	[RequireComponent(typeof(PhotonView))]
	public class AnimationRecordingStudio : Photon.MonoBehaviour
	{
		public enum State
		{
			IDLE,
			NEEDS_CALIBRATION,
			CALIBRATION_READY,
			CALIBRATION_SUCCESS,
			CALIBRATION_FAILURE,
			RECORDING_READY,
			RECORDING,
			RECORDING_SUCCESS,
			RECORDING_FAILURE
		}

		[SerializeField]
		private float maxAnimationDuration = 4f;

		[SerializeField]
		private AnimationCurve armScaleCurve;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_StateChangeEvent;

		private SynchronizedField<string> _currentAnimationName;

		private SynchronizedStateMachine stateMachine;

		private SynchronizedTimer timer;

		private bool automatePosition = true;

		private bool automateRotation = true;

		private const float CALIBRATION_SUCCESS_DURATION = 2f;

		private const float CALIBRATION_FAILURE_DURATION = 2f;

		private const float RECORDING_READY_DURATION = 3f;

		private const float RECORDING_SUCCESS_DURATION = 2f;

		private const float RECORDING_FAILURE_DURATION = 2f;

		public string StatusMessage { get; private set; }

		public string CurrentAnimationName
		{
			get
			{
				return _currentAnimationName.Get();
			}
			private set
			{
				_currentAnimationName.Set(value);
			}
		}

		public bool HasCalibrationData => PlayerAnimationRecording.HasCalibrationData;

		public bool NeedsCalibration
		{
			get
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				return currentStateId == State.NEEDS_CALIBRATION;
			}
		}

		public bool IsCalibrating
		{
			get
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				return currentStateId == State.CALIBRATION_READY || currentStateId == State.CALIBRATION_FAILURE || currentStateId == State.CALIBRATION_SUCCESS;
			}
		}

		public bool IsRecording
		{
			get
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				return currentStateId == State.RECORDING || currentStateId == State.RECORDING_READY || currentStateId == State.RECORDING_SUCCESS || currentStateId == State.RECORDING_FAILURE;
			}
		}

		public event Action StateChangeEvent
		{
			add
			{
				Action action = this.m_StateChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_StateChangeEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_StateChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_StateChangeEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			timer = new SynchronizedTimer(this, "TIMER", SetterPermissionMode.MASTER);
			_currentAnimationName = new SynchronizedField<string>(this, "CAN", string.Empty, SetterPermissionMode.MASTER);
			stateMachine = new SynchronizedStateMachine("SM", SetterPermissionMode.MASTER);
			stateMachine.StateChangeEvent += OnStateMachineStateChange;
			stateMachine.AddState(0, OnEnterIdleState, null, OnUpdateIdleState);
			stateMachine.AddState(1, OnEnterNeedsCalibrationState, null, null);
			stateMachine.AddState(2, OnEnterCalibrationReadyState, null, OnUpdateCalibrationReadyState);
			stateMachine.AddState(3, OnEnterCalibrationSuccessState, null, OnUpdateCalibrationSuccessState);
			stateMachine.AddState(4, OnEnterCalibrationFailureState, null, OnUpdateCalibrationFailureState);
			stateMachine.AddState(5, OnEnterRecordingReadyState, null, OnUpdateRecordingReadyState);
			stateMachine.AddState(6, OnEnterRecordingState, OnExitRecordingState, OnUpdateRecordingState);
			stateMachine.AddState(7, OnEnterRecordingSuccessState, null, OnUpdateRecordingSuccessState);
			stateMachine.AddState(8, OnEnterRecordingFailureState, null, OnUpdateRecordingFailureState);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			RestoreLocalPlayerMovement();
			stateMachine.StateChangeEvent -= OnStateMachineStateChange;
			PlayerAnimationRecording.ClearCalibrationData();
			PlayerAnimationRecording.ClearStaticRecordedAnimationData();
		}

		private void Update()
		{
			stateMachine.Update();
		}

		public void StartCalibration()
		{
			if (base.hasAuthority)
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				if ((currentStateId == State.NEEDS_CALIBRATION || currentStateId == State.IDLE) && LocalPlayerCanRecord())
				{
					stateMachine.EnterState(2);
				}
			}
		}

		public void StopCalibration()
		{
			if (base.hasAuthority)
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				if (currentStateId == State.CALIBRATION_READY)
				{
					stateMachine.EnterState(0);
				}
			}
		}

		public void StartRecording(string animationName, bool automatePosition, bool automateRotation)
		{
			if (base.hasAuthority && stateMachine.CurrentStateId == 0 && LocalPlayerCanRecord())
			{
				this.automatePosition = automatePosition;
				this.automateRotation = automateRotation;
				CurrentAnimationName = animationName;
				stateMachine.EnterState(5);
			}
		}

		public void StopRecording()
		{
			if (base.hasAuthority)
			{
				State currentStateId = (State)stateMachine.CurrentStateId;
				if (currentStateId == State.RECORDING)
				{
					stateMachine.EnterState(7);
				}
			}
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Record an animation!";
			RestoreLocalPlayerMovement();
		}

		private void OnUpdateIdleState()
		{
			if (base.hasAuthority && !PlayerAnimationRecording.HasCalibrationData)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterNeedsCalibrationState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Calibration Required";
			RestoreLocalPlayerMovement();
		}

		private void OnEnterCalibrationReadyState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Stand up straight in a T-pose and press the Teleport button to Calibrate!";
			RestrictLocalPlayerMovement();
		}

		private void OnUpdateCalibrationReadyState()
		{
			if (base.hasAuthority)
			{
				if (!LocalPlayerCanRecord())
				{
					stateMachine.EnterState(4);
				}
				else if (SingletonMonoBehaviour<InputManager>.Instance.LeftHandVRInputHandler.TeleportButtonDown || SingletonMonoBehaviour<InputManager>.Instance.RightHandVRInputHandler.TeleportButtonDown)
				{
					PlayerAnimationRecording.UpdateCalibrationData(Player.LocalPlayer);
					stateMachine.EnterState(3);
				}
			}
		}

		private void OnEnterCalibrationSuccessState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Calibration Success!";
			RestrictLocalPlayerMovement();
			if (base.hasAuthority)
			{
				timer.StartTimer(2f);
			}
		}

		private void OnUpdateCalibrationSuccessState()
		{
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterCalibrationFailureState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Calibration Failed!";
			RestrictLocalPlayerMovement();
			if (base.hasAuthority)
			{
				timer.StartTimer(2f);
				PlayerAnimationRecording.ClearCalibrationData();
			}
		}

		private void OnUpdateCalibrationFailureState()
		{
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterRecordingReadyState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = 3f.ToString("N0");
			if (base.hasAuthority)
			{
				timer.StartTimer(3f);
			}
			RestrictLocalPlayerMovement();
		}

		private void OnUpdateRecordingReadyState()
		{
			StatusMessage = timer.TimeRemaining.ToString("N0");
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(6);
			}
		}

		private void OnEnterRecordingState(ushort previousStateId, ushort previousSubStateId)
		{
			RestrictLocalPlayerMovement();
			if (base.hasAuthority && Player.LocalPlayer != null)
			{
				timer.StartTimer(maxAnimationDuration);
				PlayerAnimationRecording.StartRecording(Player.LocalPlayer, CurrentAnimationName, automatePosition, automateRotation, armScaleCurve);
			}
		}

		private void OnUpdateRecordingState()
		{
			StatusMessage = string.Format("Recording {0}.  Press Teleport/Jump button to finish.", timer.TimeElapsed.ToString("N2"));
			if (base.hasAuthority)
			{
				if (!LocalPlayerCanRecord())
				{
					stateMachine.EnterState(8);
				}
				else if (SingletonMonoBehaviour<InputManager>.Instance.LeftHandVRInputHandler.TeleportButtonDown || SingletonMonoBehaviour<InputManager>.Instance.RightHandVRInputHandler.TeleportButtonDown || timer.TimerOver)
				{
					stateMachine.EnterState(7);
				}
			}
		}

		private void OnExitRecordingState(ushort nextStateId, ushort nextSubStaeId)
		{
			PlayerAnimationRecording.StopRecording();
		}

		private void OnEnterRecordingSuccessState(ushort previousStateId, ushort previousSubStateId)
		{
			if (PlayerAnimationRecording.StaticLatestRecordings.Count > 0)
			{
				StatusMessage = $"Recording Success!  Saved {PlayerAnimationRecording.StaticLatestRecordings[PlayerAnimationRecording.StaticLatestRecordings.Count - 1].Name}";
			}
			else
			{
				StatusMessage = "Error saving animation asset.";
			}
			RestrictLocalPlayerMovement();
			if (base.hasAuthority)
			{
				timer.StartTimer(2f);
			}
		}

		private void OnUpdateRecordingSuccessState()
		{
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterRecordingFailureState(ushort previousStateId, ushort previousSubStateId)
		{
			StatusMessage = "Recording Failed!";
			RestrictLocalPlayerMovement();
			if (base.hasAuthority)
			{
				PlayerAnimationRecording.DeleteLastAnimation();
				timer.StartTimer(2f);
			}
		}

		private void OnUpdateRecordingFailureState()
		{
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(0);
			}
		}

		private void RestrictLocalPlayerMovement()
		{
			if (Player.LocalPlayer != null)
			{
				Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			}
		}

		private void RestoreLocalPlayerMovement()
		{
			if (Player.LocalPlayer != null)
			{
				Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			}
		}

		private void OnStateMachineStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (this.StateChangeEvent != null)
			{
				this.StateChangeEvent();
			}
		}

		private bool LocalPlayerCanRecord()
		{
			if (Player.LocalPlayer == null)
			{
				return false;
			}
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode != LocalPlayerController.DisplayMode.VR)
			{
				return false;
			}
			return true;
		}
	}
	public class AnimationRecordingStudioMenu : UnityEngine.MonoBehaviour
	{
		[Header("Prefab References")]
		[SerializeField]
		private AGVirtualKeyboard keyboardPrefab;

		[SerializeField]
		private float keyboardForwardOffset = 0.3f;

		[SerializeField]
		private float keyboardVerticalOffset = -0.5f;

		[SerializeField]
		private float keyboardPitch = 20f;

		[Header("Main Control Panel")]
		[SerializeField]
		private GameObject mainControlPanelRoot;

		[SerializeField]
		private Text mainControlPanelLabel;

		[SerializeField]
		private Button3D mainControlPanelCalibrateButton;

		[SerializeField]
		private Button3D mainControlPanelRecordNewAnimationButton;

		[SerializeField]
		private Button3D mainControlPanelRecordAnotherTakeButton;

		[Header("Naming Control Panel")]
		[SerializeField]
		private GameObject namingControlPanelRoot;

		[SerializeField]
		private InputField3D namingInputField;

		[Header("Calibration Control Panel")]
		[SerializeField]
		private GameObject calibrationControlPanelRoot;

		[SerializeField]
		private UnityEngine.UI.Image calibrationSuccessStatusImage;

		[SerializeField]
		private UnityEngine.UI.Image calibrationFailureStatusImage;

		[SerializeField]
		private Text calibrationHeadValue;

		[SerializeField]
		private Text calibrationShoulderValue;

		[SerializeField]
		private Text calibrationArmsValue;

		[SerializeField]
		private Button3D recalibrationButton;

		[Header("Recording Control Panel")]
		[SerializeField]
		private GameObject recordingControlPanelRoot;

		[SerializeField]
		private ToggleButton3D automatePositionButton;

		[SerializeField]
		private ToggleButton3D automateRotationButton;

		[SerializeField]
		private ToggleButton3D visualizeAimButton;

		private AnimationRecordingStudio recordingStudio;

		private AGVirtualKeyboard keyboard;

		private ISchedulerPromise nameNewAnimationPromise;

		private string latestAnimationName = string.Empty;

		private bool automatePosition = true;

		private bool automateRotation = true;

		private bool visualizeAim;

		private void Awake()
		{
			recordingStudio = UnityEngine.Object.FindObjectOfType<AnimationRecordingStudio>();
			recordingStudio.StateChangeEvent += OnRecordingStateChange;
			keyboard = UnityEngine.Object.Instantiate(keyboardPrefab, Vector3.zero, Quaternion.identity);
			keyboard.ForceHideKeyboard(immediate: true);
		}

		private void Start()
		{
			if (UIInputModule.Instance != null)
			{
				GetComponentInChildren<Canvas>().worldCamera = UIInputModule.Instance.ControllerCamera;
			}
			automatePositionButton.IsOn = automatePosition;
			automateRotationButton.IsOn = automateRotation;
			visualizeAimButton.IsOn = visualizeAim;
			OnRecordingStateChange();
		}

		private void OnDestroy()
		{
			recordingStudio.StateChangeEvent -= OnRecordingStateChange;
		}

		private void Update()
		{
			mainControlPanelLabel.text = recordingStudio.StatusMessage;
		}

		private void OnRecordingStateChange()
		{
			UpdateNamingPanel();
			UpdateMainPanel();
			UpdateRecordingPanel();
			UpdateCalibrationPanel();
		}

		private void UpdateNamingPanel()
		{
			bool active = IsNameNewAnimationCoroutineRunning();
			namingControlPanelRoot.SetActive(active);
		}

		private void UpdateMainPanel()
		{
			bool flag = !IsNameNewAnimationCoroutineRunning();
			mainControlPanelRoot.SetActive(flag);
			if (flag)
			{
				bool needsCalibration = recordingStudio.NeedsCalibration;
				mainControlPanelCalibrateButton.gameObject.SetActive(needsCalibration);
				bool flag2 = !recordingStudio.IsCalibrating && !recordingStudio.IsRecording && !needsCalibration;
				bool flag3 = !string.IsNullOrEmpty(latestAnimationName);
				mainControlPanelRecordNewAnimationButton.gameObject.SetActive(flag2);
				mainControlPanelRecordAnotherTakeButton.gameObject.SetActive(flag2 && flag3);
			}
		}

		private void UpdateRecordingPanel()
		{
			bool flag = IsNameNewAnimationCoroutineRunning();
			bool active = !recordingStudio.IsCalibrating && !recordingStudio.IsRecording && !recordingStudio.NeedsCalibration && !flag;
			recordingControlPanelRoot.SetActive(active);
		}

		private void UpdateCalibrationPanel()
		{
			bool flag = IsNameNewAnimationCoroutineRunning();
			bool flag2 = !recordingStudio.IsCalibrating && !recordingStudio.IsRecording && !flag;
			calibrationControlPanelRoot.SetActive(flag2);
			if (flag2)
			{
				bool needsCalibration = recordingStudio.NeedsCalibration;
				calibrationSuccessStatusImage.gameObject.SetActive(!needsCalibration);
				calibrationFailureStatusImage.gameObject.SetActive(needsCalibration);
				recalibrationButton.Interactable = !needsCalibration;
				float num = 0f;
				float num2 = 0f;
				float num3 = 0f;
				if (PlayerAnimationRecording.CalibrationData != null)
				{
					num = PlayerAnimationRecording.CalibrationData.HeadHeight;
					num2 = PlayerAnimationRecording.CalibrationData.ShoulderOffset;
					num3 = PlayerAnimationRecording.CalibrationData.ArmLength;
				}
				string format = "{0} m";
				calibrationHeadValue.text = string.Format(format, num.ToString("N1"));
				calibrationShoulderValue.text = string.Format(format, num2.ToString("N1"));
				calibrationArmsValue.text = string.Format(format, num3.ToString("N1"));
			}
		}

		private void StartNameNewAnimationCoroutine()
		{
			if (!IsNameNewAnimationCoroutineRunning())
			{
				nameNewAnimationPromise = SingletonMonoBehaviour<Scheduler>.Instance.Run(NameNewAnimationCoroutine());
				nameNewAnimationPromise.Finally(Button_RecordAnotherTake);
			}
		}

		private bool IsNameNewAnimationCoroutineRunning()
		{
			return nameNewAnimationPromise != null && !nameNewAnimationPromise.IsCompleted;
		}

		private IEnumerator<ISchedule> NameNewAnimationCoroutine()
		{
			Player localPlayer = Player.LocalPlayer;
			localPlayer.PlayerLocomotion.AddMovementRestriction(this);
			Vector3 localPlayerPosition = Player.LocalPlayer.Head.RigidbodyEx.targetPosition;
			Vector3 localPlayerForward = Player.LocalPlayer.Head.RigidbodyEx.TargetTransform.forward;
			Vector3 forwardPlanar = Vector3.ProjectOnPlane(localPlayerForward, Vector3.up).normalized;
			Vector3 keyboardPosition = localPlayerPosition + forwardPlanar * keyboardForwardOffset + Vector3.up * keyboardVerticalOffset;
			Vector3 forwardPitched = Quaternion.AngleAxis(axis: Vector3.Cross(Vector3.up, forwardPlanar), angle: keyboardPitch) * forwardPlanar;
			Quaternion keyboardRotation = Quaternion.LookRotation(forwardPitched);
			keyboard.ShowKeyboard(this, keyboardPosition, keyboardRotation);
			keyboard.KeysEnabled = true;
			yield return Schedule.NextFrame;
			OnRecordingStateChange();
			namingInputField.Text = null;
			namingInputField.SelectInputField();
			while (KeyboardInputField.FocusedInputField != null || string.IsNullOrEmpty(namingInputField.Text))
			{
				yield return Schedule.NextFrame;
			}
			latestAnimationName = namingInputField.Text;
			keyboard.HideKeyboard(this);
			localPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}

		[SkipRename]
		public void Button_StartCalibration()
		{
			recordingStudio.StartCalibration();
		}

		[SkipRename]
		public void Button_RecordNewAnimation()
		{
			StartNameNewAnimationCoroutine();
		}

		[SkipRename]
		public void Button_RecordAnotherTake()
		{
			recordingStudio.StartRecording(latestAnimationName, automatePosition, automateRotation);
		}

		[SkipRename]
		public void Toggle_AutomatePositionsValueChange(bool value)
		{
			automatePosition = value;
		}

		[SkipRename]
		public void Toggle_AutomateRotationValueChange(bool value)
		{
			automateRotation = value;
		}

		[SkipRename]
		public void Toggle_VisualizeAimValueChange(bool value)
		{
			visualizeAim = value;
		}
	}
}
namespace RecRoom.Core
{
	public class PlayerAnimationPreviewPuppet : PlayerPuppet
	{
		private PlayerAnimationPuppetSource animationPuppetSource = new PlayerAnimationPuppetSource();

		public PlayerAnimationAsset ActiveAnimation
		{
			get
			{
				return animationPuppetSource.ActiveAnimation;
			}
			set
			{
				animationPuppetSource.ActiveAnimation = value;
			}
		}

		public Player SourcePlayer
		{
			get
			{
				return animationPuppetSource.SourcePlayer;
			}
			set
			{
				if (value != animationPuppetSource.SourcePlayer)
				{
					if (animationPuppetSource.SourcePlayer != null)
					{
						CleanupPreviousPlayer();
					}
					animationPuppetSource.SourcePlayer = value;
					if (animationPuppetSource.SourcePlayer != null)
					{
						SetupNewPlayer();
					}
				}
			}
		}

		protected override IPlayerPuppetSource Source => animationPuppetSource;

