namespace RecRoom
{
	public class PlayerAnimationPuppetMenu : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private PlayerAnimationAsset defaultAnimation;

		[SerializeField]
		private Button3D decrementButton;

		[SerializeField]
		private Button3D incrementButton;

		[SerializeField]
		private Text label;

		private PlayerAnimationPreviewPuppet previewPuppet;

		private int _latestAnimationIndex;

		private int LatestAnimationIndex
		{
			get
			{
				return _latestAnimationIndex;
			}
			set
			{
				_latestAnimationIndex = value;
				if (_latestAnimationIndex <= 0)
				{
					_latestAnimationIndex = 0;
					decrementButton.Interactable = false;
				}
				else
				{
					decrementButton.Interactable = true;
				}
				if (_latestAnimationIndex >= PlayerAnimationRecording.StaticLatestRecordings.Count - 1)
				{
					_latestAnimationIndex = PlayerAnimationRecording.StaticLatestRecordings.Count - 1;
					incrementButton.Interactable = false;
				}
				else
				{
					incrementButton.Interactable = true;
				}
			}
		}

		private void Awake()
		{
			PlayerAnimationRecording.AnimationRecordedEvent += OnNewAnimationRecorded;
			previewPuppet = UnityEngine.Object.FindObjectOfType<PlayerAnimationPreviewPuppet>();
			if (Player.LocalPlayerExists)
			{
				OnLocalPlayerCreated();
			}
			else
			{
				Player.LocalPlayerCreatedEvent += new Action(OnLocalPlayerCreated);
			}
		}

		private void Start()
		{
			if (UIInputModule.Instance != null)
			{
				GetComponentInChildren<Canvas>().worldCamera = UIInputModule.Instance.ControllerCamera;
			}
			OnNewAnimationRecorded();
		}

		private void OnDestroy()
		{
			PlayerAnimationRecording.AnimationRecordedEvent -= OnNewAnimationRecorded;
			Player.LocalPlayerCreatedEvent -= new Action(OnLocalPlayerCreated);
		}

		private void Update()
		{
			if (previewPuppet != null)
			{
				if (PlayerAnimationRecording.StaticLatestRecordings.Count > 0)
				{
					PlayerAnimationRecording.AnimationRecordingData animationRecordingData = PlayerAnimationRecording.StaticLatestRecordings[LatestAnimationIndex];
					previewPuppet.ActiveAnimation = animationRecordingData.AnimationAsset;
					label.text = animationRecordingData.Name;
				}
				else
				{
					previewPuppet.ActiveAnimation = defaultAnimation;
					label.text = string.Empty;
				}
			}
		}

		private void OnNewAnimationRecorded()
		{
			LatestAnimationIndex = PlayerAnimationRecording.StaticLatestRecordings.Count - 1;
		}

		private void OnLocalPlayerCreated()
		{
			SingletonMonoBehaviour<Scheduler>.Instance.Run(SetupLocalPlayerCoroutine());
		}

		private IEnumerator<ISchedule> SetupLocalPlayerCoroutine()
		{
			yield return Schedule.NextFrame;
			if (previewPuppet != null)
			{
				previewPuppet.SourcePlayer = Player.LocalPlayer;
			}
		}

		[SkipRename]
		public void Button_AnimationIndexIncrement()
		{
			LatestAnimationIndex++;
		}

		[SkipRename]
		public void Button_AnimationIndexDecrement()
		{
			LatestAnimationIndex--;
		}
	}
}
namespace RecRoom.Core
{
	public class PlayerAnimationPuppetSource : IPlayerPuppetSource
	{
		public PlayerAnimationAsset ActiveAnimation;

		public Player SourcePlayer;

		private PlayerAnimationSystem animationSystem = new PlayerAnimationSystem();

		private List<PlayerAnimationEvent.AnimationEventType> animationEvents = new List<PlayerAnimationEvent.AnimationEventType>();

		private PlayerAnimationFrame latestFrame;

		public bool ShouldDisplay => SourcePlayer != null;

		public Color SkinColor => SourcePlayer.PlayerOutfit.SkinColor.color;

		public Color HairColor => SourcePlayer.PlayerOutfit.HairColor.color;

		public IList<OutfitSelectionToBody> OutfitSelections => SourcePlayer.PlayerOutfit.OutfitSelections;

		public AvatarFaceSettings FaceFeatures => SourcePlayer.PlayerOutfit.FaceFeatures;

		public float AudioVolume => SourcePlayer.AudioMaxForFrame;

		public PuppetTransform Head => new PuppetTransform
		{
			localPosition = latestFrame.Head.Position,
			localRotation = latestFrame.Head.Rotation
		};

		public PuppetTransform Body => new PuppetTransform
		{
			localPosition = latestFrame.Body.Position,
			localRotation = latestFrame.Body.Rotation
		};

		public PuppetHandState LeftHand => new PuppetHandState
		{
			transform = new PuppetTransform
			{
				localPosition = latestFrame.LeftHand.Position,
				localRotation = latestFrame.LeftHand.Rotation
			},
			isMenuHandVisible = false,
			thumbsUpActive = false,
			openClosedAxis = latestFrame.LeftHandTrigger
		};

		public PuppetHandState RightHand => new PuppetHandState
		{
			transform = new PuppetTransform
			{
				localPosition = latestFrame.RightHand.Position,
				localRotation = latestFrame.RightHand.Rotation
			},
			isMenuHandVisible = false,
			thumbsUpActive = false,
			openClosedAxis = latestFrame.RightHandTrigger
		};

		public void UpdateAnimation(float deltaTime)
		{
			animationSystem.CrossFade(ActiveAnimation, 0.2f, loops: true, 0.2f);
			animationSystem.OnUpdate(ApplyAnimationFrame, deltaTime, animationEvents, out var _, out var _);
		}

		private void ApplyAnimationFrame(PlayerAnimationFrame frame, float rootMotionDisplacement)
		{
			latestFrame = frame;
		}
	}
}
namespace RecRoom.Activities.Arena
{
	[RequireComponent(typeof(PhotonView))]
	[RequireComponent(typeof(ArenaEncounterSpawner))]
	public class ArenaBase : Photon.MonoBehaviour
	{
		private enum State
		{
			INACTIVE,
			CONTESTED,
			CAPTURING,
			RUNNING
		}

		private enum OverlappingPlayerType
		{
			NONE,
			ON_SINGLE_TEAM,
			ON_MULTIPLE_TEAMS
		}

		[SerializeField]
		private string baseName;

		[Header("Timing")]
		[SerializeField]
		private float onActivateInitialWaveDelay = 5f;

		[SerializeField]
		private float waveDuration = 60f;

		[Header("Encounters")]
		[SerializeField]
		private EncounterDescriptor blueTeamEncounterPrefab;

		[SerializeField]
		private EncounterDescriptor redTeamEncounterPrefab;

		[Header("Team")]
		[SerializeField]
		private bool canChangeTeam;

		[SerializeField]
		private GameTeam defaultTeam;

		[Header("Capture")]
		[SerializeField]
		private Transform captureCenter;

		[SerializeField]
		private float captureRadius = 5f;

		[SerializeField]
		private float captureDuration = 10f;

		[SerializeField]
		private float returnToOwningTeamDuration = 10f;

		[Header("Portal Doors")]
		[SerializeField]
		private LockableDoor blueTeamPortal;

		[SerializeField]
		private LockableDoor redTeamPortal;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private ArenaEncounterSpawner encounterSpawner;

		private GameManager arenaManager;

		private ArenaBaseVisuals visuals;

		private SynchronizedStateMachine stateMachine;

		private SynchronizedTimer masterTimer;

		private SynchronizedField<GameTeam> _owningTeam;

		private SynchronizedField<GameTeam> _capturingTeam;

		private SynchronizedField<float> _captureAmount;

		private GameTeam OwningTeam
		{
			get
			{
				return _owningTeam.Get();
			}
			set
			{
				_owningTeam.Set(value);
			}
		}

		private GameTeam CapturingTeam
		{
			get
			{
				return _capturingTeam.Get();
			}
			set
			{
				_capturingTeam.Set(value);
			}
		}

		private float CaptureAmount
		{
			get
			{
				return _captureAmount.Get();
			}
			set
			{
				_captureAmount.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			visuals = GetComponentInChildren<ArenaBaseVisuals>(includeInactive: true);
			if (visuals != null)
			{
				visuals.SetBaseName(baseName);
			}
			_owningTeam = new SynchronizedField<GameTeam>(this, "OT", defaultTeam, SetterPermissionMode.MASTER, OnTeamChange);
			_capturingTeam = new SynchronizedField<GameTeam>(this, "CT", GameTeam.ANY, SetterPermissionMode.MASTER);
			_captureAmount = new SynchronizedField<float>(this, "CA", 0f, SetterPermissionMode.MASTER);
			masterTimer = new SynchronizedTimer(this, "TIMER", SetterPermissionMode.MASTER);
			stateMachine = new SynchronizedStateMachine("SM", SetterPermissionMode.MASTER);
			stateMachine.AddState(0, OnEnterInactiveState, null, null);
			stateMachine.AddState(1, null, null, OnUpdateContestedState);
			stateMachine.AddState(2, OnEnterCapturingState, OnExitCapturingState, OnUpdateCapturingState);
			stateMachine.AddState(3, OnEnterRunningState, OnExitRunningState, OnUpdateRunningState);
		}

		private void Update()
		{
			stateMachine.Update();
			masterTimer.UpdateCallbacks();
		}

		public void Initialize(ArenaManager arenaManager)
		{
			this.arenaManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (redTeamPortal != null)
			{
				redTeamPortal.IsLocked = true;
			}
			if (blueTeamPortal != null)
			{
				blueTeamPortal.IsLocked = true;
			}
			stateMachine.Start(this, 0);
		}

		public void MasterActivate()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (canChangeTeam)
				{
					OwningTeam = defaultTeam;
				}
				stateMachine.EnterState(3);
			}
		}

		public void MasterDeactivate()
		{
			if (PhotonNetwork.isMasterClient)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterInactiveState(ushort previousStateId, ushort previousSubStateId)
		{
			if (visuals != null)
			{
				visuals.SetInactive();
			}
			if (PhotonNetwork.isMasterClient)
			{
				encounterSpawner.MasterDestroyAllActiveEncounters();
			}
		}

		private void OnUpdateContestedState()
		{
			if (visuals != null)
			{
				visuals.SetContested(GetTeamColor(CapturingTeam), GetTeamColor(OwningTeam), CaptureAmount, captureRadius);
			}
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			GameTeam overlappingPlayerTeam;
			OverlappingPlayerType overlappingPlayerType = GetOverlappingPlayerType(CapturingTeam, out overlappingPlayerTeam);
			if (overlappingPlayerType != OverlappingPlayerType.ON_MULTIPLE_TEAMS && overlappingPlayerType == OverlappingPlayerType.ON_SINGLE_TEAM)
			{
				if (overlappingPlayerTeam != CapturingTeam)
				{
					CaptureAmount = 0f;
				}
				CapturingTeam = overlappingPlayerTeam;
				stateMachine.EnterState(2);
			}
		}

		private void OnEnterCapturingState(ushort previousStateId, ushort previousSubStateId)
		{
			string titleText = GetTeamName(CapturingTeam) + " CAPTURING BASE " + baseName;
			string subtitleText = null;
			GameTeam playerTeam = arenaManager.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			if (previousStateId == 3 && playerTeam == OwningTeam)
			{
				subtitleText = "PORTAL AND ELITE BOTS OFFLINE";
			}
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, subtitleText, 5f);
			if (PhotonNetwork.isMasterClient)
			{
				masterTimer.StartTimer(CalculateCaptureDuration());
			}
		}

		private void OnUpdateCapturingState()
		{
			if (visuals != null)
			{
				visuals.SetCapturing(GetTeamColor(CapturingTeam), GetTeamColor(OwningTeam), CalculateCaptureAmount(), captureRadius);
			}
			if (PhotonNetwork.isMasterClient)
			{
				GameTeam overlappingPlayerTeam;
				OverlappingPlayerType overlappingPlayerType = GetOverlappingPlayerType(CapturingTeam, out overlappingPlayerTeam);
				if (overlappingPlayerType != OverlappingPlayerType.ON_SINGLE_TEAM || overlappingPlayerTeam != CapturingTeam)
				{
					stateMachine.EnterState(1);
				}
				else if (masterTimer.TimerOver)
				{
					OwningTeam = CapturingTeam;
					stateMachine.EnterState(3);
				}
			}
		}

		private void OnExitCapturingState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId == 3)
			{
				string titleText = GetTeamName(OwningTeam) + " CAPTURED BASE " + baseName;
				string subtitleText = null;
				GameTeam playerTeam = arenaManager.TeamManager.GetPlayerTeam(PhotonNetwork.player);
				if (playerTeam == OwningTeam)
				{
					subtitleText = "PORTAL AND ELITE BOTS ONLINE";
				}
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, titleText, subtitleText, 5f);
			}
			if (PhotonNetwork.isMasterClient)
			{
				CaptureAmount = CalculateCaptureAmount();
			}
		}

		private void OnEnterRunningState(ushort previousStateId, ushort previousSubStateId)
		{
			if (visuals != null)
			{
				visuals.SetOwned(GetTeamName(OwningTeam), GetTeamColor(OwningTeam), captureRadius);
			}
			if (blueTeamPortal != null)
			{
				blueTeamPortal.IsLocked = OwningTeam != GameTeam.TEAM_1;
			}
			if (redTeamPortal != null)
			{
				redTeamPortal.IsLocked = OwningTeam != GameTeam.TEAM_2;
			}
			if (PhotonNetwork.isMasterClient)
			{
				if (canChangeTeam)
				{
					CaptureAmount = 0f;
				}
				if (OwningTeam != GameTeam.ANY)
				{
					masterTimer.StartTimer(onActivateInitialWaveDelay);
				}
			}
		}

		private void OnUpdateRunningState()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			if (canChangeTeam)
			{
				GameTeam overlappingPlayerTeam;
				switch (GetOverlappingPlayerType(OwningTeam, out overlappingPlayerTeam))
				{
				case OverlappingPlayerType.ON_MULTIPLE_TEAMS:
					stateMachine.EnterState(1);
					return;
				case OverlappingPlayerType.ON_SINGLE_TEAM:
					if (overlappingPlayerTeam != OwningTeam)
					{
						CapturingTeam = overlappingPlayerTeam;
						stateMachine.EnterState(2);
						return;
					}
					break;
				}
			}
			if (masterTimer.TimerOver && OwningTeam != GameTeam.ANY)
			{
				EncounterDescriptor encounterDescriptor = ((OwningTeam != GameTeam.TEAM_1) ? redTeamEncounterPrefab : blueTeamEncounterPrefab);
				encounterSpawner.MasterSpawnEncounter(encounterDescriptor, OwningTeam);
				masterTimer.StartTimer(waveDuration);
			}
		}

		private void OnExitRunningState(ushort nextStateId, ushort nextSubStateId)
		{
			if (blueTeamPortal != null)
			{
				blueTeamPortal.IsLocked = true;
			}
			if (redTeamPortal != null)
			{
				redTeamPortal.IsLocked = true;
			}
		}

		private float CalculateCaptureDuration()
		{
			float a = ((CapturingTeam != OwningTeam) ? captureDuration : returnToOwningTeamDuration);
			return Mathf.Lerp(a, 0f, CaptureAmount);
		}

		private float CalculateCaptureAmount()
		{
			float a = ((CapturingTeam != OwningTeam) ? captureDuration : returnToOwningTeamDuration);
			return Mathf.InverseLerp(a, 0f, masterTimer.TimeRemaining);
		}

		private void OnTeamChange()
		{
		}

		private OverlappingPlayerType GetOverlappingPlayerType(GameTeam owningTeam, out GameTeam overlappingPlayerTeam)
		{
			OverlappingPlayerType overlappingPlayerType = OverlappingPlayerType.NONE;
			overlappingPlayerTeam = GameTeam.ANY;
			if (arenaManager != null)
			{
				IEnumerable<PhotonPlayer> activePlayers = arenaManager.TeamManager.GetActivePlayers();
				foreach (PhotonPlayer item in activePlayers)
				{
					if (OverlappingPlayer(item))
					{
						GameTeam playerTeam = arenaManager.TeamManager.GetPlayerTeam(item);
						if (overlappingPlayerType == OverlappingPlayerType.NONE)
						{
							overlappingPlayerTeam = playerTeam;
							overlappingPlayerType = OverlappingPlayerType.ON_SINGLE_TEAM;
						}
						else if (overlappingPlayerTeam != playerTeam)
						{
							overlappingPlayerTeam = GameTeam.ANY;
							overlappingPlayerType = OverlappingPlayerType.ON_MULTIPLE_TEAMS;
							break;
						}
					}
				}
			}
			return overlappingPlayerType;
		}

		private bool OverlappingPlayer(PhotonPlayer player)
		{
			if (!arenaManager.CombatManager.PlayerIsAlive(player))
			{
				return false;
			}
			Player player2 = player.ToPlayer();
			if (player2 == null || captureCenter == null)
			{
				return false;
			}
			return (player2.CurrentFloorPosition - captureCenter.position).sqrMagnitude <= captureRadius * captureRadius;
		}

		private Color GetTeamColor(GameTeam team)
		{
			if (team == GameTeam.ANY)
			{
				return Color.white;
			}
			return NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(team);
		}

		private string GetTeamName(GameTeam team)
		{
			if (team == GameTeam.ANY)
			{
				return "NEUTRAL";
			}
			return GameTeamSettings.GetTeamName(team).ToUpper() + " TEAM";
		}

		private void OnDrawGizmos()
		{
			if (captureCenter != null)
			{
				Gizmos.color = Color.white;
				Gizmos.DrawWireSphere(captureCenter.position, captureRadius);
			}
		}
	}
}
public class ArenaBaseVisuals : UnityEngine.MonoBehaviour
{
	[Header("Label")]
	[SerializeField]
	private TextMesh labelText;

	[SerializeField]
	private Renderer labelRenderer;

	[Header("Wall Label")]
	[SerializeField]
	private Renderer[] wallLabelRenderers;

	[SerializeField]
	private TextMesh[] wallLabelTexts;

	[Header("Chevron")]
	[SerializeField]
	private Renderer[] chevron;

	[Header("Glow Ring")]
	[SerializeField]
	private Transform glowRingRoot;

	[SerializeField]
	private Renderer glowRingRenderer;

	[SerializeField]
	private Renderer glowRingBaseRenderer;

	[Header("Slider")]
	[SerializeField]
	private Transform sliderForeground;

	[SerializeField]
	private Renderer sliderForegroundRenderer;

	[SerializeField]
	private Transform sliderBackground;

	[SerializeField]
	private Renderer sliderBackgroundRenderer;

	private static readonly Color DEFAULT_COLOR = new Color(0.6f, 0.6f, 0.6f, 1f);

	private int textColorId = Shader.PropertyToID("_Color");

	private int chevronColorId = Shader.PropertyToID("_Color");

	private int ringColorId = Shader.PropertyToID("_Color");

	private int sliderColorId = Shader.PropertyToID("_TintColor");

	public void SetInactive()
	{
		DisableLabel();
		DisableRing();
		DisableSlider();
		SetWallLabelColor(DEFAULT_COLOR);
	}

	public void SetBaseName(string baseName)
	{
		if (wallLabelTexts != null)
		{
			for (int i = 0; i < wallLabelTexts.Length; i++)
			{
				wallLabelTexts[i].text = baseName;
			}
		}
	}

	public void SetContested(Color capturingTeamColor, Color owningTeamColor, float captureAmount, float ringRadius)
	{
		SetLabel("CONTESTED", DEFAULT_COLOR);
		SetRing(DEFAULT_COLOR, ringRadius);
		SetWallLabelColor(owningTeamColor);
		SetSlider(capturingTeamColor, owningTeamColor, captureAmount);
	}

	public void SetCapturing(Color capturingTeamColor, Color owningTeamColor, float captureAmount, float ringRadius)
	{
		SetLabel("CAPTURING", DEFAULT_COLOR);
		SetWallLabelColor(owningTeamColor);
		SetRing(capturingTeamColor, ringRadius);
		SetSlider(capturingTeamColor, owningTeamColor, captureAmount);
	}

	public void SetOwned(string teamName, Color teamColor, float ringRadius)
	{
		SetLabel(teamName, teamColor);
		SetWallLabelColor(teamColor);
		SetRing(teamColor, ringRadius);
		DisableSlider();
	}

	private void SetLabel(string text, Color color)
	{
		labelText.gameObject.SetActive(value: true);
		labelText.text = text;
		labelRenderer.material.SetColor(textColorId, color);
		Renderer[] array = chevron;
		foreach (Renderer renderer in array)
		{
			renderer.material.SetColor(chevronColorId, color);
		}
	}

	private void DisableLabel()
	{
		labelText.gameObject.SetActive(value: false);
	}

	private void SetSlider(Color foregroundColor, Color backgroundColor, float progressAmount)
	{
		sliderForeground.gameObject.SetActive(value: true);
		sliderForegroundRenderer.material.SetColor(sliderColorId, foregroundColor);
		sliderBackground.gameObject.SetActive(value: true);
		sliderBackgroundRenderer.material.SetColor(sliderColorId, backgroundColor);
		Vector3 localScale = sliderForeground.localScale;
		localScale.x = Mathf.Clamp01(progressAmount);
		sliderForeground.localScale = localScale;
	}

	private void DisableSlider()
	{
		sliderForeground.gameObject.SetActive(value: false);
		sliderBackground.gameObject.SetActive(value: false);
	}

	private void SetRing(Color color, float radius)
	{
		color.a = 0.4f;
		color *= 0.8f;
		glowRingRoot.gameObject.SetActive(value: true);
		Vector3 localScale = glowRingRoot.localScale;
		localScale.x = radius;
		localScale.z = radius;
		glowRingRoot.localScale = localScale;
		glowRingRenderer.material.SetColor(ringColorId, color);
		glowRingBaseRenderer.material.SetColor(chevronColorId, color);
	}

	private void DisableRing()
	{
		glowRingRoot.gameObject.SetActive(value: false);
	}

	private void SetWallLabelColor(Color color)
	{
		color.a = 0.4f;
		color *= 0.8f;
		for (int i = 0; i < wallLabelRenderers.Length; i++)
		{
			wallLabelRenderers[i].material.SetColor(textColorId, color);
		}
	}
}
namespace RecRoom.Activities.Arena
{
	public class ArenaDoor : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private TextMesh timerLabelText;

		[SerializeField]
		private bool alwaysOpenWhenUnlocked = true;

		[SerializeField]
		private RecRoomAudioClip openAudio;

		[Autofill(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		private Animator animator;

		private static readonly int ANIMATION_CLOSED_ID = Animator.StringToHash("Locked");

		private bool _isLocked;

		private bool _isOpen;

		public bool IsLocked
		{
			get
			{
				return _isLocked;
			}
			set
			{
				_isLocked = value;
				if (_isLocked)
				{
					IsOpen = false;
				}
				else if (alwaysOpenWhenUnlocked)
				{
					IsOpen = true;
				}
			}
		}

		public bool IsOpen
		{
			get
			{
				return _isOpen;
			}
			private set
			{
				bool isOpen = _isOpen;
				_isOpen = value;
				if (animator != null)
				{
					animator.SetBool(ANIMATION_CLOSED_ID, !_isOpen);
				}
				if (isOpen != _isOpen && openAudio != null && openAudio.audioClip != null)
				{
					AudioManager.Play3DSFX(openAudio, base.transform);
				}
			}
		}

		public float NextUnlockTime { get; set; }

		private void Awake()
		{
			IsOpen = GameManager.IsSandboxActive;
		}

		private void Update()
		{
			if (timerLabelText != null)
			{
				if (IsOpen)
				{
					timerLabelText.text = "DOORS OPEN!";
					return;
				}
				float f = NextUnlockTime - (float)PhotonNetwork.time;
				int num = Mathf.RoundToInt(f);
				timerLabelText.text = "DOORS OPEN IN " + num;
			}
		}
	}
	public class ArenaEMP : Photon.MonoBehaviour
	{
		public delegate void ArenaEmpAction(ArenaEMP thisEmp, PhotonPlayer player);

		private enum State
		{
			NOT_IN_EMP_SITE,
			IN_EMP_SITE,
			ATTACHED_TO_MAINFRAME,
			ARMED,
			DETONATED,
			DEFUSED
		}

		private enum AttachedToMainframeSubStates
		{
			READY_TO_ARM,
			ARMING
		}

		private enum ArmedSubState
		{
			ARMED,
			DISARMING
		}

		[Header("Arming")]
		[SerializeField]
		private float armDuration = 10f;

		[Header("Mainframe Attaching")]
		[SerializeField]
		private SimpleVolume attachmentSearchVolume;

		[SerializeField]
		private BoxCollider attachmentSnapCollider;

		[Header("Detonate")]
		[SerializeField]
		private float detonateDelay = 40f;

		[Header("Disarm")]
		[SerializeField]
		private float disarmDuration = 10f;

		[Header("Misc Button")]
		[SerializeField]
		private float buttonDischargeDuration = 4f;

		[Header("EMP Site Feedback")]
		[SerializeField]
		private RendererMaterialPair glowRenderer;

		[SerializeField]
		private Color dimColor;

		[SerializeField]
		private Color glowColor;

		[Header("Mainframe Attach Feedback")]
		[SerializeField]
		private RecRoomAudioClip onMainframeAttachAudio;

		[Header("Button Feedback")]
		[SerializeField]
		private RecRoomAudioClip buttonHoldAudio;

		[Header("Warning Feedback")]
		[SerializeField]
		private float minWarningFrequency = 2f;

		[SerializeField]
		private float maxWarningFrequency = 6f;

		[SerializeField]
		private AnimationCurve warningFrequencyCurve;

		[SerializeField]
		private RecRoomAudioClip warningBeepAudio;

		[Header("Armed Feedback")]
		[SerializeField]
		private RecRoomAudioClip onArmAudio;

		[SerializeField]
		private RecRoomAudioClip loopingArmedAudio;

		[Header("Detonation Feedback")]
		[SerializeField]
		private RecRoomAudioClip detonationAudio;

		[SerializeField]
		private float detonationParticlesDelay = 0.77f;

		[SerializeField]
		private PooledParticle detonationParticlePrefab;

		[Header("Defused Feedback")]
		[SerializeField]
		private RecRoomAudioClip defusedAudio;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		private Timer localTimer;

		private SynchronizedTimer stateTimer;

		private SynchronizedStateMachine stateMachine;

		private ToolPlayerAttractor attractor;

		private ChargePhysicalButton button;

		private SFXAudioSource loopingButtonHoldAudioSource;

		private SFXAudioSource loopingArmedAudioSource;

		private int glowColorId = Shader.PropertyToID("_EmissionColor");

		public static ArenaEmpAction ArmEvent;

		public static ArenaEmpAction DefuseEvent;

		public bool Armed => stateMachine.CurrentStateId == 3;

		public bool Detonated => stateMachine.CurrentStateId == 4;

		public bool Defused => stateMachine.CurrentStateId == 5;

		public void Initialize(ArenaManager arenaManager)
		{
		}

		protected override void Awake()
		{
			base.Awake();
			tool.AddCustomPickupCondition(CustomToolPickupCondition);
			tool.PostReleaseEvent += OnToolPostRelease;
			attractor = GetComponent<ToolPlayerAttractor>();
			button = GetComponentInChildren<ChargePhysicalButton>();
			button.ChargedEvent += OnButtonPress;
			button.DischargeDuration = buttonDischargeDuration;
			button.AddCustomChargeCondition(CustomButtonChargeCondition);
			localTimer = new Timer();
			stateTimer = new SynchronizedTimer(this, "TIMER", SetterPermissionMode.AUTHORITY);
			stateMachine = new SynchronizedStateMachine("SSM", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, OnEnterNotInEmpSiteState, null, OnUpdateNotInEmpSiteState);
			stateMachine.AddState(1, OnEnterInEmpSiteState, null, OnUpdateInEmpSiteState);
			stateMachine.AddState(2, OnEnterAttachedToMainframeSuperState, null, OnUpdateAttachedToMainframeSuperState);
			stateMachine.AddState(2, 0, OnEnterReadyToArmSubState, null, OnUpdateReadyToArmSubState);
			stateMachine.AddState(2, 1, OnEnterArmingSubState, OnExitArmingSubState, OnUpdateArmingSubState);
			stateMachine.AddState(3, OnEnterArmedSuperState, OnExitArmedSuperState, OnUpdateArmedSuperState);
			stateMachine.AddState(3, 0, OnEnterArmedSubState, null, OnUpdateArmedSubState);
			stateMachine.AddState(3, 1, OnEnterDisarmingSubState, OnExitDisarmingSubState, OnUpdateDisarmingSubState);
			stateMachine.AddState(4, OnEnterDetonatedState, null, null);
			stateMachine.AddState(5, OnEnterDefusedState, null, null);
		}

		private void Start()
		{
			tool.ToolCleanup.PauseCleanup(this);
			stateMachine.Start(this, 0);
		}

		private void OnDisable()
		{
			StopLoopingArmedAudio();
			StopLoopingButtonHoldAudio();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostReleaseEvent -= OnToolPostRelease;
			button.ChargedEvent -= OnButtonPress;
			StopLoopingArmedAudio();
			StopLoopingButtonHoldAudio();
		}

		private void Update()
		{
			stateMachine.Update();
			stateTimer.UpdateCallbacks();
			localTimer.UpdateCallbacks();
		}

		private void OnEnterNotInEmpSiteState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				bool flag = PhotonPlayerIsOnOffense(PhotonNetwork.player);
				attractor.SuppressAttractor = !flag;
			}
			button.LabelText = "TAKE TO MAINFRAME";
			button.ButtonLabelText = "ARM";
			button.Activated = false;
			SetDimGlow();
		}

		private void OnUpdateNotInEmpSiteState()
		{
			if (base.hasAuthority && ArenaEMPSite.IsInEMPSite(this))
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterInEmpSiteState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				bool flag = PhotonPlayerIsOnOffense(PhotonNetwork.player);
				attractor.SuppressAttractor = !flag;
			}
			button.LabelText = "STICK TO MAINFRAME";
			button.ButtonLabelText = "ARM";
			button.Activated = false;
			SetFullGlow();
			if (tool.IsHeldByPlayer && tool.HolderHand != null && tool.HolderHand.isLocal)
			{
				tool.HolderHand.Vibrate(500);
			}
		}

		private void OnUpdateInEmpSiteState()
		{
			if (base.hasAuthority && !ArenaEMPSite.IsInEMPSite(this))
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterAttachedToMainframeSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				attractor.SuppressAttractor = true;
			}
			tool.RigidbodyEx.AddKinematic(this);
			button.ButtonLabelText = "ARM";
			button.Activated = true;
			button.ChargeDuration = armDuration;
			AudioManager.Play3DSFX(onMainframeAttachAudio, base.transform);
			SetFullGlow();
		}

		private void OnUpdateAttachedToMainframeSuperState()
		{
			if (base.hasAuthority && tool.IsHeld)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterReadyToArmSubState(ushort previousStateId, ushort previousSubStateId)
		{
			button.LabelText = "READY TO ARM";
		}

		private void OnUpdateReadyToArmSubState()
		{
			if (button.IsPressing && button.GetSomePressingPlayer().IsLocal)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				stateMachine.EnterState(2, 1);
			}
		}

		private void OnEnterArmingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			button.LabelText = "ARMING...";
			StartLoopingButtonHoldAudio();
		}

		private void OnUpdateArmingSubState()
		{
			if (base.hasAuthority && !button.IsPressing)
			{
				stateMachine.EnterState(2, 0);
			}
		}

		private void OnExitArmingSubState(ushort nextStateId, ushort nextSubStateId)
		{
			StopLoopingButtonHoldAudio();
		}

		private void OnEnterArmedSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				attractor.SuppressAttractor = true;
			}
			button.ChargeDuration = disarmDuration;
			button.ButtonLabelText = "DISARM";
			button.Activated = true;
			tool.RigidbodyEx.AddKinematic(this);
			if (base.hasAuthority)
			{
				stateTimer.StartTimer(detonateDelay);
			}
			StartLoopingArmedAudio();
			if (ArmEvent != null)
			{
				ArmEvent(this, base.authority);
			}
		}

		private void OnUpdateArmedSuperState()
		{
			float chargeT = Mathf.InverseLerp(detonateDelay, 0f, stateTimer.TimeRemaining);
			TryPlayWarningBeepAudio(chargeT);
			UpdatePulsingGlow();
			if (base.hasAuthority && stateTimer.TimerOver)
			{
				stateMachine.EnterState(4);
			}
		}

		private void OnExitArmedSuperState(ushort nextStateId, ushort nextSubStateId)
		{
			StopLoopingArmedAudio();
		}

		private void OnEnterArmedSubState(ushort previousStateId, ushort previousSubStateId)
		{
			button.LabelText = "ARMED";
			AudioManager.Play3DSFX(onArmAudio, base.transform);
		}

		private void OnUpdateArmedSubState()
		{
			if (button.IsPressing && button.GetSomePressingPlayer().IsLocal)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				stateMachine.EnterState(3, 1);
			}
		}

		private void OnEnterDisarmingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			button.LabelText = "DISARMING...";
			StartLoopingButtonHoldAudio();
		}

		private void OnUpdateDisarmingSubState()
		{
			if (base.hasAuthority && !button.IsPressing)
			{
				stateMachine.EnterState(3, 0);
			}
		}

		private void OnExitDisarmingSubState(ushort nextStateId, ushort nextSubStateId)
		{
			StopLoopingButtonHoldAudio();
		}

		private void OnEnterDetonatedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				attractor.SuppressAttractor = true;
			}
			tool.RigidbodyEx.RemoveKinematic(this);
			button.LabelText = "BOOM!";
			button.ButtonLabelText = "BOOM";
			button.Activated = false;
			SetDimGlow();
			AudioManager.Play2DSFX(detonationAudio);
			localTimer.StartTimerWithoutMaxRunningTime();
			localTimer.AddTimeElapsedCallback(detonationParticlesDelay, PlayDetonationParticles);
		}

		private void PlayDetonationParticles()
		{
			if (detonationParticlePrefab != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(detonationParticlePrefab);
				if (pooledParticle != null)
				{
					pooledParticle.Play(base.transform.position, Quaternion.identity);
				}
			}
		}

		private void OnEnterDefusedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (attractor != null)
			{
				attractor.SuppressAttractor = true;
			}
			tool.RigidbodyEx.RemoveKinematic(this);
			button.LabelText = "DEFUSED";
			button.ButtonLabelText = "DEFUSED";
			button.Activated = false;
			SetDimGlow();
			AudioManager.Play3DSFX(defusedAudio, base.transform);
			if (DefuseEvent != null)
			{
				DefuseEvent(this, base.authority);
			}
		}

		private bool CustomToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (!(selectingPlayer != null) || !PhotonPlayerIsOnOffense(selectingPlayer.PhotonPlayer))
			{
				return false;
			}
			int result;
			switch ((State)stateMachine.CurrentStateId)
			{
			case State.ATTACHED_TO_MAINFRAME:
				result = ((stateMachine.CurrentSubStateId == 0) ? 1 : 0);
				break;
			default:
				result = 0;
				break;
			case State.NOT_IN_EMP_SITE:
			case State.IN_EMP_SITE:
				result = 1;
				break;
			}
			return (byte)result != 0;
		}

		private void OnToolPostRelease(Tool tool)
		{
			if (base.hasAuthority && stateMachine.CurrentStateId == 1 && TryFindOverlappingMainframe(out var closestPoint, out var closestRotation))
			{
				base.transform.position = closestPoint;
				base.transform.rotation = closestRotation;
				stateMachine.EnterState(2, 0);
			}
		}

		private bool TryFindOverlappingMainframe(out Vector3 closestPoint, out Quaternion closestRotation)
		{
			closestPoint = base.transform.position;
			closestRotation = base.transform.rotation;
			Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
			int num = Physics.OverlapBoxNonAlloc(attachmentSearchVolume.WorldSpaceCenter, attachmentSearchVolume.WorldSpaceSize / 2f, iMMEDIATE_COLLIDER_HITS, attachmentSearchVolume.transform.rotation);
			for (int i = 0; i < num; i++)
			{
				ArenaMainframe component = iMMEDIATE_COLLIDER_HITS[i].gameObject.GetComponent<ArenaMainframe>();
				if (component == null)
				{
					continue;
				}
				closestPoint = Physics.ClosestPoint(base.transform.position, iMMEDIATE_COLLIDER_HITS[i], iMMEDIATE_COLLIDER_HITS[i].transform.position, iMMEDIATE_COLLIDER_HITS[i].transform.rotation);
				if (closestPoint == base.transform.position)
				{
					if (Physics.ComputePenetration(attachmentSnapCollider, attachmentSnapCollider.transform.position, attachmentSnapCollider.transform.rotation, iMMEDIATE_COLLIDER_HITS[i], iMMEDIATE_COLLIDER_HITS[i].transform.position, iMMEDIATE_COLLIDER_HITS[i].transform.rotation, out var direction, out var distance))
					{
						closestPoint += direction * distance;
						closestRotation = Quaternion.LookRotation(direction, base.transform.up);
					}
				}
				else
				{
					Vector3 normalized = (base.transform.position - closestPoint).normalized;
					closestRotation = Quaternion.LookRotation(normalized, base.transform.up);
				}
				return true;
			}
			return false;
		}

		private void OnButtonPress(ChargePhysicalButton button)
		{
			if (base.hasAuthority)
			{
				switch ((State)stateMachine.CurrentStateId)
				{
				case State.ATTACHED_TO_MAINFRAME:
					stateMachine.EnterState(3, 0);
					break;
				case State.ARMED:
					stateMachine.EnterState(5);
					break;
				}
			}
		}

		private bool CustomButtonChargeCondition(ChargePhysicalButton button, PhotonPlayer chargingPlayer, PlayerHand chargingPlayerHand)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null)
			{
				return true;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(chargingPlayer))
			{
				return false;
			}
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(chargingPlayer))
			{
				return false;
			}
			return true;
		}

		private void UpdatePulsingGlow()
		{
			float t = UnityEngine.Time.time % 1f;
			float f = Mathf.Lerp(0f, (float)Math.PI * 2f, t);
			float t2 = Mathf.Sin(f);
			SetGlowColor(Color.Lerp(dimColor, glowColor, t2));
		}

		private void SetDimGlow()
		{
			SetGlowColor(dimColor);
		}

		private void SetFullGlow()
		{
			SetGlowColor(glowColor);
		}

		private void SetGlowColor(Color color)
		{
			glowRenderer.Material.SetColor(glowColorId, color);
		}

		private void StartLoopingButtonHoldAudio()
		{
			StopLoopingButtonHoldAudio();
			loopingButtonHoldAudioSource = AudioManager.StartLooping3DSFX(buttonHoldAudio, base.transform);
		}

		private void StopLoopingButtonHoldAudio()
		{
			if (loopingButtonHoldAudioSource != null)
			{
				AudioManager.StopLoopingSFX(loopingButtonHoldAudioSource);
				loopingButtonHoldAudioSource = null;
			}
		}

		private void StartLoopingArmedAudio()
		{
			StopLoopingButtonHoldAudio();
			loopingArmedAudioSource = AudioManager.StartLooping3DSFX(loopingArmedAudio, base.transform);
		}

		private void StopLoopingArmedAudio()
		{
			if (loopingArmedAudioSource != null)
			{
				AudioManager.StopLoopingSFX(loopingArmedAudioSource);
				loopingArmedAudioSource = null;
			}
		}

		private void TryPlayWarningBeepAudio(float chargeT)
		{
			if (localTimer.TimerOver)
			{
				if (warningBeepAudio != null && warningBeepAudio.audioClip != null)
				{
					AudioManager.Play3DSFX(warningBeepAudio, base.transform);
				}
				float t = warningFrequencyCurve.Evaluate(chargeT);
				float num = Mathf.Lerp(minWarningFrequency, maxWarningFrequency, t);
				float maxRunningTime = 1f / num;
				localTimer.StartTimer(maxRunningTime);
			}
		}

		private bool PhotonPlayerIsOnOffense(PhotonPlayer player)
		{
			throw new Exception("Unsupported");
		}
	}
	[RequireComponent(typeof(SimpleVolume))]
	public class ArenaEMPSite : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private SimpleVolume volume;

		private static List<ArenaEMPSite> allEmpSites = new List<ArenaEMPSite>();

		private void Awake()
		{
			allEmpSites.Add(this);
		}

		private void OnDestroy()
		{
			allEmpSites.Remove(this);
		}

		public static bool IsInEMPSite(ArenaEMP emp)
		{
			for (int i = 0; i < allEmpSites.Count; i++)
			{
				if (allEmpSites[i].volume.ContainsPoint(emp.transform.position))
				{
					return true;
				}
			}
			return false;
		}
	}
	[RequireComponent(typeof(PhotonView))]
	public class ArenaEncounterSpawner : Photon.MonoBehaviour
	{
		[Header("Team Warzone Mode Encounters")]
		[SerializeField]
		private int maxTeamEncountersRunning = 2;

		[SerializeField]
		private float encounterSpawnPeriod = 20f;

		[SerializeField]
		private GameEncounter initialEncounterPrefab;

		[SerializeField]
		private GameEncounter[] encounterPrefabs;

		private List<GameEncounter> activeEncounters = new List<GameEncounter>();

		private List<GameEncounter> encounterScratchSpace = new List<GameEncounter>();

		public int MaxTeamEncountersRunning => maxTeamEncountersRunning;

		public float EncounterSpawnPeriod => encounterSpawnPeriod;

		public GameEncounter InitialEncounterPrefab => initialEncounterPrefab;

		public GameEncounter[] EncounterPrefabs => encounterPrefabs;

		public int RunningEncounterCount => activeEncounters.Count;

		public int GetRunningEncounterCountByTeam(GameTeam encounterTeam)
		{
			int num = 0;
			for (int i = 0; i < activeEncounters.Count; i++)
			{
				if (activeEncounters[i].Team == encounterTeam)
				{
					num++;
				}
			}
			return num;
		}

		protected override void Awake()
		{
			base.Awake();
			GameEncounter.GameEncounterInstantiatedEvent += OnGameEncounterInstantiated;
			GameEncounter.GameEncounterDestroyedEvent += OnGameEncounterDestroyed;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			GameEncounter.GameEncounterInstantiatedEvent -= OnGameEncounterInstantiated;
			GameEncounter.GameEncounterDestroyedEvent -= OnGameEncounterDestroyed;
		}

		public GameEncounter MasterSpawnEncounter(GameEncounter encounterPrefab, Transform encounterSpawnPoint, GameTeam team, EnemyPatrol overridePatrol = null)
		{
			GameEncounter result = null;
			if (PhotonNetwork.isMasterClient)
			{
				string encounterPrefabName = ((!(encounterPrefab != null)) ? null : encounterPrefab.name);
				Vector3 position = ((!(encounterSpawnPoint != null)) ? Vector3.zero : encounterSpawnPoint.position);
				Quaternion rotation = ((!(encounterSpawnPoint != null)) ? Quaternion.identity : encounterSpawnPoint.rotation);
				result = GameEncounter.MasterInstantiate(encounterPrefabName, automaticallyActivate: true, position, rotation, team, overridePatrol, base.photonView, null);
			}
			return result;
		}

		public GameEncounter MasterSpawnEncounter(EncounterDescriptor encounterDescriptor, GameTeam team)
		{
			return MasterSpawnEncounter(encounterDescriptor.EncounterPrefab, encounterDescriptor.EncounterSpawnPoint, team, encounterDescriptor.OverridePatrol);
		}

		public void MasterDestroyAllActiveEncounters()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			encounterScratchSpace.Clear();
			encounterScratchSpace.AddRange(activeEncounters);
			for (int i = 0; i < encounterScratchSpace.Count; i++)
			{
				if (encounterScratchSpace[i] != null)
				{
					encounterScratchSpace[i].MasterDeactivate();
				}
			}
		}

		private void OnGameEncounterInstantiated(GameEncounter instantiatedEncounter)
		{
			if (EncounterBelongsToThisSpawner(instantiatedEncounter))
			{
				activeEncounters.Add(instantiatedEncounter);
			}
		}

		private void OnGameEncounterDestroyed(GameEncounter encounter)
		{
			if (EncounterBelongsToThisSpawner(encounter))
			{
				activeEncounters.Remove(encounter);
			}
		}

		private bool EncounterBelongsToThisSpawner(GameEncounter encounter)
		{
			return encounter.InstantiatorPhotonViewId == base.photonView.viewID;
		}
	}
