	[RequireComponent(typeof(PhotonView))]
	public class ArenaEquipmentSpawner : Photon.MonoBehaviour
	{
		[SerializeField]
		private Transform equipmentSpawnTransform;

		[Header("Spawn Configuration")]
		[SerializeField]
		private SpawnableToolType equipmentType;

		[SerializeField]
		private float[] spawnDelays;

		[Header("Feedback")]
		[SerializeField]
		private PulsingBeam pulsingBeam;

		[SerializeField]
		private RecRoomAudioClip spawnIn10SecondsAudio;

		[SerializeField]
		private string spawnIn10SecondsNotification = "POWER WEAPON SPAWNS IN 10";

		[SerializeField]
		private RecRoomAudioClip onSpawnAudio;

		[SerializeField]
		private string onSpawnNotification = "POWER WEAPON SPAWNED";

		[SerializeField]
		private bool playNotificationOnEquipmentPickup = true;

		[SerializeField]
		private string equipmentPickupNotification = "{0} GRABBED POWER WEAPON";

		[Header("UI")]
		[SerializeField]
		private GameObject uiRoot;

		[SerializeField]
		private Renderer[] uiRenderers;

		[SerializeField]
		private TextMesh spawnTimerText;

		private SynchronizedTimer spawnTimer;

		private const float UI_CULL_DISTANCE = 2f;

		private const float UI_CULL_DISTANCE_SQR = 4f;

		private const float DEFAULT_SPAWN_DELAY = 120f;

		private bool _enabled;

		private SynchronizedField<int> _latestEquipmentToolPhotonViewId;

		private Tool _cachedLatestEquipmentTool;

		private SynchronizedField<int> _spawnDelayIndex;

		public bool Enabled
		{
			get
			{
				return _enabled;
			}
			set
			{
				bool flag = _enabled;
				_enabled = value;
				if (!_enabled)
				{
					spawnTimer.ClearCallbacks();
					if (PhotonNetwork.isMasterClient && LatestEquipmentTool != null)
					{
						LatestEquipmentTool.MasterResetToLastSpawnPosition();
					}
				}
				if (_enabled && !flag && PhotonNetwork.isMasterClient)
				{
					SpawnDelayIndex = 0;
					spawnTimer.StartTimer(SpawnDelay);
				}
			}
		}

		private Tool LatestEquipmentTool
		{
			get
			{
				return _cachedLatestEquipmentTool;
			}
			set
			{
				_latestEquipmentToolPhotonViewId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private int SpawnDelayIndex
		{
			get
			{
				return _spawnDelayIndex.Get();
			}
			set
			{
				_spawnDelayIndex.Set(value);
			}
		}

		private float SpawnDelay
		{
			get
			{
				if (spawnDelays == null || spawnDelays.Length == 0)
				{
					return 120f;
				}
				int num = Mathf.Clamp(SpawnDelayIndex, 0, spawnDelays.Length - 1);
				return spawnDelays[num];
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (pulsingBeam != null)
			{
				pulsingBeam.gameObject.SetActive(value: false);
			}
			_latestEquipmentToolPhotonViewId = new SynchronizedField<int>(this, "LFCID", -1, SetterPermissionMode.MASTER, OnLatestEquipmentPhotonViewIdChange);
			_spawnDelayIndex = new SynchronizedField<int>(this, "SDI", 0, SetterPermissionMode.MASTER);
			spawnTimer = new SynchronizedTimer(this, "ST", SetterPermissionMode.MASTER);
			spawnTimer.StartTimerEvent += OnTimerChange;
			Tool.StaticToolInstantiatedEvent += OnToolInstantiated;
		}

		private void Start()
		{
			OnLatestEquipmentPhotonViewIdChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent -= OnLocalPlayerTeamChange;
			}
			if (spawnTimer != null)
			{
				spawnTimer.StartTimerEvent -= OnTimerChange;
			}
			Tool.StaticToolInstantiatedEvent -= OnToolInstantiated;
		}

		private void Update()
		{
			spawnTimer.UpdateCallbacks();
			UpdateUI();
			if (Enabled && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && PhotonNetwork.isMasterClient && LatestEquipmentTool == null && spawnTimer.TimerOver)
			{
				MasterSpawnEquipment();
			}
		}

		private void UpdateUI()
		{
			if (!Enabled || LatestEquipmentTool != null || LocalPlayerIsInUICullRegion())
			{
				uiRoot.SetActive(value: false);
				return;
			}
			uiRoot.SetActive(value: true);
			spawnTimerText.text = spawnTimer.TimeRemaining.ToTimeString();
		}

		private bool LocalPlayerIsInUICullRegion()
		{
			if (!Player.LocalPlayerExists)
			{
				return false;
			}
			return Vector3.ProjectOnPlane(Player.LocalPlayer.Head.transform.position - base.transform.position, Vector3.up).sqrMagnitude <= 4f;
		}

		public void Initialize(ArenaManager arenaManager)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent += OnLocalPlayerTeamChange;
				OnLocalPlayerTeamChange();
			}
		}

		private void OnLocalPlayerTeamChange()
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			Color teamColor = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam);
			for (int i = 0; i < uiRenderers.Length; i++)
			{
				uiRenderers[i].material.color = teamColor;
			}
		}

		private void MasterSpawnEquipment()
		{
			if (Enabled && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && PhotonNetwork.isMasterClient)
			{
				LatestEquipmentTool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(equipmentType, equipmentSpawnTransform.position, equipmentSpawnTransform.rotation, 1f);
				base.photonView.RpcAll(RpcOnEquipmentSpawn);
			}
		}

		[PunRPC]
		private void RpcOnEquipmentSpawn()
		{
			PlaySpawnFeedback();
		}

		private void OnTimerChange()
		{
			spawnTimer.AddTimeRemainingCallback(10f, PlaySpawnIn10SecondsFeedback);
		}

		private void PlaySpawnIn10SecondsFeedback()
		{
			AudioManager.Play2DSFX(spawnIn10SecondsAudio);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, spawnIn10SecondsNotification, 3f);
		}

		private void PlaySpawnFeedback()
		{
			AudioManager.Play2DSFX(onSpawnAudio);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, onSpawnNotification, 3f);
		}

		private void OnToolInstantiated(Tool thisTool)
		{
			if (thisTool != null && thisTool.photonView.viewID == _latestEquipmentToolPhotonViewId.Get())
			{
				OnLatestEquipmentPhotonViewIdChange();
			}
		}

		private void OnLatestEquipmentPhotonViewIdChange()
		{
			PhotonView photonView = PhotonView.Find(_latestEquipmentToolPhotonViewId.Get());
			Tool tool = ((!(photonView != null)) ? null : photonView.GetComponent<Tool>());
			if (!(tool != _cachedLatestEquipmentTool))
			{
				return;
			}
			_cachedLatestEquipmentTool = tool;
			if (_cachedLatestEquipmentTool != null)
			{
				_cachedLatestEquipmentTool.ToolCleanup.PauseCleanup(this);
				_cachedLatestEquipmentTool.KinematicOnReset = true;
				_cachedLatestEquipmentTool.PostPickupEvent += OnLatestEquipmentPickup;
				_cachedLatestEquipmentTool.PostResetEvent += OnLatestEquipmentReset;
				if (pulsingBeam != null)
				{
					pulsingBeam.gameObject.SetActive(value: true);
				}
			}
			else if (pulsingBeam != null)
			{
				pulsingBeam.gameObject.SetActive(value: false);
			}
		}

		private void OnLatestEquipmentPickup(Tool tool)
		{
			tool.PostPickupEvent -= OnLatestEquipmentPickup;
			if (playNotificationOnEquipmentPickup && tool != null && tool.IsHeldByPlayer && tool.HolderPlayer != null && !tool.HolderPlayer.PhotonPlayer.IsLocal)
			{
				string titleText = string.Format(equipmentPickupNotification, tool.HolderPlayer.PhotonPlayer.NickName);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, 3f);
			}
			if (tool == LatestEquipmentTool)
			{
				OnLatestEquipmentRemoved();
			}
		}

		private void OnLatestEquipmentReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			tool.PostResetEvent -= OnLatestEquipmentReset;
			if (tool == LatestEquipmentTool)
			{
				OnLatestEquipmentRemoved();
			}
		}

		private void OnLatestEquipmentRemoved()
		{
			LatestEquipmentTool.PostResetEvent -= OnLatestEquipmentReset;
			LatestEquipmentTool.PostPickupEvent -= OnLatestEquipmentPickup;
			LatestEquipmentTool.ToolCleanup.ResumeCleanup(this);
			if (PhotonNetwork.isMasterClient)
			{
				LatestEquipmentTool = null;
				if (Enabled)
				{
					SpawnDelayIndex++;
					spawnTimer.StartTimer(SpawnDelay);
				}
			}
		}
	}
