	[RequireComponent(typeof(OverlapVolume))]
	public class ArenaFuelCellSlot : UnityEngine.MonoBehaviour
	{
		public delegate void ArenaFuelCellSlotAction(ArenaFuelCellSlot thisSlot);

		[SerializeField]
		private GameTeam team = GameTeam.ANY;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private OverlapVolume overlapVolume;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static ArenaFuelCellSlotAction m_SlotOccupationChangeEvent;

		private float lastUpdateTime;

		private bool _enabled;

		private bool _occupied;

		private const float UPDATE_FREQUENCY = 5f;

		private const float UPDATE_PERIOD = 0.2f;

		public bool Enabled
		{
			get
			{
				return _enabled;
			}
			set
			{
				_enabled = value;
				if (!base.enabled)
				{
					Occupied = false;
				}
			}
		}

		public GameTeam Team => team;

		public bool Occupied
		{
			get
			{
				return _occupied;
			}
			private set
			{
				bool occupied = _occupied;
				_occupied = value;
				if (occupied != _occupied && ArenaFuelCellSlot.SlotOccupationChangeEvent != null)
				{
					ArenaFuelCellSlot.SlotOccupationChangeEvent(this);
				}
			}
		}

		public static event ArenaFuelCellSlotAction SlotOccupationChangeEvent
		{
			add
			{
				ArenaFuelCellSlotAction arenaFuelCellSlotAction = ArenaFuelCellSlot.m_SlotOccupationChangeEvent;
				ArenaFuelCellSlotAction arenaFuelCellSlotAction2;
				do
				{
					arenaFuelCellSlotAction2 = arenaFuelCellSlotAction;
					arenaFuelCellSlotAction = Interlocked.CompareExchange(ref ArenaFuelCellSlot.m_SlotOccupationChangeEvent, (ArenaFuelCellSlotAction)Delegate.Combine(arenaFuelCellSlotAction2, value), arenaFuelCellSlotAction);
				}
				while (arenaFuelCellSlotAction != arenaFuelCellSlotAction2);
			}
			remove
			{
				ArenaFuelCellSlotAction arenaFuelCellSlotAction = ArenaFuelCellSlot.m_SlotOccupationChangeEvent;
				ArenaFuelCellSlotAction arenaFuelCellSlotAction2;
				do
				{
					arenaFuelCellSlotAction2 = arenaFuelCellSlotAction;
					arenaFuelCellSlotAction = Interlocked.CompareExchange(ref ArenaFuelCellSlot.m_SlotOccupationChangeEvent, (ArenaFuelCellSlotAction)Delegate.Remove(arenaFuelCellSlotAction2, value), arenaFuelCellSlotAction);
				}
				while (arenaFuelCellSlotAction != arenaFuelCellSlotAction2);
			}
		}

		private void Update()
		{
			if (!Enabled || !(UnityEngine.Time.time - lastUpdateTime >= 0.2f))
			{
				return;
			}
			lastUpdateTime = UnityEngine.Time.time;
			bool occupied = false;
			for (int i = 0; i < ArenaFuelCell.AllFuelCells.Count; i++)
			{
				if (ArenaFuelCell.AllFuelCells != null && overlapVolume.ContainsPoint(ArenaFuelCell.AllFuelCells[i].transform.position))
				{
					occupied = true;
					break;
				}
			}
			Occupied = occupied;
		}
	}
