		[Serializable]
		private class AwardConfig
		{
			public int BaseCredits = 50;

			public int BonusRangeStart;

			public int BonusRangeEnd;

			public int TotalPossible => BaseCredits + BonusRangeEnd;

			public int GetCredits(out int adjustedBaseAward, out int adjustedBonusAward, float timeFactor = 1f)
			{
				int num = UnityEngine.Random.Range(BonusRangeStart, BonusRangeEnd + 1);
				adjustedBaseAward = Mathf.RoundToInt((float)BaseCredits * timeFactor);
				adjustedBonusAward = Mathf.RoundToInt((float)num * timeFactor);
				return adjustedBaseAward + adjustedBonusAward;
			}
		}

