		protected override void Awake()
		{
			base.Awake();
			encounterSpawner = UnityEngine.Object.FindObjectOfType<ArenaEncounterSpawner>();
			if (encounterSpawner == null)
			{
				UnityEngine.Debug.LogError("Add an arena encounter spawner on a gameobject in the scene");
			}
			arenaVO = UnityEngine.Object.FindObjectOfType<ArenaVO>();
			if (arenaVO == null)
			{
				UnityEngine.Debug.LogError("Add an ArenaVO on a gameobject in the scene");
			}
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomWinnerNotification = PlayWinnerNotification;
			GameManager.OnGameStartEvent += OnGameStart;
			GameManager.OnGameEndEvent += OnGameEnd;
			GameManager.OnPlayerOutOfBoundsEvent += MasterOnPlayerOutOfBounds;
			GameManager.InitializeLocalPlayerEvent += InitializeLocalPlayer;
			GameManager.ResetLocalPlayerEvent += ResetLocalPlayer;
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			GetPlayerData(PhotonNetwork.player);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.hasCustomResultsSubStateDuration = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.customResultsSubStateDuration = postGameDuration;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameModeNotification = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameOverGiftGeneration = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameOverGiftDequeing = true;
			masterStateTimer = new SynchronizedTimer(this, "ARENA_TIMER", SetterPermissionMode.MASTER);
			localStateTimer = new Timer();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyDamagedPlayerEvent += OnEnemyDamagedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledPlayerEvent += OnEnemyKilledPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledEnemyEvent += OnEnemyKilledEnemy;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledEnemyEvent += OnPlayerKilledEnemy;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent += OnPlayerDamagedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent += OnPlayerRevived;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnedEquipmentInstantiatedEvent += OnEquipmentInstantiated;
			Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerSpawn);
			PointsDropper.PointsDropEvent += OnChestPointsDrop;
			Collectible.PreAllocateCollectibles(collectiblePrefab, 100);
			Collectible.PreAllocateCollectibles(SingletonMonoBehaviour<CurrencyManager>.Instance.GetCurrencyPrefab(CurrencyType.LaserTagTickets), 100);
			team1WorldSpaceNotificationPrefab.Color = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(GameTeam.TEAM_1);
			team2WorldSpaceNotificationPrefab.Color = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(GameTeam.TEAM_1);
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
			{
				OnGameStart();
			}
		}

		protected override void Start()
		{
			base.Start();
			gameStateMachine = new SynchronizedStateMachine("ARENA", SetterPermissionMode.MASTER);
			gameStateMachine.AddState(ushort.MaxValue, null, null, null);
			InitializeMusic();
			InitializeEncounters();
			InitializeEquipmentSpawners();
			InitializeEquipment();
			InitializeDoors();
			InitializeVendingMachines();
			InitializeAttritionMode();
			gameStateMachine.Start(this, ushort.MaxValue);
		}

		protected void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoinInProgress)
		{
			localPlayerHUD = UnityEngine.Object.Instantiate(hudPrefab);
			localPlayerHUD.Initialize(NetworkedSingletonMonoBehaviour<GameManager>.Instance, PhotonNetwork.player);
			if (IsCurrentModeAttrition)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
			}
		}

		protected void ResetLocalPlayer(bool localPlayerIsSpectator)
		{
			if (localPlayerHUD != null)
			{
				UnityEngine.Object.Destroy(localPlayerHUD.gameObject);
				localPlayerHUD = null;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PointsDropper.PointsDropEvent -= OnChestPointsDrop;
			Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerSpawn);
			GameManager.OnGameStartEvent -= OnGameStart;
			GameManager.OnGameEndEvent -= OnGameEnd;
			GameManager.OnPlayerOutOfBoundsEvent -= MasterOnPlayerOutOfBounds;
			GameManager.InitializeLocalPlayerEvent -= InitializeLocalPlayer;
			GameManager.ResetLocalPlayerEvent -= ResetLocalPlayer;
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnedEquipmentInstantiatedEvent -= OnEquipmentInstantiated;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyDamagedPlayerEvent -= OnEnemyDamagedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledPlayerEvent -= OnEnemyKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledEnemyEvent -= OnEnemyKilledEnemy;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledEnemyEvent -= OnPlayerKilledEnemy;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent -= OnPlayerDamagedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent -= OnPlayerRevived;
			}
		}

		protected void Update()
		{
			gameStateMachine.Update();
			localMusicStateMachine.Update();
			masterStateTimer.UpdateCallbacks();
			localStateTimer.UpdateCallbacks();
		}

		protected void OnGameStart()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = true;
			ArenaMode modeType = (ArenaMode)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType;
			if (modeType == ArenaMode.Attrition3v3 || modeType == ArenaMode.Attrition4v4)
			{
				StartAttritionMode();
			}
		}

		protected void OnGameEnd()
		{
			UpdateVendingMachineLocalPlayerCredits(0);
			if (PhotonNetwork.isMasterClient)
			{
				gameStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected int GetEloGameScore(PhotonPlayer photonPlayer)
		{
			int value = 0;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(photonPlayer, PlayerStatType.STAT_5, out value);
			return value;
		}

		public override void RecordMatchAnalytics(bool finishedGame)
		{
			int value = 0;
			int value2 = 0;
			int value3 = 0;
			bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_1, out value);
			bool flag2 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_2, out value2);
			bool flag3 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_3, out value3);
			if (flag || flag2 || flag3)
			{
				AnalyticsHelper.AddCustomStatsToActivityStats("finished_game", finishedGame.ToString());
				AnalyticsHelper.AddCustomStatsCounter("games_played", 1);
				AnalyticsHelper.AddCustomStatsCounter("player_kills", value);
				AnalyticsHelper.AddCustomStatsCounter("enemy_kills", value2);
				AnalyticsHelper.AddCustomStatsCounter("deaths", value3);
				AnalyticsHelper.AddCustomStatsToActivityStats("player_type", SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType.ToString());
			}
		}

		private void OnEquipmentInstantiated(SpawnableTool equipment)
		{
			Tool component = equipment.GetComponent<Tool>();
			if (component != null)
			{
				RangedWeapon component2 = component.GetComponent<RangedWeapon>();
				if (component2 != null)
				{
					component2.LocalPlayerFireEvent += OnLocalPlayerFireRangedWeapon;
				}
				component.DestroyEvent += OnEquipmentToolDestroyed;
			}
		}

		private void InitializeEquipment()
		{
			List<SpawnableTool> list = this.FindAllObjectsOfType<SpawnableTool>();
			for (int i = 0; i < list.Count; i++)
			{
				OnEquipmentInstantiated(list[i]);
			}
		}

		private void OnLocalPlayerFireRangedWeapon(RangedWeapon rangedWeapon)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomGameSettings.ForceDualWieldingSupport || rangedWeapon == null || rangedWeapon.Tool == null || !rangedWeapon.Tool.IsHeldByPlayer)
			{
				return;
			}
			Player holderPlayer = rangedWeapon.Tool.HolderPlayer;
			if (holderPlayer == null || !holderPlayer.isLocal)
			{
				return;
			}
			SpawnableTool component = rangedWeapon.GetComponent<SpawnableTool>();
			if (rangedWeapon == null || component == null || dualWieldAllowedWeaponTypes.Contains(component.Type))
			{
				return;
			}
			PlayerHand holderHand = rangedWeapon.Tool.HolderHand;
			PlayerHand playerHand = ((!(holderHand != null)) ? null : holderPlayer.GetOtherHand(holderHand.Type));
			Tool tool = ((!(playerHand != null) || !playerHand.IsHoldingTool) ? null : playerHand.HeldTool);
			RangedWeapon rangedWeapon2 = ((!(tool != null)) ? null : tool.GetComponent<RangedWeapon>());
			if (!(rangedWeapon2 == null) && !(rangedWeapon2 == rangedWeapon))
			{
				Weapon component2 = tool.GetComponent<Weapon>();
				SpawnableTool component3 = tool.GetComponent<SpawnableTool>();
				if (component2 != null && component3 != null && !dualWieldAllowedWeaponTypes.Contains(component3.Type))
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "CANNOT DUAL WIELD", 3f);
					holderPlayer.TryDisarm(tool);
				}
			}
		}

		private void OnEquipmentToolDestroyed(Tool tool)
		{
			RangedWeapon component = tool.GetComponent<RangedWeapon>();
			if (component != null)
			{
				component.LocalPlayerFireEvent -= OnLocalPlayerFireRangedWeapon;
			}
			tool.DestroyEvent -= OnEquipmentToolDestroyed;
		}

		private void OnEnemyDamagedPlayer(Enemy attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				OnMusicCombatEvent(defender);
				OnPlayerDamage(defenderImpactBodyPart, impactPoint, Vector3.up);
			}
		}

		private void OnEnemyKilledPlayer(Enemy attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				if (PhotonNetwork.isMasterClient)
				{
					MasterAddPoints(attacker, playerKillPoints);
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(defender, PlayerStatType.STAT_3, 1);
				}
				OnPlayerDamage(defenderImpactBodyPart, impactPoint, Vector3.up);
				if (defender.IsLocal)
				{
					OnLocalPlayerDeathByEnemy();
				}
			}
		}

		private void OnEnemyKilledEnemy(Enemy attacker, Enemy defender, Vector3 point)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && attacker.Team != defender.Team)
			{
				bool flag = defender.EnemyType == EnemyType.QUEST_SCIFI_ELITE_FLYING_RANGED || defender.EnemyType == EnemyType.QUEST_SCIFI_ELITE_GROUND_RANGED;
				if (PhotonNetwork.isMasterClient)
				{
					int points = ((!flag) ? normalEnemyKillPoints : eliteEnemyKillPoints);
					MasterAddPoints(attacker, points);
				}
			}
		}

		private void OnPlayerKilledEnemy(PhotonPlayer attacker, Weapon attackerWeapon, Enemy defender, Vector3 point)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				return;
			}
			OnMusicCombatEvent(attacker);
			bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayerOnTeam(attacker, defender.Team);
			bool flag2 = defender.EnemyType == EnemyType.QUEST_SCIFI_ELITE_FLYING_RANGED || defender.EnemyType == EnemyType.QUEST_SCIFI_ELITE_GROUND_RANGED;
			if (PhotonNetwork.isMasterClient)
			{
				if (flag)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(attacker, PlayerStatType.STAT_2, -1);
					MasterAddPoints(attacker, enemyFriendlyFirePoints);
				}
				else
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(attacker, PlayerStatType.STAT_2, 1);
					int points = ((!flag2) ? normalEnemyKillPoints : eliteEnemyKillPoints);
					MasterAddPoints(attacker, points);
				}
			}
			Vector3 position = defender.transform.position;
			if (flag)
			{
				SpawnCollectiblesLostByPlayer(attacker, Mathf.Abs(enemyFriendlyFirePoints));
			}
			else
			{
				int value = ((!flag2) ? normalEnemyKillPoints : eliteEnemyKillPoints);
				SpawnCollectiblesOnPlayerPickup(attacker, value, position);
			}
			if (!attacker.IsLocal)
			{
				return;
			}
			if (flag)
			{
				PlayWorldSpacePointsNotification(enemyFriendlyFirePoints, "TAGGED FRIENDLY BOT", position);
				return;
			}
			if (flag2)
			{
				PlayWorldSpacePointsNotification(eliteEnemyKillPoints, "TAGGED ELITE BOT", position);
			}
			else
			{
				PlayWorldSpacePointsNotification(normalEnemyKillPoints, "TAGGED BOT", position);
			}
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.ArenaBotTag(defender);
			}
		}

		private void OnPlayerDamagedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			OnMusicCombatEvent(defender);
			OnPlayerDamage(defenderImpactBodyPart, impactPoint, impactSurfaceNormal);
		}

		private void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				return;
			}
			OnMusicCombatEvent(attacker);
			bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(attacker, defender);
			if (PhotonNetwork.isMasterClient && !flag)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(defender, PlayerStatType.STAT_3, 1);
				if (flag)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(attacker, PlayerStatType.STAT_1, -1);
					MasterAddPoints(attacker, playerFriendlyFireKillPoints);
				}
				else
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(attacker, PlayerStatType.STAT_1, 1);
					MasterAddPoints(attacker, playerKillPoints);
				}
			}
			OnPlayerDamage(defenderImpactBodyPart, impactPoint, impactSurfaceNormal);
			if (!flag)
			{
				SpawnCollectiblesOnPlayerPickup(attacker, playerKillPoints, impactPoint);
			}
			if (defender.IsLocal)
			{
				OnLocalPlayerDeathByPlayer(attacker, flag);
			}
			else if (attacker.IsLocal)
			{
				bool criticalHit = defenderImpactBodyPart == Player.BodyPart.Head;
				OnLocalPlayerKilledPlayer(defender, criticalHit, flag, impactPoint);
				if (!flag && Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerEvents.ArenaHeroTag(defender);
				}
			}
			else
			{
				OnRemotePlayerKilledRemotePlayer(defender, attacker, flag);
			}
		}

		private void OnLocalPlayerKilledPlayer(PhotonPlayer deadPlayer, bool criticalHit, bool friendlyFire, Vector3 impactPoint)
		{
			if (criticalHit)
			{
				AudioManager.Play2DSFX(playerKilledPlayerCriticalHitSFX);
			}
			else
			{
				AudioManager.Play2DSFX(playerKilledPlayerSFX);
			}
			if (friendlyFire)
			{
				Vector3 position = deadPlayer.ToPlayer().Head.transform.position;
				PlayWorldSpacePointsNotification(playerFriendlyFireKillPoints, "FRIENDLY FIRE " + deadPlayer.NickName, position);
			}
			else
			{
				Vector3 position2 = deadPlayer.ToPlayer().Head.transform.position;
				PlayWorldSpacePointsNotification(playerKillPoints, "TAGGED " + deadPlayer.NickName, position2);
			}
			string titleText = "TAGGED " + deadPlayer.NickName;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, titleText, 3f);
		}

		private void OnRemotePlayerKilledRemotePlayer(PhotonPlayer defender, PhotonPlayer attacker, bool friendlyFire)
		{
			string titleText = attacker.NickName + " TAGGED " + defender.NickName;
			string subtitleText = ((!friendlyFire) ? null : "FRIENDLY FIRE");
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, titleText, subtitleText, 2f);
		}

		private void OnLocalPlayerDeathByPlayer(PhotonPlayer killer, bool friendlyFire)
		{
			string text = "TAGGED BY ";
			text = ((!killer.IsLocal) ? (text + killer.NickName) : (text + "SELF"));
			string subtitleText = ((!friendlyFire) ? null : "FRIENDLY FIRE");
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, text, subtitleText, 3f);
		}

		private void OnLocalPlayerDeathByEnemy()
		{
			string titleText = "TAGGED BY BOT";
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, 3f);
		}

		private void OnPlayerDamage(Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				Quaternion rotation = Quaternion.LookRotation(impactSurfaceNormal);
				if (defenderImpactBodyPart == Player.BodyPart.Head)
				{
					AudioManager.Play3DSFX(playerDamagedCriticalHitSFX, impactPoint);
					PooledParticle.TryPlayPrefab(playerDamagedCriticalHitParticles, impactPoint, rotation);
				}
				else
				{
					AudioManager.Play3DSFX(playerDamagedSFX, impactPoint);
					PooledParticle.TryPlayPrefab(playerDamagedParticles, impactPoint, rotation);
				}
			}
		}

		private void PlayWorldSpacePointsNotification(int points, string subtitle, Vector3 worldPosition)
		{
			string pointsString = GetPointsString(points, withUnits: false);
			worldPosition += 1.35f * Vector3.up;
			WorldSpaceNotification prefab = ((!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayerOnTeam(PhotonNetwork.player, GameTeam.TEAM_1)) ? team2WorldSpaceNotificationPrefab : team1WorldSpaceNotificationPrefab);
			WorldSpaceNotification.PlayNext(prefab, pointsString, 1.5f, subtitle, followPlayer: false, worldPosition, 1f, billboard: true);
		}

		private void OnPlayerRevived(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 position)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				return;
			}
			OnMusicCombatEvent(revivedPlayer);
			OnMusicCombatEvent(revivingPlayer);
			AudioManager.Play3DSFX(playerReviveSFX, position);
			PooledParticle.TryPlayPrefab(reviveParticles, position);
			if (revivedPlayer.IsLocal)
			{
				PlayLocalPlayerRevivedFeedback(revivingPlayer);
			}
			else if (revivingPlayer.IsLocal)
			{
				PlayLocalPlayerRevivingFeedback(revivedPlayer);
				if (Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerEvents.ArenaFriendRevive(revivedPlayer);
				}
			}
			else
			{
				PlayRemotePlayerRevivedFeedback(revivedPlayer, revivingPlayer);
			}
			if (PhotonNetwork.isMasterClient)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(revivingPlayer, PlayerStatType.STAT_4, 1);
			}
		}

		private void PlayLocalPlayerRevivedFeedback(PhotonPlayer revivingPlayer)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "REVIVED BY " + revivingPlayer.NickName + "!", 3f);
		}

		private void PlayLocalPlayerRevivingFeedback(PhotonPlayer revivedPlayer)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "YOU REVIVED " + revivedPlayer.NickName + "!", 3f);
		}

		private void PlayRemotePlayerRevivedFeedback(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer)
		{
