		private void MasterSetAllTeamsCredits(int credits)
		{
			GameTeam[] allTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAllTeams();
			for (int i = 0; i < allTeams.Length; i++)
			{
				GetTeamData(allTeams[i]).Credits = credits;
			}
		}

		private void MasterAddAllTeamsCredits(int creditDelta)
		{
			GameTeam[] allTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAllTeams();
			for (int i = 0; i < allTeams.Length; i++)
			{
				GetTeamData(allTeams[i]).Credits += creditDelta;
			}
