		private int GetPlayerCredits(PhotonPlayer player)
		{
			if (teamsShareCredits)
			{
				return GetTeamData(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player)).Credits;
			}
			return GetPlayerData(player).Credits;
		}

		private void MasterAddPlayerCredits(PhotonPlayer player, int deltaCredits)
		{
			if (player != null)
			{
				if (teamsShareCredits)
				{
					GetTeamData(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player)).Credits += deltaCredits;
				}
				else
				{
					GetPlayerData(player).Credits += deltaCredits;
				}
			}
		}

		private void MasterAddPoints(PhotonPlayer player, int points)
		{
			if (!PhotonNetwork.isMasterClient || !NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				return;
			}
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player);
			if (playerTeam != GameTeam.ANY)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(player, PlayerStatType.STAT_5, points, canGoNegative: false);
				if (IsCurrentModeAttrition)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(playerTeam, points, NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin);
				}
			}
		}

		private void MasterAddPoints(Enemy enemy, int points)
		{
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && enemy != null && enemy.Team != GameTeam.ANY && IsCurrentModeAttrition)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(enemy.Team, points, NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin);
			}
		}

		private string GetPointsString(int creditValue, bool withUnits = true)
		{
			int num = Mathf.Abs(creditValue);
			string text = ((creditValue >= 0) ? "+" : "-");
			string text2 = ((!withUnits) ? string.Empty : " POINTS");
			return text + num + text2;
		}

		private void PlayPointsNotification(int points)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, GetPointsString(points), 2f);
		}

		private void OnChestPointsDrop(PointsDropper thisDropper, Vector3 position, PhotonPlayer[] rewardedPlayers, int minValue, int maxValue, PointDropType dropType, bool dontAddToCombatScore)
		{
			if (rewardedPlayers != null && rewardedPlayers.Length > 0 && rewardedPlayers[0] != null && thisDropper.GetComponent<BreakablePointsContainer>() != null)
			{
				PhotonPlayer photonPlayer = rewardedPlayers[0];
				if (PhotonNetwork.isMasterClient && !dontAddToCombatScore)
				{
					MasterAddPoints(photonPlayer, lootChestPoints);
				}
				SpawnCollectiblesOnPlayerPickup(photonPlayer, lootChestPoints, position);
				if (photonPlayer.IsLocal)
				{
					PlayWorldSpacePointsNotification(lootChestPoints, string.Empty, position);
				}
			}
		}

		private void SpawnCollectiblesOnPlayerPickup(PhotonPlayer pickupPlayer, int value, Vector3 spawnPosition)
		{
