		{
			Collectible.SpawnCollectibleGroup(collectiblePrefab, Mathf.Abs(creditValue), individualCollectibleCreditValue, spawnPosition, pickupPosition, 0.5f);
		}

		private bool IsValidPurchase(PhotonPlayer player, int creditCost)
		{
			return NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && (player == null || (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(player) && GetPlayerCredits(player) >= creditCost));
		}

		private void InitializeVendingMachines()
		{
			ArenaVendingMachine.MasterPurchaseRequestEvent += OnMasterVendingMachinePurchaseRequest;
			vendingMachines = this.FindAllObjectsOfType<ArenaVendingMachine>();
			for (int i = 0; i < vendingMachines.Count; i++)
			{
				vendingMachines[i].Initialize(this);
				vendingMachines[i].SetLocalPlayerCredits(0);
			}
		}

		private void CleanupVendingMachines()
		{
			ArenaVendingMachine.MasterPurchaseRequestEvent -= OnMasterVendingMachinePurchaseRequest;
		}

		private void OnMasterVendingMachinePurchaseRequest(ArenaVendingMachine vendingMachine, ArenaVendingMachineSlot vendingMachineSlot, PhotonPlayer player, int creditCost)
		{
			if (PhotonNetwork.isMasterClient && IsValidPurchase(player, creditCost) && creditCost > 0)
			{
				MasterAddPlayerCredits(player, -creditCost);
				base.photonView.RpcAll(RpcOnPurchaseSuccess, player, vendingMachine, vendingMachineSlot, creditCost);
			}
		}

		[PunRPC]
		private void RpcOnPurchaseSuccess(PhotonPlayer player, ArenaVendingMachine vendingMachine, ArenaVendingMachineSlot vendingMachineSlot, int creditCost)
		{
			if (!(vendingMachine != null))
			{
				return;
			}
			if (PhotonNetwork.isMasterClient)
			{
				vendingMachine.OnMasterPurchaseSuccess(vendingMachineSlot);
			}
			if (player != null)
			{
				if (player.IsLocal)
				{
					AudioManager.Play2DSFX(lootSpentSFX);
					PlayPointsNotification(-creditCost);
				}
				SpawnCollectiblesLostByPlayer(player, creditCost, vendingMachine.CreditDispenseTransform.position);
			}
		}

		private void UpdateVendingMachineLocalPlayerCredits(int localPlayerCredits)
		{
			if (vendingMachines != null)
			{
				for (int i = 0; i < vendingMachines.Count; i++)
				{
					vendingMachines[i].SetLocalPlayerCredits(localPlayerCredits);
				}
			}
		}

		private void OnCreditsChange()
		{
			UpdateVendingMachineLocalPlayerCredits(GetPlayerCredits(PhotonNetwork.player));
		}

		protected void MasterOnPlayerOutOfBounds(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient && IsValidOutOfBoundsHit(player))
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterKillPlayer(player);
				base.photonView.RpcPlayer(player, RpcOnOutOfBoundsHitPlayer);
			}
		}

		private bool IsValidOutOfBoundsHit(PhotonPlayer hitPlayer)
		{
			return gameStateMachine.CurrentStateId != ushort.MaxValue && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(hitPlayer) && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(hitPlayer);
		}

		[PunRPC]
		private void RpcOnOutOfBoundsHitPlayer()
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "OUT!", "OUT OF BOUNDS!", 3f);
		}

		private void InitializeAttritionMode()
		{
			gameStateMachine.AddState(0, OnEnterAttritionRoundRunningState, OnExitAttritionRoundRunningState, OnUpdateAttritionRoundRunningState);
			gameStateMachine.AddState(0, 0, OnEnterAttritionLowScoreSubState, OnExitAttritionLowScoreSubState, null);
			gameStateMachine.AddState(0, 1, OnEnterAttritionHighScoreSubState, null, null);
		}

		private void StartAttritionMode()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameStart = true;
			if (PhotonNetwork.isMasterClient)
			{
				gameStateMachine.EnterState(0, 0);
			}
		}

		private void OnEnterAttritionRoundRunningState(ushort previousStateId, ushort previousSubStateId)
		{
			LockAllDoors();
			GetLatestAttritionScore(out latestWinningTeam, out latestBlueTeamScore, out latestRedTeamScore);
			if (PhotonNetwork.isMasterClient)
			{
				MasterSpawnInitialEncounter(GameTeam.TEAM_1);
				MasterSpawnInitialEncounter(GameTeam.TEAM_2);
				masterStateTimer.StartTimer(encounterSpawner.EncounterSpawnPeriod);
			}
			EnableAllEquipmentSpawners();
			localStateTimer.StartTimerWithoutMaxRunningTime();
			localStateTimer.AddTimeElapsedCallback(1f, PlayModeNotification);
			localStateTimer.AddTimeElapsedCallback(2.33f, PlayTitleAnnouncementVO);
			localStateTimer.AddTimeElapsedCallback(4f, PlayRulesNotification);
			localStateTimer.AddTimeElapsedCallback(4.66f, PlayRulesInstructionVO);
			localStateTimer.AddTimeElapsedCallback(9f, PlayTeamNotification);
			localMusicStateMachine.EnterState(1);
		}

		private void OnUpdateAttritionRoundRunningState()
		{
			UpdateAttritionTeamScoreFeedback(ref latestWinningTeam, ref latestBlueTeamScore, ref latestRedTeamScore);
			int num = Mathf.Max(latestRedTeamScore, latestBlueTeamScore);
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			if (masterStateTimer.TimerOver)
			{
				if (encounterSpawner.GetRunningEncounterCountByTeam(GameTeam.TEAM_1) < encounterSpawner.MaxTeamEncountersRunning)
				{
					MasterSpawnRandomEncounter(GameTeam.TEAM_1, 1);
				}
				if (encounterSpawner.GetRunningEncounterCountByTeam(GameTeam.TEAM_2) < encounterSpawner.MaxTeamEncountersRunning)
				{
					MasterSpawnRandomEncounter(GameTeam.TEAM_2, 1);
				}
				masterStateTimer.StartTimer(encounterSpawner.EncounterSpawnPeriod);
			}
			if (num >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
			else if (gameStateMachine.CurrentSubStateId == 0 && (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining <= gameEndingSoonTimeRemaining || num >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin - gameEndingSoonPointsRemaining))
			{
				gameStateMachine.EnterState(0, 1);
			}
		}

		private void OnExitAttritionRoundRunningState(ushort nextStateId, ushort nextSubStateId)
		{
			UnlockAllDoors();
			AudioManager.MusicMixer.PlayFanfareMusic();
			localMusicStateMachine.EnterState(0);
			DisableAllEquipmentSpawners();
			if (PhotonNetwork.isMasterClient)
			{
				encounterSpawner.MasterDestroyAllActiveEncounters();
			}
		}

		private void GetLatestAttritionScore(out GameTeam latestWinningTeam, out int latestBlueTeamScore, out int latestRedTeamScore)
		{
			latestRedTeamScore = 0;
			latestBlueTeamScore = 0;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out latestWinningTeam, out var highestScore, IncludeInactiveTeams: true))
			{
				if (latestWinningTeam == GameTeam.TEAM_1)
				{
					latestBlueTeamScore = highestScore;
					latestRedTeamScore = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetScore(GameTeam.TEAM_2);
				}
				else if (latestWinningTeam == GameTeam.TEAM_2)
				{
					latestRedTeamScore = highestScore;
					latestBlueTeamScore = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetScore(GameTeam.TEAM_1);
				}
			}
		}

		private void UpdateAttritionTeamScoreFeedback(ref GameTeam latestWinningTeam, ref int latestBlueTeamScore, ref int latestRedTeamScore)
		{
			int a = latestBlueTeamScore;
			int b = latestRedTeamScore;
			int num = Mathf.Max(a, b);
			bool flag = num >= minLeadFeedbackPoints;
			GameTeam gameTeam = latestWinningTeam;
			GetLatestAttritionScore(out latestWinningTeam, out latestBlueTeamScore, out latestRedTeamScore);
			int num2 = Mathf.Max(latestBlueTeamScore, latestRedTeamScore);
			if (num2 >= minLeadFeedbackPoints && (!flag || latestWinningTeam != gameTeam))
			{
				PlayTeamTookTheLeadFeedback(latestWinningTeam);
			}
		}

		private void OnEnterAttritionLowScoreSubState(ushort previousStateId, ushort previousSubStateId)
		{
		}

		private void OnExitAttritionLowScoreSubState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void OnEnterAttritionHighScoreSubState(ushort previousStateId, ushort previousSubStateId)
		{
			localMusicStateMachine.EnterState(3);
			GetLatestAttritionScore(out var gameTeam, out var _, out var _);
			if (gameTeam != GameTeam.ANY)
			{
				PlayTeamCloseToWinFeedback(gameTeam);
			}
		}

