			string empty = string.Empty;
			RecRoomAudioClip recRoomAudioClip = null;
			if (highestScoreTeam == GameTeam.ANY)
			{
				empty = "Tie Game";
				recRoomAudioClip = DefaultAudioSettings.ConfigAsset.GameTieVO;
			}
			else
			{
				empty = arenaVO.GetTeam(highestScoreTeam).TeamName + " Wins!";
				recRoomAudioClip = arenaVO.GetTeam(highestScoreTeam).WinVO;
			}
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, empty, 4f);
			AudioManager.Play2DSFX(recRoomAudioClip);
		}

