		private void InitializeMusic()
		{
			localMusicStateMachine = new ManualUpdateStateMachine();
			localMusicStateMachine.AddState(0, null, null, null);
			localMusicStateMachine.AddState(1, OnEnterExploreMusicState, null, OnUpdateExploreMusicState);
			localMusicStateMachine.AddState(2, OnEnterCombatMusicState, OnExitCombatMusicState, OnUpdateCombatMusicState);
			localMusicStateMachine.AddState(3, OnEnterLastLapMusicState, OnExitLastLapMusicState, null);
			localMusicStateMachine.EnterState(0);
		}

		private void OnEnterExploreMusicState(ushort previousStateId, ushort previousSubStateId)
		{
			AudioManager.MusicMixer.SetGameplayMusicFadeInTime(0f);
		}

		private void OnUpdateExploreMusicState()
		{
			if (IsInMusicCombat())
			{
				localMusicStateMachine.EnterState(2);
			}
		}

		private void OnEnterCombatMusicState(ushort previousStateId, ushort previousSubStateId)
		{
			AudioManager.MusicMixer.SetGameplayMusicFadeInTime(combatMusicFadeOutTime);
			AudioManager.MusicMixer.PlayActionMusic();
		}

		private void OnUpdateCombatMusicState()
		{
			if (!IsInMusicCombat())
			{
				localMusicStateMachine.EnterState(1);
			}
		}

		private void OnExitCombatMusicState(ushort nextStateId, ushort nextSubStateId)
		{
			AudioManager.MusicMixer.StopActionMusic();
		}

		private void OnEnterLastLapMusicState(ushort previousStateId, ushort previousSubStateId)
		{
			AudioManager.MusicMixer.AddOverrideMusic(arenaVO.teamNearingVictoryMusic, this);
			AudioManager.MusicMixer.PlayOverrideMusic();
		}

		private void OnExitLastLapMusicState(ushort nextStateId, ushort nextSubStateId)
		{
			AudioManager.MusicMixer.StopOverrideMusic();
			AudioManager.MusicMixer.RemoveOverrideMusic(this);
		}

		private void OnMusicCombatEvent(PhotonPlayer player)
		{
			if (player != null && player.IsLocal && IsLocalPlayerEligibleForMusicCombatEvent())
			{
				lastCombatEventTime = UnityEngine.Time.time;
			}
		}

		private bool IsLocalPlayerEligibleForMusicCombatEvent()
		{
			return NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(PhotonNetwork.player);
		}

		private bool IsInMusicCombat()
		{
			float num = UnityEngine.Time.time - lastCombatEventTime;
			return IsLocalPlayerEligibleForMusicCombatEvent() && num <= combatMusicMinPlayTime;
		}

		public void MasterSpawnEncounter(EncounterDescriptor encounterDescriptor, GameTeam team)
		{
			encounterSpawner.MasterSpawnEncounter(encounterDescriptor, team);
		}

		private void InitializeEncounters()
		{
			if (encounterSpawner.EncounterPrefabs == null || encounterSpawner.EncounterPrefabs.Length == 0)
			{
				UnityEngine.Debug.LogError("Missing Encounter Prefabs.");
			}
			List<ArenaEncounterSpawnPoint> list = this.FindAllObjectsOfType<ArenaEncounterSpawnPoint>();
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].Team == GameTeam.TEAM_1)
				{
					blueTeamEncounterSpawnPoints.Add(list[i]);
				}
				else if (list[i].Team == GameTeam.TEAM_2)
				{
					redTeamEncounterSpawnPoints.Add(list[i]);
				}
			}
			if (blueTeamEncounterSpawnPoints.Count == 0 || redTeamEncounterSpawnPoints.Count == 0)
			{
				UnityEngine.Debug.LogError("Missing Encounter Spawn Points");
			}
		}

		private void MasterSpawnInitialEncounter(GameTeam team)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			List<ArenaEncounterSpawnPoint> list = ((team != GameTeam.TEAM_1) ? redTeamEncounterSpawnPoints : blueTeamEncounterSpawnPoints);
			ArenaEncounterSpawnPoint arenaEncounterSpawnPoint = null;
			for (int i = 0; i < list.Count; i++)
			{
				if (list[i].IsInitialSpawnPoint)
				{
					arenaEncounterSpawnPoint = list[i];
					break;
				}
			}
			if (arenaEncounterSpawnPoint == null)
			{
				MasterSpawnRandomEncounter(team, 1);
			}
			else
			{
				encounterSpawner.MasterSpawnEncounter(encounterSpawner.InitialEncounterPrefab, arenaEncounterSpawnPoint.transform, team, arenaEncounterSpawnPoint.Patrol);
			}
		}

		private void MasterSpawnRandomEncounter(GameTeam team, int count)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			encounterSpawnScratchSpace.Clear();
			List<ArenaEncounterSpawnPoint> list = ((team != GameTeam.TEAM_1) ? redTeamEncounterSpawnPoints : blueTeamEncounterSpawnPoints);
			UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
			for (int i = 0; i < count; i++)
			{
				int num = UnityEngine.Random.Range(0, encounterSpawner.EncounterPrefabs.Length);
				GameEncounter encounterPrefab = encounterSpawner.EncounterPrefabs[num];
				int encounterSpawnPointIndex = GetEncounterSpawnPointIndex(encounterSpawnScratchSpace, list);
				if (!encounterSpawnScratchSpace.Contains(encounterSpawnPointIndex))
				{
					encounterSpawnScratchSpace.Add(encounterSpawnPointIndex);
				}
				ArenaEncounterSpawnPoint arenaEncounterSpawnPoint = list[encounterSpawnPointIndex];
				encounterSpawner.MasterSpawnEncounter(encounterPrefab, arenaEncounterSpawnPoint.transform, team, arenaEncounterSpawnPoint.Patrol);
			}
		}

		private int GetEncounterSpawnPointIndex(List<int> usedIndices, List<ArenaEncounterSpawnPoint> spawnPoints)
		{
			bool flag = usedIndices.Count == spawnPoints.Count;
			int num = UnityEngine.Random.Range(0, spawnPoints.Count);
			if (flag)
			{
				return num;
			}
			for (int i = 0; i < spawnPoints.Count; i++)
			{
				int num2 = (num + i) % spawnPoints.Count;
				if (!usedIndices.Contains(num2))
				{
					num = num2;
					break;
				}
			}
			return num;
		}

		private TeamData GetTeamData(GameTeam team)
		{
			TeamData value = null;
			if (allTeamData != null && !allTeamData.TryGetValue(team, out value))
			{
				value = new TeamData(this, team);
				value.CreditChangeEvent += OnCreditsChange;
				allTeamData[team] = value;
			}
			return value;
		}

		private PlayerData GetPlayerData(PhotonPlayer player)
		{
			PlayerData value = null;
			if (allPlayerData != null && player != null && !allPlayerData.TryGetValue(player.ID, out value))
			{
				value = new PlayerData(player);
				value.CreditChangeEvent += OnCreditsChange;
				allPlayerData[player.ID] = value;
			}
			return value;
		}

		protected void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
		{
			GetPlayerData(newPlayer);
		}
	}
