	public class ArenaVendingMachine : Photon.MonoBehaviour
	{
		public delegate void PurchaseRequest(ArenaVendingMachine vendingMachine, ArenaVendingMachineSlot vendingMachineSlot, PhotonPlayer player, int credits);

		[Header("Team")]
		[SerializeField]
		private GameTeam team = GameTeam.ANY;

		[SerializeField]
		private TextMesh teamLabel;

		[Header("Credits")]
		[SerializeField]
		private TextMesh playerCreditLabel;

		[SerializeField]
		private Transform creditDispenseTransform;

		[SerializeField]
		private float creditChangeAnimationDelay = 0.5f;

		[SerializeField]
		private float creditChangeRate = 800f;

		private ArenaVendingMachineSlot[] vendingSlots;

		private int localPlayerCredits = -1;

		private int previousLocalPlayerCredits = -1;

		private int creditAnimationLatestIntValue = -1;

		private float creditAnimationStartTime;

		private float creditAnimationEndTime;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static PurchaseRequest m_MasterPurchaseRequestEvent;

		public Transform CreditDispenseTransform => creditDispenseTransform;

		public ArenaManager ArenaManager { get; private set; }

		public static event PurchaseRequest MasterPurchaseRequestEvent
		{
			add
			{
				PurchaseRequest purchaseRequest = ArenaVendingMachine.m_MasterPurchaseRequestEvent;
				PurchaseRequest purchaseRequest2;
				do
				{
					purchaseRequest2 = purchaseRequest;
					purchaseRequest = Interlocked.CompareExchange(ref ArenaVendingMachine.m_MasterPurchaseRequestEvent, (PurchaseRequest)Delegate.Combine(purchaseRequest2, value), purchaseRequest);
				}
				while (purchaseRequest != purchaseRequest2);
			}
			remove
			{
				PurchaseRequest purchaseRequest = ArenaVendingMachine.m_MasterPurchaseRequestEvent;
				PurchaseRequest purchaseRequest2;
				do
				{
					purchaseRequest2 = purchaseRequest;
					purchaseRequest = Interlocked.CompareExchange(ref ArenaVendingMachine.m_MasterPurchaseRequestEvent, (PurchaseRequest)Delegate.Remove(purchaseRequest2, value), purchaseRequest);
				}
				while (purchaseRequest != purchaseRequest2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (teamLabel != null)
			{
				teamLabel.text = GameTeamSettings.GetTeamName(team).ToUpper() + " TEAM";
			}
			vendingSlots = GetComponentsInChildren<ArenaVendingMachineSlot>();
			for (int i = 0; i < vendingSlots.Length; i++)
			{
				vendingSlots[i].Initialize(this, team);
				vendingSlots[i].MasterPurchaseRequestEvent += OnMasterPurchaseRequest;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			for (int i = 0; i < vendingSlots.Length; i++)
			{
				vendingSlots[i].MasterPurchaseRequestEvent -= OnMasterPurchaseRequest;
			}
		}

		private void Update()
		{
			UpdateCreditAnimation();
		}

		private void OnMasterPurchaseRequest(ArenaVendingMachineSlot slot, PhotonPlayer purchasingPlayer, int creditCost)
		{
			if (PhotonNetwork.isMasterClient && ArenaVendingMachine.MasterPurchaseRequestEvent != null && creditCost > 0 && slot != null)
			{
				ArenaVendingMachine.MasterPurchaseRequestEvent(this, slot, purchasingPlayer, creditCost);
			}
		}

		private void UpdateCreditAnimation()
		{
			float t = Mathf.InverseLerp(creditAnimationStartTime, creditAnimationEndTime, UnityEngine.Time.time);
			int num = Mathf.RoundToInt(Mathf.Lerp(previousLocalPlayerCredits, localPlayerCredits, t));
			if (num != creditAnimationLatestIntValue)
			{
				creditAnimationLatestIntValue = num;
				playerCreditLabel.text = creditAnimationLatestIntValue.ToString();
			}
		}

		public void Initialize(ArenaManager arenaManager)
		{
			ArenaManager = arenaManager;
		}

		public void SetLocalPlayerCredits(int localPlayerCredits)
		{
			previousLocalPlayerCredits = this.localPlayerCredits;
			this.localPlayerCredits = localPlayerCredits;
			int num = Mathf.Abs(localPlayerCredits - previousLocalPlayerCredits);
			float num2 = (float)num / creditChangeRate;
			creditAnimationStartTime = UnityEngine.Time.time + creditChangeAnimationDelay;
			creditAnimationEndTime = creditAnimationStartTime + num2;
			for (int i = 0; i < vendingSlots.Length; i++)
			{
				vendingSlots[i].SetLocalPlayerCredits(localPlayerCredits);
			}
		}

		public void OnMasterPurchaseSuccess(ArenaVendingMachineSlot slot)
		{
			slot.OnMasterPurchaseSuccess();
		}
	}
