	public class ArenaVendingMachineEquipmentSlot : ArenaVendingMachineSlot
	{
		[SerializeField]
		private SpawnableToolType equipmentType = SpawnableToolType.ROTJ_PISTOL;

		[SerializeField]
		private Transform equipmentSpawnTransform;

		private SynchronizedField<int> _equipmentPhotonViewId;

		private float lastSpawnUpdateTime;

		private const float SPAWN_FREQUENCY = 2f;

		private const float SPAWN_PERIOD = 0.5f;

		private Tool _cachedEquipmentTool;

		private Vector3 EquipmentSpawnPosition => (!(equipmentSpawnTransform != null)) ? Vector3.zero : equipmentSpawnTransform.position;

		private Quaternion EquipmentSpawnRotation => (!(equipmentSpawnTransform != null)) ? Quaternion.identity : equipmentSpawnTransform.rotation;

		private Tool EquipmentTool
		{
			get
			{
				return _cachedEquipmentTool;
			}
			set
			{
				int newValue = ((!(value != null) || !(value.photonView != null)) ? (-1) : value.photonView.viewID);
				_equipmentPhotonViewId.Set(newValue);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_equipmentPhotonViewId = new SynchronizedField<int>(this, "EVS", -1, SetterPermissionMode.MASTER, enforceInitialValue: false, OnEquipmentPhotonViewIdChange);
			Tool.StaticToolInstantiatedEvent += OnToolInstantiated;
		}

		protected override void Start()
		{
			base.Start();
			OnEquipmentPhotonViewIdChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Tool.StaticToolInstantiatedEvent -= OnToolInstantiated;
		}

		protected override void Update()
		{
			base.Update();
			if (!(vendingMachine == null) && !(vendingMachine.ArenaManager == null) && !(NetworkedSingletonMonoBehaviour<GameManager>.Instance == null) && !(UnityEngine.Time.time - lastSpawnUpdateTime < 0.5f))
			{
				lastSpawnUpdateTime = UnityEngine.Time.time;
				if (PhotonNetwork.isMasterClient && EquipmentTool == null)
				{
					EquipmentTool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(equipmentType, EquipmentSpawnPosition, EquipmentSpawnRotation, 1f);
				}
			}
		}

		private void OnToolInstantiated(Tool thisTool)
		{
			if (thisTool != null && thisTool.photonView.viewID == _equipmentPhotonViewId.Get())
			{
				OnEquipmentPhotonViewIdChange();
			}
		}

		private void OnEquipmentPhotonViewIdChange()
		{
			int viewID = _equipmentPhotonViewId.Get();
			PhotonView photonView = PhotonView.Find(viewID);
			Tool tool = ((!(photonView != null)) ? null : photonView.GetComponent<Tool>());
			if (!(tool != _cachedEquipmentTool))
			{
				return;
			}
			_cachedEquipmentTool = tool;
			if (_cachedEquipmentTool != null)
			{
				_cachedEquipmentTool.KinematicOnReset = true;
				_cachedEquipmentTool.AddCustomPickupCondition(EquipmentPickupCondition);
				_cachedEquipmentTool.PrePickupEvent += OnEquipmentPickup;
				ToolPlayerAttractor component = _cachedEquipmentTool.GetComponent<ToolPlayerAttractor>();
				if (component != null)
				{
					component.SuppressAttractor = true;
				}
				_cachedEquipmentTool.ToolCleanup.PauseCleanup(this);
			}
		}

		private void OnEquipmentPickup(Tool tool)
		{
			if (PhotonNetwork.isMasterClient && tool == _cachedEquipmentTool)
			{
				_cachedEquipmentTool = null;
			}
			tool.PrePickupEvent -= OnEquipmentPickup;
			tool.RemoveCustomPickupCondition(EquipmentPickupCondition);
			ToolPlayerAttractor component = tool.GetComponent<ToolPlayerAttractor>();
			if (component != null)
			{
				component.SuppressAttractor = false;
			}
			tool.ToolCleanup.ResumeCleanup(this);
			if (PhotonNetwork.isMasterClient)
			{
				RaiseMasterPurchaseRequestEvent(tool.HolderPlayer.PhotonPlayer);
			}
		}

		private bool EquipmentPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return selectingPlayer.PhotonPlayer.IsLocal && localPlayerCanAfford;
		}
	}
