namespace RecRoom.Tools.Weapons
{
	public class FlipOpenWeaponSights : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		[SerializeField]
		private Transform leftHandFrontSight;

		[SerializeField]
		private Transform leftHandBackSight;

		[SerializeField]
		private Vector3 closedLeftHandRotation;

		[SerializeField]
		private Vector3 openLeftHandRotation;

		[SerializeField]
		private Transform rightHandFrontSight;

		[SerializeField]
		private Transform rightHandBackSight;

		[SerializeField]
		private Vector3 closedRightHandRotation;

		[SerializeField]
		private Vector3 openRightHandRotation;

		[SerializeField]
		private float timeToUpdate = 0.5f;

		private Coroutine updateSightCoroutine;

		private void Awake()
		{
			if (tool != null)
			{
				tool.PostPickupEvent += OnToolPickup;
				tool.PostReleaseEvent += OnToolRelease;
				OnToolHolderChange(tool);
			}
		}

		private void OnDestroy()
		{
			if (tool != null)
			{
				tool.PostPickupEvent -= OnToolPickup;
				tool.PostReleaseEvent -= OnToolRelease;
			}
		}

		private void OnToolPickup(Tool tool)
		{
			OnToolHolderChange(tool);
		}

		private void OnToolRelease(Tool tool)
		{
			OnToolHolderChange(tool, forceRelease: true);
		}

		private void OnToolHolderChange(Tool tool, bool forceRelease = false)
		{
			if (tool.HolderHand == null || forceRelease)
			{
				StartUpdateSightCoroutine(Quaternion.Euler(closedLeftHandRotation), Quaternion.Euler(closedRightHandRotation));
			}
			else if (tool.HolderHand.Type == PlayerHand.HandType.Left)
			{
				StartUpdateSightCoroutine(Quaternion.Euler(openLeftHandRotation), Quaternion.Euler(closedRightHandRotation));
			}
			else
			{
				StartUpdateSightCoroutine(Quaternion.Euler(closedLeftHandRotation), Quaternion.Euler(openRightHandRotation));
			}
		}

		private IEnumerator UpdateSightCoroutine(Quaternion leftTargetLocalRotation, Quaternion rightTargetLocalRotation)
		{
			Quaternion initialLocalLeftOrientation = leftHandFrontSight.localRotation;
			Quaternion initialLocalRightOrientation = rightHandFrontSight.localRotation;
			float startTime = UnityEngine.Time.time;
			float endTime = startTime + timeToUpdate;
			while (UnityEngine.Time.time < endTime)
			{
				float t = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
				SetLeftHandRotation(Quaternion.Slerp(initialLocalLeftOrientation, leftTargetLocalRotation, t));
				SetRightHandRotation(Quaternion.Slerp(initialLocalRightOrientation, rightTargetLocalRotation, t));
				yield return null;
			}
			SetLeftHandRotation(leftTargetLocalRotation);
			SetRightHandRotation(rightTargetLocalRotation);
		}

		private void StartUpdateSightCoroutine(Quaternion leftTargetOrientation, Quaternion rightTargetOrientation)
		{
			StopUpdateSightCoroutine();
			updateSightCoroutine = StartCoroutine(UpdateSightCoroutine(leftTargetOrientation, rightTargetOrientation));
		}

		private void StopUpdateSightCoroutine()
		{
			if (updateSightCoroutine != null)
			{
				StopCoroutine(updateSightCoroutine);
				updateSightCoroutine = null;
			}
		}

		private void SetLeftHandRotation(Quaternion rotation)
		{
			if (leftHandFrontSight != null)
			{
				leftHandFrontSight.localRotation = rotation;
			}
			if (leftHandBackSight != null)
			{
				leftHandBackSight.localRotation = rotation;
			}
		}

		private void SetRightHandRotation(Quaternion rotation)
		{
			if (rightHandFrontSight != null)
			{
				rightHandFrontSight.localRotation = rotation;
			}
			if (rightHandBackSight != null)
			{
				rightHandBackSight.localRotation = rotation;
			}
		}
	}
}
