					}
				}
			}
		}

		[Header("Team Color")]
		[SerializeField]
		private UnityEngine.UI.Image[] thisTeamColorElements;

		[Header("Health")]
		[SerializeField]
		private Slider healthBar;

		[Header("Shield")]
		[SerializeField]
		private Slider shieldBar;

		[Header("Down But Not Out")]
		[SerializeField]
		private Slider dbnoBar;

		[Header("Ammunition")]
		[SerializeField]
		private AmmoHUD leftHandAmmoHUD;

		[SerializeField]
		private AmmoHUD rightHandAmmoHUD;

		[Header("Score")]
		[SerializeField]
		private ScoreHUD thisTeamScoreHUD;

		[SerializeField]
		private ScoreHUD otherTeamScoreHUD;

		[Header("Timer")]
		[SerializeField]
		private Text timerText;

		[Header("Remaining Players")]
		[SerializeField]
		private RemainingPlayersHUD remainingPlayersHUD;

		[Header("HUD Scale")]
		[SerializeField]
		private Vector3 screensCanvasPivotScale = new Vector3(0.7f, 0.7f, 0.7f);

		[SerializeField]
		private Transform canvasPivot;

		private GameManager gameManager;

		private PhotonPlayer player;

		private Player playerAvatar;

		public Transform ParentTransform { get; set; }

		private void LateUpdate()
		{
			UpdatePlayerCombatStats();
			UpdateAmmo();
			UpdateTimers();
			UpdateRemainingPlayers();
			FollowCamera();
		}

		private void OnDestroy()
		{
			if (gameManager != null)
			{
				gameManager.TeamManager.TeamChangeEvent -= OnTeamChange;
				gameManager.ScoreManager.StatsChangeEvent -= OnStatsChange;
			}
		}

		public void Initialize(GameManager gameManager, PhotonPlayer player, Layers defaultCullingLayer = Layers.CameraMesh, Transform parentTransform = null)
		{
			this.player = player;
			this.gameManager = gameManager;
			UpdatePlayerCombatStats();
			UpdateAmmo();
			this.gameManager.TeamManager.TeamChangeEvent += OnTeamChange;
			UpdateTeamColors();
			this.gameManager.ScoreManager.StatsChangeEvent += OnStatsChange;
			UpdateTeamScores();
			UpdateRemainingPlayers();
			ParentTransform = parentTransform;
			if (ParentTransform != null)
			{
				base.transform.SetParent(parentTransform, worldPositionStays: false);
			}
			if (canvasPivot == null)
			{
				canvasPivot = base.transform.GetChild(0);
			}
			canvasPivot.localScale = ((player.ToPlayer().ControllerDisplayMode != LocalPlayerController.DisplayMode.SCREEN) ? Vector3.one : screensCanvasPivotScale);
			base.gameObject.SetLayerRecursively(defaultCullingLayer);
		}

		private void FollowCamera()
		{
			if (SingletonMonoBehaviour<CameraRig>.Instance != null && SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera != null && ParentTransform == null)
			{
				base.transform.position = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
				base.transform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.rotation;
			}
		}

		private void UpdateTimers()
		{
			string text = string.Empty;
			if (gameManager != null)
			{
				if (gameManager.PresenceManager.CustomTimerString != null)
				{
					text = gameManager.PresenceManager.CustomTimerString;
				}
				else if (gameManager.CurrentMode.TimerSettings.GameHasDuration)
				{
					text = gameManager.GameTimerManager.TimeRemaining.ToTimeString();
				}
			}
			if (timerText != null)
			{
				timerText.text = text;
			}
		}

		private void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			if (changingTeamPlayer == player)
			{
				UpdateTeamColors();
				UpdateTeamScores();
			}
		}

		private void UpdateTeamColors()
		{
			GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(player);
			Color teamColor = gameManager.TeamManager.GetTeamColor(playerTeam);
			if (thisTeamColorElements != null)
			{
				for (int i = 0; i < thisTeamColorElements.Length; i++)
				{
					teamColor.a = thisTeamColorElements[i].color.a;
					thisTeamColorElements[i].color = teamColor;
				}
			}
			if (thisTeamScoreHUD != null)
			{
				thisTeamScoreHUD.UpdateColor(teamColor);
			}
			if (leftHandAmmoHUD != null)
			{
				leftHandAmmoHUD.UpdateColor(teamColor);
			}
			if (rightHandAmmoHUD != null)
			{
				rightHandAmmoHUD.UpdateColor(teamColor);
			}
			if (otherTeamScoreHUD != null)
			{
				GameTeam anotherTeam = gameManager.TeamManager.GetAnotherTeam(playerTeam);
				Color teamColor2 = gameManager.TeamManager.GetTeamColor(anotherTeam);
				otherTeamScoreHUD.UpdateColor(teamColor2);
			}
		}

		private void OnStatsChange()
		{
			UpdateTeamScores();
		}

		private void UpdateTeamScores()
		{
			if (!(gameManager == null) && player != null)
			{
				GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(player);
				int scoreToWin = gameManager.ScoreManager.ScoreToWin;
				if (thisTeamScoreHUD != null)
				{
					int score = gameManager.ScoreManager.GetScore(playerTeam);
					thisTeamScoreHUD.UpdateScore(score, scoreToWin);
				}
				if (otherTeamScoreHUD != null)
				{
					GameTeam anotherTeam = gameManager.TeamManager.GetAnotherTeam(playerTeam);
					int score2 = gameManager.ScoreManager.GetScore(anotherTeam);
					otherTeamScoreHUD.UpdateScore(score2, scoreToWin);
				}
			}
		}

		private void UpdatePlayerCombatStats()
		{
			if (player != null && !(gameManager == null))
			{
				if (BattleRoyaleManager.Instance != null && BattleRoyaleManager.Instance.IsPlayerEliminated(PhotonNetwork.player))
				{
					DisableHealth();
				}
				else if (gameManager.CombatManager.IsPlayerDownButNotOut(player))
				{
					UpdatePlayerDBNO();
				}
				else
				{
					UpdatePlayerHealth();
				}
			}
		}

		private void UpdatePlayerDBNO()
		{
			if (dbnoBar != null)
			{
				float playerDownButNotOutValue = gameManager.CombatManager.GetPlayerDownButNotOutValue(player);
				float downButNotOutMaxValue = gameManager.CurrentMode.CombatSettings.DownButNotOutMaxValue;
				dbnoBar.gameObject.SetActive(value: true);
				dbnoBar.value = playerDownButNotOutValue / downButNotOutMaxValue;
			}
			if (healthBar != null)
			{
				healthBar.gameObject.SetActive(value: false);
			}
			if (shieldBar != null)
			{
				shieldBar.gameObject.SetActive(value: false);
			}
		}

		private void UpdatePlayerHealth()
		{
			if (dbnoBar != null)
			{
				dbnoBar.gameObject.SetActive(value: false);
			}
			if (healthBar != null)
			{
				int playerHealth = gameManager.CombatManager.GetPlayerHealth(player);
				int defaultHealth = gameManager.CurrentMode.CombatSettings.DefaultHealth;
				float value = (float)playerHealth / (float)defaultHealth;
				healthBar.gameObject.SetActive(value: true);
				healthBar.value = value;
			}
			if (shieldBar != null)
			{
				bool supportsPlayerShield = gameManager.CurrentMode.CombatSettings.SupportsPlayerShield;
				shieldBar.gameObject.SetActive(supportsPlayerShield);
				if (supportsPlayerShield)
				{
					int playerShield = gameManager.CombatManager.GetPlayerShield(player);
					int maximumShield = gameManager.CurrentMode.CombatSettings.MaximumShield;
					float value2 = (float)playerShield / (float)maximumShield;
					shieldBar.value = value2;
				}
			}
		}

		private void DisableHealth()
		{
			if (dbnoBar != null)
			{
				dbnoBar.gameObject.SetActive(value: false);
			}
			if (healthBar != null)
			{
				healthBar.gameObject.SetActive(value: false);
			}
			if (shieldBar != null)
			{
				shieldBar.gameObject.SetActive(value: false);
			}
		}

		private void UpdateAmmo()
		{
			if (playerAvatar == null && player != null)
			{
				playerAvatar = player.ToPlayer();
			}
			if (!(playerAvatar == null))
			{
				Weapon weapon = null;
				if (playerAvatar.LeftHand != null && playerAvatar.LeftHand.IsHoldingTool && playerAvatar.LeftHand.HeldTool != null)
				{
					weapon = playerAvatar.LeftHand.HeldTool.GetComponent<Weapon>();
				}
				leftHandAmmoHUD.UpdateAmmo(weapon);
				Weapon weapon2 = null;
				if (playerAvatar.RightHand != null && playerAvatar.RightHand.IsHoldingTool && playerAvatar.RightHand.HeldTool != null)
				{
					weapon2 = playerAvatar.RightHand.HeldTool.GetComponent<Weapon>();
				}
				rightHandAmmoHUD.UpdateAmmo(weapon2);
			}
		}

		private void UpdateRemainingPlayers()
		{
			if (remainingPlayersHUD != null && BattleRoyaleManager.Instance != null)
			{
				if (BattleRoyaleManager.Instance.IsPlayerEliminated(PhotonNetwork.player))
				{
					remainingPlayersHUD.Disable();
					return;
				}
				int numPlayersRemaining = BattleRoyaleManager.Instance.NumPlayersRemaining;
				remainingPlayersHUD.UpdatePlayerText(numPlayersRemaining);
			}
		}
	}
}
