public class ArtTestingLoadOutfitTools : UnityEngine.MonoBehaviour
{
	private SpawnedEquipmentDrawer drawer;

	private void Awake()
	{
		VerifySingleCopyOfScript();
		StartCoroutine(RunClearScene());
	}

	private IEnumerator RunClearScene()
	{
		OutfitItem[] outfits = UnityEngine.Object.FindObjectsOfType<OutfitItem>();
		OutfitItem[] array = outfits;
		foreach (OutfitItem outfitItem in array)
		{
			outfitItem.gameObject.SetActive(value: false);
			UnityEngine.Object.DestroyImmediate(outfitItem.gameObject);
		}
		while (NetworkedSingletonMonoBehaviour<OutfitManager>.Instance == null || !Player.LocalPlayerExists || !Player.LocalPlayer.IsInitialized)
		{
			yield return null;
		}
		drawer = base.gameObject.AddComponent<SpawnedEquipmentDrawer>();
		drawer.IsSelected = true;
		Vector3 startPosition = new Vector3(0f, 1.5f, 0f);
		for (int j = 0; j < NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitPrefabs.Count; j++)
		{
			OutfitItem outfit = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitPrefabs[j];
			CreateCombinations(outfit, startPosition + j * Vector3.back * 0.3f);
		}
	}

	private void CreateCombinations(OutfitItem outfit, Vector3 startPosition)
	{
		CreateOutfitTool(new OutfitSelection(outfit), startPosition);
		int num = 1;
		if (outfit.SelectionGroups == null)
		{
			return;
		}
		for (int i = 0; i < outfit.SelectionGroups.Length; i++)
		{
			OutfitItem.OutfitSelectionGroup outfitSelectionGroup = outfit.SelectionGroups[i];
			if (!outfitSelectionGroup.IsValid)
			{
				continue;
			}
			for (int j = 0; j <= outfitSelectionGroup.decals.Count; j++)
			{
				for (int k = 0; k < outfitSelectionGroup.masks.Count; k++)
				{
					for (int l = 0; l < outfitSelectionGroup.swatches.Count; l++)
					{
						CreateOutfitTool(new OutfitSelection(outfit, (l >= outfitSelectionGroup.swatches.Count) ? null : outfitSelectionGroup.swatches[l], (k >= outfitSelectionGroup.masks.Count) ? null : outfitSelectionGroup.masks[k], (j >= outfitSelectionGroup.decals.Count) ? null : outfitSelectionGroup.decals[j]), startPosition + num * Vector3.left * ((outfit.Type != OutfitManager.OutfitType.Shirt) ? 0.25f : 0.5f));
						num++;
					}
				}
			}
		}
	}

	private void CreateOutfitTool(OutfitSelection selection, Vector3 position)
	{
		OutfitTool outfitTool = OutfitTool.LocalFind(selection, PlayerSpawnedEquipment.Purpose.Drawer);
		if (outfitTool == null)
		{
			OutfitTool outfitTool2 = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitToolForLocalPlayer(selection, PlayerSpawnedEquipment.Purpose.Drawer, null);
			if (outfitTool2 != null)
			{
				drawer.AddTool(outfitTool2.Tool);
			}
		}
	}

	private void VerifySingleCopyOfScript()
	{
		ArtTestingLoadOutfitTools[] array = UnityEngine.Object.FindObjectsOfType<ArtTestingLoadOutfitTools>();
		if (array.Length > 1)
		{
			UnityEngine.Debug.LogError("Found two ArtTestingLoadOutfitTools in scene. This will break expected behavior.");
			ArtTestingLoadOutfitTools[] array2 = array;
			foreach (ArtTestingLoadOutfitTools artTestingLoadOutfitTools in array2)
			{
				UnityEngine.Debug.LogError("ArtTestingLoadOutfitTools on gameObject:" + artTestingLoadOutfitTools.gameObject, artTestingLoadOutfitTools.gameObject);
			}
		}
	}
}
namespace RecRoom.Activities.Bowling
{
	public class BowlingBall : Ball
	{
		public float AngularVelocityThrowMultiplier;

		public float LerpFrictionSpeed;

		public float InertiaMultiplier = 1.5f;

		public float YUpVelocityScalar = 0.5f;

		public float MaxDepenetrationVelocity = 1f;

		[SerializeField]
		private AnimationCurve rumbleVolumeBySpeedSquared;

		[SerializeField]
		private RecRoomAudioClip rumble;

		private SFXAudioSource rumbleSFX;

		[Header("Thrower collision ignoring")]
		[SerializeField]
		private float reEnableBodyCollisionDelay = 0.5f;

		private Player throwerPlayer;

		private float floorFriction;

		private bool colliding;

		private SphereCollider collider;

		private ISchedulerPromise deferredReEnableCollisionCoroutine;

		protected override void Awake()
		{
			base.Awake();
			collider = GetComponentInChildren<SphereCollider>();
			floorFriction = collider.material.dynamicFriction;
			base.Tool.RigidbodyEx.velocity *= InertiaMultiplier;
			base.Tool.RigidbodyEx.UnityRigidbody.maxDepenetrationVelocity = MaxDepenetrationVelocity;
			base.Tool.PostPickupEvent += OnToolPickup;
			base.Tool.PreReleaseEvent += OnToolRelease;
			base.Tool.AddCustomPickupCondition(CustomPickupCondition);
		}

		private bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return selectingPlayer == thisTool.Owner || !IsDeferredReEnableCoroutineRunning();
		}

		public void Start()
		{
			if (base.Tool != null)
			{
				base.Tool.PostReleaseEvent += Throw;
			}
			rumbleSFX = AudioManager.StartLooping3DSFX(rumble, base.transform);
		}

		private void Throw(Tool thisTool)
		{
			collider.material.dynamicFriction = 0f;
			base.Tool.RigidbodyEx.angularVelocity *= AngularVelocityThrowMultiplier;
			Vector3 velocity = base.Tool.RigidbodyEx.velocity;
			if (velocity.y > 0f)
			{
				velocity.y *= YUpVelocityScalar;
				base.Tool.RigidbodyEx.velocity = velocity;
			}
		}

		private void Update()
		{
			if (colliding)
			{
				rumbleSFX.AudioSource.volume = rumbleVolumeBySpeedSquared.Evaluate(base.Tool.RigidbodyEx.velocity.sqrMagnitude);
				colliding = false;
			}
			else
			{
				rumbleSFX.AudioSource.volume = 0f;
			}
		}

		private void OnCollisionStay(Collision collision)
		{
			colliding = true;
			collider.material.dynamicFriction = Mathf.Lerp(collider.material.dynamicFriction, floorFriction, UnityEngine.Time.deltaTime * LerpFrictionSpeed);
		}

		private void OnToolPickup(Tool tool)
		{
			throwerPlayer = tool.Owner;
			DisableThrowerBodyCollision();
		}

		private void OnToolRelease(Tool tool)
		{
			deferredReEnableCollisionCoroutine = this.InvokeInLateUpdate(reEnableBodyCollisionDelay, DeferredReEnablePlayerBodyCollision);
			deferredReEnableCollisionCoroutine.Then(delegate
			{
				deferredReEnableCollisionCoroutine = null;
			});
		}

		private bool IsDeferredReEnableCoroutineRunning()
		{
			return deferredReEnableCollisionCoroutine != null && !deferredReEnableCollisionCoroutine.IsCompleted;
		}

		private void DisableThrowerBodyCollision()
		{
			if (throwerPlayer != null)
			{
				base.Tool.IgnoreCollision(throwerPlayer.Body.BodyCollider, ignore: true);
			}
		}

		private void DeferredReEnablePlayerBodyCollision()
		{
			if (throwerPlayer != null)
			{
				base.Tool.IgnoreCollision(throwerPlayer.Body.BodyCollider, ignore: false);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if ((bool)rumbleSFX)
			{
				AudioManager.StopLoopingSFX(rumbleSFX);
			}
			base.Tool.PostPickupEvent -= OnToolPickup;
			base.Tool.PreReleaseEvent -= OnToolRelease;
			base.Tool.RemoveCustomPickupCondition(CustomPickupCondition);
		}
	}
	public class BowlingManager : GameRuleManager
	{
		public delegate void PlayerBowled(PhotonPlayer bowler, int points);

		public const int NULL_SCORE = -1;

		private const int MAX_BOWLS_PER_FRAME = 3;

		private const int MAX_FRAMES = 10;

		private SynchronizedTimer masterStateTimer;

		private BowlingScoreboard BowlingScoreboard;

		private BowlingLane BowlingLane;

		private SynchronizedField<GameTeam> _currentTeam;

		private SynchronizedField<int> _currentFrame;

		private Dictionary<int, SynchronizedField<int[]>> allPlayerBowls = new Dictionary<int, SynchronizedField<int[]>>();

		private Dictionary<int, SynchronizedField<bool>> allPlayerBumpers = new Dictionary<int, SynchronizedField<bool>>();

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private PlayerBowled m_PlayerBowledEvent;

		public new static BowlingManager Instance => NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance as BowlingManager;

		public GameTeam CurrentTeam
		{
			get
			{
				return _currentTeam.Get();
			}
			set
			{
				_currentTeam.Set(value);
			}
		}

		public PhotonPlayer CurrentPlayer => NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnyPlayerOnTeam(CurrentTeam);

		public int CurrentFrame
		{
			get
			{
				return _currentFrame.Get();
			}
			set
			{
				_currentFrame.Set(value);
			}
		}

		public override string RuleTypeAutoTag => "bowling";

		public bool AllowManualPinReset => false;

		public event PlayerBowled PlayerBowledEvent
		{
			add
			{
				PlayerBowled playerBowled = this.m_PlayerBowledEvent;
				PlayerBowled playerBowled2;
				do
				{
					playerBowled2 = playerBowled;
					playerBowled = Interlocked.CompareExchange(ref this.m_PlayerBowledEvent, (PlayerBowled)Delegate.Combine(playerBowled2, value), playerBowled);
				}
				while (playerBowled != playerBowled2);
			}
			remove
			{
				PlayerBowled playerBowled = this.m_PlayerBowledEvent;
				PlayerBowled playerBowled2;
				do
				{
					playerBowled2 = playerBowled;
					playerBowled = Interlocked.CompareExchange(ref this.m_PlayerBowledEvent, (PlayerBowled)Delegate.Remove(playerBowled2, value), playerBowled);
				}
				while (playerBowled != playerBowled2);
			}
		}

		public int GetPlayerBowl(PhotonPlayer player, int bowl)
		{
			SynchronizedField<int[]> playerBowls = GetPlayerBowls(player);
			return playerBowls.Get()[bowl];
		}

		public void SetPlayerBowl(PhotonPlayer player, int bowl, int points)
		{
			SynchronizedField<int[]> playerBowls = GetPlayerBowls(player);
			int[] array = (int[])playerBowls.Get().Clone();
			array[bowl] = points;
			playerBowls.Set(array);
		}

		private void ClearAllLocalPlayerBowls()
		{
			SynchronizedField<int[]> playerBowls = GetPlayerBowls(PhotonNetwork.player);
			playerBowls.Set(GetNullScoresArray());
		}

		public SynchronizedField<int[]> GetPlayerBowls(PhotonPlayer player)
		{
			if (!allPlayerBowls.TryGetValue(player.ID, out var value))
			{
				value = new SynchronizedField<int[]>(player, "BOWLS", GetNullScoresArray(), SetterPermissionMode.ANYONE, OnFrameScoreChanged);
				allPlayerBowls[player.ID] = value;
			}
			return value;
		}

		public void SetCurrentBowl(int bowlNumber, int points)
		{
			SetPlayerBowl(CurrentPlayer, FrameToFirstBowlIndex(CurrentFrame) + bowlNumber - 1, points);
		}

		public bool GetPlayerBumpers(PhotonPlayer player)
		{
			return getPlayerBumpers(player).Get();
		}

		private SynchronizedField<bool> getPlayerBumpers(PhotonPlayer player)
		{
			if (!allPlayerBumpers.TryGetValue(player.ID, out var value))
			{
				value = new SynchronizedField<bool>(player, "BUMP", defaultValue: false, SetterPermissionMode.ANYONE, OnPlayerBumpersChanged);
				allPlayerBumpers[player.ID] = value;
			}
			return value;
		}

		public void SetPlayerBumpers(PhotonPlayer player, bool on)
		{
			getPlayerBumpers(player).Set(on);
		}

		protected override void Awake()
		{
			base.Awake();
			GameManager.OnGameStartEvent += OnGameStart;
			_currentTeam = new SynchronizedField<GameTeam>(this, "CURRENT_TEAM", GameTeam.ANY, SetterPermissionMode.ANYONE, OnCurrentTeamTurnChanged);
			_currentFrame = new SynchronizedField<int>(this, "CF", 1, SetterPermissionMode.ANYONE, OnCurrentFrameChanged);
			masterStateTimer = new SynchronizedTimer(this, "TIMER", SetterPermissionMode.MASTER);
			BowlingScoreboard = UnityEngine.Object.FindObjectOfType<BowlingScoreboard>();
			BowlingLane = BowlingScoreboard.BowlingLane;
			BowlingLane.CustomValidateBall = CustomValidateBall;
			BowlingLane.BallBowledEvent += OnLaneBallBowled;
			BowlingLane.TurnFinishedEvent += OnLaneTurnFinished;
			ClearAllLocalPlayerBowls();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent += OnTeamChange;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomWinnerNotification = PlayWinnerNotification;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameOver = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameStart = false;
			BowlingScoreboard.Refresh();
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
			{
				BowlingScoreboard.Refresh();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			GameManager.OnGameStartEvent -= OnGameStart;
			if ((bool)NetworkedSingletonMonoBehaviour<GameManager>.Instance)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent -= OnTeamChange;
			}
		}

		protected void Update()
		{
			masterStateTimer.UpdateCallbacks();
		}

		public void OnPlayerBowled(PhotonPlayer bowler, int points)
		{
			if (bowler != null && this.PlayerBowledEvent != null)
			{
				this.PlayerBowledEvent(bowler, points);
			}
		}

		protected void OnGameStart()
		{
			ClearAllLocalPlayerBowls();
			if (PhotonNetwork.isMasterClient)
			{
				CurrentTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams()[0];
				CurrentFrame = 1;
				BowlingLane.MasterStartNewGame();
			}
		}

		private void OnCurrentTeamTurnChanged()
		{
			BowlingScoreboard.Refresh();
			if (CurrentTeam != GameTeam.ANY && CurrentTeam == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(Player.LocalPlayer.PhotonPlayer))
			{
				if (CurrentFrame == 1)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Your Turn!", "On lane 2", 5f);
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Your Turn!", 3f);
				}
			}
			if (PhotonNetwork.isMasterClient && CurrentTeam != GameTeam.ANY)
			{
				PhotonPlayer anyPlayerOnTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnyPlayerOnTeam(CurrentTeam);
				if (anyPlayerOnTeam != null)
				{
					BowlingLane.Bumpers = GetPlayerBumpers(anyPlayerOnTeam);
				}
				else
				{
					BowlingLane.Bumpers = false;
				}
			}
		}

		private void OnLaneTurnFinished()
		{
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
				if (activeTeams.Length == 0)
				{
					UnityEngine.Debug.LogError("No Active Teams");
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
					return;
				}
				int i;
				for (i = 0; i < activeTeams.Length && GetPlayerBowl(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnyPlayerOnTeam(activeTeams[i]), FrameToFirstBowlIndex(CurrentFrame)) != -1; i++)
				{
				}
				if (i >= activeTeams.Length)
				{
					i = 0;
					CurrentFrame++;
				}
				if (CurrentFrame > 10)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
				}
				else
				{
					CurrentTeam = activeTeams[i];
				}
			}
			BowlingScoreboard.Refresh();
		}

		private void OnLaneBallBowled(int bowlNumber, int points)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				SetCurrentBowl(bowlNumber, points);
			}
		}

		private void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			BowlingScoreboard.Refresh();
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
			GameTeam[] array = activeTeams;
			foreach (GameTeam gameTeam in array)
			{
				if (gameTeam == CurrentTeam)
				{
					return;
				}
			}
			OnLaneTurnFinished();
			BowlingLane.ForcePrepareNewRound();
		}

		private void OnFrameScoreChanged()
		{
			BowlingScoreboard.Refresh();
		}

		private void OnCurrentFrameChanged()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = "Frame " + CurrentFrame;
			if (PhotonNetwork.isMasterClient)
			{
				BowlingLane.TenthFrame = CurrentFrame == 10;
			}
			BowlingScoreboard.Refresh();
		}

		internal void LocalPlayerToggleBumpers(PhotonPlayer player)
		{
			bool playerBumpers = GetPlayerBumpers(player);
			playerBumpers = !playerBumpers;
			SetPlayerBumpers(player, playerBumpers);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.Format("Bumpers {0}", (!playerBumpers) ? "Off" : "On"), "For your turn", 4f);
		}

		private void OnPlayerBumpersChanged()
		{
			BowlingScoreboard.Refresh();
		}

		internal void LocalPlayerManualResetPins(PhotonPlayer player)
		{
		}

		private void PlayWinnerNotification()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out var highestScoreTeam, out var _);
			string empty = string.Empty;
			empty = ((highestScoreTeam != GameTeam.ANY) ? (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnyPlayerOnTeam(highestScoreTeam).NickName + " Wins!") : "Tie Game");
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, empty, 4f);
		}

		public static int FrameToFirstBowlIndex(int frameNumber)
		{
			return (frameNumber - 1) * 2;
		}

		private static int[] GetNullScoresArray()
		{
			int num = Mathf.Max(2, 1);
			int num2 = 10 * num + 1;
			int[] array = new int[num2];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = -1;
			}
			return array;
		}

		private bool CustomValidateBall(BowlingBall bowlingBall)
		{
			return CurrentTeam == GameTeam.ANY || (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(bowlingBall.Tool.owner) == CurrentTeam && bowlingBall.Tool.PreviousNonNullHolderPlayer == bowlingBall.Tool.owner.ToPlayer());
		}
	}
	public class BowlingMiniScoreboard : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private BowlingLane BowlingLane;

		[SerializeField]
		private Text frameText;

		private void Awake()
		{
			BowlingLane.BallBowledEvent += BallBowledEvent;
			BowlingLane.FramePointsChangedEvent += FramePointsChanged;
			frameText.text = string.Empty;
		}

		private void FramePointsChanged()
		{
			BallBowledEvent(0, 0);
		}

		private void BallBowledEvent(int bowl1to3, int points)
		{
			if (BowlingLane.FirstBowlPoints == 10)
			{
				frameText.text = "  X\n ";
				return;
			}
			if (BowlingLane.FirstBowlPoints + BowlingLane.SecondBowlPoints == 10)
			{
				frameText.text = string.Format("{0} {1}\n ", BowlingLane.FirstBowlPoints, "/");
				return;
			}
			string arg = ((BowlingLane.FirstBowlPoints < 0 || BowlingLane.SecondBowlPoints < 0) ? " " : (BowlingLane.FirstBowlPoints + BowlingLane.SecondBowlPoints).ToString());
			frameText.text = $"{BowlingScoreboardPlayerRow.GetBowlSymbol(BowlingLane.FirstBowlPoints)} {BowlingScoreboardPlayerRow.GetBowlSymbol(BowlingLane.SecondBowlPoints)}\n{arg}";
		}
	}
	public class BowlingScoreboard : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private BowlingScoreboardPlayerRow[] playerRows;

		[SerializeField]
		private GameObject bumpersInfo;

		[SerializeField]
		private Color waitingColor;

		[SerializeField]
		private Color turnColor;

		public BowlingLane BowlingLane;

		public int MaxRows => playerRows.Length;

		private void Awake()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent += OnGameStart;
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				bumpersInfo.SetActive(value: true);
			}
		}

		private void OnDestroy()
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent -= OnGameStart;
		}

		private void OnGameStart()
		{
			bumpersInfo.SetActive(value: false);
		}

		public void Refresh()
		{
			for (int i = 0; i < MaxRows; i++)
			{
				BowlingScoreboardPlayerRow bowlingScoreboardPlayerRow = playerRows[i];
				bowlingScoreboardPlayerRow.SetRowColor((BowlingManager.Instance.CurrentTeam != (GameTeam)i) ? waitingColor : turnColor);
				PhotonPlayer anyPlayerOnTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnyPlayerOnTeam((GameTeam)i);
				if (anyPlayerOnTeam != null)
				{
					bowlingScoreboardPlayerRow.NameText.text = anyPlayerOnTeam.NickName;
					bowlingScoreboardPlayerRow.BumpersIcon.SetActive(BowlingManager.Instance.GetPlayerBumpers(anyPlayerOnTeam));
					int[] array = BowlingManager.Instance.GetPlayerBowls(anyPlayerOnTeam).Get();
					int num = 0;
					for (int j = 1; j <= 10; j++)
					{
						int num2 = BowlingManager.FrameToFirstBowlIndex(j);
						if (array[num2] == 10)
						{
							num += 10;
							int k = num2 + 1;
							int num3 = 2;
							for (; k < array.Length; k++)
							{
								if (num3 <= 0)
								{
									break;
								}
								if (k - num2 > 4)
								{
									break;
								}
								if (array[k] != -1)
								{
									num += array[k];
									num3--;
								}
							}
							if (num3 != 0)
							{
								num = -1;
							}
						}
						else
						{
							num += Mathf.Clamp(array[num2], 0, 10) + Mathf.Clamp(array[num2 + 1], 0, 10);
							if (array[num2] + array[num2 + 1] == 10)
							{
								num = ((num2 + 2 >= array.Length || array[num2 + 2] == -1) ? (-1) : (num + array[num2 + 2]));
							}
						}
						int frameToCurrentFrame = (int)(MaxRows * (BowlingManager.Instance.CurrentFrame - j) + BowlingManager.Instance.CurrentTeam - i);
						bowlingScoreboardPlayerRow.SetFrame(j, array[num2], array[num2 + 1], array[num2 + 2], num, frameToCurrentFrame);
					}
					if (PhotonNetwork.isMasterClient)
					{
						NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetScore((GameTeam)i, bowlingScoreboardPlayerRow.TotalScore);
					}
				}
				else
				{
					bowlingScoreboardPlayerRow.NameText.text = "---";
					bowlingScoreboardPlayerRow.TotalText.text = string.Empty;
					bowlingScoreboardPlayerRow.BumpersIcon.SetActive(value: false);
					for (int l = 1; l <= 10; l++)
					{
						bowlingScoreboardPlayerRow.SetFrame(l, -1, -1, -1, -1, -1);
					}
				}
			}
		}
	}
	public class BowlingScoreboardPlayerRow : UnityEngine.MonoBehaviour
	{
		public int TotalScore;

		public Text[] rowTexts;

		public UnityEngine.UI.Image[] rowImages;

		public GameObject BumpersIcon;

		public Text NameText => rowTexts[0];

		public Text TotalText => rowTexts[11];

		public void SetRowColor(Color color)
		{
			UnityEngine.UI.Image[] array = rowImages;
			foreach (UnityEngine.UI.Image image in array)
			{
				color.a = image.color.a;
				image.color = color;
			}
		}

		public void SetFrame(int frame1to10, int bowl1, int bowl2, int bowl3, int total, int frameToCurrentFrame)
		{
			string text;
			if (total >= 0 && ((bowl1 >= 0 && bowl2 >= 0) || bowl1 == 10))
			{
				text = total.ToString();
				TotalText.text = text;
				TotalScore = total;
			}
			else
			{
				text = " ";
				if (frame1to10 == 1)
				{
					TotalText.text = text;
					TotalScore = 0;
				}
			}
			if (bowl1 < 0)
			{
				if (frameToCurrentFrame > 0)
				{
					rowTexts[frame1to10].text = $"- -\n{text}";
				}
				else
				{
					rowTexts[frame1to10].text = string.Empty;
				}
			}
			else if (frame1to10 == 10)
			{
				rowTexts[frame1to10].text = string.Format("{0}{1}{2}{4}\n{3}", GetBowlSymbol(bowl1), GetBowlSymbol(bowl2, bowl1 != 10 && bowl1 + bowl2 == 10), GetBowlSymbol(bowl3), text, (bowl3 < 0) ? " " : string.Empty);
			}
			else if (bowl1 == 10)
			{
				rowTexts[frame1to10].text = $"  X\n{text}";
			}
			else
			{
				rowTexts[frame1to10].text = $"{GetBowlSymbol(bowl1)} {GetBowlSymbol(bowl2, bowl1 + bowl2 == 10)}\n{text}";
			}
			Color color = rowImages[frame1to10].color;
			color.a = ((frameToCurrentFrame < 0 && bowl1 < 0) ? 0f : 1f);
			rowImages[frame1to10].color = color;
		}

		public static string GetBowlSymbol(int points, bool spare = false)
		{
			if (points < 0)
			{
				return " ";
			}
			if (spare)
			{
				return "/";
			}
			return points switch
			{
				0 => "-", 
				10 => "X", 
				_ => points.ToString(), 
			};
		}
	}
	public class BowlingLane : Photon.MonoBehaviour
	{
		public delegate void BallBowled(int bowl1to3, int points);

		public delegate void TurnFinished();

		public delegate void FramePointsChanged();

		public delegate bool ValidateBall(BowlingBall bowlingBall);

		private enum BowlingLaneState
		{
			INVALID,
			PREPARING_ROUND,
			BOWLING_FRAME,
			LIFT_PINS
		}

		private const int MAX_FRAME_POINTS = 10;

		private const int MAX_PINS = 10;

		private const float SLEEP_SPEED = 0.2f;

		private const float SLEEP_SPIN = 1f;

		private const float MIN_RESET_DELAY = 2f;

		private const float MAX_RESET_DELAY = 7f;

		[SerializeField]
		private BowlingPin pinPrefab;

		[SerializeField]
		private Transform firstPinLocation;

		[SerializeField]
		private Transform fowlLine;

