		[SerializeField]
		private Transform[] ballReturnSpawnLocations;

		[SerializeField]
		private Renderer bowlLight1;

		[SerializeField]
		private Renderer bowlLight2;

		[SerializeField]
		private Animator animator;

		[SerializeField]
		private RecRoomAudioClip pinSetterSound;

		[SerializeField]
		private Collider triggerVolume;

		[SerializeField]
		private RecRoomAudioClip strikeSFX;

		private int pinStrikeEnergy = 45;

		private int pinHitMinThreshold = 1;

		private float pinEnergy;

		private float pinEnergyDecay = 50f;

		private float lastPinCollisionTime;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private BallBowled m_BallBowledEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private TurnFinished m_TurnFinishedEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private FramePointsChanged m_FramePointsChangedEvent;

		public ValidateBall CustomValidateBall;

		private List<BowlingPin> pins = new List<BowlingPin>(10);

		private SynchronizedTimer bowlingTimer;

		private SynchronizedStateMachine stateMachine;

		private BowlingBall cachedActiveBall;

		private BowlingBall prevCachedActiveBall;

		private SynchronizedField<int> _activeBallPhotonViewId;

		private SynchronizedField<bool> _tenthFrame;

		private SynchronizedField<bool> _bumpers;

		private SynchronizedField<int, int, int> _framePoints;

		private BowlingBall ActiveBall
		{
			get
			{
				return cachedActiveBall;
			}
			set
			{
				_activeBallPhotonViewId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		public bool TenthFrame
		{
			get
			{
				return _tenthFrame.Get();
			}
			set
			{
				_tenthFrame.Set(value);
			}
		}

		public bool Bumpers
		{
			get
