		public int SecondBowlPoints
		{
			get
			{
				return _framePoints.Get2();
			}
			set
			{
				_framePoints.Set2(value);
			}
		}

		public int ThirdBowlPoints
		{
			get
			{
				return _framePoints.Get3();
			}
			set
			{
				_framePoints.Set3(value);
			}
		}

		private int RemainingBowlsThisFrame
		{
			get
			{
				if (FirstBowlPoints == -1)
				{
					return 2;
				}
				if (TenthFrame)
				{
					bool flag = FirstBowlPoints == 10 || FirstBowlPoints + SecondBowlPoints == 10;
					if (SecondBowlPoints == -1)
					{
						return (!flag) ? 1 : 2;
					}
					if (ThirdBowlPoints == -1)
					{
						return flag ? 1 : 0;
					}
				}
				else if (FirstBowlPoints != 10 && SecondBowlPoints == -1)
				{
					return 1;
				}
				return 0;
			}
		}

		private bool ResetPinsDuringTenthFrame
		{
			get
			{
				if (!TenthFrame)
				{
					return false;
				}
				if (FirstBowlPoints == 10 && SecondBowlPoints == -1)
				{
					return true;
				}
				if (SecondBowlPoints == 10 && ThirdBowlPoints == -1)
				{
					return true;
				}
				if (FirstBowlPoints != 10 && FirstBowlPoints + SecondBowlPoints == 10 && ThirdBowlPoints == -1)
				{
					return true;
				}
				return false;
			}
		}

		public event BallBowled BallBowledEvent
		{
			add
			{
				BallBowled ballBowled = this.m_BallBowledEvent;
				BallBowled ballBowled2;
				do
				{
					ballBowled2 = ballBowled;
					ballBowled = Interlocked.CompareExchange(ref this.m_BallBowledEvent, (BallBowled)Delegate.Combine(ballBowled2, value), ballBowled);
				}
				while (ballBowled != ballBowled2);
			}
			remove
			{
				BallBowled ballBowled = this.m_BallBowledEvent;
				BallBowled ballBowled2;
				do
				{
					ballBowled2 = ballBowled;
					ballBowled = Interlocked.CompareExchange(ref this.m_BallBowledEvent, (BallBowled)Delegate.Remove(ballBowled2, value), ballBowled);
				}
				while (ballBowled != ballBowled2);
			}
		}

		public event TurnFinished TurnFinishedEvent
		{
			add
			{
				TurnFinished turnFinished = this.m_TurnFinishedEvent;
				TurnFinished turnFinished2;
				do
				{
					turnFinished2 = turnFinished;
					turnFinished = Interlocked.CompareExchange(ref this.m_TurnFinishedEvent, (TurnFinished)Delegate.Combine(turnFinished2, value), turnFinished);
				}
