		protected override void Awake()
		{
			base.Awake();
			stateMachine = new SynchronizedStateMachine("BLSM", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(1, OnEnterPreparingRound, null, OnUpdatePreparingRound);
			stateMachine.AddState(2, OnEnterBowlingFrame, OnExitBowlingFrame, OnUpdateBowlingFrame);
			stateMachine.AddState(3, OnEnterLiftPins, OnExitLiftPins, OnUpdateLiftPins);
			stateMachine.AddState(0, null, null, null);
			_framePoints = new SynchronizedField<int, int, int>(this, "BFP", -1, -1, -1, SetterPermissionMode.ANYONE, OnFramePointsChanged);
			_tenthFrame = new SynchronizedField<bool>(this, "TF", defaultValue: false, SetterPermissionMode.ANYONE);
			_bumpers = new SynchronizedField<bool>(this, "BUMP", defaultValue: false, SetterPermissionMode.ANYONE, OnBumperModeChanged);
			_activeBallPhotonViewId = new SynchronizedField<int>(this, "ABID", -1, SetterPermissionMode.ANYONE, OnActiveBallPhotonViewIdChange);
			bowlingTimer = new SynchronizedTimer(this, "BOWL_TIMER", SetterPermissionMode.ANYONE);
		}

		protected void Start()
		{
			SetupPins();
			stateMachine.Start(this, 1);
			this.Update1hz(StaggeredUpdate);
		}

		protected void Update()
		{
			stateMachine.Update();
			bowlingTimer.UpdateCallbacks();
		}

		private void StaggeredUpdate(float deltaTime)
		{
			ValidatePinPositions();
		}

		public void ResetPoints()
		{
			_framePoints.Set(-1, -1, -1);
		}

		private void OnFramePointsChanged()
		{
			if (this.FramePointsChangedEvent != null)
			{
				this.FramePointsChangedEvent();
			}
		}

		private void OnBumperModeChanged()
		{
			animator.SetBool("BumpersEnabled", Bumpers);
		}

		private void OnActiveBallPhotonViewIdChange()
		{
			if (prevCachedActiveBall != null)
			{
				prevCachedActiveBall.Tool.ToolCleanup.ResumeCleanup(this);
			}
			prevCachedActiveBall = cachedActiveBall;
			PhotonView photonView = PhotonView.Find(_activeBallPhotonViewId.Get());
			cachedActiveBall = ((!(photonView != null)) ? null : photonView.GetComponent<BowlingBall>());
			if (cachedActiveBall != null)
			{
				cachedActiveBall.Tool.ToolCleanup.PauseCleanup(this);
			}
		}

		public void PlayPinSetterSound()
		{
			AudioManager.Play3DSFX(pinSetterSound, base.transform);
		}

		public void MasterStartNewGame()
		{
			if (PhotonNetwork.isMasterClient)
			{
				SingletonMonoBehaviour<Scheduler>.Instance.Run(this, StartNewGameRoutine());
			}
		}

		public IEnumerator<ISchedule> StartNewGameRoutine()
		{
			while (stateMachine.CurrentStateId != 2 && ActiveBall != null)
			{
				yield return Schedule.NextFrame;
			}
			stateMachine.EnterState(0);
			stateMachine.EnterState(1);
			_framePoints.Set(-1, -1, -1);
		}

		private void OnTriggerEnter(Collider other)
		{
			ValidateColliderInLane(other);
		}

		private void ValidateColliderInLane(Collider other)
		{
			Tool componentInParent = other.GetComponentInParent<Tool>();
			if (!(componentInParent != null) || !componentInParent.hasAuthority)
			{
				return;
			}
			bool flag = false;
			if (stateMachine.CurrentStateId == 2)
			{
				BowlingBall componentInParent2 = other.GetComponentInParent<BowlingBall>();
				if (componentInParent2 != null)
				{
					if ((bool)ActiveBall && componentInParent2 == ActiveBall)
					{
						flag = true;
					}
					else if (!componentInParent2.Tool.IsHeld && ActiveBall == null)
					{
						if (fowlLine.InverseTransformPoint(componentInParent2.owner.ToPlayer().Head.transform.position).z < 0f)
						{
							SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Foul!", 3f);
							base.photonView.RpcAll(RpcPlayFowlBuzzer);
						}
						else if (CustomValidateBall == null || CustomValidateBall(componentInParent2))
						{
							ActiveBall = componentInParent2;
							TransferAuthorityOfLaneAndPins(componentInParent2.owner);
							flag = true;
						}
					}
				}
			}
			if (!flag)
			{
				componentInParent.AuthorityResetToLastSpawnPosition();
			}
		}

		[PunRPC]
		private void RpcPlayFowlBuzzer()
		{
			AudioManager.Play3DSFX(fowlBuzzer, base.transform);
		}

		public void ForcePrepareNewRound()
		{
			stateMachine.EnterState(0);
			stateMachine.EnterState(1);
		}

		private void OnEnterPreparingRound(ushort otherStateId, ushort otherSubStateId)
		{
			ResetPoints();
			if (otherStateId == 3 && this.TurnFinishedEvent != null)
			{
				this.TurnFinishedEvent();
			}
			if (PhotonNetwork.isMasterClient && (bool)ActiveBall)
			{
				ActiveBall.Tool.MasterResetToLastSpawnPosition();
				ActiveBall = null;
			}
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcResetPins);
			}
			Renderer renderer = bowlLight1;
			bool flag = false;
			bowlLight2.enabled = flag;
			renderer.enabled = flag;
		}

		private void OnUpdatePreparingRound()
		{
			stateMachine.EnterState(2);
		}

		private void OnEnterLiftPins(ushort otherStateId, ushort otherSubStateId)
		{
			animator.SetTrigger("LiftAndCount");
			if (PhotonNetwork.isMasterClient)
			{
				bowlingTimer.StartTimer(5f);
			}
			bowlLight1.enabled = RemainingBowlsThisFrame >= 2;
			bowlLight2.enabled = RemainingBowlsThisFrame >= 1;
		}

		private void OnUpdateLiftPins()
		{
			if (base.hasAuthority)
			{
				foreach (BowlingPin pin in pins)
				{
					if (pin.StandingInLane)
					{
						Vector3 position = pin.Tool.transform.position;
						position.y = firstPinLocation.position.y;
						pin.Tool.RigidbodyEx.targetPosition = position;
					}
				}
			}
			if (bowlingTimer.TimerOver)
			{
				if (RemainingBowlsThisFrame > 0)
				{
					stateMachine.EnterState(2);
				}
				else
				{
					stateMachine.EnterState(1);
				}
			}
		}

		private void OnExitLiftPins(ushort otherStateId, ushort otherSubStateId)
		{
			DisableDownedPins();
			if (ResetPinsDuringTenthFrame)
			{
				if (base.hasAuthority)
				{
					base.photonView.RpcAll(RpcResetPins);
					if (BowlingManager.Instance.CurrentPlayer == Player.LocalPlayer.PhotonPlayer)
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Bonus Bowl!", $"{RemainingBowlsThisFrame} throws left", 4f);
					}
				}
			}
			else
			{
				DisableDownedPins();
			}
		}

		private void OnEnterBowlingFrame(ushort otherStateId, ushort otherSubStateId)
		{
			if (base.hasAuthority)
			{
				CountStandingPins();
				bowlingTimer.StartTimer(7f);
				bowlingTimer.Pause();
			}
			bowlLight1.enabled = RemainingBowlsThisFrame >= 2;
			bowlLight2.enabled = RemainingBowlsThisFrame >= 1;
		}

		private void OnUpdateBowlingFrame()
		{
			if (!base.hasAuthority || !ActiveBall)
			{
				return;
			}
			float z = firstPinLocation.InverseTransformPoint(ActiveBall.transform.position).z;
			float num = 0f - firstPinLocation.InverseTransformDirection(ActiveBall.Tool.RigidbodyEx.velocity).z;
			if (z < 5f)
			{
				foreach (BowlingPin pin in pins)
				{
					if (pin.Tool.RigidbodyEx.IsSleeping())
					{
						pin.Tool.RigidbodyEx.WakeUp();
					}
					if (pin.photonView.owner != ActiveBall.owner)
					{
						pin.photonView.TransferOwnership(ActiveBall.owner.ID);
					}
				}
			}
			if (!(z < -1.5f) && !(num < 0.001f))
			{
				return;
			}
			if (bowlingTimer.IsPaused)
			{
				bowlingTimer.Resume();
			}
			if (bowlingTimer.TimeElapsed < 2f)
			{
				return;
			}
			if (!bowlingTimer.TimerOver)
			{
				foreach (BowlingPin pin2 in pins)
				{
					if (pin2.Tool.IsEnabled)
					{
						if (pin2.Tool.RigidbodyEx.velocity.sqrMagnitude > 0.040000003f)
						{
							return;
						}
						Vector3 localAngularVelocity = pin2.Tool.RigidbodyEx.localAngularVelocity;
						localAngularVelocity.y = 0f;
						if (localAngularVelocity.sqrMagnitude > 1f)
						{
							return;
						}
					}
				}
			}
			int num2 = CountStandingPins();
			if (FirstBowlPoints == -1)
			{
				FirstBowlPoints = 10 - num2;
				if (this.BallBowledEvent != null)
				{
					this.BallBowledEvent(1, FirstBowlPoints);
				}
				BowlingManager.Instance?.OnPlayerBowled(ActiveBall.owner, FirstBowlPoints);
				if (FirstBowlPoints == 10 && ActiveBall.owner.IsLocal)
				{
					Player.LocalPlayer.PlayerEvents.BowlingStrike();
				}
			}
			else if (SecondBowlPoints == -1)
			{
				SecondBowlPoints = 10 - num2 - ((!TenthFrame || FirstBowlPoints != 10) ? FirstBowlPoints : 0);
				if (this.BallBowledEvent != null)
				{
					this.BallBowledEvent(2, SecondBowlPoints);
				}
				BowlingManager.Instance?.OnPlayerBowled(ActiveBall.owner, SecondBowlPoints);
				if (FirstBowlPoints == 10 && SecondBowlPoints == 10 && ActiveBall.owner.IsLocal)
				{
					Player.LocalPlayer.PlayerEvents.BowlingStrike();
				}
			}
			else if (ThirdBowlPoints == -1)
			{
				int num3 = ((SecondBowlPoints != 10 && FirstBowlPoints + SecondBowlPoints != 10) ? SecondBowlPoints : 0);
				ThirdBowlPoints = 10 - num2 - num3;
				if (this.BallBowledEvent != null)
				{
					this.BallBowledEvent(3, ThirdBowlPoints);
				}
				BowlingManager.Instance?.OnPlayerBowled(ActiveBall.owner, ThirdBowlPoints);
				if ((FirstBowlPoints + SecondBowlPoints == 10 || SecondBowlPoints == 10) && ThirdBowlPoints == 10 && ActiveBall.owner.IsLocal)
				{
					Player.LocalPlayer.PlayerEvents.BowlingStrike();
				}
			}
			stateMachine.EnterState(3);
		}

		private void OnExitBowlingFrame(ushort otherStateId, ushort otherSubStateId)
		{
			if (!base.hasAuthority || !ActiveBall)
			{
				return;
			}
			Vector3 position = ballReturnSpawnLocations[0].position;
			if (ballReturnSpawnLocations.Length > 1)
			{
				Transform[] array = ballReturnSpawnLocations;
				foreach (Transform transform in array)
				{
					if (!Physics.CheckSphere(transform.position, 0.2f, 159785984))
					{
						position = transform.position;
						break;
					}
				}
			}
			ActiveBall.Tool.AuthorityResetToDefault(position, UnityEngine.Random.rotation, sleepPhysics: false, wasCleanedUp: true);
			ActiveBall.Tool.ToolCleanup.ResumeCleanup(this);
			ActiveBall = null;
		}

		[PunRPC]
		private void RpcPlayStrikeSound()
		{
			AudioManager.Play3DSFX(strikeSFX, base.transform.position);
		}

		[PunRPC]
		private void RpcResetPins()
		{
			foreach (BowlingPin pin in pins)
			{
				pin.StandingInLane = true;
				pin.Tool.IsEnabled = true;
				pin.Tool.SleepOnCleanup = true;
				pin.Tool.AuthorityResetToLastSpawnPosition();
				pin.Tool.ToolCleanup.PauseCleanup(this);
				pin.Tool.RigidbodyEx.RemoveKinematic(this);
				pin.Tool.RigidbodyEx.Sleep();
			}
		}

		public void OnPinCollision(Collision collision, BowlingPin pin, BowlingPin otherPin)
		{
			if (!(collision.impulse.sqrMagnitude > (float)pinHitMinThreshold))
			{
				return;
			}
			pinEnergy = Mathf.Clamp(pinEnergy - (UnityEngine.Time.time - lastPinCollisionTime) * pinEnergyDecay, 0f, pinStrikeEnergy);
			lastPinCollisionTime = UnityEngine.Time.time;
			pinEnergy += Mathf.Clamp(collision.impulse.sqrMagnitude, 0f, 5f);
			if (pinEnergy > (float)pinStrikeEnergy)
			{
				pinEnergy = 0f;
				if (base.hasAuthority)
				{
					base.photonView.RpcAll(RpcPlayStrikeSound);
				}
			}
		}

		public void SetStandingPinsKinematic(int kinematic)
		{
			foreach (BowlingPin pin in pins)
			{
				if (kinematic > 0 && pin.StandingInLane)
				{
					pin.Tool.RigidbodyEx.AddKinematic(this);
					continue;
				}
				pin.Tool.RigidbodyEx.RemoveKinematic(this);
				pin.Tool.RigidbodyEx.Sleep();
			}
		}

		private int CountStandingPins()
		{
			int num = 0;
			foreach (BowlingPin pin in pins)
			{
				if (pin.Tool.IsEnabled && pin.IsUpright && (pin.Tool.LastSpawnPosition - pin.transform.position).sqrMagnitude < 0.0625f)
				{
					pin.StandingInLane = true;
					num++;
				}
				else
				{
					pin.StandingInLane = false;
				}
			}
			return num;
		}

		public void DisableDownedPins()
		{
			foreach (BowlingPin pin in pins)
			{
				if (!pin.StandingInLane)
				{
					pin.Tool.IsEnabled = false;
				}
			}
		}

		private void ValidatePinPositions()
		{
			foreach (BowlingPin pin in pins)
			{
				if (pin.transform.position.y < -1f || float.IsNaN(pin.transform.localPosition.y))
				{
					UnityEngine.Debug.LogError($"Pin error {pin.transform.position.y}. owner: {pin.photonView.owner}, resetting", base.gameObject);
					pin.Tool.MasterResetToLastSpawnPosition();
				}
			}
		}

		private void SetupPins()
		{
			pins.Clear();
			BowlingPin[] array = UnityEngine.Object.FindObjectsOfType<BowlingPin>();
			BowlingPin[] array2 = array;
			foreach (BowlingPin bowlingPin in array2)
			{
				if (bowlingPin.Lane == this)
				{
					pins.Add(bowlingPin);
				}
			}
			foreach (BowlingPin pin in pins)
			{
				pin.Tool.IgnoreCollision(triggerVolume, ignore: true);
				pin.Tool.RigidbodyEx.WakeUp();
				pin.Tool.ToolCleanup.PauseCleanup(this);
			}
		}

		private void TransferAuthorityOfLaneAndPins(PhotonPlayer newOwner)
		{
			base.photonView.TransferOwnership(newOwner.ID);
			foreach (BowlingPin pin in pins)
			{
				pin.photonView.TransferOwnership(newOwner.ID);
			}
		}
	}
	public class BowlingPin : Photon.MonoBehaviour
	{
		private const float MAX_UPRIGHT_ANGLE_OFFSET_DEGREES = 25f;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		[SerializeField]
		private BowlingLane lane;

		private SynchronizedField<bool> standingInLane;

		public Tool Tool => tool;

		public BowlingLane Lane => lane;

		public bool StandingInLane
		{
			get
			{
				return standingInLane.Get();
			}
			set
			{
				standingInLane.Set(value);
			}
		}

		public float AngleFromUpright => Vector3.Angle(base.transform.up, Vector3.up);

		public bool IsUpright => AngleFromUpright <= 25f;

		protected override void Awake()
		{
			base.Awake();
			standingInLane = new SynchronizedField<bool>(this, "BP", defaultValue: false, SetterPermissionMode.ANYONE);
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (lane != null)
			{
				BowlingPin componentInParent = collision.collider.GetComponentInParent<BowlingPin>();
				lane.OnPinCollision(collision, this, componentInParent);
			}
		}
	}
