	public class PoolBall : UnityEngine.MonoBehaviour
	{
		public const float Radius = 0.0315f;

		public int BallNumber;

		[Autofill(AutofillType.SelfAndParent, false)]
		[SerializeField]
		private Tool tool;

		public Tool Tool => tool;

		public bool IsCueBall => BallNumber == 0;

		private void Awake()
		{
			int num = (BallNumber - 1) % 16;
			int num2 = 3 - num / 4;
			int num3 = num % 4;
			Material material = GetComponentInChildren<Renderer>().material;
			material.SetTextureScale("_MainTex", new Vector2(0.248f, 0.248f));
			material.SetTextureOffset("_MainTex", new Vector2(0.25f * (float)num3 + 0.001f, 0.25f * (float)num2 + 0.001f));
		}

		private void Start()
		{
			this.FixedUpdate10hz(OnFixedUpdate);
		}

		public void OnFixedUpdate(float deltaTime)
		{
			float sqrMagnitude = tool.RigidbodyEx.velocity.sqrMagnitude;
			if (sqrMagnitude > 0f)
			{
				if (sqrMagnitude < 0.0001f)
				{
					Tool.RigidbodyEx.Sleep();
				}
				else if (sqrMagnitude < 0.02f)
				{
					Tool.RigidbodyEx.angularVelocity *= 0.75f;
				}
			}
		}
	}
