				while (action != action2);
			}
			remove
			{
				Action action = this.m_StateChanged;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_StateChanged, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public event Action<float> BallHit
		{
			add
			{
				Action<float> action = this.m_BallHit;
				Action<float> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BallHit, (Action<float>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<float> action = this.m_BallHit;
				Action<float> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BallHit, (Action<float>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_currentState = new SynchronizedField<State>(this, "S", State.Detached, SetterPermissionMode.AUTHORITY, OnStateChanged);
			_holdingHandLocalPosition = new SynchronizedField<Vector3>(this, "HHLP", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_holdingHandLocalRotation = new SynchronizedField<Quaternion>(this, "HHLR", Quaternion.identity, SetterPermissionMode.AUTHORITY);
			_aimingHandLocalPosition = new SynchronizedField<Vector3>(this, "AHLP", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_shootingLockedPosition = new SynchronizedField<Vector3>(this, "SLP", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_shootingLockedRotation = new SynchronizedField<Quaternion>(this, "SLR", Quaternion.identity, SetterPermissionMode.AUTHORITY);
			_shootingHandStartPosition = new SynchronizedField<Vector3>(this, "SHSP", Vector3.zero, SetterPermissionMode.AUTHORITY);
		}

		private void Start()
		{
			PoolBall[] array = UnityEngine.Object.FindObjectsOfType<PoolBall>();
			Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
			foreach (Collider collider in componentsInChildren)
			{
				PoolBall[] array2 = array;
				foreach (PoolBall poolBall in array2)
				{
					Physics.IgnoreCollision(collider, poolBall.GetComponentInChildren<Collider>());
				}
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			lastBallHit = null;
		}

		private void FixedUpdate()
		{
			if (CurrentState == State.Shooting)
			{
				CheckForBallHits();
			}
			lastTipPosition = tip.position;
		}

		private void CheckForBallHits()
		{
			Vector3 vector = tip.position - lastTipPosition;
			if (Vector3.Dot(vector, base.transform.forward) <= 0f)
			{
				return;
			}
			int num = Physics.SphereCastNonAlloc(lastTipPosition, 0.01f, vector.normalized, hits, vector.magnitude, 1024);
			for (int i = 0; i < num; i++)
			{
				if (!hits[i].collider.gameObject.CompareTag("Pool/Ball") || hits[i].point.IsZero())
				{
					continue;
				}
				PoolBall componentInParent = hits[i].collider.GetComponentInParent<PoolBall>();
				if (componentInParent != lastBallHit || UnityEngine.Time.realtimeSinceStartup - timeLastBallHit > 0.25f)
				{
					Vector3 force = 1.25f * (vector / UnityEngine.Time.fixedDeltaTime);
					componentInParent.Tool.RigidbodyEx.AddForceAtPosition(force, hits[i].point, ForceMode.VelocityChange);
					lastBallHit = componentInParent;
					timeLastBallHit = UnityEngine.Time.realtimeSinceStartup;
					AudioManager.Play3DSFX(ballHitAudio.audioClip, hits[i].point, Mathf.Lerp(0f, ballHitAudio.volume, force.magnitude / 2f), ballHitAudio.pitchVariation, ballHitAudio.pitchShift);
					if (this.BallHit != null)
					{
						this.BallHit(force.magnitude);
					}
				}
			}
		}

		private void OnStateChanged()
		{
			if (this.StateChanged != null)
			{
				this.StateChanged();
			}
		}
	}
	public class PoolCueAimGrip : ToolAccessory
	{
		private PoolCueRigidbodyPickup poolCueRigidbodyPickup;

		private PlungerRigidbodyPickup thisRigidbodyPickup;

		[Autofill(AutofillType.Parent, false)]
		[SerializeField]
		private PoolCue cue;

		public bool IsPickedUp { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.IgnorePickupDirection = true;
				base.Tool.PostPickupEvent += OnPostPickup;
				base.Tool.PreReleaseEvent += OnPreRelease;
				base.Tool.PostReleaseEvent += OnPostRelease;
				base.Tool.PostResetEvent += OnReset;
			}
		}

		protected override void Start()
		{
			base.Start();
			poolCueRigidbodyPickup = parentTool.RigidbodyPickup as PoolCueRigidbodyPickup;
			if (poolCueRigidbodyPickup == null)
			{
				UnityEngine.Debug.LogError(parentTool.name + "missing StabilizedRigidbodyPickup.");
				return;
			}
			thisRigidbodyPickup = base.Tool.RigidbodyPickup as PlungerRigidbodyPickup;
			thisRigidbodyPickup.ConstraintPickup = poolCueRigidbodyPickup;
			thisRigidbodyPickup.ConstraintOffsetPosition = localPosition;
			thisRigidbodyPickup.ConstraintOffsetRotation = localRotation;
			thisRigidbodyPickup.ConstraintLocalAxis = Vector3.forward;
			thisRigidbodyPickup.MinimumConstraintDistance = 0f;
			thisRigidbodyPickup.MaximumConstraintDistance = 0f;
			if (!base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToParentTool();
			}
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			if (initialized && !base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToParentTool();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= OnPostPickup;
				base.Tool.PostReleaseEvent -= OnPostRelease;
				base.Tool.PostResetEvent -= OnReset;
			}
		}

		private void OnPostPickup(Tool tool)
		{
			IsPickedUp = true;
			if (tool.HolderPlayer == Player.LocalPlayer)
			{
				PlayerHand holderHand = tool.HolderHand;
				cue.AimingHandLocalPosition = cue.transform.InverseTransformPoint(holderHand.transform.position);
				cue.CurrentState = PoolCue.State.Aiming;
			}
		}

		private void OnPreRelease(Tool tool)
		{
			if (tool.HolderPlayer == Player.LocalPlayer)
			{
				PlayerHand otherHand = Player.LocalPlayer.GetOtherHand(tool.HolderHand.Type);
				cue.HoldingHandLocalRotation = otherHand.transform.InverseTransformRotation(cue.transform.rotation);
				cue.HoldingHandLocalPosition = cue.transform.InverseTransformPoint(otherHand.transform.position);
				cue.CurrentState = PoolCue.State.Holding;
			}
		}

		private void OnPostRelease(Tool tool)
		{
			IsPickedUp = false;
			this.EndOfFrameRoutine(AuthorityAttachToParentTool);
		}

		private void OnReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			UnityEngine.Debug.LogErrorFormat("Resetting stabilization subtool {0}. Subtools generally shouldn't be manually reset.", this);
			AuthorityAttachToParentTool();
		}

		private void AuthorityAttachToParentTool()
		{
			if (base.Tool.hasAuthority && parentTool != null)
			{
				base.Tool.AuthorityAttachToObject(parentTool.photonView, localPosition, localRotation, localScale);
			}
		}
	}
	public class PoolCueRigidbodyPickup : RigidbodyPickup
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private PoolCue cue;

		public override Quaternion TargetRotation
		{
			get
			{
				if (!IsPickedUp || tool.HolderPlayer == null)
				{
					return base.TargetRotation;
				}
				PlayerHand holderHand = tool.HolderHand;
				PlayerHand otherHand = tool.HolderPlayer.GetOtherHand(holderHand.Type);
				return cue.CurrentState switch
				{
					PoolCue.State.Holding => holderHand.transform.TransformRotation(cue.HoldingHandLocalRotation), 
					PoolCue.State.Aiming => Quaternion.LookRotation(otherHand.transform.position - holderHand.transform.position), 
					PoolCue.State.Shooting => cue.ShootingLockedRotation, 
					_ => base.TargetRotation, 
				};
			}
		}

		public override Vector3 TargetPosition
		{
			get
			{
				if (!IsPickedUp || tool.HolderPlayer == null)
				{
					return base.TargetPosition;
				}
				PlayerHand holderHand = tool.HolderHand;
				PlayerHand otherHand = tool.HolderPlayer.GetOtherHand(holderHand.Type);
				switch (cue.CurrentState)
				{
				case PoolCue.State.Holding:
					return holderHand.transform.position - TargetRotation * cue.HoldingHandLocalPosition;
				case PoolCue.State.Aiming:
					return otherHand.transform.position - TargetRotation * cue.AimingHandLocalPosition;
				case PoolCue.State.Shooting:
				{
					Vector3 vector = Vector3.Project(holderHand.transform.position - cue.ShootingHandStartPosition, cue.ShootingLockedRotation * Vector3.forward);
					return cue.ShootingLockedPosition + vector;
				}
				default:
					return base.TargetPosition;
				}
			}
		}

		protected override void Awake()
		{
			base.Awake();
			tool.PostPickupEvent += OnPostPickup;
			tool.PostReleaseEvent += OnPostRelease;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostPickupEvent -= OnPostPickup;
			tool.PostReleaseEvent -= OnPostRelease;
		}

		private void OnPostPickup(Tool thisTool)
		{
			tool.GetHolderSpaceHandPickupTransform(tool.HolderHand.transform, tool.HolderHand.Type == PlayerHand.HandType.Left, out var position, out var rotation);
			Matrix4x4 matrix4x = default(Matrix4x4);
			matrix4x.SetTRS(position, rotation, Vector3.one);
			cue.HoldingHandLocalPosition = matrix4x.inverse.MultiplyPoint(Vector3.zero);
			cue.HoldingHandLocalRotation = rotation;
			cue.CurrentState = PoolCue.State.Holding;
		}

		private void OnPostRelease(Tool thisTool)
		{
			cue.CurrentState = PoolCue.State.Detached;
		}
	}
