	public class PoolTableCushion : Photon.MonoBehaviour
	{
		private const float minBounce = 0.2f;

		private const float maxBounce = 0.8f;

		private const float speedForMaxBounce = 2.5f;

		private void OnCollisionEnter(Collision collision)
		{
			if (collision.gameObject.CompareTag("Pool/Ball"))
			{
				PoolBall componentInParent = collision.gameObject.GetComponentInParent<PoolBall>();
				RigidbodyEx rigidbodyEx = componentInParent.Tool.RigidbodyEx;
				Vector3 relativeVelocity = collision.relativeVelocity;
				float num = Mathf.Lerp(0.2f, 0.8f, Mathf.Clamp01(relativeVelocity.magnitude / 2.5f));
				Vector3 velocity = num * Vector3.Reflect(relativeVelocity, base.transform.forward);
				Vector3 angularVelocity = rigidbodyEx.angularVelocity;
				Vector3 angularVelocity2 = num * Vector3.Reflect(angularVelocity, base.transform.right);
				rigidbodyEx.velocity = velocity;
				rigidbodyEx.angularVelocity = angularVelocity2;
			}
		}
	}
	public class PoolTablePocket : Photon.MonoBehaviour
	{
		[SerializeField]
		private RecRoomAudioClip audioClip;

		[SerializeField]
		private float speedForFullVolume;

		[SerializeField]
		private Transform ballDropPoint;

		[SerializeField]
		private Transform cueBallDropPoint;

		private const float DROP_LINEAR_VELOCITY = 0.5f;

		private const float DROP_ANGULAR_VELOCITY = 100f;

		private void OnTriggerEnter(Collider other)
		{
			if (other.CompareTag("Pool/Ball"))
			{
				float volumeScaler = Mathf.Clamp01(other.attachedRigidbody.velocity.magnitude / Mathf.Max(0.01f, speedForFullVolume));
				AudioManager.Play3DSFX(audioClip.audioClip, other.transform.position, audioClip.volume, audioClip.pitchVariation, audioClip.pitchShift, null, volumeScaler);
				if (PhotonNetwork.isMasterClient)
				{
					PoolBall componentInParent = other.gameObject.GetComponentInParent<PoolBall>();
					Transform transform = ((!componentInParent.IsCueBall) ? ballDropPoint : cueBallDropPoint);
					componentInParent.Tool.RigidbodyEx.SetDiscontinuousPositionAndRotation(transform.position, Quaternion.identity);
					componentInParent.Tool.RigidbodyEx.ResetVelocityWorldSpace(0.5f * transform.forward, 100f * transform.right);
				}
			}
		}
	}
}
public class AdjustablePodiumPickup : RigidbodyPickup
{
	[SerializeField]
	private float localMinYOffset = -0.9f;

	[SerializeField]
	private float localMaxYOffset;

	private float yOffset;

	[SerializeField]
	private Transform podiumRoot;

	public float YOffset => yOffset;

	public override Vector3 TargetPosition
	{
		get
		{
			if (!IsPickedUp || podiumRoot == null)
			{
				return base.TargetPosition;
			}
			Vector3 position = podiumRoot.InverseTransformPoint(base.TargetPosition);
			float y = podiumRoot.InverseTransformPoint(base.TargetPosition).y;
			yOffset = Mathf.Clamp(y, localMinYOffset, localMaxYOffset);
			position.y = yOffset;
			position.x = 0f;
			position.z = 0f;
			return podiumRoot.TransformPoint(position);
		}
	}

	public override Quaternion TargetRotation => podiumRoot.transform.rotation;

	protected override void Awake()
	{
		base.Awake();
		object token = new object();
		rigidbodyEx.AddKinematic(token);
	}
}
