		GameManager.EnableLocalPlayerToolRestrictionEvent += EnableLocalPlayerToolRestrictions;
		GameManager.OnPlayerTeamChangeEvent += OnTeamChange;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		GameManager.InitializeLocalPlayerEvent += InitializeLocalPlayer;
		GameManager.ResetLocalPlayerEvent += ResetLocalPlayer;
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		if (guessButton == null)
		{
			CharadesPhysicalButton[] array = UnityEngine.Object.FindObjectsOfType<CharadesPhysicalButton>();
			if (array.Length == 0)
			{
				throw new InvalidOperationException("Need a Guess button!");
			}
			if (array.Length > 1)
			{
				throw new InvalidOperationException("Too many guess buttons!");
			}
			guessButton = array[0];
			if (guessButton == null)
			{
				throw new Exception("WE NEED A GUESS BUTTON!");
			}
		}
		charadesStateMachine = new SynchronizedStateMachine("CHARADES", SetterPermissionMode.MASTER);
		charadesStateMachine.AddState(ushort.MaxValue, null, null, null);
		charadesStateMachine.AddState(0, OnEnterCoopGameStartState, null, OnUpdateCoopGameStartState);
		charadesStateMachine.AddState(1, OnEnterCoopSelectPerformerState, null, OnUpdateCoopSelectPerformerState);
		charadesStateMachine.AddState(2, OnEnterCoopPerformerRoundStartState, null, OnUpdateCoopPerformerRoundStartState);
		charadesStateMachine.AddState(3, OnEnterCoopPerformerRoundRunningState, OnExitCoopPerformerRoundRunningState, OnUpdateCoopPerformerRoundRunningState);
		charadesStateMachine.AddState(4, OnEnterCoopPostPerformerRoundState, OnExitCoopPostPerformerRoundState, OnUpdateCoopPostPerformerRoundState);
		charadesStateMachine.AddState(5, OnEnterTeamGameStartState, null, OnUpdateTeamGameStartState);
		charadesStateMachine.AddState(6, OnEnterTeamSelectPerformerState, null, OnUpdateTeamSelectPerformerState);
		charadesStateMachine.AddState(7, OnEnterTeamPerformerRoundStartState, null, OnUpdateTeamPerformerRoundStartState);
		charadesStateMachine.AddState(8, OnEnterTeamPerformerRoundRunningState, OnExitTeamPerformerRoundRunningState, OnUpdateTeamPerformerRoundRunningState);
		charadesStateMachine.AddState(9, OnEnterSwitchPerformingTeamState, OnExitSwitchPerformingTeamState, OnUpdateSwitchPerformingTeamState);
		charadesStateMachine.AddState(10, OnEnterTeamGameEndState, null, OnUpdateTeamGameEndState);
		masterCharadesStateTimer = new SynchronizedTimer(this, "CHARADES_TIMER", SetterPermissionMode.MASTER);
		_performerTeamPlayerIndexId = new SynchronizedField<GameTeamPlayerIndex>(this, "PERFORMER_TEAM_PLAYER_INDEX", GameTeamPlayerIndex.ANY_INDEX, SetterPermissionMode.MASTER, OnPerformerIdChange);
		_currentTeamIndex = new SynchronizedField<GameTeam>(this, "CURRENT_TEAM_INDEX", GameTeam.ANY, SetterPermissionMode.MASTER, OnPerformerIdChange);
		_currentTeamRound = new SynchronizedField<int>(this, "CURRENT_TEAM_ROUND", 0, SetterPermissionMode.MASTER, OnTeamRoundNumberChange);
		_teamOneLastPerformerIndex = new SynchronizedField<GameTeamPlayerIndex>(this, "TEAM_ONE_LAST_PERFORMER_INDEX", GameTeamPlayerIndex.ANY_INDEX, SetterPermissionMode.MASTER);
		_teamTwoLastPerformerIndex = new SynchronizedField<GameTeamPlayerIndex>(this, "TEAM_TWO_LAST_PERFORMER_INDEX", GameTeamPlayerIndex.ANY_INDEX, SetterPermissionMode.MASTER);
		allCharadesPens = this.FindAllObjectsOfType<CharadesPen>();
		for (int i = 0; i < allCharadesPens.Count; i++)
		{
			if (allCharadesPens[i].GetComponent<GamePracticeObject>() == null)
			{
				if (gameCharadesPen == null)
				{
					gameCharadesPen = allCharadesPens[i];
				}
				else
				{
					UnityEngine.Debug.LogError("There is more than one gameplay extruder in the scene.  Only one is supported.  Please remove extras.");
				}
			}
		}
		if (gameCharadesPen == null)
		{
			UnityEngine.Debug.LogError("No non-practice extruder tools in Charades scene.");
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolRestrictedByTeamPlayerIndex = true;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolRestrictedByTeam = true;
		colorButton = guessButton.GetComponent<ColorButton>();
		defaultButtonColor = colorButton.Color;
		guessButton.pressEvent.AddListener(OnGuessButtonPush);
		roundTimerVisual = this.FindAllObjectsOfType<CharadesRoundTimer>()[0];
		cardBox = this.FindAllObjectsOfType<CardBox>()[0];
		podiums = this.FindAllObjectsOfType<CharadesPodium>();
		ClearPodiums();
		Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawned);
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void Start()
	{
		base.Start();
		charadesStateMachine.Start(this, ushort.MaxValue);
		if (gameCharadesPen != null)
		{
			gameCharadesPen.Tool.AddCustomPickupCondition(CustomGameplayPickupCondition);
			customPickupConditionTools.Add(gameCharadesPen.Tool);
		}
		if (cardBox.Cards == null)
		{
			return;
		}
		for (int i = 0; i < cardBox.Cards.Count; i++)
		{
			if (cardBox.Cards[i] != null)
			{
				cardBox.Cards[i].Tool.AddCustomPickupCondition(CustomGameplayPickupCondition);
				customPickupConditionTools.Add(cardBox.Cards[i].Tool);
			}
		}
	}

	private void TestForPodiumSpawnPoints()
	{
		foreach (CharadesPodium podium in podiums)
		{
			CharadesPodium.PodiumConfiguration[] podiumConfig = podium.GetPodiumConfig();
			GameSpawnPoint[] componentsInChildren = podium.GetComponentsInChildren<GameSpawnPoint>();
			bool flag = false;
			GameSpawnPoint[] array = componentsInChildren;
			foreach (GameSpawnPoint gameSpawnPoint in array)
			{
				for (int j = 0; j < podiumConfig.Length; j++)
				{
					if (gameSpawnPoint.SupportsGameMode((GameModeType)podiumConfig[j].Mode) && gameSpawnPoint.GameTeam == podiumConfig[j].Team && gameSpawnPoint.GameTeamPlayerIndex == podiumConfig[j].TeamPlayerIndex)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					UnityEngine.Debug.LogError("Spawn point " + gameSpawnPoint.gameObject.name + " on " + podium.gameObject.name + " doesn't match current podium player settings");
				}
			}
		}
	}

	private void OnLocalPlayerRespawned()
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.GetLocalPlayerSpawnPointTag() == SpawnPointTagType.TAG_2 && gameCharadesPen != null)
		{
			base.photonView.RpcMaster(RpcMasterRequestGameplayExtruder);
		}
		localPlayerRespawning = false;
	}

	protected void Update()
	{
		charadesStateMachine.Update();
		masterCharadesStateTimer.UpdateCallbacks();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		ResetLocalPlayerToolRestrictionsOnDestroy();
		foreach (Tool customPickupConditionTool in customPickupConditionTools)
		{
			if (customPickupConditionTool != null)
			{
				customPickupConditionTool.RemoveCustomPickupCondition(CustomGameplayPickupCondition);
			}
		}
		guessButton.pressEvent.RemoveListener(OnGuessButtonPush);
		Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawned);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent -= EnableLocalPlayerToolRestrictions;
		GameManager.OnPlayerTeamChangeEvent -= OnTeamChange;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
		GameManager.InitializeLocalPlayerEvent -= InitializeLocalPlayer;
		GameManager.ResetLocalPlayerEvent -= ResetLocalPlayer;
	}

	protected void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
			{
				charadesStateMachine.EnterState(0);
			}
			else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
			{
				charadesStateMachine.EnterState(5);
			}
		}
		AuthorityDestroyExtrusions();
		ClearPodiums();
		UpdatePodiums();
	}

	protected void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			charadesStateMachine.EnterState(ushort.MaxValue);
			MasterDisableGameplayExtruders();
		}
		AuthorityDestroyExtrusions();
		colorButton.Color = defaultButtonColor;
		ClearPodiums();
		UpdateLocalPlayerCardVisibility(forceVisible: true);
	}

	protected void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoiningInProgress)
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolSupportedTeamPlayerIndex = GameTeamPlayerIndex.ANY_INDEX;
		if (!localPlayerIsSpectator)
		{
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_1);
		}
		UpdateLocalPlayerCardVisibility();
	}

	protected void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.DEFAULT);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.DEFAULT);
		}
	}

	protected void InitializeSceneOnPreGame()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisableGameplayExtruders();
		}
		AuthorityDestroyExtrusions();
	}

	private void MasterDisableGameplayExtruders()
	{
		if (gameCharadesPen != null)
		{
			gameCharadesPen.Tool.Disable();
		}
	}

	[PunRPC]
	private void RpcMasterRequestGameplayExtruder(PhotonMessageInfo messageInfo)
	{
		PhotonPlayer sender = messageInfo.sender;
		if (PhotonNetwork.isMasterClient && sender != null && IsPlayerPerforming(sender))
		{
			base.photonView.RpcPlayer(sender, RpcPickupGameplayExtruder);
		}
	}

	[PunRPC]
	private void RpcPickupGameplayExtruder()
	{
		PlayerHand dominantHand = Player.LocalPlayer.DominantHand;
		if (gameCharadesPen != null && dominantHand != null)
		{
			gameCharadesPen.Tool.LocalTakeOwnershipAndResetToDefault(dominantHand.transform.position, dominantHand.transform.rotation);
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			if (playerTeam != GameTeam.ANY)
			{
				gameCharadesPen.SelectedColor = TEAM_COLORS[(int)playerTeam];
			}
			dominantHand.TryPickupTool(gameCharadesPen.Tool, inPhysicalPickupRange: false);
		}
	}

	protected void OnTeamChange(PhotonPlayer changingTeamPlayer)
	{
		UpdatePodiums();
		SetPersistentTeamFeedback();
	}

	private void UpdateButtonColor()
	{
		if (CurrentPerformingTeam == GameTeam.ANY)
		{
			colorButton.Color = defaultButtonColor;
		}
		else
		{
			colorButton.Color = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(CurrentPerformingTeam);
		}
	}

	private void AuthorityDestroyExtrusions()
	{
		if (allCharadesPens != null)
		{
			for (int i = 0; i < allCharadesPens.Count; i++)
			{
				CharadesPen charadesPen = allCharadesPens[i];
				if (charadesPen.hasAuthority && charadesPen.CreationContext != null)
				{
					charadesPen.CreationContext.ShapeCreationContext.DeselectShapeContainer();
				}
			}
		}
		List<StandaloneShapeContainer> list = new List<StandaloneShapeContainer>();
		foreach (ShapeContainer allShapeContainer in ShapeContainer.AllShapeContainers)
		{
			StandaloneShapeContainer standaloneShapeContainer = allShapeContainer as StandaloneShapeContainer;
			if (standaloneShapeContainer != null && standaloneShapeContainer.hasAuthority)
			{
				list.Add(standaloneShapeContainer);
			}
		}
		foreach (StandaloneShapeContainer item in list)
		{
			item.CreationObject.RequestMasterDespawn();
		}
	}

