	private void PlayNewPerformerNotification()
	{
		PhotonPlayer playerAtTeamPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerAtTeamPlayerIndex(CurrentPerformingTeam, PerformerPlayerIndex);
		if (playerAtTeamPlayerIndex != null)
		{
			if (playerAtTeamPlayerIndex.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Your Turn!", 2f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, playerAtTeamPlayerIndex.NickName + "'s Turn!", 2f);
			}
		}
	}

	private void OnEnterCoopPerformerRoundStartState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterCharadesStateTimer.StartTimer(5f);
			foreach (ShapeContainer allShapeContainer in ShapeContainer.AllShapeContainers)
			{
				StandaloneShapeContainer standaloneShapeContainer = allShapeContainer as StandaloneShapeContainer;
				if (standaloneShapeContainer != null)
				{
					standaloneShapeContainer.Tool.MasterResetToLastPickup();
				}
			}
			cardBox.MasterClearCards();
		}
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && IsPlayerPerforming(PhotonNetwork.player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_2);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_2);
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
		}
		UpdateLocalPlayerCardVisibility();
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining > coopMaxPerformerRoundRunningDuration)
		{
			roundTimerVisual.Timer = coopMaxPerformerRoundRunningDuration;
		}
		else
		{
			roundTimerVisual.Timer = NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining;
		}
	}

