				if (standaloneShapeContainer != null)
				{
					standaloneShapeContainer.Tool.MasterResetToLastPickup();
				}
			}
			cardBox.MasterClearCards();
		}
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && IsPlayerPerforming(PhotonNetwork.player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_2);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_2);
