	{
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			charadesStateMachine.EnterState(8);
		}
	}

	private void CheckOutOfBounds()
	{
		if (Player.LocalPlayerExists && Player.LocalPlayer.IsOutOfWorldBounds && !localPlayerRespawning)
		{
			if (outOfBoundsStartTime == 0f)
			{
				outOfBoundsStartTime = UnityEngine.Time.time;
			}
			else if (UnityEngine.Time.time - outOfBoundsStartTime > maxTimeOutOfBounds)
			{
				outOfBoundsStartTime = 0f;
				localPlayerRespawning = true;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
			}
		}
		else
		{
			outOfBoundsStartTime = 0f;
		}
	}

	private void OnEnterCoopPerformerRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining > coopMaxPerformerRoundRunningDuration)
			{
				masterCharadesStateTimer.StartTimer(coopMaxPerformerRoundRunningDuration);
			}
			else
			{
				masterCharadesStateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining);
			}
		}
		if (timerTickLoop == null)
		{
			timerTickLoop = AudioManager.StartLooping3DSFX(timerTickLoopClip, roundTimerVisual.transform);
		}
		roundTimerVisual.Timer = masterCharadesStateTimer.TimeRemaining;
	}

	private void OnUpdateCoopPerformerRoundRunningState()
	{
		roundTimerVisual.Timer = masterCharadesStateTimer.TimeRemaining;
		CheckOutOfBounds();
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			base.photonView.RpcAll(RpcOnTimerExpired);
			charadesStateMachine.EnterState(4);
		}
	}

	private void OnExitCoopPerformerRoundRunningState(ushort nextStateId, ushort nextSubStateId)
	{
		StopTickTimer();
	}

	private void OnEnterTeamPerformerRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining > teamMaxPerformerRoundRunningDuration)
			{
				masterCharadesStateTimer.StartTimer(teamMaxPerformerRoundRunningDuration);
			}
			else
			{
				masterCharadesStateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining);
			}
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Resume();
		}
		if (timerTickLoop == null)
		{
			timerTickLoop = AudioManager.StartLooping3DSFX(timerTickLoopClip, roundTimerVisual.transform);
		}
		roundTimerVisual.Timer = masterCharadesStateTimer.TimeRemaining;
	}

	private void OnUpdateTeamPerformerRoundRunningState()
	{
		roundTimerVisual.Timer = masterCharadesStateTimer.TimeRemaining;
		CheckOutOfBounds();
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			base.photonView.RpcAll(RpcOnTimerExpired);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeRemaining < 1f)
			{
				charadesStateMachine.EnterState(9);
			}
			else
			{
				charadesStateMachine.EnterState(6);
			}
		}
	}

	private void OnExitTeamPerformerRoundRunningState(ushort nextStateId, ushort nextSubStateId)
	{
		StopTickTimer();
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
		ResetPerformer();
	}

