	{
		if (PhotonNetwork.isMasterClient)
		{
			masterCharadesStateTimer.StartTimer(2f);
		}
	}

	private void OnExitCoopPostPerformerRoundState(ushort nextStateId, ushort nextSubStateId)
	{
		ResetPerformer();
	}

	private void OnUpdateCoopPostPerformerRoundState()
	{
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			charadesStateMachine.EnterState(1);
		}
	}

	private void OnEnterSwitchPerformingTeamState(ushort previousStateId, ushort previousSubStateId)
	{
		ResetPerformer();
		if (PhotonNetwork.isMasterClient)
		{
			masterCharadesStateTimer.StartTimer(5f);
			if (CurrentPerformingTeam == GameTeam.TEAM_1)
			{
				TeamOneLastPerformerIndex = PerformerPlayerIndex;
				CurrentPerformingTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(CurrentPerformingTeam);
				PerformerPlayerIndex = TeamTwoLastPerformerIndex;
			}
			else if (CurrentPerformingTeam == GameTeam.TEAM_2)
			{
				TeamTwoLastPerformerIndex = PerformerPlayerIndex;
				CurrentPerformingTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(CurrentPerformingTeam);
				PerformerPlayerIndex = TeamOneLastPerformerIndex;
			}
			else if (CurrentPerformingTeam == GameTeam.ANY)
			{
				CurrentPerformingTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(CurrentPerformingTeam);
			}
			CurrentTeamRoundNumber++;
		}
	}

	private void OnUpdateSwitchPerformingTeamState()
	{
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			charadesStateMachine.EnterState(6);
		}
	}

	private void OnExitSwitchPerformingTeamState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.MasterStartTimer();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
		}
	}

	private void UpdateSwitchTeamFeedback()
	{
		if (CurrentPerformingTeam != GameTeam.ANY)
		{
			SetPersistentTeamFeedback();
			if (CurrentPerformingTeam == GameTeam.TEAM_1)
			{
				AudioManager.Play2DSFX(blueTeamJoinVO);
			}
			else if (CurrentPerformingTeam == GameTeam.TEAM_2)
			{
				AudioManager.Play2DSFX(redTeamJoinVO);
			}
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(CurrentPerformingTeam) + "'s Turn!", "(Round " + CurrentTeamRoundNumber + " of " + numberOfTeamRounds + ")", 2.5f);
		}
	}

	private void SetPersistentTeamFeedback()
	{
		if (CurrentPerformingTeam != GameTeam.ANY)
		{
			UpdateButtonColor();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(CurrentPerformingTeam) + "'s Turn (Round " + CurrentTeamRoundNumber + " of " + numberOfTeamRounds + ")";
		}
	}

	private void OnEnterTeamGameEndState(ushort previousStateId, ushort previousSubStateId)
	{
		ResetPerformer();
		masterCharadesStateTimer.StartTimer(1f);
	}

	private void OnUpdateTeamGameEndState()
	{
		if (PhotonNetwork.isMasterClient && masterCharadesStateTimer.TimerOver)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
		}
	}

	public bool IsPlayerPerforming(PhotonPlayer player)
	{
		return NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerIndex(player) == PerformerPlayerIndex && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player) == CurrentPerformingTeam;
	}

	private void ResetPerformer()
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolSupportedTeamPlayerIndex = GameTeamPlayerIndex.ANY_INDEX;
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && IsPlayerPerforming(PhotonNetwork.player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_1);
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
		}
	}

	private void OnPerformerIdChange()
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolSupportedTeamPlayerIndex = PerformerPlayerIndex;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnToolSupportedTeam = CurrentPerformingTeam;
		AuthorityDestroyExtrusions();
		guessButton.ClearAllPressers();
		gameCharadesPen.AuthorityResetToDefaults();
	}

	private void MasterIncrementPerformerPlayerIndex()
	{
		GameTeamPlayerIndex performerPlayerIndex = PerformerPlayerIndex;
		PhotonPlayer[] teamPlayersSortedByIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayersSortedByIndex(CurrentPerformingTeam);
		for (int i = 0; i < teamPlayersSortedByIndex.Length; i++)
		{
			GameTeamPlayerIndex teamPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerIndex(teamPlayersSortedByIndex[i]);
			if (teamPlayerIndex > performerPlayerIndex)
			{
				PerformerPlayerIndex = teamPlayerIndex;
				return;
			}
		}
		PerformerPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerIndex(teamPlayersSortedByIndex[0]);
	}

	private void UpdateLocalPlayerCardVisibility(bool forceVisible = false)
	{
		cardBox.UpdateLocalPlayerCardVisibility(IsPlayerPerforming(PhotonNetwork.player) || forceVisible);
	}

	private void OnGuessButtonPush(PhysicalButtonBase button, Player buttonPusher)
	{
		if (buttonPusher.PhotonPlayer.IsLocal && IsValidGuess(buttonPusher.PhotonPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestGuess);
		}
	}

	[PunRPC]
	private void RpcMasterRequestGuess(PhotonMessageInfo messageInfo)
	{
		PhotonPlayer sender = messageInfo.sender;
		if (!PhotonNetwork.isMasterClient || sender == null || !IsValidGuess(sender))
		{
			return;
		}
		base.photonView.RpcAll(RpcOnGuess, sender);
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
		{
			GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
			for (int i = 0; i < activeTeams.Length; i++)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(activeTeams[i], 1);
			}
			charadesStateMachine.EnterState(4);
		}
		else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(sender), 1);
			charadesStateMachine.EnterState(6);
		}
	}

	[PunRPC]
	private void RpcOnGuess(PhotonPlayer performer)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Score!", "The word was: " + cardBox.PreviousWord, 3f);
		}
		else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(performer)) + " Scores!", "The word was: " + cardBox.PreviousWord, 3f);
		}
		AudioManager.Play3DSFX(successClip, guessButton.transform.position);
	}

	[PunRPC]
	private void RpcOnTimerExpired()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Time's up!", "The word was: " + cardBox.PreviousWord, 3f);
		AudioManager.Play3DSFX(timerExpiredClip, roundTimerVisual.transform.position);
	}

	private bool IsValidGuess(PhotonPlayer guesser)
	{
		return IsPlayerPerforming(guesser) && IsPerformerRoundRunning();
	}

	private bool ShouldSkipPerformerRoundRunning()
	{
		return charadesStateMachine.CurrentStateId == 1 || charadesStateMachine.CurrentStateId == 2 || charadesStateMachine.CurrentStateId == 7 || IsPerformerRoundRunning();
	}

	private bool IsPerformerRoundRunning()
	{
		return charadesStateMachine.CurrentStateId == 3 || charadesStateMachine.CurrentStateId == 8;
	}

	private void OnTeamRoundNumberChange()
	{
		if (CurrentTeamRoundNumber > numberOfTeamRounds)
		{
			charadesStateMachine.EnterState(10);
		}
		else if (CurrentTeamRoundNumber != 0)
		{
			Invoke("UpdateSwitchTeamFeedback", 3f);
		}
	}

	public void UpdatePodiums()
	{
		for (int i = 0; i < podiums.Count; i++)
		{
			PhotonPlayer playerAtTeamPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerAtTeamPlayerIndex(podiums[i].GetTeam((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType), podiums[i].GetPlayerIndex((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType));
			if (playerAtTeamPlayerIndex == null)
			{
				podiums[i].ClearPlayerName();
			}
			else
			{
				podiums[i].SetPlayerName(playerAtTeamPlayerIndex.NickName);
			}
			podiums[i].SetPodiumColor((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType);
		}
	}

	public void ClearPodiums()
	{
		for (int i = 0; i < podiums.Count; i++)
		{
			podiums[i].SetPodiumColor((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType);
			podiums[i].ClearPlayerName();
		}
	}

	private void ResetLocalPlayerToolRestrictionsOnDestroy()
	{
		if (cardBox.Cards != null)
		{
			for (int i = 0; i < cardBox.Cards.Count; i++)
			{
				if (cardBox.Cards[i] != null)
				{
					cardBox.Cards[i].Tool.SetPickupEnabled(enabled: true, this);
				}
			}
		}
		if (gameCharadesPen != null)
		{
			gameCharadesPen.Tool.SetPickupEnabled(enabled: true, this);
		}
		for (int j = 0; j < podiums.Count; j++)
		{
			if (podiums[j].PodiumHandleTool != null)
			{
				podiums[j].PodiumHandleTool.SetPickupEnabled(enabled: true, this);
			}
		}
	}

	protected void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
	{
		if (cardBox.Cards != null)
		{
			for (int i = 0; i < cardBox.Cards.Count; i++)
			{
				if (cardBox.Cards[i] != null)
				{
					cardBox.Cards[i].Tool.SetPickupEnabled(pickupEnabled, this);
				}
			}
		}
		if (gameCharadesPen != null)
		{
			gameCharadesPen.Tool.SetPickupEnabled(pickupEnabled, this);
		}
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
		GameTeamPlayerIndex teamPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerIndex(PhotonNetwork.player);
		for (int j = 0; j < podiums.Count; j++)
		{
			if (podiums[j].PodiumHandleTool != null)
			{
				GameTeam team = podiums[j].GetTeam((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType);
				GameTeamPlayerIndex playerIndex = podiums[j].GetPlayerIndex((int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType);
				podiums[j].PodiumHandleTool.SetPickupEnabled(playerTeam == team && teamPlayerIndex == playerIndex, this);
			}
		}
	}

	private bool CustomGameplayPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		return !NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning || IsPlayerPerforming(selectingPlayer.PhotonPlayer);
	}

	protected void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		UpdatePodiums();
		if (PhotonNetwork.isMasterClient && IsPlayerPerforming(player) && ShouldSkipPerformerRoundRunning())
		{
			base.photonView.RpcAll(RpcOnTimerExpired);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
			{
				charadesStateMachine.EnterState(4);
			}
			else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
			{
				charadesStateMachine.EnterState(6);
			}
		}
	}

	private void StopTickTimer()
	{
		if (timerTickLoop != null)
		{
			timerTickLoop.Stop();
			timerTickLoop = null;
		}
	}
}
