public class PhysicsButtonVisual : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float releaseSpeed = 0.5f;

	[SerializeField]
	private float pressSpeed = 10f;

	[SerializeField]
	private Transform unpressedTransform;

	[SerializeField]
	private Transform pressedTransform;

	private Rigidbody rigidbody;

	private Vector3 buttonDownDirection;

	private float pressedTime;

	private float unpressedTime;

	private Collider buttonCollider;

	[SerializeField]
	private PhysicalButtonBase parentButton;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		buttonCollider = GetComponent<Collider>();
		buttonDownDirection = (pressedTransform.position - unpressedTransform.position).normalized;
		rigidbody.position = unpressedTransform.position;
		rigidbody.velocity = Vector3.zero;
	}

	private void FixedUpdate()
	{
		Collider collider = null;
		PhotonPlayer somePressingPlayer = parentButton.GetSomePressingPlayer(out collider);
		if (collider != null)
		{
			Vector3 direction = Vector3.zero;
			if (Physics.ComputePenetration(buttonCollider, base.transform.position, base.transform.rotation, collider, collider.gameObject.transform.position, collider.gameObject.transform.rotation, out direction, out var distance))
			{
				Vector3 b = Vector3.Project(distance * direction, buttonDownDirection);
				if (Vector3Ext.SqDistance(rigidbody.position, b) > Vector3Ext.SqDistance(rigidbody.position, pressedTransform.position))
				{
					b = pressedTransform.position;
				}
				rigidbody.position = Vector3.Lerp(rigidbody.position, b, pressedTime);
				rigidbody.rotation = pressedTransform.rotation;
				pressedTime += UnityEngine.Time.deltaTime * pressSpeed;
				unpressedTime = 0f;
			}
		}
		else if (somePressingPlayer != null)
		{
			rigidbody.position = Vector3.Lerp(rigidbody.position, pressedTransform.position, pressedTime);
			rigidbody.rotation = pressedTransform.rotation;
			pressedTime += UnityEngine.Time.deltaTime * pressSpeed;
			unpressedTime = 0f;
		}
		else
		{
			if (unpressedTransform.position != base.transform.position)
			{
				rigidbody.position = Vector3.Lerp(rigidbody.position, unpressedTransform.position, unpressedTime);
				rigidbody.rotation = unpressedTransform.rotation;
				unpressedTime += UnityEngine.Time.deltaTime * releaseSpeed;
			}
			pressedTime = 0f;
		}
	}
}
