public class DiscGolfBumper : DiscGolfTriggerable
{
	[Header("Bumper")]
	[SerializeField]
	private float bumpForce = 1f;

	[SerializeField]
	private float bumpCooldown = 1.1f;

	[Header("Aim Assist")]
	[SerializeField]
	private bool aimAssisted;

	public Transform AimAssistTarget;

	private float lastBumpTime;

	private CollisionForwarder triggerForwarder;

	protected override void Awake()
	{
		base.Awake();
		triggerForwarder = GetComponentInChildren<CollisionForwarder>();
		if (triggerForwarder != null)
		{
			triggerForwarder.TriggerEnter += OnTriggerEnter;
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		if (!base.Active)
		{
			return;
		}
		DiscGolfDisc componentInParent = other.GetComponentInParent<DiscGolfDisc>();
		if (componentInParent != null && componentInParent.hasAuthority && UnityEngine.Time.time - lastBumpTime > bumpCooldown)
		{
			if (aimAssisted && AimAssistTarget != null)
			{
				float magnitude = (AimAssistTarget.position - componentInParent.transform.position).magnitude;
				float num = 2f * magnitude / DiscGolfDisc.MaxVelocity;
				Vector3 vector = -Physics.gravity * componentInParent.AirLiftModifier;
				Vector3 vector2 = Physics.gravity + vector;
				Vector3 velocity = (AimAssistTarget.position - componentInParent.transform.position) / num - vector2 * num / 2f;
				float num2 = num * componentInParent.Tool.RigidbodyEx.drag;
				velocity += num2 * velocity.normalized;
				componentInParent.transform.rotation = Quaternion.identity;
				componentInParent.Tool.RigidbodyEx.angularVelocity = componentInParent.transform.up * DiscGolfDisc.MaxAngularVelocity;
				componentInParent.Tool.RigidbodyEx.velocity = velocity;
			}
			else
			{
				componentInParent.Tool.RigidbodyEx.AddForce(base.transform.forward * bumpForce, ForceMode.Impulse);
			}
			if (gizmoAnimator != null)
			{
				gizmoAnimator.SetTrigger("Bump");
			}
			lastBumpTime = UnityEngine.Time.time;
		}
	}
}
