public class DiscGolfCheckpoint : Photon.MonoBehaviour
{
	[SerializeField]
	private OverlapVolume[] triggerVolumes;

	[SerializeField]
	private DiscGolfCheckpoint exitCheckpoint;

	private DiscGolfTee[] checkpointTees;

	protected override void Awake()
	{
		base.Awake();
		foreach (DiscGolfDisc item in this.FindAllObjectsOfType<DiscGolfDisc>())
		{
			item.DiscPickupEvent += OnDiscPickup;
		}
		checkpointTees = GetComponentsInChildren<DiscGolfTee>();
	}

	protected override void OnDestroy()
	{
		foreach (DiscGolfDisc item in this.FindAllObjectsOfType<DiscGolfDisc>())
		{
			item.DiscPickupEvent -= OnDiscPickup;
		}
		base.OnDestroy();
	}

	private void OnDiscPickup(DiscGolfDisc disc, PhotonPlayer pickupPlayer, PhotonPlayer throwingPlayer)
	{
		if (triggerVolumes == null)
		{
			return;
		}
		for (int i = 0; i < triggerVolumes.Length; i++)
		{
			if (base.hasAuthority && triggerVolumes[i].ContainsPoint(disc.transform.position))
			{
				disc.CurrentCheckpoint = ((!(exitCheckpoint != null)) ? null : this);
				break;
			}
		}
	}

	public DiscGolfTee GetTeamTee(GameTeam team)
	{
		if (checkpointTees == null)
		{
			return null;
		}
		for (int i = 0; i < checkpointTees.Length; i++)
		{
			if (checkpointTees[i].Team == team)
			{
				return checkpointTees[i];
			}
		}
		return null;
	}
}
