	private float activeTravelTime = 1f;

	[SerializeField]
	private float inactiveTravelTime = 1f;

	private float lastInactiveTime;

	protected override void Update()
	{
		base.Update();
		if (base.Active)
		{
			base.transform.position = Vector3.Lerp(startTransform.position, endTransform.position, (UnityEngine.Time.time - lastTriggerTime) / activeTravelTime);
		}
		else
		{
			base.transform.position = Vector3.Lerp(endTransform.position, startTransform.position, (UnityEngine.Time.time - lastInactiveTime) / inactiveTravelTime);
		}
	}

	protected override void OnActiveChanged()
	{
		base.OnActiveChanged();
		if (!base.Active)
		{
			lastInactiveTime = UnityEngine.Time.time;
		}
	}
}
public class DiscGolfGizmoManager : UnityEngine.MonoBehaviour
{
	private const float GRID_CELL_SIZE = 10f;

	private List<DiscGolfGizmoMotion> gizmos;

	private List<DiscGolfDisc> discs;

	private int countX;

	private int countZ;

	private HashSet<int> previousCells = new HashSet<int>();

	private HashSet<int> currentCells = new HashSet<int>();

	private DiscGolfCell[] cells;

	private float minX;

	private float maxX;

	private float minZ;

	private float maxZ;

	public void Awake()
	{
		gizmos = this.FindAllObjectsOfType<DiscGolfGizmoMotion>();
		discs = this.FindAllObjectsOfType<DiscGolfDisc>();
		CreateGrid();
	}

	public void Start()
	{
		for (int i = 0; i < cells.Length; i++)
		{
			cells[i].IsActive = false;
		}
	}

	public void Update()
	{
		HashSet<int> hashSet = previousCells;
		previousCells = currentCells;
		currentCells = hashSet;
		currentCells.Clear();
		for (int i = 0; i < discs.Count; i++)
		{
			DiscGolfDisc discGolfDisc = discs[i];
			if (!discGolfDisc.Tool.RigidbodyEx.IsSleeping() && FindCell(discGolfDisc.transform.position, out var cellIndex, out var cellX, out var cellZ))
			{
				currentCells.Add(cellIndex);
				int num = CoordinatesToIndex(cellX - 1, cellZ + 1);
				if (num != -1)
				{
					currentCells.Add(num);
				}
				int num2 = CoordinatesToIndex(cellX, cellZ + 1);
				if (num2 != -1)
				{
					currentCells.Add(num2);
				}
				int num3 = CoordinatesToIndex(cellX + 1, cellZ + 1);
				if (num3 != -1)
				{
					currentCells.Add(num3);
				}
				int num4 = CoordinatesToIndex(cellX - 1, cellZ);
				if (num4 != -1)
				{
					currentCells.Add(num4);
				}
				int num5 = CoordinatesToIndex(cellX + 1, cellZ);
				if (num5 != -1)
				{
					currentCells.Add(num5);
				}
				int num6 = CoordinatesToIndex(cellX - 1, cellZ - 1);
				if (num6 != -1)
				{
					currentCells.Add(num6);
				}
				int num7 = CoordinatesToIndex(cellX, cellZ - 1);
				if (num7 != -1)
				{
					currentCells.Add(num7);
				}
				int num8 = CoordinatesToIndex(cellX + 1, cellZ - 1);
				if (num8 != -1)
				{
					currentCells.Add(num8);
				}
			}
		}
		foreach (int previousCell in previousCells)
		{
			if (!currentCells.Contains(previousCell))
			{
				cells[previousCell].IsActive = false;
			}
		}
		foreach (int currentCell in currentCells)
		{
			if (!previousCells.Contains(currentCell))
			{
				cells[currentCell].IsActive = true;
			}
		}
	}

	private void CreateGrid()
	{
		if (gizmos.Count == 0)
		{
			cells = new DiscGolfCell[0];
			return;
		}
		minX = (maxX = gizmos[0].transform.position.x);
		minZ = (maxZ = gizmos[0].transform.position.z);
		for (int i = 1; i < gizmos.Count; i++)
		{
			DiscGolfGizmoMotion discGolfGizmoMotion = gizmos[i];
			minX = Mathf.Min(minX, discGolfGizmoMotion.transform.position.x);
			minZ = Mathf.Min(minZ, discGolfGizmoMotion.transform.position.z);
			maxX = Mathf.Max(maxX, discGolfGizmoMotion.transform.position.x);
			maxZ = Mathf.Max(maxZ, discGolfGizmoMotion.transform.position.z);
		}
		minX -= 10f;
		minZ -= 10f;
		maxX += 10f;
		maxZ += 10f;
		countX = Mathf.CeilToInt((maxX - minX) / 10f);
		countZ = Mathf.CeilToInt((maxZ - minZ) / 10f);
		cells = new DiscGolfCell[countZ * countX];
		for (int j = 0; j < countZ; j++)
		{
			for (int k = 0; k < countX; k++)
			{
				int num = CoordinatesToIndex(k, j);
				DiscGolfCell discGolfCell = new DiscGolfCell();
				cells[num] = discGolfCell;
			}
		}
		for (int l = 0; l < gizmos.Count; l++)
		{
			DiscGolfGizmoMotion discGolfGizmoMotion2 = gizmos[l];
			FindCell(discGolfGizmoMotion2.transform.position, out var cellIndex, out var _, out var _);
			cells[cellIndex].AddGizmo(discGolfGizmoMotion2);
		}
	}

	private bool FindCell(Vector3 position, out int cellIndex, out int cellX, out int cellZ)
	{
		cellIndex = (cellX = (cellZ = -1));
		if (position.x < minX || position.z < minZ || position.x > maxX || position.z > maxZ)
		{
			return false;
		}
		cellX = (int)((position.x - minX) / 10f);
		cellZ = (int)((position.z - minZ) / 10f);
		cellIndex = CoordinatesToIndex(cellX, cellZ);
		return true;
	}

	private int CoordinatesToIndex(int cellX, int cellZ)
	{
		if (cellX < 0 || cellZ < 0 || cellX >= countX || cellZ >= countZ)
		{
			return -1;
		}
		return cellZ * countX + cellX;
	}
}
public class DiscGolfGizmoMotion : Photon.MonoBehaviour
{
	[SerializeField]
	private Vector3 translationFrequency = Vector3.zero;

	[SerializeField]
	private Vector3 translationDisplacement = Vector3.zero;

	[SerializeField]
	private Vector3 localTranslationFrequency = Vector3.zero;

	[SerializeField]
	private Vector3 localTranslationDisplacement = Vector3.zero;

	[SerializeField]
	private Vector3 rotationFrequency = Vector3.zero;

	private Vector3 InitialPosition { get; set; }

	private Vector3 InitialRotation { get; set; }

	protected override void Awake()
	{
		base.Awake();
		InitialPosition = base.transform.position;
		InitialRotation = base.transform.rotation.eulerAngles;
	}

	private void Update()
	{
		UpdateMotion();
	}

	private void UpdateMotion()
	{
		float num = (float)(PhotonNetwork.time % 100000.0);
		float num2 = (float)Math.PI * 2f * num;
		Quaternion quaternion = Quaternion.identity;
		Vector3 vector2;
		Vector3 vector = (vector2 = Vector3.zero);
		if ((translationDisplacement.x > 0.001f && translationFrequency.x > 0.001f) || (translationDisplacement.y > 0.001f && translationFrequency.y > 0.001f) || (translationDisplacement.z > 0.001f && translationFrequency.z > 0.001f))
		{
			float x = translationDisplacement.x * Mathf.Sin(translationFrequency.x * num2);
			float y = translationDisplacement.y * Mathf.Sin(translationFrequency.y * num2);
			float z = translationDisplacement.z * Mathf.Sin(translationFrequency.z * num2);
			vector = new Vector3(x, y, z);
		}
		if ((localTranslationDisplacement.x > 0.001f && localTranslationFrequency.x > 0.001f) || (localTranslationDisplacement.y > 0.001f && localTranslationFrequency.y > 0.001f) || (localTranslationDisplacement.z > 0.001f && localTranslationFrequency.z > 0.001f))
		{
			float x = localTranslationDisplacement.x * Mathf.Sin(localTranslationFrequency.x * num2);
			float y = localTranslationDisplacement.y * Mathf.Sin(localTranslationFrequency.y * num2);
			float z = localTranslationDisplacement.z * Mathf.Sin(localTranslationFrequency.z * num2);
			vector2 = x * base.transform.right + y * base.transform.up + z * base.transform.forward;
		}
		if (rotationFrequency.x > 0.001f || rotationFrequency.y > 0.001f || rotationFrequency.z > 0.001f)
		{
			float x2 = InitialRotation.x + 360f * rotationFrequency.x * num % 360f;
			float y2 = InitialRotation.y + 360f * rotationFrequency.y * num % 360f;
			float z2 = InitialRotation.z + 360f * rotationFrequency.z * num % 360f;
			quaternion = Quaternion.Euler(x2, y2, z2);
		}
		base.transform.position = InitialPosition + vector + vector2;
		if (quaternion != Quaternion.identity)
		{
			base.transform.rotation = quaternion;
		}
	}
}
