	protected override void Awake()
	{
		base.Awake();
		GameManager.OnGameStartEvent += OnGameStart;
		GameManager.OnGameEndEvent += OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent += EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		GameManager.ResetLocalPlayerEvent += ResetLocalPlayer;
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		_currentHoleId = new SynchronizedField<DiscGolfHole>(this, "CURRENT_HOLE_ID", DiscGolfHole.INVALID, SetterPermissionMode.MASTER);
		_firstHoleId = new SynchronizedField<DiscGolfHole>(this, "FIRST_HOLE_ID", DiscGolfHole.INVALID, SetterPermissionMode.MASTER);
		_lastHoleId = new SynchronizedField<DiscGolfHole>(this, "LAST_HOLE_ID", DiscGolfHole.INVALID, SetterPermissionMode.MASTER);
		discGolfStateMachine = new SynchronizedStateMachine("DISC_GOLF", SetterPermissionMode.MASTER);
		discGolfStateMachine.AddState(ushort.MaxValue, null, null, null);
		discGolfStateMachine.AddState(0, OnEnterHoleRunningState, null, OnUpdateHoleRunningState);
		discGolfStateMachine.AddState(1, OnEnterHoleFinishedState, null, OnUpdateHoleFinishedState);
		masterDiscGolfStateTimer = new SynchronizedTimer(this, "DISC_GOLF_TIMER", SetterPermissionMode.MASTER);
		goals = UnityEngine.Object.FindObjectsOfType<DiscGolfGoal>();
		tees = UnityEngine.Object.FindObjectsOfType<DiscGolfTee>();
		allDiscs = this.FindAllObjectsOfType<DiscGolfDisc>();
		for (int i = 0; i < allDiscs.Count; i++)
		{
			DiscGolfDisc discGolfDisc = allDiscs[i];
			discGolfDisc.Tool.SuppressesPlayerMovement = true;
			if (discGolfDisc.GetComponent<GamePracticeObject>() == null)
			{
				discGolfDisc.DiscPickupEvent += OnDiscPickup;
				discGolfDisc.DiscScoreEvent += AuthorityOnDiscScore;
				discGolfDisc.DiscHazardEvent += AuthorityOnDiscHazard;
				discGolfDisc.CollidedWithSolid += OnDiscCollideWithSolid;
				discGolfDisc.DiscThrowEvent += OnDiscThrown;
				discGolfDisc.DiscResetEvent += OnDiscReset;
				gameplayDiscs.Add(discGolfDisc);
			}
		}
		powerups = this.FindAllObjectsOfType<DiscGolfPowerUp>();
		for (int j = 0; j < powerups.Count; j++)
		{
			DiscGolfPowerUp discGolfPowerUp = powerups[j];
			discGolfPowerUp.PickupEvent = (DiscGolfPowerUp.Pickup)Delegate.Combine(discGolfPowerUp.PickupEvent, new DiscGolfPowerUp.Pickup(OnPowerupPickup));
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void Start()
	{
		base.Start();
		foreach (DiscGolfDisc gameplayDisc in gameplayDiscs)
		{
			gameplayDisc.Tool.ToolCleanup.PauseCleanup(this);
		}
		discGolfStateMachine.Start(this, ushort.MaxValue);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		foreach (DiscGolfDisc gameplayDisc in gameplayDiscs)
		{
			if (gameplayDisc != null)
			{
				gameplayDisc.DiscPickupEvent -= OnDiscPickup;
				gameplayDisc.DiscScoreEvent -= AuthorityOnDiscScore;
				gameplayDisc.DiscHazardEvent -= AuthorityOnDiscHazard;
				gameplayDisc.CollidedWithSolid -= OnDiscCollideWithSolid;
				gameplayDisc.DiscThrowEvent -= OnDiscThrown;
				gameplayDisc.DiscResetEvent -= OnDiscReset;
			}
		}
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent -= EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
		GameManager.ResetLocalPlayerEvent -= ResetLocalPlayer;
	}

	protected void Update()
	{
		discGolfStateMachine.Update();
		masterDiscGolfStateTimer.UpdateCallbacks();
	}

	protected void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			FirstHole = firstHole;
			LastHole = lastHole;
			CurrentHole = firstHole;
			discGolfStateMachine.EnterState(0);
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
		{
			PlayerHand[] array = UnityEngine.Object.FindObjectsOfType<PlayerHand>();
			foreach (PlayerHand playerHand in array)
			{
				playerHand.GravityPickupCapsuleLength = gravityPickupDistanceOverride;
			}
			foreach (DiscGolfDisc gameplayDisc in gameplayDiscs)
			{
				gameplayDisc.Tool.SkinMapper.SetDefaultSkinOverride(discSkinOverride);
				gameplayDisc.UpdateTeamColor();
			}
		}
		DiscGolfPowerUp[] array2 = UnityEngine.Object.FindObjectsOfType<DiscGolfPowerUp>();
		foreach (DiscGolfPowerUp discGolfPowerUp in array2)
		{
			discGolfPowerUp.LocalEnabled = discGolfPowerUp.IsEnabled;
		}
		GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
		foreach (GameTeam key in activeTeams)
		{
			lastStrokeIncrementTimes[key] = 0f;
		}
	}

	protected void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			discGolfStateMachine.EnterState(ushort.MaxValue);
		}
	}

