	private void AuthorityOnDiscScore(DiscGolfDisc disc, DiscGolfGoal goal, PhotonPlayer thrower)
	{
		if (disc.hasAuthority && IsValidScore(disc, goal, thrower))
		{
			base.photonView.RpcMaster(RpcMasterFinishHole, disc, goal, thrower, arg4: false);
			StartCoroutine(WaitForMasterGoalConfirmation());
		}
	}

	private IEnumerator WaitForMasterGoalConfirmation()
	{
		waitingForMasterGoalConfirmation = true;
		yield return new WaitForSeconds(2f);
		waitingForMasterGoalConfirmation = false;
	}

	private void OnDiscPickup(DiscGolfDisc disc, PhotonPlayer pickupPlayer, PhotonPlayer lastThrower)
	{
		if (IsValidThrow(disc, pickupPlayer))
		{
			int teamStroke = GetTeamStroke(disc.Team);
			bool flag = IncrementTeamStroke(disc, pickupPlayer);
			if (PhotonNetwork.isMasterClient)
			{
				RaycastHit hitInfo;
				Vector3 anchorPoint = ((!Physics.Raycast(disc.transform.position, Vector3.down, out hitInfo, 20f, 2048)) ? disc.transform.position : (hitInfo.point + Vector3.up * 0.05f));
				StartCoroutine(DelayedSetTeamAnchorPoint(disc.Team, anchorPoint));
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(pickupPlayer) == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player))
			{
				int num = GetTeamStroke(disc.Team);
				if (teamStroke == num && flag)
				{
					num++;
				}
				PlayLocalDiscPickupFeedback(disc, pickupPlayer, lastThrower, num);
				if (disc.hasAuthority && lastThrower != null && lastThrower != pickupPlayer)
				{
					float magnitude = (disc.LastReleasePosition - disc.SyncedLastPickupPosition).magnitude;
					base.photonView.RpcAll(RpcPlaySyncedDiscPickupFeedback, disc.transform.position, magnitude);
				}
			}
		}
		RestrictedEnableDiscPickup(disc);
	}

	private void PlayLocalDiscPickupFeedback(DiscGolfDisc disc, PhotonPlayer pickupPlayer, PhotonPlayer throwingPlayer, int strokeCount)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2 && throwingPlayer != null && throwingPlayer != pickupPlayer)
		{
			AudioManager.Play2DSFX(catchSFX);
			PooledParticle.TryPlayPrefab(catchVFXPrefab, disc.transform.position);
		}
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Stroke " + strokeCount, 1.5f);
	}

	[PunRPC]
	private void RpcPlaySyncedDiscPickupFeedback(Vector3 notificationPosition, float catchDistance)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_2)
		{
			Vector3 vector = Vector3.up * 0.35f;
			float magnitude = (notificationPosition - Player.LocalPlayer.Head.transform.position).magnitude;
			float scaleOverride = 1f + ((!(magnitude > catchNotificationDistanceBeforeScaling)) ? 0f : ((magnitude - catchNotificationDistanceBeforeScaling) / catchNotificationMetersPerScaleFactor));
			WorldSpaceNotification.PlayNext("Catch!", 3f, catchDistance.ToString("F1") + "m", followPlayer: false, notificationPosition + vector, scaleOverride, billboard: true);
		}
	}

	public void LocalVoluntaryHazard(PhotonPlayer player)
	{
		if (!player.IsLocal)
		{
			return;
		}
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player);
		DiscGolfDisc teamDisc = GetTeamDisc(playerTeam);
		if (teamDisc != null && IsValidThrow(teamDisc, player) && !teamDisc.Tool.IsHeld)
		{
			teamDisc.photonView.TransferOwnership(player.ID);
			if (teamDisc.hasAuthority)
			{
				AuthorityOnDiscHazard(teamDisc, null, player);
			}
		}
	}

	private IEnumerator DelayedAuthorityOnDiscHazard(DiscGolfDisc disc, Killzone hazard, PhotonPlayer throwPlayer)
	{
		yield return new WaitForSeconds(0.5f);
		AuthorityOnDiscHazard(disc, hazard, throwPlayer);
	}

	private void AuthorityOnDiscHazard(DiscGolfDisc disc, Killzone hazard, PhotonPlayer throwPlayer)
	{
		if (disc.hasAuthority && IsValidThrow(disc, throwPlayer) && !disc.Hazarded && !disc.Tool.IsHeld && !waitingForMasterGoalConfirmation)
		{
			disc.Hazarded = true;
			base.photonView.RpcAll(RpcOnDiscHazard, disc, throwPlayer);
		}
	}

	private IEnumerator DelayedReenableDisc(DiscGolfDisc disc)
	{
		yield return new WaitForSeconds(0.5f);
		disc.Tool.AuthorityDisableAndMove(GetTeamAnchorPoint(disc.Team), Quaternion.identity);
		disc.Tool.IsEnabled = true;
		RestrictedEnableDiscPickup(disc);
	}

	[PunRPC]
	private void RpcOnDiscHazard(DiscGolfDisc disc, PhotonPlayer thrower)
	{
		if (disc != null)
		{
			if (PhotonNetwork.isMasterClient)
			{
				IncrementTeamStroke(disc, thrower, checkDistance: false);
			}
			disc.Tool.AuthorityDisableAndMove(GetTeamAnchorPoint(disc.Team), Quaternion.identity);
			if (disc.Tool.hasAuthority)
			{
				disc.Tool.photonView.RPC("RpcOnReset", PhotonTargets.All, disc.SyncedLastPickupPosition, Quaternion.identity, true, disc.Tool.transform.position, disc.Tool.transform.rotation, false);
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(thrower) == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Hazard", 1.5f);
				AudioManager.Play2DSFX(playerOutSFX);
			}
		}
	}

	private void OnDiscReset(DiscGolfDisc disc, Vector3 resetPosition, Quaternion resetRotation)
	{
		StartCoroutine(DelayedReenableDisc(disc));
	}

	private void OnDiscCollideWithSolid(DiscGolfDisc disc, Collider solid, PhotonPlayer thrower)
	{
		if (!solid.gameObject.CompareTag("Hazard") && (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType != GameModeType.MODE_2 || !CollisionDetection.CanPlayerStandOnCollider(solid)))
		{
			return;
		}
		disc.Tool.DisablePickup(this);
		if (disc.hasAuthority)
		{
			if (disc.Tool.NetworkTransform.UseDynamicDistanceExtrapolation)
			{
				AuthorityOnDiscHazard(disc, null, thrower);
			}
			else
			{
				StartCoroutine(DelayedAuthorityOnDiscHazard(disc, null, thrower));
			}
		}
	}

	private void OnDiscThrown(DiscGolfDisc disc, PhotonPlayer thrower)
	{
		if (!disc.Tool.NetworkTransform.UseDynamicDistanceExtrapolation)
		{
			return;
		}
		Vector3 normalized = Vector3.ProjectOnPlane(disc.Tool.RigidbodyEx.velocity, Vector3.up).normalized;
		PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(disc.Team);
		PhotonPlayer photonPlayer = null;
		float num = -1f;
		PhotonPlayer[] array = teamPlayers;
		foreach (PhotonPlayer photonPlayer2 in array)
		{
			if (photonPlayer2.ToPlayer() != null && photonPlayer2 != thrower)
			{
				Vector3 normalized2 = Vector3.ProjectOnPlane(photonPlayer2.ToPlayer().Head.transform.position - disc.transform.position, Vector3.up).normalized;
				float num2 = Vector3.Dot(normalized, normalized2);
				if (num2 > num)
				{
					num = num2;
					photonPlayer = photonPlayer2;
				}
			}
		}
		disc.Tool.NetworkTransform.PotentialOwners.Clear();
		disc.Tool.NetworkTransform.PotentialOwners.Add(thrower);
		if (photonPlayer != null)
		{
			disc.Tool.NetworkTransform.PotentialOwners.Add(photonPlayer);
		}
	}

	[PunRPC]
	private void RpcMasterFinishHole(DiscGolfDisc disc, DiscGolfGoal goal, PhotonPlayer thrower, bool forfeit)
	{
		if (PhotonNetwork.isMasterClient && disc != null && goal != null && IsValidScore(disc, goal, thrower))
		{
			disc.Tool.Disable();
			SetTeamHoleFinished(disc.Team, isHoleFinished: true);
			int teamStroke = GetTeamStroke(disc.Team);
			int deltaScore = teamStroke - goal.Par;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddScore(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(thrower), deltaScore);
			base.photonView.RpcAll(RpcOnFinishHole, goal, thrower, forfeit, teamStroke);
		}
	}

	[PunRPC]
	private void RpcOnFinishHole(DiscGolfGoal goal, PhotonPlayer thrower, bool forfeit, int throwerHoleStrokeCount)
	{
		if (!(goal != null))
		{
			return;
		}
		int score = GetScore(goal.Par, throwerHoleStrokeCount);
		string strokeCountString = GetStrokeCountString(throwerHoleStrokeCount, score);
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(thrower);
		ScreenSpaceNotificationManager.NotificationType style = ((playerTeam != NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) && !forfeit) ? ScreenSpaceNotificationManager.NotificationType.Minor : ScreenSpaceNotificationManager.NotificationType.Medium);
		if (forfeit)
		{
			string titleText = "Mercy Rule: " + NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(playerTeam);
			if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.IsPlaying)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(style, titleText, strokeCountString, 1.7f, 1.5f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(style, titleText, strokeCountString, 1.5f);
			}
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(style, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(playerTeam) + " Scores!", strokeCountString, 1.5f);
			AudioManager.Play3DSFX(goalSFX, goal.transform.position);
			PooledParticle.TryPlayPrefab(goalVFXPrefab, goal.transform.position, goal.transform.rotation);
		}
		if (playerTeam == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player))
		{
			Player.LocalPlayer.PlayerEvents.DiscGolfCompletedHole(score);
			ChallengeEvents.DiscGolfScoreEvent(score, goal.Par, throwerHoleStrokeCount);
			Profiles.LocalAddScore(RecRoomSceneManager.CurrentSceneName, CurrentHole.ToString(), score, "Par " + goal.Par, NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetScore(playerTeam));
		}
	}

	private bool IsValidScore(DiscGolfDisc disc, DiscGolfGoal goal, PhotonPlayer thrower)
	{
		return discGolfStateMachine.CurrentStateId == 0 && CurrentHole == goal.Hole && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(thrower) && !GetTeamHoleFinished(disc.Team);
	}

	private bool IsValidThrow(DiscGolfDisc disc, PhotonPlayer player)
	{
		return discGolfStateMachine.CurrentStateId == 0 && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(player) && !GetTeamHoleFinished(disc.Team);
	}

	private bool IncrementTeamStroke(DiscGolfDisc disc, PhotonPlayer thrower, bool checkDistance = true)
	{
		bool result = false;
		Vector3 vector = Vector3.ProjectOnPlane(disc.transform.position - GetTeamAnchorPoint(disc.Team), Vector3.up);
		if (!checkDistance || (vector.magnitude >= strokeIncrementThreshold && UnityEngine.Time.time - lastStrokeIncrementTimes[disc.Team] > 1f))
		{
			result = true;
			lastStrokeIncrementTimes[disc.Team] = UnityEngine.Time.time;
			if (PhotonNetwork.isMasterClient)
			{
				AddTeamStroke(disc.Team, 1);
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
				{
					int teamStroke = GetTeamStroke(disc.Team);
					DiscGolfGoal currentGoal = GetCurrentGoal();
					if (currentGoal != null)
					{
						int score = GetScore(currentGoal.Par, teamStroke);
						if ((float)score >= mercyRuleHoleScore)
						{
							RpcMasterFinishHole(disc, currentGoal, thrower, forfeit: true);
						}
					}
				}
			}
		}
		return result;
	}

	private DiscGolfDisc GetTeamDisc(GameTeam team)
	{
		for (int i = 0; i < gameplayDiscs.Count; i++)
		{
			if (gameplayDiscs[i].Team == team)
			{
				return gameplayDiscs[i];
			}
		}
		return null;
	}

	private List<DiscGolfDisc> GetTeamDiscs(GameTeam team)
	{
		List<DiscGolfDisc> list = new List<DiscGolfDisc>();
		foreach (DiscGolfDisc gameplayDisc in gameplayDiscs)
		{
			if (gameplayDisc.Team == team)
			{
				list.Add(gameplayDisc);
			}
		}
		return list;
	}

	private void MasterDisableGameplayDiscs()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < gameplayDiscs.Count; i++)
			{
				gameplayDiscs[i].Tool.Disable();
			}
		}
	}

	private void OnPowerupPickup(DiscGolfPowerUp powerup, DiscGolfDisc disc, Player discThrower)
	{
		if (discThrower.PhotonPlayer.IsLocal && IsValidPowerup(disc, powerup, discThrower.PhotonPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestPowerup, disc, powerup, discThrower.PhotonPlayer);
			powerup.LocalEnabled = false;
		}
	}

	[PunRPC]
	private void RpcMasterRequestPowerup(DiscGolfDisc disc, DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		if (PhotonNetwork.isMasterClient && disc != null && powerup != null && IsValidPowerup(disc, powerup, discThrower))
		{
			SetTeamPowerupUsed(disc.Team, isPowerupUsed: true);
			AddTeamStroke(disc.Team, powerup.ScoreAdjust);
			base.photonView.RpcAll(RpcOnPowerup, powerup, discThrower);
		}
	}

	[PunRPC]
	private void RpcOnPowerup(DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		if (powerup != null)
		{
			AudioManager.Play3DSFX(powerupHitSFX, powerup.transform.position);
			powerup.OnPickup();
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(discThrower))
			{
				powerup.LocalEnabled = false;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Bonus!", "Stroke " + powerup.ScoreAdjust, 1.5f);
			}
		}
	}

	private bool IsValidPowerup(DiscGolfDisc disc, DiscGolfPowerUp powerup, PhotonPlayer discThrower)
	{
		return discGolfStateMachine.CurrentStateId == 0 && CurrentHole == powerup.Hole && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(discThrower) && !GetTeamHoleFinished(disc.Team);
	}

	private DiscGolfGoal GetCurrentGoal()
	{
		DiscGolfHole currentHole = CurrentHole;
		for (int i = 0; i < goals.Length; i++)
		{
			if (goals[i].Hole == currentHole)
			{
				return goals[i];
			}
		}
		return null;
	}

	private DiscGolfTee GetTee(GameTeam team)
	{
		DiscGolfHole currentHole = CurrentHole;
		for (int i = 0; i < tees.Length; i++)
		{
			if (tees[i].Hole == currentHole && tees[i].Team == team)
			{
				return tees[i];
			}
		}
		return null;
	}

	private void UpdateHelpBeams()
	{
		DiscGolfHole currentHole = CurrentHole;
		bool flag = discGolfStateMachine.CurrentStateId == 0;
		for (int i = 0; i < goals.Length; i++)
		{
			goals[i].BeamEnabled = flag && goals[i].Hole == currentHole;
		}
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			for (int j = 0; j < gameplayDiscs.Count; j++)
			{
				gameplayDiscs[j].BeamEnabled = flag && gameplayDiscs[j].Team == playerTeam;
			}
		}
	}

	private void OnEnterHoleRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterInitializeHole();
		}
		UpdateHelpBeams();
		DiscGolfGoal currentGoal = GetCurrentGoal();
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = "Hole " + CurrentHoleNumber + " Par " + currentGoal.Par;
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Hole " + CurrentHoleNumber, "Par " + currentGoal.Par, 3f);
	}

	private void OnUpdateHoleRunningState()
	{
		if (PhotonNetwork.isMasterClient && IsHoleFinished())
		{
			discGolfStateMachine.EnterState(1);
		}
	}

	private bool IsHoleFinished()
	{
		GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
		for (int i = 0; i < activeTeams.Length; i++)
		{
			if (!GetTeamHoleFinished(activeTeams[i]))
			{
				return false;
			}
		}
		return true;
	}

	private void OnEnterHoleFinishedState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterDiscGolfStateTimer.StartTimer(6f);
		}
		masterDiscGolfStateTimer.AddTimeRemainingCallback(4.5f, PlayHoleCompletedFeedback);
	}

	private void OnUpdateHoleFinishedState()
	{
		if (PhotonNetwork.isMasterClient && masterDiscGolfStateTimer.TimerOver)
		{
			if (CurrentHole >= LastHole)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
				return;
			}
			CurrentHole++;
			discGolfStateMachine.EnterState(0);
		}
	}

	private void PlayHoleCompletedFeedback()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Hole " + CurrentHoleNumber + " Completed!", 3f);
	}

	private TeamData GetTeamData(GameTeam team)
	{
		if (!teamData.TryGetValue(team, out var value))
		{
			value = new TeamData(team, this);
			teamData[team] = value;
		}
		return value;
	}

	private int GetScore(int par, int strokeCount)
	{
		return strokeCount - par;
	}

	private int GetTeamStroke(GameTeam team)
	{
		return GetTeamData(team).Stroke;
	}

	private void SetTeamStroke(GameTeam team, int strokeCount)
	{
		GetTeamData(team).Stroke = strokeCount;
	}

	private void AddTeamStroke(GameTeam team, int deltaScore)
	{
		GetTeamData(team).Stroke += deltaScore;
	}

	private Vector3 GetTeamAnchorPoint(GameTeam team)
	{
		return GetTeamData(team).Anchor;
	}

	private IEnumerator DelayedSetTeamAnchorPoint(GameTeam team, Vector3 anchorPoint)
	{
		yield return new WaitForSeconds(1f);
		if (!GetTeamDisc(team).Hazarded)
		{
			SetTeamAnchorPoint(team, anchorPoint);
		}
	}

	private void SetTeamAnchorPoint(GameTeam team, Vector3 anchorPoint)
	{
		GetTeamData(team).Anchor = anchorPoint;
	}

	private bool GetTeamHoleFinished(GameTeam team)
	{
		return GetTeamData(team).HoleFinished;
	}

	private void SetTeamHoleFinished(GameTeam team, bool isHoleFinished)
	{
		GetTeamData(team).HoleFinished = isHoleFinished;
	}

	private bool GetTeamPowerupUsed(GameTeam team)
	{
		return GetTeamData(team).PowerupUsed;
	}

	private void SetTeamPowerupUsed(GameTeam team, bool isPowerupUsed)
	{
		GetTeamData(team).PowerupUsed = isPowerupUsed;
	}

	private void MasterInitializeHole()
	{
		GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
		for (int i = 0; i < activeTeams.Length; i++)
		{
			DiscGolfTee tee = GetTee(activeTeams[i]);
			DiscGolfDisc teamDisc = GetTeamDisc(activeTeams[i]);
			if (tee == null || teamDisc == null)
			{
				UnityEngine.Debug.LogError("Could not spawn " + GameTeamSettings.GetTeamName(activeTeams[i]) + " Team disc on Hole " + CurrentHoleNumber);
			}
			else
			{
				teamDisc.Tool.MasterResetToDefault(tee.transform.position, tee.transform.rotation);
				SetTeamAnchorPoint(activeTeams[i], tee.transform.position);
			}
			SetTeamHoleFinished(activeTeams[i], isHoleFinished: false);
			SetTeamStroke(activeTeams[i], 1);
			SetTeamPowerupUsed(activeTeams[i], isPowerupUsed: false);
		}
		foreach (DiscGolfDisc teamDisc2 in GetTeamDiscs(GameTeam.ANY))
		{
			teamDisc2.Tool.MasterResetToLastSpawnPosition();
		}
	}

	private string GetStrokeCountString(int strokeCount, int score)
	{
		string empty = string.Empty;
		if (strokeCount == 1)
		{
			return scoreHoleInOne;
		}
		if (score < -2)
		{
			return scoreLessThanNeg2;
		}
		return score switch
		{
			-2 => scoreNeg2, 
			-1 => scoreNeg1, 
			0 => scoreZero, 
			1 => scorePos1, 
			2 => scorePos2, 
			3 => scorePos3, 
			_ => "+" + score, 
		};
	}

	protected void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
	{
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
		for (int i = 0; i < gameplayDiscs.Count; i++)
		{
			gameplayDiscs[i].Tool.SetPickupEnabled(pickupEnabled && playerTeam == gameplayDiscs[i].Team, this);
		}
	}

	private void RestrictedEnableDiscPickup(DiscGolfDisc disc)
	{
		if (disc != null)
		{
			bool flag = !NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning || (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == disc.Team);
			disc.Tool.SetPickupEnabled(flag, this);
		}
	}

	protected void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient && discGolfStateMachine.CurrentStateId == 0 && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(player))
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerCount(playerTeam) == 0)
			{
				DiscGolfDisc teamDisc = GetTeamDisc(playerTeam);
				teamDisc.Tool.Disable();
			}
		}
	}
}
public class DiscGolfPowerUp : LegacyPowerup
{
	public delegate void Pickup(DiscGolfPowerUp thisPowerup, DiscGolfDisc disc, Player discThrower);

	[Header("Hole")]
	[SerializeField]
	private DiscGolfHole hole = DiscGolfHole.INVALID;

	[SerializeField]
	private int scoreAdjust = -1;

	[SerializeField]
	private Text scoreAdjustText;

	[SerializeField]
	private PooledParticle hitParticles;

	[SerializeField]
	private RecRoomAudioClip onHit;

	private CollisionForwarder collisionForwarder;

	private Vector3 lastHitVelocity = Vector3.zero;

	public Pickup PickupEvent;

	public DiscGolfHole Hole => hole;

	public int ScoreAdjust => scoreAdjust;

	public bool LocalEnabled
	{
		get
		{
			return visualRoot.gameObject.activeInHierarchy && scoreAdjustText.enabled;
		}
		set
		{
			visualRoot.gameObject.SetActive(value);
			scoreAdjustText.enabled = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		collisionForwarder = GetComponentInChildren<CollisionForwarder>();
		if (collisionForwarder != null)
		{
			collisionForwarder.TriggerEnter += OnTriggerEnter;
		}
		if (scoreAdjustText != null)
		{
			scoreAdjustText.text = Mathf.Abs(ScoreAdjust).ToString();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (collisionForwarder != null)
		{
			collisionForwarder.TriggerEnter -= OnTriggerEnter;
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Tool colliderTool = collider.GetColliderTool();
		DiscGolfDisc discGolfDisc = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<DiscGolfDisc>());
		if (base.IsAlive && discGolfDisc != null && discGolfDisc.Thrower != null && discGolfDisc.Thrower.IsLocal && LocalEnabled && PickupEvent != null)
		{
			lastHitVelocity = discGolfDisc.Tool.RigidbodyEx.velocity;
			PickupEvent(this, discGolfDisc, discGolfDisc.Thrower.ToPlayer());
		}
	}

	public void OnPickup()
	{
		if (!(hitParticles != null))
		{
			return;
		}
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(hitParticles);
		if (pooledParticle != null)
		{
			Quaternion rotation = base.transform.rotation;
			if (lastHitVelocity != Vector3.zero)
			{
				rotation = Quaternion.LookRotation(Vector3.Project(lastHitVelocity, base.transform.forward).normalized, base.transform.up);
			}
			pooledParticle.Play(base.transform.position, rotation);
			AudioManager.Play3DSFX(onHit, base.transform.position);
		}
	}

	protected override void OnIsAliveChange()
	{
		base.OnIsAliveChange();
		if (scoreAdjustText != null)
		{
			scoreAdjustText.enabled = base.IsAlive;
		}
	}
}
public class DiscGolfPressurePlate : DiscGolfTriggerSwitch
{
	[SerializeField]
	private bool requiresDiscToTrigger;

	[SerializeField]
	private OverlapVolume triggerVolume;

	private List<Player> triggeringPlayers = new List<Player>();

	protected void Update()
	{
		UpdateTriggeringPlayers();
	}

	private void UpdateTriggeringPlayers()
	{
		if (!(triggerVolume != null) || !PhotonNetwork.isMasterClient)
		{
			return;
		}
		Player[] array = UnityEngine.Object.FindObjectsOfType<Player>();
		foreach (Player player in array)
		{
			if (triggerVolume.ContainsPoint(player.Head.transform.position))
			{
				if (!triggeringPlayers.Contains(player))
				{
					triggeringPlayers.Add(player);
				}
			}
			else if (triggeringPlayers.Contains(player))
			{
				triggeringPlayers.Remove(player);
			}
		}
		if (CanBeTriggered())
		{
			base.CurrentState = SwitchState.ON;
		}
		else
		{
			base.CurrentState = SwitchState.OFF;
		}
	}

	protected override bool CanBeTriggered()
	{
		if (triggeringPlayers.Count == 0)
		{
			return false;
		}
		if (!requiresDiscToTrigger)
		{
			return true;
		}
		foreach (Player triggeringPlayer in triggeringPlayers)
		{
			DiscGolfDisc discGolfDisc = ((!(triggeringPlayer.LeftHand.HeldTool != null)) ? null : triggeringPlayer.LeftHand.HeldTool.GetComponent<DiscGolfDisc>());
			DiscGolfDisc discGolfDisc2 = ((!(triggeringPlayer.RightHand.HeldTool != null)) ? null : triggeringPlayer.RightHand.HeldTool.GetComponent<DiscGolfDisc>());
			if (discGolfDisc != null || discGolfDisc2 != null)
			{
				return true;
			}
		}
		return false;
	}
}
public abstract class DiscGolfSwitch : Photon.MonoBehaviour
{
	public enum SwitchState
	{
		INVALID = -1,
		OFF,
		ON,
		STATE_0,
		STATE_1,
		STATE_2,
		STATE_3,
		STATE_4
	}

	[SerializeField]
	private SwitchState initialState = SwitchState.INVALID;

	private SynchronizedField<SwitchState> _currentState;

	public SwitchState CurrentState
	{
		get
		{
			return _currentState.Get();
		}
		set
		{
			_currentState.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_currentState = new SynchronizedField<SwitchState>(this, "SWITCH_STATE", initialState, SetterPermissionMode.AUTHORITY, OnSwitchStateChanged);
	}

	protected virtual void OnSwitchStateChanged()
	{
	}
}
public class DiscGolfSwitchGizmo : DiscGolfTriggerSwitch
{
	[Header("Switch Gizmo")]
	[SerializeField]
	private float resetTime = 5f;

	private CollisionForwarder triggerForwarder;

	private float lastTriggerTime;

	protected override void Awake()
	{
		base.Awake();
		triggerForwarder = GetComponentInChildren<CollisionForwarder>();
		if (triggerForwarder != null)
		{
			triggerForwarder.TriggerEnter += OnTriggerEnter;
		}
	}

	private void Update()
	{
		if (PhotonNetwork.isMasterClient && base.CurrentState == SwitchState.ON && UnityEngine.Time.time - lastTriggerTime > resetTime)
		{
			base.CurrentState = SwitchState.OFF;
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		if (PhotonNetwork.isMasterClient && other.GetComponentInParent<DiscGolfDisc>() != null && base.CurrentState == SwitchState.OFF)
		{
			base.CurrentState = SwitchState.ON;
			lastTriggerTime = UnityEngine.Time.time;
		}
	}
}
