public class DiscGolfTestingManager : UnityEngine.MonoBehaviour
{
	[Header("Last Throw")]
	[SerializeField]
	private Text lastThrowInitialSpeedText;

	[SerializeField]
	private Text lastThrowMaxHeightText;

	[SerializeField]
	private Text lastThrowDistanceText;

	[SerializeField]
	private Text lastThrowCurveText;

	[SerializeField]
	private Text lastThrowMaxSpeedText;

	[SerializeField]
	[Header("Overall stats")]
	private Text maxInitialSpeedText;

	[SerializeField]
	private Text maxThrowHeightText;

	[SerializeField]
	private Text maxThrowDistanceText;

	[SerializeField]
	private Text maxThrowCurveText;

	[SerializeField]
	private Text maxThrowSpeedText;

	private float maxInitSpeed;

	private float maxDistance;

	private float maxCurve;

	private float maxHeight;

	private float maxSpeed;

	private void Awake()
	{
		DiscGolfDisc[] array = UnityEngine.Object.FindObjectsOfType<DiscGolfDisc>();
		foreach (DiscGolfDisc discGolfDisc in array)
		{
			discGolfDisc.CollidedWithSolid += OnDiscCollidedWithSolid;
		}
	}

	private void OnDiscCollidedWithSolid(DiscGolfDisc disc, Collider solid, PhotonPlayer thrower)
	{
		lastThrowInitialSpeedText.text = disc.LastThrowInitialSpeed.ToString();
		lastThrowDistanceText.text = disc.LastThrowDistance.ToString();
		lastThrowCurveText.text = disc.LastThrowMaxCurveDeviation.ToString();
		lastThrowMaxHeightText.text = disc.LastThrowMaxHeight.ToString();
		lastThrowMaxSpeedText.text = disc.LastThrowMaxSpeed.ToString();
		if (disc.MaxThrowInitialSpeed > maxInitSpeed)
		{
			maxInitSpeed = disc.MaxThrowInitialSpeed;
		}
		if (disc.MaxThrowDistance > maxDistance)
		{
			maxDistance = disc.MaxThrowDistance;
		}
		if (disc.MaxThrowHeight > maxHeight)
		{
			maxHeight = disc.MaxThrowHeight;
		}
		if (disc.MaxThrowCurveDeviation > maxCurve)
		{
			maxCurve = disc.MaxThrowCurveDeviation;
		}
		if (disc.MaxThrowSpeed > maxSpeed)
		{
			maxSpeed = disc.MaxThrowSpeed;
		}
		maxInitialSpeedText.text = maxInitSpeed.ToString();
		maxThrowDistanceText.text = maxDistance.ToString();
		maxThrowHeightText.text = maxHeight.ToString();
		maxThrowCurveText.text = maxCurve.ToString();
		maxThrowSpeedText.text = maxSpeed.ToString();
	}
}
