public abstract class DiscGolfTriggerable : Photon.MonoBehaviour
{
	[Header("Disc Golf Triggerable")]
	[SerializeField]
	private bool activeOnStart = true;

	[SerializeField]
	protected bool autoReset = true;

	[SerializeField]
	protected float autoResetTime = 5f;

	[SerializeField]
	protected Animator gizmoAnimator;

	private SynchronizedField<bool> _active;

	protected float lastTriggerTime;

	public bool Active
	{
		get
		{
			return _active.Get();
		}
		set
		{
			_active.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		_active = new SynchronizedField<bool>(this, "GIZMO_ACTIVE", activeOnStart, SetterPermissionMode.MASTER, OnActiveChanged);
	}

	protected virtual void Update()
	{
		if (Active && autoReset && UnityEngine.Time.time - lastTriggerTime >= autoResetTime)
		{
			ResetTrigger();
		}
	}

	public virtual void Trigger()
	{
		if (PhotonNetwork.isMasterClient)
		{
			lastTriggerTime = UnityEngine.Time.time;
			Active = true;
		}
	}

	public virtual void ResetTrigger()
	{
		if (PhotonNetwork.isMasterClient)
		{
			Active = activeOnStart;
		}
	}

	protected virtual void OnActiveChanged()
	{
	}
}
