public class DiscGolfWindTunnel : DiscGolfTriggerable
{
	private const string DYNAMIC_UPDATE_GROUP = "DiscGolfParticles";

	[Header("Wind Tunnel")]
	[SerializeField]
	private float windForce = 9.8f;

	[SerializeField]
	private ForceMode windForceMode;

	[SerializeField]
	private Renderer fanRenderer;

	[Header("Audio")]
	[SerializeField]
	private AudioSource fanAudioSource;

	[Header("Visuals")]
	private ParticleSystem[] windParticles;

	[Header("Aim Assist")]
	[SerializeField]
	private bool aimAssisted;

	private const float MIN_PARTICLE_SPEED = 4.5f;

	private const float MAX_PARTICLE_SPEED = 10f;

	private const float MIN_WIND_FORCE = 0.3f;

	private const float MAX_WIND_FORCE = 1.2f;

	public Transform AimAssistTarget;

	private List<DiscGolfDisc> affectedDiscs = new List<DiscGolfDisc>();

	private float nextFanBladeTime;

	private float nextFanBladeInterval = 1f;

	private ParticleSystem[] particleSystems;

	private bool bWasActive = true;

	protected override void Awake()
	{
		base.Awake();
		if (fanAudioSource == null)
		{
			fanAudioSource = GetComponent<AudioSource>();
		}
		if (windParticles == null)
		{
			windParticles = GetComponentsInChildren<ParticleSystem>();
		}
		if (windParticles != null && windParticles.Length > 0)
		{
			ParticleSystem[] array = windParticles;
			foreach (ParticleSystem particleSystem in array)
			{
				ParticleSystem.MainModule main = particleSystem.main;
				main.startSpeed = Mathf.Clamp(4.5f + windForce / 0.90000004f * 5.5f, 4.5f, 10f);
			}
		}
	}

	private void Start()
	{
		if (gizmoAnimator != null)
		{
			gizmoAnimator.SetBool("Active", base.Active);
		}
		nextFanBladeInterval = Mathf.Clamp(1f - windForce, 0.1f, 1f);
		nextFanBladeTime = UnityEngine.Time.time + nextFanBladeInterval;
		if (!DynamicUpdateManager.Instance.IsGroupRegistered("DiscGolfParticles"))
		{
			int[] array = new int[6];
			array[0] = 4;
			array[5] = 4;
			array[4] = 4;
			array[1] = 10;
			array[2] = int.MaxValue;
			array[3] = int.MaxValue;
			DynamicUpdateManager.Instance.RegisterGroup("DiscGolfParticles", float.MaxValue, callWhenDisabled: true, array);
		}
		DynamicUpdateManager.Instance.RegisterObject("DiscGolfParticles", this, DynamicUpdateManager.DefaultCostFunction(IsVisibleForDynamicUpdate, TransformForDynamicUpdate), DynamicUpdate);
		particleSystems = GetComponentsInChildren<ParticleSystem>();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		DynamicUpdateManager.Instance.UnregisterObject("DiscGolfParticles", this);
	}

	protected override void Update()
	{
		base.Update();
		if (base.Active && fanRenderer != null)
		{
			fanRenderer.material.SetFloat("_Speed", Mathf.Min(windForce * 8f * (float)Math.PI, 13f));
			if (UnityEngine.Time.time > nextFanBladeTime && fanAudioSource != null)
			{
				fanAudioSource.Play();
				nextFanBladeTime = UnityEngine.Time.time + nextFanBladeInterval;
			}
		}
	}

	private bool IsVisibleForDynamicUpdate()
	{
		return fanRenderer.isVisible;
	}

	private Transform TransformForDynamicUpdate()
	{
		return base.transform;
	}

	private void DynamicUpdate(bool bShouldUpdate)
	{
		if (bShouldUpdate == bWasActive)
		{
			return;
		}
		if (bShouldUpdate)
		{
			for (int i = 0; i < particleSystems.Length; i++)
			{
				particleSystems[i].Play();
			}
		}
		else
		{
			for (int j = 0; j < particleSystems.Length; j++)
			{
				particleSystems[j].Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
			}
		}
		bWasActive = bShouldUpdate;
	}

	public override void Trigger()
	{
		base.Trigger();
		if (!PhotonNetwork.isMasterClient || windForceMode != ForceMode.Impulse || affectedDiscs.Count <= 0)
		{
			return;
		}
		foreach (DiscGolfDisc affectedDisc in affectedDiscs)
		{
			ApplyForceToDisc(affectedDisc);
		}
	}

	protected override void OnActiveChanged()
	{
		if (gizmoAnimator != null)
		{
			gizmoAnimator.SetBool("Active", base.Active);
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		DiscGolfDisc componentInParent = other.GetComponentInParent<DiscGolfDisc>();
		if (componentInParent != null && !affectedDiscs.Contains(componentInParent))
		{
			affectedDiscs.Add(componentInParent);
		}
	}

	private void OnTriggerStay(Collider other)
	{
		if (base.Active && windForceMode == ForceMode.Force)
		{
			DiscGolfDisc componentInParent = other.GetComponentInParent<DiscGolfDisc>();
			ApplyForceToDisc(componentInParent);
		}
	}

	private void OnTriggerExit(Collider other)
	{
		DiscGolfDisc componentInParent = other.GetComponentInParent<DiscGolfDisc>();
		if (componentInParent != null && affectedDiscs.Contains(componentInParent))
		{
			affectedDiscs.Remove(componentInParent);
		}
	}

	private void ApplyForceToDisc(DiscGolfDisc disc)
	{
		if (disc != null && disc.hasOwnership)
		{
			Vector3 vector = ((!aimAssisted || !(AimAssistTarget != null)) ? base.transform.forward : (AimAssistTarget.position - disc.transform.position).normalized);
			disc.Tool.RigidbodyEx.AddForce(vector * windForce, windForceMode);
		}
	}
}
public class Portal : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Portal exitPortal;

	[SerializeField]
	private Renderer entranceRenderer;

	[SerializeField]
	private RawImage entranceImage;

	[SerializeField]
	private float cooldown = 0.5f;

	[SerializeField]
	private GameObject debugMarker;

	private CollisionForwarder collisionForwarder;

	private Vector3 edgeLeft = Vector3.zero;

	private Vector3 edgeRight = Vector3.zero;

	public Camera ExitCamera { get; private set; }

	public float LastExitTime { get; private set; }

	private void Awake()
	{
		ExitCamera = GetComponentInChildren<Camera>();
		collisionForwarder = GetComponentInChildren<CollisionForwarder>();
		if (collisionForwarder != null)
		{
			collisionForwarder.TriggerEnter += OnTriggerEnter;
		}
		if (entranceImage != null)
		{
			edgeRight = base.transform.right * entranceImage.rectTransform.rect.xMax * entranceImage.rectTransform.lossyScale.x;
			edgeLeft = -edgeRight;
		}
	}

	private void Start()
	{
		if (exitPortal != null && ExitCamera != null && exitPortal.ExitCamera != null)
		{
			RenderTexture renderTexture = new RenderTexture(1024, 1024, 24);
			ExitCamera.targetTexture = renderTexture;
			if (entranceRenderer != null)
			{
				entranceRenderer.material.mainTexture = renderTexture;
			}
			if (entranceImage != null)
			{
				entranceImage.texture = renderTexture;
			}
		}
	}

	private void Update()
	{
		Transform transform = Player.LocalPlayer.Head.transform;
		Vector3 vector = base.transform.InverseTransformPoint(transform.position);
		ExitCamera.transform.position = exitPortal.transform.TransformPoint(-vector);
		ExitCamera.transform.LookAt(exitPortal.transform);
		ExitCamera.nearClipPlane = (ExitCamera.transform.position - exitPortal.transform.position).magnitude + 1f;
		Vector3 vector2 = base.transform.position + edgeLeft - transform.position;
		Vector3 to = base.transform.position + edgeRight - transform.position;
		ExitCamera.fieldOfView = Mathf.Abs(Vector3.Angle(vector2, to));
	}

	public void ExitPortal(Tool tool, Vector3 entrancePositionOffset, Quaternion entranceRotationOffset, Vector3 entranceVelocityDirection, float entranceSpeed)
	{
		LastExitTime = UnityEngine.Time.time;
		Vector3 position = new Vector3(0f - entrancePositionOffset.x, entrancePositionOffset.y, 0f - entrancePositionOffset.z);
		tool.transform.position = base.transform.TransformPoint(position);
		Vector3 direction = entranceVelocityDirection;
		direction.x = 0f - direction.x;
		direction.z = 0f - direction.z;
		tool.RigidbodyEx.velocity = base.transform.TransformDirection(direction) * entranceSpeed;
	}

	private void OnTriggerEnter(Collider other)
	{
		ToolCollider component = other.GetComponent<ToolCollider>();
		if (component != null && Vector3.Dot(component.Tool.RigidbodyEx.velocity, base.transform.forward) < 0f && UnityEngine.Time.time - exitPortal.LastExitTime > cooldown)
		{
			Tool tool = component.Tool;
			if (tool.hasAuthority)
			{
				Vector3 entrancePositionOffset = base.transform.InverseTransformPoint(tool.transform.position);
				entrancePositionOffset.z = 0f;
				exitPortal.ExitPortal(tool, entrancePositionOffset, base.transform.InverseTransformRotation(tool.transform.rotation), base.transform.InverseTransformDirection(tool.RigidbodyEx.velocity.normalized), tool.RigidbodyEx.velocity.magnitude);
			}
		}
	}
}
public class Basketball : Ball
{
	[Header("Basketball")]
	public ParticleSystem FireTrail;

	public PooledParticle PassedRimParticle;

	public RecRoomAudioClip PassedRimAudio;

	public bool HasShooter { get; private set; }

	public Vector3 LastShotLocation { get; private set; }

	public string LastShooterName { get; private set; }

	public Player ShootingPlayer { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if (base.Tool != null)
		{
			base.Tool.PreReleaseEvent += OnBasketballReleased;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.PreReleaseEvent -= OnBasketballReleased;
		}
	}

	public void PassedRim(BasketballRim rim)
	{
		AudioManager.Play3DSFX(PassedRimAudio, base.transform);
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(PassedRimParticle);
		if (pooledParticle != null)
		{
			pooledParticle.Play(base.transform.position, base.transform.rotation);
		}
		if (FireTrail.gameObject.activeSelf)
		{
			CancelInvoke("HideFireTrail");
		}
		FireTrail.gameObject.SetActive(value: true);
		FireTrail.Play();
		Invoke("HideFireTrail", 1f);
	}

	private IEnumerator DrawSpot(Vector3 loc)
	{
		float t = 0f;
		while (t < 5f)
		{
			UnityEngine.Debug.DrawRay(loc, Vector3.up * 1.5f, Color.magenta);
			t += UnityEngine.Time.deltaTime;
			yield return null;
		}
	}

	private void HideFireTrail()
	{
		FireTrail.gameObject.SetActive(value: false);
	}

	private void OnBasketballReleased(Tool tool)
	{
		HasShooter = tool.HolderPlayer != null;
		if (HasShooter)
		{
			LastShooterName = tool.HolderPlayer.PlayerName;
			LastShotLocation = tool.HolderPlayer.CurrentFloorPosition;
			ShootingPlayer = tool.HolderPlayer;
		}
	}
}
public class BasketballRim : Photon.MonoBehaviour
{
	private class BasketballShot
	{
		private SynchronizedField<string, Vector3, float> shot;

		public string ShooterName => shot.Get1();

		public Vector3 Position => shot.Get2();

		public float Distance => shot.Get3();

		public void Init(BasketballRim rim, string key, Action callback)
		{
			shot = new SynchronizedField<string, Vector3, float>(rim, key, string.Empty, new Vector3(0f, -999f, 0f), 0f, SetterPermissionMode.MASTER, callback);
		}

		public void SetShot(string shooterName, Vector3 position, float distance)
		{
			shot.Set(shooterName, position, distance);
		}
	}

	[SerializeField]
	private CollisionForwarder rimTop;

	[SerializeField]
	private CollisionForwarder rimBottom;

	[SerializeField]
	private BasketballShotMarker basketballShotMarkerPrefab;

	private BasketballShotMarker mostRecentBasketballShotMarker;

	private BasketballShotMarker farthestBasketballShotMarker;

	private BasketballShot farthestShot = new BasketballShot();

	private BasketballShot mostRecentShot = new BasketballShot();

	private List<Basketball> _trackedBalls = new List<Basketball>();

	private string FARTHEST_SHOT_KEY = "FarthestShotPosition";

	private string MOST_RECENT_SHOT_KEY = "MostRecentShotPosition";

	[NonSerialized]
	private IDisposable _schedulerToken;

	private bool trackingShots;

	public IDisposable SchedulerToken
	{
		get
		{
			return _schedulerToken;
		}
		set
		{
			if (_schedulerToken != null)
			{
				_schedulerToken.Dispose();
			}
			_schedulerToken = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (basketballShotMarkerPrefab != null && base.photonView != null)
		{
			trackingShots = true;
			mostRecentShot.Init(this, MOST_RECENT_SHOT_KEY, OnMostRecentShotChanged);
			farthestShot.Init(this, FARTHEST_SHOT_KEY, OnFarthestShotChanged);
			farthestBasketballShotMarker = UnityEngine.Object.Instantiate(basketballShotMarkerPrefab);
			farthestBasketballShotMarker.name = string.Concat(farthestBasketballShotMarker, "_farthest");
			farthestBasketballShotMarker.Mode = BasketballShotMarker.Modes.Farthest;
			mostRecentBasketballShotMarker = UnityEngine.Object.Instantiate(basketballShotMarkerPrefab);
			mostRecentBasketballShotMarker.name = string.Concat(farthestBasketballShotMarker, "_mostRecent");
			mostRecentBasketballShotMarker.Mode = BasketballShotMarker.Modes.Recent;
		}
	}

	private void Start()
	{
		rimTop.TriggerEnter += RimTop_TriggerEnter;
		rimBottom.TriggerEnter += RimBottom_TriggerEnter;
		OnMostRecentShotChanged();
		OnFarthestShotChanged();
	}

	private void OnMostRecentShotChanged()
	{
		if (mostRecentBasketballShotMarker != null)
		{
			mostRecentBasketballShotMarker.UpdateForShot(mostRecentShot.ShooterName, mostRecentShot.Position, mostRecentShot.Distance);
		}
	}

	private void OnFarthestShotChanged()
	{
		if (farthestBasketballShotMarker != null)
		{
			farthestBasketballShotMarker.UpdateForShot(farthestShot.ShooterName, farthestShot.Position, farthestShot.Distance);
		}
	}

	private void RimTop_TriggerEnter(Collider trigger)
	{
		Basketball basketballTool = GetBasketballTool(trigger);
		if (basketballTool != null)
		{
			AddTrackedBall(basketballTool);
		}
	}

	private void RimBottom_TriggerEnter(Collider trigger)
	{
		Basketball basketballTool = GetBasketballTool(trigger);
		if (!(basketballTool != null) || !RemoveTrackedBall(basketballTool))
		{
			return;
		}
		basketballTool.PassedRim(this);
		if (trackingShots && basketballTool.HasShooter)
		{
			Vector3 position = base.transform.position;
			position.y = basketballTool.LastShotLocation.y;
			float num = Vector3.Distance(basketballTool.LastShotLocation, position);
			if (farthestBasketballShotMarker != null && num > farthestShot.Distance)
			{
				farthestShot.SetShot(basketballTool.LastShooterName, basketballTool.LastShotLocation, num);
			}
			else if (mostRecentBasketballShotMarker != null)
			{
				mostRecentShot.SetShot(basketballTool.LastShooterName, basketballTool.LastShotLocation, num);
			}
			if (basketballTool.ShootingPlayer != null)
			{
				basketballTool.ShootingPlayer.PlayerEvents.MadeBasket(num);
			}
		}
	}

	private Basketball GetBasketballTool(Collider collider)
	{
		ToolCollider component = collider.GetComponent<ToolCollider>();
		if (component != null)
		{
			return component.Tool.GetComponent<Basketball>();
		}
		return null;
	}

	private void AddTrackedBall(Basketball ball)
	{
		bool flag = false;
		if (!_trackedBalls.Contains(ball))
		{
			_trackedBalls.Add(ball);
			flag = true;
		}
		if (flag)
		{
			RefreshSchedulerUpdates();
		}
	}

	private bool RemoveTrackedBall(Basketball ball)
	{
		bool flag = _trackedBalls.Remove(ball);
		if (flag)
		{
			RefreshSchedulerUpdates();
		}
		return flag;
	}

	private void RefreshSchedulerUpdates()
	{
		SchedulerToken = null;
		if (_trackedBalls.Count > 0)
		{
			SchedulerToken = this.Update(UpdateTrackedBalls);
		}
	}

	private void UpdateTrackedBalls()
	{
		bool flag = false;
		for (int num = _trackedBalls.Count - 1; num >= 0; num--)
		{
			if (_trackedBalls[num] == null || _trackedBalls[num].transform.position.y < rimBottom.transform.position.y)
			{
				_trackedBalls.RemoveAt(num);
				flag = true;
			}
		}
		if (flag)
		{
			RefreshSchedulerUpdates();
		}
	}
}
public class Dodgeball : Ball
{
	public delegate void DodgeballCatch(PhotonPlayer catchPlayer, PhotonPlayer thrower, Vector3 catchPoint);

	public delegate void DodgeballHitPlayer(PhotonPlayer thrower, PhotonPlayer hitPlayer, Vector3 hitPoint);

	[SerializeField]
	private ParticleSystem fireTrailParticles;

	private SynchronizedField<bool> isAlive;

	private SynchronizedField<int> throwerId;

	private SynchronizedField<int> firstHitPlayerId;

	private SynchronizedField<Vector3> firstHitPlayerPoint;

	public DodgeballCatch DodgeballCatchEvent;

	public DodgeballHitPlayer DodgeballPlayerOutEvent;

	public DodgeballHitPlayer DodgeballPlayerHitEvent;

	private bool IsAlive
	{
		get
		{
			return isAlive.Get();
		}
		set
		{
			isAlive.Set(value);
		}
	}

	private PhotonPlayer Thrower
	{
		get
		{
			return PhotonPlayer.Find(throwerId.Get());
		}
		set
		{
			throwerId.Set(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	private PhotonPlayer FirstHitPlayer
	{
		get
		{
			return PhotonPlayer.Find(firstHitPlayerId.Get());
		}
		set
		{
			firstHitPlayerId.Set(value?.ID ?? PhotonPlayer.Invalid);
		}
	}

	private Vector3 FirstHitPlayerPoint
	{
		get
		{
			return firstHitPlayerPoint.Get();
		}
		set
		{
			firstHitPlayerPoint.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		isAlive = new SynchronizedField<bool>(this, "IS_ALIVE", defaultValue: false, SetterPermissionMode.AUTHORITY, UpdateAliveDeadState);
		throwerId = new SynchronizedField<int>(this, "THROWER_ID", PhotonPlayer.Invalid, SetterPermissionMode.AUTHORITY);
		firstHitPlayerId = new SynchronizedField<int>(this, "FIRST_HIT_ID", PhotonPlayer.Invalid, SetterPermissionMode.AUTHORITY);
		firstHitPlayerPoint = new SynchronizedField<Vector3>(this, "FIRST_HIT_POINT", Vector3.zero, SetterPermissionMode.AUTHORITY);
		if (base.Tool != null)
		{
			base.Tool.PostPickupEvent += OnPostPickup;
			base.Tool.PostReleaseEvent += OnPostRelease;
			base.Tool.PostResetEvent += OnReset;
		}
	}

	private void Start()
	{
		UpdateAliveDeadState();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.PostPickupEvent -= OnPostPickup;
			base.Tool.PostReleaseEvent -= OnPostRelease;
			base.Tool.PostResetEvent -= OnReset;
		}
	}

	private void OnReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasEnabled)
	{
		if (base.hasAuthority)
		{
			Thrower = null;
			FirstHitPlayer = null;
			IsAlive = false;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		if (base.hasAuthority)
		{
			PhotonPlayer photonPlayer = tool.HolderPlayer.PhotonPlayer;
			PhotonPlayer thrower = Thrower;
			if (IsAlive && thrower != photonPlayer && thrower != null && DodgeballCatchEvent != null)
			{
				DodgeballCatchEvent(photonPlayer, thrower, base.transform.position);
			}
			Thrower = null;
			FirstHitPlayer = null;
			IsAlive = false;
		}
	}

	private void OnPostRelease(Tool tool)
	{
		if (base.hasAuthority)
		{
			Thrower = tool.HolderPlayer.PhotonPlayer;
			FirstHitPlayer = null;
			IsAlive = true;
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (collision.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
		{
			Player.BodyPart bodyPart;
			Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null)
			{
				OnPlayerCollisionEnter(colliderPlayer, collision);
				return;
			}
		}
		if (collision.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics) && collision.GetColliderTool() != null)
		{
			if (!collision.gameObject.GetComponent<Dodgeball>())
			{
				OnToolCollisionEnter();
			}
		}
		else
		{
			OnOtherCollisionEnter();
		}
	}

	private void OnPlayerCollisionEnter(Player hitPlayer, Collision collision)
	{
		if (!base.hasAuthority || (base.Tool != null && base.Tool.IsHeld) || !IsAlive || Thrower == null)
		{
			return;
		}
		if (FirstHitPlayer == null)
		{
			Vector3 vector = ((collision.contacts.Length <= 0) ? base.transform.position : collision.contacts[0].point);
			FirstHitPlayer = hitPlayer.PhotonPlayer;
			FirstHitPlayerPoint = vector;
			if (FirstHitPlayer != null && DodgeballPlayerHitEvent != null)
			{
				DodgeballPlayerHitEvent(Thrower, FirstHitPlayer, FirstHitPlayerPoint);
			}
		}
		else if (hitPlayer.PhotonPlayer != FirstHitPlayer)
		{
			if (DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(Thrower, FirstHitPlayer, FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	private void OnToolCollisionEnter()
	{
		if (base.hasAuthority)
		{
			if (FirstHitPlayer != null && DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(Thrower, FirstHitPlayer, FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	private void OnOtherCollisionEnter()
	{
		if (base.hasAuthority)
		{
			if (IsAlive && FirstHitPlayer != null && DodgeballPlayerOutEvent != null)
			{
				DodgeballPlayerOutEvent(Thrower, FirstHitPlayer, FirstHitPlayerPoint);
			}
			IsAlive = false;
		}
	}

	private void UpdateAliveDeadState()
	{
		bool flag = IsAlive;
		if (base.Tool != null)
		{
			base.Tool.GravityPickupMode = (flag ? Tool.GravityPickup.DISABLED : Tool.GravityPickup.SNAP_POSITION_SNAP_ORIENTATION);
		}
		if (flag)
		{
			fireTrailParticles.Play();
		}
		else
		{
			fireTrailParticles.Stop();
		}
	}
}
public class DodgeballManager : GameRuleManager
{
	private enum DodgeballGameStates
	{
		ROUND_START = 0,
		ROUND_RUNNING = 1,
		ROUND_OVER = 2,
		INVALID = 65535
	}

	private enum DodgeballSpawnPointTags
	{
		Court,
		Sidelines
	}

	private enum DodgeballTeleportRegionTags
	{
		Court,
		Sidelines
	}

	private class PlayerData
	{
		private PhotonPlayer _player;

		private SynchronizedField<bool> _onSidelines;

		public bool OnSidelines
		{
			get
			{
				return _onSidelines.Get();
			}
			set
			{
				_onSidelines.Set(value);
			}
		}

		public PlayerData(PhotonPlayer player)
		{
			_player = player;
			_onSidelines = new SynchronizedField<bool>(player, "ON_SIDELINES", defaultValue: false, SetterPermissionMode.ANYONE, OnPlayerOnSidelines);
			OnPlayerOnSidelines();
		}

		private void OnPlayerOnSidelines()
		{
			if (OnSidelines)
			{
				_player.ToPlayer().AddToolInteractionRestriction(Instance);
			}
			else
			{
				_player.ToPlayer().RemoveToolInteractionRestriction(Instance);
			}
		}
	}

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip roundStartSFX;

	[SerializeField]
	private RecRoomAudioClip roundOverSFX;

	[SerializeField]
	private RecRoomAudioClip playerScoreSFX;

	[SerializeField]
	private RecRoomAudioClip playerScoreVO;

	[SerializeField]
	private RecRoomAudioClip playerOutSFX;

	[SerializeField]
	private RecRoomAudioClip playerOutVO;

	[SerializeField]
	private RecRoomAudioClip playerImpactSFX;

	[Header("Particles")]
	[SerializeField]
	private PooledParticle playerImpactVFXPrefab;

	private SynchronizedStateMachine dodgeballStateMachine;

	private SynchronizedTimer masterDodgeballStateTimer;

	private List<Dodgeball> balls;

	private List<Killzone> killzones;

	private bool localPlayerRespawning;

	private float outOfBoundsStartTime;

	private float maxTimeOutOfBounds = 3f;

	private const float ROUND_NOTIFICATION_DURATION = 3f;

	private const float DEATH_NOTIFICATION_DURATION = 3f;

	private const float HIT_NOTIFICATION_OFFSET_DISTANCE = 0.35f;

	private Dictionary<int, PlayerData> playerData = new Dictionary<int, PlayerData>();

	public new static DodgeballManager Instance => NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance as DodgeballManager;

	private int WonRoundsToFinishGame => NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin / 2 + 1;

	public override string RuleTypeAutoTag => "dodgeball";

	protected override void Awake()
	{
		base.Awake();
		GameManager.OnGameStartEvent += OnGameStart;
		GameManager.OnGameEndEvent += OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent += EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		GameManager.ResetLocalPlayerEvent += ResetLocalPlayer;
		GameManager.InitializeLocalPlayerEvent += InitializeLocalPlayer;
		dodgeballStateMachine = new SynchronizedStateMachine("DODGEBALL", SetterPermissionMode.MASTER);
		dodgeballStateMachine.AddState(ushort.MaxValue, null, null, null);
		dodgeballStateMachine.AddState(0, OnEnterRoundStartState, null, OnUpdateRoundStartState);
		dodgeballStateMachine.AddState(1, OnEnterRoundRunningState, null, OnUpdateRoundRunningState);
		dodgeballStateMachine.AddState(2, OnEnterRoundOverState, OnExitRoundOverState, OnUpdateRoundOverState);
		masterDodgeballStateTimer = new SynchronizedTimer(this, "DODGEBALL_TIMER", SetterPermissionMode.MASTER);
		balls = this.FindAllObjectsOfType<Dodgeball>();
		killzones = this.FindAllObjectsOfType<Killzone>();
		Player.PlayerCreatedEvent += new Action<Player>(OnPlayerCreated);
		Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawned);
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent -= EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
		GameManager.ResetLocalPlayerEvent -= ResetLocalPlayer;
		GameManager.InitializeLocalPlayerEvent -= InitializeLocalPlayer;
		Player.PlayerCreatedEvent -= new Action<Player>(OnPlayerCreated);
		Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawned);
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.RemoveToolInteractionRestriction(this);
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
	}

	protected override void Start()
	{
		base.Start();
		for (int i = 0; i < balls.Count; i++)
		{
			Dodgeball dodgeball = balls[i];
			dodgeball.DodgeballCatchEvent = (Dodgeball.DodgeballCatch)Delegate.Combine(dodgeball.DodgeballCatchEvent, new Dodgeball.DodgeballCatch(OnDodgeballCatch));
			Dodgeball dodgeball2 = balls[i];
			dodgeball2.DodgeballPlayerOutEvent = (Dodgeball.DodgeballHitPlayer)Delegate.Combine(dodgeball2.DodgeballPlayerOutEvent, new Dodgeball.DodgeballHitPlayer(OnDodgeballPlayerOut));
			Dodgeball dodgeball3 = balls[i];
			dodgeball3.DodgeballPlayerHitEvent = (Dodgeball.DodgeballHitPlayer)Delegate.Combine(dodgeball3.DodgeballPlayerHitEvent, new Dodgeball.DodgeballHitPlayer(OnDodgeballPlayerHit));
		}
		EnableKillzones(enable: false);
		dodgeballStateMachine.Start(this, ushort.MaxValue);
	}

	private void Update()
	{
		dodgeballStateMachine.Update();
		masterDodgeballStateTimer.UpdateCallbacks();
	}

	private void InitializeSceneOnPreGame()
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterResetAllBalls();
		}
	}

	private void OnGameStart()
	{
		if (PhotonNetwork.isMasterClient)
		{
			dodgeballStateMachine.EnterState(0);
		}
		foreach (Dodgeball ball in balls)
		{
			ball.Tool.ToolCleanup.PauseCleanup(this);
		}
		EnableKillzones(enable: true);
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = "Best " + WonRoundsToFinishGame + " of " + NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin + " Rounds";
	}

	private void OnGameEnd()
	{
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
		if (PhotonNetwork.isMasterClient)
		{
			dodgeballStateMachine.EnterState(ushort.MaxValue);
		}
		foreach (Dodgeball ball in balls)
		{
			ball.Tool.ToolCleanup.ResumeCleanup(this);
		}
		EnableKillzones(enable: false);
	}

	private void OnPlayerCreated(Player player)
	{
		if (player.isLocal && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			LocalPlayerSetOnSidelines(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(player.PhotonPlayer));
		}
	}

	private void OnLocalPlayerRespawned()
	{
		localPlayerRespawning = false;
	}

	private void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoiningInProgress)
	{
		if (!localPlayerIsSpectator)
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
		}
	}

	private void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
		}
	}

	private void OnEnterRoundStartState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisableAllBalls();
			masterDodgeballStateTimer.StartTimer(5f);
		}
		masterDodgeballStateTimer.AddTimeRemainingCallback(3f, PlayRoundStartEffect);
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
		}
	}

	private void OnUpdateRoundStartState()
	{
		if (PhotonNetwork.isMasterClient && masterDodgeballStateTimer.TimerOver)
		{
			dodgeballStateMachine.EnterState(1);
		}
	}

	private void PlayRoundStartEffect()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Round Starting", 3f);
	}

	private void OnEnterRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
		if (PhotonNetwork.isMasterClient)
		{
			MasterResetAllBalls();
		}
		AudioManager.Play2DSFX(roundStartSFX);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Go!", 2f);
	}

	private void OnUpdateRoundRunningState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			GameTeam[] allTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAllTeams();
			for (int i = 0; i < allTeams.Length; i++)
			{
				if (IsEntireTeamOnSidelines(allTeams[i]))
				{
					GameTeam anotherTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(allTeams[i]);
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddScore(anotherTeam, 1);
					dodgeballStateMachine.EnterState(2);
				}
			}
		}
		if (Player.LocalPlayerExists && Player.LocalPlayer.IsOutOfWorldBounds && !localPlayerRespawning)
		{
			if (outOfBoundsStartTime == 0f)
			{
				outOfBoundsStartTime = UnityEngine.Time.time;
			}
			else if (UnityEngine.Time.time - outOfBoundsStartTime > maxTimeOutOfBounds)
			{
				outOfBoundsStartTime = 0f;
				localPlayerRespawning = true;
				base.photonView.RpcMaster<PhotonPlayer, PhotonPlayer, Vector3>(RpcMasterRequestPlayerOut, null, PhotonNetwork.player, Vector3.zero);
			}
		}
		else
		{
			outOfBoundsStartTime = 0f;
		}
	}

	private void OnEnterRoundOverState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			foreach (PhotonPlayer activePlayer in NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers())
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterResetPlayerHealth(activePlayer);
			}
			masterDodgeballStateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration + 3f);
		}
		this.InvokeInUpdate(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration, PlayRoundOverEffect);
	}

	private void OnExitRoundOverState(ushort nextStateId, ushort nextSubStateId)
	{
		if (nextStateId == 0 && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			LocalPlayerSetOnSidelines(isOnSidelines: false);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
		}
	}

	private void OnUpdateRoundOverState()
	{
		if (PhotonNetwork.isMasterClient && masterDodgeballStateTimer.TimerOver)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out var _, out var highestScore);
			if (highestScore >= WonRoundsToFinishGame)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
			else
			{
				dodgeballStateMachine.EnterState(0);
			}
		}
	}

	private void PlayRoundOverEffect()
	{
		AudioManager.Play2DSFX(roundOverSFX);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Round Over!", 3f);
	}

	private void OnDodgeballPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 hitPoint)
	{
		if (IsValidHit(thrower, outPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestPlayerOut, thrower, outPlayer, hitPoint);
		}
	}

	private void OnDodgeballPlayerHit(PhotonPlayer thrower, PhotonPlayer hitPlayer, Vector3 hitPoint)
	{
		if (IsValidHit(thrower, hitPlayer))
		{
			base.photonView.RpcAll(RpcOnPlayerHit, thrower, hitPlayer, hitPoint);
		}
	}

	[PunRPC]
	private void RpcMasterRequestPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidHit(thrower, outPlayer))
		{
			base.photonView.RpcAll(RpcOnPlayerOut, thrower, outPlayer, outPoint);
		}
	}

	private bool IsValidHit(PhotonPlayer thrower, PhotonPlayer outPlayer)
	{
		return dodgeballStateMachine.CurrentStateId == 1 && (thrower == null || (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(outPlayer) && !IsPlayerOnSidelines(thrower) && !IsPlayerOnSidelines(outPlayer) && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(thrower, outPlayer)));
	}

	[PunRPC]
	private void RpcOnPlayerOut(PhotonPlayer thrower, PhotonPlayer outPlayer, Vector3 outPoint)
	{
		if (outPlayer.IsLocal && (thrower == null || !IsPlayerOnSidelines(outPlayer)))
		{
			outPlayer.ToPlayer().AddToolInteractionRestriction(this);
			LocalPlayerSetOnSidelines(isOnSidelines: true);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
			if (thrower != null)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You're Out!", "Hit by " + thrower.NickName, 3f);
			}
			else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(outPlayer))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Out of bounds!", "Don't disrupt the game", 3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Penalty!", "You were out of bounds", 3f);
			}
			AudioManager.Play2DSFX(playerOutSFX);
			AudioManager.Play2DSFX(playerOutVO);
		}
		else if (thrower != null && thrower.IsLocal)
		{
			Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - outPoint).normalized + Vector3.up);
			WorldSpaceNotification.PlayNext("Out!", 3f, null, followPlayer: false, outPoint + vector);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You Hit " + outPlayer.NickName, 3f);
			AudioManager.Play2DSFX(playerScoreSFX);
			AudioManager.Play2DSFX(playerScoreVO);
			Player.LocalPlayer.PlayerEvents.DodgeballOut();
		}
	}

	[PunRPC]
	private void RpcOnPlayerHit(PhotonPlayer thrower, PhotonPlayer hitPlayer, Vector3 hitPoint)
	{
		AudioManager.Play3DSFX(playerImpactSFX, hitPoint);
		PooledParticle.TryPlayPrefab(playerImpactVFXPrefab, hitPoint);
	}

	private void OnDodgeballCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		if (catcher.IsLocal && IsValidCatch(catcher, thrower))
		{
			base.photonView.RpcMaster(RpcMasterRequestPlayerCatch, catcher, thrower, catchPoint);
		}
	}

	[PunRPC]
	private void RpcMasterRequestPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidCatch(catcher, thrower))
		{
			base.photonView.RpcAll(RpcOnPlayerCatch, catcher, thrower, catchPoint);
		}
	}

	private bool IsValidCatch(PhotonPlayer catcher, PhotonPlayer thrower)
	{
		return dodgeballStateMachine.CurrentStateId == 1 && !IsPlayerOnSidelines(catcher) && !IsPlayerOnSidelines(thrower) && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(catcher, thrower);
	}

	[PunRPC]
	private void RpcOnPlayerCatch(PhotonPlayer catcher, PhotonPlayer thrower, Vector3 catchPoint)
	{
		Vector3 vector = 0.35f * ((Player.LocalPlayer.Head.transform.position - catchPoint).normalized + Vector3.up);
		WorldSpaceNotification.PlayNext("Catch!", 3f, null, followPlayer: false, catchPoint + vector);
	}

	private bool IsEntireTeamOnSidelines(GameTeam team)
	{
		PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(team);
		for (int i = 0; i < teamPlayers.Length; i++)
		{
			if (!IsPlayerOnSidelines(teamPlayers[i]))
			{
				return false;
			}
		}
		return true;
	}

	private PlayerData GetPlayerData(PhotonPlayer player)
	{
		if (!playerData.TryGetValue(player.ID, out var value))
		{
			value = new PlayerData(player);
			playerData[player.ID] = value;
		}
		return value;
	}

	private bool IsPlayerOnSidelines(PhotonPlayer player)
	{
		return player != null && GetPlayerData(player).OnSidelines;
	}

	private void LocalPlayerSetOnSidelines(bool isOnSidelines)
	{
		GetPlayerData(PhotonNetwork.player).OnSidelines = isOnSidelines;
		if (isOnSidelines)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(Player.LocalPlayer.PhotonPlayer))
			{
				Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			}
			else
			{
				Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			}
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_2);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_2);
		}
		else
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeleportManager.SetLocalPlayerTeleportRegionTag(TeleportRegionTagType.TAG_1);
		}
	}

	private void MasterResetAllBalls()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < balls.Count; i++)
			{
				balls[i].Tool.MasterResetToLastSpawnPosition();
			}
		}
	}

	private void MasterDisableAllBalls()
	{
		if (PhotonNetwork.isMasterClient)
		{
			for (int i = 0; i < balls.Count; i++)
			{
				balls[i].Tool.Disable();
			}
		}
	}

	private void EnableKillzones(bool enable)
	{
		for (int i = 0; i < killzones.Count; i++)
		{
			killzones[i].gameObject.SetActive(enable);
		}
	}

	private void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
	{
		for (int i = 0; i < balls.Count; i++)
		{
			balls[i].Tool.SetPickupEnabled(pickupEnabled, this);
		}
	}
}
public class AnnouncementBulletinBoardUI : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private string defaultMessage;

	[SerializeField]
	private TextMeshProUGUI messageText;

	[SerializeField]
	private Button3D moreInfoButton;

	private string moreInfoUrl = "https://rec.net";

	private void Start()
	{
		Refresh();
		CommunityBoard.CurrentBoardAnnouncementUpdated += Refresh;
		CommunityBoard.CurrentBoardUpdated += Refresh;
	}

	private void OnDestroy()
	{
		CommunityBoard.CurrentBoardAnnouncementUpdated -= Refresh;
		CommunityBoard.CurrentBoardUpdated -= Refresh;
	}

	private void Refresh()
	{
		if (CommunityBoard.Current?.CurrentAnnouncement != null)
		{
			messageText.text = CommunityBoard.Current.CurrentAnnouncement.Message;
			moreInfoUrl = CommunityBoard.Current.CurrentAnnouncement.MoreInfoUrl;
		}
		else
		{
			messageText.text = defaultMessage;
			moreInfoUrl = null;
		}
		moreInfoButton.Interactable = !string.IsNullOrEmpty(moreInfoUrl);
	}

	public void Button_MoreInfo()
	{
		WebBrowser.ShowWebPage(moreInfoUrl, "Rec Room announcement", showPrefix: false);
	}
}
namespace RecRoom
{
	public class AutoAdjustHeight : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private float minYOffset = -0.5f;

		[SerializeField]
		private float maxYOffset = 0.5f;

		[SerializeField]
		private float baseHeight = 1.5f;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Interpolator interpolator;

		private bool adjusted;

		private void Update()
		{
			if (Player.IsCloseToAnyPlayer(base.transform.position))
			{
				if (!adjusted)
				{
					adjusted = true;
					Vector3 position = base.transform.position;
					if (Player.LocalPlayerExists)
					{
						position.y = Mathf.Clamp(Player.LocalPlayer.Head.transform.position.y - baseHeight, minYOffset, maxYOffset);
					}
					interpolator.TargetPosition = position;
				}
			}
			else
			{
				adjusted = false;
			}
		}
	}
}
public class BulletinBoardController : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameObject[] nonJuniorOnlyObjects;

	[SerializeField]
	private GameObject[] juniorOnlyObjects;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip buttonDownAudio;

	[SerializeField]
	private RecRoomAudioClip buttonUpAudio;

	private BulletinBoardVisualLayer[] visualLayers;

	private void Awake()
	{
		visualLayers = GetComponentsInChildren<BulletinBoardVisualLayer>(includeInactive: true);
	}

	private void Start()
	{
		Button3DBase[] componentsInChildren = base.gameObject.GetComponentsInChildren<Button3DBase>(includeInactive: true);
		Button3DBase[] array = componentsInChildren;
		foreach (Button3DBase button3DBase in array)
		{
			button3DBase.ButtonDownAudio = buttonDownAudio;
			button3DBase.ButtonUpAudio = buttonUpAudio;
		}
		Canvas[] componentsInChildren2 = GetComponentsInChildren<Canvas>(includeInactive: true);
		foreach (Canvas canvas in componentsInChildren2)
		{
			canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
		}
		bool flag = Profiles.LocalProfile.IsJunior();
		if (juniorOnlyObjects != null)
		{
			for (int k = 0; k < juniorOnlyObjects.Length; k++)
			{
				if (juniorOnlyObjects[k] != null)
				{
					juniorOnlyObjects[k].SetActive(flag);
				}
			}
		}
		if (nonJuniorOnlyObjects == null)
		{
			return;
		}
		for (int l = 0; l < nonJuniorOnlyObjects.Length; l++)
		{
			if (nonJuniorOnlyObjects[l] != null)
			{
				nonJuniorOnlyObjects[l].SetActive(!flag);
			}
		}
	}

	public void ShowVisualLayer(BulletinBoardVisualLayer.VisualLayer visualLayer)
	{
		BulletinBoardVisualLayer[] array = visualLayers;
		foreach (BulletinBoardVisualLayer bulletinBoardVisualLayer in array)
		{
			bulletinBoardVisualLayer.gameObject.SetActive(bulletinBoardVisualLayer.Layer == visualLayer);
		}
	}
}
