public class ChangingRoomMenu : UnityEngine.MonoBehaviour
{
	private enum MenuMode
	{
		Home,
		Hair,
		Skin,
		Face
	}

	private enum HairSubMode
	{
		Hair,
		Beard
	}

	private struct ColorButton
	{
		public RadioButton3D RadioButton;

		public AvatarColor Color;
	}

	private MenuMode menuMode;

	private HairSubMode hairSubMode;

	[SerializeField]
	private RectTransform mainPanel;

	[SerializeField]
	private GameObject mainPanelHomeMode;

	[SerializeField]
	private GameObject mainPanelHairMode;

	[SerializeField]
	private GameObject mainPanelSkinMode;

	[SerializeField]
	private GameObject mainPanelFaceMode;

	[SerializeField]
	private RectTransform secondPanel;

	[SerializeField]
	private GameObject secondPanelHairMode;

	[SerializeField]
	private GameObject secondPanelSkinMode;

	[SerializeField]
	private GameObject secondPanelFaceMode;

	[SerializeField]
	private GameObject secondPanelBeardMode;

	[SerializeField]
	private RadioButton3D hairButton;

	[SerializeField]
	private RadioButton3D skinButton;

	[SerializeField]
	private Animator mainPanelAnimator;

	[SerializeField]
	private Animator secondPanelAnimator;

	[Header("Face Editing")]
	[SerializeField]
	private RadioButton3D eyesButton;

	[SerializeField]
	private RadioButton3D mouthButton;

	[SerializeField]
	private Button3D moveUpButton;

	[SerializeField]
	private Button3D moveDownButton;

	[SerializeField]
	private Button3D moveLeftButton;

	[SerializeField]
	private Button3D moveRightButton;

	[SerializeField]
	private Button3D scaleUpButton;

	[SerializeField]
	private Button3D scaleDownButton;

	[SerializeField]
	private float FaceFeatureMoveAmount = 0.02f;

	[SerializeField]
	private float FaceFeatureScaleAmount = 0.05f;

	[Header("Panel Adjustment")]
	[SerializeField]
	private bool enablePanelAdjustment = true;

	[SerializeField]
	private int mainPanelAdjustmentAmount;

	[SerializeField]
	private int secondPanelAdjustmentAmount;

	[SerializeField]
	private float adjustmentTriggerOnDistance = 1.7f;

	[SerializeField]
	private float adjustmentTriggerOffDistance = 1.7f;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip buttonDownAudio;

	[SerializeField]
	private RecRoomAudioClip buttonUpAudio;

	private bool initialized;

	private Dictionary<FaceFeatureType, List<FaceFeatureBase>> featureOptions;

	private Dictionary<FaceFeatureType, int> currentFeatureIndices;

	private FaceFeatureType activeFeatureType;

	private bool adjustmentCoroutineRunning;

	private bool panelsAdjusted;

	private Vector3 originalMainPanelPosition;

	private Vector3 originalSecondPanelPosition;

	private List<ColorButton> hairColorButtons;

	private List<ColorButton> beardColorButtons;

	private List<ColorButton> skinColorButtons;

	public void ShowMenu(bool show)
	{
		if (mainPanelAnimator != null)
		{
			mainPanelAnimator.SetBool("Visible", show);
		}
	}

	private void Awake()
	{
		SetupButtonAudio();
		hairColorButtons = SetupColorButtons(secondPanelHairMode);
		beardColorButtons = SetupColorButtons(secondPanelBeardMode);
		skinColorButtons = SetupColorButtons(secondPanelSkinMode);
		if (mainPanelAnimator != null)
		{
			mainPanelAnimator.SetBool("Visible", value: true);
		}
	}

	private void Start()
	{
		if (UIInputModule.Instance != null)
		{
			GetComponentInChildren<Canvas>().worldCamera = UIInputModule.Instance.ControllerCamera;
		}
		SetMode(MenuMode.Home);
		Player.LocalPlayerCreatedEvent += new Action(Initialize);
		SetDefaultButtonStates();
		if (enablePanelAdjustment && !adjustmentCoroutineRunning)
		{
			originalMainPanelPosition = mainPanel.localPosition;
			originalSecondPanelPosition = secondPanel.localPosition;
			StartCoroutine(PanelAdjustment());
		}
	}

	private void Initialize()
	{
		if (!initialized && Player.LocalPlayerExists)
		{
			featureOptions = new Dictionary<FaceFeatureType, List<FaceFeatureBase>>();
			featureOptions[FaceFeatureType.Brow] = Player.LocalPlayer.PlayerOutfit.GetAvailableFaceFeatures(FaceFeatureType.Brow);
			featureOptions[FaceFeatureType.Eye] = Player.LocalPlayer.PlayerOutfit.GetAvailableFaceFeatures(FaceFeatureType.Eye);
			featureOptions[FaceFeatureType.Nose] = Player.LocalPlayer.PlayerOutfit.GetAvailableFaceFeatures(FaceFeatureType.Nose);
			featureOptions[FaceFeatureType.Mouth] = Player.LocalPlayer.PlayerOutfit.GetAvailableFaceFeatures(FaceFeatureType.Mouth);
			currentFeatureIndices = new Dictionary<FaceFeatureType, int>();
			currentFeatureIndices[FaceFeatureType.Brow] = 0;
			currentFeatureIndices[FaceFeatureType.Eye] = 0;
			currentFeatureIndices[FaceFeatureType.Nose] = 0;
			currentFeatureIndices[FaceFeatureType.Mouth] = 0;
			initialized = true;
			Player.LocalPlayerCreatedEvent -= new Action(Initialize);
		}
	}

	private void SetDefaultButtonStates()
	{
		if (hairButton != null)
		{
			hairButton.IsCurrent = true;
			Button_SetHairSubMode();
		}
		if (skinButton != null)
		{
			skinButton.IsCurrent = true;
		}
		if (eyesButton != null)
		{
			eyesButton.IsCurrent = true;
			Button_ChangeActiveFeatureType(1);
		}
	}

	private IEnumerator PanelAdjustment()
	{
		adjustmentCoroutineRunning = true;
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		while (true)
		{
			float playerDistance = Vector3.Distance(Player.LocalPlayer.Head.transform.position, base.transform.position);
			if (!panelsAdjusted)
			{
				if (playerDistance <= adjustmentTriggerOnDistance)
				{
					mainPanel.localPosition = originalMainPanelPosition + mainPanelAdjustmentAmount * Vector3.right;
					secondPanel.localPosition = originalSecondPanelPosition + secondPanelAdjustmentAmount * Vector3.right;
					panelsAdjusted = true;
				}
			}
			else if (playerDistance > adjustmentTriggerOffDistance)
			{
				mainPanel.localPosition = originalMainPanelPosition;
				secondPanel.localPosition = originalSecondPanelPosition;
				panelsAdjusted = false;
			}
			yield return new WaitForSeconds(0.5f);
		}
	}

	private void SetMode(MenuMode mode)
	{
		menuMode = mode;
		bool value = menuMode != MenuMode.Home;
		secondPanelAnimator.SetBool("Visible", value);
		mainPanelHomeMode.SetActive(menuMode == MenuMode.Home);
		mainPanelHairMode.SetActive(menuMode == MenuMode.Hair);
		secondPanelHairMode.SetActive(menuMode == MenuMode.Hair && hairSubMode == HairSubMode.Hair);
		secondPanelBeardMode.SetActive(menuMode == MenuMode.Hair && hairSubMode == HairSubMode.Beard);
		mainPanelSkinMode.SetActive(menuMode == MenuMode.Skin);
		secondPanelSkinMode.SetActive(menuMode == MenuMode.Skin);
		mainPanelFaceMode.SetActive(menuMode == MenuMode.Face);
		secondPanelFaceMode.SetActive(menuMode == MenuMode.Face);
		switch (menuMode)
		{
		case MenuMode.Hair:
		case MenuMode.Skin:
			RefreshAllColorButtonStates();
			break;
		case MenuMode.Face:
			RefreshFeatureEditButtonStates();
			RefreshFeatureButtonIcons();
			break;
		}
		if (mainPanelAnimator != null)
		{
			mainPanelAnimator.SetTrigger("Refresh");
		}
	}

	private void SetupButtonAudio()
	{
		Button3DBase[] componentsInChildren = GetComponentsInChildren<Button3DBase>(includeInactive: true);
		Button3DBase[] array = componentsInChildren;
		foreach (Button3DBase button3DBase in array)
		{
			button3DBase.ButtonDownAudio = buttonDownAudio;
			button3DBase.ButtonUpAudio = buttonUpAudio;
		}
	}

	private List<ColorButton> SetupColorButtons(GameObject parentObject)
	{
		List<ColorButton> list = new List<ColorButton>();
		if (parentObject != null)
		{
			RadioButton3D[] componentsInChildren = parentObject.GetComponentsInChildren<RadioButton3D>();
			RadioButton3D[] array = componentsInChildren;
			foreach (RadioButton3D radioButton3D in array)
			{
				AvatarColor componentInChildren = radioButton3D.GetComponentInChildren<AvatarColor>();
				if (componentInChildren != null)
				{
					list.Add(new ColorButton
					{
						RadioButton = radioButton3D,
						Color = componentInChildren
					});
				}
			}
		}
		return list;
	}

	[SkipRename]
	public void Button_ResetOutfitSelection()
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerOutfit.RestoreOutfitSelection();
		}
	}

	[SkipRename]
	public void Button_RandomizeOutfitSelection()
	{
		if (Player.LocalPlayerExists && NetworkedSingletonMonoBehaviour<OutfitManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.RandomizePlayerOutfit();
		}
	}

	[SkipRename]
	public void Button_ChangeAvatarColor(AvatarColor avatarColor)
	{
		if (Player.LocalPlayerExists)
		{
			if (avatarColor.Type == AvatarColor.ColorType.Skin)
			{
				Player.LocalPlayer.PlayerOutfit.SetSkinColor(avatarColor.GuidString, logChange: true);
			}
			else if (avatarColor.Type == AvatarColor.ColorType.Hair)
			{
				ShowHairDyeMessageIfApplicable();
				Player.LocalPlayer.PlayerOutfit.SetHairColor(avatarColor.GuidString, logChange: true);
			}
			else if (avatarColor.Type == AvatarColor.ColorType.Beard)
			{
				ShowHairDyeMessageIfApplicable();
				Player.LocalPlayer.PlayerOutfit.SetBeardColor(avatarColor.GuidString, logChange: true);
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Button_ChangeAvatarColor cannot handle the avatarColor.Type {0}", avatarColor.Type);
			}
		}
	}

	private void ShowHairDyeMessageIfApplicable()
	{
		if (NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetActiveConsumableInCategory(ConsumableManager.Category.Potion_HairDye) != null)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Deactivate hair dye in your backpack", 3f);
		}
	}

	public void Button_ChangeActiveFeatureType(int featureType)
	{
		activeFeatureType = (FaceFeatureType)featureType;
		RefreshFeatureEditButtonStates();
	}

	public void Button_NextSelectionForActiveFeature(bool forward)
	{
		if (!Player.LocalPlayerExists || (activeFeatureType != FaceFeatureType.Eye && activeFeatureType != FaceFeatureType.Mouth))
		{
			return;
		}
		int num = currentFeatureIndices[activeFeatureType];
		int count = featureOptions[activeFeatureType].Count;
		if (count < 1)
		{
			return;
		}
		if (forward)
		{
			num = (num + 1) % count;
		}
		else
		{
			num--;
			if (num < 0)
			{
				num = count - 1;
			}
		}
		currentFeatureIndices[activeFeatureType] = num;
		string guid = featureOptions[activeFeatureType][num].Guid;
		Player.LocalPlayer.PlayerOutfit.SetFaceFeatureSelection(activeFeatureType, guid, logChange: true);
		RefreshFeatureButtonIcons();
	}

	public void Button_SetMode(int mode)
	{
		SetMode((MenuMode)mode);
	}

	public void Button_Confirm()
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerOutfit.SnapShotAppearanceSelection();
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Appearance saved", 3f);
		}
		SetMode(MenuMode.Home);
	}

	public void Button_Cancel()
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerOutfit.RestoreAppearanceSelection();
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Appearance reset", 3f);
		}
		SetMode(MenuMode.Home);
	}

	public void Button_SetHairSubMode(bool beard = false)
	{
		hairSubMode = (beard ? HairSubMode.Beard : HairSubMode.Hair);
		secondPanelHairMode.SetActive(menuMode == MenuMode.Hair && hairSubMode == HairSubMode.Hair);
		secondPanelBeardMode.SetActive(menuMode == MenuMode.Hair && hairSubMode == HairSubMode.Beard);
	}

	public void Button_MoveFeature(int direction)
	{
		if (Player.LocalPlayerExists)
		{
			Vector2 position = CalculateDesiredFeaturePosition(activeFeatureType, direction);
			Player.LocalPlayer.PlayerOutfit.SetFaceFeaturePositionOffset(activeFeatureType, position, logChange: true);
			RefreshFeatureEditButtonStates();
		}
	}

	private Vector2 CalculateDesiredFeaturePosition(FaceFeatureType featureType, int direction)
	{
		Vector2 result = Vector2.zero;
		if (Player.LocalPlayerExists)
		{
			Vector2 vector = Vector2.zero;
			switch (direction)
			{
			case 0:
				vector = Vector2.up * FaceFeatureMoveAmount;
				break;
			case 1:
				vector = Vector2.right * (0f - FaceFeatureMoveAmount);
				break;
			case 2:
				vector = Vector2.up * (0f - FaceFeatureMoveAmount);
				break;
			case 3:
				vector = Vector2.right * FaceFeatureMoveAmount;
				break;
			}
			switch (featureType)
			{
			case FaceFeatureType.Eye:
			{
				Vector2 mouthPositionOffset = Player.LocalPlayer.PlayerOutfit.FaceFeatures.EyePositionOffset;
				result = mouthPositionOffset + vector;
				break;
			}
			case FaceFeatureType.Mouth:
			{
				Vector2 mouthPositionOffset = Player.LocalPlayer.PlayerOutfit.FaceFeatures.MouthPositionOffset;
				result = mouthPositionOffset + vector;
				break;
			}
			}
		}
		return result;
	}

	public void Button_ScaleFeature(bool larger)
	{
		if (Player.LocalPlayerExists)
		{
			float scale = CalculateDesiredFeatureScale(activeFeatureType, larger);
			Player.LocalPlayer.PlayerOutfit.SetFaceFeatureScaleOffset(activeFeatureType, scale, logChange: true);
			RefreshFeatureEditButtonStates();
		}
	}

	private float CalculateDesiredFeatureScale(FaceFeatureType featureType, bool larger)
	{
		float result = 0f;
		if (Player.LocalPlayerExists)
		{
			float num = (float)(larger ? 1 : (-1)) * FaceFeatureScaleAmount;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
			{
				float mouthScaleOffset = Player.LocalPlayer.PlayerOutfit.FaceFeatures.EyeScaleOffset;
				result = mouthScaleOffset + num;
				break;
			}
			case FaceFeatureType.Mouth:
			{
				float mouthScaleOffset = Player.LocalPlayer.PlayerOutfit.FaceFeatures.MouthScaleOffset;
				result = mouthScaleOffset + num;
				break;
			}
			}
		}
		return result;
	}

	public void Button_RotateFeature(bool clockwise)
	{
		UnityEngine.Debug.LogWarning("Rotation is not yet supported for face feature editing.");
	}

	private void RefreshFeatureEditButtonStates()
	{
		if (Player.LocalPlayerExists)
		{
			float minDelta = FaceFeatureMoveAmount / 4f;
			RefreshMoveButton(moveUpButton, 0, minDelta);
			RefreshMoveButton(moveRightButton, 1, minDelta);
			RefreshMoveButton(moveDownButton, 2, minDelta);
			RefreshMoveButton(moveLeftButton, 3, minDelta);
			float minDelta2 = FaceFeatureScaleAmount / 4f;
			RefreshScaleButton(scaleUpButton, larger: true, minDelta2);
			RefreshScaleButton(scaleDownButton, larger: false, minDelta2);
		}
	}

	private void RefreshMoveButton(Button3D button, int direction, float minDelta)
	{
		if (button != null)
		{
			Vector2 desiredPosition = CalculateDesiredFeaturePosition(activeFeatureType, direction);
			button.Interactable = Player.LocalPlayer.FacialAnimator.CanMoveFeature(activeFeatureType, desiredPosition, minDelta);
		}
	}

	private void RefreshScaleButton(Button3D button, bool larger, float minDelta)
	{
		if (button != null)
		{
			float desiredScale = CalculateDesiredFeatureScale(activeFeatureType, larger);
			button.Interactable = Player.LocalPlayer.FacialAnimator.CanScaleFeature(activeFeatureType, desiredScale, minDelta);
		}
	}

	private void RefreshFeatureButtonIcons()
	{
		RefreshFeatureButtonIcon(eyesButton, FaceFeatureType.Eye);
		RefreshFeatureButtonIcon(mouthButton, FaceFeatureType.Mouth);
	}

	private void RefreshFeatureButtonIcon(RadioButton3D button, FaceFeatureType featureType)
	{
		if (!Player.LocalPlayerExists || !(button != null))
		{
			return;
		}
		FaceFeatureBase selectedFaceFeature = Player.LocalPlayer.FacialAnimator.GetSelectedFaceFeature(featureType);
		if (selectedFaceFeature != null)
		{
			Sprite menuButtonSprite = selectedFaceFeature.MenuButtonSprite;
			if (menuButtonSprite != null)
			{
				button.OnSprite = menuButtonSprite;
				button.OffSprite = menuButtonSprite;
			}
		}
	}

	private void RefreshAllColorButtonStates()
	{
		if (Player.LocalPlayerExists)
		{
			ColorVault.ColorToGuid hairColor = Player.LocalPlayer.PlayerOutfit.HairColor;
			RefreshColorButtonStates(hairColor, hairColorButtons);
			ColorVault.ColorToGuid beardColor = Player.LocalPlayer.PlayerOutfit.BeardColor;
			RefreshColorButtonStates(beardColor, beardColorButtons);
			ColorVault.ColorToGuid skinColor = Player.LocalPlayer.PlayerOutfit.SkinColor;
			RefreshColorButtonStates(skinColor, skinColorButtons);
		}
	}

	private void RefreshColorButtonStates(ColorVault.ColorToGuid activeColor, List<ColorButton> buttons)
	{
		if (!Player.LocalPlayerExists || buttons == null)
		{
			return;
		}
		foreach (ColorButton button in buttons)
		{
			if (button.Color.GuidString == activeColor.guidString)
			{
				button.RadioButton.IsCurrent = true;
			}
			else
			{
				button.RadioButton.ForceRelease();
			}
		}
	}
}
public class DormroomOOBEFlow : OOBEFlowBase
{
	private enum DrawersMode
	{
		AllRealDrawersEnabled,
		TutorialDrawerOnlyEnabled,
		NoneEnabled
	}

	[SerializeField]
	private float timeBetweenStates = 1f;

