	[SerializeField]
	private GameObject playerTypeButtonsParent;

	[SerializeField]
	private ChargePhysicalButton walkModeButton;

	[SerializeField]
	private ChargePhysicalButton teleportModeButton;

	private List<Action<bool>> drawerSelectedCallbacks;

	private bool buttonEnabled = true;

	private bool NUXRunning;

	private bool isTrueNewUser;

	private WatchUI watchMenu;

	private HomeScreenFlow homeScreen;

	private ProfileWatchUIFlow profileMenu;

	private BrowseRoomsScreen browseRoomsMenu;

	private StoreScreen storeMenu;

	private InputField3D profileMenuNameInputField;

	private RecRoomAudioClip howToOpenMenuAudio;

	private IEnumerator Start()
	{
		ChargePhysicalButton rerunButton = rerunTutorialButton.GetComponentInChildren<ChargePhysicalButton>();
		rerunButton.ChargedEvent += Button_RerunOOBEFlow;
		if (ShouldStartNUX())
		{
			AnalyticsHelper.RecordPlayerAccountStartedMonth();
			LockerroomOOBEFlow.FirstTimeInRecCenter = true;
			TutorialManager.PickedUpStickyToolNumberOfTimes = 0;
			SingletonMonoBehaviour<TutorialManager>.Instance.SetFirstTimeInForNewUser();
			isTrueNewUser = true;
			SingletonMonoBehaviour<TutorialManager>.Instance.MarkUserTried(TutorialManager.UserTracking.HasLearnedAboutNewWatch_2018_08_20);
			if (Objectives.LookupCachedObjectiveGroup(1) == null)
			{
				Objectives.ClearGroup(1, null);
			}
			StartCoroutine(RunOOBEFlow());
		}
		else
		{
			while (!Player.LocalPlayerExists)
			{
				yield return null;
			}
			while (SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.FadedOut)
			{
				yield return null;
			}
			SingletonMonoBehaviour<TutorialManager>.Instance.TryTeachableMoment<CreateCustomRoomTeachableMoment>();
		}
	}

	private bool ShouldStartNUX()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Complete)
		{
			return false;
		}
		if ((SingletonMonoBehaviour<TutorialManager>.Instance.NUXState >= TutorialManager.NUXFlowState.Q2A_WelcomeToPaddleball && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState < TutorialManager.NUXFlowState.TDU_OpenTokensBox) || (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState >= TutorialManager.NUXFlowState.TeleportToMannequin && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState <= TutorialManager.NUXFlowState.LearnStop))
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
			return false;
		}
		return true;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (rerunTutorialButton != null)
		{
			ChargePhysicalButton componentInChildren = rerunTutorialButton.GetComponentInChildren<ChargePhysicalButton>();
			componentInChildren.ChargedEvent -= Button_RerunOOBEFlow;
		}
		if (NUXRunning && SingletonMonoBehaviour<TutorialManager>.Instance != null && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState != TutorialManager.NUXFlowState.Q2A_WelcomeToPaddleball && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState != TutorialManager.NUXFlowState.Q2A_WelcomeToPaintball && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState != TutorialManager.NUXFlowState.Q2A_WelcomeToUGCRoom)
		{
			FinishNUXState(InterruptableFlow.FlowState.Incomplete);
		}
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.DailiesObjectiveTracker.RemoveObjectiveTrackingSuppressed(this);
			Player.LocalPlayer.OrientationObjectiveTracker.RemoveObjectiveTrackingSuppressed(this);
		}
		if (watchMenu != null)
		{
			watchMenu.UnpauseMessages(this);
		}
		DisableDrawerHighlightsAndSelectEvents();
	}

	public void Button_RerunOOBEFlow(ChargePhysicalButton button)
	{
		if (!SingletonMonoBehaviour<TutorialManager>.Instance.IsTeachableMomentPlaying)
		{
			if (buttonEnabled)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.NotRan;
				StartCoroutine(MovePlayerAndStartOOBE());
			}
			buttonEnabled = false;
		}
	}

	private IEnumerator MovePlayerAndStartOOBE()
	{
		Player.LocalPlayer.Respawn(rerunTutorialSpawnPoint.LocalPosition, rerunTutorialSpawnPoint.LocalRotation, rerunTutorialSpawnPoint.Parent);
		yield return new WaitForSecondsRealtime(1f);
		yield return RunOOBEFlow();
		buttonEnabled = true;
	}

	private IEnumerator RunOOBEFlow()
	{
		NUXRunning = true;
		PhotonNetwork.player.SetCustomProperties("prev_activity", "oobe");
		if (SingletonMonoBehaviour<TutorialManager>.Instance.HasCompletedTutorial && Player.LocalPlayerExists)
		{
			Player.LocalPlayer.Backpack.RecallAllTools();
		}
		SetupDormForOOBE();
		yield return RunWaitForPlayerSpawn();
		Player.LocalPlayer.EnableOutOfBoundsCheck(enable: false);
		drawerRack.InitializeTutorialOutfits();
		Player.LocalPlayer.PlayerUI.MenusCanBeOpened = false;
		watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		SetupWatchForNUX();
		Player.LocalPlayer.DailiesObjectiveTracker.AddObjectiveTrackingSuppressed(this);
		Player.LocalPlayer.OrientationObjectiveTracker.AddObjectiveTrackingSuppressed(this);
		watchMenu.PauseMessages(this);
		watchMenu.WatchMenuProjector.AuthorityCloseMenu();
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.ScreenPlayerController.AddFavoriteToolRestriction(this);
			SingletonMonoBehaviour<LocalPlayerController>.Instance.ScreenPlayerController.QuickCommsController.AddRestriction(this);
		}
		yield return RunWaitForUserIsPresent();
		howToOpenMenuAudio = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(SingletonMonoBehaviour<TutorialManager>.Instance.GetInputSpecificVOType(TutorialManager.TutorialAudioType.LookAtWristToViewWatch));
		string tokensNUXExperimentName = typeof(SplitTesting.TokensAndDressUpNUX_2018_07_16).ToString();
		string skipTokensNUXSegment = SplitTesting.TokensAndDressUpNUX_2018_07_16.SkipTokensAndDressUpNUX.ToString();
		string runTokensNUXSegment = SplitTesting.TokensAndDressUpNUX_2018_07_16.RunTokensAndDressUpNUX.ToString();
		string assignedTokensNUXSegment;
		if (!isTrueNewUser || SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
		{
			assignedTokensNUXSegment = skipTokensNUXSegment;
		}
		else
		{
			assignedTokensNUXSegment = SingletonMonoBehaviour<SplitTesting>.Instance.GetExperimentSegment(tokensNUXExperimentName);
			if (assignedTokensNUXSegment == null)
			{
				assignedTokensNUXSegment = skipTokensNUXSegment;
			}
		}
		bool shouldRunTokensNUX = assignedTokensNUXSegment == runTokensNUXSegment;
		bool tokensBalanceSuccessfullyModified = false;
		string tduNUXError = string.Empty;
		if (shouldRunTokensNUX)
		{
			Storefronts.GrantBalanceRequest[] balanceAdds = new Storefronts.GrantBalanceRequest[1]
			{
				new Storefronts.GrantBalanceRequest
				{
					Multiplier = 1f,
					BalanceAddType = StorefrontBalanceAddTypes.ChecklistCredit
				}
			};
			Storefronts.ModifyBalance(CurrencyType.RecCenterTokens, balanceAdds, delegate(string error, Storefronts.BalanceUpdateResponseDTO<Storefronts.RewardBalanceModificationDTO> updateResponse)
			{
				if (string.IsNullOrEmpty(error) && updateResponse != null && updateResponse.BalanceUpdates.Count == 1 && updateResponse.BalanceUpdates[0].UpdateResponse == Storefronts.UpdateResponseTypes.OK)
				{
					tokensBalanceSuccessfullyModified = true;
				}
				else
				{
					tokensBalanceSuccessfullyModified = false;
					tduNUXError = error;
					UnityEngine.Debug.LogWarningFormat("Failed to modify tokens balance during TDU NUX. Error: {0}", error);
				}
			});
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState != TutorialManager.NUXFlowState.Complete)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.NotRan;
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.NotRan)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			AudioManager.Play3DSFX(logoRezClip, Map3D.transform.position);
			yield return new WaitForSeconds(2f);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Dorm Room", 2f);
			yield return new WaitForSeconds(1f);
			if (introAudio != null)
			{
				introAudio.Play();
			}
			FinishNUXState(InterruptableFlow.FlowState.Complete);
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TutorialStart;
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.TutorialStart)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Welcome);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.ThisIsYourDorm);
			yield return new WaitForSeconds(timeBetweenStates);
			FinishNUXState(InterruptableFlow.FlowState.Complete);
			if (SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.SCREENS_Walk;
			}
			else
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.ChooseVRPlayerType;
			}
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.ChooseVRPlayerType)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.ThereAreTwoWaysToMove);
			bool modeAssigned = false;
			ChargePhysicalButton.Charged onTeleportButtonClicked = delegate
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = VRMovementMode.TELEPORT;
				modeAssigned = true;
			};
			ChargePhysicalButton.Charged onWalkButtonClicked = delegate
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = VRMovementMode.WALK;
				SingletonMonoBehaviour<SettingsManager>.Instance.WalkingHandMode = WalkHandMode.LEFT_HAND_CONTROLS;
				modeAssigned = true;
			};
			teleportModeButton.ChargedEvent += onTeleportButtonClicked;
			walkModeButton.ChargedEvent += onWalkButtonClicked;
			PositionVRPlayerTypeButtons();
			playerTypeButtonsParent.SetActive(value: true);
			RecRoomAudioClip pickModeAudio = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.PickWhichWayYoudLikeToMove);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(pickModeAudio);
			yield return RunInterruptableFlow(initialHelpVO: SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.WeRecommendTeleport), condition: () => modeAssigned ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, repeatingHelp: pickModeAudio, onComplete: delegate
			{
				tutorialDrawer.SelectButton.interactable = false;
				HideHelpPopup();
			}, helpInterval: 15f, maxHelpCount: -1, debugString: "ChooseVRPlayerType");
			teleportModeButton.ChargedEvent -= onTeleportButtonClicked;
			walkModeButton.ChargedEvent -= onWalkButtonClicked;
			playerTypeButtonsParent.SetActive(value: false);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Great);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.YouCanChangeBetweenWalkingAndTeleporting);
			FinishNUXState(InterruptableFlow.FlowState.Complete);
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_WALK)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.VR_Walk;
			}
			else
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Teleport;
			}
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Teleport)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			RecRoomAudioClip initialAudio = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.TeleportToMiddleOfRoom);
			yield return RunTeleportTutorial(teleportTargetRug, initialAudio, initialAudio, -1);
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			yield return new WaitForSeconds(0.5f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Perfect);
			yield return new WaitForSeconds(0.5f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.WaveAtYourself);
			yield return new WaitForSeconds(timeBetweenStates);
			FinishNUXState();
			if (shouldRunTokensNUX && !tokensBalanceSuccessfullyModified)
			{
				shouldRunTokensNUX = false;
				AnalyticsHelper.NUXFailedToStartTDUNUX(tduNUXError);
			}
			if (shouldRunTokensNUX)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TDU_OpenTokensBox;
			}
			else
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.ChooseHairSkin;
			}
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.VR_Walk)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			RecRoomAudioClip initialAudio2 = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.SCREENS_WalkToGlowingCircle);
			yield return RunWalkTutorial(teleportTargetRug, initialAudio2, initialAudio2, -1);
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			Func<InterruptableFlow.FlowState> playerFacingMirror = delegate
			{
				float num = 0.85f;
				Transform transform = Player.LocalPlayer.Head.transform;
				return (Vector3.Dot(transform.transform.forward, (changingRoomMenu.transform.position - transform.transform.position).normalized) > num) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete;
			};
			InterruptableFlow.FlowState playerFacedMirror = playerFacingMirror();
			if (SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled && playerFacedMirror != InterruptableFlow.FlowState.Complete)
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Great);
				ShowNote(TutorialManager.HelpType.SwipeButton);
				ShowLookAtHelpPopup("Look at mirror");
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.RotateToMirror_RightController);
				RecRoomAudioClip nullClip = null;
				yield return RunInterruptableFlow(playerFacingMirror, null, nullClip, delegate(InterruptableFlow.FlowState result)
				{
					HideHelpPopup();
					playerFacedMirror = result;
				}, 5f, 3, "FaceMirror_VRWalk");
			}
			if (playerFacedMirror == InterruptableFlow.FlowState.Complete)
			{
				yield return new WaitForSeconds(0.5f);
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Perfect);
				yield return new WaitForSeconds(0.5f);
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.WaveAtYourself);
			}
			yield return new WaitForSeconds(timeBetweenStates);
			FinishNUXState();
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.ChooseHairSkin;
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.SCREENS_Walk)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.SCREENS_OneWayToMoveIsWalking);
			RecRoomAudioClip initialAudio3 = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.SCREENS_WalkToGlowingCircle);
			yield return RunWalkTutorial(teleportTargetRug, initialAudio3, initialAudio3, -1);
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Perfect);
			yield return new WaitForSeconds(timeBetweenStates);
			FinishNUXState();
			if (shouldRunTokensNUX && !tokensBalanceSuccessfullyModified)
			{
				shouldRunTokensNUX = false;
				AnalyticsHelper.NUXFailedToStartTDUNUX(tduNUXError);
			}
			if (shouldRunTokensNUX)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TDU_OpenTokensBox;
			}
			else
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.ChooseHairSkin;
			}
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.ChooseHairSkin)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			ShowOpenDrawerHelpPopup();
			RecRoomAudioClip initialAudio4 = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(SingletonMonoBehaviour<TutorialManager>.Instance.GetInputSpecificVOType(TutorialManager.TutorialAudioType.WhenReadyOpenShirtDrawer));
			EnableDrawers(DrawersMode.TutorialDrawerOnlyEnabled);
			highlightedRenderers.Add(shirtDrawerRenderer);
			bool drawerOpened = false;
			tutorialDrawer.DrawerSelected = delegate(bool isOpen)
			{
				drawerOpened = isOpen;
			};
			InterruptableFlow.FlowState openedDrawer = InterruptableFlow.FlowState.Incomplete;
			yield return RunInterruptableFlow(() => drawerOpened ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, initialAudio4, initialAudio4, delegate(InterruptableFlow.FlowState result)
			{
				tutorialDrawer.SelectButton.interactable = false;
				HideHelpPopup();
				openedDrawer = result;
			}, 15f, 3, "OpenDrawer");
			Player.LocalPlayer.AddToolInteractionRestriction(this);
			highlightedRenderers.Remove(shirtDrawerRenderer);
			yield return new WaitForSeconds(timeBetweenStates);
			FinishNUXState(openedDrawer);
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.ChooseShirt2;
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState <= TutorialManager.NUXFlowState.ChooseShirt2)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			tutorialDrawer.IsSelected = true;
			Player.LocalPlayer.AddToolInteractionRestriction(this);
			RecRoomAudioClip initialAudio5 = null;
			RecRoomAudioClip repeatingAudio = null;
			initialAudio5 = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(SingletonMonoBehaviour<TutorialManager>.Instance.GetInputSpecificVOType(TutorialManager.TutorialAudioType.GrabWhiteAndOrangeShirt));
			repeatingAudio = initialAudio5;
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Great);
			Player.LocalPlayer.RemoveToolInteractionRestriction(this);
			if (SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.PlayVO(SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(SingletonMonoBehaviour<TutorialManager>.Instance.GetInputSpecificVOType(TutorialManager.TutorialAudioType.SwipeRotateToHighlightedShirt)));
				ShowNote(TutorialManager.HelpType.SwipeButton);
			}
			ShowLookAtHelpPopup("Look at shirt");
			InterruptableFlow.FlowState equippedShirt = InterruptableFlow.FlowState.Incomplete;
			OutfitTool shirt2 = tutorialDrawer.Tools[1].GetComponent<OutfitTool>();
			highlightedRenderers.Add(shirt2.ItemRenderer);
			Transform viewTransform = ((!SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled) ? Player.LocalPlayer.Head.transform : SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera.transform);
			Func<InterruptableFlow.FlowState> playerFacedShirt = delegate
			{
				float num = ((!SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled) ? 0.6f : 0.8f);
				return (Vector3.Dot(viewTransform.forward, (shirt2.transform.position - viewTransform.position).normalized) > num) ? InterruptableFlow.FlowState.Complete : ((equippedShirt == InterruptableFlow.FlowState.Complete) ? InterruptableFlow.FlowState.Fail : InterruptableFlow.FlowState.Incomplete);
			};
			StartCoroutine(RunInterruptableFlow(playerFacedShirt, delegate(InterruptableFlow.FlowState result)
			{
				if (result == InterruptableFlow.FlowState.Complete)
				{
					ShowNote(TutorialManager.HelpType.GrabButton);
					ShowClothesHelpPopup();
					SingletonMonoBehaviour<TutorialManager>.Instance.PlayVO(repeatingAudio);
				}
			}, 15f, 3, "FaceShirt2"));
			shirt2.EquipStateChanged = delegate(OutfitTool.PlayerEquipState equipState)
			{
				if (equipState == OutfitTool.PlayerEquipState.Wearing)
				{
					equippedShirt = InterruptableFlow.FlowState.Complete;
				}
			};
			yield return RunInterruptableFlow(() => equippedShirt, null, repeatingAudio, delegate
			{
				highlightedRenderers.Remove(shirt2.ItemRenderer);
			}, 15f, 3, "EquipShirt2");
			InterruptableFlow.FlowState playerFacedMirror2 = InterruptableFlow.FlowState.Incomplete;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled)
			{
				ShowNote(TutorialManager.HelpType.SwipeButton);
				ShowLookAtHelpPopup("Look at mirror");
				if (SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
				{
					yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.SCREENS_TurnToFaceMirror);
				}
				else
				{
					yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.SwipeRotateToMirror);
				}
				Func<InterruptableFlow.FlowState> playerFacingMirror2 = delegate
				{
					float num = ((!SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled) ? 0.5f : 0.8f);
					return (Vector3.Dot(viewTransform.transform.forward, (changingRoomMenu.transform.position - viewTransform.transform.position).normalized) > num) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete;
				};
				RecRoomAudioClip nullClip2 = null;
				yield return RunInterruptableFlow(playerFacingMirror2, null, nullClip2, delegate(InterruptableFlow.FlowState result)
				{
					HideHelpPopup();
					playerFacedMirror2 = result;
				}, 5f, 3, "FaceMirror");
			}
			yield return new WaitForSeconds(timeBetweenStates);
			drawerRack.PlayOpenDrawerAudio();
			tutorialDrawer.IsSelected = false;
			InterruptableFlow.FlowState stateResult = ((equippedShirt == InterruptableFlow.FlowState.Timeout || playerFacedMirror2 == InterruptableFlow.FlowState.Timeout) ? InterruptableFlow.FlowState.Timeout : ((equippedShirt == InterruptableFlow.FlowState.Complete && playerFacedMirror2 == InterruptableFlow.FlowState.Complete) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete));
			FinishNUXState(stateResult);
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.OpenMenu;
			HideHelpPopup();
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.TDU_OpenTokensBox)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.TDU_LetsCustomizeYourOutfit);
			SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(Avatars.GiftPackages, useSpawnLocation: false, dismissExistingGift: true);
			float waitStartTime = UnityEngine.Time.time;
			while (!SingletonMonoBehaviour<GiftManager>.Instance.IsAGiftBoxCurrentlySpawned && UnityEngine.Time.time - waitStartTime < 3f)
			{
				yield return null;
			}
			if (!SingletonMonoBehaviour<GiftManager>.Instance.IsAGiftBoxCurrentlySpawned)
			{
				SingletonMonoBehaviour<GiftManager>.Instance.StopReceiveGiftsCoroutine();
				AnalyticsHelper.NUXTimedOutWaitingForTokensBox();
				UnityEngine.Debug.LogWarning("Timed out waiting for tokens box to spawn in TDU NUX.");
				FinishNUXState();
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TDU_OpenClothesDrawer;
			}
			else
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.TDU_HereAreSomeTokens);
				ShowHelpPopup(TutorialManager.HelpType.GrabButton);
				ShowNote(TutorialManager.HelpType.GrabButton);
				RecRoomAudioClip initialAudio6 = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.TDU_PullTabToOpenBox);
				yield return RunInterruptableFlow(() => (!SingletonMonoBehaviour<GiftManager>.Instance.IsAGiftBoxCurrentlySpawned) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, initialAudio6, initialAudio6, delegate
				{
				}, 15f, -1, string.Empty);
				HideHelpPopup();
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.TDU_EnoughToBuySomething);
				FinishNUXState();
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TDU_OpenMenu;
			}
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.TDU_OpenMenu)
		{
			StartNUXState();
			Player.LocalPlayer.PlayerUI.MenusCanBeOpened = true;
			ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
			ShowNote(TutorialManager.HelpType.OpenWatch);
			watchMenu.PopAllFlows();
			VibrateBothHands(Player.LocalPlayer);
			ShowNote(TutorialManager.HelpType.OpenWatch);
			yield return RunInterruptableFlow(() => watchMenu.FullyVisible ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, howToOpenMenuAudio, howToOpenMenuAudio, delegate(InterruptableFlow.FlowState result)
			{
				FinishNUXState(result);
			}, 15f, -1, "WaitUntilPlayerOpensMenuNoTimeout");
			HideHelpPopup();
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.TDU_ClickStoreButton;
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.TDU_ClickStoreButton)
		{
			StartNUXState();
			homeScreen.ClearHighlights();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
