			yield return RunInterruptableFlow(() => paintballButtonPressed ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, initialAudio13, initialAudio13, delegate
			{
			}, 15f, -1, string.Empty);
			paintballButton.AttractHighlighted = false;
			watchMenu.BasicInteractionRestriction.AllElementsRestricted = true;
			GoToRoomConditionalButton.OnButtonAction -= paintballButtonListener;
		}
		else
		{
			HideHelpPopup();
			yield return new WaitForSeconds(timeBetweenStates);
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			StartNUXState();
			Player.LocalPlayer.EnableOutOfBoundsCheck(enable: true);
			Player.LocalPlayer.DailiesObjectiveTracker.RemoveObjectiveTrackingSuppressed(this);
			Player.LocalPlayer.OrientationObjectiveTracker.RemoveObjectiveTrackingSuppressed(this);
			watchMenu.UnpauseMessages(this);
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
			{
				SingletonMonoBehaviour<LocalPlayerController>.Instance.ScreenPlayerController.RemoveFavoriteToolRestriction(this);
				SingletonMonoBehaviour<LocalPlayerController>.Instance.ScreenPlayerController.QuickCommsController.RemoveRestriction(this);
			}
			watchMenu.Locked = false;
			homeScreen.ClearHighlights();
			watchMenu.BasicInteractionRestriction.AllElementsRestricted = false;
			HideAllNotes();
			lockerRoomDoor.gameObject.SetActive(value: true);
			lockerRoomDoorSign.SetActive(value: true);
			lockerRoomDoor.IsLocked = false;
			StartCoroutine(RunSpawnTools());
			privacyPolicyButton.SetActive(value: true);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.ReadyToGoPlay);
			StartCoroutine(RunStopIntroAudio(5f));
			yield return new WaitForSeconds(0.5f);
			FinishNUXState(InterruptableFlow.FlowState.Complete);
			NUXRunning = false;
			EnableDrawers(DrawersMode.AllRealDrawersEnabled);
			RecRoomAudioClip whenReadyTeleportThroughDoorClip = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.TeleportThroughDoor);
			for (int i = 0; i < 3; i++)
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(whenReadyTeleportThroughDoorClip);
				SingletonMonoBehaviour<TutorialManager>.Instance.PlayAttentionHelper(lockerRoomDoor.transform.position + Vector3.up);
				yield return new WaitForSeconds(10f);
			}
		}
	}

