	private void EnableDrawers(DrawersMode mode)
	{
		drawerRack.DrawersMenu.gameObject.SetActive(mode != DrawersMode.NoneEnabled);
		if (skinsRack != null)
		{
			skinsRack.DrawersMenu.gameObject.SetActive(mode != DrawersMode.NoneEnabled);
		}
		SpawnedEquipmentDrawer[] array = UnityEngine.Object.FindObjectsOfType<SpawnedEquipmentDrawer>();
		foreach (SpawnedEquipmentDrawer spawnedEquipmentDrawer in array)
		{
			bool interactable = true;
			bool active = true;
			switch (mode)
			{
			case DrawersMode.AllRealDrawersEnabled:
				interactable = spawnedEquipmentDrawer != tutorialDrawer;
				active = spawnedEquipmentDrawer != tutorialDrawer;
				break;
			case DrawersMode.TutorialDrawerOnlyEnabled:
				interactable = spawnedEquipmentDrawer == tutorialDrawer;
				active = spawnedEquipmentDrawer != shirtDrawer;
				break;
			case DrawersMode.NoneEnabled:
				interactable = false;
				active = false;
				break;
			}
			spawnedEquipmentDrawer.SelectButton.interactable = interactable;
			spawnedEquipmentDrawer.SelectButton.gameObject.SetActive(active);
		}
	}

	private void CloseAllDrawers()
	{
		for (int i = 0; i < drawerRack.Drawers.Count; i++)
		{
			drawerRack.Drawers[i].IsSelected = false;
		}
		if (skinsRack != null)
		{
			for (int j = 0; j < skinsRack.Drawers.Count; j++)
			{
				skinsRack.Drawers[j].IsSelected = false;
			}
		}
	}

	private void EnableDrawerHighlightsAndSelectEvents()
	{
		if (allDrawers.Length != allDrawerRenderers.Length)
		{
			return;
		}
		drawerSelectedCallbacks = new List<Action<bool>>();
		for (int i = 0; i < allDrawers.Length; i++)
		{
			SpawnedEquipmentDrawer spawnedEquipmentDrawer = allDrawers[i];
			Renderer renderer = allDrawerRenderers[i];
			if (spawnedEquipmentDrawer != null && renderer != null)
			{
				highlightedRenderers.Add(renderer);
				Action<bool> action = delegate
				{
					OnDrawerSelected(renderer);
				};
				drawerSelectedCallbacks.Add(action);
				spawnedEquipmentDrawer.DrawerSelected = (Action<bool>)Delegate.Combine(spawnedEquipmentDrawer.DrawerSelected, action);
			}
		}
	}

	private void DisableDrawerHighlightsAndSelectEvents()
	{
		if (allDrawers.Length != allDrawerRenderers.Length)
		{
			return;
		}
		for (int i = 0; i < allDrawers.Length; i++)
		{
			SpawnedEquipmentDrawer spawnedEquipmentDrawer = allDrawers[i];
			Renderer renderer = allDrawerRenderers[i];
			if (spawnedEquipmentDrawer != null && renderer != null)
			{
				highlightedRenderers.Remove(renderer);
				if (spawnedEquipmentDrawer.DrawerSelected != null && drawerSelectedCallbacks != null && drawerSelectedCallbacks[i] != null)
				{
					spawnedEquipmentDrawer.DrawerSelected = (Action<bool>)Delegate.Remove(spawnedEquipmentDrawer.DrawerSelected, drawerSelectedCallbacks[i]);
				}
			}
		}
	}

	private void OnDrawerSelected(Renderer highlightRenderer)
	{
		highlightedRenderers.Remove(highlightRenderer);
	}

