public class DormroomSceneManager : RecRoomSceneManager
{
	private const string blockedUserMessageFormat = "{0}.\nYou can rejoin in {1}";

	[Header("Room Locking")]
	[SerializeField]
	private TeleportationPortal[] exitTeleportationPortals;

	[SerializeField]
	private GameObject rerunTutorialButton;

	protected override IEnumerator Start()
	{
		yield return base.Start();
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Complete)
		{
			yield return BlockedCoroutine();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
	}

	private IEnumerator BlockedCoroutine()
	{
		int blockDuration = 0;
		if (PlayerReporting.CurrentBlockDetail != null)
		{
			blockDuration = PlayerReporting.CurrentBlockDetail.Duration;
		}
		if (blockDuration > 0)
		{
			SetRoomExitsActive(active: false);
			yield return ShowBlockedMessage(blockDuration);
			SetRoomExitsActive(active: true);
		}
	}

	private void SetRoomExitsActive(bool active)
	{
		TeleportationPortal[] array = exitTeleportationPortals;
		foreach (TeleportationPortal teleportationPortal in array)
		{
			if (teleportationPortal.Target == null)
			{
				teleportationPortal.gameObject.SetActive(active);
			}
		}
		if (rerunTutorialButton != null)
		{
			rerunTutorialButton.SetActive(active);
		}
	}

	private IEnumerator ShowBlockedMessage(float blockDuration)
	{
		float blockStartTime = UnityEngine.Time.unscaledTime;
		while (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerUI.WatchMenu == null)
		{
			yield return null;
		}
		PlayerUI playerUI = Player.LocalPlayer.PlayerUI;
		WatchUI menu = Player.LocalPlayer.PlayerUI.WatchMenu;
		menu.BasicInteractionRestriction.AllElementsRestricted = true;
		UIAccountStatusDialog accountStatusDialog = menu.GetFlowByType<UIAccountStatusDialog>();
		menu.PushFlow(accountStatusDialog);
		menu.PlayAttract();
		menu.Locked = true;
		while (UnityEngine.Time.unscaledTime - blockStartTime < blockDuration)
		{
			accountStatusDialog.UpdateUIState(UIAccountStatusDialog.Status.Banned);
			yield return new WaitForSeconds(1f);
		}
		PlayerReporting.CurrentBlockDetail.Duration = 0;
		menu.Locked = false;
		menu.PopFlow();
		menu.BasicInteractionRestriction.AllElementsRestricted = false;
	}

	public void LockRoom(string title, string lockedReason)
	{
		SetRoomExitsActive(active: false);
		if (Player.LocalPlayerExists)
		{
			WatchUI watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			watchMenu.BasicInteractionRestriction.AllElementsRestricted = true;
			watchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.LOCKED, title, lockedReason);
			watchMenu.Locked = true;
		}
	}

	public void Button_PrivacyPolicy()
	{
		WebBrowser.ShowPrivacyPolicyWebPage();
	}

	public void Button_FAQ()
	{
		WebBrowser.ShowHelpWebPage();
	}
}
public class FeaturedCreatorBulletinBoardUI : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameObject creatorContainer;

	[SerializeField]
	private GameObject defaultContainer;

	[SerializeField]
	private GameObject viewRoomsButton;

	[SerializeField]
	private Button3D howToBuildButton;

	[SerializeField]
	private TextMeshProUGUI titleText;

	[SerializeField]
	private TextMeshProUGUI highlightsButtonText;

	private string defaultTitleText;

	private string defaultHighlightsButtonText;

	private void Start()
	{
		defaultTitleText = titleText.text;
		defaultHighlightsButtonText = highlightsButtonText.text;
		Refresh();
		CommunityBoard.CurrentBoardUpdated += Refresh;
	}

	private void OnDestroy()
	{
		CommunityBoard.CurrentBoardUpdated -= Refresh;
	}

	private void Refresh()
	{
		CommunityBoard.CommunityBoardDTO current = CommunityBoard.Current;
		int? num = current?.FeaturedPlayer?.Id;
		if (num.HasValue && num.GetValueOrDefault() > 0)
		{
			if ((object)creatorContainer != null)
			{
				creatorContainer.gameObject.SetActive(value: true);
			}
			if ((object)viewRoomsButton != null)
			{
				viewRoomsButton.gameObject.SetActive(value: true);
			}
			if ((object)defaultContainer != null)
			{
				defaultContainer.gameObject.SetActive(value: false);
			}
			PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
			{
				playerSpecificUIBehaviour.SetPlayer(current.FeaturedPlayer.Id);
			}
			titleText.text = ((!string.IsNullOrEmpty(current.FeaturedPlayer.TitleOverride)) ? current.FeaturedPlayer.TitleOverride : defaultTitleText);
			highlightsButtonText.text = ((!string.IsNullOrEmpty(current.FeaturedPlayer.UrlOverride)) ? "Player highlights" : defaultHighlightsButtonText);
		}
		else
		{
			if ((object)creatorContainer != null)
			{
				creatorContainer.gameObject.SetActive(value: false);
			}
			if ((object)viewRoomsButton != null)
			{
				viewRoomsButton.gameObject.SetActive(value: false);
			}
			if ((object)defaultContainer != null)
			{
				defaultContainer.gameObject.SetActive(value: false);
			}
		}
	}

	public void Button_Highlights()
	{
		if (string.IsNullOrEmpty(CommunityBoard.Current.FeaturedPlayer.UrlOverride))
		{
			Profile profile = Profiles.Get(CommunityBoard.Current.FeaturedPlayer.Id);
			if (profile != null)
			{
				BrowseRoomsScreen flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<BrowseRoomsScreen>();
				string query = $"@{profile.Username}";
				Vector3 optimalDetachedMenuPositionHeadHeightWorldSpace = Player.LocalPlayer.PlayerUI.WatchMenuProjector.OptimalDetachedMenuPositionHeadHeightWorldSpace;
				flowByType.SearchByDoorSelection(query, optimalDetachedMenuPositionHeadHeightWorldSpace);
			}
		}
		else
		{
			WebBrowser.ShowWebPage(CommunityBoard.Current.FeaturedPlayer.UrlOverride, "Player highlights", showPrefix: false);
		}
		AnalyticsHelper.AddCustomStatsCounter("featuredCreatorHighlights", 1);
	}

	public void Button_HowToBuild()
	{
		WebBrowser.ShowWebPage("https://recroom.happyfox.com/kb/article/43-custom-rooms-tools-and-tutorials", "how to build");
	}

	public void Button_ViewProfile()
	{
		Profile profile = Profiles.Get(CommunityBoard.Current.FeaturedPlayer.Id);
		if (profile != null && Player.LocalPlayerExists)
		{
			WatchUI watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			WatchMenuProjector watchMenuProjector = Player.LocalPlayer.PlayerUI.WatchMenuProjector;
			PlayerDetailsWatchUIFlow flowByType = watchMenu.GetFlowByType<PlayerDetailsWatchUIFlow>();
			if (!watchMenuProjector.IsMenuOpen)
			{
				watchMenuProjector.AuthorityOpenMenuDetached(watchMenuProjector.OptimalDetachedMenuPositionHeadHeightWorldSpace, force: false);
			}
			if (watchMenu.CurrentFlow != flowByType)
			{
				flowByType.SetProfile(profile);
				watchMenu.PushFlow(flowByType);
			}
			AnalyticsHelper.AddCustomStatsCounter("featuredCreatorProfile", 1);
		}
	}
}
public class FeaturedRoomsBulletinBoardUI : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct FeaturedRoomData
	{
		public string roomName;

		public long roomId;

		public Texture2D featuredImage;
	}

	private struct RoomServerData
	{
		public RecNet.Room roomInfo;

		public bool isFull;

		public bool hasOtherError;
	}

	[SerializeField]
	private GameObject featuredRoomsContainer;

	[SerializeField]
	private GameObject defaultContainer;

	[SerializeField]
	private TextMeshProUGUI featuredRoomGroupName;

	[SerializeField]
	private TextMeshProUGUI featuredRoomName;

	[SerializeField]
	private RawImage featuredRoomImage;

	[SerializeField]
	private float displayTimePerRoom = 5f;

	[SerializeField]
	private Animator contentRefreshAnimator;

	[SerializeField]
	private GameObject roomFullMessage;

	[SerializeField]
	private GameObject roomErrorMessage;

	[SerializeField]
	private Button3DBase goToRoomButton;

	private int currentRoomIdx;

	private float displayDuration;

	private bool isJoiningRoom;

	private int joinRequestRoomIdx;

	private FeaturedRoomData[] roomList = new FeaturedRoomData[0];

	private RoomServerData[] roomServerDataList;

	private void Start()
	{
		Refresh();
		CommunityBoard.CurrentBoardUpdated += Refresh;
	}

	private void OnEnable()
	{
		contentRefreshAnimator.SetBool("Visible", value: true);
	}

	private void OnDestroy()
	{
		CommunityBoard.CurrentBoardUpdated -= Refresh;
	}

	private void Update()
	{
		if (roomList.Length > 0)
		{
			displayDuration += UnityEngine.Time.deltaTime;
			if (displayDuration >= displayTimePerRoom)
			{
				GoToNextImage();
				RefreshDisplay();
			}
		}
	}

	private void Refresh()
	{
		featuredRoomsContainer.SetActive(value: false);
		defaultContainer.SetActive(value: true);
		RecNet.Rooms.FeaturedRoomGroupDTO featuredRoomGroupDTO = CommunityBoard.Current?.FeaturedRoomGroup;
		if (!(this != null))
		{
			return;
		}
		int? num = featuredRoomGroupDTO?.FeaturedRooms.Count;
		if (!num.HasValue || num.GetValueOrDefault() <= 0)
		{
			return;
		}
		featuredRoomGroupName.text = featuredRoomGroupDTO.Name;
		List<RecNet.Rooms.FeaturedRoom> featuredRooms = featuredRoomGroupDTO.FeaturedRooms;
		roomList = new FeaturedRoomData[featuredRooms.Count];
		roomServerDataList = new RoomServerData[roomList.Length];
		for (int i = 0; i < roomServerDataList.Length; i++)
		{
			roomServerDataList[i] = default(RoomServerData);
		}
		for (int j = 0; j < featuredRooms.Count; j++)
		{
			int roomListIdx = j;
			roomList[roomListIdx].roomName = featuredRooms[j].RoomName;
			roomList[roomListIdx].roomId = featuredRooms[j].RoomId;
			roomList[roomListIdx].featuredImage = null;
			Images.GetImage(featuredRooms[roomListIdx].ImageName, generateMipMaps: false, overrideJuniorCheck: true, 512u).Then(delegate(Texture2D tex)
			{
				if (roomList != null)
				{
					roomList[roomListIdx].featuredImage = tex;
					if (featuredRoomsContainer != null && !featuredRoomsContainer.activeSelf)
					{
						currentRoomIdx = roomListIdx;
						featuredRoomsContainer.SetActive(value: true);
						defaultContainer.SetActive(value: false);
						contentRefreshAnimator.SetBool("Visible", value: true);
						RefreshDisplay();
					}
				}
			});
		}
	}

	private void GoToNextImage()
	{
		displayDuration = 0f;
		currentRoomIdx = (currentRoomIdx + 1) % roomList.Length;
	}

	private void RefreshDisplay()
	{
		int num = roomList.Length;
		int num2 = 0;
		while (roomList[currentRoomIdx].featuredImage == null)
		{
			GoToNextImage();
			num2++;
			if (num2 >= num)
			{
				UnityEngine.Debug.LogWarning("Could not enable featured rooms display... no images are available");
				return;
			}
		}
		featuredRoomName.text = $"^{roomList[currentRoomIdx].roomName}";
		featuredRoomImage.texture = roomList[currentRoomIdx].featuredImage;
		bool isFull = roomServerDataList[currentRoomIdx].isFull;
		bool hasOtherError = roomServerDataList[currentRoomIdx].hasOtherError;
		roomFullMessage.SetActive(isFull);
		roomErrorMessage.SetActive(hasOtherError && !isFull);
		goToRoomButton.Interactable = !isJoiningRoom && !isFull && !hasOtherError;
		contentRefreshAnimator.SetTrigger("Refresh");
	}

	private void GoToRoom(int roomIdx)
	{
		isJoiningRoom = true;
		string roomName = roomList[roomIdx].roomName;
		joinRequestRoomIdx = roomIdx;
		SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(roomName, SessionManager.LoadSceneSources.BULLETIN_BOARD_FEATURED_ROOMS, isPrivate: false, null, OnRoomJoinResponse);
	}

	private void OnRoomJoinResponse(GameSessions.JoinGameErrorCode responseCode)
	{
		if (responseCode != GameSessions.JoinGameErrorCode.Success)
		{
			isJoiningRoom = false;
			if (responseCode == GameSessions.JoinGameErrorCode.InsufficientSpace)
			{
				roomServerDataList[joinRequestRoomIdx].isFull = true;
			}
			else
			{
				roomServerDataList[joinRequestRoomIdx].hasOtherError = true;
			}
			RefreshDisplay();
		}
	}

	public void Button_GoToCurrentRoom()
	{
		if (Player.LocalPlayerExists && !isJoiningRoom && !roomServerDataList[currentRoomIdx].hasOtherError && !roomServerDataList[currentRoomIdx].isFull)
		{
			GoToRoom(currentRoomIdx);
		}
	}

	public void Button_ShowNextRoom()
	{
		if (Player.LocalPlayerExists)
		{
			currentRoomIdx = (currentRoomIdx + 1) % roomList.Length;
			displayDuration = 0f;
			RefreshDisplay();
		}
	}

	public void Button_ShowPreviousRoom()
	{
		if (Player.LocalPlayerExists)
		{
			currentRoomIdx = (currentRoomIdx + roomList.Length - 1) % roomList.Length;
			displayDuration = 0f;
			RefreshDisplay();
		}
	}
}
