public class NUXCoCTableAutoHeight : UnityEngine.MonoBehaviour
{
	private const float heightAtScale0 = 0.031f;

	private const float heightAtScale1 = 0.916f;

	public Transform buttonTransform;

	public AnimationCurve curve;

	public float animationDuration = 1f;

	public float idealDistance = 0.6f;

	public float acceptableError = 0.1f;

	private bool isAnimating;

	private float targetY;

	private float animationStartTime;

	private float animationStartY;

	private void Awake()
	{
		targetY = buttonTransform.position.y;
	}

	private void Update()
	{
		float y = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position.y;
		float num = y - targetY;
		if (Mathf.Abs(num - idealDistance) > acceptableError)
		{
			SetTarget(y - idealDistance);
		}
		if (isAnimating)
		{
			float num2 = UnityEngine.Time.time - animationStartTime;
			if (num2 >= animationDuration)
			{
				UpdateScales(targetY);
				isAnimating = false;
			}
			else
			{
				float t = curve.Evaluate(num2 / animationDuration);
				float desiredY = Mathf.Lerp(animationStartY, targetY, t);
				UpdateScales(desiredY);
			}
		}
	}

	private void SetTarget(float newTargetY)
	{
		targetY = newTargetY;
		isAnimating = true;
		animationStartTime = UnityEngine.Time.time;
		animationStartY = buttonTransform.position.y;
	}

	private void UpdateScales(float desiredY)
	{
		float num = desiredY - 0.031f;
		float num2 = 0.885f;
		float num3 = num / num2;
		Vector3 localScale = base.transform.localScale;
		localScale.y = num3;
		base.transform.localScale = localScale;
		Vector3 localScale2 = buttonTransform.localScale;
		localScale2.y = 1f / num3;
		buttonTransform.localScale = localScale2;
	}
}
public class RewardBobAndRotate : UnityEngine.MonoBehaviour
{
	public float bobDistance_m = 0.03f;

	public float bobDuration_s = 3f;

	public bool bShouldSpin = true;

	public bool bClockwise = true;

	public float spinDuration_s = 5f;

	private float startTime;

	private Vector3 originalPosition;

	private Quaternion originalRotation;

	private void Start()
	{
		startTime = UnityEngine.Time.realtimeSinceStartup;
		originalPosition = base.gameObject.transform.position;
		originalRotation = base.gameObject.transform.rotation;
	}

	private void Update()
	{
		float num = UnityEngine.Time.realtimeSinceStartup - startTime;
		float y = Mathf.Sin((float)Math.PI * 2f * (num % bobDuration_s) / bobDuration_s) * bobDistance_m;
		base.gameObject.transform.position = originalPosition + new Vector3(0f, y, 0f);
		if (bShouldSpin)
		{
			float num2 = 360f * (num % spinDuration_s) / spinDuration_s;
			if (!bClockwise)
			{
				num2 *= -1f;
			}
			base.gameObject.transform.rotation = originalRotation * Quaternion.Euler(0f, num2, 0f);
		}
	}
}
public class WeeklyChallengeBulletinBoardUI : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private TextMeshProUGUI weeklyChallengeTimeRemaining;

	[SerializeField]
	private string weeklyChallengePrefix = "New Weekly Challenges in ";

	[SerializeField]
	private TextMeshProUGUI themeText;

	[SerializeField]
	private ObjectiveChecklist weeklyChecklist;

	[SerializeField]
	private Transform rewardOrientationTransform;

	[SerializeField]
	private GameObject displayTable;

	[SerializeField]
	private GameObject glassCase;

	[SerializeField]
	private Transform glassCaseCenter;

	[SerializeField]
	private float minScale = 0.5f;

	[SerializeField]
	private float displayMarginHorizontal = 0.05f;

	[SerializeField]
	private float displayMarginVertical = 0.1f;

	[SerializeField]
	private Transform displayLabelRoot;

	[SerializeField]
	private GameObject displayLabel;

	private TimeSpan nextChallengesTimeSpan;

	private int lastSeconds = -1;

	private IEnumerator Start()
	{
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.OnWeeklyChallengeUpdated += UpdateAllObjectives;
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap != null)
		{
			string themeString = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.ThemeString;
			if (!string.IsNullOrEmpty(themeString))
			{
				themeText.text = themeString;
			}
			ObjectiveChecklist objectiveChecklist = weeklyChecklist;
			objectiveChecklist.OnRewardObjectSpawned = (Action<GameObject>)Delegate.Combine(objectiveChecklist.OnRewardObjectSpawned, new Action<GameObject>(OnRewardSpawned));
			UpdateAllObjectives();
		}
		SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.UpdateLastSeenChallengeMapId();
	}

	private void OnDestroy()
	{
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance != null)
		{
			SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.OnWeeklyChallengeUpdated -= UpdateAllObjectives;
		}
		ObjectiveChecklist objectiveChecklist = weeklyChecklist;
		objectiveChecklist.OnRewardObjectSpawned = (Action<GameObject>)Delegate.Remove(objectiveChecklist.OnRewardObjectSpawned, new Action<GameObject>(OnRewardSpawned));
	}

	private void OnRewardSpawned(GameObject rewardObject)
	{
		Collider[] componentsInChildren = rewardObject.GetComponentsInChildren<Collider>();
		Bounds bounds = new Bounds(rewardObject.transform.position, Vector3.zero);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			bounds.Encapsulate(componentsInChildren[i].bounds);
		}
		float num = Mathf.Max(bounds.extents.x, bounds.extents.z);
		float num2 = num;
		float num3 = bounds.extents.y;
		Vector3 vector = bounds.center - rewardObject.transform.position;
		if (num > 2f * bounds.extents.y)
		{
			if (bounds.extents.x >= bounds.extents.z)
			{
				rewardOrientationTransform.rotation *= Quaternion.Euler(0f, 0f, -90f);
				num2 = Mathf.Max(bounds.extents.z, bounds.extents.y);
				num3 = bounds.extents.x;
			}
			else
			{
				rewardOrientationTransform.rotation *= Quaternion.Euler(-90f, 0f, 0f);
				num2 = Mathf.Max(bounds.extents.x, bounds.extents.y);
				num3 = bounds.extents.z;
			}
		}
		float num4 = Mathf.Max(minScale, (num2 + displayMarginHorizontal) * 2f);
		float y = Mathf.Max(minScale, (num3 + displayMarginVertical) * 2f);
		Vector3 localScale = displayTable.transform.localScale;
		localScale.x = num4;
		localScale.z = num4;
		displayTable.transform.localScale = localScale;
		Vector3 localScale2 = new Vector3(num4, y, num4);
		glassCase.transform.localScale = localScale2;
		displayLabel.transform.position = displayLabelRoot.position;
		rewardOrientationTransform.position = glassCaseCenter.position - rewardOrientationTransform.TransformVector(vector);
	}

	private void Update()
	{
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.HasValue)
		{
			nextChallengesTimeSpan = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.Value - (DateTime.UtcNow + SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.TimeDiff.Value);
			if (nextChallengesTimeSpan.Seconds != lastSeconds)
			{
				ShowWeeklyTimeRemaining();
				lastSeconds = nextChallengesTimeSpan.Seconds;
			}
		}
	}

	private void ShowWeeklyTimeRemaining()
	{
		string text = TimeSpanToString();
		UIHelper.SafeSetText(weeklyChallengeTimeRemaining, weeklyChallengePrefix + text);
	}

	private void UpdateAllObjectives()
	{
		weeklyChecklist.UpdateAllObjectives();
	}

	private string TimeSpanToString()
	{
		if (!SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.HasValue || !SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.TimeDiff.HasValue)
		{
			return string.Format("{0:D2}:{1:D2}:{2:D2}:{0:D2}", 0, 0, 0, 0);
		}
		if (nextChallengesTimeSpan.TotalSeconds < 0.0)
		{
			return string.Format("{0:D2}:{1:D2}:{2:D2}:{0:D2}", 0, 0, 0, 0);
		}
		int days = nextChallengesTimeSpan.Days;
		int hours = nextChallengesTimeSpan.Hours;
		int minutes = nextChallengesTimeSpan.Minutes;
		int seconds = nextChallengesTimeSpan.Seconds;
		return $"{days:D2}:{hours:D2}:{minutes:D2}:{seconds:D2}";
	}
}
public class YoutubeBulletinBoardUI : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Parent, false)]
	private BulletinBoardController bulletinBoardController;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private VideoPlayer videoPlayer;

	[SerializeField]
	private MeshRenderer largeVideoRenderer;

	[SerializeField]
	private GameObject loadingVisual;

	[SerializeField]
	private Transform contentRoot;

	[SerializeField]
	private YoutubeBulletinCard cardPrefab;

	private List<YoutubeBulletinCard> cards = new List<YoutubeBulletinCard>();

	private Coroutine playYoutubeCardCoroutine;

	private void Start()
	{
		Refresh();
		CommunityBoard.CurrentBoardUpdated += Refresh;
	}

	private void OnDestroy()
	{
		CommunityBoard.CurrentBoardUpdated -= Refresh;
	}

	private void Refresh()
	{
		Button_CloseVideoPlayer();
		YoutubeBulletinCard[] array = cards.ToArray();
		foreach (YoutubeBulletinCard youtubeBulletinCard in array)
		{
			if (youtubeBulletinCard != null)
			{
				UnityEngine.Object.Destroy(youtubeBulletinCard.gameObject);
			}
		}
		cards.Clear();
		int? num = CommunityBoard.Current?.Videos.Count;
		if (!num.HasValue || num.GetValueOrDefault() <= 0)
		{
			return;
		}
		foreach (CommunityBoard.CommunityBoardVideoData item in CommunityBoard.Current.Videos.SkipTake(0, 3))
		{
			YoutubeBulletinCard youtubeBulletinCard2 = UnityEngine.Object.Instantiate(cardPrefab, contentRoot, worldPositionStays: false);
			youtubeBulletinCard2.transform.localScale = Vector3.one;
			youtubeBulletinCard2.transform.localRotation = Quaternion.identity;
			youtubeBulletinCard2.Setup(item, this);
			cards.Add(youtubeBulletinCard2);
		}
	}

	public void PlayYoutubeCard(YoutubeBulletinCard youtubeBulletinCard)
	{
		if (playYoutubeCardCoroutine == null)
		{
			playYoutubeCardCoroutine = StartCoroutine(RunPlayYoutubeCard(youtubeBulletinCard));
		}
	}

	private IEnumerator RunPlayYoutubeCard(YoutubeBulletinCard youtubeBulletinCard)
	{
		bulletinBoardController.ShowVisualLayer(BulletinBoardVisualLayer.VisualLayer.LargeVideoPlayer);
		loadingVisual.SetActive(value: true);
		largeVideoRenderer.gameObject.SetActive(value: false);
		while (!youtubeBulletinCard.IsVideoURLReady)
		{
			yield return null;
		}
		if (videoPlayer.isPlaying)
		{
			videoPlayer.Stop();
		}
		videoPlayer.url = youtubeBulletinCard.VideoURL;
		videoPlayer.Prepare();
		while (!videoPlayer.isPrepared)
		{
			yield return null;
		}
		yield return null;
		videoPlayer.Play();
		loadingVisual.SetActive(value: false);
		largeVideoRenderer.gameObject.SetActive(value: true);
		videoPlayer.targetMaterialRenderer = largeVideoRenderer;
	}

	public void Button_CloseVideoPlayer()
	{
		if (videoPlayer.isPlaying)
		{
			videoPlayer.Stop();
		}
		bulletinBoardController.ShowVisualLayer(BulletinBoardVisualLayer.VisualLayer.Default);
		if (playYoutubeCardCoroutine != null)
		{
			StopCoroutine(playYoutubeCardCoroutine);
			playYoutubeCardCoroutine = null;
		}
	}
}
