public class Mic : UnityEngine.MonoBehaviour
{
	private class PlayerData
	{
		private List<Mic> micsInRange = new List<Mic>();

		public bool InRangeOfMic => micsInRange.Count > 0;

		public void EnterMicRange(Mic mic)
		{
			if (!micsInRange.Contains(mic))
			{
				micsInRange.Add(mic);
				return;
			}
			UnityEngine.Debug.LogWarningFormat("Already in range of {0}!", mic.gameObject.name);
		}

		public void ExitMicRange(Mic mic)
		{
			micsInRange.Remove(mic);
		}
	}

	private static List<Mic> AllMicrophones = new List<Mic>();

	[SerializeField]
	private MicrophoneManager microphoneManagerPrefab;

	[SerializeField]
	private float micVolumeAdjustment = 0.75f;

	[SerializeField]
	private bool applyAudioFX = true;

	[SerializeField]
	private RecRoomAudioClip[] micHeadHitAudio;

	[SerializeField]
	private float micHitSpeakerLinesDuration = 0.2f;

	[SerializeField]
	private MicrophoneManager.MicVolumeLevel micHitSpeakerLineLevel = MicrophoneManager.MicVolumeLevel.LEVEL_3;

	[SerializeField]
	private RecRoomAudioClip micFeedbackAudio;

	[SerializeField]
	private float micFeedbackSpeakerLinesDuration = 1.3f;

	[SerializeField]
	private MicrophoneManager.MicVolumeLevel micFeedbackSpeakerLineLevel = MicrophoneManager.MicVolumeLevel.LEVEL_4;

	private Tool tool;

	private float minTimeBetweenMicHits = 0.2f;

	private float timeOfLastMicHit;

	private float minCollisionSpeedForFeedback = 7f;

	private float chanceOfFeedback = 0.8f;

	private float minTimeBetweenFeedback = 2f;

	private float timeOfLastFeedback;

	private static Dictionary<long, PlayerData> playerData = new Dictionary<long, PlayerData>();

	private void Awake()
	{
		AllMicrophones.Add(this);
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PostPickupEvent += OverrideCollisionLayer;
		}
	}

	private void Start()
	{
		if (SingletonMonoBehaviour<MicrophoneManager>.Instance == null)
		{
			UnityEngine.Object.Instantiate(microphoneManagerPrefab);
		}
		else
		{
			SingletonMonoBehaviour<MicrophoneManager>.Instance.MicAdded();
		}
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.PostPickupEvent -= OverrideCollisionLayer;
		}
		AllMicrophones.Remove(this);
		if (AllMicrophones.Count == 0 && SingletonMonoBehaviour<MicrophoneManager>.Instance != null)
		{
			SingletonMonoBehaviour<MicrophoneManager>.Instance.ScheduleDestroy();
		}
		foreach (PlayerData value in playerData.Values)
		{
			value.ExitMicRange(this);
		}
	}

	public void OnHeadOverlapChanged(Player player, Player.BodyPart bodyPart, bool isIn)
	{
		if (player != null)
		{
			AudioSource voiceAudioSource = player.VoiceAudioSource;
			if (isIn)
			{
				GetPlayerData(player.PlayerId).EnterMicRange(this);
			}
			else
			{
				GetPlayerData(player.PlayerId).ExitMicRange(this);
			}
			if (!GetPlayerData(player.PlayerId).InRangeOfMic)
			{
				voiceAudioSource.spatialBlend = 1f;
				voiceAudioSource.volume = 1f;
				voiceAudioSource.GetComponent<AudioHighPassFilter>().enabled = false;
				voiceAudioSource.GetComponent<AudioReverbFilter>().enabled = false;
			}
			else if (voiceAudioSource.spatialBlend == 1f)
			{
				voiceAudioSource.spatialBlend = 0f;
				voiceAudioSource.volume = micVolumeAdjustment;
				voiceAudioSource.GetComponent<AudioHighPassFilter>().enabled = applyAudioFX;
				voiceAudioSource.GetComponent<AudioReverbFilter>().enabled = applyAudioFX;
			}
			if (SingletonMonoBehaviour<MicrophoneManager>.Instance != null)
			{
				SingletonMonoBehaviour<MicrophoneManager>.Instance.OnMicUseEvent(player, isIn);
			}
		}
	}

	private void OverrideCollisionLayer(Tool thisTool)
	{
		tool.SetCollisionLayer(tool.DefaultCollisionLayer);
	}

	public void OnMicHit(Collider collider)
	{
		PlayMicHitAudio(collider);
	}

	private void PlayMicHitAudio(Collider collider)
	{
		PlayerHand componentInParent = collider.GetComponentInParent<PlayerHand>();
		if (tool.IsHeld)
		{
			Player componentInParent2 = collider.GetComponentInParent<Player>();
			if ((bool)componentInParent2 && (componentInParent == null || componentInParent == tool.HolderHand || componentInParent.HeldTool != null))
			{
				return;
			}
		}
		if (UnityEngine.Time.time - timeOfLastMicHit > minTimeBetweenMicHits)
		{
			timeOfLastMicHit = UnityEngine.Time.time;
			AudioManager.Play2DSFX(micHeadHitAudio[UnityEngine.Random.Range(0, micHeadHitAudio.Length)]);
			if (SingletonMonoBehaviour<MicrophoneManager>.Instance != null)
			{
				SingletonMonoBehaviour<MicrophoneManager>.Instance.OnMicSpeakerLinesEvent(micHitSpeakerLinesDuration, micHitSpeakerLineLevel);
			}
			if (componentInParent != null)
			{
				componentInParent.Vibrate(30);
			}
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		PlayMicHitAudio(collision.collider);
		if (collision.relativeVelocity.magnitude > minCollisionSpeedForFeedback && UnityEngine.Random.value < chanceOfFeedback && UnityEngine.Time.time - timeOfLastFeedback > minTimeBetweenFeedback)
		{
			timeOfLastFeedback = UnityEngine.Time.time;
			AudioManager.Play2DSFX(micFeedbackAudio);
			if (SingletonMonoBehaviour<MicrophoneManager>.Instance != null)
			{
				SingletonMonoBehaviour<MicrophoneManager>.Instance.OnMicSpeakerLinesEvent(micFeedbackSpeakerLinesDuration, micFeedbackSpeakerLineLevel);
			}
		}
	}

	private PlayerData GetPlayerData(long playerId)
	{
		if (!playerData.TryGetValue(playerId, out var value))
		{
			value = new PlayerData();
			playerData[playerId] = value;
		}
		return value;
	}
}
