public class MicrophoneManager : SingletonMonoBehaviour<MicrophoneManager>
{
	public enum MicVolumeLevel
	{
		OFF,
		LEVEL_1,
		LEVEL_2,
		LEVEL_3,
		LEVEL_4
	}

	[Serializable]
	public struct SpeakerLineLevelThreshold
	{
		public MicVolumeLevel lineLevel;

		public float volumeThreshold;
	}

	private List<Player> players = new List<Player>();

	private MicVolumeLevel micAudioEffectSpeakerLineLevel;

	[SerializeField]
	private SpeakerLineLevelThreshold[] speakerLineLevelThresholds;

	private float scheduledDestroyWait;

	private Coroutine destroyRoutine;

	private Coroutine micSpeakerLinesRoutine;

	public MicVolumeLevel CurrentSpeakerLineLevel { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		int num = System.Enum.GetNames(typeof(MicVolumeLevel)).Length;
		if (num - 1 != speakerLineLevelThresholds.Length)
		{
			UnityEngine.Debug.LogError("Length of Speaker Line Level Thresholds array must be " + (num - 1));
		}
	}

	private void Update()
	{
		UpdateCurrentSpeakerLineLevel();
	}

	public void ScheduleDestroy()
	{
		if (!base.gameObject.activeInHierarchy)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else if (destroyRoutine == null)
		{
			destroyRoutine = StartCoroutine(WaitAndDestroy());
		}
	}

	private IEnumerator WaitAndDestroy()
	{
		yield return new WaitForSeconds(scheduledDestroyWait);
		UnityEngine.Object.Destroy(base.gameObject);
		destroyRoutine = null;
	}

	public void MicAdded()
	{
		if (destroyRoutine != null)
		{
			StopCoroutine(destroyRoutine);
		}
		destroyRoutine = null;
	}

	public void OnMicUseEvent(Player player, bool isUsing)
	{
		if (isUsing && !players.Contains(player))
		{
			players.Add(player);
		}
		else if (!isUsing && players.Contains(player))
		{
			players.Remove(player);
		}
	}

	public void OnMicSpeakerLinesEvent(float micAudioDuration, MicVolumeLevel lineLevel)
	{
		scheduledDestroyWait = Mathf.Max(micAudioDuration + 1f, scheduledDestroyWait);
		if (lineLevel >= micAudioEffectSpeakerLineLevel)
		{
			micAudioEffectSpeakerLineLevel = lineLevel;
			if (micSpeakerLinesRoutine != null)
			{
				StopCoroutine(micSpeakerLinesRoutine);
			}
			micSpeakerLinesRoutine = StartCoroutine(RunEndMicAudioEffect(micAudioDuration));
		}
	}

	private MicVolumeLevel VolumeToSpeakerLineLevel(float volume)
	{
		for (int num = speakerLineLevelThresholds.Length - 1; num >= 0; num--)
		{
			if (volume >= speakerLineLevelThresholds[num].volumeThreshold)
			{
				return speakerLineLevelThresholds[num].lineLevel;
			}
		}
		return MicVolumeLevel.OFF;
	}

	private void UpdateCurrentSpeakerLineLevel()
	{
		float num = 0f;
		if (micAudioEffectSpeakerLineLevel != MicVolumeLevel.OFF)
		{
			CurrentSpeakerLineLevel = micAudioEffectSpeakerLineLevel;
			return;
		}
		List<int> list = new List<int>();
		for (int i = 0; i < players.Count; i++)
		{
			if (players[i] == null)
			{
				list.Add(i);
			}
			else if (players[i].AudioMaxForFrame > PhotonVoiceSettings.Instance.VoiceDetectionThreshold)
			{
				num = Mathf.Max(num, Mathf.InverseLerp(PhotonVoiceSettings.Instance.VoiceDetectionThreshold, 1f, players[i].AudioMaxForFrame));
			}
		}
		foreach (int item in list)
		{
			players.RemoveAt(item);
		}
		CurrentSpeakerLineLevel = VolumeToSpeakerLineLevel(num);
	}

	private IEnumerator RunEndMicAudioEffect(float micHitAudioDuration)
	{
		yield return new WaitForSeconds(micHitAudioDuration);
		micAudioEffectSpeakerLineLevel = MicVolumeLevel.OFF;
	}
}
