public class PlayingCardDeck : Photon.MonoBehaviour
{
	private const int DECK_SIZE = 52;

	[SerializeField]
	private SimplePhysicalButton recallCardsButton;

	private PlayingCard[] cards;

	private List<PlayingCard> recalledCards = new List<PlayingCard>();

	private HashSet<ToolGroup> recalledGroups = new HashSet<ToolGroup>();

	private Vector3 initialPosition = Vector3.zero;

	private Quaternion initialRotation = Quaternion.identity;

	protected override void Awake()
	{
		initialPosition = base.transform.position;
		initialRotation = base.transform.rotation;
		cards = GetComponentsInChildren<PlayingCard>();
		if (cards.Length != 52)
		{
			UnityEngine.Debug.LogError("Deck does not have the correct number of cards.  Has " + cards.Length + " and requires " + 52 + " cards.");
		}
		if (recallCardsButton != null)
		{
			recallCardsButton.pressEvent.AddListener(OnRecallButtonPressed);
		}
	}

	private void Start()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		for (int i = 0; i < 4; i++)
		{
			for (int j = 0; j < 13; j++)
			{
				cards[i * 13 + j].Suit = (PlayingCard.PlayingCardSuit)i;
				cards[i * 13 + j].Value = (PlayingCard.PlayingCardValue)j;
			}
		}
		CreateGroup(cards);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (recallCardsButton != null)
		{
			recallCardsButton.pressEvent.RemoveListener(OnRecallButtonPressed);
		}
	}

	private void CreateGroup(PlayingCard[] cardsToAdd)
	{
		PlayingCardGroup playingCardGroup = cardsToAdd[0].CreateNewGroup() as PlayingCardGroup;
		playingCardGroup.IsDeck = true;
		playingCardGroup.AuthorityAddChildren(cardsToAdd);
		playingCardGroup.AuthorityShuffle();
		playingCardGroup.transform.position = initialPosition;
		playingCardGroup.transform.rotation = initialRotation;
	}

	private void OnRecallButtonPressed(PhysicalButtonBase thisButton, Player pushPlayer)
	{
		if (pushPlayer.isLocal)
		{
			RequestRecall();
		}
	}

	private void RequestRecall()
	{
		base.photonView.RpcMaster(RpcMasterRecall);
	}

	[PunRPC]
	private void RpcMasterRecall()
	{
		recalledCards.Clear();
		recalledGroups.Clear();
		for (int i = 0; i < cards.Length; i++)
		{
			if (cards[i].IsInGroup && !cards[i].Group.Tool.IsHeld && !recalledGroups.Contains(cards[i].Group))
			{
				recalledGroups.Add(cards[i].Group);
			}
		}
		foreach (ToolGroup recalledGroup in recalledGroups)
		{
			if (!recalledGroup.hasAuthority)
			{
				recalledGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			recalledGroup.AuthorityClearTools();
			recalledGroup.AuthorityDestroy();
		}
		for (int j = 0; j < cards.Length; j++)
		{
			if (!cards[j].IsInGroup && !cards[j].Tool.IsHeld)
			{
				recalledCards.Add(cards[j]);
			}
		}
		if (recalledCards.Count > 0)
		{
			CreateGroup(recalledCards.ToArray());
		}
	}
}
public class PlayingCardGroup : ToolGroup
{
	private struct LayoutTransform
	{
		public Vector3 Position;

		public Quaternion Rotation;

		public static LayoutTransform Default
		{
			get
			{
				LayoutTransform result = default(LayoutTransform);
				result.Position = Vector3.zero;
				result.Rotation = Quaternion.identity;
				return result;
			}
		}

		public void Clear()
		{
			Position = Vector3.zero;
			Rotation = Quaternion.identity;
		}

		public LayoutTransform Mirror(Vector3 surfaceNormal)
		{
			LayoutTransform result = default(LayoutTransform);
			result.Position = 2f * Vector3.Project(Position, surfaceNormal) - Position;
			result.Rotation = Quaternion.Inverse(Rotation);
			return result;
		}
	}

	[Header("Playing Card Group")]
	[SerializeField]
	private RecRoomAudioClip shuffleSound;

	[Header("Deck Select")]
	[SerializeField]
	private float deckDwellTime = 1.5f;

	[Header("Deck Offset Transforms")]
	[SerializeField]
	private Transform deckNeighborTransform;

	[SerializeField]
	private Transform deckHighlightTransform;

	[SerializeField]
	private Transform entireDeckHighlightTransform;

	[Header("Stack Offset Transforms")]
	[SerializeField]
	private Transform stackNeighborTransform;

	[SerializeField]
	private Transform stackHighlightTransform;

	[SerializeField]
	private Transform stackAfterHighlightTransform;

	[SerializeField]
	private Transform entireStackHighlightTransform;

	private bool wasSleeping;

	private ToolGroupElement hoveredCard;

	private bool hoverEntireGroup;

	private ToolGroupElement insertionPreviewCard;

	private SynchronizedField<bool> _isDeck;

	private bool dwellingOnDeck;

	private float deckDwellStartTime;

	private int hoveredCardIndex = -1;

	private LayoutTransform neighborTransform;

	private LayoutTransform defaultCardTransform;

	private LayoutTransform cardHighlightTransform;

	private LayoutTransform entireGroupHighlightTransform;

	private LayoutTransform cardBeforeHighlightTransform;

	private LayoutTransform cardAfterHighlightTransform;

	public bool IsDeck
	{
		get
		{
			return _isDeck.Get();
		}
		set
		{
			_isDeck.Set(value);
		}
	}

	private bool IsUpsideDown => Vector3.Dot(base.transform.up, Vector3.up) <= 0f;

	private ToolGroupElement TopCard
	{
		get
		{
			if (base.Size == 0)
			{
				return null;
			}
			if (IsUpsideDown)
			{
				return children[0];
			}
			return children[children.Count - 1];
		}
	}

	private bool DwellingLongEnoughToSelectDeck => dwellingOnDeck && UnityEngine.Time.time - deckDwellStartTime >= deckDwellTime;

	private Vector3 RandomCardPositionOffset
	{
		get
		{
			Vector3 result = Vector3.zero;
			if (IsDeck)
			{
				Vector2 insideUnitCircle = UnityEngine.Random.insideUnitCircle;
				result = new Vector3(insideUnitCircle.x, 0f, insideUnitCircle.y) * 0.001f;
			}
			return result;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (base.Tool != null)
		{
			base.Tool.InputDownEvent += OnInputDown;
			base.Tool.ShakeEvent += OnShake;
			base.Tool.CustomHandSpacePickupTransformModifier = HandSpacePickupTransformModifier;
		}
		_isDeck = new SynchronizedField<bool>(this, "IS_DECK", defaultValue: false, SetterPermissionMode.AUTHORITY, OnIsDeckChange);
	}

	private void Start()
	{
		base.Tool.ToolCleanup.PauseCleanup(this);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.InputDownEvent -= OnInputDown;
			base.Tool.ShakeEvent -= OnShake;
		}
	}

	public void AuthorityShuffle()
	{
		int[] array = children.Select((ToolGroupElement x) => x.photonView.viewID).ToArray();
		UnityExtensions.ShuffleArray(array);
		AuthorityReorderTools(array);
		base.photonView.RpcAll(RpcPlayShuffleSound);
	}

	[PunRPC]
	private void RpcPlayShuffleSound()
	{
		if (shuffleSound != null)
		{
			AudioManager.Play3DSFX(shuffleSound, base.transform.position);
		}
	}

	protected override void Update()
	{
		base.Update();
		if (insertionPreviewCard != null && (insertionPreviewCard.Tool.IsHeld || (insertionPreviewCard.IsInGroup && insertionPreviewCard.Group.Tool.IsHeld)))
		{
			int num = 0;
			bool flag = true;
			int desiredNewChildIndex = GetDesiredNewChildIndex(insertionPreviewCard, Vector3.zero, Quaternion.identity);
			if (desiredNewChildIndex > 0)
			{
				num = desiredNewChildIndex - 1;
				flag = false;
			}
			for (int i = 0; i < children.Count; i++)
			{
				if (i != num)
				{
					children[i].FrontAddHighlightEnabled = false;
					children[i].BackAddHighlightEnabled = false;
				}
				else
				{
					children[i].FrontAddHighlightEnabled = !flag;
					children[i].BackAddHighlightEnabled = flag;
				}
			}
		}
		bool flag2 = base.Tool.RigidbodyEx.IsSleeping();
		if (!base.Tool.IsHeld && flag2 && !wasSleeping && base.hoveredGroup != null && (base.hoveredGroup.Tool.IsHeld || (base.hoveredGroup is PlayingCardGroup && (base.hoveredGroup as PlayingCardGroup).IsDeck)))
		{
			TryAddToHoveredGroup();
		}
		wasSleeping = flag2;
	}

	private void OnInputDown(Tool thisTool)
	{
		if (base.hasAuthority)
		{
			IsDeck = !IsDeck;
		}
	}

	private void OnShake(Tool tool)
	{
		AuthorityShuffle();
		if (base.Tool.HolderHand != null)
		{
			base.Tool.HolderHand.Vibrate(200);
		}
	}

	public override void DisplayAddGroupHighlight(ToolGroup groupToAdd)
	{
		insertionPreviewCard = null;
		PlayingCardGroup playingCardGroup = ((!(groupToAdd != null)) ? null : groupToAdd.GetComponent<PlayingCardGroup>());
		if (playingCardGroup == null || playingCardGroup.Size == 0)
		{
			base.DisplayAddGroupHighlight(groupToAdd);
		}
		else
		{
			DisplayAddToolHighlight(playingCardGroup.children[0]);
		}
	}

	public override void DisplayAddToolHighlight(ToolGroupElement toolToAdd)
	{
		insertionPreviewCard = null;
		if (toolToAdd == null)
		{
			base.DisplayAddToolHighlight(toolToAdd);
		}
		else
		{
			insertionPreviewCard = toolToAdd;
		}
	}

	public override bool CanAddGroup(ToolGroup group)
	{
		return group != null && group.GetComponent<PlayingCardGroup>() != null;
	}

	public override bool CanAddChild(ToolGroupElement tool)
	{
		return tool != null && tool.GetComponent<PlayingCard>() != null;
	}

	protected override void OnCloned(ToolGroup oldGroup)
	{
		base.OnCloned(oldGroup);
		PlayingCardGroup component = oldGroup.GetComponent<PlayingCardGroup>();
		if (component != null)
		{
			IsDeck = component.IsDeck;
		}
	}

	public override ToolGroupElement GetHighlightedChildInGroup(ToolGroupElement tool, Player player, bool physicalPickup)
	{
		ToolGroupElement toolGroupElement = null;
		if (IsDeck)
		{
			return GetHighlightedToolInDeck(tool, player, physicalPickup);
		}
		return GetHighlightedToolInStack(tool, player, physicalPickup);
	}

	private ToolGroupElement GetHighlightedToolInDeck(ToolGroupElement tool, Player player, bool physicalPickup)
	{
		ToolGroupElement result = null;
		if (!base.Tool.IsHeld)
		{
			if (!dwellingOnDeck)
			{
				dwellingOnDeck = true;
				deckDwellStartTime = UnityEngine.Time.time;
			}
			if (!DwellingLongEnoughToSelectDeck)
			{
				result = TopCard;
			}
		}
		else if (base.Tool.IsHeld && base.Tool.Owner == player && tool == TopCard)
		{
			result = tool;
		}
		return result;
	}

	private ToolGroupElement GetHighlightedToolInStack(ToolGroupElement tool, Player player, bool physicalPickup)
	{
		ToolGroupElement result = null;
		if (physicalPickup && base.Tool.IsHeld && base.Tool.Owner == player)
		{
			result = tool;
		}
		return result;
	}

	private void HandSpacePickupTransformModifier(Transform handTransform, bool isLeftHand, ref Vector3 position, ref Quaternion rotation)
	{
		if (IsDeck)
		{
			rotation = handTransform.InverseTransformRotation(base.transform.rotation);
		}
	}

	protected override void OnHoverStart(Tool thisTool)
	{
		base.OnHoverStart(thisTool);
		hoverEntireGroup = true;
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
	}

	protected override void OnHoverEnd(Tool thisTool)
	{
		base.OnHoverEnd(thisTool);
		hoverEntireGroup = false;
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
		if (dwellingOnDeck)
		{
			dwellingOnDeck = false;
		}
	}

	public override void OnChildInGroupHoverStart(ToolGroupElement tool)
	{
		base.OnChildInGroupHoverStart(tool);
		hoveredCard = tool;
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
	}

	public override void OnChildInGroupHoverEnd(ToolGroupElement tool)
	{
		base.OnChildInGroupHoverEnd(tool);
		hoveredCard = null;
		if (dwellingOnDeck && !DwellingLongEnoughToSelectDeck)
		{
			dwellingOnDeck = false;
		}
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
	}

	protected override void OnRemoveChild(ToolGroupElement tool)
	{
		base.OnRemoveChild(tool);
		if (dwellingOnDeck)
		{
			dwellingOnDeck = false;
		}
	}

	private void OnIsDeckChange()
	{
		StopDelayedUpdateOnRemove();
		UpdateGroupLayout();
		UpdateGroupCollider();
	}

	protected override int GetDesiredNewChildIndex(ToolGroupElement newTool, Vector3 localPosition, Quaternion localRotation)
	{
		int num = -1;
		bool isUpsideDown = IsUpsideDown;
		Vector3 rhs = ((!isUpsideDown) ? base.transform.up : (-base.transform.up));
		bool flag = Vector3.Dot(newTool.transform.position - base.transform.position, rhs) >= 0f;
		if (isUpsideDown)
		{
			return (!flag) ? children.Count : 0;
		}
		return flag ? children.Count : 0;
	}

	protected override void UpdateGroupLayout()
	{
		if (children.Count <= 0)
		{
			return;
		}
		defaultCardTransform = LayoutTransform.Default;
		if (IsDeck)
		{
			neighborTransform = CreateLocalLayoutTransform(deckNeighborTransform);
			cardBeforeHighlightTransform = defaultCardTransform;
			cardAfterHighlightTransform = defaultCardTransform;
			cardHighlightTransform = CreateLocalLayoutTransform(deckHighlightTransform);
			entireGroupHighlightTransform = CreateLocalLayoutTransform(entireDeckHighlightTransform);
			if (IsUpsideDown)
			{
				cardHighlightTransform = cardHighlightTransform.Mirror(Vector3.forward);
				entireGroupHighlightTransform = entireGroupHighlightTransform.Mirror(Vector3.forward);
			}
		}
		else
		{
			neighborTransform = CreateLocalLayoutTransform(stackNeighborTransform);
			cardHighlightTransform = CreateLocalLayoutTransform(stackHighlightTransform);
			cardAfterHighlightTransform = CreateLocalLayoutTransform(stackAfterHighlightTransform);
			cardBeforeHighlightTransform = cardAfterHighlightTransform.Mirror(Vector3.forward);
			entireGroupHighlightTransform = CreateLocalLayoutTransform(entireStackHighlightTransform);
			if (IsUpsideDown)
			{
				entireGroupHighlightTransform = entireGroupHighlightTransform.Mirror(Vector3.forward);
			}
		}
		LayoutTransform groupLocalLayout = new LayoutTransform
		{
			Position = Vector3.zero,
			Rotation = Quaternion.identity
		};
		hoveredCardIndex = ((!(hoveredCard != null)) ? (-1) : children.FindIndex((ToolGroupElement t) => t == hoveredCard));
		if (base.Tool.IsHeld)
		{
			int num = children.Count / 2;
			UpdateGroupLayoutForCard(num, defaultCardTransform, ref groupLocalLayout);
			for (int num2 = num + 1; num2 < children.Count; num2++)
			{
				UpdateGroupLayoutForCard(num2, neighborTransform, ref groupLocalLayout);
			}
			neighborTransform = neighborTransform.Mirror(Vector3.forward);
			groupLocalLayout.Clear();
			for (int num3 = num - 1; num3 >= 0; num3--)
			{
				UpdateGroupLayoutForCard(num3, neighborTransform, ref groupLocalLayout);
			}
		}
		else if (IsUpsideDown)
		{
			neighborTransform = neighborTransform.Mirror(Vector3.forward);
			UpdateGroupLayoutForCard(children.Count - 1, defaultCardTransform, ref groupLocalLayout);
			for (int num4 = children.Count - 2; num4 >= 0; num4--)
			{
				UpdateGroupLayoutForCard(num4, neighborTransform, ref groupLocalLayout);
			}
		}
		else
		{
			UpdateGroupLayoutForCard(0, defaultCardTransform, ref groupLocalLayout);
			for (int num5 = 1; num5 < children.Count; num5++)
			{
				UpdateGroupLayoutForCard(num5, neighborTransform, ref groupLocalLayout);
			}
		}
	}

	private void UpdateGroupLayoutForCard(int cardIndex, LayoutTransform neighborTransform, ref LayoutTransform groupLocalLayout)
	{
		LayoutTransform thisCardLayoutTransform = GetThisCardLayoutTransform(cardIndex);
		thisCardLayoutTransform = IntegrateLocalLayoutTransform(neighborTransform, thisCardLayoutTransform, ref groupLocalLayout);
		children[cardIndex].UpdateGroupLayout(thisCardLayoutTransform.Position + RandomCardPositionOffset, thisCardLayoutTransform.Rotation, groupLocalLayout.Position, groupLocalLayout.Rotation);
	}

	private LayoutTransform GetThisCardLayoutTransform(int thisCardIndex)
	{
		if (hoverEntireGroup)
		{
			return entireGroupHighlightTransform;
		}
		if (hoveredCardIndex < 0)
		{
			return defaultCardTransform;
		}
		if (thisCardIndex < hoveredCardIndex)
		{
			return cardBeforeHighlightTransform;
		}
		if (thisCardIndex > hoveredCardIndex)
		{
			return cardAfterHighlightTransform;
		}
		return cardHighlightTransform;
	}

	private LayoutTransform CreateLocalLayoutTransform(Transform worldTransform)
	{
		return new LayoutTransform
		{
			Position = base.transform.InverseTransformPoint(worldTransform.position),
			Rotation = base.transform.InverseTransformRotation(worldTransform.rotation)
		};
	}

	private LayoutTransform IntegrateLocalLayoutTransform(LayoutTransform neighborTransform, LayoutTransform thisCardTransform, ref LayoutTransform integratedLayoutTransform)
	{
		integratedLayoutTransform.Position = neighborTransform.Position.TransformCoordinateSpace(integratedLayoutTransform.Position, integratedLayoutTransform.Rotation);
		integratedLayoutTransform.Rotation = integratedLayoutTransform.Rotation.TransformRotation(neighborTransform.Rotation);
		thisCardTransform.Position = thisCardTransform.Position.TransformCoordinateSpace(integratedLayoutTransform.Position, integratedLayoutTransform.Rotation);
		thisCardTransform.Rotation = integratedLayoutTransform.Rotation.TransformRotation(thisCardTransform.Rotation);
		return thisCardTransform;
	}
}
