public class PokerChipGroup : ToolGroup
{
	[SerializeField]
	private Transform stackOffsetTransform;

	private bool tryToDropChip;

	private bool wasSleeping;

	private ToolGroupElement insertionPreviewChip;

	private bool IsUpsideDown => Vector3.Dot(base.transform.up, Vector3.up) <= 0f;

	private ToolGroupElement TopChip
	{
		get
		{
			if (base.Size == 0)
			{
				return null;
			}
			if (IsUpsideDown)
			{
				return children[0];
			}
			return children[children.Count - 1];
		}
	}

	private ToolGroupElement BottomChip
	{
		get
		{
			if (base.Size == 0)
			{
				return null;
			}
			if (IsUpsideDown)
			{
				return children[children.Count - 1];
			}
			return children[0];
		}
	}

	private Vector3 RandomCardPositionOffset
	{
		get
		{
			Vector2 insideUnitCircle = UnityEngine.Random.insideUnitCircle;
			return new Vector3(insideUnitCircle.x, 0f, insideUnitCircle.y) * 0.001f;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (base.Tool != null)
		{
			base.Tool.InputDownEvent += OnInputDown;
		}
	}

	private void Start()
	{
		base.Tool.ToolCleanup.PauseCleanup(this);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.InputDownEvent -= OnInputDown;
		}
	}

	protected override void Update()
	{
		base.Update();
		if (insertionPreviewChip != null && (insertionPreviewChip.Tool.IsHeld || (insertionPreviewChip.IsInGroup && insertionPreviewChip.Group.Tool.IsHeld)))
		{
			int num = 0;
			bool flag = true;
			int desiredNewChildIndex = GetDesiredNewChildIndex(insertionPreviewChip, Vector3.zero, Quaternion.identity);
			if (desiredNewChildIndex > 0)
			{
				num = desiredNewChildIndex - 1;
				flag = false;
			}
			for (int i = 0; i < children.Count; i++)
			{
				if (i != num)
				{
					children[i].FrontAddHighlightEnabled = false;
					children[i].BackAddHighlightEnabled = false;
				}
				else
				{
					children[i].FrontAddHighlightEnabled = !flag;
					children[i].BackAddHighlightEnabled = flag;
				}
			}
		}
		bool flag2 = base.Tool.RigidbodyEx.IsSleeping();
		if (!base.Tool.IsHeld && flag2 && !wasSleeping)
		{
			TryAddToHoveredGroup();
		}
		wasSleeping = flag2;
		if (tryToDropChip)
		{
			ToolGroupElement bottomChip = BottomChip;
			if (bottomChip != null)
			{
				AuthorityRemoveChild(bottomChip);
			}
			tryToDropChip = false;
		}
	}

	private void OnInputDown(Tool thisTool)
	{
		if (base.hasAuthority)
		{
			tryToDropChip = true;
		}
	}

	public override bool CanAddGroup(ToolGroup group)
	{
		return group != null && group.GetComponent<PokerChipGroup>() != null;
	}

	public override bool CanAddChild(ToolGroupElement tool)
	{
		return tool != null && tool.GetComponent<PokerChip>() != null;
	}

	public override ToolGroupElement GetHighlightedChildInGroup(ToolGroupElement tool, Player player, bool physicalPickup)
	{
		ToolGroupElement result = null;
		if (!base.Tool.IsHeld && !physicalPickup)
		{
			result = TopChip;
		}
		else if (base.Tool.IsHeld && base.Tool.Owner == player && tool == TopChip)
		{
			result = tool;
		}
		return result;
	}

	protected override int GetDesiredNewChildIndex(ToolGroupElement newTool, Vector3 localPosition, Quaternion localRotation)
	{
		int num = -1;
		bool isUpsideDown = IsUpsideDown;
		Vector3 rhs = ((!isUpsideDown) ? base.transform.up : (-base.transform.up));
		bool flag = Vector3.Dot(newTool.transform.position - base.transform.position, rhs) >= 0f;
		if (isUpsideDown)
		{
			return (!flag) ? children.Count : 0;
		}
		return flag ? children.Count : 0;
	}

	protected override void UpdateGroupLayout()
	{
		if (children.Count > 0)
		{
			Vector3 vector = base.transform.InverseTransformPoint(stackOffsetTransform.position);
			Quaternion rotation = base.transform.InverseTransformRotation(stackOffsetTransform.rotation);
			Vector3 vector2 = Vector3.zero;
			Quaternion quaternion = Quaternion.identity;
			int num = children.Count / 2;
			for (int i = num; i < children.Count; i++)
			{
				children[i].UpdateGroupLayout(vector2 + RandomCardPositionOffset, quaternion, vector2, quaternion);
				vector2 = vector.TransformCoordinateSpace(vector2, quaternion);
				quaternion = quaternion.TransformRotation(rotation);
			}
			vector = -1f * vector;
			rotation = Quaternion.Inverse(rotation);
			vector2 = Vector3.zero;
			quaternion = Quaternion.identity;
			for (int num2 = num - 1; num2 >= 0; num2--)
			{
				vector2 = vector.TransformCoordinateSpace(vector2, quaternion);
				quaternion = quaternion.TransformRotation(rotation);
				children[num2].UpdateGroupLayout(vector2 + RandomCardPositionOffset, quaternion, vector2, quaternion);
			}
		}
	}

	public override void OnChildInGroupHoverStart(ToolGroupElement tool)
	{
		base.OnChildInGroupHoverStart(tool);
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
	}

	public override void OnChildInGroupHoverEnd(ToolGroupElement tool)
	{
		base.OnChildInGroupHoverEnd(tool);
		if (!base.DelayedUpdateCoroutineIsRunning)
		{
			UpdateGroupLayout();
		}
	}
}
