public class SpeakerLinesController2D : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct SpeakerLineConfig
	{
		public VoiceLineControl lineControl;

		public MicrophoneManager.MicVolumeLevel speakerLineType;
	}

	[SerializeField]
	private SpeakerLineConfig[] speakerLines;

	[SerializeField]
	private SpeakerLineConfig shoutLines;

	[SerializeField]
	private VoiceLineControl.VoiceLineControlConfig speakerLineConfig;

	[SerializeField]
	[Range(0f, 180f)]
	private float maxAngleDiff = 45f;

	[SerializeField]
	[Range(0f, 180f)]
	private float offsetAngle = 45f;

	private void Awake()
	{
		SpeakerLineConfig[] array = speakerLines;
		for (int i = 0; i < array.Length; i++)
		{
			SpeakerLineConfig speakerLineConfig = array[i];
			speakerLineConfig.lineControl.gameObject.SetActive(value: false);
		}
	}

	private void Update()
	{
		UpdateSpeakerLines();
	}

	private void UpdateSpeakerLines()
	{
		if (!Player.LocalPlayerExists || !(SingletonMonoBehaviour<MicrophoneManager>.Instance != null))
		{
			return;
		}
		MicrophoneManager.MicVolumeLevel currentSpeakerLineLevel = SingletonMonoBehaviour<MicrophoneManager>.Instance.CurrentSpeakerLineLevel;
		if (currentSpeakerLineLevel >= shoutLines.speakerLineType)
		{
			shoutLines.lineControl.gameObject.SetActive(value: true);
			shoutLines.lineControl.Config = speakerLineConfig;
			shoutLines.lineControl.SetLifespan(UnityEngine.Time.time + speakerLineConfig.TTL);
		}
		for (int num = speakerLines.Length - 1; num >= 0; num--)
		{
			VoiceLineControl lineControl = speakerLines[num].lineControl;
			if (shoutLines.lineControl.gameObject.activeSelf)
			{
				lineControl.SetLifespan(0f);
			}
			else
			{
				bool flag = currentSpeakerLineLevel >= speakerLines[num].speakerLineType;
				if (flag)
				{
					lineControl.gameObject.SetActive(flag);
					lineControl.Config = speakerLineConfig;
					lineControl.SetLifespan(UnityEngine.Time.time + speakerLineConfig.TTL);
				}
			}
		}
		Transform transform = Player.LocalPlayer.Head.transform;
		Player localPlayer = Player.LocalPlayer;
		Vector3 vector = localPlayer.Head.transform.position - transform.position;
		float num2 = Vector3.Angle(localPlayer.Head.transform.right, vector.normalized);
		float num3 = Mathf.Abs(num2 - 90f);
		if (num3 < maxAngleDiff)
		{
			float y = ((!(num2 < 90f)) ? (0f - offsetAngle) : offsetAngle);
			base.transform.localRotation = Quaternion.Euler(0f, y, 0f);
		}
		else
		{
			base.transform.localRotation = Quaternion.identity;
		}
	}
}
public class ToolHolder : Photon.MonoBehaviour, IPersistable, IPostDeserializationPersistable
{
	[SerializeField]
	private Transform toolCouplingTransform;

	[SerializeField]
	private float couplingRadius = 0.2f;

	[SerializeField]
	private Tool initiallyCoupledTool;

	private Tool thisTool;

	private SynchronizedField<int> _heldToolPhotonId;

	private readonly HashSet<Tool> subscribedTools = new HashSet<Tool>();

	private PersistenceViewData lastDeserializedData;

	public Tool HeldTool
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_heldToolPhotonId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<Tool>();
		}
		set
		{
			_heldToolPhotonId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
		}
	}

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		_heldToolPhotonId = new SynchronizedField<int>(this, "HELD_TOOL_ID", -1, SetterPermissionMode.ANYONE, OnHeldToolChanged);
		thisTool = GetComponent<Tool>();
		if (thisTool != null)
		{
			thisTool.PostPickupEvent += OnHolderPickedUp;
		}
		if (toolCouplingTransform == null)
		{
			toolCouplingTransform = base.transform;
		}
		Tool.StaticToolInstantiatedEvent += SubscribeToToolEvents;
	}

	private void Start()
	{
		Tool[] array = UnityEngine.Object.FindObjectsOfType<Tool>();
		foreach (Tool tool in array)
		{
			SubscribeToToolEvents(tool);
		}
		if (!(initiallyCoupledTool != null))
		{
			return;
		}
		initiallyCoupledTool.PostResetEvent += OnInitiallyHeldToolReset;
		if (CanAttachTool(initiallyCoupledTool, initiallyCoupledTool.IsHeld))
		{
			if (initiallyCoupledTool.hasAuthority)
			{
				HeldTool = initiallyCoupledTool;
			}
			else
			{
				OnHeldToolChanged();
			}
		}
	}

	protected override void OnDestroy()
	{
		if (thisTool != null)
		{
			thisTool.PostPickupEvent -= OnHolderPickedUp;
		}
		if (initiallyCoupledTool != null)
		{
			initiallyCoupledTool.PostResetEvent -= OnInitiallyHeldToolReset;
		}
		foreach (Tool item in new List<Tool>(subscribedTools))
		{
			UnsubscribeFromToolEvents(item);
		}
		Tool.StaticToolInstantiatedEvent -= SubscribeToToolEvents;
		base.OnDestroy();
	}

	private void SubscribeToToolEvents(Tool tool)
	{
		if (!subscribedTools.Contains(tool) && tool != thisTool)
		{
			tool.PostPickupEvent += OnToolPickedUp;
			tool.PostReleaseEvent += OnToolReleased;
			tool.DestroyEvent += UnsubscribeFromToolEvents;
			subscribedTools.Add(tool);
		}
	}

	private void UnsubscribeFromToolEvents(Tool tool)
	{
		if (subscribedTools.Contains(tool))
		{
			if (tool == initiallyCoupledTool)
			{
				initiallyCoupledTool = null;
			}
			tool.PostPickupEvent -= OnToolPickedUp;
			tool.PostReleaseEvent -= OnToolReleased;
			tool.DestroyEvent -= UnsubscribeFromToolEvents;
			subscribedTools.Remove(tool);
		}
	}

	private void OnHeldToolChanged()
	{
		Tool heldTool = HeldTool;
		if (heldTool != null)
		{
			CoupleTool(heldTool);
		}
	}

	private void CoupleTool(Tool tool)
	{
		if (!CanAttachTool(tool, toolIsHeld: false))
		{
			return;
		}
		if (tool.owner != base.owner && tool.hasAuthority)
		{
			if (thisTool.IsHeld)
			{
				tool.photonView.TransferOwnership(thisTool.HolderView.ownerId);
			}
			else
			{
				base.photonView.TransferOwnership(tool.owner.ID);
			}
		}
		tool.SetCollisionLayer(Layers.DynamicPhysicsIgnoreDynamicAndPlayerPhysics);
		tool.RigidbodyPickup.Pickup(thisTool.RigidbodyPickup, toolCouplingTransform.localPosition, toolCouplingTransform.localRotation);
	}

	private void OnToolReleased(Tool tool)
	{
		if (tool.hasAuthority)
		{
			float sqrMagnitude = (tool.transform.position - toolCouplingTransform.position).sqrMagnitude;
			if (sqrMagnitude < couplingRadius * couplingRadius && CanAttachTool(tool, toolIsHeld: false))
			{
				HeldTool = tool;
			}
		}
	}

	private void OnToolPickedUp(Tool tool)
	{
		if (tool.hasAuthority)
		{
			Tool heldTool = HeldTool;
			if (heldTool != null && tool == heldTool)
			{
				HeldTool = null;
			}
		}
	}

	private void OnHolderPickedUp(Tool tool)
	{
		Tool heldTool = HeldTool;
		if (heldTool != null && heldTool.owner != base.owner)
		{
			heldTool.photonView.TransferOwnership(base.owner.ID);
		}
	}

	private bool CanAttachTool(Tool tool, bool toolIsHeld)
	{
		Tool heldTool = HeldTool;
		return tool != null && tool != thisTool && !toolIsHeld && tool.PickupEnabled && (heldTool == null || heldTool == tool) && tool.PlayerSpawnedEquipment == null;
	}

	private void OnInitiallyHeldToolReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		if (tool.hasAuthority && CanAttachTool(tool, tool.IsHeld))
		{
			HeldTool = tool;
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		lastDeserializedData = deserializeParams.viewData;
	}

	public void PostDeserialize(Dictionary<Guid, Guid> persistenceViewIdMappings)
	{
		if (lastDeserializedData != null)
		{
			if (lastDeserializedData.ToolHolderData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing ToolHolder {0}: data empty.", base.gameObject);
				return;
			}
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(lastDeserializedData.ToolHolderData.HeldViewId);
			if (guid != Guid.Empty)
			{
				if (persistenceViewIdMappings != null && persistenceViewIdMappings.ContainsKey(guid))
				{
					guid = persistenceViewIdMappings[guid];
				}
				if (PersistenceView.AllViews.TryGetValue(guid, out var value))
				{
					if (value.hasAuthority)
					{
						Tool component = value.GetComponent<Tool>();
						if (component != null)
						{
							HeldTool = component;
						}
						else
						{
							UnityEngine.Debug.LogErrorFormat(this, "Could not attach object {0} with GUID {1} to attach to ToolHolder {2}, as it is not a tool.", component, guid, base.gameObject);
						}
					}
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat(this, "Could not find tool with GUID {0} to attach to ToolHolder {1}", guid, base.gameObject);
				}
			}
			lastDeserializedData = null;
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat(this, "No persistence data found with PostDeserializing ToolHolder {0}", base.gameObject);
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.ToolHolderData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing ToolHolder {0}: Data already specified.", base.gameObject);
			return;
		}
		viewData.ToolHolderData = new ToolHolderData();
		if (HeldTool != null)
		{
			PersistenceView component = HeldTool.GetComponent<PersistenceView>();
			if (component != null)
			{
				viewData.ToolHolderData.HeldViewId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(component.Id);
				return;
			}
			UnityEngine.Debug.LogFormat(this, "Serializing ToolHolder {0}: HeldTool {1} has no corresponding PersistenceView.", base.gameObject, HeldTool.gameObject);
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.cyan;
		Vector3 center = ((!(toolCouplingTransform != null)) ? base.transform.position : toolCouplingTransform.position);
		Gizmos.DrawWireSphere(center, couplingRadius);
	}
}
