public sealed class Dart : StickyBase
{
	[Header("Drag Configuration")]
	[SerializeField]
	private Transform centerOfMass;

	[SerializeField]
	private Transform tail;

	[SerializeField]
	private float tailDrag = 0.1f;

	[SerializeField]
	private AnimationCurve dragByAngle;

	[SerializeField]
	private float scaleVelocityAtRelease = 1.25f;

	[SerializeField]
	private float scaleAngularVelocityAtRelease;

	[Header("Sticking Requirements")]
	[SerializeField]
	private float minSpeedToStick = 1f;

	[SerializeField]
	private float maxAngleToVelocityToStick = 45f;

	[SerializeField]
	private float maxAngleToSurfaceToStick = 60f;

	protected override void Start()
	{
		base.Start();
		base.Tool.RigidbodyEx.localCenterOfMass = base.transform.InverseTransformPoint(centerOfMass.position);
		base.Tool.PostReleaseEvent += OnPostRelease;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.PostReleaseEvent -= OnPostRelease;
		}
	}

	private void FixedUpdate()
	{
		if (!base.Tool.RigidbodyEx.isKinematic && !base.Tool.RigidbodyEx.IsSleeping())
		{
			Vector3 vector = base.transform.InverseTransformDirection(base.Tool.RigidbodyEx.angularVelocity);
			Quaternion quaternion = UnityExtensions.QuaternionFromAngularVelocity(vector * UnityEngine.Time.fixedDeltaTime);
			Vector3 vector2 = base.transform.InverseTransformPoint(tail.position);
			Vector3 direction = (quaternion * vector2 - vector2) / UnityEngine.Time.fixedDeltaTime;
			Vector3 toDirection = base.Tool.RigidbodyEx.velocity + base.transform.TransformDirection(direction);
			Quaternion.FromToRotation(base.Tool.RigidbodyEx.physicsRotation * Vector3.forward, toDirection).ToAngleAxis(out var angle, out var axis);
			float num = toDirection.sqrMagnitude * tailDrag * dragByAngle.Evaluate(angle);
			base.Tool.RigidbodyEx.AddTorque(axis * num);
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (base.hasAuthority && !base.IsAttached && !base.Tool.IsHeld && collision.relativeVelocity.magnitude > minSpeedToStick && Vector3.Angle(collision.relativeVelocity, -base.transform.forward) < maxAngleToVelocityToStick && Vector3.Angle(collision.contacts[0].normal, -base.transform.forward) < maxAngleToSurfaceToStick)
		{
			PhotonView componentInParent = collision.gameObject.GetComponentInParent<PhotonView>();
			AuthorityTryAttach(componentInParent);
		}
	}

	private void OnPostRelease(Tool tool)
	{
		tool.RigidbodyEx.velocity *= scaleVelocityAtRelease;
		tool.RigidbodyEx.angularVelocity *= scaleAngularVelocityAtRelease;
	}

	protected override void AuthorityProcessStickyToolReleased()
	{
	}
}
public class LaundryBinPickup : RigidbodyPickup
{
	private const float LINEAR_LIMIT = 0.001f;

	[Header("Joint Parameters")]
	[SerializeField]
	private float spring = 1000f;

	[SerializeField]
	private float damper = 200f;

	private Joint attachJoint;

	public override bool IsPickedUp => attachJoint != null;

	protected override void Awake()
	{
		base.Awake();
		tool.CustomSnapToHandBehavior = SnapToHandBehavior;
		tool.HeldCollisionLayer = Tool.DEFAULT_LAYER;
		tool.PreReleaseEvent += OnToolPreRelease;
		tool.PostReleaseEvent += OnToolPostRelease;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		tool.PreReleaseEvent -= OnToolPreRelease;
		tool.PostReleaseEvent -= OnToolPostRelease;
	}

	private void OnToolPreRelease(Tool thisTool)
	{
		rigidbodyEx.constraints |= RigidbodyConstraints.FreezePositionY;
	}

	private void OnToolPostRelease(Tool thisTool)
	{
		rigidbodyEx.constraints &= (RigidbodyConstraints)(-5);
	}

	public override void Pickup(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		Release();
		attachJoint = CreateJoint(target, targetSpacePickupPosition, targetSpacePickupRotation);
	}

	public override void Release()
	{
		if (attachJoint != null)
		{
			UnityEngine.Object.Destroy(attachJoint);
			attachJoint = null;
		}
		SingletonMonoBehaviour<Scheduler>.Instance.Run(this, ClampAngularVelocityWhileRotating());
	}

	private IEnumerator<ISchedule> ClampAngularVelocityWhileRotating()
	{
		while (!tool.IsHeld && rigidbodyEx.angularVelocity.sqrMagnitude > 0.0001f)
		{
			yield return Schedule.NextFixedUpdate;
			rigidbodyEx.angularVelocity = rigidbodyEx.GetConstrainedAngularVelocity(rigidbodyEx.angularVelocity);
		}
	}

	private void SnapToHandBehavior()
	{
	}

	private Joint CreateJoint(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		ConfigurableJoint configurableJoint = base.gameObject.AddComponent<ConfigurableJoint>();
		configurableJoint.autoConfigureConnectedAnchor = false;
		configurableJoint.anchor = base.transform.InverseTransformPoint(target.physicsPosition);
		configurableJoint.connectedBody = target.UnityRigidbody;
		configurableJoint.connectedAnchor = Vector3.zero;
		configurableJoint.configuredInWorldSpace = true;
		configurableJoint.xMotion = ConfigurableJointMotion.Limited;
		configurableJoint.yMotion = ConfigurableJointMotion.Free;
		configurableJoint.zMotion = ConfigurableJointMotion.Limited;
		configurableJoint.angularXMotion = ConfigurableJointMotion.Free;
		configurableJoint.angularYMotion = ConfigurableJointMotion.Free;
		configurableJoint.angularZMotion = ConfigurableJointMotion.Free;
		SoftJointLimit linearLimit = configurableJoint.linearLimit;
		linearLimit.limit = 0.001f;
		configurableJoint.linearLimit = linearLimit;
		SoftJointLimitSpring linearLimitSpring = configurableJoint.linearLimitSpring;
		linearLimitSpring.spring = spring;
		linearLimitSpring.damper = damper;
		configurableJoint.linearLimitSpring = linearLimitSpring;
		configurableJoint.breakForce = float.PositiveInfinity;
		return configurableJoint;
	}
}
public class HingeDoorPickup : RigidbodyPickup
{
	[Header("Hold Configuration Parameters")]
	[SerializeField]
	private float springForce = 100f;

	[SerializeField]
	private float linearDrag = 20f;

	[SerializeField]
	private float angularDrag = 5f;

	[SerializeField]
	private float breakForce = 50f;

	private float previousDrag;

	private float previousAngularDrag;

	private Joint attachJoint;

	public override bool IsPickedUp => attachJoint != null;

	public override void Pickup(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		Release();
		attachJoint = CreateJoint(target, targetSpacePickupPosition, targetSpacePickupRotation);
		previousDrag = rigidbodyEx.drag;
		previousAngularDrag = rigidbodyEx.angularDrag;
		rigidbodyEx.drag = linearDrag;
		rigidbodyEx.angularDrag = angularDrag;
	}

	public override void Release()
	{
		rigidbodyEx.drag = previousDrag;
		rigidbodyEx.angularDrag = previousAngularDrag;
		if (attachJoint != null)
		{
			UnityEngine.Object.Destroy(attachJoint);
			attachJoint = null;
		}
	}

	private Joint CreateJoint(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		SpringJoint springJoint = base.gameObject.AddComponent<SpringJoint>();
		springJoint.autoConfigureConnectedAnchor = false;
		springJoint.anchor = -targetSpacePickupPosition;
		springJoint.connectedBody = target.UnityRigidbody;
		springJoint.connectedAnchor = Vector3.zero;
		springJoint.spring = springForce;
		springJoint.breakForce = breakForce;
		return springJoint;
	}
}
