[ExecuteInEditMode]
public class Mirror : UnityEngine.MonoBehaviour
{
	internal class ReflectionData
	{
		public RenderTexture leftTexture;

		public RenderTexture rightTexture;

		public MaterialPropertyBlock propertyBlock;
	}

	[SerializeField]
	private Transform quad;

	[SerializeField]
	private bool disablePixelLights = true;

	[SerializeField]
	[Tooltip("Mirror will use up to the anti-aliasing level specified in QualitySettings, without exceeding this value (1, 2, 4, or 8)")]
	private int maxAntiAliasing = 1;

	private static readonly Vector4[] quadCorners = new Vector4[4]
	{
		new Vector4(-0.5f, -0.5f, 0f, 1f),
		new Vector4(-0.5f, 0.5f, 0f, 1f),
		new Vector4(0.5f, 0.5f, 0f, 1f),
		new Vector4(0.5f, -0.5f, 0f, 1f)
	};

	private static float StereoscopicOptimizationDistance = 5f;

	private static float NoRenderOptimizationDistance = 30f;

	internal Dictionary<Camera, ReflectionData> m_Reflections = new Dictionary<Camera, ReflectionData>();

	private Camera mirrorCamera;

	private Skybox mirrorSkybox;

	private RenderTexture dummy;

	private Renderer renderer;

	private static bool s_InsideRendering = false;

	private static int LeftTexturePropertyID;

	private static int RightTexturePropertyID;

	private static int LeftMirrorCameraViewProjPropertyID;

	private static int RightMirrorCameraViewProjPropertyID;

	private static readonly Rect DefaultRect = new Rect(0f, 0f, 1f, 1f);

	private Vector3 mirrorNormal;

	private void OnValidate()
	{
		if (maxAntiAliasing != 1 && maxAntiAliasing != 2 && maxAntiAliasing != 4 && maxAntiAliasing != 8)
		{
			maxAntiAliasing = 1;
		}
	}

	private void Awake()
	{
		if (quad == null)
		{
			UnityEngine.Debug.LogWarning("Mirror does not have an assigned quad. Disabling this Mirror component.");
			base.enabled = false;
			return;
		}
		renderer = GetComponent<Renderer>();
		mirrorNormal = -quad.transform.forward;
		LeftTexturePropertyID = Shader.PropertyToID("_LeftReflectionTex");
		RightTexturePropertyID = Shader.PropertyToID("_RightReflectionTex");
		LeftMirrorCameraViewProjPropertyID = Shader.PropertyToID("_LeftMirrorCameraViewProj");
		RightMirrorCameraViewProjPropertyID = Shader.PropertyToID("_RightMirrorCameraViewProj");
	}

	public void OnWillRenderObject()
	{
		if (!base.enabled || !renderer || !renderer.enabled)
		{
			return;
		}
		Camera current = Camera.current;
		if (!current || current == mirrorCamera || Vector3.Dot(mirrorNormal, current.transform.position - quad.transform.position) <= 0f || s_InsideRendering)
		{
			return;
		}
		s_InsideRendering = true;
		ReflectionData reflectionData = GetReflectionData(current);
		int pixelLightCount = QualitySettings.pixelLightCount;
		if (disablePixelLights)
		{
			QualitySettings.pixelLightCount = 0;
		}
		UpdateCameraModes(current);
		Vector3 vector = renderer.bounds.ClosestPoint(Camera.current.transform.position);
		float magnitude = (Camera.current.transform.position - vector).magnitude;
		if (current.stereoEnabled)
		{
			if ((current.stereoTargetEye == StereoTargetEyeMask.Both || current.stereoTargetEye == StereoTargetEyeMask.Left) && ShouldRenderEye(magnitude, 0))
			{
				Matrix4x4 stereoProjectionMatrix = current.GetStereoProjectionMatrix(Camera.StereoscopicEye.Left);
				Matrix4x4 stereoViewMatrix = current.GetStereoViewMatrix(Camera.StereoscopicEye.Left);
				RenderMirror(reflectionData.leftTexture, stereoViewMatrix, stereoProjectionMatrix, DefaultRect, out var trimmedProjectionMatrix);
				Matrix4x4 value = trimmedProjectionMatrix * stereoViewMatrix;
				reflectionData.propertyBlock.SetMatrix(LeftMirrorCameraViewProjPropertyID, value);
			}
			if ((current.stereoTargetEye == StereoTargetEyeMask.Both || current.stereoTargetEye == StereoTargetEyeMask.Right) && ShouldRenderEye(magnitude, 1))
			{
				Matrix4x4 stereoViewMatrix2 = current.GetStereoViewMatrix(Camera.StereoscopicEye.Right);
				Matrix4x4 stereoProjectionMatrix2 = current.GetStereoProjectionMatrix(Camera.StereoscopicEye.Right);
				RenderMirror(reflectionData.rightTexture, stereoViewMatrix2, stereoProjectionMatrix2, DefaultRect, out var trimmedProjectionMatrix2);
				Matrix4x4 value2 = trimmedProjectionMatrix2 * stereoViewMatrix2;
				reflectionData.propertyBlock.SetMatrix(RightMirrorCameraViewProjPropertyID, value2);
			}
		}
		else if (ShouldRenderEye(magnitude, 0))
		{
			RenderMirror(reflectionData.leftTexture, current.worldToCameraMatrix, current.projectionMatrix, DefaultRect, out var trimmedProjectionMatrix3);
			Matrix4x4 value3 = trimmedProjectionMatrix3 * current.worldToCameraMatrix;
			reflectionData.propertyBlock.SetMatrix(LeftMirrorCameraViewProjPropertyID, value3);
		}
		renderer.SetPropertyBlock(reflectionData.propertyBlock);
		if (disablePixelLights)
		{
			QualitySettings.pixelLightCount = pixelLightCount;
		}
		s_InsideRendering = false;
	}

	private void RenderMirror(RenderTexture targetTexture, Matrix4x4 camViewMatrix, Matrix4x4 camProjectionMatrix, Rect camViewport, out Matrix4x4 trimmedProjectionMatrix)
	{
		mirrorCamera.worldToCameraMatrix = camViewMatrix;
		mirrorCamera.projectionMatrix = camProjectionMatrix;
		mirrorCamera.targetTexture = targetTexture;
		mirrorCamera.rect = camViewport;
		Vector4 plane = Plane(quad.transform.position, mirrorNormal);
		mirrorCamera.worldToCameraMatrix *= CalculateReflectionMatrix(plane);
		mirrorCamera.transform.position = mirrorCamera.cameraToWorldMatrix.GetPosition();
		mirrorCamera.transform.rotation = mirrorCamera.cameraToWorldMatrix.GetRotation();
		GetClipSpaceRenderBounds(out var min, out var max);
		Matrix4x4 inverse = mirrorCamera.projectionMatrix.inverse;
		Vector4 vector = inverse * new Vector4(min.x, min.y, -1f, 1f);
		vector /= vector.w;
		Vector4 vector2 = inverse * new Vector4(max.x, max.y, -1f, 1f);
		vector2 /= vector2.w;
		trimmedProjectionMatrix = CalculateOffCenterPerspectiveMatrix(vector.x, vector2.x, vector.y, vector2.y, mirrorCamera.nearClipPlane, mirrorCamera.farClipPlane);
		mirrorCamera.projectionMatrix = trimmedProjectionMatrix;
		Vector4 clipPlane = CameraSpacePlane(mirrorCamera, quad.transform.position, mirrorNormal);
		mirrorCamera.projectionMatrix = mirrorCamera.CalculateObliqueMatrix(clipPlane);
		bool invertCulling = GL.invertCulling;
		GL.invertCulling = !invertCulling;
		mirrorCamera.Render();
		GL.invertCulling = invertCulling;
	}

	private bool ShouldRenderEye(float distance, int eyeIndex)
	{
		if (distance > NoRenderOptimizationDistance)
		{
			return false;
		}
		if (distance > StereoscopicOptimizationDistance)
		{
			return UnityEngine.Time.frameCount % 2 == eyeIndex;
		}
		return true;
	}

	private void GetClipSpaceRenderBounds(out Vector2 min, out Vector2 max)
	{
		Matrix4x4 localToWorldMatrix = quad.transform.localToWorldMatrix;
		Matrix4x4 worldToCameraMatrix = mirrorCamera.worldToCameraMatrix;
		Matrix4x4 projectionMatrix = mirrorCamera.projectionMatrix;
		float num = float.MaxValue;
		float num2 = float.MaxValue;
		float num3 = float.MinValue;
		float num4 = float.MinValue;
		Vector4[] array = quadCorners;
		foreach (Vector4 vector in array)
		{
			Vector4 vector2 = projectionMatrix * worldToCameraMatrix * localToWorldMatrix * vector;
			if (vector2.z > 0f)
			{
				vector2 /= vector2.w;
				num = Mathf.Min(num, Mathf.Max(-1f, vector2.x));
				num2 = Mathf.Min(num2, Mathf.Max(-1f, vector2.y));
				num3 = Mathf.Max(num3, Mathf.Min(1f, vector2.x));
				num4 = Mathf.Max(num4, Mathf.Min(1f, vector2.y));
				continue;
			}
			num = -1f;
			num2 = -1f;
			num3 = 1f;
			num4 = 1f;
			break;
		}
		min = new Vector2(num, num2);
		max = new Vector2(num3, num4);
	}

	private void OnDisable()
	{
		if ((bool)mirrorCamera)
		{
			mirrorCamera.targetTexture = null;
			UnityEngine.Object.DestroyImmediate(mirrorCamera.gameObject);
			mirrorCamera = null;
		}
		foreach (ReflectionData value in m_Reflections.Values)
		{
			UnityEngine.Object.DestroyImmediate(value.leftTexture);
			UnityEngine.Object.DestroyImmediate(value.rightTexture);
		}
		m_Reflections.Clear();
		if (dummy != null)
		{
			UnityEngine.Object.DestroyImmediate(dummy);
			dummy = null;
		}
	}

	private void UpdateCameraModes(Camera src)
	{
		if (!mirrorCamera)
		{
			GameObject gameObject = new GameObject("MirrorCam" + base.gameObject.name, typeof(Camera), typeof(Skybox), typeof(FlushOnPostRender));
			gameObject.hideFlags = HideFlags.HideAndDontSave;
			mirrorSkybox = gameObject.GetComponent<Skybox>();
			mirrorCamera = gameObject.GetComponent<Camera>();
			mirrorCamera.enabled = false;
			mirrorCamera.cullingMask = 1606418399;
			mirrorCamera.gameObject.AddComponent<OutlineEffectRenderer>();
			mirrorCamera.gameObject.AddComponent<IgnoreEffectRenderer>();
		}
		mirrorCamera.useOcclusionCulling = false;
		mirrorCamera.clearFlags = src.clearFlags;
		mirrorCamera.backgroundColor = src.backgroundColor;
		if (src.clearFlags == CameraClearFlags.Skybox)
		{
			Skybox skybox = src.GetComponent(typeof(Skybox)) as Skybox;
			if (!skybox || !skybox.material)
			{
				mirrorSkybox.enabled = false;
			}
			else
			{
				mirrorSkybox.enabled = true;
				mirrorSkybox.material = skybox.material;
			}
		}
		if (dummy == null)
		{
			dummy = new RenderTexture(1, 1, 0);
		}
		mirrorCamera.targetTexture = dummy;
		mirrorCamera.allowHDR = src.allowHDR;
		mirrorCamera.allowMSAA = src.allowMSAA;
		mirrorCamera.farClipPlane = src.farClipPlane;
		mirrorCamera.nearClipPlane = src.nearClipPlane;
		mirrorCamera.orthographic = src.orthographic;
		mirrorCamera.fieldOfView = src.fieldOfView;
		mirrorCamera.aspect = src.aspect;
		mirrorCamera.orthographicSize = src.orthographicSize;
	}

	private ReflectionData GetReflectionData(Camera currentCamera)
	{
		ReflectionData value = null;
		if (!m_Reflections.TryGetValue(currentCamera, out value))
		{
			value = new ReflectionData();
			value.propertyBlock = new MaterialPropertyBlock();
			m_Reflections[currentCamera] = value;
		}
		int pixelWidth = currentCamera.pixelWidth;
		int pixelHeight = currentCamera.pixelHeight;
		int b = Mathf.Min(QualitySettings.antiAliasing, maxAntiAliasing);
		b = Mathf.Max(1, b);
		if (!value.leftTexture || value.leftTexture.width != pixelWidth || value.leftTexture.height != pixelHeight || value.leftTexture.antiAliasing != b)
		{
			if ((bool)value.leftTexture)
			{
				UnityEngine.Object.DestroyImmediate(value.leftTexture);
			}
			value.leftTexture = new RenderTexture(pixelWidth, pixelHeight, 24, RenderTextureFormat.DefaultHDR);
			value.leftTexture.antiAliasing = b;
			value.leftTexture.hideFlags = HideFlags.DontSave;
			value.propertyBlock.SetTexture(LeftTexturePropertyID, value.leftTexture);
		}
		if (currentCamera.stereoEnabled && (!value.rightTexture || value.rightTexture.width != pixelWidth || value.rightTexture.height != pixelHeight || value.rightTexture.antiAliasing != b))
		{
			if ((bool)value.rightTexture)
			{
				UnityEngine.Object.DestroyImmediate(value.rightTexture);
			}
			value.rightTexture = new RenderTexture(pixelWidth, pixelHeight, 24, RenderTextureFormat.DefaultHDR);
			value.rightTexture.antiAliasing = b;
			value.rightTexture.hideFlags = HideFlags.DontSave;
			value.propertyBlock.SetTexture(RightTexturePropertyID, value.rightTexture);
		}
		return value;
	}

	private Vector4 Plane(Vector3 pos, Vector3 normal)
	{
		return new Vector4(normal.x, normal.y, normal.z, 0f - Vector3.Dot(pos, normal));
	}

	private Vector4 CameraSpacePlane(Camera cam, Vector3 pos, Vector3 normal)
	{
		Matrix4x4 worldToCameraMatrix = cam.worldToCameraMatrix;
		Vector3 pos2 = worldToCameraMatrix.MultiplyPoint(pos);
		Vector3 normalized = worldToCameraMatrix.MultiplyVector(normal).normalized;
		return Plane(pos2, normalized);
	}

	private static Matrix4x4 CalculateReflectionMatrix(Vector4 plane)
	{
		Matrix4x4 identity = Matrix4x4.identity;
		identity.m00 = 1f - 2f * plane[0] * plane[0];
		identity.m01 = -2f * plane[0] * plane[1];
		identity.m02 = -2f * plane[0] * plane[2];
		identity.m03 = -2f * plane[3] * plane[0];
		identity.m10 = -2f * plane[1] * plane[0];
		identity.m11 = 1f - 2f * plane[1] * plane[1];
		identity.m12 = -2f * plane[1] * plane[2];
		identity.m13 = -2f * plane[3] * plane[1];
		identity.m20 = -2f * plane[2] * plane[0];
		identity.m21 = -2f * plane[2] * plane[1];
		identity.m22 = 1f - 2f * plane[2] * plane[2];
		identity.m23 = -2f * plane[3] * plane[2];
		identity.m30 = 0f;
		identity.m31 = 0f;
		identity.m32 = 0f;
		identity.m33 = 1f;
		return identity;
	}

	private static Matrix4x4 CalculateOffCenterPerspectiveMatrix(float left, float right, float bottom, float top, float near, float far)
	{
		float value = 2f * near / (right - left);
		float value2 = 2f * near / (top - bottom);
		float value3 = (right + left) / (right - left);
		float value4 = (top + bottom) / (top - bottom);
		float value5 = (0f - (far + near)) / (far - near);
		float value6 = (0f - 2f * far * near) / (far - near);
		float value7 = -1f;
		return new Matrix4x4
		{
			[0, 0] = value,
			[0, 1] = 0f,
			[0, 2] = value3,
			[0, 3] = 0f,
			[1, 0] = 0f,
			[1, 1] = value2,
			[1, 2] = value4,
			[1, 3] = 0f,
			[2, 0] = 0f,
			[2, 1] = 0f,
			[2, 2] = value5,
			[2, 3] = value6,
			[3, 0] = 0f,
			[3, 1] = 0f,
			[3, 2] = value7,
			[3, 3] = 0f
		};
	}
}
[RequireComponent(typeof(Rigidbody))]
[RequireComponent(typeof(Joint))]
public class JointMaxStretch : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Tooltip("Max distance this bone can stretch from it's parent before resetting to it's original offset")]
	private float maxStretch = 0.2f;

	private Rigidbody rigidbody;

	private Joint joint;

	private Vector3 defaultPosition;

	private Quaternion defaultRotation;

	private float maxDistanceFromConnectedBody;

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
		joint = GetComponent<Joint>();
		defaultPosition = joint.connectedBody.transform.InverseTransformPoint(base.transform.position);
		defaultRotation = joint.connectedBody.transform.InverseTransformRotation(base.transform.rotation);
	}

	private void Update()
	{
		if (Vector3.Distance(base.transform.position, joint.connectedBody.transform.position) > defaultPosition.magnitude + maxStretch)
		{
			base.transform.position = joint.connectedBody.transform.TransformPoint(defaultPosition);
			base.transform.rotation = joint.connectedBody.transform.TransformRotation(defaultRotation);
			rigidbody.velocity = Vector3.zero;
			rigidbody.angularVelocity = Vector3.zero;
		}
	}
}
namespace RecRoom
{
	public class Radio : Photon.MonoBehaviour, IPersistable
	{
		public ActionEvent OnCurrentTrackChanged = new ActionEvent();

		[Header("Audio")]
		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		private SFXTrack[] tracks;

		[SerializeField]
		private bool randomInitialTrack;

		[SerializeField]
		private bool defaultToTrackLoop;

		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private Tool _tool;

		private int currentTrackNumber = -1;

		private bool paused;

		public Tool Tool => _tool;

		private RadioScreen RadioScreen { get; set; }

		public bool Looping { get; set; }

		public bool Shuffle { get; set; }

		private string CurrentTrackName
		{
			get
			{
				if (currentTrackNumber >= 0 && currentTrackNumber < tracks.Length)
				{
					return tracks[currentTrackNumber].Clip.name;
				}
				return "Nothing playing";
			}
		}

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			if (Tool != null)
			{
				Tool.InputDownEvent += OnInputDown;
				RadioScreen = Tool.Menu.GetFlowByType<RadioScreen>();
				if (RadioScreen != null)
				{
					RadioScreen.Initialize(Tool.Menu);
				}
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (Tool != null)
			{
				Tool.InputDownEvent -= OnInputDown;
			}
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		}

		private void Start()
		{
			if (base.hasAuthority && currentTrackNumber < 0)
			{
				if (randomInitialTrack)
				{
					PlayRandomTrack(randomTrackPosition: true);
				}
				else
				{
					PlaySpecificTrack(0);
				}
				if (defaultToTrackLoop)
				{
					Looping = true;
				}
				else
				{
					Looping = false;
				}
			}
			SingletonMonoBehaviour<Scheduler>.Instance.Run(this, StaggeredUpdateRoutine());
		}

		private void OnInputDown(Tool thisTool)
		{
		}

		public void PlayNextTrack()
		{
			int num = currentTrackNumber;
			if (Shuffle)
			{
				PlayRandomTrack();
				return;
			}
			num = (num + 1) % tracks.Length;
			PlaySpecificTrack(num);
		}

		public void PlayPreviousTrack()
		{
			int num = currentTrackNumber;
			if (Shuffle)
			{
				PlayRandomTrack();
				return;
			}
			num--;
			if (num < 0)
			{
				num = tracks.Length - 1;
			}
			PlaySpecificTrack(num);
		}

		public string GetNowPlayingString()
		{
			return $"{currentTrackNumber + 1}/{tracks.Length}: {CurrentTrackName}";
		}

		public void OnCircuitInput()
		{
			if (PhotonNetwork.isMasterClient)
			{
				PlayPause();
			}
		}

		public void PlayPause()
		{
			paused = !paused;
			base.photonView.RpcAll(RpcRadioSyncState, currentTrackNumber, audioSource.time, Looping, Shuffle, paused);
		}

		private IEnumerator<ISchedule> StaggeredUpdateRoutine()
		{
			ScheduleRate schedule = new ScheduleRate(10f);
			while (this != null)
			{
				if (!audioSource.isPlaying && !paused && base.hasAuthority)
				{
					if (Looping)
					{
						PlaySpecificTrack(currentTrackNumber);
					}
					else
					{
						PlayNextTrack();
					}
				}
				yield return schedule;
			}
		}

		private void PlaySpecificTrack(int trackNumber)
		{
			base.photonView.RpcAll(RpcRadioSyncState, trackNumber, 0f, Looping, Shuffle, paused);
		}

		private void PlayRandomTrack(bool randomTrackPosition = false)
		{
			int num = UnityEngine.Random.Range(0, tracks.Length) % tracks.Length;
			float arg = 0f;
			if (randomTrackPosition)
			{
				arg = UnityEngine.Random.Range(0f, tracks[num].Clip.length * 0.9f);
			}
			base.photonView.RpcAll(RpcRadioSyncState, num, arg, Looping, Shuffle, paused);
		}

		private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcRadioSyncState, currentTrackNumber, audioSource.time, Looping, Shuffle, paused);
			}
		}

		[PunRPC]
		private void RpcRadioSyncState(int trackNumber, float time, bool doLooping, bool doShuffle, bool isPaused)
		{
			if (trackNumber < tracks.Length && tracks[trackNumber] != null)
			{
				audioSource.Stop();
				audioSource.clip = tracks[trackNumber].Clip;
				if (time < audioSource.clip.length)
				{
					audioSource.time = time;
				}
				else
				{
					audioSource.time = 0f;
					UnityEngine.Debug.LogWarning("tried to set audiosource time for clip of length " + audioSource.clip.length + " to " + time);
				}
				currentTrackNumber = trackNumber;
				Looping = doLooping;
				Shuffle = doShuffle;
				OnCurrentTrackChanged.Invoke();
				if (!isPaused)
				{
					audioSource.Play();
				}
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.version < RoomPersistenceVersion.RADIO_PERSISTENCE)
			{
				return;
			}
			if (deserializeParams.viewData.PersistedSfxData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing radio {0}: No data found!", base.gameObject);
				return;
			}
			PersistedSFXData persistedSfxData = deserializeParams.viewData.PersistedSfxData;
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistedSfxData.TrackId);
			int num = -1;
			for (int i = 0; i < tracks.Length; i++)
			{
				if (tracks[i].Guid == guid)
				{
					num = i;
					break;
				}
			}
			if (num > 0)
			{
				base.photonView.RpcAll(RpcRadioSyncState, num, 0f, persistedSfxData.Loop, persistedSfxData.Shuffle, persistedSfxData.Paused);
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.PersistedSfxData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Radio {0}: Data already specified.", base.gameObject);
				return;
			}
			SFXTrack sFXTrack = tracks[currentTrackNumber];
			viewData.PersistedSfxData = new PersistedSFXData
			{
				TrackId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(sFXTrack.Guid),
				Paused = paused,
				Loop = Looping,
				Shuffle = Shuffle
			};
		}
	}
