public class ReceptionBell : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private AudioSource audioSource;

	[SerializeField]
	private float minTimeBetweenRings = 0.25f;

	private float lastRingTime;

	private void OnCollisionEnter(Collision col)
	{
		if (col.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyAndAnyPlayerPhysics) && UnityEngine.Time.time - lastRingTime > minTimeBetweenRings)
		{
			audioSource.Play();
			lastRingTime = UnityEngine.Time.time;
		}
	}

	private void OnTriggerEnter(Collider col)
	{
		if (col.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
		{
			PlayerCollider component = col.gameObject.GetComponent<PlayerCollider>();
			if (component != null && component.BodyPart.IsHand() && UnityEngine.Time.time - lastRingTime > minTimeBetweenRings)
			{
				audioSource.Play();
				lastRingTime = UnityEngine.Time.time;
			}
		}
	}
}
public class SlidingDrawerPickup : RigidbodyPickup
{
	[Header("Hold Configuration Parameters")]
	[SerializeField]
	private float springForce = 100f;

	[SerializeField]
	private float linearDrag = 20f;

	[SerializeField]
	private float angularDrag = 5f;

	[SerializeField]
	private float breakForce = 50f;

	private float previousDrag;

	private float previousAngularDrag;

	private Joint attachJoint;

	public override bool IsPickedUp => attachJoint != null;

	public override void Pickup(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		Release();
		attachJoint = CreateJoint(target, targetSpacePickupPosition, targetSpacePickupRotation);
		previousDrag = rigidbodyEx.drag;
		previousAngularDrag = rigidbodyEx.angularDrag;
		rigidbodyEx.drag = linearDrag;
		rigidbodyEx.angularDrag = angularDrag;
	}

	public override void Release()
	{
		rigidbodyEx.drag = previousDrag;
		rigidbodyEx.angularDrag = previousAngularDrag;
		if (attachJoint != null)
		{
			UnityEngine.Object.Destroy(attachJoint);
			attachJoint = null;
		}
	}

	private Joint CreateJoint(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		SpringJoint springJoint = base.gameObject.AddComponent<SpringJoint>();
		springJoint.autoConfigureConnectedAnchor = false;
		springJoint.anchor = -targetSpacePickupPosition;
		springJoint.connectedBody = target.UnityRigidbody;
		springJoint.connectedAnchor = Vector3.zero;
		springJoint.spring = springForce;
		springJoint.breakForce = breakForce;
		return springJoint;
	}
}
[RequireComponent(typeof(Tool))]
public class UnrollingScreen : Photon.MonoBehaviour
{
	[SerializeField]
	private Transform screenTop;

	[SerializeField]
	private Transform screenBottom;

	[SerializeField]
	private SlideshowScreen screen;

	[SerializeField]
	private float screenVisibilityDistance = 0.1f;

	private Tool tool;

	private Vector3 screenDownDirection;

	protected override void Awake()
	{
		base.Awake();
		tool = GetComponent<Tool>();
		if (tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
		}
		screenDownDirection = (screenBottom.position - screenTop.position).normalized;
	}

	private void FixedUpdate()
	{
		if (base.hasAuthority)
		{
			Vector3 lhs = screenTop.position - tool.RigidbodyEx.physicsPosition;
			if (Vector3.Dot(lhs, screenDownDirection) > 0f)
			{
				tool.RigidbodyEx.targetPosition = screenTop.position;
			}
			Vector3 lhs2 = screenBottom.position - tool.RigidbodyEx.physicsPosition;
			if (Vector3.Dot(lhs2, screenDownDirection) < 0f)
			{
				tool.RigidbodyEx.targetPosition = screenBottom.position;
				lhs2 = Vector3.zero;
			}
			float magnitude = lhs2.magnitude;
			if (magnitude <= screenVisibilityDistance && !screen.IsVisible)
			{
				screen.SetVisibility(visible: true);
			}
			else if (magnitude > screenVisibilityDistance && screen.IsVisible)
			{
				screen.SetVisibility(visible: false);
			}
		}
	}
}
