					drunk = Interlocked.CompareExchange(ref this.m_DrunkEvent, (Drunk)Delegate.Combine(drunk2, value), drunk);
				}
				while (drunk != drunk2);
			}
			remove
			{
				Drunk drunk = this.m_DrunkEvent;
				Drunk drunk2;
				do
				{
					drunk2 = drunk;
					drunk = Interlocked.CompareExchange(ref this.m_DrunkEvent, (Drunk)Delegate.Remove(drunk2, value), drunk);
				}
				while (drunk != drunk2);
			}
		}

		public event Action<DrinkableBottle> IsEmptyChangeEvent
		{
			add
			{
				Action<DrinkableBottle> action = this.m_IsEmptyChangeEvent;
				Action<DrinkableBottle> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_IsEmptyChangeEvent, (Action<DrinkableBottle>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<DrinkableBottle> action = this.m_IsEmptyChangeEvent;
				Action<DrinkableBottle> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_IsEmptyChangeEvent, (Action<DrinkableBottle>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_isEmpty = new SynchronizedField<bool>(this, "ie", defaultValue: false, SetterPermissionMode.AUTHORITY, OnIsEmptyChange);
			_isCorked = new SynchronizedField<bool>(this, "iu", defaultValue: true, SetterPermissionMode.AUTHORITY);
			tool.PostResetEvent += OnToolReset;
			tool.PostPickupEvent += OnToolPickup;
			if (eventListener != null)
			{
				eventListener.CollisionEvent += HandleParticleCollision;
			}
			if (cork != null && !IsCorked)
			{
				cork.SetActive(value: false);
			}
			StopEmitting();
			tool.HeldCollisionLayer = Layers.DynamicPhysicsIgnoreStaticPhysics;
			OnIsEmptyChange();
		}

		private void Start()
		{
			this.Update10hz(StaggeredUpdate);
			this.Update10hz(StaggeredLateUpdate);
		}

		private void OnDisable()
		{
			StopEmitting();
			drinkingHeadTransform = null;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostResetEvent -= OnToolReset;
			tool.PostPickupEvent -= OnToolPickup;
			if (eventListener != null)
			{
				eventListener.CollisionEvent -= HandleParticleCollision;
			}
		}

		private void StaggeredUpdate(float deltaTime)
		{
			if (!insideHeadCollider)
			{
				bool flag = Vector3.Dot(base.transform.up, Vector3.up) < 0f;
				bool flag2 = !IsEmpty && flag;
				if (onlyPourWhileHeld)
				{
					flag2 &= tool.IsHeldByPlayer;
				}
				flag2 &= !tool.IsEquippedOnPlayer;
				if (!flag)
				{
					canBeginPour = true;
				}
				if (flag2 && !IsEmitting && canBeginPour)
				{
					StartEmitting();
				}
				else if (!flag2 && IsEmitting)
				{
					StopEmitting();
				}
			}
		}

		private void StaggeredLateUpdate(float deltaTime)
		{
			if (drinkingHeadTransform != null)
			{
				mouthTrigger.enabled = true;
				if (insideHeadCollider)
				{
					AttemptDrinking(capTransform.position, intersectionDrinkRadius);
				}
				else if (IsEmitting)
				{
					PositionMouthTrigger();
				}
			}
			else
			{
				mouthTrigger.enabled = false;
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			if (TryAssignDrinker(other))
			{
				insideHeadCollider = true;
			}
		}

		private void OnTriggerExit(Collider other)
		{
			if (TryAssignDrinker(other))
			{
				insideHeadCollider = false;
			}
		}

		public void AuthorityMarkEmpty()
		{
			if (base.hasAuthority)
			{
				IsEmpty = true;
			}
		}

		private void OnIsEmptyChange()
		{
			if (liquidRendererRoot != null)
			{
				liquidRendererRoot.gameObject.SetActive(!IsEmpty);
			}
			if (shakeAudio != null)
			{
				shakeAudio.enabled = !IsEmpty;
			}
			if (this.IsEmptyChangeEvent != null)
			{
				this.IsEmptyChangeEvent(this);
			}
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (base.hasAuthority && !keepIsEmptyStateOnReset)
			{
				IsEmpty = false;
			}
			StopEmitting();
		}

		private void OnToolPickup(Tool thisTool)
		{
			if (IsCorked)
			{
				IsCorked = false;
				if (uncorkAudio != null)
				{
					AudioManager.Play3DSFX(uncorkAudio, base.transform);
				}
				if (cork != null)
				{
					cork.SetActive(value: false);
				}
			}
		}

		private void HandleParticleCollision(ParticleEventListener listener, Collider otherCollider, IEnumerable<ParticleCollisionEvent> collisions)
		{
			if (TryAssignDrinker(otherCollider) && CanDrink)
			{
				Vector3 worldPosition = collisions.Select((ParticleCollisionEvent c) => c.intersection).Average();
				AttemptDrinking(worldPosition, particleDrinkRadius);
			}
		}

		private void StartEmitting()
		{
			this.SafeStopSchedule(emissionRoutinePromise);
			emissionRoutinePromise = SingletonMonoBehaviour<Scheduler>.Instance.Run(this, MonitorEmissionCoroutine());
			EnableParticleEmission(emissionEnabled: true);
			canBeginPour = false;
		}

		private void StopEmitting()
		{
			EnableParticleEmission(emissionEnabled: false);
			this.SafeStopSchedule(emissionRoutinePromise);
			emissionRoutinePromise = null;
		}

		private void PositionMouthTrigger()
		{
			if (drinkingHeadTransform != null)
			{
				mouthTrigger.transform.position = drinkingHeadTransform.position;
				mouthTrigger.transform.rotation = drinkingHeadTransform.rotation;
			}
		}

		private IEnumerator<ISchedule> MonitorEmissionCoroutine()
		{
			float lifeRemaining = lifeSpan;
			float nextPourTime = UnityEngine.Time.time + pourInterval;
			while (lifeRemaining > 0f)
			{
				if (insideHeadCollider)
				{
					EnableParticleEmission(emissionEnabled: false);
					yield return Schedule.Until(() => !insideHeadCollider);
					EnableParticleEmission(emissionEnabled: true);
				}
				lifeRemaining -= UnityEngine.Time.deltaTime;
				if (pourAudio != null && UnityEngine.Time.time > nextPourTime)
				{
					float t = lifeRemaining / lifeSpan;
					float pitchShift = Mathf.Lerp(emptyPourPitchShift, pourAudio.pitchShift, t);
					AudioManager.Play3DSFX(pourAudio.audioClip, base.transform.position, pourAudio.volume, pourAudio.pitchVariation, pitchShift);
					nextPourTime = UnityEngine.Time.time + pourInterval;
				}
				yield return Schedule.NextFrame;
			}
			StopEmitting();
		}

		private void EnableParticleEmission(bool emissionEnabled)
		{
			for (int i = 0; i < waterParticles.Length; i++)
			{
				ParticleSystem.EmissionModule emission = waterParticles[i].emission;
				if (emission.enabled != emissionEnabled)
				{
					emission.enabled = emissionEnabled;
				}
			}
		}

		private bool TryAssignDrinker(Collider otherCollider)
		{
			if (otherCollider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
			{
				Player.BodyPart bodyPart;
				Player colliderPlayer = otherCollider.GetColliderPlayer(out bodyPart);
				if (bodyPart == Player.BodyPart.Head)
				{
					drinkingHeadTransform = otherCollider.transform;
					drinkingPlayer = colliderPlayer.PhotonPlayer;
					return true;
				}
			}
			return false;
		}

		private void AttemptDrinking(Vector3 worldPosition, float drinkRadius)
		{
			if (!CanDrink)
			{
				return;
			}
			PositionMouthTrigger();
			Vector3 b = mouthTrigger.transform.TransformPoint(mouthTrigger.center);
			float num = Vector3.Distance(worldPosition, b);
			if (!(num <= drinkRadius))
			{
				return;
			}
			if (drinkAudioClips.Length > 0)
			{
				RecRoomAudioClip recRoomAudioClip = drinkAudioClips[UnityEngine.Random.Range(0, drinkAudioClips.Length)];
				if (recRoomAudioClip != null)
				{
					AudioManager.Play3DSFX(recRoomAudioClip, mouthTrigger.transform.position);
				}
			}
			if (drinkSplashPrefab != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(drinkSplashPrefab);
				pooledParticle.Play(worldPosition, drinkingHeadTransform.rotation);
			}
			lastDrinkTime = UnityEngine.Time.time;
			if (this.DrunkEvent != null)
			{
				this.DrunkEvent(this, drinkingPlayer);
			}
		}
	}
}
