public class SlideshowScreen : Photon.MonoBehaviour
{
	[SerializeField]
	private Texture2D[] slideshow;

	[SerializeField]
	private Renderer screenRenderer;

	[SerializeField]
	private UnityEngine.UI.Button rightButton;

	[SerializeField]
	private UnityEngine.UI.Button leftButton;

	[SerializeField]
	private bool loop = true;

	private int slideIndex;

	private bool _isVisible;

	public bool IsVisible
	{
		get
		{
			return _isVisible;
		}
		private set
		{
			_isVisible = value;
			screenRenderer.gameObject.SetActive(_isVisible);
			leftButton.gameObject.SetActive(_isVisible);
			rightButton.gameObject.SetActive(_isVisible);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
	}

	private void Start()
	{
		IsVisible = false;
		UpdateMaterial();
		rightButton.GetComponentInParent<Canvas>().worldCamera = UIInputModule.Instance.ControllerCamera;
		leftButton.GetComponentInParent<Canvas>().worldCamera = UIInputModule.Instance.ControllerCamera;
	}

	[SkipRename]
	public void Button_NextSlide()
	{
		slideIndex++;
		if (slideIndex >= slideshow.Length)
		{
			if (loop)
			{
				slideIndex %= slideshow.Length;
			}
			else
			{
				slideIndex = slideshow.Length - 1;
			}
		}
		base.photonView.RpcAll(RpcSetIndex, slideIndex);
	}

	[SkipRename]
	public void Button_PrevSlide()
	{
		slideIndex--;
		if (slideIndex < 0)
		{
			if (loop)
			{
				slideIndex += slideshow.Length;
			}
			else
			{
				slideIndex = 0;
			}
		}
		base.photonView.RpcAll(RpcSetIndex, slideIndex);
	}

	public void SetVisibility(bool visible)
	{
		if (IsVisible != visible)
		{
			base.photonView.RpcAll(RpcSetVisibility, visible);
		}
	}

	private void UpdateMaterial()
	{
		screenRenderer.material.mainTexture = slideshow[slideIndex];
	}

	private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (base.hasAuthority)
		{
			base.photonView.RpcPlayer(newPlayer, RpcSetIndex, slideIndex);
			base.photonView.RpcPlayer(newPlayer, RpcSetVisibility, IsVisible);
		}
	}

	[PunRPC]
	public void RpcSetIndex(int currentIndex)
	{
		slideIndex = currentIndex;
		UpdateMaterial();
	}

	[PunRPC]
	public void RpcSetVisibility(bool visible)
	{
		IsVisible = visible;
	}
}
public class VendingMachine : Photon.MonoBehaviour
{
	[SerializeField]
	private Transform productReleaseTransform;

	[SerializeField]
	private ToolPool productPool;

	[SerializeField]
	private float timeBeforeProductDrop = 1.5f;

	[Header("Audio & Visuals")]
	[SerializeField]
	private RecRoomAudioClip machineFunctionAudioClip;

	[SerializeField]
	private RecRoomAudioClip productDropAudioClip;

	[SerializeField]
	private RecRoomAudioClip machineEmptyAudioClip;

	private const float buttonCooldown = 3f;

	private float lastButtonPressTime;

	private const float productReleaseCooldown = 5f;

	private float lastProductReleaseTime;

	private Animator animator;

	private static readonly int[] buttonPressIds = new int[4]
	{
		Animator.StringToHash("ButtonDown_1"),
		Animator.StringToHash("ButtonDown_2"),
		Animator.StringToHash("ButtonDown_3"),
		Animator.StringToHash("ButtonDown_4")
	};

	protected override void Awake()
	{
		base.Awake();
		if (productPool != null)
		{
			Tool[] pool = productPool.Pool;
			foreach (Tool tool in pool)
			{
				tool.PostResetEvent += OnProductReset;
			}
		}
		animator = GetComponent<Animator>();
	}

	private void Start()
	{
		if (productPool != null)
		{
			Tool[] pool = productPool.Pool;
			foreach (Tool tool in pool)
			{
				tool.SupportsAnimateIn = false;
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (productPool != null)
		{
			Tool[] pool = productPool.Pool;
			foreach (Tool tool in pool)
			{
				tool.PostResetEvent -= OnProductReset;
			}
		}
	}

	public void OnVendingButtonPressed(int buttonIndex)
	{
		if (UnityEngine.Time.time - lastButtonPressTime > 3f)
		{
			lastButtonPressTime = UnityEngine.Time.time;
			base.photonView.RpcMaster(RpcMasterRequestProductRelease);
			if (animator != null)
			{
				animator.SetTrigger(buttonPressIds[buttonIndex]);
			}
			if (machineFunctionAudioClip != null)
			{
				AudioManager.Play3DSFX(machineFunctionAudioClip, base.transform);
			}
		}
	}

	[PunRPC]
	private void RpcMasterRequestProductRelease()
	{
		if (PhotonNetwork.isMasterClient && productPool != null && UnityEngine.Time.time - lastProductReleaseTime > 5f)
		{
			Vector3 position = ((!(productReleaseTransform != null)) ? base.transform.position : productReleaseTransform.position);
			Quaternion rotation = ((!(productReleaseTransform != null)) ? base.transform.rotation : productReleaseTransform.rotation);
			Tool tool = productPool.Acquire(position, rotation);
			if (tool != null)
			{
				tool.RigidbodyEx.AddKinematic(this);
				StartCoroutine(ReleaseProductCoroutine(tool));
				lastProductReleaseTime = UnityEngine.Time.time;
			}
			else
			{
				base.photonView.RpcAll(RpcOnProductRelease, arg1: false);
			}
		}
	}

	private IEnumerator ReleaseProductCoroutine(Tool productToRelease)
	{
		yield return new WaitForSeconds(timeBeforeProductDrop);
		base.photonView.RpcAll(RpcOnProductRelease, arg1: true);
		productToRelease.RigidbodyEx.RemoveKinematic(this);
	}

	[PunRPC]
	private void RpcOnProductRelease(bool success)
	{
		if (success)
		{
			if (productDropAudioClip != null)
			{
				AudioManager.Play3DSFX(productDropAudioClip, base.transform);
			}
		}
		else if (machineEmptyAudioClip != null)
		{
			AudioManager.Play3DSFX(machineEmptyAudioClip, base.transform);
		}
	}

	private void OnProductReset(Tool product, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		productPool.Release(product);
	}
}
namespace RecRoom.Activities
{
	public class HoloTarget : Photon.MonoBehaviour
	{
		public enum TargetState
		{
			Activating,
			Active,
			Hit,
			Inactive,
			Invalid
		}

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action<HoloTarget> m_HoloTargetHitEvent;

		private static readonly int SPAWN_DEATH_ANIMATOR_ID;

		[SerializeField]
		private RecRoomAudioClip spawnAudio;

		[SerializeField]
		private RecRoomAudioClip deathAudio;

		[SerializeField]
		private Animator animator;

		[SerializeField]
		private CollisionForwarder collisionForwarder;

		public SynchronizedStateMachine HoloTargetStateMachine;

		private SynchronizedTimer masterHoloTargetStateTimer;

		private float hitStateDuration = 1f;

		private float activatingStateDuration = 1f;

		public static event Action<HoloTarget> HoloTargetHitEvent
		{
			add
			{
				Action<HoloTarget> action = HoloTarget.m_HoloTargetHitEvent;
				Action<HoloTarget> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref HoloTarget.m_HoloTargetHitEvent, (Action<HoloTarget>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<HoloTarget> action = HoloTarget.m_HoloTargetHitEvent;
				Action<HoloTarget> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref HoloTarget.m_HoloTargetHitEvent, (Action<HoloTarget>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public void Initialize()
		{
			HoloTargetStateMachine = new SynchronizedStateMachine("HOLOTARGET_" + base.photonView.viewID, SetterPermissionMode.MASTER);
			HoloTargetStateMachine.AddState(4, null, null, null);
			HoloTargetStateMachine.AddState(0, OnEnterActivatingState, null, OnUpdateActivatingState);
			HoloTargetStateMachine.AddState(1, OnEnterActiveState, null, null);
			HoloTargetStateMachine.AddState(2, OnEnterHitState, null, OnUpdateHitState);
			HoloTargetStateMachine.AddState(3, OnEnterInactiveState, null, null);
			HoloTargetStateMachine.Start(this, 4);
			masterHoloTargetStateTimer = new SynchronizedTimer(this, "HOLOTARGET_TIMER", SetterPermissionMode.MASTER);
			collisionForwarder.TriggerEnter += OnTriggerEnter;
		}

		protected override void OnDestroy()
		{
			collisionForwarder.TriggerEnter -= OnTriggerEnter;
		}

		private void Update()
		{
			HoloTargetStateMachine.Update();
			masterHoloTargetStateTimer.UpdateCallbacks();
		}

		private void OnTriggerEnter(Collider other)
		{
			if (PhotonNetwork.isMasterClient && HoloTargetStateMachine.CurrentStateId == 1)
			{
				PaddleballBall component = other.GetComponent<PaddleballBall>();
				if (component != null && !component.Tool.IsHeld)
				{
					HoloTargetStateMachine.EnterState(2);
				}
			}
		}

		private void OnEnterActivatingState(ushort previousStateId, ushort previousSubStateId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				masterHoloTargetStateTimer.StartTimer(activatingStateDuration);
			}
			base.gameObject.SetActive(value: true);
			AudioManager.Play3DSFX(spawnAudio, base.transform.position);
			if (animator != null)
			{
				animator.SetInteger(SPAWN_DEATH_ANIMATOR_ID, 0);
			}
		}

		private void OnUpdateActivatingState()
		{
			if (PhotonNetwork.isMasterClient && masterHoloTargetStateTimer.TimerOver)
			{
				HoloTargetStateMachine.EnterState(1);
			}
		}

		private void OnEnterActiveState(ushort previousStateId, ushort previousSubStateId)
		{
			base.gameObject.SetActive(value: true);
		}

		private void OnEnterHitState(ushort previousStateId, ushort previousSubStateId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				masterHoloTargetStateTimer.StartTimer(hitStateDuration);
			}
			AudioManager.Play3DSFX(deathAudio, base.transform.position);
			if (animator != null)
			{
				animator.SetInteger(SPAWN_DEATH_ANIMATOR_ID, 1);
			}
		}

		private void OnUpdateHitState()
		{
			if (PhotonNetwork.isMasterClient && masterHoloTargetStateTimer.TimerOver)
			{
				if (HoloTarget.HoloTargetHitEvent != null)
				{
					HoloTarget.HoloTargetHitEvent(this);
				}
				HoloTargetStateMachine.EnterState(3);
			}
		}

		private void OnEnterInactiveState(ushort previousStateId, ushort previousSubStateId)
		{
			base.gameObject.SetActive(value: false);
		}

		static HoloTarget()
		{
			HoloTarget.HoloTargetHitEvent = null;
			SPAWN_DEATH_ANIMATOR_ID = Animator.StringToHash("SpawnDeath");
		}
	}
	public class HoloTargetLevel : Photon.MonoBehaviour
	{
