	public class HoloTargetManager : Photon.MonoBehaviour
	{
		public HoloTargetLevel[] allLevels;

		private int numberOfHitsRequired;

		private SynchronizedField<int> _currentLevel;

		private SynchronizedField<int> _numberOfTargetsHit;

		private int CurrentLevel
		{
			get
			{
				return _currentLevel.Get();
			}
			set
			{
				if (value >= allLevels.Length)
				{
					value = 0;
				}
				_currentLevel.Set(value);
			}
		}

		private int NumberOfTargetsHit
		{
			get
			{
				return _numberOfTargetsHit.Get();
			}
			set
			{
				_numberOfTargetsHit.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_currentLevel = new SynchronizedField<int>(this, "CL", 0, SetterPermissionMode.MASTER, OnCurrentLevelChange);
			_numberOfTargetsHit = new SynchronizedField<int>(this, "NOTH", 0, SetterPermissionMode.MASTER);
			HoloTargetLevel[] array = allLevels;
			foreach (HoloTargetLevel holoTargetLevel in array)
			{
				holoTargetLevel.Initialize();
			}
			HoloTarget.HoloTargetHitEvent += OnTargetHit;
		}

		private void OnEnable()
		{
			if (PhotonNetwork.isMasterClient && CurrentLevel != 0)
			{
				CurrentLevel = 0;
			}
			else
			{
				OnCurrentLevelChange();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			HoloTarget.HoloTargetHitEvent -= OnTargetHit;
		}

		private void OnCurrentLevelChange()
		{
			NumberOfTargetsHit = 0;
			numberOfHitsRequired = allLevels[CurrentLevel].Targets.Length;
			for (int i = 0; i < allLevels.Length; i++)
			{
				allLevels[i].gameObject.SetActive(i == CurrentLevel);
			}
			allLevels[CurrentLevel].StartLevel();
		}

		private void OnTargetHit(HoloTarget target)
		{
			NumberOfTargetsHit++;
			if (NumberOfTargetsHit >= numberOfHitsRequired)
			{
				CurrentLevel++;
			}
		}
	}
}
public class Paddle : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RigidbodyPickup.SpringSettings springSettings = new RigidbodyPickup.SpringSettings
	{
		SpringForce = 50000f,
		Damper = 1f,
		MassMultiplier = 1f
	};

	private void Awake()
	{
		Tool component = GetComponent<Tool>();
		if (component != null && component.RigidbodyPickup != null)
		{
			component.RigidbodyEx.UnityRigidbody.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
