			_skippedTutorial = new SynchronizedField<bool>(player, "ST", defaultValue: false, SetterPermissionMode.ANYONE);
			_videoTutorial = new SynchronizedField<bool>(player, "VT", defaultValue: false, SetterPermissionMode.ANYONE);
