	public enum PaddleballSpawnPointTag
	{
		ANY = -1,
		NON_NUX_SPECTATOR,
		NUX_ONLY
	}

	public enum PaddleballGameStates
	{
		ROUND_RUNNING = 0,
		BALL_SCORED = 1,
		INVALID = 65535
	}

	[Header("Ball Scored State")]
	[SerializeField]
	private float ballScoredStateDuration = 2f;

	[Header("SFX and VFX")]
	[SerializeField]
	private RecRoomAudioClip goalSFX;

	[SerializeField]
	private RecRoomAudioClip goalVO;

	[SerializeField]
	private PooledParticle goalVFXPrefab;

	[Header("NUX")]
	[SerializeField]
	private PaddleballOOBE paddleballOOBE;

	private SynchronizedStateMachine paddleballStateMachine;

	private SynchronizedTimer masterPaddleballStateTimer;

	private TeleportationPortal[] lockingPortals;

	private List<PaddleballBall> allBalls;

	private PaddleballBall gameBall;

	private List<PaddleballBallSpawnPoint> ballSpawnPoints;

	private List<PaddleballGoal> goals;

	private SynchronizedField<GameTeam> servingTeamId;

	private Dictionary<int, PlayerNUXData> playerNUXData = new Dictionary<int, PlayerNUXData>();

	public new static PaddleballManager Instance => NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance as PaddleballManager;

	public bool IsAnyPlayerInTutorial
	{
		get
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				if (GetPlayerNUXData(player).IsInTutorial)
				{
					return true;
				}
			}
			return false;
		}
	}

	public bool AreAllPlayersInitialized
	{
		get
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				if (!GetPlayerNUXData(player).IsInitialized)
				{
					return false;
				}
			}
			return true;
		}
	}

	public bool HasAnyPlayerRunStandeeTutorial
	{
		get
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				if (GetPlayerNUXData(player).RanSocialStandeeTutorial)
				{
					return true;
				}
			}
			return false;
		}
	}

	public bool HasAnyPlayerSkippedTutorial
	{
		get
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				if (GetPlayerNUXData(player).SkippedTutorial)
				{
					return true;
				}
			}
			return false;
		}
	}

	public bool HasAnyPlayerWatchedVideoTutorial
	{
		get
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				if (GetPlayerNUXData(player).WatchedVideoTutorial)
				{
					return true;
				}
			}
			return false;
		}
	}

	public bool ReadyToPlay => !IsAnyPlayerInTutorial && AreAllPlayersInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.ReadyToPlay;

	public override string RuleTypeAutoTag => "paddleball";

	private GameTeam ServingTeam
	{
		get
		{
			return servingTeamId.Get();
		}
		set
		{
			servingTeamId.Set(value);
		}
	}

	public void LocalPlayerStartingTutorial()
	{
		PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
		PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
		playerNUXData.IsInTutorial = true;
	}

	public void LocalPlayerRanStandeeTutorial()
	{
		PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
		PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
		playerNUXData.RanSocialStandeeTutorial = true;
	}

	public void LocalPlayerLeavingTutorial()
	{
		if (Player.LocalPlayerExists)
		{
			PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
			PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
			playerNUXData.IsInTutorial = false;
		}
	}

	public void LocalPlayerSkippingTutorial()
	{
		PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
		PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
		playerNUXData.SkippedTutorial = true;
	}

	public void LocalPlayerWatchedVideoTutorial()
	{
		PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
		PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
		playerNUXData.WatchedVideoTutorial = true;
	}

	protected override void Awake()
	{
		base.Awake();
		GameManager.OnGameStartEvent += OnGameStart;
		GameManager.OnGameEndEvent += OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent += EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		GameManager.InitializeLocalPlayerEvent += InitializeLocalPlayer;
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		paddleballOOBE = UnityEngine.Object.FindObjectOfType<PaddleballOOBE>();
		lockingPortals = (from tp in UnityEngine.Object.FindObjectsOfType<TeleportationPortal>()
			where tp.SupportsInGameLocking
			select tp).ToArray();
		paddleballStateMachine = new SynchronizedStateMachine("PADDLEBALL", SetterPermissionMode.MASTER);
		paddleballStateMachine.AddState(ushort.MaxValue, null, null, null);
		paddleballStateMachine.AddState(0, OnEnterRoundRunningState, null, OnUpdateRoundRunningState);
		paddleballStateMachine.AddState(1, OnEnterBallScoredState, null, OnUpdateBallScoredState);
		masterPaddleballStateTimer = new SynchronizedTimer(this, "PADDLEBALL_TIMER", SetterPermissionMode.MASTER);
		allBalls = this.FindAllObjectsOfType<PaddleballBall>();
		for (int num = 0; num < allBalls.Count; num++)
		{
			if (!allBalls[num].GetComponent<GamePracticeObject>())
			{
				gameBall = allBalls[num];
				break;
			}
		}
		ballSpawnPoints = this.FindAllObjectsOfType<PaddleballBallSpawnPoint>();
		goals = this.FindAllObjectsOfType<PaddleballGoal>();
		for (int num2 = 0; num2 < goals.Count; num2++)
		{
			PaddleballGoal paddleballGoal = goals[num2];
			paddleballGoal.ScoreEvent = (PaddleballGoal.Score)Delegate.Combine(paddleballGoal.ScoreEvent, new PaddleballGoal.Score(OnGoalScore));
		}
		servingTeamId = new SynchronizedField<GameTeam>(this, "SERVING_TEAM", GameTeam.ANY, SetterPermissionMode.MASTER);
		if (PhotonNetwork.isMasterClient)
		{
			ServingTeam = GameTeam.TEAM_1;
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (gameBall != null && gameBall.Tool != null)
		{
			gameBall.Tool.RemoveCustomPickupCondition(CustomBallPickupCondition);
		}
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent -= EnableLocalPlayerToolRestrictions;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
		GameManager.InitializeLocalPlayerEvent -= InitializeLocalPlayer;
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
	}

	protected override void Start()
	{
		base.Start();
		gameBall.Tool.AddCustomPickupCondition(CustomBallPickupCondition);
		gameBall.Tool.NetworkTransform.UseDynamicDistanceExtrapolation = true;
		foreach (PaddleballBall allBall in allBalls)
		{
			allBall.Tool.ToolCleanup.PauseCleanup(this);
		}
		paddleballStateMachine.Start(this, ushort.MaxValue);
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Q2A_WelcomeToPaddleball)
		{
			StartCoroutine(paddleballOOBE.RunTutorial());
		}
		else
		{
			StartCoroutine(LocalInitAndCheckOtherPlayerTutorialStatus());
		}
	}

	private IEnumerator LocalInitAndCheckOtherPlayerTutorialStatus()
	{
		yield return SetPlayerInitialized();
		yield return CheckIfOtherPlayerInTutorialVOShouldPlay();
	}

	private IEnumerator CheckIfOtherPlayerInTutorialVOShouldPlay()
	{
		while (!AreAllPlayersInitialized)
		{
			yield return null;
		}
		if (!GetPlayerNUXData(Player.LocalPlayer.PhotonPlayer).IsInTutorial && IsAnyPlayerInTutorial)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = true;
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.OtherPlayerInTutorial);
		}
	}

	public IEnumerator SetPlayerInitialized()
	{
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		PlayerNUXData localPlayerData = GetPlayerNUXData(Player.LocalPlayer.PhotonPlayer);
		localPlayerData.IsInitialized = true;
		localPlayerData.TimeJoined = DateTime.UtcNow.ToString();
	}

	protected void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		StartCoroutine(CheckIfOtherPlayerInTutorialVOShouldPlay());
	}

	protected void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = IsAnyPlayerInTutorial;
		PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
		PlayerNUXData playerNUXData = GetPlayerNUXData(photonPlayer);
		if (player != photonPlayer && playerNUXData.IsInTutorial)
		{
			PlayerNUXData playerNUXData2 = GetPlayerNUXData(player);
			DateTime dateTime = DateTime.Parse(playerNUXData2.TimeJoined);
			DateTime dateTime2 = DateTime.Parse(playerNUXData.TimeJoined);
			double totalSeconds = (DateTime.UtcNow - dateTime).TotalSeconds;
			bool joinedFirst = dateTime < dateTime2;
			AnalyticsHelper.NUXOpponentLeftDuringTutorial(totalSeconds, joinedFirst);
		}
		RemovePlayerNUXData(player);
	}

	protected void Update()
	{
		paddleballStateMachine.Update();
		masterPaddleballStateTimer.UpdateCallbacks();
	}

	protected void InitializeSceneOnPreGame()
	{
		if (PhotonNetwork.isMasterClient)
		{
			gameBall.Tool.Disable();
		}
	}

	protected void OnGameStart()
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = false;
		if (PhotonNetwork.isMasterClient)
		{
			paddleballStateMachine.EnterState(0);
		}
		gameBall.Tool.NetworkTransform.PotentialOwners.Clear();
		IEnumerable<PhotonPlayer> activePlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer item in activePlayers)
		{
			gameBall.Tool.NetworkTransform.PotentialOwners.Add(item);
		}
		TeleportationPortal[] array = lockingPortals;
		foreach (TeleportationPortal teleportationPortal in array)
		{
			teleportationPortal.gameObject.SetActive(value: false);
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = "First to " + NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin + " Goals";
	}

	protected void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			paddleballStateMachine.EnterState(ushort.MaxValue);
		}
		TeleportationPortal[] array = lockingPortals;
		foreach (TeleportationPortal teleportationPortal in array)
		{
			teleportationPortal.gameObject.SetActive(value: true);
		}
	}

	protected void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoiningInProgress)
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
	}

	private PlayerNUXData GetPlayerNUXData(PhotonPlayer player)
	{
		if (!playerNUXData.TryGetValue(player.ID, out var value))
		{
			value = new PlayerNUXData(player);
			playerNUXData[player.ID] = value;
		}
		return value;
	}

	private void RemovePlayerNUXData(PhotonPlayer player)
	{
		if (playerNUXData.ContainsKey(player.ID))
		{
			playerNUXData.Remove(player.ID);
		}
	}

	private void OnGoalScore(PaddleballGoal goal, Vector3 scorePoint)
	{
		if (goal.hasAuthority && IsValidScore())
		{
			base.photonView.RpcMaster(RpcMasterRequestScore, goal, scorePoint);
		}
	}

	[PunRPC]
	private void RpcMasterRequestScore(PaddleballGoal goal, Vector3 scorePoint)
	{
		if (PhotonNetwork.isMasterClient && goal != null && IsValidScore())
		{
			GameTeam anotherTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(goal.Team);
			if (anotherTeam != GameTeam.ANY)
			{
				ServingTeam = goal.Team;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddScore(anotherTeam, 1);
				paddleballStateMachine.EnterState(1);
				base.photonView.RpcAll(RpcOnScore, goal, scorePoint);
			}
		}
	}

	private bool IsValidScore()
	{
		return paddleballStateMachine.CurrentStateId == 0;
	}

	[PunRPC]
	private void RpcOnScore(PaddleballGoal goal, Vector3 scorePoint)
	{
		if (goal != null)
		{
			GameTeam anotherTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(goal.Team);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(anotherTeam) + " Scores!", 3f);
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == anotherTeam)
			{
				Player.LocalPlayer.PlayerEvents.PaddleballScore();
			}
			AudioManager.Play3DSFX(goalSFX, scorePoint);
			AudioManager.Play3DSFX(goalVO, scorePoint);
			PooledParticle.TryPlayPrefab(goalVFXPrefab, scorePoint);
		}
	}

	private void MasterTransferGoalAuthority()
	{
		for (int i = 0; i < goals.Count; i++)
		{
			PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(goals[i].Team);
			if (teamPlayers.Length > 0 && goals[i].owner != teamPlayers[0])
			{
				goals[i].photonView.TransferOwnership(teamPlayers[0]);
			}
		}
	}

	private void MasterResetBall(GameTeam servingTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			Transform teamBallSpawnPoint = GetTeamBallSpawnPoint(servingTeam);
			if (teamBallSpawnPoint != null)
			{
				gameBall.Tool.LocalTakeOwnershipAndResetToDefault(teamBallSpawnPoint.position, teamBallSpawnPoint.rotation);
			}
			else
			{
				gameBall.Tool.LocalTakeOwnershipAndResetToLastSpawnPosition();
			}
		}
	}

	private void MasterHideBall(GameTeam servingTeam)
	{
		if (PhotonNetwork.isMasterClient)
		{
			Transform teamBallSpawnPoint = GetTeamBallSpawnPoint(servingTeam);
			if (teamBallSpawnPoint != null)
			{
				gameBall.Tool.LocalTakeOwnershipAndResetToDefault(teamBallSpawnPoint.position + Vector3.down * 20f, teamBallSpawnPoint.rotation);
			}
			else
			{
				MasterResetBall(servingTeam);
			}
		}
	}

	private Transform GetTeamBallSpawnPoint(GameTeam team)
	{
		Transform transform = null;
		for (int i = 0; i < ballSpawnPoints.Count; i++)
		{
			if (ballSpawnPoints[i].Team == team)
			{
				transform = ballSpawnPoints[i].transform;
				break;
			}
		}
		if (transform == null)
		{
			UnityEngine.Debug.LogError("Missing ball spawn point for team " + team);
		}
		return transform;
	}

	private void OnEnterRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		GameTeam servingTeam = ServingTeam;
		if (PhotonNetwork.isMasterClient)
		{
			MasterTransferGoalAuthority();
			MasterResetBall(servingTeam);
		}
		gameBall.ClearTrails();
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out var _, out var highestScore);
		string subtitleText = ((highestScore != NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin - 1) ? null : "Match Point!");
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(ServingTeam) + "'s Serve!", subtitleText, 3f);
	}

	private void OnUpdateRoundRunningState()
	{
		if (gameBall.transform.position.y < -5f)
		{
			MasterResetBall(ServingTeam);
		}
	}

	private void OnEnterBallScoredState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterPaddleballStateTimer.StartTimer(ballScoredStateDuration);
		}
		MasterHideBall(ServingTeam);
		gameBall.ClearTrails();
	}

	private void OnUpdateBallScoredState()
	{
		if (PhotonNetwork.isMasterClient && masterPaddleballStateTimer.TimerOver)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out var _, out var highestScore);
			if (highestScore >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
			else
			{
				paddleballStateMachine.EnterState(0);
			}
		}
	}

	protected void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
	{
		gameBall.Tool.SetPickupEnabled(pickupEnabled, this);
	}

	private bool CustomBallPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		return paddleballStateMachine.CurrentStateId == 0;
	}
}
public class PaddleballOOBE : OOBEFlowBase
{
	[SerializeField]
	private UIProjector scoreboardProjectorForNUX;

	[SerializeField]
	private TeleportationPortal practiceDoorHighlightForNUX;

	[SerializeField]
	private Transform[] pathToPracticeDoorNUX;

	[SerializeField]
	private GameObject pathMarkerNUX;

	[SerializeField]
	private float timeToTraversePathNUX = 3f;

	[SerializeField]
	private TeleportationPortal recCenterDoorHighlightForNUX;

	[SerializeField]
	private TeleportationPortal enterCourtTeleportationPortal;

	private bool Q2A_isWaitingOnGameToStart;

	private float Q2A_waitingStartTime;

	private Coroutine leadToPracticeDoorCoroutine;

	private PaddleballManager paddleballManager;

	private WatchUI watchMenu;

	private RecRoomAudioClip howToOpenMenuAudio;

	private const float timeBetweenStates = 1f;

	private bool isInitialized;

	private float enteredSceneTime;

	private List<TeleportationPortal> highlightedPortals = new List<TeleportationPortal>();

	protected override void OnDestroy()
	{
		if (Q2A_isWaitingOnGameToStart && SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance != null)
		{
			AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToPaddleball, UnityEngine.Time.time - Q2A_waitingStartTime, InterruptableFlow.FlowState.Incomplete);
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
		}
		enterCourtTeleportationPortal.LocalPlayerUseEvent -= OnLocalPlayerEnterCourt;
		base.OnDestroy();
	}

	public IEnumerator RunTutorial()
	{
		yield return null;
		if (!isInitialized)
		{
			InitializeForTutorial();
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = true;
		enteredSceneTime = UnityEngine.Time.time;
		enterCourtTeleportationPortal.LocalPlayerUseEvent += OnLocalPlayerEnterCourt;
		float startTime = UnityEngine.Time.time;
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		WatchChallengesTeachableMoment challengesTutorial = SingletonMonoBehaviour<TutorialManager>.Instance.GetTeachableMoment<WatchChallengesTeachableMoment>();
		if (challengesTutorial != null)
		{
			challengesTutorial.Suppress = true;
		}
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_ThisIsPaddleball);
		yield return new WaitForSeconds(1f);
		paddleballManager.LocalPlayerSkippingTutorial();
		yield return paddleballManager.SetPlayerInitialized();
		if (!paddleballManager.ReadyToPlay)
		{
			Q2A_waitingStartTime = UnityEngine.Time.time;
			Q2A_isWaitingOnGameToStart = true;
			if (paddleballManager.IsAnyPlayerInTutorial)
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.OtherPlayerInTutorial);
			}
			else
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_YoullBeMatchedSoon);
			}
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_WALK)
			{
				ShowHelpPopup(TutorialManager.HelpType.WalkButton);
				SingletonMonoBehaviour<Scheduler>.Instance.Run(WaitForPlayerToWalkMinDistance(Player.LocalPlayer.CurrentFloorPosition, 1f)).Then(delegate
				{
					HideHelpPopup();
				});
			}
			else
			{
				Player.LocalPlayer.PlayerLocomotion.TeleportEvent += HideTeleportHelpOnPlayerTeleport;
				ShowHelpPopup(TutorialManager.HelpType.TeleportButton);
			}
			float timeSinceLastPrompt = 0f;
			float longWaitTime1 = 30f;
			float longWaitTime2 = 40f;
			leadToPracticeDoorCoroutine = StartCoroutine(LeadToPracticeDoor());
			while (!paddleballManager.ReadyToPlay)
			{
				yield return null;
				timeSinceLastPrompt += UnityEngine.Time.deltaTime;
				if (timeSinceLastPrompt > longWaitTime1)
				{
					yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_WereStillLooking);
					timeSinceLastPrompt = 0f;
					break;
				}
			}
			while (!paddleballManager.ReadyToPlay)
			{
				yield return null;
				timeSinceLastPrompt += UnityEngine.Time.deltaTime;
				if (timeSinceLastPrompt > longWaitTime2)
				{
					if (challengesTutorial != null)
					{
						challengesTutorial.Suppress = false;
					}
					yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_IfYouDontWantToWait);
					timeSinceLastPrompt = 0f;
				}
			}
		}
		if (leadToPracticeDoorCoroutine != null)
		{
			StopCoroutine(leadToPracticeDoorCoroutine);
			leadToPracticeDoorCoroutine = null;
			pathMarkerNUX.gameObject.SetActive(value: false);
			RemoveHighlightFromDoor(practiceDoorHighlightForNUX);
		}
		yield return new WaitForSeconds(1f);
		if (scoreboardProjectorForNUX != null)
		{
			scoreboardProjectorForNUX.Visibility = ProjectorBase.VisibilityState.ForceOpen;
		}
		yield return new WaitForSeconds(0.5f);
		List<Player> players = Player.All;
		bool isThereAJuniorPlayer = false;
		for (int num = 0; num < players.Count; num++)
		{
			if (!(players[num] == null))
			{
				Profile profile = Profiles.Get(players[num].PlayerId);
				if (profile != null && (bool)profile.JuniorProfile)
				{
					isThereAJuniorPlayer = true;
					break;
				}
			}
		}
		if (isThereAJuniorPlayer)
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_YouveBeenMatchedJunior);
		}
		else
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_YouveBeenMatched);
		}
		while (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			yield return null;
		}
		Q2A_isWaitingOnGameToStart = false;
		float endTime = UnityEngine.Time.time;
		AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToPaddleball, endTime - startTime, InterruptableFlow.FlowState.Complete);
		startTime = UnityEngine.Time.time;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_2);
		while (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_CongratulationsOnFirstGame);
		yield return new WaitForSeconds(1f);
		StartCoroutine(HighlightRecCenterDoor());
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_GoToTheRecCenter);
		endTime = UnityEngine.Time.time;
		AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_FinishedFirstGame, endTime - startTime, InterruptableFlow.FlowState.Complete);
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = paddleballManager.IsAnyPlayerInTutorial;
		SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
		if (challengesTutorial != null)
		{
			challengesTutorial.Suppress = false;
		}
	}

	private void InitializeForTutorial()
	{
		if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerUI.WatchMenu != null)
		{
			watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		}
		else
		{
			StartCoroutine(GetPlayerInitData());
		}
		howToOpenMenuAudio = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.LookAtWristToViewWatch);
		paddleballManager = PaddleballManager.Instance;
		isInitialized = true;
	}

	private IEnumerator GetPlayerInitData()
	{
		while (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerUI.WatchMenu == null)
		{
			yield return null;
		}
		watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
	}

	private void OnLocalPlayerEnterCourt()
	{
		AnalyticsHelper.NUXEnteredPaddleballCourt(UnityEngine.Time.time - enteredSceneTime);
		if (leadToPracticeDoorCoroutine != null)
		{
			StopCoroutine(leadToPracticeDoorCoroutine);
			HideHelpPopup();
			leadToPracticeDoorCoroutine = null;
			pathMarkerNUX.gameObject.SetActive(value: false);
			RemoveHighlightFromDoor(practiceDoorHighlightForNUX);
		}
	}

	private void HideTeleportHelpOnPlayerTeleport(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
	{
		HideHelpPopup();
		Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= HideTeleportHelpOnPlayerTeleport;
	}

	private IEnumerator RunWaitUntilPlayerOpensMenu(Action<InterruptableFlow.FlowState> onComplete)
	{
		yield return RunInterruptableFlow(initialHelpVO: SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.OpenWatch), condition: () => watchMenu.FullyVisible ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, repeatingHelp: howToOpenMenuAudio, onComplete: onComplete, helpInterval: 15f, maxHelpCount: 3, debugString: "WaitUntilPlayerOpensMenu");
	}

	private IEnumerator LeadToPracticeDoor()
	{
		BezierPath path = null;
		if (pathToPracticeDoorNUX != null && pathToPracticeDoorNUX.Length >= 4)
		{
			path = new BezierPath();
			path.AddCurve(pathToPracticeDoorNUX[0].position, pathToPracticeDoorNUX[1].position, pathToPracticeDoorNUX[2].position, pathToPracticeDoorNUX[3].position);
			for (int i = 6; i < pathToPracticeDoorNUX.Length; i += 3)
			{
				path.AddCurve(pathToPracticeDoorNUX[i - 2].position, pathToPracticeDoorNUX[i - 1].position, pathToPracticeDoorNUX[i].position);
			}
		}
		while (true)
		{
			float timeInState = 0f;
			pathMarkerNUX.gameObject.SetActive(value: true);
			while (timeInState < timeToTraversePathNUX)
			{
				timeInState += UnityEngine.Time.deltaTime;
				if (pathMarkerNUX != null && path != null)
				{
					float t = timeInState / timeToTraversePathNUX;
					Vector3 position = path.EvaluatePath(t);
					pathMarkerNUX.transform.position = position;
				}
				yield return null;
			}
			pathMarkerNUX.gameObject.SetActive(value: false);
			int numHighlights = 3;
			float highlightTime = 0.5f;
			float timeBetweenHighlights = 0.25f;
			for (int j = 0; j < numHighlights; j++)
			{
				timeInState = 0f;
				while (timeInState < highlightTime)
				{
					timeInState += UnityEngine.Time.deltaTime;
					AddHighlightToDoor(practiceDoorHighlightForNUX);
					yield return null;
				}
				RemoveHighlightFromDoor(practiceDoorHighlightForNUX);
				timeInState = 0f;
				while (timeInState < timeBetweenHighlights)
				{
					timeInState += UnityEngine.Time.deltaTime;
					yield return null;
				}
			}
		}
	}

	private IEnumerator HighlightRecCenterDoor()
	{
		float timeBetweenHighlights = 0.25f;
		float highlightTime = 0.75f;
		int numFlashes = 3;
		float delayBetweenCycles = 2f;
		float time = 0f;
		while (true)
		{
			for (int i = 0; i < numFlashes; i++)
			{
				time = 0f;
				RemoveHighlightFromDoor(recCenterDoorHighlightForNUX);
				while (time < timeBetweenHighlights)
				{
					time += UnityEngine.Time.deltaTime;
					yield return null;
				}
				time = 0f;
				while (time < highlightTime)
				{
					time += UnityEngine.Time.deltaTime;
					AddHighlightToDoor(recCenterDoorHighlightForNUX);
					yield return null;
				}
			}
			time = 0f;
			while (time < delayBetweenCycles)
			{
				AddHighlightToDoor(recCenterDoorHighlightForNUX);
				time += UnityEngine.Time.deltaTime;
				yield return null;
			}
		}
	}

	private IEnumerator<ISchedule> WaitForPlayerToWalkMinDistance(Vector3 startPosition, float minDistance)
	{
		float currentDistance = 0f;
		do
		{
			yield return Schedule.Wait(1f);
			currentDistance = Vector3.Distance(startPosition, Player.LocalPlayer.CurrentFloorPosition);
		}
		while (currentDistance < minDistance);
	}

	private void AddHighlightToDoor(TeleportationPortal portal)
	{
		if (!highlightedPortals.Contains(portal))
		{
			portal.Highlight = true;
			highlightedPortals.Add(portal);
		}
	}

	private void RemoveHighlightFromDoor(TeleportationPortal portal)
	{
		portal.Highlight = false;
		highlightedPortals.Remove(portal);
	}

	private void Update()
	{
		if (highlightedPortals != null && highlightedPortals.Count > 0)
		{
			for (int i = 0; i < highlightedPortals.Count; i++)
			{
				highlightedPortals[i].RenderHighlight();
			}
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class BurstFireGun : RangedWeapon
	{
		private enum BurstMode
		{
			SPRAY,
			SIMPLE
		}

		private const float KICKBACK_RECOIL_DIRECTION = -1f;

		private const float DEFAULT_SPRAY_TARGET_DISTANCE = 50f;

		[Header("Burst")]
		[SerializeField]
		private BurstMode burstMode;

		[Header("Kickback")]
		[SerializeField]
		private Transform kickbackTransform;

		[SerializeField]
		private float totalBurstAngle = 5f;

		[Header("Kickback Curve")]
		private float curvePeakTimeNormalized = 0.25f;

		[SerializeField]
		private float curveNextShotTimeNormalized = 0.75f;

		[Header("Simple Burst")]
		[SerializeField]
		private float simpleBurstModeBurstSize = 16f;

		[Header("Spray")]
		[SerializeField]
		private bool hasMaxDistance;

		[SerializeField]
		private float maxDistance = 50f;

		[SerializeField]
		private Transform sprayTargetRoot;

		private Transform[] sprayTargets;

		private Coroutine automaticCoroutine;

		private Coroutine kickbackCoroutine;

		private float KickbackAngle
		{
			get
			{
				float num = 0f;
				if (kickbackTransform != null)
				{
					num = kickbackTransform.localEulerAngles.x;
					if (num > 180f)
					{
						num -= 360f;
					}
					else if (num < -180f)
					{
						num += 360f;
					}
				}
				return num;
			}
			set
			{
				if (kickbackTransform != null)
				{
					Vector3 localEulerAngles = kickbackTransform.localEulerAngles;
					localEulerAngles.x = value;
					kickbackTransform.localEulerAngles = localEulerAngles;
				}
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (burstMode == BurstMode.SPRAY)
			{
				if (sprayTargetRoot == null || sprayTargetRoot.childCount == 0)
				{
					UnityEngine.Debug.LogError(base.name + " is missing spray targets.");
				}
				else
				{
					sprayTargets = new Transform[sprayTargetRoot.childCount];
					for (int i = 0; i < sprayTargetRoot.childCount; i++)
					{
						sprayTargets[i] = sprayTargetRoot.GetChild(i);
					}
				}
			}
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent += OnInputDown;
				base.Tool.InputUpEvent += OnInputUp;
				base.Tool.InputCancelledEvent += OnInputCancelled;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent -= OnInputDown;
				base.Tool.InputUpEvent -= OnInputUp;
				base.Tool.InputCancelledEvent -= OnInputCancelled;
			}
		}

		private void OnInputDown(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (base.IsMisfire || base.IsOnCooldown)
				{
					base.WeaponAudio.OnMisfire();
				}
				else
				{
					StartAutomaticCoroutine();
				}
			}
		}

		private void OnInputUp(Tool thisTool)
		{
			StopAutomaticCoroutine();
		}

		private void OnInputCancelled(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				StopAutomaticCoroutine();
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				if (!base.hasAuthority)
				{
					ApplyKickback(Mathf.RoundToInt(chargeAmount));
				}
				FireBullet(position, rotation, velocity, 1f, shotId);
			}
		}

		private void StartAutomaticCoroutine()
		{
			StopAutomaticCoroutine();
			automaticCoroutine = StartCoroutine(AutomaticCoroutine());
		}

		private void StopAutomaticCoroutine()
		{
			if (automaticCoroutine != null)
			{
				StopCoroutine(automaticCoroutine);
				automaticCoroutine = null;
			}
		}

		private bool AutomaticCoroutineIsRunning()
		{
			return automaticCoroutine != null;
		}

		private IEnumerator AutomaticCoroutine()
		{
			float timeBetweenShots = 1f / maximumAutomaticFiringRate;
			if (burstMode == BurstMode.SPRAY)
			{
				sprayTargetRoot.localPosition = new Vector3(0f, 0f, (!hasMaxDistance) ? 50f : maxDistance);
				for (int i = 0; i < sprayTargets.Length; i++)
				{
					if (!base.HasEnoughMagazineAmmunition)
					{
						TryPlayOutOfAmmoFeedback();
						break;
					}
					if (base.IsMisfire)
					{
						base.WeaponAudio.OnMisfire();
						break;
					}
					ApplyKickback(i);
					Vector3 vector = (sprayTargets[i].position - barrelTransform.position).normalized;
					if (HasOverridenTargetPoint)
					{
						Quaternion quaternion = Quaternion.FromToRotation(barrelTransform.forward, vector);
						Vector3 normalized = (OverrideTargetPoint - barrelTransform.position).normalized;
						vector = quaternion * normalized;
					}
					Fire(vector * bulletFireSpeed, i);
					yield return WaitBetweenShots(timeBetweenShots);
				}
			}
			else
			{
				for (int j = 0; (float)j < simpleBurstModeBurstSize; j++)
				{
					if (!base.HasEnoughMagazineAmmunition)
					{
						TryPlayOutOfAmmoFeedback();
					}
					else if (base.IsMisfire)
					{
						base.WeaponAudio.OnMisfire();
					}
					else
					{
						ApplyKickback(j);
						Fire(j);
					}
					yield return WaitBetweenShots(timeBetweenShots);
				}
			}
			automaticCoroutine = null;
		}

		private IEnumerator WaitBetweenShots(float time)
		{
			for (float timer = 0f; timer < time; timer += UnityEngine.Time.deltaTime)
			{
				yield return null;
			}
		}

		private void ApplyKickback(int semiAutomaticShotCount)
		{
			StopKickbackCoroutine();
			kickbackCoroutine = StartCoroutine(KickbackCoroutine(semiAutomaticShotCount));
		}

		private void StopKickbackCoroutine()
		{
			if (kickbackCoroutine != null)
			{
				StopCoroutine(kickbackCoroutine);
				kickbackCoroutine = null;
			}
		}

		private IEnumerator KickbackCoroutine(int semiAutomaticShotCount)
		{
			if (!(kickbackTransform == null))
			{
				float singleShotKickbackAngle = totalBurstAngle / (float)sprayTargets.Length;
				float timeBetweenShots = 1f / maximumAutomaticFiringRate;
				float singleShotKickbackDuration = UnityExtensions.InverseLerpForMax(0f, timeBetweenShots, curveNextShotTimeNormalized);
				float initialAngle = (float)semiAutomaticShotCount * singleShotKickbackAngle * -1f;
				float initialVelocity = 0f;
				float acceleration = 0f;
				CalculateKickbackParameters(curvePeakTimeNormalized * singleShotKickbackDuration, curveNextShotTimeNormalized * singleShotKickbackDuration, singleShotKickbackDuration, singleShotKickbackAngle, out initialVelocity, out acceleration);
				float timer = 0f;
				for (float returnToRestTime = CalculateTotalKickbackTime(Mathf.Abs(initialAngle), initialVelocity, acceleration); timer < returnToRestTime; timer += UnityEngine.Time.deltaTime)
				{
					float deltaAngle = initialVelocity * timer + 0.5f * acceleration * timer * timer;
					KickbackAngle = initialAngle + deltaAngle * -1f;
					yield return null;
				}
				KickbackAngle = 0f;
				kickbackCoroutine = null;
			}
		}

		private void CalculateKickbackParameters(float peakTime, float sampleTime, float finalTime, float sampleValue, out float initialVelocity, out float acceleration)
		{
			float t = Mathf.InverseLerp(peakTime, 1f, sampleTime);
			float num = UnityExtensions.InverseLerpForMin(0f, sampleValue, t);
			initialVelocity = 2f * num / peakTime;
			acceleration = -2f * initialVelocity / finalTime;
		}

		private float CalculateTotalKickbackTime(float initialValue, float initialVelocity, float acceleration)
		{
			float num = 0f;
			float num2 = num - initialValue;
			return UnityExtensions.SolveQuadraticEquationMaxValue(acceleration / 2f, initialVelocity, 0f - num2);
		}
	}
}
