namespace RecRoom.Tools.Weapons
{
	public class Grenade : Weapon
	{
		private enum LifetimeState
		{
			DISARMED,
			ARMED,
			DETONATED
		}

		[Header("Explosion")]
		[SerializeField]
		private float explosionRadius = 5f;

		[SerializeField]
		private float explosionForce = 30f;

		[SerializeField]
		protected AnimationCurve forceFalloff = AnimationCurve.Linear(0f, 1f, 1f, 1f);

		[SerializeField]
		protected AnimationCurve damageFalloff = AnimationCurve.Linear(0f, 1f, 1f, 1f);

		[SerializeField]
		private float explosionTimeout = 5f;

		[Header("Visuals")]
		[SerializeField]
		private Transform visualRoot;

		[SerializeField]
		private PooledParticle explosionParticlesPrefab;

		[SerializeField]
		private PooledParticle armedParticlesPrefab;

		[SerializeField]
		private Transform armedParticlesTransform;

		[SerializeField]
		private Color defaultColor = Color.green;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip explodeAudio;

		[SerializeField]
		private RecRoomAudioClip activeAudio;

		[SerializeField]
		private RecRoomAudioClip countdownAudio;

		[SerializeField]
		private AnimationCurve explosionTimeLeftToCountdownAudioCurve;

		private Explosive explosive = new Explosive();

		private SFXAudioSource armedAudioSource;

		private PooledParticle armedParticles;

		private bool explosionAllowed = true;

		private float lastArmedAudioPlayTime;

		private SynchronizedStateMachine lifetimeStateMachine;

		private SynchronizedTimer lifetimeTimer;

		private bool destroyAfterDetonation;

		[NonSerialized]
		public bool AutomaticallyArmOnNextRelease = true;

		protected override Color WeaponColor => (!(base.TeamColor != null) || !base.TeamColor.IsValidTeam) ? defaultColor : base.TeamColor.Color;

		protected override void Awake()
		{
			base.Awake();
			AutomaticallyArmOnNextRelease = true;
			lifetimeStateMachine = new SynchronizedStateMachine("LTSM", SetterPermissionMode.AUTHORITY);
			lifetimeStateMachine.AddState(0, null, null, null);
			lifetimeStateMachine.AddState(1, OnEnterArmedState, OnExitArmedState, OnUpdateArmedState);
			lifetimeStateMachine.AddState(2, OnEnterDetonatedState, OnExitDetonatedState, null);
			lifetimeTimer = new SynchronizedTimer(this, "LTT", SetterPermissionMode.AUTHORITY);
			explosive.PlayerImpactEvent += OnExplosivePlayerImpact;
			explosive.EnemyImpactEvent += OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent += OnExplosiveTrapImpact;
			explosive.ToolImpactEvent += OnExplosiveToolImpact;
			if (base.Tool != null)
			{
				base.Tool.PreReleaseEvent += OnPreRelease;
				base.Tool.PreAttachEvent += OnPreAttach;
			}
		}

		protected override void Start()
		{
			base.Start();
			CheckIfDestroyAfterDetonation();
			PlayerSpawnedEquipment playerSpawnedEquipment = base.Tool.PlayerSpawnedEquipment;
			if (playerSpawnedEquipment != null)
			{
				PlayerSpawnedEquipment.Purpose toolPurpose = playerSpawnedEquipment.ToolPurpose;
				if (toolPurpose == PlayerSpawnedEquipment.Purpose.Drawer)
				{
					explosionAllowed = false;
				}
			}
			LifetimeState lifetimeState = ((base.Wielder.Enemy != null) ? LifetimeState.ARMED : LifetimeState.DISARMED);
			lifetimeStateMachine.Start(this, (ushort)lifetimeState);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PreReleaseEvent -= OnPreRelease;
				base.Tool.PreAttachEvent -= OnPreAttach;
			}
			explosive.PlayerImpactEvent -= OnExplosivePlayerImpact;
			explosive.EnemyImpactEvent -= OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent -= OnExplosiveTrapImpact;
			explosive.ToolImpactEvent -= OnExplosiveToolImpact;
			StopArmedParticles();
			StopArmedLoopingAudio();
		}

		protected void Update()
		{
			lifetimeStateMachine.Update();
			lifetimeTimer.UpdateCallbacks();
		}

		private void OnEnterArmedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.Tool != null && base.Tool.ToolCleanup != null)
			{
				base.Tool.ToolCleanup.PauseCleanup(this);
			}
			StartArmedParticles();
			StartArmedLoopingAudio();
			lastArmedAudioPlayTime = explosionTimeout;
			if (base.hasAuthority)
			{
				lifetimeTimer.StartTimer(explosionTimeout);
			}
		}

		private void OnUpdateArmedState()
		{
			float timeRemaining = lifetimeTimer.TimeRemaining;
			float num = explosionTimeLeftToCountdownAudioCurve.Evaluate(timeRemaining / explosionTimeout);
			if (lastArmedAudioPlayTime - timeRemaining > num)
			{
				lastArmedAudioPlayTime = timeRemaining;
				AudioManager.Play3DSFX(countdownAudio, base.transform.position);
			}
			if (base.hasAuthority && lifetimeTimer.TimerOver)
			{
				lifetimeStateMachine.EnterState(2);
			}
		}

		private void OnExitArmedState(ushort nextStateId, ushort nextSubStateId)
		{
			if (base.Tool != null && base.Tool.ToolCleanup != null)
			{
				base.Tool.ToolCleanup.ResumeCleanup(this);
			}
			StopArmedParticles();
			StopArmedLoopingAudio();
		}

		private void OnEnterDetonatedState(ushort previousStateId, ushort previousSubStateId)
		{
			EnableBody(enabled: false);
			PlayExplosionFeedback();
			explosive.Explode(base.transform.position, explosionRadius, explosionForce, damageFalloff, forceFalloff, 1f);
			if (!(base.Tool != null))
			{
				return;
			}
			bool flag = base.Tool.ToolCleanup != null && base.Tool.ToolCleanup.OverridesActive;
			if (destroyAfterDetonation && !flag)
			{
				if (PhotonNetwork.isMasterClient)
				{
					PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
				}
			}
			else if (base.hasAuthority)
			{
				base.Tool.HolderInfo = ToolHolderInfo.NotHeld;
				base.Tool.ToolCleanup?.AuthorityQueueForceCleanup();
			}
		}

		private void OnExitDetonatedState(ushort nextStateId, ushort nextSubStateId)
		{
			EnableBody(enabled: true);
		}

		private void CheckIfDestroyAfterDetonation()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DestroyBrokenEquipment)
			{
				destroyAfterDetonation = true;
			}
			else
			{
				destroyAfterDetonation = false;
			}
		}

		private void OnPreRelease(Tool tool)
		{
			if (base.hasAuthority && AutomaticallyArmOnNextRelease)
			{
				AuthorityStartCooking();
			}
			AutomaticallyArmOnNextRelease = true;
		}

		private void OnPreAttach(Tool tool)
		{
			if (base.hasAuthority && lifetimeStateMachine.CurrentStateId == 1)
			{
				lifetimeStateMachine.EnterState(0);
			}
		}

		protected override void OnReset(Tool thisTool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasEnabled)
		{
			base.OnReset(thisTool, position, rotation, oldPosition, wasEnabled);
			CheckIfDestroyAfterDetonation();
			if (base.hasAuthority)
			{
				lifetimeStateMachine.EnterState(0);
			}
		}

		protected override void OnWielderChange()
		{
			base.OnWielderChange();
			if (base.TeamColor != null)
			{
				if (base.Wielder.IsValid)
				{
					base.TeamColor.RefreshOwnerTeam();
				}
				else
				{
					base.TeamColor.ClearOwnerTeam();
				}
			}
			if (base.Wielder.Enemy != null && base.hasAuthority)
			{
				AuthorityStartCooking();
			}
		}

		protected override void HitExplosive(Player hittingPlayer, Weapon hittingWeapon)
		{
			base.HitExplosive(hittingPlayer, hittingWeapon);
			if (hittingPlayer.isLocal && base.Tool.AllowedToTakeOwnership)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (base.hasAuthority)
			{
				base.Wielder = new Combatant(PhotonNetwork.player);
				AuthorityStartCooking(!(hittingWeapon is Grenade));
			}
		}

		public void AuthorityStartCooking(bool detonateImmediately = false)
		{
			if (base.hasAuthority && explosionAllowed)
			{
				LifetimeState currentStateId = (LifetimeState)lifetimeStateMachine.CurrentStateId;
				if (detonateImmediately && currentStateId != LifetimeState.DETONATED)
				{
					lifetimeStateMachine.EnterState(2);
				}
				else if (!detonateImmediately && currentStateId == LifetimeState.DISARMED)
				{
					lifetimeStateMachine.EnterState(1);
				}
			}
		}

		private void EnableBody(bool enabled)
		{
			if (visualRoot != null)
			{
				visualRoot.gameObject.SetActive(enabled);
			}
			if (!(base.Tool != null))
			{
				return;
			}
			if (base.Tool.RigidbodyEx != null)
			{
				if (!enabled)
				{
					base.Tool.RigidbodyEx.AddKinematic(this);
				}
				else
				{
					base.Tool.RigidbodyEx.RemoveKinematic(this);
				}
			}
			base.Tool.SupportsAnimateOut = enabled;
		}

		private void PlayExplosionFeedback()
		{
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(explosionParticlesPrefab);
			if (pooledParticle != null)
			{
				pooledParticle.SetColor(WeaponColor);
				pooledParticle.Play(base.transform.position, base.transform.rotation);
			}
			AudioManager.Play3DSFX(explodeAudio, base.transform.position);
		}

		private void StartArmedParticles()
		{
			StopArmedParticles();
			if (armedParticlesPrefab != null && armedParticlesTransform != null)
			{
				armedParticles = ObjectPool.Instance.Acquire(armedParticlesPrefab);
				armedParticles.SetColor(WeaponColor);
				armedParticles.Play(armedParticlesTransform, loop: true);
			}
		}

		private void StopArmedParticles()
		{
			if (armedParticles != null)
			{
				armedParticles.Stop();
				armedParticles = null;
			}
		}

		private void StartArmedLoopingAudio()
		{
			StopArmedLoopingAudio();
			armedAudioSource = AudioManager.StartLooping3DSFX(activeAudio, base.transform);
		}

		private void StopArmedLoopingAudio()
		{
			if (armedAudioSource != null)
			{
				armedAudioSource.Stop();
				armedAudioSource.Release();
				armedAudioSource = null;
			}
		}

		private void OnExplosivePlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			OnPlayerImpact(hitPlayer, hitBodyPart, impact);
		}

		private void OnExplosiveEnemyImpact(Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			if (!(base.Wielder.Enemy != null))
			{
				OnEnemyImpact(hitEnemy, EnemyArmorType.NORMAL, impact);
				if (hitEnemy.hasAuthority)
				{
					hitEnemy.AuthorityOnDamageApplyForce(WeaponDamageType.EXPLOSIVE, armorType, impact.Force, impact.Point);
				}
			}
		}

		private void OnExplosiveToolImpact(Tool hitTool, WeaponImpact impact)
		{
			OnToolImpact(hitTool, impact);
			if (base.hasAuthority && hitTool.hasAuthority)
			{
				hitTool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Impulse);
			}
		}

		private void OnExplosiveTrapImpact(Trap hitTrap, WeaponImpact impact)
		{
			OnTrapImpact(hitTrap, impact);
		}

		public override int GetPlayerImpactDamage(Player.BodyPart hitBodyPart, float preAttackChargeAmount, bool selfDamage)
		{
			return Mathf.RoundToInt((float)base.GetPlayerImpactDamage(hitBodyPart, preAttackChargeAmount, selfDamage) * Mathf.Clamp01(preAttackChargeAmount));
		}
	}
}
