	public override string RuleTypeAutoTag => "paintball";

	protected override void Awake()
	{
		base.Awake();
		GameManager.OnGameStartEvent += OnGameStart;
		GameManager.OnGameEndEvent += OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent += EnableLocalPlayerToolRestrictions;
		GameManager.OnPlayerOutOfBoundsEvent += MasterOnPlayerOutOfBounds;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		paintballOOBE = UnityEngine.Object.FindObjectOfType<PaintballOOBE>();
		paintballStateMachine = new SynchronizedStateMachine("PAINTBALL", SetterPermissionMode.MASTER);
		paintballStateMachine.AddState(ushort.MaxValue, null, null, null);
		paintballStateMachine.AddState(0, OnEnterCTFRoundRunningState, null, null);
		paintballStateMachine.AddState(1, OnEnterCTFFlagCapturedState, null, OnUpdateCTFFlagCapturedState);
		paintballStateMachine.AddState(2, null, null, OnUpdateTeamBattleRoundRunningState);
		paintballStateMachine.AddState(3, null, null, OnUpdateFreeForAllBattleRoundRunningState);
		paintballStateMachine.AddState(4, OnEnterTeamEliminationRoundRunningState, OnExitTeamEliminationRoundRunningState, OnUpdateTeamEliminationRoundRunningState);
		paintballStateMachine.AddState(5, OnEnterTeamEliminationRoundOverState, OnExitTeamEliminationRoundOverState, OnUpdateTeamEliminationRoundOverState);
		paintballStateMachine.AddState(6, OnEnterTeamEliminationBetweenRoundsState, OnExitTeamEliminationBetweenRoundsState, OnUpdateTeamEliminationBetweenRoundsState);
		masterPaintballStateTimer = new SynchronizedTimer(this, "PAINTBALL_TIMER", SetterPermissionMode.MASTER);
		List<Flag> list = this.FindAllObjectsOfType<Flag>();
		for (int i = 0; i < list.Count; i++)
		{
			Flag flag = list[i];
			flag.FlagAtGoalEvent = (Flag.FlagAtGoal)Delegate.Combine(flag.FlagAtGoalEvent, new Flag.FlagAtGoal(OnFlagAtGoal));
			Flag flag2 = list[i];
			flag2.FlagPickupEvent = (Flag.FlagPickup)Delegate.Combine(flag2.FlagPickupEvent, new Flag.FlagPickup(OnFlagPickup));
			Flag flag3 = list[i];
			flag3.FlagReleaseEvent = (Flag.FlagRelease)Delegate.Combine(flag3.FlagReleaseEvent, new Flag.FlagRelease(OnFlagRelease));
			Flag flag4 = list[i];
			flag4.FlagResetEvent = (Flag.FlagReset)Delegate.Combine(flag4.FlagResetEvent, new Flag.FlagReset(OnFlagReset));
			if (!flags.ContainsKey(list[i].Mode))
			{
				flags.Add(list[i].Mode, new List<Flag>());
			}
			flags[list[i].Mode].Add(list[i]);
			SpawnableTool component = list[i].GetComponent<SpawnableTool>();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.IgnoredSceneEquipment.Add(component);
		}
		List<FlagGoal> list2 = this.FindAllObjectsOfType<FlagGoal>();
		for (int j = 0; j < list.Count; j++)
		{
			if (!flagGoals.ContainsKey(list2[j].Mode))
			{
				flagGoals.Add(list2[j].Mode, new List<FlagGoal>());
			}
			flagGoals[list2[j].Mode].Add(list2[j]);
		}
		_lastScoringTeamEliminationTeam = new SynchronizedField<GameTeam>(this, "LAST_SCORING_TEAM_ELIM_TEAM", GameTeam.ANY, SetterPermissionMode.MASTER);
		_teamEliminationRoundCount = new SynchronizedField<int>(this, "TEAM_ELIM_ROUND_COUNT", 0, SetterPermissionMode.MASTER);
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilled;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent += OnPlayerRevived;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent += OnMiscKilledPlayer;
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void Start()
	{
		base.Start();
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Q2A_WelcomeToPaintball)
		{
			paintballOOBE.StartCoroutine(paintballOOBE.RunTutorial());
		}
		paintballStateMachine.Start(this, ushort.MaxValue);
		foreach (List<Flag> value in flags.Values)
		{
			foreach (Flag item in value)
			{
				item.Tool.AddCustomPickupCondition(CustomFlagPickupCondition);
				customPickupConditionTools.Add(item.Tool);
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		foreach (Tool customPickupConditionTool in customPickupConditionTools)
		{
			if (customPickupConditionTool != null)
			{
				customPickupConditionTool.RemoveCustomPickupCondition(CustomFlagPickupCondition);
			}
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilled;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent -= OnPlayerRevived;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent -= OnMiscKilledPlayer;
		}
		if (Player.LocalPlayer != null)
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.EnableLocalPlayerToolRestrictionEvent -= EnableLocalPlayerToolRestrictions;
		GameManager.OnPlayerOutOfBoundsEvent -= MasterOnPlayerOutOfBounds;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
	}

	protected void Update()
	{
		paintballStateMachine.Update();
		masterPaintballStateTimer.UpdateCallbacks();
	}

	protected void InitializeSceneOnPreGame()
	{
		DisableAllFlagsAndGoals();
	}

	protected void OnGameStart()
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.PresenceManager.CurrentPresenceString = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.Name + " - First to " + NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin + NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ScoreSettings.ScoreName + "s";
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = true;
		switch ((PaintballMode)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType)
		{
		case PaintballMode.MultiFlagCaptureTheFlag:
		case PaintballMode.OneFlagCaptureTheFlag:
			AudioManager.Play2DSFX(captureTheFlagTitleVO);
			if (PhotonNetwork.isMasterClient)
			{
				paintballStateMachine.EnterState(0);
			}
			break;
		case PaintballMode.TeamBattle:
			AudioManager.Play2DSFX(teamBattleTitleVO);
			if (PhotonNetwork.isMasterClient)
			{
				paintballStateMachine.EnterState(2);
			}
			break;
		case PaintballMode.FreeForAllBattle:
			if (PhotonNetwork.isMasterClient)
			{
				paintballStateMachine.EnterState(3);
			}
			break;
		case PaintballMode.TeamElimination:
			if (PhotonNetwork.isMasterClient)
			{
				TeamEliminationRoundCount = 0;
				paintballStateMachine.EnterState(4);
			}
			break;
		}
	}

	protected void OnGameEnd()
	{
		if (PhotonNetwork.isMasterClient)
		{
			paintballStateMachine.EnterState(ushort.MaxValue);
		}
	}

	protected int GetEloGameScore(PhotonPlayer photonPlayer)
	{
		int value = 0;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(photonPlayer, PlayerStatType.STAT_1, out value);
		return value;
	}

	public override void RecordMatchAnalytics(bool finishedGame)
	{
		int value = 0;
		int value2 = 0;
		int value3 = 0;
		bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_1, out value);
		bool flag2 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_3, out value2);
		bool flag3 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, PlayerStatType.STAT_2, out value3);
		if (flag || flag2 || flag3)
		{
			AnalyticsHelper.AddCustomStatsToActivityStats("finished_game", finishedGame.ToString());
			AnalyticsHelper.AddCustomStatsCounter("games_played", 1);
			AnalyticsHelper.AddCustomStatsCounter("player_kills", value);
			AnalyticsHelper.AddCustomStatsCounter("flag_captures", value2);
			AnalyticsHelper.AddCustomStatsCounter("deaths", value3);
			AnalyticsHelper.AddCustomStatsToActivityStats("player_type", SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType.ToString());
		}
	}

	private void OnPlayerKilled(PhotonPlayer shooter, PhotonPlayer hitPlayer, Weapon weapon, Player.BodyPart hitBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(hitPlayer, PlayerStatType.STAT_2, 1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(shooter, PlayerStatType.STAT_1, 1);
			if (paintballStateMachine.CurrentStateId == 2 || paintballStateMachine.CurrentStateId == 3)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(shooter), 1);
			}
		}
		if (hitPlayer.IsLocal)
		{
			PlayLocalPlayerOutFeedback(shooter);
		}
		else if (shooter.IsLocal)
		{
			PlayLocalPlayerHitFeedback(hitPlayer);
			Player.LocalPlayer.PlayerEvents.PaintballHit();
		}
		else
		{
			PlayRemotePlayerOutFeedback(hitPlayer);
		}
	}

	private void OnMiscKilledPlayer(PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddPlayerStat(defender, PlayerStatType.STAT_2, 1);
		}
		if (defender.IsLocal)
		{
			PlayLocalPlayerOutFeedback(null);
		}
	}

	private void PlayLocalPlayerOutFeedback(PhotonPlayer attacker)
	{
		AudioManager.Play2DSFX(playerOutSFX);
		if (paintballStateMachine.CurrentStateId == 4)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "You're Out!" + GetTeamEliminationTeamStatusString(PhotonNetwork.player), "High five a teammate to revive.", 3f);
		}
		else if (attacker != null)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "You're Out!", "Hit by " + attacker.NickName, 3f);
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "You're Out!", 3f);
		}
	}

	private void PlayLocalPlayerHitFeedback(PhotonPlayer hitPlayer)
	{
		AudioManager.Play2DSFX(playerHitSFX);
		Vector3 vector = 0.35f * Vector3.up;
		WorldSpaceNotification.PlayNext("Hit!", 3f, null, followPlayer: false, hitPlayer.ToPlayer().Head.transform.position + vector);
		if (paintballStateMachine.CurrentStateId == 4)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You Hit " + hitPlayer.NickName + GetTeamEliminationTeamStatusString(hitPlayer), 3f);
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You Hit " + hitPlayer.NickName, 3f);
		}
	}

	private void PlayRemotePlayerOutFeedback(PhotonPlayer hitPlayer)
	{
		if (paintballStateMachine.CurrentStateId == 4)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(hitPlayer, PhotonNetwork.player))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, hitPlayer.NickName + " is Out!" + GetTeamEliminationTeamStatusString(hitPlayer), "High five them to revive.", 3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, hitPlayer.NickName + " is Out!" + GetTeamEliminationTeamStatusString(hitPlayer), 3f);
			}
		}
	}

	private void OnFlagAtGoal(Flag flag, GameTeam goalTeam, Player capturePlayer)
	{
		if (capturePlayer.PhotonPlayer.IsLocal && IsValidFlagCapture(flag, goalTeam, capturePlayer.PhotonPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestFlagCapture, flag, goalTeam, capturePlayer.PhotonPlayer);
		}
	}

	private void OnFlagPickup(Flag flag, Player pickupPlayer)
	{
		if (pickupPlayer.PhotonPlayer.IsLocal)
		{
			if (IsValidFlagReturn(flag, pickupPlayer.PhotonPlayer))
			{
				flag.Tool.AuthorityResetToLastSpawnPosition();
				base.photonView.RpcMaster(RpcMasterRequestFlagReturn, flag, pickupPlayer.PhotonPlayer);
			}
			else if (IsValidFlagPickup(flag, pickupPlayer.PhotonPlayer))
			{
				base.photonView.RpcMaster(RpcMasterRequestFlagTaken, flag, pickupPlayer.PhotonPlayer);
			}
		}
	}

	private void OnFlagRelease(Flag flag, Player droppingPlayer)
	{
		if (droppingPlayer.PhotonPlayer.IsLocal && IsValidFlagDrop(flag, droppingPlayer.PhotonPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestFlagDrop, flag, droppingPlayer.PhotonPlayer);
		}
	}

	private void OnFlagReset(Flag flag)
	{
		if (PhotonNetwork.isMasterClient && IsValidFlagReturn(flag, null))
		{
			base.photonView.RpcMaster<Flag, PhotonPlayer>(RpcMasterRequestFlagReturn, flag, null);
		}
	}

	[PunRPC]
	private void RpcMasterRequestFlagCapture(Flag flag, GameTeam goalTeam, PhotonPlayer capturer)
	{
		if (PhotonNetwork.isMasterClient && flag != null && capturer != null && IsValidFlagCapture(flag, goalTeam, capturer))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddScore(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(capturer), 1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddPlayerStat(capturer, PlayerStatType.STAT_3, 1);
			paintballStateMachine.EnterState(1);
			base.photonView.RpcAll(RpcOnFlagCaptured, flag, capturer);
		}
	}

	[PunRPC]
	private void RpcMasterRequestFlagReturn(Flag flag, PhotonPlayer returner)
	{
		if (PhotonNetwork.isMasterClient && flag != null && IsValidFlagReturn(flag, returner))
		{
			base.photonView.RpcAll(RpcOnFlagReturn, flag, returner);
		}
	}

	[PunRPC]
	private void RpcMasterRequestFlagTaken(Flag flag, PhotonPlayer pickupPlayer)
	{
		if (PhotonNetwork.isMasterClient && flag != null && IsValidFlagPickup(flag, pickupPlayer))
		{
			base.photonView.RpcAll(RpcOnFlagTaken, flag, pickupPlayer);
		}
	}

	[PunRPC]
	private void RpcMasterRequestFlagDrop(Flag flag, PhotonPlayer dropper)
	{
		if (PhotonNetwork.isMasterClient && flag != null && IsValidFlagDrop(flag, dropper))
		{
			base.photonView.RpcAll(RpcOnFlagDrop, flag, dropper);
		}
	}

	[PunRPC]
	private void RpcOnFlagCaptured(Flag flag, PhotonPlayer capturingPlayer)
	{
		if (capturingPlayer != null)
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(capturingPlayer);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(playerTeam) + " Scores!", "Scored by " + capturingPlayer.NickName, 3f);
			switch (playerTeam)
			{
			case GameTeam.TEAM_1:
				AudioManager.Play2DSFX(flagCaptureSFX);
				AudioManager.Play2DSFX(blueTeamFlagCaptureVO);
				break;
			case GameTeam.TEAM_2:
				AudioManager.Play2DSFX(flagCaptureSFX);
				AudioManager.Play2DSFX(redTeamFlagCaptureVO);
				break;
			}
			if (capturingPlayer.IsLocal)
			{
				ChallengeEvents.FlagCaptured();
				Player.LocalPlayer.PlayerEvents.PaintballFlagCapture();
				PlayerGameRoleManager.Instance.RequestRemoveRole(capturingPlayer, flagCarrierGameRoleId);
				Player.LocalPlayer.PlayerWalking.RemoveMaxWalkSpeed(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportCooldown(this);
			}
		}
	}

	[PunRPC]
	private void RpcOnFlagTaken(Flag flag, PhotonPlayer flagCarrier)
	{
		if (flagCarrier != null && flagCarrier.IsLocal)
		{
			PlayerGameRoleManager.Instance.RequestAddRole(flagCarrier, flagCarrierGameRoleId);
			Player.LocalPlayer.PlayerWalking.AddMaxWalkSpeed(flagHolderCustomWalkSpeed, this, 500);
			Player.LocalPlayer.PlayerLocomotion.AddTeleportCooldown(flagHolderMovementCooldown, this, 500);
		}
		if (flag != null)
		{
			if (flag.Team == GameTeam.ANY)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Flag Taken!", 1.5f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(flag.Team) + " Flag Taken!", 1.5f);
			}
			if (flag.Team == GameTeam.TEAM_1 && UnityEngine.Time.time - lastTeam1FlagPickupAudioTime >= audioFXMinInterval)
			{
				lastTeam1FlagPickupAudioTime = UnityEngine.Time.time;
				AudioManager.Play2DSFX(flagPickupSFX);
				AudioManager.Play2DSFX(blueTeamFlagPickupVO);
			}
			else if (flag.Team == GameTeam.TEAM_2 && UnityEngine.Time.fixedTime - lastTeam2FlagPickupAudioTime >= audioFXMinInterval)
			{
				lastTeam2FlagPickupAudioTime = UnityEngine.Time.time;
				AudioManager.Play2DSFX(flagPickupSFX);
				AudioManager.Play2DSFX(redTeamFlagPickupVO);
			}
		}
	}

	[PunRPC]
	private void RpcOnFlagReturn(Flag flag, PhotonPlayer returningPlayer)
	{
		if (flag != null)
		{
			if (flag.Team == GameTeam.ANY)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Flag Returned", 1.5f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(flag.Team) + " Flag Returned", 1.5f);
			}
			if (flag.Team == GameTeam.TEAM_1)
			{
				AudioManager.Play2DSFX(flagReturnSFX);
				AudioManager.Play2DSFX(blueTeamFlagReturnVO);
			}
			else if (flag.Team == GameTeam.TEAM_2)
			{
				AudioManager.Play2DSFX(flagReturnSFX);
				AudioManager.Play2DSFX(redTeamFlagReturnVO);
			}
			if (returningPlayer != null && returningPlayer.IsLocal)
			{
				ChallengeEvents.FlagReturned();
			}
		}
	}

	[PunRPC]
	private void RpcOnFlagDrop(Flag flag, PhotonPlayer dropper)
	{
		if (dropper != null && dropper.IsLocal)
		{
			PlayerGameRoleManager.Instance.RequestRemoveRole(dropper, flagCarrierGameRoleId);
			Player.LocalPlayer.PlayerWalking.RemoveMaxWalkSpeed(this);
			Player.LocalPlayer.PlayerLocomotion.RemoveTeleportCooldown(this);
		}
		if (flag != null)
		{
			if (flag.Team == GameTeam.ANY)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Flag Dropped", 1.5f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(flag.Team) + " Flag Dropped", 1.5f);
			}
			if (flag.Team == GameTeam.TEAM_1 && UnityEngine.Time.time - lastTeam1FlagDropAudioTime >= audioFXMinInterval)
			{
				lastTeam1FlagDropAudioTime = UnityEngine.Time.time;
				AudioManager.Play2DSFX(flagDroppedSFX);
				AudioManager.Play2DSFX(blueTeamFlagDroppedVO);
			}
			else if (flag.Team == GameTeam.TEAM_2 && UnityEngine.Time.time - lastTeam2FlagDropAudioTime >= audioFXMinInterval)
			{
				lastTeam2FlagDropAudioTime = UnityEngine.Time.time;
				AudioManager.Play2DSFX(flagDroppedSFX);
				AudioManager.Play2DSFX(redTeamFlagDroppedVO);
			}
		}
	}

	private bool IsValidFlagCapture(Flag flag, GameTeam goalTeam, PhotonPlayer capturer)
	{
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(capturer);
		Flag teamFlag = GetTeamFlag(playerTeam);
		bool flag2 = !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(capturer) && paintballStateMachine.CurrentStateId == 0 && goalTeam == playerTeam && playerTeam != flag.Team;
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType == GameModeType.MODE_1)
		{
			flag2 &= teamFlag.AtHomeGoal;
		}
		return flag2;
	}

	private bool IsValidFlagDrop(Flag flag, PhotonPlayer droppingPlayer)
	{
		return !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(droppingPlayer) && paintballStateMachine.CurrentStateId == 0 && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(droppingPlayer) != flag.Team;
	}

	private bool IsValidFlagPickup(Flag flag, PhotonPlayer pickupPlayer)
	{
		return !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(pickupPlayer) && paintballStateMachine.CurrentStateId == 0 && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(pickupPlayer) != flag.Team;
	}

	private bool IsValidFlagReturn(Flag flag, PhotonPlayer returner)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType != GameModeType.MODE_1)
		{
			return false;
		}
		if (paintballStateMachine.CurrentStateId != 0)
		{
			return false;
		}
		if (returner != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(returner))
		{
			return false;
		}
		if (returner != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(returner) != flag.Team)
		{
			return false;
		}
		return true;
	}

	private Flag GetTeamFlag(GameTeam team)
	{
		Flag result = null;
		List<Flag> value = null;
		if (flags.TryGetValue(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType, out value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				if (value[i].Team == team)
				{
					result = value[i];
					break;
				}
			}
		}
		return result;
	}

	private void AuthorityResetAllCurrentModeFlagsAndGoals()
	{
		List<Flag> value = null;
		if (flags.TryGetValue(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType, out value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				if (!value[i].AtHomeGoal)
				{
					value[i].Tool.AuthorityResetToLastSpawnPosition();
				}
			}
		}
		List<FlagGoal> value2 = null;
		if (flagGoals.TryGetValue(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType, out value2))
		{
			for (int j = 0; j < value2.Count; j++)
			{
				value2[j].gameObject.SetActive(value: true);
			}
		}
	}

	private void DisableAllFlagsAndGoals()
	{
		if (PhotonNetwork.isMasterClient)
		{
			foreach (List<Flag> value in flags.Values)
			{
				foreach (Flag item in value)
				{
					item.Tool.Disable();
				}
			}
		}
		foreach (List<FlagGoal> value2 in flagGoals.Values)
		{
			foreach (FlagGoal item2 in value2)
			{
				item2.gameObject.SetActive(value: false);
			}
		}
	}

	private void OnEnterCTFRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Resume();
		}
		AuthorityResetAllCurrentModeFlagsAndGoals();
	}

	private void OnEnterCTFFlagCapturedState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
			masterPaintballStateTimer.StartTimer(3f);
		}
		AuthorityResetAllCurrentModeFlagsAndGoals();
	}

	private void OnUpdateCTFFlagCapturedState()
	{
		if (PhotonNetwork.isMasterClient && masterPaintballStateTimer.TimerOver)
		{
			GameTeam highestScoreTeam = GameTeam.ANY;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out highestScoreTeam, out var highestScore);
			if (highestScore >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
			else
			{
				paintballStateMachine.EnterState(0);
			}
		}
	}

	private void OnUpdateTeamBattleRoundRunningState()
	{
		GameTeam highestScoreTeam = GameTeam.ANY;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out highestScoreTeam, out var highestScore);
		if (PhotonNetwork.isMasterClient && highestScore >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
		}
	}

	private void OnUpdateFreeForAllBattleRoundRunningState()
	{
		GameTeam highestScoreTeam = GameTeam.ANY;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out highestScoreTeam, out var highestScore);
		if (PhotonNetwork.isMasterClient && highestScore >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
		}
	}

	private void OnEnterTeamEliminationRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.MasterStartTimer();
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = true;
		this.InvokeInUpdate(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration, PlayTeamEliminationRoundStartingNotification);
	}

	private void OnUpdateTeamEliminationRoundRunningState()
	{
		if (PhotonNetwork.isMasterClient && (NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimerOver || !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.AllActiveTeamsAreAlive))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
			paintballStateMachine.EnterState(5);
		}
	}

	private void OnExitTeamEliminationRoundRunningState(ushort nextStateId, ushort nextSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			TeamEliminationRoundCount++;
			int num = 0;
			GameTeam lastScoringTeamEliminationTeam = GameTeam.ANY;
			GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
			for (int i = 0; i < activeTeams.Length; i++)
			{
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.TeamIsAlive(activeTeams[i]))
				{
					num++;
					lastScoringTeamEliminationTeam = activeTeams[i];
				}
			}
			if (num > 1)
			{
				LastScoringTeamEliminationTeam = GameTeam.ANY;
			}
			else
			{
				LastScoringTeamEliminationTeam = lastScoringTeamEliminationTeam;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterAddScore(LastScoringTeamEliminationTeam, 1);
			}
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = false;
	}

	private void PlayTeamEliminationRoundStartingNotification()
	{
		string titleText = $"Round {TeamEliminationRoundCount + 1} Starting!";
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, 2.5f);
	}

	private void OnEnterTeamEliminationRoundOverState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterPaintballStateTimer.StartTimer(8f);
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = false;
		this.InvokeInUpdate(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration, PlayTeamEliminationRoundOverNotification);
	}

	private void OnUpdateTeamEliminationRoundOverState()
	{
		if (PhotonNetwork.isMasterClient && masterPaintballStateTimer.TimerOver)
		{
			GameTeam highestScoreTeam = GameTeam.ANY;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetHighestScore(out highestScoreTeam, out var highestScore);
			if (highestScore >= NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.ScoreToWin)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
			else
			{
				paintballStateMachine.EnterState(6);
			}
		}
	}

	private void OnExitTeamEliminationRoundOverState(ushort nextStateId, ushort nextSubStateId)
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = true;
	}

	private void PlayTeamEliminationRoundOverNotification()
	{
		string text = null;
		text = ((LastScoringTeamEliminationTeam != GameTeam.ANY) ? $"{NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(LastScoringTeamEliminationTeam)} Scores!" : "Tie Round");
		float duration = 8f - NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration - 1f;
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Round Over!", text, duration);
	}

	private void OnEnterTeamEliminationBetweenRoundsState(ushort previousStateId, ushort previousSubStateId)
	{
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
		}
		if (PhotonNetwork.isMasterClient)
		{
			foreach (PhotonPlayer activePlayer in NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers())
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterResetPlayerHealth(activePlayer);
			}
			masterPaintballStateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration);
		}
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = false;
		this.InvokeInUpdate(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RespawnDuration, PlayTeamEliminationRoundOverNotification);
	}

	private void OnUpdateTeamEliminationBetweenRoundsState()
	{
		if (PhotonNetwork.isMasterClient && masterPaintballStateTimer.TimerOver)
		{
			paintballStateMachine.EnterState(4);
		}
	}

	private void OnExitTeamEliminationBetweenRoundsState(ushort nextStateId, ushort nextSubStateId)
	{
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CombatEnabled = true;
	}

	private string GetTeamEliminationTeamStatusString(PhotonPlayer player)
	{
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player);
		int num = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.TeamPlayersAliveCount(playerTeam);
		int teamPlayerCount = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerCount(playerTeam);
		return $" [{NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(playerTeam)} - {num}/{teamPlayerCount}]";
	}

	private void OnPlayerRevived(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 position)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddPlayerStat(revivingPlayer, PlayerStatType.STAT_4, 1);
		}
		AudioManager.Play3DSFX(playerReviveSFX, position);
		if (revivedPlayer.IsLocal)
		{
			PlayLocalPlayerRevivedFeedback(revivingPlayer);
		}
		else if (revivingPlayer.IsLocal)
		{
			PlayLocalPlayerRevivingFeedback(revivedPlayer);
		}
		else
		{
			PlayRemotePlayerRevivedFeedback(revivedPlayer);
		}
	}

	private void PlayLocalPlayerRevivedFeedback(PhotonPlayer revivingPlayer)
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You've been Revived by " + revivingPlayer.NickName + "!", GetTeamEliminationTeamStatusString(PhotonNetwork.player), 2f);
	}

	private void PlayLocalPlayerRevivingFeedback(PhotonPlayer revivedPlayer)
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You Revived " + revivedPlayer.NickName + "!", GetTeamEliminationTeamStatusString(PhotonNetwork.player), 2f);
	}

	private void PlayRemotePlayerRevivedFeedback(PhotonPlayer revivedPlayer)
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, revivedPlayer.NickName + " Revived!" + GetTeamEliminationTeamStatusString(PhotonNetwork.player), 2f);
	}

	protected void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
	{
		List<Flag> value = null;
		if (flags.TryGetValue(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType, out value))
		{
			for (int i = 0; i < value.Count; i++)
			{
				value[i].Tool.SetPickupEnabled(pickupEnabled, this);
			}
		}
	}

	private bool CustomFlagPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		if (paintballStateMachine.CurrentStateId == 1)
		{
			return false;
		}
		Flag component = tool.GetComponent<Flag>();
		GameTeam gameTeam = ((!(component != null)) ? GameTeam.ANY : component.Team);
		GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(selectingPlayer.PhotonPlayer);
		if (gameTeam == playerTeam && component.AtHomeGoal)
		{
			return false;
		}
		if (playerTeam == GameTeam.ANY)
		{
			return false;
		}
		return true;
	}

	protected void MasterOnPlayerOutOfBounds(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient && IsValidOutOfBoundsHit(player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterKillPlayer(player);
			base.photonView.RpcPlayer(player, RpcOnOutOfBoundsHitPlayer);
		}
	}

	private bool IsValidOutOfBoundsHit(PhotonPlayer hitPlayer)
	{
		return paintballStateMachine.CurrentStateId != ushort.MaxValue && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(hitPlayer) && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(hitPlayer);
	}

	[PunRPC]
	private void RpcOnOutOfBoundsHitPlayer()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "You're Out!", "Out of Bounds!", 3f);
	}
}
public class PaintballOOBE : OOBEFlowBase
{
	private bool isWaitingOnGameToStart;

	private float waitingStartTime;

	private bool tutorialRunning;

	public IEnumerator RunTutorial()
	{
		if (tutorialRunning)
		{
			yield break;
		}
		tutorialRunning = true;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = true;
		float startTime = UnityEngine.Time.time;
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		WatchChallengesTeachableMoment challengesTutorial = SingletonMonoBehaviour<TutorialManager>.Instance.GetTeachableMoment<WatchChallengesTeachableMoment>();
		if (challengesTutorial != null)
		{
			challengesTutorial.Suppress = true;
		}
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2Paintball_ThisIsPaintball);
		yield return new WaitForSeconds(1f);
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.ReadyToPlay)
		{
			waitingStartTime = UnityEngine.Time.time;
			isWaitingOnGameToStart = true;
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2Paintball_WhileYouWait);
			float timeSinceLastPrompt = 0f;
			float longWaitTime = 120f;
			while (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.ReadyToPlay)
			{
				yield return null;
				timeSinceLastPrompt += UnityEngine.Time.deltaTime;
				if (timeSinceLastPrompt > longWaitTime)
				{
					if (SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
					{
						yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.SCREENS_IfYoudPreferNotToWait);
					}
					else
					{
						yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_IfYouDontWantToWait);
					}
					timeSinceLastPrompt = 0f;
				}
			}
		}
		while (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(2f);
		switch ((PaintballManager.PaintballMode)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType)
		{
		case PaintballManager.PaintballMode.MultiFlagCaptureTheFlag:
		case PaintballManager.PaintballMode.OneFlagCaptureTheFlag:
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2Paintball_WelcomeCaptureTheFlag);
			break;
		case PaintballManager.PaintballMode.TeamBattle:
		case PaintballManager.PaintballMode.FreeForAllBattle:
		case PaintballManager.PaintballMode.TeamElimination:
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2Paintball_WelcomeTeamBattle);
			break;
		default:
			UnityEngine.Debug.LogWarning("Unrecognized PaintballMode in PaintballOOBE: " + (PaintballManager.PaintballMode)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.ModeType);
			break;
		}
		isWaitingOnGameToStart = false;
		float endTime = UnityEngine.Time.time;
		AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToPaintball, endTime - startTime, InterruptableFlow.FlowState.Complete);
		startTime = UnityEngine.Time.time;
		while (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2A_CongratulationsOnFirstGame);
		yield return new WaitForSeconds(1f);
		while (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState != GameStates.POST_GAME || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentPostGameState != PostGameSubStates.RESULTS)
		{
			yield return null;
		}
		yield return new WaitForSeconds(4f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2Paintball_WhatsNext);
		endTime = UnityEngine.Time.time;
		AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_FinishedFirstGame, endTime - startTime, InterruptableFlow.FlowState.Complete);
		SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
		if (challengesTutorial != null)
		{
			challengesTutorial.Suppress = false;
		}
		SingletonMonoBehaviour<TutorialManager>.Instance.ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
		while (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
		{
			yield return null;
		}
		SingletonMonoBehaviour<TutorialManager>.Instance.HideHelpPopup();
		tutorialRunning = false;
	}

	protected override void OnDestroy()
	{
		if (isWaitingOnGameToStart && SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance != null)
		{
			AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToPaintball, UnityEngine.Time.time - waitingStartTime, InterruptableFlow.FlowState.Incomplete);
		}
		if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
		}
		base.OnDestroy();
	}
}
