public class SniperScope : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Renderer scopeRenderer;

	[SerializeField]
	private Camera scopeCamera;

	[SerializeField]
	private float fov = 5f;

	[SerializeField]
	private int resolution = 256;

	private RenderTexture renderTexture;

	private Tool tool;

	private bool RenderingEnabled
	{
		set
		{
			if (scopeCamera != null)
			{
				scopeCamera.enabled = value;
			}
			if (tool != null)
			{
				Layers renderLayer = ((!value) ? Layers.DynamicPhysics : Layers.CameraMesh);
				tool.SetRenderLayer(renderLayer);
			}
		}
	}

	private void Awake()
	{
		renderTexture = new RenderTexture(resolution, resolution, 24);
		if (scopeCamera == null || scopeRenderer == null)
		{
			UnityEngine.Debug.LogError("SniperScope: Missing camera or renderer.");
			return;
		}
		scopeCamera.fieldOfView = fov;
		scopeCamera.targetTexture = renderTexture;
		scopeRenderer.material.mainTexture = renderTexture;
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PostPickupEvent += OnToolPickup;
			tool.PostReleaseEvent += OnToolRelease;
		}
	}

	private void Start()
	{
		RenderingEnabled = tool == null;
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.PostPickupEvent -= OnToolPickup;
			tool.PostReleaseEvent -= OnToolRelease;
		}
	}

	private void OnToolPickup(Tool tool)
	{
		if (tool.Owner.isLocal)
		{
			RenderingEnabled = true;
		}
	}

	private void OnToolRelease(Tool tool)
	{
		RenderingEnabled = false;
	}
}
