	{
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
