	}
}
public class AutoHeightAdjust : UnityEngine.MonoBehaviour
{
	public Transform transformToMove;

	public AnimationCurve curve;

	public float animationDuration = 1f;

	public float idealDistance = 0.6f;

	public float acceptableError = 0.1f;

	private bool isAnimating;

	private float targetY;

	private float animationStartTime;

	private float animationStartY;

	private void Awake()
	{
		targetY = transformToMove.position.y;
	}

	private void Update()
	{
		float y = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position.y;
		float num = y - targetY;
		if (Mathf.Abs(num - idealDistance) > acceptableError)
		{
			SetTarget(y - idealDistance);
		}
		if (isAnimating)
		{
			float num2 = UnityEngine.Time.time - animationStartTime;
			if (num2 >= animationDuration)
			{
				UpdateHeight(targetY);
				isAnimating = false;
			}
			else
			{
				float t = curve.Evaluate(num2 / animationDuration);
				float newHeight = Mathf.Lerp(animationStartY, targetY, t);
				UpdateHeight(newHeight);
			}
		}
	}

	private void SetTarget(float newTargetY)
	{
		targetY = newTargetY;
		isAnimating = true;
		animationStartTime = UnityEngine.Time.time;
		animationStartY = transformToMove.position.y;
	}

	private void UpdateHeight(float newHeight)
	{
		Vector3 position = transformToMove.position;
		position.y = newHeight;
		transformToMove.position = position;
	}
}
public class AutoReposition : UnityEngine.MonoBehaviour
{
	public delegate bool ShouldRun();

	public float acceptableDistance_meters = 1.5f;

	public float acceptableLookAwayAngle_degrees = 60f;

	public float timeBeforeResetForDistance = 0.5f;

	public float timeBeforeResetForAngle = 2f;

	public Transform transformToMonitor;

	[SerializeField]
	private bool useDefaultPositioning = true;

	[SerializeField]
	[FormerlySerializedAs("defaultDistFromCamera")]
	private float defaultDistFromVRCamera = 0.75f;

	[SerializeField]
	private float defaultDistFromScreenCamera = 1.25f;

	[SerializeField]
	private float defaultHeightOffset = -0.1f;

	public IEnumerator OnResetRequired;

	public ShouldRun CustomShouldRunLogic;

	private float timeOutsideDistance;

	private float timeOutsideAngle;

	private bool isInReset;

	private void Update()
	{
		bool flag = true;
		if (!isInReset && CustomShouldRunLogic != null)
		{
			flag = CustomShouldRunLogic();
		}
		if (isInReset || !flag)
		{
			timeOutsideDistance = 0f;
			timeOutsideAngle = 0f;
			return;
		}
		if (IsOutsideIdealDistance())
		{
			timeOutsideDistance += UnityEngine.Time.deltaTime;
		}
		if (IsOutsideIdealAngle())
		{
			timeOutsideAngle += UnityEngine.Time.deltaTime;
		}
		if (timeOutsideDistance > timeBeforeResetForDistance || timeOutsideAngle > timeBeforeResetForAngle)
		{
			ResetMenu();
		}
	}

	public void ResetMenu()
	{
		if (!isInReset)
		{
			StartCoroutine(ResetMenuRoutine());
		}
	}

	private IEnumerator ResetMenuRoutine()
	{
		isInReset = true;
		timeOutsideDistance = 0f;
		timeOutsideAngle = 0f;
		if (OnResetRequired != null)
		{
			yield return OnResetRequired;
		}
		if (useDefaultPositioning)
		{
			Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform;
			Vector3 forward = transform.forward;
			forward.y = 0f;
			forward.Normalize();
			float num = ((!SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode) ? defaultDistFromVRCamera : defaultDistFromScreenCamera);
			Vector3 position = transform.position + forward * num;
			position.y = transform.position.y + defaultHeightOffset;
			transformToMonitor.position = position;
			transformToMonitor.rotation = Quaternion.LookRotation(forward);
		}
		isInReset = false;
	}

	private bool IsOutsideIdealDistance()
	{
		float sqrMagnitude = (transformToMonitor.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position).sqrMagnitude;
		return sqrMagnitude > acceptableDistance_meters * acceptableDistance_meters;
	}

	private bool IsOutsideIdealAngle()
	{
		Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
		forward.y = 0f;
		forward.Normalize();
		Vector3 rhs = transformToMonitor.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
		rhs.y = 0f;
		rhs.Normalize();
		float f = Mathf.Acos(Vector3.Dot(forward, rhs));
		float num = (float)Math.PI / 180f * acceptableLookAwayAngle_degrees;
		return Mathf.Abs(f) > num;
	}
}
