	public class FakePlayerHand : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private LineRenderer menuLaser;

		[SerializeField]
		private Transform menuHandVisibleLaserStartPosition;

		[SerializeField]
		private AnimationCurve MenuLaserDistanceAlpha = AnimationCurve.Linear(0f, 0f, 0.25f, 1f);

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private MenuFinger menuFinger;

		private const float MENU_LASER_ALPHA = 0.85f;

		public MenuFinger MenuFinger => menuFinger;

		public bool IsLaserActive => menuLaser.enabled;

		public void UpdateMenuLaser(Vector3 menuTargetPosition, bool clickPressed, bool uiSelected)
		{
			menuLaser.enabled = true;
			Vector3 normalized = (menuTargetPosition - menuHandVisibleLaserStartPosition.position).normalized;
			menuLaser.SetPosition(0, menuHandVisibleLaserStartPosition.position);
			menuLaser.SetPosition(1, menuTargetPosition - normalized * menuLaser.widthMultiplier / 2f);
			Color black = Color.black;
			menuLaser.startColor = black;
			Color endColor = Color.white * GetMenuLaserAlpha(menuTargetPosition, clickPressed, uiSelected);
			menuLaser.endColor = endColor;
		}

		public void DisableMenuLaser()
		{
			menuLaser.enabled = false;
		}

		private float GetMenuLaserAlpha(Vector3 menuTargetPosition, bool clickPressed, bool uiSelected)
		{
			float num = 0.85f;
			if (!clickPressed)
			{
				float time = Vector3.Distance(menuHandVisibleLaserStartPosition.position, menuTargetPosition);
				num *= MenuLaserDistanceAlpha.Evaluate(time);
				if (!uiSelected)
				{
					num *= 0.1f;
				}
			}
			return num;
		}
	}
