	public void SetPositionRotationToDefault()
	{
		Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
		forward.y = 0f;
		forward.Normalize();
		Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position + forward * 0.75f;
		position.y = Mathf.Clamp(SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position.y - 0.1f, 1f, 3f);
		base.transform.position = position;
		base.transform.rotation = Quaternion.LookRotation(forward);
	}

