	public void UpdateStatus(string status, bool enableButtons)
	{
		if (ProfileSelectionFlow != null)
		{
			ProfileSelectionFlow.SetInfoText(status, enableButtons);
		}
	}

	public IEnumerator WaitForLogIn()
	{
		if (StackedUI == null)
		{
			InitializeAndOpenMenu();
		}
		UpdateStatus("Downloading profiles...", enableButtons: false);
		yield return RecNet.Login.DownloadCachedLoginProfiles(delegate(string e, List<Profile> result)
		{
			error = e;
			cachedProfiles = result;
		});
		if (!string.IsNullOrEmpty(error))
		{
			UpdateStatus(error, enableButtons: false);
			yield break;
		}
		ProfileSelectionFlow.UpdateGridWithProfiles();
		UpdateStatus(string.Empty, enableButtons: true);
		StackedUI.GetFlowByType<UIRegistrationDialog>().SetUpFlow();
		string profileArg = PUNNetworkManager.CheckCommandLineArgsFor("+profile:");
		if (!string.IsNullOrEmpty(profileArg))
		{
			Profile profile = cachedProfiles.FirstOrDefault((Profile p) => p.Username.GetDecrypted().Equals(profileArg, StringComparison.InvariantCultureIgnoreCase));
			if (profile != null)
			{
				LoginToCachedProfile(profile);
			}
		}
		while (!hasSelectedProfile)
		{
			yield return null;
		}
		yield return PlayerReporting.GetModerationBlockDetails(delegate(string e)
		{
			error = e;
		});
		if (string.IsNullOrEmpty(error))
		{
			StackedUI.PopAllFlows();
			UpdateStatus(error, enableButtons: false);
		}
		if (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.PlayStation && PlayerPrefs.GetInt(SettingsManager.PLAYSTATION_ONLY_MATCHING_PREF, 0) == 1)
		{
			bool canContinue = false;
			StackedUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Warning!", "You have settings that are separating you from 99% of Rec Room players :( To rejoin the Rec Room community select 'Primary Server'. To stay on the locked server select 'Locked Server'.", "Primary Server", "Locked Server").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					StackedUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.LOCKED, "Success!", "Please quit and restart Rec Room for this change to take effect.");
					LogPS4MatchingChangedEvent();
					PlayerPrefs.SetInt(SettingsManager.PLAYSTATION_ONLY_MATCHING_PREF, 0);
					PlayerPrefs.Save();
				}
				else
				{
					canContinue = true;
				}
			});
			yield return new WaitUntil(() => canContinue);
		}
		RunModeSelection();
		while (!hasSelectedMode)
		{
			yield return null;
		}
		if (0 == 0)
		{
			RunMicrophoneReminderFlow();
			while (!hasDismissedMicrophoneReminder && NeedsToConnectMicrophone())
			{
				yield return null;
			}
		}
		Menu.CloseMenu();
		yield return null;
	}

	private IEnumerator ReturnToProfileSelect()
	{
		Menu.CloseMenu();
		yield return new WaitForSeconds(1f);
		ProfileSelectionFlow.UpdateGridWithProfiles();
		UpdateStatus(string.Empty, enableButtons: true);
		StackedUI.PopAllFlows();
		StackedUI.PushFlow(ProfileSelectionFlow);
		recRoomLogo.SetActive(value: true);
		SetPositionRotationToDefault();
		Menu.OpenMenu();
	}

	public void Login()
	{
		ProfileSelectionFlow.SetInfoText(string.Empty, enableButtons: true);
		if (loginCoroutine != null)
		{
			StopCoroutine(loginCoroutine);
		}
		loginCoroutine = StartCoroutine(RunLogin());
	}

	private IEnumerator RunLogin()
	{
		waitingForLogin = true;
		autoReposition.ResetMenu();
		StackedUI.ShowLoginDialog();
		StackedUI.CurrentFlow.FlowExited += OnLoginFlowExited;
		Menu.ShowKeyboard();
		while (waitingForLogin)
		{
			UILoginDialog.OnLoginSubmitted = (Action<string, string, bool>)Delegate.Combine(UILoginDialog.OnLoginSubmitted, new Action<string, string, bool>(OnLoginSubmitted));
			while (waitingForLogin)
			{
				yield return null;
			}
			StackedUI.LoginDialog.SetInfoText("Logging in...", enableButtons: false);
			yield return RecNet.Login.LoginToProfile(username, password, rememberMe, delegate(string e)
			{
				if (!string.IsNullOrEmpty(e))
				{
					StackedUI.LoginDialog.SetInfoText(e, enableButtons: true);
					waitingForLogin = true;
				}
			});
		}
		yield return WaitForExistingAccountBirthdayAndEmail();
	}

	private void OnLoginFlowExited()
	{
		StackedUI.CurrentFlow.FlowExited -= OnLoginFlowExited;
		UILoginDialog.OnLoginSubmitted = (Action<string, string, bool>)Delegate.Remove(UILoginDialog.OnLoginSubmitted, new Action<string, string, bool>(OnLoginSubmitted));
		if (loginCoroutine != null)
		{
			StopCoroutine(loginCoroutine);
			loginCoroutine = null;
		}
		waitingForLogin = false;
	}

	public void SelectScreenPlayerMode()
	{
		SingletonMonoBehaviour<LocalPlayerController>.Instance.SetScreenDisplayMode();
		hasSelectedMode = true;
	}

	public void SelectVRPlayerMode()
	{
		SingletonMonoBehaviour<LocalPlayerController>.Instance.SetVRDisplayMode();
		hasSelectedMode = true;
	}

	private void RunModeSelection()
	{
		hasSelectedMode = false;
		if (!SingletonMonoBehaviour<LocalPlayerController>.Instance.CanDynamicallySwitchDisplayMode)
		{
			hasSelectedMode = true;
		}
		else if (SingletonMonoBehaviour<VRDeviceManager>.Instance == null || !SingletonMonoBehaviour<VRDeviceManager>.Instance.HMDExists)
		{
			SelectScreenPlayerMode();
		}
		else if (SingletonMonoBehaviour<VRDeviceManager>.Instance != null && SingletonMonoBehaviour<VRDeviceManager>.Instance.UserInHMD)
		{
			SelectVRPlayerMode();
		}
		else if (!hasSelectedMode)
		{
			StackedUI.PushFlow(PlayerModeSelectionFlow);
		}
	}

	public void DismissMicrophoneReminder()
	{
		hasDismissedMicrophoneReminder = true;
	}

	private void RunMicrophoneReminderFlow()
	{
		hasDismissedMicrophoneReminder = false;
		if (!NeedsToConnectMicrophone())
		{
			hasDismissedMicrophoneReminder = true;
		}
		else
		{
			StackedUI.PushFlow(MicrophoneReminderFlow);
		}
	}

	private bool NeedsToConnectMicrophone()
	{
		return SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode && !AudioManager.HasMicrophoneInput && !Profiles.LocalProfile.IsJunior();
	}

	private void OnLoginSubmitted(string username, string password, bool rememberMe)
	{
		UILoginDialog.OnLoginSubmitted = (Action<string, string, bool>)Delegate.Remove(UILoginDialog.OnLoginSubmitted, new Action<string, string, bool>(OnLoginSubmitted));
		this.username = username;
		this.password = password;
		this.rememberMe = rememberMe;
		waitingForLogin = false;
	}

	public void LoginToCachedProfile(Profile profile)
	{
		ProfileSelectionFlow.SetInfoText("Logging in...", enableButtons: false);
		StartCoroutine(RunLoginToCachedProfile(profile));
