	private IEnumerator RunLoginToCachedProfile(Profile profile)
	{
		if (hasReturnedToProfileSelect)
		{
			LogRegistrationEvent("selectedExistingProfile");
		}
		string error = null;
		yield return RecNet.Login.LoginToCachedProfile(profile.Id, delegate(string e)
		{
			error = e;
		});
		if (string.IsNullOrEmpty(error))
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Account selected", $"{profile.DisplayName}", 3f);
			yield return WaitForExistingAccountBirthdayAndEmail();
		}
		else
		{
			ProfileSelectionFlow.SetInfoText(error, enableButtons: true);
		}
	}

