	private IEnumerator ShowTypingHintAfterDelayWithNoInput(float timeToWait, int inputsRequiredToSkipHint)
	{
		float timeWithoutInput = 0f;
		int numInputsReceived = 0;
		AGVirtualKeyboard keyboard = Menu.Keyboard;
		keyboard.OnAnyKeyPressed = (Action)Delegate.Combine(keyboard.OnAnyKeyPressed, (Action)delegate
		{
			numInputsReceived++;
		});
		while (timeWithoutInput < timeToWait && numInputsReceived < inputsRequiredToSkipHint)
		{
			timeWithoutInput += UnityEngine.Time.deltaTime;
			yield return null;
		}
		if (numInputsReceived < inputsRequiredToSkipHint)
		{
			typingHint.parent = Menu.Keyboard.transform;
			typingHint.localPosition = typingHintOffsetFromKeyboard;
			typingHint.localRotation = Quaternion.identity;
			typingHint.gameObject.SetActive(value: true);
			PlayVO(TutorialManager.TutorialAudioType.UseYourFingersToPushButtons);
			LogRegistrationEvent("pressToTypeHelp");
			while (numInputsReceived < inputsRequiredToSkipHint)
			{
				yield return null;
			}
			typingHint.gameObject.SetActive(value: false);
		}
		Menu.Keyboard.OnAnyKeyPressed = null;
	}

	private void QueueRegistrationEventForPostLogIn(string step, string subStep = null)
	{
		List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
		list.Add(new KeyValuePair<string, string>("step", step));
		if (subStep != null)
		{
			list.Add(new KeyValuePair<string, string>("substep", subStep));
		}
		AnalyticsHelper.QueueEventForPostLogin("email_verification_flow", list);
	}

	private void LogPS4MatchingChangedEvent()
	{
		AmplitudeAnalyticsEventBuilder eventToLog = AmplitudeAnalyticsClient.ProfileSelectionPostLoginEvent("update_ps_only_matching_pref", RecNet.Core.LocalProfileId.ToString()).WithProperty("psOnlyMatching", value: true).WithUserProperty("psOnlyMatching", value: true);
		StartCoroutine(SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.LogOutOfSessionEvent(eventToLog));
	}

	private void LogRegistrationEvent(string step, string substep = null)
	{
		AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.OutOfSessionEvent("registration_flow").WithProperty("step", step);
		if (substep != null)
		{
			amplitudeAnalyticsEventBuilder = amplitudeAnalyticsEventBuilder.WithProperty("substep", substep);
		}
		StartCoroutine(SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.LogOutOfSessionEvent(amplitudeAnalyticsEventBuilder));
	}

	private void LogRegistrationEventWithDetail(string step, string detailField, string detailValue)
	{
		AmplitudeAnalyticsEventBuilder eventToLog = SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.OutOfSessionEvent("registration_flow").WithProperty("step", step).WithProperty(detailField, detailValue);
		StartCoroutine(SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.LogOutOfSessionEvent(eventToLog));
	}

	private IEnumerator RunCreateNewAccount()
	{
		LogRegistrationEventWithDetail("createAccountStarted", "numAccounts", cachedProfiles.Count.ToString());
		yield return ShowVideoAndImages();
		LogRegistrationEvent("videoWatched");
		waitingForBirthday = true;
		waitingForEmail = true;
		autoReposition.ResetMenu();
		bool affirmedAccountCreation = false;
		bool backToProfileSelected = false;
		StackedUI.ShowStartAccountDialog().Then(delegate(ConfirmDialogResponses response)
		{
			affirmedAccountCreation = response == ConfirmDialogResponses.Affirmative;
			backToProfileSelected = response == ConfirmDialogResponses.Cancel;
		});
		yield return new WaitUntil(() => affirmedAccountCreation || backToProfileSelected);
		if (backToProfileSelected)
		{
			hasReturnedToProfileSelect = true;
			LogRegistrationEvent("returnedToProfileSelect");
			HideVideoAndImages();
			yield return ReturnToProfileSelect();
			yield break;
		}
		LogRegistrationEvent("affirmAccountCreate");
		while (!hasSelectedProfile)
		{
			if (waitingForBirthday)
			{
				if (activeBirthdayFlow != null)
				{
					StackedUI.PushFlow(activeBirthdayFlow);
				}
				else
				{
					StackedUI.ShowBirthdayDialog("Account Creation: Step 1 of 3", OnValidBirthday);
					activeBirthdayFlow = StackedUI.CurrentFlow as UIBirthdayDialog;
				}
				Menu.ShowKeyboard();
				PlayVO(TutorialManager.TutorialAudioType.FirstEnterYourBirthday);
				if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR)
				{
					StartCoroutine(ShowTypingHintAfterDelayWithNoInput(7f, 2));
				}
				while (waitingForBirthday)
				{
					if (StackedUI.CurrentFlow as UIStartAccountCreationDialog != null)
					{
						waitingForBirthday = true;
						hasReturnedToProfileSelect = true;
						LogRegistrationEvent("returnedToProfileSelect");
						HideVideoAndImages();
						yield return ReturnToProfileSelect();
						yield break;
					}
					yield return null;
				}
				activeBirthdayFlow = null;
				LogRegistrationEventWithDetail("birthdayEntered", "isJunior", isJunior.ToString());
			}
			if (!waitingForEmail)
			{
				continue;
			}
			StackedUI.ShowRegistrationDialog(fromReminder: false, isJunior, "Account Creation: Step 2 of 3");
			PlayVO((!isJunior) ? TutorialManager.TutorialAudioType.NextWeNeedEmail : TutorialManager.TutorialAudioType.RegisterJunior);
			UIRegistrationDialog.OnValidEmailEntered = (Action<string>)Delegate.Combine(UIRegistrationDialog.OnValidEmailEntered, new Action<string>(OnValidEmailEntered));
			UIRegistrationDialog.OnPrivacyPolicySelected = (Action)Delegate.Combine(UIRegistrationDialog.OnPrivacyPolicySelected, new Action(OnPrivacyPolicySelected));
			UIRegistrationDialog.OnWhyRegisterSelected = (Action)Delegate.Combine(UIRegistrationDialog.OnWhyRegisterSelected, new Action(OnWhyRegisterSelected));
			while (waitingForEmail)
			{
				yield return null;
			}
			UIRegistrationDialog.OnPrivacyPolicySelected = (Action)Delegate.Remove(UIRegistrationDialog.OnPrivacyPolicySelected, new Action(OnPrivacyPolicySelected));
			UIRegistrationDialog.OnWhyRegisterSelected = (Action)Delegate.Remove(UIRegistrationDialog.OnWhyRegisterSelected, new Action(OnWhyRegisterSelected));
			if (email != null)
			{
				LogRegistrationEvent("emailStep", "submitted");
			}
			else
			{
				LogRegistrationEvent("emailStep", "skipped");
			}
			if (!hasAcceptedCoC)
			{
				yield return WaitForCoCAcknoledgement();
				LogRegistrationEvent("codeOfConductAgreed");
			}
			bool confirmed = false;
			StackedUI.ShowAccountStatusDialog(UIAccountStatusDialog.Status.Creating).Then((Action)delegate
			{
				confirmed = true;
			});
			bool successfullyCreated = false;
			yield return RecNet.Login.CreateAccount(birthday, email, delegate(string error)
			{
				successfullyCreated = string.IsNullOrEmpty(error);
				if (successfullyCreated)
				{
					StackedUI.AccountStatusDialog.UpdateUIState(UIAccountStatusDialog.Status.CreateSuccess);
					LogRegistrationEvent("accountCreated");
				}
				else
				{
					StackedUI.AccountStatusDialog.UpdateUIState(UIAccountStatusDialog.Status.CreateFail, error);
					LogRegistrationEvent("failedAccountCreation");
				}
			});
			yield return new WaitUntil(() => confirmed);
			if (successfullyCreated)
			{
				hasSelectedProfile = true;
			}
			else if (!successfullyCreated)
			{
				StackedUI.PopFlow();
				waitingForEmail = true;
				Menu.ShowKeyboard();
			}
		}
	}

	private IEnumerator RunShowScreensModeAccountCreationDialog()
	{
		bool affirmedBetaSignup = false;
		bool backToProfileSelected = false;
		StackedUI.ShowScreensModeAccountDialog().Then(delegate(ConfirmDialogResponses response)
		{
			affirmedBetaSignup = response == ConfirmDialogResponses.Affirmative;
			backToProfileSelected = response == ConfirmDialogResponses.Cancel;
		});
		yield return new WaitUntil(() => affirmedBetaSignup || backToProfileSelected);
		if (affirmedBetaSignup)
		{
			WebBrowser.ShowScreensBetaRegistrationWebPage();
		}
		StackedUI.PopFlow();
	}

