	private IEnumerator WaitForCoCAcknoledgement()
	{
		Menu.CloseMenu();
		codeOfConductPoster.SetActive(value: true);
		AutoReposition positioner = codeOfConductPoster.GetComponent<AutoReposition>();
		if (positioner != null)
		{
			positioner.ResetMenu();
		}
		codeOfConductButton.SetActive(value: false);
		PlayVO(TutorialManager.TutorialAudioType.ReadCodeOfConduct);
		yield return new WaitForSeconds(10f);
		ChargePhysicalButton agreeButton = codeOfConductButton.GetComponentInChildren<ChargePhysicalButton>();
		agreeButton.ChargedEvent += delegate
		{
			hasAcceptedCoC = true;
		};
		codeOfConductButton.SetActive(value: true);
		PlayVO(TutorialManager.TutorialAudioType.AgreeToCodeOfConduct);
		while (!hasAcceptedCoC)
		{
			yield return null;
		}
		codeOfConductPoster.SetActive(value: false);
		codeOfConductButton.SetActive(value: false);
		SetPositionRotationToDefault();
		Menu.OpenMenu();
	}

	private IEnumerator WaitForExistingAccountBirthdayAndEmail()
	{
		waitingForBirthday = !Profiles.LocalProfile.HasBirthday;
		waitingForEmail = Profiles.LocalProfile.RegistrationStatus == RegistrationStatus.Unregistered;
		if (!waitingForBirthday && (bool)Profiles.LocalProfile.PendingJunior)
		{
			Menu.HideKeyboard();
			yield return StackedUI.ShowAccountStatusDialog(UIAccountStatusDialog.Status.PendingJunior);
		}
		if (waitingForBirthday)
		{
			yield return WaitForBirthday();
		}
		else
		{
			isJunior = Profiles.LocalProfile.JuniorProfile;
		}
		if (waitingForEmail || !Profiles.LocalProfile.Verified)
		{
			yield return WaitForEmailVerification();
		}
		Menu.HideKeyboard();
		hasSelectedProfile = true;
	}

	private void HideVideoAndImages()
	{
		projector.SetActive(value: false);
		videoPlayer.StopVideo();
		if (posters == null)
		{
			return;
		}
		for (int i = 0; i < posters.Length; i++)
		{
			GameObject objectToShow = posters[i].ObjectToShow;
			if (objectToShow != null)
			{
				objectToShow.SetActive(value: false);
			}
		}
	}

	private IEnumerator ShowVideoAndImages()
	{
		yield return new WaitForSeconds(0.5f);
		Menu.CloseMenu();
		yield return new WaitForSeconds(0.5f);
		recRoomLogo.SetActive(value: false);
		FadeOutMusic();
		yield return new WaitForSeconds(0.5f);
		if (!hasWatchedVideo)
		{
			projector.SetActive(value: true);
			videoPlayer.PlayVideo();
			yield return new WaitForSeconds(0.5f);
			while (videoPlayer.IsVideoPlaying)
			{
				yield return null;
			}
			yield return new WaitForSeconds(0.25f);
			projector.SetActive(value: false);
			hasWatchedVideo = true;
		}
		if (posters != null)
		{
			for (int i = 0; i < posters.Length; i++)
			{
				if (i > 0)
				{
					yield return new WaitForSeconds(waitTimeBetweenPosters);
				}
				GameObject objectToShow = posters[i].ObjectToShow;
				AudioClip audio = posters[i].AudioToPlay;
				Vector3 audioLocation = Vector3.zero;
				if (objectToShow != null)
				{
					objectToShow.SetActive(value: true);
					audioLocation = objectToShow.transform.position;
				}
				if (audio != null)
				{
					AudioManager.Play2DSFX(audio, audioLocation);
				}
			}
		}
		FadeInMusic(3f);
	}

	private IEnumerator WaitForBirthday()
	{
		StackedUI.ShowBirthdayDialog(null, OnValidBirthday);
		Menu.ShowKeyboard();
		PlayVO(TutorialManager.TutorialAudioType.PleaseEnterYourBirthday);
		while (waitingForBirthday)
		{
			while (waitingForBirthday)
			{
				yield return null;
			}
			StackedUI.BirthdayDialog.SetInfoText("Updating...");
			StackedUI.BirthdayDialog.EnableButtons(enableButtons: false);
			bool restartRequired = false;
			yield return Profiles.UpdateLocalProfileBirthday(birthday, delegate(string error, Profiles.BirthdayUpdateDTO response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (response.Success)
					{
						if (response.MustRestart)
						{
							StackedUI.BirthdayDialog.SetInfoText("Success! Please restart Rec Room to continue.");
							StackedUI.BirthdayDialog.EnableButtons(enableButtons: false);
							restartRequired = true;
						}
					}
					else
					{
						StackedUI.BirthdayDialog.SetInfoText(response.Message);
						StackedUI.BirthdayDialog.EnableButtons(enableButtons: true);
						waitingForBirthday = true;
					}
				}
				else
				{
					StackedUI.BirthdayDialog.SetInfoText("Error! Failed to set birthday.");
					StackedUI.BirthdayDialog.EnableButtons(enableButtons: true);
					UnityEngine.Debug.LogError(error);
					waitingForBirthday = true;
				}
			});
			while (restartRequired)
			{
				yield return null;
			}
		}
	}

	private void OnValidBirthday(DateTime date)
	{
		birthday = date;
		isJunior = birthday.ToUniversalTime().AddYears(13) > DateTime.UtcNow;
		waitingForBirthday = false;
	}

	private IEnumerator WaitForEmailVerification()
	{
		yield return StackedUI.ShowVerifyEmailDialog(QueueRegistrationEventForPostLogIn, isJunior);
	}

	private IEnumerator WaitForEmail()
	{
		StackedUI.ShowRegistrationDialog(fromReminder: false, isJunior);
		Menu.ShowKeyboard();
		PlayVO((!isJunior) ? TutorialManager.TutorialAudioType.RegisterNonJunior : TutorialManager.TutorialAudioType.RegisterJunior);
		while (waitingForEmail)
		{
			UIRegistrationDialog.OnValidEmailEntered = (Action<string>)Delegate.Combine(UIRegistrationDialog.OnValidEmailEntered, new Action<string>(OnValidEmailEntered));
			while (waitingForEmail)
			{
				yield return null;
			}
			if (string.IsNullOrEmpty(email))
			{
				continue;
			}
			StackedUI.RegistrationDialog.SetInfoText("Setting email...", enableButtons: false);
			yield return RecNet.Login.RegisterAccount(email, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (!response.Success)
					{
						StackedUI.RegistrationDialog.SetInfoText(response.Message, enableButtons: true);
						waitingForEmail = true;
					}
				}
				else
				{
					StackedUI.RegistrationDialog.SetInfoText("Error! Failed to set email.", enableButtons: true);
					UnityEngine.Debug.LogError(error);
					waitingForEmail = true;
				}
			});
		}
	}

	private void OnValidEmailEntered(string email)
	{
		UIRegistrationDialog.OnValidEmailEntered = (Action<string>)Delegate.Remove(UIRegistrationDialog.OnValidEmailEntered, new Action<string>(OnValidEmailEntered));
		this.email = email;
		waitingForEmail = false;
	}

	private void PlayVO(TutorialManager.TutorialAudioType audioType)
	{
		RecRoomAudioClip tutorialAudio = tutorialAudioConfigs.GetTutorialAudio(audioType);
		if (VOSource.isPlaying)
		{
			VOSource.Stop();
		}
		VOSource.clip = tutorialAudio.audioClip;
		VOSource.volume = tutorialAudio.volume;
		if (tutorialAudio.pitchVariation > 0f)
		{
			VOSource.pitch = 1f + UnityEngine.Random.Range(0f - tutorialAudio.pitchVariation, tutorialAudio.pitchVariation);
		}
		else
		{
			VOSource.pitch = 1f;
		}
		VOSource.Play();
	}

	private void FadeInMusic(float delay = 0f)
	{
		if (musicFadeCoroutine != null)
		{
			StopCoroutine(musicFadeCoroutine);
		}
		musicFadeCoroutine = StartCoroutine(FadeInMusicRoutine(delay));
	}

	private IEnumerator FadeInMusicRoutine(float delay)
	{
		if (musicSource != null)
		{
			yield return new WaitForSeconds(delay);
			musicSource.Play();
			float startVolume = musicSource.volume;
			for (float t = 0f; t < 1f; t += UnityEngine.Time.deltaTime / musicFadeInTime)
			{
				musicSource.volume = Mathf.Lerp(startVolume, initialMusicVolume, t);
				yield return null;
			}
			musicSource.volume = initialMusicVolume;
		}
	}

	private void FadeOutMusic(float delay = 0f)
	{
		if (musicFadeCoroutine != null)
		{
			StopCoroutine(musicFadeCoroutine);
		}
		musicFadeCoroutine = StartCoroutine(FadeOutMusicRoutine(delay));
	}

	private IEnumerator FadeOutMusicRoutine(float delay)
	{
		if (musicSource != null)
		{
			yield return new WaitForSeconds(delay);
			float startVolume = musicSource.volume;
			for (float t = 0f; t < 1f; t += UnityEngine.Time.deltaTime / musicFadeOutTime)
			{
				musicSource.volume = Mathf.Lerp(startVolume, 0f, t);
				yield return null;
			}
			musicSource.volume = 0f;
			musicSource.Stop();
		}
	}
