namespace RecRoom.Activities.Quest
{
	public class DraculaQuestGear : QuestGear
	{
		private Whip whip;

		private RangedWeapon rangedWeapon;

		private void Awake()
		{
			whip = GetComponent<Whip>();
			if (whip != null)
			{
				whip.Tool.AddCustomPickupCondition(WhipCustomPickupCondition);
				whip.Tool.AddCustomEquipCondition(WhipCustomEquipCondition);
				whip.Tool.PostPickupEvent += OnWhipPickup;
				this.UpdateAtRate(5f, UpdateWhipCleanup);
			}
			else
			{
				rangedWeapon = GetComponent<RangedWeapon>();
				if (rangedWeapon != null)
				{
					rangedWeapon.AmmunitionChangeEvent += OnAmmunitionChange;
				}
			}
			if (whip == null && rangedWeapon == null)
			{
				UnityEngine.Object.Destroy(this);
			}
		}

		private void OnDestroy()
		{
			if (whip != null)
			{
				whip.Tool.RemoveCustomPickupCondition(WhipCustomPickupCondition);
				whip.Tool.RemoveCustomEquipCondition(WhipCustomEquipCondition);
				whip.Tool.PostPickupEvent -= OnWhipPickup;
			}
			if (rangedWeapon != null)
			{
				rangedWeapon.AmmunitionChangeEvent -= OnAmmunitionChange;
			}
		}

		private bool WhipCustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			foreach (PlayerHand bothHand in selectingPlayer.BothHands)
			{
				if (bothHand.HeldTool != null && bothHand.HeldTool.SpawnableToolType == SpawnableToolType.DRACULA_WHIP)
				{
					return false;
				}
			}
			PlayerToolEquipSlot[] allSlots = selectingPlayer.ToolEquipSlots.AllSlots;
			foreach (PlayerToolEquipSlot playerToolEquipSlot in allSlots)
			{
				if (playerToolEquipSlot.IsFull && playerToolEquipSlot.EquippedTool.SpawnableToolType == SpawnableToolType.DRACULA_WHIP && thisTool != playerToolEquipSlot.EquippedTool)
				{
					return false;
				}
			}
			return true;
		}

		private void OnWhipPickup(Tool thisTool)
		{
			if (!(thisTool.HolderPlayer == Player.LocalPlayer))
			{
				return;
			}
			foreach (PlayerHand bothHand in Player.LocalPlayer.BothHands)
			{
				if (bothHand.HeldTool != null && bothHand.HeldTool != thisTool && bothHand.HeldTool.SpawnableToolType == SpawnableToolType.DRACULA_WHIP)
				{
					bothHand.TryReleaseTool(Vector3.zero, Vector3.zero);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "No dual wielding... don't be sneaky!", 2f);
				}
			}
		}

		private bool WhipCustomEquipCondition(Tool tool, Player equippingPlayer, ToolEquipSlot equipSlot)
		{
			if (equippingPlayer != null)
			{
				foreach (PlayerHand bothHand in equippingPlayer.BothHands)
				{
					if (bothHand.HeldTool != null && bothHand.HeldTool.SpawnableToolType == SpawnableToolType.DRACULA_WHIP && bothHand.HeldTool != tool)
					{
						return false;
					}
				}
				PlayerToolEquipSlot[] allSlots = equippingPlayer.ToolEquipSlots.AllSlots;
				foreach (PlayerToolEquipSlot playerToolEquipSlot in allSlots)
				{
					if (playerToolEquipSlot.IsFull && playerToolEquipSlot.EquippedTool.SpawnableToolType == SpawnableToolType.DRACULA_WHIP && tool != playerToolEquipSlot.EquippedTool)
					{
						return false;
					}
				}
			}
			return true;
		}

		private void UpdateWhipCleanup(float deltaTime)
		{
			if (!(whip == null))
			{
				whip.Tool.ToolCleanup.CheckCleanup();
			}
		}

		private void OnAmmunitionChange()
		{
			if (rangedWeapon.hasAuthority && rangedWeapon.IsAmmoTotallyExhausted && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				rangedWeapon.Tool.PostResetEvent += NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.OnSpawnedToolReset;
				rangedWeapon.Tool.ToolCleanup.AuthorityQueueForceCleanup();
				rangedWeapon.Tool.ToolCleanup.defaultDelayUntilCleanup = 0f;
			}
		}
	}
