		[Header("Dash")]
		[SerializeField]
		private DashConfiguration[] phaseDashConfigurations;

		[SerializeField]
		private float maxDashForce = 67f;

		[SerializeField]
		private float dashSlowdownDistance = 1f;

		[Header("Bat Form")]
		[SerializeField]
		private EnemyType batFormEnemyType = EnemyType.QUEST_DRACULA_BOSS_BAT;

		[SerializeField]
		private EnemyType batFormDecoyEnemyType = EnemyType.QUEST_DRACULA_BASIC_LUNGE_BAT_ENEMY;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private GameEncounter animalFormGameEncounter;

		private SynchronizedField<Vector3> _attackOrigin;

		private SynchronizedField<Vector3> _relocateTarget;

		private SynchronizedField<int> _currentPhase;

		public SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private SynchronizedTimer phaseChangeTimer;

		private AnimationAttackTrigger animationAttackTrigger;

		private AttackConfiguration currentAttackConfiguration = AttackConfiguration.Default;

		private Vector3 lastUpdatedAttackTargetPosition = Vector3.zero;

		private int attacksPerformedThisCycle;

		private bool chargingMeleeAttack;

		private SFXAudioSource teleportingInAudioSource;

		private Vector3 AttackOrigin
		{
			get
			{
				return _attackOrigin.Get();
			}
			set
			{
				_attackOrigin.Set(value);
			}
		}

		private Vector3 RelocateTarget
		{
			get
			{
				return _relocateTarget.Get();
			}
			set
			{
				_relocateTarget.Set(value);
			}
		}

		private EncounterPhase CurrentEncounterPhase
		{
			get
			{
				return (EncounterPhase)_currentPhase.Get();
			}
			set
			{
				_currentPhase.Set((int)value);
			}
		}

		public override int CustomEncounterValue => (int)CurrentEncounterPhase;

		private bool IsInBatForm
		{
			get
			{
				EncounterPhase currentEncounterPhase = CurrentEncounterPhase;
				return currentEncounterPhase == EncounterPhase.BAT_FORM_1 || currentEncounterPhase == EncounterPhase.BAT_FORM_2;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			cachesLatestVisibleTargetPosition = canTargetLastVisiblePlayerPosition;
			enemyAudio.MovingSoundVolumeDrivenBySteeringSpeed = !base.Steering.IsHovering;
			animationAttackTrigger = GetComponentInChildren<AnimationAttackTrigger>(includeInactive: true);
			if (animationAttackTrigger == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing Animation Attack Trigger.");
			}
			else
			{
				animationAttackTrigger.MeleeAttackEnableEvent += OnMeleeAttackAnimationActive;
			}
			_attackOrigin = new SynchronizedField<Vector3>(this, "AO", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_relocateTarget = new SynchronizedField<Vector3>(this, "RT", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_currentPhase = new SynchronizedField<int>(this, "CP", 0, SetterPermissionMode.MASTER, OnCurrentPhaseChange);
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			mustBeOnNavMesh = false;
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			phaseChangeTimer = new SynchronizedTimer(this, "P", SetterPermissionMode.MASTER);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterFindTargetState, OnExitFindTargetState, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(4, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
			behaviorStateMachine.AddState(1, OnEnterTeleportOutState, OnExitTeleportOutState, OnUpdateTeleportOutState);
			behaviorStateMachine.AddState(2, OnEnterSneakState, OnExitSneakState, OnUpdateSneakState);
			behaviorStateMachine.AddState(3, OnEnterTeleportInState, OnExitTeleportInState, OnUpdateTeleportInState);
			behaviorStateMachine.AddState(5, OnEnterAttackTargetState, OnExitAttackTargetState, OnUpdateAttackTargetState);
			behaviorStateMachine.AddState(6, OnEnterPostAttackState, OnExitPostAttackState, OnUpdatePostAttackState);
			behaviorStateMachine.AddState(7, OnEnterDashState, OnExitDashState, OnUpdateDashState);
			Enemy.EnemyInstantiatedEvent += OnEnemyInstantiated;
			Enemy.TookDamageEvent += OnTookDamage;
			base.photonView.OwnerChangedEvent += OnAuthorityChanged;
		}

		protected override void Start()
		{
			base.Start();
			if (PhotonNetwork.isMasterClient)
			{
				GameEncounter[] componentsInChildren = GetComponentsInChildren<GameEncounter>();
				foreach (GameEncounter gameEncounter in componentsInChildren)
				{
					gameEncounter.Initialize();
					gameEncounter.MasterActivate();
				}
			}
			behaviorStateMachine.Start(this, ushort.MaxValue);
			OnCurrentPhaseChange();
		}

		protected override void OnDestroy()
		{
			Enemy.EnemyInstantiatedEvent -= OnEnemyInstantiated;
			Enemy.TookDamageEvent -= OnTookDamage;
			base.photonView.OwnerChangedEvent -= OnAuthorityChanged;
			base.OnDestroy();
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
			phaseChangeTimer.UpdateCallbacks();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (trackTargetCount)
			{
				return FindLeastTargetedNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
			}
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = movementSpeed;
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					behaviorStateMachine.EnterState(1);
				}
				else if (pathTowardsPlayerCentroidToFindTarget)
				{
					UpdateTargetCentroidPath(movementSlowdownDistance);
				}
				else
				{
					behaviorStateMachine.EnterState(7);
				}
			}
		}

		private void OnExitFindTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private void OnEnterTeleportOutState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.Jump = EnemyAnimator.JumpState.PREPARE;
			base.CollidersEnabled = false;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(teleportOutDuration);
			}
		}

		private void OnUpdateTeleportOutState()
		{
			if (behaviorTimer.TimerOver)
			{
				OnDisengagedStart();
				if (base.hasAuthority)
				{
					behaviorStateMachine.EnterState(2);
				}
			}
		}

		private void OnExitTeleportOutState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.Jump = EnemyAnimator.JumpState.NONE;
			base.Steering.StopAll();
		}

		private void OnEnterSneakState(ushort previousStateId, ushort previousSubStateId)
		{
			if (sneakingVOClips != null && sneakingVOClips.Length > 0)
			{
				float num = UnityEngine.Random.Range(0f, 1f);
				if (num <= playSneakingVOProbability)
				{
					int num2 = UnityEngine.Random.Range(0, sneakingVOClips.Length);
					AudioManager.Play2DSFX(sneakingVOClips[num2]);
				}
			}
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(sneakDuration);
			}
		}

		private void OnUpdateSneakState()
		{
			if (!behaviorTimer.TimerOver)
			{
				return;
			}
			if (!teleportingInParticle.isPlaying)
			{
				teleportingInParticle.Play();
				teleportingInAudioSource = AudioManager.Play3DSFX(teleportingInAudioClip, base.transform);
				if (base.hasAuthority)
				{
					RelocateTarget = GetRelocateTarget(out var targetHeight);
					base.RigidbodyEx.targetPosition = RelocateTarget + Vector3.up * targetHeight;
					base.RigidbodyEx.targetRotation = Quaternion.LookRotation(base.Target.FloorPosition - RelocateTarget, Vector3.up);
					behaviorTimer.StartTimer(teleportParticleTimeBeforeTeleportIn);
				}
			}
			else if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(3);
			}
		}

		private void OnExitSneakState(ushort previousStateId, ushort previousSubStateId)
		{
			teleportingInParticle.Stop();
			if ((object)teleportingInAudioSource != null)
			{
				teleportingInAudioSource.Stop();
			}
		}

		private void OnEnterTeleportInState(ushort previousStateId, ushort previousSubStateId)
		{
			OnDisengagedEnd();
			attacksPerformedThisCycle = 0;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(teleportInDuration);
			}
		}

		private void OnUpdateTeleportInState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(4);
			}
		}

		private void OnExitTeleportInState(ushort previousStateId, ushort previousSubStateId)
		{
			base.CollidersEnabled = true;
		}

		private Vector3 GetRelocateTarget(out float targetHeight)
		{
			if (!base.Target.IsValid)
			{
			}
			Vector3 zero = Vector3.zero;
			Vector3 zero2 = Vector3.zero;
			float num = 0f;
			if (UnityEngine.Random.Range(0f, 1f) <= assassinationProbability)
			{
				zero2 = Vector3.ProjectOnPlane(-base.Target.Player.Head.transform.forward, Vector3.up).normalized;
				num = assassinationTeleportInDistanceFromTarget;
			}
			else
			{
				zero2 = Vector3.ProjectOnPlane(base.Target.Player.Head.transform.forward, Vector3.up).normalized;
				float num2 = normalTeleportAngleInFrontOfPlayer / 2f;
				zero2 = Quaternion.AngleAxis(UnityEngine.Random.Range(0f - num2, num2), Vector3.up) * zero2;
				num = normalTeleportInDistanceFromTarget;
			}
			zero = base.Target.HeadPosition + zero2 * num;
			if (Enemy.TryGetRaycastHitPoint(base.Target.HeadPosition, zero2, num, out var distance, out var hitPoint, out var hitNormal))
			{
				zero = hitPoint;
			}
			if (Enemy.TryGetRaycastHitPoint(zero, Vector3.down, float.MaxValue, out distance, out hitPoint, out hitNormal))
			{
				zero = hitPoint;
				targetHeight = Mathf.Max(distance, base.Steering.DesiredHoverHeight);
			}
			else
			{
				targetHeight = base.Steering.CurrentHoverHeight;
			}
			Enemy.TrySampleNavMesh(zero, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			chargingMeleeAttack = Vector3.SqrMagnitude(base.Target.HeadPosition - base.Steering.HoverPosition) <= targetDistanceForMeleeAttack * targetDistanceForMeleeAttack;
			if (chargingMeleeAttack)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.CHARGE;
			}
			else
			{
				enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			}
			enemyAudio.OnChargeAttack();
			enemyParticles.StartCharge(rangedWeapon.ProjectileOriginTransform);
			if (base.hasAuthority)
			{
				AttackOrigin = base.Steering.HoverPosition;
				behaviorTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid || behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(5);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
			}
		}

		private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyParticles.StopCharge();
		}

		private void OnEnterAttackTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority && attacksPerformedThisCycle > 0)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
				}
			}
			TryGetLatestTargetAttackPoint(out lastUpdatedAttackTargetPosition);
			AttackTargetCombatant(chargingMeleeAttack);
			attacksPerformedThisCycle++;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackTargetState()
		{
			if (base.hasAuthority && (!base.Target.IsValid || behaviorTimer.TimerOver))
			{
				if (attacksPerformedThisCycle >= currentAttackConfiguration.numberOfAttacks)
				{
					if (supportsPostAttack)
					{
						behaviorStateMachine.EnterState(6);
					}
					else
					{
						behaviorStateMachine.EnterState(7);
					}
				}
				else
				{
					behaviorStateMachine.EnterState(4);
				}
			}
			else
			{
				base.Steering.Look(GetAttackLookVector());
			}
		}

		private void OnExitAttackTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			if (!supportsPostAttack)
			{
				enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private Vector3 GetAttackLookVector()
		{
			bool inXZPlane = true;
			if (updateTargetPositionWhileAttacking)
			{
				return GetLookAtTargetVector(inXZPlane);
			}
			return GetLookAtVector(lastUpdatedAttackTargetPosition, inXZPlane);
		}

		private bool TryGetLatestTargetAttackPoint(out Vector3 targetPosition)
		{
			if (!base.Target.IsValid)
			{
				targetPosition = Vector3.zero;
				return false;
			}
			if (attackTarget == AttackTarget.PLAYER_HEAD)
			{
				targetPosition = ((!canTargetLastVisiblePlayerPosition) ? base.Target.HeadPosition : latestVisibleTargetHeadPosition);
			}
			else
			{
				targetPosition = ((!canTargetLastVisiblePlayerPosition) ? base.Target.FloorPosition : latestVisibleTargetFloorPosition);
			}
			return true;
		}

		private void AttackTargetCombatant(bool meleeAttack)
		{
			if (!base.Target.IsValid)
			{
				return;
			}
			enemyAudio.OnAttack();
			if (meleeAttack)
			{
				enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			}
			else
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
				enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.ATTACK;
			}
			if (base.hasAuthority)
			{
				if (!updateTargetPositionWhileAttacking)
				{
					AuthorityFireRangedWeaponAtExplicitTargetPosition(lastUpdatedAttackTargetPosition, animationShotDelay);
				}
				else if (attackTarget == AttackTarget.PLAYER_HEAD)
				{
					AuthorityFireRangedWeaponAtTarget(canTargetLastVisiblePlayerPosition, animationShotDelay);
				}
				else if (attackTarget == AttackTarget.PLAYER_FEET)
				{
					AuthorityFireRangedWeaponAtTargetFloor(canTargetLastVisiblePlayerPosition, animationShotDelay);
				}
			}
		}

		private void OnEnterPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.POST_ATTACK;
			enemyAudio.OnChargeAttack();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(postAttackDuration);
			}
		}

		private void OnUpdatePostAttackState()
		{
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid || behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(7);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
			}
		}

		private void OnExitPostAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
		}

		private void OnEnterDashState(ushort previousStateId, ushort previousSubStateId)
		{
			DashConfiguration phaseDashConfiguration = GetPhaseDashConfiguration(CurrentEncounterPhase);
			base.Steering.MaxHorizontalSpeed = phaseDashConfiguration.dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxDashForce;
			base.Steering.MaxVerticalSpeed = phaseDashConfiguration.dashSpeed;
			base.Steering.MaxVerticalSteeringForce = maxDashForce;
			if (base.hasAuthority)
			{
				base.Steering.Path(GetDashPosition(phaseDashConfiguration.minDashDistance, phaseDashConfiguration.maxDashDistance), dashSlowdownDistance, 0.05f * phaseDashConfiguration.dashSpeed, faceVelocity: false);
				float num = UnityEngine.Random.Range(0f, 1f);
				float maxRunningTime = phaseDashConfiguration.dashTimeout;
				if (num <= phaseDashConfiguration.noDashProbability)
				{
					maxRunningTime = 0f;
				}
				behaviorTimer.StartTimer(maxRunningTime);
			}
		}

		private void OnUpdateDashState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(0);
				}
				else if (base.Target.IsValid && base.Steering.IsHovering)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
			}
		}

		private void OnExitDashState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private Vector3 GetDashPosition(float minDashDistance, float maxDashDistance)
		{
			Vector3 zero = Vector3.zero;
			Vector3 vector = Vector3.ProjectOnPlane(AttackOrigin - base.transform.position, Vector3.up);
			float magnitude = vector.magnitude;
			zero = ((!(magnitude >= maxDashDistance)) ? UnityEngine.Random.onUnitSphere : (vector / magnitude));
			float num = UnityEngine.Random.Range(minDashDistance, maxDashDistance);
			Enemy.TrySampleNavMesh(base.RigidbodyEx.physicsPosition + zero * num, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		protected override void OnDisengagedStart()
		{
			base.OnDisengagedStart();
			ChangeVisibility(visible: false);
			base.CollidersEnabled = false;
			AudioManager.Play3DSFX(teleportOutAudioClip, base.transform.position);
		}

		protected override void OnDisengagedEnd()
		{
			ChangeVisibility(visible: true);
			base.OnDisengagedEnd();
			AudioManager.Play3DSFX(teleportInAudioClip, base.transform.position);
		}

		private void ChangeVisibility(bool visible)
		{
			if (teleportParticle != null)
			{
				teleportParticle.Play();
			}
			visibleMeshRenderer.enabled = visible;
		}

		private void OnMeleeAttackAnimationActive(bool active)
		{
			if (meleeAttackColliders != null)
			{
				MeleeWeaponCollider[] array = meleeAttackColliders;
				foreach (MeleeWeaponCollider meleeWeaponCollider in array)
				{
					meleeWeaponCollider.enabled = active;
				}
			}
		}

		private void OnEnemyInstantiated(Enemy newEnemy)
		{
			if (newEnemy.EnemyType == batFormEnemyType)
			{
				newEnemy.DeathEvent += OnAnimalFormEnemyDeath;
			}
			else if (newEnemy.EnemyType == batFormDecoyEnemyType)
			{
				newEnemy.DeathEvent += OnAnimalFormDecoyEnemyDeath;
			}
		}

		private void OnTookDamage(Combatant attacker, Enemy defender, Vector3 impactPoint)
		{
			if (PhotonNetwork.isMasterClient && defender == this && phaseChangeTimer.TimerOver)
			{
				EncounterPhase currentEncounterPhase = CurrentEncounterPhase;
				if (currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_1 || currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_2 || currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_3)
				{
					CurrentEncounterPhase++;
					phaseChangeTimer.StartTimer(5f);
				}
			}
		}

		private void OnAnimalFormEnemyDeath(Enemy deadEnemy)
		{
			deadEnemy.DeathEvent -= OnAnimalFormEnemyDeath;
			if (PhotonNetwork.isMasterClient)
			{
				CurrentEncounterPhase++;
			}
		}

		private void OnAnimalFormDecoyEnemyDeath(Enemy deadEnemy)
		{
			deadEnemy.DeathEvent -= OnAnimalFormDecoyEnemyDeath;
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && IsInBatForm)
			{
				((QuestManager)NetworkedSingletonMonoBehaviour<GameManager>.Instance).CurrentRoomStoryState++;
			}
		}

		private void OnCurrentPhaseChange()
		{
			EncounterPhase currentEncounterPhase = CurrentEncounterPhase;
			if (currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_1 || currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_2 || currentEncounterPhase == EncounterPhase.VAMPIRE_FORM_3)
			{
				currentAttackConfiguration = GetPhaseAttackConfiguration(currentEncounterPhase);
				if (rangedWeapon != null)
				{
					rangedWeapon.PlayerHitEvent -= base.OnRangedWeaponPlayerHit;
					rangedWeapon.PlayerToolHitEvent -= base.OnRangedWeaponPlayerToolHit;
					rangedWeapon.EnemyHitEvent -= base.OnRangedWeaponEnemyHit;
					rangedWeapon.LocalPreFireEvent -= OnRangedWeaponLocalFire;
				}
				rangedWeapon = currentAttackConfiguration.attackWeapon;
				rangedWeapon.PlayerHitEvent += base.OnRangedWeaponPlayerHit;
				rangedWeapon.PlayerToolHitEvent += base.OnRangedWeaponPlayerToolHit;
				rangedWeapon.EnemyHitEvent += base.OnRangedWeaponEnemyHit;
				rangedWeapon.LocalPreFireEvent += OnRangedWeaponLocalFire;
			}
		}

		private AttackConfiguration GetPhaseAttackConfiguration(EncounterPhase phase)
		{
			if (phaseAttackConfigurations != null)
			{
				AttackConfiguration[] array = phaseAttackConfigurations;
				for (int i = 0; i < array.Length; i++)
				{
					AttackConfiguration result = array[i];
					if (result.encounterPhase == phase)
					{
						return result;
					}
				}
			}
			return AttackConfiguration.Default;
		}

		private DashConfiguration GetPhaseDashConfiguration(EncounterPhase phase)
		{
			if (phaseDashConfigurations != null)
			{
				DashConfiguration[] array = phaseDashConfigurations;
				for (int i = 0; i < array.Length; i++)
				{
					DashConfiguration result = array[i];
					if (result.encounterPhase == phase)
					{
						return result;
					}
				}
			}
			return DashConfiguration.Default;
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = true;
			}
			animalFormGameEncounter.MasterDeactivate();
			GameEncounter.MasterDestroy(animalFormGameEncounter);
		}

		private void OnAuthorityChanged(int newOwnerId)
		{
			if (phaseAttackConfigurations != null)
			{
				AttackConfiguration[] array = phaseAttackConfigurations;
				for (int i = 0; i < array.Length; i++)
				{
					AttackConfiguration attackConfiguration = array[i];
					attackConfiguration.attackWeapon.photonView.TransferOwnership(newOwnerId);
				}
			}
		}
	}
	public class QuestLungingEnemy : Enemy
	{
		private enum BehaviorState
		{
			FIND_TARGET = 0,
			FOLLOW_TARGET = 1,
			LUNGE_ATTACK_CHARGE = 2,
			LUNGE_ATTACK = 3,
			POST_ATTACK = 4,
			DASH = 5,
			INVALID = 65535
		}

		[Header("Target Selection")]
		[SerializeField]
		private bool pathTowardsPlayerCentroidToFindTarget = true;

		[SerializeField]
		private float desiredTargetDistance = 1f;

		[Header("Attack Charge")]
		[SerializeField]
		private float attackChargeDuration = 1f;

		[Header("Lunge Attack")]
		[SerializeField]
		private float maxLungeDistance = 8f;

		[SerializeField]
		private float lungeForce = 300f;

		[SerializeField]
		private float lungeTime = 3f;

		[SerializeField]
		private AnimationCurve lungeCurve;

		[Header("Post Attack")]
		[SerializeField]
		private float postAttackDuration = 2f;

		[Header("Dash")]
		[SerializeField]
		private float dashSpeed = 4f;

		[SerializeField]
		private float maxDashForce = 67f;

		[SerializeField]
		private float dashSlowdownDistance = 1f;

		[SerializeField]
		private float minDashDistance = 2f;

		[SerializeField]
		private float maxDashDistance = 4f;

		[SerializeField]
		private float dashTimeout = 2.5f;

		[Header("Visuals")]
		[SerializeField]
		private ParticleSystem lungeParticle;

		[SerializeField]
		private TrailRenderer lungeTrail;

		private const string lungingEnemyToken = "LungingEnemy";

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private bool defaultHoverBehavior;

		private AnimationAttackTrigger animationAttackTrigger;

		private float shieldStunRecoilSpeed = 3.5f;

		private SynchronizedField<Vector3> _attackOrigin;

		private float currentLungeLength;

		private float minLungeHeight;

		private float maxLungeHeight;

		private Vector3 AttackOrigin
		{
			get
			{
				return _attackOrigin.Get();
			}
			set
			{
				_attackOrigin.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			animationAttackTrigger = GetComponentInChildren<AnimationAttackTrigger>(includeInactive: true);
			if (animationAttackTrigger != null)
			{
				animationAttackTrigger.MeleeAttackEnableEvent += OnMeleeAttackAnimationActive;
			}
			else
			{
				base.MeleeCombatActive = true;
			}
			defaultHoverBehavior = base.Steering.HoverEnabled;
			_attackOrigin = new SynchronizedField<Vector3>(this, "AO", Vector3.zero, SetterPermissionMode.AUTHORITY);
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterFindTargetState, OnExitFindTargetState, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
			behaviorStateMachine.AddState(2, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
			behaviorStateMachine.AddState(3, OnEnterLungeAttackState, OnExitLungeAttackState, OnUpdateLungeAttackState);
			behaviorStateMachine.AddState(4, OnEnterPostAttackState, OnExitPostAttackState, OnUpdatePostAttackState);
			behaviorStateMachine.AddState(5, OnEnterDashState, OnExitDashState, OnUpdateDashState);
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (animationAttackTrigger != null)
			{
				animationAttackTrigger.MeleeAttackEnableEvent -= OnMeleeAttackAnimationActive;
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			if (isPatrolling)
			{
				return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
			}
			float distanceToClosestTargetSqr;
			return SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopLooking();
			base.Steering.MaxHorizontalSpeed = movementSpeed;
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					behaviorStateMachine.EnterState(1);
				}
				else if (pathTowardsPlayerCentroidToFindTarget)
				{
					UpdateTargetCentroidPath(movementSlowdownDistance);
				}
			}
		}

		private void OnExitFindTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			base.Steering.MaxVerticalSteeringForce = movementMaxForce;
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxVerticalSpeed = movementSpeed;
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
		}

		protected virtual void OnUpdateFollowTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			float distanceToClosestTargetSqr;
			Combatant closestOpponent = SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
			if (closestOpponent.IsValid && distanceToClosestTargetSqr <= desiredTargetDistance * desiredTargetDistance && HasStraightPathToTarget(closestOpponent.HeadPosition))
			{
				behaviorStateMachine.EnterState(2);
				return;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				behaviorStateMachine.EnterState(0);
				return;
			}
			if (LastAttackerIsValidTarget())
			{
				base.Target = base.LastAttacker;
				base.LastAttacker = Combatant.Invalid;
			}
			Vector3 floorPosition = base.Target.FloorPosition;
			if (!base.Steering.PathIsValid(floorPosition, desiredTargetDistance * 1.1f))
			{
				base.Steering.Path(floorPosition);
			}
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopPathing();
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.CHARGE;
			enemyAudio.OnChargeAttack();
			if (base.hasAuthority)
			{
				AttackOrigin = base.Steering.HoverPosition;
				behaviorTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (base.hasAuthority && (!base.Target.IsValid || behaviorTimer.TimerOver))
			{
				behaviorStateMachine.EnterState(3);
			}
		}

		private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
		}

		private void OnEnterLungeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			if ((object)lungeParticle != null)
			{
				lungeParticle.Play();
			}
			if ((object)lungeTrail != null)
			{
				lungeTrail.SetEnabled(enabled: true);
			}
			enemyAudio.OnAttack();
			base.Steering.MaxHorizontalSteeringForce = lungeForce;
			base.Steering.MaxVerticalSteeringForce = lungeForce;
			base.Steering.HoverEnabled = true;
			base.Steering.GravityEnabled = false;
			Vector3 lungeTargetPosition = GetLungeTargetPosition();
			lungeTargetPosition.y = AttackOrigin.y;
			currentLungeLength = Vector3.Distance(AttackOrigin, lungeTargetPosition);
			base.Steering.MaxHorizontalSpeed = currentLungeLength / lungeTime;
			base.Steering.MaxVerticalSpeed = 1000f;
			float num = Vector3.Distance(base.Target.HeadPosition, base.Target.FloorPosition);
			if (num < base.Steering.CurrentHoverHeight)
			{
				minLungeHeight = num;
				maxLungeHeight = base.Steering.CurrentHoverHeight;
			}
			else
			{
				minLungeHeight = base.Steering.CurrentHoverHeight;
				maxLungeHeight = num;
			}
			if (base.hasAuthority)
			{
				base.Steering.Path(lungeTargetPosition, ignoreNavmesh: true);
				behaviorTimer.StartTimer(lungeTime);
			}
		}

		private void OnUpdateLungeAttackState()
		{
			float time = Vector3.Distance(AttackOrigin, base.transform.position) / (0.78f * currentLungeLength);
			float newHeight = minLungeHeight + (maxLungeHeight - minLungeHeight) * lungeCurve.Evaluate(time);
			base.Steering.SetDesiredHoverHeight("LungingEnemy", newHeight);
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(4);
			}
		}

		private void OnExitLungeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.HoverEnabled = defaultHoverBehavior;
			base.Steering.GravityEnabled = !defaultHoverBehavior;
			base.Steering.UnsetDesiredHoverHeight("LungingEnemy");
			if (nextStateId != 4)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
			if ((object)lungeParticle != null)
			{
				lungeParticle.Stop();
			}
			if ((object)lungeTrail != null)
			{
				lungeTrail.SetEnabled(enabled: false);
			}
		}

		private Vector3 GetLungeTargetPosition()
		{
			Vector3 vector = base.Target.HeadPosition - AttackOrigin;
			float num = Mathf.Min(vector.magnitude * 2f, maxLungeDistance);
			Vector3 normalized = vector.normalized;
			Vector3 vector2 = AttackOrigin + normalized * num;
			if (Enemy.TryGetRaycastHitPoint(AttackOrigin, normalized, num, out var distance, out var hitPoint, out var hitNormal))
			{
				vector2 = hitPoint;
			}
			if (Enemy.TryGetRaycastHitPoint(vector2, Vector3.down, float.MaxValue, out distance, out hitPoint, out hitNormal))
			{
				vector2 = hitPoint;
			}
			Enemy.TrySampleNavMesh(vector2, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		private void OnEnterPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.POST_ATTACK;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(postAttackDuration);
			}
		}

		private void OnUpdatePostAttackState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(5);
			}
		}

		private void OnExitPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
		}

		private void OnEnterDashState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxDashForce;
			base.Steering.MaxVerticalSpeed = dashSpeed;
			base.Steering.MaxVerticalSteeringForce = maxDashForce;
			if (base.hasAuthority)
			{
				base.Steering.Path(GetDashPosition(), dashSlowdownDistance, 0.025f * dashSpeed, faceVelocity: false);
				behaviorTimer.StartTimer(dashTimeout);
			}
		}

		private void OnUpdateDashState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver || !base.Steering.PathIsValid() || base.Steering.ReachedPathDestination)
				{
					behaviorStateMachine.EnterState(0);
				}
				else if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(!base.Steering.IsHovering));
				}
			}
		}

		private void OnExitDashState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private Vector3 GetDashPosition()
		{
			Vector3 vector = base.transform.position + new Vector3(UnityEngine.Random.Range(0f - minDashDistance, minDashDistance), UnityEngine.Random.Range(0f - minDashDistance, minDashDistance), UnityEngine.Random.Range(0f - minDashDistance, minDashDistance));
			if (base.Target.IsValid && !base.IsStunned)
			{
				Vector3 normalized = Vector3.ProjectOnPlane(base.transform.position - base.Target.HeadPosition, Vector3.up).normalized;
				vector = base.Target.HeadPosition + normalized * desiredTargetDistance;
				Vector3 vector2 = Vector3.Cross(normalized, Vector3.up);
				vector += (float)(-1 * UnityEngine.Random.Range(0, 2)) * UnityEngine.Random.Range(minDashDistance, maxDashDistance) * vector2;
			}
			Vector3 desiredPosition = vector + Vector3.down * base.Steering.CurrentHoverHeight;
			Enemy.TrySampleNavMesh(desiredPosition, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		private void OnMeleeAttackAnimationActive(bool active)
		{
			if (base.MeleeCombatActive != active)
			{
				base.MeleeCombatActive = active;
			}
		}

		protected override void OnPlayerToolImpact(Enemy enemy, Tool hitTool, WeaponImpact impact)
		{
			TryApplyShieldBlock(hitTool, impact);
		}

		private void TryApplyShieldBlock(Tool hitTool, WeaponImpact impact)
		{
			if (base.hasAuthority && base.IsAlive && base.Health > 0)
			{
				MeleeWeapon component = hitTool.GetComponent<MeleeWeapon>();
				if (!(component == null) && component.IsShield)
				{
					AuthorityStun(WeaponDamageType.MELEE_SHIELD, EnemyArmorType.NORMAL);
					Vector3 normalized = Vector3.ProjectOnPlane(base.RigidbodyEx.physicsPosition - impact.Point, Vector3.up).normalized;
					Vector3 velocity = normalized * shieldStunRecoilSpeed;
					AuthorityOnDamageChangeVelocity(WeaponDamageType.MELEE_SHIELD, EnemyArmorType.NORMAL, velocity, Vector3.zero);
				}
			}
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			base.RigidbodyEx.useGravity = true;
		}

		protected override void OnStunEnd(bool interruptsCustomBehaviour)
		{
			base.OnStunEnd(interruptsCustomBehaviour);
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = false;
			}
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			base.Steering.MaxVerticalSteeringForce = movementMaxForce;
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxVerticalSpeed = movementSpeed;
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			base.Steering.StopPathing();
		}
	}
}
[RequireComponent(typeof(PhotonView))]
public class LoopingTransformPath : Photon.MonoBehaviour
{
	[Header("Path")]
	[SerializeField]
	private Transform[] targetPath;

	[SerializeField]
	private float rotateSpeed = 5f;

	[SerializeField]
	private float translateSpeed = 1f;

	[SerializeField]
	private AnimationCurve lerpFunction = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(1f, 1f));

	private float duration;

	protected override void Awake()
	{
		base.Awake();
		CalculateDuration();
	}

	protected void Update()
	{
		UpdateTransform(UnityEngine.Time.deltaTime);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
	}

	private void CalculateDuration()
	{
		float a = ((!(translateSpeed > 0.001f)) ? 0f : (Vector3.Magnitude(targetPath[0].position - targetPath[1].position) / translateSpeed));
		float b = ((!(rotateSpeed > 0.001f)) ? 0f : (Quaternion.Angle(targetPath[0].rotation, targetPath[1].rotation) / rotateSpeed));
		duration = Mathf.Max(a, b) * 2f;
	}

	private void UpdateTransform(float deltaTime)
	{
		if (!(duration < 0.001f))
		{
			float num = (float)(PhotonNetwork.time % 100000.0);
			num %= duration;
			float t = lerpFunction.Evaluate(1f - Mathf.Abs(1f - 2f * (num / duration)));
			if (translateSpeed > 0.001f)
			{
				base.transform.position = Vector3.Lerp(targetPath[0].position, targetPath[1].position, t);
			}
			if (rotateSpeed > 0.001f)
			{
				base.transform.rotation = Quaternion.Lerp(targetPath[0].rotation, targetPath[1].rotation, t);
			}
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class MirrorCannon : BeamGun
	{
		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private SwivelToolHandle handle;

		private bool hasTarget;

		public override bool Firing => handle.Tool.IsHeldByPlayer && hasTarget;

		protected override void Start()
		{
			base.Start();
			SetTeamColor(defaultProjectileColor, resetToDefault: false);
		}

		protected override void StaggeredUpdate(float deltaTime)
		{
			base.StaggeredUpdate(deltaTime);
			UpdateFindTarget();
			if (base.isBeamActive && automaticFireCoroutine == null)
			{
				StartAutomaticCoroutine();
			}
		}

		private void UpdateFindTarget()
		{
			hasTarget = false;
			if (Physics.Raycast(barrelTransform.transform.position, barrelTransform.forward, out var hitInfo, beamLength, 362036736))
			{
				EnemyArmorType hitEnemyArmorType;
				Enemy colliderEnemy = hitInfo.collider.GetColliderEnemy(out hitEnemyArmorType);
				if (colliderEnemy != null && colliderEnemy.GetDamageCombatSettings(GetEnemyDamage(), DamageType, hitEnemyArmorType) > 0)
				{
					hasTarget = true;
				}
			}
		}
	}
	public class MultiCrossbow : RangedWeapon
	{
		[Header("Crossbow")]
		[SerializeField]
		private Transform[] boltInitialNockingTransform;

		[SerializeField]
		protected Transform[] boltFinalNockingTransform;

		[SerializeField]
		private float boltNockingAnimationLength = 0.5f;

		private static readonly int drawId = Animator.StringToHash("Pull");

		protected CrossbowBolt[] bolts;

		private float currentBoltAcquisitionTime;

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent += OnInputDown;
			}
			bolts = new CrossbowBolt[boltFinalNockingTransform.Length];
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent -= OnInputDown;
			}
		}

		private void Update()
		{
			for (int i = 0; i < bolts.Length; i++)
			{
				if (bolts[i] != null)
				{
					float t = Mathf.InverseLerp(currentBoltAcquisitionTime, currentBoltAcquisitionTime + boltNockingAnimationLength, UnityEngine.Time.time);
					bolts[i].transform.position = Vector3.Lerp(boltInitialNockingTransform[i].position, boltFinalNockingTransform[i].position, t);
					bolts[i].transform.rotation = boltFinalNockingTransform[i].rotation;
				}
			}
		}

		private void OnInputDown(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (base.IsMisfire || base.IsOnCooldown)
				{
					base.WeaponAudio.OnMisfire();
				}
				else
				{
					Fire();
				}
			}
		}

		protected override void OnAmmunitionChange()
		{
			base.OnAmmunitionChange();
			if (base.MagazineAmmunition == 0)
			{
				base.Animator.SetFloat(drawId, 0f);
				return;
			}
			base.Animator.SetFloat(drawId, 1f);
			for (int i = 0; i < bolts.Length; i++)
			{
				if (bolts[i] == null)
				{
					bolts[i] = AcquireBullet() as CrossbowBolt;
					currentBoltAcquisitionTime = UnityEngine.Time.time;
				}
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				FireBullet(position, rotation, velocity, 1f, shotId);
			}
		}

		protected override void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			for (int i = 0; i < bolts.Length; i++)
			{
				if (bolts[i] == null)
				{
					byte shotId2 = shotId;
					base.FireBullet(position, rotation, velocity, chargeAmount, shotId2, overrideAndDisableGravity: false, collisionFilter, prefab);
				}
				else
				{
					bolts[i].Fire(bolts[i].transform.position, bolts[i].transform.rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, shotId);
					bolts[i] = null;
				}
			}
		}

		protected override Bullet FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, float maxLifetime, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			Bullet result = null;
			for (int i = 0; i < bolts.Length; i++)
			{
				if (bolts == null)
				{
					byte shotId2 = shotId;
					result = base.FireBullet(position, rotation, velocity, chargeAmount, maxLifetime, shotId2, overrideAndDisableGravity: false, collisionFilter, prefab);
				}
				else
				{
					result = bolts[i];
					bolts[i].Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, maxLifetime, shotId);
					bolts[i] = null;
				}
			}
			return result;
		}

		private void OnDrawGizmosSelected()
		{
			if (boltFinalNockingTransform == null)
			{
				return;
			}
			for (int i = 0; i < boltFinalNockingTransform.Length; i++)
			{
				if (!(boltFinalNockingTransform[i] == null) && !(boltInitialNockingTransform[i] == null))
				{
					Vector3 position = boltInitialNockingTransform[i].position;
					Vector3 position2 = boltFinalNockingTransform[i].position;
					Gizmos.color = Color.yellow;
					Gizmos.DrawWireSphere(position2, 0.05f);
					Gizmos.color = Color.white;
					Gizmos.DrawLine(position, position2);
					Gizmos.color = Color.green;
					Gizmos.DrawRay(position2, boltInitialNockingTransform[i].forward);
				}
			}
		}
	}
}
public class QuestTriggerTrap : Trap
{
	private void OnTriggerEnter(Collider other)
	{
		WeaponImpact impact = new WeaponImpact
		{
			Velocity = Vector3.zero,
			Force = Vector3.zero,
			Point = (other.transform.position + base.transform.position) / 2f,
			Distance = 0f,
			SurfaceNormal = other.transform.position - base.transform.position,
			GameObject = other.gameObject
		};
		Tool colliderTool = other.GetColliderTool();
		if (colliderTool != null)
		{
			if (colliderTool.IsHeld && colliderTool.Owner.isLocal && !base.hasAuthority)
			{
				base.photonView.TransferOwnership(colliderTool.Owner.PhotonPlayer);
			}
			ToolHit(colliderTool, impact);
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = other.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			if (colliderPlayer.isLocal && !base.hasAuthority)
			{
				base.photonView.TransferOwnership(colliderPlayer.PhotonPlayer);
			}
			PlayerHit(colliderPlayer, bodyPart, impact);
		}
		else
		{
			EnemyArmorType hitEnemyArmorType;
			Enemy colliderEnemy = other.GetColliderEnemy(out hitEnemyArmorType);
			if (colliderEnemy != null)
			{
				EnemyHit(colliderEnemy, hitEnemyArmorType, WeaponDamageType.MELEE, impact);
			}
		}
	}
}
public class RangedWeaponTrap : Trap
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private RangedWeapon RangedWeapon;

	[SerializeField]
	private float reloadTime = 1f;

	[SerializeField]
	private float timeBetweenShots = 3f;

	[SerializeField]
	[Tooltip("Used to offset the time between multiple traps")]
	private float startTime = 3f;

	private SynchronizedTimer timer;

	protected override void Awake()
	{
		base.Awake();
		timer = new SynchronizedTimer(this, "TRAPTIMER", SetterPermissionMode.MASTER_OR_AUTHORITY);
		timer.StartTimer(timeBetweenShots + startTime);
		this.Update10hz(StaggeredUpdate);
		RangedWeapon.PlayerImpactEvent += OnPlayerImpact;
		RangedWeapon.PlayerToolImpactEvent += OnPlayerToolImpact;
		RangedWeapon.EnemyImpactEvent += OnEnemyImpact;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		RangedWeapon.PlayerImpactEvent -= OnPlayerImpact;
		RangedWeapon.PlayerToolImpactEvent -= OnPlayerToolImpact;
		RangedWeapon.EnemyImpactEvent -= OnEnemyImpact;
	}

	private void OnEnemyImpact(Weapon weapon, Enemy defender, WeaponImpact impact, bool hadDamageAuthority)
	{
	}

	private void OnPlayerToolImpact(Weapon weapon, Tool defender, WeaponImpact impact, bool hadDamageAuthority)
	{
		ToolHit(defender, impact);
	}

	private void OnPlayerImpact(Weapon weapon, Player player, Player.BodyPart bodyPart, WeaponImpact impact, bool hadDamageAuthority)
	{
		PlayerHit(player, bodyPart, impact);
	}

	private void StaggeredUpdate(float obj)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (timer.TimerOver)
		{
			if (RangedWeapon.HasEnoughMagazineAmmunition)
			{
				RangedWeapon.Fire();
			}
			timer.StartTimer(timeBetweenShots);
		}
		else if (timer.TimeRemaining <= reloadTime && !RangedWeapon.HasEnoughMagazineAmmunition && !RangedWeapon.IsReloading)
		{
			RangedWeapon.ReloadAmmunition();
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class Whip : ExplosiveRangedWeapon
	{
		public enum WhipState
		{
			Primed,
			Uncoiling,
			Hooked,
			Cracking,
			Coiling
		}

		[Serializable]
		public struct IntervalContainer
		{
			public float min;

			public float max;

			public float Evaluate(float normalizedValue)
			{
				return Mathf.Lerp(min, max, normalizedValue);
			}
		}

		public static readonly Collider[] instantaneousOverlapResults = new Collider[16];

		[Header("Whip Attack")]
		[SerializeField]
		[FormerlySerializedAs("handVelocityMultiplier")]
		private float popperReleaseVelocityMultiplier = 1.2f;

		[SerializeField]
		private float popperCollisionForgivenessTime = 0.3f;

		[SerializeField]
		private float maxLengthReachedForgivenessTime = 0.25f;

		[SerializeField]
		private FloatValueCurve powerOverDistance;

		[SerializeField]
		private IntervalContainer blastRadiusOverDistance;

		[Header("Whip State")]
		[SerializeField]
		private float coilingTime = 0.25f;

		[Header("Whip Visuals")]
		[SerializeField]
		private MeshRenderer coiledThongMeshRenderer;

		[SerializeField]
		[FormerlySerializedAs("ropeAttachPoint")]
		private ReferencePoint thongAttachPoint;

		[SerializeField]
		private ReferencePoint popperPrimedPosition;

		[SerializeField]
		private PooledParticle weakCrackParticleEffect;

		[SerializeField]
		private PooledParticle strongCrackParticleEffect;

		[SerializeField]
		private Vector3 minRopeFirstHandle = Vector3.zero;

		[SerializeField]
		private Vector3 maxRopeFirstHandle = Vector3.zero;

		[SerializeField]
		private Vector3 minRopeSecondHandle = Vector3.zero;

		[SerializeField]
		private Vector3 maxRopeSecondHandle = Vector3.zero;

		[SerializeField]
		private float minToMaxInterpolationDistance = 5f;

		[Header("Whip Audio")]
		[SerializeField]
		private RecRoomAudioClip weakCrackAudioClip;

		[SerializeField]
		private RecRoomAudioClip strongCrackAudioClip;

		[SerializeField]
		private float strongCrackPowerThreshold = 0.8f;

		[SerializeField]
		private float strongThrowSpeedThreshold = 4f;

		[Header("Whip Gesture")]
		[SerializeField]
		private float whipGestureStartSpeed = 5f;

		[SerializeField]
		private float whipGestureCrackSpeed = 3f;

		[SerializeField]
		private float whipGestureReleaseTime = 0.2f;

		[Header("Whip Pull Tools")]
		[SerializeField]
		private AnimationCurve toolPullArcTimeByDistance;

		[SerializeField]
		private AnimationCurve toolPullAccuracyByAimAccuracy;

		[Header("Whip Hook Magnet")]
		[SerializeField]
		[Tooltip("Latch on to whip interactables from a distance")]
		private float hookMagnetDistance = 1f;

		[SerializeField]
		private LayerMask hookMagnetLayers;

		[SerializeField]
		[Tooltip("Minimum distance the popper must travel before activating the hook magnet")]
		private float hookMagnetMinDistance = 2f;

		private const float CRACKING_VELOCITY_DIRECTION_THRESHOLD = 0.6f;

		private const float UNCOIL_MIN_SPEED = 3.5f;

		private const int ROPE_POINTS_COUNT = 20;

		private SynchronizedStateMachine whipStateMachine;

		private SynchronizedField<bool> _disablePopperGravity;

		private Vector3 uncoilVelocity = Vector3.zero;

		private Vector3 crackVelocity = Vector3.zero;

		private Vector3 coilingStartPosition = Vector3.zero;

		private float lastCoilingStartTime;

		[NonSerialized]
		public bool GestureWhipping = true;

		private bool startedThrowGesture;

		private float lastThrowGestureStartTime;

		private SynchronizedField<int> _hookedInteractableId;

		private WhipInteractable _cachedHookedInteractable;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private WhipPopper popper;

		private float lastPopperCollisionTime;

		private float lastMaxLengthReachedTime;

		private float lastAttackPowerValue;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private LineRenderer ropeRenderer;

		private Vector3[] ropeSegmentPoints = new Vector3[20];

		private BezierPath ropePath = new BezierPath();

		public WhipState CurrentWhipState
		{
			get
			{
				return (WhipState)whipStateMachine.CurrentStateId;
			}
			private set
			{
				whipStateMachine.EnterState((ushort)value);
			}
		}

		public bool DisablePopperGravity
		{
			get
			{
				return _disablePopperGravity.Get();
			}
			set
			{
				_disablePopperGravity.Set(value);
			}
		}

		public bool PopperHitSomething { get; private set; }

		private WhipInteractable HookedInteractable
		{
			get
			{
				int num = _hookedInteractableId.Get();
				if (_cachedHookedInteractable == null || _cachedHookedInteractable.photonView.viewID != num)
				{
					_cachedHookedInteractable = PhotonView.Find(num)?.GetComponent<WhipInteractable>();
				}
				return _cachedHookedInteractable;
			}
			set
			{
				_hookedInteractableId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
				_cachedHookedInteractable = value;
			}
		}

		protected override Color WeaponColor => (!(base.TeamColor != null) || !base.TeamColor.IsValidTeam) ? Color.gray : base.TeamColor.Color;

		public Vector3 PopperPrimedPosition => popperPrimedPosition.position;

		protected override void Awake()
		{
			base.Awake();
			popper.transform.SetParent(null);
			popper.EnemyImpactEvent += OnPopperEnemyImpact;
			popper.ToolImpactEvent += OnPopperToolImpact;
			popper.PlayerImpactEvent += OnPopperPlayerImpact;
			popper.TrapImpactEvent += OnPopperTrapImpact;
			popper.OtherImpactEvent += OnPopperOtherImpact;
			popper.DestroyEvent += OnPopperDestroyed;
			base.Tool.PostPickupEvent += OnPickup;
			base.Tool.PostReleaseEvent += OnRelease;
			base.Tool.InputUpWithVelocityEvent += OnInputUpWithVelocity;
			ropeRenderer.positionCount = 20;
			_hookedInteractableId = new SynchronizedField<int>(this, "HI", -1, SetterPermissionMode.AUTHORITY);
			_disablePopperGravity = new SynchronizedField<bool>(this, "DPG", defaultValue: false, SetterPermissionMode.AUTHORITY);
			whipStateMachine = new SynchronizedStateMachine("WSM", SetterPermissionMode.AUTHORITY);
			whipStateMachine.AddState(4, OnEnterCoilingState, null, OnUpdateCoilingState);
			whipStateMachine.AddState(0, OnEnterPrimedState, OnExitPrimedState, OnUpdatePrimedState);
			whipStateMachine.AddState(1, OnEnterUncoilingState, OnExitUncoilingState, OnUpdateUncoilingState);
			whipStateMachine.AddState(2, null, null, OnUpdateHookedState);
			whipStateMachine.AddState(3, OnEnterCrackingState, OnExitCrackingState, OnUpdateCrackingState);
			whipStateMachine.Start(this, 0);
			this.Update10hz(StaggeredUpdate);
		}

		private void StaggeredUpdate(float obj)
		{
			if (!base.hasAuthority || CurrentWhipState != WhipState.Uncoiling || !(popper.SqrDistanceTraveled > hookMagnetMinDistance * hookMagnetMinDistance))
			{
				return;
			}
			int num = Physics.OverlapSphereNonAlloc(popper.transform.position, hookMagnetDistance, instantaneousOverlapResults, hookMagnetLayers);
			for (int i = 0; i < num; i++)
			{
				Trap colliderTrap = instantaneousOverlapResults[i].GetColliderTrap();
				if (colliderTrap != null)
				{
					popper.transform.position = instantaneousOverlapResults[i].ClosestPoint(popper.transform.position);
					popper.AttachToHook(colliderTrap, instantaneousOverlapResults[i]);
					break;
				}
			}
		}

		private void LateUpdate()
		{
			UpdateRope();
		}

		private void FixedUpdate()
		{
			whipStateMachine.Update();
		}

		protected override void OnDestroy()
		{
			base.Tool.PostPickupEvent -= OnPickup;
			base.Tool.PostReleaseEvent -= OnRelease;
			base.Tool.InputUpWithVelocityEvent -= OnInputUpWithVelocity;
			if (popper != null)
			{
				popper.EnemyImpactEvent -= OnPopperEnemyImpact;
				popper.ToolImpactEvent -= OnPopperToolImpact;
				popper.PlayerImpactEvent -= OnPopperPlayerImpact;
				popper.TrapImpactEvent -= OnPopperTrapImpact;
				popper.OtherImpactEvent -= OnPopperOtherImpact;
				popper.DestroyEvent -= OnPopperDestroyed;
				UnityEngine.Object.Destroy(popper.gameObject);
			}
			base.OnDestroy();
		}

		private void OnPopperDestroyed(Bullet bullet)
		{
			PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
			QuestGameplayRoom questGameplayRoom = UnityEngine.Object.FindObjectOfType<QuestGameplayRoom>();
			UnityEngine.Debug.LogErrorFormat("Unexpectedly destroyed Whip Popper. Destroying parent Whip ({0}.{1}) held by {2} as {3} in room {4}.{5}.", base.name, base.photonView.viewID, (!base.Tool.IsHeldByPlayer) ? "NOBODY" : base.Tool.HolderPlayer.PhotonPlayer.NickName, base.Tool.HolderInfo.Type, (!(questGameplayRoom != null)) ? "NO ROOM" : questGameplayRoom.name, (!(questGameplayRoom != null)) ? string.Empty : questGameplayRoom.CurrentState.ToString());
		}

		private void OnPickup(Tool tool)
		{
			if (base.hasAuthority)
			{
				CurrentWhipState = WhipState.Primed;
			}
		}

		private void OnRelease(Tool tool)
		{
			if (base.hasAuthority)
			{
				CurrentWhipState = WhipState.Primed;
			}
		}

		private void OnInputUpWithVelocity(Tool tool, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority && CurrentWhipState == WhipState.Primed && linearVelocity.sqrMagnitude > 12.25f)
			{
				uncoilVelocity = linearVelocity * popperReleaseVelocityMultiplier;
				CurrentWhipState = WhipState.Uncoiling;
			}
		}

		protected override void OnWielderChange()
		{
			base.OnWielderChange();
			if (base.Wielder.Player != null)
			{
				Rigidbody rigidbody = AllRigidbodies[Mathf.Max(0, AllRigidbodies.Count - 1)];
				if (rigidbody == null || (bool)rigidbody.GetComponent<PlayerHead>())
				{
					AllRigidbodies.Remove(rigidbody);
				}
				AllRigidbodies.Add(base.Wielder.Player.Head.RigidbodyEx.UnityRigidbody);
			}
		}

		private void OnEnterCoilingState(ushort otherStateId, ushort otherSubStateId)
		{
			coilingStartPosition = popper.transform.position;
			lastCoilingStartTime = UnityEngine.Time.time;
			base.WeaponAudio.OnCharge();
		}

		private void OnUpdateCoilingState()
		{
			float num = UnityEngine.Time.time - lastCoilingStartTime;
			Vector3 position = popperPrimedPosition.position;
			if (num < coilingTime)
			{
				popper.transform.position = Vector3.Lerp(coilingStartPosition, position, num / coilingTime);
				return;
			}
			popper.transform.position = position;
			if (base.hasAuthority)
			{
				CurrentWhipState = WhipState.Primed;
			}
		}

		private void OnEnterPrimedState(ushort otherStateId, ushort otherSubStateId)
		{
			HookedInteractable = null;
			base.WeaponAudio.OnFullyChargedLoopStart();
			startedThrowGesture = false;
		}

		private void OnUpdatePrimedState()
		{
			if (popper != null)
			{
				popper.transform.position = popperPrimedPosition.position;
			}
			else
			{
				OnPopperDestroyed(null);
			}
		}

		private void OnExitPrimedState(ushort otherStateId, ushort otherSubStateId)
		{
			base.WeaponAudio.OnFullyChargedLoopStop();
		}

		private void OnEnterUncoilingState(ushort otherStateId, ushort otherSubStateId)
		{
			PopperHitSomething = false;
			if (base.hasAuthority)
			{
				Fire(uncoilVelocity, Mathf.Min(uncoilVelocity.magnitude / strongThrowSpeedThreshold, 1f));
			}
		}

		private void OnUpdateUncoilingState()
		{
			if (!base.hasAuthority || !GestureWhipping)
			{
				return;
			}
			bool flag = false;
			if (lastPopperCollisionTime > lastFireTime && UnityEngine.Time.time - lastPopperCollisionTime > popperCollisionForgivenessTime)
			{
				flag = true;
			}
			else if (lastMaxLengthReachedTime < lastFireTime)
			{
				if (popper.SqrDistanceTraveled >= popper.SelfdestructDistance * popper.SelfdestructDistance - 0.0001f)
				{
					lastMaxLengthReachedTime = UnityEngine.Time.time;
				}
			}
			else if (UnityEngine.Time.time - lastMaxLengthReachedTime > maxLengthReachedForgivenessTime)
			{
				flag = true;
			}
			if (flag)
			{
				CurrentWhipState = WhipState.Coiling;
			}
		}

		private void OnExitUncoilingState(ushort otherStateId, ushort otherSubStateId)
		{
			PopperHitSomething = false;
			popper.Release(popper.transform.position);
		}

		private void OnUpdateHookedState()
		{
			if (HookedInteractable != null)
			{
				popper.transform.position = HookedInteractable.HookPointWorldPosition;
				if (base.hasAuthority && Vector3.SqrMagnitude(popper.transform.position - thongAttachPoint.position) > popper.SelfdestructDistance * popper.SelfdestructDistance)
				{
					CurrentWhipState = WhipState.Coiling;
				}
			}
			else if (base.hasAuthority)
			{
				CurrentWhipState = WhipState.Coiling;
			}
		}

		private void OnEnterCrackingState(ushort otherStateId, ushort otherSubStateId)
		{
			if (base.hasAuthority)
			{
				if (HookedInteractable == null)
				{
					float num = powerOverDistance.EvaluateNonNormalized(Vector3.Distance(popper.transform.position, barrelTransform.position));
					explosionRadius = blastRadiusOverDistance.Evaluate(num);
					AuthorityManualExplode(0f, popper.transform.position, explosionRadius, num);
				}
				else
				{
					HookedInteractable.CrackHookedWhip(base.Tool.HolderPlayer.PhotonPlayer, crackVelocity);
				}
			}
		}

		private void OnUpdateCrackingState()
		{
			if (base.hasAuthority)
			{
				CurrentWhipState = WhipState.Coiling;
			}
		}

		private void OnExitCrackingState(ushort otherStateId, ushort otherSubStateId)
		{
			HookedInteractable = null;
		}

		private void UpdateRope()
		{
			bool flag = CurrentWhipState != WhipState.Primed;
			ropeRenderer.enabled = flag && base.Tool.IsVisible;
			coiledThongMeshRenderer.enabled = !flag && base.Tool.IsVisible;
			popper.gameObject.SetActive(flag && base.Tool.IsVisible);
			if (flag)
			{
				ropePath.Clear();
				Vector3 position = thongAttachPoint.position;
				Vector3 position2 = popper.transform.position;
				float t = Mathf.Min(1f, Vector3.Distance(position, position2) / minToMaxInterpolationDistance);
				Vector3 vector = Vector3.Lerp(minRopeFirstHandle, maxRopeFirstHandle, t);
				Vector3 vector2 = Vector3.Lerp(minRopeSecondHandle, maxRopeSecondHandle, t);
				Vector3 controlPoint = position + base.Tool.RigidbodyEx.TargetTransform.TransformVector(vector);
				Vector3 controlPoint2 = position2 + popper.transform.TransformVector(vector2);
				ropePath.AddCurve(position, controlPoint, controlPoint2, position2);
				for (int i = 0; i < 20; i++)
				{
					ref Vector3 reference = ref ropeSegmentPoints[i];
					reference = ropePath.EvaluatePath((float)i / 19f);
				}
				ropeRenderer.SetPositions(ropeSegmentPoints);
			}
		}

		private void DrawRope()
		{
			ropePath.Clear();
			Vector3 position = thongAttachPoint.position;
			Vector3 position2 = popper.transform.position;
			float t = Mathf.Min(1f, Vector3.Distance(position, position2) / minToMaxInterpolationDistance);
			Vector3 vector = Vector3.Lerp(minRopeFirstHandle, maxRopeFirstHandle, t);
			Vector3 vector2 = Vector3.Lerp(minRopeSecondHandle, maxRopeSecondHandle, t);
			Vector3 controlPoint = position + base.Tool.RigidbodyEx.TargetTransform.TransformVector(vector);
			Vector3 controlPoint2 = position2 + popper.transform.TransformVector(vector2);
			ropePath.AddCurve(position, controlPoint, controlPoint2, position2);
			for (int i = 0; i < 20; i++)
			{
				ref Vector3 reference = ref ropeSegmentPoints[i];
				reference = ropePath.EvaluatePath((float)i / 19f);
			}
			ropeRenderer.SetPositions(ropeSegmentPoints);
		}

		public void UpdateWhippingGesture(Vector3 newVelocity)
		{
			if (!base.hasAuthority || !base.Tool.IsHeldByPlayer)
			{
				return;
			}
			if (CurrentWhipState == WhipState.Primed)
			{
				if (base.Tool.IsInputPressed)
				{
					startedThrowGesture = false;
				}
				else if (!startedThrowGesture)
				{
					if (newVelocity.sqrMagnitude >= whipGestureStartSpeed * whipGestureStartSpeed && Vector3.Dot(newVelocity.normalized, base.Tool.HolderPlayer.Head.transform.forward) >= 0.6f)
					{
						startedThrowGesture = true;
						lastThrowGestureStartTime = UnityEngine.Time.time;
					}
				}
				else if (UnityEngine.Time.time - lastThrowGestureStartTime >= whipGestureReleaseTime)
				{
					uncoilVelocity = newVelocity * popperReleaseVelocityMultiplier;
					CurrentWhipState = WhipState.Uncoiling;
				}
			}
			else
			{
				if (CurrentWhipState != WhipState.Uncoiling && CurrentWhipState != WhipState.Hooked)
				{
					return;
				}
				bool flag = base.Tool.IsInputPressed;
				if (!flag && newVelocity.sqrMagnitude > whipGestureCrackSpeed * whipGestureCrackSpeed)
				{
					switch (CurrentWhipState)
					{
					case WhipState.Uncoiling:
						flag = Vector3.Dot(newVelocity.normalized, popper.Velocity.normalized) <= -0.6f;
						break;
					case WhipState.Hooked:
						flag = Vector3.Dot(newVelocity.normalized, base.Tool.HolderPlayer.Head.transform.forward) <= -0.6f;
						break;
					}
				}
				if (flag)
				{
					crackVelocity = newVelocity;
					CurrentWhipState = WhipState.Cracking;
				}
			}
		}

		public void AuthorityManualUncoil(Vector3 uncoilVelocity)
		{
			if (base.hasAuthority && !GestureWhipping && CurrentWhipState == WhipState.Primed)
			{
				this.uncoilVelocity = uncoilVelocity;
				CurrentWhipState = WhipState.Uncoiling;
			}
		}

		public void AuthorityManualCrack(Vector3 crackPullVelocity)
		{
			if (base.hasAuthority && !GestureWhipping && (CurrentWhipState == WhipState.Uncoiling || CurrentWhipState == WhipState.Hooked))
			{
				crackVelocity = crackPullVelocity;
				CurrentWhipState = WhipState.Cracking;
			}
		}

		protected override Bullet AcquireBullet(Bullet prefab = null)
		{
			return popper;
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			Quaternion rotation2 = Quaternion.LookRotation(Vector3.ProjectOnPlane(velocity, Vector3.up));
			base.FireShot(position, rotation2, velocity, chargeAmount, isMisfire, shotId);
			FireBullet(position, rotation2, velocity, chargeAmount, shotId, DisablePopperGravity, PopperCollisionFilter);
		}

		protected override void Explode(float delay, Vector3 position, float radius, float chargeAmount)
		{
			lastAttackPowerValue = chargeAmount;
			bool flag = lastAttackPowerValue >= strongCrackPowerThreshold;
			explosionAudio = ((!flag) ? weakCrackAudioClip : strongCrackAudioClip);
			explosionParticles = ((!flag) ? weakCrackParticleEffect : strongCrackParticleEffect);
			ExplodeInternal(position, radius, chargeAmount, radius * 2f);
		}

		private bool PopperCollisionFilter(Rigidbody potentialHitRigidbody)
		{
			if (!base.Tool.IsHeldByPlayer)
			{
				return true;
			}
			Player holderPlayer = base.Tool.HolderPlayer;
			if (holderPlayer == null)
			{
				return true;
			}
			return potentialHitRigidbody != holderPlayer.Head.RigidbodyEx.UnityRigidbody && potentialHitRigidbody != holderPlayer.LeftHand.RigidbodyEx.UnityRigidbody && potentialHitRigidbody != holderPlayer.RightHand.RigidbodyEx.UnityRigidbody && potentialHitRigidbody != holderPlayer.Body.Rigidbody;
		}

		private void OnPopperEnemyImpact(Bullet thisBullet, Enemy hitEnemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			OnPopperImpact(impact);
		}

		private void OnPopperToolImpact(Bullet thisBullet, Tool hitTool, WeaponImpact impact)
		{
			OnPopperImpact(impact);
		}

		private void OnPopperPlayerImpact(Bullet thisBullet, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			OnPopperImpact(impact);
		}

		private void OnPopperTrapImpact(Bullet thisBullet, Trap hitTrap, WeaponImpact impact)
		{
			if (base.hasAuthority)
			{
				WhipInteractable whipInteractable = hitTrap as WhipInteractable;
				if (whipInteractable != null)
				{
					HookedInteractable = whipInteractable;
					whipInteractable.HookToObject(impact.Point);
					CurrentWhipState = WhipState.Hooked;
				}
			}
			OnPopperImpact(impact);
		}

		private void OnPopperOtherImpact(Bullet thisBullet, WeaponImpact impact)
		{
			OnPopperImpact(impact);
		}

		private void OnPopperImpact(WeaponImpact impact)
		{
			lastPopperCollisionTime = UnityEngine.Time.time;
			PopperHitSomething = true;
		}

		protected override void OnExplosivePlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			impact.PreAttackChargeAmount = lastAttackPowerValue;
			OnPlayerImpact(hitPlayer, hitBodyPart, impact);
		}

		protected override void OnExplosiveEnemyImpact(Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			if (!(base.Wielder.Enemy != null))
			{
				impact.PreAttackChargeAmount = lastAttackPowerValue;
				OnEnemyImpact(hitEnemy, EnemyArmorType.NORMAL, impact);
				if (hitEnemy.hasAuthority)
				{
					hitEnemy.AuthorityOnDamageApplyForce(WeaponDamageType.EXPLOSIVE, armorType, impact.Force, impact.Point);
				}
			}
		}

		protected override void OnExplosiveToolImpact(Tool hitTool, WeaponImpact impact)
		{
			Vector3 force = Vector3.zero;
			Vector3 position = Vector3.zero;
			if (base.hasAuthority && !hitTool.IsHeld && hitTool.CanBePickedUp && base.Tool.IsHeldByPlayer && base.Tool.HolderPlayer != null)
			{
				Vector3 position2 = base.Tool.HolderPlayer.GetOtherHand(base.Tool.HolderPlayer.DominantHand.Type).transform.position;
				Vector3 vector = position2 - hitTool.RigidbodyEx.worldCenterOfMass;
				float num = toolPullArcTimeByDistance.Evaluate(vector.magnitude);
				Vector3 b = vector;
				b.y = 0f;
				b /= num;
				position = hitTool.RigidbodyEx.worldCenterOfMass - b.normalized;
				b.y = vector.y / num + (0f - Physics.gravity.y) / 2f * num;
				b *= hitTool.RigidbodyEx.mass;
				float num2 = toolPullAccuracyByAimAccuracy.Evaluate(impact.Distance / blastRadiusOverDistance.max);
				LootTool component = hitTool.GetComponent<LootTool>();
				if (base.hasAuthority && component != null)
				{
					num2 = num2.ReMapRange(new Vector2(0f, 1f), new Vector2(0.8f, 1f));
				}
				if (num2 > 0.8f)
				{
					Transform transform = hitTool.RigidbodyEx.transform;
					force = Vector3.up * ((float)Math.PI * 2f) / num;
					force = transform.TransformVector(Vector3.Scale(transform.InverseTransformVector(force), hitTool.RigidbodyEx.inertiaTensor));
				}
				impact.Force = Vector3.Lerp(impact.Force, b, num2);
				impact.Point = Vector3.Lerp(impact.Point, hitTool.RigidbodyEx.worldCenterOfMass, num2);
			}
			OnToolImpact(hitTool, impact);
			if (base.hasAuthority && hitTool.hasAuthority)
			{
				hitTool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Impulse);
				hitTool.AuthorityApplyForce(force, position, ForceMode.VelocityChange);
			}
		}

		protected override void OnExplosiveTrapImpact(Trap hitTrap, WeaponImpact impact)
		{
			OnTrapImpact(hitTrap, impact);
		}

		private void OnDrawGizmos()
		{
			Vector3 vector = base.transform.TransformVector(minRopeFirstHandle);
			Vector3 vector2 = base.transform.TransformVector(maxRopeFirstHandle);
			Vector3 vector3 = popper.transform.TransformVector(minRopeSecondHandle);
			Vector3 vector4 = popper.transform.TransformVector(maxRopeSecondHandle);
			Vector3 position = thongAttachPoint.position;
			Vector3 position2 = popper.transform.position;
			Gizmos.color = Color.blue;
			Gizmos.DrawLine(position, position + vector);
			Gizmos.DrawLine(position2, position2 + vector3);
			Gizmos.color = Color.red;
			Gizmos.DrawLine(position, position + vector2);
			Gizmos.DrawLine(position2, position2 + vector4);
			float t = Mathf.Min(1f, Vector3.Distance(position, position2) / minToMaxInterpolationDistance);
			Vector3 vector5 = Vector3.Lerp(vector, vector2, t);
			Vector3 vector6 = Vector3.Lerp(vector3, vector4, t);
			Gizmos.color = Color.gray;
			Gizmos.DrawLine(position, position + vector5);
			Gizmos.DrawLine(position2, position2 + vector6);
			if (!UnityEngine.Application.isPlaying)
			{
				DrawRope();
			}
		}
	}
}
