	public class WhipInteractable : Trap
	{
		public delegate void WhipCrackHandler(WhipInteractable interactable, PhotonPlayer crackingPlayer, Vector3 crackGestureVelocity, Vector3 hookPointWorldPosition);

		private const string kinematicToken = "WhipInteractableKinematic";

		[SerializeField]
		private bool kinematicByDefault = true;

		[SerializeField]
		private RecRoomAudioClip hookedAudio;

		[SerializeField]
		private RecRoomAudioClip crackedAudio;

		private SynchronizedField<Vector3> _hookPoint;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private WhipCrackHandler m_HookedWhipCracked;

		private Vector3 HookPointLocalPosition
		{
			get
			{
				return _hookPoint.Get();
			}
			set
			{
				_hookPoint.Set(value);
			}
		}

		public Vector3 HookPointWorldPosition => HookTransform.TransformPoint(HookPointLocalPosition);

		private Transform HookTransform => (!(base.RigidbodyEx != null)) ? base.transform : base.RigidbodyEx.TargetTransform;

		public event WhipCrackHandler HookedWhipCracked
		{
			add
			{
				WhipCrackHandler whipCrackHandler = this.m_HookedWhipCracked;
				WhipCrackHandler whipCrackHandler2;
				do
				{
					whipCrackHandler2 = whipCrackHandler;
					whipCrackHandler = Interlocked.CompareExchange(ref this.m_HookedWhipCracked, (WhipCrackHandler)Delegate.Combine(whipCrackHandler2, value), whipCrackHandler);
				}
				while (whipCrackHandler != whipCrackHandler2);
			}
			remove
			{
				WhipCrackHandler whipCrackHandler = this.m_HookedWhipCracked;
				WhipCrackHandler whipCrackHandler2;
				do
				{
					whipCrackHandler2 = whipCrackHandler;
					whipCrackHandler = Interlocked.CompareExchange(ref this.m_HookedWhipCracked, (WhipCrackHandler)Delegate.Remove(whipCrackHandler2, value), whipCrackHandler);
				}
				while (whipCrackHandler != whipCrackHandler2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_hookPoint = new SynchronizedField<Vector3>(this, "HPT", Vector3.zero, SetterPermissionMode.ANYONE);
			if (kinematicByDefault)
			{
				SetKinematic();
			}
		}

		public void HookToObject(Vector3 hitPoint)
		{
			HookPointLocalPosition = HookTransform.InverseTransformPoint(hitPoint);
			if (hookedAudio != null)
			{
				AudioManager.Play3DSFX(hookedAudio, HookPointWorldPosition);
			}
		}

		public void CrackHookedWhip(PhotonPlayer crackingPlayer, Vector3 crackGestureVelocity)
		{
			base.photonView.RpcAll(RpcCrackHookedWhip, crackingPlayer, crackGestureVelocity);
		}

		[PunRPC]
		protected void RpcCrackHookedWhip(PhotonPlayer crackingPlayer, Vector3 crackVelocity)
		{
			if (this.HookedWhipCracked != null)
			{
				this.HookedWhipCracked(this, crackingPlayer, crackVelocity, HookPointWorldPosition);
			}
			if (crackedAudio != null)
			{
				AudioManager.Play3DSFX(crackedAudio, HookPointWorldPosition);
			}
		}

		public void SetPhysical()
		{
			if ((object)rigidbodyEx != null)
			{
				rigidbodyEx.SetKinematic("WhipInteractableKinematic", addKinematic: false);
			}
			base.gameObject.ReplaceLayerRecursively(Layers.StaticPhysics, Layers.DynamicPhysics);
		}

		public void SetKinematic()
		{
			if ((object)rigidbodyEx != null)
			{
				rigidbodyEx.SetKinematic("WhipInteractableKinematic", addKinematic: true);
			}
		}

		public void Cleanup(float secondsBeforeCleanup)
		{
			SingletonMonoBehaviour<Scheduler>.Instance.InvokeInUpdate(secondsBeforeCleanup, base.MasterDisable);
		}
	}
	public class WhipInteractionSubscriber : UnityEngine.MonoBehaviour
	{
		[SerializeField]
