namespace RecRoom.Activities
{
	public class WhipPullable : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private Vector3 pullVelocityMultiplier = Vector3.one;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private WhipInteractable whipInteractable;

		private void Awake()
		{
			whipInteractable.HookedWhipCracked += OnWhipCrack;
			if (whipInteractable.RigidbodyEx == null)
			{
				UnityEngine.Debug.LogError($"{base.name} doesn't have a RigidbodyEx component. Pullables must have this component.");
			}
		}

		private void OnDestroy()
		{
			if (whipInteractable != null)
			{
				whipInteractable.HookedWhipCracked -= OnWhipCrack;
			}
		}

		private void OnWhipCrack(WhipInteractable interactable, PhotonPlayer crackingPlayer, Vector3 crackGestureVelocity, Vector3 hookingPoint)
		{
			if (whipInteractable.RigidbodyEx.isKinematic)
			{
				whipInteractable.SetPhysical();
			}
			if (whipInteractable.hasAuthority)
			{
				whipInteractable.RigidbodyEx.AddForceAtPosition(Vector3.Scale(crackGestureVelocity, pullVelocityMultiplier), hookingPoint, ForceMode.VelocityChange);
			}
		}
	}
