public class DrinkingFountain : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float turnOffWaterTime = 0.5f;

	[SerializeField]
	private CollisionForwarder triggerCollider;

	[Header("Audio & Visuals")]
	[SerializeField]
	private RecRoomAudioClip startAudioClip;

	[SerializeField]
	private RecRoomAudioClip loopAudioClip;

	[SerializeField]
	private RecRoomAudioClip endAudioClip;

	private ParticleSystem[] waterParticles;

	private float lastCollisionTime;

	private float lastCollisionStartTime;

	private bool sfxIsPlaying;

	private SFXAudioSource loopAudioSource;

	private void Awake()
	{
		waterParticles = GetComponentsInChildren<ParticleSystem>();
		if (triggerCollider != null)
		{
			triggerCollider.gameObject.layer = 10;
			triggerCollider.TriggerEnter += OnTriggerEnter;
			triggerCollider.TriggerStay += OnTriggerStay;
			triggerCollider.TriggerExit += OnTriggerExit;
		}
	}

	private void Update()
	{
		if (waterParticles != null)
		{
			float num = UnityEngine.Time.time - lastCollisionTime;
			float num2 = UnityEngine.Time.time - lastCollisionStartTime;
			ParticleSystem[] array = waterParticles;
			foreach (ParticleSystem particleSystem in array)
			{
				ParticleSystem.EmissionModule emission = particleSystem.emission;
				emission.enabled = num2 >= particleSystem.main.startDelay.constant && num < turnOffWaterTime;
			}
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand())
		{
			lastCollisionStartTime = UnityEngine.Time.time;
			if (startAudioClip != null && loopAudioClip != null && !sfxIsPlaying)
			{
				AudioManager.Play3DSFX(startAudioClip, base.transform);
				loopAudioSource = AudioManager.StartLooping3DSFX(loopAudioClip, base.transform);
				sfxIsPlaying = true;
			}
		}
	}

	private void OnTriggerStay(Collider collider)
	{
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand())
		{
			lastCollisionTime = UnityEngine.Time.time;
		}
	}

	private void OnTriggerExit(Collider collider)
	{
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && bodyPart.IsHand() && loopAudioSource != null && endAudioClip != null && sfxIsPlaying)
		{
			loopAudioSource.Stop();
			AudioManager.Play3DSFX(endAudioClip, base.transform);
			sfxIsPlaying = false;
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class Bow : RangedWeapon
	{
		[Header("Charging")]
		[SerializeField]
		private float maxDrawLength = 0.7f;

		[SerializeField]
		private AnimationCurve arrowChargeOverDrawLengthCurve;

		[SerializeField]
		private Transform rightHandedArrowShelfTransform;

		[SerializeField]
		private Transform leftHandedArrowShelfTransform;

		[SerializeField]
		private float minChargeArrowSpeed = 3f;

		[Header("Audio and Visuals")]
		[SerializeField]
		private RecRoomAudioClip limbCreakAudioClip;

		[SerializeField]
		private AnimationCurve pitchShiftCurve;

		[SerializeField]
		private float limbFeedbackDistanceInterval = 0.01f;

		[SerializeField]
		private RecRoomAudioClip arrowNockingAudioClip;

		[SerializeField]
		private Transform meshTransform;

		[NonSerialized]
		public bool FireArrowOnStringPickupRelease = true;

		private BowArrow readiedArrow;

		private float lastDrawLengthForFeedback;

		protected static readonly int ANIMATION_DRAW_ID = Animator.StringToHash("Pull");

		public BowString BowString { get; set; }

		public OffsetRotationRigidbodyPickup OffsetRotationRigidbodyPickup { get; private set; }

		private Transform ArrowShelfTransform
		{
			get
			{
				Transform result = rightHandedArrowShelfTransform;
				if (base.Tool.HolderHand != null && base.Tool.HolderHand.Type == PlayerHand.HandType.Left)
				{
					result = leftHandedArrowShelfTransform;
				}
				return result;
			}
		}

		protected override bool HasTriggerAnimation => false;

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent += OnPostPickup;
				base.Tool.PostReleaseEvent += OnPostRelease;
			}
		}

		protected override void Start()
		{
			base.Start();
			if (BowString == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing a bow string child.");
			}
			OffsetRotationRigidbodyPickup = base.Tool.RigidbodyPickup as OffsetRotationRigidbodyPickup;
		}

		private void Update()
		{
			if (OffsetRotationRigidbodyPickup == null)
			{
				UnityEngine.Debug.LogError("OffsetRotationRigidbodyPickup is NULL");
			}
			if (BowString == null)
			{
				UnityEngine.Debug.LogError("BowString is NULL");
			}
			else if (BowString.RetractableRigidbodyPickup == null)
			{
				UnityEngine.Debug.LogError("BowString.RetractableRigidbodyPickup is NULL");
			}
			else if (BowString.RetractableRigidbodyPickup.RestTransform == null)
			{
				UnityEngine.Debug.LogError("BowString.RetractableRigidbodyPickup.RestTransform is NULL");
			}
			if (readiedArrow == null && !BowString.RetractableRigidbodyPickup.InterpolatingToRest)
			{
				BowString.transform.position = BowString.RetractableRigidbodyPickup.RestTransform.position;
				BowString.transform.rotation = BowString.RetractableRigidbodyPickup.RestTransform.rotation;
			}
			if (base.Tool.IsHeldByPlayer)
			{
				OffsetRotationRigidbodyPickup.usingOffsetRotation = readiedArrow != null;
				if (readiedArrow != null && base.Tool.HolderHand != null)
				{
					readiedArrow.transform.position = BowString.transform.position;
					readiedArrow.transform.LookAt(ArrowShelfTransform, Vector3.up);
					Vector3 vector = Vector3.Cross(readiedArrow.transform.forward, base.Tool.HolderHand.PalmDirection);
					OffsetRotationRigidbodyPickup.rotationUpVector = ((base.Tool.HolderHand.Type != PlayerHand.HandType.Left) ? (-vector) : vector);
				}
				float magnitude = (BowString.RetractableRigidbodyPickup.RestTransform.position - BowString.transform.position).magnitude;
				float num = Mathf.InverseLerp(0f, maxDrawLength, magnitude);
				if (BowString.Tool.IsHeld && Mathf.Abs(lastDrawLengthForFeedback - magnitude) >= limbFeedbackDistanceInterval && magnitude <= maxDrawLength)
				{
					lastDrawLengthForFeedback = magnitude;
					PlayLimbFeedbackEffects(num);
				}
				base.Animator.Play(ANIMATION_DRAW_ID, 0, num);
			}
		}

		protected override void OnDestroy()
		{
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= OnPostPickup;
				base.Tool.PostReleaseEvent -= OnPostRelease;
				if (base.Tool.HolderPlayer != null && base.Tool.HolderPlayer == Player.LocalPlayer)
				{
					base.Tool.HolderPlayer.Backpack.RemoveDisableFavoriteToolSelection(this);
				}
			}
			base.OnDestroy();
		}

		private void OnPostPickup(Tool tool)
		{
			if (tool.HolderHand != null)
			{
				MirrorMesh(tool.HolderHand.Type == PlayerHand.HandType.Right);
				if (tool.HolderPlayer == Player.LocalPlayer)
				{
					tool.HolderPlayer.Backpack.AddDisableFavoriteToolSelection(this);
				}
			}
		}

		private void OnPostRelease(Tool tool)
		{
			base.Animator.Play(ANIMATION_DRAW_ID, 0, 0f);
			if (readiedArrow != null)
			{
				readiedArrow.Release(Vector3.zero);
			}
			if (BowString.Tool.IsHeld && tool.HolderPlayer == BowString.Tool.Owner && BowString.Tool.Owner.isLocal)
			{
				BowString.Tool.HolderInfo = ToolHolderInfo.NotHeld;
				BowString.transform.position = BowString.RetractableRigidbodyPickup.RestTransform.position;
				BowString.transform.rotation = BowString.RetractableRigidbodyPickup.RestTransform.rotation;
			}
			if (tool.HolderPlayer == Player.LocalPlayer)
			{
				tool.HolderPlayer.Backpack.RemoveDisableFavoriteToolSelection(this);
			}
		}

		public void ReadyArrow()
		{
			if (readiedArrow == null)
			{
				if (base.IsOnCooldown || !base.HasEnoughMagazineAmmunition)
				{
					return;
				}
				readiedArrow = AcquireBullet() as BowArrow;
				if (readiedArrow != null)
				{
					if (arrowNockingAudioClip != null)
					{
						AudioManager.Play3DSFX(arrowNockingAudioClip, BowString.transform);
					}
					readiedArrow.transform.localScale = Vector3.one;
					readiedArrow.transform.position = BowString.transform.position;
					readiedArrow.transform.rotation = BowString.transform.rotation;
				}
			}
			else
			{
				BowString.Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
		}

		public void AuthorityFireArrowAtPoint(Vector3 targetPoint, float normalizedCharge)
		{
			if (base.hasAuthority && base.Tool.IsHeld && readiedArrow != null)
			{
				Vector3 normalized = (targetPoint - readiedArrow.transform.position).normalized;
				AuthorityFireArrowInDirection(normalized, normalizedCharge);
			}
		}

		private void AuthorityFireArrowInDirection(Vector3 direction, float normalizedCharge)
		{
			if (base.hasAuthority && base.Tool.IsHeld && readiedArrow != null)
			{
				normalizedCharge = Mathf.Clamp01(normalizedCharge);
				float num = Mathf.Lerp(minChargeArrowSpeed, bulletFireSpeed, normalizedCharge);
				Vector3 velocity = direction * num;
				Fire(velocity, normalizedCharge);
			}
		}

		public void OnStringPickup()
		{
			if (FireArrowOnStringPickupRelease)
			{
				ReadyArrow();
			}
		}

		public void OnStringRelease()
		{
			if (FireArrowOnStringPickupRelease && base.hasAuthority && base.Tool.IsHeld && readiedArrow != null)
			{
				float magnitude = (base.Tool.RigidbodyEx.targetPosition - BowString.Tool.RigidbodyEx.targetPosition).magnitude;
				float time = Mathf.InverseLerp(0f, maxDrawLength, magnitude);
				float normalizedCharge = arrowChargeOverDrawLengthCurve.Evaluate(time);
				AuthorityFireArrowInDirection(readiedArrow.transform.forward, normalizedCharge);
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			if (readiedArrow != null)
			{
				base.FireShot(readiedArrow.transform.position, readiedArrow.transform.rotation, readiedArrow.transform.forward, chargeAmount, isMisfire, shotId);
				FireBullet(readiedArrow.transform.position, readiedArrow.transform.rotation, velocity, chargeAmount, shotId);
				if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal)
				{
					float intensity = 0.5f + 0.5f * chargeAmount;
					base.Tool.HolderHand.Vibrate(20, intensity);
				}
			}
		}

		protected override void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			if (readiedArrow != null)
			{
				readiedArrow.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, shotId);
				readiedArrow = null;
			}
		}

		private void PlayLimbFeedbackEffects(float drawLengthT)
		{
			if (limbCreakAudioClip != null)
			{
				limbCreakAudioClip.pitchShift = pitchShiftCurve.Evaluate(drawLengthT);
				AudioManager.Play3DSFX(limbCreakAudioClip, base.transform);
			}
			if (!(base.Tool.Owner != null) || !base.Tool.Owner.isLocal)
			{
				return;
			}
			foreach (PlayerHand bothHand in base.Tool.Owner.BothHands)
			{
				bothHand.Vibrate(20, 0.5f);
			}
		}

		private void MirrorMesh(bool mirror)
		{
			if (meshTransform != null)
			{
				Vector3 localScale = meshTransform.localScale;
				localScale.z = Mathf.Abs(localScale.z) * ((!mirror) ? 1f : (-1f));
				meshTransform.localScale = localScale;
			}
		}
	}
	public class BowArrow : Bullet
	{
		[SerializeField]
		private Transform colliderOriginTransform;

		private Transform targetParent;

		private Quaternion targetLocalRotation = Quaternion.identity;

		private Vector3 targetLocalPosition = Vector3.zero;

		private bool targetParentIsEnemy;

		private bool targetParentIsPlayer;

		private Coroutine delayedReleaseCoroutine;

		protected override Vector3 ColliderOrigin => (!(colliderOriginTransform != null)) ? base.transform.position : colliderOriginTransform.position;

		protected bool Active { get; set; }

		protected override void Awake()
		{
			base.Awake();
			Active = true;
		}

		protected override void FixedUpdate()
		{
			if (Active)
			{
				base.FixedUpdate();
			}
			else if (targetParent != null)
			{
				base.transform.position = targetParent.TransformPoint(targetLocalPosition);
				base.transform.rotation = targetParent.TransformRotation(targetLocalRotation);
				if (!targetParent.gameObject.activeSelf || (targetParentIsEnemy && (base.HitEnemy == null || base.HitEnemy.RigidbodyEx.isKinematic)))
				{
					ImmediateReleaseBullet();
				}
			}
			else
			{
				ImmediateReleaseBullet();
			}
		}

		protected override void OnRaycastCollisionEnter(WeaponRaycastHit raycastCollision)
		{
			base.OnRaycastCollisionEnter(raycastCollision);
			if (hitGameObject != null)
			{
				targetParent = hitGameObject.transform;
				targetParentIsEnemy = base.HitEnemy != null;
				targetParentIsPlayer = base.HitPlayer != null;
				if (targetParentIsPlayer)
				{
					Player.PlayerSpawnEvent += new Action<Player>(OnPlayerSpawned);
				}
				Quaternion rotation = Quaternion.LookRotation(base.transform.forward, Vector3.up);
				targetLocalRotation = targetParent.InverseTransformRotation(rotation);
				targetLocalPosition = targetParent.InverseTransformPoint(raycastCollision.Point + (base.transform.position - ColliderOrigin));
				Vector3 one = Vector3.one;
				Vector3 lossyScale = base.transform.lossyScale;
				if (lossyScale != one)
				{
					Vector3 b = new Vector3(base.transform.localScale.x / lossyScale.x, base.transform.localScale.y / lossyScale.y, base.transform.localScale.z / lossyScale.z);
					base.transform.localScale = Vector3.Scale(one, b);
				}
				if (trail != null)
				{
					trail.Stop();
				}
			}
		}

		public override void Release(Vector3 finalPosition)
		{
			Active = false;
			RaiseDestroyedEvent();
			if (base.enabled)
			{
				delayedReleaseCoroutine = StartCoroutine(WaitForArrowLifetimeCoroutine());
			}
		}

		public void ImmediateReleaseBullet()
		{
			if (delayedReleaseCoroutine != null)
			{
				StopCoroutine(delayedReleaseCoroutine);
			}
			ResetArrowParams();
			ObjectPool.Instance.Release(this);
		}

		private IEnumerator WaitForArrowLifetimeCoroutine()
		{
			float timeToWait = lifetime - (UnityEngine.Time.time - fireTime);
			if (timeToWait > 0f)
			{
				yield return new WaitForSeconds(timeToWait);
			}
			ResetArrowParams();
			ObjectPool.Instance.Release(this);
		}

		public void ResetArrowParams()
		{
			if (targetParentIsPlayer)
			{
				Player.PlayerSpawnEvent -= new Action<Player>(OnPlayerSpawned);
			}
			base.enabled = false;
			if (trail != null)
			{
				trail.enabled = false;
			}
			Active = true;
			targetParent = null;
			targetLocalRotation = Quaternion.identity;
			targetLocalPosition = Vector3.zero;
			targetParentIsEnemy = false;
			targetParentIsPlayer = false;
		}

		private void OnPlayerSpawned(Player player)
		{
			if (targetParentIsPlayer && player == base.HitPlayer)
			{
				ImmediateReleaseBullet();
			}
		}
	}
}
public class BowString : WeaponAccessory
{
	[NonSerialized]
	public Bow Bow;

	private Collider toolCollider;

	public RetractableRigidbodyPickup RetractableRigidbodyPickup { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		toolCollider = GetComponentInChildren<Collider>();
		if (toolCollider == null)
		{
			UnityEngine.Debug.LogError($"BowString '{base.name}' expected to contain a collider");
		}
		Bow = parentWeapon as Bow;
		if (Bow == null)
		{
			UnityEngine.Debug.LogError(base.name + " is not parented to a bow weapon.");
		}
		Bow.BowString = this;
		if (base.Tool != null)
		{
			base.Tool.IgnorePickupDirection = true;
			base.Tool.AlwaysPhysicalPickupOffCenter = false;
		}
	}

	protected override void Start()
	{
		base.Start();
		if (base.Tool != null)
		{
			RetractableRigidbodyPickup = base.Tool.RigidbodyPickup as RetractableRigidbodyPickup;
			base.Tool.PostPickupEvent += OnPostPickup;
			base.Tool.PostReleaseEvent += OnPostRelease;
		}
		if (RetractableRigidbodyPickup != null)
		{
			RetractableRigidbodyPickup.ReachedRestPoint += OnRetractableRigidbodyPickupReachedRestPoint;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (base.Tool != null)
		{
			base.Tool.PostReleaseEvent -= OnPostRelease;
		}
		if (RetractableRigidbodyPickup != null)
		{
			RetractableRigidbodyPickup.ReachedRestPoint -= OnRetractableRigidbodyPickupReachedRestPoint;
		}
	}

	private void FixedUpdate()
	{
		if (Bow != null && RetractableRigidbodyPickup != null)
		{
			RetractableRigidbodyPickup.sphericalRestrictionCenter = Bow.Tool.RigidbodyEx.targetPosition;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		Bow.OnStringPickup();
	}

	private void OnPostRelease(Tool tool)
	{
		if (RetractableRigidbodyPickup != null)
		{
			toolCollider.enabled = false;
			Bow.OnStringRelease();
			RetractableRigidbodyPickup.Retract();
		}
	}

	private void OnRetractableRigidbodyPickupReachedRestPoint()
	{
		toolCollider.enabled = true;
	}
}
