namespace RecRoom.Tools.Weapons
{
	public class Crossbow : RangedWeapon
	{
		[Header("Crossbow")]
		[SerializeField]
		private FloatValueCurve speedOverDrawTime;

		[SerializeField]
		private Transform boltNockingTransform;

		[SerializeField]
		private Transform maxPullTransform;

		[SerializeField]
		private float pullingHapticFrequency = 5f;

		private static readonly int drawId = Animator.StringToHash("Pull");

		private CrossbowBolt chargingBolt;

		private float chargeStartTime;

		private float nextVibrateTime;

		private float maxDrawDistance;

		private bool playedFullChargeFeedback;

		private Vector3 initialNockingPointLocalPosition = Vector3.zero;

		private Vector3 localMaxDrawPosition = Vector3.zero;

		protected override void Awake()
		{
			base.Awake();
			if (boltNockingTransform != null && maxPullTransform != null)
			{
				initialNockingPointLocalPosition = boltNockingTransform.localPosition;
				localMaxDrawPosition = maxPullTransform.localPosition;
				maxDrawDistance = (maxPullTransform.position - boltNockingTransform.position).magnitude;
			}
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent += OnInputDown;
				base.Tool.InputPressedEvent += OnInputPressed;
				base.Tool.InputUpEvent += OnInputUp;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent -= OnInputDown;
				base.Tool.InputPressedEvent -= OnInputPressed;
				base.Tool.InputUpEvent -= OnInputUp;
			}
		}

		private void FixedUpdate()
		{
			if (chargingBolt != null)
			{
				boltNockingTransform.localPosition = initialNockingPointLocalPosition + (localMaxDrawPosition - initialNockingPointLocalPosition) / maxDrawDistance * Mathf.Min(maxDrawDistance, maxDrawDistance * (UnityEngine.Time.time - chargeStartTime) / speedOverDrawTime.Duration);
				chargingBolt.transform.position = boltNockingTransform.position;
				chargingBolt.transform.rotation = boltNockingTransform.rotation;
			}
			else
			{
				boltNockingTransform.localPosition = initialNockingPointLocalPosition;
			}
		}

		private void Update()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (base.Tool.IsHeldByPlayer)
			{
				float num = UnityEngine.Time.time - chargeStartTime;
				bool flag = num >= speedOverDrawTime.Duration;
				if (chargingBolt != null)
				{
					base.Animator.SetFloat(drawId, Mathf.Min(1f, num / speedOverDrawTime.Duration));
					if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal && UnityEngine.Time.time >= nextVibrateTime && !flag)
					{
						nextVibrateTime += 1f / pullingHapticFrequency;
						PlayHaptics();
					}
				}
				else
				{
					base.Animator.SetFloat(drawId, 0f);
				}
				if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal && chargingBolt != null && !playedFullChargeFeedback && flag)
				{
					PlayHaptics();
					playedFullChargeFeedback = true;
				}
			}
			else if (chargingBolt != null)
			{
				Fire(0f);
			}
		}

		private void PlayHaptics(int millis = 1, float intensity = 0.1f)
		{
			base.Tool.HolderHand.Vibrate(millis, intensity);
		}

		private void OnInputDown(Tool thisTool)
		{
			if (base.hasAuthority && !TryStartCharge())
			{
				base.WeaponAudio.OnMisfire();
			}
		}

		private void OnInputPressed(Tool thisTool)
		{
			if (base.hasAuthority && chargingBolt == null)
			{
				TryStartCharge();
			}
		}

		private void OnInputUp(Tool thisTool)
		{
			if (base.hasAuthority && chargingBolt != null)
			{
				float chargeAmount = Mathf.InverseLerp(chargeStartTime, chargeStartTime + speedOverDrawTime.Duration, UnityEngine.Time.time);
				Fire(chargeAmount);
			}
		}

		private bool TryStartCharge()
		{
			bool result = false;
			if (base.hasAuthority && chargingBolt == null)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (!base.IsMisfire && !base.IsOnCooldown)
				{
					base.photonView.RpcAll(RpcStartChargingBolt);
					result = true;
				}
			}
			return result;
		}

		[PunRPC]
		protected void RpcStartChargingBolt()
		{
			chargeStartTime = UnityEngine.Time.time;
			nextVibrateTime = 0f;
			chargingBolt = AcquireBullet() as CrossbowBolt;
			chargingBolt.transform.position = boltNockingTransform.position;
			chargingBolt.transform.rotation = boltNockingTransform.rotation;
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (chargingBolt != null)
			{
				Vector3 velocity2 = velocity.normalized * speedOverDrawTime.Evaluate(chargeAmount);
				if (isMisfire)
				{
					FireBullet(position, rotation, velocity2, chargeAmount, 0f, shotId);
				}
				else
				{
					FireBullet(position, rotation, velocity2, chargeAmount, shotId);
				}
				if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal)
				{
					float intensity = Mathf.Lerp(0.5f, 1f, chargeAmount);
					PlayHaptics(20, intensity);
				}
				playedFullChargeFeedback = false;
			}
		}

		protected override void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			if (chargingBolt != null)
			{
				if (chargingBolt.maxChargedParticleTrail != null && chargeAmount >= 0.99f)
				{
					chargingBolt.maxChargedParticleTrail.Play();
				}
				chargingBolt.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, shotId);
			}
			chargingBolt = null;
		}

		protected override Bullet FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, float maxLifetime, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			if (chargingBolt != null)
			{
				if (chargingBolt.maxChargedParticleTrail != null && chargeAmount >= 0.99f)
				{
					chargingBolt.maxChargedParticleTrail.Play();
				}
				chargingBolt.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, maxLifetime, shotId);
			}
			CrossbowBolt result = chargingBolt;
			chargingBolt = null;
			return result;
		}
	}
	public class CrossbowBolt : BowArrow
	{
		public ParticleSystem maxChargedParticleTrail;

		protected override void OnRaycastCollisionEnter(WeaponRaycastHit raycastCollision)
		{
			base.OnRaycastCollisionEnter(raycastCollision);
			if (hitGameObject != null && maxChargedParticleTrail != null && maxChargedParticleTrail.isPlaying)
			{
				maxChargedParticleTrail.Stop();
			}
		}
	}
}
public class OffsetRotationRigidbodyPickup : RigidbodyPickup
{
	[Header("Offset")]
	public bool usingOffsetRotation;

	public Transform rotationHandleTransform;

	public Vector3 rotationUpVector = Vector3.zero;

	public override Quaternion TargetRotation
	{
		get
		{
			if (rotationHandleTransform == null || !usingOffsetRotation)
			{
				return base.TargetRotation;
			}
			if (rotationUpVector == Vector3.zero)
			{
				return Quaternion.LookRotation(base.transform.position - rotationHandleTransform.position);
			}
			return Quaternion.LookRotation(base.transform.position - rotationHandleTransform.position, rotationUpVector);
		}
	}
}
namespace RecRoom.Activities.Quest.RecRoom.Activities.Quest
{
	public class EnemyRopes : UnityEngine.MonoBehaviour
	{
		private enum RopeLifetime
		{
			WHILE_SPAWNING,
			WHILE_ALIVE,
			ALWAYS
		}

		[Serializable]
		public struct Rope
		{
			public Transform Root;

			public bool InvertY;
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Enemy enemy;

		[Header("Configuration")]
		[SerializeField]
		public Rope[] allRopes;

		[SerializeField]
		private RopeLifetime ropeLifetime = RopeLifetime.WHILE_ALIVE;

		[Header("Feedback")]
		[SerializeField]
		private RecRoomAudioClip onRopeSpawnAudio;

		[SerializeField]
		private RecRoomAudioClip onRopeRetractAudio;

		private const float RETRACT_DURATION = 2f;

		private const float RETRACT_SPEED = 3f;

		private bool spawnedFromAbove = true;

		private bool isRetracting;

		private float retractEndTime;

		private Vector3[] retractInitialPositions;

		private void Awake()
		{
			if (enemy == null)
			{
				UnityEngine.Debug.LogError(base.name + " enemy ropes does not have an Enemy reference.");
			}
			if (allRopes == null || allRopes.Length == 0)
			{
				UnityEngine.Debug.LogWarning(base.name + " enemy ropes has zero rope references.");
			}
			isRetracting = false;
			retractEndTime = 0f;
			retractInitialPositions = new Vector3[allRopes.Length];
			bool flag = ropeLifetime != RopeLifetime.WHILE_SPAWNING;
			for (int i = 0; i < allRopes.Length; i++)
			{
				EnableRope(allRopes[i].Root.gameObject, flag);
			}
			enemy.SpawnStartEvent += OnEnemySpawnStart;
			enemy.SpawnEndEvent += OnEnemySpawnEnd;
			enemy.DeathEvent += OnEnemyDeath;
		}

		private void OnEnemySpawnStart(Enemy enemy)
		{
			Vector3 vector = enemy.SpawnTargetPosition - enemy.InstantiationPosition;
			Vector3 vector2 = Vector3.Project(vector, Vector3.up);
			Vector3 vector3 = vector - vector2;
			spawnedFromAbove = vector2.sqrMagnitude >= 1f && vector3.sqrMagnitude < 0.1f;
			if (!spawnedFromAbove)
			{
				return;
			}
			if (!enemy.SpawnOnPatrol)
			{
				AudioManager.Play3DSFX(onRopeSpawnAudio, base.transform);
			}
			if (ropeLifetime == RopeLifetime.WHILE_SPAWNING && allRopes != null)
			{
				for (int i = 0; i < allRopes.Length; i++)
				{
					EnableRope(allRopes[i].Root.gameObject, enabled: true);
				}
			}
		}

		private void OnEnemySpawnEnd(Enemy enemy)
		{
			if (spawnedFromAbove && ropeLifetime == RopeLifetime.WHILE_SPAWNING)
			{
				Retract();
			}
		}

		private void OnEnemyDeath(Enemy enemy)
		{
			if (ropeLifetime == RopeLifetime.WHILE_ALIVE)
			{
				Retract();
			}
		}

		private void LateUpdate()
		{
			if (allRopes == null || allRopes.Length == 0)
			{
				base.enabled = false;
			}
			UpdateBillboarding();
			UpdateRetract();
		}

		private void Retract()
		{
			AudioManager.Play3DSFX(onRopeRetractAudio, base.transform);
			isRetracting = true;
			retractEndTime = UnityEngine.Time.time + 2f;
			if (allRopes != null)
			{
				for (int i = 0; i < allRopes.Length; i++)
				{
					ref Vector3 reference = ref retractInitialPositions[i];
					reference = allRopes[i].Root.transform.position;
				}
			}
		}

		private void UpdateBillboarding()
		{
			if (!(SingletonMonoBehaviour<CameraRig>.Instance != null) || !(SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera != null))
			{
				return;
			}
			Vector3 vector = -SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
			vector = ((!(Vector3.Dot(vector, Vector3.up) >= 1f - Mathf.Epsilon)) ? Vector3.ProjectOnPlane(vector, Vector3.up).normalized : Vector3.forward);
			for (int i = 0; i < allRopes.Length; i++)
			{
				Vector3 up = Vector3.up;
				if (allRopes[i].InvertY)
				{
					up *= -1f;
				}
				allRopes[i].Root.transform.rotation = Quaternion.LookRotation(vector, up);
			}
		}

		private void UpdateRetract()
		{
			if (!isRetracting)
			{
				return;
			}
			bool flag = UnityEngine.Time.time >= retractEndTime;
			if (flag)
			{
				base.enabled = false;
			}
			for (int i = 0; i < allRopes.Length; i++)
			{
				retractInitialPositions[i] += Vector3.up * UnityEngine.Time.deltaTime * 3f;
				allRopes[i].Root.transform.position = retractInitialPositions[i];
				if (flag)
				{
					EnableRope(allRopes[i].Root.gameObject, enabled: false);
				}
			}
		}

		private void EnableRope(GameObject rope, bool enabled)
		{
			Vector3 localScale = rope.transform.localScale;
			localScale.x = ((!enabled) ? 0f : 1f);
			rope.transform.localScale = localScale;
			rope.SetActive(enabled);
		}
	}
}
public class QuestBoulderTrap : Trap
{
	[Header("Boulder")]
	[SerializeField]
	private float maxSpeed = 15f;

	[SerializeField]
	private float fullRollingSpeedForAudio = 1f;

	[SerializeField]
	private RecRoomAudioClip rollingAudioClip;

	private bool collidedThisFrame;

	private Vector3 previousVelocity = Vector3.zero;

	private Vector3 previousAngularVelocity = Vector3.zero;

	private SFXAudioSource rollingAudioSource;

	protected override void OnIsEnabledChange()
	{
		base.OnIsEnabledChange();
		if (base.IsEnabled)
		{
			previousVelocity = Vector3.zero;
			previousAngularVelocity = Vector3.zero;
			StartRollingAudio();
		}
		else
		{
			StopRollingAudio();
		}
	}

	private void Update()
	{
		if (rollingAudioSource != null)
		{
			float magnitude = rigidbodyEx.velocity.magnitude;
			rollingAudioSource.AudioSource.volume = rollingAudioClip.volume * Mathf.Clamp01(Mathf.Lerp(0f, 1f, magnitude / fullRollingSpeedForAudio));
		}
	}

	private void FixedUpdate()
	{
		if (!collidedThisFrame)
		{
			previousVelocity = rigidbodyEx.velocity;
			previousAngularVelocity = rigidbodyEx.angularVelocity;
		}
		else
		{
			rigidbodyEx.velocity = previousVelocity;
			rigidbodyEx.angularVelocity = previousAngularVelocity;
			collidedThisFrame = false;
		}
		if (rigidbodyEx.velocity.sqrMagnitude >= maxSpeed * maxSpeed)
		{
			rigidbodyEx.velocity = Vector3.ClampMagnitude(rigidbodyEx.velocity, maxSpeed);
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (collision.contacts.Length == 0)
		{
			return;
		}
		WeaponImpact impact = new WeaponImpact
		{
			Velocity = previousVelocity,
			Force = previousVelocity / UnityEngine.Time.fixedDeltaTime * rigidbodyEx.mass,
			Point = collision.contacts[0].point,
			Distance = 0f,
			SurfaceNormal = collision.contacts[0].normal,
			GameObject = collision.gameObject
		};
		Tool colliderTool = collision.GetColliderTool();
		if (colliderTool != null)
		{
			collidedThisFrame = true;
			if (colliderTool.IsHeld && colliderTool.Owner.isLocal && !base.hasAuthority)
			{
				base.photonView.TransferOwnership(colliderTool.Owner.PhotonPlayer);
			}
			ToolHit(colliderTool, impact);
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			collidedThisFrame = true;
			if (colliderPlayer.isLocal && !base.hasAuthority)
			{
				base.photonView.TransferOwnership(colliderPlayer.PhotonPlayer);
			}
			return;
		}
		EnemyArmorType hitEnemyArmorType;
		Enemy colliderEnemy = collision.GetColliderEnemy(out hitEnemyArmorType);
		if (colliderEnemy != null)
		{
			collidedThisFrame = true;
			EnemyHit(colliderEnemy, hitEnemyArmorType, WeaponDamageType.MELEE, impact);
		}
	}

	private void StartRollingAudio()
	{
		StopRollingAudio();
		rollingAudioSource = AudioManager.StartLooping3DSFX(rollingAudioClip, base.transform);
	}

	private void StopRollingAudio()
	{
		if (rollingAudioSource != null)
		{
			rollingAudioSource.Stop();
			rollingAudioSource = null;
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestGoblinRangedEnemy : Enemy
	{
		private enum CombatState
		{
			FIND_TARGET = 0,
			CHARGE_ATTACK = 1,
			ATTACK_TARGET = 2,
			POST_ATTACK = 3,
			DASH = 4,
			INVALID = 65535
		}

		private enum AttackTarget
		{
			PLAYER_HEAD,
			PLAYER_FEET
		}

		[Header("Target Selection")]
		[SerializeField]
		private bool pathTowardsPlayerCentroidToFindTarget = true;

		[SerializeField]
		private bool updateTargetPositionWhileAttacking = true;

		[Header("Attack Charge")]
		[SerializeField]
		private float attackChargeDuration = 1f;

		[Header("Attack")]
		[SerializeField]
		private float attackDuration = 3f;

		[SerializeField]
		private AttackTarget attackTarget;

		[SerializeField]
		private bool canTargetLastVisiblePlayerPosition;

		[SerializeField]
		private float animationShotDelay;

		[Header("Post Attack")]
		[SerializeField]
		private bool supportsPostAttack;

		[SerializeField]
		private float postAttackDuration;

		[Header("Dash")]
		[SerializeField]
		private float dashSpeed = 4f;

		[SerializeField]
		[FormerlySerializedAs("maxDashForce")]
		private float maxHorizontalDashForce = 67f;

		[SerializeField]
		private float maxVerticalDashForce = 67f;

		[SerializeField]
		private float dashSlowdownDistance = 1f;

		[SerializeField]
		private float minDashDistance = 2f;

		[SerializeField]
		private float maxDashDistance = 4f;

		[SerializeField]
		private float dashTimeout = 2.5f;

		private SynchronizedField<Vector3> _attackOrigin;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private Vector3 lastUpdatedAttackTargetPosition = Vector3.zero;

		private Vector3 AttackOrigin
		{
			get
			{
				return _attackOrigin.Get();
			}
			set
			{
				_attackOrigin.Set(value);
			}
		}

		private bool PitchWhileLooking => base.Steering.IsHovering && !neverPitchWhileLooking;

		protected override void Awake()
		{
			base.Awake();
			cachesLatestVisibleTargetPosition = canTargetLastVisiblePlayerPosition;
			enemyAudio.MovingSoundVolumeDrivenBySteeringSpeed = !base.Steering.IsHovering;
			_attackOrigin = new SynchronizedField<Vector3>(this, "AO", Vector3.zero, SetterPermissionMode.AUTHORITY);
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterFindTargetState, OnExitFindTargetState, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
			behaviorStateMachine.AddState(2, OnEnterAttackTargetState, null, OnUpdateAttackTargetState);
			behaviorStateMachine.AddState(3, OnEnterPostAttackState, OnExitPostAttackState, OnUpdatePostAttackState);
			behaviorStateMachine.AddState(4, OnEnterDashState, OnExitDashState, OnUpdateDashState);
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			if (trackTargetCount)
			{
				return FindLeastTargetedNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
			}
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopLooking();
			base.Steering.MaxHorizontalSpeed = movementSpeed;
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					behaviorStateMachine.EnterState(1);
				}
				else if (pathTowardsPlayerCentroidToFindTarget)
				{
					UpdateTargetCentroidPath(movementSlowdownDistance);
				}
				else
				{
					behaviorStateMachine.EnterState(4);
				}
			}
		}

		private void OnExitFindTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			if (base.hasAuthority)
			{
				AttackOrigin = base.Steering.HoverPosition;
			}
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			enemyAudio.OnChargeAttack();
			if ((object)enemyParticles != null)
			{
				enemyParticles.StartCharge(rangedWeapon.ProjectileOriginTransform);
			}
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid || behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(2);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(!PitchWhileLooking));
				}
			}
		}

		private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
			if ((object)enemyParticles != null)
			{
				enemyParticles.StopCharge();
			}
		}

		private void OnEnterAttackTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			TryGetLatestTargetAttackPoint(out lastUpdatedAttackTargetPosition);
			AttackTargetCombatant();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackTargetState()
		{
			if (base.hasAuthority && (!base.Target.IsValid || behaviorTimer.TimerOver))
			{
				if (supportsPostAttack)
				{
					behaviorStateMachine.EnterState(3);
				}
				else
				{
					behaviorStateMachine.EnterState(4);
				}
			}
			else
			{
				base.Steering.Look(GetAttackLookVector());
			}
		}

		private Vector3 GetAttackLookVector()
		{
			bool inXZPlane = !base.Steering.IsHovering;
			if (updateTargetPositionWhileAttacking)
			{
				return GetLookAtTargetVector(inXZPlane);
			}
			return GetLookAtVector(lastUpdatedAttackTargetPosition, inXZPlane);
		}

		private bool TryGetLatestTargetAttackPoint(out Vector3 targetPosition)
		{
			if (updateTargetPositionWhileAttacking || !base.Target.IsValid)
			{
				targetPosition = Vector3.zero;
				return false;
			}
			if (attackTarget == AttackTarget.PLAYER_HEAD)
			{
				targetPosition = ((!canTargetLastVisiblePlayerPosition) ? base.Target.HeadPosition : latestVisibleTargetHeadPosition);
			}
			else
			{
				targetPosition = ((!canTargetLastVisiblePlayerPosition) ? base.Target.FloorPosition : latestVisibleTargetFloorPosition);
			}
			return true;
		}

		private void AttackTargetCombatant()
		{
			if (!base.Target.IsValid)
			{
				return;
			}
			enemyAudio.OnAttack();
			if (base.hasAuthority)
			{
				if (!updateTargetPositionWhileAttacking)
				{
					AuthorityFireRangedWeaponAtExplicitTargetPosition(lastUpdatedAttackTargetPosition, animationShotDelay);
				}
				else if (attackTarget == AttackTarget.PLAYER_HEAD)
				{
					AuthorityFireRangedWeaponAtTarget(canTargetLastVisiblePlayerPosition, animationShotDelay);
				}
				else if (attackTarget == AttackTarget.PLAYER_FEET)
				{
					AuthorityFireRangedWeaponAtTargetFloor(canTargetLastVisiblePlayerPosition, animationShotDelay);
				}
			}
		}

		private void OnEnterPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.POST_ATTACK;
			enemyAudio.OnChargeAttack();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(postAttackDuration);
			}
		}

		private void OnUpdatePostAttackState()
		{
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid || behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(4);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(!PitchWhileLooking));
				}
			}
		}

		private void OnExitPostAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
		}

		private void OnEnterDashState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxHorizontalDashForce;
			base.Steering.MaxVerticalSpeed = dashSpeed;
			base.Steering.MaxVerticalSteeringForce = maxVerticalDashForce;
			if (base.hasAuthority)
			{
				base.Steering.Path(GetDashPosition(), dashSlowdownDistance, 0.025f * dashSpeed, faceVelocity: false);
				behaviorTimer.StartTimer(dashTimeout);
			}
		}

		private void OnUpdateDashState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver || !base.Steering.PathIsValid() || base.Steering.ReachedPathDestination)
				{
					behaviorStateMachine.EnterState(0);
				}
				else if (base.Target.IsValid && base.Steering.IsHovering)
				{
					base.Steering.Look(GetLookAtTargetVector(!PitchWhileLooking));
				}
			}
		}

		private void OnExitDashState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private Vector3 GetDashPosition()
		{
			Vector3 zero = Vector3.zero;
			Vector3 vector = Vector3.ProjectOnPlane(AttackOrigin - base.transform.position, Vector3.up);
			float magnitude = vector.magnitude;
			zero = ((!(magnitude >= maxDashDistance)) ? UnityEngine.Random.onUnitSphere : (vector / magnitude));
			float num = UnityEngine.Random.Range(minDashDistance, maxDashDistance);
			Enemy.TrySampleNavMesh(base.RigidbodyEx.physicsPosition + zero * num, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			if (interruptsCustomBehaviour && base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = true;
			}
		}

		protected override void OnStunEnd(bool interruptsCustomBehaviour)
		{
			base.OnStunEnd(interruptsCustomBehaviour);
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = false;
			}
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = true;
			}
		}
	}
	public class QuestKnightEnemy : Enemy
	{
		private enum AttackType
		{
			SPIN,
			CHARGE
		}

		private enum BehaviorState
		{
			FIND_TARGET = 0,
			FOLLOW_TARGET = 1,
			LOOK_AT_TARGET = 2,
			SLASH_ATTACK = 3,
			SPIN_ATTACK_PREPARE = 4,
			SPIN_ATTACK = 5,
			SPIN_ATTACK_STOP = 6,
			CHARGE_TARGET = 7,
			POST_ATTACK = 8,
			INVALID = 65535
		}

		[Header("Knight")]
		[SerializeField]
		private AttackType attackType;

		[Header("Target Selection")]
		[SerializeField]
		private float desiredTargetDistance = 1f;

		[SerializeField]
		private float minRandomTargetOffsetAngle = 15f;

		[SerializeField]
		private float maxRandomTargetOffsetAngle = 30f;

		[Header("Look At Target")]
		[SerializeField]
		private float lookAtTargetDuration = 0.5f;

		[SerializeField]
		private float lookAtTargetAngularSpeedDegrees = 360f;

		[Header("Attack")]
		[SerializeField]
		private float attackRange = 2.8f;

		[SerializeField]
		private float slashAttackDuration = 1.5f;

		[Header("Spin Prepare")]
		[SerializeField]
		private float spinPrepareAngularSpeed = 60f;

		[SerializeField]
		private float spinPrepareAngle = -30f;

		[SerializeField]
		private float spinPrepareSlowdownAngle = 20f;

		[Header("Spin")]
		[SerializeField]
		private float spinAngularSpeed = 360f;

		[SerializeField]
		private float spinAngle = 360f;

		[Header("Spin Stop")]
		[SerializeField]
		private float spinStopAngle = 60f;

		[SerializeField]
		private float spinStopSlowdownAngle = 50f;

		[Header("Post Attack")]
		[SerializeField]
		private float postAttackDuration = 2f;

		[Header("Charge Attack")]
		[SerializeField]
		private float chargeDistance = 8f;

		[SerializeField]
		private float chargeSpeed = 12f;

		[SerializeField]
		private float chargeMaxForce = 100f;

		[SerializeField]
		private ParticleSystem chargeParticles;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private SynchronizedField<Vector3> _spinStartDirection;

		private AnimationAttackTrigger animationAttackTrigger;

		private Vector3 SpinStartDirection
		{
			get
			{
				return _spinStartDirection.Get();
			}
			set
			{
				_spinStartDirection.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			animationAttackTrigger = GetComponentInChildren<AnimationAttackTrigger>(includeInactive: true);
			if (animationAttackTrigger == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing Animation Attack Trigger.");
			}
			else
			{
				animationAttackTrigger.MeleeAttackEnableEvent += OnMeleeAttackAnimationActive;
			}
			_spinStartDirection = new SynchronizedField<Vector3>(this, "SSD", Vector3.forward, SetterPermissionMode.AUTHORITY);
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, null, null, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
			behaviorStateMachine.AddState(2, OnEnterLookAtTargetState, OnExitLookAtTargetState, OnUpdateLookAtTargetState);
			behaviorStateMachine.AddState(3, OnEnterSlashAttackState, OnExitSlashAttackState, OnUpdateSlashAttackState);
			behaviorStateMachine.AddState(8, OnEnterPostAttackState, OnExitPostAttackState, OnUpdatePostAttackState);
			behaviorStateMachine.AddState(4, OnEnterSpinAttackPrepareState, OnExitSpinAttackPrepareState, OnUpdateSpinAttackPrepareState);
			behaviorStateMachine.AddState(5, OnEnterSpinAttackState, OnExitSpinAttackState, OnUpdateSpinAttackState);
			behaviorStateMachine.AddState(6, OnEnterSpinAttackStopState, OnExitSpinAttackStopState, OnUpdateSpinAttackStopState);
			behaviorStateMachine.AddState(7, OnEnterChargeTargetState, OnExitChargeTargetState, OnUpdateChargeTargetState);
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (animationAttackTrigger != null)
			{
				animationAttackTrigger.MeleeAttackEnableEvent -= OnMeleeAttackAnimationActive;
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		public override void AuthorityOnDamageApplyForce(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 force, Vector3 point)
		{
			force = Vector3.ProjectOnPlane(force, base.Steering.SurfaceNormal);
			base.AuthorityOnDamageApplyForce(damageType, armorType, force, point);
		}

		public override void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority)
			{
				velocity = Vector3.ProjectOnPlane(velocity, base.Steering.SurfaceNormal);
				base.AuthorityOnDamageChangeVelocity(damageType, armorType, velocity, angularVelocity);
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			if (isPatrolling)
			{
				return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
			}
			float distanceToClosestTargetSqr;
			return SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					behaviorStateMachine.EnterState(2);
				}
			}
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
		}

		protected virtual void OnUpdateFollowTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out var distanceToClosestTargetSqr).IsValid && distanceToClosestTargetSqr <= attackRange * attackRange)
			{
				behaviorStateMachine.EnterState(3);
				return;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				behaviorStateMachine.EnterState(0);
				return;
			}
			if (LastAttackerIsValidTarget())
			{
				base.Target = base.LastAttacker;
				base.LastAttacker = Combatant.Invalid;
			}
			Vector3 floorPosition = base.Target.FloorPosition;
			if (!base.Steering.PathIsValid(floorPosition, desiredTargetDistance * 1.1f))
			{
				floorPosition = GetRandomOffsetPosition(floorPosition, desiredTargetDistance, minRandomTargetOffsetAngle, maxRandomTargetOffsetAngle);
				base.Steering.Path(floorPosition);
			}
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopPathing();
		}

		private void OnEnterSlashAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.CHARGE;
			enemyAudio.OnChargeAttack();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(slashAttackDuration);
			}
		}

		private void OnUpdateSlashAttackState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				if (attackType == AttackType.SPIN)
				{
					behaviorStateMachine.EnterState(4);
				}
				else
				{
					behaviorStateMachine.EnterState(7);
				}
			}
		}

		private void OnExitSlashAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 4 && nextStateId != 7)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private void OnEnterSpinAttackPrepareState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			if (base.hasAuthority)
			{
				float maxRunningTime = Mathf.Abs(spinPrepareAngle) / spinPrepareAngularSpeed * 2f;
				behaviorTimer.StartTimer(maxRunningTime);
				Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				Vector3 normalized2 = (Quaternion.Euler(0f, spinPrepareAngle, 0f) * normalized).normalized;
				base.Steering.MaxAngularSpeed = spinPrepareAngularSpeed;
				base.Steering.Look(normalized2, spinPrepareSlowdownAngle);
			}
		}

		private void OnUpdateSpinAttackPrepareState()
		{
			if (base.hasAuthority && (behaviorTimer.TimerOver || base.Steering.ReachedLookTarget))
			{
				behaviorStateMachine.EnterState(5);
			}
		}

		private void OnExitSpinAttackPrepareState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 5)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private void OnEnterSpinAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			enemyAudio.OnAttack();
			base.Steering.StopAll();
			if (base.hasAuthority)
			{
				SpinStartDirection = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				base.Steering.MaxAngularSpeed = spinAngularSpeed;
				float maxRunningTime = Mathf.Abs(spinAngle) / spinAngularSpeed;
				behaviorTimer.StartTimer(maxRunningTime);
			}
		}

		private void OnUpdateSpinAttackState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(6);
					return;
				}
				float y = spinAngularSpeed * behaviorTimer.TimeElapsed;
				Vector3 normalized = (Quaternion.Euler(0f, y, 0f) * SpinStartDirection).normalized;
				base.Steering.Look(normalized);
			}
		}

		private void OnExitSpinAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 6)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private void OnEnterSpinAttackStopState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			if (base.hasAuthority)
			{
				float maxRunningTime = Mathf.Abs(spinStopAngle) / spinAngularSpeed * 2f;
				behaviorTimer.StartTimer(maxRunningTime);
				Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				Vector3 normalized2 = (Quaternion.Euler(0f, spinStopAngle, 0f) * normalized).normalized;
				base.Steering.MaxAngularSpeed = spinAngularSpeed;
				base.Steering.Look(normalized2, spinStopSlowdownAngle);
			}
		}

		private void OnUpdateSpinAttackStopState()
		{
			if (base.hasAuthority && (behaviorTimer.TimerOver || base.Steering.ReachedLookTarget))
			{
				behaviorStateMachine.EnterState(8);
			}
		}

		private void OnExitSpinAttackStopState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 8)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private void OnEnterPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.POST_ATTACK;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(postAttackDuration);
			}
		}

		private void OnUpdatePostAttackState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		private void OnExitPostAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
		}

		private void OnEnterChargeTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			enemyAudio.OnAttack();
			base.Steering.MaxHorizontalSteeringForce = chargeMaxForce;
			base.Steering.MaxHorizontalSpeed = chargeSpeed;
			if (base.hasAuthority)
			{
				base.Steering.Path(GetChargeTargetPosition());
				behaviorTimer.StartTimer(1.2f * chargeDistance / chargeSpeed);
			}
		}

		private void OnUpdateChargeTargetState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(8);
			}
		}

		private void OnExitChargeTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 8)
			{
				enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
			}
		}

		private Vector3 GetChargeTargetPosition()
		{
			Vector3 vector = ((!(lineOfSightOrigin != null)) ? base.RigidbodyEx.physicsPosition : lineOfSightOrigin.position);
			Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
			Vector3 vector2 = vector + normalized * chargeDistance;
			if (Enemy.TryGetRaycastHitPoint(vector, normalized, chargeDistance, out var distance, out var hitPoint, out var hitNormal))
			{
				vector2 = hitPoint;
			}
			if (Enemy.TryGetRaycastHitPoint(vector2, -Vector3.up, float.MaxValue, out distance, out hitPoint, out hitNormal))
			{
				vector2 = hitPoint;
			}
			Enemy.TrySampleNavMesh(vector2, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		private void OnEnterLookAtTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = lookAtTargetAngularSpeedDegrees;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(lookAtTargetDuration);
			}
		}

		private void OnUpdateLookAtTargetState()
		{
			if (base.hasAuthority)
			{
				if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(1);
				}
			}
		}

		private void OnExitLookAtTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopLooking();
		}

		protected override void OnInterruptedRecoveryStart()
		{
			base.OnInterruptedRecoveryStart();
			if (base.hasAuthority)
			{
				base.Steering.Look(Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized);
			}
		}

		protected override void OnInterruptedRecoveryEnd()
		{
			base.OnInterruptedRecoveryEnd();
			base.Steering.StopLooking();
		}

		private void OnMeleeAttackAnimationActive(bool active)
		{
			if (base.MeleeCombatActive == active)
			{
				return;
			}
			base.MeleeCombatActive = active;
			if (chargeParticles != null)
			{
				if (active)
				{
					chargeParticles.Play();
				}
				else
				{
					chargeParticles.Stop();
				}
			}
		}
	}
	public class QuestRotatingBossEnemy : Enemy
	{
		private enum BehaviorState
		{
			FIND_TARGET = 0,
			LOOK_AT_TARGET_RANGED = 1,
			CHARGE_RANGED_ATTACK = 2,
			RANGED_ATTACK = 3,
			MELEE_ATTACK = 4,
			LOOK_AT_TARGET_MELEE = 5,
			INVALID = 65535
		}

		[Header("Behavior Timing")]
		[SerializeField]
		private float lookAtTargetDuration = 0.5f;

		[SerializeField]
		private float attackChargeDuration = 1f;

		[SerializeField]
		private float attackDuration = 0.5f;

		[Header("Scanning")]
		[SerializeField]
		private float maxVisionConeAngle = 15f;

		[SerializeField]
		private float findTargetAngularSpeedDegrees = 30f;

		[SerializeField]
		private float findTargetSlowdownAngle = 10f;

		[SerializeField]
		private float lookAtTargetAngularSpeedDegrees = 360f;

		[SerializeField]
		private float randomLookDirectionMaximumAngle = 110f;

		[Header("Melee Attack")]
		[SerializeField]
		private float meleeRange = 2f;

		[SerializeField]
		private float meleeAttackDuration = 1.5f;

		private SynchronizedField<Vector3> _lookDirection;

		private Vector3 desiredSurfacePosition = Vector3.zero;

		private Vector3 initialForwardVector = Vector3.forward;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private Vector3 LookDirection
		{
			get
			{
				return _lookDirection.Get();
			}
			set
			{
				_lookDirection.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			desiredSurfacePosition = base.SpawnTargetPosition;
			initialForwardVector = base.transform.forward;
			_lookDirection = new SynchronizedField<Vector3>(this, "LOOK_DIR", Vector3.forward, SetterPermissionMode.AUTHORITY);
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.RigidbodyEx.useGravity = false;
			base.RigidbodyEx.constraints = RigidbodyConstraints.None;
			behaviorTimer = new SynchronizedTimer(this, "BEHAVIOR", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("BEHAVIOR", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterFindTargetState, null, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterLookAtTargetRangedState, null, OnUpdateLookAtTargetRangedState);
			behaviorStateMachine.AddState(2, OnEnterChargeRangedAttackState, OnExitChargeRangedAttackState, OnUpdateChargeRangedAttackState);
			behaviorStateMachine.AddState(3, OnEnterRangedAttackState, null, OnUpdateRangedAttackState);
			behaviorStateMachine.AddState(5, OnEnterLookAtTargetMeleeState, null, OnUpdateLookAtTargetMeleeState);
			behaviorStateMachine.AddState(4, OnEnterMeleeAttackState, null, OnUpdateMeleeAttackState);
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override void OnActiveCombatStart()
		{
			base.OnActiveCombatStart();
			base.RigidbodyEx.ClearVelocity();
		}

		protected override void OnActiveCombatUpdate()
		{
			base.OnActiveCombatUpdate();
			if (!base.hasAuthority)
			{
				return;
			}
			base.Steering.Seek(desiredSurfacePosition, 3f);
			if (behaviorStateMachine.CurrentStateId != 5 && behaviorStateMachine.CurrentStateId != 4)
			{
				float distanceToClosestTargetSqr;
				Combatant closestOpponent = SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
				if (distanceToClosestTargetSqr <= meleeRange * meleeRange)
				{
					base.Target = closestOpponent;
					behaviorStateMachine.EnterState(5);
				}
			}
		}

		protected override void OnActiveCombatEnd()
		{
			base.OnActiveCombatEnd();
			base.Steering.StopSeeking();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			Combatant result = Combatant.Invalid;
			if (LastAttackerIsValidTarget())
			{
				result = base.LastAttacker;
			}
			else
			{
				FindNearbyTargetsInVisionCone(isPatrolling, base.RigidbodyEx.physicsPosition, base.transform.forward, maxVisionConeAngle, float.MaxValue, inXZPlane: false, mustHaveLineOfSight: true, targetScratchSpace);
				if (targetScratchSpace.Count > 0)
				{
					result = targetScratchSpace[0];
				}
			}
			return result;
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = findTargetAngularSpeedDegrees;
		}

		private void OnUpdateFindTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant target = FindTarget();
			if (target.IsValid)
			{
				base.Target = target;
				base.LastAttacker = Combatant.Invalid;
				behaviorStateMachine.EnterState(1);
				return;
			}
			if (base.Steering.ReachedLookTarget || behaviorTimer.TimerOver)
			{
				Vector3 randomLookDirection = GetRandomLookDirection();
				Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				float num = Vector3.Angle(normalized, randomLookDirection);
				float maxRunningTime = num / findTargetAngularSpeedDegrees * 2f;
				LookDirection = randomLookDirection;
				behaviorTimer.StartTimer(maxRunningTime);
			}
			base.Steering.Look(LookDirection, findTargetSlowdownAngle);
		}

		private Vector3 GetRandomLookDirection()
		{
			float y = UnityEngine.Random.Range(0f - randomLookDirectionMaximumAngle, randomLookDirectionMaximumAngle);
			return Quaternion.Euler(0f, y, 0f) * initialForwardVector;
		}

		private void OnEnterLookAtTargetRangedState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = lookAtTargetAngularSpeedDegrees;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(lookAtTargetDuration);
			}
		}

		private void OnUpdateLookAtTargetRangedState()
		{
			if (base.hasAuthority)
			{
				if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(2);
				}
			}
		}

		private void OnEnterLookAtTargetMeleeState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = lookAtTargetAngularSpeedDegrees;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(lookAtTargetDuration);
			}
		}

		private void OnUpdateLookAtTargetMeleeState()
		{
			if (base.hasAuthority)
			{
				if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(4);
				}
			}
		}

		private void OnEnterChargeRangedAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			base.Steering.MaxAngularSpeed = lookAtTargetAngularSpeedDegrees;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeRangedAttackState()
		{
			if (base.hasAuthority)
			{
				if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(3);
				}
			}
		}

		protected void OnExitChargeRangedAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
		}

		private void OnEnterRangedAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = lookAtTargetAngularSpeedDegrees;
			AttackTargetPlayer();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateRangedAttackState()
		{
			if (base.hasAuthority)
			{
				if (base.Target.IsValid)
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(0);
				}
			}
		}

		private void AttackTargetPlayer()
		{
			if (base.Target.IsValid)
			{
				enemyAudio.OnAttack();
				if (base.hasAuthority)
				{
					AuthorityFireRangedWeaponAtTarget(canFireAtLastVisiblePosition: false);
				}
			}
		}

		private void OnEnterMeleeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.PlayMeleeAttack();
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(meleeAttackDuration);
			}
		}

		private void OnUpdateMeleeAttackState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(0);
			}
		}
	}
}
public class QuestSwingingAxeTrap : Trap
{
	[Header("Swinging Axe")]
	[SerializeField]
	private float swingFrequency = 1f;

	private MeleeWeaponCollider[] axeColliders;

	protected override void Awake()
	{
		base.Awake();
		axeColliders = GetComponentsInChildren<MeleeWeaponCollider>();
		if (animator != null)
		{
			animator.speed = swingFrequency;
			UnityEngine.MonoBehaviour.print("changed animator speed to " + animator.speed);
		}
	}

	protected override void Start()
	{
		base.Start();
		MeleeWeaponCollider[] array = axeColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.PlayerImpactEvent += OnMeleeColliderPlayerImpact;
			meleeWeaponCollider.AddIgnoredRigidbody(rigidbodyEx.UnityRigidbody);
			meleeWeaponCollider.enabled = true;
		}
	}

	protected override void OnDestroy()
	{
		MeleeWeaponCollider[] array = axeColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.PlayerImpactEvent -= OnMeleeColliderPlayerImpact;
		}
		base.OnDestroy();
	}

	protected virtual void OnMeleeColliderPlayerImpact(MeleeWeaponCollider collider, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
	{
		PlayerHit(hitPlayer, hitBodyPart, impact);
	}
}
public class RetractableRigidbodyPickup : AxisConstrainedRigidbodyPickup
{
	[Header("Retractable")]
	[SerializeField]
	private bool interpolateToRest = true;

	[SerializeField]
	private float interpolateToRestDuration = 0.25f;

	[SerializeField]
	private Transform restTransform;

	private Coroutine retractingToRestPointCoroutine;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_ReachedRestPoint;

	public bool InterpolatingToRest { get; protected set; }

	public Transform RestTransform => restTransform;

	public override Vector3 TargetPosition
	{
		get
		{
			if (IsPickedUp || restTransform == null)
			{
				return base.TargetPosition;
			}
			return restTransform.position;
		}
	}

	public override Quaternion TargetRotation
	{
		get
		{
			if (IsPickedUp || restTransform == null)
			{
				return base.TargetRotation;
			}
			return restTransform.rotation;
		}
	}

	public event Action ReachedRestPoint
	{
		add
		{
			Action action = this.m_ReachedRestPoint;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ReachedRestPoint, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_ReachedRestPoint;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ReachedRestPoint, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
	}

	public override void Pickup(RigidbodyEx target, Vector3 targetSpacePickupPosition, Quaternion targetSpacePickupRotation)
	{
		base.Pickup(target, targetSpacePickupPosition, targetSpacePickupRotation);
		StopRetractCoroutine();
	}

	public void Retract()
	{
		StartRetractCoroutine();
	}

	private void StopRetractCoroutine()
	{
		if (retractingToRestPointCoroutine != null)
		{
			StopCoroutine(retractingToRestPointCoroutine);
		}
	}

	private void StartRetractCoroutine()
	{
		StopRetractCoroutine();
		retractingToRestPointCoroutine = StartCoroutine(RetractToRestPointCoroutine());
	}

	private IEnumerator RetractToRestPointCoroutine()
	{
		float timer = 0f;
		while (!base.gameObject.activeSelf && timer <= 0.5f)
		{
			yield return null;
			timer += UnityEngine.Time.deltaTime;
		}
		Vector3 velocity = Vector3.zero;
		Vector3 angularVelocity = Vector3.zero;
		rigidbodyEx.ClearVelocity();
		timer = 0f;
		InterpolatingToRest = true;
		while (interpolateToRest && timer < interpolateToRestDuration)
		{
			Vector3 nextPosition = Vector3.SmoothDamp(rigidbodyEx.physicsPosition, TargetPosition, ref velocity, interpolateToRestDuration);
			Vector3 targetEulerAngles = TargetRotation.eulerAngles;
			Vector3 eulerAngles = base.transform.rotation.eulerAngles;
			eulerAngles.x = Mathf.SmoothDampAngle(eulerAngles.x, targetEulerAngles.x, ref angularVelocity.x, interpolateToRestDuration);
			eulerAngles.y = Mathf.SmoothDampAngle(eulerAngles.y, targetEulerAngles.y, ref angularVelocity.y, interpolateToRestDuration);
			eulerAngles.z = Mathf.SmoothDampAngle(eulerAngles.z, targetEulerAngles.z, ref angularVelocity.z, interpolateToRestDuration);
			Quaternion nextRotation = Quaternion.Euler(eulerAngles);
			SetRigidbodyTransform(nextPosition, nextRotation);
			rigidbodyEx.ClearVelocity();
			yield return new WaitForFixedUpdate();
			timer += UnityEngine.Time.fixedDeltaTime;
		}
		InterpolatingToRest = false;
		if (this.ReachedRestPoint != null)
		{
			this.ReachedRestPoint();
		}
		while (true)
		{
			yield return new WaitForFixedUpdate();
			SetRigidbodyTransform(TargetPosition, TargetRotation);
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class FollowBulletParticle : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private PooledParticle pooledParticle;

		private readonly List<Bullet> bullets = new List<Bullet>();

		private void LateUpdate()
		{
			if (bullets.Count > 0)
			{
				Vector3 zero = Vector3.zero;
				foreach (Bullet bullet in bullets)
				{
					zero += bullet.transform.position;
				}
				zero /= (float)bullets.Count;
				base.transform.position = zero;
			}
			else
			{
				pooledParticle.Stop();
			}
		}

		public void SetTargets(IEnumerable<Bullet> targets)
		{
			bullets.Clear();
			bullets.AddRange(targets);
			foreach (Bullet target in targets)
			{
				target.DestroyEvent += OnBulletDestroyed;
			}
			pooledParticle.Play(loop: true);
		}

		private void OnBulletDestroyed(Bullet bullet)
		{
			bullets.Remove(bullet);
			bullet.DestroyEvent -= OnBulletDestroyed;
		}
	}
}
namespace RecRoom.Activities.Quest.Goblin2
{
	public class ForceWandWeapon : SpreadRangedWeapon
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private DelayedRangedWeaponTrigger trigger;

		[Header("Wand")]
		[SerializeField]
		private Transform spreadOffsetRoot;

		[SerializeField]
		private WandProjectileParticles shootParticlesPrefab;

		[SerializeField]
		private float minBulletPercentageRequiredForParticles = 0.25f;

		[Header("Aiming")]
		[SerializeField]
		private bool useHeadAimBias;

		[SerializeField]
		private float maxHeadAimAngle = 75f;

		[Header("Damage")]
		[SerializeField]
		[Range(0f, 1f)]
		private float centerShotInitialCharge = 1f;

		[SerializeField]
		[Range(0f, 1f)]
		private float spreadShotInitialCharge = 0.3f;

		[SerializeField]
		private AnimationCurve damageFalloffCurve = AnimationCurve.Linear(0f, 1f, 1f, 0f);

		[Header("Physics Damage")]
		[SerializeField]
		private float minPhysicsDamageVelocity = 1f;

		[SerializeField]
		private float maxFloorAngleDegrees = 30f;

		[SerializeField]
		private float enemyCollisionDamageCharge = 1f;

		[SerializeField]
		private float otherEnemyCollisionDamageCharge = 1f;

		[SerializeField]
		private float environmentCollisionDamageCharge = 1f;

		private readonly List<Enemy> enemyEventSubscriptions = new List<Enemy>();

		private WandProjectileParticles bulletParticles;

		protected override bool HasTriggerAnimation => false;

		protected override void Awake()
		{
			base.Awake();
			trigger.TriggeredEvent += OnTriggeredEvent;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			trigger.TriggeredEvent -= OnTriggeredEvent;
		}

		private void LateUpdate()
		{
			if (bulletTracker != null && bulletParticles != null && bulletTracker.LivingBulletCount <= (float)spreadTargets.Length * minBulletPercentageRequiredForParticles)
			{
				bulletParticles.StopVelocity();
				bulletParticles = null;
			}
		}

		private void OnTriggeredEvent(DelayedRangedWeaponTrigger trigger)
		{
			if (base.hasAuthority)
			{
				Fire(1f);
			}
		}

		public override void Fire(float charge)
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (base.IsMisfire || base.IsOnCooldown)
			{
				base.WeaponAudio.OnMisfire();
				return;
			}
			Vector3 vector = barrelTransform.forward;
			if (useHeadAimBias && base.Tool.IsHeldByPlayer && Vector3.Angle(vector, base.Tool.HolderPlayer.Head.transform.forward) < maxHeadAimAngle)
			{
				Vector3 physicsPosition = base.Tool.HolderPlayer.Head.RigidbodyEx.physicsPosition;
				Vector3 normalized = (barrelTransform.position - physicsPosition).normalized;
				vector = (vector + normalized).normalized;
			}
			spreadOffsetRoot.forward = vector;
			Fire(vector * bulletFireSpeed, charge);
		}

		protected override void OnBulletEnemyImpact(Bullet bullet, Enemy enemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			base.OnBulletEnemyImpact(bullet, enemy, enemyArmorType, impact);
			if (impact.PreAttackChargeAmount > spreadShotInitialCharge)
			{
				bulletTracker.GetBulletGroupContainingBullet(bullet)?.DestroyAllBullets();
			}
		}

		protected override bool OnEnemyImpact(Enemy enemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			if (impact.PreAttackChargeAmount > spreadShotInitialCharge)
			{
				if (enemy.Steering.IsOnSurface)
				{
					float magnitude = impact.Force.magnitude;
					impact.Force = Vector3.ProjectOnPlane(impact.Force, enemy.Steering.SurfaceNormal).normalized * magnitude;
				}
				if (base.hasAuthority && !enemyEventSubscriptions.Contains(enemy))
				{
					SubscribeToEnemyEvents(enemy);
				}
			}
			float time = Mathf.Clamp01(impact.Distance / maxDistance);
			impact.PreAttackChargeAmount *= damageFalloffCurve.Evaluate(time);
			return base.OnEnemyImpact(enemy, enemyArmorType, impact);
		}

		protected void OnEnemyStunEnd(Enemy enemy)
		{
			UnsubscribeFromEnemyEvents(enemy);
		}

		protected void OnEnemyCollisionEnter(Enemy enemy, Collision collision)
		{
			if (!(collision.relativeVelocity.sqrMagnitude > minPhysicsDamageVelocity * minPhysicsDamageVelocity))
			{
				return;
			}
			EnemyArmorType hitEnemyArmorType;
			Enemy colliderEnemy = collision.GetColliderEnemy(out hitEnemyArmorType);
			bool flag = false;
			float preAttackChargeAmount = 0f;
			if (colliderEnemy != null)
			{
				flag = true;
				preAttackChargeAmount = enemyCollisionDamageCharge;
			}
			else
			{
				Vector3 normal = collision.contacts[0].normal;
				float num = Vector3.Angle(normal, Vector3.up);
				if (num > maxFloorAngleDegrees)
				{
					flag = true;
					preAttackChargeAmount = environmentCollisionDamageCharge;
				}
			}
			if (flag)
			{
				UnsubscribeFromEnemyEvents(enemy);
				WeaponImpact impact = new WeaponImpact
				{
					Velocity = collision.relativeVelocity,
					Force = Vector3.zero,
					Point = collision.contacts[0].point,
					Distance = 0f,
					SurfaceNormal = collision.contacts[0].normal,
					GameObject = collision.gameObject,
					PreAttackChargeAmount = preAttackChargeAmount
				};
				DealEnemySecondaryDamage(enemy, impact);
				if ((bool)colliderEnemy)
				{
					impact.PreAttackChargeAmount = otherEnemyCollisionDamageCharge;
					DealEnemySecondaryDamage(colliderEnemy, impact);
				}
			}
		}

		private void SubscribeToEnemyEvents(Enemy enemy)
		{
			if (!enemyEventSubscriptions.Contains(enemy))
			{
				enemy.CollisionEnterEvent += OnEnemyCollisionEnter;
				enemy.StunEndEvent += OnEnemyStunEnd;
				enemyEventSubscriptions.Add(enemy);
			}
		}

		private void UnsubscribeFromEnemyEvents(Enemy enemy)
		{
			enemy.CollisionEnterEvent -= OnEnemyCollisionEnter;
			enemy.StunEndEvent -= OnEnemyStunEnd;
			enemyEventSubscriptions.Remove(enemy);
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			if (isMisfire)
			{
				base.WeaponAudio.OnMisfire();
				return;
			}
			base.FireShot(position, rotation, velocity, spreadShotInitialCharge, isMisfire, shotId);
			base.FireShot(position, rotation, velocity, centerShotInitialCharge, isMisfire, shotId);
			if (shootParticlesPrefab != null)
			{
				bulletParticles = ObjectPool.Instance.Acquire(shootParticlesPrefab);
				bulletParticles.ResetVelocity();
				bulletParticles.Play(barrelTransform);
			}
		}
	}
	[RequireComponent(typeof(Tool))]
	public class MagicCharge : Photon.MonoBehaviour
	{
		private const float MAX_CHARGE = 1f;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Header("Charging")]
		[SerializeField]
		private float movingChargeTime = 1f;

		[SerializeField]
		private float passiveChargeTime = 1.5f;

		[SerializeField]
		private float unchargeTime = 1f;

		[SerializeField]
		private float minimumChargeVelocity = 0.3f;

		[SerializeField]
		private float reverseVelocityLookbackStartTime = 0.15f;

		[SerializeField]
		private float reverseVelocityLookbackEndTime = 0.1f;

		[SerializeField]
		[Range(0f, 1f)]
		private float minimumCharge = 0.1f;

		[Header("Feedback")]
		[SerializeField]
		private WeaponAudio weaponAudio;

		[SerializeField]
		private Animator chargeAnimator;

		[SerializeField]
		private float minChargeVibrationInterval = 0.5f;

		[SerializeField]
		private float maxChargeVibrationInterval = 0.2f;

		[SerializeField]
		private float chargedVibrationInterval;

		[SerializeField]
		private float vibrationIntensity = 0.2f;

		[SerializeField]
		private float offhandVibrationRatio = 0.5f;

		[SerializeField]
		private AudioSource chargeAudioSource;

		private float _charge;

		private Coroutine chargeRoutine;

		private float lastVibrationTime;

		private float maxAudioVolume;

		public float Charge
		{
			get
			{
				return _charge;
			}
			private set
			{
				if (_charge != value)
				{
					_charge = value;
					chargeAnimator.SetFloat("Charge", _charge);
				}
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (chargeAudioSource != null)
			{
				maxAudioVolume = chargeAudioSource.volume;
			}
		}

		private void OnPickup(Tool thisTool)
		{
			OnHolderChange(thisTool);
		}

		private void OnHolderChange(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcResetCharge);
			}
		}

		public void StartCharging()
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcStartCharging);
			}
		}

		public void ResetCharge()
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcResetCharge);
			}
		}

		[PunRPC]
		private void RpcStartCharging()
		{
			if (chargeRoutine == null)
			{
				chargeRoutine = StartCoroutine(RunChargeCoroutine());
			}
			if (chargeAudioSource != null && !chargeAudioSource.isPlaying)
			{
				chargeAudioSource.Play();
			}
		}

		[PunRPC]
		private void RpcResetCharge()
		{
			this.SafeStopCoroutine(chargeRoutine);
			chargeRoutine = null;
			Charge = 0f;
			if (chargeAudioSource != null)
			{
				chargeAudioSource.Stop();
			}
			if (weaponAudio != null)
			{
				weaponAudio.OnStopCharge();
			}
		}

		private IEnumerator RunChargeCoroutine()
		{
			lastVibrationTime = 0f;
			float chargeRange = 1f - minimumCharge;
			while (Charge < 1f)
			{
				bool shouldChargeThisFrame = tool.IsHeldByPlayer;
				if (shouldChargeThisFrame)
				{
					Vector3 averageHistoricalKinematicLinearVelocity = tool.HolderHand.RigidbodyEx.GetAverageHistoricalKinematicLinearVelocity(reverseVelocityLookbackStartTime, reverseVelocityLookbackEndTime);
					if (Vector3.Dot(averageHistoricalKinematicLinearVelocity, tool.HolderHand.RigidbodyEx.velocity) < 0f)
					{
						shouldChargeThisFrame = false;
					}
				}
				float chargeDelta;
				if (!shouldChargeThisFrame)
				{
					chargeDelta = ((!(unchargeTime > 0f)) ? (-1f) : ((0f - UnityEngine.Time.deltaTime) / unchargeTime));
				}
				else
				{
					float num = ((!(tool.HolderHand.RigidbodyEx.velocity.magnitude >= minimumChargeVelocity)) ? passiveChargeTime : movingChargeTime);
					chargeDelta = ((!(num > 0f)) ? 1f : (UnityEngine.Time.deltaTime / num));
				}
				chargeDelta *= chargeRange;
				Charge = Mathf.Clamp(Charge + chargeDelta, minimumCharge, 1f);
				VibrateHands(vibrationInterval: Mathf.Lerp(minChargeVibrationInterval, maxChargeVibrationInterval, Charge), intensity: (int)(ushort)vibrationIntensity);
				UpdateAudioVolume();
				yield return null;
			}
			if (weaponAudio != null)
			{
				weaponAudio.OnCharge();
			}
			while (true)
			{
				VibrateHands(vibrationIntensity, chargedVibrationInterval);
				yield return null;
			}
		}

		private void UpdateAudioVolume()
		{
			if (chargeAudioSource != null)
			{
				chargeAudioSource.volume = maxAudioVolume * Charge;
			}
		}

		private void VibrateHands(float intensity, float vibrationInterval)
		{
			if (UnityEngine.Time.time < lastVibrationTime + vibrationInterval)
			{
				return;
			}
			lastVibrationTime = UnityEngine.Time.time;
			if (tool.IsHeldByPlayer)
			{
				tool.HolderHand.Vibrate(200, intensity);
				PlayerHand otherHand = tool.HolderPlayer.GetOtherHand(tool.HolderHand.Type);
				if (otherHand.IsHoldingTool && otherHand.HeldTool.ParentTool == tool)
				{
					otherHand.Vibrate(200, intensity * offhandVibrationRatio);
				}
			}
		}
	}
