	public class QuestFirePowerup : Powerup
	{
		[SerializeField]
		private float bonusEnemyForce = 20f;

		[SerializeField]
		private float minRepeatDamageInterval = 0.5f;

		private readonly Dictionary<Enemy, float> enemyDamagedTimes = new Dictionary<Enemy, float>();

		protected override void ProcessEnemyImpact(Weapon weapon, Enemy defender, WeaponImpact impact, bool hadDamageAuthority)
		{
			base.ProcessEnemyImpact(weapon, defender, impact, hadDamageAuthority);
			DamageEnemy(defender, weapon, weapon.DamageType, impact);
		}

		private void DamageEnemy(Enemy enemy, Weapon weapon, WeaponDamageType damageType, WeaponImpact impact)
		{
			if ((!(weapon != null) || enemyDamagedTimes.ContainsKey(enemy)) && !(UnityEngine.Time.time > enemyDamagedTimes[enemy] + minRepeatDamageInterval))
			{
				return;
			}
			if (base.hasAuthority)
			{
				if (!enemy.hasAuthority)
				{
					enemy.TransferOwnership(PhotonNetwork.player);
				}
				Vector3 force = impact.Force.normalized * bonusEnemyForce;
				int enemyDamage = weapon.GetEnemyDamage(impact.PreAttackChargeAmount);
				enemy.AuthorityTryApplyAttack(weapon.authority, weapon, damageType, EnemyArmorType.NORMAL, enemyDamage, impact);
				enemy.AuthorityOnDamageApplyForce(damageType, EnemyArmorType.NORMAL, force, impact.Point);
			}
			enemyDamagedTimes[enemy] = UnityEngine.Time.time;
		}
	}
	public class Potion : Photon.MonoBehaviour
	{
		public delegate void PotionActivated(Potion potion, PhotonPlayer player);

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private PotionActivated m_PotionActivatedEvent;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private DrinkableBottle waterBottle;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private BreakableObject breakableObject;

		[SerializeField]
		private PowerupType powerupType;

		[SerializeField]
		private int drinksToActivate = 3;

		[SerializeField]
		private float drinkResetTime = 2f;

		[SerializeField]
		private RecRoomAudioClip clinkSfx;

		private PhotonPlayer lastDrunkPlayer;

		private float lastDrinkTime;

		private int consecutiveDrinks;

		[NonSerialized]
		public bool AutomaticDrinkingEnabled = true;

		public event PotionActivated PotionActivatedEvent
		{
			add
			{
				PotionActivated potionActivated = this.m_PotionActivatedEvent;
				PotionActivated potionActivated2;
				do
				{
					potionActivated2 = potionActivated;
					potionActivated = Interlocked.CompareExchange(ref this.m_PotionActivatedEvent, (PotionActivated)Delegate.Combine(potionActivated2, value), potionActivated);
				}
				while (potionActivated != potionActivated2);
			}
			remove
			{
				PotionActivated potionActivated = this.m_PotionActivatedEvent;
				PotionActivated potionActivated2;
				do
				{
					potionActivated2 = potionActivated;
					potionActivated = Interlocked.CompareExchange(ref this.m_PotionActivatedEvent, (PotionActivated)Delegate.Remove(potionActivated2, value), potionActivated);
				}
				while (potionActivated != potionActivated2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			tool.PostResetEvent += OnToolReset;
			waterBottle.DrunkEvent += OnBottleDrunk;
			waterBottle.IsEmptyChangeEvent += OnBottleEmptyChange;
		}

		private void Start()
		{
			OnBottleEmptyChange(waterBottle);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostResetEvent -= OnToolReset;
			waterBottle.DrunkEvent -= OnBottleDrunk;
			waterBottle.IsEmptyChangeEvent -= OnBottleEmptyChange;
		}

		public void TryDrink(PhotonPlayer player)
		{
			if (base.hasAuthority && player != null)
			{
				lastDrunkPlayer = player;
				AuthorityActivate();
				lastDrunkPlayer = null;
			}
		}

		private void OnTriggerEnter(Collider collider)
		{
			if (!tool.IsHeldByPlayer || clinkSfx == null)
			{
				return;
			}
			Tool colliderTool = collider.GetColliderTool();
			if (colliderTool != null && colliderTool != tool && colliderTool.IsHeld)
			{
				Potion component = colliderTool.GetComponent<Potion>();
				if (component != null)
				{
					AudioManager.Play3DSFX(clinkSfx, base.transform.position);
				}
			}
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			lastDrunkPlayer = null;
			consecutiveDrinks = 0;
		}

		private void OnBottleDrunk(DrinkableBottle bottle, PhotonPlayer drinker)
		{
			if (AutomaticDrinkingEnabled)
			{
				if (UnityEngine.Time.time > lastDrinkTime + drinkResetTime)
				{
					lastDrunkPlayer = null;
				}
				if (lastDrunkPlayer != drinker)
				{
					lastDrunkPlayer = drinker;
					consecutiveDrinks = 0;
				}
				if (tool.HolderPlayer != null && tool.HolderPlayer.PhotonPlayer == drinker)
				{
					lastDrinkTime = UnityEngine.Time.time;
					consecutiveDrinks++;
				}
				if (base.hasAuthority && consecutiveDrinks >= drinksToActivate)
				{
					AuthorityActivate();
					lastDrunkPlayer = null;
				}
			}
		}

		private void OnBottleEmptyChange(DrinkableBottle bottle)
		{
			if (breakableObject != null)
			{
				breakableObject.SetBreakable(bottle.IsEmpty, this);
			}
		}

		private void AuthorityActivate()
		{
			if (base.hasAuthority && !waterBottle.IsEmpty)
			{
				waterBottle.AuthorityMarkEmpty();
				if (powerupType != PowerupType.INVALID)
				{
					Powerup.RequestPowerupActivation(powerupType, lastDrunkPlayer);
				}
				base.photonView.RpcAll(RpcOnPotionActivated, lastDrunkPlayer);
			}
		}

		[PunRPC]
		private void RpcOnPotionActivated(PhotonPlayer activatingPlayer)
		{
			if (this.PotionActivatedEvent != null)
			{
				this.PotionActivatedEvent(this, activatingPlayer);
			}
		}
	}
