		private const int TOOL_COLLISION_REFLECTION_DELAY_FRAMES = 1;

		private SynchronizedField<int> _projectileToolId;

		private float reflectionLastAttackStartFrame = float.MinValue;

		private Coroutine reflectionDelayedToolCollisionCoroutine;

		private Coroutine delayedAttackCoroutine;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private ReflectionAction m_ReflectionEvent;

		public ProjectileTool ProjectileTool { get; private set; }

		public ProjectileToolEnemyImpact CustomProjectileEnemyImpactResolution { get; set; }

		private Vector3 ReflectionTarget => (!(reflectionTarget != null)) ? base.transform.position : reflectionTarget.position;

		public event ReflectionAction ReflectionEvent
		{
			add
			{
				ReflectionAction reflectionAction = this.m_ReflectionEvent;
				ReflectionAction reflectionAction2;
				do
				{
					reflectionAction2 = reflectionAction;
					reflectionAction = Interlocked.CompareExchange(ref this.m_ReflectionEvent, (ReflectionAction)Delegate.Combine(reflectionAction2, value), reflectionAction);
