				ReflectionAction reflectionAction2;
				do
				{
					reflectionAction2 = reflectionAction;
					reflectionAction = Interlocked.CompareExchange(ref this.m_ReflectionEvent, (ReflectionAction)Delegate.Remove(reflectionAction2, value), reflectionAction);
				}
				while (reflectionAction != reflectionAction2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_projectileToolId = new SynchronizedField<int>(this, "PROJ", -1, SetterPermissionMode.MASTER, OnProjectileChange);
			Tool.StaticToolInstantiatedEvent += OnToolInstantiated;
		}

		private void Start()
		{
			OnProjectileChange();
			if (PhotonNetwork.isMasterClient && ProjectileTool == null)
			{
				InstantiateProjectile();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Tool.StaticToolInstantiatedEvent -= OnToolInstantiated;
			if (ProjectileTool != null)
			{
				ProjectileTool.PlayerImpactEvent -= OnProjectilePlayerImpact;
				ProjectileTool.ToolImpactEvent -= OnProjectileToolImpact;
				ProjectileTool.EnemyImpactEvent -= OnProjectileEnemyImpact;
				ProjectileTool.OtherImpactEvent -= OnProjectileOtherImpact;
				ProjectileTool.FinishEvent -= OnProjectileFinish;
				ProjectileTool.Tool.AttackAppliedEvent -= OnProjectileAttackApplied;
			}
		}

		protected override float GetFireSpeed(float desiredSpeed)
		{
			return (!(desiredSpeed <= 0f)) ? desiredSpeed : defaultProjectileSpeed;
		}

		protected override void LocalFire(Vector3 target, float speed)
		{
			if (ProjectileTool == null)
			{
				UnityEngine.Debug.LogError(base.name + " tried to fire a projectile but is missing a projectile tool reference.");
				return;
			}
			ProjectileTool.Tool.ClearDynamicMaxSpeed();
			if (base.hasAuthority)
			{
				if (!ProjectileTool.hasAuthority)
				{
					ProjectileTool.photonView.TransferOwnership(PhotonNetwork.player);
				}
				Vector3 position = projectileOriginTransform.position;
				Quaternion rotation = projectileOriginTransform.rotation;
				Vector3 normalized = (target - position).normalized;
				ProjectileTool.AuthorityFire(position, rotation, normalized * speed);
			}
		}

		private void InstantiateProjectile()
		{
			Vector3 position = projectileOriginTransform.position;
			Quaternion rotation = projectileOriginTransform.rotation;
			Tool tool = Tool.PhotonInstantiateForRoom(projectilePrefab.name, position, rotation, 1f, base.photonView.viewID);
			if (tool == null)
			{
				UnityEngine.Debug.LogError("Failed to instantiate enemy projectile tool.  Prefab is likely not in the resources directory.");
				return;
			}
			tool.IsEnabled = false;
			_projectileToolId.Set(tool.photonView.viewID);
		}

		private void OnToolInstantiated(Tool tool)
		{
			if (tool != null && tool.InstantiatorPhotonViewId == base.photonView.viewID && tool.photonView.viewID == _projectileToolId.Get())
			{
				OnProjectileChange();
			}
		}

		private void OnProjectileChange()
		{
			ProjectileTool = null;
			if (_projectileToolId != null)
			{
				PhotonView photonView = PhotonView.Find(_projectileToolId.Get());
				ProjectileTool = ((!(photonView != null)) ? null : photonView.GetComponent<ProjectileTool>());
				if (ProjectileTool != null)
				{
					ProjectileTool.PlayerImpactEvent += OnProjectilePlayerImpact;
					ProjectileTool.ToolImpactEvent += OnProjectileToolImpact;
					ProjectileTool.EnemyImpactEvent += OnProjectileEnemyImpact;
					ProjectileTool.OtherImpactEvent += OnProjectileOtherImpact;
					ProjectileTool.FinishEvent += OnProjectileFinish;
					ProjectileTool.Tool.CustomApplyForceModifier = ModifyProjectileAppliedForce;
					ProjectileTool.Tool.CustomVelocityChangeModifier = ModifyProjectileVelocityChange;
					ProjectileTool.Tool.AttackAppliedEvent += OnProjectileAttackApplied;
				}
			}
		}

		private void OnProjectilePlayerImpact(ProjectileTool thisProjectile, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (thisProjectile != null && hitPlayer.hasAuthority)
			{
				if (!thisProjectile.hasAuthority)
				{
					thisProjectile.photonView.TransferOwnership(PhotonNetwork.player);
				}
				OnPlayerHit(hitPlayer, hitBodyPart, impact);
				thisProjectile.AuthorityFinish();
			}
		}

		private void OnProjectileEnemyImpact(ProjectileTool thisProjectile, Enemy hitEnemy, EnemyArmorType hitArmorType, WeaponImpact impact)
		{
			if (!(thisProjectile != null) || !thisProjectile.hasAuthority)
			{
				return;
			}
			if (CustomProjectileEnemyImpactResolution != null)
			{
				CustomProjectileEnemyImpactResolution(thisProjectile, thisEnemy, hitEnemy, hitArmorType, impact);
				return;
			}
			if (!hitEnemy.hasAuthority)
			{
				hitEnemy.photonView.TransferOwnership(PhotonNetwork.player);
			}
			OnEnemyHit(hitEnemy, hitArmorType, impact);
			thisProjectile.AuthorityFinish();
		}

		private void OnProjectileToolImpact(ProjectileTool thisProjectile, Tool hitTool, WeaponImpact impact)
		{
			if (!(thisProjectile != null) || !hitTool.hasAuthority)
			{
				return;
			}
			if (canBeReflectedByAttacks)
			{
				if ((float)UnityEngine.Time.frameCount - reflectionLastAttackStartFrame >= 1f)
				{
					StartDelayedToolCollisionCoroutine(thisProjectile, hitTool, impact);
				}
			}
			else
			{
				ProjectileToolImpactHelper(thisProjectile, hitTool, impact);
			}
		}

		private void ProjectileToolImpactHelper(ProjectileTool thisProjectile, Tool hitTool, WeaponImpact impact)
		{
			if (!thisProjectile.hasAuthority)
			{
				thisProjectile.photonView.TransferOwnership(PhotonNetwork.player);
			}
			OnPlayerToolHit(hitTool, impact);
			thisProjectile.AuthorityFinish();
		}

		private void OnProjectileOtherImpact(ProjectileTool thisProjectile, WeaponImpact impact)
		{
			if (thisProjectile != null && thisProjectile.hasAuthority)
			{
				thisProjectile.AuthorityFinish();
			}
		}

		private void OnProjectileFinish(ProjectileTool projectile, Vector3 point, bool timedOut)
		{
			if (!timedOut)
			{
				PlayParticles(projectileImpactParticlesPrefab, point, Vector3.up);
				AudioManager.Play3DSFX(projectileImpactAudio, point);
			}
		}

		public void AuthorityReflect(Vector3 target, float speed, ReflectionTypes reflectionType = ReflectionTypes.TO_PLAYER)
		{
			AuthorityReflect(target, speed, successReturnLifetime, reflectionType);
		}

		public void AuthorityReflect(Vector3 target, float speed, Vector3 currentPosition, Quaternion currentRotation, ReflectionTypes reflectionType = ReflectionTypes.TO_PLAYER)
		{
			AuthorityReflect(target, speed, successReturnLifetime, currentPosition, currentRotation, reflectionType);
		}

		public void AuthorityReflect(Vector3 target, float speed, float lifetime, ReflectionTypes reflectionType = ReflectionTypes.TO_PLAYER)
		{
			Vector3 physicsPosition = ProjectileTool.Tool.RigidbodyEx.physicsPosition;
			Quaternion physicsRotation = ProjectileTool.Tool.RigidbodyEx.physicsRotation;
			AuthorityReflect(target, speed, lifetime, physicsPosition, physicsRotation, reflectionType);
		}

		public void AuthorityReflect(Vector3 target, float speed, float lifetime, Vector3 currentPosition, Quaternion currentRotation, ReflectionTypes reflectionType = ReflectionTypes.TO_PLAYER)
		{
			if (base.hasAuthority)
			{
				if (!ProjectileTool.hasAuthority)
				{
					ProjectileTool.photonView.TransferOwnership(PhotonNetwork.player);
				}
				Vector3 vector = (target - currentPosition).normalized * speed;
				ProjectileTool.AuthorityFire(currentPosition, currentRotation, vector, lifetime);
				base.photonView.RpcAll(RpcOnReflection, reflectionType, currentPosition, vector);
			}
		}

		private void OnProjectileAttackApplied(Tool projectileTool, Weapon attacker, WeaponDamageType damageType, Vector3 point)
		{
			if (canBeReflectedByAttacks && attacker.hasAuthority)
			{
				reflectionLastAttackStartFrame = UnityEngine.Time.time;
				StopDelayedToolCollisionCoroutine();
				StartDelayedAttackCoroutine();
			}
		}

		private void AttackProjectileReflectHelper(ReflectionTypes reflectionType)
		{
			float speed;
			float lifetime;
			if (reflectionType == ReflectionTypes.TO_ENEMY_SUCCESS)
			{
				speed = Mathf.Clamp(ProjectileTool.Tool.RigidbodyEx.velocity.magnitude, defaultProjectileSpeed, maxReturnSpeed);
				lifetime = successReturnLifetime;
			}
			else
			{
				speed = failReturnSpeed;
				lifetime = failReturnLifetime;
			}
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			AuthorityReflect(ReflectionTarget, speed, lifetime, reflectionType);
		}

		private void ModifyProjectileAppliedForce(ref Vector3 force, Vector3 point)
		{
			force = (ReflectionTarget - point).normalized * force.magnitude;
		}

		private void ModifyProjectileVelocityChange(ref Vector3 linearVelocity, ref Vector3 angularVelocity, Vector3 point)
		{
			linearVelocity = (ReflectionTarget - point).normalized * linearVelocity.magnitude;
		}

		[PunRPC]
		private void RpcOnReflection(ReflectionTypes reflectionType, Vector3 point, Vector3 newVelocity)
		{
			if (this.ReflectionEvent != null && ProjectileTool != null)
			{
				this.ReflectionEvent(ProjectileTool, reflectionType, point, newVelocity);
			}
			PlayParticles(reflectionParticlesPrefab, point, Vector3.up);
			switch (reflectionType)
			{
			case ReflectionTypes.TO_PLAYER:
				AudioManager.Play3DSFX(reflectionToPlayerAudio, point);
				break;
			case ReflectionTypes.TO_ENEMY_SUCCESS:
				AudioManager.Play3DSFX(reflectionToEnemyAudio, point);
				break;
			default:
				AudioManager.Play3DSFX(reflectionToEnemyFailAudio, point);
				break;
			}
		}

		private void StartDelayedToolCollisionCoroutine(ProjectileTool thisProjectile, Tool hitTool, WeaponImpact impact)
		{
			StopDelayedToolCollisionCoroutine();
			reflectionDelayedToolCollisionCoroutine = StartCoroutine(ReflectionDelayedToolCollision(thisProjectile, hitTool, impact));
		}

		private void StopDelayedToolCollisionCoroutine()
		{
			if (reflectionDelayedToolCollisionCoroutine != null)
			{
				StopCoroutine(reflectionDelayedToolCollisionCoroutine);
				reflectionDelayedToolCollisionCoroutine = null;
			}
		}

		private IEnumerator ReflectionDelayedToolCollision(ProjectileTool thisProjectile, Tool hitTool, WeaponImpact impact)
		{
			for (int i = 0; i < 1; i++)
			{
				yield return null;
			}
			Weapon hitWeapon = hitTool.GetComponent<Weapon>();
			if (hitWeapon != null && damageTypesThatAlwaysReflect.Contains(hitWeapon.DamageType))
			{
				AttackProjectileReflectHelper(ReflectionTypes.TO_ENEMY_FAIL);
			}
			else
			{
				ProjectileToolImpactHelper(thisProjectile, hitTool, impact);
			}
		}

		private void StartDelayedAttackCoroutine()
		{
			StopDelayedAttackCoroutine();
			delayedAttackCoroutine = StartCoroutine(DelayedAttackCoroutine());
		}

		private void StopDelayedAttackCoroutine()
		{
			if (delayedAttackCoroutine != null)
			{
				StopCoroutine(delayedAttackCoroutine);
				delayedAttackCoroutine = null;
			}
		}

		private IEnumerator DelayedAttackCoroutine()
		{
			yield return null;
			AttackProjectileReflectHelper(ReflectionTypes.TO_ENEMY_SUCCESS);
		}
	}
}
namespace RecRoom.Core.Combat
{
	public class ProjectileTool : Photon.MonoBehaviour
	{
		public delegate void PlayerImpact(ProjectileTool thisTool, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact);

		public delegate void ToolImpact(ProjectileTool thisTool, Tool hitTool, WeaponImpact impact);

		public delegate void EnemyImpact(ProjectileTool thisTool, Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact);

		public delegate void TrapImpact(ProjectileTool thisTool, Trap hitTrap, WeaponImpact impact);

		public delegate void OtherImpact(ProjectileTool thisTool, WeaponImpact impact);

		public delegate void FinishAction(ProjectileTool thisTool, Vector3 point, bool timedOut);

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[SerializeField]
		private float projectileForce = 16f;

		[SerializeField]
		private float defaultMaxLifetime = 10f;

		[SerializeField]
		private bool useGravity;

		[SerializeField]
		private bool canBePickedUp;

		[SerializeField]
		private bool faceVelocity;

		[Header("Feedback")]
		[SerializeField]
		private PooledParticle timeoutParticlesPrefab;

		[SerializeField]
		private RecRoomAudioClip timeoutAudio;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private PlayerImpact m_PlayerImpactEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private ToolImpact m_ToolImpactEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private EnemyImpact m_EnemyImpactEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private OtherImpact m_OtherImpactEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private FinishAction m_FinishEvent;

		private BulletTrail trail;

		private SynchronizedTimer lifetimeTimer;

		public Tool Tool => tool;

		public event PlayerImpact PlayerImpactEvent
		{
			add
			{
				PlayerImpact playerImpact = this.m_PlayerImpactEvent;
				PlayerImpact playerImpact2;
				do
				{
					playerImpact2 = playerImpact;
					playerImpact = Interlocked.CompareExchange(ref this.m_PlayerImpactEvent, (PlayerImpact)Delegate.Combine(playerImpact2, value), playerImpact);
				}
				while (playerImpact != playerImpact2);
			}
			remove
			{
				PlayerImpact playerImpact = this.m_PlayerImpactEvent;
				PlayerImpact playerImpact2;
				do
				{
					playerImpact2 = playerImpact;
					playerImpact = Interlocked.CompareExchange(ref this.m_PlayerImpactEvent, (PlayerImpact)Delegate.Remove(playerImpact2, value), playerImpact);
				}
				while (playerImpact != playerImpact2);
			}
		}

		public event ToolImpact ToolImpactEvent
		{
			add
			{
				ToolImpact toolImpact = this.m_ToolImpactEvent;
				ToolImpact toolImpact2;
				do
				{
					toolImpact2 = toolImpact;
					toolImpact = Interlocked.CompareExchange(ref this.m_ToolImpactEvent, (ToolImpact)Delegate.Combine(toolImpact2, value), toolImpact);
				}
				while (toolImpact != toolImpact2);
			}
			remove
			{
				ToolImpact toolImpact = this.m_ToolImpactEvent;
				ToolImpact toolImpact2;
				do
				{
					toolImpact2 = toolImpact;
					toolImpact = Interlocked.CompareExchange(ref this.m_ToolImpactEvent, (ToolImpact)Delegate.Remove(toolImpact2, value), toolImpact);
				}
				while (toolImpact != toolImpact2);
			}
		}

		public event EnemyImpact EnemyImpactEvent
		{
			add
			{
				EnemyImpact enemyImpact = this.m_EnemyImpactEvent;
				EnemyImpact enemyImpact2;
				do
				{
					enemyImpact2 = enemyImpact;
					enemyImpact = Interlocked.CompareExchange(ref this.m_EnemyImpactEvent, (EnemyImpact)Delegate.Combine(enemyImpact2, value), enemyImpact);
				}
				while (enemyImpact != enemyImpact2);
			}
			remove
			{
				EnemyImpact enemyImpact = this.m_EnemyImpactEvent;
				EnemyImpact enemyImpact2;
				do
				{
					enemyImpact2 = enemyImpact;
					enemyImpact = Interlocked.CompareExchange(ref this.m_EnemyImpactEvent, (EnemyImpact)Delegate.Remove(enemyImpact2, value), enemyImpact);
				}
				while (enemyImpact != enemyImpact2);
			}
		}

		public event OtherImpact OtherImpactEvent
		{
			add
			{
				OtherImpact otherImpact = this.m_OtherImpactEvent;
				OtherImpact otherImpact2;
				do
				{
					otherImpact2 = otherImpact;
					otherImpact = Interlocked.CompareExchange(ref this.m_OtherImpactEvent, (OtherImpact)Delegate.Combine(otherImpact2, value), otherImpact);
				}
				while (otherImpact != otherImpact2);
			}
			remove
			{
				OtherImpact otherImpact = this.m_OtherImpactEvent;
				OtherImpact otherImpact2;
				do
				{
					otherImpact2 = otherImpact;
					otherImpact = Interlocked.CompareExchange(ref this.m_OtherImpactEvent, (OtherImpact)Delegate.Remove(otherImpact2, value), otherImpact);
				}
				while (otherImpact != otherImpact2);
			}
		}

		public event FinishAction FinishEvent
		{
			add
			{
				FinishAction finishAction = this.m_FinishEvent;
				FinishAction finishAction2;
				do
				{
					finishAction2 = finishAction;
					finishAction = Interlocked.CompareExchange(ref this.m_FinishEvent, (FinishAction)Delegate.Combine(finishAction2, value), finishAction);
				}
				while (finishAction != finishAction2);
			}
			remove
			{
				FinishAction finishAction = this.m_FinishEvent;
				FinishAction finishAction2;
				do
				{
					finishAction2 = finishAction;
					finishAction = Interlocked.CompareExchange(ref this.m_FinishEvent, (FinishAction)Delegate.Remove(finishAction2, value), finishAction);
				}
				while (finishAction != finishAction2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			lifetimeTimer = new SynchronizedTimer(this, "LT", SetterPermissionMode.AUTHORITY);
			trail = GetComponentInChildren<BulletTrail>();
			tool.SleepOnStart = false;
			tool.SleepOnCleanup = false;
			tool.SuppressAnimateInOut = true;
			tool.PostResetEvent += OnToolReset;
		}

		private void Start()
		{
			tool.SetPickupEnabled(canBePickedUp, this);
			tool.RigidbodyEx.useGravity = useGravity;
			tool.RigidbodyEx.constraints = (faceVelocity ? RigidbodyConstraints.FreezeRotation : RigidbodyConstraints.None);
			tool.RigidbodyEx.collisionDetectionMode = CollisionDetectionMode.ContinuousDynamic;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostResetEvent -= OnToolReset;
		}

		private void Update()
		{
			if (base.hasAuthority && lifetimeTimer.TimerOver)
			{
				AuthorityFinish(timedOut: true);
			}
		}

		private void FixedUpdate()
		{
			if (faceVelocity)
			{
				Vector3 velocity = tool.RigidbodyEx.velocity;
				if (velocity.sqrMagnitude >= 0.001f)
				{
					tool.RigidbodyEx.targetRotation = Quaternion.LookRotation(velocity.normalized, Vector3.up);
				}
			}
		}

		public void AuthorityFire(Vector3 position, Quaternion rotation, Vector3 initialVelocity)
		{
			AuthorityFire(position, rotation, initialVelocity, defaultMaxLifetime);
		}

		public void AuthorityFire(Vector3 position, Quaternion rotation, Vector3 initialVelocity, float lifetime)
		{
			if (base.hasAuthority)
			{
				lifetimeTimer.StartTimer(lifetime);
				tool.AuthorityResetToDefault(position, rotation, sleepPhysics: false);
				tool.RigidbodyEx.velocity = initialVelocity;
			}
		}

		public void AuthorityFinish(bool timedOut = false)
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcFinish, base.transform.position, base.transform.rotation, timedOut, tool.RigidbodyEx.velocity);
				tool.IsEnabled = false;
			}
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (trail != null)
			{
				trail.Clear();
			}
			tool.RigidbodyEx.useGravity = useGravity;
		}

		[PunRPC]
		private void RpcFinish(Vector3 finishPosition, Quaternion finishRotation, bool timedOut, Vector3 finishVelocity)
		{
			if (timedOut)
			{
				if (timeoutParticlesPrefab != null)
				{
					PooledParticle pooledParticle = ObjectPool.Instance.Acquire(timeoutParticlesPrefab);
					if (pooledParticle != null)
					{
						pooledParticle.Play(finishPosition, finishRotation, finishVelocity);
					}
				}
				AudioManager.Play3DSFX(timeoutAudio, finishPosition);
			}
			if (trail != null)
			{
				trail.Clear();
			}
			if (this.FinishEvent != null)
			{
				this.FinishEvent(this, finishPosition, timedOut);
			}
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (collision.contacts == null || collision.contacts.Length == 0)
			{
				return;
			}
			GameObject gameObject = collision.gameObject;
			Vector3 point = collision.contacts[0].point;
			Vector3 normal = collision.contacts[0].normal;
			float magnitude = (point - tool.LastSpawnPosition).magnitude;
			WeaponImpact impact = new WeaponImpact
			{
				Force = tool.RigidbodyEx.velocity.normalized * projectileForce,
				Velocity = tool.RigidbodyEx.velocity,
				Point = point,
				Distance = magnitude,
				SurfaceNormal = normal,
				GameObject = gameObject,
				PreAttackChargeAmount = 0f
			};
			if (gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
			{
				Player.BodyPart bodyPart;
				Player colliderPlayer = collision.collider.GetColliderPlayer(out bodyPart);
				if (colliderPlayer != null && this.PlayerImpactEvent != null)
				{
					this.PlayerImpactEvent(this, colliderPlayer, bodyPart, impact);
				}
			}
			else if (gameObject.IsInLayerMask(LayerMasks.EnemyPhysics))
			{
				EnemyArmorType hitEnemyArmorType;
				Enemy colliderEnemy = collision.collider.GetColliderEnemy(out hitEnemyArmorType);
				if (colliderEnemy != null && this.EnemyImpactEvent != null)
				{
					this.EnemyImpactEvent(this, colliderEnemy, hitEnemyArmorType, impact);
				}
			}
			else if (collision.gameObject.IsInLayerMask(LayerMasks.ToolPhysics))
			{
				Tool colliderTool = collision.collider.GetColliderTool();
				if (colliderTool != tool && colliderTool != null && this.ToolImpactEvent != null)
				{
					this.ToolImpactEvent(this, colliderTool, impact);
				}
			}
			else if (this.OtherImpactEvent != null)
			{
				this.OtherImpactEvent(this, impact);
			}
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestWitchBossEnemy : Enemy
	{
		private enum CombatStates
		{
			RELOCATE = 0,
			POST_RELOCATE_DELAY = 1,
			CHARGE_ATTACK = 2,
			WAITING_FOR_PLAYER_REFLECT = 3,
			PLAYER_REFLECTED = 4,
			REFLECT_PROJECTILE = 5,
			TAKE_DAMAGE = 6,
			INVALID = 65535
		}

		[Header("Patrol")]
		[SerializeField]
		private float postPatrolDelay = 4f;

		[Header("Relocate Phase")]
		[SerializeField]
		private float dashSpeed = 4f;

		[SerializeField]
		private float maxDashForce = 67f;

		[SerializeField]
		private float dashSlowdownDistance = 1f;

		[SerializeField]
		private float dashTimeout = 2.5f;

		[Header("Projectile Volley Phase")]
		[SerializeField]
		private float attackChargeDuration = 1f;

		[SerializeField]
		private float projectileHeadTargetHeightOffset = -0.2f;

		[SerializeField]
		private float reflectionDuration = 0.5f;

		[SerializeField]
		private int requiredReturnCount = 3;

		[SerializeField]
		private int firstVolleyRequiredReturnCount = 3;

		[SerializeField]
		[Range(0f, 1f)]
		private float reselectTargetPlayerChance = 0.2f;

		[Header("Projectile Speed")]
		[SerializeField]
		private AnimationCurve projectileSpeedByHealthCurve;

		[SerializeField]
		private float volleySpeedDelta = 2f;

		[Header("Take Damage")]
		[SerializeField]
		private int takeDamageAmount = 40;

		[SerializeField]
		private float takeDamageDuration = 2f;

		[Header("Disengage")]
		[SerializeField]
		private float postDisengageDelay = 1f;

		private const float MAX_REFLECTION_RETURN_TIME = 8f;

		private SynchronizedField<Vector3> _hitDirection;

		private SynchronizedField<bool> _previousStateWasPatrol;

		private SynchronizedField<int> _reflectionCount;

		private SynchronizedField<Vector3> _relocateTarget;

		private SynchronizedField<float> _timeUntilCollision;

		private SynchronizedStateMachine combatStateMachine;

		private SynchronizedTimer combatStateTimer;

		private EnemyProjectileToolRangedWeapon projectileToolRangedWeapon;

		private WitchPatrolPoints witchRelocatePoints;

		private bool firstRelocate = true;

		private Vector3 HitDirection
		{
			get
			{
				return _hitDirection.Get();
			}
			set
			{
				_hitDirection.Set(value);
			}
		}

		private bool PreviousStateWasPatrol
		{
			get
			{
				return _previousStateWasPatrol.Get();
			}
			set
			{
				_previousStateWasPatrol.Set(value);
			}
		}

		private int ReflectionCount
		{
			get
			{
				return _reflectionCount.Get();
			}
			set
			{
				_reflectionCount.Set(value);
			}
		}

		private Vector3 RelocateTarget
		{
			get
			{
				return _relocateTarget.Get();
			}
			set
			{
				_relocateTarget.Set(value);
			}
		}

		private float TimeUntilCollision
		{
			get
			{
				return _timeUntilCollision.Get();
			}
			set
			{
				_timeUntilCollision.Set(value);
			}
		}

		private int RequiredReturnHitCount
		{
			get
			{
				if (base.Health > base.MaxHealth - takeDamageAmount)
				{
					return firstVolleyRequiredReturnCount;
				}
				return requiredReturnCount;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (rangedWeapon != null)
			{
				projectileToolRangedWeapon = rangedWeapon as EnemyProjectileToolRangedWeapon;
				if (projectileToolRangedWeapon != null)
				{
					projectileToolRangedWeapon.ReflectionEvent += OnProjectileReflection;
					projectileToolRangedWeapon.CustomProjectileEnemyImpactResolution = ProjectileEnemyImpactResolution;
				}
			}
			if (base.Patrol != null)
			{
				witchRelocatePoints = base.Patrol as WitchPatrolPoints;
			}
			if (projectileToolRangedWeapon == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing a Projectile Tool Ranged Weapon.");
			}
			_relocateTarget = new SynchronizedField<Vector3>(this, "RT", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_reflectionCount = new SynchronizedField<int>(this, "RC", 0, SetterPermissionMode.AUTHORITY);
			_hitDirection = new SynchronizedField<Vector3>(this, "HD", Vector3.forward, SetterPermissionMode.AUTHORITY);
			_previousStateWasPatrol = new SynchronizedField<bool>(this, "PSWP", defaultValue: true, SetterPermissionMode.AUTHORITY);
			_timeUntilCollision = new SynchronizedField<float>(this, "TUC", 0f, SetterPermissionMode.AUTHORITY);
			combatStateTimer = new SynchronizedTimer(this, "CT", SetterPermissionMode.AUTHORITY);
			combatStateMachine = new SynchronizedStateMachine("CSM", SetterPermissionMode.AUTHORITY);
			combatStateMachine.AddState(1, OnEnterPostRelocateDelayState, null, OnUpdatePostRelocateDelayState);
			combatStateMachine.AddState(0, OnEnterRelocateState, OnExitRelocateState, OnUpdateRelocateState);
			combatStateMachine.AddState(2, OnEnterChargeAttackState, null, OnUpdateChargeAttackState);
			combatStateMachine.AddState(3, null, null, OnUpdateWaitingForPlayerReflectState);
			combatStateMachine.AddState(4, OnEnterPlayerReflectedState, null, OnUpdatePlayerReflectedState);
			combatStateMachine.AddState(5, OnEnterReflectProjectileState, null, OnUpdateReflectProjectileState);
			combatStateMachine.AddState(6, OnEnterTakeDamageState, OnExitTakeDamageState, OnUpdateTakeDamageState);
		}

		protected override void Start()
		{
			base.Start();
			combatStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (projectileToolRangedWeapon != null)
			{
				projectileToolRangedWeapon.ReflectionEvent -= OnProjectileReflection;
			}
		}

		protected override void Update()
		{
			base.Update();
			combatStateMachine.Update();
			combatStateTimer.UpdateCallbacks();
		}

		protected override void OnPatrolStart()
		{
			base.OnPatrolStart();
			base.Steering.HoverEnabled = false;
			if (base.hasAuthority)
			{
				PreviousStateWasPatrol = true;
			}
		}

		protected override void OnPatrolEnd()
		{
			base.OnPatrolEnd();
			base.Steering.HoverEnabled = true;
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(0);
			}
		}

		protected override void OnActiveCombatEnd()
		{
			base.OnActiveCombatEnd();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(ushort.MaxValue);
			}
		}

		private void ProjectileEnemyImpactResolution(ProjectileTool projectile, Enemy attackingEnemy, Enemy hitEnemy, EnemyArmorType hitArmorType, WeaponImpact impact)
		{
			if (projectile.hasAuthority)
			{
				projectile.Tool.RigidbodyEx.ClearVelocity();
			}
		}

		protected override void OnRangedWeaponLocalFire(EnemyRangedWeapon weapon, float shotDelay)
		{
		}

		private void OnProjectileReflection(ProjectileTool thisProjectile, EnemyProjectileToolRangedWeapon.ReflectionTypes reflectionType, Vector3 point, Vector3 newVelocity)
		{
			if (!(thisProjectile != null) || !thisProjectile.hasAuthority || base.IsDisengaged || base.IsPatroling || base.Health <= 0 || !base.IsAlive)
			{
				return;
			}
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (reflectionType == EnemyProjectileToolRangedWeapon.ReflectionTypes.TO_ENEMY_SUCCESS)
			{
				HitDirection = newVelocity.normalized;
				Vector3 position = projectileToolRangedWeapon.ProjectileOriginTransform.position;
				Vector3 vector = position - point;
				float magnitude = vector.magnitude;
				Vector3 normalized = vector.normalized;
				float magnitude2 = Vector3.Project(newVelocity, normalized).magnitude;
				float num = 0f;
				if (magnitude2 <= Mathf.Epsilon)
				{
					num = reflectionDuration;
				}
				else
				{
					num = magnitude / magnitude2;
					if (num <= 0f || num >= 8f)
					{
						num = reflectionDuration;
					}
					else if (num < reflectionDuration)
					{
						float num2 = num / reflectionDuration;
						thisProjectile.Tool.SetDynamicMaxSpeed(magnitude2 * num2);
						num = reflectionDuration;
					}
				}
				TimeUntilCollision = num;
				combatStateMachine.EnterState(4);
			}
			else
			{
				combatStateMachine.EnterState(0);
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (isPatrolling)
			{
				return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
			}
			FindNearbyTargets(isPatrolling, mustHaveLineOfSight: true, targetScratchSpace);
			if (targetScratchSpace.Count == 0)
			{
				return Combatant.Invalid;
			}
			if (targetScratchSpace.Count == 1)
			{
				return targetScratchSpace[0];
			}
			int num = UnityEngine.Random.Range(0, targetScratchSpace.Count);
			if (base.Target.IsValid && base.Target == targetScratchSpace[num])
			{
				float num2 = 1f / (float)targetScratchSpace.Count;
				float percentageTrue = reselectTargetPlayerChance / num2;
				if (!UnityExtensions.GetRandomResult(percentageTrue))
				{
					int num3 = UnityEngine.Random.Range(1, targetScratchSpace.Count - 1);
					num = (num + num3) % targetScratchSpace.Count;
				}
			}
			return targetScratchSpace[num];
		}

		private void OnEnterRelocateState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxDashForce;
			base.Steering.MaxVerticalSpeed = dashSpeed;
			base.Steering.MaxVerticalSteeringForce = maxDashForce;
			if (base.hasAuthority)
			{
				base.Target = FindTarget();
				RelocateTarget = GetRelocatePosition();
				base.Steering.Seek(RelocateTarget, dashSlowdownDistance, 0.01f, faceVelocity: false, separateHeightSeeking: false);
				combatStateTimer.StartTimer(dashTimeout);
			}
		}

		private void OnUpdateRelocateState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (combatStateTimer.TimerOver || base.Steering.ReachedMainSeekTarget)
			{
				combatStateMachine.EnterState(1);
				return;
			}
			base.Steering.Seek(RelocateTarget, dashSlowdownDistance, 0.01f, faceVelocity: false, separateHeightSeeking: false);
			if (base.Target.IsValid && base.Steering.IsHovering)
			{
				base.Steering.Look(GetLookAtTargetVector(!base.Steering.IsHovering));
			}
		}

		private void OnExitRelocateState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopSeeking();
		}

		private Vector3 GetRelocatePosition()
		{
			if (witchRelocatePoints == null)
			{
				return base.RigidbodyEx.physicsPosition;
			}
			if (firstRelocate && PreviousStateWasPatrol)
			{
				return witchRelocatePoints.GetInitialWitchPoint();
			}
			if (base.Health < takeDamageAmount)
			{
				return witchRelocatePoints.GetFinalWitchPoint();
			}
			firstRelocate = false;
			return witchRelocatePoints.GetRandomWitchPoint();
		}

		private void OnEnterPostRelocateDelayState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				float maxRunningTime = postDisengageDelay;
				if (PreviousStateWasPatrol)
				{
					maxRunningTime = postPatrolDelay;
					PreviousStateWasPatrol = false;
				}
				combatStateTimer.StartTimer(maxRunningTime);
			}
		}

		private void OnUpdatePostRelocateDelayState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(2);
			}
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.PlayRangedAttack();
			enemyAudio.OnAttack();
			if (base.hasAuthority)
			{
				ReflectionCount = 0;
				combatStateTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant target = base.Target;
			if (combatStateTimer.TimerOver)
			{
				if (!base.Target.IsValid)
				{
					base.Target = FindTarget();
				}
				if (base.Target.IsValid)
				{
					float time = Mathf.Clamp01((float)base.Health / (float)base.MaxHealth);
					float desiredSpeed = projectileSpeedByHealthCurve.Evaluate(time);
					projectileToolRangedWeapon.AuthorityFire(base.Target.HeadPosition + Vector3.up * projectileHeadTargetHeightOffset, desiredSpeed);
				}
				combatStateMachine.EnterState(3);
			}
			else if (base.Target.IsValid)
			{
				base.Steering.Look(GetLookAtTargetVector(!base.Steering.IsHovering));
			}
		}

		private void OnUpdateWaitingForPlayerReflectState()
		{
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid || !SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target) || !projectileToolRangedWeapon.ProjectileTool.Tool.IsEnabled)
				{
					combatStateMachine.EnterState(0);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(!base.Steering.IsHovering));
				}
			}
		}

		private void OnEnterPlayerReflectedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				float num = TimeUntilCollision;
				if (ReflectionCount < RequiredReturnHitCount - 1)
				{
					num = Mathf.Max(0f, num - reflectionDuration);
				}
				combatStateTimer.StartTimer(num);
			}
		}

		private void OnUpdatePlayerReflectedState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				if (ReflectionCount >= RequiredReturnHitCount - 1)
				{
					combatStateMachine.EnterState(6);
				}
				else
				{
					combatStateMachine.EnterState(5);
				}
			}
		}

		private void OnEnterReflectProjectileState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.PlayMeleeAttack();
			if (base.hasAuthority)
			{
				ReflectionCount++;
				combatStateTimer.StartTimer(reflectionDuration);
			}
		}

		private void OnUpdateReflectProjectileState()
		{
			if (!base.hasAuthority || !combatStateTimer.TimerOver)
			{
				return;
			}
			base.Target = FindTarget();
			if (!base.Target.IsValid)
			{
				combatStateMachine.EnterState(0);
				return;
			}
			float time = Mathf.Clamp01((float)base.Health / (float)base.MaxHealth);
			float num = projectileSpeedByHealthCurve.Evaluate(time);
			float speed = num + (float)ReflectionCount * volleySpeedDelta;
			Vector3 target = base.Target.HeadPosition + Vector3.up * projectileHeadTargetHeightOffset;
			if (projectileToolRangedWeapon.ProjectileTool.Tool.IsEnabled)
			{
				projectileToolRangedWeapon.AuthorityReflect(target, speed);
			}
			else
			{
				Vector3 position = projectileToolRangedWeapon.ProjectileOriginTransform.position;
				Quaternion rotation = projectileToolRangedWeapon.ProjectileOriginTransform.rotation;
				projectileToolRangedWeapon.AuthorityReflect(target, speed, position, rotation);
			}
			combatStateMachine.EnterState(3);
		}

		private void OnEnterTakeDamageState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.StartStun(isInterrupted: false);
			if (base.hasAuthority)
			{
				projectileToolRangedWeapon.ProjectileTool.AuthorityFinish();
				Vector3 point = base.RigidbodyEx.physicsPosition - HitDirection * 0.5f;
				WeaponImpact impact = WeaponImpact.Default;
				impact.Point = point;
				impact.SurfaceNormal = HitDirection;
				AuthorityTryApplyAttack(this, WeaponDamageType.SELF_ATTACK, EnemyArmorType.NORMAL, takeDamageAmount, impact);
				AuthorityOnDamageApplyForce(WeaponDamageType.DEFAULT, EnemyArmorType.NORMAL, HitDirection, base.transform.position);
				combatStateTimer.StartTimer(takeDamageDuration);
			}
		}

		private void OnUpdateTakeDamageState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(0);
			}
		}

		private void OnExitTakeDamageState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.StopStun();
		}

		protected override void OnDisengagedStart()
		{
			base.OnDisengagedStart();
			base.CollidersEnabled = false;
			base.Steering.MaxHorizontalSpeed = dashSpeed;
			base.Steering.MaxVerticalSpeed = dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxDashForce;
			base.Steering.MaxVerticalSteeringForce = maxDashForce;
			if (base.hasAuthority)
			{
				PreviousStateWasPatrol = false;
				RelocateTarget = witchRelocatePoints.GetRetreatWitchPoint();
				base.Steering.Seek(RelocateTarget, movementSlowdownDistance, 0.25f, faceVelocity: false, separateHeightSeeking: false);
			}
		}

		protected override void OnDisengagedUpdate()
		{
			base.OnDisengagedUpdate();
			if (base.hasAuthority && !base.Steering.ReachedMainSeekTarget)
			{
				base.Steering.Seek(RelocateTarget, movementSlowdownDistance, 0.25f, faceVelocity: false, separateHeightSeeking: false);
			}
		}

		protected override void OnDisengagedEnd()
		{
			base.OnDisengagedEnd();
			base.Steering.StopAll();
			base.CollidersEnabled = true;
		}

		private bool ProjectileIsTravelingTowardsPoint(Vector3 point)
		{
			Vector3 velocity = projectileToolRangedWeapon.ProjectileTool.Tool.RigidbodyEx.velocity;
			if (!(velocity.sqrMagnitude >= 0.1f))
			{
				return false;
			}
			Vector3 lhs = point - projectileToolRangedWeapon.ProjectileTool.transform.position;
			return Vector3.Dot(lhs, velocity) >= 0f;
		}
	}
}
[RequireComponent(typeof(PhotonView))]
public class SteamTrap : Trap
{
	private enum States
	{
		INVALID,
		DELAY,
		OFF,
		WARNING,
		ON
	}

	[Header("Emission")]
	[SerializeField]
	private Transform[] steamEmissionTransforms;

	[SerializeField]
	private OverlapVolume collisionVolume;

	[Header("Timing")]
	[SerializeField]
	private float initialDelay;

	[SerializeField]
	private float offDuration = 3f;

	[SerializeField]
	private float warningDuration = 1f;

	[SerializeField]
	private float onDuration = 2f;

	[Header("Particles")]
	[SerializeField]
	private PooledParticle warningParticlesPrefab;

	[SerializeField]
	private PooledParticle steamParticlesPrefab;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip warningLoopingAudio;

	[SerializeField]
	private RecRoomAudioClip steamLoopingAudio;

	private const float MIN_PLAYER_COLLISION_TEST_DISTANCE = 5f;

	private const float MIN_PLAYER_COLLISION_TEST_DISTANCE_SQR = 25f;

	private SFXAudioSource currentLoopingAudio;

	private List<PooledParticle> currentParticles = new List<PooledParticle>();

	private SynchronizedStateMachine stateMachine;

	private SynchronizedTimer stateTimer;

	protected override void Awake()
	{
		base.Awake();
		stateTimer = new SynchronizedTimer(this, "ST", SetterPermissionMode.AUTHORITY);
		stateMachine = new SynchronizedStateMachine("SM", SetterPermissionMode.AUTHORITY);
		stateMachine.AddState(0, null, null, null);
		stateMachine.AddState(1, OnEnterDelayState, null, OnUpdateDelayState);
		stateMachine.AddState(2, OnEnterOffState, null, OnUpdateOffState);
		stateMachine.AddState(3, OnEnterWarningState, OnExitWarningState, OnUpdateWarningState);
		stateMachine.AddState(4, OnEnterOnState, OnExitOnState, OnUpdateOnState);
		stateMachine.Start(this, 1);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		StopParticles();
		StopLoopingAudio();
	}

	private void Update()
	{
		stateMachine.Update();
		stateTimer.UpdateCallbacks();
	}

	protected override void OnIsEnabledChange()
	{
		base.OnIsEnabledChange();
		if (base.IsEnabled)
		{
			if (base.hasAuthority)
			{
				stateMachine.EnterState(1);
			}
			return;
		}
		StopParticles();
		StopLoopingAudio();
		if (base.hasAuthority)
		{
			stateMachine.EnterState(0);
		}
	}

	private void OnEnterDelayState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			stateTimer.StartTimer(initialDelay);
		}
	}

	private void OnUpdateDelayState()
	{
		if (base.hasAuthority && stateTimer.TimerOver)
		{
			stateMachine.EnterState(2);
		}
	}

	private void OnEnterOffState(ushort previousStateId, ushort previousSubStateId)
	{
		if (base.hasAuthority)
		{
			stateTimer.StartTimer(offDuration);
		}
	}

	private void OnUpdateOffState()
	{
		if (base.hasAuthority && stateTimer.TimerOver)
		{
			stateMachine.EnterState(3);
		}
	}

	private void OnEnterWarningState(ushort previousStateId, ushort previousSubStateId)
	{
		for (int i = 0; i < steamEmissionTransforms.Length; i++)
		{
			PlayParticles(steamEmissionTransforms[i], warningParticlesPrefab, warningDuration);
		}
		StartLoopingAudio(warningLoopingAudio);
		if (base.hasAuthority)
		{
			stateTimer.StartTimer(warningDuration);
		}
	}

	private void OnUpdateWarningState()
	{
		if (base.hasAuthority && stateTimer.TimerOver)
		{
			stateMachine.EnterState(4);
		}
	}

	private void OnExitWarningState(ushort nextStateId, ushort nextSubStateId)
	{
		StopLoopingAudio();
	}

	private void OnEnterOnState(ushort previousStateId, ushort previousSubStateId)
	{
		for (int i = 0; i < steamEmissionTransforms.Length; i++)
		{
			PlayParticles(steamEmissionTransforms[i], steamParticlesPrefab, onDuration);
		}
		StartLoopingAudio(steamLoopingAudio);
		if (base.hasAuthority)
		{
			stateTimer.StartTimer(onDuration);
		}
	}

	private void OnUpdateOnState()
	{
		UpdateCollision();
		if (base.hasAuthority && stateTimer.TimerOver)
		{
			stateMachine.EnterState(2);
		}
	}

	private void OnExitOnState(ushort nextStateId, ushort nextSubStateId)
	{
		StopLoopingAudio();
	}

	private void PlayParticles(Transform emissionTransform, PooledParticle particlePrefab, float duration)
	{
		if (particlePrefab != null)
		{
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(particlePrefab);
			if (pooledParticle != null)
			{
				currentParticles.Add(pooledParticle);
				pooledParticle.SetDuration(duration);
				pooledParticle.Play(emissionTransform.position, emissionTransform.rotation);
			}
		}
	}

	private void StopParticles()
	{
		for (int i = 0; i < currentParticles.Count; i++)
		{
			if (currentParticles[i] != null)
			{
				currentParticles[i].Stop();
			}
		}
		currentParticles.Clear();
	}

	private void StartLoopingAudio(RecRoomAudioClip loopingAudioClip)
	{
		StopLoopingAudio();
		currentLoopingAudio = AudioManager.StartLooping3DSFX(loopingAudioClip, base.transform);
	}

	private void StopLoopingAudio()
	{
		if (currentLoopingAudio != null)
		{
			AudioManager.StopLoopingSFX(currentLoopingAudio);
			currentLoopingAudio = null;
		}
	}

	private void UpdateCollision()
	{
		if (Player.LocalPlayerExists && (collisionVolume.transform.position - Player.LocalPlayer.Head.transform.position).sqrMagnitude <= 25f)
		{
			bool flag = false;
			Player.BodyPart hitBodyPart = Player.BodyPart.None;
			Vector3 point = Vector3.zero;
			if (collisionVolume.ContainsPoint(Player.LocalPlayer.Head.transform.position))
			{
				flag = true;
				hitBodyPart = Player.BodyPart.Head;
				point = Player.LocalPlayer.Head.transform.position;
			}
			else if (collisionVolume.ContainsPoint(Player.LocalPlayer.LeftHand.transform.position))
			{
				flag = true;
				hitBodyPart = Player.BodyPart.LeftHand;
				point = Player.LocalPlayer.LeftHand.transform.position;
			}
			else if (collisionVolume.ContainsPoint(Player.LocalPlayer.RightHand.transform.position))
			{
				flag = true;
				hitBodyPart = Player.BodyPart.RightHand;
				point = Player.LocalPlayer.RightHand.transform.position;
			}
			if (flag)
			{
				PlayerHit(impact: new WeaponImpact
				{
					Point = point
				}, hitPlayer: Player.LocalPlayer, hitBodyPart: hitBodyPart);
			}
		}
	}
}
public class WandProjectileParticles : PooledParticle
{
	private struct VelocityLimit
	{
		public bool Enabled;

		public float Multiplier;

		public float Damping;
	}

	[SerializeField]
	private ParticleSystem[] particleSystemsWithVelocity;

	private VelocityLimit[] systemVelocityLimitMultipliers;

	private float[] systemGravityMultipliers;

	protected override void Awake()
	{
		base.Awake();
		systemVelocityLimitMultipliers = new VelocityLimit[particleSystemsWithVelocity.Length];
		systemGravityMultipliers = new float[particleSystemsWithVelocity.Length];
		for (int i = 0; i < particleSystemsWithVelocity.Length; i++)
		{
			ParticleSystem.LimitVelocityOverLifetimeModule limitVelocityOverLifetime = particleSystemsWithVelocity[i].limitVelocityOverLifetime;
			ref VelocityLimit reference = ref systemVelocityLimitMultipliers[i];
			reference = new VelocityLimit
			{
				Enabled = limitVelocityOverLifetime.enabled,
				Multiplier = limitVelocityOverLifetime.limitMultiplier,
				Damping = limitVelocityOverLifetime.dampen
			};
			ParticleSystem.MainModule main = particleSystemsWithVelocity[i].main;
			systemGravityMultipliers[i] = main.gravityModifierMultiplier;
		}
	}

	public void ResetVelocity()
	{
		for (int i = 0; i < particleSystemsWithVelocity.Length; i++)
		{
			ParticleSystem.MainModule main = particleSystemsWithVelocity[i].main;
			main.gravityModifierMultiplier = systemGravityMultipliers[i];
			ParticleSystem.LimitVelocityOverLifetimeModule limitVelocityOverLifetime = particleSystemsWithVelocity[i].limitVelocityOverLifetime;
			limitVelocityOverLifetime.enabled = systemVelocityLimitMultipliers[i].Enabled;
			limitVelocityOverLifetime.limitMultiplier = systemVelocityLimitMultipliers[i].Multiplier;
			limitVelocityOverLifetime.dampen = systemVelocityLimitMultipliers[i].Damping;
		}
	}

	public void StopVelocity()
	{
		for (int i = 0; i < particleSystemsWithVelocity.Length; i++)
		{
			ParticleSystem.MainModule main = particleSystemsWithVelocity[i].main;
			main.gravityModifierMultiplier = 0f;
			ParticleSystem.LimitVelocityOverLifetimeModule limitVelocityOverLifetime = particleSystemsWithVelocity[i].limitVelocityOverLifetime;
			limitVelocityOverLifetime.enabled = true;
			limitVelocityOverLifetime.limitMultiplier = 0f;
			limitVelocityOverLifetime.dampen = 1f;
		}
	}
}
