[RequireComponent(typeof(PhotonView))]
public class DestructibleTrap : Trap
{
	private enum State
	{
		IDLE,
		DAMAGED,
		DESTROYED
	}

	[SerializeField]
	private bool hasLimitedAllowedDamageTypes;

	[SerializeField]
	private WeaponDamageType[] allowedDamageTypes;

	[SerializeField]
	private float damagedDuration = 1f;

	[SerializeField]
	private RecRoomAudioClip damageAudio;

	private SynchronizedTimer stateTimer;

	private SynchronizedStateMachine stateMachine;

	private Transform parent;

	private Vector3 initialLocalPosition = Vector3.zero;

	private Quaternion initialLocalRotation = Quaternion.identity;

	protected override void Awake()
	{
		base.Awake();
		parent = base.transform.parent;
		initialLocalPosition = base.transform.localPosition;
		initialLocalRotation = base.transform.localRotation;
		stateTimer = new SynchronizedTimer(this, "ST", SetterPermissionMode.AUTHORITY);
		stateMachine = new SynchronizedStateMachine("SSM", SetterPermissionMode.AUTHORITY);
		stateMachine.AddState(0, OnEnterIdleState, null, null);
		stateMachine.AddState(1, OnEnterDamagedState, null, OnUpdateDamagedState);
		stateMachine.AddState(2, OnEnterDestroyedState, null, null);
	}

	protected override void Start()
	{
		base.Start();
		stateMachine.Start(this, 0);
	}

	private void Update()
	{
		stateMachine.Update();
		stateTimer.UpdateCallbacks();
	}

	public override void AuthorityApplyDamage(WeaponDamageType damageType, int damage, Vector3 point, Vector3 normal)
	{
		base.AuthorityApplyDamage(damageType, damage, point, normal);
		if ((!hasLimitedAllowedDamageTypes || allowedDamageTypes == null || allowedDamageTypes.Contains(damageType)) && base.hasAuthority && stateMachine.CurrentStateId == 0)
		{
			base.photonView.RpcAll(RpcOnDamage, point);
			stateMachine.EnterState(1);
		}
	}

	[PunRPC]
	protected void RpcOnDamage(Vector3 point)
	{
		AudioManager.Play3DSFX(damageAudio, point);
	}

	private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
	{
		base.RigidbodyEx.AddKinematic(this);
		base.transform.SetParent(parent);
		base.transform.localPosition = initialLocalPosition;
		base.transform.localRotation = initialLocalRotation;
	}

	private void OnEnterDamagedState(ushort previousStateId, ushort previousSubStateId)
	{
		base.RigidbodyEx.RemoveKinematic(this);
		base.transform.SetParent(null, worldPositionStays: true);
		if (base.hasAuthority)
		{
			stateTimer.StartTimer(damagedDuration);
		}
	}

	private void OnUpdateDamagedState()
	{
		if (base.hasAuthority && stateTimer.TimerOver)
		{
			stateMachine.EnterState(2);
		}
	}

	private void OnEnterDestroyedState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisable();
		}
	}
}
namespace RecRoom.Core.GameManagement
{
	[RequireComponent(typeof(BaseOpenableChest))]
	public class EquipmentSpawnerChest : Photon.MonoBehaviour
	{
		public delegate void EquipmentSpawnerChestAction(EquipmentSpawnerChest thisChest);

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private BaseOpenableChest chest;

		[AutofillOptional(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		private SparkleOutline sparkleEffect;

		[Header("Configuration")]
		[FormerlySerializedAs("lootSpawnOrigin")]
		[SerializeField]
		private Transform spawnOrigin;

		[Header("Spawn Arc")]
		[SerializeField]
		private float spawnArcAngle = 120f;

		[SerializeField]
		private float spawnArcAngleMinRandomOffset = -0.1f;

		[SerializeField]
		private float spawnArcAngleMaxRandomOffset = 0.1f;

		[FormerlySerializedAs("lootSpawnRadius")]
		[SerializeField]
		private float spawnRadius = 1f;

		[Header("Spawn Physics")]
		[SerializeField]
		private float spawnSpeed = 1f;

		[SerializeField]
		private float spawnSpeedRandomMultiplier = 1.15f;

		[SerializeField]
		private float spawnMaxAngularSpeed = 15f;

		private SynchronizedField<bool> _isEnabled;

		public static readonly List<EquipmentSpawnerChest> AllChests = new List<EquipmentSpawnerChest>();

		public static EquipmentSpawnerChestAction ChestOpenEvent = null;

		public bool IsEnabled
		{
			get
			{
				return _isEnabled.Get();
			}
			set
			{
				_isEnabled.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_isEnabled = new SynchronizedField<bool>(this, "SIE", defaultValue: true, SetterPermissionMode.MASTER, OnIsEnabledChange);
			BaseOpenableChest baseOpenableChest = chest;
			baseOpenableChest.CloseEvent = (BaseOpenableChest.ChestAction)Delegate.Combine(baseOpenableChest.CloseEvent, new BaseOpenableChest.ChestAction(OnChestClose));
			BaseOpenableChest baseOpenableChest2 = chest;
			baseOpenableChest2.OpeningEvent = (BaseOpenableChest.ChestAction)Delegate.Combine(baseOpenableChest2.OpeningEvent, new BaseOpenableChest.ChestAction(OnChestOpening));
			BaseOpenableChest baseOpenableChest3 = chest;
			baseOpenableChest3.OpenEvent = (BaseOpenableChest.ChestAction)Delegate.Combine(baseOpenableChest3.OpenEvent, new BaseOpenableChest.ChestAction(OnChestOpen));
			AllChests.Add(this);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			AllChests.Remove(this);
			BaseOpenableChest baseOpenableChest = chest;
			baseOpenableChest.CloseEvent = (BaseOpenableChest.ChestAction)Delegate.Remove(baseOpenableChest.CloseEvent, new BaseOpenableChest.ChestAction(OnChestClose));
			BaseOpenableChest baseOpenableChest2 = chest;
			baseOpenableChest2.OpeningEvent = (BaseOpenableChest.ChestAction)Delegate.Remove(baseOpenableChest2.OpeningEvent, new BaseOpenableChest.ChestAction(OnChestOpening));
			BaseOpenableChest baseOpenableChest3 = chest;
			baseOpenableChest3.OpenEvent = (BaseOpenableChest.ChestAction)Delegate.Remove(baseOpenableChest3.OpenEvent, new BaseOpenableChest.ChestAction(OnChestOpen));
		}

		private void Start()
		{
			OnIsEnabledChange();
		}

		public void MasterEnable(bool enabled)
		{
			if (PhotonNetwork.isMasterClient)
			{
				IsEnabled = enabled;
			}
		}

		public void MasterReset()
		{
			if (chest != null)
			{
				chest.MasterReset();
			}
		}

		public void GetEquipmentSpawnPhysics(float normalizedArcAngle, out Vector3 position, out Quaternion orientation, out Vector3 linearVelocity, out Vector3 angularVelocity)
		{
			position = spawnOrigin.position;
			Vector3 normalized = Vector3.ProjectOnPlane(spawnOrigin.forward, Vector3.up).normalized;
			orientation = Quaternion.LookRotation(normalized, Vector3.up);
			normalizedArcAngle += UnityEngine.Random.Range(spawnArcAngleMinRandomOffset, spawnArcAngleMaxRandomOffset);
			float angle = Mathf.Lerp((0f - spawnArcAngle) / 2f, spawnArcAngle / 2f, normalizedArcAngle);
			linearVelocity = Quaternion.AngleAxis(angle, spawnOrigin.up) * spawnOrigin.forward * spawnSpeed;
			linearVelocity *= UnityEngine.Random.Range(1f, spawnSpeedRandomMultiplier);
			angularVelocity = Vector3.up * UnityEngine.Random.Range(0f - spawnMaxAngularSpeed, spawnMaxAngularSpeed);
		}

		private void OnChestClose(BaseOpenableChest chest)
		{
			if (sparkleEffect != null)
			{
				sparkleEffect.enabled = true;
			}
		}

		private void OnChestOpening(BaseOpenableChest chest)
		{
			if (sparkleEffect != null)
			{
				sparkleEffect.enabled = false;
			}
		}

		private void OnChestOpen(BaseOpenableChest chest)
		{
			if (sparkleEffect != null)
			{
				sparkleEffect.enabled = false;
			}
			if (ChestOpenEvent != null)
			{
				ChestOpenEvent(this);
			}
		}

		private void OnIsEnabledChange()
		{
			base.gameObject.SetActive(IsEnabled);
		}

		private void OnDrawGizmosSelected()
		{
			if (spawnOrigin != null)
			{
				Gizmos.color = Color.yellow;
				Vector3 position = spawnOrigin.position;
				Vector3 normalized = Vector3.ProjectOnPlane(spawnOrigin.forward, Vector3.up).normalized;
				Vector3 vector = spawnOrigin.position + normalized * spawnRadius;
				Gizmos.DrawLine(position, vector);
				Vector3 gizmoArcVertex = GetGizmoArcVertex((0f - spawnArcAngle) / 2f, normalized);
				Gizmos.DrawLine(position, gizmoArcVertex);
				Vector3 gizmoArcVertex2 = GetGizmoArcVertex((0f - spawnArcAngle) / 4f, normalized);
				Gizmos.DrawLine(position, gizmoArcVertex2);
				Vector3 gizmoArcVertex3 = GetGizmoArcVertex(spawnArcAngle / 4f, normalized);
				Gizmos.DrawLine(position, gizmoArcVertex3);
				Vector3 gizmoArcVertex4 = GetGizmoArcVertex(spawnArcAngle / 2f, normalized);
				Gizmos.DrawLine(position, gizmoArcVertex4);
				Gizmos.DrawLine(gizmoArcVertex, gizmoArcVertex2);
				Gizmos.DrawLine(gizmoArcVertex2, vector);
				Gizmos.DrawLine(vector, gizmoArcVertex3);
				Gizmos.DrawLine(gizmoArcVertex3, gizmoArcVertex4);
			}
		}

		private Vector3 GetGizmoArcVertex(float angle, Vector3 forward)
		{
			return spawnOrigin.position + Quaternion.AngleAxis(angle, Vector3.up) * forward * spawnRadius;
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class JigsawPuzzle : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private struct PieceData
		{
			public JigsawPuzzlePiece Piece;

			public Transform SolvedTransform;
		}

		[SerializeField]
		private PieceData[] pieces;

		public bool Completed
		{
			get
			{
				for (int i = 0; i < pieces.Length; i++)
				{
					if (!pieces[i].Piece.IsPlaced)
					{
						return false;
					}
				}
				return true;
			}
		}

		private void Awake()
		{
			for (int i = 0; i < pieces.Length; i++)
			{
				pieces[i].Piece.PlacementTransform = pieces[i].SolvedTransform;
			}
		}
	}
	public class JigsawPuzzlePiece : Photon.MonoBehaviour
	{
		private enum State
		{
			NOT_PLACED,
			PLACED
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[AutofillOptional(AutofillType.Self, false)]
		[SerializeField]
		private SparkleOutline sparkleOutline;

		[SerializeField]
		private float placementRadius = 0.2f;

		[SerializeField]
		private RecRoomAudioClip placementAudio;

		[NonSerialized]
		public Transform PlacementTransform;

		private SynchronizedStateMachine stateMachine;

		public bool IsPlaced => stateMachine.CurrentStateId == 1;

		protected override void Awake()
		{
			base.Awake();
			tool.PostReleaseEvent += OnToolPostRelease;
			tool.PostResetEvent += OnToolReset;
			tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			stateMachine = new SynchronizedStateMachine("SSM", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, OnEnterNotPlacedState, null, null);
			stateMachine.AddState(1, OnEnterPlacedState, OnExitPlacedState, null);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostReleaseEvent -= OnToolPostRelease;
			tool.PostResetEvent -= OnToolReset;
		}

		private void OnToolPostRelease(Tool tool)
		{
			AuthorityTryPlace();
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (base.hasAuthority)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnEnterNotPlacedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (sparkleOutline != null)
			{
				sparkleOutline.enabled = true;
			}
			tool.RigidbodyEx.RemoveKinematic(this);
			tool.EnablePickup(this);
			AuthorityTryPlace();
		}

		private void OnEnterPlacedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (sparkleOutline != null)
			{
				sparkleOutline.enabled = false;
			}
			if (base.hasAuthority)
			{
				base.transform.position = PlacementTransform.position;
				base.transform.rotation = PlacementTransform.rotation;
			}
			tool.RigidbodyEx.AddKinematic(this);
			tool.DisablePickup(this);
			if (tool.ToolCleanup != null)
			{
				tool.ToolCleanup.PauseCleanup(this);
			}
		}

		private void OnExitPlacedState(ushort nextStateId, ushort nextSubStateId)
		{
			if (tool != null && tool.ToolCleanup != null)
			{
				tool.ToolCleanup.ResumeCleanup(this);
			}
		}

		private void AuthorityTryPlace()
		{
			if (base.hasAuthority && stateMachine.CurrentStateId == 0 && !(PlacementTransform == null))
			{
				if ((PlacementTransform.position - base.transform.position).sqrMagnitude <= placementRadius * placementRadius)
				{
					stateMachine.EnterState(1);
				}
				base.photonView.RpcAll(RpcOnPlace);
			}
		}

		[PunRPC]
		protected void RpcOnPlace()
		{
			AudioManager.Play3DSFX(placementAudio, PlacementTransform.position);
		}
	}
}
namespace RecRoom.Core.GameManagement
{
	public class LootTool : CurrencyTool
	{
		public delegate void LootToolAction(LootTool thisLootTool);

		[SerializeField]
		private LootManager.LootType lootType;

		[SerializeField]
		[Tooltip("Only for CUSTOM_VALUE Loot Type")]
		private int customValue;

		[Header("Feedback")]
		[SerializeField]
		private bool beaconOnlyEnabledWhenDespawning = true;

		[SerializeField]
		private float blinkFeedbackTimeRemaining = 3f;

		[SerializeField]
		private float blinkFeedbackMinFrequency = 10f;

		[SerializeField]
		private float blinkFeedbackMaxFrequency = 20f;

		[SerializeField]
		private PooledParticle pickupVFXPrefab;

		[Header("Name Tag")]
		[SerializeField]
		private GameObject nameTagCanvas;

		[SerializeField]
		private Text nameTag;

		private bool _cachedIsLostLoot;

		private long _cachedLostLootOwnerPlayerId = -1L;

		private float _cachedLostLootValue;

		private SynchronizedTimer lifeTimer;

		private SynchronizedField<bool> _alreadyPickedUp;

		private SynchronizedField<bool, long, float> _lostLootData;

		private SynchronizedField<bool> _isDespawning;

		public static LootToolAction CollectEvent;

		public LootManager.LootType LootType => lootType;

		public int CustomValue => customValue;

		public PooledParticle PickupVFXPrefab => pickupVFXPrefab;

		public bool IsLostLoot => _cachedIsLostLoot;

		public long LostLootOwnerId => _cachedLostLootOwnerPlayerId;

		public float LostLootValue => _cachedLostLootValue;

		public override bool AlreadyPickedUp => _alreadyPickedUp.Get();

		private bool IsDespawning => _isDespawning.Get();

		protected override void Awake()
		{
			base.Awake();
			lifeTimer = new SynchronizedTimer(this, "SST", SetterPermissionMode.AUTHORITY);
			_alreadyPickedUp = new SynchronizedField<bool>(this, "SAPU", defaultValue: false, SetterPermissionMode.MASTER);
			_lostLootData = new SynchronizedField<bool, long, float>(this, "SLLD", defaultVal1: false, -1L, 0f, SetterPermissionMode.MASTER, OnLostLootDataChange);
			_isDespawning = new SynchronizedField<bool>(this, "SIS", defaultValue: false, SetterPermissionMode.AUTHORITY, OnIsDespawningChange);
			tool.AddCustomPickupCondition(CustomPickupCondition);
			Profiles.OnProfileUpdated += OnRecNetProfileUpdate;
		}

		protected override void Start()
		{
			base.Start();
			OnLostLootDataChange();
			OnIsDespawningChange();
		}

		protected override void Update()
		{
			base.Update();
			if (!IsDespawning)
			{
				return;
			}
			if (pulsingBeam != null)
			{
				float timeRemaining = lifeTimer.TimeRemaining;
				if (timeRemaining <= blinkFeedbackTimeRemaining)
				{
					pulsingBeam.IsBlinking = true;
					float t = Mathf.InverseLerp(blinkFeedbackTimeRemaining, 0f, timeRemaining);
					pulsingBeam.BlinkFrequency = Mathf.SmoothStep(blinkFeedbackMinFrequency, blinkFeedbackMaxFrequency, t);
				}
				else
				{
					pulsingBeam.IsBlinking = false;
				}
			}
			if (base.hasAuthority && lifeTimer.TimerOver)
			{
				tool.AuthorityDisableAndMovetoLastSpawnPoint();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Profiles.OnProfileUpdated -= OnRecNetProfileUpdate;
		}

		private void OnLostLootDataChange()
		{
			_cachedIsLostLoot = _lostLootData.Get1();
			_cachedLostLootOwnerPlayerId = _lostLootData.Get2();
			_cachedLostLootValue = _lostLootData.Get3();
			UpdateNameTag();
		}

		private void OnRecNetProfileUpdate(long playerId)
		{
			if (_cachedIsLostLoot && _cachedLostLootOwnerPlayerId == playerId)
			{
				UpdateNameTag();
			}
		}

		private void UpdateNameTag()
		{
			if (!(nameTagCanvas == null) && !(nameTag == null))
			{
				nameTagCanvas.SetActive(_cachedIsLostLoot);
				if (_cachedIsLostLoot)
				{
					Profile profile = Profiles.Get(_cachedLostLootOwnerPlayerId);
					nameTag.text = ((profile == null) ? string.Empty : ((string)profile.DisplayName));
				}
			}
		}

		public void MasterInitializeAsLostLoot(long playerId, float lootValue)
		{
			if (PhotonNetwork.isMasterClient)
			{
				_lostLootData.Set(newValue1: true, playerId, lootValue);
			}
		}

		public void MasterStartDespawn(float lifetime)
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				_isDespawning.Set(newValue: true);
				lifeTimer.StartTimer(lifetime);
			}
		}

		public void MasterSetAlreadyPickedUp()
		{
			if (PhotonNetwork.isMasterClient)
			{
				_alreadyPickedUp.Set(newValue: true);
			}
		}

		protected override void OnToolReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			base.OnToolReset(tool, position, rotation, oldPosition, wasCleanedUp);
			if (PhotonNetwork.isMasterClient)
			{
				_lostLootData.Set(newValue1: false, -1L, 0f);
				_alreadyPickedUp.Set(newValue: false);
			}
			if (base.hasAuthority)
			{
				_isDespawning.Set(newValue: false);
			}
		}

		protected override void OnPickup(Tool tool)
		{
			base.OnPickup(tool);
			if (!AlreadyPickedUp && CollectEvent != null)
			{
				CollectEvent(this);
			}
		}

		private bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return !_cachedIsLostLoot || _cachedLostLootOwnerPlayerId == selectingPlayer.PlayerId;
		}

		private void OnIsDespawningChange()
		{
			if (pulsingBeam != null)
			{
				pulsingBeam.gameObject.SetActive(IsDespawning || !beaconOnlyEnabledWhenDespawning);
			}
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestCannon : ExplosiveRangedWeapon
	{
		public delegate void QuestCannonAction(QuestCannon thisCannon);

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private SwivelTool swivel;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private DelayedRangedWeaponTrigger trigger;

		[SerializeField]
		private QuestCannonLighter lighter;

		[Header("Enemy Interaction")]
		[SerializeField]
		private float minEnemyWieldYawAngle = -45f;

		[SerializeField]
		private float maxEnemyWieldYawAngle = 45f;

		[SerializeField]
		private float minEnemyWieldPitchAngle = -30f;

		[SerializeField]
		private float maxEnemyWieldPitchAngle = 30f;

		[Header("Lighter Interaction")]
		[SerializeField]
		private Transform lighterHolsterTransform;

		[SerializeField]
		private Transform wickTransform;

		private static List<QuestCannon> _activeCannons = new List<QuestCannon>();

		public QuestCannonAction WielderChangeEvent;

		public QuestCannonLighter Lighter => lighter;

		public Transform LighterHolsterTransform => lighterHolsterTransform;

		public Transform WickTransform => wickTransform;

		public static IEnumerable<QuestCannon> ActiveCannons => _activeCannons;

		public float MinEnemyWieldYawAngleNormalized => (!(swivel.Handle != null)) ? 0f : swivel.Handle.GetNormalizedYawAngleFromAbsoluteYawAngle(minEnemyWieldYawAngle);

		public float MaxEnemyWieldYawAngleNormalized => (!(swivel.Handle != null)) ? 1f : swivel.Handle.GetNormalizedYawAngleFromAbsoluteYawAngle(maxEnemyWieldYawAngle);

		public float MinEnemyWieldPitchAngleNormalized => (!(swivel.Handle != null)) ? 0f : swivel.Handle.GetNormalizedPitchAngleFromAbsolutePitchAngle(minEnemyWieldPitchAngle);

		public float MaxEnemyWieldPitchAngleNormalized => (!(swivel.Handle != null)) ? 0f : swivel.Handle.GetNormalizedPitchAngleFromAbsolutePitchAngle(maxEnemyWieldPitchAngle);

		protected override void Awake()
		{
			base.Awake();
			if (swivel.Handle != null && swivel.Handle.Tool != null)
			{
				swivel.Handle.Tool.AddCustomPickupCondition(CustomHandlePickupCondition);
			}
			if (trigger != null)
			{
				trigger.TriggeredEvent += OnCannonFire;
			}
		}

		protected override void Start()
		{
			base.Start();
			base.Tool.RigidbodyEx.AddKinematic(this);
			base.Tool.DisablePickup(this);
		}

		protected void OnEnable()
		{
			_activeCannons.Add(this);
		}

		protected void OnDisable()
		{
			_activeCannons.Remove(this);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (trigger != null)
			{
				trigger.TriggeredEvent -= OnCannonFire;
			}
		}

		public void RequestFire(PhotonPlayer firingPlayer = null)
		{
			base.photonView.RpcPlayer(base.authority, RpcRequestFire, firingPlayer);
		}

		[PunRPC]
		protected void RpcRequestFire(PhotonPlayer firingPlayer)
		{
			if (base.hasAuthority)
			{
				if (firingPlayer != null)
				{
					base.Wielder = new Combatant(firingPlayer);
				}
				trigger.AuthorityTryFire();
			}
		}

		protected override void OnWielderChange()
		{
			base.OnWielderChange();
			if (WielderChangeEvent != null)
			{
				WielderChangeEvent(this);
			}
		}

		private bool CustomHandlePickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return base.Wielder.Enemy == null || base.Wielder.Enemy.Health <= 0 || !base.Wielder.Enemy.IsAlive;
		}

		private void OnCannonFire(DelayedRangedWeaponTrigger trigger)
		{
			if (base.hasAuthority)
			{
				Fire();
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				FireBullet(position, rotation, velocity, 1f, shotId);
			}
		}

		public void EnemyStartWielding(Enemy enemy)
		{
			if (enemy.hasAuthority)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				base.Wielder = new Combatant(enemy);
			}
		}

		public bool EnemyCanWield(Enemy enemy)
		{
			if (swivel.Handle.Tool.IsHeld)
			{
				return false;
			}
			if (base.Wielder.Enemy != null && base.Wielder.Enemy != enemy)
			{
				return false;
			}
			return true;
		}

		public void EnemyStopWielding()
		{
			if (base.hasAuthority)
			{
				base.Wielder = Combatant.Invalid;
			}
		}

		public Vector3 GetEnemyWieldPosition()
		{
			return swivel.ScreenWieldTransform.position;
		}

		public Vector3 GetEnemyWieldForwardVector()
		{
			return Vector3.ProjectOnPlane(swivel.Tool.RigidbodyEx.TargetTransform.forward, Vector3.up);
		}

		public void GetNormalizedAimPitchYaw(out float pitch, out float yaw)
		{
			swivel.Handle.GetNormalizedAimPitchYaw(out pitch, out yaw);
		}

		public void AuthoritySetNormalizedAimPitchYaw(float aimPitch, float aimYaw)
		{
			if (base.hasAuthority)
			{
				swivel.Handle.AuthoritySetNormalizedAimPitchYaw(aimPitch, aimYaw);
			}
		}
	}
	public class QuestCannoneerEnemy : Enemy
	{
		private enum CombatState
		{
			FIRE_CANNON = 0,
			INVALID = 65535
		}

		private enum FireCannonSubState
		{
			AIM_CANNON,
			LIGHT_CANNON,
			FIRE_CANNON
		}

		[Header("Cannon Locating")]
		[SerializeField]
		private float cannonSearchRadius = 1f;

		[Header("Timing")]
		[SerializeField]
		private float fireCannonDuration = 1.25f;

		[SerializeField]
		private float lightCannonDuration = 0.33f;

		[SerializeField]
		private float postFireCannonDuration = 0.5f;

		[Header("Cannon Firing")]
		[SerializeField]
		private float cannonAimSpeed = 0.33f;

		[SerializeField]
		private float minimumCannonRateOfFire = 0.2f;

		[SerializeField]
		private float maximumCannonRateOfFire = 1f;

		private float aimPitchVelocity;

		private float aimYawVelocity;

		private SynchronizedStateMachine combatStateMachine;

		private SynchronizedTimer combatStateTimer;

		private QuestCannon _cachedCannon;

		private SynchronizedField<int> _cannonId;

		private SynchronizedField<float, float> _cannonAimTarget;

		private QuestCannon Cannon
		{
			get
			{
				return _cachedCannon;
			}
			set
			{
				_cannonId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private float CannonAimTargetPitch => _cannonAimTarget.Get1();

		private float CannonAimTargetYaw => _cannonAimTarget.Get2();

		protected override void Awake()
		{
			base.Awake();
			mustBeOnNavMesh = false;
			_cannonId = new SynchronizedField<int>(this, "CANID", -1, SetterPermissionMode.AUTHORITY, OnCannonIdChange);
			_cannonAimTarget = new SynchronizedField<float, float>(this, "CATY", 0f, 0f, SetterPermissionMode.AUTHORITY);
			combatStateTimer = new SynchronizedTimer(this, "CST", SetterPermissionMode.AUTHORITY);
			combatStateMachine = new SynchronizedStateMachine("CSM", SetterPermissionMode.AUTHORITY);
			combatStateMachine.AddState(0, OnEnterFireCannonSuperState, OnExitFireCannonSuperState, OnUpdateFireCannonSuperState);
			combatStateMachine.AddState(0, 0, OnEnterAimCannonSubState, null, OnUpdateAimCannonSubState);
			combatStateMachine.AddState(0, 1, OnEnterLightCannonSubState, null, OnUpdateLightCannonSubState);
			combatStateMachine.AddState(0, 2, OnEnterFireCannonSubState, null, OnUpdateFireCannonSubState);
		}

		protected override void Start()
		{
			base.Start();
			OnCannonIdChange();
			base.RigidbodyEx.AddKinematic(this);
			combatStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void Update()
		{
			base.Update();
			combatStateMachine.Update();
			combatStateTimer.UpdateCallbacks();
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(0, 0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void OnActiveCombatStart()
		{
			base.OnActiveCombatStart();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
		}

		protected override bool GetIsMoving()
		{
			return combatStateMachine.CurrentStateId == 0 && combatStateMachine.CurrentSubStateId == 0;
		}

		private void OnEnterFireCannonSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			aimPitchVelocity = 0f;
			aimYawVelocity = 0f;
			base.Steering.StopAll();
			base.Steering.enabled = false;
			if (base.hasAuthority)
			{
				if (Cannon == null)
				{
					Cannon = FindCannonInSearchRadius();
				}
				SetCannonAim(GetRandomAimPitch(), GetRandomAimYaw());
			}
		}

		private void OnUpdateFireCannonSuperState()
		{
			if (base.hasAuthority && Cannon != null)
			{
				base.RigidbodyEx.targetPosition = Cannon.GetEnemyWieldPosition();
				base.RigidbodyEx.targetRotation = Quaternion.LookRotation(Cannon.GetEnemyWieldForwardVector());
			}
		}

		private void OnExitFireCannonSuperState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private bool SteerCannonTowardsTarget(float targetPitch, float targetYaw)
		{
			Cannon.GetNormalizedAimPitchYaw(out var pitch, out var yaw);
			float f = targetYaw - yaw;
			float num = cannonAimSpeed * UnityEngine.Time.deltaTime;
			if (Mathf.Abs(f) < num)
			{
				Cannon.AuthoritySetNormalizedAimPitchYaw(pitch, targetYaw);
				return true;
			}
			pitch = Mathf.SmoothDamp(pitch, targetPitch, ref aimPitchVelocity, UnityEngine.Time.deltaTime, cannonAimSpeed);
			yaw = Mathf.SmoothDamp(yaw, targetYaw, ref aimYawVelocity, UnityEngine.Time.deltaTime, cannonAimSpeed);
			Cannon.AuthoritySetNormalizedAimPitchYaw(pitch, yaw);
			return false;
		}

		private void OnEnterAimCannonSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				combatStateTimer.StartTimer(GetNextCannonFirePeriod());
			}
		}

		private void OnUpdateAimCannonSubState()
		{
			if (base.hasAuthority)
			{
				float cannonAimTargetPitch = CannonAimTargetPitch;
				float cannonAimTargetYaw = CannonAimTargetYaw;
				if (SteerCannonTowardsTarget(cannonAimTargetPitch, cannonAimTargetYaw))
				{
					float minEnemyWieldYawAngleNormalized = Cannon.MinEnemyWieldYawAngleNormalized;
					float maxEnemyWieldYawAngleNormalized = Cannon.MaxEnemyWieldYawAngleNormalized;
					float num = Mathf.Abs(cannonAimTargetYaw - minEnemyWieldYawAngleNormalized);
					SetCannonAim(GetRandomAimPitch(), (!(num <= 0.01f)) ? minEnemyWieldYawAngleNormalized : maxEnemyWieldYawAngleNormalized);
				}
				if (combatStateTimer.TimerOver)
				{
					combatStateMachine.EnterState(0, 1);
				}
			}
		}

		private void OnEnterLightCannonSubState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.PlayRangedAttack();
			if (base.hasAuthority)
			{
				combatStateTimer.StartTimer(lightCannonDuration);
			}
		}

		private void OnUpdateLightCannonSubState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(0, 2);
			}
		}

		private void OnEnterFireCannonSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				Cannon.RequestFire();
				combatStateTimer.StartTimer(fireCannonDuration + postFireCannonDuration);
			}
		}

		private void OnUpdateFireCannonSubState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(0, 0);
			}
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			if (Cannon != null)
			{
				Cannon.EnemyStopWielding();
			}
		}

		private QuestCannon FindCannonInSearchRadius()
		{
			Collider[] array = Physics.OverlapSphere(base.RigidbodyEx.physicsPosition, cannonSearchRadius, 159785984, QueryTriggerInteraction.Ignore);
			for (int i = 0; i < array.Length; i++)
			{
				Tool colliderTool = array[i].GetColliderTool();
				if (!(colliderTool == null))
				{
					QuestCannon component = colliderTool.GetComponent<QuestCannon>();
					if (!(component == null) && component.EnemyCanWield(this))
					{
						return component;
					}
				}
			}
			return null;
		}

		private float GetNextCannonFirePeriod()
		{
			float min = 1f / minimumCannonRateOfFire;
			float max = 1f / maximumCannonRateOfFire;
			return UnityEngine.Random.Range(min, max);
		}

		private void OnCannonIdChange()
		{
			_cachedCannon = null;
			if (_cannonId != null)
			{
				PhotonView photonView = PhotonView.Find(_cannonId.Get());
				_cachedCannon = ((!(photonView != null)) ? null : photonView.GetComponent<QuestCannon>());
				if (_cachedCannon != null)
				{
					_cachedCannon.EnemyStartWielding(this);
				}
			}
		}

		private float GetRandomAimYaw()
		{
			return (!UnityExtensions.GetRandomResult(0.5f)) ? Cannon.MaxEnemyWieldYawAngleNormalized : Cannon.MinEnemyWieldYawAngleNormalized;
		}

		private float GetRandomAimPitch()
		{
			return (!UnityExtensions.GetRandomResult(0.5f)) ? Cannon.MaxEnemyWieldPitchAngleNormalized : Cannon.MinEnemyWieldPitchAngleNormalized;
		}

		private void SetCannonAim(float pitch, float yaw)
		{
			_cannonAimTarget.Set(pitch, yaw);
		}
	}
	public class QuestCannonLighter : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Autofill(AutofillType.SelfAndParent, false)]
		[SerializeField]
		private QuestCannon cannon;

		[SerializeField]
		private Transform tipTransform;

		[SerializeField]
		private float wickLightDistance = 0.1f;

		public Tool Tool => tool;

		private void Awake()
		{
			base.transform.SetParent(cannon.transform.parent, worldPositionStays: true);
			QuestCannon questCannon = cannon;
			questCannon.WielderChangeEvent = (QuestCannon.QuestCannonAction)Delegate.Combine(questCannon.WielderChangeEvent, new QuestCannon.QuestCannonAction(OnCannonWielderChange));
			cannon.Tool.PostResetEvent += OnCannonReset;
			cannon.Tool.EnabledChangeEvent += OnCannonEnableChange;
			tool.KinematicOnSleep = true;
			tool.KinematicOnReset = true;
			tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_SNAP_ORIENTATION;
			tool.RigidbodyEx.SleepChangedEvent += OnSleepChange;
		}

		private void OnDestroy()
		{
			if (cannon != null)
			{
				QuestCannon questCannon = cannon;
				questCannon.WielderChangeEvent = (QuestCannon.QuestCannonAction)Delegate.Remove(questCannon.WielderChangeEvent, new QuestCannon.QuestCannonAction(OnCannonWielderChange));
				if (cannon.Tool != null)
				{
					cannon.Tool.PostResetEvent -= OnCannonReset;
					cannon.Tool.EnabledChangeEvent -= OnCannonEnableChange;
				}
			}
			if (tool != null && tool.RigidbodyEx != null)
			{
				tool.RigidbodyEx.SleepChangedEvent -= OnSleepChange;
			}
		}

		private void Update()
		{
			AuthorityFireCannonsWithWickInRange();
		}

		private void OnSleepChange(RigidbodyEx rigidbodyEx)
		{
			if (rigidbodyEx.IsSleeping() && !tool.IsHeld && tool.hasAuthority)
			{
				tool.AuthorityResetToDefault(cannon.LighterHolsterTransform.position, cannon.LighterHolsterTransform.rotation, sleepPhysics: true);
			}
		}

		private void AuthorityFireCannonsWithWickInRange()
		{
			if (!tool.hasAuthority)
			{
				return;
			}
			float num = wickLightDistance * wickLightDistance;
			foreach (QuestCannon activeCannon in QuestCannon.ActiveCannons)
			{
				if ((tipTransform.position - activeCannon.WickTransform.position).sqrMagnitude <= num)
				{
					activeCannon.RequestFire(tool.authority);
				}
			}
		}

		private void OnCannonWielderChange(QuestCannon cannon)
		{
			if (tool.hasAuthority)
			{
				if (cannon.Wielder.Enemy != null && tool.IsEnabled)
				{
					tool.AuthorityDisableAndMove(cannon.LighterHolsterTransform.position, cannon.LighterHolsterTransform.rotation);
				}
				else if (cannon.Wielder.Enemy == null && !tool.IsEnabled)
				{
					tool.IsEnabled = true;
				}
			}
		}

		private void OnCannonReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (tool != null && tool.hasAuthority)
			{
				if (cannon != null)
				{
					tool.AuthorityResetToDefault(cannon.LighterHolsterTransform.position, cannon.LighterHolsterTransform.rotation, sleepPhysics: true);
				}
				else
				{
					tool.AuthorityResetToLastSpawnPosition();
				}
			}
		}

		private void OnCannonEnableChange(Tool tool)
		{
			if (tool.hasAuthority)
			{
				tool.IsEnabled = cannon.Tool.IsEnabled;
			}
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.yellow;
			Gizmos.DrawWireSphere(tipTransform.position, wickLightDistance);
		}
	}
	public class QuestPirateBossEnemy : Enemy
	{
		private enum CombatState
		{
			IDLE = 0,
			RELOCATE = 1,
			EVADE = 2,
			FIND_TARGET = 3,
			CHARGE_ATTACK = 4,
			ATTACK = 5,
			INVALID = 65535
		}

		private enum EvadeSubState
		{
			EVADE,
			POST_EVADE_IDLE
		}

		[Header("Evade")]
