		[SerializeField]
		private float evadeMovementSpeed = 4f;

		[SerializeField]
		private float evadeSlowdownDistance = 1f;

		[SerializeField]
		private float evadeCompleteIdleDuration = 0.5f;

		[Header("Evade Look Steering")]
		[SerializeField]
		private float evadeAngularSpeed = 90f;

		[SerializeField]
		private float maxEvadeFaceVelocityDistance = 0.5f;

		[SerializeField]
		private float evadeFaceVelocityYawAngle = 15f;

		[Header("Ranged Attack")]
		[SerializeField]
		private float firstPhaseRangedAttackChance = 0.5f;

		[SerializeField]
		private float secondPhaseRangedAttackChance = 0.5f;

		[SerializeField]
		private float thirdPhaseRangedAttackChance = 1f;

		[SerializeField]
		private float attackChargeDuration = 0.66f;

		[SerializeField]
		private float attackDuration = 0.75f;

		private SynchronizedStateMachine combatStateMachine;

		private SynchronizedTimer combatStateTimer;

		private SynchronizedField<int> _relocatePointIndex;

		private SynchronizedField<Vector3> _seekTarget;

		private SynchronizedField<bool> _isFirstDisengage;

		private QuestPirateBossPatrolPoints relocatePatrolPoints;

		private bool IsFirstDisengage
		{
			get
			{
				return _isFirstDisengage.Get();
			}
			set
			{
				_isFirstDisengage.Set(value);
			}
		}

		public override int CustomEncounterValue => (combatStateMachine.CurrentStateId == 2) ? 1 : 0;

		private int RelocatePointIndex
		{
			get
			{
				return _relocatePointIndex.Get();
			}
			set
			{
				int num = value;
				if (relocatePatrolPoints != null)
				{
					num = Mathf.Clamp(num, 0, relocatePatrolPoints.PatrolPointCount);
				}
				_relocatePointIndex.Set(num);
			}
		}

		private Vector3 SeekTarget
		{
			get
			{
				return _seekTarget.Get();
			}
			set
			{
				_seekTarget.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			mustBeOnNavMesh = false;
			_relocatePointIndex = new SynchronizedField<int>(this, "RPI", 0, SetterPermissionMode.AUTHORITY);
			_seekTarget = new SynchronizedField<Vector3>(this, "ST", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_isFirstDisengage = new SynchronizedField<bool>(this, "PSWP", defaultValue: true, SetterPermissionMode.AUTHORITY);
			combatStateTimer = new SynchronizedTimer(this, "CT", SetterPermissionMode.AUTHORITY);
			combatStateMachine = new SynchronizedStateMachine("CSM", SetterPermissionMode.AUTHORITY);
			combatStateMachine.AddState(0, null, null, null);
			combatStateMachine.AddState(1, OnEnterRelocateState, OnExitRelocateState, OnUpdateRelocateState);
			combatStateMachine.AddState(2, OnEnterEvadeSuperState, OnExitEvadeSuperState, null);
			combatStateMachine.AddState(2, 0, OnEnterEvadeSubState, OnExitEvadeSubState, OnUpdateEvadeSubState);
			combatStateMachine.AddState(2, 1, OnEnterPostEvadeIdleSubState, null, OnUpdatePostEvadeIdleSubState);
			combatStateMachine.AddState(4, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
			combatStateMachine.AddState(5, OnEnterAttackState, OnExitAttackState, OnUpdateAttackState);
			if (base.Patrol != null)
			{
				relocatePatrolPoints = base.Patrol as QuestPirateBossPatrolPoints;
			}
		}

		protected override void Start()
		{
			base.Start();
			combatStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void Update()
		{
			base.Update();
			combatStateMachine.Update();
			combatStateTimer.UpdateCallbacks();
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(1);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override bool AuthorityTryApplyAttackInternal(Combatant attacker, Weapon weapon, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (base.IsSpawning)
			{
				return false;
			}
			if (base.IsDisengaged)
			{
				return false;
			}
			if (base.IsStunned)
			{
				return false;
			}
			if (weapon != null)
			{
				QuestCannon component = weapon.GetComponent<QuestCannon>();
				if (component == null)
				{
					return false;
				}
			}
			return base.AuthorityTryApplyAttackInternal(attacker, weapon, damageType, armorType, damage, impact);
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			base.RigidbodyEx.useGravity = true;
		}

		protected override void OnStunEnd(bool interruptsCustomBehaviour)
		{
			base.OnStunEnd(interruptsCustomBehaviour);
			base.RigidbodyEx.useGravity = false;
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
		}

		protected override void MasterOnCustomEncounterEventInternal()
		{
			base.MasterOnCustomEncounterEventInternal();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(1);
			}
		}

		private Transform GetRelocateTransform()
		{
			if (relocatePatrolPoints == null)
			{
				return base.transform;
			}
			return relocatePatrolPoints.GetPatrolTransformAtIndex(RelocatePointIndex);
		}

		private void IncrementRelocatePointIndex()
		{
			RelocatePointIndex++;
		}

		private void ResetRelocatePointIndex()
		{
			RelocatePointIndex = 0;
		}

		private void OnEnterRelocateState(ushort previousStateid, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			if (base.hasAuthority)
			{
				Transform relocateTransform = GetRelocateTransform();
				if (relocateTransform == null)
				{
					combatStateMachine.EnterState(0);
					return;
				}
				Vector3 position = relocateTransform.position;
				float magnitude = (position - base.transform.position).magnitude;
				float maxRunningTime = magnitude / evadeMovementSpeed * 2f;
				combatStateTimer.StartTimer(maxRunningTime);
				base.Steering.Seek(relocateTransform.position, movementSlowdownDistance, 0.1f, faceVelocity: false, separateHeightSeeking: false);
				base.Steering.Look(GetLookVector(relocateTransform.position, relocateTransform));
			}
		}

		private void OnUpdateRelocateState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (base.Steering.ReachedMainSeekTarget || combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(2, 0);
				return;
			}
			Transform relocateTransform = GetRelocateTransform();
			if (relocateTransform == null)
			{
				combatStateMachine.EnterState(0);
				return;
			}
			base.Steering.Seek(relocateTransform.position, movementSlowdownDistance, 0.1f, faceVelocity: false, separateHeightSeeking: false);
			base.Steering.Look(GetLookVector(relocateTransform.position, relocateTransform));
		}

		private void OnExitRelocateState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private void OnEnterEvadeSuperState(ushort previousStateId, ushort previousSubStateid)
		{
			suppressMovingAnimation = true;
			base.Steering.MaxHorizontalSpeed = evadeMovementSpeed;
			base.Steering.MaxAngularSpeed = evadeAngularSpeed;
		}

		private void OnExitEvadeSuperState(ushort nextStateId, ushort nextSubStateId)
		{
			suppressMovingAnimation = false;
			base.Steering.StopAll();
		}

		private void OnEnterEvadeSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
				}
				Transform relocateTransform = GetRelocateTransform();
				if (relocateTransform == null)
				{
					combatStateMachine.EnterState(0);
					return;
				}
				Vector3 nextEvadeTarget = GetNextEvadeTarget(relocateTransform, SeekTarget);
				float magnitude = (nextEvadeTarget - base.transform.position).magnitude;
				float maxRunningTime = magnitude / evadeMovementSpeed * 2f;
				SeekTarget = nextEvadeTarget;
				combatStateTimer.StartTimer(maxRunningTime);
				AuthorityUpdateEvadeSteering(relocateTransform);
			}
		}

		private void OnUpdateEvadeSubState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if ((base.Steering.ReachedMainSeekTarget || combatStateTimer.TimerOver) && !TryEnterChargeAttackState())
			{
				combatStateMachine.EnterState(2, 1);
				return;
			}
			Transform relocateTransform = GetRelocateTransform();
			if (relocateTransform == null)
			{
				combatStateMachine.EnterState(0);
			}
			else
			{
				AuthorityUpdateEvadeSteering(relocateTransform);
			}
		}

		private void OnExitEvadeSubState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		private void AuthorityUpdateEvadeSteering(Transform relocateTransform)
		{
			if (base.hasAuthority)
			{
				base.Steering.Seek(SeekTarget, evadeSlowdownDistance, 0.01f, faceVelocity: false, separateHeightSeeking: false);
				base.Steering.Look(GetLookVector(SeekTarget, relocateTransform));
			}
		}

		private Vector3 GetLookVector(Vector3 targetPosition, Transform movementOriginTransform)
		{
			Vector3 rhs = Vector3.ProjectOnPlane(SeekTarget - base.RigidbodyEx.physicsPosition, movementOriginTransform.up);
			if (rhs.sqrMagnitude < maxEvadeFaceVelocityDistance * maxEvadeFaceVelocityDistance)
			{
				return GetIdleLookVector(movementOriginTransform);
			}
			Vector3 normalized = Vector3.Cross(movementOriginTransform.forward, rhs).normalized;
			return Quaternion.AngleAxis(evadeFaceVelocityYawAngle, normalized) * movementOriginTransform.forward;
		}

		private Vector3 GetIdleLookVector(Transform movementOriginTransform)
		{
			if (CurrentTargetIsValidTarget())
			{
				return GetLookAtTargetVector(inXZPlane: true);
			}
			return movementOriginTransform.forward;
		}

		private void OnEnterPostEvadeIdleSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				combatStateTimer.StartTimer(evadeCompleteIdleDuration);
			}
		}

		private void OnUpdatePostEvadeIdleSubState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(2, 0);
				return;
			}
			Transform relocateTransform = GetRelocateTransform();
			if (relocateTransform == null)
			{
				combatStateMachine.EnterState(0);
			}
			else
			{
				base.Steering.Look(GetIdleLookVector(relocateTransform));
			}
		}

		private Vector3 GetNextEvadeTarget(Transform relocateTransform, Vector3 previousTarget)
		{
			Vector3 right = relocateTransform.right;
			Vector3 lhs = previousTarget - relocateTransform.position;
			if (Vector3.Dot(lhs, right) >= 0f)
			{
				right *= -1f;
			}
			return relocateTransform.position + right * maxEvadeDistance;
		}

		private bool TryEnterChargeAttackState()
		{
			if (!UnityExtensions.GetRandomResult(GetRangedAttackChance()))
			{
				return false;
			}
			base.Target = FindTarget();
			if (!CurrentTargetIsValidTarget())
			{
				return false;
			}
			combatStateMachine.EnterState(4);
			return true;
		}

		private float GetRangedAttackChance()
		{
			return RelocatePointIndex switch
			{
				2 => thirdPhaseRangedAttackChance, 
				1 => secondPhaseRangedAttackChance, 
				_ => firstPhaseRangedAttackChance, 
			};
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			enemyAudio.OnChargeAttack();
			enemyAudio.OnAttack();
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			if (base.hasAuthority)
			{
				combatStateTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (base.hasAuthority)
			{
				if (combatStateTimer.TimerOver)
				{
					combatStateMachine.EnterState(5);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
			}
		}

		private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			if (nextStateId != 5)
			{
				enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
			}
		}

		private void OnEnterAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.ATTACK;
			if (base.hasAuthority)
			{
				AuthorityFireRangedWeaponAtTargetFloor(canFireAtLastVisiblePosition: false);
				combatStateTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackState()
		{
			if (base.hasAuthority && combatStateTimer.TimerOver)
			{
				combatStateMachine.EnterState(2, 0);
			}
		}

		private void OnExitAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
		}

		protected override void OnDisengagedStart()
		{
			base.OnDisengagedStart();
			base.CollidersEnabled = false;
			if (!IsFirstDisengage)
			{
				base.Steering.MaxHorizontalSpeed = movementSpeed;
				base.Steering.MaxVerticalSpeed = movementSpeed;
				base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
				base.Steering.MaxVerticalSteeringForce = movementMaxForce;
				if (base.hasAuthority)
				{
					Transform retreatTransform = relocatePatrolPoints.GetRetreatTransform();
					SeekTarget = retreatTransform.position;
					base.Steering.Seek(SeekTarget, movementSlowdownDistance, 0.25f, faceVelocity: false, separateHeightSeeking: false);
					base.Steering.Look(GetLookVector(SeekTarget, retreatTransform));
				}
			}
		}

		protected override void OnDisengagedUpdate()
		{
			base.OnDisengagedUpdate();
			if (!IsFirstDisengage && base.hasAuthority && !base.Steering.ReachedMainSeekTarget)
			{
				Transform retreatTransform = relocatePatrolPoints.GetRetreatTransform();
				base.Steering.Seek(SeekTarget, movementSlowdownDistance, 0.25f, faceVelocity: false, separateHeightSeeking: false);
				base.Steering.Look(GetLookVector(SeekTarget, retreatTransform));
			}
		}

		protected override void OnDisengagedEnd()
		{
			base.OnDisengagedEnd();
			base.Steering.StopAll();
			base.CollidersEnabled = true;
			if (base.hasAuthority)
			{
				if (IsFirstDisengage)
				{
					IsFirstDisengage = false;
				}
				else
				{
					IncrementRelocatePointIndex();
				}
			}
		}
	}
}
[RequireComponent(typeof(PhotonView))]
public class QuestPirateBossPatrolPoints : EnemyPatrol
{
	[SerializeField]
	private Transform[] orderedPatrolPoints;

	[SerializeField]
	private Transform retreatPoint;

	public int PatrolPointCount => orderedPatrolPoints.Length;

	public override bool HasValidPatrolPoints => false;

	public override bool HasReachedTarget(Vector3 enemyPosition, Vector3 targetPosition)
	{
		return true;
	}

	public override bool HasFinishedPatrol(int currentTargetId)
	{
		return true;
	}

	public override bool TryGetNextTarget(int currentTargetId, out int nextTargetId, out Vector3 targetPosition)
	{
		nextTargetId = -1;
		targetPosition = Vector3.zero;
		return false;
	}

	public override Vector3 GetGizmoPosition()
	{
		return Vector3.zero;
	}

	public Transform GetPatrolTransformAtIndex(int index)
	{
		if (orderedPatrolPoints == null || orderedPatrolPoints.Length < 1)
		{
			return base.transform;
		}
		if (index < 0)
		{
			return orderedPatrolPoints[0];
		}
		if (index >= orderedPatrolPoints.Length)
		{
			return orderedPatrolPoints[orderedPatrolPoints.Length - 1];
		}
		return orderedPatrolPoints[index];
	}

	public Transform GetRetreatTransform()
	{
		return (!(retreatPoint != null)) ? base.transform : retreatPoint;
	}

	private void OnDrawGizmosSelected()
	{
		float radius = 0.3f;
		if (orderedPatrolPoints != null && orderedPatrolPoints.Length > 0)
		{
			if (orderedPatrolPoints.Length > 1)
			{
				Gizmos.color = Color.blue;
				Gizmos.DrawWireSphere(orderedPatrolPoints[0].position, radius);
				for (int i = 1; i < orderedPatrolPoints.Length - 1; i++)
				{
					Gizmos.color = Color.white;
					Gizmos.DrawWireSphere(orderedPatrolPoints[i].position, radius);
				}
			}
			Gizmos.color = Color.red;
			Gizmos.DrawWireSphere(orderedPatrolPoints[orderedPatrolPoints.Length - 1].position, radius);
		}
		if (retreatPoint != null)
		{
			Gizmos.color = Color.yellow;
			Gizmos.DrawWireSphere(retreatPoint.position, radius);
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestToolCustomReset : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		private void Awake()
		{
			tool.CustomAuthorityResetOnKillzoneBehavior = AuthorityCustomKillzoneBehavior;
		}

		private void Start()
		{
			if (tool.ToolCleanup != null)
			{
				tool.ToolCleanup.CustomGetResetPositionAndOrientationBehavior = GetCustomCleanupResetPositionAndOrientation;
			}
		}

		private bool AuthorityCustomKillzoneBehavior(Tool thisTool, Killzone killzone)
		{
			if (!tool.hasAuthority)
			{
				return false;
			}
			QuestToolResetPoint questToolResetPoint = QuestToolResetPoint.ClosestResetPoint(GetPlayerTeamPoint());
			if (questToolResetPoint == null)
			{
				return false;
			}
			tool.AuthorityResetToDefault(questToolResetPoint.transform.position, questToolResetPoint.transform.rotation, sleepPhysics: true);
			return true;
		}

		private bool GetCustomCleanupResetPositionAndOrientation(out Vector3 position, out Quaternion rotation)
		{
			QuestToolResetPoint questToolResetPoint = QuestToolResetPoint.ClosestResetPoint(GetPlayerTeamPoint());
			if (questToolResetPoint == null)
			{
				position = Vector3.zero;
				rotation = Quaternion.identity;
				return false;
			}
			position = questToolResetPoint.transform.position;
			rotation = questToolResetPoint.transform.rotation;
			return true;
		}

		private Vector3 GetPlayerTeamPoint()
		{
			if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TryGetActivePlayerCentroid(out var centroid))
			{
				return centroid;
			}
			return base.transform.position;
		}
	}
	public class QuestToolResetPoint : UnityEngine.MonoBehaviour
	{
		public static List<QuestToolResetPoint> AllResetPoints = new List<QuestToolResetPoint>();

		public static QuestToolResetPoint ClosestResetPoint(Vector3 point)
		{
			int num = -1;
			float num2 = float.MaxValue;
			for (int i = 0; i < AllResetPoints.Count; i++)
			{
				float sqrMagnitude = (AllResetPoints[i].transform.position - point).sqrMagnitude;
				if (sqrMagnitude < num2)
				{
					num = i;
					num2 = sqrMagnitude;
				}
			}
			if (num < 0)
			{
				return null;
			}
			return AllResetPoints[num];
		}

		private void Awake()
		{
			AllResetPoints.Add(this);
		}

		private void OnDestroy()
		{
			AllResetPoints.Remove(this);
		}

		private void OnDrawGizmos()
		{
			float num = 0.5f;
			Vector3 vector = base.transform.up * num;
			Gizmos.color = Color.green;
			GizmoExtensions.DrawGizmoArrow(base.transform.position - vector * 0.5f, base.transform.position + vector * 0.5f);
		}
	}
	public class QuestWeaponCorkScaler : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private RangedWeapon weapon;

		[SerializeField]
		private Transform cork;

		[SerializeField]
		private float scaleCorkDuration = 0.2f;

		[SerializeField]
		private Transform hiddenCorkLocalPositionTransform;

		private Vector3 defaultCorkLocalPosition = Vector3.zero;

		private Vector3 defaultCorkLocalScale = Vector3.one;

		private Coroutine scaleCorkOnReloadCoroutine;

		private void Awake()
		{
			defaultCorkLocalPosition = cork.localPosition;
			defaultCorkLocalScale = cork.localScale;
			weapon.AmmunitionChangeEvent += OnWeaponAmmunitionChange;
		}

		private void OnDestroy()
		{
			weapon.AmmunitionChangeEvent -= OnWeaponAmmunitionChange;
		}

		private void OnWeaponAmmunitionChange()
		{
			if (weapon.MagazineAmmunition == 0)
			{
				ScaleCorkOnFire();
			}
			else
			{
				StartScaleCorkOnReloadCoroutine();
			}
		}

		private void ScaleCorkOnFire()
		{
			StopScaleCorkOnReloadCoroutine();
			cork.localScale = Vector3.zero;
		}

		private void StartScaleCorkOnReloadCoroutine()
		{
			StopScaleCorkOnReloadCoroutine();
			scaleCorkOnReloadCoroutine = StartCoroutine(ScaleCorkOnReloadCoroutine());
		}

		private void StopScaleCorkOnReloadCoroutine()
		{
			if (scaleCorkOnReloadCoroutine != null)
			{
				StopCoroutine(scaleCorkOnReloadCoroutine);
				scaleCorkOnReloadCoroutine = null;
			}
		}

		private IEnumerator ScaleCorkOnReloadCoroutine()
		{
			float startTime = UnityEngine.Time.time;
			float endTime = startTime + scaleCorkDuration;
			while (UnityEngine.Time.time <= endTime)
			{
				float rawT = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
				float smoothedT = Mathf.SmoothStep(0f, 1f, rawT);
				cork.localScale = Vector3.Lerp(hiddenCorkLocalPositionTransform.localScale, defaultCorkLocalScale, smoothedT);
				cork.localPosition = Vector3.Lerp(hiddenCorkLocalPositionTransform.localPosition, defaultCorkLocalPosition, smoothedT);
				yield return null;
			}
			cork.localPosition = defaultCorkLocalPosition;
			cork.localScale = defaultCorkLocalScale;
			scaleCorkOnReloadCoroutine = null;
		}
	}
}
namespace RecRoom
{
	public class SparkleOutline : UnityEngine.MonoBehaviour
	{
		[AutofillOptional(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private VisibleInCamera visibleInCamera;

		[SerializeField]
		private float minSparklePeriod = 2f;

		[SerializeField]
		private float maxSparklePeriod = 10f;

		[SerializeField]
		private Material overrideMaterial;

		[SerializeField]
		private MeshRenderer[] ignoredRenderers;

		private Timer timer = new Timer();

		private Coroutine sparkleCoroutine;

		private List<MeshRenderer> renderers = new List<MeshRenderer>();

		private static readonly float SPARKLE_DURATION = 1.5f;

		private static readonly AnimationCurve COLOR_SPARKLE_CURVE = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(0.1f, 0f), new Keyframe(0.2f, 1f), new Keyframe(0.3f, 1f), new Keyframe(0.4f, 0f), new Keyframe(1f, 0f));

		private static readonly AnimationCurve WIDTH_SPARKLE_CURVE = new AnimationCurve(new Keyframe(0f, 0f), new Keyframe(0.2f, 1f), new Keyframe(1f, 0f));

		private void Awake()
		{
			renderers.AddRange(GetComponentsInChildren<MeshRenderer>());
			if (ignoredRenderers != null)
			{
				for (int i = 0; i < ignoredRenderers.Length; i++)
				{
					renderers.Remove(ignoredRenderers[i]);
				}
			}
		}

		private void OnEnable()
		{
			StartTimer();
		}

		private void Update()
		{
			if (timer.TimerOver)
			{
				OnSparkle();
				StartTimer();
			}
		}

		private static void GetSmoothedInterpolation(float t, out float widthT, out float colorT)
		{
			widthT = WIDTH_SPARKLE_CURVE.Evaluate(Mathf.Clamp01(t));
			colorT = COLOR_SPARKLE_CURVE.Evaluate(Mathf.Clamp01(t));
		}

		private void StartTimer()
		{
			timer.StartTimer(Mathf.Max(SPARKLE_DURATION, UnityEngine.Random.Range(minSparklePeriod, maxSparklePeriod)));
		}

		private void OnSparkle()
		{
			if (visibleInCamera.IsVisible)
			{
				StartSparkleCoroutine();
			}
		}

		private void StartSparkleCoroutine()
		{
			StopSparkleCoroutine();
			sparkleCoroutine = StartCoroutine(SparkleCoroutine());
		}

		private void StopSparkleCoroutine()
		{
			if (sparkleCoroutine != null)
			{
				StopCoroutine(sparkleCoroutine);
				sparkleCoroutine = null;
			}
		}

		private IEnumerator SparkleCoroutine()
		{
			float startTime = UnityEngine.Time.time;
			float endTime = startTime + SPARKLE_DURATION;
			while (UnityEngine.Time.time <= endTime)
			{
				float t = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
				GetSmoothedInterpolation(t, out var widthT, out var colorT);
				if (tool == null || !tool.IsHoverHighlighted)
				{
					for (int i = 0; i < renderers.Count; i++)
					{
						if (overrideMaterial != null)
						{
							SparkleEffectRenderer.RenderSparkleOutine(renderers[i], overrideMaterial, widthT, colorT);
						}
						else
						{
							SparkleEffectRenderer.RenderSparkleOutine(renderers[i], widthT, colorT);
						}
					}
				}
				yield return null;
			}
			sparkleCoroutine = null;
		}
	}
}
public class StaggeredIdleAnimation : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float maxStartDelay;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Animator animator;

	private static readonly int RestartIdleTriggerId = Animator.StringToHash("RestartIdle");

	private IEnumerator Start()
	{
		if (maxStartDelay > 0f)
		{
			float delay = UnityEngine.Random.Range(0f, maxStartDelay);
			yield return new WaitForSeconds(delay);
		}
		animator.SetTrigger(RestartIdleTriggerId);
	}
}
public class TorchFlameBillboard : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float followTime = 0.1f;

	private Vector3 flameTipPosition = Vector3.zero;

	private Vector3 velocity = Vector3.zero;

	private static readonly Vector3 TARGET_FLAME_TIP_OFFSET = Vector3.up * 0.2f;

	private void Awake()
	{
		flameTipPosition = base.transform.position + TARGET_FLAME_TIP_OFFSET;
	}

	private void LateUpdate()
	{
		Vector3 target = base.transform.position + TARGET_FLAME_TIP_OFFSET;
		flameTipPosition = Vector3.SmoothDamp(flameTipPosition, target, ref velocity, followTime);
		Vector3 normalized = (flameTipPosition - base.transform.position).normalized;
		Vector3 forward = base.transform.forward;
		Vector3 lhs = Vector3.Cross(normalized, forward);
		Vector3 forward2 = Vector3.Cross(lhs, normalized);
		base.transform.rotation = Quaternion.LookRotation(forward2, normalized);
	}
}
namespace RecRoom.Tools.Weapons
{
	public class AutomaticGun : RangedWeapon
	{
		protected Coroutine automaticFireCoroutine;

		protected bool triggerHeld;

		private bool hasReceivedInputDownSincePickup;

		public virtual bool Firing => triggerHeld && base.HasEnoughMagazineAmmunition && !base.IsMisfire;

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent += OnToolPostPickup;
				base.Tool.InputDownEvent += OnInputDown;
				base.Tool.InputPressedEvent += OnInputPressed;
				base.Tool.InputUpEvent += OnInputUp;
				base.Tool.InputCancelledEvent += OnInputCancelled;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= OnToolPostPickup;
				base.Tool.InputDownEvent -= OnInputDown;
				base.Tool.InputPressedEvent -= OnInputPressed;
				base.Tool.InputUpEvent -= OnInputUp;
				base.Tool.InputCancelledEvent -= OnInputCancelled;
			}
		}

		private void OnToolPostPickup(Tool thisTool)
		{
			hasReceivedInputDownSincePickup = false;
		}

		private void OnInputDown(Tool thisTool)
		{
			hasReceivedInputDownSincePickup = true;
			TryStartFiring();
		}

		private void OnInputPressed(Tool thisTool)
		{
			if (hasReceivedInputDownSincePickup && !IsAutomaticCoroutineRunning() && base.HasEnoughMagazineAmmunition && !base.IsMisfire && !base.IsOnCooldown)
			{
				TryStartFiring();
			}
		}

		private void TryStartFiring()
		{
			if (base.hasAuthority)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (base.IsMisfire || base.IsOnCooldown)
				{
					base.WeaponAudio.OnMisfire();
				}
				else
				{
					StartAutomaticCoroutine();
				}
			}
			if (base.HasEnoughMagazineAmmunition && !base.IsMisfire && !base.IsOnCooldown)
			{
				triggerHeld = true;
			}
		}

		private void OnInputUp(Tool thisTool)
		{
			StopAutomaticCoroutine();
			triggerHeld = false;
		}

		private void OnInputCancelled(Tool thisTool)
		{
			StopAutomaticCoroutine();
			triggerHeld = false;
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				FireBullet(position, rotation, velocity, chargeAmount, shotId);
			}
		}

		protected virtual void StopAutomaticCoroutine()
		{
			if (automaticFireCoroutine != null)
			{
				StopCoroutine(automaticFireCoroutine);
				automaticFireCoroutine = null;
			}
		}

		protected virtual void StartAutomaticCoroutine()
		{
			StopAutomaticCoroutine();
			automaticFireCoroutine = StartCoroutine(AutomaticFireCoroutine());
		}

		private bool IsAutomaticCoroutineRunning()
		{
			return automaticFireCoroutine != null;
		}

		private IEnumerator AutomaticFireCoroutine()
		{
			while (true)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
					break;
				}
				if (base.IsMisfire)
				{
					base.WeaponAudio.OnMisfire();
					break;
				}
				Fire();
				float timeBetweenShots = 1f / maximumAutomaticFiringRate;
				yield return WaitBetweenShots(timeBetweenShots);
			}
			automaticFireCoroutine = null;
		}

		protected IEnumerator WaitBetweenShots(float time)
		{
			for (float timer = 0f; timer < time; timer += UnityEngine.Time.deltaTime)
			{
				yield return null;
			}
		}
	}
	public class BeamGun : AutomaticGun
	{
		private static int tintColorID = Shader.PropertyToID("_TintColor");

		private static int rampCutoffID = Shader.PropertyToID("_EmissionCutoff");

		[Header("Beam")]
		[SerializeField]
		private Transform beam;

		private Material beamMaterial;

		[SerializeField]
		private PooledParticle chargeParticlePrefab;

		private PooledParticle chargeParticles;

		private ParticleSystem.EmissionModule chargeParticleEmission;

		[SerializeField]
		private PooledParticle muzzleFlashParticlePrefab;

		private PooledParticle muzzleFlashParticles;

		[SerializeField]
		private PooledParticle emberParticlePrefab;

		private PooledParticle emberParticles;

		[SerializeField]
		private float chargeActivationTime;

		[SerializeField]
		private int emberFinishedBurst = 100;

		[Tooltip("Make sure bullet max stretch and the charge/beam particle systems are similar")]
		[SerializeField]
		protected float beamLength = 15f;

		[SerializeField]
		private float beamWidth = 0.25f;

		[SerializeField]
		private float beamExtendLerpSpeed = 10f;

		[Tooltip("(1, 1) is fully charged, multiplied by beam width")]
		public AnimationCurve BeamWidthByCharge;

		[Tooltip("(1, 1) is fully charged, multiplied by beam length")]
		public AnimationCurve BeamLengthByCharge;

		[Tooltip("(1, 1) is fully charged, opaque")]
		public AnimationCurve BeamOpacityByCharge;

		[Tooltip("This is a multiplier over time (set to repeat)")]
		public AnimationCurve BeamWidthNoise;

		public RecRoomAudioClip SpinUp;

		public RecRoomAudioClip SpinUpCancel;

		public RecRoomAudioClip FireInitialize;

		public RecRoomAudioClip FireLoop;

		public RecRoomAudioClip FireFinished;

		[SerializeField]
		private MeshRenderer AmmoEmmissiveRampRenderer;

		private Material ammoEmmissiveRampMaterial;

		[SerializeField]
		private TeamColorRenderer teamColorRenderer;

		private SFXAudioSource activeLoopAudio;

		private SFXAudioSource activeSpinAudio;

		private SynchronizedField<float> _chargeTime;

		protected bool wasBeamActive;

		protected bool wasCharging;

		public float ChargePercentage => chargeTime / chargeActivationTime;

		protected float chargeTime
		{
			get
			{
				return _chargeTime.Get();
			}
			set
			{
				_chargeTime.Set(value);
			}
		}

		protected bool isBeamActive => chargeTime >= chargeActivationTime;

		protected bool isCharging => chargeTime > 0f && chargeTime < chargeActivationTime;

		protected override void Awake()
		{
			base.Awake();
			_chargeTime = new SynchronizedField<float>(base.Tool, "PWCT", 0f, SetterPermissionMode.MASTER_OR_AUTHORITY);
		}

		protected override void Start()
		{
			base.Start();
			chargeParticles = ObjectPool.Instance.Acquire(chargeParticlePrefab);
			chargeParticles.transform.SetParent(muzzleFlashOrigin);
			chargeParticles.transform.localPosition = Vector3.zero;
			chargeParticles.transform.localRotation = Quaternion.identity;
			chargeParticleEmission = chargeParticles.PrimaryParticleSystem.emission;
			muzzleFlashParticles = ObjectPool.Instance.Acquire(muzzleFlashParticlePrefab);
			muzzleFlashParticles.transform.SetParent(muzzleFlashOrigin);
			muzzleFlashParticles.transform.localPosition = Vector3.zero;
			muzzleFlashParticles.transform.localRotation = Quaternion.identity;
			emberParticles = ObjectPool.Instance.Acquire(emberParticlePrefab);
			emberParticles.transform.SetParent(muzzleFlashOrigin);
			emberParticles.transform.localPosition = Vector3.zero;
			emberParticles.transform.localRotation = Quaternion.identity;
			beamMaterial = beam.GetComponent<MeshRenderer>().material;
			ammoEmmissiveRampMaterial = AmmoEmmissiveRampRenderer.material;
			if (teamColorRenderer != null)
			{
				teamColorRenderer.CustomSetColorBehavior = SetTeamColor;
			}
			this.Update30hz(StaggeredUpdate);
		}

		protected void SetTeamColor(Color color, bool resetToDefault)
		{
			beamMaterial.SetColor(tintColorID, color);
			chargeParticles.SetColor(color);
			muzzleFlashParticles.SetColor(color);
			emberParticles.SetColor(color);
		}

		protected virtual void StaggeredUpdate(float deltaTime)
		{
			if (base.hasAuthority)
			{
				chargeTime = ((!Firing) ? 0f : (chargeTime + deltaTime));
			}
			if (!wasCharging && isCharging)
			{
				if (chargeParticles.PrimaryParticleSystem.isPlaying)
				{
					chargeParticles.PrimaryParticleSystem.Simulate(0f, withChildren: true, restart: true, fixedTimeStep: false);
				}
				chargeParticles.Play(loop: true);
				activeSpinAudio = AudioManager.Play3DSFX(SpinUp, barrelTransform.position);
			}
			if (wasCharging && !wasBeamActive && !isCharging)
			{
				if ((bool)activeSpinAudio)
				{
					AudioManager.StopLoopingSFX(activeSpinAudio);
				}
				AudioManager.Play3DSFX(SpinUpCancel, barrelTransform.position);
			}
			if (wasBeamActive && !isBeamActive)
			{
				if ((bool)activeLoopAudio)
				{
					AudioManager.StopLoopingSFX(activeLoopAudio);
				}
				AudioManager.Play3DSFX(FireFinished, barrelTransform.position);
				emberParticles.PrimaryParticleSystem.Emit(emberFinishedBurst);
				muzzleFlashParticles.PrimaryParticleSystem.Stop(withChildren: true);
			}
			if (isBeamActive && !wasBeamActive)
			{
				AudioManager.Play3DSFX(FireInitialize, barrelTransform.position);
				activeLoopAudio = AudioManager.StartLooping3DSFX(FireLoop, barrelTransform.position);
				muzzleFlashParticles.Play(loop: true);
			}
			float num = BeamWidthByCharge.Evaluate(ChargePercentage);
			float num2 = beamLength * BeamLengthByCharge.Evaluate(ChargePercentage);
			if (isBeamActive)
			{
				num *= BeamWidthNoise.Evaluate(chargeTime);
				if (Physics.Raycast(barrelTransform.position, barrelTransform.forward, out var hitInfo, beamLength, 362036736))
				{
					num2 = hitInfo.distance;
				}
				num2 = ((!(beam.localScale.z > num2)) ? Mathf.Lerp(beam.localScale.z, num2, deltaTime * beamExtendLerpSpeed) : num2);
			}
			beam.localScale = new Vector3(beamWidth * num, beamWidth * num, num2);
			beam.localPosition = Vector3.forward * beam.localScale.z / 2f;
			chargeParticleEmission.enabled = isCharging;
			SetBeamOpacity(BeamOpacityByCharge.Evaluate(ChargePercentage));
			ammoEmmissiveRampMaterial.SetFloat(rampCutoffID, base.MagazineAmmunitionNormalized);
			wasBeamActive = isBeamActive;
			wasCharging = isCharging;
		}

		private void SetBeamOpacity(float a)
		{
			Color color = beamMaterial.GetColor(tintColorID);
			color.a = a;
			beamMaterial.SetColor(tintColorID, color);
		}

		protected override void StopAutomaticCoroutine()
		{
			if (automaticFireCoroutine != null)
			{
				StopCoroutine(automaticFireCoroutine);
				automaticFireCoroutine = null;
			}
		}

		protected override void StartAutomaticCoroutine()
		{
			StopAutomaticCoroutine();
			automaticFireCoroutine = StartCoroutine(AutomaticBeamFireCoroutine());
		}

		private IEnumerator AutomaticBeamFireCoroutine()
		{
			while (true)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
					break;
				}
				if (base.IsMisfire)
				{
					base.WeaponAudio.OnMisfire();
					break;
				}
				if (isBeamActive)
				{
					Fire();
				}
				float timeBetweenShots = 1f / maximumAutomaticFiringRate;
				yield return WaitBetweenShots(timeBetweenShots);
			}
			automaticFireCoroutine = null;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (automaticFireCoroutine != null)
			{
				StopCoroutine(automaticFireCoroutine);
				automaticFireCoroutine = null;
			}
			if ((bool)chargeParticles)
			{
				chargeParticles.Stop();
			}
			if ((bool)muzzleFlashParticles)
			{
				muzzleFlashParticles.Stop();
			}
			if ((bool)emberParticles)
			{
				emberParticles.Stop();
			}
		}
	}
	public class ChargeGun : RangedWeapon
	{
		[Header("Charging")]
		[SerializeField]
		private float maxChargeTime = 2.5f;

		[SerializeField]
		private AnimationCurve chargeCurve;

		[SerializeField]
		private PooledParticle chargeParticlePrefab;

		private SynchronizedField<bool> _isCharging;

		private SynchronizedField<float> _chargeStartTime;

		private PooledParticle chargeParticles;

		private float CurrentTime => (float)PhotonNetwork.time;

		private bool IsCharging
		{
			get
			{
				return _isCharging.Get();
			}
			set
			{
				if (!IsCharging)
				{
					_chargeStartTime.Set(CurrentTime);
				}
				_isCharging.Set(value);
			}
		}

		private float ChargeDuration => CurrentTime - _chargeStartTime.Get();

		private float ChargeAmount
		{
			get
			{
				float time = Mathf.InverseLerp(0f, maxChargeTime, ChargeDuration);
				return Mathf.Clamp01(chargeCurve.Evaluate(time));
			}
		}

		private void OnInputDown(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (base.IsMisfire || base.IsOnCooldown)
				{
					base.WeaponAudio.OnMisfire();
				}
				else
				{
					IsCharging = true;
				}
			}
		}

		private void OnInputUp(Tool thisTool)
		{
			if (base.hasAuthority && IsCharging)
			{
				IsCharging = false;
				Fire(ChargeAmount);
			}
		}

		private void OnInputCancelled(Tool thisTool)
		{
			if (base.hasAuthority && IsCharging)
			{
				IsCharging = false;
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				FireBullet(position, rotation, velocity, chargeAmount, shotId);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_isCharging = new SynchronizedField<bool>(this, "IS_CHARGING", defaultValue: false, SetterPermissionMode.AUTHORITY, OnChargingChanged);
			_chargeStartTime = new SynchronizedField<float>(this, "CHARGE_START_TIME", 0f, SetterPermissionMode.AUTHORITY);
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent += OnInputDown;
				base.Tool.InputUpEvent += OnInputUp;
				base.Tool.InputCancelledEvent += OnInputCancelled;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent -= OnInputDown;
				base.Tool.InputUpEvent -= OnInputUp;
				base.Tool.InputCancelledEvent -= OnInputCancelled;
			}
		}

		protected override void Start()
		{
			base.Start();
			OnChargingChanged();
		}

		private void OnChargingChanged()
		{
			if (IsCharging)
			{
				StartChargeParticles();
				base.WeaponAudio.OnCharge(ChargeDuration);
				return;
			}
			StopChargeParticles();
			base.WeaponAudio.OnStopCharge();
			if (base.WeaponAudio.IsLoopingFullyChargedAudio)
			{
				base.WeaponAudio.OnFullyChargedLoopStop();
			}
		}

		private void Update()
		{
			if (IsCharging && ChargeAmount >= 1f && !base.WeaponAudio.IsLoopingFullyChargedAudio)
			{
				base.WeaponAudio.OnStopCharge();
				base.WeaponAudio.OnFullyChargedLoopStart();
			}
		}

		private void StartChargeParticles()
		{
			StopChargeParticles();
			if (chargeParticlePrefab != null)
			{
				chargeParticles = ObjectPool.Instance.Acquire(chargeParticlePrefab);
				if (chargeParticles != null)
				{
					chargeParticles.Play(muzzleFlashOrigin, loop: true);
				}
			}
		}

		private void StopChargeParticles()
		{
			if (chargeParticles != null)
			{
				chargeParticles.Stop();
				chargeParticles = null;
			}
		}
	}
	public class ChargeGunProjectile : Bullet
	{
		[Header("Radius")]
		[SerializeField]
		private float minRadius = 0.02f;

		[SerializeField]
		private float maxRadius = 0.1f;

		[Header("Trail")]
		[SerializeField]
		private float minTrailLifetime = 0.5f;

		[SerializeField]
		private float maxTrailLifetime = 1.5f;

		[SerializeField]
		private float minTrailWidthExpansion = 1.1f;

		[SerializeField]
		private float maxTrailWidthExpansion = 3f;

		private PersistentBulletTrail persistentTrail;

		protected override void Awake()
		{
			base.Awake();
			persistentTrail = GetComponentInChildren<PersistentBulletTrail>(includeInactive: true);
		}

		public override void Fire(Vector3 position, Quaternion rotation, Vector3 initialVelocity, float impactForce, float chargeAmount, List<Rigidbody> ignoredRigidbodies, WeaponRaycastCollider.CollisionFilter collisionFilter, float maxLifetime, byte shotId, bool overrideAndDisableGravity = false)
		{
			base.Fire(position, rotation, initialVelocity, impactForce, chargeAmount, ignoredRigidbodies, collisionFilter, maxLifetime, shotId, overrideAndDisableGravity);
			chargeAmount = Mathf.Clamp01(chargeAmount);
			base.Radius = Mathf.Lerp(minRadius, maxRadius, chargeAmount);
			persistentTrail.Widths = Vector2.one * base.Radius;
			persistentTrail.Lifetime = Mathf.Lerp(minTrailLifetime, maxTrailLifetime, chargeAmount);
			persistentTrail.FinalWidthScale = Mathf.Lerp(minTrailWidthExpansion, maxTrailWidthExpansion, chargeAmount);
		}
	}
}
[RequireComponent(typeof(Renderer))]
public class BlinkingRenderer : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RendererMaterialPair[] renderers;

	[SerializeField]
	private FloatValueCurve blinkIntensityCurve;

	[SerializeField]
	private string colorShaderPropertyName = "_EmissionColor";

	[Header("Play On Awake")]
	[SerializeField]
	private bool playOnAwake;

	[SerializeField]
	private float playOnAwakeFrequency = 3f;

	private int emissionColorShaderId;

	private Color[] initialEmissionColors;

	private Coroutine blinkCoroutine;

	private float _blinkIntensity = 1f;

	private float BlinkIntensity
	{
		get
		{
			return _blinkIntensity;
		}
		set
		{
			float blinkIntensity = _blinkIntensity;
			_blinkIntensity = value;
			if (blinkIntensity != _blinkIntensity)
			{
				UpdateRenderer();
			}
		}
	}

	private void Start()
	{
		emissionColorShaderId = Shader.PropertyToID(colorShaderPropertyName);
		if (renderers == null || renderers.Length == 0)
		{
			UnityEngine.Debug.LogError(base.name + " Blinking Renderer is missing renderers.");
		}
		initialEmissionColors = new Color[renderers.Length];
		for (int i = 0; i < initialEmissionColors.Length; i++)
		{
			ref Color reference = ref initialEmissionColors[i];
			reference = renderers[i].Material.GetColor(emissionColorShaderId);
		}
		UpdateRenderer();
		if (playOnAwake)
		{
			StartBlinking(playOnAwakeFrequency);
		}
	}

	private void OnDestroy()
	{
		StopBlinking();
	}

	public void StartBlinking(float frequency)
	{
		StopBlinking();
		blinkCoroutine = StartCoroutine(BlinkCoroutine(frequency));
	}

	public void StopBlinking()
	{
		if (blinkCoroutine != null)
		{
			StopCoroutine(blinkCoroutine);
			blinkCoroutine = null;
		}
	}

	private IEnumerator BlinkCoroutine(float frequency)
	{
		float timer = 0f;
		float period = 1f / frequency;
		while (true)
		{
			for (timer = 0f; timer < period; timer += UnityEngine.Time.deltaTime)
			{
				float t = Mathf.InverseLerp(0f, period, timer);
				BlinkIntensity = blinkIntensityCurve.Evaluate(t);
				yield return null;
			}
		}
	}

	private void UpdateRenderer()
	{
		if (renderers != null && initialEmissionColors != null)
		{
			for (int i = 0; i < renderers.Length; i++)
			{
				renderers[i].Material.SetColor(emissionColorShaderId, Color.Lerp(Color.black, initialEmissionColors[i], BlinkIntensity));
			}
		}
	}
}
public class EnemyFacialAnimator : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private JitteringSprite faceJitter;

	[HideInInspector]
	public Sprite faceSprite;

