namespace RecRoom.Core.AI
{
	[RequireComponent(typeof(PhotonView))]
	public class QuestEnemyArticulatingAccessory : Photon.MonoBehaviour
	{
		public Steering Steering { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			Steering = GetComponent<Steering>();
		}

		public Vector3 GetLookAtVector(Vector3 position, bool inXZPlane = false)
		{
			Vector3 vector = position - base.transform.position;
			if (inXZPlane)
			{
				vector = Vector3.ProjectOnPlane(vector, Vector3.up);
			}
			return vector.normalized;
		}
	}
