			}
		}

		private int FacesAlive
		{
			get
			{
				int num = 0;
				for (int i = 0; i < faces.Length; i++)
				{
					if (faces[i] != null && !faces[i].IsDead)
					{
						num++;
					}
				}
				return num;
			}
		}

		public static event FaceDeath FaceDeathEvent
		{
			add
			{
				FaceDeath faceDeath = QuestJumbotronBossEnemy.m_FaceDeathEvent;
				FaceDeath faceDeath2;
				do
				{
					faceDeath2 = faceDeath;
					faceDeath = Interlocked.CompareExchange(ref QuestJumbotronBossEnemy.m_FaceDeathEvent, (FaceDeath)Delegate.Combine(faceDeath2, value), faceDeath);
				}
				while (faceDeath != faceDeath2);
			}
			remove
			{
				FaceDeath faceDeath = QuestJumbotronBossEnemy.m_FaceDeathEvent;
				FaceDeath faceDeath2;
				do
				{
					faceDeath2 = faceDeath;
					faceDeath = Interlocked.CompareExchange(ref QuestJumbotronBossEnemy.m_FaceDeathEvent, (FaceDeath)Delegate.Remove(faceDeath2, value), faceDeath);
				}
				while (faceDeath != faceDeath2);
