		public new static event EnemyAction TookDamageEvent
		{
			add
			{
				EnemyAction enemyAction = QuestJumbotronBossEnemy.m_TookDamageEvent;
				EnemyAction enemyAction2;
				do
				{
					enemyAction2 = enemyAction;
					enemyAction = Interlocked.CompareExchange(ref QuestJumbotronBossEnemy.m_TookDamageEvent, (EnemyAction)Delegate.Combine(enemyAction2, value), enemyAction);
				}
				while (enemyAction != enemyAction2);
			}
			remove
			{
				EnemyAction enemyAction = QuestJumbotronBossEnemy.m_TookDamageEvent;
				EnemyAction enemyAction2;
				do
				{
					enemyAction2 = enemyAction;
					enemyAction = Interlocked.CompareExchange(ref QuestJumbotronBossEnemy.m_TookDamageEvent, (EnemyAction)Delegate.Remove(enemyAction2, value), enemyAction);
