		protected override void Awake()
		{
			base.Awake();
			cachesLatestVisibleTargetPosition = true;
			weapon = GetComponentInChildren<QuestJumbotronBossWeapon>();
			_searchYaw = new SynchronizedField<float>(this, "LOOK_YAW", 0f, SetterPermissionMode.AUTHORITY);
			_retargetPlayerCount = new SynchronizedField<int>(this, "RETARGET_COUNT", 0, SetterPermissionMode.AUTHORITY);
			behaviorTimer = new SynchronizedTimer(this, "BEHAVIOR", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("BEHAVIOR", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterWakingUpState, null, OnUpdateWakingUpState);
			behaviorStateMachine.AddState(1, OnEnterFindTargetState, null, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(2, OnEnterFollowTargetState, null, OnUpdateFollowTargetState);
			behaviorStateMachine.AddState(3, OnEnterChargeAttackState, null, OnUpdateChargeAttackState);
			behaviorStateMachine.AddState(4, OnEnterAttackState, null, OnUpdateAttackState);
			behaviorStateMachine.AddState(5, OnEnterFaceBrokeState, OnExitFaceBrokeState, OnUpdateFaceBrokeState);
			faces = GetComponentsInChildren<QuestJumbotronBossFace>();
			int num = base.MaxHealth / faces.Length;
			int num2 = base.MaxHealth - num * faces.Length;
			for (int i = 0; i < faces.Length; i++)
			{
				int defaultHealth = num + ((i == faces.Length - 1) ? num2 : 0);
				faces[i].Initialize(this, i, defaultHealth);
				faces[i].HealthChangeEvent += OnFaceHealthChanged;
				faces[i].DeathEvent += OnFaceDeath;
			}
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
			SetRigidbodyExParameters();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (faces != null)
			{
				for (int i = 0; i < faces.Length; i++)
				{
					faces[i].HealthChangeEvent -= OnFaceHealthChanged;
					faces[i].DeathEvent -= OnFaceDeath;
				}
			}
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override void OnActiveCombatUpdate()
		{
			base.OnActiveCombatUpdate();
			if (base.hasAuthority && base.Health > 0 && FacesAlive == 0)
			{
				base.Health = 0;
			}
		}

		protected override void OnDisengagedStart()
		{
			base.OnDisengagedStart();
			Sleep();
		}

		protected override void OnDisengagedEnd()
		{
			base.OnDisengagedEnd();
			WakeUp();
		}

		private void Sleep()
		{
			if (faces != null)
			{
				QuestJumbotronBossFace[] array = faces;
				foreach (QuestJumbotronBossFace questJumbotronBossFace in array)
				{
					questJumbotronBossFace.IsSleeping = true;
				}
			}
			enemyAnimator.IsDisengaged = true;
			weapon.IsSleeping = true;
		}

		private void WakeUp()
		{
			if (faces != null)
			{
				QuestJumbotronBossFace[] array = faces;
				foreach (QuestJumbotronBossFace questJumbotronBossFace in array)
				{
					questJumbotronBossFace.IsSleeping = false;
				}
			}
			enemyAnimator.IsDisengaged = false;
			weapon.IsSleeping = false;
			AudioManager.Play2DSFX(wakeUpVO);
		}

		private void OnEnterWakingUpState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(wakeUpDuration);
			}
		}

		private void OnUpdateWakingUpState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(1);
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			Combatant result = Combatant.Invalid;
			if (LastAttackerIsValidTarget())
			{
				result = base.LastAttacker;
			}
			else if (SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target) && RetargetPlayerCount < maxRetargetPlayerCount)
			{
				result = base.Target;
			}
			else
			{
				FindNearbyTargetsInVisionCone(isPatrolling, lineOfSightOrigin.position, lineOfSightOrigin.forward, maxTargetLookAngle, maxLookForTargetDistance, inXZPlane: true, mustHaveLineOfSight: true, targetScratchSpace);
				if (targetScratchSpace.Count > 0)
				{
					int index = UnityEngine.Random.Range(0, targetScratchSpace.Count);
					result = targetScratchSpace[index];
				}
			}
			return result;
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			weapon.Steering.StopLooking();
			weapon.Steering.MaxAngularSpeed = lookForTargetsRotationSpeed;
			if (base.hasAuthority)
			{
				AuthorityUpdateLookForTarget();
			}
		}

		private void OnUpdateFindTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant combatant = FindTarget();
			if (combatant.IsValid)
			{
				if (combatant != base.Target)
				{
					RetargetPlayerCount = 0;
				}
				else
				{
					RetargetPlayerCount++;
				}
				base.Target = combatant;
				base.LastAttacker = Combatant.Invalid;
				behaviorStateMachine.EnterState(2);
			}
			else
			{
				AuthorityUpdateLookForTarget();
			}
		}

		private void AuthorityUpdateLookForTarget()
		{
			if (base.hasAuthority)
			{
				if (weapon.Steering.ReachedLookTarget)
				{
					SearchYaw = UnityEngine.Random.Range(0f, 360f);
				}
				Vector3 targetDirection = Quaternion.Euler(lookForTargetPitchAngle, SearchYaw, 0f) * Vector3.forward;
				weapon.Steering.Look(targetDirection, slowdownAngle, 0.1f);
			}
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			weapon.Steering.StopLooking();
			weapon.Steering.MaxAngularSpeed = lookAtTargetRotationSpeed;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(lookAtTargetDuration);
			}
		}

		private void OnUpdateFollowTargetState()
		{
			if (base.hasAuthority)
			{
				weapon.Steering.Look(weapon.GetLookAtVector(latestVisibleTargetHeadPosition));
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(3);
				}
			}
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			weapon.Steering.StopLooking();
			weapon.Steering.MaxAngularSpeed = lookAtTargetRotationSpeed;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(chargeAttackDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (base.hasAuthority)
			{
				weapon.Steering.Look(weapon.GetLookAtVector(latestVisibleTargetHeadPosition));
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(4);
				}
			}
		}

		private void OnEnterAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			weapon.Steering.StopLooking();
			weapon.Steering.MaxAngularSpeed = lookAtTargetRotationSpeed;
			enemyAudio.OnAttack();
			if (base.hasAuthority)
			{
				AuthorityFireRangedWeaponAtTarget(canFireAtLastVisiblePosition: true);
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackState()
		{
			if (base.hasAuthority)
			{
				weapon.Steering.Look(weapon.GetLookAtVector(latestVisibleTargetHeadPosition));
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(1);
				}
			}
		}

		private void OnEnterFaceBrokeState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(screenBrokeWaitDuration);
			}
		}

		private void OnUpdateFaceBrokeState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(1);
			}
		}

		private void OnExitFaceBrokeState(ushort nextStateId, ushort nextSubStateId)
		{
			if (QuestJumbotronBossEnemy.FaceDeathEvent != null)
			{
				QuestJumbotronBossEnemy.FaceDeathEvent(this, FacesAlive, faces.Length);
			}
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			SetRigidbodyExParameters();
		}

		protected override void OnStunEnd(bool interruptsCustomBehaviour)
		{
			base.OnStunEnd(interruptsCustomBehaviour);
			SetRigidbodyExParameters();
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			SetRigidbodyExParameters();
			enemyAnimator.PlayDeath();
			AudioManager.Play2DSFX(deathVO);
			if (!base.hasAuthority)
			{
				return;
			}
			for (int i = 0; i < faces.Length; i++)
			{
				if (!faces[i].IsDead && faces[i].Health > 0)
				{
					faces[i].Health = 0;
				}
			}
		}

		protected override void DetectStuckEnemy()
		{
		}

		protected override bool AuthorityTryApplyAttackInternal(Combatant attacker, Weapon weapon, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			QuestJumbotronBossFace face = GetFace(armorType);
			if (base.hasAuthority && base.Health > 0 && initialized && !base.IsDisengaged && face != null && face.CanTakeDamage)
			{
				damage = GetDamageCombatSettings(damage, damageType, armorType);
				if (damage > 0)
				{
					bool arg = face.Health <= damage;
					base.photonView.RpcAll(base.RpcOnTookDamage, attacker, damageType, armorType, damage, arg, impact.Point, impact.SurfaceNormal);
					base.LastAttacker = attacker;
					base.LastAttackerWeapon = weapon;
					face.Health -= damage;
					AuthorityStun(damageType, armorType);
				}
				return true;
			}
			return false;
		}

		protected override void OnTookDamage(Combatant attacker, WeaponDamageType damageType, EnemyArmorType armorType, int damage, bool killingBlow, Vector3 hitPoint, Vector3 hitNormal)
		{
			base.OnTookDamage(attacker, damageType, armorType, damage, killingBlow, hitPoint, hitNormal);
			if (QuestJumbotronBossEnemy.TookDamageEvent != null)
			{
				QuestJumbotronBossEnemy.TookDamageEvent(this);
			}
		}

		private void OnFaceHealthChanged(QuestJumbotronBossFace face, int newHealth, int maxHealth, PhotonPlayer attackingPlayer)
		{
			if (base.hasAuthority)
			{
				int num = 0;
				for (int i = 0; i < faces.Length; i++)
				{
					num += faces[i].Health;
				}
				base.Health = num;
			}
		}

		private void OnFaceDeath(QuestJumbotronBossFace face, PhotonPlayer attackingPlayer)
		{
			for (int i = 0; i < screenBreakAudio.Length; i++)
			{
				AudioManager.Play2DSFX(screenBreakAudio[i]);
			}
			if (randomScreenBreakVO != null)
			{
				AudioManager.PlayRandom2DSFX(randomScreenBreakVO, base.transform.position);
			}
			if (base.hasAuthority && base.IsAlive && behaviorStateMachine.CurrentStateId != 5)
			{
				behaviorStateMachine.EnterState(5);
			}
		}

		private QuestJumbotronBossFace GetFace(EnemyArmorType armorType)
		{
			QuestJumbotronBossFace result = null;
			for (int i = 0; i < faces.Length; i++)
			{
				if (faces[i].ArmorType == armorType)
				{
					result = faces[i];
					break;
				}
			}
			return result;
		}

		public override void AuthorityOnDamageApplyForce(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 force, Vector3 point)
		{
			base.AuthorityOnDamageApplyForce(damageType, armorType, Vector3.zero, point);
		}

		public override void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			base.AuthorityOnDamageChangeVelocity(damageType, armorType, Vector3.zero, Vector3.zero);
		}

		public override void AuthorityClearVelocity()
		{
			base.AuthorityClearVelocity();
		}

		private void SetRigidbodyExParameters()
		{
			base.RigidbodyEx.useGravity = false;
			base.RigidbodyEx.AddKinematic(this);
			base.RigidbodyEx.constraints = RigidbodyConstraints.FreezeAll;
		}
	}
	public class QuestJumbotronBossFace : UnityEngine.MonoBehaviour
