		}

		private void Start()
		{
			OnHealthChange();
		}

		public void Initialize(QuestJumbotronBossEnemy thisEnemy, int id, int defaultHealth)
		{
			this.thisEnemy = thisEnemy;
			maxHealth = defaultHealth;
			_health = new SynchronizedField<int>(thisEnemy, $"FACE{id}_HEALTH", maxHealth, SetterPermissionMode.AUTHORITY, OnHealthChange);
