		private void OnHealthChange()
		{
			if (this.HealthChangeEvent != null)
			{
				this.HealthChangeEvent(this, Health, maxHealth, thisEnemy.authority);
			}
			UpdateVisuals();
			if (Animator != null && Health > 0 && Health < maxHealth)
			{
				Animator.SetTrigger(ANIMATION_HIT_ID);
			}
			if (facialAnimator != null)
			{
				facialAnimator.OnHit();
			}
			if (PhotonNetwork.isMasterClient && Health <= 0 && !IsDead)
			{
				IsDead = true;
			}
		}

		private void OnIsDeadChange()
		{
			if (IsDead)
			{
				if (this.DeathEvent != null)
				{
					this.DeathEvent(this, thisEnemy.authority);
				}
				if (Animator != null)
				{
					Animator.SetTrigger(ANIMATION_DEATH_ID);
				}
			}
		}

		private void UpdateVisuals()
		{
			if (Animator != null)
			{
				Animator.SetBool(ANIMATION_SLEEPING_ID, IsSleeping);
			}
			if (healthBar != null)
			{
				healthBar.OnHealthChange(Health, maxHealth, localPlayerCausedDamage: true);
			}
		}
	}
	public class QuestJumbotronBossWeapon : UnityEngine.MonoBehaviour
	{
