	public class QuestSciFiChargeShotEnemy : Enemy
	{
		private enum BehaviorState
		{
			POST_SPAWN = 0,
			FIND_TARGET = 1,
			FOLLOW_TARGET = 2,
			ATTACK_DELAY = 3,
			ATTACK = 4,
			INVALID = 65535
		}

		private enum FollowTargetSubState
		{
			PREPARE_CHARGE = 0,
			CHARGE_ATTACK = 1,
			INVALID = 65535
		}

		[Header("Post Spawn")]
		[SerializeField]
		private float postSpawnDelay = 0.5f;

		[Header("Scan For Target Head Parameters")]
		[SerializeField]
		private float scanForTargetHeadSlowdownAngle = 10f;

		[SerializeField]
		private float maxScanForTargetHeadYaw = 35f;

		[SerializeField]
		private float scanForTargetHeadPitch = 8f;

		[SerializeField]
		private float maxVisionConeAngle = 15f;

		[Header("Follow Target")]
		[SerializeField]
		private float snapToTargetAngularSpeedDegrees = 360f;

		[SerializeField]
		private float followTargetMovementSpeed = 1.5f;

		[SerializeField]
		private float followTargetMovementMaxForce = 50f;

		[SerializeField]
		private float followTargetMovementSlowdownDistance = 1f;

		[SerializeField]
		private float followTargetAngularSpeedDegrees = 90f;

		[SerializeField]
		private float targetAcquiredHeadLaserOffset = 0.1f;

		[SerializeField]
		private float desiredTargetOffset = 1.5f;

		[SerializeField]
		private float minRandomOffsetAngle = 30f;

		[SerializeField]
		private float maxRandomOffsetAngle = 45f;

		[Header("Head")]
		[SerializeField]
		private QuestEnemyArticulatingAccessory head;

		[SerializeField]
		private Transform laser;

		[Header("Attack")]
		[SerializeField]
		private float chargePrepareDuration = 0.5f;

		[SerializeField]
		private float chargeAttackDuration = 3f;

		[SerializeField]
		private float attackDelayDuration = 0.5f;

		[SerializeField]
		private float attackDuration = 0.5f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip[] alertVO;

		[SerializeField]
		private RecRoomAudioClip alertSFX;

		private SynchronizedField<float> _headYaw;

		private SynchronizedField<int> _lastCriticalHitAttackerId;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private EnemyFacialAnimator facialAnimator;

		private BlinkingRenderer blinkingRenderer;

		private Vector3 attackTarget = Vector3.zero;

		private float HeadYaw
		{
			get
			{
				return _headYaw.Get();
			}
			set
			{
				_headYaw.Set(value);
			}
		}

		private Combatant LastCriticalHitAttacker
		{
			get
			{
				return new Combatant(_lastCriticalHitAttackerId.Get());
			}
			set
			{
				_lastCriticalHitAttackerId.Set(value.ID);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			cachesLatestVisibleTargetPosition = true;
			facialAnimator = GetComponentInChildren<EnemyFacialAnimator>();
			blinkingRenderer = GetComponentInChildren<BlinkingRenderer>();
			_headYaw = new SynchronizedField<float>(this, "HY", 0f, SetterPermissionMode.AUTHORITY);
			_lastCriticalHitAttackerId = new SynchronizedField<int>(this, "LCHAID", -1, SetterPermissionMode.AUTHORITY);
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterPostSpawnState, null, OnUpdatePostSpawnState);
			behaviorStateMachine.AddState(1, OnEnterFindTargetState, OnExitFindTargetState, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(2, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
			behaviorStateMachine.AddState(2, 0, OnEnterPrepareChargeSubState, null, OnUpdatePrepareChargeSubState);
			behaviorStateMachine.AddState(2, 1, OnEnterChargeAttackSubState, OnExitChargeAttackSubState, OnUpdateChargeAttackSubState);
			behaviorStateMachine.AddState(3, OnEnterAttackDelayState, null, OnUpdateAttackDelayState);
			behaviorStateMachine.AddState(4, OnEnterAttackState, null, OnUpdateAttackState);
		}

		protected override void Start()
		{
			base.Start();
			laser.gameObject.SetActive(value: false);
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(1);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		public override void AuthorityOnDamageApplyForce(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 force, Vector3 point)
		{
			force = Vector3.ProjectOnPlane(force, base.Steering.SurfaceNormal);
			base.AuthorityOnDamageApplyForce(damageType, armorType, force, point);
		}

		public override void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority)
			{
				velocity = Vector3.ProjectOnPlane(velocity, base.Steering.SurfaceNormal);
				base.AuthorityOnDamageChangeVelocity(damageType, armorType, velocity, angularVelocity);
			}
		}

		private void OnEnterPostSpawnState(ushort previousStateId, ushort nextStateId)
		{
			laser.gameObject.SetActive(value: false);
			head.Steering.StopAll();
			head.Steering.MaxAngularSpeed = movementAngularSpeed;
			if (base.hasAuthority)
			{
				HeadYaw = 0f;
				behaviorTimer.StartTimer(postSpawnDelay);
			}
		}

		private void OnUpdatePostSpawnState()
		{
			if (base.hasAuthority)
			{
				Vector3 targetDirection = base.transform.rotation.TransformRotation(Quaternion.Euler(scanForTargetHeadPitch, HeadYaw, 0f)) * Vector3.forward;
				head.Steering.Look(targetDirection, scanForTargetHeadSlowdownAngle);
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(1);
				}
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			UpdateLaser(out var hitPoint, out var _);
			if (LastCriticalHitAttackerIsValidTarget())
			{
				return LastCriticalHitAttacker;
			}
			float magnitude = Vector3.ProjectOnPlane(hitPoint - base.transform.position, Vector3.up).magnitude;
			FindNearbyTargetsInVisionCone(isPatrolling, head.transform.position, head.transform.forward, maxVisionConeAngle, magnitude, inXZPlane: false, mustHaveLineOfSight: true, targetScratchSpace);
			if (targetScratchSpace.Count > 0)
			{
				return targetScratchSpace[0];
			}
			return Combatant.Invalid;
		}

		private bool LastCriticalHitAttackerIsValidTarget()
		{
			return LastCriticalHitAttacker.IsValid && !SingletonMonoBehaviour<EnemyManager>.Instance.IsAlly(base.Team, LastCriticalHitAttacker);
		}

		protected override void OnPatrolStart()
		{
			base.OnPatrolStart();
			head.Steering.StopAll();
			head.Steering.MaxAngularSpeed = movementAngularSpeed;
			LastCriticalHitAttacker = Combatant.Invalid;
		}

		protected override void OnPatrolUpdate()
		{
			base.OnPatrolUpdate();
			UpdateLaser(out var _, out var _);
			if (base.hasAuthority)
			{
				UpdateHeadSeeking();
			}
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			head.Steering.StopAll();
			head.Steering.MaxAngularSpeed = movementAngularSpeed;
			base.Steering.StopAll();
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			base.Steering.MaxHorizontalSpeed = movementSlowdownDistance;
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			if (base.hasAuthority)
			{
				HeadYaw = 0f;
			}
		}

		private void OnUpdateFindTargetState()
		{
			UpdateLaser(out var _, out var _);
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant target = FindTarget();
			if (target.IsValid)
			{
				base.Target = target;
				base.LastAttacker = Combatant.Invalid;
				LastCriticalHitAttacker = Combatant.Invalid;
				behaviorStateMachine.EnterState(2, 0);
				return;
			}
			UpdateHeadSeeking();
			if (LastAttackerIsValidTarget() && SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.LastAttacker))
			{
				Vector3 floorPosition = base.LastAttacker.FloorPosition;
				if (!base.Steering.PathIsValid(floorPosition, desiredTargetOffset * 1.1f) || base.Steering.ReachedPathDestination)
				{
					Vector3 randomOffsetPosition = GetRandomOffsetPosition(floorPosition, desiredTargetOffset, minRandomOffsetAngle, maxRandomOffsetAngle);
					base.Steering.Path(randomOffsetPosition, movementSlowdownDistance);
				}
			}
			else
			{
				AuthorityStartPatrol();
			}
		}

		private void OnExitFindTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			head.Steering.StopAll();
			base.Steering.StopSeeking();
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			head.Steering.StopAll();
			head.Steering.MaxAngularSpeed = followTargetAngularSpeedDegrees;
			base.Steering.StopAll();
			base.Steering.MaxAngularSpeed = followTargetAngularSpeedDegrees;
			base.Steering.MaxHorizontalSpeed = followTargetMovementSpeed;
			base.Steering.MaxHorizontalSteeringForce = followTargetMovementMaxForce;
		}

		private void OnUpdateFollowTargetState()
		{
			UpdateLaser(out var _, out var _);
			if (!base.hasAuthority)
			{
				return;
			}
			if (LastCriticalHitAttackerIsValidTarget())
			{
				base.Target = LastCriticalHitAttacker;
				LastCriticalHitAttacker = Combatant.Invalid;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				AuthorityStartPatrol();
				return;
			}
			if (!base.Steering.PathIsValid(latestVisibleTargetFloorPosition, desiredTargetOffset * 1.1f) || base.Steering.ReachedPathDestination)
			{
				Vector3 randomOffsetPosition = GetRandomOffsetPosition(latestVisibleTargetFloorPosition, desiredTargetOffset, minRandomOffsetAngle, maxRandomOffsetAngle);
				base.Steering.Path(randomOffsetPosition, followTargetMovementSlowdownDistance);
			}
			Vector3 position = latestVisibleTargetHeadPosition - Vector3.up * targetAcquiredHeadLaserOffset;
			Vector3 lookAtVector = head.GetLookAtVector(position);
			head.Steering.Look(lookAtVector);
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
		}

		protected override void OnTargetChange()
		{
			base.OnTargetChange();
			if (base.Target.IsValid)
			{
				if (alertVO != null)
				{
					AudioManager.PlayRandom3DSFX(alertVO, base.transform);
				}
				if (alertSFX != null && alertSFX.audioClip != null)
				{
					AudioManager.Play2DSFX(alertSFX);
				}
			}
		}

		private void OnEnterPrepareChargeSubState(ushort previousStateId, ushort previousSubStateId)
		{
			head.Steering.MaxAngularSpeed = snapToTargetAngularSpeedDegrees;
			base.Steering.MaxAngularSpeed = snapToTargetAngularSpeedDegrees;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(chargePrepareDuration);
			}
		}

		private void OnUpdatePrepareChargeSubState()
		{
			if (base.hasAuthority)
			{
				base.Steering.Look(GetLookAtVector(latestVisibleTargetFloorPosition, inXZPlane: true));
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(2, 1);
				}
			}
		}

		private void OnExitPrepareChargeSubState(ushort nextStateId, ushort nextSubStateId)
		{
			head.Steering.MaxAngularSpeed = followTargetAngularSpeedDegrees;
			base.Steering.MaxAngularSpeed = followTargetAngularSpeedDegrees;
			base.Steering.StopLooking();
		}

		private void OnEnterChargeAttackSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (enemyParticles != null)
			{
				enemyParticles.StartCharge(laser);
			}
			enemyAudio.StartCharge(looping: false);
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(chargeAttackDuration);
			}
		}

		private void OnUpdateChargeAttackSubState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				behaviorStateMachine.EnterState(3);
			}
		}

		private void OnExitChargeAttackSubState(ushort nextStateId, ushort nextSubStateId)
		{
			if (enemyParticles != null)
			{
				enemyParticles.StopCharge();
			}
			enemyAudio.StopCharge();
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
		}

		private void OnEnterAttackDelayState(ushort previousStateId, ushort previousSubStateId)
		{
			laser.gameObject.SetActive(value: false);
			attackTarget = latestVisibleTargetHeadPosition - Vector3.up * targetAcquiredHeadLaserOffset;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackDelayDuration);
			}
		}

		private void OnUpdateAttackDelayState()
		{
			if (base.hasAuthority)
			{
				Vector3 lookAtVector = GetLookAtVector(attackTarget, inXZPlane: true);
				head.Steering.Look(lookAtVector);
				base.Steering.Look(lookAtVector);
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(4);
				}
			}
		}

		private void OnEnterAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			laser.gameObject.SetActive(value: false);
			if (base.hasAuthority)
			{
				if (rangedWeapon != null)
				{
					rangedWeapon.AuthorityFire(attackTarget);
				}
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackState()
		{
			if (base.hasAuthority && behaviorTimer.TimerOver)
			{
				AuthorityStartPatrol();
			}
		}

		protected override void OnInterruptedRecoveryStart()
		{
			base.OnInterruptedRecoveryStart();
			if (base.hasAuthority)
			{
				Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				head.Steering.Look(normalized);
				base.Steering.Look(normalized);
			}
		}

		protected override void OnInterruptedRecoveryEnd()
		{
			base.OnInterruptedRecoveryEnd();
			head.Steering.StopLooking();
			base.Steering.StopLooking();
		}

		protected override void OnTookDamage(Combatant attacker, WeaponDamageType damageType, EnemyArmorType armorType, int damage, bool killingBlow, Vector3 hitPoint, Vector3 hitNormal)
		{
			base.OnTookDamage(attacker, damageType, armorType, damage, killingBlow, hitPoint, hitNormal);
			if (facialAnimator != null)
			{
				facialAnimator.OnHit();
			}
			if (base.hasAuthority && Enemy.IsCriticalHit(armorType))
			{
				LastCriticalHitAttacker = attacker;
			}
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			laser.gameObject.SetActive(value: false);
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			if (blinkingRenderer != null)
			{
				blinkingRenderer.StopBlinking();
			}
			laser.gameObject.SetActive(value: false);
		}

		private void UpdateLaser(out Vector3 hitPoint, out Vector3 hitNormal)
		{
			Vector3 forward = head.Steering.transform.forward;
			Enemy.TryGetRaycastHitPoint(head.Steering.transform.position, forward, 50f, 362036736, out var distance, out hitPoint, out hitNormal);
			laser.gameObject.SetActive(value: true);
			forward = (hitPoint - laser.position).normalized;
			laser.rotation = Quaternion.LookRotation(forward);
			Vector3 localScale = laser.localScale;
			localScale.z = distance;
			laser.localScale = localScale;
		}

		private void UpdateLaserHelper(Vector3 direction, out float hitDistance, out Vector3 hitPoint, out Vector3 hitNormal)
		{
			Enemy.TryGetRaycastHitPoint(head.Steering.transform.position, direction, 50f, 362036736, out hitDistance, out hitPoint, out hitNormal);
			laser.gameObject.SetActive(value: true);
			direction = (hitPoint - laser.position).normalized;
			laser.rotation = Quaternion.LookRotation(direction);
			Vector3 localScale = laser.localScale;
			localScale.z = hitDistance;
			laser.localScale = localScale;
		}

		private void UpdateHeadSeeking()
		{
			if (head.Steering.ReachedLookTarget || behaviorTimer.TimerOver)
			{
				float num = 2f * maxScanForTargetHeadYaw;
				float maxRunningTime = num / movementAngularSpeed * 1.05f;
				float num2 = Mathf.Sign(HeadYaw);
				HeadYaw = -1f * num2 * maxScanForTargetHeadYaw;
				behaviorTimer.StartTimer(maxRunningTime);
			}
			Vector3 targetDirection = base.transform.rotation.TransformRotation(Quaternion.Euler(scanForTargetHeadPitch, HeadYaw, 0f)) * Vector3.forward;
			head.Steering.Look(targetDirection, scanForTargetHeadSlowdownAngle);
		}

		public override void TransferOwnership(PhotonPlayer player)
		{
			base.TransferOwnership(player);
			head.photonView.TransferOwnership(player);
		}
	}
}
public class FadeOverDistance : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float maxDistance = 16f;

	[SerializeField]
	private float minDistance = 1f;

	[SerializeField]
	private float maxDistanceAlpha = 0.15f;

	[SerializeField]
	private float minDistanceAlpha = 1f;

	private Renderer renderer;

	private int shaderColorId;

	private void Awake()
	{
		renderer = GetComponent<Renderer>();
		if (renderer == null)
		{
			base.enabled = false;
		}
		shaderColorId = Shader.PropertyToID("_TintColor");
	}

	private void Update()
	{
		if (SingletonMonoBehaviour<CameraRig>.Instance != null && renderer != null)
		{
			float sqrMagnitude = (base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.transform.position).sqrMagnitude;
			float t = Mathf.InverseLerp(minDistance * minDistance, maxDistance * maxDistance, sqrMagnitude);
			Color color = renderer.material.GetColor(shaderColorId);
			color.a = Mathf.SmoothStep(minDistanceAlpha, maxDistanceAlpha, t);
			renderer.material.SetColor(shaderColorId, color);
		}
	}
}
public class LaserBillboard : UnityEngine.MonoBehaviour
{
	private void OnWillRenderObject()
	{
		if (!(base.transform.parent == null))
		{
			Vector3 forward = base.transform.parent.forward;
			Vector3 vector = (base.transform.position - Camera.current.transform.position).normalized;
			if (Mathf.Abs(Vector3.Dot(forward, vector)) >= 1f - Mathf.Epsilon)
			{
				vector = Vector3.up;
			}
			Vector3 vector2 = Vector3.Cross(vector, forward);
			Vector3 forward2 = Vector3.Cross(forward, vector2);
			base.transform.rotation = Quaternion.LookRotation(forward2, vector2);
		}
	}
}
public class LaserCapBillboard : UnityEngine.MonoBehaviour
{
	private void OnWillRenderObject()
	{
		Vector3 normalized = (base.transform.position - Camera.current.transform.position).normalized;
		normalized = Vector3.ProjectOnPlane(normalized, Vector3.up);
		base.transform.rotation = Quaternion.LookRotation(normalized, Vector3.up);
	}
}
public class Quest_Scifi_RotatingSiren : UnityEngine.MonoBehaviour
{
	public float degreesPerSecond;

	private void Update()
	{
		base.transform.Rotate(0f, 0f, degreesPerSecond * UnityEngine.Time.deltaTime, Space.Self);
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestExplosiveEnemy : Enemy
	{
		private enum BehaviorState
		{
			FIND_TARGET = 0,
			FOLLOW_TARGET = 1,
			INVALID = 65535
		}

		[Header("Proximity")]
		[SerializeField]
		private float warningFrequency = 4f;

		[SerializeField]
		private RecRoomAudioClip warningAudioBeep;

		[Header("Explosion")]
		[SerializeField]
		private float explosionDistance = 2f;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private BlinkingRenderer blinkingRenderer;

		private Coroutine warningAudioCoroutine;

		protected override void Awake()
		{
			base.Awake();
			blinkingRenderer = GetComponentInChildren<BlinkingRenderer>();
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, null, null, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
		}

		protected override void Start()
		{
			base.Start();
			StartWarningFeedback();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			StopWarningFeedback();
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			Combatant invalid = Combatant.Invalid;
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			if (trackTargetCount)
			{
				return FindLeastTargetedNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
			}
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					behaviorStateMachine.EnterState(1);
				}
			}
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
		}

		private void OnUpdateFollowTargetState()
		{
			float distanceToClosestTargetSqr = 0f;
			Combatant closestOpponent = SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
			if (!base.hasAuthority)
			{
				return;
			}
			if (closestOpponent.IsValid && distanceToClosestTargetSqr <= explosionDistance * explosionDistance)
			{
				if (base.hasAuthority)
				{
					AuthorityExplode();
				}
				return;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				behaviorStateMachine.EnterState(0);
				return;
			}
			Vector3 floorPosition = base.Target.FloorPosition;
			if (!base.Steering.PathIsValid(floorPosition, 0.1f))
			{
				base.Steering.Path(floorPosition);
			}
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopPathing();
		}

		private void AuthorityExplode()
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcExplode);
			}
		}

		[PunRPC]
		private void RpcExplode()
		{
			StopWarningFeedback();
			if (enemyParticles != null)
			{
				enemyParticles.OnExplode();
			}
			enemyAudio.OnExplode();
			WeaponImpact impact = default(WeaponImpact);
			SingletonMonoBehaviour<EnemyManager>.Instance.GetOpponentsInRadius(this, explosionDistance, mustHaveLineOfSight: true, targetScratchSpace);
			for (int i = 0; i < targetScratchSpace.Count; i++)
			{
				if (targetScratchSpace[i].Player != null)
				{
					impact.Point = targetScratchSpace[i].HeadPosition;
					OnPlayerImpact(this, targetScratchSpace[i].Player, Player.BodyPart.Head, impact);
				}
			}
			if (base.hasAuthority)
			{
				base.Health = 0;
				AuthorityShatter(-base.transform.forward, EnemyArmorType.CRITICAL_HIT);
			}
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			StopWarningFeedback();
		}

		private void StartWarningFeedback()
		{
			StopWarningFeedback();
			blinkingRenderer.StartBlinking(warningFrequency);
			warningAudioCoroutine = StartCoroutine(WarningAudioCoroutine(warningFrequency));
		}

		private void StopWarningFeedback()
		{
			blinkingRenderer.StopBlinking();
			if (warningAudioCoroutine != null)
			{
				StopCoroutine(warningAudioCoroutine);
				warningAudioCoroutine = null;
			}
		}

		private IEnumerator WarningAudioCoroutine(float frequency)
		{
			float period = 1f / frequency;
			float timer = 0f;
			while (true)
			{
				PlayWarningAudio();
				for (timer = 0f; timer < period; timer += UnityEngine.Time.deltaTime)
				{
					yield return null;
				}
			}
		}

		private void PlayWarningAudio()
		{
			if (warningAudioBeep != null && warningAudioBeep.audioClip != null)
			{
				AudioManager.Play3DSFX(warningAudioBeep, base.transform);
			}
		}

		protected override void OnInterruptedRecoveryStart()
		{
			base.OnInterruptedRecoveryStart();
			if (base.hasAuthority)
			{
				base.Steering.Look(Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized);
			}
		}

		protected override void OnInterruptedRecoveryEnd()
		{
			base.OnInterruptedRecoveryEnd();
			base.Steering.StopLooking();
		}
	}
	public class QuestSciFiRangedEnemy : Enemy
	{
		private enum BehaviorState
		{
			FIND_TARGET = 0,
			CHARGE_ATTACK = 1,
			ATTACK_TARGET = 2,
			DASH = 3,
			INVALID = 65535
		}

		[Header("Look For Target")]
		[SerializeField]
		private float engageRadius = 20f;

		[SerializeField]
		private int maxRetargetPlayerCount = 3;

		[Header("Attacking")]
		[SerializeField]
		private bool attacksSameTargetUntilDead = true;

		[SerializeField]
		private float attackChargeDuration = 1f;

		[SerializeField]
		private float attackDuration = 3f;

		[Header("Dash")]
		[SerializeField]
		private float dashSpeed = 4f;

		[SerializeField]
		private float maxDashForce = 67f;

		[SerializeField]
		private float dashSlowdownDistance = 1f;

		[SerializeField]
		private float minDashDistance = 2f;

		[SerializeField]
		private float maxDashDistance = 4f;

		[SerializeField]
		private float dashTimeout = 2.5f;

		private EnemyFacialAnimator facialAnimator;

		private SynchronizedField<Vector3> _attackOrigin;

		private SynchronizedField<int> _retargetPlayerCount;

		private SynchronizedStateMachine behaviorStateMachine;

		private SynchronizedTimer behaviorTimer;

		private Vector3 AttackOrigin
		{
			get
			{
				return _attackOrigin.Get();
			}
			set
			{
				_attackOrigin.Set(value);
			}
		}

		private int RetargetPlayerCount
		{
			get
			{
				return _retargetPlayerCount.Get();
			}
			set
			{
				_retargetPlayerCount.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			facialAnimator = GetComponentInChildren<EnemyFacialAnimator>();
			cachesLatestVisibleTargetPosition = true;
			_attackOrigin = new SynchronizedField<Vector3>(this, "AO", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_retargetPlayerCount = new SynchronizedField<int>(this, "RC", 0, SetterPermissionMode.AUTHORITY);
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
			behaviorTimer = new SynchronizedTimer(this, "B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine = new SynchronizedStateMachine("B", SetterPermissionMode.AUTHORITY);
			behaviorStateMachine.AddState(ushort.MaxValue, null, null, null);
			behaviorStateMachine.AddState(0, OnEnterFindTargetState, OnExitFindTargetState, OnUpdateFindTargetState);
			behaviorStateMachine.AddState(1, OnEnterChargeAttackState, OnExitChargeAttackState, OnUpdateChargeAttackState);
			behaviorStateMachine.AddState(2, OnEnterAttackTargetState, null, OnUpdateAttackTargetState);
			behaviorStateMachine.AddState(3, OnEnterDashState, OnExitDashState, OnUpdateDashState);
		}

		protected override void Start()
		{
			base.Start();
			behaviorStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				behaviorStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			behaviorStateMachine.Update();
			behaviorTimer.UpdateCallbacks();
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			Combatant result = Combatant.Invalid;
			if (LastAttackerIsValidTarget())
			{
				result = base.LastAttacker;
			}
			else if (attacksSameTargetUntilDead && CurrentTargetIsValidTarget() && RetargetPlayerCount < maxRetargetPlayerCount)
			{
				result = base.Target;
			}
			else
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out var distanceToClosestTargetSqr);
				if (distanceToClosestTargetSqr <= engageRadius * engageRadius)
				{
					result = ((!trackTargetCount) ? FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: true) : FindLeastTargetedNearbyTarget(isPatrolling, mustHaveLineOfSight: true));
				}
			}
			return result;
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopLooking();
			base.Steering.MaxHorizontalSpeed = movementSpeed;
		}

		private void OnUpdateFindTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant combatant = FindTarget();
			if (combatant.IsValid)
			{
				if (combatant != base.Target)
				{
					RetargetPlayerCount = 0;
				}
				else
				{
					RetargetPlayerCount++;
				}
				base.Target = combatant;
				base.LastAttacker = Combatant.Invalid;
				behaviorStateMachine.EnterState(1);
			}
			else
			{
				UpdateTargetCentroidPath(movementSlowdownDistance);
			}
		}

		private void OnExitFindTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			if (base.hasAuthority)
			{
				AttackOrigin = base.Steering.HoverPosition;
			}
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.CHARGE;
			if (base.hasAuthority)
			{
				behaviorTimer.StartTimer(attackChargeDuration);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (behaviorTimer.TimerOver)
			{
				if (SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
				{
					behaviorStateMachine.EnterState(2);
				}
				else
				{
					behaviorStateMachine.EnterState(3);
				}
			}
			else
			{
				base.Steering.Look(GetLookAtVector(latestVisibleTargetHeadPosition, !base.Steering.IsHovering), 5f);
			}
		}

		private void OnExitChargeAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			enemyAnimator.RangedCombat = EnemyAnimator.RangedCombatState.NONE;
		}

		private void OnEnterAttackTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAudio.OnAttack();
			if (base.hasAuthority)
			{
				AuthorityFireRangedWeaponAtTarget(canFireAtLastVisiblePosition: true);
				behaviorTimer.StartTimer(attackDuration);
			}
		}

		private void OnUpdateAttackTargetState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver)
				{
					behaviorStateMachine.EnterState(3);
				}
				else if (behaviorTimer.TimeElapsed > rangedWeapon.TotalShotDuration && LastAttackerIsValidTarget() && base.LastAttacker != base.Target)
				{
					behaviorStateMachine.EnterState(0);
				}
				else
				{
					base.Steering.Look(GetLookAtVector(latestVisibleTargetHeadPosition, !base.Steering.IsHovering), 5f);
				}
			}
		}

		private void OnEnterDashState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = dashSpeed;
			base.Steering.MaxHorizontalSteeringForce = maxDashForce;
			base.Steering.MaxVerticalSpeed = dashSpeed;
			base.Steering.MaxVerticalSteeringForce = maxDashForce;
			if (base.hasAuthority)
			{
				base.Steering.Path(GetFleePosition(), dashSlowdownDistance, 0.025f * dashSpeed, faceVelocity: false);
				behaviorTimer.StartTimer(dashTimeout);
			}
		}

		private void OnUpdateDashState()
		{
			if (base.hasAuthority)
			{
				if (behaviorTimer.TimerOver || !base.Steering.PathIsValid() || base.Steering.ReachedPathDestination)
				{
					behaviorStateMachine.EnterState(0);
				}
				else if (SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target) && base.Steering.IsHovering)
				{
					base.Steering.Look(GetLookAtTargetVector(!base.Steering.IsHovering), 5f);
				}
			}
		}

		private void OnExitDashState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopPathing();
		}

		private Vector3 GetFleePosition()
		{
			Vector3 zero = Vector3.zero;
			Vector3 vector = Vector3.ProjectOnPlane(AttackOrigin - base.transform.position, Vector3.up);
			float magnitude = vector.magnitude;
			zero = ((!(magnitude >= maxDashDistance)) ? UnityEngine.Random.onUnitSphere : (vector / magnitude));
			float num = UnityEngine.Random.Range(minDashDistance, maxDashDistance);
			Enemy.TrySampleNavMesh(base.RigidbodyEx.physicsPosition + zero * num, out var closestNavMeshPostion);
			return closestNavMeshPostion;
		}

		protected override void OnStunStart(bool interruptsCustomBehaviour)
		{
			base.OnStunStart(interruptsCustomBehaviour);
			if (interruptsCustomBehaviour && base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = true;
			}
		}

		protected override void OnStunEnd(bool interruptsCustomBehaviour)
		{
			base.OnStunEnd(interruptsCustomBehaviour);
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = false;
			}
		}

		protected override void OnTookDamage(Combatant attacker, WeaponDamageType damageType, EnemyArmorType armorType, int damage, bool killingBlow, Vector3 hitPoint, Vector3 hitNormal)
		{
			base.OnTookDamage(attacker, damageType, armorType, damage, killingBlow, hitPoint, hitNormal);
			if (facialAnimator != null)
			{
				facialAnimator.OnHit();
			}
		}

		public override void AuthorityOnDamageApplyForce(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 force, Vector3 point)
		{
			force = Vector3.ProjectOnPlane(force, Vector3.up);
			base.AuthorityOnDamageApplyForce(damageType, armorType, force, point);
		}

		protected override void OnDeath()
		{
			base.OnDeath();
			if (base.Steering.IsHovering)
			{
				base.RigidbodyEx.useGravity = true;
			}
		}
	}
	public class ExplosiveTrap : Trap
	{
		private enum LifeStates
		{
			DISARMED = 0,
			ARMED = 1,
			DETONATED = 2,
			INVALID = 65535
		}

		[AutofillOptional(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		private BlinkingRenderer blinkingRenderer;

		[Header("Arming")]
		[SerializeField]
		private bool canBeProximityArmed;

		[SerializeField]
		private float proximityArmRadius = 2f;

		[SerializeField]
		private float armedDuration = 1.5f;

		[Header("Armed Feedback")]
		[SerializeField]
		private float armedWarningFrequency = 4f;

		[SerializeField]
		private RecRoomAudioClip armedWarningBeepAudio;

		[Header("Detonation")]
		[SerializeField]
		private float explosionRadius = 3f;

		[SerializeField]
		private float explosiveForce = 30f;

		[Header("Feedback")]
		[SerializeField]
		private PooledParticle explosionParticlePrefab;

		[SerializeField]
		private RecRoomAudioClip explosionAudio;

		[SerializeField]
		private Renderer[] renderers;

		private static PhotonPlayer[] damagingPlayers = new PhotonPlayer[1];

		private SynchronizedTimer stateTimer;

		private SynchronizedStateMachine stateMachine;

		private bool initialized;

		private PointsDropper pointsDropper;

		private Explosive explosive = new Explosive();

		private Coroutine armedWarningAudioCoroutine;

		private bool CollisionEnabled
		{
			set
			{
				rigidbodyEx.SetKinematic(this, !value);
				rigidbodyEx.useGravity = value;
				TrapCollider[] array = colliders;
				foreach (TrapCollider trapCollider in array)
				{
					trapCollider.enabled = value;
				}
			}
		}

		private bool VisualsEnabled
		{
			set
			{
				Renderer[] array = renderers;
				foreach (Renderer renderer in array)
				{
					renderer.enabled = value;
				}
			}
		}

		protected override void Awake()
		{
			base.Awake();
			explosive.PlayerImpactEvent += OnPlayerImpact;
			explosive.EnemyImpactEvent += OnEnemyImpact;
			explosive.TrapImpactEvent += OnTrapImpact;
			explosive.ToolImpactEvent += OnToolImpact;
			pointsDropper = GetComponent<PointsDropper>();
			stateTimer = new SynchronizedTimer(this, "ST", SetterPermissionMode.AUTHORITY);
			stateMachine = new SynchronizedStateMachine("LIFE", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(ushort.MaxValue, null, null, null);
			stateMachine.AddState(0, null, null, OnUpdateDisarmedState);
			stateMachine.AddState(1, OnEnterArmedState, OnExitArmedState, OnUpdateArmedState);
			stateMachine.AddState(2, OnEnterDetonatedState, OnExitDetonatedState, null);
		}

		protected override void Start()
		{
			base.Start();
			stateMachine.Start(this, 0);
			initialized = true;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			explosive.PlayerImpactEvent -= OnPlayerImpact;
			explosive.EnemyImpactEvent -= OnEnemyImpact;
			explosive.TrapImpactEvent -= OnTrapImpact;
			explosive.ToolImpactEvent -= OnToolImpact;
		}

		protected override void OnIsEnabledChange()
		{
			base.OnIsEnabledChange();
			if (base.hasAuthority && initialized)
			{
				if (base.IsEnabled)
				{
					stateMachine.EnterState(0);
				}
				else
				{
					stateMachine.EnterState(ushort.MaxValue);
				}
			}
		}

		private void Update()
		{
			stateMachine.Update();
			stateTimer.UpdateCallbacks();
		}

		private void OnUpdateDisarmedState()
		{
			if (canBeProximityArmed && !(Player.LocalPlayer == null) && (Player.LocalPlayer.Head.transform.position - base.transform.position).sqrMagnitude <= proximityArmRadius * proximityArmRadius)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterArmedState(ushort previousStateId, ushort previousSubStateId)
		{
			StartArmedFeedback();
			if (base.hasAuthority)
			{
				stateTimer.StartTimer(armedDuration);
			}
		}

		private void OnUpdateArmedState()
		{
			if (base.hasAuthority && stateTimer.TimerOver)
			{
				stateMachine.EnterState(2);
			}
		}

		private void OnExitArmedState(ushort nextStateId, ushort nextSubStateId)
		{
			StopArmedFeedback();
		}

		private void OnEnterDetonatedState(ushort previousStateId, ushort previousSubStateId)
		{
			VisualsEnabled = false;
			CollisionEnabled = false;
			Explode();
		}

		private void OnExitDetonatedState(ushort nextStateId, ushort nextSubStateId)
		{
			VisualsEnabled = true;
			CollisionEnabled = true;
		}

		public override void AuthorityApplyDamage(WeaponDamageType damageType, int damage, Vector3 point, Vector3 normal)
		{
			base.AuthorityApplyDamage(damageType, damage, point, normal);
			if (base.hasAuthority)
			{
				stateMachine.EnterState(2);
			}
		}

		private void OnPlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			PlayerHit(hitPlayer, Player.BodyPart.Torso, impact);
		}

		private void OnEnemyImpact(Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			EnemyHit(hitEnemy, EnemyArmorType.NORMAL, WeaponDamageType.EXPLOSIVE, impact);
		}

		private void OnTrapImpact(Trap hitTrap, WeaponImpact impact)
		{
			TrapHit(hitTrap, WeaponDamageType.EXPLOSIVE, impact);
		}

		private void OnToolImpact(Tool hitTool, WeaponImpact impact)
		{
			ToolHit(hitTool, impact);
		}

		private void Explode()
		{
			if (pointsDropper != null && base.authority != null)
			{
				damagingPlayers[0] = base.authority;
				pointsDropper.DropPoints(damagingPlayers, base.transform.position);
			}
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(explosionParticlePrefab);
			if (pooledParticle != null)
			{
				pooledParticle.Play(base.transform.position, Quaternion.LookRotation(Vector3.up));
			}
			AudioManager.Play2DSFX(explosionAudio);
			AuthorityRunCollision();
		}

		private void AuthorityRunCollision()
		{
			if (base.hasAuthority)
			{
				explosive.Explode(base.transform.position, explosionRadius, explosiveForce);
			}
		}

		private void StartArmedFeedback()
		{
			StopArmedFeedback();
			if (blinkingRenderer != null)
			{
				blinkingRenderer.StartBlinking(armedWarningFrequency);
			}
			armedWarningAudioCoroutine = StartCoroutine(ArmedWarningAudioCoroutine(armedWarningFrequency));
		}

		private void StopArmedFeedback()
		{
			if (blinkingRenderer != null)
			{
				blinkingRenderer.StopBlinking();
			}
			if (armedWarningAudioCoroutine != null)
			{
				StopCoroutine(armedWarningAudioCoroutine);
				armedWarningAudioCoroutine = null;
			}
		}

		private IEnumerator ArmedWarningAudioCoroutine(float frequency)
		{
			if (armedWarningBeepAudio == null || armedWarningBeepAudio.audioClip == null)
			{
				armedWarningAudioCoroutine = null;
				yield break;
			}
			float period = 1f / frequency;
			float timer = 0f;
			while (true)
			{
				AudioManager.Play3DSFX(armedWarningBeepAudio, base.transform);
				for (timer = 0f; timer < period; timer += UnityEngine.Time.deltaTime)
				{
					yield return null;
				}
			}
		}

		private void OnDrawGizmos()
		{
			if (canBeProximityArmed)
			{
				Gizmos.color = Color.yellow;
				Gizmos.DrawWireSphere(base.transform.position, proximityArmRadius);
			}
		}
	}
}
[RequireComponent(typeof(PhotonView))]
[RequireComponent(typeof(Steering))]
public class LaserTrap : Trap
{
	private enum PathingMode
	{
		PING_PONG,
		PING_PONG_STOP_AT_EACH_NODE,
		LOOP,
		LOOP_STOP_AT_EACH_NODE
	}

	private enum LaserRotationMode
	{
		PARALLEL,
		PERPENDICULAR
	}

	[Header("Laser")]
	[SerializeField]
	private Transform[] lasers;

	[SerializeField]
	private float maxLaserLength = 10f;

	[SerializeField]
	private float rotationSpeed = 30f;

	[SerializeField]
	private float slowdownAngle = 5f;

	[Header("Path")]
	[SerializeField]
	private Transform[] targetPath;

	[SerializeField]
	private int initialNodeIndex;

	[SerializeField]
	private PathingMode pathingMode;

	[SerializeField]
	private LaserRotationMode laserRotationMode;

	[Header("Feedback")]
	[SerializeField]
	private PooledParticle impactParticlePrefab;

	private static RaycastHit[] RAYCAST_HITS = new RaycastHit[8];

	private SynchronizedField<int, int> _pathNodeIndices;

	private Steering steering;

	private Quaternion targetLookRotation = Quaternion.identity;

	private RaycastHitComparer raycastHitComparer = new RaycastHitComparer();

	private PooledParticle[] impactParticles;

	private static Vector3 gizmoCubeSize = Vector3.one * 0.1f;

	private int CurrentPathNodeIndex => _pathNodeIndices.Get1();

	private int PreviousPathNodeIndex => _pathNodeIndices.Get2();

	private int DefaultNodeIndex => (initialNodeIndex >= 0 && initialNodeIndex < targetPath.Length) ? initialNodeIndex : 0;

	protected override void Awake()
	{
		base.Awake();
		steering = GetComponent<Steering>();
		_pathNodeIndices = new SynchronizedField<int, int>(this, "CURRENT_INDEX", 0, DefaultNodeIndex, SetterPermissionMode.MASTER, OnPathNodeIndexChange);
	}

	protected override void Start()
	{
		base.Start();
		OnPathNodeIndexChange();
		if (base.hasAuthority)
		{
			AuthorityUpdateSteering();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		CleanupParticles();
		impactParticles = null;
	}

	private void Update()
	{
		for (int i = 0; i < lasers.Length; i++)
		{
			UpdateLaser(i);
		}
		if (base.hasAuthority)
		{
			if (steering.ReachedLookTarget)
			{
				AuthorityUpdatePathIndex();
			}
			AuthorityUpdateSteering();
		}
	}

	protected override void OnIsEnabledChange()
	{
		base.OnIsEnabledChange();
		if (base.IsEnabled)
		{
			if (base.hasAuthority)
			{
				_pathNodeIndices.Set(DefaultNodeIndex, DefaultNodeIndex);
				base.transform.rotation = targetLookRotation;
			}
			InitializeParticles();
		}
		else
		{
			CleanupParticles();
		}
	}

	private void UpdateLaser(int laserIndex)
	{
		if (laserIndex < 0 || laserIndex >= lasers.Length)
		{
			return;
		}
		Transform transform = lasers[laserIndex];
		Vector3 origin = transform.position + transform.forward * 0.02f;
		int num = Physics.RaycastNonAlloc(origin, transform.forward, RAYCAST_HITS, maxLaserLength, 362036736, QueryTriggerInteraction.Ignore);
		if (num > 0)
		{
			Array.Sort(RAYCAST_HITS, 0, num, raycastHitComparer);
		}
		Vector3 position = transform.position;
		float distance = maxLaserLength;
		for (int i = 0; i < num; i++)
		{
			if (OnRaycastCollision(RAYCAST_HITS[i]))
			{
				position = RAYCAST_HITS[i].point;
				distance = RAYCAST_HITS[i].distance;
				break;
			}
		}
		Vector3 localScale = transform.localScale;
		localScale.z = distance;
		transform.localScale = localScale;
		if (impactParticles != null && laserIndex < impactParticles.Length)
		{
			PooledParticle pooledParticle = impactParticles[laserIndex];
			if (pooledParticle != null)
			{
				pooledParticle.transform.position = position;
				pooledParticle.transform.rotation = Quaternion.LookRotation(-transform.forward);
			}
		}
	}

	private bool OnRaycastCollision(RaycastHit hit)
	{
		if (hit.distance < Mathf.Epsilon)
		{
			return false;
		}
		bool result = true;
		Player player = null;
		if ((player = hit.collider.GetColliderPlayer(out var bodyPart)) != null)
		{
			WeaponImpact impact = new WeaponImpact
			{
				Velocity = Vector3.zero,
				Force = Vector3.zero,
				GameObject = ((!(hit.rigidbody != null)) ? hit.collider.gameObject : hit.rigidbody.gameObject),
				Point = hit.point,
				Distance = 0f,
				SurfaceNormal = hit.normal,
				PreAttackChargeAmount = 1f
			};
			PlayerHit(player, bodyPart, impact);
			result = false;
		}
		return result;
	}

	private void OnPathNodeIndexChange()
	{
		steering.MaxAngularSpeed = rotationSpeed;
		if (targetPath.Length >= 2 && CurrentPathNodeIndex >= 0 && CurrentPathNodeIndex < targetPath.Length)
		{
			Vector3 up = Vector3.up;
			int num = targetPath.Length - 1;
			if (num == 1)
			{
				up = GetPathSegmentNormal(0);
			}
			else if (CurrentPathNodeIndex == 0 || CurrentPathNodeIndex == targetPath.Length - 1)
			{
				up = Vector3.up;
			}
			else
			{
				int segmentIndex = CurrentPathNodeIndex - 1;
				int currentPathNodeIndex = CurrentPathNodeIndex;
				up = (GetPathSegmentNormal(segmentIndex) + GetPathSegmentNormal(currentPathNodeIndex)).normalized;
			}
			Vector3 normalized = (targetPath[CurrentPathNodeIndex].position - base.transform.position).normalized;
			targetLookRotation = Quaternion.LookRotation(normalized, up);
			if (laserRotationMode == LaserRotationMode.PARALLEL)
			{
				targetLookRotation *= Quaternion.Euler(0f, 0f, 90f);
			}
		}
	}

	private Vector3 GetPathSegmentNormal(int segmentIndex)
	{
		int num = segmentIndex + 1;
		Vector3 normalized = (targetPath[segmentIndex].position - base.transform.position).normalized;
		Vector3 normalized2 = (targetPath[num].position - base.transform.position).normalized;
		return Vector3.Cross(normalized, normalized2).normalized;
	}

	private void AuthorityUpdateSteering()
	{
		float num = slowdownAngle;
		if (pathingMode == PathingMode.LOOP || (pathingMode == PathingMode.PING_PONG && CurrentPathNodeIndex > 0 && CurrentPathNodeIndex < targetPath.Length - 1))
		{
			num = 0f;
		}
		steering.Look(targetLookRotation, num, 0.1f);
	}

	private void AuthorityUpdatePathIndex()
	{
		int nextPathIndex = GetNextPathIndex(CurrentPathNodeIndex, PreviousPathNodeIndex);
		if (nextPathIndex != CurrentPathNodeIndex)
		{
			_pathNodeIndices.Set(nextPathIndex, CurrentPathNodeIndex);
		}
	}

	private int GetNextPathIndex(int currentIndex, int previousIndex)
	{
		int result = currentIndex;
		switch (pathingMode)
		{
		case PathingMode.LOOP:
		case PathingMode.LOOP_STOP_AT_EACH_NODE:
			result = GetNextLoopIndex(currentIndex);
			break;
		case PathingMode.PING_PONG:
		case PathingMode.PING_PONG_STOP_AT_EACH_NODE:
			result = GetNextPingPongIndex(currentIndex, previousIndex);
			break;
		}
		return result;
	}

	private int GetNextLoopIndex(int currentIndex)
	{
		return (currentIndex + 1) % targetPath.Length;
	}

	private int GetNextPingPongIndex(int currentIndex, int previousIndex)
	{
		if (targetPath.Length < 2)
		{
			return currentIndex;
		}
		int num = currentIndex;
		if (currentIndex == 0)
		{
			return 1;
		}
		if (currentIndex == targetPath.Length - 1)
		{
			return targetPath.Length - 2;
		}
		int num2 = currentIndex - previousIndex;
		if (num2 == 0)
		{
			num2 = 1;
		}
		float num3 = Mathf.Sign(num2);
		return currentIndex + (int)num3;
	}

	private void InitializeParticles()
	{
		CleanupParticles();
		if (impactParticles == null)
		{
			impactParticles = new PooledParticle[lasers.Length];
		}
		for (int i = 0; i < impactParticles.Length; i++)
		{
			impactParticles[i] = ObjectPool.Instance.Acquire(impactParticlePrefab);
			if (impactParticles[i] != null)
			{
				impactParticles[i].Play(loop: true);
			}
		}
	}

	private void CleanupParticles()
	{
		if (impactParticles == null)
		{
			return;
		}
		for (int i = 0; i < impactParticles.Length; i++)
		{
			if (impactParticles[i] != null)
			{
				impactParticles[i].Stop();
				impactParticles[i] = null;
			}
		}
	}

	private void OnDrawGizmos()
	{
		if (targetPath == null || targetPath.Length <= 0)
		{
			return;
		}
		for (int i = 0; i < targetPath.Length; i++)
		{
			Gizmos.color = Color.white;
			Gizmos.DrawLine(base.transform.position, targetPath[i].position);
			Gizmos.color = Color.green;
			Gizmos.DrawWireCube(targetPath[i].position, gizmoCubeSize);
			if (i < targetPath.Length - 1)
			{
				Gizmos.DrawLine(targetPath[i].position, targetPath[i + 1].position);
			}
		}
	}
}
[RequireComponent(typeof(PhotonView))]
[RequireComponent(typeof(PointsDropper))]
public class PointsDropTrap : Trap
{
	[Header("Loot Trap")]
	[SerializeField]
	private int defaultHealth = 1;

	[SerializeField]
	private Transform lootSpawn;

	[Header("Damage Feedback")]
	[SerializeField]
	private Material fullHealthMaterial;

	[SerializeField]
	private Material damagedMaterial;

	[Header("DeathFeedback")]
	[SerializeField]
	private RecRoomAudioClip onDeathAudio;

	[SerializeField]
	private PooledParticle onDeathParticles;

	private SynchronizedField<int> _health;

	private Renderer[] renderers;

	private PointsDropper lootDropper;

	private List<PhotonPlayer> damagingPlayers = new List<PhotonPlayer>();

	private int Health
	{
		get
		{
			return _health.Get();
		}
		set
		{
			_health.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		renderers = GetComponentsInChildren<Renderer>();
		lootDropper = GetComponent<PointsDropper>();
		_health = new SynchronizedField<int>(this, "HEALTH", defaultHealth, SetterPermissionMode.AUTHORITY, OnHealthChange);
	}

	protected override void Start()
	{
		base.Start();
		OnHealthChange();
	}

	protected override void OnIsEnabledChange()
	{
		base.OnIsEnabledChange();
		if (base.IsEnabled)
		{
			damagingPlayers.Clear();
			if (base.hasAuthority)
			{
				Health = defaultHealth;
			}
		}
	}

	public override void MasterResetToSpawnPoint()
	{
		base.MasterResetToSpawnPoint();
		if (PhotonNetwork.isMasterClient)
		{
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			Health = defaultHealth;
		}
	}

	private void OnHealthChange()
	{
		if (renderers != null)
		{
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				renderer.material = ((Health != defaultHealth) ? damagedMaterial : fullHealthMaterial);
			}
		}
	}

	public override void AuthorityApplyDamage(WeaponDamageType damageType, int damage, Vector3 point, Vector3 normal)
	{
		base.AuthorityApplyDamage(damageType, damage, point, normal);
		if (base.hasAuthority && Health > 0)
		{
			Health -= damage;
			bool arg = Health <= 0;
			base.photonView.RpcAll(RpcOnDamage, base.authority, arg, point, normal);
		}
	}

	[PunRPC]
	protected void RpcOnDamage(PhotonPlayer attacker, bool killingBlow, Vector3 point, Vector3 normal)
	{
		damagingPlayers.Add(attacker);
		if (!killingBlow)
		{
			return;
		}
		if (lootDropper != null && damagingPlayers.Count > 0)
		{
			lootDropper.DropPoints(damagingPlayers.ToArray(), lootSpawn.position);
		}
		if (onDeathParticles != null)
		{
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(onDeathParticles);
			if (pooledParticle != null)
			{
				pooledParticle.Play(point, Quaternion.LookRotation(normal, Vector3.up));
			}
		}
		if (onDeathAudio != null && onDeathAudio.audioClip != null)
		{
			AudioManager.Play3DSFX(onDeathAudio, point);
		}
	}
}
public class WeaponFlashlight : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Light light;

	[SerializeField]
	private GameObject lightShaftMeshes;

	private Tool thisTool;

	private LightRenderMode defaultRenderMode;

	public Light Light => light;

	public GameObject LightShaftMeshes => lightShaftMeshes;

	private void Start()
	{
		if (light != null)
		{
			defaultRenderMode = light.renderMode;
			thisTool = GetComponentInParent<Tool>();
			if (thisTool != null)
			{
				thisTool.PostPickupEvent += OnPickup;
				thisTool.PostReleaseEvent += OnRelease;
			}
		}
	}

	private void OnDestroy()
	{
		if (thisTool != null)
		{
			thisTool.PostPickupEvent -= OnPickup;
			thisTool.PostReleaseEvent -= OnRelease;
		}
	}

	private void OnPickup(Tool tool)
	{
		if (tool.HolderView.isLocal)
		{
			light.renderMode = LightRenderMode.ForcePixel;
		}
	}

	private void OnRelease(Tool tool)
	{
