}
public class WeaponFlashlightController : UnityEngine.MonoBehaviour
{
	private enum VisibleState
	{
		VISIBLE,
		MESHES_VISIBLE,
		HIDDEN
	}

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Weapon weapon;

	[SerializeField]
	private WeaponFlashlight flashlightPrefab;

	[SerializeField]
	private Transform flashlightRoot;

	private WeaponFlashlight flashlight;

	public bool FlashlightAllowed => RecNet.Rooms.LocalRoomScene.Location == RoomSceneLocations.THE_RISE_OF_JUMBOTRON && !GameSessions.LocalGameSession.IsSandbox;

	private void Start()
	{
		if (weapon == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a weapon reference.");
			return;
		}
		weapon.Tool.PostPickupEvent += OnPostPickup;
		weapon.Tool.PostReleaseEvent += OnPostRelease;
		weapon.Tool.VisibilityChangeEvent += OnWeaponVisibilityChange;
		OnWeaponVisibilityChange(weapon.Tool.IsVisible, isRemoteVisible: false);
	}

	private void OnDestroy()
	{
		if (weapon != null)
		{
			weapon.Tool.PostPickupEvent -= OnPostPickup;
			weapon.Tool.PostReleaseEvent -= OnPostRelease;
			weapon.Tool.VisibilityChangeEvent -= OnWeaponVisibilityChange;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		SetVisibility(VisibleState.VISIBLE);
	}

	private void OnPostRelease(Tool tool)
	{
		SetVisibility(VisibleState.MESHES_VISIBLE);
	}

	private void OnWeaponVisibilityChange(bool visible, bool isRemoteVisible)
	{
		if (weapon != null)
		{
			if (weapon.Tool.IsHeld)
			{
				SetVisibility((!weapon.Tool.IsVisible) ? VisibleState.HIDDEN : VisibleState.VISIBLE);
			}
			else
			{
				SetVisibility(weapon.Tool.IsVisible ? VisibleState.MESHES_VISIBLE : VisibleState.HIDDEN);
			}
		}
		else
		{
			SetVisibility(VisibleState.MESHES_VISIBLE);
		}
	}

	private void SetVisibility(VisibleState visibleState)
	{
		if (!FlashlightAllowed)
		{
			visibleState = VisibleState.HIDDEN;
		}
		if (flashlight == null && visibleState != VisibleState.HIDDEN)
		{
			flashlight = UnityEngine.Object.Instantiate(flashlightPrefab, flashlightRoot);
		}
		if (flashlight != null)
		{
			flashlight.Light.enabled = visibleState == VisibleState.VISIBLE;
			flashlight.LightShaftMeshes.gameObject.SetActive(visibleState != VisibleState.HIDDEN);
		}
	}
}
public class BreakableObject : Photon.MonoBehaviour, IPersistable, ICustomImposterBehavior
{
	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private MeleeWeapon thisWeapon;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private ToolPlayerAttractor attractor;

	[Header("Meshes")]
	[SerializeField]
	private GameObject wholeObject;

	[SerializeField]
	private GameObject fracturedObject;

	[Header("Destruction")]
	[SerializeField]
	private bool shatterOnAnyImpact;

	[SerializeField]
	private float shatterSpeed = 2f;

	[SerializeField]
	private float brokenLifetime = 5f;

	[Header("Feedback")]
	[SerializeField]
	private PooledParticle smashParticlePrefab;

	[SerializeField]
	private RecRoomAudioClip[] smashSounds;

	private SynchronizedField<int> _health;

	private SynchronizedField<bool> _sandboxBreakable;

	private TokenFlag unbreakableFlag = new TokenFlag();

	private RagdollPiece[] pieces;

	private bool isShattered;

	private bool destroyAfterShatter;

	private Coroutine delayedDisableCoroutine;

	private WeaponImpact lastImpact = WeaponImpact.Default;

	bool IPersistable.BlockObjectPersistance => false;

	public int Health
	{
		get
		{
			return _health.Get();
		}
		set
		{
			_health.Set(Mathf.Clamp(value, 0, 1));
		}
	}

	public Tool Tool { get; private set; }

	public bool CanShatter => !unbreakableFlag.HasTokens;

	protected override void Awake()
	{
		base.Awake();
		Tool = GetComponent<Tool>();
		if (Tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing Tool component.");
		}
		else
		{
			Tool.AttackAppliedEvent += OnAttackApplied;
			Tool.AuthorityForceAppliedEvent += OnAuthorityForceApplied;
			Tool.AuthorityVelocityChangeEvent += OnAuthorityChangeVelocity;
			Tool.PostPickupEvent += OnToolPostPickup;
			Tool.PostResetEvent += OnToolReset;
			Tool.AddCustomScreensValidPointOfInterestCondition(CustomScreensValidPointOfInterestCondition);
		}
		_health = new SynchronizedField<int>(this, "HP", 1, SetterPermissionMode.AUTHORITY, OnHealthChange);
		_sandboxBreakable = new SynchronizedField<bool>(this, "SB", defaultValue: true, SetterPermissionMode.ANYONE, OnSandboxBreakableChanged);
		if (fracturedObject != null)
		{
			pieces = fracturedObject.GetComponentsInChildren<RagdollPiece>(includeInactive: true);
			fracturedObject.SetActive(value: false);
		}
		if (thisWeapon != null)
		{
			thisWeapon.EnemyAppliedAttackEvent += OnEnemyAppliedAttack;
			thisWeapon.DealtPlayerOnPlayerDamageEvent += OnWeaponDealtPlayerOnPlayerDamage;
			thisWeapon.EnemyImpactEvent += OnWeaponEnemyImpact;
			thisWeapon.PlayerImpactEvent += OnWeaponPlayerImpact;
			thisWeapon.PlayerToolImpactEvent += OnWeaponPlayerToolImpact;
			thisWeapon.OtherImpactEvent += OnWeaponOtherImpact;
		}
		isShattered = false;
	}

	private void Start()
	{
		Tool.SupportsAnimateOut = false;
		if (Tool.CreationObject != null)
		{
			CheckIfDestroyAfterShatter();
			CreationObject creationObject = Tool.CreationObject;
			BoolSettingEditEvent settingEvent = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUiFlow) => editableUiFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, "Is Breakable");
				instance.PropertyGetter = CreationObjectSetting_GetSandboxBreakable;
				instance.PropertySetter = CreationObjectSetting_SetSandboxBreakable;
			});
			creationObject.AddConfigurableSetting(settingEvent);
		}
		if (wholeObject != null)
		{
			wholeObject.SetActive(value: true);
		}
		if (fracturedObject != null)
		{
			fracturedObject.SetActive(value: false);
		}
		OnHealthChange();
		OnSandboxBreakableChanged();
	}

	private void OnDisable()
	{
		ResetShatter();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.AttackAppliedEvent -= OnAttackApplied;
			Tool.AuthorityForceAppliedEvent -= OnAuthorityForceApplied;
			Tool.AuthorityVelocityChangeEvent -= OnAuthorityChangeVelocity;
			Tool.PostPickupEvent -= OnToolPostPickup;
			Tool.PostResetEvent -= OnToolReset;
			Tool.RemoveCustomScreensValidPointOfInterestCondition(CustomScreensValidPointOfInterestCondition);
		}
		if (thisWeapon != null)
		{
			thisWeapon.EnemyAppliedAttackEvent -= OnEnemyAppliedAttack;
			thisWeapon.DealtPlayerOnPlayerDamageEvent -= OnWeaponDealtPlayerOnPlayerDamage;
			thisWeapon.EnemyImpactEvent -= OnWeaponEnemyImpact;
			thisWeapon.PlayerImpactEvent -= OnWeaponPlayerImpact;
			thisWeapon.PlayerToolImpactEvent -= OnWeaponPlayerToolImpact;
			thisWeapon.OtherImpactEvent -= OnWeaponOtherImpact;
		}
	}

	protected virtual void OnHealthChange()
	{
		if (Health <= 0 && base.gameObject.activeSelf)
		{
			StartDelayedDisableCoroutine();
		}
	}

	private void OnSandboxBreakableChanged()
	{
		if (Tool.CreationObject != null)
		{
			SetBreakable(_sandboxBreakable.Get(), Tool.CreationObject);
		}
	}

	private void StartDelayedDisableCoroutine()
	{
		StopDelayedDisableCoroutine();
		delayedDisableCoroutine = StartCoroutine(RunDelayedDisableCoroutine());
	}

	private void StopDelayedDisableCoroutine()
	{
		if (delayedDisableCoroutine != null)
		{
			StopCoroutine(delayedDisableCoroutine);
			delayedDisableCoroutine = null;
		}
	}

	private IEnumerator RunDelayedDisableCoroutine()
	{
		for (float timer = 0f; timer < brokenLifetime; timer += UnityEngine.Time.deltaTime)
		{
			yield return null;
		}
		if (Tool != null)
		{
			if (Tool.ToolCleanup.OverridesActive)
			{
				Tool.ToolCleanup.AuthorityQueueForceCleanup();
			}
			else if (PhotonNetwork.isMasterClient)
			{
				if (destroyAfterShatter)
				{
					PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
				}
				else
				{
					Tool.MasterDisableAndMoveToLastSpawnPosition();
				}
			}
		}
		delayedDisableCoroutine = null;
	}

	private void OnToolPostPickup(Tool tool)
	{
		if (isShattered && Tool.IsHeld && Tool.Owner.isLocal)
		{
			Tool.HolderInfo = ToolHolderInfo.NotHeld;
		}
	}

	private bool CustomScreensValidPointOfInterestCondition(Tool thisTool)
	{
		return !isShattered;
	}

	public void SetBreakable(bool isBreakable, object flag)
	{
		if (isBreakable)
		{
			unbreakableFlag.Remove(flag);
		}
		else
		{
			unbreakableFlag.Add(flag);
		}
	}

	private bool CreationObjectSetting_GetSandboxBreakable()
	{
		return _sandboxBreakable.Get();
	}

	private void CreationObjectSetting_SetSandboxBreakable(bool isBreakable)
	{
		if (Tool.CreationObject != null)
		{
			_sandboxBreakable.Set(isBreakable);
		}
	}

	private void OnWeaponEnemyImpact(Weapon weapon, Enemy defender, WeaponImpact impact, bool hadDamageAuthority)
	{
		ShatterOnImpact(impact, hadDamageAuthority);
	}

	private void OnWeaponPlayerImpact(Weapon weapon, Player player, Player.BodyPart bodyPart, WeaponImpact impact, bool hadDamageAuthority)
	{
		bool flag = false;
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
		{
			flag = !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(player.PhotonPlayer) || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsInvincible(player.PhotonPlayer);
		}
		ShatterOnImpact(impact, hadDamageAuthority || flag);
	}

	private void OnWeaponPlayerToolImpact(Weapon weapon, Tool hitTool, WeaponImpact impact, bool hadDamageAuthority)
	{
		ShatterOnImpact(impact, hadDamageAuthority);
	}

	private void OnWeaponOtherImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
	{
		if (!Tool.IsHeld)
		{
			ShatterOnImpact(impact, hadDamageAuthority);
		}
	}

	private void OnWeaponDealtPlayerOnPlayerDamage(Player hitPlayer)
	{
		if (base.hasAuthority)
		{
			AuthorityApplyAttackAndShatter(lastImpact);
		}
	}

	private void OnEnemyAppliedAttack(Weapon weapon, WeaponImpact impact, bool dealtDamage)
	{
		if (dealtDamage && thisWeapon != null && weapon == thisWeapon)
		{
			AuthorityApplyAttackAndShatter(impact.Point, impact.Velocity);
		}
	}

	private void ShatterOnImpact(WeaponImpact impact, bool hadDamageAuthority)
	{
		if (base.hasAuthority && (hadDamageAuthority || shatterOnAnyImpact) && thisWeapon != null)
		{
			AuthorityApplyAttackAndShatter(impact);
		}
		lastImpact = impact;
	}

	private void AuthorityApplyAttackAndShatter(WeaponImpact impact)
	{
		Vector3 velocity = Vector3.Reflect(impact.Velocity, impact.SurfaceNormal);
		AuthorityApplyAttackAndShatter(impact.Point, velocity);
	}

	private void AuthorityApplyAttackAndShatter(Vector3 point, Vector3 velocity)
	{
		if (base.hasAuthority)
		{
			OnAttackApplied(Tool, null, WeaponDamageType.DEFAULT, point);
			AuthorityShatter(velocity);
		}
	}

	private void ResetShatter()
	{
		isShattered = false;
		if (pieces != null)
		{
			RagdollPiece[] array = pieces;
			foreach (RagdollPiece ragdollPiece in array)
			{
				ragdollPiece.StopRagdoll();
			}
		}
		StopDelayedDisableCoroutine();
	}

	private void CheckIfDestroyAfterShatter()
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DestroyBrokenEquipment)
		{
			destroyAfterShatter = true;
		}
		else
		{
			destroyAfterShatter = false;
		}
	}

	protected virtual void OnToolReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasEnabled)
	{
		CheckIfDestroyAfterShatter();
		ResetShatter();
		if (base.hasAuthority)
		{
			Health = 1;
		}
		Tool.RigidbodyEx.RemoveKinematic(this);
		Tool.EnablePickup(this);
		if (wholeObject != null)
		{
			wholeObject.SetActive(value: true);
		}
		if (fracturedObject != null)
		{
			fracturedObject.SetActive(value: false);
		}
		if (attractor != null)
		{
			attractor.SuppressAttractor = false;
		}
	}

	protected virtual void OnAttackApplied(Tool thisTool, Weapon weapon, WeaponDamageType damageType, Vector3 point)
	{
		if (base.hasAuthority && Health > 0 && CanShatter)
		{
			Health = 0;
		}
	}

	protected void OnAuthorityForceApplied(Tool thisTool, Vector3 force, Vector3 point)
	{
		AuthorityShatter(force);
	}

	protected void OnAuthorityChangeVelocity(Tool thisTool, Vector3 linearVelocity, Vector3 angularVelocity)
	{
		AuthorityShatter(linearVelocity);
	}

	private void AuthorityShatter(Vector3 velocity)
	{
		if (Health <= 0 && base.hasAuthority && !isShattered && Health <= 0)
		{
			velocity = Vector3.ClampMagnitude(velocity, shatterSpeed);
			base.photonView.RpcAll(RpcShatter, velocity);
		}
	}

	[PunRPC]
	protected void RpcShatter(Vector3 initialVelocity)
	{
		if (Tool.IsHeld && Tool.Owner.isLocal)
		{
			Tool.HolderInfo = ToolHolderInfo.NotHeld;
		}
		isShattered = true;
		Tool.RigidbodyEx.AddKinematic(this);
		Tool.DisablePickup(this);
		if (wholeObject != null)
		{
			wholeObject.SetActive(value: false);
		}
		if (fracturedObject != null)
		{
			fracturedObject.SetActive(value: true);
			if (pieces != null)
			{
				RagdollPiece[] array = pieces;
				foreach (RagdollPiece ragdollPiece in array)
				{
					ragdollPiece.StartRagdoll(initialVelocity, base.transform.position, shatterSpeed);
				}
			}
		}
		if (attractor != null)
		{
			attractor.SuppressAttractor = true;
		}
		if (smashSounds != null)
		{
			AudioManager.PlayRandom3DSFX(smashSounds, base.transform);
		}
		if (smashParticlePrefab != null)
		{
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(smashParticlePrefab);
			if (pooledParticle != null)
			{
				pooledParticle.Play(base.transform.position, base.transform.rotation);
			}
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData.BreakableObjectData == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing BreakableObject {0}: data empty.", base.gameObject);
		}
		else
		{
			_sandboxBreakable.Set(deserializeParams.viewData.BreakableObjectData.IsBreakable);
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.BreakableObjectData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing BreakableObject {0}: Data already specified.", base.gameObject);
		}
		else
		{
			viewData.BreakableObjectData = new BreakableObjectData
			{
				IsBreakable = _sandboxBreakable.Get()
			};
		}
	}

	void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
	{
		UnityEngine.Object.DestroyImmediate(fracturedObject);
	}
}
public class BreakablePointsContainer : BreakableObject
{
	public delegate void BreakablePointContainerAction(BreakablePointsContainer container);

	[Header("Loot and Points")]
	[SerializeField]
	[FormerlySerializedAs("lootDrops")]
	private PointsDropper pointDropper;

	private List<PhotonPlayer> playerHitInstances = new List<PhotonPlayer>();

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private static BreakablePointContainerAction m_BreakEvent;

	public static event BreakablePointContainerAction BreakEvent
	{
		add
		{
			BreakablePointContainerAction breakablePointContainerAction = BreakablePointsContainer.m_BreakEvent;
			BreakablePointContainerAction breakablePointContainerAction2;
			do
			{
				breakablePointContainerAction2 = breakablePointContainerAction;
				breakablePointContainerAction = Interlocked.CompareExchange(ref BreakablePointsContainer.m_BreakEvent, (BreakablePointContainerAction)Delegate.Combine(breakablePointContainerAction2, value), breakablePointContainerAction);
			}
			while (breakablePointContainerAction != breakablePointContainerAction2);
		}
		remove
		{
			BreakablePointContainerAction breakablePointContainerAction = BreakablePointsContainer.m_BreakEvent;
			BreakablePointContainerAction breakablePointContainerAction2;
			do
			{
				breakablePointContainerAction2 = breakablePointContainerAction;
				breakablePointContainerAction = Interlocked.CompareExchange(ref BreakablePointsContainer.m_BreakEvent, (BreakablePointContainerAction)Delegate.Remove(breakablePointContainerAction2, value), breakablePointContainerAction);
			}
			while (breakablePointContainerAction != breakablePointContainerAction2);
		}
	}

	protected override void OnAttackApplied(Tool thisTool, Weapon weapon, WeaponDamageType damageType, Vector3 point)
	{
		PhotonPlayer photonPlayer = base.owner;
		if (weapon != null && weapon.owner != null)
		{
			photonPlayer = weapon.owner;
		}
		if (photonPlayer != null)
		{
			playerHitInstances.Add(photonPlayer);
		}
		base.OnAttackApplied(thisTool, weapon, damageType, point);
	}

	protected override void OnHealthChange()
	{
		base.OnHealthChange();
		if (base.Health <= 0 && base.gameObject.activeSelf)
		{
			if (pointDropper != null && playerHitInstances.Count > 0)
			{
				pointDropper.DropPoints(playerHitInstances.ToArray());
			}
			if (BreakablePointsContainer.BreakEvent != null)
			{
				BreakablePointsContainer.BreakEvent(this);
			}
		}
	}

	protected override void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		base.OnToolReset(thisTool, resetPosition, resetRotation, oldPosition, wasCleanedUp);
		playerHitInstances.Clear();
	}
}
public class DoorUnlockTrigger : OverlapVolume
{
	private enum TriggerState
	{
		LOCKED,
		PRE
	}

	private PulsingBeam attractor;

	private Animator animator;

	private static readonly int ANIMATION_LOCKED_ID = Animator.StringToHash("Locked");

	private bool _active;

	private bool _locked;

	public bool Active
	{
		get
		{
			return _active;
		}
		set
		{
			_active = value;
			OnStateChange();
		}
	}

	public bool Locked
	{
		get
		{
			return _locked;
		}
		set
		{
			_locked = value;
			OnStateChange();
		}
	}

	private void Awake()
	{
		attractor = GetComponentInChildren<PulsingBeam>();
		animator = GetComponentInChildren<Animator>();
		OnStateChange();
	}

	private void OnStateChange()
	{
		if (attractor != null)
		{
			attractor.gameObject.SetActive(Active);
		}
		if (animator != null)
		{
			animator.SetBool(ANIMATION_LOCKED_ID, Locked);
		}
	}
}
namespace RecRoom.Activities.Quest
{
	public class QuestMeleeAttackEnemy : Enemy
	{
		private enum CombatState
		{
			FIND_TARGET = 0,
			FOLLOW_TARGET = 1,
			SCRAMBLE_CHARGE = 2,
			REPOSITION = 3,
			ATTACK = 4,
			BLOCK = 5,
			INVALID = 65535
		}

		private enum RepositionSubState
		{
			PREPARE,
			REPOSITION,
			POST
		}

		private enum AttackSubState
		{
			CHARGE,
			CHARGE_FAST,
			ATTACK,
			RECOVERY,
			INTERRUPTED
		}

		[Header("Target Selection")]
		[SerializeField]
		private float desiredTargetDistance = 1f;

		[SerializeField]
		private float minRandomTargetOffsetAngle = 15f;

		[SerializeField]
		private float maxRandomTargetOffsetAngle = 30f;

		[Header("Scramble To Target")]
		[SerializeField]
		private float scrambleToTargetDistance = 5f;

		[SerializeField]
		private float scrambleToTargetSpeed = 3f;

		[SerializeField]
		private bool scrambleHasRequiredAttackVariant;

		[SerializeField]
		private int scrambleRequiredAttackVariantIndex;

		[Header("Reposition")]
		[SerializeField]
		private bool repositionBeforeAttack = true;

		[SerializeField]
		private float repositionTargetDistanceMultiplier = 1f;

		[SerializeField]
		private float repositionAngle = 10f;

		[SerializeField]
		private float repositionPrepareDuration = 0.25f;

		[SerializeField]
		private float maximumRepositionDuration = 1f;

		[SerializeField]
		private float postRepositionDuration = 0.5f;

		[SerializeField]
		private float repositionSpeed = 6f;

		[SerializeField]
		private float repositionMaxForce = 100f;

		[SerializeField]
		private float repositionAngularSpeed = 720f;

		[Header("Charge Attack")]
		[SerializeField]
		private bool chargesAttack = true;

		[SerializeField]
		private float chargeAttackDuration = 0.5f;

		[SerializeField]
		private float chargeAttackFastDuration = 0.05f;

		[SerializeField]
		private bool supportsChargingWhileMoving = true;

		[Header("Attack")]
		[SerializeField]
		private float attackDuration = 1.5f;

		[Header("Attack Recovery")]
		[SerializeField]
		private float attackRecoveryDuration = 1f;

		[Header("Attack Block")]
		[SerializeField]
		private bool supportsBlocking = true;

		[SerializeField]
		private float blockDuration = 1f;

		[SerializeField]
		private float blockLinearVelocityMultiplier = 0.25f;

		[SerializeField]
		private float blockAngularVelocityMultiplier;

		[SerializeField]
		private RecRoomAudioClip blockAudio;

		[SerializeField]
		private PooledParticle blockParticles;

		[Header("Attack Interruption")]
		[SerializeField]
		private bool supportsAttackInterruption;

		[SerializeField]
		private float attackInterruptionDuration = 1.5f;

		[SerializeField]
		private RecRoomAudioClip attackInterruptAudio;

		[SerializeField]
		private PooledParticle attackInterruptParticle;

		[Header("Attack Colliders")]
		[SerializeField]
		private Collider swingCollider;

		private SynchronizedStateMachine combatStateMachine;

		private SynchronizedTimer combatTimer;

		private SynchronizedField<int> _meleeAttackVariantIndex;

		private AnimationAttackTrigger animationAttackTrigger;

		protected const RigidbodyConstraints BLOCK_RIGIDBODY_CONSTRAINTS = RigidbodyConstraints.FreezeRotation;

		private Vector3 repositionStartTargetPosition;

		private int MeleeAttackVariantIndex
		{
			get
			{
				return _meleeAttackVariantIndex.Get();
			}
			set
			{
				_meleeAttackVariantIndex.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			animationAttackTrigger = GetComponentInChildren<AnimationAttackTrigger>(includeInactive: true);
			if (animationAttackTrigger != null)
			{
				animationAttackTrigger.MeleeAttackEnableEvent += OnMeleeAttackAnimationActive;
			}
			_meleeAttackVariantIndex = new SynchronizedField<int>(this, "MAVI", 0, SetterPermissionMode.AUTHORITY, OnMeleeAttackVariantChange);
			OnMeleeAttackVariantChange();
			combatTimer = new SynchronizedTimer(this, "BEHAVIOR", SetterPermissionMode.AUTHORITY);
			combatStateMachine = new SynchronizedStateMachine("BEHAVIOR", SetterPermissionMode.AUTHORITY);
			combatStateMachine.AddState(ushort.MaxValue, null, null, null);
			combatStateMachine.AddState(0, OnEnterFindTargetState, null, OnUpdateFindTargetState);
			combatStateMachine.AddState(1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
			combatStateMachine.AddState(2, OnEnterScrambleChargeState, OnExitScrambleChargeState, OnUpdateScrambleChargeState);
			combatStateMachine.AddState(5, OnEnterBlockState, OnExitBlockState, OnUpdateBlockState);
			combatStateMachine.AddState(3, OnEnterRepositionSuperState, OnExitRepositionSuperState, null);
			combatStateMachine.AddState(3, 0, OnEnterPrepareRepositionSubState, null, OnUpdatePrepareRepositionSubState);
			combatStateMachine.AddState(3, 1, OnEnterRepositionSubState, null, OnUpdateRepositionSubState);
			combatStateMachine.AddState(3, 2, OnEnterPostRepositionSubState, null, OnUpdatePostRepositionSubState);
			combatStateMachine.AddState(4, OnEnterAttackSuperState, OnExitAttackSuperState, null);
			combatStateMachine.AddState(4, 0, OnEnterChargeAttackSubState, null, OnUpdateChargeAttackSubState);
			combatStateMachine.AddState(4, 1, OnEnterChargeAttackFastSubState, null, OnUpdateChargeAttackFastSubState);
			combatStateMachine.AddState(4, 2, OnEnterAttackSubState, OnExitAttackSubState, OnUpdateAttackSubState);
			combatStateMachine.AddState(4, 3, OnEnterAttackRecoverySubState, null, OnUpdateAttackRecoverySubState);
			combatStateMachine.AddState(4, 4, OnEnterAttackInterruptedSubState, null, OnUpdateAttackInterruptedSubState);
		}

		protected override void Start()
		{
			base.Start();
			EnableSwingCollider(enabled: false);
			combatStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (animationAttackTrigger != null)
			{
				animationAttackTrigger.MeleeAttackEnableEvent -= OnMeleeAttackAnimationActive;
			}
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			combatStateMachine.Update();
			combatTimer.UpdateCallbacks();
		}

		private void OnMeleeAttackAnimationActive(bool active)
		{
			if (base.MeleeCombatActive != active)
			{
				base.MeleeCombatActive = active;
			}
		}

		private void OnMeleeAttackVariantChange()
		{
			enemyAnimator.SetMeleeAttackVariantIndex(MeleeAttackVariantIndex);
		}

		protected override void OnPlayerImpact(Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (base.hasAuthority && hitPlayer.isLocal)
			{
				StartCoroutine(DeferredAttackPlayerCoroutine(enemy, hitPlayer, hitBodyPart, impact));
			}
			else
			{
				AttackPlayer(enemy, hitPlayer, hitBodyPart, impact);
			}
		}

		private IEnumerator DeferredAttackPlayerCoroutine(Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			yield return null;
			AttackPlayer(enemy, hitPlayer, hitBodyPart, impact);
		}

		private void AttackPlayer(Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (!(enemy == null) && !(hitPlayer == null) && base.hasAuthority && (combatStateMachine.CurrentStateId != 4 || combatStateMachine.CurrentSubStateId != 4) && (!IsPlayerBlocking(hitPlayer, out var blockingWeapon) || !AuthorityTryAttackInterrupt(hitPlayer.PhotonPlayer, blockingWeapon, impact.Point)))
			{
				base.OnPlayerImpact(enemy, hitPlayer, hitBodyPart, impact);
			}
		}

		protected override void OnPlayerToolImpact(Enemy enemy, Tool hitTool, WeaponImpact impact)
		{
			if (base.hasAuthority && supportsAttackInterruption && base.IsAlive && base.Health > 0)
			{
				MeleeWeapon component = hitTool.GetComponent<MeleeWeapon>();
				if (!(component == null) && component.Tool.IsHeld && !component.Tool.IsEquippedOnPlayer && !component.IsSwing())
				{
					AuthorityTryAttackInterrupt(component.owner, component, impact.Point);
				}
			}
		}

		protected override bool AuthorityTryApplyAttackInternal(Combatant attacker, Weapon weapon, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			if (attacker.Player != null && AuthorityTryApplyCustomMeleeAttack(weapon, attacker.Player.PhotonPlayer, impact))
			{
				return false;
			}
			return base.AuthorityTryApplyAttackInternal(attacker, weapon, damageType, armorType, damage, impact);
		}

		private bool AuthorityTryApplyCustomMeleeAttack(Weapon weapon, PhotonPlayer attackerPlayer, WeaponImpact impact)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (!base.IsAlive || base.Health <= 0)
			{
				return false;
			}
			MeleeWeapon meleeWeapon = ((!(weapon != null)) ? null : weapon.GetComponent<MeleeWeapon>());
			if (meleeWeapon == null)
			{
				return false;
			}
			if (!IsMeleeWeaponAttackFromFront(meleeWeapon, impact))
			{
				return false;
			}
			CombatState currentStateId = (CombatState)combatStateMachine.CurrentStateId;
			AttackSubState currentSubStateId = (AttackSubState)combatStateMachine.CurrentSubStateId;
			if (currentStateId == CombatState.ATTACK && currentSubStateId == AttackSubState.ATTACK)
			{
				return AuthorityTryAttackInterrupt(attackerPlayer, meleeWeapon, impact.Point);
			}
			bool flag = currentStateId == CombatState.ATTACK && (currentSubStateId == AttackSubState.CHARGE || currentSubStateId == AttackSubState.CHARGE_FAST);
			bool flag2 = currentStateId == CombatState.BLOCK || currentStateId == CombatState.REPOSITION || currentStateId == CombatState.SCRAMBLE_CHARGE;
			if (flag || flag2)
			{
				return AuthorityTryBlock(attackerPlayer, meleeWeapon, impact.Point, impact.SurfaceNormal);
			}
			return false;
		}

		private bool AuthorityTryBlock(PhotonPlayer attackingPlayer, MeleeWeapon weapon, Vector3 blockPoint, Vector3 blockNormal)
		{
			if (!supportsBlocking)
			{
				return false;
			}
			if (!weapon.CanBeBlockedByEnemies)
			{
				return false;
			}
			base.photonView.RpcAll(RpcOnBlock, attackingPlayer, blockPoint);
			if (combatStateMachine.CurrentStateId == 5)
			{
				combatTimer.StartTimer(blockDuration);
			}
			else
			{
				combatStateMachine.EnterState(5);
			}
			return true;
		}

		private bool IsPlayerBlocking(Player player, out MeleeWeapon blockingWeapon)
		{
			if (!IsToolBlocking(player.RightHand.HeldTool, out blockingWeapon) && !IsToolBlocking(player.LeftHand.HeldTool, out blockingWeapon))
			{
				return false;
			}
			Vector3 normalized = Vector3.ProjectOnPlane(base.RigidbodyEx.physicsPosition - player.TrackingSpace.RigidbodyEx.targetPosition, Vector3.up).normalized;
			return Vector3.Dot(player.TrackingSpace.RigidbodyEx.TargetTransform.forward, normalized) > 0f;
		}

		private bool IsToolBlocking(Tool tool, out MeleeWeapon blockingWeapon)
		{
			blockingWeapon = ((!(tool != null)) ? null : tool.GetComponent<MeleeWeapon>());
			return blockingWeapon != null && blockingWeapon.CanBlockEnemyMeleeAttacks && blockingWeapon.ManualBlockingEnabled;
		}

		[PunRPC]
		protected void RpcOnBlock(PhotonPlayer attackerPlayer, Vector3 blockPoint)
		{
			if (attackerPlayer != null && attackerPlayer.IsLocal)
			{
				AudioManager.Play2DSFX(blockAudio);
			}
			else
			{
				AudioManager.Play3DSFX(blockAudio, blockPoint);
			}
			if (attackInterruptParticle != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(blockParticles);
				if (pooledParticle != null)
				{
					pooledParticle.Play(blockPoint, Quaternion.identity);
				}
			}
			if (combatStateMachine.CurrentStateId == 5)
			{
				enemyAnimator.IsBlocking = true;
			}
		}

		private bool AuthorityTryAttackInterrupt(PhotonPlayer defendingPlayer, MeleeWeapon weapon, Vector3 blockPoint)
		{
			if (!supportsAttackInterruption)
			{
				return false;
			}
			if (!weapon.CanBlockEnemyMeleeAttacks)
			{
				return false;
			}
			base.photonView.RpcAll(RpcOnAttackInterrupt, defendingPlayer, weapon.photonView.viewID, blockPoint);
			combatStateMachine.EnterState(4, 4);
			return true;
		}

		[PunRPC]
		protected void RpcOnAttackInterrupt(PhotonPlayer defenderPlayer, int weaponId, Vector3 point)
		{
			if (defenderPlayer != null && defenderPlayer.IsLocal)
			{
				AudioManager.Play2DSFX(attackInterruptAudio);
			}
			else
			{
				AudioManager.Play3DSFX(attackInterruptAudio, point);
			}
			if (attackInterruptParticle != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(attackInterruptParticle);
				if (pooledParticle != null)
				{
					pooledParticle.Play(point, Quaternion.identity);
				}
			}
			PhotonView photonView = PhotonView.Find(weaponId);
			MeleeWeapon meleeWeapon = ((!(photonView != null)) ? null : photonView.GetComponent<MeleeWeapon>());
			if (meleeWeapon != null)
			{
				meleeWeapon.OnBlockAttack(point);
			}
		}

		private bool IsMeleeWeaponAttackFromFront(MeleeWeapon weapon, WeaponImpact impact)
		{
			if (impact.GameObject == null || weapon.Tool == null)
			{
				return false;
			}
			Vector3 vector = ((!weapon.Tool.IsHeldByPlayer) ? impact.Point : weapon.Tool.HolderHand.transform.position);
			Vector3 normalized = (vector - impact.GameObject.transform.position).normalized;
			return Vector3.Dot(normalized, base.transform.forward) >= -0.2f;
		}

		private void EnableSwingCollider(bool enabled)
		{
			if (swingCollider != null)
			{
				swingCollider.enabled = enabled;
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			return FindLeastTargetedNearbyTarget(isPatrolling, mustHaveLineOfSight: true);
		}

		private void OnEnterFindTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
		}

		private void OnUpdateFindTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Combatant target = FindTarget();
			if (target.IsValid)
			{
				base.Target = target;
				base.LastAttacker = Combatant.Invalid;
				MeleeAttackVariantIndex = enemyAnimator.GetRandomMeleeAttackVariantIndex();
				if (repositionBeforeAttack && InRepositionRange(base.Target.FloorPosition, base.Steering.SurfacePosition, 0.5f))
				{
					combatStateMachine.EnterState(3, 0);
				}
				else
				{
					combatStateMachine.EnterState(1);
				}
			}
			else
			{
				UpdateTargetCentroidPath(1f);
			}
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
			base.Steering.MaxAngularSpeed = movementAngularSpeed;
		}

		private void OnUpdateFollowTargetState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				combatStateMachine.EnterState(0);
				return;
			}
			Vector3 floorPosition = base.Target.FloorPosition;
			Vector3 surfacePosition = base.Steering.SurfacePosition;
			float sqrMagnitude = (surfacePosition - floorPosition).sqrMagnitude;
			float num = desiredTargetDistance * desiredTargetDistance;
			if (sqrMagnitude <= num || (base.Steering.IsPathing && base.Steering.ReachedPathDestination))
			{
				if (repositionBeforeAttack && InRepositionRange(floorPosition, base.Steering.SurfacePosition, -0.2f))
				{
					combatStateMachine.EnterState(3, 0);
				}
				else if (chargesAttack)
				{
					combatStateMachine.EnterState(4, 0);
				}
				else
				{
					combatStateMachine.EnterState(4, 2);
				}
				return;
			}
			float num2 = scrambleToTargetDistance * scrambleToTargetDistance;
			float distanceToClosestTargetSqr;
			Combatant closestOpponent = SingletonMonoBehaviour<EnemyManager>.Instance.GetClosestOpponent(this, out distanceToClosestTargetSqr);
			if (supportsChargingWhileMoving && closestOpponent.IsValid && distanceToClosestTargetSqr <= num2)
			{
				base.Target = closestOpponent;
				combatStateMachine.EnterState(2);
				return;
			}
			float num3 = Mathf.Max(0f, desiredTargetDistance - 0.5f);
			if (!base.Steering.PathIsValid(floorPosition, num3 * 1.1f))
			{
				floorPosition = GetRandomOffsetPosition(floorPosition, num3, minRandomTargetOffsetAngle, maxRandomTargetOffsetAngle);
				base.Steering.Path(floorPosition);
			}
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			base.Steering.StopPathing();
		}

		private bool InRepositionRange(Vector3 targetPosition, Vector3 currentPosition, float epsilon)
		{
			float num = repositionTargetDistanceMultiplier * desiredTargetDistance;
			return (targetPosition - currentPosition).magnitude - num <= epsilon;
		}

		private void OnEnterRepositionSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = repositionSpeed;
			base.Steering.MaxHorizontalSteeringForce = repositionMaxForce;
			base.Steering.MaxAngularSpeed = repositionAngularSpeed;
			repositionStartTargetPosition = ((!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target)) ? latestVisibleTargetFloorPosition : base.Target.FloorPosition);
		}

		private void OnExitRepositionSuperState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.Jump = EnemyAnimator.JumpState.NONE;
		}

		private void OnEnterPrepareRepositionSubState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.Jump = EnemyAnimator.JumpState.PREPARE;
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(repositionPrepareDuration);
			}
		}

		private void OnUpdatePrepareRepositionSubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(3, 1);
			}
		}

		private void OnEnterRepositionSubState(ushort previousStateId, ushort previousSubStateId)
		{
			enemyAnimator.Jump = EnemyAnimator.JumpState.JUMP;
			if (base.hasAuthority)
			{
				base.Steering.Look(GetLookAtVector(repositionStartTargetPosition, inXZPlane: true));
				Vector3 surfacePosition = base.Steering.SurfacePosition;
				float rotationAngle = ((!((repositionStartTargetPosition - surfacePosition).magnitude - desiredTargetDistance <= 0.5f)) ? 0f : repositionAngle);
				Vector3 repositionPosition = GetRepositionPosition(repositionStartTargetPosition, surfacePosition, desiredTargetDistance, rotationAngle);
				base.Steering.Path(repositionPosition, 1f, 0.02f);
				combatTimer.StartTimer(maximumRepositionDuration);
			}
		}

		private void OnUpdateRepositionSubState()
		{
			if (base.hasAuthority)
			{
				base.Steering.Look(GetLookAtVector(repositionStartTargetPosition, inXZPlane: true));
				if (base.Steering.ReachedPathDestination || combatTimer.TimerOver)
				{
					combatStateMachine.EnterState(3, 2);
				}
			}
		}

		private void OnEnterPostRepositionSubState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopPathing();
			enemyAnimator.Jump = EnemyAnimator.JumpState.JUMP;
			if (base.hasAuthority)
			{
				base.Steering.Look(GetLookAtVector(repositionStartTargetPosition, inXZPlane: true));
				combatTimer.StartTimer(postRepositionDuration);
			}
		}

		private void OnUpdatePostRepositionSubState()
		{
			if (base.hasAuthority)
			{
				base.Steering.Look(GetLookAtVector(repositionStartTargetPosition, inXZPlane: true));
				if (combatTimer.TimerOver)
				{
					combatStateMachine.EnterState(4, 1);
				}
			}
		}

		private Vector3 GetRepositionPosition(Vector3 targetPosition, Vector3 currentPosition, float targetDistance, float rotationAngle)
		{
			Vector3 vector = Vector3.ProjectOnPlane(currentPosition - targetPosition, Vector3.up).normalized * targetDistance;
			if (Mathf.Abs(rotationAngle) <= 1f)
			{
				return targetPosition + vector;
			}
			Vector3 vector2 = Quaternion.Euler(0f, rotationAngle, 0f) * vector;
			Vector3 closestNavMeshPostion = targetPosition + vector2;
			bool flag = Enemy.TrySampleNavMesh(closestNavMeshPostion, out closestNavMeshPostion);
			Vector3 vector3 = Quaternion.Euler(0f, 0f - rotationAngle, 0f) * vector;
			Vector3 closestNavMeshPostion2 = targetPosition + vector3;
			bool flag2 = Enemy.TrySampleNavMesh(closestNavMeshPostion2, out closestNavMeshPostion2);
			if (flag && flag2)
			{
				return GetBetterRepositionPosition(targetPosition, currentPosition, targetDistance, closestNavMeshPostion, closestNavMeshPostion2);
			}
			if (flag)
			{
				return closestNavMeshPostion;
			}
			if (flag2)
			{
				return closestNavMeshPostion2;
			}
			Enemy.TrySampleNavMesh(targetPosition + vector, out var closestNavMeshPostion3);
			return closestNavMeshPostion3;
		}

		private Vector3 GetBetterRepositionPosition(Vector3 targetPosition, Vector3 currentPosition, float targetDistance, Vector3 reposition1, Vector3 reposition2)
		{
			float num = targetDistance * targetDistance;
			float num2 = Mathf.Abs((reposition1 - targetPosition).sqrMagnitude - num);
			float num3 = Mathf.Abs((reposition2 - targetPosition).sqrMagnitude - num);
			float num4 = num2 - num3;
			if (num4 <= -0.001f)
			{
				return reposition1;
			}
			if (num4 >= 0.001f)
			{
				return reposition2;
			}
			float sqrMagnitude = (reposition1 - currentPosition).sqrMagnitude;
			float sqrMagnitude2 = (reposition2 - currentPosition).sqrMagnitude;
			float num5 = sqrMagnitude - sqrMagnitude2;
			if (num5 >= 0.01f)
			{
				return reposition1;
			}
			if (num5 <= -0.01f)
			{
				return reposition2;
			}
			return (!UnityExtensions.GetRandomResult(0.5f)) ? reposition2 : reposition1;
		}

		private void OnEnterScrambleChargeState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			base.Steering.MaxHorizontalSpeed = scrambleToTargetSpeed;
			if (scrambleHasRequiredAttackVariant)
			{
				MeleeAttackVariantIndex = scrambleRequiredAttackVariantIndex;
			}
			enemyAnimator.IsSprinting = true;
		}

		private void OnUpdateScrambleChargeState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
			Vector3 floorPosition = base.Target.FloorPosition;
			Vector3 surfacePosition = base.Steering.SurfacePosition;
			float sqrMagnitude = (surfacePosition - floorPosition).sqrMagnitude;
			float num = desiredTargetDistance * desiredTargetDistance;
			if (sqrMagnitude <= num || (base.Steering.IsPathing && base.Steering.ReachedPathDestination))
			{
				combatStateMachine.EnterState(4, 0);
				return;
			}
			float num2 = Mathf.Max(0f, desiredTargetDistance - 0.5f);
			if (!base.Steering.PathIsValid(floorPosition, num2 * 1.1f))
			{
				floorPosition = GetRandomOffsetPosition(floorPosition, num2, minRandomTargetOffsetAngle, maxRandomTargetOffsetAngle);
				base.Steering.Path(floorPosition);
			}
		}

		private void OnExitScrambleChargeState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			enemyAnimator.IsSprinting = false;
		}

		private void OnEnterBlockState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
			base.RigidbodyEx.constraints = RigidbodyConstraints.FreezeRotation;
			enemyAnimator.IsBlocking = true;
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(blockDuration);
			}
		}

		private void OnUpdateBlockState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(4, 1);
			}
		}

		private void OnExitBlockState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopAll();
			base.RigidbodyEx.constraints = RigidbodyConstraints.FreezeRotation;
			enemyAnimator.IsBlocking = false;
		}

		private void OnEnterAttackSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.StopAll();
		}

		private void OnExitAttackSuperState(ushort nextStateId, ushort nextSubStateId)
		{
			base.RigidbodyEx.RemoveKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.NONE;
		}

		private void OnEnterChargeAttackSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(chargeAttackDuration);
			}
			base.RigidbodyEx.AddKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.CHARGE;
			enemyAudio.OnChargeAttack();
		}

		private void OnUpdateChargeAttackSubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(4, 2);
			}
		}

		private void OnEnterChargeAttackFastSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(chargeAttackFastDuration);
			}
			base.RigidbodyEx.AddKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.CHARGE;
		}

		private void OnUpdateChargeAttackFastSubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(4, 2);
			}
		}

		private void OnEnterAttackSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				base.RigidbodyEx.targetRotation = Quaternion.LookRotation(GetLookAtTargetVector(inXZPlane: true), Vector3.up);
				combatTimer.StartTimer(attackDuration);
			}
			if (animationAttackTrigger == null)
			{
				base.MeleeCombatActive = true;
			}
			EnableSwingCollider(enabled: true);
			base.RigidbodyEx.AddKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK;
			enemyAudio.OnAttack();
		}

		private void OnUpdateAttackSubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(4, 3);
			}
		}

		private void OnExitAttackSubState(ushort nextStateId, ushort nextSubStateId)
		{
			EnableSwingCollider(enabled: false);
			if (animationAttackTrigger == null)
			{
				base.MeleeCombatActive = false;
			}
		}

		private void OnEnterAttackRecoverySubState(ushort previousStateId, ushort previousSubStateId)
		{
			base.RigidbodyEx.AddKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.POST_ATTACK;
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(attackRecoveryDuration);
			}
		}

		private void OnUpdateAttackRecoverySubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(0);
			}
		}

		private void OnEnterAttackInterruptedSubState(ushort previousStateId, ushort previousSubStateId)
		{
			base.RigidbodyEx.AddKinematic(this);
			enemyAnimator.MeleeCombat = EnemyAnimator.MeleeCombatState.ATTACK_INTERRUPTED;
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(attackInterruptionDuration);
			}
		}

		private void OnUpdateAttackInterruptedSubState()
		{
			if (base.hasAuthority && combatTimer.TimerOver)
			{
				combatStateMachine.EnterState(0);
			}
		}

		public override void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority)
			{
				float num = Vector3.Dot(velocity.normalized, Vector3.up);
				if (num < 0f)
				{
					float magnitude = velocity.magnitude;
					velocity = Vector3.ProjectOnPlane(velocity, Vector3.up).normalized * magnitude;
				}
				if (combatStateMachine.CurrentStateId == 5)
				{
					velocity *= blockLinearVelocityMultiplier;
					angularVelocity *= blockAngularVelocityMultiplier;
				}
				base.AuthorityOnDamageChangeVelocity(damageType, armorType, velocity, angularVelocity);
			}
		}

		protected override void OnInterruptedRecoveryStart()
		{
			base.OnInterruptedRecoveryStart();
			if (base.hasAuthority)
			{
				base.Steering.Look(Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized);
			}
		}

		protected override void OnInterruptedRecoveryEnd()
		{
			base.OnInterruptedRecoveryEnd();
			base.Steering.StopLooking();
		}
	}
