	public static class QuestGearSettings
	{
		private static QuestGearConfig ConfigAsset = CustomSettingsLoader.LoadConfig<QuestGearConfig>();

		private const string ConfigsAssetFilePath = "Assets/Activities/Quest/Shared/Content/Configs/";

		private static QuestGearConfig GetConfigAssetForCampaign(QuestCampaign campaign)
		{
			if (ConfigAsset == null || ConfigAsset.campaign != campaign)
			{
				ConfigAsset = CustomSettingsLoader.LoadConfig<QuestGearConfig>(campaign.ToString());
			}
			return ConfigAsset;
		}

		public static QuestGearEntry[] GetQuestGearTypes(QuestCampaign campaign)
		{
			QuestGearConfig configAssetForCampaign = GetConfigAssetForCampaign(campaign);
			if (configAssetForCampaign != null)
			{
				return ConfigAsset.gearTypes;
			}
			return null;
		}

		public static int[] GetNumberOfItemsToDropRange(QuestCampaign campaign)
		{
			QuestGearConfig configAssetForCampaign = GetConfigAssetForCampaign(campaign);
			if (configAssetForCampaign != null)
			{
				return new int[2] { configAssetForCampaign.minNumberOfItemsSpawnedPerDrop, configAssetForCampaign.maxNumberOfItemsSpawnedPerDrop };
			}
			return null;
		}

		public static QuestGear GetGearCustomBehavior(QuestCampaign campaign)
		{
			QuestGearConfig configAssetForCampaign = GetConfigAssetForCampaign(campaign);
			if (configAssetForCampaign != null)
			{
				QuestGear customGearBehavior = configAssetForCampaign.customGearBehavior;
				if (customGearBehavior != null)
				{
					return customGearBehavior.GetComponent<QuestGear>();
				}
			}
			return null;
		}
	}
