public class LockableDoor : TeleportationPortal
{
	[SerializeField]
	private RecRoomAudioClip unlockAudio;

	[SerializeField]
	private GameObject lockVisual;

	[SerializeField]
	private GameObject teleportBlockingColliders;

	private static readonly int ANIMATION_LOCKED_ID = Animator.StringToHash("Locked");

	public GameObject TeleportBlockingColliders => teleportBlockingColliders;

	public override bool IsLocked
	{
		get
		{
			return _isLocked;
		}
		set
		{
			_isLocked = value;
			if (lockVisual != null)
			{
				lockVisual.gameObject.SetActive(_isLocked);
			}
			if (Animator != null)
			{
				Animator.SetBool(ANIMATION_LOCKED_ID, _isLocked);
			}
			if (!_isLocked && unlockAudio != null && unlockAudio.audioClip != null)
			{
				AudioManager.Play3DSFX(unlockAudio, base.transform);
			}
			if (teleportBlockingColliders != null)
			{
				teleportBlockingColliders.SetActive(_isLocked);
			}
		}
	}

	private void Reset()
	{
		mode = PortalMode.Nothing;
	}
}
public enum PointDropType
{
