}
public class PointsDropper : Photon.MonoBehaviour
{
	public delegate void PointsDrop(PointsDropper thisDropper, Vector3 position, PhotonPlayer[] rewardedPlayers, int minValue, int maxValue, PointDropType lootType, bool dontAddToCombatScore = false);

	[SerializeField]
	private PointDropType lootType;

	[SerializeField]
	[FormerlySerializedAs("minGold")]
	private int minDropValue;

	[SerializeField]
	[FormerlySerializedAs("maxGold")]
	private int maxDropValue;

	[SerializeField]
	[FormerlySerializedAs("dropParticleOffset")]
	private float dropFeedbackOffset = 0.15f;

	[SerializeField]
	private SpawnableToolType spawnEquipmentTool = SpawnableToolType.INVALID;

	[SerializeField]
	[Header("For CBM")]
	[Tooltip("Gets routed through point system for added effects (such as giving silver in addition to points) but not actually added to team score (combat score)")]
	private bool dontAddToCombatScore;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private static PointsDrop m_PointsDropEvent;

	public int MinDropValue => minDropValue;

	public int MaxDropValue => maxDropValue;

	public static event PointsDrop PointsDropEvent
	{
		add
		{
			PointsDrop pointsDrop = PointsDropper.m_PointsDropEvent;
			PointsDrop pointsDrop2;
			do
			{
				pointsDrop2 = pointsDrop;
				pointsDrop = Interlocked.CompareExchange(ref PointsDropper.m_PointsDropEvent, (PointsDrop)Delegate.Combine(pointsDrop2, value), pointsDrop);
			}
			while (pointsDrop != pointsDrop2);
		}
		remove
		{
			PointsDrop pointsDrop = PointsDropper.m_PointsDropEvent;
			PointsDrop pointsDrop2;
			do
			{
				pointsDrop2 = pointsDrop;
				pointsDrop = Interlocked.CompareExchange(ref PointsDropper.m_PointsDropEvent, (PointsDrop)Delegate.Remove(pointsDrop2, value), pointsDrop);
			}
			while (pointsDrop != pointsDrop2);
		}
	}

	public void DropPoints(PhotonPlayer[] rewardedPlayers)
	{
		DropPoints(rewardedPlayers, base.transform.position + Vector3.up * dropFeedbackOffset);
	}

	public virtual void DropPoints(PhotonPlayer[] rewardedPlayers, Vector3 point)
	{
		if (base.enabled && PointsDropper.PointsDropEvent != null)
		{
			PointsDropper.PointsDropEvent(this, point, rewardedPlayers, minDropValue, maxDropValue, lootType, dontAddToCombatScore);
		}
		if (base.enabled && spawnEquipmentTool != SpawnableToolType.INVALID)
		{
			MasterSpawnLoot(spawnEquipmentTool, base.transform.position, UnityEngine.Random.rotation, 1f, Vector3.up + UnityEngine.Random.insideUnitSphere, UnityEngine.Random.insideUnitSphere, lootShouldDespawn: false);
		}
	}

	private LootTool MasterSpawnLoot(SpawnableToolType spawnTool, Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity, bool lootShouldDespawn)
	{
		if (!PhotonNetwork.isMasterClient || NetworkedSingletonMonoBehaviour<GameManager>.Instance == null)
		{
			return null;
		}
		Tool tool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(spawnTool, spawnPoint, spawnOrientation, spawnScale, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup: true);
		LootTool result = tool?.GetComponent<LootTool>();
		if (tool != null && tool.RigidbodyEx != null)
		{
			tool.RigidbodyEx.velocity = linearVelocity;
			tool.RigidbodyEx.angularVelocity = angularVelocity;
		}
		return result;
	}
}
