		private float _localPlayerLoot;

		private float serverLootBaseValue = 1f;

		private float serverMaxLootValueMultiplier = 999.9f;

		private bool hasOverrideEnemyDeathLootDropRate;

		private float overrideEnemyDeathLootDropRate;

		private bool loadedFirstRoom;

		private static List<LostLootData> SessionAllLostLoot = new List<LostLootData>();

		private static readonly string LOOT_VALUE_FORMAT_STRING = "+{0}";

		private static readonly float NOTIFICATION_DURATION = 0.66f;

		private static readonly Vector3 NOTIFICATION_OFFSET = new Vector3(0f, 0.5f, 0f);

		private static readonly string REWARDS_DISABLED_NOTIFICATION = "Rewards are disabled in this room.";

		private static readonly float NOTIFICATION_AUDIO_DELAY = 0.15f;

		private float EnemyLootDropRate
		{
			get
			{
				if (hasOverrideEnemyDeathLootDropRate)
				{
					return overrideEnemyDeathLootDropRate;
				}
				return enemyDeathLootDropRateDefault;
			}
		}

		public static LootManager Instance { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			if (Instance == null)
			{
				Instance = this;
			}
			RecRoomSceneManager.LevelRoomLoadedEvent = (RecRoomSceneManager.LevelRoomAction)Delegate.Combine(RecRoomSceneManager.LevelRoomLoadedEvent, new RecRoomSceneManager.LevelRoomAction(OnLevelRoomLoad));
			if (gameManager != null)
			{
				gameManager.GameStartedEvent += OnGameStart;
				gameManager.GameWinEvent += OnGameWin;
				gameManager.GameLoseEvent += OnGameLose;
			}
			InitializeStorefront();
			LootTool.CollectEvent = (LootTool.LootToolAction)Delegate.Combine(LootTool.CollectEvent, new LootTool.LootToolAction(OnCollectLoot));
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Combine(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
			Enemy.EnemyDeathEvent += OnEnemyDeath;
			QuestManager.CheckpointReachedEvent += OnCheckpointReached;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			LootTool.CollectEvent = (LootTool.LootToolAction)Delegate.Remove(LootTool.CollectEvent, new LootTool.LootToolAction(OnCollectLoot));
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Remove(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
			Enemy.EnemyDeathEvent -= OnEnemyDeath;
			QuestManager.CheckpointReachedEvent -= OnCheckpointReached;
			if (gameManager != null)
			{
				gameManager.GameStartedEvent -= OnGameStart;
				gameManager.GameWinEvent -= OnGameWin;
				gameManager.GameLoseEvent -= OnGameLose;
			}
			RecRoomSceneManager.LevelRoomLoadedEvent = (RecRoomSceneManager.LevelRoomAction)Delegate.Remove(RecRoomSceneManager.LevelRoomLoadedEvent, new RecRoomSceneManager.LevelRoomAction(OnLevelRoomLoad));
			if (Instance == this)
			{
				Instance = null;
			}
		}

		private void OnGameStart()
		{
			loadedFirstRoom = false;
			ClearLocalPlayerLoot();
			if (!gameManager.CustomGameSettings.AllowRewards)
			{
				ClearLocalPlayerLostLootForCurrentActivityLevel();
			}
			if (!CurrentLocationHasLevelRooms())
			{
				StartCoroutine(TrySpawnLootCoroutine());
			}
		}

		private void OnLevelRoomLoad()
		{
			StartCoroutine(TrySpawnLootCoroutine());
		}

		private void OnGameLose()
		{
			if (lootLossType == LootLossType.RECOVERABLE_LOST_LOOT)
			{
				StartCoroutine(DropLostLootCoroutine());
			}
			else if (lootLossType == LootLossType.BANK_AT_CHECKPOINTS)
			{
				StartCoroutine(LoseAllLootCoroutine());
			}
		}

		private void OnGameWin()
		{
			StartCoroutine(BankLootCoroutine(questWasWon: true));
		}

		private void OnCheckpointReached()
		{
			if (lootLossType == LootLossType.BANK_AT_CHECKPOINTS)
			{
				StartCoroutine(BankLootCoroutine(questWasWon: false));
			}
		}

		private IEnumerator TrySpawnLootCoroutine()
		{
			if (TryRequestLostLootSpawnInCurrentScene(Vector3.zero))
			{
				ClearLocalPlayerLostLootForCurrentActivityLevel();
				yield return new WaitForSeconds(lostLootNearbyNotificationDelay);
				string title = "YOUR LOST GOLD IS NEARBY";
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, 3f);
				yield return new WaitForSeconds(NOTIFICATION_AUDIO_DELAY);
				AudioManager.Play2DSFX(lostLootNearbyNotificationAudio);
			}
			else if (!loadedFirstRoom && GetCurrentRoomSceneLocationHasLostLoot())
			{
				yield return new WaitForSeconds(lostLootReminderNotificationDelay);
				string title2 = "YOUR LOST GOLD IS STILL OUT THERE";
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title2, 3f);
				yield return new WaitForSeconds(NOTIFICATION_AUDIO_DELAY);
				AudioManager.Play2DSFX(lostLootReminderNotificationAudio);
			}
			loadedFirstRoom = true;
		}

		private IEnumerator DropLostLootCoroutine()
		{
			yield return new WaitForSeconds(dropLostLootDelay);
			ClearLocalPlayerLostLootForCurrentActivityLevel();
			if (IsLocalPlayerPlaying() && TryGetLocalPlayerLoot(out var currentLootValue) && currentLootValue != 0f)
			{
				Vector3 worldSpaceDropPosition = Player.LocalPlayer.CurrentFloorPosition;
				Quaternion worldSpaceDropRotation = Player.LocalPlayer.TrackingSpace.transform.rotation;
				if (!Player.LocalPlayer.IsOverValidGround(out var _))
				{
					worldSpaceDropPosition = Player.LocalPlayer.LastLocalPlayerValidGroundPosition;
				}
				bool maxedOutLootPile = false;
				if (currentLootValue >= (float)maxLostLootPileValue)
				{
					currentLootValue = maxLostLootPileValue;
					maxedOutLootPile = true;
				}
				SetLocalPlayerLostLootForCurrentScene(currentLootValue, worldSpaceDropPosition, worldSpaceDropRotation);
				ClearLocalPlayerLoot();
				Vector3 spawnVelocity = (Vector3.ProjectOnPlane(Player.LocalPlayer.Head.transform.forward, Vector3.up).normalized + Vector3.up).normalized * lostLootPreviewSpawnSpeed;
				if (TryRequestLostLootSpawnInCurrentScene(spawnVelocity))
				{
					AudioManager.Play2DSFX(dropLostLootAudio);
					float timeRemaining = dropLostLootNotificationDelay - dropLostLootDelay;
					yield return new WaitForSeconds(timeRemaining);
					string title = $"YOU LOST {currentLootValue} GOLD";
					string subtitle = ((!maxedOutLootPile) ? "CONTINUE TO RECOVER IT!" : "MAX SIZE GOLD PILE");
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, subtitle, 3f);
					yield return new WaitForSeconds(NOTIFICATION_AUDIO_DELAY);
					AudioManager.Play2DSFX(dropLostLootNotificationAudio);
				}
			}
		}

		private IEnumerator LoseAllLootCoroutine()
		{
			yield return new WaitForSeconds(bankLootDelay);
			if (TryGetLocalPlayerLoot(out var currentLootValue) && (float)(int)currentLootValue != 0f)
			{
				ClearLocalPlayerLoot();
				AudioManager.Play2DSFX(dropLostLootAudio);
				string title = $"SILVER DROPPED";
				string subtitle = "Reach checkpoints to bank your silver";
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, subtitle, 5f);
			}
		}

		private IEnumerator BankLootCoroutine(bool questWasWon)
		{
			int bonus = 0;
			if (questWasWon && rankBonuses != null)
			{
				GameScoreManager.ScoreRank teamRank = gameManager.ScoreManager.GetTeamRank(gameManager.TeamManager.GetPlayerTeam(PhotonNetwork.player));
				RankBucket[] array = rankBonuses;
				for (int i = 0; i < array.Length; i++)
				{
					RankBucket rankBucket = array[i];
					if (rankBucket.rank == teamRank)
					{
						bonus = rankBucket.bonus;
						break;
					}
				}
			}
			yield return new WaitForSeconds(bankLootDelay);
			if (lootLossType == LootLossType.RECOVERABLE_LOST_LOOT)
			{
				ClearLocalPlayerLostLootForCurrentActivityLevel();
			}
			if (TryGetLocalPlayerLoot(out var currentLootValue))
			{
				string title = ((!UploadLootToStorefront(currentLootValue + (float)bonus)) ? REWARDS_DISABLED_NOTIFICATION : string.Format(lootBankedText, currentLootValue));
				if (bonus > 0)
				{
					string subtitleText = $"Rank Bonus +{bonus} Silver!";
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, subtitleText, 5f);
					AddLocalPlayerLoot(bonus);
				}
				else if (lootLossType == LootLossType.BANK_AT_CHECKPOINTS)
				{
					string subtitleText2 = title;
					title = "CHECKPOINT REACHED";
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, subtitleText2, 5f);
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, title, 3f);
				}
				yield return new WaitForSeconds(NOTIFICATION_AUDIO_DELAY);
				AudioManager.Play2DSFX(bankLootNotificationAudio);
				if (!questWasWon)
				{
					ClearLocalPlayerLoot();
				}
			}
		}

		private void OnCollectLoot(LootTool lootTool)
		{
			if (lootTool.IsLostLoot)
			{
				OnRecoverLostLoot(lootTool);
			}
			else
			{
				OnPickupRegularLoot(lootTool);
			}
		}

		private void OnRecoverLostLoot(LootTool lootTool)
		{
			float lostLootValue = lootTool.LostLootValue;
			string text = null;
			if (Profiles.LocalProfile != null && (long)Profiles.LocalProfile.Id == lootTool.LostLootOwnerId)
			{
				AddLootSinglePlayer(lootTool, PhotonNetwork.player, lostLootValue);
				text = "YOU";
			}
			else
			{
				Profile profile = Profiles.Get(lootTool.LostLootOwnerId);
				text = ((profile == null) ? "PLAYER" : ((string)profile.DisplayName));
			}
			AudioManager.Play3DSFX(lostLootPickupAudio, lootTool.transform.position);
			string titleText = $"{text} RECOVERED";
			string subtitleText = $"{lostLootValue} LOST GOLD";
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, subtitleText, 3f);
		}

		private void OnPickupRegularLoot(LootTool lootTool)
		{
			float num = 0f;
			if (gameManager.CustomGameSettings.AllowRewards)
			{
				num = lootTool.LootType switch
				{
					LootType.LARGE_PILE => largePileLootValue, 
					LootType.CUSTOM_VALUE => lootTool.CustomValue, 
					_ => smallPileLootValue, 
				};
			}
			AddLootToAllPlayers(lootTool, num);
			WorldSpaceNotification worldSpaceNotification = WorldSpaceNotification.PlayNext(string.Format(LOOT_VALUE_FORMAT_STRING, num), 2f, null, followPlayer: false, lootTool.transform.position + NOTIFICATION_OFFSET, NOTIFICATION_DURATION, billboard: true);
			AudioManager.PlayRandom3DSFX(lootPilePickupAudio, lootTool.transform.position);
			if (lootTool.PickupVFXPrefab != null)
			{
				PooledParticle.TryPlayPrefab(lootTool.PickupVFXPrefab, lootTool.transform.position, Quaternion.LookRotation(Vector3.up));
			}
			QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
			if (worldSpaceNotification != null && questManager != null && questManager.hasCustomPointDropColor)
			{
				worldSpaceNotification.Color = questManager.customPointDropColor;
			}
		}

		private LootTool MasterSpawnLoot(SpawnableToolType lootEquipment, Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity, bool lootShouldDespawn)
		{
			if (!PhotonNetwork.isMasterClient || gameManager == null)
			{
				return null;
			}
			if (gameManager == null)
			{
				return null;
			}
			Tool tool = gameManager.SpawnManager.MasterSpawnEquipment(lootEquipment, spawnPoint, spawnOrientation, spawnScale, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup: true);
			LootTool lootTool = ((!(tool != null)) ? null : tool.GetComponent<LootTool>());
			if (lootTool != null && lootShouldDespawn)
			{
				lootTool.MasterStartDespawn(spawnedLootPileLifetime);
			}
			if (tool != null && tool.RigidbodyEx != null)
			{
				tool.RigidbodyEx.velocity = linearVelocity;
				tool.RigidbodyEx.angularVelocity = angularVelocity;
			}
			return lootTool;
		}

		private void OnChestOpen(EquipmentSpawnerChest chest)
		{
			if (PhotonNetwork.isMasterClient)
			{
				int num = Mathf.RoundToInt(smallChestLootValue / smallPileLootValue);
				for (int i = 0; i < num; i++)
				{
					float normalizedArcAngle = Mathf.InverseLerp(0f, num - 1, i);
					chest.GetEquipmentSpawnPhysics(normalizedArcAngle, out var position, out var orientation, out var linearVelocity, out var angularVelocity);
					MasterSpawnLoot(smallPileEquipmentType, position, orientation, 1f, linearVelocity, angularVelocity, lootShouldDespawn: true);
				}
			}
		}

		public void SetEnemyLootDropRate(float enemyLootDropRate)
		{
			hasOverrideEnemyDeathLootDropRate = true;
			overrideEnemyDeathLootDropRate = enemyLootDropRate;
		}

		public void ResetEnemyLootDropRate()
		{
			hasOverrideEnemyDeathLootDropRate = false;
		}

		public float GetDefaultEnemyLootDropRate()
		{
			return enemyDeathLootDropRateDefault;
		}

		private void OnEnemyDeath(Enemy enemy)
		{
			if (PhotonNetwork.isMasterClient && !(enemy == null) && !(enemy.LastAttacker.Player == null) && UnityExtensions.GetRandomResult(EnemyLootDropRate))
			{
				Vector3 position = enemy.ObjectSpawnOrigin.position;
				int num = Mathf.RoundToInt(enemyLootValue / smallPileLootValue);
				for (int i = 0; i < num; i++)
				{
					Vector2 vector = UnityEngine.Random.insideUnitCircle * enemyLootMaxHorizontalSpawnRandomOffset;
					Vector3 vector2 = new Vector3(vector.x, 1f, vector.y);
					Vector3 linearVelocity = vector2 * enemyLootMaxLinearSpeed;
					Vector3 angularVelocity = UnityEngine.Random.onUnitSphere * enemyLootMaxAngularSpeed;
					MasterSpawnLoot(smallPileEquipmentType, position, Quaternion.identity, 1f, linearVelocity, angularVelocity, lootShouldDespawn: true);
				}
				base.photonView.RpcAll(RpcOnLootSpawn, position);
			}
		}

		private void OnBreakablePointContainerBroken(BreakablePointsContainer container)
		{
			if (PhotonNetwork.isMasterClient && !(container == null) && UnityExtensions.GetRandomResult(breakableContainerLootDropRateDefault))
			{
				Vector3 position = container.transform.position;
				int num = Mathf.RoundToInt(breakableContainerLootValue / smallPileLootValue);
				for (int i = 0; i < num; i++)
				{
					Vector2 vector = UnityEngine.Random.insideUnitCircle * enemyLootMaxHorizontalSpawnRandomOffset;
					Vector3 vector2 = new Vector3(vector.x, 1f, vector.y);
					Vector3 linearVelocity = vector2 * enemyLootMaxLinearSpeed;
					Vector3 angularVelocity = UnityEngine.Random.onUnitSphere * enemyLootMaxAngularSpeed;
					MasterSpawnLoot(smallPileEquipmentType, position, Quaternion.identity, 1f, linearVelocity, angularVelocity, lootShouldDespawn: true);
				}
				base.photonView.RpcAll(RpcOnLootSpawn, position);
			}
		}

		[PunRPC]
		private void RpcOnLootSpawn(Vector3 spawnPoint)
		{
			StartCoroutine(EnemyLootSpawnFeedbackCoroutine(spawnPoint));
		}

		private IEnumerator EnemyLootSpawnFeedbackCoroutine(Vector3 spawnPoint)
		{
			yield return new WaitForSeconds(enemyLootSpawnAudioDelay);
			AudioManager.Play2DSFX(enemyLootSpawnAudio);
		}

		private bool TryGetLocalPlayerLoot(out float lootValue)
		{
			if (!IsLocalPlayerPlaying())
			{
				lootValue = 0f;
				return false;
			}
			if (LootIsBackedByValidStat() && gameManager.ScoreManager.TryGetPlayerStat(PhotonNetwork.player, lootStorageStat, out var value))
			{
				lootValue = value;
			}
			else
			{
				lootValue = _localPlayerLoot;
			}
			return true;
		}

		private void ClearLocalPlayerLoot()
		{
			_localPlayerLoot = 0f;
			if (LootIsBackedByValidStat())
			{
				gameManager.ScoreManager.ClearPlayerStat(PhotonNetwork.player, lootStorageStat);
			}
		}

		private void AddLocalPlayerLoot(float deltaLootValue)
		{
			if (IsLocalPlayerPlaying())
			{
				if (LootIsBackedByValidStat())
				{
					gameManager.ScoreManager.AddPlayerStat(PhotonNetwork.player, lootStorageStat, (int)deltaLootValue);
				}
				else
				{
					_localPlayerLoot += deltaLootValue;
				}
			}
		}

		private void AddLootToAllPlayers(LootTool lootTool, float deltaLootValue)
		{
			if (LootIsBackedByValidStat() && lootTool.owner.IsLocal)
			{
				base.photonView.RpcMaster(RpcMasterRequestAddLootAllPlayers, lootTool.owner, lootTool, (int)deltaLootValue);
			}
			else if (IsLocalPlayerPlaying())
			{
				_localPlayerLoot += deltaLootValue;
			}
		}

		private void AddLootSinglePlayer(LootTool lootTool, PhotonPlayer player, float lostLootValue)
		{
			if (player.IsLocal && lootTool.owner == player)
			{
				if (LootIsBackedByValidStat())
				{
					base.photonView.RpcMaster(RpcMasterRequestAddLootSinglePlayer, player, lootTool, (int)lostLootValue);
				}
				else if (IsLocalPlayerPlaying())
				{
					_localPlayerLoot += lostLootValue;
				}
			}
		}

		[PunRPC]
		private void RpcMasterRequestAddLootAllPlayers(PhotonPlayer pickupPlayer, LootTool lootTool, int deltaLootValue)
		{
			if (PhotonNetwork.isMasterClient && (!(lootTool != null) || !lootTool.AlreadyPickedUp) && !gameManager.TeamManager.IsPlayerSpectator(pickupPlayer))
			{
				if (lootTool != null)
				{
					lootTool.MasterSetAlreadyPickedUp();
				}
				if (gameManager.CustomGameSettings.AllowRewards)
				{
					gameManager.ScoreManager.MasterAddPlayerStatForAllActivePlayers(lootStorageStat, deltaLootValue);
				}
			}
		}

		[PunRPC]
		private void RpcMasterRequestAddLootSinglePlayer(PhotonPlayer player, LootTool lootTool, int value)
		{
			if (PhotonNetwork.isMasterClient && (!(lootTool != null) || !lootTool.AlreadyPickedUp) && !gameManager.TeamManager.IsPlayerSpectator(player))
			{
				if (lootTool != null)
				{
					lootTool.MasterSetAlreadyPickedUp();
				}
				if (gameManager.CustomGameSettings.AllowRewards)
				{
					gameManager.ScoreManager.MasterAddPlayerStat(player, lootStorageStat, value);
				}
			}
		}

		private bool LootIsBackedByValidStat()
		{
			return lootStorageType == LootStorageType.GAME_STAT && gameManager != null && lootStorageStat != PlayerStatType.INVALID;
		}

		private bool TryRequestLostLootSpawnInCurrentScene(Vector3 spawnVelocity)
		{
			int currentSceneLocalPlayerLostLootIndex = GetCurrentSceneLocalPlayerLostLootIndex();
			if (currentSceneLocalPlayerLostLootIndex >= 0 && Profiles.LocalProfile != null)
			{
				long arg = Profiles.LocalProfile.Id;
				float value = SessionAllLostLoot[currentSceneLocalPlayerLostLootIndex].Value;
				Vector3 levelLocalDropPosition = SessionAllLostLoot[currentSceneLocalPlayerLostLootIndex].LevelLocalDropPosition;
				Quaternion levelLocalDropRotation = SessionAllLostLoot[currentSceneLocalPlayerLostLootIndex].LevelLocalDropRotation;
				base.photonView.RpcMaster(RpcMasterRequestLostLootSpawn, arg, levelLocalDropPosition, levelLocalDropRotation, value, spawnVelocity);
				return true;
			}
			return false;
		}

		[PunRPC]
		private void RpcMasterRequestLostLootSpawn(long ownerPlayerId, Vector3 position, Quaternion rotation, float lootValue, Vector3 spawnVelocity)
		{
			if (PhotonNetwork.isMasterClient)
			{
				LootTool lootTool = MasterSpawnLoot(lostLootEquipmentType, position, rotation, 1f, spawnVelocity, Vector3.zero, lootShouldDespawn: false);
				if (lootTool != null)
				{
					lootTool.MasterInitializeAsLostLoot(ownerPlayerId, lootValue);
				}
			}
		}

		private void CopyLocalPlayerLostLootForCurrentSceneToCurrentLoot()
		{
			if (TryGetLocalPlayerLostLootValueForCurrentScene(out var lostLootValue))
			{
				AddLocalPlayerLoot(lostLootValue);
				ClearLocalPlayerLostLootForCurrentActivityLevel();
			}
		}

		private bool TryGetLocalPlayerLostLootValueForCurrentScene(out float lostLootValue)
		{
			if (!IsLocalPlayerPlaying())
			{
				lostLootValue = 0f;
				return false;
			}
			GetCurrentSceneData(out var location, out var hasLevelRooms, out var levelRoomIndex);
			int localPlayerLostLootIndexForScene = GetLocalPlayerLostLootIndexForScene(location, hasLevelRooms, levelRoomIndex);
			if (localPlayerLostLootIndexForScene < 0)
			{
				lostLootValue = 0f;
				return false;
			}
			lostLootValue = SessionAllLostLoot[localPlayerLostLootIndexForScene].Value;
			return true;
		}

		private void ClearLocalPlayerLostLootForCurrentActivityLevel()
		{
			int currentRoomSceneLocationLocalPlayerLostLootIndex = GetCurrentRoomSceneLocationLocalPlayerLostLootIndex();
			if (currentRoomSceneLocationLocalPlayerLostLootIndex >= 0)
			{
				SessionAllLostLoot.RemoveAt(currentRoomSceneLocationLocalPlayerLostLootIndex);
			}
		}

		private void SetLocalPlayerLostLootForCurrentScene(float dropValue, Vector3 worldSpaceDropPosition, Quaternion worldSpaceDropRotation)
		{
			if (IsLocalPlayerPlaying())
			{
				GetCurrentSceneData(out var location, out var hasLevelRooms, out var levelRoomIndex);
				LostLootData lostLootData = new LostLootData
				{
					Value = dropValue,
					Location = location,
					HasLevelRooms = hasLevelRooms,
					LevelRoomIndex = levelRoomIndex,
					LevelLocalDropPosition = worldSpaceDropPosition,
					LevelLocalDropRotation = worldSpaceDropRotation
				};
				int localPlayerLostLootIndexForLocation = GetLocalPlayerLostLootIndexForLocation(location);
				if (localPlayerLostLootIndexForLocation >= 0)
				{
					SessionAllLostLoot[localPlayerLostLootIndexForLocation] = lostLootData;
				}
				else
				{
					SessionAllLostLoot.Add(lostLootData);
				}
			}
		}

		private bool GetCurrentRoomSceneLocationHasLostLoot()
		{
			return GetCurrentRoomSceneLocationLocalPlayerLostLootIndex() >= 0;
		}

		private int GetCurrentRoomSceneLocationLocalPlayerLostLootIndex()
		{
			GetCurrentRoomSceneLocation(out var location);
			return GetLocalPlayerLostLootIndexForLocation(location);
		}

		private int GetCurrentSceneLocalPlayerLostLootIndex()
		{
			GetCurrentSceneData(out var location, out var hasLevelRooms, out var levelRoomIndex);
			return GetLocalPlayerLostLootIndexForScene(location, hasLevelRooms, levelRoomIndex);
		}

		private int GetLocalPlayerLostLootIndexForLocation(RoomSceneLocations location)
		{
			for (int i = 0; i < SessionAllLostLoot.Count; i++)
			{
				if (SessionAllLostLoot[i].Location == location)
				{
					return i;
				}
			}
			return -1;
		}

		private int GetLocalPlayerLostLootIndexForScene(RoomSceneLocations location, bool hasLevelRooms, int levelRoomIndex)
		{
			for (int i = 0; i < SessionAllLostLoot.Count; i++)
			{
				if (SessionAllLostLoot[i].Location == location && SessionAllLostLoot[i].HasLevelRooms == hasLevelRooms && (!hasLevelRooms || SessionAllLostLoot[i].LevelRoomIndex == levelRoomIndex))
				{
					return i;
				}
			}
			return -1;
		}

		private bool CurrentLocationHasLevelRooms()
		{
			GetCurrentSceneData(out var _, out var hasLevelRooms, out var _);
			return hasLevelRooms;
		}

		private void GetCurrentRoomSceneLocation(out RoomSceneLocations location)
		{
			GetCurrentSceneData(out location, out var _, out var _);
		}

		private void GetCurrentSceneData(out RoomSceneLocations location, out bool hasLevelRooms, out int levelRoomIndex)
		{
			int index = Mathf.Max(0, SceneManager.sceneCount - 1);
			UnityEngine.SceneManagement.Scene sceneAt = SceneManager.GetSceneAt(index);
			AGRoomSettings.TryGetRoomSceneLocationFromSceneName((!sceneAt.IsValid()) ? null : sceneAt.name, out location, out levelRoomIndex);
			hasLevelRooms = AGRoomSettings.GetRoomSceneLocationSubSceneCount(location) > 0;
		}

		private bool IsLocalPlayerPlaying()
		{
			return gameManager != null && !gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player);
		}

		private void InitializeStorefront()
		{
			RecNet.Storefronts.FetchBalanceAddConfig(currencyType, StorefrontBalanceAddTypes.DirectBalanceWithMultiplier, delegate(string error, StorefrontBalanceAddConfigDTO nullableConfig)
			{
				if (nullableConfig != null)
				{
					serverLootBaseValue = nullableConfig.BaseAward;
					serverMaxLootValueMultiplier = nullableConfig.MaxPartialMultiplier;
				}
			});
		}

		private bool UploadLootToStorefront(float lootValue)
		{
			if (!gameManager.CustomGameSettings.AllowRewards)
			{
				return false;
			}
			float value = lootValue / serverLootBaseValue;
			value = Mathf.Clamp(value, 0f, serverMaxLootValueMultiplier);
			RecNet.Storefronts.GrantBalanceRequest[] balanceAdds = new RecNet.Storefronts.GrantBalanceRequest[1]
			{
				new RecNet.Storefronts.GrantBalanceRequest
				{
					Multiplier = value,
					BalanceAddType = StorefrontBalanceAddTypes.DirectBalanceWithMultiplier
				}
			};
			RecNet.Storefronts.ModifyBalance(currencyType, balanceAdds, delegate
			{
			});
			return true;
		}
	}
}
namespace RecRoom.Activities.Quest
{
	[RequireComponent(typeof(PhotonView))]
	[RequireComponent(typeof(QuestRoomCulling))]
	public class QuestGameplayRoom : QuestRoomBase
	{
		private enum QuestRoomEncounterFinishCondition
		{
			COMPLETE_REQUIRED_ENCOUNTERS,
			OPEN_DOOR
		}

		public enum RoomState
		{
			INACTIVE,
			RUNNING_ENCOUNTERS,
			FINISHED_ENCOUNTERS,
			FINISHED
		}

		[SerializeField]
		private string friendlyName;

		[Header("Required Encounters")]
		[SerializeField]
		private GameEncounter[] requiredEncounters;

		[SerializeField]
		private bool supportsFanfare = true;

		[Header("Randomly Enabled Encounters")]
		[SerializeField]
		private RandomlyEnabledGameEncounterDesc[] randomlyEnabledEncounters;

		[Header("Exit")]
		[SerializeField]
		[FormerlySerializedAs("finishCondition")]
		private QuestRoomEncounterFinishCondition encountersFinishCondition = QuestRoomEncounterFinishCondition.OPEN_DOOR;

		[Header("Tool Cleanup")]
		[SerializeField]
		private bool toolCleanupEnabled;

		private bool _spawnPointsEnabled;

		private SynchronizedStateMachine stateMachine;

		private List<GameEncounter> otherEncounters = new List<GameEncounter>();

		private QuestRoomExitDoor[] doors;

		private UIProjector[] scoreboardProjectors;

		private Coroutine doorTriggerFeedbackCoroutine;

		private bool playedFanfare;

		public GameSpawnPoint[] PlayerSpawnPoints { get; private set; }

		public GiftBoxSpawnPoint[] GiftSpawnPoints { get; private set; }

		protected override bool DisableToolCleanup => !toolCleanupEnabled;

		private bool DoorsLocked
		{
			set
			{
				QuestRoomExitDoor[] array = doors;
				foreach (QuestRoomExitDoor questRoomExitDoor in array)
				{
					questRoomExitDoor.IsLocked = value;
				}
			}
		}

		private bool DoorTriggerActive
		{
			set
			{
				QuestRoomExitDoor[] array = doors;
				foreach (QuestRoomExitDoor questRoomExitDoor in array)
				{
					questRoomExitDoor.TriggerActive = value;
				}
			}
		}

		private bool SpawnPointsEnabled
		{
			get
			{
				return _spawnPointsEnabled;
			}
			set
			{
				_spawnPointsEnabled = value;
				OnSpawnPointEnabledUpdated();
			}
		}

		private bool ScoreboardsActive
		{
			set
			{
				if (scoreboardProjectors != null)
				{
					UIProjector[] array = scoreboardProjectors;
					foreach (UIProjector uIProjector in array)
					{
						uIProjector.enabled = value;
					}
				}
			}
		}

		public RoomState CurrentState => (RoomState)stateMachine.CurrentStateId;

		private bool CanExitRoom => AllRequiredEncountersFinished && !AnyOptionalEncountersRunning;

		private bool AnyRequiredEncountersRunning
		{
			get
			{
				if (requiredEncounters != null)
				{
					for (int i = 0; i < requiredEncounters.Length; i++)
					{
						if (requiredEncounters[i].IsRunning)
						{
							return true;
						}
					}
				}
				return false;
			}
		}

		private bool AllRequiredEncountersFinished
		{
			get
			{
				if (requiredEncounters != null)
				{
					for (int i = 0; i < requiredEncounters.Length; i++)
					{
						if (!requiredEncounters[i].IsFinished)
						{
							return false;
						}
					}
				}
				return true;
			}
		}

		private bool HasRequiredEncounters => requiredEncounters != null && requiredEncounters.Length > 0;

		private bool AnyOptionalEncountersRunning
		{
			get
			{
				for (int i = 0; i < otherEncounters.Count; i++)
				{
					if (otherEncounters[i].IsRunning)
					{
						return true;
					}
				}
				if (randomlyEnabledEncounters != null)
				{
					for (int j = 0; j < randomlyEnabledEncounters.Length; j++)
					{
						if (randomlyEnabledEncounters[j].Encounter.IsRunning)
						{
							return true;
						}
					}
				}
				return false;
			}
		}

		public override void Initialize(QuestManager questManager, int roomIndex)
		{
			base.Initialize(questManager, roomIndex);
			InitializeEncounters();
			InitializeSpawnPoints();
			InitializeDoors();
			InitializeScoreboards();
			InitializeStateMachine(roomIndex);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CleanupDoors();
		}

		private void Update()
		{
			if (stateMachine != null)
			{
				stateMachine.Update();
			}
		}

		public void Activate()
		{
			base.gameObject.SetActive(value: true);
			SpawnPointsEnabled = true;
			if (PhotonNetwork.isMasterClient)
			{
				MasterResetAllRoomTools();
				MasterResetAllRoomTraps();
				MasterActivateAllEncounters();
				stateMachine.EnterState(1);
			}
		}

		public void Deactivate()
		{
			if (PhotonNetwork.isMasterClient)
			{
				stateMachine.EnterState(0);
				MasterDisableAllRoomTools();
				MasterDisableAllRoomTraps();
				MasterDeactivateAllEncounters();
			}
			SpawnPointsEnabled = false;
			base.gameObject.SetActive(value: false);
		}

		public bool IsFinished()
		{
			return stateMachine.CurrentStateId == 3;
		}

		public override void OnLocalPlayerEnter()
		{
			base.OnLocalPlayerEnter();
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, friendlyName, 4f);
		}

		private void InitializeStateMachine(int roomIndex)
		{
			stateMachine = new SynchronizedStateMachine("ROOM" + roomIndex, SetterPermissionMode.MASTER);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterRunningEncountersState, OnExitRunningEncountersState, OnUpdateRunningEncountersState);
			stateMachine.AddState(2, OnEnterFinishedEncounterState, null, null);
			stateMachine.AddState(3, null, null, null);
			stateMachine.Start(this, 0);
		}

		private void OnEnterRunningEncountersState(ushort previousStateId, ushort previousSubStateId)
		{
			playedFanfare = false;
			DoorTriggerActive = false;
			DoorsLocked = true;
			ScoreboardsActive = false;
			RaiseStartRunningEvent();
		}

		private void OnUpdateRunningEncountersState()
		{
			bool flag = (DoorTriggerActive = CanExitRoom);
			ScoreboardsActive = flag;
			if (!playedFanfare && HasRequiredEncounters && flag && supportsFanfare)
			{
				playedFanfare = true;
				AudioManager.MusicMixer.PlayFanfareMusic();
			}
			if (PhotonNetwork.isMasterClient && flag)
			{
				bool flag2 = false;
				switch (encountersFinishCondition)
				{
				case QuestRoomEncounterFinishCondition.OPEN_DOOR:
					flag2 = AllPlayersOnDoorTrigger(base.QuestManager.TeamManager.GetActivePlayers());
					break;
				case QuestRoomEncounterFinishCondition.COMPLETE_REQUIRED_ENCOUNTERS:
					flag2 = true;
					break;
				}
				if (flag2)
				{
					stateMachine.EnterState(2);
				}
			}
		}

		private void OnExitRunningEncountersState(ushort nextStateId, ushort nextSubStateId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterDeactivateNotYetTriggeredEncounters();
			}
			StopDoorTriggerFeedbackCoroutine();
			RaiseStopRunningEvent();
		}

		private void OnEnterFinishedEncounterState(ushort previousStateId, ushort previousSubStateId)
		{
			DoorsLocked = false;
			DoorTriggerActive = false;
			ScoreboardsActive = true;
			if (encountersFinishCondition == QuestRoomEncounterFinishCondition.COMPLETE_REQUIRED_ENCOUNTERS && PhotonNetwork.isMasterClient)
			{
				stateMachine.EnterState(3);
			}
		}

		private void InitializeEncounters()
		{
			GameEncounter[] encounters = GetComponentsInChildren<GameEncounter>();
			if (encounters == null)
			{
				return;
			}
			for (int i = 0; i < encounters.Length; i++)
			{
				if ((requiredEncounters == null || !requiredEncounters.Contains(encounters[i])) && (randomlyEnabledEncounters == null || Array.FindIndex(randomlyEnabledEncounters, (RandomlyEnabledGameEncounterDesc rand) => rand.Encounter == encounters[i]) < 0))
				{
					otherEncounters.Add(encounters[i]);
				}
				encounters[i].Initialize();
			}
		}

		private void MasterActivateAllEncounters()
		{
			if (requiredEncounters != null)
			{
				for (int i = 0; i < requiredEncounters.Length; i++)
				{
					requiredEncounters[i].MasterActivate();
				}
			}
			for (int j = 0; j < otherEncounters.Count; j++)
			{
				otherEncounters[j].MasterActivate();
			}
			if (randomlyEnabledEncounters == null)
			{
				return;
			}
			for (int k = 0; k < randomlyEnabledEncounters.Length; k++)
			{
				if (UnityExtensions.GetRandomResult(randomlyEnabledEncounters[k].EnabledChance))
				{
					randomlyEnabledEncounters[k].Encounter.MasterActivate();
				}
			}
		}

		private void MasterDeactivateNotYetTriggeredEncounters()
		{
			if (requiredEncounters != null)
			{
				for (int i = 0; i < requiredEncounters.Length; i++)
				{
					if (requiredEncounters[i].IsWaitingForTrigger)
					{
						requiredEncounters[i].MasterDeactivate();
					}
				}
			}
			for (int j = 0; j < otherEncounters.Count; j++)
			{
				if (otherEncounters[j].IsWaitingForTrigger)
				{
					otherEncounters[j].MasterDeactivate();
				}
			}
			if (randomlyEnabledEncounters == null)
			{
				return;
			}
			for (int k = 0; k < randomlyEnabledEncounters.Length; k++)
			{
				if (randomlyEnabledEncounters[k].Encounter.IsWaitingForTrigger)
				{
					randomlyEnabledEncounters[k].Encounter.MasterDeactivate();
				}
			}
		}

		private void MasterDeactivateAllEncounters()
		{
			if (requiredEncounters != null)
			{
				for (int i = 0; i < requiredEncounters.Length; i++)
				{
					requiredEncounters[i].MasterDeactivate();
				}
			}
			for (int j = 0; j < otherEncounters.Count; j++)
			{
				otherEncounters[j].MasterDeactivate();
			}
			if (randomlyEnabledEncounters != null)
			{
				for (int k = 0; k < randomlyEnabledEncounters.Length; k++)
				{
					randomlyEnabledEncounters[k].Encounter.MasterDeactivate();
				}
			}
		}

		private void InitializeSpawnPoints()
		{
			PlayerSpawnPoints = GetComponentsInChildren<GameSpawnPoint>(includeInactive: true);
			if (PlayerSpawnPoints == null || PlayerSpawnPoints.Length == 0)
			{
				UnityEngine.Debug.LogError("Quest Room " + base.name + " is missing player spawn points.");
				return;
			}
			GiftSpawnPoints = GetComponentsInChildren<GiftBoxSpawnPoint>(includeInactive: true);
			OnSpawnPointEnabledUpdated();
		}

		private void OnSpawnPointEnabledUpdated()
		{
			if (PlayerSpawnPoints != null)
			{
				GameSpawnPoint[] playerSpawnPoints = PlayerSpawnPoints;
				foreach (GameSpawnPoint gameSpawnPoint in playerSpawnPoints)
				{
					gameSpawnPoint.SpawnPointEnabled = SpawnPointsEnabled;
				}
			}
		}

		private void InitializeDoors()
		{
			doors = base.transform.GetComponentsInChildren<QuestRoomExitDoor>(includeInactive: true);
			if (doors != null && doors.Length > 0)
			{
				QuestRoomExitDoor[] array = doors;
				foreach (QuestRoomExitDoor questRoomExitDoor in array)
				{
					questRoomExitDoor.LocalPlayerUseDoorPortalEvent += OnLocalPlayerUseDoorPortal;
					questRoomExitDoor.LocalPlayerStopOnDoorTriggerEvent += OnLocalPlayerStopOnDoorUnlockTrigger;
				}
				DoorsLocked = true;
			}
		}

		private void CleanupDoors()
		{
			if (doors != null)
			{
				QuestRoomExitDoor[] array = doors;
				foreach (QuestRoomExitDoor questRoomExitDoor in array)
				{
					questRoomExitDoor.LocalPlayerUseDoorPortalEvent -= OnLocalPlayerUseDoorPortal;
					questRoomExitDoor.LocalPlayerStopOnDoorTriggerEvent -= OnLocalPlayerStopOnDoorUnlockTrigger;
				}
			}
		}

		private void OnLocalPlayerUseDoorPortal()
		{
			if (stateMachine.CurrentStateId == 2 && !base.QuestManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				base.photonView.RpcMaster(RpcRequestMasterFinishRoom);
			}
		}

		private bool AllPlayersOnDoorTrigger(IEnumerable<PhotonPlayer> players)
		{
			bool result = false;
			QuestRoomExitDoor[] array = doors;
			foreach (QuestRoomExitDoor questRoomExitDoor in array)
			{
				if (questRoomExitDoor.AllPlayersOnTrigger(players))
				{
					result = true;
					break;
				}
			}
			return result;
		}

		[PunRPC]
		private void RpcRequestMasterFinishRoom()
		{
			if (PhotonNetwork.isMasterClient && stateMachine.CurrentStateId == 2)
			{
				stateMachine.EnterState(3);
			}
		}

		private void InitializeScoreboards()
		{
			scoreboardProjectors = GetComponentsInChildren<UIProjector>();
		}

		private void OnLocalPlayerStopOnDoorUnlockTrigger()
		{
			if (stateMachine.CurrentStateId == 1)
			{
				StartStopOnDoorUnlockTriggerFeedbackCoroutine(0.25f);
			}
		}

		private void StartStopOnDoorUnlockTriggerFeedbackCoroutine(float delay)
		{
			StopDoorTriggerFeedbackCoroutine();
			doorTriggerFeedbackCoroutine = StartCoroutine(PlayDoorTriggerFeedbackCoroutine(delay));
		}

		private void StopDoorTriggerFeedbackCoroutine()
		{
			if (doorTriggerFeedbackCoroutine != null)
			{
				StopCoroutine(doorTriggerFeedbackCoroutine);
				doorTriggerFeedbackCoroutine = null;
			}
		}

		private IEnumerator PlayDoorTriggerFeedbackCoroutine(float delay)
		{
			yield return new WaitForSeconds(delay);
			if (AnyRequiredEncountersRunning || AnyOptionalEncountersRunning)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "There Are Still Enemies Out There!", null, 3f);
			}
			else if (!AllRequiredEncountersFinished)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Continue Exploring To Unlock This Door!", null, 3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Gather All Players To Unlock The Next Room!", null, 3f);
			}
		}

		private void TestForTeamSpawnPointExistence()
		{
			bool flag = false;
			int num = 4;
			bool[] array = new bool[num];
			GameSpawnPoint[] playerSpawnPoints = PlayerSpawnPoints;
			foreach (GameSpawnPoint gameSpawnPoint in playerSpawnPoints)
			{
				int gameTeamPlayerIndex = (int)gameSpawnPoint.GameTeamPlayerIndex;
				if (gameTeamPlayerIndex >= 0 && gameTeamPlayerIndex < array.Length)
				{
					array[gameTeamPlayerIndex] = true;
				}
				flag |= gameSpawnPoint.TestsForOverlap;
			}
			bool flag2 = true;
			for (int j = 0; j < array.Length; j++)
			{
				if (!array[j])
				{
					flag2 = false;
					break;
				}
			}
			if (!flag2)
			{
				UnityEngine.Debug.LogError("Quest Room " + base.name + " must have spawn points set for all " + num + " player indices.");
			}
			if (flag)
			{
				UnityEngine.Debug.LogError("Quest Room " + base.name + " must not have spawn points that test for overlap");
			}
		}
	}
	public class QuestGearManager : Photon.MonoBehaviour
	{
		private const float CHEST_LOOT_SPAWN_ITEM_DELAY = 0.05f;

		[Header("Quest")]
		[SerializeField]
		private QuestCampaign campaign;

		private LootTable<GameObject> gearTable = new LootTable<GameObject>();

		private EquipPermissions hipEquipSlotPermissions;

		private EquipPermissions shoulderEquipSlotPermissions;

		private SpawnableToolType[] hipSlotPermissionExceptions;

		private SpawnableToolType[] shoulderSlotPermissionExceptions;

		private QuestGear customGearBehavior;

		public static QuestGearManager Instance { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			if (Instance == null)
			{
				Instance = this;
			}
			InitializeLootTables();
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnedEquipmentInstantiatedEvent += OnEquipmentInstantiated;
				((QuestManager)NetworkedSingletonMonoBehaviour<GameManager>.Instance).GameplayRoomLoaded += OnRoomLoaded;
			}
			customGearBehavior = QuestGearSettings.GetGearCustomBehavior(campaign);
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Combine(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
		}

		private void InitializeLootTables()
		{
			QuestGearEntry[] questGearTypes = QuestGearSettings.GetQuestGearTypes(campaign);
			if (questGearTypes != null)
			{
				QuestGearEntry[] array = questGearTypes;
				for (int i = 0; i < array.Length; i++)
				{
					QuestGearEntry questGearEntry = array[i];
					gearTable.AddLoot(questGearEntry.gearPrefab, questGearEntry.dropWeight);
				}
			}
		}

		protected override void OnDestroy()
		{
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Remove(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
			if (Instance == this)
			{
				Instance = null;
			}
			base.OnDestroy();
		}

		private void OnChestOpen(EquipmentSpawnerChest chest)
		{
			StartCoroutine(SpawnChestLootCoroutine(chest));
		}

		private IEnumerator SpawnChestLootCoroutine(EquipmentSpawnerChest chest)
		{
			float deltaArcAngle = 0.2f;
			int[] itemsToSpawnRange = QuestGearSettings.GetNumberOfItemsToDropRange(campaign);
			int numSpawns = UnityEngine.Random.Range(itemsToSpawnRange[0], itemsToSpawnRange[1] + 1);
			for (int i = 0; i < numSpawns; i++)
			{
				chest.GetEquipmentSpawnPhysics(deltaArcAngle * (float)i, out var position, out var orientation, out var linearVelocity, out var angularVelocity);
				MasterTrySpawnGear(position, orientation, 1f, linearVelocity, angularVelocity);
				yield return new WaitForSeconds(0.05f);
			}
		}

		private bool MasterTrySpawnGear(Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return false;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null)
			{
				return false;
			}
			GameObject randomLoot = gearTable.GetRandomLoot();
			if (randomLoot == null)
			{
				return false;
			}
			return TrySpawnGear(randomLoot, spawnPoint, spawnOrientation, spawnScale, linearVelocity, angularVelocity);
		}

		private bool TrySpawnGear(GameObject gearPrefab, Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			SpawnableTool component = gearPrefab.GetComponent<SpawnableTool>();
			if (component != null)
			{
				Tool tool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(component.Type, spawnPoint, spawnOrientation, spawnScale, -1, suppressAnimateInParticles: true, spawnIgnoringDynamicPhysics: true, suppressCleanup: true);
				if (tool != null && tool.RigidbodyEx != null)
				{
					tool.RigidbodyEx.velocity = linearVelocity;
					tool.RigidbodyEx.angularVelocity = angularVelocity;
				}
				return true;
			}
			return false;
		}

		private void OnEquipmentInstantiated(SpawnableTool spawnedTool)
		{
			if (spawnedTool != null)
			{
				AddCustomGearBehaviorToTool(spawnedTool.Tool);
			}
		}

		private void OnRoomLoaded(QuestGameplayRoom loadedRoom)
		{
			foreach (Tool tool in loadedRoom.Tools)
			{
				AddCustomGearBehaviorToTool(tool);
			}
		}

		private void AddCustomGearBehaviorToTool(Tool tool)
		{
			if (tool != null && customGearBehavior != null)
			{
				tool.gameObject.AddComponent(customGearBehavior.GetType());
			}
		}
	}
