		protected override void Awake()
		{
			base.Awake();
			if (customInGameRole.Overrides)
			{
				PlayerGameRoleManager.Instance.AddInGameRoleDefinition(customInGameRole.Value, this, RoleMapPriority.SceneManager);
			}
			RecRoomSceneManager.DeferInitialization();
			respawnsPlayersOnGameStart = false;
			supportsGameOverGiftGeneration = false;
			hasCustomGameOverFeedback = true;
			hasCustomResultsSubStateDuration = hasCustomPostGameDuration;
			if (hasCustomPostGameDuration)
			{
				customResultsSubStateDuration = customPostGameDuration;
			}
			_defaultRoomIndex = new SynchronizedField<int>(this, "DRI", 0, SetterPermissionMode.MASTER, OnDefaultRoomIndexChanged);
			_defaultCampaignStoryState = new SynchronizedField<int>(this, "DSS", 0, SetterPermissionMode.MASTER, OnDefaultCampaignStoryStateChanged);
			_currentCampaignStoryState = new SynchronizedField<int>(this, "SS", 0, SetterPermissionMode.MASTER, OnStoryStateChanged);
			_currentRoomStoryState = new SynchronizedField<int>(this, "RSS", 0, SetterPermissionMode.MASTER, OnStoryStateChanged);
			masterQuestStateTimer = new SynchronizedTimer(this, "QUEST_TIMER", SetterPermissionMode.MASTER);
			base.CombatManager.EnteringCombatEvent += OnEnterCombat;
			base.CombatManager.ExitingCombatEvent += OnExitCombat;
			base.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
			base.CombatManager.PlayerRevivePlayerEvent += OnPlayerRevive;
			base.CombatManager.EnemyKilledPlayerEvent += OnEnemyKilledPlayer;
			base.CombatManager.MiscKilledPlayerEvent += OnMiscKilledPlayer;
			base.CombatManager.PlayerKilledEnemyEvent += OnPlayerKilledEnemy;
			PointsDropper.PointsDropEvent += RequestPointsDrop;
			if (usesCollectiblesForPoints)
			{
				if (collectiblePrefab == null)
				{
					UnityEngine.Debug.LogError("Quest Manager uses collectibles for points and the collectible prefab is null.");
				}
				else
				{
					Collectible.CollectedEvent += OnCollectibleCollected;
					Collectible.PreAllocateCollectibles(collectiblePrefab);
				}
			}
			allWeapons = UnityEngine.Object.FindObjectsOfType<Weapon>();
			allBreakableObjects = UnityEngine.Object.FindObjectsOfType<BreakableObject>();
		}

		protected override void Start()
		{
			OnDefaultCampaignStoryStateChanged();
			base.Start();
			PlayerGameRoleManager.Instance.UpdatePredefinedRoles(GameRoleSettings.PredefinedGameRoles);
		}

		protected override void OnDestroy()
		{
			if (currentGameplayRoom != null)
			{
				currentGameplayRoom.OnLocalPlayerExit();
			}
			base.OnDestroy();
			if (PlayerGameRoleManager.Instance != null)
			{
				PlayerGameRoleManager.Instance.RemoveInGameRoleDefition(this);
				PlayerGameRoleManager.Instance.UpdatePredefinedRoles();
			}
			PointsDropper.PointsDropEvent -= RequestPointsDrop;
			Collectible.CollectedEvent -= OnCollectibleCollected;
			Player.LocalPlayerSpawnEvent -= new Action(EnterLocalQuestRoom);
			if (base.CombatManager != null)
			{
				base.CombatManager.EnteringCombatEvent -= OnEnterCombat;
				base.CombatManager.ExitingCombatEvent -= OnExitCombat;
				base.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilledPlayer;
				base.CombatManager.PlayerRevivePlayerEvent -= OnPlayerRevive;
				base.CombatManager.EnemyKilledPlayerEvent -= OnEnemyKilledPlayer;
				base.CombatManager.MiscKilledPlayerEvent -= OnMiscKilledPlayer;
				base.CombatManager.PlayerKilledEnemyEvent -= OnPlayerKilledEnemy;
			}
		}

		protected override void Update()
		{
			base.Update();
			questStateMachine.Update();
			masterQuestStateTimer.UpdateCallbacks();
		}

		protected override void OnGameStart()
		{
			base.OnGameStart();
			gameCanStillBeWon = true;
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			foreach (PhotonPlayer activePlayer in base.TeamManager.GetActivePlayers())
			{
				base.CombatManager.MasterResetPlayerHealth(activePlayer);
			}
			base.photonView.RpcAll(RpcOnMultipleHealthChanges);
			questStateMachine.EnterState(1);
		}

		[PunRPC]
		private void RpcOnMultipleHealthChanges()
		{
			foreach (PhotonPlayer activePlayer in base.TeamManager.GetActivePlayers())
			{
				OnPlayerHealthChanged(activePlayer, HealthChangeType.Initialize);
			}
		}

		protected override void OnGameEnd()
		{
			base.OnGameEnd();
			Collectible.ReturnAllCollectibles();
			if (PhotonNetwork.isMasterClient)
			{
				questStateMachine.EnterState(0);
			}
		}

		protected override void InitializeSceneOnLoad()
		{
			base.InitializeSceneOnLoad();
			for (int i = 0; i < allWeapons.Length; i++)
			{
				allWeapons[i].Tool.KinematicOnReset = true;
			}
			InitializeRooms();
			questStateMachine = new SynchronizedStateMachine("QUEST", SetterPermissionMode.MASTER);
			questStateMachine.AddState(0, null, null, null);
			questStateMachine.AddState(1, OnEnterInitialLoadState, null, OnUpdateInitialLoadState);
			questStateMachine.AddState(4, OnEnterWinState, OnExitWinState, OnUpdateWinState);
			questStateMachine.AddState(3, null, null, null);
			questStateMachine.AddState(3, 0, OnEnterLoseSubState, null, OnUpdateLoseSubState);
			questStateMachine.AddState(3, 1, OnEnterUnloadingFinalRoomSubState, OnExitUnloadingFinalRoomSubState, OnUpdateUnloadingFinalRoomSubState);
			questStateMachine.AddState(2, OnEnterRunningState, OnExitRunningState, null);
			for (int j = 0; j < totalRoomCount; j++)
			{
				questStateMachine.AddState(2, GetRoomRunningSubStateId(j), OnEnterRunningRoomSubState, null, OnUpdateRunningRoomSubState);
				questStateMachine.AddState(2, GetRoomUnloadingSubStateId(j), OnEnterUnloadingRoomSubState, OnExitUnloadingRoomSubState, OnUpdateUnloadingRoomSubState);
			}
			questStateMachine.Start(this, 0);
			Player.LocalPlayerSpawnEvent += new Action(EnterLocalQuestRoom);
			if (Player.LocalPlayerExists)
			{
				EnterLocalQuestRoom();
			}
			RecRoomSceneManager.FinishInitialization();
		}

		protected override void InitializeSceneOnPreGame()
		{
			base.InitializeSceneOnPreGame();
			if (PhotonNetwork.isMasterClient)
			{
				questStateMachine.EnterState(0);
			}
		}

		protected override int GetEloGameScore(PhotonPlayer photonPlayer)
		{
			int value = 0;
			base.ScoreManager.TryGetPlayerStat(photonPlayer, PlayerStatType.STAT_1, out value);
			return value;
		}

		private void OnDefaultRoomIndexChanged()
		{
			if (CanContinue && IsQuestRunning && QuestManager.CheckpointReachedEvent != null)
			{
				QuestManager.CheckpointReachedEvent();
			}
		}

		private void OnPlayerHealthChanged(PhotonPlayer player, HealthChangeType healthChangeType, Enemy enemyDeathAttacker = null, PhotonPlayer friendlyFireDeathAttacker = null)
		{
			if (PhotonNetwork.isMasterClient && IsQuestRunning)
			{
				if (base.CombatManager.AllActivePlayersAreDead)
				{
					questStateMachine.EnterState(3, 0);
				}
				else if (base.CombatManager.GetPlayerHealth(player) <= 0)
				{
					EnemyType arg = ((!(enemyDeathAttacker != null)) ? EnemyType.INVALID : enemyDeathAttacker.EnemyType);
					base.photonView.RpcAll(RpcOnPlayerDown, player, healthChangeType, arg);
					PenalizePlayer(player, healthChangeType, friendlyFireDeathAttacker);
				}
			}
		}

		public void PenalizePlayer(PhotonPlayer player, HealthChangeType healthChangeType, PhotonPlayer friendlyFireDeathAttacker = null)
		{
			if (healthChangeType != HealthChangeType.FriendlyFire)
			{
				int num = ((healthChangeType != HealthChangeType.Trap) ? deathPointsPenalty : Mathf.RoundToInt((float)deathPointsPenalty * deathPenaltyTrapMultiplier));
				MasterAddPlayerPointsValue(player, -num);
				if (addPointsToLootStat != PlayerStatType.INVALID)
				{
					int value = 0;
					base.ScoreManager.TryGetPlayerStat(player, addPointsToLootStat, out value);
					base.ScoreManager.AddPlayerStat(player, addPointsToLootStat, -Mathf.Min(value, num));
				}
			}
			else if (friendlyFireDeathAttacker != null)
			{
				Vector3 collectPosition = player.ToPlayer().Head.transform.position + Vector3.up * 0.25f;
				RequestPointsCollect(collectPosition, new int[1] { friendlyFireDeathAttacker.ID }, -friendlyFirePointsPenalty, PointDropType.NORMAL, isCollectible: false);
				if (addPointsToLootStat != PlayerStatType.INVALID)
				{
					int value2 = 0;
					base.ScoreManager.TryGetPlayerStat(friendlyFireDeathAttacker, addPointsToLootStat, out value2);
					base.ScoreManager.AddPlayerStat(friendlyFireDeathAttacker, addPointsToLootStat, -Mathf.Min(value2, friendlyFirePointsPenalty));
				}
			}
		}

		private void OnPlayerRevive(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 position)
		{
			OnPlayerHealthChanged(revivedPlayer, HealthChangeType.Revive);
			AudioManager.Play3DSFX(playerReviveSFX, position);
			PooledParticle.TryPlayPrefab(reviveVFXPrefab, position);
			if (revivedPlayer.IsLocal)
			{
				if (lastLocalDeathNotificationToken != null)
				{
					lastLocalDeathNotificationToken.Dispose();
					lastLocalDeathNotificationToken = null;
				}
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You've been revived by " + revivingPlayer.NickName + "!", 2f);
			}
			else if (revivingPlayer.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You revived " + revivedPlayer.NickName + "!", 2f);
				Player.LocalPlayer.PlayerEvents.QuestFriendRevive(revivedPlayer);
			}
		}

		private void OnPlayerKilledEnemy(PhotonPlayer attacker, Weapon attackerWeapon, Enemy defender, Vector3 point)
		{
			if (attacker.IsLocal && defender != null && Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.QuestEnemyKill(defender);
				if (attackerWeapon != null)
				{
					ChallengeEvents.EliminatedAI(new ChallengeEvents.ElminatedAIEventData(attackerWeapon.Tool, defender));
				}
			}
		}

		private void OnEnemyKilledPlayer(Enemy attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			PlayPlayerHitFx(defender, impactPoint);
			OnPlayerHealthChanged(defender, HealthChangeType.Enemy, attacker);
		}

		private void OnMiscKilledPlayer(PhotonPlayer defender, Player.BodyPart defenderImpactBosyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			PooledParticle.TryPlayPrefab(playerDamagedVFXPrefab, impactPoint);
			OnPlayerHealthChanged(defender, HealthChangeType.Trap);
		}

		private bool IsValidOutOfBoundsHitPlayer(PhotonPlayer hitPlayer)
		{
			if (!IsQuestRunning)
			{
				return false;
			}
			if (base.TeamManager.IsPlayerSpectator(hitPlayer))
			{
				return false;
			}
			return true;
		}

		[PunRPC]
		private void RpcOnPlayerDown(PhotonPlayer downedPlayer, HealthChangeType healthChangeType, EnemyType enemyDeathAttackerType)
		{
			string text = null;
			if (healthChangeType == HealthChangeType.Enemy)
			{
				text = EnemySettings.GetEnemyDamageFriendlyNameString(enemyDeathAttackerType);
			}
			if (downedPlayer.IsLocal && healthChangeType != HealthChangeType.FriendlyFire)
			{
				PlayDeathPenaltyNotification(healthChangeType, text);
				return;
			}
			AudioManager.Play2DSFX(remotePlayerOutSFX);
			string text2 = null;
			text2 = (string.IsNullOrEmpty(text) ? (downedPlayer.NickName + " is Down!") : (downedPlayer.NickName + " Got " + text + "!"));
			string subtitleText = "High five them to revive.";
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, text2, subtitleText, 3f);
		}

		public void PlayDeathPenaltyNotification(HealthChangeType healthChangeType, string enemyDamageFriendlyName, string customTitle = null)
		{
			AudioManager.Play2DSFX(localPlayerOutSFX);
			string titleText = ((!string.IsNullOrEmpty(customTitle)) ? customTitle : "You're Down!");
			int num = ((healthChangeType != HealthChangeType.Trap) ? deathPointsPenalty : Mathf.RoundToInt((float)deathPointsPenalty * deathPenaltyTrapMultiplier));
			string subtitleText = null;
			if (!string.IsNullOrEmpty(enemyDamageFriendlyName))
			{
				subtitleText = "You Got " + enemyDamageFriendlyName + "!";
			}
			else if (addPointsToLootStat != PlayerStatType.INVALID)
			{
				StatMetadata[] stats = base.CurrentMode.ScoreSettings.Stats;
				for (int i = 0; i < stats.Length; i++)
				{
					StatMetadata statMetadata = stats[i];
					if (statMetadata.StatType == addPointsToLootStat)
					{
						subtitleText = " -" + num + " " + statMetadata.Name;
						break;
					}
				}
			}
			else if (base.CurrentMode.ScoreSettings.HasScore)
			{
				subtitleText = " -" + num + " " + base.CurrentMode.ScoreSettings.ScoreName;
			}
			lastLocalDeathNotificationToken = SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, titleText, subtitleText, 5f);
		}

		public void PlayPlayerHitFx(PhotonPlayer hitPlayer, Vector3 impactPoint)
		{
			if (hitPlayer.IsLocal && SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				Vector3 closestPointInFieldOfView = SingletonMonoBehaviour<CameraRig>.Instance.GetClosestPointInFieldOfView(impactPoint);
				Vector3 normalized = (closestPointInFieldOfView - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position).normalized;
				Quaternion rotation = Quaternion.LookRotation(normalized);
				PooledParticle.TryPlayPrefab(playerDamagedVFXPrefab, closestPointInFieldOfView, rotation);
			}
			else
			{
				PooledParticle.TryPlayPrefab(playerDamagedVFXPrefab, impactPoint);
			}
		}

		private void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			HealthChangeType healthChangeType = HealthChangeType.FriendlyFire;
			OnPlayerHealthChanged(defender, healthChangeType, null, attacker);
			Vector3 vector = 0.35f * Vector3.up;
			WorldSpaceNotification.PlayNext("Friendly Fire!", 3f, null, followPlayer: false, defender.ToPlayer().Head.transform.position + vector);
			if (defender.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Friendly Fire! " + attacker.NickName + " hit you.", 3f);
			}
			else if (attacker.IsLocal)
			{
				PooledParticle.TryPlayPrefab(playerDamagedVFXPrefab, impactPoint);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Oops! You Hit " + defender.NickName, 3f);
			}
		}

		private void MasterAddPlayerPointsValue(PhotonPlayer player, int deltaPoints)
		{
			if (PhotonNetwork.isMasterClient && IsQuestRunning && player != null && !base.TeamManager.IsPlayerSpectator(player))
			{
				base.ScoreManager.TryGetPlayerStat(player, PlayerStatType.STAT_1, out var value);
				int num = ((deltaPoints <= 0 && value < Mathf.Abs(deltaPoints)) ? (-value) : deltaPoints);
				base.ScoreManager.MasterAddPlayerStat(player, PlayerStatType.STAT_1, num);
				GameTeam playerTeam = base.TeamManager.GetPlayerTeam(player);
				base.ScoreManager.AddScore(playerTeam, num);
			}
		}

		private void RequestPointsDrop(PointsDropper dropper, Vector3 dropPosition, PhotonPlayer[] rewardedPlayers, int minValue, int maxValue, PointDropType pointsType, bool dontAddToCombatScore = false)
		{
			if (rewardedPlayers == null || rewardedPlayers.Length == 0)
			{
				rewardedPlayers = base.TeamManager.GetOtherPlayers(GameTeam.ANY);
			}
			if (rewardedPlayers == null)
			{
				return;
			}
			int pointsValue = GetPointsValue(minValue, maxValue);
			int value = Mathf.RoundToInt(pointsValue / rewardedPlayers.Length);
			if (usesCollectiblesForPoints)
			{
				TrySpawnCollectibles(dropPosition, rewardedPlayers, value, pointsType);
			}
			else if (dropper == null || dropper.hasAuthority)
			{
				int[] array = new int[rewardedPlayers.Length];
				for (int i = 0; i < rewardedPlayers.Length; i++)
				{
					array[i] = rewardedPlayers[i].ID;
				}
				RequestPointsCollect(dropPosition, array, value, pointsType, isCollectible: false, pointsValue, dontAddToCombatScore);
			}
		}

		private void RequestPointsCollect(Vector3 collectPosition, int[] rewardedPlayerIds, int value, PointDropType pointsType, bool isCollectible, int undividedValue = 0, bool dontAddToCombatScore = false)
		{
			base.photonView.RpcMaster(RpcMasterRequestPointsCollect, collectPosition, rewardedPlayerIds, value, pointsType, isCollectible, undividedValue, dontAddToCombatScore);
		}

		[PunRPC]
		private void RpcMasterRequestPointsCollect(Vector3 dropPosition, int[] rewardedPlayerIds, int pointValue, PointDropType pointsType, bool isCollectible, int undividedValue, bool dontAddToCombatScore)
		{
			if (!PhotonNetwork.isMasterClient || !IsQuestRunning || rewardedPlayerIds == null || rewardedPlayerIds.Length <= 0)
			{
				return;
			}
			if (addPointsToLootStat != PlayerStatType.INVALID && everyoneEarnsUndividedLoot && pointValue >= 0)
			{
				base.ScoreManager.MasterAddPlayerStatForAllActivePlayers(addPointsToLootStat, undividedValue);
			}
			if (!dontAddToCombatScore)
			{
				foreach (int iD in rewardedPlayerIds)
				{
					PhotonPlayer photonPlayer = PhotonPlayer.Find(iD);
					if (photonPlayer != null)
					{
						MasterAddPlayerPointsValue(photonPlayer, pointValue);
					}
				}
			}
			if (!isCollectible && playPointsFXandNotifications)
			{
				base.photonView.RpcAll(RpcOnPointsCollect, dropPosition, rewardedPlayerIds, pointValue, pointsType, undividedValue);
			}
		}

		[PunRPC]
		private void RpcOnPointsCollect(Vector3 dropPosition, int[] rewardedPlayerIds, int value, PointDropType pointsType, int undividedValue)
		{
			if (rewardedPlayerIds.Contains(PhotonNetwork.player.ID) || (everyoneEarnsUndividedLoot && undividedValue != 0))
			{
				if (everyoneEarnsUndividedLoot && undividedValue != 0)
				{
					value = undividedValue;
				}
				WorldSpaceNotification worldSpaceNotification = null;
				switch (pointsType)
				{
				case PointDropType.NORMAL:
					AudioManager.Play3DSFX(smallPointsSpawnSFX, dropPosition);
					PooledParticle.TryPlayPrefab(smallPointsSpawnVFXPrefab, dropPosition, Quaternion.LookRotation(Vector3.up));
					worldSpaceNotification = WorldSpaceNotification.PlayNext(((value <= 0) ? string.Empty : "+") + value, 1.5f, null, followPlayer: false, dropPosition);
					break;
				case PointDropType.LARGE:
					AudioManager.Play3DSFX(largePointsSpawnSFX, dropPosition);
					PooledParticle.TryPlayPrefab(largePointsSpawnVFXPrefab, dropPosition, Quaternion.LookRotation(Vector3.up));
					worldSpaceNotification = WorldSpaceNotification.PlayNext(((value <= 0) ? string.Empty : "+") + value, 1.5f, null, followPlayer: false, dropPosition);
					break;
				}
				if (worldSpaceNotification != null && hasCustomPointDropColor)
				{
					worldSpaceNotification.Color = customPointDropColor;
				}
			}
		}

		private int GetPointsValue(int minValue, int maxValue)
		{
			UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
			return UnityEngine.Random.Range(minValue, maxValue + 1);
		}

		private void OnEnterCombat()
		{
			if (IsQuestRunning)
			{
				AudioManager.MusicMixer.PlayActionMusic();
				AudioManager.MusicMixer.SetGameplayMusicFadeInTime(0.5f);
			}
		}

		private void OnExitCombat()
		{
			AudioManager.MusicMixer.StopActionMusic();
		}

		private bool TrySpawnCollectibles(Vector3 dropPosition, PhotonPlayer[] rewardedPlayers, int value, PointDropType pointsType)
		{
			if (!usesCollectiblesForPoints || collectiblePrefab == null || !Player.LocalPlayerExists || !rewardedPlayers.Contains(PhotonNetwork.player))
			{
				return false;
			}
			Collectible.SpawnCollectibleGroup(collectiblePrefab, value, collectibleValue, dropPosition, Player.LocalPlayer, pointsType == PointDropType.LARGE);
			return true;
		}

		private void OnCollectibleCollected(Collectible collectible)
		{
			if (localPhotonPlayerIdArray == null)
			{
				localPhotonPlayerIdArray = new int[1] { PhotonNetwork.player.ID };
			}
			RequestPointsCollect(collectible.transform.position, localPhotonPlayerIdArray, collectible.Value, PointDropType.NORMAL, isCollectible: true, collectible.Value);
		}

		private void OnEnterInitialLoadState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
			{
				Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: false, dropTools: false);
			}
			if (PhotonNetwork.isMasterClient)
			{
				masterQuestStateTimer.StartTimer(Player.DespawnDuration);
			}
		}

		private void OnUpdateInitialLoadState()
		{
			if (PhotonNetwork.isMasterClient && masterQuestStateTimer.TimerOver)
			{
				int initialRoomIndex = GetInitialRoomIndex();
				questStateMachine.EnterState(2, GetRoomRunningSubStateId(initialRoomIndex));
			}
		}

		private void OnEnterRunningState(ushort previousStateId, ushort previousSubStateId)
		{
			base.CombatManager.FriendlyFireEnabled = true;
			UnloadCurrentGameplayRoom();
			if (PhotonNetwork.isMasterClient)
			{
				CurrentCampaignStoryState = DefaultCampaignStoryState;
			}
		}

		private void OnExitRunningState(ushort nextStateId, ushort nextSubStateId)
		{
			OnExitCombat();
			base.CombatManager.FriendlyFireEnabled = false;
		}

		private void OnEnterRunningRoomSubState(ushort previousStateId, ushort previousSubStateId)
		{
			LoadGameplayRoom(GetCurrentGameplayRoomIndex());
			if (PhotonNetwork.isMasterClient)
			{
				CurrentRoomStoryState = StoryState.STATE_0;
			}
		}

		private void OnUpdateRunningRoomSubState()
		{
			if (currentGameplayRoom == null)
			{
				return;
			}
			if (base.CombatManager.AllActivePlayersAreDead)
			{
				questStateMachine.EnterState(3, 0);
			}
			else if (PhotonNetwork.isMasterClient && (currentGameplayRoom == null || currentGameplayRoom.IsFinished()))
			{
				int currentGameplayRoomIndex = GetCurrentGameplayRoomIndex();
				int num = currentGameplayRoomIndex + 1;
				if (num < totalRoomCount)
				{
					questStateMachine.EnterState(2, GetRoomUnloadingSubStateId(currentGameplayRoomIndex));
				}
				else
				{
					questStateMachine.EnterState(4);
				}
			}
		}

		private void OnEnterUnloadingRoomSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
			{
				Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: false, dropTools: false);
			}
			if (PhotonNetwork.isMasterClient)
			{
				masterQuestStateTimer.StartTimer(Player.DespawnDuration);
			}
			localCachedSpawnEquipmentInstantiationInfo = PlayerSpawnEquipmentInfo.GetDesiredLocalSpawnEquipmentInstantions();
		}

		private void OnUpdateUnloadingRoomSubState()
		{
			if (PhotonNetwork.isMasterClient && masterQuestStateTimer.TimerOver)
			{
				int currentGameplayRoomIndex = GetCurrentGameplayRoomIndex();
				int roomIndex = currentGameplayRoomIndex + 1;
				questStateMachine.EnterState(2, GetRoomRunningSubStateId(roomIndex));
			}
		}

		private void OnExitUnloadingRoomSubState(ushort nextStateId, ushort nextSubStateId)
		{
			if (usesCollectiblesForPoints)
			{
				Collectible.ReturnAllCollectibles();
			}
			UnloadCurrentGameplayRoom();
		}

		private void OnEnterWinState(ushort previousStateId, ushort previousSubStateId)
		{
			respawnsPlayersOnGameOver = false;
			AudioManager.Play2DSFX(gameWinSFX);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "THE END", victoryNotificationString, 5f);
			AudioManager.MusicMixer.StopAllMusic();
			if (PhotonNetwork.isMasterClient)
			{
				GameTeam firstActiveTeam = base.TeamManager.GetFirstActiveTeam();
				if (firstActiveTeam != GameTeam.ANY)
				{
					base.ScoreManager.MasterArbitrarilySetWinningTeam(firstActiveTeam);
				}
				ResetCheckpointProgress();
				masterQuestStateTimer.StartTimer(winGameOverDuration);
			}
			if (base.CustomGameSettings.AllowRewards && !base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				GameTeam playerTeam = base.TeamManager.GetPlayerTeam(PhotonNetwork.player);
				StartCoroutine(TryGenerateLocalPlayerGift(base.ScoreManager.GetScore(playerTeam)));
			}
			RaiseGameWinEvent();
		}

		protected void ResetCheckpointProgress()
		{
			DefaultRoomIndex = 0;
			DefaultCampaignStoryState = StoryState.STATE_0;
			CurrentCampaignStoryState = StoryState.STATE_0;
			CurrentRoomStoryState = StoryState.STATE_0;
		}

		private void OnUpdateWinState()
		{
			if (PhotonNetwork.isMasterClient && masterQuestStateTimer.TimerOver)
			{
				MasterStopGame();
			}
		}

		private void OnExitWinState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void OnEnterLoseSubState(ushort previousStateId, ushort previousSubStateId)
		{
			gameCanStillBeWon = false;
			respawnsPlayersOnGameOver = true;
			AudioManager.MusicMixer.StopAllMusic();
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "THE END", loseNotificationString, 5f);
			AudioManager.Play2DSFX(gameLoseSFX);
			if (PhotonNetwork.isMasterClient)
			{
				masterQuestStateTimer.StartTimer(loseGameOverDuration);
			}
			RaiseGameLoseEvent();
		}

		private void OnUpdateLoseSubState()
		{
			if (PhotonNetwork.isMasterClient && masterQuestStateTimer.TimerOver)
			{
				questStateMachine.EnterState(3, 1);
			}
		}

		private void OnEnterUnloadingFinalRoomSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
			{
				Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: false, dropTools: false);
			}
			if (PhotonNetwork.isMasterClient)
			{
				masterQuestStateTimer.StartTimer(Player.DespawnDuration);
			}
		}

		private void OnUpdateUnloadingFinalRoomSubState()
		{
			if (PhotonNetwork.isMasterClient && masterQuestStateTimer.TimerOver)
			{
				MasterStopGame();
			}
		}

		private void OnExitUnloadingFinalRoomSubState(ushort nextStateId, ushort nextSubStateId)
		{
			UnloadCurrentGameplayRoom();
		}

		private void InitializeRooms()
		{
			totalRoomCount = RecRoomSceneManager.Instance.GetLevelRoomCount();
			preGameRoom = UnityEngine.Object.FindObjectOfType<QuestPreGameRoom>();
			if (preGameRoom == null)
			{
				UnityEngine.Debug.LogError("There is no Quest Pre-Game Room.  One is required.");
			}
			else
			{
				preGameRoom.Initialize(this, -1);
			}
		}

		private void LoadGameplayRoom(int roomIndex)
		{
			if (currentGameplayRoom != null)
			{
				UnloadCurrentGameplayRoom();
			}
			RecRoomSceneManager.Instance.LoadLevelRoomAsync(roomIndex, OnGameplayRoomLoad);
		}

		private void OnGameplayRoomLoad(int roomIndex, GameObject[] roomRoots)
		{
			if (roomRoots != null)
			{
				for (int i = 0; i < roomRoots.Length; i++)
				{
					if (roomRoots[i] != null)
					{
						currentGameplayRoom = roomRoots[i].GetComponentInChildren<QuestGameplayRoom>();
						if (currentGameplayRoom != null)
						{
							break;
						}
					}
				}
				if (currentGameplayRoom != null)
				{
					currentGameplayRoom.Initialize(this, roomIndex);
					currentGameplayRoom.Activate();
					base.SpawnManager.AddSpawnPoints(currentGameplayRoom.PlayerSpawnPoints);
					base.SpawnManager.AddGiftSpawnPoints(currentGameplayRoom.GiftSpawnPoints);
				}
			}
			if (!base.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
			{
				base.SpawnManager.LocalPlayerRequestRespawn(dropTools: false);
			}
			if (this.GameplayRoomLoaded != null)
			{
				this.GameplayRoomLoaded(currentGameplayRoom);
			}
		}

		private void UnloadCurrentGameplayRoom()
		{
			int num = -1;
			if (currentGameplayRoom != null)
			{
				if (Player.LocalPlayerExists)
				{
					PlayerSpawnEquipmentInfo playerSpawnEquipmentInfo = localCachedSpawnEquipmentInstantiationInfo;
					base.SpawnManager.LocalPlayerRequestInstantiateToolsOnRespawn(playerSpawnEquipmentInfo.leftHandTool, playerSpawnEquipmentInfo.rightHandTool, playerSpawnEquipmentInfo.leftHipTool, playerSpawnEquipmentInfo.rightHipTool, playerSpawnEquipmentInfo.shoulderTool, suppressCleanupOnSpawnedTools: true);
					localCachedSpawnEquipmentInstantiationInfo = PlayerSpawnEquipmentInfo.Empty;
				}
				num = currentGameplayRoom.RoomIndex;
				base.SpawnManager.RemoveSpawnPoints(currentGameplayRoom.PlayerSpawnPoints);
				base.SpawnManager.RemoveGiftSpawnPoints(currentGameplayRoom.GiftSpawnPoints);
				currentGameplayRoom.OnLocalPlayerExit();
				if (PhotonNetwork.isMasterClient)
				{
					MasterCleanupAllSpawnedEquipment();
				}
				currentGameplayRoom.Deactivate();
				currentGameplayRoom = null;
			}
			if (num >= 0)
			{
				RecRoomSceneManager.Instance.UnloadLevelRoomAsync(num);
			}
		}

		private void EnterLocalQuestRoom()
		{
			if (localCurrentQuestRoom != null)
			{
				localCurrentQuestRoom.OnLocalPlayerExit();
			}
			if (!IsQuestRunning || !base.IsGameRunning || base.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				localCurrentQuestRoom = preGameRoom;
			}
			else if (IsQuestRunning)
			{
				localCurrentQuestRoom = currentGameplayRoom;
			}
			if (localCurrentQuestRoom != null)
			{
				localCurrentQuestRoom.OnLocalPlayerEnter();
			}
		}

		private ushort GetRoomRunningSubStateId(int roomIndex)
		{
			return (ushort)_GetRoomSubStateId(roomIndex, RunningStateSubStateTypes.RUNNING_ROOM_SUB_STATE);
		}

		private ushort GetRoomUnloadingSubStateId(int roomIndex)
		{
			return (ushort)_GetRoomSubStateId(roomIndex, RunningStateSubStateTypes.UNLOADING_ROOM_SUB_STATE);
		}

		private int _GetRoomSubStateId(int roomIndex, RunningStateSubStateTypes subStateType)
		{
			int num = (int)(2 * roomIndex + subStateType);
			int num2 = 0;
			return num2 + num;
		}

		private int GetRoomIndexFromSubStateId(ushort subStateId)
		{
			if (subStateId < 0)
			{
				return -1;
			}
			return subStateId / 2;
		}

		private int GetInitialRoomIndex()
		{
			return DefaultRoomIndex;
		}

		public int GetCurrentGameplayRoomIndex()
		{
			return GetRoomIndexFromSubStateId(questStateMachine.CurrentSubStateId);
		}

		private void OnDefaultCampaignStoryStateChanged()
		{
			if (PhotonNetwork.isMasterClient)
			{
				base.GameHasSaveState = DefaultCampaignStoryState != StoryState.STATE_0;
			}
		}

		private void OnStoryStateChanged()
		{
			if (this.StoryStateChanged != null)
			{
				this.StoryStateChanged(CurrentCampaignStoryState);
			}
		}

		private IEnumerator TryGenerateLocalPlayerGift(int score)
		{
			GiftBoxSpawnPoint spawnPoint = base.SpawnManager.GetGiftBoxSpawnPoint(PhotonNetwork.player);
			if (!(spawnPoint != null))
			{
				yield break;
			}
			Avatars.GiftPackage giftPackage = null;
			int numRetries = 0;
			GiftManager.GiftContext rankContext = base.ScoreManager.GetRankGiftContext(base.TeamManager.GetPlayerTeam(PhotonNetwork.player));
			GiftManager.GiftContext alternateContext = base.ScoreManager.GetAlternateGiftContext();
			while (giftPackage == null && numRetries < 3)
			{
				yield return SingletonMonoBehaviour<GiftManager>.Instance.RunGenerateGift(rankContext, alternateContext, isGameGift: false, delegate(Avatars.GiftPackage gift, string e)
				{
					if (gift != null)
					{
						giftPackage = gift;
					}
				});
				numRetries++;
			}
			if (giftPackage != null)
			{
				giftPackage.SetGiftContext(rankContext);
				yield return SingletonMonoBehaviour<GiftManager>.Instance.DequeueGift(giftPackage, spawnPoint.LocalPosition, spawnPoint.LocalRotation, (Avatars.GiftPackage variant) => variant.PackageVariant.dequeueBehavior == GiftPackageVariant.DequeueBehaviors.ConsumeImmediately);
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to generate gift package for Quest on the server.");
			}
		}

		protected override void MasterOnPlayerOutOfBounds(PhotonPlayer player)
		{
			base.MasterOnPlayerOutOfBounds(player);
			if (PhotonNetwork.isMasterClient)
			{
				bool arg = false;
				if (IsValidOutOfBoundsHitPlayer(player))
				{
					arg = true;
					base.CombatManager.MasterKillPlayer(player);
				}
				base.photonView.RpcAll(RpcOnOutOfBoundsHitPlayer, player, arg);
			}
		}

		[PunRPC]
		private void RpcOnOutOfBoundsHitPlayer(PhotonPlayer player, bool wasValidHit)
		{
			if (player.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "You're Out!", "Out of Bounds!", 1.5f);
				base.SpawnManager.LocalPlayerRequestRespawn(dropTools: false);
			}
			if (wasValidHit)
			{
				OnPlayerHealthChanged(player, HealthChangeType.OutOfBounds);
			}
		}

		protected override void EnableLocalPlayerToolRestrictions(bool pickupEnabled)
		{
			base.EnableLocalPlayerToolRestrictions(pickupEnabled);
			for (int i = 0; i < allWeapons.Length; i++)
			{
				if (allWeapons[i] != null)
				{
					allWeapons[i].Tool.SetPickupEnabled(pickupEnabled, this);
				}
			}
			for (int j = 0; j < allBreakableObjects.Length; j++)
			{
				if (allBreakableObjects[j] != null)
				{
					allBreakableObjects[j].Tool.SetPickupEnabled(pickupEnabled, this);
				}
			}
		}
	}
