				if (!tools[i].IsSubTool)
				{
					tools[i].MasterResetToLastSpawnPosition();
				}
			}
		}

		protected void MasterDisableAllRoomTools()
		{
			if (tools == null)
			{
				return;
			}
			for (int i = 0; i < tools.Length; i++)
			{
				if (!tools[i].IsSubTool)
				{
					tools[i].MasterDisableAndMoveToLastSpawnPosition();
				}
			}
		}

		private void InitializeTools()
		{
			tools = GetComponentsInChildren<Tool>(includeInactive: true);
			if (tools == null || !DisableToolCleanup)
			{
				return;
			}
			for (int i = 0; i < tools.Length; i++)
			{
				if (tools[i].ToolCleanup != null)
				{
					tools[i].ToolCleanup.PauseCleanup(this);
				}
			}
		}

		protected void MasterResetAllRoomTraps()
		{
