	public class QuestPassiveMeleeEnemy : Enemy
	{
		private enum CombatState
		{
			FIND_TARGET = 0,
			FOLLOW_TARGET = 1,
			PASSIVELY_ATTACK = 2,
			INVALID = 65535
		}

		[Header("Target Selection")]
		[SerializeField]
		private float desiredTargetDistance = 1f;

		[SerializeField]
		private float minRandomTargetOffsetAngle = 15f;

		[SerializeField]
		private float maxRandomTargetOffsetAngle = 30f;

		[Header("Melee Attack")]
		[SerializeField]
		private Transform armsTransform;

		[SerializeField]
		private float meleeAttackDuration = 3f;

		[Header("Shield Block")]
		[SerializeField]
		private float shieldStunRecoilSpeed = 3.5f;

		private SynchronizedStateMachine combatStateMachine;

		private SynchronizedTimer combatTimer;

		protected override void Awake()
		{
			base.Awake();
			combatTimer = new SynchronizedTimer(this, "BEHAVIOR", SetterPermissionMode.AUTHORITY);
			combatStateMachine = new SynchronizedStateMachine("BEHAVIOR", SetterPermissionMode.AUTHORITY);
			combatStateMachine.AddState(ushort.MaxValue, null, null, null);
			combatStateMachine.AddState(0, null, null, OnUpdateFindTargetState);
			combatStateMachine.AddState(1, OnEnterFollowTargetState, OnExitFollowTargetState, OnUpdateFollowTargetState);
			combatStateMachine.AddState(2, OnEnterPassivelyAttackState, OnExitPassivelyAttackState, OnUpdatePassivelyAttackState);
		}

		protected override void Start()
		{
			base.Start();
			base.MeleeCombatActive = true;
			combatStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnCombatStart()
		{
			base.OnCombatStart();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(0);
			}
		}

		protected override void OnCombatEnd()
		{
			base.OnCombatEnd();
			if (base.hasAuthority)
			{
				combatStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Update()
		{
			base.Update();
			combatStateMachine.Update();
			combatTimer.UpdateCallbacks();
		}

		protected override void OnPlayerImpact(Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (IsPlayerBlocking(hitPlayer, out var blockingWeapon))
			{
				Vector3 normalized = Vector3.ProjectOnPlane(base.RigidbodyEx.physicsPosition - impact.Point, Vector3.up).normalized;
				ApplyPlayerBlock(blockingWeapon, impact.Point, normalized);
			}
			else
			{
				base.OnPlayerImpact(enemy, hitPlayer, hitBodyPart, impact);
			}
		}

		protected override void OnPlayerToolImpact(Enemy enemy, Tool hitTool, WeaponImpact impact)
		{
			if (IsToolBlocking(hitTool, out var blockingWeapon))
			{
				Vector3 normalized = Vector3.ProjectOnPlane(base.RigidbodyEx.physicsPosition - impact.Point, Vector3.up).normalized;
				ApplyPlayerBlock(blockingWeapon, impact.Point, normalized);
			}
		}

		private bool IsPlayerBlocking(Player player, out MeleeWeapon blockingWeapon)
		{
			if (!IsToolBlocking(player.RightHand.HeldTool, out blockingWeapon) && !IsToolBlocking(player.LeftHand.HeldTool, out blockingWeapon))
			{
				return false;
			}
			Vector3 normalized = Vector3.ProjectOnPlane(base.RigidbodyEx.physicsPosition - player.TrackingSpace.RigidbodyEx.targetPosition, Vector3.up).normalized;
			return Vector3.Dot(player.TrackingSpace.RigidbodyEx.TargetTransform.forward, normalized) > 0f;
		}

		private bool IsToolBlocking(Tool tool, out MeleeWeapon blockingWeapon)
		{
			blockingWeapon = ((!(tool != null)) ? null : tool.GetComponent<MeleeWeapon>());
			return blockingWeapon != null && blockingWeapon.CanBlockEnemyMeleeAttacks;
		}

		private void ApplyPlayerBlock(Weapon blockingWeapon, Vector3 blockPoint, Vector3 recoilDirection)
		{
			if (base.hasAuthority && base.IsAlive && base.Health > 0)
			{
				AuthorityStun(WeaponDamageType.MELEE_SHIELD, EnemyArmorType.NORMAL);
				Vector3 velocity = recoilDirection * shieldStunRecoilSpeed;
				AuthorityOnDamageChangeVelocity(WeaponDamageType.MELEE_SHIELD, EnemyArmorType.NORMAL, velocity, Vector3.zero);
				base.photonView.RpcAll(RpcOnPlayerBlocked, blockingWeapon.photonView.viewID, blockPoint);
			}
		}

		[PunRPC]
		protected void RpcOnPlayerBlocked(int weaponId, Vector3 point)
		{
			PhotonView photonView = PhotonView.Find(weaponId);
			MeleeWeapon meleeWeapon = ((!(photonView != null)) ? null : photonView.GetComponent<MeleeWeapon>());
			if (meleeWeapon != null)
			{
				meleeWeapon.OnBlockAttack(point);
			}
		}

		protected override Combatant FindTarget(bool isPatrolling = false)
		{
			if (LastAttackerIsValidTarget())
			{
				return base.LastAttacker;
			}
			return FindRandomNearbyTarget(isPatrolling, mustHaveLineOfSight: false);
		}

		private void OnUpdateFindTargetState()
		{
			if (base.hasAuthority)
			{
				Combatant target = FindTarget();
				if (target.IsValid)
				{
					base.Target = target;
					base.LastAttacker = Combatant.Invalid;
					combatStateMachine.EnterState(1);
				}
				else
				{
					UpdateTargetCentroidPath(1f);
				}
			}
		}

		private void OnEnterFollowTargetState(ushort previousStateId, ushort previousSubStateId)
		{
			base.Steering.MaxHorizontalSpeed = movementSpeed;
			base.Steering.MaxHorizontalSteeringForce = movementMaxForce;
		}

		private void OnUpdateFollowTargetState()
		{
			AimWeaponsAtTargetPlayer();
			if (!base.hasAuthority)
			{
				return;
			}
			if (!SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(base.Target))
			{
				combatStateMachine.EnterState(0);
				return;
			}
			Vector3 floorPosition = base.Target.FloorPosition;
			if (!base.Steering.PathIsValid(floorPosition, desiredTargetDistance * 1.1f))
			{
				floorPosition = GetRandomOffsetPosition(floorPosition, desiredTargetDistance, minRandomTargetOffsetAngle, maxRandomTargetOffsetAngle);
				base.Steering.Path(floorPosition);
			}
			if (base.Steering.ReachedPathDestination)
			{
				combatStateMachine.EnterState(2);
			}
		}

		private void OnExitFollowTargetState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopPathing();
		}

		private void OnEnterPassivelyAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			if (enemyAudio != null)
			{
				enemyAudio.OnAttack();
			}
			if (base.hasAuthority)
			{
				combatTimer.StartTimer(meleeAttackDuration);
			}
		}

		private void OnUpdatePassivelyAttackState()
		{
			AimWeaponsAtTargetPlayer();
			if (base.hasAuthority)
			{
				if (!base.Target.IsValid)
				{
					combatStateMachine.EnterState(0);
				}
				else if (combatTimer.TimerOver)
				{
					combatStateMachine.EnterState(1);
				}
				else
				{
					base.Steering.Look(GetLookAtTargetVector(inXZPlane: true));
				}
			}
		}

		private void OnExitPassivelyAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			base.Steering.StopLooking();
		}

		private void AimWeaponsAtTargetPlayer()
		{
			if (!(armsTransform != null))
			{
				return;
			}
			Vector3 forward = base.transform.forward;
			if (base.Target.IsValid)
			{
				Vector3 vector = base.Target.HeadPosition - Vector3.up * 1f;
				Vector3 normalized = Vector3.ProjectOnPlane(vector - armsTransform.position, base.transform.right).normalized;
				float num = Vector3.Dot(normalized, base.transform.up);
				float num2 = Vector3.Dot(normalized, base.transform.forward);
				if (num < 1f - Mathf.Epsilon && num > 0f && num2 > 0f)
				{
					forward = normalized;
				}
			}
			armsTransform.rotation = Quaternion.LookRotation(forward, base.transform.up);
		}

		public override void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority)
			{
				float num = Vector3.Dot(velocity.normalized, Vector3.up);
				if (num < 0f)
				{
					float magnitude = velocity.magnitude;
					velocity = Vector3.ProjectOnPlane(velocity, Vector3.up).normalized * magnitude;
				}
				base.AuthorityOnDamageChangeVelocity(damageType, armorType, velocity, angularVelocity);
			}
		}

		protected override void OnInterruptedRecoveryStart()
		{
			base.OnInterruptedRecoveryStart();
			if (base.hasAuthority)
			{
				base.Steering.Look(Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized);
			}
		}

		protected override void OnInterruptedRecoveryEnd()
		{
			base.OnInterruptedRecoveryEnd();
			base.Steering.StopLooking();
		}
	}
}
