namespace RecRoom
{
	public class QuestTestingTable : Photon.MonoBehaviour
	{
		[SerializeField]
		private TextMeshProUGUI startingRoomText;

		[SerializeField]
		private TextMeshProUGUI startingStoryStateText;

		private SynchronizedField<int> _currentStartingRoom;

		private SynchronizedField<int> _currentStartingStoryState;

		private int CurrentStartingRoom
		{
			get
			{
				return _currentStartingRoom.Get();
			}
			set
			{
				_currentStartingRoom.Set(value);
			}
		}

		private QuestManager.StoryState CurrentStartingStoryState
		{
			get
			{
				return (QuestManager.StoryState)_currentStartingStoryState.Get();
			}
			set
			{
				_currentStartingStoryState.Set((int)value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_currentStartingRoom = new SynchronizedField<int>(this, "CSR", 0, SetterPermissionMode.MASTER, OnStartingRoomChanged);
			_currentStartingStoryState = new SynchronizedField<int>(this, "CSSS", 0, SetterPermissionMode.MASTER, OnStartingStoryStateChanged);
		}

		private void Start()
		{
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
				CurrentStartingRoom = questManager.DefaultRoomIndex;
				CurrentStartingStoryState = questManager.CurrentCampaignStoryState;
			}
			OnStartingRoomChanged();
			OnStartingStoryStateChanged();
		}

		public void RequestMasterIncreaseStartingRoom()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				int roomSceneLocationSubSceneCount = AGRoomSettings.GetRoomSceneLocationSubSceneCount(GameSessions.LocalGameSession.Location);
				if (CurrentStartingRoom + 1 < roomSceneLocationSubSceneCount)
				{
					base.photonView.RpcMaster(RpcMasterSetStartingRoom, CurrentStartingRoom + 1);
				}
			}
		}

		public void RequestMasterDecreaseStartingRoom()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && CurrentStartingRoom - 1 >= 0)
			{
				base.photonView.RpcMaster(RpcMasterSetStartingRoom, CurrentStartingRoom - 1);
			}
		}

		[PunRPC]
		private void RpcMasterSetStartingRoom(int newLevel)
		{
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				int roomSceneLocationSubSceneCount = AGRoomSettings.GetRoomSceneLocationSubSceneCount(GameSessions.LocalGameSession.Location);
				if (newLevel >= 0 && newLevel < roomSceneLocationSubSceneCount)
				{
					((QuestManager)NetworkedSingletonMonoBehaviour<GameManager>.Instance).DefaultRoomIndex = newLevel;
					CurrentStartingRoom = newLevel;
				}
			}
		}

		public void RequestMasterIncreaseStoryState()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && CurrentStartingStoryState + 1 <= QuestManager.StoryState.STATE_19)
			{
				base.photonView.RpcMaster(RpcMasterSetStartingStoryState, CurrentStartingStoryState + 1);
			}
		}

		public void RequestMasterDecreaseStoryState()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && CurrentStartingStoryState - 1 >= QuestManager.StoryState.STATE_0)
			{
				base.photonView.RpcMaster(RpcMasterSetStartingStoryState, CurrentStartingStoryState - 1);
			}
		}

		[PunRPC]
		private void RpcMasterSetStartingStoryState(QuestManager.StoryState newStoryState)
		{
			if (PhotonNetwork.isMasterClient && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && newStoryState >= QuestManager.StoryState.STATE_0 && newStoryState <= QuestManager.StoryState.STATE_19)
			{
				QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
				questManager.CurrentCampaignStoryState = newStoryState;
				questManager.DefaultCampaignStoryState = newStoryState;
				CurrentStartingStoryState = newStoryState;
			}
		}

		private void OnStartingRoomChanged()
		{
			startingRoomText.text = $"Starting in room {CurrentStartingRoom + 1}:\n{AGRoomSettings.GetRoomSceneLocationSubSceneAtIndex(GameSessions.LocalGameSession.Location, CurrentStartingRoom)}";
		}

		private void OnStartingStoryStateChanged()
		{
			startingStoryStateText.text = $"Story State: {CurrentStartingStoryState}";
		}
	}
}
namespace RecRoom.Core.AI
{
	public class RagdollPiece : UnityEngine.MonoBehaviour
	{
		private enum CriticalHitRagdollAction
		{
			NONE = -1,
			PLAY_EFFECT
		}

		[Tooltip("Only mark colliders as disable when not ragdolling if the colliders are exclusively used for ragdolling.")]
		[SerializeField]
		private bool disableColliderWhenNotRagdolling;

		[SerializeField]
		private bool disableInsteadOfRagdoll;

		[Header("Critical Hits")]
		[SerializeField]
		private float criticalHitShatterSpeedMultiplier = 1f;

		[SerializeField]
		private CriticalHitRagdollAction criticalHitActionOverride = CriticalHitRagdollAction.NONE;

		[SerializeField]
		private float criticalHitOverrideChance;

		[SerializeField]
		private bool disableWhenOverriding = true;

		[SerializeField]
		private PooledParticle criticalHitActionEffect;

		[SerializeField]
		private RecRoomAudioClip criticalHitActionAudioClip;

		private Collider[] colliders;

		private Rigidbody rigidbody;

		private Transform parent;

		private Vector3 localPosition = Vector3.zero;

		private Quaternion localRotation = Quaternion.identity;

		private Vector3 localScale = Vector3.one;

		private bool isRagdolling;

		private float ragdollStartTime;

		private Vector3 ragdollStartScale = Vector3.one;

		private ISchedulerPromise shrinkRoutine;

		private const float SHRINK_DELAY = 3.33f;

		private const float SHRINK_DURATION = 0.66f;

		private static bool useCustomGravity = false;

		private static Vector3 customGravity = Physics.gravity;

		public static void UseCustomGravity(Vector3 customGravity)
		{
			useCustomGravity = true;
			RagdollPiece.customGravity = customGravity;
		}

		public static void UseDefaultGravity()
		{
			useCustomGravity = false;
			customGravity = Physics.gravity;
		}

		private void Awake()
		{
			parent = base.transform.parent;
			localPosition = base.transform.localPosition;
			localRotation = base.transform.localRotation;
			localScale = base.transform.localScale;
			colliders = GetComponentsInChildren<Collider>(includeInactive: true);
			if (disableColliderWhenNotRagdolling)
			{
				for (int i = 0; i < colliders.Length; i++)
				{
					colliders[i].enabled = false;
				}
			}
		}

		private void OnDisable()
		{
			if (!base.gameObject.activeSelf)
			{
				base.transform.localScale *= 0f;
			}
		}

		public void StartRagdoll(Vector3 impactVelocity, Vector3 bodyCenterPosition, float explosionSpeed, bool isCriticalHit = false)
		{
			if (isRagdolling)
			{
				return;
			}
			isRagdolling = true;
			if (isCriticalHit && criticalHitActionOverride != CriticalHitRagdollAction.NONE && UnityEngine.Random.Range(0f, 1f) <= criticalHitOverrideChance)
			{
				if (criticalHitActionOverride == CriticalHitRagdollAction.PLAY_EFFECT)
				{
					PlayCriticalHitEffect();
				}
				return;
			}
			if (disableInsteadOfRagdoll)
			{
				base.gameObject.SetActive(value: false);
				return;
			}
			Vector3 angularVelocity = UnityEngine.Random.onUnitSphere * explosionSpeed * 57.29578f;
			Vector3 vector = (base.transform.position - bodyCenterPosition).normalized * explosionSpeed;
			Vector3 velocity = impactVelocity + vector;
			if (isCriticalHit)
			{
				velocity *= criticalHitShatterSpeedMultiplier;
			}
			int layer = 27;
			base.gameObject.layer = layer;
			for (int i = 0; i < colliders.Length; i++)
			{
				colliders[i].enabled = true;
				colliders[i].gameObject.layer = layer;
			}
			base.transform.localPosition = localPosition;
			base.transform.localRotation = localRotation;
			base.transform.localScale = localScale;
			base.transform.SetParent(null, worldPositionStays: true);
			if (rigidbody == null)
			{
				rigidbody = base.gameObject.AddComponent<Rigidbody>();
			}
			if (rigidbody != null)
			{
				rigidbody.isKinematic = false;
				rigidbody.angularDrag = 0f;
				rigidbody.drag = 0f;
				rigidbody.velocity = velocity;
				rigidbody.angularVelocity = angularVelocity;
				rigidbody.useGravity = !useCustomGravity;
			}
			ragdollStartTime = UnityEngine.Time.time;
			ragdollStartScale = base.transform.localScale;
			shrinkRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(ShrinkRoutine());
		}

		public void StopRagdoll()
		{
			if (!isRagdolling)
			{
				return;
			}
			if (base.gameObject != null)
			{
				base.gameObject.SetActive(value: true);
			}
			if (rigidbody != null)
			{
				UnityEngine.Object.Destroy(rigidbody);
				rigidbody = null;
			}
			bool flag = !disableColliderWhenNotRagdolling;
			for (int i = 0; i < colliders.Length; i++)
			{
				if (colliders[i] != null)
				{
					colliders[i].enabled = flag;
				}
			}
			if (base.transform != null)
			{
				base.transform.SetParent(parent, worldPositionStays: true);
				base.transform.localPosition = localPosition;
				base.transform.localRotation = localRotation;
				base.transform.localScale = localScale;
			}
			if (shrinkRoutine != null)
			{
				shrinkRoutine.Cancel();
				shrinkRoutine = null;
			}
			isRagdolling = false;
		}

		private IEnumerator<ISchedule> ShrinkRoutine()
		{
			float shrinkDelayEndTime = ragdollStartTime + 3.33f;
			if (useCustomGravity)
			{
				while (UnityEngine.Time.time < shrinkDelayEndTime)
				{
					yield return Schedule.NextFixedUpdate;
					rigidbody.AddForce(customGravity);
				}
			}
			else
			{
				yield return Schedule.Wait(shrinkDelayEndTime - UnityEngine.Time.time);
			}
			if (rigidbody != null)
			{
				rigidbody.isKinematic = true;
				for (int i = 0; i < colliders.Length; i++)
				{
					colliders[i].enabled = false;
				}
			}
			float shrinkEndTime = shrinkDelayEndTime + 0.66f;
			ScheduleRate scheduleRate = new ScheduleRate(30f);
			while (UnityEngine.Time.time < shrinkEndTime)
			{
				yield return scheduleRate;
				float invT = Mathf.InverseLerp(shrinkEndTime, shrinkDelayEndTime, UnityEngine.Time.time);
				base.transform.localScale = ragdollStartScale * invT;
			}
			base.transform.localScale = Vector3.zero;
		}

		private void PlayCriticalHitEffect()
		{
			if (disableWhenOverriding)
			{
				base.gameObject.SetActive(value: false);
			}
			if (criticalHitActionEffect != null)
			{
				ObjectPool.Instance.Acquire(criticalHitActionEffect)?.Play(base.transform);
			}
			if (criticalHitActionAudioClip != null)
			{
				AudioManager.Play3DSFX(criticalHitActionAudioClip, base.transform.position);
			}
		}
	}
