	public class QuestRoomLoot : QuestRoomBehaviour
	{
		[SerializeField]
		private bool hasEnabledChestLimit = true;

		[SerializeField]
		private int maxEnabledLootChests = 8;

		[SerializeField]
		private EquipmentSpawnerChest[] guaranteedEnabledChests;

		[SerializeField]
		private bool hasCustomEnemyLootDropRate;

		[SerializeField]
		private float customEnemyLootDropRate;

		protected override void OnRoomStartRunning(QuestRoomBase room)
		{
			base.OnRoomStartRunning(room);
			MasterDisableRandomLootChests();
			if (hasCustomEnemyLootDropRate)
			{
				LootManager.Instance.SetEnemyLootDropRate(customEnemyLootDropRate);
			}
			else
			{
				LootManager.Instance.ResetEnemyLootDropRate();
			}
		}

		protected override void OnRoomStopRunning(QuestRoomBase room)
		{
			base.OnRoomStopRunning(room);
			LootManager.Instance.ResetEnemyLootDropRate();
		}

		protected override void OnInitialize(QuestRoomBase room)
		{
		}

		protected override void OnLocalPlayerEnter(QuestRoomBase room)
		{
		}

		protected override void OnLocalPlayerExit(QuestRoomBase room)
		{
		}

		private void MasterDisableRandomLootChests()
		{
			if (!hasEnabledChestLimit || !PhotonNetwork.isMasterClient)
			{
				return;
			}
			EquipmentSpawnerChest[] componentsInChildren = GetComponentsInChildren<EquipmentSpawnerChest>(includeInactive: true);
			if (componentsInChildren.Length <= maxEnabledLootChests)
			{
				return;
			}
			UnityExtensions.ShuffleArray(componentsInChildren);
			int num = 0;
			int num2 = Mathf.Max(0, componentsInChildren.Length - maxEnabledLootChests);
			int i;
			for (i = 0; i < componentsInChildren.Length; i++)
			{
				if (num >= num2)
				{
					break;
				}
				if (guaranteedEnabledChests.Contains(componentsInChildren[i]))
				{
					componentsInChildren[i].MasterEnable(enabled: true);
					continue;
				}
				num++;
				componentsInChildren[i].MasterEnable(enabled: false);
			}
			for (; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].MasterEnable(enabled: true);
			}
		}
	}
	public class QuestRoomMusic : QuestRoomBehaviour
	{
		[SerializeField]
		private bool hasCustomAmbience;

		[SerializeField]
		private RecRoomAudioClip customAmbience;

		[SerializeField]
		private bool hasCustomGameplayMusic;

		[SerializeField]
		private RecRoomAudioClip customGameplayMusic;

		[SerializeField]
		private bool hasCustomActionMusic;

		[SerializeField]
		public ExtendedRecRoomAudioClips customActionMusicClips;

		protected override void OnInitialize(QuestRoomBase room)
		{
		}

		protected override void OnRoomStartRunning(QuestRoomBase room)
		{
			base.OnRoomStartRunning(room);
			if (hasCustomGameplayMusic)
			{
				AudioManager.MusicMixer.StopGameplayMusic();
			}
		}

		protected override void OnLocalPlayerEnter(QuestRoomBase room)
		{
			if (hasCustomAmbience)
			{
				AudioManager.AddAmbientAudio(customAmbience, this);
				AudioManager.PlayAmbientAudio();
			}
			if (hasCustomGameplayMusic)
			{
				AudioManager.MusicMixer.AddGameplayMusic(customGameplayMusic, this);
				AudioManager.MusicMixer.PlayGameplayMusic();
			}
			if (hasCustomActionMusic)
			{
				AudioManager.MusicMixer.AddActionMusic(customActionMusicClips, this);
			}
		}

		protected override void OnLocalPlayerExit(QuestRoomBase room)
		{
			if (hasCustomAmbience)
			{
				AudioManager.RemoveAmbientAudio(this);
			}
			if (hasCustomGameplayMusic)
			{
				AudioManager.MusicMixer.RemoveGameplayMusic(this);
			}
			if (hasCustomActionMusic)
			{
				AudioManager.MusicMixer.RemoveActionMusic(this);
			}
		}
	}
