		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent += OnInputDown;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.InputDownEvent -= OnInputDown;
			}
		}

		private void Update()
		{
			if (currentBolt != null)
			{
				float t = Mathf.InverseLerp(currentBoltAcquisitionTime, currentBoltAcquisitionTime + boltNockingAnimationLength, UnityEngine.Time.time);
				currentBolt.transform.position = Vector3.Lerp(boltInitialNockingTransform.position, boltFinalNockingTransform.position, t);
				currentBolt.transform.rotation = boltFinalNockingTransform.rotation;
			}
		}

		private void OnInputDown(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				if (!base.HasEnoughMagazineAmmunition)
				{
					TryPlayOutOfAmmoFeedback();
				}
				else if (base.IsMisfire || base.IsOnCooldown)
				{
					base.WeaponAudio.OnMisfire();
				}
				else
				{
					Fire();
				}
			}
		}

		protected override void OnAmmunitionChange()
		{
			base.OnAmmunitionChange();
			if (base.MagazineAmmunition == 0)
			{
				base.Animator.SetFloat(drawId, 0f);
				return;
			}
			base.Animator.SetFloat(drawId, 1f);
			if (currentBolt == null)
			{
				currentBolt = AcquireBullet() as CrossbowBolt;
				currentBoltAcquisitionTime = UnityEngine.Time.time;
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (!isMisfire)
			{
				FireBullet(position, rotation, velocity, 1f, shotId);
			}
		}

		protected override void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			if (currentBolt == null)
			{
				byte shotId2 = shotId;
				base.FireBullet(position, rotation, velocity, chargeAmount, shotId2, overrideAndDisableGravity: false, collisionFilter, prefab);
			}
			else
			{
				currentBolt.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, shotId);
				currentBolt = null;
			}
		}

		protected override Bullet FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, float maxLifetime, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			Bullet bullet = null;
			if (currentBolt == null)
			{
				byte shotId2 = shotId;
				bullet = base.FireBullet(position, rotation, velocity, chargeAmount, maxLifetime, shotId2, overrideAndDisableGravity: false, collisionFilter, prefab);
			}
			else
			{
				bullet = currentBolt;
				currentBolt.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, maxLifetime, shotId);
				currentBolt = null;
			}
			return bullet;
		}
	}
}
namespace RecRoom.Activities.BattleRoyale
{
	public class BattleRoyaleAmmo : CurrencyTool
	{
		public delegate void CollectAction(BattleRoyaleAmmo ammo);

		[Header("Feedback")]
		[SerializeField]
		private RecRoomAudioClip collectAudio;

		public static CollectAction CollectEvent = null;

		private bool _alreadyPickedUp;

		private static readonly string PICKUP_FORMAT_STRING = "+{0} {1} AMMO";

		private static readonly string AUTOMATIC_AMMO_NAME = "AUTOMATIC";

		private static readonly string PISTOL_AMMO_NAME = "PISTOL";

		private static readonly string RIFLE_AMMO_NAME = "RIFLE";

		private static readonly string SHOTGUN_AMMO_NAME = "SHOTGUN";

		private static readonly string BOW_AMMO_NAME = "BOW";

		private static readonly string HAND_CANNON_AMMO_NAME = "HAND CANNON";

		private static readonly string ROCKET_LAUNCHER_AMMO_NAME = "LAUNCHER";

		private static readonly float NOTIFICATION_DURATION = 0.66f;

		private static readonly Vector3 NOTIFICATION_OFFSET = new Vector3(0f, 0.5f, 0f);

		public BattleRoyaleGearType AmmoType { get; private set; }

		public int AmmoAmount { get; private set; }

		public override bool AlreadyPickedUp => _alreadyPickedUp;

		private string GetAmmoTypeName()
		{
			return AmmoType switch
			{
				BattleRoyaleGearType.WEAPON_AUTOMATIC => AUTOMATIC_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_BOW => BOW_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_HAND_CANNON => HAND_CANNON_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_PISTOL => PISTOL_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_RIFLE => RIFLE_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_ROCKET_LAUNCHER => ROCKET_LAUNCHER_AMMO_NAME, 
				BattleRoyaleGearType.WEAPON_SHOTGUN => SHOTGUN_AMMO_NAME, 
				_ => string.Empty, 
			};
		}

		public void SetConfigurationData(AmmunitionData configurationData)
		{
			AmmoType = (BattleRoyaleGearType)configurationData.AmmoGearType;
			AmmoAmount = configurationData.AmmoAmount;
		}

		public void AuthoritySetAlreadyPickedUp()
		{
			if (base.hasAuthority)
			{
				_alreadyPickedUp = true;
			}
		}

		protected override void OnPickup(Tool tool)
		{
			base.OnPickup(tool);
			if (!AlreadyPickedUp)
			{
				WorldSpaceNotification.PlayNext(string.Format(PICKUP_FORMAT_STRING, AmmoAmount, GetAmmoTypeName()), NOTIFICATION_DURATION, null, followPlayer: false, base.transform.position + NOTIFICATION_OFFSET, 0.3f, billboard: true);
				AudioManager.Play3DSFX(collectAudio, base.transform.position);
				if (!AlreadyPickedUp && CollectEvent != null)
				{
					CollectEvent(this);
				}
			}
		}
	}
	public class BattleRoyaleCableCar : Photon.MonoBehaviour
	{
		public delegate void CableCarAction(BattleRoyaleCableCar thisCableCar);

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private FixedPathVehicle vehicle;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip ambientAudio;

		[SerializeField]
		private RecRoomAudioClip doorWindLoopingSFX;

		[SerializeField]
		private RecRoomAudioClip fanfareAudio;

		[SerializeField]
		private Transform fanfareSpeakerTransform;

		[Header("Kick Players Out")]
		[SerializeField]
		private float kickPlayersOutRandomMaxLateralOffset = 1.5f;

		[SerializeField]
		private float kickPlayersOutRandomMaxRotationAngle = 20f;

		private SynchronizedField<bool> _isEnabled;

		private LockableDoor[] doors;

		private BattleRoyaleGliderSpawner[] gliderSpawners;

		private SFXAudioSource loopingDoorWindAudio;

		public static CableCarAction LocalPlayerExitEvent;

		private bool _doorsLocked;

		public static BattleRoyaleCableCar Instance { get; private set; }

		public FixedPathVehicle FixedPathVehicle => vehicle;

		public bool DoorsLocked
		{
			get
			{
				return _doorsLocked;
			}
			set
			{
				_doorsLocked = value;
				if (doors != null)
				{
					for (int i = 0; i < doors.Length; i++)
					{
						doors[i].IsLocked = value;
					}
				}
				UpdateGliderSpawnersEnabled();
				UpdateAudio();
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (Instance == null)
			{
				Instance = this;
			}
			vehicle.LocalPlayerOccupiesChangeEvent += OnVehicleOccupiedChange;
			doors = GetComponentsInChildren<LockableDoor>();
			gliderSpawners = GetComponentsInChildren<BattleRoyaleGliderSpawner>();
			for (int i = 0; i < gliderSpawners.Length; i++)
			{
				gliderSpawners[i].LocalGliderSpawnEvent += OnLocalGliderSpawned;
			}
			_isEnabled = new SynchronizedField<bool>(this, "IS_ENABLED", defaultValue: true, SetterPermissionMode.AUTHORITY, OnIsEnabledChange);
		}

		private void Start()
		{
			UpdateGliderSpawnersEnabled();
			OnIsEnabledChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			vehicle.LocalPlayerOccupiesChangeEvent -= OnVehicleOccupiedChange;
			if (gliderSpawners != null)
			{
				for (int i = 0; i < gliderSpawners.Length; i++)
				{
					if (gliderSpawners[i] != null)
					{
						gliderSpawners[i].LocalGliderSpawnEvent -= OnLocalGliderSpawned;
					}
				}
			}
			StopAllAudio();
			if (Instance == this)
			{
				Instance = null;
			}
		}

		public void MasterEnable()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				_isEnabled.Set(newValue: true);
				AuthorityStopRunning();
				vehicle.AuthoritySnapToFirstPathPoint();
			}
		}

		public void MasterDisable()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				AuthorityStopRunning();
				_isEnabled.Set(newValue: false);
			}
		}

		public void AuthorityStartRunning()
		{
			if (base.hasAuthority)
			{
				vehicle.IsRunning = true;
			}
		}

		public void AuthorityStopRunning()
		{
			if (base.hasAuthority)
			{
				vehicle.IsRunning = false;
			}
		}

		public void PlayFanfareAudio()
		{
			if (fanfareSpeakerTransform != null)
			{
				SFXAudioSource sFXAudioSource = AudioManager.Play3DSFX(fanfareAudio, fanfareSpeakerTransform);
				sFXAudioSource.AudioSource.dopplerLevel = 0f;
			}
		}

		public void KickOutLocalPlayer()
		{
			if (FixedPathVehicle.LocalPlayerOccupies && Player.LocalPlayerExists)
			{
				BattleRoyaleGliderSpawner closestGliderSpawner = GetClosestGliderSpawner(Player.LocalPlayer.Head.transform.position);
				if (!(closestGliderSpawner == null))
				{
					Vector3 destinationPlayerPosition = closestGliderSpawner.transform.position + closestGliderSpawner.transform.right * UnityEngine.Random.Range(-1f, 1f) * kickPlayersOutRandomMaxLateralOffset;
					Vector3 value = Quaternion.AngleAxis(UnityEngine.Random.Range(-1f, 1f) * kickPlayersOutRandomMaxRotationAngle, closestGliderSpawner.transform.up) * closestGliderSpawner.transform.forward;
					Player.LocalPlayer.PlayerLocomotion.TeleportTo(destinationPlayerPosition, value, canCarryTools: true, FixedPathVehicle.RigidbodyEx, cancelCurrentTeleport: true);
				}
			}
		}

		private void OnIsEnabledChange()
		{
			base.gameObject.SetActive(_isEnabled.Get());
		}

		private void OnVehicleOccupiedChange()
		{
			UpdateGliderSpawnersEnabled();
			UpdateAudio();
		}

		private void OnLocalGliderSpawned(BattleRoyaleGlider glider)
		{
			if (LocalPlayerExitEvent != null)
			{
				LocalPlayerExitEvent(this);
			}
		}

		private void UpdateGliderSpawnersEnabled()
		{
			bool flag = vehicle.LocalPlayerOccupies && !DoorsLocked;
			if (gliderSpawners != null)
			{
				for (int i = 0; i < gliderSpawners.Length; i++)
				{
					gliderSpawners[i].enabled = flag;
				}
			}
		}

		private BattleRoyaleGliderSpawner GetClosestGliderSpawner(Vector3 position)
		{
			BattleRoyaleGliderSpawner result = null;
			float num = float.MaxValue;
			if (gliderSpawners != null)
			{
				for (int i = 0; i < gliderSpawners.Length; i++)
				{
					if (gliderSpawners[i].enabled)
					{
						float sqrMagnitude = (position - gliderSpawners[i].transform.position).sqrMagnitude;
						if (sqrMagnitude <= num)
						{
							num = sqrMagnitude;
							result = gliderSpawners[i];
						}
					}
				}
			}
			return result;
		}

		private void UpdateAudio()
		{
			if (vehicle.LocalPlayerOccupies)
			{
				StartAmbientAudio();
				if (DoorsLocked)
				{
					StopDoorWindAudio();
				}
				else
				{
					StartDoorWindAudio();
				}
			}
			else
			{
				StopAllAudio();
			}
		}

		private void StartAmbientAudio()
		{
			AudioManager.AddAmbientAudio(ambientAudio, this);
		}

		private void StopAmbientAudio()
		{
			AudioManager.RemoveAmbientAudio(this);
		}

		private void StartDoorWindAudio()
		{
			if (loopingDoorWindAudio == null)
			{
				loopingDoorWindAudio = AudioManager.StartLooping2DSFX(doorWindLoopingSFX);
			}
		}

		private void StopDoorWindAudio()
		{
			if (loopingDoorWindAudio != null)
			{
				AudioManager.StopLoopingSFX(loopingDoorWindAudio);
				loopingDoorWindAudio = null;
			}
		}

		private void StopAllAudio()
		{
			StopAmbientAudio();
			StopDoorWindAudio();
		}
	}
}
public class BattleRoyaleCableCarPathGenerator : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float initialPointRingRadius = 450f;

	[SerializeField]
	private float maxRandomPathAngle = 20f;

	[SerializeField]
	private float pathLength = 900f;

	public static BattleRoyaleCableCarPathGenerator Instance { get; private set; }

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
	}

	private void OnDestroy()
	{
		if (Instance == this)
		{
			Instance = null;
		}
	}

	public Vector3[] GeneratePath()
	{
		Vector3[] array = new Vector3[2];
		float angle = UnityEngine.Random.Range(0f, 360f);
		ref Vector3 reference = ref array[0];
		reference = base.transform.position + Quaternion.AngleAxis(angle, Vector3.up) * Vector3.forward * initialPointRingRadius;
		float angle2 = UnityEngine.Random.Range(0f - maxRandomPathAngle, maxRandomPathAngle);
		Vector3 normalized = (base.transform.position - array[0]).normalized;
		normalized = Quaternion.AngleAxis(angle2, Vector3.up) * normalized;
		ref Vector3 reference2 = ref array[1];
		reference2 = array[0] + normalized * pathLength;
		return array;
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireSphere(base.transform.position, initialPointRingRadius);
		Gizmos.color = Color.red;
		Vector3 vector = base.transform.position - Vector3.forward * initialPointRingRadius;
		Vector3 vector2 = Quaternion.AngleAxis(0f - maxRandomPathAngle, Vector3.up) * Vector3.forward;
		Vector3 to = vector + vector2 * pathLength;
		Gizmos.DrawLine(vector, to);
		Vector3 vector3 = Quaternion.AngleAxis(maxRandomPathAngle, Vector3.up) * Vector3.forward;
		Vector3 to2 = vector + vector3 * pathLength;
		Gizmos.DrawLine(vector, to2);
	}
}
