	public class BattleRoyaleGameplayZone : Photon.MonoBehaviour
	{
		private enum State
		{
			DISABLED,
			ENABLED
		}

		private enum EnabledSubState
		{
			WAITING,
			SHRINKING_SOON,
			SHRINKING,
			FINISHED
		}

		[Header("Damage")]
		[SerializeField]
		private int damageAmount = 10;

		[SerializeField]
		private float damagePeriod = 1f;

		[Header("Timing")]
		[SerializeField]
		private float initialWaitBeforeShrinkingDuration = 120f;

		[SerializeField]
		private float waitBeforeShrinkingDuration = 60f;

		[SerializeField]
		private float shrinkingSoonDuration = 60f;

		[SerializeField]
		private float shrinkingDuration = 10f;

		[Header("Notifications")]
		[SerializeField]
		private string shrinkingSoonNotification;

		[SerializeField]
		private string shrinkingNotification;

		[Header("Ring Config")]
		[SerializeField]
		private float[] ringRadii = new float[5] { 550f, 450f, 300f, 150f, 20f };

		[SerializeField]
		private Vector3 initialRingCenter = Vector3.zero;

		[Header("Visuals")]
		[SerializeField]
		private Transform fenceRoot;

		[SerializeField]
		private MeshRenderer fenceRenderer;

		[SerializeField]
		private float worldSpaceFenceHeight = 300f;

		[SerializeField]
		private float worldSpaceFenceHexHorizontalSize = 6f;

		[SerializeField]
		private float worldSpaceFenceHexVerticalSize = 6f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip loopingOutsideRingSFX;

		[SerializeField]
		private RecRoomAudioClip outsideRingDamageAudio;

		[SerializeField]
		private AudioRolloff nearRingAudioRolloff;

		[SerializeField]
		private AnimationCurve ringSpatialAudioCurve;

		private SynchronizedStateMachine stateMachine;

		private SynchronizedTimer stateTimer;

		private SynchronizedField<int, Vector3, float, Vector3, float> _ringData;

		private float lastLocalPlayerDamageTime;

		private float ringRadiusVelocity;

		private Vector3 ringCenterVelocity = Vector3.zero;

		private float fenceFadeEndDistance = 200f;

		private SFXAudioSource loopingRingAudioSource;

		private bool _localPlayerIsInsideRing;

		private static readonly int FENCE_FADE_END_DIST_SHADER_ID = Shader.PropertyToID("_FadeEndViewDistance");

		private const float HEXAGON_U_TEXTURE_SCALE = 1.27777f;

		private const float HEXAGON_V_TEXTURE_SCALE = 0.25f;

		private const int FENCE_MESH_SEGMENTS = 32;

		public static BattleRoyaleGameplayZone Instance { get; private set; }

		public bool RingsEnabled => stateMachine.CurrentStateId == 1;

		public Vector3 LocalRingCenter
		{
			get
			{
				return fenceRoot.transform.position;
			}
			private set
			{
				Vector3 position = fenceRoot.transform.position;
				position.x = value.x;
				position.z = value.z;
				fenceRoot.transform.position = position;
			}
		}

		public float LocalRingRadius
		{
			get
			{
				return fenceRoot.transform.localScale.x;
			}
			private set
			{
				fenceRoot.localScale = new Vector3(value, worldSpaceFenceHeight, value);
				float num = (float)Math.PI * 2f * value;
				float num2 = num / 32f;
				float num3 = Mathf.RoundToInt(num2 / worldSpaceFenceHexHorizontalSize);
				float x = 1.27777f * num3;
				float num4 = worldSpaceFenceHeight / worldSpaceFenceHexVerticalSize;
				float y = 0.25f * num4;
				fenceRenderer.material.mainTextureScale = new Vector2(x, y);
			}
		}

		public float NextRingRadius => _ringData.Get5();

		public Vector3 NextRingCenter => _ringData.Get4();

		public float CurrentRingRadius => _ringData.Get3();

		public Vector3 CurrentRingCenter => _ringData.Get2();

		private int RingCount => _ringData.Get1();

		private bool LocalPlayerIsInsideRing
		{
			get
			{
				return _localPlayerIsInsideRing;
			}
			set
			{
				bool localPlayerIsInsideRing = _localPlayerIsInsideRing;
				_localPlayerIsInsideRing = value;
				if (localPlayerIsInsideRing != _localPlayerIsInsideRing)
				{
					if (_localPlayerIsInsideRing)
					{
						StopOutsideRingFeedback();
					}
					else
					{
						StartOutsideRingFeedback();
					}
				}
			}
		}

		private float InitialRingRadius => (ringRadii == null || ringRadii.Length <= 0) ? 550f : ringRadii[0];

		protected override void Awake()
		{
			base.Awake();
			if (Instance == null)
			{
				Instance = this;
			}
			_ringData = new SynchronizedField<int, Vector3, float, Vector3, float>(this, "CRSF", 0, initialRingCenter, InitialRingRadius, initialRingCenter, InitialRingRadius, SetterPermissionMode.MASTER);
			stateTimer = new SynchronizedTimer(this, "ST", SetterPermissionMode.MASTER);
			stateMachine = new SynchronizedStateMachine("SSM", SetterPermissionMode.MASTER);
			stateMachine.AddState(0, EnterDisabledSuperState, null, null);
			stateMachine.AddState(1, EnterEnabledSuperState, null, UpdateEnabledSuperState);
			stateMachine.AddState(1, 0, EnterWaitingSubState, ExitWaitingSubState, UpdateWaitingSubState);
			stateMachine.AddState(1, 1, EnterShrinkingSoonSubState, ExitShrinkingSoonSubState, UpdateShrinkingSoonSubState);
			stateMachine.AddState(1, 2, EnterShrinkingSubState, ExitShrinkingSubState, UpdateShrinkingSubState);
			stateMachine.AddState(1, 3, null, null, null);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			StopOutsideRingFeedback();
			StopRingAudioFeedback();
			if (Instance == this)
			{
				Instance = null;
			}
		}

		private void Update()
		{
			stateMachine.Update();
		}

		public void MasterStart()
		{
			if (PhotonNetwork.isMasterClient)
			{
				SetRingData(0, initialRingCenter, InitialRingRadius, initialRingCenter, InitialRingRadius);
				stateMachine.EnterState(1, 0);
			}
		}

		public void MasterStop()
		{
			if (PhotonNetwork.isMasterClient)
			{
				stateMachine.EnterState(0);
			}
		}

		private void EnterDisabledSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			fenceRenderer.enabled = false;
			LocalPlayerIsInsideRing = true;
			StopRingAudioFeedback();
		}

		private void EnterEnabledSuperState(ushort previousStateId, ushort previousSubStateId)
		{
			fenceRenderer.enabled = true;
			fenceFadeEndDistance = fenceRenderer.sharedMaterial.GetFloat(FENCE_FADE_END_DIST_SHADER_ID);
			LocalRingCenter = CurrentRingCenter;
			LocalRingRadius = CurrentRingRadius;
			LocalPlayerIsInsideRing = true;
		}

		private void UpdateEnabledSuperState()
		{
			LocalRingRadius = Mathf.SmoothDamp(LocalRingRadius, CurrentRingRadius, ref ringRadiusVelocity, shrinkingDuration);
			LocalRingCenter = Vector3.SmoothDamp(LocalRingCenter, CurrentRingCenter, ref ringCenterVelocity, shrinkingDuration);
			float distance;
			Vector3 closestPointOnRingToPlayer = GetClosestPointOnRingToPlayer(PhotonNetwork.player, LocalRingCenter, LocalRingRadius, out distance);
			bool flag = PlayerCanTakeRingDamage(PhotonNetwork.player);
			LocalPlayerIsInsideRing = !flag || distance <= 0f;
			float maxDistance = nearRingAudioRolloff.maxDistance;
			if (flag && (!LocalPlayerIsInsideRing || Mathf.Abs(distance) <= maxDistance))
			{
				float spatialBlend = 0f;
				if (distance < 0f)
				{
					float time = Mathf.Clamp01(Mathf.InverseLerp(0f - maxDistance, 0f, distance));
					spatialBlend = Mathf.Clamp01(1f - ringSpatialAudioCurve.Evaluate(time));
				}
				UpdateRingAudioFeedback(closestPointOnRingToPlayer, spatialBlend);
			}
			else
			{
				StopRingAudioFeedback();
			}
			fenceRenderer.enabled = Mathf.Abs(distance) <= fenceFadeEndDistance;
			if (!LocalPlayerIsInsideRing && UnityEngine.Time.time - lastLocalPlayerDamageTime >= damagePeriod)
			{
				lastLocalPlayerDamageTime = UnityEngine.Time.time;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.LocalRequestMiscPlayerDamage(Player.BodyPart.Head, Player.LocalPlayer.Head.transform.position, damageAmount, damageIgnoresShield: true);
				AudioManager.Play2DSFX(outsideRingDamageAudio);
			}
		}

		private Vector3 GetClosestPointOnRingToPlayer(PhotonPlayer player, Vector3 ringCenter, float ringRadius, out float distance)
		{
			Player player2 = player.ToPlayer();
			if (player2 == null)
			{
				distance = 0f;
				return Vector3.zero;
			}
			Vector3 position = player2.Head.transform.position;
			Vector3 vector = Vector3.ProjectOnPlane(position - ringCenter, Vector3.up);
			float magnitude = vector.magnitude;
			distance = magnitude - ringRadius;
			Vector3 vector2 = ((!(magnitude > 0f)) ? (Vector3.forward * ringRadius) : (vector * (ringRadius / magnitude)));
			Vector3 result = ringCenter + vector2;
			result.y = position.y;
			return result;
		}

		private bool PlayerCanTakeRingDamage(PhotonPlayer player)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				return false;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(player))
			{
				return false;
			}
			if (BattleRoyaleManager.Instance.IsPlayerEliminated(player, out var _))
			{
				return false;
			}
			return true;
		}

		private void EnterWaitingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				float maxRunningTime = ((RingCount != 0) ? waitBeforeShrinkingDuration : initialWaitBeforeShrinkingDuration);
				stateTimer.StartTimer(maxRunningTime);
			}
		}

		private void UpdateWaitingSubState()
		{
			if (PhotonNetwork.isMasterClient && stateTimer.TimerOver)
			{
				stateMachine.EnterState(1, 1);
			}
		}

		private void ExitWaitingSubState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void EnterShrinkingSoonSubState(ushort previousStateId, ushort previousSubStateId)
		{
			PlayNotification(shrinkingSoonNotification);
			if (PhotonNetwork.isMasterClient)
			{
				int num = Mathf.Clamp(RingCount + 1, 0, ringRadii.Length - 1);
				float nextRingRadius = ringRadii[num];
				TryGetNextRandomRing(CurrentRingCenter, CurrentRingRadius, nextRingRadius, out var nextRingCenter);
				SetRingData(RingCount, CurrentRingCenter, CurrentRingRadius, nextRingCenter, nextRingRadius);
				stateTimer.StartTimer(shrinkingSoonDuration);
			}
		}

		private void UpdateShrinkingSoonSubState()
		{
			if (PhotonNetwork.isMasterClient && stateTimer.TimerOver)
			{
				stateMachine.EnterState(1, 2);
			}
		}

		private void ExitShrinkingSoonSubState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void EnterShrinkingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			PlayNotification(shrinkingNotification);
			if (PhotonNetwork.isMasterClient)
			{
				SetRingData(RingCount + 1, NextRingCenter, NextRingRadius, NextRingCenter, NextRingRadius);
				stateTimer.StartTimer(shrinkingDuration);
			}
		}

		private void UpdateShrinkingSubState()
		{
			if (PhotonNetwork.isMasterClient && stateTimer.TimerOver)
			{
				if (RingCount < ringRadii.Length - 1)
				{
					stateMachine.EnterState(1, 0);
				}
				else
				{
					stateMachine.EnterState(1, 3);
				}
			}
		}

		private void ExitShrinkingSubState(ushort nextStateid, ushort nextSubStateId)
		{
		}

		private void StartOutsideRingFeedback()
		{
			StopOutsideRingFeedback();
			if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.AddPersistentNotification("BEES!", "Return To Safety!", this);
			}
		}

		private void StopOutsideRingFeedback()
		{
			if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
			}
		}

		private void UpdateRingAudioFeedback(Vector3 closestPointOnRing, float spatialBlend)
		{
			if (loopingRingAudioSource == null)
			{
				loopingRingAudioSource = AudioManager.StartLooping3DSFX(loopingOutsideRingSFX, Vector3.zero, nearRingAudioRolloff);
			}
			loopingRingAudioSource.AudioSource.spatialBlend = spatialBlend;
			loopingRingAudioSource.transform.position = closestPointOnRing;
		}

		private void StopRingAudioFeedback()
		{
			if (loopingRingAudioSource != null)
			{
				loopingRingAudioSource.AudioSource.spatialBlend = 1f;
				AudioManager.StopLoopingSFX(loopingRingAudioSource);
				loopingRingAudioSource = null;
			}
		}

		private void SetRingData(int ringCount, Vector3 currentRingCenter, float currentRingRadius, Vector3 nextRingCenter, float nextRingRadius)
		{
			_ringData.Set(ringCount, currentRingCenter, currentRingRadius, nextRingCenter, nextRingRadius);
		}

		private void PlayNotification(string notification)
		{
			if (BattleRoyaleManager.Instance == null || !BattleRoyaleManager.Instance.IsGameEnding)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, notification, 5f);
			}
		}

		private bool TryGetNextRandomRing(Vector3 currentRingCenter, float currentRingRadius, float nextRingRadius, out Vector3 nextRingCenter)
		{
			float num = currentRingRadius - nextRingRadius;
			bool flag = num > 0f;
			if (flag)
			{
				Vector2 vector = UnityEngine.Random.insideUnitCircle * num;
				Vector3 vector2 = new Vector3(vector.x, 0f, vector.y);
				nextRingCenter = currentRingCenter + vector2;
			}
			else
			{
				nextRingCenter = currentRingCenter;
			}
			return flag;
		}

		private void OnDrawGizmosSelected()
		{
			if (Player.LocalPlayerExists)
			{
				float distance;
				Vector3 closestPointOnRingToPlayer = GetClosestPointOnRingToPlayer(PhotonNetwork.player, LocalRingCenter, LocalRingRadius, out distance);
				Gizmos.color = Color.blue;
				Gizmos.DrawWireSphere(closestPointOnRingToPlayer, 0.5f);
				Gizmos.color = Color.yellow;
				Gizmos.DrawLine(Player.LocalPlayer.Head.transform.position, closestPointOnRingToPlayer);
			}
		}
	}
	public class BattleRoyaleGear : UnityEngine.MonoBehaviour
	{
		private RangedWeapon rangedWeapon;

		private BattleRoyaleGearData equipmentData;

		public string DisplayName => (equipmentData == null) ? null : equipmentData.DisplayName;

		public Color Color
		{
			get
			{
				BattleRoyaleGearQuality quality = ((equipmentData != null) ? ((BattleRoyaleGearQuality)equipmentData.Quality) : BattleRoyaleGearQuality.COMMON);
				return BattleRoyaleGearSettings.GetGearQualityColor(quality);
			}
		}

		private void Awake()
		{
			rangedWeapon = GetComponent<RangedWeapon>();
			if (rangedWeapon != null)
			{
				rangedWeapon.LocalPlayerFireEvent += OnLocalPlayerFireRangedWeapon;
			}
		}

		private void Start()
		{
			if (equipmentData == null)
			{
				return;
			}
			Color color = Color;
			TeamColorRenderer component = GetComponent<TeamColorRenderer>();
			if (component != null)
			{
				component.SetOverrideColor(Color);
			}
			ToolPlayerAttractor component2 = GetComponent<ToolPlayerAttractor>();
			if (component2 != null)
			{
				component2.OverrideSetEnableOnRelease(enableOnRelease: true);
				component2.SetColor(Color);
			}
			if (equipmentData.RangedWeaponData != null && rangedWeapon != null)
			{
				rangedWeapon.SetConfigurationData(equipmentData.RangedWeaponData);
				if (!equipmentData.RangedWeaponData.ResetOnTotalAmmoExhaustion)
				{
					rangedWeapon.CustomGetReserveAmmoBehavior = RangedWeaponGetReserveAmmoBehavior;
					rangedWeapon.CustomSetReserveAmmoBehavior = RangedWeaponSetReserveAmmoBehavior;
				}
				return;
			}
			HealthPotion component3 = GetComponent<HealthPotion>();
			if (equipmentData.HealthPotionData != null && component3 != null)
			{
				component3.SetConfigurationData(equipmentData.HealthPotionData);
				return;
			}
			BattleRoyaleAmmo component4 = GetComponent<BattleRoyaleAmmo>();
			if (component4 != null)
			{
				component4.SetConfigurationData(equipmentData.AmmunitionData);
			}
		}

		private void OnDestroy()
		{
			if (rangedWeapon != null)
			{
				rangedWeapon.LocalPlayerFireEvent -= OnLocalPlayerFireRangedWeapon;
			}
		}

		public void Initialize(BattleRoyaleGearData equipmentData)
		{
			this.equipmentData = equipmentData;
		}

		private void OnLocalPlayerFireRangedWeapon(RangedWeapon rangedWeapon)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomGameSettings.ForceDualWieldingSupport || rangedWeapon == null || rangedWeapon.Tool == null || !rangedWeapon.Tool.IsHeldByPlayer)
			{
				return;
			}
			Player holderPlayer = rangedWeapon.Tool.HolderPlayer;
			if (!(holderPlayer == null) && holderPlayer.isLocal)
			{
				PlayerHand holderHand = rangedWeapon.Tool.HolderHand;
				PlayerHand playerHand = ((!(holderHand != null)) ? null : holderPlayer.GetOtherHand(holderHand.Type));
				Tool tool = ((!(playerHand != null) || !playerHand.IsHoldingTool) ? null : playerHand.HeldTool);
				RangedWeapon rangedWeapon2 = ((!(tool != null)) ? null : tool.GetComponent<RangedWeapon>());
				if (!(rangedWeapon2 == null) && !(rangedWeapon2 == this.rangedWeapon))
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "CANNOT DUAL WIELD", 3f);
					holderPlayer.TryDisarm(tool);
				}
			}
		}

		private int RangedWeaponGetReserveAmmoBehavior(Weapon weapon)
		{
			if (weapon.Tool == null || !weapon.Tool.IsHeld || !weapon.Tool.IsHeldByPlayer || weapon.Tool.HolderPlayer == null || weapon.Tool.HolderPlayer.PhotonPlayer == null)
			{
				return 0;
			}
			return BattleRoyaleGearManager.Instance.GetFieldAmmo(weapon.Tool.HolderPlayer.PhotonPlayer, (BattleRoyaleGearType)equipmentData.GearType);
		}

		private void RangedWeaponSetReserveAmmoBehavior(Weapon weapon, int ammo)
		{
			if (weapon.Tool.IsHeld && weapon.Tool.IsHeldByPlayer && !(weapon.Tool.HolderPlayer == null) && weapon.hasAuthority)
			{
				BattleRoyaleGearManager.Instance.SetFieldAmmo(weapon.Tool.HolderPlayer.PhotonPlayer, (BattleRoyaleGearType)equipmentData.GearType, ammo);
			}
		}
	}
	public class BattleRoyaleGearBag : Photon.MonoBehaviour
	{
		private enum State
		{
			ON_BACK,
			NOT_ON_BACK
		}

		[Serializable]
		private struct BattleRoyaleGearSlotDescriptor
		{
			[SerializeField]
			public string Name;

			[SerializeField]
			public Transform SlotTransform;

			[SerializeField]
			public SpawnableToolType[] SupportedEquipmentTypes;
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Header("Settings")]
		[SerializeField]
		private Collider easyAccessCollider;

		[Header("Bag Slots")]
		[SerializeField]
		private BattleRoyaleGearSlotDescriptor[] bagSlotDescriptors;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip putOnSFX;

		[SerializeField]
		private RecRoomAudioClip takeOffSFX;

		[SerializeField]
		private RecRoomAudioClip hipAttachSFX;

		[SerializeField]
		private RecRoomAudioClip hipDetachSFX;

		[SerializeField]
		private RecRoomAudioClip[] modifyStoredToolSFX;

		private ManualUpdateStateMachine localStateMachine;

		private PhotonPlayer wearerPhotonPlayer;

		private Player wearerRecRoomPlayer;

		private List<ToolEquipSlot> bagSlots = new List<ToolEquipSlot>();

		private FirstPersonRendererHiding bagFirstPersonRenderers;

		private static Dictionary<string, object> LOCAL_PLAYER_INSTANTIATION_PARAMETERS;

		private static readonly string WEARER_ID_INSTANTIATION_PARAM_NAME = "PEB.WEARER_ID";

		private static readonly string PLAYER_SPAWNED_EQUIPMENT_PURPOSE_PARAM_NAME = "Purpose";

		private bool WearerIsLocal => wearerPhotonPlayer != null && wearerPhotonPlayer.IsLocal;

		private Vector3 WearerBackPosition
		{
			get
			{
				if (wearerRecRoomPlayer != null)
				{
					return wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.AttachPositionWorldSpace;
				}
				return base.transform.position;
			}
		}

		private Quaternion WearerBackRotation
		{
			get
			{
				if (wearerRecRoomPlayer != null)
				{
					return wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.AttachRotationWorldSpace;
				}
				return base.transform.rotation;
			}
		}

		private bool IsOnBack => localStateMachine.CurrentStateId == 0;

		protected override void Awake()
		{
			base.Awake();
			wearerPhotonPlayer = null;
			bool flag = false;
			if (tool.InstantiationParameters != null)
			{
				object value2;
				if (tool.InstantiationParameters.TryGetValue(WEARER_ID_INSTANTIATION_PARAM_NAME, out var value))
				{
					wearerPhotonPlayer = PhotonPlayer.Find((int)value);
					wearerRecRoomPlayer = wearerPhotonPlayer.ToPlayer();
				}
				else if (tool.InstantiationParameters.TryGetValue(PLAYER_SPAWNED_EQUIPMENT_PURPOSE_PARAM_NAME, out value2))
				{
					flag = true;
				}
			}
			if (flag)
			{
				if (easyAccessCollider != null)
				{
					easyAccessCollider.gameObject.SetActive(value: false);
				}
				UnityEngine.Object.Destroy(this);
				return;
			}
			tool.EquippedCollisionLayer = Layers.DynamicPhysicsIgnoreEnemyAndPlayerPhysics;
			tool.CustomSelectionForwarding = BagSelectionForwarding;
			if (WearerIsLocal)
			{
				bagFirstPersonRenderers = base.gameObject.AddComponent<FirstPersonRendererHiding>();
			}
			if (easyAccessCollider != null)
			{
				easyAccessCollider.gameObject.SetActive(value: false);
			}
			tool.PostAttachEvent += OnPostAttach;
			tool.PrePickupEvent += OnPrePickup;
			tool.PostResetEvent += OnReset;
			tool.AllowedToTransferOwnershipOnCollision = false;
			tool.AddCustomPickupCondition(BagPickupCondition);
			tool.ToolCleanup.CustomGetResetPositionAndOrientationBehavior = CustomToolResetBehavior;
			tool.SupportsAnimateIn = !WearerIsLocal;
			if (bagSlotDescriptors != null)
			{
				for (int i = 0; i < bagSlotDescriptors.Length; i++)
				{
					ToolEquipSlot toolEquipSlot = new ToolEquipSlot(ToolEquipSlot.EquipSlotType.Shoulder, this, bagSlotDescriptors[i].SlotTransform, i.ToString());
					toolEquipSlot.ToolEquipEvent = (ToolEquipSlot.EquipAction)Delegate.Combine(toolEquipSlot.ToolEquipEvent, new ToolEquipSlot.EquipAction(OnSlotEquip));
					toolEquipSlot.ToolUnequipEvent = (ToolEquipSlot.EquipAction)Delegate.Combine(toolEquipSlot.ToolUnequipEvent, new ToolEquipSlot.EquipAction(OnSlotUnequip));
					bagSlots.Add(toolEquipSlot);
				}
			}
			localStateMachine = new ManualUpdateStateMachine();
			localStateMachine.AddState(0, OnEnterOnBackState, null, null);
			localStateMachine.AddState(1, OnEnterNotOnBackState, null, null);
			localStateMachine.Initialize(0);
		}

		private void Start()
		{
			for (int i = 0; i < bagSlots.Count; i++)
			{
				bagSlots[i].InitializeOnStart();
			}
			if (wearerRecRoomPlayer != null)
			{
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.SupportsPreviewVisuals = false;
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.AddCustomDropCondition(ShoulderDropCondition);
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.CustomEquipBehavior = CustomShoulderEquipBehavior;
				tool.GetComponent<TaggedTool>().InitializeDefaultTagIds();
				wearerRecRoomPlayer.ToolEquipSlots.TryEquipTool(tool, null, wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot);
				wearerRecRoomPlayer.ToolEquipSlots.LeftHipSlot.ToolEquipEvent += OnHipEquip;
				wearerRecRoomPlayer.ToolEquipSlots.LeftHipSlot.ToolUnequipEvent += OnHipUnequip;
				wearerRecRoomPlayer.ToolEquipSlots.RightHipSlot.ToolEquipEvent += OnHipEquip;
				wearerRecRoomPlayer.ToolEquipSlots.RightHipSlot.ToolUnequipEvent += OnHipUnequip;
			}
			tool.SkinMapper.LocalApplyFavoriteSkin();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (wearerRecRoomPlayer != null)
			{
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.SupportsPreviewVisuals = true;
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.CustomEquipBehavior = null;
				wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.RemoveCustomDropCondition(ShoulderDropCondition);
				wearerRecRoomPlayer.ToolEquipSlots.LeftHipSlot.ToolEquipEvent -= OnHipEquip;
				wearerRecRoomPlayer.ToolEquipSlots.LeftHipSlot.ToolUnequipEvent -= OnHipUnequip;
				wearerRecRoomPlayer.ToolEquipSlots.RightHipSlot.ToolEquipEvent -= OnHipEquip;
				wearerRecRoomPlayer.ToolEquipSlots.RightHipSlot.ToolUnequipEvent -= OnHipUnequip;
			}
			for (int i = 0; i < bagSlots.Count; i++)
			{
				ToolEquipSlot toolEquipSlot = bagSlots[i];
				toolEquipSlot.ToolEquipEvent = (ToolEquipSlot.EquipAction)Delegate.Remove(toolEquipSlot.ToolEquipEvent, new ToolEquipSlot.EquipAction(OnSlotEquip));
				ToolEquipSlot toolEquipSlot2 = bagSlots[i];
				toolEquipSlot2.ToolUnequipEvent = (ToolEquipSlot.EquipAction)Delegate.Remove(toolEquipSlot2.ToolUnequipEvent, new ToolEquipSlot.EquipAction(OnSlotUnequip));
				if (bagSlots[i].EquippedTool != null)
				{
					OnSlotUnequip(bagSlots[i].EquippedTool, bagSlots[i]);
				}
			}
			tool.PostResetEvent -= OnReset;
			tool.PrePickupEvent -= OnPrePickup;
			tool.PostAttachEvent -= OnPostAttach;
		}

		private void OnDrawGizmos()
		{
			if (bagSlotDescriptors == null)
			{
				return;
			}
			for (int i = 0; i < bagSlotDescriptors.Length; i++)
			{
				if (bagSlotDescriptors[i].SlotTransform != null)
				{
					Gizmos.color = Color.blue;
					Gizmos.DrawSphere(bagSlotDescriptors[i].SlotTransform.position, 0.05f);
					Gizmos.DrawLine(bagSlotDescriptors[i].SlotTransform.position, bagSlotDescriptors[i].SlotTransform.position + bagSlotDescriptors[i].SlotTransform.forward * 0.1f);
				}
			}
		}

		public void DropAllEquipment()
		{
			if (base.hasAuthority)
			{
				for (int i = 0; i < bagSlots.Count; i++)
				{
					bagSlots[i].TryEquipTool(null);
				}
			}
		}

		private Tool BagSelectionForwarding(Player player, bool physicalPickup, Collider selectedCollider)
		{
			if (IsOnBack)
			{
				for (int i = 0; i < bagSlots.Count; i++)
				{
					if (bagSlots[i].IsFull)
					{
						return bagSlots[i].EquippedTool;
					}
				}
			}
			return tool;
		}

		private void OnPrePickup(Tool tool)
		{
			if (localStateMachine.CurrentStateId != 1)
			{
				AudioManager.Play3DSFX(takeOffSFX, base.transform);
				localStateMachine.EnterState(1);
			}
		}

		private void OnPostAttach(Tool tool)
		{
			if (localStateMachine.CurrentStateId != 0)
			{
				AudioManager.Play3DSFX(putOnSFX, base.transform);
				localStateMachine.EnterState(0);
			}
		}

		private void OnReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (WearerIsLocal)
			{
				tool.SupportsAnimateOut = true;
				if (base.hasAuthority)
				{
					wearerRecRoomPlayer.ToolEquipSlots.TryEquipTool(tool, null, wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot);
				}
			}
		}

		private bool BagPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (wearerPhotonPlayer != null && selectingPlayer.PhotonPlayer != wearerPhotonPlayer)
			{
				return false;
			}
			if (IsOnBack)
			{
				return false;
			}
			return true;
		}

		private bool CustomToolResetBehavior(out Vector3 position, out Quaternion orientation)
		{
			if (wearerRecRoomPlayer != null)
			{
				position = WearerBackPosition;
				orientation = WearerBackRotation;
				return true;
			}
			position = Vector3.zero;
			orientation = Quaternion.identity;
			return false;
		}

		private bool CustomShoulderEquipBehavior(Tool tool, PlayerToolEquipSlot equipSlot)
		{
			if (tool == this.tool)
			{
				return false;
			}
			if (IsOnBack)
			{
				StartCoroutine(DelayedTryStoreTool(tool));
			}
			return true;
		}

		private bool ShoulderDropCondition(Tool tool, PlayerToolEquipSlot slot)
		{
			return tool != this.tool;
		}

		private void OnHipEquip(Tool tool, PlayerToolEquipSlot slot)
		{
			AudioManager.Play3DSFX(hipAttachSFX, tool.transform.position);
		}

		private void OnHipUnequip(Tool tool, PlayerToolEquipSlot slot)
		{
			AudioManager.Play3DSFX(hipDetachSFX, tool.transform.position);
		}

		public bool TryStoreToolInBag(Tool tool)
		{
			if (tool == null || tool.IsHeld || !tool.IsValidAttach())
			{
				return false;
			}
			int num = -1;
			int num2 = -1;
			for (int i = 0; i < bagSlots.Count; i++)
			{
				if (bagSlotDescriptors[i].SupportedEquipmentTypes.Contains(tool.SpawnableToolType) && !bagSlots[i].IsOnEquipCooldown())
				{
					if (num < 0)
					{
						num = i;
					}
					if (!bagSlots[i].IsFull)
					{
						num2 = i;
						break;
					}
				}
			}
			if (num < 0)
			{
				return false;
			}
			if (num2 < 0)
			{
				num2 = num;
			}
			bagSlots[num2].TryEquipTool(tool);
			return false;
		}

		private void OnSlotEquip(Tool equippedTool, ToolEquipSlot attachedSLot)
		{
			AudioManager.PlayRandom3DSFX(modifyStoredToolSFX, base.transform);
			equippedTool.AddCustomPickupCondition(StoredToolPickupCondition);
			if (WearerIsLocal)
			{
				FirstPersonRendererHiding firstPersonRendererHiding = equippedTool.GetComponent<FirstPersonRendererHiding>();
				if (firstPersonRendererHiding == null)
				{
					firstPersonRendererHiding = equippedTool.gameObject.AddComponent<FirstPersonRendererHiding>();
				}
				if (wearerRecRoomPlayer != null && wearerRecRoomPlayer.BlobShadowProjector != null)
				{
					equippedTool.AddBlobShadowCasters(wearerRecRoomPlayer.BlobShadowProjector);
				}
				firstPersonRendererHiding.Hide();
			}
		}

		private void OnSlotUnequip(Tool unequippedTool, ToolEquipSlot attachedSLot)
		{
			AudioManager.PlayRandom3DSFX(modifyStoredToolSFX, base.transform);
			unequippedTool.RemoveCustomPickupCondition(StoredToolPickupCondition);
			tool.RigidbodyEx.UnityRigidbody.ResetCenterOfMass();
			if (WearerIsLocal)
			{
				FirstPersonRendererHiding component = unequippedTool.GetComponent<FirstPersonRendererHiding>();
				if (component != null)
				{
					component.Show(Layers.DynamicPhysics);
				}
				if (wearerRecRoomPlayer != null && wearerRecRoomPlayer.BlobShadowProjector != null)
				{
					unequippedTool.RemoveBlobShadowCasters(wearerRecRoomPlayer.BlobShadowProjector);
				}
			}
		}

		private bool StoredToolPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (wearerPhotonPlayer != null && wearerRecRoomPlayer != selectingPlayer)
			{
				return false;
			}
			if (!wearerRecRoomPlayer.ToolEquipSlots.ShoulderSlot.IsHandInSelectionVolume(selectionPoint))
			{
				return false;
			}
			return true;
		}

		private void OnEnterOnBackState(ushort previousStateId, ushort previousSubStateId)
		{
			if (WearerIsLocal && bagFirstPersonRenderers != null)
			{
				bagFirstPersonRenderers.Hide();
			}
			if (easyAccessCollider != null)
			{
				bool inVRDisplayMode = SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode;
				easyAccessCollider.gameObject.SetActive(WearerIsLocal && inVRDisplayMode);
			}
		}

		private void OnEnterNotOnBackState(ushort previousStateId, ushort previousSubStateId)
		{
			if (WearerIsLocal)
			{
				if (bagFirstPersonRenderers != null)
				{
					bagFirstPersonRenderers.Show(Layers.DynamicPhysics);
				}
				if (easyAccessCollider != null)
				{
					easyAccessCollider.gameObject.SetActive(value: false);
				}
			}
		}

		private IEnumerator DelayedTryStoreTool(Tool tool)
		{
			yield return null;
			TryStoreToolInBag(tool);
		}

		public static BattleRoyaleGearBag InstantiateForLocalPlayer(BattleRoyaleGearBag prefab)
		{
			Tool tool = null;
			if (prefab != null && Player.LocalPlayerExists)
			{
				Vector3 attachPositionWorldSpace = Player.LocalPlayer.ToolEquipSlots.ShoulderSlot.AttachPositionWorldSpace;
				Quaternion attachRotationWorldSpace = Player.LocalPlayer.ToolEquipSlots.ShoulderSlot.AttachRotationWorldSpace;
				if (LOCAL_PLAYER_INSTANTIATION_PARAMETERS == null)
				{
					LOCAL_PLAYER_INSTANTIATION_PARAMETERS = new Dictionary<string, object>();
				}
				else
				{
					LOCAL_PLAYER_INSTANTIATION_PARAMETERS.Clear();
				}
				LOCAL_PLAYER_INSTANTIATION_PARAMETERS.Add(WEARER_ID_INSTANTIATION_PARAM_NAME, PhotonNetwork.player.ID);
				tool = Tool.PhotonInstantiate(prefab.name, attachPositionWorldSpace, attachRotationWorldSpace, 1f, -1, LOCAL_PLAYER_INSTANTIATION_PARAMETERS);
			}
			return (!(tool != null)) ? null : tool.GetComponent<BattleRoyaleGearBag>();
		}
	}
	public class BattleRoyaleGearManager : Photon.MonoBehaviour
	{
		[Header("Player Bags")]
		[SerializeField]
		private BattleRoyaleGearBag bagPrefab;

		[SerializeField]
		private BattleRoyalePlayerMap mapPrefab;

		[Header("Equipment")]
		[SerializeField]
		private TextAsset arsenalBlob;

		[Header("Chests")]
		[SerializeField]
		private float chestEnabledPercentage = 0.5f;

		private BattleRoyaleGearBag localPlayerBag;

		private BattleRoyaleArsenalData arsenal;

		private LootTable<LootTable<int>> weaponLootTable = new LootTable<LootTable<int>>();

		private LootTable<int> accessoryLootTable;

		private LootTable<int> ammunitionLootTable;

		private int[] ammunitionLookupTable;

		private Dictionary<int, SynchronizedField<int[]>> allPlayerAmmo = new Dictionary<int, SynchronizedField<int[]>>();

		private const float CHEST_LOOT_SPAWN_ITEM_DELAY = 0.05f;

		private const float PLAYER_DEATH_AMMO_SPAWN_LINEAR_SPEED = 4f;

		private const float PLAYER_DEATH_AMMO_SPAWN_ANGULAR_SPEED = 720f;

		public static BattleRoyaleGearManager Instance { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			if (Instance == null)
			{
				Instance = this;
			}
			if (arsenalBlob != null && arsenalBlob.bytes != null)
			{
				arsenal = BattleRoyaleArsenalData.Parser.ParseFrom(arsenalBlob.bytes);
				InitializeLootTables();
			}
			BattleRoyaleAmmo.CollectEvent = (BattleRoyaleAmmo.CollectAction)Delegate.Combine(BattleRoyaleAmmo.CollectEvent, new BattleRoyaleAmmo.CollectAction(OnCollectAmmo));
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent += OnGameStart;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnedEquipmentInstantiatedEvent += OnEquipmentInstantiated;
			}
			if (Player.LocalPlayerExists)
			{
				OnLocalPlayerSpawn();
			}
			else
			{
				Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerSpawn);
			}
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Combine(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
		}

		private void Start()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledPlayerEvent += OnEnemyKilledPlayer;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			BattleRoyaleAmmo.CollectEvent = (BattleRoyaleAmmo.CollectAction)Delegate.Remove(BattleRoyaleAmmo.CollectEvent, new BattleRoyaleAmmo.CollectAction(OnCollectAmmo));
			EquipmentSpawnerChest.ChestOpenEvent = (EquipmentSpawnerChest.EquipmentSpawnerChestAction)Delegate.Remove(EquipmentSpawnerChest.ChestOpenEvent, new EquipmentSpawnerChest.EquipmentSpawnerChestAction(OnChestOpen));
			Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerSpawn);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent -= OnGameStart;
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilledPlayer;
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.EnemyKilledPlayerEvent -= OnEnemyKilledPlayer;
				}
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager != null)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SpawnedEquipmentInstantiatedEvent -= OnEquipmentInstantiated;
				}
			}
			if (Instance == this)
			{
				Instance = null;
			}
		}

		private void InitializeLootTables()
		{
			LootTable<int>[] array = new LootTable<int>[9];
			ammunitionLookupTable = new int[array.Length];
			for (int i = 0; i < ammunitionLookupTable.Length; i++)
			{
				ammunitionLookupTable[i] = -1;
			}
			for (int j = 0; j < arsenal.Gear.Count; j++)
			{
				if (!arsenal.Gear[j].IsAvailable)
				{
					continue;
				}
				BattleRoyaleGearType gearType = (BattleRoyaleGearType)arsenal.Gear[j].GearType;
				int num = (int)gearType;
				if (array[num] == null)
				{
					array[num] = new LootTable<int>();
				}
				array[num].AddLoot(j, arsenal.Gear[j].DropWeight);
				if (gearType == BattleRoyaleGearType.AMMUNITION)
				{
					BattleRoyaleGearType ammoGearType = (BattleRoyaleGearType)arsenal.Gear[j].AmmunitionData.AmmoGearType;
					int num2 = (int)ammoGearType;
					if (num2 >= 0 && num2 < ammunitionLookupTable.Length)
					{
						ammunitionLookupTable[num2] = j;
					}
				}
			}
			for (int k = 0; k < array.Length; k++)
			{
				BattleRoyaleGearType battleRoyaleGearType = (BattleRoyaleGearType)k;
				if (battleRoyaleGearType != BattleRoyaleGearType.ACCESSORY && battleRoyaleGearType != BattleRoyaleGearType.AMMUNITION && battleRoyaleGearType != BattleRoyaleGearType.GEAR_TYPE_COUNT && array[k] != null)
				{
					int gearTypeDropWeight = BattleRoyaleGearSettings.GetGearTypeDropWeight(battleRoyaleGearType);
					if (gearTypeDropWeight >= 0)
					{
						weaponLootTable.AddLoot(array[k], gearTypeDropWeight);
					}
				}
			}
			accessoryLootTable = array[7];
			ammunitionLootTable = array[8];
		}

		private void OnChestOpen(EquipmentSpawnerChest chest)
		{
			StartCoroutine(SpawnChestLootCoroutine(chest));
		}

		private IEnumerator SpawnChestLootCoroutine(EquipmentSpawnerChest chest)
		{
			float deltaArcAngle = 0.2f;
			chest.GetEquipmentSpawnPhysics(deltaArcAngle * 1f, out var position, out var orientation, out var linearVelocity, out var angularVelocity);
			BattleRoyaleGearType spawnedWeaponType;
			bool weaponSpawnSuccess = MasterTrySpawnWeapon(position, orientation, 1f, linearVelocity, angularVelocity, out spawnedWeaponType);
			WaitForSeconds wait = new WaitForSeconds(0.05f);
			yield return wait;
			chest.GetEquipmentSpawnPhysics(deltaArcAngle * 2f, out position, out orientation, out linearVelocity, out angularVelocity);
			MasterSpawnAccessory(position, orientation, 1f, linearVelocity, angularVelocity);
			yield return wait;
			if (weaponSpawnSuccess)
			{
				chest.GetEquipmentSpawnPhysics(deltaArcAngle * 3f, out position, out orientation, out linearVelocity, out angularVelocity);
				MasterSpawnAmmunition(spawnedWeaponType, position, orientation, 1f, linearVelocity, angularVelocity);
				yield return wait;
			}
			float finalSpawnArcAngle = ((!weaponSpawnSuccess) ? 3f : 4f) * deltaArcAngle;
			chest.GetEquipmentSpawnPhysics(finalSpawnArcAngle, out position, out orientation, out linearVelocity, out angularVelocity);
			MasterSpawnRandomAmmunition(position, orientation, 1f, linearVelocity, angularVelocity);
		}

		public int GetFieldAmmo(PhotonPlayer player, BattleRoyaleGearType ammoType)
		{
			SynchronizedField<int[]> playerAmmoField = GetPlayerAmmoField(player);
			return playerAmmoField.Get()[(int)ammoType];
		}

		public void SetFieldAmmo(PhotonPlayer player, BattleRoyaleGearType ammoType, int ammoValue)
		{
			SynchronizedField<int[]> playerAmmoField = GetPlayerAmmoField(player);
			int[] array = (int[])playerAmmoField.Get().Clone();
			array[(int)ammoType] = ammoValue;
			playerAmmoField.Set(array);
		}

		private void ClearAllLocalPlayerFieldAmmo()
		{
			SynchronizedField<int[]> playerAmmoField = GetPlayerAmmoField(PhotonNetwork.player);
			playerAmmoField.Set(new int[9]);
		}

		private SynchronizedField<int[]> GetPlayerAmmoField(PhotonPlayer player)
		{
			if (!allPlayerAmmo.TryGetValue(player.ID, out var value))
			{
				value = new SynchronizedField<int[]>(player, "AMMO", new int[9], SetterPermissionMode.ANYONE);
				allPlayerAmmo[player.ID] = value;
			}
			return value;
		}

		private void OnCollectAmmo(BattleRoyaleAmmo ammo)
		{
			if (ammo.hasAuthority && !ammo.AlreadyPickedUp)
			{
				ammo.AuthoritySetAlreadyPickedUp();
				int fieldAmmo = GetFieldAmmo(PhotonNetwork.player, ammo.AmmoType);
				SetFieldAmmo(PhotonNetwork.player, ammo.AmmoType, fieldAmmo + ammo.AmmoAmount);
			}
		}

		private void OnGameStart()
		{
			if (PhotonNetwork.isMasterClient)
			{
				for (int i = 0; i < EquipmentSpawnerChest.AllChests.Count; i++)
				{
					EquipmentSpawnerChest.AllChests[i].MasterEnable(UnityExtensions.GetRandomResult(chestEnabledPercentage));
				}
				for (int j = 0; j < EquipmentSpawnerChest.AllChests.Count; j++)
				{
					if (EquipmentSpawnerChest.AllChests[j].IsEnabled)
					{
						EquipmentSpawnerChest.AllChests[j].MasterReset();
					}
				}
			}
			ClearAllLocalPlayerFieldAmmo();
		}

		private void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (defender.IsLocal)
			{
				LocalPlayerDropAllEquipment();
			}
			if (PhotonNetwork.isMasterClient)
			{
				MasterSpawnKilledPlayerAmmo(defender);
			}
		}

		private void OnEnemyKilledPlayer(Enemy attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (defender.IsLocal)
			{
				LocalPlayerDropAllEquipment();
			}
			if (PhotonNetwork.isMasterClient)
			{
				MasterSpawnKilledPlayerAmmo(defender);
			}
		}

		private void LocalPlayerDropAllEquipment()
		{
			if (localPlayerBag != null)
			{
				localPlayerBag.DropAllEquipment();
			}
			Player.LocalPlayer.ReleaseToolsFromAllEquipSlots();
		}

		private void MasterSpawnKilledPlayerAmmo(PhotonPlayer killedPlayer)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			Player player = killedPlayer.ToPlayer();
			if (player == null)
			{
				return;
			}
			SynchronizedField<int[]> playerAmmoField = GetPlayerAmmoField(killedPlayer);
			int[] array = (int[])playerAmmoField.Get().Clone();
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] > 0)
				{
					Vector3 onUnitSphere = UnityEngine.Random.onUnitSphere;
					Vector3 angularVelocity = onUnitSphere * 720f * ((float)Math.PI / 180f);
					if (onUnitSphere.y < 0f)
					{
						onUnitSphere.y *= -1f;
					}
					Vector3 linearVelocity = (Vector3.up + onUnitSphere).normalized * 4f;
					MasterSpawnAmmunition((BattleRoyaleGearType)i, player.Body.transform.position, Quaternion.identity, 1f, linearVelocity, angularVelocity);
				}
				array[i] = 0;
			}
			playerAmmoField.Set(array);
		}

		private void OnLocalPlayerSpawn()
		{
			Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerSpawn);
			localPlayerBag = BattleRoyaleGearBag.InstantiateForLocalPlayer(bagPrefab);
			BattleRoyalePlayerMap.InstantiateForLocalPlayer(mapPrefab, localPlayerBag);
		}

		private bool MasterTrySpawnWeapon(Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity, out BattleRoyaleGearType spawnedWeaponType)
		{
			spawnedWeaponType = BattleRoyaleGearType.GEAR_TYPE_COUNT;
			if (!PhotonNetwork.isMasterClient)
			{
				return false;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null)
			{
				return false;
			}
			if (arsenal == null || arsenal.Gear == null || arsenal.Gear.Count <= 0)
			{
				return false;
			}
			LootTable<int> randomLoot = weaponLootTable.GetRandomLoot();
			if (randomLoot == null)
			{
				return false;
			}
			int randomLoot2 = randomLoot.GetRandomLoot();
			if (randomLoot2 < 0 || randomLoot2 >= arsenal.Gear.Count)
			{
				return false;
			}
			if (!TrySpawnGear(randomLoot2, spawnPoint, spawnOrientation, spawnScale, linearVelocity, angularVelocity))
			{
				return false;
			}
			spawnedWeaponType = (BattleRoyaleGearType)arsenal.Gear[randomLoot2].GearType;
			return true;
		}

		private void MasterSpawnAccessory(Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (PhotonNetwork.isMasterClient && !(NetworkedSingletonMonoBehaviour<GameManager>.Instance == null) && arsenal != null && arsenal.Gear != null && arsenal.Gear.Count > 0)
			{
				int randomLoot = accessoryLootTable.GetRandomLoot();
				if (randomLoot >= 0 && randomLoot < arsenal.Gear.Count)
				{
					TrySpawnGear(randomLoot, spawnPoint, spawnOrientation, spawnScale, linearVelocity, angularVelocity);
				}
			}
		}

		private void MasterSpawnRandomAmmunition(Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (PhotonNetwork.isMasterClient && !(NetworkedSingletonMonoBehaviour<GameManager>.Instance == null) && arsenal != null && arsenal.Gear != null && arsenal.Gear.Count > 0)
			{
				int randomLoot = ammunitionLootTable.GetRandomLoot();
				if (randomLoot >= 0 && randomLoot < arsenal.Gear.Count)
				{
					TrySpawnGear(randomLoot, spawnPoint, spawnOrientation, spawnScale, linearVelocity, angularVelocity);
				}
			}
		}

		private void MasterSpawnAmmunition(BattleRoyaleGearType ammunitionGearType, Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (!PhotonNetwork.isMasterClient || NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || arsenal == null || arsenal.Gear == null || arsenal.Gear.Count <= 0)
			{
				return;
			}
			if (ammunitionGearType >= BattleRoyaleGearType.WEAPON_PISTOL && (int)ammunitionGearType < ammunitionLookupTable.Length)
			{
				int num = ammunitionLookupTable[(int)ammunitionGearType];
				if (num >= 0 && num < arsenal.Gear.Count)
				{
					TrySpawnGear(num, spawnPoint, spawnOrientation, 1f, linearVelocity, angularVelocity);
				}
			}
		}

		private bool TrySpawnGear(int arsenalIndex, Vector3 spawnPoint, Quaternion spawnOrientation, float spawnScale, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			BattleRoyaleGearData battleRoyaleGearData = arsenal.Gear[arsenalIndex];
			if (battleRoyaleGearData == null)
			{
				return false;
			}
			SpawnableToolType equipmentId = (SpawnableToolType)battleRoyaleGearData.EquipmentId;
			if (equipmentId == SpawnableToolType.INVALID)
			{
				return false;
			}
			Tool tool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(equipmentId, spawnPoint, spawnOrientation, spawnScale, arsenalIndex, suppressAnimateInParticles: true, spawnIgnoringDynamicPhysics: true, suppressCleanup: true, suppressSkins: true);
			if (tool != null && tool.RigidbodyEx != null)
			{
				tool.RigidbodyEx.velocity = linearVelocity;
				tool.RigidbodyEx.angularVelocity = angularVelocity;
			}
			return true;
		}

		private void OnEquipmentInstantiated(SpawnableTool equipment)
		{
			int instantiationTag = equipment.InstantiationTag;
			if (instantiationTag >= 0 && instantiationTag < arsenal.Gear.Count)
			{
				BattleRoyaleGear battleRoyaleGear = equipment.gameObject.AddComponent<BattleRoyaleGear>();
				battleRoyaleGear.Initialize(arsenal.Gear[instantiationTag]);
			}
		}
	}
