		[SerializeField]
		private RecRoomAudioClip steerSFX;

		[SerializeField]
		private Transform steerLeftAudioOrigin;

		[SerializeField]
		private Transform steerRightAudioOrigin;

		[SerializeField]
		private AnimationCurve steerSFXCurve;

		[Header("Throttle Audio")]
		[SerializeField]
		private RecRoomAudioClip windSFX;

		[SerializeField]
		private AnimationCurve windSFXThrottleCurve;

		[SerializeField]
		private float throttleAudioDecelerateTime = 0.5f;

		[Header("Creak Audio")]
		[SerializeField]
		private RecRoomAudioClip[] handlebarCreakSFXChoices;

		[SerializeField]
		private float minCreakPeriod = 0.5f;

		[SerializeField]
		private float steerCreakThreshold = 0.5f;

		[SerializeField]
		private float throttleCreakThreshold = 0.4f;

		private bool destroyOnRiderExit;

		private Coroutine delayedDestroyCoroutine;

		private SFXAudioSource loopingWindSFX;

		private SFXAudioSource loopingSteerSFX;

		private SFXAudioSource loopingCanopySFX;

		private float smoothedAudioThrottle;

		private float smoothedAudioThrottleVelocity;

		private Vector2 previousSteerThrottle = Vector2.zero;

		private float lastCreakTime;

		private const float PLAYER_SAFETY_LANDING_RADIUS = 1f;

		private const float GLIDER_DELAYED_DESTROY_DURATION = 1f;

		[NonSerialized]
		public bool InDirectSteerMode;

		private bool _boardingEnabled = true;

		public bool BoardingEnabled
		{
			get
			{
				return _boardingEnabled;
			}
			set
			{
				_boardingEnabled = value;
				UpdatePortalLocking();
			}
		}

		protected override void Awake()
		{
			base.Awake();
			portal.LocalPlayerUseEvent += OnLocalPlayerUsePortal;
			portal.ChangeMode(TeleportationPortal.PortalMode.Nothing);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			portal.LocalPlayerUseEvent -= OnLocalPlayerUsePortal;
			StopLoopingAudio();
		}

		private void Update()
		{
			if (!InDirectSteerMode)
			{
				SteerInternal(handlebar.Throttle, handlebar.Steering);
			}
		}

		private void OnDrawGizmos()
		{
			Gizmos.color = Color.green;
			Gizmos.DrawWireSphere(base.transform.TransformPoint(collisionSphereOriginLocalposition), collisionSphereRadius);
		}

		public void SteerDirectly(float rawThrottle, float rawSteering)
		{
			if (InDirectSteerMode)
			{
				SteerInternal(rawThrottle, rawSteering);
			}
		}

		private void SteerInternal(float rawThrottle, float rawSteering)
		{
			float steering = Mathf.Sign(rawSteering) * steeringCurve.Evaluate(Mathf.Abs(rawSteering));
			float throttle = throttleCurve.Evaluate(rawThrottle);
			UpdateCanopy(throttle, steering);
			UpdateAudio(throttle, steering);
			UpdateVignetting(steering);
			AuthorityMove(throttle, steering);
		}

		private void UpdateCanopy(float throttle, float steering)
		{
			if (!(canopyVisual == null))
			{
				float num = 0f;
				if (throttle < 0f)
				{
					float t = Mathf.InverseLerp(-1f, 0f, throttle);
					num = Mathf.Lerp(negativeThrottleCanopyPitch, minThrottleCanopyPitch, t);
				}
				else
				{
					num = Mathf.Lerp(minThrottleCanopyPitch, maxThrottleCanopyPitch, throttle);
				}
				float z = steering * maxTurnCanopyRoll;
				canopyVisual.transform.localRotation = Quaternion.Euler(num, 0f, z);
			}
		}

		private void UpdateVignetting(float steering)
		{
			if (base.hasAuthority && base.Rider != null && base.Rider.IsLocal)
			{
				float vehicleVignetteIntensityInterpolation = steeringVignetteCurve.Evaluate(Mathf.Abs(steering));
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.SetVehicleVignetteIntensityInterpolation(vehicleVignetteIntensityInterpolation);
			}
		}

		private void UpdateAudio(float throttle, float steering)
		{
			if (base.Rider == null)
			{
				StopLoopingAudio();
			}
			else
			{
				if (loopingCanopySFX == null)
				{
					loopingCanopySFX = AudioManager.StartLooping3DSFX(canopyFlapSFX, base.transform);
				}
				if (loopingSteerSFX == null)
				{
					loopingSteerSFX = AudioManager.StartLooping3DSFX(steerSFX, base.transform.position);
				}
				if (steering < 0f)
				{
					loopingSteerSFX.transform.position = steerRightAudioOrigin.position;
				}
				else
				{
					loopingSteerSFX.transform.position = steerLeftAudioOrigin.position;
				}
				loopingSteerSFX.AudioSource.volume = steerSFXCurve.Evaluate(Mathf.Clamp01(Mathf.Abs(steering))) * steerSFX.volume;
				if (loopingWindSFX == null)
				{
					loopingWindSFX = AudioManager.StartLooping3DSFX(windSFX, base.transform);
				}
				float num = Mathf.Clamp01(throttle);
				float smoothTime = ((!(num < smoothedAudioThrottle)) ? 0f : throttleAudioDecelerateTime);
				smoothedAudioThrottle = Mathf.SmoothDamp(smoothedAudioThrottle, num, ref smoothedAudioThrottleVelocity, smoothTime);
				loopingWindSFX.AudioSource.volume = windSFXThrottleCurve.Evaluate(smoothedAudioThrottle) * windSFX.volume;
			}
			float num2 = Mathf.Abs(previousSteerThrottle.x);
			float num3 = Mathf.Abs(steering);
			if ((UnityEngine.Time.time - lastCreakTime >= minCreakPeriod && num2 < steerCreakThreshold && num3 >= steerCreakThreshold) || (previousSteerThrottle.y < throttleCreakThreshold && throttle >= throttleCreakThreshold))
			{
				AudioManager.PlayRandom3DSFX(handlebarCreakSFXChoices, handlebar.transform);
				lastCreakTime = UnityEngine.Time.time;
			}
			previousSteerThrottle = new Vector2(steering, throttle);
		}

		private void StopLoopingAudio()
		{
			if (loopingCanopySFX != null)
			{
				AudioManager.StopLoopingSFX(loopingCanopySFX);
				loopingCanopySFX = null;
			}
			if (loopingSteerSFX != null)
			{
				AudioManager.StopLoopingSFX(loopingSteerSFX);
				loopingSteerSFX = null;
			}
			if (loopingWindSFX != null)
			{
				AudioManager.StopLoopingSFX(loopingWindSFX);
				loopingWindSFX = null;
			}
		}

		private void AuthorityMove(float throttle, float steering)
		{
			if (!base.hasAuthority || (base.Rider == null && UnityEngine.Time.time - lastRiderExitTime >= postDisembarkSlowdownDuration))
			{
				return;
			}
			rigidbodyEx.targetRotation *= Quaternion.AngleAxis(steering * -1f * maxYawSpeed * UnityEngine.Time.deltaTime, Vector3.up);
			float num = 0f;
			float num2 = 0f;
			if (throttle < 0f)
			{
				float t = Mathf.InverseLerp(-1f, 0f, throttle);
				num = Mathf.Lerp(negativeThrottleForwardSpeed, minThrottleForwardSpeed, t);
				num2 = Mathf.Lerp(negativeThrottleFallingSpeed, minThrottleFallingSpeed, t);
			}
			else
			{
				num = Mathf.Lerp(minThrottleForwardSpeed, maxThrottleForwardSpeed, throttle);
				num2 = Mathf.Lerp(minThrottleFallingSpeed, maxThrottleFallingSpeed, throttle);
			}
			Vector3 vector = -1f * Vector3.up * num2;
			Vector3 vector2 = base.transform.forward * num;
			Vector3 velocity = vector2 + vector;
			if (MoveRigidbody(velocity) && base.Rider != null && base.Rider.IsLocal)
			{
				Vector3 autoDismountPoint = Vector3.zero;
				if (TryGetAutoDismountPoint(out autoDismountPoint))
				{
					Player.LocalPlayer.PlayerLocomotion.TeleportTo(autoDismountPoint, null, canCarryTools: true, null);
				}
			}
		}

		private bool MoveRigidbody(Vector3 velocity)
		{
			Vector3 desiredDisplacement = velocity * UnityEngine.Time.deltaTime;
			Vector3 vector = rigidbodyEx.TargetTransform.TransformPoint(collisionSphereOriginLocalposition);
			bool hitSomething = false;
			Vector3 vector2 = CollisionDetection.RunSphereCollisionDisplacement(vector, collisionSphereRadius, collisionSkinThickness, desiredDisplacement, 2048, collisionMaxIterations, 0.001f, out hitSomething);
			Vector3 vector3 = vector2 - vector;
			rigidbodyEx.targetPosition += vector3;
			return hitSomething;
		}

		private bool TryGetAutoDismountPoint(out Vector3 autoDismountPoint)
		{
			autoDismountPoint = Vector3.zero;
			Vector3 destinationPosition = portal.DestinationPosition;
			Vector3 position = base.transform.InverseTransformPoint(destinationPosition);
			Vector3 vector = rigidbodyEx.TargetTransform.TransformPoint(position);
			float num = 0.2f;
			float maxDistance = 2f;
			if (!Physics.Raycast(vector + Vector3.up * num, -Vector3.up, out var hitInfo, maxDistance, 2048, QueryTriggerInteraction.Ignore))
			{
				return false;
			}
			if (!CollisionDetection.CanPlayerStandOnCollider(hitInfo.collider, hitInfo.normal))
			{
				return false;
			}
			autoDismountPoint = hitInfo.point;
			return true;
		}

		private void UpdateParticles()
		{
			if (firstPersonParticles != null)
			{
				firstPersonParticles.gameObject.SetActive(base.Rider != null && base.Rider.IsLocal);
			}
		}

		protected override void OnRiderChange()
		{
			base.OnRiderChange();
			UpdatePortalLocking();
			UpdateParticles();
		}

		private void UpdatePortalLocking()
		{
			portal.IsLocked = base.Rider != null || !BoardingEnabled;
		}

		protected override void GetLocalRiderLocalPositionRotation(out Vector3 boardLocalPosition, out Quaternion boardLocalRotation)
		{
			Vector3 destinationPosition = portal.DestinationPosition;
			Vector3 destinationForward = portal.DestinationForward;
			SingletonMonoBehaviour<CameraRig>.Instance.TransformHeadFloorToRigPositionAndOrientation(destinationPosition, destinationForward, forwardInHeadSpace: true, out var rigPosition, out var rigRotation);
			boardLocalPosition = base.transform.InverseTransformPoint(rigPosition);
			boardLocalRotation = base.transform.InverseTransformRotation(rigRotation);
		}

		protected override void OnRiderExit(PhotonPlayer exitingRider)
		{
			base.OnRiderExit(exitingRider);
			if (exitingRider.IsLocal && destroyOnRiderExit)
			{
				StartDelayedDestroyCoroutine();
			}
			exitingRider.ToPlayer().PlayerEvents.ExitedGlider();
		}

		private void OnLocalPlayerUsePortal()
		{
			StartCoroutine(DelayedLocalPlayerBoard());
		}

		private void StartDelayedDestroyCoroutine()
		{
			if (delayedDestroyCoroutine == null)
			{
				delayedDestroyCoroutine = StartCoroutine(DelayedDestroyGlider());
			}
		}

		private IEnumerator DelayedDestroyGlider()
		{
			BoardingEnabled = false;
			yield return new WaitForSeconds(1f);
			if (this != null && base.hasAuthority)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}

		private IEnumerator DelayedLocalPlayerBoard()
		{
			yield return null;
			LocalPlayerBoard();
		}

		[PunRPC]
		private void RpcOnGliderDeploy(Vector3 deployPosition)
		{
			AudioManager.Play3DSFX(deploySFX, deployPosition);
		}

		public static BattleRoyaleGlider InstantiateForLocalPlayer(Vector3 position, Quaternion rotation, bool boardGlider, bool destroyOnRiderExit)
		{
			GameObject gameObject = PhotonNetwork.Instantiate("[Glider]", position, rotation, 1f, 0);
			if (gameObject == null)
			{
				return null;
			}
			BattleRoyaleGlider component = gameObject.GetComponent<BattleRoyaleGlider>();
			if (component == null)
			{
				return null;
			}
			component.destroyOnRiderExit = destroyOnRiderExit;
			if (Player.LocalPlayerExists && boardGlider)
			{
				if (component.animateInOut != null)
				{
					component.animateInOut.SupportsAnimateIn = false;
				}
				component.LocalPlayerBoard();
				component.photonView.RpcAll(component.RpcOnGliderDeploy, position);
			}
			return component;
		}
	}
	[RequireComponent(typeof(Tool))]
	public class BattleRoyaleGliderHandlebar : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private VirtualJoystickRigidbodyPickup pickup;

		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private BattleRoyaleGlider glider;

		[Header("Settings")]
		[SerializeField]
		private AnimationCurve settleSpeedCurve;

		private float settleStartTime;

		private Vector3 targetLocalPosition = Vector3.zero;

		private Quaternion targetLocalRotation = Quaternion.identity;

		public float Steering
		{
			get
			{
				float f = Vector3.Dot(base.transform.up, glider.RigidbodyEx.TargetTransform.right);
				return -1f * Mathf.InverseLerp(0f, 1f, Mathf.Abs(f)) * Mathf.Sign(f);
			}
		}

		public float Throttle
		{
			get
			{
				float f = Vector3.Dot(base.transform.up, glider.RigidbodyEx.TargetTransform.forward);
				return Mathf.InverseLerp(0f, 1f, Mathf.Abs(f)) * Mathf.Sign(f);
			}
		}

		public Tool Tool => tool;

		private void Awake()
		{
			tool.AttachEnabled = false;
			tool.AddCustomPickupCondition(CustomPickupCondition);
			tool.AllowedToTransferOwnershipOnCollision = false;
			tool.GravityPickupMode = Tool.GravityPickup.DISABLED;
			tool.AlwaysPhysicalPickupOffCenter = true;
			tool.PostReleaseEvent += OnToolRelease;
			glider.photonView.OwnerChangedEvent += OnGliderOwnerChange;
			tool.RigidbodyEx.AddKinematic(this);
			tool.RigidbodyEx.parent = glider.RigidbodyEx;
			targetLocalPosition = glider.transform.InverseTransformPoint(base.transform.position);
			targetLocalRotation = glider.transform.InverseTransformRotation(base.transform.rotation);
		}

		private void Start()
		{
			pickup.Pivot = glider.RigidbodyEx.TargetTransform;
			pickup.PivotLocalPosition = targetLocalPosition;
			pickup.PivotLocalRotation = targetLocalRotation;
		}

		private void OnDestroy()
		{
			if (tool != null)
			{
				tool.PostReleaseEvent -= OnToolRelease;
			}
			if (glider != null && glider.photonView != null)
			{
				glider.photonView.OwnerChangedEvent -= OnGliderOwnerChange;
			}
		}

		private void Update()
		{
			if (tool.hasAuthority && !tool.IsHeld)
			{
				tool.RigidbodyEx.targetLocalPosition = targetLocalPosition;
				float time = UnityEngine.Time.time - settleStartTime;
				float num = settleSpeedCurve.Evaluate(time);
				tool.RigidbodyEx.targetLocalRotation = Quaternion.RotateTowards(tool.RigidbodyEx.targetLocalRotation, targetLocalRotation, num * UnityEngine.Time.deltaTime);
			}
		}

		private void OnToolRelease(Tool tool)
		{
			settleStartTime = UnityEngine.Time.time;
		}

		private void OnGliderOwnerChange(int newOwnerId)
		{
			if (glider != null && glider.hasAuthority && tool != null)
			{
				tool.photonView.TransferOwnership(PhotonNetwork.player);
			}
		}

		private bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return glider != null && glider.Rider != null && glider.Rider == selectingPlayer.PhotonPlayer;
		}
	}
	[RequireComponent(typeof(SimpleVolume))]
	public class BattleRoyaleGliderSpawner : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private SimpleVolume volume;

		private const float SPAWN_VERTICAL_OFFSET = 3.5f;

		private const float SPAWN_FORWARD_OFFSET = 2f;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<BattleRoyaleGlider> m_LocalGliderSpawnEvent;

		public event Action<BattleRoyaleGlider> LocalGliderSpawnEvent
		{
			add
			{
				Action<BattleRoyaleGlider> action = this.m_LocalGliderSpawnEvent;
				Action<BattleRoyaleGlider> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalGliderSpawnEvent, (Action<BattleRoyaleGlider>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<BattleRoyaleGlider> action = this.m_LocalGliderSpawnEvent;
				Action<BattleRoyaleGlider> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalGliderSpawnEvent, (Action<BattleRoyaleGlider>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void LateUpdate()
		{
			if (Player.LocalPlayerExists && !Player.LocalPlayer.IsInVehicle && !Player.LocalPlayer.PlayerLocomotion.TeleportRunning && !Player.LocalPlayer.PlayerLocomotion.RotationBeingModified && volume.ContainsPoint(Player.LocalPlayer.Head.RigidbodyEx.targetPosition))
			{
				Vector3 normalized = Vector3.ProjectOnPlane(Player.LocalPlayer.Head.RigidbodyEx.TargetTransform.forward, Vector3.up).normalized;
				if (Vector3.Dot(normalized, base.transform.forward) <= 0f)
				{
					normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
				}
				Vector3 position = Player.LocalPlayer.CurrentFloorPosition + Vector3.up * 3.5f + normalized * 2f;
				Quaternion rotation = Quaternion.LookRotation(normalized, Vector3.up);
				BattleRoyaleGlider battleRoyaleGlider = BattleRoyaleGlider.InstantiateForLocalPlayer(position, rotation, boardGlider: true, destroyOnRiderExit: true);
				if (battleRoyaleGlider != null && this.LocalGliderSpawnEvent != null)
				{
					this.LocalGliderSpawnEvent(battleRoyaleGlider);
				}
			}
		}
	}
}
public class BattleRoyaleImageManager : UnityEngine.MonoBehaviour
{
	[Header("Rank Badges")]
	[SerializeField]
	private Sprite[] colorRankBadges;

	[SerializeField]
	private Sprite[] whiteRankBadges;

	public static BattleRoyaleImageManager Instance { get; private set; }

	public Sprite GetColorSpriteForRankIdx(int rankIdx)
	{
		if (colorRankBadges == null || colorRankBadges.Length == 0)
		{
			return null;
		}
		int num = Mathf.Clamp(rankIdx, 0, colorRankBadges.Length - 1);
		return colorRankBadges[num];
	}

	public Sprite GetWhiteSpriteForRankIdx(int rankIdx)
	{
		if (whiteRankBadges == null || whiteRankBadges.Length == 0)
		{
			return null;
		}
		int num = Mathf.Clamp(rankIdx, 0, whiteRankBadges.Length - 1);
		return whiteRankBadges[num];
	}

	private void Awake()
	{
		if (Instance == null)
		{
			Instance = this;
		}
	}

	private void OnDestroy()
	{
		if (Instance == this)
		{
			Instance = null;
		}
	}
}
