		private void InitializeSceneOnPreGame()
		{
			if (PhotonNetwork.isMasterClient && BattleRoyaleCableCar.Instance != null)
			{
				BattleRoyaleCableCar.Instance.MasterDisable();
			}
		}

		private void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoiningInProgress)
		{
			localPlayerHud = UnityEngine.Object.Instantiate(hudPrefab);
			localPlayerHud.Initialize(NetworkedSingletonMonoBehaviour<GameManager>.Instance, PhotonNetwork.player);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_1);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.OverrideSupportsOutOfBoundsForLocalPlayer = false;
			UpdatePlayerNameVisibility();
		}

		private void ResetLocalPlayer(bool localPlayerIsSpectator)
		{
			if (localPlayerHud != null)
			{
				UnityEngine.Object.Destroy(localPlayerHud.gameObject);
				localPlayerHud = null;
			}
		}

		private void OnLocalPlayerRespawn()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.SetLocalPlayerSpawnPointTag(SpawnPointTagType.TAG_2);
			}
			if (!hasRegisteredLocalPlayerCallbacks)
			{
				RegisterLocalPlayerEventCallbacks();
				hasRegisteredLocalPlayerCallbacks = true;
			}
			PhotonPlayer photonPlayer = Player.LocalPlayer.PhotonPlayer;
			if (IsPlayerEliminated(photonPlayer))
			{
				OnLocalPlayerGameOver(wasWinner: false);
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.OverrideSupportsOutOfBoundsForLocalPlayer = true;
			}
			else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(photonPlayer))
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.OverrideSupportsOutOfBoundsForLocalPlayer = true;
			}
		}

		private void OnLocalPlayerExitCableCar(BattleRoyaleCableCar cableCar)
		{
			StartCoroutine(PlayPlayerExitGondolaMusic());
			localPlayerGameStartTime = UnityEngine.Time.realtimeSinceStartup;
			hasReportedStats = false;
		}

		private IEnumerator PlayPlayerExitGondolaMusic()
		{
			AudioManager.MusicMixer.AddOverrideMusic(localPlayerExitGondolaMusic, this);
			AudioManager.MusicMixer.PlayOverrideMusic();
			yield return new WaitForSeconds(localPlayerExitGondolaMusic.audioClip.length + 0.1f);
			AudioManager.MusicMixer.StopOverrideMusic();
			AudioManager.MusicMixer.RemoveOverrideMusic(this);
		}

		private void OnLocalPlayerGameOver(bool wasWinner)
		{
			if (!Player.LocalPlayerExists || hasReportedStats)
			{
				return;
			}
			int value = 0;
			if (wasWinner)
			{
				value = 1;
			}
			else
			{
				float statLastChangeTime = 0f;
				if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(Player.LocalPlayer.PhotonPlayer, PlayerStatType.STAT_2, out value, out statLastChangeTime))
				{
					value = 16;
				}
			}
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SendGameOverChallengeEvent(isSpectator: false, wasWinner);
			Player.LocalPlayer.PlayerEvents.RecRoyalePlayerFinished(wasWinner, 1f);
			hasReportedStats = true;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomGameSettings.AllowRewards && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				RecNetRecRoyaleStats.MatchCompleteStats matchCompleteStats = new RecNetRecRoyaleStats.MatchCompleteStats();
				matchCompleteStats.Rank = value;
				matchCompleteStats.NumEliminations = localPlayerNumEliminations;
				matchCompleteStats.SecondsAlive = (localPlayerGameStartTime.HasValue ? ((int)(UnityEngine.Time.realtimeSinceStartup - localPlayerGameStartTime.Value)) : 0);
				matchCompleteStats.WalkGame = true;
				matchCompleteStats.CustomGame = !RecNet.Rooms.LocalRoomDetails.Room.IsAGRoom || GameSessions.LocalGameSession.Private;
				matchCompleteStats.ChestsOpened = numChestsOpened;
				matchCompleteStats.ShieldPotionsConsumed = numShieldPotionsConsumed;
				matchCompleteStats.HealthPotionsConsumed = numHealthPotionsConsumed;
				matchCompleteStats.SecondsInAir = ((localPlayerExitGliderTime.HasValue && localPlayerGameStartTime.HasValue) ? ((int)(localPlayerExitGliderTime.Value - localPlayerGameStartTime.Value)) : 0);
				RecNetRecRoyaleStats.SendMatchStats(matchCompleteStats);
				List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
				list.Add(new KeyValuePair<string, string>("rank", value.ToString()));
				list.Add(new KeyValuePair<string, string>("eliminations", localPlayerNumEliminations.ToString()));
				AnalyticsHelper.AddCustomStatsToActivityStats(list);
			}
			localPlayerNumEliminations = 0;
			localPlayerGameStartTime = null;
			numChestsOpened = 0;
			numHealthPotionsConsumed = 0;
			numShieldPotionsConsumed = 0;
			localPlayerExitGliderTime = null;
		}

		private void OnLocalPlayerScored(PhotonPlayer killedPlayer)
		{
			localPlayerNumEliminations++;
			bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(PhotonNetwork.player, killedPlayer);
			if (Player.LocalPlayerExists && !flag)
			{
				Player.LocalPlayer.PlayerEvents.RecRoyaleHeroTag(killedPlayer);
			}
		}

		private void OnLocalPlayerChestOpened()
		{
			numChestsOpened++;
		}

		private void OnLocalPlayerPotionConsumed(float healthAmount, float shieldAmount)
		{
			if (healthAmount > 0f)
			{
				numHealthPotionsConsumed++;
			}
			if (shieldAmount > 0f)
			{
				numShieldPotionsConsumed++;
			}
		}

		private void OnLocalPlayerExitGlider()
		{
			localPlayerExitGliderTime = UnityEngine.Time.realtimeSinceStartup;
		}

		private void RegisterLocalPlayerEventCallbacks()
		{
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.OpenedChestEvent += OnLocalPlayerChestOpened;
				Player.LocalPlayer.PlayerEvents.PotionConsumedEvent += OnLocalPlayerPotionConsumed;
				Player.LocalPlayer.PlayerEvents.ExitedGliderEvent += OnLocalPlayerExitGlider;
			}
		}

		private void UnregisterLocalPlayerEventCallbacks()
		{
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.OpenedChestEvent -= OnLocalPlayerChestOpened;
				Player.LocalPlayer.PlayerEvents.PotionConsumedEvent -= OnLocalPlayerPotionConsumed;
				Player.LocalPlayer.PlayerEvents.ExitedGliderEvent -= OnLocalPlayerExitGlider;
			}
		}

		private void OnGameStart()
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterInitializeCableCarOnGameStart();
				gameStateMachine.EnterState(0, 0);
			}
		}

		private void OnGameEnd()
		{
			if (PhotonNetwork.isMasterClient)
			{
				gameStateMachine.EnterState(ushort.MaxValue);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressPregameVO = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SuppressGameOverChallengeEvent = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsPlayingAgainInThisInstance = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameLeaveNotificationsDuringGameplay = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsPlayersLeaving = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.allowDevsAndCommunityTeamToStartWhileWaitingForPlayers = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.hasCustomGameOverFeedback = true;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameOver = false;
			GameManager.OnGameStartEvent += OnGameStart;
			GameManager.OnGameEndEvent += OnGameEnd;
			GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
			GameManager.InitializeLocalPlayerEvent += InitializeLocalPlayer;
			GameManager.ResetLocalPlayerEvent += ResetLocalPlayer;
			GameManager.OnPlayerOutOfBoundsEvent += MasterOnPlayerOutOfBounds;
			Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawn);
			BattleRoyaleCableCar.LocalPlayerExitEvent = (BattleRoyaleCableCar.CableCarAction)Delegate.Combine(BattleRoyaleCableCar.LocalPlayerExitEvent, new BattleRoyaleCableCar.CableCarAction(OnLocalPlayerExitCableCar));
			gameStateTimer = new SynchronizedTimer(this, "GSTIMER", SetterPermissionMode.MASTER);
			gameStateMachine = new SynchronizedStateMachine("BRSM", SetterPermissionMode.MASTER);
			gameStateMachine.AddState(ushort.MaxValue, null, null, null);
			gameStateMachine.AddState(0, OnEnterCableCarSuperState, null, null);
			gameStateMachine.AddState(0, 0, OnEnterSpawnInCableCarSubState, null, OnUpdateSpawnInCableCarSubState);
			gameStateMachine.AddState(0, 1, OnEnterCableCarFanfareSubState, OnExitCableCarFanfareSubState, OnUpdateCableCarFanfareSubState);
			gameStateMachine.AddState(1, OnEnterGameRunningState, OnExitGameRunningState, OnUpdateGameRunningState);
			gameStateMachine.AddState(1, 0, OnEnterWaitForPlayersToExitCableCarSubState, null, OnUpdateWaitForPlayersToExitCableCarSubState);
			gameStateMachine.AddState(1, 1, OnEnterWarnPlayersKickOutOfCableCarSubState, null, OnUpdateWarnPlayersKickOutOfCableCarSubState);
			gameStateMachine.AddState(1, 2, OnEnterKickPlayersOutOfCableCarSubState, OnExitKickPlayersOutOfCableCarSubState, OnUpdateKickPlayersOutOfCableCarSubState);
			gameStateMachine.AddState(1, 3, null, null, null);
			gameStateMachine.AddState(2, null, OnExitVictorySuperState, null);
			gameStateMachine.AddState(2, 0, OnEnterVictoryInitialFeedbackSubState, null, OnUpdateVictoryInitialFeedbackSubState);
			gameStateMachine.AddState(2, 1, OnEnterVictorySecondaryFeedbackSubState, null, OnUpdateVictorySecondaryFeedbackSubState);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterOnlyPlayerDeathEvent += OnMasterOnlyPlayerDeath;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent += OnPlayerDamagedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscDamagedPlayerEvent += OnMiscDamagedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDownedPlayerEvent += OnPlayerDownedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent += OnMiscKilledPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscDownedPlayerEvent += OnMiscDownedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.DownButNotOutKilledPlayerEvent += OnDBNOKilledPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent += OnPlayerRevive;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.StatsChangeEvent += OnPlayerStatChange;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent += OnPlayerTeamChange;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CustomDownButNotOutRespawnCondition = CustomDownButNotOutRespawnCondition;
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
			{
				OnGameStart();
			}
		}

		protected override void Start()
		{
			base.Start();
			gameStateMachine.Start(this, ushort.MaxValue);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawn);
			BattleRoyaleCableCar.LocalPlayerExitEvent = (BattleRoyaleCableCar.CableCarAction)Delegate.Remove(BattleRoyaleCableCar.LocalPlayerExitEvent, new BattleRoyaleCableCar.CableCarAction(OnLocalPlayerExitCableCar));
			UnregisterLocalPlayerEventCallbacks();
			GameManager.OnGameStartEvent -= OnGameStart;
			GameManager.OnGameEndEvent -= OnGameEnd;
			GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
			GameManager.InitializeLocalPlayerEvent -= InitializeLocalPlayer;
			GameManager.ResetLocalPlayerEvent -= ResetLocalPlayer;
			GameManager.OnPlayerOutOfBoundsEvent -= MasterOnPlayerOutOfBounds;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.CustomDownButNotOutRespawnCondition = null;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.StatsChangeEvent -= OnPlayerStatChange;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent -= OnPlayerTeamChange;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterOnlyPlayerDeathEvent -= OnMasterOnlyPlayerDeath;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent -= OnPlayerDamagedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscDamagedPlayerEvent -= OnMiscDamagedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDownedPlayerEvent -= OnPlayerDownedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent -= OnMiscKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscDownedPlayerEvent -= OnMiscDownedPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.DownButNotOutKilledPlayerEvent -= OnDBNOKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerRevivePlayerEvent -= OnPlayerRevive;
			}
		}

		private void Update()
		{
			gameStateTimer.UpdateCallbacks();
			gameStateMachine.Update();
			cachedNumPlayersRemaining = CalculateNumPlayersRemaining();
		}

		public bool IsPlayerEliminated(PhotonPlayer player, out float eliminationTime)
		{
			int value;
			return !NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(player, PlayerStatType.STAT_1, out value, out eliminationTime) || value == 1;
		}

		public bool IsPlayerEliminated(PhotonPlayer player)
		{
			int value;
			return !NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(player, PlayerStatType.STAT_1, out value) || value == 1;
		}

		public bool IsTeamEliminated(GameTeam team, out float eliminationTime)
		{
			eliminationTime = 0f;
			PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(team);
			PhotonPlayer[] array = teamPlayers;
			foreach (PhotonPlayer player in array)
			{
				float eliminationTime2 = 0f;
				if (!IsPlayerEliminated(player, out eliminationTime2))
				{
					return false;
				}
				eliminationTime = Mathf.Max(eliminationTime2, eliminationTime);
			}
			return true;
		}

		public bool CustomDownButNotOutRespawnCondition(PhotonPlayer player)
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player);
			PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(playerTeam);
			PhotonPlayer[] array = teamPlayers;
			foreach (PhotonPlayer player2 in array)
			{
				if (!IsPlayerEliminated(player2) && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.IsPlayerDownButNotOut(player2))
				{
					return false;
				}
			}
			return true;
		}

		private int CalculateNumPlayersRemaining()
		{
			int num = 0;
			IEnumerable<PhotonPlayer> activePlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers();
			foreach (PhotonPlayer item in activePlayers)
			{
				if (!IsPlayerEliminated(item))
				{
					num++;
				}
			}
			return num;
		}

		private string GetPlayerEliminationRankString(PhotonPlayer player)
		{
			if (!TryGetPlayerEliminationRank(player, out var rank))
			{
				return string.Empty;
			}
			return "#" + rank;
		}

		public bool TryGetPlayerEliminationRank(PhotonPlayer player, out int rank)
		{
			return NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(player, PlayerStatType.STAT_2, out rank) && rank > 0;
		}

		public bool TryGetLastTeamStanding(out GameTeam lastTeamStanding)
		{
			int num = 0;
			float num2 = 0f;
			lastTeamStanding = GameTeam.ANY;
			GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
			if (!activeTeams.Any())
			{
				return false;
			}
			GameTeam[] array = activeTeams;
			foreach (GameTeam gameTeam in array)
			{
				if (!IsTeamEliminated(gameTeam, out var eliminationTime))
				{
					num++;
					lastTeamStanding = gameTeam;
				}
				else if (num == 0 && eliminationTime >= num2)
				{
					num2 = eliminationTime;
					lastTeamStanding = gameTeam;
				}
			}
			return num < 2;
		}

		private int CalculatePlayerEliminationRank(PhotonPlayer thisPlayer)
		{
			if (!IsPlayerEliminated(thisPlayer, out var eliminationTime))
			{
				return 0;
			}
			IEnumerable<PhotonPlayer> activePlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers();
			int num = 0;
			foreach (PhotonPlayer item in activePlayers)
			{
				if (item != thisPlayer && (!IsPlayerEliminated(item, out var eliminationTime2) || eliminationTime2 > eliminationTime))
				{
					num++;
				}
			}
			return num + 1;
		}

		private void MasterInitializeCableCarOnGameStart()
		{
			if (PhotonNetwork.isMasterClient && !(BattleRoyaleCableCar.Instance == null))
			{
				if (!BattleRoyaleCableCar.Instance.hasAuthority)
				{
					BattleRoyaleCableCar.Instance.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				if (BattleRoyaleCableCarPathGenerator.Instance != null)
				{
					BattleRoyaleCableCar.Instance.FixedPathVehicle.AuthoritySetPathPoints(BattleRoyaleCableCarPathGenerator.Instance.GeneratePath());
				}
				BattleRoyaleCableCar.Instance.MasterEnable();
				SynchronizedField.SendPendingRoomUpdates();
			}
		}

		private void OnPlayerStatChange()
		{
			UpdatePlayerNameVisibility();
		}

		private void OnPlayerTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			UpdatePlayerNameVisibility();
		}

		private void UpdatePlayerNameVisibility()
		{
			float eliminationTime;
			bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && !IsGameEnding && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && !IsPlayerEliminated(PhotonNetwork.player, out eliminationTime);
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			for (int i = 0; i < otherPlayers.Length; i++)
			{
				Player player = otherPlayers[i].ToPlayer();
				if (player != null)
				{
					if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(otherPlayers[i], PhotonNetwork.player) || IsPlayerEliminated(otherPlayers[i], out eliminationTime))
					{
						player.PlayerUI.NamesHiddenFlag.Remove(this);
					}
					else if (flag)
					{
						player.PlayerUI.NamesHiddenFlag.Add(this);
					}
					else
					{
						player.PlayerUI.NamesHiddenFlag.Remove(this);
					}
				}
			}
		}

		private void OnMasterOnlyPlayerDeath(PhotonPlayer deadPlayer)
		{
			if (PhotonNetwork.isMasterClient)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(deadPlayer, PlayerStatType.STAT_1, 1);
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(deadPlayer, PlayerStatType.STAT_2, CalculatePlayerEliminationRank(deadPlayer));
				SynchronizedField.SendPendingRoomUpdates();
			}
		}

		private void OnPlayerDamagedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				Quaternion rotation = Quaternion.LookRotation(impactSurfaceNormal);
				if (shieldEffect == GameCombatManager.PlayerShieldEffect.DAMAGED)
				{
					AudioManager.Play3DSFX(playerShieldDamagedSFX, impactPoint);
					BattleRoyalePooledDamageParticles.TryPlayBattleRoyaleDamageParticlePrefab(playerShieldDamagedParticles, damage, impactPoint, rotation);
				}
				else
				{
					AudioManager.Play3DSFX(playerDamagedSFX, impactPoint);
					BattleRoyalePooledDamageParticles.TryPlayBattleRoyaleDamageParticlePrefab(playerDamagedParticles, damage, impactPoint, rotation);
				}
			}
		}

		private void OnMiscDamagedPlayer(PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
		}

		private void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			OnPlayerDamagedPlayer(attacker, defender, weapon, defenderImpactBodyPart, impactPoint, impactSurfaceNormal, damage, shieldEffect);
			if (defender.IsLocal)
			{
				PlayLocalPlayerDeathFeedback(attacker.NickName);
			}
			else if (attacker.IsLocal)
			{
				PlayLocalPlayerKilledOtherPlayerFeedback(defender, displayRank: true);
				OnLocalPlayerScored(defender);
			}
			else
			{
				PlayRemotePlayerDeathFeedback(defender, attacker.NickName);
			}
			if (PhotonNetwork.isMasterClient)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(attacker, PlayerStatType.STAT_3, (int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.TimeElapsed);
			}
		}

		private void OnMiscKilledPlayer(PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (defender.IsLocal)
			{
				PlayLocalPlayerDeathFeedback("The Swarm");
			}
			else
			{
				PlayRemotePlayerDeathFeedback(defender, "The Swarm");
			}
		}

		private void OnDBNOKilledPlayer(PhotonPlayer player)
		{
			if (player.IsLocal)
			{
				PlayLocalPlayerDBNODeathFeedback();
			}
			else
			{
				PlayRemotePlayerDBNODeathFeedback(player);
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(player, PlayerStatType.STAT_4, out var value))
			{
				PhotonPlayer photonPlayer = PhotonPlayer.Find(value);
				if (photonPlayer != null && photonPlayer.IsLocal)
				{
					OnLocalPlayerScored(player);
				}
			}
		}

		private void OnPlayerDownedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			OnPlayerDamagedPlayer(attacker, defender, weapon, defenderImpactBodyPart, impactPoint, impactSurfaceNormal, damage, shieldEffect);
			if (defender.IsLocal)
			{
				PlayLocalPlayerDownedFeedback(attacker.NickName);
			}
			else if (attacker.IsLocal)
			{
				PlayLocalPlayerDownedOtherPlayerFeedback(defender);
			}
			else
			{
				PlayRemotePlayerDownedFeedback(defender);
			}
			if (PhotonNetwork.isMasterClient)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(defender, PlayerStatType.STAT_4, attacker.ID);
			}
		}

		private void OnMiscDownedPlayer(PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (defender.IsLocal)
			{
				PlayLocalPlayerDownedFeedback("The Swarm");
			}
			else
			{
				PlayRemotePlayerDownedFeedback(defender);
			}
		}

		private void OnPlayerRevive(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 position)
		{
			AudioManager.Play3DSFX(playerReviveSFX, position);
			PooledParticle.TryPlayPrefab(playerReviveParticles, position);
			Vector3 vector = 0.35f * Vector3.up;
			WorldSpaceNotification.PlayNext("Revived!", 3f, null, followPlayer: false, position + vector);
			if (revivedPlayer.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You've been revived by " + revivingPlayer.NickName + "!", 2f);
			}
			else if (revivingPlayer.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You revived " + revivedPlayer.NickName + "!", 2f);
			}
			else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(revivedPlayer, PhotonNetwork.player))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Your Squad Mate " + revivedPlayer.NickName + " was revived!", 3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, revivedPlayer.NickName + " was revived!", 3f);
			}
			if (PhotonNetwork.isMasterClient)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(revivedPlayer, PlayerStatType.STAT_4, PhotonPlayer.Invalid);
			}
		}

