			{
				gameStateTimer.StartTimer(spawnInCableCarStateDuration);
			}
		}

		private void OnUpdateSpawnInCableCarSubState()
		{
			if (PhotonNetwork.isMasterClient && gameStateTimer.TimerOver)
			{
				gameStateMachine.EnterState(0, 1);
			}
