		private void OnEnterGameRunningState(ushort previousStateId, ushort previousSubStateId)
		{
			if (BattleRoyaleCableCar.Instance != null)
			{
				BattleRoyaleCableCar.Instance.DoorsLocked = false;
			}
			if (PhotonNetwork.isMasterClient && BattleRoyaleGameplayZone.Instance != null)
			{
				BattleRoyaleGameplayZone.Instance.MasterStart();
			}
		}

		private void OnUpdateGameRunningState()
		{
			if (PhotonNetwork.isMasterClient && TryGetLastTeamStanding(out var lastTeamStanding) && lastTeamStanding != GameTeam.ANY)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterArbitrarilySetWinningTeam(lastTeamStanding);
				gameStateMachine.EnterState(2, 0);
			}
		}

		private void OnExitGameRunningState(ushort nextStateId, ushort nextSubStateId)
		{
			if (PhotonNetwork.isMasterClient && BattleRoyaleCableCar.Instance != null)
			{
				BattleRoyaleCableCar.Instance.MasterDisable();
			}
			if (PhotonNetwork.isMasterClient && BattleRoyaleGameplayZone.Instance != null)
			{
				BattleRoyaleGameplayZone.Instance.MasterStop();
			}
		}

