		private bool IsLocalPlayerInCableCar()
		{
			if (BattleRoyaleCableCar.Instance == null)
			{
				return false;
			}
			if (!BattleRoyaleCableCar.Instance.FixedPathVehicle.LocalPlayerOccupies)
			{
				return false;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				return false;
			}
			if (IsPlayerEliminated(PhotonNetwork.player))
			{
				return false;
			}
			return true;
		}

		private void OnExitVictorySuperState(ushort nextStateId, ushort nextSubStateId)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetPhotonPlayerWon(PhotonNetwork.player) && Player.LocalPlayerExists)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Grab some props! Take a photo!'", 3f);
			}
		}

		private void OnEnterVictoryInitialFeedbackSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetPhotonPlayerWon(PhotonNetwork.player))
			{
				PlayLocalPlayerGameWinFeedback();
			}
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			PhotonPlayer[] playerList = PhotonNetwork.playerList;
			foreach (PhotonPlayer player in playerList)
			{
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetPhotonPlayerWon(player))
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterRequestPlayerInvincibility(player, victoryStateDuration);
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterResetPlayerHealth(player);
				}
			}
			gameStateTimer.StartTimer(4f);
		}

