			string playerEliminationRankString = GetPlayerEliminationRankString(PhotonNetwork.player);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "YOU WIN - SCOUT'S HONOR!  " + playerEliminationRankString, 5f);
		}

		private void OnEnterVictorySecondaryFeedbackSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetPhotonPlayerWon(PhotonNetwork.player))
			{
				PlayLocalPlayerGameLoseFeedback();
			}
			else
			{
				OnLocalPlayerGameOver(wasWinner: true);
			}
			if (PhotonNetwork.isMasterClient)
			{
				MasterPrepareCelebrationState();
				gameStateTimer.StartTimer(victoryStateDuration - 4f);
			}
		}

		private void OnUpdateVictorySecondaryFeedbackSubState()
		{
			if (PhotonNetwork.isMasterClient && gameStateTimer.TimerOver)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.MasterStopGame();
			}
		}

		private void PlayLocalPlayerGameLoseFeedback()
		{
			AudioManager.Play2DSFX(localPlayerLoseMusic);
			PhotonPlayer player = null;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetAnyPlayerOnWinningTeam(out player))
			{
				string text = player.NickName;
				PhotonPlayer[] teammatesOfPlayer = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeammatesOfPlayer(player);
				for (int i = 0; i < teammatesOfPlayer.Length; i++)
				{
					text += $" & {teammatesOfPlayer[i].NickName}";
				}
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "GAME OVER!", text + " WON", 3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "GAME OVER!", 3f);
			}
		}

		protected void MasterPrepareCelebrationState()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			GameTeam winningTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetWinningTeam();
			if (winningTeam == GameTeam.ANY)
			{
				return;
			}
			PhotonPlayer[] teamPlayersSortedByIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayersSortedByIndex(winningTeam);
			if (teamPlayersSortedByIndex == null || teamPlayersSortedByIndex.Length == 0)
			{
				return;
			}
			PhotonPlayer photonPlayer = null;
			int num = 0;
			PhotonPlayer[] array = teamPlayersSortedByIndex;
			foreach (PhotonPlayer photonPlayer2 in array)
			{
				int value = 0;
				bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.TryGetPlayerStat(photonPlayer2, PlayerStatType.STAT_3, out value);
				if (!IsPlayerEliminated(photonPlayer2) && (photonPlayer == null || (flag && value >= num)))
				{
					photonPlayer = photonPlayer2;
					if (flag)
					{
						num = value;
					}
				}
			}
			if (photonPlayer == null)
			{
				return;
			}
			Player player = photonPlayer.ToPlayer();
			if (player == null)
			{
				return;
			}
			winnerDoor.MasterSpawnWinnerDoorAndProps(player);
			float num2 = 100f;
			PhotonPlayer[] array2 = teamPlayersSortedByIndex;
			foreach (PhotonPlayer photonPlayer3 in array2)
			{
				Player player2 = photonPlayer3.ToPlayer();
				if (player2 != null && player2 != player && Player.DistanceSqrBetweenPlayers(player2, player) >= num2)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterRespawnPlayer(player2.PhotonPlayer, SpawnPointTagType.TAG_3, ignoreDefaultTag: true, dropTools: false, leftHandIsDominant: false, RequestedEquipmentSpawnParameters.Default, RequestedEquipmentSpawnParameters.Default, RequestedEquipmentSpawnParameters.Default, RequestedEquipmentSpawnParameters.Default, RequestedEquipmentSpawnParameters.Default, requestedEquipmentSuppressCleanup: true, requestGiftSpawn: false);
				}
			}
		}

		protected void MasterOnPlayerOutOfBounds(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient && IsPlayerEliminated(player))
			{
				base.photonView.RpcAll(RpcOnOutOfBoundsHitPlayer, player);
			}
		}

		[PunRPC]
		private void RpcOnOutOfBoundsHitPlayer(PhotonPlayer player)
		{
			if (player.IsLocal)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Out of Bounds!", 1.5f);
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
			}
		}
	}
	public class BattleRoyaleMapManager : UnityEngine.MonoBehaviour
	{
		[Header("World Space Corners")]
		[SerializeField]
		private Vector3 lowerLeftCornerWorldSpacePosition = Vector3.zero;

		[SerializeField]
		private Vector3 lowerRightCornerWorldSpacePosition = Vector3.zero;

		[SerializeField]
		private Vector3 upperLeftCornerWorldSpacePosition = Vector3.zero;

		private Vector3 worldSpaceIslandHorizontalAxis;

		private Vector3 worldSpaceIslandVerticalAxis;

		private float worldSpaceIslandHorizontalSize;

		private float worldSpaceIslandVerticalSize;

		public static BattleRoyaleMapManager Instance { get; private set; }

		private void Awake()
		{
			if (Instance == null)
			{
				Instance = this;
			}
			worldSpaceIslandHorizontalAxis = Vector3.ProjectOnPlane(lowerRightCornerWorldSpacePosition - lowerLeftCornerWorldSpacePosition, Vector3.up);
			worldSpaceIslandHorizontalSize = worldSpaceIslandHorizontalAxis.magnitude;
			worldSpaceIslandHorizontalAxis /= worldSpaceIslandHorizontalSize;
			worldSpaceIslandVerticalAxis = Vector3.ProjectOnPlane(upperLeftCornerWorldSpacePosition - lowerLeftCornerWorldSpacePosition, Vector3.up);
			worldSpaceIslandVerticalSize = worldSpaceIslandVerticalAxis.magnitude;
			worldSpaceIslandVerticalAxis /= worldSpaceIslandHorizontalSize;
		}

		private void OnDestroy()
		{
			if (Instance == this)
			{
				Instance = null;
			}
		}

		public Vector3 GetMapSpacePoint(Vector3 worldSpacePoint, Transform lowerLeftParent, Vector3 upperRightBound, float zOffset = 0f)
		{
			Vector3 normalizedMapSpacePoint = GetNormalizedMapSpacePoint(worldSpacePoint);
			Vector3 vector = lowerLeftParent.InverseTransformPoint(upperRightBound);
			return new Vector3(normalizedMapSpacePoint.x * vector.x, normalizedMapSpacePoint.y * vector.y, 0f - zOffset);
		}

		public Vector3 GetNormalizedMapSpacePoint(Vector3 worldSpacePoint, float zOffset = 0f)
		{
			Vector3 worldSpaceVector = worldSpacePoint - lowerLeftCornerWorldSpacePosition;
			Vector3 mapSpaceVector = GetMapSpaceVector(worldSpaceVector);
			return new Vector3(Mathf.Clamp01(mapSpaceVector.x / worldSpaceIslandHorizontalSize), Mathf.Clamp01(mapSpaceVector.y / worldSpaceIslandVerticalSize), 0f - zOffset);
		}

		public Quaternion GetMapSpaceRotation(Vector3 worldSpaceForward)
		{
			return Quaternion.LookRotation(Vector3.forward, GetMapSpaceVector(worldSpaceForward));
		}

		public float GetMapSpaceDistance(float worldSpaceDistance)
		{
			return Mathf.InverseLerp(0f, worldSpaceIslandHorizontalSize, worldSpaceDistance);
		}

		private Vector3 GetMapSpaceVector(Vector3 worldSpaceVector)
		{
			return Vector3.Dot(worldSpaceVector, worldSpaceIslandHorizontalAxis) * Vector3.right + Vector3.Dot(worldSpaceVector, worldSpaceIslandVerticalAxis) * Vector3.up;
		}
	}
	public class BattleRoyalePlayerCombatUI : PlayerCombatUI
	{
		protected override void UpdatePlayerHealth(bool resetHealth)
		{
			if (player == null)
			{
				return;
			}
			bool flag = false;
			if (BattleRoyaleManager.Instance != null)
			{
				flag = BattleRoyaleManager.Instance.IsPlayerEliminated(player);
			}
			if (flag)
			{
				if (dbnoBar != null)
				{
					dbnoBar.gameObject.SetActive(value: false);
				}
				if (healthBar != null)
				{
					healthBar.gameObject.SetActive(value: false);
				}
				if (shieldBar != null)
				{
					shieldBar.gameObject.SetActive(value: false);
				}
				if (icon != null)
				{
					icon.gameObject.SetActive(value: false);
				}
				if (reviveText != null)
				{
					reviveText.gameObject.SetActive(value: false);
				}
			}
			else
			{
				base.UpdatePlayerHealth(resetHealth);
			}
		}
	}
}
public class BattleRoyalePlayerCountDisplay : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private TextMesh playerCountText;

	[SerializeField]
	private GameObject displayGameObject;

	private int previousPlayersRemaining = -1;

	private void Update()
	{
		if (playerCountText != null && BattleRoyaleManager.Instance != null)
		{
			int numPlayersRemaining = BattleRoyaleManager.Instance.NumPlayersRemaining;
			if (numPlayersRemaining != previousPlayersRemaining)
