		public Transform OpenMapRoot => expandedRoot.transform;

		public Vector3 OpenMapWorldSpaceDimensions => expandedWorldSpaceDimensions;

		public bool PermanentOwnerIsLocal => permanentOwnerPhotonPlayer != null && permanentOwnerPhotonPlayer.IsLocal;

		protected override void Awake()
		{
			base.Awake();
			permanentOwnerPhotonPlayer = null;
			permanentOwnerEquipmentBag = null;
			if (tool.InstantiationParameters != null)
			{
				if (tool.InstantiationParameters.TryGetValue(PERMANENT_OWNER_ID_INSTANTIATION_PARAM_NAME, out var value))
				{
					permanentOwnerPhotonPlayer = PhotonPlayer.Find((int)value);
				}
				if (tool.InstantiationParameters.TryGetValue(BAG_ID_INSTANTIATION_PARAM_NAME, out var value2))
				{
					PhotonView photonView = PhotonView.Find((int)value2);
					permanentOwnerEquipmentBag = ((!(photonView != null)) ? null : photonView.GetComponent<BattleRoyaleGearBag>());
				}
			}
			localStateMachine.AddState(0, OnEnterCollapsedState, null, null);
			localStateMachine.AddState(1, OnEnterExpandedState, null, OnUpdateExpandedState);
			localStateMachine.Initialize(0);
			tool.AllowedToTransferOwnershipOnCollision = false;
			tool.AddCustomPickupCondition(MapPickupCondition);
			tool.PostResetEvent += OnToolReset;
			tool.PreAttachEvent += OnToolPreAttach;
			tool.PrePickupEvent += OnToolPrePickup;
			originalExpandedRootParent = expandedRoot.transform.parent;
			lowerLeftMapTransform.gameObject.SetActive(PermanentOwnerIsLocal);
			base.enabled = PermanentOwnerIsLocal;
			tool.SupportsAnimateIn = !PermanentOwnerIsLocal;
			if (PermanentOwnerIsLocal)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent += OnPlayerTeamChange;
			}
		}

		private void Start()
		{
			if (base.hasAuthority && permanentOwnerEquipmentBag != null)
			{
				permanentOwnerEquipmentBag.TryStoreToolInBag(tool);
			}
			if ((bool)tool.ToolCleanup)
			{
				tool.ToolCleanup.CustomGetResetPositionAndOrientationBehavior = CustomToolResetBehavior;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostResetEvent -= OnToolReset;
			tool.PreAttachEvent -= OnToolPreAttach;
			tool.PrePickupEvent -= OnToolPrePickup;
			if ((bool)NetworkedSingletonMonoBehaviour<GameManager>.Instance)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent -= OnPlayerTeamChange;
			}
		}

		private void Update()
		{
			localStateMachine.Update();
			if (permanentOwnerPhotonPlayer != null && permanentOwnerPhotonPlayer.IsLocal && !tool.IsHeld)
			{
				Vector3 position = permanentOwnerEquipmentBag.transform.position;
				float sqrMagnitude = (position - base.transform.position).sqrMagnitude;
				if (sqrMagnitude >= 9f)
				{
					ResetToBag();
				}
			}
		}

		public void ResetToBag()
		{
			Vector3 position = permanentOwnerEquipmentBag.transform.position;
			Quaternion rotation = permanentOwnerEquipmentBag.transform.rotation;
			tool.AuthorityResetToDefault(position, rotation, sleepPhysics: true);
		}

		public void DetachOpenMap()
		{
			tool.CanBeIgnored = false;
			if (expandedRoot.transform.parent != null)
			{
				expandedRoot.transform.SetParent(null);
			}
		}

		public void ReattachOpenMap()
		{
			tool.CanBeIgnored = true;
			if (expandedRoot.transform.parent != originalExpandedRootParent)
			{
				expandedRoot.transform.SetParent(originalExpandedRootParent, worldPositionStays: false);
				expandedRoot.transform.localPosition = Vector3.zero;
				expandedRoot.transform.localRotation = Quaternion.identity;
				expandedRoot.transform.localScale = Vector3.one;
			}
		}

		private void OnToolPreAttach(Tool tool)
		{
			if (localStateMachine.CurrentStateId != 0)
			{
				localStateMachine.EnterState(0);
			}
		}

		private void OnToolPrePickup(Tool tool)
		{
			if (localStateMachine.CurrentStateId != 1)
			{
				localStateMachine.EnterState(1);
			}
		}

		private void OnToolReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (base.hasAuthority && permanentOwnerEquipmentBag != null)
			{
				permanentOwnerEquipmentBag.TryStoreToolInBag(tool);
			}
		}

		private bool CustomToolResetBehavior(out Vector3 position, out Quaternion orientation)
		{
			if (permanentOwnerEquipmentBag != null)
			{
				position = permanentOwnerEquipmentBag.transform.position;
				orientation = permanentOwnerEquipmentBag.transform.rotation;
				return true;
			}
			position = Vector3.zero;
			orientation = Quaternion.identity;
			return false;
		}

		private bool MapPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return permanentOwnerPhotonPlayer == null || selectingPlayer.PhotonPlayer == permanentOwnerPhotonPlayer;
		}

		private void OnEnterCollapsedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (expandedRoot != null)
			{
				expandedRoot.SetActive(value: false);
			}
			if (collapsedRoot != null)
			{
				collapsedRoot.SetActive(value: true);
			}
		}

		private void OnEnterExpandedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (expandedRoot != null)
			{
				expandedRoot.SetActive(value: true);
			}
			if (collapsedRoot != null)
			{
				collapsedRoot.SetActive(value: false);
			}
			UpdateSquadMembers();
		}

		private void OnUpdateExpandedState()
		{
			if (!PermanentOwnerIsLocal)
			{
				lowerLeftMapTransform.gameObject.SetActive(value: false);
				base.enabled = false;
			}
			else if (Player.LocalPlayerExists)
			{
				UpdatePips();
				UpdateRings();
			}
		}

		private void OnPlayerTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			UpdateSquadMembers();
		}

		private void UpdatePips()
		{
			for (int i = 0; i < pips.Length; i++)
			{
				if (pips[i].player == null)
				{
					continue;
				}
				if (BattleRoyaleManager.Instance.IsPlayerEliminated(pips[i].player.PhotonPlayer))
				{
					pips[i].marker.sprite = eliminatedSprite;
					pips[i].marker.transform.localRotation = Quaternion.identity;
					continue;
				}
				pips[i].transform.localPosition = BattleRoyaleMapManager.Instance.GetMapSpacePoint(pips[i].player.Head.transform.position, lowerLeftMapTransform, upperRightMapTransform.position, zOffset);
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(pips[i].player.PhotonPlayer))
				{
					pips[i].marker.sprite = arrowSprite;
					pips[i].marker.transform.localRotation = BattleRoyaleMapManager.Instance.GetMapSpaceRotation(pips[i].player.Head.transform.forward);
				}
				else
				{
					pips[i].marker.sprite = downSprite;
					pips[i].marker.transform.localRotation = Quaternion.identity;
				}
			}
		}

		private void UpdateSquadMembers()
		{
			if (!PermanentOwnerIsLocal)
			{
				return;
			}
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			Color teamColor = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam);
			int teamMaxPlayerCount = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamMaxPlayerCount(playerTeam);
			bool flag = teamMaxPlayerCount > 1;
			int num = 1;
			pips[0].player = Player.LocalPlayer;
			pips[0].marker.gameObject.SetActive(value: true);
			pips[0].marker.transform.localScale = ((!flag) ? DEFAULT_PIP_SCALE : LOCAL_PLAYER_PIP_SCALE);
			pips[0].marker.color = ((!flag) ? DEFAULT_PIP_COLOR : teamColor);
			PhotonPlayer[] teammatesOfPlayer = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeammatesOfPlayer(PhotonNetwork.player);
			for (int i = 0; i < teammatesOfPlayer.Length; i++)
			{
				if (num >= pips.Length)
				{
					break;
				}
				Player player = teammatesOfPlayer[i].ToPlayer();
				if (player != null)
				{
					pips[num].player = player;
					pips[num].marker.gameObject.SetActive(value: true);
					pips[num].marker.transform.localScale = TEAMMATE_PIP_SCALE;
					pips[num].marker.color = teamColor;
					num++;
				}
			}
			for (int j = num; j < pips.Length; j++)
			{
				pips[j].marker.gameObject.SetActive(value: false);
			}
		}

		private void UpdateRings()
		{
			if (BattleRoyaleGameplayZone.Instance == null || !BattleRoyaleGameplayZone.Instance.RingsEnabled)
			{
				ringOverlayRenderer.Material.SetFloat(INNER_RING_RADIUS_UV_SHADER_ID, 4f);
				ringOverlayRenderer.Material.SetVector(INNER_RING_CENTER_UV_SHADER_ID, Vector3.zero);
				ringOverlayRenderer.Material.SetFloat(OUTER_RING_RADIUS_UV_SHADER_ID, 4f);
				ringOverlayRenderer.Material.SetVector(OUTER_RING_CENTER_UV_SHADER_ID, Vector3.zero);
				return;
			}
			float mapSpaceDistance = BattleRoyaleMapManager.Instance.GetMapSpaceDistance(BattleRoyaleGameplayZone.Instance.NextRingRadius);
			ringOverlayRenderer.Material.SetFloat(INNER_RING_RADIUS_UV_SHADER_ID, mapSpaceDistance);
			Vector3 normalizedMapSpacePoint = BattleRoyaleMapManager.Instance.GetNormalizedMapSpacePoint(BattleRoyaleGameplayZone.Instance.NextRingCenter);
			ringOverlayRenderer.Material.SetVector(INNER_RING_CENTER_UV_SHADER_ID, normalizedMapSpacePoint);
			float mapSpaceDistance2 = BattleRoyaleMapManager.Instance.GetMapSpaceDistance(BattleRoyaleGameplayZone.Instance.LocalRingRadius);
			ringOverlayRenderer.Material.SetFloat(OUTER_RING_RADIUS_UV_SHADER_ID, mapSpaceDistance2);
			Vector3 normalizedMapSpacePoint2 = BattleRoyaleMapManager.Instance.GetNormalizedMapSpacePoint(BattleRoyaleGameplayZone.Instance.LocalRingCenter);
			ringOverlayRenderer.Material.SetVector(OUTER_RING_CENTER_UV_SHADER_ID, normalizedMapSpacePoint2);
		}

		public static BattleRoyalePlayerMap InstantiateForLocalPlayer(BattleRoyalePlayerMap prefab, BattleRoyaleGearBag bag)
		{
			Tool tool = null;
			if (prefab != null && bag != null)
			{
				if (LOCAL_PLAYER_INSTANTIATION_PARAMETERS == null)
				{
					LOCAL_PLAYER_INSTANTIATION_PARAMETERS = new Dictionary<string, object>();
				}
				else
				{
					LOCAL_PLAYER_INSTANTIATION_PARAMETERS.Clear();
				}
				LOCAL_PLAYER_INSTANTIATION_PARAMETERS.Add(BAG_ID_INSTANTIATION_PARAM_NAME, bag.photonView.viewID);
				LOCAL_PLAYER_INSTANTIATION_PARAMETERS.Add(PERMANENT_OWNER_ID_INSTANTIATION_PARAM_NAME, PhotonNetwork.player.ID);
				tool = Tool.PhotonInstantiate(prefab.name, bag.transform.position, bag.transform.rotation, 1f, -1, LOCAL_PLAYER_INSTANTIATION_PARAMETERS);
				if (tool != null)
				{
					bag.TryStoreToolInBag(tool);
				}
			}
			return (!(tool != null)) ? null : tool.GetComponent<BattleRoyalePlayerMap>();
		}
	}
	public class BattleRoyalePooledDamageParticles : PooledParticle
	{
		[SerializeField]
		private float minDamageValue = 1f;

		[SerializeField]
		private float maxDamageValue = 30f;

		[Header("Impact Particle System")]
		[SerializeField]
		private ParticleSystem impactParticleSystem;

		[Header("Impact Particle Start Size")]
		[SerializeField]
		private float impactStartSizeMinDamage;

		[SerializeField]
		private float impactStartSizeMaxDamage;

		[Header("Impact Particle Start Lifetime")]
		[SerializeField]
		private float impactStartLifetimeMinDamage;

		[SerializeField]
		private float impactStartLifetimeMaxDamage;

		[Header("Spray Particle System")]
		[SerializeField]
		private ParticleSystem sprayParticleSystem;

		[Header("Spray Particle Burst Count")]
		[SerializeField]
		private int sprayBurstCountMinDamage;

		[SerializeField]
		private int sprayBurstCountMaxDamage;

		public static BattleRoyalePooledDamageParticles TryPlayBattleRoyaleDamageParticlePrefab(BattleRoyalePooledDamageParticles prefab, float damage, Vector3 position, Quaternion rotation)
		{
			BattleRoyalePooledDamageParticles battleRoyalePooledDamageParticles = ((!(prefab != null)) ? null : ObjectPool.Instance.Acquire(prefab));
			if (battleRoyalePooledDamageParticles != null)
			{
				battleRoyalePooledDamageParticles.SetDamageValue(damage);
				battleRoyalePooledDamageParticles.Play(position, rotation);
			}
			return battleRoyalePooledDamageParticles;
		}

		public void SetDamageValue(float damage)
		{
			float t = Mathf.InverseLerp(minDamageValue, maxDamageValue, damage);
			if (impactParticleSystem != null)
			{
				ParticleSystem.MainModule main = impactParticleSystem.main;
				main.startSize = Mathf.Lerp(impactStartSizeMinDamage, impactStartSizeMaxDamage, t);
				main.startLifetime = Mathf.Lerp(impactStartLifetimeMinDamage, impactStartLifetimeMaxDamage, t);
			}
			if (sprayParticleSystem != null)
			{
				ParticleSystem.EmissionModule emission = sprayParticleSystem.emission;
				emission.burstCount = Mathf.RoundToInt(Mathf.Lerp(sprayBurstCountMinDamage, sprayBurstCountMaxDamage, t));
			}
		}
	}
	public class BattleRoyalePosterSwap : UnityEngine.MonoBehaviour
	{
		[Header("Setup")]
		[SerializeField]
		private Renderer posterRenderer;

		[SerializeField]
		private int posterMaterialIndex;

		[Header("Poster Swap")]
		[SerializeField]
		private Material publicGamePosterMaterial;

		[SerializeField]
		private Material customRoomPosterMaterial;

		private void Awake()
		{
			if (Player.LocalPlayerExists)
			{
				OnLocalPlayerCreated();
			}
			else
			{
				Player.LocalPlayerCreatedEvent.Add(OnLocalPlayerCreated);
			}
		}

		private void OnDestroy()
		{
			Player.LocalPlayerCreatedEvent.Remove(OnLocalPlayerCreated);
		}

		private void OnLocalPlayerCreated()
		{
			if (posterRenderer == null)
			{
				return;
			}
			Material[] sharedMaterials = posterRenderer.sharedMaterials;
			if (posterMaterialIndex >= 0 && posterMaterialIndex < sharedMaterials.Length)
			{
				if (InCustomRoom())
				{
					sharedMaterials[posterMaterialIndex] = customRoomPosterMaterial;
				}
				else
				{
					sharedMaterials[posterMaterialIndex] = publicGamePosterMaterial;
				}
				posterRenderer.sharedMaterials = sharedMaterials;
			}
		}

		private bool InCustomRoom()
		{
			if (RecNet.Rooms.LocalRoomDetails.Room.IsAGRoom)
			{
				return false;
			}
			if (!CustomGameContainsRole("Walk"))
			{
				return false;
			}
			if (!CustomGameContainsRole("Teleport"))
			{
				return false;
			}
			return true;
		}

		private bool CustomGameContainsRole(string searchRoleName)
		{
			if (PlayerGameRoleManager.Instance == null)
			{
				return false;
			}
			List<GameRole> sortedActiveRoles = PlayerGameRoleManager.Instance.GetSortedActiveRoles();
			foreach (GameRole item in sortedActiveRoles)
			{
				if (item.RoleName == searchRoleName)
				{
					return true;
				}
			}
			return false;
		}
	}
	[Serializable]
	public struct PlayerRankPositionSettings
	{
		[Tooltip("An additional space to add to each player's local name height, offset by rank")]
		public float spaceBetweenRanks;

		[Tooltip("Spacing to add between player's in rank 2 and 3 (to help distinguish top positions)")]
		public float spaceBetweenSecondAndThirdRank;

		[Tooltip("Spacing to add between player's in rank 1 and 2 (to help distinguish top positions)")]
		public float spaceBetweenFirstAndSecondRank;

		[Tooltip("Default position for player's name relative to its token parent")]
		public Vector3 defaultPlayerNameLocalPosition;
	}
	public class BattleRoyaleVisitorMap : UnityEngine.MonoBehaviour
	{
		private enum MapVisibilityMode
		{
			NONE,
			BEES_AND_LIVE_PLAYERS,
			BEES_AND_PLAYER_DEATHS
		}

		[SerializeField]
		[Tooltip("How frequently (in frames) to check whether to update token position (one token per update). Higher is more performant")]
		private int updateFrequency = 10;

		[SerializeField]
		private GameObject mapTokenPrefab;

		[SerializeField]
		private GameObject beeRingVisualizerPrefab;

		[SerializeField]
		[Tooltip("If/when to track players and bee movement on this map.")]
		private MapVisibilityMode mode;

		[SerializeField]
		private PlayerRankPositionSettings settings = new PlayerRankPositionSettings
		{
			spaceBetweenRanks = 0.005f,
			spaceBetweenSecondAndThirdRank = 0.01f,
			spaceBetweenFirstAndSecondRank = 0.015f,
			defaultPlayerNameLocalPosition = new Vector3(0f, 0f, -0.06f)
		};

		private BattleRoyaleVisitorMapToken[] playerTokenObjects;

		private GameObject beeRingVisualizer;

		[SerializeField]
		private Transform lowerLeftMapTransform;

		[SerializeField]
		private Transform upperRightMapTransform;

		[SerializeField]
		private Collider mapCollider;

		private float ringHeightAdjustment = 1.2f;

		private int lastMovedTokenIndex;

		private bool gameIsRunning;

		private void Awake()
		{
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent += OnGameStart;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameEndedEvent += OnGameEnd;
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerEliminatedByPlayer;
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.DownButNotOutKilledPlayerEvent += OnPlayerEliminatedByDBNO;
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent += OnPlayerEliminatedByMisc;
				}
			}
			if (mode == MapVisibilityMode.NONE)
			{
				mapCollider.enabled = false;
			}
			else
			{
				InitializeMapObjects();
			}
		}

		private void OnDestroy()
		{
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameStartedEvent -= OnGameStart;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameEndedEvent -= OnGameEnd;
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent -= OnPlayerEliminatedByPlayer;
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.DownButNotOutKilledPlayerEvent -= OnPlayerEliminatedByDBNO;
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MiscKilledPlayerEvent -= OnPlayerEliminatedByMisc;
				}
			}
		}

		private void InitializeMapObjects()
		{
			int activePlayersMaxCount = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayersMaxCount();
			playerTokenObjects = new BattleRoyaleVisitorMapToken[activePlayersMaxCount];
			for (int i = 0; i < activePlayersMaxCount; i++)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(mapTokenPrefab, lowerLeftMapTransform);
				playerTokenObjects[i] = gameObject.GetComponent<BattleRoyaleVisitorMapToken>();
				gameObject.SetActive(value: false);
			}
			beeRingVisualizer = UnityEngine.Object.Instantiate(beeRingVisualizerPrefab, lowerLeftMapTransform);
			beeRingVisualizer.SetActive(value: false);
		}

		private void ResetMapObjects()
		{
			BattleRoyaleVisitorMapToken[] array = playerTokenObjects;
			foreach (BattleRoyaleVisitorMapToken battleRoyaleVisitorMapToken in array)
			{
				battleRoyaleVisitorMapToken.gameObject.SetActive(value: false);
			}
			beeRingVisualizer.SetActive(value: false);
		}

		private void OnPlayerEliminatedByPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (mode == MapVisibilityMode.BEES_AND_PLAYER_DEATHS)
			{
				ShowFinalMapPosition(defender, impactPoint, GetRank(defender));
			}
		}

		private void OnPlayerEliminatedByDBNO(PhotonPlayer player)
		{
			if (mode == MapVisibilityMode.BEES_AND_PLAYER_DEATHS)
			{
				Vector3 position = player.ToPlayer().Head.transform.position;
				ShowFinalMapPosition(player, position, GetRank(player));
			}
		}

		private void OnPlayerEliminatedByMisc(PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (mode == MapVisibilityMode.BEES_AND_PLAYER_DEATHS)
			{
				ShowFinalMapPosition(defender, impactPoint, GetRank(defender));
			}
		}

		private int GetRank(PhotonPlayer player)
		{
			int rank = -1;
			BattleRoyaleManager.Instance.TryGetPlayerEliminationRank(player, out rank);
			return rank;
		}

		private void ShowFinalMapPosition(PhotonPlayer player, Vector3 lastPosition, int rank)
		{
			BattleRoyaleVisitorMapToken[] array = playerTokenObjects;
			foreach (BattleRoyaleVisitorMapToken battleRoyaleVisitorMapToken in array)
			{
				if (battleRoyaleVisitorMapToken.CanBeSetByPlayer(player))
				{
					battleRoyaleVisitorMapToken.SetRankedPlayerInfo(player, settings, rank);
					battleRoyaleVisitorMapToken.transform.localPosition = GetLocalTokenPositionByWorldPoint(lastPosition);
					battleRoyaleVisitorMapToken.SetPlayerMarkerRotation(BattleRoyaleMapManager.Instance.GetMapSpaceRotation(player.ToPlayer().Head.transform.forward));
					battleRoyaleVisitorMapToken.gameObject.SetActive(value: true);
					break;
				}
			}
		}

		private void PopulateWinningPlayers()
		{
			if (!BattleRoyaleManager.Instance.TryGetLastTeamStanding(out var lastTeamStanding))
			{
				return;
			}
			PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(lastTeamStanding);
			string[] array = new string[teamPlayers.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = teamPlayers[i].NickName;
			}
			PhotonPlayer[] array2 = teamPlayers;
			foreach (PhotonPlayer photonPlayer in array2)
			{
				if (BattleRoyaleManager.Instance.IsPlayerEliminated(photonPlayer))
				{
					continue;
				}
				Transform transform = photonPlayer.ToPlayer().Head.transform;
				BattleRoyaleVisitorMapToken[] array3 = playerTokenObjects;
				foreach (BattleRoyaleVisitorMapToken battleRoyaleVisitorMapToken in array3)
				{
					if (battleRoyaleVisitorMapToken.CanBeSetByPlayer(photonPlayer))
					{
						battleRoyaleVisitorMapToken.SetWinningTeamInfo(photonPlayer, string.Join(", ", array), settings);
						battleRoyaleVisitorMapToken.transform.localPosition = GetLocalTokenPositionByWorldPoint(transform.position);
						battleRoyaleVisitorMapToken.SetPlayerMarkerRotation(BattleRoyaleMapManager.Instance.GetMapSpaceRotation(transform.forward));
						battleRoyaleVisitorMapToken.gameObject.SetActive(value: true);
						return;
					}
				}
			}
		}

		private void InitializeActivePlayerTokens()
		{
			int num = 0;
			foreach (PhotonPlayer activePlayer in NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayers())
			{
				if (num < playerTokenObjects.Length)
				{
					playerTokenObjects[num].SetPlayerInfo(activePlayer);
				}
				num++;
			}
		}

		private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
		{
			if (mode != MapVisibilityMode.BEES_AND_LIVE_PLAYERS)
			{
				return;
			}
			BattleRoyaleVisitorMapToken[] array = playerTokenObjects;
			foreach (BattleRoyaleVisitorMapToken battleRoyaleVisitorMapToken in array)
			{
				if (battleRoyaleVisitorMapToken.Player == null)
				{
					battleRoyaleVisitorMapToken.SetPlayerInfo(newPlayer);
					break;
				}
			}
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer newPlayer)
		{
			if (mode != MapVisibilityMode.BEES_AND_LIVE_PLAYERS)
			{
				return;
			}
			BattleRoyaleVisitorMapToken[] array = playerTokenObjects;
			foreach (BattleRoyaleVisitorMapToken battleRoyaleVisitorMapToken in array)
			{
				if (battleRoyaleVisitorMapToken.Player == newPlayer)
				{
					battleRoyaleVisitorMapToken.SetPlayerInfo(null);
					break;
				}
			}
		}

		private void OnGameStart()
		{
			if (mode == MapVisibilityMode.BEES_AND_LIVE_PLAYERS)
			{
				InitializeActivePlayerTokens();
			}
			lastMovedTokenIndex = 0;
			gameIsRunning = true;
		}

		private void OnGameEnd()
		{
			if (mode == MapVisibilityMode.BEES_AND_LIVE_PLAYERS)
			{
				ResetMapObjects();
			}
			else if (mode == MapVisibilityMode.BEES_AND_PLAYER_DEATHS)
			{
				PopulateWinningPlayers();
			}
			gameIsRunning = false;
		}

		private Vector3 GetLocalTokenPositionByWorldPoint(Vector3 point)
		{
			Vector3 mapSpacePoint = BattleRoyaleMapManager.Instance.GetMapSpacePoint(point, lowerLeftMapTransform, upperRightMapTransform.position);
			mapSpacePoint.z = GetMapColliderLocalHeight(mapSpacePoint);
			return mapSpacePoint;
		}

		private float GetMapColliderLocalHeight(Vector3 position)
		{
			Ray ray = new Ray(lowerLeftMapTransform.TransformPoint(position), Vector3.down);
			if (mapCollider.Raycast(ray, out var hitInfo, float.PositiveInfinity))
			{
				return lowerLeftMapTransform.InverseTransformPoint(hitInfo.point).z;
			}
			return position.z;
		}

		private void Update()
		{
			if (mode != MapVisibilityMode.NONE && this.IsStaggeredUpdateFrame(updateFrequency))
			{
				UpdateBees();
				if (mode == MapVisibilityMode.BEES_AND_LIVE_PLAYERS && gameIsRunning)
				{
					UpdateLivePlayers();
				}
			}
		}

		private void UpdateBees()
		{
			bool flag = BattleRoyaleGameplayZone.Instance != null && BattleRoyaleGameplayZone.Instance.RingsEnabled;
			beeRingVisualizer.gameObject.SetActive(flag);
			if (flag)
			{
				float mapSpaceDistance = BattleRoyaleMapManager.Instance.GetMapSpaceDistance(BattleRoyaleGameplayZone.Instance.LocalRingRadius);
				beeRingVisualizer.transform.localPosition = GetLocalTokenPositionByWorldPoint(BattleRoyaleGameplayZone.Instance.LocalRingCenter);
				beeRingVisualizer.transform.localScale = new Vector3(mapSpaceDistance, mapSpaceDistance, mapSpaceDistance * ringHeightAdjustment);
			}
		}

		private void UpdateLivePlayers()
		{
			for (int i = 0; i < playerTokenObjects.Length; i++)
			{
				int num = (i + lastMovedTokenIndex + 1) % playerTokenObjects.Length;
				PhotonPlayer player = playerTokenObjects[num].Player;
				if (player != null && !BattleRoyaleManager.Instance.IsPlayerEliminated(player, out var _))
				{
					Vector3 localTokenPositionByWorldPoint = GetLocalTokenPositionByWorldPoint(player.ToPlayer().Head.transform.position);
					playerTokenObjects[num].SetPlayerMarkerRotation(BattleRoyaleMapManager.Instance.GetMapSpaceRotation(player.ToPlayer().Head.transform.forward));
					playerTokenObjects[num].transform.localPosition = localTokenPositionByWorldPoint;
					playerTokenObjects[num].gameObject.SetActive(value: true);
					lastMovedTokenIndex = num;
					break;
				}
				playerTokenObjects[num].gameObject.SetActive(value: false);
			}
		}
	}
	public class BattleRoyaleVisitorMapToken : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private TextMesh playerName;

		[SerializeField]
		private GameObject playerMarkerRoot;

		[SerializeField]
		private MeshRenderer flagRenderer;

		private MaterialPropertyBlock materialProperties;

		public PhotonPlayer Player { get; private set; }

		public bool CanBeSetByPlayer(PhotonPlayer player)
		{
			bool flag = Player == null;
			if (!flag && player != null)
			{
				flag = player.ID == Player.ID;
			}
			return flag;
		}

		public void SetPlayerInfo(PhotonPlayer player)
		{
			Player = player;
			if (Player != null)
			{
				playerName.text = Player.NickName;
				GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(Player);
				SetPlayerTeamColor(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam));
			}
		}

		public void SetWinningTeamInfo(PhotonPlayer player, string roster, PlayerRankPositionSettings settings)
		{
			SetRankedPlayerInfo(player, settings, 1);
			playerName.text = $"#1: {roster}";
		}

		public void SetRankedPlayerInfo(PhotonPlayer player, PlayerRankPositionSettings settings, int rank)
		{
			Player = player;
			if (Player == null)
			{
				return;
			}
			if (rank > 0)
			{
				int activePlayersMaxCount = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayersMaxCount();
				playerName.text = $"#{rank}: {Player.NickName}";
				float num = (float)(activePlayersMaxCount - rank) * settings.spaceBetweenRanks;
				if (rank <= 2)
				{
					num = (float)(activePlayersMaxCount - 3) * settings.spaceBetweenRanks + settings.spaceBetweenSecondAndThirdRank;
					if (rank == 1)
					{
						num += settings.spaceBetweenFirstAndSecondRank;
					}
				}
				playerName.transform.localPosition = new Vector3(settings.defaultPlayerNameLocalPosition.x, settings.defaultPlayerNameLocalPosition.y, settings.defaultPlayerNameLocalPosition.z - num);
			}
			else
			{
				playerName.text = Player.NickName;
				playerName.transform.localPosition = settings.defaultPlayerNameLocalPosition;
			}
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(Player);
			SetPlayerTeamColor(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam));
		}

		public void SetPlayerTeamColor(Color color)
		{
			MeshRenderer component = playerName.gameObject.GetComponent<MeshRenderer>();
			if (materialProperties == null)
			{
				materialProperties = new MaterialPropertyBlock();
			}
			component.GetPropertyBlock(materialProperties);
			materialProperties.SetColor(ShaderIDs.COLOR, color);
			component.SetPropertyBlock(materialProperties);
			flagRenderer.GetPropertyBlock(materialProperties);
			materialProperties.SetColor(ShaderIDs.COLOR, color);
			flagRenderer.SetPropertyBlock(materialProperties);
		}

		public void SetPlayerMarkerRotation(Quaternion rotation)
		{
			playerMarkerRoot.transform.parent.localRotation = rotation;
		}
	}
	public class BattleRoyaleWinnerDoor : Photon.MonoBehaviour
	{
		[SerializeField]
		private BattleRoyaleWinnerSign winnerSign;

		private static SpawnableToolType[] randomProps = new SpawnableToolType[13]
		{
			SpawnableToolType.HAM,
			SpawnableToolType.PIRATE_FRYING_PAN,
			SpawnableToolType.PIRATE_FRYING_PAN,
			SpawnableToolType.PIRATE_PLUSH_FISH,
			SpawnableToolType.PIRATE_PLUSH_FISH,
			SpawnableToolType.CONFETTI_GUN,
			SpawnableToolType.CONFETTI_GUN,
			SpawnableToolType.BUCKET,
			SpawnableToolType.MARSHMALLOWSTICK,
			SpawnableToolType.MOCKTAIL_GOBLET,
			SpawnableToolType.MOCKTAIL_MARGARITA,
			SpawnableToolType.PIRATE_BEER_BOTTLE,
			SpawnableToolType.PIRATE_MUG
		};

		private static Vector3[] doorPlayerOffsets = new Vector3[32]
		{
			new Vector3(3f, 0f, 3f),
			new Vector3(-3f, 0f, 3f),
			new Vector3(2.5f, 0f, 2.5f),
			new Vector3(-2.5f, 0f, 2.5f),
			new Vector3(4f, 0f, 3f),
			new Vector3(-4f, 0f, 3f),
			new Vector3(4f, 0f, 4f),
			new Vector3(-4f, 0f, 4f),
			new Vector3(5f, 0f, 5f),
			new Vector3(-5f, 0f, 5f),
			new Vector3(2f, 0f, 3f),
			new Vector3(-2f, 0f, 3f),
			new Vector3(3f, 0f, 4f),
			new Vector3(-3f, 0f, 4f),
			new Vector3(1f, 0f, 3f),
			new Vector3(-1f, 0f, 3f),
			new Vector3(3f, 0f, 2f),
			new Vector3(-3f, 0f, 2f),
			new Vector3(3f, 0f, 0f),
			new Vector3(-3f, 0f, 0f),
			new Vector3(0f, 0f, 4f),
			new Vector3(0f, 0f, 6f),
			new Vector3(3f, 0f, -1.5f),
			new Vector3(-3f, 0f, -1.5f),
			new Vector3(3f, 0f, -3f),
			new Vector3(-3f, 0f, -3f),
			new Vector3(4f, 0f, -3f),
			new Vector3(-4f, 0f, -3f),
			new Vector3(4f, 0f, -4f),
			new Vector3(-4f, 0f, -4f),
			new Vector3(0f, 0f, -3f),
			new Vector3(0f, 0f, -5f)
		};

		public void MasterSpawnWinnerDoorAndProps(Player winner)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			Quaternion quaternion = Quaternion.Euler(0f, winner.Head.transform.rotation.eulerAngles.y, 0f);
			Vector3 doorPosition = Vector3.zero;
			Quaternion doorRotation = Quaternion.identity;
			bool flag = false;
			Vector3[] array = doorPlayerOffsets;
			foreach (Vector3 doorOffset in array)
			{
				if (TrySetDoorTransform(winner.CurrentFloorPosition, quaternion, doorOffset, out doorPosition, out doorRotation))
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				doorPosition = winner.CurrentFloorPosition + quaternion * Vector3.back * 0.5f;
				doorRotation = quaternion;
			}
			PhotonNetwork.InstantiateSceneObjectEx(base.name, doorPosition, doorRotation, 1f, 0, -1, null);
			Vector3 vector = winner.Head.transform.position + quaternion * Vector3.forward + Vector3.up * 0.5f;
			for (int j = 0; j < 3; j++)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnTool(winnerSign.name, vector + UnityEngine.Random.insideUnitSphere * 0.5f, UnityEngine.Random.rotation, 1f, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup: true);
			}
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(SpawnableToolType.HAM, vector + UnityEngine.Random.insideUnitSphere * 0.75f, UnityEngine.Random.rotation, 1f, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup: true);
			for (int k = 0; k < UnityEngine.Random.Range(3, 5); k++)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(randomProps.Random(), vector + UnityEngine.Random.insideUnitSphere * 0.75f, UnityEngine.Random.rotation, 1f, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup: true);
			}
		}

		private bool TrySetDoorTransform(Vector3 center, Quaternion faceRotation, Vector3 doorOffset, out Vector3 doorPosition, out Quaternion doorRotation)
		{
			doorPosition = center + faceRotation * doorOffset;
			if (doorOffset == Vector3.zero)
			{
				doorRotation = faceRotation;
			}
			else
			{
				Vector3 vector = center - doorPosition;
				vector.y = 0f;
				doorRotation = Quaternion.LookRotation(vector.normalized, Vector3.up);
			}
			RaycastHit hit;
			CollisionDetection.CollisionResult collisionResult = CollisionDetection.Raycast(doorPosition + Vector3.up, Vector3.down, 3f, 2049, out hit);
			if (collisionResult == CollisionDetection.CollisionResult.HIT)
			{
				doorPosition = hit.point;
				return !Physics.CheckSphere(doorPosition + Vector3.up, 0.75f, 2049, QueryTriggerInteraction.Ignore) && !Physics.CheckSphere(doorPosition + doorRotation * Vector3.forward + Vector3.up, 0.75f, 2049, QueryTriggerInteraction.Ignore);
			}
			return false;
		}
	}
