	public class FirstPersonRendererHiding : UnityEngine.MonoBehaviour
	{
		private MeshRenderer[] allRenderers;

		private List<MeshRenderer> shadowCasters;

		public void Hide()
		{
			if (allRenderers != null)
			{
				for (int i = 0; i < allRenderers.Length; i++)
				{
					allRenderers[i].gameObject.layer = 8;
				}
			}
			if (shadowCasters != null)
			{
				for (int j = 0; j < shadowCasters.Count; j++)
				{
					shadowCasters[j].enabled = true;
				}
			}
		}

		public void Show(Layers layer)
		{
			if (allRenderers != null)
			{
				for (int i = 0; i < allRenderers.Length; i++)
				{
					allRenderers[i].gameObject.layer = (int)layer;
				}
			}
			if (shadowCasters != null)
			{
				for (int j = 0; j < shadowCasters.Count; j++)
				{
					shadowCasters[j].enabled = false;
				}
			}
		}

		private void Awake()
		{
			allRenderers = GetComponentsInChildren<MeshRenderer>(includeInactive: true);
			shadowCasters = new List<MeshRenderer>();
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode != LocalPlayerController.DisplayMode.VR)
			{
				return;
			}
			for (int i = 0; i < allRenderers.Length; i++)
			{
				if (allRenderers[i].shadowCastingMode == ShadowCastingMode.On || allRenderers[i].shadowCastingMode == ShadowCastingMode.ShadowsOnly)
				{
					shadowCasters.Add(Player.CreateFirstPersonShadowCasterForMeshRenderer(allRenderers[i]));
				}
			}
		}
	}
