namespace RecRoom.Core.Vehicles
{
	[RequireComponent(typeof(Rigidbody))]
	[RequireComponent(typeof(RigidbodyEx))]
	[RequireComponent(typeof(SimpleVolume))]
	public class FixedPathVehicle : Photon.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private RigidbodyEx rigidbodyEx;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private SimpleVolume playerOccupancyVolume;

		[SerializeField]
		private float maxSpeed = 20f;

		private SynchronizedField<bool> _isRunning;

		private SynchronizedField<Vector3[]> _pathPoints;

		private SynchronizedField<int> _pathTargetIndex;

		private Vector3 velocity = Vector3.zero;

		private VehicleCollider[] colliders;

		private bool _localPlayerOccupies;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_LocalPlayerOccupiesChangeEvent;

		private const float MAX_POINT_REACH_DISTANCE = 1f;

		private const float MAX_POINT_REACH_DISTANCE_SQR = 1f;

		public RigidbodyEx RigidbodyEx => rigidbodyEx;

		public bool LocalPlayerOccupies
		{
			get
			{
				return _localPlayerOccupies;
			}
			set
			{
				bool localPlayerOccupies = _localPlayerOccupies;
				if (localPlayerOccupies != value)
				{
					_localPlayerOccupies = value;
					if (!_localPlayerOccupies && Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent == rigidbodyEx)
					{
						Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent = null;
					}
					else if (_localPlayerOccupies && Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent != rigidbodyEx)
					{
						Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent = rigidbodyEx;
					}
					if (this.LocalPlayerOccupiesChangeEvent != null)
					{
						this.LocalPlayerOccupiesChangeEvent();
					}
				}
			}
		}

		public bool IsRunning
		{
			get
			{
				return _isRunning.Get();
			}
			set
			{
				_isRunning.Set(value);
			}
		}

		private int PathTargetIndex
		{
			get
			{
				return _pathTargetIndex.Get();
			}
			set
			{
				_pathTargetIndex.Set(value);
			}
		}

		public event Action LocalPlayerOccupiesChangeEvent
		{
			add
			{
				Action action = this.m_LocalPlayerOccupiesChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalPlayerOccupiesChangeEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_LocalPlayerOccupiesChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalPlayerOccupiesChangeEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			rigidbodyEx.EnableProxyMovement(this);
			rigidbodyEx.AddUpdateLodOverride(this, UpdateLOD.TwoPointFiveMeters);
			colliders = GetComponentsInChildren<VehicleCollider>();
			for (int i = 0; i < colliders.Length; i++)
			{
				colliders[i].ThisVehicle = this;
			}
			_isRunning = new SynchronizedField<bool>(this, "ISRUN", defaultValue: false, SetterPermissionMode.AUTHORITY, OnIsRunningChange);
			_pathPoints = new SynchronizedField<Vector3[]>(this, "PATH_POINTS", new Vector3[0], SetterPermissionMode.AUTHORITY);
			_pathTargetIndex = new SynchronizedField<int>(this, "PTINDEX", 0, SetterPermissionMode.AUTHORITY);
		}

		private void Start()
		{
			OnIsRunningChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (rigidbodyEx != null)
			{
				rigidbodyEx.RemoveUpdateLodOverride(this);
			}
		}

		public void AuthoritySetPathPoints(Vector3[] pathPoints)
		{
			if (base.hasAuthority)
			{
				_pathPoints.Set(pathPoints);
			}
		}

		public void AuthoritySnapToFirstPathPoint()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Vector3[] array = _pathPoints.Get();
			if (array != null && array.Length != 0)
			{
				PathTargetIndex = 0;
				Vector3 vector = array[PathTargetIndex];
				Quaternion newRotation = base.transform.rotation;
				if (array.Length > 1)
				{
					newRotation = Quaternion.LookRotation((array[1] - vector).normalized, Vector3.up);
				}
				rigidbodyEx.SetDiscontinuousPositionAndRotation(vector, newRotation);
			}
		}

		private void Update()
		{
			LocalPlayerOccupies = Player.LocalPlayerExists && (Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent == null || Player.LocalPlayer.TrackingSpace.RigidbodyEx.parent == rigidbodyEx) && playerOccupancyVolume.ContainsPoint(Player.LocalPlayer.Head.RigidbodyEx.physicsPosition);
			if (base.hasAuthority)
			{
				AuthorityMove();
			}
		}

		private void AuthorityMove()
		{
			Vector3[] array = _pathPoints.Get();
			if (array == null || array.Length == 0 || !IsRunning)
			{
				return;
			}
			Vector3 vector = array[PathTargetIndex];
			Vector3 vector2 = vector - rigidbodyEx.targetPosition;
			if (vector2.sqrMagnitude <= 1f)
			{
				PathTargetIndex = GetWraparoundPathPointIndex(PathTargetIndex, 1);
				return;
			}
			Vector3 normalized = vector2.normalized;
			Vector3 rhs = rigidbodyEx.targetRotation * Vector3.forward;
			Vector3 forward = ((!(Vector3.Dot(normalized, rhs) < 0f)) ? normalized : (-normalized));
			rigidbodyEx.targetRotation = Quaternion.LookRotation(forward, Vector3.up);
			Vector3 vector3 = Vector3.zero;
			if (array.Length > 1)
			{
				int wraparoundPathPointIndex = GetWraparoundPathPointIndex(PathTargetIndex, -1);
				Vector3 vector4 = array[wraparoundPathPointIndex];
				Vector3 onNormal = vector - vector4;
				Vector3 vector5 = Vector3.Project(vector2, onNormal);
				vector3 = -(vector2 - vector5);
			}
			rigidbodyEx.targetPosition = Vector3.SmoothDamp(rigidbodyEx.targetPosition, vector, ref velocity, UnityEngine.Time.deltaTime, maxSpeed, UnityEngine.Time.deltaTime) - vector3;
		}

		private int GetWraparoundPathPointIndex(int currentIndex, int offset)
		{
			int num = _pathPoints.Get().Length;
			if (offset < 0)
			{
				offset = num - Mathf.Abs(offset) % num;
			}
			return (currentIndex + offset) % num;
		}

		private void OnIsRunningChange()
		{
			if (!IsRunning)
			{
				velocity = Vector3.zero;
			}
		}
	}
}
