namespace RecRoom.Activities.BattleRoyale
{
	public class VirtualJoystickRigidbodyPickup : RigidbodyPickup
	{
		[NonSerialized]
		public Transform Pivot;

		[NonSerialized]
		public Vector3 PivotLocalPosition;

		[NonSerialized]
		public Quaternion PivotLocalRotation;

		private Quaternion inversePickupRotation = Quaternion.identity;

		public override Vector3 TargetPosition
		{
			get
			{
				if (Pivot == null)
				{
					return base.transform.position;
				}
				return Pivot.TransformPoint(PivotLocalPosition);
			}
		}

		public override Quaternion TargetRotation
		{
			get
			{
				if (Pivot == null)
				{
					return base.transform.rotation;
				}
				Vector3 targetPosition = holder.targetPosition;
				Quaternion rotation = GetLocalHolderRotation(targetPosition) * inversePickupRotation;
				return Pivot.TransformRotation(rotation);
			}
		}

		public override void Pickup(RigidbodyEx holderRigidbodyEx, Vector3 holderSpacePickupPosition, Quaternion holderSpacePickupRotation)
		{
			Quaternion localHolderRotation = GetLocalHolderRotation(holderRigidbodyEx.targetPosition);
			inversePickupRotation = Quaternion.Inverse(localHolderRotation);
			base.Pickup(holderRigidbodyEx, holderSpacePickupPosition, holderSpacePickupRotation);
		}

		private Quaternion GetLocalHolderRotation(Vector3 holderPoint)
		{
			Vector3 vector = Pivot.InverseTransformPoint(holderPoint);
			Vector3 normalized = (PivotLocalPosition - vector).normalized;
			Vector3 rhs = PivotLocalRotation * Vector3.forward;
			Vector3 lhs = Vector3.Cross(normalized, rhs);
			rhs = Vector3.Cross(lhs, normalized);
			return Quaternion.LookRotation(rhs, normalized);
		}
	}
}
