namespace RecRoom
{
	public class RoomCalibration : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public struct CalibrationInstruction
		{
			public CalibrationState state;

			public string instructionText;

			public Sprite instructionSprite;
		}

		public enum CalibrationState
		{
			Invalid = -1,
			Started,
			Height,
			Verification,
			Warning,
			Finished,
			ConfirmStanding
		}

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action m_OnRoomCalibrationCompleted;

		[SerializeField]
		private float hmdToTopOfHead = 0.127f;

		[SerializeField]
		private float manualHeightAdjustIncrement = 0.0254f;

		[SerializeField]
		private CalibrationInstruction[] calibrationInstructions;

		[SerializeField]
		private Transform roomCenterTransform;

		[SerializeField]
		private GameObject trackerGizmo;

		[SerializeField]
		private GameObject showDuringVerification;

		[SerializeField]
		private Text heightMetersText;

		[SerializeField]
		private Text heightFeetText;

		[SerializeField]
		private Text cameraHeightMetersText;

		[SerializeField]
		private Text cameraHeightFeetText;

		[SerializeField]
		private Animator instructionsAnimator;

		private float heightEstimate_meters = 2f;

		[SerializeField]
		private Text instructionText;

		[SerializeField]
		private UnityEngine.UI.Image instructionImage;

		public static readonly string CALIBRATION_STATE_PREF = "RoomCalibrationState";

		public static readonly string CALIBRATION_HEIGHT_PREF = "CameraOffsetHeight";

		public static readonly string CALIBRATION_DEPTH_PREF = "CameraOffsetDepth";

		public static readonly string CALIBRATION_OFFCENTER_PREF = "CameraOffsetOffcenter";

		private const float MIN_TIME_PER_SUBSTATE = 2f;

		private const float MINIMUM_HEIGHT_METERS = 1f;

		private CalibrationState _currentState = CalibrationState.Invalid;

		private CalibrationState previousState = CalibrationState.Invalid;

		private Vector3 hmdPosition;

		private float trackerHeightFromGround;

		private float timeSinceSubStateStarted;

		public static bool LoadDormRoomOnCompletion = true;

		private CalibrationState CurrentState
		{
			get
			{
				return _currentState;
			}
			set
			{
				_currentState = value;
				timeSinceSubStateStarted = 0f;
				if (instructionsAnimator != null)
				{
					instructionsAnimator.SetTrigger("Spin");
				}
				else
				{
					UpdateInstructionsForCurrentState();
				}
			}
		}

		public static bool UsesRoomCalibration
		{
			get
			{
				if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
				{
					return false;
				}
				return SingletonMonoBehaviour<PlatformManager>.Instance != null && SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.PlayStation;
			}
		}

		public static bool RequiresCalibration => UsesRoomCalibration && (!PlayerPrefs.HasKey(CALIBRATION_STATE_PREF) || PlayerPrefs.GetInt(CALIBRATION_STATE_PREF) < 4);

		private VRInputHandler LeftHandInput => SingletonMonoBehaviour<InputManager>.Instance.LeftHandVRInputHandler;

		private VRInputHandler RightHandInput => SingletonMonoBehaviour<InputManager>.Instance.RightHandVRInputHandler;

		private bool LeftHandAvailable => LeftHandInput != null && LeftHandInput.IsConnected;

		private bool RightHandAvailable => RightHandInput != null && RightHandInput.IsConnected;

		private bool LeftTriggerDownNoLaser
		{
			get
			{
				FakePlayerHand playerHand = VRSplashScreenController.GetPlayerHand(PlayerHand.HandType.Left);
				bool flag = playerHand != null && playerHand.IsLaserActive;
				return LeftHandAvailable && LeftHandInput.HairTriggerButtonDown && !flag;
			}
		}

		private bool RightTriggerDownNoLaser
		{
			get
			{
				FakePlayerHand playerHand = VRSplashScreenController.GetPlayerHand(PlayerHand.HandType.Right);
				bool flag = playerHand != null && playerHand.IsLaserActive;
				return RightHandAvailable && RightHandInput.HairTriggerButtonDown && !flag;
			}
		}

		private bool AdjustUpButtonDown => (RightHandAvailable && RightHandInput.CalibrateUpButtonDown) || (LeftHandAvailable && LeftHandInput.CalibrateUpButtonDown);

		private bool AdjustDownButtonDown => (RightHandAvailable && RightHandInput.CalibrateDownButtonDown) || (LeftHandAvailable && LeftHandInput.CalibrateDownButtonDown);

		private bool RestartButtonDown => (RightHandAvailable && RightHandInput.CalibrateBackButtonDown) || (LeftHandAvailable && LeftHandInput.CalibrateBackButtonDown);

		public static event Action OnRoomCalibrationCompleted
		{
			add
			{
				Action action = RoomCalibration.m_OnRoomCalibrationCompleted;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref RoomCalibration.m_OnRoomCalibrationCompleted, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = RoomCalibration.m_OnRoomCalibrationCompleted;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref RoomCalibration.m_OnRoomCalibrationCompleted, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void Start()
		{
			PlayerPrefs.DeleteKey(CALIBRATION_STATE_PREF);
			PlayerPrefs.Save();
			if (showDuringVerification != null)
			{
				showDuringVerification.SetActive(value: false);
			}
			if (UsesRoomCalibration)
			{
				CurrentState = CalibrationState.Started;
			}
			else
			{
				OnCalibrationCompleted();
			}
			UpdateInstructionsForCurrentState();
		}

		private void Update()
		{
			UpdatePropPositions();
			UpdateCalibrationState();
		}

		public static void SaveRoomCalibration()
		{
			PlayerPrefs.SetInt(CALIBRATION_STATE_PREF, 4);
			PlayerPrefs.SetFloat(CALIBRATION_HEIGHT_PREF, SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition.y);
			PlayerPrefs.SetFloat(CALIBRATION_DEPTH_PREF, SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition.z);
			PlayerPrefs.SetFloat(CALIBRATION_OFFCENTER_PREF, SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition.x);
			PlayerPrefs.Save();
		}

		public static void LoadRoomCalibration()
		{
			if (!RequiresCalibration && UsesRoomCalibration)
			{
				float x = ((!PlayerPrefs.HasKey(CALIBRATION_OFFCENTER_PREF)) ? SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition.x : PlayerPrefs.GetFloat(CALIBRATION_OFFCENTER_PREF));
				Vector3 newOffset = new Vector3(x, PlayerPrefs.GetFloat(CALIBRATION_HEIGHT_PREF), PlayerPrefs.GetFloat(CALIBRATION_DEPTH_PREF));
				CameraStartPoint.UpdateOffset(newOffset);
			}
		}

		private void UpdateCalibrationState()
		{
			timeSinceSubStateStarted += UnityEngine.Time.deltaTime;
			switch (CurrentState)
			{
			case CalibrationState.Started:
				UpdateStartedState();
				break;
			case CalibrationState.ConfirmStanding:
				UpdateConfirmStandingState();
				break;
			case CalibrationState.Height:
				UpdateHeightState();
				break;
			case CalibrationState.Verification:
				UpdateVerificationState();
				break;
			case CalibrationState.Warning:
				UpdateWarningState();
				break;
			case CalibrationState.Finished:
				break;
			}
		}

		private void EnterState()
		{
			if (previousState != CurrentState && CurrentState != CalibrationState.Invalid)
			{
				previousState = CurrentState;
				if (CurrentState == CalibrationState.Started)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.transform.position = Vector3.zero;
					SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = Quaternion.identity;
				}
			}
		}

		public void UpdateInstructionsForCurrentState()
		{
			CalibrationInstruction calibrationInstruction = GetCalibrationInstruction(CurrentState);
			if (instructionText != null)
			{
				instructionText.text = calibrationInstruction.instructionText;
			}
			if (instructionImage != null)
			{
				instructionImage.sprite = calibrationInstruction.instructionSprite;
			}
		}

		private void UpdateStartedState()
		{
			EnterState();
			if (timeSinceSubStateStarted > 2f && (LeftTriggerDownNoLaser || RightTriggerDownNoLaser))
			{
				hmdPosition = GetHMDPositionRelativeToTracker();
				CameraStartPoint.UpdateOffset(new Vector3(0f - hmdPosition.x, SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition.y, 0f - hmdPosition.z));
				CurrentState = CalibrationState.ConfirmStanding;
			}
		}

		private void UpdateConfirmStandingState()
		{
			EnterState();
			if (timeSinceSubStateStarted > 2f && (LeftTriggerDownNoLaser || RightTriggerDownNoLaser))
			{
				CurrentState = CalibrationState.Height;
			}
		}

		public void RecenterPlayarea()
		{
			hmdPosition = GetHMDPositionRelativeToTracker();
		}

		private void UpdateHeightEstimate(float newEstimate_meters)
		{
			heightEstimate_meters = newEstimate_meters;
			trackerHeightFromGround = heightEstimate_meters - hmdToTopOfHead - hmdPosition.y;
			CameraStartPoint.UpdateOffset(new Vector3(0f - hmdPosition.x, trackerHeightFromGround, 0f - hmdPosition.z));
			if (heightMetersText != null)
			{
				heightMetersText.text = $"{heightEstimate_meters:0.00} m";
			}
			if (heightFeetText != null)
			{
				float num = 3.28084f;
				float num2 = heightEstimate_meters * num;
				int num3 = (int)num2;
				float num4 = num2 - (float)num3;
				int num5 = (int)(12f * num4 + 0.5f);
				if (num5 >= 12)
				{
					num3++;
					num5 %= 12;
				}
				heightFeetText.text = $"{num3} ft {num5} in";
			}
			if (cameraHeightMetersText != null)
			{
				cameraHeightMetersText.text = $"{trackerHeightFromGround:0.00} m";
			}
			if (cameraHeightFeetText != null)
			{
				float num6 = 3.28084f;
				float num7 = trackerHeightFromGround * num6;
				int num8 = (int)num7;
				float num9 = num7 - (float)num8;
				int num10 = (int)(12f * num9 + 0.5f);
				if (num10 >= 12)
				{
					num8++;
					num10 %= 12;
				}
				cameraHeightFeetText.text = $"{num8} ft {num10} in";
			}
		}

		private void UpdateHeightState()
		{
			EnterState();
			if (timeSinceSubStateStarted > 2f && (LeftTriggerDownNoLaser || RightTriggerDownNoLaser))
			{
				float magnitude = (LeftHandInput.WorldSpaceTrackedPosition - RightHandInput.WorldSpaceTrackedPosition).magnitude;
				magnitude = Math.Max(magnitude, 1f);
				UpdateHeightEstimate(magnitude);
				CurrentState = CalibrationState.Verification;
			}
		}

		[SkipRename]
		public void Button_RaiseHeight(PhysicalButtonBase button, Player player)
		{
			if (timeSinceSubStateStarted > 2f)
			{
				ManuallyRaiseHeight();
			}
		}

		[SkipRename]
		public void Button_LowerHeight(PhysicalButtonBase button, Player player)
		{
			if (timeSinceSubStateStarted > 2f)
			{
				ManuallyLowerHeight();
			}
		}

		[SkipRename]
		public void Button_StartOver(PhysicalButtonBase button, Player player)
		{
			if (timeSinceSubStateStarted > 2f)
			{
				CurrentState = CalibrationState.Started;
			}
		}

		[SkipRename]
		public void Button_Done(PhysicalButtonBase button, Player player)
		{
			if (timeSinceSubStateStarted > 2f)
			{
				FinishCalibrationAndGoToWarning();
			}
		}

		private void ManuallyRaiseHeight()
		{
			CameraStartPoint.UpdateOffset(SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition + Vector3.up * manualHeightAdjustIncrement);
			UpdateHeightEstimate(heightEstimate_meters + manualHeightAdjustIncrement);
		}

		private void ManuallyLowerHeight()
		{
			CameraStartPoint.UpdateOffset(SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition - Vector3.up * manualHeightAdjustIncrement);
			UpdateHeightEstimate(heightEstimate_meters - manualHeightAdjustIncrement);
		}

		private void UpdateVerificationState()
		{
			EnterState();
			if (AdjustUpButtonDown)
			{
				ManuallyRaiseHeight();
			}
			else if (AdjustDownButtonDown)
			{
				ManuallyLowerHeight();
			}
			else if (RestartButtonDown)
			{
				CurrentState = CalibrationState.Started;
			}
			else if (timeSinceSubStateStarted > 2f && (LeftTriggerDownNoLaser || RightTriggerDownNoLaser))
			{
				FinishCalibrationAndGoToWarning();
			}
		}

		private void FinishCalibrationAndGoToWarning()
		{
			SaveRoomCalibration();
			CurrentState = CalibrationState.Warning;
		}

		private void UpdateWarningState()
		{
			EnterState();
			if (timeSinceSubStateStarted > 2f && (LeftTriggerDownNoLaser || RightTriggerDownNoLaser))
			{
				OnCalibrationCompleted();
			}
		}

		public static Vector3 GetHMDPositionRelativeToTracker()
		{
			return Vector3.zero;
		}

		public static Vector3 GetTrackerWorldPosition()
		{
			return SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position - GetHMDPositionRelativeToTracker();
		}

		private void OnCalibrationCompleted()
		{
			if (RoomCalibration.OnRoomCalibrationCompleted != null)
			{
				RoomCalibration.OnRoomCalibrationCompleted();
			}
			if (Profiles.LocalProfile != null && LoadDormRoomOnCompletion)
			{
				GameSessions.GoToDormRoom();
			}
		}

		private CalibrationInstruction GetCalibrationInstruction(CalibrationState state)
		{
			CalibrationInstruction result = default(CalibrationInstruction);
			if (calibrationInstructions != null)
			{
				CalibrationInstruction[] array = calibrationInstructions;
				for (int i = 0; i < array.Length; i++)
				{
					CalibrationInstruction result2 = array[i];
					if (result2.state == state)
					{
						return result2;
					}
				}
			}
			return result;
		}

		private void UpdatePropPositions()
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position;
			Vector3 trackerWorldPosition = GetTrackerWorldPosition();
			trackerGizmo.transform.position = trackerWorldPosition;
			Vector3 position2 = trackerWorldPosition - SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition;
			position2.y = 0f;
			roomCenterTransform.position = position2;
			if (showDuringVerification != null)
			{
				showDuringVerification.SetActive(CurrentState == CalibrationState.Verification);
			}
		}
	}
