public class SoccerManager : GameRuleManager
{
	public enum SoccerGameStates
	{
		PRE_ROUND = 0,
		ROUND_RUNNING = 1,
		BALL_SCORED = 2,
		INVALID = 65535
	}

	private const float ROUND_START_STATE_DURATION = 3f;

	private const float BALL_SCORED_STATE_DURATION = 3f;

	[Header("SFX and VO")]
	[SerializeField]
	private RecRoomAudioClip blueTeamScoreSFX;

	[SerializeField]
	private RecRoomAudioClip redTeamScoreSFX;

	[SerializeField]
	private RecRoomAudioClip goalSFX;

	[SerializeField]
	private RecRoomAudioClip goalVO;

	[SerializeField]
	private RecRoomAudioClip powerupPickupSFX;

	private SynchronizedStateMachine soccerStateMachine;

	private SynchronizedTimer masterSoccerStateTimer;

	private SoccerBall ball;

	private SoccerGarageDoor garageDoor;

	private LegacyPowerupSpawner[] powerupSpawnPoints;

	private readonly List<SoccerPowerup> cachedPowerups = new List<SoccerPowerup>();

	[SerializeField]
	private Transform soccerBallSpawnTransform;

	public new static SoccerManager Instance => NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance as SoccerManager;

	public override string RuleTypeAutoTag => "soccer";

	protected override void Awake()
	{
		base.Awake();
		GameManager.OnGameStartEvent += OnGameStart;
		GameManager.OnGameEndEvent += OnGameEnd;
		GameManager.InitializeSceneOnPreGameEvent += InitializeSceneOnPreGame;
		soccerStateMachine = new SynchronizedStateMachine("SOCCER", SetterPermissionMode.MASTER);
		soccerStateMachine.AddState(ushort.MaxValue, null, null, null);
		soccerStateMachine.AddState(0, OnEnterPreRoundState, OnExitPreRoundState, OnUpdatePreRoundState);
		soccerStateMachine.AddState(1, OnEnterRoundRunningState, OnExitRoundRunningState, null);
		soccerStateMachine.AddState(2, OnEnterBallScoredState, OnExitBallScoredState, OnUpdateBallScoredState);
		masterSoccerStateTimer = new SynchronizedTimer(this, "SOCCER_TIMER", SetterPermissionMode.MASTER);
		List<SoccerBall> list = this.FindAllObjectsOfType<SoccerBall>();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].GetComponent<GamePracticeObject>() == null)
			{
				ball = list[i];
				break;
			}
		}
		if (ball == null)
		{
			UnityEngine.Debug.LogError("There is no non-practice soccer ball in the soccer scene.");
		}
		else
		{
			ball.ScoreEvent += OnBallScore;
		}
		SoccerPowerup.StaticPickupEvent = (SoccerPowerup.Pickup)Delegate.Combine(SoccerPowerup.StaticPickupEvent, new SoccerPowerup.Pickup(OnPowerupPickup));
		powerupSpawnPoints = UnityEngine.Object.FindObjectsOfType<LegacyPowerupSpawner>();
		garageDoor = UnityEngine.Object.FindObjectOfType<SoccerGarageDoor>();
		garageDoor.Open = true;
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.GAME_RUNNING)
		{
			OnGameStart();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		GameManager.OnGameStartEvent -= OnGameStart;
		GameManager.OnGameEndEvent -= OnGameEnd;
		GameManager.InitializeSceneOnPreGameEvent -= InitializeSceneOnPreGame;
		SoccerPowerup.StaticPickupEvent = (SoccerPowerup.Pickup)Delegate.Remove(SoccerPowerup.StaticPickupEvent, new SoccerPowerup.Pickup(OnPowerupPickup));
	}

	protected override void Start()
	{
		base.Start();
		soccerStateMachine.Start(this, ushort.MaxValue);
	}

	protected void Update()
	{
		soccerStateMachine.Update();
		masterSoccerStateTimer.UpdateCallbacks();
	}

	protected void InitializeSceneOnPreGame()
	{
		garageDoor.Open = true;
	}

	protected void OnGameStart()
	{
		garageDoor.Open = false;
		ball.Tool.ToolCleanup.PauseCleanup(this);
		if (PhotonNetwork.isMasterClient)
		{
			soccerStateMachine.EnterState(0);
		}
	}

	protected void OnGameEnd()
	{
		garageDoor.Open = true;
		ball.Tool.ToolCleanup.ResumeCleanup(this);
		if (PhotonNetwork.isMasterClient)
		{
			soccerStateMachine.EnterState(ushort.MaxValue);
		}
	}

	private void OnBallScore(SoccerBall ball, SoccerGoal scoredOnGoal, Vector3 scorePoint)
	{
		if (ball.Tool.Owner.isLocal && IsValidScore())
		{
			base.photonView.RpcMaster(RpcMasterRequestScore, scoredOnGoal.Team, scorePoint);
		}
	}

	[PunRPC]
	private void RpcMasterRequestScore(GameTeam scoredOnTeam, Vector3 scorePoint)
	{
		if (PhotonNetwork.isMasterClient && IsValidScore())
		{
			GameTeam anotherTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetAnotherTeam(scoredOnTeam);
			PhotonPlayer lastHitPlayer = ball.GetLastHitPlayer(anotherTeam);
			if (anotherTeam != GameTeam.ANY)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.AddScore(anotherTeam, 1);
				soccerStateMachine.EnterState(2);
				ball.Tool.Disable();
				base.photonView.RpcAll(RpcOnScore, lastHitPlayer, anotherTeam, scorePoint);
			}
		}
	}

	private bool IsValidScore()
	{
		return soccerStateMachine.CurrentStateId == 1;
	}

	[PunRPC]
	private void RpcOnScore(PhotonPlayer scorer, GameTeam scoringTeam, Vector3 scorePoint)
	{
		string subtitleText = ((scorer == null) ? string.Empty : $"Goal scored by {scorer.NickName}");
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamName(scoringTeam) + " Scores!", subtitleText, 3f);
		switch (scoringTeam)
		{
		case GameTeam.TEAM_1:
			AudioManager.Play2DSFX(blueTeamScoreSFX);
			break;
		case GameTeam.TEAM_2:
			AudioManager.Play2DSFX(redTeamScoreSFX);
			break;
		}
		AudioManager.Play3DSFX(goalSFX, scorePoint);
		AudioManager.Play3DSFX(goalVO, scorePoint);
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == scoringTeam)
		{
			Player.LocalPlayer.PlayerEvents.SoccerGoal();
		}
	}

	private void MasterResetBall()
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (soccerBallSpawnTransform != null)
			{
				ball.Tool.MasterResetToDefault(soccerBallSpawnTransform.position, soccerBallSpawnTransform.rotation, sleepPhysics: false);
			}
			else
			{
				ball.Tool.MasterResetToLastSpawnPosition();
			}
		}
	}

	private void OnPowerupPickup(SoccerPowerup powerup, Player pickupPlayer)
	{
		if (pickupPlayer.PhotonPlayer.IsLocal && IsValidPowerup(powerup, pickupPlayer.PhotonPlayer))
		{
			base.photonView.RpcMaster(RpcMasterRequestPowerup, powerup, pickupPlayer.PhotonPlayer);
		}
	}

	[PunRPC]
	private void RpcMasterRequestPowerup(SoccerPowerup powerup, PhotonPlayer pickupPlayer)
	{
		if (PhotonNetwork.isMasterClient && powerup != null && IsValidPowerup(powerup, pickupPlayer))
		{
			powerup.MasterOnPickup();
			base.photonView.RpcAll(RpcOnPowerupPickup, powerup, pickupPlayer);
		}
	}

	private bool IsValidPowerup(SoccerPowerup powerup, PhotonPlayer pickupPlayer)
	{
		return soccerStateMachine.CurrentStateId == 1 && powerup.IsAlive && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(pickupPlayer);
	}

	[PunRPC]
	private void RpcOnPowerupPickup(SoccerPowerup powerup, PhotonPlayer pickupPlayer)
	{
		if (powerup != null)
		{
			AudioManager.Play3DSFX(powerupPickupSFX, powerup.transform.position);
			if (pickupPlayer.IsLocal)
			{
				Powerup.RequestPowerupActivation(PowerupType.SOCCER_SPEED, pickupPlayer);
			}
		}
	}

	private void MasterDisableAllPowerups()
	{
		CachePowerups();
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		foreach (SoccerPowerup cachedPowerup in cachedPowerups)
		{
			cachedPowerup.MasterDisable();
		}
	}

	private void MasterEnableAllPowerups()
	{
		CachePowerups();
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		if (cachedPowerups.Count == 0)
		{
			MasterSpawnPowerups();
			CachePowerups();
		}
		foreach (SoccerPowerup cachedPowerup in cachedPowerups)
		{
			cachedPowerup.MasterEnable();
		}
	}

	private void MasterSpawnPowerups()
	{
		if (PhotonNetwork.isMasterClient)
		{
			LegacyPowerupSpawner[] array = powerupSpawnPoints;
			foreach (LegacyPowerupSpawner legacyPowerupSpawner in array)
			{
				legacyPowerupSpawner.MasterSpawnPowerup();
			}
		}
	}

	private void CachePowerups()
	{
		if (cachedPowerups.Count != 0)
		{
			return;
		}
		foreach (LegacyPowerup allPowerup in LegacyPowerup.AllPowerups)
		{
			if (allPowerup is SoccerPowerup)
			{
				cachedPowerups.Add((SoccerPowerup)allPowerup);
			}
		}
	}

	private void OnEnterPreRoundState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterSoccerStateTimer.StartTimer(3f);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
			if (soccerBallSpawnTransform != null)
			{
				ball.Tool.MasterDisableAndMove(soccerBallSpawnTransform.position, soccerBallSpawnTransform.rotation);
			}
			else
			{
				ball.Tool.MasterDisableAndMoveToLastSpawnPosition();
			}
		}
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
		}
		this.InvokeInUpdate(Player.RespawnDuration, PlayRoundStartNotification);
	}

	private void OnExitPreRoundState(ushort nextStateId, ushort nextSubStateId)
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Go!", 1.5f);
	}

	private void OnUpdatePreRoundState()
	{
		if (PhotonNetwork.isMasterClient && masterSoccerStateTimer.TimerOver)
		{
			soccerStateMachine.EnterState(1);
		}
	}

	private void PlayRoundStartNotification()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Round Starting", 1.5f);
	}

	private void OnEnterRoundRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Resume();
			MasterEnableAllPowerups();
			MasterResetBall();
		}
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
	}

	private void OnExitRoundRunningState(ushort nextStateId, ushort nextSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterDisableAllPowerups();
			MasterResetBall();
		}
	}

	private void OnEnterBallScoredState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterSoccerStateTimer.StartTimer(3f);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Pause();
		}
	}

	private void OnExitBallScoredState(ushort nextStateId, ushort nextSubStateId)
	{
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn(dropTools: false);
		}
	}

	private void OnUpdateBallScoredState()
	{
		if (PhotonNetwork.isMasterClient && masterSoccerStateTimer.TimerOver)
		{
			soccerStateMachine.EnterState(0);
		}
	}
}
public class SoccerPowerup : LegacyPowerup
