public class SoccerShield : UnityEngine.MonoBehaviour
{
	[Header("Powerup Visuals")]
	[SerializeField]
	private TeleportChargeVisual powerupBar;

	[SerializeField]
	private Transform powerupVisualRoot;

	[SerializeField]
	private float powerupDepletionRateSeconds = 15f;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip powerupStart;

	private float fillPowerup;

	private float powerupFillSpeed = 1f;

	private float _powerupCharge;

	private bool _isLocalUsingPowerup;

	private bool _usingPowerup;

	public Tool Tool { get; private set; }

	public float PowerupCharge
	{
		get
		{
			return _powerupCharge;
		}
		private set
		{
			_powerupCharge = Mathf.Clamp01(value);
			powerupBar.Charge = PowerupCharge;
			if (PowerupCharge == 0f && UsingPowerup)
			{
				UsingPowerup = false;
			}
		}
	}

	public bool UsingPowerup
	{
		get
		{
			return _usingPowerup;
		}
		private set
		{
			bool flag = value && PowerupCharge > 0f;
			if (_usingPowerup == flag)
			{
				return;
			}
			_usingPowerup = flag;
			UpdatePowerupFX();
			if (!(Tool.Owner != null))
			{
				return;
			}
			if (flag)
			{
				_isLocalUsingPowerup = Tool.isLocal;
				if (_isLocalUsingPowerup)
				{
					Player.LocalPlayer.PlayerLocomotion.AddTeleportMaxHorizontalDistanceScalar(2f, this, 10002);
				}
			}
			else if (_isLocalUsingPowerup)
			{
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportMaxHorizontalDistanceScalar(this);
			}
		}
	}

	public Vector3 PowerupVisualPosition => powerupVisualRoot.position;

	private void Awake()
	{
		Tool = GetComponent<Tool>();
		if (Tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
			return;
		}
		Tool.PostReleaseEvent += OnPostRelease;
		Tool.InputDownEvent += OnInputDown;
	}

	private void OnDestroy()
	{
		if (Tool != null)
		{
			Tool.PostReleaseEvent -= OnPostRelease;
			Tool.InputDownEvent -= OnInputDown;
		}
	}

	private void Update()
	{
		if (!Tool.IsHeld || !(Tool.Owner != null) || !Tool.Owner.isLocal)
		{
			return;
		}
		if (fillPowerup > 0f)
		{
			float num = UnityEngine.Time.deltaTime * powerupFillSpeed;
			fillPowerup -= num;
			PowerupCharge += num;
			if (PowerupCharge >= 1f)
			{
				fillPowerup = 0f;
			}
		}
		if (UsingPowerup)
		{
			float num2 = UnityEngine.Time.deltaTime * 1f / powerupDepletionRateSeconds;
			PowerupCharge -= num2;
		}
	}

	private void OnPostRelease(Tool tool)
	{
		if (tool.HolderPlayer != null && tool.HolderPlayer.isLocal && RecRoomSceneManager.Instance != null)
		{
			PowerupCharge = 0f;
			UsingPowerup = false;
		}
	}

	private void OnInputDown(Tool thisTool)
	{
		UsingPowerup = true;
	}

	public void UsePowerup(LegacyPowerup powerup)
	{
		if (Tool.IsHeldByPlayer && Tool.HolderPlayer != null && Tool.HolderPlayer.isLocal)
		{
			fillPowerup = powerup.PowerupValue;
		}
	}

	private void UpdatePowerupFX()
	{
		powerupVisualRoot.gameObject.SetActive(UsingPowerup);
		if (UsingPowerup)
		{
			AudioManager.Play3DSFX(powerupStart, base.transform);
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			UsingPowerup = (bool)stream.ReceiveNext();
			PowerupCharge = (float)stream.ReceiveNext();
		}
		else
		{
			stream.SendNext(UsingPowerup);
			stream.SendNext(PowerupCharge);
		}
	}
}
public class TeleportChargeVisual : UnityEngine.MonoBehaviour
{
	[Header("Curves")]
	[SerializeField]
	private ColorValueCurve colorCurve;

	[SerializeField]
	private FloatValueCurve scaleCurve;

	[Header("Component References")]
	[SerializeField]
	private Slider sliderToSet;

	[SerializeField]
	private UnityEngine.UI.Image imageToColor;

	[SerializeField]
	private Transform transformToScale;

	public float Charge
	{
		set
		{
			value = Mathf.Clamp01(value);
			if (sliderToSet != null)
			{
				sliderToSet.value = Mathf.Clamp01(value);
			}
			if (imageToColor != null)
			{
				imageToColor.color = colorCurve.Evaluate(value);
			}
			if (transformToScale != null)
			{
				transformToScale.localScale = Vector3.one * scaleCurve.Evaluate(value);
			}
		}
	}
}
namespace RecRoom.Activities.Soccer
{
	public class SoccerSpeedPowerup : Powerup
	{
		[Header("Soccer Speed Powerup")]
		[SerializeField]
		private float walkSpeed = 12f;

		[SerializeField]
		private float teleportMaxDistanceScalar = 2f;

		protected override void Awake()
		{
			base.Awake();
			if (base.TargetPlayer != null && base.TargetPlayer.IsLocal)
			{
				Player.LocalPlayer.PlayerWalking.AddMaxWalkSpeed(walkSpeed, this, 10001);
				Player.LocalPlayer.PlayerLocomotion.AddTeleportMaxHorizontalDistanceScalar(teleportMaxDistanceScalar, this, 10001);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.TargetPlayer != null && base.TargetPlayer.IsLocal)
			{
				Player.LocalPlayer.PlayerWalking.RemoveMaxWalkSpeed(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportMaxHorizontalDistanceScalar(this);
			}
		}
	}
}
namespace RecRoom.VFX
{
	public class FreezeParticles : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private float freezeTime;

		private ParticleSystem[] particles;

		private void Awake()
		{
			CacheParticles();
		}

		private void Start()
		{
			FreezeParticleTime(freezeTime);
		}

		private void OnValidate()
		{
			if (particles == null)
			{
				CacheParticles();
			}
			FreezeParticleTime(freezeTime);
		}

		private void CacheParticles()
		{
			particles = GetComponentsInChildren<ParticleSystem>();
		}

		private void FreezeParticleTime(float time)
		{
			for (int i = 0; i < particles.Length; i++)
			{
				particles[i].Simulate(time, withChildren: true, restart: true, fixedTimeStep: false);
			}
		}
	}
}
