public class CodeExample : UnityEngine.MonoBehaviour
{
	private AnimatedGifPlayer AnimatedGifPlayer;

	public UnityEngine.UI.Button PlayButton;

	public UnityEngine.UI.Button PauseButton;

	public void Awake()
	{
		AnimatedGifPlayer = GetComponent<AnimatedGifPlayer>();
		AnimatedGifPlayer.FileName = "AnimatedGIFPlayerExampe 3.gif";
		AnimatedGifPlayer.AutoPlay = false;
		AnimatedGifPlayer.OnReady += OnGifLoaded;
		AnimatedGifPlayer.OnLoadError += OnGifLoadError;
		AnimatedGifPlayer.Init();
	}

	private void OnGifLoaded()
	{
		PlayButton.interactable = true;
		UnityEngine.Debug.Log("GIF size: width: " + AnimatedGifPlayer.Width + "px, height: " + AnimatedGifPlayer.Height + " px");
	}

	private void OnGifLoadError()
	{
		UnityEngine.Debug.Log("Error Loading GIF");
	}

	public void Play()
	{
		AnimatedGifPlayer.Play();
		PlayButton.interactable = false;
		PauseButton.interactable = true;
	}

	public void Pause()
	{
		AnimatedGifPlayer.Pause();
		PlayButton.interactable = true;
		PauseButton.interactable = false;
	}

	public void OnDisable()
	{
		AnimatedGifPlayer.OnReady -= Play;
	}
}
public class MeshRendererExample : UnityEngine.MonoBehaviour
{
	private float dir = 1f;

	private void Update()
	{
		base.transform.Rotate(new Vector3(0f, dir, 0f) * 50f * UnityEngine.Time.deltaTime);
		if ((double)base.transform.rotation.y > 0.8)
		{
			dir = -1f;
		}
		if ((double)base.transform.rotation.y < 0.3)
		{
			dir = 1f;
		}
	}
