				OnLoadErrorAction onLoadErrorAction = this.m_OnLoadError;
				OnLoadErrorAction onLoadErrorAction2;
				do
				{
					onLoadErrorAction2 = onLoadErrorAction;
					onLoadErrorAction = Interlocked.CompareExchange(ref this.m_OnLoadError, (OnLoadErrorAction)Delegate.Remove(onLoadErrorAction2, value), onLoadErrorAction);
				}
				while (onLoadErrorAction != onLoadErrorAction2);
			}
		}

		private void Awake()
		{
			if (State == GifPlayerState.PreProcessing)
			{
				Init();
			}
		}

		public void Update()
		{
			CheckFrameChange();
		}

		private void OnApplicationQuit()
		{
			EndDecodeThread();
		}

		public void Init()
		{
			_cacheFrames = CacheFrames;
			_bufferAllFrames = BufferAllFrames;
			_useThreadedDecoder = UseThreadedDecoder;
			if (_bufferAllFrames && !_cacheFrames)
			{
				_bufferAllFrames = false;
			}
			if (_cacheFrames)
			{
				_cachedFrames = new List<GifDecoder.GifFrame>();
			}
			_targetComponent = GetTargetComponent();
			_gifDecoder = new GifDecoder();
			CurrentFrameNumber = 0;
			_hasFirstFrameBeenShown = false;
			_frameIsReady = false;
			State = GifPlayerState.Disabled;
			StartDecodeThread();
			if (FileName.Length > 0)
			{
				StartCoroutine(Load());
			}
		}

		public void Play()
		{
			if (State != GifPlayerState.Stopped)
			{
				UnityEngine.Debug.LogWarning("Can't play GIF playback. State is: " + State);
			}
			else
			{
				State = GifPlayerState.Playing;
			}
		}

		public void Pause()
		{
			if (State != GifPlayerState.Playing)
			{
				UnityEngine.Debug.LogWarning("Can't pause GIF is not playing. State is: " + State);
			}
			else
			{
				State = GifPlayerState.Stopped;
			}
		}

		public int GetNumberOfFrames()
		{
			return (_gifDecoder != null) ? _gifDecoder.GetFrameCount() : 0;
		}

		private IEnumerator Load()
		{
			if (FileName.Length == 0)
			{
				UnityEngine.Debug.LogWarning("File name not set");
				yield break;
			}
			State = GifPlayerState.Loading;
			string path = ((!(FileName.Substring(0, 4) == "http")) ? System.IO.Path.Combine("file://" + Path switch
			{
				GifPath.StreamingAssetsPath => UnityEngine.Application.streamingAssetsPath, 
				GifPath.PersistentDataPath => UnityEngine.Application.persistentDataPath, 
				GifPath.TemporaryCachePath => UnityEngine.Application.temporaryCachePath, 
				_ => UnityEngine.Application.streamingAssetsPath, 
			}, FileName) : FileName);
			using WWW www = new WWW(path.Replace("#", "%23"));
			yield return www;
			if (!string.IsNullOrEmpty(www.error))
			{
				UnityEngine.Debug.LogWarning("File load error.\n" + www.error + "\nPath:" + WWW.EscapeURL(path, Encoding.Default));
				State = GifPlayerState.Error;
				yield break;
			}
			ActualHash = Security.GetAntiTamperHash(www.bytes);
			bool flag = false;
			if (!string.IsNullOrEmpty(AntiTamperHash))
			{
				if (ActualHash == AntiTamperHash)
				{
					flag = true;
				}
				else
				{
					UnityEngine.Debug.LogWarning("Corrupted streaming file : " + path);
					AnalyticsHelper.StreamingAssetCheat(path);
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.LogWarning("Could not validate gif with anti-tamper hash");
				State = GifPlayerState.Error;
				if (this.OnLoadError != null)
				{
					this.OnLoadError();
				}
				yield break;
			}
			lock (_locker)
			{
				if (_gifDecoder.Read(new MemoryStream(www.bytes)) == GifDecoder.Status.StatusOk)
				{
					State = GifPlayerState.PreProcessing;
					CreateTargetTexture();
					StartDecoder();
					yield break;
				}
				UnityEngine.Debug.LogWarning("Error loading gif");
				State = GifPlayerState.Error;
				if (this.OnLoadError != null)
				{
					this.OnLoadError();
				}
			}
		}

		private void CreateTargetTexture()
		{
			if (GifTexture != null && _gifDecoder != null && GifTexture.width == _gifDecoder.GetFrameWidth() && GifTexture.height == _gifDecoder.GetFrameHeight())
			{
				return;
			}
			if (_gifDecoder == null || _gifDecoder.GetFrameWidth() == 0 || _gifDecoder.GetFrameWidth() == 0)
			{
				GifTexture = Texture2D.blackTexture;
				return;
			}
			if (GifTexture != null && GifTexture.hideFlags == HideFlags.HideAndDontSave)
			{
				UnityEngine.Object.Destroy(GifTexture);
			}
			GifTexture = CreateTexture(_gifDecoder.GetFrameWidth(), _gifDecoder.GetFrameHeight());
			GifTexture.hideFlags = HideFlags.HideAndDontSave;
		}

		private void SetTexture()
		{
			if (_targetComponent == null)
			{
				return;
			}
			if (_targetComponent is SpriteRenderer)
			{
				SpriteRenderer spriteRenderer = (SpriteRenderer)_targetComponent;
				Vector2 size = spriteRenderer.size;
				Sprite sprite = Sprite.Create(GifTexture, new Rect(0f, 0f, GifTexture.width, GifTexture.height), new Vector2(0.5f, 0.5f), 100f, 0u, SpriteMeshType.FullRect);
				sprite.name = "Gif Player Sprite";
				sprite.hideFlags = HideFlags.HideAndDontSave;
				spriteRenderer.sprite = sprite;
				spriteRenderer.size = size;
			}
			else if (_targetComponent is Renderer)
			{
				Renderer renderer = (Renderer)_targetComponent;
				if (!(renderer.sharedMaterial == null))
				{
					if (renderer.sharedMaterials.Length > 0 && renderer.sharedMaterials.Length > _targetMaterial)
					{
						renderer.sharedMaterials[_targetMaterial].mainTexture = GifTexture;
					}
					else
					{
						renderer.sharedMaterial.mainTexture = GifTexture;
					}
				}
			}
			else if (_targetComponent is RawImage)
			{
				RawImage rawImage = (RawImage)_targetComponent;
				rawImage.texture = GifTexture;
			}
		}

		private UnityEngine.Component GetTargetComponent()
		{
			UnityEngine.Component[] components = GetComponents<UnityEngine.Component>();
			return components.FirstOrDefault((UnityEngine.Component component) => component is Renderer || component is RawImage);
		}

		private void SetTargetTexture()
		{
			if (GifTexture == null || GifTexture.width != _gifDecoder.GetFrameWidth() || GifTexture.height != _gifDecoder.GetFrameWidth())
			{
				GifTexture = CreateTexture(_gifDecoder.GetFrameWidth(), _gifDecoder.GetFrameHeight());
			}
			GifTexture.hideFlags = HideFlags.HideAndDontSave;
			if (TargetComponent == null)
			{
				return;
			}
			if (TargetComponent is MeshRenderer)
			{
				Renderer renderer = (Renderer)TargetComponent;
				if (renderer.sharedMaterial == null)
				{
					return;
				}
				if (renderer.sharedMaterials.Length > 0 && renderer.sharedMaterials.Length > _targetMaterial)
				{
					renderer.sharedMaterials[_targetMaterial].mainTexture = GifTexture;
				}
				else
				{
					renderer.sharedMaterial.mainTexture = GifTexture;
				}
			}
			if (TargetComponent is SpriteRenderer)
			{
				SpriteRenderer spriteRenderer = (SpriteRenderer)TargetComponent;
				Sprite sprite = Sprite.Create(GifTexture, new Rect(0f, 0f, GifTexture.width, GifTexture.height), new Vector2(0.5f, 0.5f));
				sprite.name = "Gif Player Sprite";
				sprite.hideFlags = HideFlags.HideAndDontSave;
				spriteRenderer.sprite = sprite;
			}
			if (TargetComponent is RawImage)
			{
				RawImage rawImage = (RawImage)TargetComponent;
				rawImage.texture = GifTexture;
			}
		}

		private static Texture2D CreateTexture(int width, int height)
		{
			return new Texture2D(width, height, TextureFormat.RGBA32, mipmap: false);
		}

		private void BufferFrames()
		{
			if (_useThreadedDecoder)
			{
				_wh.Set();
				return;
			}
			lock (_locker)
			{
				while (true)
				{
					_gifDecoder.ReadNextFrame(loop: false);
					if (_gifDecoder.AllFramesRead)
					{
						break;
					}
					GifDecoder.GifFrame currentFrame = _gifDecoder.GetCurrentFrame();
					AddFrameToCache(currentFrame);
				}
				_frameIsReady = true;
			}
		}

		private void AddFrameToCache(GifDecoder.GifFrame frame)
		{
			byte[] array = new byte[frame.Image.Length];
			Buffer.BlockCopy(frame.Image, 0, array, 0, frame.Image.Length);
			frame.Image = array;
			lock (_cachedFrames)
			{
				_cachedFrames.Add(frame);
			}
		}

		private void StartDecoder()
		{
			if (_bufferAllFrames)
			{
				BufferFrames();
			}
			else
			{
				StartReadFrame();
			}
			State = GifPlayerState.Stopped;
			if (this.OnReady != null)
			{
				this.OnReady();
			}
			if (AutoPlay)
			{
				Play();
			}
		}

		private void SetNextFrameTime()
		{
			_secondsTillNextFrame = CurrentFrame.Delay;
		}

		private void UpdateFrameTime()
		{
			if (State != GifPlayerState.Playing)
			{
				return;
			}
			if (!UnityEngine.Application.isPlaying || OverrideTimeScale)
			{
				if (OverrideTimeScale)
				{
					_secondsTillNextFrame -= (UnityEngine.Time.realtimeSinceStartup - _editorPreviousUpdateTime) * TimeScale;
				}
				else
				{
					_secondsTillNextFrame -= UnityEngine.Time.realtimeSinceStartup - _editorPreviousUpdateTime;
				}
				_editorPreviousUpdateTime = UnityEngine.Time.realtimeSinceStartup;
			}
			else
			{
				_secondsTillNextFrame -= UnityEngine.Time.deltaTime;
			}
		}

		private void UpdateFrame()
		{
			if (_gifDecoder.NumberOfFrames > 0 && _gifDecoder.NumberOfFrames == CurrentFrameNumber)
			{
				CurrentFrameNumber = 0;
				if (!Loop)
				{
					Pause();
					return;
				}
			}
			if (_cacheFrames)
			{
				lock (_cachedFrames)
				{
					CurrentFrame = ((_cachedFrames.Count <= CurrentFrameNumber) ? _gifDecoder.GetCurrentFrame() : _cachedFrames[CurrentFrameNumber]);
				}
				if (!_gifDecoder.AllFramesRead)
				{
					StartReadFrame();
				}
			}
			else
			{
				CurrentFrame = _gifDecoder.GetCurrentFrame();
				StartReadFrame();
			}
			UpdateTexture();
			SetNextFrameTime();
			CurrentFrameNumber++;
		}

		private void CheckFrameChange()
		{
			if ((State != GifPlayerState.Playing && _hasFirstFrameBeenShown) || !_frameIsReady || State == GifPlayerState.Loading)
			{
				return;
			}
			if (!_hasFirstFrameBeenShown)
			{
				SetTexture();
				lock (_locker)
				{
					UpdateFrame();
				}
				_hasFirstFrameBeenShown = true;
				return;
			}
			UpdateFrameTime();
			if (_secondsTillNextFrame > 0f)
			{
				return;
			}
			lock (_locker)
			{
				UpdateFrame();
			}
		}

		private void UpdateTexture()
		{
			GifTexture.LoadRawTextureData(CurrentFrame.Image);
			GifTexture.Apply();
		}

		private void StartReadFrame()
		{
			_frameIsReady = false;
			if (_useThreadedDecoder)
			{
				_wh.Set();
			}
			else if (!_cacheFrames || !_gifDecoder.AllFramesRead)
			{
				_gifDecoder.ReadNextFrame(!_cacheFrames);
				if (_cacheFrames && !_gifDecoder.AllFramesRead)
				{
					AddFrameToCache(_gifDecoder.GetCurrentFrame());
				}
				_frameIsReady = true;
			}
		}

		private void StartDecodeThread()
		{
			if (!_useThreadedDecoder)
			{
				return;
			}
			if (_decodeThread != null)
			{
				lock (_locker)
				{
					_threadLoop = !_cacheFrames;
					_threadBufferAll = _bufferAllFrames;
					return;
				}
			}
			_threadIsCanceled = false;
			_decodeThread = new Thread(FrameDataThread);
			_decodeThread.Name = "gifDecoder" + _decodeThread.ManagedThreadId;
			_decodeThread.IsBackground = true;
			_decodeThread.Start();
		}

		private void EndDecodeThread()
		{
			if (!_threadIsCanceled)
			{
				_threadIsCanceled = true;
				_wh.Set();
			}
		}

		private void FrameDataThread()
		{
			_wh.WaitOne();
			while (!_threadIsCanceled)
			{
				lock (_locker)
				{
					_gifDecoder.ReadNextFrame(_threadLoop || (Loop && !_cacheFrames));
					if (_cacheFrames && _gifDecoder.AllFramesRead)
					{
						_frameIsReady = true;
						break;
					}
					if (_cacheFrames)
					{
						AddFrameToCache(_gifDecoder.GetCurrentFrame());
					}
					if (_threadBufferAll)
					{
						if (_gifDecoder.AllFramesRead)
						{
							_frameIsReady = true;
							break;
						}
						continue;
					}
					_frameIsReady = true;
				}
				_wh.WaitOne();
			}
			_threadIsCanceled = true;
			_decodeThread = null;
		}
	}
}
public class AQUAS_BubbleBehaviour : UnityEngine.MonoBehaviour
{
	public float averageUpdrift;

	public float waterLevel;

	public GameObject mainCamera;

	public GameObject smallBubble;

	private int smallBubbleCount;

	private int maxSmallBubbleCount;

	private AQUAS_SmallBubbleBehaviour smallBubbleBehaviour;

	private void Start()
	{
		maxSmallBubbleCount = UnityEngine.Random.Range(20, 30);
		smallBubbleCount = 0;
		smallBubbleBehaviour = smallBubble.GetComponent<AQUAS_SmallBubbleBehaviour>();
	}

	private void Update()
	{
		base.transform.Translate(Vector3.up * UnityEngine.Time.deltaTime * averageUpdrift, Space.World);
		SmallBubbleSpawner();
		if (mainCamera.transform.position.y > waterLevel || base.transform.position.y > waterLevel)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void SmallBubbleSpawner()
	{
		if (smallBubbleCount <= maxSmallBubbleCount)
		{
			smallBubble.transform.localScale = base.transform.localScale * UnityEngine.Random.Range(0.05f, 0.2f);
			smallBubbleBehaviour.averageUpdrift = averageUpdrift * 0.5f;
			smallBubbleBehaviour.waterLevel = waterLevel;
			smallBubbleBehaviour.mainCamera = mainCamera;
			UnityEngine.Object.Instantiate(smallBubble, new Vector3(base.transform.position.x + UnityEngine.Random.Range(-0.1f, 0.1f), base.transform.position.y - UnityEngine.Random.Range(0.01f, 1f), base.transform.position.z + UnityEngine.Random.Range(-0.1f, 0.1f)), Quaternion.identity);
			smallBubbleCount++;
		}
	}
}
public class AQUAS_BubbleMorph : UnityEngine.MonoBehaviour
{
	private float t;

	private float t2;

	[Space(5f)]
	[Header("Duration of a full morphing cycle")]
	public float tTarget;

	private SkinnedMeshRenderer skinnedMeshRenderer;

	private void Start()
	{
		skinnedMeshRenderer = GetComponent<SkinnedMeshRenderer>();
	}

	private void Update()
	{
		t += UnityEngine.Time.deltaTime;
		t2 += UnityEngine.Time.deltaTime;
		if (t < tTarget / 2f)
		{
			skinnedMeshRenderer.SetBlendShapeWeight(0, Mathf.Lerp(0f, 50f, t / (tTarget / 2f)));
			skinnedMeshRenderer.SetBlendShapeWeight(1, Mathf.Lerp(50f, 0f, t / (tTarget / 2f)));
		}
		else if (t >= tTarget / 2f && t < tTarget)
		{
			skinnedMeshRenderer.SetBlendShapeWeight(0, Mathf.Lerp(50f, 100f, t / tTarget));
			skinnedMeshRenderer.SetBlendShapeWeight(1, Mathf.Lerp(0f, 50f, t / tTarget));
		}
		else if (t >= tTarget && t < tTarget * 1.5f)
		{
			skinnedMeshRenderer.SetBlendShapeWeight(0, Mathf.Lerp(100f, 50f, t / (tTarget * 1.5f)));
			skinnedMeshRenderer.SetBlendShapeWeight(1, Mathf.Lerp(50f, 100f, t / (tTarget * 1.5f)));
		}
		else if (t >= tTarget * 1.5f && t < tTarget * 2f)
		{
			skinnedMeshRenderer.SetBlendShapeWeight(0, Mathf.Lerp(50f, 0f, t / (tTarget * 2f)));
			skinnedMeshRenderer.SetBlendShapeWeight(1, Mathf.Lerp(100f, 50f, t / (tTarget * 2f)));
		}
		else
		{
			t = 0f;
		}
	}
}
[AddComponentMenu("AQUAS/Buoyancy")]
[RequireComponent(typeof(Rigidbody))]
public class AQUAS_Buoyancy : UnityEngine.MonoBehaviour
{
	public enum debugModes
	{
		none,
		showAffectedFaces,
		showForceRepresentation,
		showReferenceVolume
	}

	public float waterLevel;

	public float waterDensity;

	[Space(5f)]
	public bool useBalanceFactor;

	public Vector3 balanceFactor;

	[Space(20f)]
	[Range(0f, 1f)]
	public float dynamicSurface = 0.3f;

	[Range(1f, 10f)]
	public float bounceFrequency = 3f;

	[Space(5f)]
	[Header("Debugging can be ver performance heavy!")]
	public debugModes debug;

	private Vector3[] vertices;

	private int[] triangles;

	private Mesh mesh;

	private Rigidbody rb;

	private float effWaterDensity;

	private float regWaterDensity;

	private float maxWaterDensity;

	private void Start()
	{
		mesh = GetComponent<MeshFilter>().mesh;
		vertices = mesh.vertices;
		triangles = mesh.triangles;
		rb = GetComponent<Rigidbody>();
		regWaterDensity = waterDensity;
		maxWaterDensity = regWaterDensity + regWaterDensity * 0.5f * dynamicSurface;
	}

	private void FixedUpdate()
	{
		if (balanceFactor.x < 0.001f)
		{
			balanceFactor.x = 0.001f;
		}
		if (balanceFactor.y < 0.001f)
		{
			balanceFactor.y = 0.001f;
		}
		if (balanceFactor.z < 0.001f)
		{
			balanceFactor.z = 0.001f;
		}
		AddForce();
	}

	private void Update()
	{
		regWaterDensity = waterDensity;
		maxWaterDensity = regWaterDensity + regWaterDensity * 0.5f * dynamicSurface;
		effWaterDensity = (maxWaterDensity - regWaterDensity) / 2f + regWaterDensity + Mathf.Sin(UnityEngine.Time.time * bounceFrequency) * (maxWaterDensity - regWaterDensity) / 2f;
	}

	private void AddForce()
	{
		for (int i = 0; i < triangles.Length; i += 3)
		{
			Vector3 vector = vertices[triangles[i]];
			Vector3 vector2 = vertices[triangles[i + 1]];
			Vector3 vector3 = vertices[triangles[i + 2]];
			float num = waterLevel - Center(vector, vector2, vector3).y;
			if (num > 0f && Center(vector, vector2, vector3).y > (Center(vector, vector2, vector3) + Normal(vector, vector2, vector3)).y)
			{
				float y = effWaterDensity * Physics.gravity.y * num * Area(vector, vector2, vector3) * Normal(vector, vector2, vector3).normalized.y;
				if (useBalanceFactor)
				{
					rb.AddForceAtPosition(new Vector3(0f, y, 0f), base.transform.TransformPoint(new Vector3(base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).x / (balanceFactor.x * base.transform.localScale.x * 1000f), base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).y / (balanceFactor.y * base.transform.localScale.x * 1000f), base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).z / (balanceFactor.z * base.transform.localScale.x * 1000f))));
				}
				else
				{
					rb.AddForceAtPosition(new Vector3(0f, y, 0f), base.transform.TransformPoint(new Vector3(base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).x, base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).y, base.transform.InverseTransformPoint(Center(vector, vector2, vector3)).z)));
				}
				if (debug == debugModes.showAffectedFaces)
				{
					UnityEngine.Debug.DrawLine(Center(vector, vector2, vector3), Center(vector, vector2, vector3) + Normal(vector, vector2, vector3), Color.white);
				}
				if (debug == debugModes.showForceRepresentation)
				{
					UnityEngine.Debug.DrawRay(Center(vector, vector2, vector3), new Vector3(0f, y, 0f), Color.red);
				}
				if (debug == debugModes.showReferenceVolume)
				{
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector).z), new Vector3(base.transform.TransformPoint(vector2).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector2).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector2).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector2).z), new Vector3(base.transform.TransformPoint(vector3).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector3).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector3).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector3).z), new Vector3(base.transform.TransformPoint(vector).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector).x, waterLevel, base.transform.TransformPoint(vector).z), new Vector3(base.transform.TransformPoint(vector2).x, waterLevel, base.transform.TransformPoint(vector2).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector2).x, waterLevel, base.transform.TransformPoint(vector2).z), new Vector3(base.transform.TransformPoint(vector3).x, waterLevel, base.transform.TransformPoint(vector3).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector3).x, waterLevel, base.transform.TransformPoint(vector3).z), new Vector3(base.transform.TransformPoint(vector).x, waterLevel, base.transform.TransformPoint(vector).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector).x, waterLevel, base.transform.TransformPoint(vector).z), new Vector3(base.transform.TransformPoint(vector).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector2).x, waterLevel, base.transform.TransformPoint(vector2).z), new Vector3(base.transform.TransformPoint(vector2).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector2).z), Color.green);
					UnityEngine.Debug.DrawLine(new Vector3(base.transform.TransformPoint(vector3).x, waterLevel, base.transform.TransformPoint(vector3).z), new Vector3(base.transform.TransformPoint(vector3).x, Center(vector, vector2, vector3).y, base.transform.TransformPoint(vector3).z), Color.green);
				}
			}
		}
	}

	private Vector3 Center(Vector3 p1, Vector3 p2, Vector3 p3)
	{
		Vector3 position = (p1 + p2 + p3) / 3f;
		return base.transform.TransformPoint(position);
	}

	private Vector3 Normal(Vector3 p1, Vector3 p2, Vector3 p3)
	{
		return Vector3.Cross(base.transform.TransformPoint(p2) - base.transform.TransformPoint(p1), base.transform.TransformPoint(p3) - base.transform.TransformPoint(p1)).normalized;
	}

	private float Area(Vector3 p1, Vector3 p2, Vector3 p3)
	{
		float num = Vector3.Distance(new Vector3(base.transform.TransformPoint(p1).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p1).z), new Vector3(base.transform.TransformPoint(p2).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p2).z));
		float num2 = Vector3.Distance(new Vector3(base.transform.TransformPoint(p3).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p3).z), new Vector3(base.transform.TransformPoint(p1).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p1).z));
		return num * num2 * Mathf.Sin(Vector3.Angle(new Vector3(base.transform.TransformPoint(p2).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p2).z) - new Vector3(base.transform.TransformPoint(p1).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p1).z), new Vector3(base.transform.TransformPoint(p3).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p3).z) - new Vector3(base.transform.TransformPoint(p1).x, Center(p1, p2, p3).y, base.transform.TransformPoint(p1).z)) * ((float)Math.PI / 180f)) / 2f;
	}
}
