public class AQUAS_SmallBubbleBehaviour : UnityEngine.MonoBehaviour
{
	public float averageUpdrift;

	public float waterLevel;

	public GameObject mainCamera;

	private float updriftFactor;

	private void Start()
	{
		updriftFactor = UnityEngine.Random.Range((0f - averageUpdrift) * 0.75f, averageUpdrift * 0.75f);
	}

	private void Update()
	{
		base.transform.Translate(Vector3.up * UnityEngine.Time.deltaTime * (averageUpdrift + updriftFactor), Space.World);
		if (mainCamera.transform.position.y > waterLevel || base.transform.position.y > waterLevel)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
}
namespace AQUAS
{
	public class AQUAS_Walk : UnityEngine.MonoBehaviour
	{
		public float m_moveSpeed = 10f;

		public CharacterController m_controller;

		private void Start()
		{
			if (m_controller == null)
			{
				m_controller = GetComponent<CharacterController>();
			}
		}

		private void Update()
		{
			if (m_controller != null && m_controller.enabled)
			{
				Vector3 vector = Input.GetAxis("Vertical") * base.transform.TransformDirection(Vector3.forward) * m_moveSpeed;
				m_controller.Move(vector * UnityEngine.Time.deltaTime);
				Vector3 vector2 = Input.GetAxis("Horizontal") * base.transform.TransformDirection(Vector3.right) * m_moveSpeed;
				m_controller.Move(vector2 * UnityEngine.Time.deltaTime);
				m_controller.SimpleMove(Physics.gravity);
			}
		}
	}
}
