namespace BestHTTP.Authentication
{
	public enum AuthenticationTypes
	{
		Unknown,
		Basic,
		Digest
	}
	public sealed class Credentials
	{
		public AuthenticationTypes Type { get; private set; }

		public string UserName { get; private set; }

		public string Password { get; private set; }

		public Credentials(string userName, string password)
			: this(AuthenticationTypes.Unknown, userName, password)
		{
		}

		public Credentials(AuthenticationTypes type, string userName, string password)
		{
			Type = type;
			UserName = userName;
			Password = password;
		}
	}
	public sealed class Digest
	{
		public Uri Uri { get; private set; }

		public AuthenticationTypes Type { get; private set; }

		public string Realm { get; private set; }

		public bool Stale { get; private set; }

		private string Nonce { get; set; }

		private string Opaque { get; set; }

		private string Algorithm { get; set; }

		public List<string> ProtectedUris { get; private set; }

		private string QualityOfProtections { get; set; }

		private int NonceCount { get; set; }

		private string HA1Sess { get; set; }

		internal Digest(Uri uri)
		{
			Uri = uri;
			Algorithm = "md5";
		}

		public void ParseChallange(string header)
		{
			Type = AuthenticationTypes.Unknown;
			Stale = false;
			Opaque = null;
			HA1Sess = null;
			NonceCount = 0;
			QualityOfProtections = null;
			if (ProtectedUris != null)
			{
				ProtectedUris.Clear();
			}
			WWWAuthenticateHeaderParser wWWAuthenticateHeaderParser = new WWWAuthenticateHeaderParser(header);
			foreach (HeaderValue value in wWWAuthenticateHeaderParser.Values)
			{
				switch (value.Key)
				{
				case "basic":
					Type = AuthenticationTypes.Basic;
					break;
				case "digest":
					Type = AuthenticationTypes.Digest;
					break;
				case "realm":
					Realm = value.Value;
					break;
				case "domain":
					if (!string.IsNullOrEmpty(value.Value) && value.Value.Length != 0)
					{
						if (ProtectedUris == null)
						{
							ProtectedUris = new List<string>();
						}
						int pos = 0;
						string item = value.Value.Read(ref pos, ' ');
						do
						{
							ProtectedUris.Add(item);
							item = value.Value.Read(ref pos, ' ');
						}
						while (pos < value.Value.Length);
					}
					break;
				case "nonce":
					Nonce = value.Value;
					break;
				case "qop":
					QualityOfProtections = value.Value;
					break;
				case "stale":
					Stale = bool.Parse(value.Value);
					break;
				case "opaque":
					Opaque = value.Value;
					break;
				case "algorithm":
					Algorithm = value.Value;
					break;
				}
			}
		}

		public string GenerateResponseHeader(HTTPRequest request, Credentials credentials, bool isProxy = false)
		{
			try
			{
				switch (Type)
				{
				case AuthenticationTypes.Basic:
					return "Basic " + Convert.ToBase64String(Encoding.UTF8.GetBytes($"{credentials.UserName}:{credentials.Password}"));
				case AuthenticationTypes.Digest:
				{
					NonceCount++;
					string empty = string.Empty;
					string text = new System.Random(request.GetHashCode()).Next(int.MinValue, int.MaxValue).ToString("X8");
					string text2 = NonceCount.ToString("X8");
					switch (Algorithm.TrimAndLower())
					{
					case "md5":
						empty = $"{credentials.UserName}:{Realm}:{credentials.Password}".CalculateMD5Hash();
						break;
					case "md5-sess":
						if (string.IsNullOrEmpty(HA1Sess))
						{
							HA1Sess = $"{credentials.UserName}:{Realm}:{credentials.Password}:{Nonce}:{text2}".CalculateMD5Hash();
						}
						empty = HA1Sess;
						break;
					default:
						return string.Empty;
					}
					string empty2 = string.Empty;
					string text3 = ((QualityOfProtections == null) ? null : QualityOfProtections.TrimAndLower());
					string text4 = ((!isProxy) ? request.MethodType.ToString().ToUpper() : "CONNECT");
					string text5 = ((!isProxy) ? request.CurrentUri.GetRequestPathAndQueryURL() : (request.CurrentUri.Host + ":" + request.CurrentUri.Port));
					if (text3 == null)
					{
						string arg = (request.MethodType.ToString().ToUpper() + ":" + request.CurrentUri.GetRequestPathAndQueryURL()).CalculateMD5Hash();
						empty2 = $"{empty}:{Nonce}:{arg}".CalculateMD5Hash();
					}
					else if (text3.Contains("auth-int"))
					{
						text3 = "auth-int";
						byte[] array = request.GetEntityBody();
						if (array == null)
						{
							array = string.Empty.GetASCIIBytes();
						}
						string text6 = $"{text4}:{text5}:{array.CalculateMD5Hash()}".CalculateMD5Hash();
						empty2 = $"{empty}:{Nonce}:{text2}:{text}:{text3}:{text6}".CalculateMD5Hash();
					}
					else
					{
						if (!text3.Contains("auth"))
						{
							return string.Empty;
						}
						text3 = "auth";
						string text7 = (text4 + ":" + text5).CalculateMD5Hash();
						empty2 = $"{empty}:{Nonce}:{text2}:{text}:{text3}:{text7}".CalculateMD5Hash();
					}
					string text8 = $"Digest username=\"{credentials.UserName}\", realm=\"{Realm}\", nonce=\"{Nonce}\", uri=\"{text5}\", cnonce=\"{text}\", response=\"{empty2}\"";
					if (text3 != null)
					{
						text8 = string.Concat(text8, ", qop=\"" + text3 + "\", nc=" + text2);
					}
					if (!string.IsNullOrEmpty(Opaque))
					{
						text8 = text8 + ", opaque=\"" + Opaque + "\"";
					}
					return text8;
				}
				}
			}
			catch
			{
			}
			return string.Empty;
		}

		public bool IsUriProtected(Uri uri)
		{
			if (string.CompareOrdinal(uri.Host, Uri.Host) != 0)
			{
				return false;
			}
			string text = uri.ToString();
			if (ProtectedUris != null && ProtectedUris.Count > 0)
			{
				for (int i = 0; i < ProtectedUris.Count; i++)
				{
					if (text.Contains(ProtectedUris[i]))
					{
						return true;
					}
				}
			}
			return true;
		}
	}
	public static class DigestStore
	{
		private static Dictionary<string, Digest> Digests = new Dictionary<string, Digest>();

		private static object Locker = new object();

		private static string[] SupportedAlgorithms = new string[2] { "digest", "basic" };

		public static Digest Get(Uri uri)
		{
			lock (Locker)
			{
				Digest value = null;
				if (Digests.TryGetValue(uri.Host, out value) && !value.IsUriProtected(uri))
				{
					return null;
				}
				return value;
			}
		}

		public static Digest GetOrCreate(Uri uri)
		{
			lock (Locker)
			{
				Digest value = null;
				if (!Digests.TryGetValue(uri.Host, out value))
				{
					Digests.Add(uri.Host, value = new Digest(uri));
				}
				return value;
			}
		}

		public static void Remove(Uri uri)
		{
			lock (Locker)
			{
				Digests.Remove(uri.Host);
			}
		}

		public static string FindBest(List<string> authHeaders)
		{
			if (authHeaders == null || authHeaders.Count == 0)
			{
				return string.Empty;
			}
			List<string> list = new List<string>(authHeaders.Count);
			for (int i = 0; i < authHeaders.Count; i++)
			{
				list.Add(authHeaders[i].ToLower());
			}
			int j;
			for (j = 0; j < SupportedAlgorithms.Length; j++)
			{
				int num = list.FindIndex((string header) => header.StartsWith(SupportedAlgorithms[j]));
				if (num != -1)
				{
					return authHeaders[num];
				}
			}
			return string.Empty;
		}
	}
}
namespace BestHTTP.Caching
{
	public class HTTPCacheFileInfo : IComparable<HTTPCacheFileInfo>
	{
		internal Uri Uri { get; set; }

		internal DateTime LastAccess { get; set; }

		public int BodyLength { get; set; }

		private string ETag { get; set; }

		private string LastModified { get; set; }

		private DateTime Expires { get; set; }

		private long Age { get; set; }

		private long MaxAge { get; set; }

		private DateTime Date { get; set; }

		private bool MustRevalidate { get; set; }

		private DateTime Received { get; set; }

		private string ConstructedPath { get; set; }

		internal ulong MappedNameIDX { get; set; }

		internal HTTPCacheFileInfo(Uri uri)
			: this(uri, DateTime.UtcNow, -1)
		{
		}

		internal HTTPCacheFileInfo(Uri uri, DateTime lastAcces, int bodyLength)
		{
			Uri = uri;
			LastAccess = lastAcces;
			BodyLength = bodyLength;
			MaxAge = -1L;
			MappedNameIDX = HTTPCacheService.GetNameIdx();
		}

		internal HTTPCacheFileInfo(Uri uri, BinaryReader reader, int version)
		{
			Uri = uri;
			LastAccess = DateTime.FromBinary(reader.ReadInt64());
			BodyLength = reader.ReadInt32();
			switch (version)
			{
			default:
				return;
			case 2:
				MappedNameIDX = reader.ReadUInt64();
				break;
			case 1:
				break;
			}
			ETag = reader.ReadString();
			LastModified = reader.ReadString();
			Expires = DateTime.FromBinary(reader.ReadInt64());
			Age = reader.ReadInt64();
			MaxAge = reader.ReadInt64();
			Date = DateTime.FromBinary(reader.ReadInt64());
			MustRevalidate = reader.ReadBoolean();
			Received = DateTime.FromBinary(reader.ReadInt64());
		}

		internal void SaveTo(BinaryWriter writer)
		{
			writer.Write(LastAccess.ToBinary());
			writer.Write(BodyLength);
			writer.Write(MappedNameIDX);
			writer.Write(ETag);
			writer.Write(LastModified);
			writer.Write(Expires.ToBinary());
			writer.Write(Age);
			writer.Write(MaxAge);
			writer.Write(Date.ToBinary());
			writer.Write(MustRevalidate);
			writer.Write(Received.ToBinary());
		}

		public string GetPath()
		{
			if (ConstructedPath != null)
			{
				return ConstructedPath;
			}
			return ConstructedPath = Path.Combine(HTTPCacheService.CacheFolder, MappedNameIDX.ToString("X"));
		}

		public bool IsExists()
		{
			if (!HTTPCacheService.IsSupported)
			{
				return false;
			}
			return File.Exists(GetPath());
		}

		internal void Delete()
		{
			if (!HTTPCacheService.IsSupported)
			{
				return;
			}
			string path = GetPath();
			try
			{
				File.Delete(path);
			}
			catch
			{
			}
			finally
			{
				Reset();
			}
		}

		private void Reset()
		{
			BodyLength = -1;
			ETag = string.Empty;
			Expires = DateTime.FromBinary(0L);
			LastModified = string.Empty;
			Age = 0L;
			MaxAge = -1L;
			Date = DateTime.FromBinary(0L);
			MustRevalidate = false;
			Received = DateTime.FromBinary(0L);
		}

		private void SetUpCachingValues(HTTPResponse response)
		{
			response.CacheFileInfo = this;
			ETag = response.GetFirstHeaderValue("ETag").ToStrOrEmpty();
			Expires = response.GetFirstHeaderValue("Expires").ToDateTime(DateTime.FromBinary(0L));
			LastModified = response.GetFirstHeaderValue("Last-Modified").ToStrOrEmpty();
			Age = response.GetFirstHeaderValue("Age").ToInt64(0L);
			Date = response.GetFirstHeaderValue("Date").ToDateTime(DateTime.FromBinary(0L));
			string firstHeaderValue = response.GetFirstHeaderValue("cache-control");
			if (!string.IsNullOrEmpty(firstHeaderValue))
			{
				string[] array = firstHeaderValue.FindOption("max-age");
				if (array != null && double.TryParse(array[1], out var result))
				{
					MaxAge = (int)result;
				}
				MustRevalidate = firstHeaderValue.ToLower().Contains("must-revalidate");
			}
			Received = DateTime.UtcNow;
		}

		internal bool WillExpireInTheFuture()
		{
			if (!IsExists())
			{
				return false;
			}
			if (MustRevalidate)
			{
				return false;
			}
			if (MaxAge != -1)
			{
				long val = Math.Max(0L, (long)(Received - Date).TotalSeconds);
				long num = Math.Max(val, Age);
				long num2 = (long)(DateTime.UtcNow - Date).TotalSeconds;
				long num3 = num + num2;
				return num3 < MaxAge;
			}
			return Expires > DateTime.UtcNow;
		}

		internal void SetUpRevalidationHeaders(HTTPRequest request)
		{
			if (IsExists())
			{
				if (!string.IsNullOrEmpty(ETag))
				{
					request.AddHeader("If-None-Match", ETag);
				}
				if (!string.IsNullOrEmpty(LastModified))
				{
					request.AddHeader("If-Modified-Since", LastModified);
				}
			}
		}

		public Stream GetBodyStream(out int length)
		{
			if (!IsExists())
			{
				length = 0;
				return null;
			}
			length = BodyLength;
			LastAccess = DateTime.UtcNow;
			FileStream fileStream = new FileStream(GetPath(), FileMode.Open, FileAccess.Read, FileShare.Read);
			fileStream.Seek(-length, SeekOrigin.End);
			return fileStream;
		}

		internal HTTPResponse ReadResponseTo(HTTPRequest request)
		{
			if (!IsExists())
			{
				return null;
			}
			LastAccess = DateTime.UtcNow;
			using FileStream stream = new FileStream(GetPath(), FileMode.Open, FileAccess.Read, FileShare.Read);
			HTTPResponse hTTPResponse = new HTTPResponse(request, stream, request.UseStreaming, isFromCache: true);
			hTTPResponse.CacheFileInfo = this;
			hTTPResponse.Receive(BodyLength);
			return hTTPResponse;
		}

		internal void Store(HTTPResponse response)
		{
			if (!HTTPCacheService.IsSupported)
			{
				return;
			}
			string path = GetPath();
			if (path.Length > HTTPManager.MaxPathLength)
			{
				return;
			}
			if (File.Exists(path))
			{
				Delete();
			}
			using (FileStream fileStream = new FileStream(path, FileMode.Create))
			{
				fileStream.WriteLine("HTTP/1.1 {0} {1}", response.StatusCode, response.Message);
				foreach (KeyValuePair<string, List<string>> header in response.Headers)
				{
					for (int i = 0; i < header.Value.Count; i++)
					{
						fileStream.WriteLine("{0}: {1}", header.Key, header.Value[i]);
					}
				}
				fileStream.WriteLine();
				fileStream.Write(response.Data, 0, response.Data.Length);
			}
			BodyLength = response.Data.Length;
			LastAccess = DateTime.UtcNow;
			SetUpCachingValues(response);
		}

		internal Stream GetSaveStream(HTTPResponse response)
		{
			if (!HTTPCacheService.IsSupported)
			{
				return null;
			}
			LastAccess = DateTime.UtcNow;
			string path = GetPath();
			if (File.Exists(path))
			{
				Delete();
			}
			if (path.Length > HTTPManager.MaxPathLength)
			{
				return null;
			}
			using (FileStream fs = new FileStream(path, FileMode.Create))
			{
				fs.WriteLine("HTTP/1.1 {0} {1}", response.StatusCode, response.Message);
				foreach (KeyValuePair<string, List<string>> header in response.Headers)
				{
					for (int i = 0; i < header.Value.Count; i++)
					{
						fs.WriteLine("{0}: {1}", header.Key, header.Value[i]);
					}
				}
				fs.WriteLine();
			}
			if (response.IsFromCache && !response.Headers.ContainsKey("content-length"))
			{
				response.Headers.Add("content-length", new List<string> { BodyLength.ToString() });
			}
			SetUpCachingValues(response);
			return new FileStream(GetPath(), FileMode.Append);
		}

		public int CompareTo(HTTPCacheFileInfo other)
		{
			return LastAccess.CompareTo(other.LastAccess);
		}
	}
	internal sealed class HTTPCacheFileLock
	{
		private static Dictionary<Uri, object> FileLocks = new Dictionary<Uri, object>();

		private static object SyncRoot = new object();

		internal static object Acquire(Uri uri)
		{
			lock (SyncRoot)
			{
				if (!FileLocks.TryGetValue(uri, out var value))
				{
					FileLocks.Add(uri, value = new object());
				}
				return value;
			}
		}

		internal static void Remove(Uri uri)
		{
			lock (SyncRoot)
			{
				if (FileLocks.ContainsKey(uri))
				{
					FileLocks.Remove(uri);
				}
			}
		}

		internal static void Clear()
		{
			lock (SyncRoot)
			{
				FileLocks.Clear();
			}
		}
	}
	public sealed class HTTPCacheMaintananceParams
	{
		public TimeSpan DeleteOlder { get; private set; }

		public ulong MaxCacheSize { get; private set; }

		public HTTPCacheMaintananceParams(TimeSpan deleteOlder, ulong maxCacheSize)
		{
			DeleteOlder = deleteOlder;
			MaxCacheSize = maxCacheSize;
		}
	}
	public sealed class UriComparer : IEqualityComparer<Uri>
	{
		public bool Equals(Uri x, Uri y)
		{
			return Uri.Compare(x, y, UriComponents.HttpRequestUrl, UriFormat.SafeUnescaped, StringComparison.Ordinal) == 0;
		}

		public int GetHashCode(Uri uri)
		{
			return uri.ToString().GetHashCode();
		}
	}
	public static class HTTPCacheService
	{
		private const int LibraryVersion = 2;

		private static bool isSupported;

		private static bool IsSupportCheckDone;

		private static Dictionary<Uri, HTTPCacheFileInfo> library;

		private static Dictionary<ulong, HTTPCacheFileInfo> UsedIndexes;

		private static bool InClearThread;

		private static bool InMaintainenceThread;

		private static ulong NextNameIDX;

		public static bool IsSupported
		{
			get
			{
				if (IsSupportCheckDone)
				{
					return isSupported;
				}
				try
				{
					File.Exists(HTTPManager.GetRootCacheFolder());
					isSupported = true;
				}
				catch
				{
					isSupported = false;
					HTTPManager.Logger.Warning("HTTPCacheService", "Cache Service Disabled!");
				}
				finally
				{
					IsSupportCheckDone = true;
				}
				return isSupported;
			}
		}

		private static Dictionary<Uri, HTTPCacheFileInfo> Library
		{
			get
			{
				LoadLibrary();
				return library;
			}
		}

		internal static string CacheFolder { get; private set; }

		private static string LibraryPath { get; set; }

		static HTTPCacheService()
		{
			UsedIndexes = new Dictionary<ulong, HTTPCacheFileInfo>();
			NextNameIDX = 1uL;
		}

		internal static void CheckSetup()
		{
			if (!IsSupported)
			{
				return;
			}
			try
			{
				SetupCacheFolder();
				LoadLibrary();
			}
			catch
			{
			}
		}

		internal static void SetupCacheFolder()
		{
			if (!IsSupported)
			{
				return;
			}
			try
			{
				if (string.IsNullOrEmpty(CacheFolder) || string.IsNullOrEmpty(LibraryPath))
				{
					CacheFolder = Path.Combine(HTTPManager.GetRootCacheFolder(), "HTTPCache");
					if (!Directory.Exists(CacheFolder))
					{
						Directory.CreateDirectory(CacheFolder);
					}
					LibraryPath = Path.Combine(HTTPManager.GetRootCacheFolder(), "Library");
				}
			}
			catch
			{
				isSupported = false;
				HTTPManager.Logger.Warning("HTTPCacheService", "Cache Service Disabled!");
			}
		}

		internal static ulong GetNameIdx()
		{
			lock (Library)
			{
				ulong nextNameIDX = NextNameIDX;
				do
				{
					NextNameIDX = ++NextNameIDX % ulong.MaxValue;
				}
				while (UsedIndexes.ContainsKey(NextNameIDX));
				return nextNameIDX;
			}
		}

		internal static bool HasEntity(Uri uri)
		{
			if (!IsSupported)
			{
				return false;
			}
			lock (Library)
			{
				return Library.ContainsKey(uri);
			}
		}

		internal static bool DeleteEntity(Uri uri, bool removeFromLibrary = true)
		{
			if (!IsSupported)
			{
				return false;
			}
			object obj = HTTPCacheFileLock.Acquire(uri);
			lock (obj)
			{
				try
				{
					lock (Library)
					{
						HTTPCacheFileInfo value;
						bool flag = Library.TryGetValue(uri, out value);
						if (flag)
						{
							value.Delete();
						}
						if (flag && removeFromLibrary)
						{
							Library.Remove(uri);
							UsedIndexes.Remove(value.MappedNameIDX);
						}
						return true;
					}
				}
				finally
				{
				}
			}
		}

		internal static bool IsCachedEntityExpiresInTheFuture(HTTPRequest request)
		{
			if (!IsSupported)
			{
				return false;
			}
			lock (Library)
			{
				if (Library.TryGetValue(request.CurrentUri, out var value))
				{
					return value.WillExpireInTheFuture();
				}
			}
			return false;
		}

		internal static void SetHeaders(HTTPRequest request)
		{
			if (!IsSupported)
			{
				return;
			}
			lock (Library)
			{
				if (Library.TryGetValue(request.CurrentUri, out var value))
				{
					value.SetUpRevalidationHeaders(request);
				}
			}
		}

		internal static HTTPCacheFileInfo GetEntity(Uri uri)
		{
			if (!IsSupported)
			{
				return null;
			}
			HTTPCacheFileInfo value = null;
			lock (Library)
			{
				Library.TryGetValue(uri, out value);
				return value;
			}
		}

		internal static HTTPResponse GetFullResponse(HTTPRequest request)
		{
			if (!IsSupported)
			{
				return null;
			}
			lock (Library)
			{
				if (Library.TryGetValue(request.CurrentUri, out var value))
				{
					return value.ReadResponseTo(request);
				}
			}
			return null;
		}

		internal static bool IsCacheble(Uri uri, HTTPMethods method, HTTPResponse response)
		{
			if (!IsSupported)
			{
				return false;
			}
			if (method != HTTPMethods.Get)
			{
				return false;
			}
			if (response == null)
			{
				return false;
			}
			if (response.StatusCode < 200 || response.StatusCode >= 400)
			{
				return false;
			}
			List<string> headerValues = response.GetHeaderValues("cache-control");
			if (headerValues != null && headerValues.Exists(delegate(string headerValue)
			{
				string text = headerValue.ToLower();
				return text.Contains("no-store") || text.Contains("no-cache");
			}))
			{
				return false;
			}
			List<string> headerValues2 = response.GetHeaderValues("pragma");
			if (headerValues2 != null && headerValues2.Exists(delegate(string headerValue)
			{
				string text = headerValue.ToLower();
				return text.Contains("no-store") || text.Contains("no-cache");
			}))
			{
				return false;
			}
			List<string> headerValues3 = response.GetHeaderValues("content-range");
			if (headerValues3 != null)
			{
				return false;
			}
			return true;
		}

		internal static HTTPCacheFileInfo Store(Uri uri, HTTPMethods method, HTTPResponse response)
		{
			if (response == null || response.Data == null || response.Data.Length == 0)
			{
				return null;
			}
			if (!IsSupported)
			{
				return null;
			}
			HTTPCacheFileInfo value = null;
			lock (Library)
			{
				if (!Library.TryGetValue(uri, out value))
				{
					Library.Add(uri, value = new HTTPCacheFileInfo(uri));
					UsedIndexes.Add(value.MappedNameIDX, value);
				}
				try
				{
					value.Store(response);
					if (HTTPManager.Logger.Level == Loglevels.All)
					{
						HTTPManager.Logger.Verbose("HTTPCacheService", $"{uri.ToString()} - Saved to cache");
					}
				}
				catch
				{
					DeleteEntity(uri);
					throw;
				}
			}
			return value;
		}

		internal static Stream PrepareStreamed(Uri uri, HTTPResponse response)
		{
			if (!IsSupported)
			{
				return null;
			}
			lock (Library)
			{
				if (!Library.TryGetValue(uri, out var value))
				{
					Library.Add(uri, value = new HTTPCacheFileInfo(uri));
					UsedIndexes.Add(value.MappedNameIDX, value);
				}
				try
				{
					return value.GetSaveStream(response);
				}
				catch
				{
					DeleteEntity(uri);
					throw;
				}
			}
		}

		public static void BeginClear()
		{
			if (IsSupported && !InClearThread)
			{
				InClearThread = true;
				SetupCacheFolder();
				ThreadPool.QueueUserWorkItem(delegate(object param)
				{
					ClearImpl(param);
				});
			}
		}

		private static void ClearImpl(object param)
		{
			if (!IsSupported)
			{
				return;
			}
			try
			{
				string[] files = Directory.GetFiles(CacheFolder);
				for (int i = 0; i < files.Length; i++)
				{
					try
					{
						File.Delete(files[i]);
					}
					catch
					{
					}
				}
			}
			finally
			{
				UsedIndexes.Clear();
				library.Clear();
				NextNameIDX = 1uL;
				SaveLibrary();
				InClearThread = false;
			}
		}

		public static void BeginMaintainence(HTTPCacheMaintananceParams maintananceParam)
		{
			if (maintananceParam == null)
			{
				throw new ArgumentNullException("maintananceParams == null");
			}
			if (!IsSupported || InMaintainenceThread)
			{
				return;
			}
			InMaintainenceThread = true;
			SetupCacheFolder();
			ThreadPool.QueueUserWorkItem(delegate
			{
				try
				{
					lock (Library)
					{
						DateTime dateTime = DateTime.UtcNow - maintananceParam.DeleteOlder;
						List<HTTPCacheFileInfo> list = new List<HTTPCacheFileInfo>();
						foreach (KeyValuePair<Uri, HTTPCacheFileInfo> item in Library)
						{
							if (item.Value.LastAccess < dateTime && DeleteEntity(item.Key, removeFromLibrary: false))
							{
								list.Add(item.Value);
							}
						}
						for (int i = 0; i < list.Count; i++)
						{
							Library.Remove(list[i].Uri);
							UsedIndexes.Remove(list[i].MappedNameIDX);
						}
						list.Clear();
						ulong num = GetCacheSize();
						if (num > maintananceParam.MaxCacheSize)
						{
							List<HTTPCacheFileInfo> list2 = new List<HTTPCacheFileInfo>(library.Count);
							foreach (KeyValuePair<Uri, HTTPCacheFileInfo> item2 in library)
							{
								list2.Add(item2.Value);
							}
							list2.Sort();
							int num2 = 0;
							while (num >= maintananceParam.MaxCacheSize && num2 < list2.Count)
							{
								try
								{
									HTTPCacheFileInfo hTTPCacheFileInfo = list2[num2];
									ulong num3 = (ulong)hTTPCacheFileInfo.BodyLength;
									DeleteEntity(hTTPCacheFileInfo.Uri);
									num -= num3;
								}
								catch
								{
								}
								finally
								{
									num2++;
								}
							}
						}
					}
				}
				finally
				{
					SaveLibrary();
					InMaintainenceThread = false;
				}
			});
		}

		public static int GetCacheEntityCount()
		{
			if (!IsSupported)
			{
				return 0;
			}
			CheckSetup();
			lock (Library)
			{
				return Library.Count;
			}
		}

		public static ulong GetCacheSize()
		{
			ulong num = 0uL;
			if (!IsSupported)
			{
				return num;
			}
			CheckSetup();
			lock (Library)
			{
				foreach (KeyValuePair<Uri, HTTPCacheFileInfo> item in Library)
				{
					if (item.Value.BodyLength > 0)
					{
						num += (ulong)item.Value.BodyLength;
					}
				}
				return num;
			}
		}

		private static void LoadLibrary()
		{
			if (library != null || !IsSupported)
			{
				return;
			}
			library = new Dictionary<Uri, HTTPCacheFileInfo>(new UriComparer());
			if (!File.Exists(LibraryPath))
			{
				DeleteUnusedFiles();
				return;
			}
			try
			{
				int num;
				lock (library)
				{
					using FileStream input = new FileStream(LibraryPath, FileMode.Open);
					using BinaryReader binaryReader = new BinaryReader(input);
					num = binaryReader.ReadInt32();
					if (num > 1)
					{
						NextNameIDX = binaryReader.ReadUInt64();
					}
					int num2 = binaryReader.ReadInt32();
					for (int i = 0; i < num2; i++)
					{
						Uri uri = new Uri(binaryReader.ReadString());
						HTTPCacheFileInfo hTTPCacheFileInfo = new HTTPCacheFileInfo(uri, binaryReader, num);
						if (hTTPCacheFileInfo.IsExists())
						{
							library.Add(uri, hTTPCacheFileInfo);
							if (num > 1)
							{
								UsedIndexes.Add(hTTPCacheFileInfo.MappedNameIDX, hTTPCacheFileInfo);
							}
						}
					}
				}
				if (num == 1)
				{
					BeginClear();
				}
				else
				{
					DeleteUnusedFiles();
				}
			}
			catch
			{
			}
		}

		internal static void SaveLibrary()
		{
			if (library == null || !IsSupported)
			{
				return;
			}
			try
			{
				lock (Library)
				{
					using FileStream output = new FileStream(LibraryPath, FileMode.Create);
					using BinaryWriter binaryWriter = new BinaryWriter(output);
					binaryWriter.Write(2);
					binaryWriter.Write(NextNameIDX);
					binaryWriter.Write(Library.Count);
					foreach (KeyValuePair<Uri, HTTPCacheFileInfo> item in Library)
					{
						binaryWriter.Write(item.Key.ToString());
						item.Value.SaveTo(binaryWriter);
					}
				}
			}
			catch
			{
			}
		}

		internal static void SetBodyLength(Uri uri, int bodyLength)
		{
			if (!IsSupported)
			{
				return;
			}
			lock (Library)
			{
				if (Library.TryGetValue(uri, out var value))
				{
					value.BodyLength = bodyLength;
					return;
				}
				Library.Add(uri, value = new HTTPCacheFileInfo(uri, DateTime.UtcNow, bodyLength));
				UsedIndexes.Add(value.MappedNameIDX, value);
			}
		}

		private static void DeleteUnusedFiles()
		{
			if (!IsSupported)
			{
				return;
			}
			CheckSetup();
			string[] files = Directory.GetFiles(CacheFolder);
			for (int i = 0; i < files.Length; i++)
			{
				try
				{
					string fileName = Path.GetFileName(files[i]);
					ulong result = 0uL;
					bool flag = false;
					if (ulong.TryParse(fileName, NumberStyles.AllowHexSpecifier, null, out result))
					{
						lock (Library)
						{
							flag = !UsedIndexes.ContainsKey(result);
						}
					}
					else
					{
						flag = true;
					}
					if (flag)
					{
						File.Delete(files[i]);
					}
				}
				catch
				{
				}
			}
		}
	}
}
namespace BestHTTP
{
	internal delegate void HTTPConnectionRecycledDelegate(ConnectionBase conn);
	internal abstract class ConnectionBase : IDisposable
	{
		protected DateTime LastProcessTime;

		protected HTTPConnectionRecycledDelegate OnConnectionRecycled;

		private bool IsThreaded;

		public string ServerAddress { get; protected set; }

		public HTTPConnectionStates State { get; protected set; }

		public bool IsFree => State == HTTPConnectionStates.Initial || State == HTTPConnectionStates.Free;

		public bool IsActive => State > HTTPConnectionStates.Initial && State < HTTPConnectionStates.Free;

		public HTTPRequest CurrentRequest { get; protected set; }

		public virtual bool IsRemovable => IsFree && DateTime.UtcNow - LastProcessTime > HTTPManager.MaxConnectionIdleTime;

		public DateTime StartTime { get; protected set; }

		public DateTime TimedOutStart { get; protected set; }

		protected HTTPProxy Proxy { get; set; }

		public bool HasProxy => Proxy != null;

		public Uri LastProcessedUri { get; protected set; }

		protected bool IsDisposed { get; private set; }

		public ConnectionBase(string serverAddress)
			: this(serverAddress, threaded: true)
		{
		}

		public ConnectionBase(string serverAddress, bool threaded)
		{
			ServerAddress = serverAddress;
			State = HTTPConnectionStates.Initial;
			LastProcessTime = DateTime.UtcNow;
			IsThreaded = threaded;
		}

		internal abstract void Abort(HTTPConnectionStates hTTPConnectionStates);

		internal void Process(HTTPRequest request)
		{
			if (State == HTTPConnectionStates.Processing)
			{
				throw new Exception("Connection already processing a request!");
			}
			StartTime = DateTime.MaxValue;
			State = HTTPConnectionStates.Processing;
			CurrentRequest = request;
			if (IsThreaded)
			{
				ThreadPool.QueueUserWorkItem(ThreadFunc);
			}
			else
			{
				ThreadFunc(null);
			}
		}

		protected virtual void ThreadFunc(object param)
		{
		}

		internal void HandleProgressCallback()
		{
			if (CurrentRequest.OnProgress != null && CurrentRequest.DownloadProgressChanged)
			{
				try
				{
					CurrentRequest.OnProgress(CurrentRequest, CurrentRequest.Downloaded, CurrentRequest.DownloadLength);
				}
				catch (Exception ex)
				{
					HTTPManager.Logger.Exception("ConnectionBase", "HandleProgressCallback - OnProgress", ex);
				}
				CurrentRequest.DownloadProgressChanged = false;
			}
			if (CurrentRequest.OnUploadProgress != null && CurrentRequest.UploadProgressChanged)
			{
				try
				{
					CurrentRequest.OnUploadProgress(CurrentRequest, CurrentRequest.Uploaded, CurrentRequest.UploadLength);
				}
				catch (Exception ex2)
				{
					HTTPManager.Logger.Exception("ConnectionBase", "HandleProgressCallback - OnUploadProgress", ex2);
				}
				CurrentRequest.UploadProgressChanged = false;
			}
		}

		internal void HandleCallback()
		{
			try
			{
				HandleProgressCallback();
				if (State == HTTPConnectionStates.Upgraded)
				{
					if (CurrentRequest != null && CurrentRequest.Response != null && CurrentRequest.Response.IsUpgraded)
					{
						CurrentRequest.UpgradeCallback();
					}
					State = HTTPConnectionStates.WaitForProtocolShutdown;
				}
				else
				{
					CurrentRequest.CallCallback();
				}
			}
			catch (Exception ex)
			{
				HTTPManager.Logger.Exception("ConnectionBase", "HandleCallback", ex);
			}
		}

		internal void Recycle(HTTPConnectionRecycledDelegate onConnectionRecycled)
		{
			OnConnectionRecycled = onConnectionRecycled;
			if (State <= HTTPConnectionStates.Initial || State >= HTTPConnectionStates.WaitForProtocolShutdown || State == HTTPConnectionStates.Redirected)
			{
				RecycleNow();
			}
		}

		protected void RecycleNow()
		{
			if (State == HTTPConnectionStates.TimedOut || State == HTTPConnectionStates.Closed)
			{
				LastProcessTime = DateTime.MinValue;
			}
			State = HTTPConnectionStates.Free;
			CurrentRequest = null;
			if (OnConnectionRecycled != null)
			{
				OnConnectionRecycled(this);
				OnConnectionRecycled = null;
			}
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		protected virtual void Dispose(bool disposing)
		{
			IsDisposed = true;
		}
	}
	public sealed class StreamList : Stream
	{
		private Stream[] Streams;

		private int CurrentIdx;

		public override bool CanRead
		{
			get
			{
				if (CurrentIdx >= Streams.Length)
				{
					return false;
				}
				return Streams[CurrentIdx].CanRead;
			}
		}

		public override bool CanSeek => false;

		public override bool CanWrite
		{
			get
			{
				if (CurrentIdx >= Streams.Length)
				{
					return false;
				}
				return Streams[CurrentIdx].CanWrite;
			}
		}

		public override long Length
		{
			get
			{
				if (CurrentIdx >= Streams.Length)
				{
					return 0L;
				}
				long num = 0L;
				for (int i = 0; i < Streams.Length; i++)
				{
					num += Streams[i].Length;
				}
				return num;
			}
		}

		public override long Position
		{
			get
			{
				throw new NotImplementedException("Position get");
			}
			set
			{
				throw new NotImplementedException("Position set");
			}
		}

		public StreamList(params Stream[] streams)
		{
			Streams = streams;
			CurrentIdx = 0;
		}

		public override void Flush()
		{
			if (CurrentIdx < Streams.Length)
			{
				for (int i = 0; i <= CurrentIdx; i++)
				{
					Streams[i].Flush();
				}
			}
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			if (CurrentIdx >= Streams.Length)
			{
				return -1;
			}
			int i;
			for (i = Streams[CurrentIdx].Read(buffer, offset, count); i < count; i += Streams[CurrentIdx].Read(buffer, offset + i, count - i))
			{
				if (CurrentIdx++ >= Streams.Length)
				{
					break;
				}
			}
			return i;
		}

		public override void Write(byte[] buffer, int offset, int count)
		{
			if (CurrentIdx < Streams.Length)
			{
				Streams[CurrentIdx].Write(buffer, offset, count);
			}
		}

		public void Write(string str)
		{
			byte[] aSCIIBytes = str.GetASCIIBytes();
			Write(aSCIIBytes, 0, aSCIIBytes.Length);
		}

		protected override void Dispose(bool disposing)
		{
			for (int i = 0; i < Streams.Length; i++)
			{
				try
				{
					Streams[i].Dispose();
				}
				catch (Exception ex)
				{
					HTTPManager.Logger.Exception("StreamList", "Dispose", ex);
				}
			}
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			if (CurrentIdx >= Streams.Length)
			{
				return 0L;
			}
			return Streams[CurrentIdx].Seek(offset, origin);
		}

		public override void SetLength(long value)
		{
			throw new NotImplementedException("SetLength");
		}
	}
	internal sealed class FileConnection : ConnectionBase
	{
		public FileConnection(string serverAddress)
			: base(serverAddress)
		{
		}

		internal override void Abort(HTTPConnectionStates newState)
		{
			base.State = newState;
			HTTPConnectionStates state = base.State;
			if (state == HTTPConnectionStates.TimedOut)
			{
				base.TimedOutStart = DateTime.UtcNow;
			}
			throw new NotImplementedException();
		}

		protected override void ThreadFunc(object param)
		{
			try
			{
				using FileStream fileStream = new FileStream(base.CurrentRequest.CurrentUri.LocalPath, FileMode.Open, FileAccess.Read);
				using StreamList streamList = new StreamList(new MemoryStream(), fileStream);
				streamList.Write("HTTP/1.1 200 Ok\r\n");
				streamList.Write("Content-Type: application/octet-stream\r\n");
				streamList.Write("Content-Length: " + fileStream.Length + "\r\n");
				streamList.Write("\r\n");
				streamList.Seek(0L, SeekOrigin.Begin);
				base.CurrentRequest.Response = new HTTPResponse(base.CurrentRequest, streamList, base.CurrentRequest.UseStreaming, isFromCache: false);
				if (!base.CurrentRequest.Response.Receive())
				{
					base.CurrentRequest.Response = null;
				}
			}
			catch (Exception exception)
			{
				if (base.CurrentRequest != null)
				{
					base.CurrentRequest.Response = null;
					switch (base.State)
					{
					case HTTPConnectionStates.AbortRequested:
						base.CurrentRequest.State = HTTPRequestStates.Aborted;
						break;
					case HTTPConnectionStates.TimedOut:
						base.CurrentRequest.State = HTTPRequestStates.TimedOut;
						break;
					default:
						base.CurrentRequest.Exception = exception;
						base.CurrentRequest.State = HTTPRequestStates.Error;
						break;
					}
				}
			}
			finally
			{
				base.State = HTTPConnectionStates.Closed;
				if (base.CurrentRequest.State == HTTPRequestStates.Processing)
				{
					if (base.CurrentRequest.Response != null)
					{
						base.CurrentRequest.State = HTTPRequestStates.Finished;
					}
					else
					{
						base.CurrentRequest.State = HTTPRequestStates.Error;
					}
				}
			}
		}
	}
}
namespace BestHTTP.Cookies
{
	public sealed class Cookie : IComparable<Cookie>, IEquatable<Cookie>
	{
		private const int Version = 1;

		public string Name { get; private set; }

		public string Value { get; private set; }

		public DateTime Date { get; internal set; }

		public DateTime LastAccess { get; set; }

		public DateTime Expires { get; private set; }

		public long MaxAge { get; private set; }

		public bool IsSession { get; private set; }

		public string Domain { get; private set; }

		public string Path { get; private set; }

		public bool IsSecure { get; private set; }

		public bool IsHttpOnly { get; private set; }

		public Cookie(string name, string value)
			: this(name, value, "/", string.Empty)
		{
		}

		public Cookie(string name, string value, string path)
			: this(name, value, path, string.Empty)
		{
		}

		public Cookie(string name, string value, string path, string domain)
			: this()
		{
			Name = name;
			Value = value;
			Path = path;
			Domain = domain;
		}

		public Cookie(Uri uri, string name, string value, DateTime expires, bool isSession = true)
			: this(name, value, uri.AbsolutePath, uri.Host)
		{
			Expires = expires;
			IsSession = isSession;
			Date = DateTime.UtcNow;
		}

		public Cookie(Uri uri, string name, string value, long maxAge = -1L, bool isSession = true)
			: this(name, value, uri.AbsolutePath, uri.Host)
		{
			MaxAge = maxAge;
			IsSession = isSession;
			Date = DateTime.UtcNow;
		}

		internal Cookie()
		{
			IsSession = true;
			MaxAge = -1L;
			LastAccess = DateTime.UtcNow;
		}

		public bool WillExpireInTheFuture()
		{
			if (IsSession)
			{
				return true;
			}
			return (MaxAge == -1) ? (Expires > DateTime.UtcNow) : (Math.Max(0L, (long)(DateTime.UtcNow - Date).TotalSeconds) < MaxAge);
		}

		public uint GuessSize()
		{
			return (uint)(((Name != null) ? (Name.Length * 2) : 0) + ((Value != null) ? (Value.Length * 2) : 0) + ((Domain != null) ? (Domain.Length * 2) : 0) + ((Path != null) ? (Path.Length * 2) : 0) + 32 + 3);
		}

		public static Cookie Parse(string header, Uri defaultDomain)
		{
			Cookie cookie = new Cookie();
			try
			{
				List<HeaderValue> list = ParseCookieHeader(header);
				foreach (HeaderValue item in list)
				{
					switch (item.Key.ToLowerInvariant())
					{
					case "path":
					{
						object path;
						if (string.IsNullOrEmpty(item.Value) || !item.Value.StartsWith("/"))
						{
							path = "/";
						}
						else
						{
							string text = (cookie.Path = item.Value);
							path = text;
						}
						cookie.Path = (string)path;
						break;
					}
					case "domain":
						if (string.IsNullOrEmpty(item.Value))
						{
							return null;
						}
						cookie.Domain = ((!item.Value.StartsWith(".")) ? item.Value : item.Value.Substring(1));
						break;
					case "expires":
						cookie.Expires = item.Value.ToDateTime(DateTime.FromBinary(0L));
						cookie.IsSession = false;
						break;
					case "max-age":
						cookie.MaxAge = item.Value.ToInt64(-1L);
						cookie.IsSession = false;
						break;
					case "secure":
						cookie.IsSecure = true;
						break;
					case "httponly":
						cookie.IsHttpOnly = true;
						break;
					default:
						cookie.Name = item.Key;
						cookie.Value = item.Value;
						break;
					}
				}
				if (HTTPManager.EnablePrivateBrowsing)
				{
					cookie.IsSession = true;
				}
				if (string.IsNullOrEmpty(cookie.Domain))
				{
					cookie.Domain = defaultDomain.Host;
				}
				if (string.IsNullOrEmpty(cookie.Path))
				{
					cookie.Path = defaultDomain.AbsolutePath;
				}
				DateTime date = (cookie.LastAccess = DateTime.UtcNow);
				cookie.Date = date;
			}
			catch
			{
			}
			return cookie;
		}

		internal void SaveTo(BinaryWriter stream)
		{
			stream.Write(1);
			stream.Write(Name ?? string.Empty);
			stream.Write(Value ?? string.Empty);
			stream.Write(Date.ToBinary());
			stream.Write(LastAccess.ToBinary());
			stream.Write(Expires.ToBinary());
			stream.Write(MaxAge);
			stream.Write(IsSession);
			stream.Write(Domain ?? string.Empty);
			stream.Write(Path ?? string.Empty);
			stream.Write(IsSecure);
			stream.Write(IsHttpOnly);
		}

		internal void LoadFrom(BinaryReader stream)
		{
			stream.ReadInt32();
			Name = stream.ReadString();
			Value = stream.ReadString();
			Date = DateTime.FromBinary(stream.ReadInt64());
			LastAccess = DateTime.FromBinary(stream.ReadInt64());
			Expires = DateTime.FromBinary(stream.ReadInt64());
			MaxAge = stream.ReadInt64();
			IsSession = stream.ReadBoolean();
			Domain = stream.ReadString();
			Path = stream.ReadString();
			IsSecure = stream.ReadBoolean();
			IsHttpOnly = stream.ReadBoolean();
		}

		public override string ToString()
		{
			return Name + "=" + Value;
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			return Equals(obj as Cookie);
		}

		public bool Equals(Cookie cookie)
		{
			if (cookie == null)
			{
				return false;
			}
			if (object.ReferenceEquals(this, cookie))
			{
				return true;
			}
			return Name.Equals(cookie.Name, StringComparison.Ordinal) && ((Domain == null && cookie.Domain == null) || Domain.Equals(cookie.Domain, StringComparison.Ordinal)) && ((Path == null && cookie.Path == null) || Path.Equals(cookie.Path, StringComparison.Ordinal));
		}

		public override int GetHashCode()
		{
			return ToString().GetHashCode();
		}

		private static string ReadValue(string str, ref int pos)
		{
			string empty = string.Empty;
			if (str == null)
			{
				return empty;
			}
			return str.Read(ref pos, ';');
		}

		private static List<HeaderValue> ParseCookieHeader(string str)
		{
			List<HeaderValue> list = new List<HeaderValue>();
			if (str == null)
			{
				return list;
			}
			int pos = 0;
			while (pos < str.Length)
			{
				string key = str.Read(ref pos, (char ch) => ch != '=' && ch != ';').Trim();
				HeaderValue headerValue = new HeaderValue(key);
				if (pos < str.Length && str[pos - 1] == '=')
				{
					headerValue.Value = ReadValue(str, ref pos);
				}
				list.Add(headerValue);
			}
			return list;
		}

		public int CompareTo(Cookie other)
		{
			return LastAccess.CompareTo(other.LastAccess);
		}
	}
	public static class CookieJar
	{
		private const int Version = 1;

		public static TimeSpan AccessThreshold = TimeSpan.FromDays(7.0);

		private static List<Cookie> Cookies = new List<Cookie>();

		private static object Locker = new object();

		private static bool _isSavingSupported;

		private static bool IsSupportCheckDone;

		private static bool Loaded;

		public static bool IsSavingSupported
		{
			get
			{
				if (IsSupportCheckDone)
				{
					return _isSavingSupported;
				}
				try
				{
					File.Exists(HTTPManager.GetRootCacheFolder());
					_isSavingSupported = true;
				}
				catch
				{
					_isSavingSupported = false;
					HTTPManager.Logger.Warning("CookieJar", "Cookie saving and loading disabled!");
				}
				finally
				{
					IsSupportCheckDone = true;
				}
				return _isSavingSupported;
			}
		}

		private static string CookieFolder { get; set; }

		private static string LibraryPath { get; set; }

		internal static void SetupFolder()
		{
			if (!IsSavingSupported)
			{
				return;
			}
			try
			{
				if (string.IsNullOrEmpty(CookieFolder) || string.IsNullOrEmpty(LibraryPath))
				{
					CookieFolder = Path.Combine(HTTPManager.GetRootCacheFolder(), "Cookies");
					LibraryPath = Path.Combine(CookieFolder, "Library");
				}
			}
			catch
			{
			}
		}

		internal static void Set(HTTPResponse response)
		{
			if (response == null)
			{
				return;
			}
			lock (Locker)
			{
				try
				{
					Maintain();
					List<Cookie> list = new List<Cookie>();
					List<string> headerValues = response.GetHeaderValues("set-cookie");
					if (headerValues == null)
					{
						return;
					}
					foreach (string item in headerValues)
					{
						try
						{
							Cookie cookie = Cookie.Parse(item, response.baseRequest.CurrentUri);
							if (cookie == null)
							{
								continue;
							}
							int idx;
							Cookie cookie2 = Find(cookie, out idx);
							if (!string.IsNullOrEmpty(cookie.Value) && cookie.WillExpireInTheFuture())
							{
								if (cookie2 == null)
								{
									Cookies.Add(cookie);
									list.Add(cookie);
								}
								else
								{
									cookie.Date = cookie2.Date;
									Cookies[idx] = cookie;
									list.Add(cookie);
								}
							}
							else if (idx != -1)
							{
								Cookies.RemoveAt(idx);
							}
						}
						catch
						{
						}
					}
					response.Cookies = list;
				}
				catch
				{
				}
			}
		}

		internal static void Maintain()
		{
			lock (Locker)
			{
				try
				{
					uint num = 0u;
					int num2 = 0;
					while (num2 < Cookies.Count)
					{
						Cookie cookie = Cookies[num2];
						if (!cookie.WillExpireInTheFuture() || cookie.LastAccess + AccessThreshold < DateTime.UtcNow)
						{
							Cookies.RemoveAt(num2);
							continue;
						}
						if (!cookie.IsSession)
						{
							num += cookie.GuessSize();
						}
						num2++;
					}
					if (num > HTTPManager.CookieJarSize)
					{
						Cookies.Sort();
						while (num > HTTPManager.CookieJarSize && Cookies.Count > 0)
						{
							Cookie cookie2 = Cookies[0];
							Cookies.RemoveAt(0);
							num -= cookie2.GuessSize();
						}
					}
				}
				catch
				{
				}
			}
		}

		internal static void Persist()
		{
			if (!IsSavingSupported)
			{
				return;
			}
			lock (Locker)
			{
				if (!Loaded)
				{
					return;
				}
				try
				{
					Maintain();
					if (!Directory.Exists(CookieFolder))
					{
						Directory.CreateDirectory(CookieFolder);
					}
					using FileStream output = new FileStream(LibraryPath, FileMode.Create);
					using BinaryWriter binaryWriter = new BinaryWriter(output);
					binaryWriter.Write(1);
					int num = 0;
					foreach (Cookie cookie in Cookies)
					{
						if (!cookie.IsSession)
						{
							num++;
						}
					}
					binaryWriter.Write(num);
					foreach (Cookie cookie2 in Cookies)
					{
						if (!cookie2.IsSession)
						{
							cookie2.SaveTo(binaryWriter);
						}
					}
				}
				catch
				{
				}
			}
		}

		internal static void Load()
		{
			if (!IsSavingSupported)
			{
				return;
			}
			lock (Locker)
			{
				if (Loaded)
				{
					return;
				}
				SetupFolder();
				try
				{
					Cookies.Clear();
					if (!Directory.Exists(CookieFolder))
					{
						Directory.CreateDirectory(CookieFolder);
					}
					if (!File.Exists(LibraryPath))
					{
						return;
					}
					using FileStream input = new FileStream(LibraryPath, FileMode.Open);
					using BinaryReader binaryReader = new BinaryReader(input);
					binaryReader.ReadInt32();
					int num = binaryReader.ReadInt32();
					for (int i = 0; i < num; i++)
					{
						Cookie cookie = new Cookie();
						cookie.LoadFrom(binaryReader);
						if (cookie.WillExpireInTheFuture())
						{
							Cookies.Add(cookie);
						}
					}
				}
				catch
				{
					Cookies.Clear();
				}
				finally
				{
					Loaded = true;
				}
			}
		}

		public static List<Cookie> Get(Uri uri)
		{
			lock (Locker)
			{
				Load();
				List<Cookie> list = null;
				for (int i = 0; i < Cookies.Count; i++)
				{
					Cookie cookie = Cookies[i];
					if (cookie.WillExpireInTheFuture() && uri.Host.IndexOf(cookie.Domain) != -1 && uri.AbsolutePath.StartsWith(cookie.Path))
					{
						if (list == null)
						{
							list = new List<Cookie>();
						}
						list.Add(cookie);
					}
				}
				return list;
			}
		}

		public static void Set(Uri uri, Cookie cookie)
		{
			Set(cookie);
		}

		public static void Set(Cookie cookie)
		{
			lock (Locker)
			{
				Load();
				Find(cookie, out var idx);
				if (idx >= 0)
				{
					Cookies[idx] = cookie;
				}
				else
				{
					Cookies.Add(cookie);
				}
			}
		}

		public static List<Cookie> GetAll()
		{
			lock (Locker)
			{
				Load();
				return Cookies;
			}
		}

		public static void Clear()
		{
			lock (Locker)
			{
				Load();
				Cookies.Clear();
			}
		}

		public static void Clear(TimeSpan olderThan)
		{
			lock (Locker)
			{
				Load();
				int num = 0;
				while (num < Cookies.Count)
				{
					Cookie cookie = Cookies[num];
					if (!cookie.WillExpireInTheFuture() || cookie.Date + olderThan < DateTime.UtcNow)
					{
						Cookies.RemoveAt(num);
					}
					else
					{
						num++;
					}
				}
			}
		}

		public static void Clear(string domain)
		{
			lock (Locker)
			{
				Load();
				int num = 0;
				while (num < Cookies.Count)
				{
					Cookie cookie = Cookies[num];
					if (!cookie.WillExpireInTheFuture() || cookie.Domain.IndexOf(domain) != -1)
					{
						Cookies.RemoveAt(num);
					}
					else
					{
						num++;
					}
				}
			}
		}

		public static void Remove(Uri uri, string name)
		{
			lock (Locker)
			{
				Load();
				int num = 0;
				while (num < Cookies.Count)
				{
					Cookie cookie = Cookies[num];
					if (cookie.Name.Equals(name, StringComparison.OrdinalIgnoreCase) && uri.Host.IndexOf(cookie.Domain) != -1)
					{
						Cookies.RemoveAt(num);
					}
					else
					{
						num++;
					}
				}
			}
		}

		private static Cookie Find(Cookie cookie, out int idx)
		{
			for (int i = 0; i < Cookies.Count; i++)
			{
				Cookie cookie2 = Cookies[i];
				if (cookie2.Equals(cookie))
				{
					idx = i;
					return cookie2;
				}
			}
			idx = -1;
			return null;
		}
	}
}
namespace BestHTTP.Decompression.Crc
{
	internal class CRC32
	{
		private uint dwPolynomial;

		private long _TotalBytesRead;

		private bool reverseBits;

		private uint[] crc32Table;

		private const int BUFFER_SIZE = 8192;

		private uint _register = uint.MaxValue;

		public long TotalBytesRead => _TotalBytesRead;

		public int Crc32Result => (int)(~_register);

		public CRC32()
			: this(reverseBits: false)
		{
		}

		public CRC32(bool reverseBits)
			: this(-306674912, reverseBits)
		{
		}

		public CRC32(int polynomial, bool reverseBits)
		{
			this.reverseBits = reverseBits;
			dwPolynomial = (uint)polynomial;
			GenerateLookupTable();
		}

		public int GetCrc32(Stream input)
		{
			return GetCrc32AndCopy(input, null);
		}

		public int GetCrc32AndCopy(Stream input, Stream output)
		{
			if (input == null)
			{
				throw new Exception("The input stream must not be null.");
			}
			byte[] array = new byte[8192];
			int count = 8192;
			_TotalBytesRead = 0L;
			int num = input.Read(array, 0, count);
			output?.Write(array, 0, num);
			_TotalBytesRead += num;
			while (num > 0)
			{
				SlurpBlock(array, 0, num);
				num = input.Read(array, 0, count);
				output?.Write(array, 0, num);
				_TotalBytesRead += num;
			}
			return (int)(~_register);
		}

		public int ComputeCrc32(int W, byte B)
		{
			return _InternalComputeCrc32((uint)W, B);
		}

		internal int _InternalComputeCrc32(uint W, byte B)
		{
