	public sealed class WriteOnlyBufferedStream : Stream
	{
		private int _position;

		private byte[] buffer;

		private Stream stream;

		public override bool CanRead => false;

		public override bool CanSeek => false;

		public override bool CanWrite => true;

		public override long Length => buffer.Length;

		public override long Position
		{
			get
			{
				return _position;
			}
			set
			{
				throw new NotImplementedException("Position set");
			}
		}

		public WriteOnlyBufferedStream(Stream stream, int bufferSize)
		{
			this.stream = stream;
			buffer = new byte[bufferSize];
			_position = 0;
		}

		public override void Flush()
		{
			if (_position > 0)
			{
				if (HTTPManager.Logger.Level == Loglevels.All)
				{
					HTTPManager.Logger.Information("BufferStream", $"Flushing {_position:N0} bytes");
				}
				stream.Write(buffer, 0, _position);
				_position = 0;
			}
		}

		public override void Write(byte[] bufferFrom, int offset, int count)
		{
			while (count > 0)
			{
				int num = Math.Min(count, buffer.Length - _position);
				Array.Copy(bufferFrom, offset, buffer, _position, num);
				_position += num;
				offset += num;
				count -= num;
				if (_position == buffer.Length)
				{
					Flush();
				}
			}
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			return 0;
		}

		public override long Seek(long offset, SeekOrigin origin)
		{
			return 0L;
		}

		public override void SetLength(long value)
		{
		}
	}
	public sealed class WWWAuthenticateHeaderParser : KeyValuePairList
	{
		public WWWAuthenticateHeaderParser(string headerValue)
		{
			base.Values = ParseQuotedHeader(headerValue);
		}

		private List<HeaderValue> ParseQuotedHeader(string str)
		{
			List<HeaderValue> list = new List<HeaderValue>();
			if (str != null)
			{
				int pos = 0;
				string key = str.Read(ref pos, (char ch) => !char.IsWhiteSpace(ch) && !char.IsControl(ch)).TrimAndLower();
				list.Add(new HeaderValue(key));
				while (pos < str.Length)
				{
					string key2 = str.Read(ref pos, '=').TrimAndLower();
					HeaderValue headerValue = new HeaderValue(key2);
					str.SkipWhiteSpace(ref pos);
					headerValue.Value = str.ReadPossibleQuotedText(ref pos);
					list.Add(headerValue);
				}
			}
			return list;
		}
	}
