	public sealed class HTTPMultiPartForm : HTTPFormBase
	{
		private string Boundary;

		private byte[] CachedData;

		public HTTPMultiPartForm()
		{
			Boundary = "BestHTTP_HTTPMultiPartForm_" + GetHashCode().ToString("X");
		}

		public override void PrepareRequest(HTTPRequest request)
		{
			request.SetHeader("Content-Type", "multipart/form-data; boundary=\"" + Boundary + "\"");
		}

		public override byte[] GetData()
		{
			if (CachedData != null)
			{
				return CachedData;
			}
			using MemoryStream memoryStream = new MemoryStream();
			for (int i = 0; i < base.Fields.Count; i++)
			{
				HTTPFieldData hTTPFieldData = base.Fields[i];
				memoryStream.WriteLine("--" + Boundary);
				memoryStream.WriteLine("Content-Disposition: form-data; name=\"" + hTTPFieldData.Name + "\"" + (string.IsNullOrEmpty(hTTPFieldData.FileName) ? string.Empty : ("; filename=\"" + hTTPFieldData.FileName + "\"")));
				if (!string.IsNullOrEmpty(hTTPFieldData.MimeType))
				{
					memoryStream.WriteLine("Content-Type: " + hTTPFieldData.MimeType);
				}
				memoryStream.WriteLine("Content-Length: " + hTTPFieldData.Payload.Length);
				memoryStream.WriteLine();
				memoryStream.Write(hTTPFieldData.Payload, 0, hTTPFieldData.Payload.Length);
				memoryStream.Write(HTTPRequest.EOL, 0, HTTPRequest.EOL.Length);
			}
			memoryStream.WriteLine("--" + Boundary + "--");
			base.IsChanged = false;
			return CachedData = memoryStream.ToArray();
		}
	}
	public sealed class HTTPUrlEncodedForm : HTTPFormBase
	{
		private const int EscapeTreshold = 256;

		private byte[] CachedData;

		public override void PrepareRequest(HTTPRequest request)
		{
			request.SetHeader("Content-Type", "application/x-www-form-urlencoded");
		}

		public override byte[] GetData()
		{
			if (CachedData != null && !base.IsChanged)
			{
				return CachedData;
			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < base.Fields.Count; i++)
			{
				HTTPFieldData hTTPFieldData = base.Fields[i];
				if (i > 0)
				{
					stringBuilder.Append("&");
				}
				stringBuilder.Append(EscapeString(hTTPFieldData.Name));
				stringBuilder.Append("=");
				if (!string.IsNullOrEmpty(hTTPFieldData.Text) || hTTPFieldData.Binary == null)
				{
					stringBuilder.Append(EscapeString(hTTPFieldData.Text));
				}
				else
				{
					stringBuilder.Append(EscapeString(Encoding.UTF8.GetString(hTTPFieldData.Binary, 0, hTTPFieldData.Binary.Length)));
				}
			}
			base.IsChanged = false;
			return CachedData = Encoding.UTF8.GetBytes(stringBuilder.ToString());
		}

		public static string EscapeString(string originalString)
		{
			if (originalString.Length < 256)
			{
				return Uri.EscapeDataString(originalString);
			}
			int num = originalString.Length / 256;
			StringBuilder stringBuilder = new StringBuilder(num);
			for (int i = 0; i <= num; i++)
			{
				stringBuilder.Append((i >= num) ? Uri.EscapeDataString(originalString.Substring(256 * i)) : Uri.EscapeDataString(originalString.Substring(256 * i, 256)));
			}
			return stringBuilder.ToString();
		}
	}
	public sealed class RawJsonForm : HTTPFormBase
	{
		private byte[] CachedData;

		public override void PrepareRequest(HTTPRequest request)
		{
			request.SetHeader("Content-Type", "application/json");
		}

		public override byte[] GetData()
		{
			if (CachedData != null && !base.IsChanged)
			{
				return CachedData;
			}
			Dictionary<string, string> json = base.Fields.ToDictionary((HTTPFieldData x) => x.Name, (HTTPFieldData x) => x.Text);
			string s = BestHTTP.JSON.Json.Encode(json);
			base.IsChanged = false;
			return CachedData = Encoding.UTF8.GetBytes(s);
		}
	}
	public sealed class UnityForm : HTTPFormBase
	{
		public WWWForm Form { get; set; }

		public UnityForm()
		{
		}

		public UnityForm(WWWForm form)
		{
			Form = form;
		}

		public override void CopyFrom(HTTPFormBase fields)
		{
			base.Fields = fields.Fields;
			base.IsChanged = true;
			if (Form != null)
			{
				return;
			}
			Form = new WWWForm();
			if (base.Fields == null)
			{
				return;
			}
			for (int i = 0; i < base.Fields.Count; i++)
			{
				HTTPFieldData hTTPFieldData = base.Fields[i];
				if (string.IsNullOrEmpty(hTTPFieldData.Text) && hTTPFieldData.Binary != null)
				{
					Form.AddBinaryData(hTTPFieldData.Name, hTTPFieldData.Binary, hTTPFieldData.FileName, hTTPFieldData.MimeType);
				}
				else
				{
					Form.AddField(hTTPFieldData.Name, hTTPFieldData.Text, hTTPFieldData.Encoding);
				}
			}
		}

		public override void PrepareRequest(HTTPRequest request)
		{
			if (Form.headers.ContainsKey("Content-Type"))
			{
				request.SetHeader("Content-Type", Form.headers["Content-Type"]);
			}
			else
			{
				request.SetHeader("Content-Type", "application/x-www-form-urlencoded");
			}
		}

		public override byte[] GetData()
		{
			return Form.data;
		}
	}
