		protected int ReadChunkLength(Stream stream)
		{
			string text = ReadTo(stream, 10);
			string[] array = text.Split(';');
			string text2 = array[0];
			if (int.TryParse(text2, NumberStyles.AllowHexSpecifier, null, out var result))
			{
				return result;
			}
			throw new Exception($"Can't parse '{text2}' as a hex number!");
		}

		protected void ReadChunked(Stream stream)
		{
			BeginReceiveStreamFragments();
			string firstHeaderValue = GetFirstHeaderValue("Content-Length");
			bool flag = !string.IsNullOrEmpty(firstHeaderValue);
			int result = 0;
			if (flag)
			{
				flag = int.TryParse(firstHeaderValue, out result);
			}
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				VerboseLogging($"ReadChunked - hasContentLengthHeader: {flag.ToString()}, contentLengthHeader: {firstHeaderValue} realLength: {result:N0}");
			}
			using MemoryStream memoryStream = new MemoryStream();
			int num = ReadChunkLength(stream);
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				VerboseLogging($"chunkLength: {num:N0}");
			}
			byte[] array = new byte[num];
			int num2 = 0;
			baseRequest.DownloadLength = ((!flag) ? num : result);
			baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
			string text = ((!IsFromCache) ? GetFirstHeaderValue("content-encoding") : null);
			bool flag2 = !string.IsNullOrEmpty(text) && text == "gzip";
			while (num != 0)
			{
				if (array.Length < num)
				{
					Array.Resize(ref array, num);
				}
				int num3 = 0;
				do
				{
					int num4 = stream.Read(array, num3, num - num3);
					if (num4 <= 0)
					{
						throw ExceptionHelper.ServerClosedTCPStream();
					}
					num3 += num4;
					baseRequest.Downloaded += num4;
					baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
				}
				while (num3 < num);
				if (baseRequest.UseStreaming)
				{
					WaitWhileHasFragments();
					if (flag2)
					{
						byte[] array2 = Decompress(array, 0, num3);
						if (array2 != null)
						{
							FeedStreamFragment(array2, 0, array2.Length);
						}
					}
					else
					{
						FeedStreamFragment(array, 0, num3);
					}
				}
				else
				{
					memoryStream.Write(array, 0, num3);
				}
				ReadTo(stream, 10);
				num2 += num3;
				num = ReadChunkLength(stream);
				if (HTTPManager.Logger.Level == Loglevels.All)
				{
					VerboseLogging($"chunkLength: {num:N0}");
				}
				if (!flag)
				{
					baseRequest.DownloadLength += num;
				}
				baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
			}
			if (baseRequest.UseStreaming)
			{
				if (flag2)
				{
					byte[] array3 = Decompress(null, 0, 0, forceDecompress: true);
					if (array3 != null)
					{
						FeedStreamFragment(array3, 0, array3.Length);
					}
				}
				FlushRemainingFragmentBuffer();
			}
			ReadHeaders(stream);
			if (!baseRequest.UseStreaming)
			{
				Data = DecodeStream(memoryStream);
			}
		}

		internal void ReadRaw(Stream stream, long contentLength)
		{
			BeginReceiveStreamFragments();
			baseRequest.DownloadLength = contentLength;
			baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				VerboseLogging($"ReadRaw - contentLength: {contentLength:N0}");
			}
			string text = ((!IsFromCache) ? GetFirstHeaderValue("content-encoding") : null);
			bool flag = !string.IsNullOrEmpty(text) && text == "gzip";
			if (!baseRequest.UseStreaming && contentLength > 2147483646)
			{
				throw new OverflowException("You have to use STREAMING to download files bigger than 2GB!");
			}
			using MemoryStream memoryStream = new MemoryStream((int)((!baseRequest.UseStreaming) ? contentLength : 0));
			byte[] array = new byte[Math.Max(baseRequest.StreamFragmentSize, 4096)];
			int num = 0;
			while (contentLength > 0)
			{
				num = 0;
				do
				{
					int val = (int)Math.Min(2147483646u, (uint)contentLength);
					int num2 = stream.Read(array, num, Math.Min(val, array.Length - num));
					if (num2 <= 0)
					{
						throw ExceptionHelper.ServerClosedTCPStream();
					}
					num += num2;
					contentLength -= num2;
					baseRequest.Downloaded += num2;
					baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
				}
				while (num < array.Length && contentLength > 0);
				if (baseRequest.UseStreaming)
				{
					WaitWhileHasFragments();
					if (flag)
					{
						byte[] array2 = Decompress(array, 0, num);
						if (array2 != null)
						{
							FeedStreamFragment(array2, 0, array2.Length);
						}
					}
					else
					{
						FeedStreamFragment(array, 0, num);
					}
				}
				else
				{
					memoryStream.Write(array, 0, num);
				}
			}
			if (baseRequest.UseStreaming)
			{
				if (flag)
				{
					byte[] array3 = Decompress(null, 0, 0, forceDecompress: true);
					if (array3 != null)
					{
						FeedStreamFragment(array3, 0, array3.Length);
					}
				}
				FlushRemainingFragmentBuffer();
			}
			if (!baseRequest.UseStreaming)
			{
				Data = DecodeStream(memoryStream);
			}
		}

		protected void ReadUnknownSize(Stream stream)
		{
			string text = ((!IsFromCache) ? GetFirstHeaderValue("content-encoding") : null);
			bool flag = !string.IsNullOrEmpty(text) && text == "gzip";
			using MemoryStream memoryStream = new MemoryStream();
			byte[] array = new byte[Math.Max(baseRequest.StreamFragmentSize, 4096)];
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				VerboseLogging($"ReadUnknownSize - buffer size: {array.Length:N0}");
			}
			int num = 0;
			int num2 = 0;
			do
			{
				num = 0;
				do
				{
					num2 = 0;
					if (stream is NetworkStream networkStream && baseRequest.EnableSafeReadOnUnknownContentLength)
					{
						for (int i = num; i < array.Length; i++)
						{
							if (!networkStream.DataAvailable)
							{
								break;
							}
							int num3 = stream.ReadByte();
							if (num3 >= 0)
							{
								array[i] = (byte)num3;
								num2++;
								continue;
							}
							break;
						}
					}
					else
					{
						num2 = stream.Read(array, num, array.Length - num);
					}
					num += num2;
					baseRequest.Downloaded += num2;
					baseRequest.DownloadLength = baseRequest.Downloaded;
					baseRequest.DownloadProgressChanged = IsSuccess || IsFromCache;
				}
				while (num < array.Length && num2 > 0);
				if (baseRequest.UseStreaming)
				{
					WaitWhileHasFragments();
					if (flag)
					{
						byte[] array2 = Decompress(array, 0, num);
						if (array2 != null)
						{
							FeedStreamFragment(array2, 0, array2.Length);
						}
					}
					else
					{
						FeedStreamFragment(array, 0, num);
					}
				}
				else
				{
					memoryStream.Write(array, 0, num);
				}
			}
			while (num2 > 0);
			if (baseRequest.UseStreaming)
			{
				if (flag)
				{
					byte[] array3 = Decompress(null, 0, 0, forceDecompress: true);
					if (array3 != null)
					{
						FeedStreamFragment(array3, 0, array3.Length);
					}
				}
				FlushRemainingFragmentBuffer();
			}
			if (!baseRequest.UseStreaming)
			{
				Data = DecodeStream(memoryStream);
			}
		}

		protected byte[] DecodeStream(MemoryStream streamToDecode)
		{
			streamToDecode.Seek(0L, SeekOrigin.Begin);
			List<string> list = ((!IsFromCache) ? GetHeaderValues("content-encoding") : null);
			Stream stream = null;
			if (list == null)
			{
				return streamToDecode.ToArray();
			}
			switch (list[0])
			{
			case "gzip":
				stream = new GZipStream(streamToDecode, CompressionMode.Decompress);
				break;
			case "deflate":
				stream = new DeflateStream(streamToDecode, CompressionMode.Decompress);
				break;
			default:
				return streamToDecode.ToArray();
			}
			using MemoryStream memoryStream = new MemoryStream((int)streamToDecode.Length);
			byte[] array = new byte[1024];
			int num = 0;
			while ((num = stream.Read(array, 0, array.Length)) > 0)
			{
				memoryStream.Write(array, 0, num);
			}
			return memoryStream.ToArray();
		}

		private byte[] Decompress(byte[] data, int offset, int count, bool forceDecompress = false)
		{
			if (decompressorInputStream == null)
			{
				decompressorInputStream = new MemoryStream(count);
			}
			if (data != null)
			{
				decompressorInputStream.Write(data, offset, count);
			}
			if (!forceDecompress && decompressorInputStream.Length < 256)
			{
				return null;
			}
			decompressorInputStream.Position = 0L;
			if (decompressorGZipStream == null)
			{
				decompressorGZipStream = new GZipStream(decompressorInputStream, CompressionMode.Decompress, CompressionLevel.Default, leaveOpen: true);
				decompressorGZipStream.FlushMode = FlushType.Sync;
			}
			if (decompressorOutputStream == null)
			{
				decompressorOutputStream = new MemoryStream();
			}
			decompressorOutputStream.SetLength(0L);
			if (copyBuffer == null)
			{
				copyBuffer = new byte[1024];
			}
			int count2;
			while ((count2 = decompressorGZipStream.Read(copyBuffer, 0, copyBuffer.Length)) != 0)
			{
				decompressorOutputStream.Write(copyBuffer, 0, count2);
			}
			decompressorGZipStream.SetLength(0L);
			return decompressorOutputStream.ToArray();
		}

		protected void BeginReceiveStreamFragments()
		{
			if (!baseRequest.DisableCache && baseRequest.UseStreaming && !IsFromCache && HTTPCacheService.IsCacheble(baseRequest.CurrentUri, baseRequest.MethodType, this))
			{
				cacheStream = HTTPCacheService.PrepareStreamed(baseRequest.CurrentUri, this);
			}
			allFragmentSize = 0;
		}

		protected void FeedStreamFragment(byte[] buffer, int pos, int length)
		{
			if (buffer == null || length == 0)
			{
				return;
			}
			if (fragmentBuffer == null)
			{
				fragmentBuffer = new byte[baseRequest.StreamFragmentSize];
				fragmentBufferDataLength = 0;
			}
			if (fragmentBufferDataLength + length <= baseRequest.StreamFragmentSize)
			{
				Array.Copy(buffer, pos, fragmentBuffer, fragmentBufferDataLength, length);
				fragmentBufferDataLength += length;
				if (fragmentBufferDataLength == baseRequest.StreamFragmentSize)
				{
					AddStreamedFragment(fragmentBuffer);
					fragmentBuffer = null;
					fragmentBufferDataLength = 0;
				}
			}
			else
			{
				int num = baseRequest.StreamFragmentSize - fragmentBufferDataLength;
				FeedStreamFragment(buffer, pos, num);
				FeedStreamFragment(buffer, pos + num, length - num);
			}
		}

		protected void FlushRemainingFragmentBuffer()
		{
			if (fragmentBuffer != null)
			{
				Array.Resize(ref fragmentBuffer, fragmentBufferDataLength);
				AddStreamedFragment(fragmentBuffer);
				fragmentBuffer = null;
				fragmentBufferDataLength = 0;
			}
			if (cacheStream != null)
			{
				cacheStream.Dispose();
				cacheStream = null;
				HTTPCacheService.SetBodyLength(baseRequest.CurrentUri, allFragmentSize);
			}
		}

		protected void AddStreamedFragment(byte[] buffer)
		{
			lock (SyncRoot)
			{
				if (!IsCacheOnly)
				{
					if (streamedFragments == null)
					{
						streamedFragments = new List<byte[]>();
					}
					streamedFragments.Add(buffer);
				}
				if (HTTPManager.Logger.Level == Loglevels.All && buffer != null && streamedFragments != null)
				{
					VerboseLogging($"AddStreamedFragment buffer length: {buffer.Length:N0} streamedFragments: {streamedFragments.Count:N0}");
				}
				if (cacheStream != null)
				{
					cacheStream.Write(buffer, 0, buffer.Length);
					allFragmentSize += buffer.Length;
				}
			}
		}

		protected void WaitWhileHasFragments()
		{
			VerboseLogging("WaitWhileHasFragments");
			while (baseRequest.UseStreaming && HasFragmentsInQueue())
			{
				Thread.Sleep(16);
			}
		}

		private bool HasFragmentsInQueue()
		{
			lock (SyncRoot)
			{
				bool flag = streamedFragments != null && streamedFragments.Count >= baseRequest.MaxFragmentQueueLength;
				if (flag && HTTPManager.Logger.Level == Loglevels.All)
				{
					VerboseLogging($"HasFragmentsInQueue - {streamedFragments.Count} / {baseRequest.MaxFragmentQueueLength}");
				}
				return flag;
			}
		}

		public List<byte[]> GetStreamedFragments()
		{
			lock (SyncRoot)
			{
				if (streamedFragments == null || streamedFragments.Count == 0)
				{
					if (HTTPManager.Logger.Level == Loglevels.All)
					{
						VerboseLogging("GetStreamedFragments - no fragments, returning with null");
					}
					return null;
				}
				List<byte[]> list = new List<byte[]>(streamedFragments);
				streamedFragments.Clear();
				if (HTTPManager.Logger.Level == Loglevels.All)
				{
					VerboseLogging($"GetStreamedFragments - returning with {list.Count.ToString():N0} fragments");
				}
				return list;
			}
		}

		internal bool HasStreamedFragments()
		{
			lock (SyncRoot)
			{
				return streamedFragments != null && streamedFragments.Count >= baseRequest.MaxFragmentQueueLength;
			}
		}

		internal void FinishStreaming()
		{
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				VerboseLogging("FinishStreaming");
			}
			IsStreamingFinished = true;
			Dispose();
		}

		private void VerboseLogging(string str)
		{
			if (HTTPManager.Logger.Level == Loglevels.All)
			{
				HTTPManager.Logger.Verbose("HTTPResponse", "'" + baseRequest.CurrentUri.ToString() + "' - " + str);
			}
		}

		public void Dispose()
		{
			if (cacheStream != null)
			{
				cacheStream.Dispose();
				cacheStream = null;
			}
		}
	}
	[ExecuteInEditMode]
	public sealed class HTTPUpdateDelegator : UnityEngine.MonoBehaviour
	{
		public static Func<bool> OnBeforeApplicationQuit;

		public static Action<bool> OnApplicationForegroundStateChanged;

		private static bool IsSetupCalled;

		public static HTTPUpdateDelegator Instance { get; private set; }

		public static bool IsCreated { get; private set; }

		public static bool IsThreaded { get; set; }

		public static bool IsThreadRunning { get; private set; }

		public static int ThreadFrequencyInMS { get; set; }

		static HTTPUpdateDelegator()
		{
			ThreadFrequencyInMS = 100;
		}

		public static void CheckInstance()
		{
			try
			{
				if (!IsCreated)
				{
					GameObject gameObject = GameObject.Find("HTTP Update Delegator");
					if (gameObject != null)
					{
						Instance = gameObject.GetComponent<HTTPUpdateDelegator>();
					}
					if (Instance == null)
					{
						gameObject = new GameObject("HTTP Update Delegator");
						gameObject.hideFlags = HideFlags.DontSave;
						Instance = gameObject.AddComponent<HTTPUpdateDelegator>();
					}
					IsCreated = true;
					HTTPManager.Logger.Information("HTTPUpdateDelegator", "Instance Created!");
				}
			}
			catch
			{
				HTTPManager.Logger.Error("HTTPUpdateDelegator", "Please call the BestHTTP.HTTPManager.Setup() from one of Unity's event(eg. awake, start) before you send any request!");
			}
		}

		private void Setup()
		{
			HTTPCacheService.SetupCacheFolder();
			CookieJar.SetupFolder();
			CookieJar.Load();
			if (IsThreaded)
			{
				ThreadPool.QueueUserWorkItem(ThreadFunc);
			}
			IsSetupCalled = true;
			if (!UnityEngine.Application.isEditor || UnityEngine.Application.isPlaying)
			{
				UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
			}
			HTTPManager.Logger.Information("HTTPUpdateDelegator", "Setup done!");
		}

		private void ThreadFunc(object obj)
		{
			HTTPManager.Logger.Information("HTTPUpdateDelegator", "Update Thread Started");
			try
			{
				IsThreadRunning = true;
				while (IsThreadRunning)
				{
					HTTPManager.OnUpdate();
					Thread.Sleep(ThreadFrequencyInMS);
				}
			}
			finally
			{
				HTTPManager.Logger.Information("HTTPUpdateDelegator", "Update Thread Ended");
			}
		}

		private void Update()
		{
			if (!IsSetupCalled)
			{
				IsSetupCalled = true;
				Setup();
			}
			if (!IsThreaded)
			{
				HTTPManager.OnUpdate();
			}
		}

		private void OnDisable()
		{
			HTTPManager.Logger.Information("HTTPUpdateDelegator", "OnDisable Called!");
			OnApplicationQuit();
		}

		private void OnApplicationPause(bool isPaused)
		{
			if (OnApplicationForegroundStateChanged != null)
			{
				OnApplicationForegroundStateChanged(isPaused);
			}
		}

		private void OnApplicationQuit()
		{
			HTTPManager.Logger.Information("HTTPUpdateDelegator", "OnApplicationQuit Called!");
			if (OnBeforeApplicationQuit != null)
			{
				try
				{
					if (!OnBeforeApplicationQuit())
					{
						HTTPManager.Logger.Information("HTTPUpdateDelegator", "OnBeforeApplicationQuit call returned false, postponing plugin shutdown.");
						return;
					}
				}
				catch (Exception ex)
				{
					HTTPManager.Logger.Exception("HTTPUpdateDelegator", string.Empty, ex);
				}
			}
			IsThreadRunning = false;
			if (IsCreated)
			{
				IsCreated = false;
				HTTPManager.OnQuit();
			}
		}
	}
}
namespace BestHTTP.JSON
{
	public class Json
	{
		private const int TOKEN_NONE = 0;

		private const int TOKEN_CURLY_OPEN = 1;

		private const int TOKEN_CURLY_CLOSE = 2;

		private const int TOKEN_SQUARED_OPEN = 3;

		private const int TOKEN_SQUARED_CLOSE = 4;

		private const int TOKEN_COLON = 5;

		private const int TOKEN_COMMA = 6;

		private const int TOKEN_STRING = 7;

		private const int TOKEN_NUMBER = 8;

		private const int TOKEN_TRUE = 9;

		private const int TOKEN_FALSE = 10;

		private const int TOKEN_NULL = 11;

		private const int BUILDER_CAPACITY = 2000;

		public static object Decode(string json)
		{
			bool success = true;
			return Decode(json, ref success);
		}

		public static object Decode(string json, ref bool success)
		{
			success = true;
			if (json != null)
			{
				char[] json2 = json.ToCharArray();
				int index = 0;
				return ParseValue(json2, ref index, ref success);
			}
			return null;
		}

		public static string Encode(object json)
		{
			StringBuilder stringBuilder = new StringBuilder(2000);
			return (!SerializeValue(json, stringBuilder)) ? null : stringBuilder.ToString();
		}

		protected static Dictionary<string, object> ParseObject(char[] json, ref int index, ref bool success)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			NextToken(json, ref index);
			bool flag = false;
			while (!flag)
			{
				switch (LookAhead(json, index))
				{
				case 0:
					success = false;
					return null;
				case 6:
					NextToken(json, ref index);
					continue;
				case 2:
					NextToken(json, ref index);
					return dictionary;
				}
				string key = ParseString(json, ref index, ref success);
				if (!success)
				{
					success = false;
					return null;
				}
				int num = NextToken(json, ref index);
				if (num != 5)
				{
					success = false;
					return null;
				}
				object value = ParseValue(json, ref index, ref success);
				if (!success)
				{
					success = false;
					return null;
				}
				dictionary[key] = value;
			}
			return dictionary;
		}

		protected static List<object> ParseArray(char[] json, ref int index, ref bool success)
		{
			List<object> list = new List<object>();
			NextToken(json, ref index);
			bool flag = false;
			while (!flag)
			{
				switch (LookAhead(json, index))
				{
				case 0:
					success = false;
					return null;
				case 6:
					NextToken(json, ref index);
					continue;
				case 4:
					break;
				default:
				{
					object item = ParseValue(json, ref index, ref success);
					if (!success)
					{
						return null;
					}
					list.Add(item);
					continue;
				}
				}
				NextToken(json, ref index);
				break;
			}
			return list;
		}

		protected static object ParseValue(char[] json, ref int index, ref bool success)
		{
			switch (LookAhead(json, index))
			{
			case 7:
				return ParseString(json, ref index, ref success);
			case 8:
				return ParseNumber(json, ref index, ref success);
			case 1:
				return ParseObject(json, ref index, ref success);
			case 3:
				return ParseArray(json, ref index, ref success);
			case 9:
				NextToken(json, ref index);
				return true;
			case 10:
				NextToken(json, ref index);
				return false;
			case 11:
				NextToken(json, ref index);
				return null;
			default:
				success = false;
				return null;
			}
		}

		protected static string ParseString(char[] json, ref int index, ref bool success)
		{
			StringBuilder stringBuilder = new StringBuilder(2000);
			EatWhitespace(json, ref index);
			char c = json[index++];
			bool flag = false;
			while (!flag && index != json.Length)
			{
				c = json[index++];
				switch (c)
				{
				case '"':
					flag = true;
					break;
				case '\\':
				{
					if (index == json.Length)
					{
						break;
					}
					switch (json[index++])
					{
					case '"':
						stringBuilder.Append('"');
						continue;
					case '\\':
						stringBuilder.Append('\\');
						continue;
					case '/':
						stringBuilder.Append('/');
						continue;
					case 'b':
						stringBuilder.Append('\b');
						continue;
					case 'f':
						stringBuilder.Append('\f');
						continue;
					case 'n':
						stringBuilder.Append('\n');
						continue;
					case 'r':
						stringBuilder.Append('\r');
						continue;
					case 't':
						stringBuilder.Append('\t');
						continue;
					case 'u':
						break;
					default:
						continue;
					}
					int num = json.Length - index;
					if (num < 4)
					{
						break;
					}
					if (!(success = uint.TryParse(new string(json, index, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out var result)))
					{
						return string.Empty;
					}
					stringBuilder.Append(char.ConvertFromUtf32((int)result));
					index += 4;
					continue;
				}
				default:
					stringBuilder.Append(c);
					continue;
				}
				break;
			}
			if (!flag)
			{
				success = false;
				return null;
			}
			return stringBuilder.ToString();
		}

		protected static double ParseNumber(char[] json, ref int index, ref bool success)
		{
			EatWhitespace(json, ref index);
			int lastIndexOfNumber = GetLastIndexOfNumber(json, index);
			int length = lastIndexOfNumber - index + 1;
			success = double.TryParse(new string(json, index, length), NumberStyles.Any, CultureInfo.InvariantCulture, out var result);
			index = lastIndexOfNumber + 1;
			return result;
		}

		protected static int GetLastIndexOfNumber(char[] json, int index)
		{
			int i;
			for (i = index; i < json.Length && "0123456789+-.eE".IndexOf(json[i]) != -1; i++)
			{
			}
			return i - 1;
		}

		protected static void EatWhitespace(char[] json, ref int index)
		{
			while (index < json.Length && " \t\n\r".IndexOf(json[index]) != -1)
			{
				index++;
			}
		}

		protected static int LookAhead(char[] json, int index)
		{
			int index2 = index;
			return NextToken(json, ref index2);
		}

		protected static int NextToken(char[] json, ref int index)
		{
			EatWhitespace(json, ref index);
			if (index == json.Length)
			{
				return 0;
			}
			char c = json[index];
			index++;
			switch (c)
			{
			case '{':
				return 1;
			case '}':
				return 2;
			case '[':
				return 3;
			case ']':
				return 4;
			case ',':
				return 6;
			case '"':
				return 7;
			case '-':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				return 8;
			case ':':
				return 5;
			default:
			{
				index--;
				int num = json.Length - index;
				if (num >= 5 && json[index] == 'f' && json[index + 1] == 'a' && json[index + 2] == 'l' && json[index + 3] == 's' && json[index + 4] == 'e')
				{
					index += 5;
					return 10;
				}
				if (num >= 4 && json[index] == 't' && json[index + 1] == 'r' && json[index + 2] == 'u' && json[index + 3] == 'e')
				{
					index += 4;
					return 9;
				}
				if (num >= 4 && json[index] == 'n' && json[index + 1] == 'u' && json[index + 2] == 'l' && json[index + 3] == 'l')
				{
					index += 4;
					return 11;
				}
				return 0;
			}
			}
		}

		protected static bool SerializeValue(object value, StringBuilder builder)
		{
			bool result = true;
			if (value is string)
			{
				result = SerializeString((string)value, builder);
			}
			else if (value is IDictionary)
			{
				result = SerializeObject((IDictionary)value, builder);
			}
			else if (value is IList)
			{
				result = SerializeArray(value as IList, builder);
			}
			else if (value is bool && (bool)value)
			{
				builder.Append("true");
			}
			else if (value is bool && !(bool)value)
			{
				builder.Append("false");
			}
			else if (value is ValueType)
			{
				result = SerializeNumber(Convert.ToDouble(value), builder);
			}
			else if (value == null)
			{
				builder.Append("null");
			}
			else
			{
				result = false;
			}
			return result;
		}

		protected static bool SerializeObject(IDictionary anObject, StringBuilder builder)
		{
			builder.Append("{");
			IDictionaryEnumerator enumerator = anObject.GetEnumerator();
			bool flag = true;
			while (enumerator.MoveNext())
			{
				string aString = enumerator.Key.ToString();
				object value = enumerator.Value;
				if (!flag)
				{
					builder.Append(", ");
				}
				SerializeString(aString, builder);
				builder.Append(":");
				if (!SerializeValue(value, builder))
				{
					return false;
				}
				flag = false;
			}
			builder.Append("}");
			return true;
		}

		protected static bool SerializeArray(IList anArray, StringBuilder builder)
		{
			builder.Append("[");
			bool flag = true;
			for (int i = 0; i < anArray.Count; i++)
			{
				object value = anArray[i];
				if (!flag)
				{
					builder.Append(", ");
				}
				if (!SerializeValue(value, builder))
				{
					return false;
				}
				flag = false;
			}
			builder.Append("]");
			return true;
		}

		protected static bool SerializeString(string aString, StringBuilder builder)
		{
			builder.Append("\"");
			char[] array = aString.ToCharArray();
			foreach (char c in array)
			{
				switch (c)
				{
				case '"':
					builder.Append("\\\"");
					continue;
				case '\\':
					builder.Append("\\\\");
					continue;
				case '\b':
					builder.Append("\\b");
					continue;
				case '\f':
					builder.Append("\\f");
					continue;
				case '\n':
					builder.Append("\\n");
					continue;
				case '\r':
					builder.Append("\\r");
					continue;
				case '\t':
					builder.Append("\\t");
					continue;
				}
				int num = Convert.ToInt32(c);
				if (num >= 32 && num <= 126)
				{
					builder.Append(c);
				}
				else
				{
					builder.Append("\\u" + Convert.ToString(num, 16).PadLeft(4, '0'));
				}
			}
			builder.Append("\"");
			return true;
		}

		protected static bool SerializeNumber(double number, StringBuilder builder)
		{
			builder.Append(Convert.ToString(number, CultureInfo.InvariantCulture));
			return true;
		}
	}
}
namespace BestHTTP.Logger
{
	public class DefaultLogger : ILogger
	{
		public Loglevels Level { get; set; }

		public string FormatVerbose { get; set; }

		public string FormatInfo { get; set; }

		public string FormatWarn { get; set; }

		public string FormatErr { get; set; }

		public string FormatEx { get; set; }

		public DefaultLogger()
		{
			FormatVerbose = "[{0}] D [{1}]: {2}";
			FormatInfo = "[{0}] I [{1}]: {2}";
			FormatWarn = "[{0}] W [{1}]: {2}";
			FormatErr = "[{0}] Err [{1}]: {2}";
			FormatEx = "[{0}] Ex [{1}]: {2} - Message: {3}  StackTrace: {4}";
			Level = ((!UnityEngine.Debug.isDebugBuild) ? Loglevels.Error : Loglevels.Warning);
		}

		public void Verbose(string division, string verb)
		{
			if ((int)Level <= 0)
			{
				try
				{
					UnityEngine.Debug.Log(string.Format(FormatVerbose, GetFormattedTime(), division, verb));
				}
				catch
				{
				}
			}
		}

		public void Information(string division, string info)
		{
			if ((int)Level <= 1)
			{
				try
				{
					UnityEngine.Debug.Log(string.Format(FormatInfo, GetFormattedTime(), division, info));
				}
				catch
				{
				}
			}
		}

		public void Warning(string division, string warn)
		{
			if ((int)Level <= 2)
			{
				try
				{
					UnityEngine.Debug.LogWarning(string.Format(FormatWarn, GetFormattedTime(), division, warn));
				}
				catch
				{
				}
			}
		}

		public void Error(string division, string err)
		{
			if ((int)Level <= 3)
			{
				try
				{
					UnityEngine.Debug.LogError(string.Format(FormatErr, GetFormattedTime(), division, err));
				}
				catch
				{
				}
			}
		}

		public void Exception(string division, string msg, Exception ex)
		{
			if ((int)Level > 4)
			{
				return;
			}
			try
			{
				string empty = string.Empty;
				if (ex == null)
				{
					empty = "null";
				}
				else
				{
					StringBuilder stringBuilder = new StringBuilder();
					Exception ex2 = ex;
					int num = 1;
					while (ex2 != null)
					{
						stringBuilder.AppendFormat("{0}: {1} {2}", num++.ToString(), ex2.Message, ex2.StackTrace);
						ex2 = ex2.InnerException;
						if (ex2 != null)
						{
							stringBuilder.AppendLine();
						}
					}
					empty = stringBuilder.ToString();
				}
				UnityEngine.Debug.LogError(string.Format(FormatEx, GetFormattedTime(), division, msg, empty, (ex == null) ? "null" : ex.StackTrace));
			}
			catch
			{
			}
		}

		private string GetFormattedTime()
		{
			return DateTime.Now.Ticks.ToString();
		}
	}
	public enum Loglevels : byte
	{
		All,
		Information,
		Warning,
		Error,
		Exception,
		None
	}
	public interface ILogger
	{
		Loglevels Level { get; set; }

		string FormatVerbose { get; set; }

		string FormatInfo { get; set; }

		string FormatWarn { get; set; }

		string FormatErr { get; set; }

		string FormatEx { get; set; }

		void Verbose(string division, string verb);

		void Information(string division, string info);

		void Warning(string division, string warn);

		void Error(string division, string err);

		void Exception(string division, string msg, Exception ex);
	}
}
