		public virtual int PadBits => mPadBits;

		public virtual int IntValue
		{
			get
			{
				int num = 0;
				int num2 = System.Math.Min(4, mData.Length);
				for (int i = 0; i < num2; i++)
				{
					num |= mData[i] << 8 * i;
				}
				if (mPadBits > 0 && num2 == mData.Length)
				{
					int num3 = (1 << mPadBits) - 1;
					num &= ~(num3 << 8 * (num2 - 1));
