			{
				mData = new byte[0];
				mPadBits = 0;
				return;
			}
			int num = BigInteger.BitLen(namedBits);
			int num2 = (num + 7) / 8;
			byte[] array = new byte[num2];
			num2--;
			for (int i = 0; i < num2; i++)
			{
				array[i] = (byte)namedBits;
				namedBits >>= 8;
			}
			array[num2] = (byte)namedBits;
			int j;
			for (j = 0; (namedBits & (1 << j)) == 0; j++)
			{
			}
			mData = array;
			mPadBits = j;
		}

