	public class DerBmpString : DerStringBase
	{
		private readonly string str;

		public DerBmpString(byte[] str)
		{
			if (str == null)
			{
				throw new ArgumentNullException("str");
			}
			char[] array = new char[str.Length / 2];
			for (int i = 0; i != array.Length; i++)
			{
				array[i] = (char)((str[2 * i] << 8) | (str[2 * i + 1] & 0xFF));
			}
			this.str = new string(array);
		}

		public DerBmpString(string str)
		{
			if (str == null)
			{
				throw new ArgumentNullException("str");
			}
			this.str = str;
		}

		public static DerBmpString GetInstance(object obj)
		{
			if (obj == null || obj is DerBmpString)
			{
				return (DerBmpString)obj;
			}
			throw new ArgumentException("illegal object in GetInstance: " + Platform.GetTypeName(obj));
		}

		public static DerBmpString GetInstance(Asn1TaggedObject obj, bool isExplicit)
		{
			Asn1Object asn1Object = obj.GetObject();
			if (isExplicit || asn1Object is DerBmpString)
			{
				return GetInstance(asn1Object);
			}
			return new DerBmpString(Asn1OctetString.GetInstance(asn1Object).GetOctets());
		}

		public override string GetString()
		{
			return str;
		}

		protected override bool Asn1Equals(Asn1Object asn1Object)
		{
			if (!(asn1Object is DerBmpString derBmpString))
			{
				return false;
			}
			return str.Equals(derBmpString.str);
		}

		internal override void Encode(DerOutputStream derOut)
		{
			char[] array = str.ToCharArray();
			byte[] array2 = new byte[array.Length * 2];
			for (int i = 0; i != array.Length; i++)
			{
				array2[2 * i] = (byte)((int)array[i] >> 8);
				array2[2 * i + 1] = (byte)array[i];
			}
			derOut.WriteEncoded(30, array2);
		}
	}
	public class DerBoolean : Asn1Object
	{
		private readonly byte value;

		public static readonly DerBoolean False = new DerBoolean(value: false);

		public static readonly DerBoolean True = new DerBoolean(value: true);

		public bool IsTrue => value != 0;

		public DerBoolean(byte[] val)
		{
			if (val.Length != 1)
			{
				throw new ArgumentException("byte value should have 1 byte in it", "val");
			}
			value = val[0];
		}

		private DerBoolean(bool value)
		{
			this.value = (byte)(value ? byte.MaxValue : 0);
		}

		public static DerBoolean GetInstance(object obj)
		{
			if (obj == null || obj is DerBoolean)
			{
				return (DerBoolean)obj;
			}
			throw new ArgumentException("illegal object in GetInstance: " + Platform.GetTypeName(obj));
		}

		public static DerBoolean GetInstance(bool value)
		{
			return (!value) ? False : True;
		}

		public static DerBoolean GetInstance(Asn1TaggedObject obj, bool isExplicit)
		{
			Asn1Object asn1Object = obj.GetObject();
			if (isExplicit || asn1Object is DerBoolean)
			{
				return GetInstance(asn1Object);
			}
			return FromOctetString(((Asn1OctetString)asn1Object).GetOctets());
		}

		internal override void Encode(DerOutputStream derOut)
		{
			derOut.WriteEncoded(1, new byte[1] { value });
		}

		protected override bool Asn1Equals(Asn1Object asn1Object)
		{
			if (!(asn1Object is DerBoolean derBoolean))
			{
				return false;
			}
			return IsTrue == derBoolean.IsTrue;
		}

		protected override int Asn1GetHashCode()
		{
			return IsTrue.GetHashCode();
		}

		public override string ToString()
		{
			return (!IsTrue) ? "FALSE" : "TRUE";
		}

		internal static DerBoolean FromOctetString(byte[] value)
		{
			if (value.Length != 1)
			{
				throw new ArgumentException("BOOLEAN value should have 1 byte in it", "value");
			}
			return value[0] switch
			{
				0 => False, 
				byte.MaxValue => True, 
				_ => new DerBoolean(value), 
			};
		}
	}
	public class DerEnumerated : Asn1Object
	{
		private readonly byte[] bytes;

		private static readonly DerEnumerated[] cache = new DerEnumerated[12];

		public BigInteger Value => new BigInteger(bytes);

		public DerEnumerated(int val)
		{
			bytes = BigInteger.ValueOf(val).ToByteArray();
		}

		public DerEnumerated(BigInteger val)
		{
			bytes = val.ToByteArray();
		}

		public DerEnumerated(byte[] bytes)
		{
			this.bytes = bytes;
		}

		public static DerEnumerated GetInstance(object obj)
		{
			if (obj == null || obj is DerEnumerated)
			{
				return (DerEnumerated)obj;
			}
			throw new ArgumentException("illegal object in GetInstance: " + Platform.GetTypeName(obj));
		}

		public static DerEnumerated GetInstance(Asn1TaggedObject obj, bool isExplicit)
		{
			Asn1Object asn1Object = obj.GetObject();
			if (isExplicit || asn1Object is DerEnumerated)
			{
				return GetInstance(asn1Object);
			}
			return FromOctetString(((Asn1OctetString)asn1Object).GetOctets());
		}

		internal override void Encode(DerOutputStream derOut)
		{
			derOut.WriteEncoded(10, bytes);
		}

		protected override bool Asn1Equals(Asn1Object asn1Object)
		{
			if (!(asn1Object is DerEnumerated derEnumerated))
			{
				return false;
			}
			return Arrays.AreEqual(bytes, derEnumerated.bytes);
		}

		protected override int Asn1GetHashCode()
		{
			return Arrays.GetHashCode(bytes);
		}

		internal static DerEnumerated FromOctetString(byte[] enc)
		{
			if (enc.Length == 0)
			{
				throw new ArgumentException("ENUMERATED has zero length", "enc");
			}
			if (enc.Length == 1)
			{
				int num = enc[0];
				if (num < cache.Length)
				{
					DerEnumerated derEnumerated = cache[num];
					if (derEnumerated != null)
					{
						return derEnumerated;
					}
					return cache[num] = new DerEnumerated(Arrays.Clone(enc));
				}
			}
			return new DerEnumerated(Arrays.Clone(enc));
		}
	}
	public class DerExternal : Asn1Object
	{
		private DerObjectIdentifier directReference;

		private DerInteger indirectReference;

		private Asn1Object dataValueDescriptor;

		private int encoding;

		private Asn1Object externalContent;

