			Asn1TaggedObject asn1TaggedObject = (Asn1TaggedObject)objFromVector;
			Encoding = asn1TaggedObject.TagNo;
			if (encoding < 0 || encoding > 2)
			{
				throw new InvalidOperationException("invalid encoding value");
