	internal class IndefiniteLengthInputStream : LimitedInputStream
	{
		private int _lookAhead;

		private bool _eofOn00 = true;

		internal IndefiniteLengthInputStream(Stream inStream, int limit)
			: base(inStream, limit)
		{
			_lookAhead = RequireByte();
			CheckForEof();
		}

		internal void SetEofOn00(bool eofOn00)
		{
			_eofOn00 = eofOn00;
			if (_eofOn00)
			{
				CheckForEof();
			}
		}

		private bool CheckForEof()
		{
			if (_lookAhead == 0)
			{
				if (RequireByte() != 0)
				{
					throw new IOException("malformed end-of-contents marker");
				}
				_lookAhead = -1;
				SetParentEofDetect(on: true);
				return true;
			}
			return _lookAhead < 0;
		}

		public override int Read(byte[] buffer, int offset, int count)
		{
			if (_eofOn00 || count <= 1)
			{
				return base.Read(buffer, offset, count);
			}
			if (_lookAhead < 0)
			{
				return 0;
			}
			int num = _in.Read(buffer, offset + 1, count - 1);
			if (num <= 0)
			{
				throw new EndOfStreamException();
			}
			buffer[offset] = (byte)_lookAhead;
			_lookAhead = RequireByte();
			return num + 1;
		}

		public override int ReadByte()
		{
			if (_eofOn00 && CheckForEof())
			{
				return -1;
			}
			int lookAhead = _lookAhead;
			_lookAhead = RequireByte();
			return lookAhead;
		}

		private int RequireByte()
		{
			int num = _in.ReadByte();
			if (num < 0)
			{
				throw new EndOfStreamException();
			}
			return num;
		}
	}
	public class LazyAsn1InputStream : Asn1InputStream
	{
		public LazyAsn1InputStream(byte[] input)
			: base(input)
		{
		}

		public LazyAsn1InputStream(Stream inputStream)
			: base(inputStream)
		{
		}

		internal override DerSequence CreateDerSequence(DefiniteLengthInputStream dIn)
		{
			return new LazyDerSequence(dIn.ToArray());
		}

		internal override DerSet CreateDerSet(DefiniteLengthInputStream dIn)
		{
			return new LazyDerSet(dIn.ToArray());
		}
	}
	internal class LazyDerSequence : DerSequence
	{
		private byte[] encoded;

		public override Asn1Encodable this[int index]
		{
			get
			{
				Parse();
				return base[index];
			}
		}

		public override int Count
		{
			get
			{
				Parse();
				return base.Count;
			}
		}

		internal LazyDerSequence(byte[] encoded)
		{
			this.encoded = encoded;
		}

		private void Parse()
		{
			lock (this)
			{
				if (encoded != null)
				{
					Asn1InputStream asn1InputStream = new LazyAsn1InputStream(encoded);
					Asn1Object obj;
					while ((obj = asn1InputStream.ReadObject()) != null)
					{
						AddObject(obj);
					}
					encoded = null;
				}
			}
		}

		public override IEnumerator GetEnumerator()
		{
			Parse();
			return base.GetEnumerator();
		}

		internal override void Encode(DerOutputStream derOut)
		{
			lock (this)
			{
				if (encoded == null)
				{
					base.Encode(derOut);
				}
				else
				{
					derOut.WriteEncoded(48, encoded);
				}
			}
		}
	}
	internal class LazyDerSet : DerSet
	{
		private byte[] encoded;

		public override Asn1Encodable this[int index]
		{
			get
			{
				Parse();
				return base[index];
			}
		}

		public override int Count
		{
			get
			{
				Parse();
				return base.Count;
			}
		}

		internal LazyDerSet(byte[] encoded)
		{
			this.encoded = encoded;
		}

		private void Parse()
		{
			lock (this)
			{
				if (encoded != null)
				{
					Asn1InputStream asn1InputStream = new LazyAsn1InputStream(encoded);
					Asn1Object obj;
					while ((obj = asn1InputStream.ReadObject()) != null)
					{
						AddObject(obj);
					}
					encoded = null;
				}
			}
		}

		public override IEnumerator GetEnumerator()
		{
			Parse();
			return base.GetEnumerator();
		}

		internal override void Encode(DerOutputStream derOut)
		{
			lock (this)
			{
				if (encoded == null)
				{
					base.Encode(derOut);
				}
				else
				{
					derOut.WriteEncoded(49, encoded);
				}
			}
		}
	}
	internal abstract class LimitedInputStream : BaseInputStream
	{
		protected readonly Stream _in;

		private int _limit;

		internal LimitedInputStream(Stream inStream, int limit)
		{
			_in = inStream;
			_limit = limit;
		}

		internal virtual int GetRemaining()
		{
			return _limit;
		}

		protected virtual void SetParentEofDetect(bool on)
		{
			if (_in is IndefiniteLengthInputStream)
			{
				((IndefiniteLengthInputStream)_in).SetEofOn00(on);
			}
		}
	}
