			foreach (DerObjectIdentifier item in ordering)
			{
				X509Extension x509Extension = (X509Extension)extensions[item];
				Asn1EncodableVector asn1EncodableVector2 = new Asn1EncodableVector(item);
				if (x509Extension.IsCritical)
				{
