	public class X962Parameters : Asn1Encodable, IAsn1Choice
	{
		private readonly Asn1Object _params;

		public bool IsNamedCurve => _params is DerObjectIdentifier;

		public bool IsImplicitlyCA => _params is Asn1Null;

		public Asn1Object Parameters => _params;

		public X962Parameters(X9ECParameters ecParameters)
		{
			_params = ecParameters.ToAsn1Object();
		}

		public X962Parameters(DerObjectIdentifier namedCurve)
		{
			_params = namedCurve;
		}

		public X962Parameters(Asn1Object obj)
		{
			_params = obj;
		}

		public static X962Parameters GetInstance(object obj)
		{
			if (obj == null || obj is X962Parameters)
			{
				return (X962Parameters)obj;
			}
			if (obj is Asn1Object)
			{
				return new X962Parameters((Asn1Object)obj);
			}
			if (obj is byte[])
			{
				try
				{
					return new X962Parameters(Asn1Object.FromByteArray((byte[])obj));
				}
				catch (Exception ex)
				{
					throw new ArgumentException("unable to parse encoded data: " + ex.Message, ex);
				}
			}
			throw new ArgumentException("unknown object in getInstance()");
		}

		public override Asn1Object ToAsn1Object()
		{
			return _params;
		}
	}
	public class X9Curve : Asn1Encodable
	{
		private readonly ECCurve curve;

		private readonly byte[] seed;

		private readonly DerObjectIdentifier fieldIdentifier;

		public ECCurve Curve => curve;

		public X9Curve(ECCurve curve)
			: this(curve, null)
		{
		}

		public X9Curve(ECCurve curve, byte[] seed)
		{
			if (curve == null)
			{
				throw new ArgumentNullException("curve");
			}
			this.curve = curve;
			this.seed = Arrays.Clone(seed);
			if (ECAlgorithms.IsFpCurve(curve))
			{
				fieldIdentifier = X9ObjectIdentifiers.PrimeField;
				return;
			}
			if (ECAlgorithms.IsF2mCurve(curve))
			{
				fieldIdentifier = X9ObjectIdentifiers.CharacteristicTwoField;
				return;
			}
			throw new ArgumentException("This type of ECCurve is not implemented");
		}

		public X9Curve(X9FieldID fieldID, Asn1Sequence seq)
		{
			if (fieldID == null)
			{
				throw new ArgumentNullException("fieldID");
			}
			if (seq == null)
			{
				throw new ArgumentNullException("seq");
			}
			fieldIdentifier = fieldID.Identifier;
			if (fieldIdentifier.Equals(X9ObjectIdentifiers.PrimeField))
			{
				BigInteger value = ((DerInteger)fieldID.Parameters).Value;
				X9FieldElement x9FieldElement = new X9FieldElement(value, (Asn1OctetString)seq[0]);
				X9FieldElement x9FieldElement2 = new X9FieldElement(value, (Asn1OctetString)seq[1]);
				curve = new FpCurve(value, x9FieldElement.Value.ToBigInteger(), x9FieldElement2.Value.ToBigInteger());
			}
			else if (fieldIdentifier.Equals(X9ObjectIdentifiers.CharacteristicTwoField))
			{
				DerSequence derSequence = (DerSequence)fieldID.Parameters;
				int intValue = ((DerInteger)derSequence[0]).Value.IntValue;
				DerObjectIdentifier derObjectIdentifier = (DerObjectIdentifier)derSequence[1];
				int num = 0;
				int k = 0;
				int k2 = 0;
				if (derObjectIdentifier.Equals(X9ObjectIdentifiers.TPBasis))
				{
					num = ((DerInteger)derSequence[2]).Value.IntValue;
				}
				else
				{
					DerSequence derSequence2 = (DerSequence)derSequence[2];
					num = ((DerInteger)derSequence2[0]).Value.IntValue;
					k = ((DerInteger)derSequence2[1]).Value.IntValue;
					k2 = ((DerInteger)derSequence2[2]).Value.IntValue;
				}
				X9FieldElement x9FieldElement3 = new X9FieldElement(intValue, num, k, k2, (Asn1OctetString)seq[0]);
				X9FieldElement x9FieldElement4 = new X9FieldElement(intValue, num, k, k2, (Asn1OctetString)seq[1]);
				curve = new F2mCurve(intValue, num, k, k2, x9FieldElement3.Value.ToBigInteger(), x9FieldElement4.Value.ToBigInteger());
			}
			if (seq.Count == 3)
			{
				seed = ((DerBitString)seq[2]).GetBytes();
			}
		}

		public byte[] GetSeed()
		{
			return Arrays.Clone(seed);
		}

		public override Asn1Object ToAsn1Object()
		{
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector();
			if (fieldIdentifier.Equals(X9ObjectIdentifiers.PrimeField) || fieldIdentifier.Equals(X9ObjectIdentifiers.CharacteristicTwoField))
			{
				asn1EncodableVector.Add(new X9FieldElement(curve.A).ToAsn1Object());
				asn1EncodableVector.Add(new X9FieldElement(curve.B).ToAsn1Object());
			}
			if (seed != null)
			{
				asn1EncodableVector.Add(new DerBitString(seed));
			}
			return new DerSequence(asn1EncodableVector);
		}
	}
	public class X9ECParameters : Asn1Encodable
	{
		private X9FieldID fieldID;

		private ECCurve curve;

		private X9ECPoint g;

		private BigInteger n;

		private BigInteger h;

		private byte[] seed;

		public ECCurve Curve => curve;

		public ECPoint G => g.Point;

		public BigInteger N => n;

		public BigInteger H => h;

		public X9Curve CurveEntry => new X9Curve(curve, seed);

		public X9FieldID FieldIDEntry => fieldID;

		public X9ECPoint BaseEntry => g;

		public X9ECParameters(Asn1Sequence seq)
		{
			if (!(seq[0] is DerInteger) || !((DerInteger)seq[0]).Value.Equals(BigInteger.One))
			{
				throw new ArgumentException("bad version in X9ECParameters");
			}
			X9Curve x9Curve = new X9Curve(X9FieldID.GetInstance(seq[1]), Asn1Sequence.GetInstance(seq[2]));
			curve = x9Curve.Curve;
			object obj = seq[3];
			if (obj is X9ECPoint)
			{
				g = (X9ECPoint)obj;
			}
			else
			{
				g = new X9ECPoint(curve, (Asn1OctetString)obj);
			}
			n = ((DerInteger)seq[4]).Value;
			seed = x9Curve.GetSeed();
			if (seq.Count == 6)
			{
				h = ((DerInteger)seq[5]).Value;
			}
		}

		public X9ECParameters(ECCurve curve, ECPoint g, BigInteger n)
			: this(curve, g, n, null, null)
		{
		}

		public X9ECParameters(ECCurve curve, X9ECPoint g, BigInteger n, BigInteger h)
			: this(curve, g, n, h, null)
		{
		}

		public X9ECParameters(ECCurve curve, ECPoint g, BigInteger n, BigInteger h)
			: this(curve, g, n, h, null)
		{
		}

		public X9ECParameters(ECCurve curve, ECPoint g, BigInteger n, BigInteger h, byte[] seed)
			: this(curve, new X9ECPoint(g), n, h, seed)
		{
		}

		public X9ECParameters(ECCurve curve, X9ECPoint g, BigInteger n, BigInteger h, byte[] seed)
		{
			this.curve = curve;
			this.g = g;
			this.n = n;
			this.h = h;
			this.seed = seed;
			if (ECAlgorithms.IsFpCurve(curve))
			{
				fieldID = new X9FieldID(curve.Field.Characteristic);
				return;
			}
			if (ECAlgorithms.IsF2mCurve(curve))
			{
				IPolynomialExtensionField polynomialExtensionField = (IPolynomialExtensionField)curve.Field;
				int[] exponentsPresent = polynomialExtensionField.MinimalPolynomial.GetExponentsPresent();
				if (exponentsPresent.Length == 3)
				{
					fieldID = new X9FieldID(exponentsPresent[2], exponentsPresent[1]);
					return;
				}
				if (exponentsPresent.Length == 5)
				{
					fieldID = new X9FieldID(exponentsPresent[4], exponentsPresent[1], exponentsPresent[2], exponentsPresent[3]);
					return;
				}
				throw new ArgumentException("Only trinomial and pentomial curves are supported");
			}
			throw new ArgumentException("'curve' is of an unsupported type");
		}

		public static X9ECParameters GetInstance(object obj)
		{
			if (obj is X9ECParameters)
			{
				return (X9ECParameters)obj;
			}
			if (obj != null)
			{
				return new X9ECParameters(Asn1Sequence.GetInstance(obj));
			}
			return null;
		}

		public byte[] GetSeed()
		{
			return seed;
		}

		public override Asn1Object ToAsn1Object()
		{
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector(new DerInteger(BigInteger.One), fieldID, new X9Curve(curve, seed), g, new DerInteger(n));
			if (h != null)
			{
				asn1EncodableVector.Add(new DerInteger(h));
			}
			return new DerSequence(asn1EncodableVector);
		}
	}
	public abstract class X9ECParametersHolder
	{
		private X9ECParameters parameters;

		public X9ECParameters Parameters
		{
			get
			{
				lock (this)
				{
					if (parameters == null)
					{
						parameters = CreateParameters();
					}
					return parameters;
				}
			}
		}

		protected abstract X9ECParameters CreateParameters();
	}
	public class X9ECPoint : Asn1Encodable
	{
		private readonly Asn1OctetString encoding;

		private ECCurve c;

		private ECPoint p;

		public ECPoint Point
		{
			get
			{
				if (p == null)
				{
					p = c.DecodePoint(encoding.GetOctets()).Normalize();
				}
				return p;
			}
		}

		public bool IsPointCompressed
		{
			get
			{
				byte[] octets = encoding.GetOctets();
				return octets != null && octets.Length > 0 && (octets[0] == 2 || octets[0] == 3);
			}
		}

		public X9ECPoint(ECPoint p)
			: this(p, compressed: false)
		{
		}

		public X9ECPoint(ECPoint p, bool compressed)
		{
			this.p = p.Normalize();
			encoding = new DerOctetString(p.GetEncoded(compressed));
		}

		public X9ECPoint(ECCurve c, byte[] encoding)
		{
			this.c = c;
			this.encoding = new DerOctetString(Arrays.Clone(encoding));
		}

		public X9ECPoint(ECCurve c, Asn1OctetString s)
			: this(c, s.GetOctets())
		{
		}

		public byte[] GetPointEncoding()
		{
			return Arrays.Clone(encoding.GetOctets());
		}

		public override Asn1Object ToAsn1Object()
		{
			return encoding;
		}
	}
	public class X9FieldElement : Asn1Encodable
	{
		private ECFieldElement f;

		public ECFieldElement Value => f;

		public X9FieldElement(ECFieldElement f)
		{
			this.f = f;
		}

		public X9FieldElement(BigInteger p, Asn1OctetString s)
			: this(new FpFieldElement(p, new BigInteger(1, s.GetOctets())))
		{
		}

		public X9FieldElement(int m, int k1, int k2, int k3, Asn1OctetString s)
			: this(new F2mFieldElement(m, k1, k2, k3, new BigInteger(1, s.GetOctets())))
		{
		}

		public override Asn1Object ToAsn1Object()
		{
			int byteLength = X9IntegerConverter.GetByteLength(f);
			byte[] str = X9IntegerConverter.IntegerToBytes(f.ToBigInteger(), byteLength);
			return new DerOctetString(str);
		}
	}
	public class X9FieldID : Asn1Encodable
	{
		private readonly DerObjectIdentifier id;

		private readonly Asn1Object parameters;

		public DerObjectIdentifier Identifier => id;

		public Asn1Object Parameters => parameters;

		public X9FieldID(BigInteger primeP)
		{
			id = X9ObjectIdentifiers.PrimeField;
			parameters = new DerInteger(primeP);
		}

		public X9FieldID(int m, int k1)
			: this(m, k1, 0, 0)
		{
		}

		public X9FieldID(int m, int k1, int k2, int k3)
		{
			id = X9ObjectIdentifiers.CharacteristicTwoField;
			Asn1EncodableVector asn1EncodableVector = new Asn1EncodableVector(new DerInteger(m));
			if (k2 == 0)
			{
				if (k3 != 0)
				{
					throw new ArgumentException("inconsistent k values");
				}
				asn1EncodableVector.Add(X9ObjectIdentifiers.TPBasis, new DerInteger(k1));
			}
			else
			{
				if (k2 <= k1 || k3 <= k2)
				{
					throw new ArgumentException("inconsistent k values");
				}
				asn1EncodableVector.Add(X9ObjectIdentifiers.PPBasis, new DerSequence(new DerInteger(k1), new DerInteger(k2), new DerInteger(k3)));
			}
			parameters = new DerSequence(asn1EncodableVector);
		}

		private X9FieldID(Asn1Sequence seq)
		{
			id = DerObjectIdentifier.GetInstance(seq[0]);
			parameters = seq[1].ToAsn1Object();
		}

		public static X9FieldID GetInstance(object obj)
		{
			if (obj is X9FieldID)
			{
				return (X9FieldID)obj;
			}
			if (obj == null)
			{
				return null;
			}
			return new X9FieldID(Asn1Sequence.GetInstance(obj));
		}

		public override Asn1Object ToAsn1Object()
		{
			return new DerSequence(id, parameters);
		}
	}
	public abstract class X9IntegerConverter
	{
		public static int GetByteLength(ECFieldElement fe)
		{
			return (fe.FieldSize + 7) / 8;
		}

		public static int GetByteLength(ECCurve c)
		{
			return (c.FieldSize + 7) / 8;
		}

		public static byte[] IntegerToBytes(BigInteger s, int qLength)
		{
			byte[] array = s.ToByteArrayUnsigned();
			if (qLength < array.Length)
			{
				byte[] array2 = new byte[qLength];
				Array.Copy(array, array.Length - array2.Length, array2, 0, array2.Length);
				return array2;
			}
			if (qLength > array.Length)
			{
				byte[] array3 = new byte[qLength];
				Array.Copy(array, 0, array3, array3.Length - array.Length, array.Length);
				return array3;
			}
			return array;
		}
	}
