		}

		public override bool Equals(object obj)
		{
			if (!(obj is AsymmetricKeyParameter other))
			{
				return false;
			}
			return Equals(other);
		}

		protected bool Equals(AsymmetricKeyParameter other)
		{
			return privateKey == other.privateKey;
		}

