			byte[] array = ((updateOutputSize <= 0) ? null : new byte[updateOutputSize]);
			int num = ProcessByte(input, array, 0);
			if (updateOutputSize > 0 && num < updateOutputSize)
			{
				byte[] array2 = new byte[num];
				Array.Copy(array, 0, array2, 0, num);
				array = array2;
