	public abstract class GeneralDigest : IDigest, IMemoable
	{
		private const int BYTE_LENGTH = 64;

		private byte[] xBuf;

		private int xBufOff;

		private long byteCount;

		public abstract string AlgorithmName { get; }

		internal GeneralDigest()
		{
			xBuf = new byte[4];
		}

		internal GeneralDigest(GeneralDigest t)
		{
			xBuf = new byte[t.xBuf.Length];
			CopyIn(t);
		}

		protected void CopyIn(GeneralDigest t)
		{
			Array.Copy(t.xBuf, 0, xBuf, 0, t.xBuf.Length);
			xBufOff = t.xBufOff;
			byteCount = t.byteCount;
		}

		public void Update(byte input)
		{
			xBuf[xBufOff++] = input;
			if (xBufOff == xBuf.Length)
			{
				ProcessWord(xBuf, 0);
				xBufOff = 0;
			}
			byteCount++;
		}

		public void BlockUpdate(byte[] input, int inOff, int length)
		{
			length = System.Math.Max(0, length);
			int i = 0;
			if (xBufOff != 0)
			{
				while (i < length)
				{
					xBuf[xBufOff++] = input[inOff + i++];
					if (xBufOff == 4)
					{
						ProcessWord(xBuf, 0);
						xBufOff = 0;
						break;
					}
				}
			}
			for (int num = ((length - i) & -4) + i; i < num; i += 4)
			{
				ProcessWord(input, inOff + i);
			}
			while (i < length)
			{
				xBuf[xBufOff++] = input[inOff + i++];
			}
			byteCount += length;
		}

		public void Finish()
		{
			long bitLength = byteCount << 3;
			Update(128);
			while (xBufOff != 0)
			{
				Update(0);
			}
			ProcessLength(bitLength);
			ProcessBlock();
		}

		public virtual void Reset()
		{
			byteCount = 0L;
			xBufOff = 0;
			Array.Clear(xBuf, 0, xBuf.Length);
		}

		public int GetByteLength()
		{
			return 64;
		}

		internal abstract void ProcessWord(byte[] input, int inOff);

		internal abstract void ProcessLength(long bitLength);

		internal abstract void ProcessBlock();

		public abstract int GetDigestSize();

		public abstract int DoFinal(byte[] output, int outOff);

		public abstract IMemoable Copy();

		public abstract void Reset(IMemoable t);
	}
	public class Gost3411Digest : IDigest, IMemoable
	{
		private const int DIGEST_LENGTH = 32;

		private byte[] H = new byte[32];

		private byte[] L = new byte[32];

		private byte[] M = new byte[32];

		private byte[] Sum = new byte[32];

		private byte[][] C = MakeC();

		private byte[] xBuf = new byte[32];

		private int xBufOff;

		private ulong byteCount;

		private readonly IBlockCipher cipher = new Gost28147Engine();

		private byte[] sBox;

		private byte[] K = new byte[32];

		private byte[] a = new byte[8];

		internal short[] wS = new short[16];

		internal short[] w_S = new short[16];

		internal byte[] S = new byte[32];

		internal byte[] U = new byte[32];

		internal byte[] V = new byte[32];

		internal byte[] W = new byte[32];

		private static readonly byte[] C2 = new byte[32]
		{
			0, 255, 0, 255, 0, 255, 0, 255, 255, 0,
			255, 0, 255, 0, 255, 0, 0, 255, 255, 0,
			255, 0, 0, 255, 255, 0, 0, 0, 255, 255,
			0, 255
		};

		public string AlgorithmName => "Gost3411";

		public Gost3411Digest()
		{
			sBox = Gost28147Engine.GetSBox("D-A");
			cipher.Init(forEncryption: true, new ParametersWithSBox(null, sBox));
			Reset();
		}

		public Gost3411Digest(byte[] sBoxParam)
		{
			sBox = Arrays.Clone(sBoxParam);
			cipher.Init(forEncryption: true, new ParametersWithSBox(null, sBox));
			Reset();
		}

		public Gost3411Digest(Gost3411Digest t)
		{
			Reset(t);
		}

		private static byte[][] MakeC()
		{
			byte[][] array = new byte[4][];
			for (int i = 0; i < 4; i++)
			{
				array[i] = new byte[32];
			}
			return array;
		}

		public int GetDigestSize()
		{
			return 32;
		}

		public void Update(byte input)
		{
			xBuf[xBufOff++] = input;
			if (xBufOff == xBuf.Length)
			{
				sumByteArray(xBuf);
				processBlock(xBuf, 0);
				xBufOff = 0;
			}
			byteCount++;
		}

		public void BlockUpdate(byte[] input, int inOff, int length)
		{
			while (xBufOff != 0 && length > 0)
			{
				Update(input[inOff]);
				inOff++;
				length--;
			}
			while (length > xBuf.Length)
			{
				Array.Copy(input, inOff, xBuf, 0, xBuf.Length);
				sumByteArray(xBuf);
				processBlock(xBuf, 0);
				inOff += xBuf.Length;
				length -= xBuf.Length;
				byteCount += (uint)xBuf.Length;
			}
			while (length > 0)
			{
				Update(input[inOff]);
				inOff++;
				length--;
			}
		}

		private byte[] P(byte[] input)
		{
			int num = 0;
			for (int i = 0; i < 8; i++)
			{
				K[num++] = input[i];
				K[num++] = input[8 + i];
				K[num++] = input[16 + i];
				K[num++] = input[24 + i];
			}
			return K;
		}

		private byte[] A(byte[] input)
		{
			for (int i = 0; i < 8; i++)
			{
				a[i] = (byte)(input[i] ^ input[i + 8]);
			}
			Array.Copy(input, 8, input, 0, 24);
			Array.Copy(a, 0, input, 24, 8);
			return input;
		}

		private void E(byte[] key, byte[] s, int sOff, byte[] input, int inOff)
		{
			cipher.Init(forEncryption: true, new KeyParameter(key));
			cipher.ProcessBlock(input, inOff, s, sOff);
		}

		private void fw(byte[] input)
		{
			cpyBytesToShort(input, wS);
			w_S[15] = (short)(wS[0] ^ wS[1] ^ wS[2] ^ wS[3] ^ wS[12] ^ wS[15]);
			Array.Copy(wS, 1, w_S, 0, 15);
			cpyShortToBytes(w_S, input);
		}

		private void processBlock(byte[] input, int inOff)
		{
			Array.Copy(input, inOff, M, 0, 32);
			H.CopyTo(U, 0);
			M.CopyTo(V, 0);
			for (int i = 0; i < 32; i++)
			{
				W[i] = (byte)(U[i] ^ V[i]);
			}
			E(P(W), S, 0, H, 0);
			for (int j = 1; j < 4; j++)
			{
				byte[] array = A(U);
				for (int k = 0; k < 32; k++)
				{
					U[k] = (byte)(array[k] ^ C[j][k]);
				}
				V = A(A(V));
				for (int l = 0; l < 32; l++)
				{
					W[l] = (byte)(U[l] ^ V[l]);
				}
				E(P(W), S, j * 8, H, j * 8);
			}
			for (int m = 0; m < 12; m++)
			{
				fw(S);
			}
			for (int n = 0; n < 32; n++)
			{
				S[n] ^= M[n];
			}
			fw(S);
			for (int num = 0; num < 32; num++)
			{
				S[num] = (byte)(H[num] ^ S[num]);
			}
			for (int num2 = 0; num2 < 61; num2++)
			{
				fw(S);
			}
			Array.Copy(S, 0, H, 0, H.Length);
		}

		private void finish()
		{
			ulong n = byteCount * 8;
			Pack.UInt64_To_LE(n, L);
			while (xBufOff != 0)
			{
				Update(0);
			}
			processBlock(L, 0);
			processBlock(Sum, 0);
		}

		public int DoFinal(byte[] output, int outOff)
		{
			finish();
			H.CopyTo(output, outOff);
			Reset();
			return 32;
		}

		public void Reset()
		{
			byteCount = 0uL;
			xBufOff = 0;
			Array.Clear(H, 0, H.Length);
			Array.Clear(L, 0, L.Length);
			Array.Clear(M, 0, M.Length);
			Array.Clear(C[1], 0, C[1].Length);
			Array.Clear(C[3], 0, C[3].Length);
			Array.Clear(Sum, 0, Sum.Length);
			Array.Clear(xBuf, 0, xBuf.Length);
			C2.CopyTo(C[2], 0);
		}

		private void sumByteArray(byte[] input)
		{
			int num = 0;
			for (int i = 0; i != Sum.Length; i++)
			{
				int num2 = (Sum[i] & 0xFF) + (input[i] & 0xFF) + num;
				Sum[i] = (byte)num2;
				num = num2 >> 8;
			}
		}

		private static void cpyBytesToShort(byte[] S, short[] wS)
		{
			for (int i = 0; i < S.Length / 2; i++)
			{
				wS[i] = (short)(((S[i * 2 + 1] << 8) & 0xFF00) | (S[i * 2] & 0xFF));
			}
		}

		private static void cpyShortToBytes(short[] wS, byte[] S)
		{
			for (int i = 0; i < S.Length / 2; i++)
			{
				S[i * 2 + 1] = (byte)(wS[i] >> 8);
				S[i * 2] = (byte)wS[i];
			}
		}

		public int GetByteLength()
		{
			return 32;
		}

		public IMemoable Copy()
		{
			return new Gost3411Digest(this);
		}

		public void Reset(IMemoable other)
		{
			Gost3411Digest gost3411Digest = (Gost3411Digest)other;
			sBox = gost3411Digest.sBox;
			cipher.Init(forEncryption: true, new ParametersWithSBox(null, sBox));
			Reset();
			Array.Copy(gost3411Digest.H, 0, H, 0, gost3411Digest.H.Length);
			Array.Copy(gost3411Digest.L, 0, L, 0, gost3411Digest.L.Length);
			Array.Copy(gost3411Digest.M, 0, M, 0, gost3411Digest.M.Length);
			Array.Copy(gost3411Digest.Sum, 0, Sum, 0, gost3411Digest.Sum.Length);
			Array.Copy(gost3411Digest.C[1], 0, C[1], 0, gost3411Digest.C[1].Length);
			Array.Copy(gost3411Digest.C[2], 0, C[2], 0, gost3411Digest.C[2].Length);
			Array.Copy(gost3411Digest.C[3], 0, C[3], 0, gost3411Digest.C[3].Length);
			Array.Copy(gost3411Digest.xBuf, 0, xBuf, 0, gost3411Digest.xBuf.Length);
			xBufOff = gost3411Digest.xBufOff;
			byteCount = gost3411Digest.byteCount;
		}
	}
	public class KeccakDigest : IDigest, IMemoable
	{
		private static readonly ulong[] KeccakRoundConstants = KeccakInitializeRoundConstants();

		private static readonly int[] KeccakRhoOffsets = KeccakInitializeRhoOffsets();

		protected byte[] state = new byte[200];

		protected byte[] dataQueue = new byte[192];

		protected int rate;

		protected int bitsInQueue;

		protected int fixedOutputLength;

		protected bool squeezing;

		protected int bitsAvailableForSqueezing;

		protected byte[] chunk;

		protected byte[] oneByte;

		private ulong[] C = new ulong[5];

		private ulong[] tempA = new ulong[25];

		private ulong[] chiC = new ulong[5];

		public virtual string AlgorithmName => "Keccak-" + fixedOutputLength;

		public KeccakDigest()
			: this(288)
		{
		}

		public KeccakDigest(int bitLength)
		{
			Init(bitLength);
		}

		public KeccakDigest(KeccakDigest source)
		{
			CopyIn(source);
		}

		private static ulong[] KeccakInitializeRoundConstants()
		{
			ulong[] array = new ulong[24];
			byte b = 1;
			for (int i = 0; i < 24; i++)
			{
				array[i] = 0uL;
				for (int j = 0; j < 7; j++)
				{
					int num = (1 << j) - 1;
					if ((b & 1) != 0)
					{
						array[i] ^= (ulong)(1L << num);
					}
					bool flag = (b & 0x80) != 0;
					b <<= 1;
					if (flag)
					{
						b ^= 0x71;
					}
				}
			}
			return array;
		}

		private static int[] KeccakInitializeRhoOffsets()
		{
			int[] array = new int[25];
			int num = (array[0] = 0);
			int num2 = 1;
			int num3 = 0;
			for (int i = 1; i < 25; i++)
			{
				num = (num + i) & 0x3F;
				array[num2 % 5 + 5 * (num3 % 5)] = num;
				int num4 = (0 * num2 + num3) % 5;
				int num5 = (2 * num2 + 3 * num3) % 5;
				num2 = num4;
				num3 = num5;
			}
			return array;
		}

		private void ClearDataQueueSection(int off, int len)
		{
			for (int i = off; i != off + len; i++)
			{
				dataQueue[i] = 0;
			}
		}

		private void CopyIn(KeccakDigest source)
		{
			Array.Copy(source.state, 0, state, 0, source.state.Length);
			Array.Copy(source.dataQueue, 0, dataQueue, 0, source.dataQueue.Length);
			rate = source.rate;
			bitsInQueue = source.bitsInQueue;
			fixedOutputLength = source.fixedOutputLength;
			squeezing = source.squeezing;
			bitsAvailableForSqueezing = source.bitsAvailableForSqueezing;
			chunk = Arrays.Clone(source.chunk);
			oneByte = Arrays.Clone(source.oneByte);
		}

		public virtual int GetDigestSize()
		{
			return fixedOutputLength / 8;
		}

		public virtual void Update(byte input)
		{
			oneByte[0] = input;
			Absorb(oneByte, 0, 8L);
		}

		public virtual void BlockUpdate(byte[] input, int inOff, int len)
		{
			Absorb(input, inOff, (long)len * 8L);
		}

		public virtual int DoFinal(byte[] output, int outOff)
		{
			Squeeze(output, outOff, fixedOutputLength);
			Reset();
			return GetDigestSize();
		}

		protected virtual int DoFinal(byte[] output, int outOff, byte partialByte, int partialBits)
		{
			if (partialBits > 0)
			{
				oneByte[0] = partialByte;
				Absorb(oneByte, 0, partialBits);
			}
			Squeeze(output, outOff, fixedOutputLength);
			Reset();
			return GetDigestSize();
		}

		public virtual void Reset()
		{
			Init(fixedOutputLength);
		}

		public virtual int GetByteLength()
		{
			return rate / 8;
		}

		private void Init(int bitLength)
		{
			switch (bitLength)
			{
			case 128:
				InitSponge(1344, 256);
				break;
			case 224:
				InitSponge(1152, 448);
				break;
			case 256:
				InitSponge(1088, 512);
				break;
			case 288:
				InitSponge(1024, 576);
				break;
			case 384:
				InitSponge(832, 768);
				break;
			case 512:
				InitSponge(576, 1024);
				break;
			default:
				throw new ArgumentException("must be one of 128, 224, 256, 288, 384, or 512.", "bitLength");
			}
		}

		private void InitSponge(int rate, int capacity)
		{
			if (rate + capacity != 1600)
			{
				throw new InvalidOperationException("rate + capacity != 1600");
			}
			if (rate <= 0 || rate >= 1600 || rate % 64 != 0)
			{
				throw new InvalidOperationException("invalid rate value");
			}
			this.rate = rate;
			fixedOutputLength = 0;
			Arrays.Fill(state, 0);
			Arrays.Fill(dataQueue, 0);
			bitsInQueue = 0;
			squeezing = false;
			bitsAvailableForSqueezing = 0;
			fixedOutputLength = capacity / 2;
			chunk = new byte[rate / 8];
			oneByte = new byte[1];
		}

		private void AbsorbQueue()
		{
			KeccakAbsorb(state, dataQueue, rate / 8);
			bitsInQueue = 0;
		}

		protected virtual void Absorb(byte[] data, int off, long databitlen)
		{
			if (bitsInQueue % 8 != 0)
			{
				throw new InvalidOperationException("attempt to absorb with odd length queue");
			}
			if (squeezing)
			{
				throw new InvalidOperationException("attempt to absorb while squeezing");
			}
			long num = 0L;
			while (num < databitlen)
			{
				if (bitsInQueue == 0 && databitlen >= rate && num <= databitlen - rate)
				{
					long num2 = (databitlen - num) / rate;
					for (long num3 = 0L; num3 < num2; num3++)
					{
						Array.Copy(data, (int)(off + num / 8 + num3 * chunk.Length), chunk, 0, chunk.Length);
						KeccakAbsorb(state, chunk, chunk.Length);
					}
					num += num2 * rate;
					continue;
				}
				int num4 = (int)(databitlen - num);
				if (num4 + bitsInQueue > rate)
				{
					num4 = rate - bitsInQueue;
				}
				int num5 = num4 % 8;
				num4 -= num5;
				Array.Copy(data, off + (int)(num / 8), dataQueue, bitsInQueue / 8, num4 / 8);
				bitsInQueue += num4;
				num += num4;
				if (bitsInQueue == rate)
				{
					AbsorbQueue();
				}
				if (num5 > 0)
				{
					int num6 = (1 << num5) - 1;
					dataQueue[bitsInQueue / 8] = (byte)(data[off + (int)(num / 8)] & num6);
					bitsInQueue += num5;
					num += num5;
				}
			}
		}

		private void PadAndSwitchToSqueezingPhase()
		{
			if (bitsInQueue + 1 == rate)
			{
				dataQueue[bitsInQueue / 8] |= (byte)(1 << bitsInQueue % 8);
				AbsorbQueue();
				ClearDataQueueSection(0, rate / 8);
			}
			else
			{
				ClearDataQueueSection((bitsInQueue + 7) / 8, rate / 8 - (bitsInQueue + 7) / 8);
				dataQueue[bitsInQueue / 8] |= (byte)(1 << bitsInQueue % 8);
			}
			dataQueue[(rate - 1) / 8] |= (byte)(1 << (rate - 1) % 8);
			AbsorbQueue();
			if (rate == 1024)
			{
				KeccakExtract1024bits(state, dataQueue);
				bitsAvailableForSqueezing = 1024;
			}
			else
			{
				KeccakExtract(state, dataQueue, rate / 64);
				bitsAvailableForSqueezing = rate;
			}
			squeezing = true;
		}

		protected virtual void Squeeze(byte[] output, int offset, long outputLength)
		{
			if (!squeezing)
			{
				PadAndSwitchToSqueezingPhase();
			}
			if (outputLength % 8 != 0)
			{
				throw new InvalidOperationException("outputLength not a multiple of 8");
			}
			int num2;
			for (long num = 0L; num < outputLength; num += num2)
			{
				if (bitsAvailableForSqueezing == 0)
				{
					KeccakPermutation(state);
					if (rate == 1024)
					{
						KeccakExtract1024bits(state, dataQueue);
						bitsAvailableForSqueezing = 1024;
					}
					else
					{
						KeccakExtract(state, dataQueue, rate / 64);
						bitsAvailableForSqueezing = rate;
					}
				}
				num2 = bitsAvailableForSqueezing;
				if (num2 > outputLength - num)
				{
					num2 = (int)(outputLength - num);
				}
				Array.Copy(dataQueue, (rate - bitsAvailableForSqueezing) / 8, output, offset + (int)(num / 8), num2 / 8);
				bitsAvailableForSqueezing -= num2;
			}
		}

		private static void FromBytesToWords(ulong[] stateAsWords, byte[] state)
		{
			for (int i = 0; i < 25; i++)
			{
				stateAsWords[i] = 0uL;
				int num = i * 8;
				for (int j = 0; j < 8; j++)
				{
					stateAsWords[i] |= ((ulong)state[num + j] & 0xFFuL) << 8 * j;
				}
			}
		}

		private static void FromWordsToBytes(byte[] state, ulong[] stateAsWords)
		{
			for (int i = 0; i < 25; i++)
			{
				int num = i * 8;
				for (int j = 0; j < 8; j++)
				{
					state[num + j] = (byte)(stateAsWords[i] >> 8 * j);
				}
			}
		}

		private void KeccakPermutation(byte[] state)
		{
			ulong[] stateAsWords = new ulong[state.Length / 8];
			FromBytesToWords(stateAsWords, state);
			KeccakPermutationOnWords(stateAsWords);
			FromWordsToBytes(state, stateAsWords);
		}

		private void KeccakPermutationAfterXor(byte[] state, byte[] data, int dataLengthInBytes)
		{
			for (int i = 0; i < dataLengthInBytes; i++)
			{
				state[i] ^= data[i];
			}
			KeccakPermutation(state);
		}

		private void KeccakPermutationOnWords(ulong[] state)
		{
			for (int i = 0; i < 24; i++)
			{
				Theta(state);
				Rho(state);
				Pi(state);
				Chi(state);
				Iota(state, i);
			}
		}

		private void Theta(ulong[] A)
		{
			for (int i = 0; i < 5; i++)
			{
				C[i] = 0uL;
				for (int j = 0; j < 5; j++)
				{
					C[i] ^= A[i + 5 * j];
				}
			}
			for (int k = 0; k < 5; k++)
			{
				ulong num = (C[(k + 1) % 5] << 1) ^ (C[(k + 1) % 5] >> 63) ^ C[(k + 4) % 5];
				for (int l = 0; l < 5; l++)
				{
					A[k + 5 * l] ^= num;
				}
			}
		}

		private void Rho(ulong[] A)
		{
			for (int i = 0; i < 5; i++)
			{
				for (int j = 0; j < 5; j++)
				{
					int num = i + 5 * j;
					A[num] = ((KeccakRhoOffsets[num] == 0) ? A[num] : ((A[num] << KeccakRhoOffsets[num]) ^ (A[num] >> 64 - KeccakRhoOffsets[num])));
				}
			}
		}

		private void Pi(ulong[] A)
		{
			Array.Copy(A, 0, tempA, 0, tempA.Length);
			for (int i = 0; i < 5; i++)
			{
				for (int j = 0; j < 5; j++)
				{
					A[j + 5 * ((2 * i + 3 * j) % 5)] = tempA[i + 5 * j];
				}
			}
		}

		private void Chi(ulong[] A)
		{
			for (int i = 0; i < 5; i++)
			{
				for (int j = 0; j < 5; j++)
				{
					chiC[j] = A[j + 5 * i] ^ (~A[(j + 1) % 5 + 5 * i] & A[(j + 2) % 5 + 5 * i]);
				}
				for (int k = 0; k < 5; k++)
				{
					A[k + 5 * i] = chiC[k];
				}
			}
		}

		private static void Iota(ulong[] A, int indexRound)
		{
			A[0] ^= KeccakRoundConstants[indexRound];
		}

		private void KeccakAbsorb(byte[] byteState, byte[] data, int dataInBytes)
		{
			KeccakPermutationAfterXor(byteState, data, dataInBytes);
		}

		private void KeccakExtract1024bits(byte[] byteState, byte[] data)
		{
			Array.Copy(byteState, 0, data, 0, 128);
		}

		private void KeccakExtract(byte[] byteState, byte[] data, int laneCount)
		{
			Array.Copy(byteState, 0, data, 0, laneCount * 8);
		}

		public virtual IMemoable Copy()
		{
			return new KeccakDigest(this);
		}

		public virtual void Reset(IMemoable other)
		{
			KeccakDigest source = (KeccakDigest)other;
			CopyIn(source);
		}
	}
