	public class RipeMD256Digest : GeneralDigest
	{
		private const int DigestLength = 32;

		private int H0;

		private int H1;

		private int H2;

		private int H3;

		private int H4;

		private int H5;

		private int H6;

		private int H7;

		private int[] X = new int[16];

		private int xOff;

		public override string AlgorithmName => "RIPEMD256";

		public RipeMD256Digest()
		{
			Reset();
		}

		public RipeMD256Digest(RipeMD256Digest t)
			: base(t)
		{
			CopyIn(t);
		}

		public override int GetDigestSize()
		{
			return 32;
		}

		private void CopyIn(RipeMD256Digest t)
		{
			CopyIn((GeneralDigest)t);
			H0 = t.H0;
			H1 = t.H1;
			H2 = t.H2;
			H3 = t.H3;
			H4 = t.H4;
			H5 = t.H5;
			H6 = t.H6;
			H7 = t.H7;
			Array.Copy(t.X, 0, X, 0, t.X.Length);
			xOff = t.xOff;
		}

		internal override void ProcessWord(byte[] input, int inOff)
		{
			X[xOff++] = (input[inOff] & 0xFF) | ((input[inOff + 1] & 0xFF) << 8) | ((input[inOff + 2] & 0xFF) << 16) | ((input[inOff + 3] & 0xFF) << 24);
			if (xOff == 16)
			{
				ProcessBlock();
			}
		}

		internal override void ProcessLength(long bitLength)
		{
			if (xOff > 14)
			{
