			}
			byteCount = 0L;
		}

		public IMemoable Copy()
		{
			return new TigerDigest(this);
		}

		public void Reset(IMemoable other)
		{
			TigerDigest tigerDigest = (TigerDigest)other;
			a = tigerDigest.a;
			b = tigerDigest.b;
			c = tigerDigest.c;
			Array.Copy(tigerDigest.x, 0, x, 0, tigerDigest.x.Length);
