				uint num21 = Pack.LE_To_UInt32(key, 0);
				array[0][0] = num21;
				uint num22 = Pack.LE_To_UInt32(key, 4);
				array[0][1] = num22;
				uint num23 = Pack.LE_To_UInt32(key, 8);
				array[0][2] = num23;
				uint num24 = Pack.LE_To_UInt32(key, 12);
				array[0][3] = num24;
				for (int l = 1; l <= 10; l++)
				{
					uint num25 = SubWord(Shift(num24, 8)) ^ rcon[l - 1];
					num21 ^= num25;
					array[l][0] = num21;
					num22 ^= num21;
					array[l][1] = num22;
					num23 ^= num22;
					array[l][2] = num23;
					num24 ^= num23;
					array[l][3] = num24;
				}
				break;
			}
			case 6:
			{
				uint num13 = Pack.LE_To_UInt32(key, 0);
				array[0][0] = num13;
				uint num14 = Pack.LE_To_UInt32(key, 4);
				array[0][1] = num14;
				uint num15 = Pack.LE_To_UInt32(key, 8);
				array[0][2] = num15;
				uint num16 = Pack.LE_To_UInt32(key, 12);
				array[0][3] = num16;
				uint num17 = Pack.LE_To_UInt32(key, 16);
				array[1][0] = num17;
				uint num18 = Pack.LE_To_UInt32(key, 20);
				array[1][1] = num18;
				uint num19 = 1u;
				uint num20 = SubWord(Shift(num18, 8)) ^ num19;
				num19 <<= 1;
				num13 ^= num20;
				array[1][2] = num13;
				num14 ^= num13;
				array[1][3] = num14;
				num15 ^= num14;
				array[2][0] = num15;
				num16 ^= num15;
				array[2][1] = num16;
				num17 ^= num16;
				array[2][2] = num17;
				num18 ^= num17;
				array[2][3] = num18;
				for (int k = 3; k < 12; k += 3)
				{
					num20 = SubWord(Shift(num18, 8)) ^ num19;
					num19 <<= 1;
					num13 ^= num20;
					array[k][0] = num13;
					num14 ^= num13;
					array[k][1] = num14;
					num15 ^= num14;
					array[k][2] = num15;
					num16 ^= num15;
					array[k][3] = num16;
					num17 ^= num16;
					array[k + 1][0] = num17;
					num18 ^= num17;
					array[k + 1][1] = num18;
					num20 = SubWord(Shift(num18, 8)) ^ num19;
					num19 <<= 1;
					num13 ^= num20;
					array[k + 1][2] = num13;
					num14 ^= num13;
					array[k + 1][3] = num14;
					num15 ^= num14;
					array[k + 2][0] = num15;
					num16 ^= num15;
					array[k + 2][1] = num16;
					num17 ^= num16;
					array[k + 2][2] = num17;
					num18 ^= num17;
					array[k + 2][3] = num18;
				}
				num20 = SubWord(Shift(num18, 8)) ^ num19;
				num13 ^= num20;
				array[12][0] = num13;
				num14 ^= num13;
				array[12][1] = num14;
				num15 ^= num14;
				array[12][2] = num15;
				num16 ^= num15;
				array[12][3] = num16;
				break;
