			Array.Copy(KS1, 0, S1, 0, SBOX_SK);
			Array.Copy(KS2, 0, S2, 0, SBOX_SK);
			Array.Copy(KS3, 0, S3, 0, SBOX_SK);
			Array.Copy(KP, 0, P, 0, P_SZ);
			int num = key.Length;
			int num2 = 0;
			for (int i = 0; i < P_SZ; i++)
			{
				uint num3 = 0u;
				for (int j = 0; j < 4; j++)
				{
					num3 = (num3 << 8) | key[num2++];
					if (num2 >= num)
