				_Kr[l * 4 + 1] = (int)(_workingKey[2] & 0x1F);
				_Kr[l * 4 + 2] = (int)(_workingKey[4] & 0x1F);
				_Kr[l * 4 + 3] = (int)(_workingKey[6] & 0x1F);
				_Km[l * 4] = _workingKey[7];
				_Km[l * 4 + 1] = _workingKey[5];
				_Km[l * 4 + 2] = _workingKey[3];
				_Km[l * 4 + 3] = _workingKey[1];
