					}
					else
					{
						array3[k] = array2[num4 - 28];
					}
				}
				for (int l = 28; l < 56; l++)
				{
					int num4 = l + totrot[j];
					if (num4 < 56)
					{
						array3[l] = array2[num4];
					}
					else
					{
						array3[l] = array2[num4 - 28];
					}
