			uint num3 = ((num >> 4) ^ num2) & 0xF0F0F0F;
			num2 ^= num3;
			num ^= num3 << 4;
			num3 = ((num >> 16) ^ num2) & 0xFFFF;
			num2 ^= num3;
			num ^= num3 << 16;
			num3 = ((num2 >> 2) ^ num) & 0x33333333;
			num ^= num3;
			num2 ^= num3 << 2;
			num3 = ((num2 >> 8) ^ num) & 0xFF00FF;
			num ^= num3;
			num2 ^= num3 << 8;
			num2 = (num2 << 1) | (num2 >> 31);
			num3 = (num ^ num2) & 0xAAAAAAAAu;
			num ^= num3;
			num2 ^= num3;
			num = (num << 1) | (num >> 31);
			for (int i = 0; i < 8; i++)
			{
