				{
					long num5 = num2;
					num2 = num ^ F(wKey[2 * num4], wKey[2 * num4 + 1], num2);
					num = num5;
				}
			}
			longToBytes(outBuf, outOff, num2);
			longToBytes(outBuf, outOff + 8, num);
			return 16;
		}

