					num3 = extractW0(num);
					num4 = extractW1(num);
				}
				else
				{
					num2 = rotateLeft8(num2);
					num5 = extractW0(num2);
					num6 = extractW1(num2);
				}
			}
			return array;
		}

		private int extractW1(long lVal)
		{
			return (int)lVal;
		}

		private int extractW0(long lVal)
		{
			return (int)(lVal >> 32);
		}

		private long rotateLeft8(long x)
		{
			return (x << 8) | (x >>> 56);
		}

		private long rotateRight8(long x)
		{
			return (x >>> 8) | (x << 56);
		}

		private long bytesToLong(byte[] src, int srcOff)
		{
			long num = 0L;
			for (int i = 0; i <= 7; i++)
			{
