			}
		}

		private int G(int x)
		{
			return (int)(SS0[x & 0xFF] ^ SS1[(x >> 8) & 0xFF] ^ SS2[(x >> 16) & 0xFF] ^ SS3[(x >> 24) & 0xFF]);
		}

		private long F(int ki0, int ki1, long r)
		{
