	public abstract class SerpentEngineBase : IBlockCipher
	{
		protected static readonly int BlockSize = 16;

		internal const int ROUNDS = 32;

		internal const int PHI = -1640531527;

		protected bool encrypting;

		protected int[] wKey;

		protected int X0;

		protected int X1;

		protected int X2;

		protected int X3;

		public virtual string AlgorithmName => "Serpent";

		public virtual bool IsPartialBlockOkay => false;

		public virtual void Init(bool encrypting, ICipherParameters parameters)
		{
			if (!(parameters is KeyParameter))
			{
				throw new ArgumentException("invalid parameter passed to " + AlgorithmName + " init - " + Platform.GetTypeName(parameters));
			}
			this.encrypting = encrypting;
			wKey = MakeWorkingKey(((KeyParameter)parameters).GetKey());
		}

		public virtual int GetBlockSize()
		{
			return BlockSize;
		}

		public int ProcessBlock(byte[] input, int inOff, byte[] output, int outOff)
		{
			if (wKey == null)
			{
				throw new InvalidOperationException(AlgorithmName + " not initialised");
			}
			Check.DataLength(input, inOff, BlockSize, "input buffer too short");
			Check.OutputLength(output, outOff, BlockSize, "output buffer too short");
			if (encrypting)
			{
				EncryptBlock(input, inOff, output, outOff);
			}
			else
			{
				DecryptBlock(input, inOff, output, outOff);
			}
			return BlockSize;
		}

		public virtual void Reset()
		{
		}

		protected static int RotateLeft(int x, int bits)
		{
			return (x << bits) | (x >>> 32 - bits);
		}

		private static int RotateRight(int x, int bits)
		{
			return (x >>> bits) | (x << 32 - bits);
		}

		protected void Sb0(int a, int b, int c, int d)
		{
			int num = a ^ d;
			int num2 = c ^ num;
			int num3 = b ^ num2;
			X3 = (a & d) ^ num3;
			int num4 = a ^ (b & num);
			X2 = num3 ^ (c | num4);
			int num5 = X3 & (num2 ^ num4);
			X1 = ~num2 ^ num5;
			X0 = num5 ^ ~num4;
		}

		protected void Ib0(int a, int b, int c, int d)
		{
			int num = ~a;
			int num2 = a ^ b;
			int num3 = d ^ (num | num2);
			int num4 = c ^ num3;
			X2 = num2 ^ num4;
			int num5 = num ^ (d & num2);
			X1 = num3 ^ (X2 & num5);
			X3 = (a & num3) ^ (num4 | X1);
			X0 = X3 ^ (num4 ^ num5);
		}

		protected void Sb1(int a, int b, int c, int d)
		{
			int num = b ^ ~a;
			int num2 = c ^ (a | num);
			X2 = d ^ num2;
			int num3 = b ^ (d | num);
			int num4 = num ^ X2;
			X3 = num4 ^ (num2 & num3);
			int num5 = num2 ^ num3;
			X1 = X3 ^ num5;
			X0 = num2 ^ (num4 & num5);
		}

		protected void Ib1(int a, int b, int c, int d)
		{
			int num = b ^ d;
			int num2 = a ^ (b & num);
			int num3 = num ^ num2;
			X3 = c ^ num3;
			int num4 = b ^ (num & num2);
			int num5 = X3 | num4;
			X1 = num2 ^ num5;
			int num6 = ~X1;
			int num7 = X3 ^ num4;
			X0 = num6 ^ num7;
			X2 = num3 ^ (num6 | num7);
		}

		protected void Sb2(int a, int b, int c, int d)
		{
			int num = ~a;
			int num2 = b ^ d;
			int num3 = c & num;
			X0 = num2 ^ num3;
			int num4 = c ^ num;
			int num5 = c ^ X0;
			int num6 = b & num5;
			X3 = num4 ^ num6;
			X2 = a ^ ((d | num6) & (X0 | num4));
			X1 = num2 ^ X3 ^ (X2 ^ (d | num));
