			int num3 = a ^ c;
			int num4 = c ^ num;
			int num5 = b & num4;
			X0 = num3 ^ num5;
			int num6 = a | num2;
			int num7 = d ^ num6;
			int num8 = num3 | num7;
			X3 = num ^ num8;
