			int num5 = num & num3;
			int num6 = num2 | num5;
			X2 = num4 ^ num6;
			int num7 = b ^ num3;
			int num8 = num6 ^ num7;
			int num9 = num4 & num8;
			X0 = num ^ num9;
			int num10 = X2 & X0;
			X1 = num8 ^ num10;
			X3 = (b | d) ^ (num4 ^ num10);
