			int num3 = b & num2;
			int num4 = a ^ num3;
			int num5 = c ^ num4;
			int num6 = d | num4;
			X0 = num2 ^ num6;
			int num7 = num2 | num6;
			int num8 = d ^ num7;
			X2 = num5 ^ num8;
			int num9 = num ^ num8;
			int num10 = X0 & num9;
			X3 = num4 ^ num10;
			X1 = X3 ^ (X0 ^ num9);
