			int num4 = b | num3;
			X3 = num ^ num4;
			int num5 = ~b;
			int num6 = num | num5;
			X0 = num3 ^ num6;
			int num7 = a & X0;
			int num8 = num ^ num5;
			int num9 = num4 & num8;
			X2 = num7 ^ num9;
			X1 = a ^ num3 ^ (num8 & X2);
