			int num2 = a & num;
			int num3 = b ^ num2;
			int num4 = a & num3;
			int num5 = c ^ num4;
			X1 = d ^ num5;
			int num6 = ~a;
			int num7 = num5 & X1;
			X3 = num3 ^ num7;
			int num8 = X1 | num6;
			int num9 = d ^ num8;
			X0 = X3 ^ num9;
			X2 = (num3 & num9) ^ (X1 ^ num6);
