			{
				key0[i] = key[i * 4 % 10] & 0xFF;
				key1[i] = key[(i * 4 + 1) % 10] & 0xFF;
				key2[i] = key[(i * 4 + 2) % 10] & 0xFF;
				key3[i] = key[(i * 4 + 3) % 10] & 0xFF;
