			}
			cipher.ProcessBlock(buf, 0, mac, 0);
			Array.Copy(mac, 0, outBytes, outOff, macSize);
			Reset();
			return macSize;
		}

		public void Reset()
		{
			Array.Clear(buf, 0, buf.Length);
			bufOff = 0;
			cipher.Reset();
		}
