			desEngine.Init(forEncryption: false, lastKey2);
			desEngine.ProcessBlock(mac, 0, mac, 0);
			desEngine.Init(forEncryption: true, lastKey3);
			desEngine.ProcessBlock(mac, 0, mac, 0);
			Array.Copy(mac, 0, output, outOff, macSize);
			Reset();
			return macSize;
		}

		public void Reset()
		{
			Array.Clear(buf, 0, buf.Length);
			bufOff = 0;
			cipher.Reset();
		}
	}
