			{
				mac.BlockUpdate(bufBlock, 0, num - macSize);
				cipher.ProcessBlock(bufBlock, 0, array, 0);
				Array.Copy(array, 0, outBytes, outOff, num - macSize);
			}
			CalculateMac();
