			BigInteger d = eCPrivateKeyParameters.D;
			BigInteger d2 = ((ECPrivateKeyParameters)asymmetricCipherKeyPair.Private).D;
			bigInteger3 = d2.Subtract(bigInteger2.Multiply(d)).Mod(n);
