			if (((array[0] & 0xC0) ^ 0x40) != 0)
			{
				throw new InvalidCipherTextException("malformed signature");
			}
			if (((array[array.Length - 1] & 0xF) ^ 0xC) != 0)
			{
				throw new InvalidCipherTextException("malformed signature");
			}
