	public class TlsDeflateCompression : TlsCompression
	{
		protected class DeflateOutputStream : ZOutputStream
		{
			public DeflateOutputStream(Stream output, ZStream z, bool compress)
				: base(output, z)
			{
				base.compress = compress;
				FlushMode = 2;
			}

			public override void Flush()
			{
			}
		}

		public const int LEVEL_NONE = 0;

		public const int LEVEL_FASTEST = 1;

		public const int LEVEL_SMALLEST = 9;

		public const int LEVEL_DEFAULT = -1;

		protected readonly ZStream zIn;

		protected readonly ZStream zOut;

		public TlsDeflateCompression()
			: this(-1)
		{
		}

		public TlsDeflateCompression(int level)
		{
			zIn = new ZStream();
			zIn.inflateInit();
			zOut = new ZStream();
			zOut.deflateInit(level);
		}

		public virtual Stream Compress(Stream output)
		{
			return new DeflateOutputStream(output, zOut, compress: true);
		}

		public virtual Stream Decompress(Stream output)
		{
			return new DeflateOutputStream(output, zIn, compress: false);
		}
	}
	public class TlsDheKeyExchange : TlsDHKeyExchange
	{
		protected TlsSignerCredentials mServerCredentials;

		public TlsDheKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, DHParameters dhParameters)
			: base(keyExchange, supportedSignatureAlgorithms, dhParameters)
		{
		}

		public override void ProcessServerCredentials(TlsCredentials serverCredentials)
		{
			if (!(serverCredentials is TlsSignerCredentials))
			{
				throw new TlsFatalAlert(80);
			}
			ProcessServerCertificate(serverCredentials.Certificate);
			mServerCredentials = (TlsSignerCredentials)serverCredentials;
		}

		public override byte[] GenerateServerKeyExchange()
		{
			if (mDHParameters == null)
			{
				throw new TlsFatalAlert(80);
			}
			DigestInputBuffer digestInputBuffer = new DigestInputBuffer();
			mDHAgreePrivateKey = TlsDHUtilities.GenerateEphemeralServerKeyExchange(mContext.SecureRandom, mDHParameters, digestInputBuffer);
			SignatureAndHashAlgorithm signatureAndHashAlgorithm = TlsUtilities.GetSignatureAndHashAlgorithm(mContext, mServerCredentials);
			IDigest digest = TlsUtilities.CreateHash(signatureAndHashAlgorithm);
			SecurityParameters securityParameters = mContext.SecurityParameters;
			digest.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
			digest.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
			digestInputBuffer.UpdateDigest(digest);
			byte[] hash = DigestUtilities.DoFinal(digest);
			byte[] signature = mServerCredentials.GenerateCertificateSignature(hash);
			DigitallySigned digitallySigned = new DigitallySigned(signatureAndHashAlgorithm, signature);
			digitallySigned.Encode(digestInputBuffer);
			return digestInputBuffer.ToArray();
		}

		public override void ProcessServerKeyExchange(Stream input)
		{
			SecurityParameters securityParameters = mContext.SecurityParameters;
			SignerInputBuffer signerInputBuffer = new SignerInputBuffer();
			Stream input2 = new TeeInputStream(input, signerInputBuffer);
			ServerDHParams serverDHParams = ServerDHParams.Parse(input2);
			DigitallySigned digitallySigned = ParseSignature(input);
			ISigner signer = InitVerifyer(mTlsSigner, digitallySigned.Algorithm, securityParameters);
			signerInputBuffer.UpdateSigner(signer);
			if (!signer.VerifySignature(digitallySigned.Signature))
			{
				throw new TlsFatalAlert(51);
			}
			mDHAgreePublicKey = TlsDHUtilities.ValidateDHPublicKey(serverDHParams.PublicKey);
			mDHParameters = ValidateDHParameters(mDHAgreePublicKey.Parameters);
		}

		protected virtual ISigner InitVerifyer(TlsSigner tlsSigner, SignatureAndHashAlgorithm algorithm, SecurityParameters securityParameters)
		{
			ISigner signer = tlsSigner.CreateVerifyer(algorithm, mServerPublicKey);
			signer.BlockUpdate(securityParameters.clientRandom, 0, securityParameters.clientRandom.Length);
			signer.BlockUpdate(securityParameters.serverRandom, 0, securityParameters.serverRandom.Length);
			return signer;
		}
	}
	public class TlsDHKeyExchange : AbstractTlsKeyExchange
	{
		protected TlsSigner mTlsSigner;

		protected DHParameters mDHParameters;

		protected AsymmetricKeyParameter mServerPublicKey;

		protected TlsAgreementCredentials mAgreementCredentials;

		protected DHPrivateKeyParameters mDHAgreePrivateKey;

		protected DHPublicKeyParameters mDHAgreePublicKey;

		public override bool RequiresServerKeyExchange
		{
			get
			{
				switch (mKeyExchange)
				{
				case 3:
				case 5:
				case 11:
					return true;
				default:
					return false;
				}
			}
		}

		protected virtual int MinimumPrimeBits => 1024;

		public TlsDHKeyExchange(int keyExchange, IList supportedSignatureAlgorithms, DHParameters dhParameters)
			: base(keyExchange, supportedSignatureAlgorithms)
		{
			switch (keyExchange)
			{
			case 7:
			case 9:
				mTlsSigner = null;
				break;
			case 5:
				mTlsSigner = new TlsRsaSigner();
				break;
			case 3:
				mTlsSigner = new TlsDssSigner();
				break;
			default:
				throw new InvalidOperationException("unsupported key exchange algorithm");
			}
			mDHParameters = dhParameters;
		}

		public override void Init(TlsContext context)
		{
			base.Init(context);
			if (mTlsSigner != null)
			{
				mTlsSigner.Init(context);
			}
		}

		public override void SkipServerCredentials()
		{
			throw new TlsFatalAlert(10);
		}

		public override void ProcessServerCertificate(Certificate serverCertificate)
		{
			if (serverCertificate.IsEmpty)
			{
				throw new TlsFatalAlert(42);
			}
			X509CertificateStructure certificateAt = serverCertificate.GetCertificateAt(0);
			SubjectPublicKeyInfo subjectPublicKeyInfo = certificateAt.SubjectPublicKeyInfo;
			try
			{
				mServerPublicKey = PublicKeyFactory.CreateKey(subjectPublicKeyInfo);
			}
			catch (Exception alertCause)
			{
				throw new TlsFatalAlert(43, alertCause);
			}
			if (mTlsSigner == null)
			{
				try
				{
					mDHAgreePublicKey = TlsDHUtilities.ValidateDHPublicKey((DHPublicKeyParameters)mServerPublicKey);
					mDHParameters = ValidateDHParameters(mDHAgreePublicKey.Parameters);
				}
				catch (InvalidCastException alertCause2)
				{
					throw new TlsFatalAlert(46, alertCause2);
				}
				TlsUtilities.ValidateKeyUsage(certificateAt, 8);
			}
			else
			{
				if (!mTlsSigner.IsValidPublicKey(mServerPublicKey))
				{
					throw new TlsFatalAlert(46);
				}
				TlsUtilities.ValidateKeyUsage(certificateAt, 128);
			}
			base.ProcessServerCertificate(serverCertificate);
		}

		public override void ValidateCertificateRequest(CertificateRequest certificateRequest)
		{
			byte[] certificateTypes = certificateRequest.CertificateTypes;
			for (int i = 0; i < certificateTypes.Length; i++)
			{
				switch (certificateTypes[i])
				{
				case 1:
				case 2:
				case 3:
				case 4:
				case 64:
					continue;
				}
				throw new TlsFatalAlert(47);
			}
		}

		public override void ProcessClientCredentials(TlsCredentials clientCredentials)
		{
			if (clientCredentials is TlsAgreementCredentials)
			{
				mAgreementCredentials = (TlsAgreementCredentials)clientCredentials;
			}
			else if (!(clientCredentials is TlsSignerCredentials))
			{
				throw new TlsFatalAlert(80);
			}
		}

		public override void GenerateClientKeyExchange(Stream output)
		{
			if (mAgreementCredentials == null)
			{
				mDHAgreePrivateKey = TlsDHUtilities.GenerateEphemeralClientKeyExchange(mContext.SecureRandom, mDHParameters, output);
			}
		}

		public override void ProcessClientCertificate(Certificate clientCertificate)
		{
		}

		public override void ProcessClientKeyExchange(Stream input)
		{
			if (mDHAgreePublicKey == null)
			{
				BigInteger y = TlsDHUtilities.ReadDHParameter(input);
				mDHAgreePublicKey = TlsDHUtilities.ValidateDHPublicKey(new DHPublicKeyParameters(y, mDHParameters));
			}
		}

		public override byte[] GeneratePremasterSecret()
		{
			if (mAgreementCredentials != null)
			{
				return mAgreementCredentials.GenerateAgreement(mDHAgreePublicKey);
			}
			if (mDHAgreePrivateKey != null)
			{
				return TlsDHUtilities.CalculateDHBasicAgreement(mDHAgreePublicKey, mDHAgreePrivateKey);
			}
			throw new TlsFatalAlert(80);
		}

		protected virtual DHParameters ValidateDHParameters(DHParameters parameters)
		{
			if (parameters.P.BitLength < MinimumPrimeBits)
			{
				throw new TlsFatalAlert(71);
			}
			return TlsDHUtilities.ValidateDHParameters(parameters);
		}
	}
	public abstract class TlsDHUtilities
	{
		internal static readonly BigInteger Two = BigInteger.Two;

		private static readonly string draft_ffdhe2432_p = "";

		internal static readonly DHParameters draft_ffdhe2432 = FromSafeP(draft_ffdhe2432_p);

		private static readonly string draft_ffdhe3072_p = "";

		internal static readonly DHParameters draft_ffdhe3072 = FromSafeP(draft_ffdhe3072_p);

		private static readonly string draft_ffdhe4096_p = "";

		internal static readonly DHParameters draft_ffdhe4096 = FromSafeP(draft_ffdhe4096_p);

		private static readonly string draft_ffdhe6144_p = "";

		internal static readonly DHParameters draft_ffdhe6144 = FromSafeP(draft_ffdhe6144_p);

		private static readonly string draft_ffdhe8192_p = "";

		internal static readonly DHParameters draft_ffdhe8192 = FromSafeP(draft_ffdhe8192_p);

		private static BigInteger FromHex(string hex)
		{
			return new BigInteger(1, Hex.Decode(hex));
		}

		private static DHParameters FromSafeP(string hexP)
		{
			BigInteger bigInteger = FromHex(hexP);
			BigInteger q = bigInteger.ShiftRight(1);
			return new DHParameters(bigInteger, Two, q);
		}

		public static void AddNegotiatedDheGroupsClientExtension(IDictionary extensions, byte[] dheGroups)
		{
			extensions[ExtensionType.negotiated_ff_dhe_groups] = CreateNegotiatedDheGroupsClientExtension(dheGroups);
		}

		public static void AddNegotiatedDheGroupsServerExtension(IDictionary extensions, byte dheGroup)
		{
			extensions[ExtensionType.negotiated_ff_dhe_groups] = CreateNegotiatedDheGroupsServerExtension(dheGroup);
		}

		public static byte[] GetNegotiatedDheGroupsClientExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, ExtensionType.negotiated_ff_dhe_groups);
			return (extensionData != null) ? ReadNegotiatedDheGroupsClientExtension(extensionData) : null;
		}

		public static short GetNegotiatedDheGroupsServerExtension(IDictionary extensions)
		{
			byte[] extensionData = TlsUtilities.GetExtensionData(extensions, ExtensionType.negotiated_ff_dhe_groups);
			return (short)((extensionData != null) ? ReadNegotiatedDheGroupsServerExtension(extensionData) : (-1));
		}

		public static byte[] CreateNegotiatedDheGroupsClientExtension(byte[] dheGroups)
		{
			if (dheGroups == null || dheGroups.Length < 1 || dheGroups.Length > 255)
			{
				throw new TlsFatalAlert(80);
			}
			return TlsUtilities.EncodeUint8ArrayWithUint8Length(dheGroups);
		}

		public static byte[] CreateNegotiatedDheGroupsServerExtension(byte dheGroup)
		{
			return new byte[1] { dheGroup };
		}

		public static byte[] ReadNegotiatedDheGroupsClientExtension(byte[] extensionData)
		{
			if (extensionData == null)
			{
				throw new ArgumentNullException("extensionData");
			}
			MemoryStream memoryStream = new MemoryStream(extensionData, writable: false);
			byte b = TlsUtilities.ReadUint8(memoryStream);
			if (b < 1)
			{
				throw new TlsFatalAlert(50);
			}
			byte[] result = TlsUtilities.ReadUint8Array(b, memoryStream);
			TlsProtocol.AssertEmpty(memoryStream);
			return result;
		}

		public static byte ReadNegotiatedDheGroupsServerExtension(byte[] extensionData)
		{
			if (extensionData == null)
			{
				throw new ArgumentNullException("extensionData");
			}
			if (extensionData.Length != 1)
			{
				throw new TlsFatalAlert(50);
			}
			return extensionData[0];
		}

		public static DHParameters GetParametersForDHEGroup(short dheGroup)
		{
			return dheGroup switch
			{
				0 => draft_ffdhe2432, 
				1 => draft_ffdhe3072, 
				2 => draft_ffdhe4096, 
				3 => draft_ffdhe6144, 
				4 => draft_ffdhe8192, 
				_ => null, 
			};
		}

		public static bool ContainsDheCipherSuites(int[] cipherSuites)
		{
			for (int i = 0; i < cipherSuites.Length; i++)
			{
				if (IsDheCipherSuite(cipherSuites[i]))
				{
					return true;
				}
			}
			return false;
		}

