	public class TlsMac
	{
		protected readonly TlsContext context;

		protected readonly byte[] secret;

		protected readonly IMac mac;

		protected readonly int digestBlockSize;

		protected readonly int digestOverhead;

		protected readonly int macLength;

		public virtual byte[] MacSecret => secret;

		public virtual int Size => macLength;

		public TlsMac(TlsContext context, IDigest digest, byte[] key, int keyOff, int keyLen)
		{
			this.context = context;
			KeyParameter keyParameter = new KeyParameter(key, keyOff, keyLen);
			secret = Arrays.Clone(keyParameter.GetKey());
			if (digest is LongDigest)
			{
				digestBlockSize = 128;
				digestOverhead = 16;
			}
			else
			{
				digestBlockSize = 64;
				digestOverhead = 8;
			}
			if (TlsUtilities.IsSsl(context))
			{
				mac = new Ssl3Mac(digest);
				if (digest.GetDigestSize() == 20)
				{
					digestOverhead = 4;
				}
			}
			else
			{
				mac = new HMac(digest);
			}
			mac.Init(keyParameter);
			macLength = mac.GetMacSize();
			if (context.SecurityParameters.truncatedHMac)
			{
				macLength = System.Math.Min(macLength, 10);
			}
		}

		public virtual byte[] CalculateMac(long seqNo, byte type, byte[] message, int offset, int length)
		{
			ProtocolVersion serverVersion = context.ServerVersion;
			bool isSsl = serverVersion.IsSsl;
			byte[] array = new byte[(!isSsl) ? 13 : 11];
			TlsUtilities.WriteUint64(seqNo, array, 0);
			TlsUtilities.WriteUint8(type, array, 8);
			if (!isSsl)
			{
				TlsUtilities.WriteVersion(serverVersion, array, 9);
			}
			TlsUtilities.WriteUint16(length, array, array.Length - 2);
			mac.BlockUpdate(array, 0, array.Length);
			mac.BlockUpdate(message, offset, length);
			return Truncate(MacUtilities.DoFinal(mac));
		}

		public virtual byte[] CalculateMacConstantTime(long seqNo, byte type, byte[] message, int offset, int length, int fullLength, byte[] dummyData)
		{
			byte[] result = CalculateMac(seqNo, type, message, offset, length);
			int num = ((!TlsUtilities.IsSsl(context)) ? 13 : 11);
			int num2 = GetDigestBlockCount(num + fullLength) - GetDigestBlockCount(num + length);
			while (--num2 >= 0)
			{
				mac.BlockUpdate(dummyData, 0, digestBlockSize);
			}
			mac.Update(dummyData[0]);
			mac.Reset();
			return result;
		}

		protected virtual int GetDigestBlockCount(int inputLength)
		{
			return (inputLength + digestOverhead) / digestBlockSize;
		}

		protected virtual byte[] Truncate(byte[] bs)
		{
			if (bs.Length <= macLength)
			{
				return bs;
			}
			return Arrays.CopyOf(bs, macLength);
		}
	}
	public class TlsNullCipher : TlsCipher
	{
		protected readonly TlsContext context;

		protected readonly TlsMac writeMac;

		protected readonly TlsMac readMac;

		public TlsNullCipher(TlsContext context)
		{
			this.context = context;
			writeMac = null;
			readMac = null;
		}

		public TlsNullCipher(TlsContext context, IDigest clientWriteDigest, IDigest serverWriteDigest)
		{
			if (clientWriteDigest == null != (serverWriteDigest == null))
			{
				throw new TlsFatalAlert(80);
			}
			this.context = context;
			TlsMac tlsMac = null;
			TlsMac tlsMac2 = null;
			if (clientWriteDigest != null)
			{
				int num = clientWriteDigest.GetDigestSize() + serverWriteDigest.GetDigestSize();
				byte[] key = TlsUtilities.CalculateKeyBlock(context, num);
				int num2 = 0;
				tlsMac = new TlsMac(context, clientWriteDigest, key, num2, clientWriteDigest.GetDigestSize());
				num2 += clientWriteDigest.GetDigestSize();
				tlsMac2 = new TlsMac(context, serverWriteDigest, key, num2, serverWriteDigest.GetDigestSize());
				num2 += serverWriteDigest.GetDigestSize();
				if (num2 != num)
				{
					throw new TlsFatalAlert(80);
				}
			}
			if (context.IsServer)
			{
				writeMac = tlsMac2;
				readMac = tlsMac;
			}
			else
			{
				writeMac = tlsMac;
				readMac = tlsMac2;
			}
		}

		public virtual int GetPlaintextLimit(int ciphertextLimit)
		{
			int num = ciphertextLimit;
			if (writeMac != null)
			{
				num -= writeMac.Size;
			}
			return num;
		}

		public virtual byte[] EncodePlaintext(long seqNo, byte type, byte[] plaintext, int offset, int len)
		{
			if (writeMac == null)
			{
				return Arrays.CopyOfRange(plaintext, offset, offset + len);
			}
			byte[] array = writeMac.CalculateMac(seqNo, type, plaintext, offset, len);
			byte[] array2 = new byte[len + array.Length];
			Array.Copy(plaintext, offset, array2, 0, len);
			Array.Copy(array, 0, array2, len, array.Length);
			return array2;
		}

		public virtual byte[] DecodeCiphertext(long seqNo, byte type, byte[] ciphertext, int offset, int len)
		{
			if (readMac == null)
			{
				return Arrays.CopyOfRange(ciphertext, offset, offset + len);
			}
			int size = readMac.Size;
			if (len < size)
			{
				throw new TlsFatalAlert(50);
			}
			int num = len - size;
			byte[] a = Arrays.CopyOfRange(ciphertext, offset + num, offset + len);
			byte[] b = readMac.CalculateMac(seqNo, type, ciphertext, offset, num);
			if (!Arrays.ConstantTimeAreEqual(a, b))
			{
				throw new TlsFatalAlert(20);
			}
			return Arrays.CopyOfRange(ciphertext, offset, offset + num);
		}
	}
