		{
			byte[] array = new byte[5] { 2, 3, 4, 5, 6 };
			byte[] array2 = new byte[3] { 1, 2, 3 };
			IList list = Platform.CreateArrayList();
			for (int i = 0; i < array2.Length; i++)
			{
				for (int j = 0; j < array.Length; j++)
				{
