		public int BitCount
		{
			get
			{
				if (nBits == -1)
				{
					if (sign < 0)
					{
						nBits = Not().BitCount;
					}
					else
					{
						int num = 0;
						for (int i = 0; i < magnitude.Length; i++)
						{
							num += BitCnt(magnitude[i]);
						}
						nBits = num;
					}
				}
				return nBits;
			}
		}

		public int BitLength
		{
			get
			{
				if (nBitLength == -1)
				{
					nBitLength = ((sign != 0) ? CalcBitLength(sign, 0, magnitude) : 0);
				}
				return nBitLength;
			}
		}

		public int IntValue
		{
			get
			{
				if (sign == 0)
				{
					return 0;
				}
				int num = magnitude.Length;
				int num2 = magnitude[num - 1];
				return (sign >= 0) ? num2 : (-num2);
			}
		}

		public long LongValue
		{
			get
			{
				if (sign == 0)
				{
					return 0L;
				}
				int num = magnitude.Length;
				long num2 = magnitude[num - 1] & 0xFFFFFFFFu;
				if (num > 1)
				{
					num2 |= (magnitude[num - 2] & 0xFFFFFFFFu) << 32;
				}
				return (sign >= 0) ? num2 : (-num2);
			}
		}

