			do
			{
				long num4 = (x[--num] & 0xFFFFFFFFu) - (y[--num2] & 0xFFFFFFFFu) + num3;
				x[num] = (int)num4;
				num3 = (int)(num4 >> 63);
			}
			while (num2 > yStart);
			if (num3 != 0)
			{
				while (--x[--num] == -1)
				{
				}
			}
			return x;
		}

		public BigInteger Subtract(BigInteger n)
		{
			if (n.sign == 0)
			{
				return this;
			}
			if (sign == 0)
			{
				return n.Negate();
			}
			if (sign != n.sign)
			{
				return Add(n.Negate());
			}
			int num = CompareNoLeadingZeroes(0, magnitude, 0, n.magnitude);
			if (num == 0)
			{
				return Zero;
			}
			BigInteger bigInteger;
			BigInteger bigInteger2;
			if (num < 0)
			{
				bigInteger = n;
				bigInteger2 = this;
			}
			else
			{
				bigInteger = this;
				bigInteger2 = n;
			}
			return new BigInteger(sign * num, doSubBigLil(bigInteger.magnitude, bigInteger2.magnitude), checkMag: true);
		}

		private static int[] doSubBigLil(int[] bigMag, int[] lilMag)
		{
			int[] x = (int[])bigMag.Clone();
			return Subtract(0, x, 0, lilMag);
		}

		public byte[] ToByteArray()
		{
			return ToByteArray(unsigned: false);
		}

		public byte[] ToByteArrayUnsigned()
		{
			return ToByteArray(unsigned: true);
		}

		private byte[] ToByteArray(bool unsigned)
		{
			if (sign == 0)
			{
				return (!unsigned) ? new byte[1] : ZeroEncoding;
			}
			int num = ((!unsigned || sign <= 0) ? (BitLength + 1) : BitLength);
			int byteLength = GetByteLength(num);
			byte[] array = new byte[byteLength];
			int num2 = magnitude.Length;
			int num3 = array.Length;
			if (sign > 0)
			{
				while (num2 > 1)
				{
					uint num4 = (uint)magnitude[--num2];
					array[--num3] = (byte)num4;
					array[--num3] = (byte)(num4 >> 8);
					array[--num3] = (byte)(num4 >> 16);
					array[--num3] = (byte)(num4 >> 24);
				}
				uint num5;
				for (num5 = (uint)magnitude[0]; num5 > 255; num5 >>= 8)
				{
					array[--num3] = (byte)num5;
				}
				array[--num3] = (byte)num5;
			}
			else
			{
				bool flag = true;
				while (num2 > 1)
				{
					uint num6 = (uint)(~magnitude[--num2]);
					if (flag)
					{
						flag = ++num6 == 0;
					}
					array[--num3] = (byte)num6;
					array[--num3] = (byte)(num6 >> 8);
					array[--num3] = (byte)(num6 >> 16);
					array[--num3] = (byte)(num6 >> 24);
				}
				uint num7 = (uint)magnitude[0];
				if (flag)
				{
					num7--;
				}
				while (num7 > 255)
				{
					array[--num3] = (byte)(~num7);
					num7 >>= 8;
				}
				array[--num3] = (byte)(~num7);
				if (num3 > 0)
				{
					array[--num3] = byte.MaxValue;
				}
			}
			return array;
		}

		public override string ToString()
		{
			return ToString(10);
		}

		public string ToString(int radix)
		{
			switch (radix)
			{
			default:
				throw new FormatException("Only bases 2, 8, 10, 16 are allowed");
			case 2:
			case 8:
			case 10:
			case 16:
			{
				if (magnitude == null)
				{
					return "null";
				}
				if (sign == 0)
				{
					return "0";
				}
				int i;
				for (i = 0; i < magnitude.Length && magnitude[i] == 0; i++)
				{
				}
				if (i == magnitude.Length)
				{
					return "0";
				}
				StringBuilder stringBuilder = new StringBuilder();
				if (sign == -1)
				{
					stringBuilder.Append('-');
				}
				switch (radix)
				{
				case 2:
				{
					int num9 = i;
					stringBuilder.Append(Convert.ToString(magnitude[num9], 2));
					while (++num9 < magnitude.Length)
					{
						AppendZeroExtendedString(stringBuilder, Convert.ToString(magnitude[num9], 2), 32);
					}
					break;
				}
				case 8:
				{
					int num5 = 1073741823;
					BigInteger bigInteger3 = Abs();
					int num6 = bigInteger3.BitLength;
					IList list2 = Platform.CreateArrayList();
					while (num6 > 30)
					{
						list2.Add(Convert.ToString(bigInteger3.IntValue & num5, 8));
						bigInteger3 = bigInteger3.ShiftRight(30);
						num6 -= 30;
					}
					stringBuilder.Append(Convert.ToString(bigInteger3.IntValue, 8));
					for (int num7 = list2.Count - 1; num7 >= 0; num7--)
					{
						AppendZeroExtendedString(stringBuilder, (string)list2[num7], 10);
					}
					break;
				}
				case 16:
				{
					int num8 = i;
					stringBuilder.Append(Convert.ToString(magnitude[num8], 16));
					while (++num8 < magnitude.Length)
					{
						AppendZeroExtendedString(stringBuilder, Convert.ToString(magnitude[num8], 16), 8);
					}
					break;
				}
				case 10:
				{
					BigInteger bigInteger = Abs();
					if (bigInteger.BitLength < 64)
					{
						stringBuilder.Append(Convert.ToString(bigInteger.LongValue, radix));
						break;
					}
					long num = long.MaxValue / radix;
					long num2 = radix;
					int num3 = 1;
					while (num2 <= num)
					{
						num2 *= radix;
						num3++;
					}
					BigInteger bigInteger2 = ValueOf(num2);
					IList list = Platform.CreateArrayList();
					while (bigInteger.CompareTo(bigInteger2) >= 0)
					{
						BigInteger[] array = bigInteger.DivideAndRemainder(bigInteger2);
						list.Add(Convert.ToString(array[1].LongValue, radix));
						bigInteger = array[0];
					}
					stringBuilder.Append(Convert.ToString(bigInteger.LongValue, radix));
					for (int num4 = list.Count - 1; num4 >= 0; num4--)
					{
						AppendZeroExtendedString(stringBuilder, (string)list[num4], num3);
					}
					break;
				}
				}
				return stringBuilder.ToString();
			}
			}
		}

		private static void AppendZeroExtendedString(StringBuilder sb, string s, int minLength)
		{
			for (int i = s.Length; i < minLength; i++)
			{
				sb.Append('0');
			}
			sb.Append(s);
		}

		private static BigInteger CreateUValueOf(ulong value)
		{
			int num = (int)(value >> 32);
			int num2 = (int)value;
			if (num != 0)
			{
				return new BigInteger(1, new int[2] { num, num2 }, checkMag: false);
			}
			if (num2 != 0)
			{
				BigInteger bigInteger = new BigInteger(1, new int[1] { num2 }, checkMag: false);
				if ((num2 & -num2) == num2)
				{
					bigInteger.nBits = 1;
				}
				return bigInteger;
			}
			return Zero;
		}

		private static BigInteger CreateValueOf(long value)
		{
			if (value < 0)
			{
				if (value == long.MinValue)
				{
					return CreateValueOf(~value).Not();
				}
				return CreateValueOf(-value).Negate();
			}
			return CreateUValueOf((ulong)value);
		}

		public static BigInteger ValueOf(long value)
		{
			if (value >= 0 && value < SMALL_CONSTANTS.Length)
			{
				return SMALL_CONSTANTS[value];
			}
			return CreateValueOf(value);
		}

		public int GetLowestSetBit()
		{
			if (sign == 0)
			{
				return -1;
			}
			return GetLowestSetBitMaskFirst(-1);
		}

		private int GetLowestSetBitMaskFirst(int firstWordMask)
		{
			int num = magnitude.Length;
			int num2 = 0;
			uint num3 = (uint)(magnitude[--num] & firstWordMask);
			while (num3 == 0)
			{
				num3 = (uint)magnitude[--num];
				num2 += 32;
			}
			while ((num3 & 0xFF) == 0)
			{
				num3 >>= 8;
				num2 += 8;
			}
			while ((num3 & 1) == 0)
			{
				num3 >>= 1;
				num2++;
			}
			return num2;
		}

		public bool TestBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit position must not be negative");
			}
			if (sign < 0)
			{
				return !Not().TestBit(n);
			}
			int num = n / 32;
			if (num >= magnitude.Length)
			{
				return false;
			}
			int num2 = magnitude[magnitude.Length - 1 - num];
			return ((num2 >> n % 32) & 1) > 0;
		}

		public BigInteger Or(BigInteger value)
		{
			if (sign == 0)
			{
				return value;
			}
			if (value.sign == 0)
			{
				return this;
			}
			int[] array = ((sign <= 0) ? Add(One).magnitude : magnitude);
			int[] array2 = ((value.sign <= 0) ? value.Add(One).magnitude : value.magnitude);
			bool flag = sign < 0 || value.sign < 0;
			int num = System.Math.Max(array.Length, array2.Length);
			int[] array3 = new int[num];
			int num2 = array3.Length - array.Length;
			int num3 = array3.Length - array2.Length;
			for (int i = 0; i < array3.Length; i++)
			{
				int num4 = ((i >= num2) ? array[i - num2] : 0);
				int num5 = ((i >= num3) ? array2[i - num3] : 0);
				if (sign < 0)
				{
					num4 = ~num4;
				}
				if (value.sign < 0)
				{
					num5 = ~num5;
				}
				array3[i] = num4 | num5;
				if (flag)
				{
					array3[i] = ~array3[i];
				}
			}
			BigInteger bigInteger = new BigInteger(1, array3, checkMag: true);
			if (flag)
			{
				bigInteger = bigInteger.Not();
			}
			return bigInteger;
		}

		public BigInteger Xor(BigInteger value)
		{
			if (sign == 0)
			{
				return value;
			}
			if (value.sign == 0)
			{
				return this;
			}
			int[] array = ((sign <= 0) ? Add(One).magnitude : magnitude);
			int[] array2 = ((value.sign <= 0) ? value.Add(One).magnitude : value.magnitude);
			bool flag = (sign < 0 && value.sign >= 0) || (sign >= 0 && value.sign < 0);
			int num = System.Math.Max(array.Length, array2.Length);
			int[] array3 = new int[num];
			int num2 = array3.Length - array.Length;
			int num3 = array3.Length - array2.Length;
			for (int i = 0; i < array3.Length; i++)
			{
				int num4 = ((i >= num2) ? array[i - num2] : 0);
				int num5 = ((i >= num3) ? array2[i - num3] : 0);
				if (sign < 0)
				{
					num4 = ~num4;
				}
				if (value.sign < 0)
				{
					num5 = ~num5;
				}
				array3[i] = num4 ^ num5;
				if (flag)
				{
					array3[i] = ~array3[i];
				}
			}
			BigInteger bigInteger = new BigInteger(1, array3, checkMag: true);
			if (flag)
			{
				bigInteger = bigInteger.Not();
			}
			return bigInteger;
		}

		public BigInteger SetBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (TestBit(n))
			{
				return this;
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return Or(One.ShiftLeft(n));
		}

		public BigInteger ClearBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (!TestBit(n))
			{
				return this;
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return AndNot(One.ShiftLeft(n));
		}

		public BigInteger FlipBit(int n)
		{
			if (n < 0)
			{
				throw new ArithmeticException("Bit address less than zero");
			}
			if (sign > 0 && n < BitLength - 1)
			{
				return FlipExistingBit(n);
			}
			return Xor(One.ShiftLeft(n));
		}

		private BigInteger FlipExistingBit(int n)
		{
			int[] array = (int[])magnitude.Clone();
			array[array.Length - 1 - (n >> 5)] ^= 1 << n;
			return new BigInteger(sign, array, checkMag: false);
		}
	}
