			uint[] array2 = Nat256.Create();
			uint[] array3 = Nat256.Create();
			uint[] array4 = Nat256.Create();
			bool isOne = curve25519FieldElement3.IsOne;
			uint[] array5;
			uint[] array6;
			if (isOne)
			{
				array5 = curve25519FieldElement4.x;
				array6 = curve25519FieldElement5.x;
