			uint[] array11 = array3;
			SecP160R2Field.Square(array9, array11);
			uint[] array12 = Nat160.Create();
			SecP160R2Field.Multiply(array11, array9, array12);
			uint[] array13 = array3;
			SecP160R2Field.Multiply(array11, array7, array13);
			SecP160R2Field.Negate(array12, array12);
