			z[0] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[1];
				z[1] = (uint)num;
				num >>= 32;
			}
			num += (long)z[2] - 1L;
			z[2] = (uint)num;
			num >>= 32;
