			num += (long)z[3] - 1L;
			z[3] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[4];
				z[4] = (uint)num;
				num >>= 32;
				num += z[5];
				z[5] = (uint)num;
				num >>= 32;
			}
			num += (long)z[6] - 1L;
			z[6] = (uint)num;
			num >>= 32;
			num += (long)z[7] + 1L;
			z[7] = (uint)num;
		}

		private static void SubPInvFrom(uint[] z)
		{
			long num = (long)z[0] - 1L;
			z[0] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[1];
				z[1] = (uint)num;
				num >>= 32;
				num += z[2];
				z[2] = (uint)num;
				num >>= 32;
			}
			num += (long)z[3] + 1L;
			z[3] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[4];
				z[4] = (uint)num;
				num >>= 32;
				num += z[5];
				z[5] = (uint)num;
				num >>= 32;
			}
			num += (long)z[6] + 1L;
			z[6] = (uint)num;
			num >>= 32;
			num += (long)z[7] - 1L;
			z[7] = (uint)num;
