			4294967295u, 1u, 4294967295u, 4294967293u, 4294967295u, 1u, 4294967295u, 4294967293u, 4294967294u, 4294967295u,
			4294967295u, 4294967295u, 1u, 4294967294u, 4294967295u, 1u, 2u
