			num17 >>= 32;
			num17 += xx[9] + num3 - num5 + num13;
			z[9] = (uint)num17;
			num17 >>= 32;
			num17 += xx[10] + num3 + num4 - num14 + num15;
			z[10] = (uint)num17;
			num17 >>= 32;
			num17 += xx[11] + num4 + num5 - num15;
			z[11] = (uint)num17;
			num17 >>= 32;
			num17++;
			Reduce32((uint)num17, z);
