			if (x != 0)
			{
				long num2 = x;
				num += z[0] + num2;
				z[0] = (uint)num;
				num >>= 32;
				num += z[1] - num2;
				z[1] = (uint)num;
				num >>= 32;
				if (num != 0)
				{
					num += z[2];
					z[2] = (uint)num;
					num >>= 32;
				}
				num += z[3] + num2;
				z[3] = (uint)num;
				num >>= 32;
				num += z[4] + num2;
				z[4] = (uint)num;
				num >>= 32;
			}
			if ((num != 0 && Nat.IncAt(12, z, 5) != 0) || (z[11] == uint.MaxValue && Nat.Gte(12, z, P)))
