			z[0] = (uint)num;
			num >>= 32;
			num += (long)z[1] - 1L;
			z[1] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[2];
				z[2] = (uint)num;
				num >>= 32;
			}
			num += (long)z[3] + 1L;
			z[3] = (uint)num;
			num >>= 32;
			num += (long)z[4] + 1L;
			z[4] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				Nat.IncAt(12, z, 5);
			}
		}

		private static void SubPInvFrom(uint[] z)
		{
			long num = (long)z[0] - 1L;
			z[0] = (uint)num;
			num >>= 32;
			num += (long)z[1] + 1L;
			z[1] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				num += z[2];
				z[2] = (uint)num;
				num >>= 32;
			}
			num += (long)z[3] - 1L;
			z[3] = (uint)num;
			num >>= 32;
			num += (long)z[4] - 1L;
			z[4] = (uint)num;
			num >>= 32;
			if (num != 0)
			{
				Nat.DecAt(12, z, 5);
			}
		}
