			: this(m, k, 0, 0, a, b, order, cofactor)
		{
		}

		public F2mCurve(int m, int k1, int k2, int k3, BigInteger a, BigInteger b)
			: this(m, k1, k2, k3, a, b, null, null)
		{
		}

		public F2mCurve(int m, int k1, int k2, int k3, BigInteger a, BigInteger b, BigInteger order, BigInteger cofactor)
			: base(m, k1, k2, k3)
		{
			this.m = m;
			this.k1 = k1;
			this.k2 = k2;
			this.k3 = k3;
			m_order = order;
			m_cofactor = cofactor;
			m_infinity = new F2mPoint(this, null, null);
			if (k1 == 0)
			{
				throw new ArgumentException("k1 must be > 0");
			}
			if (k2 == 0)
			{
				if (k3 != 0)
				{
					throw new ArgumentException("k3 must be 0 if k2 == 0");
				}
			}
			else
			{
				if (k2 <= k1)
				{
					throw new ArgumentException("k2 must be > k1");
				}
				if (k3 <= k2)
				{
					throw new ArgumentException("k3 must be > k2");
				}
			}
			m_a = FromBigInteger(a);
			m_b = FromBigInteger(b);
			m_coord = 6;
		}

		protected F2mCurve(int m, int k1, int k2, int k3, ECFieldElement a, ECFieldElement b, BigInteger order, BigInteger cofactor)
			: base(m, k1, k2, k3)
		{
			this.m = m;
			this.k1 = k1;
			this.k2 = k2;
			this.k3 = k3;
			m_order = order;
			m_cofactor = cofactor;
			m_infinity = new F2mPoint(this, null, null);
			m_a = a;
			m_b = b;
			m_coord = 6;
		}

		protected override ECCurve CloneCurve()
		{
			return new F2mCurve(m, k1, k2, k3, m_a, m_b, m_order, m_cofactor);
		}

		public override bool SupportsCoordinateSystem(int coord)
		{
			if (coord == 0 || coord == 1 || coord == 6)
			{
				return true;
			}
			return false;
		}

		protected override ECMultiplier CreateDefaultMultiplier()
		{
			if (IsKoblitz)
			{
				return new WTauNafMultiplier();
			}
			return base.CreateDefaultMultiplier();
		}

		public override ECFieldElement FromBigInteger(BigInteger x)
		{
			return new F2mFieldElement(m, k1, k2, k3, x);
		}

		protected internal override ECPoint CreateRawPoint(ECFieldElement x, ECFieldElement y, bool withCompression)
		{
			return new F2mPoint(this, x, y, withCompression);
		}

		protected internal override ECPoint CreateRawPoint(ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
		{
			return new F2mPoint(this, x, y, zs, withCompression);
		}

		public bool IsTrinomial()
		{
			return k2 == 0 && k3 == 0;
		}
	}
	public abstract class ECFieldElement
	{
		public abstract string FieldName { get; }

		public abstract int FieldSize { get; }

		public virtual int BitLength => ToBigInteger().BitLength;

		public virtual bool IsOne => BitLength == 1;

		public virtual bool IsZero => 0 == ToBigInteger().SignValue;

		public abstract BigInteger ToBigInteger();

		public abstract ECFieldElement Add(ECFieldElement b);

		public abstract ECFieldElement AddOne();

		public abstract ECFieldElement Subtract(ECFieldElement b);

		public abstract ECFieldElement Multiply(ECFieldElement b);

		public abstract ECFieldElement Divide(ECFieldElement b);

		public abstract ECFieldElement Negate();

		public abstract ECFieldElement Square();

		public abstract ECFieldElement Invert();

		public abstract ECFieldElement Sqrt();

		public virtual ECFieldElement MultiplyMinusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			return Multiply(b).Subtract(x.Multiply(y));
		}

		public virtual ECFieldElement MultiplyPlusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			return Multiply(b).Add(x.Multiply(y));
		}

		public virtual ECFieldElement SquareMinusProduct(ECFieldElement x, ECFieldElement y)
		{
			return Square().Subtract(x.Multiply(y));
		}

		public virtual ECFieldElement SquarePlusProduct(ECFieldElement x, ECFieldElement y)
		{
			return Square().Add(x.Multiply(y));
		}

		public virtual ECFieldElement SquarePow(int pow)
		{
			ECFieldElement eCFieldElement = this;
			for (int i = 0; i < pow; i++)
			{
				eCFieldElement = eCFieldElement.Square();
			}
			return eCFieldElement;
		}

		public virtual bool TestBitZero()
		{
			return ToBigInteger().TestBit(0);
		}

		public override bool Equals(object obj)
		{
			return Equals(obj as ECFieldElement);
		}

		public virtual bool Equals(ECFieldElement other)
		{
			if (this == other)
			{
				return true;
			}
			if (other == null)
			{
				return false;
			}
			return ToBigInteger().Equals(other.ToBigInteger());
		}

		public override int GetHashCode()
		{
			return ToBigInteger().GetHashCode();
		}

		public override string ToString()
		{
			return ToBigInteger().ToString(16);
		}

		public virtual byte[] GetEncoded()
		{
			return BigIntegers.AsUnsignedByteArray((FieldSize + 7) / 8, ToBigInteger());
		}
	}
	public class FpFieldElement : ECFieldElement
	{
		private readonly BigInteger q;

		private readonly BigInteger r;

		private readonly BigInteger x;

		public override string FieldName => "Fp";

		public override int FieldSize => q.BitLength;

		public BigInteger Q => q;

		public FpFieldElement(BigInteger q, BigInteger x)
			: this(q, CalculateResidue(q), x)
		{
		}

		internal FpFieldElement(BigInteger q, BigInteger r, BigInteger x)
		{
			if (x == null || x.SignValue < 0 || x.CompareTo(q) >= 0)
			{
				throw new ArgumentException("value invalid in Fp field element", "x");
			}
			this.q = q;
			this.r = r;
			this.x = x;
		}

		internal static BigInteger CalculateResidue(BigInteger p)
		{
			int bitLength = p.BitLength;
			if (bitLength >= 96)
			{
				BigInteger bigInteger = p.ShiftRight(bitLength - 64);
				if (bigInteger.LongValue == -1)
				{
					return BigInteger.One.ShiftLeft(bitLength).Subtract(p);
				}
				if ((bitLength & 7) == 0)
				{
					return BigInteger.One.ShiftLeft(bitLength << 1).Divide(p).Negate();
				}
			}
			return null;
		}

		public override BigInteger ToBigInteger()
		{
			return x;
		}

		public override ECFieldElement Add(ECFieldElement b)
		{
			return new FpFieldElement(q, r, ModAdd(x, b.ToBigInteger()));
		}

		public override ECFieldElement AddOne()
		{
			BigInteger bigInteger = x.Add(BigInteger.One);
			if (bigInteger.CompareTo(q) == 0)
			{
				bigInteger = BigInteger.Zero;
			}
			return new FpFieldElement(q, r, bigInteger);
		}

		public override ECFieldElement Subtract(ECFieldElement b)
		{
			return new FpFieldElement(q, r, ModSubtract(x, b.ToBigInteger()));
		}

		public override ECFieldElement Multiply(ECFieldElement b)
		{
			return new FpFieldElement(q, r, ModMult(x, b.ToBigInteger()));
		}

		public override ECFieldElement MultiplyMinusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			BigInteger bigInteger = this.x;
			BigInteger val = b.ToBigInteger();
			BigInteger bigInteger2 = x.ToBigInteger();
			BigInteger val2 = y.ToBigInteger();
			BigInteger bigInteger3 = bigInteger.Multiply(val);
			BigInteger n = bigInteger2.Multiply(val2);
			return new FpFieldElement(q, r, ModReduce(bigInteger3.Subtract(n)));
		}

		public override ECFieldElement MultiplyPlusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			BigInteger bigInteger = this.x;
			BigInteger val = b.ToBigInteger();
			BigInteger bigInteger2 = x.ToBigInteger();
			BigInteger val2 = y.ToBigInteger();
			BigInteger bigInteger3 = bigInteger.Multiply(val);
			BigInteger value = bigInteger2.Multiply(val2);
			BigInteger bigInteger4 = bigInteger3.Add(value);
			if (r != null && r.SignValue < 0 && bigInteger4.BitLength > q.BitLength << 1)
			{
				bigInteger4 = bigInteger4.Subtract(q.ShiftLeft(q.BitLength));
			}
			return new FpFieldElement(q, r, ModReduce(bigInteger4));
		}

		public override ECFieldElement Divide(ECFieldElement b)
		{
			return new FpFieldElement(q, r, ModMult(x, ModInverse(b.ToBigInteger())));
		}

		public override ECFieldElement Negate()
		{
			return (x.SignValue != 0) ? new FpFieldElement(q, r, q.Subtract(x)) : this;
		}

		public override ECFieldElement Square()
		{
			return new FpFieldElement(q, r, ModMult(x, x));
		}

		public override ECFieldElement SquareMinusProduct(ECFieldElement x, ECFieldElement y)
		{
			BigInteger bigInteger = this.x;
			BigInteger bigInteger2 = x.ToBigInteger();
			BigInteger val = y.ToBigInteger();
			BigInteger bigInteger3 = bigInteger.Multiply(bigInteger);
			BigInteger n = bigInteger2.Multiply(val);
			return new FpFieldElement(q, r, ModReduce(bigInteger3.Subtract(n)));
		}

		public override ECFieldElement SquarePlusProduct(ECFieldElement x, ECFieldElement y)
		{
			BigInteger bigInteger = this.x;
			BigInteger bigInteger2 = x.ToBigInteger();
			BigInteger val = y.ToBigInteger();
			BigInteger bigInteger3 = bigInteger.Multiply(bigInteger);
			BigInteger value = bigInteger2.Multiply(val);
			BigInteger bigInteger4 = bigInteger3.Add(value);
			if (r != null && r.SignValue < 0 && bigInteger4.BitLength > q.BitLength << 1)
			{
				bigInteger4 = bigInteger4.Subtract(q.ShiftLeft(q.BitLength));
			}
			return new FpFieldElement(q, r, ModReduce(bigInteger4));
		}

		public override ECFieldElement Invert()
		{
			return new FpFieldElement(q, r, ModInverse(x));
		}

		public override ECFieldElement Sqrt()
		{
			if (IsZero || IsOne)
			{
				return this;
			}
			if (!q.TestBit(0))
			{
				throw Platform.CreateNotImplementedException("even value of q");
			}
			if (q.TestBit(1))
			{
				BigInteger e = q.ShiftRight(2).Add(BigInteger.One);
				return CheckSqrt(new FpFieldElement(q, r, this.x.ModPow(e, q)));
			}
			if (q.TestBit(2))
			{
				BigInteger bigInteger = this.x.ModPow(q.ShiftRight(3), q);
				BigInteger x = ModMult(bigInteger, this.x);
				BigInteger bigInteger2 = ModMult(x, bigInteger);
				if (bigInteger2.Equals(BigInteger.One))
				{
					return CheckSqrt(new FpFieldElement(q, r, x));
				}
				BigInteger x2 = BigInteger.Two.ModPow(q.ShiftRight(2), q);
				BigInteger bigInteger3 = ModMult(x, x2);
				return CheckSqrt(new FpFieldElement(q, r, bigInteger3));
			}
			BigInteger bigInteger4 = q.ShiftRight(1);
			if (!this.x.ModPow(bigInteger4, q).Equals(BigInteger.One))
			{
				return null;
			}
			BigInteger bigInteger5 = this.x;
			BigInteger bigInteger6 = ModDouble(ModDouble(bigInteger5));
			BigInteger k = bigInteger4.Add(BigInteger.One);
			BigInteger obj = q.Subtract(BigInteger.One);
			while (true)
			{
				BigInteger bigInteger7 = BigInteger.Arbitrary(q.BitLength);
				if (bigInteger7.CompareTo(q) < 0 && ModReduce(bigInteger7.Multiply(bigInteger7).Subtract(bigInteger6)).ModPow(bigInteger4, q).Equals(obj))
				{
					BigInteger[] array = LucasSequence(bigInteger7, bigInteger5, k);
					BigInteger bigInteger8 = array[0];
					BigInteger bigInteger9 = array[1];
					if (ModMult(bigInteger9, bigInteger9).Equals(bigInteger6))
					{
						return new FpFieldElement(q, r, ModHalfAbs(bigInteger9));
					}
					if (!bigInteger8.Equals(BigInteger.One) && !bigInteger8.Equals(obj))
					{
						break;
					}
				}
			}
			return null;
		}

		private ECFieldElement CheckSqrt(ECFieldElement z)
		{
			return (!z.Square().Equals(this)) ? null : z;
		}

		private BigInteger[] LucasSequence(BigInteger P, BigInteger Q, BigInteger k)
		{
			int bitLength = k.BitLength;
			int lowestSetBit = k.GetLowestSetBit();
			BigInteger bigInteger = BigInteger.One;
			BigInteger bigInteger2 = BigInteger.Two;
			BigInteger bigInteger3 = P;
			BigInteger bigInteger4 = BigInteger.One;
			BigInteger bigInteger5 = BigInteger.One;
			for (int num = bitLength - 1; num >= lowestSetBit + 1; num--)
			{
				bigInteger4 = ModMult(bigInteger4, bigInteger5);
				if (k.TestBit(num))
				{
					bigInteger5 = ModMult(bigInteger4, Q);
					bigInteger = ModMult(bigInteger, bigInteger3);
					bigInteger2 = ModReduce(bigInteger3.Multiply(bigInteger2).Subtract(P.Multiply(bigInteger4)));
					bigInteger3 = ModReduce(bigInteger3.Multiply(bigInteger3).Subtract(bigInteger5.ShiftLeft(1)));
				}
				else
				{
					bigInteger5 = bigInteger4;
					bigInteger = ModReduce(bigInteger.Multiply(bigInteger2).Subtract(bigInteger4));
					bigInteger3 = ModReduce(bigInteger3.Multiply(bigInteger2).Subtract(P.Multiply(bigInteger4)));
					bigInteger2 = ModReduce(bigInteger2.Multiply(bigInteger2).Subtract(bigInteger4.ShiftLeft(1)));
				}
			}
			bigInteger4 = ModMult(bigInteger4, bigInteger5);
			bigInteger5 = ModMult(bigInteger4, Q);
			bigInteger = ModReduce(bigInteger.Multiply(bigInteger2).Subtract(bigInteger4));
			bigInteger2 = ModReduce(bigInteger3.Multiply(bigInteger2).Subtract(P.Multiply(bigInteger4)));
			bigInteger4 = ModMult(bigInteger4, bigInteger5);
			for (int i = 1; i <= lowestSetBit; i++)
			{
				bigInteger = ModMult(bigInteger, bigInteger2);
				bigInteger2 = ModReduce(bigInteger2.Multiply(bigInteger2).Subtract(bigInteger4.ShiftLeft(1)));
				bigInteger4 = ModMult(bigInteger4, bigInteger4);
			}
			return new BigInteger[2] { bigInteger, bigInteger2 };
		}

		protected virtual BigInteger ModAdd(BigInteger x1, BigInteger x2)
		{
			BigInteger bigInteger = x1.Add(x2);
			if (bigInteger.CompareTo(q) >= 0)
			{
				bigInteger = bigInteger.Subtract(q);
			}
			return bigInteger;
		}

		protected virtual BigInteger ModDouble(BigInteger x)
		{
			BigInteger bigInteger = x.ShiftLeft(1);
			if (bigInteger.CompareTo(q) >= 0)
			{
				bigInteger = bigInteger.Subtract(q);
			}
			return bigInteger;
		}

		protected virtual BigInteger ModHalf(BigInteger x)
		{
			if (x.TestBit(0))
			{
				x = q.Add(x);
			}
			return x.ShiftRight(1);
		}

		protected virtual BigInteger ModHalfAbs(BigInteger x)
		{
			if (x.TestBit(0))
			{
				x = q.Subtract(x);
			}
			return x.ShiftRight(1);
		}

		protected virtual BigInteger ModInverse(BigInteger x)
		{
			int fieldSize = FieldSize;
			int len = fieldSize + 31 >> 5;
			uint[] p = Nat.FromBigInteger(fieldSize, q);
			uint[] array = Nat.FromBigInteger(fieldSize, x);
			uint[] z = Nat.Create(len);
			Mod.Invert(p, array, z);
			return Nat.ToBigInteger(len, z);
		}

		protected virtual BigInteger ModMult(BigInteger x1, BigInteger x2)
		{
			return ModReduce(x1.Multiply(x2));
		}

		protected virtual BigInteger ModReduce(BigInteger x)
		{
			if (r == null)
			{
				x = x.Mod(q);
			}
			else
			{
				bool flag = x.SignValue < 0;
				if (flag)
				{
					x = x.Abs();
				}
				int bitLength = q.BitLength;
				if (r.SignValue > 0)
				{
					BigInteger n = BigInteger.One.ShiftLeft(bitLength);
					bool flag2 = r.Equals(BigInteger.One);
					while (x.BitLength > bitLength + 1)
					{
						BigInteger bigInteger = x.ShiftRight(bitLength);
						BigInteger value = x.Remainder(n);
						if (!flag2)
						{
							bigInteger = bigInteger.Multiply(r);
						}
						x = bigInteger.Add(value);
					}
				}
				else
				{
					int num = ((bitLength - 1) & 0x1F) + 1;
					BigInteger bigInteger2 = r.Negate();
					BigInteger bigInteger3 = bigInteger2.Multiply(x.ShiftRight(bitLength - num));
					BigInteger bigInteger4 = bigInteger3.ShiftRight(bitLength + num);
					BigInteger bigInteger5 = bigInteger4.Multiply(q);
					BigInteger bigInteger6 = BigInteger.One.ShiftLeft(bitLength + num);
					bigInteger5 = bigInteger5.Remainder(bigInteger6);
					x = x.Remainder(bigInteger6);
					x = x.Subtract(bigInteger5);
					if (x.SignValue < 0)
					{
						x = x.Add(bigInteger6);
					}
				}
				while (x.CompareTo(q) >= 0)
				{
					x = x.Subtract(q);
				}
				if (flag && x.SignValue != 0)
				{
					x = q.Subtract(x);
				}
			}
			return x;
		}

		protected virtual BigInteger ModSubtract(BigInteger x1, BigInteger x2)
		{
			BigInteger bigInteger = x1.Subtract(x2);
			if (bigInteger.SignValue < 0)
			{
				bigInteger = bigInteger.Add(q);
			}
			return bigInteger;
		}

		public override bool Equals(object obj)
		{
			if (obj == this)
			{
				return true;
			}
			if (!(obj is FpFieldElement other))
			{
				return false;
			}
			return Equals(other);
		}

		public virtual bool Equals(FpFieldElement other)
		{
			return q.Equals(other.q) && base.Equals(other);
		}

		public override int GetHashCode()
		{
			return q.GetHashCode() ^ base.GetHashCode();
		}
	}
	public class F2mFieldElement : ECFieldElement
	{
		public const int Gnb = 1;

		public const int Tpb = 2;

		public const int Ppb = 3;

		private int representation;

		private int m;

		private int[] ks;

		private LongArray x;

		public override int BitLength => x.Degree();

		public override bool IsOne => x.IsOne();

		public override bool IsZero => x.IsZero();

		public override string FieldName => "F2m";

		public override int FieldSize => m;

		public int Representation => representation;

		public int M => m;

		public int K1 => ks[0];

		public int K2 => (ks.Length >= 2) ? ks[1] : 0;

		public int K3 => (ks.Length >= 3) ? ks[2] : 0;

		public F2mFieldElement(int m, int k1, int k2, int k3, BigInteger x)
		{
			if (x == null || x.SignValue < 0 || x.BitLength > m)
			{
				throw new ArgumentException("value invalid in F2m field element", "x");
			}
			if (k2 == 0 && k3 == 0)
			{
				representation = 2;
				ks = new int[1] { k1 };
			}
			else
			{
				if (k2 >= k3)
				{
					throw new ArgumentException("k2 must be smaller than k3");
				}
				if (k2 <= 0)
				{
					throw new ArgumentException("k2 must be larger than 0");
				}
				representation = 3;
				ks = new int[3] { k1, k2, k3 };
			}
			this.m = m;
			this.x = new LongArray(x);
		}

		public F2mFieldElement(int m, int k, BigInteger x)
			: this(m, k, 0, 0, x)
		{
		}

		private F2mFieldElement(int m, int[] ks, LongArray x)
		{
			this.m = m;
			representation = ((ks.Length != 1) ? 3 : 2);
			this.ks = ks;
			this.x = x;
		}

		public override bool TestBitZero()
		{
			return x.TestBitZero();
		}

		public override BigInteger ToBigInteger()
		{
			return x.ToBigInteger();
		}

		public static void CheckFieldElements(ECFieldElement a, ECFieldElement b)
		{
			if (!(a is F2mFieldElement) || !(b is F2mFieldElement))
			{
				throw new ArgumentException("Field elements are not both instances of F2mFieldElement");
			}
			F2mFieldElement f2mFieldElement = (F2mFieldElement)a;
			F2mFieldElement f2mFieldElement2 = (F2mFieldElement)b;
			if (f2mFieldElement.representation != f2mFieldElement2.representation)
			{
				throw new ArgumentException("One of the F2m field elements has incorrect representation");
			}
			if (f2mFieldElement.m != f2mFieldElement2.m || !Arrays.AreEqual(f2mFieldElement.ks, f2mFieldElement2.ks))
			{
				throw new ArgumentException("Field elements are not elements of the same field F2m");
			}
		}

		public override ECFieldElement Add(ECFieldElement b)
		{
			LongArray longArray = x.Copy();
			F2mFieldElement f2mFieldElement = (F2mFieldElement)b;
			longArray.AddShiftedByWords(f2mFieldElement.x, 0);
			return new F2mFieldElement(m, ks, longArray);
		}

		public override ECFieldElement AddOne()
		{
			return new F2mFieldElement(m, ks, x.AddOne());
		}

		public override ECFieldElement Subtract(ECFieldElement b)
		{
			return Add(b);
		}

		public override ECFieldElement Multiply(ECFieldElement b)
		{
			return new F2mFieldElement(m, ks, x.ModMultiply(((F2mFieldElement)b).x, m, ks));
		}

		public override ECFieldElement MultiplyMinusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			return MultiplyPlusProduct(b, x, y);
		}

		public override ECFieldElement MultiplyPlusProduct(ECFieldElement b, ECFieldElement x, ECFieldElement y)
		{
			LongArray longArray = this.x;
			LongArray longArray2 = ((F2mFieldElement)b).x;
			LongArray longArray3 = ((F2mFieldElement)x).x;
			LongArray other = ((F2mFieldElement)y).x;
			LongArray longArray4 = longArray.Multiply(longArray2, m, ks);
			LongArray other2 = longArray3.Multiply(other, m, ks);
			if (longArray4 == longArray || longArray4 == longArray2)
			{
				longArray4 = longArray4.Copy();
			}
			longArray4.AddShiftedByWords(other2, 0);
			longArray4.Reduce(m, ks);
			return new F2mFieldElement(m, ks, longArray4);
		}

		public override ECFieldElement Divide(ECFieldElement b)
		{
			ECFieldElement b2 = b.Invert();
			return Multiply(b2);
		}

		public override ECFieldElement Negate()
		{
			return this;
		}

		public override ECFieldElement Square()
		{
			return new F2mFieldElement(m, ks, x.ModSquare(m, ks));
		}

		public override ECFieldElement SquareMinusProduct(ECFieldElement x, ECFieldElement y)
		{
			return SquarePlusProduct(x, y);
		}

		public override ECFieldElement SquarePlusProduct(ECFieldElement x, ECFieldElement y)
		{
			LongArray longArray = this.x;
			LongArray longArray2 = ((F2mFieldElement)x).x;
			LongArray other = ((F2mFieldElement)y).x;
			LongArray longArray3 = longArray.Square(m, ks);
			LongArray other2 = longArray2.Multiply(other, m, ks);
			if (longArray3 == longArray)
			{
				longArray3 = longArray3.Copy();
			}
			longArray3.AddShiftedByWords(other2, 0);
			longArray3.Reduce(m, ks);
			return new F2mFieldElement(m, ks, longArray3);
		}

		public override ECFieldElement SquarePow(int pow)
		{
			return (pow >= 1) ? new F2mFieldElement(m, ks, x.ModSquareN(pow, m, ks)) : this;
		}

		public override ECFieldElement Invert()
		{
			return new F2mFieldElement(m, ks, x.ModInverse(m, ks));
		}

		public override ECFieldElement Sqrt()
		{
			return (!x.IsZero() && !x.IsOne()) ? SquarePow(m - 1) : this;
		}

		public override bool Equals(object obj)
		{
			if (obj == this)
			{
				return true;
			}
			if (!(obj is F2mFieldElement other))
			{
				return false;
			}
			return Equals(other);
		}

		public virtual bool Equals(F2mFieldElement other)
		{
			return m == other.m && representation == other.representation && Arrays.AreEqual(ks, other.ks) && x.Equals(other.x);
		}

		public override int GetHashCode()
		{
			return x.GetHashCode() ^ m ^ Arrays.GetHashCode(ks);
		}
	}
	public abstract class ECPoint
	{
		protected static ECFieldElement[] EMPTY_ZS = new ECFieldElement[0];

		protected internal readonly ECCurve m_curve;

		protected internal readonly ECFieldElement m_x;

		protected internal readonly ECFieldElement m_y;

		protected internal readonly ECFieldElement[] m_zs;

		protected internal readonly bool m_withCompression;

		protected internal IDictionary m_preCompTable;

		public virtual ECCurve Curve => m_curve;

		protected virtual int CurveCoordinateSystem => (m_curve != null) ? m_curve.CoordinateSystem : 0;

		[Obsolete("Use AffineXCoord, or Normalize() and XCoord, instead")]
		public virtual ECFieldElement X => Normalize().XCoord;

		[Obsolete("Use AffineYCoord, or Normalize() and YCoord, instead")]
		public virtual ECFieldElement Y => Normalize().YCoord;

		public virtual ECFieldElement AffineXCoord
		{
			get
			{
				CheckNormalized();
				return XCoord;
			}
		}

		public virtual ECFieldElement AffineYCoord
		{
			get
			{
				CheckNormalized();
				return YCoord;
			}
		}

		public virtual ECFieldElement XCoord => m_x;

		public virtual ECFieldElement YCoord => m_y;

		protected internal ECFieldElement RawXCoord => m_x;

		protected internal ECFieldElement RawYCoord => m_y;

		protected internal ECFieldElement[] RawZCoords => m_zs;

		public bool IsInfinity => m_x == null && m_y == null;

		public bool IsCompressed => m_withCompression;

		protected internal abstract bool CompressionYTilde { get; }

		protected ECPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, bool withCompression)
			: this(curve, x, y, GetInitialZCoords(curve), withCompression)
		{
		}

		internal ECPoint(ECCurve curve, ECFieldElement x, ECFieldElement y, ECFieldElement[] zs, bool withCompression)
		{
			m_curve = curve;
			m_x = x;
			m_y = y;
			m_zs = zs;
			m_withCompression = withCompression;
		}

		protected static ECFieldElement[] GetInitialZCoords(ECCurve curve)
		{
			int num = curve?.CoordinateSystem ?? 0;
			if (num == 0 || num == 5)
			{
				return EMPTY_ZS;
			}
