		public static ECPoint MapPointWithPrecomp(ECPoint p, int width, bool includeNegated, ECPointMap pointMap)
		{
			ECCurve curve = p.Curve;
			WNafPreCompInfo wNafPreCompInfo = Precompute(p, width, includeNegated);
			ECPoint eCPoint = pointMap.Map(p);
			WNafPreCompInfo wNafPreCompInfo2 = GetWNafPreCompInfo(curve.GetPreCompInfo(eCPoint, PRECOMP_NAME));
			ECPoint twice = wNafPreCompInfo.Twice;
			if (twice != null)
			{
				ECPoint twice2 = pointMap.Map(twice);
				wNafPreCompInfo2.Twice = twice2;
			}
			ECPoint[] preComp = wNafPreCompInfo.PreComp;
			ECPoint[] array = new ECPoint[preComp.Length];
			for (int i = 0; i < preComp.Length; i++)
			{
				array[i] = pointMap.Map(preComp[i]);
			}
			wNafPreCompInfo2.PreComp = array;
			if (includeNegated)
			{
				ECPoint[] array2 = new ECPoint[array.Length];
				for (int j = 0; j < array2.Length; j++)
				{
					array2[j] = array[j].Negate();
				}
				wNafPreCompInfo2.PreCompNeg = array2;
			}
			curve.SetPreCompInfo(eCPoint, PRECOMP_NAME, wNafPreCompInfo2);
			return eCPoint;
		}

		public static WNafPreCompInfo Precompute(ECPoint p, int width, bool includeNegated)
		{
			ECCurve curve = p.Curve;
			WNafPreCompInfo wNafPreCompInfo = GetWNafPreCompInfo(curve.GetPreCompInfo(p, PRECOMP_NAME));
			int num = 0;
			int num2 = 1 << System.Math.Max(0, width - 2);
			ECPoint[] array = wNafPreCompInfo.PreComp;
			if (array == null)
			{
				array = EMPTY_POINTS;
			}
			else
			{
				num = array.Length;
			}
			if (num < num2)
			{
				array = ResizeTable(array, num2);
				if (num2 == 1)
				{
					array[0] = p.Normalize();
				}
				else
				{
					int num3 = num;
					if (num3 == 0)
					{
						array[0] = p;
						num3 = 1;
					}
					ECFieldElement eCFieldElement = null;
					if (num2 == 2)
					{
						array[1] = p.ThreeTimes();
					}
					else
					{
						ECPoint eCPoint = wNafPreCompInfo.Twice;
						ECPoint eCPoint2 = array[num3 - 1];
						if (eCPoint == null)
						{
							eCPoint = (wNafPreCompInfo.Twice = array[0].Twice());
							if (ECAlgorithms.IsFpCurve(curve) && curve.FieldSize >= 64)
							{
								int coordinateSystem = curve.CoordinateSystem;
								if (coordinateSystem == 2 || coordinateSystem == 3 || coordinateSystem == 4)
								{
									eCFieldElement = eCPoint.GetZCoord(0);
									eCPoint = curve.CreatePoint(eCPoint.XCoord.ToBigInteger(), eCPoint.YCoord.ToBigInteger());
									ECFieldElement eCFieldElement2 = eCFieldElement.Square();
									ECFieldElement scale = eCFieldElement2.Multiply(eCFieldElement);
									eCPoint2 = eCPoint2.ScaleX(eCFieldElement2).ScaleY(scale);
									if (num == 0)
									{
										array[0] = eCPoint2;
									}
								}
							}
						}
						while (num3 < num2)
						{
							eCPoint2 = (array[num3++] = eCPoint2.Add(eCPoint));
						}
					}
					curve.NormalizeAll(array, num, num2 - num, eCFieldElement);
				}
			}
			wNafPreCompInfo.PreComp = array;
			if (includeNegated)
			{
				ECPoint[] array2 = wNafPreCompInfo.PreCompNeg;
				int i;
				if (array2 == null)
				{
					i = 0;
					array2 = new ECPoint[num2];
				}
				else
				{
					i = array2.Length;
					if (i < num2)
					{
						array2 = ResizeTable(array2, num2);
					}
				}
				for (; i < num2; i++)
				{
					array2[i] = array[i].Negate();
				}
				wNafPreCompInfo.PreCompNeg = array2;
			}
			curve.SetPreCompInfo(p, PRECOMP_NAME, wNafPreCompInfo);
			return wNafPreCompInfo;
		}

		private static byte[] Trim(byte[] a, int length)
		{
			byte[] array = new byte[length];
			Array.Copy(a, 0, array, 0, array.Length);
			return array;
		}

		private static int[] Trim(int[] a, int length)
		{
			int[] array = new int[length];
			Array.Copy(a, 0, array, 0, array.Length);
			return array;
		}

		private static ECPoint[] ResizeTable(ECPoint[] a, int length)
		{
			ECPoint[] array = new ECPoint[length];
			Array.Copy(a, 0, array, 0, a.Length);
			return array;
		}
	}
	public class WTauNafMultiplier : AbstractECMultiplier
	{
		internal static readonly string PRECOMP_NAME = "bc_wtnaf";

		protected override ECPoint MultiplyPositive(ECPoint point, BigInteger k)
		{
			if (!(point is AbstractF2mPoint))
			{
				throw new ArgumentException("Only AbstractF2mPoint can be used in WTauNafMultiplier");
			}
			AbstractF2mPoint abstractF2mPoint = (AbstractF2mPoint)point;
			AbstractF2mCurve abstractF2mCurve = (AbstractF2mCurve)abstractF2mPoint.Curve;
			int fieldSize = abstractF2mCurve.FieldSize;
			sbyte b = (sbyte)abstractF2mCurve.A.ToBigInteger().IntValue;
			sbyte mu = Tnaf.GetMu(b);
			BigInteger[] si = abstractF2mCurve.GetSi();
			ZTauElement lambda = Tnaf.PartModReduction(k, fieldSize, b, si, mu, 10);
			return MultiplyWTnaf(abstractF2mPoint, lambda, abstractF2mCurve.GetPreCompInfo(abstractF2mPoint, PRECOMP_NAME), b, mu);
		}

		private AbstractF2mPoint MultiplyWTnaf(AbstractF2mPoint p, ZTauElement lambda, PreCompInfo preCompInfo, sbyte a, sbyte mu)
		{
			ZTauElement[] alpha = ((a != 0) ? Tnaf.Alpha1 : Tnaf.Alpha0);
			BigInteger tw = Tnaf.GetTw(mu, 4);
			sbyte[] u = Tnaf.TauAdicWNaf(mu, lambda, 4, BigInteger.ValueOf(16L), tw, alpha);
			return MultiplyFromWTnaf(p, u, preCompInfo);
		}

		private static AbstractF2mPoint MultiplyFromWTnaf(AbstractF2mPoint p, sbyte[] u, PreCompInfo preCompInfo)
		{
			AbstractF2mCurve abstractF2mCurve = (AbstractF2mCurve)p.Curve;
			sbyte a = (sbyte)abstractF2mCurve.A.ToBigInteger().IntValue;
			AbstractF2mPoint[] preComp;
			if (preCompInfo == null || !(preCompInfo is WTauNafPreCompInfo))
			{
				preComp = Tnaf.GetPreComp(p, a);
				WTauNafPreCompInfo wTauNafPreCompInfo = new WTauNafPreCompInfo();
				wTauNafPreCompInfo.PreComp = preComp;
				abstractF2mCurve.SetPreCompInfo(p, PRECOMP_NAME, wTauNafPreCompInfo);
			}
			else
			{
				preComp = ((WTauNafPreCompInfo)preCompInfo).PreComp;
			}
			AbstractF2mPoint[] array = new AbstractF2mPoint[preComp.Length];
			for (int i = 0; i < preComp.Length; i++)
			{
				array[i] = (AbstractF2mPoint)preComp[i].Negate();
			}
			AbstractF2mPoint abstractF2mPoint = (AbstractF2mPoint)p.Curve.Infinity;
			int num = 0;
			for (int num2 = u.Length - 1; num2 >= 0; num2--)
			{
				num++;
				int num3 = u[num2];
				if (num3 != 0)
				{
					abstractF2mPoint = abstractF2mPoint.TauPow(num);
					num = 0;
					ECPoint b = ((num3 <= 0) ? array[-num3 >> 1] : preComp[num3 >> 1]);
					abstractF2mPoint = (AbstractF2mPoint)abstractF2mPoint.Add(b);
				}
			}
			if (num > 0)
			{
				abstractF2mPoint = abstractF2mPoint.TauPow(num);
			}
			return abstractF2mPoint;
		}
	}
	public class WTauNafPreCompInfo : PreCompInfo
	{
		protected AbstractF2mPoint[] m_preComp;

		public virtual AbstractF2mPoint[] PreComp
		{
			get
			{
				return m_preComp;
			}
			set
			{
				m_preComp = value;
			}
		}
	}
