		}

		public override bool Equals(object obj)
		{
			if (this == obj)
			{
				return true;
			}
			if (!(obj is PrimeField primeField))
			{
				return false;
			}
			return characteristic.Equals(primeField.characteristic);
		}

		public override int GetHashCode()
		{
			return characteristic.GetHashCode();
		}
