		public static uint[] FromBigInteger(BigInteger x)
		{
			if (x.SignValue < 0 || x.BitLength > 160)
			{
				throw new ArgumentException();
			}
			uint[] array = Create();
			int num = 0;
			while (x.SignValue != 0)
			{
				array[num++] = (uint)x.IntValue;
				x = x.ShiftRight(32);
			}
			return array;
		}

		public static uint GetBit(uint[] x, int bit)
		{
			if (bit == 0)
			{
				return x[0] & 1;
			}
			int num = bit >> 5;
			if (num < 0 || num >= 5)
			{
				return 0u;
			}
			int num2 = bit & 0x1F;
			return (x[num] >> num2) & 1;
		}

