	internal abstract class Enums
	{
		internal static System.Enum GetEnumValue(System.Type enumType, string s)
		{
			if (s.Length > 0 && char.IsLetter(s[0]) && s.IndexOf(',') < 0)
			{
				s = s.Replace('-', '_');
				s = s.Replace('/', '_');
				return (System.Enum)System.Enum.Parse(enumType, s, ignoreCase: false);
			}
			throw new ArgumentException();
		}

		internal static Array GetEnumValues(System.Type enumType)
		{
			return System.Enum.GetValues(enumType);
		}

		internal static System.Enum GetArbitraryValue(System.Type enumType)
		{
			Array enumValues = GetEnumValues(enumType);
			int index = (int)(DateTimeUtilities.CurrentUnixMs() & 0x7FFFFFFF) % enumValues.Length;
			return (System.Enum)enumValues.GetValue(index);
		}

		internal static bool IsEnumType(System.Type t)
		{
			return t.IsEnum;
		}
	}
