	internal struct CallbackDescriptor
	{
		public readonly System.Type[] ParamTypes;

		public readonly Action<object[]> Callback;

		public CallbackDescriptor(System.Type[] paramTypes, Action<object[]> callback)
		{
			ParamTypes = paramTypes;
