namespace BestHTTP.WebSocket.Extensions
{
	public interface IExtension
	{
		void AddNegotiation(HTTPRequest request);

		bool ParseNegotiation(WebSocketResponse resp);

		byte GetFrameHeader(WebSocketFrame writer, byte inFlag);

		byte[] Encode(WebSocketFrame writer);

		byte[] Decode(byte header, byte[] data);
	}
	public sealed class PerMessageCompression : IExtension
	{
		private static readonly byte[] Trailer = new byte[4] { 0, 0, 255, 255 };

		private MemoryStream compressorOutputStream;

		private DeflateStream compressorDeflateStream;

		private MemoryStream decompressorInputStream;

		private MemoryStream decompressorOutputStream;

		private DeflateStream decompressorDeflateStream;

		private byte[] copyBuffer = new byte[1024];

		public bool ClientNoContextTakeover { get; private set; }

		public bool ServerNoContextTakeover { get; private set; }

		public int ClientMaxWindowBits { get; private set; }

		public int ServerMaxWindowBits { get; private set; }

		public CompressionLevel Level { get; private set; }

		public int MinimumDataLegthToCompress { get; set; }

		public PerMessageCompression()
			: this(CompressionLevel.Default, clientNoContextTakeover: false, serverNoContextTakeover: false, 15, 15, 10)
		{
		}

		public PerMessageCompression(CompressionLevel level, bool clientNoContextTakeover, bool serverNoContextTakeover, int desiredClientMaxWindowBits, int desiredServerMaxWindowBits, int minDatalengthToCompress)
		{
			Level = level;
			ClientNoContextTakeover = clientNoContextTakeover;
			ServerNoContextTakeover = ServerNoContextTakeover;
			ClientMaxWindowBits = desiredClientMaxWindowBits;
			ServerMaxWindowBits = desiredServerMaxWindowBits;
			MinimumDataLegthToCompress = minDatalengthToCompress;
		}

		public void AddNegotiation(HTTPRequest request)
		{
			string text = "permessage-deflate";
			if (ServerNoContextTakeover)
			{
				text += "; server_no_context_takeover";
			}
			if (ClientNoContextTakeover)
			{
				text += "; client_no_context_takeover";
			}
			if (ServerMaxWindowBits != 15)
			{
				text = text + "; server_max_window_bits=" + ServerMaxWindowBits;
			}
			else
			{
				ServerMaxWindowBits = 15;
			}
			if (ClientMaxWindowBits != 15)
			{
				text = text + "; client_max_window_bits=" + ClientMaxWindowBits;
			}
			else
			{
				text += "; client_max_window_bits";
				ClientMaxWindowBits = 15;
			}
			request.AddHeader("Sec-WebSocket-Extensions", text);
		}

		public bool ParseNegotiation(WebSocketResponse resp)
		{
			List<string> headerValues = resp.GetHeaderValues("Sec-WebSocket-Extensions");
			if (headerValues == null)
			{
				return false;
			}
			for (int i = 0; i < headerValues.Count; i++)
			{
				HeaderParser headerParser = new HeaderParser(headerValues[i]);
				for (int j = 0; j < headerParser.Values.Count; j++)
				{
					HeaderValue headerValue = headerParser.Values[i];
					if (!string.IsNullOrEmpty(headerValue.Key) && headerValue.Key.StartsWith("permessage-deflate", StringComparison.OrdinalIgnoreCase))
					{
						HTTPManager.Logger.Information("PerMessageCompression", "Enabled with header: " + headerValues[i]);
						if (headerValue.TryGetOption("client_no_context_takeover", out var option))
						{
							ClientNoContextTakeover = true;
						}
						if (headerValue.TryGetOption("server_no_context_takeover", out option))
						{
							ServerNoContextTakeover = true;
						}
						if (headerValue.TryGetOption("client_max_window_bits", out option) && option.HasValue && int.TryParse(option.Value, out var result))
						{
							ClientMaxWindowBits = result;
						}
						if (headerValue.TryGetOption("server_max_window_bits", out option) && option.HasValue && int.TryParse(option.Value, out var result2))
						{
							ServerMaxWindowBits = result2;
						}
						return true;
					}
				}
			}
			return false;
		}

		public byte GetFrameHeader(WebSocketFrame writer, byte inFlag)
		{
			if ((writer.Type == WebSocketFrameTypes.Binary || writer.Type == WebSocketFrameTypes.Text) && writer.Data != null && writer.Data.Length >= MinimumDataLegthToCompress)
			{
				return (byte)(inFlag | 0x40);
			}
			return inFlag;
		}

		public byte[] Encode(WebSocketFrame writer)
		{
			if (writer.Data == null)
			{
				return WebSocketFrame.NoData;
			}
			if ((writer.Header & 0x40) != 0)
			{
				return Compress(writer.Data);
			}
			return writer.Data;
		}

		public byte[] Decode(byte header, byte[] data)
		{
			if ((header & 0x40) != 0)
			{
				return Decompress(data);
			}
			return data;
		}

		private byte[] Compress(byte[] data)
		{
			if (compressorOutputStream == null)
			{
				compressorOutputStream = new MemoryStream();
			}
			compressorOutputStream.SetLength(0L);
			if (compressorDeflateStream == null)
			{
				compressorDeflateStream = new DeflateStream(compressorOutputStream, CompressionMode.Compress, Level, leaveOpen: true, ClientMaxWindowBits);
				compressorDeflateStream.FlushMode = FlushType.Sync;
			}
			byte[] array = null;
			try
			{
				compressorDeflateStream.Write(data, 0, data.Length);
				compressorDeflateStream.Flush();
				compressorOutputStream.Position = 0L;
				compressorOutputStream.SetLength(compressorOutputStream.Length - 4);
				return compressorOutputStream.ToArray();
			}
			finally
			{
				if (ClientNoContextTakeover)
				{
					compressorDeflateStream.Dispose();
					compressorDeflateStream = null;
				}
			}
		}

		private byte[] Decompress(byte[] data)
		{
			if (decompressorInputStream == null)
			{
				decompressorInputStream = new MemoryStream(data.Length + 4);
			}
			decompressorInputStream.Write(data, 0, data.Length);
			decompressorInputStream.Write(Trailer, 0, Trailer.Length);
			decompressorInputStream.Position = 0L;
			if (decompressorDeflateStream == null)
			{
				decompressorDeflateStream = new DeflateStream(decompressorInputStream, CompressionMode.Decompress, CompressionLevel.Default, leaveOpen: true, ServerMaxWindowBits);
				decompressorDeflateStream.FlushMode = FlushType.Sync;
			}
			if (decompressorOutputStream == null)
			{
				decompressorOutputStream = new MemoryStream();
			}
			decompressorOutputStream.SetLength(0L);
			int count;
			while ((count = decompressorDeflateStream.Read(copyBuffer, 0, copyBuffer.Length)) != 0)
			{
				decompressorOutputStream.Write(copyBuffer, 0, count);
			}
			decompressorDeflateStream.SetLength(0L);
			byte[] result = decompressorOutputStream.ToArray();
			if (ServerNoContextTakeover)
			{
				decompressorDeflateStream.Dispose();
				decompressorDeflateStream = null;
			}
			return result;
		}
	}
}
namespace BestHTTP.WebSocket.Frames
{
	public sealed class WebSocketFrame
	{
		public static readonly byte[] NoData = new byte[0];

		public WebSocketFrameTypes Type { get; private set; }

		public bool IsFinal { get; private set; }

		public byte Header { get; private set; }

		public byte[] Data { get; private set; }

		public bool UseExtensions { get; private set; }

		public WebSocketFrame(WebSocket webSocket, WebSocketFrameTypes type, byte[] data)
			: this(webSocket, type, data, useExtensions: true)
		{
		}

		public WebSocketFrame(WebSocket webSocket, WebSocketFrameTypes type, byte[] data, bool useExtensions)
			: this(webSocket, type, data, 0uL, (ulong)((data == null) ? 0 : data.Length), isFinal: true, useExtensions)
		{
		}

		public WebSocketFrame(WebSocket webSocket, WebSocketFrameTypes type, byte[] data, bool isFinal, bool useExtensions)
			: this(webSocket, type, data, 0uL, (ulong)((data == null) ? 0 : data.Length), isFinal, useExtensions)
		{
		}

		public WebSocketFrame(WebSocket webSocket, WebSocketFrameTypes type, byte[] data, ulong pos, ulong length, bool isFinal, bool useExtensions)
		{
			Type = type;
			IsFinal = isFinal;
			UseExtensions = useExtensions;
			if (data != null)
			{
				Data = new byte[length];
				Array.Copy(data, (int)pos, Data, 0, (int)length);
			}
			else
			{
				data = NoData;
			}
			Header = (byte)((uint)(byte)(IsFinal ? 128 : 0) | (uint)Type);
			if (!UseExtensions || webSocket == null || webSocket.Extensions == null)
			{
				return;
			}
			for (int i = 0; i < webSocket.Extensions.Length; i++)
			{
				IExtension extension = webSocket.Extensions[i];
				if (extension != null)
				{
					Header |= extension.GetFrameHeader(this, Header);
					Data = extension.Encode(this);
				}
			}
		}

		public byte[] Get()
		{
			if (Data == null)
			{
				Data = NoData;
			}
			using MemoryStream memoryStream = new MemoryStream(Data.Length + 9);
			memoryStream.WriteByte(Header);
			if (Data.Length < 126)
			{
				memoryStream.WriteByte((byte)(0x80 | (byte)Data.Length));
			}
			else if (Data.Length < 65535)
			{
				memoryStream.WriteByte(254);
				byte[] bytes = BitConverter.GetBytes((ushort)Data.Length);
				if (BitConverter.IsLittleEndian)
				{
					Array.Reverse((Array)bytes, 0, bytes.Length);
				}
				memoryStream.Write(bytes, 0, bytes.Length);
			}
			else
			{
				memoryStream.WriteByte(byte.MaxValue);
				byte[] bytes2 = BitConverter.GetBytes((ulong)Data.Length);
				if (BitConverter.IsLittleEndian)
				{
					Array.Reverse((Array)bytes2, 0, bytes2.Length);
				}
				memoryStream.Write(bytes2, 0, bytes2.Length);
			}
			byte[] bytes3 = BitConverter.GetBytes(GetHashCode());
			memoryStream.Write(bytes3, 0, bytes3.Length);
			for (int i = 0; i < Data.Length; i++)
			{
				memoryStream.WriteByte((byte)(Data[i] ^ bytes3[i % 4]));
			}
			return memoryStream.ToArray();
		}

		public WebSocketFrame[] Fragment(ushort maxFragmentSize)
		{
			if (Data == null)
			{
				return null;
			}
			if (Type != WebSocketFrameTypes.Binary && Type != WebSocketFrameTypes.Text)
			{
				return null;
			}
			if (Data.Length <= maxFragmentSize)
			{
				return null;
			}
			IsFinal = false;
			Header &= 127;
			int num = Data.Length / maxFragmentSize + ((Data.Length % maxFragmentSize == 0) ? (-1) : 0);
			WebSocketFrame[] array = new WebSocketFrame[num];
			ulong num3;
			for (ulong num2 = maxFragmentSize; num2 < (ulong)Data.Length; num2 += num3)
			{
				num3 = Math.Min(maxFragmentSize, (ulong)Data.Length - num2);
				array[array.Length - num--] = new WebSocketFrame(null, WebSocketFrameTypes.Continuation, Data, num2, num3, num2 + num3 >= (ulong)Data.Length, useExtensions: false);
			}
			byte[] array2 = new byte[maxFragmentSize];
			Array.Copy(Data, 0, array2, 0, maxFragmentSize);
			Data = array2;
			return array;
		}
	}
	public sealed class WebSocketFrameReader
	{
		public byte Header { get; private set; }

		public bool IsFinal { get; private set; }

		public WebSocketFrameTypes Type { get; private set; }

		public bool HasMask { get; private set; }

		public ulong Length { get; private set; }

		public byte[] Mask { get; private set; }

		public byte[] Data { get; private set; }

		public string DataAsText { get; private set; }

		internal void Read(Stream stream)
		{
			Header = ReadByte(stream);
			IsFinal = (Header & 0x80) != 0;
			Type = (WebSocketFrameTypes)(Header & 0xF);
			byte b = ReadByte(stream);
			HasMask = (b & 0x80) != 0;
			Length = (ulong)(b & 0x7F);
			if (Length == 126)
			{
				byte[] array = new byte[2];
				stream.ReadBuffer(array);
				if (BitConverter.IsLittleEndian)
				{
					Array.Reverse((Array)array, 0, array.Length);
				}
				Length = BitConverter.ToUInt16(array, 0);
			}
			else if (Length == 127)
			{
				byte[] array2 = new byte[8];
				stream.ReadBuffer(array2);
				if (BitConverter.IsLittleEndian)
				{
					Array.Reverse((Array)array2, 0, array2.Length);
				}
				Length = BitConverter.ToUInt64(array2, 0);
			}
			if (HasMask)
			{
				Mask = new byte[4];
				if (stream.Read(Mask, 0, 4) < Mask.Length)
				{
					throw ExceptionHelper.ServerClosedTCPStream();
				}
			}
			Data = new byte[Length];
			if (Length == 0)
			{
				return;
			}
			int num = 0;
			do
			{
				int num2 = stream.Read(Data, num, Data.Length - num);
				if (num2 <= 0)
				{
					throw ExceptionHelper.ServerClosedTCPStream();
				}
				num += num2;
			}
			while (num < Data.Length);
			if (HasMask)
			{
				for (int i = 0; i < Data.Length; i++)
				{
					Data[i] ^= Mask[i % 4];
				}
			}
		}

		private byte ReadByte(Stream stream)
		{
			int num = stream.ReadByte();
			if (num < 0)
			{
				throw ExceptionHelper.ServerClosedTCPStream();
			}
			return (byte)num;
		}

		public void Assemble(List<WebSocketFrameReader> fragments)
		{
			fragments.Add(this);
			ulong num = 0uL;
			for (int i = 0; i < fragments.Count; i++)
			{
				num += fragments[i].Length;
			}
			byte[] array = new byte[num];
			ulong num2 = 0uL;
			for (int j = 0; j < fragments.Count; j++)
			{
				Array.Copy(fragments[j].Data, 0, array, (int)num2, (int)fragments[j].Length);
				num2 += fragments[j].Length;
			}
			Type = fragments[0].Type;
			Header = fragments[0].Header;
			Length = num;
			Data = array;
		}

		public void DecodeWithExtensions(WebSocket webSocket)
		{
			if (webSocket.Extensions != null)
			{
				for (int i = 0; i < webSocket.Extensions.Length; i++)
				{
					IExtension extension = webSocket.Extensions[i];
					if (extension != null)
					{
						Data = extension.Decode(Header, Data);
					}
				}
			}
			if (Type == WebSocketFrameTypes.Text && Data != null)
			{
				DataAsText = Encoding.UTF8.GetString(Data, 0, Data.Length);
			}
		}
	}
	public enum WebSocketFrameTypes : byte
	{
		Continuation = 0,
		Text = 1,
		Binary = 2,
		ConnectionClose = 8,
		Ping = 9,
		Pong = 10
	}
}
namespace BestHTTP.WebSocket
{
	public enum WebSocketStates : byte
	{
		Connecting,
		Open,
		Closing,
		Closed,
		Unknown
	}
	public delegate void OnWebSocketOpenDelegate(WebSocket webSocket);
	public delegate void OnWebSocketMessageDelegate(WebSocket webSocket, string message);
	public delegate void OnWebSocketBinaryDelegate(WebSocket webSocket, byte[] data);
	public delegate void OnWebSocketClosedDelegate(WebSocket webSocket, ushort code, string message);
	public delegate void OnWebSocketErrorDelegate(WebSocket webSocket, Exception ex);
	public delegate void OnWebSocketErrorDescriptionDelegate(WebSocket webSocket, string reason);
	public delegate void OnWebSocketIncompleteFrameDelegate(WebSocket webSocket, WebSocketFrameReader frame);
	public sealed class WebSocket
	{
		public OnWebSocketOpenDelegate OnOpen;

		public OnWebSocketMessageDelegate OnMessage;

		public OnWebSocketBinaryDelegate OnBinary;

		public OnWebSocketClosedDelegate OnClosed;

		public OnWebSocketErrorDelegate OnError;

		public OnWebSocketErrorDescriptionDelegate OnErrorDesc;

		public OnWebSocketIncompleteFrameDelegate OnIncompleteFrame;

		private bool requestSent;

		private WebSocketResponse webSocket;

		public WebSocketStates State { get; private set; }

		public bool IsOpen => webSocket != null && !webSocket.IsClosed;

		public int BufferedAmount => webSocket.BufferedAmount;

		public bool StartPingThread { get; set; }

		public int PingFrequency { get; set; }

		public TimeSpan CloseAfterNoMesssage { get; set; }

		public HTTPRequest InternalRequest { get; private set; }

		public IExtension[] Extensions { get; private set; }

		public int Latency => webSocket.Latency;

		public WebSocket(Uri uri)
			: this(uri, string.Empty, string.Empty)
		{
			Extensions = new IExtension[1]
			{
				new PerMessageCompression(CompressionLevel.Default, clientNoContextTakeover: false, serverNoContextTakeover: false, 15, 15, 5)
			};
		}

		public WebSocket(Uri uri, string origin, string protocol, params IExtension[] extensions)
		{
			string text = ((!HTTPProtocolFactory.IsSecureProtocol(uri)) ? "ws" : "wss");
			int num = ((uri.Port != -1) ? uri.Port : ((!text.Equals("wss", StringComparison.OrdinalIgnoreCase)) ? 80 : 443));
			uri = new Uri(text + "://" + uri.Host + ":" + num + uri.GetRequestPathAndQueryURL());
			PingFrequency = 1000;
			CloseAfterNoMesssage = TimeSpan.FromSeconds(10.0);
			InternalRequest = new HTTPRequest(uri, OnInternalRequestCallback);
			InternalRequest.OnUpgraded = OnInternalRequestUpgraded;
			if (uri.Port != 80)
			{
				InternalRequest.SetHeader("Host", uri.Host + ":" + uri.Port);
			}
			else
			{
				InternalRequest.SetHeader("Host", uri.Host);
			}
			InternalRequest.SetHeader("Upgrade", "websocket");
			InternalRequest.SetHeader("Connection", "keep-alive, Upgrade");
			InternalRequest.SetHeader("Sec-WebSocket-Key", GetSecKey(new object[4]
			{
				this,
				InternalRequest,
				uri,
				new object()
			}));
			if (!string.IsNullOrEmpty(origin))
			{
				InternalRequest.SetHeader("Origin", origin);
			}
			InternalRequest.SetHeader("Sec-WebSocket-Version", "13");
			if (!string.IsNullOrEmpty(protocol))
			{
				InternalRequest.SetHeader("Sec-WebSocket-Protocol", protocol);
			}
			InternalRequest.SetHeader("Cache-Control", "no-cache");
			InternalRequest.SetHeader("Pragma", "no-cache");
			Extensions = extensions;
			InternalRequest.DisableCache = true;
			InternalRequest.DisableRetry = true;
			InternalRequest.TryToMinimizeTCPLatency = true;
			if (HTTPManager.Proxy != null)
			{
				InternalRequest.Proxy = new HTTPProxy(HTTPManager.Proxy.Address, HTTPManager.Proxy.Credentials, isTransparent: false, sendWholeUri: false, HTTPManager.Proxy.NonTransparentForHTTPS);
			}
			HTTPManager.Setup();
		}

		private void OnInternalRequestCallback(HTTPRequest req, HTTPResponse resp)
		{
			string empty = string.Empty;
			switch (req.State)
			{
			default:
				return;
			case HTTPRequestStates.Finished:
				if (resp.IsSuccess || resp.StatusCode == 101)
				{
					HTTPManager.Logger.Information("WebSocket", $"Request finished. Status Code: {resp.StatusCode.ToString()} Message: {resp.Message}");
					return;
				}
				empty = $"Request Finished Successfully, but the server sent an error. Status Code: {resp.StatusCode}-{resp.Message} Message: {resp.DataAsText}";
				break;
			case HTTPRequestStates.Error:
				empty = "Request Finished with Error! " + ((req.Exception == null) ? string.Empty : ("Exception: " + req.Exception.Message + req.Exception.StackTrace));
				break;
			case HTTPRequestStates.Aborted:
				empty = "Request Aborted!";
				break;
			case HTTPRequestStates.ConnectionTimedOut:
				empty = "Connection Timed Out!";
				break;
			case HTTPRequestStates.TimedOut:
				empty = "Processing the request Timed Out!";
				break;
			}
			if (State != WebSocketStates.Connecting || !string.IsNullOrEmpty(empty))
			{
				if (OnError != null)
				{
					OnError(this, req.Exception);
				}
				if (OnErrorDesc != null)
				{
					OnErrorDesc(this, empty);
				}
				if (OnError == null && OnErrorDesc == null)
				{
					HTTPManager.Logger.Error("WebSocket", empty);
				}
			}
			else if (OnClosed != null)
			{
				OnClosed(this, 1000, "Closed while opening");
			}
			if (!req.IsKeepAlive && resp != null && resp is WebSocketResponse)
			{
				(resp as WebSocketResponse).CloseStream();
			}
		}

		private void OnInternalRequestUpgraded(HTTPRequest req, HTTPResponse resp)
		{
			webSocket = resp as WebSocketResponse;
			if (webSocket == null)
			{
				if (OnError != null)
				{
					OnError(this, req.Exception);
				}
				if (OnErrorDesc != null)
				{
					string reason = string.Empty;
					if (req.Exception != null)
					{
						reason = req.Exception.Message + " " + req.Exception.StackTrace;
					}
					OnErrorDesc(this, reason);
				}
				State = WebSocketStates.Closed;
				return;
			}
			if (State == WebSocketStates.Closed)
			{
				webSocket.CloseStream();
				return;
			}
			webSocket.WebSocket = this;
			if (Extensions != null)
			{
				for (int i = 0; i < Extensions.Length; i++)
				{
					IExtension extension = Extensions[i];
					try
					{
						if (extension != null && !extension.ParseNegotiation(webSocket))
						{
							Extensions[i] = null;
						}
					}
					catch (Exception ex)
					{
						HTTPManager.Logger.Exception("WebSocket", "ParseNegotiation", ex);
						Extensions[i] = null;
					}
				}
			}
			State = WebSocketStates.Open;
			if (OnOpen != null)
			{
				try
				{
					OnOpen(this);
				}
				catch (Exception ex2)
				{
					HTTPManager.Logger.Exception("WebSocket", "OnOpen", ex2);
				}
			}
			webSocket.OnText = delegate(WebSocketResponse ws, string msg)
			{
				if (OnMessage != null)
				{
					OnMessage(this, msg);
				}
			};
			webSocket.OnBinary = delegate(WebSocketResponse ws, byte[] bin)
			{
				if (OnBinary != null)
				{
					OnBinary(this, bin);
				}
			};
			webSocket.OnClosed = delegate(WebSocketResponse ws, ushort code, string msg)
			{
				State = WebSocketStates.Closed;
				if (OnClosed != null)
				{
					OnClosed(this, code, msg);
				}
			};
			if (OnIncompleteFrame != null)
			{
				webSocket.OnIncompleteFrame = delegate(WebSocketResponse ws, WebSocketFrameReader frame)
				{
					if (OnIncompleteFrame != null)
					{
						OnIncompleteFrame(this, frame);
					}
				};
			}
			if (StartPingThread)
			{
				webSocket.StartPinging(Math.Max(PingFrequency, 100));
			}
			webSocket.StartReceive();
		}

		public void Open()
		{
			if (requestSent)
			{
				throw new InvalidOperationException("Open already called! You can't reuse this WebSocket instance!");
			}
			if (Extensions != null)
			{
				try
				{
					for (int i = 0; i < Extensions.Length; i++)
					{
						Extensions[i]?.AddNegotiation(InternalRequest);
					}
				}
				catch (Exception ex)
				{
					HTTPManager.Logger.Exception("WebSocket", "Open", ex);
				}
			}
			InternalRequest.Send();
			requestSent = true;
			State = WebSocketStates.Connecting;
		}

		public void Send(string message)
		{
			if (IsOpen)
			{
				webSocket.Send(message);
			}
		}

		public void Send(byte[] buffer)
		{
			if (IsOpen)
			{
				webSocket.Send(buffer);
			}
		}

		public void Send(byte[] buffer, ulong offset, ulong count)
		{
			if (IsOpen)
			{
				webSocket.Send(buffer, offset, count);
			}
		}

		public void Send(WebSocketFrame frame)
		{
			if (IsOpen)
			{
				webSocket.Send(frame);
			}
		}

		public void Close()
		{
			if ((int)State >= 2)
			{
				return;
			}
			if (State == WebSocketStates.Connecting)
			{
				State = WebSocketStates.Closed;
				if (OnClosed != null)
				{
					OnClosed(this, 1005, string.Empty);
				}
			}
			else
			{
				State = WebSocketStates.Closing;
				webSocket.Close();
			}
		}

		public void Close(ushort code, string message)
		{
			if (IsOpen)
			{
				webSocket.Close(code, message);
			}
		}

		public static byte[] EncodeCloseData(ushort code, string message)
		{
			int byteCount = Encoding.UTF8.GetByteCount(message);
			using MemoryStream memoryStream = new MemoryStream(2 + byteCount);
			byte[] bytes = BitConverter.GetBytes(code);
			if (BitConverter.IsLittleEndian)
			{
				Array.Reverse((Array)bytes, 0, bytes.Length);
			}
			memoryStream.Write(bytes, 0, bytes.Length);
			bytes = Encoding.UTF8.GetBytes(message);
			memoryStream.Write(bytes, 0, bytes.Length);
			return memoryStream.ToArray();
		}

		private string GetSecKey(object[] from)
		{
			byte[] array = new byte[16];
			int num = 0;
			for (int i = 0; i < from.Length; i++)
			{
				byte[] bytes = BitConverter.GetBytes(from[i].GetHashCode());
				for (int j = 0; j < bytes.Length; j++)
				{
					if (num >= array.Length)
					{
						break;
					}
					array[num++] = bytes[j];
				}
			}
			return Convert.ToBase64String(array);
		}
	}
	public sealed class WebSocketResponse : HTTPResponse, IHeartbeat, IProtocol
	{
		public static int RTTBufferCapacity = 5;

		public Action<WebSocketResponse, string> OnText;

		public Action<WebSocketResponse, byte[]> OnBinary;

		public Action<WebSocketResponse, WebSocketFrameReader> OnIncompleteFrame;

		public Action<WebSocketResponse, ushort, string> OnClosed;

		private int _bufferedAmount;

		private List<WebSocketFrameReader> IncompleteFrames = new List<WebSocketFrameReader>();

		private List<WebSocketFrameReader> CompletedFrames = new List<WebSocketFrameReader>();

		private List<WebSocketFrameReader> frameCache = new List<WebSocketFrameReader>();

		private WebSocketFrameReader CloseFrame;

		private object FrameLock = new object();

		private object SendLock = new object();

		private List<WebSocketFrame> unsentFrames = new List<WebSocketFrame>();

		private AutoResetEvent newFrameSignal = new AutoResetEvent(initialState: false);

		private volatile bool sendThreadCreated;

		private volatile bool closeSent;

		private volatile bool closed;

		private DateTime lastPing = DateTime.MinValue;

		private DateTime lastMessage = DateTime.MinValue;

		private BestHTTP.Extensions.CircularBuffer<int> rtts = new BestHTTP.Extensions.CircularBuffer<int>(RTTBufferCapacity);

		public WebSocket WebSocket { get; internal set; }

		public bool IsClosed => closed;

		public TimeSpan PingFrequnecy { get; private set; }

		public ushort MaxFragmentSize { get; private set; }

		public int BufferedAmount => _bufferedAmount;

		public int Latency { get; private set; }

		internal WebSocketResponse(HTTPRequest request, Stream stream, bool isStreamed, bool isFromCache)
			: base(request, stream, isStreamed, isFromCache)
		{
			base.IsClosedManually = true;
			closed = false;
			MaxFragmentSize = 32767;
		}

		internal void StartReceive()
		{
			if (base.IsUpgraded)
			{
				ThreadPool.QueueUserWorkItem(ReceiveThreadFunc);
			}
		}

		internal void CloseStream()
		{
			HTTPManager.GetConnectionWith(baseRequest)?.Abort(HTTPConnectionStates.Closed);
		}

		public void Send(string message)
		{
			if (message == null)
			{
				throw new ArgumentNullException("message must not be null!");
			}
			byte[] bytes = Encoding.UTF8.GetBytes(message);
			Send(new WebSocketFrame(WebSocket, WebSocketFrameTypes.Text, bytes));
		}

		public void Send(byte[] data)
		{
			if (data == null)
			{
				throw new ArgumentNullException("data must not be null!");
			}
			WebSocketFrame webSocketFrame = new WebSocketFrame(WebSocket, WebSocketFrameTypes.Binary, data);
			if (webSocketFrame.Data != null && webSocketFrame.Data.Length > MaxFragmentSize)
			{
				WebSocketFrame[] array = webSocketFrame.Fragment(MaxFragmentSize);
				lock (SendLock)
				{
					Send(webSocketFrame);
					if (array != null)
					{
						for (int i = 0; i < array.Length; i++)
						{
							Send(array[i]);
						}
					}
					return;
				}
			}
			Send(webSocketFrame);
		}

		public void Send(byte[] data, ulong offset, ulong count)
		{
			if (data == null)
			{
				throw new ArgumentNullException("data must not be null!");
			}
			if (offset + count > (ulong)data.Length)
			{
				throw new ArgumentOutOfRangeException("offset + count >= data.Length");
			}
			WebSocketFrame webSocketFrame = new WebSocketFrame(WebSocket, WebSocketFrameTypes.Binary, data, offset, count, isFinal: true, useExtensions: true);
			if (webSocketFrame.Data != null && webSocketFrame.Data.Length > MaxFragmentSize)
			{
				WebSocketFrame[] array = webSocketFrame.Fragment(MaxFragmentSize);
				lock (SendLock)
				{
					Send(webSocketFrame);
					if (array != null)
					{
						for (int i = 0; i < array.Length; i++)
						{
							Send(array[i]);
						}
					}
					return;
				}
			}
			Send(webSocketFrame);
		}

		public void Send(WebSocketFrame frame)
		{
			if (frame == null)
			{
				throw new ArgumentNullException("frame is null!");
			}
			if (closed || closeSent)
			{
				return;
			}
			lock (SendLock)
			{
				unsentFrames.Add(frame);
				if (!sendThreadCreated)
				{
					HTTPManager.Logger.Information("WebSocketResponse", "Send - Creating thread");
					ThreadPool.QueueUserWorkItem(SendThreadFunc);
					sendThreadCreated = true;
				}
			}
			Interlocked.Add(ref _bufferedAmount, (frame.Data != null) ? frame.Data.Length : 0);
			newFrameSignal.Set();
		}

		public void Insert(WebSocketFrame frame)
		{
			if (frame == null)
			{
				throw new ArgumentNullException("frame is null!");
			}
			if (closed || closeSent)
			{
				return;
			}
			lock (SendLock)
			{
				unsentFrames.Insert(0, frame);
				if (!sendThreadCreated)
				{
					HTTPManager.Logger.Information("WebSocketResponse", "Insert - Creating thread");
					ThreadPool.QueueUserWorkItem(SendThreadFunc);
					sendThreadCreated = true;
				}
			}
			Interlocked.Add(ref _bufferedAmount, (frame.Data != null) ? frame.Data.Length : 0);
			newFrameSignal.Set();
		}

		public void SendNow(WebSocketFrame frame)
		{
			if (frame == null)
			{
				throw new ArgumentNullException("frame is null!");
			}
			if (!closed && !closeSent)
			{
				byte[] array = frame.Get();
				Stream.Write(array, 0, array.Length);
				Stream.Flush();
			}
		}

		public void Close()
		{
			Close(1000, "Bye!");
		}

		public void Close(ushort code, string msg)
		{
			if (!closed)
			{
				lock (SendLock)
				{
					unsentFrames.Clear();
				}
				Interlocked.Exchange(ref _bufferedAmount, 0);
				Send(new WebSocketFrame(WebSocket, WebSocketFrameTypes.ConnectionClose, WebSocket.EncodeCloseData(code, msg)));
			}
		}

		public void StartPinging(int frequency)
		{
			if (frequency < 100)
			{
				throw new ArgumentException("frequency must be at least 100 milliseconds!");
			}
			PingFrequnecy = TimeSpan.FromMilliseconds(frequency);
			lastMessage = DateTime.UtcNow;
			SendPing();
			HTTPManager.Heartbeats.Subscribe(this);
			HTTPUpdateDelegator.OnApplicationForegroundStateChanged = (Action<bool>)Delegate.Combine(HTTPUpdateDelegator.OnApplicationForegroundStateChanged, new Action<bool>(OnApplicationForegroundStateChanged));
		}

		private void SendThreadFunc(object param)
		{
			List<WebSocketFrame> list = new List<WebSocketFrame>();
			try
			{
				while (!closed && !closeSent)
				{
					newFrameSignal.WaitOne();
					try
					{
						lock (SendLock)
						{
							for (int num = unsentFrames.Count - 1; num >= 0; num--)
							{
								list.Add(unsentFrames[num]);
							}
							unsentFrames.Clear();
						}
						while (list.Count > 0)
						{
							WebSocketFrame webSocketFrame = list[list.Count - 1];
							list.RemoveAt(list.Count - 1);
							if (!closeSent)
							{
								byte[] array = webSocketFrame.Get();
								Stream.Write(array, 0, array.Length);
								if (webSocketFrame.Type == WebSocketFrameTypes.ConnectionClose)
								{
									closeSent = true;
								}
							}
							Interlocked.Add(ref _bufferedAmount, -webSocketFrame.Data.Length);
						}
						Stream.Flush();
					}
					catch (Exception exception)
					{
						if (HTTPUpdateDelegator.IsCreated)
						{
							baseRequest.Exception = exception;
							baseRequest.State = HTTPRequestStates.Error;
						}
						else
						{
							baseRequest.State = HTTPRequestStates.Aborted;
						}
						closed = true;
					}
				}
			}
			finally
			{
				sendThreadCreated = false;
				HTTPManager.Logger.Information("WebSocketResponse", "SendThread - Closed!");
			}
		}

		private void ReceiveThreadFunc(object param)
		{
			try
			{
				while (!closed)
				{
					try
					{
						WebSocketFrameReader webSocketFrameReader = new WebSocketFrameReader();
						webSocketFrameReader.Read(Stream);
						lastMessage = DateTime.UtcNow;
						if (webSocketFrameReader.HasMask)
						{
							Close(1002, "Protocol Error: masked frame received from server!");
							continue;
						}
						if (!webSocketFrameReader.IsFinal)
						{
							if (OnIncompleteFrame == null)
							{
								IncompleteFrames.Add(webSocketFrameReader);
								continue;
							}
							lock (FrameLock)
							{
								CompletedFrames.Add(webSocketFrameReader);
							}
							continue;
						}
						switch (webSocketFrameReader.Type)
						{
						case WebSocketFrameTypes.Continuation:
							if (OnIncompleteFrame == null)
							{
								webSocketFrameReader.Assemble(IncompleteFrames);
								IncompleteFrames.Clear();
								goto case WebSocketFrameTypes.Text;
							}
							lock (FrameLock)
							{
								CompletedFrames.Add(webSocketFrameReader);
							}
							break;
						case WebSocketFrameTypes.Text:
						case WebSocketFrameTypes.Binary:
							webSocketFrameReader.DecodeWithExtensions(WebSocket);
							lock (FrameLock)
							{
								CompletedFrames.Add(webSocketFrameReader);
							}
							break;
						case WebSocketFrameTypes.Ping:
							if (!closeSent && !closed)
							{
								Send(new WebSocketFrame(WebSocket, WebSocketFrameTypes.Pong, webSocketFrameReader.Data));
							}
							break;
						case WebSocketFrameTypes.Pong:
							try
							{
								long num = BitConverter.ToInt64(webSocketFrameReader.Data, 0);
								TimeSpan timeSpan = TimeSpan.FromTicks(lastMessage.Ticks - num);
								rtts.Add((int)timeSpan.TotalMilliseconds);
								Latency = CalculateLatency();
							}
							catch
							{
							}
							break;
						case WebSocketFrameTypes.ConnectionClose:
							CloseFrame = webSocketFrameReader;
							if (!closeSent)
							{
								Send(new WebSocketFrame(WebSocket, WebSocketFrameTypes.ConnectionClose, null));
							}
							closed = true;
							break;
						}
					}
					catch (ThreadAbortException)
					{
						IncompleteFrames.Clear();
						baseRequest.State = HTTPRequestStates.Aborted;
						closed = true;
						newFrameSignal.Set();
					}
					catch (Exception exception)
					{
						if (HTTPUpdateDelegator.IsCreated)
						{
							baseRequest.Exception = exception;
							baseRequest.State = HTTPRequestStates.Error;
						}
						else
						{
							baseRequest.State = HTTPRequestStates.Aborted;
						}
						closed = true;
						newFrameSignal.Set();
					}
				}
			}
			finally
			{
				HTTPManager.Heartbeats.Unsubscribe(this);
				HTTPUpdateDelegator.OnApplicationForegroundStateChanged = (Action<bool>)Delegate.Remove(HTTPUpdateDelegator.OnApplicationForegroundStateChanged, new Action<bool>(OnApplicationForegroundStateChanged));
				HTTPManager.Logger.Information("WebSocketResponse", "ReceiveThread - Closed!");
			}
		}

		void IProtocol.HandleEvents()
		{
			frameCache.Clear();
			lock (FrameLock)
			{
				frameCache.AddRange(CompletedFrames);
				CompletedFrames.Clear();
			}
			for (int i = 0; i < frameCache.Count; i++)
			{
				WebSocketFrameReader webSocketFrameReader = frameCache[i];
				try
				{
					WebSocketFrameTypes type = webSocketFrameReader.Type;
					if (type == WebSocketFrameTypes.Continuation)
					{
						goto IL_007f;
					}
					if (type != WebSocketFrameTypes.Text)
					{
						if (type == WebSocketFrameTypes.Binary)
						{
							if (!webSocketFrameReader.IsFinal)
							{
								goto IL_007f;
							}
							if (OnBinary != null)
							{
								OnBinary(this, webSocketFrameReader.Data);
							}
						}
					}
					else
					{
						if (!webSocketFrameReader.IsFinal)
						{
							goto IL_007f;
						}
						if (OnText != null)
						{
							OnText(this, webSocketFrameReader.DataAsText);
						}
					}
					goto end_IL_005b;
					IL_007f:
					if (OnIncompleteFrame != null)
					{
						OnIncompleteFrame(this, webSocketFrameReader);
					}
					end_IL_005b:;
				}
				catch (Exception ex)
				{
					HTTPManager.Logger.Exception("WebSocketResponse", "HandleEvents", ex);
				}
			}
			frameCache.Clear();
			if (!IsClosed || OnClosed == null || baseRequest.State != HTTPRequestStates.Processing)
			{
				return;
			}
			try
			{
				ushort arg = 0;
				string arg2 = string.Empty;
				if (CloseFrame != null && CloseFrame.Data != null && CloseFrame.Data.Length >= 2)
				{
					if (BitConverter.IsLittleEndian)
					{
						Array.Reverse((Array)CloseFrame.Data, 0, 2);
					}
					arg = BitConverter.ToUInt16(CloseFrame.Data, 0);
					if (CloseFrame.Data.Length > 2)
					{
						arg2 = Encoding.UTF8.GetString(CloseFrame.Data, 2, CloseFrame.Data.Length - 2);
					}
				}
				OnClosed(this, arg, arg2);
			}
			catch (Exception ex2)
			{
				HTTPManager.Logger.Exception("WebSocketResponse", "HandleEvents - OnClosed", ex2);
			}
		}

		void IHeartbeat.OnHeartbeatUpdate(TimeSpan dif)
		{
			DateTime utcNow = DateTime.UtcNow;
			if (utcNow - lastPing >= PingFrequnecy)
			{
				SendPing();
			}
			if (utcNow - (lastMessage + PingFrequnecy) > WebSocket.CloseAfterNoMesssage)
			{
				HTTPManager.Logger.Warning("WebSocketResponse", $"No message received in the given time! Closing WebSocket. LastMessage: {lastMessage}, PingFrequency: {PingFrequnecy}, Close After: {WebSocket.CloseAfterNoMesssage}, Now: {utcNow}");
				CloseWithError("No message received in the given time!");
			}
		}

		private void OnApplicationForegroundStateChanged(bool isPaused)
		{
			if (!isPaused)
			{
				lastMessage = DateTime.UtcNow;
			}
		}

		private void SendPing()
		{
			lastPing = DateTime.UtcNow;
			try
			{
				long ticks = DateTime.UtcNow.Ticks;
				byte[] bytes = BitConverter.GetBytes(ticks);
				WebSocketFrame frame = new WebSocketFrame(WebSocket, WebSocketFrameTypes.Ping, bytes);
				Insert(frame);
			}
			catch
			{
				HTTPManager.Logger.Information("WebSocketResponse", "Error while sending PING message! Closing WebSocket.");
				CloseWithError("Error while sending PING message!");
			}
		}

		private void CloseWithError(string message)
		{
			baseRequest.Exception = new Exception(message);
			baseRequest.State = HTTPRequestStates.Error;
			closed = true;
			HTTPManager.Heartbeats.Unsubscribe(this);
			HTTPUpdateDelegator.OnApplicationForegroundStateChanged = (Action<bool>)Delegate.Remove(HTTPUpdateDelegator.OnApplicationForegroundStateChanged, new Action<bool>(OnApplicationForegroundStateChanged));
			newFrameSignal.Set();
			CloseStream();
		}

		private int CalculateLatency()
		{
			if (rtts.Count == 0)
			{
				return 0;
			}
			int num = 0;
			for (int i = 0; i < rtts.Count; i++)
			{
				num += rtts[i];
			}
			return num / rtts.Count;
		}
	}
	public enum WebSocketStausCodes : ushort
	{
		NormalClosure = 1000,
		GoingAway = 1001,
		ProtocolError = 1002,
		WrongDataType = 1003,
		Reserved = 1004,
		NoStatusCode = 1005,
		ClosedAbnormally = 1006,
		DataError = 1007,
		PolicyError = 1008,
		TooBigMessage = 1009,
		ExtensionExpected = 1010,
		WrongRequest = 1011,
		TLSHandshakeError = 1015
	}
}
