bsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">Debug</span>.Log(hub.Name&nbsp;+&nbsp;<span style=\"color:#a31515;\">&quot;&nbsp;invokedFromClient&nbsp;success!&quot;</span>);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;This&nbsp;callback&nbsp;function&nbsp;will&nbsp;be&nbsp;called&nbsp;every&nbsp;time&nbsp;we&nbsp;try&nbsp;to&nbsp;access&nbsp;a&nbsp;protected&nbsp;API&nbsp;while&nbsp;we&nbsp;are&nbsp;using&nbsp;an&nbsp;non-authenticated&nbsp;connection.</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;/summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">private</span>&nbsp;<span style=\"color:blue;\">void</span>&nbsp;OnInvokeFailed(<span style=\"color:#2b91af;\">Hub</span>&nbsp;hub,&nbsp;<span style=\"color:#2b91af;\">ClientMessage</span>&nbsp;originalMessage,&nbsp;<span style=\"color:#2b91af;\">ResultMessage</span>&nbsp;result)\r\n&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">Debug</span>.LogWarning(hub.Name&nbsp;+&nbsp;<span style=\"color:#a31515;\">&quot;&nbsp;&quot;</span>&nbsp;+&nbsp;result.ErrorMessage);\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n<span style=\"color:blue;\">&nbsp;&nbsp;&nbsp;&nbsp;#endregion</span>\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">public</span>&nbsp;<span style=\"color:blue;\">void</span>&nbsp;Draw()\r\n&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Label(<span style=\"color:blue;\">this</span>.Title);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.BeginHorizontal();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Space(20);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;messages.Draw(<span style=\"color:#2b91af;\">Screen</span>.width&nbsp;-&nbsp;20,&nbsp;100);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.EndHorizontal();\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n}</pre>";

		public static string CacheMaintenanceSample = "<pre style=\"font-family:Consolas;font-size:13;color:black;background:silver;\"><span style=\"color:blue;\">using</span>&nbsp;System;\r\n<span style=\"color:blue;\">using</span>&nbsp;System.Collections.Generic;\r\n\r\n<span style=\"color:blue;\">using</span>&nbsp;UnityEngine;\r\n<span style=\"color:blue;\">using</span>&nbsp;BestHTTP;\r\n<span style=\"color:blue;\">using</span>&nbsp;BestHTTP.Caching;\r\n\r\n<span style=\"color:blue;\">public</span>&nbsp;<span style=\"color:blue;\">sealed</span>&nbsp;<span style=\"color:blue;\">class</span>&nbsp;<span style=\"color:#2b91af;\">CacheMaintenanceSample</span>&nbsp;:&nbsp;<span style=\"color:#2b91af;\">MonoBehaviour</span>\r\n{\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;An&nbsp;enum&nbsp;for&nbsp;better&nbsp;readability</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;/summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">enum</span>&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Days,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Hours,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Mins,\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Secs\r\n&nbsp;&nbsp;&nbsp;&nbsp;};\r\n\r\n<span style=\"color:blue;\">&nbsp;&nbsp;&nbsp;&nbsp;#region</span>&nbsp;Private&nbsp;Fields\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;What&nbsp;methode&nbsp;to&nbsp;call&nbsp;on&nbsp;the&nbsp;TimeSpan</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;/summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>&nbsp;deleteOlderType&nbsp;=&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>.Secs;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;The&nbsp;value&nbsp;for&nbsp;the&nbsp;TimeSpan.</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;/summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">int</span>&nbsp;value&nbsp;=&nbsp;10;\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;What&#39;s&nbsp;our&nbsp;maximum&nbsp;cache&nbsp;size</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:gray;\">///</span><span style=\"color:green;\">&nbsp;</span><span style=\"color:gray;\">&lt;/summary&gt;</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">int</span>&nbsp;maxCacheSize&nbsp;=&nbsp;5&nbsp;*&nbsp;1024&nbsp;*&nbsp;1024;\r\n\r\n<span style=\"color:blue;\">&nbsp;&nbsp;&nbsp;&nbsp;#endregion</span>\r\n\r\n<span style=\"color:blue;\">&nbsp;&nbsp;&nbsp;&nbsp;#region</span>&nbsp;Unity&nbsp;Events\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">void</span>&nbsp;OnGUI()\r\n&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUIHelper</span>.DrawArea(<span style=\"color:#2b91af;\">GUIHelper</span>.ClientArea,&nbsp;<span style=\"color:blue;\">true</span>,&nbsp;()&nbsp;=&gt;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.BeginHorizontal();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Label(<span style=\"color:#a31515;\">&quot;Delete&nbsp;cached&nbsp;entities&nbsp;older&nbsp;then&quot;</span>);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Label(value.ToString(),&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.MinWidth(50));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;value&nbsp;=&nbsp;(<span style=\"color:blue;\">int</span>)<span style=\"color:#2b91af;\">GUILayout</span>.HorizontalSlider(value,&nbsp;1,&nbsp;60,&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.MinWidth(100));\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Space(10);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;deleteOlderType&nbsp;=&nbsp;(<span style=\"color:#2b91af;\">DeleteOlderTypes</span>)(<span style=\"color:blue;\">int</span>)<span style=\"color:#2b91af;\">GUILayout</span>.SelectionGrid((<span style=\"color:blue;\">int</span>)deleteOlderType,&nbsp;<span style=\"color:blue;\">new</span>&nbsp;<span style=\"color:blue;\">string</span>[]&nbsp;{&nbsp;<span style=\"color:#a31515;\">&quot;Days&quot;</span>,&nbsp;<span style=\"color:#a31515;\">&quot;Hours&quot;</span>,&nbsp;<span style=\"color:#a31515;\">&quot;Mins&quot;</span>,&nbsp;<span style=\"color:#a31515;\">&quot;Secs&quot;</span>&nbsp;},&nbsp;4);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.FlexibleSpace();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.EndHorizontal();\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Space(10);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.BeginHorizontal();\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Label(<span style=\"color:#a31515;\">&quot;Max&nbsp;Cache&nbsp;Size&nbsp;(bytes):&nbsp;&quot;</span>,&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Width(150));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Label(maxCacheSize.ToString(<span style=\"color:#a31515;\">&quot;N0&quot;</span>),&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Width(70));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;maxCacheSize&nbsp;=&nbsp;(<span style=\"color:blue;\">int</span>)<span style=\"color:#2b91af;\">GUILayout</span>.HorizontalSlider(maxCacheSize,&nbsp;1024,&nbsp;10&nbsp;*&nbsp;1024&nbsp;*&nbsp;1024);\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.EndHorizontal();\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">GUILayout</span>.Space(10);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">if</span>&nbsp;(<span style=\"color:#2b91af;\">GUILayout</span>.Button(<span style=\"color:#a31515;\">&quot;Maintenance&quot;</span>))\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>&nbsp;deleteOlder&nbsp;=&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>.FromDays(14);\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">switch</span>&nbsp;(deleteOlderType)\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;{\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">case</span>&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>.Days:&nbsp;deleteOlder&nbsp;=&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>.FromDays(value);&nbsp;<span style=\"color:blue;\">break</span>;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">case</span>&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>.Hours:&nbsp;deleteOlder&nbsp;=&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>.FromHours(value);&nbsp;<span style=\"color:blue;\">break</span>;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">case</span>&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>.Mins:&nbsp;deleteOlder&nbsp;=&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>.FromMinutes(value);&nbsp;<span style=\"color:blue;\">break</span>;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:blue;\">case</span>&nbsp;<span style=\"color:#2b91af;\">DeleteOlderTypes</span>.Secs:&nbsp;deleteOlder&nbsp;=&nbsp;<span style=\"color:#2b91af;\">TimeSpan</span>.FromSeconds(value);&nbsp;<span style=\"color:blue;\">break</span>;\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:green;\">//&nbsp;Call&nbsp;the&nbsp;BeginMaintainence&nbsp;function.&nbsp;It&nbsp;will&nbsp;run&nbsp;on&nbsp;a&nbsp;thread&nbsp;to&nbsp;do&nbsp;not&nbsp;block&nbsp;the&nbsp;main&nbsp;thread.</span>\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<span style=\"color:#2b91af;\">HTTPCacheService</span>.BeginMaintainence(<span style=\"color:blue;\">new</span>&nbsp;<span style=\"color:#2b91af;\">HTTPCacheMaintananceParams</span>(deleteOlder,&nbsp;(<span style=\"color:blue;\">ulong</span>)maxCacheSize));\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}\r\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;});\r\n&nbsp;&nbsp;&nbsp;&nbsp;}\r\n\r\n<span style=\"color:blue;\">&nbsp;&nbsp;&nbsp;&nbsp;#endregion</span>\r\n}</pre>";
	}
	public static class GUIHelper
	{
		private static GUIStyle centerAlignedLabel;

		private static GUIStyle rightAlignedLabel;

		public static Rect ClientArea;

		private static void Setup()
		{
			if (centerAlignedLabel == null)
			{
				centerAlignedLabel = new GUIStyle(GUI.skin.label);
				centerAlignedLabel.alignment = TextAnchor.MiddleCenter;
				rightAlignedLabel = new GUIStyle(GUI.skin.label);
				rightAlignedLabel.alignment = TextAnchor.MiddleRight;
			}
		}

		public static void DrawArea(Rect area, bool drawHeader, Action action)
		{
			Setup();
			GUI.Box(area, string.Empty);
			GUILayout.BeginArea(area);
			if (drawHeader)
			{
				DrawCenteredText(SampleSelector.SelectedSample.DisplayName);
				GUILayout.Space(5f);
			}
			action?.Invoke();
			GUILayout.EndArea();
		}

		public static void DrawCenteredText(string msg)
		{
			Setup();
			GUILayout.BeginHorizontal();
			GUILayout.FlexibleSpace();
			GUILayout.Label(msg, centerAlignedLabel);
			GUILayout.FlexibleSpace();
			GUILayout.EndHorizontal();
		}

		public static void DrawRow(string key, string value)
		{
			Setup();
			GUILayout.BeginHorizontal();
			GUILayout.Label(key);
			GUILayout.FlexibleSpace();
			GUILayout.Label(value, rightAlignedLabel);
			GUILayout.FlexibleSpace();
			GUILayout.EndHorizontal();
		}
	}
	public class GUIMessageList
	{
		private List<string> messages = new List<string>();

		private Vector2 scrollPos;

		public void Draw()
		{
			Draw(Screen.width, 0f);
		}

		public void Draw(float minWidth, float minHeight)
		{
			scrollPos = GUILayout.BeginScrollView(scrollPos, false, false, GUILayout.MinHeight(minHeight));
			for (int i = 0; i < messages.Count; i++)
			{
				GUILayout.Label(messages[i], GUILayout.MinWidth(minWidth));
			}
			GUILayout.EndScrollView();
		}

		public void Add(string msg)
		{
			messages.Add(msg);
			scrollPos = new Vector2(scrollPos.x, float.MaxValue);
		}

		public void Clear()
		{
			messages.Clear();
		}
	}
	public sealed class AssetBundleSample : UnityEngine.MonoBehaviour
	{
		private const string URL = "https://besthttp.azurewebsites.net/Content/AssetBundle.html";

		private string status = "Waiting for user interaction";

		private AssetBundle cachedBundle;

		private Texture2D texture;

		private bool downloading;

		private void OnGUI()
		{
			GUIHelper.DrawArea(GUIHelper.ClientArea, drawHeader: true, delegate
			{
				GUILayout.Label("Status: " + status);
				if (texture != null)
				{
					GUILayout.Box(texture, GUILayout.MaxHeight(256f));
				}
				if (!downloading && GUILayout.Button("Start Download"))
				{
					UnloadBundle();
					StartCoroutine(DownloadAssetBundle());
				}
			});
		}

		private void OnDestroy()
		{
			UnloadBundle();
		}

		private IEnumerator DownloadAssetBundle()
		{
			downloading = true;
			HTTPRequest request = new HTTPRequest(new Uri("https://besthttp.azurewebsites.net/Content/AssetBundle.html")).Send();
			status = "Download started";
			while (request.State < HTTPRequestStates.Finished)
			{
				yield return new WaitForSeconds(0.1f);
				status += ".";
			}
			switch (request.State)
			{
			case HTTPRequestStates.Finished:
				if (request.Response.IsSuccess)
				{
					status = $"AssetBundle downloaded! Loaded from local cache: {request.Response.IsFromCache.ToString()}";
					AssetBundleCreateRequest async = AssetBundle.LoadFromMemoryAsync(request.Response.Data);
					yield return async;
					yield return StartCoroutine(ProcessAssetBundle(async.assetBundle));
				}
				else
				{
					status = $"Request finished Successfully, but the server sent an error. Status Code: {request.Response.StatusCode}-{request.Response.Message} Message: {request.Response.DataAsText}";
					UnityEngine.Debug.LogWarning(status);
				}
				break;
			case HTTPRequestStates.Error:
				status = "Request Finished with Error! " + ((request.Exception == null) ? "No Exception" : (request.Exception.Message + "\n" + request.Exception.StackTrace));
				UnityEngine.Debug.LogError(status);
				break;
			case HTTPRequestStates.Aborted:
				status = "Request Aborted!";
				UnityEngine.Debug.LogWarning(status);
				break;
			case HTTPRequestStates.ConnectionTimedOut:
				status = "Connection Timed Out!";
				UnityEngine.Debug.LogError(status);
				break;
			case HTTPRequestStates.TimedOut:
				status = "Processing the request Timed Out!";
				UnityEngine.Debug.LogError(status);
				break;
			}
			downloading = false;
		}

		private IEnumerator ProcessAssetBundle(AssetBundle bundle)
		{
			if (!(bundle == null))
			{
				cachedBundle = bundle;
				AssetBundleRequest asyncAsset = cachedBundle.LoadAssetAsync("9443182_orig", typeof(Texture2D));
				yield return asyncAsset;
				texture = asyncAsset.asset as Texture2D;
			}
		}

		private void UnloadBundle()
		{
			if (cachedBundle != null)
			{
				cachedBundle.Unload(unloadAllLoadedObjects: true);
				cachedBundle = null;
			}
		}
	}
	public sealed class LargeFileDownloadSample : UnityEngine.MonoBehaviour
	{
		private const string URL = "http://uk3.testmy.net/dl-102400";

		private HTTPRequest request;

		private string status = string.Empty;

		private float progress;

		private int fragmentSize = 4096;

		private void Awake()
		{
			if (PlayerPrefs.HasKey("DownloadLength"))
			{
				progress = (float)PlayerPrefs.GetInt("DownloadProgress") / (float)PlayerPrefs.GetInt("DownloadLength");
			}
		}

		private void OnDestroy()
		{
			if (request != null && request.State < HTTPRequestStates.Finished)
			{
				request.OnProgress = null;
				request.Callback = null;
				request.Abort();
			}
		}

		private void OnGUI()
		{
			GUIHelper.DrawArea(GUIHelper.ClientArea, drawHeader: true, delegate
			{
				GUILayout.Label("Request status: " + status);
				GUILayout.Space(5f);
				GUILayout.Label(string.Format("Progress: {0:P2} of {1:N0}Mb", progress, PlayerPrefs.GetInt("DownloadLength") / 1048576));
				GUILayout.HorizontalSlider(progress, 0f, 1f);
				GUILayout.Space(50f);
				if (request == null)
				{
					GUILayout.Label($"Desired Fragment Size: {(float)fragmentSize / 1024f:N} KBytes");
					fragmentSize = (int)GUILayout.HorizontalSlider(fragmentSize, 4096f, 10485760f);
					GUILayout.Space(5f);
					string text = ((!PlayerPrefs.HasKey("DownloadProgress")) ? "Start Download" : "Continue Download");
					if (GUILayout.Button(text))
					{
						StreamLargeFileTest();
					}
				}
				else if (request.State == HTTPRequestStates.Processing && GUILayout.Button("Abort Download"))
				{
					request.Abort();
				}
			});
		}

		private void StreamLargeFileTest()
		{
			request = new HTTPRequest(new Uri("http://uk3.testmy.net/dl-102400"), delegate(HTTPRequest req, HTTPResponse resp)
			{
				switch (req.State)
				{
				case HTTPRequestStates.Processing:
					if (!PlayerPrefs.HasKey("DownloadLength"))
					{
						string firstHeaderValue = resp.GetFirstHeaderValue("content-length");
						if (!string.IsNullOrEmpty(firstHeaderValue))
						{
							PlayerPrefs.SetInt("DownloadLength", int.Parse(firstHeaderValue));
						}
					}
					ProcessFragments(resp.GetStreamedFragments());
					status = "Processing";
					break;
				case HTTPRequestStates.Finished:
					if (resp.IsSuccess)
					{
						ProcessFragments(resp.GetStreamedFragments());
						if (resp.IsStreamingFinished)
						{
							status = "Streaming finished!";
							PlayerPrefs.DeleteKey("DownloadProgress");
							PlayerPrefs.Save();
							request = null;
						}
						else
						{
							status = "Processing";
						}
					}
					else
					{
						status = $"Request finished Successfully, but the server sent an error. Status Code: {resp.StatusCode}-{resp.Message} Message: {resp.DataAsText}";
						UnityEngine.Debug.LogWarning(status);
						request = null;
					}
					break;
				case HTTPRequestStates.Error:
					status = "Request Finished with Error! " + ((req.Exception == null) ? "No Exception" : (req.Exception.Message + "\n" + req.Exception.StackTrace));
					UnityEngine.Debug.LogError(status);
					request = null;
					break;
				case HTTPRequestStates.Aborted:
					status = "Request Aborted!";
					UnityEngine.Debug.LogWarning(status);
					request = null;
					break;
				case HTTPRequestStates.ConnectionTimedOut:
					status = "Connection Timed Out!";
					UnityEngine.Debug.LogError(status);
					request = null;
					break;
				case HTTPRequestStates.TimedOut:
					status = "Processing the request Timed Out!";
					UnityEngine.Debug.LogError(status);
					request = null;
					break;
				}
			});
			if (PlayerPrefs.HasKey("DownloadProgress"))
			{
				request.SetRangeHeader(PlayerPrefs.GetInt("DownloadProgress"));
			}
			else
			{
				PlayerPrefs.SetInt("DownloadProgress", 0);
			}
			request.DisableCache = true;
			request.UseStreaming = true;
			request.StreamFragmentSize = fragmentSize;
			request.Send();
		}

		private void ProcessFragments(List<byte[]> fragments)
		{
			if (fragments != null && fragments.Count > 0)
			{
				for (int i = 0; i < fragments.Count; i++)
				{
					int value = PlayerPrefs.GetInt("DownloadProgress") + fragments[i].Length;
					PlayerPrefs.SetInt("DownloadProgress", value);
				}
				PlayerPrefs.Save();
				progress = (float)PlayerPrefs.GetInt("DownloadProgress") / (float)PlayerPrefs.GetInt("DownloadLength");
			}
		}
	}
	public sealed class TextureDownloadSample : UnityEngine.MonoBehaviour
	{
		private const string BaseURL = "https://besthttp.azurewebsites.net/Content/";

		private string[] Images = new string[9] { "One.png", "Two.png", "Three.png", "Four.png", "Five.png", "Six.png", "Seven.png", "Eight.png", "Nine.png" };

		private Texture2D[] Textures = new Texture2D[9];

		private bool allDownloadedFromLocalCache;

		private int finishedCount;

		private Vector2 scrollPos;

		private void Awake()
		{
			HTTPManager.MaxConnectionPerServer = 1;
			for (int i = 0; i < Images.Length; i++)
			{
				Textures[i] = new Texture2D(100, 150);
			}
		}

		private void OnDestroy()
		{
			HTTPManager.MaxConnectionPerServer = 4;
		}

		private void OnGUI()
		{
			GUIHelper.DrawArea(GUIHelper.ClientArea, drawHeader: true, delegate
			{
				scrollPos = GUILayout.BeginScrollView(scrollPos);
				GUILayout.SelectionGrid(0, Textures, 3);
				if (finishedCount == Images.Length && allDownloadedFromLocalCache)
				{
					GUIHelper.DrawCenteredText("All images loaded from the local cache!");
				}
				GUILayout.FlexibleSpace();
				GUILayout.BeginHorizontal();
				GUILayout.Label("Max Connection/Server: ", GUILayout.Width(150f));
				GUILayout.Label(HTTPManager.MaxConnectionPerServer.ToString(), GUILayout.Width(20f));
				HTTPManager.MaxConnectionPerServer = (byte)GUILayout.HorizontalSlider((int)HTTPManager.MaxConnectionPerServer, 1f, 10f);
				GUILayout.EndHorizontal();
				if (GUILayout.Button("Start Download"))
				{
					DownloadImages();
				}
				GUILayout.EndScrollView();
			});
		}

		private void DownloadImages()
		{
			allDownloadedFromLocalCache = true;
			finishedCount = 0;
			for (int i = 0; i < Images.Length; i++)
			{
				Textures[i] = new Texture2D(100, 150);
				HTTPRequest hTTPRequest = new HTTPRequest(new Uri("https://besthttp.azurewebsites.net/Content/" + Images[i]), ImageDownloaded);
				hTTPRequest.Tag = Textures[i];
				hTTPRequest.Send();
			}
		}

		private void ImageDownloaded(HTTPRequest req, HTTPResponse resp)
		{
			finishedCount++;
			switch (req.State)
			{
			case HTTPRequestStates.Finished:
				if (resp.IsSuccess)
				{
					Texture2D tex = req.Tag as Texture2D;
					tex.LoadImage(resp.Data);
					allDownloadedFromLocalCache = allDownloadedFromLocalCache && resp.IsFromCache;
				}
				else
				{
					UnityEngine.Debug.LogWarning($"Request finished Successfully, but the server sent an error. Status Code: {resp.StatusCode}-{resp.Message} Message: {resp.DataAsText}");
				}
				break;
			case HTTPRequestStates.Error:
				UnityEngine.Debug.LogError("Request Finished with Error! " + ((req.Exception == null) ? "No Exception" : (req.Exception.Message + "\n" + req.Exception.StackTrace)));
				break;
			case HTTPRequestStates.Aborted:
				UnityEngine.Debug.LogWarning("Request Aborted!");
				break;
			case HTTPRequestStates.ConnectionTimedOut:
				UnityEngine.Debug.LogError("Connection Timed Out!");
				break;
			case HTTPRequestStates.TimedOut:
				UnityEngine.Debug.LogError("Processing the request Timed Out!");
				break;
			}
		}
	}
}
public sealed class UploadStream : Stream
{
	private MemoryStream ReadBuffer = new MemoryStream();

	private MemoryStream WriteBuffer = new MemoryStream();

	private bool noMoreData;

	private AutoResetEvent ARE = new AutoResetEvent(initialState: false);

	private object locker = new object();

	public string Name { get; private set; }

	private bool IsReadBufferEmpty
	{
		get
		{
			lock (locker)
			{
				return ReadBuffer.Position == ReadBuffer.Length;
			}
		}
	}

	public override bool CanRead
	{
		get
		{
			throw new NotImplementedException();
		}
	}

	public override bool CanSeek
	{
		get
		{
			throw new NotImplementedException();
		}
	}

	public override bool CanWrite
	{
		get
		{
			throw new NotImplementedException();
		}
	}

	public override long Length
	{
		get
		{
			throw new NotImplementedException();
		}
	}

	public override long Position
	{
		get
		{
			throw new NotImplementedException();
		}
		set
		{
			throw new NotImplementedException();
		}
	}

	public UploadStream(string name)
		: this()
	{
		Name = name;
	}

	public UploadStream()
	{
		ReadBuffer = new MemoryStream();
		WriteBuffer = new MemoryStream();
		Name = string.Empty;
	}

	public override int Read(byte[] buffer, int offset, int count)
	{
		if (noMoreData)
		{
			if (ReadBuffer.Position != ReadBuffer.Length)
			{
				return ReadBuffer.Read(buffer, offset, count);
			}
			if (WriteBuffer.Length <= 0)
			{
				HTTPManager.Logger.Information("UploadStream", $"{Name} - Read - End Of Stream");
				return -1;
			}
			SwitchBuffers();
		}
		if (IsReadBufferEmpty)
		{
			ARE.WaitOne();
			lock (locker)
			{
				if (IsReadBufferEmpty && WriteBuffer.Length > 0)
				{
					SwitchBuffers();
				}
			}
		}
		int num = -1;
		lock (locker)
		{
			return ReadBuffer.Read(buffer, offset, count);
		}
	}

	public override void Write(byte[] buffer, int offset, int count)
	{
		if (noMoreData)
		{
			throw new ArgumentException("noMoreData already set!");
		}
		lock (locker)
		{
			WriteBuffer.Write(buffer, offset, count);
			SwitchBuffers();
		}
		ARE.Set();
	}

	public override void Flush()
	{
		Finish();
	}

	protected override void Dispose(bool disposing)
	{
		if (disposing)
		{
			HTTPManager.Logger.Information("UploadStream", $"{Name} - Dispose");
			ReadBuffer.Dispose();
			ReadBuffer = null;
			WriteBuffer.Dispose();
			WriteBuffer = null;
			ARE.Close();
			ARE = null;
		}
		base.Dispose(disposing);
	}

	public void Finish()
	{
		if (noMoreData)
		{
			throw new ArgumentException("noMoreData already set!");
		}
		HTTPManager.Logger.Information("UploadStream", $"{Name} - Finish");
		noMoreData = true;
		ARE.Set();
	}

	private bool SwitchBuffers()
	{
		lock (locker)
		{
			if (ReadBuffer.Position == ReadBuffer.Length)
			{
				WriteBuffer.Seek(0L, SeekOrigin.Begin);
				ReadBuffer.SetLength(0L);
				MemoryStream writeBuffer = WriteBuffer;
				WriteBuffer = ReadBuffer;
				ReadBuffer = writeBuffer;
				return true;
			}
		}
		return false;
	}

	public override long Seek(long offset, SeekOrigin origin)
	{
		throw new NotImplementedException();
	}

	public override void SetLength(long value)
	{
		throw new NotImplementedException();
	}
}
