namespace BestHTTP.SignalRCore.Encoders
{
	public sealed class LitJsonEncoder : IEncoder
	{
		public string Name => "json";

		public LitJsonEncoder()
		{
			JsonMapper.RegisterImporter((ImporterFunc<int, long>)((int input) => input));
			JsonMapper.RegisterImporter((long input) => (int)input);
			JsonMapper.RegisterImporter((double input) => (int)(input + 0.5));
			JsonMapper.RegisterImporter((string input) => Convert.ToDateTime(input).ToUniversalTime());
			JsonMapper.RegisterImporter((double input) => (float)input);
		}

		public T DecodeAs<T>(string text)
		{
			return JsonMapper.ToObject<T>(text);
		}

		public T DecodeAs<T>(byte[] data)
		{
			throw new NotImplementedException();
		}

		public byte[] EncodeAsBinary<T>(T value)
		{
			throw new NotImplementedException();
		}

		public string EncodeAsText<T>(T value)
		{
			return JsonMapper.ToJson(value);
		}

		public object ConvertTo(System.Type toType, object obj)
		{
			string json = JsonMapper.ToJson(obj);
			return JsonMapper.ToObject(toType, json);
		}
	}
}
public class WebSocketSample : UnityEngine.MonoBehaviour
{
	private string address = "wss://echo.websocket.org";

	private string msgToSend = "Hello World!";

	private string Text = string.Empty;

	private BestHTTP.WebSocket.WebSocket webSocket;

	private Vector2 scrollPos;

	private void OnDestroy()
	{
		if (webSocket != null)
		{
			webSocket.Close();
		}
	}

	private void OnGUI()
	{
		GUIHelper.DrawArea(GUIHelper.ClientArea, drawHeader: true, delegate
		{
			scrollPos = GUILayout.BeginScrollView(scrollPos);
			GUILayout.Label(Text);
			GUILayout.EndScrollView();
			GUILayout.Space(5f);
			GUILayout.FlexibleSpace();
			address = GUILayout.TextField(address);
			if (webSocket == null && GUILayout.Button("Open Web Socket"))
			{
				webSocket = new BestHTTP.WebSocket.WebSocket(new Uri(address));
				webSocket.StartPingThread = true;
				if (HTTPManager.Proxy != null)
				{
					webSocket.InternalRequest.Proxy = new HTTPProxy(HTTPManager.Proxy.Address, HTTPManager.Proxy.Credentials, isTransparent: false);
				}
				BestHTTP.WebSocket.WebSocket obj = webSocket;
				obj.OnOpen = (OnWebSocketOpenDelegate)Delegate.Combine(obj.OnOpen, new OnWebSocketOpenDelegate(OnOpen));
				BestHTTP.WebSocket.WebSocket obj2 = webSocket;
				obj2.OnMessage = (OnWebSocketMessageDelegate)Delegate.Combine(obj2.OnMessage, new OnWebSocketMessageDelegate(OnMessageReceived));
				BestHTTP.WebSocket.WebSocket obj3 = webSocket;
				obj3.OnClosed = (OnWebSocketClosedDelegate)Delegate.Combine(obj3.OnClosed, new OnWebSocketClosedDelegate(OnClosed));
				BestHTTP.WebSocket.WebSocket obj4 = webSocket;
				obj4.OnError = (OnWebSocketErrorDelegate)Delegate.Combine(obj4.OnError, new OnWebSocketErrorDelegate(OnError));
				webSocket.Open();
				Text += "Opening Web Socket...\n";
			}
			if (webSocket != null && webSocket.IsOpen)
			{
				GUILayout.Space(10f);
				GUILayout.BeginHorizontal();
				msgToSend = GUILayout.TextField(msgToSend);
				if (GUILayout.Button("Send", GUILayout.MaxWidth(70f)))
				{
					Text += "Sending message...\n";
					webSocket.Send(msgToSend);
				}
				GUILayout.EndHorizontal();
				GUILayout.Space(10f);
				if (GUILayout.Button("Close"))
				{
					webSocket.Close(1000, "Bye!");
				}
			}
		});
	}

	private void OnOpen(BestHTTP.WebSocket.WebSocket ws)
	{
		Text += $"-WebSocket Open!\n";
	}

	private void OnMessageReceived(BestHTTP.WebSocket.WebSocket ws, string message)
	{
		Text += $"-Message received: {message}\n";
	}

	private void OnClosed(BestHTTP.WebSocket.WebSocket ws, ushort code, string message)
	{
		Text += $"-WebSocket closed! Code: {code} Message: {message}\n";
		webSocket = null;
	}

	private void OnError(BestHTTP.WebSocket.WebSocket ws, Exception ex)
	{
		string text = string.Empty;
		if (ws.InternalRequest.Response != null)
		{
			text = $"Status Code from Server: {ws.InternalRequest.Response.StatusCode} and Message: {ws.InternalRequest.Response.Message}";
		}
		Text += string.Format("-An error occured: {0}\n", (ex == null) ? ("Unknown Error " + text) : ex.Message);
		webSocket = null;
	}
}
public interface IQuantizer
{
	bool UseColor32 { get; }

	Color[] Palette { get; }

	void Train(Color[] colors);

	void Train(Color32[] colors);
}
public class NeuQuantQuantizer : IQuantizer
{
	public bool UseColor32 => true;

	public Color[] Palette { get; private set; }

	public void Train(Color[] colors)
	{
		Color32[] array = new Color32[colors.Length];
		for (int i = 0; i < colors.Length; i++)
		{
			ref Color32 reference = ref array[i];
			reference = colors[i];
		}
	}

	public void Train(Color32[] colors)
	{
		byte[] array = new byte[colors.Length * 3];
		for (int i = 0; i < colors.Length; i++)
		{
			array[i * 3] = colors[i].b;
			array[i * 3 + 1] = colors[i].g;
			array[i * 3 + 2] = colors[i].r;
		}
		NeuQuant neuQuant = new NeuQuant(array, array.Length, 10);
		byte[] array2 = neuQuant.Process();
		Color[] array3 = new Color[array2.Length / 3];
		for (int j = 0; j < array3.Length; j++)
		{
			float b = (float)(int)array2[j * 3] / 256f;
			float g = (float)(int)array2[j * 3 + 1] / 256f;
			float r = (float)(int)array2[j * 3 + 2] / 256f;
			ref Color reference = ref array3[j];
			reference = new Color(r, g, b);
		}
		Palette = array3;
	}
}
public class QuantTest : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Texture2D src;

	public Texture2D dstQuant;

	public Texture2D dstGray;

	private void Start()
	{
		Color32[] pixels = src.GetPixels32();
		NeuQuantQuantizer neuQuantQuantizer = new NeuQuantQuantizer();
		neuQuantQuantizer.Train(pixels);
		Color[] palette = neuQuantQuantizer.Palette;
		int[] array = new int[pixels.Length];
		Color32[] array2 = new Color32[pixels.Length];
		for (int i = 0; i < pixels.Length; i++)
		{
			Color color = pixels[i];
			float num = 100f;
			int num2 = 0;
			for (int j = 0; j < palette.Length; j++)
			{
				Color color2 = palette[j];
				float num3 = Mathf.Abs(color2.r - color.r) + Mathf.Abs(color2.g - color.g) + Mathf.Abs(color2.b - color.b);
				if (num3 < num)
				{
					num = num3;
					num2 = j;
				}
			}
			array[i] = num2;
			ref Color32 reference = ref pixels[i];
			reference = palette[num2];
			ref Color32 reference2 = ref array2[i];
			reference2 = new Color32((byte)num2, (byte)num2, (byte)num2, byte.MaxValue);
		}
		dstQuant = new Texture2D(src.width, src.height);
		dstQuant.SetPixels32(pixels);
		dstQuant.Apply();
		dstGray = new Texture2D(src.width, src.height);
		dstGray.SetPixels32(array2);
		dstGray.Apply();
	}
}
public class CaptureGifOnKey : UnityEngine.MonoBehaviour
{
	public enum ButtonType
	{
		KeyCode,
		InputManager,
		Mobile
	}

	public string buttonName = "p";

	public ButtonType buttonType;

	public string dir = "gifs";

	public new string name = "gif";

	public int frames = 30;

	public float frameRate = 10f;

	public int height = 480;

	public float aspect = 1.3333334f;

	public bool lockFramerate;

	[Range(2f, 256f)]
	public int paletteSize = 256;

	public CaptureTheGIF.PaletteMode paletteMode;

	public int maxGifSize;

	public bool restrictDuplicateCaptures = true;

	private void Update()
	{
		bool flag = false;
		switch (buttonType)
		{
		case ButtonType.KeyCode:
		{
			KeyCode key = (KeyCode)System.Enum.Parse(typeof(KeyCode), buttonName, ignoreCase: true);
			flag = Input.GetKeyDown(key);
			break;
		}
		case ButtonType.InputManager:
			flag = Input.GetButtonDown(buttonName);
			break;
		default:
			throw new NotImplementedException("unknown button type: " + buttonType);
		}
		if (flag && (!restrictDuplicateCaptures || !CaptureTheGIF.running))
		{
			CaptureTheGIF.Instance.Capture(frames, (int)(aspect * (float)height), height, frameRate, dir, name, lockFramerate, paletteSize, paletteMode, maxGifSize);
		}
	}
}
