public class Demo : UnityEngine.MonoBehaviour
{
	private float m_WaitTime = 4f;

	private float m_WaitTimeCount;

	private bool m_ShowMoveInButton = true;

	private void Awake()
	{
		if (base.enabled)
		{
			GUIAnimSystemFREE.Instance.m_GUISpeed = 1f;
			GUIAnimSystemFREE.Instance.m_AutoAnimation = false;
		}
	}

	private void Start()
	{
	}

	private void Update()
	{
		if (m_WaitTimeCount > 0f && m_WaitTimeCount <= m_WaitTime)
		{
			m_WaitTimeCount -= UnityEngine.Time.deltaTime;
			if (m_WaitTimeCount <= 0f)
			{
				m_WaitTimeCount = 0f;
				m_ShowMoveInButton = !m_ShowMoveInButton;
			}
		}
	}

	private void OnGUI()
	{
		if (!(m_WaitTimeCount <= 0f))
		{
			return;
		}
		Rect position = new Rect((Screen.width - 100) / 2, (Screen.height - 50) / 2, 100f, 50f);
		if (m_ShowMoveInButton)
		{
			if (GUI.Button(position, "MoveIn"))
			{
				GUIAnimSystemFREE.Instance.MoveIn(base.transform, EffectsOnChildren: true);
				m_WaitTimeCount = m_WaitTime;
			}
		}
		else if (GUI.Button(position, "MoveOut"))
		{
			GUIAnimSystemFREE.Instance.MoveOut(base.transform, EffectsOnChildren: true);
			m_WaitTimeCount = m_WaitTime;
		}
	}
}
namespace UTJ
{
	public static class fcAPI
	{
		public enum fcPixelFormat
		{
			Unknown = 0,
			ChannelMask = 15,
			TypeMask = 240,
			Type_f16 = 16,
			Type_f32 = 32,
			Type_u8 = 48,
			Type_i16 = 64,
			Type_i32 = 80,
			Rf16 = 17,
			RGf16 = 18,
			RGBf16 = 19,
			RGBAf16 = 20,
			Rf32 = 33,
			RGf32 = 34,
			RGBf32 = 35,
			RGBAf32 = 36,
			Ru8 = 49,
			RGu8 = 50,
			RGBu8 = 51,
			RGBAu8 = 52,
			Ri16 = 65,
			RGi16 = 66,
			RGBi16 = 67,
			RGBAi16 = 68,
			Ri32 = 81,
			RGi32 = 82,
			RGBi32 = 83,
			RGBAi32 = 84
		}

		public enum fcDownloadState
		{
			Idle,
			Completed,
			Error,
			InProgress
		}

		public struct fcStream
		{
			public IntPtr ptr;
		}

		public struct fcPngConfig
		{
			public int max_active_tasks;

			public static fcPngConfig default_value => new fcPngConfig
			{
				max_active_tasks = 0
			};
		}

		public struct fcPNGContext
		{
			public IntPtr ptr;
		}

		public struct fcExrConfig
		{
			public int max_active_tasks;

			public static fcExrConfig default_value => new fcExrConfig
			{
				max_active_tasks = 0
			};
		}

		public struct fcEXRContext
		{
			public IntPtr ptr;
		}

		public struct fcGifConfig
		{
			public int width;

			public int height;

			public int num_colors;

			public int max_active_tasks;

			public static fcGifConfig default_value => new fcGifConfig
			{
				width = 320,
				height = 240,
				num_colors = 256,
				max_active_tasks = 0
			};
		}

		public struct fcGIFContext
		{
			public IntPtr ptr;
		}

		public struct fcMP4Config
		{
			public Bool video;

			public Bool audio;

			public Bool video_use_hardware_encoder_if_possible;

			public int video_width;

			public int video_height;

			public int video_bitrate;

			public int video_max_framerate;

			public int video_max_buffers;

			public float audio_scale;

			public int audio_sampling_rate;

			public int audio_num_channels;

			public int audio_bitrate;

			public static fcMP4Config default_value => new fcMP4Config
			{
				video = true,
				audio = false,
				video_use_hardware_encoder_if_possible = true,
				video_width = 320,
				video_height = 240,
				video_bitrate = 256000,
				video_max_framerate = 30,
				video_max_buffers = 8,
				audio_scale = 32767f,
				audio_sampling_rate = 48000,
				audio_num_channels = 2,
				audio_bitrate = 64000
			};
		}

		public struct fcMP4Context
		{
			public IntPtr ptr;
		}

		[DllImport("FrameCapturer")]
		public static extern void fcSetModulePath(string path);

		[DllImport("FrameCapturer")]
		public static extern double fcGetTime();

		[DllImport("FrameCapturer")]
		public static extern fcStream fcCreateFileStream(string path);

		[DllImport("FrameCapturer")]
		public static extern fcStream fcCreateMemoryStream();

		[DllImport("FrameCapturer")]
		public static extern void fcDestroyStream(fcStream s);

		[DllImport("FrameCapturer")]
		public static extern ulong fcStreamGetWrittenSize(fcStream s);

		[DllImport("FrameCapturer")]
		public static extern void fcGuardBegin();

		[DllImport("FrameCapturer")]
		public static extern void fcGuardEnd();

		[DllImport("FrameCapturer")]
		public static extern void fcEraseDeferredCall(int id);

		[DllImport("FrameCapturer")]
		public static extern IntPtr fcGetRenderEventFunc();

		public static void fcGuard(Action body)
		{
			fcGuardBegin();
			body();
			fcGuardEnd();
		}

		public static fcPixelFormat fcGetPixelFormat(RenderTextureFormat v)
		{
			return v switch
			{
				RenderTextureFormat.ARGB32 => fcPixelFormat.RGBAu8, 
				RenderTextureFormat.ARGBHalf => fcPixelFormat.RGBAf16, 
				RenderTextureFormat.RGHalf => fcPixelFormat.RGf16, 
				RenderTextureFormat.RHalf => fcPixelFormat.Rf16, 
				RenderTextureFormat.ARGBFloat => fcPixelFormat.RGBAf32, 
				RenderTextureFormat.RGFloat => fcPixelFormat.RGf32, 
				RenderTextureFormat.RFloat => fcPixelFormat.Rf32, 
				RenderTextureFormat.ARGBInt => fcPixelFormat.RGBAi32, 
				RenderTextureFormat.RGInt => fcPixelFormat.RGi32, 
				RenderTextureFormat.RInt => fcPixelFormat.Ri32, 
				_ => fcPixelFormat.Unknown, 
			};
		}

		public static fcPixelFormat fcGetPixelFormat(TextureFormat v)
		{
			return v switch
			{
				TextureFormat.Alpha8 => fcPixelFormat.Ru8, 
				TextureFormat.RGB24 => fcPixelFormat.RGBu8, 
				TextureFormat.RGBA32 => fcPixelFormat.RGBAu8, 
				TextureFormat.ARGB32 => fcPixelFormat.RGBAu8, 
				TextureFormat.RGBAHalf => fcPixelFormat.RGBAf16, 
				TextureFormat.RGHalf => fcPixelFormat.RGf16, 
				TextureFormat.RHalf => fcPixelFormat.Rf16, 
				TextureFormat.RGBAFloat => fcPixelFormat.RGBAf32, 
				TextureFormat.RGFloat => fcPixelFormat.RGf32, 
				TextureFormat.RFloat => fcPixelFormat.Rf32, 
				_ => fcPixelFormat.Unknown, 
			};
		}

