	public static class FrameCapturerUtils
	{
		public static Mesh CreateFullscreenQuad()
		{
			Vector3[] vertices = new Vector3[4]
			{
				new Vector3(1f, 1f, 0f),
				new Vector3(-1f, 1f, 0f),
				new Vector3(-1f, -1f, 0f),
				new Vector3(1f, -1f, 0f)
			};
			int[] triangles = new int[6] { 0, 1, 2, 2, 3, 0 };
			Mesh mesh = new Mesh();
			mesh.vertices = vertices;
			mesh.triangles = triangles;
			return mesh;
		}
	}
	public struct Bool
	{
		private byte v;

		public static Bool True
		{
			get
			{
				Bool result = default(Bool);
				result.v = 1;
				return result;
			}
		}

		public static implicit operator bool(Bool v)
		{
			return v.v != 0;
		}

		public static implicit operator Bool(bool v)
		{
			Bool result = default(Bool);
			result.v = (byte)(v ? 1 : 0);
			return result;
		}
	}
	[Serializable]
	public class DataPath
	{
		public enum Root
		{
			CurrentDirectory,
			PersistentDataPath,
			StreamingAssetsPath,
			TemporaryCachePath,
			DataPath
		}

		public Root m_root;

		public string m_leaf;

		public DataPath()
		{
		}

		public DataPath(Root root, string leaf)
		{
			m_root = root;
			m_leaf = leaf;
		}

		public string GetPath()
		{
			string text = string.Empty;
			switch (m_root)
			{
			case Root.CurrentDirectory:
				text += ".";
				break;
			case Root.PersistentDataPath:
				text += UnityEngine.Application.persistentDataPath;
				break;
			case Root.StreamingAssetsPath:
				text += UnityEngine.Application.streamingAssetsPath;
				break;
			case Root.TemporaryCachePath:
				text += UnityEngine.Application.temporaryCachePath;
				break;
			case Root.DataPath:
				text += UnityEngine.Application.dataPath;
				break;
			}
			if (m_leaf.Length > 0)
			{
				text += "/";
				text += m_leaf;
			}
			return text;
		}

		public void CreateDirectory()
		{
			Directory.CreateDirectory(GetPath());
		}
	}
	[AddComponentMenu("UTJ/Misc/FixDeltaTime")]
	public class FixDeltaTime : UnityEngine.MonoBehaviour
	{
		public float m_targetFrameRate = 30f;

		public IEnumerator Wait()
		{
			yield return new WaitForEndOfFrame();
			float wt = UnityEngine.Time.maximumDeltaTime;
			while (UnityEngine.Time.realtimeSinceStartup - UnityEngine.Time.unscaledTime < wt)
			{
				Thread.Sleep(1);
			}
		}

		public void ApplyFrameRate()
		{
			UnityEngine.Time.maximumDeltaTime = 1f / m_targetFrameRate;
		}

		private void OnEnable()
		{
			ApplyFrameRate();
		}

		private void Update()
		{
			ApplyFrameRate();
			StartCoroutine(Wait());
		}
	}
}
public class GoogleAnalytics : UnityEngine.MonoBehaviour
{
	public const string GOOGLE_ANALYTICS_CLIENTID_PREF_KEY = "google_analytics_clientid_pref_key";

	public const string GOOGLE_ANALYTICS_SAMPLING_RATIO_KEY = "google_analytics_sampling_ratio_key";

	public const string GOOGLE_ANALYTICS_SYSTEM_INFO_SUBMITED = "system_info_submited";

	public const string SYSTEM_INFO = "SystemInfo";

	private static GoogleAnalytics Instance = null;

	private static string _ClientId;

	private static GoogleAnalyticsClient client = null;

	private static string CurrentLevelName;

	private static bool IsSessionStarted = false;

	private static readonly string[] StackFramesToSkip = new string[4] { "UnityEngine.Application.CallLogCallback", "UnityEngine.DebugLogHandler.", "UnityEngine.Logger.", "UnityEngine.Debug." };

	private static System.Random random = new System.Random((int)DateTime.Now.Ticks);

	private const float TWENTY_MINUTES = 1200f;

	public static float SamplingRatio
	{
		get
		{
			return PlayerPrefs.GetFloat("google_analytics_sampling_ratio_key", 0.02f);
		}
		set
		{
			PlayerPrefs.SetFloat("google_analytics_sampling_ratio_key", value);
		}
	}

	public static GoogleAnalyticsClient Client
	{
		get
		{
			if (client == null)
			{
				StartTracking();
			}
			return client;
		}
	}

	public static string ClientId => _ClientId;

	public static string LoadedLevelName => SceneManager.GetActiveScene().name;

	private static void EvaluateSampling()
	{
		bool randomResult = UnityExtensions.GetRandomResult(SamplingRatio);
		GoogleAnalyticsSettings.Instance.IsDisabled = !randomResult;
		GoogleAnalyticsRequestCache.IsDisabled = GoogleAnalyticsSettings.Instance.IsDisabled;
		UnityEngine.Debug.LogWarning("GA error tracking is " + randomResult);
	}

	private void Awake()
	{
		if (Instance != null)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
			return;
		}
		Instance = this;
		EvaluateSampling();
		GenerateClientId();
		client = new GoogleAnalyticsClient(_ClientId, this);
		if (!IsSessionStarted)
		{
			Client.CreateHit(GoogleAnalyticsHitType.SCREENVIEW);
			Client.StartSession();
			Client.SetUserLanguage(UnityEngine.Application.systemLanguage.ToString());
			Client.SetScreenResolution(Screen.width, Screen.height);
			string action = $"{XRSettings.loadedDeviceName}_{XRDevice.model}";
			Client.SendEventHit("device", action, string.Empty);
			Client.Send();
			IsSessionStarted = true;
		}
		SendFirstScreenHit();
		SubmitSystemInfo();
		if (GoogleAnalyticsSettings.Instance.AutoExceptionTracking)
		{
			UnityEngine.Application.logMessageReceived += HandleLog;
		}
		if (GoogleAnalyticsSettings.Instance.AutoCampaignTracking)
		{
			GA_AndroidTools.RequestReffer();
		}
		SceneManager.sceneLoaded += delegate
		{
			TrackNewLevel();
		};
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= delegate
		{
			TrackNewLevel();
		};
		UnityEngine.Application.logMessageReceived -= HandleLog;
	}

	public static void SetTrackingId(string TrackingId)
	{
		StartTracking();
		client.GenerateHeaders(TrackingId);
	}

	public static void StartTracking()
	{
		if (Instance == null)
		{
			GameObject gameObject = new GameObject("Google Analytics");
			gameObject.AddComponent<GoogleAnalytics>();
		}
	}

	private void OnApplicationPause(bool paused)
	{
		if (GoogleAnalyticsSettings.Instance.AutoAppResumeTracking)
		{
			if (paused)
			{
				Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
				Client.EndSession();
				Client.Send();
			}
			else if (Client != null)
			{
				Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
				Client.StartSession();
				Client.Send();
			}
		}
	}

	private void OnApplicationQuit()
	{
		if (GoogleAnalyticsSettings.Instance.AutoAppQuitTracking)
		{
			GoogleAnalyticsRequestCache.SendCashedRequests();
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			Client.EndSession();
			Client.Send();
		}
	}

	private void HandleLog(string logString, string stackTrace, LogType type)
	{
		ShowErrorInHeadset(logString, type);
		if (!Profiles.LocalProfile.IsJunior() && GoogleAnalyticsSettings.Instance.AutoExceptionTracking)
		{
			if (type == LogType.Error)
			{
				stackTrace = new StackTrace(2).ToString();
				stackTrace = SkipLinesContaining(stackTrace, StackFramesToSkip);
			}
			if (type == LogType.Exception || type == LogType.Error)
			{
				string exceptionDescription = $"{logString}{((!string.IsNullOrEmpty(stackTrace)) ? (Environment.NewLine + stackTrace) : string.Empty)}";
				Client.CreateHit(GoogleAnalyticsHitType.EXCEPTION);
				Client.SetExceptionDescription(exceptionDescription);
				Client.SetScreenName(LoadedLevelName);
				Client.Send();
			}
		}
	}

	private void ShowErrorInHeadset(string logString, LogType type)
	{
		if (false && (type == LogType.Exception || type == LogType.Error))
		{
			DebugVR.LogFormatPersistent(5f, "{0}: {1}", type, logString);
		}
	}

	private static string SkipLinesContaining(string str, params string[] substringsToSkip)
	{
		int num = 0;
		while (num < str.Length)
		{
			int num2 = str.IndexOf('\n', num);
			num2 = ((num2 >= 0) ? (num2 + 1) : str.Length);
			string text = str.Substring(num, num2 - num);
			bool flag = false;
			foreach (string value in substringsToSkip)
			{
				if (text.Contains(value))
				{
					flag = true;
					break;
				}
			}
			if (flag)
			{
				num = num2;
				continue;
			}
			return str.Substring(num);
		}
		return string.Empty;
	}

	private void OnReferalIntentReciver(string referrerString)
	{
		try
		{
			UnityEngine.Debug.Log("[OnReferalIntentReciver] referrerString:" + referrerString);
			int num = referrerString.LastIndexOf('?');
			UnityEngine.Debug.Log("[OnReferalIntentReciver] urlBeginIndex:" + num);
			if (num != -1)
			{
				num++;
				referrerString = referrerString.Substring(num, referrerString.Length - num);
			}
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			string[] array = referrerString.Split('&');
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (text.Equals(string.Empty))
				{
					continue;
				}
				UnityEngine.Debug.Log("[OnReferalIntentReciver] StringParams:kv " + text);
				string[] array3 = text.Split('=');
				string text2 = array3[0];
				string text3 = array3[1];
				if (string.IsNullOrEmpty(text2) || string.IsNullOrEmpty(text3))
				{
					continue;
				}
				switch (text2)
				{
				case "utm_campaign":
					Client.SetCampaignName(text3);
					break;
				case "utm_source":
					Client.SetCampaignSource(text3);
					break;
				case "utm_medium":
					Client.SetCampaignMedium(text3);
					break;
				case "utm_term":
				{
					string[] array4 = text3.Split('+');
					string[] array5 = array4;
					foreach (string keyword in array5)
					{
						Client.AddCampaignKeyword(keyword);
					}
					break;
				}
				case "utm_content":
					Client.SetCampaignContent(text3);
					break;
				case "gclid":
					Client.SetGoogleAdWordsID(text3);
					break;
				}
			}
			Client.Send();
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.Log("OnReferalIntentReciver:: parsing error");
			UnityEngine.Debug.Log(ex.Message);
		}
	}

	public static void SubmitSystemInfo()
	{
		if (GoogleAnalyticsSettings.Instance.SubmitSystemInfoOnFirstLaunch && !PlayerPrefs.HasKey("system_info_submited"))
		{
			PlayerPrefs.SetInt("system_info_submited", 1);
			Client.SendEventHit("SystemInfo", "deviceModel", SystemInfo.deviceModel);
			Client.SendEventHit("SystemInfo", "deviceName", SystemInfo.deviceName);
			Client.SendEventHit("SystemInfo", "deviceType", SystemInfo.deviceType.ToString());
			Client.SendEventHit("SystemInfo", "graphicsDeviceID", SystemInfo.graphicsDeviceID.ToString(), SystemInfo.graphicsDeviceID);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVendorID", SystemInfo.graphicsDeviceVendorID.ToString(), SystemInfo.graphicsDeviceVendorID);
			Client.SendEventHit("SystemInfo", "graphicsDeviceName", SystemInfo.graphicsDeviceName);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVendor", SystemInfo.graphicsDeviceVendor);
			Client.SendEventHit("SystemInfo", "graphicsDeviceVersion", SystemInfo.graphicsDeviceVersion);
			Client.SendEventHit("SystemInfo", "graphicsShaderLevel", SystemInfo.graphicsShaderLevel.ToString(), SystemInfo.graphicsShaderLevel);
			Client.SendEventHit("SystemInfo", "graphicsMemorySize", SystemInfo.graphicsMemorySize + "MB", SystemInfo.graphicsMemorySize);
			Client.SendEventHit("SystemInfo", "systemMemorySize", SystemInfo.systemMemorySize + "MB", SystemInfo.systemMemorySize);
			Client.SendEventHit("SystemInfo", "systemLanguage", UnityEngine.Application.systemLanguage.ToString());
			Client.SendEventHit("SystemInfo", "operatingSystem", SystemInfo.operatingSystem);
			Client.SendEventHit("SystemInfo", "processorType", SystemInfo.processorType);
			Client.SendEventHit("SystemInfo", "processorCount", SystemInfo.processorCount.ToString(), SystemInfo.processorCount);
			Client.SendEventHit("SystemInfo", "supportsAccelerometer", (!SystemInfo.supportsAccelerometer) ? "false" : "true", SystemInfo.supportsAccelerometer ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsLocationService", (!SystemInfo.supportsLocationService) ? "false" : "true", SystemInfo.supportsLocationService ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsVibration", (!SystemInfo.supportsVibration) ? "false" : "true", SystemInfo.supportsVibration ? 1 : 0);
			bool flag = true;
			Client.SendEventHit("SystemInfo", "supportsRenderTextures", (!flag) ? "false" : "true", flag ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsImageEffects", (!SystemInfo.supportsImageEffects) ? "false" : "true", SystemInfo.supportsImageEffects ? 1 : 0);
			Client.SendEventHit("SystemInfo", "supportsShadows", (!SystemInfo.supportsShadows) ? "false" : "true", SystemInfo.supportsShadows ? 1 : 0);
		}
	}

	public static void RestorePrefKeys()
	{
		PlayerPrefs.SetString("google_analytics_clientid_pref_key", _ClientId);
		PlayerPrefs.SetInt("system_info_submited", 1);
	}

	public static void Send(string request)
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			return;
		}
		if (Instance == null)
		{
			UnityEngine.Debug.LogWarning("GoogleAnalytics is destroyed, skipping the request and caching it for later send : " + request);
			GoogleAnalyticsRequestCache.SaveRequest(request);
			return;
		}
		byte[] bytes = Encoding.UTF8.GetBytes(request);
		if (GoogleAnalyticsSettings.Instance.IsRequetsCachingEnabled)
		{
			Instance.StartCoroutine(Instance.SendAnalytics(bytes, request));
		}
		else
		{
			SendSkipCache(request);
		}
	}

	public static void SendSkipCache(string request)
	{
		byte[] bytes = Encoding.UTF8.GetBytes(request);
		Client.GenerateWWW(bytes);
	}

	private IEnumerator SendAnalytics(byte[] data, string cache)
	{
		WWW www = Client.GenerateWWW(data);
		yield return www;
		if (www.error != null)
		{
			GoogleAnalyticsRequestCache.SaveRequest(cache);
		}
		else
		{
			GoogleAnalyticsRequestCache.SendCashedRequests();
		}
	}

	private static void SendFirstScreenHit()
	{
		if (GoogleAnalyticsSettings.Instance.AutoLevelTracking)
		{
			CurrentLevelName = LoadedLevelName;
			Client.CreateHit(GoogleAnalyticsHitType.APPVIEW);
			Client.SetScreenResolution(Screen.currentResolution.width, Screen.currentResolution.height);
			Client.SetViewportSize(Screen.width, Screen.height);
			Client.SetUserLanguage(UnityEngine.Application.systemLanguage.ToString());
			Client.SetScreenName(GoogleAnalyticsSettings.Instance.LevelPrefix + CurrentLevelName + GoogleAnalyticsSettings.Instance.LevelPostfix);
			Client.Send();
		}
	}

	private static void TrackNewLevel()
	{
		if (GoogleAnalyticsSettings.Instance.AutoLevelTracking && !CurrentLevelName.Equals(LoadedLevelName))
		{
			CurrentLevelName = LoadedLevelName;
			Client.SendScreenHit(GoogleAnalyticsSettings.Instance.LevelPrefix + CurrentLevelName + GoogleAnalyticsSettings.Instance.LevelPostfix);
		}
	}

	private static void GenerateClientId()
	{
		if (PlayerPrefs.HasKey("google_analytics_clientid_pref_key"))
		{
			_ClientId = PlayerPrefs.GetString("google_analytics_clientid_pref_key");
			return;
		}
		_ClientId = RandomString(8) + SystemInfo.deviceUniqueIdentifier;
		PlayerPrefs.SetString("google_analytics_clientid_pref_key", _ClientId);
	}

	private static string RandomString(int size)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < size; i++)
		{
			char value = Convert.ToChar(Convert.ToInt32(Math.Floor(26.0 * random.NextDouble() + 65.0)));
			stringBuilder.Append(value);
		}
		return stringBuilder.ToString();
	}

	public void SessionKeepAlive()
	{
		CancelInvoke("PingSessionKeepAlive");
		Invoke("PingSessionKeepAlive", 1200f);
	}

	private void PingSessionKeepAlive()
	{
		UnityEngine.Debug.Log("Session keep alive");
		Client.SendEventHit("session", "keepAlive", string.Empty);
	}
}
public class GoogleAnalyticsClient
{
	private const string PROTOCOL_VERSION = "v=1";

	private const string HTTP_URL = "http://www.google-analytics.com/collect";

	private const string HTTPS_URL = "https://ssl.google-analytics.com/collect";

	public string TrackingID;

	public string ClientID;

	public string AppName;

	public string AppVersion;

	private string DefaultHitData;

	private StringBuilder builder = new StringBuilder(256, 8192);

	private GoogleAnalyticsHitType currentHitType;

	private string DataSendUrl;

	private GoogleAnalytics googleAnalytics;

	public string AnalyticsHost => DataSendUrl;

	public GoogleAnalyticsClient(string anonymousClientID, GoogleAnalytics googleAnalytics)
	{
		this.googleAnalytics = googleAnalytics;
		ClientID = EscapeString(anonymousClientID, forced: true);
		AppName = EscapeString(GoogleAnalyticsSettings.Instance.AppName, forced: true);
		AppVersion = EscapeString(BuildSettings.Version, forced: true);
		if (GoogleAnalyticsSettings.Instance.UseHTTPS)
		{
			DataSendUrl = "https://ssl.google-analytics.com/collect";
		}
		else
		{
			DataSendUrl = "http://www.google-analytics.com/collect";
		}
		GenerateHeaders(GoogleAnalyticsSettings.Instance.GetCurentProfile().TrackingID);
	}

	public void UpdateHeaders()
	{
		GenerateHeaders(GoogleAnalyticsSettings.Instance.GetCurentProfile().TrackingID);
	}

	public void GenerateHeaders(string trackingId)
	{
		TrackingID = EscapeString(trackingId);
		builder.Length = 0;
		builder.Append("v=1");
		builder.Append("&tid=");
		builder.Append(TrackingID);
		builder.Append("&cid=");
		builder.Append(ClientID);
		builder.Append("&an=");
		builder.Append(AppName);
		builder.Append("&av=");
		builder.Append(AppVersion);
		DefaultHitData = builder.ToString();
		builder.Length = 0;
	}

