	public void CreateHit(GoogleAnalyticsHitType hit)
	{
		currentHitType = hit;
		builder.Length = 0;
		builder.Append(DefaultHitData);
		SetHitType(hit);
	}

	public void Send()
	{
		if (!GoogleAnalyticsSettings.Instance.IsDisabled && !Profiles.LocalProfile.IsJunior())
		{
			if (googleAnalytics != null)
			{
				googleAnalytics.SessionKeepAlive();
			}
			builder.Append("&z=");
			builder.Append(UnityEngine.Random.Range(0, int.MaxValue) ^ 0xD60);
			string request = builder.ToString();
			builder.Length = 0;
			GoogleAnalytics.Send(request);
		}
	}

	public WWW GenerateWWW(byte[] data)
	{
		return new WWW(DataSendUrl, data);
	}

	public void AppendData(string protocolToken, string val)
	{
		AppendData(protocolToken, val, string.Empty, 0);
	}

	public void AppendData(string protocolToken, string val, string action, int maxSize, params GoogleAnalyticsHitType[] supportedHitTypes)
	{
		if (supportedHitTypes.Length > 0)
		{
			bool flag = false;
			foreach (GoogleAnalyticsHitType googleAnalyticsHitType in supportedHitTypes)
			{
				if (googleAnalyticsHitType == currentHitType)
				{
					flag = true;
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.LogWarning("Google Analytics: " + action + " not supported for hit type  " + currentHitType);
				return;
			}
		}
		string text = EscapeString(val);
		builder.Append("&");
		builder.Append(protocolToken);
		builder.Append("=");
		builder.Append(text);
		if (maxSize > 0)
		{
			CheckDataLength(action, text, maxSize);
		}
	}

	private string FloatToCurrency(float val)
	{
		return val.ToString("n2");
	}

	private void CheckDataLength(string action, string data, int maxLength)
	{
		if (string.IsNullOrEmpty(data))
		{
			UnityEngine.Debug.LogWarning("Google Analytics: " + action + " data is null");
		}
		else if (data.Length > maxLength)
		{
			UnityEngine.Debug.LogWarning("Google Analytics: " + action + " is too long, max size " + maxLength + " bytes (" + data + ")");
		}
	}

	private string EscapeString(string original)
	{
		return EscapeString(original, forced: false);
	}

	public string EscapeString(string original, bool forced)
	{
		if (forced)
		{
			return WWW.EscapeURL(original);
		}
		if (GoogleAnalyticsSettings.Instance.StringEscaping)
		{
			return WWW.EscapeURL(original);
		}
		return original;
	}
}
public class GoogleAnalyticsRequestCache
{
	private const string DATA_SPLITTER = "|";

	private const string RQUEST_DATA_SPLITTER = "%rps%";

	private const string GA_DATA_CACHE_KEY = "GoogleAnalyticsRequestCache";

	public static bool IsDisabled;

	public static string SavedData
	{
		get
		{
			if (PlayerPrefs.HasKey("GoogleAnalyticsRequestCache"))
			{
				return PlayerPrefs.GetString("GoogleAnalyticsRequestCache");
			}
			return string.Empty;
		}
		set
		{
			PlayerPrefs.SetString("GoogleAnalyticsRequestCache", value);
		}
	}

	public static List<GACachedRequest> CurrenCachedRequests
	{
		get
		{
			if (SavedData == string.Empty)
			{
				return new List<GACachedRequest>();
			}
			try
			{
				List<GACachedRequest> list = new List<GACachedRequest>();
				List<object> list2 = AmplitudeMiniJSON.Json.Deserialize(SavedData) as List<object>;
				foreach (object item in list2)
				{
					List<object> list3 = item as List<object>;
					GACachedRequest gACachedRequest = new GACachedRequest();
					int num = 1;
					foreach (object item2 in list3)
					{
						string text = item2 as string;
						switch (num)
						{
						case 1:
							gACachedRequest.RequestBody = text;
							break;
						case 2:
							gACachedRequest.TimeCreated = Convert.ToInt64(text);
							break;
						}
						num++;
					}
					list.Add(gACachedRequest);
				}
				return list;
			}
			catch (Exception ex)
			{
				Clear();
				UnityEngine.Debug.LogError(ex.Message);
				return new List<GACachedRequest>();
			}
		}
	}

	public static void SaveRequest(string cache)
	{
		if (!IsDisabled)
		{
			GACachedRequest item = new GACachedRequest(cache, DateTime.Now.Ticks);
			List<GACachedRequest> currenCachedRequests = CurrenCachedRequests;
			currenCachedRequests.Add(item);
			UnityEngine.Debug.Log(currenCachedRequests.Count);
			CacheRequests(currenCachedRequests);
		}
	}

	public static void SendCashedRequests()
	{
		List<GACachedRequest> currenCachedRequests = CurrenCachedRequests;
		foreach (GACachedRequest item in currenCachedRequests)
		{
			string requestBody = item.RequestBody;
			if (GoogleAnalyticsSettings.Instance.IsQueueTimeEnabled)
			{
				requestBody = requestBody + "&qt" + item.Delay;
				GoogleAnalytics.SendSkipCache(requestBody);
			}
		}
		Clear();
	}

	public static void Clear()
	{
		PlayerPrefs.DeleteKey("GoogleAnalyticsRequestCache");
	}

	public static void CacheRequests(List<GACachedRequest> requests)
	{
		List<List<string>> list = new List<List<string>>();
		foreach (GACachedRequest request in requests)
		{
			List<string> list2 = new List<string>();
			list2.Add(request.RequestBody);
			list2.Add(request.TimeCreated.ToString());
			list.Add(list2);
		}
		SavedData = AmplitudeMiniJSON.Json.Serialize(list);
	}
}
public enum GoogleAnalyticsHitType
{
	PAGEVIEW,
	APPVIEW,
	EVENT,
	TRANSACTION,
	ITEM,
	SOCIAL,
	EXCEPTION,
	TIMING,
	SCREENVIEW
}
public class GoogleAnalyticsUseExample : UnityEngine.MonoBehaviour
{
	private void Start()
	{
		GoogleAnalytics.StartTracking();
	}

	private void OnGUI()
	{
		if (GUI.Button(new Rect(10f, 10f, 150f, 50f), "Page Hit"))
		{
			GoogleAnalytics.Client.SendPageHit("mydemo.com ", "/home", "homepage", string.Empty, string.Empty);
		}
		if (GUI.Button(new Rect(10f, 70f, 150f, 50f), "Event Hit"))
		{
			GoogleAnalytics.Client.SendEventHit("video", "play", "holiday", 300);
		}
		if (GUI.Button(new Rect(10f, 130f, 150f, 50f), "Transaction Hit"))
		{
			GoogleAnalytics.Client.SendTransactionHit("12345", "westernWear", "EUR", 50f, 32f, 12f);
		}
		if (GUI.Button(new Rect(10f, 190f, 150f, 50f), "Item Hit"))
		{
			GoogleAnalytics.Client.SendItemHit("12345", "sofa", "u3eqds43", 300f, 2, "furniture", "EUR");
		}
		if (GUI.Button(new Rect(190f, 10f, 150f, 50f), "Social Hit"))
		{
			GoogleAnalytics.Client.SendSocialHit("like", "facebook", "/home ");
		}
		if (GUI.Button(new Rect(190f, 70f, 150f, 50f), "Exception Hit"))
		{
			GoogleAnalytics.Client.SendExceptionHit("IOException", IsFatal: true);
		}
		if (GUI.Button(new Rect(190f, 130f, 150f, 50f), "Timing Hit"))
		{
			GoogleAnalytics.Client.SendUserTimingHit("jsonLoader", "load", 5000, "jQuery");
		}
		if (GUI.Button(new Rect(190f, 190f, 150f, 50f), "Screen Hit"))
		{
			GoogleAnalytics.Client.SendScreenHit("MainMenu");
		}
	}

	public void CustomBuildersExamples()
	{
		GoogleAnalytics.Client.CreateHit(GoogleAnalyticsHitType.PAGEVIEW);
		GoogleAnalytics.Client.SetDocumentHostName("mydemo.com");
		GoogleAnalytics.Client.SetDocumentPath("/home");
		GoogleAnalytics.Client.SetDocumentTitle("homepage");
		GoogleAnalytics.Client.Send();
		GoogleAnalytics.Client.CreateHit(GoogleAnalyticsHitType.EVENT);
		GoogleAnalytics.Client.SetEventCategory("video");
		GoogleAnalytics.Client.SetEventAction("play");
		GoogleAnalytics.Client.SetEventLabel("holiday");
		GoogleAnalytics.Client.SetEventValue(300);
		GoogleAnalytics.Client.Send();
		GoogleAnalytics.Client.CreateHit(GoogleAnalyticsHitType.PAGEVIEW);
		GoogleAnalytics.Client.SetDocumentHostName("mydemo.com");
		GoogleAnalytics.Client.SetDocumentPath("/receipt");
		GoogleAnalytics.Client.SetDocumentTitle("Receipt Page");
		GoogleAnalytics.Client.SetTransactionID("T12345");
		GoogleAnalytics.Client.SetTransactionAffiliation("Google Store - Online");
		GoogleAnalytics.Client.SetTransactionRevenue(37.39f);
		GoogleAnalytics.Client.SetTransactionTax(2.85f);
