{
	public static Dictionary<string, Texture2D> LocalCache = new Dictionary<string, Texture2D>();

	private string _url;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<Texture2D> m_OnLoad;

	public event Action<Texture2D> OnLoad
	{
		add
		{
			Action<Texture2D> action = this.m_OnLoad;
			Action<Texture2D> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnLoad, (Action<Texture2D>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<Texture2D> action = this.m_OnLoad;
			Action<Texture2D> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnLoad, (Action<Texture2D>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public SA_WWWTextureLoader()
	{
		this.OnLoad = delegate
		{
		};
		base..ctor();
	}

	public static SA_WWWTextureLoader Create()
	{
		return new GameObject("WWWTextureLoader").AddComponent<SA_WWWTextureLoader>();
	}

	public void LoadTexture(string url)
	{
		_url = url;
		if (LocalCache.ContainsKey(_url))
		{
			this.OnLoad(LocalCache[_url]);
			UnityEngine.Object.Destroy(base.gameObject);
		}
		else
		{
			StartCoroutine(LoadCoroutin());
		}
	}

	private IEnumerator LoadCoroutin()
	{
		WWW www = new WWW(_url);
		yield return www;
		if (www.error == null)
		{
			UpdateLocalCache(_url, www.texture);
			this.OnLoad(www.texture);
		}
		else
		{
			this.OnLoad(null);
		}
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private static void UpdateLocalCache(string url, Texture2D image)
	{
	}
