public abstract class OVRCameraComposition : OVRComposition
{
	public class OVRCameraFrameCompositionManager : UnityEngine.MonoBehaviour
	{
		public GameObject cameraFrameGameObj;

		public OVRCameraComposition composition;

		public RenderTexture boundaryMeshMaskTexture;

		private Material cameraFrameMaterial;

		private Material whiteMaterial;

		private void Start()
		{
			Shader shader = Shader.Find("Oculus/Unlit");
			if (!shader)
			{
				UnityEngine.Debug.LogError("Oculus/Unlit shader does not exist");
				return;
			}
			whiteMaterial = new Material(shader);
			whiteMaterial.color = Color.white;
		}

		private void OnPreRender()
		{
			if (OVRManager.instance.virtualGreenScreenType != OVRManager.VirtualGreenScreenType.Off && boundaryMeshMaskTexture != null && composition.boundaryMesh != null)
			{
				RenderTexture active = RenderTexture.active;
				RenderTexture.active = boundaryMeshMaskTexture;
				GL.PushMatrix();
				GL.LoadProjectionMatrix(GetComponent<Camera>().projectionMatrix);
				GL.Clear(clearDepth: false, clearColor: true, Color.black);
				for (int i = 0; i < whiteMaterial.passCount; i++)
				{
					if (whiteMaterial.SetPass(i))
					{
						Graphics.DrawMeshNow(composition.boundaryMesh, composition.cameraRig.ComputeTrackReferenceMatrix());
					}
				}
				GL.PopMatrix();
				RenderTexture.active = active;
			}
			if ((bool)cameraFrameGameObj)
			{
				if (cameraFrameMaterial == null)
				{
					cameraFrameMaterial = cameraFrameGameObj.GetComponent<MeshRenderer>().material;
				}
				cameraFrameMaterial.SetFloat("_Visible", 1f);
			}
		}

		private void OnPostRender()
		{
			if ((bool)cameraFrameGameObj)
			{
				cameraFrameMaterial.SetFloat("_Visible", 0f);
			}
		}
	}

	protected GameObject cameraFramePlaneObject;

	protected float cameraFramePlaneDistance;

	protected readonly bool hasCameraDeviceOpened;

	protected readonly bool useDynamicLighting;

	internal readonly OVRPlugin.CameraDevice cameraDevice = OVRPlugin.CameraDevice.WebCamera0;

	private OVRCameraRig cameraRig;

	private Mesh boundaryMesh;

	private float boundaryMeshTopY;

	private float boundaryMeshBottomY;

	private OVRManager.VirtualGreenScreenType boundaryMeshType;

	private bool nullcameraRigWarningDisplayed;

	protected OVRCameraComposition(OVRManager.CameraDevice inCameraDevice, bool inUseDynamicLighting, OVRManager.DepthQuality depthQuality)
	{
		cameraDevice = OVRCompositionUtil.ConvertCameraDevice(inCameraDevice);
		hasCameraDeviceOpened = false;
		useDynamicLighting = inUseDynamicLighting;
		bool flag = OVRPlugin.DoesCameraDeviceSupportDepth(cameraDevice);
		if (useDynamicLighting && !flag)
		{
			UnityEngine.Debug.LogWarning("The camera device doesn't support depth. The result of dynamic lighting might not be correct");
		}
		if (!OVRPlugin.IsCameraDeviceAvailable(cameraDevice))
		{
			return;
		}
		if (OVRPlugin.GetExternalCameraCount() > 0 && OVRPlugin.GetMixedRealityCameraInfo(0, out var _, out var cameraIntrinsics))
		{
			OVRPlugin.SetCameraDevicePreferredColorFrameSize(cameraDevice, cameraIntrinsics.ImageSensorPixelResolution.w, cameraIntrinsics.ImageSensorPixelResolution.h);
		}
		if (useDynamicLighting)
		{
			OVRPlugin.SetCameraDeviceDepthSensingMode(cameraDevice, OVRPlugin.CameraDeviceDepthSensingMode.Fill);
			OVRPlugin.CameraDeviceDepthQuality depthQuality2 = OVRPlugin.CameraDeviceDepthQuality.Medium;
			switch (depthQuality)
			{
			case OVRManager.DepthQuality.Low:
				depthQuality2 = OVRPlugin.CameraDeviceDepthQuality.Low;
				break;
			case OVRManager.DepthQuality.Medium:
				depthQuality2 = OVRPlugin.CameraDeviceDepthQuality.Medium;
				break;
			case OVRManager.DepthQuality.High:
				depthQuality2 = OVRPlugin.CameraDeviceDepthQuality.High;
				break;
			default:
				UnityEngine.Debug.LogWarning("Unknown depth quality");
				break;
			}
			OVRPlugin.SetCameraDevicePreferredDepthQuality(cameraDevice, depthQuality2);
		}
		OVRPlugin.OpenCameraDevice(cameraDevice);
		if (OVRPlugin.HasCameraDeviceOpened(cameraDevice))
		{
			hasCameraDeviceOpened = true;
		}
	}

	public override void Cleanup()
	{
		OVRCompositionUtil.SafeDestroy(ref cameraFramePlaneObject);
		if (hasCameraDeviceOpened)
		{
			OVRPlugin.CloseCameraDevice(cameraDevice);
		}
	}

	public override void RecenterPose()
	{
		boundaryMesh = null;
	}

	protected void CreateCameraFramePlaneObject(GameObject parentObject, Camera mixedRealityCamera, bool useDynamicLighting)
	{
		cameraFramePlaneObject = GameObject.CreatePrimitive(PrimitiveType.Quad);
		cameraFramePlaneObject.name = "MRCameraFrame";
		cameraFramePlaneObject.transform.parent = parentObject.transform;
		cameraFramePlaneObject.GetComponent<Collider>().enabled = false;
		cameraFramePlaneObject.GetComponent<MeshRenderer>().shadowCastingMode = ShadowCastingMode.Off;
		Material material = new Material(Shader.Find((!useDynamicLighting) ? "Oculus/OVRMRCameraFrame" : "Oculus/OVRMRCameraFrameLit"));
		cameraFramePlaneObject.GetComponent<MeshRenderer>().material = material;
		material.SetColor("_Color", Color.white);
		material.SetFloat("_Visible", 0f);
		cameraFramePlaneObject.transform.localScale = new Vector3(4f, 4f, 4f);
		cameraFramePlaneObject.SetActive(value: true);
		OVRCameraFrameCompositionManager oVRCameraFrameCompositionManager = mixedRealityCamera.gameObject.AddComponent<OVRCameraFrameCompositionManager>();
		oVRCameraFrameCompositionManager.cameraFrameGameObj = cameraFramePlaneObject;
		oVRCameraFrameCompositionManager.composition = this;
	}

	protected void UpdateCameraFramePlaneObject(Camera mainCamera, Camera mixedRealityCamera, RenderTexture boundaryMeshMaskTexture)
	{
		bool flag = false;
		Material material = cameraFramePlaneObject.GetComponent<MeshRenderer>().material;
		Texture2D texture2D = Texture2D.blackTexture;
		Texture2D value = Texture2D.whiteTexture;
		if (OVRPlugin.IsCameraDeviceColorFrameAvailable(cameraDevice))
		{
			texture2D = OVRPlugin.GetCameraDeviceColorFrameTexture(cameraDevice);
		}
		else
		{
			UnityEngine.Debug.LogWarning("Camera: color frame not ready");
			flag = true;
		}
		bool flag2 = OVRPlugin.DoesCameraDeviceSupportDepth(cameraDevice);
		if (useDynamicLighting && flag2)
		{
			if (OVRPlugin.IsCameraDeviceDepthFrameAvailable(cameraDevice))
			{
				value = OVRPlugin.GetCameraDeviceDepthFrameTexture(cameraDevice);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Camera: depth frame not ready");
				flag = true;
			}
		}
		if (flag)
		{
			return;
		}
		Vector3 rhs = mainCamera.transform.position - mixedRealityCamera.transform.position;
		float num = (cameraFramePlaneDistance = Vector3.Dot(mixedRealityCamera.transform.forward, rhs));
		cameraFramePlaneObject.transform.position = mixedRealityCamera.transform.position + mixedRealityCamera.transform.forward * num;
		cameraFramePlaneObject.transform.rotation = mixedRealityCamera.transform.rotation;
		float num2 = Mathf.Tan(mixedRealityCamera.fieldOfView * ((float)Math.PI / 180f) * 0.5f);
		cameraFramePlaneObject.transform.localScale = new Vector3(num * mixedRealityCamera.aspect * num2 * 2f, num * num2 * 2f, 1f);
		float num3 = num * num2 * 2f;
		float x = num3 * mixedRealityCamera.aspect;
		float cullingDistance = float.MaxValue;
		cameraRig = null;
		if (OVRManager.instance.virtualGreenScreenType != OVRManager.VirtualGreenScreenType.Off)
		{
			cameraRig = mainCamera.GetComponentInParent<OVRCameraRig>();
			if (cameraRig != null && cameraRig.centerEyeAnchor == null)
			{
				cameraRig = null;
			}
			RefreshBoundaryMesh(mixedRealityCamera, out cullingDistance);
		}
		material.mainTexture = texture2D;
		material.SetTexture("_DepthTex", value);
		material.SetVector("_FlipParams", new Vector4((!OVRManager.instance.flipCameraFrameHorizontally) ? 0f : 1f, (!OVRManager.instance.flipCameraFrameVertically) ? 0f : 1f, 0f, 0f));
		material.SetColor("_ChromaKeyColor", OVRManager.instance.chromaKeyColor);
		material.SetFloat("_ChromaKeySimilarity", OVRManager.instance.chromaKeySimilarity);
		material.SetFloat("_ChromaKeySmoothRange", OVRManager.instance.chromaKeySmoothRange);
		material.SetFloat("_ChromaKeySpillRange", OVRManager.instance.chromaKeySpillRange);
		material.SetVector("_TextureDimension", new Vector4(texture2D.width, texture2D.height, 1f / (float)texture2D.width, 1f / (float)texture2D.height));
		material.SetVector("_TextureWorldSize", new Vector4(x, num3, 0f, 0f));
		material.SetFloat("_SmoothFactor", OVRManager.instance.dynamicLightingSmoothFactor);
		material.SetFloat("_DepthVariationClamp", OVRManager.instance.dynamicLightingDepthVariationClampingValue);
		material.SetFloat("_CullingDistance", cullingDistance);
		if (OVRManager.instance.virtualGreenScreenType == OVRManager.VirtualGreenScreenType.Off || boundaryMesh == null || boundaryMeshMaskTexture == null)
		{
			material.SetTexture("_MaskTex", Texture2D.whiteTexture);
		}
		else if (cameraRig == null)
		{
			if (!nullcameraRigWarningDisplayed)
			{
				UnityEngine.Debug.LogWarning("Could not find the OVRCameraRig/CenterEyeAnchor object. Please check if the OVRCameraRig has been setup properly. The virtual green screen has been temporarily disabled");
				nullcameraRigWarningDisplayed = true;
			}
			material.SetTexture("_MaskTex", Texture2D.whiteTexture);
		}
		else
		{
			if (nullcameraRigWarningDisplayed)
			{
				UnityEngine.Debug.Log("OVRCameraRig/CenterEyeAnchor object found. Virtual green screen is activated");
				nullcameraRigWarningDisplayed = false;
			}
			material.SetTexture("_MaskTex", boundaryMeshMaskTexture);
		}
	}

	protected void RefreshBoundaryMesh(Camera camera, out float cullingDistance)
	{
		float num = ((!OVRManager.instance.virtualGreenScreenApplyDepthCulling) ? float.PositiveInfinity : OVRManager.instance.virtualGreenScreenDepthTolerance);
		cullingDistance = OVRCompositionUtil.GetMaximumBoundaryDistance(camera, OVRCompositionUtil.ToBoundaryType(OVRManager.instance.virtualGreenScreenType)) + num;
		if (boundaryMesh == null || boundaryMeshType != OVRManager.instance.virtualGreenScreenType || boundaryMeshTopY != OVRManager.instance.virtualGreenScreenTopY || boundaryMeshBottomY != OVRManager.instance.virtualGreenScreenBottomY)
		{
			boundaryMeshTopY = OVRManager.instance.virtualGreenScreenTopY;
			boundaryMeshBottomY = OVRManager.instance.virtualGreenScreenBottomY;
			boundaryMesh = OVRCompositionUtil.BuildBoundaryMesh(OVRCompositionUtil.ToBoundaryType(OVRManager.instance.virtualGreenScreenType), boundaryMeshTopY, boundaryMeshBottomY);
			boundaryMeshType = OVRManager.instance.virtualGreenScreenType;
		}
	}
}
public abstract class OVRComposition
{
	protected bool usingLastAttachedNodePose;

	protected OVRPose lastAttachedNodePose = default(OVRPose);

	public abstract OVRManager.CompositionMethod CompositionMethod();

	public abstract void Update(Camera mainCamera);

	public abstract void Cleanup();

	public virtual void RecenterPose()
	{
	}

	internal OVRPose ComputeCameraWorldSpacePose(OVRPlugin.CameraExtrinsics extrinsics)
	{
		OVRPose oVRPose = default(OVRPose);
		OVRPose oVRPose2 = default(OVRPose);
		OVRPose oVRPose3 = extrinsics.RelativePose.ToOVRPose();
		oVRPose2 = oVRPose3;
		if (extrinsics.AttachedToNode != OVRPlugin.Node.None && OVRPlugin.GetNodePresent(extrinsics.AttachedToNode))
		{
			if (usingLastAttachedNodePose)
			{
				UnityEngine.Debug.Log("The camera attached node get tracked");
				usingLastAttachedNodePose = false;
			}
			oVRPose2 = (lastAttachedNodePose = OVRPlugin.GetNodePose(extrinsics.AttachedToNode, OVRPlugin.Step.Render).ToOVRPose()) * oVRPose2;
		}
		else if (extrinsics.AttachedToNode != OVRPlugin.Node.None)
		{
			if (!usingLastAttachedNodePose)
			{
				UnityEngine.Debug.LogWarning("The camera attached node could not be tracked, using the last pose");
				usingLastAttachedNodePose = true;
			}
			oVRPose2 = lastAttachedNodePose * oVRPose2;
		}
		return OVRExtensions.ToWorldSpacePose(oVRPose2);
	}
}
internal class OVRCompositionUtil
{
	public static void SafeDestroy(GameObject obj)
	{
		if (UnityEngine.Application.isPlaying)
		{
			UnityEngine.Object.Destroy(obj);
		}
		else
		{
			UnityEngine.Object.DestroyImmediate(obj);
		}
	}

	public static void SafeDestroy(ref GameObject obj)
	{
		SafeDestroy(obj);
		obj = null;
	}

	public static OVRPlugin.CameraDevice ConvertCameraDevice(OVRManager.CameraDevice cameraDevice)
	{
		return cameraDevice switch
		{
			OVRManager.CameraDevice.WebCamera0 => OVRPlugin.CameraDevice.WebCamera0, 
			OVRManager.CameraDevice.WebCamera1 => OVRPlugin.CameraDevice.WebCamera1, 
			OVRManager.CameraDevice.ZEDCamera => OVRPlugin.CameraDevice.ZEDCamera, 
			_ => OVRPlugin.CameraDevice.None, 
		};
	}

	public static OVRBoundary.BoundaryType ToBoundaryType(OVRManager.VirtualGreenScreenType type)
	{
		switch (type)
		{
		case OVRManager.VirtualGreenScreenType.OuterBoundary:
			return OVRBoundary.BoundaryType.OuterBoundary;
		case OVRManager.VirtualGreenScreenType.PlayArea:
			return OVRBoundary.BoundaryType.PlayArea;
		default:
			UnityEngine.Debug.LogWarning("Unmatched VirtualGreenScreenType");
			return OVRBoundary.BoundaryType.OuterBoundary;
		}
	}

	public static Vector3 GetWorldPosition(Vector3 trackingSpacePosition)
	{
		OVRPose trackingSpacePose = default(OVRPose);
		trackingSpacePose.position = trackingSpacePosition;
		trackingSpacePose.orientation = Quaternion.identity;
		return OVRExtensions.ToWorldSpacePose(trackingSpacePose).position;
	}

	public static float GetMaximumBoundaryDistance(Camera camera, OVRBoundary.BoundaryType boundaryType)
	{
		if (!OVRManager.boundary.GetConfigured())
		{
			return float.MaxValue;
		}
		Vector3[] geometry = OVRManager.boundary.GetGeometry(boundaryType);
		if (geometry.Length == 0)
		{
			return float.MaxValue;
		}
		float num = float.MinValue;
		Vector3[] array = geometry;
		foreach (Vector3 trackingSpacePosition in array)
		{
			Vector3 worldPosition = GetWorldPosition(trackingSpacePosition);
			float num2 = Vector3.Dot(camera.transform.forward, worldPosition);
			if (num < num2)
			{
				num = num2;
			}
		}
		return num;
	}

	public static Mesh BuildBoundaryMesh(OVRBoundary.BoundaryType boundaryType, float topY, float bottomY)
	{
		if (!OVRManager.boundary.GetConfigured())
		{
			return null;
		}
		List<Vector3> list = new List<Vector3>(OVRManager.boundary.GetGeometry(boundaryType));
		if (list.Count == 0)
		{
			return null;
		}
		list.Add(list[0]);
		int count = list.Count;
		Vector3[] array = new Vector3[count * 2];
		Vector2[] array2 = new Vector2[count * 2];
		for (int i = 0; i < count; i++)
		{
			Vector3 vector = list[i];
			ref Vector3 reference = ref array[i];
			reference = new Vector3(vector.x, bottomY, vector.z);
			ref Vector3 reference2 = ref array[i + count];
			reference2 = new Vector3(vector.x, topY, vector.z);
			ref Vector2 reference3 = ref array2[i];
			reference3 = new Vector2((float)i / (float)(count - 1), 0f);
			ref Vector2 reference4 = ref array2[i + count];
			reference4 = new Vector2(array2[i].x, 1f);
		}
		int[] array3 = new int[(count - 1) * 2 * 3];
		for (int j = 0; j < count - 1; j++)
		{
			array3[j * 6] = j;
			array3[j * 6 + 1] = j + count;
			array3[j * 6 + 2] = j + 1 + count;
			array3[j * 6 + 3] = j;
			array3[j * 6 + 4] = j + 1 + count;
			array3[j * 6 + 5] = j + 1;
		}
		Mesh mesh = new Mesh();
		mesh.vertices = array;
		mesh.uv = array2;
		mesh.triangles = array3;
		return mesh;
	}
}
public class OVRDirectComposition : OVRCameraComposition
{
	public GameObject directCompositionCameraGameObject;

	public Camera directCompositionCamera;

	public RenderTexture boundaryMeshMaskTexture;

	public OVRDirectComposition(GameObject parentObject, Camera mainCamera, OVRManager.CameraDevice cameraDevice, bool useDynamicLighting, OVRManager.DepthQuality depthQuality)
		: base(cameraDevice, useDynamicLighting, depthQuality)
	{
		directCompositionCameraGameObject = new GameObject();
		directCompositionCameraGameObject.name = "MRDirectCompositionCamera";
		directCompositionCameraGameObject.transform.parent = parentObject.transform;
		directCompositionCamera = directCompositionCameraGameObject.AddComponent<Camera>();
		directCompositionCamera.stereoTargetEye = StereoTargetEyeMask.None;
		directCompositionCamera.depth = float.MaxValue;
		directCompositionCamera.rect = new Rect(0f, 0f, 1f, 1f);
		directCompositionCamera.clearFlags = mainCamera.clearFlags;
		directCompositionCamera.backgroundColor = mainCamera.backgroundColor;
		directCompositionCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		directCompositionCamera.nearClipPlane = mainCamera.nearClipPlane;
		directCompositionCamera.farClipPlane = mainCamera.farClipPlane;
		if (!hasCameraDeviceOpened)
		{
			UnityEngine.Debug.LogError("Unable to open camera device " + cameraDevice);
			return;
		}
		UnityEngine.Debug.Log("DirectComposition activated : useDynamicLighting " + ((!useDynamicLighting) ? "OFF" : "ON"));
		CreateCameraFramePlaneObject(parentObject, directCompositionCamera, useDynamicLighting);
	}

	public override OVRManager.CompositionMethod CompositionMethod()
	{
		return OVRManager.CompositionMethod.Direct;
	}

	public override void Update(Camera mainCamera)
	{
		if (!hasCameraDeviceOpened)
		{
			return;
		}
		if (!OVRPlugin.SetHandNodePoseStateLatency(OVRManager.instance.handPoseStateLatency))
		{
			UnityEngine.Debug.LogWarning("HandPoseStateLatency is invalid. Expect a value between 0.0 to 0.5, get " + OVRManager.instance.handPoseStateLatency);
		}
		directCompositionCamera.clearFlags = mainCamera.clearFlags;
		directCompositionCamera.backgroundColor = mainCamera.backgroundColor;
		directCompositionCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		directCompositionCamera.nearClipPlane = mainCamera.nearClipPlane;
		directCompositionCamera.farClipPlane = mainCamera.farClipPlane;
		OVRPlugin.CameraExtrinsics cameraExtrinsics;
		OVRPlugin.CameraIntrinsics cameraIntrinsics;
		if (OVRMixedReality.useFakeExternalCamera || OVRPlugin.GetExternalCameraCount() == 0)
		{
			OVRPose oVRPose = default(OVRPose);
			oVRPose = OVRExtensions.ToWorldSpacePose(new OVRPose
			{
				position = OVRMixedReality.fakeCameraPositon,
				orientation = OVRMixedReality.fakeCameraRotation
			});
			directCompositionCamera.fieldOfView = OVRMixedReality.fakeCameraFov;
			directCompositionCamera.aspect = OVRMixedReality.fakeCameraAspect;
			directCompositionCamera.transform.FromOVRPose(oVRPose);
		}
		else if (OVRPlugin.GetMixedRealityCameraInfo(0, out cameraExtrinsics, out cameraIntrinsics))
		{
			OVRPose pose = ComputeCameraWorldSpacePose(cameraExtrinsics);
			float fieldOfView = Mathf.Atan(cameraIntrinsics.FOVPort.UpTan) * 57.29578f * 2f;
			float aspect = cameraIntrinsics.FOVPort.LeftTan / cameraIntrinsics.FOVPort.UpTan;
			directCompositionCamera.fieldOfView = fieldOfView;
			directCompositionCamera.aspect = aspect;
			directCompositionCamera.transform.FromOVRPose(pose);
		}
		else
		{
			UnityEngine.Debug.LogWarning("Failed to get external camera information");
		}
		if (hasCameraDeviceOpened)
		{
			if (boundaryMeshMaskTexture == null || boundaryMeshMaskTexture.width != Screen.width || boundaryMeshMaskTexture.height != Screen.height)
			{
				boundaryMeshMaskTexture = new RenderTexture(Screen.width, Screen.height, 0, RenderTextureFormat.R8);
				boundaryMeshMaskTexture.Create();
			}
			UpdateCameraFramePlaneObject(mainCamera, directCompositionCamera, boundaryMeshMaskTexture);
			directCompositionCamera.GetComponent<OVRCameraFrameCompositionManager>().boundaryMeshMaskTexture = boundaryMeshMaskTexture;
		}
	}

	public override void Cleanup()
	{
		base.Cleanup();
		OVRCompositionUtil.SafeDestroy(ref directCompositionCameraGameObject);
		directCompositionCamera = null;
		UnityEngine.Debug.Log("DirectComposition deactivated");
	}
}
public class OVRExternalComposition : OVRComposition
{
	private GameObject foregroundCameraGameObject;

	private Camera foregroundCamera;

	private GameObject backgroundCameraGameObject;

	private Camera backgroundCamera;

	private GameObject cameraProxyPlane;

	public OVRExternalComposition(GameObject parentObject, Camera mainCamera)
	{
		backgroundCameraGameObject = new GameObject();
		backgroundCameraGameObject.name = "MRBackgroundCamera";
		backgroundCameraGameObject.transform.parent = parentObject.transform;
		backgroundCamera = backgroundCameraGameObject.AddComponent<Camera>();
		backgroundCamera.stereoTargetEye = StereoTargetEyeMask.None;
		backgroundCamera.depth = float.MaxValue;
		backgroundCamera.rect = new Rect(0f, 0f, 0.5f, 1f);
		backgroundCamera.clearFlags = mainCamera.clearFlags;
		backgroundCamera.backgroundColor = mainCamera.backgroundColor;
		backgroundCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		backgroundCamera.nearClipPlane = mainCamera.nearClipPlane;
		backgroundCamera.farClipPlane = mainCamera.farClipPlane;
		foregroundCameraGameObject = new GameObject();
		foregroundCameraGameObject.name = "MRForgroundCamera";
		foregroundCameraGameObject.transform.parent = parentObject.transform;
		foregroundCamera = foregroundCameraGameObject.AddComponent<Camera>();
		foregroundCamera.stereoTargetEye = StereoTargetEyeMask.None;
		foregroundCamera.depth = float.MaxValue;
		foregroundCamera.rect = new Rect(0.5f, 0f, 0.5f, 1f);
		foregroundCamera.clearFlags = CameraClearFlags.Color;
		foregroundCamera.backgroundColor = OVRMixedReality.chromaKeyColor;
		foregroundCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		foregroundCamera.nearClipPlane = mainCamera.nearClipPlane;
		foregroundCamera.farClipPlane = mainCamera.farClipPlane;
		cameraProxyPlane = GameObject.CreatePrimitive(PrimitiveType.Quad);
		cameraProxyPlane.name = "MRProxyClipPlane";
		cameraProxyPlane.transform.parent = parentObject.transform;
		cameraProxyPlane.GetComponent<Collider>().enabled = false;
		cameraProxyPlane.GetComponent<MeshRenderer>().shadowCastingMode = ShadowCastingMode.Off;
		Material material = new Material(Shader.Find("Oculus/OVRMRClipPlane"));
		cameraProxyPlane.GetComponent<MeshRenderer>().material = material;
		material.SetColor("_Color", OVRMixedReality.chromaKeyColor);
		material.SetFloat("_Visible", 0f);
		cameraProxyPlane.transform.localScale = new Vector3(1000f, 1000f, 1000f);
		cameraProxyPlane.SetActive(value: true);
		OVRMRForegroundCameraManager oVRMRForegroundCameraManager = foregroundCameraGameObject.AddComponent<OVRMRForegroundCameraManager>();
		oVRMRForegroundCameraManager.clipPlaneGameObj = cameraProxyPlane;
	}

	public override OVRManager.CompositionMethod CompositionMethod()
	{
		return OVRManager.CompositionMethod.External;
	}

	public override void Update(Camera mainCamera)
	{
		OVRPlugin.SetHandNodePoseStateLatency(0.0);
		backgroundCamera.clearFlags = mainCamera.clearFlags;
		backgroundCamera.backgroundColor = mainCamera.backgroundColor;
		backgroundCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		backgroundCamera.nearClipPlane = mainCamera.nearClipPlane;
		backgroundCamera.farClipPlane = mainCamera.farClipPlane;
		foregroundCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		foregroundCamera.nearClipPlane = mainCamera.nearClipPlane;
		foregroundCamera.farClipPlane = mainCamera.farClipPlane;
		if (OVRMixedReality.useFakeExternalCamera || OVRPlugin.GetExternalCameraCount() == 0)
		{
			OVRPose oVRPose = default(OVRPose);
			oVRPose = OVRExtensions.ToWorldSpacePose(new OVRPose
			{
				position = OVRMixedReality.fakeCameraPositon,
				orientation = OVRMixedReality.fakeCameraRotation
			});
			backgroundCamera.fieldOfView = OVRMixedReality.fakeCameraFov;
			backgroundCamera.aspect = OVRMixedReality.fakeCameraAspect;
			backgroundCamera.transform.FromOVRPose(oVRPose);
			foregroundCamera.fieldOfView = OVRMixedReality.fakeCameraFov;
			foregroundCamera.aspect = OVRMixedReality.fakeCameraAspect;
			foregroundCamera.transform.FromOVRPose(oVRPose);
		}
		else
		{
			if (!OVRPlugin.GetMixedRealityCameraInfo(0, out var cameraExtrinsics, out var cameraIntrinsics))
			{
				UnityEngine.Debug.LogError("Failed to get external camera information");
				return;
			}
			OVRPose pose = ComputeCameraWorldSpacePose(cameraExtrinsics);
			float fieldOfView = Mathf.Atan(cameraIntrinsics.FOVPort.UpTan) * 57.29578f * 2f;
			float aspect = cameraIntrinsics.FOVPort.LeftTan / cameraIntrinsics.FOVPort.UpTan;
			backgroundCamera.fieldOfView = fieldOfView;
			backgroundCamera.aspect = aspect;
			backgroundCamera.transform.FromOVRPose(pose);
			foregroundCamera.fieldOfView = fieldOfView;
			foregroundCamera.aspect = cameraIntrinsics.FOVPort.LeftTan / cameraIntrinsics.FOVPort.UpTan;
			foregroundCamera.transform.FromOVRPose(pose);
		}
		Vector3 vector = mainCamera.transform.position - foregroundCamera.transform.position;
		vector.y = 0f;
		cameraProxyPlane.transform.position = mainCamera.transform.position;
		cameraProxyPlane.transform.LookAt(cameraProxyPlane.transform.position + vector);
	}

	public override void Cleanup()
	{
		OVRCompositionUtil.SafeDestroy(ref backgroundCameraGameObject);
		backgroundCamera = null;
		OVRCompositionUtil.SafeDestroy(ref foregroundCameraGameObject);
		foregroundCamera = null;
		OVRCompositionUtil.SafeDestroy(ref cameraProxyPlane);
		UnityEngine.Debug.Log("ExternalComposition deactivated");
	}
}
internal class OVRMRForegroundCameraManager : UnityEngine.MonoBehaviour
{
	public GameObject clipPlaneGameObj;

	private Material clipPlaneMaterial;

	private void OnPreRender()
	{
		if ((bool)clipPlaneGameObj)
		{
			if (clipPlaneMaterial == null)
			{
				clipPlaneMaterial = clipPlaneGameObj.GetComponent<MeshRenderer>().material;
			}
			clipPlaneGameObj.GetComponent<MeshRenderer>().material.SetFloat("_Visible", 1f);
		}
	}

	private void OnPostRender()
	{
		if ((bool)clipPlaneGameObj)
		{
			clipPlaneGameObj.GetComponent<MeshRenderer>().material.SetFloat("_Visible", 0f);
		}
	}
}
public class OVRSandwichComposition : OVRCameraComposition
{
	public class HistoryRecord
	{
		public float timestamp = float.MinValue;

		public RenderTexture fgRenderTexture;

		public RenderTexture bgRenderTexture;

		public RenderTexture boundaryMeshMaskTexture;
	}

	public class OVRSandwichCompositionManager : UnityEngine.MonoBehaviour
	{
		public RenderTexture fgTexture;

		public RenderTexture bgTexture;

		public Material alphaBlendMaterial;

		private void Start()
		{
			Shader shader = Shader.Find("Oculus/UnlitTransparent");
			if (shader == null)
			{
				UnityEngine.Debug.LogError("Unable to create transparent shader");
			}
			else
			{
				alphaBlendMaterial = new Material(shader);
			}
		}

		private void OnPreRender()
		{
			if (fgTexture == null || bgTexture == null || alphaBlendMaterial == null)
			{
				UnityEngine.Debug.LogError("OVRSandwichCompositionManager has not setup properly");
			}
			else
			{
				Graphics.Blit(bgTexture, RenderTexture.active);
			}
		}

		private void OnPostRender()
		{
			if (fgTexture == null || bgTexture == null || alphaBlendMaterial == null)
			{
				UnityEngine.Debug.LogError("OVRSandwichCompositionManager has not setup properly");
			}
			else
			{
				Graphics.Blit(fgTexture, RenderTexture.active, alphaBlendMaterial);
			}
		}
	}

	public float frameRealtime;

	public Camera fgCamera;

	public Camera bgCamera;

	public readonly int historyRecordCount = 8;

	public readonly HistoryRecord[] historyRecordArray;

	public int historyRecordCursorIndex;

	public GameObject cameraProxyPlane;

	public Camera compositionCamera;

	public OVRSandwichCompositionManager compositionManager;

	private int _cameraFramePlaneLayer = -1;

	public int cameraFramePlaneLayer
	{
		get
		{
			if (_cameraFramePlaneLayer < 0)
			{
				for (int i = 24; i <= 29; i++)
				{
					string text = LayerMask.LayerToName(i);
					if (text == null || text.Length == 0)
					{
						_cameraFramePlaneLayer = i;
						break;
					}
				}
				if (_cameraFramePlaneLayer == -1)
				{
					UnityEngine.Debug.LogWarning("Unable to find an unnamed layer between 24 and 29.");
					_cameraFramePlaneLayer = 25;
				}
				UnityEngine.Debug.LogFormat("Set the CameraFramePlaneLayer in SandwichComposition to {0}. Please do NOT put any other gameobject in this layer.", _cameraFramePlaneLayer);
			}
			return _cameraFramePlaneLayer;
		}
	}

	public OVRSandwichComposition(GameObject parentObject, Camera mainCamera, OVRManager.CameraDevice cameraDevice, bool useDynamicLighting, OVRManager.DepthQuality depthQuality)
		: base(cameraDevice, useDynamicLighting, depthQuality)
	{
		frameRealtime = UnityEngine.Time.realtimeSinceStartup;
		historyRecordCount = OVRManager.instance.sandwichCompositionBufferedFrames;
		if (historyRecordCount < 1)
		{
			UnityEngine.Debug.LogWarning("Invalid sandwichCompositionBufferedFrames in OVRManager. It should be at least 1");
			historyRecordCount = 1;
		}
		if (historyRecordCount > 16)
		{
			UnityEngine.Debug.LogWarning("The value of sandwichCompositionBufferedFrames in OVRManager is too big. It would consume a lot of memory. It has been override to 16");
			historyRecordCount = 16;
		}
		historyRecordArray = new HistoryRecord[historyRecordCount];
		for (int i = 0; i < historyRecordCount; i++)
		{
			historyRecordArray[i] = new HistoryRecord();
		}
		historyRecordCursorIndex = 0;
		GameObject gameObject = new GameObject("MRSandwichForegroundCamera");
		gameObject.transform.parent = parentObject.transform;
		fgCamera = gameObject.AddComponent<Camera>();
		fgCamera.depth = 200f;
		fgCamera.clearFlags = CameraClearFlags.Color;
		fgCamera.backgroundColor = Color.clear;
		fgCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		fgCamera.nearClipPlane = mainCamera.nearClipPlane;
		fgCamera.farClipPlane = mainCamera.farClipPlane;
		GameObject gameObject2 = new GameObject("MRSandwichBackgroundCamera");
		gameObject2.transform.parent = parentObject.transform;
		bgCamera = gameObject2.AddComponent<Camera>();
		bgCamera.depth = 100f;
		bgCamera.clearFlags = mainCamera.clearFlags;
		bgCamera.backgroundColor = mainCamera.backgroundColor;
		bgCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
		bgCamera.nearClipPlane = mainCamera.nearClipPlane;
		bgCamera.farClipPlane = mainCamera.farClipPlane;
		cameraProxyPlane = GameObject.CreatePrimitive(PrimitiveType.Quad);
		cameraProxyPlane.name = "MRProxyClipPlane";
		cameraProxyPlane.transform.parent = parentObject.transform;
		cameraProxyPlane.GetComponent<Collider>().enabled = false;
		cameraProxyPlane.GetComponent<MeshRenderer>().shadowCastingMode = ShadowCastingMode.Off;
		Material material = new Material(Shader.Find("Oculus/OVRMRClipPlane"));
		cameraProxyPlane.GetComponent<MeshRenderer>().material = material;
		material.SetColor("_Color", Color.clear);
		material.SetFloat("_Visible", 0f);
		cameraProxyPlane.transform.localScale = new Vector3(1000f, 1000f, 1000f);
		cameraProxyPlane.SetActive(value: true);
		OVRMRForegroundCameraManager oVRMRForegroundCameraManager = fgCamera.gameObject.AddComponent<OVRMRForegroundCameraManager>();
		oVRMRForegroundCameraManager.clipPlaneGameObj = cameraProxyPlane;
		GameObject gameObject3 = new GameObject("MRSandwichCaptureCamera");
		gameObject3.transform.parent = parentObject.transform;
		compositionCamera = gameObject3.AddComponent<Camera>();
		compositionCamera.stereoTargetEye = StereoTargetEyeMask.None;
		compositionCamera.depth = float.MaxValue;
		compositionCamera.rect = new Rect(0f, 0f, 1f, 1f);
		compositionCamera.clearFlags = CameraClearFlags.Depth;
		compositionCamera.backgroundColor = mainCamera.backgroundColor;
		compositionCamera.cullingMask = 1 << cameraFramePlaneLayer;
		compositionCamera.nearClipPlane = mainCamera.nearClipPlane;
		compositionCamera.farClipPlane = mainCamera.farClipPlane;
		if (!hasCameraDeviceOpened)
		{
			UnityEngine.Debug.LogError("Unable to open camera device " + cameraDevice);
			return;
		}
		UnityEngine.Debug.Log("SandwichComposition activated : useDynamicLighting " + ((!useDynamicLighting) ? "OFF" : "ON"));
		CreateCameraFramePlaneObject(parentObject, compositionCamera, useDynamicLighting);
		cameraFramePlaneObject.layer = cameraFramePlaneLayer;
		RefreshRenderTextures(mainCamera);
		compositionManager = compositionCamera.gameObject.AddComponent<OVRSandwichCompositionManager>();
		compositionManager.fgTexture = historyRecordArray[historyRecordCursorIndex].fgRenderTexture;
		compositionManager.bgTexture = historyRecordArray[historyRecordCursorIndex].bgRenderTexture;
	}

	public override OVRManager.CompositionMethod CompositionMethod()
	{
		return OVRManager.CompositionMethod.Sandwich;
	}

	public override void Update(Camera mainCamera)
	{
		if (hasCameraDeviceOpened)
		{
			frameRealtime = UnityEngine.Time.realtimeSinceStartup;
			historyRecordCursorIndex++;
			if (historyRecordCursorIndex >= historyRecordCount)
			{
				historyRecordCursorIndex = 0;
			}
			if (!OVRPlugin.SetHandNodePoseStateLatency(OVRManager.instance.handPoseStateLatency))
			{
				UnityEngine.Debug.LogWarning("HandPoseStateLatency is invalid. Expect a value between 0.0 to 0.5, get " + OVRManager.instance.handPoseStateLatency);
			}
			RefreshRenderTextures(mainCamera);
			bgCamera.clearFlags = mainCamera.clearFlags;
			bgCamera.backgroundColor = mainCamera.backgroundColor;
			bgCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
			fgCamera.cullingMask = mainCamera.cullingMask & ~(int)OVRManager.instance.extraHiddenLayers;
			OVRPlugin.CameraExtrinsics cameraExtrinsics;
			OVRPlugin.CameraIntrinsics cameraIntrinsics;
			if (OVRMixedReality.useFakeExternalCamera || OVRPlugin.GetExternalCameraCount() == 0)
			{
				OVRPose oVRPose = default(OVRPose);
				oVRPose = OVRExtensions.ToWorldSpacePose(new OVRPose
				{
					position = OVRMixedReality.fakeCameraPositon,
					orientation = OVRMixedReality.fakeCameraRotation
				});
				RefreshCameraPoses(OVRMixedReality.fakeCameraFov, OVRMixedReality.fakeCameraAspect, oVRPose);
			}
			else if (OVRPlugin.GetMixedRealityCameraInfo(0, out cameraExtrinsics, out cameraIntrinsics))
			{
				OVRPose pose = ComputeCameraWorldSpacePose(cameraExtrinsics);
				float fovY = Mathf.Atan(cameraIntrinsics.FOVPort.UpTan) * 57.29578f * 2f;
				float aspect = cameraIntrinsics.FOVPort.LeftTan / cameraIntrinsics.FOVPort.UpTan;
				RefreshCameraPoses(fovY, aspect, pose);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Failed to get external camera information");
			}
			compositionCamera.GetComponent<OVRCameraFrameCompositionManager>().boundaryMeshMaskTexture = historyRecordArray[historyRecordCursorIndex].boundaryMeshMaskTexture;
			HistoryRecord historyRecordForComposition = GetHistoryRecordForComposition();
			UpdateCameraFramePlaneObject(mainCamera, compositionCamera, historyRecordForComposition.boundaryMeshMaskTexture);
			OVRSandwichCompositionManager component = compositionCamera.gameObject.GetComponent<OVRSandwichCompositionManager>();
			component.fgTexture = historyRecordForComposition.fgRenderTexture;
			component.bgTexture = historyRecordForComposition.bgRenderTexture;
			cameraProxyPlane.transform.position = fgCamera.transform.position + fgCamera.transform.forward * cameraFramePlaneDistance;
			cameraProxyPlane.transform.LookAt(cameraProxyPlane.transform.position + fgCamera.transform.forward);
		}
	}

	public override void Cleanup()
	{
		base.Cleanup();
		Camera[] array = new Camera[3] { fgCamera, bgCamera, compositionCamera };
		Camera[] array2 = array;
		foreach (Camera camera in array2)
		{
			OVRCompositionUtil.SafeDestroy(camera.gameObject);
		}
		fgCamera = null;
		bgCamera = null;
		compositionCamera = null;
		UnityEngine.Debug.Log("SandwichComposition deactivated");
	}

	private RenderTextureFormat DesiredRenderTextureFormat(RenderTextureFormat originalFormat)
	{
		return originalFormat switch
		{
			RenderTextureFormat.RGB565 => RenderTextureFormat.ARGB1555, 
			RenderTextureFormat.RGB111110Float => RenderTextureFormat.ARGBHalf, 
			_ => originalFormat, 
		};
	}

	protected void RefreshRenderTextures(Camera mainCamera)
	{
		int width = Screen.width;
		int height = Screen.height;
		RenderTextureFormat renderTextureFormat = (mainCamera.targetTexture ? DesiredRenderTextureFormat(mainCamera.targetTexture.format) : RenderTextureFormat.ARGB32);
		int num = ((!mainCamera.targetTexture) ? 24 : mainCamera.targetTexture.depth);
		HistoryRecord historyRecord = historyRecordArray[historyRecordCursorIndex];
		historyRecord.timestamp = frameRealtime;
		if (historyRecord.fgRenderTexture == null || historyRecord.fgRenderTexture.width != width || historyRecord.fgRenderTexture.height != height || historyRecord.fgRenderTexture.format != renderTextureFormat || historyRecord.fgRenderTexture.depth != num)
		{
			historyRecord.fgRenderTexture = new RenderTexture(width, height, num, renderTextureFormat);
			historyRecord.fgRenderTexture.name = "Sandwich FG " + historyRecordCursorIndex;
		}
		fgCamera.targetTexture = historyRecord.fgRenderTexture;
		if (historyRecord.bgRenderTexture == null || historyRecord.bgRenderTexture.width != width || historyRecord.bgRenderTexture.height != height || historyRecord.bgRenderTexture.format != renderTextureFormat || historyRecord.bgRenderTexture.depth != num)
		{
			historyRecord.bgRenderTexture = new RenderTexture(width, height, num, renderTextureFormat);
			historyRecord.bgRenderTexture.name = "Sandwich BG " + historyRecordCursorIndex;
		}
		bgCamera.targetTexture = historyRecord.bgRenderTexture;
		if (OVRManager.instance.virtualGreenScreenType != OVRManager.VirtualGreenScreenType.Off)
		{
			if (historyRecord.boundaryMeshMaskTexture == null || historyRecord.boundaryMeshMaskTexture.width != width || historyRecord.boundaryMeshMaskTexture.height != height)
			{
				historyRecord.boundaryMeshMaskTexture = new RenderTexture(width, height, 0, RenderTextureFormat.R8);
				historyRecord.boundaryMeshMaskTexture.name = "Boundary Mask " + historyRecordCursorIndex;
				historyRecord.boundaryMeshMaskTexture.Create();
			}
		}
		else
		{
			historyRecord.boundaryMeshMaskTexture = null;
		}
	}

	protected HistoryRecord GetHistoryRecordForComposition()
	{
		float num = frameRealtime - OVRManager.instance.sandwichCompositionRenderLatency;
		int num2 = historyRecordCursorIndex;
		int num3 = num2 - 1;
		if (num3 < 0)
		{
			num3 = historyRecordCount - 1;
		}
		while (num3 != historyRecordCursorIndex)
		{
			if (historyRecordArray[num3].timestamp <= num)
			{
				float num4 = historyRecordArray[num2].timestamp - num;
				float num5 = num - historyRecordArray[num3].timestamp;
				return (!(num4 <= num5)) ? historyRecordArray[num3] : historyRecordArray[num2];
			}
			num2 = num3--;
			if (num3 < 0)
			{
				num3 = historyRecordCount - 1;
			}
		}
		return historyRecordArray[num2];
	}

	protected void RefreshCameraPoses(float fovY, float aspect, OVRPose pose)
	{
		Camera[] array = new Camera[3] { fgCamera, bgCamera, compositionCamera };
		Camera[] array2 = array;
		foreach (Camera camera in array2)
		{
			camera.fieldOfView = fovY;
			camera.aspect = aspect;
			camera.transform.FromOVRPose(pose);
		}
	}
}
public class OVRBoundary
{
	public enum Node
	{
		HandLeft = 3,
		HandRight = 4,
		Head = 9
	}

	public enum BoundaryType
	{
		OuterBoundary = 1,
		PlayArea = 0x100
	}

	public struct BoundaryTestResult
	{
		public bool IsTriggering;

		public float ClosestDistance;

		public Vector3 ClosestPoint;

		public Vector3 ClosestPointNormal;
	}

	public struct BoundaryLookAndFeel
	{
		public Color Color;
	}

	private static int cachedVector3fSize = Marshal.SizeOf(typeof(OVRPlugin.Vector3f));

	private static OVRNativeBuffer cachedGeometryNativeBuffer = new OVRNativeBuffer(0);

	private static float[] cachedGeometryManagedBuffer = new float[0];

	public bool GetConfigured()
	{
		return OVRPlugin.GetBoundaryConfigured();
	}

	public BoundaryTestResult TestNode(Node node, BoundaryType boundaryType)
	{
		OVRPlugin.BoundaryTestResult boundaryTestResult = OVRPlugin.TestBoundaryNode((OVRPlugin.Node)node, (OVRPlugin.BoundaryType)boundaryType);
		return new BoundaryTestResult
		{
			IsTriggering = (boundaryTestResult.IsTriggering == OVRPlugin.Bool.True),
			ClosestDistance = boundaryTestResult.ClosestDistance,
			ClosestPoint = boundaryTestResult.ClosestPoint.FromFlippedZVector3f(),
			ClosestPointNormal = boundaryTestResult.ClosestPointNormal.FromFlippedZVector3f()
		};
	}

	public BoundaryTestResult TestPoint(Vector3 point, BoundaryType boundaryType)
	{
		OVRPlugin.BoundaryTestResult boundaryTestResult = OVRPlugin.TestBoundaryPoint(point.ToFlippedZVector3f(), (OVRPlugin.BoundaryType)boundaryType);
		return new BoundaryTestResult
		{
			IsTriggering = (boundaryTestResult.IsTriggering == OVRPlugin.Bool.True),
			ClosestDistance = boundaryTestResult.ClosestDistance,
			ClosestPoint = boundaryTestResult.ClosestPoint.FromFlippedZVector3f(),
			ClosestPointNormal = boundaryTestResult.ClosestPointNormal.FromFlippedZVector3f()
		};
	}

	public void SetLookAndFeel(BoundaryLookAndFeel lookAndFeel)
	{
		OVRPlugin.BoundaryLookAndFeel boundaryLookAndFeel = new OVRPlugin.BoundaryLookAndFeel
		{
			Color = lookAndFeel.Color.ToColorf()
		};
		OVRPlugin.SetBoundaryLookAndFeel(boundaryLookAndFeel);
	}

	public void ResetLookAndFeel()
	{
		OVRPlugin.ResetBoundaryLookAndFeel();
	}

	public Vector3[] GetGeometry(BoundaryType boundaryType)
	{
		int pointsCount = 0;
		if (OVRPlugin.GetBoundaryGeometry2((OVRPlugin.BoundaryType)boundaryType, IntPtr.Zero, ref pointsCount) && pointsCount > 0)
		{
			int num = pointsCount * cachedVector3fSize;
			if (cachedGeometryNativeBuffer.GetCapacity() < num)
			{
				cachedGeometryNativeBuffer.Reset(num);
			}
			int num2 = pointsCount * 3;
			if (cachedGeometryManagedBuffer.Length < num2)
			{
				cachedGeometryManagedBuffer = new float[num2];
			}
			if (OVRPlugin.GetBoundaryGeometry2((OVRPlugin.BoundaryType)boundaryType, cachedGeometryNativeBuffer.GetPointer(), ref pointsCount))
			{
				Marshal.Copy(cachedGeometryNativeBuffer.GetPointer(), cachedGeometryManagedBuffer, 0, num2);
				Vector3[] array = new Vector3[pointsCount];
				for (int i = 0; i < pointsCount; i++)
				{
					ref Vector3 reference = ref array[i];
					reference = new OVRPlugin.Vector3f
					{
						x = cachedGeometryManagedBuffer[3 * i],
						y = cachedGeometryManagedBuffer[3 * i + 1],
						z = cachedGeometryManagedBuffer[3 * i + 2]
					}.FromFlippedZVector3f();
				}
				return array;
			}
		}
		return new Vector3[0];
	}

	public Vector3 GetDimensions(BoundaryType boundaryType)
	{
		return OVRPlugin.GetBoundaryDimensions((OVRPlugin.BoundaryType)boundaryType).FromVector3f();
	}

	public bool GetVisible()
	{
		return OVRPlugin.GetBoundaryVisible();
	}

	public void SetVisible(bool value)
	{
		OVRPlugin.SetBoundaryVisible(value);
	}
}
