public static class AGPhotonHelper
{
	private static FieldInfo photonPeer_peerBaseInfo;

	private static FieldInfo peerBase_sentReliableCommandsInfo;

	public static int PendingSentReliableCommands
	{
		get
		{
			object value = photonPeer_peerBaseInfo.GetValue(PhotonNetwork.networkingPeer);
			IList list = peerBase_sentReliableCommandsInfo.GetValue(value) as IList;
			lock (list)
			{
				return list.Count;
			}
		}
	}

	static AGPhotonHelper()
	{
		System.Type typeFromHandle = typeof(PhotonPeer);
		Assembly assembly = typeFromHandle.Assembly;
		photonPeer_peerBaseInfo = typeFromHandle.GetField("peerBase", BindingFlags.Instance | BindingFlags.NonPublic);
		System.Type type = assembly.GetType("ExitGames.Client.Photon.EnetPeer", throwOnError: true, ignoreCase: true);
		peerBase_sentReliableCommandsInfo = type.GetField("sentReliableCommands", BindingFlags.Instance | BindingFlags.NonPublic);
	}

	public static float CalculateRoundTripTimeMs(bool useExponentialBackoff, int sendCount = 1)
	{
		int num = PhotonNetwork.networkingPeer.RoundTripTime + PhotonNetwork.networkingPeer.RoundTripTimeVariance * 4;
		if (useExponentialBackoff)
		{
			float num2 = 2f;
			return (float)num * (1f - Mathf.Pow(num2, sendCount)) / (1f - num2);
		}
		return num * sendCount;
	}
}
internal static class CustomTypes
{
	private static readonly RecRoom.Networking.BitPacker bitPacker = new RecRoom.Networking.BitPacker();

	public static readonly byte[] memVector3 = new byte[12];

	public static readonly byte[] memVector2 = new byte[8];

	public static readonly byte[] memVector4 = new byte[16];

	public static readonly byte[] memUncompressedQuaternion = new byte[16];

	public static readonly byte[] memGuid = new byte[16];

	public static readonly byte[] memPlayer = new byte[4];

	internal static void Register()
	{
		PhotonPeer.RegisterType(typeof(Vector2), 87, SerializeVector2, DeserializeVector2);
		PhotonPeer.RegisterType(typeof(Vector3), 86, SerializeVector3, DeserializeVector3);
		PhotonPeer.RegisterType(typeof(Vector4), 90, SerializeVector4, DeserializeVector4);
		PhotonPeer.RegisterType(typeof(Color), 67, SerializeColor, DeserializeColor);
		PhotonPeer.RegisterType(typeof(Quaternion), 81, SerializeQuaternion, DeserializeQuaternion);
		PhotonPeer.RegisterType(typeof(UncompressedQuaternion), 82, SerializeUncompressedQuaternion, DeserializeUncompressedQuaternion);
		PhotonPeer.RegisterType(typeof(Guid), 71, SerializeGuid, DeserializeGuid);
		PhotonPeer.RegisterType(typeof(QuadControlPoint), 69, QuadControlPoint.Serialize, QuadControlPoint.Deserialize);
		PhotonPeer.RegisterType(typeof(ToolHolderInfo), 84, ToolHolderInfo.Serialize, ToolHolderInfo.Deserialize);
		PhotonPeer.RegisterType(typeof(NetworkTransform.SyncData), 78, NetworkTransform.SyncData.Serialize, NetworkTransform.SyncData.Deserialize);
		PhotonPeer.RegisterType(typeof(ToolCleanup.CleanupOverrides), 85, ToolCleanup.CleanupOverrides.Serialize, ToolCleanup.CleanupOverrides.Deserialize);
		PhotonPeer.RegisterType(typeof(IndexedMap<string>.Pair), 80, ToolTagManager.SerializeTagPair, ToolTagManager.DeserializeTagPair);
	}

	private static short SerializeVector3(StreamBuffer outStream, object customobject)
	{
		Vector3 vector = (Vector3)customobject;
		int targetOffset = 0;
		lock (memVector3)
		{
			byte[] array = memVector3;
			Protocol.Serialize(vector.x, array, ref targetOffset);
			Protocol.Serialize(vector.y, array, ref targetOffset);
			Protocol.Serialize(vector.z, array, ref targetOffset);
			outStream.Write(array, 0, 12);
		}
		return 12;
	}

	private static object DeserializeVector3(StreamBuffer inStream, short length)
	{
		Vector3 vector = default(Vector3);
		lock (memVector3)
		{
			inStream.Read(memVector3, 0, 12);
			int offset = 0;
			Protocol.Deserialize(out vector.x, memVector3, ref offset);
			Protocol.Deserialize(out vector.y, memVector3, ref offset);
			Protocol.Deserialize(out vector.z, memVector3, ref offset);
		}
		return vector;
	}

	private static short SerializeVector2(StreamBuffer outStream, object customobject)
	{
		Vector2 vector = (Vector2)customobject;
		lock (memVector2)
		{
			byte[] array = memVector2;
			int targetOffset = 0;
			Protocol.Serialize(vector.x, array, ref targetOffset);
			Protocol.Serialize(vector.y, array, ref targetOffset);
			outStream.Write(array, 0, 8);
		}
		return 8;
	}

	private static object DeserializeVector2(StreamBuffer inStream, short length)
	{
		Vector2 vector = default(Vector2);
		lock (memVector2)
		{
			inStream.Read(memVector2, 0, 8);
			int offset = 0;
			Protocol.Deserialize(out vector.x, memVector2, ref offset);
			Protocol.Deserialize(out vector.y, memVector2, ref offset);
		}
		return vector;
	}

	private static short SerializeVector4(StreamBuffer outStream, object customobject)
	{
		Vector4 vector = (Vector4)customobject;
		int targetOffset = 0;
		lock (memVector4)
		{
			byte[] array = memVector4;
			Protocol.Serialize(vector.x, array, ref targetOffset);
			Protocol.Serialize(vector.y, array, ref targetOffset);
			Protocol.Serialize(vector.z, array, ref targetOffset);
			Protocol.Serialize(vector.w, array, ref targetOffset);
			outStream.Write(array, 0, 16);
		}
		return 16;
	}

	private static object DeserializeVector4(StreamBuffer inStream, short length)
	{
		Vector4 vector = default(Color);
		lock (memVector4)
		{
			inStream.Read(memVector4, 0, 16);
			int offset = 0;
			Protocol.Deserialize(out vector.x, memVector4, ref offset);
			Protocol.Deserialize(out vector.y, memVector4, ref offset);
			Protocol.Deserialize(out vector.z, memVector4, ref offset);
			Protocol.Deserialize(out vector.w, memVector4, ref offset);
		}
		return vector;
	}

	private static short SerializeColor(StreamBuffer outStream, object customobject)
	{
		Color color = (Color)customobject;
		int targetOffset = 0;
		lock (memVector4)
		{
			byte[] array = memVector4;
			Protocol.Serialize(color.r, array, ref targetOffset);
			Protocol.Serialize(color.g, array, ref targetOffset);
			Protocol.Serialize(color.b, array, ref targetOffset);
			Protocol.Serialize(color.a, array, ref targetOffset);
			outStream.Write(array, 0, 16);
		}
		return 16;
	}

	private static object DeserializeColor(StreamBuffer inStream, short length)
	{
		Color color = default(Color);
		lock (memVector4)
		{
			inStream.Read(memVector4, 0, 16);
			int offset = 0;
			Protocol.Deserialize(out color.r, memVector4, ref offset);
			Protocol.Deserialize(out color.g, memVector4, ref offset);
			Protocol.Deserialize(out color.b, memVector4, ref offset);
			Protocol.Deserialize(out color.a, memVector4, ref offset);
		}
		return color;
	}

	private static short SerializeQuaternion(StreamBuffer outStream, object customobject)
	{
		Quaternion q = (Quaternion)customobject;
		lock (bitPacker)
		{
			bitPacker.StartWriting(outStream);
			bitPacker.WriteQuaternion(q);
			return (short)bitPacker.FinishWriting();
		}
	}

	private static object DeserializeQuaternion(StreamBuffer inStream, short length)
	{
		Quaternion quaternion;
		lock (bitPacker)
		{
			bitPacker.StartReading(inStream, length);
			quaternion = bitPacker.ReadQuaternion();
			bitPacker.FinishReading();
		}
		return quaternion;
	}

	private static short SerializeUncompressedQuaternion(StreamBuffer outStream, object customobject)
	{
		Quaternion quaternion = (UncompressedQuaternion)customobject;
		int targetOffset = 0;
		lock (memUncompressedQuaternion)
		{
			byte[] array = memUncompressedQuaternion;
			Protocol.Serialize(quaternion.x, array, ref targetOffset);
			Protocol.Serialize(quaternion.y, array, ref targetOffset);
			Protocol.Serialize(quaternion.z, array, ref targetOffset);
			Protocol.Serialize(quaternion.w, array, ref targetOffset);
			outStream.Write(array, 0, 16);
		}
		return 16;
	}

	private static object DeserializeUncompressedQuaternion(StreamBuffer inStream, short length)
	{
		Quaternion quaternion = default(Quaternion);
		lock (memUncompressedQuaternion)
		{
			inStream.Read(memUncompressedQuaternion, 0, 16);
			int offset = 0;
			Protocol.Deserialize(out quaternion.x, memUncompressedQuaternion, ref offset);
			Protocol.Deserialize(out quaternion.y, memUncompressedQuaternion, ref offset);
			Protocol.Deserialize(out quaternion.z, memUncompressedQuaternion, ref offset);
			Protocol.Deserialize(out quaternion.w, memUncompressedQuaternion, ref offset);
		}
		return (UncompressedQuaternion)quaternion;
	}

	private static short SerializeGuid(StreamBuffer outStream, object customobject)
	{
		byte[] buffer = ((Guid)customobject).ToByteArray();
		outStream.Write(buffer, 0, 16);
		return 16;
	}

	private static object DeserializeGuid(StreamBuffer inStream, short length)
	{
		lock (memGuid)
		{
			inStream.Read(memGuid, 0, 16);
		}
		return new Guid(memGuid);
	}

	private static short SerializePhotonPlayer(StreamBuffer outStream, object customobject)
	{
		int iD = ((PhotonPlayer)customobject).ID;
		lock (memPlayer)
		{
			byte[] array = memPlayer;
			int targetOffset = 0;
			Protocol.Serialize(iD, array, ref targetOffset);
			outStream.Write(array, 0, 4);
			return 4;
		}
	}

	private static object DeserializePhotonPlayer(StreamBuffer inStream, short length)
	{
		int value;
		lock (memPlayer)
		{
			inStream.Read(memPlayer, 0, length);
			int offset = 0;
			Protocol.Deserialize(out value, memPlayer, ref offset);
		}
		if (PhotonNetwork.networkingPeer.mActors.ContainsKey(value))
		{
			return PhotonNetwork.networkingPeer.mActors[value];
		}
		return null;
	}
}
