	public class GizmoTypeDrawer
	{
		public static void Draw(Vector3 center, GizmoType type, Color color, float size)
		{
			Gizmos.color = color;
			switch (type)
			{
			case GizmoType.Cube:
				Gizmos.DrawCube(center, Vector3.one * size);
				break;
