	private int GenerateBulkId()
	{
		int result = LocalPlayer.ID * PhotonNetwork.MAX_VIEW_IDS + nextBulkId;
		nextBulkId = (nextBulkId + 1) % PhotonNetwork.MAX_VIEW_IDS;
		return result;
	}

	private int GetBulkIdFromInstantiationId(int instantiationId)
	{
		if (!instantiationIdToBulkIdMap.TryGetValue(instantiationId, out var value))
		{
			return 0;
		}
		return value;
	}

	internal ExitGames.Client.Photon.Hashtable SendBulkInstantiate(ExitGames.Client.Photon.Hashtable[] instantiateEvents)
	{
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable[(byte)0] = GenerateBulkId();
		hashtable[(byte)1] = instantiateEvents;
		RaiseEventOptions raiseEventOptions = new RaiseEventOptions();
		raiseEventOptions.CachingOption = EventCaching.AddToRoomCacheGlobal;
		OpRaiseEvent(1, hashtable, sendReliable: true, raiseEventOptions);
		return hashtable;
	}

	internal GameObject[] DoBulkInstantiate(ExitGames.Client.Photon.Hashtable evData, PhotonPlayer photonPlayer, GameObject[] resourceGameObjects)
	{
		int num = (int)evData[(byte)0];
		ExitGames.Client.Photon.Hashtable[] array = (ExitGames.Client.Photon.Hashtable[])evData[(byte)1];
		HashSet<int> hashSet = new HashSet<int>();
		for (int i = 0; i < array.Length; i++)
		{
			int num2 = (int)array[i][(byte)7];
			hashSet.Add(num2);
			instantiationIdToBulkIdMap[num2] = num;
		}
		bulkIdToInstantiationIdsMap[num] = hashSet;
		GameObject[] array2 = new GameObject[array.Length];
		for (int j = 0; j < array.Length; j++)
		{
			array2[j] = DoInstantiate(array[j], photonPlayer, (resourceGameObjects == null) ? null : resourceGameObjects[j]);
		}
		return array2;
	}

	internal void SendBulkDestroy(IList<GameObject> gameObjects)
	{
		HashSet<int> hashSet = new HashSet<int>();
		HashSet<int> hashSet2 = new HashSet<int>();
		foreach (GameObject gameObject in gameObjects)
		{
			if (gameObject == null)
			{
				UnityEngine.Debug.LogError("BulkDestroy failed because the array contains a NULL entry");
				return;
			}
			PhotonView[] componentsInChildren = gameObject.GetComponentsInChildren<PhotonView>(includeInactive: true);
			if (componentsInChildren == null || componentsInChildren.Length <= 0)
			{
				UnityEngine.Debug.LogError("BulkDestroy failed because one of the game objects has no PhotonView components: " + gameObject);
				return;
			}
			int instantiationId = componentsInChildren[0].instantiationId;
			HashSet<int> hashSet3 = ((!componentsInChildren[0].isRuntimeInstantiated) ? hashSet : hashSet2);
			hashSet3.Add(instantiationId);
		}
		if (hashSet2.Count > 0)
		{
			Dictionary<int, HashSet<int>> dictionary = new Dictionary<int, HashSet<int>>();
			foreach (int item in hashSet2)
			{
				if (!instantiationIdToBulkIdMap.TryGetValue(item, out var value))
				{
					value = 0;
				}
				if (!dictionary.TryGetValue(value, out var value2))
				{
					value2 = new HashSet<int>();
					dictionary.Add(value, value2);
				}
				value2.Add(item);
			}
			foreach (KeyValuePair<int, HashSet<int>> item2 in dictionary)
			{
				int key = item2.Key;
				HashSet<int> value3 = item2.Value;
				if (key == 0)
				{
					foreach (int item3 in value3)
					{
						int num = item3 / PhotonNetwork.MAX_VIEW_IDS;
						RaiseEventOptions raiseEventOptions = new RaiseEventOptions();
						raiseEventOptions.CachingOption = EventCaching.RemoveFromRoomCache;
						raiseEventOptions.TargetActors = new int[1] { num };
						ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
						hashtable[(byte)7] = item3;
						OpRaiseEvent(202, hashtable, sendReliable: true, raiseEventOptions);
					}
				}
				else if (bulkIdToInstantiationIdsMap[key].Count == value3.Count)
				{
					ServerCleanBulkInstantiate(key);
				}
				else
				{
					ServerDestroyMultipleObjectsFromBulkInstantiation(key, value3.ToArray());
					hashSet2.ExceptWith(value3);
				}
			}
		}
		if (hashSet2.Count > 0)
		{
			ExitGames.Client.Photon.Hashtable hashtable2 = new ExitGames.Client.Photon.Hashtable();
			hashtable2[(byte)1] = hashSet2.ToArray();
			OpRaiseEvent(2, hashtable2, sendReliable: true, null);
		}
		if (hashSet.Count > 0)
		{
			ExitGames.Client.Photon.Hashtable hashtable3 = new ExitGames.Client.Photon.Hashtable();
			hashtable3[(byte)1] = hashSet.ToArray();
			RaiseEventOptions raiseEventOptions2 = new RaiseEventOptions();
			raiseEventOptions2.CachingOption = EventCaching.AddToRoomCacheGlobal;
			OpRaiseEvent(2, hashtable3, sendReliable: true, raiseEventOptions2);
		}
		foreach (GameObject gameObject2 in gameObjects)
		{
			RemoveInstantiatedGO(gameObject2, localOnly: true);
		}
	}

	private void ServerDestroyMultipleObjectsFromBulkInstantiation(int bulkId, int[] instantiationIds)
	{
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable[(byte)0] = bulkId;
		hashtable[(byte)1] = instantiationIds;
		RaiseEventOptions raiseEventOptions = new RaiseEventOptions();
		raiseEventOptions.CachingOption = EventCaching.AddToRoomCacheGlobal;
		OpRaiseEvent(2, hashtable, sendReliable: true, raiseEventOptions);
	}

	private void ServerDestroySingleObjectFromBulkInstantiation(int bulkId, int instantiationId)
	{
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable[(byte)0] = bulkId;
		hashtable[(byte)2] = instantiationId;
		RaiseEventOptions raiseEventOptions = new RaiseEventOptions();
		raiseEventOptions.CachingOption = EventCaching.AddToRoomCacheGlobal;
		OpRaiseEvent(2, hashtable, sendReliable: true, raiseEventOptions);
	}

	private void DoBulkDestroy(ExitGames.Client.Photon.Hashtable evData)
	{
		PhotonView value;
		if (evData.ContainsKey((byte)1))
		{
			int[] array = (int[])evData[(byte)1];
			int[] array2 = array;
			foreach (int key in array2)
			{
				if (photonViewList.TryGetValue(key, out value))
				{
					RemoveInstantiatedGO(value.gameObject, localOnly: true);
				}
			}
		}
		else if (evData.ContainsKey((byte)2))
		{
			int key2 = (int)evData[(byte)2];
			if (photonViewList.TryGetValue(key2, out value))
			{
				RemoveInstantiatedGO(value.gameObject, localOnly: true);
			}
		}
	}

	private void RemoveFromBulkInstantiation(int instantiationId, int bulkId, bool localOnly)
	{
		instantiationIdToBulkIdMap.Remove(instantiationId);
		HashSet<int> hashSet = bulkIdToInstantiationIdsMap[bulkId];
		hashSet.Remove(instantiationId);
		if (!localOnly && hashSet.Count == 0)
		{
			ServerCleanBulkInstantiate(bulkId);
		}
	}

	private void ServerCleanBulkInstantiate(int bulkId)
	{
		RaiseEventOptions raiseEventOptions = new RaiseEventOptions();
		raiseEventOptions.CachingOption = EventCaching.RemoveFromRoomCache;
		ExitGames.Client.Photon.Hashtable hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable[(byte)0] = bulkId;
		OpRaiseEvent(1, hashtable, sendReliable: true, raiseEventOptions);
		hashtable = new ExitGames.Client.Photon.Hashtable();
		hashtable[(byte)0] = bulkId;
		OpRaiseEvent(2, hashtable, sendReliable: true, raiseEventOptions);
	}

	public override bool DispatchIncomingCommands()
	{
		backgroundWorkerIncoming.Set();
		ProcessBackgroundQueuedActions();
		return false;
	}

	private void ProcessBackgroundQueuedActions()
	{
		while (PhotonNetwork.isMessageQueueRunning && backgroundWorkerActionQueue.Count > 0)
		{
			Action action = null;
			lock (backgroundWorkerActionQueue)
			{
				action = backgroundWorkerActionQueue.Dequeue();
			}
			action();
		}
	}

	public void DebugReturn(DebugLevel level, string message)
	{
		InternalDebugReturn(level, message);
	}

	public void OnOperationResponse(OperationResponse operationResponse)
	{
		EnqueueAction(delegate
		{
			InternalOnOperationResponse(operationResponse);
		});
	}

	public void OnStatusChanged(StatusCode statusCode)
	{
		EnqueueAction(delegate
		{
			InternalOnStatusChanged(statusCode);
		});
	}

	public void OnEvent(EventData photonEvent)
	{
		EnqueueAction(delegate
		{
			InternalOnEvent(photonEvent);
		});
	}

	private void EnqueueAction(Action action)
	{
		lock (backgroundWorkerActionQueue)
		{
			backgroundWorkerActionQueue.Enqueue(action);
		}
	}

	private void StartBackgroundWorkerThreads()
	{
		StartBackgroundThread(BackgroundWorkerIncomingThread, "Photon Background Incoming Worker");
		StartBackgroundThread(BackgroundWorkerOutgoingThread, "Photon Background Outgoing Worker");
	}

	public void StopBackgroundWorkerThreads()
	{
		stopBackgroundWorkers = true;
		backgroundWorkerIncoming.Set();
		backgroundWorkerOutgoing.Set();
	}

	private void StartBackgroundThread(ThreadStart threadStart, string name)
	{
		Thread thread = new Thread(threadStart);
		thread.Name = name;
		thread.Start();
	}

	private void BackgroundWorkerIncomingThread()
	{
		BackgroundWorkerThread(backgroundWorkerIncoming, base.DispatchIncomingCommands);
	}

	private void BackgroundWorkerOutgoingThread()
	{
		BackgroundWorkerThread(backgroundWorkerOutgoing, base.SendOutgoingCommands);
	}

	private void BackgroundWorkerThread(AutoResetEvent wakeupEvent, Func<bool> action)
	{
		try
		{
			while (true)
			{
				wakeupEvent.WaitOne();
				if (stopBackgroundWorkers)
				{
					break;
				}
				try
				{
					while (action())
					{
					}
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
		}
		catch (Exception exception2)
		{
			UnityEngine.Debug.LogException(exception2);
		}
		finally
		{
			wakeupEvent.Close();
		}
	}
}
