		manuallyAllocatedViewIds = new List<int>();
		INSTANTANEOUS_GAME_OBJECT_LIST = new List<GameObject>();
		OnConnectedToPhoton = new ActionEvent(32, useTryCatch: true);
		OnLeftRoom = new ActionEvent(32, useTryCatch: true);
		OnMasterClientSwitched = new ActionEvent<PhotonPlayer>(32, useTryCatch: true);
		OnPhotonCreateRoomFailed = new ActionEvent<short, string>(32, useTryCatch: true);
		OnPhotonJoinRoomFailed = new ActionEvent<short, string>(32, useTryCatch: true);
		OnCreatedRoom = new ActionEvent(32, useTryCatch: true);
		OnJoinedLobby = new ActionEvent(32, useTryCatch: true);
		OnLeftLobby = new ActionEvent(32, useTryCatch: true);
		OnFailedToConnectToPhoton = new ActionEvent<DisconnectCause>(32, useTryCatch: true);
		OnConnectionFail = new ActionEvent<DisconnectCause>(32, useTryCatch: true);
		OnDisconnectedFromPhoton = new ActionEvent(32, useTryCatch: true);
