	{
		return Instantiate(prefabName, position, rotation, scale, group, new object[2] { instantiatorPhotonViewId, instantiationParameters });
	}

	public static GameObject GetPrefab(string prefabName)
	{
		if (!UsePrefabCache || !PrefabCache.TryGetValue(prefabName, out var value))
		{
			value = (GameObject)Resources.Load(prefabName, typeof(GameObject));
			if (UsePrefabCache)
			{
				PrefabCache.Add(prefabName, value);
			}
		}
		return value;
	}

	public static GameObject Instantiate(string prefabName, Vector3 position, Quaternion rotation, float scale, byte group, object[] data)
	{
		if (!connected || (InstantiateInRoomOnly && !inRoom))
		{
			UnityEngine.Debug.LogError("Failed to Instantiate prefab: " + prefabName + ". Client should be in a room. Current connectionStateDetailed: " + connectionStateDetailed);
			return null;
		}
		GameObject prefab = GetPrefab(prefabName);
		if (prefab == null)
		{
			UnityEngine.Debug.LogError("Failed to Instantiate prefab: " + prefabName + ". Verify the Prefab is in a Resources folder (and not in a subfolder)");
			return null;
		}
		if (prefab.GetComponent<PhotonView>() == null)
		{
			UnityEngine.Debug.LogError("Failed to Instantiate prefab:" + prefabName + ". Prefab must have a PhotonView component.");
			return null;
		}
		UnityEngine.Component[] photonViewsInChildren = prefab.GetPhotonViewsInChildren();
		int[] array = new int[photonViewsInChildren.Length];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = AllocateViewID(player.ID);
		}
		ExitGames.Client.Photon.Hashtable evData = networkingPeer.SendInstantiate(prefabName, position, rotation, scale, group, array, data, isGlobalObject: false);
		return networkingPeer.DoInstantiate(evData, networkingPeer.LocalPlayer, prefab);
	}

	public static GameObject InstantiateSceneObjectEx(string prefabName, Vector3 position, Quaternion rotation, float scale, byte group, int instantiatorPhotonViewId, Dictionary<string, object> instantiationParameters)
	{
