	public static GameObject InstantiateSceneObject(string prefabName, Vector3 position, Quaternion rotation, float scale, byte group, object[] data)
	{
		if (!connected || (InstantiateInRoomOnly && !inRoom))
		{
			UnityEngine.Debug.LogError("Failed to InstantiateSceneObject prefab: " + prefabName + ". Client should be in a room. Current connectionStateDetailed: " + connectionStateDetailed);
			return null;
		}
		if (!isMasterClient)
		{
			UnityEngine.Debug.LogError("Failed to InstantiateSceneObject prefab: " + prefabName + ". Client is not the MasterClient in this room.");
			return null;
		}
		if (!UsePrefabCache || !PrefabCache.TryGetValue(prefabName, out var value))
		{
			value = (GameObject)Resources.Load(prefabName, typeof(GameObject));
			if (UsePrefabCache)
			{
				PrefabCache.Add(prefabName, value);
			}
		}
		if (value == null)
		{
			UnityEngine.Debug.LogError("Failed to InstantiateSceneObject prefab: " + prefabName + ". Verify the Prefab is in a Resources folder (and not in a subfolder)");
			return null;
		}
		if (value.GetComponent<PhotonView>() == null)
		{
			UnityEngine.Debug.LogError("Failed to InstantiateSceneObject prefab:" + prefabName + ". Prefab must have a PhotonView component.");
			return null;
		}
		UnityEngine.Component[] photonViewsInChildren = value.GetPhotonViewsInChildren();
		int[] array = AllocateSceneViewIDs(photonViewsInChildren.Length);
		if (array == null)
		{
			UnityEngine.Debug.LogError("Failed to InstantiateSceneObject prefab: " + prefabName + ". No ViewIDs are free to use. Max is: " + MAX_VIEW_IDS);
			return null;
		}
		ExitGames.Client.Photon.Hashtable evData = networkingPeer.SendInstantiate(prefabName, position, rotation, scale, group, array, data, isGlobalObject: true);
		return networkingPeer.DoInstantiate(evData, networkingPeer.LocalPlayer, value);
	}

	public static GameObject[] BulkInstantiateSceneObjectsEx(IList<InstantiateRequestEx> requests)
	{
		InstantiateRequest[] array = new InstantiateRequest[requests.Count];
		for (int i = 0; i < requests.Count; i++)
		{
			array[i] = requests[i].ToBaseRequest();
		}
		return BulkInstantiateSceneObjects(array);
	}

	public static GameObject[] BulkInstantiateSceneObjects(IList<InstantiateRequest> requests)
	{
		if (!isMasterClient)
		{
			UnityEngine.Debug.LogError("Failed to BulkInstantiateSceneObject prefabs. Client is not the MasterClient in this room.");
			return null;
		}
		if (!connected || (InstantiateInRoomOnly && !inRoom))
		{
			UnityEngine.Debug.LogError("Failed to BulkInstantiateSceneObject prefabs. Client should be in a room. Current connectionStateDetailed: " + connectionStateDetailed);
			return null;
		}
		if (requests.Count > 40)
		{
			INSTANTANEOUS_GAME_OBJECT_LIST.Clear();
			for (int i = 0; i < requests.Count; i += 40)
			{
				List<InstantiateRequest> requests2 = requests.SkipTake(i, 40).ToList();
				GameObject[] collection = BulkInstantiateSceneObjectsInternal(requests2);
				INSTANTANEOUS_GAME_OBJECT_LIST.AddRange(collection);
			}
			return INSTANTANEOUS_GAME_OBJECT_LIST.ToArray();
		}
		return BulkInstantiateSceneObjectsInternal(requests);
	}

	private static GameObject[] BulkInstantiateSceneObjectsInternal(IList<InstantiateRequest> requests)
	{
		GameObject[] array = new GameObject[requests.Count];
		for (int i = 0; i < requests.Count; i++)
		{
			string prefabName = requests[i].PrefabName;
			GameObject value = null;
			if (!UsePrefabCache || !PrefabCache.TryGetValue(prefabName, out value))
			{
				value = (GameObject)Resources.Load(prefabName, typeof(GameObject));
				if (UsePrefabCache)
				{
					PrefabCache.Add(prefabName, value);
				}
			}
			if (value == null)
			{
				UnityEngine.Debug.LogError("Failed to BulkInstantiateSceneObject prefab: " + prefabName + ". Verify the Prefab is in a Resources folder (and not in a subfolder)");
				return null;
			}
			if (value.GetComponent<PhotonView>() == null)
			{
				UnityEngine.Debug.LogError("Failed to BulkInstantiateSceneObject prefab:" + prefabName + ". Prefab must have a PhotonView component.");
				return null;
			}
			array[i] = value;
		}
		ExitGames.Client.Photon.Hashtable[] array2 = new ExitGames.Client.Photon.Hashtable[requests.Count];
		for (int j = 0; j < requests.Count; j++)
		{
			PhotonView[] photonViewsInChildren = array[j].GetPhotonViewsInChildren();
			int[] viewIDs = AllocateSceneViewIDs(photonViewsInChildren.Length);
			array2[j] = networkingPeer.CreateInstantiateEventData(requests[j].PrefabName, requests[j].Position, requests[j].Rotation, requests[j].Scale, 0, viewIDs, requests[j].Data);
		}
		ExitGames.Client.Photon.Hashtable evData = networkingPeer.SendBulkInstantiate(array2);
		return networkingPeer.DoBulkInstantiate(evData, networkingPeer.LocalPlayer, array);
	}

	public static void BulkDestroy(IList<GameObject> gameObjects)
	{
		if (gameObjects.Count > 75)
		{
			for (int i = 0; i < gameObjects.Count; i += 75)
			{
				List<GameObject> gameObjects2 = gameObjects.SkipTake(i, 75).ToList();
				networkingPeer.SendBulkDestroy(gameObjects2);
			}
		}
		else
		{
			networkingPeer.SendBulkDestroy(gameObjects);
		}
	}

