	private void UpdateCachedAuthority()
	{
		PhotonPlayer photonPlayer = cachedAuthority;
		hasCachedAuthorityValues = true;
		cachedIsMineNoMaster = ownerId == PhotonNetwork.player.ID;
		cachedIsMine = cachedIsMineNoMaster || (!isOwnerActive && PhotonNetwork.isMasterClient);
		cachedOwner = PhotonPlayer.Find(ownerId);
		cachedAuthority = cachedOwner ?? PhotonNetwork.masterClient;
		if (photonPlayer != cachedAuthority && OnCachedAuthorityChanged != null)
		{
			OnCachedAuthorityChanged(cachedAuthority);
		}
	}

	private void InitIsLocal()
	{
		if (!_isLocal.HasValue)
		{
			_isLocal = CreatorActorNr == PhotonNetwork.player.ID;
		}
