	protected internal void Awake()
	{
		PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		PhotonNetwork.OnJoinedRoom += new Action(OnJoinedRoom);
		PhotonNetwork.OnLeftRoom += new Action(OnLeftRoom);
		if (viewID != 0)
		{
			InitIsLocal();
			_ownerId = viewID / PhotonNetwork.MAX_VIEW_IDS;
			PhotonNetwork.networkingPeer.RegisterPhotonView(this);
			instantiationDataField = PhotonNetwork.networkingPeer.FetchInstantiationData(instantiationId);
		}
		didAwake = true;
	}

