	protected internal void OnDestroy()
	{
		if (!removedFromLocalViewList)
		{
			bool flag = PhotonNetwork.networkingPeer.LocalCleanPhotonView(this);
			bool flag2 = false;
			if (flag && !flag2 && instantiationId > 0 && !PhotonHandler.AppQuits && PhotonNetwork.logLevel >= PhotonLogLevel.Informational)
			{
				UnityEngine.Debug.Log("PUN-instantiated '" + base.gameObject.name + "' got destroyed by engine. This is OK when loading levels. Otherwise use: PhotonNetwork.Destroy().");
			}
		}
		PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		PhotonNetwork.OnJoinedRoom -= new Action(OnJoinedRoom);
		PhotonNetwork.OnLeftRoom -= new Action(OnLeftRoom);
		if (!onDestroyingCalled)
		{
			RaiseOnDestroyingEvent();
		}
		if (this.OnDestroyEvent != null)
		{
			this.OnDestroyEvent();
		}
	}

	public void SerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
