public class Punchkey : UnityEngine.MonoBehaviour
{
	public enum SpecialType
	{
		None,
		Space,
		BackSpace,
		Return,
		Alt,
		Shift
	}

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<Punchkey> m_Pressed;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Button3DBase button3d;

	[SerializeField]
	private SpecialType specialKeyType;

	[SerializeField]
	[Tooltip("If true the key will be repeated as long as it stays pressed. (e.g. Backspace)")]
	private bool supportsPressAndHold;

	public string KeyCapChar = string.Empty;

	public string KeyCapChar_Shift = string.Empty;

	public string KeyCapChar_Alt = string.Empty;

	private const float HeldKeyStartInterval = 1f;

	private const float HeldKeyPressFrequency = 0.1f;

	private float lastHeldKeyPressTime;

	private Punchkeyboard punchkeyboard;

	private Collider[] colliders;

	private ToggleButton3D toggleButton;

	private Coroutine keyHeldRoutine;

	private bool keyPressEnabled = true;

	public SpecialType SpecialKeyType => specialKeyType;

	public bool Toggled
	{
		get
		{
			return toggleButton != null && toggleButton.IsOn;
		}
		set
		{
			if (toggleButton != null)
			{
				toggleButton.IsOn = value;
			}
		}
	}

	public bool SupportsShift => !string.IsNullOrEmpty(KeyCapChar_Shift);

	public bool SupportsAlt => !string.IsNullOrEmpty(KeyCapChar_Alt);

	public bool KeyPressEnabled
	{
		get
		{
			return keyPressEnabled;
		}
		set
		{
			keyPressEnabled = value;
			if (colliders != null)
			{
				Collider[] array = colliders;
				foreach (Collider collider in array)
				{
					collider.enabled = value;
				}
			}
		}
	}

	public bool IsCharKey => specialKeyType == SpecialType.None;

	public event Action<Punchkey> Pressed
	{
		add
		{
			Action<Punchkey> action = this.m_Pressed;
			Action<Punchkey> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_Pressed, (Action<Punchkey>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<Punchkey> action = this.m_Pressed;
			Action<Punchkey> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_Pressed, (Action<Punchkey>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public void Initialize(Punchkeyboard keyboard)
	{
		punchkeyboard = keyboard;
		toggleButton = button3d as ToggleButton3D;
		if (toggleButton != null)
		{
			toggleButton.OnClick.AddListener(OnButtonToggle);
		}
		else
		{
			button3d.DownEvent += OnButtonDown;
		}
		colliders = GetComponentsInChildren<Collider>(includeInactive: true);
		Collider[] array = colliders;
		foreach (Collider collider in array)
		{
			collider.enabled = false;
		}
		RefreshKeyCapText();
	}

	private void OnButtonDown(Button3DBase thisButton)
	{
		PressKey();
		if (supportsPressAndHold)
		{
			this.SafeStopCoroutine(keyHeldRoutine);
			keyHeldRoutine = StartCoroutine(KeyHeldRoutine());
		}
	}

	private void OnButtonToggle(bool isOn)
	{
		PressKey();
	}

	private void PressKey()
	{
		punchkeyboard.SimulateKeyPress(this);
		if (this.Pressed != null)
		{
			this.Pressed(this);
		}
	}

	public void RefreshKeyCapText()
	{
		TextMeshProUGUI label = button3d.Label;
		if (label != null)
		{
			if (punchkeyboard.ShiftPressed && SupportsShift)
			{
				label.text = KeyCapChar_Shift;
			}
			else if (punchkeyboard.AltPressed && SupportsAlt)
			{
				label.text = KeyCapChar_Alt;
			}
			else if (!string.IsNullOrEmpty(KeyCapChar))
			{
				label.text = KeyCapChar;
			}
		}
	}

	private IEnumerator KeyHeldRoutine()
	{
		lastHeldKeyPressTime = UnityEngine.Time.time;
		yield return new WaitForSeconds(1f);
		while (button3d.ButtonPressed)
		{
			if (UnityEngine.Time.time - lastHeldKeyPressTime > 0.1f)
			{
				lastHeldKeyPressTime = UnityEngine.Time.time;
				PressKey();
			}
			yield return null;
		}
	}
}
public class Punchkeyboard : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Punchkey shiftKey;

	[SerializeField]
	private Punchkey altKey;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip keyPressedSuccess;

	[Header("Context specific keys")]
	public Transform EmailKeysRoot;

	[SerializeField]
	private Transform standardKeyboard;

	[SerializeField]
	private Transform numericKeyboard;

	private Punchkey[] charKeys;

	private Punchkey[] allKeys;

	private TMP_InputField inputField;

	private int currentCaretPosition;

	public Action OnAnyKeyPressed;

	private bool _keysEnabled;

	public bool ShiftPressed => shiftKey.Toggled;

	public bool AltPressed => altKey.Toggled;

	public bool KeysEnabled
	{
		get
		{
			return _keysEnabled;
		}
		set
		{
			_keysEnabled = value;
			if (allKeys != null)
			{
				Punchkey[] array = allKeys;
				foreach (Punchkey punchkey in array)
				{
					punchkey.KeyPressEnabled = value;
				}
			}
		}
	}

	private bool CanType
	{
		get
		{
			if (!Player.LocalPlayerExists)
			{
				return true;
			}
			PlayerLocomotion playerLocomotion = Player.LocalPlayer.PlayerLocomotion;
			return !playerLocomotion.TeleportRunning && !playerLocomotion.RotationBeingModified;
		}
	}

	private void Awake()
	{
		allKeys = GetComponentsInChildren<Punchkey>(includeInactive: true);
		charKeys = allKeys.Where((Punchkey k) => k.IsCharKey).ToArray();
		shiftKey.Pressed += ShiftKey_Pressed;
		altKey.Pressed += AltKey_Pressed;
		Punchkey[] array = allKeys;
		foreach (Punchkey punchkey in array)
		{
			punchkey.Initialize(this);
		}
		EmailKeysRoot.gameObject.SetActive(value: false);
	}

	private void Start()
	{
		Punchkey[] array = charKeys;
		foreach (Punchkey punchkey in array)
		{
			punchkey.RefreshKeyCapText();
		}
	}

	private void Update()
	{
		TMP_InputField focusedInputField = KeyboardInputField.FocusedInputField;
		if (inputField != focusedInputField)
		{
			inputField = focusedInputField;
			if (inputField != null && inputField.text != null)
			{
				currentCaretPosition = inputField.text.Length;
			}
			else
			{
				currentCaretPosition = 0;
			}
			RefreshKeyLayout();
		}
		if (inputField != null)
		{
			inputField.caretPosition = currentCaretPosition;
		}
	}

	private void RefreshKeyLayout()
	{
		EmailKeysRoot.gameObject.SetActive(inputField != null && inputField.contentType == TMP_InputField.ContentType.EmailAddress);
		bool flag = inputField != null && (inputField.contentType == TMP_InputField.ContentType.IntegerNumber || inputField.contentType == TMP_InputField.ContentType.DecimalNumber);
		standardKeyboard.gameObject.SetActive(!flag);
		numericKeyboard.gameObject.SetActive(flag);
	}

	private void ShiftKey_Pressed(Punchkey key)
	{
		altKey.Toggled = false;
		Punchkey[] array = charKeys;
		foreach (Punchkey punchkey in array)
		{
			punchkey.RefreshKeyCapText();
		}
	}

	private void AltKey_Pressed(Punchkey key)
	{
		shiftKey.Toggled = false;
		Punchkey[] array = charKeys;
		foreach (Punchkey punchkey in array)
		{
			punchkey.RefreshKeyCapText();
		}
	}

	public void SimulateKeyPress(Punchkey key)
	{
		if (!CanType)
		{
			return;
		}
		TMP_InputField tMP_InputField = inputField;
		if (tMP_InputField != null)
		{
			int length = tMP_InputField.text.Length;
			currentCaretPosition = Mathf.Clamp(currentCaretPosition, 0, length);
			if (key.IsCharKey)
			{
				string keyString = GetKeyString(key);
				tMP_InputField.text = tMP_InputField.text.Insert(currentCaretPosition, keyString);
				currentCaretPosition += keyString.Length;
				if (ShiftPressed)
				{
					shiftKey.Toggled = false;
					ShiftKey_Pressed(shiftKey);
				}
			}
			else if (key.SpecialKeyType == Punchkey.SpecialType.Space)
			{
				tMP_InputField.text = tMP_InputField.text.Insert(currentCaretPosition, " ");
				currentCaretPosition++;
			}
			else if (key.SpecialKeyType == Punchkey.SpecialType.BackSpace && tMP_InputField.text.Length > 0)
			{
				if (tMP_InputField.selectionAnchorPosition != tMP_InputField.selectionFocusPosition)
				{
					int startIndex = Mathf.Min(tMP_InputField.selectionAnchorPosition, tMP_InputField.selectionFocusPosition);
					tMP_InputField.text = tMP_InputField.text.Remove(startIndex, Mathf.Abs(tMP_InputField.selectionAnchorPosition - tMP_InputField.selectionFocusPosition));
					currentCaretPosition = startIndex;
				}
				else if (currentCaretPosition > 0)
				{
					tMP_InputField.text = tMP_InputField.text.Remove(currentCaretPosition - 1, 1);
					currentCaretPosition--;
				}
			}
			else if (key.SpecialKeyType == Punchkey.SpecialType.Return)
			{
				ExecuteEvents.Execute(tMP_InputField.gameObject, new BaseEventData(EventSystem.current), ExecuteEvents.submitHandler);
			}
			if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null && length != tMP_InputField.text.Length && tMP_InputField.contentType != TMP_InputField.ContentType.Password)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, tMP_InputField.text, 2f, null, updateIfSameStyle: true);
			}
		}
		AudioManager.Play3DSFX(keyPressedSuccess, key.transform.position);
		if (OnAnyKeyPressed != null)
		{
			OnAnyKeyPressed();
		}
	}

	private string GetKeyString(Punchkey key)
	{
		if (ShiftPressed && key.SupportsShift)
		{
			return key.KeyCapChar_Shift;
		}
		if (AltPressed && key.SupportsAlt)
		{
			return key.KeyCapChar_Alt;
		}
		return key.KeyCapChar;
	}
}
namespace ExitGames.Client.Photon.LoadBalancing
{
	public static class Extensions
	{
		public static void Merge(this IDictionary target, IDictionary addHash)
		{
			if (addHash == null || target.Equals(addHash))
			{
				return;
			}
			foreach (object key in addHash.Keys)
			{
				target[key] = addHash[key];
			}
		}

		public static void MergeStringKeys(this IDictionary target, IDictionary addHash)
		{
			if (addHash == null || target.Equals(addHash))
			{
				return;
			}
			foreach (object key in addHash.Keys)
			{
				if (key is string)
				{
					target[key] = addHash[key];
				}
			}
		}

		public static string ToStringFull(this IDictionary origin)
		{
			return SupportClass.DictionaryToString(origin, includeTypes: false);
		}

		public static string ToStringFull(this object[] data)
		{
			if (data == null)
			{
				return "null";
			}
			string[] array = new string[data.Length];
			for (int i = 0; i < data.Length; i++)
			{
				object obj = data[i];
				array[i] = ((obj == null) ? "null" : obj.ToString());
			}
			return string.Join(", ", array);
		}

		public static Hashtable StripToStringKeys(this IDictionary original)
		{
			Hashtable hashtable = new Hashtable();
			if (original != null)
			{
				foreach (object key in original.Keys)
				{
					if (key is string)
					{
						hashtable[key] = original[key];
					}
				}
			}
			return hashtable;
		}

		public static void StripKeysWithNullValues(this IDictionary original)
		{
			object[] array = new object[original.Count];
			original.Keys.CopyTo(array, 0);
			foreach (object key in array)
			{
				if (original[key] == null)
				{
					original.Remove(key);
				}
			}
		}

		public static bool Contains(this int[] target, int nr)
		{
			if (target == null)
			{
				return false;
			}
			for (int i = 0; i < target.Length; i++)
			{
				if (target[i] == nr)
				{
					return true;
				}
			}
			return false;
		}
	}
	public class FriendInfo
	{
		public string Name { get; protected internal set; }

		public bool IsOnline { get; protected internal set; }

		public string Room { get; protected internal set; }

		public bool IsInRoom => IsOnline && !string.IsNullOrEmpty(Room);

		public override string ToString()
		{
			return string.Format("{0}\t is: {1}", Name, (!IsOnline) ? "offline" : ((!IsInRoom) ? "on master" : "playing"));
		}
	}
