		public abstract class LevelMeter<T> : LocalVoiceFramed<T>.IProcessor, ILevelMeter, IDisposable
		{
			protected float ampSum;

			protected float ampPeak;

			protected int bufferSize;

			protected float[] buffer;

			protected int prevValuesPtr;

			protected float accumAvgPeakAmpSum;

			protected int accumAvgPeakAmpCount;

			public float CurrentAvgAmp => ampSum / (float)bufferSize;

			public float CurrentPeakAmp { get; protected set; }

			public float AccumAvgPeakAmp => (accumAvgPeakAmpCount != 0) ? (accumAvgPeakAmpSum / (float)accumAvgPeakAmpCount) : 0f;

			internal LevelMeter(int samplingRate, int numChannels)
			{
				bufferSize = samplingRate * numChannels / 2;
				buffer = new float[bufferSize];
			}

			public void ResetAccumAvgPeakAmp()
			{
				accumAvgPeakAmpSum = 0f;
				accumAvgPeakAmpCount = 0;
			}

			public abstract T[] Process(T[] buf);

			public void Dispose()
			{
			}
		}

		public class LevelMeterFloat : LevelMeter<float>
		{
			public LevelMeterFloat(int samplingRate, int numChannels)
				: base(samplingRate, numChannels)
			{
			}

			public override float[] Process(float[] buf)
			{
				foreach (float num in buf)
				{
					float num2 = num;
					if (num2 < 0f)
					{
						num2 = 0f - num2;
					}
					ampSum = ampSum + num2 - buffer[prevValuesPtr];
					buffer[prevValuesPtr] = num2;
					if (ampPeak < num2)
					{
						ampPeak = num2;
					}
					if (prevValuesPtr == 0)
					{
						base.CurrentPeakAmp = ampPeak;
						ampPeak = 0f;
						accumAvgPeakAmpSum += base.CurrentPeakAmp;
						accumAvgPeakAmpCount++;
					}
					prevValuesPtr = (prevValuesPtr + 1) % bufferSize;
				}
				return buf;
			}
		}

		public class LevelMeterShort : LevelMeter<short>
		{
			public LevelMeterShort(int samplingRate, int numChannels)
				: base(samplingRate, numChannels)
			{
			}

			public override short[] Process(short[] buf)
			{
				foreach (short num in buf)
				{
					short num2 = num;
					if (num2 < 0)
					{
						num2 = (short)(-num2);
					}
					ampSum = ampSum + (float)num2 - buffer[prevValuesPtr];
					buffer[prevValuesPtr] = num2;
					if (ampPeak < (float)num2)
					{
						ampPeak = num2;
					}
					if (prevValuesPtr == 0)
					{
						base.CurrentPeakAmp = ampPeak;
						ampPeak = 0f;
						accumAvgPeakAmpSum += base.CurrentPeakAmp;
						accumAvgPeakAmpCount++;
					}
					prevValuesPtr = (prevValuesPtr + 1) % bufferSize;
				}
				return buf;
			}
		}

