		public abstract class VoiceDetector<T> : LocalVoiceFramed<T>.IProcessor, IVoiceDetector, IDisposable
		{
			protected int activityDelay;

			protected int autoSilenceCounter;

			protected int valuesCountPerSec;

			protected int activityDelayValuesCount;

			public bool On { get; set; }

			public float Threshold { get; set; }

			public bool Detected { get; set; }

			public int ActivityDelayMs
			{
				get
				{
					return activityDelay;
				}
				set
				{
					activityDelay = value;
					activityDelayValuesCount = value * valuesCountPerSec / 1000;
				}
			}

			public float MaxAudioSample { get; set; }

			internal VoiceDetector(int samplingRate, int numChannels)
			{
				valuesCountPerSec = samplingRate * numChannels;
				Threshold = 0.01f;
				ActivityDelayMs = 500;
			}

			public abstract T[] Process(T[] buf);

			public void Dispose()
			{
			}
		}

		public class VoiceDetectorFloat : VoiceDetector<float>
		{
			public VoiceDetectorFloat(int samplingRate, int numChannels)
				: base(samplingRate, numChannels)
			{
			}

			public override float[] Process(float[] buffer)
			{
				if (base.On)
				{
					base.MaxAudioSample = 0f;
					foreach (float num in buffer)
					{
						if (num > base.Threshold)
						{
							base.MaxAudioSample = Math.Max(num, base.MaxAudioSample);
							base.Detected = true;
							autoSilenceCounter = 0;
						}
						else
						{
							autoSilenceCounter++;
						}
					}
					if (autoSilenceCounter > activityDelayValuesCount)
					{
						base.Detected = false;
					}
					return (!base.Detected) ? null : buffer;
				}
				return buffer;
			}
		}

		public class VoiceDetectorShort : VoiceDetector<short>
		{
			internal VoiceDetectorShort(int samplingRate, int numChannels)
				: base(samplingRate, numChannels)
			{
			}

			public override short[] Process(short[] buffer)
			{
				if (base.On)
				{
					foreach (short num in buffer)
					{
						base.MaxAudioSample = 0f;
						if ((float)num > base.Threshold)
						{
							base.MaxAudioSample = Math.Max(num, base.MaxAudioSample);
							base.Detected = true;
							autoSilenceCounter = 0;
						}
						else
						{
							autoSilenceCounter++;
						}
					}
					if (autoSilenceCounter > activityDelayValuesCount)
					{
						base.Detected = false;
					}
					return (!base.Detected) ? null : buffer;
				}
				return buffer;
			}
		}

		public static void Resample<T>(T[] src, T[] dst, int dstCount, int channels)
		{
			for (int i = 0; i < dstCount; i += channels)
			{
				int num = i * src.Length / dstCount;
				for (int j = 0; j < channels; j++)
				{
					dst[i + j] = src[num + j];
				}
			}
		}

		internal static string tostr<T>(T[] x, int lim = 10)
		{
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < ((x.Length >= lim) ? lim : x.Length); i++)
			{
				stringBuilder.Append("-");
				stringBuilder.Append(x[i]);
			}
			return stringBuilder.ToString();
		}
	}
	public abstract class ObjectPool<TType, TInfo> : IDisposable
	{
		protected int capacity;

		protected TInfo info;

		private TType[] freeObj = new TType[0];

		protected int pos;

		protected string name;

		private bool inited;

		internal string LogPrefix => "[ObjectPool] [" + name + "]";

		public ObjectPool(int capacity, string name)
		{
			this.capacity = capacity;
			this.name = name;
		}

		public ObjectPool(int capacity, string name, TInfo info)
		{
			this.capacity = capacity;
			this.name = name;
			Init(info);
		}

		protected abstract TType createObject(TInfo info);

		protected abstract void destroyObject(TType obj);

		protected abstract bool infosMatch(TInfo i0, TInfo i1);

		public void Init(TInfo info)
		{
			lock (this)
			{
				while (pos > 0)
				{
					destroyObject(freeObj[--pos]);
				}
				this.info = info;
				freeObj = new TType[capacity];
				inited = true;
			}
		}

		public TType AcquireOrCreate()
		{
			lock (this)
			{
				if (pos > 0)
				{
					return freeObj[--pos];
				}
				if (!inited)
				{
					throw new Exception(LogPrefix + " not initialized");
				}
			}
			return createObject(info);
		}

		public TType AcquireOrCreate(TInfo info)
		{
			if (!infosMatch(this.info, info))
			{
				Init(info);
			}
			return AcquireOrCreate();
		}

		public virtual bool Release(TType obj, TInfo objInfo)
		{
			if (infosMatch(info, objInfo))
			{
				lock (this)
				{
					if (pos < freeObj.Length)
					{
						freeObj[pos++] = obj;
						return true;
					}
				}
			}
			destroyObject(obj);
			return false;
		}

		public virtual bool Release(TType obj)
		{
			lock (this)
			{
				if (pos < freeObj.Length)
				{
					freeObj[pos++] = obj;
					return true;
				}
			}
			destroyObject(obj);
			return false;
		}

		public void Dispose()
		{
			lock (this)
			{
				while (pos > 0)
				{
					destroyObject(freeObj[--pos]);
				}
				freeObj = new TType[0];
			}
		}
	}
	public class PrimitiveArrayPool<T> : ObjectPool<T[], int>
	{
		public PrimitiveArrayPool(int capacity, string name)
			: base(capacity, name)
		{
		}

		public PrimitiveArrayPool(int capacity, string name, int info)
			: base(capacity, name, info)
		{
		}

		protected override T[] createObject(int info)
		{
			return new T[info];
		}

		protected override void destroyObject(T[] obj)
		{
		}

		protected override bool infosMatch(int i0, int i1)
		{
			return i0 == i1;
		}
	}
	public class ImageBufferNativePool<T> : ObjectPool<T, ImageBufferInfo> where T : ImageBufferNative
	{
		public delegate T Factory(ImageBufferNativePool<T> pool, ImageBufferInfo info);

		private Factory factory;

		public ImageBufferNativePool(int capacity, Factory factory, string name)
			: base(capacity, name)
		{
			this.factory = factory;
		}

		public ImageBufferNativePool(int capacity, Factory factory, string name, ImageBufferInfo info)
			: base(capacity, name, info)
		{
			this.factory = factory;
		}

		protected override T createObject(ImageBufferInfo info)
		{
			return factory(this, info);
		}

		protected override void destroyObject(T obj)
		{
			obj.Dispose();
		}

		protected override bool infosMatch(ImageBufferInfo i0, ImageBufferInfo i1)
		{
			if (i0 == null)
			{
				return i1 == null;
			}
			if (i1 == null)
			{
				return i0 == null;
			}
			if (i0.Height != i1.Height)
			{
				return false;
			}
			int[] stride = i0.Stride;
			int[] stride2 = i1.Stride;
			if (stride.Length != stride2.Length)
			{
				return false;
			}
			switch (i0.Stride.Length)
			{
			case 1:
				return stride[0] == stride2[0];
			case 2:
				return stride[0] == stride2[0] && stride[1] == stride2[1];
			case 3:
				return stride[0] == stride2[0] && stride[1] == stride2[1] && stride[2] == stride2[2];
			default:
			{
				for (int j = 0; j < stride.Length; j++)
				{
					if (stride[j] != stride2[j])
					{
						return false;
					}
				}
				return true;
			}
			}
		}
	}
