		public class Util
		{
			internal static int bestEncoderSampleRate(int f)
			{
				int num = int.MaxValue;
				int result = 48000;
				foreach (object value in System.Enum.GetValues(typeof(SamplingRate)))
				{
					int num2 = Math.Abs((int)value - f);
					if (num2 < num)
					{
						num = num2;
						result = (int)value;
					}
				}
				return result;
			}
		}
	}
