			{
				throw new ObjectDisposedException("OpusDecoder");
			}
			int num = 0;
			num = ((data == null) ? opus_decode(st, null, 0, pcm, pcm.Length / channels, decode_fec) : opus_decode(st, data, data.Length, pcm, pcm.Length / channels, decode_fec));
			if (num == -4)
