	public interface IBufferReader<T> : IDisposable
	{
		bool Read(T[] buffer);
	}
	public interface IServiceable : IDisposable
	{
		void Service(LocalVoice localVoice);
	}
	public abstract class BufferReaderPushAdapterBase<T> : IServiceable, IDisposable
	{
		protected IBufferReader<T> reader;

		public BufferReaderPushAdapterBase(IBufferReader<T> reader)
		{
			this.reader = reader;
		}

		public abstract void Service(LocalVoice localVoice);

		public void Dispose()
		{
			reader.Dispose();
		}
	}
	public class BufferReaderPushAdapter<T> : BufferReaderPushAdapterBase<T>
	{
		protected T[] buffer;

		public BufferReaderPushAdapter(LocalVoice localVoice, IBufferReader<T> reader)
			: base(reader)
		{
			buffer = new T[((LocalVoiceFramed<T>)localVoice).FrameSize];
		}

		public override void Service(LocalVoice localVoice)
		{
			while (reader.Read(buffer))
			{
				((LocalVoiceFramed<T>)localVoice).PushData(buffer);
			}
		}
	}
	public class BufferReaderPushAdapterAsyncPool<T> : BufferReaderPushAdapterBase<T>
	{
		public BufferReaderPushAdapterAsyncPool(LocalVoice localVoice, IBufferReader<T> reader)
			: base(reader)
		{
		}

		public override void Service(LocalVoice localVoice)
		{
			LocalVoiceFramed<T> localVoiceFramed = (LocalVoiceFramed<T>)localVoice;
			T[] array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			while (reader.Read(array))
			{
				localVoiceFramed.PushDataAsync(array);
				array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			}
			localVoiceFramed.PushDataBufferPool.Release(array, array.Length);
		}
	}
	public class BufferReaderPushAdapterAsyncPoolCopy<T> : BufferReaderPushAdapterBase<T>
	{
		protected T[] buffer;

		public BufferReaderPushAdapterAsyncPoolCopy(LocalVoice localVoice, IBufferReader<T> reader)
			: base(reader)
		{
			buffer = new T[((LocalVoiceFramed<T>)localVoice).FrameSize];
		}

		public override void Service(LocalVoice localVoice)
		{
			while (reader.Read(buffer))
			{
				LocalVoiceFramed<T> localVoiceFramed = (LocalVoiceFramed<T>)localVoice;
				T[] array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
				Array.Copy(buffer, array, buffer.Length);
				localVoiceFramed.PushDataAsync(array);
			}
		}
	}
