		private LocalVoice createLocalVoice(VoiceInfo voiceInfo, int channelId, IEncoder encoder, Func<byte, int, LocalVoice> voiceFactory)
		{
			if (channelId == -1)
			{
				channelId = frontend.AssignChannel(voiceInfo);
			}
			byte newVoiceId = getNewVoiceId();
			if (newVoiceId != 0)
			{
				LocalVoice localVoice = voiceFactory(newVoiceId, channelId);
				if (localVoice != null)
				{
					addVoice(newVoiceId, channelId, localVoice);
					frontend.LogInfo(localVoice.LogPrefix + " added enc: " + localVoice.info.ToString());
					return localVoice;
				}
			}
			return null;
		}

		public LocalVoice CreateLocalVoice(VoiceInfo voiceInfo, int channelId = -1, IEncoder encoder = null)
		{
			return createLocalVoice(voiceInfo, channelId, encoder, (byte vId, int chId) => new LocalVoice(this, encoder, vId, voiceInfo, chId));
		}

		public LocalVoiceFramed<T> CreateLocalVoiceFramed<T>(VoiceInfo voiceInfo, int frameSize, int channelId = -1, IEncoderDataFlow<T> encoder = null)
		{
			return (LocalVoiceFramed<T>)createLocalVoice(voiceInfo, channelId, encoder, (byte vId, int chId) => new LocalVoiceFramed<T>(this, encoder, vId, voiceInfo, chId, frameSize));
		}

		public LocalVoiceAudio<T> CreateLocalVoiceAudio<T>(VoiceInfo voiceInfo, int channelId = -1, IEncoderDataFlow<T> encoder = null)
		{
			return (LocalVoiceAudio<T>)createLocalVoice(voiceInfo, channelId, encoder, (byte vId, int chId) => LocalVoiceAudio.Create<T>(this, vId, encoder, voiceInfo, chId));
		}

		private byte getNewVoiceId()
		{
			byte result = 0;
			if (voiceIdCnt == byte.MaxValue)
			{
				bool[] array = new bool[256];
				foreach (KeyValuePair<byte, LocalVoice> localVoice in localVoices)
				{
					array[localVoice.Value.id] = true;
				}
				for (byte b = 1; b != 0; b++)
				{
					if (!array[b])
					{
						result = b;
						break;
					}
				}
			}
			else
			{
				voiceIdCnt++;
				result = voiceIdCnt;
			}
			return result;
		}

		private void addVoice(byte newId, int channelId, LocalVoice v)
		{
			localVoices[newId] = v;
			if (!localVoicesPerChannel.TryGetValue(channelId, out var value))
			{
				value = new List<LocalVoice>();
				localVoicesPerChannel[channelId] = value;
			}
			value.Add(v);
			if (frontend.IsChannelJoined(channelId))
			{
				frontend.SendVoicesInfo(new List<LocalVoice> { v }, channelId, 0);
			}
			v.Group = GlobalGroup;
		}

		internal void RemoveLocalVoice(LocalVoice voice)
		{
			localVoices.Remove(voice.id);
			localVoicesPerChannel[voice.channelId].Remove(voice);
			if (frontend.IsChannelJoined(voice.channelId))
			{
				frontend.SendVoiceRemove(voice, voice.channelId, 0);
			}
			voice.Dispose();
			frontend.LogInfo(voice.LogPrefix + " removed");
		}

		internal void sendVoicesInfo(int targetPlayerId)
		{
			foreach (int key in localVoicesPerChannel.Keys)
			{
				sendChannelVoicesInfo(key, targetPlayerId);
			}
		}

		internal void sendChannelVoicesInfo(int channelId, int targetPlayerId)
		{
			if (frontend.IsChannelJoined(channelId) && localVoicesPerChannel.TryGetValue(channelId, out var value))
			{
				frontend.SendVoicesInfo(value, channelId, targetPlayerId);
			}
		}

		internal void onVoiceEvent(object content0, int channelId, int playerId, int localPlayerId)
		{
			object[] array = (object[])content0;
			if ((byte)array[0] == 0)
			{
				switch ((byte)array[1])
				{
				case 1:
					onVoiceInfo(channelId, playerId, array[2]);
					break;
				case 2:
					onVoiceRemove(channelId, playerId, array[2]);
					break;
				default:
					frontend.LogError("[PV] Unknown sevent subcode " + array[1]);
					break;
				}
				return;
			}
			byte b = (byte)array[0];
			byte b2 = (byte)array[1];
			byte[] receivedBytes = (byte[])array[2];
			if (playerId == localPlayerId && localVoices.TryGetValue(b, out var value) && value.eventTimestamps.TryGetValue(b2, out var value2))
			{
				int num = Environment.TickCount - value2;
				int num2 = num - prevRtt;
				prevRtt = num;
				if (num2 < 0)
				{
					num2 = -num2;
				}
				RoundTripTimeVariance = (num2 + RoundTripTimeVariance * 19) / 20;
				RoundTripTime = (num + RoundTripTime * 19) / 20;
			}
			onFrame(channelId, playerId, b, b2, receivedBytes);
		}

		internal object[] buildVoicesInfo(IEnumerable<LocalVoice> voicesToSend, bool logInfo)
		{
			object[] array = new object[voicesToSend.Count()];
			object[] result = new object[3]
			{
				(byte)0,
				EventSubcode.VoiceInfo,
				array
			};
			int num = 0;
			foreach (LocalVoice item in voicesToSend)
			{
				array[num] = new Dictionary<byte, object>
				{
					{ 1, item.id },
					{
						12,
						item.info.Codec
					},
					{
						2,
						item.info.SamplingRate
					},
					{
						3,
						item.info.Channels
					},
					{
						4,
						item.info.FrameDurationUs
					},
					{
						5,
						item.info.Bitrate
					},
					{
						10,
						item.info.UserData
					},
					{ 11, item.evNumber }
				};
				num++;
				if (logInfo)
				{
					frontend.LogInfo(item.LogPrefix + " Sending info: " + item.info.ToString() + " ev=" + item.evNumber);
				}
			}
			return result;
		}

		internal object[] buildVoiceRemoveMessage(LocalVoice v)
		{
			byte[] array = new byte[1] { v.id };
			object[] result = new object[3]
			{
				(byte)0,
				EventSubcode.VoiceRemove,
				array
			};
			frontend.LogInfo(v.LogPrefix + " remove sent");
			return result;
		}

		internal void clearRemoteVoices()
		{
			foreach (KeyValuePair<int, Dictionary<int, Dictionary<byte, RemoteVoice>>> remoteVoice in remoteVoices)
			{
				foreach (KeyValuePair<int, Dictionary<byte, RemoteVoice>> item in remoteVoice.Value)
				{
					foreach (KeyValuePair<byte, RemoteVoice> item2 in item.Value)
					{
						item2.Value.removeAndDispose();
					}
				}
			}
			remoteVoices.Clear();
			frontend.LogInfo("[PV] Remote voices cleared");
		}

		internal void clearRemoteVoicesInChannel(int channelId)
		{
			Dictionary<int, Dictionary<byte, RemoteVoice>> value = null;
			if (remoteVoices.TryGetValue(channelId, out value))
			{
				foreach (KeyValuePair<int, Dictionary<byte, RemoteVoice>> item in value)
				{
					foreach (KeyValuePair<byte, RemoteVoice> item2 in item.Value)
					{
						item2.Value.removeAndDispose();
					}
				}
				remoteVoices.Remove(channelId);
			}
			frontend.LogInfo("[PV] Remote voices for channel " + channelStr(channelId) + " cleared");
		}

		private void onVoiceInfo(int channelId, int playerId, object payload)
		{
			Dictionary<int, Dictionary<byte, RemoteVoice>> value = null;
			if (!remoteVoices.TryGetValue(channelId, out value))
			{
				value = new Dictionary<int, Dictionary<byte, RemoteVoice>>();
				remoteVoices[channelId] = value;
			}
			Dictionary<byte, RemoteVoice> value2 = null;
			if (!value.TryGetValue(playerId, out value2))
			{
				value2 = (value[playerId] = new Dictionary<byte, RemoteVoice>());
			}
			object[] array = (object[])payload;
			foreach (object obj in array)
			{
				Dictionary<byte, object> dictionary2 = (Dictionary<byte, object>)obj;
				byte b = (byte)dictionary2[1];
				if (!value2.ContainsKey(b))
				{
					byte b2 = (byte)dictionary2[11];
					VoiceInfo voiceInfo = VoiceInfo.CreateFromEventPayload(dictionary2);
					frontend.LogInfo("[PV] ch#" + channelStr(channelId) + " p#" + playerStr(playerId) + " v#" + b + " Info received: " + voiceInfo.ToString() + " ev=" + b2);
					RemoteVoiceOptions options = new RemoteVoiceOptions
					{
						Decoder = CreateDecoder(channelId, playerId, b, voiceInfo)
					};
					if (OnRemoteVoiceInfoAction != null)
					{
						OnRemoteVoiceInfoAction(channelId, playerId, b, voiceInfo, ref options);
					}
					value2[b] = new RemoteVoice(this, options, channelId, playerId, b, voiceInfo, b2);
				}
				else if (!SuppressInfoDuplicateWarning)
				{
					frontend.LogWarning("[PV] Info duplicate for voice #" + b + " of player " + playerStr(playerId) + " at channel " + channelStr(channelId));
				}
			}
		}

		private void onVoiceRemove(int channelId, int playerId, object payload)
		{
			byte[] array = (byte[])payload;
			Dictionary<int, Dictionary<byte, RemoteVoice>> value = null;
			if (remoteVoices.TryGetValue(channelId, out value))
			{
				Dictionary<byte, RemoteVoice> value2 = null;
				if (value.TryGetValue(playerId, out value2))
				{
					byte[] array2 = array;
					foreach (byte b in array2)
					{
						if (value2.TryGetValue(b, out var value3))
						{
							value2.Remove(b);
							frontend.LogInfo("[PV] Remote voice #" + b + " of player " + playerStr(playerId) + " at channel " + channelStr(channelId) + " removed");
							value3.removeAndDispose();
						}
						else
						{
							frontend.LogWarning("[PV] Remote voice #" + b + " of player " + playerStr(playerId) + " at channel " + channelStr(channelId) + " not found when trying to remove");
						}
					}
				}
				else
				{
					frontend.LogWarning("[PV] Remote voice list of player " + playerStr(playerId) + " at channel " + channelStr(channelId) + " not found when trying to remove voice(s)");
				}
			}
			else
			{
				frontend.LogWarning("[PV] Remote voice list of channel " + channelStr(channelId) + " not found when trying to remove voice(s)");
			}
		}

		private void onFrame(int channelId, int playerId, byte voiceId, byte evNumber, byte[] receivedBytes)
		{
			if (DebugLostPercent > 0 && rnd.Next(100) < DebugLostPercent)
			{
				frontend.LogWarning("[PV] Debug Lost Sim: 1 packet dropped");
				return;
			}
			FramesReceived++;
			Dictionary<int, Dictionary<byte, RemoteVoice>> value = null;
			if (remoteVoices.TryGetValue(channelId, out value))
			{
				Dictionary<byte, RemoteVoice> value2 = null;
				if (value.TryGetValue(playerId, out value2))
				{
					RemoteVoice value3 = null;
					if (value2.TryGetValue(voiceId, out value3))
					{
						value3.receiveBytes(receivedBytes, evNumber);
						return;
					}
					frontend.LogWarning("[PV] Frame event for not inited voice #" + voiceId + " of player " + playerStr(playerId) + " at channel " + channelStr(channelId));
				}
				else
				{
					frontend.LogWarning("[PV] Frame event for voice #" + voiceId + " of not inited player " + playerStr(playerId) + " at channel " + channelStr(channelId));
				}
			}
			else
			{
				frontend.LogWarning("[PV] Frame event for voice #" + voiceId + " of not inited channel " + channelStr(channelId));
			}
		}

		internal bool removePlayerVoices(int playerId)
		{
			foreach (int key in localVoicesPerChannel.Keys)
			{
				removePlayerVoices(key, playerId);
			}
			return true;
		}

		internal bool removePlayerVoices(int channelId, int playerId)
		{
			Dictionary<int, Dictionary<byte, RemoteVoice>> value = null;
			if (remoteVoices.TryGetValue(channelId, out value))
			{
				Dictionary<byte, RemoteVoice> value2 = null;
				if (value.TryGetValue(playerId, out value2))
				{
					value.Remove(playerId);
					foreach (KeyValuePair<byte, RemoteVoice> item in value2)
					{
						item.Value.removeAndDispose();
					}
					return true;
				}
				return false;
			}
			return false;
		}

		internal IEncoder CreateEncoder(VoiceInfo info, LocalVoice localVoice)
		{
			Codec codec = info.Codec;
			if (codec == Codec.AudioOpus)
			{
				return OpusCodec.EncoderFactory.Create(info, localVoice);
			}
			throw new UnsupportedCodecException(info.Codec, localVoice);
		}

		internal IDecoder CreateDecoder(int channelId, int playerId, byte voiceId, VoiceInfo info)
		{
			Codec codec = info.Codec;
			if (codec == Codec.AudioOpus)
			{
				return new OpusCodec.Decoder();
			}
			return null;
		}

		internal string channelStr(int channelId)
		{
			string text = frontend.ChannelIdStr(channelId);
			if (text != null)
			{
				return channelId + "(" + text + ")";
			}
			return channelId.ToString();
		}

		internal string playerStr(int playerId)
		{
			string text = frontend.PlayerIdStr(playerId);
			if (text != null)
			{
				return playerId + "(" + text + ")";
			}
			return playerId.ToString();
		}

		public void Dispose()
		{
			foreach (KeyValuePair<byte, LocalVoice> localVoice in localVoices)
			{
				localVoice.Value.Dispose();
			}
			foreach (KeyValuePair<int, Dictionary<int, Dictionary<byte, RemoteVoice>>> remoteVoice in remoteVoices)
			{
				foreach (KeyValuePair<int, Dictionary<byte, RemoteVoice>> item in remoteVoice.Value)
				{
					foreach (KeyValuePair<byte, RemoteVoice> item2 in item.Value)
					{
						item2.Value.Dispose();
					}
				}
			}
		}
	}
	public static class VoiceUtil
	{
		internal static byte byteDiff(byte latest, byte last)
		{
			return (byte)(latest - (last + 1));
		}
	}
	internal class VoiceEventCode
	{
		public const byte Code0 = 201;

		public static byte GetCode(byte channelID)
		{
			return (byte)(201 + channelID);
		}

		public static bool TryGetChannelID(byte evCode, int maxChannels, out byte channelID)
		{
			if (evCode >= 201 && evCode < 201 + maxChannels)
			{
				channelID = (byte)(evCode - 201);
				return true;
			}
			channelID = 0;
			return false;
		}
	}
	public class LoadBalancingFrontend : LoadBalancingClient, IVoiceFrontend, IDisposable
	{
		protected VoiceClient voiceClient;

		private object sendLock = new object();

		public VoiceClient VoiceClient => voiceClient;

		public new Action<EventData> OnEventAction { get; set; }

		public new Action<ExitGames.Client.Photon.LoadBalancing.ClientState> OnStateChangeAction { get; set; }

		public byte GlobalAudioGroup
		{
			get
			{
				return voiceClient.GlobalGroup;
			}
			set
			{
				voiceClient.GlobalGroup = value;
				if (base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.Joined)
				{
					if (voiceClient.GlobalGroup != 0)
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], new byte[1] { voiceClient.GlobalGroup });
					}
					else
					{
						loadBalancingPeer.OpChangeGroups(new byte[0], null);
					}
				}
			}
		}

		public bool SupportsArraySegmentSerialization => true;

		public LoadBalancingFrontend(ConnectionProtocol connectionProtocol = ConnectionProtocol.Udp)
			: base(connectionProtocol)
		{
			base.OnEventAction += onEventActionVoiceClient;
			base.OnStateChangeAction += onStateChangeVoiceClient;
			voiceClient = new VoiceClient(this);
			int num = System.Enum.GetValues(typeof(Codec)).Length + 1;
			if (loadBalancingPeer.ChannelCount < num)
			{
				loadBalancingPeer.ChannelCount = (byte)num;
			}
		}

		public void LogError(string fmt, params object[] args)
		{
			DebugReturn(DebugLevel.ERROR, string.Format(fmt, args));
		}

		public void LogWarning(string fmt, params object[] args)
		{
			DebugReturn(DebugLevel.WARNING, string.Format(fmt, args));
		}

		public void LogInfo(string fmt, params object[] args)
		{
			DebugReturn(DebugLevel.INFO, string.Format(fmt, args));
		}

		public void LogDebug(string fmt, params object[] args)
		{
			DebugReturn(DebugLevel.ALL, string.Format(fmt, args));
		}

		public int AssignChannel(VoiceInfo v)
		{
			return 1 + Array.IndexOf(System.Enum.GetValues(typeof(Codec)), v.Codec);
		}

		public bool IsChannelJoined(int channelId)
		{
			return base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.Joined;
		}

		public void SetDebugEchoMode(LocalVoice v)
		{
			if (base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.Joined)
			{
				if (v.DebugEchoMode)
				{
					SendVoicesInfo(new List<LocalVoice> { v }, v.channelId, base.LocalPlayer.ID);
				}
				else
				{
					SendVoiceRemove(v, v.channelId, base.LocalPlayer.ID);
				}
			}
		}

		public new void Service()
		{
			base.Service();
			voiceClient.Service();
		}

		public virtual bool ChangeAudioGroups(byte[] groupsToRemove, byte[] groupsToAdd)
		{
			return loadBalancingPeer.OpChangeGroups(groupsToRemove, groupsToAdd);
		}

		public void SendVoicesInfo(IEnumerable<LocalVoice> voices, int channelId, int targetPlayerId)
		{
			object customEventContent = voiceClient.buildVoicesInfo(voices, logInfo: true);
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			raiseEventOptions.SequenceChannel = (byte)channelId;
			if (targetPlayerId != 0)
			{
				raiseEventOptions.TargetActors = new int[1] { targetPlayerId };
			}
			lock (sendLock)
			{
				OpRaiseEvent(VoiceEventCode.GetCode(raiseEventOptions.SequenceChannel), customEventContent, sendReliable: true, raiseEventOptions);
			}
			if (targetPlayerId == 0)
			{
				SendDebugEchoVoicesInfo(channelId);
			}
		}

		public void SendDebugEchoVoicesInfo(int channelId)
		{
			IEnumerable<LocalVoice> enumerable = voiceClient.LocalVoices.Where((LocalVoice x) => x.DebugEchoMode);
			if (enumerable.Count() > 0)
			{
				SendVoicesInfo(enumerable, channelId, base.LocalPlayer.ID);
			}
		}

		public void SendVoiceRemove(LocalVoice voice, int channelId, int targetPlayerId)
		{
			object customEventContent = voiceClient.buildVoiceRemoveMessage(voice);
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			raiseEventOptions.SequenceChannel = (byte)channelId;
			if (targetPlayerId != 0)
			{
				raiseEventOptions.TargetActors = new int[1] { targetPlayerId };
			}
			lock (sendLock)
			{
				OpRaiseEvent(VoiceEventCode.GetCode(raiseEventOptions.SequenceChannel), customEventContent, sendReliable: true, raiseEventOptions);
			}
		}

		public void SendFrame(object content, int channelId, LocalVoice localVoice)
		{
			ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions raiseEventOptions = new ExitGames.Client.Photon.LoadBalancing.RaiseEventOptions();
			raiseEventOptions.SequenceChannel = (byte)channelId;
			if (localVoice.DebugEchoMode)
			{
				raiseEventOptions.Receivers = ExitGames.Client.Photon.LoadBalancing.ReceiverGroup.All;
			}
			raiseEventOptions.InterestGroup = localVoice.Group;
			lock (sendLock)
			{
				OpRaiseEvent(VoiceEventCode.GetCode(raiseEventOptions.SequenceChannel), content, localVoice.Reliable, raiseEventOptions);
			}
			loadBalancingPeer.SendOutgoingCommands();
		}

		public string ChannelIdStr(int channelId)
		{
			return null;
		}

		public string PlayerIdStr(int playerId)
		{
			return null;
		}

		private void onEventActionVoiceClient(EventData ev)
		{
			if (VoiceEventCode.TryGetChannelID(ev.Code, loadBalancingPeer.ChannelCount, out var channelID))
			{
				voiceClient.onVoiceEvent(ev[245], channelID, (int)ev[254], base.LocalPlayer.ID);
			}
			else
			{
				switch (ev.Code)
				{
				case byte.MaxValue:
				{
					int num = (int)ev[254];
					if (num != base.LocalPlayer.ID)
					{
						voiceClient.sendVoicesInfo(num);
					}
					break;
				}
				case 254:
				{
					int num = (int)ev[254];
					if (num == base.LocalPlayer.ID)
					{
						voiceClient.clearRemoteVoices();
					}
					else
					{
						onPlayerLeave(num);
					}
					break;
				}
				}
			}
			if (OnEventAction != null)
			{
				OnEventAction(ev);
			}
		}

		private void onStateChangeVoiceClient(ExitGames.Client.Photon.LoadBalancing.ClientState state)
		{
			switch (state)
			{
			case ExitGames.Client.Photon.LoadBalancing.ClientState.Joined:
				voiceClient.clearRemoteVoices();
				voiceClient.sendVoicesInfo(0);
				if (voiceClient.GlobalGroup != 0)
				{
					loadBalancingPeer.OpChangeGroups(new byte[0], new byte[1] { voiceClient.GlobalGroup });
				}
				break;
			case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected:
				voiceClient.clearRemoteVoices();
				break;
			}
			if (OnStateChangeAction != null)
			{
				OnStateChangeAction(state);
			}
		}

		private void onPlayerLeave(int playerId)
		{
			if (voiceClient.removePlayerVoices(playerId))
			{
				DebugReturn(DebugLevel.INFO, "[PV] Player " + playerId + " voices removed on leave");
			}
			else
			{
				DebugReturn(DebugLevel.WARNING, "[PV] Voices of player " + playerId + " not found when trying to remove on player leave");
			}
		}

		public void Dispose()
		{
			voiceClient.Dispose();
		}
	}
}
public class AudioClipWrapper : IBufferReader<float>, IDisposable
{
	private AudioClip audioClip;

	private int readPos;

	private float startTime;

	private bool playing = true;

	public bool Loop { get; set; }

	public AudioClipWrapper(AudioClip audioClip)
	{
		this.audioClip = audioClip;
		startTime = UnityEngine.Time.time;
	}

	public bool Read(float[] buffer)
	{
		if (!playing)
		{
			return false;
		}
		int num = (int)((UnityEngine.Time.time - startTime) * (float)audioClip.frequency);
		int num2 = buffer.Length / audioClip.channels;
		if (num > readPos + num2)
		{
			audioClip.GetData(buffer, readPos);
			readPos += num2;
			if (readPos >= audioClip.samples)
			{
				if (Loop)
				{
					readPos = 0;
					startTime = UnityEngine.Time.time;
				}
				else
				{
					playing = false;
				}
			}
			return true;
		}
		return false;
	}

	public void Dispose()
	{
	}
}
public class AudioStreamPlayer
{
	private const int maxPlayLagMs = 100;

	private int maxPlayLagSamples;

	private int playDelaySamples;

	private int frameSize;

	private int frameSamples;

	private int streamSamplePos;

	private int streamSamplePosAvg;

	private AudioSource source;

	private string logPrefix;

	private bool debugInfo;

	private int sourceTimeSamplesPrev;

	private int playLoopCount;

	private Queue<float[]> frameQueue = new Queue<float[]>();

	public const int FRAME_POOL_CAPACITY = 50;

	private PrimitiveArrayPool<float> framePool = new PrimitiveArrayPool<float>(50, "AudioStreamPlayer");

	public int CurrentBufferLag { get; private set; }

	public AudioSource AudioSource => source;

	private int playSamplePos
	{
		get
		{
			return (source.clip != null) ? (playLoopCount * source.clip.samples + source.timeSamples) : 0;
		}
		set
		{
			if (source.clip != null)
			{
				int num = value % source.clip.samples;
				if (num < 0)
				{
					num += source.clip.samples;
				}
				source.timeSamples = num;
				playLoopCount = value / source.clip.samples;
				sourceTimeSamplesPrev = source.timeSamples;
			}
		}
	}

	public bool IsPlaying => source.isPlaying;

	public bool IsStarted => source.clip != null;

	public AudioStreamPlayer(AudioSource audioSource, string logPrefix, bool debugInfo)
	{
		source = audioSource;
		this.logPrefix = logPrefix;
		this.debugInfo = debugInfo;
	}

	public void Start(int frequency, int channels, int frameSamples, int playDelayMs)
	{
		int lengthSamples = (100 + playDelayMs) * frequency / 1000 + frameSamples + frequency;
		this.frameSamples = frameSamples;
		frameSize = frameSamples * channels;
		maxPlayLagSamples = 100 * frequency / 1000 + this.frameSamples;
		playDelaySamples = playDelayMs * frequency / 1000 + this.frameSamples;
		CurrentBufferLag = playDelaySamples;
		streamSamplePosAvg = playDelaySamples;
		source.loop = true;
		source.clip = AudioClip.Create("AudioStreamPlayer", lengthSamples, channels, frequency, stream: false);
		streamSamplePos = 0;
		playSamplePos = 0;
		source.Play();
		source.Pause();
		framePool.Init(frameSize);
	}

	public void Update()
	{
		if (!(source.clip != null))
		{
			return;
		}
		lock (frameQueue)
		{
			while (frameQueue.Count > 0)
			{
				float[] array = frameQueue.Dequeue();
				source.clip.SetData(array, streamSamplePos % source.clip.samples);
				framePool.Release(array);
				streamSamplePos += array.Length / source.clip.channels;
			}
		}
		if (source.isPlaying)
		{
			if (source.timeSamples < sourceTimeSamplesPrev)
			{
				playLoopCount++;
			}
			sourceTimeSamplesPrev = source.timeSamples;
		}
		int num = playSamplePos;
		CurrentBufferLag = (CurrentBufferLag * 39 + (streamSamplePos - num)) / 40;
		streamSamplePosAvg = num + CurrentBufferLag;
		if (streamSamplePosAvg > streamSamplePos)
		{
			streamSamplePosAvg = streamSamplePos;
		}
		if (num < streamSamplePos - playDelaySamples && !source.isPlaying)
		{
			source.UnPause();
		}
		if (num > streamSamplePos - frameSamples && source.isPlaying)
		{
			if (debugInfo)
			{
				UnityEngine.Debug.LogWarningFormat("{0} player overrun: {1}/{2}({3}) = {4}", logPrefix, num, streamSamplePos, streamSamplePosAvg, streamSamplePos - num);
			}
			source.Pause();
			num = (playSamplePos = streamSamplePos);
			CurrentBufferLag = playDelaySamples;
		}
		if (!source.isPlaying)
		{
			return;
		}
		int num3 = streamSamplePos - playDelaySamples - maxPlayLagSamples;
		if (num < num3)
		{
			if (debugInfo)
			{
				UnityEngine.Debug.LogWarningFormat("{0} player underrun: {1}/{2}({3}) = {4}", logPrefix, num, streamSamplePos, streamSamplePosAvg, streamSamplePos - num);
			}
			num = streamSamplePos - playDelaySamples;
			playSamplePos = num;
			CurrentBufferLag = playDelaySamples;
		}
	}

	public void OnAudioFrame(float[] frame)
	{
		if (frame.Length == 0)
		{
			return;
		}
		if (frame.Length != frameSize)
		{
			UnityEngine.Debug.LogErrorFormat("{0} Audio frames are not of  size: {1} != {2}", logPrefix, frame.Length, frameSize);
			return;
		}
		float[] array = framePool.AcquireOrCreate();
		Buffer.BlockCopy(frame, 0, array, 0, frameSize * 4);
		lock (frameQueue)
		{
			frameQueue.Enqueue(array);
		}
	}

	public void Stop()
	{
		source.Stop();
		source.clip = null;
	}

	public void Pause()
	{
		if ((bool)source)
		{
			source.Pause();
		}
	}
}
public class MicWrapper : IBufferReader<float>, IDisposable
{
	private AudioClip mic;

	private string device;

	private static readonly float PsvrVolume = 0.5f;

	private int micPrevPos;

	private int micLoopCnt;

	private int readAbsPos;

	public int SourceSamplingRate => mic.frequency;

	public int Channels => mic.channels;

	public MicWrapper(string device, int suggestedFrequency)
	{
		if (Microphone.devices.Length >= 1)
		{
			this.device = device;
			Microphone.GetDeviceCaps(device, out var minFreq, out var maxFreq);
			int suggestedFrequency2 = suggestedFrequency;
			if (suggestedFrequency < minFreq || (maxFreq != 0 && suggestedFrequency > maxFreq))
			{
				suggestedFrequency2 = maxFreq;
			}
			mic = SharedMicrophone.GetMicrophone(device, suggestedFrequency2);
		}
	}

	public void Dispose()
	{
	}

	public bool Read(float[] buffer)
	{
		if (mic.channels == 0)
		{
			return false;
		}
		int position = Microphone.GetPosition(device);
		if (position < micPrevPos)
		{
			micLoopCnt++;
		}
		micPrevPos = position;
		int num = micLoopCnt * mic.samples + position;
		int num2 = buffer.Length / mic.channels;
		int num3 = readAbsPos + num2;
		if (num3 < num)
		{
			mic.GetData(buffer, readAbsPos % mic.samples);
			readAbsPos = num3;
			return true;
		}
		return false;
	}
}
[DisallowMultipleComponent]
public class PhotonVoiceHandler : UnityEngine.MonoBehaviour
{
	public int updateInterval;

	private int nextSendTickCount;

	private static bool sendThreadShouldRun;

	private static Stopwatch timerToStopConnectionInBackground;

	private static void StartFallbackSendAckThread()
	{
		if (!sendThreadShouldRun)
		{
			sendThreadShouldRun = true;
			SupportClass.StartBackgroundCalls(FallbackSendAckThread, 100, string.Empty);
		}
	}

	private static void StopFallbackSendAckThread()
	{
		sendThreadShouldRun = false;
	}

	private static bool FallbackSendAckThread()
	{
		if (sendThreadShouldRun && PhotonVoiceNetwork.Client != null && PhotonVoiceNetwork.Client.loadBalancingPeer != null)
		{
			ExitGames.Client.Photon.LoadBalancing.LoadBalancingPeer loadBalancingPeer = PhotonVoiceNetwork.Client.loadBalancingPeer;
			ExitGames.Client.Photon.LoadBalancing.ClientState state = PhotonVoiceNetwork.Client.State;
			if (timerToStopConnectionInBackground != null && PhotonVoiceNetwork.BackgroundTimeout > 0.1f && (float)timerToStopConnectionInBackground.ElapsedMilliseconds > PhotonVoiceNetwork.BackgroundTimeout * 1000f)
			{
				bool flag = true;
				switch (state)
				{
				case ExitGames.Client.Photon.LoadBalancing.ClientState.PeerCreated:
				case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnecting:
				case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected:
				case ExitGames.Client.Photon.LoadBalancing.ClientState.ConnectedToNameServer:
					flag = false;
					break;
				}
				if (flag)
				{
					PhotonVoiceNetwork.Disconnect();
				}
				timerToStopConnectionInBackground.Stop();
				timerToStopConnectionInBackground.Reset();
				return sendThreadShouldRun;
			}
			if (loadBalancingPeer.ConnectionTime - loadBalancingPeer.LastSendOutgoingTime > 200)
			{
				while (loadBalancingPeer.SendAcksOnly())
				{
				}
			}
		}
		return sendThreadShouldRun;
	}

	[RuntimeInitializeOnLoadMethod]
	private static void RuntimeInitializeOnLoad()
	{
		string text = "PhotonVoiceMono";
		GameObject gameObject = GameObject.Find(text);
		if (gameObject == null)
		{
			gameObject = new GameObject();
			gameObject.name = text;
		}
		if (gameObject.GetComponent<PhotonVoiceHandler>() == null)
		{
			gameObject.AddComponent<PhotonVoiceHandler>();
		}
		gameObject.hideFlags = HideFlags.HideInHierarchy;
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
	}

	private void Awake()
	{
		StartFallbackSendAckThread();
	}

	protected void Update()
	{
		ExitGames.Client.Photon.LoadBalancing.LoadBalancingPeer loadBalancingPeer = PhotonVoiceNetwork.Client.loadBalancingPeer;
		if (loadBalancingPeer == null)
		{
			UnityEngine.Debug.LogError("[PUNVoice]: LoadBalancingPeer broke!");
			return;
		}
		ExitGames.Client.Photon.LoadBalancing.ClientState state = PhotonVoiceNetwork.Client.State;
		bool flag = true;
		switch (state)
		{
		case ExitGames.Client.Photon.LoadBalancing.ClientState.PeerCreated:
		case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnecting:
		case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected:
		case ExitGames.Client.Photon.LoadBalancing.ClientState.ConnectedToNameServer:
			flag = false;
			break;
		}
		if (!flag)
		{
			return;
		}
		bool flag2 = true;
		while (flag2)
		{
			flag2 = loadBalancingPeer.DispatchIncomingCommands();
		}
		int num = (int)(UnityEngine.Time.realtimeSinceStartup * 1000f);
		if (num > nextSendTickCount)
		{
			bool flag3 = true;
			while (flag3)
			{
				flag3 = loadBalancingPeer.SendOutgoingCommands();
			}
			nextSendTickCount = num + updateInterval;
		}
	}

	protected void OnApplicationPause(bool pause)
	{
		if (PhotonVoiceNetwork.BackgroundTimeout > 0.1f)
		{
			if (timerToStopConnectionInBackground == null)
			{
				timerToStopConnectionInBackground = new Stopwatch();
			}
			timerToStopConnectionInBackground.Reset();
			if (pause)
			{
				timerToStopConnectionInBackground.Start();
			}
			else
			{
				timerToStopConnectionInBackground.Stop();
			}
		}
	}

	protected void OnDestroy()
	{
		StopFallbackSendAckThread();
	}

	protected void OnApplicationQuit()
	{
		StopFallbackSendAckThread();
		PhotonVoiceNetwork.Disconnect();
	}
}
[DisallowMultipleComponent]
public class PhotonVoiceNetwork : UnityEngine.MonoBehaviour
{
	private class BufferReaderPushAdapterAsyncPoolFloatToShort : BufferReaderPushAdapterBase<float>
	{
		private float[] buffer;

		public BufferReaderPushAdapterAsyncPoolFloatToShort(LocalVoice localVoice, IBufferReader<float> reader)
			: base(reader)
		{
			buffer = new float[((LocalVoiceFramed<short>)localVoice).FrameSize];
		}

		public override void Service(LocalVoice localVoice)
		{
			LocalVoiceFramed<short> localVoiceFramed = (LocalVoiceFramed<short>)localVoice;
			short[] array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			while (reader.Read(buffer))
			{
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = (short)(buffer[i] * 32767f);
				}
				localVoiceFramed.PushDataAsync(array);
				array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			}
			localVoiceFramed.PushDataBufferPool.Release(array, array.Length);
		}
	}

	private static PhotonVoiceNetwork _instance;

	private static GameObject _singleton;

	private static object instanceLock = new object();

	private static bool destroyed = false;

	public static float BackgroundTimeout = 60f;

	internal UnityVoiceFrontend client;

	private static string microphoneDevice = null;

	internal static PhotonVoiceNetwork instance => getInstance();

	public static UnityVoiceFrontend Client => (!(instance != null)) ? null : instance.client;

	public static VoiceClient VoiceClient => instance.client.VoiceClient;

	public static ExitGames.Client.Photon.LoadBalancing.ClientState ClientState => instance.client.State;

	public static string CurrentRoomName => (instance.client.CurrentRoom != null) ? instance.client.CurrentRoom.Name : string.Empty;

	public static string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			if (microphoneDevice != value && microphoneDevice != null)
			{
				SharedMicrophone.EndMicrophone(microphoneDevice);
			}
			microphoneDevice = value;
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogFormat("PUNVoice: Setting global microphone device to {0}", microphoneDevice);
			}
			PhotonVoiceRecorder[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceRecorder>();
			foreach (PhotonVoiceRecorder photonVoiceRecorder in array)
			{
				if (photonVoiceRecorder.photonView.isMine && photonVoiceRecorder.MicrophoneDevice == null)
				{
					photonVoiceRecorder.MicrophoneDevice = null;
				}
			}
		}
	}

	private PhotonVoiceNetwork()
	{
		client = new UnityVoiceFrontend(ConnectionProtocol.Udp);
	}

	internal static PhotonVoiceNetwork getInstance()
	{
		lock (instanceLock)
		{
			if (destroyed)
			{
				return null;
			}
			if (_instance == null)
			{
				_singleton = new GameObject();
				_instance = _singleton.AddComponent<PhotonVoiceNetwork>();
				_singleton.name = "PhotonVoiceNetworkSingleton";
				UnityEngine.Object.DontDestroyOnLoad(_singleton);
			}
			return _instance;
		}
	}

	private void OnDestroy()
	{
		PhotonNetwork.OnJoinedRoom -= new Action(OnJoinedRoom);
		PhotonNetwork.OnLeftRoom -= new Action(OnLeftRoom);
		PhotonNetwork.OnDisconnectedFromPhoton -= new Action(OnDisconnectedFromPhoton);
		if (!(this != _instance))
		{
			destroyed = true;
			client.Dispose();
		}
	}

	[RuntimeInitializeOnLoadMethod]
	public static void RuntimeInitializeOnLoad()
	{
		getInstance();
	}

	public void Awake()
	{
		PhotonNetwork.OnJoinedRoom += new Action(OnJoinedRoom);
		PhotonNetwork.OnLeftRoom += new Action(OnLeftRoom);
		PhotonNetwork.OnDisconnectedFromPhoton += new Action(OnDisconnectedFromPhoton);
		if (Microphone.devices.Length < 1)
		{
			UnityEngine.Debug.LogError("PUNVoice: No microphone device found");
		}
	}

	public static bool Connect()
	{
		instance.client.AppId = PhotonNetwork.PhotonServerSettings.VoiceAppID;
		instance.client.AppVersion = PhotonNetwork.gameVersion;
		if (PhotonNetwork.PhotonServerSettings.HostType == ServerSettings.HostingOption.SelfHosted)
		{
			string masterServerAddress = $"{PhotonNetwork.PhotonServerSettings.ServerAddress}:{PhotonNetwork.PhotonServerSettings.VoiceServerPort}";
			return instance.client.Connect(masterServerAddress, null, null, null, null);
		}
		if (PhotonNetwork.offlineMode || PhotonNetwork.networkingPeer.CloudRegion == CloudRegionCode.none)
		{
			return false;
		}
		UnityEngine.Debug.LogFormat("PUNVoice: connecting to region {0}", PhotonNetwork.networkingPeer.CloudRegion.ToString());
		return instance.client.ConnectToRegionMaster(PhotonNetwork.networkingPeer.CloudRegion.ToString());
	}

	public static void Disconnect()
	{
		instance.client.Disconnect();
	}

	protected void OnEnable()
	{
		if (!(this != _instance))
		{
			UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
		}
	}

	protected void OnApplicationQuit()
	{
		if (!(this != _instance))
		{
			client.Disconnect();
			client.Dispose();
		}
	}

	protected void Update()
	{
		if (!(this != _instance))
		{
			client.VoiceClient.DebugLostPercent = PhotonVoiceSettings.Instance.DebugLostPercent;
			client.Service();
		}
	}

	public static LocalVoice CreateLocalVoice(VoiceInfo voiceInfo, IBufferReader<float> reader)
	{
		LocalVoiceAudio<float> localVoiceAudio = instance.client.VoiceClient.CreateLocalVoiceAudio<float>(voiceInfo);
		localVoiceAudio.LocalUserServiceable = new BufferReaderPushAdapterAsyncPool<float>(localVoiceAudio, reader);
		return localVoiceAudio;
	}

	public static LocalVoice CreateLocalVoiceShort(VoiceInfo voiceInfo, IBufferReader<float> reader)
	{
		LocalVoiceAudio<short> localVoiceAudio = instance.client.VoiceClient.CreateLocalVoiceAudio<short>(voiceInfo);
		localVoiceAudio.LocalUserServiceable = new BufferReaderPushAdapterAsyncPoolFloatToShort(localVoiceAudio, reader);
		return localVoiceAudio;
	}

	private void OnJoinedRoom()
	{
		if (this != _instance)
		{
			return;
		}
		ExitGames.Client.Photon.LoadBalancing.ClientState state = client.State;
		if (state == ExitGames.Client.Photon.LoadBalancing.ClientState.Joined)
		{
			if (PhotonVoiceSettings.Instance.AutoConnect)
			{
				client.OpLeaveRoom();
			}
		}
		else if (PhotonVoiceSettings.Instance.AutoConnect)
		{
			client.Reconnect();
		}
	}

	private void OnLeftRoom()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	private void OnDisconnectedFromPhoton()
	{
		if (!(this != _instance) && PhotonVoiceSettings.Instance.AutoDisconnect)
		{
			client.Disconnect();
		}
	}

	internal static void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		instance.client.LinkSpeakerToRemoteVoice(speaker);
	}

	internal static void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		if (!destroyed)
		{
			instance.client.UnlinkSpeakerFromRemoteVoice(speaker);
		}
	}
}
public class UnityVoiceFrontend : LoadBalancingFrontend
{
	private Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeakers = new Dictionary<KeyValuePair<int, byte>, PhotonVoiceSpeaker>();

	private bool reconnect;

	public Action<int, byte, VoiceInfo> OnRemoteVoiceInfoAction { get; set; }

	public Action<int, byte> OnRemoteVoiceRemoveAction { get; set; }

	public Action<int, byte, float[]> OnAudioFrameAction { get; set; }

	public new Action<ExitGames.Client.Photon.LoadBalancing.ClientState> OnStateChangeAction { get; set; }

	public new Action<OperationResponse> OnOpResponseAction { get; set; }

	internal UnityVoiceFrontend(ConnectionProtocol connetProtocol)
		: base(connetProtocol)
	{
		VoiceClient obj = voiceClient;
		obj.OnRemoteVoiceInfoAction = (VoiceClient.RemoteVoiceInfoDelegate)Delegate.Combine(obj.OnRemoteVoiceInfoAction, new VoiceClient.RemoteVoiceInfoDelegate(OnRemoteVoiceInfo));
		base.AutoJoinLobby = false;
		base.OnStateChangeAction = (Action<ExitGames.Client.Photon.LoadBalancing.ClientState>)Delegate.Combine(base.OnStateChangeAction, new Action<ExitGames.Client.Photon.LoadBalancing.ClientState>(OnStateChange));
		base.OnOpResponseAction += OnOpResponse;
		loadBalancingPeer.DebugOut = DebugLevel.INFO;
	}

	public void Reconnect()
	{
		if (base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected || base.State == ExitGames.Client.Photon.LoadBalancing.ClientState.PeerCreated)
		{
			PhotonVoiceNetwork.Connect();
			return;
		}
		reconnect = true;
		Disconnect();
	}

	public override void DebugReturn(DebugLevel level, string message)
	{
		message = $"PUNVoice: {message}";
		if (level == DebugLevel.ERROR)
		{
			UnityEngine.Debug.LogError(message);
		}
	}

	public void OnOpResponse(OperationResponse resp)
	{
		if (OnOpResponseAction != null)
		{
			OnOpResponseAction(resp);
		}
	}

	private void linkVoice(int playerId, byte voiceId, VoiceInfo voiceInfo, PhotonVoiceSpeaker speaker)
	{
		speaker.OnVoiceLinked(voiceInfo.SamplingRate, voiceInfo.Channels, voiceInfo.FrameDurationSamples, PhotonVoiceSettings.Instance.PlayDelayMs);
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			if (value == speaker)
			{
				return;
			}
			if (PhotonVoiceSettings.Instance.DebugInfo)
			{
				UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice #{1} speaker replaced.", playerId, voiceId);
			}
		}
		else if (PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice #{1} speaker created.", playerId, voiceId);
		}
		voiceSpeakers[key] = speaker;
	}

	public void OnRemoteVoiceInfo(int channelId, int playerId, byte voiceId, VoiceInfo voiceInfo, ref RemoteVoiceOptions options)
	{
		options.OnDecodedFrameFloatAction = (Action<float[]>)Delegate.Combine(options.OnDecodedFrameFloatAction, (Action<float[]>)delegate(float[] frame)
		{
			OnAudioFrame(playerId, voiceId, frame);
		});
		options.OnRemoteVoiceRemoveAction = (Action)Delegate.Combine(options.OnRemoteVoiceRemoveAction, (Action)delegate
		{
			OnRemoteVoiceRemove(playerId, voiceId);
		});
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (voiceSpeakers.ContainsKey(key))
		{
		}
		PhotonVoiceSpeaker photonVoiceSpeaker = null;
		PhotonVoiceSpeaker[] array = UnityEngine.Object.FindObjectsOfType<PhotonVoiceSpeaker>();
		PhotonVoiceSpeaker[] array2 = array;
		foreach (PhotonVoiceSpeaker photonVoiceSpeaker2 in array2)
		{
			if (photonVoiceSpeaker2.photonView.viewID == (int)voiceInfo.UserData)
			{
				photonVoiceSpeaker = photonVoiceSpeaker2;
				break;
			}
		}
		if (!(photonVoiceSpeaker == null))
		{
			linkVoice(playerId, voiceId, voiceInfo, photonVoiceSpeaker);
		}
		if (OnRemoteVoiceInfoAction != null)
		{
			OnRemoteVoiceInfoAction(playerId, voiceId, voiceInfo);
		}
	}

	public void LinkSpeakerToRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		foreach (RemoteVoiceInfo remoteVoiceInfo in base.VoiceClient.RemoteVoiceInfos)
		{
			if (speaker.photonView.viewID == (int)remoteVoiceInfo.Info.UserData)
			{
				linkVoice(remoteVoiceInfo.PlayerId, remoteVoiceInfo.VoiceId, remoteVoiceInfo.Info, speaker);
			}
		}
	}

	public void OnRemoteVoiceRemove(int playerId, byte voiceId)
	{
		KeyValuePair<int, byte> key = new KeyValuePair<int, byte>(playerId, voiceId);
		if (unlinkSpeaker(key) && PhotonVoiceSettings.Instance.DebugInfo)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice # {1} speaker unlinked.", playerId, voiceId);
		}
		if (OnRemoteVoiceRemoveAction != null)
		{
			OnRemoteVoiceRemoveAction(playerId, voiceId);
		}
	}

	private bool unlinkSpeaker(KeyValuePair<int, byte> key)
	{
		if (voiceSpeakers.TryGetValue(key, out var value))
		{
			value.OnVoiceUnlinked();
		}
		return voiceSpeakers.Remove(key);
	}

	public void UnlinkSpeakerFromRemoteVoice(PhotonVoiceSpeaker speaker)
	{
		List<KeyValuePair<int, byte>> list = new List<KeyValuePair<int, byte>>();
		foreach (KeyValuePair<KeyValuePair<int, byte>, PhotonVoiceSpeaker> voiceSpeaker in voiceSpeakers)
		{
			if (voiceSpeaker.Value == speaker)
			{
				list.Add(voiceSpeaker.Key);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Player {0} voice # {1} speaker unlinked.", voiceSpeaker.Key.Key, voiceSpeaker.Key.Value);
				}
			}
		}
		foreach (KeyValuePair<int, byte> item in list)
		{
			unlinkSpeaker(item);
		}
	}

	public void OnAudioFrame(int playerId, byte voiceId, float[] frame)
	{
		PhotonVoiceSpeaker value = null;
		if (voiceSpeakers.TryGetValue(new KeyValuePair<int, byte>(playerId, voiceId), out value))
		{
			value.OnAudioFrame(frame);
		}
		if (OnAudioFrameAction != null)
		{
			OnAudioFrameAction(playerId, voiceId, frame);
		}
	}

	public void OnStateChange(ExitGames.Client.Photon.LoadBalancing.ClientState state)
	{
		if (PhotonNetwork.logLevel >= PhotonLogLevel.Informational)
		{
			UnityEngine.Debug.LogFormat("PUNVoice: Voice Client state: {0}", state);
		}
		switch (state)
		{
		case ExitGames.Client.Photon.LoadBalancing.ClientState.ConnectedToMasterserver:
			if (PhotonNetwork.inRoom)
			{
				OpJoinOrCreateRoom($"{PhotonNetwork.room.Name}_voice_", new ExitGames.Client.Photon.LoadBalancing.RoomOptions
				{
					IsVisible = false
				}, null);
			}
			else
			{
				Disconnect();
			}
			break;
		case ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected:
			if (reconnect)
			{
				PhotonVoiceNetwork.Connect();
			}
			reconnect = false;
			break;
		}
		if (OnStateChangeAction != null)
		{
			OnStateChangeAction(state);
		}
	}
}
[RequireComponent(typeof(PhotonVoiceSpeaker))]
[DisallowMultipleComponent]
[AddComponentMenu("Photon Voice/Photon Voice Recorder")]
[HelpURL("https://doc.photonengine.com/en-us/voice/current/getting-started/voice-for-pun#the__audio_source__prefab")]
public class PhotonVoiceRecorder : Photon.MonoBehaviour
{
	public struct VoiceCreatedParams
	{
		public LocalVoice Voice;

		public VoiceInfo Info;

		public VoiceCreatedParams(LocalVoice voice, VoiceInfo info)
		{
			Voice = voice;
			Info = info;
		}
	}

	private LocalVoice voice = LocalVoiceAudio.Dummy;

	private string microphoneDevice;

	public AudioClip AudioClip;

	public bool LoopAudioClip = true;

	protected ILocalVoiceAudio voiceAudio => (ILocalVoiceAudio)voice;

	public AudioUtil.IVoiceDetector VoiceDetector => (!base.photonView.isMine) ? null : voiceAudio.VoiceDetector;

	public string MicrophoneDevice
	{
		get
		{
			return microphoneDevice;
		}
		set
		{
			if (value != null && !Microphone.devices.Contains(value))
			{
				UnityEngine.Debug.LogError("PUNVoice: " + value + " is not a valid microphone device");
				return;
			}
			microphoneDevice = value;
			if (voice != LocalVoiceAudio.Dummy && AudioClip == null)
			{
				PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
				UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Setting recorder's microphone device to {0}", text);
				}
				voice.RemoveSelf();
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				bool debugEchoMode = DebugEchoMode;
				DebugEchoMode = false;
				VoiceInfo voiceInfo = VoiceInfo.CreateAudioOpus(instance.SamplingRate, micWrapper.SourceSamplingRate, micWrapper.Channels, instance.FrameDuration, instance.Bitrate, base.photonView.viewID);
				LocalVoice localVoice = voice;
				voice = createLocalVoice(voiceInfo, micWrapper);
				voice.Group = localVoice.Group;
				voice.Transmit = localVoice.Transmit;
				voiceAudio.VoiceDetector.On = voiceAudio.VoiceDetector.On;
				voiceAudio.VoiceDetector.Threshold = voiceAudio.VoiceDetector.Threshold;
				sendVoiceCreatedMessage(voiceInfo);
				DebugEchoMode = debugEchoMode;
			}
		}
	}

	public byte AudioGroup
	{
		get
		{
			return voice.Group;
		}
		set
		{
			voice.Group = value;
		}
	}

	public bool IsTransmitting => voice.IsTransmitting;

	public AudioUtil.ILevelMeter LevelMeter => voiceAudio.LevelMeter;

	public bool Transmit
	{
		get
		{
			return voice.Transmit;
		}
		set
		{
			voice.Transmit = value;
		}
	}

	public bool Detect
	{
		get
		{
			return voiceAudio.VoiceDetector.On;
		}
		set
		{
			voiceAudio.VoiceDetector.On = value;
		}
	}

	public bool DebugEchoMode
	{
		get
		{
			return voice.DebugEchoMode;
		}
		set
		{
			voice.DebugEchoMode = value;
		}
	}

	public bool VoiceDetectorCalibrating => voiceAudio.VoiceDetectorCalibrating;

	private void Start()
	{
		if (base.photonView.isMine)
		{
			PhotonVoiceSettings instance = PhotonVoiceSettings.Instance;
			if (MicrophoneDevice == null && PhotonVoiceNetwork.MicrophoneDevice == null)
			{
				UnityEngine.Debug.LogWarning("PUNVoice : PhotonVoiceRecorder is disabled since we do not have a microphone.");
				base.enabled = false;
				return;
			}
			UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
			int num = 0;
			int num2 = 0;
			IBufferReader<float> bufferReader;
			if (AudioClip == null)
			{
				if (Microphone.devices.Length < 1)
				{
					return;
				}
				string text = ((MicrophoneDevice == null) ? PhotonVoiceNetwork.MicrophoneDevice : MicrophoneDevice);
				if (PhotonVoiceSettings.Instance.DebugInfo)
				{
					UnityEngine.Debug.LogFormat("PUNVoice: Setting recorder's microphone device to {0}", text);
				}
				MicWrapper micWrapper = new MicWrapper(text, (int)instance.SamplingRate);
				num2 = micWrapper.SourceSamplingRate;
				num = micWrapper.Channels;
				bufferReader = micWrapper;
			}
			else
			{
				bufferReader = new AudioClipWrapper(AudioClip);
				num2 = AudioClip.frequency;
				num = AudioClip.channels;
				if (LoopAudioClip)
				{
					((AudioClipWrapper)bufferReader).Loop = true;
				}
			}
			VoiceInfo voiceInfo = VoiceInfo.CreateAudioOpus(instance.SamplingRate, num2, num, instance.FrameDuration, instance.Bitrate, base.photonView.viewID);
			voice = createLocalVoice(voiceInfo, bufferReader);
			VoiceDetector.On = PhotonVoiceSettings.Instance.VoiceDetection;
			VoiceDetector.Threshold = PhotonVoiceSettings.Instance.VoiceDetectionThreshold;
			if (voice != LocalVoiceAudio.Dummy)
			{
				voice.Transmit = PhotonVoiceSettings.Instance.AutoTransmit && SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.AlwaysOn;
			}
			else if (PhotonVoiceSettings.Instance.AutoTransmit)
			{
				UnityEngine.Debug.LogWarning("PUNVoice: Cannot Transmit.");
			}
			sendVoiceCreatedMessage(voiceInfo);
		}
		else
		{
			base.enabled = false;
		}
	}

	protected virtual LocalVoice createLocalVoice(VoiceInfo voiceInfo, IBufferReader<float> reader)
	{
		return PhotonVoiceNetwork.CreateLocalVoice(voiceInfo, reader);
	}

	protected virtual void sendVoiceCreatedMessage(VoiceInfo voiceInfo)
	{
		base.gameObject.SendMessage("VoiceCreated", new VoiceCreatedParams(voice, voiceInfo), SendMessageOptions.DontRequireReceiver);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (voice != LocalVoiceAudio.Dummy)
		{
			voice.RemoveSelf();
		}
	}

	private void OnEnable()
	{
		UnityEngine.Application.RequestUserAuthorization(UserAuthorization.Microphone);
	}

	public void VoiceDetectorCalibrate(int durationMs)
	{
		if (base.photonView.isMine)
		{
			voiceAudio.VoiceDetectorCalibrate(durationMs);
		}
	}

	private string tostr<T>(T[] x, int lim = 10)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < ((x.Length >= lim) ? lim : x.Length); i++)
		{
			stringBuilder.Append("-");
			stringBuilder.Append(x[i]);
		}
		return stringBuilder.ToString();
	}

	public string ToStringFull()
	{
		int minFreq = 0;
		int maxFreq = 0;
		Microphone.GetDeviceCaps(MicrophoneDevice, out minFreq, out maxFreq);
		return $"Mic '{MicrophoneDevice}': {minFreq}..{maxFreq} Hz";
	}
}
internal class PhotonVoiceRecorderShort : PhotonVoiceRecorder
{
	private class BufferReaderPushAdapterAsyncPoolFloatToShort : BufferReaderPushAdapterBase<float>
	{
		private float[] buffer;

		public BufferReaderPushAdapterAsyncPoolFloatToShort(LocalVoice localVoice, IBufferReader<float> reader)
			: base(reader)
		{
			buffer = new float[((LocalVoiceFramed<short>)localVoice).FrameSize];
		}

		public override void Service(LocalVoice localVoice)
		{
			LocalVoiceFramed<short> localVoiceFramed = (LocalVoiceFramed<short>)localVoice;
			short[] array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			while (reader.Read(buffer))
			{
				for (int i = 0; i < array.Length; i++)
				{
					array[i] = (short)(buffer[i] * 32767f);
				}
				localVoiceFramed.PushDataAsync(array);
				array = localVoiceFramed.PushDataBufferPool.AcquireOrCreate();
			}
			localVoiceFramed.PushDataBufferPool.Release(array, array.Length);
		}
	}

	protected override LocalVoice createLocalVoice(VoiceInfo voiceInfo, IBufferReader<float> reader)
	{
		return PhotonVoiceNetwork.CreateLocalVoiceShort(voiceInfo, reader);
	}
}
[DisallowMultipleComponent]
public class PhotonVoiceSettings : UnityEngine.MonoBehaviour
{
	public bool AutoConnect = true;

	public bool AutoDisconnect;

	public bool AutoTransmit = true;

	public SamplingRate SamplingRate = SamplingRate.Sampling24000;

	public OpusCodec.FrameDuration FrameDuration = OpusCodec.FrameDuration.Frame20ms;

	public int Bitrate = 30000;

	public bool VoiceDetection = true;

	public float VoiceDetectionThreshold = 0.05f;

	public int PlayDelayMs = 200;

	public int DebugLostPercent;

	public bool DebugInfo;

	private static PhotonVoiceSettings instance;

	private static object instanceLock = new object();

	public static PhotonVoiceSettings Instance
	{
		get
		{
			if (instance == null)
			{
				instance = PhotonVoiceNetwork.instance.gameObject.AddComponent<PhotonVoiceSettings>();
			}
			return instance;
		}
		private set
		{
			if (instance != value)
			{
				if (instance != null && value != null)
				{
					UnityEngine.Debug.LogErrorFormat(value, "PUNVoice: PhotonVoiceSettings instance already set, extra instance ignored.");
				}
				else
				{
					instance = value;
				}
			}
		}
	}

	private void Awake()
	{
		lock (instanceLock)
		{
			Instance = this;
		}
	}
