[RequireComponent(typeof(AudioSource))]
[DisallowMultipleComponent]
[AddComponentMenu("Photon Voice/Photon Voice Speaker")]
[HelpURL("https://doc.photonengine.com/en-us/voice/current/getting-started/voice-for-pun#the__audio_source__prefab")]
public class PhotonVoiceSpeaker : Photon.MonoBehaviour
{
	private AudioStreamPlayer player;

	public long LastRecvTime { get; private set; }

	public bool IsPlaying => player.IsPlaying;

	public int CurrentBufferLag => player.CurrentBufferLag;

	public bool IsVoiceLinked => player != null && player.IsStarted;

	public bool IsVoiceDetected { get; private set; }

	public float MaxAudioSample { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		player = new AudioStreamPlayer(GetComponent<AudioSource>(), "PUNVoice: PhotonVoiceSpeaker:", PhotonVoiceSettings.Instance.DebugInfo);
		PhotonVoiceNetwork.LinkSpeakerToRemoteVoice(this);
	}

	internal void OnVoiceLinked(int frequency, int channels, int frameSamplesPerChannel, int playDelayMs)
	{
		player.Start(frequency, channels, frameSamplesPerChannel, playDelayMs);
	}

	public void Pause()
	{
		player.Pause();
	}

	internal void OnVoiceUnlinked()
	{
		player.Stop();
	}

	private void Update()
	{
		player.Update();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		PhotonVoiceNetwork.UnlinkSpeakerFromRemoteVoice(this);
		player.Stop();
	}

	private void OnApplicationQuit()
	{
		player.Stop();
	}

	internal void OnAudioFrame(float[] frame)
	{
		LastRecvTime = DateTime.UtcNow.Ticks;
		player.OnAudioFrame(frame);
		float num = 0f;
		foreach (float f in frame)
		{
			num = Mathf.Max(Mathf.Abs(f), num);
		}
		IsVoiceDetected = num > PhotonVoiceSettings.Instance.VoiceDetectionThreshold;
		MaxAudioSample = num;
	}
}
public struct GazeEventArgs
{
	public float distance;
}
public delegate void GazeEventHandler(object sender, GazeEventArgs e);
public class SteamVR_GazeTracker : UnityEngine.MonoBehaviour
{
	public bool isInGaze;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private GazeEventHandler m_GazeOn;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private GazeEventHandler m_GazeOff;

	public float gazeInCutoff = 0.15f;

	public float gazeOutCutoff = 0.4f;

	private Transform hmdTrackedObject;

	public event GazeEventHandler GazeOn
	{
		add
		{
			GazeEventHandler gazeEventHandler = this.m_GazeOn;
			GazeEventHandler gazeEventHandler2;
			do
			{
				gazeEventHandler2 = gazeEventHandler;
				gazeEventHandler = Interlocked.CompareExchange(ref this.m_GazeOn, (GazeEventHandler)Delegate.Combine(gazeEventHandler2, value), gazeEventHandler);
			}
			while (gazeEventHandler != gazeEventHandler2);
		}
		remove
		{
			GazeEventHandler gazeEventHandler = this.m_GazeOn;
			GazeEventHandler gazeEventHandler2;
			do
			{
				gazeEventHandler2 = gazeEventHandler;
				gazeEventHandler = Interlocked.CompareExchange(ref this.m_GazeOn, (GazeEventHandler)Delegate.Remove(gazeEventHandler2, value), gazeEventHandler);
			}
			while (gazeEventHandler != gazeEventHandler2);
		}
	}

	public event GazeEventHandler GazeOff
	{
		add
		{
			GazeEventHandler gazeEventHandler = this.m_GazeOff;
			GazeEventHandler gazeEventHandler2;
			do
			{
				gazeEventHandler2 = gazeEventHandler;
				gazeEventHandler = Interlocked.CompareExchange(ref this.m_GazeOff, (GazeEventHandler)Delegate.Combine(gazeEventHandler2, value), gazeEventHandler);
			}
			while (gazeEventHandler != gazeEventHandler2);
		}
		remove
		{
			GazeEventHandler gazeEventHandler = this.m_GazeOff;
			GazeEventHandler gazeEventHandler2;
			do
			{
				gazeEventHandler2 = gazeEventHandler;
				gazeEventHandler = Interlocked.CompareExchange(ref this.m_GazeOff, (GazeEventHandler)Delegate.Remove(gazeEventHandler2, value), gazeEventHandler);
			}
			while (gazeEventHandler != gazeEventHandler2);
		}
	}

	private void Start()
	{
	}

	public virtual void OnGazeOn(GazeEventArgs e)
	{
		if (this.GazeOn != null)
		{
			this.GazeOn(this, e);
		}
	}

	public virtual void OnGazeOff(GazeEventArgs e)
	{
		if (this.GazeOff != null)
		{
			this.GazeOff(this, e);
		}
	}

	private void Update()
	{
		if (hmdTrackedObject == null)
		{
			SteamVR_TrackedObject[] array = UnityEngine.Object.FindObjectsOfType<SteamVR_TrackedObject>();
			SteamVR_TrackedObject[] array2 = array;
			foreach (SteamVR_TrackedObject steamVR_TrackedObject in array2)
			{
				if (steamVR_TrackedObject.index == SteamVR_TrackedObject.EIndex.Hmd)
				{
					hmdTrackedObject = steamVR_TrackedObject.transform;
					break;
				}
			}
		}
		if (!hmdTrackedObject)
		{
			return;
		}
		Ray ray = new Ray(hmdTrackedObject.position, hmdTrackedObject.forward);
		Plane plane = new Plane(hmdTrackedObject.forward, base.transform.position);
		float enter = 0f;
		if (plane.Raycast(ray, out enter))
		{
			Vector3 a = hmdTrackedObject.position + hmdTrackedObject.forward * enter;
			float num = Vector3.Distance(a, base.transform.position);
			if (num < gazeInCutoff && !isInGaze)
			{
				isInGaze = true;
				GazeEventArgs e = default(GazeEventArgs);
				e.distance = num;
				OnGazeOn(e);
			}
			else if (num >= gazeOutCutoff && isInGaze)
			{
				isInGaze = false;
				GazeEventArgs e2 = default(GazeEventArgs);
				e2.distance = num;
				OnGazeOff(e2);
			}
		}
	}
}
