		public static string CombinePaths(params string[] paths)
		{
			if (paths.Length == 0)
			{
				return string.Empty;
			}
			string text = paths[0];
			for (int i = 1; i < paths.Length; i++)
			{
				text = Path.Combine(text, paths[i]);
			}
			return text;
		}
