	[Serializable]
	public class AfterTimer_Component : UnityEngine.MonoBehaviour
	{
		private Action callback;

		private float triggerTime;

		private bool timerActive;

		private bool triggerOnEarlyDestroy;

		public void Init(float _time, Action _callback, bool earlydestroy)
		{
			triggerTime = _time;
			callback = _callback;
			triggerOnEarlyDestroy = earlydestroy;
			timerActive = true;
			StartCoroutine(Wait());
		}

		private IEnumerator Wait()
		{
			yield return new WaitForSeconds(triggerTime);
			timerActive = false;
			callback();
			UnityEngine.Object.Destroy(this);
		}

		private void OnDestroy()
		{
			if (timerActive)
			{
				StopCoroutine(Wait());
				timerActive = false;
				if (triggerOnEarlyDestroy)
				{
					callback();
				}
			}
		}
	}
	public class VelocityEstimator : UnityEngine.MonoBehaviour
	{
		[Tooltip("How many frames to average over for computing velocity")]
		public int velocityAverageFrames = 5;

		[Tooltip("How many frames to average over for computing angular velocity")]
		public int angularVelocityAverageFrames = 11;

		public bool estimateOnAwake;

		private Coroutine routine;

		private int sampleCount;

		private Vector3[] velocitySamples;

		private Vector3[] angularVelocitySamples;

		public void BeginEstimatingVelocity()
		{
			FinishEstimatingVelocity();
			routine = StartCoroutine(EstimateVelocityCoroutine());
		}

		public void FinishEstimatingVelocity()
		{
			if (routine != null)
			{
				StopCoroutine(routine);
				routine = null;
			}
		}

		public Vector3 GetVelocityEstimate()
		{
			Vector3 zero = Vector3.zero;
			int num = Mathf.Min(sampleCount, velocitySamples.Length);
			if (num != 0)
			{
				for (int i = 0; i < num; i++)
				{
					zero += velocitySamples[i];
				}
				zero *= 1f / (float)num;
			}
			return zero;
		}

		public Vector3 GetAngularVelocityEstimate()
		{
			Vector3 zero = Vector3.zero;
			int num = Mathf.Min(sampleCount, angularVelocitySamples.Length);
			if (num != 0)
			{
				for (int i = 0; i < num; i++)
				{
					zero += angularVelocitySamples[i];
				}
				zero *= 1f / (float)num;
			}
			return zero;
		}

		public Vector3 GetAccelerationEstimate()
		{
			Vector3 zero = Vector3.zero;
			for (int i = 2 + sampleCount - velocitySamples.Length; i < sampleCount; i++)
			{
				if (i >= 2)
				{
					int num = i - 2;
					int num2 = i - 1;
					Vector3 vector = velocitySamples[num % velocitySamples.Length];
					Vector3 vector2 = velocitySamples[num2 % velocitySamples.Length];
					zero += vector2 - vector;
				}
			}
			return zero * (1f / UnityEngine.Time.deltaTime);
		}

		private void Awake()
		{
			velocitySamples = new Vector3[velocityAverageFrames];
			angularVelocitySamples = new Vector3[angularVelocityAverageFrames];
			if (estimateOnAwake)
			{
				BeginEstimatingVelocity();
			}
		}

		private IEnumerator EstimateVelocityCoroutine()
		{
			sampleCount = 0;
			Vector3 previousPosition = base.transform.position;
			Quaternion previousRotation = base.transform.rotation;
			while (true)
			{
				yield return new WaitForEndOfFrame();
				float velocityFactor = 1f / UnityEngine.Time.deltaTime;
				int v = sampleCount % velocitySamples.Length;
				int w = sampleCount % angularVelocitySamples.Length;
				sampleCount++;
				ref Vector3 reference = ref velocitySamples[v];
				reference = velocityFactor * (base.transform.position - previousPosition);
				Quaternion deltaRotation = base.transform.rotation * Quaternion.Inverse(previousRotation);
				float theta = 2f * Mathf.Acos(Mathf.Clamp(deltaRotation.w, -1f, 1f));
				if (theta > (float)Math.PI)
				{
					theta -= (float)Math.PI * 2f;
				}
				Vector3 angularVelocity = new Vector3(deltaRotation.x, deltaRotation.y, deltaRotation.z);
				if (angularVelocity.sqrMagnitude > 0f)
				{
					angularVelocity = theta * velocityFactor * angularVelocity.normalized;
				}
				angularVelocitySamples[w] = angularVelocity;
				previousPosition = base.transform.position;
				previousRotation = base.transform.rotation;
			}
		}
	}
	public class ControllerButtonHints : UnityEngine.MonoBehaviour
	{
		private enum OffsetType
		{
			Up,
			Right,
			Forward,
			Back
		}

		private class ButtonHintInfo
		{
			public string componentName;

			public List<MeshRenderer> renderers;

			public Transform localTransform;

			public GameObject textHintObject;

			public Transform textStartAnchor;

			public Transform textEndAnchor;

			public Vector3 textEndOffsetDir;

			public Transform canvasOffset;

			public Text text;

			public TextMesh textMesh;

			public Canvas textCanvas;

			public LineRenderer line;

			public float distanceFromCenter;

			public bool textHintActive;
		}

		public Material controllerMaterial;

		public Color flashColor = new Color(1f, 0.557f, 0f);

		public GameObject textHintPrefab;

		[Header("Debug")]
		public bool debugHints;

		private SteamVR_RenderModel renderModel;

		private Player player;

		private List<MeshRenderer> renderers = new List<MeshRenderer>();

		private List<MeshRenderer> flashingRenderers = new List<MeshRenderer>();

		private float startTime;

		private float tickCount;

		private Dictionary<EVRButtonId, ButtonHintInfo> buttonHintInfos;

		private Transform textHintParent;

		private List<KeyValuePair<string, ulong>> componentButtonMasks = new List<KeyValuePair<string, ulong>>();

		private int colorID;

		private Vector3 centerPosition = Vector3.zero;

		private SteamVR_Events.Action renderModelLoadedAction;

		public bool initialized { get; private set; }

		private void Awake()
		{
			renderModelLoadedAction = SteamVR_Events.RenderModelLoadedAction(OnRenderModelLoaded);
			colorID = Shader.PropertyToID("_Color");
		}

		private void Start()
		{
			player = Player.instance;
		}

		private void HintDebugLog(string msg)
		{
			if (debugHints)
			{
				UnityEngine.Debug.Log("Hints: " + msg);
			}
		}

		private void OnEnable()
		{
			renderModelLoadedAction.enabled = true;
		}

		private void OnDisable()
		{
			renderModelLoadedAction.enabled = false;
			Clear();
		}

		private void OnParentHandInputFocusLost()
		{
			HideAllButtonHints();
			HideAllText();
		}

		private void OnHandInitialized(int deviceIndex)
		{
			renderModel = new GameObject("SteamVR_RenderModel").AddComponent<SteamVR_RenderModel>();
			renderModel.transform.parent = base.transform;
			renderModel.transform.localPosition = Vector3.zero;
			renderModel.transform.localRotation = Quaternion.identity;
			renderModel.transform.localScale = Vector3.one;
			renderModel.SetDeviceIndex(deviceIndex);
			if (!initialized)
			{
				renderModel.gameObject.SetActive(value: true);
			}
		}

		private void OnRenderModelLoaded(SteamVR_RenderModel renderModel, bool succeess)
		{
			if (!(renderModel == this.renderModel))
			{
				return;
			}
			textHintParent = new GameObject("Text Hints").transform;
			textHintParent.SetParent(base.transform);
			textHintParent.localPosition = Vector3.zero;
			textHintParent.localRotation = Quaternion.identity;
			textHintParent.localScale = Vector3.one;
			using (SteamVR_RenderModel.RenderModelInterfaceHolder renderModelInterfaceHolder = new SteamVR_RenderModel.RenderModelInterfaceHolder())
			{
				CVRRenderModels instance = renderModelInterfaceHolder.instance;
				if (instance != null)
				{
					string text = "Components for render model " + renderModel.index;
					foreach (Transform item in renderModel.transform)
					{
						ulong componentButtonMask = instance.GetComponentButtonMask(renderModel.renderModelName, item.name);
						componentButtonMasks.Add(new KeyValuePair<string, ulong>(item.name, componentButtonMask));
						string text2 = text;
						text = text2 + "\n\t" + item.name + ": " + componentButtonMask;
					}
					HintDebugLog(text);
				}
			}
			buttonHintInfos = new Dictionary<EVRButtonId, ButtonHintInfo>();
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_Axis1);
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_ApplicationMenu);
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_System);
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_Grip);
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_Axis0);
			CreateAndAddButtonInfo(EVRButtonId.k_EButton_A);
			ComputeTextEndTransforms();
			initialized = true;
			renderModel.gameObject.SetActive(value: false);
		}

		private void CreateAndAddButtonInfo(EVRButtonId buttonID)
		{
			Transform transform = null;
			List<MeshRenderer> list = new List<MeshRenderer>();
			string text = "Looking for button: " + buttonID;
			EVRButtonId eVRButtonId = buttonID;
			if (buttonID == EVRButtonId.k_EButton_Grip && SteamVR.instance.hmd_TrackingSystemName.ToLowerInvariant().Contains("oculus"))
			{
				eVRButtonId = EVRButtonId.k_EButton_Axis2;
			}
			ulong num = (ulong)(1L << (int)eVRButtonId);
			string text2;
			foreach (KeyValuePair<string, ulong> componentButtonMask in componentButtonMasks)
			{
				if ((componentButtonMask.Value & num) == num)
				{
					text2 = text;
					text = text2 + "\nFound component: " + componentButtonMask.Key + " " + componentButtonMask.Value;
					Transform transform2 = renderModel.FindComponent(componentButtonMask.Key);
					transform = transform2;
					text2 = text;
					text = string.Concat(text2, "\nFound componentTransform: ", transform2, " buttonTransform: ", transform);
					list.AddRange(transform2.GetComponentsInChildren<MeshRenderer>());
				}
			}
			text2 = text;
			text = text2 + "\nFound " + list.Count + " renderers for " + buttonID;
			foreach (MeshRenderer item in list)
			{
				text = text + "\n\t" + item.name;
			}
			HintDebugLog(text);
			if (transform == null)
			{
				HintDebugLog("Couldn't find buttonTransform for " + buttonID);
				return;
			}
			ButtonHintInfo buttonHintInfo = new ButtonHintInfo();
			buttonHintInfos.Add(buttonID, buttonHintInfo);
			buttonHintInfo.componentName = transform.name;
			buttonHintInfo.renderers = list;
			buttonHintInfo.localTransform = transform.Find("attach");
			OffsetType offsetType = OffsetType.Right;
			switch (buttonID)
			{
			case EVRButtonId.k_EButton_Axis1:
				offsetType = OffsetType.Right;
				break;
			case EVRButtonId.k_EButton_ApplicationMenu:
				offsetType = OffsetType.Right;
				break;
			case EVRButtonId.k_EButton_System:
				offsetType = OffsetType.Right;
				break;
			case EVRButtonId.k_EButton_Grip:
				offsetType = OffsetType.Forward;
				break;
			case EVRButtonId.k_EButton_Axis0:
				offsetType = OffsetType.Up;
				break;
			}
			switch (offsetType)
			{
			case OffsetType.Forward:
				buttonHintInfo.textEndOffsetDir = buttonHintInfo.localTransform.forward;
				break;
			case OffsetType.Back:
				buttonHintInfo.textEndOffsetDir = -buttonHintInfo.localTransform.forward;
				break;
			case OffsetType.Right:
				buttonHintInfo.textEndOffsetDir = buttonHintInfo.localTransform.right;
				break;
			case OffsetType.Up:
				buttonHintInfo.textEndOffsetDir = buttonHintInfo.localTransform.up;
				break;
			}
			Vector3 position = buttonHintInfo.localTransform.position + buttonHintInfo.localTransform.forward * 0.01f;
			buttonHintInfo.textHintObject = UnityEngine.Object.Instantiate(textHintPrefab, position, Quaternion.identity);
			buttonHintInfo.textHintObject.name = "Hint_" + buttonHintInfo.componentName + "_Start";
			buttonHintInfo.textHintObject.transform.SetParent(textHintParent);
			buttonHintInfo.textHintObject.layer = base.gameObject.layer;
			buttonHintInfo.textHintObject.tag = base.gameObject.tag;
			buttonHintInfo.textStartAnchor = buttonHintInfo.textHintObject.transform.Find("Start");
			buttonHintInfo.textEndAnchor = buttonHintInfo.textHintObject.transform.Find("End");
			buttonHintInfo.canvasOffset = buttonHintInfo.textHintObject.transform.Find("CanvasOffset");
			buttonHintInfo.line = buttonHintInfo.textHintObject.transform.Find("Line").GetComponent<LineRenderer>();
			buttonHintInfo.textCanvas = buttonHintInfo.textHintObject.GetComponentInChildren<Canvas>();
			buttonHintInfo.text = buttonHintInfo.textCanvas.GetComponentInChildren<Text>();
			buttonHintInfo.textMesh = buttonHintInfo.textCanvas.GetComponentInChildren<TextMesh>();
			buttonHintInfo.textHintObject.SetActive(value: false);
			buttonHintInfo.textStartAnchor.position = position;
			if (buttonHintInfo.text != null)
			{
				buttonHintInfo.text.text = buttonHintInfo.componentName;
			}
			if (buttonHintInfo.textMesh != null)
			{
				buttonHintInfo.textMesh.text = buttonHintInfo.componentName;
			}
			centerPosition += buttonHintInfo.textStartAnchor.position;
			buttonHintInfo.textCanvas.transform.localScale = Vector3.Scale(buttonHintInfo.textCanvas.transform.localScale, player.transform.localScale);
			buttonHintInfo.textStartAnchor.transform.localScale = Vector3.Scale(buttonHintInfo.textStartAnchor.transform.localScale, player.transform.localScale);
			buttonHintInfo.textEndAnchor.transform.localScale = Vector3.Scale(buttonHintInfo.textEndAnchor.transform.localScale, player.transform.localScale);
			buttonHintInfo.line.transform.localScale = Vector3.Scale(buttonHintInfo.line.transform.localScale, player.transform.localScale);
		}

		private void ComputeTextEndTransforms()
		{
			centerPosition /= (float)buttonHintInfos.Count;
			float num = 0f;
			foreach (KeyValuePair<EVRButtonId, ButtonHintInfo> buttonHintInfo in buttonHintInfos)
			{
				buttonHintInfo.Value.distanceFromCenter = Vector3.Distance(buttonHintInfo.Value.textStartAnchor.position, centerPosition);
				if (buttonHintInfo.Value.distanceFromCenter > num)
				{
					num = buttonHintInfo.Value.distanceFromCenter;
				}
			}
			foreach (KeyValuePair<EVRButtonId, ButtonHintInfo> buttonHintInfo2 in buttonHintInfos)
			{
				Vector3 vector = buttonHintInfo2.Value.textStartAnchor.position - centerPosition;
				vector.Normalize();
				vector = Vector3.Project(vector, renderModel.transform.forward);
				float num2 = buttonHintInfo2.Value.distanceFromCenter / num;
				float num3 = buttonHintInfo2.Value.distanceFromCenter * Mathf.Pow(2f, 10f * (num2 - 1f)) * 20f;
				float num4 = 0.1f;
				Vector3 position = buttonHintInfo2.Value.textStartAnchor.position + buttonHintInfo2.Value.textEndOffsetDir * num4 + vector * num3 * 0.1f;
				buttonHintInfo2.Value.textEndAnchor.position = position;
				buttonHintInfo2.Value.canvasOffset.position = position;
				buttonHintInfo2.Value.canvasOffset.localRotation = Quaternion.identity;
			}
		}

		private void ShowButtonHint(params EVRButtonId[] buttons)
		{
			renderModel.gameObject.SetActive(value: true);
			renderModel.GetComponentsInChildren(renderers);
			for (int i = 0; i < renderers.Count; i++)
			{
				Texture mainTexture = renderers[i].material.mainTexture;
				renderers[i].sharedMaterial = controllerMaterial;
				renderers[i].material.mainTexture = mainTexture;
				renderers[i].material.renderQueue = controllerMaterial.shader.renderQueue;
			}
			for (int j = 0; j < buttons.Length; j++)
			{
				if (!buttonHintInfos.ContainsKey(buttons[j]))
				{
					continue;
				}
				ButtonHintInfo buttonHintInfo = buttonHintInfos[buttons[j]];
				foreach (MeshRenderer renderer in buttonHintInfo.renderers)
				{
					if (!flashingRenderers.Contains(renderer))
					{
						flashingRenderers.Add(renderer);
					}
				}
			}
			startTime = UnityEngine.Time.realtimeSinceStartup;
			tickCount = 0f;
		}

		private void HideAllButtonHints()
		{
			Clear();
			renderModel.gameObject.SetActive(value: false);
		}

		private void HideButtonHint(params EVRButtonId[] buttons)
		{
			Color color = controllerMaterial.GetColor(colorID);
			for (int i = 0; i < buttons.Length; i++)
			{
				if (!buttonHintInfos.ContainsKey(buttons[i]))
				{
					continue;
				}
				ButtonHintInfo buttonHintInfo = buttonHintInfos[buttons[i]];
				foreach (MeshRenderer renderer in buttonHintInfo.renderers)
				{
					renderer.material.color = color;
					flashingRenderers.Remove(renderer);
				}
			}
			if (flashingRenderers.Count == 0)
			{
				renderModel.gameObject.SetActive(value: false);
			}
		}

		private bool IsButtonHintActive(EVRButtonId button)
		{
			if (buttonHintInfos.ContainsKey(button))
			{
				ButtonHintInfo buttonHintInfo = buttonHintInfos[button];
				foreach (MeshRenderer renderer in buttonHintInfo.renderers)
				{
					if (flashingRenderers.Contains(renderer))
					{
						return true;
					}
				}
			}
			return false;
		}

		private IEnumerator TestButtonHints()
		{
			while (true)
			{
				ShowButtonHint(EVRButtonId.k_EButton_Axis1);
				yield return new WaitForSeconds(1f);
				ShowButtonHint(EVRButtonId.k_EButton_ApplicationMenu);
				yield return new WaitForSeconds(1f);
				ShowButtonHint(default(EVRButtonId));
				yield return new WaitForSeconds(1f);
				ShowButtonHint(EVRButtonId.k_EButton_Grip);
				yield return new WaitForSeconds(1f);
				ShowButtonHint(EVRButtonId.k_EButton_Axis0);
				yield return new WaitForSeconds(1f);
			}
		}

		private IEnumerator TestTextHints()
		{
			while (true)
			{
				ShowText(EVRButtonId.k_EButton_Axis1, "Trigger");
				yield return new WaitForSeconds(3f);
				ShowText(EVRButtonId.k_EButton_ApplicationMenu, "Application");
				yield return new WaitForSeconds(3f);
				ShowText(EVRButtonId.k_EButton_System, "System");
				yield return new WaitForSeconds(3f);
				ShowText(EVRButtonId.k_EButton_Grip, "Grip");
				yield return new WaitForSeconds(3f);
				ShowText(EVRButtonId.k_EButton_Axis0, "Touchpad");
				yield return new WaitForSeconds(3f);
				HideAllText();
				yield return new WaitForSeconds(3f);
			}
		}

		private void Update()
		{
			if (!(renderModel != null) || !renderModel.gameObject.activeInHierarchy || flashingRenderers.Count <= 0)
			{
				return;
			}
			Color color = controllerMaterial.GetColor(colorID);
			float f = (UnityEngine.Time.realtimeSinceStartup - startTime) * (float)Math.PI * 2f;
			f = Mathf.Cos(f);
			f = Util.RemapNumberClamped(f, -1f, 1f, 0f, 1f);
			float num = UnityEngine.Time.realtimeSinceStartup - startTime;
			if (num - tickCount > 1f)
			{
				tickCount += 1f;
				SteamVR_Controller.Input((int)renderModel.index)?.TriggerHapticPulse(500);
			}
			for (int i = 0; i < flashingRenderers.Count; i++)
			{
				Renderer renderer = flashingRenderers[i];
				renderer.material.SetColor(colorID, Color.Lerp(color, flashColor, f));
			}
			if (!initialized)
			{
				return;
			}
			foreach (KeyValuePair<EVRButtonId, ButtonHintInfo> buttonHintInfo in buttonHintInfos)
			{
				if (buttonHintInfo.Value.textHintActive)
				{
					UpdateTextHint(buttonHintInfo.Value);
				}
			}
		}

		private void UpdateTextHint(ButtonHintInfo hintInfo)
		{
			Transform hmdTransform = player.hmdTransform;
			Vector3 forward = hmdTransform.position - hintInfo.canvasOffset.position;
			Quaternion a = Quaternion.LookRotation(forward, Vector3.up);
			Quaternion b = Quaternion.LookRotation(forward, hmdTransform.up);
			float t = ((!(hmdTransform.forward.y > 0f)) ? Util.RemapNumberClamped(hmdTransform.forward.y, -0.8f, -0.6f, 1f, 0f) : Util.RemapNumberClamped(hmdTransform.forward.y, 0.6f, 0.4f, 1f, 0f));
			hintInfo.canvasOffset.rotation = Quaternion.Slerp(a, b, t);
			Transform transform = hintInfo.line.transform;
			hintInfo.line.useWorldSpace = false;
			hintInfo.line.SetPosition(0, transform.InverseTransformPoint(hintInfo.textStartAnchor.position));
			hintInfo.line.SetPosition(1, transform.InverseTransformPoint(hintInfo.textEndAnchor.position));
		}

		private void Clear()
		{
			renderers.Clear();
			flashingRenderers.Clear();
		}

		private void ShowText(EVRButtonId button, string text, bool highlightButton = true)
		{
			if (buttonHintInfos.ContainsKey(button))
			{
				ButtonHintInfo buttonHintInfo = buttonHintInfos[button];
				buttonHintInfo.textHintObject.SetActive(value: true);
				buttonHintInfo.textHintActive = true;
				if (buttonHintInfo.text != null)
				{
					buttonHintInfo.text.text = text;
				}
				if (buttonHintInfo.textMesh != null)
				{
					buttonHintInfo.textMesh.text = text;
				}
				UpdateTextHint(buttonHintInfo);
				if (highlightButton)
				{
					ShowButtonHint(button);
				}
				renderModel.gameObject.SetActive(value: true);
			}
		}

		private void HideText(EVRButtonId button)
		{
			if (buttonHintInfos.ContainsKey(button))
			{
				ButtonHintInfo buttonHintInfo = buttonHintInfos[button];
				buttonHintInfo.textHintObject.SetActive(value: false);
				buttonHintInfo.textHintActive = false;
				HideButtonHint(button);
			}
		}

		private void HideAllText()
		{
			foreach (KeyValuePair<EVRButtonId, ButtonHintInfo> buttonHintInfo in buttonHintInfos)
			{
				buttonHintInfo.Value.textHintObject.SetActive(value: false);
				buttonHintInfo.Value.textHintActive = false;
			}
			HideAllButtonHints();
		}

		private string GetActiveHintText(EVRButtonId button)
		{
			if (buttonHintInfos.ContainsKey(button))
			{
				ButtonHintInfo buttonHintInfo = buttonHintInfos[button];
				if (buttonHintInfo.textHintActive)
				{
					return buttonHintInfo.text.text;
				}
			}
			return string.Empty;
		}

		private static ControllerButtonHints GetControllerButtonHints(Hand hand)
		{
			if (hand != null)
			{
				ControllerButtonHints componentInChildren = hand.GetComponentInChildren<ControllerButtonHints>();
				if (componentInChildren != null && componentInChildren.initialized)
				{
					return componentInChildren;
				}
			}
			return null;
		}

		public static void ShowButtonHint(Hand hand, params EVRButtonId[] buttons)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.ShowButtonHint(buttons);
			}
		}

		public static void HideButtonHint(Hand hand, params EVRButtonId[] buttons)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.HideButtonHint(buttons);
			}
		}

		public static void HideAllButtonHints(Hand hand)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.HideAllButtonHints();
			}
		}

		public static bool IsButtonHintActive(Hand hand, EVRButtonId button)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				return controllerButtonHints.IsButtonHintActive(button);
			}
			return false;
		}

		public static void ShowTextHint(Hand hand, EVRButtonId button, string text, bool highlightButton = true)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.ShowText(button, text, highlightButton);
			}
		}

		public static void HideTextHint(Hand hand, EVRButtonId button)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.HideText(button);
			}
		}

		public static void HideAllTextHints(Hand hand)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				controllerButtonHints.HideAllText();
			}
		}

		public static string GetActiveHintText(Hand hand, EVRButtonId button)
		{
			ControllerButtonHints controllerButtonHints = GetControllerButtonHints(hand);
			if (controllerButtonHints != null)
			{
				return controllerButtonHints.GetActiveHintText(button);
			}
			return string.Empty;
		}
	}
	public class ArcheryTarget : UnityEngine.MonoBehaviour
	{
		public UnityEvent onTakeDamage;

		public bool onceOnly;

		public Transform targetCenter;

		public Transform baseTransform;

		public Transform fallenDownTransform;

		public float fallTime = 0.5f;

		private const float targetRadius = 0.25f;

		private bool targetEnabled = true;

		private void ApplyDamage()
		{
			OnDamageTaken();
		}

		private void FireExposure()
		{
			OnDamageTaken();
		}

		private void OnDamageTaken()
		{
			if (targetEnabled)
			{
				onTakeDamage.Invoke();
				StartCoroutine(FallDown());
				if (onceOnly)
				{
					targetEnabled = false;
				}
			}
		}

		private IEnumerator FallDown()
		{
			if ((bool)baseTransform)
			{
				Quaternion startingRot = baseTransform.rotation;
				float startTime = UnityEngine.Time.time;
				float rotLerp = 0f;
				while (rotLerp < 1f)
				{
					rotLerp = Util.RemapNumberClamped(UnityEngine.Time.time, startTime, startTime + fallTime, 0f, 1f);
					baseTransform.rotation = Quaternion.Lerp(startingRot, fallenDownTransform.rotation, rotLerp);
					yield return null;
				}
			}
			yield return null;
		}
	}
	public class Arrow : UnityEngine.MonoBehaviour
	{
		public ParticleSystem glintParticle;

		public Rigidbody arrowHeadRB;

		public Rigidbody shaftRB;

		public PhysicMaterial targetPhysMaterial;

		private Vector3 prevPosition;

		private Quaternion prevRotation;

		private Vector3 prevVelocity;

		private Vector3 prevHeadPosition;

		public SoundPlayOneshot fireReleaseSound;

		public SoundPlayOneshot airReleaseSound;

		public SoundPlayOneshot hitTargetSound;

		public PlaySound hitGroundSound;

		private bool inFlight;

		private bool released;

		private bool hasSpreadFire;

		private int travelledFrames;

		private GameObject scaleParentObject;

		private void Start()
		{
			Physics.IgnoreCollision(shaftRB.GetComponent<Collider>(), Player.instance.headCollider);
		}

		private void FixedUpdate()
		{
			if (released && inFlight)
			{
				prevPosition = base.transform.position;
				prevRotation = base.transform.rotation;
				prevVelocity = GetComponent<Rigidbody>().velocity;
				prevHeadPosition = arrowHeadRB.transform.position;
				travelledFrames++;
			}
		}

		public void ArrowReleased(float inputVelocity)
		{
			inFlight = true;
			released = true;
			airReleaseSound.Play();
			if (glintParticle != null)
			{
				glintParticle.Play();
			}
			if (base.gameObject.GetComponentInChildren<FireSource>().isBurning)
			{
				fireReleaseSound.Play();
			}
			RaycastHit[] array = Physics.SphereCastAll(base.transform.position, 0.01f, base.transform.forward, 0.8f, -5, QueryTriggerInteraction.Ignore);
			RaycastHit[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				RaycastHit raycastHit = array2[i];
				if (raycastHit.collider.gameObject != base.gameObject && raycastHit.collider.gameObject != arrowHeadRB.gameObject && raycastHit.collider != Player.instance.headCollider)
				{
					UnityEngine.Object.Destroy(base.gameObject);
					return;
				}
			}
			travelledFrames = 0;
			prevPosition = base.transform.position;
			prevRotation = base.transform.rotation;
			prevHeadPosition = arrowHeadRB.transform.position;
			prevVelocity = GetComponent<Rigidbody>().velocity;
			UnityEngine.Object.Destroy(base.gameObject, 30f);
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (!inFlight)
			{
				return;
			}
			Rigidbody component = GetComponent<Rigidbody>();
			float sqrMagnitude = component.velocity.sqrMagnitude;
			bool flag = targetPhysMaterial != null && collision.collider.sharedMaterial == targetPhysMaterial && sqrMagnitude > 0.2f;
			bool flag2 = collision.collider.gameObject.GetComponent<Balloon>() != null;
			if (travelledFrames < 2 && !flag)
			{
				base.transform.position = prevPosition - prevVelocity * UnityEngine.Time.deltaTime;
				base.transform.rotation = prevRotation;
				Vector3 vector = Vector3.Reflect(arrowHeadRB.velocity, collision.contacts[0].normal);
				arrowHeadRB.velocity = vector * 0.25f;
				shaftRB.velocity = vector * 0.25f;
				travelledFrames = 0;
				return;
			}
			if (glintParticle != null)
			{
				glintParticle.Stop(withChildren: true);
			}
			if (sqrMagnitude > 0.1f)
			{
				hitGroundSound.Play();
			}
			FireSource componentInChildren = base.gameObject.GetComponentInChildren<FireSource>();
			FireSource componentInParent = collision.collider.GetComponentInParent<FireSource>();
			if (componentInChildren != null && componentInChildren.isBurning && componentInParent != null)
			{
				if (!hasSpreadFire)
				{
					collision.collider.gameObject.SendMessageUpwards("FireExposure", base.gameObject, SendMessageOptions.DontRequireReceiver);
					hasSpreadFire = true;
				}
			}
			else if (sqrMagnitude > 0.1f || flag2)
			{
				collision.collider.gameObject.SendMessageUpwards("ApplyDamage", SendMessageOptions.DontRequireReceiver);
				base.gameObject.SendMessage("HasAppliedDamage", SendMessageOptions.DontRequireReceiver);
			}
			if (flag2)
			{
				base.transform.position = prevPosition;
				base.transform.rotation = prevRotation;
				arrowHeadRB.velocity = prevVelocity;
				Physics.IgnoreCollision(arrowHeadRB.GetComponent<Collider>(), collision.collider);
				Physics.IgnoreCollision(shaftRB.GetComponent<Collider>(), collision.collider);
			}
			if (flag)
			{
				StickInTarget(collision, travelledFrames < 2);
			}
			if ((bool)Player.instance && collision.collider == Player.instance.headCollider)
			{
				Player.instance.PlayerShotSelf();
			}
		}

		private void StickInTarget(Collision collision, bool bSkipRayCast)
		{
			Vector3 direction = prevRotation * Vector3.forward;
			if (!bSkipRayCast)
			{
				RaycastHit[] array = Physics.RaycastAll(prevHeadPosition - prevVelocity * UnityEngine.Time.deltaTime, direction, prevVelocity.magnitude * UnityEngine.Time.deltaTime * 2f);
				bool flag = false;
				foreach (RaycastHit raycastHit in array)
				{
					if (raycastHit.collider == collision.collider)
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					return;
				}
			}
			UnityEngine.Object.Destroy(glintParticle);
			inFlight = false;
			shaftRB.velocity = Vector3.zero;
			shaftRB.angularVelocity = Vector3.zero;
			shaftRB.isKinematic = true;
			shaftRB.useGravity = false;
			shaftRB.transform.GetComponent<BoxCollider>().enabled = false;
			arrowHeadRB.velocity = Vector3.zero;
			arrowHeadRB.angularVelocity = Vector3.zero;
			arrowHeadRB.isKinematic = true;
			arrowHeadRB.useGravity = false;
			arrowHeadRB.transform.GetComponent<BoxCollider>().enabled = false;
			hitTargetSound.Play();
			scaleParentObject = new GameObject("Arrow Scale Parent");
			Transform parent = collision.collider.transform;
			ExplosionWobble component = collision.collider.gameObject.GetComponent<ExplosionWobble>();
			if (!component && (bool)parent.parent)
			{
				parent = parent.parent;
			}
			scaleParentObject.transform.parent = parent;
			base.transform.parent = scaleParentObject.transform;
			base.transform.rotation = prevRotation;
			base.transform.position = prevPosition;
			base.transform.position = collision.contacts[0].point - base.transform.forward * (0.75f - (Util.RemapNumberClamped(prevVelocity.magnitude, 0f, 10f, 0f, 0.1f) + UnityEngine.Random.Range(0f, 0.05f)));
		}

		private void OnDestroy()
		{
			if (scaleParentObject != null)
			{
				UnityEngine.Object.Destroy(scaleParentObject);
			}
		}
	}
	public class ArrowHand : UnityEngine.MonoBehaviour
	{
		private Hand hand;

		private Longbow bow;

		private GameObject currentArrow;

		public GameObject arrowPrefab;

		public Transform arrowNockTransform;

		public float nockDistance = 0.1f;

		public float lerpCompleteDistance = 0.08f;

		public float rotationLerpThreshold = 0.15f;

		public float positionLerpThreshold = 0.15f;

		private bool allowArrowSpawn = true;

		private bool nocked;

		private bool inNockRange;

		private bool arrowLerpComplete;

		public SoundPlayOneshot arrowSpawnSound;

		private AllowTeleportWhileAttachedToHand allowTeleport;

		public int maxArrowCount = 10;

		private List<GameObject> arrowList;

		private void Awake()
		{
			allowTeleport = GetComponent<AllowTeleportWhileAttachedToHand>();
			allowTeleport.teleportAllowed = true;
			allowTeleport.overrideHoverLock = false;
			arrowList = new List<GameObject>();
		}

		private void OnAttachedToHand(Hand attachedHand)
		{
			hand = attachedHand;
			FindBow();
		}

		private GameObject InstantiateArrow()
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(arrowPrefab, arrowNockTransform.position, arrowNockTransform.rotation);
			gameObject.name = "Bow Arrow";
			gameObject.transform.parent = arrowNockTransform;
			Util.ResetTransform(gameObject.transform);
			arrowList.Add(gameObject);
			while (arrowList.Count > maxArrowCount)
			{
				GameObject gameObject2 = arrowList[0];
				arrowList.RemoveAt(0);
				if ((bool)gameObject2)
				{
					UnityEngine.Object.Destroy(gameObject2);
				}
			}
			return gameObject;
		}

		private void HandAttachedUpdate(Hand hand)
		{
			if (bow == null)
			{
				FindBow();
			}
			if (bow == null)
			{
				return;
			}
			if (allowArrowSpawn && currentArrow == null)
			{
				currentArrow = InstantiateArrow();
				arrowSpawnSound.Play();
			}
			float num = Vector3.Distance(base.transform.parent.position, bow.nockTransform.position);
			if (!nocked)
			{
				if (num < rotationLerpThreshold)
				{
					float t = Util.RemapNumber(num, rotationLerpThreshold, lerpCompleteDistance, 0f, 1f);
					arrowNockTransform.rotation = Quaternion.Lerp(arrowNockTransform.parent.rotation, bow.nockRestTransform.rotation, t);
				}
				else
				{
					arrowNockTransform.localRotation = Quaternion.identity;
				}
				if (num < positionLerpThreshold)
				{
					float value = Util.RemapNumber(num, positionLerpThreshold, lerpCompleteDistance, 0f, 1f);
					value = Mathf.Clamp(value, 0f, 1f);
					arrowNockTransform.position = Vector3.Lerp(arrowNockTransform.parent.position, bow.nockRestTransform.position, value);
				}
				else
				{
					arrowNockTransform.position = arrowNockTransform.parent.position;
				}
				if (num < lerpCompleteDistance)
				{
					if (!arrowLerpComplete)
					{
						arrowLerpComplete = true;
						hand.controller.TriggerHapticPulse(500);
					}
				}
				else if (arrowLerpComplete)
				{
					arrowLerpComplete = false;
				}
				if (num < nockDistance)
				{
					if (!inNockRange)
					{
						inNockRange = true;
						bow.ArrowInPosition();
					}
				}
				else if (inNockRange)
				{
					inNockRange = false;
				}
				if (num < nockDistance && hand.controller.GetPress(8589934592uL) && !nocked)
				{
					if (currentArrow == null)
					{
						currentArrow = InstantiateArrow();
					}
					nocked = true;
					bow.StartNock(this);
					hand.HoverLock(GetComponent<Interactable>());
					allowTeleport.teleportAllowed = false;
					currentArrow.transform.parent = bow.nockTransform;
					Util.ResetTransform(currentArrow.transform);
					Util.ResetTransform(arrowNockTransform);
				}
			}
			if (nocked && (!hand.controller.GetPress(8589934592uL) || hand.controller.GetPressUp(8589934592uL)))
			{
				if (bow.pulled)
				{
					FireArrow();
				}
				else
				{
					arrowNockTransform.rotation = currentArrow.transform.rotation;
					currentArrow.transform.parent = arrowNockTransform;
					Util.ResetTransform(currentArrow.transform);
					nocked = false;
					bow.ReleaseNock();
					hand.HoverUnlock(GetComponent<Interactable>());
					allowTeleport.teleportAllowed = true;
				}
				bow.StartRotationLerp();
			}
		}

		private void OnDetachedFromHand(Hand hand)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}

		private void FireArrow()
		{
			currentArrow.transform.parent = null;
			Arrow component = currentArrow.GetComponent<Arrow>();
			component.shaftRB.isKinematic = false;
			component.shaftRB.useGravity = true;
			component.shaftRB.transform.GetComponent<BoxCollider>().enabled = true;
			component.arrowHeadRB.isKinematic = false;
			component.arrowHeadRB.useGravity = true;
			component.arrowHeadRB.transform.GetComponent<BoxCollider>().enabled = true;
			component.arrowHeadRB.AddForce(currentArrow.transform.forward * bow.GetArrowVelocity(), ForceMode.VelocityChange);
			component.arrowHeadRB.AddTorque(currentArrow.transform.forward * 10f);
			nocked = false;
			currentArrow.GetComponent<Arrow>().ArrowReleased(bow.GetArrowVelocity());
			bow.ArrowReleased();
			allowArrowSpawn = false;
			Invoke("EnableArrowSpawn", 0.5f);
			StartCoroutine(ArrowReleaseHaptics());
			currentArrow = null;
			allowTeleport.teleportAllowed = true;
		}

		private void EnableArrowSpawn()
		{
			allowArrowSpawn = true;
		}

		private IEnumerator ArrowReleaseHaptics()
		{
			yield return new WaitForSeconds(0.05f);
			hand.otherHand.controller.TriggerHapticPulse(1500);
			yield return new WaitForSeconds(0.05f);
			hand.otherHand.controller.TriggerHapticPulse(800);
			yield return new WaitForSeconds(0.05f);
			hand.otherHand.controller.TriggerHapticPulse(500);
			yield return new WaitForSeconds(0.05f);
			hand.otherHand.controller.TriggerHapticPulse(300);
		}

		private void OnHandFocusLost(Hand hand)
		{
			base.gameObject.SetActive(value: false);
		}

		private void OnHandFocusAcquired(Hand hand)
		{
			base.gameObject.SetActive(value: true);
		}

		private void FindBow()
		{
			bow = hand.otherHand.GetComponentInChildren<Longbow>();
		}
	}
	public class ArrowheadRotation : UnityEngine.MonoBehaviour
	{
		private void Start()
		{
			float x = UnityEngine.Random.Range(0f, 180f);
			base.transform.localEulerAngles = new Vector3(x, -90f, 90f);
		}
	}
	public class Balloon : UnityEngine.MonoBehaviour
	{
		public enum BalloonColor
		{
			Red,
			OrangeRed,
			Orange,
			YellowOrange,
			Yellow,
			GreenYellow,
			Green,
			BlueGreen,
			Blue,
			VioletBlue,
			Violet,
			RedViolet,
			LightGray,
			DarkGray,
			Random
		}

		private Hand hand;

		public GameObject popPrefab;

		public float maxVelocity = 5f;

		public float lifetime = 15f;

		public bool burstOnLifetimeEnd;

		public GameObject lifetimeEndParticlePrefab;

		public SoundPlayOneshot lifetimeEndSound;

		private float destructTime;

		private float releaseTime = 99999f;

		public SoundPlayOneshot collisionSound;

		private float lastSoundTime;

		private float soundDelay = 0.2f;

		private Rigidbody balloonRigidbody;

		private bool bParticlesSpawned;

		private static float s_flLastDeathSound;

		private void Start()
		{
			destructTime = UnityEngine.Time.time + lifetime + UnityEngine.Random.value;
			hand = GetComponentInParent<Hand>();
			balloonRigidbody = GetComponent<Rigidbody>();
		}

		private void Update()
		{
			if (destructTime != 0f && UnityEngine.Time.time > destructTime)
			{
				if (burstOnLifetimeEnd)
				{
					SpawnParticles(lifetimeEndParticlePrefab, lifetimeEndSound);
				}
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}

		private void SpawnParticles(GameObject particlePrefab, SoundPlayOneshot sound)
		{
			if (bParticlesSpawned)
			{
				return;
			}
			bParticlesSpawned = true;
			if (particlePrefab != null)
			{
				GameObject gameObject = UnityEngine.Object.Instantiate(particlePrefab, base.transform.position, base.transform.rotation);
				gameObject.GetComponent<ParticleSystem>().Play();
				UnityEngine.Object.Destroy(gameObject, 2f);
			}
			if (sound != null)
			{
				float num = UnityEngine.Time.time - s_flLastDeathSound;
				if (num < 0.1f)
				{
					sound.volMax *= 0.25f;
					sound.volMin *= 0.25f;
				}
				sound.Play();
				s_flLastDeathSound = UnityEngine.Time.time;
			}
		}

		private void FixedUpdate()
		{
			if (balloonRigidbody.velocity.sqrMagnitude > maxVelocity)
			{
				balloonRigidbody.velocity *= 0.97f;
			}
		}

		private void ApplyDamage()
		{
			SpawnParticles(popPrefab, null);
			UnityEngine.Object.Destroy(base.gameObject);
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (bParticlesSpawned)
			{
				return;
			}
			Hand hand = null;
			BalloonHapticBump component = collision.gameObject.GetComponent<BalloonHapticBump>();
			if (component != null && component.physParent != null)
			{
				hand = component.physParent.GetComponentInParent<Hand>();
			}
			if (UnityEngine.Time.time > lastSoundTime + soundDelay)
			{
				if (hand != null)
				{
					if (UnityEngine.Time.time > releaseTime + soundDelay)
					{
						collisionSound.Play();
						lastSoundTime = UnityEngine.Time.time;
					}
				}
				else
				{
					collisionSound.Play();
					lastSoundTime = UnityEngine.Time.time;
				}
			}
			if (!(destructTime > 0f))
			{
				if (balloonRigidbody.velocity.magnitude > maxVelocity * 10f)
				{
					balloonRigidbody.velocity = balloonRigidbody.velocity.normalized * maxVelocity;
				}
				if (this.hand != null)
				{
					ushort durationMicroSec = (ushort)Mathf.Clamp(Util.RemapNumber(collision.relativeVelocity.magnitude, 0f, 3f, 500f, 800f), 500f, 800f);
					this.hand.controller.TriggerHapticPulse(durationMicroSec);
				}
			}
		}

		public void SetColor(BalloonColor color)
		{
			GetComponentInChildren<MeshRenderer>().material.color = BalloonColorToRGB(color);
		}

		private Color BalloonColorToRGB(BalloonColor balloonColorVar)
		{
			Color result = new Color(255f, 0f, 0f);
			switch (balloonColorVar)
			{
			case BalloonColor.Red:
				return new Color(237f, 29f, 37f, 255f) / 255f;
			case BalloonColor.OrangeRed:
				return new Color(241f, 91f, 35f, 255f) / 255f;
			case BalloonColor.Orange:
				return new Color(245f, 140f, 31f, 255f) / 255f;
			case BalloonColor.YellowOrange:
				return new Color(253f, 185f, 19f, 255f) / 255f;
			case BalloonColor.Yellow:
				return new Color(254f, 243f, 0f, 255f) / 255f;
			case BalloonColor.GreenYellow:
				return new Color(172f, 209f, 54f, 255f) / 255f;
			case BalloonColor.Green:
				return new Color(0f, 167f, 79f, 255f) / 255f;
			case BalloonColor.BlueGreen:
				return new Color(108f, 202f, 189f, 255f) / 255f;
			case BalloonColor.Blue:
				return new Color(0f, 119f, 178f, 255f) / 255f;
			case BalloonColor.VioletBlue:
				return new Color(82f, 80f, 162f, 255f) / 255f;
			case BalloonColor.Violet:
				return new Color(102f, 46f, 143f, 255f) / 255f;
			case BalloonColor.RedViolet:
				return new Color(182f, 36f, 102f, 255f) / 255f;
			case BalloonColor.LightGray:
				return new Color(192f, 192f, 192f, 255f) / 255f;
			case BalloonColor.DarkGray:
				return new Color(128f, 128f, 128f, 255f) / 255f;
			case BalloonColor.Random:
			{
				int balloonColorVar2 = UnityEngine.Random.Range(0, 12);
				return BalloonColorToRGB((BalloonColor)balloonColorVar2);
			}
			default:
				return result;
			}
		}
	}
	public class BalloonColliders : UnityEngine.MonoBehaviour
	{
		public GameObject[] colliders;

		private Vector3[] colliderLocalPositions;

		private Quaternion[] colliderLocalRotations;

		private Rigidbody rb;

		private void Awake()
		{
			rb = GetComponent<Rigidbody>();
			colliderLocalPositions = new Vector3[colliders.Length];
			colliderLocalRotations = new Quaternion[colliders.Length];
			for (int i = 0; i < colliders.Length; i++)
			{
				ref Vector3 reference = ref colliderLocalPositions[i];
				reference = colliders[i].transform.localPosition;
				ref Quaternion reference2 = ref colliderLocalRotations[i];
				reference2 = colliders[i].transform.localRotation;
				colliders[i].name = base.gameObject.name + "." + colliders[i].name;
			}
		}

		private void OnEnable()
		{
			for (int i = 0; i < colliders.Length; i++)
			{
				colliders[i].transform.SetParent(base.transform);
				colliders[i].transform.localPosition = colliderLocalPositions[i];
				colliders[i].transform.localRotation = colliderLocalRotations[i];
				colliders[i].transform.SetParent(null);
				FixedJoint fixedJoint = colliders[i].AddComponent<FixedJoint>();
				fixedJoint.connectedBody = rb;
				fixedJoint.breakForce = float.PositiveInfinity;
				fixedJoint.breakTorque = float.PositiveInfinity;
				fixedJoint.enableCollision = false;
				fixedJoint.enablePreprocessing = true;
				colliders[i].SetActive(value: true);
			}
		}

		private void OnDisable()
		{
			for (int i = 0; i < colliders.Length; i++)
			{
				if (colliders[i] != null)
				{
					UnityEngine.Object.Destroy(colliders[i].GetComponent<FixedJoint>());
					colliders[i].SetActive(value: false);
				}
			}
		}

		private void OnDestroy()
		{
			for (int i = 0; i < colliders.Length; i++)
			{
				UnityEngine.Object.Destroy(colliders[i]);
			}
		}
	}
	public class BalloonHapticBump : UnityEngine.MonoBehaviour
	{
		public GameObject physParent;

		private void OnCollisionEnter(Collision other)
		{
			Balloon componentInParent = other.collider.GetComponentInParent<Balloon>();
