		[StructLayout((LayoutKind)2)]
		private struct GetComponentStateUnion
		{
			[FieldOffset(0)]
			public IVRRenderModels._GetComponentState pGetComponentState;

			[FieldOffset(0)]
			public _GetComponentStatePacked pGetComponentStatePacked;
		}

