[RequireComponent(typeof(UnityEngine.UI.Image))]
public class DragMe : UnityEngine.MonoBehaviour, IBeginDragHandler, IDragHandler, IEndDragHandler, IEventSystemHandler
{
	public bool dragOnSurfaces = true;

	private GameObject m_DraggingIcon;

	private RectTransform m_DraggingPlane;

	public void OnBeginDrag(PointerEventData eventData)
	{
		Canvas canvas = FindInParents<Canvas>(base.gameObject);
		if (!(canvas == null))
		{
			m_DraggingIcon = new GameObject("icon");
			m_DraggingIcon.transform.SetParent(canvas.transform, worldPositionStays: false);
			m_DraggingIcon.transform.SetAsLastSibling();
			UnityEngine.UI.Image image = m_DraggingIcon.AddComponent<UnityEngine.UI.Image>();
			CanvasGroup canvasGroup = m_DraggingIcon.AddComponent<CanvasGroup>();
			canvasGroup.blocksRaycasts = false;
			image.sprite = GetComponent<UnityEngine.UI.Image>().sprite;
			image.SetNativeSize();
			if (dragOnSurfaces)
			{
				m_DraggingPlane = base.transform as RectTransform;
			}
			else
			{
				m_DraggingPlane = canvas.transform as RectTransform;
			}
			SetDraggedPosition(eventData);
		}
	}

	public void OnDrag(PointerEventData data)
	{
		if (m_DraggingIcon != null)
		{
			SetDraggedPosition(data);
		}
	}

	private void SetDraggedPosition(PointerEventData data)
	{
		if (dragOnSurfaces && data.pointerEnter != null && data.pointerEnter.transform as RectTransform != null)
		{
			m_DraggingPlane = data.pointerEnter.transform as RectTransform;
		}
		RectTransform component = m_DraggingIcon.GetComponent<RectTransform>();
		if (RectTransformUtility.ScreenPointToWorldPointInRectangle(m_DraggingPlane, data.position, data.pressEventCamera, out var worldPoint))
		{
			component.position = worldPoint;
			component.rotation = m_DraggingPlane.rotation;
		}
	}

	public void OnEndDrag(PointerEventData eventData)
	{
		if (m_DraggingIcon != null)
		{
			UnityEngine.Object.Destroy(m_DraggingIcon);
		}
	}

	public static T FindInParents<T>(GameObject go) where T : UnityEngine.Component
	{
		if (go == null)
		{
			return (T)null;
		}
		T component = go.GetComponent<T>();
		if (component != null)
		{
			return component;
		}
		Transform parent = go.transform.parent;
		while (parent != null && component == null)
		{
			component = parent.gameObject.GetComponent<T>();
			parent = parent.parent;
		}
		return component;
	}
}
public class DragPanel : UnityEngine.MonoBehaviour, IPointerDownHandler, IDragHandler, IEventSystemHandler
{
	private Vector2 originalLocalPointerPosition;

	private Vector3 originalPanelLocalPosition;

	private RectTransform panelRectTransform;

	private RectTransform parentRectTransform;

	private void Awake()
	{
		panelRectTransform = base.transform.parent as RectTransform;
		parentRectTransform = panelRectTransform.parent as RectTransform;
	}

	public void OnPointerDown(PointerEventData data)
	{
		originalPanelLocalPosition = panelRectTransform.localPosition;
		RectTransformUtility.ScreenPointToLocalPointInRectangle(parentRectTransform, data.position, data.pressEventCamera, out originalLocalPointerPosition);
	}

	public void OnDrag(PointerEventData data)
	{
		if (!(panelRectTransform == null) && !(parentRectTransform == null))
		{
			if (RectTransformUtility.ScreenPointToLocalPointInRectangle(parentRectTransform, data.position, data.pressEventCamera, out var localPoint))
			{
				Vector3 vector = localPoint - originalLocalPointerPosition;
				panelRectTransform.localPosition = originalPanelLocalPosition + vector;
			}
			ClampToWindow();
		}
	}

	private void ClampToWindow()
	{
		Vector3 localPosition = panelRectTransform.localPosition;
		Vector3 vector = parentRectTransform.rect.min - panelRectTransform.rect.min;
		Vector3 vector2 = parentRectTransform.rect.max - panelRectTransform.rect.max;
		localPosition.x = Mathf.Clamp(panelRectTransform.localPosition.x, vector.x, vector2.x);
		localPosition.y = Mathf.Clamp(panelRectTransform.localPosition.y, vector.y, vector2.y);
		panelRectTransform.localPosition = localPosition;
	}
}
public class DropMe : UnityEngine.MonoBehaviour, IDropHandler, IPointerEnterHandler, IPointerExitHandler, IEventSystemHandler
{
	public UnityEngine.UI.Image containerImage;

	public UnityEngine.UI.Image receivingImage;

	private Color normalColor;

	public Color highlightColor = Color.yellow;

	public void OnEnable()
	{
		if (containerImage != null)
		{
			normalColor = containerImage.color;
		}
	}

	public void OnDrop(PointerEventData data)
	{
		containerImage.color = normalColor;
		if (!(receivingImage == null))
		{
			Sprite dropSprite = GetDropSprite(data);
			if (dropSprite != null)
			{
				receivingImage.overrideSprite = dropSprite;
			}
		}
	}

	public void OnPointerEnter(PointerEventData data)
	{
		if (!(containerImage == null))
		{
			Sprite dropSprite = GetDropSprite(data);
			if (dropSprite != null)
			{
				containerImage.color = highlightColor;
			}
		}
	}

	public void OnPointerExit(PointerEventData data)
	{
		if (!(containerImage == null))
		{
			containerImage.color = normalColor;
		}
	}

	private Sprite GetDropSprite(PointerEventData data)
	{
		GameObject pointerDrag = data.pointerDrag;
		if (pointerDrag == null)
		{
			return null;
		}
		UnityEngine.UI.Image component = pointerDrag.GetComponent<UnityEngine.UI.Image>();
		if (component == null)
		{
			return null;
		}
		return component.sprite;
	}
}
public class PanelManager : UnityEngine.MonoBehaviour
{
	public Animator initiallyOpen;

	private int m_OpenParameterId;

	private Animator m_Open;

	private GameObject m_PreviouslySelected;

	private const string k_OpenTransitionName = "Open";

	private const string k_ClosedStateName = "Closed";

	public void OnEnable()
	{
		m_OpenParameterId = Animator.StringToHash("Open");
		if (!(initiallyOpen == null))
		{
			OpenPanel(initiallyOpen);
		}
	}

	public void OpenPanel(Animator anim)
	{
		if (!(m_Open == anim))
		{
			anim.gameObject.SetActive(value: true);
			GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
			anim.transform.SetAsLastSibling();
			CloseCurrent();
			m_PreviouslySelected = currentSelectedGameObject;
			m_Open = anim;
			m_Open.SetBool(m_OpenParameterId, value: true);
			GameObject selected = FindFirstEnabledSelectable(anim.gameObject);
			SetSelected(selected);
		}
	}

	private static GameObject FindFirstEnabledSelectable(GameObject gameObject)
	{
		GameObject result = null;
		Selectable[] componentsInChildren = gameObject.GetComponentsInChildren<Selectable>(includeInactive: true);
		Selectable[] array = componentsInChildren;
		foreach (Selectable selectable in array)
		{
			if (selectable.IsActive() && selectable.IsInteractable())
			{
				result = selectable.gameObject;
				break;
			}
		}
		return result;
	}

	public void CloseCurrent()
	{
		if (!(m_Open == null))
		{
			m_Open.SetBool(m_OpenParameterId, value: false);
			SetSelected(m_PreviouslySelected);
			StartCoroutine(DisablePanelDeleyed(m_Open));
			m_Open = null;
		}
	}

	private IEnumerator DisablePanelDeleyed(Animator anim)
	{
		bool closedStateReached = false;
		bool wantToClose = true;
		while (!closedStateReached && wantToClose)
		{
			if (!anim.IsInTransition(0))
			{
				closedStateReached = anim.GetCurrentAnimatorStateInfo(0).IsName("Closed");
			}
			wantToClose = !anim.GetBool(m_OpenParameterId);
			yield return new WaitForEndOfFrame();
		}
		if (wantToClose)
		{
			anim.gameObject.SetActive(value: false);
		}
	}

	private void SetSelected(GameObject go)
	{
		EventSystem.current.SetSelectedGameObject(go);
		StandaloneInputModule standaloneInputModule = EventSystem.current.currentInputModule as StandaloneInputModule;
		if (!(standaloneInputModule != null))
		{
			EventSystem.current.SetSelectedGameObject(null);
		}
	}
}
public class ResizePanel : UnityEngine.MonoBehaviour, IPointerDownHandler, IDragHandler, IEventSystemHandler
{
	public Vector2 minSize = new Vector2(100f, 100f);

	public Vector2 maxSize = new Vector2(400f, 400f);

	private RectTransform panelRectTransform;

	private Vector2 originalLocalPointerPosition;

	private Vector2 originalSizeDelta;

	private void Awake()
	{
		panelRectTransform = base.transform.parent.GetComponent<RectTransform>();
	}

	public void OnPointerDown(PointerEventData data)
	{
		originalSizeDelta = panelRectTransform.sizeDelta;
		RectTransformUtility.ScreenPointToLocalPointInRectangle(panelRectTransform, data.position, data.pressEventCamera, out originalLocalPointerPosition);
	}

	public void OnDrag(PointerEventData data)
	{
		if (!(panelRectTransform == null))
		{
			RectTransformUtility.ScreenPointToLocalPointInRectangle(panelRectTransform, data.position, data.pressEventCamera, out var localPoint);
			Vector3 vector = localPoint - originalLocalPointerPosition;
			Vector2 vector2 = originalSizeDelta + new Vector2(vector.x, 0f - vector.y);
			vector2 = new Vector2(Mathf.Clamp(vector2.x, minSize.x, maxSize.x), Mathf.Clamp(vector2.y, minSize.y, maxSize.y));
			panelRectTransform.sizeDelta = vector2;
		}
	}
}
