namespace RecRoom.Tools.Weapons
{
	public class BeamTrap : Trap
	{
		[Header("Beam")]
		[SerializeField]
		private Transform origin;

		[SerializeField]
		private Transform beam;

		[SerializeField]
		private PooledParticle impactParticlePrefab;

		private PooledParticle impactParticles;

		[SerializeField]
		private PooledParticle emberParticlePrefab;

		private PooledParticle emberParticles;

		[SerializeField]
		private float beamLength = 15f;

		[SerializeField]
		private float beamWidth = 0.25f;

		[SerializeField]
		private float beamExtendLerpSpeed = 10f;

		[Tooltip("This is a multiplier over time (set to repeat)")]
		public AnimationCurve BeamWidthNoise;

		public RecRoomAudioClip FireLoop;

		public RecRoomAudioClip ImpactSFX;

		private SFXAudioSource activeLoopAudio;

		protected override void Awake()
		{
			base.Awake();
		}

		protected override void Start()
		{
			base.Start();
			impactParticles = ObjectPool.Instance.Acquire(impactParticlePrefab);
			this.Update30hz(StaggeredUpdate);
		}

		protected void OnEnable()
		{
			activeLoopAudio = AudioManager.StartLooping3DSFX(FireLoop, origin);
		}

		protected void OnDisable()
		{
			AudioManager.StopLoopingSFX(activeLoopAudio);
		}

		private void StaggeredUpdate(float deltaTime)
		{
			float num = beamWidth;
			float distance = beamLength;
			num *= BeamWidthNoise.Evaluate(UnityEngine.Time.time);
			if (Physics.SphereCast(origin.position, beamWidth / 2f, origin.forward, out var hitInfo, beamLength, 362036736))
			{
				distance = hitInfo.distance;
				impactParticles.PrimaryParticleSystem.Play();
				impactParticles.transform.SetPositionAndRotation(hitInfo.point, Quaternion.LookRotation(hitInfo.normal));
				AudioManager.Play3DSFX(ImpactSFX, hitInfo.point);
				Player player = null;
				if ((player = hitInfo.collider.GetColliderPlayer(out var bodyPart)) != null)
				{
					WeaponImpact impact = new WeaponImpact
					{
						Velocity = Vector3.zero,
						Force = Vector3.zero,
						GameObject = ((!(hitInfo.rigidbody != null)) ? hitInfo.collider.gameObject : hitInfo.rigidbody.gameObject),
						Point = hitInfo.point,
						Distance = 0f,
						SurfaceNormal = hitInfo.normal,
						PreAttackChargeAmount = 1f
					};
					PlayerHit(player, bodyPart, impact);
				}
				Tool tool = null;
				if ((tool = hitInfo.collider.GetColliderTool()) != null)
				{
					WeaponImpact impact2 = new WeaponImpact
					{
						Velocity = Vector3.zero,
						Force = Vector3.zero,
						GameObject = ((!(hitInfo.rigidbody != null)) ? hitInfo.collider.gameObject : hitInfo.rigidbody.gameObject),
						Point = hitInfo.point,
						Distance = 0f,
						SurfaceNormal = hitInfo.normal,
						PreAttackChargeAmount = 1f
					};
					ToolHit(tool, impact2);
				}
				EnemyArmorType hitEnemyArmorType;
				Enemy colliderEnemy = hitInfo.collider.GetColliderEnemy(out hitEnemyArmorType);
				if (colliderEnemy != null)
				{
					WeaponImpact impact3 = new WeaponImpact
					{
						Velocity = Vector3.zero,
						Force = Vector3.zero,
						GameObject = ((!(hitInfo.rigidbody != null)) ? hitInfo.collider.gameObject : hitInfo.rigidbody.gameObject),
						Point = hitInfo.point,
						Distance = 0f,
						SurfaceNormal = hitInfo.normal,
						PreAttackChargeAmount = 1f
					};
					EnemyHit(colliderEnemy, hitEnemyArmorType, WeaponDamageType.MELEE, impact3);
					return;
				}
			}
			distance = ((!(beam.localScale.z > distance)) ? Mathf.Lerp(beam.localScale.z, distance, deltaTime * beamExtendLerpSpeed) : distance);
			beam.localScale = new Vector3(beamWidth * num, beamWidth * num, distance);
			beam.localPosition = Vector3.forward * beam.localScale.z / 2f;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if ((bool)emberParticles)
			{
				emberParticles.Stop();
			}
			if ((bool)activeLoopAudio)
			{
				AudioManager.StopLoopingSFX(activeLoopAudio);
			}
			if ((bool)impactParticles)
			{
				impactParticles.Stop();
			}
		}
	}
}
public class EulaScreen : UnityEngine.MonoBehaviour
{
	private const string noticeText = "<b>This game requires a free Rec Room cloud profile. If this is your first time playing, a new profile will be created and linked to your PSN account.</b>";

	public Transform exitPanel;

	public UnityEngine.UI.Image fadeImage;

	public float fadeSeconds = 1f;

	public Text textObject;

	public TextAsset textAsset;

	public UnityEngine.UI.Button acceptButton;

	public UnityEngine.UI.Button declineButton;

	public UnityEngine.UI.Button pageUpButton;

	public UnityEngine.UI.Button pageDownButton;

	private bool hasAccepted;

	private bool listenForInput;

	private int startingCharacterIndex;

	private Stack<int> pageStack = new Stack<int>();

	private string fullText;

	private void Start()
	{
		exitPanel.gameObject.SetActive(value: false);
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append("<b>This game requires a free Rec Room cloud profile. If this is your first time playing, a new profile will be created and linked to your PSN account.</b>");
		stringBuilder.Append("\n\n");
		string value = Encoding.ASCII.GetString(textAsset.bytes);
		stringBuilder.Append(value);
		fullText = stringBuilder.ToString();
		fadeImage.color = Color.black;
		textObject.text = fullText;
		RefreshPageButtons();
	}

	private void Update()
	{
		if (listenForInput)
		{
		}
	}

	public IEnumerator Show()
	{
		yield return FadeIn();
		listenForInput = true;
		float timeStarted = UnityEngine.Time.realtimeSinceStartup;
		while (!hasAccepted)
		{
			float timeWaiting = UnityEngine.Time.realtimeSinceStartup - timeStarted;
			yield return new WaitForSeconds(0.1f);
		}
		yield return FadeOut();
	}

	private IEnumerator FadeIn()
	{
		fadeImage.CrossFadeAlpha(0f, fadeSeconds, ignoreTimeScale: true);
		yield return new WaitForSeconds(fadeSeconds);
	}

	private IEnumerator FadeOut()
	{
		fadeImage.CrossFadeAlpha(1f, fadeSeconds, ignoreTimeScale: true);
		yield return new WaitForSeconds(fadeSeconds);
	}

	[SkipRename]
	public void Button_Accept()
	{
		Console.WriteLine("Player accepted the EULA Screen");
		listenForInput = false;
		hasAccepted = true;
	}

	[SkipRename]
	public void Button_Decline()
	{
		Console.WriteLine("Player declined the EULA Screen");
		listenForInput = false;
		ExitApplication();
	}

	[SkipRename]
	public void Button_PageUp()
	{
		if (pageStack.Count > 0)
		{
			startingCharacterIndex = pageStack.Pop();
			textObject.text = fullText.Substring(startingCharacterIndex);
			RefreshPageButtons();
		}
	}

	[SkipRename]
	public void Button_PageDown()
	{
		int characterCountVisible = textObject.cachedTextGenerator.characterCountVisible;
		if (fullText.Length > startingCharacterIndex + characterCountVisible)
		{
			pageStack.Push(startingCharacterIndex);
			startingCharacterIndex += characterCountVisible;
			textObject.text = fullText.Substring(startingCharacterIndex);
			RefreshPageButtons();
		}
	}

	private void RefreshPageButtons()
	{
		pageUpButton.interactable = pageStack.Count > 0;
		int characterCountVisible = textObject.cachedTextGenerator.characterCountVisible;
		pageDownButton.interactable = fullText.Length > startingCharacterIndex + characterCountVisible;
	}

	private void Click(UnityEngine.UI.Button button)
	{
		StartCoroutine(RunClickButton(button));
	}

	private IEnumerator RunClickButton(UnityEngine.UI.Button button)
	{
		PointerEventData pointer = new PointerEventData(EventSystem.current);
		ExecuteEvents.Execute(button.gameObject, pointer, ExecuteEvents.pointerEnterHandler);
		ExecuteEvents.Execute(button.gameObject, pointer, ExecuteEvents.pointerDownHandler);
		yield return new WaitForSeconds(0.2f);
		ExecuteEvents.Execute(button.gameObject, pointer, ExecuteEvents.pointerUpHandler);
		ExecuteEvents.Execute(button.gameObject, pointer, ExecuteEvents.pointerClickHandler);
	}

	private void ExitApplication()
	{
		UnityEngine.Application.Quit();
	}
}
