namespace RecRoom
{
	public class PlayerFlyIndicator : UnityEngine.MonoBehaviour
	{
		private const float Alpha = 0.5f;

		private static readonly int ChargePropertyID = Shader.PropertyToID("_Charge");

		private static readonly int TintColorPropertyID = Shader.PropertyToID("_TintColor");

		private Material material;

		private LaserTeleporter laserTeleporter;

		private float charge;

		public float Charge
		{
			get
			{
				return charge;
			}
			set
			{
				if (charge != value)
				{
					charge = value;
					Refresh();
				}
			}
		}

		private void Start()
		{
			material = GetComponentInChildren<Renderer>().material;
			laserTeleporter = GetComponentInParent<PlayerHand>().PlayerHandRemote;
			if (laserTeleporter != null)
			{
				LaserTeleporter obj = laserTeleporter;
				obj.LaserColorChanged = (Action<Color?>)Delegate.Combine(obj.LaserColorChanged, new Action<Color?>(OnLaserColorChanged));
			}
			Refresh();
		}

		private void OnDestroy()
		{
			if (laserTeleporter != null)
			{
				LaserTeleporter obj = laserTeleporter;
				obj.LaserColorChanged = (Action<Color?>)Delegate.Remove(obj.LaserColorChanged, new Action<Color?>(OnLaserColorChanged));
			}
		}

		private void OnLaserColorChanged(Color? color)
		{
			Refresh();
		}

		private void Refresh()
		{
			material.SetFloat(ChargePropertyID, charge);
			if (laserTeleporter != null)
			{
				Color? laserColor = laserTeleporter.LaserColor;
				Color value = ((!laserColor.HasValue) ? ParabolicPointer.DefaultLaserColor.Value : laserColor.Value);
				value.a = 0.5f;
				material.SetColor(TintColorPropertyID, value);
			}
			base.gameObject.SetActive(charge != 0f);
		}
	}
}
