		private void OnEnable()
		{
			UpdateUIElements();
		}

		public override void UpdateUIElements()
		{
			if (!(ShareCamera == null))
			{
				ShareCamera.ShareCamState currentState = ShareCamera.CurrentState;
				bool flag = SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR;
				screenButton.interactable = currentState == ShareCamera.ShareCamState.ACTIVE;
				settingsButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.ACTIVE);
				closeButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.ACTIVE);
				takePhotoButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.ACTIVE);
				backCameraToggle.gameObject.SetActive(currentState == ShareCamera.ShareCamState.ACTIVE);
				tripodToggle.gameObject.SetActive(currentState == ShareCamera.ShareCamState.ACTIVE);
				backCameraToggle.IsOn = !ShareCamera.BackCameraIsActive;
				tripodToggle.IsOn = ShareCamera.TripodIsActive;
				backButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.PREVIEW);
				profileButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.PREVIEW);
				printButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.PREVIEW && flag);
				shareButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.PREVIEW);
				profilePhotoFrame.gameObject.SetActive(currentState == ShareCamera.ShareCamState.CONFIRM_PROFILE);
				confirmButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.CONFIRM_PROFILE);
				cancelButton.gameObject.SetActive(currentState == ShareCamera.ShareCamState.CONFIRM_PROFILE);
				UpdateButtons();
			}
		}

		private void UpdateButtons(bool disableAll = false)
		{
			if (!(ShareCamera == null))
			{
				bool flag = Profiles.LocalProfile != null && Profiles.LocalProfile.Verified;
				takePhotoButton.Interactable = !disableAll && !ShareCamera.IsPrintingPolaroid;
				PhotonPlayer photonPlayer = ShareCamera.Tool.PlayerSpawnedEquipment.SpawningPlayer.PhotonPlayer;
				printButton.Interactable = !disableAll && ShareCamera.CurrentMode == ShareCamera.ShareCamMode.PNG && !ShareCamera.IsPrintingPolaroid && !ShareCamera.HasPrintedPolaroid && (photonPlayer == null || !NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized || PlayerRoomRoleManager.Instance.GetPlayerRoleDefinition(photonPlayer).CanPrintPhotos.Value);
				profileButton.Interactable = !disableAll && ShareCamera.CurrentMode == ShareCamera.ShareCamMode.PNG && !ShareCamera.IsPrintingPolaroid && !ShareCamera.HasChangedProfilePic && flag;
				shareButton.Interactable = !disableAll && ShareCamera.CurrentMode == ShareCamera.ShareCamMode.PNG && !ShareCamera.IsPrintingPolaroid && !ShareCamera.HasSharedOnRecNet && flag;
				tripodToggle.Interactable = !disableAll;
				backCameraToggle.Interactable = !disableAll;
			}
		}

