		{
			ShareCamera = shareCam;
			ShareCamera.ScreenRenderEvent += ShareCamera_ScreenRenderEvent;
			ShareCamera.FeedbackTextEvent += ShareCamera_FeedbackTextEvent;
			ShareCamera.RefreshUIEvent += UpdateUIElements;
