			Tool.PostPickupEvent -= Tool_PostPickupEvent;
			Tool.PostReleaseEvent -= Tool_PostReleaseEvent;
			Tool.RigidbodyEx.SleepChangedEvent -= RigidbodyEx_SleepChangedEvent;
			Tool.CreationObject.LockedStatusChangedEvent -= CreationObject_LockedStatusChangedEvent;
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			playerIdsToRemoveFromMap.Clear();
			foreach (KeyValuePair<int, Costume> item in playerToCostumeMap)
			{
				if (item.Value == this)
				{
					playerIdsToRemoveFromMap.Add(item.Key);
				}
			}
			foreach (int item2 in playerIdsToRemoveFromMap)
			{
				playerToCostumeMap.Remove(item2);
			}
		}

		protected virtual bool IsUIAvailable()
		{
			return true;
		}

		protected void RefreshUIAvailability()
		{
			if (IsUIAvailable())
			{
				if (uiInstance == null)
				{
					uiPivot.enabled = true;
					uiInstance = UnityEngine.Object.Instantiate(uiPrefab, uiRoot, worldPositionStays: false);
					uiInstance.GetComponent<CostumeStackedUI>().costume = this;
					uiInstance.gameObject.SetActive(value: false);
				}
			}
			else
			{
				if (uiInstance != null)
				{
					UnityEngine.Object.Destroy(uiInstance.gameObject);
				}
				uiPivot.enabled = false;
			}
		}

		private void UpdateUIVisibility()
		{
			if (uiInstance == null)
			{
				IsUIVisible = false;
				return;
			}
			if (Tool.IsHeld || !Tool.RigidbodyEx.IsSleeping() || (Player.LocalPlayerExists && Vector3.Distance(Player.LocalPlayer.CurrentFloorPosition, base.transform.position) >= uiHideDistance) || !IsDummyUpright)
			{
				IsUIVisible = false;
			}
			else
			{
				IsUIVisible = true;
			}
			uiInstance.gameObject.SetActive(IsUIVisible);
		}

		private void TryShowBaseUIFlow()
		{
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: true);
				uiInstance.PopAllFlows();
			}
		}

		private CostumeUIFlow TryShowUIFlow<V>() where V : CostumeUIFlow
		{
			CostumeUIFlow result = null;
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: true);
				uiInstance.PopAllFlows();
				uiInstance.PushFlow<V>();
				result = uiInstance.CurrentFlow as CostumeUIFlow;
			}
			return result;
		}

		private void TryHideUI()
		{
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: false);
			}
		}

		private void Tool_HolderChangedEvent(Tool thisTool)
		{
			RefreshIsReadyToEquip();
			UpdateUIVisibility();
		}

		private void Tool_PostPickupEvent(Tool thisTool)
		{
			UpdateUIVisibility();
		}

		private void RigidbodyEx_SleepChangedEvent(RigidbodyEx obj)
		{
			UpdateUIVisibility();
		}

		private void Tool_PostReleaseEvent(Tool thisTool)
		{
			UpdateUIVisibility();
		}

		private void CreationObject_LockedStatusChangedEvent(CreationObject obj)
		{
			RefreshIsReadyToEquip();
		}

		private ShapeContainer CreationObject_CustomShapeContainerGetter(Collider collider)
		{
			ShapeContainer componentInParent = collider.GetComponentInParent<ShapeContainer>();
			if (componentInParent != null)
			{
				return componentInParent;
			}
			CostumePiece componentInParent2 = collider.GetComponentInParent<CostumePiece>();
			if (componentInParent2 != null)
			{
				return componentInParent2.VisualShapeContainer;
			}
			return null;
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient && player == EquippedPlayer)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					MasterUnequip();
				});
			}
		}

		private void ToolHighlightingOverride()
		{
			Tool.RenderOutline();
			if (IsEquipped)
			{
				return;
			}
			foreach (CostumePiece costumePiece in costumePieces)
			{
				costumePiece.RenderVisualsOutline(Tool.OutlineType);
			}
		}

		public void RequestEquipToPlayer(Player player)
		{
			if (player != null && IsReadyToEquip)
			{
				base.photonView.RpcMaster(RpcMasterRequestEquipToPlayer, player.PhotonPlayer);
			}
		}

		public void RequestUnequip()
		{
			base.photonView.RpcMaster(RpcMasterRequestUnequip);
		}

		public void RefreshIsReadyToEquip()
		{
			bool flag = true;
			foreach (CostumePiece costumePiece in costumePieces)
			{
				if (!costumePiece.IsReadyToEquip)
				{
					flag = false;
					break;
				}
			}
			IsReadyToEquip = flag && !IsEquipped && !Tool.IsHeld && !Tool.CreationObject.IsLocked;
		}

		[PunRPC]
		private void RpcMasterRequestEquipToPlayer(PhotonPlayer photonPlayer)
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterEquipToPhotonPlayer(photonPlayer);
			}
		}

		[PunRPC]
		private void RpcMasterRequestUnequip()
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterUnequip();
			}
		}

		private void MasterEquipToPhotonPlayer(PhotonPlayer photonPlayer)
		{
			if (PhotonNetwork.isMasterClient && IsReadyToEquip)
			{
				equippedPlayerId.Set(photonPlayer.ID);
			}
		}

		private void MasterUnequip()
		{
			if (PhotonNetwork.isMasterClient)
			{
				equippedPlayerId.Set(PhotonPlayer.Invalid);
			}
		}

		private void MasterSetCircuitOutput()
		{
			if (PhotonNetwork.isMasterClient)
			{
				continuousSourceNodeDisplay.SetOutput(equippedPlayerId.Get());
			}
		}

		private void OnEquippedPlayerChanged(bool suppressSFX = false)
		{
			if (EquippedPlayer != null)
			{
				HeadPiece.MasterEquip(EquippedPlayer.ToPlayer().Head.PropAnchorView);
				TorsoPiece.MasterEquip(EquippedPlayer.ToPlayer().Body.PhotonView);
				LeftHandPiece.MasterEquip(EquippedPlayer.ToPlayer().LeftHand.photonView);
				RightHandPiece.MasterEquip(EquippedPlayer.ToPlayer().RightHand.photonView);
				if (Player.LocalPlayerExists && EquippedPlayer == PhotonNetwork.player && !SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
				{
					HeadPiece.EnableIgnoreVisualTool(Player.LocalPlayer);
				}
				if (PhotonNetwork.isMasterClient && playerToCostumeMap.ContainsKey(equippedPlayerId.Get()))
				{
					Costume costume = playerToCostumeMap[equippedPlayerId.Get()];
					if (costume != null)
					{
						costume.RequestUnequip();
					}
				}
				playerToCostumeMap[equippedPlayerId.Get()] = this;
				MasterSetCircuitOutput();
				if (!suppressSFX && equipSound != null)
				{
					AudioManager.Play3DSFX(equipSound, EquippedPlayer.ToPlayer().Head.transform, sfxVolume);
				}
				if (this.EquipEvent != null)
				{
					this.EquipEvent(this);
				}
			}
			else
			{
				foreach (CostumePiece costumePiece in costumePieces)
				{
					costumePiece.MasterUnEquip();
				}
				HeadPiece.DisableIgnoreVisualTool();
				playerIdsToRemoveFromMap.Clear();
				foreach (KeyValuePair<int, Costume> item in playerToCostumeMap)
				{
					if (item.Value == this)
					{
						playerIdsToRemoveFromMap.Add(item.Key);
					}
				}
				if (playerIdsToRemoveFromMap.Count > 1)
				{
					UnityEngine.Debug.LogWarning("Costume was equipped by multiple players, this shouldn't happen.");
				}
				foreach (int item2 in playerIdsToRemoveFromMap)
				{
					playerToCostumeMap.Remove(item2);
				}
				MasterSetCircuitOutput();
				if (!suppressSFX && unequipSound != null)
				{
					AudioManager.Play3DSFX(unequipSound, base.transform, sfxVolume);
				}
				if (this.UnequipEvent != null)
				{
					this.UnequipEvent(this);
				}
			}
			RefreshIsReadyToEquip();
		}
	}
	public class CostumePiece : UnityEngine.MonoBehaviour
	{
		private const float VISUAL_TOOL_IGNORE_FADE_START_DISTANCE = 0.5f;

		private const float VISUAL_TOOL_IGNORE_FADE_COMPLETE_DISTANCE = 0.05f;

		[SerializeField]
		[FormerlySerializedAs("pieceName")]
		private string friendlyName;

		[SerializeField]
		private Renderer highlightRenderer;

		[SerializeField]
		private Tool _visualTool;

		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private Costume parentCostume;

		private Vector3 visualsDummySpacePosition;

		private Quaternion visualsDummySpaceRotation;

		private float visualsDummySpaceScale;

		private Vector3 visualsBodySpacePosition;

		private float visualsBodySpaceScale;

		private Quaternion visualsBodySpaceRotation;

		private DecorationShapeContainer visualShapeContainer;

		public string FriendlyName
		{
			[CompilerGenerated]
			get
			{
				return friendlyName;
			}
		}

		public Tool VisualTool
		{
			[CompilerGenerated]
			get
			{
				return _visualTool;
			}
		}

		public Costume ParentCostume
		{
			[CompilerGenerated]
			get
			{
				return parentCostume;
			}
		}

		public DecorationShapeContainer VisualShapeContainer
		{
			[CompilerGenerated]
			get
			{
				return visualShapeContainer;
			}
		}

		public int SandboxResourceCost
		{
			get
			{
				if (visualShapeContainer != null)
				{
					return visualShapeContainer.SandboxResourceCost;
				}
				UnityEngine.Debug.LogErrorFormat(this, "Unable to calculate resource cost for costume piece {0}: No extrusion found!", this);
				return 0;
			}
		}

		public bool IsReadyToEquip => !visualShapeContainer.HasOutOfBoundsShapes.Value;

		private void Awake()
		{
			if (parentCostume == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing costume reference.");
			}
			else
			{
				visualsDummySpacePosition = parentCostume.transform.InverseTransformPoint(VisualTool.transform.position);
				visualsDummySpaceRotation = parentCostume.transform.InverseTransformRotation(VisualTool.transform.rotation);
				visualsDummySpaceScale = parentCostume.transform.InverseTransformLossyUniformScale(VisualTool.transform.GetLossyUniformScale());
			}
			visualsBodySpacePosition = base.transform.InverseTransformPoint(VisualTool.transform.position);
			visualsBodySpaceRotation = base.transform.InverseTransformRotation(VisualTool.transform.rotation);
			visualsBodySpaceScale = base.transform.InverseTransformLossyUniformScale(VisualTool.transform.GetLossyUniformScale());
			VisualTool.PostResetEvent += OnVisualToolReset;
			VisualTool.CanBeIgnored = true;
			visualShapeContainer = VisualTool.GetComponentInParent<DecorationShapeContainer>();
			if (visualShapeContainer != null)
			{
				visualShapeContainer.HasOutOfBoundsShapes.Observe(this, VisualExtrusion_HasOutOfBoundsSubExtrusionsChanged);
			}
		}

		private void OnDestroy()
		{
			VisualTool.PostResetEvent -= OnVisualToolReset;
		}

		public void MasterEquip(PhotonView photonView)
		{
			MasterAttachToPlayer(photonView);
		}

		public void MasterUnEquip()
		{
			MasterAttachToCostumeDummy();
		}

		public void EnableIgnoreVisualTool(Player ignoringPlayer)
		{
			VisualTool.SetCustomIgnoredSettings(new Tool.CustomIgnoreSettings
			{
				FadeCenter = ignoringPlayer.Head.transform,
				FadeStartDistance = 0.5f,
				FadeCompleteDistance = 0.05f
			});
		}

		public void DisableIgnoreVisualTool()
		{
			VisualTool.ClearCustomIgnoredSettings();
		}

		private void MasterAttachToPlayer(PhotonView photonView)
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!VisualTool.hasAuthority)
				{
					VisualTool.photonView.TransferOwnership(PhotonNetwork.player);
				}
				if (VisualTool.hasAuthority)
				{
					VisualTool.AuthorityEquipToPlayer(photonView, visualsBodySpacePosition, visualsBodySpaceRotation, visualsBodySpaceScale);
					VisualTool.ManagesOwnIgnoreState = true;
				}
			}
		}

		private void MasterAttachToCostumeDummy(bool force = false)
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!VisualTool.hasAuthority)
				{
					VisualTool.photonView.TransferOwnership(PhotonNetwork.player);
				}
				if (VisualTool.hasAuthority && parentCostume != null && (force || VisualTool.HolderView != parentCostume.photonView))
				{
					VisualTool.AuthorityAttachToObject(parentCostume.photonView, visualsDummySpacePosition, visualsDummySpaceRotation, visualsDummySpaceScale);
					VisualTool.ManagesOwnIgnoreState = false;
				}
			}
		}

		private void OnVisualToolReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			UnityEngine.Debug.LogErrorFormat("Resetting CostumePiece subtool {0}. Subtools generally shouldn't be manually reset.", this);
			MasterAttachToCostumeDummy();
		}

		private void VisualExtrusion_HasOutOfBoundsSubExtrusionsChanged(bool outOfBounds)
		{
			if (parentCostume != null)
			{
				parentCostume.RefreshIsReadyToEquip();
			}
		}

		public void RenderVisualsOutline(OutlineEffectRenderer.OutlineType outlineType)
		{
			if (visualShapeContainer != null)
			{
				visualShapeContainer.RenderBatchedOutline(outlineType);
			}
			else
			{
				VisualTool.RenderOutline();
			}
		}

		public void RenderSelectionOutline(OutlineEffectRenderer.OutlineType outlineType)
		{
			int submeshCount = highlightRenderer.GetSubmeshCount();
			OutlineEffectRenderer.RenderOutline(outlineType, highlightRenderer, submeshCount);
			WorldFadeRenderer.RenderMask(highlightRenderer, submeshCount);
		}

		public void PromptToMergeExtrusion(StandaloneShapeContainer sourceExtrusion)
		{
			if (!Player.LocalPlayerExists || !visualShapeContainer.CanMergeShapeContainer(sourceExtrusion))
			{
				return;
			}
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Merge shape into costume?", $"Do you want to merge this shape into the costume's {friendlyName}?").Then(delegate(ConfirmDialogResponses r)
			{
				if (r == ConfirmDialogResponses.Affirmative)
				{
					visualShapeContainer.RequestMasterMergeShapeContainer(sourceExtrusion);
				}
			});
		}
	}
	public class CostumeShapeContainer : DecorationShapeContainer
	{
		[SerializeField]
		[Autofill(AutofillType.SelfAndParent, false)]
		private CostumePiece costumePiece;

		private IDisposable selectionHighlightUpdateToken;

		public override string FriendlyName => costumePiece.FriendlyName;

		protected override void Awake()
		{
			base.Awake();
			base.Tool.PostAttachEvent += MainTool_OnAttachOrDetach;
			base.Tool.PostDetachEvent += MainTool_OnAttachOrDetach;
			base.Tool.CustomSelectionForwarding = ToolSelectionForwarding;
		}

		private void MainTool_OnAttachOrDetach(Tool thisTool)
		{
			this.InvokeNextEndOfFrame(RefreshCollisionEnabled);
		}

		public override void OnSelectedByShapeCreationContext()
		{
			base.OnSelectedByShapeCreationContext();
			if (selectionHighlightUpdateToken == null)
			{
				selectionHighlightUpdateToken = this.Update(HighlightCostumePiece);
			}
		}

		public override void OnDeselectedByShapeCreationContext()
		{
			base.OnDeselectedByShapeCreationContext();
			if (selectionHighlightUpdateToken != null)
			{
				selectionHighlightUpdateToken.Dispose();
				selectionHighlightUpdateToken = null;
			}
		}

		public override bool CanMergeShapeContainer(ShapeContainer sourceExtrusion)
		{
			if (costumePiece.ParentCostume.IsEquipped)
			{
				return false;
			}
			return base.CanMergeShapeContainer(sourceExtrusion);
		}

		protected override void WarnShapesOutOfBounds()
		{
			base.WarnShapesOutOfBounds();
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Shapes out of bounds!", "Move your shapes closer to the costume dummy.", 3f);
		}

		private Tool ToolSelectionForwarding(Player player, bool physicalPickup, Collider selectedCollider)
		{
			return costumePiece.ParentCostume.Tool;
		}

		private void RefreshCollisionEnabled()
		{
			if (costumePiece.ParentCostume.IsEquipped)
			{
				base.Tool.DisableCollision(this);
			}
			else
			{
				base.Tool.EnableCollision(this);
			}
		}

		private void HighlightCostumePiece()
		{
			if (!costumePiece.ParentCostume.IsEquipped)
			{
				costumePiece.RenderSelectionOutline(base.Tool.OutlineType);
			}
		}
	}
	public class CostumeEquipUIFlow : CostumeUIFlow
	{
		[SerializeField]
		private Button3D equipButton;

		[SerializeField]
		private Button3D unequipButton;

		[SerializeField]
