		private void Start()
		{
			if (base.Costume != null)
			{
				base.Costume.EquipEvent += Costume_EquipEvent;
				base.Costume.UnequipEvent += Costume_UnequipEvent;
				base.Costume.IsReadyToEquipChangedEvent += Costume_IsReadyToEquipChanged;
			}
			Player.LocalPlayerCreatedEvent += new Action(OnLocalPlayerCreated);
			RefreshUI();
