		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Costume != null)
			{
				base.Costume.EquipEvent -= Costume_EquipEvent;
				base.Costume.UnequipEvent -= Costume_UnequipEvent;
				base.Costume.IsReadyToEquipChangedEvent -= Costume_IsReadyToEquipChanged;
			}
			Player.LocalPlayerCreatedEvent -= new Action(OnLocalPlayerCreated);
		}

		private void Costume_EquipEvent(Costume thisCostume)
		{
			RefreshUI();
		}

		private void Costume_UnequipEvent(Costume thisCostume)
		{
			RefreshUI();
		}

		private void Costume_IsReadyToEquipChanged(Costume thisCostume)
		{
			RefreshUI();
		}

		private void OnLocalPlayerCreated()
		{
			RefreshUI();
		}

		private void RefreshUI()
		{
			RefreshButtonState();
			RefreshInfoText();
		}

		private void RefreshButtonState()
		{
			if (Player.LocalPlayerExists && !(base.Costume == null))
			{
				if (base.Costume.EquippedPlayer == Player.LocalPlayer.PhotonPlayer)
				{
					equipButton.gameObject.SetActive(value: false);
					unequipButton.gameObject.SetActive(value: true);
					unequipButton.Interactable = true;
				}
				else
				{
					equipButton.gameObject.SetActive(value: true);
					unequipButton.gameObject.SetActive(value: false);
					equipButton.Interactable = base.Costume.IsReadyToEquip;
				}
			}
		}

		private void RefreshInfoText()
		{
			if (!(base.Costume == null) && !(infoText == null))
			{
				if (base.Costume.EquippedPlayer != null)
				{
					string nickName = base.Costume.EquippedPlayer.NickName;
					infoText.text = $"Equipped by {nickName}";
				}
				else
				{
					infoText.text = "Use 'Edit' on your Maker Pen to edit the costume";
				}
			}
		}

		[SkipRename]
		public void Button_Equip()
		{
			if (Player.LocalPlayerExists && base.Costume != null)
			{
				base.Costume.RequestEquipToPlayer(Player.LocalPlayer);
			}
		}

		[SkipRename]
		public void Button_Unequip()
		{
			if (Player.LocalPlayerExists && base.Costume != null)
			{
				base.Costume.RequestUnequip();
			}
		}
