namespace RecRoom.Core.Creation.Holotars
{
	public class AudioSample : UnityEngine.MonoBehaviour
	{
		public AudioSource audioSource;

		private bool _looping;

		private AudioClip audioClip;

		private AudioSamplerDataBlob samplerData;

		private bool _playing;

		public bool Loop
		{
			get
			{
				return _looping;
			}
			set
			{
				_looping = value;
				audioSource.loop = _looping;
			}
		}

		public bool IsPlaying => _playing;

		public void SetPitch(int pitchInput)
		{
			float pitch = audioSource.pitch;
			float num = 1f;
			if (pitchInput != 0)
			{
				num = (float)Mathf.Clamp(pitchInput, -500, 500) / 10f;
			}
			audioSource.pitch = num;
			if (pitch >= 0f && num < 0f && audioSource.clip != null)
			{
				audioSource.timeSamples = audioSource.clip.samples - 1;
			}
			if (pitch < 0f && num >= 0f)
			{
				audioSource.timeSamples = 0;
			}
		}

		public void SetVolume(int volume)
		{
			volume = Mathf.Clamp(volume, 1, 10);
			audioSource.volume = (float)volume / 10f;
		}

		private void Awake()
		{
			Stop();
		}

		private void OnDestroy()
		{
			SetAudioClip(null);
		}

		public void Initialize(AudioSamplerDataBlob data)
		{
			Stop();
			samplerData = data;
		}

		public void Play()
		{
			if (samplerData != null)
			{
				Stop(releaseAudio: false);
				EnsureAudioClip();
				audioSource.Play();
				_playing = true;
			}
			else
			{
				UnityEngine.Debug.LogWarning("Unable to play an Audio Sample with no assigned data.");
			}
		}

		public void Pause()
		{
			_playing = false;
			audioSource.Pause();
		}

		public void Stop(bool releaseAudio = true)
		{
			_playing = false;
			audioSource.Stop();
			if (releaseAudio)
			{
				SetAudioClip(null);
			}
		}

		private void EnsureAudioClip()
		{
			if (audioClip == null)
			{
				SetAudioClip(samplerData.AudioData.CreateUncompressedAudioClip());
			}
		}

		private void SetAudioClip(AudioClip clip)
		{
			if (audioClip != null)
			{
				UnityEngine.Object.DestroyImmediate(audioClip);
			}
			audioClip = clip;
			audioSource.clip = audioClip;
		}
	}
	public class AudioSampler : RecordableObject<AudioSamplerDataBlob>, IPersistable
	{
		private const InputSlot PLAY_SLOT = InputSlot.R;

		private const InputSlot SPEED_SLOT = InputSlot.G;

		private const InputSlot VOLUME_SLOT = InputSlot.B;

		private bool currentlyPlaying;

		[SerializeField]
		private float recordingUIMinDistance = 1f;

		[SerializeField]
		private float recordingUIMaxDistance = 3f;

		[SerializeField]
		private AudioSample audioSample;

		private SynchronizedField<bool> _uses2DAudio;

		public bool Uses2DAudio
		{
			get
			{
				return _uses2DAudio.Get();
			}
			set
			{
				_uses2DAudio.Set(value);
			}
		}

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			tool.AddCustomPickupCondition(ToolPickupCondition);
			_uses2DAudio = new SynchronizedField<bool>(this, "2DA", defaultValue: false, SetterPermissionMode.ANYONE, OnUses2DAudioChanged);
		}

		protected override void Start()
		{
			base.Start();
			OnUses2DAudioChanged();
		}

		protected override void InitializeCreationObjectSettings()
		{
			if (creationObject != null)
			{
				base.InitializeCreationObjectSettings();
				BoolSettingEditEvent settingEvent = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Use 2D audio";
					instance.PropertyGetter = Use2DAudio_Get;
					instance.PropertySetter = Use2DAudio_Set;
				});
				creationObject.AddConfigurableSetting(1, settingEvent);
			}
		}

		protected override void Update()
		{
			base.Update();
			if (uiInstance != null && Player.LocalPlayerExists && CanStartRecording)
			{
				float num = Vector3.Distance(Player.LocalPlayer.CurrentFloorPosition, base.transform.position);
				uiInstance.gameObject.SetActive(num > recordingUIMinDistance && num < recordingUIMaxDistance);
			}
		}

		public void UpdateCircuitInputs(Dictionary<InputSlot, int> updates)
		{
			if (updates.ContainsKey(InputSlot.R))
			{
				currentlyPlaying = updates[InputSlot.R] != 0;
			}
			if (updates.ContainsKey(InputSlot.G))
			{
				audioSample.SetPitch(updates[InputSlot.G]);
			}
			if (updates.ContainsKey(InputSlot.B))
			{
				if (updates[InputSlot.B] == 0)
				{
					audioSample.SetVolume(5);
				}
				else
				{
					audioSample.SetVolume(updates[InputSlot.B]);
				}
			}
		}

		protected override bool ShouldShowUI()
		{
			return !tool.IsHeld && base.ShouldShowUI();
		}

		protected override void UpdateObjectInteractivity()
		{
			base.UpdateObjectInteractivity();
			RefreshUIAvailability();
		}

		protected override AudioSamplerDataBlob InitializeRecordingData()
		{
			if (Player.LocalPlayerExists)
			{
				AudioSamplerDataBlob audioSamplerDataBlob = new AudioSamplerDataBlob();
				audioSamplerDataBlob.CreatorId = (int)PhotonNetwork.player.RecNetProfileId;
				return audioSamplerDataBlob;
			}
			return null;
		}

		protected override void TryGetBlobData()
		{
			if (Profiles.LocalProfile.IsJunior())
			{
				return;
			}
			DataBlobs.GetData(base.BlobName).Then(delegate(DataBlobs.DataBlob b)
			{
				if (this != null && b != null && b.bytes != null && b.name == base.BlobName)
				{
					try
					{
						AudioSamplerDataBlob audioSamplerDataBlob = AudioSamplerDataBlob.Parser.ParseFrom(b.bytes);
						if (audioSamplerDataBlob != null)
						{
							base.DataBlob = audioSamplerDataBlob;
						}
						DataBlobs.RemoveDataFromCache(b.name);
					}
					catch (Exception ex)
					{
						UnityEngine.Debug.LogErrorFormat("Error parsing Audio Sampler data blob: {0}", ex);
					}
				}
			}).Error(delegate(string e)
			{
				UnityEngine.Debug.LogWarningFormat("Error downloading Audio Sampler data: {0}", e);
			});
		}

		protected override void FinishLocalRecording()
		{
			if (base.IsRecordingLocally)
			{
				localRecordingData.Duration = UnityEngine.Time.realtimeSinceStartup - recordingStartTime;
				StopRecording(out var audioPromise);
				audioPromise.Then(delegate(AudioStreamData audioData)
				{
					localRecordingData.AudioData = audioData;
				}).Error(UnityEngine.Debug.LogWarning).Finally(delegate
				{
					EnterReviewRecordingSubstate();
				});
			}
		}

		protected override void OnEnterPlaybackIdleSubstate(ushort previousStateId, ushort previousSubstateId)
		{
			base.OnEnterPlaybackIdleSubstate(previousStateId, previousSubstateId);
			audioSample.Initialize(base.DataBlob);
		}

		protected override void OnUpdatePlaybackIdleSubstate()
		{
			base.OnUpdatePlaybackIdleSubstate();
			if (currentlyPlaying && !audioSample.audioSource.isPlaying)
			{
				audioSample.Play();
			}
		}

		protected override void OnExitPlaybackIdleSubstate(ushort nextStateId, ushort nextSubstateId)
		{
			base.OnExitPlaybackIdleSubstate(nextStateId, nextSubstateId);
			audioSample.Stop();
		}

		protected override void OnEnterReviewRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			audioSample.Initialize(localRecordingData);
			audioSample.Play();
			base.OnEnterReviewRecordingSubstate(previousStateId, previousSubStateId);
		}

		protected override void OnExitReviewRecordingSubstate(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitReviewRecordingSubstate(nextStateId, nextSubStateId);
			if (nextStateId != 2 || nextSubStateId != 2)
			{
				audioSample.Stop();
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.AudioSamplerPersistenceData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Audio Sampler {0}: data empty.", base.gameObject);
			}
			else
			{
				base.BlobName = deserializeParams.viewData.AudioSamplerPersistenceData.BlobName;
				Uses2DAudio = deserializeParams.viewData.AudioSamplerPersistenceData.Use2DAudio;
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.AudioSamplerPersistenceData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Audio Sampler {0}: Data already specified.", base.gameObject);
				return;
			}
			if (!string.IsNullOrEmpty(base.BlobName))
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.PersistTransientDataBlob(base.BlobName);
				if (transientData.datablobNamesToPersist == null)
				{
					transientData.datablobNamesToPersist = new List<string>();
				}
				transientData.datablobNamesToPersist.Add(base.BlobName);
			}
			viewData.AudioSamplerPersistenceData = new AudioSamplerPersistenceData
			{
				BlobName = base.BlobName,
				Use2DAudio = Uses2DAudio
			};
		}

		private bool ToolPickupCondition(Tool tool, Player player, Vector3 selectionPoint, bool physicalPickup)
		{
			return base.CurrentSynchronizedState != SynchronizedState.RECORDING;
		}

		public void Use2DAudio_Set(bool newValue)
		{
			Uses2DAudio = newValue;
		}

		public bool Use2DAudio_Get()
		{
			return Uses2DAudio;
		}

		private void OnUses2DAudioChanged()
		{
			audioSample.audioSource.spatialBlend = ((!Uses2DAudio) ? 1f : 0f);
		}
	}
	public class Holotar : RecordableObject<HolotarDataBlob>, IPersistable
	{
		[SerializeField]
		private HolotarPreviewPuppet previewPuppetPrefab;

		[SerializeField]
		private HolotarPlaybackPuppet playbackPuppetPrefab;

		[SerializeField]
		private Transform puppetRoot;

		[SerializeField]
		private HolotarUIPivot puppetPivot;

		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private HolotarCircuitNodeDisplay circuitDisplay;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private HolotarProjector projector;

		[NonSerialized]
		public bool LoadFromResources;

		private bool forcePlayRequested;

		private HolotarPreviewPuppet localPreviewPuppet;

		private HolotarPlaybackPuppet playbackPuppet;

		private HolotarCircuitNodeDisplay.PlayMode circuitPlayMode;

		private SynchronizedField<bool> _billboardPlayback;

		public bool BillboardPlayback
		{
			get
			{
				return _billboardPlayback.Get();
			}
			set
			{
				_billboardPlayback.Set(value);
			}
		}

		public override bool IsReadyForUse => projector.FullyOpen;

		private bool IsStatic => !GameSessions.LocalGameSession.IsSandbox || LoadFromResources;

		protected override bool CanStartRecording => !IsStatic && base.CanStartRecording;

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			tool.AddCustomPickupCondition(ToolPickupCondition);
			_billboardPlayback = new SynchronizedField<bool>(this, "HTR_BP", defaultValue: false, SetterPermissionMode.ANYONE, OnBillboardPlaybackChanged);
		}

		protected override void Start()
		{
			base.Start();
			if (circuitDisplay != null)
			{
				circuitDisplay.OnPlayModeChanged += OnCircuitPlayModeChanged;
				OnCircuitPlayModeChanged(circuitDisplay.CurrentPlayMode);
			}
		}

		protected override void InitializeCreationObjectSettings()
		{
			if (!LoadFromResources && creationObject != null)
			{
				base.InitializeCreationObjectSettings();
				BoolSettingEditEvent settingEvent = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Rotate to face viewer";
					instance.PropertyGetter = BillboardSetting_Get;
					instance.PropertySetter = BillboardSetting_Set;
				});
				creationObject.AddConfigurableSetting(settingEvent);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (circuitDisplay != null)
			{
				circuitDisplay.OnPlayModeChanged -= OnCircuitPlayModeChanged;
			}
		}

		private void OnBillboardPlaybackChanged()
		{
			RefreshBillboardPlayback();
		}

		protected override void OnAnyStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			base.OnAnyStateChanged(currentStateId, previousStateId, currentSubStateId, previousSubStateId);
			projector.TriggerFlicker();
		}

		public override void MasterSetResourceBlobName(string name)
		{
			if (LoadFromResources)
			{
				base.MasterSetResourceBlobName(name);
				return;
			}
			UnityEngine.Debug.LogErrorFormat("Unable to set resource blob name on Holotar {0}: LoadFromResources is not set.", base.gameObject);
		}

		protected override void OnEnterRecordingSynchronizedState(ushort previousStateId, ushort previousSubStateId)
		{
			projector.Visibility = ProjectorBase.VisibilityState.ForceOpen;
			base.OnEnterRecordingSynchronizedState(previousStateId, previousSubStateId);
		}

		protected override void OnExitRecordingSynchronizedState(ushort nextStateId, ushort nextSubstateId)
		{
			projector.Visibility = ProjectorBase.VisibilityState.Default;
			base.OnExitRecordingSynchronizedState(nextStateId, nextSubstateId);
		}

		protected override void OnEnterNoDataIdleSubstate(ushort previousStateId, ushort previousSubstateId)
		{
			base.OnEnterNoDataIdleSubstate(previousStateId, previousSubstateId);
			DestroyAllPuppets();
		}

		protected override void OnEnterPlaybackIdleSubstate(ushort previousStateId, ushort previousSubstateId)
		{
			RefreshBillboardPlayback();
			ShowPlaybackPuppet(base.DataBlob, loop: false);
			base.OnEnterPlaybackIdleSubstate(previousStateId, previousSubstateId);
		}

		protected override void OnExitPlaybackIdleSubstate(ushort nextStateId, ushort nextSubstateId)
		{
			base.OnExitPlaybackIdleSubstate(nextStateId, nextSubstateId);
			StopBillboardPlayback();
			DestroyAllPuppets();
			UpdateObjectInteractivity();
		}

		protected override void OnUpdatePlaybackIdleSubstate()
		{
			base.OnUpdatePlaybackIdleSubstate();
			CheckCircuitInput();
			if (projector.FullyOpen)
			{
				if (playbackPuppet.NormalizedTimestamp == 1f)
				{
					forcePlayRequested = false;
					playbackPuppet.Stop(releaseAudio: false);
					projector.TriggerFlicker();
				}
				else if (!playbackPuppet.IsPlaying)
				{
					playbackPuppet.Play();
				}
			}
			else if (playbackPuppet.IsPlaying)
			{
				playbackPuppet.Stop();
			}
		}

		private void RefreshBillboardPlayback()
		{
			if (base.CurrentIdleSubState == IdleSubstate.PLAYBACK)
			{
				if (BillboardPlayback)
				{
					puppetPivot.enabled = true;
				}
				else
				{
					StopBillboardPlayback();
				}
			}
		}

		private void StopBillboardPlayback()
		{
			puppetPivot.enabled = false;
			puppetPivot.transform.localRotation = Quaternion.identity;
		}

		private void OnCircuitPlayModeChanged(HolotarCircuitNodeDisplay.PlayMode mode)
		{
			circuitPlayMode = mode;
			if (circuitPlayMode == HolotarCircuitNodeDisplay.PlayMode.PLAY)
			{
				forcePlayRequested = true;
			}
		}

		private void CheckCircuitInput()
		{
			switch (circuitPlayMode)
			{
			case HolotarCircuitNodeDisplay.PlayMode.PLAY:
				projector.Visibility = ProjectorBase.VisibilityState.ForceOpen;
				break;
			case HolotarCircuitNodeDisplay.PlayMode.STOP:
				projector.Visibility = ProjectorBase.VisibilityState.ForceClosed;
				forcePlayRequested = false;
				break;
			case HolotarCircuitNodeDisplay.PlayMode.DEFAULT_CONNECTED:
				if (forcePlayRequested)
				{
					projector.Visibility = ProjectorBase.VisibilityState.ForceOpen;
				}
				else
				{
					projector.Visibility = ProjectorBase.VisibilityState.ForceClosed;
				}
				break;
			case HolotarCircuitNodeDisplay.PlayMode.DEFAULT_DISCONNECTED:
				projector.Visibility = ProjectorBase.VisibilityState.Default;
				forcePlayRequested = false;
				break;
			default:
				throw new InvalidOperationException("Unsupported Holotar circuit state.");
			}
		}

		protected override void OnEnterOtherPlayerRecordingState(ushort previousStateId, ushort previousSubstateId)
		{
			base.OnEnterOtherPlayerRecordingState(previousStateId, previousSubstateId);
			DestroyAllPuppets();
		}

		protected override void OnExitRecordingLocalState(ushort nextStateId, ushort nextSubstateId)
		{
			base.OnExitRecordingLocalState(nextStateId, nextSubstateId);
			DestroyAllPuppets();
		}

		protected override void OnEnterCountdownRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			ShowPreviewPuppet();
			base.OnEnterCountdownRecordingSubstate(previousStateId, previousSubStateId);
		}

		protected override void OnExitActiveRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			EndHolotarRecording(out var _);
			base.OnExitActiveRecordingSubstate(previousStateId, previousSubStateId);
		}

		protected override void StartLocalRecording()
		{
			if (!base.IsRecordingLocally)
			{
				ShowPreviewPuppet();
				recordingStartTime = UnityEngine.Time.realtimeSinceStartup;
				localRecordingData = InitializeRecordingData();
				localPreviewPuppet.PoseRecorder.StartRecording();
				micAudioRecorder.StartRecording(maxRecordingDuration);
				base.IsRecordingLocally = true;
			}
		}

		protected override void FinishLocalRecording()
		{
			if (base.IsRecordingLocally)
			{
				localRecordingData.Duration = UnityEngine.Time.realtimeSinceStartup - recordingStartTime;
				EndHolotarRecording(out var poseData);
				StopRecording(out var audioPromise);
				localRecordingData.PoseData = poseData;
				audioPromise.Then(delegate(AudioStreamData audioData)
				{
					localRecordingData.AudioData = audioData;
				}).Error(UnityEngine.Debug.LogWarning).Finally(delegate
				{
					EnterReviewRecordingSubstate();
				});
			}
		}

		private void EndHolotarRecording(out HolotarDataBlob.Types.PlayerPoseData poseData)
		{
			poseData = localPreviewPuppet.PoseRecorder.FinishRecording();
			DestroyPreviewPuppet();
		}

		protected override void OnEnterReviewRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			ShowPlaybackPuppet(localRecordingData, loop: true);
			playbackPuppet.Play();
			base.OnEnterReviewRecordingSubstate(previousStateId, previousSubStateId);
		}

		protected override void OnExitReviewRecordingSubstate(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitReviewRecordingSubstate(nextStateId, nextSubStateId);
			if (nextStateId != 2 || nextSubStateId != 2)
			{
				DestroyPlaybackPuppet();
			}
		}

		protected override void OnExitUploadRecordingSubstate(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitUploadRecordingSubstate(nextStateId, nextSubStateId);
			DestroyPlaybackPuppet();
		}

		protected override void UpdateObjectInteractivity()
		{
			base.UpdateObjectInteractivity();
			if (tool.IsHeld || !tool.RigidbodyEx.IsSleeping())
			{
				projector.Visibility = ProjectorBase.VisibilityState.ForceClosed;
			}
			else
			{
				projector.Visibility = ProjectorBase.VisibilityState.Default;
			}
		}

		protected override HolotarDataBlob InitializeRecordingData()
		{
			if (Player.LocalPlayerExists)
			{
				HolotarDataBlob holotarDataBlob = new HolotarDataBlob();
				holotarDataBlob.CreatorId = (int)PhotonNetwork.player.RecNetProfileId;
				holotarDataBlob.OutfitData = Player.LocalPlayer.PlayerOutfit.GetOutfitProtobuf();
				holotarDataBlob.VoipFilter = (int)Player.LocalPlayer.VOIPFilter;
				return holotarDataBlob;
			}
			return null;
		}

		protected override void TryGetBlobData()
		{
			if (LoadFromResources)
			{
				TextAsset textAsset = Resources.Load<TextAsset>(base.BlobName);
				if (textAsset != null)
				{
					try
					{
						HolotarDataBlob holotarDataBlob = HolotarDataBlob.Parser.ParseFrom(textAsset.bytes);
						if (holotarDataBlob != null)
						{
							base.DataBlob = holotarDataBlob;
						}
						Resources.UnloadAsset(textAsset);
						return;
					}
					catch (Exception ex)
					{
						UnityEngine.Debug.LogErrorFormat("Error parsing Holotar data blob: {0}", ex);
						return;
					}
				}
				UnityEngine.Debug.LogErrorFormat("Failed to load Holotar data from resources: {0}", base.BlobName);
			}
			else
			{
				if (Profiles.LocalProfile.IsJunior())
				{
					return;
				}
				DataBlobs.GetData(base.BlobName).Then(delegate(DataBlobs.DataBlob b)
				{
					if (this != null && b != null && b.bytes != null && b.name == base.BlobName)
					{
						try
						{
							HolotarDataBlob holotarDataBlob2 = HolotarDataBlob.Parser.ParseFrom(b.bytes);
							if (holotarDataBlob2 != null)
							{
								base.DataBlob = holotarDataBlob2;
							}
							DataBlobs.RemoveDataFromCache(b.name);
						}
						catch (Exception ex2)
						{
							UnityEngine.Debug.LogErrorFormat("Error parsing Holotar data blob: {0}", ex2);
						}
					}
				}).Error(delegate(string e)
				{
					UnityEngine.Debug.LogWarningFormat("Error downloading Holotar data: {0}", e);
				});
			}
		}

		protected override bool ShouldShowUI()
		{
			return !IsStatic && base.ShouldShowUI();
		}

		private void ShowPlaybackPuppet(HolotarDataBlob data, bool loop)
		{
			DestroyPreviewPuppet();
			if (playbackPuppet == null)
			{
				playbackPuppet = UnityEngine.Object.Instantiate(playbackPuppetPrefab, puppetRoot, worldPositionStays: false);
			}
			playbackPuppet.Initialize(data);
			playbackPuppet.Loop = loop;
		}

		private void DestroyPlaybackPuppet()
		{
			if (playbackPuppet != null)
			{
				UnityEngine.Object.Destroy(playbackPuppet.gameObject);
			}
		}

		private void ShowPreviewPuppet()
		{
			DestroyPlaybackPuppet();
			if (localPreviewPuppet == null)
			{
				localPreviewPuppet = UnityEngine.Object.Instantiate(previewPuppetPrefab, puppetRoot, worldPositionStays: false);
				localPreviewPuppet.TargetPlayer = Player.LocalPlayer;
			}
		}

		private void DestroyPreviewPuppet()
		{
			if (localPreviewPuppet != null)
			{
				UnityEngine.Object.Destroy(localPreviewPuppet.gameObject);
			}
		}

		private void DestroyAllPuppets()
		{
			DestroyPlaybackPuppet();
			DestroyPreviewPuppet();
		}

		private bool ToolPickupCondition(Tool tool, Player player, Vector3 selectionPoint, bool physicalPickup)
		{
			return base.CurrentSynchronizedState != SynchronizedState.RECORDING && projector.FullyClosed;
		}

		public void BillboardSetting_Set(bool newValue)
		{
			BillboardPlayback = newValue;
		}

		public bool BillboardSetting_Get()
		{
			return BillboardPlayback;
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.HolotarPersistenceData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Holotar {0}: data empty.", base.gameObject);
			}
			else
			{
				base.BlobName = deserializeParams.viewData.HolotarPersistenceData.BlobName;
				BillboardPlayback = deserializeParams.viewData.HolotarPersistenceData.Billboard;
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.HolotarPersistenceData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Holotar {0}: Data already specified.", base.gameObject);
				return;
			}
			if (!string.IsNullOrEmpty(base.BlobName))
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.PersistTransientDataBlob(base.BlobName);
				if (transientData.datablobNamesToPersist == null)
				{
					transientData.datablobNamesToPersist = new List<string>();
				}
				transientData.datablobNamesToPersist.Add(base.BlobName);
			}
			viewData.HolotarPersistenceData = new HolotarPersistenceData
			{
				BlobName = base.BlobName,
				Billboard = BillboardPlayback
			};
		}
	}
	public class HolotarCircuitNodeDisplay : CircuitNodeDisplay
	{
		public enum PlayMode
		{
			DEFAULT_DISCONNECTED,
			DEFAULT_CONNECTED,
			PLAY,
			STOP
		}

		private const InputSlot STOP_SLOT = InputSlot.R;

		private const InputSlot PLAY_SLOT = InputSlot.G;

		private static readonly InputMetadata[] INPUT_META = new InputMetadata[2]
		{
			new InputMetadata
			{
				InputSlot = InputSlot.G,
				Description = "Play"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.R,
				Description = "Stop"
			}
		};

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<PlayMode> m_OnPlayModeChanged;

		public PlayMode CurrentPlayMode
		{
			get
			{
				if (!IsPlayCircuitConnected)
				{
					return PlayMode.DEFAULT_DISCONNECTED;
				}
				if (IsStopRequested)
				{
					return PlayMode.STOP;
				}
				if (IsPlayRequested)
				{
					return PlayMode.PLAY;
				}
				return PlayMode.DEFAULT_CONNECTED;
			}
		}

		private bool IsPlayCircuitConnected => base.MyCircuitNode != null && base.MyCircuitNode.Inputs.ContainsKey(InputSlot.G);

		private bool IsPlayRequested => base.MyCircuitNode != null && CircuitNode.SignalToBool(base.MyCircuitNode.GetInputSignal(InputSlot.G));

		private bool IsStopRequested => base.MyCircuitNode != null && CircuitNode.SignalToBool(base.MyCircuitNode.GetInputSignal(InputSlot.R));

		public event Action<PlayMode> OnPlayModeChanged
		{
			add
			{
				Action<PlayMode> action = this.m_OnPlayModeChanged;
				Action<PlayMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPlayModeChanged, (Action<PlayMode>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<PlayMode> action = this.m_OnPlayModeChanged;
				Action<PlayMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPlayModeChanged, (Action<PlayMode>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
				CircuitNode myCircuitNode = base.MyCircuitNode;
				myCircuitNode.OnConnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Remove(myCircuitNode.OnConnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
				CircuitNode myCircuitNode2 = base.MyCircuitNode;
				myCircuitNode2.OnDisconnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Remove(myCircuitNode2.OnDisconnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
			}
			base.OnCircuitNodeInitialized(node);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj2 = (OutputNode)base.MyCircuitNode;
				obj2.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Combine(obj2.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
				CircuitNode myCircuitNode3 = base.MyCircuitNode;
				myCircuitNode3.OnConnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Combine(myCircuitNode3.OnConnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
				CircuitNode myCircuitNode4 = base.MyCircuitNode;
				myCircuitNode4.OnDisconnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Combine(myCircuitNode4.OnDisconnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
			}
			OutputNode outputNode = (OutputNode)node;
			outputNode.SetInputMeta(INPUT_META);
			if (this.OnPlayModeChanged != null)
			{
				this.OnPlayModeChanged(CurrentPlayMode);
			}
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
				CircuitNode myCircuitNode = base.MyCircuitNode;
				myCircuitNode.OnConnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Remove(myCircuitNode.OnConnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
				CircuitNode myCircuitNode2 = base.MyCircuitNode;
				myCircuitNode2.OnDisconnectedEvent = (CircuitNode.ThisNodeConnectionChanged)Delegate.Remove(myCircuitNode2.OnDisconnectedEvent, new CircuitNode.ThisNodeConnectionChanged(OnNodeConnectionChanged));
			}
		}

		private void OnNodeConnectionChanged(CircuitNode other, InputSlot inputSlot, OutputSlot outputSlot)
		{
			if (this.OnPlayModeChanged != null)
			{
				this.OnPlayModeChanged(CurrentPlayMode);
			}
		}

		private void OnNodeInputReceived(Dictionary<InputSlot, int> updates)
		{
			if (this.OnPlayModeChanged != null)
			{
				this.OnPlayModeChanged(CurrentPlayMode);
			}
		}
	}
	[SceneInstanceOnly]
	public class HolotarDataOverride : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private TextAsset[] resourceAssets;

		[SerializeField]
		private bool billboardPlayback;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Holotar holotar;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		private void Awake()
		{
			holotar.LoadFromResources = true;
			tool.DisablePickup(this);
			tool.KinematicOnReset = true;
			tool.KinematicOnSleep = true;
		}

		private void Start()
		{
			if (PhotonNetwork.isMasterClient)
			{
				holotar.BillboardPlayback = billboardPlayback;
				MasterPickRandomAsset();
			}
		}

		public void MasterPickRandomAsset()
		{
			if (resourceAssets.Length == 0)
			{
				UnityEngine.Debug.LogErrorFormat("Unable to load data for Holotar {0} from resources: No assets specified", holotar.gameObject);
				return;
			}
			int num = UnityEngine.Random.Range(0, resourceAssets.Length);
			if (resourceAssets[num] != null)
			{
				holotar.MasterSetResourceBlobName(resourceAssets[num].name);
				return;
			}
			UnityEngine.Debug.LogErrorFormat("Unable to load data for Holotar {0} from resources: Asset is null", holotar.gameObject);
		}
	}
	public class HolotarPlaybackPuppet : PlayerPuppet
	{
		[SerializeField]
		private AudioSource audioSource;

		public bool Loop;

		private AudioClip audioClip;

		protected HolotarPlaybackPuppetSource source = new HolotarPlaybackPuppetSource();

		private bool _playing;

		protected override IPlayerPuppetSource Source => source;

		public bool IsPlaying => _playing && NormalizedTimestamp < 1f;

		public float NormalizedTimestamp
		{
			get
			{
				if (source == null || source.Data == null)
				{
					return -1f;
				}
				return source.Timestamp / source.Data.Duration;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			Stop();
		}

		protected override void LateUpdate()
		{
			base.LateUpdate();
			if (VisualsActive && _playing)
			{
				source.Update(UnityEngine.Time.deltaTime);
				if (Loop && source.Data != null && source.Timestamp >= source.Data.Duration)
				{
					SetTime(0f);
				}
			}
		}

		private void OnDestroy()
		{
			SetAudioClip(null);
			source.Data = null;
		}

		public void Initialize(HolotarDataBlob data)
		{
			Stop();
			source.Data = data;
			SetVoiceFilter((AudioManager.VOIPFilter)data.VoipFilter);
			UpdatePlayerOutfit();
			UpdatePlayerSkinColor();
			UpdatePlayerFaceFeatures();
		}

		public void Play()
		{
			if (source.Data != null)
			{
				if (NormalizedTimestamp == 1f)
				{
					Stop(releaseAudio: false);
				}
				EnsureAudioClip();
				audioSource.Play();
				_playing = true;
			}
			else
			{
				UnityEngine.Debug.LogWarning("Unable to play a Holotar with no assigned data.");
			}
		}

		public void Pause()
		{
			_playing = false;
			audioSource.Pause();
		}

		public void Stop(bool releaseAudio = true)
		{
			_playing = false;
			audioSource.Stop();
			SetTime(0f);
			if (releaseAudio)
			{
				SetAudioClip(null);
			}
		}

		private void EnsureAudioClip()
		{
			if (audioClip == null)
			{
				SetAudioClip(source.Data.AudioData.CreateUncompressedAudioClip());
			}
		}

		private void SetAudioClip(AudioClip clip)
		{
			if (audioClip != null)
			{
				UnityEngine.Object.DestroyImmediate(audioClip);
			}
			audioClip = clip;
			audioSource.clip = audioClip;
		}

		private void SetTime(float time)
		{
			if (source.Data != null)
			{
				source.SetTime(time);
			}
			audioSource.time = time;
			if (_playing)
			{
				audioSource.Play();
			}
		}

		private void SetVoiceFilter(AudioManager.VOIPFilter filter)
		{
			SingletonMonoBehaviour<AudioManager>.Instance.SetSourceToVOIPMixer(audioSource, filter);
		}
	}
}
namespace RecRoom.Players.Puppet
{
	public class HolotarPlaybackPuppetSource : IPlayerPuppetSource
	{
		private HolotarDataBlob _data;

		private float _timestamp;

		public HolotarDataBlob Data
		{
			get
			{
				return _data;
			}
			set
			{
				if (_data != value)
				{
					_data = value;
					if (_data != null)
					{
						RefreshFromData();
					}
				}
			}
		}

		public bool ShouldDisplay => true;

		public Color SkinColor { get; private set; }

		public Color HairColor { get; private set; }

		public IList<OutfitSelectionToBody> OutfitSelections { get; private set; }

		public float AudioVolume => 0f;

		public PuppetTransform Head { get; private set; }

		public PuppetTransform Body { get; private set; }

		public PuppetHandState LeftHand { get; private set; }

		public PuppetHandState RightHand { get; private set; }

		public float Timestamp
		{
			get
			{
				return _timestamp;
			}
			private set
			{
				if (Data == null)
				{
					UnityEngine.Debug.LogError("Cannot set time on a HolotarReplayPuppetSource with no data.");
				}
				else if (_timestamp != value)
				{
					_timestamp = Mathf.Clamp(value, 0f, Data.Duration);
				}
			}
		}

		public AvatarFaceSettings FaceFeatures { get; private set; }

		public void Update(float deltaTime)
		{
			if (Data != null)
			{
				Timestamp += deltaTime;
				CachePoses();
			}
		}

		public void SetTime(float normalizedT)
		{
			if (Data != null)
			{
				Timestamp = Mathf.Lerp(0f, Data.Duration, normalizedT);
			}
			else
			{
				Timestamp = 0f;
			}
		}

		private void RefreshFromData()
		{
			if (Data != null)
			{
				PlayerOutfit.ParseOutfitProtobuf(Data.OutfitData, out var hairColor, out var skinColor, out var selections, out var faceSettings);
				HairColor = hairColor;
				SkinColor = skinColor;
				OutfitSelections = selections;
				FaceFeatures = faceSettings;
				Timestamp = 0f;
				CachePoses();
			}
		}

		private void CachePoses()
		{
			HolotarDataBlob.Types.PlayerPoseData poseData = Data.PoseData;
			if (poseData != null)
			{
				GetCurrentPoseIndices(out var startIndex, out var endIndex, out var poseT);
				Head = PoseStreamToTransform(poseData.HeadPoses.Poses, startIndex, endIndex, poseT);
				Body = PoseStreamToTransform(poseData.TorsoPoses.Poses, startIndex, endIndex, poseT);
				LeftHand = PoseStreamToHand(poseData.LeftHandPoses.Poses, startIndex, endIndex, poseT);
				RightHand = PoseStreamToHand(poseData.RightHandPoses.Poses, startIndex, endIndex, poseT);
			}
			else
			{
				UnityEngine.Debug.LogError("HolotarDataBlob with null PoseData found.");
			}
		}

		private void GetCurrentPoseIndices(out int startIndex, out int endIndex, out float poseT)
		{
			int count = Data.PoseData.HeadPoses.Poses.Count;
			float num = Timestamp / Data.Duration;
			int num2 = count - 1;
			float num3 = (float)num2 * num;
			startIndex = Mathf.Clamp((int)Mathf.Floor(num3), 0, num2);
			endIndex = Mathf.Clamp((int)Mathf.Ceil(num3), 0, num2);
			if (startIndex != endIndex)
			{
				poseT = Mathf.InverseLerp(startIndex, endIndex, num3);
			}
			else
			{
				poseT = 0f;
			}
		}

		private PuppetTransform PoseStreamToTransform(RepeatedField<HolotarDataBlob.Types.PoseTransformData> poses, int startIndex, int endIndex, float poseT)
		{
			if (poses.Count > 0)
			{
				startIndex = Mathf.Clamp(startIndex, 0, poses.Count);
				endIndex = Mathf.Clamp(endIndex, 0, poses.Count);
				return PoseSamplesToTransform(startIndex, poses[startIndex], endIndex, poses[endIndex], poseT);
			}
			return default(PuppetTransform);
		}

		private PuppetHandState PoseStreamToHand(RepeatedField<HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData> poses, int startIndex, int endIndex, float poseT)
		{
			PuppetHandState result = default(PuppetHandState);
			if (poses.Count > 0)
			{
				startIndex = Mathf.Clamp(startIndex, 0, poses.Count);
				endIndex = Mathf.Clamp(endIndex, 0, poses.Count);
				HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData handPoseData = poses[startIndex];
				HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData handPoseData2 = poses[endIndex];
				result.transform = PoseSamplesToTransform(startIndex, handPoseData.Transform, endIndex, handPoseData2.Transform, poseT);
				result.openClosedAxis = Mathf.Lerp(handPoseData.OpenClosedAxis, handPoseData2.OpenClosedAxis, poseT);
				int value = ((!(poseT < 0.5f)) ? endIndex : startIndex);
				value = Mathf.Clamp(value, 0, poses.Count);
				HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData handPoseData3 = poses[value];
				result.isMenuHandVisible = handPoseData3.IsMenuHandVisible;
				result.thumbsUpActive = handPoseData3.ThumbsUpActive;
			}
			return result;
		}

		private PuppetTransform PoseSamplesToTransform(int startIndex, HolotarDataBlob.Types.PoseTransformData startPose, int endIndex, HolotarDataBlob.Types.PoseTransformData endPose, float poseT)
		{
			Vector3 localPosition;
			Quaternion localRotation;
			if (startIndex == endIndex)
			{
				localPosition = startPose.LocalPosition.ToVector3();
				localRotation = startPose.LocalRotation.ToQuaternion();
			}
			else
			{
				localPosition = Vector3.Lerp(startPose.LocalPosition.ToVector3(), endPose.LocalPosition.ToVector3(), poseT);
				localRotation = Quaternion.Slerp(startPose.LocalRotation.ToQuaternion(), endPose.LocalRotation.ToQuaternion(), poseT);
			}
			return new PuppetTransform
			{
				localPosition = localPosition,
				localRotation = localRotation
			};
		}
	}
}
namespace RecRoom.Core.Creation.Holotars
{
	public class HolotarPoseRecorder : UnityEngine.MonoBehaviour
	{
		[Header("Settings")]
		[SerializeField]
		private int framesPerSecond = 12;

		[Header("Transforms")]
		[SerializeField]
		private Transform coordinateRootTransform;

		[SerializeField]
		private PlayerPuppet sourcePuppet;

		private HolotarDataBlob.Types.PlayerPoseData poseData;

		private Action<HolotarDataBlob.Types.PlayerPoseData> recordingCompleteCallback;

		private Coroutine recordingRoutine;

		private bool IsRecording => recordingRoutine != null;

		public void StartRecording()
		{
			if (!IsRecording)
			{
				recordingRoutine = StartCoroutine(RunRecordingRoutine());
			}
		}

		public HolotarDataBlob.Types.PlayerPoseData FinishRecording()
		{
			if (IsRecording)
			{
				this.SafeStopCoroutine(recordingRoutine);
				recordingRoutine = null;
				return poseData;
			}
			return null;
		}

		private IEnumerator RunRecordingRoutine()
		{
			poseData = InitializePoseData();
			float timeElapsed = 0f;
			float perSampleWait = 1f / (float)framesPerSecond;
			while (true)
			{
				CachePoseFrame();
				yield return new WaitForSeconds(perSampleWait);
				timeElapsed += UnityEngine.Time.unscaledDeltaTime;
			}
		}

		private HolotarDataBlob.Types.PlayerPoseData InitializePoseData()
		{
			HolotarDataBlob.Types.PlayerPoseData playerPoseData = new HolotarDataBlob.Types.PlayerPoseData();
			playerPoseData.SamplesPerSecond = framesPerSecond;
			playerPoseData.HeadPoses = new HolotarDataBlob.Types.PoseStream();
			playerPoseData.TorsoPoses = new HolotarDataBlob.Types.PoseStream();
			playerPoseData.LeftHandPoses = new HolotarDataBlob.Types.HandPoseStream();
			playerPoseData.RightHandPoses = new HolotarDataBlob.Types.HandPoseStream();
			return playerPoseData;
		}

		private void CachePoseFrame()
		{
			poseData.HeadPoses.Poses.Add(SampleTransform(sourcePuppet.Head));
			poseData.TorsoPoses.Poses.Add(SampleTransform(sourcePuppet.Body));
			poseData.LeftHandPoses.Poses.Add(SampleHandPose(sourcePuppet.LeftHand));
			poseData.RightHandPoses.Poses.Add(SampleHandPose(sourcePuppet.RightHand));
		}

		private HolotarDataBlob.Types.PoseTransformData SampleTransform(Transform toSample)
		{
			Vector3 vector = coordinateRootTransform.InverseTransformPoint(toSample.position);
			Quaternion quaternion = coordinateRootTransform.InverseTransformRotation(toSample.rotation);
			HolotarDataBlob.Types.PoseTransformData poseTransformData = new HolotarDataBlob.Types.PoseTransformData();
			poseTransformData.LocalPosition = vector.ToVector3Data();
			poseTransformData.LocalRotation = quaternion.ToVector3Data();
			return poseTransformData;
		}

		private HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData SampleHandPose(PlayerPuppetHand puppetHand)
		{
			HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData handPoseData = new HolotarDataBlob.Types.HandPoseStream.Types.HandPoseData();
			handPoseData.Transform = SampleTransform(puppetHand.transform);
			handPoseData.IsMenuHandVisible = puppetHand.IsPointingMeshVisible;
			handPoseData.ThumbsUpActive = puppetHand.IsThumbsUpActive;
			handPoseData.OpenClosedAxis = puppetHand.OpenCloseAxis;
			return handPoseData;
		}
	}
