	public class MicAudioRecorder : UnityEngine.MonoBehaviour
	{
		private const int MAX_SAMPLES_TO_ENCODE_PER_FRAME = 5000;

		[SerializeField]
		private AudioStreamData.Types.Format format = AudioStreamData.Types.Format.Opus;

		[SerializeField]
		private SamplingRate preferredSamplingRate = SamplingRate.Sampling24000;

		[SerializeField]
		private int compressedBitrate = 96000;

		private string microphoneDeviceName;

		private AudioClip microphoneClip;

		private int nextRecordingPosition;

		private List<float> recordedSamples;

		private int maxRecordedSamples;

		private AudioStreamData pendingStreamData;

		public bool IsRecording { get; private set; }

		private void Update()
		{
			if (!IsRecording)
			{
				return;
			}
			int num = nextRecordingPosition;
			int num2 = Microphone.GetPosition(microphoneDeviceName);
			if (num != num2)
			{
				nextRecordingPosition = num2;
				if (num > num2)
				{
					num2 += microphoneClip.samples;
				}
				float[] array = new float[microphoneClip.channels * (num2 - num)];
				if (Player.LocalPlayerExists && !Player.LocalPlayer.Mute)
				{
					microphoneClip.GetData(array, num);
				}
				RecordSamples(array, microphoneClip.channels, microphoneClip.frequency);
			}
		}

		private void RecordSamples(float[] samples, int channels, int sampleRate)
		{
			if (recordedSamples == null)
			{
				UnityEngine.Debug.LogWarning("RecordSamples() - uncompressedSamples is null");
				return;
			}
			if (recordedSamples.Count >= maxRecordedSamples)
			{
				UnityEngine.Debug.LogWarning("RecordSamples() - uncompressedSamples has exceeded maxRecordedSamples");
				return;
			}
			if (sampleRate != pendingStreamData.SampleRate)
			{
				float num = (float)pendingStreamData.SampleRate / (float)sampleRate;
				float[] array = new float[Mathf.CeilToInt(num * (float)samples.Length)];
				AudioUtil.Resample(samples, array, array.Length, channels);
				samples = array;
			}
			if (channels == 1)
			{
				recordedSamples.AddRange(samples);
			}
			else if (channels >= 2)
			{
				for (int i = 0; i < samples.Length; i += channels)
				{
					recordedSamples.Add(samples[i]);
				}
			}
		}

		public void StartRecording(float maxDuration)
		{
			if (IsRecording)
			{
				UnityEngine.Debug.LogWarning("MicAudioRecorder.StartRecording() called while IsRecording is true");
				return;
			}
			microphoneDeviceName = PhotonVoiceNetwork.MicrophoneDevice;
			if (string.IsNullOrEmpty(microphoneDeviceName))
			{
				UnityEngine.Debug.LogError("Error: No microphone");
				return;
			}
			int num = (int)preferredSamplingRate;
			microphoneClip = SharedMicrophone.GetMicrophone(microphoneDeviceName, num);
			pendingStreamData = new AudioStreamData();
			pendingStreamData.Format = this.format;
			AudioStreamData.Types.Format format = pendingStreamData.Format;
			if (format == AudioStreamData.Types.Format.Opus)
			{
				pendingStreamData.SampleRate = CalculateBestOpusEncoderSampleRate(num);
			}
			else
			{
				pendingStreamData.SampleRate = num;
			}
			pendingStreamData.Channels = 1;
			float num2 = maxDuration + 0.1f;
			maxRecordedSamples = Mathf.CeilToInt(num2 * (float)pendingStreamData.SampleRate) * pendingStreamData.Channels;
			nextRecordingPosition = Microphone.GetPosition(microphoneDeviceName);
			recordedSamples = new List<float>(maxRecordedSamples);
			IsRecording = true;
		}

		private static int CalculateBestOpusEncoderSampleRate(int f)
		{
			int num = int.MaxValue;
			int result = 48000;
			foreach (object value in System.Enum.GetValues(typeof(SamplingRate)))
			{
				int num2 = Math.Abs((int)value - f);
				if (num2 < num)
				{
					num = num2;
					result = (int)value;
				}
			}
			return result;
		}

		public void CancelRecording()
		{
			if (!IsRecording)
			{
				UnityEngine.Debug.LogWarning("MicAudioRecorder.StopRecording() called while IsRecording is false.");
				return;
			}
			IsRecording = false;
			recordedSamples = null;
			pendingStreamData = null;
		}

		public IPromise<AudioStreamData> FinishRecording()
		{
			if (!IsRecording)
			{
				return new ErroredPromise<AudioStreamData>("MicAudioRecorder.FinishRecording() called while IsRecording is false.");
			}
			IsRecording = false;
			List<float> list = recordedSamples;
			AudioStreamData audioStreamData = pendingStreamData;
			recordedSamples = null;
			pendingStreamData = null;
			Promise<AudioStreamData> promise = null;
			switch (format)
			{
			case AudioStreamData.Types.Format.Uncompressed:
				audioStreamData.UncompressedSamples.AddRange(list);
				audioStreamData.SampleCount = list.Count;
				promise = new CompletedPromise<AudioStreamData>(audioStreamData);
				break;
			case AudioStreamData.Types.Format.Opus:
				promise = new Promise<AudioStreamData>();
				StartCoroutine(RunOpusEncoding(list, audioStreamData, promise));
				break;
			default:
				throw new InvalidOperationException("MicAudioRecorder doesn't support format " + format);
			}
			return promise;
		}

		private IEnumerator RunOpusEncoding(List<float> inputSamples, AudioStreamData inputStreamData, Promise<AudioStreamData> completePromise)
		{
			OpusEncoder opusEncoder = new OpusEncoder((SamplingRate)inputStreamData.SampleRate, (Channels)inputStreamData.Channels, compressedBitrate, OpusApplicationType.Audio, Delay.Delay40ms);
			int frameSize = opusEncoder.FrameSizePerChannel * (int)opusEncoder.InputChannels;
			int frameCount = Mathf.CeilToInt((float)inputSamples.Count / (float)frameSize);
			int bytesPerSecond = compressedBitrate / 8;
			int maxBytes = bytesPerSecond * Mathf.CeilToInt((float)(frameSize * (frameCount + 1)) / (float)inputStreamData.SampleRate);
			List<byte> compressedData = new List<byte>(maxBytes);
			List<int> compressedPacketSizes = new List<int>(frameCount);
			float[] currentFrame = new float[frameSize];
			int samplesProcessedThisFrame = 0;
			for (int i = 0; i < frameCount; i++)
			{
				int sourceOffset = i * frameSize;
				int sourceCount = frameSize;
				if (sourceOffset + sourceCount > inputSamples.Count)
				{
					sourceCount = inputSamples.Count - sourceOffset;
					Array.Clear(currentFrame, 0, currentFrame.Length);
				}
				inputSamples.CopyTo(sourceOffset, currentFrame, 0, sourceCount);
				ArraySegment<byte> encodedOutput = opusEncoder.Encode(currentFrame);
				if (encodedOutput.Offset == 0 && encodedOutput.Count == encodedOutput.Array.Length)
				{
					compressedData.AddRange(encodedOutput.Array);
				}
				else
				{
					int offset = encodedOutput.Offset;
					int num = offset + encodedOutput.Count;
					for (int j = offset; j < num; j++)
					{
						compressedData.Add(encodedOutput.Array[j]);
					}
				}
				compressedPacketSizes.Add(encodedOutput.Count);
				samplesProcessedThisFrame += sourceCount;
				if (samplesProcessedThisFrame > 5000)
				{
					yield return null;
					samplesProcessedThisFrame = 0;
				}
			}
			inputStreamData.SampleCount = frameCount * frameSize;
			inputStreamData.CompressedBitrate = compressedBitrate;
			inputStreamData.CompressedPacketSizes.AddRange(compressedPacketSizes);
			inputStreamData.CompressedData = ByteString.CopyFrom(compressedData.ToArray());
			completePromise.Complete(inputStreamData);
		}
	}
	public interface IRecordable
	{
		bool IsReadyForUse { get; }

		float LocalRecordingProgress { get; }

		string StartRecordingPrompt { get; }

		void TryEnterRecordingFlow();

		void TryExitRecordingFlow();

		void TryStartRecording();

		void TryFinishRecording();

		void TrySaveRecording();
	}
	public abstract class RecordableObject<T> : Photon.MonoBehaviour, IRecordable where T : IMessage, IEquatable<T>
	{
		public enum SynchronizedState
		{
			IDLE = 0,
			RECORDING = 1,
			DISABLED = 65535
		}

		public enum LocalState
		{
			IDLE = 0,
			OTHER_PLAYER_RECORDING = 1,
			RECORDING = 2,
			INVALID = 65535
		}

		public enum IdleSubstate
		{
			NO_DATA = 0,
			PLAYBACK = 1,
			INVALID = 65535
		}

		public enum RecordingSubState
		{
			COUNTDOWN = 0,
			ACTIVE = 1,
			REVIEW = 2,
			UPLOADING = 3,
			INVALID = 65535
		}

		protected static RecordableObject<T> LocalActiveRecordingObject;

		[SerializeField]
		private RecordableStackedUI uiPrefab;

		[SerializeField]
		private Transform uiRoot;

		[SerializeField]
		private UnityEngine.MonoBehaviour uiPivot;

		[SerializeField]
		protected float maxRecordingDuration = 30f;

		[SerializeField]
		protected string startRecordingPrompt = "Start new recording?";

		[SerializeField]
		protected string dataDeleteConfirmation = "Delete recorded data?";

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		protected Tool tool;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		protected MicAudioRecorder micAudioRecorder;

		private SynchronizedStateMachine synchronizedStateMachine;

		private ManualUpdateStateMachine localStateMachine;

		protected RecordableStackedUI uiInstance;

		protected float recordingStartTime = -1f;

		private SynchronizedField<int> _recordingPlayerId;

		private PhotonPlayer _recordingPlayer;

		private SynchronizedField<string> _blobName;

		protected T localRecordingData;

		private T _dataBlob;

		protected CreationObject creationObject;

		public PhotonPlayer RecordingPlayer => _recordingPlayer;

		protected string BlobName
		{
			get
			{
				return _blobName.Get();
			}
			set
			{
				_blobName.Set(value);
			}
		}

		public T DataBlob
		{
			get
			{
				return _dataBlob;
			}
			protected set
			{
				if (_dataBlob == null || !_dataBlob.Equals(value))
				{
					_dataBlob = value;
					OnDataBlobUpdated();
				}
			}
		}

		public SynchronizedState CurrentSynchronizedState => (SynchronizedState)synchronizedStateMachine.CurrentStateId;

		public LocalState CurrentLocalState => (LocalState)localStateMachine.CurrentStateId;

		public IdleSubstate CurrentIdleSubState
		{
			get
			{
				if (CurrentLocalState != LocalState.IDLE)
				{
					return IdleSubstate.INVALID;
				}
				return (IdleSubstate)localStateMachine.CurrentSubStateId;
			}
		}

		public RecordingSubState CurrentRecordingSubState
		{
			get
			{
				if (CurrentLocalState != LocalState.RECORDING)
				{
					return RecordingSubState.INVALID;
				}
				return (RecordingSubState)localStateMachine.CurrentSubStateId;
			}
		}

		public bool IsRecordingLocally { get; protected set; }

		public virtual bool IsReadyForUse => true;

		protected virtual bool CanStartRecording => (CurrentSynchronizedState == SynchronizedState.IDLE || HasLocalRecordingPermission) && !IsRecordingLocally && !tool.IsHeld && tool.RigidbodyEx.IsSleeping() && !micAudioRecorder.IsRecording && string.IsNullOrEmpty(BlobName) && LocalActiveRecordingObject == null;

		private bool HasLocalRecordingPermission
		{
			get
			{
				PhotonPlayer recordingPlayer = RecordingPlayer;
				return CurrentSynchronizedState == SynchronizedState.RECORDING && recordingPlayer != null && recordingPlayer.IsLocal;
			}
		}

		public string StartRecordingPrompt => startRecordingPrompt;

		public float LocalRecordingProgress
		{
			get
			{
				if (CurrentRecordingSubState != RecordingSubState.ACTIVE && recordingStartTime > 0f)
				{
					return -1f;
				}
				return Mathf.Clamp01((UnityEngine.Time.realtimeSinceStartup - recordingStartTime) / maxRecordingDuration);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			tool.KinematicOnSleep = true;
			tool.PostPickupEvent += Tool_PostPickupEvent;
			tool.PostReleaseEvent += Tool_PostReleaseEvent;
			tool.RigidbodyEx.SleepChangedEvent += RigidbodyEx_SleepChangedEvent;
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			_recordingPlayerId = new SynchronizedField<int>(this, "RO_RP", -1, SetterPermissionMode.MASTER, OnRecordingPlayerIdChanged);
			_blobName = new SynchronizedField<string>(this, "RO_BN", string.Empty, SetterPermissionMode.MASTER, OnBlobNameChanged);
			synchronizedStateMachine = new SynchronizedStateMachine("RO_SM", SetterPermissionMode.MASTER);
			synchronizedStateMachine.AddState(0, null, null, null);
			synchronizedStateMachine.AddState(1, OnEnterRecordingSynchronizedState, OnExitRecordingSynchronizedState, null);
			synchronizedStateMachine.StateChangeEvent += OnAnyStateChanged;
			localStateMachine = new ManualUpdateStateMachine();
			localStateMachine.AddState(0, OnEnterIdleState, null, null);
			localStateMachine.AddState(0, 0, OnEnterNoDataIdleSubstate, null, null);
			localStateMachine.AddState(0, 1, OnEnterPlaybackIdleSubstate, OnExitPlaybackIdleSubstate, OnUpdatePlaybackIdleSubstate);
			localStateMachine.AddState(1, OnEnterOtherPlayerRecordingState, null, null);
			localStateMachine.AddState(2, OnEnterRecordingLocalState, OnExitRecordingLocalState, null);
			localStateMachine.AddState(2, 0, OnEnterCountdownRecordingSubstate, null, null);
			localStateMachine.AddState(2, 1, OnEnterActiveRecordingSubstate, OnExitActiveRecordingSubstate, OnUpdateActiveRecordingSubstate);
			localStateMachine.AddState(2, 2, OnEnterReviewRecordingSubstate, OnExitReviewRecordingSubstate, null);
			localStateMachine.AddState(2, 3, OnEnterUploadRecordingSubstate, OnExitUploadRecordingSubstate, null);
			localStateMachine.StateChangeEvent += OnAnyStateChanged;
		}

		protected virtual void Start()
		{
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
			creationObject = GetComponent<CreationObject>();
			InitializeCreationObjectSettings();
			synchronizedStateMachine.Start(this, 0);
			localStateMachine.Initialize(0);
			RefreshUIAvailability();
			UpdateObjectInteractivity();
			OnBlobNameChanged();
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RecRoom.Systems.PlayerRoles.RoomRole roleDef)
		{
			if (player.IsLocal)
			{
				RefreshUIAvailability();
			}
		}

		protected virtual void InitializeCreationObjectSettings()
		{
			if (!(creationObject != null))
			{
				return;
			}
			ButtonSettingEditEvent settingEvent = new ButtonSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultButtonUIControlPrefab, delegate(CreationObjectSettingButtonUIControl instance)
			{
				instance.PropertyDescription.text = dataDeleteConfirmation;
				instance.InteractibleGetter = DeleteDataSettings_InteractibleGet;
				instance.PropertySetter = delegate(bool buttonPressed)
				{
					if (buttonPressed)
					{
						if (instance.MakerPen != null)
						{
							instance.MakerPen.PaletteMenuToolUI.ShowConfirmationDialog(dataDeleteConfirmation, "Are you sure you want to delete this data?").Then(delegate(ConfirmDialogResponses response)
							{
								if (response == ConfirmDialogResponses.Affirmative)
								{
									RequestDeleteData();
								}
							});
						}
						else
						{
							RequestDeleteData();
						}
					}
				};
			});
			creationObject.AddConfigurableSetting(0, settingEvent);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			tool.PostPickupEvent -= Tool_PostPickupEvent;
			tool.PostReleaseEvent -= Tool_PostReleaseEvent;
			tool.RigidbodyEx.SleepChangedEvent -= RigidbodyEx_SleepChangedEvent;
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
			_dataBlob = default(T);
		}

		protected virtual void Update()
		{
			synchronizedStateMachine.Update();
			localStateMachine.Update();
		}

		private void OnBlobNameChanged()
		{
			DataBlob = default(T);
			if (!string.IsNullOrEmpty(BlobName))
			{
				TryGetBlobData();
			}
		}

		private void OnDataBlobUpdated()
		{
			if (CurrentLocalState == LocalState.IDLE)
			{
				if (DataBlob != null)
				{
					localStateMachine.EnterState(0, 1);
				}
				else
				{
					localStateMachine.EnterState(0, 0);
				}
			}
		}

		protected virtual void OnAnyStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			RefreshUIAvailability();
		}

		private void OnLocalPlayerIsHostChanged(bool isHost)
		{
			RefreshUIAvailability();
		}

		private void Tool_PostPickupEvent(Tool thisTool)
		{
			UpdateObjectInteractivity();
		}

		private void RigidbodyEx_SleepChangedEvent(RigidbodyEx obj)
		{
			UpdateObjectInteractivity();
		}

		private void Tool_PostReleaseEvent(Tool thisTool)
		{
			UpdateObjectInteractivity();
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient && player == RecordingPlayer)
			{
				MasterExitRecordingFlow();
			}
		}

		private void OnRecordingPlayerIdChanged()
		{
			_recordingPlayer = PhotonPlayer.Find(_recordingPlayerId.Get());
		}

		public virtual void MasterSetResourceBlobName(string name)
		{
			if (PhotonNetwork.isMasterClient)
			{
				BlobName = name;
			}
		}

		private void MasterEnterRecordingFlow(PhotonPlayer targetPlayer)
		{
			if (PhotonNetwork.isMasterClient && targetPlayer != null && CanStartRecording)
			{
				_recordingPlayerId.Set(targetPlayer.ID);
				if (RecordingPlayer != null)
				{
					synchronizedStateMachine.EnterState(1);
				}
			}
		}

		private void MasterExitRecordingFlow()
		{
			if (PhotonNetwork.isMasterClient && CurrentSynchronizedState == SynchronizedState.RECORDING)
			{
				_recordingPlayerId.Set(-1);
				synchronizedStateMachine.EnterState(0);
			}
		}

		protected virtual void OnEnterRecordingSynchronizedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (HasLocalRecordingPermission && Player.LocalPlayerExists)
			{
				if (CanStartRecording)
				{
					localStateMachine.EnterState(2, 0);
				}
				else
				{
					base.photonView.RpcMaster(RpcRequestMasterExitRecordingFlow);
				}
			}
			else
			{
				localStateMachine.EnterState(1);
			}
		}

		protected virtual void OnExitRecordingSynchronizedState(ushort nextStateId, ushort nextSubstateId)
		{
			localStateMachine.EnterState(0);
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubstateId)
		{
			OnDataBlobUpdated();
		}

		protected virtual void OnEnterNoDataIdleSubstate(ushort previousStateId, ushort previousSubstateId)
		{
			TryShowBaseUIFlow();
		}

		protected virtual void OnEnterPlaybackIdleSubstate(ushort previousStateId, ushort previousSubstateId)
		{
			TryHideUI();
		}

		protected virtual void OnExitPlaybackIdleSubstate(ushort nextStateId, ushort nextSubstateId)
		{
		}

		protected virtual void OnUpdatePlaybackIdleSubstate()
		{
		}

		protected virtual void OnEnterOtherPlayerRecordingState(ushort previousStateId, ushort previousSubstateId)
		{
			TryHideUI();
		}

		private void OnEnterRecordingLocalState(ushort previousStateId, ushort previousSubstateId)
		{
			LocalActiveRecordingObject = this;
		}

		protected virtual void OnExitRecordingLocalState(ushort nextStateId, ushort nextSubstateId)
		{
			TryShowBaseUIFlow();
			localRecordingData = default(T);
			LocalActiveRecordingObject = null;
		}

		protected virtual void OnEnterCountdownRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			TryShowUIFlow<HolotarCountdownFlow>();
		}

		private void OnEnterActiveRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			TryShowUIFlow<HolotarRecordingFlow>();
			StartLocalRecording();
		}

		protected virtual void OnExitActiveRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			StopRecording(out var _);
		}

		private void OnUpdateActiveRecordingSubstate()
		{
			if (LocalRecordingProgress >= 1f)
			{
				FinishLocalRecording();
			}
		}

		protected virtual void StartLocalRecording()
		{
			if (!IsRecordingLocally)
			{
				recordingStartTime = UnityEngine.Time.realtimeSinceStartup;
				localRecordingData = InitializeRecordingData();
				micAudioRecorder.StartRecording(maxRecordingDuration);
				IsRecordingLocally = true;
			}
		}

		protected void StopRecording(out IPromise<AudioStreamData> audioPromise)
		{
			audioPromise = micAudioRecorder.FinishRecording();
			recordingStartTime = -1f;
			IsRecordingLocally = false;
		}

		protected void EnterReviewRecordingSubstate()
		{
			localStateMachine.EnterState(2, 2);
		}

		protected virtual void OnEnterReviewRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			TryShowUIFlow<HolotarReviewFlow>();
		}

		protected virtual void OnExitReviewRecordingSubstate(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void OnEnterUploadRecordingSubstate(ushort previousStateId, ushort previousSubStateId)
		{
			HolotarUploadingFlow uploadFlow = TryShowUIFlow<HolotarUploadingFlow>() as HolotarUploadingFlow;
			if (localRecordingData != null)
			{
				DataBlobs.UploadTransientData(DataBlobs.DataBlobType.Holotar, localRecordingData.ToByteArray()).Then(delegate(string blobName)
				{
					base.photonView.RpcMaster(RpcRequestMasterSetBlobName, blobName);
					uploadFlow.MarkSuccess();
				}).Error(delegate(string e)
				{
					UnityEngine.Debug.LogWarningFormat("Error uploading recording: {0}", e);
					uploadFlow.MarkFailure();
				});
			}
			else
			{
				UnityEngine.Debug.LogWarningFormat("Error uploading recording: No data recorded.");
				uploadFlow.MarkFailure();
			}
		}

		protected virtual void OnExitUploadRecordingSubstate(ushort nextStateId, ushort nextSubStateId)
		{
		}

		protected virtual bool ShouldShowUI()
		{
			return true;
		}

		protected void RefreshUIAvailability()
		{
			if (ShouldShowUI())
			{
				if (uiInstance == null)
				{
					uiPivot.enabled = true;
					uiInstance = UnityEngine.Object.Instantiate(uiPrefab, uiRoot, worldPositionStays: false);
					uiInstance.GetComponent<RecordableStackedUI>().recordable = this;
					uiInstance.gameObject.SetActive(value: false);
				}
			}
			else
			{
				if (uiInstance != null)
				{
					UnityEngine.Object.Destroy(uiInstance.gameObject);
				}
				uiPivot.enabled = false;
			}
		}

		private void TryShowBaseUIFlow()
		{
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: true);
				uiInstance.PopAllFlows();
			}
		}

		private RecordableUIFlow TryShowUIFlow<V>() where V : RecordableUIFlow
		{
			RecordableUIFlow result = null;
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: true);
				uiInstance.PopAllFlows();
				uiInstance.PushFlow<V>();
				result = uiInstance.CurrentFlow as RecordableUIFlow;
			}
			return result;
		}

		private void TryHideUI()
		{
			if (uiInstance != null)
			{
				uiInstance.gameObject.SetActive(value: false);
			}
		}

		protected abstract T InitializeRecordingData();

		protected abstract void TryGetBlobData();

		protected virtual void UpdateObjectInteractivity()
		{
		}

		protected abstract void FinishLocalRecording();

		public void TryStartRecording()
		{
			if (HasLocalRecordingPermission)
			{
				localStateMachine.EnterState(2, 1);
			}
			else
			{
				UnityEngine.Debug.LogWarning("RecordableObject: Local player does not have permission to begin recording.");
			}
		}

		public void TryFinishRecording()
		{
			if (IsRecordingLocally)
			{
				FinishLocalRecording();
			}
			else
			{
				UnityEngine.Debug.LogWarning("RecordableObject: Local player cannot finish a recording when no recording is active.");
			}
		}

		public void TrySaveRecording()
		{
			if (localRecordingData != null)
			{
				localStateMachine.EnterState(2, 3);
			}
			else
			{
				UnityEngine.Debug.LogWarning("RecordableObject: Unable to save when there is no local recording data.");
			}
		}

		public void TryEnterRecordingFlow()
		{
			if (CanStartRecording && !Profiles.LocalProfile.IsJunior())
			{
				base.photonView.RpcMaster(RpcRequestMasterEnterRecordingFlow);
			}
			else
			{
				UnityEngine.Debug.LogWarning("RecordableObject: Unable to enter recording flow.");
			}
		}

		public void TryExitRecordingFlow()
		{
			if (HasLocalRecordingPermission)
			{
				base.photonView.RpcMaster(RpcRequestMasterExitRecordingFlow);
			}
			else
			{
				UnityEngine.Debug.LogWarning("RecordableObject: Local player does not have permission to exit recording flow.");
			}
		}

		public void RequestDeleteData()
		{
			base.photonView.RpcMaster(RpcRequestMasterSetBlobName, string.Empty);
		}

		public bool DeleteDataSettings_InteractibleGet()
		{
			return !string.IsNullOrEmpty(BlobName);
		}

		[PunRPC]
		protected void RpcRequestMasterEnterRecordingFlow(PhotonMessageInfo photonMessageInfo)
		{
			MasterEnterRecordingFlow(photonMessageInfo.sender);
		}

		[PunRPC]
		protected void RpcRequestMasterExitRecordingFlow()
		{
			MasterExitRecordingFlow();
		}

		[PunRPC]
		protected void RpcRequestMasterSetBlobName(string blobName, PhotonMessageInfo photonMessageInfo)
		{
			BlobName = blobName;
		}
	}
	public class AudioSamplerStartRecordingFlow : RecordableUIFlow
	{
		[SerializeField]
		private Text label;

		[SerializeField]
		private Button3D button;

		[SkipRename]
		public void Button_StartRecording()
		{
			base.Recordable.TryEnterRecordingFlow();
		}

		private void Update()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.Mute)
			{
				button.gameObject.SetActive(value: false);
				label.text = "Go to your settings to enable your mic!";
			}
			else if (base.Recordable != null)
			{
				button.gameObject.SetActive(value: true);
				label.text = base.Recordable.StartRecordingPrompt;
			}
		}
	}
	public class AudioSamplerUIPivot : UnityEngine.MonoBehaviour
	{
