	public class HolotarCountdownFlow : RecordableUIFlow
	{
		[SerializeField]
		private int countdownLength = 5;

		[SerializeField]
		private Text timeLabel;

		[SerializeField]
		private UnityEngine.UI.Image countdownFillImage;

		[SerializeField]
		private RecRoomAudioClip beepSfx;

		[SerializeField]
		private RecRoomAudioClip recordingStartSfx;

		private float timeRemaining;

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			StartCoroutine(RunCountdown());
		}

		private IEnumerator RunCountdown()
		{
			timeRemaining = countdownLength;
			while (timeRemaining > 0f)
			{
				int previousInt = Mathf.FloorToInt(timeRemaining);
				timeRemaining = Mathf.Max(0f, timeRemaining - UnityEngine.Time.deltaTime);
				UpdateUI();
				int nowInt = Mathf.FloorToInt(timeRemaining);
				if (previousInt != nowInt)
				{
					AudioManager.Play3DSFX(beepSfx, base.transform.position);
				}
				yield return 0;
			}
			AudioManager.Play3DSFX(recordingStartSfx, base.transform.position);
			yield return new WaitForSeconds(recordingStartSfx.audioClip.length);
			base.Recordable.TryStartRecording();
		}

		private void UpdateUI()
		{
			timeLabel.text = Mathf.FloorToInt(timeRemaining + 1f).ToString();
			countdownFillImage.fillAmount = 1f - timeRemaining % 1f;
		}

		[SkipRename]
		public void Button_CancelCountdown()
		{
			base.Recordable.TryExitRecordingFlow();
		}
	}
