	public class HolotarUploadingFlow : RecordableUIFlow
	{
		private const int MIN_DOTS = 1;

		private const int MAX_DOTS = 3;

		[SerializeField]
		private Text label;

		private Coroutine activeRoutine;

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			this.SafeStopCoroutine(activeRoutine);
			activeRoutine = StartCoroutine(RunIdleAnimation());
		}

		public void MarkSuccess()
		{
			this.SafeStopCoroutine(activeRoutine);
			activeRoutine = StartCoroutine(RunCompleteAnimation("Upload complete!"));
		}

		public void MarkFailure()
		{
			this.SafeStopCoroutine(activeRoutine);
			activeRoutine = StartCoroutine(RunCompleteAnimation("Upload failed..."));
		}

		private IEnumerator RunIdleAnimation()
		{
			string baseMessage = "Uploading";
			string message = baseMessage;
			int dots = 1;
			while (true)
			{
				if (dots == 1)
				{
					message = baseMessage;
				}
				message += ".";
				int num = dots + 1;
				dots = num % 3;
				label.text = message;
				yield return new WaitForSeconds(0.5f);
			}
		}

		private IEnumerator RunCompleteAnimation(string message)
		{
			label.text = message;
			yield return new WaitForSeconds(2f);
			base.Recordable.TryExitRecordingFlow();
		}
	}
