namespace RecRoom.Core.Creation
{
	public class BaseUIPivot : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		protected float rotationSpeed = 2f;

		[NonSerialized]
		public Transform TargetTransform;

		private void Start()
		{
			this.Update30hz(delegate
			{
				UpdatePivot();
			});
		}

		private void UpdatePivot()
		{
			if (ShouldUpdate())
			{
				Vector3 vector = base.transform.InverseTransformPoint(GetTargetPosition());
				float num = Quaternion.FromToRotation(Vector3.forward, vector.normalized).eulerAngles.y;
				if (num > 180f)
				{
					num -= 360f;
				}
				float num2 = rotationSpeed * UnityEngine.Time.deltaTime;
				num2 = Mathf.Min(Mathf.Abs(num), rotationSpeed * UnityEngine.Time.deltaTime);
				float angle = num2 * Mathf.Sign(num);
				base.transform.Rotate(Vector3.up, angle, Space.Self);
			}
		}

		protected virtual bool ShouldUpdate()
		{
			return TargetTransform != null || Player.LocalPlayerExists;
		}

		protected virtual Vector3 GetTargetPosition()
		{
			if (TargetTransform != null)
			{
				return TargetTransform.position;
			}
			return Player.LocalPlayer.CurrentFloorPosition;
		}
	}
}
public class SFXAudioSource : UnityEngine.MonoBehaviour
{
	public bool Is3DSFX;

	private Action<SFXAudioSource> audioSourceReleaseCallback;

	private AudioSource _audioSource;

	public Transform FollowTarget { get; set; }

	public AudioSource AudioSource => _audioSource;

	private void Awake()
	{
		_audioSource = GetComponent<AudioSource>();
	}

	private void OnDisable()
	{
		CancelInvoke("Release");
		FollowTarget = null;
		if (_audioSource != null)
		{
			_audioSource.loop = false;
		}
	}

	private void Update()
	{
		if (Is3DSFX && FollowTarget != null)
		{
			base.transform.position = FollowTarget.position;
		}
	}

	public void Play(AudioClip clip, float volume, Vector3 point, float pitchVariation, float pitchShift, AudioRolloff rolloff, Action<SFXAudioSource> onAudioSourceReleaseCallback = null)
	{
		base.transform.position = point;
		_audioSource.clip = clip;
		_audioSource.volume = volume;
		audioSourceReleaseCallback = onAudioSourceReleaseCallback;
		float num = 1f + pitchShift;
		if (pitchVariation > 0f)
		{
			num += UnityEngine.Random.Range(0f - pitchVariation, pitchVariation);
		}
		_audioSource.pitch = num;
		if (Is3DSFX)
		{
			_audioSource.SetAudioRolloff(rolloff);
		}
		_audioSource.Play();
		Invoke("Release", clip.length);
	}

	public void Loop()
	{
		if (_audioSource.isPlaying)
		{
			_audioSource.loop = true;
			CancelInvoke("Release");
		}
	}

	public void Scrub(float time)
	{
		if (_audioSource.isPlaying && time <= _audioSource.time)
		{
			_audioSource.time = time;
			float time2 = _audioSource.clip.length - time;
			CancelInvoke("Release");
			Invoke("Release", time2);
		}
	}

	public void Stop()
	{
		_audioSource.Stop();
		_audioSource.clip = null;
	}

	public void Release()
	{
		FollowTarget = null;
		CancelInvoke("Release");
		if (_audioSource.isPlaying)
		{
			_audioSource.Stop();
		}
		_audioSource.loop = false;
		ObjectPool.Instance.Release(this);
		if (audioSourceReleaseCallback != null)
		{
			audioSourceReleaseCallback(this);
			audioSourceReleaseCallback = null;
		}
	}
}
namespace RecRoom.Content.VFX
{
	[ExecuteInEditMode]
	[RequireComponent(typeof(Light))]
	public class WaterCausticsLight : UnityEngine.MonoBehaviour
	{
		[Header("Textures")]
		[SerializeField]
		private Texture alphaMap;

		[SerializeField]
		private Texture displacementNormals;

		[SerializeField]
		private RenderTexture cookie;

		[SerializeField]
		private Shader causticsShader;

		[Header("Motion")]
		[SerializeField]
		[Range(0f, 1f)]
		private float distortAmount;

		[SerializeField]
		private Vector2 alphaSpeed;

		[SerializeField]
		private Vector2 distortSpeed;

		private Vector4 textureSpeeds;

		[Header("World Integration")]
		[SerializeField]
		[Range(0f, 1f)]
		private float causticsAmount;

		[SerializeField]
		private bool useHeightBlend;

		[SerializeField]
		private float heightBlendStart = 0.5f;

		[SerializeField]
		private Color heightBlendStartLightColor = Color.white;

		[SerializeField]
		private float heightBlendEnd = -0.5f;

		[SerializeField]
		private Color heightBlendEndLightColor = Color.white;

		private Material causticsCookieMat;

		private static readonly int normalMapShaderId = Shader.PropertyToID("_NormalMap");

		private static readonly int distortAmountShaderId = Shader.PropertyToID("_DistortAmount");

		private static readonly int textureSpeedsShaderId = Shader.PropertyToID("_Speeds");

		private static readonly int causticsAmountShaderId = Shader.PropertyToID("_CausticsAmount");

		private Light targetLight;

		private void Start()
		{
			targetLight = GetComponent<Light>();
			if (targetLight.type != LightType.Directional)
			{
				UnityEngine.Debug.LogWarning("WaterCausticsLight only works with Directional lights. Disabling effect.", this);
				base.enabled = false;
			}
			else
			{
				causticsCookieMat = new Material(causticsShader);
			}
		}

		private void Update()
		{
			if ((bool)alphaMap && (bool)cookie && (bool)causticsCookieMat)
			{
				float num = causticsAmount;
				Transform transform = null;
				if (SingletonMonoBehaviour<CameraRig>.Instance != null)
				{
					transform = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform;
				}
				if ((bool)transform && useHeightBlend)
				{
					float num2 = base.transform.position.y - heightBlendStart;
					float num3 = base.transform.position.y - heightBlendEnd;
					float num4 = 1f - Mathf.Clamp01(transform.position.y - num3 / num2 - num3);
					num *= num4;
					targetLight.color = Color.Lerp(heightBlendStartLightColor, heightBlendEndLightColor, num4);
				}
				targetLight.cookie = cookie;
				textureSpeeds.x = alphaSpeed.x;
				textureSpeeds.y = alphaSpeed.y;
				textureSpeeds.z = distortSpeed.x;
				textureSpeeds.w = distortSpeed.y;
				causticsCookieMat.SetTexture(normalMapShaderId, displacementNormals);
				causticsCookieMat.SetFloat(distortAmountShaderId, distortAmount);
				causticsCookieMat.SetVector(textureSpeedsShaderId, textureSpeeds);
				causticsCookieMat.SetFloat(causticsAmountShaderId, num);
				Graphics.Blit(alphaMap, cookie, causticsCookieMat);
			}
		}

		private void OnDestroy()
		{
			SafeDestroy.Asset(causticsCookieMat);
		}

		private void OnDrawGizmosSelected()
		{
			if (useHeightBlend)
			{
				Vector3 vector = new Vector3(base.transform.position.x, base.transform.position.y - heightBlendStart, base.transform.position.z);
				Vector3 vector2 = new Vector3(base.transform.position.x, base.transform.position.y - heightBlendEnd, base.transform.position.z);
				Vector3 to = new Vector3(base.transform.position.x, vector2.y - 10000f, base.transform.position.z);
				Gizmos.color = Color.Lerp(Color.red, Color.white, 0.33f);
				Gizmos.DrawLine(base.transform.position, vector);
				Gizmos.color = Color.Lerp(Color.cyan, Color.white, 0.33f);
				Gizmos.DrawLine(vector, vector2);
				Gizmos.color = Color.Lerp(Color.blue, Color.white, 0.33f);
				Gizmos.DrawLine(vector2, to);
			}
		}
	}
}
