public static class AGRoomSettings
{
	private static readonly string ConfigsAssetFilePath = "Assets/Core/Content/Configs";

	private static AGRoomRuntimeConfig ConfigAsset = CustomSettingsLoader.LoadConfig<AGRoomRuntimeConfig>();

	private static bool SupportsEditorOnly => false;

	public static bool TryGetRoomSceneLocationFromSceneName(string sceneName, out RoomSceneLocations location)
	{
		int levelRoomIndex = -1;
		return TryGetRoomSceneLocationFromSceneName(sceneName, out location, out levelRoomIndex);
	}

	public static bool TryGetRoomSceneLocationFromSceneName(string sceneName, out RoomSceneLocations location, out int levelRoomIndex)
	{
		location = RoomSceneLocations.INVALID;
		levelRoomIndex = -1;
		if (ConfigAsset != null && !string.IsNullOrEmpty(sceneName))
		{
			for (int i = 0; i < ConfigAsset.Locations.Length; i++)
			{
				if (ConfigAsset.Locations[i].SceneName == sceneName)
				{
					location = ConfigAsset.Locations[i].LocationEnum;
					return true;
				}
				if (ConfigAsset.Locations[i].RequiredSubSceneNames != null)
				{
					for (int j = 0; j < ConfigAsset.Locations[i].RequiredSubSceneNames.Length; j++)
					{
						if (ConfigAsset.Locations[i].RequiredSubSceneNames[j] == sceneName)
						{
							location = ConfigAsset.Locations[i].LocationEnum;
							return true;
						}
					}
				}
				if (ConfigAsset.Locations[i].LevelRoomSubSceneNames == null)
				{
					continue;
				}
				for (int k = 0; k < ConfigAsset.Locations[i].LevelRoomSubSceneNames.Length; k++)
				{
					if (ConfigAsset.Locations[i].LevelRoomSubSceneNames[k] == sceneName)
					{
						location = ConfigAsset.Locations[i].LocationEnum;
						levelRoomIndex = k;
						return true;
					}
				}
			}
		}
		return false;
	}

	public static string[] GetAllRoomSceneLocationNames()
	{
		List<string> list = new List<string>();
		if (ConfigAsset != null)
		{
			AGRoomRuntimeConfig.Location[] locations = ConfigAsset.Locations;
			foreach (AGRoomRuntimeConfig.Location location in locations)
			{
				list.Add(location.Name);
			}
		}
		return list.ToArray();
	}

	public static string GetSceneNameFromRoomSceneLocation(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.SceneName;
	}

	public static string[] GetRequiredSubSceneNamesFromRoomSceneLocation(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.RequiredSubSceneNames;
	}

	public static string[] GetLevelRoomSubSceneNamesFromRoomSceneLocation(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.LevelRoomSubSceneNames;
	}

	public static int GetRoomSceneLocationSubSceneCount(RoomSceneLocations location)
	{
		AGRoomRuntimeConfig.Location roomSceneLocationConfig = GetRoomSceneLocationConfig(location);
		if (roomSceneLocationConfig != null)
		{
			return roomSceneLocationConfig.LevelRoomSubSceneNames.Length;
		}
		return 0;
	}

	public static string GetRoomSceneLocationSubSceneAtIndex(RoomSceneLocations location, int index)
	{
		AGRoomRuntimeConfig.Location roomSceneLocationConfig = GetRoomSceneLocationConfig(location);
		if (roomSceneLocationConfig != null && index >= 0 && roomSceneLocationConfig.LevelRoomSubSceneNames.Length > index)
		{
			return roomSceneLocationConfig.LevelRoomSubSceneNames[index];
		}
		return null;
	}

	public static bool TryGetRoomFromLocation(RoomSceneLocations location, out string roomName, out string roomSceneName)
	{
		roomName = null;
		roomSceneName = null;
		AGRoomRuntimeConfig.Location roomSceneLocationConfig = GetRoomSceneLocationConfig(location);
		if (roomSceneLocationConfig != null)
		{
			for (int i = 0; i < ConfigAsset.Rooms.Length; i++)
			{
				for (int j = 0; j < ConfigAsset.Rooms[i].Scenes.Length; j++)
				{
					if (ConfigAsset.Rooms[i].Scenes[j].RoomSceneLocationId == roomSceneLocationConfig.ReplicationId)
					{
						roomName = ConfigAsset.Rooms[i].Name;
						roomSceneName = ConfigAsset.Rooms[i].Scenes[j].Name;
						return true;
					}
				}
			}
		}
		return false;
	}

	private static bool TryGetLocationConfigById(string replicationId, out AGRoomRuntimeConfig.Location locationConfig)
	{
		if (ConfigAsset != null)
		{
			for (int i = 0; i < ConfigAsset.Locations.Length; i++)
			{
				if (ConfigAsset.Locations[i].ReplicationId == replicationId)
				{
					locationConfig = ConfigAsset.Locations[i];
					return true;
				}
			}
		}
		locationConfig = null;
		return false;
	}

	private static bool TryGetRoomConfigById(string replicationId, out AGRoomRuntimeConfig.Room roomConfig)
	{
		if (ConfigAsset != null)
		{
			for (int i = 0; i < ConfigAsset.Rooms.Length; i++)
			{
				if (ConfigAsset.Rooms[i].ReplicationId == replicationId)
				{
					roomConfig = ConfigAsset.Rooms[i];
					return true;
				}
			}
		}
		roomConfig = null;
		return false;
	}

	private static bool TryGetRoomSceneConfigById(string replicationId, out AGRoomRuntimeConfig.Room roomConfig, out AGRoomRuntimeConfig.RoomScene roomSceneConfig)
	{
		if (ConfigAsset != null)
		{
			for (int i = 0; i < ConfigAsset.Rooms.Length; i++)
			{
				for (int j = 0; j < ConfigAsset.Rooms[i].Scenes.Length; j++)
				{
					if (ConfigAsset.Rooms[i].Scenes[j].ReplicationId == replicationId)
					{
						roomConfig = ConfigAsset.Rooms[i];
						roomSceneConfig = ConfigAsset.Rooms[i].Scenes[j];
						return true;
					}
				}
			}
		}
		roomConfig = null;
		roomSceneConfig = null;
		return false;
	}

	public static bool TryGetRoomSceneLocationById(string replicationId, out RoomSceneLocations location)
	{
		if (TryGetLocationConfigById(replicationId, out var locationConfig))
		{
			location = locationConfig.LocationEnum;
			return true;
		}
		location = RoomSceneLocations.INVALID;
		return false;
