	{
		if (TryGetLocationConfigById(replicationId, out var locationConfig))
		{
			return locationConfig.Name;
		}
		return null;
	}

	public static string TryGetRoomNameById(string replicationId)
	{
		if (TryGetRoomConfigById(replicationId, out var roomConfig))
		{
			return roomConfig.Name;
		}
		return null;
	}

	public static string TryGetRoomSceneNameById(string replicationId)
	{
		if (TryGetRoomSceneConfigById(replicationId, out var _, out var roomSceneConfig))
		{
			return roomSceneConfig.Name;
		}
		return null;
	}

	public static int GetMaxPlayers(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.MaxPlayers ?? 0;
	}

	public static string GetRoomSceneLocationReplicationId(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.ReplicationId;
	}

	public static string GetRoomSceneLocationName(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.Name;
	}

	public static bool IsGameModeTypeSupported(RoomSceneLocations location, GameModeType gameModeType)
	{
		AGRoomRuntimeConfig.Location roomSceneLocationConfig = GetRoomSceneLocationConfig(location);
		if (roomSceneLocationConfig != null)
		{
			return roomSceneLocationConfig.SupportedGameMode == GameModeType.INVALID || roomSceneLocationConfig.SupportedGameMode == gameModeType;
		}
		return true;
	}

	public static bool TryGetRoomSceneLocationCustomTeamColors(RoomSceneLocations location, out GameTeamColorSettings colorSettings)
	{
		AGRoomRuntimeConfig.Location roomSceneLocationConfig = GetRoomSceneLocationConfig(location);
		if (roomSceneLocationConfig != null)
		{
			colorSettings = roomSceneLocationConfig.GameTeamColorSettings;
			return true;
		}
		colorSettings = default(GameTeamColorSettings);
		return false;
	}

	public static GiftManager.GiftContext GetRoomSceneLocationGiftContext(RoomSceneLocations location)
	{
		return GetRoomSceneLocationConfig(location)?.GiftContext ?? GiftManager.GiftContext.None;
	}

	public static int GetRoomSceneLocationIndex(RoomSceneLocations location)
	{
		if (location == RoomSceneLocations.INVALID)
		{
			return -1;
		}
		return (int)location;
	}

	public static AGRoomRuntimeConfig.Location GetRoomSceneLocationConfig(RoomSceneLocations location)
	{
		if (location == RoomSceneLocations.INVALID || ConfigAsset == null)
		{
			return null;
		}
		int roomSceneLocationIndex = GetRoomSceneLocationIndex(location);
		if (roomSceneLocationIndex < 0 || roomSceneLocationIndex >= ConfigAsset.Locations.Length || (ConfigAsset.Locations[roomSceneLocationIndex].ReleaseStatus == ReleaseStatus.EditorOnly && !SupportsEditorOnly))
		{
			return null;
		}
		return ConfigAsset.Locations[roomSceneLocationIndex];
	}
}
namespace RecRoom
{
	public class SandboxRuleManager : GameRuleManager
	{
		[SerializeField]
		private RecRoomAudioClip hitNotificationAudio;

		[SerializeField]
		private PooledParticle hitNotificationParticles;

		[SerializeField]
		private Color hitNotificationColor = new Color(0.9f, 0.17f, 0.17f);

		public new static SandboxRuleManager Instance => NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance as SandboxRuleManager;

		public override string RuleTypeAutoTag => "sandbox";

		protected override void Awake()
		{
			base.Awake();
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent += OnPlayerDamagedPlayer;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameModeNotification = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameOverGiftGeneration = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.supportsGameOverGiftDequeing = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameStart = false;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.respawnsPlayersOnGameOver = false;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent -= OnPlayerDamagedPlayer;
			}
		}

		private void OnPlayerDamagedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (hitNotificationParticles != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(hitNotificationParticles);
				pooledParticle.Play(impactPoint, Quaternion.identity);
			}
			if (hitNotificationAudio != null)
			{
				if (defender.IsLocal || attacker.IsLocal)
				{
					AudioManager.Play2DSFX(hitNotificationAudio);
				}
				else
				{
					AudioManager.Play3DSFX(hitNotificationAudio, impactPoint);
				}
			}
			if (defender.IsLocal)
			{
				GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(attacker);
				Color teamColor = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "HIT!", hitNotificationColor, attacker.NickName, teamColor, 2f);
			}
			else if (attacker.IsLocal)
			{
				GameTeam playerTeam2 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(defender);
				Color teamColor2 = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam2);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "YOU HIT", defender.NickName, teamColor2, 2f);
			}
		}
	}
