namespace RecRoom.Core.Encounters
{
	[RequireComponent(typeof(PhotonView))]
	public class GameEncounter : Photon.MonoBehaviour
	{
		private enum States
		{
			INACTIVE,
			WAITING_FOR_TRIGGER,
			RUNNING_STEPS,
			FINISHED
		}

		private enum RunningStepsSubStates
		{
			WAITING_FOR_STEP_COMPLETION,
			INITIAL_STEP
		}

		private enum InstantiationValues
		{
			INSTANTIATOR_ID,
			INSTANTIATION_PARAMS,
			AUTOMATICALLY_ACTIVATE,
			TEAM_ID,
			OVERRIDE_PATROL_ID,
			VALUE_COUNT
		}

		public delegate void GameEncounterAction(GameEncounter encounter);

		[SerializeField]
		private GameEncounterStartTrigger[] startTriggers;

		[SerializeField]
		private GameEncounterStep[] steps;

		private SynchronizedTimer stepTimer;

		private SynchronizedTimer encounterTimer;

		private SynchronizedStateMachine stateMachine;

		private bool wasRuntimeInstantiated;

		private bool automaticallyActivate;

		private bool isInitialized;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static GameEncounterAction m_GameEncounterInstantiatedEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static GameEncounterAction m_GameEncounterDestroyedEvent;

		public int InstantiatorPhotonViewId { get; private set; }

		public Dictionary<string, object> InstantiationParameters { get; private set; }

		public GameTeam Team { get; private set; }

		public EnemyPatrol OverridePatrol { get; private set; }

		public bool IsActive => stateMachine.CurrentStateId != 0;

		public bool IsRunning => stateMachine.CurrentStateId == 2;

		public bool IsFinished => stateMachine.CurrentStateId == 3;

		public bool IsWaitingForTrigger => stateMachine.CurrentStateId == 1;

		public GameManager Game { get; private set; }

		public static event GameEncounterAction GameEncounterInstantiatedEvent
		{
			add
			{
				GameEncounterAction gameEncounterAction = GameEncounter.m_GameEncounterInstantiatedEvent;
				GameEncounterAction gameEncounterAction2;
				do
				{
					gameEncounterAction2 = gameEncounterAction;
					gameEncounterAction = Interlocked.CompareExchange(ref GameEncounter.m_GameEncounterInstantiatedEvent, (GameEncounterAction)Delegate.Combine(gameEncounterAction2, value), gameEncounterAction);
				}
				while (gameEncounterAction != gameEncounterAction2);
			}
			remove
			{
				GameEncounterAction gameEncounterAction = GameEncounter.m_GameEncounterInstantiatedEvent;
				GameEncounterAction gameEncounterAction2;
				do
				{
					gameEncounterAction2 = gameEncounterAction;
					gameEncounterAction = Interlocked.CompareExchange(ref GameEncounter.m_GameEncounterInstantiatedEvent, (GameEncounterAction)Delegate.Remove(gameEncounterAction2, value), gameEncounterAction);
				}
				while (gameEncounterAction != gameEncounterAction2);
			}
		}

		public static event GameEncounterAction GameEncounterDestroyedEvent
		{
			add
			{
				GameEncounterAction gameEncounterAction = GameEncounter.m_GameEncounterDestroyedEvent;
				GameEncounterAction gameEncounterAction2;
				do
				{
					gameEncounterAction2 = gameEncounterAction;
					gameEncounterAction = Interlocked.CompareExchange(ref GameEncounter.m_GameEncounterDestroyedEvent, (GameEncounterAction)Delegate.Combine(gameEncounterAction2, value), gameEncounterAction);
				}
				while (gameEncounterAction != gameEncounterAction2);
			}
			remove
			{
				GameEncounterAction gameEncounterAction = GameEncounter.m_GameEncounterDestroyedEvent;
				GameEncounterAction gameEncounterAction2;
				do
				{
					gameEncounterAction2 = gameEncounterAction;
					gameEncounterAction = Interlocked.CompareExchange(ref GameEncounter.m_GameEncounterDestroyedEvent, (GameEncounterAction)Delegate.Remove(gameEncounterAction2, value), gameEncounterAction);
				}
				while (gameEncounterAction != gameEncounterAction2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			stepTimer = new SynchronizedTimer(this, "EST", SetterPermissionMode.MASTER);
			encounterTimer = new SynchronizedTimer(this, "EET", SetterPermissionMode.MASTER);
			stateMachine = new SynchronizedStateMachine("ESM", SetterPermissionMode.MASTER);
			stateMachine.AddState(0, OnEnterInactiveState, null, OnUpdateInactiveState);
			stateMachine.AddState(1, OnEnterWaitingForTriggerState, OnExitWaitingForTriggersState, OnUpdateWaitingForTriggerState);
			stateMachine.AddState(3, OnEnterFinishedState, null, OnUpdateFinishedState);
			stateMachine.AddState(2, OnEnterRunningStepsState, OnExitRunningStepsState, null);
			stateMachine.AddState(2, 0, null, null, OnUpdateWaitingForStepsSubState);
			for (int i = 0; i < steps.Length; i++)
			{
				stateMachine.AddState(2, GetStepSubStateId(i), OnEnterRunningCurrentStepSubState, OnExitRunningCurrentStepSubState, OnUpdateRunningCurrentStepSubState);
				steps[i].OnAwake(this, i, encounterTimer, stepTimer);
			}
			if (startTriggers != null)
			{
				for (int j = 0; j < startTriggers.Length; j++)
				{
					startTriggers[j].OnAwake(this, j);
				}
			}
			wasRuntimeInstantiated = base.photonView.instantiationData != null && base.photonView.instantiationData.Length == 5;
			if (wasRuntimeInstantiated)
			{
				InstantiatorPhotonViewId = (int)base.photonView.instantiationData[0];
				InstantiationParameters = (Dictionary<string, object>)base.photonView.instantiationData[1];
				Team = (GameTeam)base.photonView.instantiationData[3];
				PhotonView photonView = PhotonView.Find((int)base.photonView.instantiationData[4]);
				OverridePatrol = ((!(photonView != null)) ? null : photonView.GetComponent<EnemyPatrol>());
				automaticallyActivate = (bool)base.photonView.instantiationData[2];
			}
			else
			{
				InstantiatorPhotonViewId = -1;
				InstantiationParameters = null;
				Team = GameTeam.ANY;
				OverridePatrol = null;
				automaticallyActivate = false;
			}
		}

		private void Start()
		{
			Initialize();
			if (wasRuntimeInstantiated && GameEncounter.GameEncounterInstantiatedEvent != null)
			{
				GameEncounter.GameEncounterInstantiatedEvent(this);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			for (int i = 0; i < steps.Length; i++)
			{
				steps[i].OnCleanup();
			}
			if (startTriggers != null)
			{
				for (int j = 0; j < startTriggers.Length; j++)
				{
					startTriggers[j].OnCleanup();
				}
			}
			if (base.photonView.instantiationData != null && base.photonView.instantiationData.Length == 5 && GameEncounter.GameEncounterDestroyedEvent != null)
			{
				GameEncounter.GameEncounterDestroyedEvent(this);
			}
		}

		public void Initialize()
		{
			if (!isInitialized)
			{
				Game = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
				States states = (automaticallyActivate ? States.WAITING_FOR_TRIGGER : States.INACTIVE);
				stateMachine.Start(this, (ushort)states);
				isInitialized = true;
			}
		}

		public T GetStep<T>() where T : GameEncounterStep
		{
			return GetStepBeforeIndex<T>(steps.Length);
		}

		public T GetStepBeforeIndex<T>(int maxIndex) where T : GameEncounterStep
		{
			T result = (T)null;
			for (int i = 0; i < maxIndex && i < steps.Length; i++)
			{
				T val = ((!(steps[i] != null)) ? ((T)null) : (steps[i] as T));
				if (val != null)
				{
					result = val;
					break;
				}
			}
			return result;
		}

		public T[] GetSteps<T>() where T : GameEncounterStep
		{
			return GetStepsBeforeIndex<T>(steps.Length);
		}

		public T[] GetStepsBeforeIndex<T>(int maxIndex) where T : GameEncounterStep
		{
			List<T> list = new List<T>();
			for (int i = 0; i < maxIndex && i < steps.Length; i++)
			{
				T val = ((!(steps[i] != null)) ? ((T)null) : (steps[i] as T));
				if (val != null)
				{
					list.Add(val);
				}
			}
			return list.ToArray();
		}

		public int GetStepCount<T>() where T : GameEncounterStep
		{
			return GetStepCountBeforeIndex<T>(steps.Length);
		}

		public int GetStepCountBeforeIndex<T>(int maxIndex) where T : GameEncounterStep
		{
			int num = 0;
			for (int i = 0; i < maxIndex && i < steps.Length; i++)
			{
				if (steps[i] != null && steps[i] is T)
				{
					num++;
				}
			}
			return num;
		}

		private ushort GetStepSubStateId(int stepIndex)
		{
			return (ushort)(stepIndex + 1);
		}

		private int GetCurrentStepIndex()
		{
			return stateMachine.CurrentSubStateId - 1;
		}

		private GameEncounterStep GetCurrentStep()
		{
			int currentStepIndex = GetCurrentStepIndex();
			return (currentStepIndex < 0 || currentStepIndex >= steps.Length) ? null : steps[currentStepIndex];
		}

		public void MasterActivate()
		{
			if (PhotonNetwork.isMasterClient && stateMachine.CurrentStateId == 0)
			{
				stateMachine.EnterState(1);
			}
		}

		public void MasterDeactivate()
		{
			if (PhotonNetwork.isMasterClient && stateMachine.CurrentStateId != 0)
			{
				stateMachine.EnterState(0);
			}
		}

		private void Update()
		{
			stateMachine.Update();
			stepTimer.UpdateCallbacks();
			encounterTimer.UpdateCallbacks();
		}

		private void OnActivate()
		{
			if (startTriggers != null)
			{
				for (int i = 0; i < startTriggers.Length; i++)
				{
					startTriggers[i].OnEncounterActivate();
				}
			}
			if (steps != null)
			{
				for (int j = 0; j < steps.Length; j++)
				{
					steps[j].OnEncounterActivate();
				}
			}
		}

		private void OnDeactivate()
		{
			if (startTriggers != null)
			{
				for (int i = 0; i < startTriggers.Length; i++)
				{
					startTriggers[i].OnEncounterDeactivate();
				}
			}
			if (steps != null)
			{
				for (int j = 0; j < steps.Length; j++)
				{
					steps[j].OnEncounterDeactivate();
				}
			}
		}

		private void OnEnterInactiveState(ushort previousStateId, ushort previousSubStateId)
		{
			OnDeactivate();
		}

		private void OnUpdateInactiveState()
		{
			if (wasRuntimeInstantiated && PhotonNetwork.isMasterClient)
			{
				MasterDestroy(this);
			}
		}

		private void OnEnterWaitingForTriggerState(ushort previousStateIs, ushort previousSubStateId)
		{
			OnActivate();
			if (startTriggers != null)
			{
				for (int i = 0; i < startTriggers.Length; i++)
				{
					startTriggers[i].StartListening();
				}
			}
		}

		private void OnUpdateWaitingForTriggerState()
		{
			if (PhotonNetwork.isMasterClient && AllTriggersHaveTriggered())
			{
				if (steps.Length == 0)
				{
					stateMachine.EnterState(3);
				}
				else
				{
					stateMachine.EnterState(2, 1);
				}
			}
		}

		private void OnExitWaitingForTriggersState(ushort nextStateId, ushort nextSubStateId)
		{
			if (startTriggers != null)
			{
				for (int i = 0; i < startTriggers.Length; i++)
				{
					startTriggers[i].StopListening();
				}
			}
		}

		private bool AllTriggersHaveTriggered()
		{
			if (startTriggers != null)
			{
				for (int i = 0; i < startTriggers.Length; i++)
				{
					if (!startTriggers[i].IsTriggered())
					{
						return false;
					}
				}
			}
			return true;
		}

		private void OnEnterRunningStepsState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!isInitialized)
			{
				OnActivate();
			}
			if (PhotonNetwork.isMasterClient)
			{
				encounterTimer.StartTimerWithoutMaxRunningTime();
			}
			int currentStepIndex = GetCurrentStepIndex();
			for (int i = 0; i < steps.Length; i++)
			{
				steps[i].OnEncounterStart();
				if (i < currentStepIndex)
				{
					steps[i].OnSkipRunning();
				}
			}
		}

		private void OnExitRunningStepsState(ushort nextStateId, ushort nextSubStateId)
		{
			for (int i = 0; i < steps.Length; i++)
			{
				steps[i].OnEncounterStop();
			}
		}

		private void OnEnterRunningCurrentStepSubState(ushort previousStateId, ushort previousSubStateId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				stepTimer.StartTimerWithoutMaxRunningTime();
			}
			GameEncounterStep currentStep = GetCurrentStep();
			if (currentStep != null)
			{
				currentStep.OnStartRunning();
			}
		}

		private void OnUpdateRunningCurrentStepSubState()
		{
			GameEncounterStep currentStep = GetCurrentStep();
			if (currentStep != null)
			{
				currentStep.OnUpdateRunning();
			}
			if (PhotonNetwork.isMasterClient && (currentStep == null || !currentStep.IsBlockingEncounterEnd()))
			{
				int currentStepIndex = GetCurrentStepIndex();
				int num = currentStepIndex + 1;
				if (num < steps.Length)
				{
					stateMachine.EnterState(2, GetStepSubStateId(num));
				}
				else
				{
					stateMachine.EnterState(2, 0);
				}
			}
		}

		private void OnExitRunningCurrentStepSubState(ushort nextStateId, ushort nextSubStateId)
		{
			GameEncounterStep currentStep = GetCurrentStep();
			if (currentStep != null)
			{
				currentStep.OnStopRunning();
			}
		}

		private void OnUpdateWaitingForStepsSubState()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			bool flag = true;
			for (int i = 0; i < steps.Length; i++)
			{
				if (!steps[i].IsCompleted())
				{
					flag = false;
					break;
				}
			}
			if (flag)
			{
				stateMachine.EnterState(3);
			}
		}

		private void OnEnterFinishedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!isInitialized)
			{
				for (int i = 0; i < steps.Length; i++)
				{
					steps[i].OnSkipRunning();
				}
			}
		}

		private void OnUpdateFinishedState()
		{
			if (PhotonNetwork.isMasterClient && automaticallyActivate)
			{
				stateMachine.EnterState(0);
			}
		}

		public static GameEncounter MasterInstantiate(string encounterPrefabName, bool automaticallyActivate, Vector3 position, Quaternion rotation, GameTeam team, EnemyPatrol overridePatrol, PhotonView instantiatorPhotonView, Dictionary<string, object> instantiationParams)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return null;
			}
			if (string.IsNullOrEmpty(encounterPrefabName))
			{
				return null;
			}
			GameObject gameObject = PhotonNetwork.InstantiateSceneObject(encounterPrefabName, position, rotation, 1f, 0, new object[5]
			{
				instantiatorPhotonView.viewID,
				instantiationParams,
				automaticallyActivate,
				(int)team,
				(!(overridePatrol != null)) ? (-1) : overridePatrol.photonView.viewID
			});
			return (!(gameObject != null)) ? null : gameObject.GetComponent<GameEncounter>();
		}

		public static void MasterDestroy(GameEncounter encounter)
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!encounter.hasAuthority)
				{
					encounter.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				PhotonNetwork.Destroy(encounter.photonView);
			}
		}
	}
	public abstract class GameEncounterStartTrigger : UnityEngine.MonoBehaviour
	{
		protected GameEncounter encounter;

		protected int encounterTriggerIndex = -1;

		public abstract string Description { get; }

		public virtual void OnAwake(GameEncounter encounter, int encounterTriggerIndex)
		{
			this.encounter = encounter;
			this.encounterTriggerIndex = encounterTriggerIndex;
		}

		public virtual void OnCleanup()
		{
		}

		public virtual void OnEncounterActivate()
		{
		}

		public virtual void OnEncounterDeactivate()
		{
		}

		public abstract void StartListening();

		public abstract bool IsTriggered();

		public abstract void StopListening();

		protected string SynchronizedFieldKey(string key)
		{
			return $"T{encounterTriggerIndex}.{key}";
		}

		public static string ParseFriendlyTypeName(System.Type type)
		{
			string input = type.Name.Substring(0, type.Name.IndexOf("EncounterStartTrigger"));
			return Regex.Replace(input, "(\\B[A-Z0-9])", " $1");
		}
	}
	public abstract class GameEncounterStep : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		protected string stepName = "New Step";

		[SerializeField]
		protected int finishCondition;

		[SerializeField]
		protected int finishValue;

		protected GameEncounter encounter;

		protected int encounterStepIndex = -1;

		protected Timer encounterTimer;

		protected Timer stepTimer;

		public string StepName => stepName;

		public abstract string Description { get; }

		public virtual void OnAwake(GameEncounter encounter, int encounterStepIndex, Timer encounterTimer, Timer stepTimer)
		{
			this.encounter = encounter;
			this.encounterStepIndex = encounterStepIndex;
			this.encounterTimer = encounterTimer;
			this.stepTimer = stepTimer;
		}

		public virtual void OnCleanup()
		{
		}

		public virtual void OnEncounterActivate()
		{
		}

		public virtual void OnEncounterDeactivate()
		{
		}

		public abstract void OnEncounterStart();

		public abstract void OnEncounterStop();

		public abstract void OnStartRunning();

