	public class DependentEncountersEncounterStartTrigger : GameEncounterStartTrigger
	{
		private enum EncounterRequirement
		{
			FINISHED,
			RUNNING,
			WAITING_FOR_TRIGGER,
			INACTIVE
		}

		[SerializeField]
		public GameEncounter[] dependentEncounters;

		[SerializeField]
		private EncounterRequirement encounterRequirement;

		public override string Description => "Triggers once dependent encounters are finished.";

		public override void StartListening()
		{
		}

		public override void StopListening()
		{
		}

		public override bool IsTriggered()
		{
			bool result = true;
			if (dependentEncounters != null)
			{
				for (int i = 0; i < dependentEncounters.Length; i++)
				{
					if (!EncounterMeetsRequirement(dependentEncounters[i]))
					{
						result = false;
						break;
					}
				}
			}
			return result;
		}

		private bool EncounterMeetsRequirement(GameEncounter encounter)
		{
			if (encounter == null)
			{
				return true;
			}
			return encounterRequirement switch
			{
				EncounterRequirement.FINISHED => encounter.IsFinished, 
				EncounterRequirement.RUNNING => encounter.IsRunning, 
				EncounterRequirement.INACTIVE => !encounter.IsActive, 
				EncounterRequirement.WAITING_FOR_TRIGGER => encounter.IsWaitingForTrigger, 
				_ => false, 
			};
		}
	}
