	public class OverlapVolumeEncounterStartTrigger : GameEncounterStartTrigger
	{
		public enum PlayerRequirement
		{
			ONE_PLAYER,
			ALL_PLAYERS
		}

		[Serializable]
		public struct StoryStateDependantNotification
		{
			public QuestManager.StoryState roomStoryState;

			public string notYetTriggeredNotification;
		}

		[SerializeField]
		public EncounterOverlapVolume[] volumes;

		[SerializeField]
		public PlayerRequirement playerRequirement;

		[SerializeField]
		[FormerlySerializedAs("notYetTriggeredNotification")]
		private string defaultNotYetTriggeredNotification = string.Empty;

		[SerializeField]
		private StoryStateDependantNotification[] roomStoryStateNotifications;

		private Coroutine playNotificationCoroutine;

		public override string Description => "Players teleport or walk in to volumes.";

		public override void OnCleanup()
		{
			base.OnCleanup();
			StopListening();
		}

		public override void StartListening()
		{
			if (string.IsNullOrEmpty(defaultNotYetTriggeredNotification))
			{
				return;
			}
			for (int i = 0; i < volumes.Length; i++)
			{
				if (volumes[i] != null)
				{
					volumes[i].LocalPlayerVolumeEnterEvent += OnLocalPlayerEnterVolume;
				}
			}
		}

		public override void StopListening()
		{
			StopPlayNotificationCoroutine();
			for (int i = 0; i < volumes.Length; i++)
			{
				if (volumes[i] != null)
				{
					volumes[i].LocalPlayerVolumeEnterEvent -= OnLocalPlayerEnterVolume;
				}
			}
		}

		public override bool IsTriggered()
		{
			IEnumerable<PhotonPlayer> enumerable = null;
			int num = 0;
			if (encounter.Game != null)
			{
				enumerable = encounter.Game.TeamManager.GetActivePlayers();
				num = enumerable.Count();
			}
			else
			{
				enumerable = PhotonNetwork.playerList;
				num = PhotonNetwork.playerList.Length;
			}
			int overlappingPlayerCount = VolumeHelpers.GetOverlappingPlayerCount(enumerable, volumes);
			if (playerRequirement == PlayerRequirement.ONE_PLAYER)
			{
				return overlappingPlayerCount >= 1;
			}
			if (playerRequirement == PlayerRequirement.ALL_PLAYERS)
			{
				return overlappingPlayerCount >= num;
			}
			return false;
		}

		private void OnLocalPlayerEnterVolume()
		{
			string currentRoomStoryStateNotTriggeredNotification = GetCurrentRoomStoryStateNotTriggeredNotification();
			if (!string.IsNullOrEmpty(currentRoomStoryStateNotTriggeredNotification))
			{
				StopPlayNotificationCoroutine();
				playNotificationCoroutine = StartCoroutine(PlayNotificationCoroutine(currentRoomStoryStateNotTriggeredNotification));
			}
		}

		private void StopPlayNotificationCoroutine()
		{
			if (playNotificationCoroutine != null)
			{
				StopCoroutine(playNotificationCoroutine);
				playNotificationCoroutine = null;
			}
		}

		private IEnumerator PlayNotificationCoroutine(string notification)
		{
			yield return new WaitForSeconds(0.25f);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, notification, null, 3f);
			playNotificationCoroutine = null;
		}

		private string GetCurrentRoomStoryStateNotTriggeredNotification()
		{
			string text = null;
			if (roomStoryStateNotifications != null && roomStoryStateNotifications.Length > 0 && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				QuestManager.StoryState currentRoomStoryState = ((QuestManager)NetworkedSingletonMonoBehaviour<GameManager>.Instance).CurrentRoomStoryState;
				StoryStateDependantNotification[] array = roomStoryStateNotifications;
				for (int i = 0; i < array.Length; i++)
				{
					StoryStateDependantNotification storyStateDependantNotification = array[i];
					if (storyStateDependantNotification.roomStoryState == currentRoomStoryState)
					{
						text = storyStateDependantNotification.notYetTriggeredNotification;
						break;
					}
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				text = defaultNotYetTriggeredNotification;
			}
			return text;
		}
	}
