	public class StoryStateEncounterStartTrigger : GameEncounterStartTrigger
	{
		public enum TriggerMode
		{
			STORY_STATE,
			ROOM_STORY_STATE,
			STORY_AND_ROOM_STORY_STATE,
			STORY_OR_ROOM_STORY_STATE
		}

		[SerializeField]
		private TriggerMode triggerOn;

		[SerializeField]
		[FormerlySerializedAs("triggerOnStoryState")]
		private QuestManager.StoryState storyState;

		[SerializeField]
		private QuestManager.StoryState roomStoryState;

		public override string Description => "The Story State of the Quest is in a certain state.";

		public override void StartListening()
		{
		}

		public override void StopListening()
		{
		}

		public override bool IsTriggered()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized)
			{
				QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
				bool flag = questManager.CurrentCampaignStoryState == storyState;
				bool flag2 = questManager.CurrentRoomStoryState == roomStoryState;
				switch (triggerOn)
				{
				case TriggerMode.STORY_STATE:
					return flag;
				case TriggerMode.ROOM_STORY_STATE:
					return flag2;
				case TriggerMode.STORY_AND_ROOM_STORY_STATE:
					return flag && flag2;
				case TriggerMode.STORY_OR_ROOM_STORY_STATE:
					return flag || flag2;
				}
			}
			return false;
		}
	}
