	public abstract class BaseSpawnEnemyEncounterStep : GameEncounterStep
	{
		[Header("Spawn Configuration")]
		[SerializeField]
		public EnemySpawnerConfiguration spawnerConfiguration;

		[Header("Patrol")]
		[SerializeField]
		public bool spawnOnPatrol = true;

		[Header("Spawn Regions")]
		[SerializeField]
		public EnemySpawnNavMeshRegion[] spawnRegions = new EnemySpawnNavMeshRegion[1];

		[Header("Rewards")]
		[SerializeField]
		public bool suppressRewards;

		public static readonly string ENCOUNTER_ID_KEY = "ENC_ID";

		public static readonly string ENCOUNTER_STEP_ID_KEY = "ENC_STEP_ID";

		public static readonly string ENCOUNTER_SUPPRESS_REWARDS_KEY = "ENC_SR";

		private static List<Enemy> enemyScratchSpace = new List<Enemy>();

		protected List<Enemy> livingEnemies = new List<Enemy>();

		private Dictionary<string, object> spawnParameterDictionary = new Dictionary<string, object>();

		public override void OnAwake(GameEncounter encounter, int encounterStepIndex, Timer encounterTimer, Timer stepTimer)
		{
			base.OnAwake(encounter, encounterStepIndex, encounterTimer, stepTimer);
			Enemy.EnemyInstantiatedEvent += OnEnemyInstantiated;
			Enemy.EnemyDeathEvent += OnEnemyDeath;
			spawnParameterDictionary.Add(ENCOUNTER_ID_KEY, (!(encounter != null)) ? (-1) : encounter.photonView.viewID);
			spawnParameterDictionary.Add(ENCOUNTER_STEP_ID_KEY, encounterStepIndex);
			spawnParameterDictionary.Add(ENCOUNTER_SUPPRESS_REWARDS_KEY, suppressRewards);
		}

		public override void OnCleanup()
		{
			base.OnCleanup();
			Enemy.EnemyInstantiatedEvent -= OnEnemyInstantiated;
			Enemy.EnemyDeathEvent -= OnEnemyDeath;
		}

		public override void OnEncounterStart()
		{
		}

		public override void OnEncounterStop()
		{
			MasterKillAllLivingEnemies();
		}

		protected virtual Enemy TryMasterSpawnEnemy(EncounterEnemyDescriptor enemyDesc, bool spawnDisengaged, out bool failedToFindSpawnPoint)
		{
			failedToFindSpawnPoint = false;
			if (!PhotonNetwork.isMasterClient || enemyDesc.EnemyType == EnemyType.INVALID)
			{
				return null;
			}
			failedToFindSpawnPoint = !GetEnemySpawnTargetPositionAndRotation(enemyDesc, out var targetPosition, out var targetRotation);
			if (failedToFindSpawnPoint)
			{
				return null;
			}
			EnemyPatrol enemyPatrol = null;
			enemyPatrol = ((!(encounter.OverridePatrol != null)) ? enemyDesc.Patrol : encounter.OverridePatrol);
			GetEnemySpawnBasePositionAndRotation(targetPosition, targetRotation, out var basePosition, out var baseRotation);
			Enemy enemy = Enemy.MasterSpawn(enemyDesc.EnemyType, basePosition, baseRotation, targetPosition, spawnOnPatrol, enemyPatrol, encounter.Team, spawnDisengaged, encounter.photonView.viewID, spawnParameterDictionary);
			if (enemy == null)
			{
				LogEncounterStepWarning(string.Concat("Enemy of type ", enemyDesc.EnemyType, " failed to instantiate."));
			}
			return enemy;
		}

		protected virtual bool GetEnemySpawnTargetPositionAndRotation(EncounterEnemyDescriptor enemyDesc, out Vector3 targetPosition, out Quaternion targetRotation)
		{
			targetPosition = Vector3.zero;
			targetRotation = Quaternion.identity;
			if (enemyDesc.ExplicitSpawnPoint != null)
			{
				targetPosition = enemyDesc.ExplicitSpawnPoint.position;
				Vector3 normalized = Vector3.ProjectOnPlane(enemyDesc.ExplicitSpawnPoint.forward, Vector3.up).normalized;
				targetRotation = Quaternion.LookRotation(normalized, Vector3.up);
			}
			else
			{
				EnemySpawnNavMeshRegion enemySpawnNavMeshRegion = null;
				if (spawnRegions.Length == 0 || (enemySpawnNavMeshRegion = spawnRegions[UnityEngine.Random.Range(0, spawnRegions.Length)]) == null)
				{
					LogEncounterStepWarning("Missing or null spawn regions.");
					return false;
				}
				if (!enemySpawnNavMeshRegion.TryGetSpawnPositionAndRotation(out targetPosition, out targetRotation))
				{
					return false;
				}
				if (EnemySettings.GetEnemyBehaviorType(enemyDesc.EnemyType) == EnemyBehaviorType.FLYING)
				{
					targetPosition += Vector3.up * EnemySettings.GetFlyingEnemySpawnHeight();
				}
			}
			return true;
		}

		protected virtual void GetEnemySpawnBasePositionAndRotation(Vector3 targetPosition, Quaternion targetRotation, out Vector3 basePosition, out Quaternion baseRotation)
		{
			spawnerConfiguration.GetBaseSpawnPositionAndRotation(targetPosition, targetRotation, out basePosition, out baseRotation);
		}

		private void OnEnemyInstantiated(Enemy enemy)
		{
			if (EnemyBelongsToThisStep(enemy))
			{
				livingEnemies.Add(enemy);
			}
		}

		private void OnEnemyDeath(Enemy enemy)
		{
			if (EnemyBelongsToThisStep(enemy))
			{
				livingEnemies.Remove(enemy);
			}
		}

		private bool EnemyBelongsToThisStep(Enemy enemy)
		{
			if (enemy.InstantiatorPhotonViewId == encounter.photonView.viewID)
			{
				object value = -1;
				Dictionary<string, object> instantiationParameters = enemy.InstantiationParameters;
				if (instantiationParameters != null && instantiationParameters.TryGetValue(ENCOUNTER_STEP_ID_KEY, out value) && (int)value == encounterStepIndex)
				{
					return true;
				}
			}
			return false;
		}

		public void MasterKillAllLivingEnemies()
		{
			if (PhotonNetwork.isMasterClient)
			{
				enemyScratchSpace.Clear();
				enemyScratchSpace.AddRange(livingEnemies);
				livingEnemies.Clear();
				for (int i = 0; i < enemyScratchSpace.Count; i++)
				{
					Enemy.MasterKill(enemyScratchSpace[i]);
				}
			}
		}

		protected int GetEnemyAggroCount()
		{
			int num = 0;
			for (int i = 0; i < livingEnemies.Count; i++)
			{
				if (livingEnemies[i].IsAggrod)
				{
					num++;
				}
			}
			return num;
		}
	}
	public class CameraShakeEncounterStep : GameEncounterStep
	{
		public enum FinishConditions
		{
			TIME_ELAPSED,
			IMMEDIATELY
		}

		private enum CameraShakeType
		{
			TWO_DIMENSIONAL,
			THREE_DIMENSIONAL
		}

		[SerializeField]
		private CameraShake.CameraShakeConfig cameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[SerializeField]
		private CameraShakeType shakeType;

		[SerializeField]
		private Transform threeDimensionalTransform;

		[SerializeField]
		private float threeDimensionalInnerRadius = 10f;

		[SerializeField]
		private float threeDimensionalOuterRadius = 20f;

		public override string Description => "Plays Camera Shakes with optional 3D falloff.";

		public override void OnEncounterStart()
		{
		}

		public override void OnEncounterStop()
		{
		}

		public override void OnStartRunning()
		{
			if (shakeType == CameraShakeType.THREE_DIMENSIONAL && threeDimensionalTransform != null && Player.LocalPlayer != null)
			{
				float magnitude = (Player.LocalPlayer.Head.RigidbodyEx.targetPosition - threeDimensionalTransform.position).magnitude;
				float t = Mathf.InverseLerp(threeDimensionalInnerRadius, threeDimensionalOuterRadius, magnitude);
				float num = Mathf.SmoothStep(0f, 1f, t);
				CameraShake.SetShake(CameraShake.CameraShakeConfig.ScaleAmplitude(cameraShake, 1f - num));
			}
			else
			{
				CameraShake.SetShake(cameraShake);
			}
		}

		public override void OnUpdateRunning()
		{
		}

		public override void OnStopRunning()
		{
		}

		public override void OnSkipRunning()
		{
		}

		public override bool IsBlockingEncounterEnd()
		{
			return (FinishConditions)finishCondition switch
