		}

		private void MasterDisableTools()
		{
			MasterUpdateToolsEnabled(enable: false);
		}

		private void MasterEnableTools()
		{
			MasterUpdateToolsEnabled(enable: true);
		}

		private void MasterUpdateToolsEnabled(bool enable)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			for (int i = 0; i < tools.Length; i++)
			{
				if (tools[i] != null && !tools[i].IsHeld)
				{
					tools[i].IsEnabled = enable;
				}
			}
		}
	}
