		private void PlayMusic()
		{
			if (customMusic != null)
			{
				AudioManager.MusicMixer.AddOverrideMusic(customMusic, this);
				AudioManager.MusicMixer.PlayOverrideMusic();
				customMusicPlaying = true;
			}
		}

		public void StopMusic()
		{
			if (customMusicPlaying)
			{
				AudioManager.MusicMixer.StopOverrideMusic();
