	public class SpawnBossEnemyEncounterStep : BaseSpawnEnemyEncounterStep
	{
		public enum FinishConditions
		{
			IMMEDIATELY,
			BOSS_HEALTH_LESS_THAN,
			BOSS_KILLED,
			TIME_ELAPSED,
			BOSS_AGGROD
		}

		private const float BOSS_SPAWN_WAIT_DELAY = 0.1f;

		[Header("Boss Enemy")]
		[SerializeField]
		public EncounterEnemyDescriptor bossEnemyDescriptor;

		[Header("Boss Configuration")]
		[SerializeField]
		public bool spawnDisenaged;

		private SynchronizedField<bool, float, int> _bossSpawnData;

		public Enemy BossEnemy
		{
			get
			{
				PhotonView photonView = PhotonView.Find(_bossSpawnData.Get3());
				return (!(photonView != null)) ? null : photonView.GetComponent<Enemy>();
			}
		}

		public float BossSpawnTime => _bossSpawnData.Get2();

		public bool BossHasBeenSpawned => _bossSpawnData.Get1();

		public override string Description => string.Empty;

		public override void OnAwake(GameEncounter encounter, int encounterStepIndex, Timer encounterTimer, Timer stepTimer)
		{
			base.OnAwake(encounter, encounterStepIndex, encounterTimer, stepTimer);
			_bossSpawnData = new SynchronizedField<bool, float, int>(encounter, SynchronizedFieldKey("BSD"), defaultVal1: false, 0f, -1, SetterPermissionMode.MASTER);
		}

		public override void OnEncounterStart()
		{
			base.OnEncounterStart();
			if (PhotonNetwork.isMasterClient)
			{
				MasterSetSpawnData(hasSpawned: false, null);
			}
		}

		public override void OnStartRunning()
		{
			if (PhotonNetwork.isMasterClient)
			{
				bool failedToFindSpawnPoint;
				Enemy bossEnemy = TryMasterSpawnEnemy(bossEnemyDescriptor, spawnDisenaged, out failedToFindSpawnPoint);
				MasterSetSpawnData(hasSpawned: true, bossEnemy);
			}
		}

		public override void OnUpdateRunning()
		{
		}

		public override void OnStopRunning()
		{
		}

		public override void OnSkipRunning()
		{
		}

		public override bool IsBlockingEncounterEnd()
		{
			float num = (float)PhotonNetwork.time;
			if (!BossHasBeenSpawned || num < BossSpawnTime + 0.1f)
			{
				return true;
			}
			return (FinishConditions)finishCondition switch
			{
				FinishConditions.IMMEDIATELY => false, 
				FinishConditions.BOSS_HEALTH_LESS_THAN => BossEnemy != null && BossEnemy.Health >= Mathf.Clamp(finishValue, 0, Mathf.Abs(finishValue)), 
				FinishConditions.BOSS_KILLED => livingEnemies.Count > 0, 
				FinishConditions.TIME_ELAPSED => stepTimer.TimeElapsed < (float)finishValue, 
				FinishConditions.BOSS_AGGROD => GetEnemyAggroCount() < livingEnemies.Count, 
				_ => true, 
			};
		}

		public override bool IsCompleted()
		{
			return livingEnemies.Count == 0;
		}

		private void MasterSetSpawnData(bool hasSpawned, Enemy bossEnemy)
		{
			float newValue = ((!hasSpawned) ? 0f : ((float)PhotonNetwork.time));
			int newValue2 = ((!(bossEnemy != null)) ? (-1) : bossEnemy.photonView.viewID);
			_bossSpawnData.Set(hasSpawned, newValue, newValue2);
		}
	}
