				return _enemySpawnParameters.Get3();
			}
			set
			{
				_enemySpawnParameters.Set3(value);
			}
		}

		private int CurrentIndexSpawnRetryCount
		{
			get
			{
				return _enemySpawnParameters.Get4();
			}
			set
			{
				_enemySpawnParameters.Set4(value);
			}
		}

		public override void OnAwake(GameEncounter encounter, int encounterStepIndex, Timer encounterTimer, Timer stepTimer)
		{
			base.OnAwake(encounter, encounterStepIndex, encounterTimer, stepTimer);
			_enemySpawnParameters = new SynchronizedField<int, int, float, int>(encounter, SynchronizedFieldKey("SP"), 0, 0, 0f, 0, SetterPermissionMode.MASTER);
		}

		public override void OnStartRunning()
		{
			if (PhotonNetwork.isMasterClient)
			{
				EnemySpawnCount = 0;
				NextEnemySpawnIndex = 0;
				NextSpawnTime = 0f;
				CurrentIndexSpawnRetryCount = 0;
			}
		}

		public override void OnUpdateRunning()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			float num = (float)PhotonNetwork.time;
			if (num < stepTimer.StartTime + timeBeforeFirstSpawn || NextEnemySpawnIndex >= enemies.Length || !(NextSpawnTime <= num))
			{
				return;
			}
			bool failedToFindSpawnPoint = false;
			int nextEnemySpawnIndex = NextEnemySpawnIndex;
			if (nextEnemySpawnIndex >= 0 && nextEnemySpawnIndex < enemies.Length && TryMasterSpawnEnemy(enemies[nextEnemySpawnIndex], spawnDisengaged: false, out failedToFindSpawnPoint) != null)
			{
				EnemySpawnCount++;
			}
			if (failedToFindSpawnPoint && CurrentIndexSpawnRetryCount < 10)
			{
				NextSpawnTime = num + 0.5f;
				CurrentIndexSpawnRetryCount++;
				return;
			}
			if (CurrentIndexSpawnRetryCount > 0)
			{
				LogEncounterStepWarning("Enemy at index " + NextEnemySpawnIndex + " took " + CurrentIndexSpawnRetryCount + " respawn retries to spawn.");
			}
			NextEnemySpawnIndex++;
			CurrentIndexSpawnRetryCount = 0;
			NextSpawnTime = num + TimeBetweenSpawns;
		}

		public override void OnStopRunning()
		{
			if (EnemySpawnCount < enemies.Length)
			{
				LogEncounterStepWarning("Only spawned " + EnemySpawnCount + " of " + enemies.Length + " enemies.");
			}
		}

		public override void OnSkipRunning()
		{
		}

		public override bool IsBlockingEncounterEnd()
		{
			float num = (float)PhotonNetwork.time;
			if (NextEnemySpawnIndex >= enemies.Length && num > NextSpawnTime)
			{
				switch ((FinishConditions)finishCondition)
				{
				case FinishConditions.IMMEDIATELY:
					return false;
				case FinishConditions.ENEMIES_ALIVE:
					return livingEnemies.Count > Mathf.Clamp(finishValue, 0, EnemySpawnCount);
				case FinishConditions.ENEMIES_KILLED:
					return EnemySpawnCount - livingEnemies.Count < Mathf.Clamp(finishValue, 0, EnemySpawnCount);
				case FinishConditions.TIME_ELAPSED:
					return stepTimer.TimeElapsed < (float)finishValue;
				case FinishConditions.ENEMIES_AGGROD:
					return GetEnemyAggroCount() < Mathf.Clamp(finishValue, 0, livingEnemies.Count);
				}
			}
			return true;
		}

		public override bool IsCompleted()
		{
			return livingEnemies.Count == 0;
		}
	}
	public class SpawnMinionEnemyEncounterStep : SpawnEnemyEncounterStep
	{
		[SerializeField]
		private float minEnemySpawnRadius;

		[SerializeField]
		private float maxEnemySpawnRadius;

		[SerializeField]
		[Autofill(AutofillType.SelfAndParent, false)]
		private Enemy targetEnemy;

		private int SPAWN_RAY_TRIES = 3;

		protected override bool GetEnemySpawnTargetPositionAndRotation(EncounterEnemyDescriptor enemyDesc, out Vector3 targetPosition, out Quaternion targetRotation)
		{
			float num = UnityEngine.Random.Range(minEnemySpawnRadius, maxEnemySpawnRadius);
			targetRotation = targetEnemy.RigidbodyEx.targetRotation;
			Vector3 targetPosition2 = targetEnemy.RigidbodyEx.targetPosition;
			bool flag = false;
			targetPosition = targetPosition2;
			for (int i = 0; i < SPAWN_RAY_TRIES; i++)
			{
				Vector3 normalized = new Vector3(UnityEngine.Random.Range(0f, 1f), UnityEngine.Random.Range(0f, 1f), UnityEngine.Random.Range(0f, 1f)).normalized;
				targetPosition = targetPosition2 + normalized * num;
				if (Enemy.TryGetRaycastHitPoint(targetPosition2, normalized, num, out var distance, out var hitPoint, out var hitNormal))
				{
					targetPosition = hitPoint;
				}
				flag = Enemy.TryGetRaycastHitPoint(targetPosition, Vector3.down, float.MaxValue, out distance, out hitPoint, out hitNormal);
				if (flag)
				{
					flag = Enemy.TrySampleNavMesh(hitPoint, out hitPoint);
				}
				if (flag)
				{
					break;
				}
			}
			return flag;
		}

		protected override void GetEnemySpawnBasePositionAndRotation(Vector3 targetPosition, Quaternion targetRotation, out Vector3 basePosition, out Quaternion baseRotation)
		{
			basePosition = targetEnemy.RigidbodyEx.targetPosition;
			baseRotation = targetEnemy.RigidbodyEx.targetRotation;
		}
	}
