[RequireComponent(typeof(Rigidbody))]
public class Collectible : UnityEngine.MonoBehaviour
{
	public delegate void Collected(Collectible thisCollectible);

	public enum CollectibleType
	{
		Default,
		SciFi,
		Store_Ticket,
		Store_Token,
		Store_Gold,
		Store_Silver
	}

	[Header("Spawning")]
	[SerializeField]
	private float spawnForce = 4.5f;

	[SerializeField]
	private float upWeight = 1f;

	[SerializeField]
	private float sideWeight = 1f;

	[SerializeField]
	private float torqueOffset = 0.1f;

	[SerializeField]
	private CollectibleType collectibleType;

	[Header("Collection Distances")]
	[SerializeField]
	private float attractDistance = 3.5f;

	[SerializeField]
	private float stayOnFloorDistance = 2.5f;

	[SerializeField]
	private float collectDistance = 0.25f;

	[Header("Collection Durations")]
	[SerializeField]
	private float maxCollectionDuration = 2f;

	[Header("Attraction Physics")]
	[SerializeField]
	private float minAttractSpeed = 17f;

	[SerializeField]
	private float maxAttractSpeed = 25f;

	[SerializeField]
	private float attractSmoothTime = 0.25f;

	[SerializeField]
	private float playerHeadTargetOffset = -0.2f;

	[SerializeField]
	private float attractRotationSpeed = 60f;

	[Header("Feedback")]
	[SerializeField]
	private RecRoomAudioClip[] pickupAudio;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private static Collected m_CollectedEvent;

	public const int DEFAULT_PRE_ALLOCATE_SIZE = 10;

	private static Transform _collectibleRoot;

	private static Dictionary<CollectibleType, List<Collectible>> allCollectiblesDict;

	private Rigidbody rigidbody;

	private bool attracting;

	private float attractionStartTime;

	private bool collected;

	private float attractSpeed = 20f;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationAxis = Vector3.up;

	private Vector3? targetPosition;

	private Player targetPlayer;

	private bool automaticallyPickup;

	private bool mustComeToRestBeforePickup = true;

	private float delay;

	private float resetTime;

	private static Transform CollectibleRoot
	{
		get
		{
			if (_collectibleRoot == null)
			{
				GameObject gameObject = new GameObject("Collectibles");
				_collectibleRoot = gameObject.transform;
			}
			return _collectibleRoot;
		}
	}

	public int Value { get; private set; }

	public static event Collected CollectedEvent
	{
		add
		{
			Collected collected = Collectible.m_CollectedEvent;
			Collected collected2;
			do
			{
				collected2 = collected;
				collected = Interlocked.CompareExchange(ref Collectible.m_CollectedEvent, (Collected)Delegate.Combine(collected2, value), collected);
			}
			while (collected != collected2);
		}
		remove
		{
			Collected collected = Collectible.m_CollectedEvent;
			Collected collected2;
			do
			{
				collected2 = collected;
				collected = Interlocked.CompareExchange(ref Collectible.m_CollectedEvent, (Collected)Delegate.Remove(collected2, value), collected);
			}
			while (collected != collected2);
		}
	}

	public void Reset(int value, Vector3 position, Vector3 forceDirection, Player targetPlayer, float delay = 0f, bool automaticallyPickup = false)
	{
		ResetBase(value, position, forceDirection);
		targetPosition = null;
		this.targetPlayer = targetPlayer;
		this.automaticallyPickup = automaticallyPickup;
		mustComeToRestBeforePickup = true;
		this.delay = delay;
	}

	public void Reset(int value, Vector3 position, Vector3 forceDirection, Vector3? targetPosition, float delay = 0f, bool mustComeToRestBeforePickup = true)
	{
		ResetBase(value, position, forceDirection);
		this.targetPosition = targetPosition;
		targetPlayer = null;
		automaticallyPickup = true;
		this.mustComeToRestBeforePickup = mustComeToRestBeforePickup;
		this.delay = delay;
	}

	private void ResetBase(int value, Vector3 position, Vector3 forceDirection)
	{
		resetTime = UnityEngine.Time.time;
		attracting = false;
		attractionStartTime = 0f;
		collected = false;
		velocity = Vector3.zero;
		rigidbody.isKinematic = false;
		rigidbody.useGravity = true;
		rigidbody.position = position;
		rigidbody.AddForceAtPosition(forceDirection * spawnForce, position - forceDirection * torqueOffset, ForceMode.Impulse);
		Value = value;
	}

	private void Awake()
	{
		rigidbody = GetComponent<Rigidbody>();
	}

	private void Update()
	{
		if (targetPlayer == null)
		{
			Vector3? vector = targetPosition;
			if (!vector.HasValue && !targetPosition.HasValue)
			{
				return;
			}
		}
		if (UnityEngine.Time.time - resetTime < delay)
		{
			return;
		}
		Vector3 vector2 = Vector3.zero;
		if (targetPlayer != null)
		{
			vector2 = targetPlayer.Head.RigidbodyEx.targetPosition + Vector3.up * playerHeadTargetOffset;
		}
		else
		{
			Vector3? vector3 = targetPosition;
			if (vector3.HasValue && targetPosition.HasValue)
			{
				vector2 = targetPosition.Value;
			}
		}
		float sqrMagnitude = Vector3.ProjectOnPlane(vector2 - base.transform.position, Vector3.up).sqrMagnitude;
		if (!attracting && (!mustComeToRestBeforePickup || rigidbody.IsSleeping()) && (automaticallyPickup || sqrMagnitude <= attractDistance * attractDistance))
		{
			attracting = true;
			attractionStartTime = UnityEngine.Time.time;
			velocity = Vector3.zero;
			rotationAxis = UnityEngine.Random.onUnitSphere;
			attractSpeed = Mathf.Lerp(minAttractSpeed, maxAttractSpeed, UnityEngine.Random.Range(0f, 1f));
			rigidbody.isKinematic = true;
		}
		if (attracting)
		{
			if (targetPlayer != null && sqrMagnitude >= stayOnFloorDistance * stayOnFloorDistance)
			{
				vector2.y = targetPlayer.TrackingSpace.RigidbodyEx.targetPosition.y;
			}
			base.transform.position = Vector3.SmoothDamp(base.transform.position, vector2, ref velocity, attractSmoothTime, attractSpeed, UnityEngine.Time.deltaTime);
			base.transform.localRotation *= Quaternion.AngleAxis(attractRotationSpeed * UnityEngine.Time.deltaTime, rotationAxis);
			float num = UnityEngine.Time.time - attractionStartTime;
			if (!collected && (sqrMagnitude <= collectDistance * collectDistance || num >= maxCollectionDuration))
			{
				collected = true;
				OnCollect();
			}
		}
	}

	private void OnCollect()
	{
		if (Collectible.CollectedEvent != null)
		{
			Collectible.CollectedEvent(this);
		}
		if (pickupAudio != null)
		{
			AudioManager.PlayRandom3DSFX(pickupAudio, base.transform.position);
		}
		ReturnCollectible(this);
	}

	public static void PreAllocateCollectibles(Collectible prefab, int count = 10)
	{
		for (int i = 0; i < count; i++)
		{
			CreateNewCollectible(prefab);
		}
	}

	public static void SpawnCollectibleGroup(Collectible prefab, int totalGroupValue, int individualCollectibleValue, Vector3 spawnPosition, Player targetPlayer, bool automaticallyPickup, float spawnDuration = 0f)
	{
		SpawnCollectibleGroupBase(prefab, totalGroupValue, individualCollectibleValue, spawnPosition, null, targetPlayer, automaticallyPickup, spawnDuration);
	}

	public static void SpawnCollectibleGroup(Collectible prefab, int totalGroupValue, int individualCollectibleValue, Vector3 spawnPosition, Vector3 targetPosition, float spawnDuration = 0f)
	{
		SpawnCollectibleGroupBase(prefab, totalGroupValue, individualCollectibleValue, spawnPosition, targetPosition, null, automaticallyPickup: true, spawnDuration);
	}

	private static void SpawnCollectibleGroupBase(Collectible prefab, int totalGroupValue, int individualCollectibleValue, Vector3 spawnPosition, Vector3? targetPosition, Player targetPlayer, bool automaticallyPickup, float spawnDuration)
	{
		if (individualCollectibleValue < 1)
		{
			individualCollectibleValue = 1;
		}
		int num = Mathf.CeilToInt((float)totalGroupValue / (float)individualCollectibleValue);
		int num2 = totalGroupValue % individualCollectibleValue;
		float num3 = spawnDuration / (float)num;
		for (int i = 0; i < num; i++)
		{
			Collectible nextCollectible = GetNextCollectible(prefab);
			float y = (float)i / (float)num * 360f;
			Vector3 vector = Vector3.up * nextCollectible.upWeight;
			Vector3 vector2 = Quaternion.Euler(0f, y, 0f) * Vector3.right * nextCollectible.sideWeight;
			Vector3 normalized = (vector + vector2).normalized;
			int value = ((i != num - 1 || num2 <= 0) ? individualCollectibleValue : num2);
			float num4 = num3 * (float)i;
			if (targetPlayer != null)
			{
				nextCollectible.Reset(value, spawnPosition, normalized, targetPlayer, num4, automaticallyPickup);
			}
			else
			{
				nextCollectible.Reset(value, spawnPosition, normalized, targetPosition, num4, mustComeToRestBeforePickup: false);
			}
		}
	}

	public static IEnumerator SpawnStaggeredCollectibleGroup(Collectible prefab, int totalGroupValue, int individualCollectibleValue, Vector3 spawnPosition, Player targetPlayer, bool automaticallyPickup, float spawnDuration = 1f, Action onFinishedSpawning = null)
	{
		return SpawnStaggeredCollectibleGroupBase(prefab, totalGroupValue, individualCollectibleValue, spawnPosition, null, targetPlayer, automaticallyPickup, 0.1f, spawnDuration, onFinishedSpawning);
	}

	private static IEnumerator SpawnStaggeredCollectibleGroupBase(Collectible prefab, int totalGroupValue, int individualCollectibleValue, Vector3 spawnPosition, Vector3? targetPosition, Player targetPlayer, bool automaticallyPickup, float updateDelay, float spawnDuration, Action onFinishedSpawning)
	{
		int collectibleCount = Mathf.CeilToInt((float)totalGroupValue / (float)individualCollectibleValue);
		int valueRemainder = totalGroupValue % individualCollectibleValue;
		float deltaDuration = spawnDuration / (float)collectibleCount;
		for (int i = 0; i < collectibleCount; i++)
		{
			Collectible collectible = GetNextCollectible(prefab);
			float velocityRotationAngle = (float)i / (float)collectibleCount * 360f;
			Vector3 upComponent = Vector3.up * collectible.upWeight;
			Vector3 sidecomponent = Quaternion.Euler(0f, velocityRotationAngle, 0f) * Vector3.right * collectible.sideWeight;
			Vector3 velocityDirection = (upComponent + sidecomponent).normalized;
			int value = ((i != collectibleCount - 1 || valueRemainder <= 0) ? individualCollectibleValue : valueRemainder);
			if (targetPlayer != null)
			{
				collectible.Reset(value, spawnPosition, velocityDirection, targetPlayer, updateDelay, automaticallyPickup);
			}
			else
			{
				collectible.Reset(value, spawnPosition, velocityDirection, targetPosition, updateDelay, mustComeToRestBeforePickup: false);
			}
			yield return new WaitForSeconds(deltaDuration);
		}
		onFinishedSpawning?.Invoke();
	}

	public static Collectible GetNextCollectible(Collectible prefab)
	{
		Collectible collectible = null;
		foreach (Collectible item in allCollectiblesDict.GetOrCreate(prefab.collectibleType))
		{
			if (item != null && !item.gameObject.activeSelf)
			{
				collectible = item;
				break;
			}
		}
		if (collectible == null)
		{
			collectible = CreateNewCollectible(prefab);
		}
		if (collectible != null)
		{
			collectible.gameObject.SetActive(value: true);
		}
		return collectible;
	}

	public static void ReturnCollectible(Collectible collectible)
	{
		if (collectible != null)
		{
			collectible.gameObject.SetActive(value: false);
		}
	}

	public static void ReturnAllCollectibles()
	{
		foreach (KeyValuePair<CollectibleType, List<Collectible>> item in allCollectiblesDict)
		{
			for (int i = 0; i < item.Value.Count; i++)
			{
				ReturnCollectible(item.Value[i]);
			}
		}
	}

	private static Collectible CreateNewCollectible(Collectible prefab)
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(prefab.gameObject);
		Collectible component = gameObject.GetComponent<Collectible>();
		component.transform.SetParent(CollectibleRoot, worldPositionStays: true);
		component.gameObject.SetActive(value: false);
		allCollectiblesDict.GetOrCreate(prefab.collectibleType).Add(component);
		return component;
	}

	static Collectible()
	{
		Collectible.CollectedEvent = null;
		_collectibleRoot = null;
		allCollectiblesDict = new Dictionary<CollectibleType, List<Collectible>>();
	}
}
