	[Serializable]
	public sealed class CustomGameSettingsManager : IGameComponent
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_SettingsChangedEvent;

		public bool SuppressRewardsNotifications;

		private GameManager gameManager;

		private List<SpawnableToolType> _availableSpawnEquipment;

		public List<SpawnableToolType> AvailableSpawnEquipment
		{
			get
			{
				InitializeAvailableSpawnEquipment();
				return _availableSpawnEquipment;
			}
		}

		public bool CanEditCustomGameSettings => gameManager.CanToggleMode && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanEditGameSettings.Value;

		public bool SupportsCustomFieldItemsOverride => gameManager.CurrentMode.CustomGameSettings.EnabledFieldEquipmentOverride;

		public bool SupportsCustomSpawnEquipment => gameManager.CurrentMode.CustomGameSettings.SpawnEquipmentSet != SpawnableToolConfig.CustomGameEquipmentSet.INVALID;

		public bool ForceDualWieldingSupport
		{
			get
			{
				SpawnableToolType spawnEquipmentForHand = gameManager.SpawnManager.GetSpawnEquipmentForHand(dominantHand: true);
				SpawnableToolType spawnEquipmentForHand2 = gameManager.SpawnManager.GetSpawnEquipmentForHand(dominantHand: false);
				return spawnEquipmentForHand != SpawnableToolType.INVALID && spawnEquipmentForHand2 != SpawnableToolType.INVALID;
			}
		}

		public bool CurrentModeSupportsCustomScoreToWin => gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions.Length > 1;

		public bool CurrentModeSupportsCustomDuration => gameManager.CurrentMode.TimerSettings.DurationOptions != null && gameManager.CurrentMode.TimerSettings.DurationOptions.Length > 1;

		public bool AllowRewards => RecNet.Rooms.LocalRoomDetails.Room.IsAGRoom;

		public event Action SettingsChangedEvent
		{
			add
			{
				Action action = this.m_SettingsChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SettingsChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_SettingsChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SettingsChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public void OnAwake(GameManager gameManager)
		{
			this.gameManager = gameManager;
			gameManager.ModeChangeEvent += OnModeChanged;
		}

		public void OnStart()
		{
			MarkSettingsChanged();
		}

		public void OnDestroy()
		{
		}

		public void OnUpdate()
		{
		}

		public void OnGameStart()
		{
		}

		public void OnGameEnd()
		{
		}

		public void InitializeLocalPlayer(bool localPlayerIsSpectator)
		{
		}

		public void ResetLocalPlayer(bool localPlayerIsSpectator)
		{
		}

		public void OnPlayerDisconnected(PhotonPlayer player)
		{
		}

		public void ToggleScoreToWin()
		{
			if (CanEditCustomGameSettings)
			{
				int scoreToWinIndex = GetScoreToWinIndex(gameManager.ScoreManager.ScoreToWin);
				if (scoreToWinIndex >= 0)
				{
					scoreToWinIndex = (scoreToWinIndex + 1) % gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions.Length;
					gameManager.ScoreManager.SetScoreToWin(gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions[scoreToWinIndex].ScoreToWin);
				}
			}
		}

		public void ToggleGameDuration()
		{
			if (CanEditCustomGameSettings)
			{
				int durationIndex = GetDurationIndex(gameManager.GameTimerManager.Duration);
				if (durationIndex >= 0)
				{
					durationIndex = (durationIndex + 1) % gameManager.CurrentMode.TimerSettings.DurationOptions.Length;
					gameManager.GameTimerManager.RequestMasterSetDuration(gameManager.CurrentMode.TimerSettings.DurationOptions[durationIndex].Duration);
				}
			}
		}

		public void ToggleDefaultSpawnEquipment(bool dominantHand)
		{
			if (CanEditCustomGameSettings)
			{
				SpawnableToolType spawnEquipmentForHand = gameManager.SpawnManager.GetSpawnEquipmentForHand(dominantHand);
				int spawnEquipmentIndex = GetSpawnEquipmentIndex(spawnEquipmentForHand);
				if (spawnEquipmentIndex >= 0)
				{
					spawnEquipmentIndex = (spawnEquipmentIndex + 1) % AvailableSpawnEquipment.Count;
					gameManager.SpawnManager.SetSpawnEquipmentForHand(dominantHand, AvailableSpawnEquipment[spawnEquipmentIndex]);
				}
			}
		}

		public void ToggleFieldEquipment()
		{
			if (CanEditCustomGameSettings)
			{
				gameManager.SpawnManager.ToggleFieldEquipmentEnabled();
			}
		}

		public void MarkSettingsChanged()
		{
			SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.CustomGameSettingsChanged();
			if (this.SettingsChangedEvent != null)
			{
				this.SettingsChangedEvent();
			}
		}

		private void NotifyAllowRewards(bool allow)
		{
			if (!SuppressRewardsNotifications)
			{
				if (AllowRewards)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Rewards enabled for this game", 2f);
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Rewards disabled for this game", 2f);
				}
			}
		}

		private int GetScoreToWinIndex(int scoreToWin)
		{
			for (int i = 0; i < gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions.Length; i++)
			{
				if (gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions[i].ScoreToWin == scoreToWin)
				{
					return i;
				}
			}
			return -1;
		}

		private int GetDurationIndex(float duration)
		{
			for (int i = 0; i < gameManager.CurrentMode.TimerSettings.DurationOptions.Length; i++)
			{
				if (gameManager.CurrentMode.TimerSettings.DurationOptions[i].Duration == duration)
				{
					return i;
				}
			}
			return -1;
		}

		private int GetSpawnEquipmentIndex(SpawnableToolType equipment)
		{
			for (int i = 0; i < AvailableSpawnEquipment.Count; i++)
			{
				if (AvailableSpawnEquipment[i] == equipment)
				{
					return i;
				}
			}
			return -1;
		}

		private void OnModeChanged()
		{
			if (PhotonNetwork.isMasterClient)
			{
				gameManager.ScoreManager.SetDefaultScoreToWin();
				if (IsCurrentDurationInvalidForMode())
				{
					gameManager.GameTimerManager.RequestMasterSetDurationToDefault();
				}
			}
		}

		private bool IsCurrentDurationInvalidForMode()
		{
			if (GameManager.IsSandboxActive)
			{
				return false;
			}
			int durationIndex = GetDurationIndex(gameManager.GameTimerManager.Duration);
			return durationIndex < 0;
		}

		private void InitializeAvailableSpawnEquipment()
		{
			if (_availableSpawnEquipment == null)
			{
				_availableSpawnEquipment = new List<SpawnableToolType>();
				_availableSpawnEquipment.Add(SpawnableToolType.INVALID);
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.DominantHandTool != SpawnableToolType.INVALID)
				{
					_availableSpawnEquipment.Add(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.DominantHandTool);
				}
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.OffHandTool != SpawnableToolType.INVALID)
				{
					_availableSpawnEquipment.Add(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.OffHandTool);
				}
				if (gameManager.CurrentMode.CustomGameSettings.SpawnEquipmentSet != SpawnableToolConfig.CustomGameEquipmentSet.INVALID)
				{
					_availableSpawnEquipment.AddRange(SpawnableToolSettings.GetCustomGameEquipmentSet(gameManager.CurrentMode.CustomGameSettings.SpawnEquipmentSet, NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.DominantHandTool, NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.OffHandTool));
				}
			}
		}
	}
}
