[Serializable]
public class GameBoundsManager : IGameComponent
{
	private enum OutOfBoundsStates
	{
		INVALID,
		IN_BOUNDS,
		OUT_OF_BOUNDS_GRACE_PERIOD,
		OUT_OF_BOUNDS_COUNTING_DOWN,
		OUT_OF_BOUNDS_TIMER_EXPIRED
	}

	private GameManager gameManager;

	private ManualUpdateStateMachine localPlayerOutOfBoundsStateMachine;

	private Timer stateTimer;

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		localPlayerOutOfBoundsStateMachine = new ManualUpdateStateMachine();
		localPlayerOutOfBoundsStateMachine.AddState(0, null, null, null);
		localPlayerOutOfBoundsStateMachine.AddState(1, null, null, OnUpdateInBoundsState);
		localPlayerOutOfBoundsStateMachine.AddState(2, OnEnterOutOfBoundsGracePeriodState, null, OnUpdateOutOfBoundsGracePeriodState);
		localPlayerOutOfBoundsStateMachine.AddState(3, OnEnterOutOfBoundsCountingDownState, null, OnUpdateOutOfBoundsCountingDownState);
		localPlayerOutOfBoundsStateMachine.AddState(4, OnEnterOutOfBoundsTimerExpiredState, null, null);
		localPlayerOutOfBoundsStateMachine.Initialize(0);
		stateTimer = new Timer();
	}

	public void OnStart()
	{
	}

	public void OnDestroy()
	{
	}

	public void OnUpdate()
	{
		localPlayerOutOfBoundsStateMachine.Update();
		stateTimer.UpdateCallbacks();
	}

	public void OnGameStart()
	{
	}

	public void OnGameEnd()
	{
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawned);
			localPlayerOutOfBoundsStateMachine.EnterState(1);
		}
		else
		{
			localPlayerOutOfBoundsStateMachine.EnterState(0);
		}
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawned);
		localPlayerOutOfBoundsStateMachine.EnterState(0);
	}

	private void OnLocalPlayerRespawned()
	{
		localPlayerOutOfBoundsStateMachine.EnterState(1);
	}

	private void OnUpdateInBoundsState()
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.SupportsOutOfBounds && Player.LocalPlayerExists && Player.LocalPlayer.IsOutOfWorldBounds)
		{
			localPlayerOutOfBoundsStateMachine.EnterState(2);
		}
	}

	private void OnEnterOutOfBoundsGracePeriodState(ushort previousStateId, ushort previousSubStateId)
	{
		stateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.GracePeriodDuration);
	}

	private void OnUpdateOutOfBoundsGracePeriodState()
	{
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.SupportsOutOfBounds || !Player.LocalPlayerExists || !Player.LocalPlayer.IsOutOfWorldBounds || Player.LocalPlayer.IsSpawning)
		{
			localPlayerOutOfBoundsStateMachine.EnterState(1);
		}
		else if (stateTimer.TimerOver)
		{
			localPlayerOutOfBoundsStateMachine.EnterState(3);
		}
	}

	private void OnEnterOutOfBoundsCountingDownState(ushort previousStateId, ushort previousSubStateId)
	{
		stateTimer.StartTimer(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.MaxTimeOutOfBounds);
		int num = (int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.MaxTimeOutOfBounds;
		for (int i = 0; i < num; i++)
		{
			stateTimer.AddTimeElapsedCallback(i, PlayCountdownNotification);
		}
	}

	private void OnUpdateOutOfBoundsCountingDownState()
	{
		if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameBoundsSettings.SupportsOutOfBounds || !Player.LocalPlayerExists || !Player.LocalPlayer.IsOutOfWorldBounds)
		{
			localPlayerOutOfBoundsStateMachine.EnterState(1);
		}
		else if (stateTimer.TimerOver)
		{
			localPlayerOutOfBoundsStateMachine.EnterState(4);
		}
	}

	private void PlayCountdownNotification()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, ((int)Mathf.Round(stateTimer.TimeRemaining)/*cast due to .constrained prefix*/).ToString(), 1f);
	}

	private void OnEnterOutOfBoundsTimerExpiredState(ushort previousStateId, ushort previousSubStateId)
	{
		if (gameManager != null && Player.LocalPlayerExists)
		{
			gameManager.photonView.RpcMaster(gameManager.RpcMasterOnPlayerOutOfBounds);
		}
	}
}
