		LEAVING_COMBAT
	}

	public delegate void MasterOnlyPlayerDamage(PhotonPlayer deadPlayer);

	public delegate void PlayerDamageToPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, PlayerShieldEffect shieldEffect);

	public delegate void PlayerRevivePlayer(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 revivePosition);

