		public PlayerData(PhotonPlayer player, int defaultHealth)
		{
			thisPhotonPlayer = player;
			_health = new ObscuredSynchronizedField<int>(player, "HEALTH", defaultHealth, SetterPermissionMode.MASTER, OnHealthChange);
			_shield = new ObscuredSynchronizedField<int>(player, "SHIELD", 0, SetterPermissionMode.MASTER, OnHealthChange);
			_downButNotOut = new SynchronizedField<bool, bool, float, float, float>(player, "DBNO", defaultVal1: false, defaultVal2: false, 0f, 0f, 0f, SetterPermissionMode.MASTER, OnDownButNotOutChange);
			_healthOverTime = new ObscuredSynchronizedField<bool, float, float, int>(player, "HEALTH_OVER_TIME", defaultVal1: false, 0f, 0f, 0, SetterPermissionMode.MASTER);
			_shieldOverTime = new ObscuredSynchronizedField<bool, float, float, int>(player, "SHIELD_OVER_TIME", defaultVal1: false, 0f, 0f, 0, SetterPermissionMode.MASTER);
			_enemyTargetCount = new SynchronizedField<int>(player, "ENEMY_TARGETS", 0, SetterPermissionMode.MASTER);
			_lastDeathStartTime = new SynchronizedField<float>(player, "LAST_DEATH_START_TIME", float.MinValue, SetterPermissionMode.MASTER);
			_lastDeathEndTime = new SynchronizedField<float>(player, "LAST_DEATH_END_TIME", float.MinValue, SetterPermissionMode.MASTER);
			_lastDamageTime = new SynchronizedField<float>(player, "LAST_DAMAGE_TIME", float.MinValue, SetterPermissionMode.MASTER);
			_timesRevived = new SynchronizedField<int>(player, "TIMES_REVIVED", 0, SetterPermissionMode.MASTER);
			_lastReviveTime = new ObscuredSynchronizedField<float>(player, "LAST_REVIVE_TIME", float.MinValue, SetterPermissionMode.MASTER);
			_lastRevivedOtherPlayerTime = new SynchronizedField<float>(player, "LAST_REVIVE_OTHER_TIME", float.MinValue, SetterPermissionMode.MASTER);
			_invincibilityEndTime = new ObscuredSynchronizedField<float>(player, "INVINCIBILITY_END_TIME", float.MinValue, SetterPermissionMode.MASTER);
			UpdateCanDamageFriendlyPlayers();
		}

		public void ClearHealthRestoration()
		{
			_healthOverTime.Set(newValue1: false, 0f, 0f, 0);
		}

		public void RestoreHealthOverTime(float startTime, float duration, int deltaHealth)
		{
			_healthOverTime.Set(newValue1: true, startTime, duration, deltaHealth);
		}

		public void ClearShieldRestoration()
		{
			_shieldOverTime.Set(newValue1: false, 0f, 0f, 0);
		}

		public void RestoreShieldOverTime(float startTime, float duration, int deltaShield)
		{
			_shieldOverTime.Set(newValue1: true, startTime, duration, deltaShield);
		}

		public void ClearDownButNotOut()
		{
			_downButNotOut.Set(newValue1: false, newValue2: false, 0f, 0f, 0f);
		}

		public void RunDownButNotOut(float remainingValue, float currentTime, float depletionRate)
		{
			float num = remainingValue / depletionRate;
			_downButNotOut.Set(newValue1: true, newValue2: true, remainingValue, currentTime, currentTime + num);
		}

		public void PauseDownButNotOut()
		{
			_downButNotOut.Set(newValue1: true, newValue2: false, DBNOValueRemaining, 0f, 0f);
		}

		private void OnDownButNotOutChange()
		{
			if (this.DownButNotOutChangeEvent != null)
			{
				this.DownButNotOutChangeEvent(thisPhotonPlayer);
			}
			OnHealthChange();
		}

		private void OnHealthChange()
		{
			if (this.HealthChangeEvent != null)
			{
				this.HealthChangeEvent(thisPhotonPlayer);
			}
		}

		public void UpdateCanDamageFriendlyPlayers()
		{
			CanDamageFriendlyPlayers = !Profiles.Get(thisPhotonPlayer.RecNetProfileId).IsJunior();
		}
	}

