	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		GameSpawnManager.MasterOnlyPlayerRespawnEvent += OnMasterRespawnPlayer;
		localPlayerLifeStateMachine = new ManualUpdateStateMachine();
		localPlayerLifeStateMachine.AddState(0, OnEnterLocalPlayerGameNotRunningState, null, null);
		localPlayerLifeStateMachine.AddState(1, OnEnterLocalPlayerAliveState, OnExitLocalPlayerAliveState, OnUpdateLocalPlayerAliveState);
		localPlayerLifeStateMachine.AddState(2, OnEnterLocalPlayerDeadState, null, OnUpdateLocalPlayerDeadState);
		localPlayerLifeStateMachine.AddState(3, OnEnterLocalPlayerRespawnState, OnExitLocalPlayerRespawnState, OnUpdateLocalPlayerRespawnState);
		localPlayerLifeStateMachine.AddState(4, OnEnterLocalPlayerDownButNotOutState, null, OnUpdateLocalPlayerDownButNotOutState);
		localPlayerLifeStateMachine.Initialize(0);
		localPlayerLifeStateTimer = new Timer();
		inCombatStateMachine = new ManualUpdateStateMachine();
		inCombatStateMachine.AddState(0, null, null, OnUpdateOutOfCombatState);
		inCombatStateMachine.AddState(1, OnEnterInCombatState, OnExitInCombatState, null);
		inCombatStateMachine.AddState(1, 0, null, null, OnUpdateInCombatSubState);
		inCombatStateMachine.AddState(1, 1, OnEnterLeavingCombatSubState, null, OnUpdateLeavingCombatSubState);
		inCombatStateMachine.Initialize(0);
		inCombatTimer = new Timer();
		Enemy.EnemySpawnEvent += OnEnemySpawn;
		Enemy.EnemyDeathEvent += OnEnemyDeath;
		Enemy.TookDamageEvent += OnEnemyTookDamage;
		Player.LocalPlayerEnteredKillzoneEvent += new Action<Killzone>(OnLocalPlayerEnterKillzone);
		gameManager.TeamManager.TeamChangeEvent += OnTeamChange;
		Profiles.OnProfileUpdated += OnProfileUpdated;
	}

	public void OnStart()
	{
		CreatePlayerUI();
		UpdatePlayerUI();
	}

	public void OnDestroy()
	{
		GameSpawnManager.MasterOnlyPlayerRespawnEvent -= OnMasterRespawnPlayer;
		Enemy.EnemySpawnEvent -= OnEnemySpawn;
		Enemy.EnemyDeathEvent -= OnEnemyDeath;
		Enemy.TookDamageEvent -= OnEnemyTookDamage;
		GameReviveHandshakeGesture.StaticIsEnabled = false;
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnTeamChange;
		}
		ClearAllFeedbackVisualEffects();
		StopPersistentNotification();
		if (PlayerGameRoleManager.Instance != null)
		{
			PlayerGameRoleManager.Instance.RequestRemoveRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
		}
		Player.LocalPlayerEnteredKillzoneEvent -= new Action<Killzone>(OnLocalPlayerEnterKillzone);
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.RemoveToolInteractionRestriction(this);
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
		Profiles.OnProfileUpdated -= OnProfileUpdated;
	}

	public void OnUpdate()
	{
		localPlayerLifeStateMachine.Update();
		localPlayerLifeStateTimer.UpdateCallbacks();
		inCombatStateMachine.Update();
		inCombatTimer.UpdateCallbacks();
		if (gameManager.IsGameRunning)
		{
			MasterUpdateAllPlayersHealOverTime();
			MasterUpdateAllPlayersDownButNotOut();
		}
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
		if (playerUIs.TryGetValue(player, out var value))
		{
			ObjectPool.Instance.Release(value);
			playerUIs.Remove(player);
		}
	}

	private void OnMasterRespawnPlayer(PhotonPlayer respawnedPlayer)
	{
		if (!GameManager.IsSandboxActive && gameManager.CurrentMode.CombatSettings.RestoreHealthOnRespawn)
		{
			MasterResetPlayerHealth(respawnedPlayer);
		}
	}

	public void OnGameStart()
	{
		EnemyManager.SupportsEnemyOnEnemyFriendlyFire = gameManager.CurrentMode.CombatSettings.SupportsEnemyOnEnemyFriendlyFire;
		EnemyManager.SupportsPlayerOnEnemyFriendlyFire = gameManager.CurrentMode.CombatSettings.SupportsPlayerOnEnemyFriendlyFire;
		if (gameManager.CurrentMode.CombatSettings.SupportsHandshakeReviving)
		{
			GameReviveHandshakeGesture.StaticIsEnabled = true;
			GameReviveHandshakeGesture.StaticRunDuration = gameManager.CurrentMode.CombatSettings.HandshakeReviveHoldDuration;
		}
		foreach (PhotonPlayer activePlayer in gameManager.TeamManager.GetActivePlayers())
		{
			gameManager.CombatManager.MasterResetTimesRevivedForPlayer(activePlayer);
		}
	}

	public void OnGameEnd()
	{
		EnemyManager.SupportsEnemyOnEnemyFriendlyFire = true;
		EnemyManager.SupportsPlayerOnEnemyFriendlyFire = true;
		GameReviveHandshakeGesture.StaticIsEnabled = false;
		ClearActiveHandshakeReviveFeedback();
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		UpdatePlayerUI();
		InitializeEnemyCombatUI();
		if (!localPlayerIsSpectator && (gameManager.CurrentMode.CombatSettings.SupportsEnemyOnPlayerCombat || gameManager.CurrentMode.CombatSettings.SupportsPlayerOnPlayerCombat))
		{
			localPlayerLifeStateMachine.EnterState(1);
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.HandCollisionChanged += OnPlayerHandCollision;
			});
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.GestureDetected += OnPlayerHandGestureDetected;
			});
		}
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		UpdatePlayerUI();
		ResetEnemyCombatUI();
		localPlayerLifeStateMachine.EnterState(0);
		if (!localPlayerIsSpectator)
		{
			ClearAllFeedbackVisualEffects();
			StopPersistentNotification();
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.HandCollisionChanged -= OnPlayerHandCollision;
			});
			Player.LocalPlayer.BothHands.ForEach(delegate(PlayerHand x)
			{
				x.Gestures.GestureDetected += OnPlayerHandGestureDetected;
			});
		}
	}

	private void OnProfileUpdated(long rrProfileId)
	{
		PhotonPlayer fromRecNetProfileId = PhotonPlayer.GetFromRecNetProfileId(rrProfileId);
		if (fromRecNetProfileId != null)
		{
			GetPlayerData(fromRecNetProfileId)?.UpdateCanDamageFriendlyPlayers();
		}
	}

	private PlayerData GetPlayerData(PhotonPlayer player)
	{
		PlayerData value = null;
		if (player != null && !playerData.TryGetValue(player.ID, out value))
		{
			value = new PlayerData(player, gameManager.CurrentMode.CombatSettings.DefaultHealth);
			value.HealthChangeEvent += OnPlayerHealthChange;
			value.DownButNotOutChangeEvent += OnPlayerDownButNotOutChange;
			playerData[player.ID] = value;
		}
		return value;
	}

	public int GetPlayerHealth(PhotonPlayer player)
	{
		return GetPlayerData(player).Health;
	}

	public int GetPlayerShield(PhotonPlayer player)
	{
		return GetPlayerData(player).Shield;
	}

	public float GetLastDamageTime(PhotonPlayer player)
	{
		return GetPlayerData(player).LastDamageTime;
	}

	public bool PlayerIsAlive(PhotonPlayer player)
	{
		return GetPlayerHealth(player) > 0 || !gameManager.CurrentMode.CombatSettings.SupportsCombat;
	}

	public bool IsPlayerDownButNotOut(PhotonPlayer player)
	{
		if (!gameManager.CurrentMode.CombatSettings.SupportsDownButNotOut)
		{
			return false;
		}
		return GetPlayerData(player).IsDownButNotOut;
	}

	public float GetPlayerDownButNotOutValue(PhotonPlayer player)
	{
		if (!gameManager.CurrentMode.CombatSettings.SupportsDownButNotOut)
		{
			return 0f;
		}
		PlayerData playerData = GetPlayerData(player);
		return playerData.DBNOValueRemaining;
	}

	public bool PlayerCanBeRevived(PhotonPlayer player, out float timeUntilRevive)
	{
		timeUntilRevive = GetTimeUntilPlayerReviveAvailable(player);
		return !PlayerIsAlive(player) && timeUntilRevive <= 0f;
	}

	public int TeamPlayersAliveCount(GameTeam team)
	{
		int num = 0;
		PhotonPlayer[] teamPlayers = gameManager.TeamManager.GetTeamPlayers(team);
		for (int i = 0; i < teamPlayers.Length; i++)
		{
			if (PlayerIsAlive(teamPlayers[i]))
			{
				num++;
			}
		}
		return num;
	}

	public bool TeamIsAlive(GameTeam team)
	{
		bool result = false;
		PhotonPlayer[] teamPlayers = gameManager.TeamManager.GetTeamPlayers(team);
		for (int i = 0; i < teamPlayers.Length; i++)
		{
			if (PlayerIsAlive(teamPlayers[i]))
			{
				result = true;
				break;
			}
		}
		return result;
	}

	public float GetPlayerLastDeathStartTime(PhotonPlayer player)
	{
		return GetPlayerData(player).LastDeathStartTime;
	}

	public float GetPlayerLastDeathEndTime(PhotonPlayer player)
	{
		return GetPlayerData(player).LastDeathEndTime;
	}

	public void MasterResetPlayerHealth(PhotonPlayer player, float restoreHealthPercentage = 1f)
	{
		PlayerData playerData = GetPlayerData(player);
		MasterClearDownButNotOut(playerData);
		MasterSetPlayerShield(playerData, 0);
		MasterSetPlayerHealth(playerData, Mathf.RoundToInt((float)gameManager.CurrentMode.CombatSettings.DefaultHealth * restoreHealthPercentage));
	}

	public void MasterDamagePlayer(PhotonPlayer player, int damage, bool ignoreShield)
	{
		MasterDamagePlayer(player, damage, ignoreShield, out var _, out var _);
	}

	public void MasterDamagePlayer(PhotonPlayer player, int damage, bool ignoreShield, out PlayerDamageResult damageResult, out PlayerShieldEffect shieldEffect)
	{
		damageResult = PlayerDamageResult.DAMAGED;
		shieldEffect = PlayerShieldEffect.NONE;
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		PlayerData playerData = GetPlayerData(player);
		int shield = playerData.Shield;
		int num = 0;
		if (gameManager.CurrentMode.CombatSettings.SupportsPlayerShield && !ignoreShield)
		{
			num = Mathf.Min(shield, damage);
			if (num > 0)
			{
				shieldEffect = ((num < shield) ? PlayerShieldEffect.DAMAGED : PlayerShieldEffect.BROKE);
				MasterSetPlayerShield(playerData, shield - num);
			}
		}
		int health = playerData.Health;
		int num2 = damage - num;
		if (num2 > 0)
		{
			MasterSetPlayerHealth(playerData, health - num2);
		}
		if (health > 0 && num2 >= health)
		{
			damageResult = PlayerDamageResult.KILLED;
		}
		bool supportsDownButNotOut = gameManager.CurrentMode.CombatSettings.SupportsDownButNotOut;
		if (damageResult == PlayerDamageResult.KILLED && supportsDownButNotOut)
		{
			MasterSetDownButNotOut(playerData, gameManager.CurrentMode.CombatSettings.DownButNotOutMaxValue);
			damageResult = PlayerDamageResult.DOWNED;
		}
	}

	public void MasterKillPlayer(PhotonPlayer player)
	{
		PlayerData playerData = GetPlayerData(player);
		MasterClearDownButNotOut(playerData);
		MasterSetPlayerShield(playerData, 0);
		MasterSetPlayerHealth(playerData, 0);
	}

	public void MasterRestorePlayerHealth(PhotonPlayer player, int healthRestoreAmount, float healthRestoreDuration)
	{
		PlayerData playerData = GetPlayerData(player);
		MasterRestorePlayerHealth(playerData, healthRestoreAmount, healthRestoreDuration);
	}

	private void MasterRestorePlayerHealth(PlayerData playerData, int healthRestoreAmount, float healthRestoreDuration)
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (playerData.IsRestoringHealthOverTime)
			{
				MasterSetPlayerHealth(playerData, playerData.Health);
			}
			if (healthRestoreDuration <= 0.01f)
			{
				MasterSetPlayerHealth(playerData, playerData.Health + healthRestoreAmount);
			}
			else
			{
				playerData.RestoreHealthOverTime((float)PhotonNetwork.time, healthRestoreDuration, Mathf.RoundToInt(healthRestoreAmount));
			}
		}
	}

	public void MasterRestorePlayerShield(PhotonPlayer player, int shieldRestoreAmount, float shieldRestoreDuration)
	{
		if (PhotonNetwork.isMasterClient)
		{
			PlayerData playerData = GetPlayerData(player);
			if (playerData.IsRestoringShieldOverTime)
			{
				MasterSetPlayerShield(playerData, playerData.Shield);
			}
			if (shieldRestoreDuration <= 0.01f)
			{
				MasterSetPlayerShield(playerData, playerData.Shield + shieldRestoreAmount);
			}
			else
			{
				playerData.RestoreShieldOverTime((float)PhotonNetwork.time, shieldRestoreDuration, Mathf.RoundToInt(shieldRestoreAmount));
			}
		}
	}

	private void MasterSetPlayerHealth(PlayerData playerData, int newHealth)
	{
		if (PhotonNetwork.isMasterClient)
		{
			newHealth = Mathf.Clamp(newHealth, 0, gameManager.CurrentMode.CombatSettings.MaxHealth);
			float num = (float)PhotonNetwork.time;
			float num2 = playerData.Health;
			if ((float)newHealth < num2)
			{
				playerData.LastDamageTime = num;
			}
			if (num2 > 0f && newHealth <= 0)
			{
				playerData.LastDeathStartTime = num;
			}
			if (num2 == 0f && newHealth > 0)
			{
				playerData.LastDeathEndTime = num;
			}
			playerData.ClearHealthRestoration();
			playerData.Health = newHealth;
		}
	}

	private void MasterSetPlayerShield(PlayerData playerData, int newShield)
	{
		if (PhotonNetwork.isMasterClient)
		{
			newShield = Mathf.Clamp(newShield, 0, gameManager.CurrentMode.CombatSettings.MaximumShield);
			playerData.ClearShieldRestoration();
			playerData.Shield = newShield;
		}
	}

	private void MasterSetDownButNotOut(PlayerData playerData, float remainingValue)
	{
		if (PhotonNetwork.isMasterClient)
		{
			remainingValue = Mathf.Max(0f, remainingValue);
			float depletionRate = gameManager.CurrentMode.CombatSettings.DownButNotOutMaxValue / gameManager.CurrentMode.CombatSettings.DownButNotOutMaxDepletionDuration;
			playerData.RunDownButNotOut(remainingValue, (float)PhotonNetwork.time, depletionRate);
		}
	}

	private void MasterClearDownButNotOut(PlayerData playerData)
	{
		if (PhotonNetwork.isMasterClient)
		{
			playerData.ClearDownButNotOut();
		}
	}

	private void MasterPauseDownButNotOut(PlayerData playerData)
