	private void MasterUpdateAllPlayersHealOverTime()
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
		float currentTime = (float)PhotonNetwork.time;
		foreach (PhotonPlayer item in activePlayers)
		{
			PlayerData playerData = GetPlayerData(item);
			MasterUpdatePlayerHealOverTime(playerData, currentTime);
			if (gameManager.CurrentMode.CombatSettings.AutoHeal)
			{
				MasterUpdatePlayerAutoHeal(playerData, currentTime, gameManager.CurrentMode.CombatSettings.DefaultHealth, gameManager.CurrentMode.CombatSettings.AutoHealDelay, gameManager.CurrentMode.CombatSettings.AutoHealDuration);
			}
		}
	}

	private void MasterUpdateAllPlayersDownButNotOut()
	{
		if (!PhotonNetwork.isMasterClient || !gameManager.CurrentMode.CombatSettings.SupportsDownButNotOut)
		{
			return;
		}
		IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer item in activePlayers)
		{
			MasterUpdatePlayerDownButNotOut(item);
		}
	}

	private void MasterUpdatePlayerHealOverTime(PlayerData playerData, float currentTime)
	{
		if (playerData.IsRestoringHealthOverTime && currentTime >= playerData.HealthRestoreStartTime + playerData.HealthRestoreDuration)
		{
			MasterSetPlayerHealth(playerData, playerData.Health);
		}
		if (playerData.IsRestoringShieldOverTime && currentTime >= playerData.ShieldRestoreStartTime + playerData.ShieldRestoreDuration)
		{
			MasterSetPlayerShield(playerData, playerData.Shield);
		}
	}

	private void MasterUpdatePlayerAutoHeal(PlayerData playerData, float currentTime, int defaultHealth, float autoHealDelay, float autoHealDuration)
	{
		int health = playerData.Health;
		if (health > 0 && health < defaultHealth && !playerData.IsRestoringHealthOverTime && currentTime - playerData.LastDamageTime >= autoHealDelay)
		{
			int healthRestoreAmount = defaultHealth - health;
			MasterRestorePlayerHealth(playerData, healthRestoreAmount, autoHealDuration);
		}
	}

	private void MasterUpdatePlayerDownButNotOut(PhotonPlayer player)
	{
		PlayerData playerData = GetPlayerData(player);
		int health = playerData.Health;
		if (health <= 0 && playerData.IsDownButNotOut && (!(playerData.DBNOValueRemaining > 0f) || (CustomDownButNotOutRespawnCondition != null && CustomDownButNotOutRespawnCondition(player))))
		{
			playerData.ClearDownButNotOut();
			if (this.MasterOnlyPlayerDeathEvent != null)
			{
				this.MasterOnlyPlayerDeathEvent(player);
			}
			gameManager.photonView.RpcAll(gameManager.RpcOnDBNOKilledPlayer, player);
		}
	}

	private float GetTimeUntilPlayerReviveAvailable(PhotonPlayer player)
	{
		float num = GetPlayerLastDeathStartTime(player) + gameManager.CurrentMode.CombatSettings.RequiredReviveDelay;
		float num2 = (float)PhotonNetwork.time;
		return Mathf.Max(0f, num - num2);
	}

	public bool PlayerIsInvincible(PhotonPlayer player)
	{
		double time = PhotonNetwork.time;
		if (IsPlayerDownButNotOut(player) && time - (double)GetPlayerLastDeathStartTime(player) < (double)gameManager.CurrentMode.CombatSettings.DownButNotOutInvincibilityDuration)
		{
			return true;
		}
		if (time - (double)GetPlayerLastDeathEndTime(player) < (double)gameManager.CurrentMode.CombatSettings.DeathInvincibilityDuration)
		{
			return true;
		}
		if (time - (double)GetPlayerLastReviveTime(player) < (double)gameManager.CurrentMode.CombatSettings.ReviveInvincibilityDuration)
		{
			return true;
		}
		if (time - (double)GetPlayerLastRevivedOtherPlayerTime(player) < (double)gameManager.CurrentMode.CombatSettings.ReviveOtherPlayerInvincibilityDuration)
		{
			return true;
		}
		if (time < (double)GetPlayerLastInvincibilityEndTime(player))
		{
			return true;
		}
		return false;
	}

	private bool PlayerIsTeleporting(PhotonPlayer player)
	{
		Player player2 = player.ToPlayer();
		return player2 != null && player2.PlayerLocomotion.IsTeleporting;
	}

