	private void OnEnterLocalPlayerGameNotRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		localPlayerHasPendingPickupTools = false;
		localLastDeathToolLeft = null;
		localLastDeathToolRight = null;
		localLastDeathEquippedTools = null;
		PlayerGameRoleManager.Instance.RequestRemoveRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
	}

	private void OnEnterLocalPlayerAliveState(ushort previousStateId, ushort previousSubStateId)
	{
		GameCombatManager.LocalPlayerChangedToAliveEvent.SafeInvoke();
		PlayerGameRoleManager.Instance.RequestRemoveRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
		FadeOutDeadMonochromeEffect();
		StopPersistentNotification();
		if (localPlayerHasPendingPickupTools)
		{
			LocalPlayerTryPickupToolsOnRevive();
		}
	}

	private void OnUpdateLocalPlayerAliveState()
	{
		if (IsPlayerDownButNotOut(PhotonNetwork.player))
		{
			localPlayerLifeStateMachine.EnterState(4);
		}
		else if (!PlayerIsAlive(PhotonNetwork.player))
		{
			localPlayerLifeStateMachine.EnterState(2);
		}
		else if (gameManager.CurrentMode.CombatSettings.PlayMonochromeEffectWhenDamaged)
		{
			SetDamageMonochromeEffect(GetPlayerHealth(PhotonNetwork.player), gameManager.CurrentMode.CombatSettings.DefaultHealth);
		}
	}

	private void OnExitLocalPlayerAliveState(ushort previousStateId, ushort previousSubStateId)
	{
		PlayerGameRoleManager.Instance.RequestAddRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
	}

	private void OnEnterLocalPlayerDeadState(ushort previousStateId, ushort previousSubStateId)
	{
		GameCombatManager.LocalPlayerChangedToDeadEvent.SafeInvoke();
		PlayerGameRoleManager.Instance.RequestAddRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
		ModeCombatSettings combatSettings = gameManager.CurrentMode.CombatSettings;
		if (combatSettings.AutoRespawnWhenDead)
		{
			localPlayerLifeStateTimer.StartTimer(combatSettings.AutoRespawnDelay);
		}
		if (combatSettings.PlayMonochromeEffectWhenDead)
		{
			FadeInDeadMonochromeEffect(combatSettings.DeadMonochromeEffectAmount);
		}
		if (combatSettings.PlayPersistentNotificationWhenDead)
		{
			PlayPersistentNotification(combatSettings.DeadPersistentNotification);
		}
		foreach (PlayerHand bothHand in Player.LocalPlayer.BothHands)
		{
			bothHand.Vibrate(200);
		}
		Player localPlayer = Player.LocalPlayer;
		if (localPlayer != null)
		{
			Tool heldTool = localPlayer.LeftHand.HeldTool;
			localLastDeathToolLeft = ((!IsToolValidForRevivePickup(heldTool)) ? null : heldTool);
			Tool heldTool2 = localPlayer.RightHand.HeldTool;
			localLastDeathToolRight = ((!IsToolValidForRevivePickup(heldTool2)) ? null : heldTool2);
			localLastDeathEquippedTools = localPlayer.ToolEquipSlots.GetAllEquippedTools();
		}
	}

	private bool IsToolValidForRevivePickup(Tool tool)
	{
		if (tool == null)
		{
			return false;
		}
		if (tool.IsSubTool)
		{
			return false;
		}
		return true;
	}

	private void OnUpdateLocalPlayerDeadState()
	{
		if (gameManager != null && gameManager.IsGameRunning)
		{
			Player.LocalPlayer.ReleaseToolsFromBothHands();
			Player.LocalPlayer.ReleaseToolsFromAllEquipSlots();
			if (!gameManager.GameCanStillBeWon && gameManager.CurrentMode.CombatSettings.PlayPersistentNotificationWhenDead)
			{
				StopPersistentNotification();
			}
			else
			{
				UpdateRespawnRevivePersistentNotification();
			}
			if (IsPlayerDownButNotOut(PhotonNetwork.player))
			{
				localPlayerLifeStateMachine.EnterState(4);
			}
			else if (gameManager.CurrentMode.CombatSettings.AutoRespawnWhenDead && localPlayerLifeStateTimer.TimerOver)
			{
				localPlayerLifeStateMachine.EnterState(3);
			}
			else if (PlayerIsAlive(PhotonNetwork.player))
			{
				localPlayerLifeStateMachine.EnterState(1);
			}
		}
	}

	private void UpdateRespawnRevivePersistentNotification()
	{
		ModeCombatSettings combatSettings = gameManager.CurrentMode.CombatSettings;
		bool flag = combatSettings.SupportsPlayerReviving && combatSettings.RequiredReviveDelay > 0f;
		float timeUntilPlayerReviveAvailable = GetTimeUntilPlayerReviveAvailable(PhotonNetwork.player);
		bool flag2 = flag && timeUntilPlayerReviveAvailable > 0f;
		bool flag3 = flag && timeUntilPlayerReviveAvailable <= 0f;
		bool flag4 = combatSettings.AutoRespawnWhenDead && combatSettings.AutoRespawnDelay > 0f;
		string text = null;
		string subtitle = null;
		text = ((!flag3) ? combatSettings.DeadPersistentNotification : combatSettings.ReviveAvailableString);
		if (flag2)
		{
			int num = Mathf.RoundToInt(timeUntilPlayerReviveAvailable);
			subtitle = string.Format(combatSettings.ReviveCooldownSubtitleFormat, num);
		}
		else if (flag4)
		{
			int num2 = Mathf.RoundToInt(localPlayerLifeStateTimer.TimeRemaining);
			subtitle = string.Format(combatSettings.RespawnTimerFormatString, num2);
		}
		UpdatePersistentNotificationTitle(text);
		UpdatePersistentNotificationSubtitle(subtitle);
	}

	private void OnEnterLocalPlayerRespawnState(ushort previousStateId, ushort previousSubStateId)
	{
		Player.LocalPlayer.AddToolInteractionRestriction(this);
		Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
		gameManager.SpawnManager.LocalPlayerRequestRespawn();
	}

	private void OnUpdateLocalPlayerRespawnState()
	{
		if (gameManager != null && gameManager.IsGameRunning && GetPlayerHealth(PhotonNetwork.player) > 0)
		{
			localPlayerLifeStateMachine.EnterState(1);
		}
	}

	private void OnExitLocalPlayerRespawnState(ushort nextStateId, ushort nextSubStateId)
	{
		Player.LocalPlayer.RemoveToolInteractionRestriction(this);
		Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
	}

	private void OnEnterLocalPlayerDownButNotOutState(ushort previousStateId, ushort previousSubStateId)
	{
		PlayerGameRoleManager.Instance.RequestAddRole(PhotonNetwork.player, GameRoleId.AG_ELIMINATED);
		ModeCombatSettings combatSettings = gameManager.CurrentMode.CombatSettings;
		if (combatSettings.PlayMonochromeEffectWhenDownButNotOut)
		{
			FadeInDeadMonochromeEffect(combatSettings.DownButNotOutMonochromeEffectAmount);
		}
		if (combatSettings.PlayPersistentNotificationWhenDownButNotOut)
		{
			PlayPersistentNotification(combatSettings.DownButNotOutPersistentNotification);
		}
	}

	private void OnUpdateLocalPlayerDownButNotOutState()
	{
		if (!(gameManager != null) || !gameManager.IsGameRunning)
		{
			return;
		}
		Player.LocalPlayer.ReleaseToolsFromBothHands();
		if (PlayerIsAlive(PhotonNetwork.player))
		{
			localPlayerLifeStateMachine.EnterState(1);
			return;
		}
		if (!IsPlayerDownButNotOut(PhotonNetwork.player))
		{
			localPlayerLifeStateMachine.EnterState(2);
		}
		if (gameManager.CurrentMode.CombatSettings.PlayPersistentNotificationWhenDownButNotOut)
		{
			UpdatePersistentNotificationTitle(gameManager.CurrentMode.CombatSettings.DownButNotOutPersistentNotification);
			UpdatePersistentNotificationSubtitle(gameManager.CurrentMode.CombatSettings.ReviveAvailableString);
		}
	}

	public bool RequestWeaponOnPlayerDamage(Weapon weapon, WeaponDamageType damageType, Player defender, Player.BodyPart defenderBodyPart, WeaponImpact impact)
	{
		if (weapon.Wielder.Enemy != null)
		{
			return RequestEnemyOnPlayerDamage(weapon.Wielder.Enemy, defender, defenderBodyPart, impact.Point);
		}
		if (weapon.Wielder.Player != null)
		{
			return RequestPlayerOnPlayerWeaponDamage(weapon, damageType, weapon.Wielder.Player.PhotonPlayer, defender.PhotonPlayer, defenderBodyPart, impact);
		}
		return false;
	}

	public bool RequestWeaponOnToolDamage(Weapon weapon, WeaponDamageType damageType, Player defender, Tool defenderTool, WeaponImpact impact)
	{
		if (weapon.Wielder.Enemy != null)
		{
			bool wasBlocked = false;
			return RequestEnemyOnToolDamage(weapon.Wielder.Enemy, defenderTool, impact.Point, out wasBlocked);
		}
		if (weapon.Wielder.Player != null)
		{
			return RequestWeaponOnToolDamage(weapon, damageType, weapon.Wielder.Player.PhotonPlayer, defender.PhotonPlayer, defenderTool, impact);
		}
		return false;
	}

	public bool RequestWeaponOnToolDamage(Weapon weapon, WeaponDamageType damageType, PhotonPlayer attacker, PhotonPlayer defender, Tool defenderTool, WeaponImpact impact)
	{
		Weapon component = defenderTool.GetComponent<Weapon>();
		bool isHeldByPlayer = defenderTool.IsHeldByPlayer;
		if (component != null && component.CanBlockWeaponAttacks && isHeldByPlayer)
		{
			return CanLocallyRequestPlayerOnPlayerWeaponDamage(weapon, damageType, attacker, defender);
		}
		if (gameManager.CurrentMode.CombatSettings.SupportsPlayerOnPlayerToolDisarm && isHeldByPlayer)
		{
			PhotonPlayer attacker2 = null;
			if (weapon != null && weapon.Wielder.IsValid && weapon.Wielder.Player != null)
			{
				attacker2 = weapon.Wielder.Player.PhotonPlayer;
			}
			if (IsValidPlayerOnPlayerDamage(attacker2, defender, weapon, damageType))
			{
				bool wasBlocked = false;
				return TryDisarm(defenderTool, out wasBlocked);
			}
		}
		else if (gameManager.CurrentMode.CombatSettings.SupportsPlayerOnPlayerToolDamageForwarding && (weapon.CanDamagePlayersViaHeldTool || !isHeldByPlayer))
		{
			return RequestPlayerOnPlayerWeaponDamage(weapon, damageType, attacker, defender, Player.BodyPart.None, impact);
		}
		return false;
	}

	private bool CanLocallyRequestPlayerOnPlayerWeaponDamage(Weapon weapon, WeaponDamageType damageType, PhotonPlayer attacker, PhotonPlayer defender)
	{
		bool flag = defender.IsLocal;
		if (damageType != WeaponDamageType.EXPLOSIVE && !weapon.DefenderHasDamageAuthority)
		{
			flag |= attacker.IsLocal;
		}
		return flag && IsValidPlayerOnPlayerDamage(attacker, defender, weapon, damageType);
	}

	private bool RequestPlayerOnPlayerWeaponDamage(Weapon weapon, WeaponDamageType damageType, PhotonPlayer attacker, PhotonPlayer defender, Player.BodyPart defenderBodyPart, WeaponImpact impact)
	{
		if (CanLocallyRequestPlayerOnPlayerWeaponDamage(weapon, damageType, attacker, defender))
		{
			gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestPlayerOnPlayerDamage, weapon, damageType, attacker, defender, defenderBodyPart, impact.Point, impact.SurfaceNormal, impact.PreAttackChargeAmount, impact.ImpactId);
			return true;
		}
		return false;
	}

	public void MasterRequestPlayerOnPlayerDamage(Weapon weapon, WeaponDamageType damageType, PhotonPlayer attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, float impactChargeAmount, byte impactId)
	{
		if ((damageType != WeaponDamageType.EXPLOSIVE && weapon.ImpactAlreadyRegistered(impactId)) || !PhotonNetwork.isMasterClient || !IsValidPlayerOnPlayerDamage(attacker, defender, weapon, damageType))
		{
			return;
		}
		bool isSelfDamage = attacker == defender;
		int playerImpactDamage = weapon.GetPlayerImpactDamage(defenderImpactBodyPart, impactChargeAmount, isSelfDamage);
		int damage = ((!GameManager.IsSandboxActive) ? playerImpactDamage : 0);
		MasterDamagePlayer(defender, damage, ignoreShield: false, out var damageResult, out var shieldEffect);
		switch (damageResult)
		{
		case PlayerDamageResult.KILLED:
			if (this.MasterOnlyPlayerDeathEvent != null)
			{
				this.MasterOnlyPlayerDeathEvent(defender);
			}
			gameManager.photonView.RpcAll(gameManager.RpcOnPlayerKilledPlayer, attacker, defender, weapon, defenderImpactBodyPart, impactPoint, impactSurfaceNormal, playerImpactDamage, shieldEffect);
			break;
		case PlayerDamageResult.DOWNED:
			gameManager.photonView.RpcAll(gameManager.RpcOnPlayerDownedPlayer, attacker, defender, weapon, defenderImpactBodyPart, impactPoint, impactSurfaceNormal, playerImpactDamage, shieldEffect);
			break;
		default:
			gameManager.photonView.RpcAll(gameManager.RpcOnPlayerDamagedPlayer, attacker, defender, weapon, defenderImpactBodyPart, impactPoint, impactSurfaceNormal, playerImpactDamage, shieldEffect);
			break;
		}
	}

	public void OnPlayerDamagedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, PlayerShieldEffect shieldEffect)
	{
		if (this.PlayerDamagedPlayerEvent != null)
		{
			this.PlayerDamagedPlayerEvent(attacker, defender, weapon, defenderBodyPart, impactPoint, impactSurfaceNormal, damage, shieldEffect);
		}
		if (weapon != null)
		{
			weapon.NotifyWeaponDealtPlayerOnPlayerDamage(defender.ToPlayer());
		}
		if (defender != null && defender.IsLocal && gameManager.CurrentMode.CombatSettings.PlayRedFlashWhenDamaged)
		{
			PlayRedFlash();
		}
	}

	public void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, PlayerShieldEffect shieldEffect)
	{
		if (this.PlayerKilledPlayerEvent != null)
		{
			this.PlayerKilledPlayerEvent(attacker, defender, weapon, defenderBodyPart, impactPoint, impactSurfaceNormal, damage, shieldEffect);
			if (attacker.IsLocal)
			{
				Tool attackerTool = ((!(weapon != null)) ? null : weapon.Tool);
				ChallengeEvents.ElminatedOtherPlayerEventData eventData = new ChallengeEvents.ElminatedOtherPlayerEventData(attacker, defender, attackerTool, defenderBodyPart);
				ChallengeEvents.ElminatedOtherPlayer(eventData);
			}
			else if (defender.IsLocal)
			{
				ChallengeEvents.LocalPlayerEliminatedEventData eventData2 = new ChallengeEvents.LocalPlayerEliminatedEventData(attacker, defender);
				ChallengeEvents.LocalPlayerEliminated(eventData2);
			}
		}
	}

	public void OnPlayerDownedPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, PlayerShieldEffect shieldEffect)
	{
		if (this.PlayerDownedPlayerEvent != null)
		{
			this.PlayerDownedPlayerEvent(attacker, defender, weapon, defenderBodyPart, impactPoint, impactSurfaceNormal, damage, shieldEffect);
			if (attacker.IsLocal)
			{
				Tool attackerTool = ((!(weapon != null)) ? null : weapon.Tool);
				ChallengeEvents.ElminatedOtherPlayerEventData eventData = new ChallengeEvents.ElminatedOtherPlayerEventData(attacker, defender, attackerTool, defenderBodyPart);
				ChallengeEvents.ElminatedOtherPlayer(eventData);
			}
			else if (defender.IsLocal)
			{
				ChallengeEvents.LocalPlayerEliminatedEventData eventData2 = new ChallengeEvents.LocalPlayerEliminatedEventData(attacker, defender);
				ChallengeEvents.LocalPlayerEliminated(eventData2);
			}
		}
	}

	private bool IsValidPlayerOnPlayerDamage(PhotonPlayer attacker, PhotonPlayer defender, Weapon attackingWeapon, WeaponDamageType damageType)
	{
		if (!GameManager.IsSandboxActive && !gameManager.IsGameRunning)
		{
			return false;
		}
		if (!gameManager.CurrentMode.CombatSettings.SupportsPlayerOnPlayerCombat)
		{
			return false;
		}
		if (!CombatEnabled)
		{
			return false;
		}
		if (attacker == null || defender == null)
		{
			return false;
		}
		if (!GameManager.IsSandboxActive && attacker == defender && !attackingWeapon.CanSuicide)
		{
			return false;
		}
		if (!PlayerIsAlive(defender))
		{
			return false;
		}
		if (PlayerIsInvincible(defender))
		{
			return false;
		}
		if (gameManager.TeamManager.IsPlayerSpectator(attacker) || gameManager.TeamManager.IsPlayerSpectator(defender))
		{
			return false;
		}
		if (attackingWeapon == null)
		{
			return false;
		}
		bool flag = attacker != defender && gameManager.TeamManager.PlayersAreTeammates(attacker, defender);
		bool flag2 = gameManager.CurrentMode.CombatSettings.SupportsFriendlyFire && FriendlyFireEnabled;
		if (!flag2 && flag && !gameManager.CurrentMode.CombatSettings.WeaponTypesThatAlwaysSupportFriendlyFire.Contains(damageType))
		{
			return false;
		}
		if (flag2 && flag && gameManager.CurrentMode.CombatSettings.SupportsPlayerDataBasedFriendlyFire)
		{
			PlayerData playerData = GetPlayerData(attacker);
			if (playerData != null && !playerData.CanDamageFriendlyPlayers)
			{
				return false;
			}
		}
		if (flag2 && flag && gameManager.CurrentMode.CombatSettings.WeaponTypesThatDoNotSupportFriendlyFire.Contains(damageType))
		{
			return false;
		}
		return true;
	}

	public bool RequestEnemyOnPlayerDamage(Enemy attacker, Player defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint)
	{
		if (CanLocallyRequestEnemyOnPlayerDamage(attacker, defender))
		{
			gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestEnemyOnPlayerDamage, attacker, defender.PhotonPlayer, defenderImpactBodyPart, impactPoint);
			return true;
		}
		return false;
	}

	public bool RequestEnemyOnToolDamage(Enemy attacker, Tool defenderTool, Vector3 impactPoint, out bool wasBlocked)
	{
		wasBlocked = false;
		if (gameManager.CurrentMode.CombatSettings.SupportsEnemyOnPlayerToolDisarm && (!gameManager.CurrentMode.CombatSettings.RestrictEnemyOnPlayerToolDisarmToCertainEnemyTypes || gameManager.CurrentMode.CombatSettings.RestrictedEnemyOnPlayerToolDisarmAllowedTypes.Contains(attacker.EnemyType)))
		{
			return TryDisarm(defenderTool, out wasBlocked);
		}
		if (gameManager.CurrentMode.CombatSettings.SupportsEnemyOnPlayerToolDamageForwarding && defenderTool.IsHeld && defenderTool.HolderPlayer != null)
		{
			Weapon component = defenderTool.GetComponent<Weapon>();
			if (component != null && component.IsShield)
			{
				wasBlocked = true;
				return CanLocallyRequestEnemyOnPlayerDamage(attacker, defenderTool.HolderPlayer);
			}
			return RequestEnemyOnPlayerDamage(attacker, defenderTool.HolderPlayer, Player.BodyPart.None, impactPoint);
		}
		return CanLocallyRequestEnemyOnPlayerDamage(attacker, defenderTool.HolderPlayer);
	}

	private bool CanLocallyRequestEnemyOnPlayerDamage(Enemy attacker, Player defender)
	{
		return defender != null && defender.PhotonPlayer.IsLocal && IsValidEnemyOnPlayerDamage(attacker, defender.PhotonPlayer);
	}

	public void MasterRequestEnemyOnPlayerDamage(Enemy attacker, PhotonPlayer defender, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint)
	{
		if (!PhotonNetwork.isMasterClient || !IsValidEnemyOnPlayerDamage(attacker, defender))
		{
			return;
		}
		int playerAttackDamage = attacker.GetPlayerAttackDamage(defenderImpactBodyPart);
		MasterDamagePlayer(defender, playerAttackDamage, ignoreShield: false, out var damageResult, out var shieldEffect);
		switch (damageResult)
		{
		case PlayerDamageResult.KILLED:
			if (this.MasterOnlyPlayerDeathEvent != null)
			{
				this.MasterOnlyPlayerDeathEvent(defender);
			}
			gameManager.photonView.RpcAll(gameManager.RpcOnEnemyKilledPlayer, attacker, defender, defenderImpactBodyPart, impactPoint, shieldEffect);
			break;
		case PlayerDamageResult.DOWNED:
			gameManager.photonView.RpcAll(gameManager.RpcOnEnemyDownedPlayer, attacker, defender, defenderImpactBodyPart, impactPoint, shieldEffect);
			break;
		default:
			gameManager.photonView.RpcAll(gameManager.RpcOnEnemyDamagedPlayer, attacker, defender, defenderImpactBodyPart, impactPoint, shieldEffect);
			break;
		}
	}

