	private bool ShouldDisplayEnemyHealthBar(Enemy enemy)
	{
		if (enemy.HealthBarSetting == Enemy.HealthBarMode.ALWAYS_DISPLAY)
		{
			return true;
		}
		if (enemy.HealthBarSetting == Enemy.HealthBarMode.NEVER_DISPLAY)
		{
			return false;
		}
		if (!enemyCombatUIInitialized)
		{
			return false;
		}
		ModeCombatSettings combatSettings = gameManager.CurrentMode.CombatSettings;
		if (!combatSettings.DisplayEnemyCombatUI)
		{
			return false;
		}
		if (gameManager.TeamManager.PlayerOnTeam(PhotonNetwork.player, enemy.Team) && !combatSettings.DisplayEnemyUIForAllies)
		{
			return false;
		}
		return true;
	}

