	public void MasterRequestPlayerRevive(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer, Vector3 revivePoint)
	{
		if (!PhotonNetwork.isMasterClient || !IsValidPlayerRevive(revivedPlayer, revivingPlayer))
		{
			return;
		}
		float restoreHealthPercentage = 1f;
		PlayerData playerData = GetPlayerData(revivedPlayer);
		if (gameManager.CurrentMode.CombatSettings.ReviveWithCustomHealthAmount)
		{
			restoreHealthPercentage = gameManager.CurrentMode.CombatSettings.DefaultRevivedPlayerHealthPercentage / 100f;
			if (gameManager.CurrentMode.CombatSettings.RevivedPlayerHealthPercentageByNumberOfRevives != null && gameManager.CurrentMode.CombatSettings.RevivedPlayerHealthPercentageByNumberOfRevives.Length > 0)
			{
				int num = Mathf.Min(playerData.TimesRevived, gameManager.CurrentMode.CombatSettings.RevivedPlayerHealthPercentageByNumberOfRevives.Length - 1);
				restoreHealthPercentage = gameManager.CurrentMode.CombatSettings.RevivedPlayerHealthPercentageByNumberOfRevives[num] / 100f;
			}
		}
		MasterResetPlayerHealth(revivedPlayer, restoreHealthPercentage);
		if (revivingPlayer != null)
		{
			GetPlayerData(revivingPlayer).LastRevivedOtherPlayerTime = (float)PhotonNetwork.time;
		}
		playerData.TimesRevived++;
		gameManager.photonView.RpcAll(gameManager.RpcOnPlayerRevive, revivedPlayer, revivingPlayer, revivePoint);
	}

