	public bool IsValidPlayerRevive(PhotonPlayer revivedPlayer, PhotonPlayer revivingPlayer)
	{
		if (!gameManager.IsGameRunning)
		{
			return false;
		}
		if (!gameManager.CurrentMode.CombatSettings.SupportsPlayerReviving)
		{
			return false;
		}
		if (!CombatEnabled)
		{
			return false;
		}
		if (revivedPlayer == null || revivingPlayer == null)
		{
			return false;
		}
		if (gameManager.TeamManager.IsPlayerSpectator(revivedPlayer) || gameManager.TeamManager.IsPlayerSpectator(revivingPlayer))
		{
			return false;
		}
		if (!gameManager.TeamManager.PlayersAreTeammates(revivedPlayer, revivingPlayer))
		{
			return false;
		}
		if (!PlayerIsAlive(revivingPlayer))
		{
			return false;
		}
		if (PlayerIsAlive(revivedPlayer))
		{
			return false;
		}
		if (gameManager.CurrentMode.CombatSettings.SupportsDownButNotOut && !IsPlayerDownButNotOut(revivedPlayer))
		{
			return false;
		}
		if (GetTimeUntilPlayerReviveAvailable(revivedPlayer) > 0f)
		{
			return false;
		}
		double time = PhotonNetwork.time;
		if (time - (double)GetPlayerData(revivingPlayer).LastReviveTime <= 2.0)
		{
			return false;
		}
		if (time - (double)GetPlayerLastDeathEndTime(revivingPlayer) <= 2.0)
		{
			return false;
		}
		return true;
	}

	private void OnLocalPlayerRevived()
	{
		localPlayerHasPendingPickupTools = gameManager.CurrentMode.CombatSettings.PickupDroppedToolsOnRevive;
		if (localPlayerLifeStateMachine.CurrentStateId == 1)
		{
			LocalPlayerTryPickupToolsOnRevive();
		}
	}

	private void LocalPlayerTryPickupToolsOnRevive()
	{
		Player localPlayer = Player.LocalPlayer;
		if (localPlayerHasPendingPickupTools && localPlayer != null)
		{
			if (localLastDeathToolLeft != null && localPlayer.LeftHand.HeldTool == null)
			{
				localPlayer.LeftHand.TryPickupTool(localLastDeathToolLeft, inPhysicalPickupRange: false);
			}
			if (localLastDeathToolRight != null && localPlayer.RightHand.HeldTool == null)
			{
				localPlayer.RightHand.TryPickupTool(localLastDeathToolRight, inPhysicalPickupRange: false);
			}
			if (localLastDeathEquippedTools != null && localLastDeathEquippedTools.Length > 0)
			{
				localPlayer.ToolEquipSlots.EquipTools(localLastDeathEquippedTools);
			}
		}
		localPlayerHasPendingPickupTools = false;
		localLastDeathToolLeft = null;
		localLastDeathToolRight = null;
		localLastDeathEquippedTools = null;
	}

	private void OnPlayerHandCollision(PlayerHand localHand, PlayerHand remoteHand)
	{
		if (!RequiresHandshakeRevive)
		{
			PlayerHand revivedHand = null;
			PlayerHand revivingHand = null;
			PhotonPlayer revivedPlayer = null;
			PhotonPlayer revivingPlayer = null;
			GetRevivingPlayer(localHand, remoteHand, out revivedPlayer, out revivingPlayer, out revivedHand, out revivingHand);
			if (IsValidPlayerRevive(revivedPlayer, revivingPlayer))
			{
				Vector3 arg = (localHand.transform.position + remoteHand.transform.position) / 2f;
				gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestPlayerRevive, revivedPlayer, revivingPlayer, arg);
			}
		}
	}

	private void OnPlayerHandGestureDetected(PlayerHand triggeringHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture, Player triggeringPlayer = null, Player remotePlayer = null)
	{
		if (!RequiresHandshakeRevive || (gesture != PlayerHandGestures.Gesture.GameReviveHandshakeStart && gesture != PlayerHandGestures.Gesture.GameReviveHandshakeSuccess && gesture != PlayerHandGestures.Gesture.GameReviveHandshakeCancel))
		{
			return;
		}
		PlayerHand revivedHand = null;
		PlayerHand revivingHand = null;
		PhotonPlayer revivedPlayer = null;
		PhotonPlayer revivingPlayer = null;
		GetRevivingPlayer(triggeringHand, otherHand, out revivedPlayer, out revivingPlayer, out revivedHand, out revivingHand);
		if (revivingPlayer != null && revivingPlayer.IsLocal && IsValidPlayerRevive(revivedPlayer, revivingPlayer))
		{
			Vector3 arg = (triggeringHand.transform.position + otherHand.transform.position) / 2f;
			switch (gesture)
			{
			case PlayerHandGestures.Gesture.GameReviveHandshakeStart:
			{
				int arg2 = ((!(revivedHand != null)) ? (-1) : revivedHand.photonView.viewID);
				int arg3 = ((!(revivingHand != null)) ? (-1) : revivingHand.photonView.viewID);
				gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestStartHandshakeRevive, revivedPlayer, revivingPlayer, arg2, arg3);
				break;
			}
			case PlayerHandGestures.Gesture.GameReviveHandshakeSuccess:
				gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestPlayerRevive, revivedPlayer, revivingPlayer, arg);
				break;
			case PlayerHandGestures.Gesture.GameReviveHandshakeCancel:
				gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestCancelHandshakeRevive, revivedPlayer, revivingPlayer);
				break;
			}
		}
	}

	private void GetRevivingPlayer(PlayerHand localHand, PlayerHand remoteHand, out PhotonPlayer revivedPlayer, out PhotonPlayer revivingPlayer, out PlayerHand revivedHand, out PlayerHand revivingHand)
	{
		PhotonPlayer photonPlayer = ((!(localHand != null) || !(localHand.ThisPlayer != null)) ? null : localHand.ThisPlayer.PhotonPlayer);
		PhotonPlayer photonPlayer2 = ((!(remoteHand != null) || !(remoteHand.ThisPlayer != null)) ? null : remoteHand.ThisPlayer.PhotonPlayer);
		if (PlayerIsAlive(photonPlayer))
		{
			revivedPlayer = photonPlayer2;
			revivingPlayer = photonPlayer;
			revivedHand = remoteHand;
			revivingHand = localHand;
		}
		else
		{
			revivedPlayer = photonPlayer;
			revivingPlayer = photonPlayer2;
			revivedHand = localHand;
			revivingHand = remoteHand;
		}
	}

	private bool IsValidSandboxCreatorRevive(PhotonPlayer photonPlayer)
	{
		return GameManager.IsSandboxActive && PlayerRoomRoleManager.Instance.GetPlayerRoleDefinition(photonPlayer).CanSelfRevive.Value;
	}

