	private void StartHandshakeReviveFeedback(PhotonPlayer revivingPlayer, PlayerHand revivedHand, PlayerHand revivingHand)
	{
		GameReviveHandshakeFeedback gameReviveHandshakeFeedback = null;
		for (int i = 0; i < activeHandshakeReviveFeedback.Count; i++)
		{
			if (activeHandshakeReviveFeedback[i] != null && activeHandshakeReviveFeedback[i].RevivingPlayer == revivingPlayer)
			{
				gameReviveHandshakeFeedback = activeHandshakeReviveFeedback[i];
				break;
			}
		}
		if (gameReviveHandshakeFeedback == null)
		{
			GameReviveHandshakeFeedback handshakeReviveFeedbackPrefab = gameManager.CurrentMode.CombatSettings.HandshakeReviveFeedbackPrefab;
			if (handshakeReviveFeedbackPrefab != null)
			{
				gameReviveHandshakeFeedback = ObjectPool.Instance.Acquire(handshakeReviveFeedbackPrefab);
			}
		}
		if (gameReviveHandshakeFeedback != null)
		{
			gameReviveHandshakeFeedback.StartRunning(revivingPlayer, revivedHand, revivingHand, HandshakeReviveDuration);
			activeHandshakeReviveFeedback.Add(gameReviveHandshakeFeedback);
		}
	}

	private void StopHandshakeReviveFeedback(PhotonPlayer revivingPlayer)
	{
		handshakeReviveFeedbackScratchSpace.Clear();
		for (int i = 0; i < activeHandshakeReviveFeedback.Count; i++)
		{
			if (!(activeHandshakeReviveFeedback[i] == null) && (activeHandshakeReviveFeedback[i].RevivingPlayer == null || activeHandshakeReviveFeedback[i].RevivingPlayer == revivingPlayer))
			{
				handshakeReviveFeedbackScratchSpace.Add(activeHandshakeReviveFeedback[i]);
			}
		}
		for (int j = 0; j < handshakeReviveFeedbackScratchSpace.Count; j++)
		{
			if (handshakeReviveFeedbackScratchSpace[j] != null)
			{
				handshakeReviveFeedbackScratchSpace[j].Release();
			}
			activeHandshakeReviveFeedback.Remove(handshakeReviveFeedbackScratchSpace[j]);
		}
	}

	private void ClearActiveHandshakeReviveFeedback()
	{
		for (int i = 0; i < activeHandshakeReviveFeedback.Count; i++)
		{
			activeHandshakeReviveFeedback[i].Release();
		}
		activeHandshakeReviveFeedback.Clear();
		handshakeReviveFeedbackScratchSpace.Clear();
	}

