	public void MasterRequestPlayerInvincibility(PhotonPlayer player, float invincibilityDuration)
	{
		if (PhotonNetwork.isMasterClient && IsValidInvincibility(player))
		{
			MasterSetPlayerLastInvincibilityEndTime(player, invincibilityDuration);
		}
	}

	private bool IsValidInvincibility(PhotonPlayer player)
	{
		if (!gameManager.IsGameRunning)
		{
			return false;
		}
		if (player == null)
		{
			return false;
		}
		if (gameManager.TeamManager.IsPlayerSpectator(player))
		{
			return false;
		}
		if (!PlayerIsAlive(player))
		{
			return false;
		}
		return true;
	}

	private float GetPlayerLastInvincibilityEndTime(PhotonPlayer player)
	{
		return GetPlayerData(player).LastInvincibilityEndTime;
	}

	private void MasterSetPlayerLastInvincibilityEndTime(PhotonPlayer player, float invincibilityDuration)
	{
		if (PhotonNetwork.isMasterClient)
		{
			PlayerData playerData = GetPlayerData(player);
			float a = (float)PhotonNetwork.time + invincibilityDuration;
			playerData.LastInvincibilityEndTime = Mathf.Max(a, playerData.LastInvincibilityEndTime);
		}
	}

	private bool TryDisarm(Tool defenderTool, out bool wasBlocked)
	{
		if (IsValidDisarm(defenderTool, out wasBlocked) && defenderTool.HolderPlayer.TryDisarm(defenderTool))
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Disarmed!", 2f);
			return true;
		}
		return false;
	}

	private bool IsValidDisarm(Tool defenderTool, out bool isShield)
	{
		isShield = false;
		if (defenderTool == null)
		{
			return false;
		}
		if (!defenderTool.IsHeldByPlayer)
		{
			return false;
		}
		if (defenderTool.HolderPlayer == null || !defenderTool.HolderPlayer.isLocal)
		{
			return false;
		}
		PhotonPlayer photonPlayer = defenderTool.HolderPlayer.PhotonPlayer;
		if (!PlayerIsAlive(photonPlayer))
		{
			return false;
		}
		Weapon component = defenderTool.GetComponent<Weapon>();
		if (component != null && (component.IsShield || gameManager.CurrentMode.CombatSettings.WeaponTypesThatCannotBeDisarmed.Contains(component.DamageType)))
		{
			isShield = true;
			return false;
		}
		if (PlayerIsInvincible(photonPlayer))
		{
			return false;
		}
		return true;
	}

	private void OnLocalPlayerEnterKillzone(Killzone killzone)
	{
		Player.LocalPlayer.RespawnAtLastValidGroundPosition(dropTools: false);
		if (killzone != null && killzone.KillsPlayersOnRespawn)
		{
			int damage = ((!(gameManager.CurrentMode != null)) ? 100 : gameManager.CurrentMode.CombatSettings.MaxHealth);
			LocalRequestMiscPlayerDamage(Player.BodyPart.Head, Player.LocalPlayer.Head.transform.position, damage, damageIgnoresShield: true);
		}
	}

