	private void CreatePlayerUI()
	{
		GameObject gameObject = new GameObject("PlayerCombatUI");
		gameObject.transform.SetParent(gameManager.transform);
		if (gameManager.CurrentMode.CombatSettings.PlayerCombatUIPrefab != null)
		{
			playerUIPrefab = gameManager.CurrentMode.CombatSettings.PlayerCombatUIPrefab;
		}
		else
		{
			playerUIPrefab = (Resources.Load("[PlayerCombatUI]") as GameObject).GetComponent<PlayerCombatUI>();
		}
		ObjectPool.Instance.Prefill(playerUIPrefab, gameManager.MaximumSupportedPlayersInAnyNonSandboxMode);
	}

	private void UpdatePlayerUI()
	{
		ModeCombatSettings combatSettings = gameManager.CurrentMode.CombatSettings;
		if (!gameManager.IsGameRunning || !combatSettings.DisplayPlayerCombatUI)
		{
			foreach (PlayerCombatUI value2 in playerUIs.Values)
			{
				ObjectPool.Instance.Release(value2);
			}
			playerUIs.Clear();
			return;
		}
		GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(PhotonNetwork.player);
		IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
		foreach (PhotonPlayer item in activePlayers)
		{
			PhotonPlayer photonPlayer = item;
			if (!playerUIs.TryGetValue(photonPlayer, out var value))
			{
				value = ObjectPool.Instance.Acquire(playerUIPrefab);
				value.GameManager = gameManager;
				playerUIs[photonPlayer] = value;
			}
			if (photonPlayer != PhotonNetwork.player || combatSettings.DisplayPlayerUIForLocalPlayer)
			{
				GameTeam playerTeam2 = gameManager.TeamManager.GetPlayerTeam(item);
				bool flag = playerTeam2 == playerTeam;
				bool flag2 = (!flag && !combatSettings.HidePlayerUIForOpponents) || (flag && combatSettings.DisplayPlayerUIForAllies);
				bool healthBarAlwaysVisible = flag2 && flag && combatSettings.AlliesPlayerUIAlwaysVisible;
				value.SetPlayer(photonPlayer, flag2, healthBarAlwaysVisible);
			}
			else
			{
				ObjectPool.Instance.Release(value);
				playerUIs.Remove(photonPlayer);
			}
		}
		KeysToRemove.Clear();
		foreach (KeyValuePair<PhotonPlayer, PlayerCombatUI> playerUI in playerUIs)
		{
			if (!activePlayers.Contains(playerUI.Key))
			{
				ObjectPool.Instance.Release(playerUI.Value);
				KeysToRemove.Add(playerUI.Key);
			}
		}
		for (int i = 0; i < KeysToRemove.Count; i++)
		{
			playerUIs.Remove(KeysToRemove[i]);
		}
	}

	private void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		UpdatePlayerUI();
	}

	private void AddEnemyUI(Enemy enemy)
	{
		EnemyCombatUI enemyCombatUI = null;
		foreach (EnemyCombatUI item in enemyUI)
		{
			if (item != null && !item.IsVisible)
			{
				enemyCombatUI = item;
				break;
			}
		}
		if (enemyCombatUI == null)
		{
			enemyCombatUI = CreateEnemyUI();
		}
		enemyCombatUI.Enemy = enemy;
		enemyCombatUI.FadeIn();
	}

	private void TryRemoveEnemyUI(Enemy enemy)
	{
		foreach (EnemyCombatUI item in enemyUI)
		{
			if (item.IsVisible && item.Enemy != null && item.Enemy == enemy)
			{
				item.FadeOut();
			}
		}
	}

	private void RemoveAllEnemyUI()
	{
		foreach (EnemyCombatUI item in enemyUI)
		{
			if (item.IsVisible && (item.Enemy == null || item.Enemy.HealthBarSetting != Enemy.HealthBarMode.ALWAYS_DISPLAY))
			{
				item.FadeOut();
			}
		}
	}

	private EnemyCombatUI CreateEnemyUI()
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(gameManager.CurrentMode.CombatSettings.EnemyCombatUIPrefab.gameObject);
		EnemyCombatUI component = gameObject.GetComponent<EnemyCombatUI>();
		if (enemyUIRoot == null)
		{
			GameObject gameObject2 = new GameObject("EnemyCombatUI");
			enemyUIRoot = gameObject2.transform;
			enemyUIRoot.SetParent(gameManager.transform, worldPositionStays: false);
		}
		component.transform.SetParent(enemyUIRoot, worldPositionStays: false);
		component.gameObject.SetActive(value: false);
		enemyUI.Add(component);
		return component;
	}
}
public class GameInvisibleWall : UnityEngine.MonoBehaviour
{
	private struct CollisionPoint
	{
		public bool Active;

		public Vector3 Center;

		public float Radius;

		public float Lifetime;

		public int ImpactShaderPropertyId;

		public int AlphaShaderPropertyId;
	}

	private const int MAX_COLLISION_COUNT = 8;

	private CollisionPoint[] collisionPoints = new CollisionPoint[8];

	private void Awake()
	{
		Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
		Collider[] array = componentsInChildren;
		foreach (Collider collider in array)
		{
			if (collider.gameObject.GetComponent<CollisionForwarder>() == null)
			{
				collider.gameObject.AddComponent<CollisionForwarder>().CollisionEnter += OnCollisionEnter;
			}
		}
		for (int j = 0; j < collisionPoints.Length; j++)
		{
			ref CollisionPoint reference = ref collisionPoints[j];
			reference = new CollisionPoint
			{
				Active = false,
				Center = Vector3.zero,
				Radius = 0f,
				Lifetime = 0f,
				ImpactShaderPropertyId = Shader.PropertyToID("_ImpactPoint" + j),
				AlphaShaderPropertyId = Shader.PropertyToID("_ImpactPointAlpha" + j)
			};
		}
	}

	private void Update()
	{
		for (int i = 0; i < collisionPoints.Length; i++)
		{
			if (collisionPoints[i].Active)
			{
				collisionPoints[i].Lifetime += UnityEngine.Time.deltaTime / InvisibleWallVisualSettings.ImpactDuration;
				if (collisionPoints[i].Lifetime >= 1f)
				{
					collisionPoints[i].Active = false;
				}
			}
			float w = InvisibleWallVisualSettings.EvaluateImpactGrowthCurve(collisionPoints[i].Lifetime) * collisionPoints[i].Radius;
			float value = InvisibleWallVisualSettings.EvaluateImpactAlphaCurve(collisionPoints[i].Lifetime);
			if (!collisionPoints[i].Active)
			{
				value = 0f;
				w = 0f;
			}
			Shader.SetGlobalVector(value: new Vector4(collisionPoints[i].Center.x, collisionPoints[i].Center.y, collisionPoints[i].Center.z, w), name: collisionPoints[i].ImpactShaderPropertyId);
			Shader.SetGlobalFloat(collisionPoints[i].AlphaShaderPropertyId, value);
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		int num = 0;
		for (int i = 0; i < collisionPoints.Length; i++)
		{
			if (!collisionPoints[i].Active)
			{
				num = i;
				break;
			}
		}
		collisionPoints[num].Active = true;
		collisionPoints[num].Center = ((collision.contacts.Length <= 0) ? collision.collider.transform.position : collision.contacts[0].point);
		collisionPoints[num].Radius = InvisibleWallVisualSettings.ConvertImpactVelocityToImpactRadius(collision.relativeVelocity);
		collisionPoints[num].Lifetime = 0f;
	}
}
