public class GameManager : NetworkedSingletonMonoBehaviour<GameManager>, IPersistableSettings
{
	public delegate void WinnerNotification();

	public delegate void VoteChange();

	private class PlayerData
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private VoteChange m_VoteChangeEvent;

		private SynchronizedField<string> _vote;

		public string Vote
		{
			get
			{
				return _vote.Get();
			}
			set
			{
				_vote.Set(value);
			}
		}

		public event VoteChange VoteChangeEvent
		{
			add
			{
				VoteChange voteChange = this.m_VoteChangeEvent;
				VoteChange voteChange2;
				do
				{
					voteChange2 = voteChange;
					voteChange = Interlocked.CompareExchange(ref this.m_VoteChangeEvent, (VoteChange)Delegate.Combine(voteChange2, value), voteChange);
				}
				while (voteChange != voteChange2);
			}
			remove
			{
				VoteChange voteChange = this.m_VoteChangeEvent;
				VoteChange voteChange2;
				do
				{
					voteChange2 = voteChange;
					voteChange = Interlocked.CompareExchange(ref this.m_VoteChangeEvent, (VoteChange)Delegate.Remove(voteChange2, value), voteChange);
				}
				while (voteChange != voteChange2);
			}
		}

		public PlayerData(PhotonPlayer player)
		{
			_vote = new SynchronizedField<string>(player, "VOTE", string.Empty, SetterPermissionMode.ANYONE, VoteChangeCallback);
		}

		private void VoteChangeCallback()
		{
			if (this.VoteChangeEvent != null)
			{
				this.VoteChangeEvent();
			}
		}
	}

