	private float StartGameDelay
	{
		get
		{
			if (!IsSandboxActive)
			{
				return 10f;
			}
			return 3f;
		}
	}

	private float ResultsDelay
	{
		get
		{
			if (!IsSandboxActive)
			{
				if (SupportsLevelSwitching)
				{
					return 35f;
				}
				if (hasCustomResultsSubStateDuration)
				{
					return customResultsSubStateDuration;
				}
				return 15f;
			}
			return 1f;
		}
	}

	public static bool IsSandboxActive => GameSessions.LocalGameSession != null && GameSessions.LocalGameSession.IsSandbox;

	public bool IsInitializing => CurrentState == GameStates.INVALID || CurrentState == GameStates.INITIALIZE_RULES;

	public int MaximumSupportedPlayersInAnyNonSandboxMode
	{
		get
		{
			int num = 0;
			foreach (GameMode mode in modes)
			{
				if (!mode.IsSandboxOnly)
				{
					int num2 = 0;
					TeamDescriptor[] teamConfigs = mode.TeamSettings.TeamConfigs;
					for (int i = 0; i < teamConfigs.Length; i++)
					{
						TeamDescriptor teamDescriptor = teamConfigs[i];
						num2 += teamDescriptor.MaxTeamSize;
					}
					num = Mathf.Max(num, num2);
				}
			}
			return num;
		}
	}

	public bool SupportsSpectating => (!RecNet.Rooms.LocalRoomDetails.Room.IsAGRoom || GameSessions.LocalGameSession.Private) && CurrentMode.TeamSettings.SupportsSpectating;

