	{
		get
		{
			return _currentMode;
		}
		private set
		{
			if (value != _currentMode)
			{
				if (gameStateMachine != null)
				{
					gameStateMachine.EnterState(0);
				}
				if (NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance != null && PhotonNetwork.isMasterClient)
				{
					PhotonNetwork.Destroy(NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.gameObject);
				}
				_currentMode = value;
			}
		}
	}

