	public bool SupportsLevelSwitching => RecNet.Rooms.LocalRoomDetails != null && RecNet.Rooms.LocalRoomDetails.Room.SupportsLevelVoting;

	public bool CanVoteNextLevel => SupportsLevelSwitching && CurrentPostGameState == PostGameSubStates.RESULTS;

	public virtual bool ReadyToPlay => TeamManager.GameStartTeamRequirementsMet;

	public bool ReadyToJoinInProgress => CurrentMode.GameStartSettings.SupportsJoinInProgress && CurrentState == GameStates.GAME_RUNNING && TeamManager.GetActivePlayerVacancy() > 0;

	public bool CanToggleMode => CurrentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS || CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME;

	public float LoadingGameTimeRemaining => (CurrentPreGameState != PreGameSubStates.GAME_LOADING) ? 0f : masterGameStateTimer.TimeRemaining;

	public float PostGameTimeRemaining => (CurrentPostGameState != PostGameSubStates.RESULTS) ? 0f : masterGameStateTimer.TimeRemaining;

	public GameStates CurrentState => (GameStates)((gameStateMachine == null) ? ushort.MaxValue : gameStateMachine.CurrentStateId);

	public bool IsDisabled => CurrentState == GameStates.DISABLED;

	public bool IsPreGameOrInitializing => CurrentState == GameStates.PRE_GAME || CurrentState == GameStates.INITIALIZE_RULES;

	public bool IsGameRunning => CurrentState == GameStates.GAME_RUNNING;

	public bool IsGameRunningOrLoading => CurrentState == GameStates.GAME_RUNNING || (CurrentState == GameStates.PRE_GAME && (CurrentPreGameState == PreGameSubStates.GAME_LOADING || CurrentPreGameState == PreGameSubStates.GAME_ON));

	public bool CanSpawnGiftPackageInCurrentState => !IsGameRunningOrLoading && (CurrentState != GameStates.POST_GAME || CurrentPostGameState != PostGameSubStates.GAME_OVER) && CurrentState != GameStates.SWITCH_LEVEL;

	public bool GameCanStillBeWon => IsGameRunning && gameCanStillBeWon;

	public PreGameSubStates CurrentPreGameState
	{
		get
		{
			if (CurrentState != GameStates.PRE_GAME)
			{
				return PreGameSubStates.INVALID;
			}
			return (PreGameSubStates)gameStateMachine.CurrentSubStateId;
		}
	}

	public PostGameSubStates CurrentPostGameState
	{
		get
		{
			if (CurrentState != GameStates.POST_GAME)
			{
				return PostGameSubStates.INVALID;
			}
			return (PostGameSubStates)gameStateMachine.CurrentSubStateId;
		}
	}

	protected bool IsGameInProgress => !IsPreGameOrInitializing || GameHasSaveState;

