	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
		nextLevelVotes = new Dictionary<string, int>();
		FetchModes();
		_currentModeType = new SynchronizedField<GameModeType>(this, "CURRENT_MODE_TYPE", DefaultMode.ModeType, SetterPermissionMode.MASTER, OnModeChanged);
		GameTimerManager = new GameTimerManager();
		CombatManager = new GameCombatManager();
		SpawnManager = new GameSpawnManager();
		ScoreManager = new GameScoreManager();
		TeamManager = new GameTeamManager();
		TeleportManager = new GameMovementManager();
		UIManager = new GameUIManager();
		PowerupManager = new GamePowerupManager();
		BoundsManager = new GameBoundsManager();
		PresenceManager = new GamePresenceManager();
		CustomGameSettings = new CustomGameSettingsManager();
		gameComponentManagers.Add(GameTimerManager);
		gameComponentManagers.Add(CombatManager);
		gameComponentManagers.Add(PresenceManager);
		gameComponentManagers.Add(SpawnManager);
		gameComponentManagers.Add(ScoreManager);
		gameComponentManagers.Add(TeamManager);
		gameComponentManagers.Add(TeleportManager);
		gameComponentManagers.Add(BoundsManager);
		gameComponentManagers.Add(UIManager);
		gameComponentManagers.Add(PowerupManager);
		gameComponentManagers.Add(CustomGameSettings);
		CurrentMode = GetMode(CurrentGameModeType);
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnAwake(this);
		}
		TeamManager.LocalPlayerTeamChangeEvent += OnLocalPlayerTeamChange;
		TeamManager.TeamChangeEvent += OnTeamChange;
		Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
		SpawnManager.SpawnedEquipmentInstantiatedEvent += OnSpawnedEquipmentInstantiated;
		SpawnManager.SpawnedEquipmentDestroyedEvent += OnSpawnedEquipmentDestroyed;
		_gameHasSaveState = new SynchronizedField<bool>(this, "GAME_HAS_SAVE_STATE", defaultValue: false, SetterPermissionMode.MASTER);
		_gameStartDelay = new SynchronizedField<float>(this, "GAME_START_DELAY", 10f, SetterPermissionMode.MASTER);
		_nextLevel = new SynchronizedField<string>(this, "NEXT_LEVEL_ID", string.Empty, SetterPermissionMode.MASTER, OnNextLevelChanged);
		gameStateMachine = new SynchronizedStateMachine("GAME", SetterPermissionMode.MASTER);
		gameStateMachine.StateChangeEvent += OnStateChange;
		gameStateMachine.AddState(0, OnEnterInitializeRulesGameState, OnExitInitializeRulesGameState, OnUpdateInitializeRulesGameState);
		gameStateMachine.AddState(1, OnEnterPreGameState, null, null);
		gameStateMachine.AddState(1, 0, OnEnterWaitingForPlayersSubState, OnExitWaitingForPlayersSubState, OnUpdateWaitingForPlayersSubState);
		gameStateMachine.AddState(1, 1, OnEnterWaitingForStartSubState, OnExitWaitingForStartSubState, OnUpdateWaitingForStartSubState);
		gameStateMachine.AddState(1, 2, OnEnterGameLoadingSubState, null, OnUpdateGameLoadingSubState);
		gameStateMachine.AddState(1, 3, OnEnterGameOnSubState, OnExitGameOnSubState, OnUpdateGameOnSubState);
		gameStateMachine.AddState(2, OnEnterGameRunningState, OnExitGameRunningState, OnUpdateGameRunningState);
		gameStateMachine.AddState(3, OnEnterPostGameState, null, null);
		gameStateMachine.AddState(3, 0, OnEnterGameOverSubState, OnExitGameOverSubState, OnUpdateGameOverSubState);
		gameStateMachine.AddState(3, 1, OnEnterResultsSubState, OnExitResultsSubState, OnUpdateResultsSubState);
		gameStateMachine.AddState(4, null, null, null);
		gameStateMachine.AddState(4, 0, null, null, OnUpdateSwitchingLevelSubState);
		gameStateMachine.AddState(4, 1, OnEnterLevelSwitchedSubState, null, OnUpdateLevelSwitchedSubState);
		gameStateMachine.AddState(5, OnEnterDisabledState, null, null);
		_gameID = new SynchronizedField<string>(this, "GAME_ID", string.Empty, SetterPermissionMode.MASTER, OnGameIDChanged);
		_gameEndedPrematurely = new SynchronizedField<bool>(this, "COMPLETED_FULL_GAME", defaultValue: false, SetterPermissionMode.MASTER);
		masterGameStateTimer = new SynchronizedTimer(this, "GAME_STATE_TIMER", SetterPermissionMode.MASTER);
		localGameStateTimer = new Timer();
	}

	private void FetchModes()
	{
		GameMode[] componentsInChildren = GetComponentsInChildren<GameMode>();
		bool supportsEditorOnlyModes = false;
		if (!IsSandboxActive)
		{
			FetchNonSandboxModes(componentsInChildren, supportsEditorOnlyModes);
		}
		else
		{
			FetchAvailableSandboxModes(componentsInChildren, supportsEditorOnlyModes);
		}
		bool flag = modes != null && modes.Count == 1;
		foreach (GameMode mode in modes)
		{
			mode.GameManager = this;
			if ((flag || mode.IsDefaultMode) && (!IsSandboxActive || mode.IsSandboxOnly))
			{
				DefaultMode = mode;
				break;
			}
		}
	}

	private void FetchNonSandboxModes(GameMode[] allModes, bool supportsEditorOnlyModes)
	{
		modes.Clear();
		foreach (GameMode gameMode in allModes)
		{
			RoomSceneLocations location = GameSessions.LocalGameSession.Location;
			if (gameMode.Locations.Contains(location) && (!gameMode.IsEditorOnly || supportsEditorOnlyModes) && !gameMode.IsSandboxOnly && AGRoomSettings.IsGameModeTypeSupported(location, gameMode.ModeType))
			{
				modes.Add(gameMode);
			}
		}
	}

	private void FetchAvailableSandboxModes(GameMode[] allModes, bool supportsEditorOnlyModes)
	{
		modes.Clear();
		foreach (GameMode gameMode in allModes)
		{
			if (gameMode.IsAvailableInSandboxSession && (!gameMode.IsEditorOnly || supportsEditorOnlyModes) && gameMode.IsSandboxOnly)
			{
				modes.Add(gameMode);
			}
		}
	}

	protected virtual void Start()
	{
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnStart();
		}
		InitializeSceneOnLoad();
		gameStateMachine.Start(this, 0);
		OnModeChanged();
	}

	private void OnRecRoomPlayerCreated(Player player)
	{
		if (player.isLocal)
		{
			OnLocalRecRoomPlayerCreated();
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, player.PhotonPlayer.NickName + " joined the game", 3f);
		}
	}

	private void OnLocalRecRoomPlayerCreated()
	{
		if (IsPreGameOrInitializing)
		{
			if (TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				TeamManager.RequestNextTeam(PhotonNetwork.player);
			}
		}
		else if (IsGameRunning)
		{
			if (ReadyToJoinInProgress && TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				localGameStateTimer.AddTimeElapsedCallback(5f, PlayJoinGameInProgressNotification);
				localGameStateTimer.AddTimeElapsedCallback(8f, TryJoinInProgress);
			}
			else
			{
				localGameStateTimer.AddTimeElapsedCallback(5f, PlayGameInProgressNotification);
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (IsGameRunning && NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.RecordMatchAnalytics(finishedGame: false);
		}
		if (PlayerGameRoleManager.Instance != null)
		{
			PlayerGameRoleManager.Instance.RequestRemoveRole(PhotonNetwork.player, GameRoleId.AG_IN_GAME);
		}
		AudioManager.RemoveGlobalPlayerVoiceRolloff(this);
		if (AudioManager.MusicMixer != null)
		{
			AudioManager.MusicMixer.StopAllMusic();
		}
		if (CurrentMode != null && CurrentMode.AudioSettings.HasCustomNotificationSFX && SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.ClearNotificationAudio();
		}
		if (gameStateMachine != null)
		{
			gameStateMachine.StateChangeEvent -= OnStateChange;
		}
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnDestroy();
		}
		if (TeamManager != null)
		{
			TeamManager.TeamChangeEvent -= OnTeamChange;
		}
		Player.PlayerCreatedEvent -= new Action<Player>(OnRecRoomPlayerCreated);
		if (SpawnManager != null)
		{
			SpawnManager.SpawnedEquipmentInstantiatedEvent -= OnSpawnedEquipmentInstantiated;
			SpawnManager.SpawnedEquipmentDestroyedEvent -= OnSpawnedEquipmentDestroyed;
		}
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.ClearScreenCustomGameBehaviorControllers();
			if (CurrentMode != null && CurrentMode.QuickTimeEmotes != null)
			{
				SingletonMonoBehaviour<LocalPlayerController>.Instance.RemoveScreenCustomQuickTimeEmotes(CurrentMode.QuickTimeEmotes);
			}
		}
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
	}

	protected virtual void Update()
	{
		gameStateMachine.Update();
		masterGameStateTimer.UpdateCallbacks();
		localGameStateTimer.UpdateCallbacks();
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnUpdate();
		}
	}

	private void GameStart()
	{
		GameID = Guid.NewGuid().ToString();
		OnGameStart();
		GameManager.OnGameStartEvent.SafeInvoke();
	}

	protected virtual void OnGameStart()
	{
		if (CurrentMode.AudioSettings.HasCustomNotificationSFX)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.SetNotificationAudio(CurrentMode.AudioSettings.CustomNotificationSFX);
		}
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnGameStart();
		}
		if (CurrentMode.QuickTimeEmotes != null)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.AddScreenModeQuickTimeEmotes(CurrentMode.QuickTimeEmotes);
		}
	}

	private void GameEnd()
	{
		GameID = string.Empty;
		OnGameEnd();
		GameManager.OnGameEndEvent.SafeInvoke();
	}

	protected virtual void OnGameEnd()
	{
		if (CurrentMode.AudioSettings.HasCustomNotificationSFX)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.ClearNotificationAudio();
		}
		if (NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.RecordMatchAnalytics(finishedGame: true);
		}
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnGameEnd();
		}
		if (CurrentMode.QuickTimeEmotes != null)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.RemoveScreenCustomQuickTimeEmotes(CurrentMode.QuickTimeEmotes);
		}
	}

	protected virtual ChallengeEvents.GameEndedEventData GetEndGameChallengeEventData(bool isSpectator, bool won)
	{
		return new ChallengeEvents.GameEndedEventData(isSpectator, won, GameTimerManager.TimeElapsed);
	}

	protected virtual void InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoiningInProgress)
	{
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].InitializeLocalPlayer(localPlayerIsSpectator);
		}
		GameManager.InitializeLocalPlayerEvent.SafeInvoke(localPlayerIsSpectator, localPlayerIsJoiningInProgress);
		if (!localPlayerIsSpectator && supportsGameModeNotification)
		{
			localGameStateTimer.AddTimeElapsedCallback(localGameStateTimer.TimeElapsed + Player.RespawnDuration, PlayGameModeNotification);
		}
		UpdateLocalPlayerToolRestrictions(isGameRunning: true, localPlayerIsSpectator);
		ChallengeEvents.LocalPlayerGameStarted(localPlayerIsSpectator, localPlayerIsJoiningInProgress);
	}

	protected virtual void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].ResetLocalPlayer(localPlayerIsSpectator);
		}
		GameManager.ResetLocalPlayerEvent.SafeInvoke(localPlayerIsSpectator);
		UpdateLocalPlayerToolRestrictions(isGameRunning: false, localPlayerIsSpectator);
	}

	protected virtual void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		MasterUpdateGameStateOnPlayerChange(null);
		if (changingTeamPlayer == PhotonNetwork.player)
		{
			UpdateLocalPlayerToolRestrictions(IsGameRunning, TeamManager.IsPlayerSpectator(PhotonNetwork.player));
		}
		GameManager.OnPlayerTeamChangeEvent.SafeInvoke(changingTeamPlayer);
	}

	protected void SetMode(GameModeType modeType)
	{
		base.photonView.RpcMaster(RpcMasterSetMode, modeType);
	}

	protected void MasterSetMode(GameModeType modeType)
	{
		if (PhotonNetwork.isMasterClient && CanToggleMode)
		{
			CurrentGameModeType = modeType;
		}
	}

	private void OnModeChanged()
	{
		CurrentMode = GetMode(CurrentGameModeType);
		if (CurrentMode.AudioSettings.HasCustomPlayerVoiceRolloff)
		{
			AudioManager.AddGlobalPlayerVoiceRolloff(CurrentMode.AudioSettings.CustomPlayerVoiceRolloff, this);
		}
		else
		{
			AudioManager.RemoveGlobalPlayerVoiceRolloff(this);
		}
		SingletonMonoBehaviour<LocalPlayerController>.Instance.ClearScreenCustomGameBehaviorControllers();
		if (CurrentMode.ScreenControllers != null)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.AddScreenCustomGameBehaviorControllers(CurrentMode.ScreenControllers);
		}
		if (!SupportsSpectating && Player.LocalPlayerExists && TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			TeamManager.RequestNextTeam(PhotonNetwork.player);
		}
		if (this.ModeChangeEvent != null)
		{
			this.ModeChangeEvent();
		}
	}

	private int GetModeIndex(GameModeType modeType)
	{
		int result = -1;
		for (int i = 0; i < modes.Count; i++)
		{
			if (modes[i].ModeType == modeType)
			{
				result = i;
				break;
			}
		}
		return result;
	}

	private GameMode GetMode(GameModeType modeType)
	{
		GameMode result = null;
		foreach (GameMode mode in modes)
		{
			if (mode.ModeType == modeType)
			{
				result = mode;
				break;
			}
		}
		return result;
	}

	public void LocalPlayerTryOpenVoteNextLevelMenu()
	{
		if (CanVoteNextLevel)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowVoteDialog();
		}
	}

	public void LocalPlayerTryOpenStartOverMenu()
	{
		if (CanContinue)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Start Over", "Are you sure? This will reset your checkpoint progress.").Then(delegate(ConfirmDialogResponses r)
			{
				switch (r)
				{
				case ConfirmDialogResponses.Affirmative:
					LocalPlayerStartGame(startOver: true);
					break;
				}
			});
		}
		else
		{
			LocalPlayerStartGame();
		}
	}

	public void LocalPlayerSubmitLevelVote(string sceneName)
	{
		if (VoteIsValid(sceneName))
		{
			PlayerData playerData = GetPlayerData(PhotonNetwork.player);
			playerData.Vote = sceneName;
		}
	}

	public void OnVotesChange()
	{
		nextLevelVotes = new Dictionary<string, int>();
		int num = 0;
		string text = null;
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer player in playerList)
		{
			PlayerData playerData = GetPlayerData(player);
			string vote = playerData.Vote;
			if (VoteIsValid(vote))
			{
				int num2 = nextLevelVotes.GetOrCreate(vote) + 1;
				nextLevelVotes[vote] = num2;
				if (num2 > num)
				{
					num = num2;
					text = vote;
				}
			}
		}
		if (PhotonNetwork.isMasterClient && CanVoteNextLevel && text != null)
		{
			NextLevel = text;
		}
		if (this.VoteReceivedEvent != null)
		{
			this.VoteReceivedEvent();
		}
	}

	public int GetLevelVotes(string sceneName)
	{
		nextLevelVotes.TryGetValue(sceneName, out var value);
		return value;
	}

	private bool VoteIsValid(string sceneName)
	{
		return RecNet.Rooms.LocalRoomDetails != null && RecNet.Rooms.LocalRoomDetails.Scenes.Any((RoomScene s) => s.Name.Equals(sceneName, StringComparison.InvariantCultureIgnoreCase));
	}

	private void OnNextLevelChanged()
	{
		if (this.NextLevelChangeEvent != null)
		{
			this.NextLevelChangeEvent();
		}
	}

	private PlayerData GetPlayerData(PhotonPlayer player)
	{
		if (!playerData.TryGetValue(player.ID, out var value))
		{
			value = new PlayerData(player);
			playerData[player.ID] = value;
			value.VoteChangeEvent += OnVotesChange;
		}
		return value;
	}

	private void OnUpdateSwitchingLevelSubState()
	{
		if (!PhotonNetwork.isMasterClient || isSendingLevelSwitchRequest)
		{
			return;
		}
		long[] expectedPlayerIds = PhotonNetwork.otherPlayers.Select((PhotonPlayer p) => p.RecNetProfileId).ToArray();
		isSendingLevelSwitchRequest = true;
		GameSessions.JoinRoomScene(NextLevel, expectedPlayerIds, GameSessions.AdditionalPlayerJoinMode.AutoFollow).Then(delegate(GameSessions.JoinGameErrorCode result)
		{
			if (result == GameSessions.JoinGameErrorCode.Success)
			{
				gameStateMachine.EnterState(4, 1);
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to switch scenes at end of game: " + result);
				gameStateMachine.EnterState(1, 0);
			}
		}).Error(delegate(string error)
		{
			UnityEngine.Debug.LogError("Failed to switch scenes at end of game: " + error);
			gameStateMachine.EnterState(1, 0);
		})
			.Finally(delegate
			{
				isSendingLevelSwitchRequest = false;
			});
	}

	private void OnEnterLevelSwitchedSubState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			masterGameStateTimer.StartTimer(10f);
		}
	}

	private void OnUpdateLevelSwitchedSubState()
	{
		if (PhotonNetwork.isMasterClient && masterGameStateTimer.TimerOver)
		{
			gameStateMachine.EnterState(4, 0);
		}
	}

