	public void LocalPlayerJoinLeaveGame()
	{
		if (CurrentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS || CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME)
		{
			if (TeamManager.IsPlayerSpectator(PhotonNetwork.player))
			{
				TeamManager.RequestNextTeam(PhotonNetwork.player);
			}
			else if (SupportsSpectating)
			{
				TeamManager.LeaveTeam(PhotonNetwork.player);
			}
		}
		else
		{
			TryJoinInProgress();
		}
	}

	private void OnLocalPlayerTeamChange()
	{
		if (CurrentState == GameStates.GAME_RUNNING && !TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			if (LocalPlayerLastTeam == GameTeam.ANY)
			{
				JoinedInProgressAt = GameTimerManager.TimeElapsed;
			}
			InitializeLocalPlayer(localPlayerIsSpectator: false, localPlayerIsJoiningInProgress: true);
			if (!IsSandboxActive)
			{
				SpawnManager.LocalPlayerRequestRespawn();
			}
		}
		LocalPlayerLastTeam = TeamManager.GetPlayerTeam(PhotonNetwork.player);
	}

	public void LocalPlayerSwitchTeam(GameTeam desiredTeam)
	{
		if (TeamManager.IsPlayerSpectator(PhotonNetwork.player) || (desiredTeam != GameTeam.ANY && !CurrentMode.TeamSettings.SupportsExplicitTeamJoining))
		{
			return;
		}
		GameStates currentState = CurrentState;
		if (currentState == GameStates.PRE_GAME || currentState == GameStates.GAME_RUNNING)
		{
			PreGameSubStates currentPreGameState = CurrentPreGameState;
			if ((currentState != GameStates.PRE_GAME || currentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS || currentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME) && (currentState != GameStates.GAME_RUNNING || CurrentMode.TeamSettings.SupportsGameRunningTeamChange))
			{
				TeamManager.RequestTeamChange(PhotonNetwork.player, desiredTeam);
			}
		}
	}

	public void LocalPlayerToggleMode()
	{
		if (CanToggleMode && !TeamManager.IsPlayerSpectator(PhotonNetwork.player) && modes.Count > 1)
		{
			int modeIndex = GetModeIndex(CurrentGameModeType);
			if (modeIndex >= 0)
			{
				modeIndex = (modeIndex + 1) % modes.Count;
				SetMode(modes[modeIndex].ModeType);
			}
		}
	}

	public void MasterStopGame(bool gameEndedPrematurely = false)
	{
		if (PhotonNetwork.isMasterClient && CurrentState == GameStates.GAME_RUNNING)
		{
			GameEndedPrematurely = gameEndedPrematurely;
			gameStateMachine.EnterState(3, 0);
		}
	}

	protected virtual void InitializeSceneOnLoad()
	{
	}

	protected virtual void InitializeSceneOnPreGame()
	{
		GameManager.InitializeSceneOnPreGameEvent.SafeInvoke();
	}

	private void OnEnterInitializeRulesGameState(ushort previousStateId, ushort previousSubStateId)
	{
		localGameStateTimer.StartTimerWithoutMaxRunningTime();
		if (previousStateId == ushort.MaxValue)
		{
			if (SessionManager.InPrivateSession && RecNet.Rooms.LocalRoomDetails.LocalPlayerRole == RecNet.RoomRole.Creator && previousStateId == ushort.MaxValue)
			{
				localGameStateTimer.AddTimeElapsedCallback(4f, PlayYouveCreatedACustomRoomFeedback);
				localGameStateTimer.AddTimeElapsedCallback(12f, PlayThisRoomFeedback);
			}
			else
			{
				localGameStateTimer.AddTimeElapsedCallback(4f, PlayWaitingForPlayersOneFeedback);
				localGameStateTimer.AddTimeElapsedCallback(12f, PlayWaitingForPlayersTwoFeedback);
				localGameStateTimer.AddTimeElapsedCallback(12f, PlayerPracticeObjectAttractFX);
			}
		}
	}

	private void OnExitInitializeRulesGameState(ushort previousStateId, ushort previousSubStateId)
	{
		UpdateLocalPlayerToolRestrictions(IsGameRunning, TeamManager.IsPlayerSpectator(PhotonNetwork.player));
	}

	private void OnUpdateInitializeRulesGameState()
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (CurrentMode.GameRuleManagerPrefab == null)
			{
				gameStateMachine.EnterState(1, 0);
			}
			else if (NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance == null)
			{
				PhotonNetwork.InstantiateSceneObject(_currentMode.GameRuleManagerPrefab.gameObject.name, Vector3.zero, Quaternion.identity, 1f, 0, null);
			}
			else if (NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.Started)
			{
				gameStateMachine.EnterState(1, 0);
			}
		}
	}

	private void OnEnterPreGameState(ushort previousStateId, ushort previousSubStateId)
	{
		if (PhotonNetwork.isMasterClient)
		{
			GameSessions.SetGameInProgress(GameHasSaveState);
		}
		GameEndedPrematurely = false;
		JoinedInProgressAt = null;
		if (Player.LocalPlayerExists)
		{
			TeamManager.RequestNextTeam(PhotonNetwork.player);
		}
		PresenceManager.CurrentPresenceString = null;
		InitializeSceneOnPreGame();
		bool runToolReset = previousStateId == 2 || previousStateId == 3 || previousStateId == 1;
		UpdateSceneEquipment(runToolReset);
		RecRoomSceneManager.Instance.EquipmentManager.EnablePracticeObjects(enabled: true);
	}

	private void OnEnterWaitingForPlayersSubState(ushort previousStateId, ushort previousSubStateId)
	{
		localGameStateTimer.StartTimerWithoutMaxRunningTime();
		localGameStateTimer.AddTimeElapsedCallback(4f, PlayWaitingForPlayersTwoFeedback);
		localGameStateTimer.AddTimeElapsedCallback(8f, PlayerPracticeObjectAttractFX);
		localGameStateTimer.AddTimeElapsedCallback(45f, 60f, PlayWaitingForPlayersThreeFeedback);
		localGameStateTimer.AddTimeElapsedCallback(50f, 60f, PlayWaitingForPlayersFourFeedback);
		idsOfUnloadedPlayersWhoRequestedStart = new HashSet<long>();
		Profiles.OnProfileUpdated += OnProfileUpdatedInWaitingForPlayersSubState;
	}

	private void OnUpdateWaitingForPlayersSubState()
	{
		if (PhotonNetwork.isMasterClient && ReadyToPlay)
		{
			gameStateMachine.EnterState(1, 1);
		}
	}

	private void OnExitWaitingForPlayersSubState(ushort nextStateId, ushort nextSubStateId)
	{
		localGameStateTimer.ClearCallbacks();
		Profiles.OnProfileUpdated -= OnProfileUpdatedInWaitingForPlayersSubState;
		idsOfUnloadedPlayersWhoRequestedStart = null;
	}

	private void OnProfileUpdatedInWaitingForPlayersSubState(long id)
	{
		if (idsOfUnloadedPlayersWhoRequestedStart != null)
		{
			idsOfUnloadedPlayersWhoRequestedStart.Remove(id);
			MasterStartGame(id, StartGameDelay);
		}
	}

