	private void OnEnterGameRunningState(ushort previousStateId, ushort previousSubStateId)
	{
		if (SingletonMonoBehaviour<GiftManager>.Instance != null)
		{
			SingletonMonoBehaviour<GiftManager>.Instance.StopReceivingGifts();
		}
		localGameStateTimer.StartTimerWithoutMaxRunningTime();
		RecRoomSceneManager.Instance.EquipmentManager.EnablePracticeObjects(enabled: false);
		UpdateSceneEquipment(runToolReset: true);
		if (PhotonNetwork.isMasterClient)
		{
			GameTimerManager.MasterStartTimer();
			ScoreManager.MasterResetAllScores();
			GameSessions.SetGameInProgress(inProgress: true);
		}
		AudioManager.MusicMixer.PlayGameplayMusic();
		PlayerGameRoleManager.Instance.RequestAddRole(PhotonNetwork.player, GameRoleId.AG_IN_GAME);
		GameStart();
		if (Player.LocalPlayerExists)
		{
			bool flag = TeamManager.IsPlayerSpectator(PhotonNetwork.player);
			InitializeLocalPlayer(localPlayerIsSpectator: false, localPlayerIsJoiningInProgress: false);
			if (!flag && respawnsPlayersOnGameStart)
			{
				SpawnManager.LocalPlayerRequestRespawn();
			}
		}
		if (this.GameStartedEvent != null)
		{
			this.GameStartedEvent();
		}
	}

	private void OnExitGameRunningState(ushort nextStateId, ushort nextSubStateId)
	{
		localGameStateTimer.ClearCallbacks();
		PlayerGameRoleManager.Instance.RequestRemoveRole(PhotonNetwork.player, GameRoleId.AG_IN_GAME);
		GameEnd();
		AudioManager.MusicMixer.StopAllMusic();
		if (PhotonNetwork.isMasterClient)
		{
			GameTimerManager.Pause();
		}
		if (this.GameEndedEvent != null)
		{
			this.GameEndedEvent();
		}
	}

