		if (supportsGameOverGiftGeneration && !GameEndedPrematurely && SingletonMonoBehaviour<GiftManager>.Instance != null && !TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			GiftManager.GiftContext roomSceneLocationGiftContext = AGRoomSettings.GetRoomSceneLocationGiftContext(GameSessions.LocalGameSession.Location);
			SingletonMonoBehaviour<GiftManager>.Instance.GenerateGameGift(roomSceneLocationGiftContext);
		}
		if (PhotonNetwork.isMasterClient && SupportsLevelSwitching)
		{
			List<string> list = (from s in RecNet.Rooms.LocalRoomDetails.Scenes
				where s.CanMatchmakeInto
				select s.Name).ToList();
			int num = list.IndexOf(RecNet.Rooms.LocalRoomScene.Name);
			num = (num + 1) % list.Count;
			NextLevel = list[num];
		}
