	private void OnEnterGameOverSubState(ushort previousStateId, ushort previousSubStateId)
	{
		if (!hasCustomGameOverFeedback)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "GAME OVER!", 3f);
			AudioManager.Play2DSFX(DefaultAudioSettings.ConfigAsset.GameOverSFX);
			RecRoomAudioClip clip = ((!CurrentMode.AudioSettings.HasCustomGameOverVO) ? DefaultAudioSettings.ConfigAsset.GameOverVO : CurrentMode.AudioSettings.GameOverVO);
			AudioManager.Play2DSFX(clip);
			this.InvokeInUpdate(3f, PlayWinnerNotification);
		}
		else if (PhotonNetwork.isMasterClient)
		{
			masterGameStateTimer.StartTimer(3f);
		}
		bool flag = TeamManager.IsPlayerSpectator(PhotonNetwork.player);
		bool won = !flag && ScoreManager.GetPhotonPlayerWon(PhotonNetwork.player);
		if (!flag)
		{
			Player.LocalPlayer.PlayerEvents.GameOver(won, GetGameCompletionPercentage());
		}
		if (!SuppressGameOverChallengeEvent)
		{
			SendGameOverChallengeEvent(flag, won);
		}
	}

	public void SendGameOverChallengeEvent(bool isSpectator, bool won)
	{
		ChallengeEvents.GameEndedEventData endGameChallengeEventData = GetEndGameChallengeEventData(isSpectator, won);
		ChallengeEvents.LocalPlayerGameEnded(endGameChallengeEventData);
	}

