		{
			SpawnManager.LocalPlayerRequestRespawn(!flag, supportsGameOverGiftDequeing && !flag);
		}
		else if (supportsGameOverGiftDequeing)
		{
			SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(Avatars.GiftPackages, useSpawnLocation: false, dismissExistingGift: false);
		}
	}

