	protected float GetGameCompletionPercentage()
	{
		float result = 1f;
		if (GameTimerManager.Duration > 0f)
		{
			float num = ((!JoinedInProgressAt.HasValue) ? 0f : JoinedInProgressAt.Value);
			float num2 = ((!GameEndedPrematurely) ? 0f : (GameTimerManager.Duration - GameTimerManager.TimeElapsed));
			float num3 = Mathf.Max(0.001f, (!GameEndedPrematurely) ? GameTimerManager.TimeElapsed : GameTimerManager.Duration);
			float num4 = num2 + num;
			result = 1f - Mathf.Clamp(num4 / num3, 0f, 1f);
		}
		return result;
	}

	private void PlayWinnerNotification()
	{
		if (CustomWinnerNotification != null)
		{
			CustomWinnerNotification();
			return;
		}
		ScoreManager.GetHighestScore(out var highestScoreTeam, out var _);
		string empty = string.Empty;
		RecRoomAudioClip recRoomAudioClip = null;
		if (highestScoreTeam == GameTeam.ANY)
		{
			empty = "Tie Game";
			recRoomAudioClip = DefaultAudioSettings.ConfigAsset.GameTieVO;
		}
		else
		{
			empty = TeamManager.GetTeamName(highestScoreTeam) + " Wins!";
			recRoomAudioClip = ((highestScoreTeam != GameTeam.TEAM_1) ? ((!CurrentMode.AudioSettings.HasCustomTeamWinVO) ? DefaultAudioSettings.ConfigAsset.RedTeamWinVO : CurrentMode.AudioSettings.RedTeamWinVO) : ((!CurrentMode.AudioSettings.HasCustomTeamWinVO) ? DefaultAudioSettings.ConfigAsset.BlueTeamWinVO : CurrentMode.AudioSettings.BlueTeamWinVO));
		}
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, empty, 3f);
		AudioManager.Play2DSFX(recRoomAudioClip);
	}

