	public void MasterCleanupAllSpawnedEquipment(bool cleanupHeldTools = false, bool cleanupEquippedTools = false)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		List<SpawnableTool> list = new List<SpawnableTool>();
		for (int i = 0; i < SpawnedEquipment.Count; i++)
		{
			if (SpawnedEquipment[i] != null)
			{
				bool flag = true;
				if (SpawnedEquipment[i].Tool.IsHeld && !cleanupHeldTools)
				{
					flag = false;
				}
				else if (SpawnedEquipment[i].Tool.IsEquippedOnPlayer && !cleanupEquippedTools)
				{
					flag = false;
				}
				if (flag)
				{
					list.Add(SpawnedEquipment[i]);
				}
			}
		}
		for (int j = 0; j < list.Count; j++)
		{
			list[j].Tool.MasterDisableAndMoveToLastSpawnPosition();
		}
		list = null;
	}

