	private void MasterStartGame(long recNetProfileId, float gameStartDelay, bool startOver = false)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		bool flag;
		if (CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME)
		{
			flag = true;
		}
		else if (CurrentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS && allowDevsAndCommunityTeamToStartWhileWaitingForPlayers)
		{
			Profile profile = Profiles.Get(recNetProfileId);
			if (profile != null)
			{
				flag = profile.Developer;
			}
			else
			{
				if (idsOfUnloadedPlayersWhoRequestedStart != null)
				{
					idsOfUnloadedPlayersWhoRequestedStart.Add(recNetProfileId);
				}
				flag = false;
			}
		}
		else
		{
			flag = false;
		}
		if (flag)
		{
			CanContinue = !startOver;
			GameStartDelay = gameStartDelay;
			gameStateMachine.EnterState(1, 2);
		}
	}

