	protected virtual void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (CanVoteNextLevel)
		{
			GetPlayerData(newPlayer);
		}
	}

	protected virtual void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (!player.IsRecNetBot && (!IsGameRunning || supportsGameLeaveNotificationsDuringGameplay))
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, player.NickName + " left the game", 3f);
		}
		for (int i = 0; i < gameComponentManagers.Count; i++)
		{
			gameComponentManagers[i].OnPlayerDisconnected(player);
		}
		MasterUpdateGameStateOnPlayerChange(player);
	}

	protected virtual void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		TryAssignTeamPlayerOnMasterSwitch();
		TryRespawnPlayerOnMasterSwitch();
		MasterUpdateGameStateOnPlayerChange(null);
	}

	private void TryAssignTeamPlayerOnMasterSwitch()
	{
		if (IsPreGameOrInitializing && !SupportsSpectating && TeamManager.IsPlayerSpectator(PhotonNetwork.player))
		{
			TeamManager.RequestNextTeam(PhotonNetwork.player);
		}
	}

	private void TryRespawnPlayerOnMasterSwitch()
	{
		if (IsGameRunning && !TeamManager.IsPlayerSpectator(PhotonNetwork.player) && Player.LocalPlayerExists && Player.LocalPlayer.IsSpawning)
		{
			SpawnManager.LocalPlayerRequestRespawn(dropTools: false);
		}
	}

	protected virtual void MasterUpdateGameStateOnPlayerChange(PhotonPlayer leavingPlayer)
	{
		if (PhotonNetwork.isMasterClient)
		{
			bool flag = !ReadyToPlay && !supportsPlayersLeaving;
			if ((CurrentPreGameState == PreGameSubStates.GAME_LOADING || CurrentPreGameState == PreGameSubStates.GAME_ON) && leavingPlayer != null && !TeamManager.IsPlayerSpectator(leavingPlayer) && flag)
			{
				gameStateMachine.EnterState(1, 0);
			}
			else if (CurrentState == GameStates.GAME_RUNNING && flag)
			{
				MasterStopGame(gameEndedPrematurely: true);
			}
			GameSessions.SetGameInProgress(IsGameInProgress);
		}
	}

	public void DeserializeFrom(PersistedRoomData roomData)
	{
		RoomPersistenceVersion version = (RoomPersistenceVersion)roomData.Version;
		if (version < RoomPersistenceVersion.RADIO_PERSISTENCE || (GameSessions.LocalGameSession.IsSandbox && version < RoomPersistenceVersion.ROOM_ROLES))
		{
			return;
		}
		if (roomData.GameSettings == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing GameManager {0}: Data not specified.", base.gameObject);
			return;
		}
		GameModeType modeType = (GameModeType)roomData.GameSettings.ModeType;
		if (GetMode(modeType) != null)
		{
			CurrentGameModeType = modeType;
		}
		if (!GameSessions.LocalGameSession.IsSandbox)
		{
			ScoreManager.ScoreToWin = roomData.GameSettings.ScoreToWin;
			GameTimerManager.Duration = roomData.GameSettings.Duration;
			SpawnManager.FieldEquipmentEnabled = roomData.GameSettings.FieldEquipmentEnabled;
			if (roomData.GameSettings.DominantHandSpawnToolPrefabId != null)
			{
				SpawnManager.DominantHandSpawnEquipment = SpawnableToolSettings.GetSpawnableToolType(RecRoom.Protobuf.ByteStringExtensions.ToGuid(roomData.GameSettings.DominantHandSpawnToolPrefabId));
			}
			if (roomData.GameSettings.OffHandSpawnToolPrefabId != null)
			{
				SpawnManager.OffHandSpawnEquipment = SpawnableToolSettings.GetSpawnableToolType(RecRoom.Protobuf.ByteStringExtensions.ToGuid(roomData.GameSettings.OffHandSpawnToolPrefabId));
			}
		}
	}

	public void SerializeTo(ref PersistedRoomData roomData)
	{
		if (roomData.GameSettings != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing GameManager {0}: Data already specified.", base.gameObject);
			return;
		}
		roomData.GameSettings = new GameSettingsData();
		roomData.GameSettings.ModeType = (int)CurrentGameModeType;
		if (GameSessions.LocalGameSession.IsSandbox)
		{
			return;
		}
		roomData.GameSettings.ScoreToWin = ScoreManager.ScoreToWin;
		roomData.GameSettings.Duration = GameTimerManager.Duration;
		roomData.GameSettings.FieldEquipmentEnabled = SpawnManager.FieldEquipmentEnabled;
		SpawnableToolType dominantHandSpawnEquipment = SpawnManager.DominantHandSpawnEquipment;
		if (dominantHandSpawnEquipment != SpawnableToolType.INVALID)
		{
			Guid spawnableToolPrefabId = SpawnableToolSettings.GetSpawnableToolPrefabId(dominantHandSpawnEquipment);
			if (spawnableToolPrefabId != Guid.Empty)
			{
				roomData.GameSettings.DominantHandSpawnToolPrefabId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(spawnableToolPrefabId);
			}
		}
		SpawnableToolType offHandSpawnEquipment = SpawnManager.OffHandSpawnEquipment;
		if (offHandSpawnEquipment != SpawnableToolType.INVALID)
		{
			Guid spawnableToolPrefabId2 = SpawnableToolSettings.GetSpawnableToolPrefabId(offHandSpawnEquipment);
			if (spawnableToolPrefabId2 != Guid.Empty)
			{
				roomData.GameSettings.OffHandSpawnToolPrefabId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(spawnableToolPrefabId2);
			}
		}
	}

	private void OnGameIDChanged()
	{
		if (!string.IsNullOrEmpty(GameID))
		{
			AnalyticsHelper.GameStart(GameID);
		}
	}
