namespace RecRoom.Core.GameManagement
{
	public class GamePowerupManager : IGameComponent
	{
		private GameManager gameManager;

		private readonly List<Powerup> activePowerups = new List<Powerup>();

		public void OnAwake(GameManager gameManager)
		{
			this.gameManager = gameManager;
			Powerup.PowerupInstantiatedEvent += OnPowerupInitialized;
			Powerup.PowerupEffectsStartedEvent += OnPowerupEffectsStarted;
			Powerup.PowerupDestroyedEvent += OnPowerupDestroyed;
			Powerup.PowerupActivationRequestedEvent += OnPowerupActivationRequested;
			gameManager.CombatManager.PlayerHealthChangeEvent += OnPlayerHealthChanged;
		}

		public void OnDestroy()
		{
			gameManager.CombatManager.PlayerHealthChangeEvent -= OnPlayerHealthChanged;
			Powerup.PowerupInstantiatedEvent -= OnPowerupInitialized;
			Powerup.PowerupEffectsStartedEvent -= OnPowerupEffectsStarted;
			Powerup.PowerupDestroyedEvent -= OnPowerupDestroyed;
			Powerup.PowerupActivationRequestedEvent -= OnPowerupActivationRequested;
		}

		public void OnGameStart()
		{
		}

		public void OnGameEnd()
		{
		}

		public void InitializeLocalPlayer(bool localPlayerIsSpectator)
		{
			RemoveAllActivePowerupsForPlayer(PhotonNetwork.player);
		}

		public void ResetLocalPlayer(bool localPlayerIsSpectator)
		{
		}

		public void OnPlayerDisconnected(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient)
			{
				RemoveAllActivePowerupsForPlayer(player);
			}
		}

		public void OnStart()
		{
		}

		public void OnUpdate()
		{
		}

		private void OnPowerupInitialized(Powerup powerup)
		{
			activePowerups.Add(powerup);
			if (powerup.TargetPlayer.IsLocal)
			{
				FadeInTonemapping(powerup);
			}
		}

		private void OnPowerupDestroyed(Powerup powerup)
		{
			AudioManager.MusicMixer.RemovePowerupMusic(powerup);
			activePowerups.Remove(powerup);
			int num = 0;
			for (int i = 0; i < activePowerups.Count; i++)
			{
				if (activePowerups[i] != null && activePowerups[i].TargetPlayer.IsLocal)
				{
					num++;
				}
			}
			if (num == 0)
			{
				AudioManager.MusicMixer.StopPowerupMusic();
			}
			if (powerup.TargetPlayer.IsLocal && !PlayerHasActivePowerup(powerup.TargetPlayer))
			{
				FadeOutTonemapping(powerup.TonemappingFadeTime);
			}
		}

		private void OnPowerupEffectsStarted(Powerup powerup)
		{
			if (powerup.TargetPlayer.IsLocal && powerup.MusicClip != null && powerup.MusicClip.audioClip != null)
			{
				AudioManager.MusicMixer.AddPowerupMusic(powerup.MusicClip, powerup);
				AudioManager.MusicMixer.PlayPowerupMusic();
			}
		}

		private void OnPowerupActivationRequested(PowerupType powerupType, PhotonPlayer player)
		{
			gameManager.photonView.RpcMaster(gameManager.RpcMasterActivatePowerup, powerupType, player);
		}

		private void OnPlayerHealthChanged(PhotonPlayer player)
		{
			if (!gameManager.CombatManager.PlayerIsAlive(player))
			{
				RemoveAllActivePowerupsForPlayer(player);
			}
		}

		public void MasterActivatePowerup(PowerupType powerupType, PhotonPlayer player)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			Powerup activeMatchingPowerup = GetActiveMatchingPowerup(powerupType, player);
			if (activeMatchingPowerup != null)
			{
				activeMatchingPowerup.MasterRestartTimer();
				return;
			}
			Powerup powerup = Powerup.MasterSpawnPowerup(powerupType, player, gameManager.photonView.viewID, null);
			if (powerup.GrantsInvincibility)
			{
				gameManager.CombatManager.MasterRequestPlayerInvincibility(player, powerup.InvincibilityDuration);
			}
		}

		private void FadeInTonemapping(Powerup powerup)
		{
			UnityEngine.Debug.LogWarning("Tonemapping in Powerups is disabled for now, if we want this back we should fade in a different PostProcessingProfile");
		}

		private void FadeOutTonemapping(float duration)
		{
		}

		private bool PlayerHasActivePowerup(PhotonPlayer player)
		{
			for (int i = 0; i < activePowerups.Count; i++)
			{
				if (activePowerups[i].TargetPlayer == player)
				{
					return true;
				}
			}
			return false;
		}

		private Powerup GetActiveMatchingPowerup(PowerupType powerupType, PhotonPlayer player)
		{
			for (int i = 0; i < activePowerups.Count; i++)
			{
				if (activePowerups[i].TargetPlayer == player && activePowerups[i].Type == powerupType)
				{
					return activePowerups[i];
				}
			}
			return null;
		}

		private void RemoveAllActivePowerupsForPlayer(PhotonPlayer player)
		{
			int num = 0;
			while (num < activePowerups.Count)
			{
				if (activePowerups[num].TargetPlayer == player)
				{
					if (activePowerups[num].hasAuthority)
					{
						PhotonNetwork.Destroy(activePowerups[num].photonView);
					}
					activePowerups.RemoveAt(num);
				}
				else
				{
					num++;
				}
			}
		}
	}
}
