[Serializable]
public class GamePresenceManager : IGameComponent
{
	private string _currentPresenceString = string.Empty;

	private string _customTimerTimer;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_PresenceChangeEvent;

	public string CurrentPresenceString
	{
		get
		{
			return _currentPresenceString;
		}
		set
		{
			_currentPresenceString = value;
			if (this.PresenceChangeEvent != null)
			{
				this.PresenceChangeEvent();
			}
		}
	}

	public string CustomTimerString
	{
		get
		{
			return _customTimerTimer;
		}
		set
		{
			_customTimerTimer = value;
			if (this.PresenceChangeEvent != null)
			{
				this.PresenceChangeEvent();
			}
		}
	}

	public event Action PresenceChangeEvent
	{
		add
		{
			Action action = this.m_PresenceChangeEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PresenceChangeEvent, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_PresenceChangeEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PresenceChangeEvent, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public void OnAwake(GameManager gameManager)
	{
	}

	public void OnStart()
	{
	}

	public void OnDestroy()
	{
	}

	public void OnUpdate()
	{
	}

	public void OnGameStart()
	{
	}

	public void OnGameEnd()
	{
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.CustomRichPresenceString)
			{
				Player.LocalPlayer.PushRichPresence(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.RichPresenceString);
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.CustomLocalPlayerStatus)
			{
				Player.LocalPlayer.PushLocalPlayerStatus(NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.LocalPlayerStatus);
			}
		}
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		if (!localPlayerIsSpectator)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.CustomRichPresenceString)
			{
				Player.LocalPlayer.PopRichPresence();
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GamePresenceSettings.CustomLocalPlayerStatus)
			{
				Player.LocalPlayer.PopLocalPlayerStatus();
			}
		}
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
	}
}
public class GameReviveHandshakeFeedback : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private PooledParticle particlesPrefab;

	[SerializeField]
	private RecRoomAudioClip loopingAudioClip;

	[SerializeField]
	private float almostFinishedTimeRemaining = 1f;

	[SerializeField]
	private RecRoomAudioClip almostFinishAudioClip;

	private PlayerHand revivingHand;

	private PlayerHand revivedHand;

	private Coroutine runningCoroutine;

	private PooledParticle loopingParticles;

	private SFXAudioSource loopingAudio;

	private SFXAudioSource almostFinishedAudio;

	public PhotonPlayer RevivingPlayer { get; private set; }

	private void OnDestroy()
	{
		StopFeedback();
		DetachHands();
	}

	public void StartRunning(PhotonPlayer revivingPlayer, PlayerHand revivingHand, PlayerHand revivedHand, float duration)
	{
		StartRunningCoroutine(revivingPlayer, revivedHand, revivingHand, duration);
	}

	public void Release()
	{
		StopRunningCoroutine();
		StopFeedback();
		DetachHands();
		RevivingPlayer = null;
		ObjectPool.Instance.Release(this);
	}

	private void StartRunningCoroutine(PhotonPlayer revivingPlayer, PlayerHand revivingHand, PlayerHand revivedHand, float duration)
	{
		StopRunningCoroutine();
		runningCoroutine = StartCoroutine(RunningCoroutine(revivingPlayer, revivingHand, revivedHand, duration));
	}

	private void StopRunningCoroutine()
	{
		if (runningCoroutine != null)
		{
			StopCoroutine(runningCoroutine);
			runningCoroutine = null;
		}
	}

	private void StartLoopingFeedback(Vector3 point, float duration)
	{
		StopFeedback();
		loopingAudio = AudioManager.StartLooping3DSFX(loopingAudioClip, point);
		loopingParticles = ObjectPool.Instance.Acquire(particlesPrefab);
		if (loopingParticles != null)
		{
			loopingParticles.SetDuration(duration, setStartLifetime: true);
			loopingParticles.Play(point, Quaternion.identity);
		}
	}

	private void StopFeedback()
	{
		if (loopingParticles != null)
		{
			loopingParticles.Stop();
			loopingParticles = null;
		}
		if (loopingAudio != null)
		{
			loopingAudio.Stop();
			loopingAudio = null;
		}
		if (almostFinishedAudio != null)
		{
			almostFinishedAudio.Stop();
			almostFinishedAudio = null;
		}
	}

	private IEnumerator RunningCoroutine(PhotonPlayer revivingPlayer, PlayerHand revivingHand, PlayerHand revivedHand, float duration)
	{
		RevivingPlayer = revivingPlayer;
		this.revivingHand = revivingHand;
		this.revivedHand = revivedHand;
		AttachHands();
		StartLoopingFeedback(GetFeedbackPosition(), duration);
		float timeUntilAlmostReady = Mathf.Max(0f, duration - almostFinishedTimeRemaining);
		float endTime = UnityEngine.Time.time + timeUntilAlmostReady;
		while (UnityEngine.Time.time < endTime)
		{
			yield return null;
			UpdateLoopingParticlePosition();
		}
		almostFinishedAudio = AudioManager.Play3DSFX(almostFinishAudioClip, GetFeedbackPosition());
		endTime = UnityEngine.Time.time + almostFinishedTimeRemaining;
		while (UnityEngine.Time.time < endTime)
		{
			yield return null;
			UpdateLoopingParticlePosition();
		}
		Release();
	}

	private void AttachHands()
	{
		PlayerHand.ConnectHandshake(revivingHand, revivedHand);
	}

	private void DetachHands()
	{
		PlayerHand.BreakHandshake(revivingHand, revivedHand);
		revivingHand = null;
		revivedHand = null;
	}

	private void UpdateLoopingParticlePosition()
	{
		Vector3 feedbackPosition = GetFeedbackPosition();
		if (loopingParticles != null)
		{
			loopingParticles.transform.position = feedbackPosition;
		}
	}

	private Vector3 GetFeedbackPosition()
	{
		if (revivedHand != null)
		{
			return revivedHand.transform.position;
		}
		if (revivingHand != null)
		{
			return revivingHand.transform.position;
		}
		if (RevivingPlayer != null)
		{
			Player player = RevivingPlayer.ToPlayer();
			if (player != null)
			{
				return player.Head.transform.position;
			}
		}
		return Vector3.zero;
	}
}
namespace RecRoom
{
	public abstract class GameRuleManager : NetworkedSingletonMonoBehaviour<GameRuleManager>
	{
		public const int GAME_RULE_MANAGER_PRIORITY = 500;

		[Header("Player HUD")]
		[SerializeField]
		protected LocalPlayerCombatHUD hudPrefab;

		[Header("Roles")]
		[SerializeField]
		private OverridableGameRole customInGameRole = new OverridableGameRole
		{
			Value = new GameRole(GameRoleId.AG_IN_GAME, null, "In-Game"),
			Overrides = false
		};

		[SerializeField]
		private GameRoleSettings customExtraGameRoleSettings;

		public LocalPlayerCombatHUD HudPrefab => hudPrefab;

		public virtual GameRoleSettings CustomExtraGameRoleSettings => customExtraGameRoleSettings;

		public bool Started { get; private set; }

		public abstract string RuleTypeAutoTag { get; }

		protected override void Awake()
		{
			base.Awake();
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.transform.parent != null)
			{
				base.transform.SetParent(NetworkedSingletonMonoBehaviour<GameManager>.Instance.transform.parent, worldPositionStays: false);
			}
			if (customInGameRole.Overrides)
			{
				PlayerGameRoleManager.Instance.AddInGameRoleDefinition(customInGameRole.Value, this, RoleMapPriority.SceneManager);
			}
		}

		protected virtual void Start()
		{
			Started = true;
			PlayerGameRoleManager.Instance.UpdatePredefinedRoles(CustomExtraGameRoleSettings.PredefinedGameRoles);
		}

		public virtual void RecordMatchAnalytics(bool finishedGame)
		{
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (PlayerGameRoleManager.Instance != null)
			{
				PlayerGameRoleManager.Instance.RemoveInGameRoleDefition(this);
				PlayerGameRoleManager.Instance.UpdatePredefinedRoles();
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				RecordMatchAnalytics(finishedGame: false);
			}
		}
	}
}
