[Serializable]
public class GameScoreManager : ScoreManager, IGameComponent
{
	public enum ScoreRank
	{
		Invalid = -1,
		S,
		A,
		B,
		C,
		SS
	}

	private const string DEFAULT_STAT_NAME = "Invalid Stat";

	private GameManager gameManager;

	private ObscuredSynchronizedField<int> _scoreToWin;

	private SynchronizedField<GameTeam> _explicitWinner;

	private Dictionary<int, SynchronizedField<int[], float[]>> playerStats = new Dictionary<int, SynchronizedField<int[], float[]>>();

	public string ScoreToWinAndUnitsString
	{
		get
		{
			string scoreName = gameManager.CurrentMode.ScoreSettings.ScoreName;
			int scoreToWin = gameManager.ScoreManager.ScoreToWin;
			string text = $"{scoreToWin.ToString()} {scoreName}";
			if (scoreToWin > 1)
			{
				text += "s";
			}
			return text;
		}
	}

	public int CurrentModeDefaultScoreToWin => GetModeDefaultScoreToWin(gameManager.CurrentMode);

	public int ScoreToWin
	{
		get
		{
			return _scoreToWin.Get();
		}
		set
		{
			_scoreToWin.Set(value);
		}
	}

	private GameTeam ExplicitWinner
	{
		get
		{
			return _explicitWinner.Get();
		}
		set
		{
			_explicitWinner.Set(value);
		}
	}

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		int num = 0;
		foreach (int value in System.Enum.GetValues(typeof(GameTeam)))
		{
			num = Mathf.Max(num, value);
		}
		_explicitWinner = new SynchronizedField<GameTeam>(gameManager, "ExplicitWinner", GameTeam.ANY, SetterPermissionMode.MASTER, FireStatsChangeEvent);
		_teamScores = new SynchronizedField<int[], int[]>(gameManager, "TeamScores", new int[num + 1], new int[num + 1], SetterPermissionMode.MASTER, FireStatsChangeEvent);
		_scoreToWin = new ObscuredSynchronizedField<int>(gameManager, "ScoreToWin", GetModeDefaultScoreToWin(gameManager.DefaultMode), SetterPermissionMode.MASTER, OnScoreToWinChanged);
	}

	public void OnStart()
	{
	}

	public void OnDestroy()
	{
	}

	public void OnUpdate()
	{
	}

	public void OnPlayerDisconnected(PhotonPlayer player)
	{
		FireStatsChangeEvent();
	}

	public void OnGameStart()
	{
	}

	public void OnGameEnd()
	{
	}

	public void InitializeLocalPlayer(bool localPlayerIsSpectator)
	{
		ResetAllLocalPlayerStats();
	}

	public void ResetLocalPlayer(bool localPlayerIsSpectator)
	{
	}

	public int GetScoreToWinOptionIndex(int scoreToWin)
	{
		ModeScoreToWinOption[] customScoreToWinOptions = gameManager.CurrentMode.ScoreSettings.CustomScoreToWinOptions;
		for (int i = 0; i < customScoreToWinOptions.Length; i++)
		{
			if (customScoreToWinOptions[i].ScoreToWin == scoreToWin)
			{
				return i;
			}
		}
		return -1;
	}

	public bool GetPhotonPlayerWon(PhotonPlayer player)
	{
		GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(player);
		GameTeam highestScoreTeam;
		int highestScore;
		return GetHighestScore(out highestScoreTeam, out highestScore) && (highestScoreTeam == GameTeam.ANY || highestScoreTeam == playerTeam);
	}

	public GameTeam GetWinningTeam()
	{
		GameTeam highestScoreTeam = GameTeam.ANY;
		GetHighestScore(out highestScoreTeam, out var _);
		return highestScoreTeam;
	}

	public bool TryGetAnyPlayerOnWinningTeam(out PhotonPlayer player)
	{
		if (!GetHighestScore(out var highestScoreTeam, out var _))
		{
			player = null;
			return false;
		}
		player = gameManager.TeamManager.GetAnyPlayerOnTeam(highestScoreTeam);
		return player != null;
	}

	public bool GetHighestScore(out GameTeam highestScoreTeam, out int highestScore, bool IncludeInactiveTeams = false)
	{
		bool result = false;
		highestScore = 0;
		highestScoreTeam = GameTeam.ANY;
		if (gameManager.CurrentMode.ScoreSettings.GameWinCondition == GameWinCondition.EVERYONE_WINS)
		{
			result = true;
			highestScoreTeam = gameManager.TeamManager.GetFirstActiveTeam();
		}
		else if (gameManager.CurrentMode.ScoreSettings.GameWinCondition == GameWinCondition.WINNER_EXPLICITY_SET)
		{
			GameTeam[] array = ((!IncludeInactiveTeams) ? gameManager.TeamManager.GetActiveTeams() : gameManager.TeamManager.GetAllTeams());
			for (int i = 0; i < array.Length; i++)
			{
				if (ExplicitWinner == array[i])
				{
					highestScoreTeam = array[i];
					result = true;
					break;
				}
			}
		}
		else
		{
			result = true;
			GameTeam[] array2 = ((!IncludeInactiveTeams) ? gameManager.TeamManager.GetActiveTeams() : gameManager.TeamManager.GetAllTeams());
			for (int j = 0; j < array2.Length; j++)
			{
				int score = GetScore(array2[j]);
				bool flag = (gameManager.CurrentMode.ScoreSettings.GameWinCondition == GameWinCondition.GREATEST_SCORE_WINS && score > highestScore) || (gameManager.CurrentMode.ScoreSettings.GameWinCondition == GameWinCondition.LOWEST_SCORE_WINS && score < highestScore);
				if (j == 0 || flag)
				{
					highestScore = score;
					highestScoreTeam = array2[j];
				}
				else if (score == highestScore)
				{
					highestScoreTeam = GameTeam.ANY;
				}
			}
		}
		return result;
	}

	public void AddScore(GameTeam team, int deltaScore)
	{
		gameManager.photonView.RpcMaster(gameManager.RpcMasterAddScore, team, deltaScore);
	}

	public override void MasterResetAllScores()
	{
		base.MasterResetAllScores();
		if (PhotonNetwork.isMasterClient)
		{
			ExplicitWinner = GameTeam.ANY;
		}
	}

	public void MasterArbitrarilySetWinningTeam(GameTeam team)
	{
		if (PhotonNetwork.isMasterClient)
		{
			ExplicitWinner = team;
		}
	}

	public void SetDefaultScoreToWin()
	{
		SetScoreToWin(CurrentModeDefaultScoreToWin);
	}

	private int GetModeDefaultScoreToWin(GameMode mode)
	{
		ModeScoreToWinOption[] customScoreToWinOptions = mode.ScoreSettings.CustomScoreToWinOptions;
		if (customScoreToWinOptions != null && customScoreToWinOptions.Length > 0)
		{
			int num = -1;
			for (int i = 0; i < customScoreToWinOptions.Length; i++)
			{
				if (customScoreToWinOptions[i].IsDefault)
				{
					num = i;
					break;
				}
			}
			return (num < 0) ? customScoreToWinOptions[0].ScoreToWin : customScoreToWinOptions[num].ScoreToWin;
		}
		return 0;
	}

	public void SetScoreToWin(int newScoreToWin)
	{
		gameManager.photonView.RpcMaster(gameManager.RpcMasterSetScoreToWin, newScoreToWin);
	}

	public void MasterSetScoreToWin(int newScoreToWin)
	{
		if (PhotonNetwork.isMasterClient)
		{
			ScoreToWin = newScoreToWin;
		}
	}

	private void OnScoreToWinChanged()
	{
		gameManager.CustomGameSettings.MarkSettingsChanged();
	}

	public bool HasRanks()
	{
		RankBucket[] rankBuckets = gameManager.CurrentMode.ScoreSettings.ranks.rankBuckets;
		return rankBuckets != null && rankBuckets.Length > 0 && rankBuckets[0].rank != ScoreRank.Invalid;
	}

	public ScoreRank GetTeamRank(GameTeam team)
	{
		ScoreRank result = ScoreRank.Invalid;
		RankBucket[] rankBuckets = gameManager.CurrentMode.ScoreSettings.ranks.rankBuckets;
		if (rankBuckets != null)
		{
			int score = GetScore(team);
			int num = -1;
			RankBucket[] array = rankBuckets;
			for (int i = 0; i < array.Length; i++)
			{
				RankBucket rankBucket = array[i];
				if (score >= rankBucket.minimumScore && rankBucket.minimumScore > num)
				{
					num = rankBucket.minimumScore;
					result = rankBucket.rank;
				}
			}
		}
		return result;
	}

	public GiftManager.GiftContext GetRankGiftContext(ScoreRank rank)
	{
		RankGiftContext[] rankGiftContexts = gameManager.CurrentMode.ScoreSettings.ranks.rankGiftContexts;
		if (rankGiftContexts != null)
		{
			RankGiftContext[] array = rankGiftContexts;
			for (int i = 0; i < array.Length; i++)
			{
				RankGiftContext rankGiftContext = array[i];
				if (rankGiftContext.rank == rank)
				{
					return rankGiftContext.giftContext;
				}
			}
		}
		return GiftManager.GiftContext.Default;
	}

	public GiftManager.GiftContext GetAlternateGiftContext()
	{
		return gameManager.CurrentMode.ScoreSettings.alternateGiftContext;
	}

	public GiftManager.GiftContext GetRankGiftContext(GameTeam team)
	{
		return GetRankGiftContext(GetTeamRank(team));
	}

	private SynchronizedField<int[], float[]> GetPlayerStatField(PhotonPlayer player)
	{
		if (!playerStats.TryGetValue(player.ID, out var value))
		{
			value = new SynchronizedField<int[], float[]>(player, "STATS", new int[0], new float[0], SetterPermissionMode.ANYONE, FireStatsChangeEvent);
			playerStats[player.ID] = value;
		}
		int num = gameManager.CurrentMode.ScoreSettings.Stats.Length;
		if (value.Get1().Length != num || value.Get2().Length != num)
		{
			value.Set(new int[num], new float[num]);
		}
		return value;
	}

	public bool TryGetPlayerStat(PhotonPlayer player, PlayerStatType stat, out int value, out float statLastChangeTime)
	{
		int statIndex = GetStatIndex(stat);
		if (statIndex >= 0 && statIndex < gameManager.CurrentMode.ScoreSettings.Stats.Length)
		{
			SynchronizedField<int[], float[]> playerStatField = GetPlayerStatField(player);
			int[] array = playerStatField.Get1();
			float[] array2 = playerStatField.Get2();
			value = array[statIndex];
			statLastChangeTime = array2[statIndex];
			return true;
		}
		value = 0;
		statLastChangeTime = 0f;
		return false;
	}

	public bool TryGetPlayerStat(PhotonPlayer player, PlayerStatType stat, out int value)
	{
		int statIndex = GetStatIndex(stat);
		if (statIndex >= 0 && statIndex < gameManager.CurrentMode.ScoreSettings.Stats.Length)
		{
			int[] array = GetPlayerStatField(player).Get1();
			value = array[statIndex];
			return true;
		}
		value = 0;
		return false;
	}

	public bool TryGetPlayerStatLastChangeTime(PhotonPlayer player, PlayerStatType stat, out float lastChangeTime)
	{
		int statIndex = GetStatIndex(stat);
		if (statIndex >= 0 && statIndex < gameManager.CurrentMode.ScoreSettings.Stats.Length)
		{
			float[] array = GetPlayerStatField(player).Get2();
			lastChangeTime = array[statIndex];
			return true;
		}
		lastChangeTime = 0f;
		return false;
	}

	public void MasterAddPlayerStatForAllActivePlayers(PlayerStatType stat, int deltaValue)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		foreach (PhotonPlayer activePlayer in gameManager.TeamManager.GetActivePlayers())
		{
			MasterAddPlayerStat(activePlayer, stat, deltaValue, canGoNegative: false);
		}
	}

	public void AddPlayerStat(PhotonPlayer player, PlayerStatType stat, int deltaValue)
	{
		gameManager.photonView.RpcMaster(gameManager.RpcMasterAddPlayerStat, player, stat, deltaValue);
	}

	public void SetPlayerStat(PhotonPlayer player, PlayerStatType stat, int value)
	{
		int value2 = 0;
		TryGetPlayerStat(player, stat, out value2);
		AddPlayerStat(player, stat, value - value2);
	}

	public void ClearPlayerStat(PhotonPlayer player, PlayerStatType stat)
	{
		if (TryGetPlayerStat(player, stat, out var value) && value != 0)
		{
			AddPlayerStat(player, stat, -value);
		}
	}

	public void MasterAddPlayerStat(PhotonPlayer player, PlayerStatType stat, int deltaValue, bool canGoNegative = true)
	{
		if (PhotonNetwork.isMasterClient && TryGetPlayerStat(player, stat, out var value))
		{
			value += deltaValue;
			if (!canGoNegative && value < 0)
			{
				value = 0;
			}
			MasterSetPlayerStat(player, stat, value);
		}
	}

	public void MasterSetPlayerStat(PhotonPlayer player, PlayerStatType stat, int value)
	{
		int statIndex = GetStatIndex(stat);
		if (PhotonNetwork.isMasterClient && statIndex >= 0 && statIndex < gameManager.CurrentMode.ScoreSettings.Stats.Length)
		{
			SynchronizedField<int[], float[]> playerStatField = GetPlayerStatField(player);
			int[] array = (int[])playerStatField.Get1().Clone();
			array[statIndex] = value;
			float[] array2 = (float[])playerStatField.Get2().Clone();
			array2[statIndex] = (float)PhotonNetwork.time;
			playerStatField.Set(array, array2);
		}
	}

	public void ResetAllLocalPlayerStats()
	{
		int num = gameManager.CurrentMode.ScoreSettings.Stats.Length;
		GetPlayerStatField(PhotonNetwork.player).Set(new int[num], new float[num]);
	}

	private int GetStatIndex(PlayerStatType statType)
	{
		int result = -1;
		for (int i = 0; i < gameManager.CurrentMode.ScoreSettings.Stats.Length; i++)
		{
			if (gameManager.CurrentMode.ScoreSettings.Stats[i].StatType == statType)
			{
				result = i;
				break;
			}
		}
		return result;
	}
}
