	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		Tool.StaticToolInstantiatedEvent += OnToolInstantiated;
		int defaultValue = -1;
		int defaultValue2 = -1;
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings != null)
		{
			defaultValue = (int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.DominantHandTool;
			defaultValue2 = (int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DefaultEquipmentSpawnSettings.OffHandTool;
		}
		_dominantHandSpawnEquipment = new ObscuredSynchronizedField<int>(gameManager, "DH_EQUP", defaultValue, SetterPermissionMode.MASTER, OnSpawnEquipmentChanged);
		_offHandSpawnEquipment = new ObscuredSynchronizedField<int>(gameManager, "OH_EQUP", defaultValue2, SetterPermissionMode.MASTER, OnSpawnEquipmentChanged);
		_fieldEquipmentEnabled = new SynchronizedField<bool>(gameManager, "FE_EQUP", DefaultFieldEquipmentEnabled, SetterPermissionMode.MASTER, OnFieldEquipmentChanged);
		ResetEquipmentSpawnParametersToDefault();
	}

	public void OnStart()
	{
		GameSpawnPoint[] array = UnityEngine.Object.FindObjectsOfType<GameSpawnPoint>();
		for (int i = 0; i < array.Length; i++)
		{
			if (array[i].SupportsGameState(SupportedGameState.PRE_POST_GAME))
			{
				prePostGameSpawnPoints.Add(array[i]);
			}
			if (array[i].SupportsGameState(SupportedGameState.PLAYING_GAME))
			{
				playingGameSpawnPoints.Add(array[i]);
			}
		}
		GiftBoxSpawnPoint[] array2 = UnityEngine.Object.FindObjectsOfType<GiftBoxSpawnPoint>();
		if (array2 != null)
		{
			giftBoxSpawnPoints.AddRange(array2);
		}
	}

