	public void LocalPlayerRequestInstantiateToolsOnRespawn(Tool leftHandTool, Tool rightHandTool, Tool leftHipTool, Tool rightHipTool, Tool shoulderTool, bool suppressCleanupOnSpawnedTools)
	{
		GetToolEquipmentAndSkinId(leftHandTool, ref leftHandRequestedSpawnParameters);
		GetToolWeaponAmmoValues(leftHandTool, ref leftHandRequestedSpawnParameters);
		GetToolEquipmentAndSkinId(rightHandTool, ref rightHandRequestedSpawnParameters);
		GetToolWeaponAmmoValues(rightHandTool, ref rightHandRequestedSpawnParameters);
		GetToolEquipmentAndSkinId(leftHipTool, ref leftHipSlotRequestedSpawnParameters);
		GetToolWeaponAmmoValues(leftHipTool, ref leftHipSlotRequestedSpawnParameters);
		GetToolEquipmentAndSkinId(rightHipTool, ref rightHipSlotRequestedSpawnParameters);
		GetToolWeaponAmmoValues(rightHipTool, ref rightHipSlotRequestedSpawnParameters);
		GetToolEquipmentAndSkinId(shoulderTool, ref shoulderSlotRequestedSpawnParameters);
		GetToolWeaponAmmoValues(shoulderTool, ref shoulderSlotRequestedSpawnParameters);
		requestedSpawnEquipmentSuppressCleanup = suppressCleanupOnSpawnedTools;
	}

	private void GetToolEquipmentAndSkinId(Tool tool, ref RequestedEquipmentSpawnParameters spawnParams)
	{
		spawnParams.EquipmentType = SpawnableToolType.INVALID;
		spawnParams.EquipmentSkinId = null;
		if (!(tool != null))
		{
			return;
		}
		spawnParams.EquipmentType = tool.SpawnableToolType;
		if (tool.SkinMapper != null)
		{
			if (!string.IsNullOrEmpty(tool.SkinMapper.ActiveSkinGuid))
			{
				spawnParams.EquipmentSkinId = tool.SkinMapper.ActiveSkinGuid;
			}
			else
			{
				spawnParams.EquipmentSkinId = tool.SkinMapper.OriginalSkinGuid;
			}
		}
	}

	private void GetToolWeaponAmmoValues(Tool tool, ref RequestedEquipmentSpawnParameters spawnParams)
	{
		spawnParams.WeaponMagazineAmmo = 0;
		spawnParams.WeaponReserveAmmo = 0;
		if (tool != null)
		{
			Weapon component = tool.gameObject.GetComponent<Weapon>();
			if (component != null)
			{
				spawnParams.WeaponMagazineAmmo = component.MagazineAmmunition;
				spawnParams.WeaponReserveAmmo = component.ReserveAmmunition;
			}
		}
	}

	internal void LocalPlayerRequestRespawnAtPoint(SandboxCircuitSpawnPoint sandboxCircuitSpawnPoint, bool dropTools = true, bool requestGiftSpawn = false)
	{
		bool arg = Player.LocalPlayer.DominantHand.Type == PlayerHand.HandType.Left;
		gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestPlayerRespawnAtPoint, PhotonNetwork.player.ID, sandboxCircuitSpawnPoint.photonView, dropTools, arg, leftHandRequestedSpawnParameters, rightHandRequestedSpawnParameters, leftHipSlotRequestedSpawnParameters, rightHipSlotRequestedSpawnParameters, shoulderSlotRequestedSpawnParameters, requestedSpawnEquipmentSuppressCleanup, requestGiftSpawn);
		ResetEquipmentSpawnParametersToDefault();
	}

	private Tool GetExistingToolByTag(PhotonPlayer player, string tag, bool takeFromOtherPlayers)
	{
		Tool tool = null;
		if (!string.IsNullOrEmpty(tag))
		{
			TaggedTool leastRecentlyUsedTool = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetLeastRecentlyUsedTool(tag);
			if (leastRecentlyUsedTool != null)
			{
				if (!leastRecentlyUsedTool.Tool.IsHeldByPlayer && !leastRecentlyUsedTool.Tool.IsEquippedOnPlayer)
				{
					tool = leastRecentlyUsedTool.Tool;
				}
				else if (leastRecentlyUsedTool.Tool.HolderPlayer == player.ToPlayer())
				{
					tool = leastRecentlyUsedTool.Tool;
				}
				else if (takeFromOtherPlayers)
				{
					tool = leastRecentlyUsedTool.Tool;
					tool.HolderInfo = ToolHolderInfo.NotHeld;
				}
			}
		}
		if (tool != null)
		{
			tool.photonView.TransferOwnership(player);
		}
		return tool;
	}

	public void LocalPlayerRequestRespawn(bool dropTools = true, bool requestGiftSpawn = false)
	{
		if (Player.LocalPlayer == null)
		{
			UnityEngine.Debug.LogError("Requesting respawn for non-existent Player!");
			return;
		}
		bool arg = Player.LocalPlayer.DominantHand.Type == PlayerHand.HandType.Left;
		gameManager.photonView.RpcMaster(gameManager.RpcMasterRequestPlayerRespawn, PhotonNetwork.player.ID, (int)GetLocalPlayerSpawnPointTag(), arg3: false, dropTools, arg, leftHandRequestedSpawnParameters, rightHandRequestedSpawnParameters, leftHipSlotRequestedSpawnParameters, rightHipSlotRequestedSpawnParameters, shoulderSlotRequestedSpawnParameters, requestedSpawnEquipmentSuppressCleanup, requestGiftSpawn);
		ResetEquipmentSpawnParametersToDefault();
	}

	public void MasterRespawnPlayerAtPoint(PhotonPlayer player, SpawnPoint spawnPoint, bool dropTools, bool leftHandIsDominant, RequestedEquipmentSpawnParameters requestedLeftHandEquipment, RequestedEquipmentSpawnParameters requestedRightHandEquipment, RequestedEquipmentSpawnParameters requestedLeftHipEquipment, RequestedEquipmentSpawnParameters requestedRightHipEquipment, RequestedEquipmentSpawnParameters requestedShoulderEquipment, bool requestedEquipmentSuppressCleanup, bool requestGiftSpawn)
	{
		if (!PhotonNetwork.isMasterClient || player == null)
		{
			return;
		}
		if (spawnPoint == null)
		{
			if (!GameManager.IsSandboxActive)
			{
				UnityEngine.Debug.LogError("Spawn Point is null.  Cannot spawn player " + player.NickName);
			}
			return;
		}
		spawnPoint.MasterUse();
		Vector3 localPosition;
		Quaternion localRotation;
		Transform firstAvailableSpawnTransform = spawnPoint.GetFirstAvailableSpawnTransform(out localPosition, out localRotation);
		Tool arg = null;
		Tool arg2 = null;
		Tool arg3 = null;
		SandboxCircuitSpawnPoint sandboxCircuitSpawnPoint = spawnPoint as SandboxCircuitSpawnPoint;
		Tool arg4;
		Tool arg5;
		if (sandboxCircuitSpawnPoint != null)
		{
			if (leftHandIsDominant)
			{
				arg4 = GetExistingToolByTag(player, sandboxCircuitSpawnPoint.PrimaryHandHeldTag, sandboxCircuitSpawnPoint.PrimaryHandTakeFromHolder);
				arg5 = GetExistingToolByTag(player, sandboxCircuitSpawnPoint.SecondaryHandHeldTag, sandboxCircuitSpawnPoint.SecondaryHandTakeFromHolder);
			}
			else
			{
				arg5 = GetExistingToolByTag(player, sandboxCircuitSpawnPoint.PrimaryHandHeldTag, sandboxCircuitSpawnPoint.PrimaryHandTakeFromHolder);
				arg4 = GetExistingToolByTag(player, sandboxCircuitSpawnPoint.SecondaryHandHeldTag, sandboxCircuitSpawnPoint.SecondaryHandTakeFromHolder);
			}
		}
		else
		{
			arg4 = MasterGetPlayerSpawnTool(player, leftHandIsDominant, requestedLeftHandEquipment.EquipmentType, requestedLeftHandEquipment.WeaponMagazineAmmo, requestedLeftHandEquipment.WeaponReserveAmmo, requestedEquipmentSuppressCleanup, firstAvailableSpawnTransform.transform);
			arg5 = MasterGetPlayerSpawnTool(player, !leftHandIsDominant, requestedRightHandEquipment.EquipmentType, requestedRightHandEquipment.WeaponMagazineAmmo, requestedRightHandEquipment.WeaponReserveAmmo, requestedEquipmentSuppressCleanup, firstAvailableSpawnTransform.transform);
			arg = MasterGetPlayerSpawnTool(player, isDominantHand: false, requestedLeftHipEquipment.EquipmentType, requestedLeftHipEquipment.WeaponMagazineAmmo, requestedLeftHipEquipment.WeaponReserveAmmo, requestedEquipmentSuppressCleanup, firstAvailableSpawnTransform.transform);
			arg2 = MasterGetPlayerSpawnTool(player, isDominantHand: false, requestedRightHipEquipment.EquipmentType, requestedRightHipEquipment.WeaponMagazineAmmo, requestedRightHipEquipment.WeaponReserveAmmo, requestedEquipmentSuppressCleanup, firstAvailableSpawnTransform.transform);
			arg3 = MasterGetPlayerSpawnTool(player, isDominantHand: false, requestedShoulderEquipment.EquipmentType, requestedShoulderEquipment.WeaponMagazineAmmo, requestedShoulderEquipment.WeaponReserveAmmo, requestedEquipmentSuppressCleanup, firstAvailableSpawnTransform.transform);
		}
		gameManager.photonView.RpcPlayer(player, gameManager.RpcRespawnPlayer, localPosition, localRotation, spawnPoint.Parent, dropTools, arg4, requestedLeftHandEquipment.EquipmentSkinId, arg5, requestedRightHandEquipment.EquipmentSkinId, arg, requestedLeftHipEquipment.EquipmentSkinId, arg2, requestedRightHipEquipment.EquipmentSkinId, arg3, requestedShoulderEquipment.EquipmentSkinId, requestGiftSpawn);
		if (GameSpawnManager.MasterOnlyPlayerRespawnEvent != null)
		{
			GameSpawnManager.MasterOnlyPlayerRespawnEvent(player);
		}
	}

