	private Tool MasterGetPlayerSpawnTool(PhotonPlayer player, bool isDominantHand, SpawnableToolType requestedEquipmentType, int requestedMagazineAmmo, int requestedReserveAmmo, bool requestedEquipmentSuppressCleanup, Transform spawnPoint)
	{
		Tool tool = null;
		if (requestedEquipmentType != SpawnableToolType.INVALID)
		{
			tool = MasterGetEquipmentSpawnTool(player, requestedEquipmentType, spawnPoint.position, spawnPoint.rotation, 1f, requestedEquipmentSuppressCleanup);
		}
		else if (!GameManager.IsSandboxActive)
		{
			tool = MasterGetEquipmentSpawnTool(player, (!isDominantHand) ? OffHandSpawnEquipment : DominantHandSpawnEquipment, spawnPoint.position, spawnPoint.rotation, 1f, suppressCleanup: false);
		}
		if (tool != null && (requestedReserveAmmo >= 0 || requestedMagazineAmmo >= 0))
		{
			Weapon component = tool.GetComponent<Weapon>();
			if (component != null)
			{
				int magazineAmmunition = Mathf.Max(0, requestedMagazineAmmo);
				int reserveAmmunition = Mathf.Max(0, requestedReserveAmmo);
				component.ForceAmmunitionValuesOnSpawn(magazineAmmunition, reserveAmmunition);
			}
		}
		return tool;
	}

	public GiftBoxSpawnPoint GetGiftBoxSpawnPoint(PhotonPlayer player)
	{
