		{
			GameTeamPlayerIndex teamPlayerIndex = gameManager.TeamManager.GetTeamPlayerIndex(player);
			FilterGiftBoxSpawnPoints(giftBoxSpawnPoints, teamPlayerIndex, filteredGiftBoxSpawnPoints);
			if (filteredGiftBoxSpawnPoints.Count > 0)
			{
				filteredGiftBoxSpawnPoints.Sort(GiftBoxSpawnPoint.Comparer);
				result = filteredGiftBoxSpawnPoints[0];
