		{
			if (!(allSpawnPoints[i] == null) && allSpawnPoints[i].SpawnPointEnabled && allSpawnPoints[i].SupportedTeamPlayerIndex == requiredPlayerIndex)
			{
				filteredSpawnPointsOut.Add(allSpawnPoints[i]);
			}
		}
	}

