	private Dictionary<string, object> GetEquipmentInstantiationParameters(int tag, bool suppressAnimateInParticles, bool spawnIgnoringDynamicPhysics, bool suppressCleanup, bool suppressSkins)
	{
		Dictionary<string, object> dictionary = null;
		if (tag >= 0 || suppressAnimateInParticles || spawnIgnoringDynamicPhysics || suppressCleanup || suppressSkins)
		{
			dictionary = new Dictionary<string, object>();
		}
		if (tag >= 0)
		{
			dictionary.Add(TAG_INSTANTIATION_ID, tag);
		}
		if (suppressCleanup)
		{
			dictionary.Add(SUPPRESS_CLEANUP_TOOL_INSTANTIATION_ID, suppressCleanup);
		}
		if (suppressAnimateInParticles)
		{
			dictionary.Add(SUPPRESS_ANIMATE_IN_PARTICLES_TOOL_INSTANTIATION_ID, suppressAnimateInParticles);
		}
		if (spawnIgnoringDynamicPhysics)
		{
			dictionary.Add(IGNORE_DYNAMIC_COLLISIONS_TOOL_INSTANTIATION_ID, spawnIgnoringDynamicPhysics);
		}
		if (suppressSkins)
		{
			dictionary.Add(SUPPRESS_SKINS_TOOL_INSTANTIATION_ID, suppressSkins);
		}
		return dictionary;
	}

