		{
			bool suppressCleanup2 = suppressCleanup;
			result = MasterSpawnEquipment(equipmentType, spawnPosition, spawnRotation, spawnScale, -1, suppressAnimateInParticles: false, spawnIgnoringDynamicPhysics: false, suppressCleanup2);
		}
		return result;
	}

	private void OnToolInstantiated(Tool tool)
	{
		if (tool.InstantiatorPhotonViewId != gameManager.photonView.viewID)
		{
			return;
		}
		tool.EnabledChangeEvent += OnSpawnedToolEnabledChange;
		tool.PostResetEvent += OnSpawnedToolReset;
		tool.SleepOnCleanup = false;
		tool.SleepOnStart = false;
		object value = false;
		if (tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue(SUPPRESS_CLEANUP_TOOL_INSTANTIATION_ID, out value) && (bool)value)
		{
			tool.ToolCleanup.PauseCleanup(this);
		}
		else
		{
			tool.ToolCleanup.MinDisplacementBeforeCleanup = -1f;
		}
		object value2 = false;
		if (tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue(SUPPRESS_ANIMATE_IN_PARTICLES_TOOL_INSTANTIATION_ID, out value2) && (bool)value2)
		{
			tool.SupportsAnimateIn = false;
		}
		object value3 = false;
		if (tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue(IGNORE_DYNAMIC_COLLISIONS_TOOL_INSTANTIATION_ID, out value3) && (bool)value3)
		{
			tool.DefaultCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			tool.SetCollisionLayer(tool.DefaultCollisionLayer);
			foreach (Tool childTool in tool.ChildTools)
			{
				childTool.DefaultCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
				childTool.SetCollisionLayer(tool.DefaultCollisionLayer);
			}
			if (tool.RigidbodyEx != null)
			{
				tool.RigidbodyEx.SleepChangedEvent += OnToolSleepChange;
			}
			tool.PrePickupEvent += OnToolPrePickup;
		}
		object value4 = false;
		if (tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue(SUPPRESS_SKINS_TOOL_INSTANTIATION_ID, out value4) && (bool)value4 && tool.SkinMapper != null)
		{
			tool.SkinMapper.SuppressSkins = true;
		}
		SpawnableTool component = tool.GetComponent<SpawnableTool>();
		if (component != null)
		{
			if (component.Tool == null)
			{
				component.Tool = tool;
			}
			object value5 = -1;
			if (tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue(TAG_INSTANTIATION_ID, out value5) && (int)value5 >= 0)
			{
				component.InstantiationTag = (int)value5;
			}
			if (this.SpawnedEquipmentInstantiatedEvent != null)
			{
				this.SpawnedEquipmentInstantiatedEvent(component);
			}
		}
	}

	private void OnSpawnedToolEnabledChange(Tool tool)
	{
		if (!tool.IsEnabled)
		{
			TearDownSpawnedTool(tool);
		}
	}

	public void OnSpawnedToolReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		bool flag = false;
		foreach (SpawnableTool item in gameManager.CurrentMode.GameEquipmentSettings.ToolTypesToNotDestroyWhenReset)
		{
			if (item != null && item.Type == tool.SpawnableToolType)
			{
				flag = true;
				break;
			}
		}
		if (!flag)
		{
			TearDownSpawnedTool(tool);
		}
	}

	private void TearDownSpawnedTool(Tool tool)
	{
		tool.EnabledChangeEvent -= OnSpawnedToolEnabledChange;
		tool.PostResetEvent -= OnSpawnedToolReset;
		SpawnableTool spawnableTool = ((!(tool != null)) ? null : tool.GetComponent<SpawnableTool>());
		if (spawnableTool != null && this.SpawnedEquipmentDestroyedEvent != null)
		{
			this.SpawnedEquipmentDestroyedEvent(spawnableTool);
		}
		if (PhotonNetwork.isMasterClient)
		{
			if (!tool.hasAuthority)
			{
				tool.photonView.TransferOwnership(PhotonNetwork.player);
			}
			PhotonNetwork.Destroy(tool.gameObject);
		}
	}

