	protected virtual void PopulateModeSpecificGameData(PhotonPlayer player, out GameModeType currentMode, out GameTeam playerTeam, out GameTeamPlayerIndex playerTeamPlayerIndex, out bool isSpectator)
	{
		currentMode = gameManager.CurrentMode.ModeType;
		playerTeam = gameManager.TeamManager.GetPlayerTeam(player);
		playerTeamPlayerIndex = gameManager.TeamManager.GetTeamPlayerIndex(player);
		isSpectator = gameManager.TeamManager.IsPlayerSpectator(player);
	}

	protected SpawnPoint MasterGetSpawnPoint(PhotonPlayer player, SpawnPointTagType playerTag, bool ignoreDefaultTag)
	{
		List<GameSpawnPoint> list = (GameManager.IsSandboxActive ? sandboxGameSpawnPoints : ((!IsGameRunning) ? prePostGameSpawnPoints : playingGameSpawnPoints));
		if (list.Count == 0)
		{
			if (!GameManager.IsSandboxActive)
			{
				UnityEngine.Debug.LogError("Missing spawn points for " + gameManager.name + ((!IsGameRunning) ? " in pre/post game state" : " in playing game state"));
			}
			return null;
		}
		GameSpawnPoint result = ((!GameManager.IsSandboxActive) ? list[0] : null);
		PopulateModeSpecificGameData(player, out var currentMode, out var playerTeam, out var playerTeamPlayerIndex, out var isSpectator);
		FilterSpawnPointsRequired(list, playerTeam, playerTeamPlayerIndex, playerTag, ignoreDefaultTag, isSpectator, currentMode, spawnPointsRequirementFiltered);
		if (spawnPointsRequirementFiltered.Count == 0)
		{
			UnityEngine.Debug.Log("Filtered out all possible spawn points due to spawn point requirement tests.  Falling back to arbitrary spawn point.");
			return result;
		}
		List<GameSpawnPoint> list2 = null;
		FilterSpawnPointsOverlap(spawnPointsRequirementFiltered, spawnPointsOverlapFiltered);
		if (spawnPointsOverlapFiltered.Count > 0)
		{
			list2 = spawnPointsOverlapFiltered;
		}
		else
		{
			UnityEngine.Debug.Log("Filtered out all possible spawn points due to spawn point overlap test.  Falling back to overlapping spawn points.");
			list2 = spawnPointsRequirementFiltered;
		}
		SpawnPoint spawnPoint = null;
		return (IsGameRunning ? CurrentModeSpawnSettings.SpawnPointSelectionMethod : GameSpawnPointSelectionMethod.LEAST_RECENTLY_USED) switch
		{
			GameSpawnPointSelectionMethod.RANDOM_WITHOUT_OPPONENT_VISIBILITY => FindSpawnPointRandomWithoutEnemyVisibility(playerTeam, list2), 
			GameSpawnPointSelectionMethod.WEIGHTED_TEAM_PROXIMITY => FindSpawnPointWeightedTeamProximity(playerTeam, list2), 
			GameSpawnPointSelectionMethod.RANDOM => FindSpawnPointRandom(list2), 
			_ => FindSpawnPointLeastRecentlyUsed(list2), 
		};
	}

	protected void FilterSpawnPointsRequired(List<GameSpawnPoint> allSpawnPoints, GameTeam requiredTeam, GameTeamPlayerIndex requiredPlayerIndex, SpawnPointTagType requiredTag, bool ignoreDefaultTag, bool isSpectator, GameModeType requiredMode, List<GameSpawnPoint> filteredSpawnPointsOut)
	{
		filteredSpawnPointsOut.Clear();
		for (int i = 0; i < allSpawnPoints.Count; i++)
		{
			if (allSpawnPoints[i].SpawnPointEnabled && allSpawnPoints[i].SupportsGameMode(requiredMode) && (!isSpectator || allSpawnPoints[i].IsOnlyForSpectators) && (isSpectator || !allSpawnPoints[i].IsOnlyForSpectators) && (requiredTeam == GameTeam.ANY || allSpawnPoints[i].GameTeam == GameTeam.ANY || allSpawnPoints[i].GameTeam == requiredTeam) && (requiredPlayerIndex == GameTeamPlayerIndex.ANY_INDEX || allSpawnPoints[i].GameTeamPlayerIndex == GameTeamPlayerIndex.ANY_INDEX || allSpawnPoints[i].GameTeamPlayerIndex == requiredPlayerIndex) && (requiredTag == SpawnPointTagType.DEFAULT || (allSpawnPoints[i].CustomTag == SpawnPointTagType.DEFAULT && !ignoreDefaultTag) || allSpawnPoints[i].CustomTag == requiredTag))
			{
				filteredSpawnPointsOut.Add(allSpawnPoints[i]);
			}
		}
	}

	protected void FilterSpawnPointsOverlap(List<GameSpawnPoint> allSpawnPoints, List<GameSpawnPoint> filteredSpawnPointsOut)
	{
		filteredSpawnPointsOut.Clear();
		for (int i = 0; i < allSpawnPoints.Count; i++)
		{
			if (!allSpawnPoints[i].IsOnCooldown && !allSpawnPoints[i].IsBlockedByOverlaps)
			{
				filteredSpawnPointsOut.Add(allSpawnPoints[i]);
			}
		}
	}

	private SpawnPoint FindSpawnPointLeastRecentlyUsed(List<GameSpawnPoint> spawnPoints)
	{
		spawnPoints.Sort(GameSpawnPoint.Comparer);
		return spawnPoints[0];
