	private SpawnPoint FindSpawnPointWeightedTeamProximity(GameTeam spawningPlayerTeam, List<GameSpawnPoint> spawnPoints)
	{
		teammateProximitySpawnPointScores.Clear();
		PhotonPlayer[] teamPlayers = GetTeamPlayers(spawningPlayerTeam);
		List<Vector3> playerPositions = GetPlayerPositions(teamPlayers);
		PhotonPlayer[] otherPlayers = GetOtherPlayers(spawningPlayerTeam);
		List<Vector3> playerPositions2 = GetPlayerPositions(otherPlayers);
		bool flag = true;
		float? num = null;
		for (int i = 0; i < spawnPoints.Count; i++)
		{
			float spawnPointTeamProximityScore = GetSpawnPointTeamProximityScore(playerPositions, playerPositions2, spawnPoints[i]);
			teammateProximitySpawnPointScores.Add(new ScoredSpawnPoint
			{
				SpawnPoint = spawnPoints[i],
				Score = spawnPointTeamProximityScore
			});
			if (num.HasValue)
			{
				float num2 = num.Value - spawnPointTeamProximityScore;
				if (num2 != 0f)
				{
					flag = false;
				}
			}
			num = spawnPointTeamProximityScore;
		}
		int index;
		if (!flag)
		{
			teammateProximitySpawnPointScores.Sort((ScoredSpawnPoint a, ScoredSpawnPoint b) => b.Score.CompareTo(a.Score));
			index = 0;
		}
		else
		{
			UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
			index = UnityEngine.Random.Range(0, teammateProximitySpawnPointScores.Count);
		}
		return teammateProximitySpawnPointScores[index].SpawnPoint;
	}

	private float GetSpawnPointTeamProximityScore(List<Vector3> teammatePositions, List<Vector3> opponentPositions, GameSpawnPoint spawnPoint)
	{
		float spawnPointProximityScoreHelper = GetSpawnPointProximityScoreHelper(spawnPoint, teammatePositions, CurrentModeSpawnSettings.TeammateProximityScoreSettings);
		float spawnPointProximityScoreHelper2 = GetSpawnPointProximityScoreHelper(spawnPoint, opponentPositions, CurrentModeSpawnSettings.EnemyProximityScoreSettings);
		return spawnPointProximityScoreHelper + spawnPointProximityScoreHelper2;
	}

	private List<GameTeam> GetPlayerTeams(IEnumerable<PhotonPlayer> photonPlayers, bool mustHavePlayerAvatar = true)
	{
		List<GameTeam> list = new List<GameTeam>();
		foreach (PhotonPlayer photonPlayer in photonPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (!mustHavePlayerAvatar || player != null)
			{
				list.Add(gameManager.TeamManager.GetPlayerTeam(photonPlayer));
			}
		}
		return list;
	}

	private List<Vector3> GetPlayerPositions(IEnumerable<PhotonPlayer> photonPlayers)
	{
		List<Vector3> list = new List<Vector3>();
		foreach (PhotonPlayer photonPlayer in photonPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null)
			{
				list.Add(player.Head.transform.position);
			}
		}
		return list;
	}

	public float GetSpawnPointProximityScoreHelper(GameSpawnPoint spawnPoint, List<Vector3> playerPositions, ProximityScoreSettings scoreSettings)
	{
		float num = 0f;
		for (int i = 0; i < playerPositions.Count; i++)
		{
			float spawnPointProximityScoreForPosition = GetSpawnPointProximityScoreForPosition(spawnPoint, playerPositions[i], scoreSettings);
			num += spawnPointProximityScoreForPosition;
		}
		return num;
	}

	public float GetSpawnPointProximityScoreForPosition(GameSpawnPoint spawnPoint, Vector3 playerPosition, ProximityScoreSettings scoreSettings)
	{
		float magnitude = Vector3.ProjectOnPlane(playerPosition - spawnPoint.WorldPosition, Vector3.up).magnitude;
		if (scoreSettings.UseCurve && scoreSettings.DistanceScoreCurve != null)
		{
			return scoreSettings.DistanceScoreCurve.Evaluate(magnitude);
		}
		float t = Mathf.InverseLerp(scoreSettings.MinThreshold, scoreSettings.MaxThreshold, magnitude);
		return Mathf.Lerp(scoreSettings.MinScore, scoreSettings.MaxScore, t);
	}

	private SpawnPoint FindSpawnPointRandomWithoutEnemyVisibility(GameTeam spawningPlayerTeam, List<GameSpawnPoint> spawnPoints)
	{
		UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
		GameTeam[] otherTeams = gameManager.TeamManager.GetOtherTeams(spawningPlayerTeam);
		if (otherTeams == null || otherTeams.Length == 0)
		{
			return spawnPoints[UnityEngine.Random.Range(0, spawnPoints.Count)];
		}
		spawnPointFilteringScratchSpace.Clear();
		for (int i = 0; i < spawnPoints.Count; i++)
		{
			if (!spawnPoints[i].IsVisibleToTeamPlayers(otherTeams))
			{
				spawnPointFilteringScratchSpace.Add(spawnPoints[i]);
			}
		}
		if (spawnPointFilteringScratchSpace.Count == 0)
		{
			return spawnPoints[UnityEngine.Random.Range(0, spawnPoints.Count)];
		}
		return spawnPointFilteringScratchSpace[UnityEngine.Random.Range(0, spawnPointFilteringScratchSpace.Count)];
	}

	private void ResetPlayerVisibility()
	{
		currentVisTestGameplaySPIndex = 0;
		if (playingGameSpawnPoints != null && playingGameSpawnPoints.Count > 0)
		{
			for (int i = 0; i < playingGameSpawnPoints.Count; i++)
			{
				playingGameSpawnPoints[i].ClearTeamPlayerVisibility();
			}
		}
	}

	private void UpdatePlayerVisibility()
	{
		if (PhotonNetwork.isMasterClient && IsGameRunning && playingGameSpawnPoints != null && playingGameSpawnPoints.Count != 0)
		{
			int num = Mathf.Min(4, playingGameSpawnPoints.Count);
			IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
			List<GameTeam> playerTeams = GetPlayerTeams(activePlayers);
			List<Vector3> playerPositions = GetPlayerPositions(activePlayers);
			for (int i = 0; i < num; i++)
			{
				playingGameSpawnPoints[currentVisTestGameplaySPIndex].UpdateTeamPlayerVisibility(playerTeams, playerPositions);
				currentVisTestGameplaySPIndex = (currentVisTestGameplaySPIndex + 1) % playingGameSpawnPoints.Count;
			}
		}
	}
}
public class GameSpawnPoint : SpawnPoint
{
	public static SpawnPointComparer<GameSpawnPoint> Comparer = new SpawnPointComparer<GameSpawnPoint>();

	[SerializeField]
	protected SupportedGameState supportedState;

	[SerializeField]
	[Tooltip("Leave the supported game modes array empty to support all game modes.")]
	protected GameModeType[] supportedGameModes;

	private HashSet<GameTeam> visibleToTeams = new HashSet<GameTeam>();

	public bool IsOnlyForSpectators { get; protected set; }

	public GameTeam GameTeam { get; protected set; }

	public GameTeamPlayerIndex GameTeamPlayerIndex { get; protected set; }

	public SpawnPointTagType CustomTag { get; protected set; }

	public SupportedGameState SupportedGameState => supportedState;

	protected override Color GizmoColor => Color.red;

	public bool SupportsGameState(SupportedGameState state)
	{
		return supportedState == SupportedGameState.ALL_STATES || supportedState == state;
	}

	public bool SupportsGameMode(GameModeType mode)
	{
		return supportedGameModes == null || supportedGameModes.Length == 0 || supportedGameModes.Contains(mode);
	}

	public void ClearTeamPlayerVisibility()
	{
		visibleToTeams.Clear();
	}

	public void UpdateTeamPlayerVisibility(List<GameTeam> playerTeams, List<Vector3> playerPositions, float testPlayerHeight = 1.8f)
	{
		visibleToTeams.Clear();
		if (playerTeams == null || playerPositions == null || playerTeams.Count != playerPositions.Count)
		{
			return;
		}
		Vector3 vector = base.transform.position + Vector3.up * testPlayerHeight;
		for (int i = 0; i < playerPositions.Count; i++)
		{
			Vector3 vector2 = playerPositions[i];
			Vector3 vector3 = vector2 - vector;
			Vector3 normalized = vector3.normalized;
			float magnitude = vector3.magnitude;
			if (!Physics.Raycast(vector, normalized, magnitude, 2048, QueryTriggerInteraction.Ignore))
			{
				visibleToTeams.Add(playerTeams[i]);
			}
		}
	}

	public bool IsVisibleToTeamPlayers(GameTeam[] teams)
	{
		for (int i = 0; i < teams.Length; i++)
		{
			if (visibleToTeams.Contains(teams[i]))
			{
				return true;
			}
		}
		return false;
	}

	protected override void Awake()
	{
		base.Awake();
		IsOnlyForSpectators = false;
		GameTeam = GameTeam.ANY;
		GameTeamPlayerIndex = GameTeamPlayerIndex.ANY_INDEX;
		CustomTag = SpawnPointTagType.DEFAULT;
	}
}
public class GameSpectatorSpawnPoint : GameSpawnPoint
{
	protected override void Awake()
	{
		base.Awake();
		base.IsOnlyForSpectators = true;
	}
}
