	public bool GameStartTeamRequirementsMet
	{
		get
		{
			int activePlayerCount = GetActivePlayerCount();
			GameTeam[] activeTeams = GetActiveTeams();
			int currentTeamCount = ((activeTeams != null) ? activeTeams.Length : 0);
			int currentMinTeamSize = ((activeTeams != null) ? GetMinTeamSize(activeTeams) : 0);
			return GetTeamRequirementsMet(gameManager.CurrentMode.GameStartSettings.GameStartTeamRequirement, activePlayerCount, currentTeamCount, currentMinTeamSize);
		}
	}

	public bool GameAutomaticStartTeamRequirementsMet
	{
		get
		{
			int activePlayerCount = GetActivePlayerCount();
			GameTeam[] activeTeams = GetActiveTeams();
			int currentTeamCount = ((activeTeams != null) ? activeTeams.Length : 0);
			int currentMinTeamSize = ((activeTeams != null) ? GetMinTeamSize(activeTeams) : 0);
			return GetTeamRequirementsMet(gameManager.CurrentMode.GameStartSettings.GameAutomaticStartTeamRequirement, activePlayerCount, currentTeamCount, currentMinTeamSize);
		}
	}

