		beacons = new PlayerHighlightBeam[gameManager.MaximumSupportedPlayersInAnyNonSandboxMode];
		UnityEngine.Object original = Resources.Load("[PlayerHighlightBeam]");
		for (int i = 0; i < beacons.Length; i++)
		{
			GameObject gameObject2 = UnityEngine.Object.Instantiate(original) as GameObject;
			beacons[i] = gameObject2.GetComponent<PlayerHighlightBeam>();
			if (beacons[i] != null)
			{
				beacons[i].transform.SetParent(gameObject.transform);
			}
