		gameManager.StateChangeEvent += OnGameStateChanged;
		gameManager.DisabledEvent += OnGameManagerDisabled;
		if (gameManager.CombatManager != null)
		{
			gameManager.CombatManager.PlayerDownButNotOutChangeEvent += OnPlayerDownButNotOutChange;
		}
		base.TeamChangeEvent += UpdateCachedSquadDisableOpponentRadios;
		hasCustomLevelColorSettings = AGRoomSettings.TryGetRoomSceneLocationCustomTeamColors(GameSessions.LocalGameSession.Location, out customLevelColorSettings);
	}

