	private bool GameTeamRequirementsMetWithoutPlayer(PhotonPlayer player)
	{
		GameTeam playerTeam = GetPlayerTeam(player);
		if (playerTeam == GameTeam.ANY)
		{
			return GameStartTeamRequirementsMet;
		}
		int activePlayerCount = GetActivePlayerCount();
		GameTeam[] activeTeams = GetActiveTeams();
		int num = ((activeTeams != null) ? activeTeams.Length : 0);
		int num2 = ((activeTeams != null) ? GetMinTeamSize(activeTeams) : 0);
		int num3 = GetTeamPlayerCount(playerTeam) - 1;
		if (num3 == 0)
		{
			num--;
		}
		else if (num3 < num2)
		{
			num2 = num3;
		}
		return GetTeamRequirementsMet(gameManager.CurrentMode.GameStartSettings.GameStartTeamRequirement, activePlayerCount, num, num2);
	}

	private bool GetTeamRequirementsMet(GameStartTeamRequirement requirements, int currentPlayerCount, int currentTeamCount, int currentMinTeamSize)
	{
		GetRequiredTeamCountAndSize(requirements, out var requiredPlayerCount, out var requiredTeamCount, out var requiredTeamSize);
		return currentPlayerCount >= requiredPlayerCount && currentTeamCount >= requiredTeamCount && currentMinTeamSize >= requiredTeamSize;
	}

	public void GetRequiredTeamCountAndSize(GameStartTeamRequirement requirements, out int requiredPlayerCount, out int requiredTeamCount, out int requiredTeamSize)
	{
		switch (requirements)
		{
		default:
			requiredPlayerCount = int.MaxValue;
			requiredTeamCount = int.MaxValue;
			requiredTeamSize = int.MaxValue;
			break;
		case GameStartTeamRequirement.TWO_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 2;
			requiredTeamCount = 2;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.TWO_TEAMS_TWO_PLAYERS:
			requiredPlayerCount = 4;
			requiredTeamCount = 2;
			requiredTeamSize = 2;
			break;
		case GameStartTeamRequirement.TWO_TEAMS_THREE_PLAYERS:
			requiredPlayerCount = 6;
			requiredTeamCount = 2;
			requiredTeamSize = 3;
			break;
		case GameStartTeamRequirement.TWO_TEAMS_FOUR_PLAYERS:
			requiredPlayerCount = 8;
			requiredTeamCount = 2;
			requiredTeamSize = 4;
			break;
		case GameStartTeamRequirement.THREE_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 3;
			requiredTeamCount = 3;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.THREE_TEAMS_TWO_PLAYERS:
			requiredPlayerCount = 6;
			requiredTeamCount = 3;
			requiredTeamSize = 2;
			break;
		case GameStartTeamRequirement.FOUR_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 4;
			requiredTeamCount = 4;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.FOUR_TEAMS_TWO_PLAYERS:
			requiredPlayerCount = 8;
			requiredTeamCount = 4;
			requiredTeamSize = 2;
			break;
		case GameStartTeamRequirement.ONE_TEAM_ANY_PLAYERS:
			requiredPlayerCount = 1;
			requiredTeamCount = 1;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.ONE_TEAM_TWO_PLAYERS:
			requiredPlayerCount = 2;
			requiredTeamCount = 1;
			requiredTeamSize = 2;
			break;
		case GameStartTeamRequirement.FIVE_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 5;
			requiredTeamCount = 5;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.SIX_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 6;
			requiredTeamCount = 6;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.SEVEN_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 7;
			requiredTeamCount = 7;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.EIGHT_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 8;
			requiredTeamCount = 8;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.NO_REQUIREMENTS:
			requiredPlayerCount = int.MinValue;
			requiredTeamCount = int.MinValue;
			requiredTeamSize = int.MinValue;
			break;
		case GameStartTeamRequirement.FOURTEEN_TEAMS_ONE_PLAYER:
			requiredPlayerCount = 14;
			requiredTeamCount = 14;
			requiredTeamSize = 1;
			break;
		case GameStartTeamRequirement.SIX_TEAMS_THREE_PLAYERS_PER_TEAM:
			requiredPlayerCount = 18;
			requiredTeamCount = 6;
			requiredTeamSize = 3;
			break;
		case GameStartTeamRequirement.FOUR_PLAYERS_TWO_TEAMS_TWO_PLAYERS_PER_TEAM:
			requiredPlayerCount = 4;
			requiredTeamCount = 2;
			requiredTeamSize = 2;
			break;
		}
	}

