	public Color GetTeamColor(GameTeam team, bool useAlternateColor = false)
	{
		if (gameManager.CurrentMode.TeamSettings.UseHighContrastOpponentTeamColor)
		{
			bool isLocalPlayerTeam = GetPlayerTeam(PhotonNetwork.player) == team;
			return GameTeamSettings.GetHighContrastTeamColor(team, isLocalPlayerTeam);
		}
		if (hasCustomLevelColorSettings && customLevelColorSettings.TryGetTeamColor(team, out var color, useAlternateColor))
		{
			return color;
		}
		return GameTeamSettings.GetDefaultTeamColor(team);
	}

