	public override int GetTeamMaxPlayerCount(GameTeam team)
	{
		int result = 0;
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			if (gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team == team)
			{
				result = gameManager.CurrentMode.TeamSettings.TeamConfigs[i].MaxTeamSize;
				break;
			}
		}
		return result;
	}

	public override GameTeam[] GetAllTeams()
	{
		TeamManager.INSTANTANEOUS_TEAMS.Clear();
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			TeamManager.INSTANTANEOUS_TEAMS.Add(gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team);
		}
		return TeamManager.INSTANTANEOUS_TEAMS.ToArray();
	}

	public override int GetActivePlayersMaxCount()
	{
		int num = 0;
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			num += gameManager.CurrentMode.TeamSettings.TeamConfigs[i].MaxTeamSize;
		}
		return num;
	}

	public override bool PlayerCanSwitchTeam(PhotonPlayer player)
	{
		bool flag = false;
		GameTeam playerTeam = GetPlayerTeam(player);
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			if (gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team != playerTeam)
			{
				if (gameManager.CurrentState == GameStates.GAME_RUNNING && gameManager.CurrentMode.TeamSettings.SupportsGameRunningTeamChange && GetTeamPlayerCount(playerTeam) - GetTeamPlayerCount(GetAnotherTeam(playerTeam)) > 0)
				{
					flag = true;
					break;
				}
				if (gameManager.CurrentState != GameStates.GAME_RUNNING && GetTeamVacancy(gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team) > 0)
				{
					flag = true;
					break;
				}
			}
		}
		return flag & PlayerGameRoleManager.Instance.GetPlayerRoleDefinition(player).CanSwitchTeams.Value;
	}

	public override bool PlayerCanLeaveGame(PhotonPlayer player)
	{
		return !IsPlayerSpectator(player) && GameTeamRequirementsMetWithoutPlayer(player) && gameManager.SupportsSpectating;
	}

	public bool TryGetActivePlayerCentroid(out Vector3 centroid)
	{
		centroid = Vector3.zero;
		int num = 0;
		IEnumerable<PhotonPlayer> activePlayers = GetActivePlayers();
		foreach (PhotonPlayer item in activePlayers)
		{
			Player player = item.ToPlayer();
			if (player != null)
			{
				num++;
				centroid += player.CurrentFloorPosition;
			}
		}
		if (num > 0)
		{
			centroid /= (float)num;
			return true;
		}
		return false;
	}

	public override string GetTeamName(GameTeam team)
	{
		if (!gameManager.CurrentMode.TeamSettings.UseTeamNamesInFeedback)
		{
			PhotonPlayer[] teamPlayers = GetTeamPlayers(team);
			if (teamPlayers.Length > 0)
			{
				return teamPlayers[0].NickName;
			}
		}
		return base.GetTeamName(team);
	}

	private void OnGameStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateAllPlayerVisuals();
	}

	private void OnGameModeChanged()
	{
		if (PhotonNetwork.isMasterClient)
		{
			Dictionary<PhotonPlayer, GameTeam> dictionary = new Dictionary<PhotonPlayer, GameTeam>();
			PhotonPlayer[] playerList = PhotonNetwork.playerList;
			foreach (PhotonPlayer photonPlayer in playerList)
			{
				if (gameManager.CurrentMode.TeamSettings.PreserveTeamsWhenChangingToThisMode)
				{
					dictionary.Add(photonPlayer, GetPlayerTeam(photonPlayer));
				}
				else
				{
					dictionary.Add(photonPlayer, GameTeam.ANY);
				}
			}
			MasterClearTeams();
			PhotonPlayer[] playerList2 = PhotonNetwork.playerList;
			foreach (PhotonPlayer photonPlayer2 in playerList2)
			{
				GameTeam desiredTeam = dictionary[photonPlayer2];
				MasterAssignTeam(photonPlayer2, desiredTeam, GameTeam.ANY, preferPartiedTeam: true);
			}
		}
		UpdateAllPlayerVisuals();
	}

	private void OnGameManagerDisabled()
	{
		UpdateAllPlayerVisuals();
	}

	public void MasterAssignTeam(PhotonPlayer player, GameTeam desiredTeam, GameTeam forbiddenTeam, bool preferPartiedTeam, bool failover = true)
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		GameTeam gameTeam = GameTeam.ANY;
		if (desiredTeam != GameTeam.ANY && GetTeamVacancy(desiredTeam) > 0)
		{
			gameTeam = desiredTeam;
		}
		else if (failover)
		{
			gameTeam = AssignPlayerTeam(player, forbiddenTeam, preferPartiedTeam);
		}
		if (gameTeam == GameTeam.ANY)
		{
			if (failover)
			{
				UnityEngine.Debug.LogWarning("Unable to assign a team to " + ((player == null) ? "null player" : player.NickName));
			}
		}
		else
		{
			SetPlayerTeam(player, gameTeam);
		}
	}

	private GameTeam AssignPlayerTeam(PhotonPlayer player, GameTeam forbiddenTeam, bool preferPartiedTeam)
	{
		GameTeam gameTeam = GameTeam.ANY;
		Player player2 = player.ToPlayer();
		if (!(player2 != null) || !player2.PlayerParty.IsInParty || !preferPartiedTeam)
		{
			gameTeam = ((gameManager.CurrentMode.TeamSettings.TeamSelectionMethod != TeamSelectionMethod.LARGEST_TEAM_INDEX_ORDER) ? GetLeastOccupiedTeam(forbiddenTeam) : GetMostOccupiedTeam(forbiddenTeam));
		}
		else
		{
			gameTeam = GetPartyMemberTeam(player, player2.PlayerParty.CurrentPartyId);
			if (gameTeam == GameTeam.ANY)
			{
				gameTeam = GetLeastOccupiedTeam(forbiddenTeam);
			}
		}
		return gameTeam;
	}

	private GameTeam GetLeastOccupiedTeam(GameTeam forbiddenTeam = GameTeam.ANY)
	{
		if (GetActivePlayerVacancy() <= 0)
		{
			return GameTeam.ANY;
		}
		int num = -1;
		List<GameTeam> list = new List<GameTeam>();
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			if (GetTeamVacancy(gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team) == 0)
			{
				continue;
			}
			int teamPlayerCount = GetTeamPlayerCount(gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team);
			if ((forbiddenTeam == GameTeam.ANY || forbiddenTeam != gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team) && (num < 0 || teamPlayerCount <= num))
			{
				if (num < 0 || teamPlayerCount < num)
				{
					list.Clear();
					num = teamPlayerCount;
				}
				list.Add(gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team);
			}
		}
		if (list.Count == 0)
		{
			return GameTeam.ANY;
		}
		switch (gameManager.CurrentMode.TeamSettings.TeamSelectionMethod)
		{
		case TeamSelectionMethod.SMALLEST_TEAM_INDEX_ORDER:
		case TeamSelectionMethod.LARGEST_TEAM_INDEX_ORDER:
			list.Sort(delegate(GameTeam a, GameTeam b)
			{
				int num4 = (int)a;
				return num4.CompareTo((int)b);
			});
			if (forbiddenTeam != GameTeam.ANY)
			{
				for (int num3 = 0; num3 < list.Count; num3++)
				{
					if (list[num3] > forbiddenTeam)
					{
						return list[num3];
					}
				}
			}
			return list[0];
		case TeamSelectionMethod.SMALLEST_TEAM_LOWEST_SCORE:
		{
			int num2 = int.MaxValue;
			GameTeam result = GameTeam.ANY;
			for (int j = 0; j < list.Count; j++)
			{
				int score = gameManager.ScoreManager.GetScore(list[j]);
				if (score < num2)
				{
					result = list[j];
					num2 = score;
				}
			}
			return result;
		}
		default:
			return list[UnityEngine.Random.Range(0, list.Count)];
		}
	}

	private GameTeam GetMostOccupiedTeam(GameTeam forbiddenTeam = GameTeam.ANY)
	{
		GameTeam mostOccupiedTeamInternal = GetMostOccupiedTeamInternal(mustNotHavePartyPlayers: true, forbiddenTeam);
		if (mostOccupiedTeamInternal == GameTeam.ANY)
		{
			mostOccupiedTeamInternal = GetMostOccupiedTeamInternal(mustNotHavePartyPlayers: false, forbiddenTeam);
		}
		return mostOccupiedTeamInternal;
	}

	private GameTeam GetMostOccupiedTeamInternal(bool mustNotHavePartyPlayers, GameTeam forbiddenTeam)
	{
		int num = -1;
		GameTeam result = GameTeam.ANY;
		for (int i = 0; i < gameManager.CurrentMode.TeamSettings.TeamConfigs.Length; i++)
		{
			GameTeam team = gameManager.CurrentMode.TeamSettings.TeamConfigs[i].Team;
			if (team == forbiddenTeam || GetTeamVacancy(team) == 0)
			{
				continue;
			}
			int teamPlayerCount = GetTeamPlayerCount(team);
			if (mustNotHavePartyPlayers && teamPlayerCount > 0)
			{
				PhotonPlayer anyPlayerOnTeam = GetAnyPlayerOnTeam(team);
				Player player = anyPlayerOnTeam.ToPlayer();
				if (player == null || player.PlayerParty.IsInParty)
				{
					continue;
				}
			}
			if (teamPlayerCount > num)
			{
				num = teamPlayerCount;
				result = team;
			}
		}
		return result;
	}

	private void OnPlayerDownButNotOutChange(PhotonPlayer player)
	{
		if (gameManager.IsGameRunning && !gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player) && gameManager.CurrentMode.TeamSettings.SupportsTeammateBeacons && gameManager.CurrentMode.TeamSettings.TeammateBeaconsOnlyWhenDownButNotOut)
		{
			UpdateBeacons();
		}
	}

	private void UpdateBeacons()
	{
		if (!gameManager.IsGameRunning || gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player) || (!gameManager.CurrentMode.TeamSettings.SupportsTeammateBeacons && !gameManager.CurrentMode.TeamSettings.SupportsOpponentBeacons))
		{
			for (int i = 0; i < beacons.Length; i++)
			{
				if (beacons[i] != null)
				{
					beacons[i].gameObject.SetActive(value: false);
				}
			}
			return;
		}
		GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(PhotonNetwork.player);
		IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
		int j = 0;
		IEnumerator<PhotonPlayer> enumerator = activePlayers.GetEnumerator();
		while (enumerator.MoveNext() && j < beacons.Length)
		{
			PhotonPlayer current = enumerator.Current;
			GameTeam playerTeam2 = gameManager.TeamManager.GetPlayerTeam(current);
			bool flag = gameManager.CurrentMode.TeamSettings.SupportsOpponentBeacons && playerTeam2 != playerTeam;
			bool flag2 = gameManager.CurrentMode.TeamSettings.SupportsTeammateBeacons && playerTeam2 == playerTeam && (!gameManager.CurrentMode.TeamSettings.TeammateBeaconsOnlyWhenDownButNotOut || gameManager.CombatManager.IsPlayerDownButNotOut(current));
			if (beacons[j] != null)
			{
				if (current != PhotonNetwork.player && (flag || flag2))
				{
					beacons[j].gameObject.SetActive(value: true);
					beacons[j].Color = GetTeamColor(playerTeam2);
					beacons[j].Player = current.ToPlayer();
				}
				else
				{
					beacons[j].gameObject.SetActive(value: false);
				}
			}
			j++;
		}
		for (; j < beacons.Length; j++)
		{
			if (beacons[j] != null)
			{
				beacons[j].gameObject.SetActive(value: false);
			}
		}
	}

	private void UpdateCachedSquadDisableOpponentRadios(PhotonPlayer changingTeamPlayer = null, bool isDisconnecting = false)
	{
		if (!gameManager.CurrentMode.TeamSettings.UseTeamRadio)
		{
			return;
		}
		squadmates = GetTeammatesOfPlayer(PhotonNetwork.player);
		PhotonPlayer[] opponentsOfPlayer = GetOpponentsOfPlayer(PhotonNetwork.player);
		for (int i = 0; i < opponentsOfPlayer.Length; i++)
		{
			Player player = opponentsOfPlayer[i].ToPlayer();
			if (player != null)
			{
				player.PlayerAudio.SetRadioVoice(enableRadio: false);
			}
		}
	}

	private void UpdateLocalSquadCommunication()
	{
		if (Player.LocalPlayer == null)
		{
			return;
		}
		for (int i = 0; i < squadmates.Length; i++)
		{
			if (squadmates[i] == null)
			{
				UpdateCachedSquadDisableOpponentRadios();
				break;
			}
			Player player = squadmates[i].ToPlayer();
			if (player != null)
			{
				float num = Vector3.SqrMagnitude(player.Head.transform.position - Player.LocalPlayer.Head.transform.position);
				if (player.PlayerAudio.IsRadioVoiceEnabled && num <= gameManager.CurrentMode.TeamSettings.ExitRadioDistance * gameManager.CurrentMode.TeamSettings.ExitRadioDistance)
				{
					player.PlayerAudio.SetRadioVoice(enableRadio: false);
				}
				else if (!player.PlayerAudio.IsRadioVoiceEnabled && num >= gameManager.CurrentMode.TeamSettings.EnterRadioDistance * gameManager.CurrentMode.TeamSettings.EnterRadioDistance)
				{
					player.PlayerAudio.SetRadioVoice(enableRadio: true, gameManager.CurrentMode.TeamSettings.RadioVolume);
				}
			}
		}
	}

	private void UpdatePlayerTeamVisuals()
	{
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		PhotonPlayer[] array = playerList;
		foreach (PhotonPlayer photonPlayer in array)
		{
			Player player = photonPlayer.ToPlayer();
			if (!(player == null))
			{
				GameTeam playerTeam = GetPlayerTeam(photonPlayer);
				Color teamColor = GetTeamColor(playerTeam);
				ApplyPlayerTeamOutfit(player, playerTeam, teamColor);
				ApplyPlayerTeleportLaserVisuals(player, playerTeam, teamColor);
			}
		}
	}

	private void ApplyPlayerTeamOutfit(Player recRoomPlayer, GameTeam playerTeam, Color teamColor)
	{
		if (playerTeam == GameTeam.ANY || gameManager.IsDisabled || !gameManager.CurrentMode.TeamSettings.SupportsTeamOutfits || (gameManager.CurrentMode.TeamSettings.SupportsTeamOutfitsOnlyDuringGame && !gameManager.IsGameRunningOrLoading))
		{
			recRoomPlayer.PlayerOutfit.TeamOutfitColorEmissionEnabled = false;
			recRoomPlayer.PlayerOutfit.TeamOutfitColorEmissionAmount = 0f;
			recRoomPlayer.PlayerOutfit.TeamColor = null;
		}
		else
		{
			recRoomPlayer.PlayerOutfit.TeamOutfitColorEmissionEnabled = hasCustomLevelColorSettings && customLevelColorSettings.TeamOutfitColorEmissionEnabled;
			recRoomPlayer.PlayerOutfit.TeamOutfitColorEmissionAmount = ((!hasCustomLevelColorSettings) ? 0f : customLevelColorSettings.TeamOutfitColorEmissionAmount);
			recRoomPlayer.PlayerOutfit.TeamColor = teamColor;
		}
		if (playerTeam == GameTeam.ANY || gameManager.IsDisabled || !gameManager.CurrentMode.TeamSettings.SupportsPlayerNameTeamColor || (gameManager.CurrentMode.TeamSettings.SupportsPlayerNameTeamColorOnlyDuringGame && !gameManager.IsGameRunningOrLoading))
		{
			recRoomPlayer.PlayerUI.TeamColor = null;
		}
		else
		{
			recRoomPlayer.PlayerUI.TeamColor = teamColor;
		}
	}

	private void ApplyPlayerTeleportLaserVisuals(Player recRoomPlayer, GameTeam playerTeam, Color teamColor)
	{
		if (recRoomPlayer == null)
		{
			return;
		}
		bool flag = recRoomPlayer.LeftHand != null && recRoomPlayer.LeftHand.PlayerHandRemote != null;
		bool flag2 = recRoomPlayer.RightHand != null && recRoomPlayer.RightHand.PlayerHandRemote != null;
		if (playerTeam == GameTeam.ANY || gameManager.IsDisabled || !gameManager.CurrentMode.TeamSettings.SupportsPlayerTeleportLaserTeamColor)
		{
			if (flag)
			{
				recRoomPlayer.LeftHand.PlayerHandRemote.LaserColor = null;
			}
			if (flag2)
			{
				recRoomPlayer.RightHand.PlayerHandRemote.LaserColor = null;
			}
		}
		else
		{
			if (flag)
			{
				recRoomPlayer.LeftHand.PlayerHandRemote.LaserColor = teamColor;
			}
			if (flag2)
			{
				recRoomPlayer.RightHand.PlayerHandRemote.LaserColor = teamColor;
			}
		}
		bool decalCylinderVisible = playerTeam != GameTeam.ANY && !gameManager.IsDisabled && gameManager.CurrentMode.TeamSettings.SupportsPlayerTeleportDecalCylinder;
		if (flag)
		{
			recRoomPlayer.LeftHand.PlayerHandRemote.DecalCylinderVisible = decalCylinderVisible;
		}
		if (flag2)
		{
			recRoomPlayer.RightHand.PlayerHandRemote.DecalCylinderVisible = decalCylinderVisible;
		}
	}
}
public static class GameTeamSettings
{
	private struct TeamColor
	{
		public GameTeam Team;

		public Color Color;
	}

	private static GameTeamConfig ConfigAsset = CustomSettingsLoader.LoadConfig<GameTeamConfig>();

	private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

	private const string MissingTeamName = "MISSING_TEAM_NAME";

	private static readonly Color MissingTeamColor = Color.white;

	public static Color GetHighContrastTeamColor(GameTeam team, bool isLocalPlayerTeam)
	{
		if (ConfigAsset == null)
		{
			return MissingTeamColor;
		}
		if (isLocalPlayerTeam)
		{
			return ConfigAsset.HighContrastLocalPlayerTeamColor;
		}
		return ((int)team % 2 != 0) ? ConfigAsset.HighContrastOddOpponentTeamColor : ConfigAsset.HighContrastEvenOpponentTeamColor;
	}

	public static Color GetDefaultTeamColor(GameTeam team)
	{
		if (ConfigAsset != null)
		{
			if (team == GameTeam.ANY)
			{
				return ConfigAsset.AnyTeamConfig.Color;
			}
			int num = ConfigAsset.TeamConfigs.Length;
			int num2 = (int)team % num;
			return ConfigAsset.TeamConfigs[num2].Color;
		}
		return MissingTeamColor;
	}

	public static string GetTeamName(GameTeam team)
	{
		if (ConfigAsset != null)
		{
			if (team == GameTeam.ANY)
			{
				return ConfigAsset.AnyTeamConfig.Name;
			}
			if ((int)team < ConfigAsset.TeamConfigs.Length)
			{
				return ConfigAsset.TeamConfigs[(int)team].Name;
			}
		}
		return "MISSING_TEAM_NAME";
	}
}
