		remove
		{
			Action action = GameTimerManager.m_OnDurationChangedEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref GameTimerManager.m_OnDurationChangedEvent, (Action)Delegate.Remove(action2, value), action);
