	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		timer = new SynchronizedTimer(gameManager, "GAME", SetterPermissionMode.MASTER);
		timer.StartTimerEvent += OnStartTimer;
		NetworkedSingletonMonoBehaviour<GameManager>.Instance.ModeChangeEvent += UpdateSandboxTimerSettings;
		_duration = new ObscuredSynchronizedField<float>(gameManager, "DURATION", GetModeDefaultDuration(gameManager.DefaultMode), SetterPermissionMode.MASTER, OnDurationChanged);
