	private float GetModeDefaultDuration(GameMode mode)
	{
		ModeDurationOption[] durationOptions = mode.TimerSettings.DurationOptions;
		if (durationOptions != null && durationOptions.Length > 0)
		{
			int num = -1;
			for (int i = 0; i < durationOptions.Length; i++)
			{
				if (durationOptions[i].IsDefault)
				{
					num = i;
					break;
				}
			}
			return (num < 0) ? durationOptions[0].Duration : durationOptions[num].Duration;
		}
		return 0f;
