		gameManager.CustomGameSettings.MarkSettingsChanged();
		if (GameTimerManager.OnDurationChangedEvent != null)
		{
			GameTimerManager.OnDurationChangedEvent();
		}
	}

	public void MasterStartTimer()
	{
		if (timer == null)
		{
			UnityEngine.Debug.LogError("GameTimerManager has not been initialized.");
		}
		if (PhotonNetwork.isMasterClient)
		{
			if (gameManager.CurrentMode.TimerSettings.GameHasDuration)
			{
				timer.StartTimer(gameManager.GameTimerManager.Duration);
			}
			else
			{
				timer.StartTimerWithoutMaxRunningTime();
			}
		}
	}

	public void Pause()
	{
		if (PhotonNetwork.isMasterClient)
		{
			timer.Pause();
		}
	}

	public void Resume()
	{
		if (PhotonNetwork.isMasterClient)
		{
			timer.Resume();
