	public void OnUpdate()
	{
		if (timer != null)
		{
			timer.UpdateCallbacks();
		}
	}

	public void AddTimeElapsedCallback(float timeElapsed, Action callback)
	{
		gameManager.InvokeInUpdate(timeElapsed, callback);
