public class GameUIDataModel
{
	public string Name = string.Empty;

	public string PresenceString = string.Empty;

	public bool SupportsPreviousGameResults;

	public bool SupportsExplicitTeamJoining;

	public bool SupportsModeSwitching;

	public bool SupportsMapSwitching;

	public bool StaysInPostGameForever;

	public bool SupportsTimedMatches;

	public bool SupportsJoinInProgress;

	public bool CanContinue;

	public bool HasScore;

	public bool HasScoreToWin;

	public bool HasRank;

	public bool HasCustomRankName;

	public string RankName;

	public string WinCondition;

	public string ModeName;

	public string NextMapName;

	public int RequiredPlayerCount;

	public int RequiredTeamCount;

	public int RequiredTeamSize;

	public int ScoreboardPageSize;

	public int StatCount;

	public string[] StatNames;

	public bool[] HideStatsInUI;

	public int TeamCount;

	public GameUITeamDataModel[] TeamModels;

	public GameUILocalPlayerDataModel LocalPlayer;

	public bool SupportsTeamSwitching => RequiredTeamCount > 1;

	public bool UseTeamSwitchButton => SupportsTeamSwitching && !SupportsExplicitTeamJoining;

	public bool UseTeamJoinButton => SupportsTeamSwitching && SupportsExplicitTeamJoining;

	public static void DeepCopy(GameUIDataModel source, GameUIDataModel dest)
	{
		dest.Name = source.Name;
		dest.PresenceString = source.PresenceString;
		dest.SupportsPreviousGameResults = source.SupportsPreviousGameResults;
		dest.SupportsJoinInProgress = source.SupportsJoinInProgress;
		dest.SupportsModeSwitching = source.SupportsModeSwitching;
		dest.SupportsMapSwitching = source.SupportsMapSwitching;
		dest.StaysInPostGameForever = source.StaysInPostGameForever;
		dest.SupportsTimedMatches = source.SupportsTimedMatches;
		dest.CanContinue = source.CanContinue;
		dest.HasScore = source.HasScore;
		dest.HasScoreToWin = source.HasScoreToWin;
		dest.HasRank = source.HasRank;
		dest.HasCustomRankName = source.HasCustomRankName;
		dest.RankName = source.RankName;
		dest.ModeName = source.ModeName;
		dest.NextMapName = source.NextMapName;
		dest.RequiredPlayerCount = source.RequiredPlayerCount;
		dest.RequiredTeamCount = source.RequiredTeamCount;
		dest.RequiredTeamSize = source.RequiredTeamSize;
		dest.ScoreboardPageSize = source.ScoreboardPageSize;
		dest.StatCount = source.StatCount;
		if (dest.StatNames == null)
		{
			dest.StatNames = new string[source.StatNames.Length];
		}
		Array.Copy(source.StatNames, dest.StatNames, source.StatCount);
		if (dest.HideStatsInUI == null)
		{
			dest.HideStatsInUI = new bool[source.HideStatsInUI.Length];
		}
		Array.Copy(source.HideStatsInUI, dest.HideStatsInUI, source.StatCount);
		if (dest.TeamModels == null)
		{
			dest.TeamModels = new GameUITeamDataModel[source.TeamModels.Length];
			for (int i = 0; i < dest.TeamModels.Length; i++)
			{
				dest.TeamModels[i] = new GameUITeamDataModel();
			}
		}
		dest.TeamCount = source.TeamCount;
		for (int j = 0; j < source.TeamCount; j++)
		{
			GameUITeamDataModel.DeepCopy(source.TeamModels[j], dest.TeamModels[j]);
		}
		if (dest.LocalPlayer == null)
		{
			dest.LocalPlayer = new GameUILocalPlayerDataModel();
		}
		GameUILocalPlayerDataModel.DeepCopy(source.LocalPlayer, dest.LocalPlayer);
	}
}
public class GameUITeamDataModel
{
	public bool Active;

	public bool IsLocal;

	public Color Color = Color.white;

	public int Score;

	public string Rank = string.Empty;

	public GameTeam GameTeam;

	public GameUIPlayerDataModel[] PlayerModels;

	public static void DeepCopy(GameUITeamDataModel source, GameUITeamDataModel dest)
	{
		dest.Active = source.Active;
		dest.IsLocal = source.IsLocal;
		dest.Color = source.Color;
		dest.Score = source.Score;
		dest.Rank = source.Rank;
		dest.GameTeam = source.GameTeam;
		if (dest.PlayerModels == null || dest.PlayerModels.Length != source.PlayerModels.Length)
		{
			dest.PlayerModels = new GameUIPlayerDataModel[source.PlayerModels.Length];
			for (int i = 0; i < dest.PlayerModels.Length; i++)
			{
				dest.PlayerModels[i] = new GameUIPlayerDataModel();
			}
		}
		for (int j = 0; j < source.PlayerModels.Length; j++)
		{
			GameUIPlayerDataModel.DeepCopy(source.PlayerModels[j], dest.PlayerModels[j]);
		}
	}
}
public class GameUIPlayerDataModel
{
	public bool Active;

	public bool IsLocal;

	public string Name = string.Empty;

	public int StatCount;

	public int[] Stats;

	public static void DeepCopy(GameUIPlayerDataModel source, GameUIPlayerDataModel dest)
	{
		dest.Active = source.Active;
		dest.IsLocal = source.IsLocal;
		dest.Name = source.Name;
		if (dest.Stats == null)
		{
			dest.Stats = new int[source.Stats.Length];
		}
		dest.StatCount = source.StatCount;
		Array.Copy(source.Stats, dest.Stats, source.StatCount);
	}
}
public class GameUILocalPlayerDataModel
