public enum GameUIState
{
	PRE_GAME,
	WAITING_FOR_PLAYERS,
	GAME_STARTING,
	GAME_ON,
	GAME_RUNNING,
	GAME_OVER,
	RESULTS_LOCKED,
	RESULTS,
	LOADING_NEXT_LEVEL
}
public class GameUIManager : IGameComponent
{
	private GameManager gameManager;

	private List<GameUIView> gameUiViews = new List<GameUIView>();

	private GameUIState uiState;

	private GameUIDataModel currentDataModel;

	private GameUIDataModel previousDataModel;

	private GameUITimerDataModel currentTimerDataModel;

	private GameUITimerDataModel previousTimerDataModel;

	private bool gameDataIsDirty = true;

	private bool supportsPreviousGameResults;

	public void OnAwake(GameManager gameManager)
	{
		this.gameManager = gameManager;
		this.gameManager.ModeChangeEvent += OnDataDirtied;
		this.gameManager.NextLevelChangeEvent += OnDataDirtied;
		this.gameManager.TeamManager.TeamChangeEvent += OnTeamChange;
		this.gameManager.ScoreManager.StatsChangeEvent += OnDataDirtied;
		this.gameManager.PresenceManager.PresenceChangeEvent += OnDataDirtied;
		this.gameManager.StateChangeEvent += OnGameStateChange;
		this.gameManager.CustomGameSettings.SettingsChangedEvent += OnDataDirtied;
		Profiles.OnProfileUpdated += OnPlayerNameChange;
	}

	public void OnStart()
	{
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
		currentDataModel = CreateUIDataModel();
		previousDataModel = new GameUIDataModel();
		UpdateUIState();
		BroadcastGameUIDataModel();
		currentTimerDataModel = new GameUITimerDataModel();
		previousTimerDataModel = new GameUITimerDataModel();
		UpdateUITimerDataModel();
		BroadcastUITimerDataModel();
	}

	public void AddGameUIView(GameUIView uiView)
	{
		uiView.JoinLeaveGameButtonPressEvent += OnJoinLeaveGameButtonPressed;
		uiView.StartGameButtonPressEvent += OnStartGameButtonPressed;
		uiView.StartOverButtonPressEvent += OnStartOverButtonPressed;
		uiView.StartGameEarlyButtonPressEvent += OnStartGameEarlyButtonPressed;
		uiView.SwitchTeamButtonPressEvent += OnSwitchTeamButtonPressed;
		uiView.SwitchModeButtonPressEvent += OnSwitchModeButtonPressed;
		uiView.VoteNextMapButtonPressEvent += OnVoteNextMapButtonPressed;
		uiView.ViewResultsButtonPressEvent += OnViewResultsButtonPressed;
		uiView.JoinTeamButtonPressEvent += OnJoinTeamButtonPressed;
		gameUiViews.Add(uiView);
		GameUIDataModel dataModel = ((uiState != GameUIState.RESULTS && uiState != GameUIState.RESULTS_LOCKED) ? currentDataModel : previousDataModel);
		uiView.SetGameDataModel(uiState, dataModel);
	}

	public void RemoveGameUIView(GameUIView uiView)
	{
		uiView.JoinLeaveGameButtonPressEvent -= OnJoinLeaveGameButtonPressed;
		uiView.StartGameButtonPressEvent -= OnStartGameButtonPressed;
		uiView.StartOverButtonPressEvent -= OnStartOverButtonPressed;
		uiView.StartGameEarlyButtonPressEvent -= OnStartGameEarlyButtonPressed;
		uiView.SwitchTeamButtonPressEvent -= OnSwitchTeamButtonPressed;
		uiView.SwitchModeButtonPressEvent -= OnSwitchModeButtonPressed;
		uiView.VoteNextMapButtonPressEvent -= OnVoteNextMapButtonPressed;
		uiView.ViewResultsButtonPressEvent -= OnViewResultsButtonPressed;
		uiView.JoinTeamButtonPressEvent -= OnJoinTeamButtonPressed;
		gameUiViews.Remove(uiView);
	}

	public void OnUpdate()
	{
		int num = 0;
		while (num < gameUiViews.Count)
		{
			if (gameUiViews[num] == null)
			{
				gameUiViews.RemoveAt(num);
			}
			else
			{
				num++;
			}
		}
		UpdateUITimerDataModel();
		BroadcastUITimerDataModel();
		if (gameDataIsDirty)
		{
			UpdateCurrentGameModel();
			BroadcastGameUIDataModel();
			gameDataIsDirty = false;
		}
	}

	public void OnDestroy()
	{
		if (gameManager != null)
		{
			gameManager.ModeChangeEvent -= OnDataDirtied;
			gameManager.TeamManager.TeamChangeEvent -= OnTeamChange;
			gameManager.ScoreManager.StatsChangeEvent -= OnDataDirtied;
			gameManager.PresenceManager.PresenceChangeEvent -= OnDataDirtied;
			gameManager.StateChangeEvent -= OnGameStateChange;
			gameManager.CustomGameSettings.SettingsChangedEvent -= OnDataDirtied;
			Profiles.OnProfileUpdated -= OnPlayerNameChange;
		}
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
		if (gameUiViews == null)
		{
			return;
		}
		for (int i = 0; i < gameUiViews.Count; i++)
		{
			if (gameUiViews[i] != null)
			{
				gameUiViews[i].JoinLeaveGameButtonPressEvent -= OnJoinLeaveGameButtonPressed;
				gameUiViews[i].StartGameButtonPressEvent -= OnStartGameButtonPressed;
				gameUiViews[i].StartGameEarlyButtonPressEvent -= OnStartGameEarlyButtonPressed;
				gameUiViews[i].SwitchTeamButtonPressEvent -= OnSwitchTeamButtonPressed;
				gameUiViews[i].StartOverButtonPressEvent -= OnStartOverButtonPressed;
				gameUiViews[i].SwitchModeButtonPressEvent -= OnSwitchModeButtonPressed;
				gameUiViews[i].VoteNextMapButtonPressEvent -= OnVoteNextMapButtonPressed;
				gameUiViews[i].ViewResultsButtonPressEvent -= OnViewResultsButtonPressed;
				gameUiViews[i].JoinTeamButtonPressEvent -= OnJoinTeamButtonPressed;
			}
		}
	}

