		gameDataIsDirty = true;
	}

	private void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		gameDataIsDirty = true;
	}

	private void OnDataDirtied(bool value)
	{
		gameDataIsDirty = true;
	}

	private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RecRoom.Systems.PlayerRoles.RoomRole roleDef)
	{
		gameDataIsDirty = true;
	}

	private void OnDataDirtied()
	{
		gameDataIsDirty = true;
	}

	private void OnGameStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateUIState();
		gameDataIsDirty = true;
