	private void OnViewResultsButtonPressed()
	{
		if (gameManager.CurrentState == GameStates.PRE_GAME)
		{
			if (uiState == GameUIState.RESULTS && gameManager.CurrentPreGameState == PreGameSubStates.WAITING_FOR_PLAYERS)
			{
				uiState = GameUIState.WAITING_FOR_PLAYERS;
			}
			else if (uiState == GameUIState.RESULTS && gameManager.CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME)
			{
				uiState = GameUIState.PRE_GAME;
			}
			else if (uiState == GameUIState.PRE_GAME || uiState == GameUIState.WAITING_FOR_PLAYERS)
			{
				uiState = GameUIState.RESULTS;
			}
			gameDataIsDirty = true;
		}
	}

	private GameUIDataModel CreateUIDataModel()
	{
		GameUIDataModel gameUIDataModel = new GameUIDataModel();
		gameUIDataModel.Name = RecRoomSceneManager.CurrentSceneFriendlyName;
		gameUIDataModel.HasScore = false;
		gameUIDataModel.HasScoreToWin = false;
		gameUIDataModel.HasRank = false;
		gameUIDataModel.HasCustomRankName = false;
		gameUIDataModel.RankName = null;
		gameUIDataModel.SupportsPreviousGameResults = false;
		gameUIDataModel.StaysInPostGameForever = !gameManager.supportsPlayingAgainInThisInstance;
		gameUIDataModel.SupportsExplicitTeamJoining = gameManager.CurrentMode.TeamSettings.SupportsExplicitTeamJoining;
		gameUIDataModel.SupportsModeSwitching = gameManager.HasMoreThanOneMode;
		gameUIDataModel.SupportsMapSwitching = gameManager.SupportsLevelSwitching;
		gameUIDataModel.SupportsJoinInProgress = gameManager.CurrentMode.GameStartSettings.SupportsJoinInProgress;
		gameUIDataModel.CanContinue = gameManager.CanContinue;
		gameUIDataModel.SupportsTimedMatches = false;
		gameUIDataModel.ModeName = string.Empty;
		gameUIDataModel.NextMapName = gameManager.NextLevel;
		gameManager.TeamManager.GetRequiredTeamCountAndSize(gameManager.CurrentMode.GameStartSettings.GameStartTeamRequirement, out gameUIDataModel.RequiredPlayerCount, out gameUIDataModel.RequiredTeamCount, out gameUIDataModel.RequiredTeamSize);
		gameUIDataModel.WinCondition = string.Empty;
		gameUIDataModel.PresenceString = string.Empty;
		int num = System.Enum.GetValues(typeof(PlayerStatType)).Length - 1;
		gameUIDataModel.StatCount = 0;
		gameUIDataModel.StatNames = new string[num];
		gameUIDataModel.HideStatsInUI = new bool[num];
		int num2 = System.Enum.GetValues(typeof(GameTeam)).Length - 1;
		gameUIDataModel.TeamCount = 0;
		gameUIDataModel.TeamModels = new GameUITeamDataModel[num2];
		int length = System.Enum.GetValues(typeof(GameTeamPlayerIndex)).Length;
		for (int i = 0; i < num2; i++)
		{
			gameUIDataModel.TeamModels[i] = new GameUITeamDataModel();
			gameUIDataModel.TeamModels[i].Active = false;
			gameUIDataModel.TeamModels[i].IsLocal = false;
			gameUIDataModel.TeamModels[i].Color = Color.white;
			gameUIDataModel.TeamModels[i].Score = 0;
			gameUIDataModel.TeamModels[i].Rank = string.Empty;
			gameUIDataModel.TeamModels[i].GameTeam = GameTeam.ANY;
			gameUIDataModel.TeamModels[i].PlayerModels = new GameUIPlayerDataModel[length];
			for (int j = 0; j < length; j++)
			{
				gameUIDataModel.TeamModels[i].PlayerModels[j] = new GameUIPlayerDataModel();
				gameUIDataModel.TeamModels[i].PlayerModels[j].Active = false;
				gameUIDataModel.TeamModels[i].PlayerModels[j].IsLocal = false;
				gameUIDataModel.TeamModels[i].PlayerModels[j].StatCount = 0;
				gameUIDataModel.TeamModels[i].PlayerModels[j].Stats = new int[num];
			}
		}
		gameUIDataModel.LocalPlayer = new GameUILocalPlayerDataModel();
		gameUIDataModel.LocalPlayer.IsSpectator = true;
		gameUIDataModel.LocalPlayer.CanSwitchTeams = false;
		gameUIDataModel.LocalPlayer.CanJoinGame = false;
		gameUIDataModel.LocalPlayer.CanLeaveGame = false;
		gameUIDataModel.LocalPlayer.CanStartGame = false;
		gameUIDataModel.LocalPlayer.CanChangeMode = false;
		return gameUIDataModel;
	}

	private void UpdateCurrentGameModel()
	{
		currentDataModel.SupportsPreviousGameResults = supportsPreviousGameResults;
		currentDataModel.NextMapName = gameManager.NextLevel;
		currentDataModel.CanContinue = gameManager.CanContinue;
		if (previousDataModel != null)
		{
			previousDataModel.NextMapName = currentDataModel.NextMapName;
		}
		gameManager.TeamManager.GetRequiredTeamCountAndSize(gameManager.CurrentMode.GameStartSettings.GameStartTeamRequirement, out currentDataModel.RequiredPlayerCount, out currentDataModel.RequiredTeamCount, out currentDataModel.RequiredTeamSize);
		ScoreboardSettings scoreboardSettings = gameManager.CurrentMode.ScoreboardSettings;
		int num = (scoreboardSettings.MinScoreboardTeamSize.Overrides ? scoreboardSettings.MinScoreboardTeamSize.Value : 0);
		string winCondition = gameManager.ScoreManager.ScoreToWinAndUnitsString.ToUpper();
		currentDataModel.HasScore = gameManager.CurrentMode.ScoreSettings.HasScore;
		currentDataModel.HasScoreToWin = gameManager.ScoreManager.ScoreToWin > 0;
		currentDataModel.HasRank = gameManager.ScoreManager.HasRanks();
		currentDataModel.HasCustomRankName = gameManager.CurrentMode.ScoreSettings.HasCustomRankName;
		currentDataModel.RankName = gameManager.CurrentMode.ScoreSettings.CustomRankName;
		if (gameManager.CurrentMode.ScoreSettings.GameOverCondition == GameOverCondition.TIMED)
		{
			currentDataModel.WinCondition = "TIMED";
		}
		else if (gameManager.CurrentMode.ScoreSettings.GameOverCondition == GameOverCondition.ARBITRARY)
		{
			currentDataModel.WinCondition = "-";
		}
		else
		{
			currentDataModel.WinCondition = winCondition;
		}
		currentDataModel.StatCount = gameManager.CurrentMode.ScoreSettings.Stats.Length;
		for (int i = 0; i < currentDataModel.StatCount; i++)
		{
			currentDataModel.StatNames[i] = gameManager.CurrentMode.ScoreSettings.Stats[i].Name;
			currentDataModel.HideStatsInUI[i] = gameManager.CurrentMode.ScoreSettings.Stats[i].HideInUI;
		}
		string text = gameManager.CurrentMode.Name.ToUpper();
		if (SessionManager.InPrivateSession)
		{
			if (!string.IsNullOrEmpty(text))
			{
				text += " ";
			}
			text += "(INVITE ONLY)";
		}
		currentDataModel.ModeName = text;
		currentDataModel.PresenceString = gameManager.PresenceManager.CurrentPresenceString;
		currentDataModel.SupportsTimedMatches = gameManager.CurrentMode.TimerSettings.GameHasDuration;
		currentDataModel.SupportsMapSwitching = gameManager.SupportsLevelSwitching;
		currentDataModel.StaysInPostGameForever = !gameManager.supportsPlayingAgainInThisInstance;
		GameTeam[] allTeams = gameManager.TeamManager.GetAllTeams();
		Array.Sort(allTeams, delegate(GameTeam a, GameTeam b)
		{
			int num11 = (int)a;
			return num11.CompareTo((int)b);
		});
		currentDataModel.TeamCount = gameManager.CurrentMode.TeamSettings.TeamConfigs.Length;
		int num2 = 0;
		for (int num3 = 0; num3 < allTeams.Length; num3++)
		{
			currentDataModel.TeamModels[num3].IsLocal = false;
			currentDataModel.TeamModels[num3].Color = gameManager.TeamManager.GetTeamColor(allTeams[num3]);
			currentDataModel.TeamModels[num3].Score = gameManager.ScoreManager.GetScore(allTeams[num3]);
			currentDataModel.TeamModels[num3].GameTeam = allTeams[num3];
			GameScoreManager.ScoreRank teamRank = gameManager.ScoreManager.GetTeamRank(allTeams[num3]);
			currentDataModel.TeamModels[num3].Rank = ((teamRank <= GameScoreManager.ScoreRank.Invalid) ? string.Empty : teamRank.ToString());
			if (teamRank == GameScoreManager.ScoreRank.SS)
			{
				currentDataModel.TeamModels[num3].Rank = "S+";
			}
			PhotonPlayer[] teamPlayersSortedByIndex = gameManager.TeamManager.GetTeamPlayersSortedByIndex(allTeams[num3]);
			currentDataModel.TeamModels[num3].Active = teamPlayersSortedByIndex.Length > 0;
			int num4 = System.Enum.GetValues(typeof(PlayerStatType)).Length - 1;
			int num5 = currentDataModel.TeamModels[num3].PlayerModels.Length;
			int num6 = Math.Max(num, teamPlayersSortedByIndex.Length);
			num2 += num6;
			Array.Resize(ref currentDataModel.TeamModels[num3].PlayerModels, num6);
			for (int num7 = num5; num7 < currentDataModel.TeamModels[num3].PlayerModels.Length; num7++)
			{
				currentDataModel.TeamModels[num3].PlayerModels[num7] = new GameUIPlayerDataModel();
				currentDataModel.TeamModels[num3].PlayerModels[num7].Active = false;
				currentDataModel.TeamModels[num3].PlayerModels[num7].IsLocal = false;
				currentDataModel.TeamModels[num3].PlayerModels[num7].StatCount = 0;
				currentDataModel.TeamModels[num3].PlayerModels[num7].Stats = new int[num4];
			}
			int num8;
			for (num8 = 0; num8 < teamPlayersSortedByIndex.Length; num8++)
			{
				if (teamPlayersSortedByIndex[num8] == PhotonNetwork.player)
				{
					currentDataModel.TeamModels[num3].PlayerModels[num8].IsLocal = true;
					currentDataModel.TeamModels[num3].IsLocal = true;
				}
				else
				{
					currentDataModel.TeamModels[num3].PlayerModels[num8].IsLocal = false;
				}
				currentDataModel.TeamModels[num3].PlayerModels[num8].Active = true;
				Profile profile = Profiles.Get(teamPlayersSortedByIndex[num8].RecNetProfileId);
				string empty = string.Empty;
				if (profile != null)
				{
					empty = profile.DisplayName.GetDecrypted();
				}
				else
				{
					Player player = teamPlayersSortedByIndex[num8].ToPlayer();
					empty = ((!(player != null)) ? teamPlayersSortedByIndex[num8].NickName : player.PlayerName);
				}
				currentDataModel.TeamModels[num3].PlayerModels[num8].Name = empty;
				currentDataModel.TeamModels[num3].PlayerModels[num8].StatCount = currentDataModel.StatCount;
				for (int num9 = 0; num9 < currentDataModel.StatCount; num9++)
				{
					gameManager.ScoreManager.TryGetPlayerStat(teamPlayersSortedByIndex[num8], gameManager.CurrentMode.ScoreSettings.Stats[num9].StatType, out var value);
					currentDataModel.TeamModels[num3].PlayerModels[num8].Stats[num9] = value;
				}
			}
			for (; num8 < currentDataModel.TeamModels[num3].PlayerModels.Length; num8++)
			{
				currentDataModel.TeamModels[num3].PlayerModels[num8].Active = false;
			}
		}
		int num10 = 8;
		if (scoreboardSettings.ScoreboardPageSize.Overrides)
		{
			num10 = scoreboardSettings.ScoreboardPageSize.Value;
		}
		else
		{
			switch (scoreboardSettings.PageSizeCalculation)
			{
			case ScoreboardSettings.PageSizeCalculations.MinTeamSizeX2:
				num10 = num * 2;
				break;
			case ScoreboardSettings.PageSizeCalculations.FitPlayerCount:
				num10 = num2;
				break;
			}
		}
		if (scoreboardSettings.MinScoreboardPageSize.Overrides)
		{
			num10 = Math.Max(scoreboardSettings.MinScoreboardPageSize.Value, num10);
		}
		currentDataModel.ScoreboardPageSize = num10;
		currentDataModel.LocalPlayer.IsSpectator = gameManager.TeamManager.IsPlayerSpectator(PhotonNetwork.player);
		currentDataModel.LocalPlayer.CanSwitchTeams = gameManager.TeamManager.PlayerCanSwitchTeam(PhotonNetwork.player);
		currentDataModel.LocalPlayer.CanLeaveGame = gameManager.TeamManager.PlayerCanLeaveGame(PhotonNetwork.player);
		currentDataModel.LocalPlayer.CanStartGame = PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanStartGames.Value;
		currentDataModel.LocalPlayer.CanChangeMode = PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanChangeGameMode.Value;
		switch (gameManager.CurrentState)
		{
		case GameStates.PRE_GAME:
			currentDataModel.LocalPlayer.CanJoinGame = gameManager.TeamManager.GetGameVacancy() > 0;
			break;
		case GameStates.GAME_RUNNING:
			currentDataModel.LocalPlayer.CanJoinGame = gameManager.ReadyToJoinInProgress;
			break;
		default:
			currentDataModel.LocalPlayer.CanJoinGame = false;
			break;
		}
	}

	private void UpdateUITimerDataModel()
	{
		if (gameManager.PresenceManager.CustomTimerString != null)
		{
			currentTimerDataModel.GameTimeRemaining = gameManager.PresenceManager.CustomTimerString;
		}
		else if (gameManager.CurrentMode.TimerSettings.GameHasDuration)
		{
			currentTimerDataModel.GameDuration = gameManager.GameTimerManager.Duration.ToTimeString();
			currentTimerDataModel.GameTimeRemaining = gameManager.GameTimerManager.TimeRemaining.ToTimeString();
		}
		else
		{
			currentTimerDataModel.GameDuration = "∞";
			currentTimerDataModel.GameTimeRemaining = gameManager.GameTimerManager.TimeElapsed.ToTimeString();
		}
		if (gameManager.CurrentPreGameState == PreGameSubStates.GAME_LOADING)
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = ((int)gameManager.LoadingGameTimeRemaining/*cast due to .constrained prefix*/).ToString();
		}
		else if (gameManager.CurrentState == GameStates.POST_GAME)
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = ((int)gameManager.PostGameTimeRemaining/*cast due to .constrained prefix*/).ToString();
		}
		else
		{
			currentTimerDataModel.GameStateTransitionTimeRemaining = "0";
		}
	}

	private void BroadcastGameUIDataModel()
	{
		GameUIDataModel dataModel = ((uiState != GameUIState.RESULTS && uiState != GameUIState.RESULTS_LOCKED) ? currentDataModel : previousDataModel);
		for (int i = 0; i < gameUiViews.Count; i++)
		{
			gameUiViews[i].SetGameDataModel(uiState, dataModel);
		}
	}

	private void BroadcastUITimerDataModel()
	{
		GameUITimerDataModel timerDataModel = ((uiState != GameUIState.RESULTS) ? currentTimerDataModel : previousTimerDataModel);
		for (int i = 0; i < gameUiViews.Count; i++)
		{
			gameUiViews[i].SetTimerDataModel(uiState, timerDataModel);
		}
	}

	private void UpdateUIState()
	{
		switch (gameManager.CurrentState)
		{
		case GameStates.PRE_GAME:
			switch (gameManager.CurrentPreGameState)
			{
			case PreGameSubStates.WAITING_FOR_PLAYERS:
				uiState = GameUIState.WAITING_FOR_PLAYERS;
				break;
			case PreGameSubStates.WAITING_FOR_START_GAME:
				uiState = GameUIState.PRE_GAME;
				break;
			case PreGameSubStates.GAME_LOADING:
				uiState = GameUIState.GAME_STARTING;
				break;
			case PreGameSubStates.GAME_ON:
				uiState = GameUIState.GAME_ON;
				break;
			}
			break;
		case GameStates.GAME_RUNNING:
			uiState = GameUIState.GAME_RUNNING;
			break;
		case GameStates.POST_GAME:
			switch (gameManager.CurrentPostGameState)
			{
			case PostGameSubStates.GAME_OVER:
				uiState = GameUIState.GAME_OVER;
				break;
			case PostGameSubStates.RESULTS:
				uiState = GameUIState.RESULTS_LOCKED;
				UpdateCurrentGameModel();
				GameUIDataModel.DeepCopy(currentDataModel, previousDataModel);
				GameUITimerDataModel.DeepCopy(currentTimerDataModel, previousTimerDataModel);
				supportsPreviousGameResults = true;
				break;
			}
			break;
		}
	}
}
