namespace RecRoom
{
	public class ModeRestriction : VisibilityRestriction
	{
		public enum RoomCreator
		{
			AG_CREATED,
			PLAYER_CREATED,
			ALL
		}

		public enum SessionVisibility
		{
			PUBLIC,
			PRIVATE,
			ALL
		}

		public enum GameMode
		{
			NON_SANDBOX,
			SANDBOX,
			ALL
		}

		[SerializeField]
		private RoomCreator supportedRoomCreator = RoomCreator.ALL;

		[SerializeField]
		private SessionVisibility supportedVisibility = SessionVisibility.ALL;

		[SerializeField]
		private GameMode supportedGameMode = GameMode.ALL;

		public RoomSceneLocationPicker[] DisableInLocations;

		public static bool IsSupported(RoomCreator roomCreator)
		{
			bool isAGRoom = RecNet.Rooms.LocalRoomDetails.Room.IsAGRoom;
			return roomCreator == RoomCreator.ALL || (isAGRoom && roomCreator == RoomCreator.AG_CREATED) || (!isAGRoom && roomCreator == RoomCreator.PLAYER_CREATED);
		}

		public static bool IsSupported(SessionVisibility visibility)
		{
			bool flag = GameSessions.LocalGameSession.Private;
			return visibility == SessionVisibility.ALL || (flag && visibility == SessionVisibility.PRIVATE) || (!flag && visibility == SessionVisibility.PUBLIC);
		}

		public static bool IsSupported(GameMode gameMode)
		{
			bool isSandbox = GameSessions.LocalGameSession.IsSandbox;
			return gameMode == GameMode.ALL || (isSandbox && gameMode == GameMode.SANDBOX) || (!isSandbox && gameMode == GameMode.NON_SANDBOX);
		}

		protected override void RefreshVisibility()
		{
			bool active = IsSupported(supportedRoomCreator) && IsSupported(supportedVisibility) && IsSupported(supportedGameMode) && !DisabledInLocation(GameSessions.LocalGameSession.Location);
			base.gameObject.SetActive(active);
		}

		private bool DisabledInLocation(RoomSceneLocations location)
		{
			if (DisableInLocations == null)
			{
				return false;
			}
			for (int i = 0; i < DisableInLocations.Length; i++)
			{
				if (AGRoomSettings.GetRoomSceneLocationReplicationId(location) == DisableInLocations[i].LocationId)
				{
					return true;
				}
			}
			return false;
		}
	}
}
public class PlayerCombatUI : UnityEngine.MonoBehaviour
{
	protected enum PlayerLifeState
	{
		ALIVE,
		DBNO,
		DEAD
	}

	[SerializeField]
	[FormerlySerializedAs("deadIcon")]
	protected SpriteRenderer icon;

	[Header("Sprites")]
	[SerializeField]
	protected Sprite downedSprite;

	[SerializeField]
	protected Sprite deadSprite;

	[Header("Bars")]
	[SerializeField]
	protected HealthBar shieldBar;

	[SerializeField]
	[Tooltip("Health bar will be searched in children if not assigned")]
	protected HealthBar healthBar;

	[SerializeField]
	protected HealthBar dbnoBar;

	[Header("Labels")]
	[SerializeField]
	protected GameObject reviveText;

	private GameManager _gameManager;

	protected PhotonPlayer player;

	protected Player playerAvatar;

	private bool playerIsDownButNotOut;

	protected CustomKOEffect attackersCustomKOEffect;

	protected bool healthBarAlwaysVisible;

	protected bool displayHealthBar = true;

	protected ThrobbingUIElement deadIconUpdater;

	protected bool isLocalPlayersTeammate;

	protected bool isTeamGame;

	protected Color playerTeamColor;

	public GameManager GameManager
	{
		get
		{
			return _gameManager;
		}
		set
		{
			if (_gameManager != value)
			{
				if (_gameManager != null)
				{
					_gameManager.CombatManager.PlayerHealthChangeEvent -= OnPlayerHealthChange;
					_gameManager.CombatManager.PlayerKilledPlayerEvent -= OnPlayerKilled;
				}
				_gameManager = value;
				if (_gameManager != null)
				{
					_gameManager.CombatManager.PlayerHealthChangeEvent += OnPlayerHealthChange;
					_gameManager.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilled;
				}
				UpdatePlayerHealth(resetHealth: true);
			}
		}
	}

	public void SetPlayer(PhotonPlayer player, bool displayHealthBar, bool healthBarAlwaysVisible)
	{
		this.player = player;
		playerAvatar = ((this.player == null) ? null : this.player.ToPlayer());
		this.displayHealthBar = displayHealthBar;
		this.healthBarAlwaysVisible = healthBarAlwaysVisible;
		if (healthBar != null)
		{
			healthBar.gameObject.SetActive(this.displayHealthBar);
			healthBar.AlwaysViewVisible = this.healthBarAlwaysVisible;
		}
		if (shieldBar != null)
		{
			shieldBar.gameObject.SetActive(this.displayHealthBar);
			shieldBar.AlwaysViewVisible = this.healthBarAlwaysVisible;
		}
		if (dbnoBar != null)
		{
			dbnoBar.gameObject.SetActive(this.displayHealthBar);
			dbnoBar.AlwaysViewVisible = this.healthBarAlwaysVisible;
		}
		isLocalPlayersTeammate = GameManager.TeamManager.PlayersAreTeammates(player, PhotonNetwork.player);
		isTeamGame = GameManager.TeamManager.MaxTeamCount > 1;
		GameTeam playerTeam = GameManager.TeamManager.GetPlayerTeam(player);
		playerTeamColor = GameManager.TeamManager.GetTeamColor(playerTeam);
		UpdatePlayerHealth();
	}

	private void Awake()
	{
		if (healthBar == null)
		{
			healthBar = GetComponentInChildren<HealthBar>();
		}
		if (icon != null)
		{
			deadIconUpdater = icon.GetComponent<ThrobbingUIElement>();
			if (deadSprite == null)
			{
				deadSprite = icon.sprite;
			}
		}
	}

	private void LateUpdate()
	{
		if (playerIsDownButNotOut)
		{
			UpdatePlayerHealth();
		}
		if (playerAvatar != null)
		{
			base.transform.position = playerAvatar.PlayerUI.LabelTransform.position;
			base.transform.rotation = playerAvatar.PlayerUI.LabelTransform.rotation;
		}
	}

	private void OnPlayerHealthChange(PhotonPlayer player)
	{
		if (player != null && this.player == player)
		{
			UpdatePlayerHealth();
		}
	}

	private void OnPlayerKilled(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
	{
		if (defender == null || player != defender)
		{
			return;
		}
		if (attacker == null || attacker == defender || (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.PlayersAreTeammates(attacker, defender)))
		{
			attackersCustomKOEffect = null;
			return;
		}
		attackersCustomKOEffect = attacker.ToPlayer().CustomKOEffect.GetInstanceOfActiveEffect();
		if (attackersCustomKOEffect != null)
		{
			attackersCustomKOEffect.transform.SetParent(base.transform);
			if (attackersCustomKOEffect.Sprite != null)
			{
				attackersCustomKOEffect.Sprite.color = ((!isTeamGame) ? Color.white : playerTeamColor);
			}
			RectTransform rectTransform = attackersCustomKOEffect.transform as RectTransform;
			if (rectTransform != null)
			{
				attackersCustomKOEffect.transform.localPosition = new Vector3(rectTransform.anchorMax.x - rectTransform.pivot.x, rectTransform.anchorMax.y - rectTransform.pivot.y, 0f);
			}
			attackersCustomKOEffect.transform.localRotation = Quaternion.identity;
			RefreshDefaultIconState(GetPlayerState(player));
		}
	}

	private void UpdatePlayerHealth()
	{
		UpdatePlayerHealth(resetHealth: false);
	}

	private void RefreshDefaultIconState(PlayerLifeState lifeState)
	{
		if (!(icon != null))
		{
			return;
		}
		switch (lifeState)
		{
		case PlayerLifeState.ALIVE:
			icon.gameObject.SetActive(value: false);
			if (deadIconUpdater != null)
			{
				deadIconUpdater.Active = false;
			}
			break;
		case PlayerLifeState.DBNO:
			icon.sprite = downedSprite;
			icon.color = playerTeamColor;
			icon.gameObject.SetActive(value: true);
			if (deadIconUpdater != null)
			{
				deadIconUpdater.Active = true;
			}
			break;
		case PlayerLifeState.DEAD:
		{
			bool flag = attackersCustomKOEffect != null;
			icon.gameObject.SetActive(!flag);
			if (!flag)
			{
				icon.sprite = deadSprite;
				icon.color = ((!isTeamGame) ? Color.white : playerTeamColor);
			}
			if (deadIconUpdater != null)
			{
				deadIconUpdater.Active = !flag;
			}
			break;
		}
		}
	}

	protected virtual void UpdatePlayerHealth(bool resetHealth)
	{
		if (player == null || GameManager == null)
		{
			playerIsDownButNotOut = false;
			return;
		}
		PlayerLifeState playerState = GetPlayerState(player);
		playerIsDownButNotOut = playerState == PlayerLifeState.DBNO;
		bool active = false;
		if (reviveText != null)
		{
			if (isLocalPlayersTeammate && playerState != PlayerLifeState.ALIVE)
			{
				if (GameManager.CombatManager.PlayerCanBeRevived(player, out var timeUntilRevive))
				{
					active = true;
				}
				else if (!playerIsDownButNotOut)
				{
					this.WaitRoutine(timeUntilRevive + 0.05f, UpdatePlayerHealth);
				}
			}
			reviveText.SetActive(active);
		}
		if (dbnoBar != null && displayHealthBar)
		{
			dbnoBar.gameObject.SetActive(playerState == PlayerLifeState.DBNO);
			if (playerState == PlayerLifeState.DBNO)
			{
				float playerDownButNotOutValue = GameManager.CombatManager.GetPlayerDownButNotOutValue(player);
				float downButNotOutMaxValue = GameManager.CurrentMode.CombatSettings.DownButNotOutMaxValue;
				if (resetHealth)
				{
					dbnoBar.ResetHealth(playerDownButNotOutValue, downButNotOutMaxValue);
				}
				else
				{
					dbnoBar.OnHealthChange(playerDownButNotOutValue, downButNotOutMaxValue, !isLocalPlayersTeammate);
				}
			}
		}
		if (healthBar != null && displayHealthBar)
		{
			healthBar.gameObject.SetActive(playerState == PlayerLifeState.ALIVE);
			if (playerState == PlayerLifeState.ALIVE)
			{
				int playerHealth = GameManager.CombatManager.GetPlayerHealth(player);
				int defaultHealth = GameManager.CurrentMode.CombatSettings.DefaultHealth;
				if (resetHealth)
				{
					healthBar.ResetHealth(playerHealth, defaultHealth);
				}
				else
				{
					healthBar.OnHealthChange(playerHealth, defaultHealth, !isLocalPlayersTeammate);
				}
			}
		}
		if (shieldBar != null && displayHealthBar)
		{
			shieldBar.gameObject.SetActive(playerState == PlayerLifeState.ALIVE);
			if (playerState == PlayerLifeState.ALIVE)
			{
				int playerShield = GameManager.CombatManager.GetPlayerShield(player);
				int maximumShield = GameManager.CurrentMode.CombatSettings.MaximumShield;
				if (resetHealth)
				{
					shieldBar.ResetHealth(playerShield, maximumShield);
				}
				else
				{
					shieldBar.OnHealthChange(playerShield, maximumShield, !isLocalPlayersTeammate);
				}
			}
		}
		RefreshDefaultIconState(playerState);
		if (playerState == PlayerLifeState.ALIVE && attackersCustomKOEffect != null)
		{
			ObjectPool.Instance.Release(attackersCustomKOEffect);
			attackersCustomKOEffect = null;
		}
	}

	private PlayerLifeState GetPlayerState(PhotonPlayer player)
	{
		if (GameManager.CombatManager.IsPlayerDownButNotOut(player))
		{
			return PlayerLifeState.DBNO;
		}
		if (!GameManager.CombatManager.PlayerIsAlive(player))
		{
			return PlayerLifeState.DEAD;
		}
		return PlayerLifeState.ALIVE;
	}
}
namespace RecRoom.UI
{
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Custom Game Behavior Controllers/Battle Royale Map Screen Controller", fileName = "BattleRoyaleMapScreenController")]
	public class BattleRoyaleMapScreenController : ScreenCustomGameBehaviorController
	{
		[SerializeField]
		private float menuVerticalBufferPercentage = 4f;

		private int startedFrame;

		public override void OnAddedToPlayerController(ScreenPlayerController playerController)
		{
			playerController.AddFavoriteToolRestriction(this);
		}

		public override void OnRemovedFromPlayerController(ScreenPlayerController playerController)
		{
			playerController.RemoveFavoriteToolRestriction(this);
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, GameManager gameManager, ScreenInputHandler input)
		{
			if (!input.FavoriteToolButtonDown)
			{
				return false;
			}
			if (!player.ToolEquipSlots.ShoulderSlot.enabled)
			{
				return false;
			}
			if (!player.ToolEquipSlots.ShoulderSlot.IsFull)
			{
				return false;
			}
			Tool tool = player.ToolEquipSlots.ShoulderSlot.EquippedTool.SelectForwardedTool(player, physicalPickupSelection: true);
			if (tool == null)
			{
				return false;
			}
			BattleRoyalePlayerMap component = tool.GetComponent<BattleRoyalePlayerMap>();
			if (component == null)
			{
				return false;
			}
			if (!gameManager.CombatManager.PlayerIsAlive(player.PhotonPlayer))
			{
				return false;
			}
			if (!player.CanInteractWithTools)
			{
				return false;
			}
			return true;
		}

		public override bool PreventsToolPickup(ScreenPlayerController playerController, Player player, GameManager gameManager)
		{
			return false;
		}

		public override bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.FavoriteToolSprite, "Open Map");
			return true;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			startedFrame = UnityEngine.Time.frameCount;
			playerController.AddGameplayCursorVisibilityRestriction(this);
			Tool tool = player.ToolEquipSlots.ShoulderSlot.EquippedTool.SelectForwardedTool(player, physicalPickupSelection: true);
			if (tool == null)
			{
				return;
			}
			BattleRoyalePlayerMap component = tool.GetComponent<BattleRoyalePlayerMap>();
			if (!(component == null))
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				if (offHand.HeldTool != null)
				{
					playerController.TryDropOffHandTool(player);
				}
				playerController.TryPickupToolOffHand(player, tool);
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			PlayerHand offHand = playerController.GetOffHand(player);
			Tool heldTool = offHand.HeldTool;
			if (heldTool == null)
			{
				return false;
			}
			if (!player.ToolEquipSlots.ShoulderSlot.enabled)
			{
				return false;
			}
			BattleRoyalePlayerMap component = heldTool.GetComponent<BattleRoyalePlayerMap>();
			if (component == null)
			{
				return false;
			}
			if (!gameManager.CombatManager.PlayerIsAlive(player.PhotonPlayer))
			{
				return false;
			}
			if (!player.CanInteractWithTools)
			{
				return false;
			}
			if (UnityEngine.Time.frameCount > startedFrame)
			{
				if (input.FavoriteToolButtonDown || input.CancelButtonDown)
				{
					return false;
				}
				hud.AddToolActionDialog(input.FavoriteToolSprite, "Close Map");
			}
			return true;
		}

		public override void OnLateUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			PlayerHand offHand = playerController.GetOffHand(player);
			BattleRoyalePlayerMap battleRoyalePlayerMap = ((!(offHand.HeldTool != null)) ? null : offHand.HeldTool.GetComponent<BattleRoyalePlayerMap>());
			if (!(battleRoyalePlayerMap == null) && hud.WorldSpaceUIAnchor.AttachedGameObject != battleRoyalePlayerMap.OpenMapRoot.gameObject)
			{
				battleRoyalePlayerMap.DetachOpenMap();
				hud.WorldSpaceUIAnchor.Attach(battleRoyalePlayerMap.OpenMapRoot.gameObject, battleRoyalePlayerMap.OpenMapWorldSpaceDimensions.y, Quaternion.LookRotation(Vector3.up), menuVerticalBufferPercentage, resetPositionOnDetach: false);
			}
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager)
		{
			hud.WorldSpaceUIAnchor.Detach();
			playerController.RemoveGameplayCursorVisibilityRestriction(this);
			if (player == null)
			{
				return;
			}
			PlayerHand offHand = playerController.GetOffHand(player);
			Tool heldTool = offHand.HeldTool;
			if (!(heldTool == null))
			{
				BattleRoyalePlayerMap component = heldTool.GetComponent<BattleRoyalePlayerMap>();
				if (!(component == null))
				{
					component.ReattachOpenMap();
					playerController.TryDropOffHandTool(player);
					component.Tool.SuppressAnimateInOut = true;
					component.ResetToBag();
					component.Tool.SuppressAnimateInOut = false;
				}
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player, GameManager gameManager)
		{
		}
	}
}
