	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Custom Game Behavior Controllers/Revive Teammate Screen Controller", fileName = "ReviveTeammateScreenController")]
	public class ReviveTeammateCustomGameScreenController : ScreenCustomGameBehaviorController
	{
		[Header("High Five Animation")]
		[SerializeField]
		private PlayerAnimation highFiveReviveAnimation;

		[Header("Handshake Animation")]
		[SerializeField]
		private PlayerAnimation handshakeReviveAnimation;

		[Header("Settings")]
		[SerializeField]
		private float maxReviveDistance = 1f;

		[SerializeField]
		private float walkSpeedMultiplier;

		[Header("Tooltip")]
		[SerializeField]
		private float tooltipHeight = 1f;

		private const float MAX_SEARCH_DISTANCE = 5f;

		private const float MAX_SEARCH_DISTANCE_SQR = 25f;

		private const float PLAYER_SEARCH_FREQUENCY = 3f;

		private const float PLAYER_SEARCH_PERIOD = 1f / 3f;

		private float lastSearchTime;

		private PhotonPlayer cachedNearestDeadTeammate;

		private bool isHandshakeReviving;

		private float handshakeReviveStartTime;

		private float maxReviveMoveDistance = 1f;

		private Vector3 handshakeStartPosition = Vector3.zero;

		private PhotonPlayer revivableTeammate;

		public override void OnAddedToPlayerController(ScreenPlayerController playerController)
		{
			lastSearchTime = UnityEngine.Time.time - 1f;
			cachedNearestDeadTeammate = null;
		}

		public override void OnRemovedFromPlayerController(ScreenPlayerController playerController)
		{
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, GameManager gameManager, ScreenInputHandler input)
		{
			if (!gameManager.IsGameRunning)
			{
				return false;
			}
			PhotonPlayer photonPlayer = GetRevivableTeammate(player, gameManager);
			return photonPlayer != null && (input.PickupButtonDown || input.PickupButtonPressed);
		}

		public override bool PreventsToolPickup(ScreenPlayerController playerController, Player player, GameManager gameManager)
		{
			PhotonPlayer photonPlayer = GetRevivableTeammate(player, gameManager);
			return photonPlayer != null;
		}

		public override bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			PhotonPlayer photonPlayer = GetRevivableTeammate(player, gameManager);
			if (photonPlayer != null)
			{
				Player player2 = photonPlayer.ToPlayer();
				if (player2 != null)
				{
					Vector2 viewportPosition = camera.WorldToViewportPoint(player2.TrackingSpace.transform.position + Vector3.up * tooltipHeight);
					hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, "Revive");
					return true;
				}
			}
			return false;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			revivableTeammate = GetRevivableTeammate(player, gameManager);
			if (gameManager.CombatManager.RequiresHandshakeRevive)
			{
				handshakeStartPosition = player.TrackingSpace.RigidbodyEx.targetPosition;
				handshakeReviveStartTime = UnityEngine.Time.time;
				isHandshakeReviving = true;
				playerController.PlayLoopingAnimation(handshakeReviveAnimation);
				PlayerHand offHand = playerController.GetOffHand(player);
				PlayerHand closerOtherPlayerHand = GetCloserOtherPlayerHand(player, revivableTeammate);
				gameManager.CombatManager.LocalPlayerRequestStartHandshakeRevive(revivableTeammate, closerOtherPlayerHand, offHand);
			}
			else
			{
				isHandshakeReviving = false;
				playerController.PlayAnimation(highFiveReviveAnimation, restartIfAlreadyPlaying: true);
			}
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplier, this);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			if (isHandshakeReviving)
			{
				return UpdateHandshakeRevive(playerController, player, camera, gameManager, input);
			}
			return playerController.IsAnimationPlaying(highFiveReviveAnimation);
		}

		public override void OnLateUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, GameManager gameManager)
		{
			if (isHandshakeReviving && revivableTeammate != null && gameManager != null)
			{
				gameManager.CombatManager.LocalPlayerRequestCancelHandshakeRevive(revivableTeammate);
			}
			revivableTeammate = null;
			isHandshakeReviving = false;
			playerController.RemoveWalkSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player, GameManager gameManager)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1 && revivableTeammate != null && !isHandshakeReviving)
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				gameManager.CombatManager.LocalPlayerRequestHighFiveRevive(revivableTeammate, offHand.RigidbodyEx.targetPosition);
			}
		}

		private PhotonPlayer GetRevivableTeammate(Player player, GameManager gameManager)
		{
			if (UnityEngine.Time.time - lastSearchTime > 1f / 3f)
			{
				lastSearchTime = UnityEngine.Time.time;
				cachedNearestDeadTeammate = SearchForNearbyTeammateInternal(player, gameManager);
			}
			if (cachedNearestDeadTeammate != null && gameManager.CombatManager.PlayerIsAlive(cachedNearestDeadTeammate))
			{
				cachedNearestDeadTeammate = null;
			}
			if (cachedNearestDeadTeammate == null)
			{
				return null;
			}
			float distSqr = 0f;
			if (!TryGetDistanceSqrToTeammate(player, cachedNearestDeadTeammate, out distSqr))
			{
				return null;
			}
			if (distSqr > maxReviveDistance * maxReviveDistance)
			{
				return null;
			}
			return cachedNearestDeadTeammate;
		}

		private PhotonPlayer SearchForNearbyTeammateInternal(Player player, GameManager gameManager)
		{
			if (!gameManager.IsGameRunning)
			{
				return null;
			}
			PhotonPlayer photonPlayer = player.PhotonPlayer;
			if (!gameManager.CombatManager.PlayerIsAlive(photonPlayer))
			{
				return null;
			}
			PhotonPlayer[] teammatesOfPlayer = gameManager.TeamManager.GetTeammatesOfPlayer(photonPlayer);
			if (teammatesOfPlayer == null || teammatesOfPlayer.Length == 0)
			{
				return null;
			}
			Vector3 targetPosition = player.TrackingSpace.RigidbodyEx.targetPosition;
			PhotonPlayer result = null;
			float num = 25f;
			for (int i = 0; i < teammatesOfPlayer.Length; i++)
			{
				if (!gameManager.CombatManager.PlayerIsAlive(teammatesOfPlayer[i]))
				{
					float distSqr = 0f;
					if (TryGetDistanceSqrToTeammate(player, teammatesOfPlayer[i], out distSqr) && distSqr < num)
					{
						result = teammatesOfPlayer[i];
						num = distSqr;
					}
				}
			}
			return result;
		}

		private bool TryGetDistanceSqrToTeammate(Player thisPlayer, PhotonPlayer teammate, out float distSqr)
		{
			Player player = teammate.ToPlayer();
			if (player == null)
			{
				distSqr = 0f;
				return false;
			}
			Vector3 position = player.TrackingSpace.transform.position;
			distSqr = (position - thisPlayer.TrackingSpace.RigidbodyEx.targetPosition).sqrMagnitude;
			return true;
		}

		private bool UpdateHandshakeRevive(ScreenPlayerController playerController, Player player, Camera camera, GameManager gameManager, ScreenInputHandler input)
		{
			float num = UnityEngine.Time.time - handshakeReviveStartTime;
			if (num >= gameManager.CombatManager.HandshakeReviveDuration + 0.1f)
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				gameManager.CombatManager.LocalPlayerRequestHandshakeReviveSuccess(revivableTeammate, offHand.transform.position);
				isHandshakeReviving = false;
				return false;
			}
			float sqrMagnitude = (player.TrackingSpace.RigidbodyEx.targetPosition - handshakeStartPosition).sqrMagnitude;
			if (sqrMagnitude >= maxReviveMoveDistance * maxReviveMoveDistance)
			{
				return false;
			}
			if (!gameManager.CombatManager.IsValidPlayerRevive(revivableTeammate, PhotonNetwork.player))
			{
				return false;
			}
			return input.PickupButtonPressed;
		}

		private PlayerHand GetCloserOtherPlayerHand(Player thisPlayer, PhotonPlayer otherPlayer)
		{
			if (thisPlayer == null)
			{
				return null;
			}
			if (otherPlayer == null)
			{
				return null;
			}
			Player player = otherPlayer.ToPlayer();
			if (player == null)
			{
				return null;
			}
			float sqrMagnitude = Vector3.ProjectOnPlane(thisPlayer.TrackingSpace.transform.position - player.LeftHand.transform.position, Vector3.up).sqrMagnitude;
			float sqrMagnitude2 = Vector3.ProjectOnPlane(thisPlayer.TrackingSpace.transform.position - player.RightHand.transform.position, Vector3.up).sqrMagnitude;
			if (sqrMagnitude < sqrMagnitude2)
			{
				return player.LeftHand;
			}
			return player.RightHand;
		}
	}
}
[DisallowMultipleComponent]
public class GameTeleportRestriction : TeleportRestriction
{
	[SerializeField]
	private bool spectatorsAllowed = true;

	[SerializeField]
	private bool allTeamsAllowed = true;

	[SerializeField]
	private GameTeam[] allowedTeams;

	[SerializeField]
	private TeleportRegionTagType requiredTag = TeleportRegionTagType.DEFAULT;

	public void UpdateRestrictions(bool isGameRunning, bool localPlayerIsSpectator, GameTeam localPlayerTeam, TeleportRegionTagType playerTag)
	{
		if (!isGameRunning || GameManager.IsSandboxActive)
		{
			base.MovementBlocked = false;
			return;
		}
		if (localPlayerIsSpectator)
		{
			base.MovementBlocked = !spectatorsAllowed;
			return;
		}
		if (allTeamsAllowed)
		{
			base.MovementBlocked = false;
		}
		else
		{
			base.MovementBlocked = true;
			for (int i = 0; i < allowedTeams.Length; i++)
			{
				if (allowedTeams[i] == localPlayerTeam)
				{
					base.MovementBlocked = false;
					break;
				}
			}
		}
		if (requiredTag != TeleportRegionTagType.DEFAULT && requiredTag != playerTag)
		{
			base.MovementBlocked = true;
		}
	}
}
