public class HostManager : NetworkedSingletonMonoBehaviour<HostManager>, IPersistableSettings
{
	private SynchronizedField<bool> _enforceHostsOnlyAreas;

	private SynchronizedField<bool> _allowScoreboards;

	private bool thisSceneContainsHostOnlyAreas;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<bool> m_AllowScoreboardsEvent;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<bool> m_EnforceHostsOnlyAreasEvent;

	private Coroutine localEnforceHostsOnlyAreasRoutine;

	public bool EnforceHostsOnlyAreas
	{
		get
		{
			return _enforceHostsOnlyAreas.Get();
		}
		private set
		{
			_enforceHostsOnlyAreas.Set(value);
		}
	}

	public bool AllowScoreboards
	{
		get
		{
			return _allowScoreboards.Get();
