	private bool LocalPlayerOverValidTeleportRegion
	{
		get
		{
			if (!Player.LocalPlayerExists || PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player))
			{
				return true;
			}
			bool flag = true;
			RaycastHit[] array = Physics.RaycastAll(Player.LocalPlayer.Head.transform.position + Vector3.up * 3f, Vector3.down, 7f, 67128320);
			RaycastHit[] array2 = array;
			foreach (RaycastHit raycastHit in array2)
			{
				EventTeleportRestriction componentInChildren = raycastHit.collider.GetComponentInChildren<EventTeleportRestriction>();
				if (componentInChildren != null && componentInChildren.RegionType == EventTeleportRestriction.TeleportRegionType.HOST && EnforceHostsOnlyAreas)
				{
					flag = false;
				}
			}
			if (flag)
			{
				return true;
			}
			RaycastHit[] array3 = Physics.RaycastAll(Player.LocalPlayer.Body.transform.position + Vector3.up * 3f, Vector3.down, 7f, 67128320);
			RaycastHit[] array4 = array3;
			foreach (RaycastHit raycastHit2 in array4)
			{
				EventTeleportRestriction componentInChildren2 = raycastHit2.collider.GetComponentInChildren<EventTeleportRestriction>();
				if (componentInChildren2 != null && componentInChildren2.RegionType == EventTeleportRestriction.TeleportRegionType.HOST && EnforceHostsOnlyAreas)
				{
					return false;
				}
			}
			return true;
		}
	}

