	protected override void Awake()
	{
		base.Awake();
		_enforceHostsOnlyAreas = new SynchronizedField<bool>(this, "HM_HOA", defaultValue: true, SetterPermissionMode.MASTER, OnEnforceHostsOnlyAreasChange);
		_allowScoreboards = new SynchronizedField<bool>(this, "HM_AS", defaultValue: true, SetterPermissionMode.MASTER, OnAllowScoreboardsChange);
		thisSceneContainsHostOnlyAreas = UnityEngine.Object.FindObjectOfType<EventTeleportRestriction>() != null;
		Player.PlayerCreatedEvent += new Action<Player>(Player_OnPlayerCreated);
		RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomUpdated);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Player.PlayerCreatedEvent -= new Action<Player>(Player_OnPlayerCreated);
		RecNet.Rooms.OnLocalRoomUpdated -= new Action(OnLocalRoomUpdated);
	}

	private void Player_OnPlayerCreated(Player player)
	{
		if (player.isLocal && EnforceHostsOnlyAreas)
		{
			UpdateEnforcementHostOnlyAreas();
		}
	}

	private void OnLocalRoomUpdated()
	{
		CircuitVisibilityBehaviour.CircuitVisibilityChanged();
		EnsureLocalEnforceHostsOnlyAreasCoroutine();
	}

	public void ToggleAllowScoreboards(bool allowScoreboards)
	{
		base.photonView.RpcMaster(RpcMasterToggleAllowScoreboards, allowScoreboards);
	}

	private void OnAllowScoreboardsChange()
	{
		if (this.AllowScoreboardsEvent != null)
		{
			this.AllowScoreboardsEvent(AllowScoreboards);
		}
	}

	public void ToggleEnforceHostsOnlyAreas(bool hostsOnly)
	{
		base.photonView.RpcMaster(RpcMasterToggleEnforceHostsOnlyAreas, hostsOnly);
	}

	private void OnEnforceHostsOnlyAreasChange()
	{
		PlayHostOnlyAreaChangeNotification();
		UpdateEnforcementHostOnlyAreas();
	}

	private void PlayHostOnlyAreaChangeNotification()
	{
		if (thisSceneContainsHostOnlyAreas)
		{
			if (!PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player) && !LocalPlayerOverValidTeleportRegion)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "The host has restricted access to the stage", 2.3f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, (!EnforceHostsOnlyAreas) ? "The host has allowed people on stage" : "The host has restricted access to the stage", 3f);
			}
		}
	}

	private void UpdateEnforcementHostOnlyAreas()
	{
		if (!PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player))
		{
			EnsureLocalEnforceHostsOnlyAreasCoroutine();
		}
		if (this.EnforceHostsOnlyAreasEvent != null)
		{
			this.EnforceHostsOnlyAreasEvent(EnforceHostsOnlyAreas);
		}
	}

	private void EnsureLocalEnforceHostsOnlyAreasCoroutine()
	{
		if (!PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player) && EnforceHostsOnlyAreas && localEnforceHostsOnlyAreasRoutine == null)
		{
			localEnforceHostsOnlyAreasRoutine = StartCoroutine(RunLocalEnforceHostsOnlyAreas());
		}
	}

	private IEnumerator RunLocalEnforceHostsOnlyAreas()
	{
		yield return new WaitForSeconds(2.5f);
		while (EnforceHostsOnlyAreas && !PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player))
		{
			if (!LocalPlayerOverValidTeleportRegion)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "You are not allowed on stage!", 3f);
				yield return new WaitForSeconds(3f);
				if (!LocalPlayerOverValidTeleportRegion)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Respawning offstage...", 2f);
					yield return new WaitForSeconds(2f);
					RecRoomSceneManager.Instance.SpawnManager.LocalPlayerRequestRespawn(dropTools: false);
					yield return new WaitForSeconds(3f);
				}
			}
			else
			{
				yield return new WaitForSeconds(3f);
			}
		}
		localEnforceHostsOnlyAreasRoutine = null;
	}

	[PunRPC]
	private void RpcMasterToggleAllowScoreboards(bool allowScoreboards, PhotonMessageInfo messageInfo)
	{
		if (PlayerRoomRoleManager.IsPlayerAHost(messageInfo.sender))
		{
			AllowScoreboards = allowScoreboards;
		}
	}

	[PunRPC]
	private void RpcMasterToggleEnforceHostsOnlyAreas(bool hostsOnly, PhotonMessageInfo messageInfo)
	{
		if (PlayerRoomRoleManager.IsPlayerAHost(messageInfo.sender))
		{
			EnforceHostsOnlyAreas = hostsOnly;
		}
	}

	public void DeserializeFrom(PersistedRoomData roomData)
	{
		RoomPersistenceVersion version = (RoomPersistenceVersion)roomData.Version;
		if (version < RoomPersistenceVersion.PERSISTENT_HOST_SETTINGS)
		{
			return;
		}
		if (roomData.HostSettings == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing EventManager {0}: Data not specified.", base.gameObject);
			return;
		}
		EnforceHostsOnlyAreas = roomData.HostSettings.EnforceHostOnlyAreas;
		AllowScoreboards = !roomData.HostSettings.HideScoreboards;
		if (roomData.SandboxSettings != null && GameManager.IsSandboxActive)
		{
			int timeLimitSeconds = roomData.SandboxSettings.TimeLimitSeconds;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.RequestMasterSetSandboxDuration(timeLimitSeconds);
		}
	}

	public void SerializeTo(ref PersistedRoomData roomData)
	{
		if (roomData.HostSettings != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing EventManager {0}: Data already specified.", base.gameObject);
			return;
		}
		roomData.HostSettings = new HostSettingsData();
		roomData.HostSettings.EnforceHostOnlyAreas = EnforceHostsOnlyAreas;
		roomData.HostSettings.HideScoreboards = !AllowScoreboards;
		if (roomData.SandboxSettings == null)
		{
			roomData.SandboxSettings = new SandboxSettingsData();
		}
		roomData.SandboxSettings.TimeLimitSeconds = (int)NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Duration;
	}
}
