public class OccupiableSpawnPoint : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool automaticallyRelease = true;

	[SerializeField]
	private float sphereCheckRadius = 0.25f;

	[SerializeField]
	private Vector3 sphereCheckCenter = Vector3.zero;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<OccupiableSpawnPoint> m_AutomaticallyReleasedEvent;

	public bool Occupied { get; private set; }

	public event Action<OccupiableSpawnPoint> AutomaticallyReleasedEvent
	{
		add
		{
			Action<OccupiableSpawnPoint> action = this.m_AutomaticallyReleasedEvent;
			Action<OccupiableSpawnPoint> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_AutomaticallyReleasedEvent, (Action<OccupiableSpawnPoint>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<OccupiableSpawnPoint> action = this.m_AutomaticallyReleasedEvent;
			Action<OccupiableSpawnPoint> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_AutomaticallyReleasedEvent, (Action<OccupiableSpawnPoint>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Update()
	{
		if (!Occupied || !automaticallyRelease)
		{
			return;
		}
		Vector3 position = base.transform.TransformPoint(sphereCheckCenter);
		if (!Physics.CheckSphere(position, sphereCheckRadius, 495330304, QueryTriggerInteraction.Ignore))
		{
			if (this.AutomaticallyReleasedEvent != null)
			{
				this.AutomaticallyReleasedEvent(this);
			}
			Release();
		}
	}

	public void Occupy()
	{
		Occupied = true;
	}

	public void Release()
	{
		Occupied = false;
	}

	private void OnDrawGizmos()
	{
		if (automaticallyRelease)
		{
			Gizmos.color = ((!Occupied) ? Color.green : Color.red);
			Gizmos.DrawWireSphere(base.transform.TransformPoint(sphereCheckCenter), sphereCheckRadius);
		}
	}
}
[DisallowMultipleComponent]
public class RecRoomSceneManager : Photon.MonoBehaviour, IPersistableSettings
{
	public delegate void LevelRoomAction();

	[Serializable]
	public enum SceneCategory
	{
		None,
		Paintball,
		DiscGolf
	}

	[SerializeField]
	private string friendlyName;

	[SerializeField]
	private PlayerHand.WorldCollisionMode playerHandConcaveMeshCollisionMode;

	[Header("Scene Settings")]
	[SerializeField]
	private SceneAFKSettings afkSettings;

	[SerializeField]
	private SceneAudioSettings audioSettings;

	[SerializeField]
	private SceneInteractionSettings interactionSettings;

	[SerializeField]
	private ScenePhysicsSettings physicsSettings;

	[SerializeField]
	private SceneGeometrySettings geometrySettings;

	[SerializeField]
	private SceneMoodSettings sceneMoodSettings;

	[SerializeField]
	private SceneRenderingSettings sceneRenderingSettings;

	[SerializeField]
	private SceneSpawnManager spawnManager;

	[SerializeField]
	private ScenePresenceSettings presenceSettings;

	[SerializeField]
	private SceneEquipmentManager equipmentManager;

	[Header("Scene Role")]
	[Comment("These overrides are for *Room* specific overrides. For games, use the GameRuleManager In-Game role.")]
	[SerializeField]
	[FormerlySerializedAs("sceneEveryoneRole")]
	private OverridableGameRole sceneEveryoneGameRole = new OverridableGameRole();

	[SerializeField]
	private OverridableRoomRole sceneEveryoneRoomRole = new OverridableRoomRole();

	[Header("Analytics")]
	[SerializeField]
	private SceneCategory category;

	private List<IRecRoomSceneComponent> recRoomSceneComponents = new List<IRecRoomSceneComponent>();

	private int messageQueuePauseCounter;

	private bool sceneDataLoaded;

	private bool instanceInitializationDeferred;

	protected bool wasMasterClient;

	private static bool staticInitializationDeferred;

	private bool isApplicationQuitting;

	public static LevelRoomAction LevelRoomLoadedEvent;

	public SceneAFKSettings AFKSettings => afkSettings;

	public SceneAudioSettings AudioSettings => audioSettings;

	public SceneInteractionSettings InteractionSettings => interactionSettings;

	public ScenePhysicsSettings PhysicsSettings => physicsSettings;

	public SceneGeometrySettings GeometrySettings => geometrySettings;

	public SceneMoodSettings SceneMoodSettings => sceneMoodSettings;

	public SceneRenderingSettings SceneRenderingSettings => sceneRenderingSettings;

	public SceneSpawnManager SpawnManager => spawnManager;

	public ScenePresenceSettings PresenceSettings => presenceSettings;

	public SceneEquipmentManager EquipmentManager => equipmentManager;

	public bool PersistentRoomLoadingFinished { get; private set; }

	public static SceneCategory Category => (Instance != null) ? Instance.category : SceneCategory.None;

	public static string CurrentSceneFriendlyName => (!(Instance != null) || string.IsNullOrEmpty(Instance.friendlyName)) ? CurrentSceneName : Instance.friendlyName;

	public static string CurrentSceneName => SceneManagerHelper.ActiveSceneName;

	public static bool IsCurrentSceneAValidActivity => Instance != null;

	private bool InstanceInitialized => sceneDataLoaded && !instanceInitializationDeferred;

	public static bool HasRunningGame => NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning;

	public static RecRoomSceneManager Instance { get; private set; }

	public static bool IsInitialized => Instance != null && Instance.InstanceInitialized;

	public virtual bool SpawnPlayersInRoom => true;

	protected virtual bool UseSplashScreenControls => false;

	public static void DeferInitialization()
	{
		if (Instance != null)
		{
			Instance.instanceInitializationDeferred = true;
		}
		else
		{
			staticInitializationDeferred = true;
		}
	}

	public static void FinishInitialization()
	{
		if (Instance != null)
		{
			Instance.instanceInitializationDeferred = false;
		}
		else
		{
			staticInitializationDeferred = false;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (sceneEveryoneGameRole.Overrides)
		{
			PlayerGameRoleManager.Instance.AddEveryoneRoleDefinition(sceneEveryoneGameRole.Value, this, RoleMapPriority.SceneManager);
		}
		if (sceneEveryoneRoomRole.Overrides)
		{
			PlayerRoomRoleManager.Instance.AddEveryoneRoleDefinition(sceneEveryoneRoomRole.Value, this, RoleMapPriority.SceneManager);
		}
		PersistentRoomLoadingFinished = false;
		UnityEngine.Application.backgroundLoadingPriority = ThreadPriority.Low;
		LoadRequiredSubScenes();
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
		if (Instance == null)
		{
			Instance = this;
			if (staticInitializationDeferred)
			{
				Instance.instanceInitializationDeferred = staticInitializationDeferred;
				staticInitializationDeferred = false;
			}
		}
		recRoomSceneComponents.Add(AFKSettings);
		recRoomSceneComponents.Add(AudioSettings);
		recRoomSceneComponents.Add(InteractionSettings);
		recRoomSceneComponents.Add(PhysicsSettings);
		recRoomSceneComponents.Add(GeometrySettings);
		recRoomSceneComponents.Add(SceneMoodSettings);
		recRoomSceneComponents.Add(SceneRenderingSettings);
		recRoomSceneComponents.Add(PresenceSettings);
		recRoomSceneComponents.Add(SpawnManager);
		recRoomSceneComponents.Add(EquipmentManager);
		EnvironmentLightingSettings.CopyDefaultSettingsFromScene();
		RecRoom.Core.Rendering.FogSettings.CopyDefaultSettingsFromScene();
		RenderFogSettings.CreateDefaultSettingsFromScene();
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].OnAwake(this);
		}
		RegisterPlayerSpawnCallback();
	}

	protected virtual IEnumerator Start()
	{
		sceneDataLoaded = true;
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].OnStart();
		}
		if (UseSplashScreenControls)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.EnterSplashScreenState();
		}
		else
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.EnterGameplayState();
		}
		wasMasterClient = PhotonNetwork.isMasterClient;
		yield return StartCoroutine(LoadPersistentRoomAndPlayers());
	}

	protected IEnumerator LoadPersistentRoomAndPlayers()
	{
		yield return StartCoroutine(WaitForPersistedRoomDataToLoad());
		MasterSpawnAllPlayers();
	}

	protected IEnumerator WaitForPersistedRoomDataToLoad()
	{
		if (NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)
		{
			bool loadRoomSuccess = false;
			string loadRoomError = string.Empty;
			yield return StartCoroutine(NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.WaitForInitialLoad(delegate(bool success, string error)
			{
				loadRoomSuccess = success;
				loadRoomError = error;
			}));
			if (!loadRoomSuccess)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom((!string.IsNullOrEmpty(loadRoomError)) ? loadRoomError : "Failed to load room.", SessionManager.LoadSceneSources.PERSISTENCE_ERROR);
				yield break;
			}
		}
		PersistentRoomLoadingFinished = true;
	}

	private void RegisterPlayerSpawnCallback()
	{
		if (Player.LocalPlayerExists)
		{
			OnLocalPlayerSpawn();
		}
		else
		{
			Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerSpawn);
		}
	}

	private void MasterSpawnAllPlayers()
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			if (PhotonNetwork.playerList[i].ToPlayer() == null)
			{
				SpawnManager.MasterSpawnNewPlayer(PhotonNetwork.playerList[i]);
			}
		}
	}

	private void OnApplicationQuit()
	{
		isApplicationQuitting = true;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		ResumeNetworkMessageQueueOnDestroy();
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].OnDestroy();
		}
		if (!isApplicationQuitting)
		{
			PhotonNetwork.player.SetCustomProperties("prev_activity", CurrentSceneName);
			long roomId = GameSessions.LocalGameSession.RoomId;
			PhotonNetwork.player.SetCustomProperties("prev_room", roomId);
		}
		StopAllCoroutines();
		if (Instance == this)
		{
			Instance = null;
		}
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.OnRecRoomSceneManagerDestroyed();
		}
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		if (PlayerGameRoleManager.Instance != null)
		{
			PlayerGameRoleManager.Instance.RemoveEveryoneRoleDefinition(this);
		}
	}

	protected virtual void Update()
	{
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].Update();
		}
	}

	public int GetLevelRoomCount()
	{
		return AGRoomSettings.GetRoomSceneLocationSubSceneCount(GameSessions.LocalGameSession.Location);
	}

	public void LoadLevelRoomAsync(int roomIndex, Action<int, GameObject[]> callback = null)
	{
		string roomSceneLocationSubSceneAtIndex = AGRoomSettings.GetRoomSceneLocationSubSceneAtIndex(GameSessions.LocalGameSession.Location, roomIndex);
		if (string.IsNullOrEmpty(roomSceneLocationSubSceneAtIndex))
		{
			callback?.Invoke(roomIndex, null);
		}
		else
		{
			StartCoroutine(LoadLevelRoomAsyncCoroutine(roomSceneLocationSubSceneAtIndex, roomIndex, callback));
		}
	}

	public void UnloadLevelRoomAsync(int roomIndex)
	{
		string roomSceneLocationSubSceneAtIndex = AGRoomSettings.GetRoomSceneLocationSubSceneAtIndex(GameSessions.LocalGameSession.Location, roomIndex);
		if (!string.IsNullOrEmpty(roomSceneLocationSubSceneAtIndex))
		{
			Scene sceneByName = SceneManager.GetSceneByName(roomSceneLocationSubSceneAtIndex);
			if (sceneByName.IsValid())
			{
				SceneManager.UnloadSceneAsync(sceneByName);
			}
		}
	}

	private void LoadRequiredSubScenes()
	{
		string[] requiredSubSceneNamesFromRoomSceneLocation = AGRoomSettings.GetRequiredSubSceneNamesFromRoomSceneLocation(GameSessions.LocalGameSession.Location);
		if (requiredSubSceneNamesFromRoomSceneLocation != null)
		{
			for (int i = 0; i < requiredSubSceneNamesFromRoomSceneLocation.Length; i++)
			{
				SceneManager.LoadScene(requiredSubSceneNamesFromRoomSceneLocation[i], LoadSceneMode.Additive);
			}
		}
	}

	private IEnumerator LoadLevelRoomAsyncCoroutine(string roomSceneName, int roomIndex, Action<int, GameObject[]> callback)
	{
		TryPauseNetworkMessageQueue();
		UnityEngine.AsyncOperation asyncLoad = SceneManager.LoadSceneAsync(roomSceneName, LoadSceneMode.Additive);
		while (!asyncLoad.isDone)
		{
			yield return null;
		}
		yield return null;
		Scene roomScene = SceneManager.GetSceneAt(SceneManager.sceneCount - 1);
		GameObject[] roomRoots = ((!roomScene.IsValid()) ? null : roomScene.GetRootGameObjects());
		TryResumeNetworkMessageQueue();
		callback?.Invoke(roomIndex, roomRoots);
		if (LevelRoomLoadedEvent != null)
		{
			LevelRoomLoadedEvent();
		}
	}

	private void TryPauseNetworkMessageQueue()
	{
		NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.PauseMessageQueue();
		messageQueuePauseCounter++;
	}

	private void TryResumeNetworkMessageQueue()
	{
		if (messageQueuePauseCounter > 0)
		{
			messageQueuePauseCounter--;
			NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.ResumeMessageQueue();
		}
	}

	private void ResumeNetworkMessageQueueOnDestroy()
	{
		while (messageQueuePauseCounter > 0)
		{
			TryResumeNetworkMessageQueue();
		}
	}

	private void OnLocalPlayerSpawn()
	{
		Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerSpawn);
		PlayerHand.ConcaveMeshWorldCollisionMode = playerHandConcaveMeshCollisionMode;
		for (int i = 0; i < recRoomSceneComponents.Count; i++)
		{
			recRoomSceneComponents[i].SetLocalPlayerSettings();
		}
	}

