	public void RpcSpawnNewPlayer(Vector3 spawnPosition, Quaternion spawnRotation)
	{
		SpawnManager.SpawnNewPlayer(spawnPosition, spawnRotation);
	}

	[PunRPC]
	public void RpcMasterRequestPlayerRespawn(bool dropTools, PhotonMessageInfo messageInfo)
	{
		SpawnManager.MasterRespawnPlayer(messageInfo.sender, dropTools);
	}

	[PunRPC]
	public void RpcRespawnPlayer(Vector3 spawnPosition, Quaternion spawnRotation, PhotonView spawnParent, bool dropTools)
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.Respawn(spawnPosition, spawnRotation, spawnParent, dropTools);
