	public void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient && PersistentRoomLoadingFinished && !newPlayer.IsRecNetBot)
		{
			SpawnManager.MasterSpawnNewPlayer(newPlayer);
		}
	}

	public virtual void OnMasterClientSwitched(PhotonPlayer newMasterClient)
	{
		if (!PhotonNetwork.isMasterClient && wasMasterClient)
		{
			StopAllCoroutines();
			wasMasterClient = false;
		}
		else if (PhotonNetwork.isMasterClient)
		{
			wasMasterClient = true;
			StartCoroutine(LoadPersistentRoomAndPlayers());
		}
	}

	public void DeserializeFrom(PersistedRoomData roomData)
	{
		SceneSettingsData sceneSettingsData = roomData.SceneSettingsData;
		if (sceneSettingsData != null)
		{
			if (sceneSettingsData.MoodId != null && !sceneSettingsData.MoodId.IsEmpty)
			{
				SceneMoodSettings.SetCurrentMoodByGuid(RecRoom.Protobuf.ByteStringExtensions.ToGuid(sceneSettingsData.MoodId));
			}
			GeometrySettings.MovementBlockersEnabled = !sceneSettingsData.MovementBlockersDisabled;
		}
	}

	public void SerializeTo(ref PersistedRoomData roomData)
	{
		if (roomData.SceneSettingsData != null)
		{
			UnityEngine.Debug.LogError("Error serializing SceneSettings in room data: Data already specified.");
			return;
		}
		roomData.SceneSettingsData = new SceneSettingsData();
		if (sceneMoodSettings.RoomMoodsEnabled)
		{
			roomData.SceneSettingsData.MoodId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(SceneMoodSettings.CurrentMood.Guid);
		}
		roomData.SceneSettingsData.MovementBlockersDisabled = !GeometrySettings.MovementBlockersEnabled;
	}
}
