[Serializable]
public class SceneAudioSettings : IRecRoomSceneComponent
{
	[Header("Custom Rolloff")]
	[SerializeField]
	private bool hasCustomPlayerVoiceRolloff;

	[SerializeField]
	private AudioRolloff customPlayerVoiceRolloff;

	[SerializeField]
	private bool hasCustom3DSFXRolloff;

	[SerializeField]
	private AudioRolloff custom3DSFXRolloff;

	[Header("Custom Teleport Sounds")]
	[SerializeField]
	private RecRoomAudioClip[] customTeleportSounds;

	[Header("Custom Walk Sounds")]
	[SerializeField]
	private bool hasCustomWalkSounds;

	[SerializeField]
	private RecRoomAudioClip[] customWalkSounds;

	[Header("Music")]
	[SerializeField]
	private RecRoomAudioClip ambientAudio;

	[SerializeField]
	private RecRoomAudioClip loadingGameMusic;

	[SerializeField]
	private RecRoomAudioClip gameplayMusic;

	[SerializeField]
	private ExtendedRecRoomAudioClips actionMusic;

	[SerializeField]
	private RecRoomAudioClip fanfareMusic;

	public bool HasCustomPlayerVoiceRolloff => hasCustomPlayerVoiceRolloff;

	public AudioRolloff CustomPlayerVoiceRolloff => customPlayerVoiceRolloff;

	public void OnAwake(RecRoomSceneManager sceneManager)
	{
		if (hasCustomPlayerVoiceRolloff)
		{
			AudioManager.AddGlobalPlayerVoiceRolloff(customPlayerVoiceRolloff, this);
		}
		if (hasCustom3DSFXRolloff)
		{
			AudioManager.Add3DSFXRolloff(custom3DSFXRolloff, this);
		}
		PlayerAudio.CustomTeleportSounds = customTeleportSounds;
		if (hasCustomWalkSounds)
		{
			PlayerAudio.CustomWalkFootstepSounds = customWalkSounds;
		}
		else
		{
			PlayerAudio.CustomWalkFootstepSounds = null;
		}
		AudioManager.AddAmbientAudio(ambientAudio, this);
		AudioManager.PlayAmbientAudio();
		AudioManager.MusicMixer.AddLoadingMusic(loadingGameMusic, this);
		AudioManager.MusicMixer.AddGameplayMusic(gameplayMusic, this);
		AudioManager.MusicMixer.AddActionMusic(actionMusic, this);
		AudioManager.MusicMixer.AddFanfareMusic(fanfareMusic, this);
	}

	public void OnDestroy()
	{
		if (hasCustomPlayerVoiceRolloff)
		{
			AudioManager.RemoveGlobalPlayerVoiceRolloff(this);
		}
		if (hasCustom3DSFXRolloff)
		{
			AudioManager.Remove3DSFXRolloff(this);
		}
		AudioManager.StopAmbientAudio();
		AudioManager.RemoveAmbientAudio(this);
		if (AudioManager.MusicMixer != null)
		{
			AudioManager.MusicMixer.RemoveLoadingMusic(this);
			AudioManager.MusicMixer.RemoveGameplayMusic(this);
			AudioManager.MusicMixer.RemoveActionMusic(this);
			AudioManager.MusicMixer.RemoveFanfareMusic(this);
		}
	}

	public void OnStart()
	{
	}

	public void Update()
	{
	}

	public void SetLocalPlayerSettings()
	{
	}
}
namespace RecRoom.Core.Scene
{
	[Serializable]
	public class SceneEquipmentManager : IRecRoomSceneComponent
	{
		private GamePracticeObject[] practiceObjects;

		public List<SpawnableTool> SceneEquipment { get; private set; }

		public void OnAwake(RecRoomSceneManager sceneManager)
		{
			practiceObjects = UnityEngine.Object.FindObjectsOfType<GamePracticeObject>();
			if (GameManager.IsSandboxActive)
			{
				GamePracticeObject[] array = practiceObjects;
				foreach (GamePracticeObject gamePracticeObject in array)
				{
					UnityEngine.Object.Destroy(gamePracticeObject.gameObject);
				}
				practiceObjects = null;
			}
			SceneEquipment = new List<SpawnableTool>();
			if (GameSessions.LocalGameSession.IsSandbox)
			{
				return;
			}
			SpawnableTool[] array2 = UnityEngine.Object.FindObjectsOfType<SpawnableTool>();
			foreach (SpawnableTool spawnableTool in array2)
			{
				if (spawnableTool.GetComponent<GamePracticeObject>() == null)
				{
					SceneEquipment.Add(spawnableTool);
				}
			}
		}

		public void OnStart()
		{
		}

		public void OnDestroy()
		{
		}

		public void Update()
		{
		}

		public void SetLocalPlayerSettings()
		{
		}

		public void EnableActivityObjects(bool enabled, IList<SpawnableTool> ignoreEquipment, bool runReset)
		{
			foreach (SpawnableTool item in SceneEquipment)
			{
				if (item != null && (ignoreEquipment == null || !ignoreEquipment.Contains(item)))
				{
					item.Enable(enabled);
					if (enabled && runReset && PhotonNetwork.isMasterClient)
					{
						item.Tool.MasterResetToLastSpawnPosition();
					}
				}
			}
		}

		public void SetActivityObjectLocalPlayerToolRestrictions(bool pickupEnabled)
		{
			for (int i = 0; i < SceneEquipment.Count; i++)
			{
				if (SceneEquipment[i] != null && SceneEquipment[i].Tool != null)
				{
					SceneEquipment[i].Tool.SetPickupEnabled(pickupEnabled, this);
				}
			}
		}

		public void EnablePracticeObjects(bool enabled)
		{
			if (practiceObjects == null)
			{
				return;
			}
			for (int i = 0; i < practiceObjects.Length; i++)
			{
				if (practiceObjects[i] != null)
				{
					practiceObjects[i].SetActive(enabled);
				}
			}
		}

		public void PlayPracticeObjectAttentionEffects()
		{
			if (practiceObjects == null)
			{
				return;
			}
			for (int i = 0; i < practiceObjects.Length; i++)
			{
				if (practiceObjects[i] != null && practiceObjects[i].PlayAttractEffect)
				{
					AudioManager.Play3DSFX(DefaultAudioSettings.ConfigAsset.AttentionPingSFX, practiceObjects[i].transform.position);
				}
			}
		}
	}
