namespace RecRoom.Core.Scene
{
	[Serializable]
	public class SceneMoodSettings : IRecRoomSceneComponent
	{
		[SerializeField]
		private MoodSetting[] availableMoods;

		[SerializeField]
		private MoodSetting defaultMood;

		[SerializeField]
		private PostProcessVolume postProcessVolume;

		private PostProcessProfile defaultPostProcessProfile;

		[SerializeField]
		private ReflectionProbe[] reflectionProbes;

		private Transform _sceneGeneratedRoot;

		private SynchronizedField<int> _currentRoomMoodIndex;

		public bool RoomMoodsEnabled => defaultMood != null;

		private Transform SceneGeneratedRoot
		{
			get
			{
				if (_sceneGeneratedRoot == null)
				{
					_sceneGeneratedRoot = new GameObject("SceneGenerated").transform;
					_sceneGeneratedRoot.gameObject.hideFlags = HideFlags.DontSaveInEditor;
				}
				return _sceneGeneratedRoot;
			}
		}

		public MoodSetting CurrentMood
		{
			get
			{
				if (CurrentRoomMoodIndex >= 0)
				{
					return availableMoods[CurrentRoomMoodIndex];
				}
				return defaultMood;
			}
		}

		public int CurrentRoomMoodIndex
		{
			get
			{
				return _currentRoomMoodIndex.Get();
			}
			set
			{
				_currentRoomMoodIndex.Set(value);
			}
		}

		public void OnAwake(RecRoomSceneManager sceneManager)
		{
			_currentRoomMoodIndex = new SynchronizedField<int>(sceneManager, "CRMID", -1, SetterPermissionMode.ANYONE, OnCurrentRoomMoodIdChange);
		}

		public void OnStart()
		{
			if (!postProcessVolume)
			{
				UnityEngine.Debug.LogWarning("Missing PostProcessVolume");
			}
			else
			{
				defaultPostProcessProfile = postProcessVolume.sharedProfile;
			}
			if (defaultMood != null)
			{
				if (CurrentRoomMoodIndex < 0 && PhotonNetwork.isMasterClient)
				{
					SetCurrentMoodByGuid(defaultMood.Guid);
				}
				OnCurrentRoomMoodIdChange();
			}
		}

		public void SetCurrentMoodByGuid(Guid guid)
		{
			for (int i = 0; i < availableMoods.Length; i++)
			{
				if (guid == availableMoods[i].Guid)
				{
					CurrentRoomMoodIndex = i;
				}
			}
		}

		private void OnCurrentRoomMoodIdChange()
		{
			SetupMood(CurrentMood);
		}

		public void MoveForward()
		{
			CurrentRoomMoodIndex = (CurrentRoomMoodIndex + 1) % availableMoods.Length;
		}

		public void MoveBackward()
		{
			int num = availableMoods.Length + (CurrentRoomMoodIndex - 1);
			CurrentRoomMoodIndex = num % availableMoods.Length;
		}

		public void SetupMood(MoodSetting mood)
		{
			CleanupOldMoodObjects();
			if (mood != null)
			{
				if (mood.SkyboxMaterial != null)
				{
					RenderSettings.skybox = mood.SkyboxMaterial;
				}
				if ((bool)mood.PostProcessProfile && (bool)postProcessVolume)
				{
					postProcessVolume.sharedProfile = mood.PostProcessProfile;
				}
				if (RenderSettings.sun == null)
				{
					UnityEngine.Debug.LogError("Sun Source reference has not been set in Lighting settings. Please set this reference to apply directional light settings from scene mood.");
				}
				else
				{
					ApplyLightSettings(mood.SunSourceSettings);
				}
				ApplyEnvironmentLightingSettings(mood);
				ApplyFogSettings(mood.FogSettings);
				MoodObjectGroup[] moodBackdropGroups = mood.MoodBackdropGroups;
				foreach (MoodObjectGroup objectData in moodBackdropGroups)
				{
					InstantiateMoodObject(objectData);
				}
				ReflectionProbe[] array = reflectionProbes;
				foreach (ReflectionProbe reflectionProbe in array)
				{
					reflectionProbe.RenderProbe();
				}
			}
			else if ((bool)postProcessVolume)
			{
				postProcessVolume.sharedProfile = defaultPostProcessProfile;
			}
		}

		private void CleanupOldMoodObjects()
		{
			if ((bool)postProcessVolume)
			{
				postProcessVolume.sharedProfile = defaultPostProcessProfile;
			}
			else
			{
				UnityEngine.Debug.LogWarning("No Postprocessing Volume found in this scene");
			}
			if (!UnityEngine.Application.isPlaying)
			{
				return;
			}
			foreach (Transform item in SceneGeneratedRoot)
			{
				SafeDestroy.GameObject(item.gameObject);
			}
		}

		private void ApplyLightSettings(SunSettings settings)
		{
			if (settings.localPosition.Overrides)
			{
				RenderSettings.sun.transform.localPosition = settings.localPosition.Value;
			}
			if (settings.localRotation.Overrides)
			{
				RenderSettings.sun.transform.localEulerAngles = settings.localRotation.Value;
			}
			if (settings.localScale.Overrides)
			{
				RenderSettings.sun.transform.localScale = settings.localScale.Value;
			}
			if (settings.color.Overrides)
			{
				RenderSettings.sun.color = settings.color.Value;
			}
			if (settings.indirectMultiplier.Overrides)
			{
				RenderSettings.sun.bounceIntensity = settings.indirectMultiplier.Value;
			}
			if (settings.lightIntensity.Overrides)
			{
				RenderSettings.sun.intensity = settings.lightIntensity.Value;
			}
			if (settings.shadowStrength.Overrides)
			{
				RenderSettings.sun.shadowStrength = settings.shadowStrength.Value;
			}
		}

		private void ApplyEnvironmentLightingSettings(MoodSetting settings)
		{
			if (settings.UseGradientEnvironmentLighting.Overrides)
			{
				if (settings.UseGradientEnvironmentLighting.Value)
				{
					RenderSettings.ambientMode = AmbientMode.Trilight;
				}
				else
				{
					RenderSettings.ambientMode = AmbientMode.Skybox;
				}
			}
			if (settings.GradientSkyColor.Overrides)
			{
				RenderSettings.ambientSkyColor = settings.GradientSkyColor.Value;
			}
			if (settings.GradientEquatorColor.Overrides)
			{
				RenderSettings.ambientEquatorColor = settings.GradientEquatorColor.Value;
			}
			if (settings.GradientGroundColor.Overrides)
			{
				RenderSettings.ambientGroundColor = settings.GradientGroundColor.Value;
			}
		}

		private void ApplyFogSettings(RecRoom.Core.Creation.SceneMoods.FogSettings settings)
		{
			if (settings.fogEnabled.Overrides)
			{
				RenderSettings.fog = settings.fogEnabled.Value;
			}
			if (settings.fogStartDistance.Overrides)
			{
				RenderSettings.fogStartDistance = settings.fogStartDistance.Value;
			}
			if (settings.fogEndDistance.Overrides)
			{
				RenderSettings.fogEndDistance = settings.fogEndDistance.Value;
			}
			if (settings.fogColor.Overrides)
			{
				RenderSettings.fogColor = settings.fogColor.Value;
			}
		}

		private GameObject InstantiateMoodObject(MoodObjectGroup objectData)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(objectData.rootObject);
			if (objectData.worldPosition.Overrides)
			{
				gameObject.transform.position = objectData.worldPosition.Value;
			}
			if (objectData.worldRotation.Overrides)
			{
				gameObject.transform.eulerAngles = objectData.worldRotation.Value;
			}
			if (objectData.scale.Overrides)
			{
				gameObject.transform.localScale = objectData.scale.Value;
			}
			gameObject.transform.parent = SceneGeneratedRoot;
			return gameObject;
		}

		public void OnDestroy()
		{
