	{
		[Serializable]
		public sealed class PhysicsLODSettings
		{
			[SerializeField]
			private float UnderTwoPointFiveMeterUpdateRate = -1f;

			[SerializeField]
			private float UnderFiveMeterUpdateRate = -1f;

			[SerializeField]
			private float UnderTenMeterUpdateRate = 60f;

			[SerializeField]
			private float UnderTwentyMeterUpdateRate = 30f;

			[SerializeField]
			private float UnderFiftyMeterUpdateRate = 10f;

			[SerializeField]
			private float UnderHundredMeterUpdateRate = 2f;

			[SerializeField]
			private float UnderFiveHundredMeterUpdateRate = 0.25f;

			[SerializeField]
			private float GreaterThanFiveHundredMeterUpdateRate = 0.01f;

			private Dictionary<UpdateLOD, float> updateRates;

			public static readonly PhysicsLODSettings DefaultPhysicsSettings = new PhysicsLODSettings();

			public float GetUpdateRate(UpdateLOD updateLod)
			{
				if (updateRates == null)
				{
					InitializeUpdateRates();
				}
				if (updateRates.TryGetValue(updateLod, out var value))
				{
					return value;
				}
				throw new InvalidOperationException($"Unknown update LOD {updateLod}!");
			}

			private void InitializeUpdateRates()
			{
				updateRates = new Dictionary<UpdateLOD, float>
				{
					{
						UpdateLOD.TwoPointFiveMeters,
						UnderTwoPointFiveMeterUpdateRate
					},
					{
						UpdateLOD.FiveMeters,
						UnderFiveMeterUpdateRate
					},
					{
						UpdateLOD.TenMeters,
						UnderTenMeterUpdateRate
					},
					{
						UpdateLOD.TwentyMeters,
						UnderTwentyMeterUpdateRate
					},
					{
						UpdateLOD.FiftyMeters,
						UnderFiftyMeterUpdateRate
					},
					{
						UpdateLOD.HundredMeters,
						UnderHundredMeterUpdateRate
					},
					{
						UpdateLOD.FiveHundredMeters,
						UnderFiveHundredMeterUpdateRate
					},
					{
						UpdateLOD.GreaterThanFiveHundredMeters,
						GreaterThanFiveHundredMeterUpdateRate
					}
				};
			}
		}

