namespace RecRoom
{
	[Serializable]
	public class SceneRenderingSettings : IRecRoomSceneComponent
	{
		private struct CameraSettings
		{
			public Camera camera;

			public float? initialClip;

			public bool? initialAllowMSAA;
		}

		[SerializeField]
		private bool overrideFarClip;

		[SerializeField]
		private float farClip = 1000f;

		[SerializeField]
		private bool overrideShadowDistance;

		[SerializeField]
		private float shadowDistance = 300f;

		private float? initialShadowDistance;

		[SerializeField]
		private bool overrideAllowMSAA;

		[SerializeField]
		private bool allowMSAA;

		[SerializeField]
		private PostProcessVolume[] ssfxVolumes;

		private List<CameraSettings> cameraSettings = new List<CameraSettings>();

		public void OnAwake(RecRoomSceneManager sceneManager)
		{
			if (overrideShadowDistance)
			{
				initialShadowDistance = QualitySettings.shadowDistance;
				QualitySettings.shadowDistance = shadowDistance;
			}
			if (SingletonMonoBehaviour<CameraRig>.IsInitialized)
			{
				if (SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera != null)
				{
					ApplySceneCameraOverrides(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera);
				}
				if (SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera != null)
				{
					ApplySceneCameraOverrides(SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera);
				}
			}
		}

		public void OnStart()
		{
		}

		public void OnDestroy()
		{
			if (initialShadowDistance.HasValue)
			{
				QualitySettings.shadowDistance = initialShadowDistance.Value;
			}
			foreach (CameraSettings cameraSetting in cameraSettings)
			{
				if (cameraSetting.camera != null)
				{
					if (cameraSetting.initialClip.HasValue)
					{
						cameraSetting.camera.farClipPlane = cameraSetting.initialClip.Value;
					}
					if (cameraSetting.initialAllowMSAA.HasValue)
					{
						cameraSetting.camera.allowMSAA = cameraSetting.initialAllowMSAA.Value;
					}
				}
			}
		}

		public void Update()
		{
		}

		public void SetLocalPlayerSettings()
		{
		}

		public void ApplySceneCameraOverrides(Camera camera)
		{
			if (camera != null)
			{
				CameraSettings item = new CameraSettings
				{
					camera = camera
				};
				if (overrideFarClip)
				{
					item.initialClip = camera.farClipPlane;
					camera.farClipPlane = farClip;
				}
				if (overrideAllowMSAA)
				{
					item.initialAllowMSAA = camera.allowMSAA;
					camera.allowMSAA = allowMSAA;
				}
				cameraSettings.Add(item);
			}
		}
	}
}
[Serializable]
public class SceneSpawnManager : IRecRoomSceneComponent
{
	private struct SpawnPointBlockedData
	{
		public class DataComparer : IComparer<SpawnPointBlockedData>
		{
			public int Compare(SpawnPointBlockedData a, SpawnPointBlockedData b)
			{
				if (a.isBlocked != b.isBlocked)
				{
					return a.isBlocked.CompareTo(b.isBlocked);
				}
				return SceneSpawnPoint.Comparer.Compare(a.spawnPoint, b.spawnPoint);
			}
		}

		public static DataComparer Comparer = new DataComparer();

		public SceneSpawnPoint spawnPoint;

		public bool isBlocked;
	}

	private RecRoomSceneManager sceneManager;

	private SceneSpawnPoint[] sceneSpawnPoints;

	private List<SceneSpawnPoint> spawnPointOverrides = new List<SceneSpawnPoint>();

	private List<SpawnPointBlockedData> filteredSpawnPoints = new List<SpawnPointBlockedData>();

	private Coroutine spawnNewPlayerCoroutine;

	public const string PREVIOUSACTIVITY_PROPERTY = "prev_activity";

	public const string PREVIOUSROOM_PROPERTY = "prev_room";

	public void OnAwake(RecRoomSceneManager sceneManager)
	{
		this.sceneManager = sceneManager;
		PhotonNetwork.OnLeftRoom += new Action(OnLeftPhotonRoom);
	}

	public void OnStart()
	{
		sceneSpawnPoints = UnityEngine.Object.FindObjectsOfType<SceneSpawnPoint>();
	}

	public void OnDestroy()
	{
		PhotonNetwork.OnLeftRoom -= new Action(OnLeftPhotonRoom);
	}

	public void Update()
	{
	}

	public void SetLocalPlayerSettings()
	{
	}

	public void MasterSpawnNewPlayer(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient && RecRoomSceneManager.Instance.SpawnPlayersInRoom)
		{
			long customProperty = newPlayer.GetCustomProperty<long>("prev_room");
			SpawnPoint spawnPoint = MasterGetLeastRecentlyUsedSpawnPoint(customProperty);
			if (spawnPoint == null)
			{
				UnityEngine.Debug.LogError("Could not spawn player because a spawn point could not be acquired.");
				return;
			}
			spawnPoint.MasterUse();
			spawnPoint.GetFirstAvailableSpawnTransform(out var localPosition, out var localRotation);
			sceneManager.photonView.RpcPlayer(newPlayer, sceneManager.RpcSpawnNewPlayer, localPosition, localRotation);
		}
	}

	public void SpawnNewPlayer(Vector3 position, Quaternion rotation)
	{
		CancelPendingSpawn();
		spawnNewPlayerCoroutine = sceneManager.StartCoroutine(SpawnNewPlayerCoroutine(position, rotation));
	}

	public void LocalPlayerRequestRespawn(bool dropTools)
	{
		sceneManager.photonView.RpcMaster(sceneManager.RpcMasterRequestPlayerRespawn, dropTools);
	}

	public void MasterRespawnPlayer(PhotonPlayer player, bool dropTools)
	{
		if (PhotonNetwork.isMasterClient && player != null)
		{
			SpawnPoint spawnPoint = MasterGetLeastRecentlyUsedSpawnPoint(0L);
			if (spawnPoint == null)
			{
				UnityEngine.Debug.LogError("Spawn Point is null.  Cannot spawn player " + player.NickName);
				return;
			}
			spawnPoint.MasterUse();
			spawnPoint.GetFirstAvailableSpawnTransform(out var localPosition, out var localRotation);
			sceneManager.photonView.RpcPlayer(player, sceneManager.RpcRespawnPlayer, localPosition, localRotation, spawnPoint.Parent, dropTools);
		}
	}

	private unsafe IEnumerator SpawnNewPlayerCoroutine(Vector3 position, Quaternion rotation)
	{
		yield return new WaitUntil(new Func<bool>(null, (nint)(delegate*<bool>)(&ShapeManager.get_AllShapeContainersInitialized)));
		SingletonMonoBehaviour<LocalPlayerController>.Instance.InstantiateLocalPlayer(position, rotation);
		while (SingletonMonoBehaviour<CameraFade>.Instance.IsFading)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1.5f);
		if (!SingletonMonoBehaviour<TutorialManager>.Instance.SuppressActivityNameNotification)
		{
			AudioManager.Play2DSFX(DefaultAudioSettings.ConfigAsset.ActivityTitleJingleSFX);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, string.Format("{0}{1}", GameSessions.LocalGameSession.Name, (!GameSessions.LocalGameSession.Private) ? string.Empty : " [PRIVATE]"), 3f);
		}
	}

	private void CancelPendingSpawn()
	{
		if (spawnNewPlayerCoroutine != null)
		{
			sceneManager.StopCoroutine(spawnNewPlayerCoroutine);
			spawnNewPlayerCoroutine = null;
		}
	}

	private void OnLeftPhotonRoom()
	{
		CancelPendingSpawn();
	}

	public void AddSpawnPointOverride(SceneSpawnPoint spawnPoint)
	{
		bool flag = spawnPointOverrides.Count == 0;
		spawnPointOverrides.Add(spawnPoint);
		if (flag && spawnPointOverrides.Count > 0)
		{
			SceneSpawnPoint[] array = sceneSpawnPoints;
			foreach (SceneSpawnPoint sceneSpawnPoint in array)
			{
				sceneSpawnPoint.SpawnPointEnabled = false;
			}
		}
	}

	public void RemoveSpawnPointOverride(SceneSpawnPoint spawnPoint)
	{
		bool flag = spawnPointOverrides.Count > 0;
		spawnPointOverrides.Remove(spawnPoint);
		if (flag && spawnPointOverrides.Count == 0)
		{
			SceneSpawnPoint[] array = sceneSpawnPoints;
			foreach (SceneSpawnPoint sceneSpawnPoint in array)
			{
				sceneSpawnPoint.SpawnPointEnabled = true;
			}
		}
	}

	private SceneSpawnPoint MasterGetLeastRecentlyUsedSpawnPoint(long previousRoomId = 0L)
	{
		SceneSpawnPoint sceneSpawnPoint = null;
		if (spawnPointOverrides.Count > 0)
		{
			sceneSpawnPoint = GetLeastRecentlyUsedSpawnPointInternal(spawnPointOverrides, previousRoomId);
		}
		if (sceneSpawnPoint == null)
		{
			sceneSpawnPoint = GetLeastRecentlyUsedSpawnPointInternal(sceneSpawnPoints, previousRoomId);
		}
		if (sceneSpawnPoint == null)
		{
			UnityEngine.Debug.Log("Could not find a spawn point configured for this player. Spawning at default scene spawn point anyway.");
			return sceneSpawnPoints[0];
		}
		return sceneSpawnPoint;
	}

	private SceneSpawnPoint GetLeastRecentlyUsedSpawnPointInternal(IList<SceneSpawnPoint> spawnPoints, long previousRoomId)
	{
		if (spawnPoints.Count == 0)
		{
			UnityEngine.Debug.LogError("Activity " + RecRoomSceneManager.CurrentSceneFriendlyName + " does not contain any spawn points.");
			return null;
		}
		SceneSpawnPoint sceneSpawnPoint = null;
		if (previousRoomId > 0)
		{
			sceneSpawnPoint = FindLRUSpawnPoint(spawnPoints, previousRoomId);
		}
		if (sceneSpawnPoint == null)
		{
			sceneSpawnPoint = FindLRUSpawnPoint(spawnPoints, 0L);
		}
		return sceneSpawnPoint;
	}

	private SceneSpawnPoint FindLRUSpawnPoint(IList<SceneSpawnPoint> spawnPoints, long requiredPreviousRoomId = 0L)
	{
		FilterSpawnPoints(spawnPoints, requiredPreviousRoomId, filteredSpawnPoints);
		if (filteredSpawnPoints.Count == 0)
		{
			return null;
		}
		filteredSpawnPoints.Sort(SpawnPointBlockedData.Comparer);
		return filteredSpawnPoints[0].spawnPoint;
	}

	private void FilterSpawnPoints(IList<SceneSpawnPoint> spawnPoints, long requiredPreviousRoomId, List<SpawnPointBlockedData> filteredSpawnPointsOut)
	{
		bool flag = requiredPreviousRoomId <= 0;
		filteredSpawnPointsOut.Clear();
		for (int i = 0; i < spawnPoints.Count; i++)
		{
			SceneSpawnPoint sceneSpawnPoint = spawnPoints[i];
			if (!sceneSpawnPoint.SpawnPointEnabled)
			{
				continue;
			}
			if (flag)
			{
				if (sceneSpawnPoint.SupportsPreviousRoomCheck)
				{
					continue;
				}
			}
			else if (!sceneSpawnPoint.SupportsPreviousRoomCheck || !sceneSpawnPoint.PreviousRooms.Contains(requiredPreviousRoomId))
			{
				continue;
			}
			filteredSpawnPointsOut.Add(new SpawnPointBlockedData
			{
				spawnPoint = sceneSpawnPoint,
				isBlocked = sceneSpawnPoint.IsBlockedByOverlaps
			});
		}
	}
}
public class SceneSpawnPoint : SpawnPoint
{
	public static SpawnPointComparer<SceneSpawnPoint> Comparer = new SpawnPointComparer<SceneSpawnPoint>();

	public virtual bool SupportsPreviousRoomCheck => false;

	public virtual IList<long> PreviousRooms => new long[0];

	protected override Color GizmoColor => Color.red;
}
namespace RecRoom.Activities
{
	[Serializable]
	public abstract class ScoreManager
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_StatsChangeEvent;

		protected SynchronizedField<int[], int[]> _teamScores;

		protected int[] TeamScores
		{
			get
			{
				return _teamScores.Get1();
			}
			set
			{
				int[] array = new int[TeamScores.Length];
				Array.Copy(TeamScores, array, TeamScores.Length);
				_teamScores.Set(value, array);
			}
		}

		protected int[] PreviousTeamScores => _teamScores.Get2();

		public event Action StatsChangeEvent
		{
			add
			{
				Action action = this.m_StatsChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_StatsChangeEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_StatsChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_StatsChangeEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public int GetScore(GameTeam team)
		{
			if (team == GameTeam.ANY)
			{
				return 0;
			}
			return _teamScores.Get1()[(int)team];
		}

		public int GetPreviousScore(GameTeam team)
		{
			if (team == GameTeam.ANY)
			{
				return 0;
			}
			return _teamScores.Get2()[(int)team];
		}

		public void MasterAddScore(GameTeam team, int deltaScore, int maxScore, bool supportsNegativeScore = false)
		{
			if (PhotonNetwork.isMasterClient)
			{
				int score = GetScore(team);
				int score2 = Mathf.Min(score + deltaScore, maxScore);
				MasterSetScore(team, score2, supportsNegativeScore);
			}
		}

		public void MasterAddScore(GameTeam team, int deltaScore, bool supportsNegativeScore = false)
		{
			if (PhotonNetwork.isMasterClient)
			{
				int score = GetScore(team);
				MasterSetScore(team, score + deltaScore, supportsNegativeScore);
			}
		}

		public void MasterSetScore(GameTeam team, int score, bool supportsNegativeScore = false)
		{
			if (PhotonNetwork.isMasterClient)
			{
				int[] array = (int[])TeamScores.Clone();
				if (!supportsNegativeScore && score < 0)
				{
					score = 0;
				}
				array[(int)team] = score;
				TeamScores = array;
			}
		}

		public virtual void MasterResetAllScores()
		{
			if (PhotonNetwork.isMasterClient)
			{
				TeamScores = new int[TeamScores.Length];
			}
		}

		protected virtual void FireStatsChangeEvent()
		{
			if (this.StatsChangeEvent != null)
			{
				this.StatsChangeEvent();
			}
		}
	}
