public class SpawnPointComparer<T> : IComparer<T> where T : SpawnPoint
{
	public int Compare(T a, T b)
	{
		return a.UseCount.CompareTo(b.UseCount);
	}
}
public abstract class SpawnPoint : Photon.MonoBehaviour
{
	[SerializeField]
	private bool testsForOverlap = true;

	[SerializeField]
	protected Transform[] backupSpawnPositions;

	[SerializeField]
	private PhotonView parent;

	private const float COOLDOWN = 3f;

	protected const float OVERLAP_TEST_HEIGHT = 2f;

	public const float OVERLAP_TEST_RADIUS = 0.5f;

	private static float ENVIRONMENT_OVERLAP_TEST_OFFSET = 0.6f;

	private static float ENVIRONMENT_OVERLAP_TEST_HEIGHT = 2f - ENVIRONMENT_OVERLAP_TEST_OFFSET;

	private static float TELEPORT_REGION_TEST_HEIGHT = 0.5f;

	private static float TELEPORT_REGION_TEST_RADIUS = 0.45f;

	[NonSerialized]
	public bool SpawnPointEnabled = true;

	private SynchronizedField<int> _useCount;

	private SynchronizedField<float> _lastUseTime;

	public Vector3 WorldPosition => base.transform.position;

	public Quaternion WorldRotation => base.transform.rotation;

	public Vector3 LocalPosition => (!(Parent != null)) ? WorldPosition : Parent.transform.InverseTransformPoint(WorldPosition);

	public Quaternion LocalRotation => (!(Parent != null)) ? WorldRotation : Parent.transform.InverseTransformRotation(WorldRotation);

	public PhotonView Parent => parent;

	public bool TestsForOverlap => testsForOverlap;

	public int UseCount
	{
		get
		{
			return _useCount.Get();
		}
		private set
		{
			_useCount.Set(value);
		}
	}

	public bool IsOnCooldown => UseCount > 0 && CurrentTime - LastUseTime <= 3f;

	private float LastUseTime
	{
		get
		{
			return _lastUseTime.Get();
		}
		set
		{
			_lastUseTime.Set(value);
		}
	}

	private float CurrentTime => (float)PhotonNetwork.time;

	public virtual bool IsBlockedByOverlaps
	{
		get
		{
			if (TestsForOverlap)
			{
				if (!IsBlockedAtPosition(base.transform.position))
				{
					return false;
				}
				if (backupSpawnPositions != null)
				{
					Transform[] array = backupSpawnPositions;
					foreach (Transform transform in array)
					{
						if (!IsBlockedAtPosition(transform.position))
						{
							return false;
						}
					}
				}
				return true;
			}
			return false;
		}
	}

	protected abstract Color GizmoColor { get; }

	protected override void Awake()
	{
		base.Awake();
		_lastUseTime = new SynchronizedField<float>(this, "LAST_USE_TIME", 0f, SetterPermissionMode.MASTER);
		_useCount = new SynchronizedField<int>(this, "USE_COUNT", 0, SetterPermissionMode.MASTER);
	}

	public void MasterUse()
	{
		if (PhotonNetwork.isMasterClient)
		{
			LastUseTime = CurrentTime;
			UseCount++;
		}
	}

	public Transform GetFirstAvailableSpawnTransform(out Vector3 localPosition, out Quaternion localRotation)
	{
		if (!TestsForOverlap || !IsBlockedAtPosition(base.transform.position))
		{
			localPosition = LocalPosition;
			localRotation = LocalRotation;
			return base.transform;
		}
		if (backupSpawnPositions != null)
		{
			Transform[] array = backupSpawnPositions;
			foreach (Transform transform in array)
			{
				if (!IsBlockedAtPosition(transform.position))
				{
					localPosition = ((!(Parent != null)) ? transform.position : Parent.transform.InverseTransformPoint(transform.position));
					localRotation = ((!(Parent != null)) ? transform.rotation : Parent.transform.InverseTransformRotation(transform.rotation));
					return transform;
				}
			}
		}
		localPosition = LocalPosition;
		localRotation = LocalRotation;
		return base.transform;
	}

	public virtual bool IsBlockedAtPosition(Vector3 position)
	{
		return PlayerOverlapAtPosition(position);
	}

	public static bool PlayerOverlapAtPosition(Vector3 position)
	{
		return Physics.CheckCapsule(position, position + Vector3.up * 2f, 0.5f, 1053184);
	}

	public static bool ToolOrEnvironmentOverlapAtPosition(Vector3 position)
	{
		Vector3 vector = position + Vector3.up * ENVIRONMENT_OVERLAP_TEST_OFFSET;
		return Physics.CheckCapsule(vector, vector + Vector3.up * ENVIRONMENT_OVERLAP_TEST_HEIGHT, 0.5f, 3073);
	}

	public static bool IsInValidPosition(Vector3 position)
	{
		return CollisionDetection.IsSphereOverColliderPlayerCanStandOn(position + TELEPORT_REGION_TEST_HEIGHT * Vector3.up, TELEPORT_REGION_TEST_RADIUS, TELEPORT_REGION_TEST_HEIGHT);
	}

	public void Enable()
	{
		SpawnPointEnabled = true;
	}

	public void Disable()
	{
		SpawnPointEnabled = false;
	}

	protected virtual void OnDrawGizmos()
	{
		if (!SpawnPointEnabled)
		{
			return;
		}
		Gizmos.color = Color.blue;
		Gizmos.DrawLine(base.transform.position, base.transform.position + base.transform.forward * 1.5f);
		Gizmos.color = GizmoColor;
		Gizmos.DrawSphere(base.transform.position, 0.5f);
		if (backupSpawnPositions != null)
		{
			Gizmos.color = Gizmos.color.ChangeAlpha(Gizmos.color.a / 5f);
			Transform[] array = backupSpawnPositions;
			foreach (Transform transform in array)
			{
				Gizmos.DrawSphere(transform.position, 0.5f);
			}
		}
	}

	protected virtual void OnDrawGizmosSelected()
	{
		if (!SpawnPointEnabled)
		{
			return;
		}
		Gizmos.color = Color.red;
		if (backupSpawnPositions == null)
		{
			return;
		}
		if (IsBlockedAtPosition(base.transform.position))
		{
			Gizmos.DrawWireSphere(base.transform.position, 0.5f);
		}
		Transform[] array = backupSpawnPositions;
		foreach (Transform transform in array)
		{
			if (IsBlockedAtPosition(transform.position))
			{
				Gizmos.DrawWireSphere(transform.position, 0.5f);
			}
		}
	}
}
