namespace RecRoom.Activities
{
	[Serializable]
	public abstract class TeamManager
	{
		protected class PlayerData
		{
			[CompilerGenerated]
			[DebuggerBrowsable(DebuggerBrowsableState.Never)]
			private TeamChange m_TeamChangeEvent;

			private PhotonPlayer _player;

			private SynchronizedField<GameTeam, GameTeamPlayerIndex> _teamField;

			public GameTeam TeamId => _teamField.Get1();

			public GameTeamPlayerIndex TeamPlayerIndex => _teamField.Get2();

			public event TeamChange TeamChangeEvent
			{
				add
				{
					TeamChange teamChange = this.m_TeamChangeEvent;
					TeamChange teamChange2;
					do
					{
						teamChange2 = teamChange;
						teamChange = Interlocked.CompareExchange(ref this.m_TeamChangeEvent, (TeamChange)Delegate.Combine(teamChange2, value), teamChange);
					}
					while (teamChange != teamChange2);
				}
				remove
				{
					TeamChange teamChange = this.m_TeamChangeEvent;
					TeamChange teamChange2;
					do
					{
						teamChange2 = teamChange;
						teamChange = Interlocked.CompareExchange(ref this.m_TeamChangeEvent, (TeamChange)Delegate.Remove(teamChange2, value), teamChange);
					}
					while (teamChange != teamChange2);
				}
			}

			public PlayerData(PhotonPlayer player, string synchronizedKey)
			{
				_player = player;
				_teamField = new SynchronizedField<GameTeam, GameTeamPlayerIndex>(player, synchronizedKey, GameTeam.ANY, GameTeamPlayerIndex.ANY_INDEX, SetterPermissionMode.ANYONE, TeamChangeCallback);
			}

			public void SetTeam(GameTeam team, GameTeamPlayerIndex playerIndex)
			{
				_teamField.Set(team, playerIndex);
			}

			private void TeamChangeCallback()
			{
				if (this.TeamChangeEvent != null)
				{
					this.TeamChangeEvent(_player, isDisconnecting: false);
				}
			}
		}

		public delegate void TeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting);

		protected static readonly List<GameTeam> INSTANTANEOUS_TEAMS = new List<GameTeam>();

		protected static readonly List<PhotonPlayer> INSTANTANEOUS_PLAYERS = new List<PhotonPlayer>();

		protected static readonly List<GameTeamPlayerIndex> INSTANTANEOUS_PLAYER_INDICES = new List<GameTeamPlayerIndex>();

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private TeamChange m_TeamChangeEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_LocalPlayerTeamChangeEvent;

		private Dictionary<int, PlayerData> allPlayerData = new Dictionary<int, PlayerData>();

		protected abstract string PlayerTeamSerializationKey { get; }

		public event TeamChange TeamChangeEvent
		{
			add
			{
				TeamChange teamChange = this.m_TeamChangeEvent;
				TeamChange teamChange2;
				do
				{
					teamChange2 = teamChange;
					teamChange = Interlocked.CompareExchange(ref this.m_TeamChangeEvent, (TeamChange)Delegate.Combine(teamChange2, value), teamChange);
				}
				while (teamChange != teamChange2);
			}
			remove
			{
				TeamChange teamChange = this.m_TeamChangeEvent;
				TeamChange teamChange2;
				do
				{
					teamChange2 = teamChange;
					teamChange = Interlocked.CompareExchange(ref this.m_TeamChangeEvent, (TeamChange)Delegate.Remove(teamChange2, value), teamChange);
				}
				while (teamChange != teamChange2);
			}
		}

		public event Action LocalPlayerTeamChangeEvent
		{
			add
			{
				Action action = this.m_LocalPlayerTeamChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalPlayerTeamChangeEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_LocalPlayerTeamChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_LocalPlayerTeamChangeEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public virtual void OnAwake()
		{
			PlayerData playerData = GetPlayerData(PhotonNetwork.player);
			if (playerData == null)
			{
				UnityEngine.Debug.LogError("Could not retrieve player data for local player.");
			}
			else
			{
				playerData.TeamChangeEvent += OnLocalPlayerTeamChange;
			}
			Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
		}

		public virtual void OnStart()
		{
		}

		public virtual void OnDestroy()
		{
			foreach (PlayerData value in allPlayerData.Values)
			{
				value.TeamChangeEvent -= OnTeamChange;
			}
			Player.PlayerCreatedEvent -= new Action<Player>(OnRecRoomPlayerCreated);
		}

		public virtual void OnUpdate()
		{
		}

		public void OnPlayerDisconnected(PhotonPlayer player)
		{
			OnTeamChange(player, isDisconnecting: true);
		}

		protected virtual void OnRecRoomPlayerCreated(Player player)
		{
		}

		public void LeaveTeam(PhotonPlayer player)
		{
			if ((player.IsLocal || PhotonNetwork.isMasterClient) && PlayerCanLeaveGame(player))
			{
				SetPlayerTeam(player, GameTeam.ANY);
			}
		}

		public void MasterClearTeams()
		{
			if (PhotonNetwork.isMasterClient)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					SetPlayerTeam(PhotonNetwork.playerList[i], GameTeam.ANY);
				}
			}
		}

		public abstract int GetTeamMaxPlayerCount(GameTeam team);

		public abstract GameTeam[] GetAllTeams();

		public abstract int GetActivePlayersMaxCount();

		public abstract bool PlayerCanSwitchTeam(PhotonPlayer player);

		public abstract bool PlayerCanLeaveGame(PhotonPlayer player);

		protected PlayerData GetPlayerData(PhotonPlayer player)
		{
			PlayerData value = null;
			if (allPlayerData != null && player != null && !allPlayerData.TryGetValue(player.ID, out value))
			{
				value = new PlayerData(player, PlayerTeamSerializationKey);
				value.TeamChangeEvent += OnTeamChange;
				allPlayerData[player.ID] = value;
			}
			return value;
		}

		protected virtual void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			if (this.TeamChangeEvent != null)
			{
				this.TeamChangeEvent(changingTeamPlayer, isDisconnecting);
			}
		}

		protected void OnLocalPlayerTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			if (this.LocalPlayerTeamChangeEvent != null)
			{
				this.LocalPlayerTeamChangeEvent();
			}
		}

		public bool IsPlayerSpectator(PhotonPlayer player)
		{
			return GetPlayerTeam(player) == GameTeam.ANY;
		}

		public GameTeam GetPlayerTeam(PhotonPlayer player)
		{
			return (player == null) ? GameTeam.ANY : GetPlayerData(player).TeamId;
		}

		public GameTeamPlayerIndex GetTeamPlayerIndex(PhotonPlayer player)
		{
			return (player == null) ? GameTeamPlayerIndex.ANY_INDEX : GetPlayerData(player).TeamPlayerIndex;
		}

		public bool TryGetPlayerTeamAndIndex(PhotonPlayer player, out GameTeam gameTeam, out GameTeamPlayerIndex gameTeamPlayerIndex)
		{
			gameTeam = GameTeam.ANY;
			gameTeamPlayerIndex = GameTeamPlayerIndex.ANY_INDEX;
			if (player != null)
			{
				PlayerData playerData = GetPlayerData(player);
				gameTeam = playerData.TeamId;
				gameTeamPlayerIndex = playerData.TeamPlayerIndex;
				return true;
			}
			return false;
		}

		public PhotonPlayer GetPlayerAtTeamPlayerIndex(GameTeam team, GameTeamPlayerIndex teamPlayerIndex)
		{
			PhotonPlayer[] teamPlayers = GetTeamPlayers(team);
			for (int i = 0; i < teamPlayers.Length; i++)
			{
				if (GetTeamPlayerIndex(teamPlayers[i]) == teamPlayerIndex)
				{
					return teamPlayers[i];
				}
			}
			return null;
		}

		public int GetTeamPlayerCount(GameTeam team)
		{
			return GetTeamPlayers(team).Length;
		}

		public GameTeam GetAnotherTeam(GameTeam team)
		{
			GameTeam result = GameTeam.ANY;
			GameTeam[] allTeams = GetAllTeams();
			for (int i = 0; i < allTeams.Length; i++)
			{
				if (allTeams[i] != team)
				{
					result = allTeams[i];
					break;
				}
			}
			return result;
		}

		public GameTeam[] GetOtherTeams(GameTeam team)
		{
			return (from t in GetAllTeams()
				where t != team && GetTeamPlayerCount(t) > 0
				select t).ToArray();
		}

		public GameTeam[] GetActiveTeams()
		{
			return (from t in GetAllTeams()
				where GetTeamPlayerCount(t) > 0
				select t).ToArray();
		}

		public int GetTeamVacancy(GameTeam team)
		{
			return GetTeamMaxPlayerCount(team) - GetTeamPlayerCount(team);
		}

		public int GetGameVacancy()
		{
			int num = 0;
			GameTeam[] allTeams = GetAllTeams();
			for (int i = 0; i < allTeams.Length; i++)
			{
				num += GetTeamVacancy(allTeams[i]);
			}
			return num;
		}

		public PhotonPlayer GetAnyPlayerOnTeam(GameTeam team)
		{
			PhotonPlayer result = null;
			if (team != GameTeam.ANY)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					if (GetPlayerTeam(PhotonNetwork.playerList[i]) == team)
					{
						result = PhotonNetwork.playerList[i];
						break;
					}
				}
			}
			return result;
		}

		public PhotonPlayer[] GetTeamPlayers(GameTeam team)
		{
			INSTANTANEOUS_PLAYERS.Clear();
			if (team != GameTeam.ANY)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					if (GetPlayerTeam(PhotonNetwork.playerList[i]) == team)
					{
						INSTANTANEOUS_PLAYERS.Add(PhotonNetwork.playerList[i]);
					}
				}
			}
			return INSTANTANEOUS_PLAYERS.ToArray();
		}

		public PhotonPlayer[] GetTeammatesOfPlayer(PhotonPlayer player)
		{
			INSTANTANEOUS_PLAYERS.Clear();
			GameTeam playerTeam = GetPlayerTeam(player);
			if (playerTeam != GameTeam.ANY)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					if (GetPlayerTeam(PhotonNetwork.playerList[i]) == playerTeam && PhotonNetwork.playerList[i] != player)
					{
						INSTANTANEOUS_PLAYERS.Add(PhotonNetwork.playerList[i]);
					}
				}
			}
			return INSTANTANEOUS_PLAYERS.ToArray();
		}

		public PhotonPlayer[] GetOpponentsOfPlayer(PhotonPlayer player)
		{
			INSTANTANEOUS_PLAYERS.Clear();
			GameTeam playerTeam = GetPlayerTeam(player);
			if (playerTeam != GameTeam.ANY)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					if (GetPlayerTeam(PhotonNetwork.playerList[i]) != playerTeam && PhotonNetwork.playerList[i] != player)
					{
						INSTANTANEOUS_PLAYERS.Add(PhotonNetwork.playerList[i]);
					}
				}
			}
			return INSTANTANEOUS_PLAYERS.ToArray();
		}

		public PhotonPlayer[] GetTeamPlayersSortedByIndex(GameTeam team)
		{
			PhotonPlayer[] teamPlayers = GetTeamPlayers(team);
			Array.Sort(teamPlayers, (PhotonPlayer a, PhotonPlayer b) => GetTeamPlayerIndex(a).CompareTo(GetTeamPlayerIndex(b)));
			return teamPlayers;
		}

		public PhotonPlayer[] GetOtherPlayers(GameTeam team)
		{
			INSTANTANEOUS_PLAYERS.Clear();
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				GameTeam playerTeam = GetPlayerTeam(PhotonNetwork.playerList[i]);
				if (playerTeam != team && playerTeam != GameTeam.ANY)
				{
					INSTANTANEOUS_PLAYERS.Add(PhotonNetwork.playerList[i]);
				}
			}
			return INSTANTANEOUS_PLAYERS.ToArray();
		}

		public GameTeam GetFirstActiveTeam()
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				GameTeam playerTeam = GetPlayerTeam(PhotonNetwork.playerList[i]);
				if (playerTeam != GameTeam.ANY)
				{
					return playerTeam;
				}
			}
			return GameTeam.ANY;
		}

		public int GetActiveTeamCount()
		{
			return GetActiveTeams().Length;
		}

		public IEnumerable<PhotonPlayer> GetActivePlayers()
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				if (GetPlayerTeam(PhotonNetwork.playerList[i]) != GameTeam.ANY)
				{
					yield return PhotonNetwork.playerList[i];
				}
			}
		}

		public int GetActivePlayerCount()
		{
			return GetActivePlayers().Count();
		}

		public int GetActivePlayerVacancy()
		{
			return GetActivePlayersMaxCount() - GetActivePlayerCount();
		}

		public bool PlayersAreTeammates(PhotonPlayer playerA, PhotonPlayer playerB)
		{
			GameTeam playerTeam = GetPlayerTeam(playerA);
			GameTeam playerTeam2 = GetPlayerTeam(playerB);
			return playerTeam != GameTeam.ANY && playerTeam == playerTeam2;
		}

		public bool PlayerOnTeam(PhotonPlayer playerA, GameTeam team)
		{
			GameTeam playerTeam = GetPlayerTeam(playerA);
			return playerTeam == team;
		}

		protected int GetMinTeamSize(GameTeam[] teams)
		{
			GameTeam minTeam;
			return GetMinTeamSize(teams, out minTeam);
		}

		protected int GetMinTeamSize(GameTeam[] teams, out GameTeam minTeam)
		{
			minTeam = GameTeam.ANY;
			int num = int.MaxValue;
			for (int i = 0; i < teams.Length; i++)
			{
				int teamPlayerCount = GetTeamPlayerCount(teams[i]);
				if (teamPlayerCount < num)
				{
					minTeam = teams[i];
					num = teamPlayerCount;
				}
			}
			return num;
		}

		public virtual string GetTeamName(GameTeam team)
		{
			return (team != GameTeam.ANY) ? (GameTeamSettings.GetTeamName(team) + " Team") : "Spectating";
		}

		protected GameTeam GetPartyMemberTeam(PhotonPlayer thisPhotonPlayer, string partyId)
		{
			IEnumerable<PhotonPlayer> activePlayers = GetActivePlayers();
			foreach (PhotonPlayer item in activePlayers)
			{
				if (item == thisPhotonPlayer)
				{
					continue;
				}
				Player player = item.ToPlayer();
				if (!(player == null) && !(player.PlayerParty.CurrentPartyId != partyId))
				{
					GameTeam playerTeam = GetPlayerTeam(item);
					if (GetTeamVacancy(playerTeam) != 0)
					{
						return playerTeam;
					}
				}
			}
			return GameTeam.ANY;
		}

		protected void SetPlayerTeam(PhotonPlayer player, GameTeam team)
		{
			GameTeamPlayerIndex playerIndex = ((team != GameTeam.ANY) ? GetNextTeamPlayerIndex(team) : GameTeamPlayerIndex.ANY_INDEX);
			GetPlayerData(player).SetTeam(team, playerIndex);
		}

		protected GameTeamPlayerIndex GetNextTeamPlayerIndex(GameTeam team)
		{
			INSTANTANEOUS_PLAYER_INDICES.Clear();
			if (team != GameTeam.ANY)
			{
				PhotonPlayer[] playerList = PhotonNetwork.playerList;
				foreach (PhotonPlayer player in playerList)
				{
					PlayerData playerData = GetPlayerData(player);
					if (playerData.TeamId == team)
					{
						INSTANTANEOUS_PLAYER_INDICES.Add(playerData.TeamPlayerIndex);
					}
				}
			}
			INSTANTANEOUS_PLAYER_INDICES.Sort();
			GameTeamPlayerIndex gameTeamPlayerIndex = GameTeamPlayerIndex.INDEX_0;
			for (int j = 0; j < INSTANTANEOUS_PLAYER_INDICES.Count; j++)
			{
				if (INSTANTANEOUS_PLAYER_INDICES[j] > gameTeamPlayerIndex)
				{
					return gameTeamPlayerIndex;
				}
				if (INSTANTANEOUS_PLAYER_INDICES[j] == gameTeamPlayerIndex)
				{
					gameTeamPlayerIndex++;
				}
			}
			return gameTeamPlayerIndex;
		}
	}
}
public class TeleportationPortal : UnityEngine.MonoBehaviour
{
	public enum PortalMode
	{
		Teleport,
		Respawn,
		DEPRECATED_1,
		DEPRECATED_5,
		Nothing,
		Room,
		DEPRECATED_2,
		DEPRECATED_3,
		DEPRECATED_4,
		TeleportToRandomPoint,
		Disabled,
		ReloadCurrentActivityLevel,
		Seat,
		Ladder,
		MultiSelect,
		RoomScene
	}

	[Header("Mode Configuration")]
	[SerializeField]
	protected PortalMode mode;

	[ConditionalField("UsesTargetTransform")]
	public Transform Target;

	[ConditionalField("IsSeat")]
	public Transform SeatDisembarkTarget;

	[SerializeField]
	[ConditionalField("IsTeleportToRandomPointMode")]
	private Transform randomPointCenter;

	[SerializeField]
	[ConditionalField("IsTeleportToRandomPointMode")]
	private float randomPointRadius = 6f;

	[SerializeField]
	[ConditionalField("IsTeleportToRandomPointMode")]
	private int randomPointMaxRetryCount = 4;

	[SerializeField]
	[ConditionalField("IsTeleportToRandomPointMode")]
	private bool randomizeRotation = true;

	[Tooltip("Name of the destination room if the Mode is 'Room' or room scene within the current room if the Mode is 'RoomScene'")]
	[FormerlySerializedAs("DestinationRoomName")]
	[ConditionalField("UsesTargetName")]
	public string TargetName;

	[ConditionalField("IsRoomSceneMode")]
	public SessionManager.JoinRoomInviteMode JoinRoomSceneInviteMode = SessionManager.JoinRoomInviteMode.InviteParty;

	[Tooltip("Door ID to look up query on Server if Mode is 'MultiSelect'")]
	[SerializeField]
	[ConditionalField("IsMultiselectMode")]
	private string DoorID;

	[SerializeField]
	[ConditionalField("IsMultiselectMode")]
	private TextMeshPro DoorNameText;

	private string roomSelectionQuery;

	[Header("Highlight")]
	[SerializeField]
	private Renderer HighlightRenderer;

	[SerializeField]
	private bool useOutlineHighlight;

	[SerializeField]
	private int highlightRendererMaterialIndex;

	[SerializeField]
	private Color highlightColor = Color.cyan;

	[SerializeField]
	private float highlightBrightness = 1f;

	[Header("Interaction")]
	[Tooltip("If the user can teleport with a tool in hand?")]
	[SerializeField]
	private bool CanCarryTools;

	[Header("Locking")]
	[SerializeField]
	private bool supportsInGameLocking;

	[SerializeField]
	private Transform activityMenuRoot;

	[HideInInspector]
	public Vector3? TargetPositionOverride;

	[HideInInspector]
	public Quaternion? TargetRotationOverride;

	[HideInInspector]
	public RecNet.Event TargetEvent;

	protected Collider Collider;

	protected Animator Animator;

	private bool localPlayerHasEverRespawned;

	private float lastLocalPlayerRespawnTime;

	private Material[] highlightMaterials;

	private Material[] defaultMaterials;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_LocalPlayerUseEvent;

	protected static readonly int ANIMATION_HIGHLIGHT_ID = Animator.StringToHash("Highlighted");

	private static TeleportationPortal _localPlayerSeat = null;

	protected bool _isLocked;

	private bool _lockedHighlight;

	private bool _highlight;

	public bool SupportsInGameLocking => supportsInGameLocking;

	public static TeleportationPortal LocalPlayerSeat
	{
		get
		{
			return _localPlayerSeat;
		}
		set
		{
			if (_localPlayerSeat != value)
			{
				_localPlayerSeat = value;
			}
		}
	}

	public virtual bool IsLocked
	{
		get
		{
			return _isLocked;
		}
		set
		{
			if (value)
			{
				_lockedHighlight = Highlight;
				Highlight = false;
				_isLocked = true;
			}
			else
			{
				_isLocked = false;
				Highlight = _lockedHighlight;
			}
		}
	}

	public Transform SeatTransform
	{
		get
		{
			if (IsSeat)
			{
				return Target;
			}
			return null;
		}
	}

	public bool IsSeat => mode == PortalMode.Seat;

	public bool IsLadder => mode == PortalMode.Ladder;

	public bool IsTeleportOnlyMode => mode == PortalMode.Teleport;

	public bool IsTeleportToRandomPointMode => mode == PortalMode.TeleportToRandomPoint;

	public bool IsMultiselectMode => mode == PortalMode.MultiSelect;

	public bool IsRoomSceneMode => mode == PortalMode.RoomScene;

	protected bool UsesTargetTransform => mode == PortalMode.Teleport || mode == PortalMode.Ladder || mode == PortalMode.Seat;

	protected bool UsesTargetName => mode == PortalMode.Room || mode == PortalMode.RoomScene;

	public virtual bool IsValid
	{
		get
		{
			if (!base.isActiveAndEnabled || IsLocked)
			{
				return false;
			}
			switch (mode)
			{
			case PortalMode.Disabled:
				return false;
			case PortalMode.Nothing:
				return this.LocalPlayerUseEvent != null;
			case PortalMode.Teleport:
			case PortalMode.Ladder:
			{
				int result;
				if (!(Target != null))
				{
					Vector3? targetPositionOverride = TargetPositionOverride;
					result = (targetPositionOverride.HasValue ? 1 : 0);
				}
				else
				{
					result = 1;
				}
				return (byte)result != 0;
			}
			case PortalMode.Seat:
			{
				int result2;
				if (SeatDisembarkTarget != null)
				{
					if (!(Target != null))
					{
						Vector3? targetPositionOverride2 = TargetPositionOverride;
						result2 = (targetPositionOverride2.HasValue ? 1 : 0);
					}
					else
					{
						result2 = 1;
					}
				}
				else
				{
					result2 = 0;
				}
				return (byte)result2 != 0;
			}
			case PortalMode.Respawn:
				return !localPlayerHasEverRespawned || UnityEngine.Time.time - lastLocalPlayerRespawnTime >= Player.RespawnDuration;
			case PortalMode.ReloadCurrentActivityLevel:
				return true;
			case PortalMode.Room:
			case PortalMode.RoomScene:
				return !string.IsNullOrEmpty(TargetName);
			case PortalMode.MultiSelect:
				return !string.IsNullOrEmpty(roomSelectionQuery);
			case PortalMode.TeleportToRandomPoint:
				return randomPointCenter != null && randomPointMaxRetryCount > 0;
			default:
				return false;
			}
		}
	}

	public Vector3 DestinationPosition
	{
		get
		{
			if (TargetPositionOverride.HasValue)
			{
				return TargetPositionOverride.Value;
			}
			if (Target != null)
			{
				return Target.transform.position;
			}
			return base.transform.position;
		}
	}

	public Vector3 DestinationForward
	{
		get
		{
			Vector3 vector = Vector3.forward;
			if (TargetRotationOverride.HasValue)
			{
				vector = TargetRotationOverride.Value * Vector3.forward;
			}
			else if (Target != null)
			{
				vector = Target.forward;
			}
			return Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
		}
	}

	public bool SupportsLaserTeleportPreview => mode == PortalMode.Teleport || mode == PortalMode.Ladder || mode == PortalMode.Seat;

	public bool Highlight
	{
		get
		{
			return _highlight;
		}
		set
		{
			if (IsLocked)
			{
				_lockedHighlight = value;
				return;
			}
			if (HighlightRenderer != null && _highlight != value && !useOutlineHighlight)
			{
				HighlightRenderer.materials = ((!value) ? defaultMaterials : highlightMaterials);
			}
			_highlight = value;
			if (Animator != null)
			{
				Animator.SetBool(ANIMATION_HIGHLIGHT_ID, _highlight);
			}
