	private void PopulateDynamicRoomData()
	{
		if (!string.IsNullOrEmpty(DoorID))
		{
			string key = $"Door.{DoorID}.Title";
			string key2 = $"Door.{DoorID}.Query";
			roomSelectionQuery = GameConfigs.Get(key2);
			if (DoorNameText != null)
			{
				DoorNameText.SetText(GameConfigs.Get(key));
			}
		}
