	public void ChangeMode(PortalMode newMode)
	{
		mode = newMode;
	}

	public void Use(Player player)
	{
		if (!IsValid || !player.PhotonPlayer.IsLocal)
		{
			return;
		}
		switch (mode)
		{
		case PortalMode.Teleport:
		case PortalMode.Ladder:
			if (!NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(player.PhotonPlayer))
			{
				player.PlayerLocomotion.TeleportTo(DestinationPosition, DestinationForward, CanCarryTools, null);
			}
			break;
		case PortalMode.Respawn:
			if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && !player.IsSpawning)
			{
				localPlayerHasEverRespawned = true;
				lastLocalPlayerRespawnTime = UnityEngine.Time.time;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn(!CanCarryTools);
			}
			break;
		case PortalMode.ReloadCurrentActivityLevel:
			if (RecRoomSceneManager.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(RecNet.Rooms.LocalRoomDetails.Room.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_DOOR, GameSessions.LocalGameSession.Private, null);
			}
			break;
		case PortalMode.Room:
			if (RecRoomSceneManager.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(TargetName, SessionManager.LoadSceneSources.CUSTOM_ROOMS_DOOR, isPrivate: false, null);
			}
			break;
		case PortalMode.RoomScene:
			if (RecRoomSceneManager.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoomScene(TargetName, SessionManager.LoadSceneSources.CUSTOM_ROOMS_DOOR, JoinRoomSceneInviteMode);
			}
			break;
		case PortalMode.TeleportToRandomPoint:
			TryTeleportToRandomPoint(player);
			break;
		case PortalMode.Seat:
			player.PlayerLocomotion.TeleportTo(DestinationPosition, DestinationForward, CanCarryTools, null);
			LocalPlayerSeat = this;
			break;
		case PortalMode.MultiSelect:
		{
			BrowseRoomsScreen flowByType = player.PlayerUI.WatchMenu.GetFlowByType<BrowseRoomsScreen>();
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_WALK)
			{
				Vector3 value = new Vector3(activityMenuRoot.position.x, Player.LocalPlayer.Head.transform.position.y - 0.1f, activityMenuRoot.position.z);
				flowByType.SearchByDoorSelection(roomSelectionQuery, value);
			}
			else
			{
				flowByType.SearchByDoorSelection(roomSelectionQuery);
			}
			IsLocked = true;
			player.PlayerEvents.MenuVisibleEvent += PlayerEvents_MenuVisibleEvent;
			break;
		}
		default:
			UnityEngine.Debug.LogErrorFormat("Unsupported portal type: {0}", mode);
			break;
		case PortalMode.Nothing:
		case PortalMode.Disabled:
			break;
		}
		if (this.LocalPlayerUseEvent != null)
		{
			this.LocalPlayerUseEvent();
		}
	}

	private void PlayerEvents_MenuVisibleEvent(bool isOpen)
	{
		if (!isOpen)
		{
			Player.LocalPlayer.PlayerEvents.MenuVisibleEvent -= PlayerEvents_MenuVisibleEvent;
			IsLocked = false;
		}
	}

	public void DisembarkSeat(Player player)
	{
		if (mode == PortalMode.Seat && !(SeatDisembarkTarget == null))
		{
			if (Physics.Raycast(SeatDisembarkTarget.position + Vector3.up, Vector3.down, out var hitInfo, 1f, 2048))
			{
				player.PlayerLocomotion.TeleportTo(hitInfo.point, null, canCarryTools: true, null);
			}
			else
			{
				player.PlayerLocomotion.TeleportTo(SeatDisembarkTarget.position + Vector3.up, null, canCarryTools: true, null);
			}
		}
	}

	public void RenderHighlight()
	{
		if (Highlight && useOutlineHighlight && HighlightRenderer != null)
		{
			OutlineEffectRenderer.RenderTeleportOutline(HighlightRenderer);
		}
	}

	private void TryTeleportToRandomPoint(Player player)
	{
		Vector3 destinationPlayerPosition = Vector3.zero;
		Vector3 value = Vector3.forward;
		bool flag = false;
		for (int i = 0; i < randomPointMaxRetryCount; i++)
		{
			Vector2 vector = UnityEngine.Random.insideUnitCircle * randomPointRadius;
			Vector3 vector2 = new Vector3(vector.x, 0f, vector.y);
			Vector3 origin = randomPointCenter.position + vector2;
			if (Physics.Raycast(origin, -Vector3.up, out var hitInfo, float.MaxValue, 2048, QueryTriggerInteraction.Ignore))
			{
				destinationPlayerPosition = hitInfo.point;
				value = ((!randomizeRotation) ? randomPointCenter.forward : (Quaternion.AngleAxis(UnityEngine.Random.Range(0f, 360f), Vector3.up) * Vector3.forward));
				flag = true;
				break;
			}
		}
		if (flag)
		{
			player.PlayerLocomotion.TeleportTo(destinationPlayerPosition, value, CanCarryTools, null);
		}
	}

	private void OnDrawGizmosSelected()
	{
		Color color = Gizmos.color;
		Gizmos.color = Color.yellow;
		Gizmos.DrawRay(DestinationPosition + new Vector3(0f, 0.1f, 0f), DestinationForward);
		Gizmos.color = color;
		if (mode == PortalMode.TeleportToRandomPoint && randomPointCenter != null)
		{
			Gizmos.DrawWireSphere(randomPointCenter.position, randomPointRadius);
		}
	}
}
