namespace Analytics
{
	public delegate SessionStats SessionStatFactory(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName);
	public class ActivitySessionAnalytics : SingletonMonoBehaviour<ActivitySessionAnalytics>
	{
		private SessionStatFactory[] statClassFactories = new SessionStatFactory[3]
		{
			RoomStats.Create,
			PerfStats.Create,
			MiscStats.Create
		};

		private SessionStats[] statClasses;

		public T GetStatClass<T>() where T : SessionStats
		{
			if (statClasses != null)
			{
				for (int i = 0; i < statClasses.Length; i++)
				{
					if (statClasses[i] is T result)
					{
						return result;
					}
				}
			}
			return (T)null;
		}

		private IEnumerator WaitAndInitialize()
		{
			while (SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance == null)
			{
				yield return null;
			}
			SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.OnTrueQuit += OnTrueQuit;
		}

		protected override void Awake()
		{
			base.Awake();
			statClasses = new SessionStats[statClassFactories.Length];
			SceneManager.sceneLoaded += SceneManager_sceneLoaded;
			GameSessions.OnLocalGameSessionUpdated += OnLocalGameSessionUpdated;
			StartCoroutine(WaitAndInitialize());
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			SceneManager.sceneLoaded -= SceneManager_sceneLoaded;
			GameSessions.OnLocalGameSessionUpdated -= OnLocalGameSessionUpdated;
		}

		private void OnLocalGameSessionUpdated()
		{
			GameSession localGameSession = GameSessions.LocalGameSession;
		}

		private void Update()
		{
			for (int i = 0; i < statClasses.Length; i++)
			{
				if (statClasses[i] != null)
				{
					statClasses[i].Update();
				}
			}
		}

		private void OnTrueQuit(bool analyticsInitialized)
		{
			if (analyticsInitialized)
			{
				LogActivityEnded();
				HandleSceneChange(null, SessionManager.LoadSceneSources.QUIT);
			}
		}

		public void LogActivityEnded()
		{
		}

		public void MarkGameStartTime()
		{
			for (int i = 0; i < statClasses.Length; i++)
			{
				if (statClasses[i] != null)
				{
					statClasses[i].OnGameStart();
				}
			}
		}

		public void RecordLoadTime(double loadTimeSeconds, bool masterDuringLoad)
		{
			for (int i = 0; i < statClasses.Length; i++)
			{
				if (statClasses[i] != null)
				{
					statClasses[i].OnActualLoadTimeData(loadTimeSeconds, masterDuringLoad);
				}
			}
		}

		private void SceneManager_sceneLoaded(Scene scene, LoadSceneMode mode)
		{
			if (!string.IsNullOrEmpty(scene.name) && scene.name != "empty")
			{
				HandleSceneChange();
			}
		}

		private void HandleSceneChange()
		{
			SessionManager.LoadSceneSources loadSource = SingletonMonoBehaviour<SessionManager>.Instance.PeekLastLoadSource();
			RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
			HandleSceneChange(localRoomDetails, loadSource);
		}

		private void HandleSceneChange(RoomDetails newRoomDetails, SessionManager.LoadSceneSources loadSource)
		{
			for (int i = 0; i < statClasses.Length; i++)
			{
				if (statClasses[i] != null)
				{
					if (!statClasses[i].MatchesRoom(newRoomDetails))
					{
						statClasses[i].Log(newRoomDetails, loadSource);
						long roomId = statClasses[i].RoomId;
						string roomName = statClasses[i].RoomName;
						statClasses[i] = GenerateStatsFromFactory(i, newRoomDetails, loadSource, roomId, roomName);
					}
					else
					{
						statClasses[i].OnNewSceneLoad(newRoomDetails);
					}
				}
				else
				{
					statClasses[i] = GenerateStatsFromFactory(i, newRoomDetails, loadSource, -1L, null);
				}
			}
		}

		private SessionStats GenerateStatsFromFactory(int factoryIdx, RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
		{
			if (roomDetails == null)
			{
				return null;
			}
			return statClassFactories[factoryIdx](roomDetails, loadSource, prevRoomId, prevRoomName);
		}
	}
}
namespace CodeStage.AntiCheat.Detectors
{
	public class AdvancedMotionCheatDetector : RRCheatDetector
	{
		[SerializeField]
		private float headToTrackingOriginMaxDelta = 5f;

		private float headToTrackingOriginMaxDeltaSqr = 25f;

		protected override string ComponentName => "AdvancedMotionCheatDetector";

		protected override void Start()
		{
			base.Start();
			headToTrackingOriginMaxDeltaSqr = headToTrackingOriginMaxDelta * headToTrackingOriginMaxDelta;
		}

		protected override bool CheatDetected()
		{
			if (!Player.LocalPlayerExists || Player.LocalPlayer.IsSpawning)
			{
				return false;
			}
			if (RecNet.Rooms.LocalRoomDetails != null && RecNet.Rooms.LocalRoomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner)
			{
				return false;
			}
			float sqrMagnitude = (Player.LocalPlayer.Head.transform.position - Player.LocalPlayer.TrackingSpace.transform.position).sqrMagnitude;
			return sqrMagnitude >= headToTrackingOriginMaxDeltaSqr;
		}
	}
}
namespace AmplitudeAnalytics
{
	public class AGAmplitudeAnalyticsSettings : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private AmplitudeAnalyticsClient.Settings editorSettings;

		[SerializeField]
		private bool forceEditorSettingsForDevelopers;

		public AmplitudeAnalyticsClient.Settings EditorSettings => editorSettings;

		public bool ForceEditorSettingsForDevelopers => forceEditorSettingsForDevelopers;
	}
	public class AmplitudeAnalyticsClient : SingletonMonoBehaviour<AmplitudeAnalyticsClient>
	{
		private enum QuitState
		{
			Running,
			WaitingForFlush,
			Flushed
		}

		private class AnalyticsCache
		{
			private const string QUEUED_EVENTS_KEY = "queued_events";

			private const string QUEUED_IDENTIFY_KEY = "queued_identify";

			public static AnalyticsCache EventCache = new AnalyticsCache("queued_events");

			public static AnalyticsCache IdentifyCache = new AnalyticsCache("queued_identify");

			private List<Dictionary<string, object>> queuedObjects = new List<Dictionary<string, object>>();

			private readonly string prefKey;

			public int TotalCachedObjects => queuedObjects.Count;

			private AnalyticsCache(string prefKey)
			{
				this.prefKey = prefKey;
			}

			public List<Dictionary<string, object>> GetBatch(int batchSize)
			{
				if (!IsEnabled)
				{
					return null;
				}
				int num = Mathf.Min(batchSize, queuedObjects.Count);
				if (num > 0)
				{
					return queuedObjects.GetRange(0, num);
				}
				return null;
			}

			public void SaveObject(AmplitudeAnalyticsIdentifyMessage obj, bool skipSaveToDisk = false)
			{
				if (IsEnabled)
				{
					SaveObject(obj.ToJsonDictionary(), skipSaveToDisk);
				}
			}

			public void SaveObject(Dictionary<string, object> obj, bool skipSaveToDisk = false)
			{
				if (IsEnabled)
				{
					queuedObjects.Add(obj);
					if (!skipSaveToDisk)
					{
						SaveToDisk();
					}
				}
			}

			public void RemoveList(List<Dictionary<string, object>> objList)
			{
				if (!IsEnabled)
				{
					return;
				}
				foreach (Dictionary<string, object> obj in objList)
				{
					RemoveObject(obj, skipSaveToDisk: true);
				}
				SaveToDisk();
			}

			public void RemoveObject(Dictionary<string, object> obj, bool skipSaveToDisk = false)
			{
				if (IsEnabled)
				{
					queuedObjects.Remove(obj);
					if (!skipSaveToDisk)
					{
						SaveToDisk();
					}
				}
			}

			public void SaveToDisk()
			{
				if (IsEnabled)
				{
					string value = AmplitudeMiniJSON.Json.Serialize(queuedObjects);
					PlayerPrefs.SetString(prefKey, value);
					PlayerPrefs.Save();
				}
			}

			public void LoadFromDisk()
			{
				if (!IsEnabled)
				{
					return;
				}
				try
				{
					string text = PlayerPrefs.GetString(prefKey);
					if (string.IsNullOrEmpty(text))
					{
						return;
					}
					if (AmplitudeMiniJSON.Json.Deserialize(text) is List<object> list)
					{
						{
							foreach (object item2 in list)
							{
								Dictionary<string, object> item = item2 as Dictionary<string, object>;
								queuedObjects.Add(item);
							}
							return;
						}
					}
					throw new InvalidCastException("Expected a list of objects, got null");
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
					PlayerPrefs.DeleteKey(prefKey);
					Event("Amplitude_DiskLoad_failed").LogAsync();
				}
			}
		}

