		private void Update()
		{
			if (initialized)
			{
				throttleTime += UnityEngine.Time.deltaTime;
				if (throttleTime >= 1f)
				{
					eventsThisSecond = 0;
					batchesThisSecond = 0;
					throttleTime = 0f;
				}
				if (!flushEventsRunning && (UnityEngine.Time.realtimeSinceStartup >= lastEventFlushTime + settings.BatchIntervalSeconds || AnalyticsCache.EventCache.TotalCachedObjects >= 10))
				{
					StartCoroutine(FlushEvents());
				}
				if (!flushIdentifysRunning && (UnityEngine.Time.realtimeSinceStartup + settings.BatchIntervalSeconds / 2f >= lastIdentifyFlushTime + settings.BatchIntervalSeconds || AnalyticsCache.IdentifyCache.TotalCachedObjects >= 10))
				{
					StartCoroutine(FlushIdentifys());
