		private bool StandaloneApplicationWantsToQuit()
		{
			if (IsEnabled && quitState == QuitState.Running)
			{
				SendEndSessionEvent();
				if (this.OnTrueQuit != null)
				{
					this.OnTrueQuit(initialized);
				}
				StartCoroutine(WaitForFlushAndQuit());
				return false;
			}
			return true;
		}

		public void SendEndSessionEvent()
		{
			if (initialized && !endSessionEventSent)
			{
				endSessionEventSent = true;
				AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsEvent.Create("session_end", SessionId, SequenceNumber, UserId);
				LogEventAsync(amplitudeAnalyticsEventBuilder.Build());
			}
		}

		private IEnumerator WaitForFlushAndQuit()
		{
			float timeout = 3f;
			quitState = QuitState.WaitingForFlush;
			yield return WaitForFlush(timeout);
			quitState = QuitState.Flushed;
			UnityEngine.Application.Quit();
		}

		public IEnumerator WaitForFlush(float timeout = 30f)
		{
			while (flushEventsRunning && timeout > 0f)
			{
				timeout -= UnityEngine.Time.unscaledDeltaTime;
				yield return null;
			}
			while (flushIdentifysRunning && timeout > 0f)
			{
				timeout -= UnityEngine.Time.unscaledDeltaTime;
				yield return null;
			}
			yield return FlushEvents(timeout);
		}

		public static long UTCMillisSinceEpoch()
		{
			return (long)(DateTime.UtcNow - new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc)).TotalMilliseconds;
		}

