		private IEnumerator FlushEvents(float timeout = -1f)
		{
			if (!IsEnabled)
			{
				yield break;
			}
			flushEventsRunning = true;
			lastEventFlushTime = UnityEngine.Time.realtimeSinceStartup;
			bool shouldSendBatch = true;
			if (batchesThisSecond >= 100)
			{
				UnityEngine.Debug.LogWarning("Too many batches being sent. Skipping flush for now");
				shouldSendBatch = false;
			}
			if (eventsThisSecond >= 1000)
			{
				UnityEngine.Debug.LogWarning("Too many events being sent. Skipping flush for now");
				shouldSendBatch = false;
			}
			if (shouldSendBatch)
			{
				AnalyticsCache cache = AnalyticsCache.EventCache;
				string url = settings.eventApiURL;
				Action<int> eventBatchSent = delegate(int totalMessages)
				{
					batchesThisSecond++;
					eventsThisSecond += totalMessages;
				};
				yield return FlushFromCache(cache, url, "event", timeout, eventBatchSent);
			}
			flushEventsRunning = false;
		}

		private IEnumerator FlushIdentifys(float timeout = -1f)
		{
			if (IsEnabled)
			{
				flushIdentifysRunning = true;
				lastIdentifyFlushTime = UnityEngine.Time.realtimeSinceStartup;
				AnalyticsCache cache = AnalyticsCache.IdentifyCache;
				string url = settings.identifyApiURL;
				yield return FlushFromCache(cache, url, "identification", timeout, delegate
				{
				});
				flushIdentifysRunning = false;
			}
		}

		private IEnumerator FlushFromCache(AnalyticsCache cache, string url, string dataIdentifier, float timeout, Action<int> onBatchSent)
		{
			if (!IsEnabled)
			{
				yield break;
			}
			float startTime = UnityEngine.Time.realtimeSinceStartup;
			bool erroredOut = false;
			bool timedOut = false;
			int batchSize = 0;
			while (true)
			{
				List<Dictionary<string, object>> batch2;
				List<Dictionary<string, object>> batch = (batch2 = cache.GetBatch(desiredBatchSize));
				if (batch2 == null || erroredOut)
				{
					break;
				}
				bool flag;
				timedOut = (flag = IsTimedOut(startTime, timeout));
				if (flag)
				{
					break;
				}
				batchSize = batch.Count;
				yield return PostJson(url, dataIdentifier, batch, delegate(long responseCode, string responseBody, List<Dictionary<string, object>> eventParams)
				{
					if ((responseCode >= 200 && responseCode < 300) || responseCode == 304)
					{
						cache.RemoveList(eventParams);
						onBatchSent(eventParams.Count);
						desiredBatchSize = Mathf.Min(desiredBatchSize * 2, 10);
						consecutiveRetriesFailed = 0;
					}
					else if (responseCode == 413)
					{
						if (desiredBatchSize <= 1)
						{
							cache.RemoveList(eventParams);
							UnityEngine.Debug.LogWarning("Received 413 error from Analytics request");
						}
						else
						{
							desiredBatchSize = Mathf.Max(1, desiredBatchSize / 2);
						}
					}
					else
					{
						if (responseCode == 400 && responseBody.Contains("invalid api_key"))
						{
							UnityEngine.Debug.LogError("Bad api key. Dropping messages");
							erroredOut = true;
						}
						else
						{
							consecutiveRetriesFailed++;
							if (consecutiveRetriesFailed >= 5)
							{
								erroredOut = true;
							}
							if (responseCode == 0)
							{
								ResponseCodeZeroErrors++;
								if (ResponseCodeZeroErrors >= 10)
								{
									UnityEngine.Debug.LogError($"Repeated Analytics Failure -- disable for this session");
									IsEnabled = false;
									erroredOut = true;
								}
							}
						}
						if (erroredOut)
						{
							cache.RemoveList(eventParams);
							UnityEngine.Debug.LogError($"AnalyticsRequest failed: [{responseCode}] {responseBody}");
						}
					}
				});
			}
			if (batchSize > 0 && settings.verboseLogging)
			{
				UnityEngine.Debug.Log(string.Format("[{0}] Flush complete: {1} events sent {2} to \"{3}\". Finished with error: {4}. TimedOut: {5}", $"{DateTime.Now:s}", batchSize, (!erroredOut && !timedOut) ? "successfully" : "unsuccessfully", dataIdentifier, erroredOut, timedOut));
			}
		}

		private IEnumerator PostJson<T>(string url, string dataIdentifier, T eventParams, Action<long, string, T> onResponse)
		{
			return PostJson(url, dataIdentifier, Config.AmplitudeKey, eventParams, onResponse);
		}

		private IEnumerator PostJson<T>(string url, string dataIdentifier, string amplitudeKey, T eventParams, Action<long, string, T> onResponse)
		{
			if (!IsEnabled || string.IsNullOrEmpty(amplitudeKey))
			{
				yield break;
			}
			WWWForm form = new WWWForm();
			form.AddField("api_key", amplitudeKey);
			string jsonString = AmplitudeMiniJSON.Json.Serialize(eventParams);
			form.AddField(dataIdentifier, jsonString);
			Uri uri = new Uri(url);
			HTTPRequest httpRequest = new HTTPRequest(uri, HTTPMethods.Post);
			httpRequest.SetFields(form);
			yield return httpRequest.Send();
			int responseCode = 0;
			string responseText = string.Empty;
			if (httpRequest.Response != null)
			{
				responseCode = httpRequest.Response.StatusCode;
				responseText = httpRequest.Response.DataAsText;
			}
			else
			{
				UnityEngine.Debug.LogError("Null response from Amplitude call");
				if (httpRequest.Exception != null)
				{
					UnityEngine.Debug.LogException(httpRequest.Exception);
				}
			}
			onResponse(responseCode, responseText, eventParams);
		}

		private bool IsTimedOut(float startTime, float timeout)
		{
			if (timeout <= 0f)
			{
				return false;
			}
			float num = UnityEngine.Time.realtimeSinceStartup - startTime;
			return num > timeout;
		}
	}
