	public static void GoToEventFailed(RecNet.Event ev, GotoEventFailureReason reason)
	{
		float value = 0f;
		if (ev != null)
		{
			nextEventFailTimes.TryGetValue(ev.EventId, out value);
		}
		float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
		if (realtimeSinceStartup > value)
		{
			AmplitudeAnalyticsClient.Event("goto_event_failed").WithProperty("event", ev.Name).WithProperty("eventId", ev.EventId.ToString())
				.WithProperty("reason", reason.ToString())
				.LogAsync();
			if (ev != null)
			{
				nextEventFailTimes[ev.EventId] = realtimeSinceStartup + 60f;
			}
		}
	}

	public static void GoToPlayerEventFailed(PlayerEvent ev, GotoEventFailureReason reason)
	{
		float value = 0f;
		if (ev != null)
		{
			nextEventFailTimes.TryGetValue(ev.PlayerEventId, out value);
		}
		float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
		if (realtimeSinceStartup > value)
		{
			AmplitudeAnalyticsClient.Event("goto_event_failed").WithProperty("event", ev.Name).WithProperty("eventId", ev.PlayerEventId.ToString())
				.WithProperty("reason", reason.ToString())
				.LogAsync();
			if (ev != null)
			{
				nextEventFailTimes[ev.PlayerEventId] = realtimeSinceStartup + 60f;
			}
		}
	}

