	public static void GameInviteMessageResponse(RecNet.Message message, bool accepted)
	{
		long fromPlayerId = message.FromPlayerId;
		string event_type = ((!accepted) ? "declined" : "accepted") + "_game_invite";
		AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event(event_type);
		PlayerPresence playerPresence = Presence.Get(fromPlayerId);
		if (playerPresence != null)
		{
			string value = null;
			if (playerPresence.GameSession != null)
			{
				value = playerPresence.GameSession.Name;
			}
			amplitudeAnalyticsEventBuilder.WithProperty("source", value);
		}
		amplitudeAnalyticsEventBuilder.WithProperty("relationship", Relationships.GetType(fromPlayerId)).WithProperty("currentActivityFriendlyName", RecRoomSceneManager.CurrentSceneFriendlyName).WithProperty("fromPlayerId", fromPlayerId.ToString())
			.LogAsync();
	}

