	public static void OnMessageReceived(RecNet.Message message)
	{
		switch (message.Type)
		{
		case RecNet.Message.MessageType.GameInvite:
		case RecNet.Message.MessageType.FriendInvite:
			OnInviteReceived(message);
			break;
		case RecNet.Message.MessageType.GameJoinFailed:
			AmplitudeAnalyticsClient.Event("game_join_failed").WithProperty("fromPlayerId", message.FromPlayerId.ToString()).LogAsync();
			break;
		case RecNet.Message.MessageType.GameInviteDeclined:
		case RecNet.Message.MessageType.PartyActivitySwitch:
			break;
		}
	}

	private static void OnInviteReceived(RecNet.Message message)
	{
		Profile profile = Profiles.Get(message.FromPlayerId);
		AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event("received_" + message.Type).WithProperty("fromPlayerId", message.FromPlayerId.ToString());
		if (profile != null)
		{
			amplitudeAnalyticsEventBuilder.WithProperty("fromPlayer", profile.Id.GetDecrypted().ToString()).WithProperty("currentActivity", RecRoomSceneManager.CurrentSceneName);
		}
		SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance.LogEventAsync(amplitudeAnalyticsEventBuilder.Build());
	}

