		PlayerHand.HandType handType2 = ((!(otherHand != null)) ? PlayerHand.HandType.Unknown : otherHand.Type);
		long num = ((!(remotePlayer != null)) ? 0 : remotePlayer.PlayerId);
		AmplitudeAnalyticsClient.Event("handGesture").WithProperty("gesture", gesture.ToString()).WithProperty("myHandType", handType.ToString())
			.WithProperty("otherHandType", handType2.ToString())
			.WithProperty("otherPlayerId", num.ToString())
			.LogAsync();
	}

