	private static AnalyticsJuniorStatus GetJuniorStatusFromProfile(Profile profile)
	{
		if (profile == null)
		{
			return AnalyticsJuniorStatus.Unknown;
		}
		if ((bool)profile.JuniorProfile)
		{
			return AnalyticsJuniorStatus.Jr;
		}
		return AnalyticsJuniorStatus.NonJr;
	}

	private static void WithUserInfo(long photonPlayerId, string propertyBase, AmplitudeAnalyticsEventBuilder ev)
	{
		ev.WithProperty(propertyBase + "_id", photonPlayerId);
		Profile profile = Profiles.Get(photonPlayerId);
		if (profile != null)
		{
			ev.WithProperty(propertyBase + "_rep", profile.Reputation.Noteriety);
			ev.WithProperty(propertyBase + "_level", profile.Level);
			ev.WithProperty(propertyBase + "_platform", profile.PlatformId.Platform.ToString());
		}
		ev.WithProperty(propertyBase + "_jrActType", GetJuniorStatusFromProfile(profile));
		PlayerPresence playerPresence = Presence.Get(photonPlayerId);
		if (playerPresence != null)
		{
			string value = null;
			if (playerPresence.GameSession != null)
			{
				value = playerPresence.GameSession.Name;
				ev.WithProperty(propertyBase + "_roomId", playerPresence.GameSession.RoomId);
			}
			ev.WithProperty(propertyBase + "_activity", value);
			ev.WithProperty(propertyBase + "_isOnline", playerPresence.IsOnline);
			ev.WithProperty(propertyBase + "_playerType", playerPresence.PlayerType);
			ev.WithProperty(propertyBase + "_statusVisibility", playerPresence.StatusVisibility);
		}
		Player player = Player.FindLocalPlayer(photonPlayerId);
		if (player != null)
		{
			GameTeam gameTeam = GameTeam.ANY;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				gameTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(player.PhotonPlayer);
			}
			ev.WithProperty(propertyBase + "_team", gameTeam.ToString());
			ev.WithProperty(propertyBase + "_height", player.CurrentFloorHeightFromHead);
			ev.WithProperty(propertyBase + "_pos", player.CurrentFloorPosition.ToString("F2"));
		}
	}

