	private static void AddVTKInitializationData(AmplitudeAnalyticsEventBuilder ev, bool playerPresent)
	{
		float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
		vtkTimes.Enqueue(realtimeSinceStartup);
		if (playerPresent)
		{
			vtkInitTimes.Enqueue(realtimeSinceStartup);
		}
		float num = realtimeSinceStartup - 600f;
		while (vtkTimes.Count > 0 && vtkTimes.Peek() < num)
		{
			vtkTimes.Dequeue();
		}
		while (vtkInitTimes.Count > 0 && vtkInitTimes.Peek() < num)
		{
			vtkInitTimes.Dequeue();
		}
		ev.WithProperty("r_is_vtk", playerPresent).WithProperty("r_init_count", vtkInitTimes.Count).WithProperty("r_count", vtkTimes.Count);
	}

