	public static void LogPhotonPings()
	{
		AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event("photon_pings");
		int num = int.MaxValue;
		Region region = null;
		foreach (Region availableRegion in PhotonNetwork.networkingPeer.AvailableRegions)
		{
			amplitudeAnalyticsEventBuilder.WithProperty(availableRegion.Code.ToString(), availableRegion.Ping.ToString());
			if (availableRegion.Ping < num)
			{
				num = availableRegion.Ping;
				region = availableRegion;
			}
		}
		if (region != null)
		{
			amplitudeAnalyticsEventBuilder.WithUserProperty("b_reg_ping", num);
			amplitudeAnalyticsEventBuilder.WithUserProperty("b_reg", region.Code.ToString());
		}
		amplitudeAnalyticsEventBuilder.LogAsync();
	}

