	private static AmplitudeAnalyticsEventBuilder RoomEvent(string eventName, long roomId, long subroomId, bool success, string error = null, Dictionary<string, int> photonStats = null)
	{
		AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event(eventName).WithProperty("success", success).WithProperty("error", error)
			.WithProperty("room_name", roomId);
		if (subroomId > 0)
		{
			amplitudeAnalyticsEventBuilder.WithProperty("subroom_name", subroomId);
		}
		RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
		if (cachedRoomDetails != null)
		{
			amplitudeAnalyticsEventBuilder.WithProperty("room_state", cachedRoomDetails.Room.State);
			amplitudeAnalyticsEventBuilder.WithProperty("room_creator", cachedRoomDetails.Room.CreatorPlayerId);
			amplitudeAnalyticsEventBuilder.WithProperty("room_accessibility", cachedRoomDetails.Room.Accessibility);
			amplitudeAnalyticsEventBuilder.WithProperty("room_circuits", CircuitNode.NodeCount);
			if (photonStats != null)
			{
				foreach (KeyValuePair<string, int> photonStat in photonStats)
				{
					amplitudeAnalyticsEventBuilder.WithProperty(photonStat.Key, photonStat.Value);
				}
			}
		}
		if (NetworkedSingletonMonoBehaviour<CreationManager>.IsInitialized)
		{
			amplitudeAnalyticsEventBuilder.WithProperty("room_usage", CreationManager.ActiveSandboxResourceCost);
		}
		return amplitudeAnalyticsEventBuilder;
	}

	public static void QueueEventForPostLogin(string eventName, List<KeyValuePair<string, string>> additionalProperties = null)
	{
		QueuedEventData queuedEventData = new QueuedEventData();
		queuedEventData.eventName = eventName;
		queuedEventData.eventTime = AmplitudeAnalyticsClient.UTCMillisSinceEpoch();
		queuedEventData.properties = additionalProperties;
		queuedEvents.Add(queuedEventData);
	}

	private static void FlushPreLoginEvents()
	{
		for (int i = 0; i < queuedEvents.Count; i++)
		{
			QueuedEventData queuedEventData = queuedEvents[i];
			AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event(queuedEventData.eventName);
			if (queuedEventData.properties != null)
			{
				for (int j = 0; j < queuedEventData.properties.Count; j++)
				{
					KeyValuePair<string, string> keyValuePair = queuedEventData.properties[j];
					amplitudeAnalyticsEventBuilder.WithProperty(keyValuePair.Key, keyValuePair.Value);
				}
			}
			AmplitudeAnalyticsEvent amplitudeAnalyticsEvent = amplitudeAnalyticsEventBuilder.Build();
			amplitudeAnalyticsEvent.OverrideEventTime(queuedEventData.eventTime);
			amplitudeAnalyticsEvent.LogAsync();
		}
		queuedEvents.Clear();
	}
}
public class AttentionMonitor : UnityEngine.MonoBehaviour
{
	private const float COARSE_ANGLE_CHECK_DEGREE_THRESHOLD = 60f;

	[SerializeField]
	private string objectLabel = "add_name_here";

	[SerializeField]
	private float distanceThreshold = 4f;

	[SerializeField]
	private BoxCollider gazeCollisionVolume;

	private void Update()
	{
		bool flag = false;
		string text = "noPlayer";
		if (Player.LocalPlayerExists)
		{
			Transform transform = Player.LocalPlayer.Head.transform;
			Vector3 to = base.transform.position - transform.position;
			text = "watchOpen";
			if (!Player.LocalPlayer.PlayerUI.WatchMenu.FullyVisible)
			{
				text = "distance";
				float sqrMagnitude = to.sqrMagnitude;
				if (sqrMagnitude < distanceThreshold * distanceThreshold)
				{
					text = "angle";
					float num = Vector3.Angle(transform.forward, to);
					if (num < 60f)
					{
						text = "raycast";
						if (gazeCollisionVolume.Raycast(new Ray(transform.position, transform.forward), out var _, distanceThreshold))
						{
							flag = true;
							text = string.Empty;
						}
					}
				}
			}
		}
		if (flag)
		{
			AnalyticsHelper.AccumulateTime(objectLabel, UnityEngine.Time.unscaledDeltaTime);
		}
	}
}
namespace CodeStage.AntiCheat.Detectors
{
	public class HeightChangeCheatDetector : RRCheatDetector
	{
		private bool playerIsSpawned;

		private float nextCheckTime = float.MinValue;

		private int nextFrameFromTeleport = int.MinValue;

		private float? lastFloorHeight;

		[SerializeField]
		private float floorHeightDiffThreshold = 0.15f;

		private SteamVR_Events.Action outOfRangeAction;

		protected override string ComponentName => "HeightChangeDetector";

		public bool HMDReportsTracking { get; private set; }

		protected override void Start()
		{
			base.Start();
			StartCoroutine(RunStart());
		}

		private IEnumerator RunStart()
		{
			while (SingletonMonoBehaviour<PlatformManager>.Instance == null || SingletonMonoBehaviour<SessionManager>.Instance == null)
			{
				yield return null;
			}
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerDespawned += PlayerDespawned;
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += PlayerSpawned;
			if (SingletonMonoBehaviour<PlatformManager>.Instance != null && SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Steam)
			{
				outOfRangeAction = SteamVR_Events.OutOfRangeAction(SteamVROutOfRangeAction);
				outOfRangeAction.enabled = true;
			}
			else if (SingletonMonoBehaviour<PlatformManager>.Instance != null && SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Oculus)
			{
				OVRManager.TrackingAcquired += OnTrackingAcquired;
				OVRManager.TrackingLost += OnTrackingLost;
			}
		}

		private void PlayerSpawned()
		{
			playerIsSpawned = true;
		}

		private void PlayerDespawned()
		{
			playerIsSpawned = false;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerDespawned -= PlayerDespawned;
				SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= PlayerSpawned;
			}
			if (SingletonMonoBehaviour<PlatformManager>.Instance != null && SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Steam)
			{
				if (outOfRangeAction != null)
				{
					outOfRangeAction.enabled = false;
					outOfRangeAction = null;
				}
			}
			else if (SingletonMonoBehaviour<PlatformManager>.Instance != null && SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Oculus)
			{
				OVRManager.TrackingAcquired -= OnTrackingAcquired;
				OVRManager.TrackingLost -= OnTrackingLost;
			}
		}

		private void SteamVROutOfRangeAction(bool outOfRange)
		{
			if (outOfRange)
			{
				OnTrackingLost();
			}
			else
			{
				OnTrackingAcquired();
			}
		}

		private void OnTrackingAcquired()
		{
			HMDReportsTracking = true;
			nextCheckTime = UnityEngine.Time.realtimeSinceStartup + 2f;
		}

		private void OnTrackingLost()
		{
			HMDReportsTracking = false;
		}

		protected override bool CheatDetected()
		{
			if (!HMDReportsTracking)
			{
				return false;
			}
			if (!playerIsSpawned)
			{
				return false;
			}
			if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerLocomotion.IsTeleporting)
			{
				nextFrameFromTeleport = UnityEngine.Time.frameCount + 1;
				return false;
			}
			if (UnityEngine.Time.frameCount <= nextFrameFromTeleport)
			{
				return false;
			}
			float y = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position.y;
			bool result = false;
			if (lastFloorHeight.HasValue && UnityEngine.Time.realtimeSinceStartup > nextCheckTime)
			{
				float num = Mathf.Abs(y - lastFloorHeight.Value);
				if (num >= floorHeightDiffThreshold)
				{
					result = true;
				}
			}
			lastFloorHeight = y;
			return result;
		}
	}
}
namespace Analytics
{
	public class MiscStats : SessionStats
	{
		private const float pctMiscStatEventsToSend = 0.1f;

		private bool forceSend;

		private Dictionary<string, int> counterStats = new Dictionary<string, int>();

		private Dictionary<string, float> timingStats = new Dictionary<string, float>();

		private Dictionary<string, string> manualStats = new Dictionary<string, string>();

		public MiscStats(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
			: base("misc_stats", roomDetails, loadSource, prevRoomId, prevRoomName)
		{
		}

		public static MiscStats Create(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
		{
			return new MiscStats(roomDetails, loadSource, prevRoomId, prevRoomName);
		}

		protected override void LogInternal(AmplitudeAnalyticsEventBuilder eventBuilder)
		{
			foreach (KeyValuePair<string, int> counterStat in counterStats)
			{
				eventBuilder.WithProperty("c_" + counterStat.Key, counterStat.Value);
			}
			foreach (KeyValuePair<string, float> timingStat in timingStats)
			{
				eventBuilder.WithProperty("t_" + timingStat.Key, timingStat.Value.ToString("F2", CultureInfo.InvariantCulture));
			}
			foreach (KeyValuePair<string, string> manualStat in manualStats)
			{
				eventBuilder.WithProperty("m_" + manualStat.Key, manualStat.Value);
			}
		}

		public void IncrementCounter(string counterName)
		{
			AdjustCounter(counterName, 1);
		}

		public void AdjustCounter(string counterName, int adjustAmt)
		{
			int value = 0;
			if (counterStats.TryGetValue(counterName, out value))
			{
				counterStats[counterName] = value + adjustAmt;
			}
			else
			{
				counterStats[counterName] = adjustAmt;
			}
		}

		public void SetCounter(string counterName, int newValue)
		{
			counterStats[counterName] = newValue;
		}

		public void AddToTimer(string timerName, float unscaledDeltaTime)
		{
			float value = 0f;
			if (timingStats.TryGetValue(timerName, out value))
			{
				timingStats[timerName] = value + unscaledDeltaTime;
			}
			else
			{
				timingStats[timerName] = unscaledDeltaTime;
			}
		}

		public void AddManualStat(string statName, string statValue)
		{
			manualStats[statName] = statValue;
		}

		public void ForceSendNextOpportunity()
		{
			forceSend = true;
		}

		protected override bool ShouldLog()
		{
			if (forceSend)
			{
				return true;
			}
			if (counterStats.Count <= 0 && timingStats.Count <= 0 && manualStats.Count <= 0)
			{
				return false;
			}
			if (UnityEngine.Random.Range(0f, 1f) > 0.1f)
			{
				return false;
			}
			return true;
		}
	}
	public class PerfStats : SessionStats
	{
		private const float pctPerfStatEventsToSend = 0.1f;

		private const float updateInterval = 1f;

		private float stdDevFromMeanForDroppedFrame = 2f;

		private int minActivityUpdatesForStdDev = 5;

		private int minActivityUpdatesForLog = 5;

		private int currentActivityFrameCount;

		private float nextUpdate;

		private float accumulatedFPSTime;

		private float accumulatedPingTime;

		public int droppedFrames;

		public int totalFrames;

		private int updateCount;

		private float droppedFrameDelta = float.MaxValue;

		public readonly EWMAStats fpsStats = new EWMAStats();

		public readonly EWMAStats pingStats = new EWMAStats();

		private readonly EWMAStats[] wrapperStats;

		private FramerateRollingWindow fpsRollingWindow = new FramerateRollingWindow(1f);

		public DetailedFramerateStats rollingWindowStats = new DetailedFramerateStats();

		private IDisposable scheduledStatToken;

		private const long TEN_MILLISECOND_TICKS = 100000L;

		private float RollingFramerateThreshold
		{
			get
			{
				if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
				{
					return 27f;
				}
				return 81f;
			}
		}

		private float DroppedFramePerc => ((totalFrames <= 0) ? 0f : ((float)droppedFrames / (float)totalFrames)) * 100f;

		public PerfStats(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
			: base("perf_stats", roomDetails, loadSource, prevRoomId, prevRoomName)
		{
			wrapperStats = new EWMAStats[TimerAnalytics.WrapperKeys.Length];
			for (int i = 0; i < wrapperStats.Length; i++)
			{
				wrapperStats[i] = new EWMAStats();
			}
			RescheduleAggregateWrapperUpdate();
		}

		public static PerfStats Create(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
		{
			return new PerfStats(roomDetails, loadSource, prevRoomId, prevRoomName);
		}

		private void RescheduleAggregateWrapperUpdate()
		{
			if (scheduledStatToken != null)
			{
				scheduledStatToken.Dispose();
			}
			scheduledStatToken = SingletonMonoBehaviour<SessionManager>.Instance.UpdateAtRate(1f, AggregateWrapperStats);
		}

		public override void Update()
		{
			base.Update();
			CheckForTooLongFrame();
			UpdateRawFPSStats();
			UpdateRollingWindowFrameStats();
		}

		protected override void LogInternal(AmplitudeAnalyticsEventBuilder eventBuilder)
		{
			eventBuilder.WithProperty("avg_fps", fpsStats.Mean).WithProperty("min_fps", fpsStats.Min).WithProperty("max_fps", fpsStats.Max)
				.WithProperty("dropped_frames_perc", DroppedFramePerc)
				.WithProperty("avg_ping", pingStats.Mean)
				.WithProperty("min_ping", pingStats.Min)
				.WithProperty("max_ping", pingStats.Max);
			for (int i = 0; i < wrapperStats.Length; i++)
			{
				TimerAnalytics.WrapperKey wrapperKey = (TimerAnalytics.WrapperKey)i;
				EWMAStats eWMAStats = wrapperStats[i];
				string property = $"w_{wrapperKey}_avg";
				float value = (float)(eWMAStats.Mean / 10000.0);
				eventBuilder.WithProperty(property, value);
			}
			if (!double.IsNaN(fpsStats.StdDev))
			{
				eventBuilder.WithProperty("stdev_fps", fpsStats.StdDev);
			}
			if (!double.IsNaN(pingStats.StdDev))
			{
				eventBuilder.WithProperty("stdev_ping", pingStats.StdDev);
			}
			eventBuilder.WithProperty("rw_dropped_frames", rollingWindowStats.totalDrops).WithProperty("rw_dropped_frames_perc", ConvertToPct(rollingWindowStats.totalDrops, rollingWindowStats.totalFrames));
			if (rollingWindowStats.numPlayers_1to2_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_1to2p", rollingWindowStats.numPlayers_1to2_drops).WithProperty("rw_dropped_frames_1to2p_perc", ConvertToPct(rollingWindowStats.numPlayers_1to2_drops, rollingWindowStats.numPlayers_1to2_total));
			}
			if (rollingWindowStats.numPlayers_3to4_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_3to4p", rollingWindowStats.numPlayers_3to4_drops).WithProperty("rw_dropped_frames_3to4p_perc", ConvertToPct(rollingWindowStats.numPlayers_3to4_drops, rollingWindowStats.numPlayers_3to4_total));
			}
			if (rollingWindowStats.numPlayers_5to8_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_5to8p", rollingWindowStats.numPlayers_5to8_drops).WithProperty("rw_dropped_frames_5to8p_perc", ConvertToPct(rollingWindowStats.numPlayers_5to8_drops, rollingWindowStats.numPlayers_5to8_total));
			}
			if (rollingWindowStats.numPlayers_9to12_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_9to12p", rollingWindowStats.numPlayers_9to12_drops).WithProperty("rw_dropped_frames_9to12p_perc", ConvertToPct(rollingWindowStats.numPlayers_9to12_drops, rollingWindowStats.numPlayers_9to12_total));
			}
			if (rollingWindowStats.numPlayers_13to16_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_13to16p", rollingWindowStats.numPlayers_13to16_drops).WithProperty("rw_dropped_frames_13to16_perc", ConvertToPct(rollingWindowStats.numPlayers_13to16_drops, rollingWindowStats.numPlayers_13to16_total));
			}
			if (rollingWindowStats.numPlayers_17plus_total > 0)
			{
				eventBuilder.WithProperty("rw_dropped_frames_17plusp", rollingWindowStats.numPlayers_17plus_drops).WithProperty("rw_dropped_frames_17plusp_perc", ConvertToPct(rollingWindowStats.numPlayers_17plus_drops, rollingWindowStats.numPlayers_17plus_total));
			}
		}

		public override void OnNewSceneLoad(RoomDetails newRoomDetails)
		{
			base.OnNewSceneLoad(newRoomDetails);
			Reset();
			for (int i = 0; i < wrapperStats.Length; i++)
			{
				wrapperStats[i].Reset();
			}
			RescheduleAggregateWrapperUpdate();
		}

		private void AggregateWrapperStats(float deltaTime)
		{
			for (int i = 0; i < TimerAnalytics.WrapperKeys.Length; i++)
			{
				TimerAnalytics.WrapperKey key = TimerAnalytics.WrapperKeys[i];
				TimerAnalytics.CallWrapper wrapper = TimerAnalytics.GetWrapper(key);
				double num = wrapper.AverageStats.Mean;
				if (num > 100000.0)
				{
					num = 100000.0;
				}
				wrapperStats[i].Track(num);
			}
		}

		protected override bool ShouldLog()
		{
			if (updateCount < minActivityUpdatesForLog)
			{
				return false;
			}
			if (Profiles.LocalProfile != null && Profiles.LocalProfile.Developer.GetDecrypted())
			{
				return true;
			}
			if (UnityEngine.Random.Range(0f, 1f) > 0.1f)
			{
				return false;
			}
			return true;
		}

		private void UpdateRawFPSStats()
		{
			currentActivityFrameCount++;
			accumulatedFPSTime += UnityEngine.Time.timeScale / UnityEngine.Time.deltaTime;
			accumulatedPingTime += PhotonNetwork.GetPing();
			if (UnityEngine.Time.time > nextUpdate && currentActivityFrameCount > 0)
			{
				float num = accumulatedFPSTime / (float)currentActivityFrameCount;
				float num2 = accumulatedPingTime / (float)currentActivityFrameCount;
				fpsStats.Track(num);
				pingStats.Track(num2);
				updateCount++;
				droppedFrames += droppedFrames;
				totalFrames += currentActivityFrameCount;
				Reset();
				nextUpdate = UnityEngine.Time.time + 1f;
			}
		}

		private void UpdateRollingWindowFrameStats()
		{
			float rollingFPS = 0f;
			if (!fpsRollingWindow.RecordFrame(UnityEngine.Time.realtimeSinceStartup, out rollingFPS))
			{
				return;
			}
			rollingWindowStats.totalFrames++;
			int num = PhotonNetwork.playerList.Length;
			if (num <= 2)
			{
				rollingWindowStats.numPlayers_1to2_total++;
			}
			else if (num <= 4)
			{
				rollingWindowStats.numPlayers_3to4_total++;
			}
			else if (num <= 8)
			{
				rollingWindowStats.numPlayers_5to8_total++;
			}
			else if (num <= 12)
			{
				rollingWindowStats.numPlayers_9to12_total++;
			}
			else if (num <= 16)
			{
				rollingWindowStats.numPlayers_13to16_total++;
			}
			else
			{
				rollingWindowStats.numPlayers_17plus_total++;
			}
			if (rollingFPS < RollingFramerateThreshold)
			{
				rollingWindowStats.totalDrops++;
				if (num <= 2)
				{
					rollingWindowStats.numPlayers_1to2_drops++;
				}
				else if (num <= 4)
				{
					rollingWindowStats.numPlayers_3to4_drops++;
				}
				else if (num <= 8)
				{
					rollingWindowStats.numPlayers_5to8_drops++;
				}
				else if (num <= 12)
				{
					rollingWindowStats.numPlayers_9to12_drops++;
				}
				else if (num <= 16)
				{
					rollingWindowStats.numPlayers_13to16_drops++;
				}
				else
				{
					rollingWindowStats.numPlayers_17plus_drops++;
				}
			}
		}

		private void CheckForTooLongFrame()
		{
			if (fpsStats.Count > minActivityUpdatesForStdDev)
			{
				droppedFrameDelta = (float)fpsStats.StdDev * stdDevFromMeanForDroppedFrame;
				if (UnityEngine.Time.deltaTime > droppedFrameDelta)
				{
					droppedFrames++;
				}
			}
		}

		private void Reset()
		{
			accumulatedFPSTime = 0f;
			accumulatedPingTime = 0f;
			currentActivityFrameCount = 0;
			droppedFrames = 0;
		}

		private float ConvertToPct(int numPositives, int numSamples)
		{
			return (numSamples > 0) ? ((float)numPositives / (float)numSamples * 100f) : 0f;
		}
	}
	public class DetailedFramerateStats
	{
		public int totalFrames;

		public int totalDrops;

		public int numPlayers_1to2_drops;

		public int numPlayers_3to4_drops;

		public int numPlayers_5to8_drops;

		public int numPlayers_9to12_drops;

		public int numPlayers_13to16_drops;

		public int numPlayers_17plus_drops;

		public int numPlayers_1to2_total;

		public int numPlayers_3to4_total;

		public int numPlayers_5to8_total;

		public int numPlayers_9to12_total;

		public int numPlayers_13to16_total;

		public int numPlayers_17plus_total;
	}
}
[DisallowMultipleComponent]
public class PlayerAnalytics : Photon.MonoBehaviour
{
	[SerializeField]
	private PlayerHandGestures.Gesture[] allowedGesturesArray;

	private string activityName = "lockerroom";

	private Player thisPlayer;

	private bool joinedEmptyActivityTracking;

	private bool isLogActivityEnded;

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
	}

	private void Start()
	{
		thisPlayer = GetComponent<Player>();
		if (isLocal)
		{
			GameSession localGameSession = GameSessions.LocalGameSession;
			int num = PhotonNetwork.playerList.Length;
			if (localGameSession != null && num == 1 && localGameSession.MaxCapacity > 1)
			{
				joinedEmptyActivityTracking = true;
			}
			activityName = RecRoomSceneManager.CurrentSceneName;
			AnalyticsHelper.ActivityLoad(localGameSession);
			UnityEngine.Debug.Log($"Player joined {GameSessions.LocalGameSession.Name} in scene \"{RecRoomSceneManager.CurrentSceneFriendlyName}\" with playerCount {num}");
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			ChallengeEvents.ChallengeEventData challengeEventData = new ChallengeEvents.ChallengeEventData(ChallengeEvents.ChallengeEventTypes.ActivityLoad);
			challengeEventData.SetVar("numPlayers", num);
			ChallengeEvents.Event(challengeEventData);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: false);
			LogActivityEnded();
		}
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
	}

	private void OnApplicationQuit()
	{
		if (isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: false, appQuit: true);
			LogActivityEnded();
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer otherPlayer)
	{
		if (isLocal)
		{
			ProcessJoinedEmptyActivityEnded(anotherPlayerJoined: true, appQuit: false);
		}
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture, Player localPlayer, Player remotePlayer)
	{
		if (isLocal && !allowedGesturesArray.Contains(gesture))
		{
		}
	}

	private void ProcessJoinedEmptyActivityEnded(bool anotherPlayerJoined, bool appQuit)
	{
		if (joinedEmptyActivityTracking)
		{
			joinedEmptyActivityTracking = false;
		}
	}

	private void LogActivityEnded()
	{
		if (!isLogActivityEnded)
		{
			AnalyticsHelper.ActivityUnload(activityName);
			isLogActivityEnded = true;
		}
	}
}
namespace Analytics
{
	public class RoomStats : SessionStats
	{
		private float totalTime;

		private string playerRoomRole = string.Empty;

		private RoomAccessibility savedRoomAccessibility = RoomAccessibility.Public;

		private bool sessionIsPrivate;

		private bool supportsScreens;

		private bool supportsWalkVR;

		private bool supportsTeleportVR;

		private bool didGameStart;

		private float TimeBeforeGameStart;

		private bool hasLoadTimeInformation;

		private double lastLoadDuration;

		private bool wasMasterForLastLoad;

		private int creatorPlayerId;

		private string creatorUsername;

		private string venueName;

		private bool bookmarked;

		private bool cheered;

		private bool subscribed;

		private bool reported;

		private int circuitCount;

		private float sceneLoadTime;

		public RoomStats(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
			: base("room_stats", roomDetails, loadSource, prevRoomId, prevRoomName)
		{
			playerRoomRole = roomDetails.LocalPlayerRole.ToString();
			savedRoomAccessibility = roomDetails.Room.Accessibility;
			sessionIsPrivate = GameSessions.LocalGameSession.Private;
			isPlayerCreated = !roomDetails.Room.IsAGRoom;
			supportsScreens = roomDetails.Room.SupportsScreens;
			supportsWalkVR = roomDetails.Room.SupportsWalkVR;
			supportsTeleportVR = roomDetails.Room.SupportsTeleportVR;
			creatorPlayerId = roomDetails.Room.CreatorPlayerId;
			creatorUsername = Profiles.Get(creatorPlayerId)?.Username;
			sceneLoadTime = UnityEngine.Time.realtimeSinceStartup;
		}

		public static RoomStats Create(RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
		{
			return new RoomStats(roomDetails, loadSource, prevRoomId, prevRoomName);
		}

		public override void Update()
		{
			base.Update();
		}

		protected override void LogInternal(AmplitudeAnalyticsEventBuilder eventBuilder)
		{
			totalTime = UnityEngine.Time.realtimeSinceStartup - sceneLoadTime;
			eventBuilder.WithProperty("total_time", totalTime.ToString("F2", CultureInfo.InvariantCulture)).WithProperty("is_private", sessionIsPrivate).WithProperty("game_started", didGameStart)
				.WithProperty("supports_walkvr", supportsWalkVR)
				.WithProperty("supports_teleportvr", supportsTeleportVR)
				.WithProperty("supports_screens", supportsScreens)
				.WithProperty("time_to_game_start", (!didGameStart) ? 0f : TimeBeforeGameStart)
				.WithProperty("player_room_role", playerRoomRole)
				.WithProperty("room_accessibility", savedRoomAccessibility)
				.WithProperty("creator_id", creatorPlayerId)
				.WithProperty("creator_name", creatorUsername)
				.WithProperty("bookmarked", bookmarked ? 1 : 0)
				.WithProperty("cheered", cheered ? 1 : 0)
				.WithProperty("subscribed", subscribed ? 1 : 0)
				.WithProperty("reported", reported ? 1 : 0)
				.WithProperty("circuit_count", circuitCount);
			if (hasLoadTimeInformation)
			{
				eventBuilder.WithProperty("loadTime", lastLoadDuration);
				eventBuilder.WithProperty("loadWasMaster", wasMasterForLastLoad);
				hasLoadTimeInformation = false;
			}
		}

		public override void OnActualLoadTimeData(double loadTimeSeconds, bool masterDuringLoad)
		{
			base.OnActualLoadTimeData(loadTimeSeconds, masterDuringLoad);
			hasLoadTimeInformation = true;
			lastLoadDuration = loadTimeSeconds;
			wasMasterForLastLoad = masterDuringLoad;
		}

		public override void OnGameStart()
		{
			didGameStart = true;
			TimeBeforeGameStart = UnityEngine.Time.timeSinceLevelLoad;
		}

		public void UpdateCircuitCount(int newCount)
		{
			circuitCount = newCount;
		}

		public void BookmarkPerformed(bool value = true)
		{
			bookmarked = value;
		}

		public void CheerPerformed()
		{
			cheered = true;
		}

		public void SubscribePerformed()
		{
			subscribed = true;
		}

		public void ReportPerformed()
		{
			reported = true;
		}
	}
}
namespace CodeStage.AntiCheat.Detectors
{
	public abstract class RRCheatDetector : ActDetectorBase
	{
		private static string logPrefix;

		private const long TICKS_PER_SECOND = 10000000L;

		private static int instancesInScene;

		[Tooltip("Time (in seconds) between detector checks.")]
		public float interval = 1f;

		[Tooltip("Maximum false positives count allowed before registering speed hack.")]
		public byte maxFalsePositives = 3;

		[Tooltip("Amount of sequential successful checks before clearing internal false positives counter.\nSet 0 to disable Cool Down feature.")]
		public int coolDown = 30;

		public bool CheckForCheatEveryFrame;

		private byte currentFalsePositives;

		private int currentCooldownShots;

		private long ticksOnStart;

		private long prevTicks;

		private long prevIntervalTicks;

		protected abstract string ComponentName { get; }

		protected static string LogPrefix
		{
			get
			{
				if (logPrefix == null)
				{
					logPrefix = ((!(Instance != null)) ? string.Empty : Instance.ComponentName) + ": ";
				}
				return logPrefix;
			}
		}

		public static RRCheatDetector Instance { get; private set; }

		private static RRCheatDetector GetOrCreateInstance
		{
			get
			{
				if (Instance != null)
				{
					return Instance;
				}
				if (ActDetectorBase.detectorsContainer == null)
				{
					ActDetectorBase.detectorsContainer = new GameObject("Anti-Cheat Toolkit Detectors");
				}
				Instance = ActDetectorBase.detectorsContainer.AddComponent<RRCheatDetector>();
				return Instance;
			}
		}

		public static void StartDetection()
		{
			if (Instance != null)
			{
				Instance.StartDetectionInternal(null, Instance.interval, Instance.maxFalsePositives, Instance.coolDown);
			}
			else
			{
				UnityEngine.Debug.LogError(LogPrefix + "can't be started since it doesn't exists in scene or not yet initialized!");
			}
		}

		public static void StartDetection(UnityAction callback)
		{
			StartDetection(callback, GetOrCreateInstance.interval);
		}

		public static void StartDetection(UnityAction callback, float interval)
		{
			StartDetection(callback, interval, GetOrCreateInstance.maxFalsePositives);
		}

		public static void StartDetection(UnityAction callback, float interval, byte maxFalsePositives)
		{
			StartDetection(callback, interval, maxFalsePositives, GetOrCreateInstance.coolDown);
		}

		public static void StartDetection(UnityAction callback, float interval, byte maxFalsePositives, int coolDown)
		{
			GetOrCreateInstance.StartDetectionInternal(callback, interval, maxFalsePositives, coolDown);
		}

		public static void StopDetection()
		{
			if (Instance != null)
			{
				Instance.StopDetectionInternal();
			}
		}

		public static void Dispose()
		{
			if (Instance != null)
			{
				Instance.DisposeInternal();
			}
		}

		private void Awake()
		{
			instancesInScene++;
			if (Init(Instance, ComponentName))
			{
				Instance = this;
			}
			SceneManager.sceneLoaded += OnLevelWasLoadedNew;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			instancesInScene--;
			SceneManager.sceneLoaded -= OnLevelWasLoadedNew;
		}

		private void OnLevelWasLoadedNew(Scene scene, LoadSceneMode mode)
		{
			OnLevelLoadedCallback();
		}

		private void OnLevelLoadedCallback()
		{
			if (instancesInScene < 2)
			{
				if (!keepAlive)
				{
					DisposeInternal();
				}
			}
			else if (!keepAlive && Instance != this)
			{
				DisposeInternal();
			}
		}

		private void OnApplicationPause(bool pause)
		{
			if (!pause)
			{
				ResetStartTicks();
			}
		}

		private void Update()
		{
			if (!isRunning)
			{
				return;
			}
			long ticks = DateTime.UtcNow.Ticks;
			long num = ticks - prevTicks;
			if (num < 0 || num > 10000000)
			{
				ResetStartTicks();
				return;
			}
			prevTicks = ticks;
			long num2 = (long)(interval * 10000000f);
			bool flag = false;
			if (CheckForCheatEveryFrame)
			{
				flag = CheatDetected();
			}
			if (ticks - prevIntervalTicks >= num2)
			{
				if (!CheckForCheatEveryFrame)
				{
					flag = CheatDetected();
				}
				if (!flag && currentFalsePositives > 0 && coolDown > 0)
				{
					currentCooldownShots++;
					if (currentCooldownShots >= coolDown)
					{
						currentFalsePositives = 0;
					}
				}
				prevIntervalTicks = ticks;
			}
			if (flag)
			{
				currentFalsePositives++;
				if (currentFalsePositives > maxFalsePositives)
				{
					OnCheatingDetected();
					return;
				}
				currentCooldownShots = 0;
				ResetStartTicks();
			}
		}

		protected abstract bool CheatDetected();

		private void StartDetectionInternal(UnityAction callback, float checkInterval, byte falsePositives, int shotsTillCooldown)
		{
			if (!isRunning && base.enabled)
			{
				if (callback == null || detectionEventHasListener)
				{
				}
				if (callback == null && !detectionEventHasListener)
				{
					base.enabled = false;
					return;
				}
				detectionAction = callback;
				interval = checkInterval;
				maxFalsePositives = falsePositives;
				coolDown = shotsTillCooldown;
				ResetStartTicks();
				currentFalsePositives = 0;
				currentCooldownShots = 0;
				started = true;
				isRunning = true;
			}
		}

		protected override void StartDetectionAutomatically()
		{
			StartDetectionInternal(null, interval, maxFalsePositives, coolDown);
		}

		protected override void PauseDetector()
		{
			isRunning = false;
		}

		protected override void ResumeDetector()
		{
			if (detectionAction != null || detectionEventHasListener)
			{
				isRunning = true;
			}
		}

		protected override void StopDetectionInternal()
		{
			if (started)
			{
				detectionAction = null;
				started = false;
				isRunning = false;
			}
		}

		protected override void DisposeInternal()
		{
			base.DisposeInternal();
			if (Instance == this)
			{
				Instance = null;
			}
		}

		private void ResetStartTicks()
		{
			ticksOnStart = DateTime.UtcNow.Ticks;
			prevTicks = ticksOnStart;
			prevIntervalTicks = ticksOnStart;
		}
	}
}
namespace Analytics
{
	public abstract class SessionStats
	{
		protected string EventName;

		protected SessionManager.LoadSceneSources LoadSource;

		protected int NumScenesInRoom;

		protected bool isPlayerCreated;

		protected long PrevRoomId;

		protected string PrevRoomName;

		protected int NumSubRoomsVisited;

		private bool HasBeenSent;

		public long RoomId { get; protected set; }

		public string RoomName { get; protected set; }

		public SessionStats(string eventName, RoomDetails roomDetails, SessionManager.LoadSceneSources loadSource, long prevRoomId, string prevRoomName)
		{
			EventName = eventName;
			RoomId = roomDetails.Room.RoomId;
			RoomName = roomDetails.Room.Name;
			NumScenesInRoom = roomDetails.Scenes.Count;
			LoadSource = loadSource;
			isPlayerCreated = !roomDetails.Room.IsAGRoom;
			PrevRoomId = prevRoomId;
			PrevRoomName = prevRoomName;
			NumSubRoomsVisited = 1;
		}

		public bool MatchesRoom(RoomDetails roomDetails)
		{
			return roomDetails != null && RoomId == roomDetails.Room.RoomId;
		}

		public void Log(RoomDetails nextRoomDetails, SessionManager.LoadSceneSources nextRoomLoadSource)
		{
			if (HasBeenSent)
			{
				UnityEngine.Debug.LogWarningFormat("Tried to send SessionStats twice (room name: {0})", RoomName);
			}
			else if (ShouldLog())
			{
				AmplitudeAnalyticsEventBuilder amplitudeAnalyticsEventBuilder = AmplitudeAnalyticsClient.Event(EventName).WithProperty("room_id", RoomId).WithProperty("room_name", RoomName)
					.WithProperty("num_scenes_in_room", NumScenesInRoom)
					.WithProperty("load_source", LoadSource)
					.WithProperty("player_created", isPlayerCreated)
					.WithProperty("num_scene_visits", NumSubRoomsVisited);
				if (!string.IsNullOrEmpty(PrevRoomName))
				{
					amplitudeAnalyticsEventBuilder.WithProperty("prev_room_id", PrevRoomId);
					amplitudeAnalyticsEventBuilder.WithProperty("prev_room_name", PrevRoomName);
				}
				if (nextRoomDetails != null)
				{
					amplitudeAnalyticsEventBuilder.WithProperty("next_room_id", nextRoomDetails.Room.RoomId);
					amplitudeAnalyticsEventBuilder.WithProperty("next_room_name", nextRoomDetails.Room.Name);
				}
				amplitudeAnalyticsEventBuilder.WithProperty("next_room_loadSource", nextRoomLoadSource);
				LogInternal(amplitudeAnalyticsEventBuilder);
				amplitudeAnalyticsEventBuilder.LogAsync();
				HasBeenSent = true;
			}
		}

		public virtual void Update()
		{
		}

		protected virtual bool ShouldLog()
		{
			return true;
		}

		protected virtual void LogInternal(AmplitudeAnalyticsEventBuilder eventBuilder)
		{
		}

		public virtual void OnNewSceneLoad(RoomDetails newRoomDetails)
		{
			NumSubRoomsVisited++;
		}

		public virtual void OnActualLoadTimeData(double loadTimeSeconds, bool masterDuringLoad)
		{
		}

		public virtual void OnGameStart()
		{
		}
	}
}
namespace RecRoom.Analytics
{
	public class RollingBufferAverageStats : IAveragedStats
	{
		public int MaxBufferLength;

		private readonly Queue<double> valuesBuffer;

		private double min = 9.223372036854776E+18;

		private double max = -9.223372036854776E+18;

		private double sum;

		public int BufferCount
		{
			[CompilerGenerated]
			get
			{
				return valuesBuffer.Count;
			}
		}

		public double Mean
		{
			[CompilerGenerated]
			get
			{
				return (valuesBuffer.Count <= 0) ? 0.0 : (sum / (double)valuesBuffer.Count);
			}
		}

		public double Min
		{
			[CompilerGenerated]
			get
			{
				return min;
			}
		}

		public double Max
		{
			[CompilerGenerated]
			get
			{
				return max;
			}
		}

		public RollingBufferAverageStats(int maxBufferLength)
		{
			MaxBufferLength = maxBufferLength;
			valuesBuffer = new Queue<double>(MaxBufferLength + 1);
		}

		public void Track(double val)
		{
			valuesBuffer.Enqueue(val);
			sum += val;
			min = Math.Min(min, val);
			max = Math.Max(max, val);
			while (valuesBuffer.Count > MaxBufferLength)
			{
				double num = valuesBuffer.Dequeue();
				sum -= num;
			}
		}

		public void Reset()
		{
			valuesBuffer.Clear();
			sum = 0.0;
			min = double.MaxValue;
			max = double.MinValue;
		}
	}
	public class EWMAStats : IAveragedStats
	{
		private long count;

		private double mean;

		private double m2;

		private double variance;

		private double stdDev;

		private double min = 9.223372036854776E+18;

		private double max = -9.223372036854776E+18;

		public long Count => count;

		public double Min => min;

		public double Max => max;

		public double Variance => variance;

		public double StdDev => stdDev;

		public double Mean => mean;

		public void Track(double val)
		{
			min = Math.Min(val, min);
			max = Math.Max(val, max);
			count++;
			double num = val - mean;
			mean += num / (double)count;
			double num2 = val - mean;
			m2 += num * num2;
			variance = ((count < 2) ? double.NaN : (m2 / (double)(count - 1)));
			stdDev = Math.Sqrt(variance);
		}

		public void Reset()
		{
			count = 0L;
			mean = 0.0;
			m2 = 0.0;
			variance = 0.0;
			stdDev = 0.0;
			min = double.MaxValue;
			max = double.MinValue;
		}
	}
	public interface IAveragedStats
	{
		double Mean { get; }

		double Min { get; }

		double Max { get; }

		void Track(double val);

		void Reset();
	}
}
