		public float roomLF;

		[Range(0.1f, 20f)]
		public float decayTime = 5f;

		[Range(0.1f, 2f)]
		public float decayHFRatio = 0.5f;

		[Range(-10000f, 1000f)]
		public float reflectionsLevel = -10000f;

		[Range(0f, 0.3f)]
		public float reflectionsDelay;

		[Range(-10000f, 2000f)]
		public float reverbLevel;

		[Range(0f, 0.1f)]
		public float reverbDelay = 0.04f;

		[Range(1000f, 20000f)]
		public float hfReference = 5000f;

		[Range(20f, 1000f)]
		public float lfReference = 250f;

		[Range(0f, 100f)]
		public float diffusion = 100f;

		[Range(0f, 100f)]
		public float density = 100f;
	}

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private AudioFilterDelegate m_AudioFilter;

	[SerializeField]
	private AudioEffectSettings[] effectSettings;

	public AudioLowPassFilter LowPassFilter { get; set; }

	public AudioHighPassFilter HighPassFilter { get; set; }

	public AudioReverbFilter ReverbFilter { get; set; }

	public AudioEffectType LastAudioEffectType { get; private set; }

	public event AudioFilterDelegate AudioFilter
	{
		add
		{
			AudioFilterDelegate audioFilterDelegate = this.m_AudioFilter;
			AudioFilterDelegate audioFilterDelegate2;
			do
			{
				audioFilterDelegate2 = audioFilterDelegate;
				audioFilterDelegate = Interlocked.CompareExchange(ref this.m_AudioFilter, (AudioFilterDelegate)Delegate.Combine(audioFilterDelegate2, value), audioFilterDelegate);
			}
			while (audioFilterDelegate != audioFilterDelegate2);
		}
		remove
		{
			AudioFilterDelegate audioFilterDelegate = this.m_AudioFilter;
			AudioFilterDelegate audioFilterDelegate2;
			do
			{
				audioFilterDelegate2 = audioFilterDelegate;
				audioFilterDelegate = Interlocked.CompareExchange(ref this.m_AudioFilter, (AudioFilterDelegate)Delegate.Remove(audioFilterDelegate2, value), audioFilterDelegate);
			}
			while (audioFilterDelegate != audioFilterDelegate2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		LowPassFilter = GetComponent<AudioLowPassFilter>();
		HighPassFilter = GetComponent<AudioHighPassFilter>();
		ReverbFilter = GetComponent<AudioReverbFilter>();
		LastAudioEffectType = AudioEffectType.None;
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		SceneManager.sceneLoaded -= SceneManager_sceneLoaded;
	}

	public void ApplyAudioEffect(AudioEffectType type)
	{
		LastAudioEffectType = type;
		AudioEffectSettings audioEffectSettings = ((type == AudioEffectType.None || effectSettings == null) ? null : effectSettings.Where((AudioEffectSettings s) => s.effectType == type).FirstOrDefault());
		if (audioEffectSettings != null)
		{
			if (LowPassFilter != null)
			{
				LowPassFilter.enabled = audioEffectSettings.applyLowPass;
				LowPassFilter.cutoffFrequency = audioEffectSettings.lowPassCutoffFrequency;
			}
			if (HighPassFilter != null)
			{
				HighPassFilter.enabled = audioEffectSettings.applyHighPass;
			}
			if (ReverbFilter != null)
			{
				ReverbFilter.enabled = audioEffectSettings.applyReverb;
				ReverbFilter.dryLevel = audioEffectSettings.dryLevel;
				ReverbFilter.room = audioEffectSettings.room;
				ReverbFilter.roomHF = audioEffectSettings.roomHF;
				ReverbFilter.roomLF = audioEffectSettings.roomLF;
				ReverbFilter.decayTime = audioEffectSettings.decayTime;
				ReverbFilter.decayHFRatio = audioEffectSettings.decayHFRatio;
				ReverbFilter.reflectionsLevel = audioEffectSettings.reflectionsLevel;
				ReverbFilter.reflectionsDelay = audioEffectSettings.reflectionsDelay;
				ReverbFilter.reverbLevel = audioEffectSettings.reverbLevel;
				ReverbFilter.reverbDelay = audioEffectSettings.reverbDelay;
				ReverbFilter.hfReference = audioEffectSettings.hfReference;
				ReverbFilter.lfReference = audioEffectSettings.lfReference;
				ReverbFilter.diffusion = audioEffectSettings.diffusion;
				ReverbFilter.density = audioEffectSettings.density;
			}
		}
		else
		{
			if (LowPassFilter != null)
			{
				LowPassFilter.enabled = false;
			}
			if (HighPassFilter != null)
			{
				HighPassFilter.enabled = false;
			}
			if (ReverbFilter != null)
			{
				ReverbFilter.enabled = false;
			}
		}
	}

	private void SceneManager_sceneLoaded(Scene arg0, LoadSceneMode arg1)
	{
		ApplyAudioEffect(AudioEffectType.None);
	}

	private void OnAudioFilterRead(float[] samples, int channels)
	{
		this.AudioFilter?.Invoke(samples, channels);
	}
