			musicMixer.Update();
		}
	}

	public void Initialize()
	{
		if (MasterMixer.GetFloat("SFXVolume", out var value))
		{
			sfxMixerVolumeDefault = (currentSFXVolume = (targetSFXVolume = value));
		}
		if (MasterMixer.GetFloat("MusicVolume", out var value2))
		{
			musicMixerVolumeDefault = (currentMusicVolume = (targetMusicVolume = value2));
		}
		if (MasterMixer.GetFloat("AmbienceVolume", out var value3))
		{
			ambienceMixerVolumeDefault = (currentAmbienceVolume = (targetAmbienceVolume = value3));
		}
		if (MasterMixer.GetFloat("VoiceVolume", out var value4))
		{
			voiceMixerVolumeDefault = (currentVoiceVolume = (targetVoiceVolume = value4));
		}
		if (MasterMixer.GetFloat("NonCoachVolume", out value4))
		{
			nonCoachVolumeDefault = (currentNonCoachVolume = (targetNonCoachVolume = value4));
		}
		MusicVolumePercentage = RecroomPrefs.GetFloat(MUSIC_VOLUME_PERCENT_PREF, 1f);
		AmbienceVolumePercentage = RecroomPrefs.GetFloat(AMBIENCE_VOLUME_PERCENT_PREF, 1f);
		SfxVolumePercentage = RecroomPrefs.GetFloat(SFX_VOLUME_PERCENT_PREF, 1f);
		VoiceVolumePercentage = RecroomPrefs.GetFloat(VOICE_VOLUME_PERCENT_PREF, 1f);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.None, MasterMixer.FindMatchingGroups("VOIP_Master")[0]);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.Radio, MasterMixer.FindMatchingGroups("VOIP_Radio")[0]);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.LowPitch, MasterMixer.FindMatchingGroups("VOIP_LowPitch")[0]);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.HighPitch, MasterMixer.FindMatchingGroups("VOIP_HighPitch")[0]);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.RadioLowPitch, MasterMixer.FindMatchingGroups("VOIP_Radio_LowPitch")[0]);
		VOIPFilterAudioMixerGroups.Add(VOIPFilter.RadioHighPitch, MasterMixer.FindMatchingGroups("VOIP_Radio_HighPitch")[0]);
		initialized = true;
	}

	public IEnumerator RunChangeAudioVolume(AudioSource audio, float from, float to, float duration)
	{
		audio.volume = from;
		float timer = 0f;
		while (timer <= duration)
		{
			timer += UnityEngine.Time.deltaTime;
			float alpha = Mathf.Clamp01(timer / duration);
			audio.volume = Mathf.Lerp(from, to, alpha);
			yield return null;
		}
	}

	public void SetSourceToVOIPMixer(AudioSource source, VOIPFilter filter)
	{
		AudioMixerGroup vOIPMixerOutput = GetVOIPMixerOutput(filter);
		source.outputAudioMixerGroup = vOIPMixerOutput;
	}

	private void UpdateSFXVolume()
	{
		bool flag = false;
		if (!SingletonMonoBehaviour<PlatformManager>.Instance.HasVRFocus)
		{
			targetSFXVolume = ApplyPercentToDB(SFXMixerVolumeMuted, SfxVolumePercentage);
			sfxVolumeLowered = true;
			lastSFXVolumeLoweredTime = UnityEngine.Time.time;
		}
		else if (!sfxVolumeLowered && flag)
		{
			targetSFXVolume = ApplyPercentToDB(SFXMixerVolumeLow, SfxVolumePercentage);
			sfxVolumeLowered = true;
			lastSFXVolumeLoweredTime = UnityEngine.Time.time;
		}
		else if (sfxVolumeLowered && UnityEngine.Time.time - lastSFXVolumeLoweredTime > 1f)
		{
			targetSFXVolume = ApplyPercentToDB(sfxMixerVolumeDefault, SfxVolumePercentage);
			sfxVolumeLowered = false;
		}
		if (VoiceVolumeLowered)
		{
			targetVoiceVolume = ApplyPercentToDB(VoiceMixerVolumeLow, VoiceVolumePercentage);
		}
		else
		{
			targetVoiceVolume = ApplyPercentToDB(voiceMixerVolumeDefault, VoiceVolumePercentage);
		}
		if (currentSFXVolume != targetSFXVolume)
		{
			currentSFXVolume = Mathf.SmoothStep(currentSFXVolume, targetSFXVolume, UnityEngine.Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("SFXVolume", currentSFXVolume);
		}
		if (currentMusicVolume != targetMusicVolume)
		{
			currentMusicVolume = Mathf.SmoothStep(currentMusicVolume, targetMusicVolume, UnityEngine.Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("MusicVolume", currentMusicVolume);
		}
		if (currentAmbienceVolume != targetAmbienceVolume)
		{
			currentAmbienceVolume = Mathf.SmoothStep(currentAmbienceVolume, targetAmbienceVolume, UnityEngine.Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("AmbienceVolume", currentAmbienceVolume);
		}
		if (currentVoiceVolume != targetVoiceVolume)
		{
			currentVoiceVolume = Mathf.SmoothStep(currentVoiceVolume, targetVoiceVolume, UnityEngine.Time.deltaTime * sfxVolumeInterpolationSpeed);
			MasterMixer.SetFloat("VoiceVolume", currentVoiceVolume);
		}
	}

	private void UpdateNonCoachVolume()
	{
		bool flag = SingletonMonoBehaviour<TutorialManager>.IsInitialized && SingletonMonoBehaviour<TutorialManager>.Instance.IsPlayingVO;
		targetNonCoachVolume = ((!flag) ? nonCoachVolumeDefault : NonCoachVolumeLow);
		if (currentNonCoachVolume != targetNonCoachVolume)
		{
			currentNonCoachVolume = Mathf.SmoothStep(currentNonCoachVolume, targetNonCoachVolume, UnityEngine.Time.deltaTime * nonCoachVolumeInterpolationSpeed);
			MasterMixer.SetFloat("NonCoachVolume", currentNonCoachVolume);
		}
	}

	private float ApplyPercentToDB(float volume, float percent)
	{
		float num = volume + 80f;
		return num * Mathf.Log10(percent.ReMapRange(new Vector2(0f, 1f), new Vector2(1f, 10f))) - 80f;
	}

	private AudioMixerGroup GetVOIPMixerOutput(VOIPFilter filter)
	{
		AudioMixerGroup value = null;
		VOIPFilterAudioMixerGroups.TryGetValue(filter, out value);
		return value;
	}

	private void UpdateMicrophoneDevice()
	{
		string desiredMicrophoneDevice = GetDesiredMicrophoneDeviceName();
		if (!string.IsNullOrEmpty(desiredMicrophoneDevice) && desiredMicrophoneDevice != PhotonVoiceNetwork.MicrophoneDevice && !microphoneInputDetector.IsAlreadyListening(desiredMicrophoneDevice))
		{
			this.InvokeNextEndOfFrame(delegate
			{
				microphoneInputDetector.StartListening(desiredMicrophoneDevice, UpdatePhotonVoiceMicrophone);
			});
		}
	}

	private void UpdatePhotonVoiceMicrophone(string microphoneDeviceName)
	{
		PhotonVoiceNetwork.MicrophoneDevice = microphoneDeviceName;
		AnalyticsHelper.MarkHasMicrophone(hasMicrophone: true);
	}

	private string GetDesiredMicrophoneDeviceName()
	{
		string result = null;
		if (Microphone.devices.Length > 0)
		{
			result = Microphone.devices[0];
			switch (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareType)
			{
			case PlatformManager.HardwareType.OCULUS:
			{
				string text2 = Microphone.devices.FirstOrDefault((string d) => d.Contains("Rift"));
				if (text2 != null)
				{
					result = text2;
				}
				break;
			}
			case PlatformManager.HardwareType.PSVR:
			{
				string text = Microphone.devices.FirstOrDefault((string d) => d.Contains("VOICE_CHAT"));
				if (text != null)
				{
					result = text;
				}
				break;
			}
			}
		}
		return result;
	}

