	public static SFXAudioSource PlayRandom2DSFX(RecRoomAudioClip[] clips, Vector3 point, bool allowRepeat = false, float volumeScaler = 1f, Action<SFXAudioSource> onAudioSourceReleasedCallback = null)
	{
		if (clips == null)
		{
			UnityEngine.Debug.Log("Warning: SFX array is null.");
			return null;
		}
		if (clips.Length == 0)
		{
			return null;
		}
		int num = (last2DClipNumber = GetRandomClipNumber(clips.Length, last2DClipNumber, allowRepeat));
		float volume = clips[num].volume * volumeScaler;
		return PlaySFX(SFXType._2D, clips[num].audioClip, point, volume, clips[num].pitchVariation, clips[num].pitchShift, null, onAudioSourceReleasedCallback);
	}

