	public static void PlayMusic(RecRoomAudioClip music, float startTime, bool loop)
	{
		if (music != null && !(SingletonMonoBehaviour<AudioManager>.Instance == null))
		{
			AudioSource audioSource = SingletonMonoBehaviour<AudioManager>.Instance.musicAudioSource;
			if (audioSource.isPlaying)
			{
				audioSource.Stop();
			}
			if (music.audioClip != null)
			{
				audioSource.loop = loop;
				audioSource.volume = music.volume;
				audioSource.clip = music.audioClip;
				audioSource.time = startTime % music.audioClip.length;
				audioSource.Play();
			}
			if (AudioManager.MusicStartStopEvent != null)
			{
				AudioManager.MusicStartStopEvent();
			}
		}
	}

