	private static SFXAudioSource PlaySFX(SFXType type, AudioClip clip, Vector3 point, float volume, float pitchVariation, float pitchShift, AudioRolloff customRolloff = null, Action<SFXAudioSource> onAudioSourceReleasedCallback = null)
	{
		if (clip == null || SingletonMonoBehaviour<AudioManager>.Instance == null)
		{
			return null;
		}
		SFXAudioSource sFXAudioSource = null;
		switch (type)
		{
		case SFXType._2D:
			sFXAudioSource = ObjectPool.Instance.Acquire(SingletonMonoBehaviour<AudioManager>.Instance.sfx2DAudioSourcePrefab);
			break;
		case SFXType._3D:
			sFXAudioSource = ObjectPool.Instance.Acquire(SingletonMonoBehaviour<AudioManager>.Instance.sfx3DAudioSourcePrefab);
			break;
		}
		if (sFXAudioSource != null)
		{
			sFXAudioSource.Play(clip, volume, point, pitchVariation, pitchShift, (customRolloff == null) ? SingletonMonoBehaviour<AudioManager>.Instance.sfxRolloffMap.LatestValue : customRolloff, onAudioSourceReleasedCallback);
		}
		return sFXAudioSource;
	}

	private static int GetRandomClipNumber(int arrayLength, int lastClipNumber, bool allowRepeat)
	{
		if (!allowRepeat && arrayLength == 1)
		{
			allowRepeat = true;
		}
		int num = UnityEngine.Random.Range(0, arrayLength);
		if (!allowRepeat && num == lastClipNumber)
		{
			num = ++num % arrayLength;
		}
		return num;
	}

	static AudioManager()
	{
		AudioManager.PlayerVoiceRolloffChangeEvent = null;
		AudioManager.MusicStartStopEvent = null;
		last2DClipNumber = 0;
		last3DClipNumber = 0;
		MUSIC_VOLUME_PERCENT_PREF = "MUSIC_VOLUME_PERCENT_PREF";
		AMBIENCE_VOLUME_PERCENT_PREF = "AMBIENCE_VOLUME_PERCENT_PREF";
		VOICE_VOLUME_PERCENT_PREF = "VOICE_VOLUME_PERCENT_PREF";
		SFX_VOLUME_PERCENT_PREF = "SFX_VOLUME_PERCENT_PREF";
	}
