namespace RecRoom.Core.Audio
{
	public class AudioPitchBendFilter : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.SelfAndParent, false)]
		[SerializeField]
		private RigidbodyEx rigidbodyEx;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private AudioSource audioSource;

		[SerializeField]
		[Range(-3f, 3f)]
		private float maxPitch = 1.5f;

		[SerializeField]
		[Range(-3f, 3f)]
		private float minPitch = 1f;

		[SerializeField]
		private float maxSpeed = 5f;

		private void Awake()
		{
			rigidbodyEx.LateUpdateEvent += UpdatePitch;
		}

		private void OnDestroy()
		{
			rigidbodyEx.LateUpdateEvent += UpdatePitch;
		}

		private void UpdatePitch(RigidbodyEx rigidbodyEx)
		{
			rigidbodyEx.GetWorldKinematicVelocitiesAtWorldSpacePoint(base.transform.position, 0f, 0f, ControllerVelocitySettings.VelocityAverageMethod.AVERAGE_DIRECTION_AVERAGE_MAGNITUDE, ControllerVelocitySettings.VelocityAverageMethod.AVERAGE_DIRECTION_AVERAGE_MAGNITUDE, out var linearVelocity, out var _);
			float magnitude = linearVelocity.magnitude;
			float t = Mathf.InverseLerp(0f, maxSpeed, magnitude);
			audioSource.pitch = Mathf.Lerp(minPitch, maxPitch, t);
		}
	}
}
public class AudioReverbZoneVolumeTrigger : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private AudioListenerSingleton.AudioEffectType customAudioEffectType;

	private OverlapVolume[] overlapVolumes;

	private bool zonesActive;

	private int _refCount;

	private AudioListenerSingleton.AudioEffectType previousEffectType;

	private int overlapReferenceCount
	{
		get
		{
			return _refCount;
		}
		set
		{
			_refCount = value;
			if (_refCount <= 0 && zonesActive)
			{
				_refCount = 0;
				SetZonesActive(active: false);
			}
			else if (_refCount > 0 && !zonesActive)
			{
				SetZonesActive(active: true);
			}
		}
	}

	private void Awake()
	{
		SetZonesActive(active: false);
		overlapVolumes = GetComponentsInChildren<OverlapVolume>(includeInactive: true);
		if (overlapVolumes != null && overlapVolumes.Length > 0)
		{
			OverlapVolume[] array = overlapVolumes;
			foreach (OverlapVolume overlapVolume in array)
			{
				overlapVolume.LocalPlayerVolumeEnterEvent += OnLocalPlayerVolumeEnterEvent;
				overlapVolume.LocalPlayerVolumeExitEvent += OnLocalPlayerVolumeExitEvent;
			}
		}
		else
		{
			UnityEngine.Debug.LogWarning("AudioReverbZoneVolumeTrigger does not have any volumes under itself.", base.gameObject);
		}
	}

	private void OnDestroy()
	{
		SetZonesActive(active: false);
		if (overlapVolumes != null && overlapVolumes.Length > 0)
		{
			OverlapVolume[] array = overlapVolumes;
			foreach (OverlapVolume overlapVolume in array)
			{
				overlapVolume.LocalPlayerVolumeEnterEvent -= OnLocalPlayerVolumeEnterEvent;
				overlapVolume.LocalPlayerVolumeExitEvent -= OnLocalPlayerVolumeExitEvent;
			}
		}
	}

	private void OnLocalPlayerVolumeExitEvent()
	{
		overlapReferenceCount--;
	}

	private void OnLocalPlayerVolumeEnterEvent()
	{
		overlapReferenceCount++;
	}

	private void SetZonesActive(bool active)
	{
		if (SingletonMonoBehaviour<AudioListenerSingleton>.Instance != null)
		{
			zonesActive = active;
			if (active)
			{
				previousEffectType = SingletonMonoBehaviour<AudioListenerSingleton>.Instance.LastAudioEffectType;
				SingletonMonoBehaviour<AudioListenerSingleton>.Instance.ApplyAudioEffect(customAudioEffectType);
			}
			else
			{
				SingletonMonoBehaviour<AudioListenerSingleton>.Instance.ApplyAudioEffect(previousEffectType);
			}
		}
	}
}
public class CollisionAudio : UnityEngine.MonoBehaviour
{
	private class CollisionRecord
	{
		public GameObject Collider;

		public float CollisionTime;
	}

	[Serializable]
	public class AudioClipsToLayer
	{
		public string Name;

		public LayerMask Layers;

		public string Tag = string.Empty;

		public AnimationCurve velocityToVolumeCurve;

		public RecRoomAudioClip[] Clips;

		[Tooltip("Per clip cooldown to limit the number of consecutive audios. Set it to 0 for most clips")]
		public float InstanceLimitDuration;

		public float LastInstanceTime { get; set; }

		public bool CanPlay(GameObject go)
		{
			int num = 1 << go.layer;
			if ((UnityEngine.Time.time <= InstanceLimitDuration || UnityEngine.Time.time - LastInstanceTime > InstanceLimitDuration) && (Layers.value & num) != 0 && (string.IsNullOrEmpty(Tag) || go.CompareTag(Tag)))
			{
				LastInstanceTime = UnityEngine.Time.time;
				return true;
			}
			return false;
		}
	}

	private const float MAX_COLLISION_MAGNITUDE = 25f;

	private float MIN_COLLISION_COOLDOWN_TIME = 0.1f;

	[SerializeField]
	private AudioClipsToLayer[] audioMappings;

	[SerializeField]
	private bool useCustomRolloff;

	[SerializeField]
	private AudioRolloff customRolloff;

	[SerializeField]
	[Tooltip("MeleeWeaponColliders that can trigger the collision audio in addition to normal physics collisions.")]
	private MeleeWeaponCollider[] meleeWeaponColliders;

	private List<CollisionRecord> collisionHistory = new List<CollisionRecord>();

	private bool enableCollisionEnter;

	private IEnumerator Start()
	{
		yield return null;
		enableCollisionEnter = true;
	}

	private void OnEnable()
	{
		MeleeWeaponCollider[] array = meleeWeaponColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.AnyImpactEvent += OnMeleeColliderImpact;
		}
	}

	private void OnDisable()
	{
		enableCollisionEnter = true;
		MeleeWeaponCollider[] array = meleeWeaponColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.AnyImpactEvent -= OnMeleeColliderImpact;
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (enableCollisionEnter && collision.contacts.Length > 0)
		{
			ProcessCollision(collision.collider.gameObject, collision.contacts[0].point, collision.contacts[0].normal, collision.relativeVelocity);
		}
	}

	private void OnMeleeColliderImpact(MeleeWeaponCollider thisCollider, WeaponImpact impact)
	{
		ProcessCollision(impact.GameObject, impact.Point, impact.SurfaceNormal, impact.Velocity);
	}

	private void ProcessCollision(GameObject colliderObject, Vector3 impactPoint, Vector3 impactNormal, Vector3 impactVelocity)
	{
		if (!enableCollisionEnter)
		{
			return;
		}
		CollisionRecord collisionRecord = null;
		foreach (CollisionRecord item in collisionHistory)
		{
			if (item.Collider == colliderObject)
			{
				collisionRecord = item;
				break;
			}
		}
		bool flag = collisionRecord == null || UnityEngine.Time.time - collisionRecord.CollisionTime > MIN_COLLISION_COOLDOWN_TIME;
		if (collisionRecord == null)
		{
			CollisionRecord collisionRecord2 = new CollisionRecord();
			collisionRecord2.Collider = colliderObject;
			collisionRecord2.CollisionTime = UnityEngine.Time.time;
			collisionRecord = collisionRecord2;
			collisionHistory.Add(collisionRecord);
		}
		else
		{
			collisionRecord.CollisionTime = UnityEngine.Time.time;
		}
		if (!flag)
		{
			return;
		}
		float magnitude = Vector3.Project(impactVelocity, impactNormal).magnitude;
		AudioClipsToLayer[] array = audioMappings;
		foreach (AudioClipsToLayer audioClipsToLayer in array)
		{
			if (audioClipsToLayer.CanPlay(colliderObject))
			{
				float volumeScalar = ((audioClipsToLayer.velocityToVolumeCurve == null || audioClipsToLayer.velocityToVolumeCurve.length <= 0) ? Mathf.Clamp01(magnitude / 25f) : audioClipsToLayer.velocityToVolumeCurve.Evaluate(Mathf.Clamp01(magnitude / 25f)));
				if (useCustomRolloff)
				{
					AudioManager.PlayRandom3DSFX(audioClipsToLayer.Clips, impactPoint, customRolloff, allowRepeat: false, volumeScalar);
				}
				else
				{
					AudioManager.PlayRandom3DSFX(audioClipsToLayer.Clips, impactPoint, null, allowRepeat: false, volumeScalar);
				}
				break;
			}
		}
	}
}
public class MicrophoneInputDetector : UnityEngine.MonoBehaviour
{
	private const float MIN_SAMPLE_INPUT_THRESHOLD = 1E-05f;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private AudioSource audioSource;

	private string activeListeningMicrophoneName;

	private ISchedulerPromise listenPromise;

	public bool InputDetected { get; private set; }

	private void Awake()
	{
		audioSource.loop = true;
		audioSource.mute = true;
	}

	public bool IsAlreadyListening(string microphoneDeviceName)
	{
		return listenPromise != null && !listenPromise.IsCompleted && activeListeningMicrophoneName == microphoneDeviceName;
	}

	public void StartListening(string microphoneDeviceName, Action<string> inputDetectedCallback)
	{
		if (listenPromise != null && !listenPromise.IsCompleted)
		{
			listenPromise.Dispose();
			listenPromise = null;
		}
		listenPromise = SingletonMonoBehaviour<Scheduler>.Instance.Run(ListenCoroutine(microphoneDeviceName, inputDetectedCallback));
		listenPromise.Finally(delegate
		{
			CleanupCoroutineState();
		});
	}

	private IEnumerator<ISchedule> ListenCoroutine(string microphoneDeviceName, Action<string> inputDetectedCallback)
	{
		activeListeningMicrophoneName = microphoneDeviceName;
		InputDetected = false;
		if (!string.IsNullOrEmpty(microphoneDeviceName))
		{
			audioSource.clip = SharedMicrophone.GetMicrophone(microphoneDeviceName, (int)PhotonVoiceSettings.Instance.SamplingRate);
			audioSource.Play();
			ScheduleWait wait = new ScheduleWait(0.05f);
			float[] samples = new float[256];
			do
			{
				yield return wait;
			}
			while (!AudioSourceHasInput(samples, microphoneDeviceName));
		}
		InputDetected = true;
		inputDetectedCallback?.Invoke(microphoneDeviceName);
	}

	private void CleanupCoroutineState()
	{
		activeListeningMicrophoneName = null;
		audioSource.Stop();
		audioSource.clip = null;
	}

	private bool AudioSourceHasInput(float[] samples, string microphoneDeviceName)
	{
		bool result = false;
		if (audioSource.clip != null)
		{
			int position = Microphone.GetPosition(microphoneDeviceName);
			audioSource.clip.GetData(samples, position);
			for (int i = 0; i < samples.Length; i++)
			{
				if (samples[i] >= 1E-05f)
				{
					result = true;
					break;
				}
			}
		}
		return result;
	}
}
public class MusicMixer
{
	private enum MusicStates
	{
		NONE,
		LOADING,
		GAMEPLAY,
		ACTION,
		ACTION_EXTENDED,
		FANFARE
	}

	private abstract class MusicStateBase
	{
		public float FadeInTime;

		protected RecRoomAudioClip currentClip;

		protected bool isPlaying;

		protected bool isEnqueued;

		protected MusicMixer musicMixer;

		protected bool repeat;

		protected bool continueInBackground;

		protected float scrubTime;

		protected float startTime;

		public int Priority { get; private set; }

		public abstract bool HasClips { get; }

		public bool IsFinished { get; private set; }

		public MusicStateBase(int priority, MusicMixer musicMixer, bool repeat, bool continueInBackground)
		{
			IsFinished = false;
			scrubTime = 0f;
			Priority = priority;
			this.musicMixer = musicMixer;
			this.repeat = repeat;
			this.continueInBackground = continueInBackground;
		}

		public void OnEnqueue()
		{
			isEnqueued = true;
			IsFinished = false;
			isPlaying = false;
			if (continueInBackground)
			{
				startTime = UnityEngine.Time.time;
			}
			SelectNewCurrentClip();
		}

		public void OnDequeue()
		{
			isEnqueued = false;
		}

		public void Play()
		{
			if (!isPlaying)
			{
				isPlaying = true;
				bool flag = AudioManager.IsPlayingMusic() && currentClip != null && AudioManager.CurrentMusicAudioClip() == currentClip.audioClip;
				if (continueInBackground || flag)
				{
					scrubTime = UnityEngine.Time.time - startTime;
				}
				else
				{
					startTime = UnityEngine.Time.time - scrubTime;
				}
				PlayCurrentClip(FadeInTime);
			}
		}

		public void Pause()
		{
			if (isPlaying)
			{
				isPlaying = false;
				scrubTime = AudioManager.GetMusicTime();
			}
		}

		public virtual void Restart()
		{
			if (isPlaying)
			{
				startTime = UnityEngine.Time.time;
				PlayCurrentClip(0f);
			}
		}

		public virtual void Update()
		{
			if (currentClip == null || currentClip.audioClip == null)
			{
				IsFinished = true;
			}
			else if (!repeat)
			{
				IsFinished = UnityEngine.Time.time - startTime >= currentClip.audioClip.length;
			}
		}

		protected abstract void SelectNewCurrentClip();

		protected void OnLatestClipChange()
		{
			if (isEnqueued)
			{
				SelectNewCurrentClip();
				if (isPlaying && currentClip != null && AudioManager.CurrentMusicAudioClip() != currentClip.audioClip)
				{
					PlayCurrentClip(FadeInTime);
				}
			}
		}

		private void PlayCurrentClip(float fadeTime)
		{
			musicMixer.PlayMusic(currentClip, repeat, scrubTime, fadeTime);
		}
	}

	private class SingleClipMusicState : MusicStateBase
	{
		private TokenMap<RecRoomAudioClip> musicMap = new TokenMap<RecRoomAudioClip>();

		public override bool HasClips => musicMap.ContainsValues;

		public SingleClipMusicState(int priority, MusicMixer musicMixer, bool repeat, bool continueInBackground)
			: base(priority, musicMixer, repeat, continueInBackground)
		{
		}

		public void AddMusicClip(RecRoomAudioClip musicClip, object token)
		{
			musicMap.AddValue(musicClip, token);
			OnLatestClipChange();
		}

		public void RemoveMusicClip(object token)
		{
			musicMap.RemoveValue(token);
			OnLatestClipChange();
		}

		protected override void SelectNewCurrentClip()
		{
			currentClip = musicMap.LatestValue;
			if (currentClip != null && AudioManager.CurrentMusicAudioClip() != currentClip.audioClip)
			{
				scrubTime = 0f;
			}
		}
	}

	private class ExtendedMusicState : MusicStateBase
	{
		private TokenMap<ExtendedRecRoomAudioClips> musicMap = new TokenMap<ExtendedRecRoomAudioClips>();

		public override bool HasClips => musicMap.ContainsValues;

		public ExtendedMusicState(int priority, MusicMixer musicMixer, bool continueInBackground)
			: base(priority, musicMixer, repeat: true, continueInBackground)
		{
		}

		public void AddMusicClip(ExtendedRecRoomAudioClips musicClip, object token)
		{
			musicMap.AddValue(musicClip, token);
			OnLatestClipChange();
		}

		public void RemoveMusicClip(object token)
		{
			musicMap.RemoveValue(token);
			OnLatestClipChange();
		}

		public override void Update()
		{
			base.Update();
			ExtendedRecRoomAudioClips latestValue = musicMap.LatestValue;
			if (latestValue != null && latestValue.ExtendedClip != null && currentClip != latestValue.ExtendedClip && (currentClip == null || currentClip.audioClip == null || UnityEngine.Time.time - startTime >= currentClip.audioClip.length) && isPlaying && isEnqueued)
			{
				currentClip = latestValue.ExtendedClip;
				musicMixer.PlayMusic(currentClip, repeat, 0f);
			}
		}

		protected override void SelectNewCurrentClip()
		{
			ExtendedRecRoomAudioClips latestValue = musicMap.LatestValue;
			if (latestValue != null && latestValue.RandomClips != null && latestValue.RandomClips.Length > 0)
			{
				currentClip = latestValue.RandomClips[UnityEngine.Random.Range(0, latestValue.RandomClips.Length)];
				if (currentClip != null && AudioManager.CurrentMusicAudioClip() != currentClip.audioClip)
				{
					scrubTime = 0f;
				}
			}
		}
	}

	private Coroutine musicTrackChangeCoroutine;

	private List<MusicStateBase> musicPriorityQueue = new List<MusicStateBase>();

	private SingleClipMusicState gameplayMusicState;

	private ExtendedMusicState actionMusicState;

	private SingleClipMusicState overrideMusicState;

	private SingleClipMusicState powerupMusicState;

	private SingleClipMusicState fanfareMusicState;

	private SingleClipMusicState loadingMusicState;

	public MusicMixer()
	{
		gameplayMusicState = new SingleClipMusicState(0, this, repeat: true, continueInBackground: false);
		actionMusicState = new ExtendedMusicState(10, this, continueInBackground: false);
		overrideMusicState = new SingleClipMusicState(25, this, repeat: true, continueInBackground: false);
		powerupMusicState = new SingleClipMusicState(50, this, repeat: false, continueInBackground: true);
		fanfareMusicState = new SingleClipMusicState(100, this, repeat: false, continueInBackground: true);
		loadingMusicState = new SingleClipMusicState(1000, this, repeat: false, continueInBackground: false);
	}

	public void Update()
	{
		if (musicPriorityQueue.Count > 0)
		{
			MusicStateBase musicStateBase = musicPriorityQueue[musicPriorityQueue.Count - 1];
			musicStateBase.Update();
			if (musicStateBase.IsFinished)
			{
				DequeueMusic(musicStateBase);
			}
		}
	}

	public void AddLoadingMusic(RecRoomAudioClip loadingMusic, object token)
	{
		loadingMusicState.AddMusicClip(loadingMusic, token);
	}

	public void RemoveLoadingMusic(object token)
	{
		loadingMusicState.RemoveMusicClip(token);
	}

	public void PlayLoadingMusic()
	{
		EnqueueMusic(loadingMusicState);
	}

	public void StopLoadingMusic()
	{
		DequeueMusic(loadingMusicState);
	}

	public void AddGameplayMusic(RecRoomAudioClip gameplayMusic, object token)
	{
		gameplayMusicState.AddMusicClip(gameplayMusic, token);
	}

	public void RemoveGameplayMusic(object token)
	{
		gameplayMusicState.RemoveMusicClip(token);
	}

	public void PlayGameplayMusic()
	{
		EnqueueMusic(gameplayMusicState);
	}

	public void StopGameplayMusic()
	{
		DequeueMusic(gameplayMusicState);
	}

	public void AddActionMusic(ExtendedRecRoomAudioClips actionMusic, object token)
	{
		actionMusicState.AddMusicClip(actionMusic, token);
	}

	public void RemoveActionMusic(object token)
	{
		actionMusicState.RemoveMusicClip(token);
	}

	public void PlayActionMusic()
	{
		EnqueueMusic(actionMusicState);
	}

	public void StopActionMusic()
	{
		DequeueMusic(actionMusicState);
	}

	public void AddPowerupMusic(RecRoomAudioClip powerupMusic, object token)
	{
		powerupMusicState.AddMusicClip(powerupMusic, token);
	}

	public void RemovePowerupMusic(object token)
	{
		powerupMusicState.RemoveMusicClip(token);
	}

	public void PlayPowerupMusic()
	{
		EnqueueMusic(powerupMusicState, restartIfAlreadyPlaying: true);
	}

	public void StopPowerupMusic()
	{
		DequeueMusic(powerupMusicState);
	}

	public void AddOverrideMusic(RecRoomAudioClip overrideMusic, object token)
	{
		overrideMusicState.AddMusicClip(overrideMusic, token);
	}

	public void RemoveOverrideMusic(object token)
	{
		overrideMusicState.RemoveMusicClip(token);
	}

	public void PlayOverrideMusic()
	{
		EnqueueMusic(overrideMusicState);
	}

	public void StopOverrideMusic()
	{
		DequeueMusic(overrideMusicState);
	}

	public void AddFanfareMusic(RecRoomAudioClip fanfareMusic, object token)
	{
		fanfareMusicState.AddMusicClip(fanfareMusic, token);
	}

	public void RemoveFanfareMusic(object token)
	{
		fanfareMusicState.RemoveMusicClip(token);
	}

	public void PlayFanfareMusic()
	{
		EnqueueMusic(fanfareMusicState);
	}

	public void StopFanfareMusic()
	{
		DequeueMusic(fanfareMusicState);
	}

	public void StopAllMusic()
	{
		if (musicPriorityQueue.Count > 0)
		{
			FadeOutMusicAndStop(0.5f);
		}
		while (musicPriorityQueue.Count > 0)
		{
			DequeueMusic(musicPriorityQueue[musicPriorityQueue.Count - 1]);
		}
	}

	public void SetGameplayMusicFadeInTime(float fadeInTime)
	{
		gameplayMusicState.FadeInTime = fadeInTime;
	}

	public void SetActionMusicFadeInTime(float fadeInTime)
	{
		actionMusicState.FadeInTime = fadeInTime;
	}

	public void SetOverrideMusicFadeInTime(float fadeInTime)
	{
		overrideMusicState.FadeInTime = fadeInTime;
	}

	private void StartChangeMusicCoroutine(RecRoomAudioClip newTrack, bool newTrackLoops, float scrubTime, float previousTrackFadeoutDuration)
	{
		StopChangeMusicCoroutine();
		musicTrackChangeCoroutine = SingletonMonoBehaviour<AudioManager>.Instance.StartCoroutine(ChangeMusicCoroutine(newTrack, newTrackLoops, scrubTime, previousTrackFadeoutDuration));
	}

	private void StopChangeMusicCoroutine()
	{
		if (musicTrackChangeCoroutine != null)
		{
			SingletonMonoBehaviour<AudioManager>.Instance.StopCoroutine(musicTrackChangeCoroutine);
			musicTrackChangeCoroutine = null;
		}
	}

	private IEnumerator ChangeMusicCoroutine(RecRoomAudioClip newTrack, bool newTrackLoops, float scrubTime, float previousTrackFadeoutDuration)
	{
		if (AudioManager.IsPlayingMusic())
		{
			yield return AudioManager.FadeMusic(0f, previousTrackFadeoutDuration);
		}
		if (newTrack == null)
		{
			AudioManager.StopMusic();
		}
		else
		{
			AudioManager.PlayMusic(newTrack, scrubTime, newTrackLoops);
		}
	}

	internal void PlayMusic(RecRoomAudioClip newMusicTrack, bool newTrackLoops, float previousTrackFadeoutDuration)
	{
		PlayMusic(newMusicTrack, newTrackLoops, 0f, previousTrackFadeoutDuration);
	}

	internal void PlayMusic(RecRoomAudioClip newMusicTrack, bool newTrackLoops, float scrubTime, float previousTrackFadeoutDuration)
	{
		StartChangeMusicCoroutine(newMusicTrack, newTrackLoops, scrubTime, previousTrackFadeoutDuration);
	}

	private void FadeOutMusicAndStop(float fadeOutDuration)
	{
		StartChangeMusicCoroutine(null, newTrackLoops: false, 0f, fadeOutDuration);
	}

	private void StopMusicImmediately()
	{
		AudioManager.StopMusic();
	}

	private void EnqueueMusic(MusicStateBase musicState, bool restartIfAlreadyPlaying = false)
	{
		if (musicState.HasClips)
		{
			if (!musicPriorityQueue.Contains(musicState))
			{
				musicPriorityQueue.Add(musicState);
				musicState.OnEnqueue();
				ApplyMusicPriorityQueueChange();
			}
			else if (restartIfAlreadyPlaying)
			{
				musicState.Restart();
			}
		}
	}

	private void DequeueMusic(MusicStateBase musicState)
	{
		if (musicPriorityQueue.Contains(musicState))
		{
			musicPriorityQueue.Remove(musicState);
			musicState.OnDequeue();
			ApplyMusicPriorityQueueChange();
		}
	}

	private void ApplyMusicPriorityQueueChange()
	{
		musicPriorityQueue.Sort((MusicStateBase a, MusicStateBase b) => a.Priority.CompareTo(b.Priority));
		for (int num = 0; num < musicPriorityQueue.Count; num++)
		{
			if (num < musicPriorityQueue.Count - 1)
			{
				musicPriorityQueue[num].Pause();
			}
			else
			{
				musicPriorityQueue[num].Play();
			}
		}
		if (musicPriorityQueue.Count == 0)
		{
			FadeOutMusicAndStop(0.5f);
		}
	}
}
