	public void SetFilterType(AudioManager.VOIPFilter filter)
	{
		if (IsRadioVoiceEnabled)
		{
			filter = ((thisPlayer.VOIPFilter == AudioManager.VOIPFilter.LowPitch) ? AudioManager.VOIPFilter.RadioLowPitch : ((thisPlayer.VOIPFilter != AudioManager.VOIPFilter.HighPitch) ? AudioManager.VOIPFilter.Radio : AudioManager.VOIPFilter.RadioHighPitch));
		}
		SingletonMonoBehaviour<AudioManager>.Instance.SetSourceToVOIPMixer(thisPlayer.VoiceAudioSource, filter);
	}

	public void SetRadioVoice(bool enableRadio, float setRadioVolume = 1f)
	{
		thisPlayer.VoiceAudioSource.spatialBlend = ((!enableRadio) ? 1f : radioSpatialBlend);
		thisPlayer.VoiceAudioSource.volume = ((!enableRadio) ? 1f : setRadioVolume);
		IsRadioVoiceEnabled = enableRadio;
		SetFilterType(thisPlayer.VOIPFilter);
	}

	public void AddVoiceAudioRolloff(AudioRolloff rolloff, object token, int priority)
	{
		PlayerAudioRolloffMap.AddValue(rolloff, token, priority);
		UpdateToLastestVoiceRolloff();
	}

	public void RemoveVoiceAudioRolloff(object token)
	{
		PlayerAudioRolloffMap.RemoveValue(token);
		UpdateToLastestVoiceRolloff();
	}

	private void UpdateToLastestVoiceRolloff()
	{
		AudioRolloff highestPriorityValue = PlayerAudioRolloffMap.HighestPriorityValue;
		if (thisPlayer != null && thisPlayer.VoiceAudioSource != null)
		{
			thisPlayer.VoiceAudioSource.SetAudioRolloff(highestPriorityValue);
		}
	}

	private void OnGlobalPlayerVoiceRolloffChange()
	{
		AudioRolloff playerVoiceRolloff = AudioManager.GetPlayerVoiceRolloff();
		if (playerVoiceRolloff != null && SingletonMonoBehaviour<AudioManager>.Instance != null)
		{
			AddVoiceAudioRolloff(playerVoiceRolloff, SingletonMonoBehaviour<AudioManager>.Instance, 1000);
		}
	}
