namespace RecRoom.Core.Audio
{
	public class ShakeAudio : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public class ShakeDefinition
		{
			public float MinimumLinearAcceleration = 50f;

			public float MaximumLinearAcceleration = 1000f;

			public float MinimumAngularAcceleration = 80f;

			public float MaximumAngularAcceleration = 1000f;

			public float MinimumInterval = 0.3f;

			public RecRoomAudioClip[] AudioClips;

			private float lastPlayTime;

			public bool CanPlay(float linearAcceleration, float angularAcceleration)
			{
				if (UnityEngine.Time.time < lastPlayTime + MinimumInterval)
				{
					return false;
				}
				bool flag = false;
				if (linearAcceleration >= MinimumLinearAcceleration && linearAcceleration <= MaximumLinearAcceleration)
				{
					flag = true;
				}
				bool flag2 = false;
				if (angularAcceleration >= MinimumAngularAcceleration && angularAcceleration <= MaximumAngularAcceleration)
				{
					flag2 = true;
				}
				return flag || flag2;
			}

			public void Play(Transform followTarget)
			{
				if (AudioClips != null && AudioClips.Length > 0)
				{
					RecRoomAudioClip recClip = AudioClips[UnityEngine.Random.Range(0, AudioClips.Length)];
					AudioManager.Play3DSFX(recClip, followTarget);
				}
				lastPlayTime = UnityEngine.Time.time;
			}
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[SerializeField]
		private bool onlyPlayAudioWhileHeldByPlayer;

		[SerializeField]
		private float lookBackStartTime = 0.1f;

		[SerializeField]
		private float lookBackEndTime = 0.05f;

		[SerializeField]
		private ShakeDefinition[] shakeDefinitions;

		private void Start()
		{
			if (tool.RigidbodyEx != null)
			{
				tool.RigidbodyEx.LateUpdateEvent += OnVelocityUpdate;
			}
		}

		private void OnDestroy()
		{
			tool.RigidbodyEx.LateUpdateEvent -= OnVelocityUpdate;
		}

		private void OnVelocityUpdate(RigidbodyEx rigidbodyEx)
		{
			if (!base.enabled || (onlyPlayAudioWhileHeldByPlayer && (tool == null || !tool.IsHeld || !tool.IsHeldByPlayer)))
			{
				return;
			}
			Vector3 maximumHistoricalKinematicLinearVelocity = tool.RigidbodyEx.GetMaximumHistoricalKinematicLinearVelocity(lookBackStartTime, lookBackEndTime);
			Vector3 maximumHistoricalKinematicAngularVelocity = tool.RigidbodyEx.GetMaximumHistoricalKinematicAngularVelocity(lookBackStartTime, lookBackEndTime);
			Vector3 vector = tool.RigidbodyEx.velocity - maximumHistoricalKinematicLinearVelocity;
			Vector3 vector2 = tool.RigidbodyEx.angularVelocity - maximumHistoricalKinematicAngularVelocity;
			float magnitude = (vector / lookBackEndTime).magnitude;
			float magnitude2 = (vector2 / lookBackEndTime).magnitude;
			for (int i = 0; i < shakeDefinitions.Length; i++)
			{
				if (shakeDefinitions[i].CanPlay(magnitude, magnitude2))
				{
					shakeDefinitions[i].Play(base.transform);
				}
			}
		}
	}
}
public static class SharedMicrophone
{
	private static Dictionary<string, AudioClip> microphones = new Dictionary<string, AudioClip>();

	private static AudioClip nullMicrophone = null;

	public static AudioClip GetMicrophone(string device, int suggestedFrequency)
	{
		AudioClip value = null;
		if (device == null)
		{
			if (nullMicrophone == null)
			{
				nullMicrophone = CreateMicrophone(device, suggestedFrequency);
			}
			value = nullMicrophone;
		}
		else if (!microphones.TryGetValue(device, out value))
		{
			value = CreateMicrophone(device, suggestedFrequency);
			microphones.Add(device, value);
		}
		return value;
	}

	private static AudioClip CreateMicrophone(string device, int suggestedFrequency)
	{
		Microphone.GetDeviceCaps(device, out var minFreq, out var maxFreq);
		int frequency = suggestedFrequency;
		if (suggestedFrequency < minFreq || (maxFreq != 0 && suggestedFrequency > maxFreq))
		{
			frequency = maxFreq;
		}
		return Microphone.Start(device, loop: true, 1, frequency);
	}

	public static void EndMicrophone(string device)
	{
		AudioClip value = null;
		if (device == null)
		{
			nullMicrophone = null;
		}
		else if (microphones.TryGetValue(device, out value))
		{
			microphones.Remove(device);
		}
		if (Microphone.IsRecording(device))
		{
			Microphone.End(device);
		}
	}
}
