namespace RecRoom.Audio
{
	public class VoiceAudioRolloffZone : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private AudioRolloff rolloff;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private SimpleVolume zoneVolume;

		private void Start()
		{
			this.Update1hz(UpdateRoutine);
		}

		private void UpdateRoutine(float deltaTime)
		{
			UpdatePlayerVoiceAudioRolloff();
		}

		private void UpdatePlayerVoiceAudioRolloff()
		{
			if (!SingletonMonoBehaviour<AudioManager>.IsInitialized)
			{
				return;
			}
			foreach (Player item in Player.All)
			{
				if (zoneVolume.ContainsPoint(item.TrackingSpace.transform.position))
				{
					item.PlayerAudio.AddVoiceAudioRolloff(rolloff, this, 10001);
				}
				else
				{
					item.PlayerAudio.RemoveVoiceAudioRolloff(this);
				}
			}
		}
	}
}
