namespace RecRoom.Core
{
	public class BlobShadowProjector : UnityEngine.MonoBehaviour
	{
		public enum ShadowType
		{
			SIMPLE_TEXTURE,
			PROJECTED_RENDERERS
		}

		private struct ShadowCaster
		{
			public Renderer Renderer;

			public int SubMeshCount;

			public ShadowCastingMode InitialShadowCastingMode;
		}

		private const int PROJECTED_RENDERERS_TEXTURE_RESOLUTION = 256;

		private const int PROJECTED_RENDERERS_ANTI_ALIASING = 8;

		private static readonly Quaternion WORLD_ALIGNED_ROTATION = Quaternion.LookRotation(-Vector3.up, Vector3.forward);

		private static Material _shadowCasterMaterial = null;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Projector projector;

		[SerializeField]
		private ShadowType defaultShadowType;

		[Header("Simple Shadow Settings")]
		[SerializeField]
		private Material simpleShadowMaterial;

		[SerializeField]
		private float simpleTextureOrthographicProjectionSize = 0.3f;

		[Header("Position")]
		[SerializeField]
		private float desiredPositionAboveParent = 0.25f;

		private ShadowType shadowType;

		private RenderTexture renderTexture;

		private List<ShadowCaster> shadowCasters = new List<ShadowCaster>();

		private List<int> shadowCasterIndicesToRemove = new List<int>();

		private Material cachedMaterial;

		private IDisposable updateToken;

		private CommandBuffer commandBuffer;

		private Camera cachedCamera;

		private TokenFlag restrictedFlag = new TokenFlag();

		private Vector3 nextPosition = Vector3.zero;

		private Quaternion nextRotation = Quaternion.identity;

		private float nextOrthographicSize = 1f;

		private static readonly Vector3[] SH_SAMPLE_VECTORS = new Vector3[1] { Vector3.up };

		private static readonly Color[] SH_SAMPLE_COLORS = new Color[1] { Color.black };

		private static Material ShadowCasterMaterial
		{
			get
			{
				if (_shadowCasterMaterial == null)
				{
					_shadowCasterMaterial = new Material(Resources.Load<Material>("legacy_BlobShadowCaster_mat"));
				}
				return _shadowCasterMaterial;
			}
		}

		public void AddBlobShadowsRestriction(object token)
		{
			restrictedFlag.Add(token);
			OnRestrictionChange();
		}

		public void RemoveBlobShadowsRestriction(object token)
		{
			restrictedFlag.Remove(token);
			OnRestrictionChange();
		}

		public void SetShadowType(ShadowType shadowType)
		{
			CleanupPreviousMode();
			this.shadowType = shadowType;
			switch (this.shadowType)
			{
			case ShadowType.SIMPLE_TEXTURE:
				InitializeSimpleTextureMode();
				break;
			case ShadowType.PROJECTED_RENDERERS:
				InitializeProjectedRenderersMode();
				break;
			}
		}

		public void AddShadowCaster(Renderer renderer)
		{
			if (renderer is SkinnedMeshRenderer)
			{
				AddShadowCaster((SkinnedMeshRenderer)renderer);
			}
			else if (renderer is MeshRenderer)
			{
				AddShadowCaster((MeshRenderer)renderer);
			}
		}

		public void AddShadowCaster(MeshRenderer renderer)
		{
			MeshFilter component = renderer.gameObject.GetComponent<MeshFilter>();
			if (component != null)
			{
				AddShadowCaster(renderer, component.sharedMesh.subMeshCount);
			}
		}

		public void AddShadowCaster(SkinnedMeshRenderer renderer)
		{
			AddShadowCaster(renderer, renderer.sharedMesh.subMeshCount);
		}

		public void AddShadowCaster(Renderer renderer, int submeshCount)
		{
			shadowCasters.Add(new ShadowCaster
			{
				Renderer = renderer,
				SubMeshCount = submeshCount,
				InitialShadowCastingMode = renderer.shadowCastingMode
			});
			if (base.gameObject.activeSelf)
			{
				EnableUnityShadowCasting(shadowCasters.Count - 1, enabled: false);
			}
		}

		public void RemoveShadowCaster(Renderer renderer)
		{
			int index = shadowCasters.FindIndex((ShadowCaster r) => r.Renderer == renderer);
			RemoveShadowCasterAtIndex(index);
		}

		private void RemoveShadowCasterAtIndex(int index)
		{
			if (index >= 0)
			{
				EnableUnityShadowCasting(index, enabled: true);
				shadowCasters.RemoveAt(index);
			}
		}

		private void Start()
		{
			Color value = Color.black;
			if (RenderSettings.ambientMode == AmbientMode.Skybox)
			{
				RenderSettings.ambientProbe.Evaluate(SH_SAMPLE_VECTORS, SH_SAMPLE_COLORS);
				value = SH_SAMPLE_COLORS[0];
			}
			else if (RenderSettings.ambientMode == AmbientMode.Trilight)
			{
				value = Color.Lerp(RenderSettings.ambientEquatorColor, RenderSettings.ambientSkyColor, 0.8f);
			}
			else if (RenderSettings.ambientMode == AmbientMode.Flat)
			{
				value = RenderSettings.ambientLight;
			}
			ShadowCasterMaterial.SetColor("_Color", value);
			SetShadowType(defaultShadowType);
		}

		private void RenderShadowTexture()
		{
			Camera activeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera;
			if (cachedCamera != activeCamera)
			{
				RemoveCommandBuffer();
				AddCommandBuffer(activeCamera);
			}
			commandBuffer.Clear();
			commandBuffer.SetRenderTarget(renderTexture);
			commandBuffer.ClearRenderTarget(clearDepth: true, clearColor: true, Color.white);
			commandBuffer.EnableScissorRect(GetScissorRect());
			PruneNullShadowCasters();
			if (shadowCasters.Count > 0)
			{
				projector.transform.position = nextPosition;
				projector.transform.rotation = nextRotation;
				projector.orthographicSize = nextOrthographicSize;
				UpdateShadowCasterMaterialColor();
				Bounds shadowCasterBounds = GetShadowCasterBounds();
				Vector3 center = shadowCasterBounds.center;
				Vector3 size = shadowCasterBounds.size;
				Vector3 desiredProjectorPosition = GetDesiredProjectorPosition();
				Vector3 vector = Vector3.ProjectOnPlane(center - desiredProjectorPosition, Vector3.up);
				nextPosition = desiredProjectorPosition + vector;
				nextRotation = WORLD_ALIGNED_ROTATION;
				nextOrthographicSize = Mathf.Max(size.x, size.z) / 2f;
				GetCameraViewProjectionMatrices(nextPosition, nextRotation, nextOrthographicSize, projector.nearClipPlane, projector.farClipPlane, out var viewTransform, out var projTransform);
				commandBuffer.SetViewProjectionMatrices(viewTransform, projTransform);
				SubmitAllShadowCasterRenders();
			}
		}

		private void AddCommandBuffer(Camera camera)
		{
			cachedCamera = camera;
			camera.AddCommandBuffer(CameraEvent.AfterEverything, commandBuffer);
		}

		private void RemoveCommandBuffer()
		{
			if (cachedCamera != null)
			{
				cachedCamera.RemoveCommandBuffer(CameraEvent.AfterEverything, commandBuffer);
				cachedCamera = null;
			}
		}

		private void GetCameraViewProjectionMatrices(Vector3 originPosition, Quaternion originRotation, float orthographicSize, float nearClipPlane, float farClipPlane, out Matrix4x4 viewTransform, out Matrix4x4 projTransform)
		{
			viewTransform = Matrix4x4.Inverse(Matrix4x4.TRS(originPosition, originRotation, Vector3.one));
			projTransform = Matrix4x4.Ortho(0f - orthographicSize, orthographicSize, 0f - orthographicSize, orthographicSize, nearClipPlane, farClipPlane);
		}

		private Rect GetScissorRect()
		{
			int num = 254;
			return new Rect(new Vector2(1f, 1f), new Vector2(num, num));
		}

		private void LazyInitializeRenderTexture()
		{
			if (renderTexture == null)
			{
				renderTexture = new RenderTexture(256, 256, 0, RenderTextureFormat.ARGB32);
				renderTexture.antiAliasing = 8;
				renderTexture.wrapMode = TextureWrapMode.Clamp;
				renderTexture.filterMode = FilterMode.Bilinear;
			}
		}

		private void PruneNullShadowCasters()
		{
			shadowCasterIndicesToRemove.Clear();
			for (int i = 0; i < shadowCasters.Count; i++)
			{
				if (shadowCasters[i].Renderer == null)
				{
					shadowCasterIndicesToRemove.Add(i);
				}
			}
			for (int num = shadowCasterIndicesToRemove.Count - 1; num >= 0; num--)
			{
				RemoveShadowCasterAtIndex(shadowCasterIndicesToRemove[num]);
			}
		}

		private Bounds GetShadowCasterBounds()
		{
			Bounds bounds = shadowCasters[0].Renderer.bounds;
			for (int i = 1; i < shadowCasters.Count; i++)
			{
				bounds.Encapsulate(shadowCasters[i].Renderer.bounds);
			}
			return bounds;
		}

		private void SubmitAllShadowCasterRenders()
		{
			for (int i = 0; i < shadowCasters.Count; i++)
			{
				if (shadowCasters[i].Renderer.enabled && shadowCasters[i].Renderer.gameObject.activeInHierarchy)
				{
					for (int j = 0; j < shadowCasters[i].SubMeshCount; j++)
					{
						commandBuffer.DrawRenderer(shadowCasters[i].Renderer, ShadowCasterMaterial, j, -1);
					}
				}
			}
		}

		private void UpdateShadowCasterMaterialColor()
		{
			if (LightmapSettings.lightProbes.count > 0)
			{
				LightProbes.GetInterpolatedProbe(projector.transform.position, null, out var probe);
				probe.Evaluate(SH_SAMPLE_VECTORS, SH_SAMPLE_COLORS);
				ShadowCasterMaterial.SetColor("_Color", SH_SAMPLE_COLORS[0]);
			}
		}

		private void CleanupPreviousMode()
		{
			if (updateToken != null)
			{
				updateToken.Dispose();
				updateToken = null;
			}
		}

		private void InitializeSimpleTextureMode()
		{
			LazyInitializeCachedMaterial();
			projector.transform.position = GetDesiredProjectorPosition();
			projector.transform.rotation = WORLD_ALIGNED_ROTATION;
			projector.orthographicSize = simpleTextureOrthographicProjectionSize;
			cachedMaterial.SetTexture("_ShadowTex ", simpleShadowMaterial.mainTexture);
		}

		private void InitializeProjectedRenderersMode()
		{
			LazyInitializeRenderTexture();
			LazyInitializeCachedMaterial();
			cachedMaterial.SetTexture("_ShadowTex", renderTexture);
			if (commandBuffer == null)
			{
				commandBuffer = new CommandBuffer();
			}
			nextPosition = GetDesiredProjectorPosition();
			nextRotation = WORLD_ALIGNED_ROTATION;
			nextOrthographicSize = projector.orthographicSize;
			updateToken = this.LateUpdate(RenderShadowTexture);
		}

		private Vector3 GetDesiredProjectorPosition()
		{
			return (!(projector.transform.parent != null)) ? (Vector3.up * desiredPositionAboveParent) : (projector.transform.parent.position + Vector3.up * desiredPositionAboveParent);
		}

		private void OnRestrictionChange()
		{
			bool flag = !restrictedFlag.HasTokens;
			bool flag2 = !flag;
			for (int i = 0; i < shadowCasters.Count; i++)
			{
				EnableUnityShadowCasting(i, flag2);
			}
			base.gameObject.SetActive(flag);
		}

		private void EnableUnityShadowCasting(int shadowCasterIndex, bool enabled)
		{
			if (shadowCasters[shadowCasterIndex].Renderer != null)
			{
				if (shadowCasters[shadowCasterIndex].InitialShadowCastingMode == ShadowCastingMode.ShadowsOnly)
				{
					shadowCasters[shadowCasterIndex].Renderer.enabled = enabled;
				}
				else
				{
					shadowCasters[shadowCasterIndex].Renderer.shadowCastingMode = (enabled ? shadowCasters[shadowCasterIndex].InitialShadowCastingMode : ShadowCastingMode.Off);
				}
			}
		}

		private void LazyInitializeCachedMaterial()
		{
			if (cachedMaterial == null)
			{
				cachedMaterial = new Material(simpleShadowMaterial);
				cachedMaterial.name += " (Instance)";
				projector.material = cachedMaterial;
			}
		}
	}
}
