[Serializable]
public abstract class AxisButtons
{
	public enum Direction
	{
		NONE,
		LEFT,
		RIGHT,
		UP,
		DOWN
	}

	[Serializable]
	protected struct DirectionDescription
	{
		public Direction Direction;

		public float MinAngleDegrees;

		public float MaxAngleDegrees;
	}

	protected struct DirectionButtonState
	{
		private bool _isPressed;

		public bool IsPressed
		{
			get
			{
				return _isPressed;
			}
			set
			{
				DirectionDown = false;
				DirectionPressed = false;
				DirectionUp = false;
				if (!_isPressed && value)
				{
					DirectionDown = true;
				}
				else if (_isPressed && !value)
				{
					DirectionUp = true;
				}
				_isPressed = value;
				if (_isPressed)
				{
					DirectionPressed = true;
				}
			}
		}

		public bool DirectionDown { get; private set; }

		public bool DirectionPressed { get; private set; }

		public bool DirectionUp { get; private set; }
	}

	[SerializeField]
	protected DirectionDescription[] possibleDirections;

	protected DirectionButtonState[] directionStates;

	public AxisButtons()
	{
		Direction[] array = (Direction[])System.Enum.GetValues(typeof(Direction));
		directionStates = new DirectionButtonState[array.Length];
		for (int i = 0; i < array.Length; i++)
		{
			int num = (int)array[i];
			directionStates[num] = default(DirectionButtonState);
			directionStates[num].IsPressed = false;
		}
	}

	public abstract void Update(Vector2 axis, bool inDeadZone, bool hasValidInput = true);

	public bool GetPressed(Direction buttonDirection)
	{
		return directionStates[(int)buttonDirection].DirectionPressed;
	}

	public bool GetDown(Direction buttonDirection)
	{
		return directionStates[(int)buttonDirection].DirectionDown;
	}

	public bool GetUp(Direction buttonDirection)
	{
		return directionStates[(int)buttonDirection].DirectionUp;
	}

	protected Direction GetDirection(Vector2 axis)
	{
		Direction result = Direction.NONE;
		if (possibleDirections != null && axis.sqrMagnitude >= Mathf.Epsilon)
		{
			float num = Vector2.right.AngleSignedVector2(axis.normalized);
			if (num < 0f)
			{
				num = 360f + num;
			}
			for (int i = 0; i < possibleDirections.Length; i++)
			{
				bool flag = possibleDirections[i].MaxAngleDegrees < possibleDirections[i].MinAngleDegrees;
				if ((num <= possibleDirections[i].MaxAngleDegrees && num >= possibleDirections[i].MinAngleDegrees) || (flag && num >= possibleDirections[i].MinAngleDegrees && num - 360f <= possibleDirections[i].MaxAngleDegrees) || (flag && num <= possibleDirections[i].MaxAngleDegrees && num + 360f >= possibleDirections[i].MinAngleDegrees))
				{
					result = possibleDirections[i].Direction;
					break;
				}
			}
		}
		return result;
	}
}
[Serializable]
public class AxisPressButtons : AxisButtons
{
	public override void Update(Vector2 axis, bool inDeadZone, bool hasValidInput = true)
	{
		Direction direction = GetDirection(axis);
		for (int i = 0; i < directionStates.Length; i++)
		{
			if (i == (int)direction)
			{
				directionStates[i].IsPressed = !inDeadZone;
			}
			else
			{
				directionStates[i].IsPressed = false;
			}
		}
	}
}
[Serializable]
public class AxisSwipeButtons : AxisButtons
{
	public enum SwipeStates
	{
		None,
		Swiping,
		SwipeComplete,
		Touch
	}

	[SerializeField]
	private float maxSwipeTime = 1f;

	[SerializeField]
	private float minSwipeDistance = 0.75f;

	private bool swipeIsValid = true;

	private Vector2 swipeDisplacement = Vector2.zero;

	private Vector2 latestPosition = Vector2.zero;

	private float swipeStartTime;

	public SwipeStates SwipeState { get; private set; }

	public override void Update(Vector2 axis, bool touchPressed, bool inputValid = true)
	{
		swipeIsValid &= inputValid;
		Direction direction = Direction.NONE;
		if (SwipeState == SwipeStates.None && touchPressed)
		{
			swipeIsValid = true;
			latestPosition = axis;
			swipeDisplacement = Vector2.zero;
			swipeStartTime = UnityEngine.Time.time;
			SwipeState = (inputValid ? SwipeStates.Swiping : SwipeStates.Touch);
		}
		else if (SwipeState == SwipeStates.Swiping && touchPressed)
		{
			swipeDisplacement += axis - latestPosition;
			latestPosition = axis;
			float num = UnityEngine.Time.time - swipeStartTime;
			float num2 = num / maxSwipeTime;
			float num3 = minSwipeDistance * num2;
			if (swipeDisplacement.magnitude < num3 && num > 0.1f)
			{
				SwipeState = SwipeStates.Touch;
			}
		}
		else if (SwipeState == SwipeStates.Swiping && !touchPressed)
		{
			float num4 = UnityEngine.Time.time - swipeStartTime;
			if (swipeIsValid && num4 <= maxSwipeTime && swipeDisplacement.magnitude >= minSwipeDistance)
			{
				direction = GetDirection(swipeDisplacement);
				SwipeState = SwipeStates.SwipeComplete;
			}
			else
			{
				SwipeState = SwipeStates.Touch;
			}
		}
		else if ((SwipeState == SwipeStates.Touch || SwipeState == SwipeStates.SwipeComplete) && !touchPressed)
		{
			SwipeState = SwipeStates.None;
		}
		for (int i = 0; i < directionStates.Length; i++)
		{
			if (i == (int)direction)
			{
				directionStates[i].IsPressed = true;
			}
			else
			{
				directionStates[i].IsPressed = false;
			}
		}
	}
}
