					if (array != null && array.Length > 0)
					{
						for (int i = 0; i < array.Length; i++)
						{
							CanvasUtilities.MatchOrthographicCameraToCanvas(array[i].MasterCamera, array[i].MasterCanvas);
							array[i].MarkForRender();
						}
						string text = $"Updated {array.Length} cached view manager camera settings";
						UnityEngine.Debug.Log(text);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Scoreboard Reset", text, 4f);
					}
					else
					{
						UnityEngine.Debug.Log("No cached view managers found!");
					}
				});
			}
			loadingScreen.IsVisible = ImageEffects.FadedOut;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode && ScreenModeHUD.gameObject.activeSelf == ImageEffects.FadedOut)
			{
				ScreenModeHUD.gameObject.SetActive(!ImageEffects.FadedOut);
