			Vector3 forward = new Vector3(vrModeHmdCamera.transform.forward.x, 0f, vrModeHmdCamera.transform.forward.z);
			VrModeHMDCameraTransformYawOnly.rotation = Quaternion.LookRotation(forward, vrModeHmdCamera.transform.parent.up);
