		private void OnDisplayModeChanged()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
			{
				QualitySettings.vSyncCount = 0;
				VrModeHmdCamera.enabled = true;
				ScreenModeCamera.enabled = false;
				ScreenModeHUD.gameObject.SetActive(value: false);
				AttachTransformToCamera(audioListener.transform, VrModeHmdCamera);
				OutlineEffectRenderer.SetHoverOutlineScale(1f);
				OutlineEffectRenderer.SetTeleportOutlineScale(1f);
				if (SingletonMonoBehaviour<CameraFade>.Instance != null)
				{
					SingletonMonoBehaviour<CameraFade>.Instance.SuppressAnimateInOutEffects = false;
				}
			}
			else
			{
				QualitySettings.vSyncCount = 1;
				VrModeHmdCamera.enabled = false;
				ScreenModeCamera.enabled = true;
				ScreenModeHUD.gameObject.SetActive(value: true);
				AttachTransformToCamera(audioListener.transform, ScreenModeCamera);
				OutlineEffectRenderer.SetHoverOutlineScale(4f);
				OutlineEffectRenderer.SetTeleportOutlineScale(0.66f);
				if (SingletonMonoBehaviour<CameraFade>.Instance != null)
				{
					SingletonMonoBehaviour<CameraFade>.Instance.SuppressAnimateInOutEffects = true;
				}
			}
			float lodBias;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
			{
				float fieldOfView = vrModeHmdCamera.fieldOfView;
				lodBias = CalcLODBias(60f, fieldOfView);
			}
			else
			{
				lodBias = baseLODBias;
			}
			QualitySettings.lodBias = lodBias;
			if (CameraRig.ActiveCameraChangeEvent != null)
			{
				CameraRig.ActiveCameraChangeEvent();
			}
		}

		public VRTrackedController GetTrackedController(VRTrackedController.HandType handType)
		{
