			{
				return vrLeftHandTrackedController;
			}
			return vrRightHandTrackedController;
		}

		public static float CalcLODBias(float flatCamFOV, float headsetFOV, float baseLODBias = 2f)
		{
			float num = (float)Math.PI / 180f * flatCamFOV;
			float num2 = (float)Math.PI / 180f * headsetFOV;
			return baseLODBias * (Mathf.Tan(num2 / 2f) / Mathf.Tan(num / 2f));
		}

		public void TransformHeadFloorToRigPositionAndOrientation(Vector3 headFloorPosition, Vector3 forward, bool forwardInHeadSpace, out Vector3 rigPosition, out Quaternion rigRotation)
		{
			forward = Vector3.ProjectOnPlane(forward, Vector3.up);
			rigRotation = Quaternion.identity;
			if (forwardInHeadSpace)
			{
				Quaternion rotation = Quaternion.Euler(0f, base.transform.InverseTransformRotation(VrModeHmdCamera.transform.rotation).eulerAngles.y, 0f);
				rigRotation = Quaternion.LookRotation(forward, Vector3.up) * Quaternion.Inverse(rotation);
			}
			else
			{
				rigRotation = Quaternion.LookRotation(forward, Vector3.up);
			}
			rigPosition = headFloorPosition - rigRotation * VrModeHmdCameraFloorOffsetLocalSpace;
		}

		public Vector3 GetClosestPointInFieldOfView(Vector3 worldSpacePoint)
		{
			Vector3 cartesionPoint = ActiveCamera.transform.InverseTransformPoint(worldSpacePoint);
			cartesionPoint.z *= -1f;
			MathExt.CartesianPointToSphericalDegrees(cartesionPoint, out var pitchDegrees, out var yawDegrees, out var radius);
			float fieldOfView = ActiveCamera.fieldOfView;
			float num = fieldOfView * 0.5f;
			float pitchDegrees2 = Mathf.Clamp(pitchDegrees, 0f - num, num);
			float horizontalFieldOfView = ActiveCamera.GetHorizontalFieldOfView();
			float num2 = horizontalFieldOfView * 0.5f;
			float yawDegrees2 = Mathf.Clamp(yawDegrees, 0f - num2, num2);
			float radius2 = Mathf.Max(0.15f, radius);
			Vector3 position = MathExt.SphericalPointDegreestoCartesian(pitchDegrees2, yawDegrees2, radius2);
			position.z *= -1f;
			return ActiveCamera.transform.TransformPoint(position);
		}

		public void AttachTransformToActiveCamera(Transform transform)
		{
			AttachTransformToCamera(transform, ActiveCamera);
		}

		private void AttachTransformToCamera(Transform transform, Camera camera)
		{
			transform.SetParent(camera.transform, worldPositionStays: false);
			transform.localPosition = Vector3.zero;
			transform.localRotation = Quaternion.identity;
			transform.localScale = Vector3.one;
		}

		public void SetTransform(Vector3 position, Quaternion rotation)
		{
			base.transform.rotation = rotation;
			base.transform.position = position;
		}

		internal void SetForcedHeight()
		{
			juniorOffsetPoint.SetForcedHeight();
		}
	}
