				NormalizedAmplitude = 0.6f,
				Duration = 0.4f,
				Frequency = 60f
			};

			public static CameraShakeConfig DefaultHeavyShake => new CameraShakeConfig
			{
				NormalizedAmplitude = 1f,
				Duration = 0.66f,
				Frequency = 60f
			};

			public static CameraShakeConfig ScaleAmplitude(CameraShakeConfig config, float t)
			{
				CameraShakeConfig result = config;
				result.NormalizedAmplitude *= t;
				return result;
			}

			public static CameraShakeConfig Lerp(CameraShakeConfig lhs, CameraShakeConfig rhs, float t)
			{
				return new CameraShakeConfig
				{
					NormalizedAmplitude = Mathf.Lerp(lhs.NormalizedAmplitude, rhs.NormalizedAmplitude, t),
					Duration = Mathf.Lerp(lhs.Duration, rhs.Duration, t),
					Frequency = Mathf.Lerp(lhs.Duration, rhs.Duration, t)
				};
			}
		}

		private class RegisteredCameraState
		{
			public Camera Camera;

			public Vector3 MaxLinearOffsets;

			public Vector3 MaxAngularOffsets;

			public Vector3 ActualPosition;

			public Quaternion ActualRotation;
		}

		private static CameraShakeConfig currentConfig = default(CameraShakeConfig);

		private static float amplitude = 0f;

		private static float seed = 0f;

		private static List<RegisteredCameraState> registeredCameras = new List<RegisteredCameraState>();

		private static ISchedulerPromise shakeRoutinePromise = null;

		private static bool hasInitialized = false;

		public static void RegisterCamera(Camera camera)
		{
			LazyInitialize();
			if (FindCameraState(camera) == null)
			{
				registeredCameras.Add(new RegisteredCameraState
				{
					Camera = camera,
					ActualPosition = camera.transform.position,
					ActualRotation = camera.transform.rotation
				});
			}
		}

		public static void UnregisterCamera(Camera camera)
		{
			RegisteredCameraState registeredCameraState = FindCameraState(camera);
			if (registeredCameraState != null)
			{
				registeredCameras.Remove(registeredCameraState);
			}
			LazyCleanup();
		}

		public static void SetMaxLinearOffsets(Camera camera, Vector3 maxLinearOffsets)
		{
			RegisteredCameraState registeredCameraState = FindCameraState(camera);
			if (registeredCameraState != null)
			{
				registeredCameraState.MaxLinearOffsets = maxLinearOffsets;
			}
		}

		public static void SetMaxAngularOffsets(Camera camera, Vector3 maxAngularOffsets)
		{
			RegisteredCameraState registeredCameraState = FindCameraState(camera);
			if (registeredCameraState != null)
			{
				registeredCameraState.MaxAngularOffsets = maxAngularOffsets;
			}
		}

		public static void SetShake(CameraShakeConfig shakeConfig)
		{
			if (!(shakeConfig.Duration <= Mathf.Epsilon) && !(shakeConfig.NormalizedAmplitude <= Mathf.Epsilon) && !(shakeConfig.Frequency <= Mathf.Epsilon))
			{
				if (!IsShakeRoutineRunning())
				{
					StartShakeRoutine();
				}
				currentConfig = shakeConfig;
				amplitude = currentConfig.NormalizedAmplitude;
			}
		}

		private static void LazyInitialize()
		{
			if (!hasInitialized)
			{
				Camera.onPreRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPreRender, new Camera.CameraCallback(OnPreRender));
				Camera.onPostRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPostRender, new Camera.CameraCallback(OnPostRender));
				hasInitialized = true;
			}
		}

		private static void LazyCleanup()
		{
			if (registeredCameras.Count == 0 && hasInitialized)
			{
				Camera.onPreRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPreRender, new Camera.CameraCallback(OnPreRender));
				Camera.onPostRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPostRender, new Camera.CameraCallback(OnPostRender));
				hasInitialized = false;
			}
		}

		private static void OnPreRender(Camera camera)
		{
			RegisteredCameraState registeredCameraState = FindCameraState(camera);
			if (registeredCameraState != null)
			{
				registeredCameraState.ActualPosition = camera.transform.position;
				registeredCameraState.ActualRotation = camera.transform.rotation;
				GetShakeDisplacements(amplitude, currentConfig.Frequency, seed, UnityEngine.Time.time, registeredCameraState.MaxLinearOffsets, registeredCameraState.MaxAngularOffsets, out var linearDisplacement, out var angularDisplacement);
				camera.transform.position = camera.transform.position + camera.transform.TransformVector(linearDisplacement);
				camera.transform.rotation = camera.transform.rotation * angularDisplacement;
			}
		}

		private static void OnPostRender(Camera camera)
		{
			RegisteredCameraState registeredCameraState = FindCameraState(camera);
			if (registeredCameraState != null)
			{
				camera.transform.position = registeredCameraState.ActualPosition;
				camera.transform.rotation = registeredCameraState.ActualRotation;
			}
		}

		private static bool IsShakeRoutineRunning()
		{
			return shakeRoutinePromise != null && shakeRoutinePromise.IsCompleted;
		}

		private static void StopShakeRoutine()
		{
			if (shakeRoutinePromise != null)
			{
				shakeRoutinePromise.Dispose();
			}
			shakeRoutinePromise = null;
		}

		private static void StartShakeRoutine()
		{
			StopShakeRoutine();
			shakeRoutinePromise = ScheduleNextFrame.QueueUpdate(ShakeRoutineUpdate, Scheduler.QueueType.LateUpdate);
			seed = UnityEngine.Random.value;
		}

		private static void ShakeRoutineUpdate()
		{
			if (currentConfig.Duration <= 0f)
			{
				amplitude = 0f;
			}
			else
			{
				float num = 1f / currentConfig.Duration;
				amplitude = Mathf.Clamp01(amplitude - num * UnityEngine.Time.deltaTime);
			}
			if (amplitude <= 0f)
			{
				StopShakeRoutine();
			}
		}

		private static void GetShakeDisplacements(float amplitude, float frequency, float seed, float time, Vector3 maxLinearOffset, Vector3 maxAngularOffset, out Vector3 linearDisplacement, out Quaternion angularDisplacement)
		{
			float num = amplitude * amplitude;
			float x = maxLinearOffset.x * num * GetNoise(time, frequency, ref seed);
			float y = maxLinearOffset.y * num * GetNoise(time, frequency, ref seed);
			float z = maxLinearOffset.z * num * GetNoise(time, frequency, ref seed);
			linearDisplacement = new Vector3(x, y, z);
			float x2 = maxAngularOffset.x * num * GetNoise(time, frequency, ref seed);
			float y2 = maxAngularOffset.y * num * GetNoise(time, frequency, ref seed);
			float z2 = maxAngularOffset.z * num * GetNoise(time, frequency, ref seed);
			angularDisplacement = Quaternion.Euler(x2, y2, z2);
		}

		private static float GetNoise(float time, float frequency, ref float seed)
		{
			return Mathf.Lerp(-1f, 1f, Mathf.PerlinNoise(seed += 1f, time * frequency));
		}

		private static RegisteredCameraState FindCameraState(Camera camera)
		{
			return registeredCameras.Find((RegisteredCameraState rcs) => rcs.Camera == camera);
		}
	}
}
public class CameraStartPoint : SingletonMonoBehaviour<CameraStartPoint>
{
	public Vector3 Default = Vector3.zero;

	public Vector3 PS4 = new Vector3(0f, 1.479f, 0.067f);

	public Vector3 MicrosoftStartPoint = new Vector3(0f, 1.479f, 0.067f);

	private void Start()
	{
		if (RoomCalibration.RequiresCalibration || SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Microsoft)
		{
			UpdateOffset(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform switch
			{
				PlatformManager.PlatformType.PlayStation => PS4, 
				PlatformManager.PlatformType.Microsoft => MicrosoftStartPoint, 
				_ => Default, 
			});
		}
		else if (RoomCalibration.UsesRoomCalibration)
		{
			RoomCalibration.LoadRoomCalibration();
		}
	}

	public static void UpdateOffset(Vector3 newOffset)
	{
		SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition = newOffset;
		UpdateChaperonePosition();
	}

	public static void UpdateChaperonePosition()
	{
		if (Player.LocalPlayerExists && SingletonMonoBehaviour<CameraRig>.IsInitialized && RoomCalibration.UsesRoomCalibration)
		{
			Vector3 position = RoomCalibration.GetTrackerWorldPosition() - SingletonMonoBehaviour<CameraStartPoint>.Instance.transform.localPosition;
			position.y = SingletonMonoBehaviour<CameraRig>.Instance.transform.position.y;
			Player.LocalPlayer.PlayerChaperone.transform.position = position;
		}
	}
}
