[DisallowMultipleComponent]
public class DebugCameraControl : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float yawSpeed = 4f;

	[SerializeField]
	private float pitchSpeed = 2f;

	[SerializeField]
	private float rollSpeed = 2f;

	[SerializeField]
	private float minMovementSpeedLegacy = 4f;

	[SerializeField]
	private AnimationCurve editorMovementSpeedCurve = AnimationCurve.EaseInOut(0f, 4f, 30f, 60f);

	private const float DEFAULT_CAMERA_HEIGHT = 1.66f;

	private void Start()
	{
		if (!RecRoomEditorPreferences.RunInDebugMode)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		base.transform.localPosition = Vector3.zero;
		Vector3 position = base.transform.position;
		position.y = SingletonMonoBehaviour<CameraRig>.Instance.transform.position.y + 1.66f;
		base.transform.position = position;
	}

	private void Update()
	{
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused)
		{
			Vector3 vector = ReadLookInput();
			float yAngle = vector.y * yawSpeed;
			base.transform.Rotate(0f, yAngle, 0f, Space.World);
			float xAngle = (0f - vector.x) * pitchSpeed;
			base.transform.Rotate(xAngle, 0f, 0f, Space.Self);
			float zAngle = (0f - vector.z) * rollSpeed;
			base.transform.Rotate(0f, 0f, zAngle, Space.Self);
		}
	}

	private void OnDestroy()
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerLocomotion.ResumeGravity(this);
		}
	}

	private Vector3 ReadMovementInput()
	{
		return new Vector3(Input.GetAxis("Movement Right"), Input.GetAxis("Movement Up"), Input.GetAxis("Movement Forward"));
	}

	private Vector3 ReadLookInput()
	{
		return new Vector3(Input.GetAxis("Mouse Y"), Input.GetAxis("Mouse X"), 0f);
	}
}
