public class HairTriggerButton
{
	public const float DEFAULT_DEADZONE = 0.1f;

	private float hairTriggerLimit;

	private bool hairTriggerWasPressed;

	public bool HairTriggerPressed { get; private set; }

	public bool HairTriggerDown { get; private set; }

	public bool HairTriggerUp { get; private set; }

	public void Update(float axisValue, bool axisGoesNegative = false)
	{
		Update(axisValue, 0.1f);
	}

	public void Update(float axisValue, float deadzone, bool axisGoesNegative = false)
	{
		hairTriggerWasPressed = HairTriggerPressed;
		if (axisGoesNegative)
		{
			axisValue = Mathf.InverseLerp(-1f, 1f, axisValue);
		}
		if (HairTriggerPressed)
		{
			if (axisValue < hairTriggerLimit - deadzone || axisValue <= 0f)
			{
				HairTriggerPressed = false;
			}
		}
		else if (axisValue > hairTriggerLimit + deadzone || axisValue >= 1f)
		{
			HairTriggerPressed = true;
		}
		hairTriggerLimit = ((!HairTriggerPressed) ? Mathf.Min(hairTriggerLimit, axisValue) : Mathf.Max(hairTriggerLimit, axisValue));
		HairTriggerDown = HairTriggerPressed && !hairTriggerWasPressed;
		HairTriggerUp = !HairTriggerPressed && hairTriggerWasPressed;
	}
}
namespace RecRoom.Core.Juniors
{
	public class JuniorOffsetPoint : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private CameraRig cameraStartPoint;

		[SerializeField]
		private GameObject cameraGO;

		[Tooltip("Forced height of junior players")]
		[SerializeField]
		private float forcedHeight = 1.67f;

		public void SetForcedHeight()
		{
			if (RecRoomSceneManager.Instance != null && !(RecRoomSceneManager.Instance is DormroomSceneManager) && Profiles.LocalProfile != null && (bool)Profiles.LocalProfile.JuniorProfile)
			{
				float num = cameraStartPoint.transform.InverseTransformPoint(cameraGO.transform.position).y - base.transform.localPosition.y;
				if (num < forcedHeight)
				{
					float y = Mathf.Min(forcedHeight - num, forcedHeight / 2f);
					Vector3 localPosition = base.transform.localPosition;
					localPosition.y = y;
					base.transform.localPosition = localPosition;
					return;
				}
			}
			base.transform.localPosition = Vector3.zero;
		}
	}
}
