	public class PostProcessVolumeSettings : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public class PlatformSettings
		{
			public enum Context
			{
				Any,
				VR,
				Screens
			}

			public Context PlayerContext;

			public RuntimePlatform[] Platforms;

			public bool ssaoEnabled;

			public bool bloomEnabled = true;
		}

		private static PlatformSettings[] DEFAULT_SETTINGS = new PlatformSettings[3]
		{
			new PlatformSettings
			{
				Platforms = new RuntimePlatform[3]
				{
					RuntimePlatform.WindowsPlayer,
					RuntimePlatform.WindowsEditor,
					RuntimePlatform.PS4
				},
				PlayerContext = PlatformSettings.Context.VR,
				ssaoEnabled = false,
				bloomEnabled = true
			},
			new PlatformSettings
			{
				Platforms = new RuntimePlatform[3]
				{
					RuntimePlatform.WindowsPlayer,
					RuntimePlatform.WindowsEditor,
					RuntimePlatform.PS4
				},
				PlayerContext = PlatformSettings.Context.Screens,
				ssaoEnabled = false,
				bloomEnabled = true
			},
			new PlatformSettings
			{
				Platforms = new RuntimePlatform[1] { RuntimePlatform.Android },
				PlayerContext = PlatformSettings.Context.Any,
				ssaoEnabled = false,
				bloomEnabled = false
			}
		};

		private void Start()
		{
			ApplySettings();
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.DisplayModeChange = (Action)Delegate.Combine(instance.DisplayModeChange, new Action(ApplySettings));
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
			{
				LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				instance.DisplayModeChange = (Action)Delegate.Remove(instance.DisplayModeChange, new Action(ApplySettings));
			}
		}

		private void ApplySettings()
		{
			PostProcessVolume component = GetComponent<PostProcessVolume>();
			PlatformSettings.Context context = ((SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode != LocalPlayerController.DisplayMode.SCREEN) ? PlatformSettings.Context.VR : PlatformSettings.Context.Screens);
			PlatformSettings platformSettings = DEFAULT_SETTINGS.FirstOrDefault((PlatformSettings s) => s.Platforms.Any((RuntimePlatform p) => p == UnityEngine.Application.platform) && (s.PlayerContext == context || s.PlayerContext == PlatformSettings.Context.Any));
			if (platformSettings == null)
			{
				return;
			}
			if (component.sharedProfile == null)
			{
				UnityEngine.Debug.LogErrorFormat(component, "No profile specified for post process volume {0}", component);
				return;
			}
			if (component.sharedProfile.TryGetSettings<Bloom>(out var outSetting))
			{
				outSetting.active = platformSettings.bloomEnabled;
			}
			if (component.sharedProfile.TryGetSettings<AmbientOcclusion>(out var outSetting2))
			{
				outSetting2.active = platformSettings.ssaoEnabled;
			}
		}
	}
}
