		};

		public override bool IsEnabledAndSupported(PostProcessRenderContext context)
		{
			return base.IsEnabledAndSupported(context) && WorldFadeRenderer.ShouldRenderImageEffect();
		}
	}
	public class WorldFadeScreenRenderer : PostProcessEffectRenderer<WorldFadeScreenSettings>
	{
		public override void Render(PostProcessRenderContext context)
		{
			PropertySheet propertySheet = context.propertySheets.Get(Shader.Find("Hidden/AG/WorldFadeScreenRenderer"));
			propertySheet.properties.SetFloat("_Brightness", base.settings.brightness);
			propertySheet.properties.SetFloat("_Saturation", base.settings.saturation);
			propertySheet.properties.SetFloat("_Contrast", base.settings.contrast);
			context.command.BlitFullscreenTriangle(context.source, context.destination, propertySheet, 0);
		}
	}
