	public class Challenge : ChallengeBase
	{
		public List<IChallenge> WithConditions = new List<IChallenge>();

		public List<IChallenge> ResetConditions = new List<IChallenge>();

		public const string RESET_CONDITIONS_KEY = "rc";

		public const string WITH_CONDITIONS_KEY = "wc";

		public override ChallengeTypes ChallengeType => ChallengeTypes.Challenge;

		public Challenge()
		{
			IgnorePreviousCompletions = false;
		}

		protected bool EvalutateConditions(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			List<bool> source = ResetConditions.Select((IChallenge _) => _.Evaluate(challengeEventData)).ToList();
			if (source.Any((bool _) => _))
			{
				Reset();
			}
			List<bool> source2 = WithConditions.Select((IChallenge _) => _.Evaluate(challengeEventData)).ToList();
			bool result = source2.Count() > 0 && source2.All((bool _) => _);
			base.Dirty |= WithConditions.Any((IChallenge _) => _.Dirty);
			return result;
		}

		protected override bool EvaluateInternal(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			return EvalutateConditions(challengeEventData);
		}

		public override void Reset()
		{
			base.Reset();
			ResetChildren();
		}

		protected void ResetChildren()
		{
			foreach (IChallenge withCondition in WithConditions)
			{
				withCondition.Reset();
			}
			foreach (IChallenge resetCondition in ResetConditions)
			{
				resetCondition.Reset();
			}
		}

		public override Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = base.Serialize();
			List<Dictionary<string, object>> list = (from _ in ResetConditions
				where !_.SkipSerialization
				select _.Serialize()).ToList();
			List<Dictionary<string, object>> list2 = (from _ in WithConditions
				where !_.SkipSerialization
				select _.Serialize()).ToList();
			if (list.Count > 0)
			{
				dictionary["rc"] = list;
			}
			if (list2.Count > 0)
			{
				dictionary["wc"] = list2;
			}
			return dictionary;
		}

		protected override void DeserializeInternal(Dictionary<string, object> jsonDict)
		{
			ResetConditions = ChallengeParser.GetChallengeSet("rc", jsonDict);
			WithConditions = ChallengeParser.GetChallengeSet("wc", jsonDict);
		}
	}
