					});
				}
				if (IgnorePreviousCompletions)
				{
					Complete = flag;
				}
			}
			if (UpdateServer && IsMasterChallenge)
			{
				this.UpdateServerEvent.DoIfNotNull(delegate(UpdateChallenge _)
				{
					_(this);
				});
			}
			return flag;
