				{
					SetVar("t_score", value);
				}
			}

			public GameEventData(ChallengeEventTypes challengeType, bool isSpectator = false)
				: base(challengeType)
			{
				Spectator = isSpectator;
				if (!(RecRoomSceneManager.Instance != null) || !(NetworkedSingletonMonoBehaviour<GameManager>.Instance != null))
				{
					return;
				}
				SetVar("gid", NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameID);
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager != null)
				{
					GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
					NumTeammates = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerCount(playerTeam);
					NumPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActivePlayerCount();
					if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager != null && playerTeam != GameTeam.ANY)
					{
						TeamScore = NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetScore(playerTeam);
					}
					else
