	public class ChallengeParser
	{
		public static IChallenge FromJsonDict(Dictionary<string, object> dict)
		{
			ChallengeTypes? challengeType = GetChallengeType(dict);
			if (challengeType.HasValue)
			{
				switch (challengeType.Value)
				{
				case ChallengeTypes.Challenge:
					return Util.Deserialize<Challenge>(dict);
				case ChallengeTypes.ChallengeCountChallenge:
					return Util.Deserialize<ChallengeCountChallenge>(dict);
				case ChallengeTypes.TimedBufferChallenge:
					return Util.Deserialize<TimedBufferChallenge>(dict);
				case ChallengeTypes.DynamicFloatArithmeticChallenge:
					return Util.Deserialize<DynamicFloatArithmeticChallenge>(dict);
				case ChallengeTypes.DynamicIntArithmeticChallenge:
					return Util.Deserialize<DynamicIntArithmeticChallenge>(dict);
				case ChallengeTypes.RequiredToolChallenge:
					return Util.Deserialize<RequiredToolChallenge>(dict);
				case ChallengeTypes.RequiredEventTypeChallenge:
					return Util.Deserialize<RequiredEventTypeChallenge>(dict);
				case ChallengeTypes.RequiredRoomSceneLocationChallenge:
					return Util.Deserialize<RequiredRoomSceneLocationChallenge>(dict);
				case ChallengeTypes.RequiredEnemyTypeChallenge:
					return Util.Deserialize<RequiredEnemyTypeChallenge>(dict);
				case ChallengeTypes.BoolVarEqualsChallenge:
					return Util.Deserialize<BoolVarEqualsChallenge>(dict);
				case ChallengeTypes.DiscGolfFinishUnderParChallenge:
					return Util.Deserialize<DiscGolfFinishUnderParChallenge>(dict);
				case ChallengeTypes.RequiredGameModeActivityChallenge:
					return Util.Deserialize<RequiredGameModeActivityChallenge>(dict);
				case ChallengeTypes.CompleteGameWithoutChallenge:
					return Util.Deserialize<CompleteGameWithoutChallenge>(dict);
				case ChallengeTypes.RequiredGestureChallenge:
					return Util.Deserialize<RequiredGestureChallenge>(dict);
				case ChallengeTypes.HitstreakChallenge:
					return Util.Deserialize<HitstreakChallenge>(dict);
				case ChallengeTypes.HitstreakCountChallenge:
					return Util.Deserialize<HitstreakCountChallenge>(dict);
				}
			}
			return null;
		}

		private static ChallengeTypes? GetChallengeType(Dictionary<string, object> dict)
		{
			if (dict != null && dict.ContainsKey("ct"))
			{
				return (ChallengeTypes)Util.GetKey<int>("ct", dict);
			}
			return null;
		}

		public static bool TryGetChallenge(string key, Dictionary<string, object> dict, out IChallenge challenge)
		{
			challenge = null;
			object value = null;
			if (dict.TryGetValue(key, out value) && value != null)
			{
				Dictionary<string, object> dict2 = (Dictionary<string, object>)value;
				challenge = FromJsonDict(dict2);
				if (challenge != null)
				{
					return true;
				}
			}
			return false;
		}

		public static List<IChallenge> GetChallengeSet(string key, Dictionary<string, object> jsonDict)
		{
			if (jsonDict.ContainsKey(key))
			{
				List<Dictionary<string, object>> listKey = Util.GetListKey<Dictionary<string, object>>(key, jsonDict);
				return new List<IChallenge>(from _ in listKey.Select(FromJsonDict)
					where _ != null
					select _);
			}
			return new List<IChallenge>();
		}

		public static T GetOptionalKey<T>(string key, Dictionary<string, object> jsonDict, T defaultValue = default(T))
		{
			if (jsonDict.ContainsKey(key))
			{
				try
				{
					return Util.GetKey<T>(key, jsonDict);
				}
				catch
				{
					UnityEngine.Debug.LogError("Badly formatted data for optional key:" + key);
					return defaultValue;
				}
			}
			return defaultValue;
		}
	}
