	public enum NumOperation
	{
		GT,
		LT,
		EQ,
		GTE,
		LTE
	}
	public abstract class DynamicArithmeticChallenge<T> : ChallengeBase where T : struct, IConvertible, IComparable<T>
	{
		public INumResolver<T> numResolverA;

		public NumOperation NumOp = NumOperation.EQ;

		public INumResolver<T> numResolverB;

		public DynamicArithmeticChallenge()
		{
		}

		public DynamicArithmeticChallenge(NumOperation numOp, INumResolver<T> numResolverA, INumResolver<T> numResolverB)
		{
			NumOp = numOp;
			this.numResolverA = numResolverA;
			this.numResolverB = numResolverB;
		}

		protected override bool EvaluateInternal(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			if (numResolverA == null || numResolverB == null)
			{
				UnityEngine.Debug.LogWarning("NumResolver was null");
				return false;
			}
			T? value = numResolverA.GetValue(challengeEventData);
			T? value2 = numResolverB.GetValue(challengeEventData);
			if (value.HasValue && value2.HasValue)
			{
				T value3 = value.Value;
				T value4 = value2.Value;
				return NumOp switch
				{
					NumOperation.GT => value3.CompareTo(value4) > 0, 
					NumOperation.LT => value3.CompareTo(value4) < 0, 
					NumOperation.GTE => value3.CompareTo(value4) > 0 || Equals(value3, value4), 
					NumOperation.LTE => value3.CompareTo(value4) < 0 || Equals(value3, value4), 
					NumOperation.EQ => Equals(value3, value4), 
					_ => throw new NotImplementedException(), 
				};
			}
			return false;
		}

		protected abstract bool Equals(T valueA, T valueB);

		public sealed override Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = base.Serialize();
			dictionary["op"] = (int)NumOp;
			if (numResolverA != null)
			{
				dictionary["rA"] = numResolverA.Serialize();
			}
			if (numResolverB != null)
			{
				dictionary["rB"] = numResolverB.Serialize();
			}
			return dictionary;
		}

		protected sealed override void DeserializeInternal(Dictionary<string, object> jsonDict)
		{
			NumOp = (NumOperation)ChallengeParser.GetOptionalKey("op", jsonDict, 2);
			numResolverA = NumResolver<T>.FromJsonDict(ChallengeParser.GetOptionalKey<Dictionary<string, object>>("rA", jsonDict));
			numResolverB = NumResolver<T>.FromJsonDict(ChallengeParser.GetOptionalKey<Dictionary<string, object>>("rB", jsonDict));
		}
	}
	public class DynamicFloatArithmeticChallenge : DynamicArithmeticChallenge<float>
	{
		public override ChallengeTypes ChallengeType => ChallengeTypes.DynamicFloatArithmeticChallenge;

		public DynamicFloatArithmeticChallenge()
		{
		}

		public DynamicFloatArithmeticChallenge(NumOperation numOp, INumResolver<float> numResolverA, INumResolver<float> numResolverB)
			: base(numOp, numResolverA, numResolverB)
		{
		}

		protected override bool Equals(float valueA, float valueB)
		{
			return Mathf.Approximately(valueA, valueB);
		}
	}
