			: base(numOp, numResolverA, numResolverB)
		{
		}

		protected override bool Equals(int valueA, int valueB)
		{
			return valueA == valueB;
		}
	}
	[HideParentWithChallengeList]
	public class ChallengeCountChallenge : Challenge
	{
		[SerializeChallenge]
		protected List<IChallenge> challengesToCount = new List<IChallenge>();

		[ChallengeFoldout]
		public List<int> notificationCounts = new List<int>();

		[SerializeField]
		private int requiredCount;

		private int lastUpdateCount;

		private float nextUpdateTime;

		private float updateInterval = 60f;

		public const string ARITHMETIC_CHALLENGE_KEY = "acc";

		public const string CHALLENGES_COUNT_CHALLENGE_KEY = "ctc";

		public const string CURRENT_COUNT_KEY = "cc";

		public const string COUNT_KEY = "t";

		public override ChallengeProgress Progress => new ChallengeProgress
		{
			Count = CurrentCount,
			Total = RequiredCount
		};

		public int CurrentCount { get; private set; }

		public int RequiredCount => requiredCount;

		public override ChallengeTypes ChallengeType => ChallengeTypes.ChallengeCountChallenge;

		public ChallengeCountChallenge()
		{
		}

		public ChallengeCountChallenge(IChallenge challengeToCount, int count)
		{
			challengesToCount.Clear();
			challengesToCount.Add(challengeToCount);
			requiredCount = count;
			CurrentCount = 0;
			Initialize();
		}

		protected override void Initialize()
		{
			WithConditions.Clear();
			base.Initialize();
			lastUpdateCount = CurrentCount;
			nextUpdateTime = UnityEngine.Time.realtimeSinceStartup + 60f;
			foreach (IChallenge item in challengesToCount)
			{
				IChallenge c = item;
				c.SkipSerialization = true;
				c.ChallengeCompleteEvent += delegate
				{
					CurrentCount++;
					c.Reset();
					base.Dirty = true;
					base.UpdateServer |= ShouldUpdateServer();
				};
				WithConditions.Add(c);
			}
		}

		private bool ShouldUpdateServer()
		{
			if (UnityEngine.Time.realtimeSinceStartup > nextUpdateTime || Mathf.Abs(CurrentCount - lastUpdateCount) > Mathf.FloorToInt((float)RequiredCount * 0.1f))
			{
				nextUpdateTime = GetNextUpdateTime();
				return true;
			}
			return false;
		}

		private float GetNextUpdateTime()
		{
			return UnityEngine.Time.realtimeSinceStartup + updateInterval;
		}

		protected override bool EvaluateInternal(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			int currentCount = CurrentCount;
			base.EvaluateInternal(challengeEventData);
			if (CurrentCount != currentCount && notificationCounts.Contains(CurrentCount))
			{
				Notify(CurrentCount, RequiredCount);
			}
			if (CurrentCount >= RequiredCount)
			{
				return true;
			}
			return false;
		}

		public override void Reset()
		{
			CurrentCount = 0;
			base.Reset();
		}

		public override Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = base.Serialize();
			if (challengesToCount.Count > 0)
			{
				List<Dictionary<string, object>> value = challengesToCount.Select((IChallenge _) => _.Serialize()).ToList();
				dictionary["ctc"] = value;
			}
			dictionary["t"] = RequiredCount;
			ChallengeBase.SerializeOptionalField("cc", CurrentCount, 0, dictionary);
			return dictionary;
		}

		protected override void DeserializeInternal(Dictionary<string, object> jsonDict)
		{
			base.DeserializeInternal(jsonDict);
			CurrentCount = ChallengeParser.GetOptionalKey("cc", jsonDict, 0);
			requiredCount = ChallengeParser.GetOptionalKey("t", jsonDict, 1);
			challengesToCount.Clear();
			if (jsonDict.ContainsKey("ctc"))
			{
				List<Dictionary<string, object>> listKey = Util.GetListKey<Dictionary<string, object>>("ctc", jsonDict);
				IEnumerable<IChallenge> collection = from _ in listKey.Select(ChallengeParser.FromJsonDict)
					where _ != null
					select _;
				challengesToCount = new List<IChallenge>(collection);
			}
		}
	}
	[HideParentWithChallengeList]
	public class TimedBufferChallenge : Challenge
	{
		public enum BufferCountMethods
		{
			Count,
			UniqueToolCount,
			UniqueAttackerCount,
			UniqueDefenderCount,
			GroupedToolMaxCount,
			UniqueGameCount
		}

		public enum ProgressModes
		{
			Complete,
			Count
		}

		public struct TimedBufferEntry : IRecNetTransferObject, IRecNetObject, IRecNetRequestObject
		{
			public float Time;

			public ChallengeEvents.IChallengeEventData EventData;

			private const string TIME_KEY = "t";

			private const string EVENT_DATA_KEY = "e";

			public void Deserialize(Dictionary<string, object> dict)
			{
				Time = Util.GetFormattedFloatKey("t", dict);
				EventData = ChallengeEvents.ChallengeEventData.Parse(Util.GetKey<Dictionary<string, object>>("e", dict));
			}

			public Dictionary<string, object> Serialize()
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("t", Time.ToString("F2", CultureInfo.InvariantCulture));
				dictionary.Add("e", EventData.Serialize());
				return dictionary;
			}

			public static TimedBufferEntry DeserializeFromDict(Dictionary<string, object> dict)
			{
				TimedBufferEntry result = default(TimedBufferEntry);
				result.Deserialize(dict);
				return result;
			}
		}

		public BufferCountMethods BufferCountMethod;

		public ProgressModes ProgressMode;

		protected unsafe static readonly Func<float> UnityTimeFunc = new Func<float>(null, (nint)(delegate*<float>)(&UnityEngine.Time.get_realtimeSinceStartup));

		private unsafe Func<float> getCurrentTimeFunc = new Func<float>(null, (nint)(delegate*<float>)(&UnityEngine.Time.get_realtimeSinceStartup));

		public const float IGNORE_INTERVAL = -1f;

		protected float interval;

		protected int total;

		private int currentCount;

		private List<TimedBufferEntry> entryBuffer = new List<TimedBufferEntry>();

		public bool PersistBuffer;

		protected List<IChallenge> challengesToCount = new List<IChallenge>();

		[ChallengeFoldout]
		public List<int> notificationCounts = new List<int>();

		public const string CHALLENGES_COUNT_CHALLENGE_KEY = "ccc";

		public const string INTERVAL_KEY = "i";

		public const string COUNT_KEY = "t";

		public const string METHOD_KEY = "m";

		public const string BUFFER_KEY = "b";

		public const string PERSIST_BUFFER_KEY = "pb";

		public const string PROGRESS_MODE_KEY = "pm";

		public const string NOTIFICATIONS_KEY = "n";

		public int BufferSize => entryBuffer.Count;

		public override ChallengeProgress Progress
		{
			get
			{
				ProgressModes progressMode = ProgressMode;
				if (progressMode == ProgressModes.Count)
				{
					return new ChallengeProgress
					{
						Count = currentCount,
						Total = total
					};
				}
				return base.Progress;
			}
		}

		public override ChallengeTypes ChallengeType => ChallengeTypes.TimedBufferChallenge;

		public unsafe TimedBufferChallenge()
		{
		}

		public TimedBufferChallenge(IChallenge challengeToCount, int count, float interval)
			: this(new IChallenge[1] { challengeToCount }, count, interval)
		{
		}

		public TimedBufferChallenge(IChallenge challengeToCount, int count, float interval, Func<float> getCurrentTimeFunc)
			: this(new IChallenge[1] { challengeToCount }, count, interval, getCurrentTimeFunc)
		{
		}

		public TimedBufferChallenge(IChallenge[] challengesToCount, int count, float interval)
			: this(challengesToCount, count, interval, UnityTimeFunc)
		{
		}

		public unsafe TimedBufferChallenge(IChallenge[] challengesToCount, int count, float interval, Func<float> getCurrentTimeFunc)
		{
			this.challengesToCount = new List<IChallenge>(challengesToCount);
			total = count;
			this.interval = interval;
			this.getCurrentTimeFunc = getCurrentTimeFunc;
			Initialize();
		}

		protected override void Initialize()
		{
			base.Initialize();
			WithConditions.Clear();
			foreach (IChallenge challengeToCount in challengesToCount)
			{
				challengeToCount.SkipSerialization = true;
				challengeToCount.ChallengeCompleteEvent += delegate(IChallenge challenge, ChallengeEvents.IChallengeEventData data)
				{
					TimedBufferEntry item = new TimedBufferEntry
					{
						Time = getCurrentTimeFunc(),
						EventData = data
					};
					entryBuffer.Add(item);
					challengeToCount.Reset();
				};
				WithConditions.Add(challengeToCount);
			}
		}

		public override void Reset()
		{
			base.Reset();
			entryBuffer.Clear();
		}

		protected override bool EvaluateInternal(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			base.EvaluateInternal(challengeEventData);
			IEnumerable<TimedBufferEntry> source = entryBuffer;
			if (interval > 0f)
			{
				source = entryBuffer.Where((TimedBufferEntry entry) => entry.Time > getCurrentTimeFunc() - interval);
			}
			int num = currentCount;
			currentCount = 0;
			switch (BufferCountMethod)
			{
			case BufferCountMethods.UniqueToolCount:
				source = (from _ in source
					group _ by _.EventData.GetVar("t_vid")).Select(Enumerable.FirstOrDefault);
				currentCount = source.Count();
				break;
			case BufferCountMethods.UniqueAttackerCount:
				source = (from _ in source
					group _ by _.EventData.GetVar("ap_pid")).Select(Enumerable.FirstOrDefault);
				currentCount = source.Count();
				break;
			case BufferCountMethods.UniqueDefenderCount:
				source = (from _ in source
					group _ by _.EventData.GetVar("dp_pid")).Select(Enumerable.FirstOrDefault);
				currentCount = source.Count();
				break;
			case BufferCountMethods.UniqueGameCount:
				source = (from _ in source
					group _ by _.EventData.GetVar("gid")).Select(Enumerable.FirstOrDefault);
				currentCount = source.Count();
				break;
			case BufferCountMethods.GroupedToolMaxCount:
			{
				IEnumerable<IGrouping<object, TimedBufferEntry>> source2 = from entry in source
					group entry by entry.EventData.GetVar("t_vid");
				currentCount = ((source2.Count() > 0) ? source2.Max((Func<IGrouping<object, TimedBufferEntry>, int>)Enumerable.Count) : 0);
				break;
			}
			default:
				currentCount = source.Count();
				break;
			}
			entryBuffer = source.ToList();
			if (num != currentCount)
			{
				if (notificationCounts.Contains(currentCount))
				{
					Notify(currentCount, total);
				}
				base.Dirty = true;
			}
			return currentCount >= total;
		}

		public override Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = base.Serialize();
			dictionary["ccc"] = challengesToCount.Select((IChallenge _) => _.Serialize()).ToList();
			dictionary["t"] = total;
			dictionary["i"] = interval.ToString("F2", CultureInfo.InvariantCulture);
			dictionary["pm"] = (int)ProgressMode;
			if (notificationCounts.Count > 0)
			{
				dictionary["n"] = notificationCounts;
			}
			dictionary["pb"] = PersistBuffer;
			if (BufferCountMethod != BufferCountMethods.Count)
			{
				dictionary["m"] = (int)BufferCountMethod;
			}
			if (entryBuffer.Count > 0 && PersistBuffer)
			{
				dictionary["b"] = entryBuffer.Select((TimedBufferEntry _) => _.Serialize()).ToList();
			}
			return dictionary;
		}

		protected override void DeserializeInternal(Dictionary<string, object> jsonDict)
		{
			base.DeserializeInternal(jsonDict);
			List<Dictionary<string, object>> listKey = Util.GetListKey<Dictionary<string, object>>("ccc", jsonDict);
			IEnumerable<IChallenge> collection = from _ in listKey.Select(ChallengeParser.FromJsonDict)
				where _ != null
				select _;
			challengesToCount = new List<IChallenge>(collection);
			total = Util.GetKey<int>("t", jsonDict);
			interval = Util.GetFormattedFloatKey("i", jsonDict);
			ProgressMode = (ProgressModes)ChallengeParser.GetOptionalKey("pm", jsonDict, 0);
			PersistBuffer = ChallengeParser.GetOptionalKey("pb", jsonDict, defaultValue: true);
			BufferCountMethod = (BufferCountMethods)ChallengeParser.GetOptionalKey("m", jsonDict, 0);
			if (jsonDict.ContainsKey("b"))
			{
				entryBuffer = Util.GetListKey<Dictionary<string, object>>("b", jsonDict).Select(TimedBufferEntry.DeserializeFromDict).ToList();
			}
			if (jsonDict.ContainsKey("n"))
			{
				notificationCounts = Util.GetListKey<int>("n", jsonDict);
			}
		}
	}
	public abstract class RequiredObjectChallenge<T, SerializedT> : ChallengeBase where T : struct
	{
		public bool Inclusive = true;

		private const bool ExclusiveIncludesNullDefault = true;

		public bool ExclusiveIncludesNull = true;

		protected List<T> values = new List<T>();

		private const string VALUES_KEY = "vs";

		private const string INCLUSIVE_KEY = "in";

		private const string EXCLUSIVE_INCLUDES_NULL_KEY = "ex";

		public RequiredObjectChallenge()
		{
		}

		public RequiredObjectChallenge(T[] requiredValues)
			: this(inclusive: true, requiredValues)
		{
		}

		public RequiredObjectChallenge(T requiredValue, params T[] requiredValues)
			: this(inclusive: true, requiredValue, requiredValues)
		{
		}

		public RequiredObjectChallenge(bool inclusive, T requiredValue, params T[] requiredValues)
			: this(inclusive, requiredValues.Union(new T[1] { requiredValue }).ToArray())
		{
		}

		public RequiredObjectChallenge(bool inclusive, T[] requiredValues)
		{
			Inclusive = inclusive;
			values.AddRange(requiredValues);
		}

		protected override bool EvaluateInternal(ChallengeEvents.IChallengeEventData challengeEventData)
		{
			T? valueFromData = GetValueFromData(challengeEventData);
			if (Inclusive)
			{
				return valueFromData.HasValue && Matches(valueFromData.Value);
			}
			if (!valueFromData.HasValue)
			{
				if (!ExclusiveIncludesNull)
				{
					return false;
				}
				return true;
			}
			return !Matches(valueFromData.Value);
		}

		protected virtual bool Matches(T value)
		{
			return values.Contains(value);
		}

		protected abstract T? GetValueFromData(ChallengeEvents.IChallengeEventData challengeEventData);

		protected abstract SerializedT SerializeValue(T value);

		protected abstract T DeserializeValue(SerializedT obj);

		public override Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = base.Serialize();
			if (values.Count > 0)
			{
				dictionary["vs"] = values.Select((T _) => SerializeValue(_)).ToList();
			}
			ChallengeBase.SerializeOptionalField("in", Inclusive, defaultValue: true, dictionary);
			ChallengeBase.SerializeOptionalField("ex", ExclusiveIncludesNull, defaultValue: true, dictionary);
			return dictionary;
		}

		protected override void DeserializeInternal(Dictionary<string, object> jsonDict)
		{
			if (jsonDict.ContainsKey("vs"))
			{
				values = (from _ in Util.GetListKey<SerializedT>("vs", jsonDict)
					select DeserializeValue(_)).ToList();
			}
			else
			{
				values.Clear();
			}
			ExclusiveIncludesNull = ChallengeParser.GetOptionalKey("ex", jsonDict, defaultValue: true);
			Inclusive = ChallengeParser.GetOptionalKey("in", jsonDict, defaultValue: true);
		}
	}
