	{
		public override ChallengeTypes ChallengeType => ChallengeTypes.CompleteGameWithoutChallenge;

		public CompleteGameWithoutChallenge()
		{
		}

		public CompleteGameWithoutChallenge(IChallenge gameStartChallenge, IChallenge gameEndChallenge, params IChallenge[] resetChallenges)
			: base(new IChallenge[2] { gameStartChallenge, gameEndChallenge }, 2, -1f)
		{
			RequiredEventTypeChallenge item = new RequiredEventTypeChallenge(ChallengeEvents.ChallengeEventTypes.GameStart);
			ResetConditions.Add(item);
			foreach (IChallenge item2 in resetChallenges)
			{
				ResetConditions.Add(item2);
			}
		}
	}
