	public interface INumResolver<T> : IRecNetObject, IRecNetRequestObject where T : struct, IConvertible
	{
		NumResolverTypes NumResolverType { get; }

		T? GetValue(ChallengeEvents.IChallengeEventData eventData);
	}
	public enum NumResolverTypes
	{
		Constant,
		Var
	}
	public abstract class NumResolver<T> : INumResolver<T>, IRecNetObject, IRecNetRequestObject where T : struct, IConvertible
	{
		private const string TYPE_KEY = "t";

		public abstract NumResolverTypes NumResolverType { get; }

		public abstract T? GetValue(ChallengeEvents.IChallengeEventData eventData);

		public virtual Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("t", (int)NumResolverType);
			return dictionary;
		}

		public abstract void Deserialize(Dictionary<string, object> jsonDict);

		public static INumResolver<T> FromJsonDict(Dictionary<string, object> jsonDict)
		{
			if (jsonDict != null && jsonDict.ContainsKey("t"))
			{
				return (NumResolverTypes)Util.GetKey<int>("t", jsonDict) switch
				{
					NumResolverTypes.Constant => Util.Deserialize<ConstantNumResolver<T>>(jsonDict), 
					NumResolverTypes.Var => Util.Deserialize<VarNumResolver<T>>(jsonDict), 
					_ => throw new NotImplementedException(), 
				};
			}
			return null;
		}
	}
