		private AnimationClip cinematicAnimation;

		private CinematicBehaviour[] dependents;

		private static readonly int ANIMATOR_PLAY_ID = Animator.StringToHash("Play");

		private static readonly string ANIMATOR_TEMPLATE_ASSET_NAME = "CinematicTemplateController";

		private static readonly string ANIMATOR_CINEMATIC_ANIMATION_NAME = "CinematicTemplateAnimation";

		private static readonly string ANIMATOR_STATE_NAME = "Cinematic";

		private static RuntimeAnimatorController _animatorTemplate = null;

		private static RuntimeAnimatorController AnimatorTemplate
		{
			get
			{
				if (_animatorTemplate == null)
				{
					_animatorTemplate = Resources.Load(ANIMATOR_TEMPLATE_ASSET_NAME) as RuntimeAnimatorController;
				}
				return _animatorTemplate;
			}
		}

		public bool IsFinished
		{
			get
			{
				if (animator != null)
				{
					AnimatorStateInfo currentAnimatorStateInfo = animator.GetCurrentAnimatorStateInfo(0);
					return currentAnimatorStateInfo.IsName(ANIMATOR_STATE_NAME) && currentAnimatorStateInfo.normalizedTime > 1f;
				}
				return true;
			}
		}

		private void Awake()
		{
			dependents = GetComponentsInChildren<CinematicBehaviour>(includeInactive: true);
			InitializeAnimator();
		}

		private void InitializeAnimator()
		{
			if (animator == null)
			{
				animator = GetComponent<Animator>();
			}
			if (animator != null && cinematicAnimation != null && !OverrideAnimatorIsValid())
			{
				AnimatorOverrideController animatorOverrideController = new AnimatorOverrideController(AnimatorTemplate);
				animatorOverrideController[ANIMATOR_CINEMATIC_ANIMATION_NAME] = cinematicAnimation;
				animator.runtimeAnimatorController = animatorOverrideController;
			}
		}

		private bool OverrideAnimatorIsValid()
		{
			if (animator.runtimeAnimatorController == null)
			{
				return false;
			}
			if (animator.runtimeAnimatorController == AnimatorTemplate)
			{
				return false;
			}
			AnimatorOverrideController animatorOverrideController = animator.runtimeAnimatorController as AnimatorOverrideController;
			if (animatorOverrideController == null)
			{
				return false;
			}
			if (animatorOverrideController[ANIMATOR_CINEMATIC_ANIMATION_NAME] != cinematicAnimation)
			{
				return false;
			}
			return true;
		}

		public void Play()
		{
			animator.Rebind();
			animator.enabled = true;
			for (int i = 0; i < dependents.Length; i++)
			{
				dependents[i].gameObject.SetActive(value: true);
				dependents[i].Reset();
			}
			animator.SetTrigger(ANIMATOR_PLAY_ID);
		}

		public void Stop()
		{
			animator.enabled = false;
			for (int i = 0; i < dependents.Length; i++)
			{
				dependents[i].Reset();
				dependents[i].gameObject.SetActive(value: false);
			}
		}
	}
	public class CinematicAnimator : CinematicBehaviour
