	public class CinematicAudio : CinematicBehaviour
	{
		[Header("Configuration")]
		[SerializeField]
		private bool is2D;

		[SerializeField]
		private bool isLooping;

		[SerializeField]
		private RecRoomAudioClip audioClip;

		private SFXAudioSource audioSource;

		protected override void Play()
		{
			StopAudioSource();
			if (is2D)
			{
				if (isLooping)
				{
					audioSource = AudioManager.StartLooping2DSFX(audioClip);
				}
				else
				{
					audioSource = AudioManager.Play2DSFX(audioClip);
				}
			}
			else if (isLooping)
			{
				audioSource = AudioManager.StartLooping3DSFX(audioClip, base.transform);
			}
			else
			{
				audioSource = AudioManager.Play3DSFX(audioClip, base.transform);
			}
		}

		protected override void Stop()
		{
			StopAudioSource();
		}

		private void StopAudioSource()
		{
			if (audioSource != null)
			{
				AudioManager.StopLoopingSFX(audioSource);
				audioSource = null;
			}
		}
	}
	public abstract class CinematicBehaviour : UnityEngine.MonoBehaviour
	{
		[Header("Animation Parameters")]
		[SerializeField]
		private bool isPlaying;

		private bool wasPlaying;

		protected virtual void Awake()
		{
			isPlaying = false;
		}

		protected virtual void Start()
		{
			Stop();
		}

		protected virtual void OnDisable()
		{
			Reset();
		}

		protected virtual void Update()
		{
			if (!wasPlaying && isPlaying)
			{
				Play();
			}
			else if (wasPlaying && !isPlaying)
			{
				Stop();
			}
			wasPlaying = isPlaying;
		}

		public void Reset()
		{
			isPlaying = false;
			wasPlaying = false;
			Stop();
		}

		protected abstract void Play();

		protected abstract void Stop();
	}
	public class CinematicCameraShake : CinematicBehaviour
	{
		[Header("Configuration")]
		[SerializeField]
		private CameraShake.CameraShakeConfig cameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[SerializeField]
		private float innerRadius = 5f;

		[SerializeField]
		private float outerRadius = 15f;

		protected override void Play()
		{
			Player localPlayer = Player.LocalPlayer;
			if (localPlayer != null)
			{
				float magnitude = (localPlayer.Head.RigidbodyEx.targetPosition - base.transform.position).magnitude;
				float t = Mathf.InverseLerp(innerRadius, outerRadius, magnitude);
				float num = Mathf.SmoothStep(0f, 1f, t);
				CameraShake.SetShake(CameraShake.CameraShakeConfig.ScaleAmplitude(cameraShake, 1f - num));
			}
		}

		protected override void Stop()
		{
		}
	}
