	public class CinematicVideoPlayer : CinematicBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private VideoPlayer videoPlayer;

		[SerializeField]
		private AudioSource audioSource;

		public string streamingAssetsMoviePath;

		[SerializeField]
		private bool autoPlay;

		[Header("PS4-specific Parameters")]
		public int renderWidth = 1280;

		public int renderHeight = 720;

		public Renderer playTarget;

		[Header("Anti Tamper")]
		[SerializeField]
		[HideInInspector]
		private bool useAntiTamperHash = true;

		[SerializeField]
		[HideInInspector]
		[Tooltip("Generate this when you setup the streamingAssetsMoviePath. This is so the users dont put a new file under here and mess with what plays in the game.")]
		private string antiTamperHash;

		[SerializeField]
		[HideInInspector]
		private string hashedStreamingAssetsMoviePath;

		private bool isVideoCorrupt;

		public bool IsVideoPlaying => videoPlayer.isPlaying;

		protected override void Awake()
		{
			base.Awake();
			if (videoPlayer.clip == null && !string.IsNullOrEmpty(streamingAssetsMoviePath))
			{
				videoPlayer.url = GetStreamingAssetUrl();
			}
			if (videoPlayer.audioOutputMode == VideoAudioOutputMode.AudioSource && audioSource != null)
			{
				videoPlayer.EnableAudioTrack(0, enabled: true);
				videoPlayer.SetTargetAudioSource(0, audioSource);
				videoPlayer.controlledAudioTrackCount = 1;
			}
			videoPlayer.Prepare();
		}

		protected override void Start()
		{
			base.Start();
			if (!useAntiTamperHash || !(videoPlayer.clip == null) || string.IsNullOrEmpty(streamingAssetsMoviePath))
			{
				return;
			}
			string streamingAssetUrl = GetStreamingAssetUrl();
			if (!string.IsNullOrEmpty(antiTamperHash))
			{
				string text = antiTamperHash;
				text = Security.GetAntiTamperHash(streamingAssetUrl);
				if (text != antiTamperHash)
				{
					UnityEngine.Debug.LogWarning("Corrupted streaming file : " + streamingAssetUrl);
					isVideoCorrupt = true;
					AnalyticsHelper.StreamingAssetCheat(streamingAssetsMoviePath);
				}
				else if (autoPlay)
				{
					PlayVideo();
				}
			}
		}

		public void PlayStreamingVideo(string streamingPath)
		{
			videoPlayer.Stop();
			videoPlayer.url = $"{UnityEngine.Application.streamingAssetsPath}/{streamingPath}";
			videoPlayer.Play();
			UnityEngine.Debug.Log("Playing: " + streamingPath);
		}

		public void PlayVideo()
		{
			Play();
		}

		public void StopVideo()
		{
			Stop();
		}

		public void PauseVideo()
		{
			if (!isVideoCorrupt)
			{
				if (videoPlayer != null)
				{
					videoPlayer.Pause();
				}
				if (audioSource != null)
				{
					audioSource.Pause();
				}
			}
		}

		protected override void Play()
		{
			if (!isVideoCorrupt)
			{
				if (videoPlayer != null)
				{
					videoPlayer.Play();
				}
				if (audioSource != null)
				{
					audioSource.Play();
				}
			}
		}

		protected override void Stop()
		{
			if (!isVideoCorrupt)
			{
				if (videoPlayer != null)
				{
					videoPlayer.Stop();
				}
				if (audioSource != null)
				{
					audioSource.Stop();
				}
			}
		}

		private string GetStreamingAssetUrl()
		{
			return $"{UnityEngine.Application.streamingAssetsPath}/{streamingAssetsMoviePath}";
		}
	}
}
namespace RecRoom
{
	public class CircuitManager : NetworkedSingletonMonoBehaviour<CircuitManager>
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action m_PreEvaluateEvent;

		private const float UpdateIntervalSeconds = 0.1f;

		private const float FudgeRange = 0.01f;

		[SerializeField]
		private CircuitLinkVisual circuitLinkVisualPrefab;

		[SerializeField]
		[HideInInspector]
		private string sceneNodeGraphs;

		private bool circuitsDirty;

		private bool isNetworkPaused;

		private Dictionary<int, CircuitNodeDisplay> nodeDisplayInstances = new Dictionary<int, CircuitNodeDisplay>();

		private Dictionary<CircuitLink, CircuitLinkVisual> circuitLinkVisuals = new Dictionary<CircuitLink, CircuitLinkVisual>();

		private bool circuitGraphsInitialized;

		private float nextUpdateTime;

		private float? lastTick;

		private float nextInterval = 0.1f;

		private float offset;

		private Vector3[] linePoints = new Vector3[2];

		public CircuitLinkVisual CircuitLinkVisualPrefab => circuitLinkVisualPrefab;

		public static event Action PreEvaluateEvent
		{
			add
			{
				Action action = CircuitManager.m_PreEvaluateEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref CircuitManager.m_PreEvaluateEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = CircuitManager.m_PreEvaluateEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref CircuitManager.m_PreEvaluateEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
			CircuitNode.OnNodesConnectedEvent = (CircuitNode.NodeConnectionChanged)Delegate.Combine(CircuitNode.OnNodesConnectedEvent, new CircuitNode.NodeConnectionChanged(OnNodesConnected));
			CircuitNode.OnNodesDisconnectedEvent = (CircuitNode.NodeConnectionChanged)Delegate.Combine(CircuitNode.OnNodesDisconnectedEvent, new CircuitNode.NodeConnectionChanged(OnNodesDisconnected));
			CircuitNode.OnNodeInstantiatedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Combine(CircuitNode.OnNodeInstantiatedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeInstantiated));
			CircuitNode.OnNodeDestroyedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Combine(CircuitNode.OnNodeDestroyedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeDestroyed));
			CircuitDebug.OnLogEvent += OnCircuitLogEvent;
			CircuitDebug.OnLogExceptionEvent += OnCircuitLogExceptionEvent;
			DeserializeSceneNodeGraph();
			circuitGraphsInitialized = PhotonNetwork.isMasterClient;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
			CircuitNode.OnNodesConnectedEvent = (CircuitNode.NodeConnectionChanged)Delegate.Remove(CircuitNode.OnNodesConnectedEvent, new CircuitNode.NodeConnectionChanged(OnNodesConnected));
			CircuitNode.OnNodesDisconnectedEvent = (CircuitNode.NodeConnectionChanged)Delegate.Remove(CircuitNode.OnNodesDisconnectedEvent, new CircuitNode.NodeConnectionChanged(OnNodesDisconnected));
			CircuitNode.OnNodeInstantiatedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Remove(CircuitNode.OnNodeInstantiatedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeInstantiated));
			CircuitNode.OnNodeDestroyedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Remove(CircuitNode.OnNodeDestroyedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeDestroyed));
			CircuitDebug.OnLogEvent -= OnCircuitLogEvent;
			CircuitDebug.OnLogExceptionEvent -= OnCircuitLogExceptionEvent;
			CircuitNodeGraph.DestroyAll();
		}

		private void Update()
		{
			UpdateLineRenderers();
			float time = UnityEngine.Time.time;
			float num = time - nextUpdateTime;
			if (num > -0.01f)
			{
				float num2 = ((!lastTick.HasValue) ? 0.1f : (time - lastTick.Value));
				offset = nextInterval - num2;
				nextInterval = 0.1f + offset;
				nextUpdateTime = time + nextInterval;
				PushCircuitUpdate();
				lastTick = time;
			}
		}

		private void PushCircuitUpdate()
		{
			CircuitManager.PreEvaluateEvent.SafeInvoke();
			CircuitNodeGraph.Update(PhotonNetwork.ServerTimestamp, PhotonNetwork.isMasterClient);
			if (PhotonNetwork.isMasterClient && AnyGraphsDirty())
			{
				bool flag = PhotonNetwork.otherPlayers.Length > 0;
				byte[] arg = ((!flag) ? new byte[0] : CircuitNodeGraph.SerializeRuntimeState());
				EvaluateAllGraphs();
				if (flag)
				{
					byte[] arg2 = CircuitNodeGraph.SerializePostEvaluateState();
					base.photonView.RpcOthers(RpcUpdateRuntimeState, arg, arg2);
				}
			}
		}

		private void UpdateLineRenderers()
		{
			if (!CircuitVisibilityBehaviour.ShouldBeVisible)
			{
				return;
			}
			foreach (KeyValuePair<CircuitLink, CircuitLinkVisual> circuitLinkVisual in circuitLinkVisuals)
			{
				CircuitLink key = circuitLinkVisual.Key;
				CircuitLinkVisual value = circuitLinkVisual.Value;
				CircuitNodeDisplay circuitNodeDisplay = VisualFor<CircuitNodeDisplay>(key.SourceNode);
				CircuitNodeDisplay circuitNodeDisplay2 = VisualFor<CircuitNodeDisplay>(key.DestNode);
				if (circuitNodeDisplay == null || circuitNodeDisplay2 == null)
				{
					value.CircuitVisibilityBehaviour.ForceDisabled = true;
					continue;
				}
				value.CircuitVisibilityBehaviour.ForceDisabled = false;
				ref Vector3 reference = ref linePoints[0];
				reference = circuitNodeDisplay.OutputSlotDisplays[key.OutputSlot].transform.position;
				ref Vector3 reference2 = ref linePoints[1];
				reference2 = circuitNodeDisplay2.InputSlotDisplays[key.InputSlot].transform.position;
				value.LineRenderer.SetPositions(linePoints);
			}
		}

		private bool AnyGraphsDirty()
		{
			foreach (CircuitNodeGraph allGraph in CircuitNodeGraph.AllGraphs)
			{
				if (allGraph.NodeGraphDirty)
				{
					return true;
				}
			}
			return false;
		}

		private void EvaluateAllGraphs()
		{
			foreach (CircuitNodeGraph allGraph in CircuitNodeGraph.AllGraphs)
			{
				if (!allGraph.IsInternalGraph)
				{
					allGraph.Evaluate(PhotonNetwork.isMasterClient);
				}
			}
		}

		[PunRPC]
		protected void RpcUpdateRuntimeState(byte[] serializedRuntimeState, byte[] serializedPostEvaluateState, PhotonMessageInfo messageInfo)
		{
			if (circuitGraphsInitialized && messageInfo.sender.IsMasterClient)
			{
				CircuitNodeGraph.DeserializeRuntimeState(serializedRuntimeState);
				CircuitNodeGraph.DeserializePostEvaluateState(serializedPostEvaluateState);
				EvaluateAllGraphs();
			}
		}

		public void PauseNetworking()
		{
			if (!isNetworkPaused)
			{
				circuitsDirty = false;
			}
			isNetworkPaused = true;
		}

		public void UnpauseNetworking()
		{
			bool flag = isNetworkPaused;
			isNetworkPaused = false;
			if (flag && circuitsDirty)
			{
				UnityEngine.Debug.Log("Detected dirty circuits while networking was paused. Reinitializing...");
				MasterSendReinitializeMessage();
			}
		}

		public void SetVisualFor(CircuitNode node, CircuitNodeDisplay nodeDisplay)
		{
			if (node.IsVirtual)
			{
				throw new InvalidOperationException("You should not be setting a visual for a virtual node! ID:" + node.NodeId);
			}
			nodeDisplayInstances[node.NodeId] = nodeDisplay;
		}

		public void RemoveVisualFor(CircuitNode node)
		{
			if (node != null)
			{
				nodeDisplayInstances.Remove(node.NodeId);
			}
		}

		public T VisualFor<T>(CircuitNode node) where T : CircuitNodeDisplay
		{
			if (node.IsVirtual)
			{
				throw new InvalidOperationException("You should not be asking for a visual for a virtual node!");
			}
			CircuitNodeDisplay value = null;
			if (nodeDisplayInstances.TryGetValue(node.NodeId, out value))
			{
				return (T)value;
			}
			return (T)null;
		}

		public void RequestMasterInstantiateNode(System.Type nodeType, int? newNodeId = null)
		{
			CircuitNodeUuidAttribute fromType = CircuitNodeUuidAttribute.GetFromType(nodeType);
			RequestMasterInstantiateNode(fromType.Id, newNodeId);
		}

		public void RequestMasterInstantiateNode(CircuitNodeType nodeType, int? newNodeId = null)
		{
			Guid nodeType2 = new Guid(nodeType.uuid);
			RequestMasterInstantiateNode(nodeType2, newNodeId);
		}

		public void RequestMasterInstantiateNode(Guid nodeType, int? newNodeId = null)
		{
			base.photonView.RpcMaster(RpcMasterInstantiateNode, nodeType, newNodeId);
		}

		[PunRPC]
		private void RpcMasterInstantiateNode(Guid nodeType, int? newNodeId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				int arg = ((!newNodeId.HasValue) ? CircuitNode.NewNodeId() : newNodeId.Value);
				Guid arg2 = Guid.NewGuid();
				base.photonView.RpcAll(RpcInstantiateNode, nodeType, arg, arg2);
			}
		}

		[PunRPC]
		private void RpcInstantiateNode(Guid nodeType, int nodeId, Guid graphGuid, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
				InternalInstantiateNode(nodeType, nodeId, graphGuid);
			}
		}

		public void MasterLocalInstantiateNode(System.Type nodeType, int? newNodeId = null)
		{
			if (PhotonNetwork.isMasterClient)
			{
				CircuitNodeUuidAttribute fromType = CircuitNodeUuidAttribute.GetFromType(nodeType);
				int nodeId = ((!newNodeId.HasValue) ? CircuitNode.NewNodeId() : newNodeId.Value);
				Guid graphGuid = Guid.NewGuid();
				InternalInstantiateNode(fromType.Id, nodeId, graphGuid);
			}
		}

		private void InternalInstantiateNode(Guid nodeType, int nodeId, Guid graphGuid)
		{
			if (circuitGraphsInitialized)
			{
				Serialization.InstantiateNode(nodeType, nodeId, graphGuid);
				circuitsDirty = true;
			}
		}

		public void RequestMasterDestroyNode(int nodeId)
		{
			if (nodeId != 0)
			{
				base.photonView.RpcMaster(RpcMasterDestroyNode, nodeId);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Attempting to delete NULL_CIRCUIT_NODE_ID");
			}
		}

		public void MasterCopyNodeSettings(int nodeId, RecRoom.Circuits.Protobuf.CircuitNodeData circuitDataToClone)
		{
			if (PhotonNetwork.isMasterClient)
			{
				base.photonView.RpcAll(CopyNodeSettings, nodeId, circuitDataToClone.ToByteArray());
			}
		}

		[PunRPC]
		private void CopyNodeSettings(int nodeId, byte[] circuitDataToCloneBytes)
		{
			RecRoom.Circuits.Protobuf.CircuitNodeData data = RecRoom.Circuits.Protobuf.CircuitNodeData.Parser.ParseFrom(circuitDataToCloneBytes);
			CircuitNode circuitNode = CircuitNode.Find(nodeId);
			if (circuitNode != null)
			{
				circuitNode.CopySettings(data);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Couldn't copy settings to unknown node");
			}
		}

		[PunRPC]
		private void RpcMasterDestroyNode(int nodeId)
		{
			if (PhotonNetwork.isMasterClient && InternalDestroyNode(nodeId) && !isNetworkPaused)
			{
				base.photonView.RpcOthers(RpcDestroyNode, nodeId);
			}
		}

		[PunRPC]
		private void RpcDestroyNode(int nodeId, PhotonMessageInfo messageInfo)
		{
			if (circuitGraphsInitialized && messageInfo.sender.IsMasterClient)
			{
				InternalDestroyNode(nodeId);
			}
		}

		public void MasterLocalDestroyNode(int nodeId)
		{
			if (PhotonNetwork.isMasterClient)
			{
				InternalDestroyNode(nodeId);
			}
		}

		private bool InternalDestroyNode(int nodeId)
		{
			if (circuitGraphsInitialized)
			{
				CircuitNode circuitNode = CircuitNode.Find(nodeId);
				if (circuitNode == null)
				{
					UnityEngine.Debug.LogError("Attempting to destroy invalid node id: " + nodeId);
					return false;
				}
				circuitNode.Destroy();
				circuitsDirty = true;
				return true;
			}
			return false;
		}

		public void RequestMasterConnectNodes(int outputNodeId, OutputSlot outputSlot, int inputNodeId, InputSlot inputSlot)
