		[PunRPC]
		private void RpcConnectNodes(int outputNodeId, OutputSlot outputSlot, int inputNodeId, InputSlot inputSlot, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
