			}
		}

		public void MasterLocalConnectNodes(int outputNodeId, OutputSlot outputSlot, int inputNodeId, InputSlot inputSlot)
		{
			if (PhotonNetwork.isMasterClient)
			{
				InternalConnectNodes(outputNodeId, outputSlot, inputNodeId, inputSlot);
			}
		}

		private bool InternalConnectNodes(int outputNodeId, OutputSlot outputSlot, int inputNodeId, InputSlot inputSlot)
		{
			if (!circuitGraphsInitialized)
			{
				return false;
			}
			CircuitNode circuitNode = CircuitNode.Find(outputNodeId);
			CircuitNode circuitNode2 = CircuitNode.Find(inputNodeId);
			if (circuitNode == null)
			{
				UnityEngine.Debug.LogError("Invalid output node id");
				return false;
			}
			if (circuitNode2 == null)
			{
				UnityEngine.Debug.LogError("Invalid input node id");
				return false;
			}
			circuitsDirty = true;
			return circuitNode.ConnectToMyOutput(circuitNode2, inputSlot, outputSlot);
		}

		public void RequestMasterDisconnectNode(int nodeId, InputSlot inputSlot)
		{
			base.photonView.RpcMaster(RpcMasterDisconnectNode, nodeId, inputSlot);
		}

		[PunRPC]
		private void RpcMasterDisconnectNode(int nodeId, InputSlot inputSlot)
		{
			if (PhotonNetwork.isMasterClient && InternalDisconnectNode(nodeId, inputSlot))
			{
				base.photonView.RpcOthers(RpcDisconnectNode, nodeId, inputSlot);
			}
		}

		[PunRPC]
		private void RpcDisconnectNode(int nodeId, InputSlot inputSlot, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
				InternalDisconnectNode(nodeId, inputSlot);
			}
		}

		public void MasterLocalDisconnectNodes(int inputNodeId, InputSlot inputSlot)
		{
			if (PhotonNetwork.isMasterClient)
			{
				InternalDisconnectNode(inputNodeId, inputSlot);
			}
		}

		private bool InternalDisconnectNode(int nodeId, InputSlot inputSlot)
		{
			if (!circuitGraphsInitialized)
			{
				return false;
			}
			CircuitNode circuitNode = CircuitNode.Find(nodeId);
			if (circuitNode == null)
			{
				UnityEngine.Debug.LogError("Invalid node id");
				return false;
			}
			circuitNode.DisconnectInput(inputSlot);
			circuitsDirty = true;
			return true;
		}

		public void RequestMasterModifyNode(int nodeId, Dictionary<object, object> modifyArgs)
		{
			base.photonView.RpcMaster(RpcMasterModifyNode, nodeId, modifyArgs);
		}

