		private void RpcMasterModifyNode(int nodeId, Dictionary<object, object> modifyArgs)
		{
			if (PhotonNetwork.isMasterClient)
			{
				base.photonView.RpcAll(RpcModifyNode, nodeId, modifyArgs);
			}
		}

		[PunRPC]
		private void RpcModifyNode(int nodeId, Dictionary<object, object> modifyArgs, PhotonMessageInfo messageInfo)
		{
