			{
				InternalModifyNode(nodeId, modifyArgs);
			}
		}

		public void MasterLocalModifyNode(int nodeId, Dictionary<object, object> modifyArgs)
		{
			if (circuitGraphsInitialized && PhotonNetwork.isMasterClient)
			{
				InternalModifyNode(nodeId, modifyArgs);
			}
		}

		private void InternalModifyNode(int nodeId, Dictionary<object, object> modifyArgs)
		{
			if (circuitGraphsInitialized)
			{
				CircuitNode circuitNode = CircuitNode.Find(nodeId);
				if (circuitNode != null)
				{
					circuitNode.ModifyNode(modifyArgs);
					circuitsDirty = true;
