		}

		public void Reinitialize(CircuitNodeGraphCollectionData data, out Dictionary<int, int> nodeIdMappings)
		{
			CircuitNodeGraph.DeserializeAll(data, out nodeIdMappings);
			MasterSendReinitializeMessage();
		}

		public void InitializeNewGraph(CircuitNodeGraphData data, out Dictionary<int, int> nodeIdMappings)
		{
			CircuitNodeGraph.Deserialize(data, reassignNodeIds: true, out nodeIdMappings);
			MasterSendReinitializeMessage();
		}

		private void MasterSendReinitializeMessage()
		{
			if (PhotonNetwork.isMasterClient)
			{
				CircuitNodeGraphCollectionData arg = CircuitNodeGraph.PersistAll();
				byte[] arg2 = CircuitNodeGraph.SerializeRuntimeState();
				base.photonView.RpcOthers(RpcReinitializeCircuits, arg, arg2);
			}
		}

		private void MasterSendReinitializeMessageToPlayer(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient)
			{
				CircuitNodeGraphCollectionData arg = CircuitNodeGraph.PersistAll();
				byte[] arg2 = CircuitNodeGraph.SerializeRuntimeState();
				base.photonView.RpcPlayer(player, RpcReinitializeCircuits, arg, arg2);
			}
		}

		[PunRPC]
		private void RpcReinitializeCircuits(CircuitNodeGraphCollectionData circuitNodeGraphs, byte[] serializedRuntimeState, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
				try
				{
					CircuitNodeGraph.DeserializeAll(circuitNodeGraphs, out var _);
					CircuitNodeGraph.DeserializeRuntimeState(serializedRuntimeState);
					EvaluateAllGraphs();
					circuitGraphsInitialized = true;
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogError("Error reinitializing circuits for RoomDataBlobName:" + ((!(NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)) ? string.Empty : NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomDataBlobName));
					UnityEngine.Debug.LogException(exception);
					SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom("Room was out of sync!", SessionManager.LoadSceneSources.CIRCUIT_REINITIALIZE_ERROR);
				}
			}
		}

		private void OnPhotonPlayerConnected(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterSendReinitializeMessageToPlayer(player);
			}
		}

		private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			if (PhotonNetwork.isMasterClient)
			{
				MasterSendReinitializeMessage();
			}
		}

		private void OnNodesConnected(CircuitNode sourceNode, CircuitNode destNode, InputSlot inputSlot, OutputSlot outputSlot)
		{
			circuitsDirty = true;
			CircuitLink key = new CircuitLink(sourceNode, destNode, inputSlot, outputSlot);
			if (!circuitLinkVisuals.ContainsKey(key))
			{
				CircuitLinkVisual circuitLinkVisual = UnityEngine.Object.Instantiate(CircuitLinkVisualPrefab);
				circuitLinkVisual.gameObject.name = "CircuitLink [" + sourceNode.NodeId + "=>" + destNode.NodeId + "]";
				circuitLinkVisual.transform.SetParent(base.transform, worldPositionStays: false);
				circuitLinkVisual.transform.localPosition = Vector3.zero;
				circuitLinkVisuals[key] = circuitLinkVisual;
				circuitLinkVisual.LineRenderer.startColor = ColorFromOutput(outputSlot);
				circuitLinkVisual.LineRenderer.endColor = ColorFromInput(inputSlot);
			}
		}

		private void OnNodesDisconnected(CircuitNode sourceNode, CircuitNode destNode, InputSlot inputSlot, OutputSlot outputSlot)
		{
			circuitsDirty = true;
			CircuitLink key = new CircuitLink(sourceNode, destNode, inputSlot, outputSlot);
			if (circuitLinkVisuals.TryGetValue(key, out var value))
			{
				UnityEngine.Object.Destroy(value.gameObject);
			}
			circuitLinkVisuals.Remove(key);
		}

		private void OnNodeInstantiated(CircuitNode node)
		{
			circuitsDirty = true;
			AnalyticsHelper.UpdateCircuitNodeCount();
		}

		private void OnNodeDestroyed(CircuitNode node)
		{
			circuitsDirty = true;
			AnalyticsHelper.UpdateCircuitNodeCount();
			List<CircuitLink> list = circuitLinkVisuals.Keys.Where((CircuitLink link) => link.SourceNode.NodeId == node.NodeId || link.DestNode.NodeId == node.NodeId).ToList();
			foreach (CircuitLink item in list)
			{
				if (circuitLinkVisuals.TryGetValue(item, out var value))
				{
					UnityEngine.Object.Destroy(value.gameObject);
				}
				circuitLinkVisuals.Remove(item);
			}
		}

		public static Color ColorFromOutput(OutputSlot outputSlot)
		{
			return ColorFromInput(IOSlots.OutputSlotToInputSlot[outputSlot]);
		}

		public static Color ColorFromInput(InputSlot inputSlot)
		{
			return inputSlot switch
			{
				InputSlot.R => Color.red, 
				InputSlot.G => Color.green, 
				InputSlot.B => Color.blue, 
				InputSlot.C => Color.cyan, 
				InputSlot.Y => Color.yellow, 
				InputSlot.M => Color.magenta, 
				InputSlot.K => Color.black, 
				InputSlot.RESET => Color.white, 
				_ => Color.gray, 
			};
		}

		private void DeserializeSceneNodeGraph()
		{
			CircuitNodeGraphCollectionData data = (string.IsNullOrEmpty(sceneNodeGraphs) ? new CircuitNodeGraphCollectionData() : CircuitNodeGraphCollectionData.Parser.ParseFrom(ByteString.FromBase64(sceneNodeGraphs)));
			CircuitNodeGraph.DeserializeAll(data, out var _);
		}

		private void OnCircuitLogEvent(CircuitLogLevel level, string message)
		{
			switch (level)
			{
			case CircuitLogLevel.Error:
				UnityEngine.Debug.LogError(message);
				break;
			case CircuitLogLevel.Warning:
				UnityEngine.Debug.LogWarning(message);
				break;
			default:
				UnityEngine.Debug.Log(message);
				break;
			}
		}

		private void OnCircuitLogExceptionEvent(Exception e, string message)
		{
			if (!string.IsNullOrEmpty(message))
			{
				UnityEngine.Debug.LogError(message);
			}
			UnityEngine.Debug.LogException(e);
		}
	}
