	public static class CircuitNodeTypeExtension
	{
		public static bool TryGetCircuitNodeType(this CircuitNodeType circuitNodeType, out Guid guid, out System.Type t)
		{
			t = null;
			guid = Guid.Empty;
			if (circuitNodeType == null)
			{
				return false;
			}
			if (string.IsNullOrEmpty(circuitNodeType.uuid))
			{
				return false;
			}
			try
			{
				guid = new Guid(circuitNodeType.uuid);
			}
			catch
			{
				return false;
			}
			return Serialization.TryGetNodeTypeByGuid(guid, out t);
		}
	}
