namespace RecRoom.Core.Screens.PlayerController
{
	public class ScreenCameraSystem
	{
		private class BlendedList<T> : BlendedList<T, T>
		{
			public BlendedList(Interpolator interpolator)
				: base((Accessor)((T a) => a), interpolator)
			{
			}
		}

		private class BlendedList<T, Y>
		{
			public delegate Y Accessor(T value);

			public delegate Y Interpolator(Y lhs, Y rhs, float t);

			private struct Entry
			{
				public T Value;

				public float StartTime;

				public float TotalDuration;
			}

			private readonly Accessor accessor;

			private readonly Interpolator interpolator;

			private List<Entry> blendedEntries = new List<Entry>();

			private List<int> entriesToRemove = new List<int>();

			public bool IsBlending => blendedEntries.Count > 0;

			public BlendedList(Accessor accessor, Interpolator interpolator)
			{
				this.accessor = accessor;
				this.interpolator = interpolator;
			}

			public bool ContainsValue(T value)
			{
				return blendedEntries.FindIndex(delegate(Entry e)
				{
					ref T value2 = ref e.Value;
					object obj = value;
					return value2.Equals(obj);
				}) >= 0;
			}

			public void Add(T value, float blendDuration, float currentTime)
			{
				if (blendedEntries.Count != 0)
				{
					Entry entry = blendedEntries[blendedEntries.Count - 1];
					ref T value2 = ref entry.Value;
					object obj = value;
					if (value2.Equals(obj))
					{
						return;
					}
				}
				if (blendedEntries.Count >= 8)
				{
					int count = Mathf.Max(0, blendedEntries.Count - 8 + 1);
					blendedEntries.RemoveRange(0, count);
				}
				blendedEntries.Add(new Entry
				{
					Value = value,
					StartTime = currentTime,
					TotalDuration = blendDuration
				});
			}

			public void Clear()
			{
				blendedEntries.Clear();
				entriesToRemove.Clear();
			}

			public Y UpdateBlend(Y activeValue, float currentTime)
			{
				if (blendedEntries.Count > 0)
				{
					entriesToRemove.Clear();
					float blendT = 0f;
					BlendEntry(0, currentTime, out var value, out blendT);
					for (int i = 1; i < blendedEntries.Count; i++)
					{
						float blendT2 = 0f;
						BlendEntry(i, currentTime, out var value2, out blendT2);
						value = interpolator(value, value2, blendT);
						blendT = blendT2;
					}
					activeValue = interpolator(value, activeValue, blendT);
					if (blendT >= 0.9999f)
					{
						blendedEntries.Clear();
					}
					else
					{
						for (int num = entriesToRemove.Count - 1; num >= 0; num--)
						{
							blendedEntries.RemoveAt(entriesToRemove[num]);
						}
					}
				}
				return activeValue;
			}

			private void BlendEntry(int index, float currentTime, out Y value, out float blendT)
			{
				Entry entry = blendedEntries[index];
				value = accessor(entry.Value);
				float value2 = currentTime - entry.StartTime;
				float num = Mathf.InverseLerp(0f, entry.TotalDuration, value2);
				blendT = Mathf.SmoothStep(0f, 1f, num);
				if (num >= 1f)
				{
					entriesToRemove.Add(index);
				}
			}
		}

		private const float MIN_PITCH_FROM_UP = 10f;

		private const float MIN_PITCH_FROM_DOWN = 10f;

		private const int MAX_FADING_COUNT = 8;

		private ScreenPlayerCameraSettings activeCameraSettings;

		private ScreenCameraTargetingData activeCameraTargetingData;

		private ScreenPlayerCameraController activeCameraController;

		private Quaternion activeCameraRotation;

		private Vector3 activeCameraPosition;

		private BlendedList<ScreenPlayerCameraSettings, ScreenCameraTargetingData> fadingSettings;

		private BlendedList<ScreenPlayerCameraController, Quaternion> fadingControllerRotations;

		private BlendedList<ScreenPlayerCameraController, Vector3> fadingControllerPositions;

		private ScreenPlayerController cachedPlayerController;

		private Player cachedPlayer;

		private Camera cachedCamera;

		private ScreenInputHandler cachedInput;

		public bool IsBlending => fadingControllerPositions.IsBlending || fadingControllerRotations.IsBlending || fadingSettings.IsBlending;

		public ScreenCameraSystem()
		{
			fadingSettings = new BlendedList<ScreenPlayerCameraSettings, ScreenCameraTargetingData>((ScreenPlayerCameraSettings s) => s.TargetingData, ScreenCameraTargetingData.Interpolate);
			fadingControllerRotations = new BlendedList<ScreenPlayerCameraController, Quaternion>(UpdateBlendingCameraControllerRotationDuringBlendOut, InterpolateCameraRotation);
			fadingControllerPositions = new BlendedList<ScreenPlayerCameraController, Vector3>(UpdateBlendingCameraControllerPositionDuringBlendOut, InterpolateCameraPosition);
		}

		public bool IsActiveCameraSettings(ScreenPlayerCameraSettings cameraSettings)
		{
			return activeCameraSettings == cameraSettings;
		}

		public void SnapCameraSettings(ScreenPlayerCameraSettings cameraSettings)
		{
			fadingSettings.Clear();
			CrossFadeCameraSettings(cameraSettings, 0f);
		}

		public void CrossFadeCameraSettings(ScreenPlayerCameraSettings cameraSettings, float fadeDuration)
		{
			if (!(activeCameraSettings == cameraSettings))
			{
				if (activeCameraSettings != null && fadeDuration > 0f)
				{
					fadingSettings.Add(activeCameraSettings, fadeDuration, UnityEngine.Time.time);
				}
				activeCameraSettings = cameraSettings;
			}
		}

		public bool IsCameraControllerRunning(ScreenPlayerCameraController cameraController)
		{
			if (cameraController == activeCameraController)
			{
				return true;
			}
			return fadingControllerPositions.ContainsValue(cameraController) || fadingControllerRotations.ContainsValue(cameraController);
		}

		public void SnapCameraController(ScreenPlayerCameraController cameraController)
		{
			fadingControllerRotations.Clear();
			fadingControllerPositions.Clear();
			CrossFadeCameraController(cameraController, 0f);
		}

		public void CrossFadeCameraController(ScreenPlayerCameraController cameraController, float fadeDuration)
		{
			if (activeCameraController != cameraController)
			{
				if (activeCameraController != null && fadeDuration > 0f)
				{
					fadingControllerRotations.Add(activeCameraController, fadeDuration, UnityEngine.Time.time);
					fadingControllerPositions.Add(activeCameraController, fadeDuration, UnityEngine.Time.time);
				}
				activeCameraController = cameraController;
				if (activeCameraController != null)
				{
					activeCameraController.OnStartRunning();
				}
			}
		}

		public void OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			cachedPlayerController = playerController;
			cachedPlayer = player;
			cachedCamera = camera;
			cachedInput = input;
			if (activeCameraSettings != null)
			{
				activeCameraTargetingData = activeCameraSettings.TargetingData;
				if (fadingSettings.IsBlending)
				{
					activeCameraTargetingData = fadingSettings.UpdateBlend(activeCameraTargetingData, UnityEngine.Time.time);
				}
				if (camera != null)
				{
					activeCameraTargetingData.ApplyToCamera(camera);
				}
			}
			if (activeCameraController != null)
			{
				bool isBlending = fadingControllerRotations.IsBlending;
				activeCameraRotation = UpdateBlendingCameraControllerRotation(activeCameraController, isBlending, isBlendingOut: false);
				if (isBlending)
				{
					activeCameraRotation = fadingControllerRotations.UpdateBlend(activeCameraRotation, UnityEngine.Time.time);
				}
				if (camera != null)
				{
					camera.transform.rotation = activeCameraRotation;
				}
			}
			cachedPlayerController = null;
			cachedPlayer = null;
			cachedCamera = null;
			cachedInput = null;
		}

		public void OnLateUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			cachedPlayerController = playerController;
			cachedPlayer = player;
			cachedCamera = camera;
			cachedInput = input;
			if (activeCameraController != null)
			{
				bool isBlending = fadingControllerPositions.IsBlending;
				activeCameraPosition = UpdateBlendingCameraControllerPosition(activeCameraController, isBlending, isBlendingOut: false);
				if (isBlending)
				{
					activeCameraPosition = fadingControllerPositions.UpdateBlend(activeCameraPosition, UnityEngine.Time.time);
				}
				if (camera != null)
				{
					camera.transform.position = activeCameraPosition;
				}
			}
			cachedPlayerController = null;
			cachedPlayer = null;
			cachedCamera = null;
			cachedInput = null;
		}

		private Quaternion UpdateBlendingCameraControllerRotation(ScreenPlayerCameraController cameraController, bool isBlendingIn, bool isBlendingOut)
		{
			return cameraController.GetCameraRotation(cachedPlayerController, cachedPlayer, cachedCamera, cachedInput, activeCameraTargetingData, isBlendingIn, isBlendingOut);
		}

		private Quaternion UpdateBlendingCameraControllerRotationDuringBlendOut(ScreenPlayerCameraController cameraController)
		{
			return UpdateBlendingCameraControllerRotation(cameraController, isBlendingIn: false, isBlendingOut: true);
		}

		private Vector3 UpdateBlendingCameraControllerPosition(ScreenPlayerCameraController cameraController, bool isBlendingIn, bool isBlendingOut)
		{
			return cameraController.GetCameraPosition(cachedPlayerController, cachedPlayer, cachedCamera, cachedInput, activeCameraTargetingData, isBlendingIn, isBlendingOut);
		}

		private Vector3 UpdateBlendingCameraControllerPositionDuringBlendOut(ScreenPlayerCameraController cameraController)
		{
			return UpdateBlendingCameraControllerPosition(cameraController, isBlendingIn: false, isBlendingOut: true);
		}

		private Quaternion InterpolateCameraRotation(Quaternion lhs, Quaternion rhs, float t)
		{
			return Quaternion.Slerp(lhs, rhs, t);
		}

		private Vector3 InterpolateCameraPosition(Vector3 lhs, Vector3 rhs, float t)
		{
			return Vector3.Lerp(lhs, rhs, t);
		}
	}
}
namespace RecRoom.Core.Creation.Screens
{
	[Serializable]
	public abstract class MoveBaseScreenCreationController<T> : ScreenCreationOperationController
	{
		[NonSerialized]
		protected bool isTransient;

		[NonSerialized]
		protected bool selectionIsPickedUp;

		[NonSerialized]
		private bool addedToSelectionOnPickup;

		[NonSerialized]
		private Vector3 selectionPositionOnCursorPickup = Vector3.zero;

		[NonSerialized]
		private Vector3 cursorProjectionOnCursorPickup = Vector3.zero;

		[NonSerialized]
		private Vector3 lastValidCursorProjectionPosition = Vector3.zero;

		[NonSerialized]
		private Vector3 cursorModePlaneNormal;

		[NonSerialized]
		private bool inCursorMode;

		[NonSerialized]
		private Vector3 cameraRelativePosition = Vector3.zero;

		[NonSerialized]
		private Vector3 previousPivotPointCameraMode = Vector3.zero;

		[NonSerialized]
		private bool inCameraMode;

		[NonSerialized]
		private Quaternion previousCameraRotation = Quaternion.identity;

		[NonSerialized]
		protected UndoEntry pendingUndoEntry;

		private const float MAX_CAMERA_PLAYER_CURSOR_MOVEMENT_ANGLE_FROM_NINETY = 30f;

		private const float MIN_CURSOR_MOVEMENT_ANGLE_FROM_NINETY = 3f;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Move Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.RESUME)
			{
				isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
				selectionIsPickedUp = isTransient;
				inCursorMode = false;
				inCameraMode = false;
				addedToSelectionOnPickup = false;
				creationController.TranslationSnappingVisualization.Disable();
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.PAUSE)
			{
				if (!isTransient && selectionIsPickedUp)
				{
					selectionIsPickedUp = false;
					OnSelectionRelease(creationController);
				}
				isTransient = false;
			}
		}

		public void PushAsActiveOperation(ScreenCreationController creationController, UndoEntry pendingUndoEntry)
		{
			this.pendingUndoEntry = pendingUndoEntry;
			PushAsActiveOperation(creationController);
		}

		protected void UpdateMove(ScreenCreationController creationController, ISelectionContext<T> context, string dialogText, T[] pickingResults)
		{
			if (selectionIsPickedUp && !creationController.Input.UsingKeyboardMouse)
			{
				creationController.AddHudToolDialog(GetRotateInputIcon(creationController), "Rotate", 50);
				if (IsRotateInputPressed(creationController))
				{
					creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Rotate);
					return;
				}
				creationController.AddHudToolDialog(GetScaleInputIcon(creationController), "Scale", 50);
				if (IsScaleInputPressed(creationController))
				{
					creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Scale);
					return;
				}
				creationController.AddHudToolDialog(GetCloneInputIcon(creationController), "Clone", 50);
				if (IsCloneInputDown(creationController))
				{
					creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Clone);
					return;
				}
			}
			UpdateTranslation(creationController, context, dialogText, pickingResults);
		}

		protected virtual bool TryPickupSelection(ScreenCreationController creationController, ISelectionContext<T> context, string dialogText, T[] pickingResults)
		{
			return TryStartOperationOnSelection(creationController, context, dialogText, pickingResults, out addedToSelectionOnPickup);
		}

		protected virtual bool TryReleaseSelection(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			if (!context.HasSelection)
			{
				return true;
			}
			if (IsMultiSelectInputPressed(creationController))
			{
				return true;
			}
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Deselect", 75);
			if (IsCancelInputDown(creationController))
			{
				context.RemoveAllFromSelection();
				return true;
			}
			creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Finish Move", 100);
			if ((creationController.Input.UsingKeyboardMouse && !IsSelectInputPressed(creationController)) || (!creationController.Input.UsingKeyboardMouse && IsSelectInputDown(creationController)))
			{
				if (addedToSelectionOnPickup)
				{
					context.RemoveAllFromSelection();
				}
				return true;
			}
			return false;
		}

		private void UpdateTranslation(ScreenCreationController creationController, ISelectionContext<T> context, string dialogText, T[] pickingResults)
		{
			if (!selectionIsPickedUp)
			{
				if (creationController.Input.UsingKeyboardMouse)
				{
					creationController.AddHudToolDialog(GetCloneInputIcon(creationController), "Clone", 50);
					if (IsCloneInputPressed(creationController))
					{
						creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Clone);
						return;
					}
				}
				if (TryPickupSelection(creationController, context, dialogText, pickingResults))
				{
					selectionIsPickedUp = true;
					OnSelectionPickup(creationController, context);
				}
				else if (IsCancelInputDown(creationController))
				{
					context.RemoveAllFromSelection();
				}
				return;
			}
			bool flag = inCursorMode;
			inCursorMode = creationController.InCursorMovementMode;
			if (!flag && inCursorMode)
			{
				OnCursorModePickup(creationController, context);
			}
			bool flag2 = inCameraMode;
			inCameraMode = !creationController.InCursorMovementMode;
			if (!flag2 && inCameraMode)
			{
				OnCameraModePickup(creationController, context);
			}
			if (TryReleaseSelection(creationController, context))
			{
				selectionIsPickedUp = false;
				OnSelectionRelease(creationController);
				if (isTransient)
				{
					creationController.MakerPen.AuthorityPopPenTool();
				}
			}
			else if (inCursorMode)
			{
				UpdateCursorModeTranslation(creationController, context);
			}
			else if (inCameraMode)
			{
				UpdateCameraModeTranslation(creationController, context);
			}
		}

		private void OnSelectionPickup(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			inCursorMode = false;
			inCameraMode = false;
			SelectionRenderer.Enabled = false;
			creationController.RestrictCursorVisibility(this);
			if (creationController.MakerPen.Snapping.IsActive)
			{
				creationController.TranslationSnappingVisualization.Enable(context, creationController.MakerPen.Snapping.GridSize);
			}
			if (pendingUndoEntry == null)
			{
				pendingUndoEntry = CreateUndoEntry(creationController);
			}
		}

		protected abstract UndoEntry CreateUndoEntry(ScreenCreationController creationController);

		private void OnSelectionRelease(ScreenCreationController creationController)
		{
			if (pendingUndoEntry != null)
			{
				if (!pendingUndoEntry.IsFinalized)
				{
					pendingUndoEntry.Finalize(creationController.CreationContext);
				}
				creationController.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			SelectionRenderer.Enabled = true;
			creationController.RestoreCursorVisibility(this);
			creationController.TranslationSnappingVisualization.Disable();
		}

		private void UpdateCursorModeTranslation(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			Vector3 projectedPosition = Vector3.zero;
			if (!TryGetCursorProjectedPosition(creationController, cursorModePlaneNormal, selectionPositionOnCursorPickup, out projectedPosition))
			{
				projectedPosition = lastValidCursorProjectionPosition;
			}
			lastValidCursorProjectionPosition = projectedPosition;
			Vector3 vector = projectedPosition - cursorProjectionOnCursorPickup;
			Vector3 vector2 = vector + selectionPositionOnCursorPickup;
			if (creationController.MakerPen.Snapping.IsActive)
			{
				vector2 = creationController.MakerPen.Snapping.SnapToNearestTranslationIncrement(vector2, context.SelectionBounds);
			}
			Vector3 linearDisplacement = vector2 - context.SelectionBounds.center;
			context.TranslateSelection(linearDisplacement);
		}

		private void UpdateCameraModeTranslation(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			Vector3 vector = creationController.Camera.transform.TransformPoint(cameraRelativePosition);
			Quaternion rotation = creationController.Camera.transform.rotation;
			bool isActive = creationController.MakerPen.Snapping.IsActive;
			if (isActive)
			{
				vector = creationController.MakerPen.Snapping.SnapToNearestTranslationIncrement(vector, context.SelectionBounds);
			}
			Vector3 linearDisplacement = vector - previousPivotPointCameraMode;
			context.TranslateSelection(linearDisplacement);
			if (!isActive)
			{
				Quaternion quaternion = UnityExtensions.FromToRotation(previousCameraRotation, rotation);
				context.RotateSelection(quaternion, vector);
				Quaternion quaternion2 = Quaternion.Inverse(quaternion);
				Quaternion quaternion3 = Quaternion.Euler(0f, quaternion.eulerAngles.y, 0f);
				context.RotateSelection(quaternion3 * quaternion2, vector);
			}
			previousPivotPointCameraMode = vector;
			previousCameraRotation = rotation;
		}

		private bool TryGetCursorProjectedPosition(ScreenCreationController creationController, Vector3 planeNormal, Vector3 planeOrigin, out Vector3 projectedPosition)
		{
			Ray ray = creationController.Camera.ViewportPointToRay(creationController.CursorViewportPosition);
			float num = Vector3.Angle(planeNormal, ray.direction);
			float num2 = Mathf.Abs(90f - num);
			if (num2 <= 3f)
			{
				projectedPosition = Vector3.zero;
				return false;
			}
			Plane plane = new Plane(planeNormal, planeOrigin);
			float enter = 0f;
			if (plane.Raycast(ray, out enter))
			{
				projectedPosition = ray.GetPoint(enter);
				return true;
			}
			projectedPosition = Vector3.zero;
			return false;
		}

		private void OnCursorModePickup(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			Vector3 forward = creationController.Camera.transform.forward;
			float num = Vector3.Angle(Vector3.up, forward);
			float num2 = Mathf.Abs(90f - num);
			if (num2 <= 30f)
			{
				cursorModePlaneNormal = forward;
			}
			else
			{
				cursorModePlaneNormal = Vector3.up;
			}
			selectionPositionOnCursorPickup = context.SelectionBounds.center;
			if (!TryGetCursorProjectedPosition(creationController, cursorModePlaneNormal, selectionPositionOnCursorPickup, out cursorProjectionOnCursorPickup))
			{
				inCursorMode = false;
			}
			else
			{
				lastValidCursorProjectionPosition = cursorProjectionOnCursorPickup;
			}
		}

		private void OnCameraModePickup(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			previousCameraRotation = creationController.Camera.transform.rotation;
			previousPivotPointCameraMode = context.SelectionBounds.center;
			cameraRelativePosition = creationController.Camera.transform.InverseTransformPoint(context.SelectionBounds.center);
		}
	}
	[Serializable]
	public abstract class MultiSelectBaseScreenCreationController<T> : ScreenCreationOperationController
	{
		[NonSerialized]
		private bool isTransient;

		[NonSerialized]
		private T lastSelectedItem = default(T);

		[NonSerialized]
		private Vector3 lastHitPoint = Vector3.zero;

		[NonSerialized]
		private bool lastClickWasMenuClick;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Multi Select Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.MakerPen.QuickActionMenu.CloseMenu();
		}

		protected virtual bool ShouldIgnoreSelection(T objectToConsider)
		{
			return false;
		}

		protected void UpdateMultiSelection(ScreenCreationController creationController, ISelectionContext<T> context, T[] pickingResults)
		{
			if (isTransient && !IsMultiSelectInputPressed(creationController))
			{
				creationController.MakerPen.AuthorityPopPenTool();
				return;
			}
			if (context.HasSelection)
			{
				creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Deselect All", 50);
				if (IsCancelInputDown(creationController))
				{
					context.RemoveAllFromSelection();
					return;
				}
			}
			Ray ray = creationController.Camera.ViewportPointToRay(creationController.CursorViewportPosition);
			RaycastHit hitInfo;
			bool flag = creationController.MakerPen.QuickActionMenu.UpdateHover(ray, out hitInfo, float.MaxValue);
			int num = 0;
			Vector3 lastClosestHitPoint = Vector3.zero;
			if (!flag)
			{
				num = SpherecastPick(creationController, context, pickingResults, out lastClosestHitPoint, out var _);
				context.RenderHoverHighlight(num, pickingResults);
			}
			if (num == 0 || !context.IsSelected(pickingResults[0]))
			{
				creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Select", 75);
			}
			else
			{
				creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Deselect", 75);
			}
			if (!IsSelectInputDown(creationController))
			{
				return;
			}
			if (flag)
			{
				creationController.MakerPen.QuickActionMenu.TryClick();
				lastClickWasMenuClick = true;
				return;
			}
			lastClickWasMenuClick = false;
			creationController.MakerPen.QuickActionMenu.CloseMenu();
			for (int i = 0; i < num; i++)
			{
				T val = pickingResults[i];
				if (!ShouldIgnoreSelection(val))
				{
					if (context.IsSelected(val))
					{
						context.RemoveFromSelection(val);
						lastSelectedItem = default(T);
					}
					else
					{
						context.AddToSelection(val);
						lastSelectedItem = val;
						lastHitPoint = lastClosestHitPoint;
					}
				}
			}
			UpdateAvailableContextActions(creationController, lastSelectedItem, lastHitPoint);
		}

		protected virtual void UpdateAvailableContextActions(ScreenCreationController creationController, T lastSelectedItem, Vector3 lastHitPoint)
		{
			creationController.MakerPen.QuickActionMenu.CloseMenu();
			creationController.MakerPen.QuickActionMenu.ClearAllButtons();
		}
	}
}
