namespace RecRoom.Core.Creation.Screens.ObjectOperations
{
	[Serializable]
	public class ObjectCloneScreenCreationController : ScreenCreationOperationController
	{
		[NonSerialized]
		private bool isTransient;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Clone Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.RESUME)
			{
				isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			if (isTransient)
			{
				if (!IsCloneInputPressed(creationController))
				{
					creationController.MakerPen.AuthorityPopPenTool();
					return;
				}
				if (creationController.CreationContext.HasSelection && !creationController.Input.UsingKeyboardMouse)
				{
					creationController.CreationContext.CloneSelection();
					creationController.MakerPen.AuthorityPopPenTool();
				}
			}
			else
			{
				creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
				if (IsCancelInputDown(creationController))
				{
					creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
					return;
				}
			}
			if (!TryStartObjectOperationOnSelection(creationController, "Clone", out var _))
			{
				return;
			}
			IPromise<CreationManager.SpawnTemplateResult> promise = creationController.CreationContext.CloneSelection();
			promise.Then(delegate(CreationManager.SpawnTemplateResult result)
			{
				SingletonMonoBehaviour<Scheduler>.Instance.Run(creationController.MakerPen, creationController.CreationContext.WaitForValidBoundsOnCloneResult(result, delegate
				{
					OnCloneResult(result, creationController);
				}));
			});
		}

		private void OnCloneResult(CreationManager.SpawnTemplateResult data, ScreenCreationController creationController)
		{
			if (data.result != CreationResult.Success || data.spawnedTools == null)
			{
				return;
			}
			creationController.CreationContext.RemoveAllFromSelection();
			foreach (Tool spawnedTool in data.spawnedTools)
			{
				creationController.CreationContext.AddToSelection(spawnedTool.CreationObject);
			}
			CreateObjectsUndoEntry pendingUndoEntry = new CreateObjectsUndoEntry("clone", creationController.CreationContext.CurrentSelection, creationController.CreationContext);
			creationController.ObjectMoveController.PushAsActiveOperation(creationController, pendingUndoEntry);
		}
	}
