	public class ObjectConfigureScreenCreationController : ScreenCreationOperationController
	{
		[NonSerialized]
		private bool selectionCreatedOnOperationStart;

		[NonSerialized]
		private bool hasOpenedConfigMenu;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Configure Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			hasOpenedConfigMenu = false;
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (!hasOpenedConfigMenu)
			{
				if (IsCancelInputDown(creationController))
				{
					creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
				}
				else if (TryStartObjectOperationOnSelection(creationController, "Configure", out selectionCreatedOnOperationStart))
				{
					InitializeMenu(creationController);
				}
			}
			else if (!creationController.MakerPen.MoveablePaletteMenu.IsMenuVisible)
			{
				Cleanup(creationController);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			Cleanup(creationController);
		}

		private void InitializeMenu(ScreenCreationController creationController)
		{
			hasOpenedConfigMenu = true;
			creationController.MakerPen.RequestInteractableSettingsUI(creationController.CreationContext.CurrentSelection.First());
		}

		private void Cleanup(ScreenCreationController creationController)
		{
			if (hasOpenedConfigMenu && selectionCreatedOnOperationStart)
			{
				creationController.CreationContext.RemoveAllFromSelection();
				hasOpenedConfigMenu = false;
			}
		}
	}
	[Serializable]
	public class ObjectConnectScreenCreationController : ScreenCreationOperationController
	{
		[SerializeField]
		private CircuitLinkVisual connectionVisualPrefab;

		private CircuitLinkVisual _connectionVisual;

		private CircuitLinkVisual ConnectionVisual
		{
			get
			{
				if (_connectionVisual == null)
				{
					_connectionVisual = UnityEngine.Object.Instantiate(connectionVisualPrefab);
					_connectionVisual.gameObject.name = "ScreensMakerPenConnectionVisual";
				}
				return _connectionVisual;
			}
		}

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Wire Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.CreationContext.RemoveAllFromSelection();
			SetConnectionLineRendererEnabled(enabled: false);
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			Vector3 closestHitPoint;
			int num = SpherecastPickConnectionPoints(creationController, out closestHitPoint);
			creationController.CreationContext.ConnectionCreationContext.RenderHoverHighlight(num, ScreenCreationOperationController.CONNECTION_RAYCAST_RESULTS);
			if (!creationController.CreationContext.ConnectionCreationContext.HasStartPoint)
			{
				creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
				if (IsCancelInputDown(creationController))
				{
					creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
					return;
				}
				creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Start Connection", 100);
				if (num > 0 && IsSelectInputDown(creationController))
				{
					creationController.CreationContext.ConnectionCreationContext.SelectStartPoint(ScreenCreationOperationController.CONNECTION_RAYCAST_RESULTS[0]);
					SetConnectionLineRendererEnabled(enabled: true);
				}
				return;
			}
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.CreationContext.ConnectionCreationContext.DeselectStartPoint();
				SetConnectionLineRendererEnabled(enabled: false);
				return;
			}
			creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Finish Connection", 100);
			ConnectionVisual.LineRenderer.startColor = creationController.CreationContext.ConnectionCreationContext.ConnectionColor;
			Vector3 connectionStartPosition = creationController.CreationContext.ConnectionCreationContext.ConnectionStartPosition;
			Vector3 currentCursorWorldPosition = GetCurrentCursorWorldPosition(creationController, connectionStartPosition);
			ConnectionVisual.LineRenderer.SetPositions(new Vector3[2] { connectionStartPosition, currentCursorWorldPosition });
			if ((creationController.Input.UsingKeyboardMouse && !IsSelectInputPressed(creationController)) || (!creationController.Input.UsingKeyboardMouse && IsSelectInputDown(creationController)))
			{
				if (num > 0)
				{
					creationController.CreationContext.ConnectionCreationContext.ConnectToStartPoint(ScreenCreationOperationController.CONNECTION_RAYCAST_RESULTS[0]);
				}
				creationController.CreationContext.ConnectionCreationContext.DeselectStartPoint();
				SetConnectionLineRendererEnabled(enabled: false);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.CreationContext.ConnectionCreationContext.DeselectStartPoint();
			SetConnectionLineRendererEnabled(enabled: false);
		}

		private void SetConnectionLineRendererEnabled(bool enabled)
		{
			ConnectionVisual.LineRenderer.gameObject.SetActive(enabled);
			ConnectionVisual.CircuitVisibilityBehaviour.ForceDisabled = !enabled;
		}

		private Vector3 GetCurrentCursorWorldPosition(ScreenCreationController creationController, Vector3 planeOrigin)
		{
			Vector3 forward = creationController.Camera.transform.forward;
			Ray ray = creationController.Camera.ViewportPointToRay(creationController.CursorViewportPosition);
			float enter = 0f;
			if (new Plane(forward, planeOrigin).Raycast(ray, out enter))
			{
				return ray.GetPoint(enter);
			}
			return planeOrigin;
		}
	}
	[Serializable]
	public class ObjectCreateInventionInstanceScreenCreationController : ScreenCreationOperationController
	{
		[SerializeField]
		private float creationCameraOffset = 5f;

		[NonSerialized]
		private IPromise<CreationManager.SpawnTemplateResult> spawnInventionInstancePromise;

		[NonSerialized]
		private ScreenCreationController cachedCreationController;

		[NonSerialized]
		private Invention cachedInvention;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Create Invention Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.CreationContext.RemoveAllFromSelection();
			RequestSpawnInventionInstance(creationController);
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
			else if (creationController.CreationContext.HasSelection)
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.MakerPen.UndoStack.Add(new CreateObjectsUndoEntry("create", "invention", creationController.CreationContext.CurrentSelection, creationController.CreationContext));
			cachedCreationController = null;
		}

		private Vector3 GetDesiredObjectCreationPosition(ScreenCreationController creationController)
		{
			return creationController.Camera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, creationCameraOffset));
		}

		private Quaternion GetDesiredObjectCreationRotation(Camera camera)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(camera.transform.forward, Vector3.up).normalized;
			Quaternion parent = Quaternion.LookRotation(-normalized);
			Quaternion identity = Quaternion.identity;
			return parent.TransformRotation(identity);
		}

		private Invention GetDesiredInvention(ScreenCreationController creationController)
		{
			return creationController.MakerPen.SelectedInvention;
		}

		private void RequestSpawnInventionInstance(ScreenCreationController creationController)
		{
			if (spawnInventionInstancePromise == null || spawnInventionInstancePromise.IsCompleted)
			{
				cachedCreationController = creationController;
				cachedInvention = GetDesiredInvention(cachedCreationController);
				Vector3 desiredObjectCreationPosition = GetDesiredObjectCreationPosition(cachedCreationController);
				Quaternion desiredObjectCreationRotation = GetDesiredObjectCreationRotation(cachedCreationController.Camera);
				spawnInventionInstancePromise = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnInventionInstance(cachedInvention, desiredObjectCreationPosition, desiredObjectCreationRotation, 1f).Then(delegate(CreationManager.SpawnTemplateResult result)
				{
					OnSpawnInstanceResultReceived(result);
				}).Finally(delegate
				{
					spawnInventionInstancePromise = null;
				});
			}
		}

		private void OnSpawnInstanceResultReceived(CreationManager.SpawnTemplateResult data)
		{
			if (data.result != CreationResult.Success || data.spawnedTools == null)
			{
				return;
			}
			cachedCreationController.CreationContext.RemoveAllFromSelection();
			foreach (Tool spawnedTool in data.spawnedTools)
			{
				cachedCreationController.CreationContext.AddToSelection(spawnedTool.CreationObject);
			}
		}
	}
}
namespace RecRoom
{
	[Serializable]
	public class ObjectCreateInventionScreenCreationController : MultiSelectBaseScreenCreationController<CreationObject>
	{
		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Create Invention Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			base.OnStart(transitionType, creationController);
			creationController.CreationContext.RemoveAllFromSelection();
			creationController.MakerPen.StartInventionObjectsSelection();
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			UpdateMultiSelection(creationController, creationController.CreationContext, ScreenCreationOperationController.OBJECT_RAYCAST_RESULTS);
			if (creationController.CreationContext.HasSelection)
			{
				creationController.AddHudToolDialog(GetMenuInputIcon(creationController), "Finish", 50);
				if (IsMenuInputDown(creationController))
				{
					creationController.MakerPen.CompleteInventionObjectsSelection();
				}
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			base.OnStop(transitionType, creationController);
			creationController.CreationContext.RemoveAllFromSelection();
			creationController.MakerPen.CancelInventionObjectsSelection();
		}

		protected override bool ShouldIgnoreSelection(CreationObject objectToConsider)
		{
			return base.ShouldIgnoreSelection(objectToConsider);
		}

		protected override void UpdateAvailableContextActions(ScreenCreationController creationController, CreationObject lastSelectedItem, Vector3 lastHitPoint)
		{
			base.UpdateAvailableContextActions(creationController, lastSelectedItem, lastHitPoint);
			if (lastSelectedItem != null)
			{
				bool flag = false;
				if (creationController.MakerPen.SelectInventionOperation.CanSelectInvention)
				{
					creationController.MakerPen.QuickActionMenu.AddButton("Select entire invention", QuickActionButton.PositionDefaults.Right, creationController.MakerPen.SelectInventionOperation.TrySelectRestOfInvention);
					flag = true;
				}
				if (flag)
				{
					creationController.MakerPen.QuickActionMenu.ShowMenuHint(lastHitPoint);
				}
			}
		}
	}
}
namespace RecRoom.Core.Creation.Screens.ObjectOperations
{
	[Serializable]
	public class ObjectCreateScreenCreationController : ScreenCreationOperationController
	{
		[SerializeField]
		private float creationCameraOffset = 5f;

		[NonSerialized]
		private IPromise<Tool> stampToolSpawnPromise;

		[NonSerialized]
		private ScreenCreationController cachedCreationController;

		[NonSerialized]
		private SpawnableToolType cachedSpawnableToolType = SpawnableToolType.INVALID;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Create Prop Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.CreationContext.RemoveAllFromSelection();
			RequestSpawnedTool(creationController);
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
			else if (creationController.CreationContext.HasSelection)
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.MakerPen.UndoStack.Add(new CreateObjectsUndoEntry("create", creationController.CreationContext.CurrentSelection, creationController.CreationContext));
			cachedCreationController = null;
		}

		private Vector3 GetDesiredObjectCreationPosition(ScreenCreationController creationController)
		{
			return creationController.Camera.ViewportToWorldPoint(new Vector3(0.5f, 0.5f, creationCameraOffset));
		}

		private Quaternion GetDesiredObjectCreationRotation(SpawnableToolType toolType, Camera camera)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(camera.transform.forward, Vector3.up).normalized;
			Quaternion parent = Quaternion.LookRotation(-normalized);
			Quaternion spawnableToolSpawnRotation = SpawnableToolSettings.GetSpawnableToolSpawnRotation(toolType);
			return parent.TransformRotation(spawnableToolSpawnRotation);
		}

		private SpawnableToolType GetDesiredSpawnableToolType(ScreenCreationController creationController)
		{
			return creationController.MakerPen.SelectedSpawnableToolType;
		}

		private void RequestSpawnedTool(ScreenCreationController creationController)
		{
			if (stampToolSpawnPromise == null || stampToolSpawnPromise.IsCompleted)
			{
				cachedCreationController = creationController;
				cachedSpawnableToolType = GetDesiredSpawnableToolType(cachedCreationController);
				Vector3 desiredObjectCreationPosition = GetDesiredObjectCreationPosition(cachedCreationController);
				Quaternion desiredObjectCreationRotation = GetDesiredObjectCreationRotation(cachedSpawnableToolType, cachedCreationController.Camera);
				stampToolSpawnPromise = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnTool(cachedSpawnableToolType, desiredObjectCreationPosition, desiredObjectCreationRotation, 1f).Then(delegate(Tool tool)
				{
					OnToolSpawn(tool);
				}).Finally(delegate
				{
					stampToolSpawnPromise = null;
				});
			}
		}

		private void OnToolSpawn(Tool tool)
		{
			if (cachedCreationController != null)
			{
				cachedCreationController.CreationContext.RemoveAllFromSelection();
				if (tool != null && tool.CreationObject != null)
				{
					cachedCreationController.CreationContext.AddToSelection(tool.CreationObject);
					Vector3 desiredObjectCreationPosition = GetDesiredObjectCreationPosition(cachedCreationController);
					Quaternion desiredObjectCreationRotation = GetDesiredObjectCreationRotation(cachedSpawnableToolType, cachedCreationController.Camera);
					cachedCreationController.CreationContext.TranslateSelection(desiredObjectCreationPosition - cachedCreationController.CreationContext.SelectionBounds.center);
					cachedCreationController.CreationContext.RotateSelection(desiredObjectCreationRotation * Quaternion.Inverse(cachedCreationController.CreationContext.SelectionTransform.rotation), null);
				}
			}
		}
	}
	[Serializable]
	public class ObjectDeleteScreenCreationController : ScreenCreationOperationController
	{
		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Delete Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			bool addedToSelection;
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
			else if (TryStartObjectOperationOnSelection(creationController, "Delete", out addedToSelection))
			{
				CreationObject[] cachedSelection = creationController.CreationContext.CurrentSelection.ToArray();
				creationController.CreationContext.SerializeSelection().Then(delegate(SpawnableTemplateData data)
				{
					DeleteObjectsUndoEntry entry = new DeleteObjectsUndoEntry(cachedSelection, data, creationController.CreationContext);
					creationController.MakerPen.UndoStack.Add(entry);
				}).Finally(delegate
				{
					creationController.CreationContext.SetSelection(cachedSelection.Length, cachedSelection);
					creationController.CreationContext.DeleteSelection();
					creationController.CreationContext.RemoveAllFromSelection();
				});
				creationController.CreationContext.DeleteSelection();
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}
	}
	public class ObjectEditScreenCreationController : ScreenCreationOperationController
	{
		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Edit Shapes Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			if (TryStartObjectOperationOnSelection(creationController, "Start Editing", out var _, ShapeContainerSelectionFilter))
			{
				Collider oBJECT_RAYCAST_LAST_COLLIDER_HIT = ScreenCreationOperationController.OBJECT_RAYCAST_LAST_COLLIDER_HIT;
				ShapeContainer shapeContainerFromObjectSelection = GetShapeContainerFromObjectSelection(creationController, oBJECT_RAYCAST_LAST_COLLIDER_HIT);
				if (shapeContainerFromObjectSelection != null && shapeContainerFromObjectSelection.CanBeEditedAfterCreation)
				{
					creationController.CreationContext.ShapeCreationContext.TrySelectShapeContainer(shapeContainerFromObjectSelection);
					creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Edit, MakerPen.TargetMode.Shape);
				}
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		private bool ShapeContainerSelectionFilter(CreationObject creationObject)
		{
			return creationObject != null && creationObject.GetComponentInChildren<ShapeContainer>() != null;
		}

		private ShapeContainer GetShapeContainerFromObjectSelection(ScreenCreationController creationController, Collider hitCollider)
		{
			if (creationController.CreationContext.SelectionCount != 1)
			{
				return null;
			}
			return creationController.CreationContext.CurrentSelection.First().GetComponentForCollider<ShapeContainer>(hitCollider);
		}
	}
	[Serializable]
	public class ObjectFreezeScreenCreationController : ScreenCreationOperationController
	{
		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Toggle Freeze Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
				return;
			}
			bool addedToSelection = false;
			if (!TryStartObjectOperationOnSelection(creationController, "Toggle Freeze", out addedToSelection))
			{
				return;
			}
			bool flag = creationController.CreationContext.HasAnyUnfrozenObject();
			UndoEntry undoEntry = null;
			if (flag)
			{
				undoEntry = new FreezeObjectsUndoEntry(creationController.CreationContext.CurrentSelection, creationController.CreationContext);
			}
			if (creationController.CreationContext.SetSelectionFrozen(flag))
			{
				if (undoEntry == null)
				{
					undoEntry = new UnfreezeObjectsUndoEntry(creationController.CreationContext.CurrentSelection, creationController.CreationContext);
				}
				creationController.MakerPen.UndoStack.Add(undoEntry);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.Format("Object{0} {1}", (creationController.CreationContext.SelectionCount <= 1) ? string.Empty : "s", (!flag) ? "unfrozen" : "frozen"), 3f);
			}
			creationController.CreationContext.RemoveAllFromSelection();
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}
	}
