namespace RecRoom.Core.Creation.Screens
{
	[Serializable]
	public abstract class RotateBaseScreenCreationController<T> : ScreenCreationOperationController
	{
		private enum RotationType
		{
			PITCH,
			YAW,
			ROLL
		}

		private const float MOUSE_ROTATION_ANGLE_DEGREES_PER_MICKEY = 0.0125f;

		[SerializeField]
		private float maxRotationAngularSpeedGamepad = 90f;

		[NonSerialized]
		protected bool isTransient;

		[NonSerialized]
		protected bool selectionIsPickedUp;

		[NonSerialized]
		private bool isRotating;

		[NonSerialized]
		private bool addedToSelectionOnPickup;

		[NonSerialized]
		private RotationType currentRotationType;

		[NonSerialized]
		private LocalRotationAxis currentRotationAxis;

		[NonSerialized]
		private float currentRotationSign = 1f;

		[NonSerialized]
		private float accumulatedRotation;

		[NonSerialized]
		private Quaternion initialRotation = Quaternion.identity;

		[NonSerialized]
		private Vector3 initialPivotPoint = Vector3.zero;

		[NonSerialized]
		protected UndoEntry pendingUndoEntry;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Rotate Mode";
			}
		}

		public override bool BlocksCameraMotion
		{
			[CompilerGenerated]
			get
			{
				return selectionIsPickedUp;
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
			selectionIsPickedUp = isTransient;
			isRotating = false;
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.PAUSE)
			{
				if (!isTransient && selectionIsPickedUp)
				{
					selectionIsPickedUp = false;
					OnSelectionRelease(creationController);
				}
				isTransient = false;
			}
		}

		protected void UpdateTransform(ScreenCreationController creationController, ISelectionContext<T> context, T[] pickingResults)
		{
			if (isTransient && !IsRotateInputPressed(creationController))
			{
				creationController.MakerPen.AuthorityPopPenTool();
			}
			else if (!selectionIsPickedUp)
			{
				if (creationController.Input.UsingKeyboardMouse)
				{
					creationController.AddHudToolDialog(GetCloneInputIcon(creationController), "Clone", 50);
					if (IsCloneInputPressed(creationController))
					{
						creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Clone);
						return;
					}
				}
				if (TryPickupSelection(creationController, context, pickingResults))
				{
					selectionIsPickedUp = true;
					OnSelectionPickup(creationController);
				}
			}
			else if (TryReleaseSelection(creationController, context))
			{
				selectionIsPickedUp = false;
				OnSelectionRelease(creationController);
			}
			else if (creationController.Input.UsingKeyboardMouse)
			{
				UpdateRotationMouse(creationController, context);
			}
			else
			{
				UpdateRotationGamepad(creationController, context);
			}
		}

		private bool TryPickupSelection(ScreenCreationController creationController, ISelectionContext<T> context, T[] pickingResults)
		{
			return isTransient || TryStartOperationOnSelection(creationController, context, "Rotate", pickingResults, out addedToSelectionOnPickup);
		}

		private bool TryReleaseSelection(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			if (isTransient)
			{
				return false;
			}
			if (!context.HasSelection)
			{
				return true;
			}
			if (IsMultiSelectInputPressed(creationController))
			{
				return true;
			}
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Deselect", 50);
			if (IsCancelInputDown(creationController))
			{
				context.RemoveAllFromSelection();
				return true;
			}
			creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Finish Rotate", 75);
			if ((creationController.Input.UsingKeyboardMouse && !IsSelectInputPressed(creationController)) || (!creationController.Input.UsingKeyboardMouse && IsSelectInputDown(creationController)))
			{
				if (addedToSelectionOnPickup)
				{
					context.RemoveAllFromSelection();
				}
				return true;
			}
			return false;
		}

		private void OnSelectionPickup(ScreenCreationController creationController)
		{
			isRotating = false;
			SelectionRenderer.Enabled = false;
			creationController.RestrictCursorVisibility(this);
			pendingUndoEntry = CreateUndoEntry(creationController);
		}

		protected abstract UndoEntry CreateUndoEntry(ScreenCreationController creationController);

		private void OnSelectionRelease(ScreenCreationController creationController)
		{
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(creationController.CreationContext);
				creationController.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			isRotating = false;
			SelectionRenderer.Enabled = true;
			creationController.RestoreCursorVisibility(this);
		}

		private void UpdateRotationGamepad(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			float pitchInput = 0f;
			float yawInput = 0f;
			float rollInput = 0f;
			GetInputRotationAmount(creationController, out pitchInput, out yawInput, out rollInput);
			if (!isRotating)
			{
				isRotating = TryStartRotationGamepad(creationController, context, yawInput, pitchInput, rollInput, out var rotationType, out var rotationAxis, out var rotationSign);
				if (isRotating)
				{
					currentRotationType = rotationType;
					currentRotationAxis = rotationAxis;
					currentRotationSign = rotationSign;
					OnRotationStart(context);
				}
			}
			if (isRotating)
			{
				float num = 0f;
				switch (currentRotationType)
				{
				case RotationType.PITCH:
					num = pitchInput;
					break;
				case RotationType.YAW:
					num = -1f * yawInput;
					break;
				case RotationType.ROLL:
					num = -1f * rollInput;
					break;
				}
				if (num == 0f)
				{
					isRotating = false;
					return;
				}
				float deltaRotation = num * maxRotationAngularSpeedGamepad * UnityEngine.Time.unscaledDeltaTime;
				UpdateRotationCommon(creationController, context, deltaRotation);
			}
		}

		private void UpdateRotationMouse(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			Vector2 mouseDeltaMickeys = creationController.Input.MouseDeltaMickeys;
			if (!isRotating)
			{
				isRotating = TryStartRotationMouse(creationController, context, mouseDeltaMickeys, out var rotationType, out var rotationAxis, out var rotationSign);
				if (isRotating)
				{
					currentRotationType = rotationType;
					currentRotationAxis = rotationAxis;
					currentRotationSign = rotationSign;
					OnRotationStart(context);
				}
			}
			if (isRotating)
			{
				float num = ((currentRotationType != RotationType.PITCH) ? mouseDeltaMickeys.x : mouseDeltaMickeys.y);
				float deltaRotation = -1f * num * 0.0125f;
				UpdateRotationCommon(creationController, context, deltaRotation);
			}
		}

		private void UpdateRotationCommon(ScreenCreationController creationController, ISelectionContext<T> context, float deltaRotation)
		{
			if (creationController.MakerPen.Snapping.IsActive)
			{
				float snapRotateAngleIncrement = creationController.MakerPen.Snapping.SnapRotateAngleIncrement;
				float num = snapRotateAngleIncrement / 15f;
				deltaRotation *= num;
			}
			accumulatedRotation += deltaRotation;
			if (accumulatedRotation >= 360f)
			{
				accumulatedRotation -= 360f;
			}
			else if (accumulatedRotation <= -360f)
			{
				accumulatedRotation += 360f;
			}
			Vector3 selectionRotationAxisVector = GetSelectionRotationAxisVector(currentRotationAxis, currentRotationSign);
			Quaternion quaternion = Quaternion.AngleAxis(accumulatedRotation, selectionRotationAxisVector);
			Quaternion quaternion2 = initialRotation * quaternion;
			if (creationController.MakerPen.Snapping.IsActive)
			{
				quaternion2 = creationController.MakerPen.Snapping.SnapToNearestRotationIncrement(quaternion2);
			}
			Quaternion angularDisplacement = quaternion2 * Quaternion.Inverse(context.SelectionTransform.rotation);
			context.RotateSelection(angularDisplacement, initialPivotPoint);
		}

		private void OnRotationStart(ISelectionContext<T> context)
		{
			accumulatedRotation = 0f;
			initialRotation = context.SelectionTransform.rotation;
			initialPivotPoint = context.SelectionBounds.center;
		}

		private bool TryStartRotationGamepad(ScreenCreationController creationController, ISelectionContext<T> context, float yawInput, float pitchInput, float rollInput, out RotationType rotationType, out LocalRotationAxis rotationAxis, out float rotationSign)
		{
			float num = Mathf.Abs(yawInput);
			float num2 = Mathf.Abs(pitchInput);
			float num3 = Mathf.Abs(rollInput);
			if (num2 > 0f && num2 >= num && num2 >= num3)
			{
				GetSelectionClosestRotationAxis(context, creationController.Camera.transform.right, out rotationAxis, out rotationSign);
				rotationType = RotationType.PITCH;
				return true;
			}
			if (num > 0f && num >= num2 && num >= num3)
			{
				GetSelectionClosestRotationAxis(context, creationController.Camera.transform.up, out rotationAxis, out rotationSign);
				rotationType = RotationType.YAW;
				return true;
			}
			if (num3 > 0f && num3 >= num && num3 >= num2)
			{
				GetSelectionClosestRotationAxis(context, creationController.Camera.transform.forward, out rotationAxis, out rotationSign);
				rotationType = RotationType.ROLL;
				return true;
			}
			rotationType = RotationType.YAW;
			rotationAxis = LocalRotationAxis.X;
			rotationSign = 1f;
			return false;
		}

		private bool TryStartRotationMouse(ScreenCreationController creationController, ISelectionContext<T> context, Vector2 deltaMouseMickeys, out RotationType rotationType, out LocalRotationAxis rotationAxis, out float rotationSign)
		{
			if (deltaMouseMickeys.sqrMagnitude < Mathf.Epsilon)
			{
				rotationType = RotationType.YAW;
				rotationAxis = LocalRotationAxis.X;
				rotationSign = 1f;
				return false;
			}
			if (Mathf.Abs(deltaMouseMickeys.x) > Mathf.Abs(deltaMouseMickeys.y))
			{
				rotationType = RotationType.YAW;
				GetSelectionClosestRotationAxis(context, creationController.Camera.transform.up, out rotationAxis, out rotationSign);
			}
			else
			{
				rotationType = RotationType.PITCH;
				GetSelectionClosestRotationAxis(context, creationController.Camera.transform.right, out rotationAxis, out rotationSign);
			}
			return true;
		}
	}
	[Serializable]
	public abstract class ScaleBaseScreenCreationController<T> : ScreenCreationOperationController
	{
		[SerializeField]
		private float maxScaleSpeed = 3f;

		private const float MOUSE_DELTA_SCALE_PER_MICKEY = 0.0002f;

		[NonSerialized]
		protected bool isTransient;

		[NonSerialized]
		protected bool selectionIsPickedUp;

		[NonSerialized]
		private bool addedToSelectionOnPickup;

		[NonSerialized]
		protected UndoEntry pendingUndoEntry;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Scale Mode";
			}
		}

		public override bool BlocksCameraMotion
		{
			[CompilerGenerated]
			get
			{
				return selectionIsPickedUp;
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
			selectionIsPickedUp = isTransient;
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.PAUSE)
			{
				if (!isTransient && selectionIsPickedUp)
				{
					selectionIsPickedUp = false;
					OnSelectionRelease(creationController);
				}
				isTransient = false;
			}
		}

		protected void UpdateTransform(ScreenCreationController creationController, ISelectionContext<T> context, T[] pickingResults)
		{
			if (isTransient && !IsScaleInputPressed(creationController))
			{
				creationController.MakerPen.AuthorityPopPenTool();
			}
			else if (!selectionIsPickedUp)
			{
				if (creationController.Input.UsingKeyboardMouse)
				{
					creationController.AddHudToolDialog(GetCloneInputIcon(creationController), "Clone", 50);
					if (IsCloneInputPressed(creationController))
					{
						creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Clone);
						return;
					}
				}
				if (TryPickupSelection(creationController, context, pickingResults))
				{
					selectionIsPickedUp = true;
					OnSelectionPickup(creationController);
				}
			}
			else if (TryReleaseSelection(creationController, context))
			{
				selectionIsPickedUp = false;
				OnSelectionRelease(creationController);
			}
			else if (creationController.Input.UsingKeyboardMouse)
			{
				UpdateScaleMouse(creationController, context);
			}
			else
			{
				UpdateScaleGamepad(creationController, context);
			}
		}

		private bool TryPickupSelection(ScreenCreationController creationController, ISelectionContext<T> context, T[] pickingResults)
		{
			return isTransient || TryStartOperationOnSelection(creationController, context, "Scale", pickingResults, out addedToSelectionOnPickup);
		}

		private bool TryReleaseSelection(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			if (isTransient)
			{
				return false;
			}
			if (!context.HasSelection)
			{
				return true;
			}
			if (IsMultiSelectInputPressed(creationController))
			{
				return true;
			}
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Deselect", 50);
			if (IsCancelInputDown(creationController))
			{
				context.RemoveAllFromSelection();
				return true;
			}
			creationController.AddHudToolDialog(GetSelectInputIcon(creationController), "Finish Scale", 75);
			if ((creationController.Input.UsingKeyboardMouse && !IsSelectInputPressed(creationController)) || (!creationController.Input.UsingKeyboardMouse && IsSelectInputDown(creationController)))
			{
				if (addedToSelectionOnPickup)
				{
					context.RemoveAllFromSelection();
				}
				return true;
			}
			return false;
		}

		private void OnSelectionPickup(ScreenCreationController creationController)
		{
			SelectionRenderer.Enabled = false;
			creationController.RestrictCursorVisibility(this);
			pendingUndoEntry = CreateUndoEntry(creationController);
		}

		protected abstract UndoEntry CreateUndoEntry(ScreenCreationController creationController);

		private void OnSelectionRelease(ScreenCreationController creationController)
		{
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(creationController.CreationContext);
				creationController.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			SelectionRenderer.Enabled = true;
			creationController.RestoreCursorVisibility(this);
		}

		private void UpdateScaleMouse(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			Vector2 mouseDeltaMickeys = creationController.Input.MouseDeltaMickeys;
			mouseDeltaMickeys.y *= -1f;
			float num = mouseDeltaMickeys.x + mouseDeltaMickeys.y;
			float deltaScale = num * 0.0002f;
			context.ScaleSelection(deltaScale, context.SelectionBounds.center);
		}

		private void UpdateScaleGamepad(ScreenCreationController creationController, ISelectionContext<T> context)
		{
			float inputScaleAmount = GetInputScaleAmount(creationController);
			float deltaScale = maxScaleSpeed * inputScaleAmount * UnityEngine.Time.unscaledDeltaTime;
			context.ScaleSelection(deltaScale, context.SelectionBounds.center);
		}
	}
