		public ScreenCreationController()
		{
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterInitialState, null, OnUpdateInitialState);
			stateMachine.AddState(2, OnEnterCameraMovementState, OnExitCameraMovementState, OnUpdateCameraMovementState);
			stateMachine.AddState(2, 0, OnEnterCameraMovementRunningSubState, null, OnUpdateCameraMovementRunningSubState);
			stateMachine.AddState(2, 1, OnEnterCameraMovementPausedSubState, null, OnUpdateCameraMovementPausedSubState);
			stateMachine.AddState(3, OnEnterCursorMovementState, OnExitCursorMovementState, OnUpdateCursorMovementState);
			stateMachine.AddState(4, OnEnterMenuInteractionState, OnExitMenuInteractionState, OnUpdateMenuInteractionState);
			stateMachine.AddState(4, 1, OnEnterMainMenuSubState, OnExitMainMenuSubState, OnUpdateMainMenuSubState);
			stateMachine.AddState(4, 2, OnEnterPaletteMenuSubState, OnExitPaletteMenuSubState, OnUpdatePaletteMenuSubState);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Move, objectMoveController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Select, objectMultiSelectController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Rotate, objectRotateController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Scale, objectScaleController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Edit, objectEditController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.CreateObject, objectCreateController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Clone, objectCloneController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Delete, objectDeleteController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Freeze, objectFreezeController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Repaint, objectColorController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Connect, objectConnectController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.Settings, objectConfigureController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.CreateInvention, objectCreateInventionController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.CreateInventionInstance, objectCreateInventionInstanceController);
			RegisterCreationOperation(MakerPen.TargetMode.Object, MakerPen.ToolMode.CreateTrigger, triggerObjectCreationController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Move, shapeMoveController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Select, shapeMultiSelectController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Rotate, shapeRotateController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Scale, shapeScaleController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Edit, shapeEditController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.CreateShape, shapeCreateController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Clone, shapeCloneController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Delete, shapeDeleteController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Repaint, shapeColorController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.Settings, shapeConfigureController);
			RegisterCreationOperation(MakerPen.TargetMode.Shape, MakerPen.ToolMode.CreateTrigger, triggerShapeCreationController);
		}

		public void OnEnterMode(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, CreationContext creationContext, ScreenInputHandler input, MakerPen makerPen)
		{
			Input = input;
			CreationContext = creationContext;
			MakerPen = makerPen;
			Camera = camera;
			this.playerController = playerController;
			this.player = player;
			this.hud = hud;
			this.playerController.AddCrouchRestriction(this);
			this.playerController.AddMenuOpeningRestriction(this);
			steeringController.GazeTargetTransform = camera.transform;
			this.playerController.AddSteeringController(steeringController, this, 10010);
			this.playerController.CursorSystem.ShowCursor(hud);
			SnapCursorToCenterOfScreen();
			this.playerController.QuickCommsController.AddRestriction(this);
			this.player.PlayerLocomotion.AddMovementRestriction(this);
			lastCursorPosition = new Vector2(0.5f, 0.5f);
			isAttemptingToExit = false;
			MakerPen makerPen2 = MakerPen;
			makerPen2.ConfigurationMenuRequested = (Action<IConfigurable>)Delegate.Combine(makerPen2.ConfigurationMenuRequested, new Action<IConfigurable>(OnMakerPenMenuConfigurationFlowRequested));
			MakerPen makerPen3 = MakerPen;
			makerPen3.InventionDetailsRequested = (Action<Invention>)Delegate.Combine(makerPen3.InventionDetailsRequested, new Action<Invention>(OnMakerPenMenuInventionDetailsFlowRequested));
			MakerPen makerPen4 = MakerPen;
			makerPen4.InventionUpdateRequested = (Action<Invention>)Delegate.Combine(makerPen4.InventionUpdateRequested, new Action<Invention>(OnMakerPenMenuInventionUpdateRequested));
			MakerPen makerPen5 = MakerPen;
			makerPen5.InventionObjectsSelectionStarted = (Action)Delegate.Combine(makerPen5.InventionObjectsSelectionStarted, new Action(OnMakerPenMenuInventionObjectsSelectionStarted));
			MakerPen makerPen6 = MakerPen;
			makerPen6.InventionObjectsSelectionCompleted = (Action)Delegate.Combine(makerPen6.InventionObjectsSelectionCompleted, new Action(OnMakerPenMenuInventionObjectsSelectionCompleted));
			MakerPen makerPen7 = MakerPen;
			makerPen7.InventionObjectsSelectionCancelled = (Action)Delegate.Combine(makerPen7.InventionObjectsSelectionCancelled, new Action(OnMakerPenMenuInventionObjectsSelectionCancelled));
			MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			MakerPen makerPen8 = MakerPen;
			makerPen8.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Combine(makerPen8.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			OnMakerPenModeChanged(makerPen.CurrentToolMode, makerPen.CurrentTargetMode);
			MakerPen.Tool.MenuProjector.GazeOpenSupported = false;
			MakerPen.Tool.MenuProjector.AuthorityDetachMenuFromTool();
			MakerPen.MoveablePaletteMenu.Tool.MenuProjector.GazeOpenSupported = false;
			MakerPen.MoveablePaletteMenu.Tool.MenuProjector.AuthorityDetachMenuFromTool();
			MakerPen.MoveablePaletteMenu.EnableHandles(enabled: false);
			stateMachine.EnterState(1);
			currentPenMode = MakerPen.TargetMode.Invalid;
			currentToolMode = MakerPen.ToolMode.Invalid;
		}

		public void OnExitMode()
		{
			while (!MakerPen.PenToolStackIsEmpty)
			{
				MakerPen.AuthorityPopPenTool();
			}
			currentPenMode = MakerPen.TargetMode.Invalid;
			currentToolMode = MakerPen.ToolMode.Invalid;
			SetActiveCreationOperation(null, MakerPen.ToolModeChangeReason.Default);
			if (MakerPen != null)
			{
				MakerPen makerPen = MakerPen;
				makerPen.ConfigurationMenuRequested = (Action<IConfigurable>)Delegate.Remove(makerPen.ConfigurationMenuRequested, new Action<IConfigurable>(OnMakerPenMenuConfigurationFlowRequested));
				MakerPen makerPen2 = MakerPen;
				makerPen2.InventionDetailsRequested = (Action<Invention>)Delegate.Remove(makerPen2.InventionDetailsRequested, new Action<Invention>(OnMakerPenMenuInventionDetailsFlowRequested));
				MakerPen makerPen3 = MakerPen;
				makerPen3.InventionUpdateRequested = (Action<Invention>)Delegate.Remove(makerPen3.InventionUpdateRequested, new Action<Invention>(OnMakerPenMenuInventionUpdateRequested));
				MakerPen makerPen4 = MakerPen;
				makerPen4.InventionObjectsSelectionStarted = (Action)Delegate.Remove(makerPen4.InventionObjectsSelectionStarted, new Action(OnMakerPenMenuInventionObjectsSelectionStarted));
				MakerPen makerPen5 = MakerPen;
				makerPen5.InventionObjectsSelectionCompleted = (Action)Delegate.Remove(makerPen5.InventionObjectsSelectionCompleted, new Action(OnMakerPenMenuInventionObjectsSelectionCompleted));
				MakerPen makerPen6 = MakerPen;
				makerPen6.InventionObjectsSelectionCancelled = (Action)Delegate.Remove(makerPen6.InventionObjectsSelectionCancelled, new Action(OnMakerPenMenuInventionObjectsSelectionCancelled));
				MakerPen makerPen7 = MakerPen;
				makerPen7.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Remove(makerPen7.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
				MakerPen.Tool.MenuProjector.GazeOpenSupported = true;
				MakerPen.Tool.MenuProjector.AuthorityAttachMenuToTool();
				MakerPen.MoveablePaletteMenu.Tool.MenuProjector.GazeOpenSupported = true;
				MakerPen.MoveablePaletteMenu.Tool.MenuProjector.AuthorityAttachMenuToTool();
			}
			if (CreationContext != null)
			{
				CreationContext.ShapeCreationContext.DeselectShapeContainer();
				CreationContext.RemoveAllFromSelection();
			}
			stateMachine.EnterState(0);
			hud.WorldSpaceUIAnchor.Detach();
			if (player != null)
			{
				player.PlayerLocomotion.RemoveMovementRestriction(this);
			}
			DisableHudDialogContent();
			playerController.RemoveCameraController(this);
			playerController.RemoveSteeringController(this);
			playerController.RemoveCrouchRestriction(this);
			playerController.RemoveMenuOpeningRestriction(this);
			playerController.QuickCommsController.RemoveRestriction(this);
			playerController = null;
			player = null;
			hud = null;
			MakerPen = null;
			Camera = null;
			menuOpenRequested = false;
			requestedMenuSubState = MenuInteractionSubState.INVALID;
			_movementStateBeforeMenuOpen = ControlState.INVALID;
		}

		public bool OnUpdate()
		{
			ClearHudToolDialogs();
			ClearHudControlsDialogs();
			AddCommonControlsDialogs();
			stateMachine.Update();
			UpdateHudToolDialogs();
			UpdateHudControlsDialogs();
			return !UpdateExitButtonHold();
		}

		public void SnapCursorToViewportPosition(Vector2 viewportPosition)
		{
			playerController.CursorSystem.SnapCursorToViewportPosition(hud, viewportPosition);
			lastCursorPosition = playerController.CursorSystem.PositionViewportSpace;
		}

		public void SnapCursorToCenterOfScreen()
		{
			playerController.CursorSystem.SnapToCenter(hud);
			lastCursorPosition = playerController.CursorSystem.PositionViewportSpace;
		}

		public void RestrictCursorVisibility(object token)
		{
			cursorHiddenFlag.Add(token);
			UpdateCursorVisibility();
		}

		public void RestoreCursorVisibility(object token)
		{
			cursorHiddenFlag.Remove(token);
			UpdateCursorVisibility();
		}

		private void UpdateCursorVisibility()
		{
			if (cursorHiddenFlag.HasTokens)
			{
				playerController.CursorSystem.HideCursor(hud);
			}
			else
			{
				playerController.CursorSystem.ShowCursor(hud);
			}
		}

		private void OnMakerPenMenuToolSelected(MakerPen.ToolMode selectedToolType)
		{
			MakerPen.TargetMode desiredTarget = MakerPen.CurrentTargetMode;
			if (MakerPen.IsCreationToolMode(selectedToolType))
			{
				switch (selectedToolType)
				{
				case MakerPen.ToolMode.CreateShape:
					desiredTarget = MakerPen.TargetMode.Shape;
					break;
				case MakerPen.ToolMode.CreateObject:
					desiredTarget = MakerPen.TargetMode.Object;
					break;
				}
				if ((selectedToolType == MakerPen.ToolMode.CreateShape && MakerPen.CurrentShapeType == ShapeType.Invalid) || (selectedToolType == MakerPen.ToolMode.CreateObject && MakerPen.SelectedSpawnableToolType == SpawnableToolType.INVALID))
				{
					OnPaletteMenuOpenRequest();
					return;
				}
			}
			MakerPen.AuthoritySelectMode(selectedToolType, desiredTarget);
			EnterMovementStateBeforeMenuOpen();
		}

