		private void OnMakerPenModeChanged(MakerPen.ToolMode toolMode, MakerPen.TargetMode targetMode)
		{
			MakerPen.TargetMode targetMode2 = currentPenMode;
			MakerPen.ToolMode toolMode2 = currentToolMode;
			currentPenMode = MakerPen.CurrentTargetMode;
			currentToolMode = MakerPen.CurrentToolMode;
			if (currentPenMode == targetMode2 && currentToolMode == toolMode2)
			{
				return;
			}
			if (currentPenMode != targetMode2)
			{
				switch (targetMode2)
				{
				case MakerPen.TargetMode.Object:
				{
					ShapeContainer shapeContainer = null;
					if (CreationContext.ShapeCreationContext.HasSelectedShapeContainer)
					{
						shapeContainer = CreationContext.ShapeCreationContext.SelectedShapeContainer;
					}
					CreationContext.RemoveAllFromSelection();
					CreationContext.ShapeCreationContext.TrySelectShapeContainer(shapeContainer);
					break;
				}
				case MakerPen.TargetMode.Shape:
					CreationContext.ShapeCreationContext.DeselectShapeContainer();
					break;
				}
			}
			Dictionary<MakerPen.ToolMode, ScreenCreationOperationController> dictionary = ((currentPenMode != MakerPen.TargetMode.Object) ? shapeModeOperations : objectModeOperations);
			ScreenCreationOperationController value = null;
			dictionary.TryGetValue(currentToolMode, out value);
			if (value == null)
			{
				value = ((currentPenMode != MakerPen.TargetMode.Object) ? ((ScreenCreationOperationController)shapeMoveController) : ((ScreenCreationOperationController)objectMoveController));
			}
			SetActiveCreationOperation(value, MakerPen.ToolTypeChangeReason);
		}

		private void RegisterCreationOperation(MakerPen.TargetMode mode, MakerPen.ToolMode toolMode, ScreenCreationOperationController operationController)
		{
			operationController.Initialize(mode, toolMode);
			switch (mode)
			{
			case MakerPen.TargetMode.Object:
				objectModeOperations[toolMode] = operationController;
				break;
			case MakerPen.TargetMode.Shape:
				shapeModeOperations[toolMode] = operationController;
				break;
			}
		}

		private void UpdateActiveCreationOperation()
		{
			if (ActiveCreationOperation != null)
			{
				ActiveCreationOperation.OnUpdate(this);
				SetHudLabel(ActiveCreationOperation.HudLabel);
			}
			else
			{
				SetHudLabel(null);
			}
		}

		private void SetActiveCreationOperation(ScreenCreationOperationController operation, MakerPen.ToolModeChangeReason changeReason)
		{
			if (_activeOperationController == operation)
			{
				return;
			}
			if (_activeOperationController != null)
			{
				ScreenCreationOperationController.OperationTransitionType transitionType = ScreenCreationOperationController.OperationTransitionType.PERMANENT;
				if (changeReason == MakerPen.ToolModeChangeReason.StackPush)
				{
					transitionType = ScreenCreationOperationController.OperationTransitionType.PAUSE;
				}
				_activeOperationController.OnStop(transitionType, this);
			}
			_activeOperationController = operation;
			if (_activeOperationController != null)
			{
				ScreenCreationOperationController.OperationTransitionType transitionType2 = ScreenCreationOperationController.OperationTransitionType.PERMANENT;
				switch (changeReason)
				{
				case MakerPen.ToolModeChangeReason.StackPop:
					transitionType2 = ScreenCreationOperationController.OperationTransitionType.RESUME;
					break;
				case MakerPen.ToolModeChangeReason.StackPush:
					transitionType2 = ScreenCreationOperationController.OperationTransitionType.PUSHED_ON_STACK;
					break;
				}
				_activeOperationController.OnStart(transitionType2, this);
				EnableHudDialogContent();
				ClearHudToolDialogs();
			}
			else
			{
				DisableHudDialogContent();
			}
		}

