		private MenuInteractionSubState GetDesiredMenuSubState()
		{
			if (stateMachine.CurrentStateId == 4)
			{
				return MenuInteractionSubState.INVALID;
			}
			if (IsPaletteMenuDesired())
			{
				return MenuInteractionSubState.PALETTE_MENU;
			}
			if (IsMainMenuDesired())
			{
				return MenuInteractionSubState.MAIN_MENU;
			}
			return MenuInteractionSubState.INVALID;
		}

		private bool IsPaletteMenuDesired()
		{
			if (MakerPen == null)
			{
				return false;
			}
			if (MakerPen.MoveablePaletteMenu.IsMenuVisible)
			{
				return true;
			}
			AddHudControlsDialog(Input.MenuButtonSprite, "Open Palette", 101);
			if (Input.MenuButtonDown)
			{
				return true;
			}
			return false;
		}

		private bool IsMainMenuDesired()
		{
			if (MakerPen == null)
			{
				return false;
			}
			if (MakerPen.Tool.MenuProjector.IsMenuVisible)
			{
				return true;
			}
			AddHudControlsDialog(Input.FavoriteToolSprite, "Open Menu", 100);
			if (Input.FavoriteToolButtonDown)
			{
				return true;
			}
			return false;
		}

		private bool UpdateMenuInput()
		{
			Ray ray = playerController.CursorSystem.GetRay(Camera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, 0f, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, Input.CursorButtonDown, Input.CursorButtonUp);
			return result.UISelectable;
		}

