		private void InitializeCameraPosition(out Vector3 initialCameraPosition, out Quaternion initialCameraRotation)
		{
			float num = 0.25f;
			Vector3 desiredCameraPosition = player.TrackingSpace.transform.TransformPoint(playerSpaceCameraTargetOffset);
			Vector3 playerHeadPosition = playerController.GetPlayerHeadPosition(player);
			desiredCameraPosition = CollisionDetection.RunOrbitCameraCollision(playerHeadPosition, desiredCameraPosition, num, num);
			Transform playerTransform = playerController.GetPlayerTransform(player);
			Vector3 desiredCameraPosition2 = playerTransform.TransformPoint(playerSpaceCameraOffset);
			initialCameraRotation = Quaternion.LookRotation(desiredCameraPosition - (initialCameraPosition = CollisionDetection.RunOrbitCameraCollision(desiredCameraPosition, desiredCameraPosition2, num, num)));
		}

		private void UpdateCursorPosition(bool isOverTarget)
		{
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (Input.UsingKeyboardMouse)
			{
				playerController.CursorSystem.SetCursorScreenPosition(hud, Camera, gameViewFocused, Input.CursorMouseScreenPosition);
			}
			else
			{
				playerController.CursorSystem.AccelerateCursor(hud, Input.CursorAxis, gameViewFocused, isOverTarget);
			}
			lastCursorPosition = playerController.CursorSystem.PositionViewportSpace;
		}

		private Vector2 GetCursorViewportPosition()
		{
			Vector2 result = new Vector2(0.5f, 0.5f);
			if (stateMachine.CurrentStateId == 3 || stateMachine.CurrentStateId == 4)
			{
				return hud.CursorViewportPosition;
			}
			return result;
		}

		private bool UpdateExitButtonHold()
		{
			bool flag = stateMachine.CurrentStateId == 4;
			if (!isAttemptingToExit && Input.CancelButtonDown && !flag)
			{
				isAttemptingToExit = true;
				exitAttemptStartTime = UnityEngine.Time.time;
			}
			if (!isAttemptingToExit)
			{
				return false;
			}
			float num = Mathf.InverseLerp(exitAttemptStartTime, exitAttemptStartTime + exitButtonHoldDuration, UnityEngine.Time.time);
			hud.EnableInteractDialog(exitTooltipViewportPosition, Input.CancelButtonSprite, "Exit Maker Pen", num);
			if (!Input.CancelButtonPressed || Input.CancelButtonUp)
			{
				isAttemptingToExit = false;
				return false;
			}
			return num >= 1f;
		}

