		}

		protected enum LocalRotationAxis
		{
			X,
			Y,
			Z
		}

		protected enum MeshShapeCreationConstraint
		{
			NONE,
			PROJECT_ON_PLANE,
			PROJECT_ON_PLANE_NORMAL_VECTOR
		}

		protected delegate bool CastFilter<T>(T potentialSelection);

		protected const int HUD_DIALOG_HIGHEST_PRIORITY = 100;

