		protected const float CURVE_SHAPE_MIN_DIST_BETWEEN_CONTROL_POINTS = 0.01f;

		protected const float CURVE_SHAPE_MIN_DIST_BETWEEN_CONTROL_POINTS_SQR = 0.0001f;

		protected const float MAX_CURVE_SHAPE_RADIUS = 0.033f;

