		public void PushAsActiveOperation(ScreenCreationController controller)
		{
			if (controller.MakerPen.CurrentTargetMode != targetMode)
			{
				UnityEngine.Debug.LogError($"Trying to push {this} as active MakerPen tool, but the MakerPen is in invalid target mode {controller.MakerPen.CurrentTargetMode}");
			}
			else
