		protected int SpherecastPickConnectionPoints(ScreenCreationController creationController, out Vector3 closestHitPoint)
		{
			Vector2 cursorViewportPosition = creationController.CursorViewportPosition;
			Ray ray = creationController.Camera.ViewportPointToRay(cursorViewportPosition);
			return creationController.CreationContext.ConnectionCreationContext.SpherecastPickConnectionPoints(ray.origin, 0.025f, ray.direction, float.MaxValue, CONNECTION_RAYCAST_RESULTS, out closestHitPoint);
		}

		protected int SpherecastPick<T>(ScreenCreationController creationController, ISelectionContext<T> context, T[] castResults, out Vector3 lastClosestHitPoint, out Collider lastColliderHit)
		{
			Vector2 cursorViewportPosition = creationController.CursorViewportPosition;
			Ray ray = creationController.Camera.ViewportPointToRay(cursorViewportPosition);
			return context.SpherecastPick(ray.origin, 0.025f, ray.direction, float.MaxValue, castResults, out lastClosestHitPoint, out lastColliderHit);
		}

		protected bool TryStartObjectOperationOnSelection(ScreenCreationController creationController, string dialogText, out bool addedToSelection, CastFilter<CreationObject> highlightFilter = null)
		{
			return TryStartOperationOnSelection(creationController, creationController.CreationContext, dialogText, OBJECT_RAYCAST_RESULTS, out OBJECT_RAYCAST_LAST_COLLIDER_HIT, out addedToSelection, highlightFilter);
		}

		protected bool TryStartShapeOperationOnSelection(ScreenCreationController creationController, string dialogText, out bool addedToSelection, CastFilter<Guid> highlightFilter = null)
		{
			return TryStartOperationOnSelection(creationController, creationController.CreationContext.ShapeCreationContext, dialogText, SHAPE_RAYCAST_RESULTS, out SHAPE_RAYCAST_LAST_COLLIDER_HIT, out addedToSelection, highlightFilter);
		}

		protected bool TryStartOperationOnSelection<T>(ScreenCreationController creationController, ISelectionContext<T> context, string dialogText, T[] pickingResults, out bool addedToSelection, CastFilter<T> highlightFilter = null)
		{
			Collider colliderHit;
			return TryStartOperationOnSelection(creationController, context, dialogText, pickingResults, out colliderHit, out addedToSelection, highlightFilter);
		}

		protected bool TryStartOperationOnSelection<T>(ScreenCreationController creationController, ISelectionContext<T> context, string dialogText, T[] pickingResults, out Collider colliderHit, out bool addedToSelection, CastFilter<T> highlightFilter = null)
		{
			addedToSelection = false;
			colliderHit = null;
			if (creationController.Input.UsingKeyboardMouse && !creationController.InCursorMovementMode)
			{
				return false;
			}
			if (!creationController.Input.UsingKeyboardMouse || creationController.InCursorMovementMode)
			{
				creationController.AddHudToolDialog(GetMultiSelectInputIcon(creationController), "Multi Select", 51);
				if (IsMultiSelectInputPressed(creationController))
				{
					creationController.MakerPen.AuthorityPushPenTool(MakerPen.ToolMode.Select);
					return false;
				}
			}
			if (TryUpdateKeyboardMouseToolShortcuts(creationController))
			{
				return false;
			}
			bool flag = IsSelectInputDown(creationController);
			Vector3 lastClosestHitPoint;
			int num = SpherecastPick(creationController, context, pickingResults, out lastClosestHitPoint, out colliderHit);
			if (num == 0)
			{
				if (flag)
				{
					context.RemoveAllFromSelection();
				}
				return false;
			}
			if (dialogText != null)
			{
				creationController.AddHudToolDialog(GetSelectInputIcon(creationController), dialogText, 100);
			}
			T val = pickingResults[0];
			if (highlightFilter != null && !highlightFilter(val))
			{
				return false;
			}
			if (context.IsSelected(val))
			{
				context.RenderHoverHighlight(context.SelectionCount, context.CurrentSelection);
			}
			else
			{
				context.RenderHoverHighlight(num, pickingResults);
				if (flag)
				{
					context.RemoveAllFromSelection();
					context.AddToSelection(num, pickingResults);
					addedToSelection = true;
				}
			}
			return flag;
		}

		protected bool TryUpdateKeyboardMouseToolShortcuts(ScreenCreationController creationController)
		{
			if (creationController.Input.UsingKeyboardMouse && creationController.InCursorMovementMode)
			{
				MakerPen.TargetMode currentTargetMode = creationController.MakerPen.CurrentTargetMode;
				if (creationController.MakerPen.CurrentToolMode != MakerPen.ToolMode.Move)
				{
					creationController.AddHudToolDialog(GetMoveInputIcon(creationController), "Move", 50);
					if (IsMoveInputDown(creationController))
					{
						creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, currentTargetMode);
						return true;
					}
				}
				if (creationController.MakerPen.CurrentToolMode != MakerPen.ToolMode.Rotate)
				{
					creationController.AddHudToolDialog(GetRotateInputIcon(creationController), "Rotate", 50);
					if (IsRotateInputDown(creationController))
					{
						creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Rotate, currentTargetMode);
						return true;
					}
				}
				if (creationController.MakerPen.CurrentToolMode != MakerPen.ToolMode.Scale)
				{
					creationController.AddHudToolDialog(GetScaleInputIcon(creationController), "Scale", 50);
					if (IsScaleInputDown(creationController))
					{
						creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Scale, currentTargetMode);
						return true;
					}
				}
			}
			return false;
		}

		protected Vector3 GetCursorModeTranslationDisplacement(ScreenCreationController creationController, float translationSpeed)
		{
			Vector3 up = Vector3.up;
			Vector3 normalized = Vector3.Cross(up, creationController.Camera.transform.forward).normalized;
			Vector3 up2 = Vector3.up;
			Vector2 walkAxis = creationController.Input.WalkAxis;
			Vector3 vector = walkAxis.x * normalized + walkAxis.y * up2;
			return vector * translationSpeed * UnityEngine.Time.deltaTime;
		}

		protected void GetSelectionClosestRotationAxis<T>(ISelectionContext<T> context, Vector3 desiredAxisDirection, out LocalRotationAxis axisType, out float axisSign)
		{
			Quaternion rotation = context.SelectionTransform.rotation;
			Vector3 lhs = rotation * Vector3.right;
			float f = Vector3.Dot(lhs, desiredAxisDirection);
			float num = Mathf.Abs(f);
			Vector3 lhs2 = rotation * Vector3.up;
			float f2 = Vector3.Dot(lhs2, desiredAxisDirection);
			float num2 = Mathf.Abs(f2);
			Vector3 lhs3 = rotation * Vector3.forward;
			float f3 = Vector3.Dot(lhs3, desiredAxisDirection);
			float num3 = Mathf.Abs(f3);
			if (num >= num2 && num >= num3)
			{
				axisType = LocalRotationAxis.X;
				axisSign = Mathf.Sign(f);
			}
			else if (num2 >= num && num2 >= num3)
			{
				axisType = LocalRotationAxis.Y;
				axisSign = Mathf.Sign(f2);
			}
			else
			{
				axisType = LocalRotationAxis.Z;
				axisSign = Mathf.Sign(f3);
			}
		}

		protected Vector3 GetSelectionRotationAxisVector(LocalRotationAxis axisType, float axisSign)
		{
			Vector3 zero = Vector3.zero;
			return axisType switch
			{
				LocalRotationAxis.X => Vector3.right, 
				LocalRotationAxis.Y => Vector3.up, 
				_ => Vector3.forward, 
			} * axisSign;
		}

