		protected bool UpdateSelectedMeshShapeSizeAndPosition(ScreenCreationController creationController, Vector3 initialShapePosition, Vector3 initialInputPosition, bool isUniformSize, MeshShapeCreationConstraint constraint, Vector3 constraintPlaneNormal, bool mustBroadcastChanges, float lastSynchronizeTime)
		{
			Vector3 size = Vector3.one;
			creationController.CreationContext.ShapeCreationContext.TryGetSelectedMeshShapeAspectRatio(out size);
			Vector3 zero = Vector3.zero;
			Vector3 vector = constraint switch
			{
				MeshShapeCreationConstraint.PROJECT_ON_PLANE => GetDesiredShapeCreationPositionInPlane(creationController, initialInputPosition, constraintPlaneNormal), 
				MeshShapeCreationConstraint.PROJECT_ON_PLANE_NORMAL_VECTOR => GetDesiredShapeCreationPositionInPlane(creationController, initialInputPosition, creationController.Camera.transform.forward), 
				_ => GetDesiredShapeCreationPosition(creationController), 
			} - initialInputPosition;
			switch (constraint)
			{
			case MeshShapeCreationConstraint.PROJECT_ON_PLANE:
				if (isUniformSize)
				{
					vector = GetUniformSize(vector);
				}
				vector = ProjectOnPlane(vector, size, constraintPlaneNormal);
				break;
			case MeshShapeCreationConstraint.PROJECT_ON_PLANE_NORMAL_VECTOR:
				if (isUniformSize)
				{
					vector = GetUniformSize(Vector3.ProjectOnPlane(size, constraintPlaneNormal));
				}
				vector = ProjectOnPlaneNormalVector(vector, size, constraintPlaneNormal);
				break;
			default:
				if (isUniformSize)
				{
					vector = GetUniformSize(vector);
				}
				break;
			}
			creationController.CreationContext.ShapeCreationContext.TryGetSelectedMeshShapePosition(out var position);
			GetMeshShapeSizeDisplacement(vector, out var clampedSizeAbs, out var displacement);
			Vector3 vector2 = initialShapePosition + displacement;
			switch (constraint)
			{
			case MeshShapeCreationConstraint.PROJECT_ON_PLANE:
				vector2 = ProjectOnPlane(vector2, position, constraintPlaneNormal);
				break;
			case MeshShapeCreationConstraint.PROJECT_ON_PLANE_NORMAL_VECTOR:
				vector2 = ProjectOnPlaneNormalVector(vector2, position, constraintPlaneNormal);
				break;
			}
			Vector3 linearDisplacement = vector2 - position;
			bool flag = mustBroadcastChanges || UnityEngine.Time.unscaledTime - lastSynchronizeTime >= 0.1f;
			creationController.CreationContext.ShapeCreationContext.UpdateSelectedMeshShapeAspectRatio(clampedSizeAbs, flag);
			creationController.CreationContext.ShapeCreationContext.TranslateSelection(linearDisplacement);
			return flag;
		}

		protected Vector3 GetDesiredShapeCreationPosition(ScreenCreationController creationController)
		{
			Vector2 cursorViewportPosition = creationController.CursorViewportPosition;
			Ray ray = creationController.Camera.ViewportPointToRay(cursorViewportPosition);
			Vector3 vector = ray.origin + ray.direction * 3f;
			if (creationController.MakerPen.Snapping.IsActive)
			{
				vector = creationController.MakerPen.Snapping.SnapToCorner(vector);
			}
			return vector;
		}

		protected Vector3 GetDesiredShapeCreationPositionInPlane(ScreenCreationController creationController, Vector3 planeOrigin, Vector3 planeNormal)
		{
			Ray ray = creationController.Camera.ViewportPointToRay(creationController.CursorViewportPosition);
			Plane plane = new Plane(planeNormal, planeOrigin);
			float enter = 0f;
			if (!plane.Raycast(ray, out enter))
			{
				return GetDesiredShapeCreationPosition(creationController);
			}
			Vector3 vector = ray.GetPoint(enter);
			if (creationController.MakerPen.Snapping.IsActive)
			{
				vector = creationController.MakerPen.Snapping.SnapToCorner(vector);
			}
			return vector;
		}

		private Vector3 ProjectOnPlane(Vector3 desiredVector, Vector3 currentVector, Vector3 planeNormal)
		{
			desiredVector = Vector3.ProjectOnPlane(desiredVector, planeNormal);
			currentVector = Vector3.Project(currentVector, planeNormal);
			return desiredVector + currentVector;
		}

		private Vector3 ProjectOnPlaneNormalVector(Vector3 desiredVector, Vector3 currentVector, Vector3 planeNormal)
		{
			desiredVector = Vector3.Project(desiredVector, planeNormal);
			currentVector = Vector3.ProjectOnPlane(currentVector, planeNormal);
			return desiredVector + currentVector;
		}

		private void GetMeshShapeSizeDisplacement(Vector3 desiredSize, out Vector3 clampedSizeAbs, out Vector3 displacement)
		{
			Vector3 vector = new Vector3(Mathf.Abs(desiredSize.x), Mathf.Abs(desiredSize.y), Mathf.Abs(desiredSize.z));
			Vector3 vector2 = new Vector3(Mathf.Sign(desiredSize.x), Mathf.Sign(desiredSize.y), Mathf.Sign(desiredSize.z));
			clampedSizeAbs = new Vector3(Mathf.Max(0.01f, vector.x), Mathf.Max(0.01f, vector.y), Mathf.Max(0.01f, vector.z));
			Vector3 vector3 = new Vector3(vector2.x * clampedSizeAbs.x, vector2.y * clampedSizeAbs.y, vector2.z * clampedSizeAbs.z);
			displacement = new Vector3((!(vector3.x < 0f)) ? 0f : vector3.x, (!(vector3.y < 0f)) ? 0f : vector3.y, (!(vector3.z < 0f)) ? 0f : vector3.z);
		}

		private Vector3 GetUniformSize(Vector3 desiredSize)
		{
			Vector3 vector = new Vector3(Mathf.Abs(desiredSize.x), Mathf.Abs(desiredSize.y), Mathf.Abs(desiredSize.z));
			Vector3 vector2 = new Vector3(Mathf.Sign(desiredSize.x), Mathf.Sign(desiredSize.y), Mathf.Sign(desiredSize.z));
			return vector2 * Mathf.Max(vector.x, vector.y, vector.z);
		}

		protected void UpdateShapeConstraintSetting(ScreenCreationController creationController)
		{
			switch (creationController.MakerPen.CurrentConstraintMode)
			{
			case MakerPen.ConstraintMode.Free:
				creationController.AddHudToolDialog(GetMultiSelectInputIcon(creationController), "Uniform", 55);
				if (IsMultiSelectInputPressed(creationController))
				{
					creationController.MakerPen.SelectConstraintMode(MakerPen.ConstraintMode.Constrained);
				}
				break;
			case MakerPen.ConstraintMode.Constrained:
				creationController.AddHudToolDialog(GetMultiSelectInputIcon(creationController), "Non Uniform", 55);
				if (!IsMultiSelectInputPressed(creationController))
				{
					creationController.MakerPen.SelectConstraintMode(MakerPen.ConstraintMode.Free);
				}
				break;
			}
		}
	}
}
namespace RecRoom.Core.Creation.Screens.ShapeOperations
{
	[Serializable]
	public class CreateTriggerShapeScreenCreationController : ScreenCreationOperationController
	{
		private enum CreationState
		{
			INVALID,
			CREATING_XZ_PLANE,
			WAITING_TO_CREATE_Y,
			CREATING_Y
		}

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private float lastMeshShapeSizeSynchronizeTime;

		[NonSerialized]
		private Vector3 lastMeshShapeCreationInitialShapePosition = Vector3.zero;

		[NonSerialized]
		private Vector3 lastMeshShapeHeightResizeInitialShapePosition = Vector3.zero;

		[NonSerialized]
		private Vector3 lastMeshShapeHeightResizeInitialInputPosition = Vector3.zero;

		[NonSerialized]
		private ScreenCreationController cachedCreationController;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Create Trigger Mode";
			}
		}

		public CreateTriggerShapeScreenCreationController()
		{
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterMeshShapeCreatingXZPlaneState, OnExitMeshShapeCreatingXZPlaneState, OnUpdateMeshShapeCreatingXZPlaneState);
			stateMachine.AddState(2, null, null, OnUpdateMeshShapeWaitingForYSubState);
			stateMachine.AddState(3, OnEnterMeshShapeCreatingYState, OnExitMeshShapeCreatingYState, OnUpdateMeshShapeCreatingYState);
			stateMachine.EnterState(0);
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.RESUME)
			{
				creationController.CreationContext.ShapeCreationContext.DeselectShapeContainer();
				creationController.CreationContext.ShapeCreationContext.CreateAndSelectShapeContainer(SpawnableToolType.TRIGGER_VOLUME);
				StartMeshShape(creationController);
				cachedCreationController = creationController;
				stateMachine.EnterState(1);
			}
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			stateMachine.Update();
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Finish Creation", 20);
			UpdateShapeConstraintSetting(creationController);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			FinishMeshShape(creationController);
			if (transitionType != OperationTransitionType.PAUSE)
			{
				stateMachine.EnterState(0);
				cachedCreationController = null;
			}
		}

		private void OnEnterMeshShapeCreatingXZPlaneState(ushort previousStateId, ushort previousSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeCreatingXZPlaneState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), "Finish Trigger Base", 100);
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: false);
			if (!IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(2);
			}
		}

		private void OnExitMeshShapeCreatingXZPlaneState(ushort nextStateId, ushort nextSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeWaitingForYSubState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), "Draw Trigger Height", 100);
			if (IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(3);
			}
		}

		private void OnEnterMeshShapeCreatingYState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedCreationController.CreationContext.ShapeCreationContext.TryGetSelectedMeshShapePosition(out lastMeshShapeHeightResizeInitialShapePosition);
			lastMeshShapeHeightResizeInitialInputPosition = GetDesiredShapeCreationPositionInPlane(cachedCreationController, lastMeshShapeCreationInitialShapePosition, Vector3.up);
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeCreatingYState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), "Finish Trigger Height", 100);
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: false);
			if (!IsShapeCreateInputPressed(cachedCreationController))
			{
				cachedCreationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateTrigger, MakerPen.TargetMode.Object);
			}
		}

		private void OnExitMeshShapeCreatingYState(ushort nextStateId, ushort nextSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: true);
		}

		private void StartMeshShape(ScreenCreationController creationController)
		{
			ShapeType type = ShapeType.TriggerVolumeBox;
			ShapeColor selectedColor = creationController.MakerPen.SelectedColor;
			lastMeshShapeCreationInitialShapePosition = GetDesiredShapeCreationPosition(creationController);
			ShapeCreationContext.ShapeCreationResult shapeCreationResult = creationController.CreationContext.ShapeCreationContext.TryCreateAndSelectMeshShapeInSelectedShapeContainer(type, selectedColor, lastMeshShapeCreationInitialShapePosition, Quaternion.identity, Vector3.one * 0.01f);
			if (shapeCreationResult.result != CreationResult.Success)
			{
				creationController.MakerPen.RaiseInvalidActionPerformed(shapeCreationResult.result, "Creation failed", null);
			}
		}

		private void FinishMeshShape(ScreenCreationController creationController)
		{
			creationController.MakerPen.UndoStack.Add(new CreateObjectsUndoEntry("create", creationController.CreationContext.CurrentSelection, creationController.CreationContext));
			creationController.CreationContext.ShapeCreationContext.DeselectShapeContainer();
		}

		protected void UpdateSelectedMeshShapeSizeAndPositionPlane(ScreenCreationController creationController, bool mustBroadcastChanges)
		{
			if (UpdateSelectedMeshShapeSizeAndPosition(creationController, lastMeshShapeCreationInitialShapePosition, lastMeshShapeCreationInitialShapePosition, creationController.MakerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained, MeshShapeCreationConstraint.PROJECT_ON_PLANE, Vector3.up, mustBroadcastChanges, lastMeshShapeSizeSynchronizeTime))
			{
				lastMeshShapeSizeSynchronizeTime = UnityEngine.Time.unscaledTime;
			}
		}

		protected void UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(ScreenCreationController creationController, bool mustBroadcastChanges)
		{
			if (UpdateSelectedMeshShapeSizeAndPosition(creationController, lastMeshShapeHeightResizeInitialShapePosition, lastMeshShapeHeightResizeInitialInputPosition, creationController.MakerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained, MeshShapeCreationConstraint.PROJECT_ON_PLANE_NORMAL_VECTOR, Vector3.up, mustBroadcastChanges, lastMeshShapeSizeSynchronizeTime))
			{
				lastMeshShapeSizeSynchronizeTime = UnityEngine.Time.unscaledTime;
			}
		}
	}
	[Serializable]
	public class ShapeCloneScreenCreationController : ScreenCreationOperationController
	{
		[NonSerialized]
		private bool isTransient;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Clone Shapes Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.RESUME)
			{
				isTransient = transitionType == OperationTransitionType.PUSHED_ON_STACK;
			}
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			if (isTransient)
			{
				if (!IsCloneInputPressed(creationController))
				{
					creationController.MakerPen.AuthorityPopPenTool();
					return;
				}
				if (creationController.CreationContext.ShapeCreationContext.HasSelection && !creationController.Input.UsingKeyboardMouse)
				{
					creationController.CreationContext.ShapeCreationContext.TryCloneSelectedShapes();
					creationController.MakerPen.AuthorityPopPenTool();
				}
			}
			else
			{
				creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
				if (IsCancelInputDown(creationController))
				{
					creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Shape);
					return;
				}
			}
			if (TryStartShapeOperationOnSelection(creationController, "Clone", out var _))
			{
				ShapeCreationContext shapeCreationContext = creationController.CreationContext.ShapeCreationContext;
				if (shapeCreationContext.TryCloneSelectedShapes() == CreationResult.Success)
				{
					CloneShapesUndoEntry pendingUndoEntry = new CloneShapesUndoEntry(shapeCreationContext.SelectedShapeContainer, shapeCreationContext.CurrentSelection, creationController.CreationContext);
					creationController.ShapeMoveController.PushAsActiveOperation(creationController, pendingUndoEntry);
				}
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}
	}
	[Serializable]
	public class ShapeColorScreenCreationController : ScreenCreationOperationController
	{
		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Color Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Shape);
				return;
			}
			bool addedToSelection = false;
			if (TryStartShapeOperationOnSelection(creationController, "Recolor", out addedToSelection))
			{
				ShapeColor selectedColor = creationController.MakerPen.SelectedColor;
				ShapeCreationContext shapeCreationContext = creationController.CreationContext.ShapeCreationContext;
				creationController.MakerPen.UndoStack.Add(new RecolorShapesInstantUndoEntry(shapeCreationContext.SelectedShapeContainer, shapeCreationContext.CurrentSelection, creationController.CreationContext, selectedColor));
				shapeCreationContext.RecolorSelectedShapes(selectedColor);
				if (addedToSelection)
				{
					shapeCreationContext.RemoveAllFromSelection();
				}
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
		}
	}
	[Serializable]
	public class ShapeConfigureScreenCreationController : ScreenCreationOperationController
	{
		[NonSerialized]
		private bool selectionCreatedOnOperationStart;

		[NonSerialized]
		private bool hasOpenedConfigMenu;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return "Configure Mode";
			}
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			hasOpenedConfigMenu = false;
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Cancel", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Shape);
			}
			else if (!hasOpenedConfigMenu)
			{
				if (TryStartShapeOperationOnSelection(creationController, "Configure", out selectionCreatedOnOperationStart))
				{
					hasOpenedConfigMenu = true;
					creationController.MakerPen.RequestInteractableSettingsUI(creationController.CreationContext.ShapeCreationContext.SelectedShapeContainer.CreationObject);
				}
			}
			else if (!creationController.MakerPen.MoveablePaletteMenu.IsMenuVisible)
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Shape);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (selectionCreatedOnOperationStart)
			{
				creationController.CreationContext.ShapeCreationContext.RemoveAllFromSelection();
			}
		}
	}
	[Serializable]
	public class ShapeCreateScreenCreationController : ScreenCreationOperationController
	{
		private enum CreationState
		{
			INVALID,
			WAITING_TO_CREATE,
			CREATING_CURVE_SHAPE,
			CREATING_MESH_SHAPE
		}

		private enum MeshShapeCreationSubState
		{
			CREATING_XZ_PLANE,
			WAITING_TO_CREATE_Y,
			CREATING_Y
		}

		private static readonly string HUD_LABEL_FORMAT = "Create {0} Mode";

		private static readonly string DRAW_CURVE_SHAPE_LABEL_FORMAT = "Draw {0}";

		private static readonly string DRAW_MESH_SHAPE_BASE_LABEL_FORMAT = "Draw {0} Base";

		private static readonly string DRAW_MESH_SHAPE_HEIGHT_LABEL_FORMAT = "Draw {0} Height";

		private static readonly string FINISH_MESH_SHAPE_BASE_LABEL_FORMAT = "Finish {0} Base";

		private static readonly string FINISH_SHAPE_LABEL_FORMAT = "Finish {0}";

		[NonSerialized]
		private string hudLabel;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private float lastCurveShapeControlPointAddTime;

		[NonSerialized]
		private float lastMeshShapeSizeSynchronizeTime;

		[NonSerialized]
		private Vector3 lastMeshShapeCreationInitialShapePosition = Vector3.zero;

		[NonSerialized]
		private Vector3 lastMeshShapeHeightResizeInitialShapePosition = Vector3.zero;

		[NonSerialized]
		private Vector3 lastMeshShapeHeightResizeInitialInputPosition = Vector3.zero;

		[NonSerialized]
		private ScreenCreationController cachedCreationController;

		public override string HudLabel
		{
			[CompilerGenerated]
			get
			{
				return hudLabel;
			}
		}

		public ShapeCreateScreenCreationController()
		{
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterWaitingToCreateState, null, OnUpdateWaitingToCreateState);
			stateMachine.AddState(2, OnEnterCurveShapeCreationState, OnExitCurveShapeCreationState, OnUpdateCurveShapeCreationState);
			stateMachine.AddState(3, OnEnterMeshShapeCreationState, OnExitMeshShapeCreationState, OnUpdateMeshShapeCreationState);
			stateMachine.AddState(3, 0, OnEnterMeshShapeCreatingXZPlaneSubState, OnExitMeshShapeCreatingXZPlaneSubState, OnUpdateMeshShapeCreatingXZPlaneSubState);
			stateMachine.AddState(3, 1, null, null, OnUpdateMeshShapeWaitingForYSubState);
			stateMachine.AddState(3, 2, OnEnterMeshShapeCreatingYSubState, OnExitMeshShapeCreatingYSubState, OnUpdateMeshShapeCreatingYSubState);
			stateMachine.EnterState(0);
		}

		public override void OnStart(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			creationController.CreationContext.ShapeCreationContext.RemoveAllFromSelection();
			if (transitionType != OperationTransitionType.RESUME)
			{
				cachedCreationController = creationController;
				stateMachine.EnterState(1);
			}
		}

		public override void OnUpdate(ScreenCreationController creationController)
		{
			stateMachine.Update();
			creationController.AddHudToolDialog(GetCancelInputIcon(creationController), "Finish Creation", 20);
			if (IsCancelInputDown(creationController))
			{
				creationController.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Object);
			}
		}

		public override void OnStop(OperationTransitionType transitionType, ScreenCreationController creationController)
		{
			if (transitionType != OperationTransitionType.PAUSE)
			{
				stateMachine.EnterState(0);
				cachedCreationController = null;
			}
		}

		private void OnEnterWaitingToCreateState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!cachedCreationController.CreationContext.ShapeCreationContext.HasSelectedShapeContainer)
			{
				cachedCreationController.CreationContext.ShapeCreationContext.CreateAndSelectShapeContainer(SpawnableToolType.SHAPE_CONTAINER);
			}
		}

		private void OnUpdateWaitingToCreateState()
		{
			if (TryUpdateKeyboardMouseToolShortcuts(cachedCreationController))
			{
				return;
			}
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			string shapeName = ShapeSettings.GetShapeName(currentShapeType);
			hudLabel = string.Format(HUD_LABEL_FORMAT, shapeName);
			bool flag = IsCurveShape(currentShapeType);
			string format = ((!flag) ? DRAW_MESH_SHAPE_BASE_LABEL_FORMAT : DRAW_CURVE_SHAPE_LABEL_FORMAT);
			format = string.Format(format, shapeName);
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), format, 100);
			UpdateShapeConstraintSetting(cachedCreationController);
			if (IsShapeCreateInputPressed(cachedCreationController))
			{
				if (flag)
				{
					stateMachine.EnterState(2);
				}
				else
				{
					stateMachine.EnterState(3, 0);
				}
			}
		}

		private void OnEnterCurveShapeCreationState(ushort previousStateId, ushort previousSubStateId)
		{
			StartCurveShape(cachedCreationController);
		}

		private void OnUpdateCurveShapeCreationState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			string shapeName = ShapeSettings.GetShapeName(currentShapeType);
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), string.Format(FINISH_SHAPE_LABEL_FORMAT, shapeName), 100);
			UpdateShapeConstraintSetting(cachedCreationController);
			UpdateCurveShape(cachedCreationController);
			if (!IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnExitCurveShapeCreationState(ushort nextStateId, ushort nextSubStateId)
		{
			FinishCurveShape(cachedCreationController);
		}

		private void OnEnterMeshShapeCreationState(ushort previousStateId, ushort previousSubStateId)
		{
			StartMeshShape(cachedCreationController);
		}

		private void OnUpdateMeshShapeCreationState()
		{
			UpdateShapeConstraintSetting(cachedCreationController);
		}

		private void OnExitMeshShapeCreationState(ushort nextStateId, ushort nextSubStateId)
		{
			FinishMeshShape(cachedCreationController);
		}

		private void OnEnterMeshShapeCreatingXZPlaneSubState(ushort previousStateId, ushort previousSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeCreatingXZPlaneSubState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			string shapeName = ShapeSettings.GetShapeName(currentShapeType);
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), string.Format(FINISH_MESH_SHAPE_BASE_LABEL_FORMAT, shapeName), 100);
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: false);
			if (!IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(3, 1);
			}
		}

		private void OnExitMeshShapeCreatingXZPlaneSubState(ushort nextStateId, ushort nextSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlane(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeWaitingForYSubState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			string shapeName = ShapeSettings.GetShapeName(currentShapeType);
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), string.Format(DRAW_MESH_SHAPE_HEIGHT_LABEL_FORMAT, shapeName), 100);
			if (IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(3, 2);
			}
		}

		private void OnEnterMeshShapeCreatingYSubState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedCreationController.CreationContext.ShapeCreationContext.TryGetSelectedMeshShapePosition(out lastMeshShapeHeightResizeInitialShapePosition);
			lastMeshShapeHeightResizeInitialInputPosition = GetDesiredShapeCreationPositionInPlane(cachedCreationController, lastMeshShapeCreationInitialShapePosition, Vector3.up);
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: true);
		}

		private void OnUpdateMeshShapeCreatingYSubState()
		{
			ShapeType currentShapeType = cachedCreationController.MakerPen.CurrentShapeType;
			string shapeName = ShapeSettings.GetShapeName(currentShapeType);
			cachedCreationController.AddHudToolDialog(GetMainActionInputIcon(cachedCreationController), string.Format(FINISH_SHAPE_LABEL_FORMAT, shapeName), 100);
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: false);
			if (!IsShapeCreateInputPressed(cachedCreationController))
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnExitMeshShapeCreatingYSubState(ushort nextStateId, ushort nextSubStateId)
		{
			UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(cachedCreationController, mustBroadcastChanges: true);
		}

		private void FinishShapeCommon(ScreenCreationController creationController)
		{
			ShapeCreationContext shapeCreationContext = creationController.CreationContext.ShapeCreationContext;
			shapeCreationContext.CheckNotifyResourceLimits();
			foreach (Guid item in shapeCreationContext.CurrentSelection)
			{
				creationController.MakerPen.UndoStack.Add(new DrawShapeUndoEntry(shapeCreationContext.SelectedShapeContainer, item, creationController.CreationContext));
			}
			shapeCreationContext.RemoveAllFromSelection();
		}

		private bool IsCurveShape(ShapeType shapeType)
		{
			return shapeType == ShapeType.Ribbon || shapeType == ShapeType.Tube;
		}

		private void StartCurveShape(ScreenCreationController creationController)
		{
			ShapeType currentShapeType = creationController.MakerPen.CurrentShapeType;
			ShapeColor selectedColor = creationController.MakerPen.SelectedColor;
			GetDesiredCurveShapeControlPoint(creationController, out var position, out var _, out var radius);
			ShapeCreationContext.ShapeCreationResult shapeCreationResult = creationController.CreationContext.ShapeCreationContext.TryCreateAndSelectCurveShapeInSelectedShapeContainer(currentShapeType, selectedColor, position, Quaternion.identity, radius);
			if (shapeCreationResult.result == CreationResult.Success)
			{
				UpdateSelectedCurveShapeControlPoint(creationController, mustAddControlPoint: true);
				UpdateSelectedCurveShapeControlPoint(creationController, mustAddControlPoint: true);
			}
			else
			{
				creationController.MakerPen.RaiseInvalidActionPerformed(shapeCreationResult.result, "Creation failed", null);
			}
		}

		private void UpdateCurveShape(ScreenCreationController creationController)
		{
			if (creationController.MakerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained)
			{
				UpdateConstrainedCurveShapeControlPoint(creationController, mustBroadcastChanges: false);
			}
			else
			{
				UpdateSelectedCurveShapeControlPoint(creationController, mustAddControlPoint: false);
			}
		}

		private void FinishCurveShape(ScreenCreationController creationController)
		{
			if (creationController.MakerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained)
			{
				UpdateConstrainedCurveShapeControlPoint(creationController, mustBroadcastChanges: true);
			}
			else
			{
				UpdateSelectedCurveShapeControlPoint(creationController, mustAddControlPoint: true);
			}
			FinishShapeCommon(creationController);
		}

		private void UpdateConstrainedCurveShapeControlPoint(ScreenCreationController creationController, bool mustBroadcastChanges)
		{
			GetDesiredCurveShapeControlPoint(creationController, out var position, out var normal, out var radius);
			bool flag = UnityEngine.Time.unscaledTime - lastCurveShapeControlPointAddTime >= 0.1f;
			bool broadcastChangesOverNetwork = mustBroadcastChanges || flag;
			Vector3 controlPointPosition = Vector3.zero;
			if (creationController.CreationContext.ShapeCreationContext.TryGetSelectedCurveShapeFirstControlPointPosition(out controlPointPosition))
			{
				creationController.CreationContext.ShapeCreationContext.UpdateSelectedCurveShapeFirstControlPoint(controlPointPosition, normal, radius, broadcastChangesOverNetwork);
			}
			creationController.CreationContext.ShapeCreationContext.UpdateSelectedCurveShapeLatestControlPoint(position, normal, radius, broadcastChangesOverNetwork);
		}

		private void UpdateSelectedCurveShapeControlPoint(ScreenCreationController creationController, bool mustAddControlPoint)
		{
			GetDesiredCurveShapeControlPoint(creationController, out var position, out var normal, out var radius);
			Vector3 controlPointPosition = Vector3.zero;
			creationController.CreationContext.ShapeCreationContext.TryGetSelectedCurveShapePreviousControlPointPosition(out controlPointPosition);
			creationController.CreationContext.ShapeCreationContext.UpdateSelectedCurveShapeLatestControlPoint(position, normal, radius, broadcastChangesOverNetwork: false);
			if (mustAddControlPoint || NeedToAddNewControlPoint(controlPointPosition, position))
			{
				lastCurveShapeControlPointAddTime = UnityEngine.Time.unscaledTime;
				creationController.CreationContext.ShapeCreationContext.TryAddSelectedCurveShapeControlPoint(position, normal, radius);
			}
		}

		private bool NeedToAddNewControlPoint(Vector3 latestControlPointPosition, Vector3 desiredControlPointPosition)
		{
			float sqrMagnitude = (latestControlPointPosition - desiredControlPointPosition).sqrMagnitude;
			if (sqrMagnitude < Mathf.Epsilon)
			{
				return false;
			}
			if (UnityEngine.Time.unscaledTime - lastCurveShapeControlPointAddTime >= 0.1f)
			{
				return true;
			}
			if (sqrMagnitude >= 0.0001f)
			{
				return true;
			}
			return false;
		}

		private void GetDesiredCurveShapeControlPoint(ScreenCreationController creationController, out Vector3 position, out Vector3 normal, out float radius)
		{
			position = GetDesiredShapeCreationPosition(creationController);
			normal = Vector3.up;
			float num = ((!creationController.MakerPen.LockCurveRadiusActive) ? 1f : creationController.MakerPen.CurveRadiusModifier);
			radius = 0.033f * num;
		}

		private void StartMeshShape(ScreenCreationController creationController)
		{
			ShapeType currentShapeType = creationController.MakerPen.CurrentShapeType;
			ShapeColor selectedColor = creationController.MakerPen.SelectedColor;
			lastMeshShapeCreationInitialShapePosition = GetDesiredShapeCreationPosition(creationController);
			ShapeCreationContext.ShapeCreationResult shapeCreationResult = creationController.CreationContext.ShapeCreationContext.TryCreateAndSelectMeshShapeInSelectedShapeContainer(currentShapeType, selectedColor, lastMeshShapeCreationInitialShapePosition, Quaternion.identity, Vector3.one * 0.01f);
			if (shapeCreationResult.result != CreationResult.Success)
			{
				creationController.MakerPen.RaiseInvalidActionPerformed(shapeCreationResult.result, "Creation failed", null);
			}
		}

		private void FinishMeshShape(ScreenCreationController creationController)
		{
			FinishShapeCommon(creationController);
		}

		protected void UpdateSelectedMeshShapeSizeAndPositionPlane(ScreenCreationController creationController, bool mustBroadcastChanges)
		{
			if (UpdateSelectedMeshShapeSizeAndPosition(creationController, lastMeshShapeCreationInitialShapePosition, lastMeshShapeCreationInitialShapePosition, creationController.MakerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained, MeshShapeCreationConstraint.PROJECT_ON_PLANE, Vector3.up, mustBroadcastChanges, lastMeshShapeSizeSynchronizeTime))
			{
				lastMeshShapeSizeSynchronizeTime = UnityEngine.Time.unscaledTime;
			}
		}

		protected void UpdateSelectedMeshShapeSizeAndPositionPlaneNormal(ScreenCreationController creationController, bool mustBroadcastChanges)
		{
