namespace RecRoom.Core
{
	public class ScreenCursorSystem
	{
		private static readonly Vector2 CROSSHAIR_VIEWPORT_POSITION = new Vector2(0.5f, 0.5f);

		private static readonly Vector2 FOCUS_LOST_MOUSE_POSITION = new Vector2(-1f, -1f);

		private ScreenPlayerCursorSettings settings;

		private bool isUsingMouseCursor;

		private Vector2 positionViewportSpace = new Vector2(0.5f, 0.5f);

		private Vector2 velocityViewportSpace = Vector2.zero;

		private Vector2 accelerationViewportSpace = Vector2.zero;

		private bool isOverTarget;

		private bool isSlowedByTarget;

		private float enterTargetTime;

		public Vector2 PositionViewportSpace => positionViewportSpace;

		public bool IsCursorEnabled(ScreenHUD hud)
		{
			return hud.IsCursorEnabled;
		}

		public Ray GetRay(Camera camera)
		{
			return camera.ViewportPointToRay(positionViewportSpace);
		}

		public void SetCrosshairTickDistance(ScreenHUD hud, float crosshairTickDistanceViewportSpace)
		{
			hud.SetCrosshairTickDistance(crosshairTickDistanceViewportSpace);
		}

		public void ShowCrosshair(ScreenHUD hud, ScreenHUD.CrosshairTickMasks crosshairTickEnabledMask = ScreenHUD.CrosshairTickMasks.ALL)
		{
			hud.EnableCursor(enabled: false);
			hud.EnableCrosshair(crosshairTickEnabledMask);
		}

		public void HideCrosshair(ScreenHUD hud)
		{
			hud.DisableCrosshair();
		}

		public void UpdateMode(bool isUsingMouseCursor, ScreenHUD hud)
		{
			if (this.isUsingMouseCursor != isUsingMouseCursor)
			{
				this.isUsingMouseCursor = isUsingMouseCursor;
				ApplyCursorSettings(hud);
			}
		}

		public void SetCursorSettings(ScreenHUD hud, ScreenPlayerCursorSettings settings)
		{
			this.settings = settings;
			ApplyCursorSettings(hud);
		}

		public void HideCursor(ScreenHUD hud)
		{
			hud.EnableCursor(enabled: false);
		}

		public void ShowCursor(ScreenHUD hud)
		{
			hud.DisableCrosshair();
			hud.EnableCursor(enabled: true);
		}

		public void SnapToCenter(ScreenHUD hud)
		{
			positionViewportSpace = new Vector2(0.5f, 0.5f);
			velocityViewportSpace = Vector2.zero;
			accelerationViewportSpace = velocityViewportSpace;
			hud.SetCursorViewportSpacePosition(positionViewportSpace);
		}

		public void SetCursorScreenPosition(ScreenHUD hud, Camera camera, bool hasFocus, Vector2 screenPosition)
		{
			if (!hasFocus)
			{
				SnapCursorToViewportPosition(hud, FOCUS_LOST_MOUSE_POSITION);
			}
			else
			{
				SnapCursorToViewportPosition(hud, camera.ScreenToViewportPoint(screenPosition));
			}
		}

		public void AccelerateCursor(ScreenHUD hud, Vector2 inputVector, bool hasFocus, bool isOverTarget)
		{
			if (settings == null || !hasFocus)
			{
				return;
			}
			bool flag = this.isOverTarget;
			this.isOverTarget = isOverTarget;
			if (!flag && isOverTarget)
			{
				isSlowedByTarget = true;
				enterTargetTime = UnityEngine.Time.time;
			}
			else if (!isOverTarget)
			{
				isSlowedByTarget = false;
			}
			float num = settings.MaxSpeedViewportSpaceGamepad;
			if (isSlowedByTarget)
			{
				float num2 = Mathf.InverseLerp(enterTargetTime, enterTargetTime + settings.OverTargetSpeedReturnDelay, UnityEngine.Time.time);
				if (num2 >= 1f)
				{
					isSlowedByTarget = false;
				}
				else
				{
					float num3 = Mathf.SmoothStep(settings.OverTargetFrictionScaler, 1f, num2);
					num *= num3;
					velocityViewportSpace = Vector2.ClampMagnitude(velocityViewportSpace, num);
				}
			}
			positionViewportSpace += velocityViewportSpace * UnityEngine.Time.deltaTime;
			positionViewportSpace = new Vector2(Mathf.Clamp01(positionViewportSpace.x), Mathf.Clamp01(positionViewportSpace.y));
			Vector2 target = inputVector * settings.MaxSpeedViewportSpaceGamepad * num;
			float num4 = ((!isOverTarget) ? settings.DecelerationTimeGamepad : 0.001f);
			float smoothTime = ((!(target.sqrMagnitude <= Mathf.Epsilon)) ? settings.AccelerationTimeGamepad : num4);
			velocityViewportSpace = Vector2.SmoothDamp(velocityViewportSpace, target, ref accelerationViewportSpace, smoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			hud.SetCursorViewportSpacePosition(positionViewportSpace);
		}

		public void SnapCursorToViewportPosition(ScreenHUD hud, Vector2 positionViewportSpace)
		{
			this.positionViewportSpace = positionViewportSpace;
			velocityViewportSpace = Vector2.zero;
			accelerationViewportSpace = velocityViewportSpace;
			hud.SetCursorViewportSpacePosition(positionViewportSpace);
		}

		private void ApplyCursorSettings(ScreenHUD hud)
		{
			if (!(settings == null))
			{
				if (isUsingMouseCursor)
				{
					hud.SetCursorSprite(settings.CursorSpriteMouse, settings.CursorSpritePivotMouse);
					hud.SetCursorSize(settings.CursorSpriteViewportSizeMouse);
				}
				else
				{
					hud.SetCursorSprite(settings.CursorSpriteGamepad, settings.CursorSpritePivotGamepad);
					hud.SetCursorSize(settings.CursorSpriteViewportSizeGamepad);
				}
			}
		}

		public void HandleScreenResolutionChanges(ScreenHUD hud)
		{
			hud.SetCursorViewportSpacePosition(positionViewportSpace);
			if (settings != null)
			{
				if (isUsingMouseCursor)
				{
					hud.SetCursorSize(settings.CursorSpriteViewportSizeMouse);
				}
				else
				{
					hud.SetCursorSize(settings.CursorSpriteViewportSizeGamepad);
				}
			}
			hud.SetCrosshairViewportSpacePosition(CROSSHAIR_VIEWPORT_POSITION);
		}
	}
