	[Serializable]
	public class FreeFlyScreenPlayerCamera : ScreenPlayerCameraController
	{
		private const float MIN_MOVEMENT_DISTANCE = 0.001f;

		private const int COLLISION_LAYER_MASK = 67128320;

		[Header("Input Settings")]
		[SerializeField]
		private ScreensCameraInputGamepadSettings cameraInputSettings;

		[SerializeField]
		private float minAngleFromUp = 10f;

		[SerializeField]
		private float minAngleFromDown = 10f;

		[Header("Collision")]
		[SerializeField]
		private bool runCollisionTests = true;

		[SerializeField]
		private float collisionRadius = 0.25f;

		[SerializeField]
		private float collisionSkinThickness = 0.02f;

		[SerializeField]
		private int maxCollisionIterations = 8;

		[Header("Translation")]
		[SerializeField]
		private float maxLateralMovementSpeed = 8f;

		[SerializeField]
		private float maxVerticalMovementSpeed = 6f;

		[SerializeField]
		private float acceleration = 30f;

		[Header("Speeds")]
		[SerializeField]
		private float gamepadRotationSpeed = 120f;

		[Header("Sprinting")]
		[SerializeField]
		private AnimationCurve cameraSprintMultiplierCurve;

		[SerializeField]
		private float minSprintInputMagnitude = 0.5f;

		[NonSerialized]
		private bool _isSprinting;

		[NonSerialized]
		private Vector3 velocity = Vector3.zero;

		[NonSerialized]
		private float sprintStartTime;

		public bool IsSprinting => _isSprinting;

		public override void OnStartRunning()
		{
			base.OnStartRunning();
			velocity = Vector3.zero;
			_isSprinting = false;
		}

		public override Quaternion GetCameraRotation(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			Quaternion rotation = camera.transform.rotation;
			Vector2 rotationDeltaAngles = cameraInput.GetRotationDeltaAngles(input, cameraInputSettings, gamepadRotationSpeed * playerController.CameraGamepadSpeedMultiplier, UnityEngine.Time.deltaTime);
			return RotateOrbitCamera(rotation, rotationDeltaAngles.x, rotationDeltaAngles.y, minAngleFromUp, minAngleFromDown);
		}

		public override Vector3 GetCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			UpdateSprinting(input);
			UpdateVelocity(camera, input);
			Vector3 position = camera.transform.position;
			Vector3 vector = velocity * UnityEngine.Time.deltaTime;
			Vector3 vector2 = position;
			if (runCollisionTests)
			{
				return CollisionDetection.RunSphereCollisionDisplacement(position, collisionRadius, collisionSkinThickness, vector, 67128320, maxCollisionIterations);
			}
			return position + vector;
		}

		private void UpdateVelocity(Camera camera, ScreenInputHandler input)
		{
			Vector2 walkAxis = input.WalkAxis;
			Vector3 vector = walkAxis.x * camera.transform.right + walkAxis.y * camera.transform.forward;
			Vector3 vector2 = vector * maxLateralMovementSpeed;
			float creationFlyingVerticalAxis = input.CreationFlyingVerticalAxis;
			Vector3 vector3 = creationFlyingVerticalAxis * camera.transform.up * maxVerticalMovementSpeed;
			Vector3 target = vector2 + vector3;
			float num = 1f;
			if (IsSprinting)
			{
				float time = UnityEngine.Time.time - sprintStartTime;
				num = cameraSprintMultiplierCurve.Evaluate(time);
			}
			float num2 = Mathf.Max(velocity.magnitude, maxLateralMovementSpeed);
			float num3 = Mathf.Max(1f, num2 / maxLateralMovementSpeed);
			float num4 = acceleration * num3;
			target *= num;
			velocity = Vector3.MoveTowards(velocity, target, num4 * UnityEngine.Time.deltaTime);
		}

		private void UpdateSprinting(ScreenInputHandler input)
		{
			bool flag = input.WalkAxis.sqrMagnitude >= minSprintInputMagnitude * minSprintInputMagnitude;
			if (IsSprinting)
			{
				if (((!input.UsingKeyboardMouse) ? input.SprintButtonDown : (!input.SprintButtonPressed)) || !flag)
				{
					_isSprinting = false;
				}
			}
			else if (((!input.UsingKeyboardMouse) ? input.SprintButtonDown : input.SprintButtonPressed) && flag)
			{
				_isSprinting = true;
				sprintStartTime = UnityEngine.Time.time;
			}
		}
	}
	[Serializable]
	public class LookAtPointOfInterestScreenPlayerCamera : ScreenPlayerCameraController
	{
		[SerializeField]
		private ScreensCameraInputGamepadSettings cameraInputSettings;

		[SerializeField]
		private float gamepadCameraSpeed = 120f;

		[SerializeField]
		private float minAngleFromUp = 10f;

		[SerializeField]
		private float minAngleFromDown = 10f;

		[Header("POI Targeting")]
		[SerializeField]
		private bool snapCameraOnStart;

		[NonSerialized]
		public IPlayerPointOfInterest PointOfInterest;

		[NonSerialized]
		private bool isFirstUpdateAfterStart;

		[NonSerialized]
		private bool snapWhileBlending;

		public override void OnStartRunning()
		{
			base.OnStartRunning();
			isFirstUpdateAfterStart = true;
		}

		public override Quaternion GetCameraRotation(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			Vector2 rotationDeltaAngles = cameraInput.GetRotationDeltaAngles(input, cameraInputSettings, gamepadCameraSpeed * playerController.CameraGamepadSpeedMultiplier, UnityEngine.Time.deltaTime);
			if (isFirstUpdateAfterStart)
			{
				isFirstUpdateAfterStart = false;
				snapWhileBlending = snapCameraOnStart && rotationDeltaAngles.sqrMagnitude <= Mathf.Epsilon;
			}
			if (snapWhileBlending && isBlendingIn && PointOfInterest != null)
			{
				Vector3 forward = camera.transform.forward;
				Vector3 normalized = Vector3.ProjectOnPlane(forward, Vector3.up).normalized;
				Vector3 vector = PointOfInterest.PointOfInterestPosition - playerController.GetPlayerHeadPosition(player);
				Vector3 normalized2 = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				Quaternion quaternion = Quaternion.FromToRotation(normalized, normalized2);
				return quaternion * camera.transform.rotation;
			}
			return RotateOrbitCamera(camera.transform.rotation, rotationDeltaAngles.x, rotationDeltaAngles.y, minAngleFromUp, minAngleFromDown);
		}

		public override Vector3 GetCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			if (PointOfInterest == null)
			{
				return GetDefaultOrbitCameraPosition(playerController, player, camera, cameraSettings);
			}
			Vector3 playerPosition = playerController.GetPlayerPosition(player);
			Vector3 pointOfInterestPosition = PointOfInterest.PointOfInterestPosition;
			Vector3 vector = Vector3.ProjectOnPlane(pointOfInterestPosition - playerPosition, Vector3.up);
			Vector3 vector2 = vector / 2f;
			float magnitude = vector2.magnitude;
			Vector3 pivotOffset = playerController.GetCameraTargetOffset() + vector2;
			Transform playerTransform = playerController.GetPlayerTransform(player);
			Quaternion rotation = camera.transform.rotation;
			return TranslateOrbitCamera(playerTransform, rotation, pivotOffset, cameraSettings.TargetToPivotOffset, cameraSettings.PivotToCameraOffset, magnitude, runCollision: true, 0.2f, 0.25f);
		}
	}
