	{
		private enum MovementMode
		{
			FOLLOW_PLAYER,
			STAY_COMPLETELY_STATIONARY
		}

		[SerializeField]
		private MovementMode movementMode;

		[NonSerialized]
		public Vector3 LookDirection;

		public override Quaternion GetCameraRotation(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			Vector3 forward = camera.transform.forward;
			Vector3 normalized = Vector3.ProjectOnPlane(forward, Vector3.up).normalized;
			Vector3 normalized2 = Vector3.ProjectOnPlane(LookDirection, Vector3.up).normalized;
			Quaternion quaternion = Quaternion.FromToRotation(normalized, normalized2);
			return quaternion * camera.transform.rotation;
		}

		public override Vector3 GetCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			if (movementMode == MovementMode.FOLLOW_PLAYER)
			{
				return GetDefaultOrbitCameraPosition(playerController, player, camera, cameraSettings);
			}
			return camera.transform.position;
		}
	}
	[Serializable]
	public class StationaryScreenPlayerCamera : ScreenPlayerCameraController
	{
		private enum MovementMode
		{
			FOLLOW_PLAYER,
			STAY_COMPLETELY_STATIONARY
		}

		[SerializeField]
		private MovementMode movementMode;

		public override Quaternion GetCameraRotation(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			return camera.transform.rotation;
		}

		public override Vector3 GetCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut)
		{
			if (movementMode == MovementMode.FOLLOW_PLAYER)
			{
				return GetDefaultOrbitCameraPosition(playerController, player, camera, cameraSettings);
			}
			return camera.transform.position;
		}
	}
	public abstract class ScreenPlayerCameraController : ICloneable
	{
		[NonSerialized]
		protected ScreenCameraInput cameraInput = new ScreenCameraInput();

		protected const float DEFAULT_COLLISION_RADIUS = 0.2f;

		protected const float DEFAULT_MIN_TARGET_DISTANCE = 0.25f;

		public abstract Quaternion GetCameraRotation(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut);

		public abstract Vector3 GetCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input, ScreenCameraTargetingData cameraSettings, bool isBlendingIn, bool isBlendingOut);

		public virtual void OnStartRunning()
		{
		}

		public object Clone()
		{
			return MemberwiseClone();
		}

		protected Quaternion RotateOrbitCamera(Quaternion cameraRotation, float deltaYaw, float deltaPitch, float minAngleFromUp, float minAngleFromDown)
		{
			cameraRotation = Quaternion.Euler(0f, deltaYaw, 0f) * cameraRotation;
			Vector3 vector = cameraRotation * Vector3.forward;
			Vector3 vector2 = cameraRotation * Vector3.right;
			float num = Vector3.SignedAngle(vector, Vector3.up, -vector2);
			float value = num + deltaPitch;
			float num2 = Mathf.Clamp(value, minAngleFromUp, 180f - minAngleFromDown);
			float x = num2 - num;
			cameraRotation *= Quaternion.Euler(x, 0f, 0f);
			return cameraRotation;
		}

		protected Vector3 GetDefaultOrbitCameraPosition(ScreenPlayerController playerController, Player player, Camera camera, ScreenCameraTargetingData cameraSettings)
		{
			Transform playerTransform = playerController.GetPlayerTransform(player);
			Quaternion rotation = camera.transform.rotation;
			Vector3 cameraTargetOffset = playerController.GetCameraTargetOffset();
			return TranslateOrbitCamera(playerTransform, rotation, cameraTargetOffset, cameraSettings.TargetToPivotOffset, cameraSettings.PivotToCameraOffset, 0f, runCollision: true, 0.2f, 0.25f);
		}

		protected Vector3 TranslateOrbitCamera(Transform targetTransform, Quaternion cameraRotation, Vector3 pivotOffset, Vector3 targetToPivotOffset, Vector3 pivotToCameraOffset, float dynamicPivotToCameraAdditionalOffset, bool runCollision, float collisionRadius, float minCollisionTargetDistance)
		{
			Vector3 vector = targetTransform.TransformPoint(targetToPivotOffset);
			Vector3 coordinateSpaceOrigin = vector + pivotOffset;
			pivotToCameraOffset.z = Mathf.Sign(pivotToCameraOffset.z) * (Mathf.Abs(pivotToCameraOffset.z) + dynamicPivotToCameraAdditionalOffset);
			Vector3 vector2 = pivotToCameraOffset.TransformCoordinateSpace(coordinateSpaceOrigin, cameraRotation);
			if (runCollision)
			{
				vector2 = CollisionDetection.RunOrbitCameraCollision(vector, vector2, minCollisionTargetDistance, collisionRadius);
			}
			return vector2;
		}
	}
	public class ScreenPlayerCameraControllerPool<T> where T : ScreenPlayerCameraController
	{
		private readonly T controllerPrefab;

		private List<T> pooledControllers = new List<T>();

		public ScreenPlayerCameraControllerPool(T controllerPrefab)
		{
			this.controllerPrefab = controllerPrefab;
		}

		public T GetNextCameraController(ScreenPlayerController playerController)
		{
			for (int i = 0; i < pooledControllers.Count; i++)
			{
				if (!playerController.IsCameraControllerRunning(pooledControllers[i]))
				{
					return pooledControllers[i];
				}
			}
			T val = controllerPrefab;
			T val2 = (T)val.Clone();
			pooledControllers.Add(val2);
			return val2;
		}
	}
}
namespace RecRoom.Core
{
	[Serializable]
	public struct ScreenCameraTargetingData
	{
		public Vector3 TargetToPivotOffset;

		public Vector3 PivotToCameraOffset;

		public float FOV;

		public static ScreenCameraTargetingData Default => new ScreenCameraTargetingData
		{
			TargetToPivotOffset = new Vector3(0.08f, 1.73f, 0.02f),
			PivotToCameraOffset = new Vector3(0.4f, -0.12f, -1.6f),
			FOV = 60f
		};

		public void ApplyToCamera(Camera camera)
		{
			camera.fieldOfView = FOV;
		}

		public static ScreenCameraTargetingData Interpolate(ScreenCameraTargetingData lhs, ScreenCameraTargetingData rhs, float t)
		{
			return new ScreenCameraTargetingData
			{
				TargetToPivotOffset = Vector3.Lerp(lhs.TargetToPivotOffset, rhs.TargetToPivotOffset, t),
				PivotToCameraOffset = Vector3.Lerp(lhs.PivotToCameraOffset, rhs.PivotToCameraOffset, t),
				FOV = Mathf.Lerp(lhs.FOV, rhs.FOV, t)
			};
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Player Settings/Screen Player Camera Settings", fileName = "ScreenPlayerCameraSettings")]
