		private ScreenPlayerGenreController ActiveGenreController
		{
			get
			{
				return _activeGenre;
			}
			set
			{
				if (!(_activeGenre == value))
				{
					if (_activeGenre != null)
					{
						_activeGenre.OnExitGenre();
					}
					_activeGenre = value;
					if (_activeGenre != null)
					{
						_activeGenre.OnEnterGenre(this, Player.LocalPlayer, SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera, SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD, inputHandler);
					}
				}
			}
		}

		private TeleportationPortal HoveredPortal
		{
			get
			{
				return _hoveredPortal;
			}
			set
			{
				if (_hoveredPortal != value)
				{
					if (_hoveredPortal != null)
					{
						_hoveredPortal.Highlight = false;
					}
					_hoveredPortal = value;
					if (_hoveredPortal != null)
					{
						_hoveredPortal.Highlight = true;
					}
				}
			}
		}

