		public bool TryPickupToolMainHand(Player player, Tool tool, bool playAnimation = false)
		{
			if (tool == null)
			{
				return false;
			}
			rightHandIsMainHand = !tool.ScreenPickupWithLeftHand;
			return TryPickupTool(player, tool, playAnimation, useMainHand: true);
		}

		public bool TryPickupToolOffHand(Player player, Tool tool, bool playAnimation = false)
		{
			return TryPickupTool(player, tool, playAnimation, useMainHand: false);
		}

		public bool HasActionInput(ScreenInputHandler input)
		{
			return input.PickupButtonDown || input.PrimaryMainHandActionButtonDown || input.SecondaryMainHandActionButtonDown || input.OffHandActionButtonDown || input.AimDownSightsButtonDown || input.JumpButtonDown || input.CrouchButtonDown;
		}

		private bool TryPickupTool(Player player, Tool tool, bool playAnimation, bool useMainHand)
		{
			if (playAnimation)
			{
				PlayerHand playerHand = ((!useMainHand) ? GetOffHand(player) : GetMainHand(player));
				PlayerAnimation playerAnimation = ((playerHand.Type != PlayerHand.HandType.Left) ? rightHandPickupAnimation : leftHandPickupAnimation);
				if (playerAnimation != null && playerAnimation.AnimationAsset != null)
				{
					deferredPickupTool = tool;
					deferredPickupToolInMainHand = useMainHand;
					PlayUninterruptableAnimation(playerAnimation, restartIfAlreadyPlaying: true);
					return true;
				}
			}
			return PickupToolInternal(player, tool, useMainHand);
		}

		public bool TryDropMainHandTool(Player player, bool tryPickupFromEquipSlot = false)
		{
			if (player == null)
			{
				return false;
			}
			bool flag = TryThrowMainHandTool(player, toolDropSpeed);
			if (flag && tryPickupFromEquipSlot)
			{
				TrySwapEquipSlotTool(player, toolEquipFirstSlotIndex, incrementIndex: true);
			}
			return flag;
		}

		public bool TryThrowMainHandTool(Player player, float throwSpeed)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand mainHand = GetMainHand(player);
			Vector3 linearVelocity = GetToolReleaseDirection(mainHand) * throwSpeed;
			return TryThrowMainHandTool(player, linearVelocity);
		}

		public bool TryThrowMainHandTool(Player player, float throwSpeed, Vector3 angularVelocity)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand mainHand = GetMainHand(player);
			Vector3 linearVelocity = GetToolReleaseDirection(mainHand) * throwSpeed;
			return TryThrowMainHandTool(player, linearVelocity, angularVelocity);
		}

		public bool TryThrowMainHandTool(Player player, Vector3 linearVelocity)
		{
			return TryThrowMainHandTool(player, linearVelocity, Vector3.zero);
		}

		public bool TryThrowMainHandTool(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand mainHand = GetMainHand(player);
			if (mainHand.HeldTool == null)
			{
				return false;
			}
			if (mainHand.TryReleaseTool(linearVelocity, angularVelocity))
			{
				rightHandIsMainHand = true;
				return true;
			}
			return false;
		}

		public bool TryThrowOffHandTool(Player player, float throwSpeed)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand offHand = GetOffHand(player);
			Vector3 linearVelocity = GetToolReleaseDirection(offHand) * throwSpeed;
			return TryThrowOffHandTool(player, linearVelocity);
		}

		public bool TryThrowOffHandTool(Player player, float throwSpeed, Vector3 angularVelocity)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand offHand = GetOffHand(player);
			Vector3 linearVelocity = GetToolReleaseDirection(offHand) * throwSpeed;
			return TryThrowOffHandTool(player, linearVelocity, angularVelocity);
		}

		public bool TryThrowOffHandTool(Player player, Vector3 linearVelocity)
		{
			return TryThrowOffHandTool(player, linearVelocity, Vector3.zero);
		}

		public bool TryThrowOffHandTool(Player player, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			if (player == null)
			{
				return false;
			}
			PlayerHand offHand = GetOffHand(player);
			if (offHand.HeldTool != null && offHand.TryReleaseTool(linearVelocity, angularVelocity))
			{
				return true;
			}
			return false;
		}

		public bool TryDropOffHandTool(Player player)
		{
			if (player == null)
			{
				return false;
			}
			return TryThrowOffHandTool(player, toolDropSpeed);
		}

		public PlayerHand GetMainHand(Player player)
		{
			if (player == null)
			{
				return null;
			}
			return (!rightHandIsMainHand) ? player.LeftHand : player.RightHand;
		}

		public PlayerHand GetOffHand(Player player)
		{
			if (player == null)
			{
				return null;
			}
			return (!rightHandIsMainHand) ? player.RightHand : player.LeftHand;
		}

		public Tool GetOtherHeldTool(Player player, Tool tool)
		{
			if (player == null || tool == null)
			{
				return null;
			}
			if (!tool.IsHeldByPlayer || tool.HolderPlayer != player)
			{
				return null;
			}
			PlayerHand holderHand = tool.HolderHand;
			if (holderHand == null)
			{
				return null;
			}
			PlayerHand otherHand = player.GetOtherHand(holderHand.Type);
			return otherHand.HeldTool;
		}

