		public void Initialize(LocalPlayerController localPlayerController)
		{
			AnimationSystem = new PlayerAnimationSystem();
			CameraSystem = new ScreenCameraSystem();
			CursorSystem = new ScreenCursorSystem();
			VirtualKeyboardController = new VirtualKeyboardController();
			fidgetAnimationController.AddFidgetAnimationSet(fidgetAnimationSet);
			latestStandFidgetAnimation = new PlayerAnimation();
			latestStandFidgetAnimation.Initialize(null, fidgetFadeTime, fidgetFadeTime, fidgetFadeTime, 1f, isMirrored: false);
			latestWalkFidgetAnimation = new PlayerAnimation();
			latestWalkFidgetAnimation.Initialize(null, fidgetFadeTime, fidgetFadeTime, fidgetFadeTime, 1f, isMirrored: false);
			EmoteSystem = new ScreenPlayerEmoteSytem();
			QuickTimeEmoteController = new QuickTimeEmoteController();
			QuickTimeEmoteController.AddEmotes(defaultQuickTimeEmotes);
			quickCommsMenuController.Initialize();
			quickCommsMenuController.AddMenu(defaultQuickCommMenu, this);
			Array.Sort(menuControllers, (PrioritizedMenuController a, PrioritizedMenuController b) => a.priority.CompareTo(b.priority));
			for (int num = 0; num < menuControllers.Length; num++)
			{
				menuControllers[num].menuController.Initialize(this);
			}
			cameraGamepadSpeedMultiplierMap.AddValue(1f, this);
			locomotionStateMachine.AddState(0, null, null, null);
			locomotionStateMachine.AddState(1, null, null, OnUpdateStandLocomotionState);
			locomotionStateMachine.AddState(2, null, null, OnUpdateWalkLocomotionState);
			locomotionStateMachine.AddState(4, OnEnterSprintLocomotionState, OnExitSprintLocomotionState, OnUpdateSprintLocomotionState);
			locomotionStateMachine.AddState(3, OnEnterCrouchLocomotionState, OnExitCrouchLocomotionState, OnUpdateCrouchLocomotionState);
			locomotionStateMachine.AddState(5, OnEnterJumpLocomotionState, null, OnUpdateJumpLocomotionState);
			locomotionStateMachine.AddState(8, OnEnterJumpLocomotionState, OnExitJumpSprintingLocomotionState, OnUpdateJumpSprintingLocomotionState);
			locomotionStateMachine.AddState(6, OnEnterFallLocomotionState, null, OnUpdateFallLocomotionState);
			locomotionStateMachine.AddState(9, OnEnterFallLocomotionState, OnExitFallSprintingLocomotionState, OnUpdateFallSprintingLocomotionState);
			locomotionStateMachine.AddState(7, OnEnterLandLocomotionState, OnExitLandLocomotionState, OnUpdateLandLocomotionState);
			locomotionStateMachine.AddState(10, OnEnterLandLocomotionState, OnExitLandSprintingLocomotionState, OnUpdateLandSprintingLocomotionState);
			locomotionStateMachine.AddState(11, OnEnterSittingInSeatLocomotionState, OnExitSittingInSeatLocomotionState, OnUpdateSittingInSeatLocomotionState);
			playerStateMachine.AddState(0, null, null, null);
			playerStateMachine.AddState(1, OnEnterPausedState, OnExitPausedState, OnUpdatePausedState);
			playerStateMachine.AddState(11, OnEnterMenuState, OnExitMenuState, OnUpdateMenuState);
			playerStateMachine.AddState(2, OnEnterIdleState, OnExitIdleState, OnUpdateIdleState);
			playerStateMachine.AddState(3, OnEnterEmoteState, OnExitEmoteState, OnUpdateEmoteState);
			playerStateMachine.AddState(8, OnEnterSocialActionState, OnExitSocialActionState, OnUpdateSocialActionState);
			playerStateMachine.AddState(6, OnEnterToolActionState, OnExitToolActionState, OnUpdateToolActionState);
			playerStateMachine.AddState(4, OnEnterClimbState, OnExitClimbState, OnUpdateClimbState);
			playerStateMachine.AddState(5, OnEnterDodgeState, OnExitDodgeState, OnUpdateDodgeState);
			playerStateMachine.AddState(7, OnEnterContextSensitiveActionState, OnExitContextSensitiveActionState, OnUpdateContextSensitiveActionState);
			playerStateMachine.AddState(9, OnEnterCustomGameState, OnExitCustomGameState, OnUpdateCustomGameState);
			playerStateMachine.AddState(10, OnEnterVehicleState, OnExitVehicleState, OnUpdateVehicleState);
			playerStateMachine.AddState(12, null, null, OnUpdatePreviewRecordingState);
			AddSteeringController(defaultSteering, this, -1);
			AddCameraController(defaultCamera, 0f, this, -1);
			for (int num2 = 0; num2 < genres.Length; num2++)
