		public void OnEnterMode()
		{
			RigidbodyEx.FollowProxiesWithPhysics = false;
			RigidbodyPickup.GlobalJointPickupEnabled = false;
			inputHandler = SingletonMonoBehaviour<InputManager>.Instance.ScreenInputHandler;
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = true;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			ResetCursor(screenModeHUD);
			Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawn);
			if (!(Player.LocalPlayer == null))
			{
				OnLocalPlayerCreated();
			}
		}

		public void OnExitMode()
		{
			inputHandler = null;
			HoveredPortal = null;
			Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawn);
			locomotionStateMachine.EnterState(0);
			playerStateMachine.EnterState(0);
			CleanupLocalPlayer();
		}

		public void OnUpdate()
		{
			if (!(Player.LocalPlayer == null))
			{
				Player localPlayer = Player.LocalPlayer;
				Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
				ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
				PlayerState currentStateId = (PlayerState)playerStateMachine.CurrentStateId;
				PreCoreUpdate(localPlayer, screenModeCamera, screenModeHUD, currentStateId, inputHandler);
				CoreUpdate(localPlayer, screenModeCamera, inputHandler);
				PostCoreUpdate(localPlayer, screenModeHUD, currentStateId, inputHandler);
			}
		}

		public void OnLateUpdate()
		{
			if (!(Player.LocalPlayer == null))
			{
				Player localPlayer = Player.LocalPlayer;
				Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
				ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
				ScreenInputHandler input = inputHandler;
				cameraTargetOffset = UpdateCameraHeightReduction();
				CameraSystem.OnLateUpdate(this, localPlayer, screenModeCamera, input);
				if (ActiveGenreController != null)
				{
					ActiveGenreController.OnLateUpdate();
				}
				switch ((PlayerState)playerStateMachine.CurrentStateId)
				{
				case PlayerState.MENU:
					OnLateUpdateMenu();
					break;
				case PlayerState.CUSTOM_GAME:
					OnLateUpdateCustomGameState();
					break;
				}
			}
		}

