			AddGenreType(ScreenPlayerGenreType.SOCIAL, this, -1);
			InitializePlayerOnEnterMode(Player.LocalPlayer, SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera);
			QuickTimeEmoteController.Initialize(quickTimeEmoteSfx);
			locomotionStateMachine.EnterState(1);
			playerStateMachine.EnterState(2);
		}

