		public Player InstantiateLocalPlayer(Vector3 position, Quaternion rotation)
		{
			Player result = null;
			if (!Player.LocalPlayerExists)
			{
				object[] data = new object[8] { DEFAULT_PLAYER_HEAD_POSITION, DEFAULT_PLAYER_HEAD_ROTATION, DEFAULT_PLAYER_LEFT_HAND_POSITION, DEFAULT_PLAYER_HAND_ROTATION, DEFAULT_PLAYER_RIGHT_HAND_POSITION, DEFAULT_PLAYER_HAND_ROTATION, position, rotation };
				GameObject gameObject = PhotonNetwork.Instantiate("[Player]", position, rotation, 1f, 0, data);
				result = gameObject.GetComponent<Player>();
