		public T GetGenreController<T>(ScreenPlayerGenreType genreType) where T : ScreenPlayerGenreController
		{
			ScreenPlayerGenreController genreController = GetGenreController(genreType);
			return (!(genreController != null)) ? ((T)null) : ((T)genreController);
		}

		public void SetActiveGenre(ScreenPlayerGenreType genreType)
		{
			if (genreType == ScreenPlayerGenreType.INVALID)
			{
				ActiveGenreController = null;
				return;
			}
			ScreenPlayerGenreController genreController = GetGenreController(genreType);
			if (genreController != null)
			{
				ActiveGenreController = genreController;
			}
		}

		private ScreenPlayerGenreController GetGenreController(ScreenPlayerGenreType genreType)
		{
			for (int i = 0; i < genres.Length; i++)
			{
				if (genres[i].GenreType == genreType)
				{
					return genres[i].GenreController;
				}
			}
			return null;
		}

		private void PreCoreUpdate(Player player, Camera camera, ScreenHUD hud, PlayerState currentState, ScreenInputHandler input)
		{
			hud.DisableInteractDialog();
			openingMenu = false;
			quickCommsMenuController.OnUpdate(this, player, hud, input);
			QuickTimeEmoteController.OnUpdate(this, hud, quickTimeEmoteViewportPosition, inputHandler);
			hud.ClearToolActionDialogs();
			if (currentState != PlayerState.MENU)
			{
				openingMenu = TryOpenAnyMenu(player, camera, hud, input, out currentMenuController);
			}
			bool flag = currentState == PlayerState.IDLE || currentState == PlayerState.EMOTE;
			bool flag2 = currentState == PlayerState.TOOL_ACTION && (currentToolActionController == null || !currentToolActionController.IsBlockingOthers);
			if (!flag && !flag2)
			{
				return;
			}
			if (CanStartClimbing(player, input))
			{
				playerStateMachine.EnterState(4);
				return;
			}
			if (TryStartDodge(player, input))
			{
				playerStateMachine.EnterState(5);
			}
			if (!flag2 && TryStartAnyToolAction(player, hud, input, out currentToolActionController, out currentActiveTool))
			{
				playerStateMachine.EnterState(6);
			}
			else if (TryStartAnyCustomGameBehavior(player, camera, hud, input, out currentCustomGameBehaviorController))
			{
				playerStateMachine.EnterState(9);
			}
			else if (TryStartAnyContextSensitiveAction(player, camera, hud, input, out currentContextSensitiveController, out currentContextSensitiveRegion))
			{
				playerStateMachine.EnterState(7);
			}
			else if (TryStartAnySocialAction(player, camera, hud, input, out currentSocialActionController))
			{
				playerStateMachine.EnterState(8);
			}
		}

		private void CoreUpdate(Player player, Camera camera, ScreenInputHandler input)
		{
			CameraSystem.OnUpdate(this, player, camera, input);
			float normalizedDistance = 0f;
			Vector3 gazeTarget = Vector3.zero;
			Vector3 gazeDirection = Vector3.zero;
			GetGazeTarget(player, camera, out gazeTarget, out gazeDirection, out normalizedDistance);
			GazeTarget = gazeTarget;
			GazeDirection = gazeDirection;
			NormalizedGazeTargetDistance = normalizedDistance;
			if (ActiveGenreController != null)
			{
				ActiveGenreController.OnUpdate();
			}
			locomotionStateMachine.Update();
			playerStateMachine.Update();
			steeringControllerMap.HighestPriorityValue?.ApplySteering(this, player, camera, input);
			AnimationSystem.OnUpdate(ApplyAnimationFrame, UnityEngine.Time.deltaTime, animationEvents, out var leftHandVelocity, out var rightHandVelocity);
			LeftHandVelocity = player.TrackingSpace.RigidbodyEx.TargetTransform.TransformVector(leftHandVelocity);
			RightHandVelocity = player.TrackingSpace.RigidbodyEx.TargetTransform.TransformVector(rightHandVelocity);
			ProcessAnimationEvents(player, camera, LeftHandVelocity, RightHandVelocity, animationEvents);
			player.LocalUpdateVoicePushToTalk(input.PushToTalkButtonPressed);
		}

		private void PostCoreUpdate(Player player, ScreenHUD hud, PlayerState currentState, ScreenInputHandler input)
		{
			VirtualKeyboardController.OnUpdate();
			UpdateAFK(player, input);
			CursorSystem.UpdateMode(input.UsingKeyboardMouse, hud);
			CursorSystem.HandleScreenResolutionChanges(hud);
			hud.SetToolActionRootViewportPosition(toolActionRootViewportPosition);
			if (openingMenu)
			{
				playerStateMachine.EnterState(11);
			}
			if (player.IsInVehicle && currentState != PlayerState.VEHICLE && currentState != PlayerState.MENU)
			{
				playerStateMachine.EnterState(10);
			}
			if (currentState != PlayerState.PAUSED && IsPauseStateDesired())
			{
				playerStateMachine.EnterState(1);
			}
		}

		private bool IsPauseStateDesired()
		{
			if (SingletonMonoBehaviour<SessionManager>.Instance != null && SingletonMonoBehaviour<SessionManager>.Instance.IsSwitchingRooms)
			{
				return true;
			}
			if (Player.LocalPlayer != null && Player.LocalPlayer.IsSpawning)
			{
				return true;
			}
			if (SingletonMonoBehaviour<CameraFade>.Instance.IsFading)
			{
				return true;
			}
			return false;
		}

		private void OnEnterPausedState(ushort previousStateId, ushort previousSubStateId)
		{
			AddSteeringController(stationarySteering, PAUSED_TOKEN, 100000);
			AddCameraController(stationaryCamera, 0f, PAUSED_TOKEN, 100000);
		}

		private void OnUpdatePausedState()
		{
			if (!IsPauseStateDesired())
			{
				playerStateMachine.EnterState(2);
				return;
			}
			Player localPlayer = Player.LocalPlayer;
			if (!(localPlayer == null))
			{
				UpdateActiveAnimation(localPlayer);
				localPlayer.PlayerWalking.UpdateWalkVelocity(Vector3.zero, 0f);
			}
		}

		private void OnExitPausedState(ushort nextStateId, ushort nextSubStateId)
		{
			RemoveSteeringController(PAUSED_TOKEN);
			RemoveCameraController(PAUSED_TOKEN);
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
		{
			lastIdleStartTime = UnityEngine.Time.time;
		}

		private void OnUpdateIdleState()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			GameManager instance = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			UpdateHoveredTool(localPlayer, screenModeHUD, screenModeCamera, inputHandler);
			UpdateFavoriteToolPickup(localPlayer, screenModeHUD, instance, inputHandler);
			UpdateToolDrop(localPlayer, screenModeHUD, inputHandler);
			UpdateToolPickup(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
			UpdateActiveToolCursor(localPlayer, screenModeHUD);
			UpdateActiveToolControlType(localPlayer);
			UpdatePortalInteraction(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
			UpdateEquipSlotToolSwap(localPlayer, inputHandler);
			if (EmoteSystem.HasQueuedEmote)
			{
				playerStateMachine.EnterState(3);
				return;
			}
			if (PlayerAnimationRecording.StaticLatestRecordings.Count > 0)
			{
				playerStateMachine.EnterState(12);
				return;
			}
			UpdateActiveAnimation(localPlayer);
			PlayerHand mainHand = GetMainHand(localPlayer);
			PlayerHand offHand = GetOffHand(localPlayer);
			if (mainHand.HeldTool != null || offHand.HeldTool != null)
			{
				screenModeHUD.AddToolActionDialog(inputHandler.DropToolButtonSprite, "Drop", GetToolDropProgress());
			}
		}

		private void OnExitIdleState(ushort nextStateId, ushort nextSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			PlayerHand mainHand = GetMainHand(localPlayer);
			mainHand.ClearHoveredTool();
			PlayerHand offHand = GetOffHand(localPlayer);
			offHand.ClearHoveredTool();
		}

		private void OnEnterToolActionState(ushort previousStateId, ushort previousSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			if (IsToolValidForPlayerControls(currentActiveTool, localPlayer))
			{
				localPlayer.PlayerWalking.AddSprintEnabled(enabled: false, this, int.MaxValue);
				Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
				ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
				StartCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
			}
		}

		private void OnUpdateToolActionState()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (!IsToolValidForPlayerControls(currentActiveTool, localPlayer))
			{
				playerStateMachine.EnterState(2);
				return;
			}
			if (currentToolActionController != null)
			{
				currentToolActionController.TryAddTooltip(this, localPlayer, currentActiveTool, screenModeHUD, inputHandler);
			}
			ScreenToolController newActiveController = null;
			Tool newActiveTool = null;
			if (TryStartDifferentToolAction(localPlayer, screenModeHUD, inputHandler, currentActiveTool, currentToolActionController, out newActiveController, out newActiveTool))
			{
				StopCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD);
				currentToolActionController = newActiveController;
				currentActiveTool = newActiveTool;
				StartCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
			}
			if (!UpdateCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD, inputHandler))
			{
				playerStateMachine.EnterState(2);
				return;
			}
			UpdateActiveToolControlType(localPlayer);
			UpdateActiveToolCursor(localPlayer, screenModeHUD);
		}

		private void OnExitToolActionState(ushort nextStateId, ushort nextSubStateId)
		{
			LastToolUseTime = UnityEngine.Time.time;
			Player localPlayer = Player.LocalPlayer;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (currentToolActionController != null)
			{
				Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
				StopCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD);
			}
			localPlayer.PlayerWalking.RemoveSprintEnabled(this);
			OnGameplayCursorVisibilityRestrictionChange();
		}

		private bool IsToolValidForPlayerControls(Tool tool, Player player)
		{
			if (tool == null)
			{
				return false;
			}
			if (tool.HolderPlayer != null && tool.HolderPlayer != player)
			{
				return false;
			}
			return true;
		}

		private void UpdateActiveToolCursor(Player player, ScreenHUD hud)
		{
			if (currentActiveTool != null)
			{
				UpdateToolCursor(currentActiveTool, player, hud);
				return;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (heldTool != null)
			{
				UpdateToolCursor(heldTool, player, hud);
				return;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (heldTool2 != null)
			{
				UpdateToolCursor(heldTool2, player, hud);
			}
		}

		private void UpdateToolCursor(Tool tool, Player player, ScreenHUD hud)
		{
			for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
			{
				tool.ScreenActionControllers[i].UpdateCursor(this, player, tool, hud);
			}
		}

		private void UpdateActiveToolControlType(Player player)
		{
			ScreenPlayerGenreType toolControlType = ScreenPlayerGenreType.INVALID;
			if (currentActiveTool != null && TryGetToolControlType(currentActiveTool, out toolControlType))
			{
				AddGenreType(toolControlType, ACTIVE_TOOL_CONTROL_TOKEN, 50000);
				return;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (heldTool == null && deferredPickupTool != null && deferredPickupToolInMainHand)
			{
				heldTool = deferredPickupTool;
			}
			if (heldTool != currentActiveTool && TryGetToolControlType(heldTool, out toolControlType))
			{
				AddGenreType(toolControlType, ACTIVE_TOOL_CONTROL_TOKEN, 50000);
				return;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (heldTool2 == null && deferredPickupTool != null && !deferredPickupToolInMainHand)
			{
				heldTool2 = deferredPickupTool;
			}
			if (heldTool2 != currentActiveTool && TryGetToolControlType(heldTool2, out toolControlType))
			{
				AddGenreType(toolControlType, ACTIVE_TOOL_CONTROL_TOKEN, 50000);
			}
			else
			{
				RemoveGenreType(ACTIVE_TOOL_CONTROL_TOKEN);
			}
		}

		private bool TryGetToolControlType(Tool tool, out ScreenPlayerGenreType toolControlType)
		{
			toolControlType = ScreenPlayerGenreType.INVALID;
			bool result = false;
			if (tool != null)
			{
				for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
				{
					ScreenPlayerGenreType requiredControlType = ScreenPlayerGenreType.INVALID;
					if (tool.ScreenActionControllers[i].TryGetRequiredControlType(out requiredControlType))
					{
						toolControlType = requiredControlType;
						result = true;
					}
				}
			}
			return result;
		}

		private bool TryStartAnyToolAction(Player player, ScreenHUD hud, ScreenInputHandler input, out ScreenToolController newActiveController, out Tool newActiveTool)
		{
			newActiveController = null;
			newActiveTool = null;
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (heldTool != null && TryStartHeldToolAction(player, heldTool, hud, input, out newActiveController))
			{
				newActiveTool = heldTool;
				return true;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (heldTool2 != null && TryStartHeldToolAction(player, heldTool2, hud, input, out newActiveController))
			{
				newActiveTool = heldTool2;
				return true;
			}
			if (heldTool != null && TryStartDefaultToolAction(player, heldTool, hud, input, out newActiveController))
			{
				newActiveTool = heldTool;
				return true;
			}
			return false;
		}

		private bool TryStartHeldToolAction(Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input, out ScreenToolController newActiveController)
		{
			newActiveController = null;
			for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
			{
				ScreenToolController screenToolController = tool.ScreenActionControllers[i];
				if (screenToolController.CanStart(this, player, tool, input))
				{
					newActiveController = screenToolController;
					return true;
				}
				screenToolController.TryAddTooltip(this, player, tool, hud, input);
			}
			return false;
		}

		private bool TryStartDefaultToolAction(Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input, out ScreenToolController newActiveController)
		{
			newActiveController = null;
			if (tool.ScreenActionControllers == null || tool.ScreenActionControllers.Length == 0)
			{
				if (defaultToolActionController.CanStart(this, player, tool, input))
				{
					newActiveController = defaultToolActionController;
					return true;
				}
				defaultToolActionController.TryAddTooltip(this, player, tool, hud, input);
			}
			return false;
		}

		private bool TryStartDifferentToolAction(Player player, ScreenHUD hud, ScreenInputHandler input, Tool currentTool, ScreenToolController currentController, out ScreenToolController newActiveController, out Tool newActiveTool)
		{
			newActiveController = null;
			newActiveTool = null;
			if (!currentController.IsBlockingSelf && currentController.CanStart(this, player, currentTool, input))
			{
				newActiveController = currentController;
				newActiveTool = currentTool;
				return true;
			}
			if (currentController.IsBlockingOthers)
			{
				return false;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (TryStartToolController(heldTool, player, hud, input, currentController, out newActiveController, out newActiveTool))
			{
				return true;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (TryStartToolController(heldTool2, player, hud, input, currentController, out newActiveController, out newActiveTool))
			{
				return true;
			}
			return false;
		}

		private bool TryStartToolController(Tool tool, Player player, ScreenHUD hud, ScreenInputHandler input, ScreenToolController currentController, out ScreenToolController newActiveController, out Tool newActiveTool)
		{
			newActiveController = null;
			newActiveTool = null;
			if (tool == null || tool.ScreenActionControllers == null)
			{
				return false;
			}
			for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
			{
				ScreenToolController screenToolController = tool.ScreenActionControllers[i];
				if (!(screenToolController == currentController))
				{
					if (screenToolController.CanStart(this, player, tool, input))
					{
						newActiveController = screenToolController;
						newActiveTool = tool;
						return true;
					}
					screenToolController.TryAddTooltip(this, player, tool, hud, input);
				}
			}
			return false;
		}

		private void StartCurrentToolAction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!(currentToolActionController == null) && !(currentActiveTool == null))
			{
				if (!currentToolActionController.PlayerMovementAllowed)
				{
					ClearHeadGazeAngles();
					ClearHandGazeAngles();
				}
				currentToolActionController.OnStart(this, player, camera, currentActiveTool, hud, input);
			}
		}

		private bool UpdateCurrentToolAction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (currentToolActionController == null || currentActiveTool == null)
			{
				return false;
			}
			return currentToolActionController.OnUpdate(this, player, camera, currentActiveTool, hud, input);
		}

		private void StopCurrentToolAction(Player player, Camera camera, ScreenHUD hud)
		{
			if (currentToolActionController != null)
			{
				currentToolActionController.OnStop(this, player, camera, currentActiveTool, hud);
			}
			currentToolActionController = null;
			currentActiveTool = null;
		}

		private void OnEnterMenuState(ushort previousStateId, ushort previousSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = false;
			CursorSystem.ShowCursor(screenModeHUD);
			quickCommsMenuController.AddRestriction(MENU_STATE_TOKEN);
			AddCrouchRestriction(MENU_STATE_TOKEN);
			AddSteeringController(stationarySteering, MENU_STATE_TOKEN, 10000);
			AddCameraController(stationaryCamera, 0f, MENU_STATE_TOKEN, 10000);
			localPlayer.PlayerWalking.AddJumpEnabled(enabled: false, this, int.MaxValue);
			StartCurrentMenu(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
		}

		private void OnUpdateMenuState()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (!UpdateCurrentMenu(localPlayer, screenModeCamera, screenModeHUD, inputHandler))
			{
				playerStateMachine.EnterState(2);
				return;
			}
			bool isOverTarget = UpdateMenuInput(screenModeCamera, inputHandler);
			UpdateMenuCursorPosition(screenModeCamera, screenModeHUD, inputHandler, isOverTarget);
			if (!currentMenuController.HasPlayerAnimation)
			{
				UpdateActiveAnimation(localPlayer);
			}
		}

		private void OnLateUpdateMenu()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			LateUpdateCurrentMenu(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
		}

		private void OnExitMenuState(ushort nextStateId, ushort nextSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = true;
			StopCurrentMenu(localPlayer, screenModeCamera, screenModeHUD);
			localPlayer.PlayerWalking.RemoveJumpEnabled(this);
			RemoveSteeringController(MENU_STATE_TOKEN);
			RemoveCameraController(MENU_STATE_TOKEN);
			RemoveCrouchRestriction(MENU_STATE_TOKEN);
			quickCommsMenuController.RemoveRestriction(MENU_STATE_TOKEN);
			ResetCursor(screenModeHUD);
		}

		private void StartCurrentMenu(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!(currentMenuController == null))
			{
				currentMenuController.OnStart(this, player, camera, hud, input);
			}
		}

		private bool UpdateCurrentMenu(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (currentMenuController == null)
			{
				return false;
			}
			return currentMenuController.OnUpdate(this, player, camera, hud, input);
		}

		private void LateUpdateCurrentMenu(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!(currentMenuController == null))
			{
				currentMenuController.OnLateUpdate(this, player, camera, hud, input);
			}
		}

		private void StopCurrentMenu(Player player, Camera camera, ScreenHUD hud)
		{
			if (!(currentMenuController == null))
			{
				currentMenuController.OnStop(this, player, camera, hud);
				currentMenuController = null;
			}
		}

		private void UpdateMenuCursorPosition(Camera camera, ScreenHUD hud, ScreenInputHandler input, bool isOverTarget)
		{
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (input.UsingKeyboardMouse)
			{
				CursorSystem.SetCursorScreenPosition(hud, camera, gameViewFocused, input.CursorMouseScreenPosition);
			}
			else
			{
				CursorSystem.AccelerateCursor(hud, input.CursorAxis, gameViewFocused, isOverTarget);
			}
		}

		private bool UpdateMenuInput(Camera camera, ScreenInputHandler input)
		{
			Ray ray = CursorSystem.GetRay(camera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, 0f, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, input.CursorButtonDown, input.CursorButtonUp);
			return result.UISelectable;
		}

		private bool CanStartClimbing(Player player, ScreenInputHandler input)
		{
			if (!player.PlayerLocomotion.CanClimb(out var climbType, out var climbableSurfaceWallNormal))
			{
				return false;
			}
			if (Vector3.Dot(GazeDirection, climbableSurfaceWallNormal) >= 0f)
			{
				return false;
			}
			if (climbType == PlayerLocomotion.ClimbType.LADDER)
			{
				return true;
			}
			if (!player.PlayerLocomotion.IsGrounded || input.JumpButtonDown)
			{
				return true;
			}
			return false;
		}

		private void OnEnterClimbState(ushort previousStateId, ushort previousSubStateId)
		{
			locomotionStateMachine.EnterState(0);
			hasPlayedLadderClimbFinalAnimation = false;
			Player localPlayer = Player.LocalPlayer;
			localPlayer.PlayerLocomotion.Climb();
			climbLedgeSteering.FacingDirection = -1f * localPlayer.PlayerLocomotion.LatestClimbWallNormal;
			AddSteeringController(climbLedgeSteering, CLIMB_STATE_TOKEN, 1001);
			if (TryGetClimbAnimation(localPlayer, out var animation, out var loops))
			{
				if (loops)
				{
					PlayLoopingAnimation(animation);
				}
				else
				{
					PlayUninterruptableAnimation(animation, restartIfAlreadyPlaying: true);
				}
			}
		}

		private void OnUpdateClimbState()
		{
			Player localPlayer = Player.LocalPlayer;
			if (localPlayer.PlayerLocomotion.LatestClimbType == PlayerLocomotion.ClimbType.LADDER && !hasPlayedLadderClimbFinalAnimation && localPlayer.PlayerLocomotion.ClimbTimeRemaining <= ladderClimbFinalAnimationRemainingTime)
			{
				hasPlayedLadderClimbFinalAnimation = true;
				PlayUninterruptableAnimation(ladderClimbFinalAnimation, restartIfAlreadyPlaying: true);
			}
			if (!localPlayer.PlayerLocomotion.IsClimbing)
			{
				playerStateMachine.EnterState(2);
			}
		}

		private void OnExitClimbState(ushort nextStateId, ushort nextSubStateId)
		{
			RemoveSteeringController(CLIMB_STATE_TOKEN);
			locomotionStateMachine.EnterState(2);
		}

		private bool TryGetClimbAnimation(Player player, out IPlayerAnimationData animation, out bool loops)
		{
			animation = null;
			loops = false;
			switch (player.PlayerLocomotion.LatestClimbType)
			{
			case PlayerLocomotion.ClimbType.CLAMBER:
				switch (player.PlayerLocomotion.LatestClimbHeightType)
				{
				case PlayerLocomotion.ClimbHeightType.TALL:
					animation = highClamberAnimation;
					break;
				case PlayerLocomotion.ClimbHeightType.MEDIUM:
					animation = mediumClamberAnimation;
					break;
				case PlayerLocomotion.ClimbHeightType.SHORT:
					animation = lowClamberAnimation;
					break;
				}
				break;
			case PlayerLocomotion.ClimbType.MANTLE:
				switch (player.PlayerLocomotion.LatestClimbHeightType)
				{
				case PlayerLocomotion.ClimbHeightType.TALL:
					animation = highMantleAnimation;
					break;
				case PlayerLocomotion.ClimbHeightType.MEDIUM:
					animation = mediumMantleAnimation;
					break;
				case PlayerLocomotion.ClimbHeightType.VERY_SHORT:
				case PlayerLocomotion.ClimbHeightType.SHORT:
					animation = lowMantleAnimation;
					break;
				}
				break;
			case PlayerLocomotion.ClimbType.LADDER:
				animation = climbLadderAnimation;
				loops = true;
				break;
			}
			return animation != null;
		}

		private bool TryStartDodge(Player player, ScreenInputHandler input)
		{
			if (!dodgeEnabledFlag.HasTokens)
			{
				return false;
			}
			if (!player.PlayerWalking.CanDodge)
			{
				return false;
			}
			if (input.WalkAxis.sqrMagnitude < Mathf.Epsilon)
			{
				return false;
			}
			if (!input.JumpButtonDown)
			{
				return false;
			}
			return true;
		}

		private void OnEnterDodgeState(ushort previousStateId, ushort previousSubStateId)
		{
			locomotionStateMachine.EnterState(0);
