			OnGameplayCursorVisibilityRestrictionChange();
		}

		private bool TryStartAnyContextSensitiveAction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input, out ScreenContextSensitiveActionController newActiveController, out ScreensContextSensitiveActionRegion newActiveRegion)
		{
			newActiveController = null;
			newActiveRegion = null;
			nearestContextSensitiveRegion = GetNearestContextSensitiveRegion(player, camera, input);
			float num = 0f;
			if (nearestContextSensitiveRegion != null)
			{
				if (isAttemptingContextSensitiveAction)
				{
					float holdRequirement = 0f;
					if (nearestContextSensitiveRegion.ActionController == null || !nearestContextSensitiveRegion.ActionController.TryGetCustomStartButtonHoldRequirement(out holdRequirement))
					{
						holdRequirement = contextSensitiveActionHoldDuration;
					}
					num = ((!(holdRequirement <= Mathf.Epsilon)) ? Mathf.InverseLerp(contextSensitiveAttemptStartTime, contextSensitiveAttemptStartTime + holdRequirement, UnityEngine.Time.time) : 1f);
				}
				hud.EnableInteractDialog(contextSensitiveActionTooltipViewportPosition, input.PickupButtonSprite, nearestContextSensitiveRegion.ActionController.TooltipLabel, num);
			}
			if (!isAttemptingContextSensitiveAction && nearestContextSensitiveRegion != null && input.PickupButtonDown)
			{
				isAttemptingContextSensitiveAction = true;
				contextSensitiveAttemptRegion = nearestContextSensitiveRegion;
				contextSensitiveAttemptStartTime = UnityEngine.Time.time;
			}
			if (!isAttemptingContextSensitiveAction)
			{
				return false;
			}
			if (contextSensitiveAttemptRegion == null || contextSensitiveAttemptRegion != nearestContextSensitiveRegion || !input.PickupButtonPressed || input.PickupButtonUp)
			{
				isAttemptingContextSensitiveAction = false;
				contextSensitiveAttemptRegion = null;
				return false;
			}
			if (num < 1f)
			{
				return false;
			}
			newActiveRegion = contextSensitiveAttemptRegion;
			newActiveController = contextSensitiveAttemptRegion.ActionController;
			isAttemptingContextSensitiveAction = false;
			contextSensitiveAttemptRegion = null;
			return true;
		}

		private void StopCurrentContextSensitiveAction(Player player, Camera camera, ScreenHUD hud)
		{
			if (currentContextSensitiveController != null)
			{
				currentContextSensitiveController.OnStop(this, player, currentContextSensitiveRegion, camera, hud);
			}
			currentContextSensitiveController = null;
			currentContextSensitiveRegion = null;
		}

		private ScreensContextSensitiveActionRegion GetNearestContextSensitiveRegion(Player player, Camera camera, ScreenInputHandler input)
		{
			if (isAttemptingToolDrop || isAttemptingToolPickup || isAttemptingPortalInteraction || isAttemptingFavoriteToolPickup)
			{
				return null;
			}
			for (int i = 0; i < ScreensContextSensitiveActionRegion.LocalPlayerOverlappingRegions.Count; i++)
			{
				ScreensContextSensitiveActionRegion screensContextSensitiveActionRegion = ScreensContextSensitiveActionRegion.LocalPlayerOverlappingRegions[i];
				if (screensContextSensitiveActionRegion.ActionController != null && screensContextSensitiveActionRegion.ActionController.CanStart(this, player, screensContextSensitiveActionRegion, camera, input))
				{
					return ScreensContextSensitiveActionRegion.LocalPlayerOverlappingRegions[i];
				}
			}
			return null;
		}

