		private void OnUpdateSocialActionState()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			ScreenSocialActionController newActiveController = null;
			if (TryStartDifferentSocialAction(localPlayer, screenModeCamera, screenModeHUD, inputHandler, currentSocialActionController, out newActiveController))
			{
				StopCurrentSocialActionController(localPlayer);
				currentSocialActionController = newActiveController;
				StartCurrentSocialActionController(localPlayer, screenModeCamera, screenModeHUD, inputHandler);
			}
			if (!UpdateCurrentSocialActionController(localPlayer, screenModeCamera, screenModeHUD, inputHandler))
			{
				playerStateMachine.EnterState(2);
