		private bool TryStartAnySocialAction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input, out ScreenSocialActionController newActiveController)
		{
			newActiveController = null;
			for (int i = 0; i < socialActionControllers.Length; i++)
			{
				ScreenSocialActionController screenSocialActionController = socialActionControllers[i];
				screenSocialActionController.TryDisplayTooltip(this, player, camera, hud, input);
				if (screenSocialActionController.CanStart(this, player, input))
				{
					newActiveController = screenSocialActionController;
					return true;
				}
			}
			return false;
		}

		private bool TryStartDifferentSocialAction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input, ScreenSocialActionController currentController, out ScreenSocialActionController newActiveController)
		{
			newActiveController = null;
			if (currentController != null && currentController.IsBlocking)
			{
				return false;
			}
			for (int i = 0; i < socialActionControllers.Length; i++)
			{
				ScreenSocialActionController screenSocialActionController = socialActionControllers[i];
				if (!(screenSocialActionController == currentController))
				{
					screenSocialActionController.TryDisplayTooltip(this, player, camera, hud, input);
					if (screenSocialActionController.CanStart(this, player, input))
					{
						newActiveController = screenSocialActionController;
						return true;
					}
				}
			}
			return false;
		}

		private void StartCurrentSocialActionController(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
