		private void OnUpdateStandLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(6);
				return;
			}
			if (TryStartSprint(localPlayer, input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(4);
				return;
			}
			if (IsCrouchStartRequested(input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(3);
				return;
			}
			if (GetPlayerMoveVelocity(localPlayer).sqrMagnitude >= 0.01f)
			{
				locomotionStateMachine.EnterState(2);
				return;
			}
			bool allowedToPlayStandFidget = UnityEngine.Time.time - lastIdleStartTime >= minInactiveFidgetDuration;
			IPlayerAnimationData animation = null;
			bool loops = true;
			GetStandAnimation(out animation, allowedToPlayStandFidget, out loops);
			SetLocomotionAnimation(animation, loops);
		}

		private void GetStandAnimation(out IPlayerAnimationData animation, bool allowedToPlayStandFidget, out bool loops)
		{
			if (_overriddenStandAnimation != null)
			{
				loops = true;
				animation = _overriddenStandAnimation;
			}
			else if (allowedToPlayStandFidget)
			{
				loops = false;
				animation = GetStandFidgetAnimation();
			}
			else
			{
				loops = false;
				animation = GetWalkFidgetAnimation();
			}
		}

		private void OnUpdateWalkLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(6);
				return;
			}
			if (TryStartSprint(localPlayer, input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(4);
				return;
			}
			if (IsCrouchStartRequested(input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(3);
				return;
			}
			if (GetPlayerMoveVelocity(localPlayer).sqrMagnitude <= Mathf.Epsilon)
			{
				locomotionStateMachine.EnterState(1);
				return;
			}
			IPlayerAnimationData animation = null;
			bool loops = true;
			GetWalkAnimation(localPlayer, out animation, out loops);
			SetLocomotionAnimation(animation, loops);
		}

		private void GetWalkAnimation(Player player, out IPlayerAnimationData animation, out bool loops)
		{
			animation = null;
			loops = true;
			if (_overriddenWalkAnimation != null)
			{
				animation = _overriddenWalkAnimation;
				return;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			bool flag = heldTool != null && heldTool.ScreenIdleAnimation.AnimationAsset != null;
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			bool flag2 = heldTool2 != null && heldTool2.ScreenIdleAnimation.AnimationAsset != null;
			if (flag && flag2)
			{
				animation = idleMaskedAnimation;
				return;
			}
			if (flag)
			{
				animation = heldTool.ScreenIdleAnimation;
				return;
			}
			if (flag2)
			{
				animation = heldTool2.ScreenIdleAnimation;
				return;
			}
			if (heldTool != null)
			{
				animation = IdleHeldToolDefaultAnimation;
				return;
			}
			loops = false;
			animation = GetWalkFidgetAnimation();
		}

		private bool TryStartSprint(Player player, ScreenInputHandler input, bool allowSloppyStart)
		{
			if (player.PlayerWalking.IsSprinting)
			{
				return true;
			}
			if (!player.PlayerWalking.CanSprint)
			{
				return false;
			}
			if (IsSprintStartRequestedInternal(input, allowSloppyStart))
			{
				player.PlayerWalking.RequestSprint();
			}
			return false;
		}

		private bool IsSprintStartRequestedInternal(ScreenInputHandler input, bool allowSloppyStart)
		{
			if (input.UsingKeyboardMouse)
			{
				if (allowSloppyStart)
				{
					return input.SprintButtonPressed;
				}
				return input.SprintButtonDown;
			}
			return input.SprintButtonDown;
		}

		private bool IsSprintStopRequested(Player player, ScreenInputHandler input)
		{
			if (!IsSprinting(player))
			{
				return true;
			}
			if (!player.PlayerWalking.CanSprint)
			{
				return true;
			}
			if (input.UsingKeyboardMouse)
			{
				return !input.SprintButtonPressed;
			}
			return input.SprintButtonDown;
		}

		private void OnEnterSprintLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			ActiveGenreController.OnSprintStart();
		}

		private void OnUpdateSprintLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(8);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(9);
				return;
			}
			if (IsCrouchStartRequested(input, allowSloppyStart: false))
			{
				locomotionStateMachine.EnterState(3);
				return;
			}
			if (IsSprintStopRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(2);
				return;
			}
			IPlayerAnimationData animation = null;
			bool loops = true;
			GetSprintAnimation(localPlayer, out animation, out loops);
			SetLocomotionAnimation(animation, loops);
		}

		private void OnExitSprintLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 8 && nextStateId != 9)
			{
				RemoveSprintCameraSettings();
				Player localPlayer = Player.LocalPlayer;
				localPlayer.PlayerWalking.StopSprint();
			}
		}

		private void GetSprintAnimation(Player player, out IPlayerAnimationData animation, out bool loops)
		{
			loops = true;
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (heldTool != null && heldTool.ScreenSprintAnimation.AnimationAsset != null)
			{
				animation = heldTool.ScreenSprintAnimation;
				return;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (heldTool2 != null && heldTool2.ScreenSprintAnimation.AnimationAsset != null)
			{
				animation = heldTool2.ScreenSprintAnimation;
			}
			else
			{
				animation = sprintDefaultAnimation;
			}
		}

		private void RemoveSprintCameraSettings()
		{
			RemoveCameraSettings(SPRINT_TOKEN);
		}

		private bool IsCrouchStartRequested(ScreenInputHandler input, bool allowSloppyStart)
		{
			if (crouchRestrictedFlag.HasTokens)
			{
				return false;
			}
			if (input.UsingKeyboardMouse)
			{
				if (allowSloppyStart)
				{
					return input.CrouchButtonPressed;
				}
				return input.CrouchButtonDown;
			}
			return input.CrouchButtonDown;
		}

		private bool IsCrouchStopRequested(ScreenInputHandler input)
		{
			if (crouchRestrictedFlag.HasTokens)
			{
				return true;
			}
			if (input.UsingKeyboardMouse)
			{
				return !input.CrouchButtonPressed;
			}
			return input.CrouchButtonDown;
		}

		private void OnEnterCrouchLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			targetCrouchHeightReduction = crouchMaxHeightReduction;
			crouchUpdateTime = crouchSmoothTime;
			targetCameraHeightReduction = crouchMaxHeightReduction;
			cameraHeightUpdateTime = crouchSmoothTime;
			Player localPlayer = Player.LocalPlayer;
			if (previousStateId == 4 || previousStateId == 9 || previousStateId == 8 || previousStateId == 9)
			{
				localPlayer.PlayerWalking.StartCrouchSlide();
			}
			else
			{
				localPlayer.PlayerWalking.StartCrouch();
			}
		}

		private void OnUpdateCrouchLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(6);
				return;
			}
			if (TryStartSprint(localPlayer, input, allowSloppyStart: false))
			{
				locomotionStateMachine.EnterState(4);
				return;
			}
			if (IsCrouchStopRequested(input))
			{
				locomotionStateMachine.EnterState(2);
				return;
			}
			GetCrouchAnimation(out var animation, out var loops);
			SetLocomotionAnimation(animation, loops);
		}

		private void OnExitCrouchLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			targetCrouchHeightReduction = 0f;
			targetCameraHeightReduction = 0f;
			Player localPlayer = Player.LocalPlayer;
			localPlayer.PlayerWalking.StopCrouch();
		}

		private void GetCrouchAnimation(out IPlayerAnimationData animation, out bool loops)
		{
			loops = true;
			if (_overriddenCrouchAnimation != null)
			{
				animation = _overriddenCrouchAnimation;
			}
			else
			{
				animation = crouchDefaultAnimation;
			}
		}

		private bool IsJumpRequested(Player player, ScreenInputHandler input)
		{
			return input.JumpButtonDown && player.PlayerWalking.CanJump;
		}

		private void OnEnterJumpLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			uninterruptableAnimation = null;
			GetJumpAnimation(localPlayer, out var animation, out var loops);
			SetLocomotionAnimation(animation, loops);
			localPlayer.PlayerWalking.RequestJump();
		}

		private void OnUpdateJumpLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler screenInputHandler = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
			}
			else if (localPlayer.PlayerLocomotion.IsGrounded)
			{
				locomotionStateMachine.EnterState(7);
			}
			else if (localPlayer.PlayerWalking.IsJumping && screenInputHandler.JumpButtonUp)
			{
				localPlayer.PlayerWalking.CutoffJump();
			}
		}

		private void OnUpdateJumpSprintingLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler screenInputHandler = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (localPlayer.PlayerLocomotion.IsGrounded)
			{
				locomotionStateMachine.EnterState(10);
				return;
			}
			if (localPlayer.PlayerWalking.IsJumping && screenInputHandler.JumpButtonUp)
			{
				localPlayer.PlayerWalking.CutoffJump();
			}
			if (IsSprintStopRequested(localPlayer, screenInputHandler))
			{
				locomotionStateMachine.EnterState(5);
			}
		}

		private void OnExitJumpSprintingLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 10)
			{
				RemoveSprintCameraSettings();
				Player localPlayer = Player.LocalPlayer;
				localPlayer.PlayerWalking.StopSprint();
			}
		}

		private void GetJumpAnimation(Player player, out IPlayerAnimationData animation, out bool loops)
		{
			loops = true;
			if (_overriddenJumpAnimation != null)
			{
				animation = _overriddenJumpAnimation;
				return;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			if (heldTool != null && heldTool.ScreenJumpAnimation.AnimationAsset != null)
			{
				animation = heldTool.ScreenJumpAnimation;
				return;
			}
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (heldTool2 != null && heldTool2.ScreenJumpAnimation.AnimationAsset != null)
			{
				animation = heldTool2.ScreenJumpAnimation;
			}
			else
			{
				animation = jumpAnimation;
			}
		}

		private bool IsFalling(Player player)
		{
			return !player.PlayerLocomotion.IsGrounded && player.PlayerLocomotion.MovementIsInitialized;
		}

		private void OnEnterFallLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			SetLocomotionAnimation(fallAnimation, animationLoops: true);
		}

		private void OnUpdateFallLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
			}
			else if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
			}
			else if (localPlayer.PlayerLocomotion.IsGrounded)
			{
				locomotionStateMachine.EnterState(7);
			}
		}

		private void OnUpdateFallSprintingLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
			}
			else if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(8);
			}
			else if (IsSprintStopRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(6);
			}
			else if (localPlayer.PlayerLocomotion.IsGrounded)
			{
