		private void OnEnterLandLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			lastFallLandTime = UnityEngine.Time.time;
			crouchUpdateTime = 0f;
			targetCameraHeightReduction = 0f;
		}

		private void OnUpdateLandLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(6);
				return;
			}
			if (TryStartSprint(localPlayer, input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(4);
				return;
			}
			if (IsCrouchStartRequested(input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(3);
				return;
			}
			GetWalkAnimation(localPlayer, out var animation, out var loops);
			SetLocomotionAnimation(animation, loops);
			float num = UnityEngine.Time.time - lastFallLandTime;
			float landCrouchBlendParameter = GetLandCrouchBlendParameter(num, fallLandDuration);
			targetCrouchHeightReduction = Mathf.Lerp(landMaxCrouchHeightReduction, 0f, landCrouchBlendParameter);
			if (num >= fallLandDuration)
			{
				locomotionStateMachine.EnterState(2);
			}
		}

		private void OnUpdateLandSprintingLocomotionState()
		{
			Player localPlayer = Player.LocalPlayer;
			ScreenInputHandler input = inputHandler;
			if (IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(11);
				return;
			}
			if (IsJumpRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(5);
				return;
			}
			if (IsFalling(localPlayer))
			{
				locomotionStateMachine.EnterState(6);
				return;
			}
			if (IsCrouchStartRequested(input, allowSloppyStart: true))
			{
				locomotionStateMachine.EnterState(3);
				return;
			}
			if (IsSprintStopRequested(localPlayer, input))
			{
				locomotionStateMachine.EnterState(2);
				return;
			}
			IPlayerAnimationData animation = null;
			bool loops = true;
			GetSprintAnimation(localPlayer, out animation, out loops);
			SetLocomotionAnimation(animation, loops);
			float num = UnityEngine.Time.time - lastFallLandTime;
			float landCrouchBlendParameter = GetLandCrouchBlendParameter(num, fallLandSprintingDuration);
			targetCrouchHeightReduction = Mathf.Lerp(landSprintMaxCrouchHeightReduction, 0f, landCrouchBlendParameter);
			if (num >= fallLandSprintingDuration)
			{
				locomotionStateMachine.EnterState(4);
			}
		}

		private void OnExitLandLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			crouchUpdateTime = crouchSmoothTime;
			targetCrouchHeightReduction = 0f;
		}

		private void OnExitLandSprintingLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			crouchUpdateTime = crouchSmoothTime;
			targetCrouchHeightReduction = 0f;
			if (nextStateId != 4)
			{
				RemoveSprintCameraSettings();
				Player localPlayer = Player.LocalPlayer;
				localPlayer.PlayerWalking.StopSprint();
			}
		}

		private float GetLandCrouchBlendParameter(float timeElapsed, float maxDuration)
		{
			float time = Mathf.InverseLerp(0f, maxDuration, timeElapsed);
			return landBlendCurve.Evaluate(time);
		}

		private void OnEnterSittingInSeatLocomotionState(ushort previousStateId, ushort previousSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			localPlayer.PlayerLocomotion.AddMovementCollisionRestriction(this);
			seatedSteering.SeatTransform = TeleportationPortal.LocalPlayerSeat.SeatTransform;
			AddSteeringController(seatedSteering, SEATED_TOKEN, 10000000);
		}

		private void OnUpdateSittingInSeatLocomotionState()
		{
			ScreenInputHandler input = inputHandler;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			Player localPlayer = Player.LocalPlayer;
			if (playerStateMachine.CurrentStateId != 2)
			{
				isAttemptingToExitSeat = false;
			}
			else if (UpdateExitSeat(screenModeHUD, input))
			{
				isAttemptingToExitSeat = false;
				TeleportationPortal.LocalPlayerSeat.DisembarkSeat(localPlayer);
			}
			if (!IsSittingInSeat())
			{
				locomotionStateMachine.EnterState(1);
				return;
			}
			bool allowedToPlayStandFidget = UnityEngine.Time.time - lastIdleStartTime >= minInactiveFidgetDuration;
			GetStandAnimation(out var animation, allowedToPlayStandFidget, out var loops);
			SetLocomotionAnimation(animation, loops);
		}

		private void OnExitSittingInSeatLocomotionState(ushort nextStateId, ushort nextSubStateId)
		{
			Player localPlayer = Player.LocalPlayer;
			if (localPlayer != null)
			{
				localPlayer.PlayerLocomotion.RemoveMovementCollisionRestriction(this);
			}
			RemoveSteeringController(SEATED_TOKEN);
		}

		private bool IsSittingInSeat()
		{
			return TeleportationPortal.LocalPlayerSeat != null;
		}

		private bool UpdateExitSeat(ScreenHUD hud, ScreenInputHandler input)
		{
			if (!isAttemptingToExitSeat && input.DropButtonDown)
			{
				isAttemptingToExitSeat = true;
				exitSeatAttemptStartTime = UnityEngine.Time.time;
			}
			if (isAttemptingToExitSeat && (input.DropButtonUp || !input.DropButtonPressed))
			{
				isAttemptingToExitSeat = false;
			}
			float num = ((!isAttemptingToExitSeat) ? 0f : Mathf.InverseLerp(exitSeatAttemptStartTime, exitSeatAttemptStartTime + portalUseDefaultHoldDuration, UnityEngine.Time.time));
			hud.AddToolActionDialog(input.DropToolButtonSprite, "Get Up", num);
			return num >= 1f;
		}

		private void InitializePlayerOnEnterMode(Player player, Camera camera)
		{
			toolEquipFirstSlotIndex = 0;
			player.LeftHand.HandConnectedState = PlayerHand.ConnectedState.CONNECTED_AND_TRACKING;
			player.RightHand.HandConnectedState = PlayerHand.ConnectedState.CONNECTED_AND_TRACKING;
			player.Head.RigidbodyEx.targetLocalPosition = DEFAULT_PLAYER_HEAD_POSITION;
			player.Head.RigidbodyEx.targetLocalRotation = DEFAULT_PLAYER_HEAD_ROTATION;
			player.LeftHand.RigidbodyEx.targetLocalPosition = DEFAULT_PLAYER_LEFT_HAND_POSITION;
			player.LeftHand.RigidbodyEx.targetLocalRotation = DEFAULT_PLAYER_HAND_ROTATION;
			player.RightHand.RigidbodyEx.targetLocalPosition = DEFAULT_PLAYER_RIGHT_HAND_POSITION;
			player.RightHand.RigidbodyEx.targetLocalRotation = DEFAULT_PLAYER_HAND_ROTATION;
			CameraShake.RegisterCamera(camera);
			CameraShake.SetMaxLinearOffsets(camera, cameraShakeMaxLinearDisplacement);
			CameraShake.SetMaxAngularOffsets(camera, cameraShakeMaxAngularDisplacement);
			player.LeftHand.PickupToolEvent += OnHandPickupTool;
			player.LeftHand.ReleaseToolEvent += OnHandReleaseTool;
			player.RightHand.PickupToolEvent += OnHandPickupTool;
			player.RightHand.ReleaseToolEvent += OnHandReleaseTool;
			player.DynamicDominantHandEnabled = false;
			player.ToolEquipSlots.AutomaticallyEquipToolOnDrop = false;
			player.ToolEquipSlots.HotSwapToolOnDrop = false;
			player.PlayerUI.WatchMenuProjector.WatchGazeOpeningEnabled = false;
			player.PlayerChaperone.RoomCenterVisualEnabled = false;
			player.PlayerLocomotion.SupportsRoomScaleMovement = false;
			player.PlayerLocomotion.CanCollideWithPlayers = false;
			player.Backpack.BackpackToolEnabledChange += OnBackpackToolEnableChange;
		}

		private void CleanupLocalPlayer()
		{
			Player localPlayer = Player.LocalPlayer;
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			QuickTimeEmoteController.Cleanup();
			StopCurrentToolAction(localPlayer, screenModeCamera, screenModeHUD);
			StopCurrentMenu(localPlayer, screenModeCamera, screenModeHUD);
			StopCurrentSocialActionController(localPlayer);
			StopCustomGameBehavior(localPlayer);
			StopCurrentContextSensitiveAction(localPlayer, screenModeCamera, screenModeHUD);
			RemoveGenreType(ACTIVE_TOOL_CONTROL_TOKEN);
			RemoveGenreType(this);
			if (screenModeCamera != null)
			{
				CameraShake.UnregisterCamera(screenModeCamera);
			}
			if (!(localPlayer == null))
			{
				if (localPlayer.LeftHand != null)
				{
					localPlayer.LeftHand.PickupToolEvent -= OnHandPickupTool;
					localPlayer.LeftHand.ReleaseToolEvent -= OnHandReleaseTool;
				}
				if (localPlayer.RightHand != null)
				{
					localPlayer.RightHand.PickupToolEvent -= OnHandPickupTool;
					localPlayer.RightHand.ReleaseToolEvent -= OnHandReleaseTool;
				}
				if (localPlayer.Backpack != null)
				{
					localPlayer.Backpack.BackpackToolEnabledChange -= OnBackpackToolEnableChange;
				}
			}
		}

