		private void ApplyAnimationFrame(PlayerAnimationFrame frame, float rootMotionDisplacement)
		{
			Player localPlayer = Player.LocalPlayer;
			if (!(localPlayer == null))
			{
				Vector3 right = localPlayer.TrackingSpace.RigidbodyEx.TargetTransform.right;
				Vector3 vector = UpdateCrouchHeightReduction();
				localPlayer.PlayerLocomotion.CrouchHeightOffset = crouchHeightReduction;
				RigidbodyEx rigidbodyEx = localPlayer.Head.RigidbodyEx;
				rigidbodyEx.targetLocalPosition = frame.Head.Position + vector;
				rigidbodyEx.targetLocalRotation = frame.Head.Rotation;
				rigidbodyEx.TargetTransform.Rotate(right, headGazePitch, Space.World);
				rigidbodyEx.TargetTransform.Rotate(Vector3.up, headGazeYaw, Space.World);
				RigidbodyEx rigidbodyEx2 = localPlayer.LeftHand.RigidbodyEx;
				rigidbodyEx2.targetLocalPosition = frame.LeftHand.Position + vector;
				rigidbodyEx2.targetLocalRotation = frame.LeftHand.Rotation;
				rigidbodyEx2.TargetTransform.RotateAround(rigidbodyEx.targetPosition, right, handGazePitch);
				RigidbodyEx rigidbodyEx3 = localPlayer.RightHand.RigidbodyEx;
				rigidbodyEx3.targetLocalPosition = frame.RightHand.Position + vector;
				rigidbodyEx3.targetLocalRotation = frame.RightHand.Rotation;
				rigidbodyEx3.TargetTransform.RotateAround(rigidbodyEx.targetPosition, right, handGazePitch);
				localPlayer.LeftHand.OpenClosedAxis = frame.LeftHandTrigger;
				localPlayer.RightHand.OpenClosedAxis = frame.RightHandTrigger;
				if (rootMotionDisplacement != 0f)
				{
					Vector3 forward = localPlayer.TrackingSpace.RigidbodyEx.TargetTransform.forward;
					localPlayer.PlayerLocomotion.Move(rootMotionDisplacement * forward / UnityEngine.Time.deltaTime);
				}
			}
		}

		private void ProcessAnimationEvents(Player player, Camera camera, Vector3 leftHandVelocity, Vector3 rightHandVelocity, List<PlayerAnimationEvent.AnimationEventType> animationEvents)
		{
			GameManager instance = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			for (int i = 0; i < animationEvents.Count; i++)
			{
				if (animationEvents[i] != PlayerAnimationEvent.AnimationEventType.NONE)
				{
					if (animationEvents[i] == PlayerAnimationEvent.AnimationEventType.DEFERRED_PICKUP_TOOL && deferredPickupTool != null)
					{
						PickupToolInternal(player, deferredPickupTool, deferredPickupToolInMainHand);
						deferredPickupTool = null;
					}
					if (currentActiveTool != null && currentToolActionController != null)
					{
						currentToolActionController.OnAnimationEvent(animationEvents[i], leftHandVelocity, rightHandVelocity, this, player, camera, currentActiveTool);
					}
					if (currentCustomGameBehaviorController != null)
					{
						currentCustomGameBehaviorController.OnAnimationEvent(animationEvents[i], this, player, instance);
					}
					if (currentSocialActionController != null)
					{
						currentSocialActionController.OnAnimationEvent(animationEvents[i], this, player);
					}
				}
			}
		}

