		{
			headGazeYaw = Mathf.SmoothDampAngle(headGazeYaw, targetYaw, ref headGazeYawVelocity, yawSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			headGazePitch = Mathf.SmoothDampAngle(headGazePitch, targetPitch, ref headGazePitchVelocity, pitchSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
		}

