				float y2 = Quaternion.LookRotation(targetForward, Vector3.up).eulerAngles.y;
				y = Mathf.SmoothDampAngle(y, y2, ref trackingSpaceRotationVelocity, smoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
				player.TrackingSpace.RigidbodyEx.targetRotation = Quaternion.Euler(0f, y, 0f);
			}
		}

		private void SetClamberRotation(Player player)
		{
