			{
				Vector3 normalized = Vector3.ProjectOnPlane(player.PlayerLocomotion.LatestClimbWallNormal, Vector3.up).normalized;
				RotatePlayer(player, -normalized, lockedCameraTrackingSpaceYawSmoothTime);
				ClearHeadGazeAngles();
				ClearHandGazeAngles();
			}
		}

		private PlayerWalking.DodgeDirectionType GetDodgeDirection(Player player, Camera camera, Vector2 inputWalkAxis)
		{
			GetWalkInputAxisWorldSpace(camera, inputWalkAxis, out var walkInputAxisWorldSpace, out var _);
			float num = Vector3.Angle(player.TrackingSpace.RigidbodyEx.TargetTransform.forward, walkInputAxisWorldSpace);
			if (num < 45f)
			{
				return PlayerWalking.DodgeDirectionType.FORWARD;
			}
			if (num > 135f)
			{
				return PlayerWalking.DodgeDirectionType.BACK;
			}
			if (Vector3.Dot(player.TrackingSpace.RigidbodyEx.TargetTransform.right, walkInputAxisWorldSpace) >= 0f)
			{
				return PlayerWalking.DodgeDirectionType.RIGHT;
			}
			return PlayerWalking.DodgeDirectionType.LEFT;
		}

		private void GetGazeTarget(Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeDirection, out float normalizedDistance)
		{
			ScreenPlayerSteeringController highestPriorityValue = steeringControllerMap.HighestPriorityValue;
			if (highestPriorityValue == null || !highestPriorityValue.TryGetGazeTarget(this, player, camera, out gazeTarget, out var gazeOrigin))
			{
				gazeTarget = Vector3.zero;
				gazeDirection = Vector3.zero;
				normalizedDistance = 0f;
				return;
			}
			gazeDirection = (gazeTarget - gazeOrigin).normalized;
			if (Physics.SphereCast(gazeOrigin, gazeTargetCollisionRadius, gazeDirection, out var hitInfo, maxGazeDistance, 362036736, QueryTriggerInteraction.Ignore))
			{
				normalizedDistance = Mathf.InverseLerp(0f, maxGazeDistance, hitInfo.distance);
				gazeTarget = gazeOrigin + gazeDirection * Mathf.Max(minGazeDistance, hitInfo.distance);
			}
			else
			{
				normalizedDistance = 1f;
				gazeTarget = gazeOrigin + gazeDirection * maxGazeDistance;
			}
		}

		private Vector3 UpdateCrouchHeightReduction()
		{
			if (crouchUpdateTime == 0f)
			{
				crouchHeightReduction = targetCrouchHeightReduction;
			}
			else
			{
				crouchHeightReduction = Mathf.SmoothDamp(crouchHeightReduction, targetCrouchHeightReduction, ref crouchHeightVelocity, crouchUpdateTime);
			}
			return -Vector3.up * crouchHeightReduction;
		}

		private Vector3 UpdateCameraHeightReduction()
		{
			if (cameraHeightUpdateTime == 0f)
			{
				cameraHeightReduction = targetCameraHeightReduction;
			}
			else
			{
				cameraHeightReduction = Mathf.SmoothDamp(cameraHeightReduction, targetCameraHeightReduction, ref cameraHeightVelocity, cameraHeightUpdateTime);
			}
			return -Vector3.up * cameraHeightReduction;
		}

		private void UpdateAFK(Player player, ScreenInputHandler input)
		{
			if (input.HasInputThisFrame || player.IsTalking)
			{
				lastInputTime = UnityEngine.Time.time;
			}
			float num = ((!VirtualKeyboardController.IsKeyboardOpen) ? minAfkDurationIdle : minAfkDurationKeyboardController);
			bool flag = !SkipUserAFKCheck && UnityEngine.Time.time - lastInputTime >= num;
			player.UpdateAFKStatus(!flag);
		}

		private void OnLocalPlayerRespawn()
		{
