		private IEnumerator<ISchedule> RunRespawnRoutine(Player player)
		{
			respawnCamera.LookDirection = GetPlayerForwardDirection(player);
			AddCameraController(respawnCamera, 0f, RESPAWN_TOKEN, 1000000);
			yield return Schedule.NextFrame;
			RemoveCameraController(RESPAWN_TOKEN);
		}

		private void OnHandPickupTool(PlayerHand hand, Tool tool)
		{
			Player thisPlayer = hand.ThisPlayer;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (tool.ScreenActionControllers != null)
			{
				for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
				{
					tool.ScreenActionControllers[i].OnToolPickup(this, thisPlayer, tool, screenModeHUD);
				}
			}
			UpdateAllMaskedAnimation(thisPlayer);
			if (ActiveGenreController != null)
			{
				ActiveGenreController.OnToolPickup();
			}
		}

