		private IEnumerator<ISchedule> RunHandReleaseTool(PlayerHand hand, Tool tool)
		{
			Player player = hand.ThisPlayer;
			ScreenHUD hud = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (tool.ScreenActionControllers != null)
			{
				for (int i = 0; i < tool.ScreenActionControllers.Length; i++)
				{
					tool.ScreenActionControllers[i].OnToolRelease(this, player, tool, hud);
				}
			}
			yield return Schedule.NextFrame;
			UpdateAllMaskedAnimation(player);
			if (ActiveGenreController != null)
			{
				ActiveGenreController.OnToolRelease();
			}
		}

		private void UpdateAllMaskedAnimation(Player player)
		{
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			PlayerHand offHand = GetOffHand(player);
			Tool heldTool2 = offHand.HeldTool;
			if (!(heldTool == null) && !(heldTool2 == null))
			{
				PlayerAnimationFrame.TransformType transformType = ((offHand.Type == PlayerHand.HandType.Left) ? PlayerAnimationFrame.TransformType.LEFT_HAND : PlayerAnimationFrame.TransformType.RIGHT_HAND);
				if (heldTool.ScreenIdleAnimation.AnimationAsset != null && heldTool2.ScreenIdleAnimation.AnimationAsset != null)
				{
					UpdateMaskedAnimation(idleMaskedAnimation, heldTool.ScreenIdleAnimation, heldTool2.ScreenIdleAnimation, transformType);
				}
			}
		}

		private void UpdateMaskedAnimation(MaskedPlayerAnimation maskedAnimation, IPlayerAnimationData baseAnimation, IPlayerAnimationData layeredAnimation, PlayerAnimationFrame.TransformType transformType)
		{
			maskedAnimation.ClearLayeredAnimations();
			maskedAnimation.SetBaseAnimation(baseAnimation);
			maskedAnimation.AddLayeredAnimation(layeredAnimation, transformType);
		}

		private bool PickupToolInternal(Player player, Tool tool, bool useMainHand)
		{
			PlayerHand playerHand = ((!useMainHand) ? GetOffHand(player) : GetMainHand(player));
			if (playerHand != null && playerHand.HeldTool == null && tool != null && !tool.IsHeldByPlayer)
			{
				return playerHand.TryPickupTool(tool, inPhysicalPickupRange: true, forceSnapPosition: true);
			}
			return false;
		}

		private void UpdateHoveredTool(Player player, ScreenHUD hud, Camera camera, ScreenInputHandler input)
		{
			PlayerHand offHand = GetOffHand(player);
			offHand.ClearHoveredTool();
			PlayerHand mainHand = GetMainHand(player);
			if (isAttemptingToolDrop || isAttemptingFavoriteToolPickup)
			{
				mainHand.ClearHoveredTool();
				return;
			}
			Tool closestTool = GetClosestTool(player, mainHand, camera);
			if (closestTool == null)
			{
				mainHand.ClearHoveredTool();
			}
			else
			{
				mainHand.SetHoveredTool(closestTool, inPhysicalPickupRange: true);
			}
		}

		private void UpdateToolDrop(Player player, ScreenHUD hud, ScreenInputHandler input)
		{
			if (input.DropButtonUp || !input.DropButtonPressed || isAttemptingFavoriteToolPickup || isAttemptingToExitSeat)
			{
				isAttemptingToolDrop = false;
			}
			PlayerHand mainHand = GetMainHand(player);
			PlayerHand offHand = GetOffHand(player);
			if (input.DropButtonDown && (mainHand.HeldTool != null || offHand.HeldTool != null))
			{
				isAttemptingToolDrop = true;
				toolDropAttemptStartTime = UnityEngine.Time.time;
			}
			if (isAttemptingToolDrop && UnityEngine.Time.time - toolDropAttemptStartTime >= toolDropDefaultHoldDuration)
			{
				isAttemptingToolDrop = false;
				if (mainHand.HeldTool != null)
				{
					TryDropMainHandTool(player, tryPickupFromEquipSlot: true);
				}
				if (offHand.HeldTool != null)
				{
					TryDropOffHandTool(player);
				}
			}
		}

		private void UpdateFavoriteToolPickup(Player player, ScreenHUD hud, GameManager gameManager, ScreenInputHandler input)
		{
			PlayerBackpackToolType playerBackpackToolType = player.Backpack.FavoriteToolType;
			if (!CanUseFavoriteToolType(player, gameManager, playerBackpackToolType))
			{
				playerBackpackToolType = GetFallbackFavoriteToolType(player, gameManager);
			}
			if (playerBackpackToolType == PlayerBackpackToolType.INVALID || favoriteToolRestrictedFlag.HasTokens || !CanUseFavoriteToolType(player, gameManager, playerBackpackToolType))
			{
				isAttemptingFavoriteToolPickup = false;
				return;
			}
			string text = string.Empty;
			switch (playerBackpackToolType)
			{
			case PlayerBackpackToolType.MAKER_PEN:
				text = "Use Maker Pen";
				break;
			case PlayerBackpackToolType.SHARE_CAM:
				text = "Use Share Cam";
				break;
			}
			PlayerHand mainHand = GetMainHand(player);
			if (mainHand.HeldTool == null)
			{
				hud.AddToolActionDialog(input.FavoriteToolSprite, text);
			}
			if (input.FavoriteToolButtonUp || !input.FavoriteToolButtonPressed)
			{
				isAttemptingFavoriteToolPickup = false;
				return;
			}
			if (input.FavoriteToolButtonDown)
			{
				isAttemptingFavoriteToolPickup = true;
				favoriteToolPickupAttemptStartTime = UnityEngine.Time.time;
			}
			if (!isAttemptingFavoriteToolPickup)
			{
				return;
			}
			float num = Mathf.InverseLerp(favoriteToolPickupAttemptStartTime, favoriteToolPickupAttemptStartTime + favoriteToolPickupHoldDuration, UnityEngine.Time.time);
			hud.EnableInteractDialog(favoriteToolPickupTooltipViewportPosition, input.FavoriteToolSprite, text, num);
			if (!(num >= 1f))
			{
				return;
			}
			isAttemptingFavoriteToolPickup = false;
			if (!player.Backpack.IsInUse(playerBackpackToolType))
			{
				player.Backpack.UseTool(playerBackpackToolType);
				return;
			}
			Tool backpackTool = player.Backpack.GetBackpackTool(playerBackpackToolType);
			if (backpackTool != null && backpackTool.IsValidPickup(player, backpackTool.transform.position, inPhysicalPickupRange: true))
			{
				SwapTool(backpackTool, player);
				TryPickupTool(player, backpackTool, playAnimation: true, useMainHand: true);
			}
		}

		private PlayerBackpackToolType GetFallbackFavoriteToolType(Player player, GameManager gameManager)
		{
			if (gameManager != null && gameManager.CurrentMode.IsSandboxOnly && !gameManager.IsGameRunning && CanUseFavoriteToolType(player, gameManager, PlayerBackpackToolType.MAKER_PEN))
			{
				return PlayerBackpackToolType.MAKER_PEN;
			}
			return PlayerBackpackToolType.SHARE_CAM;
		}

		private bool CanUseFavoriteToolType(Player player, GameManager gameManager, PlayerBackpackToolType toolType)
		{
			if (!player.CanInteractWithTools)
			{
				return false;
			}
			switch (toolType)
			{
			case PlayerBackpackToolType.INVALID:
				return false;
			case PlayerBackpackToolType.MAKER_PEN:
				if (!MakerPen.LocalPlayerCanUseCreationMode)
				{
					return false;
				}
				break;
			}
			return true;
		}

		private float GetToolDropProgress()
		{
			if (!isAttemptingToolDrop)
			{
				return 0f;
			}
			return Mathf.InverseLerp(toolDropAttemptStartTime, toolDropAttemptStartTime + toolDropDefaultHoldDuration, UnityEngine.Time.time);
		}

		private void UpdateToolPickup(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			PlayerHand mainHand = GetMainHand(player);
			PlayerHand offHand = GetOffHand(player);
			Tool hoveredTool = null;
			bool inPhysicalPickupRange = false;
			mainHand.GetHoveredTool(out hoveredTool, out inPhysicalPickupRange);
			Tool tool = hoveredTool;
			bool flag = toolPickupAttemptTool != null && toolPickupAttemptTool.IsValidPickup(player, toolPickupAttemptTool.transform.position, inPhysicalPickupRange: true);
			if (tool == null && flag)
			{
				tool = toolPickupAttemptTool;
			}
			float num = 0f;
			if (tool != null)
			{
				bool flag2 = false;
				float holdDuration = 0f;
				if (tool.IsScreensHoldToPickupRequired(out holdDuration))
				{
					num = holdDuration;
					flag2 = true;
				}
				else if (IsToolSwapRequired(tool, player, mainHand, offHand))
				{
					num = toolPickupDefaultHoldDuration;
					flag2 = true;
				}
				string tooltipString = null;
				if (!tool.TryGetPickupTooltipString(ref tooltipString))
				{
					tooltipString = ((!flag2) ? "Pickup" : "Swap");
				}
				Vector2 viewportPosition = (Vector2)camera.WorldToViewportPoint(tool.transform.position) + toolInteractDialogViewportOffset;
				hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, tooltipString, GetToolPickupProgress(num));
			}
			if (!isAttemptingToolPickup && hoveredTool != null && input.PickupButtonDown)
			{
				isAttemptingToolPickup = true;
				toolPickupAttemptTool = hoveredTool;
				toolPickupAttemptStartTime = UnityEngine.Time.time;
			}
			if (isAttemptingToolPickup)
			{
				if (input.PickupButtonUp || !input.PickupButtonPressed)
				{
					isAttemptingToolPickup = false;
					toolPickupAttemptTool = null;
				}
				else if (tool != null && UnityEngine.Time.time - toolPickupAttemptStartTime >= num)
				{
					SwapTool(tool, player);
					isAttemptingToolPickup = false;
					toolPickupAttemptTool = null;
				}
			}
		}

		private bool IsToolSwapRequired(Tool tool, Player player, PlayerHand mainHand, PlayerHand offHand)
		{
			if (tool.ScreenPickupType == Tool.ScreenToolPickupType.INTERACT_WITHOUT_HANDS)
			{
				return false;
			}
			bool flag = offHand.HeldTool != null && offHand.HeldTool != tool && !CanAnyEquipSlotStoreOffHandTool(player, offHand.HeldTool, offHand);
			if (tool.IsScreensOffHand)
			{
				return flag;
			}
			bool flag2 = mainHand.HeldTool != null && mainHand.HeldTool != tool && !CanAnyEquipSlotStoreMainHandTool(player, mainHand.HeldTool, mainHand);
			if (tool.ScreenPickupType == Tool.ScreenToolPickupType.MAIN_HAND_HELD)
			{
				return flag2;
			}
			if (tool.ScreenPickupType == Tool.ScreenToolPickupType.REQUIRES_BOTH_HANDS)
			{
				return flag2 || flag;
			}
			return false;
		}

		private void SwapTool(Tool tool, Player player)
		{
			Tool tool2 = null;
			Tool tool3 = null;
			PlayerToolEquipSlot equipSlotHoldingTool = player.ToolEquipSlots.GetEquipSlotHoldingTool(tool);
			PlayerHand mainHand = GetMainHand(player);
			PlayerHand offHand = GetOffHand(player);
			if (tool == null)
			{
				if (mainHand.HeldTool != null)
				{
					tool2 = mainHand.HeldTool;
					if (!TryDropMainHandTool(player))
					{
						return;
					}
				}
			}
			else if (tool.IsScreensOffHand || tool.ScreenPickupType == Tool.ScreenToolPickupType.INTERACT_WITHOUT_HANDS)
			{
				if (offHand.HeldTool != null)
				{
					tool3 = offHand.HeldTool;
					if (!TryDropOffHandTool(player))
					{
						return;
					}
				}
				TryPickupToolOffHand(player, tool, playAnimation: true);
			}
			else
			{
				if (tool.ScreenPickupType == Tool.ScreenToolPickupType.REQUIRES_BOTH_HANDS && offHand.HeldTool != null)
				{
					tool3 = offHand.HeldTool;
					if (!TryDropOffHandTool(player))
					{
						return;
					}
				}
				if (mainHand.HeldTool != null)
				{
					tool2 = mainHand.HeldTool;
					if (!TryDropMainHandTool(player))
					{
						return;
					}
				}
				TryPickupToolMainHand(player, tool, playAnimation: true);
			}
			if (tool2 != null)
			{
				EquipDroppedMainHandToolOnPickup(tool2, player, mainHand, equipSlotHoldingTool);
			}
			if (tool3 != null && tool3.ScreenPickupType == Tool.ScreenToolPickupType.PERMANENT_OFF_HAND_HELD)
			{
				EquipDroppedOffHandToolOnPickup(tool3, player, offHand);
			}
		}

		private void EquipDroppedMainHandToolOnPickup(Tool mainHandTool, Player player, PlayerHand mainHand, PlayerToolEquipSlot preferredEquipSlot)
		{
			if (!(preferredEquipSlot != null) || !player.ToolEquipSlots.TryEquipTool(mainHandTool, mainHand, preferredEquipSlot))
			{
				player.ToolEquipSlots.TryEquipToolMainHandOrVR(mainHandTool, mainHand, canDisplaceEquippedTool: false);
			}
		}

		private void EquipDroppedOffHandToolOnPickup(Tool offHandTool, Player player, PlayerHand offHand)
		{
			if (!player.ToolEquipSlots.TryEquipOffHandScreensOnly(offHandTool, offHand, canDisplaceEquippedTool: false))
			{
				player.ToolEquipSlots.TryEquipOffHandScreensOnly(offHandTool, offHand);
			}
		}

		private float GetToolPickupProgress(float holdDuration)
		{
			if (!isAttemptingToolPickup)
			{
				return 0f;
			}
			return Mathf.InverseLerp(toolPickupAttemptStartTime, toolPickupAttemptStartTime + holdDuration, UnityEngine.Time.time);
		}

		private Vector3 GetToolReleaseDirection(PlayerHand playerHand)
		{
			return (GazeTarget - playerHand.transform.position).normalized;
		}

		private void UpdateEquipSlotToolSwap(Player player, ScreenInputHandler input)
		{
			if ((input.SwitchToolButton1Down || input.SwitchToolButton2Down) && !(UnityEngine.Time.time - lastToolEquipSwapTime < minToolSwapPeriod) && TrySwapEquipSlotTool(player, toolEquipFirstSlotIndex, incrementIndex: true))
			{
				int totalCount = player.ToolEquipSlots.AllMainHandAndVRSlots.Length;
				toolEquipFirstSlotIndex = WraparoundIndex(toolEquipFirstSlotIndex, 1, totalCount, increment: true);
				lastToolEquipSwapTime = UnityEngine.Time.time;
			}
		}

		private bool TrySwapEquipSlotTool(Player player, int equipSlotIndex, bool incrementIndex)
		{
			PlayerToolEquipSlot nextSwapMainHandEquipSlot = GetNextSwapMainHandEquipSlot(player, equipSlotIndex, incrementIndex, equipSlotMustBeFull: true);
			if (nextSwapMainHandEquipSlot == null)
			{
				nextSwapMainHandEquipSlot = GetNextSwapMainHandEquipSlot(player, equipSlotIndex, incrementIndex, equipSlotMustBeFull: false);
			}
			if (nextSwapMainHandEquipSlot == null)
			{
				return false;
			}
			SwapTool(nextSwapMainHandEquipSlot.EquippedTool, player);
			PlayerToolEquipSlot nextSwapOffHandEquipSlot = GetNextSwapOffHandEquipSlot(player, equipSlotMustBeFull: true);
			if (nextSwapOffHandEquipSlot != null)
			{
				Tool currentMainTool = ((!(deferredPickupTool != null) || !deferredPickupToolInMainHand) ? GetMainHand(player).HeldTool : deferredPickupTool);
				if (CanPickupOffHand(currentMainTool, nextSwapOffHandEquipSlot.EquippedTool))
				{
					TryPickupToolOffHand(player, nextSwapOffHandEquipSlot.EquippedTool);
				}
			}
			return true;
		}

		private int WraparoundIndex(int baseIndex, int offset, int totalCount, bool increment)
		{
			float num = ((!increment) ? (-1f) : 1f);
			int num2 = baseIndex + (int)(num * (float)offset);
			num2 %= totalCount;
			if (num2 < 0)
			{
				num2 += totalCount;
			}
			return num2;
		}

		private PlayerToolEquipSlot GetNextSwapMainHandEquipSlot(Player player, int firstEquipSlotIndex, bool increment, bool equipSlotMustBeFull)
		{
			int num = player.ToolEquipSlots.AllMainHandAndVRSlots.Length;
			for (int i = 0; i < num; i++)
			{
				int num2 = WraparoundIndex(firstEquipSlotIndex, i, num, increment);
				PlayerToolEquipSlot playerToolEquipSlot = player.ToolEquipSlots.AllMainHandAndVRSlots[num2];
				if (IsValidSwapEquipSlot(playerToolEquipSlot, equipSlotMustBeFull))
				{
					return playerToolEquipSlot;
				}
			}
			return null;
		}

		private PlayerToolEquipSlot GetNextSwapOffHandEquipSlot(Player player, bool equipSlotMustBeFull)
		{
			if (IsValidSwapEquipSlot(player.ToolEquipSlots.OffHandScreensOnlyShoulderSlot, equipSlotMustBeFull))
			{
				return player.ToolEquipSlots.OffHandScreensOnlyShoulderSlot;
			}
			return null;
		}

		private bool IsValidSwapEquipSlot(PlayerToolEquipSlot equipSlot, bool equipSlotMustBeFull)
		{
			if (equipSlot == null)
			{
				return false;
			}
			if (!equipSlot.enabled)
			{
				return false;
			}
			if (equipSlot.EquippedTool == null && equipSlotMustBeFull)
			{
				return false;
			}
			if (equipSlot.EquippedTool != null && !equipSlot.EquippedTool.CanBePickedUp)
			{
				return false;
			}
			return true;
		}

		private bool TryStoreDroppedToolInEquipSlot(Player player, Tool tool, PlayerHand droppingHand)
		{
			if (tool == null)
			{
				return false;
			}
			if (TryStoreDroppedToolInEquipSlot(player, player.ToolEquipSlots.RightHipSlot, tool, droppingHand))
			{
				return true;
			}
			if (TryStoreDroppedToolInEquipSlot(player, player.ToolEquipSlots.LeftHipSlot, tool, droppingHand))
			{
				return true;
			}
			if (TryStoreDroppedToolInEquipSlot(player, player.ToolEquipSlots.ShoulderSlot, tool, droppingHand))
			{
				return true;
			}
			return false;
		}

		private bool TryStoreDroppedToolInEquipSlot(Player player, PlayerToolEquipSlot equipSlot, Tool tool, PlayerHand droppingHand)
		{
			if (!CanEquipSlotStoreTool(player, equipSlot, tool, droppingHand))
			{
				return false;
			}
			return droppingHand.ThisPlayer.ToolEquipSlots.TryEquipTool(tool, droppingHand, equipSlot);
		}

		private bool CanAnyEquipSlotStoreMainHandTool(Player player, Tool tool, PlayerHand droppingHand)
		{
			if (tool == null)
			{
				return false;
			}
			if (CanEquipSlotStoreTool(player, player.ToolEquipSlots.RightHipSlot, tool, droppingHand))
			{
				return true;
			}
			if (CanEquipSlotStoreTool(player, player.ToolEquipSlots.LeftHipSlot, tool, droppingHand))
			{
				return true;
			}
			if (CanEquipSlotStoreTool(player, player.ToolEquipSlots.ShoulderSlot, tool, droppingHand))
			{
				return true;
			}
			return false;
		}

		private bool CanAnyEquipSlotStoreOffHandTool(Player player, Tool tool, PlayerHand droppingHand)
		{
			if (tool == null)
			{
				return false;
			}
			if (tool.ScreenPickupType != Tool.ScreenToolPickupType.PERMANENT_OFF_HAND_HELD)
			{
				return false;
			}
			if (CanEquipSlotStoreTool(player, player.ToolEquipSlots.OffHandScreensOnlyShoulderSlot, tool, droppingHand))
			{
				return true;
			}
			return false;
		}

		private bool CanEquipSlotStoreTool(Player player, PlayerToolEquipSlot equipSlot, Tool tool, PlayerHand droppingHand)
		{
			if (equipSlot == null)
			{
				return false;
			}
			if (!equipSlot.enabled)
			{
				return false;
			}
			if (equipSlot.IsFull)
			{
				return false;
			}
			if (tool == null)
			{
				return false;
			}
			if (!player.ToolEquipSlots.CanEquipTool(tool, droppingHand, equipSlot))
			{
				return false;
			}
			return true;
		}

		private Tool GetClosestTool(Player player, PlayerHand playerHand, Camera camera)
		{
			if (deferredPickupTool != null)
			{
				return null;
			}
			if (!player.CanInteractWithTools)
			{
				return null;
			}
			PlayerHand mainHand = GetMainHand(player);
			Tool heldTool = mainHand.HeldTool;
			Tool closestToolAlongGaze = GetClosestToolAlongGaze(player, camera, playerHand, heldTool);
			if (closestToolAlongGaze != null)
			{
				return closestToolAlongGaze;
			}
			if (AnyCustomGameBehaviorPreventsToolPickup(player))
			{
				return null;
			}
			if (HoveredPortal != null || nearestContextSensitiveRegion != null)
			{
				return null;
			}
			return GetClosestToolInProximity(player, camera, playerHand, heldTool);
		}

		private Tool TryGetValidToolFromCollider(Player player, PlayerHand pickupHand, Tool currentMainTool, Collider hitCollider)
		{
			Tool colliderTool = hitCollider.GetColliderTool();
			if (colliderTool == null)
			{
				return null;
			}
			colliderTool = colliderTool.SelectForwardedTool(player, physicalPickupSelection: false, hitCollider);
			if (colliderTool.IsSubTool && colliderTool.ParentTool.IsHeld)
			{
				return null;
			}
			if (colliderTool.IsHeld)
			{
				return null;
			}
			if (!CanPickupOffHand(currentMainTool, colliderTool))
			{
				return null;
			}
			if (!colliderTool.IsValidPickup(player, pickupHand.transform.position, inPhysicalPickupRange: true))
			{
				return null;
			}
			return colliderTool;
		}

		private bool CanPickupOffHand(Tool currentMainTool, Tool offHandTool)
		{
			return !offHandTool.IsScreensOffHand || currentMainTool == null || currentMainTool.ScreenPickupType != Tool.ScreenToolPickupType.REQUIRES_BOTH_HANDS;
		}

		private Tool GetClosestToolAlongGaze(Player player, Camera camera, PlayerHand pickupHand, Tool heldMainTool)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			Ray ray = camera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
			float magnitude = Vector3.Project(player.Head.RigidbodyEx.targetPosition - camera.transform.position, camera.transform.forward).magnitude;
			float maxDistance = maxToolPickingDistance + magnitude;
			float num = 0.8f * magnitude;
			int num2 = Physics.SphereCastNonAlloc(ray, toolPickingRadius, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084288);
			Tool result = null;
			float num3 = float.MaxValue;
			bool flag = false;
			float num4 = float.MaxValue;
			for (int i = 0; i < num2; i++)
			{
				if (!(iMMEDIATE_RAYCAST_HITS[i].distance < num) && !(iMMEDIATE_RAYCAST_HITS[i].distance >= num3))
				{
					Tool tool = TryGetValidToolFromCollider(player, pickupHand, heldMainTool, iMMEDIATE_RAYCAST_HITS[i].collider);
					if (tool == null && CollisionDetection.CollidesWithMovementIgnoringMovementBlockers(iMMEDIATE_RAYCAST_HITS[i].collider))
					{
						flag = true;
						num4 = Mathf.Min(iMMEDIATE_RAYCAST_HITS[i].distance, num4);
					}
					else if ((!flag || !(iMMEDIATE_RAYCAST_HITS[i].distance > num4 + 0.1f)) && !(tool == null))
					{
						result = tool;
						num3 = iMMEDIATE_RAYCAST_HITS[i].distance;
					}
				}
			}
			return result;
		}

		private Tool GetClosestToolInProximity(Player player, Camera camera, PlayerHand pickupHand, Tool heldMainTool)
		{
			Vector3 targetPosition = player.TrackingSpace.RigidbodyEx.targetPosition;
			float num = Mathf.Max(0f, 1.7f - proximityToolSelectionRadius);
			Vector3 capsuleTopPosition = targetPosition + Vector3.up * num;
			Vector3 forward = player.TrackingSpace.RigidbodyEx.TargetTransform.forward;
			Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
			int capsuleColliderOverlaps = CollisionDetection.GetCapsuleColliderOverlaps(targetPosition, capsuleTopPosition, proximityToolSelectionRadius, 1267082240, null, iMMEDIATE_COLLIDER_HITS);
			Tool result = null;
			float num2 = proximityToolSelectionMaxAngleFromForward;
			for (int i = 0; i < capsuleColliderOverlaps; i++)
			{
				Tool tool = TryGetValidToolFromCollider(player, pickupHand, heldMainTool, iMMEDIATE_COLLIDER_HITS[i]);
				if (!(tool == null) && camera.IsInFovSimple(tool.transform.position))
				{
					Vector3 normalized = Vector3.ProjectOnPlane(tool.transform.position - targetPosition, Vector3.up).normalized;
					float num3 = Mathf.Abs(Vector3.Angle(forward, normalized));
					if (!(num3 > num2))
					{
						result = tool;
						num2 = num3;
					}
				}
			}
			return result;
		}

		private void UpdatePortalInteraction(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			PlayerHand mainHand = GetMainHand(player);
			TeleportationPortal teleportationPortal = null;
			mainHand.GetHoveredTool(out var hoveredTool, out var _);
			if (hoveredTool == null && !isAttemptingToolDrop && !TeleportationPortal.LocalPlayerSeat)
			{
				teleportationPortal = GetClosestTeleportationPortal(player, camera);
			}
			HoveredPortal = teleportationPortal;
			if (HoveredPortal != null)
			{
				HoveredPortal.RenderHighlight();
				Vector3 portalInteractDialogWorldSpacePosition = GetPortalInteractDialogWorldSpacePosition(player, teleportationPortal);
				Vector2 viewportPosition = camera.WorldToViewportPoint(portalInteractDialogWorldSpacePosition);
				string empty = string.Empty;
				hud.EnableInteractDialog(text: HoveredPortal.IsSeat ? "Sit" : ((!HoveredPortal.IsLadder) ? "Use" : "Climb"), viewportPosition: viewportPosition, sprite: inputHandler.PickupButtonSprite, progress: GetPortalInteractProgress(portalUseDefaultHoldDuration));
			}
			if (!isAttemptingPortalInteraction && HoveredPortal != null && input.PickupButtonDown && !isAttemptingToolDrop)
			{
				isAttemptingPortalInteraction = true;
				portalInteractAttemptedPortal = HoveredPortal;
				portalInteractionAttemptStartTime = UnityEngine.Time.time;
			}
			if (isAttemptingPortalInteraction)
			{
				if (portalInteractAttemptedPortal == null || portalInteractAttemptedPortal != HoveredPortal || !input.PickupButtonPressed || input.PickupButtonUp)
				{
					isAttemptingPortalInteraction = false;
					portalInteractAttemptedPortal = null;
				}
				else if (!(UnityEngine.Time.time - portalInteractionAttemptStartTime < portalUseDefaultHoldDuration))
				{
					HoveredPortal.Use(player);
					HoveredPortal = null;
					isAttemptingToolPickup = false;
					isAttemptingPortalInteraction = false;
					portalInteractAttemptedPortal = null;
				}
			}
		}

		private TeleportationPortal GetClosestTeleportationPortal(Player player, Camera camera)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			Ray ray = camera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
			float magnitude = Vector3.Project(player.Head.RigidbodyEx.targetPosition - camera.transform.position, camera.transform.forward).magnitude;
			float maxDistance = portalCheckDistance + magnitude;
			float num = magnitude * 0.8f;
			int num2 = Physics.SphereCastNonAlloc(ray, portalPickingRadius, iMMEDIATE_RAYCAST_HITS, maxDistance, 67128320, QueryTriggerInteraction.Collide);
			TeleportationPortal result = null;
			float num3 = float.MaxValue;
			bool flag = false;
			float num4 = float.MaxValue;
			for (int i = 0; i < num2; i++)
			{
				if (!(iMMEDIATE_RAYCAST_HITS[i].distance < num) && !(iMMEDIATE_RAYCAST_HITS[i].distance >= num3))
				{
					TeleportationPortal component = iMMEDIATE_RAYCAST_HITS[i].collider.gameObject.GetComponent<TeleportationPortal>();
					if (component == null && CollisionDetection.CollidesWithMovement(iMMEDIATE_RAYCAST_HITS[i].collider))
					{
						flag = true;
						num4 = Mathf.Min(iMMEDIATE_RAYCAST_HITS[i].distance, num4);
					}
					else if ((!flag || !(iMMEDIATE_RAYCAST_HITS[i].distance > num4 + 0.1f)) && !(component == null) && component.IsValid && !component.IsTeleportOnlyMode && !component.IsLadder)
					{
						result = component;
						num3 = iMMEDIATE_RAYCAST_HITS[i].distance;
					}
				}
			}
			return result;
		}

		private Vector3 GetPortalInteractDialogWorldSpacePosition(Player player, TeleportationPortal portal)
		{
			Vector3 result = Vector3.ProjectOnPlane(portal.transform.position, Vector3.up);
			result.y = player.TrackingSpace.RigidbodyEx.physicsPosition.y + portalInteractDialogTrackingSpaceHeight;
			return result;
		}

		private float GetPortalInteractProgress(float holdDuration)
		{
			if (!isAttemptingPortalInteraction)
			{
				return 0f;
			}
			return Mathf.InverseLerp(portalInteractionAttemptStartTime, portalInteractionAttemptStartTime + holdDuration, UnityEngine.Time.time);
		}

		private bool TryOpenAnyMenu(Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input, out ScreenMenuController newMenuController)
		{
			if (!MenuOpeningRestricted)
			{
				for (int i = 0; i < menuControllers.Length; i++)
				{
					if (menuControllers[i].menuController.CanOpen(this, player, camera, hud, input))
					{
						newMenuController = menuControllers[i].menuController;
						return true;
					}
					menuControllers[i].menuController.TryAddTooltip(this, player, camera, hud, input);
				}
			}
			newMenuController = null;
			return false;
		}

		public void ResetCursor(ScreenHUD hud)
		{
			if (!cursorVisibilityRestrictedFlag.HasTokens && gameplayCursorSettingsMap.ContainsValues)
			{
				CursorSystem.ShowCursor(hud);
				CursorSystem.SetCursorSettings(hud, gameplayCursorSettingsMap.HighestPriorityValue);
				CursorSystem.SnapToCenter(hud);
			}
			else
			{
				CursorSystem.HideCursor(hud);
			}
		}

		private void OnGameplayCursorVisibilityRestrictionChange()
		{
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			ResetCursor(screenModeHUD);
		}

		private void GetWalkInputAxisWorldSpace(Camera camera, Vector2 walkInputAxisInputSpace, out Vector3 walkInputAxisWorldSpace, out float walkInputMagnitude)
		{
			walkInputMagnitude = walkInputAxisInputSpace.magnitude;
			Vector3 normalized = Vector3.ProjectOnPlane(camera.transform.forward, Vector3.up).normalized;
			Vector3 normalized2 = Vector3.ProjectOnPlane(camera.transform.right, Vector3.up).normalized;
			walkInputAxisWorldSpace = (walkInputAxisInputSpace.x * normalized2 + walkInputAxisInputSpace.y * normalized).normalized;
		}
	}
