	public class ScreenPlayerEmoteSytem
	{
		private ScreenPlayerEmote queuedEmote;

		public bool HasQueuedEmote => queuedEmote != null;

		public void QueueEmote(ScreenPlayerEmote emote)
		{
			if (emote != null)
			{
				queuedEmote = emote;
			}
		}

		public bool DequeueEmote(out IPlayerAnimationData emoteAnimation, out PlayerFacialAnimator.Expression facialExpression)
		{
			if (queuedEmote == null)
			{
				emoteAnimation = null;
				facialExpression = PlayerFacialAnimator.Expression.NONE;
				return false;
			}
			if (queuedEmote.AnimationVariants != null && queuedEmote.AnimationVariants.Length > 0)
			{
				emoteAnimation = queuedEmote.AnimationVariants[UnityEngine.Random.Range(0, queuedEmote.AnimationVariants.Length)];
			}
			else
			{
				emoteAnimation = null;
			}
			facialExpression = queuedEmote.FacialExpression;
			queuedEmote = null;
			return true;
		}
	}
	[Serializable]
	public class ScreenPlayerFidgetAnimationController
	{
		[Header("Walking Weights")]
		[SerializeField]
		private int walkingLowEnergyWeight = 10;

		[SerializeField]
		private int walkingMediumEnergyWeight = 1;

		[Header("Stationary Weights")]
		[SerializeField]
		private int stationaryLowEnergyWeight = 5;

		[SerializeField]
		private int stationaryMediumEnergyWeight = 3;

		[SerializeField]
		private int stationaryHighEnergyWeight = 1;

		[NonSerialized]
		private LootTable<LootTable<PlayerAnimationAsset>> movingHierarchicalAnimationTable = new LootTable<LootTable<PlayerAnimationAsset>>();

		[NonSerialized]
		private LootTable<LootTable<PlayerAnimationAsset>> stationaryHierarchicalAnimationTable = new LootTable<LootTable<PlayerAnimationAsset>>();

		public void AddFidgetAnimationSet(PlayerFidgetAnimationSet fidgetAnimationSet)
		{
			LootTable<PlayerAnimationAsset> value = BuildAnimationLootTable(fidgetAnimationSet.LowEnergyFidgetAnimations);
			LootTable<PlayerAnimationAsset> value2 = BuildAnimationLootTable(fidgetAnimationSet.MediumEnergyFidgetAnimations);
			LootTable<PlayerAnimationAsset> value3 = BuildAnimationLootTable(fidgetAnimationSet.HighEnergyFidgetAnimations);
			movingHierarchicalAnimationTable.ClearAllLoot();
			movingHierarchicalAnimationTable.AddLoot(value, walkingLowEnergyWeight);
			movingHierarchicalAnimationTable.AddLoot(value2, walkingMediumEnergyWeight);
			stationaryHierarchicalAnimationTable.ClearAllLoot();
			stationaryHierarchicalAnimationTable.AddLoot(value, stationaryLowEnergyWeight);
			stationaryHierarchicalAnimationTable.AddLoot(value2, stationaryMediumEnergyWeight);
			stationaryHierarchicalAnimationTable.AddLoot(value3, stationaryHighEnergyWeight);
		}

		public PlayerAnimationAsset GetRandomFidgetAnimation(bool isMoving)
		{
			LootTable<PlayerAnimationAsset> lootTable = null;
			lootTable = ((!isMoving) ? stationaryHierarchicalAnimationTable.GetRandomLoot() : movingHierarchicalAnimationTable.GetRandomLoot());
			return lootTable.GetRandomLoot();
		}

		private LootTable<PlayerAnimationAsset> BuildAnimationLootTable(PlayerAnimationAsset[] animations)
		{
			LootTable<PlayerAnimationAsset> lootTable = null;
			if (animations != null)
			{
				lootTable = new LootTable<PlayerAnimationAsset>();
				for (int i = 0; i < animations.Length; i++)
				{
					lootTable.AddLoot(animations[i], 1);
				}
			}
			return lootTable;
		}
	}
