	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Genre Controllers/Action Adventure Genre Controller", fileName = "ActionAdventureScreenPlayerGenre")]
	public class ActionAdventureScreenPlayerGenre : ScreenPlayerGenreController
	{
		private enum State
		{
			INVALID,
			IDLE,
			LOCK_ON_DIRECTION,
			LOCK_ON_POI,
			AUTO_TARGET_NEARBY_POI,
			REACQUIRE_POI_LOCK_ON
		}

		[Header("Cameras")]
		[SerializeField]
		private ScreenPlayerCameraSettings defaultCameraSettings;

		[SerializeField]
		private OrbitScreenPlayerCamera defaultCamera;

		[SerializeField]
		private LookAtPointOfInterestScreenPlayerCamera lookAtPointOfInterestCamera;

		[SerializeField]
		private LookDirectionScreenPlayerCamera lookDirectionCamera;

		[SerializeField]
		private float defaultCameraBlendTime = 1f;

		[SerializeField]
		private float lockOnCameraBlendTime = 0.33f;

		[Header("Steering")]
		[SerializeField]
		private FaceVelocityScreenPlayerSteering defaultSteering;

		[SerializeField]
		private FacePointOfInterestScreenPlayerSteering facePointOfInterestSteering;

		[SerializeField]
		private FaceDirectionScreenPlayerSteering faceDirectionSteering;

		[Header("Point Of Interest Settings")]
		[SerializeField]
		private float pointOfInterestSearchRadius = 10f;

		[Header("POI Automatic Targeting")]
		[SerializeField]
		private float maxAutoTargetVisionConeAngle = 45f;

		[Header("POI Target Reacquisition")]
		[SerializeField]
		private bool reacquireLockOnTargetOnPOIEnemyDeath = true;

		[SerializeField]
		private float maxReacquireTargetVisionConeAngle = 60f;

		[Header("Point Of Interest Rendering")]
		[SerializeField]
		private Vector2 pointOfInterestVisualViewportOffset = new Vector2(0f, 0.066f);

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private List<Enemy> cachedPointOfInterestEnemies = new List<Enemy>();

		[NonSerialized]
		private List<Tool> cachedPointOfInterestTools = new List<Tool>();

		[NonSerialized]
		private IPlayerPointOfInterest lockedOnPOI;

		[NonSerialized]
		private IPlayerPointOfInterest previousLockedOnPOI;

		[NonSerialized]
		private Enemy closestEnemyPOI;

		[NonSerialized]
		private Tool closestToolPOI;

		[NonSerialized]
		private ScreenPlayerCameraControllerPool<LookAtPointOfInterestScreenPlayerCamera> lookAtPointOfInterestCameraPool;

		[NonSerialized]
		private IPlayerPointOfInterest autoTargetPOI;

		[NonSerialized]
		private float maximumAutoTargetRadius;

		public bool HasNearbyPointOfInterest => HasLockedOnPointOfInterest || closestEnemyPOI != null || closestToolPOI != null;

		public bool HasLockedOnPointOfInterest => stateMachine.CurrentStateId == 3;

		public bool HasLockedOnDirection => stateMachine.CurrentStateId == 2;

		public bool IsLockingOnToSomething => HasLockedOnDirection || HasLockedOnPointOfInterest;

		public bool HasAutoTargetPointOfInterest => stateMachine.CurrentStateId == 4;

		public float LockedOnPointOfInterestDistance
		{
			get
			{
				if (!HasLockedOnPointOfInterest)
				{
					return 0f;
				}
				Vector3 playerHeadPosition = cachedPlayerController.GetPlayerHeadPosition(cachedPlayer);
				return (LockedOnPointOfInterestPosition - playerHeadPosition).magnitude;
			}
		}

		public Vector3 NearbyPointOfInterestPosition
		{
			get
			{
				if (HasLockedOnPointOfInterest)
				{
					return LockedOnPointOfInterestPosition;
				}
				if (HasAutoTargetPointOfInterest)
				{
					return AutoTargetPointOfInterestPosition;
				}
				if (closestEnemyPOI != null)
				{
					return closestEnemyPOI.PointOfInterestPosition;
				}
				if (closestToolPOI != null)
				{
					return closestToolPOI.PointOfInterestPosition;
				}
				return Vector3.zero;
			}
		}

		public Vector3 LockedOnPointOfInterestPosition
		{
			get
			{
				if (HasLockedOnPointOfInterest && !lockedOnPOI.IsNullOrInvalid())
				{
					return lockedOnPOI.PointOfInterestPosition;
				}
				return Vector3.zero;
			}
		}

		public Vector3 AutoTargetPointOfInterestPosition
		{
			get
			{
				if (HasAutoTargetPointOfInterest && !autoTargetPOI.IsNullOrInvalid())
				{
					return autoTargetPOI.PointOfInterestPosition;
				}
				return Vector3.zero;
			}
		}

		public override void Initialize()
		{
			lookAtPointOfInterestCameraPool = new ScreenPlayerCameraControllerPool<LookAtPointOfInterestScreenPlayerCamera>(lookAtPointOfInterestCamera);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterIdleState, OnExitIdleState, OnUpdateIdleState);
			stateMachine.AddState(2, OnEnterLockOnDirectionState, OnExitLockOnDirectionState, OnUpdateLockOnDirectionState);
			stateMachine.AddState(3, OnEnterLockOnPOIState, OnExitLockOnPOIState, OnUpdateLockOnPOIState);
			stateMachine.AddState(4, OnEnterAutoTargetPOIState, OnExitAutoTargetPOIState, OnUpdateAutoTargetPOIState);
			stateMachine.AddState(5, OnEnterReacquireLockOnState, null, null);
			stateMachine.EnterState(0);
		}

		public override void OnEnterGenre(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			base.OnEnterGenre(playerController, player, camera, hud, input);
			playerController.AddCameraSettings(defaultCameraSettings, defaultCameraBlendTime, this, 100);
			playerController.AddGameplayCursorVisibilityRestriction(this);
			stateMachine.EnterState(1);
		}

		public override void OnExitGenre()
		{
			stateMachine.EnterState(0);
			cachedPlayerController.RemoveGameplayCursorVisibilityRestriction(this);
			cachedPlayerController.RemoveCameraController(this);
			cachedPlayerController.RemoveCameraSettings(this);
			cachedPlayerController.RemoveSteeringController(this);
			DisablePointOfInterestFeedbackRendering(cachedHUD);
			base.OnExitGenre();
		}

		public override void OnUpdate()
		{
			stateMachine.Update();
		}

		public override void OnLateUpdate()
		{
			UpdatePointOfInterestFeedbackRendering(cachedPlayer, cachedCamera, cachedHUD);
		}

		public void TryStartAutoTargetPointOfInterest(float maximumAutoTargetRadius)
		{
			if (stateMachine.CurrentStateId == 1)
			{
				this.maximumAutoTargetRadius = maximumAutoTargetRadius;
				stateMachine.EnterState(4);
			}
		}

		public void TryStopAutoTargetPointOfInterest()
		{
			if (stateMachine.CurrentStateId == 4)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.AddCameraController(defaultCamera, defaultCameraBlendTime, this, 100);
			cachedPlayerController.AddSteeringController(defaultSteering, this, 100);
		}

		private void OnUpdateIdleState()
		{
			UpdatePointsOfInterest(pointOfInterestSearchRadius, 180f);
			if (cachedInput.AimDownSightsButtonDown)
			{
				if (closestEnemyPOI != null)
				{
					stateMachine.EnterState(3);
				}
				else
				{
					stateMachine.EnterState(2);
				}
			}
		}

		private void OnExitIdleState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void OnEnterLockOnDirectionState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.StopSprint(cachedPlayer);
			cachedPlayerController.AddDodgeEnabled(this);
			Vector3 playerForwardDirection = cachedPlayerController.GetPlayerForwardDirection(cachedPlayer);
			lookDirectionCamera.LookDirection = playerForwardDirection;
			faceDirectionSteering.FacingDirection = playerForwardDirection;
			cachedPlayerController.AddCameraController(lookDirectionCamera, lockOnCameraBlendTime, this, 100);
			cachedPlayerController.AddSteeringController(faceDirectionSteering, this, 100);
		}

		private void OnUpdateLockOnDirectionState()
		{
			UpdatePointsOfInterest(pointOfInterestSearchRadius, 180f);
			if (!cachedInput.AimDownSightsButtonPressed)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnExitLockOnDirectionState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemoveDodgeEnabled(this);
		}

		private void OnEnterLockOnPOIState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.StopSprint(cachedPlayer);
			cachedPlayerController.AddDodgeEnabled(this);
			lockedOnPOI = closestEnemyPOI;
			facePointOfInterestSteering.PointOfInterest = lockedOnPOI;
			cachedPlayerController.AddSteeringController(facePointOfInterestSteering, this, 100);
			LookAtPointOfInterestScreenPlayerCamera nextCameraController = lookAtPointOfInterestCameraPool.GetNextCameraController(cachedPlayerController);
			nextCameraController.PointOfInterest = lockedOnPOI;
			cachedPlayerController.AddCameraController(nextCameraController, lockOnCameraBlendTime, this, 100);
		}

		private void OnUpdateLockOnPOIState()
		{
			if (!cachedInput.AimDownSightsButtonPressed)
			{
				stateMachine.EnterState(1);
			}
			else if (lockedOnPOI.IsNullOrInvalid())
			{
				if (reacquireLockOnTargetOnPOIEnemyDeath)
				{
					stateMachine.EnterState(5);
				}
				else
				{
					stateMachine.EnterState(1);
				}
			}
		}

		private void OnExitLockOnPOIState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemoveDodgeEnabled(this);
			previousLockedOnPOI = lockedOnPOI;
			lockedOnPOI = null;
		}

		private void OnEnterAutoTargetPOIState(ushort previousStateId, ushort previousSubStateId)
		{
			UpdatePointsOfInterest(maximumAutoTargetRadius, maxAutoTargetVisionConeAngle);
			if (closestEnemyPOI == null && closestToolPOI == null)
			{
				stateMachine.EnterState(1);
				return;
			}
			if (closestEnemyPOI != null)
			{
				autoTargetPOI = closestEnemyPOI;
			}
			else
			{
				autoTargetPOI = closestToolPOI;
			}
			facePointOfInterestSteering.PointOfInterest = autoTargetPOI;
			cachedPlayerController.AddSteeringController(facePointOfInterestSteering, this, 100);
		}

		private void OnUpdateAutoTargetPOIState()
		{
			if (autoTargetPOI.IsNullOrInvalid())
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnExitAutoTargetPOIState(ushort nextStateId, ushort nextSubStateId)
		{
			autoTargetPOI = null;
		}

		private void OnEnterReacquireLockOnState(ushort previousStateId, ushort previousSubStateId)
		{
			UpdatePointsOfInterest(pointOfInterestSearchRadius, maxReacquireTargetVisionConeAngle);
			if (closestEnemyPOI != null)
			{
				stateMachine.EnterState(3);
			}
			else
			{
				stateMachine.EnterState(1);
			}
		}

		private void UpdatePointsOfInterest(float searchRadius, float maxVisionConeAngle)
		{
			Vector3 playerHeadPosition = cachedPlayerController.GetPlayerHeadPosition(cachedPlayer);
			Vector3 playerForwardDirection = cachedPlayerController.GetPlayerForwardDirection(cachedPlayer);
			UpdateCachedPointOfInterestLists(cachedCamera, playerHeadPosition, searchRadius, cachedPointOfInterestEnemies, cachedPointOfInterestTools);
			closestEnemyPOI = GetClosestPointOfInterestFromEnemies(cachedPointOfInterestEnemies, playerHeadPosition, playerForwardDirection, cachedCamera.transform.position, cachedCamera.transform.forward, maxVisionConeAngle);
			bool flag = closestEnemyPOI != null;
			closestToolPOI = GetClosestPointOfInterestFromTools(cachedPointOfInterestTools, playerHeadPosition, playerForwardDirection, cachedCamera.transform.position, cachedCamera.transform.forward, maxVisionConeAngle);
			if (!flag)
			{
				UpdateCachedPointOfInterestLists(cachedCamera, playerHeadPosition, pointOfInterestSearchRadius, cachedPointOfInterestEnemies, cachedPointOfInterestTools);
				flag = GetClosestPointOfInterestFromEnemies(cachedPointOfInterestEnemies, playerHeadPosition, playerForwardDirection, cachedCamera.transform.position, cachedCamera.transform.forward, 180f) != null;
			}
			if (flag)
			{
				closestToolPOI = null;
			}
		}

		private Enemy GetClosestPointOfInterestFromEnemies(List<Enemy> potentialPOIs, Vector3 playerHeadPosition, Vector3 playerForward, Vector3 cameraPosition, Vector3 cameraForwardDirection, float maxVisionConeAngle)
		{
			Enemy result = null;
			float num = float.MaxValue;
			foreach (Enemy potentialPOI in potentialPOIs)
			{
				Vector3 pointOfInterestPosition = potentialPOI.PointOfInterestPosition;
				Vector3 lhs = pointOfInterestPosition - cameraPosition;
				if (Vector3.Dot(lhs, cameraForwardDirection) <= 0f)
				{
					continue;
				}
				Vector3 vector = pointOfInterestPosition - playerHeadPosition;
				if (maxVisionConeAngle < 180f)
				{
					Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
					float num2 = Vector3.Angle(playerForward, normalized);
					if (num2 > maxVisionConeAngle)
					{
						continue;
					}
				}
				float num3 = vector.sqrMagnitude;
				if (previousLockedOnPOI == potentialPOI)
				{
					float num4 = vector.magnitude + 2f;
					num3 = num4 * num4;
				}
				if (!(num3 >= num))
				{
					result = potentialPOI;
					num = num3;
				}
			}
			return result;
		}

		private Tool GetClosestPointOfInterestFromTools(List<Tool> potentialPOIs, Vector3 playerHeadPosition, Vector3 playerForward, Vector3 cameraPosition, Vector3 cameraForwardDirection, float maxVisionConeAngle)
		{
			Tool result = null;
			float num = float.MaxValue;
			foreach (Tool potentialPOI in potentialPOIs)
			{
				Vector3 pointOfInterestPosition = potentialPOI.PointOfInterestPosition;
				Vector3 lhs = pointOfInterestPosition - cameraPosition;
				if (Vector3.Dot(lhs, cameraForwardDirection) <= 0f)
				{
					continue;
				}
				Vector3 vector = pointOfInterestPosition - playerHeadPosition;
				if (maxVisionConeAngle < 180f)
				{
					Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
					float num2 = Vector3.Angle(playerForward, normalized);
					if (num2 > maxVisionConeAngle)
					{
						continue;
					}
				}
				float sqrMagnitude = vector.sqrMagnitude;
				if (sqrMagnitude < num)
				{
					result = potentialPOI;
					num = sqrMagnitude;
				}
			}
			return result;
		}

		private void UpdateCachedPointOfInterestLists(Camera camera, Vector3 searchOrigin, float searchRadius, List<Enemy> enemyList, List<Tool> toolList)
		{
			enemyList.Clear();
			toolList.Clear();
			Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
			int sphereColliderOverlaps = CollisionDetection.GetSphereColliderOverlaps(searchOrigin, searchRadius, 495330304, null, iMMEDIATE_COLLIDER_HITS);
			for (int i = 0; i < sphereColliderOverlaps; i++)
			{
				Tool colliderTool = iMMEDIATE_COLLIDER_HITS[i].GetColliderTool();
				if (IsValidPointOfInterest(colliderTool, camera) && !toolList.Contains(colliderTool))
				{
					toolList.Add(colliderTool);
					continue;
				}
				Enemy colliderEnemy = iMMEDIATE_COLLIDER_HITS[i].GetColliderEnemy();
				if (IsValidPointOfInterest(colliderEnemy, camera) && !enemyList.Contains(colliderEnemy))
				{
					enemyList.Add(colliderEnemy);
				}
			}
		}

		private bool IsValidPointOfInterest(IPlayerPointOfInterest pointOfInterest, Camera camera)
		{
			if (pointOfInterest.IsNullOrInvalid())
			{
				return false;
			}
			if (!IsPointOfInterestVisible(pointOfInterest.PointOfInterestPosition, camera))
			{
				return false;
			}
			return true;
		}

		private bool IsPointOfInterestVisible(Vector3 poiPosition, Camera camera)
		{
			if (!camera.IsInFovSimple(poiPosition))
			{
				return false;
			}
			Vector3 position = camera.transform.position;
			Vector3 vector = poiPosition - position;
			float num = 0.05f;
			float magnitude = vector.magnitude;
			if (magnitude <= 2f * num)
			{
				return true;
			}
			Vector3 vector2 = vector / magnitude;
			Vector3 start = position + vector2 * num;
			Vector3 end = poiPosition - vector2 * num;
			bool flag = Physics.CheckCapsule(start, end, num, 2048, QueryTriggerInteraction.Ignore);
			return !flag;
		}

		private void UpdatePointOfInterestFeedbackRendering(Player player, Camera camera, ScreenHUD hud)
		{
			Vector2 vector = Vector2.zero;
			bool flag = false;
			bool flag2 = false;
			bool flag3 = closestEnemyPOI != null;
			bool flag4 = closestToolPOI != null;
			bool hasLockedOnPointOfInterest = HasLockedOnPointOfInterest;
			if (hasLockedOnPointOfInterest && flag3)
			{
				Vector3 vector2 = camera.WorldToViewportPoint(closestEnemyPOI.PointOfInterestLabelPosition);
				vector = (Vector2)vector2 + pointOfInterestVisualViewportOffset;
				flag2 = true;
			}
			else if (hasLockedOnPointOfInterest && flag4)
			{
				vector = camera.WorldToViewportPoint(closestEnemyPOI.PointOfInterestPosition);
				flag2 = true;
			}
			else if (flag3)
			{
				Vector3 vector3 = camera.WorldToViewportPoint(closestEnemyPOI.PointOfInterestLabelPosition);
				vector = (Vector2)vector3 + pointOfInterestVisualViewportOffset;
				flag = true;
			}
			hud.EnablePointOfInterestLockOnVisual(flag2);
			if (flag2)
			{
				hud.SetPointOfInterestLockOnVisualViewportSpacePosition(vector);
			}
			hud.EnablePointOfInterestPreviewVisual(flag);
			if (flag)
			{
				hud.SetPointOfInterestPreviewVisualViewportSpacePosition(vector);
			}
		}

		private void DisablePointOfInterestFeedbackRendering(ScreenHUD hud)
		{
			hud.EnablePointOfInterestLockOnVisual(enabled: false);
			hud.EnablePointOfInterestPreviewVisual(enabled: false);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Genre Controllers/Shooter Genre Controller", fileName = "ShooterScreenPlayerGenre")]
	public class ShooterScreenPlayerGenre : ScreenPlayerGenreController
	{
		private enum State
		{
			INVALID,
			IDLE,
			POST_ACTION,
			AIM_DOWN_SIGHTS
		}

		private static readonly string AIM_DOWN_SIGHTS_TOKEN = "AIM_DOWN_SIGHTS";

		private static readonly int AIM_DOWN_SIGHTS_CAMERA_PRIORITY = 110;

		[Header("Steering And Camera Controllers")]
		[SerializeField]
		private OrbitScreenPlayerCamera cameraController;

		[SerializeField]
		private FaceCameraForwardScreenPlayerSteering steeringController;

		[SerializeField]
		private float cameraTransitionDuration = 0.25f;

		[Header("Cursor Settings")]
		[SerializeField]
		private ScreenPlayerCursorSettings defaultGameplayCursorSettings;

		[Header("Post Action Settings")]
		[SerializeField]
		private float maxPostActionDuration = 5f;

		[Header("Default Camera")]
		[SerializeField]
		private ScreenPlayerCameraSettings defaultCameraSettings;

		[Header("Aim Down Sights")]
		[SerializeField]
		private ScreenPlayerAimDownSightsSettings defaultAimDownSightsSettings;

		[SerializeField]
		private PlayerAnimation aimDownSightsDefaultAnimation;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private TokenMap<ScreenPlayerAimDownSightsSettings> aimDownSightsSettingsMap = new TokenMap<ScreenPlayerAimDownSightsSettings>();

		[NonSerialized]
		private MaskedPlayerAnimation actionReadyMaskedAnimation = new MaskedPlayerAnimation();

		[NonSerialized]
		private MaskedPlayerAnimation aimDownSightsMaskedAnimation = new MaskedPlayerAnimation();

		public bool IsAimingDownSights => stateMachine.CurrentStateId == 3;

		public override void Initialize()
		{
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterIdleState, OnExitIdleState, OnUpdateIdleState);
			stateMachine.AddState(2, OnEnterPostActionState, OnExitPostActionState, OnUpdatePostActionState);
			stateMachine.AddState(3, OnEnterAimDownSightsState, OnExitAimDownSightsState, OnUpdateAimDownSightsState);
			stateMachine.EnterState(0);
			AddAimDownSightsSettings(defaultAimDownSightsSettings, this);
		}

		public override void OnEnterGenre(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			base.OnEnterGenre(playerController, player, camera, hud, input);
			cachedPlayerController.AddSteeringController(steeringController, this, 100);
			cachedPlayerController.AddCameraController(cameraController, cameraTransitionDuration, this, 100);
			cachedPlayerController.AddCameraSettings(defaultCameraSettings, cameraTransitionDuration, this, 100);
			cachedPlayerController.AddGameplayCursorSettings(defaultGameplayCursorSettings, this, 100);
			UpdateAllMaskedAnimation();
			stateMachine.EnterState(1);
		}

		public override void OnExitGenre()
		{
			stateMachine.EnterState(0);
			cachedPlayerController.RemoveCameraController(this);
			cachedPlayerController.RemoveCameraSettings(this);
			cachedPlayerController.RemoveSteeringController(this);
			cachedPlayerController.RemoveGameplayCursorSettings(this);
			base.OnExitGenre();
		}

		public override void OnUpdate()
		{
			stateMachine.Update();
		}

		public override void OnLateUpdate()
		{
		}

		public override void OnSprintStart()
		{
			base.OnSprintStart();
			if (stateMachine.CurrentStateId == 3)
			{
				State nonAimDownSightsState = GetNonAimDownSightsState();
				stateMachine.EnterState((ushort)nonAimDownSightsState);
			}
		}

		public override void OnToolPickup()
		{
			base.OnToolPickup();
			UpdateAllMaskedAnimation();
		}

		public override void OnToolRelease()
		{
			base.OnToolRelease();
			UpdateAllMaskedAnimation();
		}

		public void AddAimDownSightsSettings(ScreenPlayerAimDownSightsSettings aimDownSightsSettings, object token)
		{
			aimDownSightsSettingsMap.AddValue(aimDownSightsSettings, token);
			if (IsAimingDownSights)
			{
				OnAimDownSightsSettingsChange();
			}
		}

		public void RemoveAimDownSightsSettings(object token)
		{
			aimDownSightsSettingsMap.RemoveValue(token);
			if (IsAimingDownSights)
			{
				OnAimDownSightsSettingsChange();
			}
		}

		public bool IsActionReadyAnimationPlaying()
		{
			IPlayerAnimationData animation = null;
			return TryGetPostActionAnimation(out animation) && cachedPlayerController.IsAnimationPlaying(animation);
		}

		public void PlayActionReadyAnimation()
		{
			IPlayerAnimationData animation = null;
			if (TryGetPostActionAnimation(out animation))
			{
				cachedPlayerController.PlayLoopingAnimation(animation);
			}
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
		{
		}

		private void OnUpdateIdleState()
		{
			if (IsAimDownSightsButtonPressed())
			{
				stateMachine.EnterState(3);
			}
			else if (IsPlayerPostAction())
			{
				stateMachine.EnterState(2);
			}
		}

		private void OnExitIdleState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		private void OnEnterPostActionState(ushort previousStateId, ushort previousSubStateId)
		{
		}

		private void OnUpdatePostActionState()
		{
			if (IsAimDownSightsButtonPressed())
			{
				stateMachine.EnterState(3);
				return;
			}
			if (!IsPlayerPostAction())
			{
				stateMachine.EnterState(1);
				return;
			}
			IPlayerAnimationData animation = null;
			if (TryGetPostActionAnimation(out animation))
			{
				cachedPlayerController.OverrideStandAnimation(animation);
				cachedPlayerController.OverrideWalkAnimation(animation);
				cachedPlayerController.OverrideJumpAnimation(animation);
			}
		}

		private void OnExitPostActionState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.ClearOverriddenStandAnimation();
			cachedPlayerController.ClearOverriddenWalkAnimation();
			cachedPlayerController.ClearOverriddenJumpAnimation();
		}

		private void OnEnterAimDownSightsState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.StopSprint(cachedPlayer);
			OnAimDownSightsSettingsChange();
		}

		private void OnUpdateAimDownSightsState()
		{
			if (!cachedInput.AimDownSightsButtonPressed)
			{
				State nonAimDownSightsState = GetNonAimDownSightsState();
				stateMachine.EnterState((ushort)nonAimDownSightsState);
				return;
			}
			IPlayerAnimationData animation = null;
			if (TryGetAimDownSightsAnimation(out animation))
			{
				cachedPlayerController.OverrideStandAnimation(animation);
				cachedPlayerController.OverrideWalkAnimation(animation);
				cachedPlayerController.OverrideJumpAnimation(animation);
				cachedPlayerController.OverrideCrouchAnimation(animation);
			}
		}

		private void OnExitAimDownSightsState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemoveCameraSettings(AIM_DOWN_SIGHTS_TOKEN);
			cachedPlayerController.RemoveWalkSpeedMultiplier(AIM_DOWN_SIGHTS_TOKEN);
			cachedPlayerController.RemoveCameraSpeedMultiplier(AIM_DOWN_SIGHTS_TOKEN);
			cachedPlayerController.ClearOverriddenStandAnimation();
			cachedPlayerController.ClearOverriddenWalkAnimation();
			cachedPlayerController.ClearOverriddenJumpAnimation();
			cachedPlayerController.ClearOverriddenCrouchAnimation();
		}

		private bool IsPlayerPostAction()
		{
			if (cachedPlayer == null || cachedPlayerController == null)
			{
				return false;
			}
			PlayerHand mainHand = cachedPlayerController.GetMainHand(cachedPlayer);
			if (mainHand.HeldTool == null)
			{
				return false;
			}
			float num = UnityEngine.Time.time - cachedPlayerController.LastToolUseTime;
			if (num > maxPostActionDuration)
			{
				return false;
			}
			return true;
		}

		private bool IsAimDownSightsButtonPressed()
		{
			bool flag = cachedInput.AimDownSightsButtonDown;
			if (!cachedPlayerController.IsSprinting(cachedPlayer))
			{
				flag |= cachedInput.AimDownSightsButtonPressed;
			}
			return flag;
		}

		private State GetNonAimDownSightsState()
		{
			if (IsPlayerPostAction())
			{
				return State.POST_ACTION;
			}
			return State.IDLE;
		}

		private void OnAimDownSightsSettingsChange()
		{
			ApplyAimDownSightsSettings(aimDownSightsSettingsMap.LatestValue);
		}

		private void ApplyAimDownSightsSettings(ScreenPlayerAimDownSightsSettings settings)
		{
			cachedPlayerController.AddCameraSettings(settings.CameraSettings, settings.FadeInTime, AIM_DOWN_SIGHTS_TOKEN, AIM_DOWN_SIGHTS_CAMERA_PRIORITY);
			cachedPlayerController.AddWalkSpeedMultiplier(settings.WalkSpeedMultiplier, AIM_DOWN_SIGHTS_TOKEN);
			cachedPlayerController.AddCameraSpeedMultiplier(settings.CameraSpeedMultiplier, AIM_DOWN_SIGHTS_TOKEN);
		}

		private bool TryGetPostActionAnimation(out IPlayerAnimationData animation)
		{
			PlayerHand mainHand = cachedPlayerController.GetMainHand(cachedPlayer);
			Tool heldTool = mainHand.HeldTool;
			bool flag = heldTool != null && heldTool.ScreenActionReadyAnimation.AnimationAsset != null;
			PlayerHand offHand = cachedPlayerController.GetOffHand(cachedPlayer);
			Tool heldTool2 = offHand.HeldTool;
			bool flag2 = heldTool2 != null && heldTool2.ScreenActionReadyAnimation.AnimationAsset != null;
			if (flag && flag2)
			{
				animation = actionReadyMaskedAnimation;
				return true;
			}
			if (flag)
			{
				animation = heldTool.ScreenActionReadyAnimation;
				return true;
			}
			if (flag2)
			{
				animation = heldTool2.ScreenActionReadyAnimation;
				return true;
			}
			animation = null;
			return false;
		}

		private bool TryGetAimDownSightsAnimation(out IPlayerAnimationData animation)
		{
			PlayerHand mainHand = cachedPlayerController.GetMainHand(cachedPlayer);
			Tool heldTool = mainHand.HeldTool;
			bool flag = heldTool != null && heldTool.ScreenAimDownSightsAnimation.AnimationAsset != null;
			PlayerHand offHand = cachedPlayerController.GetOffHand(cachedPlayer);
			Tool heldTool2 = offHand.HeldTool;
			bool flag2 = heldTool2 != null && heldTool2.ScreenAimDownSightsAnimation.AnimationAsset != null;
			if (flag && flag2)
			{
				animation = aimDownSightsMaskedAnimation;
				return true;
			}
			if (flag)
			{
				animation = heldTool.ScreenAimDownSightsAnimation;
				return true;
			}
			if (flag2)
			{
				animation = heldTool2.ScreenAimDownSightsAnimation;
				return true;
			}
			animation = aimDownSightsDefaultAnimation;
			return true;
		}

		private void UpdateAllMaskedAnimation()
		{
			if (cachedPlayerController == null || cachedPlayer == null)
			{
				return;
			}
			PlayerHand mainHand = cachedPlayerController.GetMainHand(cachedPlayer);
			Tool heldTool = mainHand.HeldTool;
			PlayerHand offHand = cachedPlayerController.GetOffHand(cachedPlayer);
			Tool heldTool2 = offHand.HeldTool;
			if (!(heldTool == null) && !(heldTool2 == null))
			{
				PlayerAnimationFrame.TransformType transformType = ((offHand.Type == PlayerHand.HandType.Left) ? PlayerAnimationFrame.TransformType.LEFT_HAND : PlayerAnimationFrame.TransformType.RIGHT_HAND);
				if (heldTool.ScreenActionReadyAnimation.AnimationAsset != null && heldTool2.ScreenActionReadyAnimation.AnimationAsset != null)
				{
					UpdateMaskedAnimation(actionReadyMaskedAnimation, heldTool.ScreenActionReadyAnimation, heldTool2.ScreenActionReadyAnimation, transformType);
				}
				if (heldTool.ScreenAimDownSightsAnimation.AnimationAsset != null && heldTool2.ScreenAimDownSightsAnimation.AnimationAsset != null)
				{
					UpdateMaskedAnimation(aimDownSightsMaskedAnimation, heldTool.ScreenAimDownSightsAnimation, heldTool2.ScreenAimDownSightsAnimation, transformType);
				}
			}
		}

		private void UpdateMaskedAnimation(MaskedPlayerAnimation maskedAnimation, IPlayerAnimationData baseAnimation, IPlayerAnimationData layeredAnimation, PlayerAnimationFrame.TransformType transformType)
		{
			maskedAnimation.ClearLayeredAnimations();
			maskedAnimation.SetBaseAnimation(baseAnimation);
			maskedAnimation.AddLayeredAnimation(layeredAnimation, transformType);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Genre Controllers/Social Genre Controller", fileName = "SocialScreenPlayerGenre")]
	public class SocialScreenPlayerGenre : ScreenPlayerGenreController
	{
		private enum State
		{
			INVALID,
			IDLE,
			LOCK_ON_DIRECTION,
			LOCK_ON_POI
		}

		private enum IdleSubState
		{
			DEFAULT,
			LOOK_AT_POI
		}

		private struct AutomaticPOITarget
		{
			public IPlayerPointOfInterest POI;

			public bool IsTalking;

			public float StartTime;
		}

		[Serializable]
		private struct POITargetingData
		{
			public float MaxRadius;

			public float MaxAngleFromPlayer;

			public float MaxAngleFromVelocity;

			public float MaxAngleFromCamera;

			public bool IsWithinThreshold(float distSqr, float angleFromPLayer, float angleFromVelocity, float angleFromCamera)
			{
				return distSqr <= MaxRadius * MaxRadius && angleFromPLayer <= MaxAngleFromPlayer && angleFromVelocity <= MaxAngleFromVelocity && angleFromCamera <= MaxAngleFromCamera;
			}
		}

		[Header("Cameras")]
		[SerializeField]
		private ScreenPlayerCameraSettings defaultCameraSettings;

		[SerializeField]
		private OrbitScreenPlayerCamera defaultCamera;

		[SerializeField]
		private LookAtPointOfInterestScreenPlayerCamera lookAtPointOfInterestCamera;

		[SerializeField]
		private LookDirectionScreenPlayerCamera lookDirectionCamera;

		[SerializeField]
		private float defaultCameraBlendTime = 1f;

		[SerializeField]
		private float lockOnCameraBlendTime = 0.5f;

		[Header("Steering")]
		[SerializeField]
		private FaceVelocityScreenPlayerSteering defaultSteering;

		[SerializeField]
		private FacePointOfInterestScreenPlayerSteering facePointOfInterestSteering;

		[SerializeField]
		private FacePointOfInterestScreenPlayerSteering automaticFacePointOfInterestSteering;

		[SerializeField]
		private FaceDirectionScreenPlayerSteering faceDirectionSteering;

		[Header("Point Of Interest Settings")]
		[SerializeField]
		private float pointOfInterestSearchRadius = 10f;

		[Header("POI Is Talking Settings")]
		[SerializeField]
		private float maxTalkingPOIAngleFromPOI = 60f;

		[SerializeField]
		private float maxTalkingPOIDistanceFromPOI = 8f;

		[SerializeField]
		private float minLookAtTalkingPOIDuration = 2f;

		[Header("POI Automatic Look At Settings")]
		[SerializeField]
		private POITargetingData defaultAutomaticTargetingData;

		[SerializeField]
		private POITargetingData talkingPOIAutomaticTargetingData;

		[Header("Point Of Interest Rendering")]
		[SerializeField]
		private Vector2 pointOfInterestVisualViewportOffset = new Vector2(0f, 0.0125f);

		[Header("Quick Comms")]
		[SerializeField]
		private QuickCommsMenu socialGestureQuickCommsMenu;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private List<IPlayerPointOfInterest> cachedPointsOfInterest = new List<IPlayerPointOfInterest>();

		[NonSerialized]
		private ScreenPlayerCameraControllerPool<LookAtPointOfInterestScreenPlayerCamera> lookAtPointOfInterestCameraPool;

		[NonSerialized]
		private IPlayerPointOfInterest lockedOnPOI;

		[NonSerialized]
		private IPlayerPointOfInterest previousLockedOnPOI;

		[NonSerialized]
		private IPlayerPointOfInterest nextLockOnPointOfInterest;

		[NonSerialized]
		private AutomaticPOITarget automaticPointOfInterest;

		public bool HasNearbyPointOfInterest => HasLockedOnPointOfInterest || !nextLockOnPointOfInterest.IsNullOrInvalid();

		public bool HasLockedOnPointOfInterest => stateMachine.CurrentStateId == 3;

		public Player LockedOnPointOfInterestPlayer => (!HasLockedOnPointOfInterest) ? null : ((Player)lockedOnPOI);

		public bool HasLockedOnDirection => stateMachine.CurrentStateId == 2;

		public bool IsLockingOnToSomething => HasLockedOnDirection || HasLockedOnPointOfInterest;

		public float LockedOnPointOfInterestDistance
		{
			get
			{
				if (!HasLockedOnPointOfInterest)
				{
					return 0f;
				}
				Vector3 playerHeadPosition = cachedPlayerController.GetPlayerHeadPosition(cachedPlayer);
				return (LockedOnPointOfInterestPosition - playerHeadPosition).magnitude;
			}
		}

		public Vector3 NearbyPointOfInterestPosition
		{
			get
			{
				if (HasLockedOnPointOfInterest)
				{
					return LockedOnPointOfInterestPosition;
				}
				if (!nextLockOnPointOfInterest.IsNullOrInvalid())
				{
					return nextLockOnPointOfInterest.PointOfInterestPosition;
				}
				return Vector3.zero;
			}
		}

		public Vector3 LockedOnPointOfInterestPosition
		{
			get
			{
				if (HasLockedOnPointOfInterest && !lockedOnPOI.IsNullOrInvalid())
				{
					return lockedOnPOI.PointOfInterestPosition;
				}
				return Vector3.zero;
			}
		}

		public override void Initialize()
		{
			lookAtPointOfInterestCameraPool = new ScreenPlayerCameraControllerPool<LookAtPointOfInterestScreenPlayerCamera>(lookAtPointOfInterestCamera);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterIdleState, null, OnUpdateIdleState);
			stateMachine.AddState(1, 0, OnEnterIdleDefaultSubState, null, OnUpdateIdleDefaultSubState);
			stateMachine.AddState(1, 1, OnEnterIdleLookAtPOISubState, null, OnUpdateIdleLookAtPOISubState);
			stateMachine.AddState(2, OnEnterLockOnDirectionState, OnExitLockOnDirectionState, OnUpdateLockOnDirectionState);
			stateMachine.AddState(3, OnEnterLockOnPOIState, OnExitLockOnPOIState, OnUpdateLockOnPOIState);
			stateMachine.EnterState(0);
		}

		public override void OnEnterGenre(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			base.OnEnterGenre(playerController, player, camera, hud, input);
			playerController.AddCameraSettings(defaultCameraSettings, defaultCameraBlendTime, this, 100);
			playerController.AddGameplayCursorVisibilityRestriction(this);
			playerController.QuickCommsController.AddAlwaysVisibleRequirement(this);
			stateMachine.EnterState(1, 0);
		}

		public override void OnExitGenre()
		{
			stateMachine.EnterState(0);
			cachedPlayerController.RemoveGameplayCursorVisibilityRestriction(this);
			cachedPlayerController.RemoveCameraController(this);
			cachedPlayerController.RemoveCameraSettings(this);
			cachedPlayerController.RemoveSteeringController(this);
			cachedPlayerController.QuickCommsController.RemoveAlwaysVisibleRequirement(this);
			DisablePointOfInterestFeedbackRendering(cachedHUD);
			base.OnExitGenre();
		}

		public override void OnUpdate()
		{
			stateMachine.Update();
		}

		public override void OnLateUpdate()
		{
			UpdatePointOfInterestFeedbackRendering(cachedPlayer, cachedCamera, cachedHUD);
		}

		private void OnEnterIdleState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.AddCameraController(defaultCamera, defaultCameraBlendTime, this, 100);
		}

		private void OnUpdateIdleState()
		{
			UpdatePointsOfInterest(pointOfInterestSearchRadius, 180f);
			if (cachedInput.AimDownSightsButtonDown)
			{
				if (!nextLockOnPointOfInterest.IsNullOrInvalid())
				{
					stateMachine.EnterState(3);
				}
				else
				{
					stateMachine.EnterState(2);
				}
			}
		}

		private void OnEnterIdleDefaultSubState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.AddSteeringController(defaultSteering, this, 100);
		}

		private void OnUpdateIdleDefaultSubState()
		{
			if (!automaticPointOfInterest.POI.IsNullOrInvalid())
			{
				stateMachine.EnterState(1, 1);
			}
		}

		private void OnEnterIdleLookAtPOISubState(ushort previousStateId, ushort previousSubStateId)
		{
			automaticFacePointOfInterestSteering.PointOfInterest = automaticPointOfInterest.POI;
			cachedPlayerController.AddSteeringController(automaticFacePointOfInterestSteering, this, 100);
		}

		private void OnUpdateIdleLookAtPOISubState()
		{
			if (automaticPointOfInterest.POI.IsNullOrInvalid())
			{
				stateMachine.EnterState(1, 0);
			}
			else
			{
				automaticFacePointOfInterestSteering.PointOfInterest = automaticPointOfInterest.POI;
			}
		}

		private void OnEnterLockOnDirectionState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.StopSprint(cachedPlayer);
			cachedPlayerController.AddDodgeEnabled(this);
			Vector3 playerForwardDirection = cachedPlayerController.GetPlayerForwardDirection(cachedPlayer);
			lookDirectionCamera.LookDirection = playerForwardDirection;
			faceDirectionSteering.FacingDirection = playerForwardDirection;
			cachedPlayerController.AddCameraController(lookDirectionCamera, lockOnCameraBlendTime, this, 100);
			cachedPlayerController.AddSteeringController(faceDirectionSteering, this, 100);
			cachedPlayerController.QuickCommsController.AddMenu(socialGestureQuickCommsMenu, this);
		}

		private void OnUpdateLockOnDirectionState()
		{
			UpdatePointsOfInterest(pointOfInterestSearchRadius, 180f);
			if (!cachedInput.AimDownSightsButtonPressed)
			{
				stateMachine.EnterState(1, 0);
			}
		}

		private void OnExitLockOnDirectionState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemoveDodgeEnabled(this);
			if (nextStateId != 3)
			{
				cachedPlayerController.QuickCommsController.RemoveMenu(this);
			}
		}

		private void OnEnterLockOnPOIState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.StopSprint(cachedPlayer);
			cachedPlayerController.AddDodgeEnabled(this);
			lockedOnPOI = nextLockOnPointOfInterest;
			facePointOfInterestSteering.PointOfInterest = lockedOnPOI;
			cachedPlayerController.AddSteeringController(facePointOfInterestSteering, this, 100);
			LookAtPointOfInterestScreenPlayerCamera nextCameraController = lookAtPointOfInterestCameraPool.GetNextCameraController(cachedPlayerController);
			nextCameraController.PointOfInterest = lockedOnPOI;
			cachedPlayerController.AddCameraController(nextCameraController, lockOnCameraBlendTime, this, 100);
			cachedPlayerController.QuickCommsController.AddMenu(socialGestureQuickCommsMenu, this);
		}

		private void OnUpdateLockOnPOIState()
		{
			if (!cachedInput.AimDownSightsButtonPressed)
			{
				stateMachine.EnterState(1, 0);
			}
			else if (lockedOnPOI.IsNullOrInvalid())
			{
				stateMachine.EnterState(1, 0);
			}
		}

		private void OnExitLockOnPOIState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemoveDodgeEnabled(this);
			previousLockedOnPOI = lockedOnPOI;
			lockedOnPOI = null;
			if (nextStateId != 2)
			{
				cachedPlayerController.QuickCommsController.RemoveMenu(this);
			}
		}

		private void UpdatePointsOfInterest(float searchRadius, float maxVisionConeAngle)
		{
			Vector3 playerHeadPosition = cachedPlayerController.GetPlayerHeadPosition(cachedPlayer);
			Vector3 playerForwardDirection = cachedPlayerController.GetPlayerForwardDirection(cachedPlayer);
			Vector3 playerMoveVelocity = cachedPlayerController.GetPlayerMoveVelocity(cachedPlayer);
			Vector3 playerVelocity = Vector3.zero;
			Vector3 vector = Vector3.ProjectOnPlane(playerMoveVelocity, Vector3.up);
			if (vector.sqrMagnitude >= Mathf.Epsilon)
			{
				playerVelocity = vector.normalized;
			}
			UpdateCachedPointOfInterestLists(cachedPlayer, cachedCamera, playerHeadPosition, searchRadius, cachedPointsOfInterest);
			nextLockOnPointOfInterest = GetClosestPointOfInterestFromPlayers(cachedPointsOfInterest, playerHeadPosition, playerForwardDirection, maxVisionConeAngle);
			bool isPOITalking = false;
			IPlayerPointOfInterest automaticLookAtPointOfInterest = GetAutomaticLookAtPointOfInterest(cachedPointsOfInterest, playerHeadPosition, playerForwardDirection, playerVelocity, out isPOITalking);
			if (!automaticLookAtPointOfInterest.IsNullOrInvalid() && automaticLookAtPointOfInterest != automaticPointOfInterest.POI)
			{
				automaticPointOfInterest.POI = automaticLookAtPointOfInterest;
				automaticPointOfInterest.StartTime = UnityEngine.Time.time;
				automaticPointOfInterest.IsTalking = isPOITalking;
			}
			else if (automaticLookAtPointOfInterest.IsNullOrInvalid() && (!automaticPointOfInterest.IsTalking || automaticPointOfInterest.POI.IsNullOrInvalid() || UnityEngine.Time.time - automaticPointOfInterest.StartTime >= minLookAtTalkingPOIDuration))
			{
				automaticPointOfInterest.POI = null;
				automaticPointOfInterest.IsTalking = false;
			}
		}

		private IPlayerPointOfInterest GetClosestPointOfInterestFromPlayers(List<IPlayerPointOfInterest> potentialPOIs, Vector3 localPlayerHeadPosition, Vector3 playerForward, float maxVisionConeAngle)
		{
			Vector3 position = cachedCamera.transform.position;
			Vector3 normalized = Vector3.ProjectOnPlane(cachedCamera.transform.forward, Vector3.up).normalized;
			IPlayerPointOfInterest result = null;
			float num = float.MaxValue;
			foreach (IPlayerPointOfInterest potentialPOI in potentialPOIs)
			{
				Vector3 pointOfInterestPosition = potentialPOI.PointOfInterestPosition;
				Vector3 pointOfInterestForwardDirection = potentialPOI.PointOfInterestForwardDirection;
				if (!cachedCamera.IsInFovSimple(pointOfInterestPosition))
				{
					continue;
				}
				float distanceToPlayerSqr = 0f;
				float angleFromPlayer = 0f;
				float angleFromVelocity = 0f;
				float angleFromPOIForward = 0f;
				float angleFromCamera = 0f;
				GetDistanceToPointOfInterest(pointOfInterestPosition, pointOfInterestForwardDirection, localPlayerHeadPosition, playerForward, Vector3.zero, position, normalized, out distanceToPlayerSqr, out angleFromPlayer, out angleFromVelocity, out angleFromPOIForward, out angleFromCamera);
				if (!(angleFromCamera >= 90f) && (!(maxVisionConeAngle < 180f) || !(angleFromPlayer > maxVisionConeAngle)))
				{
					if (previousLockedOnPOI == potentialPOI)
					{
						float num2 = Mathf.Sqrt(distanceToPlayerSqr) + 2f;
						distanceToPlayerSqr = num2 * num2;
					}
					if (!(distanceToPlayerSqr >= num))
					{
						result = potentialPOI;
						num = distanceToPlayerSqr;
					}
				}
			}
			return result;
		}

		private IPlayerPointOfInterest GetAutomaticLookAtPointOfInterest(List<IPlayerPointOfInterest> potentialPOIs, Vector3 localPlayerHeadPosition, Vector3 playerForward, Vector3 playerVelocity, out bool isPOITalking)
		{
			Vector3 position = cachedCamera.transform.position;
			Vector3 normalized = Vector3.ProjectOnPlane(cachedCamera.transform.forward, Vector3.up).normalized;
			isPOITalking = false;
			float num = 0f;
			IPlayerPointOfInterest result = null;
			for (int i = 0; i < potentialPOIs.Count; i++)
			{
				float distanceToPlayerSqr = 0f;
				float angleFromPlayer = 0f;
				float angleFromVelocity = 0f;
				float angleFromPOIForward = 0f;
				float angleFromCamera = 0f;
				IPlayerPointOfInterest playerPointOfInterest = potentialPOIs[i];
				Vector3 pointOfInterestPosition = playerPointOfInterest.PointOfInterestPosition;
				Vector3 pointOfInterestForwardDirection = playerPointOfInterest.PointOfInterestForwardDirection;
				GetDistanceToPointOfInterest(pointOfInterestPosition, pointOfInterestForwardDirection, localPlayerHeadPosition, playerForward, playerVelocity, position, normalized, out distanceToPlayerSqr, out angleFromPlayer, out angleFromVelocity, out angleFromPOIForward, out angleFromCamera);
				bool flag = playerPointOfInterest.IsHighPriorityPointOfInterest && distanceToPlayerSqr <= maxTalkingPOIDistanceFromPOI * maxTalkingPOIDistanceFromPOI && angleFromPOIForward <= maxTalkingPOIAngleFromPOI;
				if ((!flag || talkingPOIAutomaticTargetingData.IsWithinThreshold(distanceToPlayerSqr, angleFromPlayer, angleFromVelocity, angleFromCamera)) && (flag || defaultAutomaticTargetingData.IsWithinThreshold(distanceToPlayerSqr, angleFromPlayer, angleFromVelocity, angleFromCamera)))
				{
					float num2 = 1f;
					if (num2 > num)
					{
						num = num2;
						result = playerPointOfInterest;
						isPOITalking = flag;
					}
				}
			}
			return result;
		}

		private void UpdateCachedPointOfInterestLists(Player thisPlayer, Camera camera, Vector3 searchOrigin, float searchRadius, List<IPlayerPointOfInterest> playerList)
		{
			playerList.Clear();
			Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
			int sphereColliderOverlaps = CollisionDetection.GetSphereColliderOverlaps(searchOrigin, searchRadius, 1052672, null, iMMEDIATE_COLLIDER_HITS);
			for (int i = 0; i < sphereColliderOverlaps; i++)
			{
				Player.BodyPart bodyPart;
				Player colliderPlayer = iMMEDIATE_COLLIDER_HITS[i].GetColliderPlayer(out bodyPart);
				if (IsValidPointOfInterest(thisPlayer, colliderPlayer, camera) && !playerList.Contains(colliderPlayer))
				{
					playerList.Add(colliderPlayer);
					continue;
				}
				DummyPointOfInterest component = iMMEDIATE_COLLIDER_HITS[i].gameObject.GetComponent<DummyPointOfInterest>();
				if (IsValidPointOfInterest(thisPlayer, component, camera) && !playerList.Contains(colliderPlayer))
				{
					playerList.Add(component);
				}
			}
		}

		private void GetDistanceToPointOfInterest(Vector3 poiPosition, Vector3 poiForward, Vector3 localPlayerHeadPosition, Vector3 playerForward, Vector3 playerVelocity, Vector3 cameraPosition, Vector3 cameraForward, out float distanceToPlayerSqr, out float angleFromPlayer, out float angleFromVelocity, out float angleFromPOIForward, out float angleFromCamera)
		{
			Vector3 vector = poiPosition - localPlayerHeadPosition;
			distanceToPlayerSqr = vector.sqrMagnitude;
			Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
			angleFromPlayer = Vector3.Angle(playerForward, normalized);
			angleFromPOIForward = Vector3.Angle(poiForward, -normalized);
			angleFromVelocity = ((!(playerVelocity.sqrMagnitude >= Mathf.Epsilon)) ? 0f : Vector3.Angle(playerVelocity, normalized));
			Vector3 normalized2 = Vector3.ProjectOnPlane(poiPosition - cameraPosition, Vector3.up).normalized;
			angleFromCamera = Vector3.Angle(cameraForward, normalized2);
		}

		private bool IsValidPointOfInterest(Player thisPlayer, IPlayerPointOfInterest pointOfInterest, Camera camera)
		{
			if (pointOfInterest.IsNullOrInvalid())
			{
				return false;
			}
			if (pointOfInterest == thisPlayer)
			{
				return false;
			}
			if (!IsPointOfInterestVisible(pointOfInterest, camera))
			{
				return false;
			}
			return true;
		}

		private bool IsPointOfInterestVisible(IPlayerPointOfInterest pointOfInterest, Camera camera)
		{
			Vector3 position = camera.transform.position;
			Vector3 pointOfInterestPosition = pointOfInterest.PointOfInterestPosition;
			Vector3 vector = pointOfInterestPosition - position;
			float num = 0.05f;
			float magnitude = vector.magnitude;
			if (magnitude <= 2f * num)
			{
				return true;
			}
			Vector3 vector2 = vector / magnitude;
			Vector3 start = position + vector2 * num;
			Vector3 end = pointOfInterestPosition - vector2 * num;
			bool flag = Physics.CheckCapsule(start, end, num, 2048, QueryTriggerInteraction.Ignore);
			return !flag;
		}

		private void UpdatePointOfInterestFeedbackRendering(Player player, Camera camera, ScreenHUD hud)
		{
			Vector2 vector = Vector2.zero;
			bool flag = false;
			bool flag2 = false;
			bool flag3 = !nextLockOnPointOfInterest.IsNullOrInvalid();
			if (flag3)
			{
				Vector3 vector2 = camera.WorldToViewportPoint(nextLockOnPointOfInterest.PointOfInterestLabelPosition);
				vector = (Vector2)vector2 + pointOfInterestVisualViewportOffset;
			}
			if (HasLockedOnPointOfInterest && flag3)
			{
				flag2 = true;
			}
			else if (flag3)
			{
				flag = true;
			}
			hud.EnablePointOfInterestLockOnVisual(flag2);
			if (flag2)
			{
				hud.SetPointOfInterestLockOnVisualViewportSpacePosition(vector);
			}
			hud.EnablePointOfInterestPreviewVisual(flag);
			if (flag)
			{
				hud.SetPointOfInterestPreviewVisualViewportSpacePosition(vector);
			}
		}

		private void DisablePointOfInterestFeedbackRendering(ScreenHUD hud)
		{
			hud.EnablePointOfInterestLockOnVisual(enabled: false);
			hud.EnablePointOfInterestPreviewVisual(enabled: false);
		}
	}
}
namespace RecRoom.Core
{
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Player Settings/Screen Player Ranged Weapon Accuracy Settings", fileName = "ScreenPlayerRangedWeaponAccuracySettings")]
	public class ScreenPlayerRangedWeaponAccuracySettings : ScriptableObject
	{
		[Header("Canonical Spread Radius")]
		[SerializeField]
		private float canonicalMaxSpreadRadius;

		[Header("Dynamic Spread Radius")]
		[SerializeField]
		private float dynamicSpreadRadiusChangeTime = 0.2f;

		[SerializeField]
		private float walkingSpreadRadiusScaler = 1f;

		[SerializeField]
		private float sprintingSpreadRadiusScaler = 1f;

		[SerializeField]
		private float crouchingSpreadRadiusScaler = 1f;

		[SerializeField]
		private float aimDownSightsSpreadRadiusScaler = 1f;

		public float GetSpreadRadiusChangeTime()
		{
			return dynamicSpreadRadiusChangeTime;
		}

		public float GetSpreadRadius(Player player, bool isAimingDownSights)
		{
			float num = 1f;
			if (player.PlayerWalking.IsWalking)
			{
				num *= walkingSpreadRadiusScaler;
			}
			if (player.PlayerWalking.IsSprinting)
			{
				num *= sprintingSpreadRadiusScaler;
			}
			if (player.PlayerWalking.IsCrouching)
			{
				num *= crouchingSpreadRadiusScaler;
			}
			if (isAimingDownSights)
			{
				num *= aimDownSightsSpreadRadiusScaler;
			}
			return num * canonicalMaxSpreadRadius;
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Player Settings/Screen Player Ranged Weapon Crosshair Settings", fileName = "ScreenPlayerRangedWeaponCrosshairSettings")]
	public class ScreenPlayerRangedWeaponCrosshairSettings : ScriptableObject
	{
		[Header("Canonical Tick Spread")]
		[SerializeField]
		private float canonicalTickDistanceViewportSpace = 0.05f;

		[Header("Dynamic Tick Spread")]
		[SerializeField]
		private float dynamicTickDistanceChangeTime = 0.2f;

		[SerializeField]
		private float walkingTickDistanceScaler = 1f;

		[SerializeField]
		private float sprintingTickDistanceScaler = 1f;

		[SerializeField]
		private float crouchingTickDistanceScaler = 1f;

		[SerializeField]
		private float aimDownSightsTickDistanceScaler = 1f;

		public float GetTickDistanceChangeTime()
		{
			return dynamicTickDistanceChangeTime;
		}

		public float GetTickDistance(Player player, bool isAimingDownSights)
		{
			float num = 1f;
			if (player.PlayerWalking.IsWalking)
			{
				num *= walkingTickDistanceScaler;
			}
			if (player.PlayerWalking.IsSprinting)
			{
				num *= sprintingTickDistanceScaler;
			}
			if (player.PlayerWalking.IsCrouching)
			{
				num *= crouchingTickDistanceScaler;
			}
			if (isAimingDownSights)
			{
				num *= aimDownSightsTickDistanceScaler;
			}
			return num * canonicalTickDistanceViewportSpace;
		}
	}
}
