	[Serializable]
	public class FaceCameraForwardScreenPlayerSteering : ScreenPlayerSteeringController
	{
		[Header("Player Rotation")]
		[SerializeField]
		private float playerRotationSmoothTime = 0.1f;

		[Header("Player Body Part Rotation")]
		[SerializeField]
		private bool playerHeadAlignsWithGaze = true;

		[SerializeField]
		private float playerHeadRotationSmoothTime = 0.1f;

		[SerializeField]
		private bool playerHandsAlignWithGaze = true;

		[SerializeField]
		private float playerHandRotationSmoothTime = 0.1f;

		public override bool TryGetGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeOrigin)
		{
			gazeOrigin = camera.transform.position;
			gazeTarget = gazeOrigin + camera.transform.forward * 30f;
			return true;
		}

		public override void ApplySteering(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			GetCameraRelativeSurfaceCoordinateSpace(camera, out var right, out var _, out var forward);
			GetMoveVector(forward, right, input.WalkAxis, out var moveDirection, out var moveSpeedNormalized);
			playerController.MovePlayer(player, moveDirection, moveSpeedNormalized);
			playerController.SetPlayerSprintCoordinateSpace(player, forward);
			TryGetGazeTarget(playerController, player, camera, out var gazeTarget, out var _);
			Vector3 playerHeadPosition = playerController.GetPlayerHeadPosition(player);
			Vector3 normalized = (gazeTarget - playerHeadPosition).normalized;
			Vector3 normalized2 = Vector3.ProjectOnPlane(normalized, Vector3.up).normalized;
			playerController.RotatePlayer(player, normalized2, playerRotationSmoothTime);
			float num = Vector3.SignedAngle(normalized2, normalized, playerController.GetPlayerRightDirection(player));
			float targetPitch = ((!playerHeadAlignsWithGaze) ? 0f : num);
			playerController.SetHeadGazeAngles(0f, targetPitch, playerHeadRotationSmoothTime, playerHeadRotationSmoothTime);
			float targetPitch2 = ((!playerHandsAlignWithGaze) ? 0f : num);
			playerController.SetHandGazeAngles(targetPitch2, playerHandRotationSmoothTime);
		}
	}
