	[Serializable]
	public class FacePointOfInterestScreenPlayerSteering : ScreenPlayerSteeringController
	{
		[Header("Player Rotation")]
		[SerializeField]
		private float playerRotationSmoothTime = 0.1f;

		[SerializeField]
		private float playerBodyPitchRotationSmoothTime = 0.1f;

		[SerializeField]
		private float maxPitchRotationAngle = 60f;

		[Header("Sprint Configuration")]
		[SerializeField]
		private bool poiDefinesSprint = true;

		[NonSerialized]
		public IPlayerPointOfInterest PointOfInterest;

		public override bool TryGetGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeOrigin)
		{
			if (!PointOfInterest.IsNullOrInvalid())
			{
				gazeOrigin = playerController.GetPlayerHeadPosition(player);
				gazeTarget = PointOfInterest.PointOfInterestPosition;
				return true;
			}
			gazeOrigin = Vector3.zero;
			gazeTarget = Vector3.zero;
			return false;
		}

		public override void ApplySteering(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			if (!PointOfInterest.IsNullOrInvalid())
			{
				GetPlayerToPoiDirection(playerController, player, out var poiDirection, out var poiDirectionPlanar);
				Vector3 normalized = Vector3.Cross(Vector3.up, poiDirectionPlanar).normalized;
				GetCameraRelativeSurfaceCoordinateSpace(camera, out var right, out var _, out var forward);
				GetMoveVector(forward, right, input.WalkAxis, out var moveDirection, out var moveSpeedNormalized);
				playerController.MovePlayer(player, moveDirection, moveSpeedNormalized);
				playerController.RotatePlayer(player, poiDirectionPlanar, playerRotationSmoothTime);
				if (poiDefinesSprint)
				{
					playerController.SetPlayerSprintCoordinateSpace(player, poiDirectionPlanar);
				}
				else
				{
					playerController.SetPlayerSprintCoordinateSpace(player, moveDirection);
				}
				float targetPitch = Vector3.SignedAngle(poiDirectionPlanar, poiDirection, normalized);
				playerController.SetHeadGazeAngles(0f, targetPitch, playerBodyPitchRotationSmoothTime);
				playerController.SetHandGazeAngles(targetPitch, playerBodyPitchRotationSmoothTime);
			}
		}

		private void GetPlayerToPoiDirection(ScreenPlayerController playerController, Player player, out Vector3 poiDirection, out Vector3 poiDirectionPlanar)
		{
			Vector3 pointOfInterestPosition = PointOfInterest.PointOfInterestPosition;
			Vector3 playerHeadPosition = playerController.GetPlayerHeadPosition(player);
			poiDirection = (pointOfInterestPosition - playerHeadPosition).normalized;
			poiDirectionPlanar = Vector3.ProjectOnPlane(poiDirection, Vector3.up).normalized;
			Vector3 planeNormal = Vector3.Cross(Vector3.up, poiDirectionPlanar);
			Vector3 toDirection = Vector3.ProjectOnPlane(poiDirection, planeNormal);
			Quaternion quaternion = Quaternion.FromToRotation(poiDirectionPlanar, toDirection);
			Vector3 axis = Vector3.zero;
			float angle = 0f;
			quaternion.ToAngleAxis(out angle, out axis);
			angle = Mathf.Min(angle, maxPitchRotationAngle);
			quaternion = Quaternion.AngleAxis(angle, axis);
			poiDirection = quaternion * poiDirectionPlanar;
		}
	}
	[Serializable]
	public class FaceTargetScreenPlayerSteering : ScreenPlayerSteeringController
	{
		[Header("Player Rotation")]
		[SerializeField]
		private float playerRotationSmoothTime = 0.1f;

		[SerializeField]
		private float playerBodyPitchRotationSmoothTime = 0.1f;

		[SerializeField]
		private float maxPitchRotationAngle = 60f;

		[NonSerialized]
		public Transform TargetTransform;

		public override bool TryGetGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeOrigin)
		{
			if (TargetTransform != null)
			{
				gazeOrigin = playerController.GetPlayerHeadPosition(player);
				gazeTarget = TargetTransform.position;
				return true;
			}
			gazeOrigin = Vector3.zero;
			gazeTarget = Vector3.zero;
			return false;
		}

		public override void ApplySteering(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			if (!(TargetTransform == null))
			{
				GetPlayerToTargetDirection(playerController, player, out var targetDirection, out var targetDirectionPlanar);
				Vector3 normalized = Vector3.Cross(Vector3.up, targetDirectionPlanar).normalized;
				GetCameraRelativeSurfaceCoordinateSpace(camera, out var right, out var _, out var forward);
				GetMoveVector(forward, right, input.WalkAxis, out var moveDirection, out var moveSpeedNormalized);
				playerController.MovePlayer(player, moveDirection, moveSpeedNormalized);
				playerController.RotatePlayer(player, targetDirectionPlanar, playerRotationSmoothTime);
				playerController.SetPlayerSprintCoordinateSpace(player, targetDirectionPlanar);
				float targetPitch = Vector3.SignedAngle(targetDirectionPlanar, targetDirection, normalized);
				playerController.SetHeadGazeAngles(0f, targetPitch, playerBodyPitchRotationSmoothTime);
				playerController.SetHandGazeAngles(targetPitch, playerBodyPitchRotationSmoothTime);
			}
		}

		private void GetPlayerToTargetDirection(ScreenPlayerController playerController, Player player, out Vector3 targetDirection, out Vector3 targetDirectionPlanar)
		{
			Vector3 playerHeadPosition = playerController.GetPlayerHeadPosition(player);
			targetDirection = (TargetTransform.position - playerHeadPosition).normalized;
			targetDirectionPlanar = Vector3.ProjectOnPlane(targetDirection, Vector3.up).normalized;
			Vector3 planeNormal = Vector3.Cross(Vector3.up, targetDirectionPlanar);
			Vector3 toDirection = Vector3.ProjectOnPlane(targetDirection, planeNormal);
			Quaternion quaternion = Quaternion.FromToRotation(targetDirectionPlanar, toDirection);
			Vector3 axis = Vector3.zero;
			float angle = 0f;
			quaternion.ToAngleAxis(out angle, out axis);
			angle = Mathf.Min(angle, maxPitchRotationAngle);
			quaternion = Quaternion.AngleAxis(angle, axis);
			targetDirection = quaternion * targetDirectionPlanar;
		}
	}
	[Serializable]
	public class FaceVelocityScreenPlayerSteering : ScreenPlayerSteeringController
	{
		[Header("Player Rotation")]
		[SerializeField]
		private float playerRotationSmoothTime = 0.1f;

		public override bool TryGetGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeOrigin)
		{
			float playerHeadPitchAngle = playerController.GetPlayerHeadPitchAngle();
			Vector3 playerRightDirection = playerController.GetPlayerRightDirection(player);
			Vector3 playerForwardDirection = playerController.GetPlayerForwardDirection(player);
			Vector3 vector = Quaternion.AngleAxis(playerHeadPitchAngle, playerRightDirection) * playerForwardDirection;
			gazeOrigin = playerController.GetPlayerHeadPosition(player);
			gazeTarget = gazeOrigin + vector * 30f;
			return true;
		}

		public override void ApplySteering(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			GetCameraRelativeSurfaceCoordinateSpace(camera, out var right, out var _, out var forward);
			GetMoveVector(forward, right, input.WalkAxis, out var moveDirection, out var moveSpeedNormalized);
			playerController.MovePlayer(player, moveDirection, moveSpeedNormalized);
			Vector3 vector = playerController.GetPlayerForwardDirection(player);
			Vector3 playerMoveVelocity = playerController.GetPlayerMoveVelocity(player);
			if (playerMoveVelocity.sqrMagnitude >= 1E-05f)
			{
				vector = playerMoveVelocity.normalized;
			}
			playerController.SetPlayerSprintCoordinateSpace(player, vector);
			playerController.RotatePlayer(player, vector, playerRotationSmoothTime);
			playerController.SetHeadGazeAngles(0f, 0f);
			playerController.SetHandGazeAngles(0f);
		}
	}
