	public abstract class ScreenPlayerSteeringController
	{
		public abstract bool TryGetGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, out Vector3 gazeTarget, out Vector3 gazeOrigin);

		public abstract void ApplySteering(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input);

		protected void GetMoveVector(Vector3 forwardDirection, Vector3 rightDirection, Vector2 local2DMoveVector, out Vector3 moveDirection, out float moveSpeedNormalized)
		{
			moveSpeedNormalized = local2DMoveVector.magnitude;
			moveDirection = (local2DMoveVector.x * rightDirection + local2DMoveVector.y * forwardDirection).normalized;
		}

		protected void GetCameraRelativeSurfaceCoordinateSpace(Camera camera, out Vector3 right, out Vector3 up, out Vector3 forward)
		{
			up = Vector3.up;
			forward = Vector3.ProjectOnPlane(camera.transform.forward, Vector3.up).normalized;
			right = Vector3.Cross(up, forward).normalized;
		}

		protected void SteerTowardsTarget(Vector3 targetPosition, float slowdownDistance, float reachedDestinationDistance, ScreenPlayerController playerController, Player player, out Vector3 moveDirection, out float normalizedMoveSpeed)
		{
			moveDirection = Vector3.zero;
			normalizedMoveSpeed = 0f;
			Vector3 playerPosition = playerController.GetPlayerPosition(player);
			Vector3 vector = Vector3.ProjectOnPlane(targetPosition - playerPosition, Vector3.up);
			if (vector.sqrMagnitude > reachedDestinationDistance * reachedDestinationDistance)
			{
				float magnitude = vector.magnitude;
				moveDirection = vector / magnitude;
				normalizedMoveSpeed = Mathf.InverseLerp(0f, slowdownDistance, magnitude);
			}
		}
	}
}
