			VirtualKeyboardController = new VirtualKeyboardController();
		}

		public void OnEnterMode()
		{
			inputHandler = SingletonMonoBehaviour<InputManager>.Instance.ScreenInputHandler;
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = false;
			if (SingletonMonoBehaviour<SplashScreenSpawnPoint>.Instance != null)
			{
				UpdateSplashScreenMenuPosition(SingletonMonoBehaviour<SplashScreenSpawnPoint>.Instance);
			}
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			cursor.SetCursorSettings(screenModeHUD, cursorSettings);
			cursor.HideCursor(screenModeHUD);
			if (SingletonMonoBehaviour<ProfileSelectionManager>.Instance != null)
			{
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.OnSwitchToScreensMode();
			}
		}

		public void OnExitMode()
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD.WorldSpaceUIAnchor.Detach();
		}

		public void OnUpdate()
		{
			VirtualKeyboardController.OnUpdate();
			UpdateProfileSelectionMenu();
			bool isHoveringSelectable = UpdateMenuInput(inputHandler);
			UpdateCursorPosition(inputHandler, isHoveringSelectable);
		}

		public void OnLateUpdate()
		{
		}

		public void OnLocalPlayerCreated()
		{
		}

		public void OnLocalPlayerDestroyed()
		{
		}

