		}

		public void OnSplashScreenLoad(SplashScreenSpawnPoint splashScreenSpawnPoint)
		{
			UpdateSplashScreenMenuPosition(splashScreenSpawnPoint);
		}

		public bool TryPickupSpawnTool(Player player, PlayerHand hand, Tool tool)
		{
			return false;
		}

		public void OnDrawGizmos()
		{
		}

		private void UpdateSplashScreenMenuPosition(SplashScreenSpawnPoint splashScreenSpawnPoint)
		{
			if (splashScreenSpawnPoint != null && splashScreenSpawnPoint.ScreenSpawnPoint != null)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera.transform.position = splashScreenSpawnPoint.ScreenSpawnPoint.position;
				SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera.transform.rotation = splashScreenSpawnPoint.ScreenSpawnPoint.rotation;
			}
		}

		private void UpdateCursorPosition(ScreenInputHandler input, bool isHoveringSelectable)
		{
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (input.UsingKeyboardMouse)
			{
				cursor.SetCursorScreenPosition(screenModeHUD, screenModeCamera, gameViewFocused, input.CursorMouseScreenPosition);
			}
			else
			{
				cursor.AccelerateCursor(screenModeHUD, input.CursorAxis, gameViewFocused, isHoveringSelectable);
			}
			cursor.UpdateMode(input.UsingKeyboardMouse, screenModeHUD);
			cursor.HandleScreenResolutionChanges(screenModeHUD);
		}

		private bool UpdateMenuInput(ScreenInputHandler input)
		{
			Camera screenModeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeCamera;
			Ray ray = cursor.GetRay(screenModeCamera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, float.MaxValue, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, input.CursorButtonDown, input.CursorButtonUp);
			if (result.UISelectable)
			{
				SetLaserButtonPushed(input.CursorButtonDown, input.CursorButtonUp, PhotonNetwork.player, result.LaserPushButton);
			}
			return result.UISelectable;
		}

		private void SetLaserButtonPushed(bool inputDown, bool inputUp, PhotonPlayer player, PhysicalButtonBase button)
		{
			if (button != null && inputDown)
			{
				if (button != latestPushedButton)
				{
					ReleaseLatestPushedButton(player);
				}
				latestPushedButton = button;
				button.LaserPress(player);
			}
			if (inputUp || button == null)
			{
				ReleaseLatestPushedButton(player);
			}
		}

		private void ReleaseLatestPushedButton(PhotonPlayer player)
		{
			if (latestPushedButton != null)
			{
				latestPushedButton.LaserRelease(player);
				latestPushedButton = null;
			}
		}

		private void UpdateProfileSelectionMenu()
		{
			ScreenHUD screenModeHUD = SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD;
			if (!SingletonMonoBehaviour<ProfileSelectionManager>.IsInitialized || SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI == null)
			{
				if (cursor.IsCursorEnabled(screenModeHUD))
				{
					cursor.HideCursor(screenModeHUD);
				}
			}
			else if (SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD.WorldSpaceUIAnchor.AttachedUI != SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ScreenModeHUD.WorldSpaceUIAnchor.Attach(SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI, menuVerticalBufferPercentage, resetPositionOnDetach: true);
				cursor.ShowCursor(screenModeHUD);
				cursor.SnapToCenter(screenModeHUD);
			}
		}
	}
}
