				MakerPenPaletteMainScreen paletteMainScreen4 = MakerPen.PaletteMainScreen;
				paletteMainScreen4.InventionSelectionButtonPressed = (Action<Invention>)Delegate.Remove(paletteMainScreen4.InventionSelectionButtonPressed, new Action<Invention>(OnMakerPenMenuInventionSelected));
				Inventions.OnInventionUpdated -= OnInventionUpdated;
				MakerPen makerPen2 = MakerPen;
				makerPen2.ConfigurationMenuRequested = (Action<IConfigurable>)Delegate.Remove(makerPen2.ConfigurationMenuRequested, new Action<IConfigurable>(OnMakerPenMenuConfigurationFlowRequested));
				MakerPen makerPen3 = MakerPen;
				makerPen3.InventionDetailsRequested = (Action<Invention>)Delegate.Remove(makerPen3.InventionDetailsRequested, new Action<Invention>(OnMakerPenMenuInventionDetailsFlowRequested));
				MakerPen makerPen4 = MakerPen;
				makerPen4.InventionUpdateRequested = (Action<Invention>)Delegate.Remove(makerPen4.InventionUpdateRequested, new Action<Invention>(OnMakerPenMenuInventionUpdateRequested));
				MakerPen makerPen5 = MakerPen;
				makerPen5.InventionObjectsSelectionCancelled = (Action)Delegate.Remove(makerPen5.InventionObjectsSelectionCancelled, new Action(OnMakerPenMenuInventionCreationCancelled));
				toolStateMachine.EnterState(ushort.MaxValue);
				offHandStateMachine.EnterState(ushort.MaxValue);
			}
			if (CreationContext != null)
			{
				CreationContext.SelectionChangedEvent -= OnObjectSelectionChange;
				CreationContext.ShapeCreationContext.SelectionChangedEvent -= OnShapeSelectionChange;
				CreationContext.RemoveAllFromSelection();
				CreationContext.ShapeCreationContext.RemoveAllFromSelection();
				CreationContext = null;
			}
			playerController.RemoveToolPickupCondition(PlayerToolPickupCondition);
			MakerPen = null;
			OffHand = null;
			OffHandInput = null;
			ToolInput = null;
		}

		public bool OnUpdate(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			toolStateMachine.Update();
			offHandStateMachine.Update();
			if (toolInput.HairTriggerButtonUp)
			{
				MakerPen.FireToolUsedEvent();
			}
			return true;
		}

		private void OnObjectSelectionChange()
		{
			if (MakerPen.CurrentTargetMode == MakerPen.TargetMode.Object && CreationContext.SelectionCount == 1)
			{
				MakerPen.MoveablePaletteMenu.UpdateConfigFlow(CreationContext.CurrentSelection.First());
			}
			else
			{
				MakerPen.MoveablePaletteMenu.UpdateConfigFlow(null);
			}
		}

		private void OnShapeSelectionChange()
		{
			if (MakerPen.CurrentTargetMode == MakerPen.TargetMode.Shape)
			{
				MakerPen.MoveablePaletteMenu.UpdateConfigFlow(CreationContext.ShapeCreationContext.GetConfigurableForShapeSelection());
			}
		}

		private void OnMakerPenMenuToolSelected(MakerPen.ToolMode selectedToolType)
		{
			MakerPen.TargetMode targetMode = MakerPen.TargetMode.Object;
			targetMode = selectedToolType switch
			{
				MakerPen.ToolMode.Connect => MakerPen.TargetMode.Object, 
				MakerPen.ToolMode.CreateObject => MakerPen.TargetMode.Object, 
				MakerPen.ToolMode.CreateTrigger => MakerPen.TargetMode.Shape, 
				MakerPen.ToolMode.CreateInventionInstance => MakerPen.TargetMode.Object, 
				_ => MakerPen.CurrentTargetMode, 
			};
			MakerPen.AuthoritySelectMode(selectedToolType, targetMode);
			if (selectedToolType == MakerPen.ToolMode.CreateObject || selectedToolType == MakerPen.ToolMode.CreateShape || selectedToolType == MakerPen.ToolMode.Repaint)
			{
				MakerPen.AuthorityShowPaletteMainScreen((selectedToolType != MakerPen.ToolMode.CreateObject) ? MakerPenPaletteMainScreen.DisplayMode.ShapesAndColors : MakerPenPaletteMainScreen.DisplayMode.Props);
			}
		}

		private void OnUndoRequest()
		{
			MakerPen.TriggerUndo();
		}

		private void OnRedoRequest()
		{
			MakerPen.TriggerRedo();
		}

		private void OnExitEditRequest()
		{
			MakerPen.AuthoritySelectMode(MakerPen.CurrentToolMode, MakerPen.TargetMode.Object);
		}

		private void OnCreateInventionRequest()
		{
			MakerPen.MoveablePaletteMenu.ShowInventionCreationFlow(null);
			MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateInvention, MakerPen.TargetMode.Object);
		}

		private void OnPaletteMenuRequest()
		{
			if (MakerPen.MoveablePaletteMenu.IsMenuVisible)
			{
				MakerPen.AuthorityHidePaletteMenu();
			}
			else
			{
				MakerPen.AuthorityShowPaletteMenu();
			}
		}

		private void OnMakerPenMenuShapeTypeSelected(ShapeType selectedShapeType)
		{
			MakerPen.SelectShapeType(selectedShapeType);
			MakerPen.PaletteMainScreen.SelectShapeButton(selectedShapeType);
			MakerPen.TargetMode currentTargetMode = MakerPen.CurrentTargetMode;
			MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateShape, currentTargetMode);
		}

		private void OnMakerPenMenuShapeColorSelected(ShapeColor selectedShapeColor)
		{
			MakerPen.SelectShapeColor(selectedShapeColor);
		}

		private void OnMakerPenMenuSpawnableToolTypeSelected(SpawnableToolType selectedSpawnableToolType)
		{
			MakerPen.SelectSpawnableToolTypeToCreate(selectedSpawnableToolType);
			MakerPen.PaletteMainScreen.SelectPropButton(selectedSpawnableToolType);
			if (selectedSpawnableToolType == SpawnableToolType.TRIGGER_VOLUME)
			{
				MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateTrigger, MakerPen.TargetMode.Object);
			}
			else
			{
				MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateObject, MakerPen.TargetMode.Object);
			}
		}

		private void OnMakerPenMenuInventionSelected(Invention selectedInvention)
		{
			MakerPen.SelectInventionToCreate(selectedInvention);
			MakerPen.PaletteMainScreen.SelectInventionButton(selectedInvention);
			MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateInventionInstance, MakerPen.TargetMode.Object);
		}

		private void OnInventionUpdated(long inventionId)
		{
			if (MakerPen.SelectedInvention != null && MakerPen.SelectedInvention.InventionId == inventionId)
			{
				Invention inventionCached = Inventions.GetInventionCached(inventionId);
				MakerPen.SelectInventionToCreate(inventionCached);
			}
		}

		private void OnMakerPenMenuConfigurationFlowRequested(IConfigurable configurable)
		{
			MakerPen.MoveablePaletteMenu.ShowConfigFlow(configurable);
		}

		private void OnMakerPenMenuInventionDetailsFlowRequested(Invention invention)
		{
			MakerPen.MoveablePaletteMenu.ShowInventionDetailsFlow(invention);
		}

		private void OnMakerPenMenuInventionUpdateRequested(Invention invention)
		{
			MakerPen.MoveablePaletteMenu.ShowInventionCreationFlow(invention);
			MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateInvention, MakerPen.TargetMode.Object);
		}

		private void OnMakerPenMenuInventionCreationCancelled()
		{
			if (MakerPen.CurrentToolMode == MakerPen.ToolMode.CreateInvention)
			{
				MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Select, MakerPen.TargetMode.Object);
			}
		}

		private bool PlayerToolPickupCondition(Tool tool, Player player, Vector3 pickupPosition, bool inPhysicalPickupRange)
		{
			return tool == MakerPen.Tool || tool == MakerPen.MoveablePaletteMenu.Tool;
		}

		private void RegisterTool(MakerPen.TargetMode targetMode, MakerPen.ToolMode toolMode, MakerPenVRTool vrTool)
		{
			vrTool.Initialize(this, targetMode, toolMode);
			toolStateMachine.AddState((ushort)targetMode, (ushort)toolMode, vrTool.OnEnterState, vrTool.OnExitState, vrTool.OnUpdateState);
		}

		private void RegisterOffHandOperation(MakerPen.TargetMode targetMode, MakerPenVROffHandOperation offHandOperation)
		{
			offHandOperation.Initialize(this);
			offHandStateMachine.AddState((ushort)targetMode, offHandOperation.OnEnterState, offHandOperation.OnExitState, offHandOperation.OnUpdateState);
		}

		private void OnMakerPenModeChanged(MakerPen.ToolMode toolMode, MakerPen.TargetMode targetMode)
		{
			if (targetMode != lastPenTargetMode && targetMode == MakerPen.TargetMode.Object)
			{
				CreationContext.ShapeCreationContext.DeselectShapeContainer();
			}
			toolStateMachine.EnterState((ushort)targetMode, (ushort)toolMode);
			MakerPen.TargetMode targetMode2 = ((toolMode != MakerPen.ToolMode.Disabled) ? targetMode : MakerPen.TargetMode.Invalid);
			offHandStateMachine.EnterState((ushort)targetMode2, (ushort)toolMode);
			lastPenTargetMode = targetMode;
		}
	}
}
namespace RecRoom
{
	[Serializable]
	public class VRPlayerController : IPlayerController
	{
		public delegate bool PickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup);

		private const float HAIR_TRIGGER_REACTION_WINDOW = 0.25f;

		private const float BOTH_HAND_BUTTON_PRESS_WINDOW = 0.2f;

		private const float OUTFIT_FORWARD_PICKUP_RANGE = 0.15f;

		private const float OUTFIT_BACKWARD_PICKUP_RANGE = 0.1f;

		[Header("VR Movement Input")]
		[SerializeField]
		private VRMovementController[] movementComponentPrefabs;

		[Header("UI Interaction Settings")]
