		private ShareCamera ShareCam
		{
			get
			{
				if (_shareCam == null && Player.LocalPlayerExists)
				{
					Tool backpackTool = Player.LocalPlayer.Backpack.GetBackpackTool(PlayerBackpackToolType.SHARE_CAM);
					if (backpackTool != null)
					{
						_shareCam = backpackTool.GetComponent<ShareCamera>();
					}
				}
				return _shareCam;
			}
