		public VRInputHandler LeftHandInput => leftHandInput;

		public VRInputHandler RightHandInput => rightHandInput;

		private TeleportationPortal LeftHandHoveredPortal
		{
			get
			{
				return _leftHandHoveredPortal;
			}
			set
			{
				if (!(_leftHandHoveredPortal == value))
				{
					if (_leftHandHoveredPortal != null)
					{
						_leftHandHoveredPortal.Highlight = false;
					}
					_leftHandHoveredPortal = value;
					if (_leftHandHoveredPortal != null)
					{
						_leftHandHoveredPortal.Highlight = true;
					}
				}
			}
		}

		private TeleportationPortal RightHandHoveredPortal
		{
			get
			{
