				if (!(_rightHandHoveredPortal == value))
				{
					if (_rightHandHoveredPortal != null)
					{
						_rightHandHoveredPortal.Highlight = false;
					}
					_rightHandHoveredPortal = value;
					if (_rightHandHoveredPortal != null)
					{
						_rightHandHoveredPortal.Highlight = true;
					}
				}
			}
