		public void AddToolPickupCondition(PickupCondition condition)
		{
			pickupConditions.Add(condition);
		}

		public void RemoveToolPickupCondition(PickupCondition condition)
		{
			pickupConditions.Remove(condition);
		}

		public void Initialize(LocalPlayerController localPlayerController)
		{
			VRMovementController[] array = movementComponentPrefabs;
			foreach (VRMovementController original in array)
			{
				VRMovementController item = UnityEngine.Object.Instantiate(original, localPlayerController.transform, worldPositionStays: false);
				movementComponents.Add(item);
			}
		}

		public void OnEnterMode()
		{
			RigidbodyEx.FollowProxiesWithPhysics = true;
			RigidbodyPickup.GlobalJointPickupEnabled = true;
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = false;
			SingletonMonoBehaviour<InputManager>.Instance.VRInputHandlersChangedEvent += CacheHandInputHandlers;
			CacheHandInputHandlers();
			if (Player.LocalPlayerExists)
			{
				OnLocalPlayerCreated();
			}
		}

		public void OnExitMode()
		{
			if (SingletonMonoBehaviour<InputManager>.Instance != null)
			{
				SingletonMonoBehaviour<InputManager>.Instance.VRInputHandlersChangedEvent -= CacheHandInputHandlers;
			}
			UnsubscribeFromHandInputHandlers();
			if (Player.LocalPlayerExists)
			{
				CleanupLocalPlayer();
			}
		}

		public void OnUpdate()
		{
			if (Player.LocalPlayerExists)
			{
				Player localPlayer = Player.LocalPlayer;
				localPlayer.UpdateAFKStatus(SingletonMonoBehaviour<VRDeviceManager>.Instance.UserInHMD);
				UpdateHeadTransform(localPlayer.Head);
				UpdateHandActions(localPlayer, localPlayer.LeftHand, localPlayer.RightHand, leftHandInput, rightHandInput);
				UpdateHandActions(localPlayer, localPlayer.RightHand, localPlayer.LeftHand, rightHandInput, leftHandInput);
				UpdateShareCamera(localPlayer, leftHandInput, rightHandInput);
				UpdatePushToTalk(localPlayer, leftHandInput, rightHandInput);
				UpdateUIComponents(localPlayer, localPlayer.LeftHand, leftHandInput, localPlayer.RightHand, rightHandInput);
				UpdateMovementComponents(localPlayer, localPlayer.LeftHand, leftHandInput, localPlayer.RightHand, rightHandInput);
			}
		}

		public void OnLateUpdate()
		{
			if (Player.LocalPlayerExists)
			{
				UpdateTrackingSpace(Player.LocalPlayer.TrackingSpace);
			}
		}

		public void OnLocalPlayerCreated()
		{
			InitializePlayerOnEnterMode();
		}

		public void OnLocalPlayerDestroyed()
		{
			CleanupLocalPlayer();
		}

		public void OnSplashScreenLoad(SplashScreenSpawnPoint splashScreenSpawnPoint)
		{
		}

		public Player InstantiateLocalPlayer(Vector3 position, Quaternion rotation)
		{
			Player result = null;
			if (!Player.LocalPlayerExists)
			{
				Vector3 vector = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position);
				Vector3 vector2 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(leftHandInput.WorldSpaceTrackedPosition);
				Vector3 vector3 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(rightHandInput.WorldSpaceTrackedPosition);
				Quaternion quaternion = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.rotation);
				Quaternion quaternion2 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(leftHandInput.WorldSpaceTrackedRotation);
				Quaternion quaternion3 = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(rightHandInput.WorldSpaceTrackedRotation);
				Quaternion identity = Quaternion.identity;
				identity = Quaternion.Euler(0f, quaternion.eulerAngles.y, 0f);
				object[] data = new object[8] { vector, quaternion, vector2, quaternion2, vector3, quaternion3, position, rotation };
				rotation *= Quaternion.Inverse(identity);
				position -= rotation * SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCameraFloorOffsetLocalSpace;
				GameObject gameObject = PhotonNetwork.Instantiate("[Player]", position, rotation, 1f, 0, data);
				result = gameObject.GetComponent<Player>();
			}
			return result;
		}

		public bool TryPickupSpawnTool(Player player, PlayerHand hand, Tool tool)
		{
			return hand.TryPickupTool(tool, inPhysicalPickupRange: false, forceSnapPosition: true);
		}

		public void OnDrawGizmos()
		{
		}

		private void InitializePlayerOnEnterMode()
		{
			Player localPlayer = Player.LocalPlayer;
			UpdateTrackingSpace(localPlayer.TrackingSpace);
			InitializeHandOnEnterMode(localPlayer.LeftHand, leftHandInput);
			InitializeHandOnEnterMode(localPlayer.RightHand, rightHandInput);
			InitializeMovementComponentsOnEnterMode(localPlayer);
			localPlayer.DynamicDominantHandEnabled = true;
			localPlayer.PlayerWalking.StopCrouch();
			localPlayer.ToolEquipSlots.AutomaticallyEquipToolOnDrop = true;
			localPlayer.ToolEquipSlots.HotSwapToolOnDrop = true;
			localPlayer.PlayerUI.WatchMenuProjector.WatchGazeOpeningEnabled = true;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
			{
				localPlayer.PlayerLocomotion.PauseGravity(this);
			}
			localPlayer.PlayerLocomotion.SupportsRoomScaleMovement = true;
			localPlayer.PlayerLocomotion.CanCollideWithPlayers = true;
			localPlayer.PlayerChaperone.RoomCenterVisualEnabled = true;
			localPlayer.BlobShadowProjector.AddBlobShadowsRestriction(this);
		}

		private void CleanupLocalPlayer()
		{
			Player localPlayer = Player.LocalPlayer;
			if (localPlayer != null)
			{
				localPlayer.PlayerLocomotion.ResumeGravity(this);
				localPlayer.BlobShadowProjector.RemoveBlobShadowsRestriction(this);
				ResetHandOnExitMode(localPlayer.LeftHand);
				ResetHandOnExitMode(localPlayer.RightHand);
				ResetMovementComponentsOnExitMode(localPlayer);
			}
		}

		private void UpdateTrackingSpace(PlayerTrackingSpace trackingSpace)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.transform.position = trackingSpace.RigidbodyEx.physicsPosition;
			SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = trackingSpace.RigidbodyEx.physicsRotation;
		}

		private void UpdateHeadTransform(PlayerHead head)
		{
			head.RigidbodyEx.targetLocalPosition = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position);
			head.RigidbodyEx.targetLocalRotation = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.rotation);
			head.RigidbodyEx.localVelocity = Vector3.zero;
			head.RigidbodyEx.localAngularVelocity = Vector3.zero;
		}

		private void CacheHandInputHandlers()
		{
			UnsubscribeFromHandInputHandlers();
			leftHandInput = SingletonMonoBehaviour<InputManager>.Instance.LeftHandVRInputHandler;
			leftHandInput.TransformUpdateEvent += OnLeftHandTrackerUpdate;
			rightHandInput = SingletonMonoBehaviour<InputManager>.Instance.RightHandVRInputHandler;
			rightHandInput.TransformUpdateEvent += OnRightHandTrackerUpdate;
		}

		private void UnsubscribeFromHandInputHandlers()
		{
			if (leftHandInput != null)
			{
				leftHandInput.TransformUpdateEvent -= OnLeftHandTrackerUpdate;
			}
			if (rightHandInput != null)
			{
				rightHandInput.TransformUpdateEvent -= OnRightHandTrackerUpdate;
			}
		}

		private VRToolController GetCurrentHandToolActionController(PlayerHand hand)
		{
			return (hand.Type != PlayerHand.HandType.Left) ? currentRightHandToolActionController : currentLeftHandToolActionController;
		}

		private void SetCurrentHandToolActionController(VRToolController controller, PlayerHand holderHand, PlayerHand otherHand, VRInputHandler holderHandInput, VRInputHandler otherHandInput)
		{
			VRToolController vRToolController = null;
			if (holderHand.Type == PlayerHand.HandType.Left)
			{
				vRToolController = currentLeftHandToolActionController;
				currentLeftHandToolActionController = controller;
			}
			else
			{
				vRToolController = currentRightHandToolActionController;
				currentRightHandToolActionController = controller;
			}
			if (vRToolController != null)
			{
				vRToolController.OnStop(this, holderHand.ThisPlayer, holderHand.HeldTool, holderHand, otherHand, holderHandInput, otherHandInput);
			}
		}

		private void InitializeHandOnEnterMode(PlayerHand hand, VRInputHandler input)
		{
			if (hand != null)
			{
				hand.VibrateEvent += OnVibrateEvent;
				if (input != null)
				{
					hand.RigidbodyEx.useFixedTime = input.VelocityRollbackUsesFixedTimestep;
				}
			}
		}

		private void ResetHandOnExitMode(PlayerHand hand)
		{
			if (hand != null)
			{
				hand.VibrateEvent -= OnVibrateEvent;
				hand.RigidbodyEx.useFixedTime = false;
			}
		}

		private void OnLeftHandTrackerUpdate(VRInputHandler input)
		{
			if (Player.LocalPlayerExists)
			{
				OnHandTrackerUpdate(Player.LocalPlayer.LeftHand, Player.LocalPlayer.RightHand, leftHandInput, rightHandInput);
			}
		}

		private void OnRightHandTrackerUpdate(VRInputHandler input)
		{
			if (Player.LocalPlayerExists)
			{
				OnHandTrackerUpdate(Player.LocalPlayer.RightHand, Player.LocalPlayer.LeftHand, rightHandInput, leftHandInput);
			}
		}

		private void OnHandTrackerUpdate(PlayerHand thisHand, PlayerHand otherHand, VRInputHandler thisHandInput, VRInputHandler otherHandInput)
		{
			thisHand.RigidbodyEx.targetLocalPosition = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(thisHandInput.WorldSpaceTrackedPosition);
			thisHand.RigidbodyEx.targetLocalRotation = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformRotation(thisHandInput.WorldSpaceTrackedRotation);
			thisHand.RigidbodyEx.localVelocity = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformVector(thisHandInput.LinearVelocity);
			thisHand.RigidbodyEx.localAngularVelocity = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformVector(thisHandInput.AngularVelocity);
			if ((thisHand.Type == PlayerHand.HandType.Left && delayedReleaseOfLeftHandHeldTool) || (thisHand.Type == PlayerHand.HandType.Right && delayedReleaseOfRightHandHeldTool))
			{
				ReleaseHeldToolInternal(thisHand, otherHand, thisHandInput, otherHandInput);
			}
			else if ((thisHand.Type == PlayerHand.HandType.Left && delayedLeftHandVelocityTriggerRelease) || (thisHand.Type == PlayerHand.HandType.Right && delayedRightHandVelocityTriggerRelease))
			{
				ReleaseTriggerWithVelocityInternal(thisHand, thisHandInput);
			}
		}

		private void OnVibrateEvent(PlayerHand hand, int milliseconds, float intensity)
		{
			if (hand.Type == PlayerHand.HandType.Left)
			{
				leftHandInput.Vibrate(milliseconds, intensity);
			}
			else if (hand.Type == PlayerHand.HandType.Right)
			{
				rightHandInput.Vibrate(milliseconds, intensity);
			}
		}

		private void UpdateHandActions(Player player, PlayerHand thisHand, PlayerHand otherHand, VRInputHandler thisHandInput, VRInputHandler otherHandInput)
		{
			if (!(thisHand == null))
			{
				UpdateHandConnectedState(thisHand, thisHandInput);
				if (thisHandInput != null)
				{
					UpdateHandHoveredToolSelection(player, thisHand);
					UpdateHandOutfitTriggerSelection(player, thisHand);
					UpdateHandHeldToolInteraction(player, thisHand, otherHand, thisHandInput, otherHandInput);
					UpdateHandMenuInteraction(thisHand, thisHandInput);
					UpdateHandPortalInteraction(player, thisHand, thisHandInput);
					UpdateHandOpenCloseAnimation(thisHand, thisHandInput);
				}
			}
		}

		private void UpdateHandConnectedState(PlayerHand hand, VRInputHandler input)
		{
			if (input == null)
			{
				hand.HandConnectedState = PlayerHand.ConnectedState.NOT_CONNECTED;
			}
			else if (!input.IsConnected)
			{
				hand.HandConnectedState = PlayerHand.ConnectedState.NOT_CONNECTED;
			}
			else if (!input.IsTracking)
			{
				hand.HandConnectedState = PlayerHand.ConnectedState.NOT_TRACKING;
			}
			else
			{
				hand.HandConnectedState = PlayerHand.ConnectedState.CONNECTED_AND_TRACKING;
			}
		}

		private void UpdateHandHoveredToolSelection(Player player, PlayerHand hand)
		{
			bool inPhysicalPickupRange = false;
			if (CanPlayerHoverTools(player, hand))
			{
				Tool tool = FindToolInShoulderSlot(player, hand);
				if (tool == null)
				{
					tool = FindClosestToolToHandInPhysicalPickupRange(player, hand);
				}
				if (tool != null)
				{
					inPhysicalPickupRange = true;
				}
				else
				{
					tool = FindClosestToolToHandInMagnetPickupRange(player, hand);
				}
				if (tool != null)
				{
					hand.SetHoveredTool(tool, inPhysicalPickupRange);
				}
				else
				{
					hand.ClearHoveredTool();
				}
			}
			else
			{
				hand.ClearHoveredTool();
			}
		}

		private void UpdateHandHeldToolInteraction(Player player, PlayerHand holderHand, PlayerHand otherHand, VRInputHandler holderHandInput, VRInputHandler otherHandInput)
		{
			bool hairPickupButtonDown = holderHandInput.HairPickupButtonDown;
			bool hairPickupButtonUp = holderHandInput.HairPickupButtonUp;
			bool flag = holderHandInput.MenuButtonUp && Player.LocalPlayer.PlayerUI.HandUsingExpresso != holderHand;
			bool flag2 = holderHandInput.HairTriggerButtonDown || (holderHandInput.HairTriggerButtonPressed && !holderHandInput.HairTriggerButtonDownConsumed && UnityEngine.Time.unscaledTime - holderHandInput.HairTriggerButtonDownTime <= 0.25f);
			bool hairTriggerButtonPressed = holderHandInput.HairTriggerButtonPressed;
			bool hairTriggerButtonUp = holderHandInput.HairTriggerButtonUp;
			float triggerAxis = holderHandInput.TriggerAxis;
			Tool heldTool = holderHand.HeldTool;
			if (heldTool != null)
			{
				if (heldTool.IsLocked)
				{
					if (heldTool.IsVisible)
					{
						heldTool.InputAmount = triggerAxis;
						if (!(heldTool.PlayerSpawnedEquipment != null) || heldTool.PlayerSpawnedEquipment.ToolPurpose != PlayerSpawnedEquipment.Purpose.GiftBox)
						{
							VRToolController newActiveController = GetCurrentHandToolActionController(holderHand);
							if (newActiveController == null)
							{
								if (TryStartHeldToolAction(heldTool.HolderPlayer, heldTool, holderHand, otherHand, holderHandInput, otherHandInput, out newActiveController))
								{
									newActiveController.OnStart(this, heldTool.HolderPlayer, heldTool, holderHand, otherHand, holderHandInput, otherHandInput);
									SetCurrentHandToolActionController(newActiveController, holderHand, otherHand, holderHandInput, otherHandInput);
								}
							}
							else if (!newActiveController.OnUpdate(this, heldTool.HolderPlayer, heldTool, holderHand, otherHand, holderHandInput, otherHandInput))
							{
								SetCurrentHandToolActionController(null, holderHand, otherHand, holderHandInput, otherHandInput);
							}
							if (flag2)
							{
								heldTool.InputDown();
								holderHandInput.HairTriggerButtonDownConsumed = true;
							}
							if (hairTriggerButtonPressed)
							{
								heldTool.InputPressed();
							}
							if (hairTriggerButtonUp)
							{
								heldTool.InputUp();
								TryReleaseTriggerWithVelocity(holderHand, holderHandInput);
							}
							if (heldTool.SupportsRemoteControlInput)
							{
								heldTool.RemoteControlInput(holderHandInput.RCControlStickAxis, holderHandInput.RCTriggerAxis, holderHandInput.RCMainButtonPressed);
							}
						}
					}
					if (flag && !holderHand.ThisPlayer.PlayerUI.HandUsingExpresso == (bool)holderHand && holderHand.LocalUnlockHeldTool())
					{
						holderHandInput.Vibrate(500);
						if (!hairTriggerButtonPressed)
						{
							TryReleaseToolFromHand(holderHand, otherHand, holderHandInput, otherHandInput);
						}
					}
				}
				else if (flag && heldTool.CanBeLocked)
				{
					holderHand.LocalLockHeldTool();
					holderHandInput.Vibrate(500);
				}
				else if (hairPickupButtonUp)
				{
					holderHandInput.HairPickupButtonDownConsumed = true;
					TryReleaseToolFromHand(holderHand, otherHand, holderHandInput, otherHandInput);
				}
			}
			else if (holderHand.HandConnectedState != PlayerHand.ConnectedState.NOT_CONNECTED)
			{
				VRToolController currentHandToolActionController = GetCurrentHandToolActionController(holderHand);
				if (currentHandToolActionController != null)
				{
					SetCurrentHandToolActionController(null, holderHand, otherHand, holderHandInput, otherHandInput);
				}
				holderHand.GetHoveredTool(out var hoveredTool, out var inPhysicalPickupRange);
				if (holderHand.TryRemoveTriggeredOutfit(hairPickupButtonDown))
				{
					holderHandInput.HairPickupButtonDownConsumed = true;
				}
				else if (hoveredTool != null && hairPickupButtonDown && IsValidToolPickup(player, hoveredTool, holderHand.transform.position, inPhysicalPickupRange))
				{
					holderHand.TryPickupTool(hoveredTool, inPhysicalPickupRange);
					holderHandInput.HairPickupButtonDownConsumed = true;
				}
			}
		}

		private bool TryStartHeldToolAction(Player player, Tool tool, PlayerHand holderHand, PlayerHand otherHand, VRInputHandler holderHandInput, VRInputHandler otherHandInput, out VRToolController newActiveController)
		{
