			for (int i = 0; i < tool.VRActionControllers.Length; i++)
			{
				VRToolController vRToolController = tool.VRActionControllers[i];
				if (vRToolController != null && vRToolController.CanStart(this, player, tool, holderHand, otherHand, holderHandInput, otherHandInput))
				{
					newActiveController = vRToolController;
					return true;
				}
			}
			return false;
		}

