		private void UpdateHandPortalInteraction(Player player, PlayerHand hand, VRInputHandler input)
		{
			TeleportationPortal closestTeleportationPortal = GetClosestTeleportationPortal(player, hand);
			if (hand.Type == PlayerHand.HandType.Left)
			{
				LeftHandHoveredPortal = closestTeleportationPortal;
			}
			else
			{
				RightHandHoveredPortal = closestTeleportationPortal;
			}
			if (closestTeleportationPortal != null)
			{
				closestTeleportationPortal.RenderHighlight();
			}
			if (hand.HeldTool != null && hand.HeldTool.IsLocked && closestTeleportationPortal != null)
			{
				hand.CustomVisualState = PlayerHand.VisualState.DefaultHand;
			}
			else
			{
				hand.CustomVisualState = null;
			}
			if (closestTeleportationPortal != null && input.HairPickupButtonDown)
			{
				closestTeleportationPortal.Use(player);
				closestTeleportationPortal = null;
			}
		}

		public TeleportationPortal GetClosestTeleportationPortal(Player player, PlayerHand hand)
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
			{
				return null;
			}
			if (hand.IsMenuLaserEnabled())
			{
				return null;
			}
			Tool hoveredTool = null;
			hand.GetHoveredTool(out hoveredTool, out var _);
			if (hoveredTool != null)
			{
				return null;
			}
			Vector3 targetPosition = hand.RigidbodyEx.targetPosition;
			Vector3 targetPosition2 = player.Head.RigidbodyEx.targetPosition;
			Collider[] array = Physics.OverlapSphere(targetPosition, portalSearchRadius, 67128320, QueryTriggerInteraction.Collide);
			float num = float.MaxValue;
			TeleportationPortal result = null;
			for (int i = 0; i < array.Length; i++)
			{
				if (!CollisionDetection.CollidesWithMovement(array[i]))
				{
					continue;
				}
				TeleportationPortal component = array[i].gameObject.GetComponent<TeleportationPortal>();
				if (!(component == null) && component.IsValid && !component.IsTeleportOnlyMode && (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType != LocalPlayerController.PlayerType.VR_WALK || (!component.IsSeat && !component.IsLadder)))
				{
					Vector3 vector = array[i].ClosestPoint(targetPosition2);
					float sqrMagnitude = (vector - targetPosition2).sqrMagnitude;
					if (sqrMagnitude < num)
					{
						num = sqrMagnitude;
						result = component;
					}
				}
			}
			return result;
		}

		private void UpdateHandMenuInteraction(PlayerHand hand, VRInputHandler input)
		{
			UIInputModule.Instance.GetNewResults((int)hand.Type, hand.CanMenuLaserInteract, hand.MenuRaycastStartTransform.position, hand.MenuRaycastStartTransform.forward, maxUIInteractionDistance, maxUIPushButtonDistance, testAngleFromHead: true, out var result);
			bool flag = ((hand.Type != PlayerHand.HandType.Left) ? isRightHandPressing3dButton : isLeftHandPressing3dButton);
			bool flag2 = IsHandPressingUIButton(hand, result);
			if (hand.Type == PlayerHand.HandType.Left)
			{
				isLeftHandPressing3dButton = flag2;
			}
			else
			{
				isRightHandPressing3dButton = flag2;
			}
			bool buttonDown = input.UIClickDown || (!flag && flag2);
			bool buttonUp = input.UIClickUp || (flag && !flag2);
			UIInputModule.Instance.SendButtonInput((int)hand.Type, buttonDown, buttonUp);
			hand.UpdateMenuHandVisibility(result.UIRaycastPosition.HasValue);
			hand.MenuFinger.SetLaserButtonPushed(input.UIClickDown, input.UIClickUp, hand.ThisPlayer.PhotonPlayer, result.LaserPushButton);
			if (!hand.MenuHandVisualsActive || (!result.UIRaycastPosition.HasValue && !hand.ExpressoInfoGestureActive))
			{
				hand.DisableMenuLaser();
			}
			else if (result.UIRaycastPosition.HasValue)
			{
				hand.UpdateMenuLaser(result.UIRaycastPosition.Value, input.UIClickPressed, result.UISelectable);
			}
			else if (hand.ExpressoInfoGestureActive)
			{
				bool hairPickupButtonDown = input.HairPickupButtonDown;
				hand.UpdateGestureLaser(hairPickupButtonDown);
			}
		}

		private bool IsHandPressingUIButton(PlayerHand hand, UIInputModule.UIInputResult inputResult)
		{
			if (hand == null)
			{
				return false;
			}
			if (inputResult.UIRaycastPosition.HasValue)
			{
				MenuFinger menuFinger = hand.MenuFinger;
				Vector3? uIRaycastPosition = inputResult.UIRaycastPosition;
				if (menuFinger.OverlapsPoint(uIRaycastPosition.Value))
				{
					if (inputResult.UIEnteredObject == null)
					{
						return false;
					}
					if (inputResult.UIEnteredObject.CompareTag("Button3D"))
					{
						return false;
					}
					return true;
				}
			}
			return false;
		}

