		private void TryReleaseTriggerWithVelocity(PlayerHand hand, VRInputHandler input)
		{
			if (hand == null || hand.HeldTool == null || input == null)
			{
				return;
			}
			if (input.VelocityWaitForNextUpdate)
			{
				if (hand.Type == PlayerHand.HandType.Left)
				{
					delayedLeftHandVelocityTriggerRelease = true;
				}
				else
				{
					delayedRightHandVelocityTriggerRelease = true;
				}
			}
			else
			{
				ReleaseTriggerWithVelocityInternal(hand, input);
			}
		}

		private void ReleaseTriggerWithVelocityInternal(PlayerHand hand, VRInputHandler input)
		{
			if (hand.Type == PlayerHand.HandType.Left)
			{
				delayedLeftHandVelocityTriggerRelease = false;
			}
			else
			{
				delayedRightHandVelocityTriggerRelease = false;
			}
			if (!(hand.HeldTool == null))
			{
				CalculateVelocitiesRelativeToHand(hand, input, hand.HeldTool.RigidbodyEx.worldCenterOfMass, addParentVelocities: false, out var linearVelocity, out var angularVelocity);
				if (input.ThrowDirectionFollowsHeldTool)
				{
					linearVelocity = linearVelocity.magnitude * hand.HeldTool.RigidbodyEx.velocity.normalized;
				}
				hand.HeldTool.InputUpWithVelocity(linearVelocity, angularVelocity);
			}
		}

		private void TryReleaseToolFromHand(PlayerHand holderHand, PlayerHand otherHand, VRInputHandler holderHandInput, VRInputHandler otherHandInput)
		{
			if (holderHand == null || holderHand.HeldTool == null || holderHandInput == null)
			{
				return;
			}
			if (holderHandInput.VelocityWaitForNextUpdate)
			{
				if (holderHand.Type == PlayerHand.HandType.Left)
				{
					delayedReleaseOfLeftHandHeldTool = true;
				}
				else
				{
					delayedReleaseOfRightHandHeldTool = true;
				}
			}
			else
			{
				ReleaseHeldToolInternal(holderHand, otherHand, holderHandInput, otherHandInput);
			}
		}

		private void ReleaseHeldToolInternal(PlayerHand holderHand, PlayerHand otherHand, VRInputHandler holderHandInput, VRInputHandler otherHandInput)
		{
			if (holderHand.Type == PlayerHand.HandType.Left)
			{
				delayedReleaseOfLeftHandHeldTool = false;
			}
			else
			{
				delayedReleaseOfRightHandHeldTool = false;
			}
			Tool heldTool = holderHand.HeldTool;
			SetCurrentHandToolActionController(null, holderHand, otherHand, holderHandInput, otherHandInput);
			if (!(heldTool == null))
			{
				CalculateVelocitiesRelativeToHand(holderHand, holderHandInput, holderHand.HeldTool.RigidbodyEx.worldCenterOfMass, addParentVelocities: true, out var linearVelocity, out var angularVelocity);
				if (holderHandInput.ThrowDirectionFollowsHeldTool)
				{
					linearVelocity = linearVelocity.magnitude * holderHand.HeldTool.RigidbodyEx.velocity.normalized;
				}
				holderHand.TryReleaseTool(linearVelocity, angularVelocity);
			}
		}

		private void CalculateVelocitiesRelativeToHand(PlayerHand hand, VRInputHandler input, Vector3 calculationCenter, bool addParentVelocities, out Vector3 linearVelocity, out Vector3 angularVelocity)
		{
			if (hand.HeldTool == null)
			{
				linearVelocity = Vector3.zero;
				angularVelocity = Vector3.zero;
				return;
			}
			hand.RigidbodyEx.GetWorldKinematicVelocitiesAtWorldSpacePoint(calculationCenter, (float)input.VelocityRollbackStartFrame * UnityEngine.Time.smoothDeltaTime, (float)input.VelocityRollbackEndFrame * UnityEngine.Time.smoothDeltaTime, input.LinearVelocityAverageMethod, input.AngularVelocityAverageMethod, out linearVelocity, out angularVelocity);
			if (!addParentVelocities)
			{
				return;
			}
			RigidbodyEx parent = hand.RigidbodyEx.parent;
			if (parent != null)
			{
				linearVelocity += parent.velocity;
				angularVelocity += parent.angularVelocity;
				RigidbodyEx parent2 = parent.parent;
				if (parent2 != null)
				{
					linearVelocity += parent2.velocity;
					angularVelocity += parent2.angularVelocity;
				}
			}
		}

		private bool CanPlayerHoverTools(Player player, PlayerHand hand)
		{
			if (player == null)
			{
				return false;
			}
			if (!player.CanInteractWithTools)
			{
				return false;
			}
			if (hand == null)
			{
				return false;
			}
			WatchMenuProjector watchMenuProjector = player.PlayerUI.WatchMenuProjector;
			if (watchMenuProjector.IsMenuOpen && watchMenuProjector.AttachedToWrist && watchMenuProjector.AttachedHand == hand)
			{
				return false;
			}
			if (!hand.DefaultHandVisualsActive && !hand.ExpressoInfoGestureActive)
			{
				return false;
			}
			if (hand.HandConnectedState == PlayerHand.ConnectedState.NOT_CONNECTED)
			{
				return false;
			}
			return true;
		}

		private Tool FindClosestToolToHandInPhysicalPickupRange(Player player, PlayerHand hand)
		{
			Tool closestTool = null;
			float closestToolDistance = float.MaxValue;
			FindClosestToolToHandInSphere(player, hand, ref closestTool, ref closestToolDistance, hand.PhysicalPickupSphereRadius, physicalPickup: true);
			return closestTool;
		}

		private Tool FindClosestToolToHandInMagnetPickupRange(Player player, PlayerHand hand)
		{
			Vector3 gravityPickupDirection = hand.GravityPickupDirection;
			Vector3 origin = hand.GravityPickupOrigin + gravityPickupDirection * hand.GravityPickupCapsuleRadius;
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			float maxDistance = hand.GravityPickupCapsuleLength - 2f * hand.GravityPickupCapsuleRadius;
			int num = Physics.SphereCastNonAlloc(origin, hand.GravityPickupCapsuleRadius, gravityPickupDirection, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267082240);
			float num2 = float.MaxValue;
			float closestToolDistance = float.MaxValue;
			Tool closestTool = null;
			Collider highlightedCollider = null;
			for (int i = 0; i < num; i++)
			{
				Collider collider = iMMEDIATE_RAYCAST_HITS[i].collider;
				Tool tool = collider.GetColliderTool();
				if (tool != null)
				{
					tool = tool.SelectForwardedTool(player, physicalPickupSelection: false, collider);
				}
				if (tool != null && IsValidToolPickup(player, tool, hand.transform.position, inPhysicalPickupRange: false))
				{
					Bounds bounds = tool.GetColliderBounds();
					if (bounds.size.sqrMagnitude <= Mathf.Epsilon)
					{
						bounds = collider.bounds;
					}
					Vector3 vector = ((tool.GravityPickupMode == Tool.GravityPickup.SNAP_POSITION_SNAP_ORIENTATION) ? bounds.center : iMMEDIATE_RAYCAST_HITS[i].point);
					Vector3 vector2 = hand.GravityPickupOrigin - vector;
					Vector3 vector3 = vector2 - Vector3.Project(vector2, gravityPickupDirection);
					float magnitude = bounds.extents.magnitude;
					Vector3 vector4 = vector + vector3.normalized * magnitude;
					Vector3 lhs = vector4 - hand.GravityPickupOrigin;
					float num3 = Vector3.Dot(lhs, gravityPickupDirection);
					if (num3 >= 0f && num3 < num2)
					{
						closestTool = tool;
						num2 = num3;
						highlightedCollider = collider;
						closestToolDistance = vector2.magnitude;
					}
				}
			}
			FindClosestToolToHandInSphere(player, hand, ref closestTool, ref closestToolDistance, hand.GravityPickupSphereRadius, physicalPickup: false);
			if (closestTool != null && closestTool.HighlightedCollider == null)
			{
				closestTool.HighlightedCollider = highlightedCollider;
			}
			return closestTool;
		}

		private Tool FindClosestToolToHandInSphere(Player player, PlayerHand hand, ref Tool closestTool, ref float closestToolDistance, float radius, bool physicalPickup)
		{
			int num = Physics.OverlapSphereNonAlloc(hand.PhysicalPickupOrigin, radius, PhysicsExt.IMMEDIATE_COLLIDER_HITS, 1267082240);
			Collider collider = null;
			for (int i = 0; i < num; i++)
			{
				Collider collider2 = PhysicsExt.IMMEDIATE_COLLIDER_HITS[i];
				Tool tool = collider2.GetColliderTool();
				if (tool != null)
				{
					tool = tool.SelectForwardedTool(player, physicalPickup, collider2);
				}
				if (tool != null && IsValidToolPickup(player, tool, hand.transform.position, physicalPickup))
				{
					bool inFrontOfTransform;
					float num2 = tool.DistanceToTransform(collider2, hand.PhysicalPickupOriginTransform, out inFrontOfTransform);
					if ((inFrontOfTransform || tool.IgnorePickupDirection) && num2 < closestToolDistance)
					{
						closestTool = tool;
						collider = collider2;
						closestToolDistance = num2;
					}
				}
			}
			if (closestTool != null && collider != null && closestTool.HighlightedCollider == null)
			{
				closestTool.HighlightedCollider = collider;
			}
			return closestTool;
		}

		private Tool FindToolInShoulderSlot(Player player, PlayerHand hand)
		{
			if (!player.ToolEquipSlots.ShoulderSlot.IsHandInSelectionVolume(hand.transform.position))
			{
				return null;
			}
			if (player.ToolEquipSlots.ShoulderSlot.IsFull)
			{
				Tool equippedTool = player.ToolEquipSlots.ShoulderSlot.EquippedTool;
				return equippedTool.SelectForwardedTool(player, physicalPickupSelection: false);
			}
			return player.Backpack.TryGetFavoriteToolForPickup();
		}

		private bool IsValidToolPickup(Player player, Tool tool, Vector3 pickupPosition, bool inPhysicalPickupRange)
		{
			if (pickupConditions.Count > 0)
			{
				foreach (PickupCondition pickupCondition in pickupConditions)
				{
					if (!pickupCondition(tool, player, pickupPosition, inPhysicalPickupRange))
					{
						return false;
					}
				}
			}
			return tool.IsValidPickup(player, pickupPosition, inPhysicalPickupRange);
		}

		private OutfitTrigger FindClosestOutfitTriggerToHand(Player player, PlayerHand hand)
		{
			if (SingletonMonoBehaviour<TutorialManager>.Instance.CanRemoveOutfit)
			{
				RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
				Vector3 forward = hand.PhysicalPickupOriginTransform.forward;
				int num = Physics.RaycastNonAlloc(hand.PhysicalPickupOriginTransform.position - forward * 0.1f, forward, iMMEDIATE_RAYCAST_HITS, 0.25f, 32768);
				if (num != 0)
				{
					iMMEDIATE_RAYCAST_HITS.SortByDistanceToCenter(num);
					for (int i = 0; i < num; i++)
					{
						OutfitTrigger component = iMMEDIATE_RAYCAST_HITS[i].collider.GetComponent<OutfitTrigger>();
						if (component != null && component.OutfitItem != null && component.OutfitItem.Owner == player && component.OutfitItem.CurrentBodyPart != (Player.BodyPart)((hand.Type != PlayerHand.HandType.Left) ? 3 : 2) && component.OutfitItem.Type != OutfitManager.OutfitType.Shirt && (component.EnabledOutsideDormRoom || (SessionManager.InDormRoom && SpawnedEquipmentDrawer.DrawersOpen)))
						{
							return component;
						}
					}
				}
			}
			return null;
		}

