		private void UpdateCameraRigPosition(SplashScreenSpawnPoint splashScreenSpawnPoint)
		{
			if (splashScreenSpawnPoint == null || splashScreenSpawnPoint.VrSpawnPoint == null)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.transform.position = Vector3.zero;
				SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = Quaternion.identity;
			}
			else
			{
				SingletonMonoBehaviour<CameraRig>.Instance.transform.position = splashScreenSpawnPoint.VrSpawnPoint.position;
				SingletonMonoBehaviour<CameraRig>.Instance.transform.rotation = splashScreenSpawnPoint.VrSpawnPoint.rotation;
			}
			if (!SingletonMonoBehaviour<VRDeviceManager>.Instance.HMDExists)
			{
				Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform;
				Vector3? vector = splashScreenSpawnPoint?.ScreenSpawnPoint?.position;
				transform.position = ((!vector.HasValue) ? Vector3.zero : vector.Value);
				Transform transform2 = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform;
				Quaternion? quaternion = splashScreenSpawnPoint?.ScreenSpawnPoint?.rotation;
				transform2.rotation = ((!quaternion.HasValue) ? Quaternion.identity : quaternion.Value);
			}
		}

		public static FakePlayerHand GetPlayerHand(PlayerHand.HandType handType)
		{
			if (ActiveInstance == null || !ActiveInstance.isActive)
			{
				return null;
			}
			return handType switch
			{
				PlayerHand.HandType.Left => ActiveInstance.leftHand, 
				PlayerHand.HandType.Right => ActiveInstance.rightHand, 
				_ => null, 
			};
		}

		private void UpdateMenuInteraction()
		{
			UpdateHandMenuInteraction(0, leftHand, leftHandInput);
			UpdateHandMenuInteraction(1, rightHand, rightHandInput);
		}

		private void UpdateHandMenuInteraction(int handIndex, FakePlayerHand hand, VRInputHandler input)
		{
			if (!(hand == null) && input != null)
			{
				UIInputModule.Instance.GetNewResults(handIndex, uiInteractionEnabled: true, hand.transform.position, hand.transform.forward, float.MaxValue, maxPushButtonInteractionDistance, testAngleFromHead: true, out var result);
				bool uIClickDown = input.UIClickDown;
				bool uIClickUp = input.UIClickUp;
				UIInputModule.Instance.SendButtonInput(handIndex, uIClickDown, uIClickUp);
				hand.MenuFinger.SetLaserButtonPushed(input.UIClickDown, input.UIClickUp, PhotonNetwork.player, result.LaserPushButton);
				if (result.UIRaycastPosition.HasValue)
				{
					hand.UpdateMenuLaser(result.UIRaycastPosition.Value, input.UIClickPressed, result.UISelectable);
				}
				else
				{
					hand.DisableMenuLaser();
				}
			}
		}

		private void UpdateProfileSelectionMenu()
		{
			if (SingletonMonoBehaviour<ProfileSelectionManager>.IsInitialized && !(SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI == null))
			{
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.transform.position = SingletonMonoBehaviour<ProfileSelectionManager>.Instance.transform.position;
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.transform.rotation = SingletonMonoBehaviour<ProfileSelectionManager>.Instance.transform.rotation;
			}
		}
	}
