	public abstract class CircuitConnectionPoint : ConnectionPoint
	{
		[Autofill(AutofillType.SelfAndParent, false)]
		public CircuitNodeDisplay NodeDisplay;

		public CircuitNode Node;

		public virtual InputSlot? MyInputSlot => null;

		public virtual OutputSlot? MyOutputSlot => null;

		public override Tool Tool => NodeDisplay.Tool;

		public override Color ConnectionColor
		{
			get
			{
				if (MyInputSlot.HasValue)
				{
					return CircuitManager.ColorFromInput(MyInputSlot.Value);
				}
				return CircuitManager.ColorFromOutput(MyOutputSlot.Value);
			}
		}

		public void UpdateColor()
		{
			MeshRenderer[] componentsInChildren = GetComponentsInChildren<MeshRenderer>();
			MeshRenderer[] array = componentsInChildren;
			foreach (MeshRenderer meshRenderer in array)
			{
				Color color = Color.red;
				if (MyInputSlot.HasValue)
				{
					color = CircuitManager.ColorFromInput(MyInputSlot.Value);
				}
				else if (MyOutputSlot.HasValue)
				{
					color = CircuitManager.ColorFromInput(IOSlots.OutputSlotToInputSlot[MyOutputSlot.Value]);
				}
				meshRenderer.material.color = color;
			}
		}

		public override void ConnectionStart(ConnectionResultCallback penCallback = null)
		{
			base.ConnectionStart(penCallback);
			CircuitConnectionPoint circuitConnectionPoint = this;
			CreationResult result = CreationResult.Success;
			CircuitLink value;
			if (Tool.IsFrozen)
			{
				result = CreationResult.Failure_ToolFrozen;
			}
			else if (MyInputSlot.HasValue && Node.Inputs.TryGetValue(MyInputSlot.Value, out value))
			{
				CircuitNode sourceNode = value.SourceNode;
				if (sourceNode.IsVirtual)
				{
					InputSlot key = IOSlots.OutputSlotToInputSlot[value.OutputSlot];
					sourceNode = value.SourceNode.Inputs[key].SourceNode;
				}
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterDisconnectNode(Node.NodeId, MyInputSlot.Value);
				circuitConnectionPoint = NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.VisualFor<CircuitNodeDisplay>(sourceNode).OutputSlotDisplays[value.OutputSlot];
			}
			penCallback?.Invoke(result, null);
		}

		public override void ConnectionEnd(ConnectionPoint connectionStart, ConnectionPoint connectionEnd, ConnectionResultCallback penCallback = null)
		{
			base.ConnectionEnd(connectionStart, connectionEnd, penCallback);
			CreationResult result = CreationResult.Failure_Generic;
			CircuitConnectionPoint circuitConnectionPoint = ((!(connectionStart != null)) ? null : connectionStart.GetComponent<CircuitConnectionPoint>());
			CircuitConnectionPoint circuitConnectionPoint2 = ((!(connectionEnd != null)) ? null : connectionEnd.GetComponent<CircuitConnectionPoint>());
			if (circuitConnectionPoint != this)
			{
				return;
			}
			if (circuitConnectionPoint != null && circuitConnectionPoint2 != null && connectionStart != connectionEnd && !circuitConnectionPoint.NodeDisplay.Tool.IsFrozen && !circuitConnectionPoint2.NodeDisplay.Tool.IsFrozen)
			{
				if (circuitConnectionPoint.MyOutputSlot.HasValue && circuitConnectionPoint2.MyInputSlot.HasValue)
				{
					if (!IsOutputDirectlyLinkedToInput(circuitConnectionPoint.Node, circuitConnectionPoint.MyOutputSlot.Value, circuitConnectionPoint2.Node, circuitConnectionPoint2.MyInputSlot.Value))
					{
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterConnectNodes(circuitConnectionPoint.Node.NodeId, circuitConnectionPoint.MyOutputSlot.Value, circuitConnectionPoint2.Node.NodeId, circuitConnectionPoint2.MyInputSlot.Value);
					}
					else
					{
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterDisconnectNode(circuitConnectionPoint2.Node.NodeId, circuitConnectionPoint2.MyInputSlot.Value);
					}
					result = CreationResult.Success;
				}
				else if (circuitConnectionPoint.MyInputSlot.HasValue && circuitConnectionPoint2.MyOutputSlot.HasValue)
				{
					if (!IsOutputDirectlyLinkedToInput(circuitConnectionPoint2.Node, circuitConnectionPoint2.MyOutputSlot.Value, circuitConnectionPoint.Node, circuitConnectionPoint.MyInputSlot.Value))
					{
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterConnectNodes(circuitConnectionPoint2.Node.NodeId, circuitConnectionPoint2.MyOutputSlot.Value, circuitConnectionPoint.Node.NodeId, circuitConnectionPoint.MyInputSlot.Value);
					}
					else
					{
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterDisconnectNode(circuitConnectionPoint.Node.NodeId, circuitConnectionPoint.MyInputSlot.Value);
					}
					result = CreationResult.Success;
				}
			}
			penCallback?.Invoke(result, null);
		}

		private static bool IsOutputDirectlyLinkedToInput(CircuitNode outputNode, OutputSlot outputSlot, CircuitNode inputNode, InputSlot inputSlot)
		{
			CircuitLink value = null;
			if (inputNode.Inputs.TryGetValue(inputSlot, out value))
			{
				if (value.LinkType == LinkTypes.VirtualToNormal)
				{
					return false;
				}
				if (value.SourceNode.NodeId == outputNode.NodeId && value.OutputSlot == outputSlot)
				{
					return true;
				}
			}
			return false;
		}
	}
	public class CircuitEventNodeDisplay : CircuitEventNodeDisplayBase, ICustomOutputNodeDisplay
	{
		[Serializable]
		public class NodeInputReceived : UnityEvent<Dictionary<InputSlot, int>>
		{
		}

		public NodeInputReceived OnRecievedNewInput;

		[SerializeField]
		private InputMetadata[] inputMeta = new InputMetadata[1]
		{
			new InputMetadata
			{
				InputSlot = InputSlot.R
			}
		};

		public override InputMetadata[] InputMeta
		{
			get
			{
				return inputMeta;
			}
			set
			{
				inputMeta = value;
			}
		}

		public void AddInputMeta(InputSlot inputSlot, string description)
		{
			InputMetadata newInputMeta = new InputMetadata
			{
				InputSlot = inputSlot,
				Description = description
			};
			AddInputMeta(newInputMeta);
		}

		public void AddInputMeta(InputMetadata newInputMeta)
		{
			for (int i = 0; i < InputMeta.Length; i++)
			{
				if (InputMeta[i].InputSlot == newInputMeta.InputSlot)
				{
					return;
				}
			}
			InputMetadata[] array = new InputMetadata[InputMeta.Length + 1];
			InputMeta.CopyTo(array, 0);
			array[array.Length - 1] = newInputMeta;
			InputMeta = array;
			if (base.MyCircuitNode != null)
			{
				((OutputNode)base.MyCircuitNode).SetInputMeta(InputMeta);
			}
		}

		public void RemoveInputMeta(InputSlot inputToRemove)
		{
			int num = -1;
			for (int i = 0; i < InputMeta.Length; i++)
			{
				if (InputMeta[i].InputSlot == inputToRemove)
				{
					num = i;
					break;
				}
			}
			if (num < 0)
			{
				return;
			}
			InputMetadata[] array = new InputMetadata[InputMeta.Length - 1];
			for (int j = 0; j < InputMeta.Length; j++)
			{
				if (j < num)
				{
					ref InputMetadata reference = ref array[j];
					reference = InputMeta[j];
				}
				else if (j > num)
				{
					ref InputMetadata reference2 = ref array[j - 1];
					reference2 = InputMeta[j];
				}
			}
			InputMeta = array;
			if (base.MyCircuitNode != null)
			{
				((OutputNode)base.MyCircuitNode).SetInputMeta(InputMeta);
			}
		}

		protected override void NodeInputUpdate(Dictionary<InputSlot, int> updates)
		{
			if (OnRecievedNewInput != null)
			{
				OnRecievedNewInput.Invoke(updates);
			}
		}
	}
	public abstract class CircuitEventNodeDisplayBase : CircuitNodeDisplay, ICustomOutputNodeDisplay
	{
		[SerializeField]
		protected bool fireEventOnMasterOnly;

		[Tooltip("The event will fire at most once every x seconds")]
		public float eventRateLimitTime = 0.25f;

		protected float nextEventTime;

		public abstract InputMetadata[] InputMeta { get; set; }

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
			OutputNode outputNode = (OutputNode)node;
			outputNode.SetInputMeta(InputMeta);
			outputNode.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Combine(outputNode.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
		}

		private void OnNodeInputReceived(Dictionary<InputSlot, int> updates)
		{
			if (UnityEngine.Time.realtimeSinceStartup >= nextEventTime)
			{
				if (!fireEventOnMasterOnly || PhotonNetwork.isMasterClient)
				{
					NodeInputUpdate(updates);
				}
				nextEventTime = UnityEngine.Time.realtimeSinceStartup + eventRateLimitTime;
			}
		}

		protected abstract void NodeInputUpdate(Dictionary<InputSlot, int> updates);
	}
