		public static readonly List<CircuitNodeDisplay> AllDisplays = new List<CircuitNodeDisplay>();

		private static readonly int IconTexScaleOffsetPropertyId = Shader.PropertyToID("_IconTexScaleOffset");

		private static readonly int PinMaskPropertyId = Shader.PropertyToID("_PinMask");

