		public Dictionary<InputSlot, CircuitInputConnectionPoint> InputSlotDisplays = new Dictionary<InputSlot, CircuitInputConnectionPoint>();

		public Dictionary<OutputSlot, CircuitOutputConnectionPoint> OutputSlotDisplays = new Dictionary<OutputSlot, CircuitOutputConnectionPoint>();

		[Tooltip("Returns whether this is a \"simple\" node that represents a single circuit operation and nothing else. Simple nodes always use the circuit-specific instanced material.")]
		[SerializeField]
		[FormerlySerializedAs("isSimpleNode")]
		private bool _isSimpleNode;

		[Tooltip("Returns whether this node should configure the circuit-specific instanced material")]
		[SerializeField]
		[ConditionalField("IsSimpleNode", false)]
		[FormerlySerializedAs("useCustomCircuitRendering")]
		private bool _useCustomCircuitRendering;

		[SerializeField]
		private bool KeepOrientationOnPickup;

		[HideInInspector]
		[SerializeField]
		public InputSlotDisplayConfig[] inputSlotConfigs;

		[HideInInspector]
		[SerializeField]
		public OutputSlotDisplayConfig[] outputSlotConfigs;

		[SerializeField]
		[HideInInspector]
		private int nodeId;

		private int? overrideNodeId;

		[Autofill(AutofillType.Self, false)]
		public Tool Tool;

		[SerializeField]
		[HideInInspector]
		private MeshRenderer circuitMeshRenderer;

		[SerializeField]
		protected Sprite defaultCircuitLabelSprite;

		private MaterialPropertyBlock circuitMeshMaterialPropertyBlock;

		private bool editablesInitialized;

		public CircuitNode MyCircuitNode
		{
			get
			{
				return _myCircuitNode;
			}
			private set
			{
				if (_myCircuitNode != null)
				{
					CircuitNode myCircuitNode = _myCircuitNode;
					myCircuitNode.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Remove(myCircuitNode.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(OnNodeMetadataChanged));
					DeregisterFromEvents();
				}
				_myCircuitNode = value;
				if (_myCircuitNode != null)
				{
					CircuitNode myCircuitNode2 = _myCircuitNode;
					myCircuitNode2.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Combine(myCircuitNode2.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(OnNodeMetadataChanged));
					RegisterForEvents();
				}
			}
		}

		public CircuitNodeGraph NodeGraph => (MyCircuitNode == null) ? null : MyCircuitNode.NodeGraph;

		public NodeMetadata NodeMetadata => (MyCircuitNode == null) ? default(NodeMetadata) : MyCircuitNode.NodeMetadata;

		public bool IsConnected => MyCircuitNode != null && (MyCircuitNode.HasConnectedInputs || MyCircuitNode.HasConnectedOutputs);

		public bool BlockObjectPersistance => false;

		public bool IsSimpleNode => _isSimpleNode;

		public bool UseCustomCircuitRendering => _isSimpleNode || _useCustomCircuitRendering;

		public int NodeId => nodeId;

		public bool CanPersistNode
		{
			get
			{
				if (Tool != null && Tool.PersistenceView != null)
				{
					return Tool.PersistenceView.IsPersistable;
				}
				UnityEngine.Debug.LogWarning($"CircuitNodeDisplay {this} has no accessible PersistenceView. Assuming that it's safe to persist its node.");
				return true;
			}
		}

		public virtual Sprite CircuitNodeSprite => defaultCircuitLabelSprite;

		public virtual IEnumerable<SettingsEditEvent> GetEditables()
		{
			return new SettingsEditEvent[0];
		}

		public void OverrideNodeId(int? overrideId)
		{
			overrideNodeId = overrideId;
		}

		protected virtual void OnValidate()
		{
		}

		protected override void Awake()
		{
			base.Awake();
			AllDisplays.Add(this);
			base.photonView.OnDestroying += OnDestroying;
			if (!GameSessions.LocalGameSession.IsSandbox)
			{
				return;
			}
			EnsureMaterialPropertyBlock();
			if (Tool == null)
			{
				UnityEngine.Debug.LogError("CircuitNodeObject requires a Tool!");
			}
			if (IsSimpleNode || KeepOrientationOnPickup)
			{
				Tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			}
			if (UseCustomCircuitRendering)
			{
				Tool.OutlineType = OutlineEffectRenderer.OutlineType.CircuitNode;
				Tool.SelectionType = SelectionRenderer.SelectionType.Circuit;
			}
			InputSlotDisplayConfig[] array = inputSlotConfigs;
			foreach (InputSlotDisplayConfig inputSlotDisplayConfig in array)
			{
				InputSlotDisplays[inputSlotDisplayConfig.InputSlot] = inputSlotDisplayConfig.IOSlot;
			}
			OutputSlotDisplayConfig[] array2 = outputSlotConfigs;
			foreach (OutputSlotDisplayConfig outputSlotDisplayConfig in array2)
			{
				OutputSlotDisplays[outputSlotDisplayConfig.OutputSlot] = outputSlotDisplayConfig.IOSlot;
			}
			int num = 0;
			Dictionary<string, object> instantiationParameters = Tool.InstantiationParameters;
			if (instantiationParameters != null && instantiationParameters.TryGetValue("CO_CN", out var value))
			{
				num = (int)value;
			}
			if (nodeId == 0 && num == 0)
			{
				SpawnableTool component = GetComponent<SpawnableTool>();
				string text = ((!(component != null)) ? string.Empty : ("Prefab Guid:" + component.PrefabId.ToString()));
				UnityEngine.Debug.LogErrorFormat(base.gameObject, "CircuitNodeObject {0} requires Tool InstantiationParams! {1}", base.gameObject.name, text);
				return;
			}
			if (num != 0)
			{
				if (nodeId != 0)
				{
					UnityEngine.Debug.LogError("CircuitNodeObject " + base.gameObject.name + " has a serialized NodeID AND a Tool Instantiation Param NodeID!", base.gameObject);
				}
				nodeId = num;
			}
			CircuitNode.OnNodeInstantiatedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Combine(CircuitNode.OnNodeInstantiatedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeInstantiated));
			CircuitNode circuitNode = CircuitNode.Find(nodeId);
			if (circuitNode != null)
			{
				OnCircuitNodeInitialized(circuitNode);
			}
		}

		private void Start()
		{
			InitializeEditables();
			UpdateLabelSprite();
		}

		private void EnsureMaterialPropertyBlock()
		{
			if (circuitMeshRenderer != null)
			{
				circuitMeshMaterialPropertyBlock = new MaterialPropertyBlock();
			}
		}

		protected void UpdateLabelSprite()
		{
			if (circuitMeshRenderer != null)
			{
				Vector4 value = new Vector4(0f, 0f, 0f, 0f);
				if (CircuitNodeSprite != null)
				{
					Rect rect = CircuitNodeSprite.rect;
					float num = CircuitNodeSprite.texture.width;
					float num2 = CircuitNodeSprite.texture.height;
					value = new Vector4(rect.width / num, rect.height / num2, rect.x / num, rect.y / num2);
				}
				circuitMeshMaterialPropertyBlock.SetVector(IconTexScaleOffsetPropertyId, value);
				circuitMeshRenderer.SetPropertyBlock(circuitMeshMaterialPropertyBlock);
			}
		}

		private void OnNodeInstantiated(CircuitNode node)
		{
			if (node.NodeId == nodeId)
			{
				OnCircuitNodeInitialized(node);
			}
		}

		protected sealed override void OnDestroy()
		{
			base.OnDestroy();
		}

		protected virtual void OnDestroying(PhotonView destroyingPhotonView)
		{
			CircuitNode.OnNodeInstantiatedEvent = (CircuitNode.NodeLifecycleEvent)Delegate.Remove(CircuitNode.OnNodeInstantiatedEvent, new CircuitNode.NodeLifecycleEvent(OnNodeInstantiated));
			CircuitNode myCircuitNode = MyCircuitNode;
			MyCircuitNode = null;
			try
			{
				if (base.photonView != null)
				{
					base.photonView.OnDestroying -= OnDestroying;
				}
				if (NetworkedSingletonMonoBehaviour<CircuitManager>.Instance != null)
				{
					NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RemoveVisualFor(myCircuitNode);
					if (PhotonNetwork.isMasterClient)
					{
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterDestroyNode(nodeId);
					}
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			AllDisplays.Remove(this);
		}

		public virtual void OnCircuitNodeInitialized(CircuitNode node)
		{
			if (MyCircuitNode != null)
			{
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RemoveVisualFor(MyCircuitNode);
			}
			base.gameObject.name = base.gameObject.name.Replace("(Clone)", string.Empty) + "_" + node.GetType().Name + "_" + nodeId;
			MyCircuitNode = node;
			VerifyCircuitNodeIntegrity(serializing: false);
			OnNodeMetadataChanged(NodeMetadata);
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.SetVisualFor(node, this);
			InitializeEditables();
		}

		protected virtual void RegisterForEvents()
		{
		}

		protected virtual void DeregisterFromEvents()
		{
		}

		protected void InitializeEditables(bool force = false)
		{
			CreationObject component = GetComponent<CreationObject>();
			if (component != null && (!editablesInitialized || force))
			{
				if (force)
				{
					component.ClearConfigurableSettigns();
				}
				component.AddConfigurableSettings(GetEditables());
				editablesInitialized = true;
			}
		}

		protected virtual void OnNodeMetadataChanged(NodeMetadata newNodeMetadata)
		{
			List<InputSlot> list = InputSlotDisplays.Keys.ToList();
			InputMetadata[] inputMetadata = newNodeMetadata.InputMetadata;
			for (int i = 0; i < inputMetadata.Length; i++)
			{
				InputMetadata inputMeta = inputMetadata[i];
				if (!InputSlotDisplays.ContainsKey(inputMeta.InputSlot))
				{
					UnityEngine.Debug.LogError(base.gameObject.name + " is missing InputSlot " + inputMeta.InputSlot);
					continue;
				}
				CircuitInputConnectionPoint iSlot = InputSlotDisplays[inputMeta.InputSlot];
				iSlot.gameObject.SetActive(value: true);
				iSlot.inputSlot = inputMeta.InputSlot;
				iSlot.UpdateColor();
				iSlot.Node = MyCircuitNode;
				Tooltip tooltip = SetTooltip(iSlot, inputMeta.Description);
				tooltip.RefreshEvent = delegate
				{
					SetTooltip(iSlot, inputMeta.Description);
				};
				list.Remove(inputMeta.InputSlot);
			}
			for (int num = 0; num < list.Count; num++)
			{
				InputSlotDisplays[list[num]].gameObject.SetActive(value: false);
			}
			List<OutputSlot> list2 = OutputSlotDisplays.Keys.ToList();
			OutputMetadata[] outputMetadata = newNodeMetadata.OutputMetadata;
			for (int num2 = 0; num2 < outputMetadata.Length; num2++)
			{
				OutputMetadata outputMeta = outputMetadata[num2];
				if (!OutputSlotDisplays.ContainsKey(outputMeta.OutputSlot))
				{
					UnityEngine.Debug.LogError(base.gameObject.name + " is missing OutputSlot " + outputMeta.OutputSlot);
					continue;
				}
				CircuitOutputConnectionPoint oSlot = OutputSlotDisplays[outputMeta.OutputSlot];
				oSlot.gameObject.SetActive(value: true);
				oSlot.outputSlot = outputMeta.OutputSlot;
				oSlot.UpdateColor();
				oSlot.Node = MyCircuitNode;
				Tooltip tooltip2 = SetTooltip(oSlot, outputMeta.Description);
				tooltip2.RefreshEvent = delegate
				{
					SetTooltip(oSlot, outputMeta.Description);
				};
				list2.Remove(outputMeta.OutputSlot);
			}
			for (int num3 = 0; num3 < list2.Count; num3++)
			{
				OutputSlotDisplays[list2[num3]].gameObject.SetActive(value: false);
			}
			if (circuitMeshRenderer != null)
			{
				HashSet<int> source = new HashSet<int>(newNodeMetadata.InputMetadata.Select((InputMetadata m) => 1 << (int)m.InputSlot));
				HashSet<int> source2 = new HashSet<int>(newNodeMetadata.OutputMetadata.Select((OutputMetadata m) => 1 << (int)m.OutputSlot));
				Vector4 value = new Vector4(source.Sum(), source2.Sum());
				circuitMeshMaterialPropertyBlock.SetVector(PinMaskPropertyId, value);
				UpdateLabelSprite();
				circuitMeshRenderer.SetPropertyBlock(circuitMeshMaterialPropertyBlock);
			}
		}

		private Tooltip SetTooltip(CircuitConnectionPoint slot, string description)
		{
			Tooltip tooltip = slot.GetComponent<Tooltip>();
			if (tooltip == null)
			{
				tooltip = slot.gameObject.AddComponent<Tooltip>();
			}
			StringBuilder stringBuilder = new StringBuilder();
			if (!string.IsNullOrEmpty(description))
			{
				stringBuilder.AppendLine(description);
			}
			if (slot.MyOutputSlot.HasValue && MyCircuitNode != null)
			{
				stringBuilder.Append(MyCircuitNode.GetOutputSignal(slot.MyOutputSlot.Value));
			}
			tooltip.Message = stringBuilder.ToString();
			return tooltip;
		}

		public virtual void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.CircuitNodeData == null || deserializeParams.viewData.CircuitNodeData.CircuitNodeId == 0)
			{
				UnityEngine.Debug.LogError("Expected a circuit node id for CircuitNodeDisplay data");
				return;
			}
			int circuitNodeId = deserializeParams.viewData.CircuitNodeData.CircuitNodeId;
			int num = ((deserializeParams.nodeIdMapping == null) ? circuitNodeId : deserializeParams.nodeIdMapping[circuitNodeId]);
			CircuitNode circuitNode = CircuitNode.Find(num);
			if (circuitNode == null)
			{
				UnityEngine.Debug.LogErrorFormat("Found null circuit node for CircuitNodeDisplay data:\nOld ID: {0} New Id: {1}", circuitNodeId, num);
				return;
			}
			if (deserializeParams.version < RoomPersistenceVersion.CIRCUIT_CHIP_ORIENTATION && UseCustomCircuitRendering)
			{
				base.transform.LookAt(base.transform.position - base.transform.up, base.transform.right);
			}
			OnCircuitNodeInitialized(circuitNode);
		}

		public virtual void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			VerifyCircuitNodeIntegrity(serializing: true);
			int? num = overrideNodeId;
			int circuitNodeId = ((!num.HasValue) ? MyCircuitNode.NodeId : overrideNodeId.Value);
			viewData.CircuitNodeData = new RecRoom.Protobuf.CircuitNodeData
			{
				CircuitNodeId = circuitNodeId
			};
			overrideNodeId = null;
		}

		private void VerifyCircuitNodeIntegrity(bool serializing)
		{
			string text = ((!serializing) ? "I" : "S");
			if (nodeId != 0)
			{
				if (MyCircuitNode == null)
				{
					throw new ArgumentException($"{text} {base.gameObject} Null Node for nodeId {nodeId}.");
				}
				Guid circuitNodeType = GetCircuitNodeType();
				Guid nodeTypeGuid = Serialization.GetNodeTypeGuid(MyCircuitNode);
				if (circuitNodeType != Guid.Empty && circuitNodeType != nodeTypeGuid)
				{
					throw new ArgumentException($"{text} {base.gameObject} Found node type mismatch for node type on nodeId {nodeId}. Expected \"{circuitNodeType.ToString()}\" but found \"{nodeTypeGuid.ToString()}\"");
				}
			}
		}

		public Guid GetCircuitNodeType()
		{
			SpawnableTool component = GetComponent<SpawnableTool>();
			if (component != null)
			{
				SpawnableToolConfig.Config spawnableToolConfig = SpawnableToolSettings.GetSpawnableToolConfig(component.Type);
				if (spawnableToolConfig != null && spawnableToolConfig.CircuitNodeType != null && !string.IsNullOrEmpty(spawnableToolConfig.CircuitNodeType.uuid))
				{
					return new Guid(spawnableToolConfig.CircuitNodeType.uuid);
				}
			}
			return Guid.Empty;
		}

		void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
		{
			EnsureMaterialPropertyBlock();
			UpdateLabelSprite();
			if (circuitMeshRenderer != null)
			{
				circuitMeshMaterialPropertyBlock.SetVector(PinMaskPropertyId, Vector4.zero);
				circuitMeshRenderer.SetPropertyBlock(circuitMeshMaterialPropertyBlock);
			}
		}
	}
