	public static class CircuitUtils
	{
		private const int INDEX_OFFSET = 1;

		private const int ANY_TEAM_INT_VALUE = -1;

		private static int? _maxGameTeamEnumValue;

		private static int? _maxGameTeamPlayerIndexEnumValue;

		private static int MaxGameTeamEnumValue
		{
			get
			{
				if (!_maxGameTeamEnumValue.HasValue)
				{
					_maxGameTeamEnumValue = System.Enum.GetValues(typeof(GameTeam)).Cast<int>().Max();
				}
				return _maxGameTeamEnumValue.Value;
			}
		}

		private static int MaxGameTeamPlayerIndexEnumValue
		{
			get
			{
				if (!_maxGameTeamPlayerIndexEnumValue.HasValue)
				{
					_maxGameTeamPlayerIndexEnumValue = System.Enum.GetValues(typeof(GameTeamPlayerIndex)).Cast<int>().Max();
				}
				return _maxGameTeamPlayerIndexEnumValue.Value;
			}
		}

		public static void ForPlayerSignal(int playerCircuitSignal, Action<PhotonPlayer> doAction)
		{
			if (playerCircuitSignal == 0)
			{
				return;
			}
			if (playerCircuitSignal > 0)
			{
				PhotonPlayer photonPlayer = PhotonPlayer.Find(playerCircuitSignal);
				if (photonPlayer != null)
				{
					doAction(photonPlayer);
				}
			}
			else
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					PhotonPlayer obj = PhotonNetwork.playerList[i];
					doAction(obj);
				}
			}
		}

		public static GameTeam? CircuitSignalToGameTeam(int signal)
		{
			if (signal == 0 || signal > MaxGameTeamEnumValue + 1)
			{
				return null;
			}
			if (signal < 0)
			{
				return GameTeam.ANY;
			}
			return (GameTeam)(signal - 1);
		}

		public static int GameTeamToCircuitSignal(GameTeam gameTeam)
		{
			if (gameTeam == GameTeam.ANY)
			{
				return -1;
			}
			return (int)(gameTeam + 1);
		}

		public static GameTeamPlayerIndex? CircuitSignalToGameTeamPlayerIndex(int signal)
		{
			if (signal == 0 || signal > MaxGameTeamPlayerIndexEnumValue + 1)
			{
				return null;
			}
			if (signal < 0)
			{
				return GameTeamPlayerIndex.ANY_INDEX;
			}
			return (GameTeamPlayerIndex)(signal - 1);
		}

		public static int GameTeamPlayerIndexToCircuitSignal(GameTeamPlayerIndex gameTeamPlayerIndex)
		{
			if (gameTeamPlayerIndex == GameTeamPlayerIndex.ANY_INDEX)
			{
				return -1;
			}
			return (int)(gameTeamPlayerIndex + 1);
		}

		public static PlayerStatType CircuitPlayerStatToPlayerStatType(CircuitPlayerStat stat)
		{
			return (PlayerStatType)(stat - 1000);
		}
	}
	public abstract class CircuitVisibilityBehaviour : UnityEngine.MonoBehaviour
	{
		private static List<CircuitVisibilityBehaviour> All = new List<CircuitVisibilityBehaviour>();

		private static bool _hideForLocalPlayer = false;

		private bool postStart;

		private bool _forceDisabled;

		public static bool HideForLocalPlayer
		{
			get
			{
				return _hideForLocalPlayer;
			}
			set
			{
				if (value != _hideForLocalPlayer)
				{
					_hideForLocalPlayer = value;
					CircuitVisibilityChanged();
				}
			}
		}

		public bool ForceDisabled
		{
			get
			{
				return _forceDisabled;
			}
			set
			{
				if (_forceDisabled != value)
				{
					_forceDisabled = value;
					UpdateVisibility();
				}
			}
		}

		public static bool ShouldBeVisible => GameSessions.LocalGameSession.IsSandbox && PhotonNetwork.inRoom && NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanEditCircuits.Value;

		public static void CircuitVisibilityChanged()
		{
			for (int i = 0; i < All.Count; i++)
			{
				All[i].UpdateVisibility();
			}
		}

		protected virtual void Awake()
		{
			All.Add(this);
		}

		private void Start()
		{
			UpdateVisibility();
			postStart = true;
		}

		private void OnEnable()
		{
			if (postStart)
			{
				UpdateVisibility();
			}
		}

		private void OnDestroy()
		{
			All.Remove(this);
		}

		private void UpdateVisibility()
		{
			bool isVisible = ShouldBeVisible && !ForceDisabled && !HideForLocalPlayer;
			UpdateVisibility(isVisible);
		}

		protected abstract void UpdateVisibility(bool isVisible);
	}
	public sealed class DisableInteractionWhenCircuitsHidden : CircuitVisibilityBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		private bool canLocalInteract = true;

		protected override void Awake()
		{
			base.Awake();
			tool.AddCustomPickupCondition(CustomToolPickupCondition);
			if (tool.CreationObject != null)
			{
				tool.CreationObject.AddCustomSelectionCondition(CustomCreationObjectSelectionCondition);
				tool.CreationObject.AddCustomRaycastFilter(CustomCreationObjectRaycastFilter);
			}
		}

		protected override void UpdateVisibility(bool isVisible)
		{
			canLocalInteract = isVisible;
		}

		private bool CustomToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (selectingPlayer.isLocal)
			{
				return canLocalInteract;
			}
			return NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetPlayerRoleDefinition(selectingPlayer.PhotonPlayer).CanEditCircuits.Value;
		}

		private CreationResult CustomCreationObjectSelectionCondition(CreationObject thisObject)
		{
			if (!canLocalInteract)
			{
				return CreationResult.Failure_PermissionDenied;
			}
			return CreationResult.Success;
		}

		private bool CustomCreationObjectRaycastFilter(CreationObject thisObject)
		{
			return canLocalInteract;
		}
	}
	public sealed class DisableObjectWhenCircuitsHidden : CircuitVisibilityBehaviour
	{
		protected override void UpdateVisibility(bool isVisible)
		{
			if (base.gameObject.activeSelf != isVisible)
			{
				base.gameObject.SetActive(isVisible);
			}
		}
	}
