	public class ComparerCircuitNodeDisplay : ModedCircuitNodeDisplay<ComparerNode>
	{
		private Action cachedValueUpdatedEvent;

		private bool cachedAdvancedMode;

		protected override Dictionary<string, EnumChoiceData> EditableOptions
		{
			get
			{
				Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
				SignalComparisonHelper.ComparerModes[] array = (SignalComparisonHelper.ComparerModes[])System.Enum.GetValues(typeof(SignalComparisonHelper.ComparerModes));
				foreach (SignalComparisonHelper.ComparerModes comparerModes in array)
				{
					dictionary[SignalComparisonHelper.GetModeSymbol(comparerModes)] = new EnumChoiceData
					{
						enumValue = (int)comparerModes
					};
				}
				return dictionary;
			}
		}

		protected override object ModeDictionaryKey => "mode";

		protected override int GetCircuitNodeMode()
		{
			if (base.MyCircuitNode is ComparerNode comparerNode)
			{
				return (int)comparerNode.ComparerMode;
			}
			return 0;
		}

		public override IEnumerable<SettingsEditEvent> GetEditables()
		{
			List<SettingsEditEvent> list = new List<SettingsEditEvent>(base.GetEditables());
			ComparerCircuitNodeDisplay thisObj = this;
			BoolSettingEditEvent item = new BoolSettingEditEvent((MakerPenPaletteConfigScreen uiControl) => uiControl.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				instance.PropertyGetter = GetAdvancedMode;
				instance.PropertySetter = SetAdvancedMode;
				UIHelper.SafeSetText(instance.PropertyDescription, "Advanced Mode");
				ComparerCircuitNodeDisplay comparerCircuitNodeDisplay = thisObj;
				comparerCircuitNodeDisplay.cachedValueUpdatedEvent = (Action)Delegate.Combine(comparerCircuitNodeDisplay.cachedValueUpdatedEvent, new Action(instance.UpdateControl));
				instance.OnDestroyEvent += delegate
				{
					if (thisObj != null)
					{
						ComparerCircuitNodeDisplay comparerCircuitNodeDisplay2 = thisObj;
						comparerCircuitNodeDisplay2.cachedValueUpdatedEvent = (Action)Delegate.Remove(comparerCircuitNodeDisplay2.cachedValueUpdatedEvent, new Action(instance.UpdateControl));
					}
				};
			});
			list.Add(item);
			return list;
		}

		private void SetAdvancedMode(bool advancedMode)
		{
			cachedAdvancedMode = advancedMode;
			if (base.MyCircuitNode != null)
			{
				Dictionary<object, object> dictionary = new Dictionary<object, object>();
				dictionary["adv"] = cachedAdvancedMode;
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterModifyNode(base.MyCircuitNode.NodeId, dictionary);
			}
		}

		private bool GetAdvancedMode()
		{
			return cachedAdvancedMode;
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			if (base.MyCircuitNode != null)
			{
				base.MyCircuitNode.NodeModifiedEvent += UpdateCachedAdvancedMode;
			}
			UpdateCachedAdvancedMode();
		}

		private void UpdateCachedAdvancedMode()
		{
			if (base.MyCircuitNode is ComparerNode comparerNode)
			{
				cachedAdvancedMode = comparerNode.AdvancedMode;
				if (cachedValueUpdatedEvent != null)
				{
					cachedValueUpdatedEvent();
				}
			}
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (base.MyCircuitNode != null)
			{
				base.MyCircuitNode.NodeModifiedEvent -= UpdateCachedAdvancedMode;
			}
		}
	}
