				return outputMeta;
			}
			set
			{
				outputMeta = value;
			}
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (gameManager != null)
			{
				gameManager.StateChangeEvent += RoomManager_StateChangeEvent;
			}
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			if (gameManager != null)
			{
				gameManager.StateChangeEvent -= RoomManager_StateChangeEvent;
			}
