		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			MomentarySourceNode momentarySourceNode = (MomentarySourceNode)node;
			momentarySourceNode.SetOutputMeta(outputMeta);
		}

		private void RoomManager_StateChangeEvent(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (currentStateId != previousStateId || currentSubStateId != previousSubStateId)
			{
				if (currentStateId == 1 && currentSubStateId == 2)
				{
					MasterSignalOnPreGame();
				}
				else if (currentStateId == 2)
				{
					MasterSignalOnGameStart();
				}
				else if (previousStateId == 2)
				{
					MasterSignalOnGameEnd();
				}
			}
		}

		private void MasterSignalOnPreGame()
		{
			if (PhotonNetwork.isMasterClient && base.MyCircuitNode != null)
			{
				MomentarySourceNode momentarySourceNode = (MomentarySourceNode)base.MyCircuitNode;
				momentarySourceNode.SetMomentaryOutput(OutputSlot.B, 1);
			}
		}

		private void MasterSignalOnGameStart()
		{
			if (PhotonNetwork.isMasterClient && base.MyCircuitNode != null)
			{
				MomentarySourceNode momentarySourceNode = (MomentarySourceNode)base.MyCircuitNode;
				momentarySourceNode.SetMomentaryOutput(OutputSlot.R, 1);
			}
		}

		private void MasterSignalOnGameEnd()
		{
			if (PhotonNetwork.isMasterClient && base.MyCircuitNode != null)
			{
				MomentarySourceNode momentarySourceNode = (MomentarySourceNode)base.MyCircuitNode;
				momentarySourceNode.SetMomentaryOutput(OutputSlot.G, 1);
			}
		}
	}
	public class GameStateOutputNodeDisplayOld : CircuitNodeDisplay, ICustomOutputNodeDisplay
	{
		[SerializeField]
		private InputMetadata[] inputMeta = new InputMetadata[3]
		{
			new InputMetadata
			{
				InputSlot = InputSlot.R,
				Description = "Game Started"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.G,
				Description = "Game Ended"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.B,
				Description = "Pre-Game Started"
			}
		};

		public InputMetadata[] InputMeta
		{
			get
			{
				return inputMeta;
			}
			set
			{
				inputMeta = value;
			}
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
			OutputNode outputNode = (OutputNode)node;
			outputNode.SetInputMeta(inputMeta);
			outputNode.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Combine(outputNode.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
		}

		private void OnNodeInputReceived(Dictionary<InputSlot, int> updates)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			GameManager instance = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (!(instance != null) || !GameManager.IsSandboxActive)
			{
				return;
			}
			if (updates.TryGetValue(InputSlot.R, out var value))
			{
				bool flag = CircuitNode.SignalToBool(value);
				if (!instance.IsGameRunning && flag)
				{
					instance.LocalPlayerStartGame();
				}
			}
			if (updates.TryGetValue(InputSlot.G, out var value2))
			{
				bool flag2 = CircuitNode.SignalToBool(value2);
				if (instance.IsGameRunning && flag2)
				{
					instance.LocalPlayerStopGame();
				}
			}
		}
	}
