	public class PlayerHitInputNodeDisplay : CircuitNodeDisplay, ICustomInputNodeDisplay
	{
		private const int NO_TEAM_INT = 0;

		[SerializeField]
		private OutputMetadata[] outputMeta = new OutputMetadata[5]
		{
			new OutputMetadata
			{
				OutputSlot = OutputSlot.R,
				Description = "Attacker"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.G,
				Description = "Defender"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.B,
				Description = "Attacker Team"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.C,
				Description = "Defender Team"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.M,
				Description = "Damage"
			}
		};

		private Dictionary<Tuple<int, int, int>, int> cachedHits = new Dictionary<Tuple<int, int, int>, int>();

		public OutputMetadata[] OutputMeta
		{
			get
			{
				return outputMeta;
			}
			set
			{
				outputMeta = value;
			}
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			CircuitManager.PreEvaluateEvent += FlushCachedHits;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent += MasterSignalPlayerOnPlayerDamage;
			}
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			CircuitManager.PreEvaluateEvent -= FlushCachedHits;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDamagedPlayerEvent -= MasterSignalPlayerOnPlayerDamage;
			}
		}

		private void MasterSignalPlayerOnPlayerDamage(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			Tuple<int, int, int> key = Tuple.Create(attacker.ID, defender.ID, weapon.photonView.viewID);
			int value = 0;
			if (cachedHits.TryGetValue(key, out value))
			{
			}
			damage += value;
			cachedHits[key] = damage;
		}

		private void FlushCachedHits()
		{
			QueuedMomentarySourceNode queuedMomentarySourceNode = base.MyCircuitNode as QueuedMomentarySourceNode;
			if (PhotonNetwork.isMasterClient && queuedMomentarySourceNode != null)
			{
				foreach (KeyValuePair<Tuple<int, int, int>, int> cachedHit in cachedHits)
				{
					int item = cachedHit.Key.Item1;
					int item2 = cachedHit.Key.Item2;
					int playerTeamInt = GetPlayerTeamInt(item);
					int playerTeamInt2 = GetPlayerTeamInt(item2);
					int value = cachedHit.Value;
					queuedMomentarySourceNode.SetMomentaryOutputs(new QueuedMomentarySourceNode.Output
					{
						outputSlot = OutputSlot.R,
						outputValue = item
					}, new QueuedMomentarySourceNode.Output
					{
						outputSlot = OutputSlot.G,
						outputValue = item2
					}, new QueuedMomentarySourceNode.Output
					{
						outputSlot = OutputSlot.B,
						outputValue = playerTeamInt
					}, new QueuedMomentarySourceNode.Output
					{
						outputSlot = OutputSlot.C,
						outputValue = playerTeamInt2
					}, new QueuedMomentarySourceNode.Output
					{
						outputSlot = OutputSlot.M,
						outputValue = value
					});
				}
			}
			cachedHits.Clear();
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			QueuedMomentarySourceNode queuedMomentarySourceNode = (QueuedMomentarySourceNode)node;
			queuedMomentarySourceNode.SetOutputMeta(outputMeta);
		}

		private static int GetPlayerTeamInt(int playerId)
		{
			PhotonPlayer photonPlayer = PhotonPlayer.Find(playerId);
			if (photonPlayer != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				GameTeamManager teamManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager;
				if (teamManager == null || teamManager.IsPlayerSpectator(photonPlayer))
				{
					return 0;
				}
				GameTeam playerTeam = teamManager.GetPlayerTeam(photonPlayer);
				return CircuitUtils.GameTeamToCircuitSignal(playerTeam);
			}
			return 0;
		}
	}
