		protected override object ModeDictionaryKey => "mode";

		private Dictionary<string, EnumChoiceData> EnumOptions
		{
			get
			{
				if (_enumOptions == null)
				{
					_enumOptions = new Dictionary<string, EnumChoiceData>();
					List<GameRole> sortedActiveRoles = PlayerGameRoleManager.Instance.GetSortedActiveRoles();
					foreach (GameRole item in sortedActiveRoles)
					{
