			{
				return 0;
			}
			return (int)playerRoleMappingNode.PlayerRoleMapMode;
		}

		public override IEnumerable<SettingsEditEvent> GetEditables()
		{
			List<SettingsEditEvent> list = new List<SettingsEditEvent>(base.GetEditables());
			CircuitNodeModeSettingEditEvent item = new CircuitNodeModeSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => uiControl, delegate(CircuitNodeModeEditableEnumUIControl instance)
			{
				instance.PropertyDescription.enabled = false;
				instance.PropertyGetter = GetRoleId;
				instance.PropertySetter = SetRoleId;
				if (base.MyCircuitNode != null)
				{
					CircuitNode myCircuitNode = base.MyCircuitNode;
					myCircuitNode.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Combine(myCircuitNode.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
				}
				instance.OnDestroyEvent += delegate
				{
					if (base.MyCircuitNode != null)
					{
						CircuitNode myCircuitNode2 = base.MyCircuitNode;
						myCircuitNode2.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Remove(myCircuitNode2.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
					}
				};
				instance.UpdateControlFunction = UpdateSettingUIControl;
			}, EnumOptions);
			list.Add(item);
			return list;
		}

		private void UpdateSettingUIControl(CircuitNodeModeEditableEnumUIControl instance)
		{
			if (EnumOptions.Count == 0)
			{
				instance.PropertyValueText.text = "Add Custom Game Roles to Select One.";
			}
			else
			{
				instance.PropertyValueText.text = "Player Role";
			}
		}

		public int GetRoleId()
		{
			return (base.MyCircuitNode is PlayerRoleMappingNode playerRoleMappingNode) ? playerRoleMappingNode.ModificationRoleId : 0;
		}

		private void SetRoleId(int roleId)
		{
			Dictionary<object, object> dictionary = new Dictionary<object, object>();
			dictionary.Add("roleId", roleId);
			Dictionary<object, object> modifyArgs = dictionary;
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterModifyNode(base.MyCircuitNode.NodeId, modifyArgs);
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerHasRole += PlayerHasRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerAddRole += PlayerAddRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerRemoveRole += PlayerRemoveRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).TeamAddRole += TeamAddRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).TeamRemoveRole += TeamRemoveRole;
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, GameRole>(OnPlayerRolesChanged);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent += new Action(OnRoleOrdersChanged);
		}

		private void OnRoleOrdersChanged()
		{
			_enumOptions = null;
			InitializeEditables(force: true);
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerHasRole -= PlayerHasRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerAddRole -= PlayerAddRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).PlayerRemoveRole -= PlayerRemoveRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).TeamAddRole -= TeamAddRole;
			((PlayerRoleMappingNode)base.MyCircuitNode).TeamRemoveRole -= TeamRemoveRole;
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, GameRole>(OnPlayerRolesChanged);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent -= new Action(OnRoleOrdersChanged);
		}

		private void OnPlayerRolesChanged(PhotonPlayer photonPlayer, GameRole newRoleDefinition)
		{
			if (base.MyCircuitNode is PlayerRoleMappingNode playerRoleMappingNode && (playerRoleMappingNode.PlayerRoleMapMode == PlayerRoleMappingNode.PlayerRoleMapModes.PlayerHasRole || playerRoleMappingNode.PlayerRoleMapMode == PlayerRoleMappingNode.PlayerRoleMapModes.PlayerRoleChanged))
			{
				playerRoleMappingNode.MarkDirtyForRoleChange(photonPlayer.ID);
			}
		}

		private bool PlayerHasRole(int playerId, int roleId)
		{
			PhotonPlayer photonPlayer = PhotonPlayer.Find(playerId);
			return PlayerGameRoleManager.Instance.PlayerHasRole(photonPlayer, (GameRoleId)roleId);
		}

		private void PlayerAddRole(int circuitPlayerSignal, int roleId)
		{
			TogglePlayerRolesForPlayerIdCircuitSignal(circuitPlayerSignal, roleId, roleEnabled: true);
		}

		private void PlayerRemoveRole(int circuitPlayerSignal, int roleId)
		{
			TogglePlayerRolesForPlayerIdCircuitSignal(circuitPlayerSignal, roleId, roleEnabled: false);
		}

		private void TeamAddRole(int circuitTeamSignal, int roleId)
		{
			TogglePlayerRolesForTeamIdCircuitSignal(circuitTeamSignal, roleId, roleEnabled: true);
		}

		private void TeamRemoveRole(int circuitTeamSignal, int roleId)
		{
			TogglePlayerRolesForTeamIdCircuitSignal(circuitTeamSignal, roleId, roleEnabled: false);
		}

		private void TogglePlayerRolesForTeamIdCircuitSignal(int circuitTeamSignal, int roleId, bool roleEnabled)
		{
			if (RoleIdHelper.IsAGRole((GameRoleId)roleId))
			{
				return;
			}
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(circuitTeamSignal);
			if (gameTeam.HasValue)
			{
				PhotonPlayer[] teamPlayers = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayers(gameTeam.Value);
				for (int i = 0; i < teamPlayers.Length; i++)
				{
					_ToggleRoleForPlayer((GameRoleId)roleId, teamPlayers[i], roleEnabled);
				}
			}
		}

		private void TogglePlayerRolesForPlayerIdCircuitSignal(int circuitPlayerSignal, int roleId, bool roleEnabled)
		{
			GameRoleId gameRoleId = (GameRoleId)roleId;
			if (!RoleIdHelper.IsAGRole(gameRoleId))
			{
				CircuitUtils.ForPlayerSignal(circuitPlayerSignal, delegate(PhotonPlayer photonPlayer)
				{
					_ToggleRoleForPlayer(gameRoleId, photonPlayer, roleEnabled);
				});
			}
		}

		private void _ToggleRoleForPlayer(GameRoleId gameRoleId, PhotonPlayer player, bool enabled)
		{
			if (player != null && player.IsLocal)
			{
				if (enabled)
				{
					PlayerGameRoleManager.Instance.RequestAddRole(PhotonNetwork.player, gameRoleId);
				}
				else
				{
					PlayerGameRoleManager.Instance.RequestRemoveRole(player, gameRoleId);
				}
			}
		}
	}
	public class PlayerTeamMappingNodeDisplay : ModedCircuitNodeDisplay<PlayerTeamMappingNode>
	{
		private const string playerToTeamTitle = "Player to Team";

		private const string playerToTeamTooltip = "";

		private const string teamToPlayerTitle = "Team to Player";

		private const string teamToPlayerTooltip = "";

		private const string setPlayerTeamTitle = "Set Player Team";

		private const string setPlayerTeamTooltip = "Change the team a player is on";

		private const string getTeamPlayerCountTitle = "Get Team Player Count";

		private const string getTeamPlayerCountTooltip = "";

		private static readonly Dictionary<string, EnumChoiceData> friendlyModes = new Dictionary<string, EnumChoiceData>
		{
			{
				"Player to Team",
				new EnumChoiceData
				{
					enumValue = 0,
					tooltip = string.Empty
				}
			},
			{
				"Team to Player",
