		protected override int GetCircuitNodeMode()
		{
			if (!(base.MyCircuitNode is PlayerTeamMappingNode playerTeamMappingNode))
			{
				return 0;
			}
			return (int)playerTeamMappingNode.PlayerIdMapMode;
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			((PlayerTeamMappingNode)base.MyCircuitNode).PlayerToTeamIndex += PlayerToTeamIndex;
			((PlayerTeamMappingNode)base.MyCircuitNode).TeamIndexToPlayer += TeamIndexToPlayer;
			((PlayerTeamMappingNode)base.MyCircuitNode).PlayerSetTeam += PlayerSetTeam;
			((PlayerTeamMappingNode)base.MyCircuitNode).GetTeamPlayerCount += GetTeamSize;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent += OnPlayerChangedTeams;
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			((PlayerTeamMappingNode)base.MyCircuitNode).PlayerToTeamIndex -= PlayerToTeamIndex;
			((PlayerTeamMappingNode)base.MyCircuitNode).TeamIndexToPlayer -= TeamIndexToPlayer;
			((PlayerTeamMappingNode)base.MyCircuitNode).PlayerSetTeam -= PlayerSetTeam;
			((PlayerTeamMappingNode)base.MyCircuitNode).GetTeamPlayerCount -= GetTeamSize;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent -= OnPlayerChangedTeams;
			}
		}

		private void OnPlayerChangedTeams()
		{
			if (base.MyCircuitNode is PlayerTeamMappingNode { PlayerIdMapMode: not PlayerTeamMappingNode.PlayerIdMapModes.SetPlayerTeam } playerTeamMappingNode)
			{
				playerTeamMappingNode.MarkDirtyForTeamChange();
			}
		}

		private void TeamIndexToPlayer(int teamId, int teamIndex, out int playerId)
		{
			playerId = 0;
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(teamId);
			GameTeamPlayerIndex? gameTeamPlayerIndex = CircuitUtils.CircuitSignalToGameTeamPlayerIndex(teamIndex);
			if (gameTeam.HasValue && gameTeamPlayerIndex.HasValue && gameTeam.Value != GameTeam.ANY && gameTeamPlayerIndex.Value != GameTeamPlayerIndex.ANY_INDEX)
			{
				PhotonPlayer playerAtTeamPlayerIndex = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerAtTeamPlayerIndex(gameTeam.Value, gameTeamPlayerIndex.Value);
				if (playerAtTeamPlayerIndex != null)
				{
					playerId = playerAtTeamPlayerIndex.ID;
				}
			}
		}

		private void PlayerToTeamIndex(int playerId, out int teamId, out int teamIndex)
		{
			teamId = 0;
			teamIndex = 0;
			PhotonPlayer photonPlayer = PhotonPlayer.Find(playerId);
			if (photonPlayer != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TryGetPlayerTeamAndIndex(photonPlayer, out var gameTeam, out var gameTeamPlayerIndex))
			{
				teamId = CircuitUtils.GameTeamToCircuitSignal(gameTeam);
				teamIndex = CircuitUtils.GameTeamPlayerIndexToCircuitSignal(gameTeamPlayerIndex);
			}
		}

		private void PlayerSetTeam(int circuitPlayerSignal, int teamId)
		{
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(teamId);
			if (gameTeam.HasValue && gameTeam.Value != GameTeam.ANY)
			{
				CircuitUtils.ForPlayerSignal(circuitPlayerSignal, delegate(PhotonPlayer photonPlayer)
				{
					_SetPlayerTeam(photonPlayer, gameTeam.Value);
				});
			}
		}

		private void _SetPlayerTeam(PhotonPlayer photonPlayer, GameTeam gameTeam)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(photonPlayer) != gameTeam)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.MasterAssignTeam(photonPlayer, gameTeam, GameTeam.ANY, preferPartiedTeam: true, failover: false);
			}
		}

		private void GetTeamSize(int teamId, out int teamPlayerCount)
		{
			teamPlayerCount = 0;
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(teamId);
			if (gameTeam.HasValue)
			{
				teamPlayerCount = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamPlayerCount(gameTeam.Value);
			}
		}
	}
	public class RespawnPlayerNodeDisplay : CircuitNodeDisplay, ICustomOutputNodeDisplay
	{
