			},
			new InputMetadata
			{
				InputSlot = InputSlot.G,
				Description = "Respawn Entire Team"
			}
		};

		public InputMetadata[] InputMeta
		{
			get
			{
				return inputMeta;
			}
			set
			{
				inputMeta = value;
			}
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
			OutputNode outputNode = (OutputNode)node;
			outputNode.SetInputMeta(inputMeta);
			outputNode.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Combine(outputNode.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (base.MyCircuitNode != null)
			{
				OutputNode obj = (OutputNode)base.MyCircuitNode;
				obj.OutputNodeUpdatedEvent = (OutputNode.OutputNodeUpdated)Delegate.Remove(obj.OutputNodeUpdatedEvent, new OutputNode.OutputNodeUpdated(OnNodeInputReceived));
			}
		}

		private void OnNodeInputReceived(Dictionary<InputSlot, int> updates)
		{
			int value2;
			if (updates.TryGetValue(InputSlot.R, out var value) && (value == PhotonNetwork.player.ID || value < 0))
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
			}
			else if (updates.TryGetValue(InputSlot.G, out value2))
			{
				GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(value2);
				if (gameTeam.HasValue && (gameTeam.Value == GameTeam.ANY || NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == gameTeam.Value))
				{
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawn();
				}
			}
		}
	}
