	public class SetPlayerStatNodeDisplay : ModedCircuitNodeDisplay<PlayerSetStatNode>
	{
		private static float nextWarningMessageTime;

		protected override Dictionary<string, EnumChoiceData> EditableOptions
		{
			get
			{
				Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
				foreach (KeyValuePair<string, int> item in FriendlyCircuitPlayerStats.FriendlyCircuitPlayerStatsDict)
				{
					dictionary[item.Key] = new EnumChoiceData
					{
						enumValue = item.Value
					};
				}
				return dictionary;
			}
		}

		protected override object ModeDictionaryKey => "mode";

		protected override int GetCircuitNodeMode()
		{
			if (base.MyCircuitNode is PlayerSetStatNode playerSetStatNode)
			{
				return (int)playerSetStatNode.PlayerStat;
			}
			return 0;
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			PlayerSetStatNode playerSetStatNode = (PlayerSetStatNode)base.MyCircuitNode;
			playerSetStatNode.SetPlayerStat += SetPlayerStat;
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			PlayerSetStatNode playerSetStatNode = (PlayerSetStatNode)base.MyCircuitNode;
			playerSetStatNode.SetPlayerStat -= SetPlayerStat;
		}

		private void SetPlayerStat(CircuitPlayerStat stat, int playerId, int signal)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || !NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
			{
				if (PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanEditCircuits.Value && nextWarningMessageTime < UnityEngine.Time.realtimeSinceStartup)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Can't change stats when not in game!", 3f);
					nextWarningMessageTime = UnityEngine.Time.realtimeSinceStartup + 15f;
				}
			}
			else
			{
				CircuitUtils.ForPlayerSignal(playerId, delegate(PhotonPlayer photonPlayer)
				{
					_SetPlayerStat(stat, signal, photonPlayer);
				});
			}
		}

		private void _SetPlayerStat(CircuitPlayerStat stat, int signal, params PhotonPlayer[] players)
		{
			foreach (PhotonPlayer photonPlayer in players)
			{
				if (stat == CircuitPlayerStat.Player_Health)
				{
					int maxHealth = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.CombatSettings.MaxHealth;
					signal = Mathf.Clamp(signal, 0, maxHealth);
					MasterUpdatePlayerHealth(photonPlayer, signal);
				}
				else
				{
					PlayerStatType stat2 = CircuitUtils.CircuitPlayerStatToPlayerStatType(stat);
					NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.MasterSetPlayerStat(photonPlayer, stat2, signal);
				}
			}
		}

		private void MasterUpdatePlayerHealth(PhotonPlayer photonPlayer, int newHealth)
		{
			int playerHealth = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.GetPlayerHealth(photonPlayer);
			int num = newHealth - playerHealth;
			if (playerHealth != 0 && newHealth == 0)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterKillPlayer(photonPlayer);
				return;
			}
			if (num > 0)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterRestorePlayerHealth(photonPlayer, num, 0f);
				return;
			}
			int damage = Math.Abs(num);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.MasterDamagePlayer(photonPlayer, damage, ignoreShield: false);
		}
	}
