	public class LightCircuitNode : CircuitEventNodeDisplayBase
	{
		[Serializable]
		private struct ColorPair
		{
			public Color GlowColor;

			public Color ShaftColor;

			public static bool operator ==(ColorPair pair1, ColorPair pair2)
			{
				return pair1.GlowColor == pair2.GlowColor && pair1.ShaftColor == pair2.ShaftColor;
			}

			public static bool operator !=(ColorPair pair1, ColorPair pair2)
			{
				return pair1.GlowColor != pair2.GlowColor || pair1.ShaftColor != pair2.ShaftColor;
			}

			public override bool Equals(object obj)
			{
				if (obj == null || GetType() != obj.GetType())
				{
					return false;
				}
				ColorPair colorPair = (ColorPair)obj;
				return GlowColor == colorPair.GlowColor && ShaftColor == colorPair.ShaftColor;
			}

			public override int GetHashCode()
			{
				return GlowColor.GetHashCode() ^ ShaftColor.GetHashCode();
			}
		}

		private const InputSlot ON_OFF_SLOT = InputSlot.C;

		private const InputSlot COLOR_SLOT = InputSlot.M;

		private const InputSlot INTENSITY_SLOT = InputSlot.Y;

		[SerializeField]
		private Renderer shaftRenderer;

		[SerializeField]
		private Renderer glowRenderer;

		[SerializeField]
		[Range(0f, 1f)]
		[Tooltip("Max possible alpha for light colors")]
		private float maxIntensity = 0.2f;

		[SerializeField]
		private int defaultColorIndex = 11;

		private InputMetadata[] inputMetadata = new InputMetadata[3]
		{
			new InputMetadata
			{
				InputSlot = InputSlot.C,
				Description = "On/Off"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.M,
				Description = "Color"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.Y,
				Description = "Intensity"
			}
		};

		[SerializeField]
		private ColorPair[] colors = new ColorPair[0];

		private float lightIntensity = -1f;

		private ColorPair? circuitColor;

		private ColorPair lightColors;

		private ColorPair defaultColors = new ColorPair
		{
			GlowColor = Color.white,
			ShaftColor = Color.white
		};

		private MaterialPropertyBlock shaftMaterialPropertyBlock;

		private MaterialPropertyBlock glowMaterialPropertyBlock;

		private static Dictionary<InputSlot, int> offUpdates = new Dictionary<InputSlot, int>
		{
			{
				InputSlot.C,
				0
			},
			{
				InputSlot.M,
				0
			},
			{
				InputSlot.Y,
				0
			}
		};

		private bool _lightEnabled = true;

		public override InputMetadata[] InputMeta
		{
			get
			{
				return inputMetadata;
			}
			set
			{
				inputMetadata = value;
			}
		}

		public bool LightEnabled
		{
			get
			{
				return _lightEnabled;
			}
			set
			{
				if (_lightEnabled != value)
				{
					_lightEnabled = value;
					OnLightEnabledChanged();
				}
			}
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			Dictionary<InputSlot, int> dictionary = new Dictionary<InputSlot, int>();
			dictionary.Add(InputSlot.C, base.MyCircuitNode.GetInputSignal(InputSlot.C));
			dictionary.Add(InputSlot.M, base.MyCircuitNode.GetInputSignal(InputSlot.M));
			dictionary.Add(InputSlot.Y, base.MyCircuitNode.GetInputSignal(InputSlot.Y));
			Dictionary<InputSlot, int> updates = dictionary;
			NodeInputUpdate(updates);
		}

		protected override void Awake()
		{
			shaftMaterialPropertyBlock = new MaterialPropertyBlock();
			glowMaterialPropertyBlock = new MaterialPropertyBlock();
			defaultColors = colors[defaultColorIndex];
			base.Awake();
			NodeInputUpdate(offUpdates);
		}

		protected override void NodeInputUpdate(Dictionary<InputSlot, int> updates)
		{
			int value = 0;
			if (updates.TryGetValue(InputSlot.C, out value))
			{
				LightEnabled = CircuitNode.SignalToBool(value);
			}
			bool flag = false;
			int value2 = 0;
			if (updates.TryGetValue(InputSlot.M, out value2))
			{
				ColorPair? colorPair = ((value2 <= 0) ? ((ColorPair?)null) : new ColorPair?(colors[(value2 - 1) % colors.Length]));
				if (circuitColor != colorPair)
				{
					circuitColor = colorPair;
					flag = true;
				}
			}
			int value3 = 0;
			if (updates.TryGetValue(InputSlot.Y, out value3))
			{
				float num = Mathf.InverseLerp(0f, 100f, value3) * maxIntensity;
				if (lightIntensity != num)
				{
					lightIntensity = num;
					flag = true;
				}
			}
			if (flag)
			{
				OnLightParamsChanged();
			}
		}

		private void OnLightEnabledChanged()
		{
			shaftRenderer.gameObject.SetActive(LightEnabled);
			glowRenderer.gameObject.SetActive(LightEnabled);
		}

		private void OnLightParamsChanged()
		{
			if (circuitColor.HasValue)
			{
				lightColors = circuitColor.Value;
			}
			else
			{
				lightColors = defaultColors;
			}
			lightColors.ShaftColor.a = lightIntensity;
			lightColors.GlowColor.a = 1f - maxIntensity + lightIntensity;
			shaftMaterialPropertyBlock.SetColor("_TintColor", lightColors.ShaftColor);
			glowMaterialPropertyBlock.SetColor("_Color", lightColors.GlowColor);
			shaftRenderer.SetPropertyBlock(shaftMaterialPropertyBlock);
			glowRenderer.SetPropertyBlock(glowMaterialPropertyBlock);
		}
	}
	public class MessageOutputNodeVisualization : CircuitEventNodeDisplay
	{
		[SerializeField]
		private float screenSpaceMessageDuration = 1f;

		private SynchronizedField<string> _message;

		public string Message
