		public override IEnumerable<SettingsEditEvent> GetEditables()
		{
			StringSettingEditEvent stringSettingEditEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultStringUIControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				instance.PropertyGetter = GetMessage;
				instance.PropertySetter = SetMessage;
				instance.PropertyDescription.text = "Message";
				instance.SetDialogOptions("Message", "Enter a message to broadcast.", TMP_InputField.ContentType.Standard, purifyString: true);
				instance.UpdateControlFunction = delegate(CreationObjectSettingStringUIControl ui)
				{
					ui.PropertyValueText.text = GetMessage();
				};
			});
			return new SettingsEditEvent[1] { stringSettingEditEvent };
		}

		protected override void Awake()
		{
			base.Awake();
			_message = new SynchronizedField<string>(this, "msg", "Hello, world", SetterPermissionMode.MASTER_OR_AUTHORITY);
			if (OnRecievedNewInput == null)
			{
				OnRecievedNewInput = new NodeInputReceived();
			}
			OnRecievedNewInput.AddListener(PlayScreenSpaceMessage);
		}

		private void PlayScreenSpaceMessage(Dictionary<InputSlot, int> signals)
		{
			string text = string.Empty;
			if (Message != null && base.MyCircuitNode != null)
			{
				text = Message;
				InputMetadata[] inputMetadata = base.MyCircuitNode.NodeMetadata.InputMetadata;
				for (int i = 0; i < inputMetadata.Length; i++)
				{
					InputSlot inputSlot = inputMetadata[i].InputSlot;
					string text2 = $"{{{inputSlot.ToString().ToUpper()}}}";
					string text3 = $"{{{inputSlot.ToString().ToUpper()}}}";
					if (text.Contains(text2))
					{
						text = text.Replace(text2, base.MyCircuitNode.GetInputSignal(inputSlot).ToString());
					}
					if (text.Contains(text3))
					{
						text = text.Replace(text3, base.MyCircuitNode.GetInputSignal(inputSlot).ToString());
					}
				}
			}
			if (!string.IsNullOrEmpty(text))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, text, screenSpaceMessageDuration);
			}
		}

		private void SetMessage(string newMessage)
		{
			Message = newMessage;
		}

		private string GetMessage()
		{
			return (!string.IsNullOrEmpty(Message)) ? Message : string.Empty;
		}

		public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData != null && viewData.MessageData != null)
			{
				if (viewData.MessageData.Messages.Count > 0)
				{
					Message = viewData.MessageData.Messages[0];
				}
				else
				{
					Message = viewData.MessageData.Message;
				}
			}
			else
			{
				Message = string.Empty;
			}
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.MessageData == null)
			{
				viewData.MessageData = new MessageData();
			}
			else
			{
				viewData.MessageData.Messages.Clear();
			}
			viewData.MessageData.Messages.Add(Message);
		}
	}
	public abstract class ModedCircuitNodeDisplay<T> : CircuitNodeDisplay where T : CircuitNode
	{
		[SerializeField]
		protected CircuitNodeModeEditableEnumUIControl uiControl;

		[SerializeField]
		protected Sprite[] circuitLabelSprites;

		public override Sprite CircuitNodeSprite
		{
			get
			{
				if (base.MyCircuitNode == null)
				{
					return defaultCircuitLabelSprite;
				}
				int circuitNodeMode = GetCircuitNodeMode();
				if (circuitNodeMode >= 0 && circuitNodeMode < circuitLabelSprites.Length)
				{
					return circuitLabelSprites[circuitNodeMode];
				}
				return defaultCircuitLabelSprite;
			}
		}

		protected abstract Dictionary<string, EnumChoiceData> EditableOptions { get; }

		protected abstract object ModeDictionaryKey { get; }

		protected abstract int GetCircuitNodeMode();

		public override IEnumerable<SettingsEditEvent> GetEditables()
		{
			Dictionary<string, EnumChoiceData> editableOptions = EditableOptions;
			CircuitNodeModeSettingEditEvent circuitNodeModeSettingEditEvent = new CircuitNodeModeSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => uiControl, delegate(CircuitNodeModeEditableEnumUIControl instance)
			{
				instance.PropertyGetter = GetCircuitNodeMode;
				instance.PropertySetter = SetMode;
				if (base.MyCircuitNode != null)
				{
					CircuitNode myCircuitNode = base.MyCircuitNode;
					myCircuitNode.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Combine(myCircuitNode.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
				}
				instance.OnDestroyEvent += delegate
				{
					if (base.MyCircuitNode != null)
					{
						CircuitNode myCircuitNode2 = base.MyCircuitNode;
						myCircuitNode2.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Remove(myCircuitNode2.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
					}
				};
				instance.UpdateControlFunction = UpdateSettingUIControl;
			}, editableOptions);
			return new SettingsEditEvent[1] { circuitNodeModeSettingEditEvent };
		}

		private void UpdateSettingUIControl(CircuitNodeModeEditableEnumUIControl obj)
		{
			if (base.MyCircuitNode != null)
			{
				obj.PropertyValueText.text = base.MyCircuitNode.NodeMetadata.NodeDescription;
			}
			else
			{
				obj.PropertyValueText.text = string.Empty;
			}
		}

		private void SetMode(int newMode)
		{
			Dictionary<object, object> dictionary = new Dictionary<object, object>();
			dictionary.Add(ModeDictionaryKey, newMode);
			Dictionary<object, object> modifyArgs = dictionary;
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterModifyNode(base.MyCircuitNode.NodeId, modifyArgs);
		}
	}
