	public class ObjectPlayerMappingNodeDisplay : CircuitNodeDisplay
	{
		private Tool currentTool;

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			((ObjectPlayerMappingNode)base.MyCircuitNode).ObjectToHoldingPlayer += ObjectToHoldingPlayer;
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			((ObjectPlayerMappingNode)base.MyCircuitNode).ObjectToHoldingPlayer -= ObjectToHoldingPlayer;
		}

		private void OnCurrentToolChangedHands(Tool tool)
		{
			((ObjectPlayerMappingNode)base.MyCircuitNode).NodeGraph.NodeGraphDirty = true;
		}

		private void ObjectToHoldingPlayer(int objectId, out int lastHeldPlayer, out int currentHoldingPlayer)
		{
			currentHoldingPlayer = 0;
			lastHeldPlayer = 0;
			PhotonView photonView = PhotonView.Find(objectId);
			Tool tool = currentTool;
			currentTool = null;
			if (photonView != null)
			{
				currentTool = photonView.GetComponent<Tool>();
				if (currentTool != null)
				{
					if (currentTool.HolderPlayer != null)
					{
						currentHoldingPlayer = currentTool.HolderPlayer.PhotonPlayer.ID;
						lastHeldPlayer = currentHoldingPlayer;
					}
					else if (currentTool.PreviousNonNullHolderPlayer != null)
					{
						lastHeldPlayer = currentTool.PreviousNonNullHolderPlayer.PhotonPlayer.ID;
					}
				}
			}
			if (tool != currentTool)
			{
				if (tool != null)
				{
					tool.HolderChangedEvent -= OnCurrentToolChangedHands;
				}
				if (currentTool != null)
				{
					currentTool.HolderChangedEvent += OnCurrentToolChangedHands;
				}
			}
		}
	}
