		private void ChangeTagsForObject(int objectId)
		{
			PhotonView photonView = PhotonView.Find(objectId);
			if (!(photonView != null))
			{
				return;
			}
			TaggedTool component = photonView.GetComponent<TaggedTool>();
			if (component != null)
			{
				if (SetTagsNode.ChangeMode == ObjectSetTagsNode.ChangeModes.Add && !string.IsNullOrEmpty(TagName))
				{
					component.RequestAddTag(TagName);
				}
				else if (SetTagsNode.ChangeMode == ObjectSetTagsNode.ChangeModes.Remove && !string.IsNullOrEmpty(TagName))
				{
					component.RemoveTag(TagName);
				}
				else if (SetTagsNode.ChangeMode == ObjectSetTagsNode.ChangeModes.Defaults)
				{
					component.ResetTags();
				}
			}
		}

