		{
			base.DeserializeFrom(deserializeParams);
			SetTagsNodeData setTagsNodeData = deserializeParams.viewData.SetTagsNodeData;
			if (setTagsNodeData != null && setTagsNodeData.SetTag != null)
			{
				TagName = setTagsNodeData.SetTag.Tags[0];
			}
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			base.SerializeTo(ref viewData, ref transientData, outputLog);
			viewData.SetTagsNodeData = new SetTagsNodeData
			{
				SetTag = new TagData()
			};
			viewData.SetTagsNodeData.SetTag.Tags.Add(TagName);
		}
	}
