			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.G,
				Description = "Player Left"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.B,
				Description = "# of Players"
			},
			new OutputMetadata
			{
				OutputSlot = OutputSlot.C,
				Description = "Player Switched Teams"
			}
		};

