		public OutputMetadata[] OutputMeta
		{
			get
			{
				return outputMeta;
			}
			set
			{
				outputMeta = value;
			}
		}

		public override void OnCircuitNodeInitialized(CircuitNode node)
		{
			base.OnCircuitNodeInitialized(node);
			SourceNode sourceNode = (SourceNode)node;
			sourceNode.SetOutputMeta(outputMeta);
			UpdatePlayerCount(sourceNode);
		}

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			Player.PlayerCreatedEvent += new Action<Player>(OnPlayerCreated);
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerLeft);
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent += PlayerSwitchedTeams;
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			Player.PlayerCreatedEvent -= new Action<Player>(OnPlayerCreated);
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerLeft);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent -= PlayerSwitchedTeams;
			}
		}

		private void OnPlayerCreated(Player player)
		{
			SourceNode sourceNode = SourceNode;
			if (PhotonNetwork.isMasterClient && sourceNode != null && player != null)
			{
				sourceNode.SetMomentaryOutput(OutputSlot.R, player.PhotonPlayer.ID);
				UpdatePlayerCount(sourceNode);
			}
		}

		private void OnPhotonPlayerLeft(PhotonPlayer photonPlayer)
		{
			SourceNode sourceNode = SourceNode;
			if (PhotonNetwork.isMasterClient && sourceNode != null)
			{
				sourceNode.SetMomentaryOutput(OutputSlot.G, photonPlayer.ID);
				UpdatePlayerCount(sourceNode);
			}
		}

		private void UpdatePlayerCount(SourceNode node)
		{
			node.SetContinuousOutput(OutputSlot.B, PhotonNetwork.playerList.Length);
		}

		private void PlayerSwitchedTeams(PhotonPlayer photonPlayer, bool isDisconnecting)
		{
			SourceNode sourceNode = SourceNode;
			if (PhotonNetwork.isMasterClient && sourceNode != null && !isDisconnecting)
			{
				sourceNode.SetMomentaryOutput(OutputSlot.C, photonPlayer.ID);
			}
		}
	}
