	{
		[SerializeField]
		private Tooltip tooltip;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private PlayerEditableText playerEditableText;

		[SerializeField]
		private ScreenSpaceNotificationManager.NotificationType notificationType = ScreenSpaceNotificationManager.NotificationType.Medium;

		[SerializeField]
		private float duration = 1f;

		private const InputSlot ALL_SLOT = InputSlot.R;

		private const InputSlot PLAYER_SLOT = InputSlot.G;

		private const InputSlot TEAM_SLOT = InputSlot.B;

		[SerializeField]
		private InputMetadata[] inputMeta = new InputMetadata[3]
		{
			new InputMetadata
			{
				InputSlot = InputSlot.R,
				Description = "Play for All"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.G,
				Description = "Play for Player"
			},
			new InputMetadata
			{
				InputSlot = InputSlot.B,
				Description = "Play for Team"
			}
		};

		private string screenSpaceMessage;

		public override InputMetadata[] InputMeta
		{
			get
			{
				return inputMeta;
			}
			set
			{
				inputMeta = value;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			playerEditableText.OnTextUpdated.AddListener(SetScreenSpaceMessage);
		}

		protected override void OnDestroying(PhotonView destroyingPhotonView)
		{
			base.OnDestroying(destroyingPhotonView);
			if (playerEditableText != null)
			{
				playerEditableText.OnTextUpdated.RemoveListener(SetScreenSpaceMessage);
			}
		}

		public void SetScreenSpaceMessage(string message)
		{
			screenSpaceMessage = message;
			if (tooltip != null)
			{
				tooltip.Message = message;
			}
		}

		public void BroadcastScreenSpaceMessage(Dictionary<InputSlot, int> updates)
		{
			playerEditableText.Circuit_UpdateText(updates);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(notificationType, screenSpaceMessage, duration);
		}

		protected override void NodeInputUpdate(Dictionary<InputSlot, int> updates)
		{
			int value = 0;
			if (updates.TryGetValue(InputSlot.R, out value) && CircuitNode.SignalToBool(value))
			{
				BroadcastScreenSpaceMessage(updates);
				return;
			}
			int value2 = 0;
			if (updates.TryGetValue(InputSlot.G, out value2) && value2 == PhotonNetwork.player.ID)
			{
				BroadcastScreenSpaceMessage(updates);
				return;
			}
			int value3 = 0;
			if (!(NetworkedSingletonMonoBehaviour<GameManager>.Instance != null) || !updates.TryGetValue(InputSlot.B, out value3))
			{
				return;
			}
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(value3);
			if (gameTeam.HasValue)
			{
				GameTeam value4 = gameTeam.Value;
				if (value4 == GameTeam.ANY || value4 == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player))
				{
					BroadcastScreenSpaceMessage(updates);
				}
			}
		}
	}
