			{
				int index = i;
				Func<SelectorNode.SelectorConfig> getter = () => GetSelectorNodeConfigAtIndex(index);
				Action<SelectorNode.SelectorConfig> setter = delegate(SelectorNode.SelectorConfig config)
				{
