		{
			get
			{
				return _useSpatialAudio.Get();
			}
			set
			{
				_useSpatialAudio.Set(value);
			}
		}

		public bool InterruptCurrentSound
		{
			get
			{
				return _interruptCurrentSound.Get();
			}
			set
			{
				_interruptCurrentSound.Set(value);
			}
		}

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			_selectedSFXIndex = new SynchronizedField<int>(this, "sfxi", 0, SetterPermissionMode.ANYONE);
			_useSpatialAudio = new SynchronizedField<bool>(this, "sfxs", defaultValue: false, SetterPermissionMode.ANYONE);
			_interruptCurrentSound = new SynchronizedField<bool>(this, "sfxics", defaultValue: false, SetterPermissionMode.ANYONE);
		}

		private void Start()
		{
			CreationObject component = GetComponent<CreationObject>();
			Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
			for (int i = 0; i < availableSFXClips.Length; i++)
			{
				dictionary.Add(availableSFXClips[i].FriendlyName, new EnumChoiceData
				{
					enumValue = i
				});
			}
			BoolSettingEditEvent settingEvent = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUiFlow) => editableUiFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, use3dAudioSettingDescription);
				instance.PropertyGetter = SFXSpatial_Get;
				instance.PropertySetter = SFXSpatial_Set;
			});
			component.AddConfigurableSetting(0, settingEvent);
			EnumSettingEditEvent settingEvent2 = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, soundSettingDescription);
				instance.PropertyGetter = SFXIndex_Get;
				instance.PropertySetter = SFXIndex_Set;
			}, dictionary);
			component.AddConfigurableSetting(0, settingEvent2);
			BoolSettingEditEvent settingEvent3 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, interruptCurrentSoundDescription);
				instance.PropertyGetter = SFXInterrupt_Get;
				instance.PropertySetter = SFXInterrupt_Set;
			});
			component.AddConfigurableSetting(0, settingEvent3);
		}

		public bool SFXSpatial_Get()
		{
			return UseSpatialAudio;
		}

		public void SFXSpatial_Set(bool spatial)
		{
			UseSpatialAudio = spatial;
		}

		public int SFXIndex_Get()
		{
			return SelectedSFXIndex;
		}

		public void SFXIndex_Set(int index)
		{
			SelectedSFXIndex = index;
			PlaySelectedSFX(updateRateLimit: false);
		}

		public bool SFXInterrupt_Get()
		{
			return InterruptCurrentSound;
		}

		public void SFXInterrupt_Set(bool interrupt)
		{
			InterruptCurrentSound = interrupt;
		}

		public void Event_PlaySelectedSFX()
		{
			if (UnityEngine.Time.realtimeSinceStartup <= nextPlayTime)
			{
				if (!InterruptCurrentSound)
				{
					return;
				}
				if (sfxAudioSource != null && sfxAudioSource.AudioSource.isPlaying)
				{
					sfxAudioSource.Stop();
				}
			}
			PlaySelectedSFX();
		}

		private void PlaySelectedSFX(bool updateRateLimit = true)
		{
			if (SelectedSFXIndex < 0 || SelectedSFXIndex >= availableSFXClips.Length)
			{
				return;
			}
			AudioClip clip = availableSFXClips[SelectedSFXIndex].Clip;
			if (clip != null)
			{
				if (updateRateLimit)
				{
					nextPlayTime = UnityEngine.Time.realtimeSinceStartup + clip.length * 0.75f;
				}
				if (UseSpatialAudio)
				{
					sfxAudioSource = AudioManager.Play3DSFX(clip, rigidbodyEx.TargetTransform);
				}
				else
				{
					sfxAudioSource = AudioManager.Play2DSFX(clip);
				}
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.version < RoomPersistenceVersion.RADIO_PERSISTENCE)
			{
				return;
			}
			if (deserializeParams.viewData.PersistedSfxData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing radio {0}: No data found!", base.gameObject);
				return;
			}
			PersistedSFXData persistedSfxData = deserializeParams.viewData.PersistedSfxData;
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistedSfxData.TrackId);
			int selectedSFXIndex = -1;
			for (int i = 0; i < availableSFXClips.Length; i++)
			{
				if (availableSFXClips[i].Guid == guid)
				{
					selectedSFXIndex = i;
					break;
				}
			}
			SelectedSFXIndex = selectedSFXIndex;
			UseSpatialAudio = persistedSfxData.UseSpatialAudio;
			InterruptCurrentSound = persistedSfxData.InterruptCurrentSound;
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.PersistedSfxData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Radio {0}: Data already specified.", base.gameObject);
				return;
			}
			SFXTrack sFXTrack = availableSFXClips[SelectedSFXIndex];
			viewData.PersistedSfxData = new PersistedSFXData
			{
				TrackId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(sFXTrack.Guid),
				UseSpatialAudio = UseSpatialAudio,
				InterruptCurrentSound = InterruptCurrentSound
			};
		}
	}
