		public void SetOutput(OutputSlot wire, int signal)
		{
			if (PhotonNetwork.isMasterClient && base.MyCircuitNode != null)
			{
				switch (wire)
				{
				case OutputSlot.R:
				case OutputSlot.B:
					((QueuedMomentarySourceNode)base.MyCircuitNode).SetMomentaryOutput(wire, signal);
					break;
