	public class VariableNodeDisplay : CircuitNodeDisplay
	{
		private Dictionary<OutputSlot, int> cachedSignals = new Dictionary<OutputSlot, int>();

		protected override void RegisterForEvents()
		{
			base.RegisterForEvents();
			base.MyCircuitNode.NodeModifiedEvent += ClearCache;
		}

		protected override void DeregisterFromEvents()
		{
			base.DeregisterFromEvents();
			base.MyCircuitNode.NodeModifiedEvent -= ClearCache;
		}

		private void ClearCache()
		{
			cachedSignals.Clear();
		}

		public override IEnumerable<SettingsEditEvent> GetEditables()
		{
			if (base.MyCircuitNode == null)
			{
				return new SettingsEditEvent[0];
			}
			return ((IEnumerable<OutputMetadata>)base.MyCircuitNode.NodeMetadata.OutputMetadata).Select((Func<OutputMetadata, SettingsEditEvent>)delegate(OutputMetadata om)
			{
				string signalDescription = om.OutputSlot.ToString() + " Signal";
				return new IntSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultIntUIControlPrefab, delegate(CreationObjectSettingIntUIControl instance)
				{
					CircuitNode node = base.MyCircuitNode;
					instance.PropertyGetter = () => GetSignal(om.OutputSlot);
					instance.PropertySetter = delegate(int newValue)
					{
						SetSignal(om.OutputSlot, newValue);
					};
					instance.PropertyDescription.text = signalDescription;
					instance.SetDialogOptions("Set Signal", "Enter " + signalDescription, TMP_InputField.ContentType.IntegerNumber);
					node.NodeModifiedEvent += instance.UpdateControl;
					CircuitNode circuitNode = node;
					circuitNode.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Combine(circuitNode.NodeMetadataChangedEvent, (CircuitNode.NodeMetadataChanged)delegate
					{
						instance.UpdateControl();
					});
					instance.OnDestroyEvent += delegate
					{
						if (node != null)
						{
							node.NodeModifiedEvent -= instance.UpdateControl;
							CircuitNode circuitNode2 = node;
							circuitNode2.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Remove(circuitNode2.NodeMetadataChangedEvent, (CircuitNode.NodeMetadataChanged)delegate
							{
								instance.UpdateControl();
							});
						}
					};
				});
			});
		}

		private void SetSignal(OutputSlot outputSlot, int value)
		{
			if (base.MyCircuitNode != null)
			{
				Dictionary<object, object> dictionary = new Dictionary<object, object>();
				dictionary.Add((int)outputSlot, value);
				Dictionary<object, object> modifyArgs = dictionary;
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterModifyNode(base.MyCircuitNode.NodeId, modifyArgs);
				cachedSignals[outputSlot] = value;
			}
		}

		private int GetSignal(OutputSlot outputSlot)
		{
			int value = 0;
			if (!cachedSignals.TryGetValue(outputSlot, out value) && base.MyCircuitNode != null)
			{
				value = base.MyCircuitNode.GetOutputSignal(outputSlot);
				cachedSignals[outputSlot] = value;
			}
			return value;
		}
	}
