				instance.PropertySetter = SetCircuitNodeTimeUnit;
				if (base.MyCircuitNode != null)
				{
					CircuitNode myCircuitNode = base.MyCircuitNode;
					myCircuitNode.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Combine(myCircuitNode.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
				}
				instance.OnDestroyEvent += delegate
				{
					if (base.MyCircuitNode != null)
					{
						CircuitNode myCircuitNode2 = base.MyCircuitNode;
						myCircuitNode2.NodeMetadataChangedEvent = (CircuitNode.NodeMetadataChanged)Delegate.Remove(myCircuitNode2.NodeMetadataChangedEvent, new CircuitNode.NodeMetadataChanged(instance.NodeMetadataUpdated));
					}
				};
			}, choicesDictionary);
			List<SettingsEditEvent> list = new List<SettingsEditEvent>();
			foreach (SettingsEditEvent item2 in editables)
			{
				list.Add(item2);
			}
			list.Add(item);
			return list;
		}

		protected override int GetCircuitNodeMode()
