public abstract class PrefabTypeSettingEditEvent<PrefabType, PropertyType> : SettingsEditEvent where PrefabType : CreationObjectSettingPropertyUIControl<PropertyType, PrefabType>
{
	public delegate void UIControlInstanceMethod(PrefabType instance);

	public delegate PrefabType GetPrefabForEditEvent(MakerPenPaletteConfigScreen editableUIFlow);

	protected readonly GetPrefabForEditEvent prefabResolveFunc;

	protected UIControlInstanceMethod onInstanceCreated;

	public PrefabTypeSettingEditEvent(GetPrefabForEditEvent prefabResolver, UIControlInstanceMethod onInstanceCreated)
	{
		prefabResolveFunc = prefabResolver;
		this.onInstanceCreated = onInstanceCreated;
	}

	public override BaseCreationObjectSettingPropertyUIControl CreateEditableControl(MakerPenPaletteConfigScreen editableUIFlow, Transform parentTransform)
	{
		PrefabType val = UnityEngine.Object.Instantiate(prefabResolveFunc(editableUIFlow));
		val.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
		val.transform.SetParent(parentTransform, worldPositionStays: false);
		onInstanceCreated(val);
		val.UpdateControl();
		return val;
	}
}
