		protected override void Awake()
		{
			base.Awake();
			_physicallyUnparented = new SynchronizedField<bool>(this, "PhU", defaultValue: false, SetterPermissionMode.AUTHORITY, OnPhysicallyUnparentedChanged);
			Tool.AddCustomPickupCondition(CustomPickupCondition);
			Tool.CustomSelectionForwarding = CustomToolForwarding;
		}

		protected override void OnDestroy()
		{
			if (NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.LocalRemoveNode(this);
			}
			base.OnDestroy();
		}

		private void Start()
		{
			NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.LocalAddNodeToRoot(this, 0);
			OnPhysicallyUnparentedChanged();
		}

		protected virtual bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return !IsParented || PhysicallyUnparented;
		}

		protected virtual Tool CustomToolForwarding(Player selectingPlayer, bool physicalPickupSelection, Collider selectedCollider)
		{
			if (!physicalPickupSelection && ParentIsTool && !ParentConnectable.Tool.IsFrozen && !PhysicallyUnparented)
			{
				return ParentConnectable.Tool;
			}
			return Tool;
		}

		public Tool GetSafeRootTool()
		{
			if (!ParentIsTool)
			{
				return Tool;
			}
			return ParentTool.ConnectableTool.GetSafeRootTool();
		}

		public void AuthorityParentThisConnectableToOther(int slotIndex, IConnectable parentConnectable, int parentSlotIndex)
		{
			if (parentConnectable != null && Tool.hasAuthority)
			{
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.RequestMasterReparentNodes(this, slotIndex, parentConnectable, parentSlotIndex, parentConnectable.Transform.InverseTransformPoint(Transform.position), parentConnectable.Transform.InverseTransformRotation(Transform.rotation));
			}
		}

		public void AuthorityUnparentThisConnectableFromOther()
		{
			if (IsParented && Tool.hasAuthority)
			{
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.RequestMasterReparentToRoot(this);
			}
		}

		public void AuthorityParentOtherConnectableToThis(int slotIndex, IConnectable childConnectable, int childSlotIndex, Vector3? relativePosition = null, Quaternion? relativeRotation = null)
		{
			if (childConnectable != null && Tool.hasAuthority)
			{
				relativePosition = ((!relativePosition.HasValue) ? Tool.RigidbodyEx.TargetTransform.InverseTransformPoint(childConnectable.Transform.position) : relativePosition.Value);
				relativeRotation = ((!relativeRotation.HasValue) ? Tool.RigidbodyEx.TargetTransform.InverseTransformRotation(childConnectable.Transform.rotation) : relativeRotation.Value);
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.RequestMasterReparentNodes(childConnectable, childSlotIndex, this, slotIndex, relativePosition.Value, relativeRotation.Value);
			}
		}

		public void AuthorityUnparentOtherConnectableFromThis(IConnectable childConnectable)
		{
			if (childConnectable != null && Tool.hasAuthority)
			{
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.RequestMasterReparentToRoot(childConnectable);
			}
		}

		private void OnPhysicallyUnparentedChanged()
		{
			if (!ParentIsTool)
			{
				return;
			}
			if (PhysicallyUnparented && Tool.RigidbodyEx.hasParent)
			{
				Tool.RigidbodyEx.parent = null;
				Tool.RigidbodyEx.RemoveKinematic(connectionToParentToken);
				Tool.RigidbodyEx.DisableProxyMovement(connectionToParentToken);
			}
			else if (!Tool.RigidbodyEx.hasParent)
			{
				Tool.RigidbodyEx.AddKinematic(connectionToParentToken);
				Tool.RigidbodyEx.EnableProxyMovement(connectionToParentToken);
				Tool.RigidbodyEx.parent = ParentConnectable.Tool.RigidbodyEx;
				if (base.hasAuthority)
				{
					Tool.RigidbodyEx.SetDiscontinuousLocalPositionAndLocalRotation(RelativePositionToParent, RelativeRotationToParent);
				}
			}
		}

		public void SetConnectionPoint(int index, Vector3 pos)
		{
			if (connectionPoints.Length > index)
			{
				connectionPoints[index].AttachmentPointPosition = pos;
			}
			else
			{
				UnityEngine.Debug.LogError($"SetConnectionPoint: Tried to set ConnectionPoint {index} to {pos} but tool only has {connectionPoints.Length} connection points");
			}
		}

		public virtual Vector3 GetConnectionSlotPosition(int slotIndex)
		{
			if (connectionPoints != null && slotIndex >= 0 && connectionPoints.Length > slotIndex)
			{
				return connectionPoints[slotIndex].AttachmentPointPosition;
			}
			return Transform.position;
		}

		public virtual Color GetConnectionSlotColor(int slotIndex)
		{
			return Color.red;
		}

		public virtual bool CanConnectTo(int slotIndex, IConnectable otherConnectable, int otherConnectableSlotIndex)
		{
			return otherConnectable as ConnectableTool != this && !Tool.IsHeld;
		}

		public virtual bool Equals(IConnectable other)
		{
			return other as ConnectableTool == this;
		}

		public virtual void ParentChanged(int slotIndex, IConnectable newParentConnectable, int newParentSlot, Vector3 newRelativePosition, Quaternion newRelativeRotation)
		{
			Tool.RigidbodyEx.parent = null;
			if (ParentConnectable != null)
			{
				if (ParentConnectable.Tool != null)
				{
					ParentConnectable.Tool.photonView.OwnerChangedEvent -= OnParentToolOwnerChanged;
				}
				ParentConnectable = null;
			}
			Tool.RigidbodyEx.SetKinematic(connectionToParentToken, newParentConnectable != null);
			if (newParentConnectable != null && newParentConnectable.Tool != null)
			{
				Tool.RigidbodyEx.EnableProxyMovement(connectionToParentToken);
				Tool.RigidbodyEx.parent = newParentConnectable.Tool.RigidbodyEx;
				newParentConnectable.Tool.photonView.OwnerChangedEvent += OnParentToolOwnerChanged;
				Tool.RigidbodyEx.SetDiscontinuousLocalPositionAndLocalRotation(newRelativePosition, newRelativeRotation);
				RelativePositionToParent = newRelativePosition;
				RelativeRotationToParent = newRelativeRotation;
			}
			else
			{
				Tool.RigidbodyEx.DisableProxyMovement(connectionToParentToken);
				RelativePositionToParent = Vector3.zero;
				RelativeRotationToParent = Quaternion.identity;
			}
			ParentConnectable = newParentConnectable;
			if (base.hasAuthority)
			{
				PhysicallyUnparented = false;
			}
			if (this.ParentChangedEvent != null)
			{
				this.ParentChangedEvent(this, slotIndex, newParentConnectable, newParentSlot, newRelativePosition, newRelativeRotation);
			}
		}

		public virtual void ChildAdded(int slotIndex, IConnectable newChildConnectable, int newChildSlot, Vector3 relativePosition, Quaternion relativeRotation)
		{
			if (!ChildrenConnectables.Contains(newChildConnectable))
			{
				ChildrenConnectables.Add(newChildConnectable);
			}
			if (this.ChildAddedEvent != null)
			{
				this.ChildAddedEvent(newChildConnectable, newChildSlot, this, slotIndex, relativePosition, relativeRotation);
			}
		}

		public virtual void ChildRemoved(int slotIndex, IConnectable removedChildConnectable, int removedChildSlot)
		{
			ChildrenConnectables.Remove(removedChildConnectable);
			if (this.ChildRemovedEvent != null)
			{
				this.ChildRemovedEvent(removedChildConnectable, removedChildSlot, this, slotIndex);
			}
		}

		public virtual void ConnectionModified(int slotIndex, IConnectable parentConnectable, int parentSlotIndex, Vector3 relativePosition, Quaternion relativeRotation)
		{
			if (this.ConnectionModifiedEvent != null)
			{
				this.ConnectionModifiedEvent(this, slotIndex, parentConnectable, parentSlotIndex, relativePosition, relativeRotation);
			}
		}

		public virtual void RootChanged(IConnectable previousRootConnectable, IConnectable newRootConnectable)
		{
			RootTool = newRootConnectable?.Tool;
			if (this.RootChangedEvent != null)
			{
				this.RootChangedEvent(previousRootConnectable, newRootConnectable);
			}
		}

		private void OnParentToolOwnerChanged(int newOwnerId)
		{
			if (newOwnerId == PhotonNetwork.player.ID && !Tool.hasAuthority)
			{
				Tool.photonView.TransferOwnership(PhotonNetwork.player);
			}
		}

		[RuntimeInitializeOnLoadMethod]
		private static void RegisterRpcSerializationHandlers()
		{
			PhotonRpcSerialization.AddHandler(typeof(IConnectable), typeof(int), SerializeIConnectable, DeserializeIConnectable);
		}

		private static object SerializeIConnectable(object input)
		{
			return ((IConnectable)input).GameObject.GetComponent<PhotonView>().viewID;
		}

		private static object DeserializeIConnectable(object input)
		{
			PhotonView photonView = PhotonView.Find((int)input);
			return (!(photonView != null)) ? null : photonView.GetComponent<IConnectable>();
		}
	}
	public interface IConnectable : IEquatable<IConnectable>
	{
		IConnectable ParentConnectable { get; }

		Transform Transform { get; }

		GameObject GameObject { get; }

		string Name { get; }

		Guid PersistenceId { get; }

		int PhotonId { get; }

		Tool Tool { get; }

		bool ShouldSerializeUnparented { get; }

		Vector3 GetConnectionSlotPosition(int slotIndex);

		Color GetConnectionSlotColor(int slotIndex);

