		void ChildAdded(int slotIndex, IConnectable newChildConnectable, int newChildSlot, Vector3 relativePosition, Quaternion relativeRotation);

		void ChildRemoved(int slotIndex, IConnectable removedChildConnectable, int removedChildSlot);

		void ConnectionModified(int slotIndex, IConnectable parentConnectable, int parentSlot, Vector3 relativePosition, Quaternion relativeRotation);

		void RootChanged(IConnectable previousRootConnectable, IConnectable newRootConnectable);
	}
	public class ConnectionCreationContext : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private CreationContext parentCreationContext;

		private ConnectionPoint selectedStartConnectionPoint;

		private ConnectionPoint cachedStartConnectionPoint;

		public bool HasStartPoint => selectedStartConnectionPoint != null;

		public Color ConnectionColor
		{
			get
			{
				if (!HasStartPoint)
				{
					return Color.white;
				}
				return selectedStartConnectionPoint.ConnectionColor;
			}
		}

		public Vector3 ConnectionStartPosition
		{
			get
			{
				if (!HasStartPoint)
				{
					return Vector3.zero;
				}
				return (!(cachedStartConnectionPoint != null)) ? selectedStartConnectionPoint.transform.position : cachedStartConnectionPoint.AttachmentPointPosition;
			}
		}

		public bool SelectStartPoint(ConnectionPoint connectionPoint)
		{
			if (selectedStartConnectionPoint != null)
			{
				DeselectStartPoint();
			}
			if (connectionPoint == null)
			{
				return false;
			}
			if (!parentCreationContext.AddToSelection(connectionPoint.CreationObject))
			{
				return false;
			}
			selectedStartConnectionPoint = connectionPoint;
			cachedStartConnectionPoint = selectedStartConnectionPoint;
			connectionPoint.ConnectionStart();
			parentCreationContext.OnSelectionChanged += new Action<CreationObject, bool>(OnSelectionChanged);
			return true;
		}

		public void DeselectStartPoint()
		{
			if ((bool)selectedStartConnectionPoint)
			{
				parentCreationContext.OnSelectionChanged -= new Action<CreationObject, bool>(OnSelectionChanged);
				parentCreationContext.RemoveFromSelection(selectedStartConnectionPoint.CreationObject);
				selectedStartConnectionPoint = null;
				cachedStartConnectionPoint = null;
			}
		}

		public bool ConnectToStartPoint(ConnectionPoint endPointConnectable)
		{
			if (!HasStartPoint || endPointConnectable == selectedStartConnectionPoint)
			{
				return false;
			}
			bool flag = parentCreationContext.IsSelected(endPointConnectable.CreationObject);
			if (!flag && !CanBeSelected(endPointConnectable))
			{
				return false;
			}
			if (!flag)
			{
				parentCreationContext.AddToSelection(endPointConnectable.CreationObject);
			}
			endPointConnectable.ConnectionEnd(selectedStartConnectionPoint, endPointConnectable);
			selectedStartConnectionPoint.ConnectionEnd(selectedStartConnectionPoint, endPointConnectable);
			if (!flag)
			{
				parentCreationContext.RemoveFromSelection(endPointConnectable.CreationObject);
			}
			return false;
		}

		public void RenderHoverHighlight(int objCount, ConnectionPoint[] connectionPoints)
		{
			for (int i = 0; i < objCount; i++)
			{
				connectionPoints[i].RenderHoverHighlight();
			}
		}

		public int RaycastPickConnectionPoints(Vector3 origin, Vector3 direction, float maxDistance, ConnectionPoint[] pickedConnectionPoints, out Vector3 closestHit)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			int hitCount = Physics.RaycastNonAlloc(origin, direction, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084289, QueryTriggerInteraction.Collide);
			return FilterCastPickedConnectionPoints(hitCount, iMMEDIATE_RAYCAST_HITS, pickedConnectionPoints, out closestHit);
		}

		public int SpherecastPickConnectionPoints(Vector3 origin, float radius, Vector3 direction, float maxDistance, ConnectionPoint[] pickedConnectionPoints, out Vector3 closestHit)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			int hitCount = Physics.SphereCastNonAlloc(origin, radius, direction, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084289, QueryTriggerInteraction.Collide);
			return FilterCastPickedConnectionPoints(hitCount, iMMEDIATE_RAYCAST_HITS, pickedConnectionPoints, out closestHit);
		}

		private bool CanBeSelected(ConnectionPoint connectionPoint)
		{
			if (connectionPoint == null || connectionPoint.CreationObject == null || connectionPoint.CreationObject.IsLocked || connectionPoint.CreationObject.Tool.IsHeld)
			{
				return false;
			}
			return true;
		}

		private int FilterCastPickedConnectionPoints(int hitCount, RaycastHit[] castPickingHits, ConnectionPoint[] pickedConnectionPoints, out Vector3 closestHit)
		{
			return ((pickedConnectionPoints[0] = GetClosestConnectionPointFromCastPick(hitCount, castPickingHits, out closestHit)) != null) ? 1 : 0;
		}

		private ConnectionPoint GetClosestConnectionPointFromCastPick(int hitCount, RaycastHit[] castPickingHits, out Vector3 closestHit)
		{
			ConnectionPoint result = null;
			Vector3 vector = Vector3.zero;
			float num = float.MaxValue;
			for (int i = 0; i < hitCount; i++)
			{
				ConnectionPoint colliderConnectionPoint = castPickingHits[i].collider.GetColliderConnectionPoint();
				if (!(colliderConnectionPoint == null) && !(castPickingHits[i].distance >= num) && (!(colliderConnectionPoint.CreationObject != null) || colliderConnectionPoint.CreationObject.CanBeRaycasted()))
				{
					result = colliderConnectionPoint;
					num = castPickingHits[i].distance;
					vector = castPickingHits[i].point;
				}
			}
			closestHit = vector;
			return result;
		}

		private void OnSelectionChanged(CreationObject obj, bool isSelected)
		{
			if (!isSelected && selectedStartConnectionPoint != null && obj == selectedStartConnectionPoint.CreationObject)
			{
				DeselectStartPoint();
			}
		}
	}
