			if (NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveStartEvent += RoomPersistenceManager_OnSaveStart;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveSuccessEvent += RoomPersistenceManager_OnSaveSuccess;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveFailureEvent += RoomPersistenceManager_OnSaveFailure;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadStartEvent += RoomPersistenceManager_OnReloadStart;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadSuccessEvent += RoomPersistenceManager_OnReloadSuccess;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadFailureEvent += RoomPersistenceManager_OnReloadFailure;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			base.photonView.OwnerChangedEvent -= OnPhotonOwnershipChange;
			if (base.hasAuthority)
			{
				RemoveAllFromSelection();
			}
			if (NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveStartEvent -= RoomPersistenceManager_OnSaveStart;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveSuccessEvent -= RoomPersistenceManager_OnSaveSuccess;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomSaveFailureEvent -= RoomPersistenceManager_OnSaveFailure;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadStartEvent -= RoomPersistenceManager_OnReloadStart;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadSuccessEvent -= RoomPersistenceManager_OnReloadSuccess;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadFailureEvent -= RoomPersistenceManager_OnReloadFailure;
			}
			AllContexts.Remove(this);
		}

		private void Update()
		{
			if (!ShapeCreationContext.HasSelectedShapeContainer)
			{
				for (int i = 0; i < selectedObjects.Count; i++)
				{
					selectedObjects[i].Tool.RenderSelection();
				}
			}
		}

		private void RoomPersistenceManager_OnSaveStart()
		{
			AuthorityHandleRoomPersistenceStart();
		}

		private void RoomPersistenceManager_OnSaveSuccess()
		{
			AuthorityHandleRoomPersistenceComplete();
		}

		private void RoomPersistenceManager_OnSaveFailure(string error)
		{
			AuthorityHandleRoomPersistenceComplete();
		}

		private void RoomPersistenceManager_OnReloadStart()
		{
			AuthorityHandleRoomPersistenceStart();
		}

		private void RoomPersistenceManager_OnReloadSuccess()
		{
			AuthorityHandleRoomPersistenceComplete();
		}

		private void RoomPersistenceManager_OnReloadFailure(string error)
		{
			AuthorityHandleRoomPersistenceComplete();
		}

		private void AuthorityHandleRoomPersistenceStart()
		{
			if (base.hasAuthority)
			{
				RemoveAllFromSelection();
				shapeCreationContext.AuthorityHandleRoomPersistenceStart();
				WaitingForPersistence = true;
			}
		}

		private void AuthorityHandleRoomPersistenceComplete()
		{
			if (base.hasAuthority)
			{
				WaitingForPersistence = false;
				shapeCreationContext.AuthorityHandleRoomPersistenceComplete();
			}
		}

		public int RaycastPick(Vector3 origin, Vector3 direction, float maxDistance, CreationObject[] pickedObjects, out Vector3 closestHit, out Collider closestCollider)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			int hitCount = Physics.RaycastNonAlloc(origin, direction, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084289, QueryTriggerInteraction.Collide);
			return FilterCastPickedObjects(hitCount, iMMEDIATE_RAYCAST_HITS, pickedObjects, out closestHit, out closestCollider);
		}

		private CreationObject ValidateColliderForCastPick(Collider c, float distanceSq)
		{
			float physicalPickupSphereRadius = Player.LocalPlayer.DominantHand.PhysicalPickupSphereRadius;
			bool physicalPickupSelection = distanceSq < physicalPickupSphereRadius * physicalPickupSphereRadius;
			Tool colliderTool = c.GetColliderTool();
			if (colliderTool == null)
			{
				return null;
			}
			CreationObject creationObject = colliderTool.SelectForwardedCreationObject(Player.LocalPlayer, physicalPickupSelection, c);
			if (creationObject != null && creationObject.CanBeRaycasted())
			{
				if (creationObject.Tool.IsHeldByPlayer || creationObject.Tool.IsEquippedOnPlayer)
				{
					return null;
				}
				return creationObject;
			}
			return null;
		}

		public int SpherecastPick(Vector3 origin, float sphereRadius, Vector3 direction, float maxDistance, CreationObject[] pickedObjects, out Vector3 closestHit, out Collider closestCollider)
		{
			int toolArraySize = 0;
			CreationObject closestSphereCastHit = PhysicsExt.GetClosestSphereCastHit(origin, sphereRadius, direction, maxDistance, out closestHit, out closestCollider, ValidateColliderForCastPick);
			if (closestSphereCastHit != null)
			{
				GetAllObjectsInGroupNonAlloc(closestSphereCastHit, ref toolArraySize, pickedObjects);
			}
			return toolArraySize;
		}

		public bool IsSelected(CreationObject creationObject)
		{
			return selectedObjects.Contains(creationObject);
		}

		public bool SetSelection(int length, CreationObject[] creationObjects)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			bool flag = true;
			if (selectedObjects.Count != length)
			{
				flag = false;
			}
			else
			{
				for (int i = 0; i < length; i++)
				{
					if (selectedObjects[i] != creationObjects[i])
					{
						flag = false;
						break;
					}
				}
			}
			if (flag)
			{
				return true;
			}
			RemoveAllFromSelection();
			return AddToSelection(length, creationObjects);
		}

		public bool AddToSelection(CreationObject creationObject)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			bool flag = AddToSelectionInternal(creationObject);
			if (flag && this.SelectionChangedEvent != null)
			{
				this.SelectionChangedEvent();
			}
			return flag;
		}

		public bool AddToSelection(int objectCount, CreationObject[] objects)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			bool flag = true;
			for (int i = 0; i < objectCount && i < objects.Length; i++)
			{
				if (!AddToSelectionInternal(objects[i]))
				{
					flag = false;
				}
			}
			if (!flag)
			{
				for (int j = 0; j < objectCount && j < objects.Length; j++)
				{
					RemoveFromSelection(objects[j]);
				}
			}
			if (flag && this.SelectionChangedEvent != null)
			{
				this.SelectionChangedEvent();
			}
			return flag;
		}

		public void RemoveFromSelection(CreationObject creationObject)
		{
			if (base.hasAuthority)
			{
				RemoveFromSelectionInternal(creationObject);
				if (this.SelectionChangedEvent != null)
				{
					this.SelectionChangedEvent();
				}
			}
		}

		public void RemoveAllFromSelection()
		{
			if (base.hasAuthority)
			{
				CreationObject[] array = selectedObjects.ToArray();
				for (int i = 0; i < array.Length; i++)
				{
					RemoveFromSelectionInternal(array[i]);
				}
				if (this.SelectionChangedEvent != null)
				{
					this.SelectionChangedEvent();
				}
			}
		}

		public IEnumerable<ToolCollider> GetSelectionToolColliders()
		{
			foreach (CreationObject obj in CurrentSelection)
			{
				foreach (ToolCollider collider in obj.Tool.Colliders)
				{
					yield return collider;
				}
			}
		}

