			RenderHoverHighlight(objCount, creationObjects, OutlineEffectRenderer.OutlineType.Hover);
		}

		public void RenderHoverHighlight(int objCount, IEnumerable<CreationObject> creationObjects, OutlineEffectRenderer.OutlineType outlineType)
		{
			int num = 0;
			foreach (CreationObject creationObject in creationObjects)
			{
				if (num >= objCount)
				{
					break;
				}
				creationObject.Tool.RenderOutline(outlineType);
				num++;
			}
		}

		public void SetTransformationCoordinateSpace(CoordinateSpace coordinateSpace)
		{
			if (base.hasAuthority)
			{
				TransformationCoordinateSpace = coordinateSpace;
			}
		}

		public bool TranslateSelection(Vector3 linearDisplacement)
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (!canMoveSelection)
			{
				NotifyOfObjectFrozen();
				return false;
			}
			if (TransformationCoordinateSpace == CoordinateSpace.OBJECT)
			{
				linearDisplacement = SelectionTransform.TransformVector(linearDisplacement);
			}
			for (int i = 0; i < selectedObjects.Count; i++)
			{
				selectedObjects[i].transform.position += linearDisplacement;
			}
			_SelectionBounds.center += linearDisplacement;
			return true;
		}

		public bool RotateSelection(Quaternion angularDisplacement, Vector3? pivotPoint)
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (!canMoveSelection)
			{
				NotifyOfObjectFrozen();
				return false;
			}
			if (TransformationCoordinateSpace == CoordinateSpace.OBJECT)
			{
				angularDisplacement = SelectionTransform.TransformRotation(angularDisplacement);
			}
			foreach (CreationObject item in CurrentSelection)
			{
				if (pivotPoint.HasValue)
				{
					item.transform.position = pivotPoint.Value + angularDisplacement * (item.transform.position - pivotPoint.Value);
				}
				item.transform.rotation = angularDisplacement * item.transform.rotation;
			}
			selectionBoundsDirty = true;
			return true;
		}

		public bool ScaleSelection(float deltaScale, Vector3? pivotPoint = null)
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (!canMoveSelection)
			{
				NotifyOfObjectFrozen();
				return false;
			}
			if (!HasSelection)
			{
				return false;
			}
			float localUniformScale = selectedObjects[0].transform.GetLocalUniformScale();
			float num = (localUniformScale + deltaScale) / localUniformScale;
			float magnitude = SelectionBounds.extents.magnitude;
			float num2 = Mathf.Clamp(magnitude * num, 0.01f, 1000f);
			num = num2 / magnitude;
			foreach (CreationObject selectedObject in selectedObjects)
			{
				float localUniformScale2 = selectedObject.transform.GetLocalUniformScale();
				selectedObject.transform.SetLocalUniformScale(localUniformScale2 * num);
				if (pivotPoint.HasValue)
				{
					Vector3 vector = selectedObject.transform.position - pivotPoint.Value;
					selectedObject.transform.position = pivotPoint.Value + vector * num;
				}
			}
			selectionBoundsDirty = true;
			return true;
		}

		public void SetObjectTransforms(Guid[] objectGuids, Vector3[] positions, Quaternion[] rotations, float[] scales)
		{
			if (positions.Length != objectGuids.Length)
			{
				UnityEngine.Debug.LogError(string.Format("CreationContext::SetObjectTransforms {0} position entries for {1} objects when setting transforms for Objects ({2})", positions.Length, objectGuids.Length, string.Join(",", objectGuids)));
				return;
			}
			if (rotations != null && rotations.Length != objectGuids.Length)
			{
				UnityEngine.Debug.LogError(string.Format("CreationContext::SetObjectTransforms {0} rotation entries for {1} objects when setting transforms for Objects ({2})", rotations.Length, objectGuids.Length, string.Join(",", objectGuids)));
				return;
			}
			if (scales != null && scales.Length != objectGuids.Length)
			{
				UnityEngine.Debug.LogError(string.Format("CreationContext::SetObjectTransforms {0} scale entries for {1} objects when setting transforms for Objects ({2})", scales.Length, objectGuids.Length, string.Join(",", objectGuids)));
				return;
			}
			Tool tool = null;
			for (int i = 0; i < objectGuids.Length; i++)
			{
				if (CreationHelper.TryGetToolFromId(objectGuids[i], out tool))
				{
					tool.transform.position = positions[i];
					if (rotations != null)
					{
						tool.transform.rotation = rotations[i];
					}
					if (scales != null)
					{
						tool.transform.localScale = Vector3.one * scales[i];
					}
					tool.Snap();
				}
			}
		}

		public bool SetSelectionFrozen(bool freeze)
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (selectedObjects.Count == 0)
			{
				NotifyOfError(CreationResult.Failure_Generic, "Nothing selected", null, base.owner);
				return false;
			}
			foreach (CreationObject selectedObject in selectedObjects)
			{
				selectedObject.IsFrozen = freeze;
			}
			return true;
		}

		public void SetObjectsFrozen(Guid[] objectGuids, bool[] isFrozen)
		{
			CreationObject creationObject = null;
			for (int i = 0; i < objectGuids.Length; i++)
			{
				if (CreationHelper.TryGetCreationObjectFromId(objectGuids[i], out creationObject))
				{
					creationObject.IsFrozen = isFrozen[i];
				}
			}
		}

		public bool HasAnyUnfrozenObject()
		{
			for (int i = 0; i < selectedObjects.Count; i++)
			{
				if (!selectedObjects[i].IsFrozen)
				{
					return true;
				}
			}
			return false;
		}

		public IPromise<CreationManager.SpawnTemplateResult> CloneSelection()
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return new CompletedPromise<CreationManager.SpawnTemplateResult>(new CreationManager.SpawnTemplateResult
				{
					result = CreationResult.Failure_NoAuthority,
					errorCulprit = PhotonNetwork.player,
					spawnedTools = null
				});
			}
			if (!canCloneSelection)
			{
				NotifyOfObjectFrozen();
				return new CompletedPromise<CreationManager.SpawnTemplateResult>(new CreationManager.SpawnTemplateResult
				{
					result = CreationResult.Failure_ToolFrozen,
					errorCulprit = PhotonNetwork.player,
					spawnedTools = null
				});
			}
			string selectionName = GetUserFriendlySelectionName(selectedObjects);
			return NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestCloneObjects(selectedObjects).Then(delegate(CreationManager.SpawnTemplateResult r)
			{
				CloneResultCallback(selectionName, r.result, r.errorCulprit);
			}).Error(delegate
			{
				CloneResultCallback(selectionName, CreationResult.Failure_Generic);
			});
		}

		public IEnumerator<ISchedule> WaitForValidBoundsOnCloneResult(CreationManager.SpawnTemplateResult result, Action callback)
		{
			if (result.spawnedTools != null && result.spawnedTools.Count > 0)
			{
				int frameCount = 0;
				while (result.spawnedTools.Any((Tool t) => t.GetColliderBounds().extents == Vector3.zero))
				{
					frameCount++;
					if (frameCount > 5)
					{
						Tool arg = result.spawnedTools.FirstOrDefault((Tool t) => t.GetColliderBounds().extents == Vector3.zero);
						UnityEngine.Debug.LogError($"Cloned object {arg} never generated non-zero bounds.");
						break;
					}
					yield return Schedule.NextFrame;
				}
			}
			callback?.Invoke();
		}

		public bool DeleteSelection()
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (!canDeleteSelection)
			{
				NotifyOfObjectFrozen();
				return false;
			}
			CreationObject[] array = selectedObjects.ToArray();
			RemoveAllFromSelection();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].RequestMasterDespawn();
			}
			return true;
		}

		public bool TryMergeShapeSelection(ShapeContainer destContainer, IReadOnlyList<ShapeContainer> containersToMerge)
		{
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			if (!CurrentSelection.Contains(destContainer.CreationObject))
			{
				UnityEngine.Debug.LogError($"Cannot merge unselected shape container {destContainer}");
				return false;
			}
			if (!destContainer.CanBeMerged)
			{
				UnityEngine.Debug.LogError($"Cannot merge shape container {destContainer}");
				return false;
			}
			int num = destContainer.SandboxResourceCost;
			foreach (ShapeContainer item in containersToMerge)
			{
				if (!item.CanBeMerged)
				{
					UnityEngine.Debug.LogError($"Cannot merge shape container {item}");
					return false;
				}
				if (!CurrentSelection.Contains(item.CreationObject))
				{
					UnityEngine.Debug.LogError($"Cannot merge unselected shape container {item}");
					return false;
				}
				if (destContainer == item)
				{
					UnityEngine.Debug.LogError($"Cannot merge shape container {item} into itself!");
					return false;
				}
				num += item.GetShapesCostInPhysicsMode(destContainer.CurrentPhysicsMode);
				if (num > destContainer.MaxResources)
				{
					UnityEngine.Debug.LogError($"Cannot afford to merge all shapes into container {destContainer}");
					return false;
				}
			}
			RemoveAllFromSelection();
			foreach (ShapeContainer item2 in containersToMerge)
			{
				destContainer.Tool.Tags.CopyTags(item2.Tool.Tags);
				destContainer.RequestMasterMergeShapeContainer(item2);
			}
			return AddToSelection(destContainer.CreationObject);
		}

		public bool ExistsUnselectedInventionObjects(CreationObject creationObject)
		{
			if (!creationObject.InventionPiece.IsTrackingInvention)
			{
				return false;
			}
			List<CreationObject> allObjectsInInvention = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.GetAllObjectsInInvention(creationObject.InventionPiece.InstanceId);
			foreach (CreationObject item in allObjectsInInvention)
			{
				if (!IsSelected(item))
				{
					return true;
				}
			}
			return false;
		}

		public CreationResult TrySelectRestOfInvention(CreationObject creationObject)
		{
			if (creationObject == null || !creationObject.InventionPiece.IsTrackingInvention)
			{
				return CreationResult.Failure_InvalidAction;
			}
			List<CreationObject> allObjectsInInvention = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.GetAllObjectsInInvention(creationObject.InventionPiece.InstanceId);
			foreach (CreationObject item in allObjectsInInvention)
			{
				if (!IsSelected(item))
				{
					CreationResult creationResult = CanObjectBeSelected(item);
					if (creationResult != CreationResult.Success)
					{
						return creationResult;
					}
				}
			}
			foreach (CreationObject item2 in allObjectsInInvention)
			{
				if (!IsSelected(item2))
				{
					AddToSelection(item2);
				}
			}
			return CreationResult.Success;
		}

		public bool RecolorSelection(ShapeColor newColor, out UndoEntry undoEntry)
		{
			undoEntry = null;
			if (!canRepaintSelection)
			{
				NotifyOfObjectFrozen();
				return false;
			}
			return ModifySelectionProperty("Color", "recolor", out undoEntry, newColor);
		}

		public bool ModifySelectionProperty(string propertyKey, string undoLabel, out UndoEntry undoEntry, params object[] parameters)
		{
			undoEntry = null;
			if (!base.hasAuthority)
			{
				NotifyOfAuthorityError();
				return false;
			}
			List<UndoEntry> list = new List<UndoEntry>(selectedObjects.Count);
			for (int i = 0; i < selectedObjects.Count; i++)
			{
				UndoEntry undoEntry2 = selectedObjects[i].ModifyProperty(this, propertyKey, parameters);
				if (undoEntry2 != null)
				{
					list.Add(undoEntry2);
				}
			}
			if (list.Count == 1)
			{
				undoEntry = list[0];
			}
			else if (list.Count > 0)
			{
				undoEntry = new BulkModifyObjectsUndoEntry(undoLabel, selectedObjects, list, this);
			}
			return true;
		}

		public IPromise<SpawnableTemplateData> SerializeSelection()
		{
			Promise<SpawnableTemplateData> promise = new Promise<SpawnableTemplateData>();
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SerializeSpawnableTemplate(CurrentSelection).Then(delegate(CreationManager.SerializeTemplateResult result)
			{
				promise.Complete(result.spawnableTemplateData);
			}).Error(delegate(string e)
			{
				promise.Error(e);
			});
			return promise;
		}

		private int FilterCastPickedObjects(int hitCount, RaycastHit[] castPickingHits, CreationObject[] pickedObjects, out Vector3 closestHit, out Collider closestCollider)
		{
			int toolArraySize = 0;
			CreationObject closestObjectFromCastPick = GetClosestObjectFromCastPick(hitCount, castPickingHits, out closestHit, out closestCollider);
			if (closestObjectFromCastPick != null)
			{
				GetAllObjectsInGroupNonAlloc(closestObjectFromCastPick, ref toolArraySize, pickedObjects);
			}
			return toolArraySize;
		}

		private CreationObject GetClosestObjectFromCastPick(int hitCount, RaycastHit[] castPickingHits, out Vector3 closestHit, out Collider closestCollider)
		{
			Player localPlayer = Player.LocalPlayer;
			CreationObject result = null;
			Collider collider = null;
			Vector3 vector = Vector3.zero;
			float num = float.MaxValue;
			for (int i = 0; i < hitCount; i++)
			{
				Tool colliderTool = castPickingHits[i].collider.GetColliderTool();
				if (!(colliderTool == null) && !(castPickingHits[i].distance >= num))
				{
					CreationObject creationObject = colliderTool.SelectForwardedCreationObject(localPlayer, physicalPickupSelection: false, castPickingHits[i].collider);
					if (!(creationObject == null) && creationObject.CanBeRaycasted() && !creationObject.Tool.IsHeldByPlayer && !creationObject.Tool.IsEquippedOnPlayer)
					{
						result = creationObject;
						num = castPickingHits[i].distance;
						vector = castPickingHits[i].point;
						collider = castPickingHits[i].collider;
					}
				}
			}
			closestHit = vector;
			closestCollider = collider;
			return result;
		}

		private bool AddToSelectionInternal(CreationObject creationObject)
		{
			if (WaitingForPersistence)
			{
				return false;
			}
			CreationResult creationResult = CanObjectBeSelected(creationObject);
			if (creationResult != CreationResult.Success)
			{
				PhotonPlayer culprit = base.owner;
				switch (creationResult)
				{
				case CreationResult.Failure_LockedByOther:
					culprit = PhotonPlayer.Find(creationObject.LockedByPhotonPlayer);
					break;
				case CreationResult.Failure_HeldByOther:
					culprit = PhotonPlayer.Find(creationObject.Tool.HolderPlayer.PhotonPlayer.ID);
					break;
				}
				NotifyOfError(creationResult, "Error", null, culprit);
				return false;
			}
			creationObject.LockedByPhotonPlayer = PhotonNetwork.player.ID;
			selectedObjects.Add(creationObject);
			creationObject.LockedStatusChangedEvent += OnObjectLockStatusChanged;
			creationObject.photonView.OwnerChangedEvent += OnPhotonOwnershipChangedForSelection;
			creationObject.OnFrozenChanged += OnObjectFreezeStatusChanged;
			UpdateAvailableOperations();
			if (OnSelectionChanged != null)
			{
				bool u = true;
				OnSelectionChanged.Invoke(creationObject, u);
			}
			return true;
		}

		private void RemoveFromSelectionInternal(CreationObject creationObject)
		{
			if (IsSelected(creationObject))
			{
				creationObject.OnFrozenChanged -= OnObjectFreezeStatusChanged;
				creationObject.photonView.OwnerChangedEvent -= OnPhotonOwnershipChangedForSelection;
				creationObject.LockedStatusChangedEvent -= OnObjectLockStatusChanged;
				selectedObjects.Remove(creationObject);
				creationObject.LockedByPhotonPlayer = PhotonPlayer.Invalid;
				UpdateAvailableOperations();
				if (OnSelectionChanged != null)
				{
					bool u = false;
					OnSelectionChanged.Invoke(creationObject, u);
				}
			}
		}

		private CreationResult CanObjectBeSelected(CreationObject creationObject)
		{
			if (creationObject == null)
			{
				return CreationResult.Failure_ObjectDoesNotExist;
			}
			return creationObject.CanBeSelected();
		}

		private void UpdateAvailableOperations()
		{
			canMoveSelection = true;
			canRepaintSelection = true;
			canDeleteSelection = true;
			canCloneSelection = true;
			for (int i = 0; i < selectedObjects.Count; i++)
			{
				if (selectedObjects[i].Tool.IsFrozen)
				{
					canMoveSelection = false;
					canRepaintSelection = false;
					canDeleteSelection = false;
					canCloneSelection = false;
				}
			}
			selectionBoundsDirty = true;
		}

		private void UpdateSelectionBounds()
		{
			if (!selectionBoundsDirty)
			{
				return;
			}
			if (HasSelection)
			{
				_SelectionBounds = selectedObjects[0].GetWorldBounds();
				for (int i = 1; i < selectedObjects.Count; i++)
				{
					_SelectionBounds.Encapsulate(selectedObjects[i].GetWorldBounds());
				}
			}
			else
			{
				_SelectionBounds.center = Vector3.zero;
				_SelectionBounds.size = Vector3.zero;
			}
			selectionBoundsDirty = false;
		}

		public void DisableDynamicCollisionForSelectionUntilDeSelected()
		{
			foreach (CreationObject selectedObject in selectedObjects)
			{
				selectedObject.DynamicCollisionEnabled = false;
			}
		}

		private void GetAllObjectsInGroupNonAlloc(CreationObject objectInGroup, ref int toolArraySize, CreationObject[] objectArrayNonAlloc)
		{
			TryAddObjectToPreAllocatedArray(objectInGroup, ref toolArraySize, objectArrayNonAlloc);
		}

		private bool TryAddObjectToPreAllocatedArray(CreationObject creationObject, ref int objectArraySize, CreationObject[] objectArrayNonAlloc)
		{
			if (objectArraySize < objectArrayNonAlloc.Length)
			{
				objectArrayNonAlloc[objectArraySize++] = creationObject;
				return true;
			}
			return false;
		}

		private void CloneResultCallback(string selectionName, CreationResult result, params object[] parameters)
		{
			if (result == CreationResult.Success)
			{
				CreationManager.MarkResourceCostsDirty();
				return;
			}
			string errorMessage = $"Unable to clone {selectionName}";
			NotifyOfError(result, errorMessage, null, (PhotonPlayer)parameters[0]);
		}

		public void NotifyOfError(CreationResult result, string errorMessage, CreationObject creationObject, PhotonPlayer culprit)
		{
			if (this.OnCreationContextError != null)
			{
				this.OnCreationContextError(result, errorMessage, creationObject, culprit);
			}
		}

		private string GetUserFriendlySelectionName(IList<CreationObject> selection)
		{
			if (selection == null || selection.Count == 0)
			{
				return "UNKNOWN";
			}
			if (selection.Count > 1)
			{
				return "Group";
			}
			return selection[0].FriendlyName;
		}

		private void OnPhotonOwnershipChange(int newOwnerPlayerId)
		{
			if (base.hasAuthority)
			{
				RemoveAllFromSelection();
			}
		}

		private void OnPhotonOwnershipChangedForSelection(int newOwnerPlayerId)
		{
			for (int num = selectedObjects.Count - 1; num >= 0; num--)
			{
				if (!selectedObjects[num].hasOwnership)
				{
					UnityEngine.Debug.LogFormat("Object {0} had authority removed while selected. Removing it from selection.", selectedObjects[num].gameObject.name);
					RemoveFromSelection(selectedObjects[num]);
				}
			}
		}

		private void OnObjectLockStatusChanged(CreationObject obj)
		{
			if (IsSelected(obj) && !obj.IsLocked)
			{
				RemoveFromSelection(obj);
			}
		}

		private void OnObjectFreezeStatusChanged(bool isFrozen)
		{
			UpdateAvailableOperations();
		}

		private void NotifyOfAuthorityError()
		{
			NotifyOfError(CreationResult.Failure_NoAuthority, null, null, base.owner);
		}

		private void NotifyOfObjectFrozen()
		{
			CreationObject creationObject = null;
			for (int i = 0; i < selectedObjects.Count; i++)
			{
				if (selectedObjects[i].Tool.IsFrozen)
				{
					creationObject = selectedObjects[i];
					break;
				}
			}
			string arg = "Object";
			if (creationObject != null && !string.IsNullOrEmpty(creationObject.UserFriendlyName))
			{
				arg = creationObject.UserFriendlyName;
			}
			NotifyOfError(CreationResult.Failure_ToolFrozen, $"{arg} is frozen", creationObject, null);
		}

		public static CreationContext Instantiate()
		{
			GameObject gameObject = PhotonNetwork.Instantiate(PREFAB_NAME, Vector3.zero, Quaternion.identity, 1f, 0, null);
			return (!(gameObject != null)) ? null : gameObject.GetComponent<CreationContext>();
		}
	}
}
namespace RecRoom.Core.Creation.Shapes
{
	public class CreationShapeContainer : ShapeContainer
	{
		private static readonly string STATIC_NAME = "Creation Shape Container";

		private static readonly int STATIC_MAX_RESOURCES = 2500;

		private PhysicsMode costingPhysicsMode = PhysicsMode.Decoration;

		public override string DebugName => STATIC_NAME;

		public override string FriendlyName => STATIC_NAME;

		public override int MaxResources => STATIC_MAX_RESOURCES;

		public override bool DestroyIfEmpty => false;

		public override bool CanBeEditedAfterCreation => true;

		public override bool CanBeMerged => false;

		public override bool CanBeSplit => false;

		public override PhysicsMode DefaultPhysicsMode => PhysicsMode.Decoration;

		protected override RepositionWhenAddingFirstShape ShouldRepositionWhenAddingFirstShape
		{
			[CompilerGenerated]
			get
			{
				return RepositionWhenAddingFirstShape.Always;
			}
		}

		public PhysicsMode CostingPhysicsMode
		{
			get
			{
				return costingPhysicsMode;
			}
			set
			{
				if (value != costingPhysicsMode)
				{
					costingPhysicsMode = value;
					MarkResourceCostsDirty();
				}
			}
		}

		protected override void Start()
		{
			base.Start();
			base.CreationObject.ShouldDestroyWhenDestroyingAll = false;
		}

		protected override int CalculateResourceCost(PhysicsMode? physicsModeOverride = null)
		{
			if (shapeArray.ShapeCount == 0)
			{
				return 0;
			}
			return ShapeContainer.GetShapesCost(shapeArray.AllShapes, CostingPhysicsMode);
		}
	}
}
public interface ISelectionBounds
{
	Bounds SelectionBounds { get; }
}
public interface ISelectionColliderInterface
{
	IEnumerable<ToolCollider> GetSelectionToolColliders();
}
public interface ISelectionContext<T> : ISelectionBounds, ISelectionColliderInterface
{
	bool HasSelection { get; }

	int SelectionCount { get; }

	IEnumerable<T> CurrentSelection { get; }

	Transform SelectionTransform { get; }

	float SelectionScale { get; }

	event Action SelectionChangedEvent;

	int RaycastPick(Vector3 origin, Vector3 direction, float maxDistance, T[] pickedResults, out Vector3 closestHit, out Collider closestCollider);

	int SpherecastPick(Vector3 origin, float sphereRadius, Vector3 direction, float maxDistance, T[] pickedResults, out Vector3 closestHit, out Collider closestCollider);

	bool IsSelected(T obj);

	bool AddToSelection(T obj);

	bool AddToSelection(int objCount, T[] objs);

	void RemoveFromSelection(T obj);

	void RemoveAllFromSelection();

	void RenderHoverHighlight(int count, IEnumerable<T> collection);

	void RenderHoverHighlight(int count, IEnumerable<T> collection, OutlineEffectRenderer.OutlineType outlineType);

	bool RotateSelection(Quaternion angularDisplacement, Vector3? pivotPoint = null);

	bool TranslateSelection(Vector3 linearDisplacement);

	bool ScaleSelection(float deltaScale, Vector3? pivotPoint = null);
}
namespace RecRoom.Core.Creation
{
	public class ShapeCreationContext : Photon.MonoBehaviour, ISelectionContext<Guid>, ISelectionBounds, ISelectionColliderInterface
	{
		public struct ShapeCreationResult
		{
			public CreationResult result;

			public Guid newShapeGuid;

			public ShapeCreationResult(CreationResult result, Guid newShapeGuid)
			{
				this.result = result;
				this.newShapeGuid = newShapeGuid;
			}
		}

		private class ShapeContainerRequest
		{
			public Promise<ShapeContainer> promise;

			public float requestTime;
		}

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private CreationContext parentCreationContext;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private CreationShapeContainer creationShapeContainer;

		private int cachedOwnerPlayerId;

		private SynchronizedComponent<ShapeContainer> _selectedShapeContainer;

		private ShapeContainer _prevSelectedShapeContainer;

		private SynchronizedComponent<StandaloneShapeContainer> _cachedEmptyStandaloneShapeContainer;

		private SynchronizedComponent<TriggerVolumeShapeContainer> _cachedEmptyTriggerVolumeShapeContainer;

		public bool ShouldRenderWorldFadeMask = true;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_SelectionChangedEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_SelectedShapeContainerChangedEvent;

		private const float NEW_SHAPE_CONTAINER_REQUEST_TIMEOUT_DURATION = 2f;

		private Dictionary<SpawnableToolType, ShapeContainerRequest> pendingCachedContainerRequests = new Dictionary<SpawnableToolType, ShapeContainerRequest>(2);

		public ShapeContainer SelectedShapeContainer
		{
			get
			{
				return _selectedShapeContainer.Get();
			}
			private set
			{
				_selectedShapeContainer.Set(value);
			}
		}

		public StandaloneShapeContainer CachedEmptyStandaloneShapeContainer
		{
			get
			{
				return _cachedEmptyStandaloneShapeContainer.Get();
			}
			private set
			{
				_cachedEmptyStandaloneShapeContainer.Set(value);
			}
		}

		public TriggerVolumeShapeContainer CachedEmptyTriggerVolumeShapeContainer
		{
			get
			{
				return _cachedEmptyTriggerVolumeShapeContainer.Get();
			}
			private set
			{
				_cachedEmptyTriggerVolumeShapeContainer.Set(value);
			}
		}

		public bool IsEmpty => (creationShapeContainer == null || creationShapeContainer.IsEmpty) && (SelectedShapeContainer == null || SelectedShapeContainer.IsEmpty);

		public bool HasSelectedShapeContainer => SelectedShapeContainer != null;

		public bool HasSelection => HasSelectedShapeContainer && SelectionCount > 0;

		public int SelectionCount => SelectedShapes.Count;

		private IReadOnlyList<Guid> SelectedShapes => creationShapeContainer.AllShapes;

		public IEnumerable<Guid> CurrentSelection => SelectedShapes;

		public Bounds SelectionBounds
		{
			get
			{
				if (HasSelection)
				{
					return creationShapeContainer.Tool.GetColliderBounds();
				}
				return default(Bounds);
			}
		}

		public Transform SelectionTransform
		{
			get
			{
				if (HasSelection)
				{
					return creationShapeContainer.transform;
				}
				return null;
			}
		}

		public float SelectionScale
		{
			get
			{
				if (HasSelection)
				{
					return creationShapeContainer.transform.GetLossyUniformScale();
				}
				return 1f;
			}
		}

		public bool IsOverCostLimit
		{
			get
			{
				if (SelectedShapeContainer == null)
				{
					return false;
				}
				return CombinedSandboxResourceCost >= SelectedContainerMaxResources;
			}
		}

		public int CombinedSandboxResourceCost
		{
			get
			{
				int? num = SelectedShapeContainer?.SandboxResourceCost;
				return (num.HasValue ? num.Value : 0) + creationShapeContainer.SandboxResourceCost;
			}
		}

		public int SelectedContainerMaxResources
		{
			get
			{
				int? num = SelectedShapeContainer?.MaxResources;
				return num.HasValue ? num.Value : 0;
			}
		}

		public event Action SelectionChangedEvent
		{
			add
			{
				Action action = this.m_SelectionChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SelectionChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_SelectionChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SelectionChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public event Action SelectedShapeContainerChangedEvent
		{
			add
			{
				Action action = this.m_SelectedShapeContainerChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SelectedShapeContainerChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_SelectedShapeContainerChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SelectedShapeContainerChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_selectedShapeContainer = new SynchronizedComponent<ShapeContainer>(this, "SCC_SSC", SetterPermissionMode.MASTER_OR_AUTHORITY, OnSelectedShapeContainerChanged);
			_cachedEmptyStandaloneShapeContainer = new SynchronizedComponent<StandaloneShapeContainer>(this, "SCC_CESC", SetterPermissionMode.MASTER_OR_AUTHORITY);
			_cachedEmptyTriggerVolumeShapeContainer = new SynchronizedComponent<TriggerVolumeShapeContainer>(this, "SCC_CTSC", SetterPermissionMode.MASTER_OR_AUTHORITY);
			PhotonNetwork.OnPhotonPlayerDisconnected.Add(OnPhotonPlayerDisconnected);
		}

		private void Start()
		{
			AuthorityCacheShapeContainers();
			cachedOwnerPlayerId = base.photonView.OwnerActorNr;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnPhotonPlayerDisconnected.Remove(OnPhotonPlayerDisconnected);
		}

		private void Update()
		{
			if (base.hasAuthority)
			{
				if (HasSelection)
				{
					creationShapeContainer.Tool.RenderSelection();
				}
				if (ShouldRenderWorldFadeMask)
				{
					RenderWorldFadeMask();
				}
			}
		}

		public void LockOwnershipToLocalPlayer()
		{
			creationShapeContainer.CreationObject.LockedByPhotonPlayer = PhotonNetwork.player.ID;
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer player)
		{
			if (player.ID == cachedOwnerPlayerId && PhotonNetwork.isMasterClient)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
				AuthorityTearDownState();
			}
		}

		private void AuthorityTearDownState()
		{
			if (base.hasAuthority)
			{
				SelectedShapeContainer = null;
				if (CachedEmptyStandaloneShapeContainer != null && CachedEmptyStandaloneShapeContainer.CreationObject != null)
				{
					CachedEmptyStandaloneShapeContainer.CreationObject.RequestMasterDespawn();
					CachedEmptyStandaloneShapeContainer = null;
				}
				if (CachedEmptyTriggerVolumeShapeContainer != null && CachedEmptyTriggerVolumeShapeContainer.CreationObject != null)
				{
					CachedEmptyTriggerVolumeShapeContainer.CreationObject.RequestMasterDespawn();
					CachedEmptyTriggerVolumeShapeContainer = null;
				}
			}
		}

		public IPromise<ShapeContainer> CreateAndSelectShapeContainer(SpawnableToolType shapeContainerType)
		{
			if (!base.hasAuthority)
			{
				return new ErroredPromise<ShapeContainer>("Unable to create shape container without authority.");
			}
			return AuthorityGetCachedShapeContainer(shapeContainerType).Then(delegate(ShapeContainer container)
			{
				container.Tool.IsEnabled = true;
				if (TrySelectShapeContainer(container))
				{
					AuthorityCacheShapeContainer(shapeContainerType);
				}
				else
				{
					UnityEngine.Debug.LogError($"Failed to select cached shape container {container} somehow!");
				}
			});
		}

		public bool TrySelectShapeContainer(ShapeContainer shapeContainer)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (!CanSelectShapeContainer(shapeContainer))
			{
				return false;
			}
			SelectedShapeContainer = shapeContainer;
			return true;
		}

		public void DeselectShapeContainer()
		{
			if (base.hasAuthority)
			{
				SelectedShapeContainer = null;
			}
		}

		private void OnSelectedShapeContainerChanged()
		{
			if (base.hasAuthority)
			{
				if (_prevSelectedShapeContainer != null)
				{
					parentCreationContext.OnSelectionChanged -= new Action<CreationObject, bool>(OnParentSelectionChanged);
					parentCreationContext.RemoveFromSelection(_prevSelectedShapeContainer.CreationObject);
					OnShapeContainerDeselected(_prevSelectedShapeContainer);
				}
				if (SelectedShapeContainer != null)
				{
					if (!parentCreationContext.AddToSelection(SelectedShapeContainer.CreationObject))
					{
						UnityEngine.Debug.LogError("Failed to select shapeContainer");
						SelectedShapeContainer = null;
						return;
					}
					parentCreationContext.OnSelectionChanged += new Action<CreationObject, bool>(OnParentSelectionChanged);
					creationShapeContainer.CostingPhysicsMode = SelectedShapeContainer.CurrentPhysicsMode;
					OnShapeContainerSelected(SelectedShapeContainer);
				}
			}
			_prevSelectedShapeContainer = SelectedShapeContainer;
			if (this.SelectedShapeContainerChangedEvent != null)
			{
				this.SelectedShapeContainerChangedEvent();
			}
		}

		public int RaycastPick(Vector3 origin, Vector3 direction, float maxDistance, Guid[] pickedShapeIds, out Vector3 closestHit, out Collider closestCollider)
		{
			closestHit = Vector3.zero;
			closestCollider = null;
			if (SelectedShapeContainer == null)
			{
				return 0;
			}
			return SelectedShapeContainer.RaycastPickShapes(origin, direction, maxDistance, pickedShapeIds, out closestHit, creationShapeContainer);
		}

		public int SpherecastPick(Vector3 origin, float radius, Vector3 direction, float maxDistance, Guid[] pickedShapeIds, out Vector3 closestHit, out Collider closestCollider)
		{
			closestHit = Vector3.zero;
			closestCollider = null;
			if (SelectedShapeContainer == null)
			{
				return 0;
			}
			return SelectedShapeContainer.SpherecastPickShapes(origin, radius, direction, maxDistance, pickedShapeIds, out closestHit, out closestCollider, creationShapeContainer);
		}

		public bool TryAddAndSelectShapesInSelectedShapeContainer(ShapeDataCollection shapeData, int shapeColliderCosts)
		{
			if (!base.hasAuthority || SelectedShapeContainer == null)
			{
				return false;
			}
			if (!CanAffordToAddShapes(shapeColliderCosts))
			{
				return false;
			}
			RemoveAllFromSelection();
			Guid[] array = shapeData.Shapes.Select((ShapeData s) => RecRoom.Protobuf.ByteStringExtensions.ToGuid(s.Id)).ToArray();
			if (SelectedShapeContainer.ContainsAnyShape(array))
			{
				return false;
			}
			SelectedShapeContainer.LocalAddShapesFromData(shapeData);
			AddToSelection(array.Length, array);
			return true;
		}

		public ShapeCreationResult TryCreateAndSelectCurveShapeInSelectedShapeContainer(ShapeType type, ShapeColor color, Vector3 initialPosition, Quaternion initialRotation, float initialRadius)
		{
			if (!base.hasAuthority)
			{
				return new ShapeCreationResult(CreationResult.Failure_NoAuthority, Guid.Empty);
			}
			if (SelectedShapeContainer == null)
			{
				return new ShapeCreationResult(CreationResult.Failure_Generic, Guid.Empty);
			}
			if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit || IsOverCostLimit)
			{
				return new ShapeCreationResult(CreationResult.Failure_InsufficientResources, Guid.Empty);
			}
			RemoveAllFromSelection();
			Guid newShapeGuid = creationShapeContainer.AuthorityCreateCurveShape(type, color, initialPosition, initialRotation, initialRadius);
			return new ShapeCreationResult(CreationResult.Success, newShapeGuid);
		}

		public CreationResult TryAddSelectedCurveShapeControlPoint(Vector3 position, Vector3 normal, float radius)
		{
			if (!base.hasAuthority)
			{
				return CreationResult.Failure_NoAuthority;
			}
			if (SelectedShapeContainer == null)
			{
				return CreationResult.Failure_Generic;
			}
			if (SelectionCount != 1)
			{
				return CreationResult.Failure_Generic;
			}
			if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit || IsOverCostLimit)
			{
				return CreationResult.Failure_InsufficientResources;
			}
			Guid shapeId = SelectedShapes[0];
			creationShapeContainer.AuthorityAddCurveShapeControlPoint(shapeId, position, normal, radius);
			return CreationResult.Success;
		}

		public void UpdateSelectedCurveShapeFirstControlPoint(Vector3 position, Vector3 normal, float radius, bool broadcastChangesOverNetwork)
		{
			if (base.hasAuthority && !(SelectedShapeContainer == null) && SelectionCount == 1)
			{
				Guid shapeId = SelectedShapes[0];
				creationShapeContainer.AuthorityUpdateCurveShapeControlPoint(shapeId, 0, position, normal, radius, broadcastChangesOverNetwork);
			}
		}

		public void UpdateSelectedCurveShapeLatestControlPoint(Vector3 position, Vector3 normal, float radius, bool broadcastChangesOverNetwork)
		{
			if (base.hasAuthority && !(SelectedShapeContainer == null) && SelectionCount == 1)
			{
				Guid shapeId = SelectedShapes[0];
				int controlPointCount = 0;
				if (creationShapeContainer.TryGetCurveShapeControlPointCount(shapeId, out controlPointCount) && controlPointCount > 0)
				{
					creationShapeContainer.AuthorityUpdateCurveShapeControlPoint(shapeId, controlPointCount - 1, position, normal, radius, broadcastChangesOverNetwork);
				}
			}
		}

		public bool TryGetSelectedCurveShapeFirstControlPointPosition(out Vector3 controlPointPosition)
		{
			controlPointPosition = Vector3.zero;
			if (!base.hasAuthority)
			{
				return false;
			}
			if (SelectedShapeContainer == null)
			{
				return false;
			}
			if (SelectionCount != 1)
			{
				return false;
			}
			Guid shapeId = SelectedShapes[0];
			return creationShapeContainer.TryGetCurveShapeControlPointPosition(shapeId, 0, out controlPointPosition);
		}

		public bool TryGetSelectedCurveShapePreviousControlPointPosition(out Vector3 controlPointPosition)
		{
			controlPointPosition = Vector3.zero;
			if (!base.hasAuthority)
			{
				return false;
			}
			if (SelectedShapeContainer == null)
			{
				return false;
			}
			if (SelectionCount != 1)
			{
				return false;
			}
			Guid shapeId = SelectedShapes[0];
			int controlPointCount = 0;
			if (!creationShapeContainer.TryGetCurveShapeControlPointCount(shapeId, out controlPointCount) || controlPointCount <= 1)
			{
				return false;
			}
			return creationShapeContainer.TryGetCurveShapeControlPointPosition(shapeId, controlPointCount - 2, out controlPointPosition);
		}

		public ShapeCreationResult TryCreateAndSelectMeshShapeInSelectedShapeContainer(ShapeType type, ShapeColor color, Vector3 initialPosition, Quaternion initialRotation, Vector3 initialSize)
		{
			if (!base.hasAuthority)
			{
				return new ShapeCreationResult(CreationResult.Failure_NoAuthority, Guid.Empty);
			}
			if (SelectedShapeContainer == null)
			{
				return new ShapeCreationResult(CreationResult.Failure_Generic, Guid.Empty);
			}
			if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit || IsOverCostLimit)
			{
				return new ShapeCreationResult(CreationResult.Failure_InsufficientResources, Guid.Empty);
			}
			RemoveAllFromSelection();
			Guid newShapeGuid = creationShapeContainer.AuthorityCreateMeshShape(type, color, initialPosition, initialRotation, initialSize);
			return new ShapeCreationResult(CreationResult.Success, newShapeGuid);
		}

		public void UpdateSelectedMeshShapeAspectRatio(Vector3 aspectRatio, bool broadcastChangesOverNetwork)
		{
			if (base.hasAuthority && !(SelectedShapeContainer == null) && SelectionCount == 1)
			{
				Guid shapeId = SelectedShapes[0];
				creationShapeContainer.AuthoritySetMeshShapeAspectRatio(shapeId, aspectRatio, broadcastChangesOverNetwork);
			}
		}

		public void SetSelectedMeshShapeAspectRatios(Guid[] shapeIds, Vector3[] aspectRatios)
		{
			if (base.hasAuthority && !(SelectedShapeContainer == null))
			{
				creationShapeContainer.AuthoritySetMeshShapeAspectRatios(shapeIds, aspectRatios);
			}
		}

		public bool TryGetShapeRotation(Guid shapeId, out Quaternion rotationResult)
		{
			if ((bool)SelectedShapeContainer && SelectedShapeContainer.TryGetShapeRotation(shapeId, out rotationResult))
			{
				return true;
			}
			if ((bool)creationShapeContainer && creationShapeContainer.TryGetShapeRotation(shapeId, out rotationResult))
			{
				return true;
			}
			rotationResult = Quaternion.identity;
			return false;
