		public bool AddToSelection(int shapeCount, Guid[] shapeIds)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			bool flag = true;
			for (int i = 0; i < shapeCount && i < shapeIds.Length; i++)
			{
				if (!AddShapeToSelectionInternal(shapeIds[i]))
				{
					flag = false;
				}
			}
			if (!flag)
			{
				for (int j = 0; j < shapeCount && j < shapeIds.Length; j++)
				{
					RemoveFromSelection(shapeIds[j]);
				}
			}
			if (flag)
			{
				OnSelectionChanged();
			}
			return flag;
		}

