		public bool TranslateSelection(Vector3 linearDisplacement)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (creationShapeContainer.IsEmpty)
			{
				return false;
			}
			creationShapeContainer.transform.position += linearDisplacement;
			return true;
		}

		public bool RotateSelection(Quaternion angularDisplacement, Vector3? pivotPoint = null)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (creationShapeContainer.IsEmpty)
			{
				return false;
			}
			if (pivotPoint.HasValue)
			{
				creationShapeContainer.transform.position = pivotPoint.Value + angularDisplacement * (creationShapeContainer.transform.position - pivotPoint.Value);
			}
			creationShapeContainer.transform.rotation = angularDisplacement * creationShapeContainer.transform.rotation;
			return true;
		}

		public bool ScaleSelection(float deltaScale, Vector3? pivotPoint = null)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (creationShapeContainer.IsEmpty)
			{
				return false;
			}
			float localUniformScale = creationShapeContainer.transform.GetLocalUniformScale();
			float num = (localUniformScale + deltaScale) / localUniformScale;
			float magnitude = SelectionBounds.extents.magnitude;
			float num2 = Mathf.Clamp(magnitude * num, 0.01f, 1000f);
			num = num2 / magnitude;
			creationShapeContainer.transform.SetLocalUniformScale(localUniformScale * num);
			if (pivotPoint.HasValue)
			{
				Vector3 vector = creationShapeContainer.transform.position - pivotPoint.Value;
				creationShapeContainer.transform.position = pivotPoint.Value + vector * num;
			}
			return true;
		}

		public CreationResult TryCloneSelectedShapes()
		{
			if (!base.hasAuthority)
			{
				return CreationResult.Failure_NoAuthority;
			}
			if (creationShapeContainer.IsEmpty)
			{
				return CreationResult.Failure_Generic;
			}
			if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit || IsOverCostLimit)
			{
				return CreationResult.Failure_InsufficientResources;
			}
			Guid[] array = SelectedShapes.ToArray();
			RemoveAllFromSelection();
			int shapesCost = SelectedShapeContainer.GetShapesCost(array);
			if (!CanSelectedContainerAffordResourceCost(shapesCost))
			{
				AddToSelection(array.Length, array);
				return CreationResult.Failure_InsufficientResources;
			}
			SelectedShapeContainer.AuthorityCloneShapesToShapeContainer(array, creationShapeContainer);
			return CreationResult.Success;
		}

