		public bool SetSelectedShapeTransforms(Guid[] shapeIds, Vector3[] localPositions, Quaternion[] localRotations, float[] localScales)
		{
			if (!base.hasAuthority)
			{
				return false;
			}
			if (creationShapeContainer.IsEmpty)
			{
				return false;
			}
			if (localPositions != null && shapeIds.Length != localPositions.Length)
			{
				UnityEngine.Debug.LogError($"ShapeCreationContext received mismatched arrays when setting positions on shape {SelectedShapeContainer.DebugName} ({shapeIds.Length} IDs, {localPositions.Length} positions)");
				return false;
			}
			if (localRotations != null && shapeIds.Length != localRotations.Length)
			{
				UnityEngine.Debug.LogError($"ShapeCreationContext received mismatched arrays when setting rotations on shape {SelectedShapeContainer.DebugName} ({shapeIds.Length} IDs, {localRotations.Length} rotations)");
				return false;
			}
			if (localScales != null && shapeIds.Length != localScales.Length)
			{
				UnityEngine.Debug.LogError($"ShapeCreationContext received mismatched arrays when setting scales on shape {SelectedShapeContainer.DebugName} ({shapeIds.Length} IDs, {localScales.Length} scales)");
				return false;
			}
			Vector3[] array = null;
			Quaternion[] array2 = null;
			float[] array3 = null;
			if (localPositions != null)
			{
				array = new Vector3[localPositions.Length];
				for (int i = 0; i < localPositions.Length; i++)
				{
					Vector3 position = SelectedShapeContainer.ShapeRoot.TransformPoint(localPositions[i]);
					ref Vector3 reference = ref array[i];
					reference = creationShapeContainer.ShapeRoot.InverseTransformPoint(position);
				}
			}
			if (localRotations != null)
			{
				array2 = new Quaternion[localRotations.Length];
				for (int j = 0; j < localRotations.Length; j++)
				{
					Quaternion rotation = SelectedShapeContainer.ShapeRoot.TransformRotation(localRotations[j]);
					ref Quaternion reference2 = ref array2[j];
					reference2 = creationShapeContainer.ShapeRoot.InverseTransformRotation(rotation);
				}
			}
			if (localScales != null)
			{
				array3 = new float[localScales.Length];
				for (int k = 0; k < localScales.Length; k++)
				{
					float uniformLossyScale = SelectedShapeContainer.ShapeRoot.TransformLocalUniformScale(localScales[k]);
					array3[k] = creationShapeContainer.ShapeRoot.InverseTransformLossyUniformScale(uniformLossyScale);
				}
			}
			creationShapeContainer.AuthoritySetShapeTransforms(shapeIds, array, array2, array3);
			return true;
		}

