		public bool CanSelectedContainerAffordResourceCost(int cost)
		{
			if (SelectedShapeContainer == null)
			{
				return false;
			}
			return (cost <= 0 || CombinedSandboxResourceCost + cost <= SelectedContainerMaxResources) && NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(cost);
		}

		public bool CanAffordToAddShapes(int shapeColliderCosts)
		{
			if (SelectedShapeContainer == null)
			{
				return false;
			}
			int shapesCost = ShapeContainer.GetShapesCost(shapeColliderCosts, SelectedShapeContainer.CurrentPhysicsMode);
			return CanSelectedContainerAffordResourceCost(shapesCost);
		}

		public bool CanAffordToAddShapes(ShapeContainer targetContainer, int shapeColliderCosts)
		{
			if (SelectedShapeContainer == targetContainer)
			{
				return CanAffordToAddShapes(shapeColliderCosts);
			}
			return targetContainer.CanAffordToAddShapes(shapeColliderCosts);
		}

		public bool CanAffordNewShapeContainer(SpawnableToolType shapeContainerType, int shapeColliderCosts)
		{
			if (!ShapeSettings.IsSpawnableShapeContainer(shapeContainerType))
			{
				return false;
			}
			ShapeContainer shapeContainer = SpawnableToolSettings.GetSpawnableToolPrefab(shapeContainerType)?.GetComponent<ShapeContainer>();
			if (shapeContainer == null)
			{
				return false;
			}
			int spawnableToolSandboxResourceCost = SpawnableToolSettings.GetSpawnableToolSandboxResourceCost(shapeContainerType);
			int shapesCost = ShapeContainer.GetShapesCost(shapeColliderCosts, shapeContainer.DefaultPhysicsMode);
			if (!NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(spawnableToolSandboxResourceCost + shapesCost))
			{
				return false;
			}
			if (shapesCost > shapeContainer.MaxResources)
			{
				return false;
			}
			return true;
		}

		public void CheckNotifyResourceLimits()
		{
			int combinedSandboxResourceCost = CombinedSandboxResourceCost;
			if (combinedSandboxResourceCost >= SelectedContainerMaxResources)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Can't add more shapes to this Object.", "Please start a new one.", 2f);
			}
			else if ((float)combinedSandboxResourceCost >= (float)SelectedContainerMaxResources * 0.75f && SelectedShapeContainer.ShapeCount % 5 == 0)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "This Maker Pen Object is almost full.", "Start a new one soon.", 2f);
			}
		}

		private void AuthorityCacheShapeContainers()
		{
			if (CachedEmptyStandaloneShapeContainer == null)
			{
				AuthorityCacheShapeContainer(SpawnableToolType.SHAPE_CONTAINER);
			}
			if (CachedEmptyTriggerVolumeShapeContainer == null)
			{
				AuthorityCacheShapeContainer(SpawnableToolType.TRIGGER_VOLUME);
			}
		}

		private void AuthorityCacheShapeContainer(SpawnableToolType shapeContainerType)
		{
			SetCachedShapeContainer(null, shapeContainerType);
			AuthorityGetCachedShapeContainer(shapeContainerType).Then(delegate(ShapeContainer s)
			{
				SetCachedShapeContainer(s, shapeContainerType);
			});
		}

		private void SetCachedShapeContainer(ShapeContainer shapeContainer, SpawnableToolType shapeContainerType)
		{
			switch (shapeContainerType)
			{
			case SpawnableToolType.SHAPE_CONTAINER:
				CachedEmptyStandaloneShapeContainer = (StandaloneShapeContainer)shapeContainer;
				break;
			case SpawnableToolType.TRIGGER_VOLUME:
				CachedEmptyTriggerVolumeShapeContainer = (TriggerVolumeShapeContainer)shapeContainer;
				break;
			default:
				throw new ArgumentException($"Unable to cache ShapeContainer of type {shapeContainerType}");
			}
		}

		private IPromise<ShapeContainer> AuthorityGetCachedShapeContainer(SpawnableToolType shapeContainerType)
		{
			if (!base.hasAuthority)
			{
				return new ErroredPromise<ShapeContainer>("Unable to get cached shape container without authority.");
			}
			switch (shapeContainerType)
			{
			case SpawnableToolType.SHAPE_CONTAINER:
				if (CachedEmptyStandaloneShapeContainer != null)
				{
					return new CompletedPromise<ShapeContainer>(CachedEmptyStandaloneShapeContainer);
				}
				break;
			case SpawnableToolType.TRIGGER_VOLUME:
				if (CachedEmptyTriggerVolumeShapeContainer != null)
				{
					return new CompletedPromise<ShapeContainer>(CachedEmptyTriggerVolumeShapeContainer);
				}
				break;
			default:
			{
				string text = $"ShapeCreationContext cannot spawn tools of type {shapeContainerType}";
				UnityEngine.Debug.LogError(text);
				return new ErroredPromise<ShapeContainer>(text);
			}
			}
			return AuthorityRequestNewCachedShapeContainer(shapeContainerType);
		}

		private IPromise<ShapeContainer> AuthorityRequestNewCachedShapeContainer(SpawnableToolType shapeContainerType)
		{
			if (!base.hasAuthority)
			{
				string text = "Unable to request new shape containers on non-authority clients.";
				UnityEngine.Debug.LogError(text);
				return new ErroredPromise<ShapeContainer>(text);
			}
			if (parentCreationContext.WaitingForPersistence)
			{
				string text2 = "Unable to request new shape containers during a persistence operation.";
				UnityEngine.Debug.LogError(text2);
				return new ErroredPromise<ShapeContainer>(text2);
			}
			if (!ShapeSettings.IsSpawnableShapeContainer(shapeContainerType))
			{
				string text3 = $"ShapeCreationContext cannot spawn tools of type {shapeContainerType}";
				UnityEngine.Debug.LogError(text3);
				return new ErroredPromise<ShapeContainer>(text3);
			}
			if (pendingCachedContainerRequests.TryGetValue(shapeContainerType, out var value))
			{
				float num = UnityEngine.Time.realtimeSinceStartup - value.requestTime;
				if (num < 2f)
				{
					return value.promise;
				}
				value.promise.Error($"Request for new ShapeContainer {shapeContainerType} timed out.");
			}
			ShapeContainerRequest shapeContainerRequest = new ShapeContainerRequest();
			shapeContainerRequest.promise = new Promise<ShapeContainer>();
			shapeContainerRequest.requestTime = UnityEngine.Time.realtimeSinceStartup;
			ShapeContainerRequest shapeContainerRequest2 = shapeContainerRequest;
			pendingCachedContainerRequests[shapeContainerType] = shapeContainerRequest2;
			base.photonView.RpcMaster(RpcMasterRequestNewShapeContainer, shapeContainerType);
			return shapeContainerRequest2.promise;
		}

		private void RemoteMasterRequestNewCachedShapeContainer(SpawnableToolType shapeContainerType, PhotonPlayer requestingPlayer)
		{
			ShapeContainer newShapeContainer = null;
			CreationResult arg = MasterSpawnCachedShapeContainer(requestingPlayer, shapeContainerType, out newShapeContainer);
			base.photonView.RpcPlayer(requestingPlayer, RpcOnNewShapeContainerRequestResult, newShapeContainer, shapeContainerType, arg);
		}

		private CreationResult MasterSpawnCachedShapeContainer(PhotonPlayer requestingPlayer, SpawnableToolType shapeContainerType, out ShapeContainer newShapeContainer)
		{
			newShapeContainer = null;
			if (!PhotonNetwork.isMasterClient)
			{
				return CreationResult.Failure_NoAuthority;
			}
			if (requestingPlayer == null)
			{
				return CreationResult.Failure_NetworkError;
			}
			newShapeContainer = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.MasterSpawnTool(shapeContainerType, Vector3.zero, Quaternion.identity, 1f)?.GetComponent<ShapeContainer>();
			if (newShapeContainer == null)
			{
				return CreationResult.Failure_Generic;
			}
			newShapeContainer.photonView.TransferOwnership(requestingPlayer);
			newShapeContainer.Tool.IsEnabled = false;
			SynchronizedField.SendPendingRoomUpdates();
			return CreationResult.Success;
		}

		private void RemoteOnNewShapeContainerRequestResult(ShapeContainer shapeContainer, SpawnableToolType shapeContainerType, CreationResult result)
		{
			if (pendingCachedContainerRequests.TryGetValue(shapeContainerType, out var value))
			{
				pendingCachedContainerRequests.Remove(shapeContainerType);
				if (result == CreationResult.Success)
				{
					value.promise.Complete(shapeContainer);
					return;
				}
				string message = $"Error returned when requesting new ShapeContainer: {result}";
				UnityEngine.Debug.LogError(message);
				value.promise.Error(message);
			}
		}

		private bool CanSelectShapeContainer(ShapeContainer shapeContainer)
		{
			if (shapeContainer == null || shapeContainer.Tool == null)
			{
				return false;
			}
			if (shapeContainer.Tool.IsHeldByPlayer && shapeContainer.Tool.HolderPlayer != Player.LocalPlayer)
			{
				return false;
			}
			if (shapeContainer.Tool.IsHeld && shapeContainer.Tool.photonView.instantiationId != shapeContainer.Tool.HolderView.instantiationId)
			{
				return false;
			}
			if (!shapeContainer.Tool.IsEnabled)
			{
				return false;
			}
			if (shapeContainer.CreationObject.IsLocked && !shapeContainer.CreationObject.LocalPlayerHasLock)
			{
				return false;
			}
			return true;
		}

		private void OnShapeContainerSelected(ShapeContainer shapeContainer)
		{
			shapeContainer.OnSelectedByShapeCreationContext();
			shapeContainer.OnShapesChangedEvent = (Action)Delegate.Combine(shapeContainer.OnShapesChangedEvent, new Action(OnSelectedShapeContainerShapesChanged));
		}

		private void OnShapeContainerDeselected(ShapeContainer shapeContainer)
		{
			if (base.hasAuthority)
			{
				RemoveAllShapesFromSelectionInternal(shapeContainer);
			}
			shapeContainer.OnDeselectedByShapeCreationContext();
			shapeContainer.OnShapesChangedEvent = (Action)Delegate.Remove(shapeContainer.OnShapesChangedEvent, new Action(OnSelectedShapeContainerShapesChanged));
			if (shapeContainer.DestroyIfEmpty && shapeContainer.IsEmpty && !shapeContainer.WaitingForShapeData)
			{
				shapeContainer.CreationObject.RequestMasterDespawn();
			}
		}

		private void OnSelectedShapeContainerShapesChanged()
		{
			this.InvokeNextEndOfFrame(delegate
			{
				EnsureAnyValidShapes();
			});
		}

