		private bool CanSelectShape(Guid shapeId)
		{
			if (SelectedShapeContainer == null)
			{
				return false;
			}
			if (shapeId == Guid.Empty)
			{
				return false;
			}
			if (!SelectedShapeContainer.ContainsShape(shapeId) && !creationShapeContainer.ContainsShape(shapeId))
			{
				return false;
			}
			return true;
		}

		private bool AddShapeToSelectionInternal(Guid shapeId)
		{
			if (!CanSelectShape(shapeId))
			{
				return false;
			}
			if (SelectedShapes.Contains(shapeId))
			{
				return false;
			}
			SelectedShapeContainer.AuthorityTransferShapeToShapeContainer(shapeId, creationShapeContainer);
			return true;
		}

		private void RemoveShapeFromSelectionInternal(Guid shapeId)
		{
			if (SelectedShapeContainer != null)
			{
				creationShapeContainer.AuthorityTransferShapeToShapeContainer(shapeId, SelectedShapeContainer);
			}
		}

		private void RemoveAllShapesFromSelectionInternal(ShapeContainer transferTargetContainer)
		{
			if (transferTargetContainer != null)
			{
				creationShapeContainer.AuthorityTransferShapesToShapeContainer(SelectedShapes.ToArray(), transferTargetContainer);
				return;
			}
			UnityEngine.Debug.LogError("Attempting to remove shapes from selection, but no target container was specified. Deleting shapes instead...");
			creationShapeContainer.AuthorityDeleteShapes(SelectedShapes.ToArray());
		}

		public IPromise<ShapeContainer> TrySplitSelectedShapes()
		{
			if (!base.hasAuthority)
			{
				return new ErroredPromise<ShapeContainer>("No authority");
			}
			if (!HasSelection)
			{
				return new ErroredPromise<ShapeContainer>("No selection");
			}
			if (!SelectedShapeContainer.CanBeSplit)
			{
				return new ErroredPromise<ShapeContainer>("Cannot split selected container");
			}
			Promise<ShapeContainer> promise = new Promise<ShapeContainer>();
			ShapeContainer cachedSelectedContainer = SelectedShapeContainer;
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnTool(SpawnableToolType.SHAPE_CONTAINER, Vector3.zero, Quaternion.identity, 1f).Then(delegate(Tool tool)
			{
				if (cachedSelectedContainer != null)
				{
					ShapeContainer component = tool.GetComponent<ShapeContainer>();
					tool.Tags.InitializeDefaultTagIds();
					tool.Tags.CopyTags(cachedSelectedContainer.Tool.Tags);
					component.CurrentPhysicsMode = cachedSelectedContainer.CurrentPhysicsMode;
					RemoveAllShapesFromSelectionInternal(component);
					OnSelectionChanged();
					promise.Complete(component);
				}
				else
				{
					tool.CreationObject.RequestMasterDespawn();
					promise.Error("Selected shape container was destroyed before split could complete.");
				}
			}).Error(delegate(string e)
			{
				promise.Error(e);
			});
			return promise;
		}

		private void RenderHandWorldFadeMask(PlayerHand hand)
		{
			GameObject gameObject = ((!hand.IsHoldingTool) ? hand.gameObject : hand.HeldTool.gameObject);
			if (!gameObject)
			{
				return;
			}
			Renderer[] componentsInChildren = gameObject.GetComponentsInChildren<Renderer>();
			Renderer[] array = componentsInChildren;
			foreach (Renderer renderer in array)
			{
				if (renderer.enabled && !(renderer is SpriteRenderer) && renderer.sharedMaterial.renderQueue < 2450)
				{
					WorldFadeRenderer.RenderMask(renderer);
				}
			}
		}

		private void RenderWorldFadeMask()
		{
			bool flag = false;
			if ((bool)SelectedShapeContainer && !SelectedShapeContainer.IsEmpty)
			{
				flag = true;
				SelectedShapeContainer.RenderWorldFadeMask();
			}
			if ((bool)creationShapeContainer && !creationShapeContainer.IsEmpty)
			{
				flag = true;
				creationShapeContainer.RenderWorldFadeMask();
			}
			if (flag && Player.LocalPlayer != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR)
			{
				RenderHandWorldFadeMask(Player.LocalPlayer.LeftHand);
				RenderHandWorldFadeMask(Player.LocalPlayer.RightHand);
			}
		}

		public void RenderHoverHighlight(int shapeCount, IEnumerable<Guid> shapes)
		{
			RenderHoverHighlight(shapeCount, shapes, OutlineEffectRenderer.OutlineType.ExtrusionHover);
		}

		public void RenderHoverHighlight(int shapeCount, IEnumerable<Guid> shapes, OutlineEffectRenderer.OutlineType outlineType)
		{
			int num = 0;
			foreach (Guid shape in shapes)
			{
				if (num >= shapeCount)
				{
					break;
				}
				if ((bool)SelectedShapeContainer)
				{
					SelectedShapeContainer.RenderShapeOutline(shape, outlineType);
				}
				if ((bool)creationShapeContainer)
				{
					creationShapeContainer.RenderShapeOutline(shape, outlineType);
				}
				num++;
			}
		}

