		public static int CalculateObjectCosts(IEnumerable<CreationObject> objects)
		{
			int num = 0;
			foreach (CreationObject @object in objects)
			{
				num += @object.SandboxResourceCost;
			}
			return num;
		}

		public static int CalculateObjectCosts(IEnumerable<Tool> tools)
		{
			int num = 0;
			foreach (Tool tool in tools)
			{
				if (tool.CreationObject != null)
				{
					num += tool.CreationObject.SandboxResourceCost;
				}
			}
			return num;
		}

		public static int CalculateObjectCosts(IEnumerable<Guid> objectIds)
		{
			int num = 0;
			foreach (Guid objectId in objectIds)
			{
				if (TryGetCreationObjectFromId(objectId, out var creationObject))
				{
					num += creationObject.SandboxResourceCost;
				}
			}
			return num;
		}

