				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref CreationManager.m_ActiveSandboxResourcesChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = CreationManager.m_ActiveSandboxResourcesChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref CreationManager.m_ActiveSandboxResourcesChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

