			{
				activeResourceCostDirty = true;
				SingletonMonoBehaviour<Scheduler>.Instance.Run(InvokeResourcesUpdatedEvent());
			}
		}

		private static IEnumerator<ISchedule> InvokeResourcesUpdatedEvent()
		{
