		[PunRPC]
		private void RpcMasterDestroyAll()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			for (int num = SpawnedObjects.Count - 1; num >= 0; num--)
			{
				if (SpawnedObjects[num].ShouldDestroyWhenDestroyingAll)
				{
					SpawnedObjects[num].MasterDespawn();
				}
			}
			base.photonView.RpcAll(RpcAllSpawnedObjectsDestroyed);
		}

