		public IPromise<SerializeTemplateResult> SerializeSpawnableTemplate(IEnumerable<CreationObject> creationObjects, bool verboseLogging = false)
		{
			INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Clear();
			foreach (CreationObject creationObject in creationObjects)
			{
				INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Add(creationObject.Tool.PersistenceView);
			}
			List<PersistenceView> persistenceViews = INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.ToList();
			return SerializeSpawnableTemplate(persistenceViews, verboseLogging);
		}

		public IPromise<SerializeTemplateResult> SerializeSpawnableTemplate(IEnumerable<Guid> viewIds, bool verboseLogging = false)
		{
			INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Clear();
			foreach (Guid viewId in viewIds)
			{
				if (PersistenceView.AllViews.TryGetValue(viewId, out var value))
				{
					INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Add(value);
				}
			}
			List<PersistenceView> persistenceViews = INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.ToList();
			return SerializeSpawnableTemplate(persistenceViews, verboseLogging);
		}

		public IPromise<SerializeTemplateResult> SerializeSpawnableTemplate(IEnumerable<PersistenceView> persistenceViews, bool verboseLogging = false)
		{
			Promise<SerializeTemplateResult> promise = new Promise<SerializeTemplateResult>();
			SingletonMonoBehaviour<Scheduler>.Instance.Run(this, SerializeSpawnableTemplateDataBlobCoroutine(persistenceViews, verboseLogging, promise));
			return promise;
		}

		private IEnumerator<ISchedule> SerializeSpawnableTemplateDataBlobCoroutine(IEnumerable<PersistenceView> persistenceViews, bool verboseLogging, Promise<SerializeTemplateResult> promise)
		{
			StringBuilder outputBuilder = new StringBuilder();
			int pendingPreserializes = 0;
			foreach (PersistenceView persistenceView in persistenceViews)
			{
				if (persistenceView.IsPersistable)
				{
					pendingPreserializes++;
					persistenceView.PreSerialize(outputBuilder, savedToDisk: false).Finally(delegate
					{
						pendingPreserializes--;
					});
				}
			}
			float time = UnityEngine.Time.realtimeSinceStartup;
			yield return Schedule.Until(() => pendingPreserializes == 0);
			int nodeCountAtBeginning = CircuitNode.NodeCount;
			INSTANTANEOUS_TRANSIENT_IMAGE_NAMES_TO_PERSIST.Clear();
			INSTANTANEOUS_TRANSIENT_DATA_BLOB_NAMES_TO_PERSIST.Clear();
			INSTANTANEOUS_CIRCUIT_NODE_DISPLAY_LIST.Clear();
			INSTANTANEOUS_CIRCUITS_LIST.Clear();
			int hiddenCount = 0;
			if (verboseLogging)
			{
				UnityEngine.Debug.LogFormat("Group Preserialization complete in {0} seconds", UnityEngine.Time.realtimeSinceStartup - time);
			}
			SpawnableTemplateData spawnableTemplateData = InitializeSpawnableTemplateDataBlob();
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.PauseNetworking();
			foreach (PersistenceView persistenceView2 in persistenceViews)
			{
				CircuitNodeDisplay component = persistenceView2.gameObject.GetComponent<CircuitNodeDisplay>();
				if (!(component != null))
				{
					continue;
				}
				if (component.MyCircuitNode == null)
				{
					UnityEngine.Debug.LogWarning("Found CircuitNodeDisplay with null CircuitNode during serialization. This will cause problems...");
					continue;
				}
				INSTANTANEOUS_CIRCUIT_NODE_DISPLAY_LIST.Add(component);
				INSTANTANEOUS_CIRCUITS_LIST.Add(component.MyCircuitNode);
				if (component.MyCircuitNode.PairedNode != null)
				{
					hiddenCount++;
					INSTANTANEOUS_CIRCUITS_LIST.Add(component.MyCircuitNode.PairedNode);
				}
			}
			bool hasValidCircuitData = INSTANTANEOUS_CIRCUITS_LIST.Count > 0;
			UnityEngine.Debug.LogFormat("Found {0} circuit nodes ({1} hidden)", INSTANTANEOUS_CIRCUITS_LIST.Count, hiddenCount);
			if (hasValidCircuitData)
			{
				CircuitNodeGraph.CircuitNodeGraphCopy circuitNodeGraphCopy = CircuitNodeGraph.CopyNodesToNewGraphs(INSTANTANEOUS_CIRCUITS_LIST);
				if (circuitNodeGraphCopy != null && circuitNodeGraphCopy.GraphCollectionData.Graphs.Count > 0)
				{
					if (verboseLogging)
					{
						UnityEngine.Debug.LogFormat("CopyNodesToNewGraphs results:  {0} graphs", circuitNodeGraphCopy.GraphCollectionData.Graphs.Count);
					}
					spawnableTemplateData.CircuitData = circuitNodeGraphCopy.GraphCollectionData.ToByteString();
					foreach (CircuitNodeDisplay item in INSTANTANEOUS_CIRCUIT_NODE_DISPLAY_LIST)
					{
						int nodeId = item.NodeId;
						int value = circuitNodeGraphCopy.NodeMapping[nodeId];
						item.OverrideNodeId(value);
					}
				}
				else
				{
					UnityEngine.Debug.LogWarning("Serialization problem -- found circuit data but did not get valid output from CopyGraph");
				}
			}
			HashSet<Guid> subgraphPersistenceViewIds = new HashSet<Guid>();
			foreach (PersistenceView persistenceView3 in persistenceViews)
			{
				subgraphPersistenceViewIds.Add(persistenceView3.Id);
			}
			spawnableTemplateData.ConnectableGraphData = NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.SerializeConnectableSubgraph(subgraphPersistenceViewIds);
			foreach (PersistenceView persistenceView4 in persistenceViews)
			{
				if (!(persistenceView4 != null) || !persistenceView4.IsPersistable)
				{
					continue;
				}
				if (verboseLogging)
				{
					UnityEngine.Debug.LogFormat(persistenceView4, "Serializing PersistanceView {0}", persistenceView4.gameObject);
				}
				TransientDataToPersist transientData = default(TransientDataToPersist);
				PersistenceViewData persistenceViewData = persistenceView4.Serialize(ref transientData, outputBuilder);
				if (persistenceViewData == null)
				{
					continue;
				}
				if (persistenceViewData.SpawnableToolData == null)
				{
					UnityEngine.Debug.LogErrorFormat(persistenceView4, "Error serializing PersistenceView {0} that contains no SpawnableToolData", persistenceView4.gameObject);
					continue;
				}
				spawnableTemplateData.PersistenceViews.Add(persistenceViewData);
				if (transientData.imageNamesToPersist != null)
				{
					INSTANTANEOUS_TRANSIENT_IMAGE_NAMES_TO_PERSIST.AddRange(transientData.imageNamesToPersist);
				}
				if (transientData.datablobNamesToPersist != null)
				{
					INSTANTANEOUS_TRANSIENT_DATA_BLOB_NAMES_TO_PERSIST.AddRange(transientData.datablobNamesToPersist);
				}
			}
			spawnableTemplateData.OutputLog = outputBuilder.ToString();
			foreach (CircuitNodeDisplay item2 in INSTANTANEOUS_CIRCUIT_NODE_DISPLAY_LIST)
			{
				item2.OverrideNodeId(null);
			}
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.UnpauseNetworking();
			int nodeCountAtEnd = CircuitNode.NodeCount;
			if (nodeCountAtBeginning != nodeCountAtEnd)
			{
				UnityEngine.Debug.LogError($"Node count mismatch... started with {nodeCountAtBeginning} and finished with {nodeCountAtEnd} - in SerializeSpawnableTemplateDataBlobCoroutine");
			}
			if (UnityExtensions.CalculateCombinedExtents(persistenceViews, out var combinedExtents))
			{
				spawnableTemplateData.Extents = combinedExtents.ToVector3Data();
			}
			List<string> imageListCopy = new List<string>(INSTANTANEOUS_TRANSIENT_IMAGE_NAMES_TO_PERSIST);
			List<string> dataBlobListCopy = new List<string>(INSTANTANEOUS_TRANSIENT_DATA_BLOB_NAMES_TO_PERSIST);
			SerializeTemplateResult result = new SerializeTemplateResult
			{
				spawnableTemplateData = spawnableTemplateData,
				transientImages = imageListCopy,
				transientDataBlobs = dataBlobListCopy
			};
			promise.Complete(result);
		}

		public IPromise<SpawnTemplateResult> RequestSpawnTemplate(SpawnableTemplateData spawnableTemplateData, int cost, bool assignNewIds, SpawnTransformData? spawnTransformData = null, bool verboseLogging = false)
		{
			if (pendingLocalSpawnTemplateRequest != null && UnityEngine.Time.realtimeSinceStartup - lastSpawnRequestTime < 5f)
			{
				return new CompletedPromise<SpawnTemplateResult>(new SpawnTemplateResult
				{
					result = CreationResult.Failure_Generic
				});
			}
			if (!CanAffordResourceCost(cost))
			{
				return new CompletedPromise<SpawnTemplateResult>(new SpawnTemplateResult
				{
					result = CreationResult.Failure_InsufficientResources
				});
			}
			Promise<SpawnTemplateResult> promise = (pendingLocalSpawnTemplateRequest = new Promise<SpawnTemplateResult>());
			lastSpawnRequestTime = UnityEngine.Time.realtimeSinceStartup;
			promise.Finally(delegate
			{
				pendingLocalSpawnTemplateRequest = null;
			});
			base.photonView.RpcMaster(RpcMasterSpawnTemplate, spawnableTemplateData, cost, assignNewIds, spawnTransformData, verboseLogging);
			return promise;
		}

		[PunRPC]
		public void RpcMasterSpawnTemplate(SpawnableTemplateData spawnableTemplateData, int cost, bool assignNewIds, SpawnTransformData? spawnTransformData, bool verboseLogging, PhotonMessageInfo messageInfo)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			List<Tool> spawnedTools = null;
			SpawnableTemplateData templateData = null;
			CreationResult result = CreationResult.Success;
			PhotonPlayer requestingPlayer = messageInfo.sender;
			MasterSpawnTemplate(spawnableTemplateData, cost, assignNewIds, spawnTransformData, verboseLogging).Then(delegate(SpawnTemplateResult spawnResult)
			{
				result = spawnResult.result;
				spawnedTools = spawnResult.spawnedTools;
				templateData = spawnResult.templateData;
			}).Error(delegate
			{
				result = CreationResult.Failure_Generic;
			}).Finally(delegate
			{
				if (spawnedTools != null)
				{
					foreach (Tool item in spawnedTools)
					{
						item.photonView.TransferOwnership(requestingPlayer);
					}
					SynchronizedField.SendPendingRoomUpdates();
				}
				base.photonView.RpcPlayer(requestingPlayer, RpcOnSpawnResult, spawnedTools, templateData, result);
			});
		}

		[PunRPC]
		private void RpcOnSpawnResult(List<Tool> spawnedTools, SpawnableTemplateData templateData, CreationResult result)
		{
			if (pendingLocalSpawnTemplateRequest != null)
			{
				pendingLocalSpawnTemplateRequest.Complete(new SpawnTemplateResult
				{
					result = result,
					templateData = templateData,
					spawnedTools = spawnedTools
				});
			}
		}

		public Promise<SpawnTemplateResult> MasterSpawnTemplate(SpawnableTemplateData spawnableTemplateData, int cost, bool assignNewIds, SpawnTransformData? spawnTransformData, bool verboseLogging)
		{
			if (!CanAffordResourceCost(cost))
			{
				return new CompletedPromise<SpawnTemplateResult>(new SpawnTemplateResult
				{
					result = CreationResult.Failure_InsufficientResources
				});
			}
			Promise<SpawnTemplateResult> promise = new Promise<SpawnTemplateResult>();
			SingletonMonoBehaviour<Scheduler>.Instance.Run(this, SpawnTemplateCoroutine(spawnableTemplateData, verboseLogging, promise, assignNewIds, spawnTransformData));
			return promise;
		}

		private IEnumerator<ISchedule> SpawnTemplateCoroutine(SpawnableTemplateData spawnableTemplateData, bool verboseLogging, Promise<SpawnTemplateResult> promise, bool assignNewIds, SpawnTransformData? spawnTransformData = null)
		{
			RoomPersistenceVersion roomDataVersion = (RoomPersistenceVersion)spawnableTemplateData.RoomDataVersion;
			if (verboseLogging)
			{
				UnityEngine.Debug.LogFormat("Deserializing spawnable template data blob version {0}, with {1} persisted views.", roomDataVersion, spawnableTemplateData.PersistenceViews.Count);
			}
			Dictionary<int, int> nodeIdMappings = new Dictionary<int, int>();
			try
			{
				if (spawnableTemplateData.CircuitData != null && !spawnableTemplateData.CircuitData.IsEmpty)
				{
					CircuitNodeGraphCollectionData circuitNodeGraphCollectionData = CircuitNodeGraphCollectionData.Parser.ParseFrom(spawnableTemplateData.CircuitData);
					foreach (CircuitNodeGraphData graph in circuitNodeGraphCollectionData.Graphs)
					{
						Dictionary<int, int> nodeIdMappings2 = null;
						NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.InitializeNewGraph(graph, out nodeIdMappings2);
						foreach (KeyValuePair<int, int> item7 in nodeIdMappings2)
						{
							nodeIdMappings.Add(item7.Key, item7.Value);
						}
					}
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				promise.Error("Error loading room. Circuit data is corrupt!");
				yield break;
			}
			Dictionary<Guid, ConnectableNodeData> parentlessNodeMap = INSTANTANEOUS_CONNECTABLE_NODE_MAP;
			parentlessNodeMap.Clear();
			if (spawnableTemplateData.ConnectableGraphData != null && spawnableTemplateData.ConnectableGraphData.RootNode != null)
			{
				foreach (ConnectableNodeData child in spawnableTemplateData.ConnectableGraphData.RootNode.Children)
				{
					parentlessNodeMap.Add(RecRoom.Protobuf.ByteStringExtensions.ToGuid(child.PersistenceID), child);
				}
			}
			Dictionary<Guid, Guid> pvIdMap = INSTANTANEOUS_PERSISTENCE_VIEW_ID_MAP;
			pvIdMap.Clear();
			INSTANTANEOUS_INVENTION_INSTANCE_MAP.Clear();
			List<PhotonNetwork.InstantiateRequestEx> instantiationRequests = new List<PhotonNetwork.InstantiateRequestEx>(spawnableTemplateData.PersistenceViews.Count);
			List<PersistenceViewData> requestData = new List<PersistenceViewData>(spawnableTemplateData.PersistenceViews.Count);
			try
			{
				for (int i = 0; i < spawnableTemplateData.PersistenceViews.Count; i++)
				{
					PersistenceViewData persistenceViewData = spawnableTemplateData.PersistenceViews[i];
					Guid key = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceViewData.Id);
					if (assignNewIds)
					{
						PersistenceView.SetNewIdsForData(persistenceViewData, pvIdMap);
						AssignNewInventionInstanceIds(persistenceViewData, INSTANTANEOUS_INVENTION_INSTANCE_MAP);
					}
					Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceViewData.Id);
					if (PersistenceView.AllViews.ContainsKey(guid))
					{
						UnityEngine.Debug.LogWarningFormat("Data found with GUID {0} matching an object already in the scene: {1}\nLikely this object was not in a valid state when trying to destroy existing views. Skipping deserialization...", guid, PersistenceView.AllViews[guid]);
						continue;
					}
					try
					{
						CircuitNodePersistence.CheckForRequiredCircuitNodeId(persistenceViewData, nodeIdMappings, roomDataVersion);
					}
					catch (Exception exception2)
					{
						UnityEngine.Debug.LogException(exception2);
						promise.Error("Error loading room. Circuit Item was corrupt!");
						yield break;
					}
					Vector3 vector = persistenceViewData.Transform.Position.ToVector3().ValueOrZeroIfBogus();
					Quaternion quaternion = Quaternion.Euler(persistenceViewData.Transform.Rotation.ToVector3().ValueOrZeroIfBogus());
					float num = persistenceViewData.Transform.Scale;
					if (spawnTransformData.HasValue)
					{
						SpawnTransformData valueOrDefault = spawnTransformData.GetValueOrDefault();
						Matrix4x4 matrix4x = Matrix4x4.TRS(valueOrDefault.position, valueOrDefault.rotation, valueOrDefault.scale * Vector3.one);
						Matrix4x4 matrix4x2 = Matrix4x4.TRS(vector, quaternion, num * Vector3.one);
						Matrix4x4 matrix4x3 = matrix4x * matrix4x2;
						vector = matrix4x3.GetPosition();
						quaternion = matrix4x3.GetRotation();
						num = matrix4x3.GetScale().x;
					}
					if (parentlessNodeMap.ContainsKey(key))
					{
						ConnectableNodeData connectableNodeData = parentlessNodeMap[key];
						connectableNodeData.PositionRelativeToParent = vector.ToVector3Data();
						connectableNodeData.RotationRelativeToParent = quaternion.ToVector3Data();
					}
					PhotonNetwork.InstantiateRequestEx instantiateRequestEx = NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.ConstructInstantiateRequest(persistenceViewData, guid, vector, quaternion, num, roomDataVersion, verboseLogging, nodeIdMappings);
					if (instantiateRequestEx != null)
					{
						instantiationRequests.Add(instantiateRequestEx);
						requestData.Add(persistenceViewData);
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("Failed to construct instantiation request for object with guid {0}.", guid);
					}
				}
			}
			catch (Exception exception3)
			{
				UnityEngine.Debug.LogException(exception3);
				promise.Error("Error preparing to instantiate persistable group objects.");
				yield break;
			}
			GameObject[] instantiatedObjects;
			try
			{
				instantiatedObjects = PhotonNetwork.BulkInstantiateSceneObjectsEx(instantiationRequests);
			}
			catch (Exception exception4)
			{
				UnityEngine.Debug.LogException(exception4);
				promise.Error("Error instantiating spawnable template objects.");
				yield break;
			}
			List<Tuple<PersistenceView, PersistenceViewData>> viewDataPairs = new List<Tuple<PersistenceView, PersistenceViewData>>();
			try
			{
				for (int j = 0; j < instantiatedObjects.Length; j++)
				{
					PersistenceViewData persistenceViewData2 = requestData[j];
					Guid guid2 = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceViewData2.Id);
					if (instantiatedObjects[j] == null)
					{
						UnityEngine.Debug.LogErrorFormat("Null object instantiated for Persistence View with guid {0}.", guid2);
						continue;
					}
					PersistenceView componentInChildren = instantiatedObjects[j].GetComponentInChildren<PersistenceView>();
					if (componentInChildren == null)
					{
						UnityEngine.Debug.LogErrorFormat("Unable to create or locate Persistence View on object {0} with guid {1}.", instantiatedObjects[j], guid2);
					}
					else if (componentInChildren.IsChildView)
					{
						UnityEngine.Debug.LogErrorFormat("Erroneously located child Persistence View {0} on object {1} with guid {2}. Should have located its parent view {3} instead.", componentInChildren, instantiatedObjects[j], guid2, componentInChildren.ParentView);
					}
					else
					{
						componentInChildren.gameObject.SetActive(value: true);
						componentInChildren.InitializeDeserialization(persistenceViewData2, checkTransform: false);
						viewDataPairs.Add(new Tuple<PersistenceView, PersistenceViewData>(componentInChildren, persistenceViewData2));
					}
				}
			}
			catch (Exception exception5)
			{
				UnityEngine.Debug.LogException(exception5);
				promise.Error("Error initializing spawnable template objects.");
				yield break;
			}
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item8 in viewDataPairs)
				{
					PersistenceView item = item8.Item1;
					PersistenceViewData item2 = item8.Item2;
					if (item != null)
					{
						item.PreDeserialize(roomDataVersion, item2, pvIdMap);
					}
				}
			}
			catch (Exception exception6)
			{
				UnityEngine.Debug.LogException(exception6);
				promise.Error("Error pre-deserializing invention objects.");
				yield break;
			}
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item9 in viewDataPairs)
				{
					PersistenceView item3 = item9.Item1;
					PersistenceViewData item4 = item9.Item2;
					if (item3 != null)
					{
						PersistableDeserializeParams deserializeParams = new PersistableDeserializeParams
						{
							version = roomDataVersion,
							viewData = item4,
							nodeIdMapping = nodeIdMappings,
							persistenceViewIdMappings = pvIdMap,
							assignNewIds = assignNewIds,
							isRuntimeCreated = true
						};
						item3.Deserialize(deserializeParams);
					}
				}
			}
			catch (Exception exception7)
			{
				UnityEngine.Debug.LogException(exception7);
				promise.Error("Error deserializing invention objects.");
				yield break;
			}
			SynchronizedField.SendPendingRoomUpdates();
			try
			{
				ConnectableGraphData connectableGraphData = spawnableTemplateData.ConnectableGraphData;
				if (connectableGraphData != null)
				{
					NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.MasterDeserializeConnectableSubgraph(connectableGraphData, pvIdMap);
				}
			}
			catch (Exception exception8)
			{
				UnityEngine.Debug.LogException(exception8);
				promise.Error("Error deserializing connectable subgraph.");
				yield break;
			}
			yield return Schedule.NextFrame;
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item10 in viewDataPairs)
				{
					PersistenceView item5 = item10.Item1;
					if (item5 != null)
					{
						item5.PostDeserialize(pvIdMap);
					}
				}
			}
			catch (Exception exception9)
			{
				UnityEngine.Debug.LogException(exception9);
				promise.Error("Error post-deserializing invention objects.");
				yield break;
			}
			List<Tool> toolsList = new List<Tool>();
			foreach (Tuple<PersistenceView, PersistenceViewData> item11 in viewDataPairs)
			{
				PersistenceView item6 = item11.Item1;
				Tool component = item6.GetComponent<Tool>();
				if (component != null)
				{
					toolsList.Add(component);
				}
			}
			SpawnTemplateResult result = new SpawnTemplateResult
			{
				spawnedTools = toolsList,
				templateData = spawnableTemplateData
			};
			promise.Complete(result);
		}

		private SpawnableTemplateData InitializeSpawnableTemplateDataBlob()
		{
			SpawnableTemplateData spawnableTemplateData = new SpawnableTemplateData();
			spawnableTemplateData.RoomDataVersion = 14;
			return spawnableTemplateData;
		}

		private static void AssignNewInventionInstanceIds(PersistenceViewData data, Dictionary<Guid, Guid> oldIdToNewIdMap)
		{
			if (data == null)
			{
				return;
			}
			if (data.CreationObjectData != null && data.CreationObjectData.InventionPieceData != null)
			{
				Guid key = RecRoom.Protobuf.ByteStringExtensions.ToGuid(data.CreationObjectData.InventionPieceData.InstanceId);
				if (!oldIdToNewIdMap.TryGetValue(key, out var value))
				{
					value = Guid.NewGuid();
					oldIdToNewIdMap.Add(key, value);
				}
				data.CreationObjectData.InventionPieceData.InstanceId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(value);
			}
			foreach (ChildPersistenceViewData childView in data.ChildViews)
			{
				AssignNewInventionInstanceIds(childView.Data, oldIdToNewIdMap);
			}
		}

		public IPromise<SpawnTemplateResult> RequestCloneObjects(List<CreationObject> sourceObjects)
		{
			if (pendingLocalCloneRequest != null && UnityEngine.Time.realtimeSinceStartup - lastCloneRequestTime < 5f)
			{
				return new CompletedPromise<SpawnTemplateResult>(new SpawnTemplateResult
				{
					result = CreationResult.Failure_Generic,
					errorCulprit = null
				});
			}
			Promise<SpawnTemplateResult> promise = (pendingLocalCloneRequest = new Promise<SpawnTemplateResult>());
			lastCloneRequestTime = UnityEngine.Time.realtimeSinceStartup;
			promise.Finally(delegate
			{
				pendingLocalCloneRequest = null;
			});
			CreationResult creationResult = CreationResult.Success;
			PhotonPlayer errorCulprit = null;
			List<Tool> iNSTANTENOUS_TOOL_LIST = INSTANTENOUS_TOOL_LIST;
			iNSTANTENOUS_TOOL_LIST.Clear();
			int num = 0;
			foreach (CreationObject sourceObject in sourceObjects)
			{
				if (sourceObject.IsLocked && !sourceObject.LocalPlayerHasLock)
				{
					errorCulprit = PhotonPlayer.Find(sourceObject.LockedByPhotonPlayer);
					creationResult = CreationResult.Failure_LockedByOther;
					break;
				}
				Tool tool = sourceObject.Tool;
				if (tool.IsFrozen)
				{
					creationResult = CreationResult.Failure_ToolFrozen;
					break;
				}
				num += sourceObject.SandboxResourceCost;
				iNSTANTENOUS_TOOL_LIST.Add(tool);
			}
			if (!CanAffordResourceCost(num))
			{
				creationResult = CreationResult.Failure_InsufficientResources;
			}
			if (creationResult == CreationResult.Success)
			{
				base.photonView.RpcMaster(RpcRequestMasterCloneSpawnable, iNSTANTENOUS_TOOL_LIST);
			}
			else
			{
				promise.Complete(new SpawnTemplateResult
				{
					result = creationResult,
					errorCulprit = errorCulprit
				});
			}
			return promise;
		}

		[PunRPC]
		private void RpcRequestMasterCloneSpawnable(List<Tool> toolsToClone, PhotonMessageInfo messageInfo)
		{
			PhotonPlayer requestingPlayer = messageInfo.sender;
			if (!PhotonNetwork.isMasterClient || requestingPlayer == null || toolsToClone == null)
			{
				return;
			}
			List<Tool> clonedTools = null;
			SpawnableTemplateData templateData = null;
			CreationResult result = CreationResult.Success;
			MasterCloneObjects(toolsToClone).Then(delegate(SpawnTemplateResult cloneResult)
			{
				result = cloneResult.result;
				clonedTools = cloneResult.spawnedTools;
				templateData = cloneResult.templateData;
			}).Error(delegate(string e)
			{
				UnityEngine.Debug.LogError($"Error while cloning spawnables: {e}");
				result = CreationResult.Failure_Generic;
			}).Finally(delegate
			{
				if (clonedTools != null)
				{
					foreach (Tool item in clonedTools)
					{
						item.photonView.TransferOwnership(requestingPlayer);
					}
					SynchronizedField.SendPendingRoomUpdates();
				}
				base.photonView.RpcPlayer(requestingPlayer, RpcOnCloneResult, clonedTools, templateData, result);
			});
		}

		[PunRPC]
		private void RpcOnCloneResult(List<Tool> clonedTools, SpawnableTemplateData templateData, CreationResult result)
		{
			if (pendingLocalCloneRequest != null)
			{
				pendingLocalCloneRequest.Complete(new SpawnTemplateResult
				{
					result = result,
					templateData = templateData,
					spawnedTools = clonedTools
				});
			}
		}

		public IPromise<SpawnTemplateResult> MasterCloneObjects(IReadOnlyList<Tool> toolsToClone)
		{
			Promise<SpawnTemplateResult> promise = new Promise<SpawnTemplateResult>();
			SingletonMonoBehaviour<Scheduler>.Instance.Run(MasterCloneObjectsCoroutine(toolsToClone, promise));
			return promise;
		}

		private IEnumerator<ISchedule> MasterCloneObjectsCoroutine(IReadOnlyList<Tool> toolsToClone, Promise<SpawnTemplateResult> clonePromise)
		{
			int cost = CreationHelper.CalculateObjectCosts(toolsToClone);
			if (!CanAffordResourceCost(cost))
			{
				clonePromise.Complete(new SpawnTemplateResult
				{
					result = CreationResult.Failure_InsufficientResources
				});
			}
			INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Clear();
			foreach (Tool item in toolsToClone)
			{
				INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.Add(item.PersistenceView);
			}
			SpawnableTemplateData dataBlob = null;
			string serializationError = null;
			PersistenceView[] persistenceViewsCopy = INSTANTANEOUS_PERSISTENCE_VIEWS_LIST.ToArray();
			IPromise<SerializeTemplateResult> serializePromise = SerializeSpawnableTemplate(persistenceViewsCopy, verboseLogging: true).Then(delegate(SerializeTemplateResult serializationResult)
			{
				dataBlob = serializationResult.spawnableTemplateData;
			}).Error(delegate(string e)
			{
				serializationError = e;
			});
			yield return Schedule.Until(() => serializePromise.IsCompleted);
			if (dataBlob == null)
			{
				clonePromise.Error($"Error serializing data to clone. {serializationError ?? string.Empty}");
			}
			else
			{
				yield return SingletonMonoBehaviour<Scheduler>.Instance.Run(this, SpawnTemplateCoroutine(dataBlob, verboseLogging: true, clonePromise, assignNewIds: true));
			}
		}

		public PhotonNetwork.InstantiateRequestEx ConstructSpawnableToolInstantiationRequest(Guid prefabGuid, CreationObjectData creationObjectData, Vector3 position, Quaternion rotation, float scale, int circuitNodeId)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			if (circuitNodeId != 0)
			{
				dictionary["CO_CN"] = circuitNodeId;
			}
			string spawnableToolPrefabName = SpawnableToolSettings.GetSpawnableToolPrefabName(prefabGuid);
			if (!string.IsNullOrEmpty(spawnableToolPrefabName))
			{
				Color? colorOverride = null;
				GameTeam? teamOverride = null;
				if (creationObjectData != null)
				{
					if (creationObjectData.ColorOverride != null)
					{
						colorOverride = creationObjectData.ColorOverride.ToColor();
					}
					teamOverride = (GameTeam)creationObjectData.TeamOverride;
				}
				return ConstructInstantiationRequest(spawnableToolPrefabName, position, rotation, scale, colorOverride, teamOverride, dictionary);
			}
			UnityEngine.Debug.LogErrorFormat("Unable to construct instantiation request for object with prefab ID {0}", prefabGuid);
			return null;
		}

		public GameObject SpawnToolImposter(SpawnableToolType toolType, Transform parent)
		{
			GameObject result = VisualImposter.SpawnImposter(toolType, parent, null, preserveColliders: true).gameObject;
			result.SetLayerRecursively(Layers.UI);
			return result;
		}

		public IPromise<Tool> RequestSpawnTool(SpawnableToolType toolType, Vector3 position, Quaternion rotation, float scale)
		{
			return RequestSpawnTool(toolType, position, rotation, scale, Guid.Empty);
		}

		public IPromise<Tool> RequestSpawnTool(SpawnableToolType toolType, Vector3 position, Quaternion rotation, float scale, Guid id)
		{
			if (pendingLocalSpawnRequest != null && UnityEngine.Time.realtimeSinceStartup - lastSpawnEquipmentTime < 1f)
			{
				return new ErroredPromise<Tool>("Cannot request to spawn tool while another request is pending.");
			}
			if (!CanAffordTool(toolType))
			{
				return new ErroredPromise<Tool>($"Cannot afford spawn tool {toolType}");
			}
			Promise<Tool> result = (pendingLocalSpawnRequest = new Promise<Tool>());
			pendingLocalSpawnRequest.Then(delegate(Tool tool)
			{
				if (tool != null && SpawnableToolSettings.GetSpawnableToolGroup(tool.SpawnableToolType) == SpawnableToolCategoryConfig.Group.GAGDETS)
				{
					CircuitVisibilityBehaviour.HideForLocalPlayer = false;
				}
			}).Finally(delegate
			{
				pendingLocalSpawnRequest = null;
			});
			lastSpawnEquipmentTime = UnityEngine.Time.realtimeSinceStartup;
			base.photonView.RpcMaster(RpcMasterRequestSpawnTool, toolType, position, rotation, scale, id);
			return result;
		}

		[PunRPC]
		private void RpcMasterRequestSpawnTool(SpawnableToolType toolType, Vector3 position, Quaternion rotation, float scale, Guid id, PhotonMessageInfo messageInfo)
		{
			if (PhotonNetwork.isMasterClient)
			{
				Tool tool = MasterSpawnTool(toolType, position, rotation, scale, id);
				if (tool != null)
				{
					tool.photonView.TransferOwnership(messageInfo.sender);
					SynchronizedField.SendPendingRoomUpdates();
				}
				base.photonView.RpcPlayer(messageInfo.sender, RpcOnRequestEquipmentReceived, tool);
			}
		}

		[PunRPC]
		private void RpcOnRequestEquipmentReceived(Tool newTool)
		{
			if (pendingLocalSpawnRequest != null)
			{
				if (newTool != null)
				{
					pendingLocalSpawnRequest.Complete(newTool);
				}
				else
				{
					pendingLocalSpawnRequest.Error("Master failed to spawn requested tool");
				}
			}
		}

		public Tool MasterSpawnTool(SpawnableToolType toolType, Vector3 position, Quaternion rotation, float scale)
		{
			return MasterSpawnTool(toolType, position, rotation, scale, Guid.Empty);
		}

		public Tool MasterSpawnTool(SpawnableToolType toolType, Vector3 position, Quaternion rotation, float scale, Guid id)
		{
			if (PhotonNetwork.isMasterClient && CanAffordTool(toolType))
			{
				if (id != Guid.Empty && PersistenceView.AllViews.ContainsKey(id))
				{
					UnityEngine.Debug.LogError($"Trying to spawn {toolType} with ID {id}, but that ID already exists on object {PersistenceView.AllViews[id]}");
					return null;
				}
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("CO_STT", (int)toolType);
				Dictionary<string, object> dictionary2 = dictionary;
				SpawnableToolConfig.Config spawnableToolConfig = SpawnableToolSettings.GetSpawnableToolConfig(toolType);
				if (spawnableToolConfig == null)
				{
					return null;
				}
				if (spawnableToolConfig.CircuitNodeType.TryGetCircuitNodeType(out var _, out var t))
				{
					int num = CircuitNode.NewNodeId();
					dictionary2["CO_CN"] = num;
					NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.RequestMasterInstantiateNode(t, num);
				}
				string spawnableToolPrefabName = SpawnableToolSettings.GetSpawnableToolPrefabName(toolType);
				Color? colorOverride = SpawnableToolSettings.GetSpawnableToolColorOverride(toolType);
				if (colorOverride.HasValue && colorOverride.GetValueOrDefault() == Color.clear)
				{
					colorOverride = null;
				}
				GameTeam? gameTeam = SpawnableToolSettings.GetSpawnableToolTeamOverride(toolType);
				if (gameTeam == GameTeam.ANY)
				{
					gameTeam = null;
				}
				PhotonNetwork.InstantiateRequestEx request = ConstructInstantiationRequest(spawnableToolPrefabName, position, rotation, scale, colorOverride, gameTeam, dictionary2);
				return MasterSpawnToolInternal(request, id);
			}
			return null;
		}

		private PhotonNetwork.InstantiateRequestEx ConstructInstantiationRequest(string prefabName, Vector3 position, Quaternion rotation, float scale, Color? colorOverride, GameTeam? teamOverride, Dictionary<string, object> additionalInstantiationData)
		{
			Dictionary<string, object> dictionary = additionalInstantiationData;
			if (dictionary == null)
			{
				dictionary = new Dictionary<string, object>();
			}
			if (colorOverride.HasValue)
			{
				dictionary["CRM_CO"] = colorOverride.Value;
			}
			if (teamOverride.HasValue)
			{
				dictionary["CRM_TO"] = teamOverride.Value;
			}
			PhotonNetwork.InstantiateRequestEx instantiateRequestEx = new PhotonNetwork.InstantiateRequestEx();
			instantiateRequestEx.PrefabName = prefabName;
			instantiateRequestEx.Position = position;
			instantiateRequestEx.Rotation = rotation;
			instantiateRequestEx.Scale = scale;
			instantiateRequestEx.InstantiatorPhotonViewId = base.photonView.viewID;
			instantiateRequestEx.InstantiationParameters = dictionary;
			return instantiateRequestEx;
		}

		private Tool MasterSpawnToolInternal(PhotonNetwork.InstantiateRequestEx request, Guid id)
		{
			if (PhotonNetwork.isMasterClient)
			{
				Tool tool = null;
				GameObject gameObject = PhotonNetwork.InstantiateSceneObjectEx(request.PrefabName, request.Position, request.Rotation, request.Scale, 0, request.InstantiatorPhotonViewId, request.InstantiationParameters);
				if (gameObject != null)
				{
					tool = gameObject.GetComponent<Tool>();
					tool.SupportsAnimateIn = false;
					if (id != Guid.Empty)
					{
						tool.PersistenceView.Id = id;
					}
					else
					{
						tool.PersistenceView.MasterEnsureValidID();
					}
				}
				return tool;
			}
			return null;
		}

		public IPromise<InventionUpdateResult> SaveNewInvention(IEnumerable<CreationObject> sourceObjects, string name, string description, AltTextureSet image)
		{
			return SaveInvention(InventionRequestType.SaveNew, sourceObjects, name, description, image, -1L);
		}

		public IPromise<InventionUpdateResult> SaveNewVersionOfInvention(IEnumerable<CreationObject> sourceObjects, long inventionId)
		{
			return SaveInvention(InventionRequestType.SaveVersion, sourceObjects, null, null, null, inventionId);
		}

		private IPromise<InventionUpdateResult> SaveInvention(InventionRequestType saveType, IEnumerable<CreationObject> sourceObjects, string name, string description, AltTextureSet image, long inventionId)
		{
			if (pendingLocalUpdateInventionRequest != null && UnityEngine.Time.realtimeSinceStartup - lastUpdateInventionTime < 1f)
			{
				return new ErroredPromise<InventionUpdateResult>("Error");
			}
			string text = CheckObjectsCanBeSavedAsInvention(sourceObjects, inventionId);
			if (!string.IsNullOrEmpty(text))
			{
				return new ErroredPromise<InventionUpdateResult>(text);
			}
			Promise<InventionUpdateResult> result = (pendingLocalUpdateInventionRequest = new Promise<InventionUpdateResult>());
			requestedName = name;
			requestedDescription = description;
			requestedInventionId = inventionId;
			requestedImage = image;
			requestType = saveType;
			List<CreationObject> sourceObjectsAsList = sourceObjects.ToList();
			pendingLocalUpdateInventionRequest.Then(delegate(InventionUpdateResult requestResult)
			{
				if (requestResult.result == CreationResult.Success)
				{
					Guid arg = Guid.NewGuid();
					base.photonView.RpcAll(AddInventionPieceTrackingToObjects, arg, requestResult.inventionId, requestResult.inventionVersion, sourceObjectsAsList);
				}
			}).Finally(delegate
			{
				pendingLocalUpdateInventionRequest = null;
			});
			lastUpdateInventionTime = UnityEngine.Time.realtimeSinceStartup;
			base.photonView.RpcMaster(RpcMasterRequestSerializeNewInvention, sourceObjectsAsList);
			return result;
		}

		public string CheckObjectsCanBeSavedAsInvention(IEnumerable<CreationObject> sourceObjects, long inventionIdToIgnore)
		{
			if (sourceObjects == null || sourceObjects.Count() == 0)
			{
				return "No objects selected";
			}
			if (!InventionSerializer.IsValidInventionSize(sourceObjects))
			{
				return "Source objects extents are too large or are invalid";
			}
			requestedInstantiateCost = CreationHelper.CalculateObjectCosts(sourceObjects);
			if (!InventionSerializer.IsValidInventionCost(sourceObjects, requestedInstantiateCost))
			{
				return "Source objects total cost is above the resource limit";
			}
			if (AreAnyObjectsPartOfInvention(sourceObjects, inventionIdToIgnore))
			{
				UnityEngine.Debug.Log("Saving invention that includes existing invention pieces - this will break the link to the old invention and establish link to new invention");
			}
			return null;
		}

		private bool AreAnyObjectsPartOfInvention(IEnumerable<CreationObject> sourceObjects, long ignoreInventionId = -1L)
		{
			foreach (CreationObject sourceObject in sourceObjects)
			{
				if (sourceObject.InventionPiece.IsTrackingInvention && sourceObject.InventionPiece.InventionId != ignoreInventionId)
				{
					return true;
				}
			}
			return false;
		}

		[PunRPC]
		private void AddInventionPieceTrackingToObjects(Guid newInstanceId, long inventionId, int versionNumber, List<CreationObject> inventionObjects)
		{
			foreach (CreationObject inventionObject in inventionObjects)
			{
				if (inventionObject.hasAuthority)
				{
					inventionObject.InventionPiece.AuthorityInitializePiece(newInstanceId, inventionId, versionNumber);
				}
			}
		}

		[PunRPC]
		private void RpcMasterRequestSerializeNewInvention(List<CreationObject> sourceObjects, PhotonMessageInfo messageInfo)
		{
			PhotonPlayer requestingPlayer = messageInfo.sender;
			if (!PhotonNetwork.isMasterClient || requestingPlayer == null)
			{
				return;
			}
			InventionSerializer.MasterSaveNewInvention(sourceObjects, requestingPlayer).Then(delegate(InventionSerializer.SaveInventionResult saveInventionResult)
			{
				if (saveInventionResult.inventionDatablobBytes == null)
				{
					UnityEngine.Debug.LogErrorFormat("Unable to save selection as invention instance.");
				}
				else
				{
					base.photonView.RpcPlayer(requestingPlayer, RpcOnSerializeInventionResult, saveInventionResult.inventionDatablobBytes, saveInventionResult.persistedImageNames.ToArray(), saveInventionResult.persistedDataBlobNames.ToArray());
				}
			});
		}

		[PunRPC]
		private void RpcOnSerializeInventionResult(byte[] inventionBytes, string[] imageList, string[] datablobList)
		{
			SpawnableTemplateData inventionDataBlob = SpawnableTemplateData.Parser.ParseFrom(inventionBytes);
			if (inventionDataBlob == null)
			{
				if (pendingLocalUpdateInventionRequest != null)
				{
					pendingLocalUpdateInventionRequest.Complete(InventionUpdateResult.FailureGeneric);
				}
			}
			else if (requestType == InventionRequestType.SaveNew)
			{
				Images.UploadSavedImage(requestedImage, Images.SavedImageType.InventionThumbnail).Error(delegate(string errMsg)
				{
					UnityEngine.Debug.LogError("Failed to upload invention image: " + errMsg);
					if (pendingLocalUpdateInventionRequest != null)
					{
						pendingLocalUpdateInventionRequest.Error(errMsg);
					}
				}).Then(delegate(string imageName)
				{
					InventionSerializer.UploadNewInventionDataBlob(inventionDataBlob, requestedName, requestedDescription, imageName, requestedInstantiateCost, imageList, datablobList).Then(delegate(InventionResponse inventionResponse)
					{
						if (inventionResponse.Invention != null)
						{
							if (pendingLocalUpdateInventionRequest != null)
							{
								pendingLocalUpdateInventionRequest.Complete(new InventionUpdateResult
								{
									result = CreationResult.Success,
									serverResult = InventionResult.Success,
									inventionId = inventionResponse.Invention.InventionId,
									inventionVersion = inventionResponse.Invention.CurrentVersionNumber
								});
							}
						}
						else if (pendingLocalUpdateInventionRequest != null)
						{
							pendingLocalUpdateInventionRequest.Complete(InventionUpdateResult.ServerFailure(inventionResponse.Status));
						}
					}).Error(delegate(string error)
					{
						if (pendingLocalUpdateInventionRequest != null)
						{
							pendingLocalUpdateInventionRequest.Error(string.Format("Error uploading invention data: {0}", error ?? "Unknown error"));
						}
					});
				});
			}
			else
			{
				if (requestType != InventionRequestType.SaveVersion)
				{
					return;
				}
				InventionSerializer.UploadNewInventionVersion(inventionDataBlob, requestedInventionId, requestedInstantiateCost, imageList, datablobList).Then(delegate(InventionResponse inventionResponse)
				{
					if (inventionResponse.Invention != null)
					{
						if (pendingLocalUpdateInventionRequest != null)
						{
							pendingLocalUpdateInventionRequest.Complete(new InventionUpdateResult
							{
								result = CreationResult.Success,
								serverResult = InventionResult.Success,
								inventionId = inventionResponse.Invention.InventionId,
								inventionVersion = inventionResponse.Invention.CurrentVersionNumber
							});
						}
					}
					else if (pendingLocalUpdateInventionRequest != null)
					{
						pendingLocalUpdateInventionRequest.Complete(InventionUpdateResult.ServerFailure(inventionResponse.Status));
					}
				}).Error(delegate(string error)
				{
					if (pendingLocalUpdateInventionRequest != null)
					{
						pendingLocalUpdateInventionRequest.Error(string.Format("Error uploading invention data: {0}", error ?? "Unknown error"));
					}
				});
			}
		}

		public IPromise<SpawnTemplateResult> RequestSpawnInventionInstance(Invention invention, Vector3 position, Quaternion rotation, float scale)
		{
			if (pendingLocalSpawnInventionInstanceRequest != null && UnityEngine.Time.realtimeSinceStartup - lastSpawnInventionInstanceTime < 1f)
			{
				return new ErroredPromise<SpawnTemplateResult>("Attempting to spawn an invention while another request is pending");
			}
			Promise<SpawnTemplateResult> localPromise = new Promise<SpawnTemplateResult>();
			pendingLocalSpawnInventionInstanceRequest = localPromise;
			pendingLocalSpawnInventionInstanceRequest.Then((Action<SpawnTemplateResult>)delegate
			{
			}).Finally(delegate
			{
				pendingLocalSpawnInventionInstanceRequest = null;
			});
			lastSpawnInventionInstanceTime = UnityEngine.Time.realtimeSinceStartup;
			RecNet.Inventions.GetInventionVersion(invention.InventionId, invention.CurrentVersionNumber).Then(delegate(InventionVersion versionData)
			{
				if (string.IsNullOrEmpty(versionData.BlobName))
				{
					localPromise.Error("Unable to access invention blob");
				}
				else if (!CanAffordResourceCost(versionData.InstantiationCost))
				{
					localPromise.Complete(new SpawnTemplateResult
					{
						result = CreationResult.Failure_InsufficientResources
					});
				}
				else
				{
					base.photonView.RpcMaster(RpcMasterRequestSpawnInventionInstance, invention.InventionId, invention.CurrentVersionNumber, versionData.BlobName, position, rotation, scale);
				}
			}).Error(delegate(string errMsg)
			{
				localPromise.Error(errMsg);
			});
			return localPromise;
		}

		[PunRPC]
		private void RpcMasterRequestSpawnInventionInstance(long inventionId, int versionNum, string dataBlobName, Vector3 position, Quaternion rotation, float scale, PhotonMessageInfo messageInfo)
		{
			PhotonPlayer requestingPlayer = messageInfo.sender;
			if (!PhotonNetwork.isMasterClient || requestingPlayer == null)
			{
				return;
			}
			CreationResult result = CreationResult.Success;
			InventionSerializer.MasterSpawnInventionInstance(inventionId, versionNum, dataBlobName, position, rotation, scale).Then(delegate(List<Tool> instanceTools)
			{
				if (instanceTools == null)
				{
					result = CreationResult.Failure_Generic;
					UnityEngine.Debug.LogErrorFormat("Unable to instantiate invention instance with Photon View Id {0}", base.photonView.viewID);
				}
				else
				{
					foreach (Tool instanceTool in instanceTools)
					{
						instanceTool.photonView.TransferOwnership(requestingPlayer);
					}
					SynchronizedField.SendPendingRoomUpdates();
					base.photonView.RpcPlayer(requestingPlayer, RpcOnSpawnInventionInstanceResult, instanceTools, result);
				}
			});
		}

		[PunRPC]
		private void RpcOnSpawnInventionInstanceResult(List<Tool> instanceTools, CreationResult result)
		{
			if (result == CreationResult.Success)
			{
				AnalyticsHelper.AddCustomStatsCounter("inventionInstantiated", 1);
				AnalyticsHelper.IgnoreCounterSamplingOnNextStatSend();
			}
			if (pendingLocalSpawnInventionInstanceRequest != null)
			{
				pendingLocalSpawnInventionInstanceRequest.Complete(new SpawnTemplateResult
				{
					result = result,
					spawnedTools = instanceTools
				});
			}
		}

		public IPromise<Vector3> GetInventionExtents(Invention invention)
		{
			Promise<Vector3> extentsPromise = new Promise<Vector3>();
			InventionSerializer.GetInventionDataBlob(invention.InventionId, invention.CurrentVersionNumber).Then(delegate(SpawnableTemplateData data)
			{
				extentsPromise.Complete(data.Extents.ToVector3());
			}).Error(delegate
			{
				extentsPromise.Error("Error getting invention extents");
			});
			return extentsPromise;
		}

		public List<CreationObject> GetAllObjectsInInvention(Guid inventionInstanceId)
		{
			List<CreationObject> list = new List<CreationObject>();
			foreach (CreationObject spawnedObject in SpawnedObjects)
			{
				if (spawnedObject.InventionPiece.IsTrackingInvention && spawnedObject.InventionPiece.InstanceId == inventionInstanceId)
				{
					list.Add(spawnedObject);
				}
			}
			return list;
		}

		static CreationManager()
		{
			CreationManager.ActiveSandboxResourcesChangedEvent = null;
			CreationManager.AllSpawnedObjectsDestroyedEvent = null;
			spawnedObjects = new List<CreationObject>();
			InventionSerializer = new InventionSerializer();
			_cachedActiveResourceCost = 0;
			activeResourceCostDirty = true;
		}
	}
