		protected override void Awake()
		{
			base.Awake();
			_lockedByPhotonPlayer = new SynchronizedField<int>(this, "COL", PhotonPlayer.Invalid, SetterPermissionMode.ANYONE, OnLockedPhotonPlayerChanged);
			_dynamicCollisionEnabled = new SynchronizedField<bool>(this, "COD", defaultValue: true, SetterPermissionMode.ANYONE, UpdateCollisionLayer);
			_isFrozen = new SynchronizedField<bool>(this, "COF", defaultValue: false, SetterPermissionMode.MASTER_OR_AUTHORITY, OnIsFrozenChanged);
			InventionPiece = new InventionPiece(this);
			ParseInstantiationData();
			CreationManager.AddCreationObject(this);
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		}

		private void Start()
		{
			InitializeFrozen();
			OnLockedPhotonPlayerChanged();
			UpdateCollisionLayer();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CreationManager.RemoveCreationObject(this);
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		}

		private void ParseInstantiationData()
		{
			bool flag = Tool.InstantiationParameters != null;
			EquipmentType = SpawnableToolType.INVALID;
			if (flag)
			{
				if (Tool.InstantiationParameters.TryGetValue("CO_STT", out var value))
				{
					EquipmentType = (SpawnableToolType)value;
				}
				Color color = Color.clear;
				if (CreationManager.TryGetColorOverrideFromInstantiationData(Tool.InstantiationParameters, out color))
				{
					ColorOverride = color;
				}
				GameTeam team = GameTeam.ANY;
				if (CreationManager.TryGetTeamOverrideFromInstantiationData(Tool.InstantiationParameters, out team))
				{
					TeamOverride = team;
				}
			}
			if (EquipmentType == SpawnableToolType.INVALID)
			{
				EquipmentType = Tool.SpawnableToolType;
			}
		}

		public Bounds GetWorldBounds()
		{
			if (UsesBoundsOverride)
			{
				return GetOverriddenCollisionBounds();
			}
			return Tool.GetColliderBounds();
		}

		private Bounds GetOverriddenCollisionBounds()
		{
			Bounds result = new Bounds(boundsOverrideCollider.transform.TransformPoint(boundsOverrideCollider.center), Vector3.zero);
			Vector3 position = boundsOverrideCollider.size / 2f;
			Vector3[] array = new Vector3[8]
			{
				boundsOverrideCollider.transform.TransformPoint(position),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(position.x, position.y, 0f - position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(position.x, 0f - position.y, position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(position.x, 0f - position.y, 0f - position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(0f - position.x, position.y, position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(0f - position.x, position.y, 0f - position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(0f - position.x, 0f - position.y, position.z)),
				boundsOverrideCollider.transform.TransformPoint(new Vector3(0f - position.x, 0f - position.y, 0f - position.z))
			};
			for (int i = 0; i < array.Length; i++)
			{
				result.Encapsulate(array[i]);
			}
			return result;
		}

		public T GetComponentForCollider<T>(Collider collider) where T : UnityEngine.Component
		{
			if (customComponentGetters != null && customComponentGetters.TryGetValue(typeof(T), out var value))
			{
				return value(collider) as T;
			}
			return GetComponent<T>();
		}

		public void AddCustomComponentGetter<T>(Func<Collider, T> getterFunction) where T : UnityEngine.Component
		{
			if (customComponentGetters == null)
			{
				customComponentGetters = new Dictionary<System.Type, CustomComponentGetter>();
			}
			customComponentGetters[typeof(T)] = getterFunction.Invoke;
		}

		public void AddCustomSelectionCondition(SelectionCondition condition)
		{
			customSelectionConditions.Add(condition);
		}

		public void RemoveCustomSelectionCondition(SelectionCondition condition)
		{
			customSelectionConditions.Remove(condition);
		}

		public CreationResult CanBeSelected()
		{
			if (IsLocked && !LocalPlayerHasLock)
			{
				return CreationResult.Failure_LockedByOther;
			}
			if (!Tool.IsEnabled)
			{
				return CreationResult.Failure_ToolNotEnabled;
			}
			if (Tool.IsHeldByPlayer || Tool.IsEquippedOnPlayer)
			{
				if (Tool.HolderPlayer == Player.LocalPlayer)
				{
					return CreationResult.Failure_ToolHeld;
				}
				return CreationResult.Failure_HeldByOther;
			}
			if (Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.ToolPurpose != PlayerSpawnedEquipment.Purpose.None)
			{
				return CreationResult.Failure_Generic;
			}
			if (customSelectionConditions.Count > 0)
			{
				foreach (SelectionCondition customSelectionCondition in customSelectionConditions)
				{
					CreationResult creationResult = customSelectionCondition(this);
					if (creationResult != CreationResult.Success)
					{
						return creationResult;
					}
				}
			}
			return CreationResult.Success;
		}

		public void AddCustomRaycastFilter(RaycastFilter filter)
		{
			customRaycastFilters.Add(filter);
		}

		public void RemoveCustomRaycastFilter(RaycastFilter filter)
		{
			customRaycastFilters.Remove(filter);
		}

		public bool CanBeRaycasted()
		{
			if (customRaycastFilters.Count > 0)
			{
				foreach (RaycastFilter customRaycastFilter in customRaycastFilters)
				{
					if (!customRaycastFilter(this))
					{
						return false;
					}
				}
			}
			return true;
		}

		public void RequestMasterDespawn()
		{
			base.photonView.RpcMaster(RpcMasterDespawn);
		}

		[PunRPC]
		private void RpcMasterDespawn()
		{
			MasterDespawn();
		}

		public void MasterDespawn()
		{
			if (PhotonNetwork.isMasterClient)
			{
				LockedByPhotonPlayer = PhotonPlayer.Invalid;
				PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
			}
		}

		public void AddResourceCostModifier(Func<int> costFunction, object token)
		{
			if (resourceCostModifiers == null)
			{
				resourceCostModifiers = new Dictionary<object, Func<int>>(1);
			}
			resourceCostModifiers.Add(token, costFunction);
		}

		public void RemoveResourceCostOverride(object token)
		{
			if (resourceCostModifiers != null)
			{
				resourceCostModifiers.Remove(token);
			}
		}

		public void AddPropertyHandler(string property, PropertyModificationHandler handler)
		{
			if (propertyModificationHandlers == null)
			{
				propertyModificationHandlers = new Dictionary<string, PropertyModificationHandler>();
			}
			propertyModificationHandlers.Add(property, handler);
		}

		public void RemovePropertyHandler(string property, PropertyModificationHandler handler)
		{
			if (propertyModificationHandlers != null && propertyModificationHandlers.ContainsKey(property))
			{
				propertyModificationHandlers.Remove(property);
			}
		}

		public UndoEntry ModifyProperty(CreationContext context, string propertyName, params object[] modificationParameters)
		{
			if (propertyModificationHandlers != null && propertyModificationHandlers.TryGetValue(propertyName, out var value))
			{
				return value(context, modificationParameters);
			}
			return null;
		}

		private void InitializeFrozen()
		{
			initialFreezeUpdate = true;
			OnIsFrozenChanged();
		}

		private void OnIsFrozenChanged()
		{
			Tool.RigidbodyEx.SetKinematic(FrozenKinematicToken, IsFrozen);
			if (IsFrozen)
			{
				if (Tool.IsHeld && base.hasAuthority)
				{
					Tool.HolderInfo = ToolHolderInfo.NotHeld;
				}
				if (ClearVelocitiesOnFrozenChange)
				{
					Tool.RigidbodyEx.ClearVelocity();
				}
			}
			else if (!initialFreezeUpdate && ClearVelocitiesOnFrozenChange)
			{
				Tool.RigidbodyEx.ClearVelocity();
			}
			initialFreezeUpdate = false;
			if (!IsLocked || IsFrozen)
			{
				DynamicCollisionEnabled = true;
				Tool.RigidbodyEx.WakeUp();
			}
			if (this.OnFrozenChanged != null)
			{
				this.OnFrozenChanged(IsFrozen);
			}
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer photonPlayer)
		{
			if (PhotonNetwork.isMasterClient && photonPlayer.ID == LockedByPhotonPlayer)
			{
				LockedByPhotonPlayer = PhotonPlayer.Invalid;
			}
		}

		private void UpdateCollisionLayer()
		{
			Tool.SetCollisionLayer((!DynamicCollisionEnabled) ? Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics : Tool.DefaultCollisionLayer);
		}

		private void OnLockedPhotonPlayerChanged()
		{
			Tool.RigidbodyEx.SetKinematic(LockedKinematicToken, IsLocked);
			if (LockedByPhotonPlayer == PhotonNetwork.player.ID && !base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (IsLocked)
			{
				if (Tool.IsHeld && Tool.hasAuthority)
				{
					Tool.HolderInfo = ToolHolderInfo.NotHeld;
				}
			}
			else
			{
				DynamicCollisionEnabled = true;
				Tool.RigidbodyEx.WakeUp();
			}
			if (this.LockedStatusChangedEvent != null)
			{
				this.LockedStatusChangedEvent(this);
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.version < RoomPersistenceVersion.CREATION_OBJECT_ADDED)
			{
				if (deserializeParams.viewData.DeprecatedToolData == null)
				{
					UnityEngine.Debug.LogWarningFormat(this, "Error deserializing CreationObject {0}: No data ToolData specified", base.gameObject);
				}
				else
				{
					IsFrozen = deserializeParams.viewData.DeprecatedToolData.IsFrozen;
				}
				return;
			}
			if (deserializeParams.viewData.CreationObjectData == null)
			{
				UnityEngine.Debug.LogWarningFormat(this, "Error deserializing CreationObject {0}: No data specified. (This is expected when deserializing older rooms.)", base.gameObject);
				return;
			}
			IsFrozen = deserializeParams.viewData.CreationObjectData.IsFrozen;
			if (deserializeParams.version >= RoomPersistenceVersion.INVENTION_PIECE_ADDED)
			{
				InventionPieceData inventionPieceData = deserializeParams.viewData.CreationObjectData.InventionPieceData;
				if (inventionPieceData != null)
				{
					InventionPiece.DeserializeFrom(inventionPieceData);
				}
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.CreationObjectData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing CreationObject {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.CreationObjectData = new CreationObjectData();
			if (TeamOverride.HasValue)
			{
				viewData.CreationObjectData.TeamOverride = (int)TeamOverride.Value;
			}
			else
			{
				viewData.CreationObjectData.TeamOverride = -1;
			}
			if (ColorOverride.HasValue)
			{
				viewData.CreationObjectData.ColorOverride = ColorOverride.Value.ToColorData();
			}
			if (IsFrozen)
			{
				viewData.CreationObjectData.IsFrozen = IsFrozen;
			}
			if (InventionPiece.IsTrackingInvention)
			{
				InventionPieceData inventionPieceData = new InventionPieceData();
				InventionPiece.SerializeTo(inventionPieceData);
				viewData.CreationObjectData.InventionPieceData = inventionPieceData;
			}
		}
	}
	public enum CreationResult
	{
		Success,
		Failure_Generic,
		Failure_NoAuthority,
		Failure_ToolFrozen,
		Failure_LockedByOther,
		Failure_HeldByOther,
		Failure_SettingsChangedByOther,
		Failure_InsufficientResources,
		Failure_Parented,
		Failure_ObjectDoesNotExist,
		Failure_ParentChanged,
		Failure_ToolHeld,
		Failure_NetworkError,
		Failure_ObjectAlreadyExists,
		Failure_ToolNotEnabled,
		Failure_PermissionDenied,
		Failure_InvalidAction
	}
}
[DisallowMultipleComponent]
public class MultiPlayerEditableText : PlayerEditableTextBase
{
	[SerializeField]
	private int numberOfSerializedMessages = 5;

	private List<SynchronizedField<string>> SynchronizedMessages = new List<SynchronizedField<string>>();

	protected override void Awake()
	{
		base.Awake();
		for (int i = 0; i < numberOfSerializedMessages; i++)
		{
			SynchronizedMessages.Add(new SynchronizedField<string>(this, "pet_msg_" + i, defaultMessage, SetterPermissionMode.MASTER_OR_AUTHORITY, OnSynchronizedMessageChanged));
		}
	}

	protected override void RegisterEditables()
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			return;
		}
		CreationObject component = GetComponent<CreationObject>();
		if (component == null)
		{
			UnityEngine.Debug.LogWarning("Missing CreationObject", base.gameObject);
			return;
		}
		for (int num = SynchronizedMessages.Count - 1; num >= 0; num--)
		{
			int index = num;
			StringSettingEditEvent settingEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultStringUIControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				instance.PropertyDescription.text = "Message " + index;
				instance.PropertyGetter = () => SynchronizedMessageGet(index);
				instance.PropertySetter = delegate(string val)
				{
					SynchronizedMessageSet(index, val);
				};
				instance.SetDialogOptions("Enter Message", dialogMessage, TMP_InputField.ContentType.Standard, purifyString: true);
				instance.UpdateControlFunction = delegate(CreationObjectSettingStringUIControl ui)
				{
					ui.PropertyValueText.text = SynchronizedMessageGet(index);
				};
			});
			component.AddConfigurableSetting(0, settingEvent);
		}
	}

	protected override string GetBaseMessage(Dictionary<InputSlot, int> signals = null)
	{
		int value = 0;
		if (signals != null)
		{
			signals.TryGetValue(InputSlot.C, out value);
			if (value < 0 || value > SynchronizedMessages.Count - 1)
			{
				value = 0;
			}
		}
		return SynchronizedMessageGet(value);
	}

	private string SynchronizedMessageGet(int i)
	{
		return SynchronizedMessages[i].Get();
	}

	private void SynchronizedMessageSet(int i, string newMessage)
	{
		if (string.IsNullOrEmpty(newMessage))
		{
			SynchronizedMessages[i].Set(string.Empty);
		}
		else
		{
			SynchronizedMessages[i].Set(PlayerEditableTextBase.CapStringLength(newMessage, maxMessageLength));
		}
	}

	private void OnSynchronizedMessageChanged()
	{
		UpdateText();
	}

	public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		PersistenceViewData viewData = deserializeParams.viewData;
		if (viewData == null || viewData.MessageData == null)
		{
			return;
		}
		if (viewData.MessageData.Messages.Count > 0)
		{
			for (int i = 0; i < viewData.MessageData.Messages.Count && i < SynchronizedMessages.Count; i++)
			{
				SynchronizedMessageSet(i, viewData.MessageData.Messages[i]);
			}
		}
		else
		{
			SynchronizedMessageSet(0, viewData.MessageData.Message);
		}
	}

	public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.MessageData == null)
		{
			viewData.MessageData = new MessageData();
		}
		else
		{
			viewData.MessageData.Messages.Clear();
		}
		for (int i = 0; i < SynchronizedMessages.Count; i++)
		{
			viewData.MessageData.Messages.Add(SynchronizedMessageGet(i));
		}
	}
}
[DisallowMultipleComponent]
public class PlayerEditableText : PlayerEditableTextBase
{
	private SynchronizedField<string> _message;

	private string SynchronizedMessage
	{
		get
		{
			return _message.Get();
		}
		set
		{
			_message.Set(value);
		}
	}

	protected override void Awake()
	{
