		StringSettingEditEvent settingEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultStringUIControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
		{
