		if (viewData != null && viewData.MessageData != null)
		{
			if (viewData.MessageData.Messages.Count > 0)
			{
				SynchronizedMessage = viewData.MessageData.Messages[0];
			}
			else
			{
				SynchronizedMessage = viewData.MessageData.Message;
			}
		}
		else
		{
			SynchronizedMessage = defaultMessage;
		}
	}

	public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
