[DisallowMultipleComponent]
public abstract class PlayerEditableTextBase : Photon.MonoBehaviour, IPersistable
{
	[Serializable]
	public class UnityStringEvent : UnityEvent<string>
	{
	}

	[SerializeField]
	private TextMesh textMesh;

	[SerializeField]
	private TextMeshPro textMeshPro;

	[SerializeField]
	private Text uiText;

	[Tooltip("Default message if none is provided by a player")]
	[SerializeField]
	protected string defaultMessage = "Rec Room";

	[Tooltip("Truncate message to this length")]
	[SerializeField]
	protected int maxMessageLength = 100;

	[Tooltip("Will this attempt to replace {R} with a circuit signal")]
	[SerializeField]
	private bool usesCircuits;

	[Tooltip("Message in the UI Dialog used by player to edit")]
	[SerializeField]
	protected string dialogMessage = "Enter a message to display";

	private Dictionary<InputSlot, int> cachedSignals = new Dictionary<InputSlot, int>();

	public UnityStringEvent OnTextUpdated;

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		OnTextUpdated.AddListener(UpdateTextElements);
	}

	protected void Start()
	{
		RegisterEditables();
		UpdateText();
	}

	protected abstract void RegisterEditables();

	protected override void OnDestroy()
	{
		base.OnDestroy();
		OnTextUpdated.RemoveListener(UpdateTextElements);
	}

	public void Circuit_UpdateText(Dictionary<InputSlot, int> signals)
	{
		foreach (KeyValuePair<InputSlot, int> signal in signals)
		{
			cachedSignals[signal.Key] = signal.Value;
		}
		usesCircuits = true;
		UpdateText();
	}

	public void Circuit_UpdateSingleSignalText(int signal)
	{
		usesCircuits = true;
		cachedSignals[InputSlot.R] = signal;
		UpdateText();
	}

	protected void UpdateText()
	{
		if (usesCircuits)
		{
			UpdateCircuitBasedText();
		}
		else
		{
			UpdateNonCircuitBasedText();
		}
	}

	private void UpdateNonCircuitBasedText()
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			OnTextUpdated.Invoke(defaultMessage);
			return;
		}
		string baseMessage = GetBaseMessage();
		OnTextUpdated.Invoke(baseMessage);
	}

	private void UpdateCircuitBasedText()
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			int value = 0;
			cachedSignals.TryGetValue(InputSlot.R, out value);
			OnTextUpdated.Invoke(value.ToString());
			return;
		}
		StringBuilder stringBuilder = new StringBuilder(GetBaseMessage(cachedSignals));
		for (int i = 0; i < IOSlots.AllStandardInputSlots.Length; i++)
		{
			InputSlot key = IOSlots.AllStandardInputSlots[i];
			int value2 = 0;
			cachedSignals.TryGetValue(key, out value2);
			string oldValue = $"{{{key.ToString().ToUpperInvariant()}}}";
			string oldValue2 = $"{{{key.ToString().ToLowerInvariant()}}}";
			stringBuilder = stringBuilder.Replace(oldValue, value2.ToString());
			stringBuilder = stringBuilder.Replace(oldValue2, value2.ToString());
		}
		string arg = CapStringLength(stringBuilder.ToString(), maxMessageLength);
		OnTextUpdated.Invoke(arg);
	}

	protected abstract string GetBaseMessage(Dictionary<InputSlot, int> signals = null);

	protected static string CapStringLength(string message, int maxLength)
	{
		if (message.Length > maxLength)
		{
			return message.Substring(0, maxLength);
		}
		return message;
	}

	private void UpdateTextElements(string newText)
	{
		if (textMesh != null)
		{
			textMesh.text = newText;
		}
		if (uiText != null)
		{
			uiText.text = newText;
		}
		if (textMeshPro != null)
		{
			textMeshPro.text = newText;
		}
	}

	public abstract void DeserializeFrom(PersistableDeserializeParams deserializeParams);

	public abstract void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog);
}
namespace RecRoom.Core.Creation.SandboxGizmos
{
	public abstract class AcceleratedMovementGizmo : InfluencerGizmo
	{
		private const string kinematicPhysicsToken = "AcceleratedMovementKinematicPhysics";

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private CircuitEventNodeDisplay nodeDisplay;

		protected int targetSpeedInput;

		protected int targetValueInput;

		private SynchronizedField<float> _accelerationTime;

		protected float accelerationApplicationTime;

		private SynchronizedField<bool> _usesTargetValue;

		protected CircuitEventNodeDisplay NodeDisplay => nodeDisplay;

		protected float AccelerationTime
		{
			get
			{
				return _accelerationTime.Get();
			}
			private set
			{
				_accelerationTime.Set(value);
			}
		}

		protected bool UsesTargetValue
		{
			get
			{
				return _usesTargetValue.Get();
			}
			private set
			{
				_usesTargetValue.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			base.Tool.RigidbodyEx.SetUseKinematicForces("AcceleratedMovementKinematicPhysics", useKinematicForces: true);
			base.IsRunningChanged += OnIgnitionChanged;
			base.Tool.photonView.OwnerChangedEvent += OnOwnerChanged;
			base.Tool.PostReleaseEvent += OnRelease;
			base.Tool.PostAttachEvent += OnAttach;
			base.Tool.PostDetachEvent += OnRelease;
			if ((bool)base.Tool.CreationObject)
			{
				base.Tool.CreationObject.ClearVelocitiesOnFrozenChange = false;
			}
			base.ConnectableTool.ParentChangedEvent += OnParentChanged;
			_accelerationTime = new SynchronizedField<float>(this, "AT", 0f, SetterPermissionMode.ANYONE, OnAccelerationTimeChanged);
			_usesTargetValue = new SynchronizedField<bool>(this, "UTV", defaultValue: false, SetterPermissionMode.ANYONE, OnUsesTargetValueChanged);
		}

		protected override void Start()
		{
			base.Start();
			OnAccelerationTimeChanged();
			OnUsesTargetValueChanged();
		}

		protected override void OnDestroy()
		{
			base.Tool.photonView.OwnerChangedEvent -= OnOwnerChanged;
			base.Tool.PostReleaseEvent -= OnRelease;
			base.Tool.PostAttachEvent -= OnAttach;
			base.Tool.PostDetachEvent -= OnRelease;
			base.ConnectableTool.ParentChangedEvent -= OnParentChanged;
			base.OnDestroy();
		}

		protected override void SetupCreationObjectSettings()
		{
			base.SetupCreationObjectSettings();
			CreationObject component = GetComponent<CreationObject>();
			FloatSettingEditEvent settingEvent = new FloatSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultFloatUIControlPrefab, delegate(CreationObjectSettingFloatUIControl instance)
			{
				instance.PropertyDescription.text = "Acceleration Time (s)";
				instance.SetDialogOptions("Acceleration Time", "Set acceleration time in seconds", TMP_InputField.ContentType.DecimalNumber);
				instance.PropertyGetter = SandboxAccelerationTime_Get;
				instance.PropertySetter = SandboxAccelerationTime_Set;
			});
			component.AddConfigurableSetting(settingEvent);
			BoolSettingEditEvent settingEvent2 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				instance.PropertyDescription.text = "Move to Target";
				instance.PropertyGetter = SandboxUsesTargetValue_Get;
				instance.PropertySetter = SandboxUsesTargetValue_Set;
			});
			component.AddConfigurableSetting(settingEvent2);
		}

		private void OnAttach(Tool tool)
		{
			base.Tool.RigidbodyEx.ClearVelocity();
		}

		private void OnRelease(Tool tool)
		{
			UpdateAccelerationParameters();
		}

		public void ChangeInputs(Dictionary<InputSlot, int> input)
		{
			bool flag = false;
			if (input.TryGetValue(InputSlot.G, out var value) && value != targetSpeedInput)
			{
				targetSpeedInput = value;
				flag = true;
			}
			if (input.TryGetValue(InputSlot.B, out var value2))
			{
				targetValueInput = value2;
				flag = true;
			}
			if (flag)
			{
				UpdateAccelerationParameters();
			}
		}

		private void OnIgnitionChanged()
		{
			UpdateAccelerationParameters();
		}

		protected abstract void UpdateAccelerationParameters();

		protected abstract void UpdateInputParameters();

		private void OnParentChanged(IConnectable childConnectable, int childConnectableSlot, IConnectable parentConnectable, int parentConnectableSlot, Vector3? relativePosition, Quaternion? relativeRotation)
		{
			UpdateAccelerationParameters();
		}

		private float SandboxAccelerationTime_Get()
		{
			return AccelerationTime;
		}

		private void SandboxAccelerationTime_Set(float newValue)
		{
			AccelerationTime = newValue;
		}

		private bool SandboxUsesTargetValue_Get()
		{
			return UsesTargetValue;
		}

		private void SandboxUsesTargetValue_Set(bool newValue)
		{
			UsesTargetValue = newValue;
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			base.SerializeTo(ref viewData, ref transientData, outputLog);
			if (viewData.SandboxGizmoData == null)
			{
				viewData.SandboxGizmoData = new SandboxGizmoData();
			}
			if (viewData.SandboxGizmoData.AcceleratedMovementData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Accelerated Movement Gizmo {0}: Data already specified.", base.gameObject);
			}
			else
			{
				viewData.SandboxGizmoData.AcceleratedMovementData = new AcceleratedMovementData
				{
					AccelerationTime = AccelerationTime,
					UsesTargetValue = UsesTargetValue
				};
			}
		}

		public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			base.DeserializeFrom(deserializeParams);
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData.SandboxGizmoData == null || viewData.SandboxGizmoData.AcceleratedMovementData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Accelerated Movement Gizmo {0}: gizmo data or acclereted movement data empty.", base.gameObject);
			}
			else
			{
				AccelerationTime = viewData.SandboxGizmoData.AcceleratedMovementData.AccelerationTime;
				UsesTargetValue = viewData.SandboxGizmoData.AcceleratedMovementData.UsesTargetValue;
			}
		}

		private void OnAccelerationTimeChanged()
		{
			UpdateAccelerationParameters();
		}

		private void OnUsesTargetValueChanged()
		{
			UpdateInputParameters();
			UpdateAccelerationParameters();
		}

		private void OnOwnerChanged(int newOwnerId)
		{
			if (!base.Tool.IsHeld)
			{
				UpdateAccelerationParameters();
			}
		}
	}
	public class ClampGizmo : InfluencerGizmo
	{
		protected override void Awake()
		{
			base.Awake();
			base.IsRunningChanged += OnIsRunningChanged;
		}

		private void OnIsRunningChanged()
		{
			SetChildrenClamped(!base.IsRunning);
		}

		private void SetChildrenClamped(bool clamped)
		{
			foreach (IConnectable childrenConnectable in base.ConnectableTool.ChildrenConnectables)
			{
				if (childrenConnectable.Tool != null && childrenConnectable.Tool.hasAuthority)
				{
					if (childrenConnectable.Tool.IsHeld && clamped)
					{
						childrenConnectable.Tool.HolderInfo = ToolHolderInfo.NotHeld;
					}
					ConnectableTool component = childrenConnectable.Tool.GetComponent<ConnectableTool>();
					if (component != null)
					{
						component.PhysicallyUnparented = !clamped;
					}
				}
			}
		}
	}
	public class InfluencerGizmo : SandboxGizmo
	{
		public enum ConnectionSlot
		{
			Parenting,
			Influencing
		}

		[SerializeField]
		private ConnectionPoint parentingConnectionPoint;

		[SerializeField]
		private ConnectionPoint influencingConnectionPoint;

		public ConnectionPoint ParentingConnectionPoint => parentingConnectionPoint;

		public ConnectionPoint InfluencingConnectionPoint => influencingConnectionPoint;

		protected override void Awake()
		{
			base.Awake();
			if (InfluencingConnectionPoint != null)
			{
				InfluencingConnectionPoint.OnConnectionStart += OnInfluencingConnectionStart;
				InfluencingConnectionPoint.OnConnectionEnd += OnInfluencingConnectionEnd;
			}
			if (ParentingConnectionPoint != null)
			{
				ParentingConnectionPoint.OnConnectionStart += OnParentingConnectionStart;
				ParentingConnectionPoint.OnConnectionEnd += OnParentingConnectionEnd;
			}
		}

		private void OnInfluencingConnectionStart(ConnectionPoint interactable, ConnectionPoint.ConnectionResultCallback callback = null)
		{
			CreationResult result = CreationResult.Failure_HeldByOther;
			if (base.hasAuthority || !base.Tool.IsHeld)
			{
				result = CreationResult.Success;
			}
			callback?.Invoke(result, base.photonView.authority);
		}

		private void OnParentingConnectionStart(ConnectionPoint interactable, ConnectionPoint.ConnectionResultCallback callback = null)
		{
			CreationResult result = CreationResult.Failure_HeldByOther;
			if (base.hasAuthority || !base.Tool.IsHeld)
			{
				base.ConnectableTool.AuthorityUnparentThisConnectableFromOther();
				result = CreationResult.Success;
			}
			callback?.Invoke(result, base.photonView.authority);
		}

		private void OnInfluencingConnectionEnd(ConnectionPoint connectionStart, ConnectionPoint connectionEnd, ConnectionPoint.ConnectionResultCallback callback = null)
		{
			CreationResult result = CreationResult.Success;
			IConnectable connectable = null;
			ConnectionPoint connectionPoint = null;
			ConnectionPoint.ConnectionSlot childSlotIndex = ConnectionPoint.ConnectionSlot.SLOT_0;
			if (connectionStart != null && connectionEnd != null)
			{
				if (connectionStart.gameObject == influencingConnectionPoint.gameObject)
				{
					connectable = connectionEnd.GetComponentInParent<IConnectable>();
					connectionPoint = connectionEnd.GetComponent<ConnectionPoint>();
					if (connectable is ConnectableInfluencerGizmo)
					{
						connectable = null;
						connectionPoint = null;
					}
				}
				else
				{
					connectable = connectionStart.GetComponentInParent<IConnectable>();
					connectionPoint = connectionStart.GetComponent<ConnectionPoint>();
				}
			}
			if (connectionPoint != null)
			{
				childSlotIndex = connectionPoint.SlotIndex;
			}
			if (connectable != null && connectable.Tool != null)
			{
				if (!base.hasAuthority && !base.Tool.IsHeld && base.Tool.AllowedToTakeOwnership)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				if (base.hasAuthority)
				{
					if (!base.ConnectableTool.ChildrenConnectables.Contains(connectable))
					{
						Vector3 value = base.Tool.RigidbodyEx.TargetTransform.InverseTransformPoint(connectable.Tool.RigidbodyEx.TargetTransform.position);
						Quaternion value2 = base.Tool.RigidbodyEx.TargetTransform.InverseTransformRotation(connectable.Tool.RigidbodyEx.TargetTransform.rotation);
						base.ConnectableTool.AuthorityParentOtherConnectableToThis(1, connectable, (int)childSlotIndex, value, value2);
					}
					else
					{
						base.ConnectableTool.AuthorityUnparentOtherConnectableFromThis(connectable);
					}
				}
				else
				{
					result = CreationResult.Failure_NoAuthority;
				}
			}
			callback?.Invoke(result, null);
		}

		private void OnParentingConnectionEnd(ConnectionPoint connectionStart, ConnectionPoint connectionEnd, ConnectionPoint.ConnectionResultCallback callback = null)
		{
			CreationResult result = CreationResult.Success;
			IConnectable connectable = null;
			ConnectionPoint connectionPoint = null;
			ConnectionPoint.ConnectionSlot parentSlotIndex = ConnectionPoint.ConnectionSlot.SLOT_0;
			if (connectionStart != null && connectionEnd != null)
			{
				if (connectionStart.gameObject == parentingConnectionPoint.gameObject)
				{
					connectable = connectionEnd.GetComponentInParent<IConnectable>();
					connectionPoint = connectionEnd.GetComponent<ConnectionPoint>();
					if (connectable is ConnectableInfluencerGizmo)
					{
						connectable = null;
						connectionPoint = null;
					}
				}
				else
				{
					connectable = connectionStart.GetComponentInParent<IConnectable>();
					connectionPoint = connectionStart.GetComponent<ConnectionPoint>();
				}
			}
			if (connectionPoint != null)
			{
				parentSlotIndex = connectionPoint.SlotIndex;
			}
			if (connectable != null)
			{
				if (!base.hasAuthority && !base.Tool.IsHeld && base.Tool.AllowedToTakeOwnership)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				if (base.hasAuthority)
				{
					if (base.ConnectableTool.ParentConnectable != connectable)
					{
						base.ConnectableTool.AuthorityParentThisConnectableToOther(0, connectable, (int)parentSlotIndex);
					}
					else
					{
						base.ConnectableTool.AuthorityUnparentThisConnectableFromOther();
					}
				}
				else
				{
					result = CreationResult.Failure_NoAuthority;
				}
			}
			callback?.Invoke(result, null);
		}
	}
	public class PistonGizmo : AcceleratedMovementGizmo
	{
		[SerializeField]
		private float maxMovementSpeed = 10000f;

		private const float MOVEMENT_EPSILON = 1E-05f;

		private const float CENTIMETERS_TO_METERS = 0.01f;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private LineRenderer pathLineRenderer;

		private float currentTargetSpeed;

		private Vector3 currentLocalForce = Vector3.zero;

		private float currentTargetDistance;

		private float sqrLastDistanceToTarget;

		private bool reachedTargetDistance;

		private SynchronizedField<float> _maxTravelDistance;

		private float sqrMaxTravelDistance = 25f;

		private float MaxTravelDistance
		{
			get
			{
				return _maxTravelDistance.Get();
			}
			set
			{
				_maxTravelDistance.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_maxTravelDistance = new SynchronizedField<float>(this, "MD", 5f, SetterPermissionMode.ANYONE, OnMaxTravelDistanceChanged);
		}

		protected override void Start()
		{
			base.Start();
			OnMaxTravelDistanceChanged();
		}

		private void Update()
		{
			UpdatePathRenderer();
		}

		protected override void SetupCreationObjectSettings()
		{
			base.SetupCreationObjectSettings();
			CreationObject component = GetComponent<CreationObject>();
			FloatSettingEditEvent settingEvent = new FloatSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultFloatUIControlPrefab, delegate(CreationObjectSettingFloatUIControl instance)
			{
				instance.PropertyDescription.text = "Max Travel Distance (m)";
				instance.SetDialogOptions("Max Travel Distance", "Set maximum travel distance", TMP_InputField.ContentType.DecimalNumber);
				instance.PropertyGetter = SandboxMaxTravelDistance_Get;
				instance.PropertySetter = SandboxMaxTravelDistance_Set;
			});
			component.AddConfigurableSetting(settingEvent);
		}

		protected override void UpdateAccelerationParameters()
		{
			if (base.IsRunning)
			{
				currentTargetSpeed = Mathf.Min(maxMovementSpeed, Mathf.Abs(targetSpeedInput)) * 0.01f;
				if (base.UsesTargetValue)
				{
					currentTargetDistance = ((!(MaxTravelDistance > 0f)) ? Mathf.Min(0f, Mathf.Max((float)targetValueInput * 0.01f, MaxTravelDistance)) : Mathf.Max(0f, Mathf.Min((float)targetValueInput * 0.01f, MaxTravelDistance)));
					float num = currentTargetDistance * currentTargetDistance;
					float sqrMagnitude = (base.Tool.RigidbodyEx.targetLocalPosition - base.DefaultRelativePosition).sqrMagnitude;
					float num2 = Mathf.Abs(num - sqrMagnitude);
					if (num2 > 1E-05f)
					{
						bool flag = (MaxTravelDistance >= 0f && sqrMagnitude > num) || (MaxTravelDistance < 0f && sqrMagnitude <= num);
						currentTargetSpeed = ((!flag) ? currentTargetSpeed : (0f - currentTargetSpeed));
						sqrLastDistanceToTarget = float.MaxValue;
						reachedTargetDistance = false;
					}
					else
					{
						currentTargetSpeed = 0f;
						reachedTargetDistance = true;
					}
				}
				else if (targetSpeedInput < 0)
				{
					currentTargetSpeed = 0f - currentTargetSpeed;
				}
				if (base.AccelerationTime <= 0.01f)
				{
					AuthorityApplyInstantaneousLinearVelocity(currentTargetSpeed);
					return;
				}
				float num3 = ((!(Vector3.Dot(base.Tool.RigidbodyEx.TargetTransform.up, base.Tool.RigidbodyEx.velocity) >= 0f)) ? (-1f) : 1f);
				float num4 = currentTargetSpeed - base.Tool.RigidbodyEx.velocity.magnitude * num3;
				accelerationApplicationTime = 0f;
				currentLocalForce = new Vector3(0f, num4 / base.AccelerationTime, 0f);
			}
			else if (base.hasAuthority)
			{
				StopMovement();
			}
		}

		protected override void UpdateInputParameters()
		{
			if (base.UsesTargetValue)
			{
				base.NodeDisplay.AddInputMeta(InputSlot.B, "Target Position (cm)");
			}
			else
			{
				base.NodeDisplay.RemoveInputMeta(InputSlot.B);
			}
		}

		protected override void UpdateDefaultState(Vector3 newDefaultRelativePosition, Quaternion newDefaultRelativeRotation)
		{
			base.UpdateDefaultState(newDefaultRelativePosition, newDefaultRelativeRotation);
			UpdateAccelerationParameters();
		}

		protected override void UpdatePhysics()
		{
			base.UpdatePhysics();
			if (base.IsRunning && base.hasAuthority && !base.Tool.IsHeld)
			{
				if (base.AccelerationTime > 0.01f)
				{
					UpdateLinearAcceleration();
				}
				if (base.UsesTargetValue)
				{
					AuthorityCheckTargetPositionReached();
				}
				if (base.Tool.RigidbodyEx.localVelocity.sqrMagnitude > 1E-05f)
				{
					AuthorityCheckMovementLimits();
				}
			}
		}

		private void UpdateLinearAcceleration()
		{
			if (accelerationApplicationTime < base.AccelerationTime)
			{
				accelerationApplicationTime += UnityEngine.Time.fixedDeltaTime;
				if (accelerationApplicationTime < base.AccelerationTime)
				{
					Vector3 force = base.Tool.RigidbodyEx.TargetTransform.TransformVector(currentLocalForce);
					base.Tool.RigidbodyEx.AddForce(force, ForceMode.Acceleration);
				}
				else
				{
					AuthorityApplyInstantaneousLinearVelocity(currentTargetSpeed);
				}
			}
		}

		private void AuthorityCheckTargetPositionReached()
		{
			if (!base.hasAuthority || reachedTargetDistance)
			{
				return;
			}
			reachedTargetDistance = targetSpeedInput == 0;
			if (!reachedTargetDistance)
			{
				Vector3 targetLocalPositionFromPathDistance = GetTargetLocalPositionFromPathDistance(currentTargetDistance);
				float sqrMagnitude = (targetLocalPositionFromPathDistance - base.Tool.RigidbodyEx.targetLocalPosition).sqrMagnitude;
				float sqrMagnitude2 = (base.Tool.RigidbodyEx.localVelocity * UnityEngine.Time.deltaTime).sqrMagnitude;
				if (sqrMagnitude2 > sqrMagnitude || sqrMagnitude > sqrLastDistanceToTarget + 0.001f)
				{
					reachedTargetDistance = true;
				}
				else
				{
					sqrLastDistanceToTarget = sqrMagnitude;
				}
			}
			if (reachedTargetDistance)
			{
				StopMovement();
				base.Tool.RigidbodyEx.targetLocalPosition = GetTargetLocalPositionFromPathDistance(currentTargetDistance);
			}
		}

		private void AuthorityCheckMovementLimits()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Vector3 lhs = base.Tool.RigidbodyEx.targetLocalPosition - base.DefaultRelativePosition;
			Vector3 vector = base.Tool.RigidbodyEx.targetLocalRotation * Vector3.up;
			Vector3 rhs = ((!(MaxTravelDistance >= 0f)) ? (-vector) : vector);
			bool flag = Vector3.Dot(lhs, rhs) <= 0f;
			bool flag2 = false;
			if (!flag)
			{
				flag2 = lhs.sqrMagnitude >= sqrMaxTravelDistance;
			}
			if (flag || flag2)
			{
				StopMovement();
				if (flag)
				{
					base.Tool.RigidbodyEx.targetLocalPosition = base.DefaultRelativePosition;
				}
				else
				{
					base.Tool.RigidbodyEx.targetLocalPosition = base.DefaultRelativePosition + base.Tool.RigidbodyEx.targetLocalRotation * Vector3.up * MaxTravelDistance;
				}
			}
		}

		private void AuthorityApplyInstantaneousLinearVelocity(float speed)
		{
			if (base.hasAuthority)
			{
				base.Tool.RigidbodyEx.ClearLinearVelocity();
				Vector3 force = base.Tool.RigidbodyEx.TargetTransform.TransformVector(new Vector3(0f, speed, 0f));
				base.Tool.RigidbodyEx.AddForce(force, ForceMode.VelocityChange);
			}
		}

		private void StopMovement()
		{
			base.Tool.RigidbodyEx.ClearLinearVelocity();
			reachedTargetDistance = true;
			currentTargetSpeed = 0f;
			currentLocalForce = Vector3.zero;
		}

		private void UpdatePathRenderer()
		{
			if (pathLineRenderer.isVisible)
			{
				Vector3 vector = ((!base.Tool.RigidbodyEx.hasParent) ? base.DefaultRelativePosition : base.Tool.RigidbodyEx.parent.TargetTransform.TransformPoint(base.DefaultRelativePosition));
				Vector3 position = vector + base.Tool.RigidbodyEx.TargetTransform.up * MaxTravelDistance;
				pathLineRenderer.SetPosition(0, vector);
				pathLineRenderer.SetPosition(1, position);
			}
		}

		private float SandboxMaxTravelDistance_Get()
		{
			return MaxTravelDistance;
		}

		private void SandboxMaxTravelDistance_Set(float newValue)
		{
			MaxTravelDistance = newValue;
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			base.SerializeTo(ref viewData, ref transientData, outputLog);
			if (viewData.SandboxGizmoData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Piston Gizmo {0}: gizmo data is null", base.gameObject);
			}
			if (viewData.SandboxGizmoData.PistonData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing Piston Gizmo {0}: Data already specified.", base.gameObject);
			}
			else
			{
				viewData.SandboxGizmoData.PistonData = new PistonData
				{
					MaxTravelDistance = MaxTravelDistance
				};
			}
		}

		public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			base.DeserializeFrom(deserializeParams);
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData.SandboxGizmoData == null || viewData.SandboxGizmoData.PistonData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Piston Gizmo {0}: gizmo data or piston data empty.", base.gameObject);
			}
			else
			{
				MaxTravelDistance = viewData.SandboxGizmoData.PistonData.MaxTravelDistance;
			}
		}

		private void OnMaxTravelDistanceChanged()
		{
			sqrMaxTravelDistance = MaxTravelDistance * MaxTravelDistance;
			AuthorityCheckMovementLimits();
		}

		private Vector3 GetTargetLocalPositionFromPathDistance(float distance)
		{
			return base.DefaultRelativePosition + base.Tool.RigidbodyEx.targetLocalRotation * Vector3.up * distance;
		}
	}
	public class RotatorGizmo : AcceleratedMovementGizmo
	{
		[SerializeField]
		private float maxRotationSpeed = 180f;

		private const float ROTATION_STOPPED_THRESHOLD = 0.0001f;

		private float currentTargetRotationSpeed;

		private Vector3 currentLocalTorque = Vector3.zero;

		private Quaternion currentTargetLocalRotation = Quaternion.identity;

		private float sqrLastAngleToTarget;

		private bool reachedTargetAngle;

		protected override void UpdateAccelerationParameters()
		{
			if (base.IsRunning)
			{
				currentTargetRotationSpeed = RPMToRadPerSec(Mathf.Min(maxRotationSpeed, Mathf.Abs(targetSpeedInput)));
				if (targetSpeedInput < 0)
				{
					currentTargetRotationSpeed = 0f - currentTargetRotationSpeed;
				}
				if (base.UsesTargetValue)
				{
					Quaternion quaternion = Quaternion.Euler(0f, targetValueInput, 0f);
					float num = Quaternion.Angle(base.Tool.RigidbodyEx.targetLocalRotation, base.DefaultRelativeRotation * quaternion);
					if (num > 0.0001f)
					{
						currentTargetLocalRotation = quaternion;
						sqrLastAngleToTarget = float.MaxValue;
						reachedTargetAngle = false;
					}
					else
					{
						currentTargetRotationSpeed = 0f;
						reachedTargetAngle = true;
					}
				}
				if (base.AccelerationTime <= 0.01f)
				{
					AuthorityApplyInstantaneousAngularVelocity(currentTargetRotationSpeed);
					return;
				}
				float num2 = ((!(Vector3.Dot(base.Tool.RigidbodyEx.TargetTransform.up, base.Tool.RigidbodyEx.angularVelocity) >= 0f)) ? (-1f) : 1f);
				float num3 = currentTargetRotationSpeed - base.Tool.RigidbodyEx.localAngularVelocity.magnitude * num2;
				accelerationApplicationTime = 0f;
				currentLocalTorque = new Vector3(0f, num3 / base.AccelerationTime, 0f);
			}
			else if (base.hasAuthority)
			{
				StopRotation();
			}
		}

		protected override void UpdateInputParameters()
		{
			if (base.UsesTargetValue)
			{
				base.NodeDisplay.AddInputMeta(InputSlot.B, "Target Angle (deg)");
			}
			else
			{
				base.NodeDisplay.RemoveInputMeta(InputSlot.B);
			}
		}

		protected override void UpdatePhysics()
		{
			base.UpdatePhysics();
			if (base.IsRunning && !base.Tool.IsHeld)
			{
				if (base.hasAuthority && base.AccelerationTime > 0.01f)
				{
					AuthorityUpdateAngularAcceleration();
				}
				if (base.UsesTargetValue)
				{
					AuthorityCheckTargetAngleReached();
				}
			}
		}

		private void AuthorityUpdateAngularAcceleration()
		{
			if (base.hasAuthority && accelerationApplicationTime < base.AccelerationTime)
			{
				accelerationApplicationTime += UnityEngine.Time.fixedDeltaTime;
				if (accelerationApplicationTime < base.AccelerationTime)
				{
					Vector3 torque = base.Tool.RigidbodyEx.TargetTransform.TransformVector(currentLocalTorque);
					base.Tool.RigidbodyEx.AddTorque(torque, ForceMode.Acceleration);
				}
				else
				{
					AuthorityApplyInstantaneousAngularVelocity(currentTargetRotationSpeed);
				}
			}
		}

		private void AuthorityCheckTargetAngleReached()
		{
			if (!base.hasAuthority || reachedTargetAngle)
			{
				return;
			}
			reachedTargetAngle = targetSpeedInput == 0;
			if (!reachedTargetAngle)
			{
				float num = (float)Math.PI / 180f * Quaternion.Angle(base.DefaultRelativeRotation * currentTargetLocalRotation, base.Tool.RigidbodyEx.targetLocalRotation);
				Vector3 lhs = Vector3.Cross(base.Tool.RigidbodyEx.targetLocalRotation * Vector3.forward, base.DefaultRelativeRotation * currentTargetLocalRotation * Vector3.forward);
				Vector3 rhs = ((targetSpeedInput < 0) ? (base.Tool.RigidbodyEx.targetLocalRotation * Vector3.down) : (base.Tool.RigidbodyEx.targetLocalRotation * Vector3.up));
				if (Vector3.Dot(lhs, rhs) < 0f)
				{
					num = (float)Math.PI * 2f - Mathf.Abs(num);
				}
				float sqrMagnitude = (base.Tool.RigidbodyEx.angularVelocity * UnityEngine.Time.deltaTime).sqrMagnitude;
				float num2 = num * num;
				if (sqrMagnitude > num2 || num2 > sqrLastAngleToTarget + 0.0001f)
				{
					reachedTargetAngle = true;
				}
				else
				{
					sqrLastAngleToTarget = num2;
				}
			}
			if (reachedTargetAngle)
			{
				StopRotation();
				base.Tool.RigidbodyEx.targetLocalRotation = base.DefaultRelativeRotation * currentTargetLocalRotation;
			}
		}

		private void AuthorityApplyInstantaneousAngularVelocity(float angularSpeed)
		{
			if (base.hasAuthority)
			{
				base.Tool.RigidbodyEx.ClearAngularVelocity();
				Vector3 torque = base.Tool.RigidbodyEx.TargetTransform.TransformVector(new Vector3(0f, angularSpeed, 0f));
				base.Tool.RigidbodyEx.AddTorque(torque, ForceMode.VelocityChange);
			}
		}

		private void StopRotation()
		{
			base.Tool.RigidbodyEx.ClearAngularVelocity();
			reachedTargetAngle = true;
			currentTargetRotationSpeed = 0f;
			currentLocalTorque = Vector3.zero;
		}

		protected override void UpdateDefaultState(Vector3 newDefaultRelativePosition, Quaternion newDefaultRelativeRotation)
		{
			base.UpdateDefaultState(newDefaultRelativePosition, newDefaultRelativeRotation);
			UpdateAccelerationParameters();
		}

		public static float RPMToRadPerSec(float RPMSpeed)
		{
			return RPMSpeed * (float)Math.PI / 30f;
		}
	}
}
namespace RecRoom.Core.Creation
{
	public class SandboxConnectableManager : NetworkedSingletonMonoBehaviour<SandboxConnectableManager>
	{
		private struct ConnectableLink : IEquatable<ConnectableLink>
		{
			public IConnectable connectable;

			public int slot;

			public int parentSlot;

			public Vector3 relativePosition;

			public Quaternion relativeRotation;

			public ConnectableLink(IConnectable connectable, int slot, int parentSlot, Vector3 relativePosition, Quaternion relativeRotation)
			{
				this.connectable = connectable;
				this.slot = slot;
				this.parentSlot = parentSlot;
				this.relativePosition = relativePosition;
				this.relativeRotation = relativeRotation;
			}

			public ConnectableLink(IConnectable connectable, int slot, int parentSlot)
			{
				this.connectable = connectable;
				this.slot = slot;
				this.parentSlot = parentSlot;
				relativePosition = Vector3.zero;
				relativeRotation = Quaternion.identity;
			}

			public ConnectableLink(IConnectable connectable)
			{
				this.connectable = connectable;
				slot = 0;
				parentSlot = 0;
				relativePosition = Vector3.zero;
				relativeRotation = Quaternion.identity;
			}

			public bool Equals(ConnectableLink other)
			{
				if (connectable == null || other.connectable == null)
				{
					return connectable == null && other.connectable == null;
				}
				return connectable.PhotonId == other.connectable.PhotonId;
			}

			public override string ToString()
			{
				if (connectable != null)
				{
					return $"{connectable.GameObject.name}(Photon ID: {connectable.PhotonId}, Persistence ID: {connectable.PersistenceId})";
				}
				return "null";
			}
		}

