		{
			if (connectableGraphInitialized && messageInfo.sender.IsMasterClient)
			{
				InternalConnectNodes(childConnectable, childSlotIndex, parentConnectable, parentSlotIndex, relativePosition, relativeRotation);
			}
		}

		private bool InternalConnectNodes(IConnectable childConnectable, int childSlotIndex, IConnectable parentConnectable, int parentSlotIndex, Vector3 relativePosition, Quaternion relativeRotation)
		{
			ConnectableLink newNodeContent = new ConnectableLink(childConnectable, childSlotIndex, parentSlotIndex, relativePosition, relativeRotation);
			ConnectableLink nodeContentToFind = new ConnectableLink(parentConnectable);
			bool flag = false;
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(connectableTree, nodeContentToFind);
			if (uniqueTreeNode != null)
			{
				UniqueTreeNode<ConnectableLink> uniqueTreeNode2 = uniqueTreeNode.AddChild(newNodeContent);
				flag = uniqueTreeNode2 != null;
				if (flag)
				{
					childConnectable.ParentChanged(childSlotIndex, parentConnectable, parentSlotIndex, relativePosition, relativeRotation);
					if (!uniqueTreeNode.IsRoot)
					{
						AddConnectableLinkVisual(uniqueTreeNode2);
						parentConnectable.ChildAdded(parentSlotIndex, childConnectable, childSlotIndex, relativePosition, relativeRotation);
						IConnectable rootConnectable = GetRootConnectable(childConnectable);
						childConnectable.RootChanged(null, rootConnectable);
					}
				}
			}
			if (verboseLogging)
			{
				string text = ((parentConnectable == null || !(parentConnectable.GameObject != null)) ? "null" : parentConnectable.GameObject.name);
				string text2 = ((childConnectable == null || !(childConnectable.GameObject != null)) ? "null" : childConnectable.GameObject.name);
				string text3 = ((parentConnectable == null) ? "-1" : parentConnectable.PhotonId.ToString());
				string text4 = ((childConnectable == null) ? "-1" : childConnectable.PhotonId.ToString());
				UnityEngine.Debug.LogFormat("Attempted to CONNECT nodes {0}({6}).{1} -> {2}({7}).{3}: Rel. pos: {8}, Rel. rot: {9}. Success = {4}\n{5}", text2, childSlotIndex, text, parentSlotIndex, flag, UniqueTreeNode<ConnectableLink>.ToString(connectableTree), text4, text3, relativePosition.ToString("F2"), relativeRotation.eulerAngles);
			}
			return flag;
		}

