		private bool InternalDisconnectNode(IConnectable objectToDisconnect)
		{
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(nodeContentToFind: new ConnectableLink(objectToDisconnect), traversalRoot: connectableTree);
			bool flag = false;
			if (uniqueTreeNode != null && objectToDisconnect.GameObject.Equals(uniqueTreeNode.Content.connectable.GameObject))
			{
				UniqueTreeNode<ConnectableLink> parent = uniqueTreeNode.Parent;
				UniqueTreeNode<ConnectableLink>[] array = new UniqueTreeNode<ConnectableLink>[uniqueTreeNode.Children.Count];
				uniqueTreeNode.Children.CopyTo(array, 0);
				IConnectable previousRootConnectable = GetRootConnectable(objectToDisconnect);
				flag = uniqueTreeNode.Remove() != null;
				if (flag)
				{
					RemoveConnectableLinkVisual(uniqueTreeNode);
					objectToDisconnect.ParentChanged(0, null, 0, Vector3.zero, Quaternion.identity);
					if (previousRootConnectable != null)
					{
						objectToDisconnect.RootChanged(previousRootConnectable, null);
					}
					if (parent != null && parent.Content.connectable != null)
					{
						parent.Content.connectable.ChildRemoved(uniqueTreeNode.Content.parentSlot, objectToDisconnect, uniqueTreeNode.Content.slot);
					}
					Transform transform = objectToDisconnect.Transform;
					UniqueTreeNode<ConnectableLink>[] array2 = array;
					foreach (UniqueTreeNode<ConnectableLink> child in array2)
					{
						RemoveConnectableLinkVisual(child);
						child.Content.relativePosition = transform.TransformPoint(child.Content.relativePosition);
						child.Content.relativeRotation = transform.TransformRotation(child.Content.relativeRotation);
						child.Content.connectable.ParentChanged(0, null, 0, child.Content.relativePosition, child.Content.relativeRotation);
						if (previousRootConnectable != null)
						{
							UniqueTreeNode<ConnectableLink>.TraverseTree(child, delegate(UniqueTreeNode<ConnectableLink> node)
							{
								node.Content.connectable.RootChanged(previousRootConnectable, child.Content.connectable);
								return true;
							});
						}
						objectToDisconnect.ChildRemoved(child.Content.parentSlot, child.Content.connectable, child.Content.slot);
					}
				}
			}
			if (verboseLogging)
			{
				string text = ((objectToDisconnect == null || !(objectToDisconnect.GameObject != null)) ? "null" : objectToDisconnect.GameObject.name);
				string text2 = ((objectToDisconnect == null) ? "-1" : objectToDisconnect.PhotonId.ToString());
				UnityEngine.Debug.LogFormat("Attempted to REMOVE node {0}({1}): Success = {2}\n{3}", text, text2, flag, UniqueTreeNode<ConnectableLink>.ToString(connectableTree));
			}
			return flag;
		}

