		{
			if (PhotonNetwork.isMasterClient && objectToReparent.CanConnectTo(objectToReparentSlotIndex, newParent, newParentSlot) && InternalReparentNodes(objectToReparent, objectToReparentSlotIndex, newParent, newParentSlot, relativePosition, relativeRotation))
