		[PunRPC]
		protected void RpcReparentNodes(IConnectable objectToReparent, int objectToReparentSlotIndex, IConnectable newParent, int newParentSlot, Vector3 relativePosition, Quaternion relativeRotation, PhotonMessageInfo messageInfo)
		{
			if (connectableGraphInitialized && messageInfo.sender.IsMasterClient)
			{
				InternalReparentNodes(objectToReparent, objectToReparentSlotIndex, newParent, newParentSlot, relativePosition, relativeRotation);
			}
		}

		private bool InternalReparentNodes(IConnectable objectToReparent, int objectToReparentSlotIndex, IConnectable newParent, int newParentSlot, Vector3 relativePosition, Quaternion relativeRotation)
		{
			ConnectableLink connectableLink = new ConnectableLink(objectToReparent, objectToReparentSlotIndex, newParentSlot, relativePosition, relativeRotation);
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(connectableTree, connectableLink);
			ConnectableLink connectableLink2 = new ConnectableLink(newParent, objectToReparentSlotIndex, newParentSlot);
			UniqueTreeNode<ConnectableLink> uniqueTreeNode2 = UniqueTreeNode<ConnectableLink>.FindNode(connectableTree, connectableLink2);
			bool flag = false;
			if (uniqueTreeNode != null && uniqueTreeNode2 != null)
			{
				UniqueTreeNode<ConnectableLink> parent = uniqueTreeNode.Parent;
				IConnectable previousRootConnectable = GetRootConnectable(objectToReparent);
				flag = uniqueTreeNode.Reparent(connectableLink2) != null;
				if (flag)
				{
					uniqueTreeNode.Content = connectableLink;
					UpdateConnectableLinkVisual(uniqueTreeNode);
					objectToReparent.ParentChanged(objectToReparentSlotIndex, newParent, newParentSlot, relativePosition, relativeRotation);
					IConnectable newRootConnectable = GetRootConnectable(objectToReparent);
					if (previousRootConnectable != newRootConnectable)
					{
						UniqueTreeNode<ConnectableLink>.TraverseTree(uniqueTreeNode, delegate(UniqueTreeNode<ConnectableLink> node)
						{
							if (node.Content.connectable != null)
							{
								node.Content.connectable.RootChanged(previousRootConnectable, newRootConnectable);
							}
							return true;
						});
					}
					if (parent != null && parent.Content.connectable != null)
					{
						parent.Content.connectable.ChildRemoved(parent.Content.parentSlot, objectToReparent, parent.Content.slot);
					}
					newParent?.ChildAdded(newParentSlot, objectToReparent, objectToReparentSlotIndex, relativePosition, relativeRotation);
				}
			}
			if (verboseLogging)
			{
				string text = ((newParent == null || !(newParent.GameObject != null)) ? "null" : newParent.GameObject.name);
				string text2 = ((objectToReparent == null || !(objectToReparent.GameObject != null)) ? "null" : objectToReparent.GameObject.name);
				string text3 = ((newParent == null) ? "-1" : newParent.PhotonId.ToString());
				string text4 = ((objectToReparent == null) ? "-1" : objectToReparent.PhotonId.ToString());
				UnityEngine.Debug.LogFormat("Attempted to REPARENT nodes {0}({6}).{1} -> {2}({7}).{3}: Rel. pos: {8}, Rel. rot: {9} Success = {4}\n{5}", text2, objectToReparentSlotIndex, text, newParentSlot, flag, UniqueTreeNode<ConnectableLink>.ToString(connectableTree), text4, text3, relativePosition.ToString("F2"), relativeRotation.eulerAngles);
			}
			return flag;
		}

