		private bool InternalModifyNode(IConnectable connectableToModify, int childSlotIndex, int parentSlotIndex, Vector3 relativePosition, Quaternion relativeRotation)
		{
			ConnectableLink connectableLink = new ConnectableLink(connectableToModify);
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(connectableTree, connectableLink);
			bool result = false;
			if (uniqueTreeNode != null)
			{
				connectableLink.slot = childSlotIndex;
				connectableLink.parentSlot = parentSlotIndex;
				connectableLink.relativePosition = relativePosition;
				connectableLink.relativeRotation = relativeRotation;
				uniqueTreeNode.Content = connectableLink;
				connectableToModify.ConnectionModified(childSlotIndex, uniqueTreeNode.Parent?.Content.connectable, parentSlotIndex, relativePosition, relativeRotation);
				result = true;
			}
			return result;
		}

		public void GetConnectableRelativePositionAndRotation(IConnectable connectable, out Vector3 relativePosition, out Quaternion relativeRotation)
		{
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(nodeContentToFind: new ConnectableLink(connectable), traversalRoot: connectableTree);
			if (uniqueTreeNode != null)
			{
				relativePosition = uniqueTreeNode.Content.relativePosition;
				relativeRotation = uniqueTreeNode.Content.relativeRotation;
			}
			else
			{
				relativePosition = Vector3.zero;
				relativeRotation = Quaternion.identity;
			}
		}

		public IConnectable GetRootConnectable(IConnectable connectable)
		{
			UniqueTreeNode<ConnectableLink> uniqueTreeNode = UniqueTreeNode<ConnectableLink>.FindNode(nodeContentToFind: new ConnectableLink(connectable), traversalRoot: connectableTree);
			if (uniqueTreeNode != null)
			{
				UniqueTreeNode<ConnectableLink> rootConnectableNode = GetRootConnectableNode(uniqueTreeNode);
				if (rootConnectableNode != null)
				{
					return rootConnectableNode.Content.connectable;
				}
			}
			return null;
		}

		private UniqueTreeNode<ConnectableLink> GetRootConnectableNode(UniqueTreeNode<ConnectableLink> node)
		{
			if (node.IsRoot)
			{
				return null;
			}
			if (node.Parent.IsRoot)
			{
				return node;
			}
			return GetRootConnectableNode(node.Parent);
		}

		private void AddConnectableLinkVisual(UniqueTreeNode<ConnectableLink> nodeToAdd, CircuitLinkVisual linkVisualPrefabOverride = null)
		{
			if (!connectionLinkVisuals.ContainsKey(nodeToAdd.Content.connectable.PhotonId))
			{
				ConnectableLink content = nodeToAdd.Parent.Content;
				ConnectableLink content2 = nodeToAdd.Content;
				CircuitLinkVisual circuitLinkVisual = UnityEngine.Object.Instantiate((!(linkVisualPrefabOverride != null)) ? ConnectableLinkVisualPrefab : linkVisualPrefabOverride, base.transform, worldPositionStays: false);
				circuitLinkVisual.gameObject.name = $"ConnectableLink[{content.connectable.Name}.{content2.parentSlot}=>{content2.connectable.Name}.{content2.slot}]";
				circuitLinkVisual.LineRenderer.startColor = content.connectable.GetConnectionSlotColor(content2.parentSlot);
				circuitLinkVisual.LineRenderer.endColor = content2.connectable.GetConnectionSlotColor(content2.slot);
				connectionLinkVisuals[nodeToAdd.Content.connectable.PhotonId] = circuitLinkVisual;
			}
		}

		private void RemoveConnectableLinkVisual(UniqueTreeNode<ConnectableLink> nodeToRemove)
		{
			if (connectionLinkVisuals.TryGetValue(nodeToRemove.Content.connectable.PhotonId, out var value))
			{
				connectionLinkVisuals.Remove(nodeToRemove.Content.connectable.PhotonId);
				UnityEngine.Object.Destroy(value.gameObject);
			}
		}

		private void UpdateConnectableLinkVisual(UniqueTreeNode<ConnectableLink> nodeToUpdate)
		{
			if (nodeToUpdate == null)
			{
				return;
			}
			UniqueTreeNode<ConnectableLink> parent = nodeToUpdate.Parent;
			if (parent == null)
			{
				return;
			}
			if (connectionLinkVisuals.TryGetValue(nodeToUpdate.Content.connectable.PhotonId, out var value))
			{
				if (parent.Content.connectable != null)
				{
					value.gameObject.name = $"ConnectableLink[{nodeToUpdate.Parent.Content.connectable.Name}.{nodeToUpdate.Content.parentSlot}=>{nodeToUpdate.Content.connectable.Name}.{nodeToUpdate.Content.slot}]";
				}
				else
				{
					RemoveConnectableLinkVisual(nodeToUpdate);
				}
			}
			else if (parent.Content.connectable != null)
			{
				AddConnectableLinkVisual(nodeToUpdate);
			}
		}

		private void UpdateLinkLineRenderers()
		{
			ConnectableLink link;
			CircuitLinkVisual linkVisual;
			LineRenderer linkLineRenderer;
			UniqueTreeNode<ConnectableLink>.TraverseTree(connectableTree, delegate(UniqueTreeNode<ConnectableLink> node)
			{
				link = node.Content;
				if (!node.IsRoot && connectionLinkVisuals.TryGetValue(link.connectable.PhotonId, out linkVisual))
				{
					linkLineRenderer = linkVisual.LineRenderer;
					linkLineRenderer.SetPosition(0, link.connectable.GetConnectionSlotPosition(link.slot));
					linkLineRenderer.SetPosition(1, node.Parent.Content.connectable.GetConnectionSlotPosition(link.parentSlot));
					linkLineRenderer.startColor = link.connectable.GetConnectionSlotColor(link.slot);
					linkLineRenderer.endColor = node.Parent.Content.connectable.GetConnectionSlotColor(link.parentSlot);
				}
				return true;
			});
		}

		public ConnectableGraphData MasterSerializeConnectableGraph(bool usePersistenceId)
		{
			ConnectableGraphData connectableGraphData = null;
			if (PhotonNetwork.isMasterClient && connectableGraphInitialized)
			{
				connectableGraphData = new ConnectableGraphData();
				connectableGraphData.RootNode = SerializeConnectableNode(connectableTree, usePersistenceId);
			}
			return connectableGraphData;
		}

		private ConnectableNodeData SerializeConnectableNode(UniqueTreeNode<ConnectableLink> node, bool usePersistenceId)
		{
			if (!node.IsRoot && node.Content.connectable == null)
			{
				UnityEngine.Debug.LogErrorFormat("Error trying to serialize connectable node with null IConnectable: null.{0} -> {1}.{2}", node.Content.slot, node.Parent.Content.ToString(), node.Content.parentSlot);
				return null;
			}
			ConnectableNodeData connectableNodeData = new ConnectableNodeData();
			if (usePersistenceId)
			{
				connectableNodeData.PersistenceID = (node.IsRoot ? ByteString.Empty : RecRoom.Protobuf.ByteStringExtensions.ToByteString(node.Content.connectable.PersistenceId));
			}
			else
			{
				connectableNodeData.PhotonID = (node.IsRoot ? (-1) : node.Content.connectable.PhotonId);
			}
			connectableNodeData.IsRoot = node.IsRoot;
			if (!node.IsRoot)
			{
				connectableNodeData.SlotIndex = node.Content.slot;
				connectableNodeData.ParentSlotIndex = node.Content.parentSlot;
				connectableNodeData.PositionRelativeToParent = node.Content.relativePosition.ToVector3Data();
				connectableNodeData.RotationRelativeToParent = node.Content.relativeRotation.ToVector3Data();
			}
			foreach (UniqueTreeNode<ConnectableLink> child in node.Children)
			{
				if (child.Parent == null || !child.Parent.IsRoot || !child.IsLeaf || child.Content.connectable.ShouldSerializeUnparented)
				{
					connectableNodeData.Children.Add(SerializeConnectableNode(child, usePersistenceId));
				}
			}
			return connectableNodeData;
		}

		public ConnectableGraphData SerializeConnectableSubgraph(HashSet<Guid> subgraphPersistenceViewIds)
		{
			ConnectableGraphData connectableGraphData = null;
			if (connectableGraphInitialized)
			{
				connectableGraphData = new ConnectableGraphData();
				connectableGraphData.RootNode = SerializeConnectableNodesInSubgraph(connectableTree, subgraphPersistenceViewIds);
			}
			return connectableGraphData;
		}

		private ConnectableNodeData SerializeConnectableNodesInSubgraph(UniqueTreeNode<ConnectableLink> currentNode, HashSet<Guid> subgraphPersistenceViewIds, ConnectableNodeData parentNodeData = null, ConnectableNodeData rootNodeData = null)
		{
			if (!currentNode.IsRoot && currentNode.Content.connectable == null)
			{
				UnityEngine.Debug.LogErrorFormat("Error trying to serialize connectable node with null IConnectable: null.{0} -> {1}.{2}", currentNode.Content.slot, currentNode.Parent.Content.ToString(), currentNode.Content.parentSlot);
				return null;
			}
			ConnectableNodeData connectableNodeData = null;
			if (parentNodeData != null && parentNodeData.IsRoot && currentNode.IsLeaf && !currentNode.Content.connectable.ShouldSerializeUnparented)
			{
				return null;
			}
			bool flag = currentNode.IsRoot || subgraphPersistenceViewIds.Contains(currentNode.Content.connectable.PersistenceId);
			if (flag)
			{
				connectableNodeData = new ConnectableNodeData();
				connectableNodeData.PersistenceID = (currentNode.IsRoot ? ByteString.Empty : RecRoom.Protobuf.ByteStringExtensions.ToByteString(currentNode.Content.connectable.PersistenceId));
				connectableNodeData.IsRoot = currentNode.IsRoot;
				if (currentNode.IsRoot)
				{
					rootNodeData = connectableNodeData;
				}
				else
				{
					connectableNodeData.SlotIndex = currentNode.Content.slot;
					connectableNodeData.ParentSlotIndex = currentNode.Content.parentSlot;
					connectableNodeData.PositionRelativeToParent = currentNode.Content.relativePosition.ToVector3Data();
					connectableNodeData.RotationRelativeToParent = currentNode.Content.relativeRotation.ToVector3Data();
					if (parentNodeData != null)
					{
						parentNodeData.Children.Add(connectableNodeData);
					}
					else
					{
						UnityEngine.Debug.LogWarningFormat("Non-root node is included in subgraph but has no parentNodeData to add itself to - {0}", RecRoom.Protobuf.ByteStringExtensions.ToGuid(connectableNodeData.PersistenceID));
					}
				}
			}
			foreach (UniqueTreeNode<ConnectableLink> child in currentNode.Children)
			{
				ConnectableNodeData parentNodeData2 = ((!flag) ? rootNodeData : connectableNodeData);
				SerializeConnectableNodesInSubgraph(child, subgraphPersistenceViewIds, parentNodeData2, rootNodeData);
			}
			return connectableNodeData;
		}

		public void MasterDeserializeConnectableGraph(ConnectableGraphData graph)
		{
			if (PhotonNetwork.isMasterClient && InternalDeserializeConnectableGraph(graph))
			{
				MasterBroadcastReinitialize();
			}
		}

		private void MasterBroadcastReinitialize(PhotonPlayer specificPlayer = null)
		{
			if (PhotonNetwork.isMasterClient && connectableGraphInitialized)
			{
				ConnectableGraphData arg = MasterSerializeConnectableGraph(usePersistenceId: false);
				if (specificPlayer != null)
				{
					base.photonView.RpcPlayer(specificPlayer, RpcDeserializeConnectableGraph, arg);
				}
				else
				{
					base.photonView.RpcOthers(RpcDeserializeConnectableGraph, arg);
				}
			}
		}

		[PunRPC]
		protected void RpcDeserializeConnectableGraph(ConnectableGraphData graph)
		{
			if (InternalDeserializeConnectableGraph(graph))
			{
				connectableGraphInitialized = true;
			}
		}

		private bool InternalDeserializeConnectableGraph(ConnectableGraphData graph)
		{
			bool flag = true;
			List<IConnectable> list = new List<IConnectable>();
			foreach (UniqueTreeNode<ConnectableLink> child in connectableTree.Children)
			{
				if (child.IsLeaf && child.Content.connectable != null && !child.Content.connectable.ShouldSerializeUnparented)
				{
					list.Add(child.Content.connectable);
				}
			}
			connectableTree.Clear();
			foreach (int key in connectionLinkVisuals.Keys)
			{
				CircuitLinkVisual value = null;
				if (connectionLinkVisuals.TryGetValue(key, out value))
				{
					UnityEngine.Object.Destroy(value.gameObject);
				}
			}
			connectionLinkVisuals.Clear();
			flag = DeserializeConnectableNode(graph.RootNode);
			foreach (IConnectable item in list)
			{
				LocalAddNodeToRoot(item, 0);
			}
			return flag;
		}

		private bool DeserializeConnectableNode(ConnectableNodeData nodeData, Dictionary<Guid, Guid> persistenceViewIdMappings = null)
		{
			if (nodeData == null)
			{
				return false;
			}
			bool flag = true;
			IConnectable connectable = null;
			if (!nodeData.IsRoot)
			{
				connectable = GetConnectable(nodeData, persistenceViewIdMappings);
				if (connectable == null)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node {0}. Connectable was null.", GetNodeDataIdString(nodeData));
					flag = false;
				}
			}
			if (flag)
			{
				foreach (ConnectableNodeData child in nodeData.Children)
				{
					IConnectable connectable2 = GetConnectable(child, persistenceViewIdMappings);
					if (connectable2 == null)
					{
						UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable link {0}.{1} -> {2}.{3}. Child connectable component not found.", GetNodeDataIdString(child), child.SlotIndex, GetNodeDataIdString(nodeData), child.ParentSlotIndex);
						flag = false;
						break;
					}
					InternalConnectNodes(connectable2, child.SlotIndex, connectable, child.ParentSlotIndex, child.PositionRelativeToParent.ToVector3(), child.RotationRelativeToParent.ToQuaternion());
					if (!DeserializeConnectableNode(child, persistenceViewIdMappings))
					{
						break;
					}
				}
			}
			return flag;
		}

		public void MasterDeserializeConnectableSubgraph(ConnectableGraphData graph, Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			if (PhotonNetwork.isMasterClient && InternalDeserializeConnectableSubgraph(graph, persistenceViewIdMappings))
			{
				MasterBroadcastReinitialize();
			}
		}

		private bool InternalDeserializeConnectableSubgraph(ConnectableGraphData graph, Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			return DeserializeConnectableNode(graph.RootNode, persistenceViewIdMappings);
		}

		private IConnectable GetConnectable(ConnectableNodeData nodeData, Dictionary<Guid, Guid> persistenceViewIdMappings = null)
		{
			IConnectable connectable = null;
			if (nodeData.IdCase == ConnectableNodeData.IdOneofCase.PersistenceID)
			{
				if (nodeData.PersistenceID.IsEmpty)
				{
					UnityEngine.Debug.LogError("Failed to deserialize connectable node. IConnectable PersistenceID is empty.");
				}
				else
				{
					Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(nodeData.PersistenceID);
					if (persistenceViewIdMappings != null && persistenceViewIdMappings.ContainsKey(guid))
					{
						guid = persistenceViewIdMappings[guid];
					}
					PersistenceView.AllViews.TryGetValue(guid, out var value);
					if (value != null)
					{
						connectable = value.GetComponent<IConnectable>();
						if (connectable == null)
						{
							UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node {0}({1}). IConnectable component not found.", value.gameObject.name, guid);
						}
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node {0}. Persistence view not found.", guid);
					}
				}
			}
			else if (nodeData.PhotonID <= 0)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node. Invalid IConnectable PhotonID: {0}", nodeData.PhotonID);
			}
			else
			{
				PhotonView photonView = PhotonView.Find(nodeData.PhotonID);
				if (photonView != null)
				{
					connectable = photonView.GetComponent<IConnectable>();
					if (connectable == null)
					{
						UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node {0} with Photon ID: {1}. IConnectable component not found.", photonView.gameObject.name, nodeData.PhotonID);
					}
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Failed to deserialize connectable node with Photon ID: {0}. PhotonView not found.", nodeData.PhotonID);
				}
			}
			return connectable;
		}

		private string GetNodeDataIdString(ConnectableNodeData nodeData)
		{
			if (nodeData.IsRoot)
			{
				return "ROOT";
			}
			if (nodeData.IdCase == ConnectableNodeData.IdOneofCase.PersistenceID)
			{
				return RecRoom.Protobuf.ByteStringExtensions.ToGuid(nodeData.PersistenceID).ToString();
			}
			return nodeData.PhotonID.ToString();
		}

		private void OnPhotonPlayerConnected(PhotonPlayer player)
		{
			MasterBroadcastReinitialize(player);
		}

		private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			if (PhotonNetwork.isMasterClient)
			{
				connectableGraphInitialized = true;
			}
			MasterBroadcastReinitialize();
		}
	}
}
namespace RecRoom.Core.Creation.SandboxGizmos
{
	public abstract class SandboxGizmo : Photon.MonoBehaviour, IPersistable
	{
		public struct InfluencedTool
		{
			public Tool tool;

			public Vector3 relativePosition;

			public Quaternion relativeRotation;

			public InfluencedTool(Tool tool, Vector3 relativePosition, Quaternion relativeRotation)
			{
				this.tool = tool;
				this.relativePosition = relativePosition;
				this.relativeRotation = relativeRotation;
			}
		}

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private ConnectableTool _connectableTool;

		private int currentIgnitionValue;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_IsRunningChanged;

		private bool ignition;

		public ConnectableTool ConnectableTool => _connectableTool;

		public Tool Tool => ConnectableTool.Tool;

		public bool IsRunning { get; private set; }

		public virtual bool CanBeTurnedOn => !Tool.IsHeld;

		public Vector3 DefaultRelativePosition { get; protected set; }

		public Quaternion DefaultRelativeRotation { get; protected set; }

		public bool BlockObjectPersistance => false;

		public event Action IsRunningChanged
		{
			add
			{
				Action action = this.m_IsRunningChanged;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_IsRunningChanged, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_IsRunningChanged;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_IsRunningChanged, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			Tool.PostReleaseEvent += OnToolReleased;
			Tool.PostDetachEvent += OnToolReleased;
			ConnectableTool.ParentChangedEvent += OnParentChanged;
			ConnectableTool.ConnectionModifiedEvent += OnConnectionModified;
			Tool.CreationObject.LockedStatusChangedEvent += OnLockStatusChange;
			Tool.AllowedToTransferOwnershipOnCollision = false;
			Tool.RigidbodyEx.AddUpdateLodOverride(this, UpdateLOD.TwoPointFiveMeters);
			UpdateDefaultState(base.transform.position, base.transform.rotation);
		}

		protected virtual void Start()
		{
			SetupCreationObjectSettings();
			if (NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance.GizmosPlayingChanged.Add(OnGizmosPlayingChanged);
			}
		}

		protected virtual void FixedUpdate()
		{
			UpdatePhysics();
		}

		protected override void OnDestroy()
		{
			Tool.PostReleaseEvent -= OnToolReleased;
			ConnectableTool.ParentChangedEvent -= OnParentChanged;
			ConnectableTool.ConnectionModifiedEvent -= OnConnectionModified;
			Tool.CreationObject.LockedStatusChangedEvent -= OnLockStatusChange;
			if (NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance.GizmosPlayingChanged.Remove(OnGizmosPlayingChanged);
			}
			if (Tool != null && Tool.RigidbodyEx != null)
			{
				Tool.RigidbodyEx.RemoveUpdateLodOverride(this);
			}
			base.OnDestroy();
		}

		protected virtual void SetupCreationObjectSettings()
		{
		}

		private void OnGizmosPlayingChanged(bool isPlaying)
		{
			if (!isPlaying && base.hasAuthority && !Tool.IsHeld)
			{
				AuthorityResetToDefaultState();
			}
			RefreshIsRunning();
		}

		private void OnLockStatusChange(CreationObject creationObject)
		{
			if (!creationObject.IsLocked)
			{
				ModifyNodeOnRelease();
			}
			RefreshIsRunning();
		}

		private void OnToolReleased(Tool tool)
		{
			ModifyNodeOnRelease();
		}

		private void ModifyNodeOnRelease()
		{
			if (!ConnectableTool.IsParented && base.hasAuthority)
			{
				NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.RequestMasterModifyNode(ConnectableTool, ConnectableTool.ParentConnectable, 0, 0, Tool.RigidbodyEx.targetLocalPosition, Tool.RigidbodyEx.targetLocalRotation);
			}
		}

		public void ChangeGizmoIgnition(Dictionary<InputSlot, int> input)
		{
			if (input.TryGetValue(InputSlot.R, out var value) && value != currentIgnitionValue)
			{
				currentIgnitionValue = value;
				SetIgnition(value != 0);
			}
		}

		protected void SetIgnition(bool newIgnition)
		{
			ignition = newIgnition && CanBeTurnedOn;
			RefreshIsRunning();
		}

		private void RefreshIsRunning()
		{
			bool flag = ignition && SandboxGizmoManager.GizmosPlaying && !Tool.CreationObject.IsLocked;
			if (flag != IsRunning)
			{
				IsRunning = flag;
				if (this.IsRunningChanged != null)
				{
					this.IsRunningChanged();
				}
			}
		}

		protected virtual void UpdateDefaultState(Vector3 newDefaultRelativePosition, Quaternion newDefaultRelativeRotation)
		{
			DefaultRelativePosition = newDefaultRelativePosition;
			DefaultRelativeRotation = newDefaultRelativeRotation;
			AuthorityResetToDefaultState();
		}

		public virtual void AuthorityResetToDefaultState()
		{
			if (base.hasAuthority)
			{
				Tool.RigidbodyEx.ClearVelocity();
				Tool.RigidbodyEx.targetLocalPosition = DefaultRelativePosition;
				Tool.RigidbodyEx.targetLocalRotation = DefaultRelativeRotation;
			}
		}

		protected virtual void UpdatePhysics()
		{
		}

		public virtual void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
		}

		public virtual void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
		}

		private void OnParentChanged(IConnectable childConnectable, int childConnectableSlot, IConnectable parentConnectable, int parentConnectableSlot, Vector3? relativePosition = null, Quaternion? relativeRotation = null)
		{
			UpdateDefaultState(relativePosition.Value, relativeRotation.Value);
		}

		private void OnConnectionModified(IConnectable childConnectable, int childConnectableSlot, IConnectable parentConnectable, int parentConnectableSlot, Vector3? relativePosition = null, Quaternion? relativeRotation = null)
		{
			UpdateDefaultState(relativePosition.Value, relativeRotation.Value);
		}
	}
	public class SandboxGizmoManager : NetworkedSingletonMonoBehaviour<SandboxGizmoManager>
	{
		public readonly ActionEvent<bool> GizmosPlayingChanged = new ActionEvent<bool>();

		private SynchronizedField<bool> _gizmosPlaying;

		private bool showNotificationOnPlayingChanged;

		public static bool GizmosPlaying { get; private set; }

		protected override void Awake()
		{
			base.Awake();
			_gizmosPlaying = new SynchronizedField<bool>(this, "GP", defaultValue: true, SetterPermissionMode.MASTER, OnGizmosPlayingChanged);
			OnGizmosPlayingChanged();
			showNotificationOnPlayingChanged = true;
		}

		private void Start()
		{
			NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.MasterRoomDeserializationCompleteEvent += OnMasterRoomDeserializationCompleteEvent;
		}

		private void OnMasterRoomDeserializationCompleteEvent()
		{
			if (PhotonNetwork.isMasterClient)
			{
				_gizmosPlaying.Set(newValue: true);
			}
		}

		private void OnGizmosPlayingChanged()
		{
			bool gizmosPlaying = _gizmosPlaying.Get();
			GizmosPlaying = gizmosPlaying;
			GizmosPlayingChanged.Invoke(GizmosPlaying);
			if (showNotificationOnPlayingChanged)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.Format("Gizmos now {0}", (!GizmosPlaying) ? "stopped" : "playing"), 3f);
			}
		}

		public void RequestMasterSetGizmosPlaying(bool isPlaying)
		{
			base.photonView.RpcMaster(RpcRequestMasterSetGizmosPlaying, isPlaying);
		}

		[PunRPC]
		private void RpcRequestMasterSetGizmosPlaying(bool isPlaying)
		{
			if (PhotonNetwork.isMasterClient)
			{
				_gizmosPlaying.Set(isPlaying);
			}
		}
	}
	public class SmoothLookAtGizmo : InfluencerGizmo
	{
		private enum TrackingMode
		{
			Average,
			Closest
		}

		private const float MAX_DEGREES_PER_SECOND = 1080f;

		[SerializeField]
		private CreationObjectSettingStringUIControl tagEditPrefab;

		[SerializeField]
		private Tooltip tooltip;

		private SynchronizedField<string[]> _currentTags;

		private SynchronizedField<int> _smoothingAmount;

		private SynchronizedField<int> _tagTrackingMode;

		private float exponentialSmoothing;

		public string[] CurrentTags
		{
			get
			{
				return _currentTags.Get();
			}
			set
			{
				_currentTags.Set(value);
			}
		}

		public int SmoothingAmount
		{
			get
			{
				return _smoothingAmount.Get();
			}
			set
			{
				_smoothingAmount.Set(value);
			}
		}

		private TrackingMode TagTrackingMode
		{
			get
			{
				return (TrackingMode)_tagTrackingMode.Get();
			}
			set
			{
				_tagTrackingMode.Set((int)value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_currentTags = new SynchronizedField<string[]>(this, "SLAG_CT", new string[0], SetterPermissionMode.MASTER_OR_AUTHORITY, OnCurrentTagsChanged);
			_smoothingAmount = new SynchronizedField<int>(this, "SLAG_SA", 0, SetterPermissionMode.MASTER_OR_AUTHORITY, OnSmoothingAmountChanged);
			_tagTrackingMode = new SynchronizedField<int>(this, "SLAG_TTM", 0, SetterPermissionMode.MASTER_OR_AUTHORITY);
		}

		protected override void Start()
		{
			base.Start();
			OnCurrentTagsChanged();
			OnSmoothingAmountChanged();
		}

		protected override void SetupCreationObjectSettings()
		{
			base.SetupCreationObjectSettings();
			CreationObject component = GetComponent<CreationObject>();
			StringSettingEditEvent settingEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => tagEditPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				instance.PropertyDescription.text = "Tag to Follow";
				instance.PropertyGetter = Tag_Get;
				instance.PropertySetter = Tag_Set;
			});
			component.AddConfigurableSetting(settingEvent);
			IntSettingEditEvent settingEvent2 = new IntSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultIntUIControlPrefab, delegate(CreationObjectSettingIntUIControl instance)
			{
				instance.PropertyDescription.text = "Smoothing Amount";
				instance.PropertyGetter = SmoothingAmount_Get;
				instance.PropertySetter = SmoothingAmount_Set;
			});
			component.AddConfigurableSetting(settingEvent2);
			EnumSettingEditEvent settingEvent3 = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.PropertyDescription.text = "Tracking Multiple Tagged Objects";
				instance.PropertyGetter = TagTrackingMode_Get;
				instance.PropertySetter = TagTrackingMode_Set;
			}, new Dictionary<string, EnumChoiceData>
			{
				{
					"Average",
					new EnumChoiceData
					{
						enumValue = 0
					}
				},
				{
					"Closest",
					new EnumChoiceData
					{
						enumValue = 1
					}
				}
			});
			component.AddConfigurableSetting(settingEvent3);
		}

		protected override void UpdatePhysics()
		{
			base.UpdatePhysics();
			if (base.IsRunning && CurrentTags.Length >= 1 && !base.Tool.IsHeld && base.hasAuthority)
			{
				Vector3? vector = null;
				vector = ((TagTrackingMode != TrackingMode.Average) ? GetTargetRotationByClosestTaggedObject() : GetTargetRotationByAverageTaggedObject());
				if (vector.HasValue)
				{
					Quaternion to = Quaternion.LookRotation(base.Tool.RigidbodyEx.targetPosition - vector.Value, Vector3.up);
					to *= Quaternion.Euler(270f, 0f, 0f);
					to = Quaternion.RotateTowards(base.Tool.RigidbodyEx.targetRotation, to, 1080f * UnityEngine.Time.deltaTime);
					Quaternion targetRotation = Quaternion.Lerp(base.Tool.RigidbodyEx.targetRotation, to, exponentialSmoothing);
					base.Tool.RigidbodyEx.targetRotation = targetRotation;
				}
			}
		}

		private Vector3? GetTargetRotationByClosestTaggedObject()
		{
			Vector3? result = null;
			float num = float.MaxValue;
			string[] currentTags = CurrentTags;
			foreach (string value in currentTags)
			{
				if (string.IsNullOrEmpty(value))
				{
					continue;
				}
				foreach (TaggedTool item in NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetToolsWithTag(value))
				{
					float sqrMagnitude = (item.Tool.RigidbodyEx.targetPosition - base.Tool.RigidbodyEx.targetPosition).sqrMagnitude;
					if (sqrMagnitude < num)
					{
						num = sqrMagnitude;
						result = item.Tool.RigidbodyEx.targetPosition;
					}
				}
			}
			return result;
		}

		private Vector3? GetTargetRotationByAverageTaggedObject()
		{
			Vector3 zero = Vector3.zero;
			int num = 0;
			string[] currentTags = CurrentTags;
			foreach (string value in currentTags)
			{
				if (string.IsNullOrEmpty(value))
				{
					continue;
				}
				foreach (TaggedTool item in NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetToolsWithTag(value))
				{
					zero += item.Tool.RigidbodyEx.targetPosition;
					num++;
				}
			}
			if (num > 0)
			{
				return zero / num;
			}
			return null;
		}

		private int SmoothingAmount_Get()
		{
			return SmoothingAmount;
		}

		private void SmoothingAmount_Set(int newValue)
		{
			SmoothingAmount = newValue;
			OnSmoothingAmountChanged();
		}

		private int TagTrackingMode_Get()
		{
			return (int)TagTrackingMode;
		}

		private void TagTrackingMode_Set(int newValue)
		{
			TagTrackingMode = (TrackingMode)newValue;
		}

		private string Tag_Get()
		{
			string result = string.Empty;
			if (CurrentTags.Length > 0)
			{
				result = CurrentTags[0];
			}
			return result;
		}

		private void Tag_Set(string tagName)
		{
			CurrentTags = new string[1] { ToolTagManager.FormatTag(tagName) };
		}

		private void OnSmoothingAmountChanged()
		{
			exponentialSmoothing = Mathf.Pow(2f, -Mathf.Max(0, SmoothingAmount));
		}

		private void OnCurrentTagsChanged()
		{
			tooltip.Message = string.Empty;
			if (CurrentTags.Length > 0 && !string.IsNullOrEmpty(CurrentTags[0]))
			{
				tooltip.Message = "#" + string.Join(", #", CurrentTags);
			}
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			base.SerializeTo(ref viewData, ref transientData, outputLog);
			if (viewData.SandboxGizmoData == null)
			{
				viewData.SandboxGizmoData = new SandboxGizmoData();
			}
			if (viewData.SandboxGizmoData.LookAtData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing LookAt Gizmo {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.SandboxGizmoData.LookAtData = new SmoothLookAtData
			{
				Smoothness = SmoothingAmount,
				TrackingMode = (int)TagTrackingMode,
				TagData = new TagData()
			};
			viewData.SandboxGizmoData.LookAtData.TagData.Tags.AddRange(CurrentTags);
		}

		public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			base.DeserializeFrom(deserializeParams);
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData.SandboxGizmoData == null || viewData.SandboxGizmoData.LookAtData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Rotator Gizmo {0}: gizmo data or rotator data empty.", base.gameObject);
				return;
			}
			SmoothingAmount = viewData.SandboxGizmoData.LookAtData.Smoothness;
			TagTrackingMode = (TrackingMode)viewData.SandboxGizmoData.LookAtData.TrackingMode;
			if (viewData.SandboxGizmoData.LookAtData.TagData != null)
			{
				CurrentTags = new string[viewData.SandboxGizmoData.LookAtData.TagData.Tags.Count];
				viewData.SandboxGizmoData.LookAtData.TagData.Tags.CopyTo(CurrentTags, 0);
			}
		}
	}
	public class ThrusterGizmo : AcceleratedMovementGizmo
	{
		[SerializeField]
		private float maxMovementSpeed = 10000f;

		private const float MOVEMENT_EPSILON = 1E-05f;

		private const float CENTIMETERS_TO_METERS = 0.01f;

		private const string kinematicPhysicsToken = "ThrusterKinematicPhysics";

		private float currentTargetSpeed;

		private Vector3 currentLocalForce = Vector3.zero;

		private float appliedSpeed;

		private float speedAppliedPerFrame;

		private Vector3 velocityAppliedLastFrame = Vector3.zero;

		private SynchronizedField<Vector3> _rootDefaultPosition;

		private SynchronizedField<Quaternion> _rootDefaultRotation;

		private Vector3 RootDefaultPosition
		{
			get
			{
				return _rootDefaultPosition.Get();
			}
			set
			{
				_rootDefaultPosition.Set(value);
			}
		}

		private Quaternion RootDefaultRotation
		{
			get
			{
				return _rootDefaultRotation.Get();
			}
			set
			{
				_rootDefaultRotation.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_rootDefaultPosition = new SynchronizedField<Vector3>(this, "RDP", Vector3.zero, SetterPermissionMode.AUTHORITY);
			_rootDefaultRotation = new SynchronizedField<Quaternion>(this, "RDR", Quaternion.identity, SetterPermissionMode.AUTHORITY);
			base.Tool.ConnectableTool.RootChangedEvent += OnRootChanged;
		}

		protected override void OnDestroy()
		{
			base.Tool.ConnectableTool.RootChangedEvent -= OnRootChanged;
			base.OnDestroy();
		}

		protected override void UpdateAccelerationParameters()
		{
			if (base.IsRunning)
			{
				currentTargetSpeed = Mathf.Min(maxMovementSpeed, Mathf.Abs(targetSpeedInput)) * 0.01f;
				if (targetSpeedInput < 0)
				{
					currentTargetSpeed = 0f - currentTargetSpeed;
				}
				if (!(base.AccelerationTime > 0.01f))
				{
				}
			}
			else if (base.hasAuthority)
			{
				StopMovement();
			}
		}

		protected override void UpdateInputParameters()
		{
		}

		protected override void UpdatePhysics()
		{
			base.UpdatePhysics();
			if (base.IsRunning && !base.Tool.IsHeld)
			{
				AuthorityUpdateLinearVelocity();
			}
		}

		private void AuthorityUpdateLinearVelocity()
		{
			if (base.hasAuthority)
			{
				accelerationApplicationTime += UnityEngine.Time.fixedDeltaTime;
				if (accelerationApplicationTime < base.AccelerationTime)
				{
					Vector3 force = base.Tool.ConnectableTool.RootTool.RigidbodyEx.TargetTransform.TransformVector(currentLocalForce);
					base.Tool.ConnectableTool.RootTool.RigidbodyEx.AddForce(force, ForceMode.Acceleration);
					appliedSpeed += speedAppliedPerFrame;
				}
				else
				{
					base.Tool.ConnectableTool.RootTool.RigidbodyEx.AddForce(-velocityAppliedLastFrame, ForceMode.VelocityChange);
					Vector3 force2 = currentTargetSpeed * base.Tool.RigidbodyEx.TargetTransform.up;
					base.Tool.ConnectableTool.RootTool.RigidbodyEx.AddForce(force2, ForceMode.VelocityChange);
					velocityAppliedLastFrame = force2;
				}
			}
		}

		private void StopMovement()
		{
			if (base.Tool.ConnectableTool.RootTool == base.Tool)
			{
				base.Tool.RigidbodyEx.ClearLinearVelocity();
			}
			currentTargetSpeed = 0f;
			appliedSpeed = 0f;
			currentLocalForce = Vector3.zero;
			velocityAppliedLastFrame = Vector3.zero;
		}

		protected override void UpdateDefaultState(Vector3 newDefaultRelativePosition, Quaternion newDefaultRelativeRotation)
		{
			base.DefaultRelativePosition = newDefaultRelativePosition;
			base.DefaultRelativeRotation = newDefaultRelativeRotation;
			if (base.hasAuthority && base.ConnectableTool.ParentIsTool)
			{
				Tool safeRootTool = base.ConnectableTool.GetSafeRootTool();
				if (safeRootTool != null)
				{
					RootDefaultPosition = safeRootTool.RigidbodyEx.targetPosition;
					RootDefaultRotation = safeRootTool.RigidbodyEx.targetRotation;
				}
			}
			AuthorityResetToDefaultState();
		}

		public override void AuthorityResetToDefaultState()
		{
			base.AuthorityResetToDefaultState();
			if (base.hasAuthority && base.ConnectableTool.ParentIsTool)
			{
				base.ConnectableTool.RootTool.RigidbodyEx.ClearLinearVelocity();
				base.ConnectableTool.RootTool.RigidbodyEx.targetPosition = RootDefaultPosition;
				base.ConnectableTool.RootTool.RigidbodyEx.targetRotation = RootDefaultRotation;
			}
		}

		private void OnRootChanged(IConnectable previousRootConnectable, IConnectable newRootConnectable)
		{
			Tool tool = newRootConnectable.Tool;
			if (previousRootConnectable != null)
			{
				Tool tool2 = previousRootConnectable.Tool;
				if (tool2 != null && tool2 != tool)
				{
					tool2.RigidbodyEx.SetUseKinematicForces("ThrusterKinematicPhysics", useKinematicForces: false);
				}
			}
			if (tool != null && tool != base.Tool && tool.RigidbodyEx.isKinematic)
			{
				tool.RigidbodyEx.SetUseKinematicForces("ThrusterKinematicPhysics", useKinematicForces: true);
			}
		}
	}
}
namespace RecRoom
{
	public class UniqueTreeNode<T> where T : IEquatable<T>
	{
		public delegate bool TreeTraversalOperation(UniqueTreeNode<T> node);

		public T Content;

		public LinkedList<UniqueTreeNode<T>> Children;

		public UniqueTreeNode<T> _parent;

		public UniqueTreeNode<T> Parent
		{
			get
			{
				return _parent;
			}
			set
			{
				if (_parent != value)
				{
					if (_parent != null)
					{
						_parent.Children.Remove(this);
					}
					_parent = value;
					if (_parent != null && !_parent.Children.Contains(this))
					{
						_parent.Children.AddLast(this);
					}
				}
			}
		}

		public bool IsRoot => Parent == null;

		public bool IsLeaf => Children.Count == 0;

		public UniqueTreeNode<T> Root => (!IsRoot) ? Parent.Root : this;

		public UniqueTreeNode(T nodeContent)
		{
			Content = nodeContent;
			Children = new LinkedList<UniqueTreeNode<T>>();
		}

		public UniqueTreeNode<T> AddChild(T newNodeContent)
		{
			if (FindNode(Root, newNodeContent) == null)
			{
				UniqueTreeNode<T> uniqueTreeNode = new UniqueTreeNode<T>(newNodeContent);
				uniqueTreeNode.Parent = this;
				return uniqueTreeNode;
			}
			return null;
		}

		public UniqueTreeNode<T> RemoveDescendant(T nodeContentToRemove)
		{
			UniqueTreeNode<T> uniqueTreeNode = FindNode(this, nodeContentToRemove);
			if (uniqueTreeNode != null)
			{
				if (uniqueTreeNode.IsRoot)
				{
					return null;
				}
				if (!uniqueTreeNode.IsLeaf)
				{
					UniqueTreeNode<T> root = Root;
					UniqueTreeNode<T>[] array = new UniqueTreeNode<T>[uniqueTreeNode.Children.Count];
					uniqueTreeNode.Children.CopyTo(array, 0);
					UniqueTreeNode<T>[] array2 = array;
					foreach (UniqueTreeNode<T> uniqueTreeNode2 in array2)
					{
						uniqueTreeNode2.Parent = root;
					}
				}
				uniqueTreeNode.Parent = null;
			}
			return uniqueTreeNode;
		}

		public UniqueTreeNode<T> Remove()
		{
			if (Parent != null)
			{
				return Parent.RemoveDescendant(Content);
			}
			return null;
		}

		public void Clear()
		{
			foreach (UniqueTreeNode<T> child in Children)
			{
				child.Clear();
			}
			_parent = null;
			Children.Clear();
		}

		public UniqueTreeNode<T> Reparent(T newParent)
		{
			if (FindNode(this, newParent) != null)
			{
				return null;
			}
			UniqueTreeNode<T> uniqueTreeNode = FindNode(Root, newParent);
			if (uniqueTreeNode != null)
			{
				Parent = uniqueTreeNode;
				return Parent;
			}
			return null;
		}

		public static void TraverseTree(UniqueTreeNode<T> traversalRoot, TreeTraversalOperation operation)
		{
			if (traversalRoot == null || !operation(traversalRoot))
			{
				return;
			}
			foreach (UniqueTreeNode<T> child in traversalRoot.Children)
			{
				TraverseTree(child, operation);
			}
		}

		public static string ToString(UniqueTreeNode<T> traversalRoot, int depth = 0)
		{
			string empty = string.Empty;
			string text = string.Empty;
			for (int i = 0; i < depth; i++)
			{
				text += "\t";
			}
			string text2 = empty;
			empty = text2 + text + "|-" + traversalRoot.Content.ToString() + "\n";
			foreach (UniqueTreeNode<T> child in traversalRoot.Children)
			{
				empty += ToString(child, depth + 1);
			}
			return empty;
		}

		public static UniqueTreeNode<T> FindNode(UniqueTreeNode<T> traversalRoot, T nodeContentToFind)
		{
			UniqueTreeNode<T> foundNode = null;
			TraverseTree(traversalRoot, delegate(UniqueTreeNode<T> node)
			{
				ref T content = ref node.Content;
				T other = nodeContentToFind;
				if (content.Equals(other))
				{
					foundNode = node;
					return false;
				}
				return true;
			});
			return foundNode;
		}
	}
}
namespace RecRoom.Core.Creation.Inventions
{
	public class InventionPiece
	{
		private const int INVALID_VERSION = -1;

		private const long INVALID_ID = -1L;

		private SynchronizedField<Guid> _instanceId;

		private SynchronizedField<long> _inventionId;

		private SynchronizedField<int> _versionNumber;

		private Photon.MonoBehaviour owner;

		public Guid InstanceId
		{
			get
			{
				return _instanceId.Get();
			}
			private set
			{
				_instanceId.Set(value);
			}
		}

		public long InventionId
		{
			get
			{
				return _inventionId.Get();
			}
			private set
			{
				_inventionId.Set(value);
			}
		}

		public int VersionNumber
		{
			get
			{
				return _versionNumber.Get();
			}
			private set
			{
				_versionNumber.Set(value);
			}
		}

		public bool IsTrackingInvention => InventionId != -1 && VersionNumber != -1;

		public InventionPiece(Photon.MonoBehaviour owningBehavior)
		{
			owner = owningBehavior;
			_instanceId = new SynchronizedField<Guid>(owningBehavior, "BP_IID", Guid.Empty, SetterPermissionMode.AUTHORITY);
			_inventionId = new SynchronizedField<long>(owningBehavior, "BP_BID", -1L, SetterPermissionMode.AUTHORITY);
			_versionNumber = new SynchronizedField<int>(owningBehavior, "BP_VN", -1, SetterPermissionMode.AUTHORITY);
		}

		public void AuthorityInitializePiece(Guid newInstanceId, long inventionId, int versionNumber)
		{
			if (!owner.hasAuthority)
			{
				UnityEngine.Debug.LogWarning("Tried to initialized invention tracking when not authority");
				return;
			}
			InstanceId = newInstanceId;
			InventionId = inventionId;
			VersionNumber = versionNumber;
		}

		public void DeserializeFrom(InventionPieceData data)
		{
			if (owner.hasAuthority)
			{
				Guid newInstanceId = RecRoom.Protobuf.ByteStringExtensions.ToGuid(data.InstanceId);
				long inventionId = data.InventionId;
				int versionNumber = data.VersionNumber;
				AuthorityInitializePiece(newInstanceId, inventionId, versionNumber);
			}
		}

		public void SerializeTo(InventionPieceData data)
		{
			data.InstanceId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(InstanceId);
			data.InventionId = InventionId;
			data.VersionNumber = VersionNumber;
		}

		public static InventionPieceData GenerateSerializedData(Guid instanceId, long inventionId, int versionNumer)
		{
			InventionPieceData inventionPieceData = new InventionPieceData();
			inventionPieceData.InstanceId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(instanceId);
			inventionPieceData.InventionId = inventionId;
			inventionPieceData.VersionNumber = versionNumer;
			return inventionPieceData;
		}
	}
	public class InventionSerializer
	{
		public struct SaveInventionResult
		{
			public byte[] inventionDatablobBytes;

			public List<string> persistedImageNames;

			public List<string> persistedDataBlobNames;
		}

		public const float MAX_INVENTION_EXTENTS_COMPONENT_SIZE = 1000f;

		private static List<Tool> localTemporaryInventionInstanceToolList = new List<Tool>();

		private List<PersistenceView> localTempPersistenceViewsList = new List<PersistenceView>();

		public IPromise<SpawnableTemplateData> GetInventionDataBlob(long inventionId, int versionNum)
		{
			return RecNet.Inventions.GetInventionData(inventionId, versionNum).ContinueWith((byte[] rawData) => SpawnableTemplateData.Parser.ParseFrom(rawData));
		}

		public IPromise<SpawnableTemplateData> GetInventionDataBlob(string dataBlobName)
		{
			return RecNet.Inventions.GetInventionData(dataBlobName).ContinueWith((byte[] rawData) => SpawnableTemplateData.Parser.ParseFrom(rawData));
		}

		public IPromise<InventionResponse> UploadNewInventionDataBlob(SpawnableTemplateData datablob, string name, string description, string imageName, int instantiateCost, string[] imageList, string[] dataBlobList)
		{
			return RecNet.Inventions.UploadNewInvention(datablob.ToByteArray(), name, description, imageName, instantiateCost, imageList, dataBlobList).Then(delegate(InventionResponse response)
			{
				if (response.Status != InventionResult.Success)
				{
					UnityEngine.Debug.LogFormat("[INV] Invention data blob upload failed: {0}", response.Status);
				}
				else
				{
					AnalyticsHelper.AddCustomStatsCounter("inventionAdded", 1);
					AnalyticsHelper.IgnoreCounterSamplingOnNextStatSend();
				}
			});
		}

		public IPromise<InventionResponse> UploadNewInventionVersion(SpawnableTemplateData datablob, long inventionId, int instantiateCost, string[] imageList, string[] dataBlobList)
		{
			return RecNet.Inventions.AddInventionVersion(datablob.ToByteArray(), inventionId, instantiateCost, imageList, dataBlobList).Then(delegate(InventionResponse response)
			{
				if (response.Status != InventionResult.Success)
				{
					UnityEngine.Debug.LogFormat("[INV] Invention version upload failed: {0}", response.Status);
				}
				else
				{
					AnalyticsHelper.AddCustomStatsCounter("inventionUpdated", 1);
					AnalyticsHelper.IgnoreCounterSamplingOnNextStatSend();
				}
			});
		}

		public IPromise<SaveInventionResult> MasterSaveNewInvention(IEnumerable<CreationObject> sourceObjects, PhotonPlayer requestingPlayer)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return null;
			}
			Promise<SaveInventionResult> promise = new Promise<SaveInventionResult>();
			SingletonMonoBehaviour<Scheduler>.Instance.Run(MasterSaveNewInventionCoroutine(sourceObjects, requestingPlayer, promise));
			return promise;
		}

		private IEnumerator<ISchedule> MasterSaveNewInventionCoroutine(IEnumerable<CreationObject> sourceObjects, PhotonPlayer requestingPlayer, Promise<SaveInventionResult> saveInventionPromise)
		{
			localTempPersistenceViewsList.Clear();
			foreach (CreationObject sourceObject in sourceObjects)
			{
				PersistenceView component = sourceObject.GetComponent<PersistenceView>();
				if (component != null)
				{
					localTempPersistenceViewsList.Add(component);
				}
			}
			CreationManager.SerializeTemplateResult serializationResult = null;
			string serializationError = null;
			IPromise<CreationManager.SerializeTemplateResult> serializationPromise = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SerializeSpawnableTemplate(localTempPersistenceViewsList, verboseLogging: true).Then(delegate(CreationManager.SerializeTemplateResult sr)
			{
				serializationResult = sr;
			}).Error(delegate(string e)
			{
				serializationError = e;
			});
			yield return Schedule.Until(() => serializationPromise.IsCompleted);
			if (serializationResult == null)
			{
				saveInventionPromise.Error(serializationError ?? "Unknown error");
				yield break;
			}
			ConvertTransformsToInventionSpace(serializationResult.spawnableTemplateData, requestingPlayer);
			SaveInventionResult result = new SaveInventionResult
			{
				inventionDatablobBytes = serializationResult.spawnableTemplateData.ToByteArray(),
				persistedImageNames = serializationResult.transientImages,
				persistedDataBlobNames = serializationResult.transientDataBlobs
			};
			saveInventionPromise.Complete(result);
		}

		private void ConvertTransformsToInventionSpace(SpawnableTemplateData inventionData, PhotonPlayer requestingPlayer)
		{
			Vector3 zero = Vector3.zero;
			foreach (PersistenceViewData persistenceView in inventionData.PersistenceViews)
			{
				zero += persistenceView.Transform.Position.ToVector3();
			}
			Vector3 vector = zero / inventionData.PersistenceViews.Count;
			Vector3 currentFloorPosition = requestingPlayer.ToPlayer().CurrentFloorPosition;
			Vector3 forward = (vector - currentFloorPosition).ZeroY();
			Quaternion q = Quaternion.LookRotation(forward, Vector3.up);
			Matrix4x4 inverse = Matrix4x4.TRS(vector, q, Vector3.one).inverse;
			foreach (PersistenceViewData persistenceView2 in inventionData.PersistenceViews)
			{
				Matrix4x4 matrix4x = Matrix4x4.TRS(persistenceView2.Transform.Position.ToVector3(), Quaternion.Euler(persistenceView2.Transform.Rotation.ToVector3()), persistenceView2.Transform.Scale * Vector3.one);
				Matrix4x4 matrix = inverse * matrix4x;
				persistenceView2.Transform.Position = matrix.GetPosition().ToVector3Data();
				persistenceView2.Transform.Rotation = matrix.GetRotation().eulerAngles.ToVector3Data();
			}
		}

		public static bool IsValidInventionSize(IEnumerable<CreationObject> sourceObjects)
		{
			Vector3 extents;
			return UnityExtensions.CalculateCombinedExtents(sourceObjects, out extents) && !(extents.MaxComponent() > 1000f);
		}

		public static bool IsValidInventionCost(IEnumerable<CreationObject> sourceObjects, int cost)
		{
			return cost <= 30000;
		}

		public IPromise<List<Tool>> MasterSpawnInventionInstance(long inventionId, int versionNum, string dataBlobName, Vector3 position, Quaternion rotation, float scale)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return null;
			}
			Promise<List<Tool>> promise = new Promise<List<Tool>>();
			SingletonMonoBehaviour<Scheduler>.Instance.Run(MasterSpawnInventionInstanceCoroutine(inventionId, versionNum, dataBlobName, position, rotation, scale, promise));
			return promise;
		}

		private IEnumerator<ISchedule> MasterSpawnInventionInstanceCoroutine(long inventionId, int versionNum, string dataBlobName, Vector3 position, Quaternion rotation, float scale, Promise<List<Tool>> spawnInstancePromise)
		{
			int cost = -1;
			string costError = null;
			IPromise<int> costPromise = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.GetInventionInstanceCost(inventionId, versionNum).Then(delegate(int c)
			{
				cost = c;
			}).Error(delegate(string e)
			{
				costError = e;
			});
			yield return Schedule.AfterCompleted(costPromise);
			if (!string.IsNullOrEmpty(costError))
			{
				spawnInstancePromise.Error($"Failed to retrieve cost for invention: {inventionId}.{versionNum}: {costError}");
				yield break;
			}
			if (!NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(cost))
			{
				spawnInstancePromise.Error($"Can't afford to spawn invention instance: {inventionId}.{versionNum}");
				yield break;
			}
			List<Tool> instanceTools = localTemporaryInventionInstanceToolList;
			instanceTools.Clear();
			SpawnableTemplateData inventionDataBlob = null;
			IPromise<SpawnableTemplateData> datablobPromise = GetInventionDataBlob(dataBlobName).Then(delegate(SpawnableTemplateData data)
			{
				inventionDataBlob = data;
			});
			yield return Schedule.AfterCompleted(datablobPromise);
			Guid newInstanceId = Guid.NewGuid();
			foreach (PersistenceViewData persistenceView in inventionDataBlob.PersistenceViews)
			{
				if (persistenceView.CreationObjectData != null)
				{
					persistenceView.CreationObjectData.InventionPieceData = InventionPiece.GenerateSerializedData(newInstanceId, inventionId, versionNum);
				}
			}
			CreationManager.SpawnTransformData spawnTransform = new CreationManager.SpawnTransformData
			{
				position = position,
				rotation = rotation,
				scale = scale
			};
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.MasterSpawnTemplate(inventionDataBlob, cost, assignNewIds: true, spawnTransform, verboseLogging: true).Then(delegate(CreationManager.SpawnTemplateResult result)
			{
				spawnInstancePromise.Complete(result.spawnedTools);
			}).Error(delegate(string e)
			{
				spawnInstancePromise.Error(e);
			});
		}
	}
