namespace RecRoom.Core.Creation
{
	public class NoDepthMaterialSwapper : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private Material material;

		[SerializeField]
		private Material materialNoDepth;

		[SerializeField]
		private List<Renderer> renderers = new List<Renderer>();

		[SerializeField]
		private RecRoomQualitySetting[] noDepthSettings = new RecRoomQualitySetting[2]
		{
			RecRoomQualitySetting.PS4,
			RecRoomQualitySetting.Fastest
		};

		private Material _runtimeMaterial;

		private Material _runtimeMaterialNoDepth;

		private void Start()
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
			OnQualitySettingChanged(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
			}
		}

		private void OnQualitySettingChanged(RecRoomQualitySetting setting)
		{
			if (noDepthSettings.Contains(setting))
			{
				if (_runtimeMaterialNoDepth == null)
				{
					_runtimeMaterialNoDepth = new Material(materialNoDepth);
				}
				{
					foreach (Renderer renderer in renderers)
					{
						renderer.sharedMaterial = _runtimeMaterialNoDepth;
					}
					return;
				}
			}
			if (_runtimeMaterial == null)
			{
				_runtimeMaterial = new Material(material);
			}
			foreach (Renderer renderer2 in renderers)
			{
				renderer2.sharedMaterial = _runtimeMaterial;
			}
		}
	}
