			_currentEffectIndex = new SynchronizedField<int>(this, "PE_CE", 0, SetterPermissionMode.MASTER_OR_AUTHORITY, OnCurrentEffectChanged);
			_playing = new SynchronizedField<bool>(this, "PE_P", defaultValue: false, SetterPermissionMode.ANYONE);
			_looping = new SynchronizedField<bool>(this, "PE_L", defaultValue: true, SetterPermissionMode.MASTER_OR_AUTHORITY);
			_circuitColorId = new SynchronizedField<int>(this, "PE_CC", -1, SetterPermissionMode.ANYONE);
			_effectScaleFactor = new SynchronizedField<int>(this, "PE_ESF", 0, SetterPermissionMode.ANYONE, OnEffectScaleFactorChanged);
			_animationSpeed = new SynchronizedField<int>(this, "PE_AS", 0, SetterPermissionMode.ANYONE, OnAnimationSpeedChanged);
			_useSandboxRecolor = new SynchronizedField<bool>(this, "PE_USR", defaultValue: false, SetterPermissionMode.MASTER_OR_AUTHORITY, UpdateParticleColors);
			for (int i = 0; i < particleEffects.Length; i++)
			{
				effectOptions.Add(particleEffects[i].FriendlyName, new EnumChoiceData
				{
					enumValue = i
				});
			}
		}

		private void Start()
		{
			CreationObject component = GetComponent<CreationObject>();
			if (component != null)
			{
				EnumSettingEditEvent settingEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
				{
					instance.PropertyDescription.text = "Particle Type";
					instance.PropertyGetter = CurrentEffect_Get;
					instance.PropertySetter = CurrentEffect_Set;
				}, effectOptions);
				component.AddConfigurableSetting(0, settingEvent);
				BoolSettingEditEvent settingEvent2 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Looping?";
					instance.PropertyGetter = Looping_Get;
					instance.PropertySetter = Looping_Set;
				});
				component.AddConfigurableSetting(1, settingEvent2);
				BoolSettingEditEvent settingEvent3 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Use Maker Pen Custom Colors?";
					instance.PropertyGetter = SandboxRecolorable_Get;
					instance.PropertySetter = SandboxRecolorable_Set;
				});
				component.AddConfigurableSetting(2, settingEvent3);
			}
			sandboxColorable.SandboxColorChangedEvent += UpdateParticleColors;
			OnCurrentEffectChanged();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			sandboxColorable.SandboxColorChangedEvent -= UpdateParticleColors;
			StopPlaying(release: true);
		}

		private int CurrentEffect_Get()
		{
			return CurrentEffectIndex;
		}

		private void CurrentEffect_Set(int newValue)
		{
			CurrentEffectIndex = newValue;
		}

		private bool Looping_Get()
		{
			return SandboxLooping;
		}

		private void Looping_Set(bool newValue)
		{
			SandboxLooping = newValue;
		}

		private bool SandboxRecolorable_Get()
		{
			return UseSandboxRecolor;
		}

		private void SandboxRecolorable_Set(bool newValue)
		{
			UseSandboxRecolor = newValue;
		}

		private void UpdateParticleColors()
		{
			if (CircuitColorId > 0)
			{
				int colorIndex = CircuitColorId % 15;
				Color shapeColor = ShapeSettings.GetShapeColor((ShapeColor)colorIndex);
				if ((object)activeParticles != null)
				{
					activeParticles.SetColor(shapeColor);
				}
			}
			else if (UseSandboxRecolor)
			{
				if ((object)activeParticles != null)
				{
					activeParticles.SetColor(sandboxColorable.Color);
				}
			}
			else if ((object)activeParticles != null)
			{
				activeParticles.ResetColors();
			}
		}

		private void OnEffectScaleFactorChanged()
		{
			float num = Mathf.Clamp(1f + (float)EffectScaleFactor * 0.1f, particleEffects[CurrentEffectIndex].MinScale, particleEffects[CurrentEffectIndex].MaxScale);
			activeParticles.transform.localScale = new Vector3(num, num, num);
		}

		private void OnAnimationSpeedChanged()
		{
			float simulationSpeed = Mathf.Clamp(1f + (float)AnimationSpeed * 0.1f, particleEffects[CurrentEffectIndex].MinSpeed, particleEffects[CurrentEffectIndex].MaxSpeed);
			ParticleSystem.MainModule main = activeParticles.PrimaryParticleSystem.main;
			main.simulationSpeed = simulationSpeed;
		}

		private int GetEffectIndexByGuid(Guid guid)
		{
			for (int i = 0; i < particleEffects.Length; i++)
			{
				if (particleEffects[i].Guid == guid)
				{
					return i;
				}
			}
			return 0;
		}

		private void StartPlaying()
		{
			this.SafeStopSchedule(currentParticleCoroutine);
			currentParticleCoroutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(PlayEffectRoutine());
		}

		private void StopPlaying(bool release)
		{
			if (activeParticles != null)
			{
				if (release)
				{
					activeParticles.transform.localScale = Vector3.one;
					ParticleSystem.MainModule main = activeParticles.PrimaryParticleSystem.main;
					main.simulationSpeed = 1f;
					activeParticles.Stop();
				}
				else
				{
					activeParticles.PrimaryParticleSystem.Stop();
				}
			}
			this.SafeStopSchedule(currentParticleCoroutine);
			currentParticleCoroutine = null;
		}

		private IEnumerator<ISchedule> PlayEffectRoutine()
		{
			bool? particleSystemLooping = (((object)activeParticles != null) ? new bool?(activeParticles.PrimaryParticleSystem.main.loop) : ((bool?)null));
			if ((object)activeParticles != null)
			{
				activeParticles.Play(loop: true);
			}
			while (activeParticles != null && IsPlaying && particleSystemLooping != true)
			{
				yield return Schedule.Wait(activeParticles.PrimaryParticleSystem.main.duration);
				if ((object)activeParticles != null)
				{
					activeParticles.Play(loop: true);
				}
			}
		}

		private void OnCurrentEffectChanged()
		{
			if (CurrentEffectIndex >= 0 && CurrentEffectIndex < particleEffects.Length)
			{
				StopPlaying(release: true);
				activeParticles = ObjectPool.Instance.Acquire(particleEffects[CurrentEffectIndex].Prefab);
				activeParticles.transform.parent = base.transform;
				activeParticles.transform.localPosition = Vector3.zero;
				activeParticles.transform.localRotation = Quaternion.identity;
				UpdateParticleColors();
				OnAnimationSpeedChanged();
				OnEffectScaleFactorChanged();
				if (IsPlaying)
				{
					StartPlaying();
				}
			}
		}

		public void EmitSignalReceived(Dictionary<InputSlot, int> updates)
		{
			if (updates.ContainsKey(InputSlot.C))
			{
				CircuitOn = CircuitNode.SignalToBool(updates[InputSlot.C]);
				if (CircuitOn)
				{
					StartPlaying();
				}
			}
			if (updates.ContainsKey(InputSlot.M))
			{
				CircuitColorId = updates[InputSlot.M];
				UpdateParticleColors();
			}
			if (updates.ContainsKey(InputSlot.Y))
			{
				EffectScaleFactor = updates[InputSlot.Y];
			}
			if (updates.ContainsKey(InputSlot.K))
			{
				AnimationSpeed = updates[InputSlot.K];
			}
			if (!IsPlaying)
			{
				StopPlaying(release: false);
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData != null && viewData.ParticleEmitterData != null)
			{
				SandboxLooping = viewData.ParticleEmitterData.Looping;
				UseSandboxRecolor = viewData.ParticleEmitterData.UseSandboxRecolor;
				CurrentEffectIndex = GetEffectIndexByGuid(RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.ParticleEmitterData.EffectId));
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.ParticleEmitterData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing ParticleEmitterData Object {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.ParticleEmitterData = new ParticleEmitterData
			{
				Looping = SandboxLooping,
				UseSandboxRecolor = UseSandboxRecolor,
				EffectId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(particleEffects[CurrentEffectIndex].Guid)
			};
		}
	}
	public class RCCarSandboxSet : SandboxSet
	{
		private RCCar rcCar;

		private RCCarRemoteControl remoteControl;

		protected override IEnumerable<Tool> MasterSpawnPieces()
		{
			IEnumerable<Tool> enumerable = base.MasterSpawnPieces();
			foreach (Tool item in enumerable)
			{
				RCCar component = item.GetComponent<RCCar>();
				if (component != null)
				{
					rcCar = component;
					continue;
				}
				RCCarRemoteControl component2 = item.GetComponent<RCCarRemoteControl>();
				if (component2 != null)
				{
					remoteControl = component2;
				}
			}
			if (rcCar != null && remoteControl != null)
			{
				remoteControl.ControlledObject = rcCar;
			}
			else
			{
				UnityEngine.Debug.LogError("Spawned an RCCarSandboxSet that didn't have a car or remote. Car = " + (rcCar != null) + ", Remote = " + (remoteControl != null));
			}
			return enumerable;
		}
	}
}
namespace RecRoom.Activities.Toys
{
	public class RCCar : RemoteControllable, IPunObservable
	{
		private enum JumpType
		{
			None = -1,
			Normal,
			FrontFlip,
			BackFlip,
			LeftFlip,
			RightFlip
		}

		private enum EngineState
		{
			Idle,
			Accelerating,
			Decelerating,
			Cruising
		}

		[Header("Structural")]
		[SerializeField]
		private Transform frontAxleTransform;

		[SerializeField]
		private Transform rearAxleTransform;

		[SerializeField]
		private RCCarWheel[] wheels = new RCCarWheel[4];

		[Header("Physics")]
		[SerializeField]
		private float maxSpeed = 70f;

		[SerializeField]
		private float maxBoostedSpeed = 90f;

		[SerializeField]
		private float groundThrottleAcceleration = 10f;

		[SerializeField]
		private float groundFrictionDeceleration = 0.99f;

		[Tooltip("Friction deceleration for the velocity component not aligned with the car")]
		[SerializeField]
		private FloatValueCurve groundFrictionSideDecelerationOverSpeed;

		[SerializeField]
		private float boostAcceleration = 10f;

		[SerializeField]
		[FormerlySerializedAs("angularVelocityCompensationOverSpeed")]
		private FloatValueCurve angularVelocityCompensationOverTurnAmount;

		[SerializeField]
		private FloatValueCurve steeringTorqueOverSpeed;

		[SerializeField]
		private float gravity = 9.8f;

		[SerializeField]
		private float jumpVelocity = 5f;

		[SerializeField]
		private float flipVelocityBoost = 3f;

		[SerializeField]
		private FloatValueCurve flipAngularSpeedOverTime;

		[SerializeField]
		private float jumpCooldown = 0.5f;

		[SerializeField]
		private float turnOverSpeed = 2f;

		[Tooltip("(maxPitch, maxYaw, maxRoll)")]
		[SerializeField]
		private Vector3 maxAirborneAngularVelocities = Vector3.zero;

		[Tooltip("(pitchAcceleration, yawAcceleration, rollAcceleration)")]
		[SerializeField]
		private Vector3 airborneAngularAccelerations = Vector3.zero;

		[Tooltip("Offset from the center of mass where acceleration force will be applied")]
		[SerializeField]
		private Vector3 accelerationForceOffset = Vector3.zero;

		[SerializeField]
		private Vector3 chasisCenter = Vector3.zero;

		[Header("Input")]
		[SerializeField]
		private float flickGestureSpeed = 1f;

		[Header("Collisions")]
		[SerializeField]
		private float flippedOnSideCheckDistance = 0.3f;

		[SerializeField]
		private float flippedOnRoofCheckDistance = 0.1f;

		[Header("Visuals")]
		[SerializeField]
		private ParticleSystem boostParticleSystem;

		[SerializeField]
		private float maxTurnAnimationAngle = 30f;

		[SerializeField]
		private TrailRenderer[] trails;

		[Header("Audio")]
		[SerializeField]
		private AudioSource engineAudioSource;

		[SerializeField]
		private RecRoomAudioClip acceleratingAudioClip;

		[SerializeField]
		private RecRoomAudioClip deceleratingAudioClip;

		[SerializeField]
		private RecRoomAudioClip engineLoopAudioClip;

		private const float AXIS_DEADZONE_THRESHOLD = 0.01f;

		private const float VELOCITY_STOP_THRESHOLD = 0.01f;

		private float throttleAmount;

		private float yawAmount;

		private float pitchAmount;

		private JumpType jumpToExecute = JumpType.None;

		private SynchronizedField<bool> _boosting;

		private float currentSpeed;

		private float lastJumpTime;

		private const int MAX_JUMPS = 2;

		private int jumpsLeft = 2;

		private bool wasAirborne;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private Animator animator;

		private EngineState currentEngineState;

		private static readonly int wheelSpeedId = Animator.StringToHash("WheelSpeed");

		private static readonly int wheelTurnId = Animator.StringToHash("TurnAmount");

		private bool IsBoosting
		{
			get
			{
				return _boosting.Get();
			}
			set
			{
				_boosting.Set(value);
			}
		}

		private bool IsGrounded
		{
			get
			{
				RCCarWheel[] array = wheels;
				foreach (RCCarWheel rCCarWheel in array)
				{
					if (!rCCarWheel.IsGrounded)
					{
						return false;
					}
				}
				return true;
			}
		}

		private bool IsFlipped => Physics.Raycast(base.transform.TransformPoint(chasisCenter), base.transform.up, flippedOnRoofCheckDistance, 2048, QueryTriggerInteraction.Ignore) || Physics.Raycast(base.transform.TransformPoint(chasisCenter), base.transform.right, flippedOnSideCheckDistance, 2048, QueryTriggerInteraction.Ignore) || Physics.Raycast(base.transform.TransformPoint(chasisCenter), -base.transform.right, flippedOnSideCheckDistance, 2048, QueryTriggerInteraction.Ignore);

		private bool CanJump
		{
			get
			{
				return jumpsLeft > 0 && jumpToExecute == JumpType.None;
			}
			set
			{
				if (value)
				{
					jumpsLeft = 2;
				}
				else
				{
					jumpsLeft = 0;
				}
			}
		}

		private float WheelSpeed { get; set; }

		private float TurnAmount { get; set; }

		protected override void Awake()
		{
			base.Awake();
			if (frontAxleTransform == null || rearAxleTransform == null)
			{
				UnityEngine.Debug.LogError("Car's axle transforms are not defined.");
			}
			_boosting = new SynchronizedField<bool>(this, "B", defaultValue: false, SetterPermissionMode.AUTHORITY, OnBoostingChanged);
			RCCarWheel[] array = wheels;
			foreach (RCCarWheel rCCarWheel in array)
			{
				rCCarWheel.MaxSuspensionForce = base.RigidbodyEx.UnityRigidbody.mass * gravity;
			}
			base.RigidbodyEx.localCenterOfMass = Vector3.zero;
			base.Tool.AlwaysPhysicalPickupOffCenter = true;
			base.TeamColorRenderer.ColorChangeEvent += OnCarColorChange;
		}

		private void Update()
		{
			UpdateAnimation();
			UpdateAudio();
		}

		private void FixedUpdate()
		{
			UpdatePhysics();
		}

		protected override void OnDestroy()
		{
			base.TeamColorRenderer.ColorChangeEvent -= OnCarColorChange;
			base.OnDestroy();
		}

		private void UpdatePhysics()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			float lossyUniformScale = base.transform.GetLossyUniformScale();
			UpdateSuspension();
			if (IsGrounded)
			{
				if (wasAirborne)
				{
					CanJump = true;
				}
				wasAirborne = false;
				base.RigidbodyEx.localCenterOfMass = Vector3.zero;
				Vector3 vector = Vector3.Project(base.RigidbodyEx.velocity, base.transform.forward);
				Vector3 vector2 = Vector3.Project(base.RigidbodyEx.velocity, base.transform.right);
				Vector3 position = base.transform.TransformPoint(accelerationForceOffset);
				Vector3 vector3 = ((!(pitchAmount < -0.6f)) ? base.transform.forward : (-base.transform.forward));
				Vector3 vector4 = Vector3.ProjectOnPlane(vector3, wheels[0].LatestRaycastHit.normal);
				if (currentSpeed < maxSpeed && Mathf.Abs(throttleAmount) > 0.01f)
				{
					Vector3 force = vector4 * groundThrottleAcceleration * throttleAmount;
					base.RigidbodyEx.AddForceAtPosition(force, position, ForceMode.Acceleration);
				}
				else
				{
					Vector3 vector5 = -vector.normalized * groundFrictionDeceleration;
					if ((vector5 * UnityEngine.Time.fixedDeltaTime).sqrMagnitude > vector.sqrMagnitude)
					{
						vector5 = Vector3.zero;
						base.RigidbodyEx.velocity -= vector5;
					}
					base.RigidbodyEx.AddForceAtPosition(vector5, position, ForceMode.Acceleration);
				}
				if (Mathf.Abs(yawAmount) > 0.01f && vector.sqrMagnitude > 0.01f)
				{
					bool flag = Vector3.Dot(base.RigidbodyEx.velocity, base.transform.forward) >= 0f;
					Vector3 vector6 = base.transform.up * steeringTorqueOverSpeed.EvaluateNonNormalized(currentSpeed) * ((!flag) ? (0f - yawAmount) : yawAmount);
					base.RigidbodyEx.AddTorque(vector6 * lossyUniformScale);
				}
				Vector3 vector7 = -vector2.normalized * groundFrictionSideDecelerationOverSpeed.EvaluateNonNormalized(currentSpeed);
				if ((vector7 * UnityEngine.Time.fixedDeltaTime).sqrMagnitude > vector2.sqrMagnitude)
				{
					base.RigidbodyEx.velocity -= vector2;
				}
				else
				{
					base.RigidbodyEx.AddForceAtPosition(vector7, position, ForceMode.Acceleration);
				}
				Vector3 vector8 = (float)((!(base.RigidbodyEx.angularVelocity.y >= 0f)) ? 1 : (-1)) * angularVelocityCompensationOverTurnAmount.EvaluateNonNormalized(Mathf.Abs(yawAmount)) * base.transform.up;
				vector8 /= lossyUniformScale;
				if (Mathf.Abs(vector8.y * UnityEngine.Time.fixedDeltaTime) > Mathf.Abs(base.RigidbodyEx.angularVelocity.y))
				{
					Vector3 angularVelocity = base.RigidbodyEx.angularVelocity;
					angularVelocity.y = 0f;
					base.RigidbodyEx.angularVelocity = angularVelocity;
				}
				else
				{
					base.RigidbodyEx.angularVelocity += vector8 * UnityEngine.Time.fixedDeltaTime;
				}
				currentSpeed = base.RigidbodyEx.velocity.magnitude;
				currentSpeed = Mathf.Min(maxBoostedSpeed, currentSpeed);
				if (currentSpeed < 0.01f)
				{
					base.RigidbodyEx.velocity = Vector3.zero;
				}
			}
			else if (IsFlipped)
			{
				if (throttleAmount > 0.01f)
				{
					base.RigidbodyEx.localCenterOfMass = -Vector3.up * 2f;
					base.RigidbodyEx.UnityRigidbody.AddRelativeForce(turnOverSpeed, 0f, 0f, ForceMode.Acceleration);
				}
			}
			else
			{
				base.RigidbodyEx.localCenterOfMass = Vector3.zero;
				wasAirborne = true;
				Vector3 direction = base.transform.InverseTransformDirection(base.RigidbodyEx.angularVelocity);
				if (Mathf.Abs(pitchAmount) > 0.01f)
				{
					direction.x = Mathf.Min(direction.x + UnityEngine.Time.fixedDeltaTime * airborneAngularAccelerations.x * pitchAmount, maxAirborneAngularVelocities.x);
				}
				if (Mathf.Abs(yawAmount) > 0.01f)
				{
					direction.y = Mathf.Min(direction.y + UnityEngine.Time.fixedDeltaTime * airborneAngularAccelerations.y * yawAmount, maxAirborneAngularVelocities.y);
				}
				base.RigidbodyEx.angularVelocity = base.transform.TransformDirection(direction);
			}
			if (jumpToExecute != JumpType.None)
			{
				switch (jumpToExecute)
				{
				case JumpType.Normal:
					base.RigidbodyEx.AddForce(jumpVelocity * Vector3.up, ForceMode.VelocityChange);
					break;
				case JumpType.FrontFlip:
					base.RigidbodyEx.AddForce(flipVelocityBoost * Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized, ForceMode.VelocityChange);
					break;
				}
				if (jumpToExecute != JumpType.Normal)
				{
					StartCoroutine(PerformCarFlip(jumpToExecute));
				}
				lastJumpTime = UnityEngine.Time.time;
				jumpToExecute = JumpType.None;
			}
			if (IsBoosting)
			{
				base.RigidbodyEx.AddForce(boostAcceleration * base.transform.forward, ForceMode.Acceleration);
			}
			base.RigidbodyEx.velocity -= UnityEngine.Time.fixedDeltaTime * gravity * Vector3.up;
		}

		private void UpdateSuspension()
		{
			RCCarWheel[] array = wheels;
			foreach (RCCarWheel rCCarWheel in array)
			{
				if (rCCarWheel.UpdateSuspension())
				{
					base.RigidbodyEx.AddForceAtPosition(rCCarWheel.CurrentSuspensionForce, rCCarWheel.transform.position, ForceMode.Force);
				}
			}
		}

		private IEnumerator PerformCarFlip(JumpType flipType)
		{
			float flipTime = 0f;
			while (flipTime < flipAngularSpeedOverTime.Duration)
			{
				Vector3 angularVelocity = base.transform.InverseTransformDirection(base.RigidbodyEx.angularVelocity);
				float angularVelocityDelta = flipAngularSpeedOverTime.EvaluateNonNormalized(flipTime) * UnityEngine.Time.deltaTime;
				switch (flipType)
				{
				case JumpType.FrontFlip:
					angularVelocity.x += angularVelocityDelta;
					break;
				case JumpType.RightFlip:
					angularVelocity.z -= angularVelocityDelta;
					break;
				case JumpType.LeftFlip:
					angularVelocity.z += angularVelocityDelta;
					break;
				case JumpType.BackFlip:
					angularVelocity.x -= angularVelocityDelta;
					break;
				}
				base.RigidbodyEx.angularVelocity += base.transform.TransformDirection(angularVelocity);
				flipTime += UnityEngine.Time.fixedDeltaTime;
				yield return new WaitForFixedUpdate();
			}
		}

		private void UpdateAnimation()
		{
			if (base.hasAuthority)
			{
				if (IsGrounded)
				{
					WheelSpeed = ((!(Vector3.Dot(base.RigidbodyEx.velocity, base.transform.forward) >= 0f)) ? (0f - currentSpeed) : currentSpeed) / wheels[0].Circumference;
				}
				else
				{
					WheelSpeed = throttleAmount * maxSpeed / wheels[0].Circumference;
				}
				TurnAmount = yawAmount * maxTurnAnimationAngle;
			}
			animator.SetFloat(wheelSpeedId, WheelSpeed);
			animator.SetFloat(wheelTurnId, TurnAmount);
		}

		private void UpdateAudio()
		{
			switch (currentEngineState)
			{
			case EngineState.Idle:
				if (throttleAmount > 0.01f)
				{
					engineAudioSource.clip = acceleratingAudioClip.audioClip;
					engineAudioSource.time = 0f;
					engineAudioSource.loop = false;
					currentEngineState = EngineState.Accelerating;
				}
				break;
			case EngineState.Accelerating:
				if (throttleAmount > 0.01f)
				{
					if (!engineAudioSource.isPlaying)
					{
						engineAudioSource.clip = engineLoopAudioClip.audioClip;
						engineAudioSource.time = 0f;
						engineAudioSource.loop = true;
						currentEngineState = EngineState.Cruising;
					}
				}
				else
				{
					float num2 = engineAudioSource.time / engineAudioSource.clip.length;
					engineAudioSource.clip = deceleratingAudioClip.audioClip;
					engineAudioSource.time = Mathf.Max(0f, Mathf.Min(1f - num2, 0.99f)) * engineAudioSource.clip.length;
					engineAudioSource.loop = false;
					currentEngineState = EngineState.Decelerating;
				}
				break;
			case EngineState.Cruising:
				if (throttleAmount <= 0.01f)
				{
					engineAudioSource.clip = deceleratingAudioClip.audioClip;
					engineAudioSource.time = 0f;
					engineAudioSource.loop = false;
					currentEngineState = EngineState.Decelerating;
				}
				break;
			case EngineState.Decelerating:
				if (throttleAmount > 0.01f)
				{
					float num = engineAudioSource.time / engineAudioSource.clip.length;
					engineAudioSource.clip = acceleratingAudioClip.audioClip;
					engineAudioSource.time = Mathf.Max(0f, Mathf.Min(1f - num, 0.99f)) * engineAudioSource.clip.length;
					engineAudioSource.loop = false;
					currentEngineState = EngineState.Accelerating;
				}
				else if (!engineAudioSource.isPlaying)
				{
					currentEngineState = EngineState.Idle;
				}
				break;
			}
			if (currentEngineState != EngineState.Idle && !engineAudioSource.isPlaying)
			{
				engineAudioSource.Play();
			}
		}

		private void OnBoostingChanged()
		{
			if (IsBoosting)
			{
				boostParticleSystem.Play();
			}
			else
			{
				boostParticleSystem.Stop();
			}
		}

		private void OnCarColorChange()
		{
			if (trails != null)
			{
				TrailRenderer[] array = trails;
				foreach (TrailRenderer trailRenderer in array)
				{
					trailRenderer.startColor = base.TeamColorRenderer.Color;
					trailRenderer.endColor = base.TeamColorRenderer.Color;
				}
			}
		}

		public override void LocalUpdateRemoteControlInput(PlayerHand holderHand, Vector3 controlStickAxis, float triggerAxis, bool mainButtonPressed)
		{
			base.LocalUpdateRemoteControlInput(holderHand, controlStickAxis, triggerAxis, mainButtonPressed);
			if (!base.hasAuthority)
			{
				return;
			}
			throttleAmount = triggerAxis;
			yawAmount = controlStickAxis.x;
			pitchAmount = controlStickAxis.y;
			IsBoosting = mainButtonPressed;
			if (CanJump && UnityEngine.Time.time - lastJumpTime > jumpCooldown)
			{
				float num = flickGestureSpeed * flickGestureSpeed;
				Vector3 handOnlyVelocity = holderHand.HandOnlyVelocity;
				if (Vector3.Dot(handOnlyVelocity, holderHand.transform.up) > 0f && Vector3.Project(handOnlyVelocity, holderHand.transform.up).sqrMagnitude > num)
				{
					jumpToExecute = JumpType.Normal;
					jumpsLeft--;
				}
			}
		}

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (stream.isReading)
			{
				throttleAmount = (float)stream.ReceiveNext();
				WheelSpeed = (float)stream.ReceiveNext();
				TurnAmount = (float)stream.ReceiveNext();
			}
			else
			{
				stream.SendNext(throttleAmount);
				stream.SendNext(WheelSpeed);
				stream.SendNext(TurnAmount);
			}
		}

		private void OnDrawGizmos()
		{
			Gizmos.color = Color.cyan;
			Gizmos.DrawRay(base.transform.TransformPoint(chasisCenter), base.transform.up * flippedOnRoofCheckDistance);
			Gizmos.DrawRay(base.transform.TransformPoint(chasisCenter), base.transform.right * flippedOnSideCheckDistance);
			Gizmos.DrawRay(base.transform.TransformPoint(chasisCenter), -base.transform.right * flippedOnSideCheckDistance);
			Gizmos.DrawSphere(base.transform.TransformPoint(accelerationForceOffset), 0.02f);
		}
	}
	public class RCCarRemoteControl : Photon.MonoBehaviour, IPersistable, IPostDeserializationPersistable
	{
		[SerializeField]
		private RemoteControllable controlledObject;

		[SerializeField]
		private Transform resetControlledObjectTransform;

		[SerializeField]
		private CollisionForwarder leftResetButtonForwarder;

		[SerializeField]
		private CollisionForwarder rightResetButtonForwarder;

		[Header("Screen")]
		[SerializeField]
		private Renderer screenRenderer;

		[SerializeField]
		private int screenMaterialIndex;

		[SerializeField]
		private Material screenRenderMaterial;

		[SerializeField]
		private Material defaultScreenMaterial;

		[SerializeField]
		private CollisionForwarder screenButtonForwarder;

		[SerializeField]
		private Vector2 resolution = new Vector2(480f, 270f);

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private RemoteControlAnimation rcAnimation;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private TeamColorRenderer teamColorRenderer;

		private SynchronizedField<int> _controlledObjectPvId;

		private Material screenRenderMaterialCopy;

		private RenderTexture renderTexture;

		private float nextScreenButtonPressTime;

		private float nextResetButtonPressTime;

		private Guid persistedControlledViewGuid;

		public Tool Tool => _tool;

		public RemoteControllable ControlledObject
		{
			get
			{
				return controlledObject;
			}
			set
			{
				if (value == null)
				{
					_controlledObjectPvId.Set(-1);
				}
				else
				{
					_controlledObjectPvId.Set(value.photonView.viewID);
				}
			}
		}

		public bool HasControlledObject { get; private set; }

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			_controlledObjectPvId = new SynchronizedField<int>(this, "RC_CO", -1, SetterPermissionMode.ANYONE, OnControlledObjectIdChanged);
			Tool.SupportsRemoteControlInput = true;
			Tool.PostPickupEvent += OnPickup;
			Tool.PreReleaseEvent += OnRelease;
			Tool.RemoteControlInputEvent += OnRemoteControlInput;
			teamColorRenderer.ColorChangeEvent += OnTeamColorChange;
			renderTexture = new RenderTexture((int)resolution.x, (int)resolution.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			screenRenderMaterialCopy = new Material(screenRenderMaterial);
			screenRenderMaterialCopy.mainTexture = renderTexture;
		}

		private void Start()
		{
			OnTeamColorChange();
			OnControlledObjectIdChanged();
			if (screenButtonForwarder != null)
			{
				screenButtonForwarder.TriggerEnter += ScreenButtonForwarder_TriggerEnter;
			}
			if (leftResetButtonForwarder != null)
			{
				leftResetButtonForwarder.TriggerEnter += delegate(Collider c)
				{
					ResetButtonForwarder_TriggerEnter(c, leftButton: true);
				};
			}
			if (rightResetButtonForwarder != null)
			{
				rightResetButtonForwarder.TriggerEnter += delegate(Collider c)
				{
					ResetButtonForwarder_TriggerEnter(c, leftButton: false);
				};
			}
		}

		private void OnRemoteControlInput(Tool thisTool, Vector2 controlStickAxis, float triggerAxis, bool mainButtonPressed)
		{
			if (Tool.IsHeldByPlayer && Tool.HolderPlayer == Player.LocalPlayer)
			{
				if (HasControlledObject)
				{
					controlledObject.LocalUpdateRemoteControlInput(Tool.HolderHand, controlStickAxis, triggerAxis, mainButtonPressed);
				}
				rcAnimation.UpdateAnimationState(controlStickAxis, triggerAxis, mainButtonPressed);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Tool.PostPickupEvent -= OnPickup;
			Tool.PreReleaseEvent -= OnRelease;
			Tool.RemoteControlInputEvent -= OnRemoteControlInput;
			teamColorRenderer.ColorChangeEvent -= OnTeamColorChange;
			if (controlledObject != null)
			{
				controlledObject.Tool.PostResetEvent -= OnCarReset;
			}
		}

		private void OnPickup(Tool thisTool)
		{
			if (Tool.HolderView.isLocal && HasControlledObject)
			{
				if (!controlledObject.hasAuthority && !controlledObject.Tool.IsHeld)
				{
					controlledObject.photonView.TransferOwnership(Tool.owner);
				}
				if (controlledObject.RemoteFollowCamera != null && controlledObject.RemoteFollowCamera.CurrentFollowMode != RemoteFollowCamera.FollowMode.None)
				{
					controlledObject.RemoteFollowCamera.gameObject.SetActive(value: true);
					SetScreenMaterial(screenRenderMaterialCopy);
				}
			}
			if (HasControlledObject)
			{
				controlledObject.Tool.ToolCleanup.PauseCleanup(this);
			}
		}

		private void OnRelease(Tool thisTool)
		{
			if (Tool.HolderView.isLocal && HasControlledObject && controlledObject.RemoteFollowCamera != null)
			{
				controlledObject.RemoteFollowCamera.gameObject.SetActive(value: false);
				SetScreenMaterial(defaultScreenMaterial);
			}
			if (HasControlledObject)
			{
				controlledObject.Tool.ToolCleanup.ResumeCleanup(this);
			}
		}

		private void OnControlledObjectIdChanged()
		{
			int viewID = _controlledObjectPvId.Get();
			PhotonView photonView = PhotonView.Find(viewID);
			RemoteControllable remoteControllable = ((!(photonView != null)) ? null : photonView.GetComponent<RemoteControllable>());
			if (controlledObject != null && controlledObject != remoteControllable)
			{
				controlledObject.Tool.PostResetEvent -= OnCarReset;
			}
			controlledObject = remoteControllable;
			if (controlledObject != null)
			{
				controlledObject.Tool.PostResetEvent += OnCarReset;
				controlledObject.Tool.DestroyEvent += OnCarDestroyed;
				if (controlledObject.RemoteFollowCamera != null)
				{
					controlledObject.RemoteFollowCamera.Camera.targetTexture = renderTexture;
				}
				HasControlledObject = true;
			}
			else
			{
				HasControlledObject = false;
			}
		}

		public void AuthorityResetCar()
		{
			if (Tool.hasAuthority && HasControlledObject && controlledObject.hasAuthority && !ControlledObject.Tool.IsFrozen)
			{
				controlledObject.Tool.AuthorityResetToDefault(resetControlledObjectTransform.position, Quaternion.identity, sleepPhysics: true);
			}
		}

		private void ScreenButtonForwarder_TriggerEnter(Collider other)
		{
			if (Tool.IsHeldByPlayer && Tool.hasAuthority && ControlledObject != null && ControlledObject.RemoteFollowCamera != null && UnityEngine.Time.time > nextScreenButtonPressTime)
			{
				PlayerHand colliderPlayerHand = other.GetColliderPlayerHand();
				if (colliderPlayerHand != null && colliderPlayerHand != Tool.HolderHand && colliderPlayerHand.isLocal && colliderPlayerHand.MenuHandVisualsActive)
				{
					nextScreenButtonPressTime = UnityEngine.Time.time + 1f;
					RemoteFollowCamera.FollowMode followMode = ControlledObject.RemoteFollowCamera.CycleFollowMode();
					bool flag = followMode != RemoteFollowCamera.FollowMode.None;
					controlledObject.RemoteFollowCamera.gameObject.SetActive(flag);
					SetScreenMaterial((!flag) ? defaultScreenMaterial : screenRenderMaterialCopy);
				}
			}
		}

		private void ResetButtonForwarder_TriggerEnter(Collider other, bool leftButton)
		{
			if (!Tool.IsHeld || !Tool.hasAuthority || !(UnityEngine.Time.time > nextResetButtonPressTime))
			{
				return;
			}
			PlayerHand colliderPlayerHand = other.GetColliderPlayerHand();
			if (colliderPlayerHand != null && colliderPlayerHand != Tool.HolderHand && colliderPlayerHand.ThisPlayer == Tool.HolderPlayer)
			{
				nextResetButtonPressTime = UnityEngine.Time.time + 1f;
				AuthorityResetCar();
				if (leftButton)
				{
					rcAnimation.PressLeftVirtualButton();
				}
				else
				{
					rcAnimation.PressRightVirtualButton();
				}
			}
		}

		public void OnCarReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (HasControlledObject && controlledObject.hasAuthority && wasCleanedUp)
			{
				controlledObject.transform.position = resetControlledObjectTransform.position;
				controlledObject.transform.rotation = Quaternion.identity;
			}
		}

		public void OnCarDestroyed(Tool thisTool)
		{
			ControlledObject = null;
		}

		private void OnTeamColorChange()
		{
			if (HasControlledObject && controlledObject.hasAuthority)
			{
				controlledObject.TeamColorRenderer.Team = teamColorRenderer.Team;
			}
		}

		private void SetScreenMaterial(Material material)
		{
			Material[] sharedMaterials = screenRenderer.sharedMaterials;
			sharedMaterials[screenMaterialIndex] = material;
			screenRenderer.sharedMaterials = sharedMaterials;
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.RemoteControlData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing RCCarRemoteControl {0}: data empty.", base.gameObject);
				return;
			}
			Dictionary<Guid, Guid> persistenceViewIdMappings = deserializeParams.persistenceViewIdMappings;
			Guid key = RecRoom.Protobuf.ByteStringExtensions.ToGuid(deserializeParams.viewData.RemoteControlData.ControlledObjectViewId);
			if (persistenceViewIdMappings != null && persistenceViewIdMappings.ContainsKey(key))
			{
				key = persistenceViewIdMappings[key];
			}
			persistedControlledViewGuid = key;
		}

		public void PostDeserialize(Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			if (!(persistedControlledViewGuid != Guid.Empty))
			{
				return;
			}
			if (PersistenceView.AllViews.TryGetValue(persistedControlledViewGuid, out var value))
			{
				RemoteControllable component = value.GetComponent<RemoteControllable>();
				if (component != null)
				{
					ControlledObject = component;
					return;
				}
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing RCCarRemoteControl {0}: Controlled object {1} is not a RemoteControllable.", base.gameObject, value);
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing RCCarRemoteControl {0}: Could not find controllable PersistenceView with ID {1}.", base.gameObject, persistedControlledViewGuid);
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.RemoteControlData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing RCCarRemoteControl {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.RemoteControlData = new RemoteControlData();
			if (HasControlledObject)
			{
				PersistenceView component = controlledObject.GetComponent<PersistenceView>();
				if (component == null)
				{
					UnityEngine.Debug.LogFormat(this, "Serializing RCCarRemoteControl {0}: Controlled PhotonView {1} has no corresponding PersistenceView.", base.gameObject, controlledObject.gameObject);
				}
				else
				{
					viewData.RemoteControlData.ControlledObjectViewId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(component.Id);
				}
			}
		}
	}
}
namespace RecRoom
{
	public class RCCarWheel : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private float suspensionLength = 0.35f;

		[SerializeField]
		private float suspensionDamping = 10f;

		[SerializeField]
		private Transform meshTransform;

		[SerializeField]
		private float wheelRadius = 0.15f;

		private float previousCompression;

		private RaycastHit latestRaycastHit;

		private float cachedLossyScale = 1f;

		public float MaxSuspensionForce { get; set; }

		public RaycastHit LatestRaycastHit => latestRaycastHit;

		public float Circumference => 2f * wheelRadius * cachedLossyScale * (float)Math.PI;

		public Vector3 CurrentDampingForce => base.transform.up * suspensionDamping * (previousCompression - CurrentSuspensionCompression) * suspensionLength * cachedLossyScale / UnityEngine.Time.fixedDeltaTime;

		public Vector3 CurrentSuspensionForce => MaxSuspensionForce * CurrentSuspensionCompression * base.transform.up - CurrentDampingForce;

		public float CurrentSuspensionCompression => 1f - LatestRaycastHit.distance / (suspensionLength * cachedLossyScale);

		public bool IsGrounded => LatestRaycastHit.collider != null;

		private void Update()
		{
			cachedLossyScale = base.transform.GetLossyUniformScale();
		}

		public bool UpdateSuspension()
		{
			float num = cachedLossyScale * suspensionLength;
			float num2 = cachedLossyScale * wheelRadius;
			previousCompression = CurrentSuspensionCompression;
			bool flag = Physics.Raycast(base.transform.position, -base.transform.up, out latestRaycastHit, num, 3073, QueryTriggerInteraction.Ignore);
			if (flag && meshTransform != null)
			{
				meshTransform.position = base.transform.position - base.transform.up * (num * (1f - CurrentSuspensionCompression) - num2);
			}
			return flag;
		}

		private void OnDrawGizmos()
		{
			Vector3 position = base.transform.position;
			Gizmos.color = Color.red;
			Gizmos.DrawLine(position, position - base.transform.up * suspensionLength);
			if (LatestRaycastHit.collider != null)
			{
				Gizmos.DrawSphere(LatestRaycastHit.point, 0.01f);
			}
		}
	}
}
namespace RecRoom.Tools
{
	public class RemoteControlAnimation : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private Transform leftControlStickTransform;

		[SerializeField]
		private Transform rightControlStickTransform;

		[SerializeField]
		private float maxControlStickAngle = 30f;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private Animator _animator;

		private static readonly int leftTriggerId = Animator.StringToHash("TriggerPressAmount");

		private static readonly int leftMainButtonId = Animator.StringToHash("MainButtonPressed");

		private static readonly int leftVirtualButtonId = Animator.StringToHash("VirtualButtonPressed");

		private static readonly int rightTriggerId = Animator.StringToHash("TriggerPressAmountRight");

		private static readonly int rightMainButtonId = Animator.StringToHash("MainButtonPressedRight");

		private static readonly int rightVirtualButtonId = Animator.StringToHash("VirtualButtonPressedRight");

		private bool pressedLeftVirtualButton;

		private bool pressedRightVirtualButton;

		private PlayerHand.HandType holdingHand;

		public Tool Tool => _tool;

		public Animator Animator => _animator;

		private void Awake()
		{
			Tool.PostPickupEvent += OnToolPickup;
		}

		public void PressLeftVirtualButton()
		{
			pressedLeftVirtualButton = true;
		}

		public void PressRightVirtualButton()
		{
			pressedRightVirtualButton = true;
		}

		public void UpdateAnimationState(Vector2 thumbstickAxis, float triggerAxis, bool mainButtonPressed)
		{
			if (pressedLeftVirtualButton)
			{
				Animator.SetTrigger(leftVirtualButtonId);
				pressedLeftVirtualButton = false;
			}
			if (pressedRightVirtualButton)
			{
				Animator.SetTrigger(rightVirtualButtonId);
				pressedRightVirtualButton = false;
			}
			int id = ((holdingHand != PlayerHand.HandType.Right) ? leftTriggerId : rightTriggerId);
			Animator.SetFloat(id, triggerAxis);
			int id2 = ((holdingHand != PlayerHand.HandType.Right) ? leftMainButtonId : rightMainButtonId);
			Animator.SetBool(id2, mainButtonPressed);
			Transform transform = ((holdingHand != PlayerHand.HandType.Right) ? leftControlStickTransform : rightControlStickTransform);
			Vector2 vector = maxControlStickAngle * thumbstickAxis;
			transform.localRotation = ((holdingHand != PlayerHand.HandType.Left) ? Quaternion.Euler(180f - vector.y, 0f - vector.x, 0f) : Quaternion.Euler(0f - vector.y, 0f - vector.x, 0f));
		}

		private void OnToolPickup(Tool tool)
		{
			holdingHand = tool.HolderHand.Type;
		}
	}
