public class RemoteFollowCamera : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class PlacementOffset
	{
		public Vector3 position;

		[SerializeField]
		private Vector3 rotationEuler;

		private Quaternion? _rotation;

		public Quaternion rotation
		{
			get
			{
				Quaternion? quaternion = _rotation;
				if (!quaternion.HasValue)
				{
					_rotation = Quaternion.Euler(rotationEuler);
				}
				return _rotation.Value;
			}
		}
	}

	public enum FollowMode
	{
		None,
		Default,
		ThirdPerson,
		BirdsEye
	}

	[Header("Camera")]
	[SerializeField]
	private Transform targetTransform;

	[SerializeField]
	private Camera camera;

	[Header("Smoothing")]
	[SerializeField]
	private float positionSmoothingTime = 0.05f;

	[SerializeField]
	private float rotationSmoothingTime = 0.05f;

	[Header("Follow")]
	[SerializeField]
	private FollowMode currentFollowMode = FollowMode.Default;

	[SerializeField]
	private PlacementOffset thirdPersonPlacementOffset;

	[SerializeField]
	private PlacementOffset birdsEyePlacementOffset;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private Vector3 movePosition = Vector3.zero;

	private Quaternion moveRotation = Quaternion.identity;

	private Vector3 defaultLocalPosition = Vector3.zero;

	private Quaternion defaultLocalRotation = Quaternion.identity;

	public Camera Camera => camera;

	public FollowMode CurrentFollowMode => currentFollowMode;

	private void Awake()
	{
		defaultLocalPosition = targetTransform.InverseTransformPoint(base.transform.position);
		defaultLocalRotation = targetTransform.InverseTransformRotation(base.transform.rotation);
		base.transform.SetParent(targetTransform.parent, worldPositionStays: false);
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null && (SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting == RecRoomQualitySetting.PS4 || SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting == RecRoomQualitySetting.Fastest))
		{
			currentFollowMode = FollowMode.None;
		}
	}

	private void OnEnable()
	{
		currentFollowMode = FollowMode.Default;
		if (targetTransform != null)
		{
			base.transform.position = targetTransform.TransformPoint(defaultLocalPosition);
			base.transform.rotation = targetTransform.TransformRotation(defaultLocalRotation);
		}
	}

	private void LateUpdate()
	{
		if (targetTransform == null)
		{
			base.gameObject.SetActive(value: false);
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		Quaternion quaternion = Quaternion.Euler(0f, targetTransform.rotation.eulerAngles.y, 0f);
		switch (currentFollowMode)
		{
		case FollowMode.Default:
			movePosition = targetTransform.TransformPoint(defaultLocalPosition);
			moveRotation = targetTransform.TransformRotation(defaultLocalRotation);
			break;
		case FollowMode.BirdsEye:
			movePosition = targetTransform.position + quaternion * birdsEyePlacementOffset.position;
			moveRotation = Quaternion.LookRotation(targetTransform.position - base.transform.position) * birdsEyePlacementOffset.rotation;
			break;
		case FollowMode.ThirdPerson:
			movePosition = targetTransform.position + quaternion * thirdPersonPlacementOffset.position;
			moveRotation = quaternion * thirdPersonPlacementOffset.rotation;
			break;
		}
		if (currentFollowMode != FollowMode.Default)
		{
			base.transform.position = Vector3.SmoothDamp(base.transform.position, movePosition, ref velocity, positionSmoothingTime);
			base.transform.rotation = UnityExtensions.SmoothDamp(base.transform.rotation, moveRotation, ref rotationVelocity, rotationSmoothingTime);
		}
		else
		{
			base.transform.position = movePosition;
			base.transform.rotation = moveRotation;
		}
	}

	public FollowMode CycleFollowMode()
	{
		currentFollowMode = (FollowMode)((int)(currentFollowMode + 1) % System.Enum.GetNames(typeof(FollowMode)).Length);
		return currentFollowMode;
	}
}
namespace RecRoom.Core.Creation
