	public class SandboxColorable : Photon.MonoBehaviour, IPersistable
	{
		[SerializeField]
		private ShapeColor DefaultColor = ShapeColor.COLOR_13;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		private SynchronizedField<int> _makerPenColor;

		[SerializeField]
		private MeshRenderer[] colorableRenderers;

		private MaterialPropertyBlock materialProperties;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_SandboxColorChangedEvent;

		public Tool Tool => _tool;

		public ShapeColor MakerPenColor
		{
			get
			{
				return (ShapeColor)_makerPenColor.Get();
			}
			set
			{
				_makerPenColor.Set((int)value);
			}
		}

		public Color Color => ShapeSettings.GetShapeColor(MakerPenColor);

		public bool BlockObjectPersistance => false;

		public event Action SandboxColorChangedEvent
		{
			add
			{
				Action action = this.m_SandboxColorChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SandboxColorChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_SandboxColorChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_SandboxColorChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_makerPenColor = new SynchronizedField<int>(this, "SBXColor", (int)DefaultColor, SetterPermissionMode.ANYONE, OnColorChanged);
			Tool.CreationObject.AddPropertyHandler("Color", OnMakerPenRecolor);
		}

		private void Start()
		{
			OnColorChanged();
		}

		private UndoEntry OnMakerPenRecolor(CreationContext context, params object[] modificationParameters)
		{
			UndoEntry result = null;
			if (modificationParameters != null)
			{
				ShapeColor shapeColor = (ShapeColor)modificationParameters[0];
				result = new RecolorObjectsUndoEntry(new CreationObject[1] { Tool.CreationObject }, context, MakerPenColor, shapeColor);
				MakerPenColor = shapeColor;
			}
			return result;
		}

		private void OnColorChanged()
		{
			if (materialProperties == null)
			{
				materialProperties = new MaterialPropertyBlock();
			}
			MeshRenderer[] array = colorableRenderers;
			foreach (MeshRenderer meshRenderer in array)
			{
				meshRenderer.GetPropertyBlock(materialProperties);
				materialProperties.SetColor(ShaderIDs.COLOR, Color);
				meshRenderer.SetPropertyBlock(materialProperties);
			}
			if (this.SandboxColorChangedEvent != null)
			{
				this.SandboxColorChangedEvent();
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData != null && viewData.SandboxColorableData != null)
			{
				MakerPenColor = (ShapeColor)viewData.SandboxColorableData.Color;
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.SandboxColorableData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing SandboxColorable Object {0}: Data already specified.", base.gameObject);
			}
			else
			{
				viewData.SandboxColorableData = new SandboxColorableData
				{
					Color = (int)MakerPenColor
				};
			}
		}
	}
	public class SandboxDice : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private class RotationLabel
		{
			public string label;

			public Vector3 upVector = Vector3.up;
		}

		[SerializeField]
		private float angularVelocityMultiplier = 1f;

		[SerializeField]
		private List<RotationLabel> rotationLabels;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		private MomentarySourceNodeVisualization momentarySourceNode;

		private bool isThrown;

		public Tool Tool => _tool;

		private void Awake()
		{
			Tool.PostReleaseEvent += OnRelease;
			momentarySourceNode = GetComponent<MomentarySourceNodeVisualization>();
		}

		private void Update()
		{
			if (Tool.IsHeld)
			{
				return;
			}
			if (isThrown)
			{
				if (!(Tool.RigidbodyEx.angularVelocity.sqrMagnitude <= 1E-06f))
				{
					return;
				}
				isThrown = false;
				RotationLabel currentRotationLabel = GetCurrentRotationLabel();
				if (currentRotationLabel != null)
				{
					if (momentarySourceNode != null)
					{
						int result = 0;
						int.TryParse(currentRotationLabel.label, out result);
						momentarySourceNode.SetOutput(result);
					}
					float lossyUniformScale = base.transform.GetLossyUniformScale();
					float num = (lossyUniformScale - 1f) * 0.2f + 1f;
					Vector3 value = base.transform.position + Vector3.up * (lossyUniformScale * 0.05f + num * 0.03f);
					WorldSpaceNotification.PlayNext(currentRotationLabel.label, 3f, null, followPlayer: false, value, num * 0.35f, billboard: true);
				}
			}
			else if (Tool.RigidbodyEx.angularVelocity.sqrMagnitude > 10f)
			{
				isThrown = true;
			}
		}

		private void OnRelease(Tool tool)
		{
			isThrown = false;
			if (tool.hasAuthority)
			{
				Vector3 angularVelocity = tool.RigidbodyEx.angularVelocity;
				angularVelocity *= angularVelocityMultiplier;
				tool.RigidbodyEx.angularVelocity = angularVelocity;
			}
		}

		private RotationLabel GetCurrentRotationLabel()
		{
			Vector3 lhs = base.transform.InverseTransformDirection(Vector3.up);
			float num = float.MinValue;
			RotationLabel result = null;
			foreach (RotationLabel rotationLabel in rotationLabels)
			{
				float num2 = Vector3.Dot(lhs, rotationLabel.upVector);
				if (num2 >= 0.95f && num2 >= num)
				{
					num = num2;
					result = rotationLabel;
				}
			}
			return result;
		}
	}
	public abstract class SandboxGoalBase : Photon.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		protected Tool tool;

		public UnityEvent OnGoalHitEvent;

		[SerializeField]
		private Layers CollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerPhysics;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private CircuitNodeDisplay circuitNodeDisplay;

		[SerializeField]
		private float minHitInterval = 0.5f;

		[Header("Hit effects")]
		[SerializeField]
		private PooledParticle hitParticles;

		[SerializeField]
		private RecRoomAudioClip hitAudio;

		[Header("Flashing")]
		[SerializeField]
		private Renderer[] hitFlashRenderers;

		[SerializeField]
		private Color hitFlashColor = Color.white;

		[SerializeField]
		private float hitFlashIntensity = 0.3f;

		[SerializeField]
		private int hitFlashCount = 1;

		[SerializeField]
		private float hitFlashDuration = 0.3f;

		[SerializeField]
		private float hitFlashFadeDuration = 0.3f;

		[SerializeField]
		private float hitFlashInterval = 0.3f;

		private float lastHitTime;

		private Coroutine flashRoutine;

		public Tool Tool => tool;

		protected virtual bool CanPlayHitNotification => UnityEngine.Time.time >= lastHitTime + minHitInterval;

		protected override void Awake()
		{
			base.Awake();
			tool.DefaultCollisionLayer = CollisionLayer;
			tool.GravityPickupMode = Tool.GravityPickup.DISABLED;
			tool.IgnorePickupDirection = true;
			tool.AlwaysPhysicalPickupOffCenter = true;
		}

		protected abstract void OnTriggerEnter(Collider other);

		protected void NotifyPlayHitEffect(Vector3 position)
		{
			if (CanPlayHitNotification)
			{
				base.photonView.RpcAll(RpcOnGoalHit, position);
			}
		}

		[PunRPC]
		protected void RpcOnGoalHit(Vector3 position)
		{
			OnGoalHit(position);
		}

		protected virtual void OnGoalHit(Vector3 position)
		{
			if (!CanPlayHitNotification)
			{
				return;
			}
			if (OnGoalHitEvent != null)
			{
				OnGoalHitEvent.Invoke();
			}
			if (circuitNodeDisplay == null || !circuitNodeDisplay.IsConnected)
			{
				if (hitParticles != null)
				{
					PooledParticle pooledParticle = ObjectPool.Instance.Acquire(hitParticles);
					pooledParticle.Play(position, base.transform.rotation);
				}
				if (hitAudio != null)
				{
					AudioManager.Play3DSFX(hitAudio, base.transform);
				}
			}
			this.SafeStopCoroutine(flashRoutine);
			flashRoutine = StartCoroutine(RunFlashRoutine());
			lastHitTime = UnityEngine.Time.time;
		}

		private IEnumerator RunFlashRoutine()
		{
			MaterialPropertyBlock tempPropertyBlock = new MaterialPropertyBlock();
			for (int flashCount = 0; flashCount < hitFlashCount; flashCount++)
			{
				for (float t = 0f; t < hitFlashDuration + hitFlashFadeDuration; t += UnityEngine.Time.deltaTime)
				{
					float intensity = 1f - Mathf.Clamp01((t - hitFlashDuration) / hitFlashFadeDuration);
					intensity *= hitFlashIntensity;
					for (int i = 0; i < hitFlashRenderers.Length; i++)
					{
						Renderer renderer = hitFlashRenderers[i];
						TrySetShaderColor(renderer, tempPropertyBlock, ShaderIDs.TINT_COLOR, hitFlashColor, intensity);
						TrySetShaderColor(renderer, tempPropertyBlock, ShaderIDs.EMISSION_COLOR, hitFlashColor, intensity);
						TrySetShaderColor(renderer, tempPropertyBlock, ShaderIDs.MAIN_COLOR, hitFlashColor, intensity);
						renderer.SetPropertyBlock(tempPropertyBlock);
					}
					yield return null;
				}
				tempPropertyBlock.Clear();
				for (int j = 0; j < hitFlashRenderers.Length; j++)
				{
					hitFlashRenderers[j].SetPropertyBlock(tempPropertyBlock);
				}
				yield return new WaitForSeconds(hitFlashInterval);
			}
		}

		private void TrySetShaderColor(Renderer renderer, MaterialPropertyBlock propertyBlock, int propertyId, Color flashColor, float intensity)
		{
			if (renderer.sharedMaterial.HasProperty(propertyId))
			{
				Color value = Color.Lerp(renderer.sharedMaterial.GetColor(propertyId), flashColor, intensity);
				propertyBlock.SetColor(propertyId, value);
			}
		}
	}
	public class SandboxObjectRespawner : Photon.MonoBehaviour, IPersistable
	{
		private const InputSlot SPAWN_TAGGED_OBJECT = InputSlot.R;

		private const InputSlot SPAWN_OBJECT_ID = InputSlot.G;

		private SynchronizedField<string> _respawnToolTag;

		private SynchronizedField<bool> _respawnHeldTools;

		private SynchronizedField<bool> _clearVelocityOnRespawn;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private RigidbodyEx rigidbodyEx;

		[SerializeField]
		private Tooltip tooltip;

		[SerializeField]
		private CreationObjectSettingStringUIControl tagSpawnToolControlPrefab;

		public string RespawnToolTag
		{
			get
			{
				return _respawnToolTag.Get();
			}
			set
			{
				_respawnToolTag.Set(value);
			}
		}

		public bool RespawnHeldTools
		{
			get
			{
				return _respawnHeldTools.Get();
			}
			set
			{
				_respawnHeldTools.Set(value);
			}
		}

		public bool ClearVelocityOnRespawn
		{
			get
			{
				return _clearVelocityOnRespawn.Get();
			}
			set
			{
				_clearVelocityOnRespawn.Set(value);
			}
		}

		public bool BlockObjectPersistance => false;

		protected override void Awake()
		{
			base.Awake();
			_respawnToolTag = new SynchronizedField<string>(this, "RTT", string.Empty, SetterPermissionMode.AUTHORITY, OnRespawnToolUpdated);
			_respawnHeldTools = new SynchronizedField<bool>(this, "RHT", defaultValue: true, SetterPermissionMode.AUTHORITY);
			_clearVelocityOnRespawn = new SynchronizedField<bool>(this, "CVOR", defaultValue: true, SetterPermissionMode.AUTHORITY);
		}

		private void Start()
		{
			CreationObject component = GetComponent<CreationObject>();
			if (component != null)
			{
				StringSettingEditEvent settingEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => tagSpawnToolControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
				{
					instance.PropertyDescription.text = "Tag to Respawn";
					instance.PropertyGetter = RespawnTool_Get;
					instance.PropertySetter = RespawnTool_Set;
				});
				BoolSettingEditEvent settingEvent2 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Don't respawn if held by player";
					instance.PropertyGetter = RespawnToolPolitely_Get;
					instance.PropertySetter = RespawnToolPolitely_Set;
				});
				BoolSettingEditEvent settingEvent3 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
				{
					instance.PropertyDescription.text = "Clear velocity on respawn?";
					instance.PropertyGetter = ClearVelocityOnRespawn_Get;
					instance.PropertySetter = ClearVelocityOnRespawn_Set;
				});
				component.AddConfigurableSetting(settingEvent);
				component.AddConfigurableSetting(settingEvent2);
				component.AddConfigurableSetting(settingEvent3);
			}
		}

		public void RespawnTool_Set(string newValue)
		{
			RespawnToolTag = newValue;
		}

		public string RespawnTool_Get()
		{
			return RespawnToolTag;
		}

		public void RespawnToolPolitely_Set(bool newValue)
		{
			RespawnHeldTools = !newValue;
		}

		public bool RespawnToolPolitely_Get()
		{
			return !RespawnHeldTools;
		}

		public void ClearVelocityOnRespawn_Set(bool newValue)
		{
			ClearVelocityOnRespawn = newValue;
		}

		public bool ClearVelocityOnRespawn_Get()
		{
			return ClearVelocityOnRespawn;
		}

		private void OnRespawnToolUpdated()
		{
			tooltip.Message = string.Empty;
			if (!string.IsNullOrEmpty(RespawnToolTag))
			{
				tooltip.Message = "#" + RespawnToolTag;
			}
		}

		public void SpawnObjectSignalReceived(Dictionary<InputSlot, int> updates)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			if (updates.ContainsKey(InputSlot.R) && updates[InputSlot.R] != 0)
			{
				TaggedTool furthestToolWithTag = GetFurthestToolWithTag(RespawnToolTag);
				RespawnTool((!(furthestToolWithTag != null)) ? null : furthestToolWithTag.Tool);
			}
			if (!updates.ContainsKey(InputSlot.G) || updates[InputSlot.G] == 0)
			{
				return;
			}
			PhotonView photonView = PhotonView.Find(updates[InputSlot.G]);
			if (photonView != null)
			{
				Tool component = photonView.GetComponent<Tool>();
				if (component != null && (!component.IsHeld || RespawnHeldTools))
				{
					RespawnTool(component);
				}
			}
		}

		private void RespawnTool(Tool toolToRespawn)
		{
			if (toolToRespawn != null)
			{
				Vector3 velocity = Vector3.zero;
				Vector3 angularVelocity = Vector3.zero;
				bool flag = !ClearVelocityOnRespawn && !toolToRespawn.RigidbodyEx.IsSleeping();
				if (flag)
				{
					velocity = toolToRespawn.RigidbodyEx.velocity;
					angularVelocity = toolToRespawn.RigidbodyEx.angularVelocity;
				}
				toolToRespawn.LocalTakeOwnershipAndResetToDefault(rigidbodyEx.targetPosition, toolToRespawn.RigidbodyEx.targetRotation);
				if (flag)
				{
					toolToRespawn.RigidbodyEx.velocity = velocity;
					toolToRespawn.RigidbodyEx.angularVelocity = angularVelocity;
				}
			}
		}

		private TaggedTool GetFurthestToolWithTag(string tag)
		{
			ReadOnlyCollection<TaggedTool> toolsWithTag = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetToolsWithTag(tag);
			TaggedTool taggedTool = null;
			float num = 0f;
			TaggedTool taggedTool2 = null;
			float num2 = 0f;
			foreach (TaggedTool item in toolsWithTag)
			{
				if (item.Tool.IsHeldByPlayer)
				{
					if (RespawnHeldTools && taggedTool2 == null)
					{
						float num3 = Vector3.SqrMagnitude(rigidbodyEx.targetPosition - item.Tool.RigidbodyEx.targetPosition);
						if (num3 >= num)
						{
							taggedTool = item;
							num = num3;
						}
					}
				}
				else
				{
					float num4 = Vector3.SqrMagnitude(rigidbodyEx.targetPosition - item.Tool.RigidbodyEx.targetPosition);
					if (num4 >= num2)
					{
						taggedTool2 = item;
						num2 = num4;
					}
				}
			}
			return (!(taggedTool2 != null)) ? taggedTool : taggedTool2;
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData != null && viewData.ObjectSpawnPointData != null)
			{
				RespawnToolTag = viewData.ObjectSpawnPointData.ItemTag;
				RespawnHeldTools = viewData.ObjectSpawnPointData.TakeFromHolder;
				ClearVelocityOnRespawn = viewData.ObjectSpawnPointData.ClearVelocityOnRespawn;
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.ObjectSpawnPointData == null)
			{
				viewData.ObjectSpawnPointData = new ObjectSpawnPointData
				{
					ItemTag = RespawnToolTag,
					TakeFromHolder = RespawnHeldTools,
					ClearVelocityOnRespawn = ClearVelocityOnRespawn
				};
			}
		}
	}
