	public class SandboxPlayerGoal : SandboxGoalBase
	{
		[Header("Capsule Cast Settings")]
		[SerializeField]
		private Collider triggerCollider;

		[SerializeField]
		private float playerCapsuleRadius = 0.4f;

		[SerializeField]
		private float playerCapsuleHeight = 1.5f;

		protected override bool CanPlayHitNotification => base.CanPlayHitNotification && !tool.IsHeld;

		protected override void Awake()
		{
			base.Awake();
			PlayerLocomotion.PlayerTeleportedEvent += OnPlayerTeleported;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PlayerLocomotion.PlayerTeleportedEvent -= OnPlayerTeleported;
		}

		protected override void OnTriggerEnter(Collider other)
		{
			Player.BodyPart bodyPart;
			Player colliderPlayer = other.GetColliderPlayer(out bodyPart);
			if (bodyPart != Player.BodyPart.LeftHand && bodyPart != Player.BodyPart.RightHand && HasNotificationAuthority(colliderPlayer))
			{
				NotifyPlayHitEffect(colliderPlayer.Body.transform.position);
			}
		}

		private void OnPlayerTeleported(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
		{
			if (HasNotificationAuthority(player))
			{
				Vector3 vector = destinationGroundPosition - sourceGroundPosition;
				if (triggerCollider.CapsuleCast(sourceGroundPosition, sourceGroundPosition + Vector3.up * playerCapsuleHeight, playerCapsuleRadius, vector.normalized, vector.magnitude, out var hitInfo))
				{
					NotifyPlayHitEffect(hitInfo.point);
				}
			}
		}

		private bool HasNotificationAuthority(Player player)
		{
			return player != null && (tool.hasAuthority || player.isLocal);
		}
	}
	public class SandboxSet : Photon.MonoBehaviour
	{
		[Serializable]
		public struct SandboxSetPiece
		{
			public SpawnableToolType equipment;

			public Vector3 initPosition;

			public Quaternion initRotation;
		}

		[SerializeField]
		private SandboxSetPiece[] pieces;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		public Tool Tool => _tool;

		public IEnumerable<SandboxSetPiece> PieceData => pieces;

		protected override void Awake()
		{
			base.Awake();
			Tool.PostReleaseEvent += OnRelease;
		}

		private void Start()
		{
			if (Tool.CreationObject != null)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					Tool.CreationObject.LockedStatusChangedEvent += OnLockChanged;
				});
			}
		}

		protected override void OnDestroy()
		{
			Tool.PostReleaseEvent -= OnRelease;
			if (Tool.CreationObject != null)
			{
				Tool.CreationObject.LockedStatusChangedEvent -= OnLockChanged;
			}
			base.OnDestroy();
		}

		private void OnLockChanged(CreationObject setObject)
		{
			if (Tool.CreationObject == setObject && !setObject.IsLocked)
			{
				OnRelease(Tool);
			}
		}

		private void OnRelease(Tool tool)
		{
			if (PhotonNetwork.isMasterClient && pieces != null)
			{
				Tool.PostReleaseEvent -= OnRelease;
				if (Tool.CreationObject != null)
				{
					Tool.CreationObject.LockedStatusChangedEvent -= OnLockChanged;
				}
				MasterSpawnPieces();
				PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
			}
		}

		protected virtual IEnumerable<Tool> MasterSpawnPieces()
		{
			List<Tool> list = new List<Tool>();
			SandboxSetPiece[] array = pieces;
			for (int i = 0; i < array.Length; i++)
			{
				SandboxSetPiece sandboxSetPiece = array[i];
				Tool tool = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.MasterSpawnTool(sandboxSetPiece.equipment, base.transform.TransformPoint(sandboxSetPiece.initPosition), base.transform.TransformRotation(sandboxSetPiece.initRotation), 1f);
				if (tool != null)
				{
					list.Add(tool);
				}
			}
			return list;
		}

		private void OnDrawGizmos()
		{
			if (pieces != null)
			{
				SandboxSetPiece[] array = pieces;
				for (int i = 0; i < array.Length; i++)
				{
					SandboxSetPiece sandboxSetPiece = array[i];
					Vector3 vector = base.transform.TransformPoint(sandboxSetPiece.initPosition);
					Gizmos.color = Color.green;
					Gizmos.DrawSphere(vector, 0.05f);
					Gizmos.color = Color.blue;
					Gizmos.DrawRay(vector, base.transform.TransformRotation(sandboxSetPiece.initRotation) * base.transform.forward * 0.05f);
				}
			}
		}
	}
