namespace RecRoom.Tools
{
	public class Snowball : Weapon
	{
		[Header("Snowball")]
		[SerializeField]
		private Transform visualRoot;

		[SerializeField]
		private PooledParticle explodeParticles;

		[SerializeField]
		private float postExplosionCleanupTimeout = 5f;

		[SerializeField]
		private float postAuthorityCollisionDisable = 0.5f;

		[SerializeField]
		private float speedNeededToArm = 5f;

		[SerializeField]
		private ParticleSystem trailParticles;

		[SerializeField]
		private RecRoomAudioClip explodeAudio;

		[SerializeField]
		private LayerMasks destroyOnLayers = LayerMasks.BulletPhysics;

		private ToolCleanup _toolCleanup;

		private SynchronizedField<bool> _explodeOnImpact;

		private SynchronizedField<int> _explodeTime;

		private SynchronizedField<int> _throwerId;

		private Player thrower;

		public int ThrowerId
		{
			get
			{
				return _throwerId.Get();
			}
			set
			{
				_throwerId.Set(value);
			}
		}

		public bool ExplodeOnImpact
		{
			get
			{
				return _explodeOnImpact.Get();
			}
			set
			{
				_explodeOnImpact.Set(value);
			}
		}

		public int ExplodeTime
		{
			get
			{
				return _explodeTime.Get();
			}
			set
			{
				_explodeTime.Set(value);
			}
		}

		private ToolCleanup toolCleanup
		{
			get
			{
				if (_toolCleanup == null)
				{
					_toolCleanup = GetComponent<ToolCleanup>();
				}
				return _toolCleanup;
			}
		}

		protected override Color WeaponColor => Color.white;

		protected override void Awake()
		{
			base.Awake();
			_explodeOnImpact = new SynchronizedField<bool>(this, "SnowBall.AOI", defaultValue: false, SetterPermissionMode.ANYONE, UpdateExplodeOnImpactState);
			_explodeTime = new SynchronizedField<int>(this, "Snowball.ET", 0, SetterPermissionMode.ANYONE);
			_throwerId = new SynchronizedField<int>(this, "Snowball.TI", PhotonPlayer.Invalid, SetterPermissionMode.ANYONE, OnThrowerChanged);
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent += Tool_PostPickup;
				base.Tool.PostReleaseEvent += Tool_PostRelease;
				base.Tool.PostResetEvent += Tool_ResetEvent;
			}
		}

		protected override void Start()
		{
			base.Start();
			if (base.Tool != null)
			{
				base.Tool.SupportsAnimateOut = false;
			}
			if (base.hasAuthority)
			{
				ExplodeOnImpact = false;
				ExplodeTime = 0;
			}
			UpdateExplodeOnImpactState();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= Tool_PostPickup;
				base.Tool.PreReleaseEvent -= Tool_PostRelease;
				base.Tool.PostResetEvent -= Tool_ResetEvent;
			}
		}

		protected void Update()
		{
			UpdateCleanup();
		}

		private void UpdateCleanup()
		{
			bool flag = false;
			if (visualRoot.gameObject.activeSelf)
			{
				flag = !ExplodeOnImpact;
			}
			else if (ExplodeTime != 0 && PhotonNetwork.isMasterClient)
			{
				float num = (float)(PhotonNetwork.ServerTimestamp - ExplodeTime) / 1000f;
				if (num >= postExplosionCleanupTimeout)
				{
					base.Tool.LocalTakeOwnershipAndResetToLastSpawnPosition();
				}
			}
			if (ExplodeTime != 0 && visualRoot.gameObject.activeSelf)
			{
				float num2 = (float)(PhotonNetwork.ServerTimestamp - ExplodeTime) / 1000f;
				if (num2 >= postAuthorityCollisionDisable)
				{
					HideSnowball();
				}
			}
			if (toolCleanup != null && toolCleanup.enabled != flag)
			{
				toolCleanup.enabled = flag;
			}
		}

		private void Tool_PostPickup(Tool thisTool)
		{
			if (base.hasAuthority)
			{
				ExplodeOnImpact = false;
			}
		}

		private void Tool_PostRelease(Tool tool)
		{
			if (base.hasAuthority)
			{
				ThrowerId = PhotonNetwork.player.ID;
			}
			StartCooking();
		}

		private void Tool_ResetEvent(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			visualRoot.gameObject.SetActive(value: true);
			base.Tool.RigidbodyEx.useGravity = true;
			if (base.hasAuthority)
			{
				ThrowerId = PhotonPlayer.Invalid;
				ExplodeOnImpact = false;
				ExplodeTime = 0;
			}
		}

		private void OnThrowerChanged()
		{
			thrower = PhotonPlayer.Find(ThrowerId)?.ToPlayer();
		}

		private void UpdateExplodeOnImpactState()
		{
			if (ExplodeOnImpact)
			{
				trailParticles.Play();
			}
			else
			{
				trailParticles.Stop();
			}
		}

		private void StartCooking()
		{
			if (base.hasAuthority && base.Tool.RigidbodyEx.velocity.magnitude >= speedNeededToArm)
			{
				ExplodeOnImpact = true;
			}
		}

		private void Explode(Vector3 position)
		{
			HideSnowball();
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(explodeParticles);
			if (pooledParticle != null)
			{
				pooledParticle.Play(position, Quaternion.identity);
			}
			AudioManager.Play3DSFX(explodeAudio, base.transform.position);
			if (base.hasAuthority)
			{
				ExplodeTime = PhotonNetwork.ServerTimestamp;
			}
		}

		private void HideSnowball()
		{
			visualRoot.gameObject.SetActive(value: false);
			base.Tool.RigidbodyEx.useGravity = false;
			base.Tool.RigidbodyEx.velocity = Vector3.zero;
			trailParticles.Stop();
			if (base.Tool.IsHeld && base.Tool.Owner.isLocal)
			{
				base.Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (!ExplodeOnImpact || !(thrower != null) || !visualRoot.gameObject.activeSelf)
			{
				return;
			}
			GameObject gameObject = collision.collider.gameObject;
			if (gameObject == base.gameObject || collision.contacts.Length == 0)
			{
				return;
			}
			EnemyArmorType hitEnemyArmorType = EnemyArmorType.NORMAL;
			Player player = null;
			Tool tool = null;
			Enemy enemy = null;
			Vector3 force = base.Tool.RigidbodyEx.velocity.normalized * 10f;
			WeaponImpact impact = new WeaponImpact
			{
				Velocity = base.Tool.RigidbodyEx.velocity,
				Force = force,
				GameObject = gameObject,
				Point = collision.contacts[0].point,
				Distance = 0f,
				SurfaceNormal = collision.contacts[0].normal,
				PreAttackChargeAmount = 1f
			};
			bool flag = false;
			if ((player = collision.collider.GetColliderPlayer(out var bodyPart)) != null)
			{
				if (player != thrower)
				{
					flag = true;
					OnPlayerImpact(player, bodyPart, impact);
				}
			}
			else if ((enemy = collision.collider.GetColliderEnemy(out hitEnemyArmorType)) != null)
			{
				OnEnemyImpact(enemy, hitEnemyArmorType, impact);
				flag = true;
			}
			else if ((tool = collision.collider.GetColliderTool()) != null)
			{
				if (tool.GetComponent<ProjectileTool>() != null)
				{
					return;
				}
				flag = true;
				OnToolImpact(tool, impact);
			}
			else if (gameObject.IsInLayerMask(destroyOnLayers))
			{
				flag = true;
				OnOtherImpact(impact);
			}
			if (flag)
			{
				Explode(base.transform.position);
			}
		}
	}
}
