				enumValue = 2
			});
			dictionary.Add("Team 4", new EnumChoiceData
			{
				enumValue = 3
			});
			dictionary.Add("Team 5", new EnumChoiceData
			{
				enumValue = 4
			});
			dictionary.Add("Team 6", new EnumChoiceData
			{
				enumValue = 5
			});
			dictionary.Add("Team 7", new EnumChoiceData
			{
				enumValue = 6
			});
			dictionary.Add("Team 8", new EnumChoiceData
			{
				enumValue = 7
			});
			dictionary.Add("Team 9", new EnumChoiceData
			{
				enumValue = 8
			});
			dictionary.Add("Team 10", new EnumChoiceData
			{
				enumValue = 9
			});
			dictionary.Add("Team 11", new EnumChoiceData
			{
				enumValue = 10
			});
			dictionary.Add("Team 12", new EnumChoiceData
			{
				enumValue = 11
			});
			dictionary.Add("Team 13", new EnumChoiceData
			{
				enumValue = 12
			});
			dictionary.Add("Team 14", new EnumChoiceData
			{
				enumValue = 13
			});
			dictionary.Add("Team 15", new EnumChoiceData
			{
				enumValue = 14
			});
			dictionary.Add("Team 16", new EnumChoiceData
			{
				enumValue = 15
			});
			Dictionary<string, EnumChoiceData> choicesDictionary = dictionary;
			EnumSettingEditEvent settingEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.PropertyDescription.text = "Team to Respawn";
				instance.PropertyGetter = SandboxCircuitSpawnPointTeam_Get;
				instance.PropertySetter = SandboxCircuitSpawnPointTeam_Set;
			}, choicesDictionary);
			StringSettingEditEvent settingEvent2 = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => tagSpawnToolControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				instance.PropertyDescription.text = "Tag for Primary Hand Respawn";
				instance.PropertyGetter = PrimaryHandToolHeld_Get;
				instance.PropertySetter = PrimaryHandToolHeld_Set;
			});
			BoolSettingEditEvent settingEvent3 = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				instance.PropertyDescription.text = "Respawn primary hand item politely?";
				instance.PropertyGetter = PrimaryHandPoliteRespawn_Get;
				instance.PropertySetter = PrimaryHandPoliteRespawn_Set;
			});
			StringSettingEditEvent settingEvent4 = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => tagSpawnToolControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
