			});
			component.AddConfigurableSetting(0, settingEvent2);
			component.AddConfigurableSetting(1, settingEvent3);
			component.AddConfigurableSetting(2, settingEvent4);
			component.AddConfigurableSetting(3, settingEvent5);
			component.AddConfigurableSetting(4, settingEvent);
		}
		OnGameTeamChanged();
		ToggleSpawnPointRegistered(isActive: true);
