	{
		base.OnDestroy();
		ToggleSpawnPointRegistered(isActive: false);
	}

	public void SandboxCircuitSpawnPointTeam_Set(int newValue)
	{
		if (base.hasAuthority)
		{
			SettingsConfiguredGameTeam = (GameTeam)newValue;
		}
	}

