	private void ToggleSpawnPointRegistered(bool isActive)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager != null)
		{
			if (!isActive)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.RemoveSandboxSpawnPoints(this);
			}
			else
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.AddSandboxSpawnPoints(this);
			}
		}
	}

	private void OnGameTeamChanged()
	{
		if (!wired)
		{
			base.GameTeam = SettingsConfiguredGameTeam;
			UpdateSpawnPointColor();
		}
	}

	public void UpdateRespawnConfiguration(Dictionary<InputSlot, int> updates)
	{
		if (updates.ContainsKey(InputSlot.G) && updates[InputSlot.G] != 0 && updates[InputSlot.G] == PhotonNetwork.player.ID)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.LocalPlayerRequestRespawnAtPoint(this);
		}
		if (updates.ContainsKey(InputSlot.R))
		{
			int signal = updates[InputSlot.R];
			GameTeam? gameTeam = CircuitUtils.CircuitSignalToGameTeam(signal);
			wired = gameTeam.HasValue;
			if (!gameTeam.HasValue)
			{
				base.GameTeam = SettingsConfiguredGameTeam;
			}
			else
			{
				base.GameTeam = gameTeam.Value;
			}
			UpdateSpawnPointColor();
		}
	}

	private void UpdateSpawnPointColor()
	{
		Color value = unwiredMeshColor;
		if (base.GameTeam != GameTeam.ANY)
		{
			value = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(base.GameTeam);
			value = value.ChangeAlpha(unwiredMeshColor.a);
		}
		if (materialProperties == null)
		{
			materialProperties = new MaterialPropertyBlock();
		}
		baseMesh.GetPropertyBlock(materialProperties);
		materialProperties.SetColor(ShaderIDs.MAIN_COLOR, value);
		materialProperties.SetColor(ShaderIDs.SCANLINE_COLOR, value);
		baseMesh.SetPropertyBlock(materialProperties);
		beamMesh.GetPropertyBlock(materialProperties);
		materialProperties.SetColor(ShaderIDs.MAIN_COLOR, value);
		materialProperties.SetColor(ShaderIDs.SCANLINE_COLOR, value);
		beamMesh.SetPropertyBlock(materialProperties);
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		PersistenceViewData viewData = deserializeParams.viewData;
		if (viewData != null && viewData.SpawnPointData != null)
		{
			SettingsConfiguredGameTeam = (GameTeam)viewData.SpawnPointData.TeamId;
			PrimaryHandHeldTag = viewData.SpawnPointData.PrimaryHandHoldTag;
			PrimaryHandTakeFromHolder = viewData.SpawnPointData.PrimaryHandTakeFromHolder;
			SecondaryHandHeldTag = viewData.SpawnPointData.SecondaryHandHoldTag;
			SecondaryHandTakeFromHolder = viewData.SpawnPointData.SecondaryHandTakeFromHolder;
		}
		else
		{
			SettingsConfiguredGameTeam = GameTeam.ANY;
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.SpawnPointData == null)
		{
			viewData.SpawnPointData = new SpawnPointData();
		}
		viewData.SpawnPointData.TeamId = (int)SettingsConfiguredGameTeam;
		viewData.SpawnPointData.PrimaryHandHoldTag = PrimaryHandHeldTag;
		viewData.SpawnPointData.PrimaryHandTakeFromHolder = PrimaryHandTakeFromHolder;
		viewData.SpawnPointData.SecondaryHandHoldTag = SecondaryHandHeldTag;
		viewData.SpawnPointData.SecondaryHandTakeFromHolder = SecondaryHandTakeFromHolder;
	}
}
