			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		protected override void OnSpawnPointsChanged()
		{
			base.OnSpawnPointsChanged();
			UpdateSpawnPointTargetRoomIds();
		}

		private void OnTargetRoomChanged()
		{
			UpdateSpawnPointTargetRoomIds();
		}

		private void RigidbodyEx_IsKinematicChangedEvent(RigidbodyEx rigidbodyEx)
		{
			if (PhotonNetwork.isMasterClient && hasInitialized)
			{
				if (ToolIsInSpawnableState)
				{
					MasterInstantiateSpawnPoints();
				}
				else
				{
					MasterDestroySpawnPoints();
				}
			}
		}

		private void OnMasterClientSwitched(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient && hasInitialized && ToolIsInSpawnableState)
			{
				MasterInstantiateSpawnPoints();
			}
		}

		private void RoomName_Set(object obj)
		{
			string roomName = obj.ToString();
			if (!string.IsNullOrEmpty(roomName))
			{
				RecNet.Rooms.GetRoomByName(roomName).Then(delegate(RecNet.Room room)
				{
					if (this != null)
					{
						_targetRoomIdName.Set(room.RoomId, room.Name);
						ShowMessage("Success", "Connected to room " + roomName);
					}
				}).Error(delegate
				{
					if (this != null)
					{
						ShowMessage("Failed", $"Can't find room {roomName}");
					}
				});
			}
			else if (TargetRoomId > 0)
			{
				_targetRoomIdName.Set(0L, string.Empty);
				ShowMessage("Success", "Room connection removed");
			}
		}

		private string RoomName_Get()
		{
			if (!string.IsNullOrEmpty(TargetRoomName))
			{
				return TargetRoomName;
			}
			return "Not assigned";
		}

		private void ShowMessage(string title, string message)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, title, message, 4f);
		}

		private void UpdateSpawnPointTargetRoomIds()
		{
			foreach (SpawnPoint spawnPoint in spawnPoints)
			{
				if (spawnPoint.hasAuthority)
				{
					SandboxSceneSpawnPoint sandboxSceneSpawnPoint = spawnPoint as SandboxSceneSpawnPoint;
					if (sandboxSceneSpawnPoint != null)
					{
						sandboxSceneSpawnPoint.TargetRoomId = TargetRoomId;
					}
				}
			}
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.SpawnpointSpawnerData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing SandboxSceneSpawnPointSpawner {0}: data empty.", base.gameObject);
				return;
			}
			SpawnPointSpawnerData data = deserializeParams.viewData.SpawnpointSpawnerData;
			if (data.RoomId > 0)
			{
				_targetRoomIdName.Set(data.RoomId, "Loading");
				RecNet.Rooms.GetRoomById(data.RoomId).Then(delegate(RecNet.Room room)
				{
					if (this != null)
					{
						_targetRoomIdName.Set(room.RoomId, room.Name);
					}
				}).Error(delegate
				{
					if (this != null)
					{
						UnityEngine.Debug.LogWarningFormat(this, "Error deserializing SandboxSceneSpawnPointSpaner {0}: Unable to find room with ID {1}", base.gameObject, data.RoomId);
					}
				});
			}
			else
			{
				_targetRoomIdName.Set(0L, string.Empty);
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.SpawnpointSpawnerData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing SandboxSceneSpawnPointSpawner {0}: Data already specified.", base.gameObject);
			}
			else
			{
				viewData.SpawnpointSpawnerData = new SpawnPointSpawnerData
				{
					RoomId = TargetRoomId
				};
			}
		}

		public void PostDeserialize(Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			if (PhotonNetwork.isMasterClient && ToolIsInSpawnableState)
			{
				MasterInstantiateSpawnPoints();
			}
		}
	}
	public abstract class SandboxSpawnPointSpawnerBase : Photon.MonoBehaviour
	{
		[SerializeField]
		private Transform[] spawnPointOffsets;

		[SerializeField]
		private SpawnPoint spawnPointPrefab;

		protected List<SpawnPoint> spawnPoints = new List<SpawnPoint>();

		private SynchronizedField<int[]> _spawnPointIds;

		public int[] SpawnPointIds
		{
			get
			{
				return _spawnPointIds.Get();
			}
			set
			{
				_spawnPointIds.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_spawnPointIds = new SynchronizedField<int[]>(this, "SPI", new int[0], SetterPermissionMode.MASTER, OnSpawnPointsChanged);
		}

		protected virtual void Start()
		{
			OnSpawnPointsChanged();
		}

		protected virtual void OnSpawnPointsChanged()
		{
			CacheSpawnPointReferences();
		}

		protected void MasterInstantiateSpawnPoints()
		{
			if (!PhotonNetwork.isMasterClient || spawnPoints.Count != 0)
			{
				return;
			}
			Vector3 normalized = Vector3.ProjectOnPlane(-1f * base.transform.forward, Vector3.up).normalized;
			Quaternion rotation = Quaternion.LookRotation(normalized, Vector3.up);
			float num = 0.01f;
			float num2 = 0.25f + num;
			float num3 = num2 * 2f;
			Vector3 vector = Vector3.up * 2f * num3;
			Vector3 vector2 = -Vector3.up;
			float maxDistance = 2f * num3;
			Vector3 vector3 = Vector3.up * (num2 + num);
			Vector3 vector4 = Vector3.up * (1.7f - 2f * num2);
			for (int i = 0; i < spawnPointOffsets.Length; i++)
			{
				Vector3 position = spawnPointOffsets[i].position;
				Vector3 vector5 = position + vector;
				RaycastHit hit;
				CollisionDetection.CollisionResult collisionResult = CollisionDetection.SweepSphere(vector5, num2, vector2, maxDistance, 67128320, CollisionDetection.CollidesWithMovementIgnoringPlayersAndEnemies, out hit);
				if (collisionResult != CollisionDetection.CollisionResult.HIT)
				{
					continue;
				}
				float num4 = Mathf.Abs((hit.point - position).y);
				if (num4 > num3)
				{
					continue;
				}
				Vector3 vector6 = vector5 + vector2 * hit.distance;
				position = vector6 + vector2 * num2;
				Vector3 vector7 = position + vector3;
				Vector3 capsuleTopPosition = vector7 + vector4;
				if (!CollisionDetection.IsCapsuleColliderOverlapping(vector7, capsuleTopPosition, num2, 67128320, CollisionDetection.CollidesWithMovementIgnoringPlayersAndEnemies))
				{
					GameObject gameObject = PhotonNetwork.InstantiateSceneObjectEx(spawnPointPrefab.name, position, rotation, 1f, 0, base.photonView.viewID, null);
					SpawnPoint spawnPoint = ((!(gameObject != null)) ? null : gameObject.GetComponent<SpawnPoint>());
					if (!(spawnPoint == null))
					{
						spawnPoints.Add(spawnPoint);
					}
				}
			}
			int[] array = new int[spawnPoints.Count];
			for (int j = 0; j < spawnPoints.Count; j++)
			{
				array[j] = spawnPoints[j].photonView.viewID;
			}
			SpawnPointIds = array;
		}

		protected void MasterDestroySpawnPoints()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			foreach (SpawnPoint spawnPoint in spawnPoints)
			{
				PhotonNetwork.GetOwnershipAndDestroy(spawnPoint.gameObject);
			}
			if (SpawnPointIds.Length > 0)
			{
				SpawnPointIds = new int[0];
			}
		}

		protected virtual void CacheSpawnPointReferences()
		{
			spawnPoints.Clear();
			int[] spawnPointIds = SpawnPointIds;
			foreach (int num in spawnPointIds)
			{
				PhotonView photonView = PhotonView.Find(num);
				if (photonView != null)
				{
					SpawnPoint component = photonView.GetComponent<SpawnPoint>();
					if (component != null)
					{
						spawnPoints.Add(component);
						continue;
					}
					UnityEngine.Debug.LogErrorFormat("No spawn point component found in PhotonView {0}", photonView.gameObject);
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Could not find corresponding PhotonView for ID {0}", num);
				}
			}
		}
	}
}
public class UGCRoomOOBE : UnityEngine.MonoBehaviour
{
	private bool tutorialInProgress;

	private float tutorialStartTime;

	private bool wasNUXInitiated;

	private void Start()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Q2A_WelcomeToUGCRoom)
		{
			wasNUXInitiated = true;
			SingletonMonoBehaviour<CameraRig>.Instance.StartCoroutine(RunTutorial());
		}
	}

	private IEnumerator RunTutorial()
	{
		if (!tutorialInProgress)
		{
			tutorialInProgress = true;
			tutorialStartTime = UnityEngine.Time.time;
			while (!Player.LocalPlayerExists)
			{
				yield return null;
			}
			yield return new WaitForSeconds(2f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2UGC_RoomWelcome);
			yield return new WaitForSeconds(1f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(TutorialManager.TutorialAudioType.Q2UGC_WhatsNext);
			AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToUGCRoom, UnityEngine.Time.time - tutorialStartTime, OOBEFlowBase.InterruptableFlow.FlowState.Complete);
			SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
			tutorialInProgress = false;
		}
	}

	private void OnDestroy()
	{
		if (tutorialInProgress)
		{
			if (SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance != null)
			{
				AnalyticsHelper.NUXStepCompleted(TutorialManager.NUXFlowState.Q2A_WelcomeToUGCRoom, UnityEngine.Time.time - tutorialStartTime, OOBEFlowBase.InterruptableFlow.FlowState.Incomplete);
			}
			if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.NUXState = TutorialManager.NUXFlowState.Complete;
			}
		}
		if (wasNUXInitiated && SingletonMonoBehaviour<AmplitudeAnalyticsClient>.Instance != null)
		{
			AnalyticsHelper.NUXLeftUGCRoom(UnityEngine.Time.time - tutorialStartTime);
		}
	}
}
namespace RecRoom
{
	public class BulkModifyObjectsUndoEntry : ModifyObjectsUndoEntry
	{
		public class BulkModifyObjectsUndoStep : UndoStepBase
		{
			public BulkModifyObjectsUndoEntry parentEntry;

			public bool redo;

			public BulkModifyObjectsUndoStep(BulkModifyObjectsUndoEntry parentEntry, bool redo)
			{
				this.parentEntry = parentEntry;
				this.redo = redo;
			}

			public override IPromise Perform(CreationContext context)
			{
				Promise<CreationResult> promise = new Promise<CreationResult>();
				CreationResult creationResult = ValidateEntries(context);
				if (creationResult == CreationResult.Success)
				{
					SingletonMonoBehaviour<Scheduler>.Instance.Run(context, RunUndoEntriesRoutine(context, promise));
				}
				else
				{
					promise.Complete(creationResult);
				}
				return promise;
			}

			private IEnumerator<ISchedule> RunUndoEntriesRoutine(CreationContext creationContext, Promise<CreationResult> completePromise)
			{
				foreach (UndoEntry entry in parentEntry.undoEntries)
				{
					if (((!redo) ? entry.ValidateUndo(creationContext) : entry.ValidateRedo(creationContext)) != CreationResult.Success)
					{
						continue;
					}
					IPromise entryPromise = null;
					string error = null;
					if (redo)
					{
						entryPromise = entry.PerformRedo(creationContext);
					}
					else
					{
						entryPromise = entry.PerformUndo(creationContext);
					}
					entryPromise.Error(delegate(string e)
					{
						error = e;
					});
					if (entryPromise != null && !entryPromise.IsCompleted)
					{
						yield return Schedule.Until(() => entryPromise.IsCompleted);
					}
					if (!string.IsNullOrEmpty(error))
					{
						UnityEngine.Debug.LogError($"Error returned while bulk-executing UndoEntry {entry}: {error}");
					}
				}
				completePromise.Complete(CreationResult.Success);
			}

			public override CreationResult ValidateEntries(CreationContext context)
			{
				CreationResult creationResult = CreationResult.Failure_Generic;
				foreach (UndoEntry undoEntry in parentEntry.undoEntries)
				{
					creationResult = ((!redo) ? undoEntry.ValidateUndo(context) : undoEntry.ValidateRedo(context));
					if (creationResult == CreationResult.Success)
					{
						return CreationResult.Success;
					}
				}
				return creationResult;
			}
		}

		private string labelVerb;

		private IEnumerable<UndoEntry> undoEntries;

		protected override string LabelVerb
		{
			[CompilerGenerated]
			get
			{
				return labelVerb;
			}
		}

		public BulkModifyObjectsUndoEntry(string labelVerb, IEnumerable<CreationObject> targetObjects, IEnumerable<UndoEntry> undoEntries, CreationContext creationContext)
			: base(targetObjects, creationContext)
		{
			this.labelVerb = labelVerb;
			this.undoEntries = undoEntries;
			SelectObjectsUndoStep item = new SelectObjectsUndoStep(targetGuids);
			undoSteps.Add(new BulkModifyObjectsUndoStep(this, redo: false));
			undoSteps.Add(item);
			redoSteps.Add(new BulkModifyObjectsUndoStep(this, redo: true));
			redoSteps.Add(item);
			Finalize(creationContext);
		}
	}
}
