	public class CreateObjectsUndoEntry : ModifyObjectsUndoEntry
	{
		private string labelVerb;

		private string labelNoun;

		protected override string LabelVerb
		{
			[CompilerGenerated]
			get
			{
				return labelVerb;
			}
		}

		public override string Label
		{
			get
			{
				if (!string.IsNullOrEmpty(labelNoun))
				{
					return $"{LabelVerb} {labelNoun}";
				}
				return base.Label;
			}
		}

		public CreateObjectsUndoEntry(string labelVerb, IEnumerable<CreationObject> objects, CreationContext creationContext)
			: base(objects, creationContext)
		{
			InitializeEntry(labelVerb, null, objects, creationContext);
		}

		public CreateObjectsUndoEntry(string labelVerb, string labelNoun, IEnumerable<CreationObject> objects, CreationContext creationContext)
			: base(objects, creationContext)
		{
			InitializeEntry(labelVerb, labelNoun, objects, creationContext);
		}

		public void InitializeEntry(string labelVerb, string labelNoun, IEnumerable<CreationObject> objects, CreationContext creationContext)
		{
			this.labelVerb = labelVerb;
			this.labelNoun = labelNoun;
			undoSteps.Add(new DestroyObjectsUndoStep(targetGuids));
			Finalize(creationContext);
		}

		protected override IPromise PrepUndo(CreationContext creationContext)
		{
			base.PrepUndo(creationContext);
			Promise promise = new Promise();
			int cost = CreationHelper.CalculateObjectCosts(targetGuids);
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SerializeSpawnableTemplate(targetGuids).Then(delegate(CreationManager.SerializeTemplateResult result)
			{
				CreateObjectsFromTemplateUndoStep item = new CreateObjectsFromTemplateUndoStep(result.spawnableTemplateData, cost);
				redoSteps.Clear();
				redoSteps.Add(item);
				promise.Complete();
			}).Error(delegate(string e)
			{
				promise.Error(e);
			});
			return promise;
		}
	}
