	public class CloneShapesUndoEntry : ModifyShapesUndoEntry
	{
		private ShapeContainer initialShapeContainer;

		protected override string LabelVerb
		{
			[CompilerGenerated]
			get
			{
				return "clone";
			}
		}

		public CloneShapesUndoEntry(ShapeContainer shapeContainer, IEnumerable<Guid> newShapeIds, CreationContext creationContext)
			: base(shapeContainer, newShapeIds, creationContext)
		{
			initialShapeContainer = shapeContainer;
			undoSteps.Add(new DestroyShapesUndoStep(shapeContainer, newShapeIds));
		}

		public override void Finalize(CreationContext creationContext)
		{
			base.Finalize(creationContext);
			if (initialShapeContainer == null)
			{
				UnityEngine.Debug.LogError("Trying to finalize UndoEntry, but its initial ShapeContainer has been destroyed!");
				return;
			}
			int totalColliderCosts;
			ShapeDataCollection shapeDataCollection = creationContext.ShapeCreationContext.SerializeShapesIncludingSelected(initialShapeContainer, targetShapeIds, out totalColliderCosts);
			redoSteps.Add(new CreateShapesUndoStep(initialShapeContainer, shapeDataCollection, totalColliderCosts));
		}
	}
	public sealed class DeleteShapesUndoEntry : ModifyShapesUndoEntry
	{
		protected override string LabelVerb
		{
			[CompilerGenerated]
			get
			{
				return "delete";
			}
		}

		public DeleteShapesUndoEntry(ShapeContainer shapeContainer, IEnumerable<Guid> shapeIds, CreationContext creationContext)
			: base(shapeContainer, shapeIds, creationContext)
		{
			int colliderCosts;
			ShapeDataCollection currentShapeData = GetCurrentShapeData(creationContext, out shapeContainer, out colliderCosts);
			undoSteps.Add(new CreateShapesUndoStep(shapeContainer, currentShapeData, colliderCosts));
			redoSteps.Add(new DestroyShapesUndoStep(shapeContainer, shapeIds));
			Finalize(creationContext);
		}

		protected override IPromise PrepRedo(CreationContext context)
		{
			ShapeContainer shapeContainer;
			int colliderCosts;
			ShapeDataCollection currentShapeData = GetCurrentShapeData(context, out shapeContainer, out colliderCosts);
			if (currentShapeData != null)
			{
				undoSteps.Clear();
				undoSteps.Add(new CreateShapesUndoStep(shapeContainer, currentShapeData, colliderCosts));
			}
			return base.PrepRedo(context);
		}
	}
