			int totalColliderCosts;
			ShapeDataCollection shapeDataCollection = creationContext.ShapeCreationContext.SerializeShapesIncludingSelected(shapeContainer, array, out totalColliderCosts);
			undoSteps.Add(new DestroyShapesUndoStep(shapeContainer, array));
			redoSteps.Add(new CreateShapesUndoStep(shapeContainer, shapeDataCollection, totalColliderCosts));
			Finalize(creationContext);
		}
