		public ManipulateShapesUndoEntry(ShapeContainer shapeContainer, IEnumerable<Guid> shapeIds, CreationContext creationContext)
			: base(shapeContainer, shapeIds, creationContext)
		{
			ShapeDataCollection currentShapeData = GetCurrentShapeData(creationContext, out shapeContainer);
			ShapeDataCollection meshShapeData = GetMeshShapeData(currentShapeData);
			undoSteps.Add(new SetMeshShapeSizesAspectRatiosStep(shapeContainer, meshShapeData));
			undoSteps.Add(new TransformShapesUndoStep(shapeContainer, currentShapeData, transformRotations: false, transformScales: false));
		}

		public override void Finalize(CreationContext creationContext)
		{
			ShapeContainer shapeContainer;
			ShapeDataCollection currentShapeData = GetCurrentShapeData(creationContext, out shapeContainer);
			if (currentShapeData != null)
			{
				ShapeDataCollection meshShapeData = GetMeshShapeData(currentShapeData);
				redoSteps.Add(new SetMeshShapeSizesAspectRatiosStep(shapeContainer, meshShapeData));
				redoSteps.Add(new TransformShapesUndoStep(shapeContainer, currentShapeData, transformRotations: false, transformScales: false));
			}
			base.Finalize(creationContext);
		}

		private ShapeDataCollection GetMeshShapeData(ShapeDataCollection shapeDataCollection)
		{
			ShapeDataCollection shapeDataCollection2 = new ShapeDataCollection();
			foreach (ShapeData shape in shapeDataCollection.Shapes)
			{
				if (shape.MeshShapeData != null)
				{
					shapeDataCollection2.Shapes.Add(shape);
				}
			}
			return shapeDataCollection2;
		}
	}
	public class MergeShapeContainersUndoEntry : UndoEntry
	{
		private List<Guid> shapeIds = new List<Guid>();

		private List<Guid> containerIds = new List<Guid>();

		public override string Label
		{
			[CompilerGenerated]
			get
			{
				return "merge shapes";
			}
		}

		public MergeShapeContainersUndoEntry(ShapeContainer destShapeContainer, IReadOnlyList<ShapeContainer> sourceContainers, SpawnableTemplateData sourceContainerTemplateData, CreationContext creationContext)
		{
			int cost = CreationHelper.CalculateObjectCosts(sourceContainers.Select((ShapeContainer s) => s.CreationObject));
			containerIds.Add(destShapeContainer.PersistenceView.Id);
			foreach (ShapeContainer sourceContainer in sourceContainers)
			{
				containerIds.Add(sourceContainer.PersistenceView.Id);
				shapeIds.AddRange(sourceContainer.AllShapes);
			}
			undoSteps.Add(new DestroyShapesUndoStep(destShapeContainer, shapeIds));
			undoSteps.Add(new CreateObjectsFromTemplateUndoStep(sourceContainerTemplateData, cost));
			undoSteps.Add(new SelectObjectsUndoStep(containerIds.ToArray()));
			redoSteps.Add(new MergeShapeContainersUndoStep(destShapeContainer, sourceContainers));
			Finalize(creationContext);
		}
	}
