	public sealed class RecolorShapesContinuousUndoEntry : ModifyShapesUndoEntry
	{
		private class ShapeUndoData
		{
			public ShapeData originalData;

			public ShapeColor newColor;
		}

		private List<ShapeUndoData> shapesData = new List<ShapeUndoData>(1);

		private ShapeContainer initialShapeContainer;

		protected override string LabelVerb
		{
			[CompilerGenerated]
			get
			{
				return "recolor";
			}
		}

		public RecolorShapesContinuousUndoEntry(ShapeContainer shapeContainer, CreationContext creationContext)
			: base(shapeContainer, null, creationContext)
		{
			initialShapeContainer = shapeContainer;
		}

		public void AddOrUpdateShapeData(ShapeDataCollection shapeDataCollection, ShapeColor newColor)
		{
			if (base.IsFinalized)
			{
				UnityEngine.Debug.LogError("Attempting to add shape data to already finalized UndoEntry!");
				return;
			}
			foreach (ShapeData shape in shapeDataCollection.Shapes)
			{
				bool flag = false;
				foreach (ShapeUndoData shapesDatum in shapesData)
				{
					if (shapesDatum.originalData.Id == shape.Id)
					{
						shapesDatum.newColor = newColor;
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					ShapeUndoData shapeUndoData = new ShapeUndoData();
					shapeUndoData.originalData = shape;
					shapeUndoData.newColor = newColor;
					ShapeUndoData item = shapeUndoData;
					shapesData.Add(item);
				}
			}
		}

		public override void Finalize(CreationContext creationContext)
		{
			base.Finalize(creationContext);
			if (initialShapeContainer == null)
			{
				UnityEngine.Debug.LogError("Trying to finalize UndoEntry, but its initial ShapeContainer has been destroyed!");
				return;
			}
			ShapeDataCollection shapeDataCollection = new ShapeDataCollection();
			targetShapeIds = new Guid[shapesData.Count];
			for (int i = 0; i < shapesData.Count; i++)
			{
				ShapeData originalData = shapesData[i].originalData;
				ref Guid reference = ref targetShapeIds[i];
				reference = RecRoom.Protobuf.ByteStringExtensions.ToGuid(originalData.Id);
				shapeDataCollection.Shapes.Add(originalData);
			}
			undoSteps.Add(new RecolorShapesUndoStep(initialShapeContainer, shapeDataCollection));
			for (int j = 0; j < shapesData.Count; j++)
			{
				shapeDataCollection.Shapes[j].ShapeColor = (int)shapesData[j].newColor;
			}
			redoSteps.Add(new RecolorShapesUndoStep(initialShapeContainer, shapeDataCollection));
		}
	}
