	public abstract class UndoEntry
	{
		public delegate IPromise<CreationResult> Operation(CreationContext creationContext);

		protected List<UndoStepBase> undoSteps = new List<UndoStepBase>(1);

		protected List<UndoStepBase> redoSteps = new List<UndoStepBase>(1);

		public abstract string Label { get; }

		public bool IsFinalized { get; private set; }

		public virtual void Finalize(CreationContext creationContext)
		{
			IsFinalized = true;
		}

		public CreationResult ValidateUndo(CreationContext creationContext)
		{
			return ValidateSteps(undoSteps, creationContext);
		}

		public CreationResult ValidateRedo(CreationContext creationContext)
		{
			return ValidateSteps(redoSteps, creationContext);
		}

		public IPromise<CreationResult> PerformUndo(CreationContext creationContext)
		{
			if (!IsFinalized)
			{
				UnityEngine.Debug.LogError($"Attempting to undo {Label} UndoEntry, but it is not yet finalized.");
				return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
			}
			return ValidateAndExecuteSteps(undoSteps, creationContext, PrepUndo);
		}

		public IPromise<CreationResult> PerformRedo(CreationContext creationContext)
		{
			if (!IsFinalized)
			{
				UnityEngine.Debug.LogError($"Attempting to redo {Label} UndoEntry, but it is not yet finalized.");
				return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
			}
			return ValidateAndExecuteSteps(redoSteps, creationContext, PrepRedo);
		}

		protected virtual IPromise PrepUndo(CreationContext creationContext)
		{
			return new CompletedPromise();
		}

		protected virtual IPromise PrepRedo(CreationContext creationContext)
		{
			return new CompletedPromise();
		}

		private IPromise<CreationResult> ValidateAndExecuteSteps(IReadOnlyList<UndoStepBase> steps, CreationContext creationContext, Func<CreationContext, IPromise> preExecuteAction)
		{
			if (steps == null || steps.Count == 0)
			{
				UnityEngine.Debug.LogError($"Error executing UndoEntry {this}: No steps specified.");
				return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
			}
			Promise<CreationResult> requestPromise = new Promise<CreationResult>();
			CreationResult creationResult = ValidateSteps(steps, creationContext);
			if (creationResult == CreationResult.Success)
			{
				if (preExecuteAction != null)
				{
					preExecuteAction(creationContext).Then(delegate
					{
						SingletonMonoBehaviour<Scheduler>.Instance.Run(creationContext, RunUndoStepsRoutine(steps, creationContext, requestPromise));
					}).Error(delegate(string e)
					{
						requestPromise.Error(e);
					});
				}
				else
				{
					SingletonMonoBehaviour<Scheduler>.Instance.Run(creationContext, RunUndoStepsRoutine(steps, creationContext, requestPromise));
				}
			}
			else
			{
				requestPromise.Complete(creationResult);
			}
			return requestPromise;
		}

		private IEnumerator<ISchedule> RunUndoStepsRoutine(IReadOnlyList<UndoStepBase> steps, CreationContext creationContext, Promise<CreationResult> completePromise)
		{
			CreationResult result = CreationResult.Success;
			foreach (UndoStepBase step in steps)
			{
				IPromise stepPromise = null;
				string error = null;
				result = ValidateStep(step, creationContext);
				if (result != CreationResult.Success)
				{
					UnityEngine.Debug.LogErrorFormat("UndoStep {0} validation failed during execution: {1}", step, result);
					break;
				}
				try
				{
					stepPromise = step.Perform(creationContext);
					stepPromise.Error(delegate(string e)
					{
						error = e;
					});
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogErrorFormat("Exception thrown while executing UndoStep {0}: {1}", step, ex);
					result = CreationResult.Failure_Generic;
				}
				if (stepPromise != null && !stepPromise.IsCompleted)
				{
					yield return Schedule.Until(() => stepPromise.IsCompleted);
				}
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError($"Error returned while executing UndoStep {step}: {error}");
					result = CreationResult.Failure_Generic;
					break;
				}
			}
			completePromise.Complete(result);
		}

		private CreationResult ValidateSteps(IReadOnlyList<UndoStepBase> steps, CreationContext creationContext)
		{
			CreationResult creationResult = CreationResult.Success;
			foreach (UndoStepBase step in steps)
			{
				creationResult = ValidateStep(step, creationContext);
				if (creationResult != CreationResult.Success)
				{
					UnityEngine.Debug.LogFormat("UndoStep {0} validation failed: {1}", step, creationResult);
					break;
				}
			}
			return creationResult;
		}

		private CreationResult ValidateStep(UndoStepBase step, CreationContext creationContext)
		{
			try
			{
				return step.ValidateEntries(creationContext);
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogErrorFormat("Exception thrown while validating UndoStep {0}: {1}", step, ex);
				return CreationResult.Failure_Generic;
			}
		}
	}
	public class UndoStack : Photon.MonoBehaviour
	{
		[SerializeField]
		private int maxLength = 10;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private MakerPen makerPen;

		public readonly ActionEvent EntriesChanged = new ActionEvent(3);

		private WalkableStack<UndoEntry> entries;

		private Promise<CreationResult> pendingRequest;

		public bool HasPendingRequest => pendingRequest != null;

		public bool CanUndo => entries.Head != null;

		public bool CanRedo => entries.Next != null;

		public string UndoLabel
		{
			get
			{
				if (CanUndo)
				{
					return entries.Head.Label;
				}
				return string.Empty;
			}
		}

		public string RedoLabel
		{
			get
			{
				if (CanRedo)
				{
					return entries.Next.Label;
				}
				return string.Empty;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			entries = new WalkableStack<UndoEntry>(maxLength);
			PhotonNetwork.OnMasterClientSwitched.Add(OnMasterClientSwitched);
		}

		private void Start()
		{
			NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadSuccessEvent += Clear;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnMasterClientSwitched.Remove(OnMasterClientSwitched);
			if (NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomReloadSuccessEvent -= Clear;
			}
		}

		private void OnMasterClientSwitched(PhotonPlayer player)
		{
			if (pendingRequest != null)
			{
				pendingRequest.Complete(CreationResult.Failure_NetworkError);
			}
		}

		public void Add(UndoEntry entry)
		{
			entries.Add(entry);
			EntriesChanged.Invoke();
		}

		public void Clear()
		{
			entries.Clear();
			EntriesChanged.Invoke();
		}

		public IPromise<CreationResult> RequestUndo()
		{
			if (CanUndo)
			{
				UndoEntry head = entries.Head;
				entries.WalkBack();
				EntriesChanged.Invoke();
				return PerformUndoOperation(head.PerformUndo);
			}
			return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
		}

		public IPromise<CreationResult> RequestRedo()
		{
			if (CanRedo)
			{
				UndoEntry next = entries.Next;
				entries.WalkForward();
				EntriesChanged.Invoke();
				return PerformUndoOperation(next.PerformRedo);
			}
			return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
		}

		private IPromise<CreationResult> PerformUndoOperation(UndoEntry.Operation operation)
		{
			if (HasPendingRequest)
			{
				UnityEngine.Debug.LogErrorFormat("Requesting an undo operation while another is pending is not allowed.");
				return new CompletedPromise<CreationResult>(CreationResult.Failure_Generic);
			}
			Promise<CreationResult> result = (pendingRequest = new Promise<CreationResult>());
			pendingRequest.Finally(delegate
			{
				pendingRequest = null;
			});
			operation(makerPen.CreationContext).Then(delegate(CreationResult payload)
			{
				pendingRequest.Complete(payload);
			}).Error(delegate(string e)
			{
				pendingRequest.Error(e);
			});
			return result;
		}
	}
	public abstract class UndoStepBase
	{
		public override string ToString()
		{
			return GetType().ToString();
		}

		public abstract IPromise Perform(CreationContext context);

		public abstract CreationResult ValidateEntries(CreationContext context);
	}
	public class CreateObjectsFromTemplateUndoStep : UndoStepBase
	{
		private SpawnableTemplateData templateData;

		private int createObjectsCost;

		public CreateObjectsFromTemplateUndoStep(SpawnableTemplateData data, int cost)
		{
			templateData = data;
			createObjectsCost = cost;
		}

		public override IPromise Perform(CreationContext context)
		{
			Promise promise = new Promise();
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnTemplate(templateData, createObjectsCost, assignNewIds: false).Then(delegate(CreationManager.SpawnTemplateResult result)
			{
				context.RemoveAllFromSelection();
				foreach (Tool spawnedTool in result.spawnedTools)
				{
					context.AddToSelection(spawnedTool.CreationObject);
				}
				promise.Complete();
			}).Error(promise.Error);
			return promise;
		}

		public override CreationResult ValidateEntries(CreationContext context)
		{
			if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(createObjectsCost))
			{
				return CreationResult.Success;
			}
			return CreationResult.Failure_InsufficientResources;
		}
	}
