	public abstract class ModifyObjectsUndoStep : UndoStepBase
	{
		protected Guid[] objectGuids;

		public ModifyObjectsUndoStep(Guid[] objectGuids)
		{
			this.objectGuids = objectGuids;
		}

		public override IPromise Perform(CreationContext context)
		{
			context.RemoveAllFromSelection();
			Guid[] array = objectGuids;
			foreach (Guid id in array)
			{
				if (CreationHelper.TryGetCreationObjectFromId(id, out var creationObject))
				{
					context.AddToSelection(creationObject);
				}
			}
			ModifySelectedObjects(context);
			return new CompletedPromise();
		}

		protected virtual void ModifySelectedObjects(CreationContext context)
		{
		}

		public override CreationResult ValidateEntries(CreationContext context)
		{
			CreationResult result = CreationResult.Failure_ObjectDoesNotExist;
			Guid[] array = objectGuids;
			foreach (Guid id in array)
			{
				if (CreationHelper.TryGetCreationObjectFromId(id, out var creationObject))
				{
					if (!creationObject.Tool.AllowedToTakeOwnership)
					{
						return CreationResult.Failure_LockedByOther;
					}
					result = CreationResult.Success;
				}
			}
			return result;
		}
	}
