	public class TransformObjectsUndoStep : ModifyObjectsUndoStep
	{
		private Vector3[] objectPositions;

		private Quaternion[] objectRotations;

		private float[] objectScales;

		public TransformObjectsUndoStep(Guid[] objectGuids, bool transformRotations, bool transformScales)
			: base(objectGuids)
		{
			PopulateObjectTransformData(transformRotations, transformScales);
		}

		private void PopulateObjectTransformData(bool transformRotations, bool transformScales)
		{
			objectPositions = new Vector3[objectGuids.Length];
			if (transformRotations)
			{
				objectRotations = new Quaternion[objectGuids.Length];
			}
			if (transformScales)
			{
				objectScales = new float[objectGuids.Length];
			}
			Tool tool = null;
			for (int i = 0; i < objectGuids.Length; i++)
			{
				if (CreationHelper.TryGetToolFromId(objectGuids[i], out tool))
				{
					ref Vector3 reference = ref objectPositions[i];
					reference = tool.transform.position;
					if (transformRotations)
					{
						ref Quaternion reference2 = ref objectRotations[i];
						reference2 = tool.transform.rotation;
					}
					if (transformScales)
					{
						objectScales[i] = tool.transform.localScale.x;
					}
				}
			}
		}

		protected override void ModifySelectedObjects(CreationContext context)
		{
			context.SetObjectTransforms(objectGuids, objectPositions, objectRotations, objectScales);
		}
	}
	public class CreateShapesUndoStep : UndoStepBase
	{
		private Guid shapeContainerId;

		private Vector3 shapeContainerPosition;

		private Quaternion shapeContainerRotation;

		private float shapeContainerScale;

		private int shapeColliderCosts;

		private SpawnableToolType shapeContainerType;

		private ShapeDataCollection shapeDataCollection;

		public CreateShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection, int shapeColliderCosts)
		{
			shapeContainerId = shapeContainer.PersistenceView.Id;
			shapeContainerType = shapeContainer.Tool.SpawnableToolType;
			shapeContainerPosition = shapeContainer.transform.position;
			shapeContainerRotation = shapeContainer.transform.rotation;
			shapeContainerScale = shapeContainer.transform.GetLocalUniformScale();
			this.shapeDataCollection = shapeDataCollection;
			this.shapeColliderCosts = shapeColliderCosts;
		}

		public override IPromise Perform(CreationContext creationContext)
		{
			Promise completionPromise = new Promise();
			if (CreationHelper.TryGetShapeContainerFromId(shapeContainerId, out var shapeContainer))
			{
				SelectAndAddShapesToShapeContainer(shapeContainer, creationContext, completionPromise);
			}
			else if (ShapeSettings.IsSpawnableShapeContainer(shapeContainerType))
			{
				NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnTool(shapeContainerType, shapeContainerPosition, shapeContainerRotation, shapeContainerScale, shapeContainerId).Then(delegate(Tool tool)
				{
					shapeContainer = tool.GetComponent<ShapeContainer>();
					if (shapeContainer != null)
					{
						SelectAndAddShapesToShapeContainer(shapeContainer, creationContext, completionPromise);
					}
					else
					{
						completionPromise.Error("Master returned null shape container");
					}
				}).Error(completionPromise.Error);
			}
			else
			{
				completionPromise.Error($"CreateShapesUndoStep is unable to spawn missing ShapeContainer of type {shapeContainerType}");
			}
			return completionPromise;
		}

		private void SelectAndAddShapesToShapeContainer(ShapeContainer shapeContainer, CreationContext creationContext, Promise completionPromise)
		{
			if (shapeContainer == null)
			{
				completionPromise.Error("Unable to select null shape container.");
			}
			else if (creationContext.ShapeCreationContext.SelectedShapeContainer == shapeContainer || creationContext.ShapeCreationContext.TrySelectShapeContainer(shapeContainer))
			{
				if (creationContext.ShapeCreationContext.TryAddAndSelectShapesInSelectedShapeContainer(shapeDataCollection, shapeColliderCosts))
				{
					completionPromise.Complete();
				}
				else
				{
					completionPromise.Error("CreateShapesUndoStep failed to add shapes to the selected container.");
				}
			}
			else
			{
				completionPromise.Error("CreateShapesUndoStep failed to select shape container.");
			}
		}

		public override CreationResult ValidateEntries(CreationContext creationContext)
		{
			if (!CreationHelper.TryGetShapeContainerFromId(shapeContainerId, out var shapeContainer))
			{
				if (shapeContainerType != SpawnableToolType.INVALID)
				{
					if (!creationContext.ShapeCreationContext.CanAffordNewShapeContainer(shapeContainerType, shapeColliderCosts))
					{
						return CreationResult.Failure_InsufficientResources;
					}
					return CreationResult.Success;
				}
				return CreationResult.Failure_ObjectDoesNotExist;
			}
			if (shapeContainer.CreationObject.IsLocked && !shapeContainer.CreationObject.LocalPlayerHasLock)
			{
				return CreationResult.Failure_LockedByOther;
			}
			if (!creationContext.ShapeCreationContext.CanAffordToAddShapes(shapeContainer, shapeColliderCosts))
			{
				return CreationResult.Failure_InsufficientResources;
			}
			RepeatedField<ShapeData> shapes = shapeDataCollection.Shapes;
			IEnumerable<Guid> shapeIds = shapes.Select((ShapeData shape) => RecRoom.Protobuf.ByteStringExtensions.ToGuid(shape.Id));
			if (shapeContainer.ContainsAnyShape(shapeIds))
			{
				return CreationResult.Failure_ObjectAlreadyExists;
			}
			if (creationContext.ShapeCreationContext.AnySelected(shapeIds))
			{
				return CreationResult.Failure_ObjectAlreadyExists;
			}
			return CreationResult.Success;
		}
	}
	public class DestroyShapesUndoStep : ModifyShapesUndoStep
	{
		public DestroyShapesUndoStep(ShapeContainer shapeContainer, IEnumerable<Guid> shapeIds)
			: base(shapeContainer, null)
		{
			base.shapeIds = shapeIds.ToArray();
		}

		public DestroyShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection)
			: base(shapeContainer, shapeDataCollection)
		{
		}

		protected override void ModifySelectedShapes(CreationContext creationContext)
		{
			creationContext.ShapeCreationContext.DeleteSelectedShapes();
		}
	}
	public sealed class MergeShapeContainersUndoStep : UndoStepBase
	{
		private static readonly List<ShapeContainer> INSTANTANEOUS_SHAPE_CONTAINER_LIST = new List<ShapeContainer>();

		private Guid destShapeContainerId;

		private Guid[] sourceShapeContainerIds;

		public MergeShapeContainersUndoStep(ShapeContainer destShapeContainer, IReadOnlyList<ShapeContainer> sourceShapeContainers)
		{
			destShapeContainerId = destShapeContainer.PersistenceView.Id;
			sourceShapeContainerIds = new Guid[sourceShapeContainers.Count];
			for (int i = 0; i < sourceShapeContainerIds.Length; i++)
			{
				ref Guid reference = ref sourceShapeContainerIds[i];
				reference = sourceShapeContainers[i].PersistenceView.Id;
			}
		}

		public override IPromise Perform(CreationContext creationContext)
		{
			creationContext.RemoveAllFromSelection();
			INSTANTANEOUS_SHAPE_CONTAINER_LIST.Clear();
			if (TryAddShapeContainerToSelection(creationContext, destShapeContainerId, out var container))
			{
				Guid[] array = sourceShapeContainerIds;
				foreach (Guid guid in array)
				{
					if (TryAddShapeContainerToSelection(creationContext, guid, out var container2))
					{
						INSTANTANEOUS_SHAPE_CONTAINER_LIST.Add(container2);
						continue;
					}
					return new ErroredPromise($"Unable to select shape container to merge: {guid}");
				}
				if (creationContext.TryMergeShapeSelection(container, INSTANTANEOUS_SHAPE_CONTAINER_LIST))
				{
					return new CompletedPromise();
				}
				return new ErroredPromise("Failed to merge shape containers");
			}
			return new ErroredPromise($"Unable to select destination shape container to merge: {destShapeContainerId}");
		}

		private bool TryAddShapeContainerToSelection(CreationContext creationContext, Guid containerId, out ShapeContainer container)
		{
			if (CreationHelper.TryGetShapeContainerFromId(containerId, out container) && creationContext.AddToSelection(container.CreationObject))
			{
				return true;
			}
			return false;
		}

		public override CreationResult ValidateEntries(CreationContext creationContext)
		{
			CreationResult creationResult = CreationResult.Success;
			Guid[] array = sourceShapeContainerIds;
			foreach (Guid shapeContainerId in array)
			{
				creationResult = ValidateShapeContainer(shapeContainerId);
				if (creationResult != CreationResult.Success)
				{
					break;
				}
			}
			return creationResult;
		}

		private CreationResult ValidateShapeContainer(Guid shapeContainerId)
		{
			if (!CreationHelper.TryGetShapeContainerFromId(shapeContainerId, out var shapeContainer))
			{
				return CreationResult.Failure_ObjectDoesNotExist;
			}
			if (!shapeContainer.CanBeMerged)
			{
				return CreationResult.Failure_PermissionDenied;
			}
			if (!shapeContainer.CreationObject.Tool.AllowedToTakeOwnership)
			{
				return CreationResult.Failure_LockedByOther;
			}
			return CreationResult.Success;
		}
	}
	public abstract class ModifyShapesUndoStep : UndoStepBase
	{
		protected Guid shapeContainerId;

		protected Guid[] shapeIds;

		public ModifyShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection)
		{
			shapeContainerId = shapeContainer.PersistenceView.Id;
			if (shapeDataCollection != null)
			{
				if (shapeDataCollection.Shapes.Count == 0)
				{
					UnityEngine.Debug.LogError("ModifyShapesUndoStep created with no shape data.");
				}
				shapeIds = new Guid[shapeDataCollection.Shapes.Count];
				for (int i = 0; i < shapeDataCollection.Shapes.Count; i++)
				{
					ref Guid reference = ref shapeIds[i];
					reference = RecRoom.Protobuf.ByteStringExtensions.ToGuid(shapeDataCollection.Shapes[i].Id);
				}
			}
		}

		public override IPromise Perform(CreationContext creationContext)
		{
			if (shapeIds == null || shapeIds.Length == 0)
			{
				UnityEngine.Debug.LogError("ModifyShapesUndoStep.Perform() called with no shape data.");
				return new CompletedPromise();
			}
			bool flag = true;
			if (CreationHelper.TryGetShapeContainerFromId(shapeContainerId, out var shapeContainer))
			{
				flag = creationContext.ShapeCreationContext.TrySelectShapeContainer(shapeContainer);
				creationContext.ShapeCreationContext.RemoveAllFromSelection();
				if (flag)
				{
					Guid[] array = shapeIds;
					foreach (Guid shapeId in array)
					{
						creationContext.ShapeCreationContext.AddToSelection(shapeId);
					}
					ModifySelectedShapes(creationContext);
				}
			}
			return new CompletedPromise();
		}

		protected abstract void ModifySelectedShapes(CreationContext creationContext);

		public override CreationResult ValidateEntries(CreationContext creationContext)
		{
			if (!CreationHelper.TryGetShapeContainerFromId(shapeContainerId, out var shapeContainer))
			{
				return CreationResult.Failure_ObjectDoesNotExist;
			}
			if (!shapeContainer.CreationObject.Tool.AllowedToTakeOwnership)
			{
				return CreationResult.Failure_LockedByOther;
			}
			if (!shapeContainer.ContainsAnyShape(shapeIds) && !creationContext.ShapeCreationContext.AnySelected(shapeIds))
			{
				return CreationResult.Failure_ObjectDoesNotExist;
			}
			return CreationResult.Success;
		}
	}
	public sealed class RecolorShapesUndoStep : ModifyShapesUndoStep
	{
		private ShapeColor[] shapeColors;

		public RecolorShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection, ShapeColor color)
			: base(shapeContainer, shapeDataCollection)
		{
			shapeColors = new ShapeColor[1] { color };
		}

		public RecolorShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection)
			: base(shapeContainer, shapeDataCollection)
		{
			int count = shapeDataCollection.Shapes.Count;
			shapeColors = new ShapeColor[count];
			for (int i = 0; i < count; i++)
			{
				ShapeData shapeData = shapeDataCollection.Shapes[i];
				shapeColors[i] = (ShapeColor)shapeData.ShapeColor;
			}
		}

		protected override void ModifySelectedShapes(CreationContext creationContext)
		{
			if (shapeColors.Length == 1)
			{
				creationContext.ShapeCreationContext.RecolorSelectedShapes(shapeColors[0]);
			}
			else
			{
				creationContext.ShapeCreationContext.RecolorSelectedShapes(shapeIds, shapeColors);
			}
		}
	}
	public sealed class SetMeshShapeSizesAspectRatiosStep : ModifyShapesUndoStep
	{
		private Vector3[] shapeAspectRatios;

		public SetMeshShapeSizesAspectRatiosStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection)
			: base(shapeContainer, shapeDataCollection)
		{
			int count = shapeDataCollection.Shapes.Count;
			shapeAspectRatios = new Vector3[count];
			for (int i = 0; i < count; i++)
			{
				ShapeData shapeData = shapeDataCollection.Shapes[i];
				if (shapeData.MeshShapeData == null)
				{
					UnityEngine.Debug.LogError($"Attempting to create UndoStep {this} with non-Mesh Shape {shapeData.Id}");
					continue;
				}
				ref Vector3 reference = ref shapeAspectRatios[i];
				reference = shapeData.MeshShapeData.AspectRatio.ToVector3();
			}
		}

		protected override void ModifySelectedShapes(CreationContext creationContext)
		{
			creationContext.ShapeCreationContext.SetSelectedMeshShapeAspectRatios(shapeIds, shapeAspectRatios);
		}
	}
	public sealed class TransformShapesUndoStep : ModifyShapesUndoStep
	{
		private Vector3[] shapeLocalPositions;

		private Quaternion[] shapeLocalRotations;

		private float[] shapeLocalScales;

		public TransformShapesUndoStep(ShapeContainer shapeContainer, ShapeDataCollection shapeDataCollection, bool transformRotations, bool transformScales)
			: base(shapeContainer, shapeDataCollection)
		{
			int count = shapeDataCollection.Shapes.Count;
			shapeLocalPositions = new Vector3[count];
			shapeLocalRotations = ((!transformRotations) ? null : new Quaternion[count]);
			shapeLocalScales = ((!transformScales) ? null : new float[count]);
			for (int i = 0; i < count; i++)
			{
				ShapeData shapeData = shapeDataCollection.Shapes[i];
				ref Vector3 reference = ref shapeLocalPositions[i];
				reference = shapeData.CurrentLocalPosition.ToVector3();
				if (transformRotations)
				{
					ref Quaternion reference2 = ref shapeLocalRotations[i];
					reference2 = shapeData.CurrentLocalRotation.ToQuaternion();
				}
				if (transformScales)
				{
					shapeLocalScales[i] = shapeData.Scale;
				}
			}
		}

		protected override void ModifySelectedShapes(CreationContext creationContext)
		{
			creationContext.ShapeCreationContext.SetSelectedShapeTransforms(shapeIds, shapeLocalPositions, shapeLocalRotations, shapeLocalScales);
		}
	}
}
public class BezierPath
{
	private const int TOTAL_POINTS_PER_BEZIER_CURVE = 4;

	private const int UNIQUE_POINTS_PER_BEZIER_CURVE = 3;

	private const int LENGTH_SEGMENTS = 5;

	private const float LENGTH_SEGMENT_FRACTION = 0.2f;

	private const int GIZMO_EVALUATION_POINTS_PER_CURVE = 20;

	private List<Vector3> points;

	private List<float> lengthAtCurve;

	public int CurveCount { get; private set; }

	public float PathLength { get; private set; }

	public BezierPath()
	{
		points = new List<Vector3>();
		lengthAtCurve = new List<float>();
		CurveCount = 0;
		PathLength = 0f;
	}

	public void AddCurve(Vector3 start, Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			points.Add(start);
		}
		else if (Vector3.Distance(start, points[points.Count - 1]) > Mathf.Epsilon)
		{
			UnityEngine.Debug.LogError("Tried to add discontinuity to Bezier Path.");
		}
		AddCurve(controlPoint1, controlPoint2, end);
	}

	public void AddCurve(Vector3 controlPoint1, Vector3 controlPoint2, Vector3 end)
	{
		if (points.Count == 0)
		{
			UnityEngine.Debug.LogError("Tried to add a Bezier Path curve without a starting point.");
		}
		points.Add(controlPoint1);
		points.Add(controlPoint2);
		points.Add(end);
		CurveCount++;
		PathLength += CurveLength(CurveCount - 1);
		lengthAtCurve.Add(PathLength);
	}

	public void Clear()
	{
		points.Clear();
		lengthAtCurve.Clear();
		CurveCount = 0;
		PathLength = 0f;
	}

	public Vector3 EvaluatePath(float t)
	{
		if (CurveCount <= 0)
		{
			return Vector3.zero;
		}
		int num = -1;
		float t2 = 0f;
		float num2 = Mathf.Clamp01(t) * PathLength;
		for (int i = 0; i < CurveCount; i++)
		{
			if (num2 <= lengthAtCurve[i])
			{
				num = i;
				float num3 = ((i != 0) ? lengthAtCurve[i - 1] : 0f);
				float num4 = lengthAtCurve[i] - num3;
				t2 = (num2 - num3) / num4;
				break;
			}
		}
		if (num < 0)
		{
			num = CurveCount - 1;
			t2 = 1f;
		}
		return EvaluateBezierCurve(num, t2);
	}

	public void DrawGizmos()
	{
		for (int i = 0; i < CurveCount; i++)
		{
			DrawGizmosBezierCurve(i);
		}
	}

	private Vector3 EvaluateBezierCurve(int curveIndex, float t)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 vector2 = points[curveIndex * 3 + 1];
		Vector3 vector3 = points[curveIndex * 3 + 2];
		Vector3 vector4 = points[curveIndex * 3 + 3];
		float num = 1f - t;
		return vector * num * num * num + vector2 * 3f * num * num * t + vector3 * 3f * num * t * t + vector4 * t * t * t;
	}

	private float CurveLength(int curveIndex)
	{
		float num = 0f;
		float num2 = 0f;
		Vector3 vector = EvaluateBezierCurve(curveIndex, num2);
		for (int i = 0; i < 5; i++)
		{
			num2 += 0.2f;
			Vector3 vector2 = EvaluateBezierCurve(curveIndex, num2);
			num += (vector2 - vector).magnitude;
			vector = vector2;
		}
		return num;
	}

	private void DrawGizmosBezierCurve(int curveIndex)
	{
		Vector3 vector = points[curveIndex * 3];
		Vector3 vector2 = points[curveIndex * 3 + 1];
		Vector3 vector3 = points[curveIndex * 3 + 2];
		Vector3 vector4 = points[curveIndex * 3 + 3];
		Gizmos.color = Color.blue;
		Vector3 vector5 = vector;
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < 20; i++)
		{
			zero = EvaluateBezierCurve(curveIndex, (float)i / 19f);
			Gizmos.DrawLine(vector5, zero);
			vector5 = zero;
		}
	}
}
namespace RecRoom.Core.Scripts.DataStructures
{
	public abstract class AbstractStateMachine
	{
		public delegate void OnStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId);

		public delegate void StateTransition(ushort otherStateId, ushort otherSubStateId);

		public delegate void StateUpdate();

		public const ushort INVALID_STATE_ID = ushort.MaxValue;
	}
	public abstract class AbstractStateMachine<T> : AbstractStateMachine where T : AbstractStateMachine<T>.IState
	{
		public interface IState
		{
			StateTransition OnEnter { get; }

			StateTransition OnExit { get; }

			StateUpdate OnUpdate { get; }
		}

		private Dictionary<uint, T> states = new Dictionary<uint, T>();

		private StateUpdate cachedSuperStateOnUpdate;

		private StateUpdate cachedSubStateOnUpdate;

		public ushort CurrentStateId { get; private set; }

		public ushort CurrentSubStateId { get; private set; }

		public ushort PreviousStateId { get; private set; }

		public ushort PreviousSubStateId { get; private set; }

		protected bool HasCachedSuperStateOnUpdate => cachedSuperStateOnUpdate != null;

		protected bool HasCachedSubStateOnUpdate => cachedSubStateOnUpdate != null;

		public event OnStateChange StateChangeEvent
		{
			add
			{
				OnStateChange onStateChange = this.StateChangeEvent;
				OnStateChange onStateChange2;
				do
				{
					onStateChange2 = onStateChange;
					onStateChange = Interlocked.CompareExchange(ref this.StateChangeEvent, (OnStateChange)Delegate.Combine(onStateChange2, value), onStateChange);
				}
				while (onStateChange != onStateChange2);
			}
			remove
			{
				OnStateChange onStateChange = this.StateChangeEvent;
				OnStateChange onStateChange2;
				do
				{
					onStateChange2 = onStateChange;
					onStateChange = Interlocked.CompareExchange(ref this.StateChangeEvent, (OnStateChange)Delegate.Remove(onStateChange2, value), onStateChange);
				}
				while (onStateChange != onStateChange2);
			}
		}

		protected AbstractStateMachine()
		{
			PreviousStateId = ushort.MaxValue;
			PreviousSubStateId = ushort.MaxValue;
			CurrentStateId = ushort.MaxValue;
			CurrentSubStateId = ushort.MaxValue;
		}

		private T GetSuperState(ushort superStateId)
		{
			T value = default(T);
			if (superStateId != ushort.MaxValue)
			{
				states.TryGetValue(GetFullyQualifiedStateId(superStateId, ushort.MaxValue), out value);
			}
			return value;
		}

		private T GetSubState(ushort superStateId, ushort subStateId)
		{
			T value = default(T);
			if (superStateId != ushort.MaxValue && subStateId != ushort.MaxValue)
			{
				states.TryGetValue(GetFullyQualifiedStateId(superStateId, subStateId), out value);
			}
			return value;
		}

		protected T GetFullyQualifiedState(uint fullyQualifiedStateId)
		{
			states.TryGetValue(fullyQualifiedStateId, out var value);
			return value;
		}

		public void EnterState(ushort nextStateId)
		{
			EnterState(nextStateId, ushort.MaxValue);
		}

		public void EnterState(ushort nextStateId, ushort nextSubStateId)
		{
			EnterState(GetFullyQualifiedStateId(nextStateId, nextSubStateId));
		}

		protected virtual void EnterState(uint nextFullyQualifiedStateId)
		{
			uint fullyQualifiedStateId = GetFullyQualifiedStateId(CurrentStateId, CurrentSubStateId);
			RunStateTransition(nextFullyQualifiedStateId, fullyQualifiedStateId);
		}

		protected void RunStateTransition(uint nextFullyQualifiedStateId, uint previousFullyQualifiedStateId)
		{
			ushort superStateIdFromFullyQualifiedId = GetSuperStateIdFromFullyQualifiedId(nextFullyQualifiedStateId);
			ushort subStateIdFromFullyQualifiedId = GetSubStateIdFromFullyQualifiedId(nextFullyQualifiedStateId);
			bool flag = superStateIdFromFullyQualifiedId != CurrentStateId;
			bool flag2 = subStateIdFromFullyQualifiedId != CurrentSubStateId;
			T subState = GetSubState(CurrentStateId, CurrentSubStateId);
			if ((flag || flag2) && subState != null && subState.OnExit != null)
			{
				subState.OnExit(superStateIdFromFullyQualifiedId, subStateIdFromFullyQualifiedId);
			}
			T superState = GetSuperState(CurrentStateId);
			if (flag && superState != null && superState.OnExit != null)
			{
				superState.OnExit(superStateIdFromFullyQualifiedId, subStateIdFromFullyQualifiedId);
			}
			PreviousStateId = GetSuperStateIdFromFullyQualifiedId(previousFullyQualifiedStateId);
			PreviousSubStateId = GetSubStateIdFromFullyQualifiedId(previousFullyQualifiedStateId);
			CurrentStateId = superStateIdFromFullyQualifiedId;
			CurrentSubStateId = subStateIdFromFullyQualifiedId;
			if (flag)
			{
				superState = GetSuperState(CurrentStateId);
				if (superState != null)
				{
					cachedSuperStateOnUpdate = superState.OnUpdate;
					superState.OnEnter?.Invoke(PreviousStateId, PreviousSubStateId);
				}
				else
				{
					cachedSuperStateOnUpdate = null;
				}
			}
			if (flag || flag2)
			{
				subState = GetSubState(CurrentStateId, CurrentSubStateId);
				if (subState != null)
				{
					cachedSubStateOnUpdate = subState.OnUpdate;
					subState.OnEnter?.Invoke(PreviousStateId, PreviousSubStateId);
				}
				else
				{
					cachedSubStateOnUpdate = null;
				}
			}
			if (this.StateChangeEvent != null)
			{
				this.StateChangeEvent(superStateIdFromFullyQualifiedId, PreviousStateId, subStateIdFromFullyQualifiedId, PreviousSubStateId);
			}
		}

		protected void AddStateInternal(ushort stateId, T state)
		{
			AddStateInternal(stateId, ushort.MaxValue, state);
		}

		protected void AddStateInternal(ushort superStateId, ushort subStateId, T state)
		{
			SetFullyQualifiedState(GetFullyQualifiedStateId(superStateId, subStateId), state);
		}

		private void SetFullyQualifiedState(uint fullyQualifiedStateId, T state)
		{
			states.Add(fullyQualifiedStateId, state);
		}

		protected void UpdateStateMachine(float deltaTime)
		{
			if (cachedSuperStateOnUpdate != null)
			{
				cachedSuperStateOnUpdate();
			}
			if (cachedSubStateOnUpdate != null)
			{
				cachedSubStateOnUpdate();
			}
		}

		protected uint GetFullyQualifiedStateId(ushort superStateId, ushort subStateId)
		{
			return (uint)((superStateId << 16) + subStateId);
		}

		protected ushort GetSuperStateIdFromFullyQualifiedId(uint fullyQualifiedId)
		{
			return (ushort)(fullyQualifiedId >> 16);
		}

		protected ushort GetSubStateIdFromFullyQualifiedId(uint fullyQualifiedId)
		{
			return (ushort)fullyQualifiedId;
		}
	}
	public abstract class ManualUpdateAbstractStateMachine : AbstractStateMachine<ManualUpdateAbstractStateMachine.State>
	{
		public class State : IState
		{
			public StateTransition OnEnter { get; set; }

			public StateTransition OnExit { get; set; }

			public StateUpdate OnUpdate { get; set; }
		}

		public void AddState(ushort stateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate)
		{
			AddState(stateId, ushort.MaxValue, onEnter, onExit, onUpdate);
		}

		public void AddState(ushort superStateId, ushort subStateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate)
		{
			AddStateInternal(superStateId, subStateId, new State
			{
				OnEnter = onEnter,
				OnExit = onExit,
				OnUpdate = onUpdate
			});
		}

		public void Update()
		{
			UpdateStateMachine(UnityEngine.Time.deltaTime);
		}
	}
	public abstract class AutoScheduledAbstractStateMachine : AbstractStateMachine<AutoScheduledAbstractStateMachine.State>
	{
		public class State : IState
		{
			public float AuthorityUpdateHz = -1f;

			public float NonAuthorityUpdateHz = -1f;

			public StateTransition OnEnter { get; set; }

			public StateTransition OnExit { get; set; }

			public StateUpdate OnUpdate { get; set; }
		}

		public const float UPDATE_EVERY_FRAME_HZ = -1f;

		public const float DO_NOT_UPDATE_HZ = 0f;

		private readonly Scheduler.QueueType _queueType;

		private readonly float? _defaultUpdateHertz;

		protected readonly Photon.MonoBehaviour Context;

		private IDisposable _updateToken;

		private AutoScheduledAbstractStateMachine()
		{
		}

		protected AutoScheduledAbstractStateMachine(Photon.MonoBehaviour context, Scheduler.QueueType queueType = Scheduler.QueueType.Update)
			: this()
		{
			Context = context;
			_queueType = queueType;
			PhotonView photonView = Context.photonView;
			photonView.OnCachedAuthorityChanged = (PhotonView.OnCachedAuthorityChangedEvent)Delegate.Combine(photonView.OnCachedAuthorityChanged, new PhotonView.OnCachedAuthorityChangedEvent(OnContextAuthorityChanged));
			base.StateChangeEvent += OnStateChanged;
		}

		public void AddState(ushort stateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate, float authorityUpdateHz, float nonAuthorityUpdateHz)
		{
			AddState(stateId, ushort.MaxValue, onEnter, onExit, onUpdate, authorityUpdateHz, nonAuthorityUpdateHz);
		}

		public void AddState(ushort superStateId, ushort subStateId, StateTransition onEnter, StateTransition onExit, StateUpdate onUpdate, float authorityUpdateHz, float nonAuthorityUpdateHz)
		{
			State state = new State();
			state.OnEnter = onEnter;
			state.OnExit = onExit;
			state.OnUpdate = onUpdate;
			state.AuthorityUpdateHz = authorityUpdateHz;
			state.NonAuthorityUpdateHz = nonAuthorityUpdateHz;
			State state2 = state;
			AddStateInternal(superStateId, subStateId, state2);
		}

		private void OnContextAuthorityChanged(PhotonPlayer newAuthority)
		{
			RescheduleUpdate();
		}

		private void OnStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubstateId, ushort previousSubstateId)
		{
			RescheduleUpdate();
		}

		private void RescheduleUpdate()
		{
			TryDisposeUpdateToken();
			uint fullyQualifiedStateId = GetFullyQualifiedStateId(base.CurrentStateId, base.CurrentSubStateId);
			if (ShouldUpdate(fullyQualifiedStateId, out var updateHz))
			{
				if (updateHz > 0f)
				{
					_updateToken = Context.QueueUpdateAtRate(updateHz, base.UpdateStateMachine, _queueType);
				}
				else
				{
					_updateToken = Context.QueueUpdate(base.UpdateStateMachine, _queueType);
				}
			}
		}

		private bool ShouldUpdate(uint fullyQualifiedStateId, out float updateHz)
		{
			updateHz = 0f;
			if (!base.HasCachedSuperStateOnUpdate && !base.HasCachedSubStateOnUpdate)
			{
				return false;
			}
			State fullyQualifiedState = GetFullyQualifiedState(fullyQualifiedStateId);
			bool flag = Context == null || Context.hasAuthority;
			updateHz = ((!flag) ? fullyQualifiedState.NonAuthorityUpdateHz : fullyQualifiedState.AuthorityUpdateHz);
			return updateHz != 0f;
		}

		private void TryDisposeUpdateToken()
		{
			if (_updateToken != null)
			{
				_updateToken.Dispose();
				_updateToken = null;
			}
		}
	}
}
namespace RecRoom.Core.DataStructures
{
	public class IndexedMap<T> : IEnumerable<IndexedMap<T>.Pair>, IEnumerable
	{
		public struct Pair
		{
			public T value;

			public int index;
		}

		public class Enumerator : IEnumerator<Pair>, IEnumerator, IDisposable
		{
			private IndexedMap<T> map;

			private int index = -1;

			object IEnumerator.Current => Current;

			public Pair Current
			{
				get
				{
					try
					{
						return new Pair
						{
							index = index,
							value = map.indexToValue[index].value
						};
					}
					catch (IndexOutOfRangeException)
					{
						throw new InvalidOperationException();
					}
				}
			}

			public Enumerator(IndexedMap<T> map)
			{
				this.map = map;
			}

			public bool MoveNext()
			{
				do
				{
					index++;
				}
				while (index < map.indexToValue.Length && !map.indexToValue[index].hasValue);
				return index < map.indexToValue.Length;
			}

			public void Reset()
			{
				index = -1;
			}

			public void Dispose()
			{
				map = null;
			}
		}

		private struct ListEntry
		{
			public bool hasValue;

			public T value;
		}

		private const int DEFAULT_CAPACITY = 32;

		private Dictionary<T, int> valueToIndex;

		private ListEntry[] indexToValue;

		private int firstEmptyIndex;

		public int Count => valueToIndex.Count;

		public IndexedMap(int capacity)
		{
			valueToIndex = new Dictionary<T, int>(capacity);
			indexToValue = new ListEntry[capacity];
		}

		public static IndexedMap<T> FromArray(Pair[] pairs, bool expand)
		{
			if (pairs.Length > 0)
			{
				int num = -1;
				for (int i = 0; i < pairs.Length; i++)
				{
					Pair pair = pairs[i];
					if (pair.index > num)
					{
						num = pair.index;
					}
				}
				int num2 = num + 1;
				if (expand)
				{
					num2 *= 2;
				}
				if (pairs.Length > num + 1)
				{
					throw new ArgumentException("IndexMap: Construction array has invalid indices.");
				}
				IndexedMap<T> indexedMap = new IndexedMap<T>(num2);
				for (int j = 0; j < pairs.Length; j++)
				{
					Pair pair2 = pairs[j];
					if (indexedMap.indexToValue[pair2.index].hasValue)
					{
						throw new ArgumentException("IndexMap: Construction array has duplicate indices.");
					}
					ref ListEntry reference = ref indexedMap.indexToValue[pair2.index];
					reference = new ListEntry
					{
						hasValue = true,
						value = pair2.value
					};
					indexedMap.valueToIndex[pair2.value] = pair2.index;
				}
				return indexedMap;
			}
			int capacity = (expand ? 32 : 0);
			return new IndexedMap<T>(capacity);
		}

		public bool ContainsValue(T value)
		{
			return valueToIndex.ContainsKey(value);
		}

		public bool ContainsIndex(int index)
		{
			if (index < 0 || index >= indexToValue.Length)
			{
				return false;
			}
			return indexToValue[index].hasValue;
		}

		public bool Contains(Func<T, bool> filter)
		{
			ListEntry[] array = indexToValue;
			for (int i = 0; i < array.Length; i++)
			{
				ListEntry listEntry = array[i];
				if (listEntry.hasValue && filter(listEntry.value))
				{
					return true;
				}
			}
			return false;
		}

		public int GetIndex(T value)
		{
			if (valueToIndex.TryGetValue(value, out var value2))
			{
				return value2;
			}
			return -1;
		}

		public T GetValue(int index)
		{
			if (index < 0 || index >= indexToValue.Length || !indexToValue[index].hasValue)
			{
				return default(T);
			}
			return indexToValue[index].value;
		}

		public void Clear()
		{
			valueToIndex.Clear();
			Array.Clear(indexToValue, 0, indexToValue.Length);
			firstEmptyIndex = 0;
		}

		public bool TryAdd(T value)
		{
			return TryAdd(value, firstEmptyIndex);
		}

		public bool TryAdd(T value, int index)
		{
			if (!valueToIndex.ContainsKey(value))
			{
				ListEntry listEntry = new ListEntry
				{
					hasValue = true,
					value = value
				};
				if (index >= indexToValue.Length)
				{
					int num = Mathf.Max(index + 1, indexToValue.Length * 2);
					ListEntry[] destinationArray = new ListEntry[num];
					Array.Copy(indexToValue, 0, destinationArray, 0, indexToValue.Length);
					indexToValue = destinationArray;
				}
				if (!indexToValue[index].hasValue)
				{
					indexToValue[index] = listEntry;
					valueToIndex[value] = index;
					firstEmptyIndex = FindNextEmptyIndex(firstEmptyIndex);
					return true;
				}
				return false;
			}
			return false;
		}

		public bool Remove(T value)
		{
			if (valueToIndex.TryGetValue(value, out var value2))
			{
				RemoveInternal(value2);
				return true;
			}
			return false;
		}

		public bool RemoveAt(int index)
		{
			if (index < 0 || index >= indexToValue.Length)
			{
				return false;
			}
			RemoveInternal(index);
			return true;
		}

		private void RemoveInternal(int index)
		{
			T value = indexToValue[index].value;
			valueToIndex.Remove(value);
			indexToValue[index] = default(ListEntry);
			if (index < firstEmptyIndex)
			{
				firstEmptyIndex = index;
			}
		}

		public Pair[] ToArray()
		{
			Pair[] array = new Pair[Count];
			int num = 0;
			for (int i = 0; i < indexToValue.Length; i++)
			{
				ListEntry listEntry = indexToValue[i];
				if (listEntry.hasValue)
				{
					ref Pair reference = ref array[num];
					reference = new Pair
					{
						value = listEntry.value,
						index = i
					};
					num++;
				}
			}
			return array;
		}

		private int FindNextEmptyIndex(int startIndex)
		{
			int i;
			for (i = startIndex; i < indexToValue.Length && indexToValue[i].hasValue; i++)
			{
			}
			return i;
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return new Enumerator(this);
		}

		IEnumerator<Pair> IEnumerable<Pair>.GetEnumerator()
		{
			return new Enumerator(this);
		}
	}
}
public class LootTable<T>
{
	private int totalWeight;

	private List<T> valueTable = new List<T>();

	private List<int> weightTable = new List<int>();

	public void AddLoot(T value, int dropWeight)
	{
		valueTable.Add(value);
		weightTable.Add(totalWeight + dropWeight);
		totalWeight += dropWeight;
	}

	public T GetRandomLoot()
	{
		int num = UnityEngine.Random.Range(0, totalWeight);
		for (int i = 0; i < weightTable.Count; i++)
		{
			if (num < weightTable[i])
			{
				return valueTable[i];
			}
		}
		return default(T);
	}

	public void ClearAllLoot()
	{
		valueTable.Clear();
		weightTable.Clear();
		totalWeight = 0;
	}
}
