public abstract class TimestampedRollingBuffer<T>
{
	internal struct BufferEntry
	{
		public T Value;

		public float Timestamp;
	}

	private static float InvalidTime = -1f;

	private List<T> scratchBuffer = new List<T>();

	private const int MAX_SIZE = 16;

	private BufferEntry[] array;

	private int head;

	public float LatestTime { get; private set; }

	public TimestampedRollingBuffer()
		: this(16)
	{
	}

	public TimestampedRollingBuffer(int size)
	{
		array = new BufferEntry[size];
		Clear();
	}

	public void Add(float time, T value)
	{
		LatestTime = time;
		array[head].Timestamp = time;
		array[head].Value = value;
		IncrementHead();
	}

	public void Clear()
	{
		for (int i = 0; i < array.Length; i++)
		{
			array[i].Timestamp = InvalidTime;
		}
		head = 0;
	}

	public bool TryGetAverageValueOverTime(float startTime, float endTime, out T value)
	{
		value = ZeroValue();
		GetValuesInTimeWindow(startTime, endTime, scratchBuffer);
		if (scratchBuffer.Count > 0)
		{
			for (int i = 0; i < scratchBuffer.Count; i++)
			{
				value = Sum(value, scratchBuffer[i]);
			}
			value = Scale(value, 1f / (float)scratchBuffer.Count);
			return true;
		}
		return false;
	}

	public bool TryGetMaximumValueOverTime(float startTime, float endTime, out T value)
	{
		value = ZeroValue();
		GetValuesInTimeWindow(startTime, endTime, scratchBuffer);
		if (scratchBuffer.Count > 0)
		{
			for (int i = 0; i < scratchBuffer.Count; i++)
			{
				value = Max(value, scratchBuffer[i]);
			}
			return true;
		}
		return false;
	}

	internal void GetValuesInTimeWindow(float startTime, float endTime, List<T> buffer)
	{
		buffer.Clear();
		for (int i = 1; i <= array.Length; i++)
		{
			int num = RollingHeadOffset(i);
			if (array[num].Timestamp >= startTime && array[num].Timestamp <= endTime)
			{
				buffer.Add(array[num].Value);
			}
		}
	}

	private int RollingHeadOffset(int headOffset)
	{
		return (head + headOffset) % array.Length;
	}

	private void IncrementHead()
	{
		head = RollingHeadOffset(1);
	}

	protected abstract T ZeroValue();

	protected abstract T Interpolate(T lhs, T rhs, float t);

	protected abstract T Scale(T value, float t);

	protected abstract T Sum(T lhs, T rhs);

	protected abstract T Max(T lhs, T rhs);
}
public class TimestampedRollingBufferVector3 : TimestampedRollingBuffer<Vector3>
{
	protected override Vector3 ZeroValue()
	{
		return Vector3.zero;
	}

	protected override Vector3 Interpolate(Vector3 lhs, Vector3 rhs, float t)
	{
		return Vector3.Lerp(lhs, rhs, t);
	}

	protected override Vector3 Scale(Vector3 value, float t)
	{
		return value * t;
	}

	protected override Vector3 Sum(Vector3 lhs, Vector3 rhs)
	{
		return lhs + rhs;
	}

	protected override Vector3 Max(Vector3 lhs, Vector3 rhs)
	{
		return (!(lhs.sqrMagnitude > rhs.sqrMagnitude)) ? rhs : lhs;
	}
}
public class TimestampedRollingBufferFloat : TimestampedRollingBuffer<float>
{
	public TimestampedRollingBufferFloat()
	{
	}

	public TimestampedRollingBufferFloat(int size)
		: base(size)
	{
	}

	protected override float ZeroValue()
	{
		return 0f;
	}

	protected override float Interpolate(float lhs, float rhs, float t)
	{
		return Mathf.Lerp(lhs, rhs, t);
	}

	protected override float Scale(float value, float t)
	{
		return value * t;
	}

	protected override float Sum(float lhs, float rhs)
	{
		return lhs + rhs;
	}

	protected override float Max(float lhs, float rhs)
	{
		return (!(lhs > rhs)) ? rhs : lhs;
	}
}
namespace RecRoom.Core.DataStructures.Tokens
{
	public class ExplicitTokenMap<T>
	{
		private struct PrioritizedData
		{
			public int Priority;

			public T Value;
		}

		private Dictionary<object, PrioritizedData> dictionary = new Dictionary<object, PrioritizedData>(0);

		private T _highestPriorityValue;

		public virtual T HighestPriorityValue
		{
			get
			{
				return _highestPriorityValue;
			}
			protected set
			{
				_highestPriorityValue = value;
			}
		}

		public object HighestPriorityToken { get; private set; }

		public bool ContainsValues => dictionary.Count > 0;

		public bool AddValue(T value, object token, int priority)
		{
			PrioritizedData value2 = new PrioritizedData
			{
				Priority = priority,
				Value = value
			};
			if (dictionary.ContainsKey(token))
			{
				dictionary[token] = value2;
			}
			else
			{
				dictionary.Add(token, value2);
			}
			return UpdateLatestValue();
		}

		public bool RemoveValue(object token)
		{
			dictionary.Remove(token);
			return UpdateLatestValue();
		}

		public bool TryGetValue(object token, out T value)
		{
			if (dictionary.TryGetValue(token, out var value2))
			{
				value = value2.Value;
				return true;
			}
			value = default(T);
			return false;
		}

		private bool UpdateLatestValue()
		{
			int num = int.MinValue;
			T val = default(T);
			object highestPriorityToken = null;
			foreach (object key in dictionary.Keys)
			{
				PrioritizedData prioritizedData = dictionary[key];
				if (prioritizedData.Priority >= num)
				{
					num = prioritizedData.Priority;
					val = prioritizedData.Value;
					highestPriorityToken = key;
				}
			}
			bool result = !object.Equals(HighestPriorityValue, val);
			HighestPriorityValue = val;
			HighestPriorityToken = highestPriorityToken;
			return result;
		}
	}
	public class ObscuredExplicitTokenMap<T> : ExplicitTokenMap<T>
	{
		private ObscuredDataGeneric<T> _latestObscuredValue = new ObscuredDataGeneric<T>();

		public override T HighestPriorityValue
		{
			get
