namespace RecRoom
{
	public class DropItemNote : DetachMenuNote
	{
		[SerializeField]
		private GameObject canvas;

		private Tool tool;

		public void RefreshNote(Tool tool)
		{
			this.tool = tool;
			tool.RigidbodyPickup.ReachedTargetEvent += RigidbodyPickup_ReachedTargetEvent;
		}

		private void RigidbodyPickup_ReachedTargetEvent()
		{
			tool.RigidbodyPickup.ReachedTargetEvent -= RigidbodyPickup_ReachedTargetEvent;
			if (tool.IsHeldByPlayer)
			{
				int num = ((tool.HolderHand.Type == PlayerHand.HandType.Left) ? 1 : (-1));
				Transform transform = Player.LocalPlayer.Head.transform;
				Vector3 vector = tool.GetColliderBounds().ClosestPoint(transform.position);
				base.transform.position = vector + (transform.position - vector) * 0.01f + transform.up * 0.01f + transform.right * 0.01f * num;
				canvas.transform.rotation = Quaternion.LookRotation(Player.LocalPlayer.Head.transform.forward, Player.LocalPlayer.Head.transform.up);
				Refresh(isAttached: true);
				base.transform.SetParent(tool.transform);
			}
		}

		private void Update()
		{
			if (tool != null)
			{
				canvas.transform.rotation = Quaternion.LookRotation(Player.LocalPlayer.Head.transform.forward, Player.LocalPlayer.Head.transform.up);
			}
		}

		private void OnDestroy()
		{
			if (tool != null)
			{
				tool.RigidbodyPickup.ReachedTargetEvent -= RigidbodyPickup_ReachedTargetEvent;
			}
		}
	}
}
