namespace RecRoom.Core.Combat
{
	public struct Combatant
	{
		private static readonly Vector3 SCREEN_MODE_HEAD_OFFSET = new Vector3(0f, -0.33f, 0f);

		public readonly Player Player;

		public readonly Enemy Enemy;

		public readonly int ID;

		private readonly bool isPlayer;

		private int lastHeadPositionUpdateFrame;

		private Vector3 cachedHeadPosition;

		private int lastFloorPositionUpdateFrame;

		private Vector3 cachedFloorPosition;

		private int lastVelocityUpdateFrame;

		private Vector3 cachedVelocity;

		public static readonly Combatant Invalid = new Combatant(null, null);

		public bool IsValid => (isPlayer && Player != null) || Enemy != null;

		public Vector3 HeadPosition
		{
			get
			{
				if (lastHeadPositionUpdateFrame != UnityEngine.Time.frameCount)
				{
					lastHeadPositionUpdateFrame = UnityEngine.Time.frameCount;
					if (isPlayer && Player != null)
					{
						cachedHeadPosition = Player.Head.RigidbodyEx.targetPosition;
						if (Player.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN)
						{
							cachedHeadPosition += SCREEN_MODE_HEAD_OFFSET;
						}
					}
					else if (Enemy != null)
					{
						cachedHeadPosition = Enemy.transform.position;
					}
				}
				return cachedHeadPosition;
			}
		}

		public Vector3 FloorPosition
		{
			get
			{
				if (lastFloorPositionUpdateFrame != UnityEngine.Time.frameCount)
				{
					lastFloorPositionUpdateFrame = UnityEngine.Time.frameCount;
					if (isPlayer && Player != null)
					{
						cachedFloorPosition = Player.CurrentFloorPosition;
					}
					else if (Enemy != null)
					{
						cachedFloorPosition = Enemy.Steering.SurfacePosition;
					}
				}
				return cachedFloorPosition;
			}
		}

		public Vector3 Velocity
		{
			get
			{
				if (lastVelocityUpdateFrame != UnityEngine.Time.frameCount)
				{
					lastVelocityUpdateFrame = UnityEngine.Time.frameCount;
					if (isPlayer && Player != null)
					{
						cachedVelocity = Player.TrackingSpace.RigidbodyEx.velocity;
					}
					else if (Enemy != null)
					{
						cachedVelocity = Enemy.RigidbodyEx.velocity;
					}
				}
				return cachedVelocity;
			}
		}

		public bool IsLocal => Player != null && Player.isLocal;

		public bool HasAuthority => (Player != null && Player.hasAuthority) || (Enemy != null && Enemy.hasAuthority);

		public Combatant(int photonViewId)
			: this(PhotonView.Find(photonViewId))
		{
		}

		public Combatant(PhotonView photonView)
			: this(GetPlayerFromPhotonView(photonView), GetEnemyFromPhotonView(photonView))
		{
		}

		public Combatant(PhotonPlayer photonPlayer)
			: this(photonPlayer?.ToPlayer(), null)
		{
		}

		public Combatant(Player player)
			: this(player, null)
		{
		}

		public Combatant(Enemy enemy)
			: this(null, enemy)
		{
		}

		private Combatant(Player player, Enemy enemy)
		{
			Player = player;
			isPlayer = Player != null;
			Enemy = enemy;
			if (Player != null)
			{
				ID = Player.photonView.viewID;
			}
			else if (Enemy != null)
			{
				ID = Enemy.photonView.viewID;
			}
			else
			{
				ID = -1;
			}
			lastHeadPositionUpdateFrame = -1;
			cachedHeadPosition = Vector3.zero;
			lastFloorPositionUpdateFrame = -1;
			cachedFloorPosition = Vector3.zero;
			lastVelocityUpdateFrame = -1;
			cachedVelocity = Vector3.zero;
		}

		public Vector3 GetExtrapolatedHeadPosition(Vector3 projectileOrigin, float projectileSpeed)
		{
			Vector3 headPosition = HeadPosition;
			Vector3 velocity = Velocity;
			float extrapolatedTargetTime = GetExtrapolatedTargetTime(projectileOrigin, projectileSpeed, headPosition, velocity);
			return headPosition + velocity * extrapolatedTargetTime;
		}

		public override bool Equals(object obj)
		{
			Combatant combatant = (Combatant)obj;
			return object.Equals(Player, combatant.Player) && object.Equals(Enemy, combatant.Enemy);
		}

		public override int GetHashCode()
		{
			return base.GetHashCode();
		}

		private float GetExtrapolatedTargetTime(Vector3 projectileOrigin, float projectileSpeed, Vector3 targetPosition, Vector3 targetVelocity)
		{
			float magnitude = targetVelocity.magnitude;
			Vector3 rhs = ((!(magnitude > 0f)) ? targetVelocity : (targetVelocity / magnitude));
			Vector3 vector = projectileOrigin - targetPosition;
			float magnitude2 = vector.magnitude;
			Vector3 lhs = ((!(magnitude2 > 0f)) ? vector : (vector / magnitude2));
			float num = Vector3.Dot(lhs, rhs);
			float num2 = projectileSpeed * projectileSpeed - magnitude * magnitude;
			float num3 = 2f * magnitude2 * magnitude * num;
			float num4 = -1f * (magnitude2 * magnitude2);
			float num5 = Mathf.Sqrt(num3 * num3 - 4f * num2 * num4);
			float num6 = 2f * num2;
			float num7 = (0f - num3 + num5) / num6;
			float num8 = (0f - num3 - num5) / num6;
			if (num7 > 0f && num8 > 0f)
			{
				return Mathf.Min(num7, num8);
			}
			if (num7 > 0f)
			{
				return num7;
			}
			if (num8 > 0f)
			{
				return num8;
			}
			return 0f;
		}

		public static bool operator ==(Combatant lhs, Combatant rhs)
		{
			return lhs.Equals(rhs);
		}

		public static bool operator !=(Combatant lhs, Combatant rhs)
		{
			return !lhs.Equals(rhs);
		}

		private static Player GetPlayerFromPhotonView(PhotonView photonView)
		{
			return (!(photonView != null)) ? null : photonView.GetComponent<Player>();
		}

		private static Enemy GetEnemyFromPhotonView(PhotonView photonView)
		{
			return (!(photonView != null)) ? null : photonView.GetComponent<Enemy>();
		}
	}
}
