		public bool IsDisengaged => stateMachine.CurrentStateId == 5;

		public bool IsStunned => stateMachine.CurrentStateId == 4 || (stateMachine.CurrentStateId == 3 && stateMachine.CurrentSubStateId == 1);

		public bool IsAggrod => IsAggroState((EnemyStates)stateMachine.CurrentStateId);

		public virtual bool CanAggroEnemies => true;

		public virtual int CustomEncounterValue => 0;

		public Combatant LastAttacker
		{
			get
			{
				int revision = _lastAttackerId.Revision;
				if (cachedLastAttackerRevision != revision)
				{
					cachedLastAttackerRevision = revision;
					cachedLastAttacker = new Combatant(_lastAttackerId.Get());
				}
				return cachedLastAttacker;
			}
			protected set
			{
				_lastAttackerId.Set(value.ID);
			}
		}

		public Weapon LastAttackerWeapon
		{
			get
			{
				int revision = _lastAttackerWeaponId.Revision;
				if (cachedLastAttackerWeaponRevision != revision)
				{
					cachedLastAttackerWeaponRevision = revision;
					PhotonView photonView = PhotonView.Find(_lastAttackerWeaponId.Get());
					cachedLastAttackerWeapon = ((!(photonView != null)) ? null : photonView.GetComponent<Weapon>());
				}
				return cachedLastAttackerWeapon;
			}
			set
			{
				_lastAttackerWeaponId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private bool MeleeCombatAllowed
		{
			get
			{
				return _meleeCombatAllowed;
			}
			set
			{
				_meleeCombatAllowed = value;
				UpdateMeleeCombat();
			}
		}

		protected bool MeleeCombatActive
		{
			get
			{
				return _meleeCombatActive;
			}
			set
			{
				_meleeCombatActive = value;
				UpdateMeleeCombat();
			}
		}

		protected Combatant Target
		{
			get
			{
				int revision = _targetId.Revision;
				if (cachedTargetRevision != revision)
				{
					cachedTargetRevision = revision;
					cachedTarget = new Combatant(_targetId.Get());
				}
				return cachedTarget;
			}
			set
			{
				if (trackTargetCount && base.hasAuthority)
				{
					SingletonMonoBehaviour<EnemyManager>.Instance.AuthorityAddEnemyTargetCount(this, Target, -1);
				}
				_targetId.Set(value.ID);
				if (trackTargetCount && base.hasAuthority)
				{
					SingletonMonoBehaviour<EnemyManager>.Instance.AuthorityAddEnemyTargetCount(this, Target, 1);
				}
			}
		}

		protected bool CollidersEnabled
		{
			get
			{
				return Colliders != null && Colliders.Length > 0 && Colliders[0].enabled;
			}
			set
			{
				if (Colliders != null)
				{
					EnemyCollider[] colliders = Colliders;
					foreach (EnemyCollider enemyCollider in colliders)
					{
						enemyCollider.enabled = value;
					}
				}
			}
		}

		public Transform ObjectSpawnOrigin
		{
			get
			{
				if (lineOfSightOrigin != null)
				{
					return lineOfSightOrigin;
				}
				return base.transform;
			}
		}

		public bool IsVisible
		{
			get
			{
				if (!VisualsEnabled)
				{
					return false;
				}
				return visibleInCamera.IsVisible;
			}
		}

		protected bool VisualsEnabled
		{
			get
			{
				return renderers != null && renderers.Length > 0 && renderers[0].gameObject.activeSelf;
			}
			set
			{
				if (renderers != null && renderers.Length > 0)
				{
					Renderer[] array = renderers;
					foreach (Renderer renderer in array)
					{
						renderer.gameObject.SetActive(value);
					}
				}
			}
		}

		public bool IsHighLOD
		{
			get
			{
				return _isHighLOD;
			}
			set
			{
				if (_isHighLOD != value)
				{
					_isHighLOD = value;
					if (this.LODChangedEvent != null)
					{
						this.LODChangedEvent(this);
					}
				}
			}
		}

		public bool IsValidPointOfInterest => IsAlive && Health > 0 && !IsSpawning;

		public bool IsHighPriorityPointOfInterest => false;

		public Vector3 PointOfInterestPosition
		{
			get
			{
				if (screensPointOfInterestTransform != null)
				{
					return screensPointOfInterestTransform.position;
				}
				return GetColliderBounds().center;
			}
		}

		public Vector3 PointOfInterestForwardDirection => base.transform.forward;

		public Vector3 PointOfInterestLabelPosition => HealthBarRoot.position + HealthBarOffset;

