				EnemyAction enemyAction2;
				do
				{
					enemyAction2 = enemyAction;
					enemyAction = Interlocked.CompareExchange(ref Enemy.m_EnemyInstantiatedEvent, (EnemyAction)Delegate.Combine(enemyAction2, value), enemyAction);
				}
				while (enemyAction != enemyAction2);
			}
			remove
			{
				EnemyAction enemyAction = Enemy.m_EnemyInstantiatedEvent;
