					enemyAction = Interlocked.CompareExchange(ref this.m_StunEndEvent, (EnemyAction)Delegate.Remove(enemyAction2, value), enemyAction);
				}
				while (enemyAction != enemyAction2);
			}
		}

		public event EnemyAction LODChangedEvent
		{
			add
			{
				EnemyAction enemyAction = this.m_LODChangedEvent;
				EnemyAction enemyAction2;
				do
				{
					enemyAction2 = enemyAction;
					enemyAction = Interlocked.CompareExchange(ref this.m_LODChangedEvent, (EnemyAction)Delegate.Combine(enemyAction2, value), enemyAction);
				}
				while (enemyAction != enemyAction2);
			}
			remove
			{
				EnemyAction enemyAction = this.m_LODChangedEvent;
				EnemyAction enemyAction2;
				do
				{
					enemyAction2 = enemyAction;
					enemyAction = Interlocked.CompareExchange(ref this.m_LODChangedEvent, (EnemyAction)Delegate.Remove(enemyAction2, value), enemyAction);
				}
				while (enemyAction != enemyAction2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
			if (EnemyRoot != null && base.transform.parent != EnemyRoot)
			{
				base.transform.SetParent(EnemyRoot, worldPositionStays: true);
			}
			if (SingletonMonoBehaviour<EnemyManager>.Instance != null)
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.RegisterEnemy(this);
			}
			accessories = GetComponentsInChildren<QuestEnemyArticulatingAccessory>();
			Colliders = GetComponentsInChildren<EnemyCollider>(includeInactive: true);
			meleeColliders = GetComponentsInChildren<MeleeWeaponCollider>();
			ragdollBodyParts = GetComponentsInChildren<RagdollPiece>();
			renderers = GetComponentsInChildren<Renderer>(includeInactive: true);
			damageInstancesReceived = new List<PhotonPlayer>();
			EnemyCollider[] colliders = Colliders;
			foreach (EnemyCollider enemyCollider in colliders)
			{
				enemyCollider.ThisEnemy = this;
			}
			CollidersEnabled = true;
			RigidbodyEx.AddKinematic(this);
			RigidbodyEx.ClearVelocity();
			InstantiationPosition = base.transform.position;
			lastTimeOnNavMesh = UnityEngine.Time.time;
			for (int j = 0; j < meleeColliders.Length; j++)
			{
				meleeColliders[j].SupportsStationaryCollisionTests = true;
				meleeColliders[j].AddIgnoredRigidbody(RigidbodyEx.UnityRigidbody);
				meleeColliders[j].ToolImpactEvent += OnMeleeColliderToolImpact;
				meleeColliders[j].PlayerImpactEvent += OnMeleeColliderPlayerImpact;
			}
			if (rangedWeapon != null)
			{
				rangedWeapon.PlayerHitEvent += OnRangedWeaponPlayerHit;
				rangedWeapon.PlayerToolHitEvent += OnRangedWeaponPlayerToolHit;
				rangedWeapon.EnemyHitEvent += OnRangedWeaponEnemyHit;
				rangedWeapon.LocalPreFireEvent += OnRangedWeaponLocalFire;
			}
			Weapon.PostImpactEventStatic += OnWeaponAggroImpact;
			MeleeCombatAllowed = true;
			MeleeCombatActive = false;
			_health = new SynchronizedField<int>(this, "HP", maxHealth, SetterPermissionMode.AUTHORITY, OnHealthChanged);
			_isAlive = new SynchronizedField<bool>(this, "ALIVE", defaultValue: true, SetterPermissionMode.AUTHORITY, OnIsAliveChanged);
			_lastAttackerId = new SynchronizedField<int>(this, "LAID", -1, SetterPermissionMode.AUTHORITY);
			_lastAttackerWeaponId = new SynchronizedField<int>(this, "LAWID", -1, SetterPermissionMode.AUTHORITY);
			_targetId = new SynchronizedField<int>(this, "ETID", -1, SetterPermissionMode.AUTHORITY, OnTargetChange);
			_animationIsMoving = new SynchronizedField<bool>(this, "AIM", defaultValue: false, SetterPermissionMode.AUTHORITY, OnAnimationIsMovingChange);
			_currentPatrolTarget = new SynchronizedField<int, Vector3>(this, "PT", -1, SpawnTargetPosition, SetterPermissionMode.AUTHORITY);
			stateTimer = new SynchronizedTimer(this, "LC", SetterPermissionMode.AUTHORITY);
			stateMachine = new SynchronizedStateMachine("LC", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterSpawningState, OnExitSpawningState, OnUpdateSpawningState);
			stateMachine.AddState(2, OnEnterPatrolState, OnExitPatrolState, OnUpdatePatrolState);
			stateMachine.AddState(5, OnEnterDisengagedState, OnExitDisengagedState, OnUpdateDisengagedState);
			stateMachine.AddState(6, OnEnterDeadState, OnExitDeadState, OnUpdateDeadState);
			stateMachine.AddState(3, OnEnterCombatState, OnExitCombatState, OnUpdateCombatState);
			stateMachine.AddState(3, 0, OnEnterCombatActiveSubState, OnExitCombatActiveSubState, OnUpdateCombatActiveSubState);
			stateMachine.AddState(3, 1, OnEnterCombatStunSubState, OnExitCombatStunSubState, OnUpdateCombatStunSubState);
			stateMachine.AddState(4, null, null, null);
			stateMachine.AddState(4, 0, OnEnterInterruptedStunSubState, OnExitInterruptedStunSubState, OnUpdateInterruptedStunSubState);
			stateMachine.AddState(4, 1, OnEnterInterruptedRecoverySubState, OnExitInterruptedRecoverySubState, OnUpdateInterruptedRecoverySubState);
			wasRuntimeInstantiated = base.photonView.instantiationData != null && base.photonView.instantiationData.Length == 9;
			if (wasRuntimeInstantiated)
			{
				InstantiatorPhotonViewId = (int)base.photonView.instantiationData[0];
				InstantiationParameters = (Dictionary<string, object>)base.photonView.instantiationData[1];
				SpawnTargetPosition = (Vector3)base.photonView.instantiationData[3];
				EnemyType = (EnemyType)base.photonView.instantiationData[2];
				SpawnOnPatrol = (bool)base.photonView.instantiationData[4];
				Team = (GameTeam)base.photonView.instantiationData[6];
				PhotonView photonView = PhotonView.Find((int)base.photonView.instantiationData[5]);
				Patrol = ((!(photonView != null)) ? null : photonView.GetComponent<EnemyPatrol>());
				SpawnDisengaged = (bool)base.photonView.instantiationData[7];
				UniqueRandomValue = (float)base.photonView.instantiationData[8];
			}
			else
			{
				InstantiatorPhotonViewId = -1;
				InstantiationParameters = null;
				SpawnTargetPosition = base.transform.position;
				SpawnOnPatrol = true;
				EnemyType = EnemyType.INVALID;
				Patrol = null;
				Team = GameTeam.ANY;
				SpawnDisengaged = false;
				UniqueRandomValue = UnityEngine.Random.value;
			}
			if (InstantiationParameters != null && PointsDropper != null && InstantiationParameters.TryGetValue(BaseSpawnEnemyEncounterStep.ENCOUNTER_SUPPRESS_REWARDS_KEY, out var value) && (bool)value)
			{
				PointsDropper.enabled = false;
			}
		}

		protected virtual void Start()
		{
			if (wasRuntimeInstantiated && Enemy.EnemyInstantiatedEvent != null)
			{
				Enemy.EnemyInstantiatedEvent(this);
			}
			OnAnimationIsMovingChange();
			RigidbodyEx.constraints = RigidbodyConstraints.FreezeRotation;
			Steering.MovementSpeedVarietyScalar = Mathf.Lerp(0.8f, 1.2f, UniqueRandomValue);
			if (Steering.IsHovering)
			{
				Steering.SetDesiredHoverHeight("Enemy", Steering.DesiredHoverHeight + Mathf.Lerp(0.5f, -0.5f, UniqueRandomValue));
			}
			initialized = true;
			stateMachine.Start(this, 1);
			OnIsAliveChanged();
		}

		private void OnSpawn()
		{
			if (Enemy.EnemySpawnEvent != null)
			{
				Enemy.EnemySpawnEvent(this);
			}
		}

		private void OnHealthChanged()
		{
			if (Enemy.EnemyHealthChangeEvent != null)
			{
				Enemy.EnemyHealthChangeEvent(this, Health, maxHealth, base.authority);
			}
			if (base.hasAuthority && initialized && Health <= 0 && stateMachine.CurrentStateId != 6)
			{
				stateMachine.EnterState(6);
			}
		}

		private void OnIsAliveChanged()
		{
			if (IsAlive)
			{
				OnSpawn();
			}
			if (!IsAlive)
			{
				OnCleanup();
			}
		}

		protected override void OnDestroy()
		{
			if (!hasRunOnDeath)
			{
				OnDeath();
			}
			base.OnDestroy();
			if (SingletonMonoBehaviour<EnemyManager>.Instance != null)
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.UnregisterEnemy(this);
			}
			Weapon.PostImpactEventStatic -= OnWeaponAggroImpact;
			if (ragdollBodyParts != null)
			{
				RagdollPiece[] array = ragdollBodyParts;
				foreach (RagdollPiece ragdollPiece in array)
				{
					ragdollPiece.StopRagdoll();
				}
			}
			if (meleeColliders != null)
			{
				for (int j = 0; j < meleeColliders.Length; j++)
				{
					meleeColliders[j].ToolImpactEvent -= OnMeleeColliderToolImpact;
					meleeColliders[j].PlayerImpactEvent -= OnMeleeColliderPlayerImpact;
				}
			}
			if (rangedWeapon != null)
			{
				rangedWeapon.PlayerHitEvent -= OnRangedWeaponPlayerHit;
				rangedWeapon.PlayerToolHitEvent -= OnRangedWeaponPlayerToolHit;
				rangedWeapon.EnemyHitEvent -= OnRangedWeaponEnemyHit;
				rangedWeapon.LocalPreFireEvent -= OnRangedWeaponLocalFire;
			}
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		private void OnCleanup()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					TransferOwnership(PhotonNetwork.masterClient);
				}
				PhotonNetwork.Destroy(base.photonView);
			}
		}

		protected virtual void Update()
		{
			AuthorityUpdateAnimationIsMoving();
			if (cachesLatestVisibleTargetPosition && UnityEngine.Time.time - lastTargetPositionUpdateTime >= 0.1f)
			{
				lastTargetPositionUpdateTime = UnityEngine.Time.time;
				UpdateLatestTargetPosition(testLineOfSight: true);
			}
			stateMachine.Update();
			stateTimer.UpdateCallbacks();
			DetectStuckEnemy();
		}

		public virtual void LowLODUpdate()
		{
			enemyAnimator.LowPriorityUpdate();
		}

		protected void UpdateTargetCentroidPath(float slowdownDistance)
		{
			Vector3 targetCentroid = GetTargetCentroid();
			if (!Steering.PathIsValid(targetCentroid))
			{
				Steering.Path(targetCentroid, slowdownDistance);
			}
		}

		public static bool TrySampleNavMesh(Vector3 desiredPosition, out Vector3 closestNavMeshPostion)
		{
			if (NavMesh.SamplePosition(desiredPosition, out var hit, float.MaxValue, -1))
			{
				closestNavMeshPostion = hit.position;
				return true;
			}
			closestNavMeshPostion = desiredPosition;
			return false;
		}

		protected virtual void DetectStuckEnemy()
		{
			if (base.hasAuthority && IsAlive && mustBeOnNavMesh)
			{
				if (NavMesh.SamplePosition(Steering.SurfacePosition, out var _, stuckDistanceFromNavMesh, -1))
				{
					lastTimeOnNavMesh = UnityEngine.Time.time;
				}
				else if (UnityEngine.Time.time - lastTimeOnNavMesh > stuckSecondsUntilAutoKill)
				{
					UnityEngine.Debug.LogWarning(base.name + " was auto killed. ");
					AuthorityTryApplyAttack(PhotonNetwork.player, null, WeaponDamageType.DEFAULT, EnemyArmorType.NORMAL, 999999, WeaponImpact.Default);
					AuthorityTryApplyAttack(PhotonNetwork.player, null, WeaponDamageType.SELF_ATTACK, EnemyArmorType.NORMAL, 999999, WeaponImpact.Default);
				}
			}
		}

		public bool AuthorityTryApplyAttack(PhotonPlayer attackingPlayer, Weapon weapon, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			return AuthorityTryApplyAttackInternal(new Combatant(attackingPlayer), weapon, damageType, armorType, damage, impact);
		}

		public bool AuthorityTryApplyAttack(Enemy attackingEnemy, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			return AuthorityTryApplyAttackInternal(new Combatant(attackingEnemy), null, damageType, armorType, damage, impact);
		}

		protected virtual bool AuthorityTryApplyAttackInternal(Combatant attacker, Weapon weapon, WeaponDamageType damageType, EnemyArmorType armorType, int damage, WeaponImpact impact)
		{
			if (base.hasAuthority && Health > 0 && initialized && !IsDisengaged && SingletonMonoBehaviour<EnemyManager>.Instance.IsValidAttack(this, attacker))
			{
				damage = GetDamageCombatSettings(damage, damageType, armorType);
				if (damage > 0)
				{
					bool arg = Health <= damage;
					base.photonView.RpcAll(RpcOnTookDamage, attacker, damageType, armorType, damage, arg, impact.Point, impact.SurfaceNormal);
					LastAttacker = attacker;
					LastAttackerWeapon = weapon;
					Health -= damage;
				}
				AuthorityStun(damageType, armorType);
				return true;
			}
			return false;
		}

		public virtual void AuthorityStun(WeaponDamageType damageType, EnemyArmorType armorType)
		{
			if (!base.hasAuthority)
			{
				return;
			}
			GetStunCombatSettings(damageType, armorType, out var interrupt, out var stunDuration);
			EnemyStates currentStateId = (EnemyStates)stateMachine.CurrentStateId;
			if (!IsAlive || Health <= 0 || currentStateId == EnemyStates.DEAD || !(stunDuration >= Mathf.Epsilon))
			{
				return;
			}
			if ((!interrupt || !InInterruptionStunState()) && (interrupt || !InCombatStunState()))
			{
				stateTimer.StartTimer(stunDuration);
				if (interrupt)
				{
					stateMachine.EnterState(4, 0);
				}
				else
				{
					stateMachine.EnterState(3, 1);
				}
			}
			else if (stateTimer.TimeRemaining < stunDuration)
			{
				stateTimer.StartTimer(stunDuration);
			}
		}

		public virtual void AuthorityOnDamageApplyForce(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 force, Vector3 point)
		{
			if (base.hasAuthority)
			{
				float recoilForceMultiplier = GetRecoilForceMultiplier(damageType, armorType);
				RigidbodyEx.AddForceAtPosition(force * recoilForceMultiplier, point, ForceMode.Impulse);
				if (shatterType != ShatterType.NONE && shatterType != ShatterType.PHYSICS_ON_COLLISION)
				{
					Vector3 vector = force * recoilForceMultiplier / RigidbodyEx.mass;
					AuthorityShatter(RigidbodyEx.velocity + vector, armorType);
				}
			}
		}

		public virtual void AuthorityClearVelocity()
		{
			if (base.hasAuthority)
			{
				RigidbodyEx.ClearVelocity();
			}
		}

		public virtual void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, EnemyArmorType armorType, Vector3 velocity, Vector3 angularVelocity)
		{
			if (base.hasAuthority)
			{
				float recoilForceMultiplier = GetRecoilForceMultiplier(damageType, armorType);
				RigidbodyEx.velocity = velocity * recoilForceMultiplier;
				RigidbodyEx.angularVelocity = angularVelocity * recoilForceMultiplier;
				if (shatterType != ShatterType.NONE && shatterType != ShatterType.PHYSICS_ON_COLLISION)
				{
					AuthorityShatter(RigidbodyEx.velocity, armorType);
				}
			}
		}

		public int GetPlayerAttackDamage(Player.BodyPart impactBodyPart)
		{
			int result = 100;
			if (playerDamageSettings != null)
			{
				for (int i = 0; i < playerDamageSettings.Length; i++)
				{
					if (playerDamageSettings[i].BodyPart == impactBodyPart)
					{
						result = playerDamageSettings[i].Damage;
						break;
					}
				}
			}
			return result;
		}

		protected void AuthorityFireRangedWeaponAtTarget(bool canFireAtLastVisiblePosition, float animationShotDelay = 0f)
		{
			if (rangedWeapon != null)
			{
				if (canFireAtLastVisiblePosition && !cachesLatestVisibleTargetPosition)
				{
					canFireAtLastVisiblePosition = false;
					UnityEngine.Debug.LogError("Enemy " + base.name + " is misconfigured.  It is trying to use latest visible target position but is not configured to calculate it.");
				}
				if (Target.IsValid && (hasTargetLineOfSight || !canFireAtLastVisiblePosition))
				{
					EnemyRangedWeapon enemyRangedWeapon = rangedWeapon;
					Combatant target = Target;
					float shotDelay = animationShotDelay;
					enemyRangedWeapon.AuthorityFire(target, -1f, shotDelay);
				}
				else if (canFireAtLastVisiblePosition)
				{
					EnemyRangedWeapon enemyRangedWeapon2 = rangedWeapon;
					Vector3 target2 = latestVisibleTargetHeadPosition;
					float shotDelay = animationShotDelay;
					enemyRangedWeapon2.AuthorityFire(target2, -1f, shotDelay);
				}
			}
		}

		protected void AuthorityFireRangedWeaponAtTargetFloor(bool canFireAtLastVisiblePosition, float animationShotDelay = 0f)
		{
			if (rangedWeapon != null)
			{
				if (Target.IsValid && (hasTargetLineOfSight || !canFireAtLastVisiblePosition))
				{
					EnemyRangedWeapon enemyRangedWeapon = rangedWeapon;
					Vector3 floorPosition = Target.FloorPosition;
					float shotDelay = animationShotDelay;
					enemyRangedWeapon.AuthorityFire(floorPosition, -1f, shotDelay);
				}
				else if (canFireAtLastVisiblePosition)
				{
					EnemyRangedWeapon enemyRangedWeapon2 = rangedWeapon;
					Vector3 floorPosition = latestVisibleTargetFloorPosition;
					float shotDelay = animationShotDelay;
					enemyRangedWeapon2.AuthorityFire(floorPosition, -1f, shotDelay);
				}
			}
		}

		protected void AuthorityFireRangedWeaponAtExplicitTargetPosition(Vector3 targetPosition, float animationShotDelay = 0f)
		{
			if (rangedWeapon != null)
			{
				rangedWeapon.AuthorityFire(targetPosition, -1f, animationShotDelay);
			}
		}

		private void UpdateMeleeCombat()
		{
			if (meleeColliders != null)
			{
				MeleeWeaponCollider[] array = meleeColliders;
				foreach (MeleeWeaponCollider meleeWeaponCollider in array)
				{
					meleeWeaponCollider.enabled = MeleeCombatActive && MeleeCombatAllowed;
				}
			}
		}

		protected virtual void OnTookDamage(Combatant attacker, WeaponDamageType damageType, EnemyArmorType armorType, int damage, bool killingBlow, Vector3 hitPoint, Vector3 hitNormal)
		{
			if (Enemy.TookDamageEvent != null && !killingBlow)
			{
				Enemy.TookDamageEvent(attacker, this, hitPoint);
			}
			if (enemyParticles != null)
			{
				enemyParticles.OnTakeDamage(armorType, hitPoint, hitNormal);
				if (killingBlow)
				{
					enemyParticles.OnKill(armorType, hitPoint, hitNormal);
				}
			}
			enemyAudio.OnTakeDamage(armorType, hitPoint, attacker.IsLocal);
			if (killingBlow)
			{
				enemyAudio.OnKill(armorType, hitPoint, attacker.IsLocal);
			}
			if (damage > 0 && attacker.Player != null && !damageInstancesReceived.Contains(attacker.Player.PhotonPlayer))
			{
				damageInstancesReceived.Add(attacker.Player.PhotonPlayer);
			}
		}

		protected virtual void OnPlayerToolImpact(Enemy enemy, Tool hitTool, WeaponImpact impact)
		{
			Weapon weapon = ((!(hitTool != null)) ? null : hitTool.GetComponent<Weapon>());
			if (weapon != null && weapon.hasAuthority)
			{
				weapon.AuthorityOnEnemyApplyAttack(enemy, impact);
			}
		}

		protected virtual void OnPlayerImpact(Enemy enemy, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestEnemyOnPlayerDamage(enemy, hitPlayer, hitBodyPart, impact.Point);
			}
		}

		protected void OnEnemyImpact(Enemy enemy, Enemy hitEnemy, EnemyArmorType hitArmorType, WeaponImpact impact)
		{
			if (base.hasAuthority)
			{
				if (hitEnemy == this)
				{
					AuthorityTryApplyAttack(base.authority, null, WeaponDamageType.SELF_ATTACK, hitArmorType, 100, impact);
					AuthorityOnDamageApplyForce(WeaponDamageType.SELF_ATTACK, hitArmorType, impact.Force, impact.Point);
				}
				else if (!SingletonMonoBehaviour<EnemyManager>.Instance.IsAlly(Team, hitEnemy))
				{
					hitEnemy.AuthorityTryApplyAttack(this, WeaponDamageType.ENEMY_WEAPON, hitArmorType, enemyDamage, impact);
					hitEnemy.AuthorityOnDamageApplyForce(WeaponDamageType.ENEMY_WEAPON, hitArmorType, impact.Force, impact.Point);
				}
			}
		}

		private void OnMeleeColliderPlayerImpact(MeleeWeaponCollider collider, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (Health > 0 && IsAlive)
			{
				if (!base.hasAuthority && hitPlayer.isLocal)
				{
					TransferOwnership(PhotonNetwork.player);
				}
				OnPlayerImpact(this, hitPlayer, hitBodyPart, impact);
			}
		}

		private void OnMeleeColliderToolImpact(MeleeWeaponCollider collider, Tool hitTool, WeaponImpact impact)
		{
			if (Health > 0 && IsAlive && hitTool.IsHeld)
			{
				if (!base.hasAuthority && hitTool.hasAuthority)
				{
					TransferOwnership(PhotonNetwork.player);
				}
				OnPlayerToolImpact(this, hitTool, impact);
			}
		}

		protected void OnRangedWeaponPlayerHit(EnemyRangedWeapon weapon, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (Health > 0 && IsAlive)
			{
				OnPlayerImpact(this, hitPlayer, hitBodyPart, impact);
			}
		}

		protected void OnRangedWeaponPlayerToolHit(EnemyRangedWeapon weapon, Tool hitTool, WeaponImpact impact)
		{
			if (Health > 0 && IsAlive)
			{
				OnPlayerToolImpact(this, hitTool, impact);
			}
		}

		protected void OnRangedWeaponEnemyHit(EnemyRangedWeapon weapon, Enemy hitEnemy, EnemyArmorType hitArmorType, WeaponImpact impact)
		{
			if (Health > 0 && IsAlive)
			{
				OnEnemyImpact(this, hitEnemy, hitArmorType, impact);
			}
		}

		protected virtual void OnRangedWeaponLocalFire(EnemyRangedWeapon weapon, float shotDelay)
		{
			enemyAnimator.PlayRangedAttack();
		}

		protected void GetStunCombatSettings(WeaponDamageType damageType, EnemyArmorType armorType, out bool interrupt, out float stunDuration)
		{
			interrupt = false;
			stunDuration = 0f;
			if (damageType == WeaponDamageType.NON_COMBAT_COLLISION)
			{
				interrupt = false;
				stunDuration = 0.4f;
				return;
			}
			CombatSettings combatSettings = GetCombatSettings(damageType);
			if (combatSettings != null)
			{
				if (IsCriticalHit(armorType))
				{
					interrupt = combatSettings.CriticalHitInterruptsBehavior;
					stunDuration = combatSettings.CriticalHitStunDuration;
				}
				else if (IsShield(armorType))
				{
					interrupt = combatSettings.ShieldHitInterruptsBehavior;
					stunDuration = combatSettings.ShieldHitStunDuration;
				}
				else
				{
					interrupt = combatSettings.InterruptsBehavior;
					stunDuration = combatSettings.StunDuration;
				}
			}
		}

		public int GetDamageCombatSettings(int damage, WeaponDamageType damageType, EnemyArmorType armorType)
		{
			if (damageType == WeaponDamageType.NON_COMBAT_COLLISION)
			{
				return 0;
			}
			float num = 1f;
			CombatSettings combatSettings = GetCombatSettings(damageType);
			if (combatSettings != null)
			{
				num = (IsCriticalHit(armorType) ? combatSettings.CriticalHitDamageMultiplier : ((!IsShield(armorType)) ? combatSettings.DamageMultiplier : combatSettings.ShieldHitDamageMultiplier));
			}
			return Mathf.RoundToInt((float)damage * num);
		}

		protected float GetRecoilForceMultiplier(WeaponDamageType damageType, EnemyArmorType armorType)
		{
			if (damageType == WeaponDamageType.NON_COMBAT_COLLISION)
			{
				return 1f;
			}
			CombatSettings combatSettings = GetCombatSettings(damageType);
			if (combatSettings == null)
			{
				return 1f;
			}
			bool flag = Health <= 0;
			if (IsCriticalHit(armorType))
			{
				return (!flag) ? combatSettings.CriticalHitRecoilMultiplier : combatSettings.KillingBlowCriticalHitRecoilMultiplier;
			}
			if (IsShield(armorType))
			{
				return combatSettings.ShieldHitRecoilMultiplier;
			}
			return (!flag) ? combatSettings.RecoilMultiplier : combatSettings.KillingBlowRecoilMultiplier;
		}

		private CombatSettings GetCombatSettings(WeaponDamageType damageType)
		{
			CombatSettings result = null;
			CombatSettings[] array = this.combatSettings;
			foreach (CombatSettings combatSettings in array)
			{
				if (combatSettings.DamageType == WeaponDamageType.DEFAULT)
				{
					result = combatSettings;
				}
				else if (combatSettings.DamageType == damageType)
				{
					result = combatSettings;
					break;
				}
			}
			return result;
		}

		private void OnTriggerEnter(Collider collider)
