		public bool HasLineOfSight(Vector3 targetPosition)
		{
			Vector3 vector = ((!(lineOfSightOrigin != null)) ? RigidbodyEx.physicsPosition : lineOfSightOrigin.position);
			Vector3 vector2 = targetPosition - vector;
			float distance;
			Vector3 hitPoint;
			Vector3 hitNormal;
			return !TryGetRaycastHitPoint(vector, vector2.normalized, vector2.magnitude, out distance, out hitPoint, out hitNormal);
		}

		public bool HasStraightPathToTarget(Vector3 targetPosition)
		{
			Vector3 vector = ((!(lineOfSightOrigin != null)) ? RigidbodyEx.physicsPosition : lineOfSightOrigin.position);
			Vector3 vector2 = targetPosition - vector;
			float magnitude = vector2.magnitude;
			Vector3 vector3 = vector2 / magnitude;
			float distance;
			Vector3 hitPoint;
			Vector3 hitNormal;
			if (volumetricLineOfSightVolume != null)
			{
				if (Physics.BoxCast(volumetricLineOfSightVolume.WorldSpaceCenter, volumetricLineOfSightVolume.WorldSpaceSize / 2f, vector3, volumetricLineOfSightVolume.transform.rotation, magnitude, 2048))
				{
					return false;
				}
			}
			else if (TryGetRaycastHitPoint(vector, vector3, magnitude, out distance, out hitPoint, out hitNormal))
			{
				return false;
			}
			int num = Mathf.FloorToInt(magnitude / 1f);
			Vector3 zero = Vector3.zero;
			for (int i = 1; i < num; i++)
			{
				zero = vector + (float)i * 1f * vector3;
				if (!TryGetRaycastHitPoint(zero, Vector3.down, float.MaxValue, out distance, out hitPoint, out hitNormal) || !TrySampleNavMesh(hitPoint, out hitNormal))
				{
					return false;
				}
			}
			return true;
		}

		public bool IsInVisionCone(Vector3 targetPosition, float visionAngle)
		{
			Vector3 vector = ((!(lineOfSightOrigin != null)) ? RigidbodyEx.physicsPosition : lineOfSightOrigin.position);
			Vector3 vector2 = targetPosition - vector;
			Vector3 vector3 = ((!(lineOfSightOrigin != null)) ? base.transform.forward : lineOfSightOrigin.forward);
			vector3 = Vector3.ProjectOnPlane(vector3, Vector3.up).normalized;
			Vector3 normalized = Vector3.ProjectOnPlane(vector2, Vector3.up).normalized;
			return Vector3.Angle(vector3, normalized) <= visionAngle;
		}

		private void OnCollisionEnter(Collision collision)
		{
			if (this.CollisionEnterEvent != null)
			{
				this.CollisionEnterEvent(this, collision);
			}
			if (stateMachine.CurrentStateId == 6 && shatterType == ShatterType.PHYSICS_ON_COLLISION)
			{
				AuthorityShatter(Vector3.zero, EnemyArmorType.NORMAL);
			}
		}

		public static bool TryGetRaycastHitPoint(Vector3 origin, Vector3 direction, float maxDistance, out float distance, out Vector3 hitPoint, out Vector3 hitNormal)
		{
			return TryGetRaycastHitPoint(origin, direction, maxDistance, 2048, out distance, out hitPoint, out hitNormal);
		}

		public static bool TryGetRaycastHitPoint(Vector3 origin, Vector3 direction, float maxDistance, int layerMask, out float distance, out Vector3 hitPoint, out Vector3 hitNormal)
		{
			bool result = false;
			if (Physics.Raycast(origin, direction, out var hitInfo, maxDistance, layerMask))
			{
				distance = hitInfo.distance;
				hitPoint = hitInfo.point;
				hitNormal = hitInfo.normal;
				result = true;
			}
			else
			{
				distance = maxDistance;
				hitPoint = origin + direction * maxDistance;
				hitNormal = Vector3.up;
			}
			return result;
		}

		private Bounds GetColliderBounds()
		{
			Bounds result = default(Bounds);
			bool flag = false;
			for (int i = 0; i < Colliders.Length; i++)
			{
				if (Colliders[i] != null)
				{
					if (!flag)
					{
						result = Colliders[i].Bounds;
						flag = true;
					}
					else
					{
						result.Encapsulate(Colliders[i].Bounds);
					}
				}
			}
			return result;
		}

		protected virtual void OnSpawningUpdate()
		{
		}

		private void OnEnterSpawningState(ushort previousStateId, ushort previousSubStateId)
		{
			RigidbodyEx.AddKinematic(this);
			float num = spawnDuration + UnityEngine.Random.Range(0f, 0.25f);
			float magnitude = (SpawnTargetPosition - base.transform.position).magnitude;
			Steering.MaxHorizontalSpeed = 1.25f * magnitude / num;
			Steering.MaxVerticalSpeed = Steering.MaxHorizontalSpeed;
			Steering.MaxVerticalSteeringForce = movementMaxForce;
			Steering.StopAll();
			Steering.GravityEnabled = false;
			if (this.SpawnStartEvent != null)
			{
				this.SpawnStartEvent(this);
			}
		}

		private void OnUpdateSpawningState()
		{
			OnSpawningUpdate();
			if (!base.hasAuthority)
			{
				return;
			}
			if (!Steering.IsSeeking)
			{
				Steering.Seek(SpawnTargetPosition, spawnSlowdownDistance, 0.2f, faceVelocity: false, separateHeightSeeking: false);
			}
			else if (Steering.ReachedMainSeekTarget)
			{
				RigidbodyEx.targetPosition = SpawnTargetPosition;
				RigidbodyEx.ClearVelocity();
				RigidbodyEx.ClearUnityRigidbodyVelocity();
				Steering.StopSeeking();
				if (SpawnDisengaged)
				{
					stateMachine.EnterState(5);
				}
				else if (SpawnOnPatrol)
				{
					stateMachine.EnterState(2);
				}
				else
				{
					stateMachine.EnterState(3, 0);
				}
			}
		}

		private void OnExitSpawningState(ushort nextStateId, ushort nextSubStateId)
		{
			RigidbodyEx.RemoveKinematic(this);
			Steering.MaxVerticalSpeed = movementSpeed;
			Steering.MaxVerticalSteeringForce = movementMaxForce;
			Steering.GravityEnabled = true;
			Steering.StopAll();
			if (nextStateId == 3)
			{
				enemyAudio.OnAggro();
			}
			if (this.SpawnEndEvent != null)
			{
				this.SpawnEndEvent(this);
			}
		}

