		protected bool CurrentTargetIsValidTarget()
		{
			return IsValidTarget(Target);
		}

		protected bool LastAttackerIsValidTarget()
		{
			return IsValidTarget(LastAttacker);
		}

		protected bool IsValidTarget(Combatant target)
		{
			return target.IsValid && SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(target) && !SingletonMonoBehaviour<EnemyManager>.Instance.IsAlly(Team, target);
		}

		private void OnWeaponAggroImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
		{
			if (stateMachine.CurrentStateId != 2 || !weapon.hasAuthority)
			{
				return;
			}
			float sqrMagnitude = (impact.Point - base.transform.position).sqrMagnitude;
			if (sqrMagnitude >= 36f)
			{
				return;
			}
			if (!base.hasAuthority)
			{
				TransferOwnership(weapon.owner);
			}
			if (base.hasAuthority)
			{
				if (!SingletonMonoBehaviour<EnemyManager>.Instance.IsAlly(Team, weapon.owner))
				{
					Target = new Combatant(weapon.owner);
				}
				stateMachine.EnterState(3, 0);
			}
		}

		private Combatant FindNearbyAggrodAlly()
		{
			if (supportsAggroChaining)
			{
				float num = UnityEngine.Time.time - lastNearbyEnemySearchTime;
				if (num >= 0.25f)
				{
					lastNearbyEnemySearchTime = UnityEngine.Time.time;
					lastNearbyAggrodAlly = SingletonMonoBehaviour<EnemyManager>.Instance.GetAggrodAllyInRadius(this, 6f);
				}
			}
			return lastNearbyAggrodAlly;
		}

		private bool IsAggroState(EnemyStates state)
		{
			return state == EnemyStates.COMBAT || state == EnemyStates.INTERRUPTED;
		}

