		{
			enemyAnimator.StartStun(interruptsCustomBehaviour);
			enemyAudio.StopMoving();
			MeleeCombatAllowed = false;
			RigidbodyEx.constraints = ((!interruptsCustomBehaviour) ? stunConstraints.Constraints : interruptedStunConstraints.Constraints);
			Steering.Pause();
		}

