		{
			enemyAnimator.StopStun();
			MeleeCombatAllowed = true;
			RigidbodyEx.ClearVelocity();
			RigidbodyEx.constraints = RigidbodyConstraints.FreezeRotation;
			Steering.Resume();
			if (this.StunEndEvent != null)
			{
