			}
		}

		private bool InInterruptionStunState()
		{
			EnemyStates currentStateId = (EnemyStates)stateMachine.CurrentStateId;
			if (currentStateId == EnemyStates.INTERRUPTED)
			{
				EnemyInterruptedSubStates currentSubStateId = (EnemyInterruptedSubStates)stateMachine.CurrentSubStateId;
				return currentSubStateId == EnemyInterruptedSubStates.INTERRUPTED_STUN;
			}
			return false;
		}

		private bool InCombatStunState()
		{
			EnemyStates currentStateId = (EnemyStates)stateMachine.CurrentStateId;
			if (currentStateId == EnemyStates.COMBAT)
			{
				EnemyCombatSubStates currentSubStateId = (EnemyCombatSubStates)stateMachine.CurrentSubStateId;
				return currentSubStateId == EnemyCombatSubStates.COMBAT_STUN;
			}
			return false;
		}

		private bool StunIsFinished()
		{
			return !stunnedUntilRigidbodyComesToRest || RigidbodyEx.velocity.sqrMagnitude <= 0.01f;
		}

		protected void AuthorityStartPatrol()
		{
			EnemyStates currentStateId = (EnemyStates)stateMachine.CurrentStateId;
			if (base.hasAuthority && currentStateId == EnemyStates.COMBAT)
			{
				stateMachine.EnterState(2);
			}
