		protected virtual void OnPatrolStart()
		{
			if (base.hasAuthority)
			{
				LastAttacker = Combatant.Invalid;
			}
			enemyAudio.StartMoving();
			RigidbodyEx.RemoveKinematic(this);
			Steering.GravityEnabled = true;
			Steering.StopAll();
			Steering.MaxHorizontalSpeed = patrolSpeed;
			Steering.MaxVerticalSpeed = patrolSpeed;
			Steering.MaxHorizontalSteeringForce = patrolMaxForce;
			Steering.MaxVerticalSteeringForce = patrolMaxForce;
			Steering.MaxAngularSpeed = patrolAngularSpeed;
		}

