		public virtual void AuthorityUpdateDefaultPatrolBehaviour()
		{
			if (!Steering.PathIsValid(SpawnTargetPosition, 0.1f))
			{
				Steering.Path(SpawnTargetPosition, movementSlowdownDistance);
			}
		}

		private void OnEnterPatrolState(ushort previousStateId, ushort previousSubStateId)
		{
			OnPatrolStart();
		}

		private void OnUpdatePatrolState()
		{
			if (base.hasAuthority)
			{
				Combatant combatant = FindNearbyAggrodAlly();
				if (combatant.IsValid)
				{
					if (combatant.Enemy != null && combatant.Enemy.Target.IsValid)
					{
						Target = combatant.Enemy.Target;
					}
					stateMachine.EnterState(3, 0);
					return;
				}
				if (FindTarget(isPatrolling: true).IsValid)
				{
					stateMachine.EnterState(3, 0);
					return;
				}
				if (Patrol != null && Patrol.HasValidPatrolPoints && !Patrol.HasFinishedPatrol(PatrolTargetId))
				{
					if ((Patrol.HasReachedTarget(Steering.SurfacePosition, PatrolTargetPosition) || !Steering.PathIsValid(PatrolTargetPosition, 0.1f)) && Patrol.TryGetNextTarget(PatrolTargetId, out var nextTargetId, out var targetPosition))
					{
						_currentPatrolTarget.Set(nextTargetId, targetPosition);
						Steering.Path(targetPosition, movementSlowdownDistance);
					}
					return;
				}
				AuthorityUpdateDefaultPatrolBehaviour();
			}
			OnPatrolUpdate();
		}

		private void OnExitPatrolState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId == 3 && stateMachine.PreviousStateId == 1)
			{
				enemyAudio.OnAggro();
				if (enemyParticles != null && HealthBarRoot != null)
				{
					enemyParticles.OnAggro(HealthBarRoot, HealthBarOffset);
				}
			}
			OnPatrolEnd();
		}

