		protected virtual void OnDeath()
		{
			hasRunOnDeath = true;
			if (this.DeathEvent != null)
			{
				this.DeathEvent(this);
			}
			if (Enemy.EnemyDeathEvent != null)
			{
				Enemy.EnemyDeathEvent(this);
			}
			if (trackTargetCount && base.hasAuthority && SingletonMonoBehaviour<EnemyManager>.Instance != null)
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.AuthorityAddEnemyTargetCount(this, Target, -1);
			}
			Steering.StopAll();
			CollidersEnabled = shatterType == ShatterType.PHYSICS_ON_COLLISION;
			RigidbodyEx.useGravity = shatterType == ShatterType.PHYSICS_ON_COLLISION;
			MeleeCombatAllowed = false;
			if (rangedWeapon != null)
			{
				rangedWeapon.StopFiring();
			}
			RigidbodyEx.constraints = RigidbodyConstraints.None;
			if (pointsDropper != null && damageInstancesReceived != null)
			{
				pointsDropper.DropPoints(damageInstancesReceived.ToArray());
			}
			if (PhotonNetwork.isMasterClient && spawnToolOnDeath && LastAttackerWeapon != null && RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				Vector3 position = ObjectSpawnOrigin.position;
				Vector3 floorPosition = LastAttacker.FloorPosition;
				Vector3 normalized = Vector3.ProjectOnPlane(floorPosition - position, Vector3.up).normalized;
				Quaternion spawnRotation = Quaternion.LookRotation(Vector3.up, -normalized);
				Tool tool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.MasterSpawnEquipment(spawnToolType, position, spawnRotation, 1f, -1, suppressAnimateInParticles: true, spawnIgnoringDynamicPhysics: true, suppressCleanup: true);
				if (tool != null)
				{
					Vector3 vector = floorPosition - normalized * 1f;
					Vector3 vector2 = Vector3.ProjectOnPlane(vector - position, Vector3.up);
					vector2 = Vector3.ClampMagnitude(vector2, 2f);
					Vector3 vector3 = Vector3.up * 4f;
					tool.RigidbodyEx.velocity = vector2 + vector3;
					tool.RigidbodyEx.angularVelocity = UnityEngine.Random.onUnitSphere * 720f * ((float)Math.PI / 180f);
				}
			}
		}

		private void OnEnterDeadState(ushort previousStateId, ushort previousSubStateId)
		{
			OnDeath();
			enemyAudio.StopMoving();
			if (base.hasAuthority)
			{
				float maxRunningTime = 0f;
				if (shatterType == ShatterType.ANIMATION)
				{
					maxRunningTime = animationShatterDeathDuration;
				}
				else if (shatterType == ShatterType.PHYSICS || shatterType == ShatterType.PHYSICS_ON_COLLISION)
				{
					maxRunningTime = 4.25f;
				}
				stateTimer.StartTimer(maxRunningTime);
			}
		}

		private void OnUpdateDeadState()
		{
			if (base.hasAuthority && stateTimer.TimerOver)
			{
				IsAlive = false;
				stateMachine.EnterState(0);
			}
		}

		private void OnExitDeadState(ushort nextStateId, ushort nextSubStateId)
		{
			if (base.hasAuthority && nextStateId != 0)
			{
				UnityEngine.Debug.Log(string.Concat("Killed on state machine error.  Transitioned from dead state to ", (EnemyStates)nextStateId, " state"));
				Health = 0;
				IsAlive = false;
			}
		}

