		private void RemoteShatter(Vector3 initialVelocity, EnemyArmorType armorType)
		{
			isShattered = true;
			RigidbodyEx.AddKinematic(this);
			if (networkTransform != null)
			{
				networkTransform.SynchronizationReadingEnabled = false;
			}
			if (shatterType == ShatterType.ANIMATION)
			{
				if (animationShatterLookAtAttack)
				{
					Vector3 normalized = initialVelocity.normalized;
					base.transform.rotation = Quaternion.LookRotation(-normalized);
				}
				enemyAnimator.PlayDeath();
			}
			else
			{
				if (shatterType != ShatterType.PHYSICS && shatterType != ShatterType.PHYSICS_ON_COLLISION)
				{
					return;
				}
				enemyAnimator.enabled = false;
				if ((IsVisible || IsHighLOD) && ragdollBodyParts != null)
				{
					bool isCriticalHit = IsCriticalHit(armorType);
					RagdollPiece[] array = ragdollBodyParts;
					foreach (RagdollPiece ragdollPiece in array)
					{
						ragdollPiece.StartRagdoll(initialVelocity, base.transform.position, ragdollShatterSpeed, isCriticalHit);
					}
				}
			}
		}

		protected virtual void OnTargetChange()
		{
			if (transferOwnershipOnTargetChange && Target.IsValid && Target.HasAuthority && !base.hasAuthority)
			{
				TransferOwnership(PhotonNetwork.player);
			}
			if (cachesLatestVisibleTargetPosition)
			{
				UpdateLatestTargetPosition(testLineOfSight: false);
			}
		}

		protected Combatant FindRandomNearbyTarget(bool isPatrolling, bool mustHaveLineOfSight)
		{
			Combatant result = Combatant.Invalid;
			FindNearbyTargets(isPatrolling, mustHaveLineOfSight, targetScratchSpace);
			if (targetScratchSpace.Count > 0)
			{
				result = targetScratchSpace[UnityEngine.Random.Range(0, targetScratchSpace.Count)];
			}
			return result;
		}

		protected Combatant FindLeastTargetedNearbyTarget(bool isPatrolling, bool mustHaveLineOfSight)
		{
			Combatant result = Combatant.Invalid;
			FindNearbyTargets(isPatrolling, mustHaveLineOfSight, targetScratchSpace);
			if (targetScratchSpace.Count > 0)
			{
				targetScratchSpace.Sort((Combatant a, Combatant b) => SingletonMonoBehaviour<EnemyManager>.Instance.GetOtherEnemyTargetCount(a).CompareTo(SingletonMonoBehaviour<EnemyManager>.Instance.GetOtherEnemyTargetCount(b)));
				int otherEnemyTargetCount = SingletonMonoBehaviour<EnemyManager>.Instance.GetOtherEnemyTargetCount(targetScratchSpace[0]);
				int num = 1;
				for (int num2 = 1; num2 < targetScratchSpace.Count; num2++)
				{
					int otherEnemyTargetCount2 = SingletonMonoBehaviour<EnemyManager>.Instance.GetOtherEnemyTargetCount(targetScratchSpace[num2]);
					if (otherEnemyTargetCount2 == otherEnemyTargetCount)
					{
						num++;
					}
					else if (otherEnemyTargetCount2 > otherEnemyTargetCount)
					{
						break;
					}
				}
				result = targetScratchSpace[UnityEngine.Random.Range(0, num)];
			}
			return result;
		}

		protected Vector3 GetTargetCentroid()
		{
			if (SingletonMonoBehaviour<EnemyManager>.Instance.TryGetOpponentCentroid(this, out var centroid))
			{
				return centroid;
			}
			return RigidbodyEx.physicsPosition;
		}

		protected void FindNearbyTargets(bool isPatrolling, bool mustHaveLineOfSight, List<Combatant> nearbyTargets)
		{
			if (isPatrolling)
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.GetOpponentsInRadius(this, patrolSearchRadius, mustHaveLineOfSight, nearbyTargets);
			}
			else
			{
				SingletonMonoBehaviour<EnemyManager>.Instance.GetOpponentsInRadius(this, preferredTargetSearchRadius, maxTargetSearchRadius, mustHaveLineOfSight, nearbyTargets);
			}
		}

		protected void FindNearbyTargetsInVisionCone(bool isPatrolling, Vector3 visionOrigin, Vector3 visionDirection, float maxAngle, float maxDistance, bool inXZPlane, bool mustHaveLineOfSight, List<Combatant> nearbyTargets)
		{
			float maxDistance2 = ((!isPatrolling) ? maxDistance : patrolSearchRadius);
			SingletonMonoBehaviour<EnemyManager>.Instance.GetOpponentsInVisionCone(this, visionOrigin, visionDirection, maxAngle, maxDistance2, inXZPlane, mustHaveLineOfSight, nearbyTargets);
		}

		protected Vector3 GetLookAtTargetVector(bool inXZPlane)
		{
			return GetLookAtVector(Target.HeadPosition, inXZPlane);
		}

		protected Vector3 GetLookAtVector(Vector3 position, bool inXZPlane)
		{
			Vector3 vector = position - base.transform.position;
			if (inXZPlane)
			{
				vector = Vector3.ProjectOnPlane(vector, Vector3.up);
			}
			return vector.normalized;
		}

		protected Vector3 GetRandomOffsetPosition(Vector3 targetPosition, float offsetDistance, float minRandomOffsetAngle, float maxRandomOffsetAngle)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(base.transform.position - targetPosition, Vector3.up).normalized;
			float num = UnityEngine.Random.Range(minRandomOffsetAngle, maxRandomOffsetAngle);
			float randomSign = UnityExtensions.GetRandomSign();
			Quaternion quaternion = Quaternion.Euler(0f, randomSign * num, 0f);
			normalized = quaternion * normalized;
			return targetPosition + normalized * offsetDistance;
		}

		private void UpdateLatestTargetPosition(bool testLineOfSight)
		{
			lastTargetPositionUpdateTime = UnityEngine.Time.time;
			if (Target.IsValid && SingletonMonoBehaviour<EnemyManager>.Instance.TargetIsAlive(Target))
			{
				Vector3 headPosition = Target.HeadPosition;
				hasTargetLineOfSight = HasLineOfSight(headPosition);
				if (!testLineOfSight || hasTargetLineOfSight)
				{
					latestVisibleTargetHeadPosition = headPosition;
					latestVisibleTargetFloorPosition = Target.FloorPosition;
				}
			}
			else
			{
				hasTargetLineOfSight = false;
			}
		}

		public static Enemy MasterSpawn(EnemyType enemyType, Vector3 position, Quaternion rotation, Vector3 spawnTargetPosition, bool spawnOnPatrol, EnemyPatrol patrol, GameTeam team, bool spawnDisengaged, int instantiatorPhotonViewId, Dictionary<string, object> instantiationParams)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return null;
			}
			string enemyPrefabName = EnemySettings.GetEnemyPrefabName(enemyType);
			if (string.IsNullOrEmpty(enemyPrefabName))
			{
				return null;
			}
			GameObject gameObject = PhotonNetwork.InstantiateSceneObject(enemyPrefabName, position, rotation, 1f, 0, new object[9]
			{
				instantiatorPhotonViewId,
				instantiationParams,
				enemyType,
				spawnTargetPosition,
				spawnOnPatrol,
				(!(patrol != null)) ? (-1) : patrol.photonView.viewID,
				(int)team,
				spawnDisengaged,
				UnityEngine.Random.value
			});
			return (!(gameObject != null)) ? null : gameObject.GetComponent<Enemy>();
		}

		public static void MasterKill(Enemy enemy)
		{
			if (PhotonNetwork.isMasterClient && enemy != null && enemy.IsAlive)
			{
				if (!enemy.hasAuthority)
				{
					enemy.photonView.TransferOwnership(PhotonNetwork.player);
				}
				if (enemy.Health > 0)
				{
					enemy.Health = 0;
				}
				enemy.AuthorityOnDamageApplyForce(WeaponDamageType.DEFAULT, EnemyArmorType.NORMAL, Vector3.up, enemy.transform.position);
			}
		}

		public static bool IsShield(EnemyArmorType enemyArmorType)
		{
			return enemyArmorType == EnemyArmorType.SHIELD;
		}

		public static bool IsCriticalHit(EnemyArmorType enemyArmorType)
		{
			return enemyArmorType == EnemyArmorType.CRITICAL_HIT;
		}

		private void AuthorityUpdateAnimationIsMoving()
		{
			if (base.hasAuthority)
			{
				AnimationIsMoving = GetIsMoving();
			}
		}

		protected virtual bool GetIsMoving()
		{
			if (IsSpawning)
			{
				return false;
			}
			if (!Steering.IsSeeking && !Steering.IsPathing)
			{
				return false;
			}
			if (suppressMovingAnimation)
			{
				return false;
			}
			return Steering.CurrentVelocity.sqrMagnitude >= 0.0025000002f;
		}

		private void OnAnimationIsMovingChange()
		{
			enemyAnimator.IsMoving = AnimationIsMoving;
		}

		public void RenderOutline(OutlineEffectRenderer.OutlineType outlineType)
		{
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				OutlineEffectRenderer.RenderOutline(outlineType, renderer);
			}
		}

		public virtual void TransferOwnership(PhotonPlayer player)
		{
			base.photonView.TransferOwnership(player);
			if (accessories != null)
			{
				QuestEnemyArticulatingAccessory[] array = accessories;
				foreach (QuestEnemyArticulatingAccessory questEnemyArticulatingAccessory in array)
				{
					questEnemyArticulatingAccessory.photonView.TransferOwnership(player);
				}
			}
		}

		[PunRPC]
		protected void RpcOnTookDamage(Combatant attacker, WeaponDamageType damageType, EnemyArmorType armorType, int damage, bool killingBlow, Vector3 hitPoint, Vector3 hitNormal)
		{
			OnTookDamage(attacker, damageType, armorType, damage, killingBlow, hitPoint, hitNormal);
		}

		[PunRPC]
		protected void RpcShatter(Vector3 initialVelocity, EnemyArmorType armorTypeId)
		{
			RemoteShatter(initialVelocity, armorTypeId);
		}

		private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			if (Health <= 0)
			{
				OnDeath();
			}
			if (!IsAlive)
			{
				OnCleanup();
			}
		}
	}
	[RequireComponent(typeof(Enemy))]
	public class EnemyAnimator : UnityEngine.MonoBehaviour
	{
		public enum CullingMode
		{
			CullCompletely = 0,
			CullUpdateTransforms = 10,
			AnimateIfAuthority = 20,
			AlwaysAnimate = 30
		}

		public enum MeleeCombatState
		{
			NONE,
			CHARGE,
			ATTACK,
			POST_ATTACK,
			ATTACK_INTERRUPTED
		}

		public enum RangedCombatState
		{
			NONE,
			CHARGE,
			ATTACK,
			POST_ATTACK
		}

		public enum JumpState
		{
			NONE,
			PREPARE,
			JUMP
		}

		[SerializeField]
		private bool patrolHasTransition;

		[Header("Movement")]
		[SerializeField]
		private bool isAlwaysMoving;

		[Header("Melee Combat")]
		[SerializeField]
		private int meleeAttackVariantCount = 1;

		[SerializeField]
		private int blockVariantCount;

		[Header("Optimization")]
		[SerializeField]
		[Tooltip("Melee enemies should never cull, since their attacks are based on their collider positions.")]
		private CullingMode cullingMode;

		private static readonly int ON_RANGED_ATTACK_ID = Animator.StringToHash("OnRangedAttack");

		private static readonly int ON_MELEE_ATTACK_ID = Animator.StringToHash("OnMeleeAttack");

		private static readonly int ON_BLOCK_ID = Animator.StringToHash("OnBlock");

		private static readonly int ON_DEATH_ID = Animator.StringToHash("OnDeath");

		private static readonly int IS_MOVING_ID = Animator.StringToHash("IsMoving");

		private static readonly int IS_IN_COMBAT_ID = Animator.StringToHash("IsInCombat");

		private static readonly int IS_BLOCKING_ID = Animator.StringToHash("IsBlocking");

		private static readonly int IS_STUNNED_COMBAT_ID = Animator.StringToHash("IsStunnedCombat");

		private static readonly int IS_STUNNED_INTERRUPTED_ID = Animator.StringToHash("IsStunnedInterrupted");

		private static readonly int IS_DISENGAGED_ID = Animator.StringToHash("IsDisengaged");

		private static readonly int IS_SPRINTING_ID = Animator.StringToHash("IsSprinting");

		private static readonly int MELEE_COMBAT_STATE_ID = Animator.StringToHash("MeleeCombatState");

		private static readonly int RANGED_COMBAT_STATE_ID = Animator.StringToHash("RangedCombatState");

		private static readonly int JUMP_STATE_ID = Animator.StringToHash("JumpState");

		private static readonly int BLOCK_VARIANT_ID = Animator.StringToHash("BlockVariant");

		private static readonly int PATROL_HAS_TRANSITION_ID = Animator.StringToHash("PatrolHasTransition");

		private static readonly int MELEE_ATTACK_VARIANT_ID = Animator.StringToHash("MeleeAttackVariant");

		private Animator animator;

		private Enemy enemy;

		private bool hasAnimator;

		private float lastUpdateTime;

		private int blockVariantIndex;

		private int meleeAttackVariantIndex;

		public bool InCombat
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetBool(IS_IN_COMBAT_ID, value);
				}
			}
		}

		public bool IsMoving
		{
			set
			{
				if (hasAnimator)
				{
					if (isAlwaysMoving)
					{
						value = true;
					}
					animator.SetBool(IS_MOVING_ID, value);
				}
			}
		}

		public bool IsDisengaged
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetBool(IS_DISENGAGED_ID, value);
				}
			}
		}

		public MeleeCombatState MeleeCombat
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetFloat(MELEE_ATTACK_VARIANT_ID, meleeAttackVariantIndex);
					animator.SetInteger(MELEE_COMBAT_STATE_ID, (int)value);
				}
			}
		}

		public RangedCombatState RangedCombat
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetInteger(RANGED_COMBAT_STATE_ID, (int)value);
				}
			}
		}

		public JumpState Jump
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetFloat(MELEE_ATTACK_VARIANT_ID, meleeAttackVariantIndex);
					animator.SetInteger(JUMP_STATE_ID, (int)value);
				}
			}
		}

		public bool IsBlocking
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetBool(IS_BLOCKING_ID, value);
					if (value)
					{
						animator.SetInteger(BLOCK_VARIANT_ID, blockVariantIndex);
						animator.SetTrigger(ON_BLOCK_ID);
						blockVariantIndex = GetNextBlockVariantIndex();
					}
				}
			}
		}

		public bool IsSprinting
		{
			set
			{
				if (hasAnimator)
				{
					animator.SetFloat(MELEE_ATTACK_VARIANT_ID, meleeAttackVariantIndex);
					animator.SetBool(IS_SPRINTING_ID, value);
				}
			}
		}

		public void StartStun(bool isInterrupted)
		{
			if (hasAnimator)
			{
				animator.SetBool(IS_STUNNED_COMBAT_ID, !isInterrupted);
				animator.SetBool(IS_STUNNED_INTERRUPTED_ID, isInterrupted);
			}
		}

		public void StopStun()
		{
			if (hasAnimator)
			{
				animator.SetBool(IS_STUNNED_COMBAT_ID, value: false);
				animator.SetBool(IS_STUNNED_INTERRUPTED_ID, value: false);
			}
		}

		public void PlayRangedAttack()
		{
			if (animator != null)
			{
				animator.SetTrigger(ON_RANGED_ATTACK_ID);
			}
		}

		public void PlayMeleeAttack()
		{
			if (animator != null)
			{
				animator.SetFloat(MELEE_ATTACK_VARIANT_ID, meleeAttackVariantIndex);
				animator.SetTrigger(ON_MELEE_ATTACK_ID);
			}
		}

		public void PlayDeath()
		{
			if (hasAnimator)
			{
				animator.SetTrigger(ON_DEATH_ID);
			}
		}

		private void Awake()
		{
			animator = GetComponentInChildren<Animator>(includeInactive: true);
			enemy = GetComponent<Enemy>();
			enemy.LODChangedEvent += LODChangedEvent;
			hasAnimator = animator != null;
			if (!hasAnimator)
			{
				UnityEngine.Debug.LogWarning(base.name + " does not have a Unity Animator Component");
				return;
			}
			if (blockVariantCount > 1)
			{
				blockVariantIndex = GetRandomBlockVariantIndex();
			}
			if (meleeAttackVariantCount > 1)
			{
				SetMeleeAttackVariantIndex(GetRandomMeleeAttackVariantIndex());
			}
			IsMoving = false;
			InCombat = false;
			IsDisengaged = false;
			IsSprinting = false;
			IsBlocking = false;
			StopStun();
			animator.SetBool(PATROL_HAS_TRANSITION_ID, patrolHasTransition);
			Jump = JumpState.NONE;
			MeleeCombat = MeleeCombatState.NONE;
			RangedCombat = RangedCombatState.NONE;
			InitializeCullingMode();
		}

		private void OnDestroy()
		{
			if (enemy != null)
			{
				enemy.LODChangedEvent -= LODChangedEvent;
			}
		}

		private void OnEnable()
		{
			if (hasAnimator)
			{
				animator.enabled = enemy.IsHighLOD;
			}
		}

		private void OnDisable()
		{
			if (hasAnimator)
			{
				animator.enabled = false;
			}
		}

		private void LODChangedEvent(Enemy enemy)
		{
			if (hasAnimator)
			{
				animator.enabled = enemy.IsHighLOD;
			}
		}

		private void Update()
		{
			if (!hasAnimator)
			{
				base.enabled = false;
			}
			else if (animator.enabled)
			{
				lastUpdateTime = UnityEngine.Time.time;
			}
		}

		public void LowPriorityUpdate()
		{
			if (hasAnimator)
			{
				float deltaTime = UnityEngine.Time.time - lastUpdateTime;
				animator.Update(deltaTime);
			}
			lastUpdateTime = UnityEngine.Time.time;
		}

		private int GetNextBlockVariantIndex()
		{
			if (blockVariantCount <= 1)
			{
				return blockVariantIndex;
			}
			int num = UnityEngine.Random.Range(0, blockVariantCount);
			return (blockVariantIndex + num) % blockVariantCount;
		}

		private int GetRandomBlockVariantIndex()
		{
			if (blockVariantCount <= 0)
			{
				return 0;
			}
			return UnityEngine.Random.Range(0, blockVariantCount);
		}

		public int GetRandomMeleeAttackVariantIndex()
		{
			return UnityEngine.Random.Range(0, meleeAttackVariantCount);
		}

		public void SetMeleeAttackVariantIndex(int index)
		{
			meleeAttackVariantIndex = Mathf.Clamp(index, 0, meleeAttackVariantCount);
		}

		private void InitializeCullingMode()
		{
			enemy.photonView.OwnerChangedEvent -= OnEnemyOwnerChanged;
			if (cullingMode == CullingMode.AnimateIfAuthority)
			{
				enemy.photonView.OwnerChangedEvent += OnEnemyOwnerChanged;
			}
			SetCullingMode();
		}

		private void SetCullingMode()
		{
			switch (cullingMode)
			{
			case CullingMode.CullCompletely:
				animator.cullingMode = AnimatorCullingMode.CullCompletely;
				break;
			case CullingMode.CullUpdateTransforms:
				animator.cullingMode = AnimatorCullingMode.CullUpdateTransforms;
				break;
			case CullingMode.AnimateIfAuthority:
				if (enemy.hasAuthority)
				{
					animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
				}
				else
				{
					animator.cullingMode = AnimatorCullingMode.CullUpdateTransforms;
				}
				break;
			case CullingMode.AlwaysAnimate:
				animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
				break;
			}
		}

		private void OnEnemyOwnerChanged(int ownerId)
		{
			SetCullingMode();
		}
	}
}
