		private bool chargeAudioIsLooping;

		public bool MovingSoundVolumeDrivenBySteeringSpeed { get; set; } = true;

		private void Awake()
		{
			thisEnemy = GetComponent<Enemy>();
			thisEnemy.LODChangedEvent += OnThisEnemyLODChange;
		}

		private void OnDestroy()
		{
			if (thisEnemy != null)
			{
				thisEnemy.LODChangedEvent -= OnThisEnemyLODChange;
			}
			if (movingSoundAudioSource != null)
			{
				movingSoundAudioSource.Release();
				movingSoundAudioSource = null;
			}
			StopCharge();
		}

		private void Update()
		{
			if (MovingSoundVolumeDrivenBySteeringSpeed && movingSoundAudioSource != null && movingSoundAudioSource.AudioSource.isPlaying && thisEnemy != null && thisEnemy.Steering != null)
			{
				Vector3 vector = ((!thisEnemy.hasAuthority) ? thisEnemy.RigidbodyEx.velocity : thisEnemy.Steering.CurrentVelocity);
				movingSoundAudioSource.AudioSource.volume = movingSound.volume * Mathf.Min(1f, vector.magnitude / thisEnemy.Steering.MaxHorizontalSpeed);
			}
		}

		public void OnAggro()
		{
