		public void StopMoving()
		{
			movingAudioIsLooping = false;
			StopMovingAudioInternal();
		}

		public void OnAttack()
		{
			if (attackVOs != null)
			{
				AudioManager.PlayRandom3DSFX(attackVOs, base.transform);
			}
			if (attackSounds != null)
			{
				AudioManager.PlayRandom3DSFX(attackSounds, base.transform);
			}
		}

		public void OnChargeAttack()
		{
			if (chargeAttackSFX != null)
			{
				AudioManager.Play3DSFX(chargeAttackSFX, base.transform);
			}
		}

		public void OnTakeDamage(EnemyArmorType armorType, Vector3 hitPoint, bool attackerIsLocal)
		{
			if ((((object)onDamageAudioSource == null) ? ((bool?)null) : onDamageAudioSource.AudioSource?.isPlaying) == true)
			{
				onDamageAudioSource.AudioSource.time = 0f;
			}
			else
			{
				RecRoomAudioClip damageSound = GetDamageSound(armorType);
				if (damageSound?.audioClip != null)
				{
					if (attackerIsLocal)
					{
						onDamageAudioSource = AudioManager.Play2DSFX(damageSound, OnDamageAudioSourceReleased);
					}
					else
					{
						onDamageAudioSource = AudioManager.Play3DSFX(damageSound, base.transform, null, OnDamageAudioSourceReleased);
					}
				}
			}
			if ((((object)onDamageVOSource == null) ? ((bool?)null) : onDamageVOSource.AudioSource?.isPlaying) == true)
			{
				onDamageVOSource.AudioSource.time = 0f;
				return;
			}
			int? num = ((takeDamageVOs != null) ? new int?(takeDamageVOs.Length) : ((int?)null));
			if (num.HasValue && num.GetValueOrDefault() > 0)
			{
				onDamageVOSource = AudioManager.PlayRandom3DSFX(takeDamageVOs, base.transform, null, allowRepeat: false, OnDamageVOSourceReleased);
			}
		}

		public void OnKill(EnemyArmorType armorType, Vector3 hitPoint, bool attackerIsLocal)
		{
			RecRoomAudioClip killSound = GetKillSound(armorType);
			if (killSound != null)
			{
				if (attackerIsLocal)
				{
					AudioManager.Play2DSFX(killSound);
				}
				else
				{
					AudioManager.Play3DSFX(killSound, base.transform);
				}
			}
			if (deathVOs != null)
			{
				AudioManager.PlayRandom3DSFX(deathVOs, base.transform);
			}
		}

		public void StartCharge(bool looping)
		{
			chargeAudioIsLooping = looping;
			StopChargeAudioInternal();
			StartChargeAudioInternal(chargeAudioIsLooping);
		}

		public void StopCharge()
		{
			chargeAudioIsLooping = false;
			StopChargeAudioInternal();
		}

		public void OnExplode()
		{
			AudioManager.Play3DSFX(explosion, base.transform.position);
		}

		private RecRoomAudioClip GetDamageSound(EnemyArmorType armorType)
		{
			RecRoomAudioClip recRoomAudioClip = null;
			if (Enemy.IsShield(armorType))
			{
				return onShieldedDamageSound;
			}
			if (Enemy.IsCriticalHit(armorType))
			{
				return onCriticalHitDamageSound;
			}
			return onDamageSound;
		}

		private RecRoomAudioClip GetKillSound(EnemyArmorType armorType)
		{
			RecRoomAudioClip recRoomAudioClip = null;
			if (Enemy.IsCriticalHit(armorType))
			{
				return onCriticalHitKill;
			}
			return onDeathSound;
		}

		private void StartMovingAudioInternal()
		{
			if (thisEnemy.IsHighLOD && movingSound != null && movingSound.audioClip != null && movingSoundAudioSource == null)
			{
				movingSoundAudioSource = AudioManager.StartLooping3DSFX(movingSound, base.transform, null, OnMovingSoundAudioSourceReleased);
			}
		}

		private void StopMovingAudioInternal()
		{
			if (movingSoundAudioSource != null)
			{
				AudioManager.StopLoopingSFX(movingSoundAudioSource);
				movingSoundAudioSource = null;
			}
		}

		private void StartChargeAudioInternal(bool looping)
		{
			if (thisEnemy.IsHighLOD && charge != null && charge.audioClip != null && chargeAudioSource == null)
			{
				if (looping)
				{
					chargeAudioSource = AudioManager.StartLooping3DSFX(charge, base.transform, null, OnChargeAudioSourceReleased);
				}
				else
				{
					chargeAudioSource = AudioManager.Play3DSFX(charge, base.transform, null, OnChargeAudioSourceReleased);
				}
			}
		}

		private void StopChargeAudioInternal()
		{
			if (chargeAudioSource != null)
			{
				if (chargeAudioSource.AudioSource.loop)
				{
					AudioManager.StopLoopingSFX(chargeAudioSource);
				}
				chargeAudioSource = null;
			}
		}

		private void OnThisEnemyLODChange(Enemy enemy)
		{
			if (movingAudioIsLooping)
			{
				if (enemy.IsHighLOD)
				{
					StartMovingAudioInternal();
				}
				else
				{
					StopMovingAudioInternal();
				}
			}
			if (chargeAudioIsLooping)
			{
				if (enemy.IsHighLOD)
				{
					StartChargeAudioInternal(looping: true);
				}
				else
				{
					StopChargeAudioInternal();
				}
			}
		}

		private void OnDamageAudioSourceReleased(SFXAudioSource source)
		{
			onDamageAudioSource = null;
		}

		private void OnDamageVOSourceReleased(SFXAudioSource source)
		{
			onDamageVOSource = null;
		}

		private void OnChargeAudioSourceReleased(SFXAudioSource source)
		{
			chargeAudioSource = null;
		}

		private void OnMovingSoundAudioSourceReleased(SFXAudioSource source)
		{
			movingSoundAudioSource = null;
		}
	}
