	[RequireComponent(typeof(MaintainWorldSpaceOffset))]
	public class EnemyCombatUI : UnityEngine.MonoBehaviour
	{
		private HealthBar healthBar;

		private MaintainWorldSpaceOffset updater;

		private Vector3 defaultScale = Vector3.one;

		private Enemy _enemy;

		public Enemy Enemy
		{
			get
			{
				return _enemy;
			}
			set
			{
				_enemy = value;
				if (_enemy != null)
				{
					updater.Origin = ((!(_enemy.HealthBarRoot != null)) ? _enemy.transform : _enemy.HealthBarRoot);
					updater.WorldSpaceOffset = _enemy.HealthBarOffset;
					base.transform.localScale = defaultScale * _enemy.HealthBarScale;
					healthBar.ResetHealth(_enemy.Health, _enemy.MaxHealth);
				}
			}
		}

		public bool IsVisible => healthBar != null && healthBar.gameObject.activeSelf;

		private void Awake()
		{
			healthBar = GetComponentInChildren<HealthBar>();
			if (healthBar == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing a health bar.");
			}
			updater = GetComponent<MaintainWorldSpaceOffset>();
			if (updater == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing a maintain world space offset.");
			}
			defaultScale = base.transform.localScale;
			Enemy.EnemyHealthChangeEvent += OnThisEnemyHealthChange;
		}

		private void OnDestroy()
		{
			Enemy.EnemyHealthChangeEvent -= OnThisEnemyHealthChange;
		}

		private void OnThisEnemyHealthChange(Enemy enemy, int health, int maxHealth, PhotonPlayer damagingPlayer)
		{
			if (Enemy != null && enemy == Enemy)
			{
				healthBar.OnHealthChange(health, maxHealth, damagingPlayer?.IsLocal ?? false);
			}
		}

		public void FadeIn()
		{
			base.gameObject.SetActive(value: true);
			updater.enabled = true;
			healthBar.FadeIn();
		}

		public void FadeOut()
		{
			base.gameObject.SetActive(value: true);
			updater.enabled = true;
			healthBar.FadeOut();
		}
	}
