namespace RecRoom.Core.AI
{
	public class EnemyManager : SingletonMonoBehaviour<EnemyManager>
	{
		private class TeamEnemyTargets
		{
			public List<Combatant> Targets;

			public Vector3 Centroid;
		}

		private const int HIGH_QUALITY_HIGH_LOD_ENEMIES = 15;

		private const int FASTEST_QUALITY_HIGH_LOD_ENEMIES = 5;

		private const int LOD_UPDATE_INTERVAL_FRAMES = 5;

		private const float ENEMY_NOT_VISIBLE_WEIGHT_RATIO = 100f;

		private const int DEFAULT_TEAM_TARGET_ARRAY_SIZE = 100;

		private static int MaxHighLODEnemies;

		private static readonly List<float> INSTANTANEOUS_ENEMY_WEIGHTS = new List<float>(100);

		private static readonly Dictionary<GameTeam, TeamEnemyTargets> allEnemyTargets = new Dictionary<GameTeam, TeamEnemyTargets>();

		private static readonly List<Enemy> _allEnemies = new List<Enemy>();

		public static bool SupportsEnemyOnEnemyFriendlyFire = true;

		public static bool SupportsPlayerOnEnemyFriendlyFire = true;

		public static List<Enemy> AllEnemies => _allEnemies;

		public static int EnemyCount => _allEnemies.Count;

		public static int AggrodEnemyCount
		{
			get
			{
				int num = 0;
				for (int i = 0; i < _allEnemies.Count; i++)
				{
					if (_allEnemies[i] != null && _allEnemies[i].IsAggrod)
					{
						num++;
					}
				}
				return num;
			}
		}

		private void Start()
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingsUpdated;
			OnQualitySettingsUpdated(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingsUpdated;
			}
		}

		private void Update()
		{
			UpdateEnemyLODs();
			UpdateEnemyTargetLists();
		}

		public void RegisterEnemy(Enemy enemy)
		{
			_allEnemies.Add(enemy);
		}

		public void UnregisterEnemy(Enemy enemy)
		{
			_allEnemies.Remove(enemy);
		}

		public bool TargetIsAlive(Combatant target)
		{
			if (target.Player != null && target.Player.PhotonPlayer != null)
			{
				GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
				return gameManager != null && gameManager.CombatManager.PlayerIsAlive(target.Player.PhotonPlayer);
			}
			if (target.Enemy != null)
			{
				return target.Enemy.IsAlive;
			}
			return false;
		}

		public bool IsAlly(GameTeam team, Combatant target)
		{
			if (target.Enemy != null)
			{
				return IsAlly(team, target.Enemy);
			}
			if (target.Player != null)
			{
				return IsAlly(team, target.Player.PhotonPlayer);
			}
			return false;
		}

		public bool IsAlly(GameTeam team, Enemy enemy)
		{
			return enemy != null && team == enemy.Team;
		}

		public bool IsAlly(GameTeam team, PhotonPlayer player)
		{
			GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			if (player != null && team != GameTeam.ANY && gameManager != null)
			{
				return gameManager.TeamManager.PlayerOnTeam(player, team);
			}
			return false;
		}

		public bool IsValidAttack(Enemy hitEnemy, Combatant attacker)
		{
			if (hitEnemy == null || !attacker.IsValid)
			{
				return false;
			}
			if (!IsAlly(hitEnemy.Team, attacker))
			{
				return true;
			}
			if (attacker.Enemy != null)
			{
				if (attacker.Enemy == hitEnemy)
				{
					return true;
				}
				return SupportsEnemyOnEnemyFriendlyFire;
			}
			if (attacker.Player != null)
			{
				return SupportsPlayerOnEnemyFriendlyFire;
			}
			return true;
		}

		public Combatant GetAggrodAllyInRadius(Enemy thisEnemy, float radius)
		{
			TeamEnemyTargets value = null;
			if (!allEnemyTargets.TryGetValue(thisEnemy.Team, out value))
			{
				return Combatant.Invalid;
			}
			Vector3 position = thisEnemy.transform.position;
			float num = radius * radius;
			for (int i = 0; i < value.Targets.Count; i++)
			{
				if (!(value.Targets[i].Enemy == null) && !(value.Targets[i].Enemy == thisEnemy) && value.Targets[i].Enemy.IsAggrod && value.Targets[i].Enemy.CanAggroEnemies && !((value.Targets[i].FloorPosition - position).sqrMagnitude >= num))
				{
					return value.Targets[i];
				}
			}
			return Combatant.Invalid;
		}

		public Combatant GetClosestOpponent(Enemy thisEnemy, out float distanceToClosestTargetSqr)
		{
			GameTeam team = thisEnemy.Team;
			Vector3 position = thisEnemy.transform.position;
			GameTeam gameTeam = GameTeam.ANY;
			int num = -1;
			distanceToClosestTargetSqr = float.MaxValue;
			foreach (GameTeam key in allEnemyTargets.Keys)
			{
				if (key == team)
				{
					continue;
				}
				TeamEnemyTargets teamEnemyTargets = allEnemyTargets[key];
				for (int i = 0; i < teamEnemyTargets.Targets.Count; i++)
				{
					Vector3 vector = teamEnemyTargets.Targets[i].FloorPosition - position;
					float sqrMagnitude = Vector3.ProjectOnPlane(vector, Vector3.up).sqrMagnitude;
					if (sqrMagnitude <= distanceToClosestTargetSqr)
					{
						distanceToClosestTargetSqr = sqrMagnitude;
						gameTeam = key;
						num = i;
					}
				}
			}
			if (gameTeam != GameTeam.ANY && num >= 0)
			{
				return allEnemyTargets[gameTeam].Targets[num];
			}
			return Combatant.Invalid;
		}

		public void GetOpponentsInRadius(Enemy thisEnemy, float maxRadius, bool mustHaveLineOfSight, List<Combatant> targetsOut)
		{
			GetOpponentsInRadius(thisEnemy, maxRadius, maxRadius, mustHaveLineOfSight, targetsOut);
		}

		public void GetOpponentsInRadius(Enemy thisEnemy, float preferredRadius, float maxRadius, bool mustHaveLineOfSight, List<Combatant> targetsOut)
		{
			targetsOut.Clear();
			FindOpponentsWithinRadius(thisEnemy, preferredRadius, mustHaveLineOfSight, targetsOut);
			if (targetsOut.Count == 0 && maxRadius > preferredRadius)
			{
				FindOpponentsWithinRadius(thisEnemy, maxRadius, mustHaveLineOfSight, targetsOut);
			}
		}

		public void GetOpponentsInVisionCone(Enemy thisEnemy, Vector3 visionOrigin, Vector3 visionForward, float maxAngle, float maxDistance, bool inXZPlane, bool mustHaveLineOfSight, List<Combatant> targetsOut)
		{
			targetsOut.Clear();
			if (inXZPlane)
			{
				visionForward = Vector3.ProjectOnPlane(visionForward, Vector3.up);
			}
			GameTeam team = thisEnemy.Team;
			Vector3 position = thisEnemy.transform.position;
			float num = Mathf.Cos(maxAngle * ((float)Math.PI / 180f));
			float num2 = maxDistance * maxDistance;
			foreach (GameTeam key in allEnemyTargets.Keys)
			{
				if (key == team)
				{
					continue;
				}
				TeamEnemyTargets teamEnemyTargets = allEnemyTargets[key];
				for (int i = 0; i < teamEnemyTargets.Targets.Count; i++)
				{
					Vector3 vector = teamEnemyTargets.Targets[i].HeadPosition - position;
					if (inXZPlane)
					{
						vector = Vector3.ProjectOnPlane(vector, Vector3.up);
					}
					if (!(vector.sqrMagnitude > num2) && !(Vector3.Dot(vector.normalized, visionForward) < num) && (!mustHaveLineOfSight || thisEnemy.HasLineOfSight(teamEnemyTargets.Targets[i].HeadPosition)))
					{
						targetsOut.Add(teamEnemyTargets.Targets[i]);
					}
				}
			}
		}

		public bool TryGetOpponentCentroid(Enemy thisEnemy, out Vector3 centroid)
		{
			centroid = Vector3.zero;
			int num = 0;
			GameTeam team = thisEnemy.Team;
			foreach (GameTeam key in allEnemyTargets.Keys)
			{
				if (key != team)
				{
					TeamEnemyTargets teamEnemyTargets = allEnemyTargets[key];
					if (teamEnemyTargets.Targets.Count > 0)
					{
						num++;
						centroid += teamEnemyTargets.Centroid;
					}
				}
			}
			if (num == 0)
			{
				return false;
			}
			centroid /= (float)num;
			return true;
		}

		public int GetOtherEnemyTargetCount(Combatant target)
		{
			GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			if (gameManager != null && target.Player != null)
			{
				return gameManager.CombatManager.GetPlayerEnemyTargetCount(target.Player.PhotonPlayer);
			}
			return 0;
		}

		public void AuthorityAddEnemyTargetCount(Enemy thisEnemy, Combatant target, int delta)
		{
			GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			if (thisEnemy != null && thisEnemy.hasAuthority && gameManager != null && target.IsValid && target.Player != null)
			{
				gameManager.CombatManager.AddPlayerEnemyTargetCount(target.Player.PhotonPlayer, delta);
			}
		}

		private float GetEnemyLODWeight(Enemy enemy)
		{
			float num = Vector3.SqrMagnitude(enemy.transform.position - Player.LocalPlayer.Head.transform.position);
			if (!enemy.IsVisible)
			{
				num *= 100f;
			}
			return num;
		}

		private void UpdateEnemyLODs()
		{
			if (_allEnemies.Count <= MaxHighLODEnemies)
			{
				for (int i = 0; i < _allEnemies.Count; i++)
				{
					_allEnemies[i].IsHighLOD = true;
				}
				return;
			}
			if (UnityEngine.Time.frameCount % 5 == 0)
			{
				INSTANTANEOUS_ENEMY_WEIGHTS.Clear();
				for (int j = 0; j < _allEnemies.Count; j++)
				{
					INSTANTANEOUS_ENEMY_WEIGHTS.Add(GetEnemyLODWeight(_allEnemies[j]));
				}
				float nthLowestValue = INSTANTANEOUS_ENEMY_WEIGHTS.GetNthLowestValue(MaxHighLODEnemies + 1);
				for (int k = 0; k < _allEnemies.Count; k++)
				{
					bool isHighLOD = INSTANTANEOUS_ENEMY_WEIGHTS[k] < nthLowestValue;
					_allEnemies[k].IsHighLOD = isHighLOD;
				}
				return;
			}
			int num = Mathf.Max(1, 4);
			int num2 = UnityEngine.Time.frameCount % num;
			for (int l = 0; l < _allEnemies.Count; l++)
			{
				if (!_allEnemies[l].IsHighLOD && (l + num2) % num == 0)
				{
					_allEnemies[l].LowLODUpdate();
				}
			}
		}

		private void OnQualitySettingsUpdated(RecRoomQualitySetting setting)
		{
			MaxHighLODEnemies = ((setting != RecRoomQualitySetting.Fastest && setting != RecRoomQualitySetting.PS4) ? 15 : 5);
		}

		private void UpdateEnemyTargetLists()
		{
			foreach (TeamEnemyTargets value in allEnemyTargets.Values)
			{
				value.Targets.Clear();
				value.Centroid = Vector3.zero;
			}
			GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			if (gameManager == null)
			{
				PhotonPlayer[] playerList = PhotonNetwork.playerList;
				PhotonPlayer[] array = playerList;
				foreach (PhotonPlayer player in array)
				{
					AddEnemyTarget(player, GameTeam.ANY);
				}
			}
			else
			{
				IEnumerable<PhotonPlayer> activePlayers = gameManager.TeamManager.GetActivePlayers();
				foreach (PhotonPlayer item in activePlayers)
				{
					if (!gameManager.IsGameRunning || gameManager.CombatManager.PlayerIsAlive(item))
					{
						AddEnemyTarget(item, gameManager.TeamManager.GetPlayerTeam(item));
					}
				}
			}
			foreach (Enemy allEnemy in _allEnemies)
			{
				AddEnemyTarget(allEnemy, allEnemy.Team);
			}
			foreach (TeamEnemyTargets value2 in allEnemyTargets.Values)
			{
				if (value2.Targets.Count > 0)
				{
					value2.Centroid /= (float)value2.Targets.Count;
				}
			}
		}

		private void AddEnemyTarget(PhotonPlayer player, GameTeam team)
		{
			AddTarget(new Combatant(player), team);
		}

		private void AddEnemyTarget(Enemy enemy, GameTeam team)
		{
			AddTarget(new Combatant(enemy), team);
		}

		private void AddTarget(Combatant target, GameTeam team)
		{
			TeamEnemyTargets value = null;
			if (!allEnemyTargets.TryGetValue(team, out value))
			{
				value = new TeamEnemyTargets();
				value.Targets = new List<Combatant>(100);
				value.Centroid = Vector3.zero;
				allEnemyTargets.Add(team, value);
			}
			value.Targets.Add(target);
			value.Centroid += target.FloorPosition;
		}

		private void FindOpponentsWithinRadius(Enemy thisEnemy, float radius, bool mustHaveLineOfSight, List<Combatant> targetsOut)
		{
			GameTeam team = thisEnemy.Team;
			Vector3 position = thisEnemy.transform.position;
			float num = radius * radius;
			foreach (GameTeam key in allEnemyTargets.Keys)
			{
				if (key == team)
				{
					continue;
				}
				TeamEnemyTargets teamEnemyTargets = allEnemyTargets[key];
				for (int i = 0; i < teamEnemyTargets.Targets.Count; i++)
				{
					if (!((teamEnemyTargets.Targets[i].FloorPosition - position).sqrMagnitude > num) && (!mustHaveLineOfSight || thisEnemy.HasLineOfSight(teamEnemyTargets.Targets[i].HeadPosition)))
					{
						targetsOut.Add(teamEnemyTargets.Targets[i]);
					}
				}
			}
		}
	}
	public class EnemyParticles : UnityEngine.MonoBehaviour
	{
		[Header("Damage Particles")]
		[SerializeField]
		private PooledParticle defaultDamageParticles;

		[SerializeField]
		private PooledParticle onDamageParticles;

		[SerializeField]
		private PooledParticle onShieldedDamageParticles;

		[SerializeField]
		private PooledParticle onCriticalHitDamageParticles;

		[SerializeField]
		private float damageParticleZBias;

		[Header("Kill Particles")]
		[SerializeField]
		private PooledParticle defaultKillParticles;

		[SerializeField]
		private PooledParticle onKillParticles;

		[SerializeField]
		private PooledParticle onCriticalHitKillParticles;

		[SerializeField]
		private float killParticleZBias;

		[Header("Alert")]
		[SerializeField]
		private PooledParticle onAlertParticles;

		[Header("Charge")]
		[SerializeField]
		private PooledParticle onChargeParticles;

		[Header("Explosion")]
		[SerializeField]
		private PooledParticle onExplodeParticles;

		private PooledParticle chargeLoopingParticles;

		private void OnDestroy()
		{
			StopCharge();
		}

		public void OnTakeDamage(EnemyArmorType armorType, Vector3 impactPoint, Vector3 impactSurfaceNormal)
		{
			PooledParticle pooledParticle = null;
			pooledParticle = (Enemy.IsShield(armorType) ? onShieldedDamageParticles : ((!Enemy.IsCriticalHit(armorType)) ? onDamageParticles : onCriticalHitDamageParticles));
			if (pooledParticle == null)
			{
				pooledParticle = defaultDamageParticles;
			}
			if (pooledParticle != null)
			{
				PooledParticle pooledParticle2 = ObjectPool.Instance.Acquire(pooledParticle);
				if (pooledParticle2 != null)
				{
					pooledParticle2.Play(impactPoint + impactSurfaceNormal * damageParticleZBias, Quaternion.LookRotation(impactSurfaceNormal, Vector3.up));
				}
			}
		}

		public void OnKill(EnemyArmorType armorType, Vector3 impactPoint, Vector3 impactSurfaceNormal)
		{
			PooledParticle pooledParticle = null;
			pooledParticle = ((!Enemy.IsCriticalHit(armorType)) ? onKillParticles : onCriticalHitKillParticles);
			if (pooledParticle == null)
			{
				pooledParticle = defaultKillParticles;
			}
			if (pooledParticle != null)
			{
				PooledParticle pooledParticle2 = ObjectPool.Instance.Acquire(pooledParticle);
				if (pooledParticle2 != null)
				{
					pooledParticle2.Play(impactPoint + impactSurfaceNormal * killParticleZBias, Quaternion.LookRotation(impactSurfaceNormal, Vector3.up));
				}
			}
		}

		public void StartCharge(Transform transform)
		{
			StopCharge();
			if (onChargeParticles != null)
			{
				chargeLoopingParticles = ObjectPool.Instance.Acquire(onChargeParticles);
				if (chargeLoopingParticles != null)
				{
					chargeLoopingParticles.Play(transform, loop: true);
				}
			}
		}

		public void StopCharge()
		{
			if (chargeLoopingParticles != null)
			{
				chargeLoopingParticles.Stop();
				chargeLoopingParticles = null;
			}
		}

		public void OnExplode()
		{
			if (onExplodeParticles != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(onExplodeParticles);
				if (pooledParticle != null)
				{
					pooledParticle.Play(base.transform.position, Quaternion.LookRotation(Vector3.up, Vector3.up));
				}
			}
		}

		public void OnAggro(Transform transform, Vector3 offset)
		{
			if (onAlertParticles != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(onAlertParticles);
				if (pooledParticle != null)
				{
					pooledParticle.Play(transform, offset, Quaternion.identity);
				}
			}
		}
	}
	public static class EnemySettings
	{
		public static EnemyConfig ConfigAsset = CustomSettingsLoader.LoadConfig<EnemyConfig>();

		private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

		public static string FullConfigAssetFilePath => CustomSettingsLoader.GetTrimmedFilePath("Assets/Core/Content/Configs/");

		public static string FullConfigAssetFileName => CustomSettingsLoader.GetAssetFileName<EnemyConfig>() + ".asset";

		public static string FullConfigAssetFilePathAndFileName => $"{FullConfigAssetFilePath}/{FullConfigAssetFileName}";

		public static void PreloadAssets()
		{
			foreach (object value in System.Enum.GetValues(typeof(EnemyType)))
			{
				string enemyPrefabName = GetEnemyPrefabName((EnemyType)value);
				if (!string.IsNullOrEmpty(enemyPrefabName) && !PhotonNetwork.PrefabCache.ContainsKey(enemyPrefabName))
				{
					PhotonNetwork.PrefabCache.Add(enemyPrefabName, Resources.Load<GameObject>(enemyPrefabName));
				}
			}
		}

		public static string GetEnemyPrefabName(EnemyType enemyType)
		{
			EnemyConfig.Config enemyConfig = GetEnemyConfig(enemyType);
			if (enemyConfig != null && enemyConfig.Prefab != null)
			{
				return enemyConfig.Prefab.name;
			}
			return null;
		}

		public static EnemyBehaviorType GetEnemyBehaviorType(EnemyType enemyType)
		{
			return GetEnemyConfig(enemyType)?.BehaviorType ?? EnemyBehaviorType.INVALID;
		}

		public static string GetEnemyDamageFriendlyNameString(EnemyType enemyType)
		{
			return GetEnemyConfig(enemyType)?.EnemyDamageFriendlyNameString;
		}

		public static int GetEnemyScore(EnemyType enemyType, out int minScore, out int maxScore)
		{
			minScore = (maxScore = 0);
			EnemyConfig.Config enemyConfig = GetEnemyConfig(enemyType);
			if (enemyConfig != null && enemyConfig.Prefab != null)
			{
				PointsDropper component = enemyConfig.Prefab.GetComponent<PointsDropper>();
				if (component != null)
				{
					minScore = component.MinDropValue;
					maxScore = component.MaxDropValue;
				}
			}
			return (minScore + maxScore) / 2;
		}

		public static float GetFlyingEnemySpawnHeight()
		{
			if (ConfigAsset != null)
			{
				return ConfigAsset.FlyingEnemySpawnHeight;
			}
			return 0f;
		}

		private static EnemyConfig.Config GetEnemyConfig(EnemyType enemyType)
		{
			if (ConfigAsset != null && ConfigAsset.Enemies != null && enemyType >= EnemyType.QUEST_GOBLIN_BASIC_GROUND_MELEE && (int)enemyType < ConfigAsset.Enemies.Length)
			{
				return ConfigAsset.Enemies[(int)enemyType];
			}
			return null;
		}
	}
}
public enum EnemySpawnerType
{
	CEILING,
	DOOR,
	IN_PLACE
}
[Serializable]
public class EnemySpawnerConfiguration
{
	[SerializeField]
	private EnemySpawnerType spawnerType = EnemySpawnerType.IN_PLACE;

	[SerializeField]
	private float ceilingSpawnHeight = 4f;

	[SerializeField]
	private Transform doorSpawnOrigin;

	public void GetBaseSpawnPositionAndRotation(Vector3 targetSpawnPosition, Quaternion targetSpawnRotation, out Vector3 baseSpawnPosition, out Quaternion baseSpawnRotation)
	{
		if (spawnerType == EnemySpawnerType.CEILING)
		{
			baseSpawnPosition = targetSpawnPosition + Vector3.up * ceilingSpawnHeight;
			baseSpawnRotation = targetSpawnRotation;
		}
		else if (spawnerType == EnemySpawnerType.DOOR && doorSpawnOrigin != null)
		{
			baseSpawnPosition = doorSpawnOrigin.position;
			Vector3 normalized = Vector3.ProjectOnPlane(targetSpawnPosition - baseSpawnPosition, Vector3.up).normalized;
			baseSpawnRotation = Quaternion.LookRotation(normalized, Vector3.up);
		}
		else
		{
			baseSpawnPosition = targetSpawnPosition;
			baseSpawnRotation = targetSpawnRotation;
		}
	}

	public void DrawGizmo(Vector3 spawnTargetPosition)
	{
		if (spawnerType != EnemySpawnerType.IN_PLACE)
		{
			GetBaseSpawnPositionAndRotation(spawnTargetPosition, Quaternion.identity, out var baseSpawnPosition, out var _);
			Gizmos.color = Color.white;
			Gizmos.DrawLine(baseSpawnPosition, spawnTargetPosition);
		}
	}
}
namespace RecRoom.Core.AI
{
	[RequireComponent(typeof(Enemy))]
	public class EnemyTeamColor : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private struct TeamColor
		{
			public GameTeam Team;

			public Color Color;
		}

		[Header("Renderer Configuration")]
		[SerializeField]
		private string materialColorName;

		[SerializeField]
		private Renderer[] renderers;

		[Header("Colors")]
		[SerializeField]
		private bool useAlternateColorElite;

		[Header("Override Activity Config Custom Team Colors")]
		[SerializeField]
		private TeamColor[] teamColors;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Enemy enemy;

		private MaterialPropertyBlock materialPropertyBlock;

		public bool HasValidTeam { get; private set; }

		public Color Color { get; private set; }

		private void Start()
		{
			HasValidTeam = enemy.Team != GameTeam.ANY;
			if (HasValidTeam && renderers != null && renderers.Length > 0)
			{
				Color = GetTeamColor(enemy.Team, useAlternateColorElite);
				materialPropertyBlock = new MaterialPropertyBlock();
				for (int i = 0; i < renderers.Length; i++)
				{
					renderers[i].GetPropertyBlock(materialPropertyBlock);
					materialPropertyBlock.SetColor(materialColorName, Color);
					renderers[i].SetPropertyBlock(materialPropertyBlock);
				}
			}
		}

		private Color GetTeamColor(GameTeam team, bool useAlternateColor)
		{
			for (int i = 0; i < teamColors.Length; i++)
			{
				if (teamColors[i].Team == team)
				{
					return teamColors[i].Color;
				}
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				return NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(team, useAlternateColorElite);
			}
			return GameTeamSettings.GetDefaultTeamColor(team);
		}
	}
}
