namespace RecRoom.Core.AI
{
	public abstract class EnemyBulletProjectileRangedWeapon : EnemyRangedWeapon
	{
		protected enum ProjectileType
		{
			BULLET,
			EQUIPMENT
		}

		[Header("Projectile")]
		[SerializeField]
		protected ProjectileType projectileType;

		[Header("Bullet Projectile")]
		[SerializeField]
		[FormerlySerializedAs("projectilePrefab")]
		protected Bullet bulletProjectilePrefab;

		[SerializeField]
		protected Color projectileColor = Color.white;

		[Header("Equipment Projectile")]
		[SerializeField]
		protected SpawnableToolType equipmentProjectileType;

		[Header("Projectile Physics")]
		[SerializeField]
		protected float projectileSpeed = 2f;

		[SerializeField]
		protected float projectileImpactForce = 50f;

		private const float SPAWNED_TOOL_ANGULAR_SPEED = 720f;

		private Color Color
		{
			get
			{
				if (thisEnemyTeamColor != null && thisEnemyTeamColor.HasValidTeam)
				{
					return thisEnemyTeamColor.Color;
				}
				return projectileColor;
			}
		}

		protected override float GetFireSpeed(float desiredSpeed)
		{
			return (!(desiredSpeed <= 0f)) ? desiredSpeed : projectileSpeed;
		}

		protected GameObject FireProjectile(Vector3 position, Vector3 direction, float speed)
		{
			if (projectileType == ProjectileType.BULLET)
			{
				return FireBullet(position, direction, speed);
			}
			if (projectileType == ProjectileType.EQUIPMENT && base.hasAuthority)
			{
				return AuthorityFireEquipment(position, direction, speed);
			}
			return null;
		}

		private GameObject FireBullet(Vector3 position, Vector3 direction, float speed)
		{
			Bullet bullet = AcquireBullet();
			if (bullet != null)
			{
				Vector3 initialVelocity = direction * speed;
				bullet.Fire(projectileOriginTransform.position, Quaternion.LookRotation(direction, Vector3.up), initialVelocity, projectileImpactForce, 1f, ignoredRigidbodies, null, 0);
				return bullet.gameObject;
			}
			return null;
		}

		private GameObject AuthorityFireEquipment(Vector3 position, Vector3 direction, float speed)
		{
			if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				Tool tool = NetworkedSingletonMonoBehaviour<GameManager>.Instance.SpawnManager.AuthoritySpawnEquipment(equipmentProjectileType, position, Quaternion.identity, 1f, -1, suppressAnimateInParticles: true, spawnIgnoringDynamicPhysics: true, suppressCleanup: true);
				if (tool != null)
				{
					Weapon component = tool.GetComponent<Weapon>();
					if (component != null)
					{
						component.Wielder = new Combatant(thisEnemy);
					}
					tool.RigidbodyEx.velocity = direction * speed;
					tool.RigidbodyEx.angularVelocity = UnityEngine.Random.onUnitSphere * 720f * ((float)Math.PI / 180f);
					return tool.gameObject;
				}
			}
			return null;
		}

		private Bullet AcquireBullet()
		{
			Bullet bullet = null;
			if (bulletProjectilePrefab != null)
			{
				bullet = ObjectPool.Instance.Acquire(bulletProjectilePrefab);
				if (bullet != null)
				{
					bullet.DestroyEvent += OnBulletDestroy;
					bullet.PlayerImpactEvent += OnBulletPlayerImpact;
					bullet.EnemyImpactEvent += OnBulletEnemyImpact;
					bullet.ToolImpactEvent += OnBulletToolImpact;
					bullet.OtherImpactEvent += OnBulletOtherImpact;
					bullet.Color = Color;
				}
			}
			return bullet;
		}

		protected virtual void OnBulletDestroy(Bullet projectile)
		{
			projectile.DestroyEvent -= OnBulletDestroy;
			projectile.PlayerImpactEvent -= OnBulletPlayerImpact;
			projectile.EnemyImpactEvent -= OnBulletEnemyImpact;
			projectile.ToolImpactEvent -= OnBulletToolImpact;
			projectile.OtherImpactEvent -= OnBulletOtherImpact;
		}

		protected virtual void OnBulletPlayerImpact(Bullet bullet, Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
			OnPlayerHit(player, bodyPart, impact);
			PlayImpactFeedback(impact);
		}

		protected virtual void OnBulletEnemyImpact(Bullet bullet, Enemy enemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			OnEnemyHit(enemy, armorType, impact);
			PlayImpactFeedback(impact);
		}

		protected virtual void OnBulletToolImpact(Bullet thisBullet, Tool hitTool, WeaponImpact impact)
		{
			OnPlayerToolHit(hitTool, impact);
			PlayImpactFeedback(impact);
		}

		protected virtual void OnBulletOtherImpact(Bullet thisBullet, WeaponImpact impact)
		{
			PlayImpactFeedback(impact);
		}

		protected void PlayImpactFeedback(WeaponImpact impact)
		{
			PlayParticles(projectileImpactParticlesPrefab, impact.Point, impact.SurfaceNormal);
			AudioManager.Play3DSFX(projectileImpactAudio, impact.Point);
			PlayImpactDecal(projectileImpactDecalPrefab, Color, impact.Point, impact.SurfaceNormal, impact.GameObject);
		}
	}
	public class EnemyProjectileMotionRangedWeapon : EnemyBulletProjectileRangedWeapon
	{
		[Header("Physics")]
		[SerializeField]
		private bool useLegacyProjectileMotionCalculation;

		[SerializeField]
		private float maxRange = 12f;

		[Header("Incoming Feedback")]
		[SerializeField]
		private float incomingAudioDuration = 1f;

		[SerializeField]
		private RecRoomAudioClip incomingAudio;

		[Header("Splash")]
		[SerializeField]
		private PooledParticle splashParticles;

		[SerializeField]
		private RecRoomAudioClip splashAudio;

		[SerializeField]
		private float splashRadius = 2f;

		private Explosive explosive = new Explosive();

		private GameObject lastBullet;

		private Coroutine incomingAudioCoroutine;

		private Player lastBulletBlockedPlayer;

		protected override void Awake()
		{
			base.Awake();
			explosive.PlayerImpactEvent += OnExplosivePlayerImpact;
			explosive.ToolImpactEvent += OnExplosiveToolImpact;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			explosive.PlayerImpactEvent -= OnExplosivePlayerImpact;
			explosive.ToolImpactEvent -= OnExplosiveToolImpact;
		}

		protected override void LocalFire(Vector3 target, float speed)
		{
			lastBulletBlockedPlayer = null;
			float totalLifetime = 0f;
			Vector3 zero = Vector3.zero;
			Vector3 vector = target - projectileOriginTransform.position;
			target = projectileOriginTransform.position + Vector3.ClampMagnitude(vector, maxRange);
			zero = ((!useLegacyProjectileMotionCalculation) ? UnityExtensions.GetProjectileMotionInitialVelocity(projectileOriginTransform.position, target, speed, out totalLifetime) : UnityExtensions.GetLegacyProjectileMotionInitialVelocity(projectileOriginTransform.position, target, maxRange, speed, out totalLifetime));
			lastBullet = FireProjectile(projectileOriginTransform.position, zero.normalized, zero.magnitude);
			this.SafeStopCoroutine(incomingAudioCoroutine);
			float duration = totalLifetime - incomingAudioDuration;
			incomingAudioCoroutine = this.WaitRoutine(duration, PlayIncomingAudio);
		}

		protected override void OnBulletDestroy(Bullet projectile)
		{
			base.OnBulletDestroy(projectile);
			this.SafeStopCoroutine(incomingAudioCoroutine);
			Vector3 position = projectile.transform.position;
			PlayParticles(splashParticles, position, Vector3.up);
			AudioManager.Play3DSFX(splashAudio, base.transform);
			explosive.Explode(position, splashRadius, projectileImpactForce, lastBulletBlockedPlayer);
		}

		protected override void OnBulletPlayerImpact(Bullet bullet, Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
		}

		protected override void OnBulletToolImpact(Bullet thisBullet, Tool hitTool, WeaponImpact impact)
		{
			if (hitTool.IsHeldByPlayer)
			{
				Weapon component = hitTool.GetComponent<Weapon>();
				if (component != null && component.IsShield)
				{
					lastBulletBlockedPlayer = hitTool.HolderPlayer;
				}
			}
		}

		protected override void OnBulletOtherImpact(Bullet thisBullet, WeaponImpact impact)
		{
		}

		private void OnExplosivePlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			OnPlayerHit(hitPlayer, hitBodyPart, impact);
		}

		private void OnExplosiveToolImpact(Tool hitTool, WeaponImpact impact)
		{
			OnPlayerToolHit(hitTool, impact);
		}

		private void PlayIncomingAudio()
		{
			if (lastBullet != null)
			{
				AudioManager.Play3DSFX(incomingAudio, lastBullet.transform);
			}
		}
	}
