		public void AuthorityFire(Vector3 target, float desiredSpeed = -1f, float shotDelay = 0f)
		{
			if (base.hasAuthority && TargetIsInVisionCone(target))
			{
				AuthorityUpdateShotOffsets(target);
				base.photonView.RpcAll(RpcOnFire, new Combatant(-1), target, shotTargetOffsets, desiredSpeed, shotDelay);
			}
		}

		public void AuthorityFire(Combatant target, float desiredSpeed = -1f, float shotDelay = 0f)
		{
			if (base.hasAuthority && target.IsValid && TargetIsInVisionCone(target.HeadPosition))
			{
				AuthorityUpdateShotOffsets(target.HeadPosition);
				base.photonView.RpcAll(RpcOnFire, target, Vector3.zero, shotTargetOffsets, desiredSpeed, shotDelay);
			}
		}

		public void StopFiring()
		{
			StopFireCoroutine();
		}

		private void AuthorityUpdateShotOffsets(Vector3 baseTarget)
		{
			if (base.hasAuthority)
			{
				if (shotTargetOffsets == null || shotTargetOffsets.Length != shotSettings.Length)
				{
					shotTargetOffsets = new Vector3[shotSettings.Length];
				}
				UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
				for (int i = 0; i < shotSettings.Length; i++)
				{
					ref Vector3 reference = ref shotTargetOffsets[i];
					reference = GetShotOffset(baseTarget, shotSettings[i].HitChance);
				}
			}
		}

		private bool TargetIsInVisionCone(Vector3 target)
		{
			Vector3 vector = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up);
			Vector3 to = Vector3.ProjectOnPlane(target - base.transform.position, Vector3.up);
			return vector.sqrMagnitude >= 0.001f && to.sqrMagnitude >= 0.001f && Vector3.Angle(vector, to) <= validShotVisionConeDegrees;
		}

		protected virtual Vector3 GetShotOffset(Vector3 baseTarget, float hitChance)
		{
			Vector3 up = Vector3.up;
			Vector3 normalized = Vector3.ProjectOnPlane(base.transform.position - baseTarget, Vector3.up).normalized;
			Vector3 vector = Vector3.Cross(up, normalized);
			Vector3 vector2 = targetOffset.x * vector + targetOffset.y * up + targetOffset.z * normalized;
			float f = UnityEngine.Random.Range(-1f, 1f);
			float num = Mathf.Lerp(minimumFireOffsetRotationAngle, maximumFireOffsetRotationAngle, Mathf.Abs(f));
			float angle = num * Mathf.Sign(f);
			Vector3 vector3 = Quaternion.AngleAxis(angle, -normalized) * up;
			float num2 = 0f;
			float num3 = 0f;
			if (hitChance != 0f && UnityEngine.Random.Range(0f, 1f) <= hitChance)
			{
				num2 = minimumFireHitDistance;
				num3 = maximumFireHitDistance;
			}
			else
			{
				num2 = minimumFireMissDistance;
				num3 = maximumFireMissDistance;
			}
			float num4 = UnityEngine.Random.Range(num2, num3);
			Vector3 vector4 = vector3 * num4;
			return vector2 + vector4;
		}

		private void OnFire(Combatant enemyTarget, Vector3 targetPoint, Vector3[] targetOffsets, float desiredSpeed, float shotDelay)
		{
			if (thisEnemy != null && thisEnemy.Health > 0 && thisEnemy.IsAlive)
			{
				StartFireCoroutine(enemyTarget, targetPoint, targetOffsets, desiredSpeed, shotDelay);
			}
		}

		protected abstract float GetFireSpeed(float desiredSpeed);

		protected abstract void LocalFire(Vector3 target, float desiredSpeed);

		private void StartFireCoroutine(Combatant enemyTarget, Vector3 targetPoint, Vector3[] targetOffsets, float desiredSpeed, float shotDelay)
		{
			StopFireCoroutine();
			fireCoroutine = StartCoroutine(FireCoroutine(enemyTarget, targetPoint, targetOffsets, desiredSpeed, shotDelay));
		}

		private void StopFireCoroutine()
		{
			if (fireCoroutine != null)
			{
				StopCoroutine(fireCoroutine);
				fireCoroutine = null;
			}
		}

		private IEnumerator FireCoroutine(Combatant enemyTarget, Vector3 targetPoint, Vector3[] targetOffsets, float desiredSpeed, float shotDelay)
		{
			float actualSpeed = GetFireSpeed(desiredSpeed);
			for (int i = 0; i < targetOffsets.Length; i++)
			{
				if (thisEnemy == null)
				{
					break;
				}
				if (thisEnemy.Health == 0)
				{
					break;
				}
				if (!thisEnemy.IsAlive)
				{
					break;
				}
				if (thisEnemy.IsStunned)
				{
					break;
				}
				Vector3 target = targetPoint;
				if (enemyTarget.IsValid)
				{
					target = ((!movingTargetExtrapolationEnabled) ? enemyTarget.HeadPosition : enemyTarget.GetExtrapolatedHeadPosition(ProjectileOriginTransform.position, actualSpeed));
				}
				target += targetOffsets[i];
				OnPreFire(shotDelay);
				if (shotDelay >= 0.001f)
				{
					float delayEndTime = UnityEngine.Time.time + shotDelay;
					while (UnityEngine.Time.time < delayEndTime)
					{
						yield return null;
					}
				}
				PlayFireFeedback(target);
				LocalFire(target, actualSpeed);
				if (targetOffsets.Length > 1)
				{
					yield return new WaitForSeconds(timeBetweenBurstShots);
				}
			}
			fireCoroutine = null;
		}

		protected void OnPlayerHit(Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
			if (this.PlayerHitEvent != null)
			{
				this.PlayerHitEvent(this, player, bodyPart, impact);
			}
		}

		protected void OnPlayerToolHit(Tool hitTool, WeaponImpact impact)
		{
			if (hitTool.IsHeld && this.PlayerToolHitEvent != null)
			{
				this.PlayerToolHitEvent(this, hitTool, impact);
			}
		}

		protected void OnEnemyHit(Enemy hitEnemy, EnemyArmorType hitArmorType, WeaponImpact impact)
		{
			if (hitEnemy != null && this.EnemyHitEvent != null)
			{
				this.EnemyHitEvent(this, hitEnemy, hitArmorType, impact);
			}
		}

		protected void OnPreFire(float shotDelay)
		{
			AudioManager.Play3DSFX(preFireAudio, projectileOriginTransform.position);
			if (this.LocalPreFireEvent != null)
			{
				this.LocalPreFireEvent(this, shotDelay);
			}
		}

		protected void PlayFireFeedback(Vector3 target)
		{
			Vector3 normalized = (target - projectileOriginTransform.position).normalized;
			PlayParticles(muzzleFlashParticlesPrefab, projectileOriginTransform.position, normalized);
			for (int i = 0; i < additionalMuzzleFlashParticles.Length; i++)
			{
				PlayParticles(additionalMuzzleFlashParticles[i].Particles, additionalMuzzleFlashParticles[i].Transform.position, additionalMuzzleFlashParticles[i].Transform.rotation);
			}
			AudioManager.PlayRandom3DSFX(fireAudio, projectileOriginTransform.position);
		}

		protected void PlayParticles(PooledParticle particleSystemPrefab, Vector3 point, Vector3 normal)
		{
			PlayParticles(particleSystemPrefab, point, Quaternion.LookRotation(normal));
		}

		protected void PlayParticles(PooledParticle particleSystemPrefab, Vector3 point, Quaternion rotation)
		{
			if (!(particleSystemPrefab != null))
			{
				return;
			}
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(particleSystemPrefab);
			pooledParticle.transform.position = point;
			pooledParticle.transform.rotation = rotation;
			if (thisEnemyTeamColor != null && thisEnemyTeamColor.HasValidTeam)
			{
				for (int i = 0; i < pooledParticle.AllParticleSystems.Length; i++)
				{
					ParticleSystem.MainModule main = pooledParticle.AllParticleSystems[i].main;
					main.startColor = thisEnemyTeamColor.Color;
				}
			}
			pooledParticle.Play();
		}

		protected void PlayImpactDecal(ImpactDecal decalPrefab, Color color, Vector3 point, Vector3 surfaceNormal, GameObject decalParent)
		{
			if (projectileImpactDecalPrefab != null)
			{
				ImpactDecal.Spawn(decalPrefab, color, point, surfaceNormal, decalParent);
			}
		}

		[PunRPC]
		protected void RpcOnFire(Combatant enemyTarget, Vector3 targetPoint, Vector3[] targetOffsets, float desiredSpeed, float shotDelay)
		{
			OnFire(enemyTarget, targetPoint, targetOffsets, desiredSpeed, shotDelay);
		}
	}
	public class EnemySingleShotRangedWeapon : EnemyBulletProjectileRangedWeapon
	{
		protected override void LocalFire(Vector3 target, float speed)
		{
			Vector3 normalized = (target - projectileOriginTransform.position).normalized;
			FireProjectile(projectileOriginTransform.position, normalized, speed);
		}
	}
	public class EnemySprayShotRangedWeapon : EnemyBulletProjectileRangedWeapon
	{
		[Header("Spray")]
		[SerializeField]
		private int projectileCount = 5;

		[SerializeField]
		private float totalSprayAngle = 25f;

		protected override void LocalFire(Vector3 target, float speed)
		{
			Vector3 normalized = (target - projectileOriginTransform.position).normalized;
			Vector3 normalized2 = Vector3.Cross(Vector3.up, normalized).normalized;
			Vector3 normalized3 = Vector3.Cross(normalized, normalized2).normalized;
			float num = totalSprayAngle / (float)(projectileCount - 1);
			int num2 = projectileCount / 2;
			float num3 = 0f;
			for (int i = num2; i < projectileCount; i++)
			{
				Vector3 normalized4 = (Quaternion.AngleAxis(num3, normalized3) * normalized).normalized;
				FireProjectile(projectileOriginTransform.position, normalized4, speed);
				num3 += num;
			}
			num3 = 0f - num;
			for (int num4 = num2 - 1; num4 >= 0; num4--)
			{
				Vector3 normalized5 = (Quaternion.AngleAxis(num3, normalized3) * normalized).normalized.normalized;
				FireProjectile(projectileOriginTransform.position, normalized5, speed);
				num3 -= num;
			}
		}
	}
}
public abstract class EnemyPatrol : Photon.MonoBehaviour
{
