	public abstract bool HasReachedTarget(Vector3 enemyPosition, Vector3 targetPosition);

	public abstract bool HasFinishedPatrol(int currentTargetId);

	public abstract bool TryGetNextTarget(int currentTargetId, out int nextTargetId, out Vector3 targetPosition);

	public abstract Vector3 GetGizmoPosition();
}
