[RequireComponent(typeof(PhotonView))]
public class EnemyPatrolNavMeshRegionPath : EnemyPatrol
{
	[SerializeField]
	private NavMeshRegion[] pathNodes;

	[SerializeField]
	private float nodeRadius = 0.5f;

	private static readonly Color REGION_GIZMO_COLOR = new Color(0.8f, 0.6f, 0f, 0.6f);

	private static readonly Color FINAL_REGION_GIZMO_COLOR = new Color(0.8f, 0f, 0.2f, 0.6f);

	public override bool HasReachedTarget(Vector3 enemyPosition, Vector3 targetPosition)
	{
		return (enemyPosition - targetPosition).sqrMagnitude <= nodeRadius * nodeRadius;
	}

	public override bool HasFinishedPatrol(int targetId)
	{
		return pathNodes == null;
	}

	public override bool TryGetNextTarget(int currentTargetId, out int nextTargetId, out Vector3 nextTargetPosition)
	{
		if (pathNodes == null || pathNodes.Length == 0)
		{
			nextTargetPosition = base.transform.position;
			nextTargetId = -1;
			return false;
		}
		int num = Mathf.Clamp(currentTargetId + 1, 0, pathNodes.Length - 1);
		if (pathNodes[num].TryGetRandomPoint(out nextTargetPosition))
		{
			nextTargetId = num;
			return true;
		}
		nextTargetId = currentTargetId;
		return false;
	}

	public override Vector3 GetGizmoPosition()
	{
		if (pathNodes != null && pathNodes.Length > 0 && pathNodes[0] != null)
		{
			return pathNodes[0].transform.position;
		}
		return base.transform.position;
	}

	private void OnDrawGizmos()
	{
		if (pathNodes == null || pathNodes.Length == 0)
		{
			return;
		}
		if (pathNodes.Length == 1 && pathNodes[0] != null)
		{
			pathNodes[0].DrawGizmos(REGION_GIZMO_COLOR);
			return;
		}
		int num = -1;
		int num2 = -1;
		int num3 = pathNodes.Length - 1;
		for (int i = 0; i < num3; i++)
		{
			num = i;
			num2 = (num + 1) % pathNodes.Length;
			NavMeshRegion navMeshRegion = pathNodes[num];
			NavMeshRegion navMeshRegion2 = pathNodes[num2];
			if (!(navMeshRegion == null) && !(navMeshRegion2 == null))
			{
				Gizmos.color = Color.red;
				GizmoExtensions.DrawGizmoArrow(pathNodes[num].transform.position, pathNodes[num2].transform.position);
				pathNodes[num].DrawGizmos(REGION_GIZMO_COLOR);
			}
		}
		if (num2 >= 0 && num2 < pathNodes.Length)
		{
			pathNodes[num2].DrawGizmos(FINAL_REGION_GIZMO_COLOR);
		}
	}

	private void DrawPathNodeGizmo(NavMeshRegion start, NavMeshRegion end)
	{
		Gizmos.color = Color.red;
		GizmoExtensions.DrawGizmoArrow(start.transform.position, end.transform.position);
		start.DrawGizmos(REGION_GIZMO_COLOR);
	}
}
[RequireComponent(typeof(PhotonView))]
public class EnemyPatrolPath : EnemyPatrol
{
	[SerializeField]
	private Transform[] pathNodes;

	[SerializeField]
	private float nodeRadius = 0.25f;

	[SerializeField]
	private bool loop;

	public override bool HasReachedTarget(Vector3 enemyPosition, Vector3 targetPosition)
	{
		return (enemyPosition - targetPosition).sqrMagnitude <= nodeRadius * nodeRadius;
	}

	public override bool HasFinishedPatrol(int targetId)
	{
		return pathNodes == null || (!loop && targetId >= pathNodes.Length);
	}

	public override bool TryGetNextTarget(int currentTargetId, out int nextTargetId, out Vector3 nextTargetPosition)
	{
		nextTargetPosition = Vector3.zero;
		nextTargetId = -1;
		if (pathNodes == null || pathNodes.Length == 0)
		{
			return false;
		}
		if (loop)
		{
			nextTargetId = (currentTargetId + 1) % pathNodes.Length;
			nextTargetPosition = pathNodes[nextTargetId].position;
			return true;
		}
		nextTargetId = currentTargetId + 1;
		if (nextTargetId < pathNodes.Length)
		{
			nextTargetPosition = pathNodes[nextTargetId].position;
			return true;
		}
		return false;
	}

	public override Vector3 GetGizmoPosition()
	{
		if (pathNodes != null && pathNodes.Length > 0)
		{
			return pathNodes[0].position;
		}
		return base.transform.position;
	}

	private void OnDrawGizmos()
	{
		if (pathNodes != null && pathNodes.Length != 0)
		{
			int num = ((!loop) ? (pathNodes.Length - 1) : pathNodes.Length);
			for (int i = 0; i < num; i++)
			{
				int num2 = i;
				int num3 = (num2 + 1) % pathNodes.Length;
				DrawPathNodeGizmo(pathNodes[num2].position, pathNodes[num3].position, num3 != 0);
			}
		}
	}

	private void DrawPathNodeGizmo(Vector3 start, Vector3 end, bool drawEndGizmo)
	{
		Gizmos.color = Color.red;
		GizmoExtensions.DrawGizmoArrow(start, end);
		if (drawEndGizmo)
		{
			Gizmos.DrawWireCube(end, Vector3.one * nodeRadius);
		}
	}
}
[RequireComponent(typeof(NavMeshRegion))]
public class EnemySpawnNavMeshRegion : UnityEngine.MonoBehaviour
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private NavMeshRegion region;

	[SerializeField]
	private float maxRandomSpawnAngleFromForward = 30f;

	private static readonly Color GIZMO_WEDGE_MAIN_COLOR = new Color(0f, 1f, 0f, 1f);

	private static readonly Color GIZMO_WEDGE_SECONDARY_COLOR = new Color(0f, 0.3f, 0.8f, 1f);

	private static readonly Color REGION_GIZMO_COLOR = new Color(0.13f, 0.84f, 0.94f, 0.4f);

	public Vector3 TopCenterPosition => region.transform.position + region.transform.up * region.Height / 2f;

	public bool TryGetSpawnPositionAndRotation(out Vector3 position, out Quaternion rotation)
	{
		if (!region.TryGetRandomPoint(out position))
		{
			rotation = Quaternion.identity;
			return false;
		}
		Vector3 normalized = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
		float angle = UnityEngine.Random.Range(0f - maxRandomSpawnAngleFromForward, maxRandomSpawnAngleFromForward);
		rotation = Quaternion.AngleAxis(angle, Vector3.up) * Quaternion.LookRotation(normalized);
		return true;
	}
}
public class NavMeshRegion : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Vector3 size = Vector3.one;

	[Header("Search Settings")]
	[SerializeField]
	private float agentRadius = 0.4f;

	[SerializeField]
	private float agentHeight = 2f;

	[SerializeField]
	private int maxRetryCount = 5;

	public float Height => base.transform.lossyScale.y * size.y;

	public bool TryGetRandomPoint(out Vector3 position)
	{
		bool result = false;
		position = Vector3.zero;
		float maxDistance = Height / 2f;
		for (int i = 0; i < maxRetryCount; i++)
		{
			if (TryGetRandomPointInternal(maxDistance, out var navMeshPoint) && !IsOverlappingDynamicObjects(navMeshPoint))
			{
				result = true;
				position = navMeshPoint;
				break;
			}
		}
		return result;
	}

	private bool TryGetRandomPointInternal(float maxDistance, out Vector3 navMeshPoint)
	{
		Vector3 position = new Vector3(UnityEngine.Random.Range(-0.5f, 0.5f) * size.x, 0f, UnityEngine.Random.Range(-0.5f, 0.5f) * size.z);
		Vector3 sourcePosition = base.transform.TransformPoint(position);
		if (NavMesh.SamplePosition(sourcePosition, out var hit, maxDistance, -1))
		{
			navMeshPoint = hit.position;
			return true;
		}
		navMeshPoint = Vector3.zero;
		return false;
	}

	private bool IsOverlappingDynamicObjects(Vector3 navMeshPosition)
	{
		Vector3 start = navMeshPosition + Vector3.up * agentRadius;
		Vector3 end = navMeshPosition + Vector3.up * (agentHeight - agentRadius);
		return Physics.CheckCapsule(start, end, agentRadius, 496383488);
	}

	public void DrawGizmos(Color color)
	{
		Gizmos.color = color;
		Gizmos.matrix = base.transform.localToWorldMatrix;
		Gizmos.DrawCube(Vector3.zero, size);
		Gizmos.matrix = Matrix4x4.identity;
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(PhotonView))]
public class NetworkEnemyHeadRotation : Photon.MonoBehaviour, IPunObservable
{
	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (!stream.isReading || info.sender == base.authority)
		{
			if (stream.isWriting)
			{
				stream.SendNext(base.transform.rotation);
			}
			else
			{
				base.transform.rotation = (Quaternion)stream.ReceiveNext();
			}
		}
	}
}
public class Trap : Photon.MonoBehaviour
{
	[Header("Quest Trap")]
	[SerializeField]
	protected int playerDamage = 1;

	[SerializeField]
	protected int enemyDamage = 1000;

	[Header("No-KO traps")]
	[SerializeField]
	protected List<SceneSpawnPoint> customSpawnPoints;

	[SerializeField]
	protected bool penalizePlayerWithoutKO;

	[SerializeField]
	protected string damageVerb;

	protected Animator animator;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	protected RigidbodyEx rigidbodyEx;

	protected TrapCollider[] colliders;

	private SynchronizedField<bool> _isEnabled;

	protected Vector3 spawnPosition = Vector3.zero;

	protected Quaternion spawnRotation = Quaternion.identity;

	public int PlayerDamage => playerDamage;

	public RigidbodyEx RigidbodyEx => rigidbodyEx;

	public bool IsEnabled
	{
		get
		{
			return _isEnabled.Get();
		}
		private set
		{
			_isEnabled.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		animator = GetComponentInChildren<Animator>();
		_isEnabled = new SynchronizedField<bool>(this, "ENABLED", defaultValue: true, SetterPermissionMode.MASTER, OnIsEnabledChange);
		spawnPosition = base.transform.localPosition;
		spawnRotation = base.transform.localRotation;
		colliders = GetComponentsInChildren<TrapCollider>(includeInactive: true);
		TrapCollider[] array = colliders;
		foreach (TrapCollider trapCollider in array)
		{
			trapCollider.ThisTrap = this;
		}
	}

	protected virtual void Start()
	{
		OnIsEnabledChange();
	}

	public void MasterDisable()
	{
		if (PhotonNetwork.isMasterClient)
		{
			IsEnabled = false;
		}
	}

	public virtual void MasterResetToSpawnPoint()
	{
		if (PhotonNetwork.isMasterClient)
		{
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (rigidbodyEx != null)
			{
				rigidbodyEx.ClearVelocity();
			}
			base.transform.localPosition = spawnPosition;
			base.transform.localRotation = spawnRotation;
			IsEnabled = true;
		}
	}

	protected virtual void OnIsEnabledChange()
	{
		base.gameObject.SetActive(IsEnabled);
	}

	public virtual void AuthorityApplyDamage(WeaponDamageType damageType, int damage, Vector3 point, Vector3 normal)
	{
	}

	public virtual void AuthorityOnDamageApplyForce(WeaponDamageType damageType, Vector3 force, Vector3 point)
	{
		if (base.hasAuthority && rigidbodyEx != null)
		{
			rigidbodyEx.AddForceAtPosition(force, point, ForceMode.Impulse);
		}
	}

	public void AuthorityClearVelocity()
	{
		if (base.hasAuthority && rigidbodyEx != null)
		{
			rigidbodyEx.ClearVelocity();
		}
	}

	public virtual void AuthorityOnDamageChangeVelocity(WeaponDamageType damageType, Vector3 velocity, Vector3 angularVelocity)
	{
		if (base.hasAuthority && rigidbodyEx != null)
		{
			rigidbodyEx.velocity = velocity;
			rigidbodyEx.angularVelocity = angularVelocity;
		}
	}

	public virtual void LocalPlayerCustomRespawn()
	{
		if (!Player.LocalPlayer.IsSpawning)
		{
			customSpawnPoints.Sort(SceneSpawnPoint.Comparer);
			SceneSpawnPoint sceneSpawnPoint = customSpawnPoints[Player.LocalPlayer.PhotonPlayer.ID % customSpawnPoints.Count];
			Player.LocalPlayer.Respawn(sceneSpawnPoint.WorldPosition, sceneSpawnPoint.WorldRotation, null, dropTools: false);
			if (PlayerDamage == 0 && penalizePlayerWithoutKO)
			{
				QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
				questManager?.PenalizePlayer(Player.LocalPlayer.PhotonPlayer, QuestManager.HealthChangeType.Trap);
				questManager?.PlayDeathPenaltyNotification(QuestManager.HealthChangeType.Trap, damageVerb, "It's a Trap!");
				questManager?.PlayPlayerHitFx(Player.LocalPlayer.PhotonPlayer, Player.LocalPlayer.transform.position);
			}
		}
	}

	protected void ToolHit(Tool tool, WeaponImpact impact)
	{
		if (tool.IsHeldByPlayer && tool.HolderPlayer.isLocal && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.LocalRequestMiscPlayerToolDamage(tool, impact.Point);
			if (customSpawnPoints != null && customSpawnPoints.Count > 0)
			{
				LocalPlayerCustomRespawn();
			}
		}
		else if (!tool.IsHeld && base.hasAuthority)
		{
			tool.ApplyAttackAndTryTakeOwnership(null, WeaponDamageType.DEFAULT, impact.Point);
			if (tool.hasAuthority)
			{
				tool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Force);
			}
		}
	}

	protected void PlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
	{
		if (hitPlayer.isLocal && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.LocalRequestMiscPlayerDamage(hitBodyPart, impact.Point, PlayerDamage);
			if (customSpawnPoints != null && customSpawnPoints.Count > 0)
			{
				LocalPlayerCustomRespawn();
			}
		}
	}

	protected void EnemyHit(Enemy enemy, EnemyArmorType enemyArmorType, WeaponDamageType damageType, WeaponImpact impact)
	{
		if (base.hasAuthority)
		{
			if (!enemy.hasAuthority)
			{
				enemy.TransferOwnership(PhotonNetwork.player);
			}
			enemy.AuthorityTryApplyAttack(base.authority, null, damageType, enemyArmorType, enemyDamage, impact);
			enemy.AuthorityOnDamageApplyForce(damageType, enemyArmorType, impact.Force, impact.Point);
		}
	}

	protected void TrapHit(Trap hitTrap, WeaponDamageType damageType, WeaponImpact impact)
	{
		if (!(hitTrap == this))
		{
			if (base.hasAuthority && !hitTrap.hasAuthority)
			{
				hitTrap.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (hitTrap.hasAuthority)
			{
				hitTrap.AuthorityApplyDamage(damageType, enemyDamage, impact.Point, impact.SurfaceNormal);
			}
		}
	}
}
