namespace RecRoom.Core.Imposters
{
	public class HideInImposter : UnityEngine.MonoBehaviour
	{
	}
	public interface ICustomImposterBehavior
	{
		void PrepareImposter(ImposterParameters parameters);
	}
	public struct ImposterParameters
	{
		public GameTeam teamOverride;

		public Color colorOverride;

		public EquipmentSkin skinOverride;
	}
	public static class VisualImposter
	{
		private static readonly System.Type[] IMPOSTER_COMPONENT_TYPES = new System.Type[8]
		{
			typeof(Transform),
			typeof(RectTransform),
			typeof(MeshRenderer),
			typeof(MeshFilter),
			typeof(SkinnedMeshRenderer),
			typeof(CanvasRenderer),
			typeof(SpriteRenderer),
			typeof(UnityEngine.UI.Image)
		};

		private static readonly System.Type[] DESTROY_OBJECT_COMPONENT_TYPES = new System.Type[9]
		{
			typeof(HideInImposter),
			typeof(PulsingBeam),
			typeof(WeaponFlashlight),
			typeof(ToolMenuProjector),
			typeof(CircuitInputConnectionPoint),
			typeof(CircuitOutputConnectionPoint),
			typeof(Canvas),
			typeof(Camera),
			typeof(PostProcessLayer)
		};

		private static Transform disabledRoot;

		public static GameObject SpawnImposter(SpawnableToolType toolType, Transform parent, EquipmentSkin skin = null, bool preserveColliders = false)
		{
			GameObject gameObject = null;
			GameObject gameObject2 = SpawnableToolSettings.GetSpawnableToolPrefab(toolType).gameObject;
			if (gameObject2 != null)
			{
				ImposterParameters parameters = new ImposterParameters
				{
					teamOverride = SpawnableToolSettings.GetSpawnableToolTeamOverride(toolType),
					colorOverride = SpawnableToolSettings.GetSpawnableToolColorOverride(toolType),
					skinOverride = skin
				};
				gameObject = SpawnImposter(gameObject2.gameObject, parent, parameters, preserveColliders);
				SpawnableToolConfig.Config spawnableToolConfig = SpawnableToolSettings.GetSpawnableToolConfig(toolType);
				if (spawnableToolConfig != null)
				{
					gameObject.transform.localEulerAngles = spawnableToolConfig.SpawnRotation;
				}
			}
			else
			{
				UnityEngine.Debug.LogError($"Unable to spawn imposter for tool {toolType}");
			}
			return gameObject;
		}

		public static GameObject SpawnImposter(GameObject prefab, Transform parent, bool preserveColliders = false)
		{
			return SpawnImposter(prefab, parent, default(ImposterParameters), preserveColliders);
		}

		public static GameObject SpawnImposter(GameObject prefab, Transform parent, ImposterParameters parameters, bool preserveColliders)
		{
			if (disabledRoot == null)
			{
				disabledRoot = new GameObject("DisabledImposterRoot").transform;
				disabledRoot.gameObject.hideFlags = HideFlags.HideAndDontSave;
				disabledRoot.gameObject.SetActive(value: false);
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab, disabledRoot).gameObject;
			gameObject.name = $"{prefab.name} (Imposter)";
			PrepareImposterComponents(gameObject, parameters, preserveColliders);
			gameObject.transform.SetParent(parent);
			return gameObject;
		}

		private static void PrepareImposterComponents(GameObject gameObject, ImposterParameters parameters, bool preserveColliders)
		{
			UnityEngine.MonoBehaviour[] componentsInChildren = gameObject.GetComponentsInChildren<UnityEngine.MonoBehaviour>(includeInactive: true);
			UnityEngine.MonoBehaviour[] array = componentsInChildren;
			foreach (UnityEngine.MonoBehaviour component in array)
			{
				RemoveNonImposterComponent(component, parameters, preserveColliders);
			}
			UnityEngine.Component[] componentsInChildren2 = gameObject.GetComponentsInChildren<UnityEngine.Component>(includeInactive: true);
			UnityEngine.Component[] array2 = componentsInChildren2;
			foreach (UnityEngine.Component component2 in array2)
			{
				RemoveNonImposterComponent(component2, parameters, preserveColliders);
			}
		}

		private static void RemoveNonImposterComponent(UnityEngine.Component component, ImposterParameters parameters, bool preserveColliders)
		{
			if (!(component != null))
			{
				return;
			}
			System.Type type = component.GetType();
			if (component is Collider && preserveColliders)
			{
				return;
			}
			if (component is ICustomImposterBehavior customImposterBehavior)
			{
				customImposterBehavior.PrepareImposter(parameters);
			}
			if (DESTROY_OBJECT_COMPONENT_TYPES.Contains(type))
			{
				UnityEngine.Object.DestroyImmediate(component.gameObject);
				return;
			}
			LODGroup lODGroup = component as LODGroup;
			if (lODGroup != null)
			{
				LOD[] lODs = lODGroup.GetLODs();
				for (int i = 1; i < lODs.Length; i++)
				{
					Renderer[] renderers = lODs[i].renderers;
					foreach (Renderer renderer in renderers)
					{
						if (renderer != null && !lODs[0].renderers.Contains(renderer))
						{
							MeshFilter component2 = renderer.GetComponent<MeshFilter>();
							if (component2 != null)
							{
								UnityEngine.Object.DestroyImmediate(component2);
							}
							UnityEngine.Object.DestroyImmediate(renderer);
						}
					}
				}
			}
			if (!IMPOSTER_COMPONENT_TYPES.Contains(type))
			{
				UnityEngine.Object.DestroyImmediate(component);
			}
		}
	}
}
