	[Serializable]
	public class DebugVRInputHandler : VRInputHandler
	{
		[Serializable]
		private class Map
		{
			public int PickupMouseButton;

			public int TriggerMouseButton;

			public KeyCode MenuKey;

			public KeyCode TeleportKey;

			public KeyCode PushToTalkKey;

			public KeyCode RotateLeftKey;

			public KeyCode RotateRightKey;

			public KeyCode RotateDownKey;

			public KeyCode RotateUpKey;

			public KeyCode SprintKey;

			public KeyCode FlyModeModifierButton;
		}

		[SerializeField]
		private Map map;

		[SerializeField]
		private Vector3 cameraOffset = new Vector3(0.25f, -0.25f, 0.5f);

		public DebugVRInputHandler()
		{
			base.IsAimWalkCapable = false;
		}

		public override void Attach()
		{
			base.Attach();
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				DebugCameraControl component = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.gameObject.GetComponent<DebugCameraControl>();
				if (component == null)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.gameObject.AddComponent<DebugCameraControl>();
				}
			}
		}

		public override void Detach()
		{
			base.Detach();
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				DebugCameraControl component = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.gameObject.GetComponent<DebugCameraControl>();
				if (component != null)
				{
					UnityEngine.Object.Destroy(component);
				}
			}
		}

		protected override void ReadInputState(ref State state)
		{
			if (!DebugConsole.HasFocus)
			{
				if (KeyboardInputField.FocusedInputField == null)
				{
					state.FlyModeModifierButton = Button.ReadKey(map.FlyModeModifierButton);
					state.MenuButton = Button.ReadKey(map.MenuKey);
					state.PushToTalkButton = Button.ReadKey(map.PushToTalkKey);
					state.RotateLeftButton = Button.ReadKey(map.RotateLeftKey);
					state.RotateRightButton = Button.ReadKey(map.RotateRightKey);
					state.SprintButton = Button.ReadKey(map.SprintKey);
					state.TeleportButton = Button.ReadKey(map.TeleportKey);
					state.RotateDownButton = Button.ReadKey(map.RotateDownKey);
					state.WalkAxis = new Vector2(Input.GetAxisRaw("Movement Right"), Input.GetAxisRaw("Movement Forward"));
					state.RCControlStickAxis = new Vector2(Input.GetKey(KeyCode.J) ? (-1) : (Input.GetKey(KeyCode.L) ? 1 : 0), Input.GetKey(KeyCode.K) ? (-1) : (Input.GetKey(KeyCode.I) ? 1 : 0));
				}
				base.IsTracking = true;
				base.IsConnected = true;
				UpdateDebugTransform();
				state.PickupAxis.Value = ((!Input.GetMouseButton(map.PickupMouseButton)) ? 0f : 1f);
				state.TriggerAxis.Value = (Input.GetMouseButton(map.TriggerMouseButton) ? 1 : 0);
				state.TriggerPressureValue = state.TriggerAxis.Value;
			}
		}

		private void UpdateDebugTransform()
		{
			if (!(SingletonMonoBehaviour<CameraRig>.Instance == null) && !(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera == null))
			{
				rawTrackerTransform.position = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.TransformPoint(cameraOffset);
				rawTrackerTransform.rotation = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.rotation;
				float num = UnityEngine.Time.time - base.previousPoseTime;
				Vector3 vector = (rawTrackerTransform.localPosition - base.previousRawLocalPosePosition) / num;
				base.LinearVelocity = rawTrackerTransform.parent.TransformVector(vector) * base.LinearVelocityMultiplier;
				Vector3 vector2 = UnityExtensions.AngularDisplacementFromTo(base.previousRawLocalPoseRotation, rawTrackerTransform.localRotation) / num;
				base.AngularVelocity = rawTrackerTransform.parent.TransformVector(vector2) * base.AngularVelocityMultiplier;
				OnTransformUpdated();
			}
		}
	}
