	public class OculusPlatformOculusTouchVRInputConfiguration : VRInputConfiguration<OculusPlatformOculusTouchVRInputHandler>
	{
	}
	[Serializable]
	public class OculusPlatformOculusTouchVRInputHandler : VRInputHandler
	{
		[Serializable]
		private class Map
		{
			public OVRInput.Axis1D[] PickupAxes = new OVRInput.Axis1D[2]
			{
				OVRInput.Axis1D.PrimaryHandTrigger,
				OVRInput.Axis1D.PrimaryIndexTrigger
			};

			public OVRInput.Axis1D TriggerAxis = OVRInput.Axis1D.PrimaryIndexTrigger;

			public OVRInput.Button MenuButton = OVRInput.Button.Two;

			public OVRInput.Button TeleportButton = OVRInput.Button.One;

			public OVRInput.Button SprintButton = OVRInput.Button.PrimaryThumbstick;

			public OVRInput.Button PushToTalkButton = OVRInput.Button.PrimaryThumbstick;

			public OVRInput.Button SmoothRotateButton = OVRInput.Button.PrimaryThumbstick;

			public OVRInput.Button AlternateSmoothRotateButton = OVRInput.Button.One;

			public OVRInput.Button FlyModeModifierButton = OVRInput.Button.PrimaryHandTrigger;

			public OVRInput.Axis2D RotateAxis = OVRInput.Axis2D.PrimaryThumbstick;

			public OVRInput.Axis2D WalkAxis = OVRInput.Axis2D.PrimaryThumbstick;

			public OVRInput.Axis2D SmoothSwipeRotateAxis = OVRInput.Axis2D.PrimaryThumbstick;

			public OVRInput.Button RCMainButton = OVRInput.Button.PrimaryHandTrigger;

			public Axis2DSettings RotateAxisSettings;

			public Axis2DSettings WalkAxisSettings;

			public Axis2DSettings SmoothSwipeRotateAxisSettings;

			public AxisSettings TriggerSettings;

			public AxisPressButtons ThumbstickDirectionButtons;
		}

		[SerializeField]
		private Map map;

		private const int OCULUS_HAPTIC_SAMPLE_BUFFER_SIZE = 10;

		private OVRHapticsClip _oculusHapticsClip;

		private bool teleportWasPressed;

		private OVRHapticsClip OculusHapticsClip
		{
			get
			{
				if (_oculusHapticsClip == null)
				{
					_oculusHapticsClip = new OVRHapticsClip();
					OVRHaptics.OVRHapticsChannel oVRHapticsChannel = ((base.HandType != VRTrackedController.HandType.LeftHand) ? OVRHaptics.RightChannel : OVRHaptics.LeftChannel);
					oVRHapticsChannel.Preempt(OculusHapticsClip);
				}
				return _oculusHapticsClip;
			}
		}

		private string SantaCruzTriggerAxis => (base.HandType != VRTrackedController.HandType.RightHand) ? "SantaCruzLTrigger" : "SantaCruzRTrigger";

		private string SantaCruzMenuButtonAxis => (base.HandType != VRTrackedController.HandType.RightHand) ? "SantaCruzLBackButton" : "SantaCruzRBackButton";

		private string SantaCruzTeleportButtonAxis => (base.HandType != VRTrackedController.HandType.RightHand) ? "SantaCrusLPadButton" : "SantaCruzRPadButton";

		public OculusPlatformOculusTouchVRInputHandler()
		{
			base.SimultaneouslySupportsAimAndThumbstickWalk = true;
		}

		public override void Attach()
		{
			base.Attach();
			OVRManager.NewPosesEvent += OnNewPoses;
		}

		public override void Detach()
		{
			base.Detach();
			OVRManager.NewPosesEvent -= OnNewPoses;
		}

		private void OnNewPoses()
		{
			OVRPlugin.Node nodeId = ((base.HandType != VRTrackedController.HandType.LeftHand) ? OVRPlugin.Node.HandRight : OVRPlugin.Node.HandLeft);
			base.IsConnected = OVRPlugin.GetNodePresent(nodeId);
			if (!base.IsConnected)
			{
				base.IsTracking = false;
				return;
			}
			OVRInput.Controller controllerType = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			base.IsTracking = OVRInput.GetControllerPositionTracked(controllerType) && OVRInput.GetControllerOrientationTracked(controllerType);
			Vector3 localControllerPosition = OVRInput.GetLocalControllerPosition(controllerType);
			rawTrackerTransform.localPosition = localControllerPosition;
			Quaternion localControllerRotation = OVRInput.GetLocalControllerRotation(controllerType);
			rawTrackerTransform.localRotation = localControllerRotation;
			Vector3 localControllerVelocity = OVRInput.GetLocalControllerVelocity(controllerType);
			base.LinearVelocity = rawTrackerTransform.parent.TransformVector(localControllerVelocity) * base.LinearVelocityMultiplier;
			float num = UnityEngine.Time.time - base.previousPoseTime;
			Vector3 vector = UnityExtensions.AngularDisplacementFromTo(base.previousRawLocalPoseRotation, rawTrackerTransform.localRotation) / num;
			base.AngularVelocity = rawTrackerTransform.parent.TransformVector(vector) * base.AngularVelocityMultiplier;
			OnTransformUpdated();
		}

		protected override void ReadInputState(ref State state)
		{
			if (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareType == PlatformManager.HardwareType.SANTA_CRUZ)
			{
				state.TriggerAxis.Value = Input.GetAxis(SantaCruzTriggerAxis);
				state.PickupAxis.Value = Input.GetAxis(SantaCruzTriggerAxis);
				state.MenuButton = Button.ReadKey(KeyCode.Escape);
				state.TeleportButton.Pressed = !Mathf.Approximately(Input.GetAxis(SantaCruzTeleportButtonAxis), 0f);
				state.TeleportButton.Down = state.TeleportButton.Pressed && !teleportWasPressed;
				state.TeleportButton.Up = !state.TeleportButton.Pressed && teleportWasPressed;
				teleportWasPressed = state.TeleportButton.Pressed;
			}
			else
			{
				state.MenuButton = ReadButton(map.MenuButton);
				state.TeleportButton = ReadButton(map.TeleportButton);
				state.PushToTalkButton = ReadButton(map.PushToTalkButton);
				state.GripRotateButton = ReadButton(map.SmoothRotateButton);
				state.AlternateGripRotateButton = ReadButton(map.AlternateSmoothRotateButton);
				state.FlyModeModifierButton = ReadButton(map.FlyModeModifierButton);
				state.SmoothSwipeRotateAxis = ReadAxis2D(map.SmoothSwipeRotateAxis, map.SmoothSwipeRotateAxisSettings);
				state.TeleportRotateAxis = ReadAxis2D(map.RotateAxis, map.RotateAxisSettings);
				state.WalkAxis = ReadAxis2D(map.WalkAxis, map.WalkAxisSettings);
				state.SprintButton = ReadButton(map.SprintButton);
				bool inDeadZone = state.TeleportRotateAxis.sqrMagnitude < Mathf.Epsilon;
				map.ThumbstickDirectionButtons.Update(state.TeleportRotateAxis, inDeadZone);
				state.RotateRightButton = Button.ReadAxisButton(map.ThumbstickDirectionButtons, AxisButtons.Direction.RIGHT);
				state.RotateLeftButton = Button.ReadAxisButton(map.ThumbstickDirectionButtons, AxisButtons.Direction.LEFT);
				state.RotateDownButton = Button.ReadAxisButton(map.ThumbstickDirectionButtons, AxisButtons.Direction.DOWN);
				state.PickupAxis = ReadAxis(map.PickupAxes);
				state.TriggerAxis = ReadAxis(map.TriggerAxis);
				state.RCTriggerAxis = ReadAxis(map.TriggerAxis);
				state.RCControlStickAxis = ReadAxis2D(map.RotateAxis, map.RotateAxisSettings);
				state.RCMainButton = ReadButton(map.RCMainButton);
			}
			state.TriggerPressureValue = AxisSettings.ProcessValue(state.TriggerAxis.Value, map.TriggerSettings);
		}

		protected override void PulseHapticsFrame(float intensity, bool useTouchpad)
		{
			base.PulseHapticsFrame(intensity, useTouchpad);
			int num = 10 - OculusHapticsClip.Count;
			int num2 = OculusHapticsClip.Count % 2;
			byte b = (byte)Mathf.Lerp(0f, 255f, intensity);
			for (int i = 0; i < num; i++)
			{
				OculusHapticsClip.WriteSample((byte)(b * ((i + num2) % 2)));
			}
			OVRHaptics.OVRHapticsChannel oVRHapticsChannel = ((base.HandType != VRTrackedController.HandType.LeftHand) ? OVRHaptics.RightChannel : OVRHaptics.LeftChannel);
			oVRHapticsChannel.Preempt(OculusHapticsClip);
		}

		protected Button ReadButton(OVRInput.Button key)
		{
			OVRInput.Controller controllerMask = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			return new Button
			{
				Pressed = OVRInput.Get(key, controllerMask),
				Down = OVRInput.GetDown(key, controllerMask),
				Up = OVRInput.GetUp(key, controllerMask)
			};
		}

		protected Button ReadButton(OVRInput.Button[] keys)
		{
			OVRInput.Controller controllerMask = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			Button result = default(Button);
			foreach (OVRInput.Button virtualMask in keys)
			{
				result.Pressed |= OVRInput.Get(virtualMask, controllerMask);
				result.Down |= OVRInput.GetDown(virtualMask, controllerMask);
				result.Up |= OVRInput.GetUp(virtualMask, controllerMask);
			}
			return result;
		}

		protected Axis ReadAxis(OVRInput.Axis1D key, float deadzone = 0f)
		{
			OVRInput.Controller controllerMask = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			return new Axis
			{
				Value = OVRInput.Get(key, controllerMask),
				Deadzone = deadzone
			};
		}

		protected Axis ReadAxis(OVRInput.Axis1D[] keys, float deadzone = 0f)
		{
			OVRInput.Controller controllerMask = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			Axis result = new Axis
			{
				Deadzone = deadzone
			};
			foreach (OVRInput.Axis1D virtualMask in keys)
			{
				float num = OVRInput.Get(virtualMask, controllerMask);
				if (Mathf.Abs(num) > Mathf.Abs(result.Value))
				{
					result.Value = num;
				}
			}
			return result;
		}

		protected Vector2 ReadAxis2D(OVRInput.Axis2D key, Axis2DSettings axisSettings)
		{
			OVRInput.Controller controllerMask = ((base.HandType == VRTrackedController.HandType.LeftHand) ? OVRInput.Controller.LTouch : OVRInput.Controller.RTouch);
			Vector2 vector = OVRInput.Get(key, controllerMask);
			return axisSettings?.ProcessValue(vector) ?? vector;
		}
	}
