		private static readonly string DUALSHOCK_4_NAME = "Wireless Controller";

		private static readonly string XBOX_ONE_NAME = "Controller (Xbox One For Windows)";

		private static readonly string XBOX_360_NAME = "Controller (Xbox 360 For Windows)";

		private static readonly string XBOX_360_WIRELESS_NAME = "Controller (Xbox 360 Wireless Receiver For Windows)";

		[SerializeField]
		private KeyboardMouseInputMap keyboardMouseMap;

		[SerializeField]
		private GamepadInputMap xboxGamepadMap;

		[SerializeField]
		private GamepadInputMap ps4Dualshock4Map;

		[SerializeField]
		private AxisPressButtons switchToolAxisButtons;

		[SerializeField]
		private AxisPressButtons quickCommVerticalAxisButtons;

		[SerializeField]
		private AxisPressButtons quickCommHorizontalAxisButtons;

		[SerializeField]
		private float inputTimeout = 1f;

		private GamepadType currentGamepadType;

		private HairTriggerButton primaryMainHandActionHairTriggerButton = new HairTriggerButton();

		private HairTriggerButton aimDownSightsHairTriggerButton = new HairTriggerButton();

		private DiscreteButtonAxis discreteAxis = new DiscreteButtonAxis();

		private float lastInputTime;

		public GamepadType CurrentGamepadType => currentGamepadType;

		public override void Attach()
		{
			base.Attach();
			base.UsingKeyboardMouse = true;
			UpdateLabels();
		}

		protected override void ReadInputState(ref InputState state)
		{
			base.IsConnected = true;
			bool hasInputThisFrame = false;
			if (currentGamepadType == GamepadType.UNINITIALIZED || UnityEngine.Time.time - lastInputTime >= inputTimeout)
			{
				currentGamepadType = GetGamepadType();
				lastInputTime = UnityEngine.Time.time;
			}
			if (base.UsingKeyboardMouse && TestGamepadInput())
			{
				base.UsingKeyboardMouse = false;
				UpdateLabels();
			}
			else if (!base.UsingKeyboardMouse && TestKeyboardMouseInput())
			{
				base.UsingKeyboardMouse = true;
				UpdateLabels();
			}
			if (base.UsingKeyboardMouse)
			{
				UpdateStateKeyboardMouse(keyboardMouseMap, ref state, ref hasInputThisFrame);
			}
			else
			{
				switch (currentGamepadType)
				{
				case GamepadType.PLAYSTATION:
					UpdateStateGamepad(ps4Dualshock4Map, ref state, ref hasInputThisFrame);
					break;
				case GamepadType.XBOX:
					UpdateStateGamepad(xboxGamepadMap, ref state, ref hasInputThisFrame);
					break;
				}
			}
			if (hasInputThisFrame)
			{
				lastInputTime = UnityEngine.Time.time;
			}
			base.HasInputThisFrame = hasInputThisFrame;
		}

		private void UpdateStateKeyboardMouse(KeyboardMouseInputMap inputMap, ref InputState state, ref bool hasInputThisFrame)
		{
			UpdateStateCommon(inputMap, ref state, ref hasInputThisFrame);
			Vector2 rawValue = new Vector2(Input.GetAxisRaw(inputMap.WalkHorizontalAxisName), Input.GetAxisRaw(inputMap.WalkVerticalAxisName));
			state.WalkAxis = inputMap.WalkAxisSettings.ProcessValue(rawValue);
			hasInputThisFrame |= state.WalkAxis.sqrMagnitude >= Mathf.Epsilon;
			state.MouseDeltaMickeys = new Vector2(Input.GetAxisRaw("Mouse X"), -1f * Input.GetAxisRaw("Mouse Y"));
			hasInputThisFrame |= state.MouseDeltaMickeys.sqrMagnitude >= Mathf.Epsilon;
			Vector2 mouseDeltaMickeys = state.MouseDeltaMickeys;
			mouseDeltaMickeys.y *= -1f;
			Vector2 vector = mouseDeltaMickeys / inputMap.DefaultMouseHardwareDPI;
			Vector2 vector2 = vector * Screen.dpi;
			float time = vector.magnitude / UnityEngine.Time.deltaTime;
			float num = inputMap.MouseHardwareSpeedToScreenSpeedCurve.Evaluate(time);
			float magnitude = vector2.magnitude;
			float num2 = 1f;
			if (magnitude != 0f)
			{
				num2 = num / magnitude;
			}
			state.MouseDeltaScreenPosition = vector2 * num2;
			state.MouseScreenPosition = Input.mousePosition;
			state.PrimaryMainHandActionButton = Button.ReadMouseButton(inputMap.PrimaryMainHandActionMouseButtonKey);
			hasInputThisFrame |= state.PrimaryMainHandActionButton.Pressed;
			state.AimDownSightsActionButton = Button.ReadMouseButton(inputMap.AimDownSightsMouseButtonKey);
			hasInputThisFrame |= state.AimDownSightsActionButton.Pressed;
			state.CursorSelectButton = Button.ReadMouseButton(inputMap.CursorSelectMouseButtonKey);
			hasInputThisFrame |= state.CursorSelectButton.Pressed;
			state.PushToTalkButton = Button.ReadKey(inputMap.PushToTalkButton);
			hasInputThisFrame |= state.PushToTalkButton.Pressed;
			Vector2 axis = new Vector2(0f, Input.GetAxisRaw(inputMap.SwitchToolAxisName));
			switchToolAxisButtons.Update(axis, Mathf.Abs(axis.y) <= Mathf.Epsilon);
			state.SwitchToolButton1 = Button.ReadAxisButton(switchToolAxisButtons, AxisButtons.Direction.UP);
			hasInputThisFrame |= state.SwitchToolButton1.Pressed;
			state.SwitchToolButton2 = Button.ReadAxisButton(switchToolAxisButtons, AxisButtons.Direction.DOWN);
			hasInputThisFrame |= state.SwitchToolButton2.Pressed;
			state.QuickCommButton1 = Button.ReadKey(inputMap.QuickCommButton1);
			state.QuickCommButton2 = Button.ReadKey(inputMap.QuickCommButton2);
			state.QuickCommButton3 = Button.ReadKey(inputMap.QuickCommButton3);
			state.QuickCommButton4 = Button.ReadKey(inputMap.QuickCommButton4);
			state.CreationSelectButton = Button.ReadMouseButton(inputMap.CreationSelectMouseButtonKey);
			state.CreationCameraModeButton = Button.ReadMouseButton(inputMap.CreationCameraModeButtonKey);
			state.CreationMoveButton = Button.ReadKey(inputMap.CreationMoveButtonKey);
			state.CreationRotateButton = Button.ReadKey(inputMap.CreationRotateButtonKey);
			state.CreationScaleButton = Button.ReadKey(inputMap.CreationScaleButtonKey);
		}

		private void UpdateStateGamepad(GamepadInputMap inputMap, ref InputState state, ref bool hasInputThisFrame)
		{
			UpdateStateCommon(inputMap, ref state, ref hasInputThisFrame);
			Vector2 rawValue = new Vector2(Input.GetAxisRaw(inputMap.WalkHorizontalAxisName), Input.GetAxisRaw(inputMap.WalkVerticalAxisName));
			state.WalkAxis = inputMap.WalkThumbstickAxisSettings.ProcessValue(rawValue);
			hasInputThisFrame |= state.WalkAxis.sqrMagnitude >= Mathf.Epsilon;
			Vector2 rawValue2 = new Vector2(Input.GetAxisRaw(inputMap.CameraHorizontalAxisName), -1f * Input.GetAxisRaw(inputMap.CameraVerticalAxisName));
			state.CameraAxisGamepad = inputMap.CameraThumbstickAxisSettings.ProcessValue(rawValue2);
			hasInputThisFrame |= state.CameraAxisGamepad.sqrMagnitude >= Mathf.Epsilon;
			primaryMainHandActionHairTriggerButton.Update(Input.GetAxisRaw(inputMap.PrimaryMainHandActionAxisName), inputMap.PrimaryMainHandActionDeadzone, inputMap.PrimaryMainHandActionAxisGoesNegative);
			state.PrimaryMainHandActionButton = Button.ReadHairTriggerButton(primaryMainHandActionHairTriggerButton);
			hasInputThisFrame |= state.PrimaryMainHandActionButton.Pressed;
			aimDownSightsHairTriggerButton.Update(Input.GetAxisRaw(inputMap.AimDownSightsAxisName), inputMap.AimDownSightsDeadzone, inputMap.AimDownSightsAxisGoesNegative);
			state.AimDownSightsActionButton = Button.ReadHairTriggerButton(aimDownSightsHairTriggerButton);
			hasInputThisFrame |= state.AimDownSightsActionButton.Pressed;
			Vector2 rawValue3 = new Vector2(Input.GetAxisRaw(inputMap.CursorHorizontalAxisName), Input.GetAxisRaw(inputMap.CursorVerticalAxisName));
			state.CursorAxis = inputMap.WalkThumbstickAxisSettings.ProcessValue(rawValue3);
			state.CursorSelectButton = Button.ReadKey(inputMap.CursorSelectButton);
			hasInputThisFrame |= state.CursorSelectButton.Pressed;
			state.SwitchToolButton1 = Button.ReadKey(inputMap.SwitchToolButton);
			hasInputThisFrame |= state.SwitchToolButton1.Pressed;
			Vector2 axis = new Vector2(0f, Input.GetAxisRaw(inputMap.QuickCommVerticalAxisName));
			quickCommVerticalAxisButtons.Update(axis, Mathf.Abs(axis.y) <= Mathf.Epsilon);
			state.QuickCommButton1 = Button.ReadAxisButton(quickCommVerticalAxisButtons, AxisButtons.Direction.UP);
			hasInputThisFrame |= state.QuickCommButton1.Pressed;
			state.QuickCommButton4 = Button.ReadAxisButton(quickCommVerticalAxisButtons, AxisButtons.Direction.DOWN);
			hasInputThisFrame |= state.QuickCommButton3.Pressed;
			Vector2 axis2 = new Vector2(Input.GetAxisRaw(inputMap.QuickCommHorizontalAxisName), 0f);
			quickCommHorizontalAxisButtons.Update(axis2, Mathf.Abs(axis2.x) <= Mathf.Epsilon);
			state.QuickCommButton2 = Button.ReadAxisButton(quickCommHorizontalAxisButtons, AxisButtons.Direction.LEFT);
			hasInputThisFrame |= state.QuickCommButton2.Pressed;
			state.QuickCommButton3 = Button.ReadAxisButton(quickCommHorizontalAxisButtons, AxisButtons.Direction.RIGHT);
			hasInputThisFrame |= state.QuickCommButton3.Pressed;
			state.CreationSelectButton = Button.ReadKey(inputMap.CreationSelectButton);
			state.CreationCameraModeButton = Button.ReadKey(inputMap.CreationCameraModeButton);
			Vector2 rawValue4 = new Vector2(Input.GetAxisRaw(inputMap.CreationRotationLeftHorizontalAxisName), Input.GetAxisRaw(inputMap.CreationRotationLeftVerticalAxisName));
			Vector2 vector = inputMap.CreationRotationLeftAxisSettings.ProcessValue(rawValue4);
			Vector2 rawValue5 = new Vector2(Input.GetAxisRaw(inputMap.CreationRotationRightHorizontalAxisName), Input.GetAxisRaw(inputMap.CreationRotationRightVerticalAxisName));
			Vector2 vector2 = inputMap.CreationRotationRightAxisSettings.ProcessValue(rawValue5);
			state.CreationRotationRollAxis = vector.x;
			state.CreationRotationYawAxis = vector2.x;
			if (Mathf.Abs(vector.y) >= Mathf.Abs(vector2.y))
			{
				state.CreationRotationPitchAxis = vector.y;
			}
			else
			{
				state.CreationRotationPitchAxis = vector2.y;
			}
			state.CreationScaleAxis = vector.x + vector.y;
			state.CreationRotateButton = state.PrimaryMainHandActionButton;
			state.CreationScaleButton = state.AimDownSightsActionButton;
		}

		private void UpdateStateCommon(InputMap inputMap, ref InputState state, ref bool hasInputThisFrame)
		{
			hasInputThisFrame |= Input.anyKeyDown;
			state.PickupButton = Button.ReadKey(inputMap.PickupButton);
			hasInputThisFrame |= state.PickupButton.Pressed;
			state.DropButton = Button.ReadKey(inputMap.DropButton);
			hasInputThisFrame |= state.DropButton.Pressed;
			state.JumpButton = Button.ReadKey(inputMap.JumpButton);
			hasInputThisFrame |= state.JumpButton.Pressed;
			state.CrouchButton = Button.ReadKey(inputMap.CrouchButton);
			hasInputThisFrame |= state.CrouchButton.Pressed;
			state.SprintButton = Button.ReadKey(inputMap.SprintButton);
			hasInputThisFrame |= state.SprintButton.Pressed;
			state.SecondaryMainHandActionButton = Button.ReadKey(inputMap.SecondaryMainHandButton);
			hasInputThisFrame |= state.SecondaryMainHandActionButton.Pressed;
			state.OffHandActionButton = Button.ReadKey(inputMap.OffHandActionButton);
			hasInputThisFrame |= state.OffHandActionButton.Pressed;
			state.MenuButton = Button.ReadKey(inputMap.MenuButton);
			hasInputThisFrame |= state.MenuButton.Pressed;
			state.MenuCancelButton = Button.ReadKey(inputMap.MenuCancelButton);
			hasInputThisFrame |= state.MenuCancelButton.Pressed;
			state.SecondaryMenuButton = Button.ReadKey(inputMap.SecondaryMenuButton);
			hasInputThisFrame |= state.SecondaryMenuButton.Pressed;
			state.FavoriteToolButton = Button.ReadKey(inputMap.FavoriteToolButton);
			hasInputThisFrame |= state.FavoriteToolButton.Pressed;
			state.AmbientUISelectButton = Button.ReadKey(inputMap.AmbientUISelectButton);
			hasInputThisFrame |= state.AmbientUISelectButton.Pressed;
			state.CreationFlyingVerticalAxis = discreteAxis.ReadAxis(inputMap.CreationFlyingUpButton, inputMap.CreationFlyingDownButton);
			state.CreationCancelButton = Button.ReadKey(inputMap.CreationCancelButton);
			state.CreationCloneButton = Button.ReadKey(inputMap.CreationCloneButton);
		}

		private void UpdateLabels()
		{
			if (base.UsingKeyboardMouse)
			{
				UpdateLabelsCommon(keyboardMouseMap);
				return;
			}
			switch (currentGamepadType)
			{
			case GamepadType.PLAYSTATION:
				UpdateLabelsCommon(ps4Dualshock4Map);
				break;
			case GamepadType.XBOX:
				UpdateLabelsCommon(xboxGamepadMap);
				break;
			}
		}

		private void UpdateLabelsCommon(InputMap inputMap)
		{
			labels.PickupButtonSprite = inputMap.PickupButtonSprite;
			labels.DropButtonSprite = inputMap.DropButtonSprite;
			labels.JumpButtonSprite = inputMap.JumpButtonSprite;
			labels.AmbientUISelectButtonSprite = inputMap.AmbientUISelectButtonSprite;
			labels.WalkButtonSprite = inputMap.WalkButtonSprite;
			labels.LookButtonSprite = inputMap.LookButtonSprite;
			labels.PrimaryMainHandActionButtonSprite = inputMap.PrimaryMainHandActionButtonSprite;
			labels.SecondaryMainHandActionButtonSprite = inputMap.SecondaryMainHandActionButtonSprite;
			labels.AimDownSightsActionButtonSprite = inputMap.AimDownSightsActionButtonSprite;
			labels.OffHandActionButtonSprite = inputMap.OffHandActionButtonSprite;
			labels.MenuButtonSprite = inputMap.MenuButtonSprite;
			labels.SprintButtonSprite = inputMap.SprintButtonSprite;
			labels.SecondaryMenuButtonSprite = inputMap.SecondaryMenuButtonSprite;
			labels.CursorButtonSprite = inputMap.CursorButtonSprite;
			labels.MenuCancelButtonSprite = inputMap.MenuCancelButtonSprite;
			labels.FavoriteToolButtonSprite = inputMap.FavoriteToolButtonSprite;
			labels.QuickCommButton1Sprite = inputMap.QuickCommButton1Sprite;
			labels.QuickCommButton2Sprite = inputMap.QuickCommButton2Sprite;
			labels.QuickCommButton3Sprite = inputMap.QuickCommButton3Sprite;
			labels.QuickCommButton4Sprite = inputMap.QuickCommButton4Sprite;
			labels.CreationToggleCameraModeSprite = inputMap.CreationToggleCameraModeSprite;
			labels.CreationCameraModeButtonUpSprite = inputMap.CreationCameraModeButtonUpSprite;
			labels.CreationCameraModeButtonDownSprite = inputMap.CreationCameraModeButtonDownSprite;
			labels.CreationCloneButtonSprite = inputMap.CreationCloneButtonSprite;
			labels.CreationMoveModeButtonSprite = inputMap.CreationMoveModeButtonSprite;
			labels.CreationRotateModeButtonSprite = inputMap.CreationRotateModeButtonSprite;
			labels.CreationScaleModeButtonSprite = inputMap.CreationScaleModeButtonSprite;
		}

		private GamepadType GetGamepadType()
		{
			string[] joystickNames = Input.GetJoystickNames();
			for (int i = 0; i < joystickNames.Length; i++)
			{
				if (joystickNames[i] == DUALSHOCK_4_NAME)
				{
					return GamepadType.PLAYSTATION;
				}
				if (joystickNames[i] == XBOX_ONE_NAME || joystickNames[i] == XBOX_360_NAME || joystickNames[i] == XBOX_360_WIRELESS_NAME)
				{
					return GamepadType.XBOX;
				}
			}
			return GamepadType.NONE;
		}

		private bool TestKeyboardMouseInput()
		{
			return TestInput(keyboardMouseMap);
		}

		private bool TestGamepadInput()
		{
			return currentGamepadType switch
			{
				GamepadType.PLAYSTATION => TestInput(ps4Dualshock4Map), 
				GamepadType.XBOX => TestInput(xboxGamepadMap), 
				_ => false, 
			};
		}

		private bool TestInput(InputMap inputMap)
		{
			float num = Mathf.Max(0.1f, inputMap.WalkAxisDeadzone);
			return Input.GetAxisRaw(inputMap.WalkHorizontalAxisName) >= num || Input.GetAxisRaw(inputMap.WalkVerticalAxisName) >= num;
		}
	}
