		private InputMap inputMap;

		[SerializeField]
		private AxisPressButtons quickCommVerticalAxisButtons;

		[SerializeField]
		private AxisPressButtons quickCommHorizontalAxisButtons;

		private HairTriggerButton primaryMainHandActionHairTriggerButton = new HairTriggerButton();

		private HairTriggerButton aimDownSightsHairTriggerButton = new HairTriggerButton();

		private DiscreteButtonAxis discreteAxis = new DiscreteButtonAxis();

		public override void Attach()
		{
			base.Attach();
			UpdateLabels();
		}

		protected override void ReadInputState(ref InputState state)
		{
			base.IsConnected = true;
			base.UsingKeyboardMouse = false;
			bool flag = false;
			Vector2 rawValue = new Vector2(Input.GetAxisRaw(inputMap.WalkHorizontalAxisName), Input.GetAxisRaw(inputMap.WalkVerticalAxisName));
			state.WalkAxis = inputMap.WalkThumbstickAxisSettings.ProcessValue(rawValue);
			flag |= state.WalkAxis.sqrMagnitude >= Mathf.Epsilon;
			Vector2 rawValue2 = new Vector2(Input.GetAxisRaw(inputMap.CameraHorizontalAxisName), -1f * Input.GetAxisRaw(inputMap.CameraVerticalAxisName));
			state.CameraAxisGamepad = inputMap.CameraThumbstickAxisSettings.ProcessValue(rawValue2);
			flag |= state.CameraAxisGamepad.sqrMagnitude >= Mathf.Epsilon;
			float axisRaw = Input.GetAxisRaw(inputMap.PrimaryMainHandActionAxisName);
			float axisValue = Mathf.InverseLerp(0f, -1f, axisRaw);
			primaryMainHandActionHairTriggerButton.Update(axisValue, inputMap.PrimaryMainHandActionMainHandDeadzone);
			state.PrimaryMainHandActionButton = Button.ReadHairTriggerButton(primaryMainHandActionHairTriggerButton);
			flag |= state.PrimaryMainHandActionButton.Pressed;
			float axisRaw2 = Input.GetAxisRaw(inputMap.AimDownSightsAxisName);
			aimDownSightsHairTriggerButton.Update(axisRaw2, inputMap.AimDownSightsDeadzone);
			state.AimDownSightsActionButton = Button.ReadHairTriggerButton(aimDownSightsHairTriggerButton);
			flag |= state.AimDownSightsActionButton.Pressed;
			state.PickupButton = Button.ReadKey(inputMap.PickupButton);
			flag |= state.PickupButton.Pressed;
			state.DropButton = Button.ReadKey(inputMap.DropButton);
			flag |= state.DropButton.Pressed;
			state.JumpButton = Button.ReadKey(inputMap.JumpButton);
			flag |= state.JumpButton.Pressed;
			state.SwitchToolButton1 = Button.ReadKey(inputMap.SwitchToolButton);
			flag |= state.SwitchToolButton1.Pressed;
			state.CrouchButton = Button.ReadKey(inputMap.CrouchButton);
			flag |= state.CrouchButton.Pressed;
			state.SprintButton = Button.ReadKey(inputMap.SprintButton);
			flag |= state.SprintButton.Pressed;
			state.SecondaryMainHandActionButton = Button.ReadKey(inputMap.SecondaryMainHandActionButton);
			flag |= state.SecondaryMainHandActionButton.Pressed;
			state.OffHandActionButton = Button.ReadKey(inputMap.OffHandActionButton);
			flag |= state.OffHandActionButton.Pressed;
			Vector2 axis = new Vector2(0f, Input.GetAxisRaw(inputMap.QuickCommVerticalAxisName));
			quickCommVerticalAxisButtons.Update(axis, Mathf.Abs(axis.y) <= Mathf.Epsilon);
			state.QuickCommButton1 = Button.ReadAxisButton(quickCommVerticalAxisButtons, AxisButtons.Direction.UP);
			flag |= state.QuickCommButton1.Pressed;
			state.QuickCommButton4 = Button.ReadAxisButton(quickCommVerticalAxisButtons, AxisButtons.Direction.DOWN);
			flag |= state.QuickCommButton4.Pressed;
			Vector2 axis2 = new Vector2(Input.GetAxisRaw(inputMap.QuickCommHorizontalAxisName), 0f);
			quickCommHorizontalAxisButtons.Update(axis2, Mathf.Abs(axis2.x) <= Mathf.Epsilon);
			state.QuickCommButton2 = Button.ReadAxisButton(quickCommHorizontalAxisButtons, AxisButtons.Direction.LEFT);
			flag |= state.QuickCommButton2.Pressed;
			state.QuickCommButton3 = Button.ReadAxisButton(quickCommHorizontalAxisButtons, AxisButtons.Direction.RIGHT);
			flag |= state.QuickCommButton3.Pressed;
			state.MenuButton = Button.ReadKey(inputMap.MenuButton);
			flag |= state.MenuButton.Pressed;
			state.CursorSelectButton = Button.ReadKey(inputMap.CursorSelectButton);
			flag |= state.CursorSelectButton.Pressed;
			state.AmbientUISelectButton = Button.ReadKey(inputMap.AmbientUISelectButton);
			flag |= state.AmbientUISelectButton.Pressed;
			state.MenuCancelButton = Button.ReadKey(inputMap.MenuCancelButton);
			flag |= state.MenuCancelButton.Pressed;
			state.SecondaryMenuButton = Button.ReadKey(inputMap.SecondaryMenuButton);
			flag |= state.SecondaryMenuButton.Pressed;
			state.FavoriteToolButton = Button.ReadKey(inputMap.FavoriteToolButton);
			flag |= state.FavoriteToolButton.Pressed;
			Vector2 rawValue3 = new Vector2(Input.GetAxisRaw(inputMap.CursorHorizontalAxisName), Input.GetAxisRaw(inputMap.CursorVerticalAxisName));
			state.CursorAxis = inputMap.WalkThumbstickAxisSettings.ProcessValue(rawValue3);
			flag |= state.CursorAxis.sqrMagnitude >= Mathf.Epsilon;
			state.CreationFlyingVerticalAxis = discreteAxis.ReadAxis(inputMap.CreationFlyingUpButton, inputMap.CreationFlyingDownButton);
			state.CreationSelectButton = Button.ReadKey(inputMap.CreationSelectButton);
			state.CreationCancelButton = Button.ReadKey(inputMap.CreationCancelButton);
			state.CreationCameraModeButton = Button.ReadKey(inputMap.CreationCameraModeButton);
			state.CreationCloneButton = Button.ReadKey(inputMap.CreationCloneButton);
			Vector2 rawValue4 = new Vector2(Input.GetAxisRaw(inputMap.CreationRotationLeftHorizontalAxisName), Input.GetAxisRaw(inputMap.CreationRotationLeftVerticalAxisName));
			Vector2 vector = inputMap.CreationRotationLeftAxisSettings.ProcessValue(rawValue4);
			Vector2 rawValue5 = new Vector2(Input.GetAxisRaw(inputMap.CreationRotationRightHorizontalAxisName), Input.GetAxisRaw(inputMap.CreationRotationRightVerticalAxisName));
			Vector2 vector2 = inputMap.CreationRotationRightAxisSettings.ProcessValue(rawValue5);
			state.CreationRotationRollAxis = vector.x;
			state.CreationRotationYawAxis = vector2.x;
			if (Mathf.Abs(vector.y) >= Mathf.Abs(vector2.y))
			{
				state.CreationRotationPitchAxis = vector.y;
			}
			else
			{
				state.CreationRotationPitchAxis = vector2.y;
			}
			state.CreationScaleAxis = vector.x + vector.y;
			state.CreationRotateButton = state.PrimaryMainHandActionButton;
			state.CreationScaleButton = state.AimDownSightsActionButton;
			base.HasInputThisFrame = flag;
		}

		private void UpdateLabels()
		{
			labels.PickupButtonSprite = inputMap.PickupButtonSprite;
			labels.DropButtonSprite = inputMap.DropButtonSprite;
