	[Serializable]
	public class PS4MoveVRInputHandler : VRInputHandler
	{
		[Serializable]
		public class Map
		{
			public PS4MoveButton[] MenuButtons = new PS4MoveButton[2]
			{
				PS4MoveButton.Square,
				PS4MoveButton.Triangle
			};

			public PS4MoveButton SprintButton = PS4MoveButton.Move;

			public PS4MoveButton TeleportButton = PS4MoveButton.Move;

			public PS4MoveButton PushToTalkButton;

			public PS4MoveButton FlyModeModifierButton = PS4MoveButton.Trigger;

			public PS4MoveButton RotateLeftButton = PS4MoveButton.Cross;

			public PS4MoveButton RotateRightButton = PS4MoveButton.Circle;

			public PS4MoveButton[] RCMainButtons = new PS4MoveButton[2]
			{
				PS4MoveButton.Cross,
				PS4MoveButton.Circle
			};

			public AxisSettings TriggerSettings;
		}

		private class CombinedButton
		{
			public bool Down { get; private set; }

			public bool Pressed { get; private set; }

			public bool Up { get; private set; }

			public CombinedButton()
			{
				Down = false;
				Pressed = false;
				Up = false;
			}

			public void Update(params Button[] buttons)
			{
				bool pressed = Pressed;
				Down = false;
				Pressed = false;
				Up = false;
				if (buttons != null)
				{
					for (int i = 0; i < buttons.Length; i++)
					{
						Pressed |= buttons[i].Pressed;
						if (Pressed)
						{
							break;
						}
					}
				}
				if (!pressed && Pressed)
				{
					Down = true;
				}
				else if (!Pressed && pressed)
				{
					Up = true;
				}
			}
		}

		[SerializeField]
		private Map map;

		private PS4MoveInput ps4MoveInput;

		private CombinedButton smoothRotateCombinedButton = new CombinedButton();

		private DiscreteButtonAxis discreteAxis = new DiscreteButtonAxis();

		public override void Attach()
		{
			if (ps4MoveInput == null)
			{
				ps4MoveInput = rawTrackerTransform.gameObject.AddComponent<PS4MoveInput>();
				ps4MoveInput.ControllerIndex = ((base.HandType != VRTrackedController.HandType.LeftHand) ? 1 : 0);
			}
			smoothRotateCombinedButton.Update(null);
			ps4MoveInput.PosesChanged += OnPosesChanged;
		}

		public override void Detach()
		{
			if (ps4MoveInput != null)
			{
				ps4MoveInput.PosesChanged -= OnPosesChanged;
			}
		}

		private void OnPosesChanged()
		{
			base.IsConnected = ps4MoveInput.IsConnected;
			base.IsTracking = ps4MoveInput.IsTrackingPosition || ps4MoveInput.IsTrackingRotation;
			base.LinearVelocity = Vector3.zero;
			base.AngularVelocity = Vector3.zero;
			if (base.IsConnected)
			{
				if (ps4MoveInput.IsTrackingPosition)
				{
					rawTrackerTransform.localPosition = ps4MoveInput.LastPosition;
				}
				if (ps4MoveInput.IsTrackingRotation)
				{
					rawTrackerTransform.localRotation = ps4MoveInput.LastRotation;
				}
				base.LinearVelocity = rawTrackerTransform.parent.TransformVector(ps4MoveInput.LastLinearVelocity) * base.LinearVelocityMultiplier;
				base.AngularVelocity = rawTrackerTransform.parent.TransformVector(ps4MoveInput.LastAngularVelocity) * base.AngularVelocityMultiplier;
				OnTransformUpdated();
			}
		}

		protected override void ReadInputState(ref State state)
		{
			state.FlyModeModifierButton = ReadButton(map.FlyModeModifierButton);
			state.MenuButton = ReadButton(map.MenuButtons);
			state.PickupAxis = ReadAxis();
			state.PushToTalkButton = ReadButton(map.PushToTalkButton);
			state.RotateLeftButton = ReadButton(map.RotateLeftButton);
			state.RotateRightButton = ReadButton(map.RotateRightButton);
			smoothRotateCombinedButton.Update(state.RotateLeftButton, state.RotateRightButton);
			state.GripRotateButton = ReadCombinedButton(smoothRotateCombinedButton);
			state.SprintButton = ReadButton(map.SprintButton);
			state.TeleportButton = ReadButton(map.TeleportButton);
			state.CalibrateBackButton = ReadButton(PS4MoveButton.Circle);
			state.CalibrateDownButton = ReadButton(PS4MoveButton.Square);
			state.CalibrateUpButton = ReadButton(PS4MoveButton.Cross);
			float x = discreteAxis.ReadAxis(state.RotateRightButton, state.RotateLeftButton);
			state.SmoothSwipeRotateAxis = new Vector2(x, 0f);
			state.TriggerAxis = ReadAxis();
			state.TriggerPressureValue = AxisSettings.ProcessValue(ps4MoveInput.GetTriggerAxis(), map.TriggerSettings);
			state.RCMainButton = ReadButton(map.RCMainButtons);
			state.RCTriggerAxis = ReadAxis();
			if (ps4MoveInput.GetButtonDown(map.TeleportButton))
			{
				RCVirtualJoystickReferenceForward = rawTrackerTransform.forward;
				RCVirtualJoystickReferenceRight = rawTrackerTransform.right;
				RCVirtualJoystickReferenceUp = rawTrackerTransform.up;
			}
			if (ps4MoveInput.GetButton(map.TeleportButton))
			{
				Vector3 vector = Vector3.ProjectOnPlane(rawTrackerTransform.forward, RCVirtualJoystickReferenceForward);
				Vector3 lhs = Vector3.Project(vector, RCVirtualJoystickReferenceRight);
				Vector3 lhs2 = Vector3.Project(vector, RCVirtualJoystickReferenceUp);
				float x2 = 2f * ((!(Vector3.Dot(lhs, RCVirtualJoystickReferenceRight) >= 0f)) ? (0f - lhs.magnitude) : lhs.magnitude);
				float y = 2f * ((!(Vector3.Dot(lhs2, RCVirtualJoystickReferenceUp) >= 0f)) ? lhs2.magnitude : (0f - lhs2.magnitude));
				state.RCControlStickAxis = new Vector2(x2, y);
			}
			else
			{
				state.RCControlStickAxis = Vector2.zero;
			}
		}

		protected override IEnumerator VibrateCoroutine(int milliseconds, float intensity, bool useTouchpad = false)
		{
			yield break;
		}

		private Button ReadButton(PS4MoveButton key)
		{
			return new Button
			{
				Down = ps4MoveInput.GetButtonDown(key),
				Pressed = ps4MoveInput.GetButton(key),
				Up = ps4MoveInput.GetButtonUp(key)
			};
		}

		private Button ReadCombinedButton(CombinedButton combinedButton)
		{
			return new Button
			{
				Down = combinedButton.Down,
				Pressed = combinedButton.Pressed,
				Up = combinedButton.Up
			};
		}

		private Button ReadButton(PS4MoveButton[] keys)
		{
			Button result = default(Button);
			foreach (PS4MoveButton button in keys)
			{
				result.Pressed |= ps4MoveInput.GetButton(button);
				result.Down |= ps4MoveInput.GetButtonDown(button);
				result.Up |= ps4MoveInput.GetButtonUp(button);
			}
			return result;
		}

		private Axis ReadAxis()
		{
			return new Axis
			{
				Value = ps4MoveInput.GetTriggerAxis()
			};
		}
	}
