	public class ScreenCameraInput
	{
		private enum PeggedState
		{
			NONE,
			HORIZONTAL,
			VERTICAL
		}

		private const float MOUSE_ROTATION_ANGLE_DEGREES_PER_MICKEY = 0.0125f;

		private PeggedState peggedState;

		private float peggedSpeed;

		public Vector2 GetRotationDeltaAngles(ScreenInputHandler input, ScreensCameraInputGamepadSettings inputSettings, float gamepadMaxSpeed, float deltaTime)
		{
			if (input.UsingKeyboardMouse)
			{
				return GetMouseDeltaAngles(input);
			}
			return GetGamepadDeltaAngles(input, inputSettings, gamepadMaxSpeed, deltaTime);
		}

		private Vector2 GetMouseDeltaAngles(ScreenInputHandler input)
		{
			return input.MouseDeltaMickeys * 0.0125f;
		}

		private Vector2 GetGamepadDeltaAngles(ScreenInputHandler input, ScreensCameraInputGamepadSettings inputSettings, float maxSpeed, float deltaTime)
		{
			Vector2 cameraAxisGamepad = input.CameraAxisGamepad;
			float screensGamepadSensitivityNormalized = SingletonMonoBehaviour<SettingsManager>.Instance.ScreensGamepadSensitivityNormalized;
			float num = inputSettings.SensitivityCurve.Evaluate(screensGamepadSensitivityNormalized);
			float num2 = maxSpeed * num;
			float x = cameraAxisGamepad.x * num2;
			float num3 = cameraAxisGamepad.y * num2;
			PeggedState peggedState = this.peggedState;
			this.peggedState = GetPeggedState(cameraAxisGamepad, inputSettings);
			if (this.peggedState != PeggedState.NONE)
			{
				if (this.peggedState != peggedState)
				{
					peggedSpeed = num2;
				}
				else
				{
					float num4 = num2 * inputSettings.PeggedMaxSpeedScaler;
					float num5 = (num4 - num2) / inputSettings.PeggedTimeToReachMaxSpeed;
					peggedSpeed = Mathf.Min(peggedSpeed + num5 * UnityEngine.Time.deltaTime, num4);
				}
				if (this.peggedState == PeggedState.HORIZONTAL)
				{
					float num6 = Mathf.Sign(cameraAxisGamepad.x);
					x = num6 * peggedSpeed;
				}
				else
				{
					float num7 = Mathf.Sign(cameraAxisGamepad.y);
					num3 = num7 * peggedSpeed;
				}
			}
			num3 *= inputSettings.PitchScaler;
			Vector2 vector = new Vector2(x, num3);
			return vector * deltaTime;
		}

		private PeggedState GetPeggedState(Vector2 rawAxis, ScreensCameraInputGamepadSettings inputSettings)
		{
			float magnitude = rawAxis.magnitude;
			if (!(magnitude >= 0.99f))
			{
				return PeggedState.NONE;
			}
			Vector2 vector = Mathf.Sign(rawAxis.x) * Vector2.right;
			float num = Mathf.Abs(Vector2.Angle(vector, rawAxis));
			if (num <= inputSettings.PeggedMaxAngleFromHorizontal)
			{
				return PeggedState.HORIZONTAL;
			}
			if (num <= 90f + inputSettings.PeggedMaxAngleFromVertical && num <= 90f - inputSettings.PeggedMaxAngleFromVertical)
			{
				return PeggedState.VERTICAL;
			}
			return PeggedState.NONE;
		}
	}
