	public abstract class SteamVrInputHandler : VRInputHandler
	{
		protected SteamVR_Events.Action newPosesAction;

		public override void Attach()
		{
			base.Attach();
			if (newPosesAction == null)
			{
				newPosesAction = SteamVR_Events.NewPosesAction(OnNewPoses);
			}
			newPosesAction.enabled = true;
		}

		public override void Detach()
		{
			base.Detach();
			if (newPosesAction != null)
			{
				newPosesAction.enabled = false;
			}
		}

		protected override void PulseHapticsFrame(float intensity, bool useTouchpad)
		{
			base.PulseHapticsFrame(intensity, useTouchpad);
			if (TryGetSteamVRDeviceIndex(out var index))
			{
				SteamVR_Controller.Device device = SteamVR_Controller.Input((int)index);
				ushort durationMicroSec = (ushort)Mathf.Lerp(0f, 3999f, intensity);
				if (useTouchpad)
				{
					device.TriggerHapticPulse(durationMicroSec);
				}
				else
				{
					device.TriggerHapticPulse(durationMicroSec);
				}
			}
		}

		protected bool TryGetSteamVRDeviceIndex(out uint index)
		{
			ETrackedControllerRole unDeviceType = ((base.HandType == VRTrackedController.HandType.LeftHand) ? ETrackedControllerRole.LeftHand : ETrackedControllerRole.RightHand);
			CVRSystem system = OpenVR.System;
			if (system == null)
			{
				index = uint.MaxValue;
				return false;
			}
			index = system.GetTrackedDeviceIndexForControllerRole(unDeviceType);
			return index != uint.MaxValue;
		}

		private void OnNewPoses(TrackedDevicePose_t[] poses)
		{
			if (!TryGetSteamVRDeviceIndex(out var index) || index >= poses.Length)
			{
				base.IsConnected = false;
				base.IsTracking = false;
				return;
			}
			base.IsConnected = poses[index].bDeviceIsConnected;
			base.IsTracking = poses[index].bPoseIsValid;
			if (base.IsConnected)
			{
				SteamVR_Utils.RigidTransform rigidTransform = new SteamVR_Utils.RigidTransform(poses[index].mDeviceToAbsoluteTracking);
				rawTrackerTransform.localPosition = rigidTransform.pos;
				rawTrackerTransform.localRotation = rigidTransform.rot;
				SteamVR_Controller.Device device = SteamVR_Controller.Input((int)index);
				base.LinearVelocity = rawTrackerTransform.parent.TransformVector(device.velocity) * base.LinearVelocityMultiplier;
				base.AngularVelocity = rawTrackerTransform.parent.TransformVector(device.angularVelocity) * base.AngularVelocityMultiplier;
				OnTransformUpdated();
			}
		}

		protected Button ReadPress(EVRButtonId key, SteamVR_Controller.Device device)
		{
			return new Button
			{
				Pressed = device.GetPress(key),
				Down = device.GetPressDown(key),
				Up = device.GetPressUp(key)
			};
		}

		protected Button ReadPress(EVRButtonId[] keys, SteamVR_Controller.Device device)
		{
			Button result = default(Button);
			foreach (EVRButtonId buttonId in keys)
			{
				result.Pressed |= device.GetPress(buttonId);
				result.Down |= device.GetPressDown(buttonId);
				result.Up |= device.GetPressUp(buttonId);
			}
			return result;
		}

		protected Button ReadTouch(EVRButtonId key, SteamVR_Controller.Device device)
		{
			return new Button
			{
				Pressed = device.GetTouch(key),
				Down = device.GetTouchDown(key),
				Up = device.GetTouchUp(key)
			};
		}

		protected Button ReadTouch(EVRButtonId[] keys, SteamVR_Controller.Device device)
		{
			Button result = default(Button);
			foreach (EVRButtonId buttonId in keys)
			{
				result.Pressed |= device.GetTouch(buttonId);
				result.Down |= device.GetTouchDown(buttonId);
				result.Up |= device.GetTouchUp(buttonId);
			}
			return result;
		}

		protected Axis ReadAxis(EVRButtonId key, SteamVR_Controller.Device device, float deadzone = 0f)
		{
			return new Axis
			{
				Deadzone = deadzone,
				Value = device.GetAxis(key).x
			};
		}

		protected Axis ReadAxis(EVRButtonId[] keys, SteamVR_Controller.Device device, float deadzone = 0f)
		{
			Axis result = new Axis
			{
				Deadzone = deadzone
			};
			foreach (EVRButtonId buttonId in keys)
			{
				float x = device.GetAxis(buttonId).x;
				if (Mathf.Abs(x) > Mathf.Abs(result.Value))
				{
					result.Value = x;
				}
			}
			return result;
		}

		protected Vector2 ReadAxis2D(EVRButtonId key, SteamVR_Controller.Device device, Axis2DSettings axisSettings)
		{
			Vector2 axis = device.GetAxis(key);
			return axisSettings?.ProcessValue(axis) ?? axis;
		}
	}
