	[Serializable]
	public class SteamVrViveVRInputHandler : SteamVrInputHandler
	{
		[Serializable]
		private class Map
		{
			public EVRButtonId[] PickupButtons = new EVRButtonId[1] { EVRButtonId.k_EButton_Axis1 };

			public EVRButtonId TriggerButton = EVRButtonId.k_EButton_Axis1;

			public EVRButtonId MenuButton = EVRButtonId.k_EButton_ApplicationMenu;

			public EVRButtonId SprintButton = EVRButtonId.k_EButton_Axis0;

			public EVRButtonId TeleportButton = EVRButtonId.k_EButton_Axis0;

			public EVRButtonId PushToTalkButton = EVRButtonId.k_EButton_Grip;

			public EVRButtonId SmoothRotateButton = EVRButtonId.k_EButton_Grip;

			public EVRButtonId AlternateSmoothRotateButton = EVRButtonId.k_EButton_Grip;

			public EVRButtonId FlyModeModifierButton = EVRButtonId.k_EButton_Grip;

			public EVRButtonId RotateAxis = EVRButtonId.k_EButton_Axis0;

			public EVRButtonId WalkAxis = EVRButtonId.k_EButton_Axis0;

			public EVRButtonId SmoothSwipeRotateAxis = EVRButtonId.k_EButton_Axis0;

			public Axis2DSettings RotateAxisSettings;

			public Axis2DSettings WalkAxisSettings;

			public Axis2DSettings SmoothSwipeRotateAxisSettings;

			public AxisSettings TriggerSettings;

			public AxisSwipeButtons RotateAxisSwipeButtons;
		}

		[SerializeField]
		private Map map;

		private bool touchDownInDeadZone;

		private AxisSwipeButtons.SwipeStates lastSwipeState;

		private AxisSwipeButtons.SwipeStates currentSwipeState;

		protected override void ReadInputState(ref State state)
		{
			if (!TryGetSteamVRDeviceIndex(out var index))
			{
				return;
			}
			SteamVR_Controller.Device device = SteamVR_Controller.Input((int)index);
			Button button = ReadTouch(map.RotateAxis, device);
			Button button2 = ReadPress(map.RotateAxis, device);
			state.MenuButton = ReadPress(map.MenuButton, device);
			state.TeleportRotateAxis = ReadAxis2D(map.RotateAxis, device, map.RotateAxisSettings);
			bool flag = state.TeleportRotateAxis.sqrMagnitude < Mathf.Epsilon;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.TouchpadTeleportEnabled && SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode == VRMovementMode.TELEPORT)
			{
				state.TeleportButton = ReadTouch(map.RotateAxis, device);
				if (state.TeleportButton.Down)
				{
					touchDownInDeadZone = flag;
				}
			}
			else
			{
				state.TeleportButton = ReadPress(map.TeleportButton, device);
				touchDownInDeadZone = false;
			}
			state.WalkAxis = ReadAxis2D(map.WalkAxis, device, map.WalkAxisSettings);
			bool flag2 = !button.Up && (button.Down || button.Pressed);
			bool hasValidInput = (button2.Up || (!button2.Down && !button2.Pressed)) && !touchDownInDeadZone;
			lastSwipeState = map.RotateAxisSwipeButtons.SwipeState;
			map.RotateAxisSwipeButtons.Update(state.TeleportRotateAxis, flag2, hasValidInput);
			currentSwipeState = map.RotateAxisSwipeButtons.SwipeState;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.TouchpadTeleportEnabled)
			{
				if (flag2 && currentSwipeState != AxisSwipeButtons.SwipeStates.Touch && currentSwipeState != AxisSwipeButtons.SwipeStates.None)
				{
					state.TeleportButton = new Button
					{
						Up = true
					};
				}
				else if (lastSwipeState != currentSwipeState)
				{
					if (currentSwipeState == AxisSwipeButtons.SwipeStates.Touch)
					{
						state.TeleportButton = new Button
						{
							Down = true,
							Pressed = true
						};
					}
					else if (lastSwipeState == AxisSwipeButtons.SwipeStates.Touch && currentSwipeState == AxisSwipeButtons.SwipeStates.None)
					{
						state.TeleportButton = new Button
						{
							Up = true
						};
					}
				}
			}
			state.RotateRightButton = Button.ReadAxisButton(map.RotateAxisSwipeButtons, AxisButtons.Direction.RIGHT);
			state.RotateLeftButton = Button.ReadAxisButton(map.RotateAxisSwipeButtons, AxisButtons.Direction.LEFT);
			state.RotateDownButton = Button.ReadAxisButton(map.RotateAxisSwipeButtons, AxisButtons.Direction.DOWN);
			state.PushToTalkButton = ReadPress(map.PushToTalkButton, device);
			state.GripRotateButton = ReadPress(map.SmoothRotateButton, device);
			state.AlternateGripRotateButton = ReadPress(map.AlternateSmoothRotateButton, device);
			state.FlyModeModifierButton = ReadPress(map.FlyModeModifierButton, device);
			state.PickupAxis = ReadAxis(map.PickupButtons, device);
			state.SmoothSwipeRotateAxis = ReadAxis2D(map.SmoothSwipeRotateAxis, device, map.SmoothSwipeRotateAxisSettings);
			state.SprintButton = ReadPress(map.SprintButton, device);
			state.TriggerAxis = ReadAxis(map.TriggerButton, device);
			state.TriggerPressureValue = AxisSettings.ProcessValue(device.GetAxis(map.TriggerButton).x, map.TriggerSettings);
			state.RCTriggerAxis = ReadAxis(map.TriggerButton, device);
			state.RCControlStickAxis = ReadAxis2D(map.TeleportButton, device, map.RotateAxisSettings);
			state.RCMainButton = ReadPress(map.PushToTalkButton, device);
		}
	}
