public abstract class AltRenderedObject : UnityEngine.MonoBehaviour
{
	public bool NeverRender;

	public static List<AltRenderedObject> All = new List<AltRenderedObject>();

	protected virtual void Awake()
	{
		All.Add(this);
	}

	protected virtual void OnDestroy()
	{
		All.Remove(this);
	}

	public abstract void PreRender();

	public abstract void PostRender();
}
public class DisabledAltRenderedObject : AltRenderedObject
{
	private Renderer[] allRenderers = new Renderer[0];

	private bool[] renderersEnabled;

	public override void PreRender()
	{
		allRenderers = GetComponentsInChildren<Renderer>(includeInactive: true);
		renderersEnabled = new bool[allRenderers.Length];
		for (int i = 0; i < allRenderers.Length; i++)
		{
			Renderer renderer = allRenderers[i];
			if (renderer != null)
			{
				renderersEnabled[i] = renderer.enabled;
				renderer.enabled = false;
			}
		}
	}

	public override void PostRender()
	{
		for (int i = 0; i < allRenderers.Length; i++)
		{
			if (allRenderers[i] != null)
			{
				allRenderers[i].enabled = renderersEnabled[i];
			}
		}
	}
}
