namespace RecRoom
{
	public class JuniorVisibilityObject : VisibilityRestriction
	{
		public enum JuniorVisibility
		{
			NonJuniorOnly,
			JuniorOnly
		}

		public JuniorVisibility juniorVisibility;

		public static List<JuniorVisibilityObject> All = new List<JuniorVisibilityObject>();

		private bool isJunior;

		private void Awake()
		{
			All.Add(this);
		}

		private void OnDestroy()
		{
			All.Remove(this);
		}

		private void OnEnable()
		{
			SetJunior(Profiles.LocalProfile.IsJunior());
		}

		public void SetJunior(bool isJunior)
		{
			this.isJunior = isJunior;
			if (base.Initialized)
			{
				RefreshVisibility();
			}
		}

		protected override void RefreshVisibility()
		{
			bool flag = (isJunior && juniorVisibility == JuniorVisibility.JuniorOnly) || (!isJunior && juniorVisibility == JuniorVisibility.NonJuniorOnly);
			if (flag != base.gameObject.activeSelf)
			{
				base.gameObject.SetActive(flag);
			}
		}
	}
}
