		if (num2 < num)
		{
			isAnimatingRotation = false;
			base.transform.rotation = TargetRotation;
			if (this.RotationUpdated != null)
			{
				this.RotationUpdated(TargetRotation);
			}
		}
	}

	private void EvaluateScaleFrame()
	{
		if (!isAnimatingScale)
		{
			return;
		}
		float num = UnityEngine.Time.deltaTime * scaleSpeed;
		base.transform.localScale = Vector3.MoveTowards(base.transform.localScale, TargetScale, num);
		float magnitude = (TargetScale - base.transform.localScale).magnitude;
		if (magnitude < num)
		{
			isAnimatingScale = false;
			base.transform.localScale = TargetScale;
			if (this.ScaleUpdated != null)
			{
				this.ScaleUpdated(TargetScale);
			}
		}
	}

	public void StopInterpolation()
	{
		isAnimatingRotation = false;
		isAnimatingPosition = false;
		isAnimatingScale = false;
	}

	public void SnapToTarget()
	{
		base.transform.position = TargetPosition;
		base.transform.rotation = TargetRotation;
		base.transform.localScale = TargetScale;
