public class LaserTeleporter : UnityEngine.MonoBehaviour
{
	public enum LaserMode
	{
		ValidTeleportPosition,
		MissedTeleportSurface,
		InvalidTeleportDirection,
		RestrictedTeleportPosition,
		ValidPortalPosition,
		Cooldown,
		Disabled,
		InvalidPortalPosition,
		ValidLevelLoadPortal
	}

	private struct LaserCollisionData
	{
		public bool HitSomething;

		public bool HitColliderSupportsTeleport;

		public Vector3 TeleportTargetPosition;

		public Vector3 TeleportTargetNormal;

		public bool Reflected;

		public Vector3 ReflectionPoint;

		public Vector3 ReflectionTangent;

		public TeleportationPortal HitPortal;

		public FixedPathVehicle HitVehicle;

		public Tool HitTool;

		public Vector3 HitToolPosition;

		public Vector3 HitToolNormal;
	}

	private struct ToolHitData
	{
		public Vector3 Position;

		public Tool HitTool;

		public Vector3 HitToolPosition;

		public Vector3 HitToolNormal;

		public Vector3 HitToolDirection;
	}

	private delegate LaserCollisionData RunLaserCollision(Vector3 initialPosition, Vector3 initialDirection, Vector3 initialUp, float maxHorizontalDistance, float minWallAngle);

	[SerializeField]
	private Transform laserStartPosition;

	[SerializeField]
	private Transform visualRoot;

	[SerializeField]
	private ParabolicPointer parabolicPointer;

	[Header("Teleportation")]
	[SerializeField]
	private PlayerTeleportDecal playerTeleportDecalPrefab;

	[Tooltip("We will use this radius in CheckSphere to prevent you from teleporting into other sh.t")]
	[SerializeField]
	private float headCollisionRadius = 0.2f;

	[SerializeField]
	private float toolHitWindow = 0.25f;

	[Header("Collision")]
	[SerializeField]
	private BoxCollider worldOverlapCollider;

	[Header("Teleport Tool Hit")]
	[SerializeField]
	private FloatValueCurve toolHitForceCurve;

	private PlayerTeleportDecal playerTeleportDecal;

	private GameObject pointer;

	private float lastToolHitSelectionTime;

	private ToolHitData lastToolHitData;

	private TeleportationPortal lastLaserTeleportationPortal;

	private Vector3 lastLaserInitialTangent;

	private FixedPathVehicle lastLaserHitVehicle;

	[NonSerialized]
	public bool DecalCylinderVisible;

	private Color? laserColor;

	public Action<Color?> LaserColorChanged;

	private Vector3 teleportTarget = Vector3.zero;

	private LaserMode _laserMode = LaserMode.Disabled;

	[HideInInspector]
	public Player Player { get; internal set; }

	public PlayerHand Hand { get; internal set; }

	public bool Visible
	{
		get
		{
			return visualRoot.gameObject.activeSelf;
		}
		set
		{
			visualRoot.gameObject.SetActive(value);
		}
	}

	public Color? LaserColor
	{
		get
		{
			return laserColor;
		}
		set
		{
			if (!(laserColor == value))
			{
				laserColor = value;
				if (!value.HasValue || !value.HasValue)
				{
					parabolicPointer.LaserColor = ParabolicPointer.DefaultLaserColor.Value;
					playerTeleportDecal.Color = PlayerTeleportDecal.DefaultColor.Value;
				}
				else
				{
					parabolicPointer.LaserColor = value.Value;
					playerTeleportDecal.Color = value.Value;
				}
				if (LaserColorChanged != null)
				{
					LaserColorChanged(laserColor);
				}
			}
		}
	}

	public bool TeleportLaserVisible => laserMode != LaserMode.Disabled;

	private bool ToolHitThisFrame => IsWithinToolHitWindow(2f * UnityEngine.Time.deltaTime);

	private LaserMode laserMode
	{
		get
		{
			return _laserMode;
		}
		set
		{
			if (_laserMode != value)
			{
				bool flag = (Hand != null && Hand.isLocal) || DecalCylinderVisible;
				_laserMode = value;
				switch (_laserMode)
				{
				case LaserMode.Disabled:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Disabled;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
					break;
				case LaserMode.MissedTeleportSurface:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.FadeOut;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.INVALID;
					break;
				case LaserMode.InvalidTeleportDirection:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Shortened;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
					break;
				case LaserMode.RestrictedTeleportPosition:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Invalid;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.BASE_ONLY;
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.INVALID;
					break;
				case LaserMode.ValidTeleportPosition:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
					playerTeleportDecal.VisibilityMode = ((!flag) ? PlayerTeleportDecal.DecalVisibilityMode.BASE_ONLY : PlayerTeleportDecal.DecalVisibilityMode.BASE_AND_BEAM);
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.VALID;
					break;
				case LaserMode.ValidPortalPosition:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
					playerTeleportDecal.VisibilityMode = ((!flag) ? PlayerTeleportDecal.DecalVisibilityMode.BASE_ONLY : PlayerTeleportDecal.DecalVisibilityMode.BASE_AND_BEAM);
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.VALID;
					break;
				case LaserMode.InvalidPortalPosition:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Invalid;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.BASE_ONLY;
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.INVALID;
					break;
				case LaserMode.Cooldown:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
					playerTeleportDecal.VisibilityMode = ((!flag) ? PlayerTeleportDecal.DecalVisibilityMode.BASE_ONLY : PlayerTeleportDecal.DecalVisibilityMode.BASE_AND_BEAM);
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.VALID;
					break;
				case LaserMode.ValidLevelLoadPortal:
					parabolicPointer.Mode = ParabolicPointer.MeshMode.Valid;
					playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
					playerTeleportDecal.TargetValidity = PlayerTeleportDecal.DecalTargetValidity.VALID;
					break;
				}
			}
		}
	}

	private float Now => (float)PhotonNetwork.time;

	private void Awake()
	{
		playerTeleportDecal = UnityEngine.Object.Instantiate(playerTeleportDecalPrefab);
		playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
		parabolicPointer.transform.localPosition = laserStartPosition.localPosition;
		parabolicPointer.LaserTeleporter = this;
		visualRoot.gameObject.SetActive(value: false);
	}

	private void Start()
	{
		Player.SetParentPlayerRoot(playerTeleportDecal.transform);
		GameObject obj = base.gameObject;
		obj.name = obj.name + "_" + Hand.Type;
	}

	private void OnDestroy()
	{
		if (pointer != null)
		{
			UnityEngine.Object.Destroy(pointer.gameObject);
		}
		if (playerTeleportDecal != null)
		{
			UnityEngine.Object.Destroy(playerTeleportDecal.gameObject);
		}
	}

	private void OnDisable()
	{
		if (pointer != null)
		{
			pointer.gameObject.SetActive(value: false);
		}
		if (playerTeleportDecal != null)
		{
			playerTeleportDecal.VisibilityMode = PlayerTeleportDecal.DecalVisibilityMode.NONE;
		}
	}

	public void UpdateTeleportTargetParabolic(Vector3 laserInitialPosition, Vector3 laserInitialDirection, Vector3 laserUpVector)
	{
		LaserCollisionData result = default(LaserCollisionData);
		laserMode = UpdateLaserInternal(RunLaserParabolaCollision, laserInitialPosition, laserInitialDirection, laserUpVector, testOverlap: true, Player.PlayerLocomotion.MaxTeleportHorizontalDistance, Player.PlayerLocomotion.MaxTeleportHorizontalSurfaceAngle, ref result);
		UpdateDecal();
	}

	public void TryToTeleport()
	{
		if ((laserMode == LaserMode.ValidPortalPosition || laserMode == LaserMode.ValidLevelLoadPortal) && lastLaserTeleportationPortal != null)
		{
			lastLaserTeleportationPortal.Use(Player);
		}
		else if (laserMode == LaserMode.ValidTeleportPosition)
		{
			PerformTeleport(teleportTarget);
		}
		ResetTarget();
	}

	public void ResetTarget()
	{
		laserMode = LaserMode.Disabled;
		parabolicPointer.ClearParabolicRaycasts();
	}

	private LaserMode UpdateLaserInternal(RunLaserCollision collisionMethod, Vector3 initialPosition, Vector3 initialDirection, Vector3 initialUp, bool testOverlap, float maxHorizontalDistance, float minWallAngle, ref LaserCollisionData result)
	{
		if (Player.PlayerLocomotion.MovementRestricted)
		{
			return LaserMode.Disabled;
		}
		if (Player.IsOutOfWorldBounds)
		{
			return LaserMode.Disabled;
		}
		if (testOverlap)
		{
			Quaternion quaternion = Quaternion.LookRotation(initialDirection, initialUp);
			Vector3 worldSpaceCenter = worldOverlapCollider.center.TransformCoordinateSpace(initialPosition, quaternion);
			Collider boxColliderOverlap = CollisionDetection.GetBoxColliderOverlap(worldSpaceCenter, quaternion, worldOverlapCollider.size, 67128320, CollisionDetection.CollidesWithMovementIgnoringPlayers, QueryTriggerInteraction.Ignore);
			if (boxColliderOverlap != null)
			{
				return LaserMode.Disabled;
			}
		}
		if (Vector3.Angle(initialDirection, Vector3.up) < Player.PlayerLocomotion.MaxTeleportPitchDegrees)
		{
			return LaserMode.InvalidTeleportDirection;
		}
		result = collisionMethod(initialPosition, initialDirection, initialUp, maxHorizontalDistance, minWallAngle);
		lastLaserInitialTangent = initialDirection;
		lastLaserTeleportationPortal = result.HitPortal;
		lastLaserHitVehicle = result.HitVehicle;
		if (result.HitTool != null)
		{
			lastToolHitSelectionTime = UnityEngine.Time.time;
			lastToolHitData = new ToolHitData
			{
				Position = result.TeleportTargetPosition,
				HitTool = result.HitTool,
				HitToolPosition = result.HitToolPosition,
				HitToolNormal = result.HitToolNormal,
				HitToolDirection = (result.TeleportTargetPosition - initialPosition).normalized
			};
		}
		if (!result.HitSomething)
		{
			teleportTarget = result.TeleportTargetPosition;
			return LaserMode.MissedTeleportSurface;
		}
		if (result.HitPortal != null && result.HitPortal.IsValid)
		{
			result.HitPortal.RenderHighlight();
			teleportTarget = result.HitPortal.DestinationPosition;
			if (Player.PlayerLocomotion.TeleportOnCooldown)
			{
				return LaserMode.Cooldown;
			}
			if (!result.HitPortal.SupportsLaserTeleportPreview)
			{
				return LaserMode.ValidLevelLoadPortal;
			}
			if (CheckSafeTeleportPosition(teleportTarget, isPortalTeleport: true))
			{
				return LaserMode.ValidPortalPosition;
			}
			return LaserMode.InvalidPortalPosition;
		}
		teleportTarget = result.TeleportTargetPosition;
		if (Player.PlayerLocomotion.TeleportOnCooldown)
		{
			return LaserMode.Cooldown;
		}
		if (result.HitColliderSupportsTeleport && CheckSafeTeleportPosition(result.TeleportTargetPosition, isPortalTeleport: false))
		{
			return LaserMode.ValidTeleportPosition;
		}
		return LaserMode.RestrictedTeleportPosition;
	}

	private LaserCollisionData RunLaserParabolaCollision(Vector3 initialPosition, Vector3 initialDirection, Vector3 initialUp, float maxHorizontalDistance, float minWallAngle)
	{
		parabolicPointer.ClearParabolicRaycasts();
		parabolicPointer.PerformParabolicRaycasts(initialPosition, initialDirection, maxHorizontalDistance, Player.PlayerLocomotion.MaxTeleportDropDistance, minWallAngle);
		return new LaserCollisionData
		{
			HitSomething = parabolicPointer.HitSomething,
			HitColliderSupportsTeleport = parabolicPointer.HitColliderSupportsTeleport,
			TeleportTargetPosition = parabolicPointer.FinalParabolaPoint,
			HitPortal = parabolicPointer.TeleportationPortal,
			HitTool = parabolicPointer.HitTool,
			HitToolPosition = parabolicPointer.HitToolPosition,
			HitToolNormal = parabolicPointer.HitToolNormal,
			HitVehicle = parabolicPointer.HitVehicle
		};
	}

	private bool IsPointOnWall(Vector3 point, Vector3 normal, float minWallAngle)
	{
		float num = Mathf.Abs(Vector3.Angle(normal, Vector3.up));
		return num >= minWallAngle;
	}

	private void UpdateDecal()
	{
		if (playerTeleportDecal.VisibilityMode != PlayerTeleportDecal.DecalVisibilityMode.NONE)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(lastLaserInitialTangent, Vector3.up).normalized;
			playerTeleportDecal.UpdatePosition(teleportTarget, normalized);
			playerTeleportDecal.UpdateCharge(Player.PlayerLocomotion.TeleportCooldownValueInstantaneous);
			bool flag = Hand.isLocal && ToolHitThisFrame;
			playerTeleportDecal.UpdateToolHitDecal(flag, 1f, lastToolHitData.HitToolPosition, lastToolHitData.HitToolNormal);
		}
	}

	public void PerformTeleport(Vector3 position)
	{
		if (lastToolHitData.HitTool != null && IsWithinToolHitWindow(toolHitWindow))
		{
			ApplyForceToLastHitTool();
		}
		RigidbodyEx teleportRelativeRigidbody = ((!(lastLaserHitVehicle != null)) ? null : lastLaserHitVehicle.RigidbodyEx);
		Player.PlayerLocomotion.TeleportTo(position, null, canCarryTools: true, teleportRelativeRigidbody);
		Hand.Vibrate();
	}

	private void ApplyForceToLastHitTool()
	{
		lastToolHitData.HitTool.ApplyPlayerLocomotionAttack(lastToolHitData.HitToolPosition, lastToolHitData.HitToolDirection, toolHitForceCurve.Evaluate(1f));
	}

	private bool IsWithinToolHitWindow(float window)
	{
		return UnityEngine.Time.time - lastToolHitSelectionTime < window;
	}

	private bool CheckSafeTeleportPosition(Vector3 newPlayerFloorPosition, bool isPortalTeleport)
	{
		Vector3 vector = newPlayerFloorPosition + Player.Head.HeightOffset - Vector3.up * (headCollisionRadius + 0.01f);
		if (!isPortalTeleport)
		{
			Vector3 capsuleBottomPosition = newPlayerFloorPosition + Vector3.up * (2f * headCollisionRadius + 0.01f);
			if (CollisionDetection.IsCapsuleColliderOverlapping(capsuleBottomPosition, vector, headCollisionRadius, 3073, CollisionDetection.CollidesWithMovement))
			{
				return false;
			}
		}
		else if (Physics.CheckSphere(vector, headCollisionRadius + 0.01f, 3073, QueryTriggerInteraction.Ignore))
		{
			return false;
		}
		return true;
	}

	public void HandlePhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			LaserMode laserMode = (LaserMode)stream.ReceiveNext();
			this.laserMode = ((!Hand.ThisPlayer.IsVisible) ? LaserMode.Disabled : laserMode);
			if (laserMode != LaserMode.Disabled)
			{
				teleportTarget = (Vector3)stream.ReceiveNext();
				Vector3 initialPoint = (Vector3)stream.ReceiveNext();
				Vector3 initialTangent = (Vector3)stream.ReceiveNext();
				Vector3 finalPoint = (Vector3)stream.ReceiveNext();
				Vector3 finalPointTangent = (Vector3)stream.ReceiveNext();
				if ((bool)stream.ReceiveNext())
				{
					Vector3 reflectionPoint = (Vector3)stream.ReceiveNext();
					Vector3 reflectionTangent = (Vector3)stream.ReceiveNext();
					parabolicPointer.SetParabolaPointsWithReflection(initialPoint, initialTangent, reflectionPoint, reflectionTangent, finalPoint, finalPointTangent);
				}
				else
				{
					parabolicPointer.SetParabolaPoints(initialPoint, initialTangent, finalPoint, finalPointTangent);
				}
				lastLaserInitialTangent = initialTangent;
				UpdateDecal();
			}
			return;
		}
		stream.SendNext((int)this.laserMode);
		if (this.laserMode != LaserMode.Disabled)
		{
			stream.SendNext(teleportTarget);
			stream.SendNext(parabolicPointer.InitialParabolaPoint);
			stream.SendNext(parabolicPointer.InitialParabolaTangent);
			stream.SendNext(parabolicPointer.FinalParabolaPoint);
			stream.SendNext(parabolicPointer.FinalParabolaTangent);
			stream.SendNext(parabolicPointer.Reflected);
			if (parabolicPointer.Reflected)
			{
				stream.SendNext(parabolicPointer.ReflectionPoint);
				stream.SendNext(parabolicPointer.ReflectionTangent);
			}
		}
	}
}
