public class ParabolicPointer : UnityEngine.MonoBehaviour
{
	public enum MeshMode
	{
		Valid,
		Invalid,
		Shortened,
		Disabled,
		Invisible,
		FadeOut
	}

	private const int MAX_PARABOLA_SEGMENTS = 20;

	private const float MAX_HORIZONTAL_SURFACE_ANGLE = 30f;

	[Header("Parabola Mesh Properties")]
	[SerializeField]
	private float parabolaSegmentLength = 1f;

	[SerializeField]
	private float meshDistanceBetweenVertices = 0.05f;

	[SerializeField]
	private float meshWidth = 0.04f;

	[SerializeField]
	private Vector2 uvScale = Vector2.one;

	[SerializeField]
	private float shortenedDistance = 0.66f;

	[SerializeField]
	private float reflectionOffset = 0.5f;

	[SerializeField]
	[Tooltip("Limit the number of sample points for the parabolic mesh. This will make the mesh arc looks less smooth if you are drawing it for a long range")]
	private int maxSampleCount = 50;

	[SerializeField]
	[Tooltip("If the parabolic path is too long, it might be a bug or a latency issue, do not try to draw a really long path.")]
	private float maxPathLength = 50f;

	[Header("Fade Out Tunables")]
	[SerializeField]
	private float startFadeBeginDistance = 0.1f;

	[SerializeField]
	private float startFadeEndDistance = 0.3f;

	[SerializeField]
	private float endFadeBeginDistance = 0.33f;

	[SerializeField]
	private float endFadeEndDistance = 0.66f;

	public float PersonalSpaceFromLaser = 1f;

	[SerializeField]
	private Material validTargetMaterial;

	[SerializeField]
	private Material invalidTargetMaterial;

	[SerializeField]
	private Material fadeOutMaterial;

	[SerializeField]
	private Material shortenedTargetMaterial;

	private static int SHADER_COLOR_ID = Shader.PropertyToID("_TintColor");

	private Mesh parabolaMesh;

	private List<Vector3> laserScratchSpace;

	private BezierPath bezierPath = new BezierPath();

	private List<Vector3> meshVertices = new List<Vector3>(256);

	private List<Color> meshColors = new List<Color>();

	private List<Vector2> meshUVs = new List<Vector2>(256);

	private List<Vector2> meshUV2s = new List<Vector2>(256);

	private List<int> meshIndices = new List<int>(2048);

	private TeleportationPortal _teleportationPortal;

	public Tool HitTool;

	public Vector3 HitToolPosition = Vector3.zero;

	public Vector3 HitToolNormal = Vector3.zero;

	public FixedPathVehicle HitVehicle;

	public bool HitSomething;

	public bool HitColliderSupportsTeleport;

	private Material _runtimeValidTargetMaterial;

	public float ArcSpeed = 2f;

	private RaycastHit lastHit = default(RaycastHit);

	public Vector3 InitialParabolaPoint { get; private set; }

	public Vector3 InitialParabolaTangent { get; private set; }

	public Vector3 FinalParabolaTangent { get; private set; }

	public Vector3 FinalParabolaPoint { get; private set; }

	public bool Reflected { get; private set; }

	public Vector3 ReflectionPoint { get; private set; }

	public Vector3 ReflectionTangent { get; private set; }

	public float CurrentParabolaAngle { get; private set; }

	public MeshMode Mode { get; set; }

	public LaserTeleporter LaserTeleporter { get; set; }

	public TeleportationPortal TeleportationPortal
	{
		get
		{
			return _teleportationPortal;
		}
		set
		{
			if (_teleportationPortal != value)
			{
				if (_teleportationPortal != null)
				{
					_teleportationPortal.Highlight = false;
				}
				if (value != null && LaserTeleporter.Visible)
				{
					value.Highlight = true;
					_teleportationPortal = value;
				}
				else
				{
					_teleportationPortal = null;
				}
			}
		}
	}

	public bool PointOnNavMesh { get; internal set; }

	public Color LaserColor
	{
		get
		{
			return RuntimeValidTargetMaterial.GetColor(SHADER_COLOR_ID);
		}
		set
		{
			value.a = DefaultLaserColor.Value.a;
			RuntimeValidTargetMaterial.SetColor(SHADER_COLOR_ID, value);
		}
	}

	private Material RuntimeValidTargetMaterial
	{
		get
		{
			if (_runtimeValidTargetMaterial == null)
			{
				_runtimeValidTargetMaterial = new Material(validTargetMaterial);
			}
			return _runtimeValidTargetMaterial;
		}
	}

	public static Color? DefaultLaserColor { get; private set; }

	private Material LaserMaterial => Mode switch
	{
		MeshMode.Valid => RuntimeValidTargetMaterial, 
		MeshMode.Invalid => invalidTargetMaterial, 
		MeshMode.Shortened => shortenedTargetMaterial, 
		MeshMode.FadeOut => fadeOutMaterial, 
		_ => invalidTargetMaterial, 
	};

	private void Awake()
	{
		if (!DefaultLaserColor.HasValue)
		{
			DefaultLaserColor = LaserColor;
		}
		LaserColor = DefaultLaserColor.Value;
	}

	private void Start()
	{
		laserScratchSpace = new List<Vector3>(20);
		parabolaMesh = new Mesh();
		parabolaMesh.MarkDynamic();
		parabolaMesh.name = "Parabolic Pointer";
		parabolaMesh.vertices = new Vector3[0];
		parabolaMesh.triangles = new int[0];
		Mode = MeshMode.Disabled;
	}

	private void Update()
	{
		if (Mode != MeshMode.Disabled && Mode != MeshMode.Invisible && LaserTeleporter.Visible)
		{
			bezierPath = GenerateBezierPath(InitialParabolaTangent);
			GenerateMesh(ref parabolaMesh, bezierPath, meshDistanceBetweenVertices, InitialParabolaTangent, UnityEngine.Time.time * ArcSpeed % 1f);
			Graphics.DrawMesh(parabolaMesh, Matrix4x4.identity, LaserMaterial, 2);
		}
	}

	public void PerformParabolicRaycasts(Vector3 initialPoint, Vector3 initialForward, float maxHorizontalDistance, float maxDropDistance, float maxBounceHorizontalSurfaceAngle)
	{
		ClearRaycast();
		laserScratchSpace.Clear();
		Vector3 a = CalculateParabolaAcceleration(initialForward, maxHorizontalDistance);
		HitSomething = CalculateParabolaPoints(initialPoint, initialForward, a, parabolaSegmentLength, maxDropDistance);
		Vector3 normalized = (laserScratchSpace[1] - laserScratchSpace[0]).normalized;
		Vector3 vector = laserScratchSpace[laserScratchSpace.Count - 1];
		Vector3 normalized2 = (laserScratchSpace[laserScratchSpace.Count - 2] - vector).normalized;
		Vector3 reflectionPoint = Vector3.zero;
		Vector3 reflectionPointTangent = Vector3.zero;
		Vector3 vector2 = Vector3.zero;
		bool flag = false;
		float num = Mathf.Abs(Vector3.Angle(lastHit.normal, Vector3.up));
		if (HitSomething && TeleportationPortal == null && (HitTool != null || num > ((!HitColliderSupportsTeleport) ? 30f : maxBounceHorizontalSurfaceAngle)))
		{
			vector2 = initialForward;
			if (HitSomething)
			{
				vector2 = lastHit.normal;
				if (Mathf.Abs(Vector3.Dot(vector2, Vector3.up)) <= 1f - Mathf.Epsilon)
				{
					vector2 = Vector3.ProjectOnPlane(vector2, Vector3.up).normalized;
				}
			}
			HitColliderSupportsTeleport = false;
			bool reflectionHitSomething = false;
			if (CalculateReflection(vector2, parabolaSegmentLength, reflectionOffset, maxDropDistance, maxBounceHorizontalSurfaceAngle, out reflectionPoint, out reflectionPointTangent, out reflectionHitSomething))
			{
				flag = true;
				HitSomething &= reflectionHitSomething;
				vector = laserScratchSpace[laserScratchSpace.Count - 1];
				normalized2 = (laserScratchSpace[laserScratchSpace.Count - 2] - vector).normalized;
			}
		}
		if (flag)
		{
			Vector3 normalized3 = (vector - reflectionPoint + 0.25f * vector2).normalized;
			SetParabolaPointsWithReflection(initialPoint, normalized, reflectionPoint, normalized3, vector, normalized2);
		}
		else
		{
			SetParabolaPoints(initialPoint, normalized, vector, normalized2);
		}
		if (HitColliderSupportsTeleport)
		{
			HitColliderSupportsTeleport = !IsPointWithinPlayerPersonalSpace(vector);
		}
	}

	public void ClearParabolicRaycasts()
	{
		ClearRaycast();
	}

	public void SetParabolaPoints(Vector3 initialPoint, Vector3 initialTangent, Vector3 finalPoint, Vector3 finalPointTangent)
	{
		Reflected = false;
		InitialParabolaPoint = initialPoint;
		InitialParabolaTangent = initialTangent;
		FinalParabolaPoint = finalPoint;
		FinalParabolaTangent = finalPointTangent;
		ReflectionPoint = Vector3.zero;
		ReflectionTangent = Vector3.zero;
	}

	public void SetParabolaPointsWithReflection(Vector3 initialPoint, Vector3 initialTangent, Vector3 reflectionPoint, Vector3 reflectionTangent, Vector3 finalPoint, Vector3 finalPointTangent)
	{
		Reflected = true;
		InitialParabolaPoint = initialPoint;
		InitialParabolaTangent = initialTangent;
		ReflectionPoint = reflectionPoint;
		ReflectionTangent = reflectionTangent;
		FinalParabolaPoint = finalPoint;
		FinalParabolaTangent = finalPointTangent;
	}

	private bool DoRaycast(Vector3 origin, Vector3 direction, float maxDistance, out RaycastHit hit, bool updateHitTool = true)
	{
		CollisionDetection.CollisionResult collisionResult = CollisionDetection.Raycast(origin, direction, maxDistance, 67128320, CollisionDetection.CollidesWithMovementIgnoringPlayers, QueryTriggerInteraction.Collide, out hit);
		if (collisionResult == CollisionDetection.CollisionResult.HIT)
		{
			TeleportationPortal hitPortal = null;
			Tool hitTool = null;
			GetHitColliderState(hit.collider, ref HitColliderSupportsTeleport, ref hitPortal, ref HitVehicle, ref hitTool);
			TeleportationPortal = hitPortal;
			if ((bool)hitTool && updateHitTool)
			{
				HitTool = hitTool;
				HitToolNormal = hit.normal;
				HitToolPosition = hit.point;
			}
			return true;
		}
		return false;
	}

	private static void GetHitColliderState(Collider collider, ref bool supportsTeleport, ref TeleportationPortal hitPortal, ref FixedPathVehicle hitVehicle, ref Tool hitTool)
	{
		supportsTeleport = false;
		hitPortal = null;
		hitVehicle = null;
		if (collider.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics))
		{
			Tool colliderTool = collider.GetColliderTool();
			if (colliderTool != null && !colliderTool.IsHeld && colliderTool.SupportsPlayerLocomotionAttacks)
			{
				hitTool = colliderTool;
			}
		}
		if (CollisionDetection.CollidesWithMovement(collider))
		{
			supportsTeleport = CollisionDetection.CanPlayerStandOnCollider(collider);
			hitPortal = collider.gameObject.GetComponent<TeleportationPortal>();
			hitVehicle = collider.GetColliderVehicle();
		}
	}

	private void ClearRaycast()
	{
		TeleportationPortal = null;
		HitTool = null;
		HitToolPosition = Vector3.zero;
		HitToolNormal = Vector3.zero;
		HitVehicle = null;
		HitColliderSupportsTeleport = false;
	}

	private static float ParabolicCurve(float p0, float v0, float a, float t)
	{
		return p0 + v0 * t + 0.5f * a * t * t;
	}

	private static float ParabolicCurveDeriv(float v0, float a, float t)
	{
		return v0 + a * t;
	}

	private static Vector3 ParabolicCurve(Vector3 p0, Vector3 v0, Vector3 a, float t)
	{
		Vector3 result = default(Vector3);
		for (int i = 0; i < 3; i++)
		{
			result[i] = ParabolicCurve(p0[i], v0[i], a[i], t);
		}
		return result;
	}

	private static Vector3 ParabolicCurveDeriv(Vector3 v0, Vector3 a, float t)
	{
		Vector3 result = default(Vector3);
		for (int i = 0; i < 3; i++)
		{
			result[i] = ParabolicCurveDeriv(v0[i], a[i], t);
		}
		return result;
	}

	private bool CalculateParabolaPoints(Vector3 initialPoint, Vector3 initialForward, Vector3 a, float segmentLength, float maxDropDistance)
	{
		maxDropDistance = Mathf.Abs(maxDropDistance);
		bool result = false;
		Vector3 vector = initialPoint;
		laserScratchSpace.Add(vector);
		Vector3 vector2 = vector;
		float num = 0f;
		Vector3 vector3 = vector;
		RaycastHit hit = default(RaycastHit);
		for (int i = 0; i < 20; i++)
		{
			num += segmentLength / ParabolicCurveDeriv(initialForward, a, num).magnitude;
			vector3 = ParabolicCurve(vector, initialForward, a, num);
			Vector3 vector4 = vector3 - vector2;
			float magnitude = vector4.magnitude;
			Vector3 direction = vector4 / magnitude;
			float magnitude2 = Vector3.Project(vector4, initialForward).magnitude;
			float num2 = vector.y - vector3.y;
			if (num2 > maxDropDistance)
			{
				break;
			}
			if (DoRaycast(vector2, direction, magnitude, out hit))
			{
				result = true;
				lastHit = hit;
				laserScratchSpace.Add(hit.point);
				break;
			}
			laserScratchSpace.Add(vector3);
			vector2 = vector3;
		}
		return result;
	}

	private static bool IsPointWithinPlayerPersonalSpace(Vector3 point)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			Player player = photonPlayer.ToPlayer();
			if (player != null)
			{
				Vector3 currentFloorPosition = player.CurrentFloorPosition;
				float personalSpaceDistance = player.PlayerLocomotion.PersonalSpaceDistance;
				float sqrMagnitude = (currentFloorPosition - point).sqrMagnitude;
				if (sqrMagnitude <= personalSpaceDistance * personalSpaceDistance)
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool FindFirstLineSegmentCylinderItersection(Vector3 p1, Vector3 p2, Vector3 center, float radius, out Vector3 intersection)
	{
		Vector3 vector = p2 - p1;
		float num = vector.x * vector.x + vector.z * vector.z;
		if (num < Mathf.Epsilon)
		{
			intersection = Vector2.zero;
			return false;
		}
		Vector3 vector2 = p1 - center;
		float num2 = 2f * (vector.x * vector2.x + vector.z * vector2.z);
		float num3 = vector2.x * vector2.x + vector2.z * vector2.z - radius * radius;
		float num4 = -1f;
		float num5 = num2 * num2 - 4f * num * num3;
		if (!(num5 < 0f))
		{
			if (num5 == 0f)
			{
				num4 = (0f - num2) / (2f * num);
			}
			else
			{
				float num6 = Mathf.Sqrt(num5);
				float num7 = (0f - num2 + num6) / (2f * num);
				float num8 = (0f - num2 - num6) / (2f * num);
				num4 = ((!(num7 < 0f) && !(num7 > 1f)) ? ((!(num8 < 0f) && !(num8 > 1f)) ? Mathf.Min(num7, num8) : num7) : num8);
			}
		}
		intersection = p1 + num4 * vector;
		return num4 >= 0f && num4 <= 1f;
	}

	private bool CalculateReflection(Vector3 reflectionPointNormal, float segmentLength, float desiredReflectionOffset, float maxDropDistance, float maxValidSurfaceAngle, out Vector3 reflectionPoint, out Vector3 reflectionPointTangent, out bool reflectionHitSomething)
	{
		reflectionHitSomething = false;
		reflectionPoint = laserScratchSpace[laserScratchSpace.Count - 1];
		reflectionPointTangent = (laserScratchSpace[laserScratchSpace.Count - 2] - reflectionPoint).normalized;
		Vector3 vector = reflectionPoint + reflectionPointNormal * desiredReflectionOffset;
		bool result = false;
		bool flag = false;
		while (laserScratchSpace.Count < 20)
		{
			Vector3 vector2 = vector - Vector3.up * segmentLength;
			float num = reflectionPoint.y - vector2.y;
			if (num > maxDropDistance)
			{
				laserScratchSpace.Add(vector2);
				result = true;
				break;
			}
			Vector3 vector3 = vector2 - vector;
			float magnitude = vector3.magnitude;
			Vector3 direction = vector3 / magnitude;
			if (DoRaycast(vector, direction, magnitude, out var hit, updateHitTool: false))
			{
				result = true;
				float num2 = Mathf.Abs(Vector3.Angle(hit.normal, Vector3.up));
				reflectionHitSomething = num2 <= maxValidSurfaceAngle;
				if (!flag)
				{
					flag = true;
					laserScratchSpace.Add(vector);
				}
				laserScratchSpace.Add(hit.point);
				break;
			}
			laserScratchSpace.Add(vector2);
			vector = vector2;
		}
		return result;
	}

	private BezierPath GenerateBezierPath(Vector3 defaultTangent)
	{
		bezierPath.Clear();
		if (Mode == MeshMode.Shortened)
		{
			Vector3 vector = defaultTangent * shortenedDistance;
			Vector3 end = InitialParabolaPoint + vector;
			Vector3 vector2 = InitialParabolaPoint + 0.5f * vector;
			bezierPath.AddCurve(InitialParabolaPoint, vector2, vector2, end);
		}
		else if (HitTool != null)
		{
			AddBezierPath(InitialParabolaPoint, InitialParabolaTangent, ReflectionPoint, FinalParabolaTangent);
		}
		else if (Reflected)
		{
			AddBezierPath(InitialParabolaPoint, InitialParabolaTangent, ReflectionPoint, FinalParabolaTangent);
			CalculateParabolaControlPoints(ReflectionPoint, ReflectionTangent, FinalParabolaPoint, Vector3.up, out var initialControlPoint, out var finalControlPoint);
			bezierPath.AddCurve(initialControlPoint, finalControlPoint, FinalParabolaPoint);
		}
		else
		{
			AddBezierPath(InitialParabolaPoint, InitialParabolaTangent, FinalParabolaPoint, FinalParabolaTangent);
		}
		return bezierPath;
	}

	private void AddBezierPath(Vector3 initialPoint, Vector3 initialTangent, Vector3 finalPoint, Vector3 finalTangent)
	{
		CalculateParabolaControlPoints(initialPoint, InitialParabolaTangent, finalPoint, FinalParabolaTangent, out var initialControlPoint, out var finalControlPoint);
		bezierPath.AddCurve(initialPoint, initialControlPoint, finalControlPoint, finalPoint);
	}

	private void GenerateMesh(ref Mesh mesh, BezierPath path, float sampleLength, Vector3 forward, float uvoffset)
	{
		mesh.Clear();
		float pathLength = path.PathLength;
		if (pathLength > maxPathLength)
		{
			return;
		}
		int num = Mathf.RoundToInt(pathLength / sampleLength);
		if (num > maxSampleCount)
		{
			num = maxSampleCount;
		}
		Vector3 vector = Vector3.zero;
		Vector3 vector2 = Vector3.zero;
		if (path.CurveCount <= 0 || num <= 0)
		{
			return;
		}
		meshVertices.Clear();
		meshColors.Clear();
		meshUVs.Clear();
		meshUV2s.Clear();
		meshIndices.Clear();
		int num2 = 2 * num;
		int num3 = 12 * (num - 1);
		if (meshVertices.Capacity < num2)
		{
			meshVertices.Capacity = num2;
			meshColors.Capacity = num2;
			meshUVs.Capacity = num2;
			meshUV2s.Capacity = num2;
		}
		if (meshIndices.Capacity < num3)
		{
			meshIndices.Capacity = num3;
		}
		float num4 = (float)num * sampleLength;
		float num5 = meshWidth / 2f;
		Vector3 normalized = Vector3.Cross(forward, Vector3.up).normalized;
		for (int i = 0; i < num; i++)
		{
			Vector3 vector3 = path.EvaluatePath((float)i / ((float)num - 1f));
			meshVertices.Add(vector3 - normalized * num5);
			meshVertices.Add(vector3 + normalized * num5);
			float num6 = (float)i * sampleLength;
			float num7 = num4 - num6;
			float num8 = 1f;
			if (num6 <= startFadeEndDistance)
			{
				float b = Mathf.InverseLerp(startFadeBeginDistance, startFadeEndDistance, num6);
				num8 = Mathf.Min(num8, b);
			}
			if (num7 <= endFadeEndDistance)
			{
				float b2 = Mathf.InverseLerp(endFadeBeginDistance, endFadeEndDistance, num7);
				num8 = Mathf.Min(num8, b2);
			}
			Color item = Color.white * num8;
			meshColors.Add(item);
			meshColors.Add(item);
			float num9 = uvoffset;
			if (i == num - 1 && i > 1)
			{
				float magnitude = (vector2 - vector).magnitude;
				float magnitude2 = (vector3 - vector).magnitude;
				num9 += 1f - magnitude2 / magnitude;
			}
			meshUVs.Add(Vector2.Scale(new Vector2(0f, i), uvScale) - new Vector2(0f, num9));
			meshUVs.Add(Vector2.Scale(new Vector2(1f, i), uvScale) - new Vector2(0f, num9));
			float y = Mathf.InverseLerp(0f, num - 1, i);
			meshUV2s.Add(new Vector2(0f, y));
			meshUV2s.Add(new Vector2(1f, y));
			vector2 = vector;
			vector = vector3;
		}
		for (int j = 0; j < num - 1; j++)
		{
			int item2 = 2 * j;
			int item3 = 2 * j + 1;
			int item4 = 2 * j + 2;
			int item5 = 2 * j + 3;
			meshIndices.Add(item2);
			meshIndices.Add(item3);
			meshIndices.Add(item4);
			meshIndices.Add(item4);
			meshIndices.Add(item3);
			meshIndices.Add(item5);
			meshIndices.Add(item4);
			meshIndices.Add(item3);
			meshIndices.Add(item2);
			meshIndices.Add(item5);
			meshIndices.Add(item3);
			meshIndices.Add(item4);
		}
		mesh.SetVertices(meshVertices);
		mesh.SetColors(meshColors);
		mesh.SetUVs(0, meshUVs);
		mesh.SetUVs(1, meshUV2s);
		mesh.SetTriangles(meshIndices, 0);
		mesh.RecalculateNormals();
	}

	private void CalculateParabolaControlPoints(Vector3 initialPoint, Vector3 initialTangent, Vector3 finalPoint, Vector3 finalTangent, out Vector3 initialControlPoint, out Vector3 finalControlPoint)
	{
		float num = ((!(Vector3.Dot(initialTangent, finalTangent) >= 0.99f)) ? ((finalPoint - initialPoint).magnitude / (initialTangent - finalTangent).magnitude) : 0f);
		Vector3 vector = initialPoint + initialTangent * num;
		initialControlPoint = 0.33f * initialPoint + 0.67f * vector;
		finalControlPoint = 0.33f * finalPoint + 0.67f * vector;
	}

	private Vector3 CalculateParabolaAcceleration(Vector3 forward, float maxFloorDistance)
	{
		Vector3 normalized = Vector3.ProjectOnPlane(forward, Vector3.up).normalized;
		Vector3 normalized2 = Vector3.Cross(normalized, Vector3.up).normalized;
		Vector3 normalized3 = (Quaternion.AngleAxis(45f, normalized2) * normalized).normalized;
		float num = Vector3.Dot(normalized3, normalized);
		float num2 = maxFloorDistance / num;
		Vector3 vector = Vector3.Project(normalized3, Vector3.up);
		return -2f * vector / num2;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.white;
		if (lastHit.collider != null)
		{
			Gizmos.DrawWireSphere(lastHit.point + lastHit.normal, 0.1f);
			Gizmos.DrawLine(lastHit.point, lastHit.point + lastHit.normal);
		}
		if (laserScratchSpace != null)
		{
			for (int i = 1; i < laserScratchSpace.Count; i++)
			{
				Gizmos.color = Color.white;
				Gizmos.DrawSphere(laserScratchSpace[i], 0.02f);
				Gizmos.color = Color.yellow;
				Gizmos.DrawLine(laserScratchSpace[i - 1], laserScratchSpace[i]);
			}
		}
	}
}
public class PlayerFloorPositionFollowing : UnityEngine.MonoBehaviour
{
	[NonSerialized]
	public Player TrackedPlayer;

	[SerializeField]
	private Vector3 eulerAngleParentRotation = new Vector3(-90f, -90f, 0f);

	private void Update()
	{
		if (TrackedPlayer != null)
		{
			base.transform.position = TrackedPlayer.CurrentFloorPosition;
			Vector3 forward = Vector3.ProjectOnPlane(TrackedPlayer.Head.transform.forward, Vector3.up);
			base.transform.rotation = Quaternion.LookRotation(forward, Vector3.up) * Quaternion.Euler(eulerAngleParentRotation);
		}
	}
}
public class PlungerRigidbodyPickup : RigidbodyPickup
{
	[NonSerialized]
	public RigidbodyPickup ConstraintPickup;

	[NonSerialized]
	public Vector3 ConstraintOffsetPosition = Vector3.zero;

	[NonSerialized]
	public Quaternion ConstraintOffsetRotation = Quaternion.identity;

	[NonSerialized]
	public Vector3 ConstraintLocalAxis = Vector3.forward;

	[NonSerialized]
	public float MinimumConstraintDistance;

	[NonSerialized]
	public float MaximumConstraintDistance;

	[NonSerialized]
	public float CurrentDistance;

	public override Vector3 TargetPosition
	{
		get
		{
			if (ConstraintPickup == null)
			{
				return base.transform.position;
			}
			Vector3 constraintPosition = ConstraintPosition;
			if (!IsPickedUp)
			{
				return constraintPosition;
			}
			Vector3 constraintAxis = ConstraintAxis;
			Vector3 targetPosition = base.TargetPosition;
			Vector3 lhs = targetPosition - constraintPosition;
			float lossyUniformScale = ConstraintPickup.transform.GetLossyUniformScale();
			CurrentDistance = Mathf.Clamp(Vector3.Dot(lhs, constraintAxis), MinimumConstraintDistance * lossyUniformScale, MaximumConstraintDistance * lossyUniformScale);
			return constraintPosition + constraintAxis * CurrentDistance;
		}
	}

	public override Quaternion TargetRotation
	{
		get
		{
			if (ConstraintPickup == null)
			{
				return base.transform.rotation;
			}
			return ConstraintRotation;
		}
	}

	public Vector3 ConstraintPosition
	{
		get
		{
			float lossyUniformScale = ConstraintPickup.transform.GetLossyUniformScale();
			return (ConstraintOffsetPosition * lossyUniformScale).TransformCoordinateSpace(ConstraintPickup.TargetPosition, ConstraintPickup.TargetRotation);
		}
	}

	public Quaternion ConstraintRotation => ConstraintPickup.TargetRotation.TransformRotation(ConstraintOffsetRotation);

	public Vector3 ConstraintAxis => ConstraintLocalAxis.TransformCoordinateSpace(Vector3.zero, ConstraintRotation);
}
