	public void AddUpdateLodOverride(object token, UpdateLOD overrideVal)
	{
		if (_updateLodOverride.AddValue(token, overrideVal))
		{
			RefreshSchedulerUpdates();
		}
	}

	public void RemoveUpdateLodOverride(object token)
	{
		if (_updateLodOverride.RemoveValue(token))
		{
			RefreshSchedulerUpdates();
		}
	}

	private void Awake()
	{
		if (photonView == null)
		{
			photonView = GetComponentInParent<PhotonView>();
		}
		rigidbodyExCullingGroup = SingletonMonoBehaviour<CullingGroupManager>.Instance.GetOrCreateCullingGroup<RigidbodyEx>(350, 0);
		rigidbodyExCullingGroup.Add(this, 1f, CullingGroupSphereTransformTrackRate);
		hasUnityRigidbody = unityRigidbody != null;
		if (hasUnityRigidbody && customCenterOfMass.Overrides)
		{
			unityRigidbody.centerOfMass = customCenterOfMass.Value;
			ResetInertiaTensor();
		}
		RefreshSchedulerUpdates();
		ClearVelocity();
	}

	private void OnAuthorityChanged(PhotonPlayer newAuthority)
	{
		RefreshSchedulerUpdates();
	}

	private void Start()
	{
		if (RecRoomSceneManager.Instance != null)
		{
			ScenePhysicsSettings physicsSettings = RecRoomSceneManager.Instance.PhysicsSettings;
			physicsLODSettings = physicsSettings.LODSettings;
		}
		if (photonView != null)
		{
			PhotonView obj = photonView;
			obj.OnCachedAuthorityChanged = (PhotonView.OnCachedAuthorityChangedEvent)Delegate.Combine(obj.OnCachedAuthorityChanged, new PhotonView.OnCachedAuthorityChangedEvent(OnAuthorityChanged));
		}
		RefreshSchedulerUpdates();
	}

	private void OnEnable()
	{
		ClearVelocity();
	}

	private void OnDestroy()
	{
		UpdateToken = null;
		if (rigidbodyExCullingGroup != null)
		{
			rigidbodyExCullingGroup.Remove(this);
		}
		if (photonView != null)
		{
			PhotonView obj = photonView;
			obj.OnCachedAuthorityChanged = (PhotonView.OnCachedAuthorityChangedEvent)Delegate.Remove(obj.OnCachedAuthorityChanged, new PhotonView.OnCachedAuthorityChangedEvent(OnAuthorityChanged));
		}
		if (proxyTransform != null)
		{
			if (proxyTransform.childCount > 0)
			{
				proxyTransform.DetachChildren();
			}
			UnityEngine.Object.Destroy(proxyTransform.gameObject);
		}
		if (_parent != null)
		{
			_parent.DiscontinuityEvent -= OnParentDiscontinuity;
			_parent.LateUpdateEvent -= OnParentLateUpdate;
		}
	}

	public UpdateLOD GetActualUpdateLod()
	{
		UpdateLOD updateLOD;
		if (_updateLodOverride.HasTokens)
		{
			updateLOD = _updateLodOverride.MinValue;
		}
		else
		{
			updateLOD = UpdateLod;
			if (UseAuthorityUpdateLOD)
			{
				updateLOD = CullingGroupManager.MinUpdateLod(AuthorityMaxUpdateLod, updateLOD);
			}
		}
		return updateLOD;
	}

	private void RefreshSchedulerUpdates()
	{
		UpdateToken = null;
		if (!hasParent)
		{
			UpdateLOD actualUpdateLod = GetActualUpdateLod();
			float? num = ((physicsLODSettings != null) ? new float?(physicsLODSettings.GetUpdateRate(actualUpdateLod)) : ((float?)null));
			float num2 = ((!num.HasValue) ? ScenePhysicsSettings.PhysicsLODSettings.DefaultPhysicsSettings.GetUpdateRate(actualUpdateLod) : num.Value);
			if (num2 < 0f)
			{
				UpdateToken = this.RigidbodyExLateUpdate(LateUpdateInternal);
			}
			else if (num2 > 0f)
			{
				UpdateToken = this.QueueUpdateAtRate(num2, LateUpdateAtRate, Scheduler.QueueType.RigidbodyExLateUpdate);
			}
		}
	}

	private void LateUpdateAtRate(float deltaTime)
	{
		LateUpdateInternal();
	}

	private void LateUpdateInternal()
	{
		if (!IsPhysicsDriven)
		{
			CalculateKinematicPhysics();
		}
		if (MovesWithProxy)
		{
			if (this.PreProxyUpdateEvent != null)
			{
				this.PreProxyUpdateEvent(this);
			}
			MovePhysicsPositionInternal(proxyTransform.position);
			MovePhysicsRotationInternal(proxyTransform.rotation);
		}
		bool flag = IsSleeping();
		if (wasAsleep != flag && this.SleepChangedEvent != null)
		{
			this.SleepChangedEvent(this);
		}
		wasAsleep = flag;
		if (this.LateUpdateEvent != null)
		{
			this.LateUpdateEvent(this);
		}
	}

	private void OnParentLateUpdate(RigidbodyEx thisRigidbodyEx)
	{
		LateUpdateInternal();
	}

	private void AddHistoricalKinematicVelocity(Vector3 velocity)
	{
		linearKinematicVelocityHistory.Add(now, velocity);
	}

	private void AddHistoricalKinematicAngularVelocity(Vector3 angularVelocity)
	{
		angularKinematicVelocityHistory.Add(now, angularVelocity);
	}

	public void UpdateHistoricalKinematicVelocityFromRigidbody()
	{
		if (hasUnityRigidbody && !unityRigidbody.IsSleeping())
		{
			AddHistoricalKinematicVelocity(velocity);
			AddHistoricalKinematicAngularVelocity(angularVelocity);
		}
	}

	public void AddKinematic(object token)
	{
		SetKinematic(token, addKinematic: true);
	}

	public void RemoveKinematic(object token)
	{
		SetKinematic(token, addKinematic: false);
	}

	public void SetKinematic(object token, bool addKinematic)
	{
		if (addKinematic)
		{
			isKinematicFlag.Add(token);
		}
		else
		{
			isKinematicFlag.Remove(token);
		}
		isKinematic = isKinematicFlag.HasTokens;
	}

	private void OnIsKinematicChanged()
	{
		if (!isKinematic)
		{
			ResetVelocityLocalSpace(localVelocity, localAngularVelocity);
			numFramesKinematicSleep = 0;
		}
	}

	public void SetUseKinematicForces(object token, bool useKinematicForces)
	{
		if (useKinematicForces)
		{
			kinematicVelocityCalculationMode.AddValue(KinematicVelocityCalculationMode.Forces, token);
		}
		else
		{
			kinematicVelocityCalculationMode.RemoveValue(token);
		}
		ClearVelocity();
	}

	private void CalculateKinematicPhysics()
	{
		float num = now;
		float num2 = num - latestKinematicCalculationUpdateTime;
		if (!(num2 > 0f))
		{
			return;
		}
		Vector3 zero = Vector3.zero;
		Quaternion identity = Quaternion.identity;
		Vector3 vector = Vector3.zero;
		Vector3 vector2 = Vector3.zero;
		if (hasParent)
		{
			zero = targetLocalPosition;
			identity = targetLocalRotation;
		}
		else
		{
			zero = targetPosition;
			identity = targetRotation;
		}
		bool flag = false;
		if (kinematicVelocityCalculationMode.LatestValue == KinematicVelocityCalculationMode.Position)
		{
			vector = (zero - latestKinematicCalculationPosition) / num2;
			vector2 = UnityExtensions.AngularDisplacementFromTo(latestKinematicCalculationRotation, identity) / num2;
			flag = vector.sqrMagnitude > 9E-05f || vector2.sqrMagnitude > 0.0001f;
		}
		else if (kinematicVelocityCalculationMode.LatestValue == KinematicVelocityCalculationMode.Forces)
		{
			if (isSleepingKinematic)
			{
				num2 = UnityEngine.Time.deltaTime;
			}
			else
			{
				vector = latestKinematicCalculationVelocity;
				vector2 = latestKinematicCalculationAngularVelocity;
			}
			bool flag2 = torqueAppliedThisFrame.sqrMagnitude > float.Epsilon;
			if (linearAccelerationThisFrame.sqrMagnitude > float.Epsilon || angularAccelerationThisFrame.sqrMagnitude > float.Epsilon || forceAppliedThisFrame.sqrMagnitude > float.Epsilon || flag2 || vector.sqrMagnitude > 9E-05f || vector2.sqrMagnitude > 0.0001f)
			{
				flag = true;
				linearAccelerationThisFrame += forceAppliedThisFrame / mass;
				vector += linearAccelerationThisFrame;
				zero += vector * num2;
				if (flag2)
				{
					Quaternion quaternion = identity * inertiaTensorRotation;
					Quaternion quaternion2 = Quaternion.Inverse(quaternion);
					Vector3 b = new Vector3(1f / inertiaTensor.x, 1f / inertiaTensor.y, 1f / inertiaTensor.z);
					angularAccelerationThisFrame += quaternion * Vector3.Scale(quaternion2 * torqueAppliedThisFrame, b);
				}
				vector2 += angularAccelerationThisFrame;
				Vector3 axis = vector2 * 57.29578f * num2;
				identity = Quaternion.AngleAxis(axis.magnitude, axis) * identity;
				if (hasParent)
				{
					targetLocalPosition = zero;
					targetLocalRotation = identity;
				}
				else
				{
					targetPosition = zero;
					targetRotation = identity;
				}
				forceAppliedThisFrame = Vector3.zero;
				torqueAppliedThisFrame = Vector3.zero;
				angularAccelerationThisFrame = Vector3.zero;
				linearAccelerationThisFrame = Vector3.zero;
			}
		}
		else
		{
			if (hasParent)
			{
				vector = localVelocity;
				vector2 = localAngularVelocity;
			}
			else
			{
				vector = velocity;
				vector2 = angularVelocity;
			}
			flag = vector.sqrMagnitude > 9E-05f || vector2.sqrMagnitude > 0.0001f;
		}
		bool flag3 = isSleepingKinematic;
		if (flag)
		{
			if (isSleepingKinematic)
			{
				WakeUp();
			}
		}
		else if (!isSleepingKinematic)
		{
			numFramesKinematicSleep++;
			if (numFramesKinematicSleep >= 10)
			{
				Sleep();
			}
		}
		if (kinematicVelocityCalculationMode.LatestValue == KinematicVelocityCalculationMode.None || isSleepingKinematic)
		{
			return;
		}
		if (isSleepingKinematic != flag3)
		{
			if (hasParent)
			{
				ResetVelocityLocalSpace(vector, vector2);
			}
			else
			{
				ResetVelocityWorldSpace(vector, vector2);
			}
			return;
		}
		if (hasParent)
		{
			localVelocity = vector;
			localAngularVelocity = vector2;
		}
		else
		{
			velocity = vector;
			angularVelocity = vector2;
		}
		latestKinematicCalculationUpdateTime = num;
		latestKinematicCalculationPosition = zero;
		latestKinematicCalculationRotation = identity;
		latestKinematicCalculationVelocity = vector;
		latestKinematicCalculationAngularVelocity = vector2;
	}

	private void MovePhysicsPositionInternal(Vector3 newPosition)
	{
		if (hasUnityRigidbody && FollowProxiesWithPhysics)
		{
			if (unityRigidbody.position != newPosition)
			{
				unityRigidbody.MovePosition(newPosition);
			}
		}
		else if (base.transform.position != newPosition)
		{
			base.transform.position = newPosition;
		}
	}

	private void MovePhysicsRotationInternal(Quaternion newRotation)
	{
		if (hasUnityRigidbody && FollowProxiesWithPhysics)
		{
			if (!unityRigidbody.rotation.Equals(newRotation))
			{
				unityRigidbody.MoveRotation(newRotation);
			}
		}
		else if (!base.transform.rotation.Equals(newRotation))
		{
			base.transform.rotation = newRotation;
		}
	}

	private void OnParentDiscontinuity(RigidbodyEx parent)
	{
		if (MovesWithProxy)
		{
			base.transform.position = proxyTransform.position;
			base.transform.rotation = proxyTransform.rotation;
		}
	}

	private void LazyCreateTransformProxy()
	{
		if (proxyTransform == null)
		{
			GameObject gameObject = new GameObject(base.name + "(RigidbodyProxy)");
			gameObject.tag = "ProxyTransform";
			proxyTransform = gameObject.transform;
			proxyTransform.position = base.transform.position;
			proxyTransform.rotation = base.transform.rotation;
			proxyTransform.localScale = base.transform.localScale;
			if (!hasParent)
			{
				proxyTransform.SetParent(base.transform.parent, worldPositionStays: true);
			}
			else
			{
				proxyTransform.SetParent(parent.TargetTransform, worldPositionStays: true);
			}
		}
	}

	public void SetDiscontinuousPositionAndRotation(Vector3 newPosition, Quaternion newRotation)
	{
		if (MovesWithProxy)
		{
			proxyTransform.position = newPosition;
			proxyTransform.rotation = newRotation;
			base.transform.position = proxyTransform.position;
			base.transform.rotation = proxyTransform.rotation;
		}
		else
		{
			base.transform.position = newPosition;
			base.transform.rotation = newRotation;
		}
		ClearVelocity();
		if (this.DiscontinuityEvent != null)
		{
			this.DiscontinuityEvent(this);
		}
	}

	public void SetDiscontinuousLocalPositionAndLocalRotation(Vector3 newLocalPosition, Quaternion newLocalRotation)
	{
		if (MovesWithProxy)
		{
			proxyTransform.localPosition = newLocalPosition;
			proxyTransform.localRotation = newLocalRotation;
			base.transform.position = proxyTransform.position;
			base.transform.rotation = proxyTransform.rotation;
		}
		else
		{
			base.transform.localPosition = newLocalPosition;
			base.transform.localRotation = newLocalRotation;
		}
		ClearVelocity();
		if (this.DiscontinuityEvent != null)
		{
			this.DiscontinuityEvent(this);
		}
	}

	public void EnableProxyMovement(object token)
	{
		if (proxyTransform == null)
		{
			LazyCreateTransformProxy();
		}
		bool movesWithProxy = MovesWithProxy;
		proxyMovementTokens.Add(token);
		if (movesWithProxy)
		{
			return;
		}
		foreach (Transform item in base.transform)
		{
			if (item.CompareTag("ProxyTransform"))
			{
				item.SetParent(proxyTransform, worldPositionStays: false);
			}
		}
	}

	public void DisableProxyMovement(object token)
	{
		bool movesWithProxy = MovesWithProxy;
		proxyMovementTokens.Remove(token);
		if (!movesWithProxy || MovesWithProxy || proxyTransform.childCount <= 0)
		{
			return;
		}
		foreach (Transform item in proxyTransform)
		{
			item.SetParent(base.transform, worldPositionStays: false);
		}
	}

	public Vector3 GetAverageHistoricalKinematicLinearVelocity(float startTimeInPast)
	{
		return GetAverageHistoricalKinematicLinearVelocity(startTimeInPast, 0f);
	}

	public Vector3 GetAverageHistoricalKinematicLinearVelocity(float startSecondsAgo, float endSecondsAgo)
	{
		float latestTime = linearKinematicVelocityHistory.LatestTime;
		if (linearKinematicVelocityHistory.TryGetAverageValueOverTime(latestTime - startSecondsAgo, latestTime - endSecondsAgo, out var value))
		{
			return value;
		}
		return latestKinematicCalculationVelocity;
	}

