		return latestKinematicCalculationAngularVelocity;
	}

	public void GetWorldKinematicVelocitiesAtWorldSpacePoint(Vector3 worldSpacePoint, float startSecondsAgo, float endSecondsAgo, ControllerVelocitySettings.VelocityAverageMethod linearVelocityAverageMethod, ControllerVelocitySettings.VelocityAverageMethod angularVelocityAverageMethod, out Vector3 linearVelocity, out Vector3 angularVelocity)
	{
		GetLocalKinematicVelocitiesAtWorldSpacePoint(worldCenterOfMass, startSecondsAgo, endSecondsAgo, linearVelocityAverageMethod, angularVelocityAverageMethod, out linearVelocity, out angularVelocity);
		if (hasParent)
		{
			linearVelocity = parent.TargetTransform.TransformVector(linearVelocity);
			angularVelocity = parent.TargetTransform.TransformVector(angularVelocity);
		}
	}

	public void GetLocalKinematicVelocitiesAtWorldSpacePoint(Vector3 worldSpacePoint, float startSecondsAgo, float endSecondsAgo, ControllerVelocitySettings.VelocityAverageMethod linearVelocityAverageMethod, ControllerVelocitySettings.VelocityAverageMethod angularVelocityAverageMethod, out Vector3 linearVelocity, out Vector3 angularVelocity)
	{
		Vector3 vector = worldSpacePoint;
		Vector3 vector2 = worldCenterOfMass;
		if (hasParent)
		{
			vector = parent.TargetTransform.InverseTransformPoint(vector);
			vector2 = parent.TargetTransform.InverseTransformPoint(vector2);
		}
		GetKinematicVelocitiesAtPointInternal(vector, vector2, startSecondsAgo, endSecondsAgo, linearVelocityAverageMethod, angularVelocityAverageMethod, out var translationalLinearVelocity, out var rotationalLinearVelocity, out angularVelocity);
		linearVelocity = translationalLinearVelocity + rotationalLinearVelocity;
	}

	private void GetKinematicVelocitiesAtPointInternal(Vector3 samplePoint, Vector3 thisCenterOfMass, float startSecondsAgo, float endSecondsAgo, ControllerVelocitySettings.VelocityAverageMethod linearVelocityAverageMethod, ControllerVelocitySettings.VelocityAverageMethod angularVelocityAverageMethod, out Vector3 translationalLinearVelocity, out Vector3 rotationalLinearVelocity, out Vector3 angularVelocity)
	{
		translationalLinearVelocity = GetAverageHistoricalKinematicLinearVelocity(startSecondsAgo, endSecondsAgo);
		if (linearVelocityAverageMethod == ControllerVelocitySettings.VelocityAverageMethod.AVERAGE_DIRECTION_MAX_MAGNITUDE)
		{
			translationalLinearVelocity = translationalLinearVelocity.normalized * GetMaximumHistoricalKinematicLinearVelocity(startSecondsAgo, endSecondsAgo).magnitude;
		}
		angularVelocity = GetAverageHistoricalKinematicAngularVelocity(startSecondsAgo, endSecondsAgo);
		if (angularVelocityAverageMethod == ControllerVelocitySettings.VelocityAverageMethod.AVERAGE_DIRECTION_MAX_MAGNITUDE)
		{
			angularVelocity = angularVelocity.normalized * GetMaximumHistoricalKinematicAngularVelocity(startSecondsAgo, endSecondsAgo).magnitude;
		}
		Vector3 rhs = samplePoint - thisCenterOfMass;
		rotationalLinearVelocity = Vector3.Cross(angularVelocity, rhs);
	}

	public Vector3 GetConstrainedVelocity(Vector3 velocity)
	{
		RigidbodyConstraints rigidbodyConstraints = constraints;
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezePosition) == RigidbodyConstraints.FreezePosition)
		{
			return Vector3.zero;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezePositionX) != RigidbodyConstraints.None)
		{
			velocity.x *= 0f;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezePositionY) != RigidbodyConstraints.None)
		{
			velocity.y *= 0f;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezePositionZ) != RigidbodyConstraints.None)
		{
			velocity.z *= 0f;
		}
		return velocity;
	}

	public Vector3 GetConstrainedAngularVelocity(Vector3 angularVelocity)
	{
		RigidbodyConstraints rigidbodyConstraints = constraints;
		Vector3 vector = base.transform.InverseTransformDirection(angularVelocity);
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezeRotation) == RigidbodyConstraints.FreezeRotation)
		{
			return Vector3.zero;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezeRotationX) != RigidbodyConstraints.None)
		{
			vector.x *= 0f;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezeRotationY) != RigidbodyConstraints.None)
		{
			vector.y *= 0f;
		}
		if ((rigidbodyConstraints & RigidbodyConstraints.FreezeRotationZ) != RigidbodyConstraints.None)
		{
			vector.z *= 0f;
		}
		return angularVelocity;
	}

	public void AddForce(Vector3 force, ForceMode forceMode = ForceMode.Force)
	{
		Vector3 force2 = ((!hasParent) ? force : parent.TargetTransform.InverseTransformVector(force));
		AddForceLocal(force2, forceMode);
	}

	public void AddForceLocal(Vector3 force, ForceMode forceMode)
	{
		force = force.ValueOrZeroIfBogus();
		if (hasUnityRigidbody && !isKinematic)
		{
			unityRigidbody.AddForce(force, forceMode);
		}
		else if (UsesKinematicForces)
		{
			switch (forceMode)
			{
			case ForceMode.Force:
				forceAppliedThisFrame += force * UnityEngine.Time.deltaTime;
				break;
			case ForceMode.Impulse:
				forceAppliedThisFrame += force;
				break;
			case ForceMode.Acceleration:
				linearAccelerationThisFrame += force * UnityEngine.Time.deltaTime;
				break;
			case ForceMode.VelocityChange:
				linearAccelerationThisFrame += force;
				break;
			case (ForceMode)3:
			case (ForceMode)4:
				break;
			}
		}
	}

	public void AddForceAtPosition(Vector3 force, Vector3 position, ForceMode forceMode)
	{
		if (hasUnityRigidbody && !isKinematic)
		{
			unityRigidbody.AddForceAtPosition(force.ValueOrZeroIfBogus(), position, forceMode);
		}
		else if (UsesKinematicForces)
		{
			AddForce(force, forceMode);
			Vector3 torque = Vector3.Cross(position - worldCenterOfMass, force);
			AddTorque(torque, forceMode);
		}
	}

	public void AddTorque(Vector3 torque, ForceMode forceMode = ForceMode.Force)
	{
		Vector3 torque2 = ((!hasParent) ? torque : parent.TargetTransform.InverseTransformVector(torque));
		AddTorqueLocal(torque2, forceMode);
	}

	public void AddTorqueLocal(Vector3 torque, ForceMode forceMode)
	{
		torque = torque.ValueOrZeroIfBogus();
		if (hasUnityRigidbody && !isKinematic)
		{
			unityRigidbody.AddTorque(torque, forceMode);
		}
		else if (UsesKinematicForces)
		{
			switch (forceMode)
			{
			case ForceMode.Force:
				torqueAppliedThisFrame += torque * UnityEngine.Time.deltaTime;
				break;
			case ForceMode.Impulse:
				torqueAppliedThisFrame += torque;
				break;
			case ForceMode.Acceleration:
				angularAccelerationThisFrame += torque * UnityEngine.Time.deltaTime;
				break;
			case ForceMode.VelocityChange:
				angularAccelerationThisFrame += torque;
				break;
			case (ForceMode)3:
			case (ForceMode)4:
				break;
			}
		}
	}

	public void ClearVelocity()
	{
		Vector3 zero = Vector3.zero;
		ResetLinearVelocityLocalSpace(zero);
		ResetAngularVelocityLocalSpace(zero);
	}

	public void ClearUnityRigidbodyVelocity()
	{
		if (hasUnityRigidbody)
		{
			unityRigidbody.ClearVelocity();
		}
	}

	public void ClearLinearVelocity()
	{
		ResetLinearVelocityLocalSpace(Vector3.zero);
		forceAppliedThisFrame = Vector3.zero;
		linearAccelerationThisFrame = Vector3.zero;
	}

	public void ClearAngularVelocity()
	{
		ResetAngularVelocityLocalSpace(Vector3.zero);
		torqueAppliedThisFrame = Vector3.zero;
		angularAccelerationThisFrame = Vector3.zero;
	}

	public void ResetVelocityWorldSpace(Vector3 worldLinearVelocity, Vector3 worldAngularVelocity)
	{
		Vector3 localLinearVelocity = worldLinearVelocity;
		Vector3 vector = worldAngularVelocity;
		if (hasParent)
		{
			localLinearVelocity = parent.TargetTransform.InverseTransformVector(worldLinearVelocity);
			vector = parent.TargetTransform.InverseTransformVector(worldAngularVelocity);
		}
		ResetVelocityLocalSpace(localLinearVelocity, vector);
	}

	public void ResetVelocityLocalSpace(Vector3 localLinearVelocity, Vector3 localAngularVelocity)
	{
		ResetLinearVelocityLocalSpace(localLinearVelocity);
		ResetAngularVelocityLocalSpace(localAngularVelocity);
	}

	public void ResetLinearVelocityLocalSpace(Vector3 localLinearVelocity)
	{
		latestKinematicCalculationUpdateTime = now;
		if (hasParent)
		{
			latestKinematicCalculationPosition = targetLocalPosition;
			latestKinematicCalculationVelocity = localLinearVelocity;
		}
		else
		{
			latestKinematicCalculationPosition = physicsPosition;
			latestKinematicCalculationVelocity = localLinearVelocity;
		}
		linearKinematicVelocityHistory.Clear();
		if (!IsSleeping() || !localLinearVelocity.IsZero())
		{
			localVelocity = localLinearVelocity;
		}
	}

	public void ResetAngularVelocityLocalSpace(Vector3 localAngularVelocity)
	{
		latestKinematicCalculationUpdateTime = now;
		if (hasParent)
		{
			latestKinematicCalculationRotation = targetLocalRotation;
			latestKinematicCalculationAngularVelocity = localAngularVelocity;
		}
		else
		{
			latestKinematicCalculationRotation = physicsRotation;
			latestKinematicCalculationAngularVelocity = localAngularVelocity;
		}
		angularKinematicVelocityHistory.Clear();
		if (!IsSleeping() || !localAngularVelocity.IsZero())
		{
			this.localAngularVelocity = localAngularVelocity;
		}
	}

	public void ResetInertiaTensor()
	{
		if (hasUnityRigidbody)
		{
			unityRigidbody.ResetInertiaTensor();
			return;
		}
		inertiaTensor = Vector3.zero;
		inertiaTensorRotation = Quaternion.identity;
	}

	public bool SweepTest(Vector3 direction, out RaycastHit hitInfo)
	{
		if (hasUnityRigidbody)
		{
			return unityRigidbody.SweepTest(direction, out hitInfo);
		}
		hitInfo = default(RaycastHit);
		return false;
	}

	public bool SweepTest(Vector3 direction, out RaycastHit hitInfo, float maxDistance)
	{
		if (hasUnityRigidbody)
		{
			return unityRigidbody.SweepTest(direction, out hitInfo, maxDistance);
		}
		hitInfo = default(RaycastHit);
		return false;
	}

	public bool SweepTest(Vector3 direction, out RaycastHit hitInfo, float maxDistance, QueryTriggerInteraction queryTriggerInteraction)
	{
		if (hasUnityRigidbody)
		{
			return unityRigidbody.SweepTest(direction, out hitInfo, maxDistance, queryTriggerInteraction);
		}
		hitInfo = default(RaycastHit);
		return false;
	}

	public bool IsSleeping()
	{
		if (IsPhysicsDriven)
		{
			return unityRigidbody.IsSleeping();
		}
		return isSleepingKinematic;
	}

	public void Sleep()
	{
		if (IsPhysicsDriven)
		{
			Physics.SyncTransforms();
			unityRigidbody.Sleep();
		}
		else
		{
			isSleepingKinematic = true;
		}
	}

	public void WakeUp()
	{
		if (IsPhysicsDriven)
		{
			unityRigidbody.WakeUp();
			return;
		}
		isSleepingKinematic = false;
		numFramesKinematicSleep = 0;
	}

	public void FreezeCenterOfMassAndInertiaTensor()
	{
		if (hasUnityRigidbody)
		{
			UnityRigidbody.centerOfMass = UnityRigidbody.centerOfMass;
			UnityRigidbody.inertiaTensor = UnityRigidbody.inertiaTensor;
			UnityRigidbody.inertiaTensorRotation = UnityRigidbody.inertiaTensorRotation;
		}
		else
		{
			UnityEngine.Debug.LogWarningFormat("Unable to freeze center of mass and inertia tensor on {0}: No Unity rigidbody found.", this);
		}
	}

	public void UnfreezeCenterOfMassAndInertiaTensor()
	{
		if (hasUnityRigidbody)
		{
			if (customCenterOfMass.Overrides)
			{
				UnityRigidbody.centerOfMass = customCenterOfMass.Value;
			}
			else
			{
				UnityRigidbody.ResetCenterOfMass();
			}
			UnityRigidbody.ResetInertiaTensor();
		}
		else
		{
			UnityEngine.Debug.LogWarningFormat("Unable to freeze center of mass and inertia tensor on {0}: No Unity rigidbody found.", this);
		}
	}

	public void OnChangedDistanceBand(UpdateLOD oldDistanceBand, UpdateLOD newDistanceBand)
	{
		UpdateLod = newDistanceBand;
		RefreshSchedulerUpdates();
		if (OnDistanceBandChangedEvent != null)
		{
			OnDistanceBandChangedEvent(oldDistanceBand, newDistanceBand);
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.yellow;
		Gizmos.DrawWireSphere(worldCenterOfMass, 0.05f);
	}
}
[DisallowMultipleComponent]
public class RigidbodyPickup : Photon.MonoBehaviour
{
	public delegate Vector3 PositionDelegate();

	public delegate Quaternion RotationDelegate();

	protected enum State
	{
		NONE,
		PICKUP_DELAY,
		INTERPOLATING_TO_TARGET,
		FOLLOWING_TARGET,
		ATTACH_JOINT
	}

	[Serializable]
	public struct SpringSettings
	{
		public float SpringForce;

		public float Damper;

		public float MassMultiplier;

		public static SpringSettings Default = new SpringSettings
		{
			SpringForce = 10f,
			Damper = 0.5f,
			MassMultiplier = 1f
		};
	}

	[Tooltip("If true then this will accelerate towards the pickup target over time.  Otherwise snap.")]
	[SerializeField]
	[FormerlySerializedAs("interpolateToHand")]
	protected bool interpolateOnPickup = true;

	protected const float PICKUP_INTERPOLATE_DURATION = 0.06f;

	protected const float PICKUP_IGNORE_COLLISIONS_DURATION = 0.1f;

	protected const float TIMEOUT = 0.5f;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_ReachedTargetEvent;

	public static bool GlobalJointPickupEnabled = true;

	protected RigidbodyEx rigidbodyEx;

	protected NetworkTransform networkTransform;

	private ConfigurableJoint physicsJoint;

	private CollisionDetectionMode? previousCollisionDetectionMode;

	protected RigidbodyEx holder;

	private bool usedGravityOnPickup = true;

	[NonSerialized]
	public bool PickupWithPhysicsJoint;

	public PositionDelegate TargetPositionOverride;

	public RotationDelegate TargetRotationOverride;

	protected Tool tool;

	protected ManualUpdateStateMachine pickupStateMachine;

	private float stateMachineTimer;

	private SpringSettings _physicsJointSpringSetting;

	public RigidbodyPickup HolderPickup { get; protected set; }

	public Vector3 HolderSpacePickupPosition { get; protected set; }

	public Quaternion HolderSpacePickupRotation { get; protected set; }

	public virtual bool IsPickedUp => holder != null && base.enabled;

	public virtual Vector3 TargetPosition
	{
		get
		{
			if (TargetPositionOverride != null)
			{
				return TargetPositionOverride();
			}
			if (HolderPickup != null)
			{
				return HolderSpacePickupPosition.TransformCoordinateSpace(HolderPickup.TargetPosition, HolderPickup.TargetRotation);
			}
			if (!IsPickedUp)
			{
				return base.transform.position;
			}
			Quaternion coordinateSpaceRotation = TargetRotation.TransformRotation(Quaternion.Inverse(HolderSpacePickupRotation));
			Vector3 coordinateSpaceOrigin = ((!PickupWithPhysicsJoint) ? holder.targetPosition : holder.physicsPosition);
			return HolderSpacePickupPosition.TransformCoordinateSpace(coordinateSpaceOrigin, coordinateSpaceRotation);
		}
	}

	public virtual Quaternion TargetRotation
	{
		get
		{
			if (TargetRotationOverride != null)
			{
				return TargetRotationOverride();
			}
			if (!IsPickedUp)
			{
				return base.transform.rotation;
			}
			if (HolderPickup != null)
			{
				return HolderPickup.TargetRotation.TransformRotation(HolderSpacePickupRotation);
			}
			Transform transform = ((!PickupWithPhysicsJoint) ? holder.TargetTransform : holder.transform);
			return transform.TransformRotation(HolderSpacePickupRotation);
		}
	}

	public bool InterpolatingToTarget => pickupStateMachine.CurrentStateId == 2;

	public SpringSettings PhysicsJointSpringSettings
	{
		get
		{
			return _physicsJointSpringSetting;
		}
		set
		{
			_physicsJointSpringSetting = value;
			UpdateJointSpringSettings();
		}
	}

	public event Action ReachedTargetEvent
	{
		add
		{
			Action action = this.m_ReachedTargetEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ReachedTargetEvent, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_ReachedTargetEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ReachedTargetEvent, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		pickupStateMachine = new ManualUpdateStateMachine();
		pickupStateMachine.AddState(0, null, null, null);
		pickupStateMachine.AddState(1, OnEnterPickupDelayState, null, OnUpdatePickupDelayState);
		pickupStateMachine.AddState(2, OnEnterInterpolatingToTargetState, OnExitInterpolatingToTargetState, OnUpdateInterpolatingToTargetState);
		pickupStateMachine.AddState(3, null, null, OnUpdateFollowingTargetState);
		pickupStateMachine.AddState(4, OnEnterAttachJointState, OnExitAttachJointState, null);
		rigidbodyEx = GetComponent<RigidbodyEx>();
		networkTransform = GetComponent<NetworkTransform>();
		tool = GetComponent<Tool>();
		base.enabled = false;
	}

	protected virtual void LateUpdate()
	{
		pickupStateMachine.Update();
	}

	public void Pickup(RigidbodyPickup holderRigidbodyPickup, Vector3 holderSpacePickupPosition, Quaternion holderSpacePickupRotation)
	{
		Pickup(holderRigidbodyPickup.rigidbodyEx, holderSpacePickupPosition, holderSpacePickupRotation);
		HolderPickup = holderRigidbodyPickup;
	}

	public virtual void Pickup(RigidbodyEx holderRigidbodyEx, Vector3 holderSpacePickupPosition, Quaternion holderSpacePickupRotation)
	{
		Release();
		if ((bool)tool)
		{
			tool.DisableDynamicKinematicCollisions(disable: true);
		}
		if (CanPickupWithJoint(holderRigidbodyEx))
		{
			rigidbodyEx.RemoveKinematic(this);
		}
		else
		{
			previousCollisionDetectionMode = rigidbodyEx.collisionDetectionMode;
			rigidbodyEx.collisionDetectionMode = CollisionDetectionMode.Discrete;
			rigidbodyEx.AddKinematic(this);
		}
		holder = holderRigidbodyEx;
		HolderPickup = null;
		HolderSpacePickupPosition = holderSpacePickupPosition;
		HolderSpacePickupRotation = holderSpacePickupRotation;
		if (rigidbodyEx != null)
		{
			networkTransform.SynchronizationReadingEnabled = base.hasAuthority;
		}
		base.enabled = true;
		pickupStateMachine.EnterState(1);
	}

	public virtual void Release()
	{
		holder = null;
		HolderPickup = null;
		HolderSpacePickupPosition = Vector3.zero;
		HolderSpacePickupRotation = Quaternion.identity;
		if (rigidbodyEx != null)
		{
			rigidbodyEx.RemoveKinematic(this);
			if (previousCollisionDetectionMode.HasValue)
			{
				rigidbodyEx.collisionDetectionMode = previousCollisionDetectionMode.Value;
				previousCollisionDetectionMode = null;
			}
			networkTransform.SynchronizationReadingEnabled = true;
		}
		pickupStateMachine.EnterState(0);
		base.enabled = false;
	}

	public bool IsAttachedTo(RigidbodyPickup pickup)
	{
		return IsPickedUp && pickup.rigidbodyEx == holder && pickup == HolderPickup;
	}

	public bool IsAttachedTo(RigidbodyEx rigidbodyEx)
	{
		return IsPickedUp && rigidbodyEx == holder;
	}

	private void OnEnterPickupDelayState(ushort previousStateId, ushort previousSubStateId)
	{
		stateMachineTimer = UnityEngine.Time.fixedTime;
	}

	private void OnUpdatePickupDelayState()
	{
		if (base.gameObject.activeSelf || UnityEngine.Time.fixedTime - stateMachineTimer >= 0.5f)
		{
			pickupStateMachine.EnterState(2);
		}
	}

	private void OnEnterInterpolatingToTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		stateMachineTimer = UnityEngine.Time.fixedTime;
		rigidbodyEx.ClearVelocity();
	}

	private void OnUpdateInterpolatingToTargetState()
	{
		if (!interpolateOnPickup || UnityEngine.Time.fixedTime - stateMachineTimer >= 0.06f)
		{
			if (CanPickupWithJoint(holder))
			{
				pickupStateMachine.EnterState(4);
			}
			else
			{
				pickupStateMachine.EnterState(3);
			}
			return;
		}
		Vector3 currentVelocity = Vector3.zero;
		Vector3 zero = Vector3.zero;
		Vector3 position = Vector3.SmoothDamp(rigidbodyEx.physicsPosition, TargetPosition, ref currentVelocity, 0.06f);
		Vector3 eulerAngles = TargetRotation.eulerAngles;
		Vector3 eulerAngles2 = base.transform.rotation.eulerAngles;
		eulerAngles2.x = Mathf.SmoothDampAngle(eulerAngles2.x, eulerAngles.x, ref zero.x, 0.06f);
		eulerAngles2.y = Mathf.SmoothDampAngle(eulerAngles2.y, eulerAngles.y, ref zero.y, 0.06f);
		eulerAngles2.z = Mathf.SmoothDampAngle(eulerAngles2.z, eulerAngles.z, ref zero.z, 0.06f);
		Quaternion rotation = Quaternion.Euler(eulerAngles2);
		SetRigidbodyTransform(position, rotation);
		rigidbodyEx.ClearVelocity();
	}

	private void OnExitInterpolatingToTargetState(ushort previousStateId, ushort previousSubStateId)
	{
		if (this.ReachedTargetEvent != null)
		{
			this.ReachedTargetEvent();
		}
	}

	private void OnUpdateFollowingTargetState()
	{
		SetRigidbodyTransform(TargetPosition, TargetRotation);
		if ((bool)tool && UnityEngine.Time.fixedTime - stateMachineTimer >= 0.1f)
		{
			tool.DisableDynamicKinematicCollisions(disable: false);
		}
	}

	private void OnEnterAttachJointState(ushort previousStateId, ushort previousSubStateId)
	{
		if ((bool)tool)
		{
			tool.DisableDynamicKinematicCollisions(disable: false);
		}
		AttachPhysicsJoint(holder.UnityRigidbody);
	}

	private void OnExitAttachJointState(ushort nextStateId, ushort nextSubStateId)
	{
		if (physicsJoint != null)
		{
			UnityEngine.Object.Destroy(physicsJoint);
			physicsJoint = null;
		}
		rigidbodyEx.useGravity = usedGravityOnPickup;
	}

	private bool CanPickupWithJoint(RigidbodyEx attemptedHolder)
	{
		return PickupWithPhysicsJoint && GlobalJointPickupEnabled && attemptedHolder.UnityRigidbody != null;
	}

	protected void SetRigidbodyTransform(Vector3 position, Quaternion rotation)
	{
		Vector3 vector = (position - rigidbodyEx.physicsPosition) / UnityEngine.Time.fixedDeltaTime;
		Vector3 vector2 = UnityExtensions.AngularDisplacementFromTo(rigidbodyEx.physicsRotation, rotation) / UnityEngine.Time.fixedDeltaTime;
		rigidbodyEx.velocity = vector.ValueOrZeroIfBogus();
		rigidbodyEx.angularVelocity = vector2.ValueOrZeroIfBogus();
		rigidbodyEx.targetPosition = position.ValueOrZeroIfBogus();
		rigidbodyEx.targetRotation = rotation.ValueOrIdentityIfBogus();
	}

	private void AttachPhysicsJoint(Rigidbody holderRigidbody)
	{
		base.transform.position = TargetPosition;
		base.transform.rotation = TargetRotation;
		usedGravityOnPickup = rigidbodyEx.useGravity;
		rigidbodyEx.useGravity = false;
		if (physicsJoint == null)
		{
			physicsJoint = base.gameObject.AddComponent<ConfigurableJoint>();
		}
		physicsJoint.autoConfigureConnectedAnchor = false;
		physicsJoint.connectedBody = holderRigidbody;
		physicsJoint.connectedAnchor = Vector3.zero;
		physicsJoint.anchor = base.transform.InverseTransformPoint(holderRigidbody.position);
		physicsJoint.xMotion = ConfigurableJointMotion.Locked;
		physicsJoint.yMotion = ConfigurableJointMotion.Locked;
		physicsJoint.zMotion = ConfigurableJointMotion.Locked;
		physicsJoint.rotationDriveMode = RotationDriveMode.Slerp;
		UpdateJointSpringSettings();
	}

	private void UpdateJointSpringSettings()
	{
		if (physicsJoint != null)
		{
			physicsJoint.massScale = PhysicsJointSpringSettings.MassMultiplier;
			JointDrive slerpDrive = physicsJoint.slerpDrive;
			slerpDrive.positionSpring = PhysicsJointSpringSettings.SpringForce;
			slerpDrive.positionDamper = PhysicsJointSpringSettings.Damper;
			physicsJoint.slerpDrive = slerpDrive;
		}
	}

	private void Reset()
	{
		RigidbodyEx component = GetComponent<RigidbodyEx>();
		if (component == null)
		{
			component = base.gameObject.AddComponent<RigidbodyEx>();
		}
	}
}
public class SphericalConstraintRigidbodyPickup : RigidbodyPickup
{
	public enum AngularMovementMode
	{
		LOCKED,
		LIMITED,
		FREE
	}

	public enum LinearMovementMode
	{
		SPHERE_SURFACE,
		SPHERE_VOLUME
	}

	[Serializable]
	public struct AngularMovementConstraint
	{
		public AngularMovementMode Mode;

		[Header("Limited")]
		public float MinLimitedAngle;

		public float MaxLimitedAngle;

		public static AngularMovementConstraint Default = new AngularMovementConstraint
		{
			Mode = AngularMovementMode.LOCKED,
			MinLimitedAngle = 0f,
			MaxLimitedAngle = 0f
		};
	}

	[Header("Sphere")]
	public Transform sphereOrigin;

	[Header("Position Constraint")]
	public LinearMovementMode positionConstraint;

	public bool automaticallyCalculateSphereRadius = true;

	public float sphereRadius = 1f;

	[Header("Rotational Constraints")]
	public AngularMovementConstraint yawConstraint = AngularMovementConstraint.Default;

	public AngularMovementConstraint pitchConstraint = AngularMovementConstraint.Default;

	public AngularMovementConstraint rollConstraint = AngularMovementConstraint.Default;

	public override Vector3 TargetPosition
	{
		get
		{
			Vector3 targetPosition = base.TargetPosition;
			if (sphereOrigin == null)
			{
				return targetPosition;
			}
			Vector3 localPosition = sphereOrigin.InverseTransformPoint(targetPosition);
			GetPitchYawRadiusFromLocalPosition(localPosition, out var pitch, out var yaw, out var radius);
			ApplyConstraint(ref pitch, ref yaw, ref radius);
			localPosition = GetLocalPositionFromYawPitchRadius(pitch, yaw, radius);
			return sphereOrigin.TransformPoint(localPosition);
		}
	}

	public override Quaternion TargetRotation
	{
		get
		{
			if (sphereOrigin == null)
			{
				return base.TargetRotation;
			}
			return Quaternion.LookRotation(sphereOrigin.position - base.transform.position);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (sphereOrigin != null && automaticallyCalculateSphereRadius)
		{
			sphereRadius = sphereOrigin.InverseTransformPoint(base.transform.position).magnitude;
		}
	}

	public void GetCurrentNormalizedPitchYaw(out float normalizedPitch, out float normalizedYaw)
	{
		if (sphereOrigin == null)
		{
			normalizedPitch = 0f;
			normalizedYaw = 0f;
			return;
		}
		Vector3 localPosition = sphereOrigin.InverseTransformPoint(rigidbodyEx.physicsPosition);
		GetPitchYawRadiusFromLocalPosition(localPosition, out var pitch, out var yaw, out var _);
		normalizedPitch = GetNormalizedConstraintAngle(pitch, pitchConstraint);
		normalizedYaw = GetNormalizedConstraintAngle(yaw, yawConstraint);
	}

	public float GetAbsoluteYawFromNormalizedYaw(float normalizedYaw)
	{
		return GetAbsoluteConstraintAngle(normalizedYaw, yawConstraint);
	}

	public float GetAbsolutePitchFromNormalizedPitch(float normalizedPitch)
	{
		return GetAbsoluteConstraintAngle(normalizedPitch, pitchConstraint);
	}

	public float GetNormalizedYawFromAbsoluteYaw(float absoluteYaw)
	{
		return GetNormalizedConstraintAngle(absoluteYaw, yawConstraint);
	}

	public float GetNormalizedPitchFromAbsolutePitch(float absolutePitch)
	{
		return GetNormalizedConstraintAngle(absolutePitch, pitchConstraint);
	}

	public void AuthoritySetNormalizedPitchYaw(float desiredNormalizedPitch, float desiredNormalizedYaw)
	{
		if (!IsPickedUp && base.hasAuthority && !(sphereOrigin == null))
		{
			GetTransformFromNormalizedYawPitch(desiredNormalizedPitch, desiredNormalizedYaw, out var position, out var rotation);
			rigidbodyEx.targetPosition = position;
			rigidbodyEx.targetRotation = rotation;
		}
	}

	public Quaternion GetRotationFromNormalizedYawPitch(float desiredPitch, float desiredYaw)
	{
		GetTransformFromNormalizedYawPitch(desiredPitch, desiredYaw, out var _, out var rotation);
		return rotation;
	}

	public void GetTransformFromNormalizedYawPitch(float desiredNormalizedPitch, float desiredNormalizedYaw, out Vector3 position, out Quaternion rotation)
	{
		Vector3 localPosition = sphereOrigin.InverseTransformPoint(rigidbodyEx.physicsPosition);
		GetPitchYawRadiusFromLocalPosition(localPosition, out var pitch, out var yaw, out var radius);
		pitch = GetAbsoluteConstraintAngle(desiredNormalizedPitch, pitchConstraint);
		yaw = GetAbsoluteConstraintAngle(desiredNormalizedYaw, yawConstraint);
		ApplyConstraint(ref pitch, ref yaw, ref radius);
		Vector3 localPositionFromYawPitchRadius = GetLocalPositionFromYawPitchRadius(pitch, yaw, radius);
		position = sphereOrigin.TransformPoint(localPositionFromYawPitchRadius);
		rotation = Quaternion.LookRotation(sphereOrigin.position - position);
	}

	private void GetPitchYawRadiusFromLocalPosition(Vector3 localPosition, out float pitch, out float yaw, out float radius)
	{
		MathExt.CartesianPointToSphericalDegrees(localPosition, out pitch, out yaw, out radius);
	}

	private Vector3 GetLocalPositionFromYawPitchRadius(float pitch, float yaw, float radius)
	{
		return MathExt.SphericalPointDegreestoCartesian(pitch, yaw, radius);
	}

	private void ApplyConstraint(ref float pitch, ref float yaw, ref float radius)
	{
		pitch = ApplyAngularConstraint(pitch, pitchConstraint);
		yaw = ApplyAngularConstraint(yaw, yawConstraint);
		radius = ApplyLinearConstraint(radius, positionConstraint);
	}

	private float ApplyAngularConstraint(float angle, AngularMovementConstraint constraint)
	{
		switch (constraint.Mode)
		{
		case AngularMovementMode.LOCKED:
			angle = 0f;
			break;
		case AngularMovementMode.LIMITED:
		{
			angle = RemapAngleToOneEighty(angle);
			float min = Mathf.Min(constraint.MinLimitedAngle, constraint.MaxLimitedAngle);
			float max = Mathf.Max(constraint.MinLimitedAngle, constraint.MaxLimitedAngle);
			angle = Mathf.Clamp(angle, min, max);
			break;
		}
		}
		return angle;
	}

	private float RemapAngleToOneEighty(float angle)
	{
		if (angle > 180f)
		{
			angle -= 360f;
		}
		else if (angle < -180f)
		{
			angle += 360f;
		}
		return angle;
	}

	private float GetNormalizedConstraintAngle(float angle, AngularMovementConstraint constraint)
	{
		if (constraint.Mode == AngularMovementMode.LIMITED)
		{
			return Mathf.InverseLerp(constraint.MinLimitedAngle, constraint.MaxLimitedAngle, RemapAngleToOneEighty(angle));
		}
		if (constraint.Mode == AngularMovementMode.FREE)
		{
			return Mathf.InverseLerp(0f, 180f, RemapAngleToOneEighty(angle));
		}
		return 0f;
	}

	private float GetAbsoluteConstraintAngle(float normalizedAngle, AngularMovementConstraint constraint)
	{
		float result = 0f;
		if (constraint.Mode == AngularMovementMode.LIMITED)
		{
			result = RemapAngleToOneEighty(Mathf.Lerp(constraint.MinLimitedAngle, constraint.MaxLimitedAngle, normalizedAngle));
		}
		else if (constraint.Mode == AngularMovementMode.FREE)
		{
			result = Mathf.Lerp(-180f, 180f, normalizedAngle);
		}
		return result;
	}

	private float ApplyLinearConstraint(float desiredRadius, LinearMovementMode constraint)
	{
		return constraint switch
		{
			LinearMovementMode.SPHERE_SURFACE => sphereRadius, 
			_ => Mathf.Min(desiredRadius, sphereRadius), 
		};
	}
}
public class StabilizedRigidbodyPickup : RigidbodyPickup
{
	[SerializeField]
	private float separationAngle = 30f;

	[SerializeField]
	private float returnToDestabilizedSpeed = 360f;

	private Transform _stabilizer;

	[NonSerialized]
	public Vector3 StabilizerOffsetPosition = Vector3.zero;

	[NonSerialized]
	public Quaternion StabilizerOffsetRotation = Quaternion.identity;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_StabilizerSeparationEvent;

	private Coroutine returnCoroutine;

	private Quaternion returnRotation = Quaternion.identity;

	public Transform Stabilizer
	{
		get
		{
			return _stabilizer;
		}
		set
		{
			if (value == null)
			{
				StartReturnCoroutine(TargetRotation);
			}
			else
			{
				StopReturnCoroutine();
			}
			_stabilizer = value;
		}
	}

	public override Quaternion TargetRotation
	{
		get
		{
			Quaternion targetRotation = base.TargetRotation;
			if (!IsPickedUp)
			{
				return targetRotation;
			}
			if (Stabilizer == null)
			{
				if (returnCoroutine != null)
				{
					return returnRotation;
				}
				return targetRotation;
			}
			Vector3 vector = StabilizerOffsetRotation * StabilizedForward;
			Vector3 vector2 = targetRotation * Vector3.forward;
			if (Vector3.Angle(vector2, vector) >= separationAngle && this.StabilizerSeparationEvent != null)
			{
				this.StabilizerSeparationEvent();
			}
			Vector3 upwards = targetRotation * Vector3.up;
			return Quaternion.LookRotation(vector, upwards);
		}
	}

	public Vector3 StabilizedForward
	{
		get
		{
			Vector3 normalized = (StabilizerPosition - holder.targetPosition).normalized;
			if (Vector3.Dot(normalized, base.transform.forward) < 0f)
			{
				normalized *= -1f;
			}
			return normalized;
		}
	}

	private Vector3 StabilizerPosition => Stabilizer.TransformPoint(StabilizerOffsetPosition);

	public event Action StabilizerSeparationEvent
	{
		add
		{
			Action action = this.m_StabilizerSeparationEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_StabilizerSeparationEvent, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_StabilizerSeparationEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_StabilizerSeparationEvent, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void StartReturnCoroutine(Quaternion currentRotation)
	{
		StopReturnCoroutine();
		returnCoroutine = StartCoroutine(ReturnToDestabilizedRotation(currentRotation));
	}

	private void StopReturnCoroutine()
	{
		if (returnCoroutine != null)
		{
			StopCoroutine(returnCoroutine);
			returnCoroutine = null;
		}
	}

	private IEnumerator ReturnToDestabilizedRotation(Quaternion currentRotation)
	{
		returnRotation = currentRotation;
		float angle = Quaternion.Angle(returnRotation, base.TargetRotation);
		float duration = angle / returnToDestabilizedSpeed * 1.25f;
		float timer = 0f;
		while (timer < duration)
		{
			yield return null;
			timer += UnityEngine.Time.deltaTime;
			returnRotation = Quaternion.RotateTowards(returnRotation, base.TargetRotation, returnToDestabilizedSpeed * UnityEngine.Time.deltaTime);
		}
		returnCoroutine = null;
	}
}
