public class DiscNetworkTransform : NetworkTransform
{
	[SerializeField]
	private bool extrapolatesLift = true;

	[SerializeField]
	private bool extrapolatesCurve = true;

	private DiscGolfDisc disc;

	protected override void Awake()
	{
		base.Awake();
		disc = GetComponent<DiscGolfDisc>();
	}

	protected override void ExtrapolateSyncVelocityAndDisplacement(float timeSinceLastSync, out Vector3 extrapolatedDisplacement, bool extrapolateGravity = false)
	{
		base.ExtrapolateSyncVelocityAndDisplacement(timeSinceLastSync, out extrapolatedDisplacement, extrapolateGravity);
		if (!(disc != null) || !extrapolatesLift)
		{
			return;
		}
		Vector3 liftAcceleration = disc.GetLiftAcceleration(lastExtrapolatedAngularVelocity.magnitude);
		if (liftAcceleration.sqrMagnitude > 0.0001f)
		{
			extrapolatedDisplacement += liftAcceleration * timeSinceLastSync * timeSinceLastSync / 2f;
			lastExtrapolatedVelocity += liftAcceleration * timeSinceLastSync;
			if (extrapolatesCurve)
			{
				Vector3 vector = disc.CurveForce / disc.Tool.RigidbodyEx.mass;
				extrapolatedDisplacement += vector * timeSinceLastSync * timeSinceLastSync / 2f;
				lastExtrapolatedVelocity += vector * timeSinceLastSync;
			}
		}
	}
}
