[DisallowMultipleComponent]
[AddComponentMenu("Rec Room/Network Transform")]
public class NetworkTransform : Photon.MonoBehaviour, IPunObservable
{
	public class SyncData
	{
		public NetworkTransform Context;

		public int ContinuousMovementID;

		public int ParentID;

		public bool IsSleeping;

		public bool CompressedRotation;

		public Vector3 Position;

		public Quaternion Rotation;

		public float Scale;

		public Vector3 Velocity;

		public Vector3 AngularVelocity;

		private static readonly RecRoom.Networking.BitPacker bitPacker = new RecRoom.Networking.BitPacker();

		public static short Serialize(StreamBuffer outStream, object customobject)
		{
			SyncData syncData = (SyncData)customobject;
			lock (bitPacker)
			{
				bitPacker.StartWriting(outStream, syncData.Context);
				bitPacker.WriteBool(syncData.IsSleeping);
				bitPacker.WriteBool(syncData.CompressedRotation);
				bitPacker.WriteInt(syncData.ContinuousMovementID, 0, 63);
				bitPacker.WriteInt(syncData.ParentID, int.MinValue, int.MaxValue);
				bitPacker.WritePosition(syncData.Position);
				if (syncData.CompressedRotation)
				{
					bitPacker.WriteQuaternion(syncData.Rotation);
				}
				else
				{
					bitPacker.WriteUncompressedFloat(syncData.Rotation.x);
					bitPacker.WriteUncompressedFloat(syncData.Rotation.y);
					bitPacker.WriteUncompressedFloat(syncData.Rotation.z);
					bitPacker.WriteUncompressedFloat(syncData.Rotation.w);
				}
				bitPacker.WriteScale(syncData.Scale);
				bitPacker.WriteVelocity(syncData.Velocity);
				bitPacker.WriteVelocity(syncData.AngularVelocity);
				return (short)bitPacker.FinishWriting();
			}
		}

		public static object Deserialize(StreamBuffer inStream, short length)
		{
			SyncData syncData = new SyncData();
			lock (bitPacker)
			{
				bitPacker.StartReading(inStream, length);
				syncData.IsSleeping = bitPacker.ReadBool();
				syncData.CompressedRotation = bitPacker.ReadBool();
				syncData.ContinuousMovementID = bitPacker.ReadInt(0, 63);
				syncData.ParentID = bitPacker.ReadInt(int.MinValue, int.MaxValue);
				syncData.Position = bitPacker.ReadPosition();
				if (syncData.CompressedRotation)
				{
					syncData.Rotation = bitPacker.ReadQuaternion();
				}
				else
				{
					float x = bitPacker.ReadUncompressedFloat();
					float y = bitPacker.ReadUncompressedFloat();
					float z = bitPacker.ReadUncompressedFloat();
					float w = bitPacker.ReadUncompressedFloat();
					syncData.Rotation = new Quaternion(x, y, z, w);
				}
				syncData.Scale = bitPacker.ReadScale();
				syncData.Velocity = bitPacker.ReadVelocity();
				syncData.AngularVelocity = bitPacker.ReadVelocity();
				bitPacker.FinishReading();
				return syncData;
			}
		}
	}

	[SerializeField]
	public bool extrapolatesDrag;

	[SerializeField]
	public bool ignoreVisibilityOptimizations;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private RigidbodyEx rigidbodyEx;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private Tool tool;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private VisibleInCamera visibleInCamera;

	private const float LOCAL_MOVEMENT_THRESHOLD = 0.001f;

	private const float LOCAL_ROTATION_THRESHOLD = 0.5f;

	private const float LOCAL_SCALE_THRESHOLD = 0.0001f;

	private const float ACCOUNT_FOR_GRAVITY_THRESHOLD = 0.05f;

	private const float INTERPOLATION_TIME = 0.05f;

	private const float DISCONTINUITY_SMOOTH_TIME = 0.25f;

	private const int STABLE_FRAMES_BEFORE_SLEEP = 5;

	private const float TIME_WITHOUT_PACKET_BEFORE_SNAP = 0.5f;

	private const float MIN_REQUIRED_SYNC_INTERVAL = 3f;

	private const float MAX_REQUIRED_SYNC_INTERVAL = 5f;

	private const float SQR_SNAP_THRESHOLD = 25f;

	private const float SQR_MAX_INTERPOLATE_THRESHOLD = 1000f;

	private const int MAX_CONTINUOUS_MOVEMENT_ID = 63;

	public const float UncompressedRotationThreshold = 32.489998f;

	[NonSerialized]
	public bool AlwaysUseAverageKinematicVelocity;

	[NonSerialized]
	public bool RunCollisionDetectionWhileExtrapolating;

	[NonSerialized]
	public List<PhotonPlayer> PotentialOwners = new List<PhotonPlayer>();

	[NonSerialized]
	public bool UseCompressedRotation = true;

	private Collider collider;

	private float lastSyncTime;

	private int lastSyncContinuousMovementID;

	private bool syncRequested;

	private float networkLatency;

	protected Vector3 lastExtrapolatedVelocity = Vector3.zero;

	protected Vector3 lastExtrapolatedAngularVelocity = Vector3.zero;

	private float requiredSyncInterval;

	private int syncContinuousMovementID;

	private int syncParentID;

	private bool syncHasData;

	private bool syncIsSleeping;

	private Vector3 syncPosition;

	private Quaternion syncRotation;

	private float syncScale;

	private Vector3 syncVelocity;

	private Vector3 syncAngularVelocity;

	private Vector3 smoothDiscontinuityVelocity;

	private int stableFrames;

	private bool richInterpolationEnabled;

	private SyncData syncData = new SyncData();

	private float lastDiscontinuityStartTime;

	private bool useDynamicDistanceExtrapolation;

	private bool _synchronizationReadingEnabled = true;

	private bool _synchronizationWritingEnabled = true;

	public Action ValidPositionBoundsExceeded;

	private Vector3 CurrentPosition
	{
		get
		{
			if (rigidbodyEx.hasParent)
			{
				return rigidbodyEx.targetLocalPosition;
			}
			return rigidbodyEx.targetPosition;
		}
	}

	private Quaternion CurrentRotation
	{
		get
		{
			if (rigidbodyEx.hasParent)
			{
				return rigidbodyEx.targetLocalRotation;
			}
			return rigidbodyEx.targetRotation;
		}
	}

	private float CurrentScale => base.transform.GetLocalUniformScale();

	private Vector3 CurrentLinearVelocity
	{
		get
		{
			if (rigidbodyEx.hasParent)
			{
				return rigidbodyEx.localVelocity;
			}
			if (AlwaysUseAverageKinematicVelocity)
			{
				return rigidbodyEx.RecentKinematicLinearVelocity;
			}
			return rigidbodyEx.velocity;
		}
	}

	private Vector3 CurrentAngularVelocity
	{
		get
		{
			if (rigidbodyEx.hasParent)
			{
				return rigidbodyEx.localAngularVelocity;
			}
			if (AlwaysUseAverageKinematicVelocity)
			{
				return rigidbodyEx.RecentKinematicAngularVelocity;
			}
			return rigidbodyEx.angularVelocity;
		}
	}

	public bool IgnoreVisibilityOptimizations => ignoreVisibilityOptimizations;

	public bool UseDynamicDistanceExtrapolation
	{
		get
		{
			return useDynamicDistanceExtrapolation;
		}
		set
		{
			useDynamicDistanceExtrapolation = value;
			ReevaluateEnabledState();
		}
	}

	public bool SynchronizationReadingEnabled
	{
		get
		{
			return _synchronizationReadingEnabled;
		}
		set
		{
			if (value && !_synchronizationReadingEnabled)
			{
				StartSmoothingDiscontinuity();
			}
			_synchronizationReadingEnabled = value;
			ReevaluateEnabledState();
		}
	}

	public bool SynchronizationWritingEnabled
	{
		get
		{
			return _synchronizationWritingEnabled;
		}
		set
		{
			if (value && !_synchronizationWritingEnabled)
			{
				syncRequested = true;
			}
			_synchronizationWritingEnabled = value;
		}
	}

	private bool isSmoothingDiscontinuity => UnityEngine.Time.fixedTime - lastDiscontinuityStartTime < 0.25f;

	public bool IsPersistable => true;

	public static bool CanCompressRotationForSize(float maxSize)
	{
		return maxSize * maxSize < 32.489998f;
	}

	protected override void Awake()
	{
		base.Awake();
		requiredSyncInterval = UnityEngine.Random.Range(0f, 0f);
		rigidbodyEx.SleepChangedEvent += OnRigidbodySleepChange;
		Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (!componentsInChildren[i].isTrigger && componentsInChildren[i].enabled)
			{
				collider = componentsInChildren[i];
				break;
			}
		}
	}

	private void Start()
	{
		syncHasData = false;
		syncContinuousMovementID = 0;
		PhotonView photonView = ((!rigidbodyEx.hasParent) ? null : rigidbodyEx.parent.GetComponent<PhotonView>());
		syncParentID = ((!(photonView != null)) ? (-1) : photonView.viewID);
		syncPosition = CurrentPosition;
		syncRotation = CurrentRotation;
		syncScale = CurrentScale;
		syncVelocity = CurrentLinearVelocity;
		syncAngularVelocity = CurrentAngularVelocity;
		stableFrames = 0;
		base.photonView.OwnerChangedEvent += OnPhotonOwnershipChanged;
		ReevaluateEnabledState();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		rigidbodyEx.SleepChangedEvent -= OnRigidbodySleepChange;
		base.photonView.OwnerChangedEvent -= OnPhotonOwnershipChanged;
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading && info.sender != base.authority)
		{
			return;
		}
		PhotonView photonView = ((!rigidbodyEx.hasParent) ? null : rigidbodyEx.parent.GetComponent<PhotonView>());
		int num = ((!(photonView != null)) ? (-1) : photonView.viewID);
		if (stream.isWriting)
		{
			if (SynchronizationWritingEnabled)
			{
				if (syncRequested || syncContinuousMovementID != lastSyncContinuousMovementID)
				{
					syncHasData = true;
					syncRequested = false;
				}
				else if (!AlwaysUseAverageKinematicVelocity && rigidbodyEx.IsPhysicsDriven)
				{
					syncHasData = !rigidbodyEx.IsSleeping();
				}
				else
				{
					syncHasData = syncParentID != num || (syncPosition - CurrentPosition).magnitude > 0.001f || Quaternion.Angle(CurrentRotation, syncRotation) > 0.5f || Mathf.Abs(syncScale - CurrentScale) > 0.0001f;
				}
				if (syncHasData)
				{
					stableFrames = 0;
				}
				else
				{
					stableFrames++;
					syncHasData = stableFrames <= 5;
				}
				if (!syncHasData && UnityEngine.Time.fixedTime - lastSyncTime > requiredSyncInterval)
				{
					syncHasData = true;
					UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
					requiredSyncInterval = UnityEngine.Random.Range(3f, 5f);
				}
			}
			else
			{
				syncHasData = false;
			}
			ReevaluateEnabledState();
			if (!syncHasData)
			{
				if (base.photonView.ObservedComponents.Count != 1 || base.photonView.ObservedComponents[0] != this)
				{
					stream.SendNext(false);
				}
				return;
			}
			this.syncData.Context = this;
			this.syncData.ContinuousMovementID = syncContinuousMovementID;
			this.syncData.ParentID = (syncParentID = num);
			this.syncData.Position = (syncPosition = CurrentPosition);
			this.syncData.Rotation = (syncRotation = CurrentRotation);
			this.syncData.Scale = (syncScale = CurrentScale);
			this.syncData.Velocity = (syncVelocity = CurrentLinearVelocity);
			this.syncData.AngularVelocity = (syncAngularVelocity = CurrentAngularVelocity);
			this.syncData.IsSleeping = (syncIsSleeping = !AlwaysUseAverageKinematicVelocity && !rigidbodyEx.hasParent && rigidbodyEx.IsSleeping());
			this.syncData.CompressedRotation = UseCompressedRotation;
			stream.SendNext(this.syncData);
		}
		else
		{
			object obj = stream.ReceiveNext();
			SyncData syncData = obj as SyncData;
			syncHasData = syncData != null;
			if (!syncHasData)
			{
				if (SynchronizationReadingEnabled)
				{
					SnapToLastSyncPosition();
					rigidbodyEx.Sleep();
				}
				ReevaluateEnabledState();
				return;
			}
			this.syncData = syncData;
			syncContinuousMovementID = syncData.ContinuousMovementID;
			syncParentID = syncData.ParentID;
			syncPosition = syncData.Position;
			syncRotation = syncData.Rotation;
			syncScale = syncData.Scale;
			syncVelocity = syncData.Velocity;
			syncAngularVelocity = syncData.AngularVelocity;
			syncIsSleeping = syncData.IsSleeping;
			networkLatency = Mathf.Max(0f, (float)(PhotonNetwork.time - info.timestamp));
			richInterpolationEnabled = true;
			UpdateSyncParent();
			if (SynchronizationReadingEnabled)
			{
				Vector3 vector = TransformCurrentPositionToWorldSpace(syncPosition);
				float sqrMagnitude = (vector - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position).sqrMagnitude;
				float sqrMagnitude2 = (syncPosition - CurrentPosition).sqrMagnitude;
				bool flag = GameSessions.LocalGameSession != null && GameSessions.LocalGameSession.Location == RoomSceneLocations.PADDLEBALL;
				if (!UseDynamicDistanceExtrapolation && !flag && (!visibleInCamera.IsVisible || sqrMagnitude > 1000f))
				{
					SnapToLastSyncPositionAndVelocity();
					richInterpolationEnabled = false;
				}
				else if (syncIsSleeping || lastSyncTime == 0f || lastSyncContinuousMovementID != syncContinuousMovementID || (sqrMagnitude2 > 25f && !isSmoothingDiscontinuity))
				{
					SnapToLastSyncPosition();
				}
			}
			if (syncIsSleeping)
			{
				rigidbodyEx.Sleep();
			}
			ReevaluateEnabledState();
		}
		lastSyncTime = UnityEngine.Time.fixedTime;
		lastSyncContinuousMovementID = syncContinuousMovementID;
	}

	private float GetTimeSinceLastSync()
	{
		float num = UnityEngine.Time.fixedTime - lastSyncTime;
		if (UseDynamicDistanceExtrapolation)
		{
			num += GetDynamicDistanceExtrapolation() * (networkLatency + 0.05f);
		}
		return num;
	}

	private void SnapToLastSyncPosition()
	{
		ResetPhysics(syncPosition, syncRotation, syncScale);
	}

	private void SnapToLastSyncPositionAndVelocity()
	{
		TransformSetPosition(syncPosition.ValueOrZeroIfBogus(), syncRotation.ValueOrIdentityIfBogus(), syncScale);
		ResetVelocity(syncVelocity, syncAngularVelocity);
	}

	public void InsertPositionDiscontinuity(bool forceImmediate = false)
	{
		if (base.hasAuthority)
		{
			ResetVelocity(Vector3.zero, Vector3.zero);
			syncContinuousMovementID = ((syncContinuousMovementID < 63) ? (syncContinuousMovementID + 1) : 0);
			if (forceImmediate)
			{
				lastSyncTime = UnityEngine.Time.fixedTime;
				base.photonView.RpcAll(RpcForceDiscontinuitySync, CurrentPosition, CurrentRotation, CurrentScale, syncContinuousMovementID);
			}
		}
	}

	private void StartSmoothingDiscontinuity()
	{
		lastDiscontinuityStartTime = UnityEngine.Time.fixedTime;
		smoothDiscontinuityVelocity = CurrentLinearVelocity;
	}

	private void RemoteForceDiscontinuitySync(Vector3 position, Quaternion rotation, float scale, int syncContinuousMovementID)
	{
		this.syncContinuousMovementID = syncContinuousMovementID;
		syncPosition = position;
		syncRotation = rotation;
		syncScale = scale;
		syncVelocity = Vector3.zero;
		syncAngularVelocity = Vector3.zero;
		SnapToLastSyncPosition();
		lastSyncTime = UnityEngine.Time.fixedTime;
	}

	private void UpdateNetworkInterpolation()
	{
		if (SynchronizationReadingEnabled && syncHasData && !syncIsSleeping)
		{
			if (UnityEngine.Time.fixedTime - lastSyncTime > 0.5f)
			{
				syncHasData = false;
				SnapToLastSyncPosition();
				rigidbodyEx.Sleep();
			}
			else if (richInterpolationEnabled)
			{
				InterpolateTowardLatestSync();
			}
			else if (rigidbodyEx.isKinematic && (IgnoreVisibilityOptimizations || visibleInCamera.IsVisible))
			{
				SimpleKinematicExtrapolateFromLatestSync();
			}
		}
	}

	private void InterpolateTowardLatestSync()
	{
		float timeSinceLastSync = GetTimeSinceLastSync();
		Vector3 extrapolatedSyncPosition = GetExtrapolatedSyncPosition(timeSinceLastSync);
		Quaternion extrapolatedSyncRotation = GetExtrapolatedSyncRotation(timeSinceLastSync);
		Vector3 velocity;
		if (isSmoothingDiscontinuity)
		{
			Vector3 currentPosition = CurrentPosition;
			Vector3 vector = Vector3.SmoothDamp(currentPosition, extrapolatedSyncPosition, ref smoothDiscontinuityVelocity, 0.125f, float.MaxValue, UnityEngine.Time.fixedDeltaTime);
			velocity = (vector - currentPosition) / UnityEngine.Time.fixedDeltaTime;
		}
		else
		{
			velocity = (extrapolatedSyncPosition - CurrentPosition) / 0.05f;
		}
		Vector3 angularVelocity = UnityExtensions.AngularDisplacementFromTo(CurrentRotation, extrapolatedSyncRotation) / 0.05f;
		UpdatePhysics(velocity, angularVelocity, syncScale);
	}

	private void SimpleKinematicExtrapolateFromLatestSync()
	{
		float timeSinceLastSync = GetTimeSinceLastSync();
		Vector3 vector = syncPosition + syncVelocity * timeSinceLastSync;
		Quaternion extrapolatedSyncRotation = GetExtrapolatedSyncRotation(timeSinceLastSync);
		TransformSetPosition(vector.ValueOrZeroIfBogus(), extrapolatedSyncRotation.ValueOrIdentityIfBogus(), syncScale);
	}

	private Vector3 GetExtrapolatedSyncPosition(float timeSinceLastSync)
	{
		bool flag = ShouldAccountForGravity();
		Vector3 extrapolatedDisplacement = Vector3.zero;
		ExtrapolateSyncVelocityAndDisplacement(timeSinceLastSync, out extrapolatedDisplacement, flag);
		Vector3 vector = syncPosition + extrapolatedDisplacement;
		float sqrMagnitude = extrapolatedDisplacement.sqrMagnitude;
		if (RunCollisionDetectionWhileExtrapolating && sqrMagnitude > 0f && !rigidbodyEx.hasParent)
		{
			float num = Mathf.Sqrt(sqrMagnitude);
			Vector3 vector2 = extrapolatedDisplacement / num;
			if (!rigidbodyEx.hasParent && RunCollisionDetectionWhileExtrapolating && num > Mathf.Epsilon && rigidbodyEx != null && rigidbodyEx.SweepTest(vector2, out var hitInfo, num))
			{
				float num2 = timeSinceLastSync * (1f - hitInfo.distance / num);
				if (flag)
				{
					vector -= Physics.gravity * num2 * num2 / 2f;
				}
				Vector3 vector3 = syncPosition + vector2 * hitInfo.distance;
				Vector3 inDirection = vector - vector3;
				inDirection = Vector3.Reflect(inDirection, hitInfo.normal);
				Vector3 vector4 = Vector3.Project(inDirection, hitInfo.normal);
				Vector3 vector5 = inDirection - vector4;
				float num3 = ((!(collider == null) && !(collider.material == null)) ? collider.material.CombinedBounciness(hitInfo.collider.material) : 1f);
				Vector3 vector6 = vector5 + vector4 * num3;
				vector = vector3 + vector6;
				lastExtrapolatedVelocity = vector6 / inDirection.magnitude * syncVelocity.magnitude;
				if (flag)
				{
					vector += Physics.gravity * num2 * num2 / 2f;
					lastExtrapolatedVelocity += Physics.gravity * num2;
				}
			}
		}
		return vector;
	}

	private Quaternion GetExtrapolatedSyncRotation(float timeSinceLastSync)
	{
		Vector3 angularVelocity = syncAngularVelocity * timeSinceLastSync;
		Quaternion quaternion = UnityExtensions.QuaternionFromAngularVelocity(angularVelocity);
		return quaternion * syncRotation;
	}

	protected virtual void ExtrapolateSyncVelocityAndDisplacement(float timeSinceLastSync, out Vector3 extrapolatedDisplacement, bool extrapolateGravity = false)
	{
		extrapolatedDisplacement = syncVelocity * timeSinceLastSync;
		lastExtrapolatedVelocity = syncVelocity;
		lastExtrapolatedAngularVelocity = syncAngularVelocity;
		if (extrapolateGravity && !rigidbodyEx.hasParent)
		{
			extrapolatedDisplacement += Physics.gravity * timeSinceLastSync * timeSinceLastSync / 2f;
			lastExtrapolatedVelocity += Physics.gravity * timeSinceLastSync;
		}
		if (extrapolatesDrag && !rigidbodyEx.hasParent)
		{
			Vector3 vector = lastExtrapolatedVelocity * (1f - timeSinceLastSync * rigidbodyEx.drag);
			extrapolatedDisplacement += (lastExtrapolatedVelocity - vector) * timeSinceLastSync;
			lastExtrapolatedVelocity = vector;
		}
	}

	private void UpdateDynamicDistanceNetworkOwnershipTransfer()
	{
		Vector3 position = TransformCurrentPositionToWorldSpace(CurrentPosition);
		Player player = Player.FindClosest(position, PotentialOwners);
		if (player != null && player.photonView.ownerId != base.photonView.ownerId && player == Player.LocalPlayer && !isSmoothingDiscontinuity)
		{
			base.photonView.TransferOwnership(player.photonView.ownerId);
		}
	}

	private float GetDynamicDistanceExtrapolation()
	{
		float result = 1f;
		Player player = ((base.photonView.owner != null) ? (base.photonView.owner.TagObject as Player) : null);
		if (player != null && Player.LocalPlayerExists)
		{
			Vector3 position = player.Head.transform.position;
			Vector3 position2 = Player.LocalPlayer.Head.transform.position;
			Vector3 rhs = position2 - position;
			Vector3 vector = TransformCurrentPositionToWorldSpace(CurrentPosition);
			Vector3 lhs = vector - position;
			float num = Vector3.Dot(lhs, rhs);
			float sqrMagnitude = rhs.sqrMagnitude;
			float time = ((sqrMagnitude != 0f) ? (Mathf.Clamp01(num / sqrMagnitude) / 0.5f) : 0f);
			result = NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.DynamicNetworkExtrapolationCurve.Evaluate(time);
		}
		return result;
	}

	private void UpdateSyncParent()
	{
		PhotonView photonView = ((syncParentID == -1) ? null : PhotonView.Find(syncParentID));
		rigidbodyEx.parent = ((!(photonView != null)) ? null : photonView.GetComponent<RigidbodyEx>());
	}

	public void FixedUpdate()
	{
		bool flag = base.hasAuthority;
		if (!flag)
		{
			UpdateNetworkInterpolation();
		}
		if (UseDynamicDistanceExtrapolation && (tool == null || !tool.IsHeld))
		{
			UpdateDynamicDistanceNetworkOwnershipTransfer();
			flag = base.hasAuthority;
		}
		if (flag && ValidPositionBoundsExceeded != null && !RecRoom.Networking.BitPacker.VALID_POSITION_BOUNDS.Contains(rigidbodyEx.physicsPosition))
		{
			ValidPositionBoundsExceeded();
		}
	}

	private void ReevaluateEnabledState()
	{
		bool flag = NeedsToBeEnabled();
		base.enabled = flag;
	}

	private bool NeedsToBeEnabled()
	{
		if (!base.hasAuthority && SynchronizationReadingEnabled && syncHasData)
		{
			return true;
		}
		if (UseDynamicDistanceExtrapolation && (tool == null || !tool.IsHeld))
		{
			return true;
		}
		if (!rigidbodyEx.IsSleeping())
		{
			return true;
		}
		return false;
	}

	private Vector3 TransformCurrentPositionToWorldSpace(Vector3 currentPosition)
	{
		if (rigidbodyEx.hasParent)
		{
			return rigidbodyEx.parent.TargetTransform.TransformPoint(currentPosition);
		}
		return currentPosition;
	}

	private void UpdatePhysics(Vector3 velocity, Vector3 angularVelocity, float scale)
	{
		velocity = velocity.ValueOrZeroIfBogus();
		angularVelocity = angularVelocity.ValueOrZeroIfBogus();
		if (rigidbodyEx != null && !rigidbodyEx.hasParent && !rigidbodyEx.MovesWithProxy && !AlwaysUseAverageKinematicVelocity)
		{
			rigidbodyEx.velocity = velocity;
			rigidbodyEx.angularVelocity = angularVelocity;
		}
		if (!rigidbodyEx.IsPhysicsDriven || AlwaysUseAverageKinematicVelocity || rigidbodyEx.hasParent || rigidbodyEx.MovesWithProxy)
		{
			Vector3 vector = velocity * UnityEngine.Time.fixedDeltaTime + CurrentPosition;
			Quaternion quaternion = UnityExtensions.QuaternionFromAngularVelocity(angularVelocity * UnityEngine.Time.fixedDeltaTime) * CurrentRotation;
			PhysicsSetPosition(vector.ValueOrZeroIfBogus(), quaternion.ValueOrIdentityIfBogus());
		}
		base.transform.SetLocalUniformScale(scale);
	}

	private void PhysicsSetPosition(Vector3 position, Quaternion rotation)
	{
		if (rigidbodyEx.hasParent)
		{
			rigidbodyEx.targetLocalPosition = position;
			rigidbodyEx.targetLocalRotation = rotation;
		}
		else
		{
			rigidbodyEx.targetPosition = position;
			rigidbodyEx.targetRotation = rotation;
		}
	}

	private void TransformSetPosition(Vector3 position, Quaternion rotation, float scale)
	{
		if (rigidbodyEx.hasParent)
		{
			rigidbodyEx.SetDiscontinuousLocalPositionAndLocalRotation(position, rotation);
		}
		else
		{
			rigidbodyEx.SetDiscontinuousPositionAndRotation(position, rotation);
		}
		base.transform.SetLocalUniformScale(scale);
	}

	private void ResetPhysics(Vector3 position, Quaternion rotation, float scale)
	{
		TransformSetPosition(position.ValueOrZeroIfBogus(), rotation.ValueOrIdentityIfBogus(), scale);
		ResetVelocity(Vector3.zero, Vector3.zero);
	}

	private void ResetVelocity(Vector3 newVelocity, Vector3 newAngularVelocity)
	{
		newVelocity = newVelocity.ValueOrZeroIfBogus();
		newAngularVelocity = newAngularVelocity.ValueOrZeroIfBogus();
		if (rigidbodyEx != null)
		{
			if (rigidbodyEx.hasParent)
			{
				rigidbodyEx.ResetVelocityLocalSpace(newVelocity, newAngularVelocity);
			}
			else
			{
				rigidbodyEx.ResetVelocityWorldSpace(newVelocity, newAngularVelocity);
			}
		}
		lastExtrapolatedVelocity = newVelocity;
		lastExtrapolatedAngularVelocity = newAngularVelocity;
	}

	private bool ShouldAccountForGravity()
	{
		if (rigidbodyEx.useGravity && !rigidbodyEx.hasParent)
		{
			float f = Vector3.Dot(syncVelocity, Physics.gravity.normalized);
			return Mathf.Abs(f) > 0.05f;
		}
		return false;
	}

	private void OnRigidbodySleepChange(RigidbodyEx rigidbody)
	{
		ReevaluateEnabledState();
	}

	private void OnPhotonOwnershipChanged(int playerId)
	{
		syncHasData = false;
		if (base.hasAuthority)
		{
			syncRequested = true;
			ResetVelocity(lastExtrapolatedVelocity, lastExtrapolatedAngularVelocity);
		}
		else
		{
			StartSmoothingDiscontinuity();
		}
		ReevaluateEnabledState();
	}

	[PunRPC]
	protected void RpcForceDiscontinuitySync(Vector3 position, Quaternion rotation, float scale, int syncContinuousMovementID)
	{
		RemoteForceDiscontinuitySync(position, rotation, scale, syncContinuousMovementID);
	}
}
namespace RecRoom
{
	public static class PhotonRpcSerialization
	{
		private class SerializerEntry
		{
			public System.Type SerializedType;

			public Converter<object, object> Serializer;

			public Converter<object, object> Deserializer;

			public SerializerEntry(System.Type serializedType, Converter<object, object> serializer, Converter<object, object> deserializer)
			{
				SerializedType = serializedType;
				Serializer = serializer;
				Deserializer = deserializer;
			}
		}

		private static Dictionary<System.Type, SerializerEntry> _registeredSerializers = new Dictionary<System.Type, SerializerEntry>
		{
			{
				typeof(ushort),
				new SerializerEntry(typeof(short), _SerializeUnsignedShort, _DeserializeUnsignedShort)
			},
			{
				typeof(uint),
				new SerializerEntry(typeof(int), _SerializeUnsignedInt, _DeserializeUnsignedInt)
			},
			{
				typeof(ulong),
				new SerializerEntry(typeof(long), _SerializeUnsignedLong, _DeserializeUnsignedLong)
			},
			{
				typeof(PhotonPlayer),
				new SerializerEntry(typeof(int), _SerializePhotonPlayer, _DeserializePhotonPlayer)
			},
			{
				typeof(Player),
				new SerializerEntry(typeof(int), _SerializePlayer, _DeserializePlayer)
			},
			{
				typeof(PhotonView),
				new SerializerEntry(typeof(int), _SerializePhotonView, _DeserializePhotonView)
			},
			{
				typeof(Combatant),
				new SerializerEntry(typeof(int), _SerializeCombatant, _DeserializeCombatant)
			},
			{
				typeof(RequestedEquipmentSpawnParameters),
				new SerializerEntry(typeof(object), _SerializeRequestedEquipmentSpawnParameters, _DeserializeRequestedEquipmentSpawnParameters)
			}
		};

		private static RecRoom.Networking.BitPacker bitPacker = new RecRoom.Networking.BitPacker(1024);

		private static SerializerEntry GetSerializerEntry(System.Type type)
		{
			if (!_registeredSerializers.TryGetValue(type, out var value))
			{
				if (typeof(Photon.MonoBehaviour).IsAssignableFrom(type))
				{
					value = new SerializerEntry(typeof(int), _SerializePhotonMonoBehaviour, _CreateDeserializerForComponent(type));
				}
				else if (typeof(UnityEngine.Component).IsAssignableFrom(type))
				{
					value = new SerializerEntry(typeof(int), _SerializeComponent, _CreateDeserializerForComponent(type));
				}
				else if (typeof(IMessage).IsAssignableFrom(type))
				{
					value = new SerializerEntry(typeof(byte[]), _SerializeProtobuf, _CreateDeserializerForProtobuf(type));
				}
				else if (type.IsEnum)
				{
					value = new SerializerEntry(typeof(int), _SerializeEnum, null);
				}
				else if (type.IsArray)
				{
					System.Type elementType = type.GetElementType();
					SerializerEntry serializerEntry = GetSerializerEntry(elementType);
					if (serializerEntry != null)
					{
						value = new SerializerEntry(serializerEntry.SerializedType.MakeArrayType(), _CreateSerializerForIList(serializerEntry), _CreateDeserializerForArray(serializerEntry, elementType));
					}
				}
				else if (type.IsGenericType && type.GetGenericTypeDefinition() == typeof(List<>))
				{
					System.Type type2 = type.GetGenericArguments()[0];
					SerializerEntry serializerEntry2 = GetSerializerEntry(type2);
					if (serializerEntry2 != null)
					{
						value = new SerializerEntry(serializerEntry2.SerializedType.MakeArrayType(), _CreateSerializerForIList(serializerEntry2), _CreateDeserializerForList(serializerEntry2, type2));
					}
				}
				_registeredSerializers.Add(type, value);
			}
			return value;
		}

		private static Converter<object, object> GetSerializer(System.Type type)
		{
			return GetSerializerEntry(type)?.Serializer;
		}

		private static Converter<object, object> GetDeserializer(System.Type fromType, System.Type toType)
		{
			SerializerEntry serializerEntry = GetSerializerEntry(toType);
			return (serializerEntry == null || !serializerEntry.SerializedType.IsAssignableFrom(fromType)) ? null : serializerEntry.Deserializer;
		}

		private static object _SerializeUnsignedShort(object input)
		{
			return (short)(ushort)input;
		}

		private static object _SerializeUnsignedInt(object input)
		{
			return (int)(uint)input;
		}

		private static object _SerializeUnsignedLong(object input)
		{
			return (long)(ulong)input;
		}

		private static object _SerializePhotonPlayer(object input)
		{
			return ((PhotonPlayer)input).ID;
		}

		private static object _SerializePlayer(object input)
		{
			return ((Player)input).PhotonPlayer.ID;
		}

		private static object _SerializePhotonView(object input)
		{
			return ((PhotonView)input).viewID;
		}

		private static object _SerializeCombatant(object input)
