			return ((Combatant)input).ID;
		}

		private static object _SerializeRequestedEquipmentSpawnParameters(object input)
		{
			RequestedEquipmentSpawnParameters requestedEquipmentSpawnParameters = (RequestedEquipmentSpawnParameters)input;
			return new object[4] { requestedEquipmentSpawnParameters.EquipmentType, requestedEquipmentSpawnParameters.EquipmentSkinId, requestedEquipmentSpawnParameters.WeaponMagazineAmmo, requestedEquipmentSpawnParameters.WeaponReserveAmmo };
		}

		private static object _SerializePhotonMonoBehaviour(object input)
		{
			return ((Photon.MonoBehaviour)input).photonView.viewID;
