		private static object _SerializeEnum(object input)
		{
			return (int)input;
		}

		private static Converter<object, object> _CreateSerializerForIList(SerializerEntry innerSerializerEntry)
		{
			return delegate(object input)
			{
				IList list = (IList)input;
				Array array = Array.CreateInstance(innerSerializerEntry.SerializedType, list.Count);
				for (int i = 0; i < list.Count; i++)
				{
					array.SetValue(innerSerializerEntry.Serializer(list[i]), i);
				}
				return array;
			};
		}

		private static object _DeserializeUnsignedShort(object input)
		{
			return (ushort)(short)input;
		}

		private static object _DeserializeUnsignedInt(object input)
		{
			return (uint)(int)input;
		}

		private static object _DeserializeUnsignedLong(object input)
		{
			return (ulong)(long)input;
		}

		private static object _DeserializePhotonPlayer(object input)
		{
			return PhotonPlayer.Find((int)input);
		}

		private static object _DeserializePlayer(object input)
		{
			return PhotonPlayer.Find((int)input).ToPlayer();
		}

		private static object _DeserializePhotonView(object input)
		{
			return PhotonView.Find((int)input);
		}

		private static object _DeserializeCombatant(object input)
		{
			return new Combatant((int)input);
