		private static object _DeserializeRequestedEquipmentSpawnParameters(object input)
		{
			object[] array = (object[])input;
			return new RequestedEquipmentSpawnParameters
			{
				EquipmentType = (SpawnableToolType)array[0],
				EquipmentSkinId = (string)array[1],
				WeaponMagazineAmmo = (int)array[2],
				WeaponReserveAmmo = (int)array[3]
			};
