		private static Converter<object, object> _CreateDeserializerForComponent(System.Type componentType)
		{
			return delegate(object input)
			{
				PhotonView photonView = PhotonView.Find((int)input);
				return (!(photonView != null)) ? null : photonView.GetComponent(componentType);
			};
		}

		private static Converter<object, object> _CreateDeserializerForProtobuf(System.Type protobufType)
		{
			return delegate(object input)
			{
				IMessage message = (IMessage)Activator.CreateInstance(protobufType);
				message.MergeFrom((byte[])input);
				return message;
			};
		}

		private static Converter<object, object> _CreateDeserializerForArray(SerializerEntry innerSerializerEntry, System.Type type)
		{
			return delegate(object input)
			{
				IList list = (IList)input;
				Array array = Array.CreateInstance(type, list.Count);
				for (int i = 0; i < list.Count; i++)
				{
					array.SetValue(innerSerializerEntry.Deserializer(list[i]), i);
				}
				return array;
			};
		}

		private static Converter<object, object> _CreateDeserializerForList(SerializerEntry innerSerializerEntry, System.Type type)
		{
			return delegate(object input)
			{
				IList list = (IList)input;
				System.Type type2 = typeof(List<>).MakeGenericType(type);
				IList list2 = (IList)Activator.CreateInstance(type2, list.Count);
				for (int i = 0; i < list.Count; i++)
				{
					list2.Add(innerSerializerEntry.Deserializer(list[i]));
				}
				return list2;
			};
		}

		private static object BitPackerWrite<T>(object value, Action<RecRoom.Networking.BitPacker, T> writeCallback)
		{
			lock (bitPacker)
			{
				using MemoryStream memoryStream = new MemoryStream();
				bitPacker.StartWriting(memoryStream);
				writeCallback(bitPacker, (T)value);
				bitPacker.FinishWriting();
				return memoryStream.ToArray();
			}
		}

		private static object BitPackerRead<T>(object bytes, Func<RecRoom.Networking.BitPacker, T> readCallback)
		{
			lock (bitPacker)
			{
				bitPacker.StartReading((byte[])bytes);
				T val = readCallback(bitPacker);
				bitPacker.FinishReading();
				return val;
			}
		}

		private static Converter<object, object> _CreateBitPackerSerializer<T>(Action<RecRoom.Networking.BitPacker, T> writeCallback)
		{
			return (object input) => BitPackerWrite(input, writeCallback);
		}

		private static Converter<object, object> _CreateBitPackerDeserializer<T>(Func<RecRoom.Networking.BitPacker, T> readCallback)
		{
			return (object input) => BitPackerRead(input, readCallback);
		}

		public static bool CanDeserialize(System.Type fromType, System.Type toType)
		{
			return GetDeserializer(fromType, toType) != null;
		}

		public static object[] SerializeParameters(object[] methodParams)
		{
			object[] array = null;
			for (int i = 0; i < methodParams.Length; i++)
			{
				object obj = methodParams[i];
				if (obj == null)
				{
					continue;
				}
				Converter<object, object> serializer = GetSerializer(obj.GetType());
				if (serializer != null)
				{
					if (array == null)
					{
						array = new object[methodParams.Length];
						methodParams.CopyTo(array, 0);
					}
					array[i] = serializer(obj);
				}
			}
			return array ?? methodParams;
		}

		public static object[] DeserializeParameters(object[] methodParams, ParameterInfo[] methodParamInfo)
		{
			object[] array = null;
			for (int i = 0; i < methodParams.Length; i++)
			{
				object obj = methodParams[i];
				if (obj == null)
				{
					continue;
				}
				Converter<object, object> deserializer = GetDeserializer(obj.GetType(), methodParamInfo[i].ParameterType);
				if (deserializer != null)
				{
					if (array == null)
					{
						array = new object[methodParams.Length];
						methodParams.CopyTo(array, 0);
					}
					array[i] = deserializer(methodParams[i]);
				}
			}
			return array ?? methodParams;
		}

		public static void AddHandler(System.Type type, System.Type serializedType, Converter<object, object> serializer, Converter<object, object> deserializer)
		{
			if (_registeredSerializers.ContainsKey(type))
			{
				throw new Exception("RPC serialization handler already registered for type " + type.FullName);
			}
			_registeredSerializers.Add(type, new SerializerEntry(serializedType, serializer, deserializer));
		}

		public static void AddBitPackHandler<T>(Action<RecRoom.Networking.BitPacker, T> writeCallback, Func<RecRoom.Networking.BitPacker, T> readCallback)
		{
			AddHandler(typeof(T), typeof(byte[]), _CreateBitPackerSerializer(writeCallback), _CreateBitPackerDeserializer(readCallback));
		}
	}
}
