	private static void ValidateArguments(PhotonView photonView, Delegate method)
	{
		if (photonView == null)
		{
			throw new ArgumentNullException("photonView");
		}
		if ((object)method == null)
		{
			throw new ArgumentNullException("method");
		}
		Photon.MonoBehaviour monoBehaviour = method.Target as Photon.MonoBehaviour;
		if (monoBehaviour == null)
		{
			throw new ArgumentException("Method must be declared in a class derived from Photon.MonoBehaviour!", "method");
		}
		if (monoBehaviour.photonView != photonView)
		{
			throw new ArgumentException("Method target must be on the same GameObject as the PhotonView!", "method");
		}
	}

	private static PhotonMessageInfo CreateMessageInfo(PhotonView photonView)
	{
		return new PhotonMessageInfo(PhotonNetwork.player, PhotonNetwork.ServerTimestamp, photonView);
	}

	private static void SendRpc(PhotonView photonView, Delegate method, PhotonTargets recipient, params object[] parameters)
	{
		string name = method.Method.Name;
		photonView.RPC(name, recipient, parameters);
	}

	private static void SendRpc(PhotonView photonView, Delegate method, PhotonPlayer recipient, params object[] parameters)
	{
		string name = method.Method.Name;
		photonView.RPC(name, recipient, parameters);
	}

	private static bool ShouldSendToOthers()
	{
		return PhotonNetwork.otherPlayers.Length > 0;
	}

	public static void RpcAll(this PhotonView photonView, Action method)
	{
		ValidateArguments(photonView, method);
		if (ShouldSendToOthers())
		{
			SendRpc(photonView, method, PhotonTargets.Others);
		}
		method();
	}

