public class PUNNetworkManager : NetworkedSingletonMonoBehaviour<PUNNetworkManager>
{
	private enum ErrorContext
	{
		Unknown,
		ConnectionFailed,
		FailedToConnect,
		FailedToJoinRoom,
		TimeoutWhileConnecting
	}

	private enum GameSessionJoinState
	{
		None,
		ConnectingToMasterServer,
		ConnectingToGameServer,
		LoadingScene,
		WaitingToSpawnPlayer,
		ConnectedToGame
	}

	public const string MODERATOR_ROOM_SCENE_NAME = "moderator";

	public const string EMPTY_SCENE_NAME = "empty";

	public const string MAIN_ROOT_SCENE_NAME = "main_root";

	private const string RICH_JOIN_COMMAND_PREFIX = "+join:";

	public const int DEFAULT_ROOM_SIZE = 8;

	private const float PHOTON_CONNECTION_TIMEOUT = 20f;

	private const float MASTER_ROOM_LOAD_TIMEOUT = 60f;

	private const int PHOTON_SEND_RATE = 30;

	private const int PHOTON_SEND_RATE_ON_SERIALIZE = 15;

	private const float PHOTON_ROOM_HEARTBEAT_INTERVAL = 5f;

	private const string PHOTON_ROOM_HEARTBEAT_PROPERTY = "HB";

	public static readonly ExitGames.Client.Photon.Hashtable PhotonRoomPropertiesBugWorkaround = new ExitGames.Client.Photon.Hashtable { { "BUG", 1 } };

	private const float RUNNING_NETWORK_TIMEOUT = 20f;

	private const float SCENE_LOADING_NETWORK_TIMEOUT = 180f;

	private const int MAX_VOICE_RECONNECT_COUNT = 5;

	private const int ErrorUnknownReason = -1;

	private const int ErrorDisconnectedFromRecNet = -2;

	private const int ErrorFailedToInitiatePhotonConnection = -3;

	private const int ErrorTimeoutConnectingToMasterServer = -4;

	private const int ErrorTimeoutConnectingToGameServer = -5;

	private const int ErrorTimeoutWaitingToSpawn = -6;

