	public event Action<PhotonPlayer> PhotonPlayerDisconnected
	{
		add
		{
			Action<PhotonPlayer> action = this.m_PhotonPlayerDisconnected;
			Action<PhotonPlayer> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PhotonPlayerDisconnected, (Action<PhotonPlayer>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<PhotonPlayer> action = this.m_PhotonPlayerDisconnected;
			Action<PhotonPlayer> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PhotonPlayerDisconnected, (Action<PhotonPlayer>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		ResumeMessageQueueOnDestroy();
		PhotonNetwork.OnLeftRoom -= new Action(OnLeftRoom);
		PhotonNetwork.OnDisconnectedFromPhoton -= new Action(OnDisconnectedFromPhoton);
		PhotonNetwork.OnConnectedToMaster -= new Action(OnConnectedToMaster);
		PhotonNetwork.OnJoinedRoom -= new Action(OnJoinedRoom);
		PhotonNetwork.OnPhotonJoinRoomFailed -= new Action<short, string>(OnPhotonJoinRoomFailed);
		PhotonNetwork.OnConnectionFail -= new Action<DisconnectCause>(OnConnectionFail);
		PhotonNetwork.OnFailedToConnectToPhoton -= new Action<DisconnectCause>(OnFailedToConnectToPhoton);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		if (PhotonVoiceNetwork.Client != null)
		{
			UnityVoiceFrontend client = PhotonVoiceNetwork.Client;
			client.OnStateChangeAction = (Action<ExitGames.Client.Photon.LoadBalancing.ClientState>)Delegate.Remove(client.OnStateChangeAction, new Action<ExitGames.Client.Photon.LoadBalancing.ClientState>(OnPhotonVoiceStateChange));
		}
		Profiles.LocalProfileDownloaded -= Profile_LocalProfileDownloaded;
		Presence.OnPlayerPresenceUpdated -= OnPlayerPresenceUpdated;
	}

	public IEnumerator PingPhotonRegions()
	{
		GameSessions.CloudRegionPings.Clear();
		if (PhotonNetwork.connectionState != ConnectionState.Disconnected)
		{
			UnityEngine.Debug.LogError("RegionPing: Only allowed while disconnected");
			yield break;
		}
		PhotonNetwork.PhotonServerSettings.HostType = ServerSettings.HostingOption.PhotonCloud;
		PhotonNetwork.OverrideBestCloudServer(CloudRegionCode.none);
		if (!PhotonNetwork.ConnectToBestCloudServer(BuildSettings.Version))
		{
			UnityEngine.Debug.LogError("RegionPing: Failed to initiate connection NameServer");
			yield break;
		}
		yield return new WaitWhile(() => PhotonNetwork.connectionStateDetailed == ClientState.ConnectingToNameServer);
		if (PhotonNetwork.connectionStateDetailed != ClientState.ConnectedToNameServer)
		{
			UnityEngine.Debug.LogError("RegionPing: Failed to connect to NameServer");
			yield break;
		}
		Stopwatch timer = new Stopwatch();
		yield return new WaitWhile(() => PhotonNetwork.connectionStateDetailed == ClientState.ConnectedToNameServer && PhotonNetwork.networkingPeer.AvailableRegions == null && timer.ElapsedMilliseconds < 5000);
		if (PhotonNetwork.networkingPeer.AvailableRegions == null || PhotonNetwork.networkingPeer.AvailableRegions.Count == 0)
		{
			UnityEngine.Debug.LogError("RegionPing: Unable to retrieve available regions");
			yield break;
		}
		PhotonPingManager pingManager = new PhotonPingManager();
		foreach (Region availableRegion in PhotonNetwork.networkingPeer.AvailableRegions)
		{
			StartCoroutine(pingManager.PingSocket(availableRegion));
		}
		yield return new WaitUntil(() => pingManager.Done);
		foreach (Region availableRegion2 in PhotonNetwork.networkingPeer.AvailableRegions)
		{
			GameSessions.CloudRegionPings.Add(new GameSessions.CloudRegionPing(availableRegion2.Code, availableRegion2.Ping));
		}
	}

	public void Initialize()
	{
		PhotonNetwork.OnLeftRoom += new Action(OnLeftRoom);
		PhotonNetwork.OnDisconnectedFromPhoton += new Action(OnDisconnectedFromPhoton);
		PhotonNetwork.OnConnectedToMaster += new Action(OnConnectedToMaster);
		PhotonNetwork.OnJoinedRoom += new Action(OnJoinedRoom);
		PhotonNetwork.OnPhotonJoinRoomFailed += new Action<short, string>(OnPhotonJoinRoomFailed);
		PhotonNetwork.OnConnectionFail += new Action<DisconnectCause>(OnConnectionFail);
		PhotonNetwork.OnFailedToConnectToPhoton += new Action<DisconnectCause>(OnFailedToConnectToPhoton);
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		UnityVoiceFrontend client = PhotonVoiceNetwork.Client;
		client.OnStateChangeAction = (Action<ExitGames.Client.Photon.LoadBalancing.ClientState>)Delegate.Combine(client.OnStateChangeAction, new Action<ExitGames.Client.Photon.LoadBalancing.ClientState>(OnPhotonVoiceStateChange));
		Profiles.LocalProfileDownloaded += Profile_LocalProfileDownloaded;
		Presence.OnPlayerPresenceUpdated += OnPlayerPresenceUpdated;
		PhotonNetwork.sendRate = 30;
		PhotonNetwork.sendRateOnSerialize = 15;
		PhotonNetwork.BackgroundTimeout = 20f;
		PhotonNetwork.UseRpcMonoBehaviourCache = true;
		PhotonNetwork.automaticallySyncScene = false;
		PhotonNetwork.player.RecNetProfileId = RecNet.Core.LocalProfileId;
		PhotonNetwork.player.NickName = Profiles.LocalProfile.DisplayName;
		PhotonNetwork.lobby = new TypedLobby("lobby", LobbyType.SqlLobby);
		PhotonNetwork.autoJoinLobby = false;
		PhotonConfig photonConfig = Config.PhotonConfig;
		PhotonNetwork.CrcCheckEnabled = photonConfig.CrcCheckEnabled;
		PhotonVoiceSettings.Instance.AutoConnect = false;
		PhotonVoiceSettings.Instance.AutoDisconnect = false;
	}

	private void OnPhotonVoiceStateChange(ExitGames.Client.Photon.LoadBalancing.ClientState newState)
	{
		if (newState == ExitGames.Client.Photon.LoadBalancing.ClientState.Disconnected && PhotonNetwork.inRoom && !PhotonNetwork.offlineMode && Profiles.LocalProfile != null && !Profiles.LocalProfile.JuniorProfile)
		{
			if (voiceReconnectCounter < 5)
			{
				voiceReconnectCounter++;
				UnityEngine.Debug.LogErrorFormat("Voice connection lost. Attempting to reconnect ({0}/{1}).", voiceReconnectCounter, 5);
				PhotonVoiceNetwork.Connect();
			}
			else
			{
				UnityEngine.Debug.LogError("Voice connection lost. Reconnect attempt limit exceeded!");
			}
		}
	}

	private void OnApplicationQuit()
	{
		isQuitting = true;
	}

	private void Profile_LocalProfileDownloaded(Profile profile)
	{
		if (profile != null && !string.IsNullOrEmpty(profile.DisplayName) && PhotonNetwork.player != null && (ObscuredString)PhotonNetwork.player.NickName != profile.DisplayName)
		{
			PhotonNetwork.player.NickName = profile.DisplayName;
		}
	}

	private void OnPlayerPresenceUpdated(long playerId)
	{
		if (playerId != RecNet.Core.LocalProfileId)
		{
			return;
		}
		GameSession gameSession = Presence.Get(playerId).GameSession ?? GameSession.OfflineGameSession;
		if (gameSession == GameSession.OfflineGameSession)
		{
			if (targetGameSession != GameSession.OfflineGameSession)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle = disconnectAlertTitle;
				SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = string.Format(timeoutDisconnectMessage, -2);
				JoinPhotonRoomGameSession(gameSession);
			}
		}
		else if (gameSession.Location != RoomSceneLocations.INVALID)
		{
			if (targetGameSession.PhotonRegionId != gameSession.PhotonRegionId || targetGameSession.PhotonRoomId != gameSession.PhotonRoomId)
			{
				if (GameSessions.LocalGameSession.Location == RoomSceneLocations.REC_CENTER && gameSession.Location != RoomSceneLocations.DORM_ROOM && gameSession.Location != RoomSceneLocations.REC_CENTER)
				{
					base.photonView.RpcOthers(RpcPlayerSwitchedActivity, RecNet.Core.LocalProfileId, gameSession.Name);
				}
				JoinPhotonRoomGameSession(gameSession);
			}
			else
			{
				if (GameSessions.LocalGameSession == targetGameSession)
				{
					GameSessions.SetLocalGameSession(gameSession);
				}
				targetGameSession = gameSession;
			}
		}
		else
		{
			SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = "An update is required to join " + gameSession.Name;
			SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle = null;
			GameSessions.GoToDormRoom();
		}
	}

	[PunRPC]
	private void RpcPlayerSwitchedActivity(long profileId, string destination)
	{
		Profile profile = Profiles.Get(profileId);
		if (profile != null)
		{
			string value = profile.DisplayName;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, string.Format("{0} went to {1}", value.Truncate(12, "..."), destination), 3f);
		}
	}

	private void JoinPhotonRoomGameSession(GameSession gameSession)
	{
		TrackLevelLoadDuration();
		targetGameSession = gameSession;
		StopAllCoroutines();
		StartCoroutine(FadeOutToJoinRoom());
	}

	private void TrackLevelLoadDuration()
	{
		if (!isTrackingLoad && SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			isTrackingLoad = true;
			loadStartTime = DateTime.UtcNow;
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += RecordLevelLoadComplete;
		}
	}

	private void RecordLevelLoadComplete()
	{
		isTrackingLoad = false;
		SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= RecordLevelLoadComplete;
		double totalSeconds = (DateTime.UtcNow - loadStartTime).TotalSeconds;
		SingletonMonoBehaviour<ActivitySessionAnalytics>.Instance.RecordLoadTime(totalSeconds, PhotonNetwork.isMasterClient);
	}

	private IEnumerator FadeOutToJoinRoom()
	{
		if (Player.LocalPlayerExists)
		{
			yield return Player.LocalPlayer.DespawnLocal(prepForLevelSwitch: true);
		}
		else
		{
			yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: false, prepForLevelSwitch: true, suppressEffect: true, 1f);
		}
		SetGameSessionJoinState(GameSessionJoinState.ConnectingToMasterServer);
		if (PhotonNetwork.offlineMode)
		{
			PhotonNetwork.DestroyAll();
		}
		if (PhotonNetwork.connectionState == ConnectionState.Disconnected)
		{
			ConnectToTargetPhotonRegion();
		}
		else if (targetGameSession.PhotonRegionId == currentPhotonRegion && PhotonNetwork.inRoom)
		{
			if (!PhotonNetwork.LeaveRoom())
			{
				UnityEngine.Debug.LogError("Failed to leave Photon room");
				disconnectingToSwitchRegions = true;
				PhotonNetwork.Disconnect();
			}
		}
		else
		{
			disconnectingToSwitchRegions = true;
			PhotonNetwork.Disconnect();
		}
	}

	private void OnLeftRoom()
	{
		PhotonVoiceNetwork.Disconnect();
		if (SceneManagerHelper.ActiveSceneName != "empty")
		{
			SceneManager.LoadScene("empty");
		}
	}

	private void OnDisconnectedFromPhoton()
	{
		if (isQuitting)
		{
			return;
		}
		if (disconnectingToSwitchRegions)
		{
			disconnectingToSwitchRegions = false;
			ConnectToTargetPhotonRegion();
			return;
		}
		if (lastErrorContext != ErrorContext.FailedToJoinRoom)
		{
			unexpectedDisconnectHasOccurred = true;
		}
		HandleUnexpectedDisconnect();
	}

	private void HandleUnexpectedDisconnect()
	{
		StopAllCoroutines();
		switch (gameJoinState)
		{
		case GameSessionJoinState.ConnectingToMasterServer:
			GameSessions.ReportGameJoinResult(targetGameSession, GameSessions.GameJoinResult.FailedToConnectToRegion);
			break;
		case GameSessionJoinState.ConnectingToGameServer:
			GameSessions.ReportGameJoinResult(targetGameSession, GameSessions.GameJoinResult.FailedToConnectToRoom);
			break;
		case GameSessionJoinState.WaitingToSpawnPlayer:
			GameSessions.ReportGameJoinResult(targetGameSession, GameSessions.GameJoinResult.FailedToSpawnPlayer);
			break;
		}
		string format = ((lastErrorCode != 1040 && lastErrorCode != 1041 && lastErrorCode != 1023 && lastErrorContext != ErrorContext.TimeoutWhileConnecting) ? genericDisconnectMessage : ((lastErrorContext != ErrorContext.ConnectionFailed) ? timeoutCouldntConnectMessage : timeoutDisconnectMessage));
		SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle = disconnectAlertTitle;
		SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = string.Format(format, (!lastErrorCode.HasValue) ? (-1) : lastErrorCode.Value);
		lastErrorCode = null;
		lastErrorContext = ErrorContext.Unknown;
		GameSessions.GoToDormRoom().Error(delegate(string error)
		{
			UnityEngine.Debug.LogError("Unable to return to dorm room after unexpected network disconnect: " + error);
			Presence.UpdateLocalGameSession(null);
		}).Then(delegate(GameSessions.JoinGameErrorCode response)
		{
			if (response != GameSessions.JoinGameErrorCode.Success)
			{
				UnityEngine.Debug.LogError("Unable to return to dorm room after unexpected network disconnect: " + response);
				Presence.UpdateLocalGameSession(null);
			}
		});
	}

	private void ConnectToTargetPhotonRegion()
	{
		if (targetGameSession.PhotonRegionId != CloudRegionCode.none)
		{
			PhotonNetwork.offlineMode = false;
			PhotonNetwork.PhotonServerSettings.PreferredRegion = targetGameSession.PhotonRegionId;
			PhotonNetwork.EnableServerTracing = unexpectedDisconnectHasOccurred && Config.PhotonConfig.EnableServerTracingAfterDisconnect;
			if (!PhotonNetwork.ConnectUsingSettings(BuildSettings.Version))
			{
				UnityEngine.Debug.LogError("Unable to initiate Photon connection operation");
				lastErrorCode = -3;
				lastErrorContext = ErrorContext.FailedToConnect;
				HandleUnexpectedDisconnect();
			}
		}
		else
		{
			PhotonNetwork.offlineMode = true;
		}
	}

	private void OnConnectedToMaster()
	{
		currentPhotonRegion = (PhotonNetwork.offlineMode ? CloudRegionCode.none : PhotonNetwork.CloudRegion);
		if (targetGameSession.PhotonRegionId != currentPhotonRegion)
		{
			SetGameSessionJoinState(GameSessionJoinState.ConnectingToMasterServer);
			disconnectingToSwitchRegions = true;
			PhotonNetwork.Disconnect();
			return;
		}
		GameSessions.SetLocalGameSession(targetGameSession);
		RoomOptions roomOptions = new RoomOptions();
		roomOptions.CustomRoomProperties = PhotonRoomPropertiesBugWorkaround;
		roomOptions.DeleteNullProperties = true;
		roomOptions.PublishUserId = true;
		roomOptions.PlayerTtl = 1000;
		RoomOptions roomOptions2 = roomOptions;
		SetGameSessionJoinState(GameSessionJoinState.ConnectingToGameServer);
		if (!PhotonNetwork.JoinOrCreateRoom(targetGameSession.PhotonRoomId, roomOptions2, PhotonNetwork.lobby))
		{
			UnityEngine.Debug.LogError("Unable to initiate room join operation");
			lastErrorCode = -3;
			lastErrorContext = ErrorContext.FailedToJoinRoom;
			HandleUnexpectedDisconnect();
		}
	}

	private void OnJoinedRoom()
	{
		StartCoroutine(HeartbeatCoroutine());
		StartCoroutine(PostRoomJoinCoroutine());
	}

	private IEnumerator PostRoomJoinCoroutine()
	{
		voiceReconnectCounter = 0;
		SetGameSessionJoinState(GameSessionJoinState.LoadingScene);
		yield return LoadSceneCoroutine();
		if (!PhotonNetwork.offlineMode && Profiles.LocalProfile != null && !Profiles.LocalProfile.JuniorProfile)
		{
			PhotonVoiceNetwork.Connect();
		}
		if (RecRoomSceneManager.Instance.SpawnPlayersInRoom)
		{
			SetGameSessionJoinState(GameSessionJoinState.WaitingToSpawnPlayer);
			yield return new WaitUntil(() => Player.LocalPlayerExists);
		}
		else
		{
			yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: true, prepForLevelSwitch: false, suppressEffect: true, 1f);
		}
		SetGameSessionJoinState(GameSessionJoinState.ConnectedToGame);
	}

	public void PauseMessageQueue()
	{
		messageQueuePauseCounter++;
		if (messageQueuePauseCounter == 1)
		{
			if (PhotonNetwork.inRoom)
			{
				SynchronizedField.SendPendingRoomUpdates();
				PhotonNetwork.SendOutgoingCommands();
			}
			PhotonNetwork.isMessageQueueRunning = false;
			PhotonNetwork.BackgroundTimeout = 180f;
		}
	}

	public void ResumeMessageQueue()
	{
		messageQueuePauseCounter = Mathf.Max(0, messageQueuePauseCounter - 1);
		if (messageQueuePauseCounter == 0)
		{
			PhotonNetwork.isMessageQueueRunning = true;
			PhotonNetwork.BackgroundTimeout = 20f;
		}
	}

	private void ResumeMessageQueueOnDestroy()
	{
		messageQueuePauseCounter = 0;
		PhotonNetwork.isMessageQueueRunning = true;
		PhotonNetwork.BackgroundTimeout = 20f;
	}

	private unsafe IEnumerator LoadSceneCoroutine()
	{
		string sceneName = AGRoomSettings.GetSceneNameFromRoomSceneLocation(GameSessions.LocalGameSession.Location);
		PauseMessageQueue();
		PhotonNetwork.LoadLevel(sceneName);
		yield return new WaitUntil(new Func<bool>(null, (nint)(delegate*<bool>)(&RecRoomSceneManager.get_IsInitialized)));
		ResumeMessageQueue();
	}

	private IEnumerator HeartbeatCoroutine()
	{
		WaitForSeconds wait = new WaitForSeconds(5f);
		while (true)
		{
			if (PhotonNetwork.inRoom && PhotonNetwork.isMasterClient)
			{
				PhotonNetwork.room.SetCustomProperties(new ExitGames.Client.Photon.Hashtable { 
				{
					"HB",
					PhotonNetwork.ServerTimestamp
				} });
			}
			yield return wait;
		}
	}

	private void SetGameSessionJoinState(GameSessionJoinState newState)
	{
		if (gameJoinTimeoutCoroutine != null)
		{
			StopCoroutine(gameJoinTimeoutCoroutine);
			gameJoinTimeoutCoroutine = null;
		}
		gameJoinState = newState;
		switch (gameJoinState)
		{
		case GameSessionJoinState.ConnectedToGame:
			GameSessions.ReportGameJoinResult(targetGameSession, GameSessions.GameJoinResult.Success);
			break;
		case GameSessionJoinState.ConnectingToMasterServer:
		case GameSessionJoinState.ConnectingToGameServer:
		case GameSessionJoinState.WaitingToSpawnPlayer:
			gameJoinTimeoutCoroutine = StartCoroutine(GameJoinTimeoutCoroutine());
			break;
		case GameSessionJoinState.LoadingScene:
			break;
		}
	}

	private IEnumerator GameJoinTimeoutCoroutine()
	{
		yield return new WaitForSecondsIgnoreHitches(20f);
		switch (gameJoinState)
		{
		case GameSessionJoinState.ConnectingToMasterServer:
			UnityEngine.Debug.LogErrorFormat("Timeout waiting to connect to master server (state: {0}, region: {1})", PhotonNetwork.connectionStateDetailed, targetGameSession.PhotonRegionId);
			lastErrorCode = -4;
			break;
		case GameSessionJoinState.ConnectingToGameServer:
			UnityEngine.Debug.LogErrorFormat("Timeout waiting to join game (state: {0}, region: {1})", PhotonNetwork.connectionStateDetailed, targetGameSession.PhotonRegionId);
			lastErrorCode = -5;
			break;
		case GameSessionJoinState.WaitingToSpawnPlayer:
		{
			if (PhotonNetwork.inRoom && PhotonNetwork.room.CustomProperties.TryGetValue("HB", out var heartbeatValue) && heartbeatValue != null && (float)(PhotonNetwork.ServerTimestamp - (int)heartbeatValue) < 60000f)
			{
				yield return new WaitForSecondsIgnoreHitches(60f);
				UnityEngine.Debug.LogError("Timeout waiting to spawn player (zombie room, with heartbeat)");
			}
			else
			{
				UnityEngine.Debug.LogError("Timeout waiting to spawn player (zombie room, no heartbeat)");
			}
			lastErrorCode = -6;
			break;
		}
		default:
			UnityEngine.Debug.LogErrorFormat("GameJoinTimeoutCoroutine() running in unexpected state: {0}", gameJoinState);
			yield break;
		}
		lastErrorContext = ErrorContext.TimeoutWhileConnecting;
		HandleUnexpectedDisconnect();
	}

	private void OnPhotonJoinRoomFailed(short roomJoinErrorCode, string roomJoinDebugErrorMessage)
	{
		UnityEngine.Debug.LogErrorFormat("Failed to Join Photon Room (Error Code {0}: \"{1}\")", roomJoinErrorCode, roomJoinDebugErrorMessage);
		AnalyticsHelper.NetworkRoomJoin(roomJoinErrorCode);
		lastErrorCode = roomJoinErrorCode;
		lastErrorContext = ErrorContext.FailedToJoinRoom;
		PhotonNetwork.Disconnect();
	}

	private void OnConnectionFail(DisconnectCause cause)
	{
		UnityEngine.Debug.LogError("Connection failed: " + cause);
		AnalyticsHelper.UnexpectedConnectionFailure(cause);
		lastErrorCode = (int)cause;
		lastErrorContext = ErrorContext.ConnectionFailed;
	}

	private void OnFailedToConnectToPhoton(DisconnectCause cause)
	{
		UnityEngine.Debug.LogError("Failed to connect: " + cause);
		AnalyticsHelper.UnexpectedFailureToConnect(cause);
		lastErrorCode = (int)cause;
		lastErrorContext = ErrorContext.FailedToConnect;
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (PhotonNetwork.isMasterClient)
		{
			MasterSwitchToLowestPingPlayer();
			MasterSendRemotePlayerRecNetDisconnect(player);
		}
		if (this.PhotonPlayerDisconnected != null)
		{
			this.PhotonPlayerDisconnected(player);
		}
	}

	public void MasterSendRemotePlayerRecNetDisconnect(PhotonPlayer player)
	{
		if (player != null)
		{
			Presence.SendRemotePlayerDisconnectRequest(player.RecNetProfileId);
		}
	}

	public void MasterSwitchToLowestPingPlayer()
	{
		if (!PhotonNetwork.inRoom || PhotonNetwork.offlineMode || !PhotonNetwork.isMasterClient || !Player.LocalPlayerExists)
		{
			return;
		}
		Player player = Player.LocalPlayer;
		bool flag = player.Platform == PlatformManager.PlatformType.PlayStation;
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			if (photonPlayer.IsRecNetBot)
			{
				continue;
			}
			Player player2 = photonPlayer.ToPlayer();
			if (!(player2 != null))
			{
				continue;
			}
			bool flag2 = player2.Platform == PlatformManager.PlatformType.PlayStation;
			if (flag2 == flag)
			{
				if (player.Ping - player2.Ping > 5)
				{
					player = player2;
					flag = flag2;
				}
			}
			else if (!flag2)
			{
				player = player2;
				flag = flag2;
			}
		}
		if (player != Player.LocalPlayer)
		{
			PhotonNetwork.SetMasterClient(player.PhotonPlayer);
			AnalyticsHelper.NetworkNewMasterClientSelected(player, Player.LocalPlayer);
		}
	}

	public void ProcessRichJoinCommand(string connectCommand)
	{
		if (RecRoomSceneManager.Instance != null && !string.IsNullOrEmpty(connectCommand) && connectCommand.StartsWith("+join:"))
		{
			string s = connectCommand.Substring("+join:".Length);
			if (long.TryParse(s, out var result))
			{
				SingletonMonoBehaviour<SessionManager>.Instance.JoinPlayer(result, SessionManager.JoinRoomInviteMode.LeaveParty);
			}
		}
	}

	public long? CheckCommandLineArgsForRichPresenceJoin()
	{
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		if (commandLineArgs == null)
		{
			return null;
		}
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i] != null && commandLineArgs[i].StartsWith("+join:") && long.TryParse(commandLineArgs[i].Substring("+join:".Length), out var result))
			{
				return result;
			}
		}
		return null;
	}

	public static string CheckCommandLineArgsFor(string prefix)
	{
		string[] commandLineArgs = Environment.GetCommandLineArgs();
		if (commandLineArgs == null)
		{
			return null;
		}
		for (int i = 0; i < commandLineArgs.Length; i++)
		{
			if (commandLineArgs[i] != null && commandLineArgs[i].StartsWith(prefix, StringComparison.InvariantCultureIgnoreCase))
			{
				return commandLineArgs[i].Substring(prefix.Length);
			}
		}
		return null;
	}

	public PhotonPlayer DebugChangeMasterClient()
	{
		AnalyticsHelper.DebugAction("ChangeMaster");
		if (SessionManager.IsDeveloper)
		{
			int num = 0;
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				if (PhotonNetwork.playerList[i].IsMasterClient)
				{
					num = i;
					break;
				}
			}
			num = (num + 1) % PhotonNetwork.playerList.Length;
			PhotonNetwork.SetMasterClient(PhotonNetwork.playerList[num]);
			return PhotonNetwork.playerList[num];
		}
		return PhotonNetwork.player;
	}
}
namespace RecRoom.Persistence
{
	public static class CircuitNodePersistence
	{
		public static void CheckForRequiredCircuitNodeId(PersistenceViewData viewData, Dictionary<int, int> nodeIdMappings, RoomPersistenceVersion persistenceVersion)
		{
			if (viewData.SpawnableToolData == null)
			{
				return;
			}
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.SpawnableToolData.PrefabId);
			if (guid == Guid.Empty)
			{
				return;
			}
			SpawnableToolConfig.Config spawnableToolConfig = SpawnableToolSettings.GetSpawnableToolConfig(guid);
			if (spawnableToolConfig == null)
			{
				return;
			}
			CircuitNodeType circuitNodeType = spawnableToolConfig.CircuitNodeType;
			if (circuitNodeType == null || string.IsNullOrEmpty(circuitNodeType.uuid))
			{
				CleanupExtraNode(viewData, guid, nodeIdMappings);
				return;
			}
			if (!circuitNodeType.TryGetCircuitNodeType(out var guid2, out var t))
			{
				throw new InvalidOperationException("Bad circuit node type in equipment config for prefab:" + guid.ToString());
			}
			if (viewData.CircuitNodeData == null || viewData.CircuitNodeData.CircuitNodeId == 0)
			{
				CreateMissingCircuitNode(viewData, t, nodeIdMappings);
			}
			if (nodeIdMappings != null && !nodeIdMappings.ContainsKey(viewData.CircuitNodeData.CircuitNodeId))
			{
				string message = "Expected a node ID mapping for unmappedId " + viewData.CircuitNodeData.CircuitNodeId + "\nExpected type:" + guid2.ToString();
				throw new InvalidOperationException(message);
			}
			foreach (CircuitTypeMigration allCircuitTypeMigration in CircuitTypeMigration.AllCircuitTypeMigrations)
			{
				allCircuitTypeMigration.Run(viewData, nodeIdMappings, persistenceVersion);
			}
			CheckNodeType(viewData.CircuitNodeData.CircuitNodeId, guid2, nodeIdMappings);
		}

		public static void CleanupExtraNode(PersistenceViewData viewData, Guid prefabGuid, Dictionary<int, int> nodeIdMappings, bool isError = true)
		{
			if (viewData.CircuitNodeData != null && viewData.CircuitNodeData.CircuitNodeId != 0)
			{
				int circuitNodeId = viewData.CircuitNodeData.CircuitNodeId;
				int num = circuitNodeId;
				if (nodeIdMappings != null)
				{
					num = nodeIdMappings[circuitNodeId];
				}
				if (isError)
				{
					UnityEngine.Debug.LogErrorFormat("Found a node we're not supposed to have for prefab {0}! ID: {1}=>{2}", prefabGuid, circuitNodeId, num);
				}
				else
				{
					UnityEngine.Debug.LogFormat("Removed node for prefab {0}! ID: {1}=>{2}", prefabGuid, circuitNodeId, num);
				}
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.MasterLocalDestroyNode(num);
				nodeIdMappings?.Remove(circuitNodeId);
				viewData.CircuitNodeData = null;
			}
		}

		public static int CreateMissingCircuitNode(PersistenceViewData viewData, System.Type circuitNodeType, Dictionary<int, int> nodeIdMappings, bool isWarning = true)
		{
			int num = CircuitNode.NewNodeId();
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.MasterLocalInstantiateNode(circuitNodeType, num);
			viewData.CircuitNodeData = new RecRoom.Protobuf.CircuitNodeData
			{
				CircuitNodeId = num
			};
			nodeIdMappings?.Add(num, num);
			if (isWarning)
			{
				UnityEngine.Debug.LogWarningFormat("Created missing CircuitNode: {0}", num);
			}
			return num;
		}

		public static void GetNodeType(int circuitId, Dictionary<int, int> nodeIdMappings, out CircuitNode node, out Guid nodeTypeGuid)
		{
			int id = circuitId;
			if (nodeIdMappings != null)
			{
				id = nodeIdMappings[circuitId];
			}
			node = CircuitNode.Find(id);
			nodeTypeGuid = Serialization.GetNodeTypeGuid(node);
		}

		public static void CheckNodeType(int circuitId, Guid equipmentCircuitNodeGuid, Dictionary<int, int> nodeIdMappings)
		{
			CircuitNode node = null;
			Guid nodeTypeGuid = Guid.Empty;
			GetNodeType(circuitId, nodeIdMappings, out node, out nodeTypeGuid);
			if (node != null && nodeTypeGuid != equipmentCircuitNodeGuid)
			{
				throw new ArgumentException($"Found node type mismatch for node type. Expected \"{equipmentCircuitNodeGuid}\" but found \"{nodeTypeGuid.ToString()}\"");
			}
		}
	}
	public struct CircuitTypeMigration
	{
		public static List<CircuitTypeMigration> AllCircuitTypeMigrations = new List<CircuitTypeMigration>
		{
			new CircuitTypeMigration(9, SpawnableToolType.TRIGGER_VOLUME, typeof(SourceNode), typeof(QueuedMomentarySourceNode), keepCircuitLinks: true)
		};

		public readonly int RunBeforePersistenceVersion;

		public readonly SpawnableToolType PrefabType;

		public readonly System.Type OldNodeType;

		public readonly System.Type NewNodeType;

		public readonly bool KeepCircuitLinks;

		public CircuitTypeMigration(int runBeforePersistenceVersion, SpawnableToolType prefabType, System.Type oldNodeType, System.Type newNodeType, bool keepCircuitLinks)
		{
			RunBeforePersistenceVersion = runBeforePersistenceVersion;
			PrefabType = prefabType;
			OldNodeType = oldNodeType;
			NewNodeType = newNodeType;
			KeepCircuitLinks = keepCircuitLinks;
		}

		public void Run(PersistenceViewData viewData, Dictionary<int, int> nodeIdMappings, RoomPersistenceVersion persistenceVersion)
		{
			if ((int)persistenceVersion >= RunBeforePersistenceVersion)
			{
				return;
			}
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.SpawnableToolData.PrefabId);
			Guid spawnableToolPrefabId = SpawnableToolSettings.GetSpawnableToolPrefabId(PrefabType);
			if (guid != spawnableToolPrefabId)
			{
				return;
			}
			int circuitNodeId = viewData.CircuitNodeData.CircuitNodeId;
			CircuitNode node = null;
			Guid nodeTypeGuid = Guid.Empty;
			CircuitNodePersistence.GetNodeType(circuitNodeId, nodeIdMappings, out node, out nodeTypeGuid);
			System.Type type = node.GetType();
			if (type != OldNodeType)
			{
				return;
			}
			UnityEngine.Debug.LogFormat("Converting prefab node type:{0} from {1} to {2}", PrefabType, OldNodeType, NewNodeType);
			List<CircuitLink> list = (from _ in node.Inputs
				select _.Value into link
				where !link.SourceNode.IsVirtual
				select link).ToList();
			List<CircuitLink> list2 = (from link in node.Outputs.SelectMany((KeyValuePair<OutputSlot, HashSet<CircuitLink>> _) => _.Value)
				where !link.DestNode.IsVirtual
				select link).ToList();
			CircuitNodePersistence.CleanupExtraNode(viewData, guid, nodeIdMappings, isError: false);
			int num = CircuitNodePersistence.CreateMissingCircuitNode(viewData, NewNodeType, nodeIdMappings, isWarning: false);
			UnityEngine.Debug.LogFormat("Created new node {0}", num);
			if (!KeepCircuitLinks)
			{
				return;
			}
			foreach (CircuitLink item in list)
			{
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.MasterLocalConnectNodes(item.SourceNode.NodeId, item.OutputSlot, num, item.InputSlot);
			}
			foreach (CircuitLink item2 in list2)
			{
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.MasterLocalConnectNodes(num, item2.OutputSlot, item2.DestNode.NodeId, item2.InputSlot);
			}
		}
	}
