	[DisallowMultipleComponent]
	public class PersistenceView : Photon.MonoBehaviour
	{
		[Serializable]
		public struct ChildViewReference
		{
			public int childId;

			public PersistenceView persistenceView;
		}

		public static readonly Dictionary<Guid, PersistenceView> AllViews = new Dictionary<Guid, PersistenceView>();

		[SerializeField]
		private ChildViewReference[] childViews = new ChildViewReference[0];

		[SerializeField]
		private int highestChildIdAssigned = -1;

		private SynchronizedField<Guid> _synchronizedId;

		private List<IPersistable> persistableComponents;

		private List<IPreSerializationPersistable> preSerializationPersistableComponents;

		private List<IPreDeserializationPersistable> preDeserializationPersistableComponents;

		private List<IPostDeserializationPersistable> postDeserialiationPersistableComponents;

		private Guid previousSynchronizedId = Guid.Empty;

		public Guid Id
		{
			get
			{
				return _synchronizedId.Get();
			}
			set
			{
				if (!(Id != value))
				{
					return;
				}
				if (!PhotonNetwork.isMasterClient)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Only the master can set synchronized PersistenceView GUID on: {0}", base.gameObject);
					return;
				}
				Guid guid = _synchronizedId.Get();
				if (guid != Guid.Empty)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Cannot set synchronized PersistenceView GUID that has already been set on: {0}", base.gameObject);
				}
				else
				{
					_synchronizedId.Set(value);
				}
			}
		}

		public bool IsPersistable
		{
			get
			{
				if (Id == Guid.Empty)
				{
					UnityEngine.Debug.LogWarningFormat("Cannot persist object {0} with an empty PersistenceView ID", base.gameObject.name);
					return false;
				}
				if (IsChildView)
				{
					return false;
				}
				if (PersistenceBlocked)
				{
					return false;
				}
				ChildViewReference[] array = childViews;
				for (int i = 0; i < array.Length; i++)
				{
					ChildViewReference childViewReference = array[i];
					if (childViewReference.persistenceView != null && childViewReference.persistenceView.PersistenceBlocked)
					{
						return false;
					}
				}
				return true;
			}
		}

		private bool PersistenceBlocked
		{
			get
			{
				CollectPersistableComponents();
				foreach (IPersistable persistableComponent in persistableComponents)
				{
					if (persistableComponent.BlockObjectPersistance)
					{
						return true;
					}
				}
				return false;
			}
		}

		public PersistenceView ParentView { get; private set; }

		public bool IsChildView => ParentView != null;

		protected override void Awake()
		{
			base.Awake();
			if (base.transform.parent != null)
			{
				ParentView = base.transform.parent.GetComponentInParent<PersistenceView>();
			}
			PhotonNetwork.OnMasterClientSwitched.Add(OnMasterClientSwitched);
			_synchronizedId = new SynchronizedField<Guid>(this, "PID", Guid.Empty, SetterPermissionMode.MASTER, OnSynchronizedIdChange);
			OnSynchronizedIdChange();
		}

		private void Start()
		{
			MasterEnsureValidID();
		}

		protected override void OnDestroy()
		{
			PhotonNetwork.OnMasterClientSwitched.Remove(OnMasterClientSwitched);
			if (AllViews.TryGetValue(Id, out var value) && value == this)
			{
				AllViews.Remove(Id);
			}
			base.OnDestroy();
		}

		private void OnSynchronizedIdChange()
		{
			Guid id = Id;
			if (previousSynchronizedId != Guid.Empty)
			{
				UnityEngine.Debug.LogWarningFormat("Re-setting synchronized ID for PersistenceView from {0} to {1}. This shouldn't normally happen!", previousSynchronizedId, id);
				AllViews.Remove(previousSynchronizedId);
			}
			if (id != Guid.Empty)
			{
				AllViews[id] = this;
			}
			previousSynchronizedId = id;
		}

		private void OnMasterClientSwitched(PhotonPlayer player)
		{
			MasterEnsureValidID();
		}

		public void MasterEnsureValidID()
		{
			if (PhotonNetwork.isMasterClient && Id == Guid.Empty)
			{
				Id = Guid.NewGuid();
			}
		}

		public IPromise PreSerialize(StringBuilder outputLog, bool savedToDisk)
		{
			if (Id == Guid.Empty)
			{
				string text = $"Cannot pre-serialize PersistenceView {base.gameObject} with an empty ID";
				UnityEngine.Debug.LogError(text, this);
				return new ErroredPromise(text);
			}
			CollectPersistableComponents();
			return SingletonMonoBehaviour<Scheduler>.Instance.Run(this, RunPreserialize(outputLog, savedToDisk));
		}

		public IEnumerator<ISchedule> RunPreserialize(StringBuilder outputLog, bool savedToDisk)
		{
			foreach (IPreSerializationPersistable component in preSerializationPersistableComponents)
			{
				yield return SingletonMonoBehaviour<Scheduler>.Instance.Run(this, component.PreSerialize(outputLog, savedToDisk));
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference childView = array[i];
				if (childView.persistenceView != null)
				{
					IPromise childPromise = childView.persistenceView.PreSerialize(outputLog, savedToDisk);
					yield return Schedule.AfterCompleted(childPromise);
				}
			}
		}

		public PersistenceViewData Serialize(ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (Id == Guid.Empty)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Cannot serialize PersistenceView {0} with an empty ID", base.gameObject);
				return null;
			}
			CollectPersistableComponents();
			PersistenceViewData viewData = new PersistenceViewData();
			viewData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(Id);
			if (!IsChildView)
			{
				viewData.Transform = new TransformData();
				viewData.Transform.Position = base.transform.position.ValueOrZeroIfBogus().ToVector3Data();
				viewData.Transform.Rotation = base.transform.rotation.eulerAngles.ValueOrZeroIfBogus().ToVector3Data();
				viewData.Transform.Scale = base.transform.GetLocalUniformScale();
			}
			foreach (IPersistable persistableComponent in persistableComponents)
			{
				try
				{
					persistableComponent.SerializeTo(ref viewData, ref transientData, outputLog);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Error serializing components on PersistenceView {0} with ID {1}\n{2}\n{3}", base.gameObject, Id, ex.Message, ex.StackTrace);
				}
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference childViewReference = array[i];
				if (childViewReference.persistenceView != null)
				{
					PersistenceViewData data = childViewReference.persistenceView.Serialize(ref transientData, outputLog);
					viewData.ChildViews.Add(new ChildPersistenceViewData
					{
						ChildId = childViewReference.childId,
						Data = data
					});
				}
			}
			return viewData;
		}

		public void InitializeDeserialization(PersistenceViewData viewData, bool checkTransform = true)
		{
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.Id);
			if (guid == Guid.Empty)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Cannot deserialize PersistenceView {0} with a malformed or unconfigured ID", base.gameObject);
				return;
			}
			Id = guid;
			if (viewData.Transform == null || checkTransform)
			{
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference child = array[i];
				if (child.persistenceView != null)
				{
					PersistenceViewData childData = GetChildData(viewData, child);
					if (childData != null)
					{
						child.persistenceView.InitializeDeserialization(childData);
					}
				}
			}
		}

		public void PreDeserialize(RoomPersistenceVersion version, PersistenceViewData viewData, Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			CollectPersistableComponents();
			foreach (IPreDeserializationPersistable preDeserializationPersistableComponent in preDeserializationPersistableComponents)
			{
				try
				{
					preDeserializationPersistableComponent.PreDeserialize(version, viewData, persistenceViewIdMappings);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Error pre-deserializing components on PersistenceView {0} with ID {1}\n{2}\n{3}", base.gameObject, Id, ex.Message, ex.StackTrace);
				}
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference child = array[i];
				if (child.persistenceView != null)
				{
					PersistenceViewData childData = GetChildData(viewData, child);
					if (childData != null)
					{
						child.persistenceView.PreDeserialize(version, childData, persistenceViewIdMappings);
					}
				}
			}
		}

		public void Deserialize(PersistableDeserializeParams deserializeParams)
		{
			CollectPersistableComponents();
			foreach (IPersistable persistableComponent in persistableComponents)
			{
				try
				{
					persistableComponent.DeserializeFrom(deserializeParams);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Error deserializing components on PersistenceView {0} with ID {1}\n{2}\n{3}", base.gameObject, Id, ex.Message, ex.StackTrace);
				}
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference child = array[i];
				if (child.persistenceView != null)
				{
					PersistenceViewData childData = GetChildData(deserializeParams.viewData, child);
					if (childData != null)
					{
						PersistableDeserializeParams deserializeParams2 = new PersistableDeserializeParams
						{
							version = deserializeParams.version,
							viewData = childData,
							nodeIdMapping = deserializeParams.nodeIdMapping,
							persistenceViewIdMappings = deserializeParams.persistenceViewIdMappings,
							assignNewIds = deserializeParams.assignNewIds,
							isRuntimeCreated = deserializeParams.isRuntimeCreated
						};
						child.persistenceView.Deserialize(deserializeParams2);
					}
				}
			}
		}

		public void PostDeserialize(Dictionary<Guid, Guid> persistenceViewIdMappings)
		{
			CollectPersistableComponents();
			foreach (IPostDeserializationPersistable postDeserialiationPersistableComponent in postDeserialiationPersistableComponents)
			{
				try
				{
					postDeserialiationPersistableComponent.PostDeserialize(persistenceViewIdMappings);
				}
				catch (Exception ex)
				{
					UnityEngine.Debug.LogErrorFormat(this, "Error post-deserializing components on PersistenceView {0} with ID {1}\n{2}\n{3}", base.gameObject, Id, ex.Message, ex.StackTrace);
				}
			}
			ChildViewReference[] array = childViews;
			for (int i = 0; i < array.Length; i++)
			{
				ChildViewReference childViewReference = array[i];
				if (childViewReference.persistenceView != null)
				{
					childViewReference.persistenceView.PostDeserialize(persistenceViewIdMappings);
				}
			}
		}

		private void CollectPersistableComponents()
		{
			if (persistableComponents != null)
			{
				return;
			}
			persistableComponents = new List<IPersistable>();
			preSerializationPersistableComponents = new List<IPreSerializationPersistable>();
			preDeserializationPersistableComponents = new List<IPreDeserializationPersistable>();
			postDeserialiationPersistableComponents = new List<IPostDeserializationPersistable>();
			UnityEngine.MonoBehaviour[] componentsInChildren = GetComponentsInChildren<UnityEngine.MonoBehaviour>(includeInactive: true);
			UnityEngine.MonoBehaviour[] array = componentsInChildren;
			foreach (UnityEngine.MonoBehaviour monoBehaviour in array)
			{
				if (monoBehaviour == null)
				{
					UnityEngine.Debug.LogWarningFormat("Null component found while collecting persistable components on view {0}. Do you have missing script references?", this);
				}
				else
				{
					if (!(monoBehaviour is IPersistable) && !(monoBehaviour is IPreSerializationPersistable) && !(monoBehaviour is IPreDeserializationPersistable) && !(monoBehaviour is IPostDeserializationPersistable))
					{
						continue;
					}
					PersistenceView componentInParent = monoBehaviour.GetComponentInParent<PersistenceView>(includeDisabled: true);
					if (componentInParent == this)
					{
						if (monoBehaviour is IPersistable)
						{
							persistableComponents.Add((IPersistable)monoBehaviour);
						}
						if (monoBehaviour is IPreSerializationPersistable)
						{
							preSerializationPersistableComponents.Add((IPreSerializationPersistable)monoBehaviour);
						}
						if (monoBehaviour is IPreDeserializationPersistable)
						{
							preDeserializationPersistableComponents.Add((IPreDeserializationPersistable)monoBehaviour);
						}
						if (monoBehaviour is IPostDeserializationPersistable)
						{
							postDeserialiationPersistableComponents.Add((IPostDeserializationPersistable)monoBehaviour);
						}
					}
					else if (componentInParent == null)
					{
						UnityEngine.Debug.LogErrorFormat("Persistable component {0} has no PersistenceViews in its parent hierarchy. This should be impossible", monoBehaviour);
					}
				}
			}
		}

		private PersistenceViewData GetChildData(PersistenceViewData parentData, ChildViewReference child)
		{
			PersistenceViewData result = null;
			if (child.persistenceView != null)
			{
				ChildPersistenceViewData childPersistenceViewData = parentData.ChildViews.FirstOrDefault((ChildPersistenceViewData d) => d.ChildId == child.childId);
				if (childPersistenceViewData != null)
				{
					result = childPersistenceViewData.Data;
				}
				else
				{
					UnityEngine.Debug.LogWarningFormat("Data blob for PersistenceView {0} contains no corresponding data for child view {1}", this, child.persistenceView);
				}
			}
			return result;
		}

		public static void SetNewIdsForData(PersistenceViewData data, Dictionary<Guid, Guid> oldIdToNewIdMap)
		{
			if (data == null)
			{
				return;
			}
			Guid key = RecRoom.Protobuf.ByteStringExtensions.ToGuid(data.Id);
			Guid guid = Guid.NewGuid();
			data.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(guid);
			oldIdToNewIdMap.Add(key, guid);
			foreach (ChildPersistenceViewData childView in data.ChildViews)
			{
				SetNewIdsForData(childView.Data, oldIdToNewIdMap);
			}
		}
	}
