		private class ToolReference
		{
			private readonly Tool tool;

			private readonly Guid persistenceId;

			public ToolReference(Tool tool)
			{
				this.tool = tool;
				PersistenceView persistenceView = ((!(tool != null)) ? null : tool.GetComponent<PersistenceView>());
				persistenceId = ((!(persistenceView != null)) ? Guid.Empty : persistenceView.Id);
			}

			public static implicit operator ToolReference(Tool tool)
			{
				return new ToolReference(tool);
			}

			public static implicit operator Tool(ToolReference toolRef)
			{
				if (toolRef != null)
				{
					if (toolRef.tool != null)
					{
						return toolRef.tool;
					}
					if (toolRef.persistenceId != Guid.Empty && PersistenceView.AllViews.TryGetValue(toolRef.persistenceId, out var value))
					{
						return value.GetComponent<Tool>();
					}
				}
				return null;
			}
		}

