		public IEnumerator WaitForInitialLoad(PersistenceCallback callback)
		{
			while (!roomStateMachine.IsInitialized)
			{
				yield return null;
			}
			while (IsLoading)
			{
				yield return null;
			}
			if (roomStateMachine.CurrentStateId == 1)
			{
				callback(success: false, ErrorMessage);
			}
			else
			{
				callback(success: true, null);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
			Player.LocalPlayerSpawnEvent += new Action(UpdateScheduledAutosave);
			SingletonMonoBehaviour<SettingsManager>.Instance.AutosaveIntervalChanged += ChangeAutosaveInterval;
			cachedAutosaveInterval = SingletonMonoBehaviour<SettingsManager>.Instance.AutosaveInterval;
			_errorMessage = new SynchronizedField<string>(this, "ERROR", string.Empty, SetterPermissionMode.MASTER);
			_roomDataBlobName = new SynchronizedField<string>(this, "RDBN", string.Empty, SetterPermissionMode.MASTER, OnRoomDataBlobNameChanged);
			OnRoomDataBlobNameChanged();
			roomStateTimer = new SynchronizedTimer(this, "TIMER", SetterPermissionMode.MASTER);
			roomStateMachine = new SynchronizedStateMachine("RSM", SetterPermissionMode.MASTER);
			roomStateMachine.AddState(0, null, null, OnUpdateInitialRoomLoadingState);
			roomStateMachine.AddState(1, null, null, null);
			roomStateMachine.AddState(2, null, null, null);
			roomStateMachine.AddState(3, OnEnterSavingState, null, OnUpdateSavingRoomState);
			roomStateMachine.AddState(4, OnEnterPostSaveReloadingSuperState, OnExitPostSaveReloadingSuperState, null);
			roomStateMachine.AddState(4, 0, OnEnterPostSaveReloadingFadeOutSubState, null, OnUpdatePostSaveReloadingFadeOutSubState);
			roomStateMachine.AddState(4, 1, null, null, OnUpdatePostSaveReloadingReloadRoomSubState);
			roomStateMachine.AddState(5, OnEnterSavingRoomSuccessState, null, OnUpdateSavingRoomSuccessState);
			roomStateMachine.AddState(6, OnEnterSavingRoomFailedState, null, OnUpdateSavingRoomFailedState);
			roomStateMachine.AddState(7, OnEnterReloadingSuperState, OnExitReloadingSuperState, null);
			roomStateMachine.AddState(7, 0, OnEnterReloadingFadeOutSubState, null, OnUpdateReloadingFadeOutSubState);
			roomStateMachine.AddState(7, 1, null, null, OnUpdateReloadingReloadRoomSubState);
			roomStateMachine.AddState(8, OnEnterReloadingRoomSuccessState, null, OnUpdateReloadingRoomSuccessState);
			roomStateMachine.AddState(9, OnEnterReloadingRoomFailedState, null, OnUpdateReloadingRoomFailedState);
		}

		private void Start()
		{
			if (PhotonNetwork.isMasterClient)
			{
				string dataBlobName = GameSessions.LocalGameSession.DataBlobName;
				if (!string.IsNullOrEmpty(dataBlobName))
				{
					RoomDataBlobName = dataBlobName;
				}
			}
			roomStateMachine.Start(this, 0);
		}

		private void Update()
		{
			roomStateTimer.UpdateCallbacks();
			roomStateMachine.Update();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
			Player.LocalPlayerSpawnEvent -= new Action(UpdateScheduledAutosave);
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.AutosaveIntervalChanged -= ChangeAutosaveInterval;
			}
			StopPhotonTrafficMonitoring();
			SetPhotonNetworkPaused(paused: false);
		}

		private void OnRoomDataBlobNameChanged()
		{
			UpdateScheduledAutosave();
			GetRoomDataBlobPromise = ((!string.IsNullOrEmpty(RoomDataBlobName)) ? RecNet.Rooms.GetRoomData(RoomDataBlobName) : new CompletedPromise<byte[]>(null));
		}

		private new void StopAllCoroutines()
		{
			base.StopAllCoroutines();
			saveLoadPromise = null;
			SetPhotonNetworkPaused(paused: false);
			StopPhotonTrafficMonitoring();
		}

		private void TryAutosaveRoom()
		{
			if (!CanRequestRoomDataSave() || !Player.LocalPlayerExists || !GameSessions.LocalGameSession.IsSandbox)
			{
				return;
			}
			UnityEngine.Debug.Log($"Backup save for {AutosaveCurrentRoomPath} started at {UnityEngine.Time.time}");
			StartCoroutine(SerializeSandboxRoomDataBlobCoroutine(verboseLogging: false, savedToDisk: true, delegate(bool success, PersistedRoomData roomData, List<string> imageNames, List<string> dataBlobNames, string error)
			{
				if (success)
				{
					CreateLatestAutosave(roomData);
					RemoveOldestAutosavesOverMaximum();
				}
			}));
		}

		private void CreateLatestAutosave(PersistedRoomData roomData)
		{
			try
			{
				Directory.CreateDirectory(AutosaveDirectoryPath);
				using (FileStream fileStream = File.Open(AutosaveCurrentRoomPath, FileMode.Create))
				{
					byte[] array = roomData.ToByteArray();
					fileStream.Write(array, 0, array.Length);
				}
				UnityEngine.Debug.Log($"Backup save for {AutosaveCurrentRoomPath} ended at {UnityEngine.Time.time}");
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Error creating local autosave file for {AutosaveCurrentRoomPath}: {arg}");
			}
		}

		private void RemoveOldestAutosavesOverMaximum()
		{
			try
			{
				DirectoryInfo directoryInfo = Directory.CreateDirectory(AutosaveDirectoryPath);
				FileSystemInfo[] fileSystemInfos = directoryInfo.GetFileSystemInfos();
				if (fileSystemInfos.Length < 5)
				{
					return;
				}
				IEnumerable<FileSystemInfo> enumerable = fileSystemInfos.OrderByDescending((FileSystemInfo f) => f.LastWriteTimeUtc).Skip(5);
				foreach (FileSystemInfo item in enumerable)
				{
					File.Delete(item.FullName);
				}
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Error removing older autosave files for {AutosaveCurrentRoomPath}: {arg}");
			}
		}

		private bool AutosaveFileExists()
		{
			bool result = false;
			try
			{
				result = File.Exists(AutosaveCurrentRoomPath);
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Error checking for existence of {AutosaveCurrentRoomPath}: {arg}");
			}
			return result;
		}

		public void ChangeAutosaveInterval(float interval)
		{
			if (!Mathf.Approximately(interval, cachedAutosaveInterval))
			{
				cachedAutosaveInterval = interval;
				UpdateScheduledAutosave();
			}
		}

		public DateTime? GetLastAutosaveTime()
		{
			DateTime? result = null;
			if (AutosaveFileExists())
			{
				try
				{
					result = File.GetLastWriteTimeUtc(AutosaveCurrentRoomPath);
				}
				catch (Exception arg)
				{
					UnityEngine.Debug.LogError($"Error getting last write time of {AutosaveCurrentRoomPath}: {arg}");
				}
			}
			return result;
		}

		public void TryReloadRoomAutosave()
		{
			if (!AutosaveFileExists())
			{
				UnityEngine.Debug.LogError($"ERROR: Tried to load Autosave in room where no Autosave data exists: {AutosaveCurrentRoomPath}");
				return;
			}
			try
			{
				byte[] data = File.ReadAllBytes(AutosaveCurrentRoomPath);
				RecNet.Rooms.UploadLocalRoomSceneData(data, new List<string>(), new List<string>()).Then((Action<RoomScene>)delegate
				{
					RequestReloadRoomData();
				}).Error(delegate(string error)
				{
					UnityEngine.Debug.LogError($"Error uploading room data: {error}");
				});
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Error trying to restore local autosave for {AutosaveCurrentRoomPath}: {arg}");
			}
		}

		private void UpdateScheduledAutosave()
		{
			if (autosavePromise != null)
			{
				autosavePromise.Dispose();
			}
			if (cachedAutosaveInterval > 0f && RecNet.Rooms.LocalRoomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner)
			{
				autosavePromise = this.InvokeRepeated(cachedAutosaveInterval, TryAutosaveRoom);
			}
		}

		public void RequestSaveRoomData()
		{
			if (CanRequestRoomDataSave())
			{
				base.photonView.RpcMaster(RpcMasterRequestSaveRoomData);
			}
		}

		[PunRPC]
		private void RpcMasterRequestSaveRoomData()
		{
			if (PhotonNetwork.isMasterClient && CanRequestRoomDataSave())
			{
				roomStateMachine.EnterState(3);
			}
		}

		private bool CanRequestRoomDataSave()
		{
			return roomStateMachine != null && roomStateMachine.CurrentStateId == 2;
		}

		public void RequestReloadRoomData()
		{
			if (CanRequestRoomDataReload())
			{
				base.photonView.RpcMaster(RpcMasterRequestReloadRoomData);
			}
		}

		[PunRPC]
		private void RpcMasterRequestReloadRoomData()
		{
			if (PhotonNetwork.isMasterClient && CanRequestRoomDataReload())
			{
				roomStateMachine.EnterState(7, 0);
			}
		}

		private bool CanRequestRoomDataReload()
		{
			return roomStateMachine != null && roomStateMachine.CurrentStateId == 2;
		}

		public IPromise<SaveLoadInfo> TeachableMomentLoadRoomData(TextAsset savedRoomData)
		{
			return LoadRoomFromBytes(savedRoomData.bytes);
		}

		internal IPromise<SaveLoadInfo> LoadRoomFromBytes(byte[] roomDataBytes)
		{
			StopAllCoroutines();
			RoomDataBlobName = string.Empty;
			PersistedRoomData roomDataBlob = PersistedRoomData.Parser.ParseFrom(roomDataBytes);
			saveLoadPromise = new Promise<SaveLoadInfo>();
			StartCoroutine(DeserializeRoomDataBlobCoroutine(roomDataBlob, verboseLogging: false, (Promise<SaveLoadInfo>)saveLoadPromise));
			return saveLoadPromise;
		}

		public void PersistTransientImage(string transientImageName)
		{
			TransientImageNamesToPersist.Add(transientImageName);
		}

		public void PersistTransientDataBlob(string transientBlobName)
		{
			TransientDataBlobNamesToPersist.Add(transientBlobName);
		}

		private void OnUpdateInitialRoomLoadingState()
		{
			if (!PhotonNetwork.isMasterClient || (saveLoadPromise != null && !saveLoadPromise.IsCompleted))
			{
				return;
			}
			bool verboseLogging = false;
			saveLoadPromise = MasterLoadInitialRoomAsync(verboseLogging);
			saveLoadPromise.Then(delegate(SaveLoadInfo info)
			{
				if (info.version == RoomPersistenceVersion.DEFAULT_ROOM)
				{
					HandleDefaultRoomLoad();
				}
				else if (info.version < RoomPersistenceVersion.EVERYTHING_A_ROOM)
				{
					HandleRoomDataOutOfDate();
				}
				roomStateMachine.EnterState(2);
			}).Error(delegate(string error)
			{
				ErrorMessage = error;
				roomStateMachine.EnterState(1);
			});
		}

		private void OnEnterSavingState(ushort previousStateId, ushort previousSubStateId)
		{
			if (this.RoomSaveStartEvent != null)
			{
				this.RoomSaveStartEvent();
			}
		}

		private void OnUpdateSavingRoomState()
		{
			if (PhotonNetwork.isMasterClient && (saveLoadPromise == null || saveLoadPromise.IsCompleted))
			{
				bool verboseLogging = false;
				saveLoadPromise = MasterSaveRoomAsync(verboseLogging).Then((Action)delegate
				{
					roomStateMachine.EnterState(4, 0);
				}).Error(delegate(string error)
				{
					ErrorMessage = error;
					roomStateMachine.EnterState(6);
				});
			}
		}

