		private void HandleDefaultRoomLoad()
		{
			GameSession localGameSession = GameSessions.LocalGameSession;
			if (localGameSession.IsSandbox)
			{
				RoomSceneLocations location = localGameSession.Location;
				AGRoomRuntimeConfig.Location roomSceneLocationConfig = AGRoomSettings.GetRoomSceneLocationConfig(location);
				if (roomSceneLocationConfig != null && roomSceneLocationConfig.EmptyOnSandboxClone)
				{
					UnityEngine.Debug.LogFormat("Emptying non-sandbox location {0} of all spawned objects on default room load", location);
					NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestDestroyAll();
				}
			}
		}

		private void HandleRoomDataOutOfDate()
		{
			StartCoroutine(RoomOutOfDateDialogCoroutine());
		}

		private IEnumerator RoomOutOfDateDialogCoroutine()
		{
			while (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerUI.WatchMenu == null || RecNet.Rooms.LocalRoomDetails == null)
			{
				yield return null;
			}
			if (RecNet.Rooms.LocalRoomDetails.LocalPlayerRole < RecNet.RoomRole.CoOwner)
			{
				yield break;
			}
			_ = Player.LocalPlayer.PlayerUI;
			WatchUI watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			watchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Please re-save ^room", "This ^room's save data is out-of-date. Please save the room again to update it to the current version.", "Save", "Later").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					base.photonView.RpcMaster(RpcMasterRequestSaveRoomData);
				}
			});
		}

		private IPromise<SaveLoadInfo> MasterReloadRoomAsync(bool verboseLogging)
		{
			StopAllCoroutines();
			Promise<SaveLoadInfo> promise = new Promise<SaveLoadInfo>();
