		private IEnumerator MasterReloadRoomCoroutine(bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			ResetPhotonTrafficMonitoring();
			while (CreationContext.AllContexts.Any((CreationContext c) => c != null && !c.WaitingForPersistence))
			{
				yield return null;
			}
			yield return LoadRoomInternalCoroutine(verboseLogging, promise);
			promise.Then((Action)delegate
			{
				AnalyticsHelper.RoomReloaded(GameSessions.LocalGameSession.RoomId, GameSessions.LocalGameSession.RoomSceneId, success: true, null, GetPhotonTrafficMonitoringStats());
			}).Error(delegate(string error)
			{
				AnalyticsHelper.RoomReloaded(GameSessions.LocalGameSession.RoomId, GameSessions.LocalGameSession.RoomSceneId, success: false, error, GetPhotonTrafficMonitoringStats());
			});
		}

		private IPromise<SaveLoadInfo> MasterSaveRoomAsync(bool verboseLogging)
		{
			StopAllCoroutines();
			Promise<SaveLoadInfo> promise = new Promise<SaveLoadInfo>();
			StartCoroutine(MasterSaveRoomCoroutine(verboseLogging, promise));
			return promise;
		}

		private IEnumerator MasterSaveRoomCoroutine(bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			PersistedRoomData serializedRoomDataBlob = null;
			List<string> persistedImageNames = null;
			List<string> persistedDataBlobNames = null;
			bool serializedRoomDataSuccess = false;
			string serializedRoomDataError = null;
			while (CreationContext.AllContexts.Any((CreationContext c) => c != null && !c.WaitingForPersistence))
			{
				yield return null;
			}
			yield return MasterSerializeRoomDataBlobCoroutine(verboseLogging, delegate(bool success, PersistedRoomData roomData, List<string> imageNames, List<string> dataBlobNames, string error)
			{
				serializedRoomDataSuccess = success;
				serializedRoomDataBlob = roomData;
				persistedImageNames = imageNames;
				persistedDataBlobNames = dataBlobNames;
				serializedRoomDataError = error;
			});
			if (!serializedRoomDataSuccess || serializedRoomDataBlob == null)
			{
				promise.Error(serializedRoomDataError);
			}
			else
			{
				yield return MasterUploadRoomDataBlobCoroutine(serializedRoomDataBlob, persistedImageNames, persistedDataBlobNames, verboseLogging, promise);
			}
		}

		private IEnumerator MasterSerializeRoomDataBlobCoroutine(bool verboseLogging, SerializeRoomDataCallback callback)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				callback(success: false, null, null, null, "Only the Master Client may save room data.");
			}
			else if (GameSessions.LocalGameSession.IsSandbox)
			{
				yield return SerializeSandboxRoomDataBlobCoroutine(verboseLogging, savedToDisk: false, callback);
			}
			else
			{
				SerializeCustomActivityRoomDataBlobCoroutine(verboseLogging, callback);
			}
		}

		private IEnumerator SerializeSandboxRoomDataBlobCoroutine(bool verboseLogging, bool savedToDisk, SerializeRoomDataCallback callback)
		{
			if (!savedToDisk)
			{
				TransientImageNamesToPersist.Clear();
				TransientDataBlobNamesToPersist.Clear();
			}
			Dictionary<Guid, PersistenceView>.ValueCollection activePersistenceViews = PersistenceView.AllViews.Values;
			StringBuilder outputBuilder = new StringBuilder();
			int pendingPreserializes = 0;
			foreach (PersistenceView item in activePersistenceViews)
			{
				if (item.IsPersistable)
				{
					pendingPreserializes++;
					item.PreSerialize(outputBuilder, savedToDisk).Finally(delegate
					{
						pendingPreserializes--;
					});
				}
			}
			float time = UnityEngine.Time.realtimeSinceStartup;
			while (pendingPreserializes > 0)
			{
				yield return null;
			}
			if (verboseLogging)
			{
				UnityEngine.Debug.LogFormat("Preserialization complete in {0} seconds", UnityEngine.Time.realtimeSinceStartup - time);
			}
			PersistedRoomData roomDataBlob = InitializeRoomDataBlob();
			int[] circuitIdsToIgnore = (from n in CircuitNodeDisplay.AllDisplays
				where !n.CanPersistNode
				select n.NodeId).ToArray();
			if (circuitIdsToIgnore.Length > 0)
			{
				UnityEngine.Debug.Log($"Ignoring {circuitIdsToIgnore.Length} inactive circuit node IDs during persistence.");
				if (verboseLogging)
				{
					int[] array = circuitIdsToIgnore;
					foreach (int id in array)
					{
						CircuitNodeDisplay arg = CircuitNodeDisplay.AllDisplays.FirstOrDefault((CircuitNodeDisplay n) => n.NodeId == id);
						UnityEngine.Debug.Log($"Ignore circuit node display {arg} ({id})");
					}
				}
			}
			CircuitNodeGraphCollectionData nodeGraphData = CircuitNodeGraph.PersistAll(circuitIdsToIgnore);
			roomDataBlob.CircuitData = nodeGraphData.ToByteString();
			if (verboseLogging)
			{
				IEnumerable<RecRoom.Circuits.Protobuf.CircuitNodeData> enumerable = from n in nodeGraphData.Graphs.SelectMany((CircuitNodeGraphData g) => g.CircuitNodes)
					where circuitIdsToIgnore.Contains(n.NodeId)
					select n;
				foreach (RecRoom.Circuits.Protobuf.CircuitNodeData item2 in enumerable)
				{
					UnityEngine.Debug.LogError($"Attempted to not persist node {item2.NodeId}, but it was persisted anyway.");
				}
			}
			HashSet<int> serializedCircuitNodeIds = new HashSet<int>(nodeGraphData.Graphs.SelectMany((CircuitNodeGraphData g) => g.CircuitNodes.Select((RecRoom.Circuits.Protobuf.CircuitNodeData n) => n.NodeId)));
			roomDataBlob.ConnectableGraphData = NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.MasterSerializeConnectableGraph(usePersistenceId: true);
			activePersistenceViews = PersistenceView.AllViews.Values;
			foreach (PersistenceView item3 in activePersistenceViews)
			{
				if (!(item3 != null) || !item3.IsPersistable)
				{
					continue;
				}
				if (verboseLogging)
				{
					UnityEngine.Debug.LogFormat(item3, "Serializing PersistanceView {0}", item3.gameObject);
				}
				TransientDataToPersist transientData = default(TransientDataToPersist);
				PersistenceViewData persistenceViewData = item3.Serialize(ref transientData, outputBuilder);
				if (persistenceViewData == null)
				{
					continue;
				}
				if (persistenceViewData.SpawnableToolData == null)
				{
					UnityEngine.Debug.LogErrorFormat(item3, "Error serializing PersistenceView {0} that contains no SpawnableToolData", item3.gameObject);
					continue;
				}
				roomDataBlob.PersistenceViews.Add(persistenceViewData);
				if (persistenceViewData.CircuitNodeData == null || persistenceViewData.CircuitNodeData.CircuitNodeId == 0 || serializedCircuitNodeIds.Contains(persistenceViewData.CircuitNodeData.CircuitNodeId))
				{
					continue;
				}
				throw new InvalidOperationException("Attempting to serialize CircuitNode PersistenceView when node is missing from serialized circuit data!");
			}
			OutputDebugStatistics(roomDataBlob, outputBuilder);
			roomDataBlob.OutputLog = outputBuilder.ToString();
			List<string> imageListCopy = new List<string>(TransientImageNamesToPersist);
			List<string> dataBlobListCopy = new List<string>(TransientDataBlobNamesToPersist);
			callback(success: true, roomDataBlob, imageListCopy, dataBlobListCopy, null);
		}

		private void SerializeCustomActivityRoomDataBlobCoroutine(bool verboseLogging, SerializeRoomDataCallback callback)
		{
			PersistedRoomData persistedRoomData = InitializeRoomDataBlob();
			callback(success: true, persistedRoomData, null, null, null);
		}

		private PersistedRoomData InitializeRoomDataBlob()
		{
			PersistedRoomData roomData = new PersistedRoomData();
			roomData.Version = 14;
			roomData.ActivityId = AGRoomSettings.GetRoomSceneLocationReplicationId(GameSessions.LocalGameSession.Location);
			roomData.LastSaveTime = DateTime.UtcNow.ToTimestamp();
			SerializeRoomSettings(ref roomData);
			return roomData;
		}

		private void OutputDebugStatistics(PersistedRoomData data, StringBuilder outputBuilder)
		{
			List<PersistenceView> list = this.FindAllObjectsOfType<PersistenceView>();
			Dictionary<Guid, PersistenceView>.ValueCollection values = PersistenceView.AllViews.Values;
			outputBuilder.AppendLine($"Serialized {data.PersistenceViews.Count} persistence views. Found {list.Count} active PersistenceViews in the scene and {values.Count} in the view array");
			IEnumerable<PersistenceViewData> source = data.PersistenceViews.Where((PersistenceViewData v) => v.ShapeContainerData != null);
			int num = source.Count();
			IEnumerable<PersistenceView> source2 = values.Where((PersistenceView v) => v.GetComponent<ShapeContainer>() != null);
			int num2 = source2.Count();
			outputBuilder.AppendLine($"Serializing {num} shape container views. Found {num2} in the view array and {ShapeContainer.AllShapeContainers.Count} in the shape container array");
		}

		private IEnumerator MasterUploadRoomDataBlobCoroutine(PersistedRoomData roomDataBlob, List<string> imageList, List<string> dataBlobList, bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			if (roomDataBlob == null)
			{
				promise.Error("No persisted Room Data created.");
				yield break;
			}
			byte[] data = roomDataBlob.ToByteArray();
			if (data == null || data.Length == 0)
			{
				promise.Error("No room data to save.");
				yield break;
			}
			float timer = 0f;
			while (RecNet.Rooms.LocalRoomDetails == null)
			{
				if (timer >= 10f)
				{
					promise.Error("Timed out waiting for current session room id to become valid.");
					yield break;
				}
				timer += UnityEngine.Time.deltaTime;
				yield return null;
			}
			yield return RecNet.Rooms.UploadLocalRoomSceneData(data, imageList, dataBlobList).Then((Action<RoomScene>)delegate
			{
				promise.Complete(new SaveLoadInfo
				{
					version = (RoomPersistenceVersion)roomDataBlob.Version
				});
			}).Error(delegate(string error)
			{
				promise.Error(error);
			});
		}

		private IEnumerator LoadRoomInternalCoroutine(bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			PersistedRoomData roomDataBlob = null;
			yield return DownloadRoomDataBlobAsync(verboseLogging).Error(delegate(string error)
			{
				promise.Error(error);
			}).Then(delegate(PersistedRoomData data)
			{
				roomDataBlob = data;
				if (data == null)
				{
					promise.Complete(SaveLoadInfo.Default);
				}
			});
			if (!promise.IsCompleted)
			{
				yield return DeserializeRoomDataBlobCoroutine(roomDataBlob, verboseLogging, promise);
			}
		}

		private IPromise<PersistedRoomData> DownloadRoomDataBlobAsync(bool verboseLogging)
		{
			Promise<PersistedRoomData> promise = new Promise<PersistedRoomData>();
			StartCoroutine(DownloadRoomDataBlobCoroutine(verboseLogging, promise));
			return promise;
		}

		private IEnumerator DownloadRoomDataBlobCoroutine(bool verboseLogging, Promise<PersistedRoomData> promise)
		{
			float timer = 0f;
			while (RecNet.Rooms.LocalRoomDetails == null)
			{
				if (timer >= 10f)
				{
					promise.Error("Timed out waiting for current session room id to become valid.");
					yield break;
				}
				timer += UnityEngine.Time.deltaTime;
				yield return null;
			}
			RoomDataBlobName = RecNet.Rooms.LocalRoomScene.DataBlobName ?? string.Empty;
			yield return GetRoomDataBlobPromise.Error(delegate(string error)
			{
				promise.Error(error);
			}).Then(delegate(byte[] rawData)
			{
				if (rawData == null)
				{
					promise.Complete(null);
					return;
				}
				try
				{
					PersistedRoomData payload = PersistedRoomData.Parser.ParseFrom(rawData);
					promise.Complete(payload);
				}
				catch (InvalidProtocolBufferException)
				{
					promise.Error("Error attempting to parse room data stream.");
				}
			});
		}

		private IEnumerator DeserializeRoomDataBlobCoroutine(PersistedRoomData roomDataBlob, bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			if (roomDataBlob == null)
			{
				promise.Error("Room data is null.");
				yield break;
			}
			while (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsInitializing)
			{
				yield return null;
			}
			SetPhotonNetworkPaused(paused: true);
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.PauseNetworking();
			StartPhotonTrafficMonitoring();
			SaveLoadInfo? loadResults = null;
			string loadError = null;
			Promise<SaveLoadInfo> deserializePromise = new Promise<SaveLoadInfo>();
			deserializePromise.Then(delegate(SaveLoadInfo r)
			{
				loadResults = r;
			}).Error(delegate(string e)
			{
				loadError = e;
			});
			if (GameSessions.LocalGameSession.IsSandbox)
			{
				yield return DeserializeSandboxRoomDataBlobCoroutine(roomDataBlob, verboseLogging, deserializePromise);
			}
			else
			{
				DeserializeCustomActivityRoomDataBlob(roomDataBlob, verboseLogging, deserializePromise);
			}
			if (loadResults.HasValue)
			{
				SynchronizedField.SendPendingRoomUpdates();
				float resendInterval = 20f * AGPhotonHelper.CalculateRoundTripTimeMs(useExponentialBackoff: false) / 1000f;
				float maxWaitEndTime = UnityEngine.Time.realtimeSinceStartup + 15f;
				float nextResendTime = -1f;
				while (AGPhotonHelper.PendingSentReliableCommands > 0)
				{
					if (UnityEngine.Time.realtimeSinceStartup > nextResendTime)
					{
						if (UnityEngine.Time.realtimeSinceStartup > maxWaitEndTime)
						{
							UnityEngine.Debug.LogError($"Ran out of time awaiting network acknowledgement while deserializing room ${RecNet.Rooms.LocalRoomScene.Name} (${RecNet.Rooms.LocalRoomScene.RoomId}).");
							break;
						}
						PhotonNetwork.ForceSendOutgoingCommands();
						nextResendTime = UnityEngine.Time.realtimeSinceStartup + resendInterval;
					}
					yield return 0;
				}
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.UnpauseNetworking();
				promise.Complete(loadResults.Value);
			}
			else
			{
				NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.UnpauseNetworking();
				promise.Error(loadError);
			}
			StopPhotonTrafficMonitoring();
			SetPhotonNetworkPaused(paused: false);
		}

		private IEnumerator DeserializeSandboxRoomDataBlobCoroutine(PersistedRoomData roomDataBlob, bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			if (this.MasterRoomDeserializationStartEvent != null)
			{
				this.MasterRoomDeserializationStartEvent();
			}
			try
			{
				DestroyActivePersistenceViews(verboseLogging);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				promise.Error("Error cleaning room");
				yield break;
			}
			yield return null;
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.UnpauseNetworking();
			NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.PauseNetworking();
			RoomPersistenceVersion version = (RoomPersistenceVersion)roomDataBlob.Version;
			if (verboseLogging)
			{
				UnityEngine.Debug.LogFormat("Deserializing room data version {0} with {1} persisted views.", version, roomDataBlob.PersistenceViews.Count);
			}
			try
			{
				DeserializeRoomSettings(roomDataBlob);
			}
			catch (Exception exception2)
			{
				UnityEngine.Debug.LogException(exception2);
				promise.Error("Error loading room settings");
				yield break;
			}
			Dictionary<int, int> nodeIdMappings = null;
			try
			{
				if (roomDataBlob.CircuitData != null && !roomDataBlob.CircuitData.IsEmpty)
				{
					CircuitNodeGraphCollectionData data = CircuitNodeGraphCollectionData.Parser.ParseFrom(roomDataBlob.CircuitData);
					NetworkedSingletonMonoBehaviour<CircuitManager>.Instance.Reinitialize(data, out nodeIdMappings);
				}
			}
			catch (Exception exception3)
			{
				UnityEngine.Debug.LogException(exception3);
				promise.Error("Error loading room. Circuit data is corrupt!");
				yield break;
			}
			List<PhotonNetwork.InstantiateRequestEx> instantiationRequests = new List<PhotonNetwork.InstantiateRequestEx>(roomDataBlob.PersistenceViews.Count);
			List<PersistenceViewData> requestData = new List<PersistenceViewData>(roomDataBlob.PersistenceViews.Count);
			try
			{
				for (int i = 0; i < roomDataBlob.PersistenceViews.Count; i++)
				{
					PersistenceViewData persistenceViewData = roomDataBlob.PersistenceViews[i];
					Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceViewData.Id);
					if (guid == Guid.Empty)
					{
						UnityEngine.Debug.LogErrorFormat("Data found with malformed or empty ID while deserializing room.");
						continue;
					}
					if (PersistenceView.AllViews.ContainsKey(guid))
					{
						UnityEngine.Debug.LogWarningFormat("Data found with GUID {0} matching an object already in the scene: {1}\nLikely this object was not in a valid state when trying to destroy existing views. Skipping deserialization...", guid, PersistenceView.AllViews[guid]);
						continue;
					}
					try
					{
						CircuitNodePersistence.CheckForRequiredCircuitNodeId(persistenceViewData, nodeIdMappings, version);
					}
					catch (Exception exception4)
					{
						UnityEngine.Debug.LogException(exception4);
						promise.Error("Error loading room. Circuit Item was corrupt!");
						yield break;
					}
					Vector3 position = persistenceViewData.Transform.Position.ToVector3().ValueOrZeroIfBogus();
					Quaternion rotation = Quaternion.Euler(persistenceViewData.Transform.Rotation.ToVector3().ValueOrZeroIfBogus());
					float scale = persistenceViewData.Transform.Scale;
					if (version < RoomPersistenceVersion.CREATION_OBJECT_ADDED)
					{
						scale = 1f;
					}
					PhotonNetwork.InstantiateRequestEx instantiateRequestEx = ConstructInstantiateRequest(persistenceViewData, guid, position, rotation, scale, version, verboseLogging, nodeIdMappings);
					if (instantiateRequestEx != null)
					{
						instantiationRequests.Add(instantiateRequestEx);
						requestData.Add(persistenceViewData);
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("Failed to construct instantiation request for object with guid {0}.", guid);
					}
				}
			}
			catch (Exception exception5)
			{
				UnityEngine.Debug.LogException(exception5);
				promise.Error("Error preparing to instantiate room objects.");
				yield break;
			}
			GameObject[] instantiatedObjects;
			try
			{
				instantiatedObjects = PhotonNetwork.BulkInstantiateSceneObjectsEx(instantiationRequests);
			}
			catch (Exception exception6)
			{
				UnityEngine.Debug.LogException(exception6);
				promise.Error("Error instantiating room objects.");
				yield break;
			}
			List<Tuple<PersistenceView, PersistenceViewData>> viewDataPairs = new List<Tuple<PersistenceView, PersistenceViewData>>();
			try
			{
				for (int j = 0; j < instantiatedObjects.Length; j++)
				{
					PersistenceViewData persistenceViewData2 = requestData[j];
					Guid guid2 = RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceViewData2.Id);
					if (instantiatedObjects[j] == null)
					{
						UnityEngine.Debug.LogErrorFormat("Null object instantiated for Persistence View with guid {0}.", guid2);
						continue;
					}
					PersistenceView componentInChildren = instantiatedObjects[j].GetComponentInChildren<PersistenceView>();
					if (componentInChildren == null)
					{
						UnityEngine.Debug.LogErrorFormat("Unable to create or locate Persistence View on object {0} with guid {1}.", instantiatedObjects[j], guid2);
					}
					else if (componentInChildren.IsChildView)
					{
						UnityEngine.Debug.LogErrorFormat("Erroneously located child Persistence View {0} on object {1} with guid {2}. Should have located its parent view {3} instead.", componentInChildren, instantiatedObjects[j], guid2, componentInChildren.ParentView);
					}
					else
					{
						componentInChildren.gameObject.SetActive(value: true);
						componentInChildren.InitializeDeserialization(persistenceViewData2);
						viewDataPairs.Add(new Tuple<PersistenceView, PersistenceViewData>(componentInChildren, persistenceViewData2));
					}
				}
			}
			catch (Exception exception7)
			{
				UnityEngine.Debug.LogException(exception7);
				promise.Error("Error initializing room objects.");
				yield break;
			}
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item6 in viewDataPairs)
				{
					PersistenceView item = item6.Item1;
					PersistenceViewData item2 = item6.Item2;
					if (item != null)
					{
						item.PreDeserialize(version, item2, null);
					}
				}
			}
			catch (Exception exception8)
			{
				UnityEngine.Debug.LogException(exception8);
				promise.Error("Error pre-deserializing room objects.");
				yield break;
			}
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item7 in viewDataPairs)
				{
					PersistenceView item3 = item7.Item1;
					PersistenceViewData item4 = item7.Item2;
					if (item3 != null)
					{
						PersistableDeserializeParams deserializeParams = new PersistableDeserializeParams
						{
							version = version,
							viewData = item4,
							nodeIdMapping = nodeIdMappings,
							persistenceViewIdMappings = null,
							assignNewIds = false,
							isRuntimeCreated = false
						};
						item3.Deserialize(deserializeParams);
					}
				}
			}
			catch (Exception exception9)
			{
				UnityEngine.Debug.LogException(exception9);
				promise.Error("Error deserializing room objects.");
				yield break;
			}
			SynchronizedField.SendPendingRoomUpdates();
			try
			{
				ConnectableGraphData connectableGraphData = roomDataBlob.ConnectableGraphData;
				if (connectableGraphData != null)
				{
					NetworkedSingletonMonoBehaviour<SandboxConnectableManager>.Instance.MasterDeserializeConnectableGraph(connectableGraphData);
				}
			}
			catch (Exception exception10)
			{
				UnityEngine.Debug.LogException(exception10);
				promise.Error("Error deserializing connectable graph.");
				yield break;
			}
			yield return null;
			try
			{
				foreach (Tuple<PersistenceView, PersistenceViewData> item8 in viewDataPairs)
				{
					PersistenceView item5 = item8.Item1;
					if (item5 != null)
					{
						item5.PostDeserialize(null);
					}
				}
			}
			catch (Exception exception11)
			{
				UnityEngine.Debug.LogException(exception11);
				promise.Error("Error post-deserializing room objects.");
				yield break;
			}
			if (this.MasterRoomDeserializationCompleteEvent != null)
			{
				this.MasterRoomDeserializationCompleteEvent();
			}
			promise.Complete(new SaveLoadInfo
			{
				version = (RoomPersistenceVersion)roomDataBlob.Version
			});
		}

		private void DeserializeCustomActivityRoomDataBlob(PersistedRoomData roomDataBlob, bool verboseLogging, Promise<SaveLoadInfo> promise)
		{
			if (this.MasterRoomDeserializationStartEvent != null)
			{
				this.MasterRoomDeserializationStartEvent();
			}
			try
			{
				DeserializeRoomSettings(roomDataBlob);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				promise.Error("Error loading room settings");
				return;
			}
			if (this.MasterRoomDeserializationCompleteEvent != null)
			{
				this.MasterRoomDeserializationCompleteEvent();
			}
			promise.Complete(new SaveLoadInfo
			{
				version = (RoomPersistenceVersion)roomDataBlob.Version
			});
		}

		private void DestroyActivePersistenceViews(bool verbose)
		{
			List<GameObject> list = new List<GameObject>();
			List<PersistenceView> list2 = PersistenceView.AllViews.Values.ToList();
			foreach (PersistenceView item in list2)
			{
				if (item != null && item.IsPersistable)
				{
					PersistenceView.AllViews.Remove(item.Id);
					list.Add(item.gameObject);
				}
			}
			PhotonNetwork.BulkDestroy(list);
		}

		public PhotonNetwork.InstantiateRequestEx ConstructInstantiateRequest(PersistenceViewData viewData, Guid guid, Vector3 position, Quaternion rotation, float scale, RoomPersistenceVersion version, bool verboseLogging, Dictionary<int, int> circuitNodeIdMappings)
		{
			PhotonNetwork.InstantiateRequestEx result = null;
			if (viewData.SpawnableToolData != null)
			{
				result = ConstructSpawnableToolInstantiationRequest(viewData, guid, position, rotation, scale, verboseLogging, circuitNodeIdMappings);
			}
			else if (version < RoomPersistenceVersion.CREATION_OBJECT_ADDED && viewData.ShapeContainerData != null)
			{
				result = ConstructLegacyShapeContainerInstantiateRequest(viewData, guid, position, rotation, scale, verboseLogging, circuitNodeIdMappings);
			}
			else if (version < RoomPersistenceVersion.EXTRUSIONS_PHYSICS_MODE)
			{
				result = ConstructLegacyMoveableWhiteboardInstantiateRequest(viewData, guid, position, rotation, scale, verboseLogging, circuitNodeIdMappings);
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Cannot request instantiation for persistence view with ID {0} without spawnable tool.", guid);
			}
			return result;
		}

		private PhotonNetwork.InstantiateRequestEx ConstructSpawnableToolInstantiationRequest(PersistenceViewData viewData, Guid guid, Vector3 position, Quaternion rotation, float scale, bool verboseLogging, Dictionary<int, int> nodeIdMappings)
		{
			Guid guid2 = RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.SpawnableToolData.PrefabId);
			if (guid2 == Guid.Empty)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to construct instantiation request for instance with ID {0} that has an empty prefab ID.", guid);
				return null;
			}
			int num = ((viewData.CircuitNodeData != null) ? viewData.CircuitNodeData.CircuitNodeId : 0);
			if (num != 0)
			{
				num = nodeIdMappings?[num] ?? num;
			}
			PhotonNetwork.InstantiateRequestEx instantiateRequestEx = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.ConstructSpawnableToolInstantiationRequest(guid2, viewData.CreationObjectData, position, rotation, scale, num);
			if (instantiateRequestEx == null)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to construct instantiation request for instance with ID {0}.", guid);
			}
			return instantiateRequestEx;
		}

		private PhotonNetwork.InstantiateRequestEx ConstructLegacyMoveableWhiteboardInstantiateRequest(PersistenceViewData viewData, Guid guid, Vector3 position, Quaternion rotation, float scale, bool verboseLogging, Dictionary<int, int> circuitNodeIdMappings)
		{
			if (legacyMoveableWhiteboardData == null)
			{
				SpawnableTool component = SpawnableToolSettings.GetSpawnableToolPrefab(SpawnableToolType.MOVEABLE_WHITEBOARD).GetComponent<SpawnableTool>();
				legacyMoveableWhiteboardData = new SpawnableToolData
				{
					PrefabId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(component.PrefabId)
				};
			}
			viewData.SpawnableToolData = legacyMoveableWhiteboardData;
			return ConstructSpawnableToolInstantiationRequest(viewData, guid, position, rotation, scale, verboseLogging, circuitNodeIdMappings);
		}

		private PhotonNetwork.InstantiateRequestEx ConstructLegacyShapeContainerInstantiateRequest(PersistenceViewData viewData, Guid guid, Vector3 position, Quaternion rotation, float scale, bool verboseLogging, Dictionary<int, int> circuitNodeIdMappings)
		{
			if (legacyShapeContainerData == null)
			{
				SpawnableTool component = SpawnableToolSettings.GetSpawnableToolPrefab(SpawnableToolType.SHAPE_CONTAINER).GetComponent<SpawnableTool>();
				legacyShapeContainerData = new SpawnableToolData
				{
					PrefabId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(component.PrefabId)
				};
			}
			viewData.SpawnableToolData = legacyShapeContainerData;
			return ConstructSpawnableToolInstantiationRequest(viewData, guid, position, rotation, scale, verboseLogging, circuitNodeIdMappings);
		}

		private void SerializeRoomSettings(ref PersistedRoomData roomData)
		{
			IEnumerable<IPersistableSettings> enumerable = GatherPersistableSettings();
			foreach (IPersistableSettings item in enumerable)
			{
				item.SerializeTo(ref roomData);
			}
		}

		private void DeserializeRoomSettings(PersistedRoomData roomData)
		{
			IEnumerable<IPersistableSettings> enumerable = GatherPersistableSettings();
			foreach (IPersistableSettings item in enumerable)
			{
				item.DeserializeFrom(roomData);
			}
		}

		private IEnumerable<IPersistableSettings> GatherPersistableSettings()
		{
			List<IPersistableSettings> list = new List<IPersistableSettings>();
			list.Add(NetworkedSingletonMonoBehaviour<HostManager>.Instance);
			list.Add(NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance);
			if (PlayerRoomRoleManager.Instance != null)
			{
				list.Add(PlayerRoomRoleManager.Instance);
			}
			if (PlayerGameRoleManager.Instance != null)
			{
				list.Add(PlayerGameRoleManager.Instance);
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				list.Add(NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			}
			if (RecRoomSceneManager.Instance != null)
			{
				list.Add(RecRoomSceneManager.Instance);
			}
			return list;
		}

		private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			StopAllCoroutines();
		}

		private void SetPhotonNetworkPaused(bool paused)
		{
			if (isPhotonNetworkPaused != paused)
			{
				isPhotonNetworkPaused = paused;
				if (paused)
				{
					NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.PauseMessageQueue();
				}
				else
				{
					NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.ResumeMessageQueue();
				}
			}
		}

		private void StartPhotonTrafficMonitoring()
		{
			ResetPhotonTrafficMonitoring();
			NetworkDebug.InstantiateInvoked += OnPhotonTrafficMonitoring_Instantiate;
			NetworkDebug.DestroyInvoked += OnPhotonTrafficMonitoring_Destroy;
			NetworkDebug.RPCInvoked += OnPhotonTrafficMonitor_Rpc;
			NetworkDebug.RoomPropertiesSet += OnPhotonTrafficMonitoring_RoomProp;
		}

		private void StopPhotonTrafficMonitoring()
		{
			NetworkDebug.InstantiateInvoked -= OnPhotonTrafficMonitoring_Instantiate;
			NetworkDebug.DestroyInvoked -= OnPhotonTrafficMonitoring_Destroy;
			NetworkDebug.RPCInvoked -= OnPhotonTrafficMonitor_Rpc;
			NetworkDebug.RoomPropertiesSet -= OnPhotonTrafficMonitoring_RoomProp;
		}

		private void ResetPhotonTrafficMonitoring()
		{
			StopPhotonTrafficMonitoring();
			photonTrafficMonitor_instantiateCounter = 0;
			photonTrafficMonitor_destroyCounter = 0;
			photonTrafficMonitor_rpcCounter = 0;
			photonTrafficMonitor_roomPropCounter = 0;
		}

		private Dictionary<string, int> GetPhotonTrafficMonitoringStats()
		{
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			dictionary.Add("photon_instantiates", photonTrafficMonitor_instantiateCounter);
			dictionary.Add("photon_destroys", photonTrafficMonitor_destroyCounter);
			dictionary.Add("photon_rpcs", photonTrafficMonitor_rpcCounter);
			dictionary.Add("photon_roomprop_changes", photonTrafficMonitor_roomPropCounter);
			return dictionary;
		}

		private void OnPhotonTrafficMonitoring_Instantiate(GameObject go)
		{
			photonTrafficMonitor_rpcCounter++;
		}

		private void OnPhotonTrafficMonitoring_Destroy(GameObject go)
		{
			photonTrafficMonitor_destroyCounter++;
		}

		private void OnPhotonTrafficMonitor_Rpc(PhotonView view, string methodName, string player)
		{
			photonTrafficMonitor_instantiateCounter++;
		}

		private void OnPhotonTrafficMonitoring_RoomProp(ExitGames.Client.Photon.Hashtable properties)
		{
			photonTrafficMonitor_roomPropCounter++;
		}
	}
	[Serializable]
	public class SerializedGuid
	{
		[SerializeField]
		private byte[] bytes = new byte[16];

		[NonSerialized]
		private bool _valueSet;

		[NonSerialized]
		private Guid _value;

		public Guid Value
		{
			get
			{
				if (!_valueSet)
				{
					Deserialize();
				}
				return _value;
			}
			set
			{
				_value = value;
				_valueSet = true;
				Serialize();
			}
		}

		public SerializedGuid()
		{
		}

		public SerializedGuid(Guid guid)
		{
			Value = guid;
			_valueSet = false;
		}

		private void Deserialize()
		{
			_value = new Guid(bytes);
			_valueSet = true;
		}

		private void Serialize()
		{
			bytes = _value.ToByteArray();
		}
	}
}
