	{
		if (!PlayerPrefs.HasKey("fake_microsoft_platform_id"))
		{
			base.PlatformProfileId = (ulong)DateTime.UtcNow.Ticks;
			PlayerPrefs.SetString("fake_microsoft_platform_id", base.PlatformProfileId.ToString());
		}
		else
		{
			string s = PlayerPrefs.GetString("fake_microsoft_platform_id", DateTime.UtcNow.Ticks.ToString());
			base.PlatformProfileId = (ulong)long.Parse(s);
