	{
		string text = SystemInfo.deviceName;
		if (text.Contains("."))
		{
			text = text.Split('.')[0];
		}
		if (string.IsNullOrEmpty(text) || text.Length < 2)
		{
			text = "Guest";
		}
		return text;
	}

