public class OculusPlatformManager : PlatformManager
{
	private const float HMD_REFRESH_RATE = 90f;

	public override PlatformType CurrentPlatform => PlatformType.Oculus;

	public override bool HasVRFocus => OVRManager.hasVrFocus;

	private ulong DeviceSpecificHash
	{
		get
		{
			string deviceUniqueIdentifier = SystemInfo.deviceUniqueIdentifier;
			if (deviceUniqueIdentifier.Length < 2)
			{
				throw new Exception("Cannot login if the device does not report a Unique ID");
			}
			string s = deviceUniqueIdentifier.Substring(0, deviceUniqueIdentifier.Length / 2);
			string s2 = deviceUniqueIdentifier.Substring(deviceUniqueIdentifier.Length / 2);
			return (ulong)(((long)s.GetStableHashCode() << 4) + s2.GetStableHashCode());
		}
	}

	public override IEnumerator PreInitialize()
	{
		yield return null;
	}

	public override IEnumerator Initialize(InitializeCallback callback)
	{
		UpdateWindowsCustomURIRegistry();
		if (base.CurrentHardwareType == HardwareType.SANTA_CRUZ)
		{
			return InitializeSantaCruz(callback);
		}
		return InitializeRift(callback);
	}

	private IEnumerator InitializeSantaCruz(InitializeCallback callback)
	{
		yield return 0;
		UnityEngine.Debug.Log("Setting TiledMultiResLevel to High");
		OVRManager.tiledMultiResLevel = OVRManager.TiledMultiResLevel.LMSHigh;
		Player.SetPlatformPlayerId(CurrentPlatform, DeviceSpecificHash);
		UnityEngine.Application.runInBackground = true;
		UnityEngine.Time.fixedDeltaTime = 1f / 90f;
		callback(null);
	}

	private IEnumerator InitializeRift(InitializeCallback callback)
	{
		try
		{
			Oculus.Platform.Core.Initialize();
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
			callback("Failed to initialize Oculus Platform");
			yield break;
		}
		OculusApiCoroutine checkEntitlement = Entitlements.IsUserEntitledToApplication().AsCoroutine();
		yield return checkEntitlement;
		if (checkEntitlement.Result.IsError)
		{
			callback("You do not have permission to play this game");
			yield break;
		}
		OculusApiCoroutine<User> getLoggedInUser = Users.GetLoggedInUser().AsCoroutine();
		yield return getLoggedInUser;
		if (getLoggedInUser.Result.IsError)
		{
			callback("Unable to load Oculus user profile");
			yield break;
		}
		User user = getLoggedInUser.Result.Data;
		base.PlatformProfileId = user.ID;
		base.PlatformProfileName = user.OculusID;
		Player.SetPlatformPlayerId(CurrentPlatform, base.PlatformProfileId);
		UnityEngine.Application.runInBackground = true;
		UnityEngine.Time.fixedDeltaTime = 1f / 90f;
		callback(null);
	}

	public override IEnumerator PostLoginInitialize(InitializeCallback callback)
	{
		yield break;
	}

	public override void SetRichPresenceStatus(string statusText)
	{
	}

	public override IPromise<List<ulong>> GetPlatformFriendIds()
	{
		if (base.CurrentHardwareType != HardwareType.SANTA_CRUZ)
		{
			return Users.GetLoggedInUserFriends().AsPromise().ContinueWith((UserList userList) => userList.Select((User u) => u.ID).ToList());
		}
		return new ErroredPromise<List<ulong>>("GetPlatformFriendIds not yet supported");
	}

	public override IPromise<string> GetAuthParams()
	{
		if (base.CurrentHardwareType != HardwareType.SANTA_CRUZ)
		{
			return Users.GetUserProof().AsPromise().ContinueWith((UserProof userProof) => AmplitudeMiniJSON.Json.Serialize(new Dictionary<string, object> { { "Nonce", userProof.Value } }));
		}
		return new CompletedPromise<string>(null);
	}

	public override IPromise<string> GetPlatformFriendName(ulong friendId)
	{
		return Users.Get(friendId).AsPromise().ContinueWith((User user) => user.OculusID);
	}

	public override IPromise<Texture> GetPlatformFriendPicture(ulong friendId)
	{
		return Users.Get(friendId).AsPromise().ContinueWith((Func<User, IPromise<Texture>>)delegate(User user)
		{
			Promise<Texture> downloadPromise = new Promise<Texture>();
			HTTPRequest hTTPRequest = new HTTPRequest(new Uri(user.SmallImageUrl), delegate(HTTPRequest request, HTTPResponse response)
			{
				if (response != null && response.IsSuccess)
				{
					downloadPromise.Complete(response.DataAsTexture2D);
				}
				else
				{
					downloadPromise.Error("Failed to download Oculus friend picture");
				}
			});
			hTTPRequest.Send();
			return downloadPromise;
		});
	}

	public override IPromise ApplySkuMetadataOverrides(List<Commerce.SKU> skus)
	{
		string[] skus2 = skus.Select((Commerce.SKU s) => s.OculusSkuId).ToArray();
		return IAP.GetProductsBySKU(skus2).AsPromise().Then(delegate(ProductList products)
		{
			foreach (Commerce.SKU sku in skus)
			{
				Product product = products.Where((Product p) => p.Sku == sku.OculusSkuId).FirstOrDefault();
				if (product != null)
				{
					sku.DisplayPrice = product.FormattedPrice;
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("SKU {0} does not exist on Oculus", sku.OculusSkuId);
				}
			}
		});
	}

	public override IPromise<string> GetCommerceAccessToken()
	{
		return Users.GetAccessToken().AsPromise();
	}

	public override IPromise AuthorizePurchase(long transactionId, Commerce.SKU sku)
	{
		return IAP.LaunchCheckoutFlow(sku.OculusSkuId).AsPromise().ContinueWith(delegate(Purchase purchase)
		{
			object result;
			if (string.IsNullOrEmpty(purchase.Sku))
			{
				IPromise promise = new ErroredPromise("Purchase cancelled");
				result = promise;
			}
			else
			{
				result = new CompletedPromise();
			}
			return (IPromise)result;
		});
	}

	protected override HardwareType CalculateCurrentHardwareType()
	{
		return HardwareType.OCULUS;
	}
}
public static class OculusApiPromiseExtensions
{
	public static IPromise<Oculus.Platform.Message> AsPromise(this Request request)
	{
		Promise<Oculus.Platform.Message> promise = new Promise<Oculus.Platform.Message>();
		request.OnComplete(delegate(Oculus.Platform.Message message)
		{
			if (message.IsError)
			{
				Error error = message.GetError();
				promise.Error($"{error.Message} ({error.Code}|{error.HttpCode})");
			}
			else
			{
				promise.Complete(message);
			}
		});
		return promise;
	}

	public static IPromise<T> AsPromise<T>(this Request<T> request)
	{
		Promise<T> promise = new Promise<T>();
		request.OnComplete(delegate(Message<T> message)
		{
			if (message.IsError)
			{
				Error error = message.GetError();
				promise.Error($"{error.Message} ({error.Code}|{error.HttpCode})");
			}
			else
			{
				promise.Complete(message.Data);
			}
		});
		return promise;
	}
}
