public class PlatformActivateObject : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private PlatformManager.PlatformType[] platforms = new PlatformManager.PlatformType[0];

	private bool? _cachedShouldBeActive;

	public bool ShouldBeActive
	{
		get
		{
			if (!_cachedShouldBeActive.HasValue)
			{
				if (platforms.Length == 0)
				{
					UnityEngine.Debug.LogError("PlatformActivateObject requires at least one specified platform.");
					return false;
				}
				_cachedShouldBeActive = platforms.Contains(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform);
			}
			return _cachedShouldBeActive.Value;
		}
	}

	private void Awake()
	{
		base.gameObject.SetActive(ShouldBeActive);
	}

	private void OnEnable()
	{
		base.gameObject.SetActive(ShouldBeActive);
	}
}
