public abstract class PlatformManager : SingletonMonoBehaviour<PlatformManager>
{
	public enum PlatformType
	{
		All = -1,
		Steam,
		Oculus,
		PlayStation,
		Microsoft,
		HeadlessBot
	}

	[Flags]
	public enum PlatformMask
	{
		None = 0,
		Steam = 1,
		Oculus = 2,
		PlayStation = 4,
		Microsoft = 8,
		HeadlessBot = 0x10,
		All = -1
	}

	public enum HardwareType
	{
		VIVE,
		OCULUS,
		PSVR,
		MICROSOFT_VR,
		DESKTOP_NO_VR,
		SANTA_CRUZ
	}

	public delegate void InitializeCallback(string error);

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_CurrentHardwareTypeChanged;

	private string _platformName = string.Empty;

	private HardwareType _hardwareType;

	public ulong PlatformProfileId { get; protected set; }

	public string PlatformProfileName { get; protected set; }

	public byte[] PlatformProfileImage { get; protected set; }

	public string PlatformName
	{
		get
		{
			if (string.IsNullOrEmpty(_platformName))
			{
				switch (CurrentPlatform)
				{
				case PlatformType.Steam:
					_platformName = "Steam";
					break;
				case PlatformType.Oculus:
					_platformName = "Oculus";
					break;
				case PlatformType.PlayStation:
					_platformName = "PSN";
					break;
				case PlatformType.Microsoft:
					_platformName = "Xbox LIVE";
					break;
				default:
					_platformName = string.Empty;
					break;
				}
			}
			return _platformName;
		}
	}

	public HardwareType CurrentHardwareType
	{
		get
		{
			return _hardwareType;
		}
		protected set
		{
			if (_hardwareType != value)
			{
				_hardwareType = value;
				if (this.CurrentHardwareTypeChanged != null)
				{
					this.CurrentHardwareTypeChanged();
				}
			}
		}
	}

	public string ExecutablePath
	{
		get
		{
			string path = ((CurrentPlatform != PlatformType.Oculus) ? "Recroom_Release.exe" : "Recroom_Oculus.exe");
			return Path.Combine(Directory.GetParent(UnityEngine.Application.dataPath).FullName, path);
		}
	}

	public abstract PlatformType CurrentPlatform { get; }

	public string CurrentPlatformAsAnalyticsString => CurrentPlatform switch
	{
		PlatformType.All => "ALL", 
		PlatformType.Steam => "STEAM", 
		PlatformType.Oculus => "OCULUS", 
		PlatformType.PlayStation => "PS4", 
		PlatformType.Microsoft => "MICROSOFT", 
		PlatformType.HeadlessBot => "LINUX_HEADLESS_BOT", 
		_ => "UNKNOWN", 
	};

	public abstract bool HasVRFocus { get; }

	public event Action CurrentHardwareTypeChanged
	{
		add
		{
			Action action = this.m_CurrentHardwareTypeChanged;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_CurrentHardwareTypeChanged, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_CurrentHardwareTypeChanged;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_CurrentHardwareTypeChanged, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		UpdateCurrentHardwareType();
	}

	public void UpdateCurrentHardwareType()
	{
		CurrentHardwareType = CalculateCurrentHardwareType();
	}

	public abstract IEnumerator PreInitialize();

	public abstract IEnumerator Initialize(InitializeCallback callback);

	public abstract IEnumerator PostLoginInitialize(InitializeCallback callback);

	public abstract void SetRichPresenceStatus(string statusText);

	public abstract IPromise<string> GetAuthParams();

	public abstract IPromise<List<ulong>> GetPlatformFriendIds();

	public abstract IPromise<string> GetPlatformFriendName(ulong friendId);

	public abstract IPromise<Texture> GetPlatformFriendPicture(ulong friendId);

	public abstract IPromise ApplySkuMetadataOverrides(List<Commerce.SKU> skus);

	public abstract IPromise<string> GetCommerceAccessToken();

	public abstract IPromise AuthorizePurchase(long transactionId, Commerce.SKU sku);

	protected abstract HardwareType CalculateCurrentHardwareType();

	protected void UpdateWindowsCustomURIRegistry()
	{
		try
		{
			RegistryKey registryKey = Registry.CurrentUser.OpenSubKey("Software", writable: true).OpenSubKey("Classes", writable: true);
			RegistryKey registryKey2 = registryKey.OpenSubKey("recroom", writable: true);
			if (registryKey2 == null)
			{
				registryKey2 = registryKey.CreateSubKey("recroom");
				registryKey2.SetValue(string.Empty, "\"URL:RecRoom Protocol\"");
				registryKey2.SetValue("URL Protocol", string.Empty);
			}
			RegistryKey registryKey3 = registryKey2.OpenSubKey("shell\\open\\command", writable: true);
			if (registryKey3 == null)
			{
				registryKey3 = registryKey2.CreateSubKey("shell\\open\\command");
			}
			registryKey3.SetValue(string.Empty, ExecutablePath);
			registryKey.Close();
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
	}
}
