	{
		private const string LogString = "Log";

		private const string WarnString = "Warning";

		private const string ExceptionString = "EXCEPTION";

		private const string ErrorString = "ERROR";

		private void OnEnable()
		{
			UnityEngine.Application.logMessageReceived += HandleLog;
		}

		private void OnDisable()
		{
			UnityEngine.Application.logMessageReceived -= HandleLog;
		}

		private void HandleLog(string logString, string stackTrace, LogType type)
		{
			string text = type switch
			{
				LogType.Log => "Log", 
				LogType.Warning => "Warning", 
				LogType.Exception => "EXCEPTION", 
				_ => "ERROR", 
			};
			string value = $"{UnityEngine.Time.frameCount} {text} | {logString}\n\n{stackTrace}";
			Console.WriteLine(value);
		}
	}
