public class PS4VRPlaySpace : UnityEngine.MonoBehaviour
{
	public Transform frustumTransform;

	public Renderer[] frustumRenderers;

	public float safeDistance = 0.1f;

	public float fadeSpeed = 3f;

	public Color showColor;

	public Color hideColor;

	private bool showFrustum;

	private Vector3 camAcceleration;

	private Vector3 hmdPositionRaw;

	private Quaternion hmdRotationUnity;

	private Quaternion hmdRotationRaw;

	private void Start()
	{
		Renderer[] array = frustumRenderers;
		foreach (Renderer renderer in array)
		{
			renderer.material.color = hideColor;
		}
	}

	private void Update()
	{
	}

	private void UpdateFrustumTransform()
	{
	}

	private void UpdateFrustumDisplay()
	{
		Renderer[] array = frustumRenderers;
		foreach (Renderer renderer in array)
		{
			if (showFrustum)
			{
				renderer.material.color = Color.Lerp(renderer.material.color, showColor, UnityEngine.Time.deltaTime * fadeSpeed);
			}
			else
			{
				renderer.material.color = Color.Lerp(renderer.material.color, hideColor, UnityEngine.Time.deltaTime * fadeSpeed * 2f);
			}
		}
	}
}
internal class SteamPlatformManager : PlatformManager
{
	public const uint RECROOM_APP_ID = 471710u;

	private bool initialized;

	private bool isOverlayActive;

	private Callback<GameRichPresenceJoinRequested_t> gameRichPresenceJoinRequested;

	private Callback<MicroTxnAuthorizationResponse_t> microTxnAuthorizationResponse;

	private Dictionary<long, Promise> purchaseResponses = new Dictionary<long, Promise>();

	public override PlatformType CurrentPlatform => PlatformType.Steam;

	public override bool HasVRFocus => true;

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (initialized)
		{
			SteamAPI.Shutdown();
			SteamCallbacks.GameRichPresenceJoinRequested_t.UnregisterCallback(OnGameRichPresenceJoinRequested);
			SteamCallbacks.MicroTxnAuthorizationResponse_t.UnregisterCallback(OnMicroTxnAuthorizationResponse);
			SteamCallbacks.GameOverlayActivated_t.UnregisterCallback(OnScreenOverlayActivated);
			SteamVR_Events.InputFocus.RemoveListener(OnVRInputFocusChanged);
		}
		Player.PlayerCreatedEvent -= new Action<Player>(OnRecRoomPlayerCreated);
	}

	private void Update()
	{
		if (initialized)
		{
			SteamAPI.RunCallbacks();
		}
	}

	private void OnRecRoomPlayerCreated(Player player)
	{
		if (!player.isLocal && player.Platform == PlatformType.Steam)
		{
			SteamFriends.SetPlayedWith(new CSteamID(player.PlatformId));
		}
	}

	private bool ShouldRestart()
	{
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
			return true;
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
			return true;
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(new AppId_t(471710u)))
			{
				return true;
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			return true;
		}
		return false;
	}

	public override IEnumerator PreInitialize()
	{
		yield return null;
	}

	public override IEnumerator Initialize(InitializeCallback callback)
	{
		if (ShouldRestart())
		{
			UnityEngine.Application.Quit();
			yield break;
		}
		UpdateWindowsCustomURIRegistry();
		if (!SteamAPI.Init())
		{
			callback("Failed to initialize Steam Platform");
			yield break;
		}
		initialized = true;
		SteamCallbacks.GameRichPresenceJoinRequested_t.RegisterCallback(OnGameRichPresenceJoinRequested);
		SteamCallbacks.MicroTxnAuthorizationResponse_t.RegisterCallback(OnMicroTxnAuthorizationResponse);
		SteamCallbacks.GameOverlayActivated_t.RegisterCallback(OnScreenOverlayActivated);
		SteamVR_Events.InputFocus.AddListener(OnVRInputFocusChanged);
		Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
		CSteamID steamID = SteamUser.GetSteamID();
		base.PlatformProfileId = (ulong)steamID;
		base.PlatformProfileName = SteamFriends.GetPersonaName();
		Player.SetPlatformPlayerId(CurrentPlatform, base.PlatformProfileId);
		GameSessions.OnLocalGameSessionUpdated += OnLocalGameSessionUpdated;
		callback(null);
	}

	public override IEnumerator PostLoginInitialize(InitializeCallback callback)
	{
		int friendCount = SteamFriends.GetFriendCount(EFriendFlags.k_EFriendFlagBlocked | EFriendFlags.k_EFriendFlagIgnored);
		if (friendCount > 0)
		{
			List<ulong> list = new List<ulong>(friendCount);
			for (int i = 0; i < friendCount; i++)
			{
				list.Add((ulong)SteamFriends.GetFriendByIndex(i, EFriendFlags.k_EFriendFlagBlocked));
			}
			Relationships.BulkIgnorePlatformUsers(CurrentPlatform, list);
		}
		callback(null);
		yield break;
	}

	public Texture2D LoadAvatarForPlayer(CSteamID steamID)
	{
		int mediumFriendAvatar = SteamFriends.GetMediumFriendAvatar(steamID);
		if (mediumFriendAvatar != 0 && SteamUtils.GetImageSize(mediumFriendAvatar, out var pnWidth, out var pnHeight) && pnWidth != 0 && pnHeight != 0)
		{
			byte[] array = new byte[pnWidth * pnHeight * 4];
			if (SteamUtils.GetImageRGBA(mediumFriendAvatar, array, (int)(pnWidth * pnHeight * 4)))
			{
				uint num = pnWidth * 4;
				byte[] array2 = new byte[num];
				for (uint num2 = 0u; num2 < pnHeight / 2; num2++)
				{
					uint num3 = num2 * num;
					uint num4 = (pnHeight - num2 - 1) * num;
					Array.Copy(array, num3, array2, 0L, num);
					Array.Copy(array, num4, array, num3, num);
					Array.Copy(array2, 0L, array, num4, num);
				}
				Texture2D texture2D = new Texture2D((int)pnWidth, (int)pnHeight, TextureFormat.RGBA32, mipmap: false, linear: true);
				texture2D.LoadRawTextureData(array);
				texture2D.Apply();
				return texture2D;
			}
		}
		return null;
	}

