	public override IPromise<string> GetAuthParams()
	{
		try
		{
			byte[] array = new byte[1024];
			SteamUser.GetAuthSessionTicket(array, 1024, out var pcbTicket);
			string value = BitConverter.ToString(array, 0, (int)pcbTicket).Replace("-", string.Empty);
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("Ticket", value);
			string result = AmplitudeMiniJSON.Json.Serialize(dictionary);
			return new CompletedPromise<string>(result);
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
			return new ErroredPromise<string>("Failed to get auth params");
		}
	}

