	{
		return new CompletedPromise<string>(string.Empty);
	}

	public override IPromise AuthorizePurchase(long transactionId, Commerce.SKU sku)
	{
		return GetOrCreatePurchasePromise(transactionId).Finally(delegate
		{
			CleanupPurchasePromise(transactionId);
		});
	}

	private Promise GetOrCreatePurchasePromise(long transactionId)
	{
		lock (purchaseResponses)
		{
			if (!purchaseResponses.TryGetValue(transactionId, out var promise))
			{
				promise = new Promise();
				purchaseResponses.Add(transactionId, promise);
				int counter = 30;
				IDisposable token = this.Update1hz(delegate
				{
					if (isOverlayActive)
					{
						counter = 30;
					}
					else
					{
						counter--;
					}
					if (counter == 0)
					{
						UnityEngine.Debug.LogError("Timed out waiting for Steam overlay.");
						promise.Error("Timed out waiting for Steam overlay.");
					}
				});
				promise.Finally(delegate
				{
					token.Dispose();
				});
			}
			return promise;
		}
	}

	private void CleanupPurchasePromise(long transactionId)
	{
		lock (purchaseResponses)
		{
			purchaseResponses.Remove(transactionId);
		}
	}

	private void OnMicroTxnAuthorizationResponse(MicroTxnAuthorizationResponse_t param)
	{
		Promise orCreatePurchasePromise = GetOrCreatePurchasePromise((long)param.m_ulOrderID);
		if (param.m_bAuthorized == 0)
		{
			orCreatePurchasePromise.Error("Purchase cancelled/denied");
		}
		else
		{
			orCreatePurchasePromise.Complete();
		}
	}

	protected override HardwareType CalculateCurrentHardwareType()
	{
		if (SteamVR.instance == null || string.IsNullOrEmpty(XRDevice.model))
		{
			return HardwareType.DESKTOP_NO_VR;
		}
		if (SteamVR.instance.hmd_TrackingSystemName == "holographic" && SteamVR.instance.hmd_SerialNumber == "WindowsHolographic")
		{
			return HardwareType.MICROSOFT_VR;
		}
		if (XRDevice.model.StartsWith("oculus", StringComparison.InvariantCultureIgnoreCase))
		{
			return HardwareType.OCULUS;
		}
		return HardwareType.VIVE;
	}
}
namespace RecRoom.Platforms.Steam
{
	public class SteamVRDeviceManager : VRDeviceManager
	{
		public static readonly string[] SUPPORTED_DEVICES = new string[2] { "None", "OpenVR" };

		private const string DEVICE_NAME = "OpenVR";

		private bool? initialProximitySensorValue;

		private bool hasSeenProximitySensorChange;

		protected override IEnumerable<string> SupportedDevices => SUPPORTED_DEVICES;

		protected override string DeviceName => "OpenVR";

		protected override bool HMDExistsInternal => OpenVR.IsHmdPresent();

		protected override bool UserInHMDInternal
		{
			get
			{
				if (OpenVR.System != null)
				{
					if (SteamVrUseProximitySensor())
					{
						return SteamVrProximitySensorValue();
					}
					EDeviceActivityLevel trackedDeviceActivityLevel = OpenVR.System.GetTrackedDeviceActivityLevel(0u);
					return trackedDeviceActivityLevel == EDeviceActivityLevel.k_EDeviceActivityLevel_UserInteraction;
				}
				return false;
			}
		}

		protected override bool KeepDeviceLoadedWhileDynamicallySwitching => true;

		protected override void PostSetupLogic(bool success)
		{
			if (success)
			{
				SteamVR.enabled = true;
				SteamVR_Render.instance.enabled = true;
				MarkHardwareTypeAsChanged();
			}
		}

		protected override IEnumerator<ISchedule> PreSetupLogic()
		{
			yield break;
		}

		protected override void ShutdownLogic()
		{
			if (XRSettings.loadedDeviceName == DeviceName)
			{
				XRSettings.enabled = true;
			}
			SteamVR.enabled = false;
			SteamVR_Render.instance.enabled = false;
			MarkHardwareTypeAsChanged();
		}

		private bool SteamVrUseProximitySensor()
		{
			ETrackedPropertyError pError = ETrackedPropertyError.TrackedProp_Success;
			if (!OpenVR.System.GetBoolTrackedDeviceProperty(0u, ETrackedDeviceProperty.Prop_ContainsProximitySensor_Bool, ref pError) || pError != ETrackedPropertyError.TrackedProp_Success)
			{
				return false;
			}
			if (!initialProximitySensorValue.HasValue)
			{
				initialProximitySensorValue = SteamVrProximitySensorValue();
				return false;
			}
			if (!hasSeenProximitySensorChange && initialProximitySensorValue.Value != SteamVrProximitySensorValue())
			{
				hasSeenProximitySensorChange = true;
			}
			return hasSeenProximitySensorChange;
		}

		private bool SteamVrProximitySensorValue()
		{
			SteamVR_Controller.Device device = SteamVR_Controller.Input(0);
			return device.GetPress(EVRButtonId.k_EButton_ProximitySensor);
		}

		private void MarkHardwareTypeAsChanged()
		{
			SingletonMonoBehaviour<PlatformManager>.Instance.UpdateCurrentHardwareType();
		}
	}
}
