namespace RecRoom
{
	public class FontDebugger : UnityEngine.MonoBehaviour
	{
		public static int textureRebuiltCounter;

		public float logInterval = 1f;

		private float lastLogTime;

		private void Awake()
		{
			Font.textureRebuilt += Font_textureRebuilt;
		}

		private void Font_textureRebuilt(Font obj)
		{
			textureRebuiltCounter++;
		}

		private void Update()
		{
			if (UnityEngine.Time.time - lastLogTime > logInterval && textureRebuiltCounter > 0)
			{
				UnityEngine.Debug.Log("*****" + lastLogTime.ToString("F2") + " - " + UnityEngine.Time.time.ToString("F2") + ": Font texture rebuilds: " + textureRebuiltCounter);
				lastLogTime = UnityEngine.Time.time;
				textureRebuiltCounter = 0;
			}
		}
	}
