	private IEnumerator RunMoveLocalPlayer()
	{
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		SetPlayerHeight();
		Vector3 initialPosition = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position;
		while (true)
		{
			if (randomlyMovePlayer)
			{
				RandomlyMovePlayer();
				yield return new WaitForSeconds(0.05f);
			}
			yield return null;
		}
	}

	private void SetPlayerHeight()
	{
		if (Player.LocalPlayer != null)
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position;
			position.y = UnityEngine.Random.Range(1.6f, 1.8f);
			SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position = position;
		}
	}

	private void RandomlyMovePlayer()
	{
		if (Player.LocalPlayer != null)
		{
			Vector3 velocity = new Vector3(UnityEngine.Random.Range(-0.1f, 0.1f), UnityEngine.Random.Range(-0.15f, 0.15f), UnityEngine.Random.Range(-0.1f, 0.1f));
			Player.LocalPlayer.PlayerLocomotion.Move(velocity);
			if (!(UnityEngine.Random.value < 0.02f))
			{
			}
		}
	}

	private void OnGUI()
	{
		GUILayout.BeginArea(new Rect(300f, 300f, 300f, 300f));
		GUILayout.BeginHorizontal();
		GUILayout.Box("Scene : " + SceneManagerHelper.ActiveSceneName);
		GUILayout.BeginVertical();
		if (GUILayout.Button((!mainCameraCulled) ? "Stop render" : "Start render"))
		{
			mainCameraCulled = !mainCameraCulled;
		}
		if (GUILayout.Button((!randomlyMovePlayer) ? "Move player" : "Stop moving"))
		{
			randomlyMovePlayer = !randomlyMovePlayer;
		}
		GUILayout.EndVertical();
		GUILayout.EndHorizontal();
		GUILayout.EndArea();
	}
