namespace RecRoom.Platforms
{
	public abstract class VRDeviceManager : SingletonMonoBehaviour<VRDeviceManager>
	{
		protected const string NONE_DEVICE_NAME = "None";

		private ISchedulerPromise activeCoroutine;

		private Action pendingAction;

		private bool errorLoadingDevice;

		private const string SKIP_USER_PRESENCE_CHECK_KEY = "SKIPS_USER_PRESENCE_CHECK";

		private bool? cachedSkipUserPresenceCheck;

		private bool _vrDisabled;

		protected abstract IEnumerable<string> SupportedDevices { get; }

		protected abstract string DeviceName { get; }

		protected abstract bool HMDExistsInternal { get; }

		public bool HMDExists
		{
			get
			{
				if (errorLoadingDevice)
				{
					return false;
				}
				if (VRDisabled)
				{
					return false;
				}
				return HMDExistsInternal;
			}
		}

		protected abstract bool UserInHMDInternal { get; }

		public bool UserInHMD
		{
			get
			{
				if (!HMDExists)
				{
					return false;
				}
				if (SkipUserPresenceCheck)
				{
					return true;
				}
				return UserInHMDInternal;
			}
		}

		protected abstract bool KeepDeviceLoadedWhileDynamicallySwitching { get; }

		protected bool IsVRMode => SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode;

		protected bool CanDynamicallySwitchDisplayMode => SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.CanDynamicallySwitchDisplayMode;

		protected bool IsDeviceLoadedAndPresent => XRSettings.loadedDeviceName == DeviceName && XRDevice.isPresent;

		private bool SkipUserPresenceCheck
		{
			get
			{
				bool? flag = cachedSkipUserPresenceCheck;
				if (!flag.HasValue)
				{
					if (!RecroomPrefs.IsReady)
					{
						return false;
					}
					cachedSkipUserPresenceCheck = ((RecroomPrefs.GetInt("SKIPS_USER_PRESENCE_CHECK", 0) != 0) ? true : false);
				}
				bool? flag2 = cachedSkipUserPresenceCheck;
				return flag2.Value;
			}
		}

		private bool IsCoroutineRunning => activeCoroutine != null && !activeCoroutine.IsCompleted;

		private bool VRDisabled
		{
			get
			{
				return _vrDisabled;
			}
			set
			{
				if (_vrDisabled != value)
				{
					_vrDisabled = value;
					if (_vrDisabled)
					{
						XRSettings.enabled = false;
						ShutdownVRState();
					}
				}
			}
		}

		public bool VRActive { get; private set; }

		protected virtual void Start()
		{
			LocalPlayerController localPlayerController = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			localPlayerController.DisplayModeChange = (Action)Delegate.Combine(localPlayerController.DisplayModeChange, new Action(UpdateVRState));
			LocalPlayerController localPlayerController2 = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			localPlayerController2.CanDynamicallySwitchDisplayModeChange = (Action)Delegate.Combine(localPlayerController2.CanDynamicallySwitchDisplayModeChange, new Action(UpdateVRState));
			if (HMDExists && SingletonMonoBehaviour<LocalPlayerController>.Instance.CanDynamicallySwitchDisplayMode)
			{
				SetupVRState();
			}
			else
			{
				UpdateVRState();
			}
			this.UpdateAtRate(0.3f, StaggeredUpdate);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
			{
				LocalPlayerController localPlayerController = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				localPlayerController.DisplayModeChange = (Action)Delegate.Remove(localPlayerController.DisplayModeChange, new Action(UpdateVRState));
				LocalPlayerController localPlayerController2 = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				localPlayerController2.CanDynamicallySwitchDisplayModeChange = (Action)Delegate.Remove(localPlayerController2.CanDynamicallySwitchDisplayModeChange, new Action(UpdateVRState));
			}
		}

		private void StaggeredUpdate(float deltaTime)
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode && (!HMDExists || !IsDeviceLoadedAndPresent))
			{
				SetupVRState();
			}
		}

		protected void UpdateVRState()
		{
			switch (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode)
			{
			case LocalPlayerController.DisplayMode.VR:
				SetupVRState();
				break;
			case LocalPlayerController.DisplayMode.SCREEN:
				ShutdownVRState();
				break;
			}
		}

		protected void SetupVRState()
		{
			if (!VRDisabled)
			{
				if (IsCoroutineRunning)
				{
					pendingAction = SetupVRState;
				}
				else
				{
					StartActiveCoroutine(SetupVRCoroutine());
				}
			}
		}

		private IEnumerator<ISchedule> SetupVRCoroutine()
		{
			yield return SingletonMonoBehaviour<Scheduler>.Instance.Run(PreSetupLogic());
			if (!IsDeviceLoadedAndPresent)
			{
				XRSettings.LoadDeviceByName(DeviceName);
				yield return Schedule.NextFrame;
				if (IsDeviceLoadedAndPresent)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.localPosition = Vector3.zero;
					SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.localRotation = Quaternion.identity;
					SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.localScale = Vector3.one;
				}
			}
			XRSettings.enabled = true;
			XRSettings.showDeviceView = true;
			bool loadSuccessful = IsDeviceLoadedAndPresent;
			errorLoadingDevice = !loadSuccessful;
			VRActive = loadSuccessful;
			PostSetupLogic(loadSuccessful);
			UnityEngine.Debug.LogFormat("Setup VR device: {0}  Success: {1}", DeviceName, loadSuccessful);
			if (!loadSuccessful)
			{
				UnityEngine.Debug.LogErrorFormat("Error loading VR device {0}\nLoaded device: {1}\nDevice present:{2}", DeviceName, XRSettings.loadedDeviceName, XRDevice.isPresent);
				ShutdownVRState();
			}
		}

		protected void ResetVRState()
		{
			if (!VRDisabled)
			{
				if (IsCoroutineRunning)
				{
					pendingAction = ResetVRState;
				}
				else
				{
					StartActiveCoroutine(ShutdownVRCoroutine(setupAgain: true));
				}
			}
		}

		protected void ShutdownVRState()
		{
			if (IsCoroutineRunning)
			{
				pendingAction = ShutdownVRState;
			}
			else
			{
				StartActiveCoroutine(ShutdownVRCoroutine(setupAgain: false));
			}
		}

		private IEnumerator<ISchedule> ShutdownVRCoroutine(bool setupAgain)
		{
			if (!KeepDeviceLoadedWhileDynamicallySwitching || !CanDynamicallySwitchDisplayMode)
			{
				if (XRSettings.loadedDeviceName != "None" && XRSettings.supportedDevices.Contains("None"))
				{
					UnityEngine.Debug.LogFormat("Unload VR device: {0}", DeviceName);
					XRSettings.LoadDeviceByName("None");
					yield return Schedule.NextFrame;
				}
				XRSettings.enabled = false;
			}
			XRSettings.showDeviceView = false;
			VRActive = false;
			ShutdownLogic();
			if (setupAgain)
			{
				SetupVRState();
			}
		}

		protected abstract IEnumerator<ISchedule> PreSetupLogic();

		protected abstract void PostSetupLogic(bool success);

		protected abstract void ShutdownLogic();

		private void StartActiveCoroutine(IEnumerator<ISchedule> routine)
		{
			if (activeCoroutine != null && !activeCoroutine.IsCompleted)
			{
				activeCoroutine.Cancel();
			}
			activeCoroutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(this, routine);
			activeCoroutine.Finally(delegate
			{
				if (pendingAction != null)
				{
					this.InvokeNextUpdate(delegate
					{
						if (pendingAction != null)
						{
							pendingAction();
							pendingAction = null;
						}
					});
				}
			});
		}
	}
}
public class ActivityBounds : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Tooltip("If this is checked, when a player enters these bounds, they will be considered Out of Bounds")]
	private bool triggersOutOfBounds;

	private static List<ActivityBounds> inPlayAreaBounds = new List<ActivityBounds>();

	private static List<ActivityBounds> outOfPlayAreaBounds = new List<ActivityBounds>();

	private OverlapVolume overlapVolume;

	private void Awake()
	{
		overlapVolume = GetComponent<OverlapVolume>();
		if (triggersOutOfBounds)
		{
			outOfPlayAreaBounds.Add(this);
		}
		else
		{
			inPlayAreaBounds.Add(this);
		}
	}

	private void OnDestroy()
	{
		inPlayAreaBounds.Remove(this);
		outOfPlayAreaBounds.Remove(this);
	}

	private bool ContainsPoint(Vector3 point)
	{
		return overlapVolume.ContainsPoint(point);
	}

	public static bool PointInBounds(Vector3 point)
	{
		for (int i = 0; i < outOfPlayAreaBounds.Count; i++)
		{
			if (outOfPlayAreaBounds[i].ContainsPoint(point))
			{
				return false;
			}
		}
		for (int j = 0; j < inPlayAreaBounds.Count; j++)
		{
			if (inPlayAreaBounds[j].ContainsPoint(point))
			{
				return true;
			}
		}
		return inPlayAreaBounds.Count == 0;
	}
}
