	[Serializable]
	public struct PlayerAnimationEvent
	{
		public enum AnimationEventType
		{
			NONE = 0,
			DROP_TOOL = 1,
			THROW_TOOL = 2,
			CUSTOM_ACTION_1 = 3,
			CUSTOM_ACTION_2 = 4,
