	[Serializable]
	public struct PlayerAnimationFrameTransform
	{
		public Vector3 Position;

		public Quaternion Rotation;

		public PlayerAnimationFrameTransform(Vector3 position, Quaternion rotation)
		{
			Position = position;
			Rotation = rotation;
		}

		public static PlayerAnimationFrameTransform Interpolate(PlayerAnimationFrameTransform lhs, PlayerAnimationFrameTransform rhs, float t)
		{
			return new PlayerAnimationFrameTransform(Vector3.Lerp(lhs.Position, rhs.Position, t), Quaternion.Slerp(lhs.Rotation, rhs.Rotation, t));
		}

		public static PlayerAnimationFrameTransform Mirror(PlayerAnimationFrameTransform transform)
		{
			Vector3 right = Vector3.right;
			return new PlayerAnimationFrameTransform(MirrorPosition(transform.Position, right), MirrorRotation(transform.Rotation, right));
		}

		private static Vector3 MirrorPosition(Vector3 position, Vector3 mirrorPlaneNormal)
		{
			Vector3 vector = Vector3.Project(position, mirrorPlaneNormal);
			Vector3 vector2 = position - vector;
			return vector2 - vector;
		}

		private static Quaternion MirrorRotation(Quaternion rotation, Vector3 mirrorPlaneNormal)
		{
			rotation.ToAngleAxis(out var angle, out var axis);
			Vector3 vector = Vector3.Project(axis, mirrorPlaneNormal);
			Vector3 vector2 = axis - vector;
			axis = -vector2 + vector;
			return Quaternion.AngleAxis(angle, axis);
		}
	}
	[Serializable]
	public struct PlayerAnimationFrame
	{
		public enum TransformType
		{
			NONE,
			LEFT_HAND,
			RIGHT_HAND,
			HEAD,
			BODY
		}

		public float Time;

		public PlayerAnimationFrameTransform LeftHand;

		public float LeftHandTrigger;

		public PlayerAnimationFrameTransform RightHand;

		public float RightHandTrigger;

		public PlayerAnimationFrameTransform Head;

		public PlayerAnimationFrameTransform Body;

		public PlayerAnimationFrame(float time, PlayerAnimationFrameTransform leftHand, float leftHandTrigger, PlayerAnimationFrameTransform rightHand, float rightHandTrigger, PlayerAnimationFrameTransform head, PlayerAnimationFrameTransform body)
		{
			Time = time;
			LeftHand = leftHand;
			LeftHandTrigger = leftHandTrigger;
			RightHand = rightHand;
			RightHandTrigger = rightHandTrigger;
			Head = head;
			Body = body;
		}

		public static PlayerAnimationFrame Interpolate(PlayerAnimationFrame lhs, PlayerAnimationFrame rhs, float t)
		{
			return new PlayerAnimationFrame(lhs.Time, PlayerAnimationFrameTransform.Interpolate(lhs.LeftHand, rhs.LeftHand, t), Mathf.Lerp(lhs.LeftHandTrigger, rhs.LeftHandTrigger, t), PlayerAnimationFrameTransform.Interpolate(lhs.RightHand, rhs.RightHand, t), Mathf.Lerp(lhs.RightHandTrigger, rhs.RightHandTrigger, t), PlayerAnimationFrameTransform.Interpolate(lhs.Head, rhs.Head, t), PlayerAnimationFrameTransform.Interpolate(lhs.Body, rhs.Body, t));
		}

		public static PlayerAnimationFrame Mirror(PlayerAnimationFrame frame)
		{
			return new PlayerAnimationFrame(frame.Time, PlayerAnimationFrameTransform.Mirror(frame.RightHand), frame.RightHandTrigger, PlayerAnimationFrameTransform.Mirror(frame.LeftHand), frame.LeftHandTrigger, PlayerAnimationFrameTransform.Mirror(frame.Head), PlayerAnimationFrameTransform.Mirror(frame.Body));
		}

		public static PlayerAnimationFrame Mask(PlayerAnimationFrame baseFrame, PlayerAnimationFrame layeredFrame, int transformTypeMask)
		{
			float maskInterpolation = GetMaskInterpolation(TransformType.LEFT_HAND, transformTypeMask);
			float maskInterpolation2 = GetMaskInterpolation(TransformType.RIGHT_HAND, transformTypeMask);
			float maskInterpolation3 = GetMaskInterpolation(TransformType.HEAD, transformTypeMask);
			float maskInterpolation4 = GetMaskInterpolation(TransformType.BODY, transformTypeMask);
			return new PlayerAnimationFrame(baseFrame.Time, PlayerAnimationFrameTransform.Interpolate(baseFrame.LeftHand, layeredFrame.LeftHand, maskInterpolation), Mathf.Lerp(baseFrame.LeftHandTrigger, layeredFrame.LeftHandTrigger, maskInterpolation), PlayerAnimationFrameTransform.Interpolate(baseFrame.RightHand, layeredFrame.RightHand, maskInterpolation2), Mathf.Lerp(baseFrame.RightHandTrigger, layeredFrame.RightHandTrigger, maskInterpolation2), PlayerAnimationFrameTransform.Interpolate(baseFrame.Head, layeredFrame.Head, maskInterpolation3), PlayerAnimationFrameTransform.Interpolate(baseFrame.Body, layeredFrame.Body, maskInterpolation4));
		}

		private static float GetMaskInterpolation(TransformType transformType, int mask)
		{
			return (((1 << (int)transformType) & mask) != 0) ? 1f : 0f;
		}
	}
	public class PlayerAnimationAsset : ScriptableObject, IPlayerAnimation
	{
		public static readonly float CANONICAL_HEAD_HEIGHT = 1.6f;

		public static readonly float CANONICAL_SHOULDER_OFFSET = 0.3f;

		public static readonly float CANONICAL_ARM_LENGTH = 0.8f;

		[Header("Frame data")]
		[SerializeField]
		private List<PlayerAnimationFrame> frames = new List<PlayerAnimationFrame>();

		[Header("Event Data")]
		[SerializeField]
		private List<PlayerAnimationEvent> events = new List<PlayerAnimationEvent>();

		[Header("Root Motion Data")]
		[SerializeField]
		private bool useRootMotion;

		[SerializeField]
		private AnimationCurve rootMotionDisplacementCurve;

		public List<PlayerAnimationEvent> Events => events;

		public float Duration => Mathf.Max(EndTime - StartTime, 0.1f);

		public bool UseRootMotion => useRootMotion;

		public float StartTime => (frames.Count <= 0) ? 0f : frames[0].Time;

		public float EndTime => (frames.Count <= 0) ? 0f : frames.LastItem().Time;

		public bool ContainsAnimation(IPlayerAnimation animation)
		{
			PlayerAnimationAsset playerAnimationAsset = animation as PlayerAnimationAsset;
			return playerAnimationAsset == this;
		}

		public PlayerAnimationFrame ReadFrame(float currentTime, bool isMirrored)
		{
			int frameIndex = GetFrameIndex(currentTime);
			int num = frames.Count - 1;
			if (frameIndex >= num)
			{
				return frames[num];
			}
			PlayerAnimationFrame lhs = frames[frameIndex];
			PlayerAnimationFrame rhs = frames[frameIndex + 1];
			float t = Mathf.InverseLerp(lhs.Time, rhs.Time, currentTime);
			PlayerAnimationFrame playerAnimationFrame = PlayerAnimationFrame.Interpolate(lhs, rhs, t);
			if (isMirrored)
			{
				playerAnimationFrame = PlayerAnimationFrame.Mirror(playerAnimationFrame);
			}
			return playerAnimationFrame;
		}

		public float ReadRootMotionDisplacement(float currentTime)
		{
			if (!useRootMotion || rootMotionDisplacementCurve == null)
			{
				return 0f;
			}
			return rootMotionDisplacementCurve.Evaluate(currentTime);
		}

		public void Write(PlayerAnimationFrame frame)
		{
			if (frames.Count > 0)
			{
			}
			frames.Add(frame);
		}

		private int GetFrameIndex(float time)
		{
			if (time <= StartTime)
			{
				return 0;
			}
			if (time >= EndTime)
			{
				return frames.Count - 1;
			}
			int i;
			for (i = Mathf.FloorToInt(Mathf.InverseLerp(StartTime, EndTime, time) * (float)(frames.Count - 1)); i < frames.Count - 1 && frames[i].Time <= time; i++)
			{
			}
			while (i > 0 && frames[i].Time > time)
			{
				i--;
			}
			return i;
		}
	}
	[Serializable]
	public class BlendedPlayerAnimationAssets : IPlayerAnimation
	{
		[Serializable]
		private struct BlendedAnimationData
		{
			public PlayerAnimationAsset Animation;

			public float FullBlendParameter;
		}

		[SerializeField]
		private BlendedAnimationData[] animations;

		private int lowerBlendAnimationIndex = -1;

		private int upperBlendAnimationIndex = -1;

		private float blendAnimationT;

		private List<PlayerAnimationEvent> events;

		public float Duration
		{
			get
			{
				float num = 0f;
				for (int i = 0; i < animations.Length; i++)
				{
					if (!(animations[i].Animation == null))
					{
						float duration = animations[i].Animation.Duration;
						if (duration > num)
						{
							num = duration;
						}
					}
				}
				return num;
			}
		}

		public List<PlayerAnimationEvent> Events
		{
			get
			{
				if (events == null)
				{
					events = new List<PlayerAnimationEvent>();
					for (int i = 0; i < animations.Length; i++)
					{
						events.AddRange(animations[i].Animation.Events);
					}
				}
				return events;
			}
		}

		public bool UseRootMotion
		{
			get
			{
				if (lowerBlendAnimationIndex >= 0 && upperBlendAnimationIndex >= 0)
				{
					return animations[lowerBlendAnimationIndex].Animation.UseRootMotion || animations[upperBlendAnimationIndex].Animation.UseRootMotion;
				}
				if (lowerBlendAnimationIndex >= 0)
				{
					return animations[lowerBlendAnimationIndex].Animation.UseRootMotion;
				}
				if (upperBlendAnimationIndex >= 0)
				{
					return animations[upperBlendAnimationIndex].Animation.UseRootMotion;
				}
				return false;
			}
		}

		public bool ContainsAnimation(IPlayerAnimation animation)
		{
			BlendedPlayerAnimationAssets blendedPlayerAnimationAssets = animation as BlendedPlayerAnimationAssets;
			return blendedPlayerAnimationAssets == this;
		}

		public PlayerAnimationFrame ReadFrame(float currentTime, bool isMirrored)
		{
			if (lowerBlendAnimationIndex >= 0 && upperBlendAnimationIndex >= 0)
			{
				PlayerAnimationFrame lhs = animations[lowerBlendAnimationIndex].Animation.ReadFrame(currentTime, isMirrored);
				PlayerAnimationFrame rhs = animations[upperBlendAnimationIndex].Animation.ReadFrame(currentTime, isMirrored);
				return PlayerAnimationFrame.Interpolate(lhs, rhs, blendAnimationT);
			}
			if (lowerBlendAnimationIndex >= 0)
			{
				return animations[lowerBlendAnimationIndex].Animation.ReadFrame(currentTime, isMirrored);
			}
			if (upperBlendAnimationIndex >= 0)
			{
				return animations[upperBlendAnimationIndex].Animation.ReadFrame(currentTime, isMirrored);
			}
			return default(PlayerAnimationFrame);
		}

		public float ReadRootMotionDisplacement(float currentTime)
		{
			if (lowerBlendAnimationIndex >= 0 && upperBlendAnimationIndex >= 0)
			{
				float a = animations[lowerBlendAnimationIndex].Animation.ReadRootMotionDisplacement(currentTime);
				float b = animations[upperBlendAnimationIndex].Animation.ReadRootMotionDisplacement(currentTime);
				return Mathf.Lerp(a, b, blendAnimationT);
			}
			if (lowerBlendAnimationIndex >= 0)
			{
				return animations[lowerBlendAnimationIndex].Animation.ReadRootMotionDisplacement(currentTime);
			}
			if (upperBlendAnimationIndex >= 0)
			{
				return animations[upperBlendAnimationIndex].Animation.ReadRootMotionDisplacement(currentTime);
			}
			return 0f;
		}

		public void SetTargetAnimation(PlayerAnimationAsset newTargetAnimation)
		{
			if (animations != null && animations.Length > 0)
			{
				animations[animations.Length - 1].Animation = newTargetAnimation;
			}
		}

		public void SetBlendParameter(float blendParameter)
		{
			blendParameter = Mathf.Clamp01(blendParameter);
			lowerBlendAnimationIndex = -1;
			float num = float.MinValue;
			upperBlendAnimationIndex = -1;
			float num2 = float.MaxValue;
			for (int i = 0; i < animations.Length; i++)
			{
				float fullBlendParameter = animations[i].FullBlendParameter;
				if (fullBlendParameter < blendParameter && fullBlendParameter >= num)
				{
					num = fullBlendParameter;
					lowerBlendAnimationIndex = i;
				}
				else if (fullBlendParameter >= blendParameter && fullBlendParameter <= num2)
				{
					num2 = fullBlendParameter;
					upperBlendAnimationIndex = i;
				}
			}
			if (upperBlendAnimationIndex < 0 || lowerBlendAnimationIndex < 0)
			{
				blendAnimationT = 1f;
				return;
			}
			float t = Mathf.InverseLerp(num, num2, blendParameter);
			blendAnimationT = Mathf.SmoothStep(0f, 1f, t);
		}
	}
	public class MaskedPlayerAnimationAssets : IPlayerAnimation
	{
		private struct MaskedAnimation
		{
			public IPlayerAnimation Animation;

			public bool IsMirrored;

			public int TransformMask;
		}

		private MaskedAnimation baseAnimation;

		private List<MaskedAnimation> layeredAnimations = new List<MaskedAnimation>();

		private List<PlayerAnimationEvent> events = new List<PlayerAnimationEvent>();

		public float Duration
		{
			get
			{
				float num = 0f;
				if (baseAnimation.Animation != null)
				{
					num = baseAnimation.Animation.Duration;
				}
				for (int i = 0; i < layeredAnimations.Count; i++)
				{
					if (layeredAnimations[i].Animation != null)
					{
						float duration = layeredAnimations[i].Animation.Duration;
						if (duration > num)
						{
							num = duration;
						}
					}
				}
				return num;
			}
		}

		public List<PlayerAnimationEvent> Events => events;

		public bool UseRootMotion => baseAnimation.Animation.UseRootMotion;

		public bool ContainsAnimation(IPlayerAnimation animation)
		{
			if (animation == this)
			{
				return true;
			}
			for (int i = 0; i < layeredAnimations.Count; i++)
			{
				if (layeredAnimations == animation)
				{
					return true;
				}
			}
			return false;
		}

		public PlayerAnimationFrame ReadFrame(float currentTime, bool isMirrored)
		{
			if (baseAnimation.Animation == null)
			{
				return default(PlayerAnimationFrame);
			}
			PlayerAnimationFrame playerAnimationFrame = baseAnimation.Animation.ReadFrame(currentTime, baseAnimation.IsMirrored);
			for (int i = 0; i < layeredAnimations.Count; i++)
			{
				if (layeredAnimations[i].Animation != null)
				{
					PlayerAnimationFrame layeredFrame = layeredAnimations[i].Animation.ReadFrame(currentTime, layeredAnimations[i].IsMirrored);
					playerAnimationFrame = PlayerAnimationFrame.Mask(playerAnimationFrame, layeredFrame, layeredAnimations[i].TransformMask);
				}
			}
			return playerAnimationFrame;
		}

		public float ReadRootMotionDisplacement(float currentTime)
		{
			return baseAnimation.Animation.ReadRootMotionDisplacement(currentTime);
		}

		public void SetBaseAnimation(IPlayerAnimation animation, bool isMirrored)
		{
			if (animation != null && baseAnimation.Animation != animation)
			{
				baseAnimation.Animation = animation;
				baseAnimation.IsMirrored = isMirrored;
			}
		}

		public void ClearLayeredAnimations()
		{
			layeredAnimations.Clear();
		}

		public void AddLayeredAnimation(IPlayerAnimation animation, bool isMirrored, int transformMask)
		{
			if (animation != null)
			{
				layeredAnimations.Add(new MaskedAnimation
				{
					Animation = animation,
					IsMirrored = isMirrored,
					TransformMask = transformMask
				});
			}
		}
	}
	public class PlayerAnimationEditorPreviewAnimationController : UnityEngine.MonoBehaviour
	{
