		[SerializeField]
		private Transform rightHandTransform;

		[SerializeField]
		private Animator rightHandAnimator;

		private PlayerAnimationSystem animationSystem;

		private List<PlayerAnimationEvent.AnimationEventType> animationEvents = new List<PlayerAnimationEvent.AnimationEventType>();

