	public class PlayerAnimationCalibrationData
	{
		public float HeadHeight;

		public float ShoulderOffset;

		public float ArmLength;

		public float HeadToArmLength;
	}
	public static class PlayerAnimationRecording
	{
		public struct AnimationRecordingData
		{
			public PlayerAnimationAsset AnimationAsset;

			public string Name;

			public string Filepath;
		}

		private const float DEFAULT_FRAME_PERIOD = 0.1f;

		public static List<AnimationRecordingData> StaticLatestRecordings = new List<AnimationRecordingData>();

		private static ISchedulerPromise recordingPromise = null;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action m_AnimationRecordedEvent;

		public static bool HasCalibrationData => CalibrationData != null;

		public static PlayerAnimationCalibrationData CalibrationData { get; private set; }

		public static event Action AnimationRecordedEvent
		{
			add
			{
				Action action = PlayerAnimationRecording.m_AnimationRecordedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref PlayerAnimationRecording.m_AnimationRecordedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = PlayerAnimationRecording.m_AnimationRecordedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref PlayerAnimationRecording.m_AnimationRecordedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public static void StartRecording(Player player, string animationName, bool automatePosition, bool automateRotation, AnimationCurve armScaleCurve)
		{
			if (!IsRecordingRunning() && CalibrationData != null)
			{
				PlayerAnimationAsset asset = ScriptableObject.CreateInstance<PlayerAnimationAsset>();
				recordingPromise = SingletonMonoBehaviour<Scheduler>.Instance.Run(RecordAnimationCoroutine(asset, player, CalibrationData, automatePosition, automateRotation, armScaleCurve));
				recordingPromise.Finally(delegate
				{
					ExportRecordedAnimation(asset, animationName);
				});
			}
		}

		public static bool IsRecordingRunning()
		{
			return recordingPromise != null && !recordingPromise.IsCompleted;
		}

		public static void StopRecording()
		{
			if (IsRecordingRunning())
			{
				recordingPromise.Cancel();
				recordingPromise = null;
			}
		}

		public static void DeleteLastAnimation()
		{
			if (StaticLatestRecordings.Count > 0)
			{
				int index = StaticLatestRecordings.Count - 1;
				StaticLatestRecordings.RemoveAt(index);
			}
		}

		public static void ClearCalibrationData()
		{
			CalibrationData = null;
		}

		public static void ClearStaticRecordedAnimationData()
		{
			StaticLatestRecordings.Clear();
		}

		public static void UpdateCalibrationData(Player player)
		{
			Vector3 targetLocalPosition = player.RightHand.RigidbodyEx.targetLocalPosition;
			Vector3 targetLocalPosition2 = player.LeftHand.RigidbodyEx.targetLocalPosition;
			Vector3 vector = targetLocalPosition - targetLocalPosition2;
			float num = (targetLocalPosition.y + targetLocalPosition2.y) / 2f;
			float armLength = Vector3.ProjectOnPlane(vector, Vector3.up).magnitude / 2f;
			Vector3 targetLocalPosition3 = player.Head.RigidbodyEx.targetLocalPosition;
			float magnitude = Vector3.Project(targetLocalPosition3, Vector3.up).magnitude;
			float shoulderOffset = Mathf.Abs(magnitude - num);
			PlayerAnimationCalibrationData playerAnimationCalibrationData = new PlayerAnimationCalibrationData();
			playerAnimationCalibrationData.HeadHeight = magnitude;
			playerAnimationCalibrationData.ShoulderOffset = shoulderOffset;
			playerAnimationCalibrationData.ArmLength = armLength;
			CalibrationData = playerAnimationCalibrationData;
		}

		private static IEnumerator<ISchedule> RecordAnimationCoroutine(PlayerAnimationAsset asset, Player player, PlayerAnimationCalibrationData calibrationData, bool offsetPosition, bool offsetRotation, AnimationCurve armScaleCurve)
		{
			float recordingStartTime = UnityEngine.Time.time;
			GetPlayerRecordingOffset(player, offsetPosition, offsetRotation, out var linearRecordingOffset, out var angularRecordingOffset);
			ISchedule period = Schedule.Wait(0.1f);
			while (true)
			{
				float timeElapsed = UnityEngine.Time.time - recordingStartTime;
				asset.Write(RecordPlayerAnimationTransformFrame(player, timeElapsed, linearRecordingOffset, angularRecordingOffset, calibrationData, armScaleCurve));
				yield return period;
			}
		}

		private static void GetPlayerRecordingOffset(Player player, bool offsetPosition, bool offsetRotation, out Vector3 linearOffset, out float angularOffset)
		{
			linearOffset = Vector3.zero;
			if (offsetPosition)
			{
				Vector3 targetLocalPosition = player.Head.RigidbodyEx.targetLocalPosition;
				linearOffset = Vector3.ProjectOnPlane(-1f * targetLocalPosition, Vector3.up);
			}
			angularOffset = 0f;
			if (offsetRotation)
			{
				Vector3 vector = player.Head.RigidbodyEx.targetLocalRotation * Vector3.forward;
				Vector3 vector2 = Vector3.ProjectOnPlane(vector, Vector3.up);
				angularOffset = Vector3.SignedAngle(vector2, Vector3.forward, Vector3.up);
			}
		}

		private static PlayerAnimationFrame RecordPlayerAnimationTransformFrame(Player player, float timeElapsed, Vector3 linearRecordingOffset, float angularRecordingOffset, PlayerAnimationCalibrationData calibrationData, AnimationCurve armScaleCurve)
		{
			Quaternion angularOffset = Quaternion.Euler(0f, angularRecordingOffset, 0f);
			Vector3 rawBodyPartPosition = GetRawBodyPartPosition(player.Head.RigidbodyEx, linearRecordingOffset, angularOffset);
			Vector3 position = ScaleSpinePosition(rawBodyPartPosition, calibrationData.HeadHeight, PlayerAnimationAsset.CANONICAL_HEAD_HEIGHT);
			Quaternion bodyPartRotation = GetBodyPartRotation(player.Head.RigidbodyEx, angularOffset);
			Vector3 vector = rawBodyPartPosition - Vector3.up * calibrationData.ShoulderOffset;
			Vector3 shoulderPositionScaled = ScaleSpinePosition(vector, calibrationData.HeadHeight, PlayerAnimationAsset.CANONICAL_HEAD_HEIGHT);
			Vector3 rawBodyPartPosition2 = GetRawBodyPartPosition(player.LeftHand.RigidbodyEx, linearRecordingOffset, angularOffset);
			Vector3 position2 = ScaleHandPosition(rawBodyPartPosition2, vector, shoulderPositionScaled, calibrationData.ArmLength, PlayerAnimationAsset.CANONICAL_ARM_LENGTH, armScaleCurve);
			Quaternion bodyPartRotation2 = GetBodyPartRotation(player.LeftHand.RigidbodyEx, angularOffset);
			Vector3 rawBodyPartPosition3 = GetRawBodyPartPosition(player.RightHand.RigidbodyEx, linearRecordingOffset, angularOffset);
			Vector3 position3 = ScaleHandPosition(rawBodyPartPosition3, vector, shoulderPositionScaled, calibrationData.ArmLength, PlayerAnimationAsset.CANONICAL_ARM_LENGTH, armScaleCurve);
			Quaternion bodyPartRotation3 = GetBodyPartRotation(player.RightHand.RigidbodyEx, angularOffset);
			Vector3 localPosition = player.TrackingSpace.transform.InverseTransformPoint(player.Body.transform.position);
			Quaternion localRotation = player.TrackingSpace.transform.InverseTransformRotation(player.Body.transform.rotation);
			Vector3 rawBodyPartPosition4 = GetRawBodyPartPosition(localPosition, linearRecordingOffset, angularOffset);
			Vector3 position4 = ScaleSpinePosition(rawBodyPartPosition4, calibrationData.HeadHeight, PlayerAnimationAsset.CANONICAL_HEAD_HEIGHT);
			Quaternion bodyPartRotation4 = GetBodyPartRotation(localRotation, angularOffset);
			return new PlayerAnimationFrame(timeElapsed, new PlayerAnimationFrameTransform(position2, bodyPartRotation2), player.LeftHand.OpenClosedAxis, new PlayerAnimationFrameTransform(position3, bodyPartRotation3), player.RightHand.OpenClosedAxis, new PlayerAnimationFrameTransform(position, bodyPartRotation), new PlayerAnimationFrameTransform(position4, bodyPartRotation4));
		}

		private static Vector3 GetRawBodyPartPosition(Vector3 localPosition, Vector3 linearOffset, Quaternion angularOffset)
		{
			return angularOffset * (localPosition + linearOffset);
		}

		private static Vector3 GetRawBodyPartPosition(RigidbodyEx rigidbodyEx, Vector3 linearOffset, Quaternion angularOffset)
		{
			return angularOffset * (rigidbodyEx.targetLocalPosition + linearOffset);
		}

		private static Quaternion GetBodyPartRotation(Quaternion localRotation, Quaternion angularOffset)
		{
			return angularOffset * localRotation;
		}

		private static Quaternion GetBodyPartRotation(RigidbodyEx rigidbodyEx, Quaternion angularOffset)
		{
			return angularOffset * rigidbodyEx.targetLocalRotation;
		}

		private static Vector3 ScaleHandPosition(Vector3 handPositionRaw, Vector3 shoulderPositionRaw, Vector3 shoulderPositionScaled, float calibrationArmLength, float canonicalArmLength, AnimationCurve scaleCurve)
		{
			Vector3 vector = handPositionRaw - shoulderPositionRaw;
			float magnitude = vector.magnitude;
			if (magnitude <= 0.0001f)
			{
				return handPositionRaw;
			}
			float time = Mathf.InverseLerp(0f, calibrationArmLength, magnitude);
			float b = canonicalArmLength / calibrationArmLength;
			float t = scaleCurve.Evaluate(time);
			float num = Mathf.Lerp(1f, b, t);
			return shoulderPositionScaled + vector * num;
		}

		private static Vector3 ScaleSpinePosition(Vector3 positionRaw, float calibrationHeadHeight, float canonicalHeadHeight)
		{
			Vector3 vector = Vector3.Project(positionRaw, Vector3.up);
			Vector3 vector2 = positionRaw - vector;
			float num = canonicalHeadHeight / calibrationHeadHeight;
			Vector3 vector3 = vector * num;
			return vector3 + vector2;
		}

		private static void ExportRecordedAnimation(PlayerAnimationAsset asset, string name)
		{
			DateTime now = DateTime.Now;
			AnimationRecordingData item = new AnimationRecordingData
			{
				AnimationAsset = asset,
				Name = $"{name}_Take_{now.Hour}{now.Minute}{now.Second}",
				Filepath = null
			};
			StaticLatestRecordings.Add(item);
			if (PlayerAnimationRecording.AnimationRecordedEvent != null)
			{
				PlayerAnimationRecording.AnimationRecordedEvent();
			}
		}

		static PlayerAnimationRecording()
		{
			PlayerAnimationRecording.AnimationRecordedEvent = null;
		}
	}
