	public class PlayerAnimationSystem
	{
		public delegate void ApplyPlayerAnimation(PlayerAnimationFrame frame, float rootMotionDisplacement);

		private struct TimestampedRuntimeAnimation
		{
			public RuntimeAnimation RuntimeAnimation;

			public float TimeElapsed;

			public float FadeDuration;
		}

		private class RuntimeAnimation
		{
			private bool hasPreviousFrame;

			private PlayerAnimationFrame previousFrame;

			private float previousRootMotionDisplacement;

			public float PlaySpeed = 1f;

			private readonly IPlayerAnimation animation;

			private readonly bool isMirrored;

			private readonly bool[] firedEvents;

			public float NormalizedTime { get; set; }

			public IPlayerAnimation Animation => animation;

			public bool IsMirrored => isMirrored;

			public float RemainingTime
			{
				get
				{
					float num = Mathf.Clamp01(1f - NormalizedTime);
					return num * animation.Duration;
				}
			}

			public RuntimeAnimation(IPlayerAnimation animation, float playSpeed, bool isMirrored)
			{
				this.animation = animation;
				if (this.animation != null)
				{
					firedEvents = new bool[this.animation.Events.Count];
				}
				else
				{
					firedEvents = new bool[0];
				}
				PlaySpeed = playSpeed;
				this.isMirrored = isMirrored;
				NormalizedTime = 0f;
			}

			public PlayerAnimationFrame Update(float deltaTime, List<PlayerAnimationEvent.AnimationEventType> eventsOut, out Vector3 leftHandVelocity, out Vector3 rightHandVelocity, out float rootMotionDisplacement)
			{
				leftHandVelocity = Vector3.zero;
				rightHandVelocity = Vector3.zero;
				deltaTime *= PlaySpeed;
				float duration = animation.Duration;
				NormalizedTime += deltaTime / duration;
				float num = NormalizedTime * duration;
				for (int i = 0; i < animation.Events.Count; i++)
				{
					if (!firedEvents[i] && animation.Events[i].EventType != PlayerAnimationEvent.AnimationEventType.NONE && animation.Events[i].Time <= num)
					{
						firedEvents[i] = true;
						eventsOut.Add(animation.Events[i].EventType);
					}
				}
				PlayerAnimationFrame result = animation.ReadFrame(num, isMirrored);
				if (hasPreviousFrame)
				{
					leftHandVelocity = (result.LeftHand.Position - previousFrame.LeftHand.Position) / deltaTime;
					rightHandVelocity = (result.RightHand.Position - previousFrame.RightHand.Position) / deltaTime;
				}
				if (animation.UseRootMotion)
				{
					if (!hasPreviousFrame)
					{
						previousRootMotionDisplacement = 0f;
					}
					float num2 = animation.ReadRootMotionDisplacement(NormalizedTime);
					rootMotionDisplacement = num2 - previousRootMotionDisplacement;
					previousRootMotionDisplacement = num2;
				}
				else
				{
					rootMotionDisplacement = 0f;
				}
				hasPreviousFrame = true;
				previousFrame = result;
				return result;
			}
		}

		private RuntimeAnimation activeAnimation;

		private List<TimestampedRuntimeAnimation> fadingOutAnimations = new List<TimestampedRuntimeAnimation>();

		private List<int> _fadingAnimIndicesToRemove = new List<int>();

		private bool activeAnimationLoops;

		private float loopFadeDuration;

		public void CrossFade(IPlayerAnimationData animation, bool loops, bool restartIfAlreadyPlaying = false)
		{
			if (animation != null)
			{
				CrossFade(animation.GetAnimation(), animation.GetFadeInTime(), loops, animation.GetLoopFadeTime(), animation.GetIsMirrored(), animation.GetPlaySpeed(), restartIfAlreadyPlaying);
			}
		}

		public void CrossFade(IPlayerAnimation animation, float fadeTime, bool loops, float loopFadeTime, bool isMirrored = false, float playSpeed = 1f, bool restartIfAlreadyPlaying = false)
		{
			if (animation == null)
			{
				return;
			}
			if (activeAnimation != null && activeAnimation.Animation.ContainsAnimation(animation) && !restartIfAlreadyPlaying)
			{
				activeAnimationLoops = loops;
				loopFadeDuration = loopFadeTime;
				activeAnimation.PlaySpeed = playSpeed;
				return;
			}
			if (activeAnimation != null && fadeTime >= Mathf.Epsilon)
			{
				fadingOutAnimations.Add(new TimestampedRuntimeAnimation
				{
					RuntimeAnimation = activeAnimation,
					TimeElapsed = 0f,
					FadeDuration = Mathf.Min(fadeTime, activeAnimation.RemainingTime)
				});
			}
			activeAnimation = new RuntimeAnimation(animation, playSpeed, isMirrored);
			activeAnimationLoops = loops;
		}

		public void OnUpdate(ApplyPlayerAnimation applyAnimation, float deltaTime, List<PlayerAnimationEvent.AnimationEventType> eventsOut, out Vector3 leftHandVelocity, out Vector3 rightHandVelocity)
		{
			leftHandVelocity = Vector3.zero;
			rightHandVelocity = Vector3.zero;
			eventsOut.Clear();
			if (activeAnimation == null || applyAnimation == null)
			{
				return;
			}
			Vector3 leftHandVelocity2;
			Vector3 rightHandVelocity2;
			float rootMotionDisplacement;
			PlayerAnimationFrame playerAnimationFrame = activeAnimation.Update(deltaTime, eventsOut, out leftHandVelocity2, out rightHandVelocity2, out rootMotionDisplacement);
			if (fadingOutAnimations.Count == 0)
			{
				applyAnimation(playerAnimationFrame, rootMotionDisplacement);
				leftHandVelocity = leftHandVelocity2;
				rightHandVelocity = rightHandVelocity2;
				if (activeAnimationLoops && activeAnimation.RemainingTime <= loopFadeDuration)
				{
					CrossFade(activeAnimation.Animation, loopFadeDuration, loops: true, loopFadeDuration, activeAnimation.IsMirrored, activeAnimation.PlaySpeed, restartIfAlreadyPlaying: true);
				}
				return;
			}
			_fadingAnimIndicesToRemove.Clear();
			float blendT = 0f;
			UpdateFadingAnimation(0, deltaTime, eventsOut, out var frame, out var leftHandVelocity3, out var rightHandVelocity3, out var rootMotionDisplacement2, out blendT);
			for (int i = 1; i < fadingOutAnimations.Count; i++)
			{
				float blendT2 = 0f;
				UpdateFadingAnimation(i, deltaTime, eventsOut, out var frame2, out var leftHandVelocity4, out var rightHandVelocity4, out var rootMotionDisplacement3, out blendT2);
				frame = PlayerAnimationFrame.Interpolate(frame, frame2, blendT);
				rootMotionDisplacement2 = Mathf.Lerp(rootMotionDisplacement2, rootMotionDisplacement3, blendT);
				leftHandVelocity3 = Vector3.Lerp(leftHandVelocity3, leftHandVelocity4, blendT);
				rightHandVelocity3 = Vector3.Lerp(rightHandVelocity3, rightHandVelocity4, blendT);
				blendT = blendT2;
			}
			frame = PlayerAnimationFrame.Interpolate(frame, playerAnimationFrame, blendT);
			rootMotionDisplacement2 = Mathf.Lerp(rootMotionDisplacement2, rootMotionDisplacement, blendT);
			leftHandVelocity = Vector3.Lerp(leftHandVelocity3, leftHandVelocity2, blendT);
			rightHandVelocity = Vector3.Lerp(rightHandVelocity3, rightHandVelocity2, blendT);
			applyAnimation(frame, rootMotionDisplacement2);
			if (blendT >= 0.9999f)
			{
				fadingOutAnimations.Clear();
				return;
			}
			for (int num = _fadingAnimIndicesToRemove.Count - 1; num >= 0; num--)
			{
				fadingOutAnimations.RemoveAt(_fadingAnimIndicesToRemove[num]);
			}
		}

		public bool IsAnimationPlaying(IPlayerAnimationData animation)
		{
			return IsAnimationPlaying(animation.GetAnimation(), animation.GetFadeOutTime());
		}

		public bool IsAnimationPlaying(IPlayerAnimation animation, float fadeOutTime)
		{
			return activeAnimation != null && activeAnimation.Animation == animation && activeAnimation.RemainingTime > fadeOutTime;
		}

		public float GetActiveAnimationNormalizedTimeElapsed()
		{
			return (activeAnimation == null) ? 0f : activeAnimation.NormalizedTime;
		}

		public bool IsActiveAnimationFading()
		{
			return fadingOutAnimations.Count > 0;
		}

		private void UpdateFadingAnimation(int index, float deltaTime, List<PlayerAnimationEvent.AnimationEventType> eventsOut, out PlayerAnimationFrame frame, out Vector3 leftHandVelocity, out Vector3 rightHandVelocity, out float rootMotionDisplacement, out float blendT)
		{
			TimestampedRuntimeAnimation value = fadingOutAnimations[index];
			frame = value.RuntimeAnimation.Update(deltaTime, eventsOut, out leftHandVelocity, out rightHandVelocity, out rootMotionDisplacement);
			float num = 1f;
			if (value.FadeDuration > 0f)
			{
				num = Mathf.InverseLerp(0f, value.FadeDuration, value.TimeElapsed);
			}
			blendT = Mathf.SmoothStep(0f, 1f, num);
			if (num >= 1f)
			{
				_fadingAnimIndicesToRemove.Add(index);
				return;
			}
			value.TimeElapsed += deltaTime;
			fadingOutAnimations[index] = value;
		}
	}
}
