public class AvatarColor : UnityEngine.MonoBehaviour
{
	public enum ColorType
	{
		Skin,
		Hair,
		Beard
	}

	public static List<AvatarColor> All = new List<AvatarColor>();

	[Tooltip("Matching guid value from the OutfitManager Color Vault")]
	public string GuidString = string.Empty;

	public ColorType Type = ColorType.Hair;

	private UnityEngine.UI.Image image;

	[SerializeField]
	[Autofill(AutofillType.SelfAndParent, false)]
	private Outline outline;

	private bool _selected;

	public Color Color { get; private set; }

	public bool Selected
	{
		get
		{
			return _selected;
		}
		private set
		{
			if (_selected != value)
			{
				_selected = value;
				RefreshSelectedVisuals();
			}
		}
	}

	private void Awake()
	{
		RefreshSelectedVisuals();
	}

	private IEnumerator Start()
	{
		ColorVault vault = ((Type != ColorType.Skin) ? NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.HairColorVault : NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SkinColorVault);
		ColorVault.ColorToGuid colorToGuid = vault.Find(GuidString);
		if (colorToGuid != null)
		{
			Color = colorToGuid.color;
			image = GetComponent<UnityEngine.UI.Image>();
			if (image != null)
			{
				image.color = Color;
				All.Add(this);
			}
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat(this, " has an invalid color guid '", GuidString, ". Check to make sure you have the exact matching guid from the OutfitManager."));
			base.gameObject.SetActive(value: false);
		}
		while (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerOutfit == null || Player.LocalPlayer.PlayerOutfit.HairColor == null || Player.LocalPlayer.PlayerOutfit.BeardColor == null || Player.LocalPlayer.PlayerOutfit.SkinColor == null)
		{
			yield return null;
		}
		if (image != null && Player.LocalPlayerExists)
		{
			ColorVault.ColorToGuid colorToGuid2 = null;
			switch (Type)
			{
			case ColorType.Hair:
				colorToGuid2 = Player.LocalPlayer.PlayerOutfit.HairColor;
				break;
			case ColorType.Skin:
				colorToGuid2 = Player.LocalPlayer.PlayerOutfit.SkinColor;
				break;
			case ColorType.Beard:
				colorToGuid2 = Player.LocalPlayer.PlayerOutfit.BeardColor;
				break;
			}
			Selected = colorToGuid2 != null && colorToGuid2.guidString == GuidString;
		}
	}

	private void OnDestroy()
	{
		if (All != null && image != null)
		{
			All.Remove(this);
		}
	}

	private void RefreshSelectedVisuals()
	{
		if (outline != null)
		{
			outline.enabled = _selected;
		}
	}

	public static void SetSelected(ColorType type, ColorVault.ColorToGuid colorToGuid)
	{
		foreach (AvatarColor item in All)
		{
			if (item.Type == type)
			{
				item.Selected = item.GuidString == colorToGuid.guidString;
			}
		}
	}
}
[CreateAssetMenu(menuName = "RecRoom/Avatar/Color Swatch", fileName = "AvatarColorSwatch")]
public class AvatarColorSwatch : AvatarSelectionElement
{
	public static List<AvatarColorSwatch> All = new List<AvatarColorSwatch>();

	public Color ColorBase = Color.white;

	public Color ColorR = Color.white;

	public Color ColorG = Color.white;

	public Color ColorB = Color.white;

	public Color ColorDirt = Color.white;

	public bool AddDirt;

	public Color ColorDecal = Color.white;

	public Color ColorEmission = Color.white;

	private const string matDirtColName = "_Dirt_Col";

	private const string matDirtAddName = "_Dirt_Add";

	private const string matBaseColName = "_Base_Col";

	private const string matRedColName = "_Red_Col";

	private const string matGreenColName = "_Green_Col";

	private const string matBlueColName = "_Blue_Col";

	private const string matDecalColName = "_Decal_Col";

	private const string matEmissionColName = "_Emission_Col";

	public AvatarColorSwatch()
	{
		All.Add(this);
	}

	~AvatarColorSwatch()
	{
		if (All.Contains(this))
		{
			All.Remove(this);
		}
	}

	public static void Apply(AvatarColorSwatch swatch, Material mat, Material defaultMat = null)
	{
		if (swatch != null)
		{
			mat.SetColor("_Base_Col", swatch.ColorBase);
			mat.SetColor("_Red_Col", swatch.ColorR);
			mat.SetColor("_Green_Col", swatch.ColorG);
			mat.SetColor("_Blue_Col", swatch.ColorB);
			mat.SetColor("_Dirt_Col", swatch.ColorDirt);
			mat.SetInt("_Dirt_Add", swatch.AddDirt ? 1 : 0);
			mat.SetColor("_Decal_Col", swatch.ColorDecal);
			mat.SetColor("_Emission_Col", swatch.ColorEmission);
		}
		else if (defaultMat != null)
		{
			mat.SetColor("_Base_Col", defaultMat.GetColor("_Base_Col"));
			mat.SetColor("_Red_Col", defaultMat.GetColor("_Red_Col"));
			mat.SetColor("_Green_Col", defaultMat.GetColor("_Green_Col"));
			mat.SetColor("_Blue_Col", defaultMat.GetColor("_Blue_Col"));
			mat.SetColor("_Dirt_Col", defaultMat.GetColor("_Dirt_Col"));
			mat.SetInt("_Dirt_Add", defaultMat.GetInt("_Dirt_Add"));
