public class ClockFace : UnityEngine.MonoBehaviour
{
	private enum RotationAxis
	{
		X,
		Y,
		Z
	}

	[SerializeField]
	private Transform secondHand;

	[SerializeField]
	private Transform minuteHand;

	[SerializeField]
	private Transform hourHand;

	[Header("Configuration")]
	[SerializeField]
	private RotationAxis localRotationAxis = RotationAxis.Z;

	[SerializeField]
	private bool rotateClockwise = true;

	private DateTime startingLocalTime;

	private float startingAppTime;

	private float lastUpdateAppTime;

	private static readonly Vector3[] RotationAxisMasks = new Vector3[3]
	{
		Vector3.right,
		Vector3.up,
		Vector3.forward
	};

	private bool HandsActive
	{
		set
		{
			secondHand.gameObject.SetActive(value);
			minuteHand.gameObject.SetActive(value);
			hourHand.gameObject.SetActive(value);
		}
	}

	private Vector3 RotationMask => RotationAxisMasks[(int)localRotationAxis];

	private float AngleSign => (!rotateClockwise) ? 1f : (-1f);

	private void OnEnable()
	{
		HandsActive = true;
	}

	private void OnDisable()
	{
		HandsActive = false;
	}

	private void Start()
	{
		startingLocalTime = DateTime.Now;
		startingAppTime = UnityEngine.Time.realtimeSinceStartup;
	}

	private void Update()
	{
		float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
		if (!(realtimeSinceStartup - lastUpdateAppTime < 1f))
		{
			lastUpdateAppTime = realtimeSinceStartup;
			DateTime dateTime = startingLocalTime.AddSeconds(realtimeSinceStartup - startingAppTime);
			int num = dateTime.Second % 60;
			secondHand.localRotation = GetHandRotation(num, 60f);
			float num2 = (float)(dateTime.Minute % 60) + (float)num / 60f;
			minuteHand.localRotation = GetHandRotation(num2, 60f);
			float timeValue = (float)(dateTime.Hour % 12) + num2 / 60f;
			hourHand.localRotation = GetHandRotation(timeValue, 12f);
		}
	}

	private Quaternion GetHandRotation(float timeValue, float maxTimeValue)
	{
		float num = Mathf.InverseLerp(0f, maxTimeValue, timeValue);
		Vector3 euler = RotationMask * num * 360f * AngleSign;
		return Quaternion.Euler(euler);
	}
}
public class ColorVault : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ColorToGuid
	{
		public string guidString;

		public Color color;
	}

	[Tooltip("Used only for decorative purposes.")]
	public string Label = "My Vault";

	public List<ColorToGuid> Colors;

	private Dictionary<string, ColorToGuid> colorMap = new Dictionary<string, ColorToGuid>();

	protected virtual void Awake()
	{
		foreach (ColorToGuid color in Colors)
		{
			if (colorMap.ContainsKey(color.guidString))
			{
				UnityEngine.Debug.LogError(string.Concat(this, " vault has duplicate guid for colors : ", color.guidString));
			}
			else
			{
				colorMap.Add(color.guidString, color);
			}
		}
	}

	public ColorToGuid Find(string guidStr)
	{
		if (colorMap.ContainsKey(guidStr))
		{
			return colorMap[guidStr];
		}
		return null;
	}

	public virtual ColorToGuid GetRandom()
	{
		return Colors.Random();
	}
}
public class EquipmentSpawner : UnityEngine.MonoBehaviour
{
	[Header("Drawers")]
	public List<SpawnedEquipmentDrawer> Drawers;

	public SpawnedEquipmentDrawer TutorialDrawer;

	[SerializeField]
	private SpawnedEquipmentDrawer defaultOutfitDrawer;

	[SerializeField]
	private SpawnedEquipmentDrawer defaultEquipmentDrawer;

	[SerializeField]
	private bool supportsOutfits = true;

	[SerializeField]
	private bool supportsEquipments = true;

	[Header("UI")]
	public Transform DrawersMenu;

	[Header("Audio")]
	public RecRoomAudioClip openDrawer;

	public RecRoomAudioClip pagingSound;

	[Header("Debug")]
	[Tooltip("For art testing in editor")]
	public bool DebugLoadAllOutfits;

	[Header("Changing Area")]
	[SerializeField]
	private Transform changingAreaCenter;

	[SerializeField]
	private float changingAreaRadius = 2f;

	[Header("Equipment Selection")]
	[SerializeField]
	private EquipmentFavoriteUI equipmentFavoriteUI;

	private bool waitingOnSpawns;

	public int DrawerCount => Drawers.Count;

	private void Awake()
	{
		Canvas componentInChildren = GetComponentInChildren<Canvas>(includeInactive: true);
		if (componentInChildren != null && UIInputModule.Instance != null)
		{
			componentInChildren.worldCamera = UIInputModule.Instance.ControllerCamera;
		}
	}

	private IEnumerator Start()
	{
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		yield return null;
		yield return null;
		StartCoroutine(RunInitializeEquipments());
		foreach (SpawnedEquipmentDrawer drawer in Drawers)
		{
			if (drawer != null)
			{
				drawer.SelectButton.interactable = true;
				drawer.PagingSound = pagingSound;
				drawer.SpawnerParent = this;
				if (equipmentFavoriteUI != null)
				{
					drawer.DrawerSelected = (Action<bool>)Delegate.Combine(drawer.DrawerSelected, new Action<bool>(Drawer_DrawerSelected));
				}
			}
		}
	}

	private void Drawer_DrawerSelected(bool isSelected)
	{
		equipmentFavoriteUI.Visible = SpawnedEquipmentDrawer.SelectedDrawer != null && SpawnedEquipmentDrawer.SelectedDrawer.SpawnerParent.supportsEquipments;
	}

	private void OnDestroy()
	{
		if (NetworkedSingletonMonoBehaviour<OutfitManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitSelectionUnlocked -= OutfitManager_OutfitSelectionUnlocked;
		}
		if (NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.NewEquipmentUnlocked -= EquipmentManager_NewEquipmentUnlocked;
		}
	}

	private void OutfitManager_OutfitSelectionUnlocked(OutfitSelection selection)
	{
		OutfitTool outfitTool = OutfitTool.LocalFind(selection, PlayerSpawnedEquipment.Purpose.Drawer);
		if (outfitTool == null)
		{
			OutfitTool outfitTool2 = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitToolForLocalPlayer(selection, PlayerSpawnedEquipment.Purpose.Drawer, null);
			if (outfitTool2 != null && outfitTool2.Tool != null)
			{
				Equipment_ToolSpawned(outfitTool2.Tool);
			}
		}
	}

	private void EquipmentManager_NewEquipmentUnlocked(Equipment equipment)
	{
		Tool tool = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.LocalFind(equipment, PlayerSpawnedEquipment.Purpose.Drawer);
		if (tool == null)
		{
			tool = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentForLocalPlayer(equipment, new Vector3(0f, -60f, 0f), Quaternion.identity, 1f, PlayerSpawnedEquipment.Purpose.Drawer, null);
			if (tool != null)
			{
				Equipment_ToolSpawned(tool);
			}
		}
	}

	private IEnumerator RunInitializeEquipments()
	{
		while (!NetworkedSingletonMonoBehaviour<OutfitManager>.IsInitialized || !NetworkedSingletonMonoBehaviour<EquipmentManager>.IsInitialized || !Player.LocalPlayerExists)
		{
			yield return null;
		}
		waitingOnSpawns = true;
		if (supportsOutfits)
		{
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitSelectionUnlocked += OutfitManager_OutfitSelectionUnlocked;
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.UnlockedOutfitSelections.Sort();
			int count = 0;
			foreach (OutfitSelection selection in NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.UnlockedOutfitSelections)
			{
				if (selection != null && selection.outfitItem != null && selection.outfitItem.DropableItem)
				{
					OutfitTool outfit = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitToolForLocalPlayer(selection, PlayerSpawnedEquipment.Purpose.Drawer, null, selection.IsPlatformLocked);
					if (outfit != null && outfit.Tool != null)
					{
						Equipment_ToolSpawned(outfit.Tool);
					}
					int num;
					count = (num = count + 1);
					if (num % 5 == 0)
					{
						yield return null;
					}
				}
			}
		}
		if (supportsEquipments)
		{
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.NewEquipmentUnlocked += EquipmentManager_NewEquipmentUnlocked;
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.UnlockedEquipments.Sort();
			foreach (Equipment equipment in NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.UnlockedEquipments)
			{
				Tool tool = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentForLocalPlayer(equipment, new Vector3(0f, -60f, 0f), Quaternion.identity, 1f, PlayerSpawnedEquipment.Purpose.Drawer, null);
				if (tool != null)
				{
					Equipment_ToolSpawned(tool);
				}
				yield return null;
			}
		}
		waitingOnSpawns = false;
		StartCoroutine(UpdateAllDrawerPlacements());
	}

	public void InitializeTutorialOutfits()
	{
		TutorialDrawer.SelectButton.gameObject.SetActive(value: true);
		foreach (OutfitSelection tutorialOutfit in NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.TutorialOutfits)
		{
			if (tutorialOutfit != null && tutorialOutfit.outfitItem != null && tutorialOutfit.outfitItem.DropableItem)
			{
				OutfitTool outfitTool = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitToolForLocalPlayer(tutorialOutfit, PlayerSpawnedEquipment.Purpose.Drawer, null);
				if (outfitTool != null && outfitTool.Tool != null)
				{
					outfitTool.Tool.SuppressAnimateInOut = true;
					outfitTool.Tool.IsEnabled = false;
					TutorialDrawer.AddTool(outfitTool.Tool);
				}
			}
		}
		TutorialDrawer.UpdateEquipmentPlacement();
	}

	public void SelectDrawer(int drawerIndex)
	{
		for (int i = 0; i < Drawers.Count; i++)
		{
			if (drawerIndex == i && Drawers[i].SelectButton.interactable)
			{
				SetDrawerSelected(Drawers[i], isSelected: true);
				return;
			}
		}
		SetDrawerSelected(TutorialDrawer, isSelected: true);
	}

	public void DeselectDrawer(int drawerIndex)
	{
		for (int i = 0; i < Drawers.Count; i++)
		{
			if (drawerIndex == i && Drawers[i].SelectButton.interactable)
			{
				SetDrawerSelected(Drawers[i], isSelected: false);
				return;
			}
		}
		SetDrawerSelected(TutorialDrawer, isSelected: false);
	}

	public string GetDrawerName(int drawerIndex)
	{
		if (drawerIndex >= 0 && drawerIndex < Drawers.Count && Drawers[drawerIndex] != null)
		{
			return Drawers[drawerIndex].FriendlyName;
		}
		return null;
	}

	private void Equipment_ToolSpawned(Tool tool)
	{
		PlayerSpawnedEquipment.Purpose purpose = ((tool.PlayerSpawnedEquipment != null) ? tool.PlayerSpawnedEquipment.ToolPurpose : PlayerSpawnedEquipment.Purpose.None);
		if (purpose != PlayerSpawnedEquipment.Purpose.Drawer)
		{
			return;
		}
		SpawnedEquipmentDrawer drawer = GetDrawer(tool);
		if (drawer != null)
		{
			tool.SuppressAnimateInOut = true;
			tool.IsEnabled = false;
			drawer.AddTool(tool);
			if (!waitingOnSpawns)
			{
				drawer.UpdateEquipmentPlacement();
			}
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat("Missing Drawer for Tool : ", tool, ".\nMake sure you have the correct drawer types or names."));
		}
	}

	private IEnumerator UpdateAllDrawerPlacements()
	{
		foreach (SpawnedEquipmentDrawer d in Drawers)
		{
			d.UpdateEquipmentPlacement();
			yield return null;
		}
	}

	private SpawnedEquipmentDrawer GetDrawer(Tool toolPrefab)
	{
		string preferredDrawerName = string.Empty;
		OutfitManager.OutfitType item = OutfitManager.OutfitType.None;
		bool flag = false;
		OutfitTool component = toolPrefab.GetComponent<OutfitTool>();
		if (component != null)
		{
			flag = true;
			preferredDrawerName = component.OutfitSelection.outfitItem.PreferredDrawerName;
			item = component.OutfitSelection.outfitItem.Type;
		}
		else
		{
			ToolSkinMapper component2 = toolPrefab.GetComponent<ToolSkinMapper>();
			if (component2 != null)
			{
				preferredDrawerName = component2.PrefabName;
			}
		}
		SpawnedEquipmentDrawer spawnedEquipmentDrawer = null;
		foreach (SpawnedEquipmentDrawer drawer in Drawers)
		{
			if (flag)
			{
				if (!string.IsNullOrEmpty(preferredDrawerName) && drawer.InternalName == preferredDrawerName)
				{
					return drawer;
				}
				if (spawnedEquipmentDrawer == null && drawer.OutfitTypes.Contains(item))
				{
					spawnedEquipmentDrawer = drawer;
				}
			}
			else if (!string.IsNullOrEmpty(preferredDrawerName) && drawer.SupportedEquipments.Any((ToolSkinMapper e) => e != null && e.PrefabName == preferredDrawerName))
			{
				return drawer;
			}
		}
		if (spawnedEquipmentDrawer == null)
		{
			spawnedEquipmentDrawer = ((flag && defaultOutfitDrawer != null) ? defaultOutfitDrawer : ((flag || !(defaultEquipmentDrawer != null)) ? Drawers[0] : defaultEquipmentDrawer));
		}
		return spawnedEquipmentDrawer;
	}

	[SkipRename]
	public void Button_RackSelected(UnityEngine.UI.Button button)
	{
		foreach (SpawnedEquipmentDrawer drawer in Drawers)
		{
			if (ToggleDrawerButton(drawer, button))
			{
				return;
			}
		}
		ToggleDrawerButton(TutorialDrawer, button);
	}

	private bool ToggleDrawerButton(SpawnedEquipmentDrawer drawer, UnityEngine.UI.Button button)
	{
		if (drawer != null && drawer.SelectButton == button && IsPlayerInChangingArea(Player.LocalPlayer))
		{
			SetDrawerSelected(drawer, !drawer.IsSelected);
			return true;
		}
		return false;
	}

	private void SetDrawerSelected(SpawnedEquipmentDrawer drawer, bool isSelected)
	{
		if (drawer != null)
		{
			AudioManager.Play3DSFX(openDrawer, base.transform.position);
			drawer.IsSelected = isSelected;
		}
	}

	public void PlayOpenDrawerAudio()
	{
		AudioManager.Play3DSFX(openDrawer, base.transform.position);
	}

	public bool IsPlayerInChangingArea(Player player)
	{
		float num = changingAreaRadius * changingAreaRadius;
		return (player.Head.transform.position - changingAreaCenter.position).sqrMagnitude <= num;
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(changingAreaCenter.position, changingAreaRadius);
	}
}
namespace RecRoom.Avatar.Face
{
