	public class FaceFeature : FaceFeatureBase
	{
		public Vector2 DefaultAnchor = Vector2.one * 0.5f;

		public Vector2 MaxJitterAnchor = Vector2.one * 0.025f;

		public Vector2 JitteredAnchor { get; private set; }

		public override void NewJitter()
		{
			base.NewJitter();
			JitteredAnchor = FaceFeatureBase.JitteredVector2(DefaultAnchor, MaxJitterAnchor);
		}
	}
	public abstract class FaceFeatureBase : ScriptableObject
	{
		private const bool HIGH_QUALTIY_COMPRESS = true;

		[Tooltip("This guid is auto generated at the time of the asset creation and should never change if you do not want to break an existing player's feature selection")]
		[SerializeField]
		private string GuidString = System.Guid.NewGuid().ToBase64String();

		[SerializeField]
		private Sprite[] Sprites;

		[SerializeField]
		private Sprite menuButtonSprite;

		private int spriteImportHash;

		private readonly List<Tuple<string, Texture2D>> _textures = new List<Tuple<string, Texture2D>>();

		public Vector2 DefaultScale = Vector2.one;

		public Vector2 MaxJitterScale = Vector2.one * 0.025f;

		public string Guid => GuidString;

		public IEnumerable<Sprite> SrcSprites => Sprites;

		public Sprite MenuButtonSprite => menuButtonSprite;

		public IEnumerable<Tuple<string, Texture2D>> Textures
		{
			get
			{
				CheckBuildTextures();
				return _textures;
			}
		}

		public int TextureCount
		{
			get
			{
				CheckBuildTextures();
				return _textures.Count;
			}
		}

		public Vector2 JitteredScale { get; private set; }

		private void CheckBuildTextures()
		{
			int num = SpriteImportHash();
			if (spriteImportHash != num || _textures.Count == 0)
			{
				BuildSourceTextures();
				spriteImportHash = num;
			}
		}

		public void ClearCache()
		{
			try
			{
				foreach (Tuple<string, Texture2D> texture in _textures)
				{
					try
					{
						SafeDestroy.Asset(texture.Item2);
					}
					catch (Exception exception)
					{
						UnityEngine.Debug.LogException(exception);
					}
				}
			}
			finally
			{
				_textures.Clear();
				spriteImportHash = -1;
			}
		}

		private void BuildSourceTextures()
		{
			CleanTextureCache();
			for (int i = 0; i < Sprites.Length; i++)
			{
				Sprite sprite = Sprites[i];
				Texture2D texture2D = new Texture2D((int)sprite.rect.width, (int)sprite.rect.height, TextureFormat.RGBA32, mipmap: true);
				texture2D.SetPixels(sprite.texture.GetPixels((int)sprite.rect.xMin, (int)sprite.rect.yMin, (int)sprite.rect.width, (int)sprite.rect.height));
				texture2D.Apply();
				texture2D.Compress(highQuality: true);
				_textures.Add(Tuple.Create(sprite.name, texture2D));
			}
		}

		public void CleanTextureCache()
		{
			try
			{
				for (int i = 0; i < _textures.Count; i++)
				{
					SafeDestroy.Asset(_textures[i].Item2);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			finally
			{
				_textures.Clear();
			}
		}

		private int SpriteImportHash()
		{
			return 1;
		}

		protected static Vector2 JitteredVector2(Vector2 initial, Vector2 maxJitter)
		{
			return new Vector2
			{
				x = UnityEngine.Random.Range(initial.x - maxJitter.x, initial.x + maxJitter.x),
				y = UnityEngine.Random.Range(initial.y - maxJitter.y, initial.y + maxJitter.y)
			};
		}

		public virtual void NewJitter()
		{
			JitteredScale = JitteredVector2(DefaultScale, MaxJitterScale);
		}
	}
	public sealed class FaceStyle : IDisposable
	{
		private Dictionary<string, int> spriteTextureIndices;

		public Texture2DArray TextureArray { get; private set; }

		public SymmetricalFaceFeature Brow { get; private set; }

		public SymmetricalFaceFeature Eye { get; private set; }

		public FaceFeature Nose { get; private set; }

		public FaceFeature Mouth { get; private set; }

		public FaceStyle(SymmetricalFaceFeature brow, SymmetricalFaceFeature eye, FaceFeature nose, FaceFeature mouth)
		{
			try
			{
				Brow = brow;
				Eye = eye;
				Nose = nose;
				Mouth = mouth;
				spriteTextureIndices = new Dictionary<string, int>();
				Texture2D item = brow.Textures.First().Item2;
				int width = item.width;
				int height = item.height;
				TextureFormat format = item.format;
				Texture2D item2 = eye.Textures.First().Item2;
				Texture2D item3 = nose.Textures.First().Item2;
				Texture2D item4 = mouth.Textures.First().Item2;
				int num = brow.TextureCount + eye.TextureCount + nose.TextureCount + mouth.TextureCount;
				TextureArray = new Texture2DArray(width, height, num, format, mipmap: true);
				TextureArray.wrapMode = TextureWrapMode.Clamp;
				IEnumerator<Tuple<string, Texture2D>> enumerator = brow.Textures.Concat(eye.Textures).Concat(nose.Textures).Concat(mouth.Textures)
					.GetEnumerator();
				for (int i = 0; i < num; i++)
				{
					enumerator.MoveNext();
					Tuple<string, Texture2D> current = enumerator.Current;
					spriteTextureIndices[current.Item1] = i;
					Graphics.CopyTexture(current.Item2, 0, TextureArray, i);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				brow.ClearCache();
				eye.ClearCache();
				nose.ClearCache();
				mouth.ClearCache();
			}
		}

		public float SpriteUVDepth(Sprite sprite)
		{
			if (sprite == null)
			{
				throw new ArgumentNullException("sprite");
			}
			if (!spriteTextureIndices.TryGetValue(sprite.name, out var value))
			{
				UnityEngine.Debug.LogError($"Attempting to set Sprite({sprite}) that isn't part of this FaceStyle", sprite);
				throw new InvalidOperationException("The requested sprite isn't part of this FaceStyle");
			}
			return value;
		}

		public void Dispose()
		{
			SafeDestroy.Asset(TextureArray);
		}
	}
	public enum FaceFeatureType
	{
		Brow,
		Eye,
		Nose,
		Mouth
	}
	[CreateAssetMenu(fileName = "NewFaceFeatureSet", menuName = "RecRoom/Face/New Face Set")]
	public sealed class FaceStyleSet : ScriptableObject
	{
		public SymmetricalFaceFeature[] Brows;

		public SymmetricalFaceFeature[] Eyes;

		public FaceFeature[] Noses;

		public FaceFeature[] Mouths;

		private Dictionary<string, SymmetricalFaceFeature> browFeatureDictionary;

		private Dictionary<string, SymmetricalFaceFeature> eyeFeatureDictionary;

		private Dictionary<string, FaceFeature> noseFeatureDictionary;

		private Dictionary<string, FaceFeature> mouthFeatureDictionary;

		private Dictionary<string, int> featureToIndexMap = new Dictionary<string, int>();

		[HideInInspector]
		public int ImportHash;

		private bool dictionariesInitialized => browFeatureDictionary != null || eyeFeatureDictionary != null || noseFeatureDictionary != null || mouthFeatureDictionary != null;

		public FaceStyle Build(int brow, int eye, int nose, int mouth)
		{
			if (brow >= Brows.Length)
			{
				UnityEngine.Debug.LogWarning("Brow selection out of range, setting to default");
				brow = 0;
			}
			if (eye >= Eyes.Length)
			{
				UnityEngine.Debug.LogWarning("Eye selection out of range, setting to default");
				eye = 0;
			}
			if (nose >= Noses.Length)
			{
				UnityEngine.Debug.LogWarning("Nose selection out of range, setting to default");
				nose = 0;
			}
			if (mouth >= Mouths.Length)
			{
				UnityEngine.Debug.LogWarning("Mouth selection out of range, setting to default");
				mouth = 0;
			}
			return new FaceStyle(Brows[brow], Eyes[eye], Noses[nose], Mouths[mouth]);
		}

		public FaceFeatureBase GetFeature(FaceFeatureType featureType, string guid)
		{
			if (!dictionariesInitialized)
			{
				InitializeDictionaries();
			}
			FaceFeatureBase result = null;
			switch (featureType)
			{
			case FaceFeatureType.Brow:
			{
				SymmetricalFaceFeature value4 = null;
				browFeatureDictionary.TryGetValue(guid, out value4);
				result = value4;
				break;
			}
			case FaceFeatureType.Eye:
			{
				SymmetricalFaceFeature value3 = null;
				eyeFeatureDictionary.TryGetValue(guid, out value3);
				result = value3;
				break;
			}
			case FaceFeatureType.Nose:
			{
				FaceFeature value2 = null;
				noseFeatureDictionary.TryGetValue(guid, out value2);
				result = value2;
				break;
			}
			case FaceFeatureType.Mouth:
			{
				FaceFeature value = null;
				mouthFeatureDictionary.TryGetValue(guid, out value);
				result = value;
				break;
			}
			}
			return result;
		}

		public int GetFeatureIndex(string guid)
		{
			if (!dictionariesInitialized)
			{
				InitializeDictionaries();
			}
			int value = -1;
			featureToIndexMap.TryGetValue(guid, out value);
			return value;
		}

		private void InitializeDictionaries()
		{
			if (!dictionariesInitialized)
			{
				browFeatureDictionary = new Dictionary<string, SymmetricalFaceFeature>();
				eyeFeatureDictionary = new Dictionary<string, SymmetricalFaceFeature>();
				noseFeatureDictionary = new Dictionary<string, FaceFeature>();
				mouthFeatureDictionary = new Dictionary<string, FaceFeature>();
				InitializeFeatureDictionary(browFeatureDictionary, Brows);
				InitializeFeatureDictionary(eyeFeatureDictionary, Eyes);
				InitializeFeatureDictionary(noseFeatureDictionary, Noses);
				InitializeFeatureDictionary(mouthFeatureDictionary, Mouths);
			}
		}

		private void InitializeFeatureDictionary<T>(Dictionary<string, T> dictionary, T[] features) where T : FaceFeatureBase
		{
			if (dictionary != null && features != null && features.Length != 0)
			{
				for (int i = 0; i < features.Length; i++)
				{
					T value = features[i];
					dictionary.Add(value.Guid, value);
					featureToIndexMap[value.Guid] = i;
				}
			}
		}
	}
