	public class SymmetricalFaceFeature : FaceFeatureBase
	{
		public Vector2 MaxJitterAnchors = Vector2.one * 0.01f;

		public bool JitterSymetrically = true;

		public Vector2 DefaultAnchorLeft = new Vector2(0.25f, 0.75f);

		public Vector2 DefaultAnchorRight = new Vector2(0.75f, 0.75f);

		public Vector2 JitteredAnchorLeft { get; private set; }

		public Vector2 JitteredAnchorRight { get; private set; }

		public override void NewJitter()
		{
			base.NewJitter();
			Vector2 vector = FaceFeatureBase.JitteredVector2(Vector2.zero, MaxJitterAnchors);
			JitteredAnchorLeft = DefaultAnchorLeft + vector;
			if (!JitterSymetrically)
			{
				vector = FaceFeatureBase.JitteredVector2(Vector2.zero, MaxJitterAnchors);
			}
			JitteredAnchorRight = DefaultAnchorRight + vector;
		}
	}
}
