			}
			return null;
		}
	}

	public Bounds LocalBounds
	{
		get
		{
			if (ActiveRenderer != null)
			{
				if (ActiveRenderer is SkinnedMeshRenderer)
				{
					return ((SkinnedMeshRenderer)ActiveRenderer).localBounds;
				}
				MeshFilter component = ActiveRenderer.GetComponent<MeshFilter>();
				if (component != null && component.sharedMesh != null)
				{
