	public int RackIndex { get; set; }

	public Player Owner { get; set; }

	public bool Visible => !_hideFlag.HasTokens;

	public OutfitSelection Selection { get; private set; }

	public bool WornByPuppet { get; set; }

	private bool ShouldCreateTrigger
	{
		get
		{
			bool flag = Owner != null && Owner.isLocal && !WornByPuppet;
			bool flag2 = outfitTriggerEnabled && (SessionManager.InDormRoom || triggerEnabledOutsideDormroom);
			return flag && flag2;
		}
	}

	private void Awake()
	{
		Selection = new OutfitSelection(this);
		ActiveRenderer = SourceMeshRenderer;
		if (UnityEngine.Application.isPlaying)
		{
			SourceMeshRenderer.material = DefaultMaterial;
		}
		else
		{
			SourceMeshRenderer.sharedMaterial = DefaultMaterial;
		}
	}

	private void Start()
	{
		if (UsesHairColor && Owner != null)
		{
			Owner.PlayerOutfit.HairColorChanged += PlayerOutfit_ColorChanged;
			bool flag = Type == OutfitManager.OutfitType.Mouth;
			ColorVault.ColorToGuid colorToGuid = ((!flag) ? Owner.PlayerOutfit.HairColor : Owner.PlayerOutfit.BeardColor);
			if (colorToGuid != null)
			{
				PlayerOutfit_ColorChanged(colorToGuid.color, (!flag) ? AvatarColor.ColorType.Hair : AvatarColor.ColorType.Beard);
			}
		}
		SetOwnerNameTag();
		if (Owner != null && Owner.isLocal && nameTextMesh != null)
		{
			Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
		}
		if (ShouldCreateTrigger)
		{
			GameObject gameObject = new GameObject();
			outfitTrigger = gameObject.AddComponent<OutfitTrigger>();
			outfitTrigger.SetOutfitOwner(this);
			outfitTrigger.EnabledOutsideDormRoom = triggerEnabledOutsideDormroom;
			Owner.SetParentPlayerRoot(gameObject.transform);
		}
		EvaluateIfUpdateIsNeeded();
		if (!(Owner != null))
		{
			return;
		}
		if (hidesHair)
		{
			foreach (OutfitSelectionToBody outfitSelection in Owner.PlayerOutfit.OutfitSelections)
			{
				OutfitItem outfitItem = outfitSelection.selection.outfitItem;
				if (outfitItem != this && outfitItem.Type == OutfitManager.OutfitType.Hair)
				{
					outfitItem.SetVisible(visible: false, base.gameObject);
				}
			}
		}
		if (Type != OutfitManager.OutfitType.Hair)
		{
			return;
		}
		foreach (OutfitSelectionToBody outfitSelection2 in Owner.PlayerOutfit.OutfitSelections)
		{
			OutfitItem outfitItem2 = outfitSelection2.selection.outfitItem;
			if (outfitItem2 != this && outfitItem2.hidesHair)
			{
				SetVisible(visible: false, outfitItem2.gameObject);
			}
		}
	}

	private void LateUpdate()
	{
		if (Highlighted)
		{
			OutlineEffectRenderer.RenderHoverOutline(ActiveRenderer);
		}
	}

	private void OnDestroy()
	{
		if (UsesHairColor && Owner != null)
		{
			Owner.PlayerOutfit.HairColorChanged -= PlayerOutfit_ColorChanged;
		}
		if (outfitTrigger != null)
		{
			UnityEngine.Object.Destroy(outfitTrigger.gameObject);
		}
		if (Owner != null && Owner.isLocal && nameTextMesh != null)
		{
			Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
		}
		if (ActiveRenderer != null)
		{
			SafeDestroy.GameObject(ActiveRenderer.gameObject);
		}
		if (FirstPersonShadowCaster != null)
		{
			SafeDestroy.GameObject(FirstPersonShadowCaster);
		}
		if (!(Owner != null) || !hidesHair)
		{
			return;
		}
		foreach (OutfitSelectionToBody outfitSelection in Owner.PlayerOutfit.OutfitSelections)
		{
			OutfitItem outfitItem = outfitSelection.selection.outfitItem;
			if (outfitItem != this && outfitItem.Type == OutfitManager.OutfitType.Hair)
			{
				outfitItem.SetVisible(visible: true, base.gameObject);
			}
		}
	}

	public void SetVisible(bool visible, object token)
	{
		if (visible)
		{
			_hideFlag.Remove(token);
		}
		else
		{
			_hideFlag.Add(token);
		}
		bool visible2 = Visible;
		base.gameObject.SetActive(visible2);
		ActiveRenderer.enabled = visible2;
		if (nameTagRootBoneProxy != null)
		{
			nameTagRootBoneProxy.gameObject.SetActive(visible2);
		}
		if (FirstPersonShadowCaster != null)
		{
			FirstPersonShadowCaster.SetActive(visible2);
		}
	}

	private void EvaluateIfUpdateIsNeeded()
	{
		bool highlighted = Highlighted;
		base.enabled = highlighted;
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		SetOwnerNameTag();
	}

	private void SetOwnerNameTag()
	{
		if (nameTextMesh != null)
		{
			string text = string.Empty;
			if (Owner != null)
			{
				text = Owner.PlayerName.Truncate(nameTextMaxLength, ".");
			}
			nameTextMesh.text = text;
		}
	}

	private void PlayerOutfit_ColorChanged(Color color, AvatarColor.ColorType colorType)
	{
		AvatarColor.ColorType colorType2 = ((Type != OutfitManager.OutfitType.Mouth) ? AvatarColor.ColorType.Hair : AvatarColor.ColorType.Beard);
		if (colorType2 == colorType)
		{
			SetHairColor(color);
		}
	}

	public void SetHairColor(Color color)
	{
		if (UsesHairColor && ActiveRenderer != null && ActiveRenderer.material != null)
		{
			ActiveRenderer.material.color = color;
		}
	}

	public void BindToBody(OutfitBodyMapping mapping)
	{
		switch (Type)
		{
		case OutfitManager.OutfitType.Hat:
		case OutfitManager.OutfitType.BackHead:
		case OutfitManager.OutfitType.Hair:
		case OutfitManager.OutfitType.Eye:
		case OutfitManager.OutfitType.Mouth:
			BindToTransform(mapping.head);
			break;
		case OutfitManager.OutfitType.Neck:
		case OutfitManager.OutfitType.Shirt:
		case OutfitManager.OutfitType.Belt:
		case OutfitManager.OutfitType.Pocket:
		case OutfitManager.OutfitType.TeamJersey:
			BindToTransform(mapping.torso);
			break;
		case OutfitManager.OutfitType.Wrist:
		case OutfitManager.OutfitType.Glove:
		case OutfitManager.OutfitType.Watch:
		case OutfitManager.OutfitType.TeamWrist:
			if (CurrentBodyPart == Player.BodyPart.LeftHand)
			{
				BindToSkinnedMesh(mapping.leftHand);
				break;
			}
			if (CurrentBodyPart == Player.BodyPart.RightHand)
			{
				BindToSkinnedMesh(mapping.rightHand);
				break;
			}
			UnityEngine.Debug.LogError(string.Concat("An outfit (", this, ") with hand type is being placed to an incorrect body part. ", CurrentBodyPart));
			break;
		default:
			throw new Exception("PlayerOutfit.SetOutfitTarget can not set target for this outfit " + this);
		}
	}

	private void BindToSkinnedMesh(OutfitAnimatedBodyMapping bodyPart)
	{
		if (!(bodyPart.renderer == null))
		{
			bodyPart.DeoptimizeAnimatorTransformHierarchy();
			SkinnedMeshRenderer skinnedMeshRenderer = ActiveRenderer as SkinnedMeshRenderer;
			SkinnedMeshRenderer skinnedMeshRenderer2 = UnityEngine.Object.Instantiate(bodyPart.renderer, bodyPart.renderer.transform.parent);
			skinnedMeshRenderer2.sharedMesh = skinnedMeshRenderer.sharedMesh;
			skinnedMeshRenderer2.sharedMaterials = skinnedMeshRenderer.sharedMaterials;
			skinnedMeshRenderer2.name = skinnedMeshRenderer.name;
			skinnedMeshRenderer2.shadowCastingMode = skinnedMeshRenderer.shadowCastingMode;
			skinnedMeshRenderer2.reflectionProbeUsage = skinnedMeshRenderer.reflectionProbeUsage;
			skinnedMeshRenderer2.lightProbeUsage = skinnedMeshRenderer.lightProbeUsage;
			skinnedMeshRenderer2.receiveShadows = skinnedMeshRenderer.receiveShadows;
			skinnedMeshRenderer2.quality = skinnedMeshRenderer.quality;
			skinnedMeshRenderer2.gameObject.layer = skinnedMeshRenderer.gameObject.layer;
			skinnedMeshRenderer2.gameObject.tag = "OutfitRenderer";
			skinnedMeshRenderer2.gameObject.SetActive(value: true);
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.EndOfFrameRoutine(bodyPart.OptimizeAnimatorTransformHierarchy);
			if (ActiveRenderer == SourceMeshRenderer)
			{
				SafeDestroy.Component(SourceMeshRenderer);
				SourceMeshRenderer = null;
			}
			else
			{
				SafeDestroy.GameObject(ActiveRenderer.gameObject);
			}
			ActiveRenderer = skinnedMeshRenderer2;
		}
	}

	private void BindToTransform(Transform bodyParent)
	{
		SkinnedMeshRenderer sourceMeshRenderer = SourceMeshRenderer;
		Mesh sharedMesh = sourceMeshRenderer.sharedMesh;
		Material[] materials = sourceMeshRenderer.materials;
		sharedMesh.RecalculateBounds();
		sourceMeshRenderer.gameObject.GetOrAddComponent<MeshFilter>().sharedMesh = sharedMesh;
		MeshRenderer orAddComponent = sourceMeshRenderer.gameObject.GetOrAddComponent<MeshRenderer>();
		orAddComponent.materials = materials;
		ActiveRenderer = orAddComponent;
		orAddComponent.gameObject.transform.localPosition = fbxPivotOffset;
		orAddComponent.gameObject.transform.localRotation = Quaternion.identity;
		orAddComponent.gameObject.transform.localScale = Vector3.one;
		orAddComponent.gameObject.transform.SetParent(bodyParent.transform, worldPositionStays: false);
		orAddComponent.gameObject.SetLayerRecursively((Layers)bodyParent.gameObject.layer);
		orAddComponent.gameObject.tag = "OutfitRenderer";
		SafeDestroy.Component(SourceMeshRenderer);
		SourceMeshRenderer = null;
	}

	public void RenderAsIgnored(Player ignoringPlayer, Player ignoredPlayer, Color accentColor, float minAlpha, bool hide)
	{
		if (ShouldRenderIgnored())
		{
			if (hide)
			{
				IgnoreEffectRenderer.HideIgnoredItem(ActiveRenderer, ActiveRenderer.GetSubmeshCount());
				return;
			}
			GetIgnoreParameters(minAlpha, accentColor, out minAlpha, out var fadeColor);
			IgnoreEffectRenderer.RenderIgnoredItem(ActiveRenderer, ActiveRenderer.GetSubmeshCount(), ignoringPlayer, ignoredPlayer, minAlpha, fadeColor);
		}
	}

	public void RenderAsIgnored(CameraIgnoreBubble camera, Color accentColor, bool hide)
	{
		RenderAsIgnored(camera.transform.position, camera.FadeStartDistance, camera.FadeCompleteDistance, accentColor, camera.MinAlpha, hide);
	}

	public void RenderAsIgnored(Vector3 fadeCenter, float fadeStartDistance, float fadeCompleteDistance, Color accentColor, float minAlpha, bool hide)
	{
		if (ShouldRenderIgnored())
		{
			if (hide)
			{
				IgnoreEffectRenderer.HideIgnoredItem(ActiveRenderer, ActiveRenderer.GetSubmeshCount());
				return;
			}
			GetIgnoreParameters(minAlpha, accentColor, out minAlpha, out var fadeColor);
			IgnoreEffectRenderer.RenderIgnoredItem(ActiveRenderer, ActiveRenderer.GetSubmeshCount(), hideOnly: false, fadeCenter, fadeStartDistance, fadeCompleteDistance, minAlpha, fadeColor);
		}
	}

	private bool ShouldRenderIgnored()
	{
		return Visible && ActiveRenderer.enabled && ActiveRenderer.gameObject.activeInHierarchy;
	}

	private void GetIgnoreParameters(float defaultMinAlpha, Color accentColor, out float minAlpha, out Color? fadeColor)
	{
		if (OutfitManager.IsTeamOutfit(Type))
		{
			minAlpha = Mathf.Max(defaultMinAlpha, TEAM_OUTFIT_MIN_IGNORED_ALPHA);
			fadeColor = accentColor;
		}
		else
		{
			minAlpha = defaultMinAlpha;
			fadeColor = null;
		}
	}

	public void ApplySwatch(AvatarColorSwatch swatch)
	{
		if (Selection != null)
		{
			Selection.colorSwatch = swatch;
		}
		AvatarColorSwatch.Apply(swatch, ActiveRenderer.material, DefaultMaterial);
	}

	public void ApplyMask(AvatarMask mask)
	{
		if (Selection != null)
		{
			Selection.mask = mask;
		}
		AvatarMask.Apply(mask, ActiveRenderer.material, DefaultMaterial);
	}

	public void ApplyDecal(AvatarDecal decal)
	{
		if (Selection != null)
		{
			Selection.decal = decal;
		}
		AvatarDecal.Apply(decal, ActiveRenderer.material, DefaultMaterial);
	}

	public int CompareTo(OutfitItem other)
	{
		if (other == null)
		{
			return 0;
		}
		int type = (int)Type;
		int num = type.CompareTo((int)other.Type);
		if (num == 0)
		{
			int num2 = preferredIndex.CompareTo(other.preferredIndex);
			if (num2 == 0)
			{
				return base.name.CompareTo(other.name);
			}
			return num2;
		}
		return num;
	}
}
[Serializable]
public class OutfitSelection : IEquatable<OutfitSelection>, IComparable<OutfitSelection>
{
	public string name;

	[FormerlySerializedAs("outfit")]
	public OutfitItem outfitItem;

	public AvatarColorSwatch colorSwatch;

	public AvatarMask mask;

	public AvatarDecal decal;

	public bool IsNew { get; set; }

	public string FriendlyName
	{
		get
		{
			string text = outfitItem.name;
			if (mask != null)
			{
				text = text + " " + mask.name;
			}
			if (colorSwatch != null)
			{
				text = text + " " + colorSwatch.name;
			}
			if (decal != null)
			{
				text = text + " " + decal.name;
			}
			return text;
		}
	}

	public int Level { get; set; }

	public bool IsPlatformLocked { get; set; }

	private OutfitSelection()
	{
	}

	public OutfitSelection(OutfitItem o, AvatarColorSwatch cs = null, AvatarMask m = null, AvatarDecal d = null)
	{
		name = o.name;
		outfitItem = o;
		colorSwatch = cs;
		mask = m;
		decal = d;
		IsNew = false;
	}

	public OutfitSelection GetPrefab()
	{
		if (outfitItem != null)
		{
			OutfitItem outfitPrefab = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.GetOutfitPrefab(outfitItem.Guid);
			if (outfitPrefab != null)
			{
				return new OutfitSelection(outfitPrefab, colorSwatch, mask, decal);
			}
		}
		return null;
	}

	public bool Equals(OutfitSelection other)
	{
		return other != null && other.outfitItem != null && outfitItem != null && outfitItem.Guid == other.outfitItem.Guid && ((colorSwatch == null && other.colorSwatch == null) || (colorSwatch != null && other.colorSwatch != null && colorSwatch.Guid == other.colorSwatch.Guid)) && ((mask == null && other.mask == null) || (mask != null && other.mask != null && mask.Guid == other.mask.Guid)) && ((decal == null && other.decal == null) || (decal != null && other.decal != null && decal.Guid == other.decal.Guid));
	}

	public override bool Equals(object obj)
	{
		return base.Equals(obj as OutfitSelection);
	}

	public override int GetHashCode()
	{
		return ToString().GetHashCode();
	}

	public static bool operator !=(OutfitSelection os1, OutfitSelection os2)
	{
		if (object.ReferenceEquals(os1, null))
		{
			return !object.ReferenceEquals(os2, null);
		}
		return !os1.Equals(os2);
	}

	public static bool operator ==(OutfitSelection os1, OutfitSelection os2)
	{
		if (object.ReferenceEquals(os1, null))
		{
			return object.ReferenceEquals(os2, null);
		}
		return os1.Equals(os2);
	}

	public override string ToString()
	{
		return $"{outfitItem.Guid},{((!(colorSwatch != null)) ? string.Empty : colorSwatch.Guid)},{((!(mask != null)) ? string.Empty : mask.Guid)},{((!(decal != null)) ? string.Empty : decal.Guid)}";
	}

	public static OutfitSelection Parse(string desc)
	{
		if (string.IsNullOrEmpty(desc))
		{
			return null;
		}
		string[] array = desc.Split(',');
		if (array == null || array.Length != 4)
		{
			return null;
		}
		return Parse(array[0], array[1], array[2], array[3]);
	}

	public static OutfitSelection Parse(string guidString, string cs, string m, string d)
	{
		OutfitItem outfitItem = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitPrefabs.Find((OutfitItem x) => x.Guid == guidString);
		if (outfitItem != null)
		{
			AvatarColorSwatch cs2 = ((!string.IsNullOrEmpty(cs)) ? AvatarColorSwatch.All.Find((AvatarColorSwatch x) => x.Guid == cs) : null);
			AvatarMask m2 = ((!string.IsNullOrEmpty(m)) ? AvatarMask.All.Find((AvatarMask x) => x.Guid == m) : null);
			AvatarDecal d2 = ((!string.IsNullOrEmpty(d)) ? AvatarDecal.All.Find((AvatarDecal x) => x.Guid == d) : null);
			return new OutfitSelection(outfitItem, cs2, m2, d2);
		}
		return null;
	}

	public int CompareTo(OutfitSelection other)
	{
		return outfitItem.CompareTo(other.outfitItem);
	}
}
[Serializable]
public class OutfitSelectionToBody : IEquatable<OutfitSelectionToBody>
{
	public OutfitSelection selection;

	public Player.BodyPart bodyPart;

	public OutfitSelectionToBody(OutfitSelection s, Player.BodyPart b)
	{
		selection = s;
		bodyPart = b;
	}

	public bool Equals(OutfitSelectionToBody other)
	{
		return selection == other.selection && other.bodyPart == bodyPart;
	}

	public override bool Equals(object obj)
	{
		return base.Equals(obj as OutfitSelectionToBody);
	}

	public override int GetHashCode()
	{
		return ToString().GetHashCode();
	}

	public override string ToString()
	{
		return selection.ToString() + "," + (int)bodyPart;
	}

	public static OutfitSelectionToBody Parse(string serializedStr)
	{
		string[] array = serializedStr.Split(',');
		if (array == null || array.Length != 5)
		{
			return null;
		}
		try
		{
			OutfitSelection outfitSelection = OutfitSelection.Parse(array[0], array[1], array[2], array[3]);
			int b = int.Parse(array[4]);
			if (outfitSelection != null)
			{
				return new OutfitSelectionToBody(outfitSelection, (Player.BodyPart)b);
			}
		}
		catch
		{
			UnityEngine.Debug.LogError("Failed to parse OutfitSelectionToBody with str:" + serializedStr);
		}
		return null;
	}
}
