	public event Action<OutfitSelection> OutfitSelectionUnlocked
	{
		add
		{
			Action<OutfitSelection> action = this.m_OutfitSelectionUnlocked;
			Action<OutfitSelection> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OutfitSelectionUnlocked, (Action<OutfitSelection>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<OutfitSelection> action = this.m_OutfitSelectionUnlocked;
			Action<OutfitSelection> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OutfitSelectionUnlocked, (Action<OutfitSelection>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public event Action<OutfitSet> OutfitSetCompleted
	{
		add
		{
			Action<OutfitSet> action = this.m_OutfitSetCompleted;
			Action<OutfitSet> action2;
