		}
	}

	protected override void Awake()
	{
		base.Awake();
		outfitPrefabs.RemoveNulls();
		InitializeOutfitPrefabDictionary();
		InitializeOutfitTypeMap();
		InitializeOutfitSetMap();
		UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
	}

	private void InitializeOutfitPrefabDictionary()
	{
		foreach (OutfitItem outfitPrefab in outfitPrefabs)
		{
			outfitPrefabDictionary.Add(outfitPrefab.Guid, outfitPrefab);
		}
	}

	private void InitializeOutfitSetMap()
	{
		foreach (OutfitItem outfitPrefab in outfitPrefabs)
		{
			if (outfitPrefab.OutfitSet != OutfitSet.None)
			{
				if (!outfitSetMap.TryGetValue(outfitPrefab.OutfitSet, out var value))
				{
					value = new List<string>();
					outfitSetMap[outfitPrefab.OutfitSet] = value;
				}
				value.Add(outfitPrefab.Guid);
			}
		}
	}

	private void InitializeOutfitTypeMap()
	{
		outfitTypeMap = new Dictionary<OutfitType, List<OutfitSelection>>();
		List<IGrouping<OutfitType, OutfitSelection>> list = (from o in unlockedOutfitSelections
			where o != null && o.outfitItem != null
			group o by o.outfitItem.Type into oType
			select (oType)).Distinct().ToList();
		int playerLevel = ((Profiles.LocalProfile == null) ? 1 : Profiles.LocalProfile.Level.GetDecrypted());
		foreach (IGrouping<OutfitType, OutfitSelection> item in list)
		{
			OutfitType type = item.Key;
			List<OutfitSelection> value = unlockedOutfitSelections.Where((OutfitSelection o) => o != null && o.outfitItem != null && o.outfitItem.Type == type && o.outfitItem.DropableItem && o.Level <= playerLevel).ToList();
			outfitTypeMap.Add(type, value);
		}
	}

	public OutfitItem GetOutfitPrefab(string guidString)
	{
		outfitPrefabDictionary.TryGetValue(guidString, out var value);
		return value;
	}

	public List<OutfitSelectionToBody> GetInitialRandomOutfitSelection()
	{
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		foreach (OutfitSelectionList initialOutfitsList in initialOutfitsLists)
		{
			OutfitSelection outfitSelection = initialOutfitsList.selections.Random();
			Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitSelection.outfitItem.Type);
			list.Add(new OutfitSelectionToBody(outfitSelection, matchingBodyPart));
			if (matchingBodyPart == Player.BodyPart.LeftHand)
			{
				list.Add(new OutfitSelectionToBody(outfitSelection, Player.BodyPart.RightHand));
			}
		}
		return list;
	}

	public List<OutfitSelectionToBody> GetMissingOutfitsFromDefaultSet(List<OutfitSelectionToBody> currentSelection)
	{
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		foreach (OutfitSelectionToBody defaultOutfit in defaultOutfits)
		{
			bool flag = false;
			foreach (OutfitSelectionToBody item in currentSelection)
			{
				if (item.selection.outfitItem.Type == defaultOutfit.selection.outfitItem.Type && item.selection.outfitItem.CurrentBodyPart == defaultOutfit.bodyPart)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				list.Add(defaultOutfit);
			}
		}
		return list;
	}

	public static Player.BodyPart GetMatchingBodyPart(OutfitType outfitType)
	{
		Player.BodyPart result = Player.BodyPart.Head;
		switch (outfitType)
		{
		case OutfitType.Hat:
		case OutfitType.BackHead:
		case OutfitType.Hair:
		case OutfitType.Eye:
		case OutfitType.Mouth:
			result = Player.BodyPart.Head;
			break;
		case OutfitType.Neck:
		case OutfitType.Shirt:
		case OutfitType.Belt:
		case OutfitType.Pocket:
		case OutfitType.TeamJersey:
			result = Player.BodyPart.Torso;
			break;
		case OutfitType.Wrist:
		case OutfitType.Glove:
		case OutfitType.Watch:
		case OutfitType.TeamWrist:
			result = Player.BodyPart.LeftHand;
			break;
		}
		return result;
	}

	public static bool IsTeamOutfit(OutfitType outfitType)
	{
		return outfitType == OutfitType.TeamJersey || outfitType == OutfitType.TeamWrist;
	}

	public static bool IsRequiredOutfitType(OutfitType outfitType)
	{
		return outfitType == OutfitType.Shirt;
	}

	public static bool IsMatchingBodyPart(Player.BodyPart bodyPart, OutfitType outfitType)
	{
		Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitType);
		return matchingBodyPart == bodyPart || (matchingBodyPart == Player.BodyPart.LeftHand && bodyPart == Player.BodyPart.RightHand);
	}

	public void RandomizePlayerOutfit()
	{
		if (!Player.LocalPlayerExists || !(Player.LocalPlayer.PlayerOutfit != null))
		{
			return;
		}
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		foreach (KeyValuePair<OutfitType, List<OutfitSelection>> item in outfitTypeMap)
		{
			OutfitType key = item.Key;
			List<OutfitSelection> value = item.Value;
			if ((IsRequiredOutfitType(key) || !(UnityEngine.Random.value > ((value.Count < 5) ? 0.3f : 0.6f))) && value.Count > 0)
			{
				OutfitSelection outfitSelection = value.Random();
				Player.BodyPart matchingBodyPart = GetMatchingBodyPart(outfitSelection.outfitItem.Type);
				list.Add(new OutfitSelectionToBody(outfitSelection, matchingBodyPart));
				if (matchingBodyPart == Player.BodyPart.LeftHand && (outfitSelection.outfitItem.Type == OutfitType.Wrist || outfitSelection.outfitItem.Type == OutfitType.Glove))
				{
					list.Add(new OutfitSelectionToBody(outfitSelection, Player.BodyPart.RightHand));
				}
			}
		}
		if (list.Count > 0)
		{
			Player.LocalPlayer.PlayerOutfit.UnEquipAll();
			Player.LocalPlayer.PlayerOutfit.SetOutfit(list);
		}
		if (!SessionManager.InDormRoom)
		{
			AnalyticsHelper.DebugAction("RandomizePlayerOutfit");
		}
	}

	public ColorVault.ColorToGuid FindHairColor(string hairColorGuid)
	{
		return FindColorFromVault(HairColorVault, hairColorGuid);
	}

	public ColorVault.ColorToGuid FindSkinColor(string skinColorGuid)
	{
		return FindColorFromVault(SkinColorVault, skinColorGuid);
	}

	private ColorVault.ColorToGuid FindColorFromVault(ColorVault vault, string colorGuid)
	{
		ColorVault.ColorToGuid colorToGuid = vault.Find(colorGuid);
		if (colorToGuid == null)
		{
			colorToGuid = vault.GetRandom();
			if (!string.IsNullOrEmpty(colorGuid))
			{
				UnityEngine.Debug.LogWarning(string.Concat("Outfit Manager FindColor in ", vault, " can't find matching color for the guid ", colorGuid, ". Getting a random one."));
			}
		}
		return colorToGuid;
	}

	public IEnumerator DownloadUnlockedAvatarItems(RecNet.Core.ApiCallback callback)
	{
		return Avatars.DowloadUnlockedAvatarItems(delegate(string e, List<OutfitSelection> selections)
		{
			if (selections != null)
			{
				foreach (OutfitSelection selection in selections)
				{
					if (selection != null && !unlockedOutfitSelections.Contains(selection))
					{
						unlockedOutfitSelections.Add(selection);
						if (selection.IsPlatformLocked)
						{
							HasPlatformLockedOutfit = true;
						}
						if (selection.outfitItem.OutfitSet != OutfitSet.None)
						{
							List<string> value = null;
							if (outfitSetMap.TryGetValue(selection.outfitItem.OutfitSet, out value))
							{
								value.Remove(selection.outfitItem.Guid);
							}
						}
					}
				}
			}
			if (string.IsNullOrEmpty(e))
			{
				InitializeOutfitTypeMap();
			}
			RecNet.Core.SafeInvoke(callback, e);
		});
	}

	public bool AddAvatarItemToUnlockedList(string avatarItemDesc, int level)
	{
		OutfitSelection outfitSelection = OutfitSelection.Parse(avatarItemDesc);
		if (outfitSelection != null && !unlockedOutfitSelections.Contains(outfitSelection))
		{
			outfitSelection.Level = level;
			unlockedOutfitSelections.Add(outfitSelection);
			InitializeOutfitTypeMap();
			outfitSelection.IsNew = true;
			if (this.OutfitSelectionUnlocked != null)
			{
				this.OutfitSelectionUnlocked(outfitSelection);
			}
			OutfitSet outfitSet = outfitSelection.outfitItem.OutfitSet;
			if (outfitSet != OutfitSet.None && outfitSetMap.TryGetValue(outfitSet, out var value))
			{
				value.Remove(outfitSelection.outfitItem.Guid);
				if (value.Count <= 0)
				{
					UnityEngine.Debug.Log($"Outfit Set \"{outfitSet}\" completed");
					if (this.OutfitSetCompleted != null)
					{
						this.OutfitSetCompleted(outfitSet);
					}
				}
			}
			return true;
		}
		return false;
	}

	public bool IsOutfitUnlockedOnCurrentPlatform(string avatarItemDesc)
	{
		return IsOutfitUnlockedOnCurrentPlatform(OutfitSelection.Parse(avatarItemDesc));
	}

	public bool IsOutfitUnlockedOnCurrentPlatform(OutfitSelection selection)
	{
		return UnlockedOutfitSelections.Where((OutfitSelection s) => !s.IsPlatformLocked).Contains(selection) || SingletonMonoBehaviour<GiftManager>.Instance.IsOutfitUnlockedOnCurrentPlatform(selection.ToString());
	}

	public bool IsOutfitLockedOnCurrentPlatform(string avatarItemDesc)
	{
		return IsOutfitLockedOnCurrentPlatform(OutfitSelection.Parse(avatarItemDesc));
	}

	public bool IsOutfitLockedOnCurrentPlatform(OutfitSelection selection)
	{
		return UnlockedOutfitSelections.Where((OutfitSelection s) => s.IsPlatformLocked).Contains(selection);
	}

	private OutfitTool SpawnOutfitToolForPlayer(Player owner, OutfitSelection selection, PlayerSpawnedEquipment.Purpose purpose, int? level, bool platformLocked)
	{
		Dictionary<string, object> dictionary = new Dictionary<string, object>();
		dictionary.Add("Owner", owner.PhotonPlayer.ID);
		dictionary.Add("Purpose", (int)purpose);
		dictionary.Add("OutfitSelection", selection.ToString());
		Dictionary<string, object> instantiationParameters = dictionary;
		Tool tool = Tool.PhotonInstantiate(outfitToolPrefab.name, new Vector3(0f, -60f, 0f), Quaternion.identity, 1f, base.photonView.viewID, instantiationParameters);
		OutfitTool result = ((!(tool != null)) ? null : tool.GetComponent<OutfitTool>());
		if (purpose == PlayerSpawnedEquipment.Purpose.Drawer)
		{
			tool.SuppressAnimateInOut = true;
		}
		if (tool.PlayerSpawnedEquipment != null)
		{
			OutfitSelection outfitSelection = UnlockedOutfitSelections.FindLast((OutfitSelection s) => s.Equals(selection));
			if (outfitSelection != null)
			{
				tool.PlayerSpawnedEquipment.Level = outfitSelection.Level;
				tool.PlayerSpawnedEquipment.IsNew = outfitSelection.IsNew;
			}
			else
			{
				tool.PlayerSpawnedEquipment.IsNew = true;
				if (level.HasValue)
				{
					tool.PlayerSpawnedEquipment.Level = level.Value;
				}
			}
			tool.PlayerSpawnedEquipment.IsPlatformLocked = platformLocked;
		}
		return result;
	}

	public GameObject SpawnOutfitImposter(OutfitSelection selection)
	{
		if (outfitImposterSource == null)
		{
			outfitImposterSource = UnityEngine.Object.Instantiate(outfitImposterPrefab).GetComponent<OutfitRenderSetup>();
			UnityEngine.Object.DontDestroyOnLoad(outfitImposterSource.gameObject);
			outfitImposterSource.gameObject.hideFlags = HideFlags.HideAndDontSave;
		}
		outfitImposterSource.gameObject.SetActive(value: true);
		outfitImposterSource.OutfitSelection = selection;
		GameObject result = VisualImposter.SpawnImposter(outfitImposterSource.gameObject, null, preserveColliders: true).gameObject;
		outfitImposterSource.gameObject.SetActive(value: false);
		return result;
	}

	public OutfitTool SpawnOutfitToolForLocalPlayer(OutfitSelection selection, PlayerSpawnedEquipment.Purpose purpose, int? level, bool platformLocked = false)
	{
		return SpawnOutfitToolForPlayer(Player.LocalPlayer, selection, purpose, level, platformLocked);
	}

	public void DebugFillTheDefaultSelection()
	{
		AnalyticsHelper.DebugAction("UnlockAllOutfits");
	}
}
namespace RecRoom
{
	public class OutfitRenderSetup : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private bool fixCentering;

		[SerializeField]
		private Renderer _ghostRenderer;

		[SerializeField]
		private Renderer _itemRenderer;

		private OutfitSelection _outfitSelection;

		public Renderer GhostRenderer => _ghostRenderer;

		public Renderer ItemRenderer => _itemRenderer;

		public OutfitSelection OutfitSelection
		{
			get
			{
				return _outfitSelection;
			}
			set
			{
				_outfitSelection = value;
				SkinnedMeshRenderer sourceMeshRenderer = _outfitSelection.outfitItem.SourceMeshRenderer;
				SetupRenderers(sourceMeshRenderer);
			}
		}

		public void SetupRenderers(SkinnedMeshRenderer prefabItemRenderer)
		{
			MeshFilter component = _itemRenderer.GetComponent<MeshFilter>();
			component.sharedMesh = prefabItemRenderer.sharedMesh;
			_itemRenderer.materials = prefabItemRenderer.sharedMaterials;
			if (OutfitSelection.mask != null)
			{
				AvatarMask.Apply(OutfitSelection.mask, _itemRenderer.material);
			}
			if (OutfitSelection.decal != null)
			{
				AvatarDecal.Apply(OutfitSelection.decal, _itemRenderer.material);
			}
			if (OutfitSelection.colorSwatch != null)
			{
				AvatarColorSwatch.Apply(OutfitSelection.colorSwatch, _itemRenderer.material);
			}
			if (Player.LocalPlayerExists && OutfitSelection.outfitItem.UsesHairColor)
			{
				Color color = Player.LocalPlayer.PlayerOutfit.HairColor.color;
				Color color2 = Player.LocalPlayer.PlayerOutfit.BeardColor.color;
				for (int i = 0; i < ItemRenderer.materials.Length; i++)
				{
					if (OutfitSelection.outfitItem.Type == OutfitManager.OutfitType.Mouth)
					{
						ItemRenderer.materials[i].color = color2;
					}
					else
					{
						ItemRenderer.materials[i].color = color;
					}
				}
			}
			if (_ghostRenderer != null)
			{
				_ghostRenderer.GetComponent<MeshFilter>().sharedMesh = prefabItemRenderer.sharedMesh;
				_ghostRenderer.materials = prefabItemRenderer.sharedMaterials;
				Material[] array = new Material[_ghostRenderer.materials.Length];
				for (int j = 0; j < _ghostRenderer.materials.Length; j++)
				{
					array[j] = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitGhostMaterial;
				}
				_ghostRenderer.materials = array;
			}
			BoxCollider[] componentsInChildren = GetComponentsInChildren<BoxCollider>();
			foreach (BoxCollider boxCollider in componentsInChildren)
			{
				boxCollider.center = component.mesh.bounds.center;
				boxCollider.size = component.mesh.bounds.size;
			}
			if (fixCentering)
			{
				_itemRenderer.transform.localPosition = base.transform.position - component.mesh.bounds.center;
			}
		}
	}
}
