public class OutfitToolUIControl : UnityEngine.MonoBehaviour
{
	[Flags]
	public enum ItemProgressionState
	{
		None = 0,
		LevelLocked = 1,
		New = 2,
		Favorite = 4,
		Wearing = 8,
		PlatformLocked = 0x10
	}

	[Header("Locked Item Controls")]
	[SerializeField]
	private Text lockLevelText;

	[SerializeField]
	private GameObject lockPlatformText;

	[SerializeField]
	private UnityEngine.UI.Image lockIcon;

	[Header("New Item Controls")]
	[SerializeField]
	private GameObject newItemIcon;

	[Header("Favorite Item Controls")]
	[SerializeField]
	private GameObject favoriteItemIcon;

	[Header("Wearing Item Controls")]
	[SerializeField]
	private GameObject wearingItemIcon;

	private Vector3 offset = Vector3.zero;

	[SerializeField]
	private ItemProgressionState _state;

	public ItemProgressionState State
	{
		get
		{
			return _state;
		}
		set
		{
			_state = value;
			lockLevelText.gameObject.SetActive(value: false);
			lockIcon.gameObject.SetActive(value: false);
			newItemIcon.gameObject.SetActive(value: false);
			favoriteItemIcon.gameObject.SetActive(value: false);
			wearingItemIcon.gameObject.SetActive(value: false);
			lockPlatformText.SetActive(value: false);
			if (_state.HasFlag(ItemProgressionState.LevelLocked))
			{
				lockLevelText.gameObject.SetActive(value: true);
				lockIcon.gameObject.SetActive(value: true);
			}
			if ((_state & ItemProgressionState.New) == ItemProgressionState.New)
			{
				newItemIcon.gameObject.SetActive(value: true);
			}
			if ((_state & ItemProgressionState.Favorite) == ItemProgressionState.Favorite)
			{
				favoriteItemIcon.gameObject.SetActive(value: true);
			}
			if ((_state & ItemProgressionState.Wearing) == ItemProgressionState.Wearing)
			{
				wearingItemIcon.gameObject.SetActive(value: true);
			}
			if ((_state & ItemProgressionState.PlatformLocked) == ItemProgressionState.PlatformLocked)
			{
				lockPlatformText.SetActive(value: true);
				lockIcon.gameObject.SetActive(value: true);
			}
		}
	}

	public void SetLockLevel(int level)
	{
		lockLevelText.text = level.ToString();
	}

	public void UpdatePlacement(Tool tool)
	{
		base.transform.SetParent(tool.transform, worldPositionStays: false);
		base.transform.localPosition = Vector3.zero;
		Bounds colliderBounds = tool.GetColliderBounds();
		Vector3 point = base.transform.position + Vector3.up;
		Vector3 vector = colliderBounds.ClosestPoint(point);
		float magnitude = (vector - base.transform.position).magnitude;
		offset = new Vector3(0f, magnitude + 0.05f, 0f);
		base.transform.localPosition = offset;
	}
}
public class OutfitTrigger : UnityEngine.MonoBehaviour
{
	private static readonly Quaternion SKINNED_TOOL_PICKUP_ROTATION = Quaternion.Euler(new Vector3(-90f, 0f, 0f));

	private static readonly Quaternion UNSKINNED_TOOL_PICKUP_ROTATION = Quaternion.Euler(new Vector3(90f, 0f, 0f));

	private OutfitTool _sceneTool;

	private BoxCollider boxCollider;

	public OutfitItem OutfitItem { get; private set; }

	public OutfitTool SceneTool
	{
		get
		{
			if (_sceneTool == null)
			{
				_sceneTool = OutfitTool.LocalFind(OutfitItem.Selection, PlayerSpawnedEquipment.Purpose.Drawer);
			}
			return _sceneTool;
		}
	}

	public Transform TargetTransform { get; set; }

	public bool EnabledOutsideDormRoom { get; set; }

	public void SetOutfitOwner(OutfitItem outfitItem)
	{
		OutfitItem = outfitItem;
		TargetTransform = outfitItem.RendererRoot;
		if (boxCollider != null)
		{
			UnityEngine.Object.Destroy(boxCollider);
			boxCollider = null;
		}
		boxCollider = base.gameObject.AddComponent<BoxCollider>();
		boxCollider.isTrigger = true;
		base.gameObject.layer = 15;
		base.name = outfitItem.name + "_trigger";
		RefreshBounds();
	}

	public void PositionToolForPickup(OutfitTool outfitTool)
	{
		outfitTool.transform.position = base.transform.position;
		outfitTool.transform.rotation = ((!(OutfitItem.ActiveRenderer is SkinnedMeshRenderer)) ? (base.transform.rotation * UNSKINNED_TOOL_PICKUP_ROTATION) : (base.transform.rotation * SKINNED_TOOL_PICKUP_ROTATION));
	}

	private void LateUpdate()
	{
		if (TargetTransform != null)
		{
			base.transform.position = TargetTransform.position;
			base.transform.rotation = TargetTransform.rotation;
		}
	}

	private void RefreshBounds()
	{
		Bounds localBounds = OutfitItem.LocalBounds;
		boxCollider.center = localBounds.center;
		boxCollider.size = localBounds.size;
	}
}
public class IgnoreableRenderer
{
	public Renderer Renderer;

	public int SubmeshCount;

	public bool HideOnly;

	private bool warnedOnce;

	public void RenderAsIgnored(UnityEngine.MonoBehaviour owner, Player ignoringPlayer, Player ignoredPlayer, float minAlpha = -1f, bool hide = false)
	{
		if (CanRender(owner))
		{
			if (hide || HideOnly)
			{
				IgnoreEffectRenderer.HideIgnoredItem(Renderer, SubmeshCount);
			}
			else
			{
				IgnoreEffectRenderer.RenderIgnoredItem(Renderer, SubmeshCount, ignoringPlayer, ignoredPlayer, minAlpha);
			}
		}
	}

	public void RenderAsIgnored(UnityEngine.MonoBehaviour owner, CameraIgnoreBubble camera, bool hide = false)
	{
		RenderAsIgnored(owner, camera.transform.position, camera.FadeStartDistance, camera.FadeCompleteDistance, camera.MinAlpha);
	}

	public void RenderAsIgnored(UnityEngine.MonoBehaviour owner, Vector3 fadeCenter, float fadeStartDistance, float fadeCompleteDistance, float minAlpha = -1f, bool hide = false)
	{
		if (CanRender(owner))
		{
			if (hide || HideOnly)
			{
				IgnoreEffectRenderer.HideIgnoredItem(Renderer, SubmeshCount);
			}
			else
			{
				IgnoreEffectRenderer.RenderIgnoredItem(Renderer, SubmeshCount, hideOnly: false, fadeCenter, fadeStartDistance, fadeCompleteDistance, minAlpha);
			}
		}
	}

	private bool CanRender(UnityEngine.MonoBehaviour owner)
	{
		if (!Renderer)
		{
			if (!warnedOnce)
			{
				warnedOnce = true;
				UnityEngine.Debug.LogErrorFormat(owner, "IgnoreableRenderer is missing a Renderer component (owner: {0})", owner.gameObject.GetGameObjectHierarchy());
			}
			return false;
		}
		warnedOnce = false;
		return Renderer.enabled && Renderer.gameObject.activeInHierarchy;
	}
}
public class PlayerIgnoreVisual : UnityEngine.MonoBehaviour
{
	private const float MIN_ALPHA_NEAR_TEAMMATES = 0.15f;

	[SerializeField]
	[Tooltip("Used to access the outfits that are associated with this body part.")]
	private Player.BodyPart bodyPart = Player.BodyPart.None;

	[SerializeField]
	private OutfitItem customOutfitItem;

	[SerializeField]
	[FormerlySerializedAs("ignoredRenderers")]
	private List<Renderer> skippedRenderers;

	[SerializeField]
	[Tooltip("Instead of changing the material, simply disable these renderers.")]
	private List<Renderer> disabledRenderers;

	[SerializeField]
	[Tooltip("The radius around the pivot to compare against the ignore buffers")]
	private float bufferRadius = 0.15f;

	private List<IgnoreableRenderer> trackedRenderers;

	private GameManager gameManager;

	private Player ignoringPlayer;

	private CameraIgnoreBubble ignoringCamera;

	private float minAlpha = -1f;

	private IDisposable staggeredUpdateToken;

	private IDisposable renderUpdateToken;

	private bool _ignored;

	private bool initialized;

	private Color ignoreAccentColor = Color.white;

	private List<OutfitItem> outfitItems = new List<OutfitItem>();

	public Player ThisPlayer { get; private set; }

	private bool Ignored
	{
		get
		{
			return _ignored;
		}
		set
		{
			if (_ignored != value)
			{
				_ignored = value;
				if (Ignored && base.enabled && base.gameObject.activeInHierarchy)
				{
					StartIgnoredRenderUpdate();
				}
				else
				{
					StopIgnoredRenderUpdate();
				}
			}
		}
	}

	public float BufferRadius => bufferRadius;

	private void Awake()
	{
		trackedRenderers = new List<IgnoreableRenderer>();
	}

	private IEnumerator Start()
	{
		ThisPlayer = GetComponentInParent<Player>();
		if (ThisPlayer != null)
		{
			yield return new WaitUntil(() => Player.LocalPlayerExists && Player.LocalPlayer.IsInitialized);
			AddValidRenderersFromGameObject(base.gameObject);
			if (bodyPart.IsHand())
			{
				LaserTeleporter laserTeleporter = ((bodyPart != Player.BodyPart.LeftHand) ? ThisPlayer.RightHand.PlayerHandRemote : ThisPlayer.LeftHand.PlayerHandRemote);
				if (laserTeleporter != null)
				{
					AddValidRenderersFromGameObject(laserTeleporter.gameObject);
				}
			}
			ThisPlayer.PlayerOutfit.OutfitSelectionChanged += PlayerOutfit_OutfitSelectionChanged;
			PlayerOutfit_OutfitSelectionChanged();
			gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (gameManager != null)
			{
				gameManager.TeamManager.TeamChangeEvent += OnGameTeamChange;
			}
		}
		this.Update10hz(StaggeredUpdate);
		initialized = true;
	}

	private void OnEnable()
	{
		if (Ignored)
		{
			StartIgnoredRenderUpdate();
		}
	}

	private void OnDisable()
	{
		StopIgnoredRenderUpdate();
	}

	protected void OnDestroy()
	{
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnGameTeamChange;
		}
	}

	private void StaggeredUpdate(float deltaTime)
	{
		if (initialized && ThisPlayer != null)
		{
			Ignored = CheckShouldIgnore(out minAlpha, out ignoringPlayer, out ignoringCamera);
		}
	}

	private void AddValidRenderersFromGameObject(GameObject go)
	{
		Renderer[] componentsInChildren = go.GetComponentsInChildren<Renderer>(includeInactive: true);
		if (componentsInChildren == null)
		{
			return;
		}
		Renderer[] array = componentsInChildren;
		foreach (Renderer renderer in array)
		{
			if (renderer is ParticleSystemRenderer || renderer is LineRenderer || renderer.gameObject.layer == 29 || !(renderer.gameObject.tag != "OutfitRenderer") || skippedRenderers.Contains(renderer) || !(renderer.GetComponentInParent<Tool>() == null) || !(GetComponentInParent<PlayerIgnoreVisual>() == this))
			{
				continue;
			}
			bool flag = false;
			for (int j = 0; j < trackedRenderers.Count; j++)
			{
				if (trackedRenderers[j].Renderer == renderer)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				trackedRenderers.Add(new IgnoreableRenderer
				{
					Renderer = renderer,
					SubmeshCount = renderer.GetSubmeshCount(),
					HideOnly = disabledRenderers.Contains(renderer)
				});
			}
		}
	}

	private void OnGameTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		if (ThisPlayer != null)
		{
			GameTeam playerTeam = gameManager.TeamManager.GetPlayerTeam(ThisPlayer.PhotonPlayer);
			ignoreAccentColor = ((playerTeam == GameTeam.ANY) ? Color.white : NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam));
			Ignored = false;
		}
	}

	private void PlayerOutfit_OutfitSelectionChanged()
	{
		if (bodyPart == Player.BodyPart.None)
		{
			return;
		}
		outfitItems.Clear();
		foreach (OutfitSelectionToBody outfitSelection in ThisPlayer.PlayerOutfit.OutfitSelections)
		{
			if (outfitSelection.bodyPart == bodyPart || (bodyPart == Player.BodyPart.Head && outfitSelection.bodyPart == Player.BodyPart.Mouth))
			{
				outfitItems.Add(outfitSelection.selection.outfitItem);
			}
		}
	}

	private bool CheckShouldIgnore(out float minAlpha, out Player ignoringPlayer, out CameraIgnoreBubble ignoringCamera)
	{
		minAlpha = -1f;
		ignoringPlayer = null;
		ignoringCamera = null;
		if (ThisPlayer.isLocal)
		{
			float num = float.MaxValue;
			Player localPlayer = Player.LocalPlayer;
			List<Player> all = Player.All;
			for (int i = 0; i < all.Count; i++)
			{
				Player player = all[i];
				if (player != localPlayer && !player.DisplayAsIgnored && IgnoreEffectRenderer.ShouldIgnorePlayerVisual(player, this, out var projectedSqDistance) && projectedSqDistance < num)
				{
					num = projectedSqDistance;
					ignoringPlayer = player;
				}
			}
			if (ignoringPlayer != null && gameManager != null && gameManager.CurrentMode.CombatSettings.SupportsPlayerReviving && gameManager.IsGameRunning && gameManager.TeamManager.PlayersAreTeammates(ThisPlayer.PhotonPlayer, ignoringPlayer.PhotonPlayer))
			{
				minAlpha = 0.15f;
			}
		}
		else if (Player.LocalPlayerExists)
		{
			Player localPlayer2 = Player.LocalPlayer;
			if (IgnoreEffectRenderer.ShouldIgnorePlayerVisual(localPlayer2, this))
			{
				ignoringPlayer = localPlayer2;
			}
		}
		if (ignoringPlayer == null)
		{
			foreach (CameraIgnoreBubble allBubble in CameraIgnoreBubble.AllBubbles)
			{
				if (IgnoreEffectRenderer.ShouldIgnorePlayerVisual(allBubble, this))
				{
					ignoringCamera = allBubble;
					break;
				}
			}
		}
		return ignoringPlayer != null || ignoringCamera != null;
	}

	private void StartIgnoredRenderUpdate()
	{
		StopIgnoredRenderUpdate();
		renderUpdateToken = this.Update(RenderAsIgnored);
	}

	private void StopIgnoredRenderUpdate()
	{
		if (renderUpdateToken != null)
		{
			renderUpdateToken.Dispose();
			renderUpdateToken = null;
		}
	}

	private void RenderAsIgnored()
	{
		bool hide = ThisPlayer.DisplayAsIgnored && (bodyPart.IsHand() || bodyPart == Player.BodyPart.None);
		if (ignoringPlayer != null)
		{
			foreach (IgnoreableRenderer trackedRenderer in trackedRenderers)
			{
				trackedRenderer.RenderAsIgnored(this, ignoringPlayer, ThisPlayer, minAlpha, hide);
			}
			foreach (OutfitItem outfitItem in outfitItems)
			{
				if (outfitItem != null)
				{
					outfitItem.RenderAsIgnored(ignoringPlayer, ThisPlayer, ignoreAccentColor, minAlpha, hide);
				}
			}
			if (customOutfitItem != null)
			{
				customOutfitItem.RenderAsIgnored(ignoringPlayer, ThisPlayer, ignoreAccentColor, minAlpha, hide);
			}
		}
		else
		{
			if (!(ignoringCamera != null))
			{
				return;
			}
			foreach (IgnoreableRenderer trackedRenderer2 in trackedRenderers)
			{
				trackedRenderer2.RenderAsIgnored(this, ignoringCamera, hide);
			}
			foreach (OutfitItem outfitItem2 in outfitItems)
			{
				if (outfitItem2 != null)
				{
					outfitItem2.RenderAsIgnored(ignoringCamera, ignoreAccentColor, hide);
				}
			}
			if (customOutfitItem != null)
			{
				customOutfitItem.RenderAsIgnored(ignoringCamera, ignoreAccentColor, hide);
			}
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.cyan;
		Gizmos.DrawWireSphere(base.transform.position, bufferRadius);
	}
}
namespace RecRoom
{
	public class PlayerLODGroupHelper : UnityEngine.MonoBehaviour
	{
		private const int EXPECTED_MAX_OUTFIT_ITEMS = 10;

		[SerializeField]
		private LODGroup lodGroup;

		[SerializeField]
		private int maxOutfitLod = 2;

		private Coroutine setLodRoutine;

		private LOD[] lods;

		private List<Renderer>[] lodRenderers;

		private bool lodsDirty;

		private void Awake()
		{
			lods = lodGroup.GetLODs();
			lodRenderers = new List<Renderer>[lods.Length];
			for (int i = 0; i < lods.Length; i++)
			{
				Renderer[] renderers = lods[i].renderers;
				lodRenderers[i] = new List<Renderer>(renderers.Length + 10);
				lodRenderers[i].AddRange(renderers);
			}
		}

		private void OnEnable()
		{
			if (lodsDirty)
			{
				TryRunDeferredSetLODs();
			}
		}

		public void AddOutfitRenderer(Renderer renderer)
		{
			for (int i = 0; i <= maxOutfitLod; i++)
			{
				lodRenderers[i].Add(renderer);
			}
			TryRunDeferredSetLODs();
		}

		private void TryRunDeferredSetLODs()
		{
			if (base.gameObject.activeInHierarchy)
			{
				this.SafeStopCoroutine(setLodRoutine);
				setLodRoutine = StartCoroutine(DeferredSetLODs());
			}
		}

		private IEnumerator DeferredSetLODs()
		{
			yield return CoroutineExt.EndOfFrame;
			RemoveNullRenderers();
			SetLODRenderers();
			yield return null;
			lodGroup.RecalculateBounds();
			lodsDirty = false;
		}

		private void RemoveNullRenderers()
		{
			for (int i = 0; i < lodRenderers.Length; i++)
			{
				List<Renderer> list = lodRenderers[i];
				for (int num = list.Count - 1; num >= 0; num--)
				{
					if (list[num] == null)
					{
						list.RemoveAt(num);
						num--;
					}
				}
			}
		}

		private void SetLODRenderers()
		{
			for (int i = 0; i < lods.Length; i++)
			{
				List<Renderer> list = lodRenderers[i];
				lods[i].renderers = list.ToArray();
			}
			lodGroup.SetLODs(lods);
		}
	}
}
