	public static void ApplyLocalPlayerAvatarSettings(RecNet.Avatar avatar)
	{
		SynchronizedField.SetLocalPlayerValue("HairColorProp", avatar.HairColor);
		SynchronizedField.SetLocalPlayerValue("SkinColorProp", avatar.SkinColor);
		SynchronizedField.SetLocalPlayerValue("FaceFeaturesProp", avatar.FaceFeatures);
		SynchronizedField.SetLocalPlayerValue("OutFitProp", avatar.OutfitSelections);
	}

	private void ApplyFaceSettingsToFacialAnimator()
	{
		if (FaceFeatures != null)
		{
			Player component = GetComponent<Player>();
			if (component != null)
			{
				component.FacialAnimator.SetFaceSettings(FaceFeatures);
			}
		}
	}

	private void ValidateFaceFeatures(AvatarFaceSettings settings)
	{
		if (settings == null)
		{
			settings = new AvatarFaceSettings();
		}
		Player component = GetComponent<Player>();
		if (string.IsNullOrEmpty(settings.EyeGuid) || !component.FacialAnimator.IsValidGuid(FaceFeatureType.Eye, settings.EyeGuid))
		{
			if (!string.IsNullOrEmpty(settings.EyeGuid))
			{
				UnityEngine.Debug.LogWarningFormat("Could not find face feature (eye) asset for guid {0}. Choosing default option.", settings.EyeGuid);
			}
			settings.EyeGuid = component.FacialAnimator.GetDefaultFaceFeatureGuid(FaceFeatureType.Eye);
		}
		if (string.IsNullOrEmpty(settings.MouthGuid) || !component.FacialAnimator.IsValidGuid(FaceFeatureType.Mouth, settings.MouthGuid))
		{
			if (!string.IsNullOrEmpty(settings.MouthGuid))
			{
				UnityEngine.Debug.LogWarningFormat("Could not find face feature (mouth) asset for guid {0}. Choosing default option.", settings.MouthGuid);
			}
			settings.MouthGuid = component.FacialAnimator.GetDefaultFaceFeatureGuid(FaceFeatureType.Mouth);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		outfitBodyMapping = new OutfitItem.OutfitBodyMapping
		{
			head = headAnchor,
			torso = torsoAnchor,
			leftHand = new OutfitItem.OutfitAnimatedBodyMapping
			{
				renderer = leftHand,
				animator = leftHandAnimator
			},
			rightHand = new OutfitItem.OutfitAnimatedBodyMapping
			{
				renderer = rightHand,
				animator = rightHandAnimator
			}
		};
		_hairColorPlayerProperty = new SynchronizedPlayerField<string>(base.owner, "HairColorProp", string.Empty, OnPlayerHairColorChanged);
		_skinColorPlayerProperty = new SynchronizedPlayerField<string>(base.owner, "SkinColorProp", string.Empty, OnPlayerSkinColorChanged);
		_facefeaturesPlayerProperty = new SynchronizedPlayerField<string>(base.owner, "FaceFeaturesProp", string.Empty, OnPlayerFaceFeaturesChanged);
		_outfitListPlayerProperty = new SynchronizedPlayerField<string>(base.owner, "OutFitProp", string.Empty, OnPlayerOutfitChanged);
	}

	private void Start()
	{
		OnPlayerOutfitChanged();
		OnPlayerFaceFeaturesChanged();
		OnPlayerSkinColorChanged();
		OnPlayerHairColorChanged();
		if (isLocal)
		{
			bool flag = true;
			if (string.IsNullOrEmpty(HairColorPlayerProperty))
			{
				flag = false;
				SetHairColor(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(string.Empty).guidString);
			}
			bool flag2 = true;
			if (string.IsNullOrEmpty(SkinColorPlayerProperty))
			{
				flag2 = false;
				SetSkinColor(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindSkinColor(string.Empty).guidString);
			}
			if (string.IsNullOrEmpty(FaceFeaturesPlayerProperty))
			{
				if (!flag && !flag2)
				{
					SetFaceFeatures(GetRandomFaceSettings());
				}
				else
				{
					SetFaceFeatures(GetDefaultFaceSettings());
				}
			}
			else if (FaceFeatures != null && string.IsNullOrEmpty(FaceFeatures.BeardColorGuid))
			{
				if (HairColor != null)
				{
					SetBeardColor(HairColor.guidString);
				}
				else
				{
					SetBeardColor(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(string.Empty).guidString);
				}
			}
			if (string.IsNullOrEmpty(OutfitListPlayerProperty))
			{
				SetOutfit(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.GetInitialRandomOutfitSelection());
			}
			EquipDefaultOutfitSetForMissing();
			EquipTeamOutfits();
			SnapShotOutfitSelection();
			SnapShotAppearanceSelection();
		}
		player.VisibilityChanged += ThisPlayer_VisibilityChanged;
	}

	private void DelayedLocalSaveAvatar()
	{
		if (isLocal && !saveAvatarQueued)
		{
			saveAvatarQueued = true;
			this.WaitRoutine(1f, delegate
			{
				Avatars.SaveLocalAvatarSettings();
				saveAvatarQueued = false;
			});
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (outfitSelectionToBody != null && outfitSelectionToBody.selection.outfitItem != null)
			{
				UnityEngine.Object.Destroy(outfitSelectionToBody.selection.outfitItem.gameObject);
			}
		}
		outfitSelections.Clear();
		player.VisibilityChanged -= ThisPlayer_VisibilityChanged;
	}

	public OutfitSelection GetSelection(Player.BodyPart bodyPart)
	{
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.bodyPart == bodyPart)
			{
				return outfitSelection.selection;
			}
		}
		return null;
	}

	private void EquipTeamOutfits()
	{
		if (!(NetworkedSingletonMonoBehaviour<GameManager>.Instance != null))
		{
			return;
		}
		if (AGRoomSettings.TryGetRoomSceneLocationCustomTeamColors(GameSessions.LocalGameSession.Location, out var colorSettings) && colorSettings.TeamOutfitColorEmissionEnabled)
		{
			foreach (OutfitSelectionToBody item in NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.TeamOutfitsEmissive)
			{
				SetOutfit(item, playAudio: false);
			}
			return;
		}
		foreach (OutfitSelectionToBody teamOutfit in NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.TeamOutfits)
		{
			SetOutfit(teamOutfit, playAudio: false);
		}
	}

	private void ThisPlayer_VisibilityChanged(bool visible)
	{
		if (isLocal)
		{
			return;
		}
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			outfitSelection.selection.outfitItem.SetVisible(visible, playerVisibilityToken);
		}
	}

	private void OnPlayerSkinColorChanged()
	{
		SkinColor = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindSkinColor(SkinColorPlayerProperty);
	}

	private void OnPlayerHairColorChanged()
	{
		HairColor = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(HairColorPlayerProperty);
	}

	private void OnPlayerFaceFeaturesChanged()
	{
		AvatarFaceSettings avatarFaceSettings = AvatarFaceSettings.Deserialize(FaceFeaturesPlayerProperty);
		ValidateFaceFeatures(avatarFaceSettings);
		FaceFeatures = avatarFaceSettings;
		BeardColor = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(FaceFeatures.BeardColorGuid);
	}

	private void OnPlayerOutfitChanged()
	{
		EquipOutfitFromString(OutfitListPlayerProperty);
	}

	private void EquipDefaultOutfitSetForMissing()
	{
		List<OutfitSelectionToBody> missingOutfitsFromDefaultSet = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.GetMissingOutfitsFromDefaultSet(outfitSelections);
		foreach (OutfitSelectionToBody item in missingOutfitsFromDefaultSet)
		{
			SetOutfit(item, playAudio: false);
		}
	}

	private void UpdateTeamOutfits()
	{
		bool hasValue = TeamColor.HasValue;
		Color color = ((!hasValue) ? Color.white : TeamColor.Value);
		Color value = ((!TeamOutfitColorEmissionEnabled) ? color : (color * TeamOutfitColorEmissionAmount));
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (OutfitManager.IsTeamOutfit(outfitSelection.selection.outfitItem.Type))
			{
				outfitSelection.selection.outfitItem.SetVisible(hasValue, teamOutfitVisibleToken);
				if (hasValue)
				{
					outfitSelection.selection.outfitItem.ActiveRenderer.material.color = color;
					if (TeamOutfitColorEmissionEnabled && outfitSelection.selection.outfitItem.ActiveRenderer.material.IsKeywordEnabled("_EMISSION"))
					{
						outfitSelection.selection.outfitItem.ActiveRenderer.material.SetColor("_EmissionColor", value);
					}
				}
			}
			else
			{
				Player.BodyPart matchingBodyPart = OutfitManager.GetMatchingBodyPart(outfitSelection.selection.outfitItem.Type);
				if (matchingBodyPart.IsHand())
				{
					outfitSelection.selection.outfitItem.SetVisible(!hasValue, teamOutfitVisibleToken);
				}
			}
		}
	}

	public string GetOutfitNameList()
	{
		string text = string.Empty;
		for (int i = 0; i < outfitSelections.Count; i++)
		{
			text = text + outfitSelections[i].selection.outfitItem.name + ((i == outfitSelections.Count - 1) ? string.Empty : ",");
		}
		return text;
	}

	public void UnEquipAll()
	{
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody selectionToBody in array)
		{
			UnEquipOutfit(selectionToBody);
		}
	}

	public void SetHandVisible(PlayerHand.HandType type, bool isVisible)
	{
		int num;
		switch (type)
		{
		case PlayerHand.HandType.Unknown:
			return;
		case PlayerHand.HandType.Left:
			num = 2;
			break;
		default:
			num = 3;
			break;
		}
		Player.BodyPart bodyPart = (Player.BodyPart)num;
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.selection.outfitItem.CurrentBodyPart == bodyPart)
			{
				outfitSelection.selection.outfitItem.SetVisible(isVisible, handVisibleToken);
			}
		}
	}

	public void SetSkinColor(string colorGuid, bool logChange = false)
	{
		SkinColorPlayerProperty = colorGuid;
		Avatars.LocalAvatar.SkinColor = colorGuid;
		DelayedLocalSaveAvatar();
		if (logChange)
		{
			AnalyticsHelper.AvatarSkinColor(colorGuid);
		}
	}

	public void SetHairColor(string colorGuid, bool logChange = false)
	{
		HairColorPlayerProperty = ApplyConsumableHairColorOverrideIfApplicable(colorGuid);
		Avatars.LocalAvatar.HairColor = colorGuid;
		DelayedLocalSaveAvatar();
		if (logChange)
		{
			AnalyticsHelper.AvatarHairColor(colorGuid);
		}
	}

	public void ApplyHairColorOverride(string colorGuid)
	{
		HairColorPlayerProperty = colorGuid;
		AvatarFaceSettings avatarFaceSettings = AvatarFaceSettings.Deserialize(FaceFeaturesPlayerProperty);
		avatarFaceSettings.BeardColorGuid = colorGuid;
		FaceFeaturesPlayerProperty = avatarFaceSettings.Serialize();
	}

	public void UndoHairColorOverride()
	{
		HairColorPlayerProperty = Avatars.LocalAvatar.HairColor;
		FaceFeaturesPlayerProperty = Avatars.LocalAvatar.FaceFeatures;
	}

	public void SetBeardColor(string colorGuid, bool logChange = false)
	{
		AvatarFaceSettings faceFeatures = FaceFeatures;
		faceFeatures.BeardColorGuid = colorGuid;
		if (logChange)
		{
			AnalyticsHelper.AvatarBeardColor(colorGuid);
		}
		SetFaceFeatures(faceFeatures, logChange);
	}

	public void SetFaceFeatureSelection(FaceFeatureType featureType, string guid, bool logChange = false)
	{
		switch (featureType)
		{
		case FaceFeatureType.Eye:
			FaceFeatures.EyeGuid = guid;
			if (logChange)
			{
				AnalyticsHelper.AvatarEyeSettings();
			}
			break;
		case FaceFeatureType.Mouth:
			FaceFeatures.MouthGuid = guid;
			if (logChange)
			{
				AnalyticsHelper.AvatarMouthSettings();
			}
			break;
		default:
			UnityEngine.Debug.LogWarningFormat("Unrecognized feature type: {0}", featureType);
			return;
		}
		SetFaceFeatures(FaceFeatures, logChange);
	}

	public void SetFaceFeaturePositionOffset(FaceFeatureType featureType, Vector2 position, bool logChange = false)
	{
		Player component = GetComponent<Player>();
		if (!(component != null))
		{
			return;
		}
		switch (featureType)
		{
		case FaceFeatureType.Eye:
			FaceFeatures.EyePositionOffset = component.FacialAnimator.ClampFaceFeaturePositionOffset(FaceFeatureType.Eye, position);
			if (logChange)
			{
				AnalyticsHelper.AvatarEyeSettings();
			}
			break;
		case FaceFeatureType.Mouth:
			FaceFeatures.MouthPositionOffset = component.FacialAnimator.ClampFaceFeaturePositionOffset(FaceFeatureType.Mouth, position);
			if (logChange)
			{
				AnalyticsHelper.AvatarMouthSettings();
			}
			break;
		default:
			UnityEngine.Debug.LogWarningFormat("Unrecognized feature type: {0}", featureType);
			return;
		}
		SetFaceFeatures(FaceFeatures, logChange);
	}

	public void SetFaceFeatureScaleOffset(FaceFeatureType featureType, float scale, bool logChange = false)
	{
		Player component = GetComponent<Player>();
		if (!(component != null))
		{
			return;
		}
		switch (featureType)
		{
		case FaceFeatureType.Eye:
			FaceFeatures.EyeScaleOffset = component.FacialAnimator.ClampFaceFeatureScaleOffset(FaceFeatureType.Eye, scale);
			if (logChange)
			{
				AnalyticsHelper.AvatarEyeSettings();
			}
			break;
		case FaceFeatureType.Mouth:
			FaceFeatures.MouthScaleOffset = component.FacialAnimator.ClampFaceFeatureScaleOffset(FaceFeatureType.Mouth, scale);
			if (logChange)
			{
				AnalyticsHelper.AvatarMouthSettings();
			}
			break;
		default:
			UnityEngine.Debug.LogWarningFormat("Unrecognized feature type: {0}", featureType);
			return;
		}
		SetFaceFeatures(FaceFeatures, logChange);
	}

	private void SetFaceFeatures(AvatarFaceSettings newSettings, bool logChange = false)
	{
		if (newSettings != null)
		{
			string text = newSettings.Serialize();
			FaceFeaturesPlayerProperty = ApplyConsumableBeardColorOverrideIfApplicable(text);
			Avatars.LocalAvatar.FaceFeatures = text;
			DelayedLocalSaveAvatar();
			if (logChange)
			{
				AnalyticsHelper.AvatarFaceSettings();
			}
		}
	}

	public List<FaceFeatureBase> GetAvailableFaceFeatures(FaceFeatureType featureType)
	{
		if (Player.LocalPlayerExists)
		{
			return Player.LocalPlayer.FacialAnimator.GetAvailableFeatures(featureType);
		}
		return null;
	}

	public AvatarFaceSettings GetDefaultFaceSettings()
	{
		AvatarFaceSettings avatarFaceSettings = new AvatarFaceSettings();
		avatarFaceSettings.EyeGuid = Player.LocalPlayer.FacialAnimator.GetDefaultFaceFeatureGuid(FaceFeatureType.Eye);
		avatarFaceSettings.MouthGuid = Player.LocalPlayer.FacialAnimator.GetDefaultFaceFeatureGuid(FaceFeatureType.Mouth);
		if (HairColor != null)
		{
			avatarFaceSettings.BeardColorGuid = HairColor.guidString;
		}
		else
		{
			avatarFaceSettings.BeardColorGuid = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(string.Empty).guidString;
		}
		return avatarFaceSettings;
	}

	public AvatarFaceSettings GetRandomFaceSettings()
	{
		AvatarFaceSettings avatarFaceSettings = new AvatarFaceSettings();
		avatarFaceSettings.EyeGuid = Player.LocalPlayer.FacialAnimator.GetRandomFaceFeatureGuid(FaceFeatureType.Eye);
		avatarFaceSettings.MouthGuid = Player.LocalPlayer.FacialAnimator.GetRandomFaceFeatureGuid(FaceFeatureType.Mouth);
		if (HairColor != null)
		{
			avatarFaceSettings.BeardColorGuid = HairColor.guidString;
		}
		else
		{
			avatarFaceSettings.BeardColorGuid = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(string.Empty).guidString;
		}
		return avatarFaceSettings;
	}

	public void SetOutfit(List<OutfitSelectionToBody> pieces)
	{
		for (int i = 0; i < pieces.Count; i++)
		{
			SetOutfit(pieces[i], playAudio: false);
		}
	}

	public bool SetOutfitByHand(OutfitSelection selection, Player.BodyPart bodyPart)
	{
		OutfitSelectionToBody selectionToBody = new OutfitSelectionToBody(selection, bodyPart);
		if (isLocal)
		{
			AnalyticsHelper.AvatarOutfitEquip(selectionToBody, bodyPart, equip: true);
		}
		return SetOutfit(selectionToBody, playAudio: true, byHand: true);
	}

	private bool SetOutfit(OutfitSelectionToBody selectionToBody, bool playAudio)
	{
		return SetOutfit(selectionToBody, playAudio, byHand: false);
	}

	private bool SetOutfit(OutfitSelectionToBody selectionToBody, bool playAudio, bool byHand)
	{
		if (outfitSelections.Contains(selectionToBody))
		{
			return false;
		}
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (outfitSelectionToBody.selection.outfitItem.Type == selectionToBody.selection.outfitItem.Type && outfitSelectionToBody.selection.outfitItem.CurrentBodyPart == selectionToBody.bodyPart && outfitSelectionToBody.selection != selectionToBody.selection)
			{
				UnEquipOutfit(outfitSelectionToBody);
			}
		}
		string text = (OutfitListPlayerProperty = SerializeOutfitSelections(selectionToBody));
		if (!OutfitManager.IsTeamOutfit(selectionToBody.selection.outfitItem.Type))
		{
			Avatars.LocalAvatar.OutfitSelections = text;
			DelayedLocalSaveAvatar();
		}
		if (playAudio)
		{
			PlayOutfitAudio(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.EquipSounds, selectionToBody.bodyPart);
		}
		playerEvents.OutfitEquipped(selectionToBody.bodyPart);
		return true;
	}

	public bool RemoveOutfitByHand(OutfitSelection selection, Player.BodyPart bodyPart)
	{
		OutfitSelectionToBody outfitSelectionToBody = outfitSelections.Where((OutfitSelectionToBody os) => os.selection == selection && os.bodyPart == bodyPart).FirstOrDefault();
		if (outfitSelectionToBody != null)
		{
			if (isLocal)
			{
				AnalyticsHelper.AvatarOutfitEquip(selection, bodyPart, equip: false);
			}
			return RemoveOutfit(outfitSelectionToBody, playAudio: true, byHand: true);
		}
		return false;
	}

	private bool RemoveOutfit(OutfitSelectionToBody selectionToBody, bool playAudio, bool byHand)
	{
		if (!outfitSelections.Contains(selectionToBody))
		{
			return false;
		}
		UnEquipOutfit(selectionToBody);
		string text = (OutfitListPlayerProperty = SerializeOutfitSelections());
		Avatars.LocalAvatar.OutfitSelections = text;
		DelayedLocalSaveAvatar();
		if (playAudio)
		{
			PlayOutfitAudio(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.UnEquipSounds, selectionToBody.bodyPart);
		}
		return true;
	}

	private void PlayOutfitAudio(RecRoomAudioClip[] audioClips, Player.BodyPart bodyPart)
	{
		AudioManager.PlayRandom3DSFX(audioClips, bodyPart switch
		{
			Player.BodyPart.LeftHand => player.LeftHand.transform.position, 
			Player.BodyPart.RightHand => player.RightHand.transform.position, 
			Player.BodyPart.Torso => player.Body.transform.position, 
			_ => player.Head.transform.position, 
		});
	}

	public string SerializeOutfitSelections(OutfitSelectionToBody selectionToBody = null)
	{
		string text = string.Empty;
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			text = text + outfitSelection.ToString() + ";";
		}
		if (selectionToBody != null)
		{
			text += selectionToBody.ToString();
		}
		return text;
	}

	private static List<OutfitSelectionToBody> ParseOutfitString(string newSelectionsStr)
	{
		List<OutfitSelectionToBody> list = new List<OutfitSelectionToBody>();
		string[] array = newSelectionsStr.Split(';');
		string[] array2 = array;
		foreach (string text in array2)
		{
			if (!string.IsNullOrEmpty(text))
			{
				OutfitSelectionToBody outfitSelectionToBody = OutfitSelectionToBody.Parse(text);
				if (outfitSelectionToBody != null)
				{
					list.Add(outfitSelectionToBody);
				}
				else
				{
					UnityEngine.Debug.LogWarning("PlayerOutfit outfit map parse error. This means we changed a GUID or deleted an item. GUID : " + text);
				}
			}
		}
		return list;
	}

	private void EquipOutfitFromString(string outfitString)
	{
		List<OutfitSelectionToBody> list = ParseOutfitString(outfitString);
		OutfitSelectionToBody[] array = outfitSelections.ToArray();
		foreach (OutfitSelectionToBody outfitSelectionToBody in array)
		{
			if (!list.Contains(outfitSelectionToBody))
			{
				UnEquipOutfit(outfitSelectionToBody);
			}
		}
		foreach (OutfitSelectionToBody item in list)
		{
			if (item != null && item.selection != null && item.selection.outfitItem != null && !outfitSelections.Contains(item))
			{
				EquipOutfit(item);
			}
		}
		if (isLocal)
		{
			EquipDefaultOutfitSetForMissing();
		}
		UpdateTeamOutfits();
	}

	private void UnEquipOutfit(OutfitSelectionToBody selectionToBody)
	{
		if (outfitSelections.Contains(selectionToBody))
		{
			outfitSelections.Remove(selectionToBody);
			if (this.OutfitSelectionChanged != null)
			{
				this.OutfitSelectionChanged();
			}
		}
		if (isLocal)
		{
			List<OutfitTool> list = OutfitTool.LocalFindAll(selectionToBody.selection, PlayerSpawnedEquipment.Purpose.Drawer);
			foreach (OutfitTool item in list)
			{
				item.EquipState = OutfitTool.PlayerEquipState.NotWearing;
			}
			OutfitItem outfitItem = selectionToBody.selection.outfitItem;
			if (outfitItem != null && outfitItem.ActiveRenderer != null)
			{
				RemoveOutfitItemPlayerBlobShadow(player, outfitItem.ActiveRenderer);
			}
		}
		UnityEngine.Object.Destroy(selectionToBody.selection.outfitItem.gameObject);
	}

	private void EquipOutfit(OutfitSelectionToBody selectionToBody)
	{
		if (isLocal && NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.UnlockedOutfitSelections.Any((OutfitSelection s) => s.IsPlatformLocked && s == selectionToBody.selection))
		{
			return;
		}
		InstantiatePrefabForOutfit(selectionToBody.selection, selectionToBody.bodyPart);
		if (!isLocal)
		{
			return;
		}
		List<OutfitTool> list = OutfitTool.LocalFindAll(selectionToBody.selection, PlayerSpawnedEquipment.Purpose.Drawer);
		foreach (OutfitTool item in list)
		{
			item.EquipState = OutfitTool.PlayerEquipState.Wearing;
		}
		OutfitItem outfitItem = selectionToBody.selection.outfitItem;
		AddOutfitItemToPlayerBlobShadow(player, outfitItem.ActiveRenderer);
	}

	public OutfitItem InstantiatePrefabForOutfit(OutfitSelection selection, Player.BodyPart bodyPart)
	{
		OutfitItem outfitItem = (selection.outfitItem = InstantiateNewOutfitPrefab(selection, bodyPart, player));
		OutfitSelectionToBody item = new OutfitSelectionToBody(selection, bodyPart);
		outfitSelections.Add(item);
		if (this.OutfitSelectionChanged != null)
		{
			this.OutfitSelectionChanged();
		}
		SetOutfitTarget(outfitItem);
		SetOutFitLayer(outfitItem);
		if (!isLocal)
		{
			outfitItem.SetVisible(player.IsVisible, playerVisibilityToken);
		}
		switch (bodyPart)
		{
		case Player.BodyPart.LeftHand:
			outfitItem.SetVisible(player.LeftHand.DefaultHandVisualsActive, handVisibleToken);
			break;
		case Player.BodyPart.RightHand:
			outfitItem.SetVisible(player.RightHand.DefaultHandVisualsActive, handVisibleToken);
			break;
		}
		player.SetParentPlayerRoot(outfitItem.transform);
		if (isLocal && outfitItem.ActiveRenderer != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR)
		{
			outfitItem.FirstPersonShadowCaster = Player.CreateFirstPersonShadowCaster(outfitItem.ActiveRenderer).gameObject;
		}
		lodGroupHelper.AddOutfitRenderer(outfitItem.ActiveRenderer);
		return outfitItem;
	}

	public static OutfitItem InstantiateNewOutfitPrefab(OutfitSelection selection, Player.BodyPart bodyPart, Player owner, bool belongsToPuppet = false)
	{
		return InstantiateNewOutfitPrefab(selection.outfitItem, bodyPart, owner, selection.decal, selection.mask, selection.colorSwatch, belongsToPuppet);
	}

	public static OutfitItem InstantiateNewOutfitPrefab(OutfitItem outfitItem, Player.BodyPart bodyPart, Player owner, AvatarDecal decal = null, AvatarMask mask = null, AvatarColorSwatch colorSwatch = null, bool belongsToPuppet = false)
	{
		OutfitItem outfitItem2 = UnityEngine.Object.Instantiate(outfitItem);
		outfitItem2.Type = outfitItem.Type;
		if (decal != null)
		{
			outfitItem2.ApplyDecal(decal);
		}
		if (mask != null)
		{
			outfitItem2.ApplyMask(mask);
		}
		if (colorSwatch != null)
		{
			outfitItem2.ApplySwatch(colorSwatch);
		}
		outfitItem2.CurrentBodyPart = bodyPart;
		outfitItem2.Owner = owner;
		if (belongsToPuppet)
		{
			outfitItem2.WornByPuppet = true;
		}
		return outfitItem2;
	}

	private static void AddOutfitItemToPlayerBlobShadow(Player player, Renderer outfitItemRenderer)
	{
		if (outfitItemRenderer != null && player != null && player.BlobShadowProjector != null)
		{
			player.BlobShadowProjector.AddShadowCaster(outfitItemRenderer);
		}
	}

	private static void RemoveOutfitItemPlayerBlobShadow(Player player, Renderer outfitItemRenderer)
	{
		if (outfitItemRenderer != null && player != null && player.BlobShadowProjector != null)
		{
			player.BlobShadowProjector.RemoveShadowCaster(outfitItemRenderer);
		}
	}

	public void SetOutfitTarget(OutfitItem outfitItem)
	{
		outfitItem.BindToBody(outfitBodyMapping);
	}

	private void SetOutFitLayer(OutfitItem outfitItem)
	{
		Layers layer = Layers.RemotePlayerPhysics;
		if (isLocal)
		{
			layer = ((!outfitItem.CurrentBodyPart.IsHand()) ? Layers.HiddenInFirstPerson : Layers.LocalPlayerPhysics);
		}
		outfitItem.gameObject.SetLayerRecursively(layer);
	}

	public bool IsWearing(OutfitSelection selection, Player.BodyPart? bodyPart = null)
	{
		foreach (OutfitSelectionToBody outfitSelection in outfitSelections)
		{
			if (outfitSelection.selection == selection && (!bodyPart.HasValue || (outfitSelection.bodyPart == bodyPart.GetValueOrDefault() && bodyPart.HasValue)))
			{
				return true;
			}
		}
		return false;
	}

	private string ApplyConsumableHairColorOverrideIfApplicable(string colorGuid)
	{
		string result = colorGuid;
		Consumable activeConsumableInCategory = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetActiveConsumableInCategory(ConsumableManager.Category.Potion_HairDye);
		if (activeConsumableInCategory != null)
		{
			HairDyePotionConsumableItem hairDyePotionConsumableItem = activeConsumableInCategory.ConsumableItem as HairDyePotionConsumableItem;
			if (hairDyePotionConsumableItem != null)
			{
				result = hairDyePotionConsumableItem.ColorGuid;
			}
		}
		return result;
	}

	private string ApplyConsumableBeardColorOverrideIfApplicable(string serializedFaceSettings)
	{
		string result = serializedFaceSettings;
		Consumable activeConsumableInCategory = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetActiveConsumableInCategory(ConsumableManager.Category.Potion_HairDye);
		if (activeConsumableInCategory != null)
		{
			HairDyePotionConsumableItem hairDyePotionConsumableItem = activeConsumableInCategory.ConsumableItem as HairDyePotionConsumableItem;
			if (hairDyePotionConsumableItem != null)
			{
				AvatarFaceSettings avatarFaceSettings = AvatarFaceSettings.Deserialize(serializedFaceSettings);
				avatarFaceSettings.BeardColorGuid = hairDyePotionConsumableItem.ColorGuid;
				result = avatarFaceSettings.Serialize();
			}
		}
		return result;
	}

	public void SnapShotOutfitSelection()
	{
		savedOutfitSelectionStr = SerializeOutfitSelections();
		outfitSnapShotReady = true;
	}

	public void RestoreOutfitSelection()
	{
		if (outfitSnapShotReady)
		{
			EquipOutfitFromString(savedOutfitSelectionStr);
			DelayedLocalSaveAvatar();
		}
	}

	public void SnapShotAppearanceSelection()
	{
		savedHairColorGuid = HairColor.guidString;
		savedSkinColorGuid = SkinColor.guidString;
		savedFaceSettings = ((FaceFeatures == null) ? string.Empty : FaceFeatures.Serialize());
		appearanceSnapShotReady = true;
	}

	public void RestoreAppearanceSelection()
	{
		if (appearanceSnapShotReady)
		{
			SetHairColor(savedHairColorGuid);
			SetSkinColor(savedSkinColorGuid);
			AvatarFaceSettings avatarFaceSettings = AvatarFaceSettings.Deserialize(savedFaceSettings);
			ValidateFaceFeatures(avatarFaceSettings);
			SetFaceFeatures(avatarFaceSettings);
			DelayedLocalSaveAvatar();
		}
	}

	public void LocalLoadSavedOutfit(SavedOutfit savedOutfit)
	{
		if (savedOutfit != null)
		{
			OutfitListPlayerProperty = savedOutfit.OutfitSelections;
			if (savedOutfit.HairColor != null)
			{
				Avatars.LocalAvatar.HairColor = savedOutfit.HairColor;
				HairColorPlayerProperty = ApplyConsumableHairColorOverrideIfApplicable(savedOutfit.HairColor);
			}
			if (savedOutfit.SkinColor != null)
			{
				Avatars.LocalAvatar.SkinColor = savedOutfit.SkinColor;
				SkinColorPlayerProperty = savedOutfit.SkinColor;
			}
			if (savedOutfit.FaceFeatures != null)
			{
				Avatars.LocalAvatar.FaceFeatures = savedOutfit.FaceFeatures;
				FaceFeaturesPlayerProperty = ApplyConsumableBeardColorOverrideIfApplicable(savedOutfit.FaceFeatures);
			}
			else
			{
				AvatarFaceSettings avatarFaceSettings = new AvatarFaceSettings();
				avatarFaceSettings.BeardColorGuid = savedOutfit.HairColor;
				string text = avatarFaceSettings.Serialize();
				Avatars.LocalAvatar.FaceFeatures = text;
				FaceFeaturesPlayerProperty = ApplyConsumableBeardColorOverrideIfApplicable(text);
			}
			EquipTeamOutfits();
			Avatars.LocalAvatar.OutfitSelections = OutfitListPlayerProperty;
			DelayedLocalSaveAvatar();
		}
	}

	public SavedOutfit LocalGetCurrentOutfit()
	{
		SavedOutfit savedOutfit = new SavedOutfit();
		savedOutfit.OutfitSelections = OutfitListPlayerProperty;
		savedOutfit.HairColor = Avatars.LocalAvatar.HairColor;
		savedOutfit.SkinColor = SkinColorPlayerProperty;
		savedOutfit.FaceFeatures = Avatars.LocalAvatar.FaceFeatures;
		return savedOutfit;
	}

	public OutfitData GetOutfitProtobuf()
	{
		OutfitData outfitData = new OutfitData();
		outfitData.HairColor = HairColorPlayerProperty;
		outfitData.SkinColor = SkinColorPlayerProperty;
		outfitData.OutfitSelections = OutfitListPlayerProperty;
		outfitData.FaceSettings = FaceFeaturesPlayerProperty;
		return outfitData;
	}

	public static void ParseOutfitProtobuf(OutfitData data, out Color hairColor, out Color skinColor, out IList<OutfitSelectionToBody> selections, out AvatarFaceSettings faceSettings)
	{
		hairColor = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindHairColor(data.HairColor).color;
		skinColor = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.FindSkinColor(data.SkinColor).color;
		selections = ParseOutfitString(data.OutfitSelections);
		faceSettings = AvatarFaceSettings.Deserialize(data.FaceSettings);
	}
}
public class SpawnedEquipmentDrawer : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ItemSpacingConfig
	{
		[FormerlySerializedAs("MinItems")]
		public int AtLeastItemCount;

		public float MinItemCircleRadius = 0.5f;

		public float MaxItemCircleRadius = 1.35f;

		public int MaxItemsPerRing = 15;

		public float RingHeightOffset = 0.7f;

		[Range(0f, 1f)]
		public float ItemScaleFactor = 1f;

		public float AnimateSpeed = 180f;
	}

	private static List<SpawnedEquipmentDrawer> AllDrawers = new List<SpawnedEquipmentDrawer>();

	public static bool DrawersOpen = false;

	public static SpawnedEquipmentDrawer SelectedDrawer = null;

	public Action<bool> DrawerSelected;

	public string FriendlyName = string.Empty;

	public string InternalName = string.Empty;

	[Tooltip("Supported outfit types for this drawer.")]
	public List<OutfitManager.OutfitType> OutfitTypes;

	[Tooltip("Supported equipment prefabs for this drawer.")]
	public List<ToolSkinMapper> SupportedEquipments;

	[FormerlySerializedAs("startTransform")]
	[SerializeField]
	protected Transform ringCenterTransform;

	[Header("Drawer Item Spacing")]
	[SerializeField]
	[Tooltip("The total front gap in degress. Items will be offset frontGapDegrees/2 on either side of center")]
	private int frontGapDegrees = 90;

	private static ItemSpacingConfig defaultSpacingConfig = new ItemSpacingConfig();

	[SerializeField]
	private ItemSpacingConfig[] itemSpacingConfigs = new ItemSpacingConfig[1] { defaultSpacingConfig };

	[Header("Drawer UI")]
	public UnityEngine.UI.Button SelectButton;

	public UnityEngine.UI.Image NewIcon;

	public Interpolator DrawerInterpolator;

	public Vector3 DrawerOpenOffset = new Vector3(0f, 0f, -0.15f);

	private RecRoomAudioClip _pagingSound;

	private bool _isSelected;

	private Coroutine animateInOutCoroutine;

	protected int maxIndex = -1;

	[HideInInspector]
	public List<Tool> Tools;

	private List<DrawerEquipmentContainer> toolContainers;

	private Transform drawerRingCenter;

	private Vector3 defaultDrawerPosition = Vector3.zero;

	private Vector3 defaultButtonDrawerOffset = Vector3.zero;

	public int FrontGapDegrees => frontGapDegrees;

	public ItemSpacingConfig CurrentConfig
	{
		get
		{
			int count = Tools.Count;
			ItemSpacingConfig result = defaultSpacingConfig;
			for (int num = itemSpacingConfigs.Length - 1; num >= 0; num--)
			{
				ItemSpacingConfig itemSpacingConfig = itemSpacingConfigs[num];
				if (itemSpacingConfig.AtLeastItemCount < count)
				{
					result = itemSpacingConfig;
					break;
				}
			}
			return result;
		}
	}

	public float ItemScaleFactor => CurrentConfig.ItemScaleFactor;

	public RecRoomAudioClip PagingSound
	{
		get
		{
			return _pagingSound;
		}
		set
		{
			_pagingSound = value;
		}
	}

	public bool IsSelected
	{
		get
		{
			return _isSelected;
		}
		set
		{
			if (_isSelected == value || (value && Tools.Count == 0))
			{
				return;
			}
			_isSelected = value;
			if (DrawerInterpolator != null)
			{
				DrawerInterpolator.TargetPosition = defaultDrawerPosition + ((!_isSelected) ? Vector3.zero : DrawerOpenOffset);
			}
			if (_isSelected)
			{
				SelectedDrawer = this;
				DeselectOthers(this);
				base.transform.rotation = Quaternion.identity;
				animateInOutCoroutine = StartCoroutine(AnimateItemsIn());
			}
			else
			{
				if (animateInOutCoroutine != null)
				{
					StopCoroutine(animateInOutCoroutine);
				}
				foreach (DrawerEquipmentContainer toolContainer in toolContainers)
				{
					toolContainer.State = DrawerEquipmentContainer.DrawerToolState.AnimatingOut;
				}
			}
			DrawersOpen = AllDrawers.Any((SpawnedEquipmentDrawer d) => d.IsSelected);
			if (!DrawersOpen)
			{
				SelectedDrawer = null;
			}
			if (DrawerSelected != null)
			{
				DrawerSelected(_isSelected);
			}
		}
	}

	public int EquipmentCount => Tools.Count;

	public Transform RingCenterTransform
	{
		get
		{
			if (drawerRingCenter == null)
			{
				drawerRingCenter = new GameObject(base.gameObject.name + "_RingCenter").transform;
				drawerRingCenter.SetParent(base.transform);
				drawerRingCenter.position = ringCenterTransform.position;
				drawerRingCenter.rotation = ringCenterTransform.rotation;
			}
			return drawerRingCenter;
		}
	}

	public EquipmentSpawner SpawnerParent { get; set; }

	public void OnToolIsNewChanged(PlayerSpawnedEquipment spawnedEquipment, bool isNew)
	{
		UpdateNewIcon();
	}

	private IEnumerator AnimateItemsIn()
	{
		for (int i = toolContainers.Count - 1; i >= 0; i--)
		{
			toolContainers[i].State = DrawerEquipmentContainer.DrawerToolState.AnimatingIn;
			yield return new WaitForSeconds(0.075f);
		}
	}

	private static void DeselectOthers(SpawnedEquipmentDrawer selected)
	{
		foreach (SpawnedEquipmentDrawer allDrawer in AllDrawers)
		{
			if (allDrawer != selected)
			{
				allDrawer.IsSelected = false;
			}
		}
	}

	protected void Awake()
	{
		Tools = new List<Tool>();
		toolContainers = new List<DrawerEquipmentContainer>();
		if (ringCenterTransform == null)
		{
			ringCenterTransform = base.transform;
		}
		if (DrawerInterpolator != null && SelectButton != null)
		{
			defaultDrawerPosition = DrawerInterpolator.transform.position;
			defaultButtonDrawerOffset = SelectButton.transform.position - DrawerInterpolator.transform.position;
		}
		AllDrawers.Add(this);
	}

	private void Update()
	{
		if (DrawerInterpolator != null && SelectButton != null)
		{
			SelectButton.transform.position = defaultButtonDrawerOffset + DrawerInterpolator.transform.position;
		}
		if (Player.LocalPlayerExists && IsSelected && SpawnerParent != null && !SpawnerParent.IsPlayerInChangingArea(Player.LocalPlayer))
		{
			IsSelected = false;
		}
	}

	protected void OnDestroy()
	{
		AllDrawers.Remove(this);
	}

	public void UpdateNewIcon()
	{
		if (!(NewIcon != null))
		{
			return;
		}
		bool active = false;
		foreach (Tool tool in Tools)
		{
			if (tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.IsNew)
			{
				active = true;
				break;
			}
		}
		NewIcon.gameObject.SetActive(active);
	}

	public DrawerEquipmentContainer.AnimationTarget GetTarget(int index, int maxCount)
	{
		int num = maxCount / CurrentConfig.MaxItemsPerRing;
		float t = Mathf.Clamp((float)maxCount / (float)CurrentConfig.MaxItemsPerRing, 0f, 1f);
		float num2 = Mathf.Lerp(CurrentConfig.MinItemCircleRadius, CurrentConfig.MaxItemCircleRadius, t);
		int num3 = index / CurrentConfig.MaxItemsPerRing;
		float num4 = (360 - frontGapDegrees) / CurrentConfig.MaxItemsPerRing;
		float angle = (float)(index % CurrentConfig.MaxItemsPerRing) * num4 + num4 * 0.5f + (float)frontGapDegrees / 2f;
		Quaternion quaternion = Quaternion.AngleAxis(angle, Vector3.up);
		int num5 = num / 2;
		int num6 = num3 - num5;
		Vector3 vector = Vector3.up * (CurrentConfig.RingHeightOffset * (float)num6);
		Vector3 vector2 = ringCenterTransform.position + quaternion * (ringCenterTransform.forward * num2) + vector;
		Vector3 localPosition = RingCenterTransform.InverseTransformPoint(vector2);
		Vector3 forward = ringCenterTransform.position - vector2;
		Quaternion rotation = Quaternion.LookRotation(forward);
		DrawerEquipmentContainer.AnimationTarget animationTarget = new DrawerEquipmentContainer.AnimationTarget();
		animationTarget.localPosition = localPosition;
		animationTarget.rotation = rotation;
		animationTarget.angle = angle;
		animationTarget.radius = num2;
		return animationTarget;
	}

	private void OnDrawGizmosSelected()
	{
		Quaternion quaternion = Quaternion.AngleAxis(frontGapDegrees / 2, Vector3.up);
		Quaternion quaternion2 = Quaternion.AngleAxis(-(frontGapDegrees / 2), Vector3.up);
		UnityEngine.Debug.DrawLine(ringCenterTransform.position, ringCenterTransform.position + quaternion * (ringCenterTransform.forward * CurrentConfig.MaxItemCircleRadius), Color.green);
		UnityEngine.Debug.DrawLine(ringCenterTransform.position, ringCenterTransform.position + quaternion2 * (ringCenterTransform.forward * CurrentConfig.MaxItemCircleRadius), Color.green);
		Gizmos.DrawWireSphere(ringCenterTransform.position, CurrentConfig.MaxItemCircleRadius);
	}

	public void UpdateEquipmentPlacement()
	{
		for (int i = 0; i < Tools.Count; i++)
		{
			toolContainers[i].target = GetTarget(i, Tools.Count);
		}
		SelectButton.gameObject.SetActive(Tools.Count > 0);
		UpdateNewIcon();
	}

	public void AddTool(Tool tool)
	{
		GameObject gameObject = new GameObject(tool.name + "_Anchor");
		gameObject.transform.position = ringCenterTransform.position;
		gameObject.transform.rotation = ringCenterTransform.rotation;
		gameObject.transform.SetParent(RingCenterTransform, worldPositionStays: true);
		DrawerEquipmentContainer drawerEquipmentContainer = gameObject.AddComponent<DrawerEquipmentContainer>();
		drawerEquipmentContainer.Initialize(tool, this);
		toolContainers.Add(drawerEquipmentContainer);
		tool.transform.localPosition = Vector3.zero;
		tool.transform.localRotation = Quaternion.identity;
		tool.transform.SetParent(gameObject.transform, worldPositionStays: false);
		tool.PlayerSpawnedEquipment.OnIsNewChanged += OnToolIsNewChanged;
		Tools.Add(tool);
	}
}
[Obsolete("Tools with sub tools are not handled properly by this class. - bilal")]
public class ToolHighlightScaleAnimation : UnityEngine.MonoBehaviour
{
	private Tool tool;

	private AnimationCurve scaleCurve;

	private Vector3 initialScale = Vector3.one;

	private float curveDuration;

	private float latestStartTime;

	private bool isRunning;

	private void Awake()
	{
		tool = GetComponent<Tool>();
		if (tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
		}
		else
		{
			tool.HoverStartEvent += OnHoverStart;
			tool.HoverEndEvent += OnHoverEnd;
		}
		initialScale = base.transform.localScale;
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.HoverStartEvent -= OnHoverStart;
			tool.HoverEndEvent -= OnHoverEnd;
		}
	}

	private void Start()
	{
		scaleCurve = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitToolScaleAnimationCurve;
		if (scaleCurve == null || scaleCurve.length < 1)
		{
			curveDuration = 0f;
			UnityEngine.Debug.LogError("Outfit Manager tool scale animation curve is invalid.");
		}
		else
		{
			curveDuration = scaleCurve[scaleCurve.length - 1].time;
		}
	}

	private void OnHoverStart(Tool tool)
	{
		if (curveDuration <= 0f)
		{
			isRunning = false;
			return;
		}
		latestStartTime = UnityEngine.Time.time;
		isRunning = true;
	}

	private void OnHoverEnd(Tool tool)
	{
		base.transform.localScale = initialScale;
		isRunning = false;
	}

	private void Update()
	{
		if (isRunning && !tool.IsHeld)
		{
			float time = (UnityEngine.Time.time - latestStartTime) % curveDuration;
			base.transform.localScale = initialScale * scaleCurve.Evaluate(time);
		}
	}
}
namespace RecRoom.Players
{
	[DisallowMultipleComponent]
	public class PlayerBackpack : UnityEngine.MonoBehaviour
	{
		private const string BACKPACK_FAVORITE_TOOL = "BACKPACK_FAVORITE_TOOL";

		private Dictionary<PlayerBackpackToolType, Tool> allTools = new Dictionary<PlayerBackpackToolType, Tool>();

		private float toolSpawnDistance = 0.9f;

		[NonSerialized]
		public Player LocalPlayer;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<Tool, PlayerBackpackToolType, bool> m_BackpackToolEnabledChange;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<PlayerBackpackToolType> m_BackpackFavoriteToolChange;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<PlayerBackpackToolType> m_BackpackToolGrabbed;

		private TokenFlag disableFavoriteToolSelection = new TokenFlag();

		private Tool _favoriteTool;

		private PlayerBackpackToolType _cachedFavoriteToolType = PlayerBackpackToolType.INVALID;

		private Tool FavoriteTool
		{
			get
			{
				if (_favoriteTool == null)
				{
					_favoriteTool = GetBackpackTool((PlayerBackpackToolType)RecroomPrefs.GetInt("BACKPACK_FAVORITE_TOOL", -1));
				}
				return _favoriteTool;
			}
			set
			{
				_favoriteTool = value;
				_cachedFavoriteToolType = ((!(value == null)) ? GetBackpackToolType(value) : PlayerBackpackToolType.INVALID);
				RecroomPrefs.SetInt("BACKPACK_FAVORITE_TOOL", (int)_cachedFavoriteToolType);
				RecroomPrefs.Save();
			}
		}

		public PlayerBackpackToolType FavoriteToolType
		{
			get
			{
				if (FavoriteTool != null && _cachedFavoriteToolType == PlayerBackpackToolType.INVALID)
				{
					_cachedFavoriteToolType = GetBackpackToolType(FavoriteTool);
				}
				return _cachedFavoriteToolType;
			}
		}

		public event Action<Tool, PlayerBackpackToolType, bool> BackpackToolEnabledChange
		{
			add
			{
				Action<Tool, PlayerBackpackToolType, bool> action = this.m_BackpackToolEnabledChange;
				Action<Tool, PlayerBackpackToolType, bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackToolEnabledChange, (Action<Tool, PlayerBackpackToolType, bool>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<Tool, PlayerBackpackToolType, bool> action = this.m_BackpackToolEnabledChange;
				Action<Tool, PlayerBackpackToolType, bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackToolEnabledChange, (Action<Tool, PlayerBackpackToolType, bool>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public event Action<PlayerBackpackToolType> BackpackFavoriteToolChange
		{
			add
			{
				Action<PlayerBackpackToolType> action = this.m_BackpackFavoriteToolChange;
				Action<PlayerBackpackToolType> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackFavoriteToolChange, (Action<PlayerBackpackToolType>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<PlayerBackpackToolType> action = this.m_BackpackFavoriteToolChange;
				Action<PlayerBackpackToolType> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackFavoriteToolChange, (Action<PlayerBackpackToolType>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public event Action<PlayerBackpackToolType> BackpackToolGrabbed
		{
			add
			{
				Action<PlayerBackpackToolType> action = this.m_BackpackToolGrabbed;
				Action<PlayerBackpackToolType> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackToolGrabbed, (Action<PlayerBackpackToolType>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<PlayerBackpackToolType> action = this.m_BackpackToolGrabbed;
				Action<PlayerBackpackToolType> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_BackpackToolGrabbed, (Action<PlayerBackpackToolType>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void Awake()
		{
			if (!(LocalPlayer != null) || !LocalPlayer.isLocal)
			{
				return;
			}
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("Owner", PhotonNetwork.player.ID);
			dictionary.Add("Purpose", 1);
			dictionary.Add("InvisibleOnSpawn", true);
			Dictionary<string, object> instantiationParameters = dictionary;
			PlayerBackpackToolConfig.Config[] allToolConfigs = PlayerBackpackToolSettings.GetAllToolConfigs();
			foreach (PlayerBackpackToolConfig.Config config in allToolConfigs)
			{
				Tool tool = Tool.PhotonInstantiate(config.Prefab.name, Vector3.zero, Quaternion.identity, 1f, LocalPlayer.photonView.viewID, instantiationParameters);
				if (tool != null)
				{
					allTools[config.ToolType] = tool;
					tool.PrePickupEvent += Tool_PrePickupEvent;
					SingletonMonoBehaviour<Scheduler>.Instance.Run(DelayedInitialize(0.1f, delegate
					{
						tool.SkinMapper.LocalApplyFavoriteSkin();
						tool.AuthorityDisableAndMove(Vector3.one, Quaternion.identity);
						SynchronizedField.SendPendingRoomUpdates();
						tool.AuthoritySetVisible(isVisible: true);
					}));
				}
			}
			if (FavoriteTool != null)
			{
				FavoriteTool.PostReleaseEvent += FavoriteTool_PostReleaseEvent;
			}
		}

		private IEnumerator<ISchedule> DelayedInitialize(float seconds, Action function)
		{
			yield return Schedule.Wait(seconds, Scheduler.QueueType.EndOfFrame);
			function?.Invoke();
		}

		private void OnDestroy()
		{
			foreach (Tool value in allTools.Values)
			{
				value.PrePickupEvent -= Tool_PrePickupEvent;
			}
			if (FavoriteTool != null)
			{
				FavoriteTool.PostReleaseEvent -= FavoriteTool_PostReleaseEvent;
			}
		}

		public bool IsInBackpack(Tool tool)
		{
			foreach (Tool value in allTools.Values)
			{
				if (value == tool)
				{
					return true;
				}
			}
			return false;
		}

		public Tool GetBackpackTool(PlayerBackpackToolType toolType)
		{
			if (allTools.TryGetValue(toolType, out var value))
			{
				return value;
			}
			return null;
		}

		public PlayerBackpackToolType GetBackpackToolType(Tool tool)
		{
			foreach (KeyValuePair<PlayerBackpackToolType, Tool> allTool in allTools)
			{
				if (allTool.Value == tool)
				{
					return allTool.Key;
				}
			}
			return PlayerBackpackToolType.INVALID;
		}

		private void Tool_PrePickupEvent(Tool pickedUpTool)
		{
			if (pickedUpTool == FavoriteTool)
			{
				FavoriteTool.transform.position = FavoriteTool.HolderHand.transform.position;
				FavoriteTool.SupportsAnimateIn = false;
				FavoriteTool.IsEnabled = true;
				if (this.BackpackToolGrabbed != null)
				{
					this.BackpackToolGrabbed(FavoriteToolType);
				}
			}
			pickedUpTool.RigidbodyEx.RemoveKinematic(this);
			pickedUpTool.RigidbodyEx.useGravity = true;
		}

		private void FavoriteTool_PostReleaseEvent(Tool releasedTool)
		{
			if (releasedTool == FavoriteTool && FavoriteTool.IsEnabled && LocalPlayer.ToolEquipSlots.ShoulderSlot.IsHandInSelectionVolume(releasedTool.transform.position))
			{
				FavoriteTool.SupportsAnimateOut = false;
				FavoriteTool.IsEnabled = false;
			}
		}

		public void AddDisableFavoriteToolSelection(object token)
		{
			disableFavoriteToolSelection.Add(token);
		}

		public void RemoveDisableFavoriteToolSelection(object token)
		{
			disableFavoriteToolSelection.Remove(token);
		}

		public Tool TryGetFavoriteToolForPickup()
		{
			if (FavoriteTool != null && !disableFavoriteToolSelection.HasTokens && CanEnableTool(FavoriteToolType))
			{
				return FavoriteTool;
			}
			return null;
		}

		public void SetFavoriteTool(PlayerBackpackToolType toolType)
		{
			if (FavoriteTool != null)
			{
				FavoriteTool.PostReleaseEvent -= FavoriteTool_PostReleaseEvent;
			}
			FavoriteTool = GetBackpackTool(toolType);
			if (FavoriteTool != null)
			{
				FavoriteTool.PostReleaseEvent += FavoriteTool_PostReleaseEvent;
			}
			if (this.BackpackFavoriteToolChange != null)
			{
				this.BackpackFavoriteToolChange(toolType);
			}
		}

		public bool IsInUse(PlayerBackpackToolType toolType)
		{
			Tool backpackTool = GetBackpackTool(toolType);
			return backpackTool != null && backpackTool.IsEnabled;
		}

		public void UseTool(PlayerBackpackToolType toolType)
		{
			ToggleToolEnabled(GetBackpackTool(toolType), toolType, shouldBeEnabled: true);
		}

		public void RecallTool(PlayerBackpackToolType toolType)
		{
			ToggleToolEnabled(GetBackpackTool(toolType), toolType, shouldBeEnabled: false);
		}

		public void RecallTool(Tool tool)
		{
			if (IsInBackpack(tool))
			{
				ToggleToolEnabled(tool, GetBackpackToolType(tool), shouldBeEnabled: false);
				return;
			}
			UnityEngine.Debug.LogErrorFormat("{0} doesn't belong in the backpack!", tool.name);
		}

		public void RecallAllTools()
		{
			foreach (Tool value in allTools.Values)
			{
				RecallTool(value);
			}
		}

		private bool CanEnableTool(PlayerBackpackToolType toolType)
		{
			if (toolType == PlayerBackpackToolType.MAKER_PEN)
			{
				return toolType == PlayerBackpackToolType.MAKER_PEN && MakerPen.LocalPlayerCanUseCreationMode;
			}
			return true;
		}

		private void ShowCannotEnableToolFeedback(PlayerBackpackToolType toolType)
		{
			if (toolType == PlayerBackpackToolType.MAKER_PEN)
			{
				MakerPen.ShowCannotUseFeedback();
				if (this.BackpackToolEnabledChange != null)
				{
					this.BackpackToolEnabledChange(null, PlayerBackpackToolType.MAKER_PEN, arg3: false);
				}
			}
		}

		private void ToggleToolEnabled(Tool tool, PlayerBackpackToolType toolType, bool shouldBeEnabled)
		{
			if (shouldBeEnabled && !CanEnableTool(toolType))
			{
				ShowCannotEnableToolFeedback(toolType);
				return;
			}
			if (!tool.hasAuthority)
			{
				tool.photonView.TransferOwnership(PhotonNetwork.player);
			}
			tool.AuthoritySetAnimateInOut(shouldBeEnabled, !shouldBeEnabled);
			if (shouldBeEnabled && !tool.IsEnabled)
			{
				Transform transform = LocalPlayer.Head.transform;
				Vector3 vector = Vector3.ProjectOnPlane(transform.forward, Vector3.up);
				tool.transform.position = transform.position + vector * toolSpawnDistance;
				tool.transform.rotation = Quaternion.identity;
				tool.IsEnabled = true;
			}
			else
			{
				tool.RigidbodyEx.AddKinematic(this);
				tool.RigidbodyEx.useGravity = false;
				tool.IsEnabled = false;
			}
			if (this.BackpackToolEnabledChange != null)
			{
				this.BackpackToolEnabledChange(tool, GetBackpackToolType(tool), shouldBeEnabled);
			}
		}
	}
}
public class CollisionVibration : UnityEngine.MonoBehaviour
{
	private void OnCollisionEnter(Collision collision)
	{
		PlayerHand playerHand = null;
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		Tool colliderTool = collision.GetColliderTool();
		if (colliderPlayer != null)
		{
			switch (bodyPart)
			{
			case Player.BodyPart.LeftHand:
				playerHand = colliderPlayer.LeftHand;
				break;
			case Player.BodyPart.RightHand:
				playerHand = colliderPlayer.RightHand;
				break;
			}
		}
		else if (colliderTool != null && colliderTool.IsHeld && colliderTool.Owner != null)
		{
			if (colliderTool.Owner.LeftHand.HeldTool == colliderTool)
			{
				playerHand = colliderTool.Owner.LeftHand;
			}
			else if (colliderTool.Owner.RightHand.HeldTool == colliderTool)
			{
				playerHand = colliderTool.Owner.RightHand;
			}
		}
		if (playerHand != null)
		{
			playerHand.Vibrate(50);
		}
	}
}
namespace RecRoom.Consumable
{
	public class CameraFilterConsumableEffect : ConsumableEffect
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private ShareCamera shareCamera;

		[SerializeField]
		private PostProcessProfile filterProfile;

		protected override void Awake()
		{
			base.Awake();
			base.SupportedCategories.Add(ConsumableManager.Category.CameraFilter);
		}

		protected override void Start()
		{
			base.Start();
			if (base.IsMine)
			{
				shareCamera.OnPictureTaken += ShareCamera_OnPictureTaken;
			}
		}

		private void ShareCamera_OnPictureTaken(ShareCamera.FilterType filter)
		{
			RecNet.Consumable[] array = localActiveConsumables.ToArray();
			foreach (RecNet.Consumable consumable in array)
			{
				LocalUseConsumable(consumable, 1);
			}
		}

		protected override void AddEffect(ConsumableItem consumableItem, bool showNotification)
		{
			base.AddEffect(consumableItem, showNotification);
			CameraFilterConsumableItem cameraFilterConsumableItem = consumableItem as CameraFilterConsumableItem;
			if (cameraFilterConsumableItem != null)
			{
				shareCamera.UpdateFilter(cameraFilterConsumableItem);
				if (base.IsMine && showNotification)
				{
					ShowNotification(GetFilterName(cameraFilterConsumableItem.FilterType) + " film activated");
				}
			}
		}

		protected override void RemoveEffect(ConsumableItem consumableItem, bool showNotification)
		{
			base.RemoveEffect(consumableItem, showNotification);
			CameraFilterConsumableItem cameraFilterConsumableItem = consumableItem as CameraFilterConsumableItem;
			if (cameraFilterConsumableItem != null)
			{
				shareCamera.UpdateFilter(null);
				if (base.IsMine && showNotification)
				{
					ShowNotification(GetFilterName(cameraFilterConsumableItem.FilterType) + " film deactivated");
				}
			}
		}

		private string GetFilterName(ShareCamera.FilterType filter)
		{
			return filter switch
			{
				ShareCamera.FilterType.BLACK_WHITE => "Black & White", 
				ShareCamera.FilterType.DAWN => "Dawn", 
				ShareCamera.FilterType.SEPIA => "Sepia", 
				ShareCamera.FilterType.GOBLIN1 => "Goblin King", 
				ShareCamera.FilterType.JUMBOTRON => "Jumbotron", 
				ShareCamera.FilterType.CRIMSONCAULDRON => "Witch", 
				ShareCamera.FilterType.GHOSTBEARD => "Ghost Beard", 
				_ => "Share Cam", 
			};
		}
	}
