	public abstract class ConsumableEffect : Photon.MonoBehaviour
	{
		public static List<ConsumableEffect> AllLocal = new List<ConsumableEffect>();

		private SynchronizedField<bool> _showNotification;

		private SynchronizedField<string[]> _activeConsumableTypes;

		private HashSet<string> appliedActiveConsumableType = new HashSet<string>();

		protected List<RecNet.Consumable> localActiveConsumables = new List<RecNet.Consumable>();

		private Dictionary<string, GameObject> effectVisuals = new Dictionary<string, GameObject>();

		public List<ConsumableManager.Category> SupportedCategories { get; protected set; }

		public bool IsMine { get; private set; }

		protected ConsumableItem GetActiveConsumable()
		{
			string[] array = _activeConsumableTypes.Get();
			if (array.Length > 0)
			{
				return NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(array[0]);
			}
			return null;
		}

		protected override void Awake()
		{
			base.Awake();
			SupportedCategories = new List<ConsumableManager.Category>();
			IsMine = base.photonView.isLocal;
			_activeConsumableTypes = new SynchronizedField<string[]>(this, "ConEf", new string[0], SetterPermissionMode.ANYONE, delegate
			{
				OnActiveConsumableTypesChanged();
			});
			_showNotification = new SynchronizedField<bool>(this, "ConEfNot", defaultValue: false, SetterPermissionMode.ANYONE);
			if (IsMine)
			{
				AllLocal.Add(this);
			}
			this.EndOfFrameRoutine(delegate
			{
				OnActiveConsumableTypesChanged(forceDisableNotification: true);
			});
		}

		protected virtual void Start()
		{
			if (NetworkedSingletonMonoBehaviour<ConsumableManager>.IsInitialized && IsMine)
			{
				NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.TryApplyConsumableEffect(this);
			}
		}

		protected override void OnDestroy()
		{
			if (IsMine)
			{
				AllLocal.Remove(this);
			}
			base.OnDestroy();
		}

		public bool LocalActivateConsumable(RecNet.Consumable consumable, bool showNotification)
		{
			if (!IsMine)
			{
				return false;
			}
			if (SupportedCategories.Contains(consumable.Category) && !localActiveConsumables.Contains(consumable))
			{
				localActiveConsumables.Add(consumable);
				_showNotification.Set(showNotification);
				string[] array = _activeConsumableTypes.Get();
				string[] array2 = new string[array.Length + 1];
				array.CopyTo(array2, 1);
				array2[0] = consumable.ConsumableType;
				_activeConsumableTypes.Set(array2);
				return true;
			}
			return false;
		}

		public static IEnumerable<ConsumableEffect> LocalGetAll(ConsumableManager.Category category)
		{
			return AllLocal.Where((ConsumableEffect e) => e.SupportedCategories.Contains(category));
		}

		public bool LocalDeactivateConsumable(RecNet.Consumable consumable, bool showNotification)
		{
			if (!IsMine)
			{
				return false;
			}
			if (SupportedCategories.Contains(consumable.Category) && localActiveConsumables.Contains(consumable))
			{
				localActiveConsumables.Remove(consumable);
				_showNotification.Set(showNotification);
				string[] source = _activeConsumableTypes.Get();
				string[] newValue = source.Where((string d) => d != consumable.ConsumableType).ToArray();
				_activeConsumableTypes.Set(newValue);
				return true;
			}
			return false;
		}

		private void OnActiveConsumableTypesChanged(bool forceDisableNotification = false)
		{
			bool showNotification = _showNotification.Get() && !forceDisableNotification;
			string[] array = _activeConsumableTypes.Get();
			if (array != null)
			{
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (!appliedActiveConsumableType.Contains(text))
					{
						ConsumableItem consumablePrefab = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(text);
						appliedActiveConsumableType.Add(text);
						if (consumablePrefab != null)
						{
							AddEffect(consumablePrefab, showNotification);
						}
					}
				}
				{
					foreach (string item in appliedActiveConsumableType.Except(array).ToList())
					{
						appliedActiveConsumableType.Remove(item);
						ConsumableItem consumablePrefab2 = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(item);
						if (consumablePrefab2 != null)
						{
							RemoveEffect(consumablePrefab2, showNotification);
						}
					}
					return;
				}
			}
			foreach (string item2 in appliedActiveConsumableType.ToList())
			{
				appliedActiveConsumableType.Remove(item2);
				ConsumableItem consumablePrefab3 = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(item2);
				if (consumablePrefab3 != null)
				{
					RemoveEffect(consumablePrefab3, showNotification);
				}
			}
		}

		protected void LocalUseConsumable(RecNet.Consumable consumable, int deltaCount)
		{
			if (IsMine)
			{
				NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.UseConsumable(consumable, deltaCount, null);
			}
		}

		protected virtual void AddEffect(ConsumableItem consumableItem, bool showNotification)
		{
			if (consumableItem.EffectPrefab != null)
			{
				GameObject value = UnityEngine.Object.Instantiate(consumableItem.EffectPrefab, base.transform);
				effectVisuals[consumableItem.ConsumableType] = value;
			}
		}

		protected Dictionary<string, GameObject>.ValueCollection GetAllVisualEffects()
		{
			return effectVisuals.Values;
		}

		protected GameObject GetEffectVisual(ConsumableItem consumableItem)
		{
			if (!effectVisuals.ContainsKey(consumableItem.ConsumableType))
			{
				return null;
			}
			return effectVisuals[consumableItem.ConsumableType];
		}

		protected virtual void RemoveEffect(ConsumableItem consumableItem, bool showNotification)
		{
			if (consumableItem.EffectPrefab != null && effectVisuals.ContainsKey(consumableItem.ConsumableType))
			{
				GameObject gameObject = effectVisuals[consumableItem.ConsumableType];
				effectVisuals.Remove(consumableItem.ConsumableType);
				if (gameObject != null)
				{
					UnityEngine.Object.Destroy(gameObject);
				}
			}
		}

		protected void ShowNotification(string message)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, message, 3f);
		}
	}
