		public int CompareTo(ConsumableItem other)
		{
			if (other == null)
			{
				return 0;
			}
			int num = ((int)Category).CompareTo((int)other.Category);
			if (num == 0)
			{
				return FriendlyName.CompareTo(other.FriendlyName);
			}
			return num;
		}
	}
