		protected override void Awake()
		{
			base.Awake();
			PurchasedConsumables = new List<RecNet.Consumable>();
			ActiveConsumables = new Dictionary<Category, RecNet.Consumable>();
			ConsumablePrefabs.RemoveNulls();
			Consumables.OnConsumableAdded += Consumables_OnConsumableAdded;
			Consumables.OnConsumableRemoved += Consumables_OnConsumableRemoved;
			Consumables.OnPlatformLockedConsumableReceived += Consumables_OnPlatformLockedConsumableReceived;
			InitializeConsumablePrefabDictionary();
		}

		protected override void OnDestroy()
		{
			Consumables.OnConsumableAdded -= Consumables_OnConsumableAdded;
			Consumables.OnConsumableRemoved -= Consumables_OnConsumableRemoved;
			Consumables.OnPlatformLockedConsumableReceived -= Consumables_OnPlatformLockedConsumableReceived;
			base.OnDestroy();
		}

		private IEnumerator Start()
		{
			StartCoroutine(RunTimedConsumableQueue());
			while (!Player.LocalPlayerExists || !Player.LocalPlayer.IsInitialized)
			{
				yield return null;
			}
			List<RecNet.Consumable> purchasedConsumablesPerCategory = PurchasedConsumables.Where((RecNet.Consumable c) => c.ConsumableItem != null && c.IsActive && (c.ConsumableItem.Category == Category.CameraFilter || c.ConsumableItem.Category == Category.KO_Customization || c.ConsumableItem.Category == Category.Potion_HairDye)).ToList();
			foreach (RecNet.Consumable consumable in purchasedConsumablesPerCategory)
			{
				ActivateConsumable(consumable, showNotification: false);
				yield return null;
			}
			yield return UpdateRealWorldTimeConsumables();
		}

		private void InitializeConsumablePrefabDictionary()
		{
			foreach (ConsumableItem consumablePrefab in ConsumablePrefabs)
			{
				consumablePrefabDictionary.Add(consumablePrefab.ConsumableType, consumablePrefab);
			}
		}

		public RecNet.Consumable GetLastConsumable(string consumableType)
		{
			return (from pc in PurchasedConsumables
				where pc.ConsumableType == consumableType
				orderby pc.CreatedAt descending
				select pc).FirstOrDefault();
		}

		public RecNet.Consumable GetLastConsumableNotActive(string consumableType)
		{
			return (from pc in PurchasedConsumables
				where pc.ConsumableType == consumableType && !pc.IsActive
				orderby pc.CreatedAt descending
				select pc).FirstOrDefault();
		}

		public int GetRemainingCount(RecNet.Consumable consumable)
		{
			switch (consumable.ConsumableItem.LimitType)
			{
			case LimitType.Usage:
				return consumable.Count;
			case LimitType.Time:
			case LimitType.RealWorldTime:
			{
				int num = consumable.Count;
				if (consumable.IsActive)
				{
					float num2 = (from ct in activeTimedConsumableQueue
						where ct.consumable != null && ct.consumable.Id == consumable.Id
						select ct.nextTime).FirstOrDefault();
					if (num2 > 0f)
					{
						int num3 = (int)(60f - (num2 - UnityEngine.Time.time));
						num -= num3;
					}
				}
				return num;
			}
			default:
				return 0;
			}
		}

		public RecNet.Consumable GetConsumableById(long consumableId)
		{
			return (from pc in PurchasedConsumables
				where pc.Id == consumableId
				orderby pc.CreatedAt descending
				select pc).FirstOrDefault();
		}

		public void DeactivateConsumableOfCategory(Category category, bool showNotification)
		{
			IEnumerable<ConsumableEffect> enumerable = ConsumableEffect.LocalGetAll(category);
			RecNet.Consumable value = null;
			ActiveConsumables.TryGetValue(category, out value);
			if (!(value != null))
			{
				return;
			}
			foreach (ConsumableEffect item in enumerable)
			{
				item.LocalDeactivateConsumable(value, showNotification);
			}
			if (value.ConsumableItem.LimitType == LimitType.Time || value.ConsumableItem.LimitType == LimitType.RealWorldTime)
			{
				RemoveFromActiveTimedConsumableQueue(value);
			}
			Consumables.ActivateConsumable(value, isActive: false, delegate
			{
			});
			ActiveConsumables.Remove(value.Category);
			SafeRaiseActiveConsumableChanged(value, isActive: false);
		}

		public void ActivateConsumable(RecNet.Consumable newConsumable, bool showNotification)
		{
			if (newConsumable == null)
			{
				UnityEngine.Debug.LogError("Can not consume null, does not make sense!");
				return;
			}
			bool flag = false;
			for (int num = PurchasedConsumables.Count - 1; num >= 0; num--)
			{
				if (PurchasedConsumables[num].Id == newConsumable.Id)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				UnityEngine.Debug.LogError("Consumable id " + newConsumable.Id + " is not purchased, cannot be activated.");
				return;
			}
			Category consumableCategory = GetConsumableCategory(newConsumable.ConsumableType);
			DeactivateConsumableOfCategory(consumableCategory, showNotification: false);
			foreach (ConsumableEffect item in ConsumableEffect.LocalGetAll(consumableCategory))
			{
				item.LocalActivateConsumable(newConsumable, showNotification);
			}
			Consumables.ActivateConsumable(newConsumable, isActive: true, delegate
			{
			});
			ActiveConsumables[newConsumable.Category] = newConsumable;
			EnqueueTimedConsumable(newConsumable);
			SafeRaiseActiveConsumableChanged(newConsumable, isActive: true);
		}

		private IEnumerator UpdateRealWorldTimeConsumables()
		{
			List<Category> categories = ActiveConsumables.Keys.ToList();
			foreach (Category category in categories)
			{
				if (ActiveConsumables.ContainsKey(category))
				{
					RecNet.Consumable consumable = ActiveConsumables[category];
					if (consumable.ConsumableItem.LimitType == LimitType.RealWorldTime)
					{
						int currentCount = consumable.Count;
						int elapsedSeconds = (consumable.ActiveDurationMinutes.HasValue ? consumable.ActiveDurationMinutes.Value : 0) * 60;
						int newCount = Mathf.Max(consumable.InitialCount - elapsedSeconds, 0);
						int deltaCount = currentCount - newCount;
						yield return UseConsumable(consumable, deltaCount, null);
					}
				}
			}
		}

		public IEnumerator DownloadPurchasedConsumables(RecNet.Core.ApiCallback callback)
		{
			return Consumables.DowloadUnlockedConsumables(delegate(string error, List<RecNet.Consumable> selections)
			{
				if (selections != null)
				{
					PurchasedConsumables.AddRange(selections);
					PurchasedConsumables.Sort((RecNet.Consumable x, RecNet.Consumable y) => DateTime.Compare(x.CreatedAt, y.CreatedAt));
				}
				RecNet.Core.SafeInvoke(callback, error);
			});
		}

		public IEnumerator UseConsumable(RecNet.Consumable consumable, int deltaCount, RecNet.Core.ApiCallback callback)
		{
			return Consumables.UseConsumable(consumable, deltaCount, callback);
		}

		public void TryApplyConsumableEffect(ConsumableEffect consumableEffect)
		{
			foreach (Category supportedCategory in consumableEffect.SupportedCategories)
			{
				RecNet.Consumable value = null;
				ActiveConsumables.TryGetValue(supportedCategory, out value);
				if (value != null)
				{
					consumableEffect.LocalActivateConsumable(value, showNotification: false);
				}
			}
		}

		public Tool SpawnConsumableForLocalPlayer(string consumableType, long? consumableId, Vector3 position, Quaternion rotation, float scale, PlayerSpawnedEquipment.Purpose purpose, int? level)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("Owner", PhotonNetwork.player.ID);
			dictionary.Add("Purpose", (int)purpose);
			dictionary.Add("ConsumableType", consumableType);
			Dictionary<string, object> dictionary2 = dictionary;
			if (consumableId.HasValue)
			{
				dictionary2.Add("ConsumableId", consumableId.Value);
			}
			ConsumableItem consumablePrefab = GetConsumablePrefab(consumableType);
			string prefabNameInResources = ((!(consumablePrefab.ConsumableTool != null)) ? defaultConsumableToolPrefab.name : consumablePrefab.ConsumableTool.name);
			Tool tool = Tool.PhotonInstantiate(prefabNameInResources, position, rotation, scale, base.photonView.viewID, dictionary2);
			if (tool.PlayerSpawnedEquipment != null)
			{
				RecNet.Consumable lastConsumable = GetLastConsumable(consumableType);
				if (lastConsumable != null)
				{
					tool.PlayerSpawnedEquipment.Level = lastConsumable.UnlockedLevel;
				}
				else if (level.HasValue)
				{
					tool.PlayerSpawnedEquipment.Level = level.Value;
				}
				tool.PlayerSpawnedEquipment.IsNew = false;
			}
			return tool;
		}

		public GameObject SpawnConsumableImposter(string consumableType)
		{
			ConsumableItem consumablePrefab = GetConsumablePrefab(consumableType);
			if (consumablePrefab != null)
			{
				GameObject gameObject = VisualImposter.SpawnImposter(consumablePrefab.gameObject, null, preserveColliders: true).gameObject;
				gameObject.layer = 5;
				return gameObject;
			}
			return null;
		}

		private void RemoveFromActiveTimedConsumableQueue(RecNet.Consumable consumable)
		{
			ConsumableAndTime value = activeTimedConsumableQueue.FirstOrDefault((ConsumableAndTime c) => c.consumable == consumable);
			if (value.consumable != null)
			{
				Consumables.UseConsumable(value.consumable, value.consumable.Count, delegate
				{
				});
				activeTimedConsumableQueue.Remove(value);
			}
		}

		private IEnumerator RunTimedConsumableQueue()
		{
			while (true)
			{
				if (activeTimedConsumableQueue.Count > 0)
				{
					ConsumableAndTime timedItem = activeTimedConsumableQueue.Last();
					if (timedItem.consumable == null || !ActiveConsumables.ContainsValue(timedItem.consumable))
					{
						activeTimedConsumableQueue.RemoveLast();
					}
					else if (timedItem.nextTime <= UnityEngine.Time.time)
					{
						activeTimedConsumableQueue.RemoveLast();
						yield return UseConsumable(timedItem.consumable, 60, null);
						EnqueueTimedConsumable(timedItem.consumable);
					}
				}
				yield return new WaitForSeconds(5f);
			}
		}

		private void EnqueueTimedConsumable(RecNet.Consumable consumable)
		{
			if (consumable != null && consumable.ConsumableItem != null && (consumable.ConsumableItem.LimitType == LimitType.Time || consumable.ConsumableItem.LimitType == LimitType.RealWorldTime) && ActiveConsumables.ContainsValue(consumable))
			{
				ConsumableAndTime value = new ConsumableAndTime
				{
					consumable = consumable,
					nextTime = UnityEngine.Time.time + Mathf.Min(60f, consumable.Count)
				};
				LinkedListNode<ConsumableAndTime> linkedListNode = activeTimedConsumableQueue.First;
				while (linkedListNode != null && linkedListNode.Value.nextTime > value.nextTime)
				{
					linkedListNode = linkedListNode.Next;
				}
				if (linkedListNode != null)
				{
					activeTimedConsumableQueue.AddBefore(linkedListNode, value);
				}
				else
				{
					activeTimedConsumableQueue.AddLast(value);
				}
			}
		}

		public bool IsConsumablePurchased(string type)
		{
			return PurchasedConsumables.Where((RecNet.Consumable c) => c.ConsumableType == type).Count() > 0;
		}

		public bool IsConsumableOfTypeActive(string type)
		{
			ActiveConsumables.TryGetValue(GetConsumableCategory(type), out var value);
			if (value == null)
			{
				return false;
			}
			if (value.ConsumableType == type)
			{
				return true;
			}
			return false;
		}

