		private void SafeRaiseActiveConsumableChanged(RecNet.Consumable consumable, bool isActive)
		{
			try
			{
				if (this.OnActiveConsumableChanged != null)
				{
					this.OnActiveConsumableChanged(consumable, isActive);
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Error raising OnActiveConsumableChanged: " + ex);
			}
		}

		private void SafeRaisePurchasedConsumableChanged(RecNet.Consumable consumable, bool added)
		{
			try
			{
				if (this.OnPurchasedConsumableChanged != null)
				{
					this.OnPurchasedConsumableChanged(consumable, added);
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("Error raising OnPurchasedConsumableChanged: " + ex);
			}
		}

		private void Consumables_OnConsumableAdded(RecNet.Consumable consumable)
		{
			PurchasedConsumables.Add(consumable);
			SafeRaisePurchasedConsumableChanged(consumable, added: true);
		}

		private void Consumables_OnConsumableRemoved(long consumableId)
		{
			RecNet.Consumable consumable = PurchasedConsumables.RemoveWhere((RecNet.Consumable c) => c.Id == consumableId);
			if (!(consumable != null))
			{
				return;
			}
			if (ActiveConsumables.ContainsValue(consumable))
			{
				IEnumerable<ConsumableEffect> enumerable = ConsumableEffect.LocalGetAll(consumable.Category);
				RecNet.Consumable consumable2 = null;
				if (consumable.ConsumableItem.AutoActivateNextItem)
				{
					consumable2 = (from pc in PurchasedConsumables
						where pc.ConsumableType == consumable.ConsumableType
						orderby pc.CreatedAt descending
						select pc).FirstOrDefault();
				}
				foreach (ConsumableEffect item in enumerable)
				{
					item.LocalDeactivateConsumable(consumable, consumable2 == null);
				}
				Consumables.ActivateConsumable(consumable, isActive: false, delegate
				{
				});
				ActiveConsumables.Remove(consumable.Category);
				SafeRaiseActiveConsumableChanged(consumable, isActive: false);
				if (consumable2 != null)
				{
					ActivateConsumable(consumable2, showNotification: false);
				}
			}
			SafeRaisePurchasedConsumableChanged(consumable, added: false);
			AnalyticsHelper.ConsumableFinished(consumable.ConsumableItem.FriendlyName, consumable.Category, consumable.CreatedAt);
		}

		private void Consumables_OnPlatformLockedConsumableReceived()
		{
			HasPlatformLockedConsumable = true;
		}
	}
	public class ConsumableSpawnedContainerToolPiece : ConsumableSpawnedToolPiece
	{
		private List<Tool> nonInteractablePieces = new List<Tool>();

		private List<long> playersWhoInteractedWithPieces = new List<long>();

		private float spawnTime;

		private ConsumableItem consumableItem;

		private string ownerName;

		protected override void Awake()
		{
			base.Awake();
			tool.DisablePickup(this);
			spawnTime = UnityEngine.Time.time;
			ownerName = ((!(base.owner.ToPlayer() != null)) ? "Owner" : base.owner.ToPlayer().PlayerName);
		}

		protected override void OnDestroy()
		{
			if (nonInteractablePieces.Count > 0 || base.owner.ToPlayer() == null)
			{
				WorldSpaceNotification.PlayNext(ownerName + " has left the room", 3f, null, followPlayer: false, base.transform.position + Vector3.up);
			}
			else
			{
				WorldSpaceNotification.PlayNext("Item finished!", 3f, null, followPlayer: false, base.transform.position + Vector3.up);
			}
			if (isLocal)
			{
				foreach (Tool nonInteractablePiece in nonInteractablePieces)
				{
					nonInteractablePiece.PostPickupEvent -= Piece_PostPickupEvent;
					nonInteractablePiece.DestroyEvent -= OnNonInteractablePieceDestroyed;
				}
				AnalyticsHelper.SpawnableConsumableStats(consumableItem.FriendlyName, consumableItem.Category, UnityEngine.Time.time - spawnTime, nonInteractablePieces.Count, playersWhoInteractedWithPieces.Count);
			}
			base.OnDestroy();
		}

		public void SetNonHolderPieces(List<Tool> allPieces, ConsumableItem item)
		{
			if (!isLocal)
			{
				return;
			}
			consumableItem = item;
			foreach (Tool allPiece in allPieces)
			{
				ConsumableSpawnedToolPiece component = allPiece.GetComponent<ConsumableSpawnedToolPiece>();
				if (component != null)
				{
					nonInteractablePieces.Add(allPiece);
					allPiece.PostPickupEvent += Piece_PostPickupEvent;
					allPiece.DestroyEvent += OnNonInteractablePieceDestroyed;
				}
			}
		}

		private void Piece_PostPickupEvent(Tool piece)
		{
			if (piece.HolderPlayer != null && !playersWhoInteractedWithPieces.Contains(piece.HolderPlayer.PlayerId))
			{
				playersWhoInteractedWithPieces.Add(piece.HolderPlayer.PlayerId);
			}
		}

		private void OnNonInteractablePieceDestroyed(Tool piece)
		{
			nonInteractablePieces.Remove(piece);
			if (nonInteractablePieces.Count <= 0)
			{
				PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
			}
		}
	}
	public class ConsumableSpawnedToolPiece : Photon.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		protected Tool tool;

		protected override void Awake()
		{
			base.Awake();
			tool.RigidbodyEx.AddKinematic(this);
			tool.PostPickupEvent += Tool_PostPickupEvent;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += GameManager_StateChangeEvent;
			}
		}

		private void Tool_PostPickupEvent(Tool thisTool)
		{
			tool.RigidbodyEx.RemoveKinematic(this);
		}

		protected override void OnDestroy()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent -= GameManager_StateChangeEvent;
			}
			tool.PostPickupEvent -= Tool_PostPickupEvent;
			base.OnDestroy();
		}

		private void OnDisable()
		{
			if (isLocal)
			{
				PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
			}
		}

		private void GameManager_StateChangeEvent(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (currentStateId == 2 && base.hasAuthority)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}
	}
	public abstract class ConsumableTool : Photon.MonoBehaviour
	{
		private static List<ConsumableTool> LocalAll = new List<ConsumableTool>();

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		protected Tool tool;

		private object consumablePickupToken = new object();

		private object isMinePickupToken = new object();

		protected RecNet.Consumable _consumable;

		public PlayerSpawnedEquipment.Purpose Purpose { get; private set; }

		public bool IsMine { get; private set; }

		public RecNet.Consumable Consumable
		{
			get
			{
				return _consumable;
			}
			set
			{
				_consumable = value;
				tool.SetPickupEnabled(_consumable != null, consumablePickupToken);
			}
		}

		protected ConsumableItem consumableItem { get; set; }

		protected override void Awake()
		{
			base.Awake();
			IsMine = base.photonView.isLocal;
			object value = null;
			if (!tool.IsSubTool && tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue("ConsumableType", out value))
			{
				ConsumableItem consumablePrefab = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab((string)value);
				if (consumablePrefab != null)
				{
					SetConsumableItem(consumablePrefab);
				}
				object value2 = null;
				if (tool.InstantiationParameters.TryGetValue("Purpose", out value2))
				{
					Purpose = (PlayerSpawnedEquipment.Purpose)value2;
				}
			}
			if (consumableItem == null)
			{
				UnityEngine.Debug.LogError("ConsumableItem is null, something is very wrong");
			}
			tool.PostResetEvent += Tool_ResetEvent;
			if (IsMine)
			{
				LocalAll.Add(this);
			}
			tool.SetPickupEnabled(IsMine, isMinePickupToken);
			tool.CustomAuthorityResetOnKillzoneBehavior = DoNotResetOnKillzoneBehavior;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += GameManager_StateChangeEvent;
			}
		}

		private void Tool_ResetEvent(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (base.hasOwnership)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}

		private void GameManager_StateChangeEvent(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (currentStateId == 2 && base.hasAuthority)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}

		protected override void OnDestroy()
		{
			if (IsMine)
			{
				LocalAll.Remove(this);
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent -= GameManager_StateChangeEvent;
			}
			base.OnDestroy();
		}

		protected virtual void SetConsumableItem(ConsumableItem newConsumableItem)
		{
			consumableItem = newConsumableItem;
			if (!IsMine)
			{
				return;
			}
			object value = null;
			if (!tool.IsSubTool && tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue("ConsumableId", out value))
			{
				Consumable = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumableById((long)value);
				return;
			}
			Consumable = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetLastConsumableNotActive(consumableItem.ConsumableType);
			if (Consumable == null)
			{
				Consumables.OnConsumableAdded += Consumables_OnConsumableAdded;
			}
		}

		private void Consumables_OnConsumableAdded(RecNet.Consumable consumable)
		{
			if (consumable.ConsumableType == consumableItem.ConsumableType)
			{
				Consumable = consumable;
				Consumables.OnConsumableAdded -= Consumables_OnConsumableAdded;
			}
		}

		public static ConsumableTool FindConsumableTool(long id)
		{
			return LocalAll.FirstOrDefault((ConsumableTool ct) => ct.Consumable != null && ct.Consumable.Id == id);
		}

		public static ConsumableTool FindConsumableTool(ConsumableManager.Category category)
		{
			return LocalAll.FirstOrDefault((ConsumableTool ct) => ct.Consumable != null && ct.Consumable.Category == category);
		}

		protected void ShowAddedToBackpackNotification()
		{
			if (IsMine)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Added to your backpack!", 3f);
			}
		}

		private bool DoNotResetOnKillzoneBehavior(Tool thisTool, Killzone killzone)
		{
			return true;
		}
	}
