			if (activeConsumable != null)
			{
				CustomKOConsumableItem customKOConsumableItem = activeConsumable as CustomKOConsumableItem;
				if (customKOConsumableItem != null)
				{
					if (consumeInstance)
					{
						UseActiveEffects();
