namespace RecRoom
{
	public class EdibleItem : Photon.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		[SerializeField]
		private float minBiteInterval = 1f;

		[Tooltip("Array index represents number of bites, i.e. [0] is the uneaten item")]
		[SerializeField]
		private GameObject[] visualsAfterEachBite;

		[Header("Effects")]
		[SerializeField]
		private RecRoomAudioClip[] biteAudioClips = new RecRoomAudioClip[0];

		[SerializeField]
		private ParticleSystem[] biteParticles = new ParticleSystem[0];

		[NonSerialized]
		public bool SupportsAutomaticEating = true;

		private float minDistanceFromHeadSq = 0.04f;

		private float lastBiteTime;

		private bool initialized;

		private SynchronizedField<int> _biteCount;

		private int BiteCount
		{
			get
			{
				return _biteCount.Get();
			}
			set
			{
				_biteCount.Set(value);
			}
		}

		public void AuthorityTakeBite()
		{
			if (base.hasAuthority)
			{
				BiteCount++;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			tool.HeldCollisionLayer = Layers.DynamicPhysicsIgnoreStaticPhysics;
			tool.SuppressAnimateInOut = true;
			_biteCount = new SynchronizedField<int>(this, "BC", 0, SetterPermissionMode.AUTHORITY, OnBiteTaken);
			GameObject[] array = visualsAfterEachBite;
			foreach (GameObject gameObject in array)
			{
				gameObject.SetActive(value: false);
			}
			OnBiteTaken();
			initialized = true;
		}

		private void OnTriggerStay(Collider otherCollider)
		{
			if (SupportsAutomaticEating && UnityEngine.Time.time - lastBiteTime > minBiteInterval && tool.IsHeldByPlayer && tool.HolderHand != null && tool.HolderHand.isLocal && otherCollider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
			{
				otherCollider.GetColliderPlayer(out var bodyPart);
				if (bodyPart == Player.BodyPart.Mouth && Vector3.SqrMagnitude(tool.HolderPlayer.Head.transform.position - base.transform.position) < minDistanceFromHeadSq)
				{
					AuthorityTakeBite();
				}
			}
		}

		private void OnBiteTaken()
		{
			if (BiteCount >= 1)
			{
				visualsAfterEachBite[BiteCount - 1].SetActive(value: false);
				lastBiteTime = UnityEngine.Time.time;
			}
			if (initialized)
			{
				if (biteAudioClips.Length > 0)
				{
					RecRoomAudioClip recRoomAudioClip = biteAudioClips[UnityEngine.Random.Range(0, biteAudioClips.Length)];
					if (recRoomAudioClip != null)
					{
						AudioManager.Play3DSFX(recRoomAudioClip, base.transform.position);
					}
				}
				if (biteParticles.Length > 0)
				{
					ParticleSystem particleSystem = UnityEngine.Object.Instantiate(biteParticles[UnityEngine.Random.Range(0, biteParticles.Length)]);
					Transform transform = ((!(tool.HolderPlayer != null)) ? base.transform : tool.HolderPlayer.Head.transform);
					particleSystem.transform.position = transform.position + transform.forward * 0.2f - transform.up * 0.1f;
					particleSystem.Play();
					ParticleSystem.MainModule main = particleSystem.main;
					UnityEngine.Object.Destroy(particleSystem.gameObject, main.duration);
				}
			}
			if (BiteCount < visualsAfterEachBite.Length)
			{
				visualsAfterEachBite[BiteCount].SetActive(value: true);
			}
			else
			{
				tool.Disable();
			}
		}
	}
}
