	public class HandPotionConsumableEffect : ConsumableEffect
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private PlayerHand myHand;

		protected override void Awake()
		{
			base.Awake();
			base.SupportedCategories.Add(ConsumableManager.Category.Potion_Hand);
		}

		protected override void AddEffect(ConsumableItem consumableItem, bool showNotification)
		{
			base.AddEffect(consumableItem, showNotification);
			HandPotionConsumableItem handPotionConsumableItem = consumableItem as HandPotionConsumableItem;
			if (handPotionConsumableItem != null)
			{
				if (showNotification && myHand.isLocal)
				{
					ShowNotification(handPotionConsumableItem.FriendlyName + " activated");
				}
				myHand.PickupToolEvent += OnToolPickup;
				myHand.ReleaseToolEvent += OnToolRelease;
				myHand.Gestures.GestureDetectedCalledOnBothHands += OnHandGesture;
				myHand.Gestures.SuppressHighFive();
			}
		}

		protected override void RemoveEffect(ConsumableItem consumableItem, bool showNotification)
		{
			base.RemoveEffect(consumableItem, showNotification);
			HandPotionConsumableItem handPotionConsumableItem = consumableItem as HandPotionConsumableItem;
			if (handPotionConsumableItem != null)
			{
				if (showNotification && myHand.isLocal)
				{
					ShowNotification(handPotionConsumableItem.FriendlyName + " deactivated");
				}
				myHand.PickupToolEvent -= OnToolPickup;
				myHand.ReleaseToolEvent -= OnToolRelease;
				myHand.Gestures.GestureDetectedCalledOnBothHands -= OnHandGesture;
				myHand.Gestures.UnsuppressHighFive();
			}
		}

		private void OnToolPickup(PlayerHand hand, Tool tool)
		{
			Dictionary<string, GameObject>.ValueCollection allVisualEffects = GetAllVisualEffects();
			foreach (GameObject item in allVisualEffects)
			{
				item.SetActive(value: false);
			}
		}

		private void OnToolRelease(PlayerHand hand, Tool tool)
		{
			Dictionary<string, GameObject>.ValueCollection allVisualEffects = GetAllVisualEffects();
			foreach (GameObject item in allVisualEffects)
			{
				item.SetActive(value: true);
			}
		}

		private void OnHandGesture(PlayerHand triggeringHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture, Player triggeringPlayer = null, Player remotePlayer = null)
		{
			if ((!(triggeringHand == myHand) && !(otherHand == myHand)) || gesture != PlayerHandGestures.Gesture.Highfive)
			{
				return;
			}
			ConsumableItem activeConsumable = GetActiveConsumable();
			if (!(activeConsumable != null))
			{
				return;
			}
			HandPotionConsumableItem handPotionConsumableItem = activeConsumable as HandPotionConsumableItem;
			if (!(handPotionConsumableItem != null))
			{
				return;
			}
			Vector3 vector = ((!(otherHand == null)) ? ((myHand.transform.position + otherHand.transform.position) / 2f) : myHand.transform.position);
			if (handPotionConsumableItem.ParticleEffectObject != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(handPotionConsumableItem.ParticleEffectObject);
				if (pooledParticle != null)
				{
					pooledParticle.Play(vector, handPotionConsumableItem.ParticleEffectObject.transform.rotation);
				}
			}
			AudioClip onGestureAudio = handPotionConsumableItem.OnGestureAudio;
			if (onGestureAudio != null)
			{
				AudioManager.Play3DSFX(onGestureAudio, vector);
			}
			RecNet.Consumable[] array = localActiveConsumables.ToArray();
			foreach (RecNet.Consumable consumable in array)
			{
				LocalUseConsumable(consumable, 1);
			}
		}
	}
