		[Autofill(AutofillType.Self, false)]
		protected Potion potion;

		private bool hasBeenActivated;

		protected override void Awake()
		{
			base.Awake();
			if (base.IsMine)
			{
				tool.PostReleaseEvent += Tool_PostReleaseEvent;
				potion.PotionActivatedEvent += Potion_PotionActivatedEvent;
			}
		}

		protected override void OnDestroy()
		{
			if (base.IsMine)
			{
				tool.PostReleaseEvent -= Tool_PostReleaseEvent;
				potion.PotionActivatedEvent -= Potion_PotionActivatedEvent;
			}
			base.OnDestroy();
		}

		private void Tool_PostReleaseEvent(Tool thisTool)
		{
			if (!hasBeenActivated && !tool.IsSubTool && tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.GiftBox)
			{
				ShowAddedToBackpackNotification();
				PhotonNetwork.Destroy(base.gameObject);
			}
		}

		private void Potion_PotionActivatedEvent(Potion potion, PhotonPlayer player)
		{
			if (base.Consumable != null && base.IsMine && player != null && player.IsLocal)
			{
				NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.ActivateConsumable(base.Consumable, showNotification: true);
				hasBeenActivated = true;
			}
		}
	}
	[RequireComponent(typeof(Tool))]
	[RequireComponent(typeof(ToolSet))]
	public class SpawnerConsumableTool : ConsumableTool
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private ToolSet toolSet;

		private bool hasBeenConsumed;

		protected override void Awake()
		{
			base.Awake();
			if (base.IsMine)
			{
				tool.PostPickupEvent += Tool_PostPickupEvent;
				toolSet.OnPiecesSpawned += ToolSet_OnPiecesSpawned;
			}
		}

		protected override void OnDestroy()
		{
			if (base.IsMine)
			{
				tool.PostReleaseEvent -= Tool_PostPickupEvent;
				toolSet.OnPiecesSpawned -= ToolSet_OnPiecesSpawned;
			}
			base.OnDestroy();
		}

		private void Tool_PostPickupEvent(Tool thisTool)
		{
			if (!hasBeenConsumed && !tool.IsSubTool && tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.GiftBox)
			{
				ShowAddedToBackpackNotification();
				this.InvokeNextEndOfFrame(delegate
				{
					PhotonNetwork.Destroy(base.gameObject);
				});
			}
		}

		private void ToolSet_OnPiecesSpawned(List<Tool> pieces)
		{
			if (!base.IsMine)
			{
				return;
			}
			List<Tool> list = pieces.RemoveAllWhere((Tool c) => c.GetComponent<ConsumableSpawnedContainerToolPiece>() != null);
			foreach (Tool item in list)
			{
				item.GetComponent<ConsumableSpawnedContainerToolPiece>().SetNonHolderPieces(pieces, base.Consumable.ConsumableItem);
			}
			NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.UseConsumable(base.Consumable, 1, delegate(string error)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError($"Consumable Id:{base.Consumable.Id} Category:{base.Consumable.Category} can not be consumed: {error}");
					this.InvokeNextEndOfFrame(delegate
					{
						Tool[] array = pieces.ToArray();
						foreach (Tool tool in array)
						{
							tool.HolderInfo = ToolHolderInfo.NotHeld;
							PhotonNetwork.Destroy(tool.gameObject);
						}
					});
				}
			});
			hasBeenConsumed = true;
		}
	}
