		private Action<List<Tool>> m_OnPiecesSpawned;

		[SerializeField]
		private ToolPiece[] pieces;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		private bool hasBeenReleased;

		public event Action<List<Tool>> OnPiecesSpawned
		{
			add
			{
				Action<List<Tool>> action = this.m_OnPiecesSpawned;
				Action<List<Tool>> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPiecesSpawned, (Action<List<Tool>>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<List<Tool>> action = this.m_OnPiecesSpawned;
				Action<List<Tool>> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPiecesSpawned, (Action<List<Tool>>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			tool.PostReleaseEvent += OnRelease;
		}

		protected override void OnDestroy()
		{
			tool.PostReleaseEvent -= OnRelease;
			base.OnDestroy();
		}

		private void FixedUpdate()
		{
			if (!hasBeenReleased)
			{
				return;
			}
			bool flag = false;
			if (!tool.RigidbodyEx.IsSleeping())
			{
				float magnitude = tool.RigidbodyEx.angularVelocity.magnitude;
				flag = magnitude < 0.1f && tool.RigidbodyEx.velocity.magnitude < 0.01f;
			}
			else
			{
				flag = true;
			}
			if (flag && base.photonView.isLocal && pieces != null)
			{
				if (Vector3.Dot(base.transform.up, Vector3.up) > 0.9f)
				{
					SpawnPiecesAndDestroy();
					return;
				}
				base.transform.rotation = Quaternion.identity;
				flag = false;
			}
		}

		private void OnRelease(Tool tool)
		{
			this.tool.PostReleaseEvent -= OnRelease;
			hasBeenReleased = true;
		}

		protected virtual void SpawnPiecesAndDestroy()
		{
			List<Tool> list = new List<Tool>();
			ToolPiece[] array = pieces;
			for (int i = 0; i < array.Length; i++)
			{
				ToolPiece toolPiece = array[i];
				Tool tool = Tool.PhotonInstantiate(toolPiece.tool.name, base.transform.TransformPoint(toolPiece.initPosition), base.transform.TransformRotation(toolPiece.initRotation));
				if (tool != null)
				{
					list.Add(tool);
				}
			}
			if (this.OnPiecesSpawned != null)
			{
				this.OnPiecesSpawned(list);
			}
			PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
		}

		private void OnDrawGizmos()
		{
			if (pieces != null)
			{
				ToolPiece[] array = pieces;
				for (int i = 0; i < array.Length; i++)
				{
					ToolPiece toolPiece = array[i];
					Vector3 vector = base.transform.TransformPoint(toolPiece.initPosition);
					Gizmos.color = Color.green;
					Gizmos.DrawSphere(vector, 0.05f);
					Gizmos.color = Color.blue;
					Gizmos.DrawRay(vector, base.transform.TransformRotation(toolPiece.initRotation) * base.transform.forward * 0.05f);
				}
			}
		}
	}
