public class DrawerEquipmentContainer : SpawnedEquipmentContainer
{
	public enum DrawerToolState
	{
		Closed,
		AnimatingIn,
		Open,
		AnimatingOut
	}

	public class AnimationTarget
	{
		public Vector3 localPosition;

		public Quaternion rotation;

		public float angle;

		public float radius;
	}

	private DrawerToolState state;

	private float initialScale = 1f;

	private SpawnedEquipmentDrawer drawer;

	private Transform centerTransform;

	private float animationStartTime;

	private float animateInSpeed;

	private float minScale = 0.05f;

	private float animateOutTime = 0.1f;

	public AnimationTarget target;

	public DrawerToolState State
	{
		get
		{
			return state;
		}
		set
		{
			if (value != state)
			{
				state = value;
				animationStartTime = UnityEngine.Time.time;
			}
		}
	}

	protected void Awake()
	{
		useEquipmentSpawnRotation = false;
	}

	public void Initialize(Tool tool, SpawnedEquipmentDrawer drawer)
	{
		this.drawer = drawer;
		animateInSpeed = drawer.CurrentConfig.AnimateSpeed;
		centerTransform = drawer.RingCenterTransform;
		toolAttachedScale = drawer.CurrentConfig.ItemScaleFactor;
		initialScale = tool.transform.GetLocalUniformScale();
		AttachTool(tool);
	}

	public override void OnPickup(Tool tool)
	{
		base.OnPickup(tool);
		tool.transform.SetLocalUniformScale(initialScale);
	}

	public override void OnReleased(Tool tool)
	{
		base.OnReleased(tool);
		Vector3 position = tool.transform.position;
		Quaternion rotation = tool.transform.rotation;
		AttachTool(tool);
		tool.SuppressAnimateInOut = true;
		if (!drawer.IsSelected)
		{
			tool.PlayAnimateInOutEffect(animIn: false, position, rotation);
		}
		tool.IsEnabled = drawer.IsSelected;
		tool.SetUsingGravityRigidBody(usingGravity: false);
	}

	private void FixedUpdate()
	{
		if (base.Tool.IsHeld)
		{
			return;
		}
		switch (State)
		{
		case DrawerToolState.Open:
			break;
		case DrawerToolState.Closed:
			if (!base.Tool.IsHeld)
			{
				base.Tool.IsEnabled = false;
			}
			break;
		case DrawerToolState.AnimatingIn:
			UpdatePathing(centerTransform.position, centerTransform.rotation, DrawerToolState.Open);
			if (!base.Tool.IsHeld)
			{
				base.Tool.IsEnabled = true;
			}
			break;
		case DrawerToolState.AnimatingOut:
			UpdateScale(DrawerToolState.Closed);
			break;
		}
	}

	private void UpdateScale(DrawerToolState nextState)
	{
		float num = Mathf.Clamp01((UnityEngine.Time.time - animationStartTime) / animateOutTime);
		float uniformScale = Mathf.Lerp(drawer.CurrentConfig.ItemScaleFactor, minScale, num);
		base.Tool.transform.SetLocalUniformScale(uniformScale);
		if (num >= 1f)
		{
			state = nextState;
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.DrawWireSphere(base.transform.position, 0.025f);
	}

	private void UpdatePathing(Vector3 centerPosition, Quaternion startRotation, DrawerToolState nextState)
	{
		if (target != null)
		{
			float num = target.angle / animateInSpeed;
			float num2 = Mathf.Clamp01((UnityEngine.Time.time - animationStartTime) / num);
			float num3 = target.angle * num2;
			Quaternion quaternion = Quaternion.AngleAxis(num3, Vector3.up);
			Vector3 position = centerPosition + quaternion * (centerTransform.forward * target.radius);
			Vector3 position2 = drawer.transform.position;
			float t = Mathf.Clamp01(num3 / ((float)drawer.FrontGapDegrees / 2f));
			position.x = Mathf.Lerp(position2.x, position.x, t);
			position.y = Mathf.Lerp(position2.y, position.y, t);
			position.z = Mathf.Lerp(position2.z, position.z, t);
			float num4 = Mathf.Lerp(0f, target.localPosition.y, num2);
			position.y += num4;
			base.transform.position = position;
			base.transform.rotation = Quaternion.Lerp(centerTransform.rotation, target.rotation, num2);
			float num5 = Mathf.Clamp01(num2 / 0.25f);
			base.Tool.transform.SetLocalUniformScale(drawer.CurrentConfig.ItemScaleFactor * num5);
			if (num2 >= 1f)
			{
				State = nextState;
				base.transform.localPosition = target.localPosition;
				base.transform.rotation = target.rotation;
			}
		}
	}
}
