	private void AttachTool(Tool tool)
	{
		tool.SetUsingGravityRigidBody(usingGravity: false);
		tool.transform.localPosition = Vector3.zero;
		tool.transform.localRotation = Quaternion.identity;
		tool.transform.localScale = Vector3.one;
		tool.transform.SetParent(base.transform, worldPositionStays: false);
	}

	public virtual void OnReleased(Tool tool)
	{
		if (!(AssignedTool != tool))
		{
			if (assignedToolInside)
