			else if (this.AssignedToolReleasedOutside != null)
			{
				this.AssignedToolReleasedOutside(this, tool);
			}
		}
	}

	private void FixedUpdate()
	{
		HasTool = false;
		assignedToolInside = false;
		bool flag = false;
		Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
		int num = Physics.OverlapSphereNonAlloc(base.transform.TransformPoint(sphereCollider.center), sphereCollider.radius * sphereCollider.transform.GetLocalUniformScale(), iMMEDIATE_COLLIDER_HITS, 495330304);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = iMMEDIATE_COLLIDER_HITS[i].GetColliderTool();
			if (!(colliderTool != null) || !(colliderTool.PlayerSpawnedEquipment != null) || colliderTool.PlayerSpawnedEquipment.ToolPurpose != PlayerSpawnedEquipment.Purpose.Drawer)
			{
				continue;
			}
			HasTool = true;
			if (colliderTool == AssignedTool)
			{
				assignedToolInside = true;
			}
			else if (trackedTool != null)
			{
				if (trackedTool == colliderTool)
				{
					flag = true;
				}
			}
			else
			{
				trackedTool = colliderTool;
				trackedTool.PostReleaseEvent += TrackedTool_PostReleaseEvent;
				flag = true;
			}
		}
		if (!flag && trackedTool != null)
		{
			trackedTool.PostReleaseEvent -= TrackedTool_PostReleaseEvent;
			trackedTool = null;
		}
	}

	private void TrackedTool_PostReleaseEvent(Tool thisTool)
	{
