	private AnimateInOut animateInOut;

	private Collider[] overlapHitResults = new Collider[10];

	public bool Visible
	{
		get
		{
			return _visible;
		}
		set
		{
			if (_visible != value)
			{
				_visible = value;
				visual.gameObject.SetActive(_visible);
				if (animateInOut != null)
				{
					animateInOut.PlayEffect(_visible);
				}
			}
		}
	}

	private void Awake()
	{
		Visible = false;
		animateInOut = GetComponent<AnimateInOut>();
	}

	private void Update()
	{
		int overlapNonAlloc = boxCollider.GetOverlapNonAlloc(495330304, QueryTriggerInteraction.Ignore, overlapHitResults);
		for (int i = 0; i < overlapNonAlloc; i++)
		{
			Tool colliderTool = overlapHitResults[i].GetColliderTool();
			if (colliderTool != null && colliderTool.IsHeld && colliderTool.SkinMapper != null && colliderTool.PlayerSpawnedEquipment != null && colliderTool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.Drawer)
			{
				NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.ToggleFavoriteEquipment(colliderTool.SkinMapper);
				colliderTool.PlayAnimateInOutEffect(animIn: false, colliderTool.transform.position, colliderTool.transform.rotation);
