	{
		Dictionary<string, object> dictionary = new Dictionary<string, object>();
		dictionary.Add("Owner", PhotonNetwork.player.ID);
		dictionary.Add("Purpose", (int)purpose);
		dictionary.Add("ModificationGuid", modificationGuid);
		Dictionary<string, object> instantiationParameters = dictionary;
		Tool tool = Tool.PhotonInstantiate(prefabName, position, rotation, scale, base.photonView.viewID, instantiationParameters);
		if (tool != null)
		{
			if (purpose == PlayerSpawnedEquipment.Purpose.Drawer)
			{
				tool.SuppressAnimateInOut = true;
			}
			if (tool.PlayerSpawnedEquipment != null)
			{
				Equipment equipment = UnlockedEquipments.FindLast((Equipment e) => e.PrefabName == prefabName && e.ModificationGuid == modificationGuid);
				if (equipment != null)
				{
					tool.PlayerSpawnedEquipment.Level = equipment.UnlockedLevel;
				}
				else if (level.HasValue)
				{
					tool.PlayerSpawnedEquipment.Level = level.Value;
				}
			}
		}
		else
		{
			UnityEngine.Debug.LogError($"Failed to spawn equipment {prefabName} for local player.");
		}
		return tool;
	}

	public GameObject SpawnEquipmentImposter(string prefabName, string modificationGuid)
	{
		GameObject prefab = PhotonNetwork.GetPrefab(prefabName);
		return SpawnEquipmentImposter(prefab, modificationGuid);
	}

	public GameObject SpawnEquipmentImposter(GameObject prefab, string modificationGuid)
	{
		ImposterParameters parameters = default(ImposterParameters);
		if (!string.IsNullOrEmpty(modificationGuid))
		{
			EquipmentSkin equipmentSkin = GetEquipmentSkin(modificationGuid);
			if (equipmentSkin != null)
			{
				parameters = new ImposterParameters
				{
					skinOverride = equipmentSkin
				};
			}
		}
		return VisualImposter.SpawnImposter(prefab, null, parameters, preserveColliders: true);
	}

	public Tool LocalFind(Equipment equipment, PlayerSpawnedEquipment.Purpose purpose)
	{
		foreach (PlayerSpawnedEquipment item in PlayerSpawnedEquipment.All)
		{
			if (item != null && item.IsMine && item.ToolPurpose == purpose && item.Tool != null && item.Tool.SkinMapper != null && item.Tool.SkinMapper.PrefabName == equipment.PrefabName && item.Tool.SkinMapper.ActiveSkinGuid == equipment.ModificationGuid)
			{
				return item.Tool;
			}
		}
		return null;
	}

	public IEnumerator DownloadUnlockedEquipments(RecNet.Core.ApiCallback callback)
	{
		return Equipments.DowloadUnlockedEquipments(delegate(string error, List<Equipment> selections)
		{
			if (selections != null)
			{
				foreach (Equipment selection in selections)
				{
					if (!IsEquipmentRevoked(selection.PrefabName, selection.ModificationGuid))
					{
						RemoveUnlockedEquipment(selection.PrefabName, selection.ModificationGuid);
						UnlockedEquipments.Add(selection);
						if (selection.IsPlatformLocked)
						{
							HasPlatformLockedEquipment = true;
						}
						if (selection.Favorited && !FavoriteEquipments.ContainsKey(selection.PrefabName))
						{
							FavoriteEquipments.Add(selection.PrefabName, selection);
						}
					}
				}
			}
			foreach (EquipmentSelection item in defaultUnlockedEquipments)
			{
				if (item != null && item.toolSkinMapper != null && item.skin != null && !UnlockedEquipments.Any((Equipment e) => e.PrefabName == item.toolSkinMapper.PrefabName && item.skin.Guid == e.ModificationGuid))
				{
					UnlockedEquipments.Add(new Equipment
					{
						PrefabName = item.toolSkinMapper.PrefabName,
						ModificationGuid = item.skin.Guid,
						UnlockedLevel = 0
					});
				}
			}
			RecNet.Core.SafeInvoke(callback, error);
		});
	}

	public Equipment LocalGetEquipmentFromTool(Tool tool)
	{
		if (tool.SkinMapper != null && tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.IsMine)
		{
			foreach (Equipment unlockedEquipment in UnlockedEquipments)
			{
				string text = ((!(tool.SkinMapper.ActiveSkin != null)) ? string.Empty : tool.SkinMapper.ActiveSkin.Guid);
				if (unlockedEquipment.PrefabName == tool.SkinMapper.PrefabName && text == unlockedEquipment.ModificationGuid)
				{
					return unlockedEquipment;
				}
			}
		}
		return null;
	}

	public EquipmentSkin GetEquipmentSkin(string skinGuid)
	{
		foreach (EquipmentSkin item in EquipmentSkin.All)
		{
			if (item.Guid == skinGuid)
			{
				return item;
			}
		}
		UnityEngine.Debug.LogErrorFormat("Failed to find skin {0}", skinGuid);
		return null;
	}

	public Equipment GetEquipment(ToolSkinMapper toolSkinMapper)
	{
		foreach (Equipment unlockedEquipment in UnlockedEquipments)
		{
			if (unlockedEquipment != null && unlockedEquipment.PrefabName == toolSkinMapper.PrefabName && unlockedEquipment.ModificationGuid == toolSkinMapper.ActiveSkinGuid)
			{
				return unlockedEquipment;
			}
		}
		return null;
	}

	public string GetFavoriteEquipmentSkin(ToolSkinMapper toolSkinMapper)
	{
		return GetFavoriteEquipment(toolSkinMapper)?.ModificationGuid;
	}

	public string GetFavoriteEquipmentSkin(string prefabName)
	{
		return GetFavoriteEquipment(prefabName)?.ModificationGuid;
	}

	public bool IsFavoriteEquipment(ToolSkinMapper toolSkinMapper)
	{
		Equipment favoriteEquipment = GetFavoriteEquipment(toolSkinMapper);
		if (favoriteEquipment != null)
		{
			return favoriteEquipment.ModificationGuid == toolSkinMapper.ActiveSkinGuid;
		}
		return false;
	}

	public Equipment GetFavoriteEquipment(string prefabName)
	{
		if (FavoriteEquipments.TryGetValue(prefabName, out var value))
		{
			return value;
		}
		return null;
	}

	public Equipment GetFavoriteEquipment(ToolSkinMapper toolSkinMapper)
	{
		return GetFavoriteEquipment(toolSkinMapper.PrefabName);
	}

	public void ToggleFavoriteEquipment(ToolSkinMapper toolSkinMapper)
	{
		Equipment equipment = GetEquipment(toolSkinMapper);
		if (equipment == null)
		{
			return;
		}
		if (toolSkinMapper.ThisTool != null && toolSkinMapper.ThisTool.HolderHand != null)
		{
			toolSkinMapper.ThisTool.HolderHand.Vibrate(500);
			AudioManager.Play3DSFX(SingletonMonoBehaviour<AudioManager>.Instance.ToolFavoriteSkinAudio, toolSkinMapper.transform.position);
		}
		if (!equipment.Favorited)
		{
			Equipment favoriteEquipment = GetFavoriteEquipment(toolSkinMapper);
			if (favoriteEquipment != null)
			{
				favoriteEquipment.Favorited = false;
				FavoriteEquipments.Remove(toolSkinMapper.PrefabName);
			}
			equipment.Favorited = true;
			FavoriteEquipments.Add(toolSkinMapper.PrefabName, equipment);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Favorite skin set.", 2f);
		}
		else
		{
			equipment.Favorited = false;
			FavoriteEquipments.Remove(toolSkinMapper.PrefabName);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Favorite skin removed!", 2f);
		}
		Equipments.UpdateFavorites();
		if (this.FavoriteEquipmentChanged != null)
		{
			this.FavoriteEquipmentChanged(PhotonNetwork.player, toolSkinMapper.PrefabName);
		}
	}

	public bool IsEquipmentUnlockedOnCurrentPlatform(string guid)
	{
		return (from e in UnlockedEquipments
			where !e.IsPlatformLocked
			select e.ModificationGuid).Contains(guid) || SingletonMonoBehaviour<GiftManager>.Instance.IsEquipmentUnlockedOnCurrentPlatform(guid);
	}

	public bool IsEquipmentLockedOnCurrentPlatform(string guid)
	{
		return (from e in UnlockedEquipments
			where e.IsPlatformLocked
			select e.ModificationGuid).Contains(guid);
	}

	public void UpdateUnlockedEquipmentsFor(string equipmentPrefabName, string equipmentModificationGuid, int level)
	{
		foreach (Equipment unlockedEquipment in UnlockedEquipments)
		{
			if (unlockedEquipment.PrefabName == equipmentPrefabName && unlockedEquipment.ModificationGuid == equipmentModificationGuid)
			{
				return;
			}
		}
		Equipment equipment = Equipment.Create(equipmentPrefabName, equipmentModificationGuid, level);
		UnlockedEquipments.Add(equipment);
		if (this.NewEquipmentUnlocked != null)
		{
			this.NewEquipmentUnlocked(equipment);
		}
	}

	public void RevokeUnlockedEquipmentsFor(string equipmentPrefabName, string equipmentModificationGuid)
	{
		if (!IsEquipmentRevoked(equipmentPrefabName, equipmentModificationGuid))
		{
			Equipment item = Equipment.Create(equipmentPrefabName, equipmentModificationGuid, 0);
			RevokedEquipments.Add(item);
			RemoveUnlockedEquipment(equipmentPrefabName, equipmentModificationGuid);
		}
	}

	private bool IsEquipmentRevoked(string equipmentPrefabName, string equipmentModificationGuid)
	{
		foreach (Equipment revokedEquipment in RevokedEquipments)
		{
			if (revokedEquipment.PrefabName == equipmentPrefabName && revokedEquipment.ModificationGuid == equipmentModificationGuid)
			{
				return true;
			}
		}
		return false;
	}

	private bool RemoveUnlockedEquipment(string equipmentPrefabName, string equipmentModificationGuid)
	{
		foreach (Equipment unlockedEquipment in UnlockedEquipments)
		{
			if (unlockedEquipment.PrefabName == equipmentPrefabName && unlockedEquipment.ModificationGuid == equipmentModificationGuid)
			{
				if (unlockedEquipment.Favorited)
				{
					FavoriteEquipments.Remove(equipmentPrefabName);
				}
				UnlockedEquipments.Remove(unlockedEquipment);
				return true;
			}
		}
		return false;
	}

	private void OnToolInstantiated(Tool tool)
	{
		if (!tool.IsSubTool && tool.InstantiationParameters != null && tool.InstantiationParameters.TryGetValue("Purpose", out var value))
		{
			PlayerSpawnedEquipment.Purpose purpose = (PlayerSpawnedEquipment.Purpose)value;
			if (purpose != PlayerSpawnedEquipment.Purpose.None)
			{
				tool.PlayerSpawnedEquipment = tool.gameObject.AddComponent<PlayerSpawnedEquipment>();
				int spawningPlayerId = (int)tool.InstantiationParameters["Owner"];
				tool.PlayerSpawnedEquipment.SetSpawningPlayer(tool, spawningPlayerId, purpose);
			}
		}
	}
}
public class EquipmentSkin : AvatarSelectionElement
{
	[Serializable]
	public class MeshAssetMapping
	{
		public string name;

		public Mesh mesh;

		public bool IsValid => mesh != null;

		public bool Equals(MeshAssetMapping other)
		{
			return mesh == other.mesh;
		}
	}

	[Serializable]
	public class MaterialsMapping
	{
		public string name;

		public Material[] materials;

		public bool IsValid
		{
			get
			{
				if (materials == null || materials.Length == 0)
				{
					return false;
				}
				Material[] array = materials;
				foreach (Material material in array)
				{
					if (material == null)
					{
						return false;
					}
				}
				return true;
			}
		}

		public bool Equals(MaterialsMapping other)
		{
			if (other.materials.Length != materials.Length)
			{
				return false;
			}
			for (int i = 0; i < materials.Length; i++)
			{
				if (materials[i] != other.materials[i])
				{
					return false;
				}
			}
			return true;
		}
	}

	[Serializable]
	public class GameObjectActionMapping
	{
		public enum GameObjectAction
		{
			None,
			Enable,
			Disable,
			Instantiate
		}

		public string name;

		public GameObjectAction action;

		public GameObject prefabToInstantiate;
	}

	public static List<EquipmentSkin> All = new List<EquipmentSkin>();

	public List<MeshAssetMapping> MeshMappings;

	public List<MaterialsMapping> MaterialMappings;

	public List<GameObjectActionMapping> GameObjectActionMappings;

	public EquipmentSkin()
	{
		All.Add(this);
	}

	~EquipmentSkin()
	{
		if (All.Contains(this))
		{
			All.Remove(this);
		}
	}

	public bool ContainsMappings(List<MeshAssetMapping> meshMappings, List<MaterialsMapping> materialMappings)
	{
		if ((meshMappings == null && MeshMappings != null) || (meshMappings != null && MeshMappings == null))
		{
			return false;
		}
		if (meshMappings != null && MeshMappings != null)
		{
			if (meshMappings.Count != MeshMappings.Count)
			{
				return false;
			}
			for (int i = 0; i < meshMappings.Count; i++)
			{
				if (!meshMappings[i].Equals(MeshMappings[i]))
				{
					return false;
				}
			}
		}
		if ((materialMappings == null && MaterialMappings != null) || (materialMappings != null && MaterialMappings == null))
		{
			return false;
		}
		if (materialMappings != null && MaterialMappings != null)
		{
			if (materialMappings.Count != MaterialMappings.Count)
			{
				return false;
			}
			for (int j = 0; j < materialMappings.Count; j++)
			{
				if (!materialMappings[j].Equals(MaterialMappings[j]))
				{
					return false;
				}
			}
		}
		return true;
	}
}
public class GiftBoxEquipmentContainer : SpawnedEquipmentContainer
{
	public override void AttachTool(Tool tool)
	{
		base.AttachTool(tool);
		if (base.Tool != null && base.Tool.PlayerSpawnedEquipment != null)
		{
			base.Tool.PostPickupEvent += Tool_PostPickupEvent;
		}
	}

	public override void OnReleased(Tool tool)
	{
		base.OnReleased(tool);
		if (tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.IsMine && tool.GetComponent<OutfitTool>() != null)
		{
			tool.AuthorityResetToLastSpawnPosition();
		}
	}

	private void Tool_PostPickupEvent(Tool thisTool)
	{
		if (thisTool != null && thisTool.PlayerSpawnedEquipment != null)
		{
			thisTool.PostPickupEvent -= Tool_PostPickupEvent;
			Player spawningPlayer = thisTool.PlayerSpawnedEquipment.SpawningPlayer;
			if (spawningPlayer != null)
			{
				thisTool.SetParentTransform(spawningPlayer.Root.transform, worldPositionStays: true);
			}
			thisTool.SetUsingGravityRigidBody(usingGravity: true);
		}
	}
}
[DisallowMultipleComponent]
public class PlayerSpawnedEquipment : Photon.MonoBehaviour, IPersistable
{
	public delegate bool ShouldUseLongerDistanceForBackpackCleanupBehavior();

	public enum Purpose
	{
		None,
		Backpack,
		GiftBox,
		Drawer,
		Streaming
	}

	private const float BackpackToolRadius = 0.075f;

	private const float BackpackToolCleanupDistShort = 3f;

	private const float BackpackToolCleanupDistLong = 15f;

	private const float BackpackToolCleanupDistShortSqr = 9f;

	private const float BackpackToolCleanupDistLongSqr = 225f;

	public ShouldUseLongerDistanceForBackpackCleanupBehavior CustomShouldUseLongerDistanceForBackpackCleanup;

	public static List<PlayerSpawnedEquipment> All = new List<PlayerSpawnedEquipment>();

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<PlayerSpawnedEquipment> m_PickupAttemptEvent;

	private ToolCleanup toolCleanup;

	private int _level;

	private const int TRUE = 1;

	private const int FALSE = 0;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<PlayerSpawnedEquipment, bool> m_OnIsNewChanged;

	public bool IsPlatformLocked;

	private bool _isWearing;

	bool IPersistable.BlockObjectPersistance => true;

	public Purpose ToolPurpose { get; set; }

	public int SpawningPlayerId { get; private set; }

	public Player SpawningPlayer { get; private set; }

	public bool IsMine { get; private set; }

	public Tool Tool { get; private set; }

	public int Level
	{
		get
		{
			return _level;
		}
		set
		{
			if (value != _level)
			{
				_level = value;
				UpdateItemUI();
			}
		}
	}

	public string IS_NEW_PROPERTY => Player.LocalPlayer.PlayerId + ".Item.Used." + Tool.ToString();

	public bool IsNew
	{
		get
		{
			return IsMine && PlayerPrefs.GetInt(IS_NEW_PROPERTY, 1) == 1;
		}
		set
		{
			if (IsMine)
			{
				PlayerPrefs.SetInt(IS_NEW_PROPERTY, value ? 1 : 0);
				UpdateItemUI();
				if (this.OnIsNewChanged != null)
				{
					this.OnIsNewChanged(this, value);
				}
			}
		}
	}

	private bool IsLevelLocked => SpawningPlayer != null && SpawningPlayer.PlayerProgression.Level < Level;

	public bool IsWearing
	{
		get
		{
			return _isWearing;
		}
		set
		{
			_isWearing = value;
			UpdateItemUI(_isWearing);
		}
	}

	public bool IsFavorite => Tool != null && Tool.SkinMapper != null && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.IsFavoriteEquipment(Tool.SkinMapper);

	public OutfitToolUIControl ToolUIControl { get; private set; }

	public event Action<PlayerSpawnedEquipment> PickupAttemptEvent
	{
		add
		{
			Action<PlayerSpawnedEquipment> action = this.m_PickupAttemptEvent;
			Action<PlayerSpawnedEquipment> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PickupAttemptEvent, (Action<PlayerSpawnedEquipment>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<PlayerSpawnedEquipment> action = this.m_PickupAttemptEvent;
			Action<PlayerSpawnedEquipment> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PickupAttemptEvent, (Action<PlayerSpawnedEquipment>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public event Action<PlayerSpawnedEquipment, bool> OnIsNewChanged
	{
		add
		{
			Action<PlayerSpawnedEquipment, bool> action = this.m_OnIsNewChanged;
			Action<PlayerSpawnedEquipment, bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnIsNewChanged, (Action<PlayerSpawnedEquipment, bool>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<PlayerSpawnedEquipment, bool> action = this.m_OnIsNewChanged;
			Action<PlayerSpawnedEquipment, bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnIsNewChanged, (Action<PlayerSpawnedEquipment, bool>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		All.Add(this);
	}

	public void SetSpawningPlayer(Tool tool, int spawningPlayerId, Purpose purpose)
	{
		if (Tool != null)
		{
			Tool.PostPickupEvent -= OnPostPickup;
			Tool.PostResetEvent -= OnReset;
		}
		Tool = tool;
		SpawningPlayerId = spawningPlayerId;
		IsMine = SpawningPlayerId == PhotonNetwork.player.ID;
		PhotonPlayer photonPlayer = PhotonPlayer.Find(spawningPlayerId);
		SpawningPlayer = photonPlayer.ToPlayer();
		if (SpawningPlayer != null)
		{
			base.transform.parent = SpawningPlayer.Root.transform;
		}
		ToolPurpose = purpose;
		if (ToolPurpose == Purpose.GiftBox || ToolPurpose == Purpose.Drawer)
		{
			Tool.AllowedToTransferOwnershipOnCollision = false;
			Tool.AddCustomPickupCondition(OwnerOnlyToolPickupCondition);
			Tool.CanBePickedUp = true;
		}
		if (ToolPurpose == Purpose.GiftBox)
		{
			Tool.CustomAuthorityResetOnKillzoneBehavior = DoNotResetOnKillzoneBehavior;
		}
		toolCleanup = Tool.ToolCleanup;
		toolCleanup.Owner = SpawningPlayer;
		toolCleanup.PauseCleanup(this);
		if (ToolPurpose != Purpose.Backpack)
		{
			Tool.SuppressAnimateInOut = true;
		}
		Tool.PostPickupEvent += OnPostPickup;
		Tool.PostResetEvent += OnReset;
	}

	private void Start()
	{
		Tool.RigidbodyEx.AddKinematic(this);
		Tool.RigidbodyEx.useGravity = false;
		if (IsMine)
		{
			SpawningPlayer.PlayerEvents.LevelUpEvent += UpdateItemUI;
			if (NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.FavoriteEquipmentChanged += EquipmentManager_FavoriteEquipmentChanged;
			}
			UpdateItemUI();
		}
		ToolPlayerAttractor componentInChildren = GetComponentInChildren<ToolPlayerAttractor>(includeInactive: true);
		if (componentInChildren != null && ToolPurpose != Purpose.None)
		{
			componentInChildren.SuppressAttractor = true;
		}
		this.Update10hz(delegate
		{
			UpdateRunCleanUp();
		});
	}

	protected override void OnDestroy()
	{
		if (Tool != null)
		{
			Tool.PostPickupEvent -= OnPostPickup;
			Tool.PostResetEvent -= OnReset;
		}
		if (IsMine)
		{
			if (NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.FavoriteEquipmentChanged -= EquipmentManager_FavoriteEquipmentChanged;
			}
			if (SpawningPlayer != null)
			{
				SpawningPlayer.PlayerEvents.LevelUpEvent -= UpdateItemUI;
			}
		}
		All.Remove(this);
		base.OnDestroy();
	}

	private void UpdateRunCleanUp()
	{
		if (!IsMine)
		{
			return;
		}
		if (ToolPurpose == Purpose.Backpack && Tool.IsEnabled && Tool.IsVisible && Player.LocalPlayerExists && !Tool.IsHeldByPlayer)
		{
			Vector3 position = Tool.transform.position;
			float sqrMagnitude = (position - Player.LocalPlayer.Head.transform.position).sqrMagnitude;
			float num = ((CustomShouldUseLongerDistanceForBackpackCleanup == null || !CustomShouldUseLongerDistanceForBackpackCleanup()) ? 9f : 225f);
			if (sqrMagnitude >= num)
			{
				Player.LocalPlayer.Backpack.RecallTool(Tool);
			}
		}
		else if (ToolPurpose == Purpose.GiftBox && !Tool.IsSubTool)
		{
			toolCleanup.CheckCleanup();
		}
	}

	private bool DoNotResetOnKillzoneBehavior(Tool thisTool, Killzone killzone)
	{
		return true;
	}

	private bool OwnerOnlyToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		return thisTool.Owner != null && thisTool.Owner == selectingPlayer;
	}

	public bool TryPickupSpawnedEquipment(Player player)
	{
		if (this.PickupAttemptEvent != null)
		{
			this.PickupAttemptEvent(this);
		}
		if (Level > player.PlayerProgression.Level)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "You need to be level " + Level + " to use this", 1.5f);
			SingletonMonoBehaviour<TutorialManager>.Instance.PlayVO(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.LockedOutfitToolClip);
			if (ToolPurpose == Purpose.GiftBox)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
			return false;
		}
		if (ToolPurpose == Purpose.GiftBox && IsNew)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Item saved!", 3f);
		}
		if (ToolPurpose == Purpose.Drawer)
		{
			IsNew = false;
		}
		if (IsPlatformLocked)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "This item cannot be used here due to PlayStation® policies.", 1.5f);
			if (ToolPurpose == Purpose.GiftBox)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
			return false;
		}
		return true;
	}

	private void OnPostPickup(Tool tool)
	{
		if (ToolPurpose != Purpose.Drawer && ToolPurpose != Purpose.None)
		{
			tool.RigidbodyEx.RemoveKinematic(this);
			tool.RigidbodyEx.useGravity = true;
		}
	}

	private void OnReset(Tool arg1, Vector3 arg2, Quaternion arg3, Vector3 oldPosition, bool wasCleanedUp)
	{
		if (ToolPurpose == Purpose.GiftBox && Tool.hasAuthority)
		{
			PhotonNetwork.Destroy(Tool.gameObject);
		}
	}

	private void EquipmentManager_FavoriteEquipmentChanged(PhotonPlayer photonPlayer, string prefabName)
	{
		UpdateItemUI();
	}

	private void UpdateItemUI(int level)
	{
		UpdateItemUI();
	}

	private void UpdateItemUI(bool updatePlacement = false)
	{
		bool flag = IsNew || IsLevelLocked || IsFavorite || IsWearing || IsPlatformLocked;
		if (IsMine && flag && (ToolPurpose == Purpose.GiftBox || ToolPurpose == Purpose.Drawer) && ToolUIControl == null)
		{
			ToolUIControl = UnityEngine.Object.Instantiate(NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitToolUIControlPrefab);
			updatePlacement = true;
		}
		if (ToolUIControl != null)
		{
			ToolUIControl.SetLockLevel(Level);
			ToolUIControl.State = OutfitToolUIControl.ItemProgressionState.None;
			if (IsNew)
			{
				ToolUIControl.State |= OutfitToolUIControl.ItemProgressionState.New;
			}
			if (IsLevelLocked)
			{
				ToolUIControl.State |= OutfitToolUIControl.ItemProgressionState.LevelLocked;
			}
			if (IsFavorite)
			{
				ToolUIControl.State |= OutfitToolUIControl.ItemProgressionState.Favorite;
			}
			if (IsWearing)
			{
				ToolUIControl.State |= OutfitToolUIControl.ItemProgressionState.Wearing;
			}
			if (IsPlatformLocked)
			{
				ToolUIControl.State |= OutfitToolUIControl.ItemProgressionState.PlatformLocked;
			}
			if (flag || updatePlacement)
			{
				ToolUIControl.UpdatePlacement(Tool);
			}
		}
	}

	void IPersistable.DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
	}

	void IPersistable.SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
	}
}
public class SpawnedEquipmentContainer : UnityEngine.MonoBehaviour
{
	protected Tool prevTool;

	protected bool useEquipmentSpawnRotation = true;

	protected float toolAttachedScale = 1f;

	public Tool Tool { get; set; }

	public virtual void AttachTool(Tool tool)
	{
		Tool = tool;
		Tool.SetUsingGravityRigidBody(usingGravity: false);
		Tool.transform.localPosition = Vector3.zero;
		Quaternion localRotation = ((!useEquipmentSpawnRotation || Tool.SpawnableToolType == SpawnableToolType.INVALID) ? Quaternion.identity : SpawnableToolSettings.GetSpawnableToolSpawnRotation(Tool.SpawnableToolType));
		Tool.transform.localRotation = localRotation;
		Tool.transform.SetLocalUniformScale(toolAttachedScale);
		Tool.SetParentTransform(base.transform, worldPositionStays: false);
		if (prevTool != Tool)
		{
			if (Tool != null && Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.IsMine)
			{
				tool.PostPickupEvent += OnPickup;
				tool.PostReleaseEvent += OnReleased;
			}
			else if (prevTool != null && prevTool.PlayerSpawnedEquipment != null && prevTool.PlayerSpawnedEquipment.IsMine)
			{
				prevTool.PostPickupEvent -= OnPickup;
				prevTool.PostReleaseEvent -= OnReleased;
			}
		}
		prevTool = Tool;
	}

	public virtual void OnPickup(Tool tool)
	{
	}

	public virtual void OnReleased(Tool tool)
	{
	}
}
[DisallowMultipleComponent]
public class ToolSkinMapper : Photon.MonoBehaviour, ICustomImposterBehavior
{
	[Serializable]
	public class MeshComponentMapping
	{
		public string name;

		public bool IsSkinned;

		public MeshFilter MeshFilter;

		public SkinnedMeshRenderer SkinnedMeshRenderer;

		[HideInInspector]
		public Mesh OriginalMesh;

		public Mesh SharedMesh
		{
			get
			{
				Mesh result = null;
				if (IsSkinned && SkinnedMeshRenderer != null)
				{
					result = SkinnedMeshRenderer.sharedMesh;
				}
				else if (MeshFilter != null)
				{
					result = MeshFilter.sharedMesh;
				}
				return result;
			}
			set
			{
				if (IsSkinned && SkinnedMeshRenderer != null)
				{
					SkinnedMeshRenderer.sharedMesh = value;
				}
				else if (MeshFilter != null)
				{
					MeshFilter.sharedMesh = value;
				}
			}
		}
	}

	[Serializable]
	public class RendererMapping
	{
		public string name;

		public Renderer renderer;

		[HideInInspector]
		public Material[] OriginalMaterials;
	}

	[Serializable]
	public class GameObjectMapping
	{
		public string name;

		public GameObject gameObject;

		[HideInInspector]
		public GameObject InstantiatedPrefab;
	}

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<EquipmentSkin> m_ActiveSkinChanged;

	[Tooltip("The Meshes that a new skin can be applied to. The order of meshes is important to keep as it will be used to map from EquipmentSkin.")]
	public List<MeshComponentMapping> MeshMappings;

	[Tooltip("The renderers that a new skin can be applied to. The order of renderers are important to keep as it will be used to map from EquipmentSkin.")]
	public List<RendererMapping> RenderersMappings;

	[Tooltip("The game objects that are exposed to the skin mapping for certain actions.")]
	public List<GameObjectMapping> GameObjectMappings;

	private TeamColorRenderer teamColorRenderer;

	private SynchronizedField<string> _defaultSkinOverrideGuid;

	private EquipmentSkin _defaultSkinOverride;

	private SynchronizedField<string> _synchronizedSkinGuid;

	[SerializeField]
	[HideInInspector]
	private EquipmentSkin _activeSkin;

	[HideInInspector]
	public string PrefabName;

	[NonSerialized]
	public bool SuppressSkins;

	[SerializeField]
	private bool automaticallyApplySkinChangesWhenAttached;

	public Tool ThisTool { get; private set; }

	private string DefaultSkinOverrideGuid
	{
		get
		{
			return _defaultSkinOverrideGuid.Get();
		}
		set
		{
			_defaultSkinOverrideGuid.Set(value);
		}
	}

	public bool HasDefaultSkinOverride => DefaultSkinOverride != null;

	public EquipmentSkin DefaultSkinOverride
	{
		get
		{
			return _defaultSkinOverride;
		}
		private set
		{
			if (!(value != _defaultSkinOverride))
			{
				return;
			}
			if (ActiveSkin == null)
			{
				if (_defaultSkinOverride != null)
				{
					RevertSkin(_defaultSkinOverride);
				}
				if (value != null)
				{
					ApplySkin(value);
				}
			}
			_defaultSkinOverride = value;
		}
	}

	public string ActiveSkinGuid
	{
		get
		{
			if (_synchronizedSkinGuid != null)
			{
				return _synchronizedSkinGuid.Get();
			}
			return (!(ActiveSkin != null)) ? string.Empty : ActiveSkin.Guid;
		}
		set
		{
			if (_synchronizedSkinGuid != null)
			{
				_synchronizedSkinGuid.Set(value);
			}
		}
	}

	public string OriginalSkinGuid { get; private set; }

	public bool HasActiveSkin => ActiveSkin != null;

	public EquipmentSkin ActiveSkin
	{
		get
		{
			return _activeSkin;
		}
		private set
		{
			if (value != _activeSkin)
			{
				if (_activeSkin != null)
				{
					RevertSkin(_activeSkin);
				}
				else if (DefaultSkinOverride != null)
				{
					RevertSkin(DefaultSkinOverride);
				}
				if (value != null)
				{
					ApplySkin(value);
				}
				else if (DefaultSkinOverride != null)
				{
					ApplySkin(DefaultSkinOverride);
				}
				_activeSkin = value;
				string text = ((!(_activeSkin != null)) ? string.Empty : _activeSkin.Guid);
				if (text != ActiveSkinGuid)
				{
					ActiveSkinGuid = text;
				}
				if (this.ActiveSkinChanged != null)
				{
					this.ActiveSkinChanged(_activeSkin);
				}
			}
		}
	}

	public event Action<EquipmentSkin> ActiveSkinChanged
	{
		add
		{
			Action<EquipmentSkin> action = this.m_ActiveSkinChanged;
			Action<EquipmentSkin> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ActiveSkinChanged, (Action<EquipmentSkin>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<EquipmentSkin> action = this.m_ActiveSkinChanged;
			Action<EquipmentSkin> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ActiveSkinChanged, (Action<EquipmentSkin>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (automaticallyApplySkinChangesWhenAttached && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.FavoriteEquipmentChanged += OnFavoriteEquipmentChanged;
		}
		ThisTool = GetComponent<Tool>();
		ThisTool.PostResetEvent += ThisTool_ResetEvent;
		ThisTool.PostPickupEvent += ThisTool_PostPickupEvent;
		teamColorRenderer = GetComponent<TeamColorRenderer>();
		_synchronizedSkinGuid = new SynchronizedField<string>(this, "TSG", string.Empty, SetterPermissionMode.MASTER_OR_AUTHORITY, OnSkinGuidChanged);
		_defaultSkinOverrideGuid = new SynchronizedField<string>(this, "DSO", string.Empty, SetterPermissionMode.MASTER_OR_AUTHORITY, OnDefaultSkinOverrideGuidChanged);
		foreach (MeshComponentMapping meshMapping in MeshMappings)
		{
			meshMapping.OriginalMesh = meshMapping.SharedMesh;
		}
		foreach (RendererMapping renderersMapping in RenderersMappings)
		{
			renderersMapping.OriginalMaterials = renderersMapping.renderer.sharedMaterials;
		}
		if (ThisTool != null && ThisTool.InstantiationParameters != null && ThisTool.InstantiationParameters.TryGetValue("ModificationGuid", out var value))
		{
			TryApplySkin((string)value);
		}
		if (_activeSkin != null)
		{
			OriginalSkinGuid = _activeSkin.Guid;
		}
		else
		{
			OriginalSkinGuid = string.Empty;
		}
	}

	private void Start()
	{
		OnSkinGuidChanged();
		OnDefaultSkinOverrideGuidChanged();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (automaticallyApplySkinChangesWhenAttached && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.FavoriteEquipmentChanged -= OnFavoriteEquipmentChanged;
		}
		ThisTool.PostResetEvent -= ThisTool_ResetEvent;
		ThisTool.PostPickupEvent -= ThisTool_PostPickupEvent;
	}

	private void OnFavoriteEquipmentChanged(PhotonPlayer photonPlayer, string changedPrefab)
	{
		if (ThisTool != null && ThisTool.IsHeld && !ThisTool.IsHeldByPlayer && ThisTool.HolderView.CreatedBy(photonPlayer) && changedPrefab == PrefabName)
		{
			LocalApplyFavoriteSkin();
		}
	}

	private void ThisTool_PostPickupEvent(Tool thisTool)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (ThisTool.PlayerSpawnedEquipment != null && (ThisTool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.Drawer || ThisTool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.GiftBox))
		{
			NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.ToggleFavoriteEquipment(this);
			if (ThisTool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.GiftBox)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					PhotonNetwork.Destroy(base.gameObject);
				});
			}
		}
		else if (!HasActiveSkin && !SuppressSkins)
		{
			LocalApplyFavoriteSkin(playNotifications: true);
		}
	}

	private void ThisTool_ResetEvent(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		if ((!(teamColorRenderer != null) || teamColorRenderer.TeamSetByOwner || !RecRoomSceneManager.HasRunningGame) && !(thisTool.PlayerSpawnedEquipment != null) && HasActiveSkin)
		{
			ActiveSkinGuid = string.Empty;
		}
	}

	private void OnSkinGuidChanged()
	{
		if (string.IsNullOrEmpty(ActiveSkinGuid))
		{
			ActiveSkin = null;
			return;
		}
		EquipmentSkin equipmentSkin = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.GetEquipmentSkin(ActiveSkinGuid);
		ActiveSkin = equipmentSkin;
	}

	private void OnDefaultSkinOverrideGuidChanged()
	{
		if (string.IsNullOrEmpty(DefaultSkinOverrideGuid))
		{
			DefaultSkinOverride = null;
			return;
		}
		EquipmentSkin equipmentSkin = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.GetEquipmentSkin(DefaultSkinOverrideGuid);
		DefaultSkinOverride = equipmentSkin;
	}

	public void SetDefaultSkinOverride(EquipmentSkin skinOverride)
	{
		if (base.hasAuthority || PhotonNetwork.player.IsMasterClient)
		{
			DefaultSkinOverrideGuid = skinOverride.Guid;
		}
	}

	public void LocalApplySkin(string skinGuid, bool playNotifications = false)
	{
		if (string.IsNullOrEmpty(skinGuid) || !(skinGuid != ActiveSkinGuid))
		{
			return;
		}
		ActiveSkinGuid = skinGuid;
		if (playNotifications)
		{
			if (ThisTool.HolderHand != null)
			{
				ThisTool.HolderHand.Vibrate(500);
			}
			AudioManager.Play3DSFX(SingletonMonoBehaviour<AudioManager>.Instance.ToolFavoriteSkinAudio, base.transform.position);
		}
	}

	public void LocalApplyFavoriteSkin(bool playNotifications = false)
	{
		PlayerSpawnedEquipment playerSpawnedEquipment = ThisTool.PlayerSpawnedEquipment;
		if ((!(playerSpawnedEquipment != null) || (playerSpawnedEquipment.IsMine && (playerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.None || playerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.Backpack))) && (ThisTool.isSceneView || ThisTool.isLocal))
		{
			string favoriteEquipmentSkin = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.GetFavoriteEquipmentSkin(this);
			LocalApplySkin(favoriteEquipmentSkin, playNotifications);
		}
	}

	private void ApplySkin(EquipmentSkin skin)
	{
		ApplyMeshMappings(skin);
		ApplyMaterialMappings(skin);
		ApplyGameObjectMappings(skin);
	}

	private void ApplyMeshMappings(EquipmentSkin skin)
	{
		if (skin.MeshMappings.Count == 0)
		{
			return;
		}
		if (skin.MeshMappings.Count != MeshMappings.Count)
		{
			UnityEngine.Debug.LogErrorFormat("Mismatching number of mesh mappings from skin ({0}) to tool ({1}). ToolMaps:{2}, SkinMaps:{3}", skin.name, ThisTool.name, MeshMappings.Count, skin.MeshMappings.Count);
		}
		for (int i = 0; i < MeshMappings.Count && i < skin.MeshMappings.Count; i++)
		{
			if (skin.MeshMappings[i].IsValid)
			{
				MeshMappings[i].SharedMesh = skin.MeshMappings[i].mesh;
			}
		}
	}

	private void ApplyMaterialMappings(EquipmentSkin skin)
	{
		if (skin.MaterialMappings.Count == 0)
		{
			return;
		}
		if (skin.MaterialMappings.Count != RenderersMappings.Count)
		{
			UnityEngine.Debug.LogErrorFormat("Mismatching number of renderer mappings from skin ({0}) to tool ({1}). ToolMaps:{2}, SkinMaps:{3}", skin.name, ThisTool.name, RenderersMappings.Count, skin.MaterialMappings.Count);
		}
		int num = Mathf.Min(RenderersMappings.Count, skin.MaterialMappings.Count);
		for (int i = 0; i < num; i++)
		{
			if (skin.MaterialMappings[i].IsValid)
			{
				RenderersMappings[i].renderer.sharedMaterials = skin.MaterialMappings[i].materials;
			}
		}
	}

	private void ApplyGameObjectMappings(EquipmentSkin skin)
	{
		int num = Mathf.Min(GameObjectMappings.Count, skin.GameObjectActionMappings.Count);
		for (int i = 0; i < num; i++)
		{
			if (GameObjectMappings[i].gameObject != null)
			{
				switch (skin.GameObjectActionMappings[i].action)
				{
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Enable:
					if (!GameObjectMappings[i].gameObject.activeSelf)
					{
						GameObjectMappings[i].gameObject.SetActive(value: true);
					}
					break;
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Disable:
					if (GameObjectMappings[i].gameObject.activeSelf)
					{
						GameObjectMappings[i].gameObject.SetActive(value: false);
					}
					break;
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Instantiate:
					if (skin.GameObjectActionMappings[i].prefabToInstantiate == null)
					{
						UnityEngine.Debug.LogErrorFormat("Tool '{0}' has a gameObject Action to instantiate prefab '{1}'. But the prefab is null.", base.gameObject.GetGameObjectHierarchy(), GameObjectMappings[i].name);
					}
					else
					{
						GameObject gameObject = UnityEngine.Object.Instantiate(skin.GameObjectActionMappings[i].prefabToInstantiate);
						gameObject.transform.SetParent(GameObjectMappings[i].gameObject.transform, worldPositionStays: false);
						GameObjectMappings[i].InstantiatedPrefab = gameObject;
					}
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Tool '{0}' has a gameObject mapping '{1}' with null reference.", base.gameObject.GetGameObjectHierarchy(), GameObjectMappings[i].name);
			}
		}
	}

	private void RevertSkin(EquipmentSkin skin)
	{
		RevertMeshMappings(skin);
		RevertMaterialMappings(skin);
		RevertGameObjectMappings(skin);
	}

	private void RevertMeshMappings(EquipmentSkin skin)
	{
		int num = Mathf.Min(MeshMappings.Count, skin.MeshMappings.Count);
		for (int i = 0; i < num; i++)
		{
			if (skin.MeshMappings[i].IsValid && MeshMappings[i].OriginalMesh != null)
			{
				MeshMappings[i].SharedMesh = MeshMappings[i].OriginalMesh;
			}
		}
	}

	private void RevertMaterialMappings(EquipmentSkin skin)
	{
		int num = Mathf.Min(RenderersMappings.Count, skin.MaterialMappings.Count);
		for (int i = 0; i < num; i++)
		{
			if (skin.MaterialMappings[i].IsValid && RenderersMappings[i].OriginalMaterials != null && RenderersMappings[i].OriginalMaterials.Length > 0)
			{
				RenderersMappings[i].renderer.sharedMaterials = RenderersMappings[i].OriginalMaterials;
			}
		}
	}

	private void RevertGameObjectMappings(EquipmentSkin skin)
	{
		int num = Mathf.Min(GameObjectMappings.Count, skin.GameObjectActionMappings.Count);
		for (int i = 0; i < num; i++)
		{
			if (GameObjectMappings[i].gameObject != null)
			{
				switch (skin.GameObjectActionMappings[i].action)
				{
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Enable:
					GameObjectMappings[i].gameObject.SetActive(value: false);
					break;
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Disable:
					GameObjectMappings[i].gameObject.SetActive(value: true);
					break;
				case EquipmentSkin.GameObjectActionMapping.GameObjectAction.Instantiate:
					if (UnityEngine.Application.isPlaying)
					{
						UnityEngine.Object.Destroy(GameObjectMappings[i].InstantiatedPrefab);
					}
					else
					{
						UnityEngine.Object.DestroyImmediate(GameObjectMappings[i].InstantiatedPrefab);
					}
					GameObjectMappings[i].InstantiatedPrefab = null;
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Tool '{0}' has a gameObject mapping '{1}' with null reference.", base.gameObject.GetGameObjectHierarchy(), GameObjectMappings[i].name);
			}
		}
	}

	private bool TryApplySkin(string modificationGuid)
	{
		EquipmentSkin equipmentSkin = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.GetEquipmentSkin(modificationGuid);
		ActiveSkinGuid = ((!(equipmentSkin != null)) ? string.Empty : equipmentSkin.Guid);
		return equipmentSkin != null;
	}

	void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
	{
		if (parameters.skinOverride != null)
		{
			ActiveSkin = parameters.skinOverride;
		}
	}
}
