namespace RecRoom.Core.Gestures
{
	public class CollisionGesture : HandGestureBase
	{
		private enum CollisionGestureState
		{
			Inactive,
			Colliding
		}

		[Header("General")]
		[SerializeField]
		private float collisionGestureDuration = 1f;

		[SerializeField]
		private float collisionGestureDistanceThreshold = 0.4f;

		[SerializeField]
		private float collisionGesturePullBackDistance = 0.01f;

		[SerializeField]
		private float collisionGestureStartTime;

		[Header("Fist Bump")]
		[SerializeField]
		private float minFistBumpSpeed = 0.7f;

		[SerializeField]
		private float fistbumpDotThreshold = -0.8f;

		[SerializeField]
		private float fistbumpDuration = 1f;

		[SerializeField]
		private float fistbumpDistanceThreshold = 0.4f;

		[SerializeField]
		private float fistbumpPullbackDistance = 0.01f;

		[Header("High Five")]
		[SerializeField]
		private float minHighFiveSpeed = 1f;

		[SerializeField]
		private float highFiveDuration = 1f;

		[SerializeField]
		private float highFiveDistanceThreshold = 0.5f;

		[SerializeField]
		private float highFivePullbackDistance = 0.01f;

		private Vector3 collisionGestureStartPosition;

		private Vector3 collisionGestureDirection;

		private PlayerHandGestures.Gesture currentCollisionGesture = PlayerHandGestures.Gesture.None;

		private NonPlayerGestureTarget nonPlayerTarget;

		private NonPlayerGestureTarget _visuallyConnectedTarget;

		private SynchronizedField<int> _otherHand;

		private PlayerHand _visuallyConnectedHand;

		private SynchronizedStateMachine stateMachine;

		private NonPlayerGestureTarget VisuallyConnectedTarget
		{
			get
			{
				return _visuallyConnectedTarget;
			}
			set
			{
				if (_visuallyConnectedTarget != value)
				{
					if (_visuallyConnectedTarget != null)
					{
						PlayerHand.BreakNonPlayerGesture(currentCollisionGesture, base.Hand, _visuallyConnectedTarget);
					}
					_visuallyConnectedTarget = value;
					if (_visuallyConnectedTarget != null)
					{
						PlayerHand.ConnectNonPlayerGesture(currentCollisionGesture, base.Hand, _visuallyConnectedTarget);
					}
				}
			}
		}

		private PlayerHand OtherHand
		{
			get
			{
				PhotonView photonView = PhotonView.Find(_otherHand.Get());
				return (!(photonView != null)) ? null : photonView.GetComponent<PlayerHand>();
			}
			set
			{
				_otherHand.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private PlayerHand VisuallyConnectedHand
		{
			get
			{
				return _visuallyConnectedHand;
			}
			set
			{
				if (_visuallyConnectedHand != value)
				{
					if (_visuallyConnectedHand != null)
					{
						PlayerHand.BreakCollisionGesture(currentCollisionGesture, base.Hand, _visuallyConnectedHand);
					}
					_visuallyConnectedHand = value;
					if (_visuallyConnectedHand != null)
					{
						PlayerHand.ConnectCollisionGesture(currentCollisionGesture, base.Hand, _visuallyConnectedHand);
					}
				}
			}
		}

		public override bool IsBlockingOtherGestures => CurrentState == CollisionGestureState.Colliding;

		private CollisionGestureState CurrentState
		{
			get
			{
				return (CollisionGestureState)stateMachine.CurrentStateId;
			}
			set
			{
				stateMachine.EnterState((ushort)value);
			}
		}

		private bool LocalHandReadyForGesture => !playerHandGestures.IsGestureBlocked(this) && currentCollisionGesture == PlayerHandGestures.Gesture.None;

		private bool FistBumpCanStartStart
		{
			get
			{
				Vector3 rhs = base.Hand.RigidbodyEx.velocity - ((!(OtherHand == null)) ? OtherHand.RigidbodyEx.velocity : Vector3.zero);
				float num = Vector3.Dot(base.Hand.FingerDirection, (!(OtherHand == null)) ? OtherHand.FingerDirection : nonPlayerTarget.FingerDirection);
				float num2 = Mathf.Abs(Vector3.Dot(base.Hand.FingerDirection, rhs));
				float num3 = Vector3.Dot(base.Hand.RigidbodyEx.velocity, base.Hand.FingerDirection);
				float num4 = ((!(OtherHand == null)) ? Vector3.Dot(OtherHand.RigidbodyEx.velocity, OtherHand.FingerDirection) : 10f);
				return num < fistbumpDotThreshold && num2 >= minFistBumpSpeed && num3 > 0.0001f && num4 > 0.0001f;
			}
		}

		private bool HighFiveCanStart
		{
			get
			{
				Vector3 rhs = base.Hand.RigidbodyEx.velocity - ((!(OtherHand == null)) ? OtherHand.RigidbodyEx.velocity : Vector3.zero);
				float num = Mathf.Abs(Vector3.Dot(base.Hand.PalmDirection, rhs));
				float num2 = Vector3.Dot(base.Hand.RigidbodyEx.velocity, base.Hand.PalmDirection);
				float num3 = ((!(OtherHand == null)) ? Vector3.Dot(OtherHand.RigidbodyEx.velocity, OtherHand.PalmDirection) : 10f);
				return num >= minHighFiveSpeed && num2 > 0.0001f && num3 > 0.0001f;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_otherHand = new SynchronizedField<int>(this, "COLL_HID", -1, SetterPermissionMode.AUTHORITY);
			stateMachine = new SynchronizedStateMachine("COLL_S", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterCollidingState, OnExitCollidingState, OnUpdateCollidingState);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
			base.enabled = base.hasAuthority;
		}

		private void Update()
		{
			stateMachine.Update();
		}

		public override void ProcessHandCollision(PlayerHand otherHand)
		{
			base.ProcessHandCollision(otherHand);
			if (base.hasAuthority && LocalHandReadyForGesture)
			{
				OtherHand = otherHand;
				bool flag = base.Hand.OpenClosedAxis <= 0.01f && otherHand.OpenClosedAxis <= 0.01f;
				if (base.Hand.OpenClosedAxis >= 0.99f && otherHand.OpenClosedAxis >= 0.99f && FistBumpCanStartStart)
				{
					StartCollisionGesture(PlayerHandGestures.Gesture.Fistbump);
				}
				else if (flag && HighFiveCanStart)
				{
					StartCollisionGesture(PlayerHandGestures.Gesture.Highfive);
				}
			}
		}

		public override void ProcessNonPlayerHandCollision(NonPlayerGestureTarget target)
		{
			base.ProcessNonPlayerHandCollision(target);
			if (base.hasAuthority && LocalHandReadyForGesture)
			{
				nonPlayerTarget = target;
				bool flag = base.Hand.OpenClosedAxis <= 0.01f;
				if (base.Hand.OpenClosedAxis >= 0.99f && target.SupportedGesture == PlayerHandGestures.Gesture.Fistbump && FistBumpCanStartStart)
				{
					StartCollisionGesture(PlayerHandGestures.Gesture.Fistbump);
				}
				else if (flag && target.SupportedGesture == PlayerHandGestures.Gesture.Highfive && HighFiveCanStart)
				{
					StartCollisionGesture(PlayerHandGestures.Gesture.Highfive);
				}
			}
		}

		private void StartCollisionGesture(PlayerHandGestures.Gesture gestureType)
		{
			currentCollisionGesture = gestureType;
			stateMachine.EnterState(1);
		}

		private void OnEnterCollidingState(ushort otherStateId, ushort otherSubstateId)
		{
			VisuallyConnectedHand = OtherHand;
			VisuallyConnectedTarget = nonPlayerTarget;
			if (base.hasAuthority)
			{
				collisionGestureStartTime = UnityEngine.Time.time;
				collisionGestureStartPosition = base.Hand.transform.position;
				if (currentCollisionGesture == PlayerHandGestures.Gesture.Fistbump)
				{
					collisionGestureDirection = base.Hand.FingerDirection;
					collisionGestureDuration = fistbumpDuration;
					collisionGestureDistanceThreshold = fistbumpDistanceThreshold;
					collisionGesturePullBackDistance = fistbumpPullbackDistance;
				}
				else
				{
					collisionGestureDirection = base.Hand.PalmDirection;
					collisionGestureDuration = highFiveDuration;
					collisionGestureDistanceThreshold = highFiveDistanceThreshold;
					collisionGesturePullBackDistance = highFivePullbackDistance;
				}
				if (OtherHand != null)
				{
					playerHandGestures.AuthorityTriggerGesture(currentCollisionGesture, OtherHand);
				}
				else if (nonPlayerTarget != null)
				{
					playerHandGestures.AuthorityTriggerGesture(currentCollisionGesture, null);
				}
			}
		}

		private void OnUpdateCollidingState()
		{
			if (base.hasAuthority && (playerHandGestures.IsGestureBlocked(this) || UnityEngine.Time.time - collisionGestureStartTime > collisionGestureDuration || !HandNearCollisionGestureOrigin() || !HandInCorrectStateForCollisionGesture()))
			{
				CurrentState = CollisionGestureState.Inactive;
			}
		}

		private void OnExitCollidingState(ushort otherStateId, ushort otherSubstateId)
		{
			VisuallyConnectedHand = null;
			VisuallyConnectedTarget = null;
			if (base.hasAuthority)
			{
				OtherHand = null;
				nonPlayerTarget = null;
				currentCollisionGesture = PlayerHandGestures.Gesture.None;
			}
		}

		private bool HandNearCollisionGestureOrigin()
		{
			bool flag = (base.Hand.transform.position - collisionGestureStartPosition).sqrMagnitude <= collisionGestureDistanceThreshold * collisionGestureDistanceThreshold;
			bool flag2 = Vector3.Dot(base.Hand.transform.position - collisionGestureStartPosition, -collisionGestureDirection) <= collisionGesturePullBackDistance;
			return flag && flag2;
		}

		private bool HandInCorrectStateForCollisionGesture()
		{
			bool result = false;
			switch (currentCollisionGesture)
			{
			case PlayerHandGestures.Gesture.Fistbump:
				result = base.Hand.OpenClosedAxis >= 0.99f;
				break;
			case PlayerHandGestures.Gesture.Highfive:
				result = base.Hand.OpenClosedAxis <= 0.01f;
				break;
			}
			return result;
		}
	}
	public class GameReviveHandshakeGesture : HandGestureBase
	{
		private enum State
		{
			NOT_RUNNING,
			READY,
			RUNNING,
			SUCCESS
		}

		private const float POST_COLLISION_GRIP_START_DELAY = 1f;

		private const float MAX_DISTANCE_TO_HELD_HAND = 1f;

		private const float MAX_DISTANCE_TO_HELD_HAND_SQR = 1f;

		public static bool StaticIsEnabled;

		public static float StaticRunDuration = 5f;

		private PlayerHand _heldByHand;

		private SynchronizedField<int> _heldHandId;

		private PlayerHand _cachedHeldHand;

		private SynchronizedStateMachine stateMachine;

		private Timer localTimer = new Timer();

		public PlayerHand HeldByHand
		{
			get
			{
				return _heldByHand;
			}
			private set
			{
				_heldByHand = value;
				if (_heldByHand != null && base.hasAuthority)
				{
					playerHandGestures.AuthorityCancelOtherGestures(this);
				}
			}
		}

		private PlayerHand HeldHand
		{
			get
			{
				return _cachedHeldHand;
			}
			set
			{
				_heldHandId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private bool LocalHandIsGrippedForHandshake => base.Hand != null && base.Hand.OpenClosedAxis > 0.01f;

		public override bool IsBlockingOtherGestures
		{
			get
			{
				if (!StaticIsEnabled)
				{
					return false;
				}
				if (HeldByHand != null)
				{
					return true;
				}
				State currentStateId = (State)stateMachine.CurrentStateId;
				return currentStateId != State.NOT_RUNNING;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_heldHandId = new SynchronizedField<int>(this, "GAMREVHELDHAND", -1, SetterPermissionMode.AUTHORITY, OnHeldHandChange);
			stateMachine = new SynchronizedStateMachine("GAMREVHANDGES", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, null, null, null);
			stateMachine.AddState(1, OnEnterReadyState, OnExitReadyState, OnUpdateReadyState);
			stateMachine.AddState(2, OnEnterRunningState, OnExitRunningState, OnUpdateRunningState);
			stateMachine.AddState(3, null, null, OnUpdateSuccessState);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
			OnHeldHandChange();
		}

		private void Update()
		{
			stateMachine.Update();
			localTimer.UpdateCallbacks();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (HeldHand != null && HeldHand.isLocal)
			{
				GameReviveHandshakeGesture component = HeldHand.GetComponent<GameReviveHandshakeGesture>();
				component.HeldByHand = null;
			}
		}

		public override void ProcessHandCollision(PlayerHand otherHand)
		{
			if (base.hasAuthority && IsAbleToGrab(otherHand))
			{
				HeldHand = otherHand;
				stateMachine.EnterState(1);
			}
		}

		public override void Cancel()
		{
			base.Cancel();
			stateMachine.EnterState(0);
		}

		private void OnEnterReadyState(ushort previousStateId, ushort previousSubStateId)
		{
			if (base.hasAuthority)
			{
				playerHandGestures.AuthorityCancelOtherGestures(this);
			}
			localTimer.StartTimer(1f);
		}

		private void OnUpdateReadyState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (!StaticIsEnabled)
			{
				stateMachine.EnterState(0);
				return;
			}
			if (HeldHand == null)
			{
				stateMachine.EnterState(0);
				return;
			}
			float sqrMagnitude = (HeldHand.transform.position - base.transform.position).sqrMagnitude;
			if (sqrMagnitude >= 1f)
			{
				stateMachine.EnterState(0);
			}
			else if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.IsValidPlayerRevive(HeldHand.owner, base.owner))
			{
				stateMachine.EnterState(0);
			}
			else if (LocalHandIsGrippedForHandshake)
			{
				stateMachine.EnterState(2);
			}
			else if (localTimer.TimerOver)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnExitReadyState(ushort nextStateId, ushort nextSubStateId)
		{
			if (base.hasAuthority && nextStateId == 0)
			{
				HeldHand = null;
			}
		}

		private void OnEnterRunningState(ushort previousStateId, ushort previousSubStateId)
		{
			localTimer.StartTimer(StaticRunDuration);
			if (base.hasAuthority)
			{
				playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.GameReviveHandshakeStart, HeldHand, pauseOthers: false);
			}
		}

		private void OnUpdateRunningState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (!StaticIsEnabled)
			{
				stateMachine.EnterState(0);
				return;
			}
			if (HeldHand == null)
			{
				stateMachine.EnterState(0);
				return;
			}
			if (!LocalHandIsGrippedForHandshake)
			{
				stateMachine.EnterState(0);
				return;
			}
			float sqrMagnitude = (HeldHand.transform.position - base.transform.position).sqrMagnitude;
			if (sqrMagnitude >= 1f)
			{
				stateMachine.EnterState(0);
			}
			else if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.IsValidPlayerRevive(HeldHand.owner, base.owner))
			{
				stateMachine.EnterState(0);
			}
			else if (localTimer.TimerOver)
			{
				stateMachine.EnterState(3);
			}
		}

		private void OnExitRunningState(ushort nextStateId, ushort nextSubStateId)
		{
			if (base.hasAuthority)
			{
				if (nextStateId == 3)
				{
					playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.GameReviveHandshakeSuccess, HeldHand, pauseOthers: false);
				}
				else
				{
					playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.GameReviveHandshakeCancel, HeldHand, pauseOthers: false);
				}
				HeldHand = null;
			}
		}

		private void OnUpdateSuccessState()
		{
			if (base.hasAuthority)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnHeldHandChange()
		{
			PlayerHand heldHand = HeldHand;
			if (heldHand != null && heldHand.isLocal)
			{
				GameReviveHandshakeGesture component = heldHand.GetComponent<GameReviveHandshakeGesture>();
				component.HeldByHand = null;
			}
			PhotonView photonView = PhotonView.Find(_heldHandId.Get());
			_cachedHeldHand = ((!(photonView != null)) ? null : photonView.GetComponent<PlayerHand>());
			PlayerHand heldHand2 = HeldHand;
			if (heldHand2 != null && heldHand2.isLocal)
			{
				GameReviveHandshakeGesture component2 = heldHand2.GetComponent<GameReviveHandshakeGesture>();
				component2.HeldByHand = base.Hand;
			}
		}

		private bool IsAbleToGrab(PlayerHand otherPlayerHand)
		{
			if (!StaticIsEnabled)
			{
				return false;
			}
			if (stateMachine.CurrentStateId != 0)
			{
				return false;
			}
			if (otherPlayerHand == null)
			{
				return false;
			}
			if (otherPlayerHand.owner == base.owner)
			{
				return false;
			}
			if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.IsValidPlayerRevive(otherPlayerHand.owner, base.owner))
			{
				return false;
			}
			if (!IsHandValidTarget(otherPlayerHand))
			{
				return false;
			}
			PlayerHand otherHand = otherPlayerHand.ThisPlayer.GetOtherHand(otherPlayerHand.Type);
			if (otherHand != null && !IsHandValidTarget(otherHand))
			{
				return false;
			}
			return true;
		}

		private bool IsHandValidTarget(PlayerHand hand)
		{
			GameReviveHandshakeGesture component = hand.GetComponent<GameReviveHandshakeGesture>();
			if (component == null)
			{
				return false;
			}
			if (component.HeldByHand != null)
			{
				return false;
			}
			return true;
		}
	}
	public abstract class HandGestureBase : Photon.MonoBehaviour
	{
