		{
		}

		public virtual void ProcessNonPlayerHandCollision(NonPlayerGestureTarget target)
		{
		}

		public virtual void Cancel()
		{
		}
	}
	public class HandshakeGesture : HandGestureBase
	{
		public enum HandshakeState
		{
			Inactive,
			Ready_Open,
			Ready_Gripped,
			Running,
			Finished,
			Broken
