		[SerializeField]
		private float cooldown = 1f;

		[SerializeField]
		private float handOpenBufferDuration = 0.2f;

		[SerializeField]
		private float palmsTogetherDotThreshold = -0.6f;

		[SerializeField]
		private float fingerDotThreshold = -0.1f;

		[SerializeField]
		private float maxStartDistance = 0.36f;

		[SerializeField]
		private float requiredHoldDuration = 2f;

		[SerializeField]
		private float maxHoldDriftDistance = 0.26f;

		private float handshakeStartTime;

		private float handshakeBreakTime;

		private Vector3 handshakeStartPosition = Vector3.zero;

		private SynchronizedStateMachine handshakeStateMachine;

		private float lastHandOpenTime;

		private NonPlayerGestureTarget nonPlayerTarget;

		private NonPlayerGestureTarget _visuallyConnectedTarget;

		private SynchronizedField<int> _otherHand;

		private PlayerHand _visuallyConnectedHand;

		public override bool IsBlockingOtherGestures => CurrentState == HandshakeState.Ready_Gripped || CurrentState == HandshakeState.Running || CurrentState == HandshakeState.Finished;

		public override bool IgnoreGestureCooldown => true;

		private HandshakeState CurrentState => (HandshakeState)handshakeStateMachine.CurrentStateId;

		private NonPlayerGestureTarget VisuallyConnectedTarget
		{
			get
			{
				return _visuallyConnectedTarget;
			}
			set
			{
				if (_visuallyConnectedTarget != value)
				{
					if (_visuallyConnectedTarget != null)
					{
						PlayerHand.BreakNonPlayerGesture((CurrentState != HandshakeState.Broken) ? PlayerHandGestures.Gesture.HandshakeSuccess : PlayerHandGestures.Gesture.HandshakeCancel, base.Hand, _visuallyConnectedTarget);
					}
					_visuallyConnectedTarget = value;
					if (_visuallyConnectedTarget != null)
					{
						PlayerHand.ConnectNonPlayerGesture(PlayerHandGestures.Gesture.HandshakeStart, base.Hand, _visuallyConnectedTarget);
					}
				}
			}
		}

		private PlayerHand OtherHand
		{
			get
			{
				PhotonView photonView = PhotonView.Find(_otherHand.Get());
				return (!(photonView != null)) ? null : photonView.GetComponent<PlayerHand>();
			}
			set
			{
				_otherHand.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		private HandshakeGesture OtherHandshake
		{
			get
			{
				PlayerHand otherHand = OtherHand;
				if (otherHand != null)
