					return otherHand.Gestures.GetComponent<HandshakeGesture>();
				}
				return null;
			}
		}

		private PlayerHand VisuallyConnectedHand
		{
			get
			{
				return _visuallyConnectedHand;
			}
			set
			{
				if (_visuallyConnectedHand != value)
				{
					if (_visuallyConnectedHand != null)
					{
						PlayerHand.BreakHandshake(base.Hand, _visuallyConnectedHand);
					}
					_visuallyConnectedHand = value;
					if (_visuallyConnectedHand != null)
					{
						PlayerHand.ConnectHandshake(base.Hand, _visuallyConnectedHand);
					}
				}
			}
		}

		private HandshakeState OtherHandshakeState => (!(OtherHandshake == null)) ? OtherHandshake.CurrentState : nonPlayerTarget.CurrentHandshakeState;

		private Player OtherPlayer => (!(OtherHand != null)) ? null : OtherHand.ThisPlayer;

		private bool LocalHandReadyToStartHandshake => handshakeStateMachine.CurrentStateId == 0 && UnityEngine.Time.time <= lastHandOpenTime + handOpenBufferDuration;

		private bool HandsInCorrectState
		{
			get
			{
				if (OtherHand == null && nonPlayerTarget == null)
				{
					return false;
				}
				if (OtherPlayer.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN && OtherPlayer.PlayerParty.IsWaitingToMakeFriend)
				{
					return true;
				}
				float num = Vector3.Dot(base.Hand.FingerDirection, (!(OtherHand == null)) ? OtherHand.FingerDirection : nonPlayerTarget.FingerDirection);
				return num < fingerDotThreshold && base.Hand.Type == ((!(OtherHand == null)) ? OtherHand.Type : nonPlayerTarget.HandType) && (OtherHandshakeState == HandshakeState.Inactive || OtherHandshakeState == HandshakeState.Ready_Open || OtherHandshakeState == HandshakeState.Ready_Gripped);
			}
