		private bool HandsAreWithinHandshakeRange
		{
			get
			{
				if (OtherHand == null && nonPlayerTarget == null)
				{
					return false;
				}
				if (OtherPlayer.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN && OtherPlayer.PlayerParty.IsWaitingToMakeFriend)
				{
					return true;
				}
				float num = Vector3.Dot(base.Hand.PalmDirection, (!(OtherHand == null)) ? OtherHand.PalmDirection : nonPlayerTarget.PalmDirection);
				float num2 = Vector3.Dot(base.Hand.FingerDirection, (!(OtherHand == null)) ? OtherHand.FingerDirection : nonPlayerTarget.FingerDirection);
				float sqrMagnitude = (base.Hand.transform.position - ((!(OtherHand == null)) ? OtherHand.transform.position : nonPlayerTarget.transform.position)).sqrMagnitude;
				return sqrMagnitude <= maxStartDistance * maxStartDistance && num2 < fingerDotThreshold && num < palmsTogetherDotThreshold;
			}
