		private bool LocalHandIsGrippedForHandshake => base.Hand != null && base.Hand.OpenClosedAxis > 0.01f;

		private bool LocalHandshakeIsBroken => !LocalHandIsGrippedForHandshake || (base.Hand.transform.position - handshakeStartPosition).sqrMagnitude > maxHoldDriftDistance * maxHoldDriftDistance;

		private bool RemoteHandReadyForHandshake
		{
			get
			{
				Player otherPlayer = OtherPlayer;
				if (otherPlayer.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN)
				{
					return otherPlayer.PlayerParty.IsWaitingToMakeFriend;
				}
				return (OtherHand != null || nonPlayerTarget != null) && (OtherHandshakeState == HandshakeState.Ready_Gripped || OtherHandshakeState == HandshakeState.Running);
			}
		}

		private bool RemoteHandshakeIsBroken
		{
			get
			{
				Player otherPlayer = OtherPlayer;
				if (otherPlayer.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN)
				{
					return !otherPlayer.PlayerParty.IsWaitingToMakeFriend;
				}
				return (OtherHand == null && nonPlayerTarget == null) || OtherHandshakeState == HandshakeState.Broken;
			}
		}

		private bool RemoteHandFinishedHandshake => (OtherHand != null || nonPlayerTarget != null) && (OtherHandshakeState == HandshakeState.Finished || OtherHandshakeState == HandshakeState.Inactive);

		protected override void Awake()
		{
			base.Awake();
			_otherHand = new SynchronizedField<int>(this, "SHAKE_HID", -1, SetterPermissionMode.AUTHORITY);
			handshakeStateMachine = new SynchronizedStateMachine("SHAKE_S", SetterPermissionMode.AUTHORITY);
			handshakeStateMachine.AddState(0, OnEnterInactiveState, null, null);
			handshakeStateMachine.AddState(1, null, null, OnUpdateReadyOpenState);
			handshakeStateMachine.AddState(2, null, null, OnUpdateReadyGrippedState);
			handshakeStateMachine.AddState(3, OnEnterRunningState, null, OnUpdateRunningState);
			handshakeStateMachine.AddState(4, null, null, OnUpdateFinishedState);
			handshakeStateMachine.AddState(5, OnEnterBrokenState, null, OnUpdateBrokenState);
			handshakeStateMachine.StateChangeEvent += HandleStateChangeEvent;
		}

		private void Start()
		{
			handshakeStateMachine.Start(this, 0);
			base.enabled = base.hasAuthority;
		}

		private void Update()
		{
			handshakeStateMachine.Update();
			if (base.hasAuthority && base.Hand.OpenClosedAxis <= 0.01f)
			{
				lastHandOpenTime = UnityEngine.Time.time;
			}
		}

		public override void ProcessHandCollision(PlayerHand otherHand)
		{
			base.ProcessHandCollision(otherHand);
			if (base.hasAuthority && otherHand != null && LocalHandReadyToStartHandshake)
			{
				OtherHand = otherHand;
				if (HandsInCorrectState)
				{
					handshakeStateMachine.EnterState(1);
				}
			}
		}

		public override void ProcessNonPlayerHandCollision(NonPlayerGestureTarget target)
		{
			base.ProcessNonPlayerHandCollision(target);
			if (base.hasAuthority && target.SupportedGesture == PlayerHandGestures.Gesture.HandshakeStart && LocalHandReadyToStartHandshake)
			{
				nonPlayerTarget = target;
				if (HandsInCorrectState)
				{
					handshakeStateMachine.EnterState(1);
				}
			}
		}

		public override void Cancel()
		{
			base.Cancel();
			if (base.hasAuthority)
			{
				handshakeStateMachine.EnterState(5);
			}
		}

		private void HandleStateChangeEvent(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (currentStateId == 3 || currentStateId == 4)
			{
				VisuallyConnectedHand = OtherHand;
				VisuallyConnectedTarget = nonPlayerTarget;
			}
			else
			{
				VisuallyConnectedHand = null;
				VisuallyConnectedTarget = null;
			}
			if (nonPlayerTarget != null)
			{
				nonPlayerTarget.UpdateHandshakeState(CurrentState);
			}
		}

		private void OnEnterInactiveState(ushort otherStateId, ushort otherSubStateId)
		{
			if (base.hasAuthority)
			{
				OtherHand = null;
				if (nonPlayerTarget != null)
				{
					nonPlayerTarget.UpdateHandshakeState(HandshakeState.Inactive);
					nonPlayerTarget = null;
				}
			}
		}

		private void OnUpdateReadyOpenState()
		{
			if (base.hasAuthority)
			{
				if (!HandsAreWithinHandshakeRange)
				{
					handshakeStateMachine.EnterState(0);
				}
				else if (LocalHandIsGrippedForHandshake)
				{
					handshakeStateMachine.EnterState(2);
				}
			}
		}

		private void OnUpdateReadyGrippedState()
		{
			if (base.hasAuthority)
			{
				if (!HandsAreWithinHandshakeRange)
				{
					handshakeStateMachine.EnterState(0);
				}
				else if (!LocalHandIsGrippedForHandshake)
				{
					handshakeStateMachine.EnterState(1);
				}
				else if (RemoteHandReadyForHandshake)
				{
					handshakeStateMachine.EnterState(3);
				}
			}
		}

		private void OnEnterRunningState(ushort otherStateId, ushort otherSubStateId)
		{
			if (base.hasAuthority)
			{
				handshakeStartTime = UnityEngine.Time.time;
				handshakeStartPosition = base.Hand.transform.position;
				if (OtherHand != null || nonPlayerTarget != null)
				{
					playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeStart, OtherHand, pauseOthers: false);
				}
			}
		}

		private void OnUpdateRunningState()
		{
			if (base.hasAuthority)
			{
				if (RemoteHandFinishedHandshake || UnityEngine.Time.time - handshakeStartTime >= requiredHoldDuration)
				{
					handshakeStateMachine.EnterState(4);
				}
				else if (RemoteHandshakeIsBroken || LocalHandshakeIsBroken)
				{
					handshakeStateMachine.EnterState(5);
				}
			}
		}

		private void OnUpdateFinishedState()
		{
			if (base.hasAuthority)
			{
				if (RemoteHandshakeIsBroken)
				{
					handshakeStateMachine.EnterState(5);
				}
				else if (RemoteHandFinishedHandshake || (OtherPlayer != null && OtherPlayer.ControllerDisplayMode == LocalPlayerController.DisplayMode.SCREEN))
				{
					playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeSuccess, OtherHand);
					handshakeStateMachine.EnterState(0);
				}
			}
		}

		private void OnEnterBrokenState(ushort otherStateId, ushort otherSubStateId)
		{
			if (base.hasAuthority)
			{
				handshakeBreakTime = UnityEngine.Time.time;
				if (OtherHand != null || nonPlayerTarget != null)
				{
					playerHandGestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeCancel, OtherHand, pauseOthers: false);
				}
			}
		}

		private void OnUpdateBrokenState()
		{
			if (base.hasAuthority && UnityEngine.Time.time - handshakeBreakTime >= cooldown)
			{
				handshakeStateMachine.EnterState(0);
			}
		}
	}
