		}

		private IEnumerator RunResetPositionAndRotation()
		{
			Vector3 handStartPos = base.transform.position;
			Quaternion handStartRot = base.transform.rotation;
			Vector3 armStartPos = connectedArm.position;
			Quaternion armStartRot = connectedArm.rotation;
			float step = 0f;
			while (step < 1f)
			{
				base.transform.position = Vector3.Lerp(handStartPos, originalHandPosition, step);
				base.transform.rotation = Quaternion.Lerp(handStartRot, originalHandRotation, step);
				connectedArm.position = Vector3.Lerp(armStartPos, originalArmPosition, step);
				connectedArm.rotation = Quaternion.Lerp(armStartRot, originalArmRotation, step);
				step += 0.1f;
				yield return null;
			}
		}
