			gestures = GetComponents<HandGestureBase>();
			previousCollisionTestPosition = Hand.PhysicalPickupOrigin;
			base.enabled = base.hasAuthority;
		}

		private void OnEnable()
		{
			previousCollisionTestPosition = Hand.PhysicalPickupOrigin;
		}

		private void Update()
		{
			if (base.hasAuthority)
			{
				UpdateCollisionTest();
			}
		}

		public void AuthorityCancelOtherGestures(HandGestureBase allowedGesture)
		{
			if (!base.hasAuthority)
			{
				return;
			}
			for (int i = 0; i < gestures.Length; i++)
			{
				if (gestures[i] != allowedGesture)
				{
					gestures[i].Cancel();
				}
			}
		}

		public bool IsGestureBlocked(HandGestureBase gesture)
		{
			for (int i = 0; i < gestures.Length; i++)
			{
				if (gestures[i] != gesture && gestures[i].IsBlockingOtherGestures)
				{
					return true;
				}
			}
			return false;
		}

		private void UpdateCollisionTest()
		{
			PlayerHand collidingHand = null;
			NonPlayerGestureTarget nonPlayerTarget = null;
			if (!Hand.DefaultHandVisualsActive || Hand.ThisPlayer.DisplayAsIgnored)
			{
				collidingHand = null;
				nonPlayerTarget = null;
				return;
			}
			if (!TestCollisionOverlap(out collidingHand, out nonPlayerTarget))
			{
				TestCollisionSpherecast(out collidingHand, out nonPlayerTarget);
			}
			if (currentCollidingHand != collidingHand)
			{
				if (this.HandCollisionChanged != null)
				{
					this.HandCollisionChanged(Hand, collidingHand);
				}
				currentCollidingHand = collidingHand;
			}
			if (collidingHand != null)
			{
				ProcessHandCollision(collidingHand);
			}
			else if (nonPlayerTarget != null)
			{
				ProcessNonPlayerHandCollision(nonPlayerTarget);
			}
			previousCollisionTestPosition = Hand.PhysicalPickupOrigin;
		}

		private bool TestCollisionOverlap(out PlayerHand collidingHand, out NonPlayerGestureTarget nonPlayerTarget)
		{
			collidingHand = null;
			nonPlayerTarget = null;
			if (Hand.HeldTool == null)
			{
				int num = Physics.OverlapSphereNonAlloc(Hand.PhysicalPickupOrigin, handCollisionRadius, collisionTestOverlapHits, 1052672);
				for (int i = 0; i < num; i++)
				{
					PlayerHand colliderPlayerHand = collisionTestOverlapHits[i].GetColliderPlayerHand();
					if (colliderPlayerHand != null)
					{
						if (!colliderPlayerHand.ThisPlayer.isLocal && colliderPlayerHand.HeldTool == null)
						{
							collidingHand = colliderPlayerHand;
							return true;
						}
					}
					else
					{
						nonPlayerTarget = collisionTestOverlapHits[i].GetComponent<NonPlayerGestureTarget>();
						if (nonPlayerTarget != null)
						{
							return true;
						}
					}
				}
			}
			return false;
		}

		private bool TestCollisionSpherecast(out PlayerHand collidingHand, out NonPlayerGestureTarget nonPlayerTarget)
		{
			collidingHand = null;
			nonPlayerTarget = null;
			if (Hand.HeldTool == null)
			{
				Vector3 vector = Hand.PhysicalPickupOrigin - previousCollisionTestPosition;
				float magnitude = vector.magnitude;
				if (magnitude > 0f)
				{
					Vector3 direction = vector / magnitude;
					int num = Physics.SphereCastNonAlloc(previousCollisionTestPosition, handCollisionRadius, direction, collisionTestRaycastHits, magnitude);
					for (int i = 0; i < num; i++)
					{
						PlayerHand colliderPlayerHand = collisionTestRaycastHits[i].collider.GetColliderPlayerHand();
						if (colliderPlayerHand != null)
						{
							if (!colliderPlayerHand.ThisPlayer.isLocal && colliderPlayerHand.HeldTool == null)
							{
								collidingHand = colliderPlayerHand;
								return true;
							}
						}
						else
						{
							nonPlayerTarget = collisionTestRaycastHits[i].collider.GetComponent<NonPlayerGestureTarget>();
							if (nonPlayerTarget != null)
							{
								return true;
							}
						}
					}
				}
			}
			return false;
		}

		private void ProcessHandCollision(PlayerHand otherHand)
		{
			if (!Hand.DefaultHandVisualsActive || !otherHand.DefaultHandVisualsActive || Hand.ThisPlayer.DisplayAsIgnored || otherHand.ThisPlayer.DisplayAsIgnored)
			{
				return;
			}
			bool flag = UnityEngine.Time.time < lastGestureTime + gestureCooldown;
			for (int i = 0; i < gestures.Length; i++)
			{
				if (!flag || gestures[i].IgnoreGestureCooldown)
				{
					gestures[i].ProcessHandCollision(otherHand);
				}
			}
		}

		private void ProcessNonPlayerHandCollision(NonPlayerGestureTarget nonPlayerTarget)
		{
			if (!Hand.DefaultHandVisualsActive || Hand.ThisPlayer.DisplayAsIgnored)
			{
				return;
			}
			bool flag = UnityEngine.Time.time < lastGestureTime + gestureCooldown;
			for (int i = 0; i < gestures.Length; i++)
			{
				if (!flag || gestures[i].IgnoreGestureCooldown)
				{
					gestures[i].ProcessNonPlayerHandCollision(nonPlayerTarget);
				}
			}
		}

		public void AuthorityTriggerGesture(Gesture gesture, PlayerHand otherHand, bool pauseOthers = true)
		{
			if (isLocal)
			{
				base.photonView.RpcAll(RpcHandGestureDetected, otherHand, gesture, PhotonNetwork.ServerTimestamp, pauseOthers);
			}
		}

		[PunRPC]
		private void RpcHandGestureDetected(PlayerHand otherHand, Gesture gesture, int serverTimeMiliseconds, bool pauseOthers)
		{
			if (otherHand != null && otherHand.isLocal)
			{
				otherHand.Gestures.HandleLocalHandGestureDetected(Hand, gesture, serverTimeMiliseconds, Hand.ThisPlayer, pauseOthers);
			}
			else
			{
				HandleLocalHandGestureDetected(otherHand, gesture, serverTimeMiliseconds, (!(otherHand == null)) ? otherHand.ThisPlayer : null, pauseOthers);
			}
		}

		public void HandleLocalHandGestureDetected(PlayerHand otherHand, Gesture gesture, int serverTimeMiliseconds, Player otherPlayer, bool pauseOthers)
		{
			if (!(otherHand != null) || ((otherHand.Gestures.LastGestureServerTimestamp == 0 || otherHand.Gestures.LastGestureType != gesture || Math.Abs(otherHand.Gestures.LastGestureServerTimestamp - serverTimeMiliseconds) >= 600) && (LastGestureServerTimestamp == 0 || LastGestureType != gesture || Math.Abs(LastGestureServerTimestamp - serverTimeMiliseconds) >= 600)))
			{
				if (pauseOthers)
				{
					lastGestureTime = UnityEngine.Time.time;
				}
				LastGestureServerTimestamp = serverTimeMiliseconds;
				LastGestureType = gesture;
				if (this.GestureDetected != null)
				{
					this.GestureDetected(Hand, otherHand, gesture, Hand.ThisPlayer, otherPlayer);
				}
				if (this.GestureDetectedCalledOnBothHands != null)
				{
					this.GestureDetectedCalledOnBothHands(Hand, otherHand, gesture, Hand.ThisPlayer, otherPlayer);
				}
				if (otherHand != null && otherHand.Gestures.GestureDetectedCalledOnBothHands != null)
				{
					otherHand.Gestures.GestureDetectedCalledOnBothHands(otherHand, Hand, gesture, otherPlayer, Hand.ThisPlayer);
				}
				if (otherPlayer != null)
				{
					ChallengeEvents.ChallengeEventData challengeEventData = new ChallengeEvents.ChallengeEventData(ChallengeEvents.ChallengeEventTypes.Gesture);
					challengeEventData.AddDefendingPlayer(otherPlayer.PhotonPlayer);
					challengeEventData.SetVar("hg", (int)gesture);
					ChallengeEvents.Event(challengeEventData);
				}
			}
		}
	}
	public class ShakeGesture : HandGestureBase
	{
		private enum ShakeState
		{
			Inactive,
			Tracking
		}

		[SerializeField]
		private float minShakeStartSpeed = 1f;

		[SerializeField]
		private float shakeTravelDistance = 0.1f;

		[SerializeField]
		private float shakeTime = 0.7f;

		[SerializeField]
		private float shakeMaxDisplacement = 0.25f;

		private ManualUpdateStateMachine stateMachine;

		private float shakeStartTime;

		private float distanceTraveled;

		private Vector3 shakeStartPosition = Vector3.zero;

		private Vector3 shakePreviousPosition = Vector3.zero;

		public override bool IsBlockingOtherGestures => false;

		private ShakeState CurrentShakeState
		{
			get
			{
				return (ShakeState)stateMachine.CurrentStateId;
			}
			set
			{
				stateMachine.EnterState((ushort)value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			stateMachine = new ManualUpdateStateMachine();
			stateMachine.AddState(0, null, null, OnUpdateInactiveState);
			stateMachine.AddState(1, OnEnterTrackingState, null, OnUpdateTrackingState);
		}

		private void Start()
		{
			stateMachine.Initialize(0);
			base.enabled = base.hasAuthority;
		}

		private void Update()
		{
			stateMachine.Update();
		}

		private void OnUpdateInactiveState()
		{
			if (base.hasAuthority && !playerHandGestures.IsGestureBlocked(this) && base.Hand.RigidbodyEx.velocity.sqrMagnitude >= minShakeStartSpeed * minShakeStartSpeed)
			{
				CurrentShakeState = ShakeState.Tracking;
			}
		}

		private void OnEnterTrackingState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				distanceTraveled = 0f;
				shakeStartPosition = base.Hand.transform.position;
				shakePreviousPosition = shakeStartPosition;
				shakeStartTime = UnityEngine.Time.time;
			}
		}

		private void OnUpdateTrackingState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			bool flag = false;
			if (!playerHandGestures.IsGestureBlocked(this))
			{
				if (UnityEngine.Time.time - shakeStartTime < shakeTime)
				{
					if ((base.Hand.transform.position - shakeStartPosition).sqrMagnitude < shakeMaxDisplacement * shakeMaxDisplacement)
					{
						distanceTraveled += (base.Hand.transform.position - shakePreviousPosition).sqrMagnitude;
						shakePreviousPosition = base.Hand.transform.position;
						flag = true;
					}
				}
				else if (distanceTraveled >= shakeTravelDistance * shakeTravelDistance && base.Hand.HeldTool != null)
				{
					base.Hand.HeldTool.Shake();
				}
			}
			if (!flag)
			{
				CurrentShakeState = ShakeState.Inactive;
			}
		}
	}
	public class StopGesture : HandGestureBase
	{
		private enum StopGestureState
		{
			Inactive,
			Started,
			Charging,
			Completed
		}

		[SerializeField]
		private float handHeadDotThreshold = 0.95f;

		[SerializeField]
		private float palmDirectionDotThreshold = 0.8f;

		[SerializeField]
		private float fingerUpDotThreshold = 0.5f;

		[SerializeField]
		private float maximumDistance = 20f;

		[SerializeField]
		private float chargingDelay = 0.7f;

		[SerializeField]
		private float chargingDuration = 1.5f;

		private ManualUpdateStateMachine stateMachine;

		private float gestureStartTime;

		private GestureTarget targetToIgnore;

		public override bool IsBlockingOtherGestures => CurrentState == StopGestureState.Charging;

		private StopGestureState CurrentState
		{
			get
			{
				return (StopGestureState)stateMachine.CurrentStateId;
			}
			set
			{
				stateMachine.EnterState((ushort)value);
			}
		}

		public override void Cancel()
		{
			base.Cancel();
			if (base.hasAuthority)
			{
				CurrentState = StopGestureState.Inactive;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			stateMachine = new ManualUpdateStateMachine();
			stateMachine.AddState(0, null, null, OnUpdateInactiveState);
			stateMachine.AddState(1, OnEnterStartedState, null, OnUpdateStartedState);
			stateMachine.AddState(2, OnEnterChargingState, OnExitChargingState, OnUpdateChargingState);
			stateMachine.AddState(3, OnEnterCompletedState, null, null);
		}

		private void Start()
		{
			stateMachine.Initialize(0);
			base.enabled = base.hasAuthority;
		}

		private void Update()
		{
			stateMachine.Update();
		}

		private void OnUpdateInactiveState()
		{
			if (base.hasAuthority && TryAssignStopTarget())
			{
				CurrentState = StopGestureState.Started;
			}
		}

		private void OnEnterStartedState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				gestureStartTime = UnityEngine.Time.time;
			}
		}

		private void OnUpdateStartedState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (TryAssignStopTarget())
			{
				if (UnityEngine.Time.time >= gestureStartTime + chargingDelay)
				{
					CurrentState = StopGestureState.Charging;
				}
			}
			else
			{
				CurrentState = StopGestureState.Inactive;
			}
		}

		private void OnEnterChargingState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				gestureStartTime = UnityEngine.Time.time;
				if (targetToIgnore != null)
				{
					HandleGestureDetected(PlayerHandGestures.Gesture.StopGestureCharging, pauseOthers: false);
					targetToIgnore.StopGestureRunning(running: true);
					WorldSpaceNotification.PlayNext(targetToIgnore.Name, 2f, null, followPlayer: false, base.Hand.transform.position + Vector3.up * 0.15f, 0.3f);
				}
			}
		}

		private void OnUpdateChargingState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (CanContinueStopGesture())
			{
				if (UnityEngine.Time.time - chargingDuration >= gestureStartTime)
				{
					CurrentState = StopGestureState.Completed;
				}
			}
			else
			{
				CurrentState = StopGestureState.Inactive;
			}
		}

		private void OnExitChargingState(ushort otherStateId, ushort otherSubstateId)
		{
			if (otherStateId == 0 && targetToIgnore != null)
			{
				HandleGestureDetected(PlayerHandGestures.Gesture.StopGestureCancel, pauseOthers: false);
			}
			if (base.hasAuthority)
			{
				targetToIgnore.StopGestureRunning(running: false);
			}
		}

		private void OnEnterCompletedState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				HandleGestureDetected(PlayerHandGestures.Gesture.StopGestureSuccess, pauseOthers: true);
				targetToIgnore.SetIgnore(ignore: true);
				targetToIgnore = null;
				CurrentState = StopGestureState.Inactive;
			}
		}

		private void HandleGestureDetected(PlayerHandGestures.Gesture gesture, bool pauseOthers)
		{
			if (targetToIgnore != null)
			{
				playerHandGestures.HandleLocalHandGestureDetected(null, gesture, PhotonNetwork.ServerTimestamp, targetToIgnore.AttachedPlayer, pauseOthers);
			}
		}

		private bool TryAssignStopTarget()
		{
			targetToIgnore = null;
			if (playerHandGestures.IsGestureBlocked(this) || base.Hand.IsHoldingTool || !IsHandPositionedCorrectly())
			{
				return false;
			}
			Transform transform = base.Hand.ThisPlayer.Head.transform;
			targetToIgnore = DoRaycastForGestureTarget(new Ray(base.Hand.transform.position, (base.Hand.transform.position - transform.position).normalized));
			if (targetToIgnore == null)
			{
				targetToIgnore = DoRaycastForGestureTarget(new Ray(transform.position, transform.forward));
			}
			return targetToIgnore != null;
		}

		private GestureTarget DoRaycastForGestureTarget(Ray ray)
		{
			int num = Physics.RaycastNonAlloc(ray, HandGestureBase._hits, maximumDistance, 1052672, QueryTriggerInteraction.Collide);
			for (int i = 0; i < num; i++)
			{
				RaycastHit raycastHit = HandGestureBase._hits[i];
				GestureTarget gestureTarget = raycastHit.collider.GetGestureTarget();
				if (gestureTarget != null && gestureTarget.CanBeIgnored && (gestureTarget.AttachedPlayer == null || !gestureTarget.AttachedPlayer.isLocal))
				{
					return gestureTarget;
				}
			}
			return null;
		}

		private bool CanContinueStopGesture()
		{
			return targetToIgnore != null && IsHandPositionedCorrectly();
		}

		private bool IsHandPositionedCorrectly()
		{
			Transform transform = base.Hand.ThisPlayer.Head.transform;
			float num = Vector3.Dot(base.Hand.PalmDirection, transform.forward);
			float num2 = Vector3.Dot(base.Hand.FingerDirection, Vector3.up);
			float num3 = Vector3.Dot(transform.forward, (base.Hand.transform.position - transform.position).normalized);
			return base.Hand.OpenClosedAxis <= 0.01f && num >= palmDirectionDotThreshold && num2 >= fingerUpDotThreshold && num3 >= handHeadDotThreshold;
		}
	}
	public class ThumbsUpGesture : HandGestureBase
	{
		private enum ThumbsUpState
		{
			Inactive = 0,
			Started = 1,
			Playing = 2,
			Charging = 4,
			Completed = 5
		}

		[SerializeField]
		private float startDelay = 0.5f;

		[SerializeField]
		private float startAngleThreshold = 0.85f;

		[SerializeField]
		private float handHeadDotThreshold = 0.8f;

		[SerializeField]
		private float maxChargeDistance = 15f;

		[SerializeField]
		private float chargingDuration = 1.5f;

		[SerializeField]
		private float chargingDelay = 0.7f;

		private SynchronizedStateMachine stateMachine;

		private float thumbsUpDelayStart;

		private float chargingStartTime;

		private float playingStartTime;

		private GestureTarget gestureTarget;

		public override bool IsBlockingOtherGestures => CurrentThumbsUpState == ThumbsUpState.Charging;

		private ThumbsUpState CurrentThumbsUpState
		{
			get
			{
				return (ThumbsUpState)stateMachine.CurrentStateId;
			}
			set
			{
				stateMachine.EnterState((ushort)value);
			}
		}

		public override void Cancel()
		{
			base.Cancel();
			if (base.hasAuthority)
			{
				CurrentThumbsUpState = ThumbsUpState.Inactive;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			stateMachine = new SynchronizedStateMachine("THUMB", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, OnEnterInactiveState, null, OnUpdateInactiveState);
			stateMachine.AddState(1, null, null, OnUpdateStartedState);
			stateMachine.AddState(2, OnEnterPlayingState, null, OnUpdatePlayingState);
			stateMachine.AddState(4, OnEnterChargingState, OnExitChargingState, OnUpdateChargingState);
			stateMachine.AddState(5, OnEnterCompletedState, null, null);
		}

		private void Start()
		{
			stateMachine.Start(this, 0);
			base.enabled = base.hasAuthority;
		}

		private void Update()
		{
			stateMachine.Update();
		}

		private void OnEnterInactiveState(ushort otherStateId, ushort otherSubStateId)
		{
			base.Hand.ThumbsUpAnimationEnabled = false;
		}

		private void OnUpdateInactiveState()
		{
			if (base.hasAuthority && ThumbsUpStartConditions())
			{
				thumbsUpDelayStart = UnityEngine.Time.time;
				CurrentThumbsUpState = ThumbsUpState.Started;
			}
		}

		private void OnUpdateStartedState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (ThumbsUpStartConditions())
			{
				if (UnityEngine.Time.time - thumbsUpDelayStart >= startDelay)
				{
					CurrentThumbsUpState = ThumbsUpState.Playing;
				}
			}
			else
			{
				CurrentThumbsUpState = ThumbsUpState.Inactive;
			}
		}

		private void OnEnterPlayingState(ushort otherStateId, ushort otherSubStateId)
		{
			base.Hand.ThumbsUpAnimationEnabled = true;
			playingStartTime = UnityEngine.Time.time;
		}

		private void OnUpdatePlayingState()
		{
			if (base.hasAuthority)
			{
				if (ThumbsUpEndConditions())
				{
					thumbsUpDelayStart = 0f;
					CurrentThumbsUpState = ThumbsUpState.Inactive;
				}
				else if (TryAssignGestureTarget() && UnityEngine.Time.time >= playingStartTime + chargingDelay)
				{
					CurrentThumbsUpState = ThumbsUpState.Charging;
				}
			}
		}

		private void OnEnterChargingState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				chargingStartTime = UnityEngine.Time.time;
				if (gestureTarget != null)
				{
					HandleGestureDetected(PlayerHandGestures.Gesture.CheerGestureCharging, pauseOthers: false);
					WorldSpaceNotification.PlayNext(gestureTarget.Name, 2f, null, followPlayer: false, base.Hand.transform.position + Vector3.up * 0.15f, 0.3f);
				}
			}
		}

		private void OnUpdateChargingState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (CanContinueThumbsUpGesture())
			{
				if (UnityEngine.Time.time - chargingDuration >= chargingStartTime)
				{
					CurrentThumbsUpState = ThumbsUpState.Completed;
				}
			}
			else
			{
				CurrentThumbsUpState = ThumbsUpState.Inactive;
			}
		}

		private void OnExitChargingState(ushort otherStateId, ushort otherSubstateId)
		{
			if (otherStateId == 0 && gestureTarget != null)
			{
				HandleGestureDetected(PlayerHandGestures.Gesture.CheerGestureCancel, pauseOthers: false);
			}
			if (base.hasAuthority)
			{
				gestureTarget.StopGestureRunning(running: false);
			}
		}

		private void OnEnterCompletedState(ushort otherStateId, ushort otherSubstateId)
		{
			if (base.hasAuthority)
			{
				HandleGestureDetected(PlayerHandGestures.Gesture.CheerGestureSuccess, pauseOthers: true);
				gestureTarget.ShowCheerConfirmation();
				gestureTarget = null;
				CurrentThumbsUpState = ThumbsUpState.Inactive;
			}
		}

		private bool ThumbsUpStartConditions()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				return false;
			}
			return !playerHandGestures.IsGestureBlocked(this) && base.Hand.OpenClosedAxis >= 0.99f && Mathf.Abs(Vector3.Dot(base.Hand.ThumbDirection, Vector3.up)) >= startAngleThreshold;
		}

		private bool ThumbsUpChargingConditions()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				return false;
			}
			Transform transform = base.Hand.ThisPlayer.Head.transform;
			return !playerHandGestures.IsGestureBlocked(this) && base.Hand.OpenClosedAxis >= 0.99f && Vector3.Dot(base.Hand.ThumbDirection, Vector3.up) >= startAngleThreshold && Vector3.Dot((base.Hand.transform.position - transform.position).normalized, transform.forward) >= handHeadDotThreshold;
		}

		private bool ThumbsUpEndConditions()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				return true;
			}
			return playerHandGestures.IsGestureBlocked(this) || base.Hand.OpenClosedAxis < 0.99f;
		}

		private bool TryAssignGestureTarget()
		{
			gestureTarget = null;
			if (base.Hand.IsHoldingTool || !ThumbsUpChargingConditions())
			{
				return false;
			}
			Transform transform = base.Hand.ThisPlayer.Head.transform;
			gestureTarget = DoRaycastForGestureTarget(new Ray(transform.position, transform.forward));
			if (gestureTarget == null)
			{
				gestureTarget = DoRaycastForGestureTarget(new Ray(base.Hand.transform.position, (base.Hand.transform.position - transform.position).normalized));
			}
			return gestureTarget != null;
		}

		private GestureTarget DoRaycastForGestureTarget(Ray ray)
		{
			int num = Physics.RaycastNonAlloc(ray, HandGestureBase._hits, maxChargeDistance, 1052672, QueryTriggerInteraction.Collide);
			for (int i = 0; i < num; i++)
			{
				RaycastHit raycastHit = HandGestureBase._hits[i];
				GestureTarget gestureTarget = raycastHit.collider.GetGestureTarget();
				if (gestureTarget != null && gestureTarget.CanBeCheered && (gestureTarget.AttachedPlayer == null || !gestureTarget.AttachedPlayer.isLocal))
				{
					return gestureTarget;
				}
			}
			return null;
		}

		private bool CanContinueThumbsUpGesture()
		{
			return gestureTarget != null && ThumbsUpChargingConditions();
		}

		private void HandleGestureDetected(PlayerHandGestures.Gesture gesture, bool pauseOthers)
		{
			if (gestureTarget != null)
			{
				playerHandGestures.HandleLocalHandGestureDetected(null, gesture, PhotonNetwork.ServerTimestamp, gestureTarget.AttachedPlayer, pauseOthers);
			}
		}
	}
}
public class GestureTarget : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool supportsStop = true;

	[SerializeField]
	private bool supportsCheer = true;

	public Action<bool> IgnoreEvent;

	private float lastIgnoreTime;

	private float minTimeBetweenIgnores = 1f;

	private float lastCheerTime;

	private float minTimeBetweenCheers = 2f;

	public Player AttachedPlayer { get; private set; }

	public RoomDoor AttachedRoomDoor { get; private set; }

	public bool IsIgnored
	{
		get
		{
			if (AttachedPlayer == null)
			{
				return false;
			}
			return AttachedPlayer.DisplayAsIgnored;
		}
	}

	public bool CanBeIgnored => !IsIgnored && supportsStop && (AttachedPlayer == null || AttachedPlayer != Player.LocalPlayer) && UnityEngine.Time.time - lastIgnoreTime > minTimeBetweenIgnores;

	public bool CanBeCheered => supportsCheer && (AttachedPlayer == null || !AttachedPlayer.isLocal) && UnityEngine.Time.time - lastCheerTime > minTimeBetweenCheers;

	public string Name
	{
		get
		{
			if (AttachedPlayer != null)
			{
				return AttachedPlayer.PlayerName;
			}
			return "Sandy";
		}
	}

	private void Awake()
	{
		AttachedPlayer = GetComponentInParent<Player>();
		AttachedRoomDoor = GetComponentInParent<RoomDoor>();
	}

	public void StopGestureRunning(bool running)
	{
		if (AttachedPlayer != null)
		{
			AttachedPlayer.LocalIgnore = running;
		}
	}

	public void SetIgnore(bool ignore)
	{
		StopGestureRunning(running: false);
		if (AttachedPlayer != null)
		{
			Player.SavePlayerIgnored(AttachedPlayer.PlayerId, ignore);
			StartCoroutine(RunShowStopWatchConfirmation());
		}
		else if (ignore)
		{
			lastIgnoreTime = UnityEngine.Time.time;
		}
		if (IgnoreEvent != null)
		{
			IgnoreEvent(ignore);
		}
	}

	private IEnumerator RunShowStopWatchConfirmation()
	{
		yield return new WaitForSeconds(0.6f);
		Player.LocalPlayer.PlayerUI.WatchMenu.PlayAttract();
		StopPlayerWatchUIFlow stopFlow = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<StopPlayerWatchUIFlow>();
		stopFlow.SetPlayer(AttachedPlayer);
		stopFlow.MuteAndIgnorePlayer(AttachedPlayer);
		Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(stopFlow);
	}

	public void ShowCheerConfirmation()
	{
		lastCheerTime = UnityEngine.Time.time;
		StartCoroutine(RunShowCheerWatchConfirmation());
	}

	private IEnumerator RunShowCheerWatchConfirmation()
	{
		yield return new WaitForSeconds(0.6f);
		Player.LocalPlayer.PlayerUI.WatchMenu.PlayAttract();
		CheerPlayerWatchUIFlow cheerFlow = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<CheerPlayerWatchUIFlow>();
		cheerFlow.SetPlayer(AttachedPlayer);
		Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(cheerFlow);
	}

	public void ShowPointConfirmation(PlayerHand hand)
	{
		if (AttachedPlayer != null)
		{
			Player.LocalPlayer.PlayerUI.WatchMenuProjector.AuthorityOpenMenuDetached();
			if (AttachedPlayer.isLocal)
			{
				ProfileWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<ProfileWatchUIFlow>();
				flowByType.SetPlayer(AttachedPlayer);
				Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
			}
			else
			{
				PlayerDetailsWatchUIFlow flowByType2 = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<PlayerDetailsWatchUIFlow>();
				flowByType2.SetPlayer(AttachedPlayer);
				Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType2);
				Player.LocalPlayer.PlayerEvents.PointedAtPlayer();
			}
		}
		else if (AttachedRoomDoor != null && !string.IsNullOrEmpty(AttachedRoomDoor.TargetName) && AttachedRoomDoor.IsLocked)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Locked!", 2f);
		}
	}
}
public delegate void PanicToggledEventHandler(object sender);
[RequireComponent(typeof(Collider))]
public class GhostingPulse : UnityEngine.MonoBehaviour
{
	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private PanicToggledEventHandler m_PanicToggled;

	private CapsuleCollider ghostingCollider;

	private Player thisPlayer;

	private float startRadiusScale;

	private float startHeightScale;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip onEnableAudioClip;

	[SerializeField]
	private RecRoomAudioClip activeLoopingAudioClip;

	[Header("Visuals")]
	[SerializeField]
	private FloatValueCurve radiusAnimationCurve;

	[SerializeField]
	private FloatValueCurve heightAnimationCurve;

	[SerializeField]
	private ParticleSystem EMPParticle;

	[SerializeField]
	private FloatValueCurve alphaOverDistanceCurve;

	[SerializeField]
	private Material ghostMaterial;

	[SerializeField]
	private GameObject situationRingPrefab;

	private SFXAudioSource loopingAudioSource;

	private bool _pulseEnabled = true;

	private float activeTime;

	private bool active;

	public Material GhostMaterial => ghostMaterial;

	public bool PulseEnabled
	{
		get
		{
			return _pulseEnabled;
		}
		set
		{
			_pulseEnabled = value;
			if (Active && !_pulseEnabled)
			{
				Active = false;
			}
		}
	}

	public bool Active
	{
		get
		{
			return active;
		}
		set
		{
			if (!PulseEnabled)
			{
				value = false;
			}
			if (!value)
			{
				StopPulseActiveAudio();
			}
			else if (!active)
			{
				PlayPulseActiveAudio();
			}
			activeTime = 0f;
			ghostingCollider.enabled = value;
			SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumeLowered = value;
			foreach (Transform item in base.transform)
			{
				item.gameObject.SetActive(value);
			}
			bool flag = active;
			active = value;
			if (active != flag && this.PanicToggled != null)
			{
				this.PanicToggled(this);
			}
		}
	}

	public float Radius => ghostingCollider.bounds.extents.x;

	public float MaxRadius => ghostingCollider.radius;

	public event PanicToggledEventHandler PanicToggled
	{
		add
		{
			PanicToggledEventHandler panicToggledEventHandler = this.m_PanicToggled;
			PanicToggledEventHandler panicToggledEventHandler2;
			do
			{
				panicToggledEventHandler2 = panicToggledEventHandler;
				panicToggledEventHandler = Interlocked.CompareExchange(ref this.m_PanicToggled, (PanicToggledEventHandler)Delegate.Combine(panicToggledEventHandler2, value), panicToggledEventHandler);
			}
			while (panicToggledEventHandler != panicToggledEventHandler2);
		}
		remove
		{
			PanicToggledEventHandler panicToggledEventHandler = this.m_PanicToggled;
			PanicToggledEventHandler panicToggledEventHandler2;
			do
			{
				panicToggledEventHandler2 = panicToggledEventHandler;
				panicToggledEventHandler = Interlocked.CompareExchange(ref this.m_PanicToggled, (PanicToggledEventHandler)Delegate.Remove(panicToggledEventHandler2, value), panicToggledEventHandler);
			}
			while (panicToggledEventHandler != panicToggledEventHandler2);
		}
	}

	private void Awake()
	{
		ghostingCollider = GetComponent<CapsuleCollider>();
		if (ghostingCollider == null)
		{
			UnityEngine.Debug.LogError("Ghosting pulse collider is not a Capsule Collider.");
		}
		thisPlayer = base.gameObject.GetComponentInParent<Player>();
	}

	private void Start()
	{
		GameObject gameObject = UnityEngine.Object.Instantiate(situationRingPrefab, base.transform, worldPositionStays: false);
		gameObject.transform.localScale = Vector3.one;
		gameObject.transform.localPosition = Vector3.zero;
		startRadiusScale = base.transform.localScale.x;
		startHeightScale = base.transform.localScale.z;
		Active = false;
	}

	private void Update()
	{
		if (!Active)
		{
			return;
		}
		base.transform.position = thisPlayer.CurrentFloorPosition;
		base.transform.localPosition = Vector3.zero;
		if (activeTime <= radiusAnimationCurve.Duration)
		{
			float num = startRadiusScale + radiusAnimationCurve.Evaluate(activeTime / radiusAnimationCurve.Duration);
			float z = startHeightScale + heightAnimationCurve.Evaluate(activeTime / heightAnimationCurve.Duration);
			base.transform.localScale = new Vector3(num, num, z);
			if (activeTime + UnityEngine.Time.deltaTime > radiusAnimationCurve.Duration && EMPParticle != null)
			{
				EMPParticle.Play();
			}
		}
		activeTime += UnityEngine.Time.deltaTime;
	}

	public void TogglePanic()
	{
		Active = !Active;
	}

	public float AlphaForDistance(float distance)
	{
		float t = Mathf.Min(distance / MaxRadius, 1f);
		return alphaOverDistanceCurve.Evaluate(t);
	}

	private void PlayPulseActiveAudio()
	{
		StopPulseActiveAudio();
		AudioManager.Play3DSFX(onEnableAudioClip, thisPlayer.CurrentFloorPosition);
		loopingAudioSource = AudioManager.StartLooping2DSFX(activeLoopingAudioClip);
	}

	private void StopPulseActiveAudio()
	{
		if (loopingAudioSource != null)
		{
			AudioManager.StopLoopingSFX(loopingAudioSource);
			loopingAudioSource = null;
		}
	}
}
public class HandCollisionTransformUpdater : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private BoxCollider handCollider;

	[SerializeField]
	[Autofill(AutofillType.Parent, false)]
	private PlayerHand myHand;

	[SerializeField]
	private Vector3 rotationWhenClosedEuler;

	[SerializeField]
	private Vector3 colliderCenterWhenClosed;

	[SerializeField]
	private Vector3 colliderSizeWhenClosed;

	private Quaternion rotationWhenClosed;

	private Quaternion rotationWhenOpen;

	private Vector3 colliderCenterWhenOpen;

	private Vector3 colliderSizeWhenOpen;

	private bool wasClosed;

	private void Awake()
	{
		rotationWhenClosed = Quaternion.Euler(rotationWhenClosedEuler);
		rotationWhenOpen = base.transform.localRotation;
		colliderCenterWhenOpen = handCollider.center;
		colliderSizeWhenOpen = handCollider.size;
	}

	private void Update()
	{
		bool flag = myHand.OpenClosedAxis > 0.5f;
		if (flag != wasClosed)
		{
			if (flag)
			{
				base.transform.localRotation = rotationWhenClosed;
				handCollider.center = colliderCenterWhenClosed;
				handCollider.size = colliderSizeWhenClosed;
			}
			else
			{
				base.transform.localRotation = rotationWhenOpen;
				handCollider.center = colliderCenterWhenOpen;
				handCollider.size = colliderSizeWhenOpen;
			}
			wasClosed = flag;
		}
	}
}
public class HeadGestureDetect : UnityEngine.MonoBehaviour
{
	public enum Gesture
	{
		TiltUp,
		TiltDown,
		NodUp,
		NodDown,
		FullNod,
		TurnLeft,
		TurnRight,
		ShakeLeft,
		ShakeRight,
		FullShake,
		LeanLeft,
		LeanRight,
		NodLeft,
		NodRight,
		FullSideNod
	}

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<Gesture> m_GestureDetected;

	[SerializeField]
	private float nodSensitivity = 10f;

	[SerializeField]
	private float shakeSensitivity = 10f;

	[SerializeField]
	private float leanSensitivity = 10f;

	[SerializeField]
	private float nodNeutralZone = 5f;

	[SerializeField]
	private float shakeNeutralZone = 5f;

	[SerializeField]
	private float leanNeutralZone = 5f;

	[SerializeField]
	private float timeOut = 3f;

	[SerializeField]
	private Transform trackedHead;

	[Tooltip("Enabling this will fire all the different gestures and not just the full gestures.")]
	public bool DetailedDetection;

	private float countdown;

	private float baselineX;

	private float baselineY;

	private float baselineZ;

	private float pitch;

	private float yaw;

	private float roll;

	private float doSomethingTime;

	private bool tiltUp;

	private bool tiltDown;

	private bool nodUp;

	private bool nodDown;

	private bool turnLeft;

	private bool turnRight;

	private bool shakeLeft;

	private bool shakeRight;

	private bool leanLeft;

	private bool leanRight;

	private bool nodLeft;

	private bool nodRight;

	private int nods;

	private int shakes;

	private int sideNods;

	private float pitchAng;

	private float yawAng;

	private float rollAng;

	public event Action<Gesture> GestureDetected
	{
		add
		{
			Action<Gesture> action = this.m_GestureDetected;
			Action<Gesture> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_GestureDetected, (Action<Gesture>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<Gesture> action = this.m_GestureDetected;
			Action<Gesture> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_GestureDetected, (Action<Gesture>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Start()
	{
		if (trackedHead == null)
		{
			trackedHead = base.transform;
		}
		baselineX = Angle(trackedHead.localEulerAngles.x);
		baselineY = Angle(trackedHead.localEulerAngles.y);
		baselineZ = Angle(trackedHead.localEulerAngles.z);
		doSomethingTime = UnityEngine.Time.time;
	}

	private void Update()
	{
		countdown = UnityEngine.Time.time - doSomethingTime;
		pitch = Angle(trackedHead.localEulerAngles.x);
		yaw = Angle(trackedHead.localEulerAngles.y);
		roll = Angle(trackedHead.localEulerAngles.z);
		pitchAng = AngleBetween(pitch, baselineX);
		yawAng = AngleBetween(yaw, baselineY);
		rollAng = AngleBetween(roll, baselineZ);
		if (tiltUp && countdown > timeOut)
		{
			tiltUp = false;
			baselineX = pitch;
			return;
		}
		if (tiltDown && countdown > timeOut)
		{
			tiltDown = false;
			baselineX = pitch;
			return;
		}
		if (turnLeft && countdown > timeOut)
		{
			turnLeft = false;
			baselineY = yaw;
			return;
		}
		if (turnRight && countdown > timeOut)
		{
			turnRight = false;
			baselineY = yaw;
			return;
		}
		if (nods > 0 && countdown > timeOut)
		{
			nods = 0;
		}
		if (shakes > 0 && countdown > timeOut)
		{
			shakes = 0;
		}
		if (sideNods > 0 && countdown > timeOut)
		{
			sideNods = 0;
		}
		if (!tiltUp && pitchAng < 0f - nodSensitivity)
		{
			tiltUp = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltUp);
			}
		}
		if (tiltUp && pitchAng > nodNeutralZone && countdown < timeOut)
		{
			tiltUp = false;
			nodUp = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodUp);
			}
		}
		if (!tiltDown && pitchAng > nodSensitivity)
		{
			tiltDown = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TiltDown);
			}
		}
		if (tiltDown && pitchAng < nodNeutralZone && countdown < timeOut)
		{
			tiltDown = false;
			doSomethingTime = UnityEngine.Time.time;
			nodDown = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodDown);
			}
		}
		if (nodDown && nodUp)
		{
			nods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullNod);
			}
			doSomethingTime = UnityEngine.Time.time;
			nodUp = false;
			nodDown = false;
		}
		if (!turnRight && yawAng > shakeSensitivity)
		{
			turnRight = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnRight);
			}
		}
		if (turnRight && yawAng < shakeNeutralZone && countdown < timeOut)
		{
			turnRight = false;
			shakeRight = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeRight);
			}
		}
		if (!turnLeft && yawAng < 0f - shakeSensitivity)
		{
			turnLeft = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.TurnLeft);
			}
		}
		if (turnLeft && yawAng > 0f - shakeNeutralZone)
		{
			turnLeft = false;
			doSomethingTime = UnityEngine.Time.time;
			shakeLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.ShakeLeft);
			}
		}
		if (shakeLeft && shakeRight)
		{
			shakes++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullShake);
			}
			doSomethingTime = UnityEngine.Time.time;
			shakeLeft = false;
			shakeRight = false;
		}
		if (!leanRight && rollAng < 0f - leanSensitivity)
		{
			leanRight = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanRight);
			}
		}
		if (leanRight && rollAng > leanNeutralZone && countdown < timeOut)
		{
			leanRight = false;
			nodRight = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodRight);
			}
		}
		if (!leanLeft && rollAng > leanSensitivity)
		{
			leanLeft = true;
			doSomethingTime = UnityEngine.Time.time;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.LeanLeft);
			}
		}
		if (leanLeft && rollAng < leanNeutralZone)
		{
			leanLeft = false;
			doSomethingTime = UnityEngine.Time.time;
			nodLeft = true;
			if (DetailedDetection && this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.NodLeft);
			}
		}
		if (nodLeft && nodRight)
		{
			sideNods++;
			if (this.GestureDetected != null)
			{
				this.GestureDetected(Gesture.FullSideNod);
			}
			doSomethingTime = UnityEngine.Time.time;
			nodLeft = false;
			nodRight = false;
		}
	}

	private float Angle(float a)
	{
		if (a > 180f)
		{
			a -= 360f;
		}
		return a;
	}

	private float AngleBetween(float a, float b)
	{
		float num = a - b;
		if (num > 180f || num < -180f)
		{
			num = 360f - num;
		}
		return num;
	}
}
