	public class LocalPlayerController : SingletonMonoBehaviour<LocalPlayerController>
	{
		public enum DisplayMode
		{
			UNINITIALIZED,
			VR,
			SCREEN
		}

		public enum PlayerType
		{
			UNINITIALIZED,
			VR_WALK,
			VR_TELEPORT,
			SCREEN
		}

		private enum State
		{
			SPLASH_SCREEN,
			GAMEPLAY
		}

		private const string FORCE_DISPLAY_MODE_OVERRIDE_PREFIX = "+forcemode:";

		private const string DISPLAY_MODE_OVERRIDE_PREFIX = "+mode:";

		private const string SCREEN_LAUNCH_STRING = "screen";

		private const string VR_LAUNCH_STRING = "vr";

		public static readonly List<PlayerType> AllPlayerTypes = new List<PlayerType>
		{
			PlayerType.VR_WALK,
			PlayerType.VR_TELEPORT,
			PlayerType.SCREEN
		};

		[Header("VR Controllers")]
		[SerializeField]
		private VRPlayerController vrWalkPlayerController;

		[SerializeField]
		private VRPlayerController vrTeleportPlayerController;

		[SerializeField]
		private VRSplashScreenController vrSplashScreenController;

		[Header("Screens Controllers")]
		[SerializeField]
		private ScreenPlayerController screenController;

		[SerializeField]
		private ScreenUISplashScreenController screenUISplashScreenController;

		private State state;

		private PlayerType _currentPlayerType;

		private DisplayMode _currentDisplayMode;

		private IPlayerController _activeController;

		private bool _gameViewFocused;

		private bool _canDynamicallySwitchDisplayMode = true;

		private bool _isCursorLocked;

		public Action DisplayModeChange;

		public Action PlayerTypeChange;

		public Action CanDynamicallySwitchDisplayModeChange;

		private VRMovementMode? preSwitchRoomMode;

		public bool InScreenDisplayMode => CurrentDisplayMode == DisplayMode.SCREEN;

		public bool InVRDisplayMode => CurrentDisplayMode == DisplayMode.VR;

		public PlayerType CurrentPlayerType
		{
			get
			{
				return _currentPlayerType;
			}
			private set
			{
				if (_currentPlayerType != value)
				{
					_currentPlayerType = value;
					switch (value)
					{
					case PlayerType.SCREEN:
						CurrentDisplayMode = DisplayMode.SCREEN;
						break;
					case PlayerType.VR_WALK:
					case PlayerType.VR_TELEPORT:
						CurrentDisplayMode = DisplayMode.VR;
						break;
					}
					if (AnalyticsHelper.HasClientInitialized)
					{
						AnalyticsHelper.UpdatePlayerType();
					}
					if (PlayerTypeChange != null)
					{
						PlayerTypeChange();
					}
				}
			}
		}

		public DisplayMode CurrentDisplayMode
		{
			get
			{
				return _currentDisplayMode;
			}
			private set
			{
				if (_currentDisplayMode != value)
				{
					_currentDisplayMode = value;
					RecNet.Core.InScreenMode = value == DisplayMode.SCREEN && !SessionManager.IsDeveloper;
					if (Player.LocalPlayer != null)
					{
						Player.LocalPlayer.ControllerDisplayMode = value;
					}
					if (DisplayModeChange != null)
					{
						DisplayModeChange();
					}
				}
			}
		}

		private IPlayerController ActiveController
		{
			get
			{
				return _activeController;
			}
			set
			{
				if (_activeController != value)
				{
					if (_activeController != null)
					{
						_activeController.OnExitMode();
					}
					_activeController = value;
					if (_activeController != null)
					{
						_activeController.OnEnterMode();
					}
				}
			}
		}

		public bool GameViewFocused
		{
			get
			{
				return _gameViewFocused;
			}
			private set
			{
				_gameViewFocused = value;
				UpdateCursor();
			}
		}

		public bool CanDynamicallySwitchDisplayMode
		{
			get
			{
				return _canDynamicallySwitchDisplayMode;
			}
			private set
			{
				if (_canDynamicallySwitchDisplayMode != value)
				{
					_canDynamicallySwitchDisplayMode = value;
					if (CanDynamicallySwitchDisplayModeChange != null)
					{
						CanDynamicallySwitchDisplayModeChange();
					}
				}
			}
		}

		public bool IsCursorLocked
		{
			get
			{
				return _isCursorLocked;
			}
			set
			{
				_isCursorLocked = value;
				UpdateCursor();
			}
		}

		public ScreenPlayerController ScreenPlayerController
		{
			[CompilerGenerated]
			get
			{
				return screenController;
			}
		}

		public static string GetPlayerModeDescription(PlayerType playerType)
		{
			return playerType switch
			{
				PlayerType.SCREEN => "Screen", 
				PlayerType.VR_TELEPORT => "Teleport", 
				PlayerType.VR_WALK => "Walk", 
				_ => "Invalid", 
			};
		}

		public void SwitchVRMovementModeToJoinRoom(VRMovementMode requiredMode)
		{
			if (CurrentPlayerType == PlayerType.VR_TELEPORT || CurrentPlayerType == PlayerType.VR_WALK)
			{
				preSwitchRoomMode = SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode;
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = requiredMode;
				SetVRDisplayMode();
			}
		}

		public void ClearPreSwitchRoomVRMovementMode()
		{
			preSwitchRoomMode = null;
		}

		public void TryRevertVRMovementMode()
		{
			if ((CurrentPlayerType == PlayerType.VR_TELEPORT || CurrentPlayerType == PlayerType.VR_WALK) && preSwitchRoomMode.HasValue)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = preSwitchRoomMode.Value;
				ClearPreSwitchRoomVRMovementMode();
				SetVRDisplayMode();
			}
		}

		public void SetScreenDisplayMode()
		{
			CanDynamicallySwitchDisplayMode = false;
			SetPlayerTypeByDisplayMode(DisplayMode.SCREEN);
		}

		public void SetVRDisplayMode()
		{
			CanDynamicallySwitchDisplayMode = false;
			SetPlayerTypeByDisplayMode(DisplayMode.VR);
		}

		private void SetPlayerTypeByDisplayMode(DisplayMode mode)
		{
			switch (mode)
			{
			case DisplayMode.SCREEN:
				CurrentPlayerType = PlayerType.SCREEN;
				break;
			case DisplayMode.VR:
				CurrentPlayerType = GetVRPlayerType();
				break;
			}
		}

		public Player InstantiateLocalPlayer(Vector3 position, Quaternion rotation)
		{
			if (ActiveController == null)
			{
				UnityEngine.Debug.LogError("Local Player Controller Instantiate Local Player Error: Missing Active Controller.");
				return null;
			}
			return ActiveController.InstantiateLocalPlayer(position, rotation);
		}

		public void EnterSplashScreenState()
		{
			state = State.SPLASH_SCREEN;
		}

		public void EnterGameplayState()
		{
			UpdateCurrentPlayerType();
			state = State.GAMEPLAY;
		}

		public void OnSplashScreenLoad(SplashScreenSpawnPoint splashScreenSpawnPoint)
		{
			if (state != State.SPLASH_SCREEN)
			{
				UnityEngine.Debug.LogError("Splash screen scene was loaded while not in the splash screen controller state.");
			}
			else
			{
				ActiveController.OnSplashScreenLoad(splashScreenSpawnPoint);
			}
		}

		public bool TryPickupSpawnTool(Player player, PlayerHand playerHand, Tool tool)
		{
			if (ActiveController == null)
			{
				return false;
			}
			return ActiveController.TryPickupSpawnTool(player, playerHand, tool);
		}

		public void AddScreenCustomGameBehaviorControllers(ScreenCustomGameBehaviorController[] customGameBehaviorControllers)
		{
			screenController.AddCustomGameBehaviorControllers(customGameBehaviorControllers);
		}

		public void ClearScreenCustomGameBehaviorControllers()
		{
			screenController.ClearCustomGameBehaviorControllers();
		}

		public void AddScreensDefaultControlType(ScreenPlayerController.ScreenPlayerGenreType controlType, object token, int priority)
		{
			screenController.AddGenreType(controlType, token, priority);
		}

		public void RemoveScreensDefaultControlType(object token)
		{
			screenController.RemoveGenreType(token);
		}

		protected override void Awake()
		{
			base.Awake();
			GameViewFocused = true;
			Player.LocalPlayerCreatedEvent += new Action(OnLocalPlayerCreated);
			Player.LocalPlayerDestroyedEvent += new Action(OnLocalPlayerDestroyed);
			PlayerTrackingSpace.OnLocalPlayerTrackingSpaceRigidbodyExLateUpdate += OnTrackingSpaceLateUpdate;
			vrWalkPlayerController.Initialize(this);
			vrTeleportPlayerController.Initialize(this);
			vrSplashScreenController.Initialize(this);
			screenController.Initialize(this);
			screenUISplashScreenController.Initialize(this);
			CheckDisplayModeOverrides();
		}

		private void Start()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementModeChanged += OnVRMovementModeChanged;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PlayerTrackingSpace.OnLocalPlayerTrackingSpaceRigidbodyExLateUpdate -= OnTrackingSpaceLateUpdate;
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementModeChanged -= OnVRMovementModeChanged;
			}
			Player.LocalPlayerCreatedEvent -= new Action(OnLocalPlayerCreated);
			Player.LocalPlayerDestroyedEvent -= new Action(OnLocalPlayerDestroyed);
		}

		private void Update()
		{
			UpdateCurrentDisplayMode();
			UpdateActiveController();
			if (ActiveController == null)
			{
				UnityEngine.Debug.LogError("Local Player Controller Update: Missing Active Controller.");
			}
			else
			{
				ActiveController.OnUpdate();
			}
		}

		private void OnTrackingSpaceLateUpdate()
		{
			if (ActiveController == null)
			{
				UnityEngine.Debug.LogError("Local Player Controller Late Update: Missing Active Controller.");
			}
			else
			{
				ActiveController.OnLateUpdate();
			}
		}

		private void OnApplicationFocus(bool focus)
		{
			GameViewFocused = focus;
		}

		private void OnDrawGizmos()
		{
			if (ActiveController != null)
			{
				ActiveController.OnDrawGizmos();
			}
		}

		private void OnLocalPlayerCreated()
		{
			if (ActiveController != null)
			{
				ActiveController.OnLocalPlayerCreated();
			}
		}

		private void OnLocalPlayerDestroyed()
		{
			if (ActiveController != null)
			{
				ActiveController.OnLocalPlayerDestroyed();
			}
		}

		private void OnVRMovementModeChanged()
		{
			UpdateCurrentPlayerType();
		}

		private void UpdateCurrentDisplayMode()
		{
			if (CanDynamicallySwitchDisplayMode)
			{
				DisplayMode desiredDisplayMode = GetDesiredDisplayMode();
				SetPlayerTypeByDisplayMode(desiredDisplayMode);
			}
		}

		private void UpdateCurrentPlayerType()
		{
			if (!CanDynamicallySwitchDisplayMode)
			{
				SetPlayerTypeByDisplayMode(CurrentDisplayMode);
			}
		}

		private DisplayMode GetDesiredDisplayMode()
		{
			return (SingletonMonoBehaviour<VRDeviceManager>.Instance != null && SingletonMonoBehaviour<VRDeviceManager>.Instance.UserInHMD) ? DisplayMode.VR : DisplayMode.SCREEN;
		}

		private PlayerType GetVRPlayerType()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode == VRMovementMode.TELEPORT)
			{
				return PlayerType.VR_TELEPORT;
			}
			return PlayerType.VR_WALK;
		}

		private void UpdateActiveController()
		{
			switch (state)
			{
			case State.SPLASH_SCREEN:
				if (CurrentPlayerType == PlayerType.VR_WALK || CurrentPlayerType == PlayerType.VR_TELEPORT)
				{
					ActiveController = vrSplashScreenController;
				}
				else if (CurrentPlayerType == PlayerType.SCREEN)
				{
					ActiveController = screenUISplashScreenController;
				}
				break;
			case State.GAMEPLAY:
				if (CurrentPlayerType == PlayerType.VR_WALK)
				{
					ActiveController = vrWalkPlayerController;
				}
				else if (CurrentPlayerType == PlayerType.VR_TELEPORT)
				{
					ActiveController = vrTeleportPlayerController;
				}
				else if (CurrentPlayerType == PlayerType.SCREEN)
				{
					ActiveController = screenController;
				}
				break;
			}
		}

		internal void AddScreenModeQuickTimeEmotes(QuickTimeEmote[] quickTimeEmotes)
		{
			screenController.QuickTimeEmoteController.AddEmotes(quickTimeEmotes);
		}

		internal void RemoveScreenCustomQuickTimeEmotes(QuickTimeEmote[] quickTimeEmotes)
		{
			screenController.QuickTimeEmoteController.RemoveEmotes(quickTimeEmotes);
		}

		private void CheckDisplayModeOverrides()
		{
			string modeArg = PUNNetworkManager.CheckCommandLineArgsFor("+forcemode:");
			if (!ProcessDisplayModeArg(modeArg))
			{
				string modeArg2 = PUNNetworkManager.CheckCommandLineArgsFor("+mode:");
				ProcessDisplayModeArg(modeArg2);
			}
		}

		private bool ProcessDisplayModeArg(string modeArg)
		{
			if (!string.IsNullOrEmpty(modeArg))
			{
				if (modeArg.Equals("screen", StringComparison.InvariantCultureIgnoreCase))
				{
					SetScreenDisplayMode();
					return true;
				}
				if (SingletonMonoBehaviour<VRDeviceManager>.Instance != null && SingletonMonoBehaviour<VRDeviceManager>.Instance.HMDExists && modeArg.Equals("vr", StringComparison.InvariantCultureIgnoreCase))
				{
					SetVRDisplayMode();
					return true;
				}
			}
			return false;
		}

		private void UpdateCursor()
		{
			if (GameViewFocused && !StreamerGUI.ShowGUI)
			{
				Cursor.visible = false;
				Cursor.lockState = (IsCursorLocked ? CursorLockMode.Locked : CursorLockMode.None);
			}
			else
			{
				Cursor.visible = true;
				Cursor.lockState = CursorLockMode.None;
			}
		}
	}
	public class MenuFinger : UnityEngine.MonoBehaviour
	{
		public Transform FingertipTransform;

		[Autofill(AutofillType.Self, false)]
		public BoxCollider overlapCollider;

		[SerializeField]
		[AutofillOptional(AutofillType.SelfAndParent, true)]
		private PhotonView photonView;

		[SerializeField]
		private PlayerHand.HandType fingerType;

		private Button3DBase prevOverlapButton;

		private PhysicalButtonBase latestPushedButton;

		public bool isLocal => photonView == null || photonView.isLocal;

		public VRInputHandler InputHandler => (fingerType != PlayerHand.HandType.Left) ? SingletonMonoBehaviour<InputManager>.Instance.RightHandVRInputHandler : SingletonMonoBehaviour<InputManager>.Instance.LeftHandVRInputHandler;

		public void SetLaserButtonPushed(bool inputDown, bool inputUp, PhotonPlayer player, PhysicalButtonBase button)
		{
			if (button != null && inputDown)
			{
				if (button != latestPushedButton)
				{
					ReleaseLatestPushedButton(player);
				}
				latestPushedButton = button;
				button.LaserPress(player);
			}
			if (inputUp || button == null)
			{
				ReleaseLatestPushedButton(player);
			}
		}

		public void ReleaseLatestPushedButton(PhotonPlayer player)
		{
			if (latestPushedButton != null)
			{
				latestPushedButton.LaserRelease(player);
				latestPushedButton = null;
			}
		}

		private void LateUpdate()
		{
			Button3DBase button3DBase = null;
			int num = overlapCollider.Overlap(PhysicsExt.IMMEDIATE_COLLIDER_HITS, 4197409, QueryTriggerInteraction.Collide);
			for (int i = 0; i < num; i++)
			{
				Collider collider = PhysicsExt.IMMEDIATE_COLLIDER_HITS[i];
				if (!collider.gameObject.CompareTag("Button3D"))
				{
					continue;
				}
				Button3DBase componentInParent = collider.GetComponentInParent<Button3DBase>();
				if (componentInParent != null)
				{
					if (prevOverlapButton == null)
					{
						button3DBase = componentInParent;
						break;
					}
					if (componentInParent == prevOverlapButton)
					{
						button3DBase = componentInParent;
					}
				}
			}
			if (button3DBase != null)
			{
				button3DBase.TrySetMenuFinger(this);
			}
			else if (prevOverlapButton != null)
			{
				prevOverlapButton.TryReleaseMenuFinger(this);
			}
			prevOverlapButton = button3DBase;
		}

		public bool OverlapsPoint(Vector3 worldPosition)
		{
			return overlapCollider.Contains(worldPosition);
		}
	}
