	public class FlyVRMovementController : VRMovementController
	{
		private class HandState
		{
			public PlayerHand Hand;

			public VRInputHandler Input;

			public PlayerFlyIndicator Indicator;

			private float charge;

			public bool IsFullyCharged => Charge >= 1f;

			public float Charge
			{
				get
				{
					return charge;
				}
				set
				{
					if (charge != value)
					{
						charge = value;
						if (Indicator != null)
						{
							Indicator.Charge = charge;
						}
					}
				}
			}
		}

		public PlayerFlyIndicator IndicatorPrefab;

		private static readonly float MaxArmDistance = 0.4f;

		private static readonly Vector3 HeadToChest = new Vector3(0f, -0.3f, 0f);

		private static readonly float SpeedCurveExponent = 2f;

		private static readonly float MinFlightSpeed = 0.5f;

		private static readonly float MaxFlightSpeed = 50f;

		private static readonly float StartGestureDuration = 0.7f;

		private static readonly float StartGestureAngleLimit = 45f;

		private static readonly float VignetteFadeInTime = 0.1f;

		private static readonly float VignetteFadeOutTime = 0.25f;

		private bool isFlyingThisFrame;

		private bool isFullyChargedThisFrame;

		private float relativeDistance = float.MaxValue;

		private Vector3 savedChestPosition;

		private HandState LeftHandState;

		private HandState RightHandState;

		private void OnPlayerTeleported(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
		{
			LeftHandState.Charge = 0f;
			RightHandState.Charge = 0f;
		}

		public override void OnEnterMode(Player player)
		{
			player.PlayerLocomotion.TeleportEvent += OnPlayerTeleported;
		}

		public override void OnExitMode(Player player)
		{
			if (LeftHandState != null)
			{
				if (LeftHandState.Indicator != null)
				{
					UnityEngine.Object.Destroy(LeftHandState.Indicator.gameObject);
				}
				LeftHandState = null;
			}
			if (RightHandState != null)
			{
				if (RightHandState.Indicator != null)
				{
					UnityEngine.Object.Destroy(RightHandState.Indicator.gameObject);
				}
				RightHandState = null;
			}
			player.PlayerLocomotion.TeleportEvent -= OnPlayerTeleported;
			player.PlayerLocomotion.ResumeGravity(this);
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopFlyVignette(0f);
			}
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			if (LeftHandState == null)
			{
				LeftHandState = new HandState
				{
					Hand = leftHand,
					Input = leftInput
				};
			}
			else
			{
				LeftHandState.Hand = leftHand;
				LeftHandState.Input = leftInput;
			}
			if (RightHandState == null)
			{
				RightHandState = new HandState
				{
					Hand = rightHand,
					Input = rightInput
				};
			}
			else
			{
				RightHandState.Hand = rightHand;
				RightHandState.Input = rightInput;
			}
			if (LeftHandState.Indicator == null)
			{
				LeftHandState.Indicator = UnityEngine.Object.Instantiate(IndicatorPrefab, new Vector3(-0.02f, 0f, 0f), Quaternion.identity);
				LeftHandState.Indicator.transform.SetParent(player.LeftHand.transform, worldPositionStays: false);
			}
			if (RightHandState.Indicator == null)
			{
				RightHandState.Indicator = UnityEngine.Object.Instantiate(IndicatorPrefab, new Vector3(0.02f, 0f, 0f), Quaternion.identity);
				RightHandState.Indicator.transform.SetParent(player.RightHand.transform, worldPositionStays: false);
			}
			if (movementState.IsLeftInputConsumed && !LeftHandState.IsFullyCharged)
			{
				LeftHandState.Charge = 0f;
				StopAllCoroutines();
			}
			if (movementState.IsRightInputConsumed && !RightHandState.IsFullyCharged)
			{
				RightHandState.Charge = 0f;
				StopAllCoroutines();
			}
			if (LeftHandState.IsFullyCharged)
			{
				movementState.IsLeftInputConsumed = true;
			}
			if (RightHandState.IsFullyCharged)
			{
				movementState.IsRightInputConsumed = true;
			}
			bool flag = isFullyChargedThisFrame;
			bool flag2 = isFlyingThisFrame;
			HandleInput(player);
			if (flag2 != isFlyingThisFrame)
			{
				OnIsFlyingChange();
			}
			if (flag != isFullyChargedThisFrame)
			{
				OnIsFullyChargedChange(player);
			}
		}

		private void OnIsFlyingChange()
		{
			if (isFlyingThisFrame)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartFlyVignette(VignetteFadeInTime);
			}
			else
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopFlyVignette(VignetteFadeOutTime);
			}
		}

		private void OnIsFullyChargedChange(Player player)
		{
			if (isFullyChargedThisFrame)
			{
				player.PlayerLocomotion.PauseGravity(this);
			}
			else
			{
				player.PlayerLocomotion.ResumeGravity(this);
			}
		}

		private void HandleInput(Player player)
		{
			isFlyingThisFrame = false;
			isFullyChargedThisFrame = false;
			if (!(PlayerGameRoleManager.Instance != null) || !PlayerGameRoleManager.Instance.GetLocalPlayerRoleDefinition().CanFly.Value || player == null)
			{
				LeftHandState.Charge = 0f;
				RightHandState.Charge = 0f;
				return;
			}
			if (LeftHandState.Charge == 0f)
			{
				CheckForStartFlyingGesture(LeftHandState);
			}
			if (RightHandState.Charge == 0f)
			{
				CheckForStartFlyingGesture(RightHandState);
			}
			if ((!LeftHandState.IsFullyCharged && !RightHandState.IsFullyCharged) || player.PlayerLocomotion.MovementRestricted)
			{
				return;
			}
			isFullyChargedThisFrame = true;
			if (LeftHandState.IsFullyCharged && LeftHandState.Input.TeleportButtonPressed)
			{
				isFlyingThisFrame = true;
				PerformFlight(player, LeftHandState.Hand);
				return;
			}
			if (RightHandState.IsFullyCharged && RightHandState.Input.TeleportButtonPressed)
			{
				isFlyingThisFrame = true;
				PerformFlight(player, RightHandState.Hand);
				return;
			}
			relativeDistance = float.MaxValue;
			if (LeftHandState.IsFullyCharged)
			{
				CheckForStopFlyingGesture(player, LeftHandState, RightHandState);
			}
			if (RightHandState.IsFullyCharged)
			{
				CheckForStopFlyingGesture(player, RightHandState, LeftHandState);
			}
		}

		private void PerformFlight(Player player, PlayerHand hand)
		{
			float num = CalculateFlightSpeed(player, hand);
			Vector3 velocity = hand.transform.forward * num;
			player.PlayerLocomotion.Move(velocity, withCollision: false);
		}

		private float CalculateFlightSpeed(Player player, PlayerHand hand)
		{
			if (relativeDistance == float.MaxValue)
			{
				savedChestPosition = player.TrackingSpace.transform.InverseTransformPoint(player.Head.transform.position + HeadToChest);
			}
			Vector3 vector = player.TrackingSpace.transform.InverseTransformPoint(hand.transform.position);
			float magnitude = (vector - savedChestPosition).magnitude;
			relativeDistance = Mathf.Min(magnitude, relativeDistance);
			magnitude = Mathf.Clamp(magnitude - relativeDistance, 0f, MaxArmDistance);
			float f = Mathf.InverseLerp(0f, MaxArmDistance, magnitude);
			f = Mathf.Pow(f, SpeedCurveExponent);
			return Mathf.Lerp(MinFlightSpeed, MaxFlightSpeed, f);
		}

		private void CheckForStartFlyingGesture(HandState state)
		{
			if (state.Input == null || !state.Input.TeleportButtonDown)
			{
				return;
			}
			float num = Vector3.Angle(Vector3.up, state.Hand.transform.forward);
			if (num < StartGestureAngleLimit)
			{
				HandState handState = ((state != LeftHandState) ? LeftHandState : RightHandState);
				if (!handState.IsFullyCharged)
				{
					handState.Charge = 0f;
				}
				StopAllCoroutines();
				StartCoroutine(WaitForStartFlyingGestureCompleted(state));
			}
		}

		private IEnumerator WaitForStartFlyingGestureCompleted(HandState state)
		{
			float timeStart = UnityEngine.Time.realtimeSinceStartup;
			while (UnityEngine.Time.realtimeSinceStartup - timeStart < StartGestureDuration)
			{
				if (state.Input == null || !state.Input.TeleportButtonPressed)
				{
					state.Charge = 0f;
					yield break;
				}
				float angleFromUp = Vector3.Angle(Vector3.up, state.Hand.transform.forward);
				if (!(angleFromUp < StartGestureAngleLimit))
				{
					state.Charge = 0f;
					yield break;
				}
				state.Charge = Mathf.InverseLerp(timeStart, timeStart + StartGestureDuration, UnityEngine.Time.realtimeSinceStartup);
				yield return null;
			}
			state.Charge = 1f;
			relativeDistance = float.MaxValue;
			HandState otherState = ((state != LeftHandState) ? LeftHandState : RightHandState);
			otherState.Charge = 0f;
		}

		private void CheckForStopFlyingGesture(Player player, HandState state, HandState offHandState)
		{
			if (offHandState.Input != null && offHandState.Input.TeleportButtonDown)
			{
				state.Charge = 0f;
			}
		}
	}
	public class GripRotateVRMovementController : VRMovementController
	{
		private const float CONTINUOUS_ROTATION_VIGNETTE_FADE_IN_TIME = 0.05f;

		private const float CONTINUOUS_ROTATION_VIGNETTE_FADE_OUT_TIME = 0.1f;

		[SerializeField]
		private float InputStepSize = 7.5f;

		[SerializeField]
		private float OutputStepSize = 22.5f;

		[SerializeField]
		private float InputScalar = 2f;

		private bool isRotating;

		private Vector3 lastVector;

		private float currentRotationYaw;

		private float pendingRotationYaw;

		public override void OnEnterMode(Player player)
		{
			player.PlayerLocomotion.TeleportCanceled += OnTeleportCanceled;
		}

		public override void OnExitMode(Player player)
		{
			player.PlayerLocomotion.RelinquishRotationControl(this);
			player.PlayerLocomotion.TeleportCanceled -= OnTeleportCanceled;
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			if (movementState.IsEitherInputConsumed)
			{
				if (isRotating)
				{
					StopContinuousRotation(player);
				}
				return;
			}
			bool flag = false;
			if (leftInput != null && rightInput != null)
			{
				flag = leftInput.GripRotateButtonPressed && rightInput.GripRotateButtonPressed;
				if (SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode == VRMovementMode.TELEPORT || SingletonMonoBehaviour<SettingsManager>.Instance.ThumbstickWalk != ThumbstickWalkMode.OFF)
				{
					flag |= leftInput.AlternateGripRotateButtonPressed && rightInput.AlternateGripRotateButtonPressed;
				}
			}
			if (isRotating)
			{
				UpdateRunningState(player, leftInput, rightInput, flag);
			}
			else
			{
				UpdateNoneState(player, leftInput, rightInput, flag);
			}
			if (isRotating)
			{
				movementState.IsLeftInputConsumed = true;
				movementState.IsRightInputConsumed = true;
			}
			float yaw = pendingRotationYaw - currentRotationYaw;
			if (pendingRotationYaw != 0f && player.PlayerLocomotion.ApplyRotation(this, yaw))
			{
				currentRotationYaw = pendingRotationYaw;
				pendingRotationYaw = 0f;
			}
		}

		private void UpdateNoneState(Player player, VRInputHandler leftInput, VRInputHandler rightInput, bool buttonPressed)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ContinuousRotationMode != ContinuousRotationMode.DISABLED && player.PlayerLocomotion.RotationAllowed && !player.PlayerLocomotion.RotationBeingModified && buttonPressed && TryGetVector(leftInput, rightInput, out lastVector) && player.PlayerLocomotion.RequestRotationControl(this))
			{
				StartContinuousRotation();
				UpdateRunningState(player, leftInput, rightInput, buttonPressed);
			}
		}

		private void StartContinuousRotation()
		{
			currentRotationYaw = 0f;
			pendingRotationYaw = 0f;
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartContinuousRotationVignette(0.05f);
			isRotating = true;
		}

		private void StopContinuousRotation(Player player)
		{
			currentRotationYaw = 0f;
			pendingRotationYaw = 0f;
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopContinuousRotationVignette(0.1f);
			player.PlayerLocomotion.RelinquishRotationControl(this);
			isRotating = false;
		}

		private void UpdateRunningState(Player player, VRInputHandler leftInput, VRInputHandler rightInput, bool buttonPressed)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ContinuousRotationMode == ContinuousRotationMode.DISABLED || !buttonPressed || !TryGetVector(leftInput, rightInput, out var Vector))
			{
				StopContinuousRotation(player);
				return;
			}
			float num = lastVector.AngleSignedVector3(Vector);
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ContinuousRotationMode == ContinuousRotationMode.DISCRETE && Mathf.Abs(num) >= InputStepSize)
			{
				lastVector = Vector;
				pendingRotationYaw = currentRotationYaw + OutputStepSize * Mathf.Sign(num);
			}
			else if (SingletonMonoBehaviour<SettingsManager>.Instance.ContinuousRotationMode == ContinuousRotationMode.CONTINUOUS)
			{
				pendingRotationYaw = num * InputScalar;
			}
		}

		private bool TryGetVector(VRInputHandler leftInput, VRInputHandler rightInput, out Vector3 Vector)
		{
			Vector3 vector = Vector3.ProjectOnPlane(rightInput.WorldSpaceTrackedPosition - leftInput.WorldSpaceTrackedPosition, Vector3.up);
			if (vector.sqrMagnitude <= 0.01f)
			{
				Vector = Vector3.zero;
				return false;
			}
			Vector = Vector3.Cross(vector.normalized, Vector3.up);
			Vector = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformDirection(Vector).normalized;
			return true;
		}

		private void OnTeleportCanceled(Player player)
		{
			if (isRotating)
			{
				StopContinuousRotation(player);
			}
		}
	}
	public class PlayerCollisionDisplacementVRMovementController : VRMovementController
	{
		public enum WorldCollisionType
		{
			DISABLED,
			HEAD_ONLY,
			HEAD_AND_BODY
		}

		[Header("World Collision")]
		[SerializeField]
		private float collisionHeadRadius = 0.125f;

		private float lastWorldCollisionTime;

		private bool isCollidingWithWorld;

		private static Collider[] LocalPlayerOverlapColliders = new Collider[16];

		private static Collider[] LocalPlayerHeadOnlyColliders = new Collider[8];

		private static Collider[] LocalPlayerBodyAndHeadColliders = new Collider[8];

		private static TokenFlag disabledTokenFlag = new TokenFlag();

		private const float WORLD_COLLISION_COOLDOWN_TIME = 0.2f;

		private const float WORLD_COLLISION_VIGNETTE_FADE_IN_TIME = 0.02f;

		private const float WORLD_COLLISION_VIGNETTE_FADE_OUT_TIME = 0.1f;

		private static bool Enabled => !disabledTokenFlag.HasTokens;

		public static void SetEnabled(object token, bool enabled)
		{
			if (enabled)
			{
				disabledTokenFlag.Remove(token);
			}
			else
			{
				disabledTokenFlag.Add(token);
			}
		}

		public override void OnEnterMode(Player player)
		{
		}

		public override void OnExitMode(Player player)
		{
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopWorldCollisionVignette(0f);
			}
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			UpdateWorldCollision(player);
		}

		private void UpdateWorldCollision(Player player)
		{
			if (!Enabled)
			{
				return;
			}
			bool flag = isCollidingWithWorld;
			if (TryGetWorldCollisionDepenetration(player, out var depenetration))
			{
				isCollidingWithWorld = true;
				lastWorldCollisionTime = UnityEngine.Time.time;
				player.PlayerLocomotion.Move(depenetration / UnityEngine.Time.deltaTime);
			}
			else if (UnityEngine.Time.time - lastWorldCollisionTime >= 0.2f)
			{
				isCollidingWithWorld = false;
			}
			if (flag != isCollidingWithWorld && SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				if (isCollidingWithWorld)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartWorldCollisionVignette(0.02f);
				}
				else
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopWorldCollisionVignette(0.1f);
				}
			}
		}

		private bool TryGetWorldCollisionDepenetration(Player player, out Vector3 depenetration)
		{
			depenetration = Vector3.zero;
			Vector3 position = player.Head.transform.position;
			Vector3 vector = player.CurrentFloorPosition + Vector3.up * collisionHeadRadius;
			Vector3 vector2 = position - vector;
			if (vector2.sqrMagnitude > 0.0625f)
			{
				vector += Vector3.up * 0.25f;
				vector2 = position - vector;
			}
			Vector3 capsulePosition = vector + vector2 / 2f;
			float capsuleHeight = vector2.magnitude + 2f * collisionHeadRadius;
			int capsuleColliderOverlaps = CollisionDetection.GetCapsuleColliderOverlaps(vector, position, collisionHeadRadius, 67128320, CollisionDetection.CollidesWithMovementIgnoringPlayersAndEnemies, LocalPlayerOverlapColliders);
			if (capsuleColliderOverlaps <= 0)
			{
				return false;
			}
			int num = 0;
			int num2 = 0;
			for (int i = 0; i < capsuleColliderOverlaps; i++)
			{
				PlayerWorldCollisionConfig component = LocalPlayerOverlapColliders[i].gameObject.GetComponent<PlayerWorldCollisionConfig>();
				WorldCollisionType worldCollisionType = ((!(component != null)) ? WorldCollisionType.HEAD_ONLY : component.PlayerCollisionType);
				if (worldCollisionType == WorldCollisionType.HEAD_ONLY && num < LocalPlayerHeadOnlyColliders.Length)
				{
					LocalPlayerHeadOnlyColliders[num++] = LocalPlayerOverlapColliders[i];
				}
				else if (worldCollisionType == WorldCollisionType.HEAD_AND_BODY && num2 < LocalPlayerBodyAndHeadColliders.Length)
				{
					LocalPlayerBodyAndHeadColliders[num2++] = LocalPlayerOverlapColliders[i];
				}
			}
			Vector3 totalDepenetration = Vector3.zero;
			Vector3 totalDepenetration2 = Vector3.zero;
			float capsuleHeight2 = collisionHeadRadius * 2f;
			bool flag = false;
			flag |= CollisionDetection.TryGetCapsuleDepenetration(player.Head.transform.position, player.Head.transform.rotation, collisionHeadRadius, capsuleHeight2, num, LocalPlayerHeadOnlyColliders, out totalDepenetration);
			if (flag | CollisionDetection.TryGetCapsuleDepenetration(capsulePosition, Quaternion.identity, collisionHeadRadius, capsuleHeight, num2, LocalPlayerBodyAndHeadColliders, out totalDepenetration2))
			{
				depenetration = Vector3.ProjectOnPlane(totalDepenetration + totalDepenetration2, Vector3.up);
				return true;
			}
			return false;
		}
	}
	public class RemotePlayerMovementAudio : UnityEngine.MonoBehaviour
	{
	}
	public class SwipeRotateVRMovementController : VRMovementController
	{
		private enum SmoothRotationController
		{
			NONE,
			LEFT,
			RIGHT
		}

		private const float VIGNETTE_FADE_IN_TIME = 0.05f;

		private const float VIGNETTE_FADE_OUT_TIME = 0.075f;

		private static readonly string SNAP_ROTATE_TOKEN = "SNAP_ROTATE";

		private static readonly string SMOOTH_ROTATE_TOKEN = "SMOOTH_ROTATE";

		[SerializeField]
		private float inPlaceRotationSpeed = 540f;

		[SerializeField]
		private float maxSmoothRotationSpeed = 180f;

		private SmoothRotationController _currentSmoothRotateController;

		private float lastInPlaceRotationDirection = 1f;

		private float currentRotationYaw;

		private float pendingRotationYaw;

		private Coroutine snapRotateCoroutine;

		private float snapRotateDestinationAngle;

		private SmoothRotationController CurrentSmoothRotateController
		{
			get
			{
				return _currentSmoothRotateController;
			}
			set
			{
				SmoothRotationController currentSmoothRotateController = _currentSmoothRotateController;
				_currentSmoothRotateController = value;
				if (currentSmoothRotateController == SmoothRotationController.NONE && _currentSmoothRotateController != SmoothRotationController.NONE)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartSwipeRotateVignette(0.05f);
				}
				else if (currentSmoothRotateController != SmoothRotationController.NONE && _currentSmoothRotateController == SmoothRotationController.NONE)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSwipeRotateVignette(0.075f);
				}
			}
		}

		private bool SnapRotateRunning => snapRotateCoroutine != null;

		public override void OnEnterMode(Player player)
		{
			player.PlayerLocomotion.TeleportCanceled += OnTeleportCanceled;
		}

		public override void OnExitMode(Player player)
		{
			ClearSmoothRotation(player);
			ClearSnapRotation(player);
			player.PlayerLocomotion.TeleportCanceled -= OnTeleportCanceled;
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			bool flag = !movementState.IsLeftInputConsumed;
			bool flag2 = !movementState.IsRightInputConsumed;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateMode == SwipeRotateMode.SMOOTH)
			{
				UpdateSmoothRotation(player, leftInput, flag, rightInput, flag2);
				return;
			}
			if (flag)
			{
				UpdateHandSnapRotation(player, leftHand, leftInput);
			}
			if (flag2)
			{
				UpdateHandSnapRotation(player, rightHand, rightInput);
			}
		}

		private void UpdateSmoothRotation(Player player, VRInputHandler leftInput, bool leftInputEnabled, VRInputHandler rightInput, bool rightInputEnabled)
		{
			if (!TryRunSmoothRotate(player, leftInput, leftInputEnabled, rightInput, rightInputEnabled))
			{
				ClearSmoothRotation(player);
			}
		}

		private bool TryRunSmoothRotate(Player player, VRInputHandler leftInput, bool leftInputEnabled, VRInputHandler rightInput, bool rightInputEnabled)
		{
			if (SnapRotateRunning)
			{
				return false;
			}
			if (!player.PlayerLocomotion.RotationAllowed || player.PlayerLocomotion.TeleportRunning || !SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled)
			{
				return false;
			}
			float normalizedRotationVelocity = 0f;
			CurrentSmoothRotateController = GetSmoothRotationInput(CurrentSmoothRotateController, leftInput, leftInputEnabled, rightInput, rightInputEnabled, out normalizedRotationVelocity);
			if (CurrentSmoothRotateController != SmoothRotationController.NONE && normalizedRotationVelocity != 0f)
			{
				if (!player.PlayerLocomotion.RequestRotationControl(SMOOTH_ROTATE_TOKEN))
				{
					return false;
				}
				float yaw = normalizedRotationVelocity * maxSmoothRotationSpeed * UnityEngine.Time.deltaTime;
				player.PlayerLocomotion.ApplyRotation(SMOOTH_ROTATE_TOKEN, yaw);
				player.PlayerLocomotion.RelinquishRotationControl(SMOOTH_ROTATE_TOKEN);
			}
			return true;
		}

		private SmoothRotationController GetSmoothRotationInput(SmoothRotationController currentSmoothRotateController, VRInputHandler leftInput, bool leftInputEnabled, VRInputHandler rightInput, bool rightInputEnabled, out float normalizedRotationVelocity)
		{
			bool flag = leftInputEnabled && leftInput.SmoothSwipeRotateAxis != 0f;
			bool flag2 = rightInputEnabled && rightInput.SmoothSwipeRotateAxis != 0f;
			if (currentSmoothRotateController == SmoothRotationController.LEFT && flag)
			{
				normalizedRotationVelocity = leftInput.SmoothSwipeRotateAxis;
				return currentSmoothRotateController;
			}
			if (currentSmoothRotateController == SmoothRotationController.RIGHT && flag2)
			{
				normalizedRotationVelocity = rightInput.SmoothSwipeRotateAxis;
				return currentSmoothRotateController;
			}
			if (flag2)
			{
				normalizedRotationVelocity = rightInput.SmoothSwipeRotateAxis;
				return SmoothRotationController.RIGHT;
			}
			if (flag)
			{
				normalizedRotationVelocity = leftInput.SmoothSwipeRotateAxis;
				return SmoothRotationController.LEFT;
			}
			normalizedRotationVelocity = 0f;
			return SmoothRotationController.NONE;
		}

		private void UpdateHandSnapRotation(Player player, PlayerHand hand, VRInputHandler input)
		{
			if (input != null)
			{
				if (input.RotateLeftButtonDown)
				{
					SnapRotateLeft(hand);
				}
				else if (input.RotateRightButtonDown)
				{
					SnapRotateRight(hand);
				}
				else if (input.RotateDownButtonDown)
				{
					SnapRotate180(hand);
				}
			}
		}

		private float RotateInPlaceAngle(Player player)
		{
			float num = 0f;
			return SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateMode switch
			{
				SwipeRotateMode.SNAP_FORTY_FIVE_DEGREES => 45f, 
				_ => 90f, 
			};
		}

		public void SnapRotateLeft(PlayerHand hand)
		{
			Player thisPlayer = hand.ThisPlayer;
			float num = RotateInPlaceAngle(thisPlayer);
			if (TryRotateInPlace(thisPlayer, 0f - num, inPlaceRotationSpeed))
			{
				thisPlayer.PlayerAudio.OnInPlaceRotateLeft();
				thisPlayer.PlayerEvents.SwipeRotate(is180Turn: false);
				hand.Vibrate();
				lastInPlaceRotationDirection = 1f;
			}
		}

		public void SnapRotateRight(PlayerHand hand)
		{
			Player thisPlayer = hand.ThisPlayer;
			float angle = RotateInPlaceAngle(thisPlayer);
			if (TryRotateInPlace(thisPlayer, angle, inPlaceRotationSpeed))
			{
				thisPlayer.PlayerAudio.OnInPlaceRotateRight();
				thisPlayer.PlayerEvents.SwipeRotate(is180Turn: false);
				hand.Vibrate();
				lastInPlaceRotationDirection = -1f;
			}
		}

		public void SnapRotate180(PlayerHand hand)
		{
			Player thisPlayer = hand.ThisPlayer;
			if (TryRotateInPlace(thisPlayer, 180f * lastInPlaceRotationDirection, inPlaceRotationSpeed))
			{
				thisPlayer.PlayerAudio.OnInPlaceRotate180();
				thisPlayer.PlayerEvents.SwipeRotate(is180Turn: true);
				hand.Vibrate();
			}
		}

		public bool TryRotateInPlace(Player player, float angle, float speed)
		{
			if (!player.PlayerLocomotion.RotationAllowed || player.PlayerLocomotion.TeleportRunning || !SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled)
			{
				return false;
			}
			ClearSmoothRotation(player);
			float duration = Mathf.Abs(angle) / speed;
			if (player.LeftHand.HeldTool != null)
			{
				player.LeftHand.HeldTool.OnPlayerRotateInPlace(angle, duration);
			}
			if (player.RightHand.HeldTool != null)
			{
				player.RightHand.HeldTool.OnPlayerRotateInPlace(angle, duration);
			}
			RunSnapRotate(player, angle, duration);
			return true;
		}

		private void OnTeleportCanceled(Player player)
		{
			ClearSnapRotation(player);
		}

		private void ClearSmoothRotation(Player player)
		{
			CurrentSmoothRotateController = SmoothRotationController.NONE;
			player.PlayerLocomotion.RelinquishRotationControl(SMOOTH_ROTATE_TOKEN);
		}

		private void ClearSnapRotation(Player player)
		{
			if (SnapRotateRunning)
			{
				this.SafeStopCoroutine(snapRotateCoroutine);
				snapRotateCoroutine = null;
				snapRotateDestinationAngle = 0f;
				player.PlayerLocomotion.RelinquishRotationControl(SNAP_ROTATE_TOKEN);
			}
		}

		private void RunSnapRotate(Player player, float rotationAngle, float duration)
		{
			if (player.PlayerLocomotion.RequestRotationControl(SNAP_ROTATE_TOKEN))
			{
				float instantAngle = 0f;
				if (SnapRotateRunning)
				{
					instantAngle = snapRotateDestinationAngle;
					StopCoroutine(snapRotateCoroutine);
					snapRotateCoroutine = null;
				}
				snapRotateDestinationAngle = rotationAngle;
				snapRotateCoroutine = StartCoroutine(SnapRotateCoroutine(player, rotationAngle, duration, instantAngle));
			}
		}

		private IEnumerator SnapRotateCoroutine(Player player, float angle, float duration, float instantAngle)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartSwipeRotateVignette(0.05f);
			if (instantAngle != 0f)
			{
				pendingRotationYaw = instantAngle;
				while (pendingRotationYaw != 0f)
				{
					float instantaneousYaw = pendingRotationYaw - currentRotationYaw;
					if (player.PlayerLocomotion.ApplyRotation(SNAP_ROTATE_TOKEN, instantaneousYaw))
					{
						currentRotationYaw = pendingRotationYaw;
						pendingRotationYaw = 0f;
					}
					yield return null;
				}
			}
			currentRotationYaw = 0f;
			pendingRotationYaw = 0f;
			for (float timer = 0f; timer <= duration; timer += UnityEngine.Time.deltaTime)
			{
				float t = Mathf.Clamp01(timer / duration);
				pendingRotationYaw = Mathf.Lerp(0f, angle, t);
				float instantaneousYaw2 = pendingRotationYaw - currentRotationYaw;
				if (player.PlayerLocomotion.ApplyRotation(SNAP_ROTATE_TOKEN, instantaneousYaw2))
				{
					currentRotationYaw = pendingRotationYaw;
					pendingRotationYaw = 0f;
				}
				yield return null;
			}
			pendingRotationYaw = angle;
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSwipeRotateVignette(0.075f);
			snapRotateCoroutine = null;
			player.PlayerLocomotion.RelinquishRotationControl(SNAP_ROTATE_TOKEN);
		}
	}
	public class TeleportVRMovementController : VRMovementController
	{
		private enum TeleportState
		{
			RUNNING,
			NOT_RUNNING
		}

		private TeleportState leftHandTeleportState = TeleportState.NOT_RUNNING;

		private TeleportState rightHandTeleportState = TeleportState.NOT_RUNNING;

		public override void OnEnterMode(Player player)
		{
		}

		public override void OnExitMode(Player player)
		{
			if (player != null)
			{
				ResetTeleporter(player.LeftHand);
				ResetTeleporter(player.RightHand);
			}
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			UpdateHandTeleporter(player, leftHand, leftInput, rightHandTeleportState, ref leftHandTeleportState, ref movementState);
			UpdateHandTeleporter(player, rightHand, rightInput, leftHandTeleportState, ref rightHandTeleportState, ref movementState);
		}

		private void UpdateHandTeleporter(Player player, PlayerHand hand, VRInputHandler input, TeleportState otherHandState, ref TeleportState thisHandTeleportState, ref VRMovementControllerState movementState)
		{
			if (movementState.GetInputConsumed(input))
			{
				EnterState(hand, TeleportState.NOT_RUNNING, ref thisHandTeleportState);
				return;
			}
			if (thisHandTeleportState != TeleportState.NOT_RUNNING)
			{
				if (thisHandTeleportState != TeleportState.RUNNING)
				{
					return;
				}
			}
			else
			{
				if (otherHandState != TeleportState.NOT_RUNNING || !input.TeleportButtonDown || player.PlayerLocomotion.TeleportRunning)
				{
					return;
				}
				EnterState(hand, TeleportState.RUNNING, ref thisHandTeleportState);
			}
			if (hand == null || hand.PlayerHandRemote == null)
			{
				EnterState(hand, TeleportState.NOT_RUNNING, ref thisHandTeleportState);
				return;
			}
			if (!input.TeleportButtonPressed && !input.TeleportButtonUp)
			{
				EnterState(hand, TeleportState.NOT_RUNNING, ref thisHandTeleportState);
				return;
			}
			movementState.SetInputConsumed(input);
			hand.PlayerHandRemote.UpdateTeleportTargetParabolic(hand.transform.position, hand.transform.forward, hand.transform.up);
			if (input.TeleportButtonUp)
			{
				hand.PlayerHandRemote.TryToTeleport();
			}
		}

		private void EnterState(PlayerHand hand, TeleportState targetState, ref TeleportState teleportState)
		{
			if (teleportState != targetState)
			{
				teleportState = targetState;
				if (teleportState == TeleportState.NOT_RUNNING)
				{
					ResetTeleporter(hand);
				}
			}
		}

		private void ResetTeleporter(PlayerHand hand)
		{
			if (hand != null && hand.PlayerHandRemote != null)
			{
				hand.PlayerHandRemote.ResetTarget();
			}
		}
	}
	public abstract class VRMovementController : UnityEngine.MonoBehaviour
	{
		public abstract void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState);

		public abstract void OnEnterMode(Player player);

		public abstract void OnExitMode(Player player);
	}
}
public struct VRMovementControllerState
{
	public bool IsLeftInputConsumed;

	public bool IsRightInputConsumed;

	public bool IsEitherInputConsumed => IsLeftInputConsumed || IsRightInputConsumed;

	public bool GetInputConsumed(VRTrackedController.HandType handType)
	{
		return handType switch
		{
			VRTrackedController.HandType.LeftHand => IsLeftInputConsumed, 
			VRTrackedController.HandType.RightHand => IsRightInputConsumed, 
			_ => throw new ArgumentException("Unknown HandType: " + handType), 
		};
	}

	public bool GetInputConsumed(VRInputHandler input)
	{
		return GetInputConsumed(input.HandType);
	}

	public void SetHandConsumed(VRTrackedController.HandType handType, bool value = true)
	{
		switch (handType)
		{
		case VRTrackedController.HandType.LeftHand:
			IsLeftInputConsumed = value;
			break;
		case VRTrackedController.HandType.RightHand:
			IsRightInputConsumed = value;
			break;
		default:
			throw new ArgumentException("Unknown HandType: " + handType);
		}
	}

	public void SetInputConsumed(VRInputHandler controller, bool value = true)
	{
		SetHandConsumed(controller.HandType, value);
	}
}
namespace RecRoom.Players.Movement
{
	public class WalkVRMovementController : VRMovementController
	{
		private enum State
		{
			NOT_WALKING,
			AIM_WALKING,
			THUMBSTICK_WALKING,
			AIM_SPRINTING,
			THUMBSTICK_SPRINTING
		}

		[SerializeField]
		private float minSpeedHandAngle = 30f;

		[SerializeField]
		private float maxSpeedHandAngle = 80f;

		private State currentState;

		private float aimWalkStartTime;

		private const float AIM_SPRINT_MIN_DOUBLE_CLICK_DELAY = 0.08f;

		private const float AIM_SPRINT_MAX_DOUBLE_CLICK_DURATION = 0.33f;

		public static WalkHandMode Mode
		{
			get
			{
				if (RecRoomEditorPreferences.RunInDebugMode)
				{
					return WalkHandMode.LEFT_HAND_CONTROLS;
				}
				return SingletonMonoBehaviour<SettingsManager>.Instance.WalkingHandMode;
			}
		}

		public override void OnEnterMode(Player player)
		{
		}

		public override void OnExitMode(Player player)
		{
			if (player != null)
			{
				player.PlayerWalking.StopSprint();
				player.PlayerWalking.ClearWalkVelocityImmediate();
			}
		}

		public override void ProcessInput(Player player, PlayerHand leftHand, VRInputHandler leftInput, PlayerHand rightHand, VRInputHandler rightInput, ref VRMovementControllerState movementState)
		{
			PlayerHand activeHand = leftHand;
			VRInputHandler activeInput = leftInput;
			PlayerHand activeHand2 = leftHand;
			VRInputHandler activeInput2 = rightInput;
			if (Mode == WalkHandMode.RIGHT_HAND_CONTROLS)
			{
				activeHand = rightHand;
				activeInput = rightInput;
				activeHand2 = leftHand;
				activeInput2 = leftInput;
			}
			RunStateSetup(player);
			RunStateTransitions(player, activeHand, activeInput, movementState);
			RunStateUpdates(player, activeHand, activeInput, ref movementState);
			UpdateJump(player, activeHand2, activeInput2, ref movementState);
		}

		private void RunStateSetup(Player player)
		{
			Camera vrModeHmdCamera = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera;
			Vector3 vector = vrModeHmdCamera.transform.forward;
			float f = Vector3.Dot(vector, Vector3.up);
			float num = 0.999999f;
			if (Mathf.Abs(f) >= num)
			{
				float num2 = -1f * Mathf.Sign(f);
				vector = num2 * vrModeHmdCamera.transform.up;
			}
			player.PlayerWalking.CoordinateSpaceForward = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
		}

		private void RunStateTransitions(Player player, PlayerHand activeHand, VRInputHandler activeInput, VRMovementControllerState movementState)
		{
			if (!IsInputAllowed(player, activeHand, activeInput, movementState))
			{
				SetCurrentState(State.NOT_WALKING, player, activeHand, activeInput);
				return;
			}
			bool flag = activeInput.WalkAxis.sqrMagnitude > Mathf.Epsilon;
			switch (currentState)
			{
			case State.NOT_WALKING:
			{
				GetWalkModesEnabled(activeInput, out var aimWalkEnabled, out var thumbstickWalkEnabled);
				if (aimWalkEnabled && activeInput.TeleportButtonPressed)
				{
					SetCurrentState(State.AIM_WALKING, player, activeHand, activeInput);
				}
				else if (thumbstickWalkEnabled && flag)
				{
					SetCurrentState(State.THUMBSTICK_WALKING, player, activeHand, activeInput);
				}
				break;
			}
			case State.THUMBSTICK_WALKING:
				if (!flag)
				{
					SetCurrentState(State.NOT_WALKING, player, activeHand, activeInput);
				}
				else if (player.PlayerWalking.IsSprintEnabled && activeInput.SprintButtonDown)
				{
					SetCurrentState(State.THUMBSTICK_SPRINTING, player, activeHand, activeInput);
				}
				break;
			case State.THUMBSTICK_SPRINTING:
				if (!flag)
				{
					SetCurrentState(State.NOT_WALKING, player, activeHand, activeInput);
				}
				else if (!player.PlayerWalking.IsSprinting)
				{
					SetCurrentState(State.THUMBSTICK_WALKING, player, activeHand, activeInput);
				}
				break;
			case State.AIM_WALKING:
			{
				float num = UnityEngine.Time.time - aimWalkStartTime;
				if (player.PlayerWalking.IsSprintEnabled && num >= 0.08f && activeInput.TeleportButtonDown)
				{
					SetCurrentState(State.AIM_SPRINTING, player, activeHand, activeInput);
				}
				else if (num >= 0.33f && !activeInput.TeleportButtonPressed)
				{
					SetCurrentState(State.NOT_WALKING, player, activeHand, activeInput);
				}
				break;
			}
			case State.AIM_SPRINTING:
				if (!activeInput.TeleportButtonPressed)
				{
					SetCurrentState(State.NOT_WALKING, player, activeHand, activeInput);
				}
				else if (!player.PlayerWalking.IsSprinting)
				{
					SetCurrentState(State.AIM_WALKING, player, activeHand, activeInput);
				}
				break;
			}
		}

		private void UpdateJump(Player player, PlayerHand activeHand, VRInputHandler activeInput, ref VRMovementControllerState movementState)
		{
			if (IsInputAllowed(player, activeHand, activeInput, movementState))
			{
				if (CanClimb(player, !player.PlayerLocomotion.IsGrounded || activeInput.TeleportButtonDown))
				{
					player.PlayerLocomotion.Climb();
				}
				else if (player.PlayerWalking.CanJump && activeInput.TeleportButtonDown)
				{
					player.PlayerWalking.RequestJump();
				}
				else if (!player.PlayerLocomotion.IsGrounded && activeInput.TeleportButtonUp)
				{
					player.PlayerWalking.CutoffJump();
				}
			}
		}

		private bool IsInputAllowed(Player player, PlayerHand activeHand, VRInputHandler activeInput, VRMovementControllerState movementState)
		{
			if (!player.PlayerWalking.IsWalkEnabled)
			{
				return false;
			}
			if (activeHand == null || activeInput == null)
			{
				return false;
			}
			if (movementState.GetInputConsumed(activeInput))
			{
				return false;
			}
			if (SingletonMonoBehaviour<CameraFade>.Instance.IsFading)
			{
				return false;
			}
			return true;
		}

		private bool CanClimb(Player player, bool isJumping)
		{
			if (!player.PlayerLocomotion.CanClimb(out var climbType, out var climbableSurfaceWallNormal))
			{
				return false;
			}
			if (!isJumping && climbType != PlayerLocomotion.ClimbType.LADDER)
			{
				return false;
			}
			Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.forward;
			if (Vector3.Dot(forward, climbableSurfaceWallNormal) >= -0.3f)
			{
				return false;
			}
			return true;
		}

		private void RunStateUpdates(Player player, PlayerHand activeHand, VRInputHandler activeInput, ref VRMovementControllerState movementState)
		{
			bool flag = SingletonMonoBehaviour<SettingsManager>.Instance.ThumbstickWalk != ThumbstickWalkMode.OFF;
			switch (currentState)
			{
			case State.NOT_WALKING:
				player.PlayerWalking.UpdateWalkVelocity(Vector3.zero, 0f);
				break;
			case State.AIM_WALKING:
				if (activeInput.TeleportButtonPressed)
				{
					PerformAimWalk(player, activeHand);
				}
				else
				{
					player.PlayerWalking.UpdateWalkVelocity(Vector3.zero, 0f);
				}
				flag = true;
				break;
			case State.AIM_SPRINTING:
				PerformAimWalk(player, activeHand);
				flag = true;
				break;
			case State.THUMBSTICK_WALKING:
			case State.THUMBSTICK_SPRINTING:
				PerformThumbstickWalk(player, activeInput);
				break;
			}
			if (flag)
			{
				movementState.SetInputConsumed(activeInput);
			}
		}

		private void SetCurrentState(State state, Player player, PlayerHand activeHand, VRInputHandler activeInput)
		{
			if (currentState != state)
			{
				OnExitState(currentState, player, activeHand, activeInput);
				currentState = state;
				OnEnterState(state, player, activeHand, activeInput);
			}
		}

		private void OnEnterState(State state, Player player, PlayerHand activeHand, VRInputHandler activeInput)
		{
			switch (state)
			{
			case State.AIM_WALKING:
				aimWalkStartTime = UnityEngine.Time.time;
				break;
			case State.AIM_SPRINTING:
			case State.THUMBSTICK_SPRINTING:
				if (player != null && player.PlayerWalking != null)
				{
					player.PlayerWalking.RequestSprint();
				}
				break;
			}
		}

		private void OnExitState(State state, Player player, PlayerHand activeHand, VRInputHandler activeInput)
		{
			if ((state == State.AIM_SPRINTING || state == State.THUMBSTICK_SPRINTING) && player != null && player.PlayerWalking != null)
			{
				player.PlayerWalking.StopSprint();
			}
		}

		private void GetWalkModesEnabled(VRInputHandler input, out bool aimWalkEnabled, out bool thumbstickWalkEnabled)
		{
			if (!input.IsAimWalkCapable)
			{
				aimWalkEnabled = false;
				thumbstickWalkEnabled = true;
			}
			else
			{
				thumbstickWalkEnabled = SingletonMonoBehaviour<SettingsManager>.Instance.ThumbstickWalk != ThumbstickWalkMode.OFF;
				aimWalkEnabled = !thumbstickWalkEnabled || input.SimultaneouslySupportsAimAndThumbstickWalk;
			}
		}

		private void PerformAimWalk(Player player, PlayerHand hand)
		{
			Vector3 normalizedDesiredDirection = Vector3.Normalize(new Vector3(hand.transform.forward.x, 0f, hand.transform.forward.z));
			float num = Mathf.Abs(Vector3.Angle(hand.transform.forward, -Vector3.up));
			if (num >= 90f)
			{
				num = 180f - num;
			}
			float normalizedDesiredSpeed = Mathf.InverseLerp(minSpeedHandAngle, maxSpeedHandAngle, num);
			player.PlayerWalking.UpdateWalkVelocity(normalizedDesiredDirection, normalizedDesiredSpeed);
		}

		private void PerformThumbstickWalk(Player player, VRInputHandler controller)
		{
			Vector2 walkAxis = controller.WalkAxis;
			float magnitude = walkAxis.magnitude;
			GetThumbstickCoordinateSpace(controller, out var forward, out var right);
			Vector3 normalized = (right * walkAxis.x + forward * walkAxis.y).normalized;
			player.PlayerWalking.UpdateWalkVelocity(normalized, magnitude);
		}

		private void GetThumbstickCoordinateSpace(VRInputHandler controller, out Vector3 forward, out Vector3 right)
		{
			Vector3 forward2 = Vector3.forward;
			Vector3 up = Vector3.up;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ThumbstickWalk == ThumbstickWalkMode.HEAD_RELATIVE)
			{
				forward2 = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.forward;
				up = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.up;
			}
			else
			{
				forward2 = controller.WorldSpaceTrackedRotation * Vector3.forward;
				up = controller.WorldSpaceTrackedRotation * Vector3.up;
			}
			float f = Vector3.Dot(forward2, Vector3.up);
			forward = ((!(Mathf.Abs(f) >= 0.999f)) ? forward2 : (-1f * Mathf.Sign(f) * up));
			forward = Vector3.ProjectOnPlane(forward, Vector3.up).normalized;
			right = Vector3.Cross(Vector3.up, forward).normalized;
		}
	}
}
