public class CustomKOEffect : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float delayTimeBeforeThrob = 0.5f;

	private ThrobbingUIElement throbbingUI;

	private ParticleSystem[] allParticleSystems;

	private Animator animator;

	private Coroutine StartThrobbingUICoroutine;

	public UnityEngine.UI.Image Sprite { get; private set; }

	private void Awake()
	{
		Sprite = GetComponentInChildren<UnityEngine.UI.Image>(includeInactive: true);
		throbbingUI = GetComponentInChildren<ThrobbingUIElement>(includeInactive: true);
		allParticleSystems = GetComponentsInChildren<ParticleSystem>(includeInactive: true);
		animator = GetComponentInChildren<Animator>(includeInactive: true);
	}

	private void OnEnable()
	{
		if (throbbingUI != null)
		{
			if (animator != null)
			{
				throbbingUI.Active = false;
				if (StartThrobbingUICoroutine != null)
				{
					StopCoroutine(StartThrobbingUICoroutine);
				}
				StartThrobbingUICoroutine = StartCoroutine(WaitForAnimatorAndStartThrob());
			}
			else
			{
				throbbingUI.Active = true;
			}
		}
		if (allParticleSystems != null)
		{
			for (int i = 0; i < allParticleSystems.Length; i++)
			{
				allParticleSystems[i].Play();
			}
		}
	}

	private IEnumerator WaitForAnimatorAndStartThrob()
	{
		yield return null;
		while (animator.GetCurrentAnimatorStateInfo(0).normalizedTime < 1f)
		{
			yield return null;
		}
		yield return new WaitForSeconds(delayTimeBeforeThrob);
		throbbingUI.Active = true;
		StartThrobbingUICoroutine = null;
	}

	private void OnDisable()
	{
		if (throbbingUI != null)
		{
			throbbingUI.Active = false;
		}
		if (allParticleSystems != null)
		{
			for (int i = 0; i < allParticleSystems.Length; i++)
			{
				allParticleSystems[i].Stop();
			}
		}
	}
}
public class PersonalMuteZone : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private BoxCollider boxCollider;

	private Player thisPlayer;

	private Vector3 boxSize = Vector3.one;

	[Tooltip("Delay before mute is active, this is to filter out quick swipe of hand in front of face without meaning to mute.")]
	[SerializeField]
	private float muteDelay = 1f;

	private float inMuteZoneDuration;

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		boxSize = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
		base.enabled = thisPlayer.isLocal;
	}

	private void Update()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.AlwaysOn || SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode || !SingletonMonoBehaviour<SettingsManager>.Instance.MuteWithHandEnabled || !Player.LocalPlayerExists)
		{
			return;
		}
		bool flag = false;
		Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
		Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
		int num = Physics.OverlapBoxNonAlloc(center, boxSize, iMMEDIATE_COLLIDER_HITS, boxCollider.transform.rotation, 1049088);
		for (int i = 0; i < num; i++)
		{
			if (flag)
			{
				break;
			}
			flag |= IsHandInMuteZone(iMMEDIATE_COLLIDER_HITS[i]);
		}
		if (flag)
		{
			inMuteZoneDuration += UnityEngine.Time.deltaTime;
			if (!Player.LocalPlayer.MutedBy(Player.MuteFlags.GESTURE_MUTE) && inMuteZoneDuration >= muteDelay)
			{
				Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.GESTURE_MUTE);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Muted", 1.5f);
			}
		}
		else
		{
			inMuteZoneDuration = 0f;
			if (Player.LocalPlayer.MutedBy(Player.MuteFlags.GESTURE_MUTE))
			{
				Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.GESTURE_MUTE, enabled: false);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Unmuted", 1.5f);
			}
		}
	}

	private bool IsHandInMuteZone(Collider col)
	{
		Player.BodyPart bodyPart;
		Player colliderPlayer = col.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null && colliderPlayer.isLocal && bodyPart.IsHand())
		{
			PlayerHand hand = colliderPlayer.GetHand(bodyPart);
			if (hand != null && hand.DefaultHandVisualsActive)
			{
				return true;
			}
		}
		return false;
	}
}
