	public event Action<bool> VisibilityChanged
	{
		add
		{
			Action<bool> action = this.m_VisibilityChanged;
			Action<bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_VisibilityChanged, (Action<bool>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<bool> action = this.m_VisibilityChanged;
			Action<bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_VisibilityChanged, (Action<bool>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

