	private IEnumerator Start()
	{
		if (isLocal && VOIPFilter != SingletonMonoBehaviour<SettingsManager>.Instance.VoiceFilter)
		{
			VOIPFilter = SingletonMonoBehaviour<SettingsManager>.Instance.VoiceFilter;
		}
		else
		{
			OnVOIPFilterChanged();
		}
		if (isLocal)
		{
			RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomUpdated);
			OnLocalRoomUpdated();
			bool flag = SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR;
			GameObject[] array = hideInFirstPerson;
			foreach (GameObject gameObject in array)
			{
				if (gameObject.GetComponentInChildren<Collider>() != null)
				{
					UnityEngine.Debug.LogError("Hidable object has a collider.  Its layer will be changed to hidden in first person.");
				}
				if (flag)
				{
					CreateFirstPersonShadowCaster(gameObject);
				}
				gameObject.SetLayerRecursively(Layers.HiddenInFirstPerson);
			}
			base.name += "_local";
			Renderer[] array2 = blobShadowRenderers;
			foreach (Renderer renderer in array2)
			{
				BlobShadowProjector.AddShadowCaster(renderer);
			}
			SingletonMonoBehaviour<CameraRig>.Instance.SetTransform(base.transform.position, base.transform.rotation);
			SingletonMonoBehaviour<CameraRig>.Instance.SetForcedHeight();
			CameraStartPoint.UpdateChaperonePosition();
			AnimateInOut.SuppressAnimation = true;
			SpawnLocal();
			LocalUpdatePing();
			SetMuteFlag(MuteFlags.VOICE_TYPE_MUTE, SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.Mute);
			SetMuteFlag(MuteFlags.PTT_MUTE, SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.PushToTalk);
			IgnoreBuffer = SingletonMonoBehaviour<SettingsManager>.Instance.IgnoreBuffer;
			DisablePersonalBubbleForFriends = SingletonMonoBehaviour<SettingsManager>.Instance.DisablePersonalBubbleForFriends;
		}
		else
		{
			Relationships.RelationshipUpdated += OnRelationshipUpdated;
			OnRelationshipUpdated(PlayerId);
			if (!DynamicUpdateManager.Instance.IsGroupRegistered("Player"))
			{
				int[] array3 = new int[6];
				array3[0] = 3;
				array3[5] = 3;
				array3[4] = 3;
				array3[1] = int.MaxValue;
				array3[2] = int.MaxValue;
				array3[3] = int.MaxValue;
				DynamicUpdateManager.Instance.RegisterGroup("Player", 100f, callWhenDisabled: true, array3);
			}
			leftHandAnimator = leftHand.GetComponentInChildren<Animator>(includeInactive: true);
			leftHandRenderer = leftHand.GetComponentInChildren<Renderer>(includeInactive: true);
			rightHandAnimator = rightHand.GetComponentInChildren<Animator>(includeInactive: true);
			rightHandRenderer = rightHand.GetComponentInChildren<Renderer>(includeInactive: true);
			headAnimator = head.GetComponent<Animator>();
			headRenderer = head.GetComponentInChildren<Renderer>(includeInactive: true);
			DynamicUpdateManager.Instance.RegisterObject("Player", this, DynamicUpdateManager.DefaultCostFunction(IsVisibleForAnimations, GetPlayerPositionTransform), DynamicUpdate);
		}
		OnUserIsPresentChanged();
		OnMuteFlagsUpdated();
		OnIgnoreBufferChanged();
		IsInitialized = true;
		if (isLocal)
		{
			SavedVoiceChatSettings = SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat;
		}
		if (PlayerCreatedEvent != null)
		{
			PlayerCreatedEvent.Invoke(this);
		}
		if (isLocal && LocalPlayerCreatedEvent != null)
		{
			LocalPlayerCreatedEvent.Invoke();
		}
		if (isLocal)
		{
			ProcessPlayerEventNotifications();
		}
		yield break;
	}

