			relationship = Relationships.Get(PlayerId);
			if (relationship != null)
			{
				flag = relationship.Ignored != Relationship.ReciprocalStatus.None || relationship.Muted == Relationship.ReciprocalStatus.Local || relationship.Muted == Relationship.ReciprocalStatus.Mutual;
				IgnoredStatus = relationship.Ignored;
			}
			SetMuteFlag(MuteFlags.RELATIONSHIP_MUTE, flag);
		}
	}

