	private void Update()
	{
		bool flag = isLocal;
		if (flag)
		{
			TestLocalPlayerWorldBounds();
			TestKillzones();
			if (UnityEngine.Time.time - lastUpdateGroundPositionTime >= 0.5f)
			{
				UpdateLastValidGroundPosition();
			}
		}
		FacialAnimator.Talking = IsTalking;
		voiceObject.transform.position = head.transform.position;
		voiceObject.transform.rotation = head.transform.rotation;
		if (flag && UnityEngine.Time.time >= nextPingUpdateTime)
		{
			LocalUpdatePing();
		}
	}

	private void LateUpdate()
	{
		UpdateIdentityPosition();
	}

	public void EnableOutOfBoundsCheck(bool enable)
	{
		isOutOfBoundsCheckEnabled = enable;
	}

	private void UpdateIdentityPosition()
	{
		if (!isLocal)
		{
			playerIdentity.transform.position = head.transform.position;
			return;
		}
		Vector3 up = Vector3.up;
		Vector3 normalized = Vector3.ProjectOnPlane(head.transform.forward, up).normalized;
		Vector3 normalized2 = Vector3.ProjectOnPlane(head.transform.right, up).normalized;
		Vector3 vector = normalized2 * localIdentityOffset.x + up * localIdentityOffset.y + normalized * localIdentityOffset.z;
		playerIdentity.transform.position = head.RigidbodyEx.physicsPosition + vector;
	}

	private void LocalUpdatePing()
	{
		if (isLocal)
		{
			Ping = SingletonMonoBehaviour<DebugGuiManager>.Instance.PerformanceCounters.RoundTripTime;
			nextPingUpdateTime = UnityEngine.Time.time + pingUpdateInterval;
		}
	}

