	private void TestLocalPlayerWorldBounds()
	{
		bool flag = isOutOfBoundsCheckEnabled;
		bool flag2 = false;
		if (flag && GameSessions.LocalGameSession.Location != RoomSceneLocations.PSVR_ROOM_CALIBRATION && !GameSessions.LocalGameSession.IsSandbox && !PlayerLocomotion.IsTeleporting && !IsSpawning)
		{
			flag2 = RunOutOfBoundsTestInternal();
		}
		switch (outOfBoundsState)
		{
		case OutOfBoundsState.IN_BOUNDS:
			if (flag2)
			{
				lastLeftBoundsTime = UnityEngine.Time.time;
				outOfBoundsState = OutOfBoundsState.OUT_OF_BOUNDS_GRACE_PERIOD;
			}
			break;
		case OutOfBoundsState.OUT_OF_BOUNDS_GRACE_PERIOD:
			if (!flag2)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
				outOfBoundsState = OutOfBoundsState.IN_BOUNDS;
			}
			else if (UnityEngine.Time.time - lastLeftBoundsTime >= 1f)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Out of bounds!", 2f);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.AddPersistentNotification("Walk back to the play area", this);
				outOfBoundsState = OutOfBoundsState.OUT_OF_BOUNDS;
			}
			break;
		case OutOfBoundsState.OUT_OF_BOUNDS:
			if (!flag2)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
				outOfBoundsState = OutOfBoundsState.IN_BOUNDS;
			}
			break;
		}
	}

	private bool RunOutOfBoundsTestInternal()
	{
		return Head.IsOutOfWorldBounds;
	}

	private void TestKillzones()
	{
		bool flag = inKillzone;
		killzone = GetKillzone();
		inKillzone = killzone != null;
		if (!flag && inKillzone && LocalPlayerEnteredKillzoneEvent != null)
		{
			LocalPlayerEnteredKillzoneEvent.Invoke(killzone);
		}
	}

	private Killzone GetKillzone()
	{
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
		{
			return null;
		}
		if (!PlayerLocomotion.MovementIsInitialized)
		{
			return null;
		}
		int layerMask = 524288;
		Vector3 latestCapsuleFootPosition = Vector3.zero;
		if (!PlayerLocomotion.TryGetLatestCapsuleFootPosition(out latestCapsuleFootPosition))
		{
			return null;
		}
		Collider sphereColliderOverlap = CollisionDetection.GetSphereColliderOverlap(latestCapsuleFootPosition, PlayerLocomotion.CapsuleRadius, layerMask, null, QueryTriggerInteraction.Collide);
		if (sphereColliderOverlap == null)
		{
			return null;
		}
		Killzone component = sphereColliderOverlap.GetComponent<Killzone>();
		if (component == null)
		{
			return null;
		}
		if (!component.RespawnsPlayers)
		{
			return null;
		}
		return component;
	}

