	public void UpdateAFKStatus(bool userIsPresent)
	{
		if (!isRoomOwner && !PhotonNetwork.offlineMode && PhotonNetwork.inRoom && RecRoomSceneManager.Instance != null && !SessionManager.InDormRoom && !SessionManager.InRoomCalibration && !SessionManager.InPrivateSession)
		{
			float num = UnityEngine.Time.unscaledTime - lastAFKActiveTime;
			UserIsPresent = userIsPresent;
			if (userIsPresent)
			{
				lastAFKActiveTime = UnityEngine.Time.unscaledTime;
				currentAfkCoundown = -1;
			}
			else if (num > AfkKickToIntroTimeout)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom(afkIntroMessage, SessionManager.LoadSceneSources.AFK);
				AnalyticsHelper.UserAFK(num);
				lastAFKActiveTime = UnityEngine.Time.unscaledTime;
			}
			else if (num > AfkWarningStartTimeout)
			{
				int num2 = Mathf.CeilToInt(AfkKickToIntroTimeout - num);
				if (currentAfkCoundown != num2)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, afkWarningMessageTitle, afkWarningMessageSubTitle + num2, 2f, null, updateIfSameStyle: true);
					currentAfkCoundown = num2;
				}
			}
		}
		else
		{
			lastAFKActiveTime = UnityEngine.Time.unscaledTime;
			currentAfkCoundown = -1;
		}
	}

	public void ProcessPlayerEventNotifications()
	{
		if (PlayerUI.WatchMenu == null)
		{
			StartCoroutine(WaitForWatchAndReprocessPlayerEvents());
		}
		else
		{
			if (SingletonMonoBehaviour<PlayerEventNotificationManager>.Instance.UnprocessedNotifications.Count <= 0)
			{
				return;
			}
			PlayerEventNotificationManager.PlayerEventInfo currentEvent = SingletonMonoBehaviour<PlayerEventNotificationManager>.Instance.UnprocessedNotifications.Dequeue();
			AnalyticsHelper.PlayerCreatedEventNotification(currentEvent.Name, currentEvent.PlayerEventId);
			PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Upcoming Event", $"The event {currentEvent.Name} is starting now! Would you like to join?", "Go!", "Dismiss").Then(delegate(ConfirmDialogResponses r)
			{
				if (r == ConfirmDialogResponses.Affirmative)
				{
					AnalyticsHelper.PlayerCreatedEventNotification_GoToRoom(currentEvent.Name, currentEvent.PlayerEventId);
					StartCoroutine(JoinPlayerEvent(currentEvent.PlayerEventId, SessionManager.LoadSceneSources.EVENT_NOTIFICATION));
				}
				else
				{
					ProcessPlayerEventNotifications();
				}
			});
		}
	}

	private IEnumerator WaitForWatchAndReprocessPlayerEvents()
	{
		while (PlayerUI.WatchMenu == null || IsSpawning)
		{
			yield return null;
		}
		yield return null;
		ProcessPlayerEventNotifications();
	}

	private IEnumerator JoinPlayerEvent(long playerEventId, SessionManager.LoadSceneSources joinSource)
	{
		yield return RecNet.PlayerEvents.GetPlayerEventById(playerEventId).Then(delegate(PlayerEvent playerEvent)
		{
			if (playerEvent != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunGoToPlayerEvent(playerEvent, joinSource);
			}
			else if (this != null)
			{
				PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Event Unavailable", "This event couldn't be joined. Please try again later.").Then((Action)delegate
				{
					ProcessPlayerEventNotifications();
				});
			}
		});
	}

