	public bool TryDisarm(Tool tool)
	{
		bool result = false;
		if (tool != null && tool.IsHeld && tool.hasAuthority && tool.Owner == this)
		{
			Vector3 normalized = Vector3.ProjectOnPlane(Head.transform.forward, Vector3.up).normalized;
			Vector3 normalized2 = Vector3.Cross(Vector3.up, normalized).normalized;
			float angle = UnityEngine.Random.Range(-20f, 20f);
			float angle2 = UnityEngine.Random.Range(-20f, 20f);
			normalized = Quaternion.AngleAxis(angle2, normalized2) * Quaternion.AngleAxis(angle, Vector3.up) * normalized;
			tool.HolderInfo = ToolHolderInfo.NotHeld;
			tool.RigidbodyEx.AddForce(normalized * 4f, ForceMode.VelocityChange);
			lastDisarmTime = UnityEngine.Time.time;
			result = true;
		}
		return result;
	}

