	public void Respawn(Vector3 parentRelativePosition, Quaternion parentRelativeRotation, PhotonView parentPhotonView, bool dropTools = true, Tool leftHandSpawnTool = null, string leftHandSkinId = null, Tool rightHandSpawnTool = null, string rightHandSkinId = null, Tool leftHipSpawnTool = null, string leftHipSkinId = null, Tool rightHipSpawnTool = null, string rightHipSkinId = null, Tool shoulderSpawnTool = null, string shoulderSkinId = null, bool requestGiftSpawn = false)
	{
		RespawnCoroutine = StartCoroutine(RespawnLocal(parentRelativePosition, parentRelativeRotation, parentPhotonView, dropTools, leftHandSpawnTool, leftHandSkinId, rightHandSpawnTool, rightHandSkinId, leftHipSpawnTool, leftHipSkinId, rightHipSpawnTool, rightHipSkinId, shoulderSpawnTool, shoulderSkinId, requestGiftSpawn));
