	public Coroutine SpawnLocal()
	{
		if (!isLocal)
		{
			UnityEngine.Debug.LogError("Player.SpawnLocal() can only be called on the LocalPlayer!");
		}
		isSpawned = true;
		PlayerLocomotion.OnPlayerSpawn();
		base.photonView.RpcOthers(RpcBroadcastSpawnPlayer);
		PhotonNetwork.SendOutgoingCommands();
		if (PlayerSpawnEvent != null)
		{
			PlayerSpawnEvent.Invoke(this);
		}
		if (LocalPlayerSpawnEvent != null)
		{
			LocalPlayerSpawnEvent.Invoke();
		}
		SingletonMonoBehaviour<SessionManager>.Instance.LocalPlayerSpawned();
		return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: true);
	}

	public Coroutine DespawnLocal(bool prepForLevelSwitch, bool dropTools = true)
	{
		if (!isLocal)
		{
			UnityEngine.Debug.LogError("Player.DespawnLocal() can only be called on the LocalPlayer!");
		}
		if (!isSpawned)
		{
			return StartCoroutine(WaitForCameraFadeCoroutine());
		}
		PlayerLocomotion.OnPlayerDespawn();
		isSpawned = false;
		if (dropTools)
		{
			ReleaseToolsFromBothHands();
			ReleaseToolsFromAllEquipSlots();
		}
		else
		{
			LockToolsInBothHandsOnRespawn(localLocked: true);
		}
		base.photonView.RpcOthers(RpcBroadcastDespawnPlayer);
		PhotonNetwork.SendOutgoingCommands();
		SingletonMonoBehaviour<SessionManager>.Instance.LocalPlayerDespawned();
		return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: false, prepForLevelSwitch);
	}

	private IEnumerator WaitForCameraFadeCoroutine()
	{
		float startTime = UnityEngine.Time.time;
		yield return new WaitWhile(() => SingletonMonoBehaviour<CameraFade>.Instance.IsFading && UnityEngine.Time.time - startTime <= 3f);
	}

	private void LockToolsInBothHandsOnRespawn(bool localLocked)
	{
		LeftHand.LocalLockHeldToolOnRespawn(localLocked);
		RightHand.LocalLockHeldToolOnRespawn(localLocked);
	}

	public IEnumerator RespawnLocal(Vector3 parentRelativePosition, Quaternion parentRelativeRotation, PhotonView parentPhotonView, bool dropTools, Tool leftHandSpawnTool, string leftHandToolSkinId, Tool rightHandSpawnTool, string rightHandToolSkinId, Tool leftHipSpawnTool, string leftHipToolSkinId, Tool rightHipSpawnTool, string rightHipToolSkinId, Tool shoulderSpawnTool, string shoulderToolSkinId, bool requestGiftSpawn)
	{
		yield return DespawnLocal(prepForLevelSwitch: false, dropTools);
		PlayerLocomotion.CoordinateSpace spawnRotationCoordinateSpace = PlayerLocomotion.CoordinateSpace.PLAYER_SPACE;
		RigidbodyEx parentRigidbodyEx = ((!(parentPhotonView != null)) ? null : parentPhotonView.GetComponent<RigidbodyEx>());
		Vector3 worldPosition = parentRelativePosition;
		Quaternion worldRotation = parentRelativeRotation;
		if (parentRigidbodyEx != null)
		{
			TrackingSpace.RigidbodyEx.parent = parentRigidbodyEx;
			worldPosition = parentRigidbodyEx.TargetTransform.TransformPoint(parentRelativePosition);
			worldRotation = parentRigidbodyEx.TargetTransform.TransformRotation(parentRelativeRotation);
		}
		PlayerLocomotion.MoveTo(worldPosition, worldRotation * Vector3.forward, insertDiscontinuity: true, spawnRotationCoordinateSpace, forceSetHeight: true);
		LastSpawnPosition = worldPosition;
		LastSpawnRotation = worldRotation;
		yield return SpawnLocal();
		if (!dropTools)
		{
			LockToolsInBothHandsOnRespawn(localLocked: false);
		}
		LocalPickupSpawnTool(LeftHand, leftHandSpawnTool, leftHandToolSkinId);
		LocalPickupSpawnTool(RightHand, rightHandSpawnTool, rightHandToolSkinId);
		EquipSpawnTool(ToolEquipSlots.LeftHipSlot, leftHipSpawnTool, leftHipToolSkinId);
		EquipSpawnTool(ToolEquipSlots.RightHipSlot, rightHipSpawnTool, rightHipToolSkinId);
		EquipSpawnTool(ToolEquipSlots.ShoulderSlot, shoulderSpawnTool, shoulderToolSkinId);
		if (requestGiftSpawn)
		{
			SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(Avatars.GiftPackages, useSpawnLocation: true, dismissExistingGift: false);
		}
		RespawnCoroutine = null;
	}

	private void LocalPickupSpawnTool(PlayerHand hand, Tool spawnTool, string skinId)
	{
		if (!isLocal || hand == null || spawnTool == null)
		{
			return;
		}
		if (hand.IsHoldingTool)
		{
			hand.HeldTool.HolderInfo = ToolHolderInfo.NotHeld;
		}
		if (!SingletonMonoBehaviour<LocalPlayerController>.Instance.TryPickupSpawnTool(this, hand, spawnTool))
		{
			return;
		}
		spawnTool.IsLocked = true;
		if (!(spawnTool.SkinMapper == null))
		{
			if (!string.IsNullOrEmpty(skinId))
			{
				spawnTool.SkinMapper.LocalApplySkin(skinId);
			}
			spawnTool.SkinMapper.LocalApplyFavoriteSkin();
		}
	}

	private void EquipSpawnTool(PlayerToolEquipSlot equipSlot, Tool spawnTool, string skinId)
	{
		if (equipSlot == null || spawnTool == null)
		{
			return;
		}
		if (equipSlot.EquippedTool != null)
		{
			equipSlot.DropTool();
		}
		if (ToolEquipSlots.TryEquipTool(spawnTool, null, equipSlot) && !(spawnTool.SkinMapper == null))
		{
			if (!string.IsNullOrEmpty(skinId))
			{
				spawnTool.SkinMapper.LocalApplySkin(skinId);
			}
			spawnTool.SkinMapper.LocalApplyFavoriteSkin();
		}
	}

