	public bool IsOverValidGround(out Vector3 groundPosition)
	{
		if (!inKillzone && CollisionDetection.IsSphereOverColliderPlayerCanStandOn(Head.RigidbodyEx.targetPosition, 0.1f, 3f, out var hit) && !IsOverDynamicTool(hit.collider))
		{
			groundPosition = hit.point;
			return true;
		}
		groundPosition = Vector3.zero;
		return false;
	}

	private bool IsOverDynamicTool(Collider collider)
	{
		if (collider == null)
		{
			return false;
		}
		Tool colliderTool = collider.GetColliderTool();
		if (colliderTool == null)
		{
			return false;
		}
		return !colliderTool.IsFrozen;
	}

