	public static Player FindClosest(Vector3 position, List<PhotonPlayer> playersToSearch = null)
	{
		Player result = null;
		float num = float.MaxValue;
		PhotonPlayer[] array = ((playersToSearch == null) ? PhotonNetwork.playerList : playersToSearch.ToArray());
		PhotonPlayer[] array2 = array;
		foreach (PhotonPlayer photonPlayer in array2)
		{
			if (photonPlayer == null)
			{
				continue;
			}
			Player player = photonPlayer.ToPlayer();
			if (!(player == null))
			{
				float sqrMagnitude = (player.Head.transform.position - position).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					result = player;
					num = sqrMagnitude;
				}
			}
		}
		return result;
	}

