	public static bool IsCloseToAnyPlayer(Vector3 position, float distance = 2f)
	{
		if (distance <= Mathf.Epsilon)
		{
			return false;
		}
		float num = distance * distance;
		foreach (Player item in All)
		{
			if (item != null && item.IsVisible && (position - item.CurrentFloorPosition).sqrMagnitude <= num)
			{
				return true;
			}
		}
		return false;
	}

	public static float DistanceSqrBetweenPlayers(Player lhs, Player rhs)
	{
		if (lhs == null || rhs == null)
		{
			return float.MaxValue;
		}
		return Vector3.ProjectOnPlane(lhs.Head.transform.position - rhs.Head.transform.position, Vector3.up).sqrMagnitude;
	}

	public static GameObject CreateFirstPersonShadowCaster(GameObject sourceObject)
	{
		GameObject result = null;
		SkinnedMeshRenderer componentInChildren = sourceObject.GetComponentInChildren<SkinnedMeshRenderer>();
		if (componentInChildren != null)
		{
			SkinnedMeshRenderer skinnedMeshRenderer = CreateFirstPersonShadowCasterForSkinnedMeshRenderer(componentInChildren);
			if (skinnedMeshRenderer != null)
			{
				result = skinnedMeshRenderer.gameObject;
			}
		}
		else
		{
			MeshRenderer componentInChildren2 = sourceObject.GetComponentInChildren<MeshRenderer>();
			if (componentInChildren2 != null)
			{
				MeshRenderer meshRenderer = CreateFirstPersonShadowCasterForMeshRenderer(componentInChildren2);
				if (meshRenderer != null)
				{
					result = meshRenderer.gameObject;
				}
			}
		}
		return result;
	}

	public static Renderer CreateFirstPersonShadowCaster(Renderer sourceRenderer)
	{
		Renderer result = null;
		if (sourceRenderer is SkinnedMeshRenderer)
		{
			result = CreateFirstPersonShadowCasterForSkinnedMeshRenderer((SkinnedMeshRenderer)sourceRenderer);
		}
		else if (sourceRenderer is MeshRenderer)
		{
			result = CreateFirstPersonShadowCasterForMeshRenderer((MeshRenderer)sourceRenderer);
		}
		return result;
	}

	public static MeshRenderer CreateFirstPersonShadowCasterForMeshRenderer(MeshRenderer renderer)
	{
		if (renderer != null && renderer.shadowCastingMode != ShadowCastingMode.Off)
		{
			MeshFilter component = renderer.GetComponent<MeshFilter>();
			if (component != null)
			{
				GameObject gameObject = CreateFirstPersonShadowCasterHelper(renderer.gameObject);
				MeshFilter meshFilter = gameObject.AddComponent<MeshFilter>();
				meshFilter.sharedMesh = component.sharedMesh;
				MeshRenderer meshRenderer = gameObject.AddComponent<MeshRenderer>();
				meshRenderer.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
				meshRenderer.sharedMaterials = renderer.sharedMaterials;
				return meshRenderer;
			}
		}
		return null;
	}

	public static SkinnedMeshRenderer CreateFirstPersonShadowCasterForSkinnedMeshRenderer(SkinnedMeshRenderer skinnedMeshRenderer)
	{
		if ((bool)skinnedMeshRenderer && skinnedMeshRenderer.shadowCastingMode != ShadowCastingMode.Off)
		{
			GameObject gameObject = CreateFirstPersonShadowCasterHelper(skinnedMeshRenderer.gameObject);
			SkinnedMeshRenderer skinnedMeshRenderer2 = gameObject.AddComponent<SkinnedMeshRenderer>();
			skinnedMeshRenderer2.shadowCastingMode = ShadowCastingMode.ShadowsOnly;
			skinnedMeshRenderer2.sharedMesh = skinnedMeshRenderer.sharedMesh;
			skinnedMeshRenderer2.bones = skinnedMeshRenderer.bones;
			skinnedMeshRenderer2.rootBone = skinnedMeshRenderer.rootBone;
			skinnedMeshRenderer2.materials = skinnedMeshRenderer.materials;
			skinnedMeshRenderer2.quality = skinnedMeshRenderer.quality;
			skinnedMeshRenderer2.updateWhenOffscreen = skinnedMeshRenderer.updateWhenOffscreen;
			skinnedMeshRenderer2.skinnedMotionVectors = skinnedMeshRenderer.skinnedMotionVectors;
			skinnedMeshRenderer2.localBounds = skinnedMeshRenderer.localBounds;
			if (skinnedMeshRenderer.sharedMesh != null)
			{
				for (int i = 0; i < skinnedMeshRenderer.sharedMesh.blendShapeCount; i++)
				{
					skinnedMeshRenderer2.SetBlendShapeWeight(i, skinnedMeshRenderer.GetBlendShapeWeight(i));
				}
			}
			return skinnedMeshRenderer2;
		}
		return null;
	}

	private static GameObject CreateFirstPersonShadowCasterHelper(GameObject gameObject)
	{
		GameObject gameObject2 = new GameObject();
		gameObject2.name = $"{gameObject.name} (FirstPersonShadowCaster)";
		gameObject2.transform.SetParent(gameObject.transform);
		gameObject2.transform.localPosition = Vector3.zero;
		gameObject2.transform.localRotation = Quaternion.identity;
		gameObject2.transform.localScale = Vector3.one;
		gameObject2.layer = 29;
		gameObject2.tag = "LayerIsLocked";
		return gameObject2;
	}

	public void OnChangedDistanceBand(UpdateLOD oldDistanceBand, UpdateLOD newDistanceBand)
	{
		MyUpdateLod = newDistanceBand;
		RecalculateMinOtherPlayerUpdateLOD();
		if (OnDistanceBandChanged != null)
		{
			OnDistanceBandChanged(this, oldDistanceBand, newDistanceBand);
		}
	}

	private static void RecalculateMinOtherPlayerUpdateLOD()
	{
		MinOtherPlayerUpdateLOD = UpdateLOD.Invalid;
		if (!LocalPlayerExists || All.Count == 1)
		{
			return;
		}
		for (int i = 0; i < All.Count && !(All[i] == LocalPlayer); i++)
		{
			UpdateLOD myUpdateLod = All[i].MyUpdateLod;
			if (myUpdateLod <= MinOtherPlayerUpdateLOD)
			{
				MinOtherPlayerUpdateLOD = myUpdateLod;
			}
		}
	}
}
public class PlayerAfterImageParticles : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private ParticleSystem[] particleSystems;

	[SerializeField]
	private float speed = 5f;

	[SerializeField]
	private float emissionRate = 100f;

	[SerializeField]
	private Color defaultColor = new Color(0.45f, 0.45f, 0.45f, 1f);

	public Color Color
	{
		set
		{
			ParticleSystem[] array = particleSystems;
			foreach (ParticleSystem particleSystem in array)
			{
				ParticleSystem.MainModule main = particleSystem.main;
				main.startColor = value;
			}
		}
	}

	public void Run(Vector3 origin, Vector3 destination)
	{
		base.transform.position = origin;
		Vector3 vector = destination - origin;
		base.transform.rotation = Quaternion.LookRotation(-vector.normalized);
		float num = vector.magnitude / speed;
		ParticleSystem[] array = particleSystems;
		foreach (ParticleSystem particleSystem in array)
		{
			ParticleSystem.MainModule main = particleSystem.main;
			main.startLifetime = num;
			main.startSpeed = speed;
			particleSystem.Play();
		}
		UnityEngine.Object.Destroy(base.gameObject, num);
	}

	private void Awake()
	{
		ParticleSystem[] array = particleSystems;
		foreach (ParticleSystem particleSystem in array)
		{
			ParticleSystem.EmissionModule emission = particleSystem.emission;
			emission.rateOverTime = new ParticleSystem.MinMaxCurve
			{
				constantMax = emissionRate
			};
		}
		Color = defaultColor;
	}
}
namespace RecRoom.Players
{
	public sealed class PlayerBody : UnityEngine.MonoBehaviour
	{
		private enum AnimatorState
		{
			Uninitialized,
			Normal,
			Walking
		}

		private const int QUALITY_CHECK_FREQUENCY_HZ = 3;

		[Comment("Although PlayerBody itself is not synchronized, we need a PhotonView component on the player's torso so that sticky objects can attach to the torso properly.")]
		[Header("References")]
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private VisibleInCamera visibleInCamera;

		[SerializeField]
		private Collider bodyCollider;

		[SerializeField]
		private Rigidbody bodyRigidbody;

		[SerializeField]
		private Transform toolEquipSlotsRoot;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private PhotonView _photonView;

		[Header("Orientation")]
		[SerializeField]
		private float bodyWeightFollowTime = 0.2f;

		[SerializeField]
		private float neckHorizontalOffset = -0.05f;

		[SerializeField]
		private float neckVerticalOffset = -0.1f;

		[Header("Clamping")]
		[SerializeField]
		private float minPitch = -30f;

		[SerializeField]
		private float maxPitch = 30f;

		[SerializeField]
		private float minYaw = -30f;

		[SerializeField]
		private float maxYaw = 30f;

		[Header("Forward Clamping")]
		[SerializeField]
		private float maxForwardYaw = 60f;

		[Header("Broken Neck Compensation")]
		[SerializeField]
		private float minBrokenNeckDetectionAngle = 45f;

		[SerializeField]
		private float minBrokenNeckCompensationAngle = 35f;

		[Header("Animation")]
		[SerializeField]
		private Animator headWalkAnimator;

		[SerializeField]
		private float WalkingAnimationMultiplier = 1.2f;

		[Header("Quality")]
		[SerializeField]
		private float maxHighQualityDistance = 50f;

		private static readonly int SpeedParameterID = Animator.StringToHash("Speed");

		[NonSerialized]
		public bool AlignWithGravity;

		private bool highQualityUpdates;

		private float maxHighQualitySqDistance;

		private Transform clampSpaceTransform;

		private float bodyHeadOffset = 1f;

		private Vector3 bodyWeightPointTrackingSpace;

		private Vector3 bodyWeightVelocity = Vector3.zero;

		private Vector3 bodyWeightForwardVelocity = Vector3.zero;

		private bool _visible = true;

		private AnimatorState _currentAnimatorState;

		public PhotonView PhotonView => _photonView;

		public Player Player { get; private set; }

		public Rigidbody Rigidbody => bodyRigidbody;

		public Collider BodyCollider => bodyCollider;

		public bool Visible
		{
			get
			{
				return _visible;
			}
			set
			{
				if (value != _visible)
				{
					_visible = value;
					base.gameObject.SetActive(_visible);
				}
			}
		}

		public Vector3 HeightOffset => Vector3.Project(base.transform.position - Player.CurrentFloorPosition, Vector3.up);

		private AnimatorState CurrentAnimatorState
		{
			get
			{
				return _currentAnimatorState;
			}
			set
			{
				if (value != _currentAnimatorState)
				{
					_currentAnimatorState = value;
					switch (_currentAnimatorState)
					{
					case AnimatorState.Normal:
						headWalkAnimator.enabled = false;
						break;
					case AnimatorState.Walking:
						headWalkAnimator.enabled = true;
						break;
					}
				}
			}
		}

		private void Awake()
		{
			GameObject gameObject = new GameObject("Body Clamp Space");
			gameObject.transform.SetParent(base.transform.parent);
			clampSpaceTransform = gameObject.transform;
			Player = GetComponentInParent<Player>();
			Vector3 neckPositionTrackingSpace = GetNeckPositionTrackingSpace();
			Vector3 vector = Player.TrackingSpace.transform.InverseTransformPoint(base.transform.position);
			bodyHeadOffset = (vector - neckPositionTrackingSpace).magnitude;
			bodyWeightPointTrackingSpace = neckPositionTrackingSpace - Vector3.up * bodyHeadOffset;
			maxHighQualitySqDistance = maxHighQualityDistance * maxHighQualityDistance;
			CurrentAnimatorState = AnimatorState.Normal;
		}

		private void Start()
		{
			this.LateUpdateAtRate(3f, StaggeredLateUpdate);
		}

		private void LateUpdate()
		{
			UpdateAnimatorState(highQualityUpdates);
			UpdatePosition(highQualityUpdates);
		}

		private void StaggeredLateUpdate(float deltaTime)
		{
			highQualityUpdates = ShouldUseHighQualityUpdates();
		}

		private void UpdateAnimatorState(bool highQuality)
		{
			if (highQuality)
			{
				float normalizedSpeed = Player.PlayerWalking.NormalizedSpeed;
				if (normalizedSpeed >= Mathf.Epsilon)
				{
					CurrentAnimatorState = AnimatorState.Walking;
					float value = Mathf.Clamp01(WalkingAnimationMultiplier * normalizedSpeed);
					headWalkAnimator.SetFloat(SpeedParameterID, value);
				}
				else
				{
					CurrentAnimatorState = AnimatorState.Normal;
				}
			}
			else
			{
				CurrentAnimatorState = AnimatorState.Normal;
			}
		}

		private void UpdatePosition(bool highQuality)
		{
			Vector3 neckPositionTrackingSpace = GetNeckPositionTrackingSpace();
			Vector3 vector;
			if (highQuality)
			{
				GetTargetBodyVectors(neckPositionTrackingSpace, out var targetBodyWeightPointTS, out var targetBodyForwardTS, out var brokenNeck);
				bodyWeightPointTrackingSpace = Vector3.SmoothDamp(bodyWeightPointTrackingSpace, targetBodyWeightPointTS, ref bodyWeightVelocity, bodyWeightFollowTime);
				Vector3 current = Player.TrackingSpace.transform.InverseTransformDirection(base.transform.forward);
				vector = Vector3.SmoothDamp(current, targetBodyForwardTS, ref bodyWeightForwardVelocity, bodyWeightFollowTime);
				if (!brokenNeck)
				{
					vector = ClampBodyForward(vector);
					if (!AlignWithGravity)
					{
						bodyWeightPointTrackingSpace = ClampBodyWeightPosition(neckPositionTrackingSpace, bodyWeightPointTrackingSpace);
					}
				}
			}
			else
			{
				vector = ((!TryGetProjectedVector(Player.Head.transform.forward, Vector3.up, out var projectedVector)) ? Player.TrackingSpace.transform.InverseTransformDirection(base.transform.forward) : Player.TrackingSpace.transform.InverseTransformDirection(projectedVector));
				bodyWeightPointTrackingSpace = GetDefaultBodyWeightTrackingSpacePoint(neckPositionTrackingSpace);
			}
			GetWorldSpaceBodyPositionRotation(neckPositionTrackingSpace, bodyWeightPointTrackingSpace, vector, out var position, out var rotation);
			base.transform.SetPositionAndRotation(position, rotation);
			toolEquipSlotsRoot.SetPositionAndRotation(position, rotation);
		}

		private void GetWorldSpaceBodyPositionRotation(Vector3 neckPositionTS, Vector3 bodyPointTS, Vector3 forwardTS, out Vector3 position, out Quaternion rotation)
		{
			Vector3 normalized = (neckPositionTS - bodyPointTS).normalized;
			Vector3 lhs = Vector3.Cross(normalized, forwardTS);
			forwardTS = Vector3.Cross(lhs, normalized);
			Vector3 position2 = neckPositionTS - normalized * bodyHeadOffset;
			position = Player.TrackingSpace.transform.TransformPoint(position2);
			Quaternion rotation2 = Quaternion.LookRotation(forwardTS, normalized);
			rotation = Player.TrackingSpace.transform.TransformRotation(rotation2);
		}

		private void GetTargetBodyVectors(Vector3 neckPositionTS, out Vector3 targetBodyWeightPointTS, out Vector3 targetBodyForwardTS, out bool brokenNeck)
		{
			brokenNeck = false;
			Vector3 defaultBodyWeightTrackingSpacePoint = GetDefaultBodyWeightTrackingSpacePoint(neckPositionTS);
			Vector3 vector = Player.TrackingSpace.transform.InverseTransformDirection(headWalkAnimator.transform.up);
			Vector3 vector2 = Player.TrackingSpace.transform.InverseTransformDirection(headWalkAnimator.transform.forward);
			Quaternion.FromToRotation(-Vector3.up, -vector).ToAngleAxis(out var angle, out var axis);
			if (AlignWithGravity || angle < minBrokenNeckDetectionAngle)
			{
				targetBodyWeightPointTS = defaultBodyWeightTrackingSpacePoint;
				targetBodyForwardTS = Vector3.ProjectOnPlane(vector2, Vector3.up).normalized;
				return;
			}
			float angle2 = angle - minBrokenNeckCompensationAngle;
			Vector3 vector3 = Quaternion.AngleAxis(angle2, axis) * -Vector3.up;
			targetBodyWeightPointTS = neckPositionTS + vector3 * bodyHeadOffset;
			targetBodyForwardTS = vector2;
			brokenNeck = true;
		}

		private Vector3 GetNeckPositionTrackingSpace()
		{
			Vector3 vector = Player.TrackingSpace.transform.InverseTransformDirection(headWalkAnimator.transform.forward);
			Vector3 vector2 = Player.TrackingSpace.transform.InverseTransformDirection(headWalkAnimator.transform.up);
			Vector3 vector3 = Player.TrackingSpace.transform.InverseTransformPoint(headWalkAnimator.transform.position);
			return vector3 + vector * neckHorizontalOffset + vector2 * neckVerticalOffset;
		}

		private Vector3 GetDefaultBodyWeightTrackingSpacePoint(Vector3 neckPositionTS)
		{
			return neckPositionTS - Vector3.up * bodyHeadOffset;
		}

		private Vector3 ClampBodyWeightPosition(Vector3 neckPositionTrackingSpace, Vector3 bodyWeightPointTS)
		{
			clampSpaceTransform.position = Player.TrackingSpace.transform.TransformPoint(neckPositionTrackingSpace);
			Vector3 vector = Player.TrackingSpace.transform.InverseTransformDirection(headWalkAnimator.transform.forward);
			Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
			Quaternion rotation = Quaternion.LookRotation(Vector3.up, normalized);
			clampSpaceTransform.rotation = Player.TrackingSpace.transform.TransformRotation(rotation);
			Vector3 position = Player.TrackingSpace.transform.TransformPoint(bodyWeightPointTS);
			Vector3 cartesionPoint = clampSpaceTransform.InverseTransformPoint(position);
			MathExt.CartesianPointToSphericalDegrees(cartesionPoint, out var pitchDegrees, out var yawDegrees, out var radius);
			float pitchDegrees2 = Mathf.Clamp(pitchDegrees, minPitch, maxPitch);
			float yawDegrees2 = Mathf.Clamp(yawDegrees, minYaw, maxYaw);
			Vector3 position2 = MathExt.SphericalPointDegreestoCartesian(pitchDegrees2, yawDegrees2, radius);
			Vector3 position3 = clampSpaceTransform.TransformPoint(position2);
			return Player.TrackingSpace.transform.InverseTransformPoint(position3);
		}

		private Vector3 ClampBodyForward(Vector3 bodyForwardTS)
		{
			Vector3 vector = Player.TrackingSpace.transform.InverseTransformDirection(Player.Head.transform.forward);
			if (!TryGetProjectedVector(vector, Vector3.up, out var projectedVector))
			{
				return bodyForwardTS;
			}
			if (!TryGetProjectedVector(bodyForwardTS, Vector3.up, out var projectedVector2))
			{
				return bodyForwardTS;
			}
			float value = Vector3.SignedAngle(projectedVector, projectedVector2, Vector3.up);
			float angle = Mathf.Clamp(value, -1f * maxForwardYaw, maxForwardYaw);
			Quaternion quaternion = Quaternion.AngleAxis(angle, Vector3.up);
			return quaternion * projectedVector;
		}

		private bool ShouldUseHighQualityUpdates()
		{
			if (Player.isLocal)
			{
				return true;
			}
			bool flag = true;
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				float num = Vector3.SqrMagnitude(base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position);
				if (num > maxHighQualitySqDistance)
				{
					flag = false;
				}
			}
			if (flag)
			{
				flag = visibleInCamera.IsVisible;
			}
			return flag;
		}

		private bool TryGetProjectedVector(Vector3 vector, Vector3 projectionPlaneNormal, out Vector3 projectedVector)
		{
			if (Mathf.Abs(Vector3.Dot(vector, projectionPlaneNormal)) < 1f)
			{
				projectedVector = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				return true;
			}
			projectedVector = Vector3.zero;
			return false;
		}
	}
}
public class PlayerChaperone : UnityEngine.MonoBehaviour
{
	public enum ChaperoneMode
	{
		None = -1,
		SteamVR,
		Oculus,
		MicrosoftVR
	}

	private delegate void CornerAssignmentCallback(Vector3[] corners);

	[SerializeField]
	private float lineThickness = 0.1f;

	[SerializeField]
	private Material material;

	[SerializeField]
	private MeshRenderer chaperoneBoundsRenderer;

	[SerializeField]
	private MeshRenderer chaperoneCenterRenderer;

	[SerializeField]
	private float centerRaycastDistance = 0.2f;

	private MeshFilter chaperoneMeshFilter;

	private Vector3[] vertices;

	private Player thisPlayer;

	[NonSerialized]
	public bool RoomCenterVisualEnabled = true;

	private static ChaperoneMode? _currentChaperoneMode = null;

	private static RaycastHit[] chaperoneCenterRaycastResults = new RaycastHit[20];

	private HmdQuad_t playSpaceBounds = default(HmdQuad_t);

	public bool ShowCurrentBounds { get; set; }

	public static ChaperoneMode CurrentChaperoneMode
	{
		get
		{
			ChaperoneMode? currentChaperoneMode = _currentChaperoneMode;
			if (!currentChaperoneMode.HasValue)
			{
				_currentChaperoneMode = ChaperoneMode.Oculus;
			}
			return _currentChaperoneMode.Value;
		}
	}

	private void Awake()
	{
		thisPlayer = GetComponentInParent<Player>();
		chaperoneMeshFilter = chaperoneBoundsRenderer.gameObject.GetComponent<MeshFilter>();
		if (thisPlayer == null || !thisPlayer.isLocal)
		{
			base.gameObject.SetActive(value: false);
		}
		else if (CurrentChaperoneMode == ChaperoneMode.None)
		{
			chaperoneBoundsRenderer.gameObject.SetActive(value: false);
		}
	}

	private void Update()
	{
		if (RoomCenterVisualEnabled && SingletonMonoBehaviour<SettingsManager>.Instance.ShowRoomCenter)
		{
			Vector3 origin = base.transform.position + Vector3.up * centerRaycastDistance / 2f;
			int num = Physics.RaycastNonAlloc(origin, -Vector3.up, chaperoneCenterRaycastResults, centerRaycastDistance, 2048);
			if (num > 0)
			{
				Array.Sort(chaperoneCenterRaycastResults, (RaycastHit a, RaycastHit b) => b.point.y.CompareTo(a.point.y));
				chaperoneCenterRenderer.transform.position = chaperoneCenterRaycastResults[0].point;
			}
			else
			{
				chaperoneCenterRenderer.transform.position = base.transform.position;
			}
			chaperoneCenterRenderer.gameObject.SetActive(value: true);
		}
		else
		{
			chaperoneCenterRenderer.gameObject.SetActive(value: false);
		}
	}

	private void OnEnable()
	{
		if (UnityEngine.Application.isPlaying)
		{
			StartCoroutine(BuildMesh());
		}
	}

	private IEnumerator BuildMesh()
	{
		chaperoneMeshFilter.mesh = null;
		Vector3[] borderCorners = null;
		switch (CurrentChaperoneMode)
		{
		case ChaperoneMode.SteamVR:
			yield return GetBoundsSteamVR(delegate(Vector3[] c)
			{
				borderCorners = c;
			});
			break;
		case ChaperoneMode.Oculus:
			yield return GetBoundsOculus(delegate(Vector3[] c)
			{
				borderCorners = c;
			});
			break;
		}
		if (borderCorners != null)
		{
			BuildBorderMesh(borderCorners);
		}
	}

	private IEnumerator GetBoundsSteamVR(CornerAssignmentCallback assignCorners)
	{
		CVRChaperone chaperone = OpenVR.Chaperone;
		if (chaperone == null)
		{
			assignCorners(null);
			yield break;
		}
		while (chaperone.GetCalibrationState() != ChaperoneCalibrationState.OK)
		{
			yield return null;
		}
		bool initOpenVR = !SteamVR.active && !SteamVR.usingNativeSupport;
		if (initOpenVR)
		{
			EVRInitError peError = EVRInitError.None;
			OpenVR.Init(ref peError, EVRApplicationType.VRApplication_Other);
		}
		HmdQuad_t pRect = default(HmdQuad_t);
		bool success = chaperone?.GetPlayAreaRect(ref pRect) ?? false;
		if (initOpenVR)
		{
			OpenVR.Shutdown();
		}
		if (!success)
		{
			UnityEngine.Debug.LogWarning("Failed to get Calibrated Play Area bounds!  Make sure you have tracking first, and that your space is calibrated.");
			assignCorners(null);
			yield break;
		}
		assignCorners(new Vector3[4]
		{
			new Vector3(pRect.vCorners0.v0, pRect.vCorners0.v1, pRect.vCorners0.v2),
			new Vector3(pRect.vCorners1.v0, pRect.vCorners1.v1, pRect.vCorners1.v2),
			new Vector3(pRect.vCorners2.v0, pRect.vCorners2.v1, pRect.vCorners2.v2),
			new Vector3(pRect.vCorners3.v0, pRect.vCorners3.v1, pRect.vCorners3.v2)
		});
	}

	private IEnumerator GetBoundsOculus(CornerAssignmentCallback assignCorners)
	{
		OVRBoundary boundary = OVRManager.boundary;
		if (boundary == null || !boundary.GetConfigured())
		{
			assignCorners(null);
		}
		else
		{
			assignCorners(GetBoundaryBordersOculus(boundary));
		}
		yield break;
	}

	private Vector3[] GetBoundaryBordersOculus(OVRBoundary boundary)
	{
		Vector3 dimensions = boundary.GetDimensions(OVRBoundary.BoundaryType.PlayArea);
		return new Vector3[4]
		{
			new Vector3((0f - dimensions.x) / 2f, dimensions.y, (0f - dimensions.z) / 2f),
			new Vector3(dimensions.x / 2f, dimensions.y, (0f - dimensions.z) / 2f),
			new Vector3(dimensions.x / 2f, dimensions.y, dimensions.z / 2f),
			new Vector3((0f - dimensions.x) / 2f, dimensions.y, dimensions.z / 2f)
		};
	}

	private void BuildBorderMesh(Vector3[] borderCorners)
	{
		vertices = new Vector3[borderCorners.Length * 2];
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < borderCorners.Length; i++)
		{
			Vector3 vector = borderCorners[i];
			ref Vector3 reference = ref vertices[i];
			reference = new Vector3(vector.x, 0.01f, vector.z);
			zero += vertices[i];
		}
		zero /= (float)borderCorners.Length;
		chaperoneCenterRenderer.transform.localPosition = zero;
		if (lineThickness == 0f)
		{
			chaperoneMeshFilter.mesh = null;
			return;
		}
		for (int j = 0; j < borderCorners.Length; j++)
		{
			int num = (j + 1) % borderCorners.Length;
			int num2 = (j + borderCorners.Length - 1) % borderCorners.Length;
			Vector3 normalized = (vertices[num] - vertices[j]).normalized;
			Vector3 normalized2 = (vertices[num2] - vertices[j]).normalized;
			Vector3 vector2 = vertices[j];
			vector2 += Vector3.Cross(normalized, Vector3.up) * lineThickness;
			vector2 += Vector3.Cross(normalized2, Vector3.down) * lineThickness;
			vertices[borderCorners.Length + j] = vector2;
		}
		int[] triangles = new int[24]
		{
			7, 4, 0, 7, 0, 3, 6, 7, 3, 6,
			3, 2, 5, 6, 2, 5, 2, 1, 4, 5,
			1, 4, 1, 0
		};
		Vector2[] uv = new Vector2[8]
		{
			new Vector2(0f, 0f),
			new Vector2(1f, 0f),
			new Vector2(0f, 0f),
			new Vector2(1f, 0f),
			new Vector2(0f, 1f),
			new Vector2(1f, 1f),
			new Vector2(0f, 1f),
			new Vector2(1f, 1f)
		};
		Mesh mesh = new Mesh();
		chaperoneMeshFilter.mesh = mesh;
		mesh.vertices = vertices;
		mesh.uv = uv;
		mesh.triangles = triangles;
		if (material != null)
		{
			chaperoneBoundsRenderer.material = material;
		}
		else
		{
			chaperoneBoundsRenderer.material = Resources.GetBuiltinResource<Material>("Sprites-Default.mat");
		}
	}

	public bool IsInBounds()
	{
		bool result = false;
		switch (CurrentChaperoneMode)
		{
		case ChaperoneMode.Oculus:
			result = IsInBoundsOculus();
			break;
		case ChaperoneMode.SteamVR:
			result = IsInBoundsSteamVR();
			break;
		case ChaperoneMode.MicrosoftVR:
			result = true;
			break;
		}
		return result;
	}

	private bool IsInBoundsOculus()
	{
		OVRBoundary boundary = OVRManager.boundary;
		if (boundary != null && boundary.GetConfigured())
		{
			Vector3[] boundaryBordersOculus = GetBoundaryBordersOculus(boundary);
			for (int i = 0; i < boundaryBordersOculus.Length; i++)
			{
				ref Vector3 reference = ref boundaryBordersOculus[i];
				reference = HmdVector3ToHeadSpace(boundaryBordersOculus[i]);
			}
			return IsInConvexPolygon(thisPlayer.Head.transform.position, boundaryBordersOculus);
		}
		return false;
	}

	private bool IsInBoundsSteamVR()
	{
		CVRChaperone chaperone = OpenVR.Chaperone;
		if (chaperone != null && chaperone.GetCalibrationState() == ChaperoneCalibrationState.OK)
		{
			if (!chaperone.GetPlayAreaRect(ref playSpaceBounds))
			{
				return false;
			}
			Vector3[] polygon = new Vector3[4]
			{
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners0),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners1),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners2),
				HmdVector3ToHeadSpace(playSpaceBounds.vCorners3)
			};
			return IsInConvexPolygon(thisPlayer.Head.transform.position, polygon);
		}
		return false;
	}

	private Vector3 HmdVector3ToHeadSpace(HmdVector3_t hmdVector)
	{
		return thisPlayer.transform.TransformPoint(new Vector3(hmdVector.v0, hmdVector.v1, hmdVector.v2));
	}

	private Vector3 HmdVector3ToHeadSpace(Vector3 hmdVector)
	{
		return thisPlayer.transform.TransformPoint(hmdVector);
	}

	private bool IsInConvexPolygon(Vector3 testPoint, Vector3[] polygon)
	{
		if (polygon.Length == 0)
		{
			return false;
		}
		if (polygon.Length == 1)
		{
			return polygon[0].x == testPoint.x && polygon[0].z == testPoint.z;
		}
		int num = 0;
		int num2 = 0;
		for (int i = 0; i < polygon.Length; i++)
		{
			if (polygon[i].x == testPoint.x && polygon[i].z == testPoint.z)
			{
				return true;
			}
			float x = polygon[i].x;
			float z = polygon[i].z;
			int num3 = ((i < polygon.Length - 1) ? (i + 1) : 0);
			float x2 = polygon[num3].x;
			float z2 = polygon[num3].z;
			float x3 = testPoint.x;
			float z3 = testPoint.z;
			float num4 = (x3 - x) * (z2 - z) - (z3 - z) * (x2 - x);
			if (num4 > 0f)
			{
				num++;
			}
			if (num4 < 0f)
			{
				num2++;
			}
			if (num > 0 && num2 > 0)
			{
				return false;
			}
		}
		return true;
	}
}
public class PlayerCollider : RecRoomCollider
{
	[SerializeField]
	protected Player.BodyPart bodyPart;

	[HideInInspector]
	public Player ThisPlayer;

	public Player.BodyPart BodyPart => bodyPart;

	private void OnTriggerEnter(Collider collider)
	{
		Player.BodyPart otherPlayerBodyPart = Player.BodyPart.None;
		Player colliderPlayer = collider.GetColliderPlayer(out otherPlayerBodyPart);
		if (colliderPlayer != null)
		{
			ThisPlayer.PlayerEvents.PlayerHit(BodyPart, colliderPlayer, otherPlayerBodyPart);
		}
	}
}
namespace RecRoom.Players
{
	public class PlayerEmotes : Photon.MonoBehaviour
	{
		[Header("Shared Fields")]
		[SerializeField]
		private Canvas emoteBubbleCanvas;

		[SerializeField]
		private Animator emoteBubbleAnimator;

		[SerializeField]
		private JitteringTransform jitteringTransform;

		[SerializeField]
		private float minDistanceForBubbles = 2f;

		[Header("Emote Fields")]
		[SerializeField]
		private GameObject emoteRoot;

		[SerializeField]
		private Text emoteText;

		[SerializeField]
		private UnityEngine.UI.Image emoteImage;

		[SerializeField]
		private float textDuration = 2f;

		[Header("Chat Emote Fields")]
		[SerializeField]
		private GameObject chatRoot;

		[SerializeField]
		private Text chatEmoteText;

		[SerializeField]
		private UnityEngine.UI.Image chatEmoteImage;

		[SerializeField]
		private float chatDuration = 4f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip chatEmoteSFX;

		[SerializeField]
		private AudioRolloff chatEmoteCustomRolloff;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Player player;

		private static readonly int speakingAnimationID = Animator.StringToHash("Speaking");

		private float sqrMinDistanceForBubbles;

		private Coroutine emoteCoroutine;

		private Coroutine sendingChatEmoteCoroutine;

		public bool UsingEmoteBubble { get; set; }

		private bool CanShowEmote => player.isLocal || !player.Mute;

		protected override void Awake()
		{
			base.Awake();
			sqrMinDistanceForBubbles = minDistanceForBubbles * minDistanceForBubbles;
			UsingEmoteBubble = true;
			emoteBubbleCanvas.gameObject.SetActive(value: false);
			emoteImage.sprite = null;
		}

		private void Start()
		{
			bool flag = player.isLocal;
			emoteBubbleCanvas.gameObject.SetLayerRecursively((!flag) ? Layers.CameraMesh : Layers.HiddenInFirstPerson);
		}

		private void Update()
		{
			if (emoteBubbleCanvas.gameObject.activeInHierarchy && jitteringTransform != null)
			{
				jitteringTransform.UpdateTransform();
			}
		}

		public void ToggleUsingEmoteBubble()
		{
			UsingEmoteBubble = !UsingEmoteBubble;
		}

		public void LocalChoosingEmote(bool choosing)
		{
			base.photonView.RpcAll(RpcChoosingEmote, choosing, UsingEmoteBubble);
		}

		private void RemoteChoosingEmote(bool choosing, bool remoteUsingEmoteBubble)
		{
			if (emoteCoroutine == null)
			{
				emoteBubbleCanvas.gameObject.SetActive(choosing && remoteUsingEmoteBubble);
			}
			emoteBubbleAnimator.SetBoolIfActive(speakingAnimationID, !choosing);
		}

		public void LocalEmote(string emoteName, string context = null)
		{
			int expressoEmoteConfigIndex = ContextualEmotesSettings.GetExpressoEmoteConfigIndex(emoteName);
			base.photonView.RpcAll(RpcEmote, expressoEmoteConfigIndex, context, UsingEmoteBubble);
		}

		public void SendChatEmote(string message)
		{
			StartSendChatEmoteCoroutine(message);
		}

		private void RemoteEmote(PhotonPlayer emotingPlayer, int emoteConfigIndex, string context, bool remoteUsingEmoteBubble)
		{
			Player player = emotingPlayer.ToPlayer();
			if (player != null)
			{
				CancelCurrentEmoteCoroutine();
				emoteCoroutine = StartCoroutine(RunShowEmote(ContextualEmotesSettings.GetExpressoEmote(emoteConfigIndex), context, remoteUsingEmoteBubble));
			}
		}

		private void StartChatEmoteCoroutine(string message)
		{
			CancelCurrentEmoteCoroutine();
			emoteCoroutine = StartCoroutine(RunShowChatEmote(message));
		}

		private IEnumerator RunShowEmote(ContextualEmotesConfig.ExpressoEmote emote, string context, bool usingEmoteBubble)
		{
			if (emote != null)
			{
				bool showBubble = emote.forceEmoteBubble || (usingEmoteBubble && (!string.IsNullOrEmpty(emote.emoteText) || emote.emoticon != null) && (player.isLocal || (player.CurrentFloorPosition - Player.LocalPlayer.CurrentFloorPosition).sqrMagnitude >= sqrMinDistanceForBubbles));
				chatRoot.SetActive(value: false);
				emoteRoot.SetActive(value: true);
				if (showBubble)
				{
					emoteBubbleCanvas.gameObject.SetActive(value: true);
					emoteBubbleAnimator.SetBool(speakingAnimationID, value: true);
					emoteText.text = emote.GetEmoteTextWithContext(context);
					emoteImage.sprite = emote.emoticon;
					emoteImage.enabled = emoteImage.sprite != null;
				}
				if (emote.emoteAudio != null && player.isLocal)
				{
					AudioManager.Play2DSFX(emote.emoteAudio);
				}
				if (!string.IsNullOrEmpty(emote.facialExpression))
				{
					player.FacialAnimator.PlayEmote(emote.facialExpression);
				}
				yield return new WaitForSeconds(textDuration);
			}
			emoteBubbleCanvas.gameObject.SetActive(value: false);
			emoteCoroutine = null;
		}

		private IEnumerator RunShowChatEmote(string message)
		{
			chatRoot.SetActive(value: true);
			emoteRoot.SetActive(value: false);
			emoteBubbleCanvas.gameObject.SetActive(value: true);
			emoteBubbleAnimator.SetBool(speakingAnimationID, value: true);
			if (Profiles.LocalProfile.IsJunior())
			{
				chatEmoteImage.enabled = true;
				chatEmoteText.enabled = false;
			}
			else
			{
				chatEmoteImage.enabled = false;
				chatEmoteText.enabled = true;
				chatEmoteText.text = message;
				GameManager instance = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
				if (!player.isLocal && (bool)instance && (bool)instance.CurrentMode && instance.CurrentMode.TeamSettings.UseTeamRadio && instance.TeamManager != null && instance.TeamManager.PlayersAreTeammates(player.PhotonPlayer, Player.LocalPlayer.PhotonPlayer))
				{
					Vector3 vector = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.WorldToViewportPoint(player.Head.transform.position);
					if (vector.z < 0f || vector.z > NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.TeamSettings.ExitRadioDistance || vector.x < 0f || vector.y < 0f || vector.x > 1f || vector.y > 1f)
					{
						string titleText = string.Format("Teammate {0} says :{1}{2}", player.PlayerName.Truncate(12, "..."), Environment.NewLine, message);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, titleText, 3.5f);
					}
				}
			}
			if (player.isLocal)
			{
				AudioManager.Play2DSFX(chatEmoteSFX);
			}
			else
			{
				AudioManager.Play3DSFX(chatEmoteSFX, player.Head.transform.position, chatEmoteCustomRolloff);
			}
			yield return new WaitForSeconds(chatDuration);
			emoteBubbleCanvas.gameObject.SetActive(value: false);
			emoteCoroutine = null;
		}

		private void CancelCurrentEmoteCoroutine()
		{
			this.SafeStopCoroutine(emoteCoroutine);
			emoteCoroutine = null;
			emoteBubbleCanvas.gameObject.SetActive(value: false);
		}

		private void StartSendChatEmoteCoroutine(string message)
		{
			if (sendingChatEmoteCoroutine == null)
			{
				sendingChatEmoteCoroutine = StartCoroutine(SendChatEmoteCoroutine(message));
			}
		}

		private IEnumerator SendChatEmoteCoroutine(string message)
		{
			yield return StringSanitization.RequestIsStringPure(message, delegate(string error, StringSanitization.IsPureStringResponse response)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError("Error purifying Chat Emote Message.  Please try again.");
				}
				else if (response.IsPure)
				{
					base.photonView.RpcAll(RpcChatEmote, message);
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Can't Send Chat Message", 2f);
				}
			});
			sendingChatEmoteCoroutine = null;
		}

		[PunRPC]
		private void RpcChoosingEmote(bool choosing, bool usingEmoteBubble)
		{
			if (CanShowEmote)
			{
				RemoteChoosingEmote(choosing, usingEmoteBubble);
			}
		}

		[PunRPC]
		private void RpcEmote(int emoteConfigIndex, string context, bool usingEmoteBubble, PhotonMessageInfo messageInfo)
		{
			if (!CanShowEmote)
			{
				return;
			}
			PhotonPlayer sender = messageInfo.sender;
			RemoteEmote(sender, emoteConfigIndex, context, usingEmoteBubble);
			ContextualEmotesConfig.ExpressoEmote expressoEmote = ContextualEmotesSettings.GetExpressoEmote(emoteConfigIndex);
			if (expressoEmote != null && !string.IsNullOrEmpty(expressoEmote.emoteText))
			{
				string emoteTextWithContext = expressoEmote.GetEmoteTextWithContext(context);
				if (player.isLocal)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, emoteTextWithContext, 2f);
				}
				else if (ShouldShowRemoteEmoteNotification(expressoEmote))
				{
					string titleText = string.Format("{0} says :{1}{2}", player.PlayerName.Truncate(20, "..."), Environment.NewLine, emoteTextWithContext);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, titleText, 3.5f);
				}
			}
		}

		[PunRPC]
		private void RpcChatEmote(string message)
		{
			if (CanShowEmote)
			{
				StartChatEmoteCoroutine(message);
			}
		}

		private bool ShouldShowRemoteEmoteNotification(ContextualEmotesConfig.ExpressoEmote emoteConfig)
		{
			GameManager gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			return player.isLocal || (gameManager != null && (!emoteConfig.onlyBroadcastToTeam || gameManager.TeamManager.PlayersAreTeammates(player.PhotonPlayer, PhotonNetwork.player)));
		}
	}
}
