namespace RecRoom.Avatar.Face
{
	[ExecuteInEditMode]
	public class PlayerFacialAnimator : UnityEngine.MonoBehaviour
	{
		public enum Expression
		{
			NONE,
			HAPPY_EMOTE,
			SAD_EMOTE,
			DISGUST_EMOTE,
			LAUGH_EMOTE,
			SMILE,
			HUGE_SMILE,
			CELEBRATE,
			SAD,
			DISGUST,
			GOT_HIT,
			CONCENTRATING,
			KISS
		}

		private const float MIN_SECONDS_BETWEEN_BROADCASTS = 0.5f;

		[Header("Facial Features")]
		[SerializeField]
		private FaceStyleSet faceStyleSet;

		[SerializeField]
		private int browSelection;

		[SerializeField]
		private int eyeSelection;

		[SerializeField]
		private int noseSelection;

		[SerializeField]
		private int mouthSelection;

		[Header("Constraints")]
		[SerializeField]
		private Vector2 EyesHorizontalPositionRange = new Vector2(-0.1f, 0.1f);

		[SerializeField]
		private Vector2 EyesVerticalPositionRange = new Vector2(-0.3f, 0.3f);

		[SerializeField]
		private Vector2 MouthHorizontalPositionRange = new Vector2(-0.3f, 0.3f);

		[SerializeField]
		private Vector2 MouthVerticalPositionRange = new Vector2(-0.3f, 0.7f);

		[SerializeField]
		private float MinEyeAndMouthDistance = 0.05f;

		[SerializeField]
		private Vector2 EyeScaleRange = new Vector2(-0.1f, 0.25f);

		[SerializeField]
		private Vector2 MouthScaleRange = new Vector2(-0.2f, 0.4f);

		private const float defaultEyeMouthDelta = 0.5f;

		private FaceStyle faceStyle;

		[Header("Rendering")]
		[SerializeField]
		private Renderer faceRenderer;

		private int generatedFaceStyleHash;

		[HideInInspector]
		public Sprite browSprite;

		[HideInInspector]
		public Sprite eyeSprite;

		[HideInInspector]
		public Sprite noseSprite;

		[HideInInspector]
		public Sprite mouthSprite;

		[SerializeField]
		private float jitterFPS = 6f;

		private Vector2 leftBrowPosition;

		private Vector2 rightBrowPosition;

		private Vector2 leftEyePosition;

		private Vector2 rightEyePosition;

		private Vector3 nosePosition;

		private Vector3 mouthPosition;

		private Vector2 eyePositionOffset = Vector2.zero;

		private Vector2 mouthPositionOffset = Vector2.zero;

		private float eyeScaleOffset;

		private float mouthScaleOffset;

		private List<FaceFeatureBase> eyeFeatures;

		private List<FaceFeatureBase> mouthFeatures;

		[Header("Emotes")]
		[SerializeField]
		private GameObject emoteExtraFacialFeatures;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Animator animator;

		[SerializeField]
		[AutofillOptional(AutofillType.Parent, false)]
		private Player player;

		private Coroutine emoteCoroutine;

		private string currentEmoteName;

		private int currentEmoteId = -1;

		private int lastJitterCount = -1;

		[NonSerialized]
		public bool UpdateMaterial = true;

		private const float emoteDuration = 3f;

		private static int EmoteHappyID = Animator.StringToHash("EmoteHappy");

		private static int EmoteSadID = Animator.StringToHash("EmoteSad");

		private static int EmoteDisgustID = Animator.StringToHash("EmoteDisgust");

		private static int EmoteLaunghID = Animator.StringToHash("EmoteLaugh");

		private static int SmileID = Animator.StringToHash("Smile");

		private static int HugeSmileID = Animator.StringToHash("HugeSmile");

		private static int CelebrateID = Animator.StringToHash("Score");

		private static int SadID = Animator.StringToHash("Sad");

		private static int DisgustID = Animator.StringToHash("Disgust");

		private static int HitID = Animator.StringToHash("Hit");

		private static int ConcentrateID = Animator.StringToHash("Concentrate");

		private static int KissID = Animator.StringToHash("Kiss");

		private static int TalkingID = Animator.StringToHash("Talking");

		private static int MuteID = Animator.StringToHash("Mute");

		private static int SpriteArrayID = Shader.PropertyToID("_SpriteArray");

		private static int BrowOffsetsID = Shader.PropertyToID("_BrowOffsets");

		private static int BrowIdxID = Shader.PropertyToID("_BrowIdx");

		private static int LeftEyeID = Shader.PropertyToID("_LeftEye");

		private static int RightEyeID = Shader.PropertyToID("_RightEye");

		private static int EyeIdxID = Shader.PropertyToID("_EyeIdx");

		private static int NoseID = Shader.PropertyToID("_Nose");

		private static int NoseIdxID = Shader.PropertyToID("_NoseIdx");

		private static int MouthID = Shader.PropertyToID("_Mouth");

		private static int MouthIdxID = Shader.PropertyToID("_MouthIdx");

		private float lastBroadcastTime;

		private MaterialPropertyBlock internal_faceMatProperties;

		public Renderer FaceRenderer => faceRenderer;

		private int SelectedFaceStyleHash => (3 * (browSelection + 1)) ^ (7 * (eyeSelection + 3)) ^ (11 * (noseSelection + 7)) ^ (13 * (mouthSelection + 11)) ^ faceStyleSet.ImportHash;

		public bool Talking
		{
			get
			{
				return animator.GetBool(TalkingID);
			}
			set
			{
				animator.SetBoolIfActive(TalkingID, value && !Emoting);
			}
		}

		public bool Emoting => currentEmoteName != null || currentEmoteId >= 0;

		private MaterialPropertyBlock FaceMatProperties
		{
			get
			{
				if (internal_faceMatProperties == null)
				{
					internal_faceMatProperties = new MaterialPropertyBlock();
				}
				return internal_faceMatProperties;
			}
		}

		public void PlayExpression(Expression expression)
		{
			if (expression != Expression.NONE)
			{
				int idFromExpression = GetIdFromExpression(expression);
				if (IsEmoteExpression(expression))
				{
					PlayEmote(idFromExpression);
				}
				else
				{
					animator.SetTrigger(idFromExpression);
				}
			}
		}

		public void PlayEmote(string stateName)
		{
			CancelCurrentEmote();
			emoteCoroutine = StartCoroutine(RunPlayEmote(stateName));
		}

		private void PlayEmote(int stateId)
		{
			CancelCurrentEmote();
			emoteCoroutine = StartCoroutine(RunPlayEmote(stateId));
		}

		private void CancelCurrentEmote()
		{
			if (emoteCoroutine != null && currentEmoteName != null)
			{
				StopCoroutine(emoteCoroutine);
				animator.SetBool(currentEmoteName, value: false);
				currentEmoteName = null;
			}
		}

		private IEnumerator RunPlayEmote(int stateId)
		{
			currentEmoteId = stateId;
			animator.SetBool(stateId, value: true);
			yield return new WaitForSeconds(3f);
			animator.SetBool(stateId, value: false);
			currentEmoteId = -1;
		}

		private IEnumerator RunPlayEmote(string stateName)
		{
			currentEmoteName = stateName;
			animator.SetBool(stateName, value: true);
			yield return new WaitForSeconds(3f);
			animator.SetBool(stateName, value: false);
			currentEmoteName = null;
		}

		private void Awake()
		{
			animator = GetComponent<Animator>();
			UnityEngine.Random.InitState((int)DateTime.UtcNow.Ticks);
			if (UnityEngine.Application.isPlaying && faceStyleSet != null)
			{
				BuildFaceStyle();
			}
			eyeFeatures = new List<FaceFeatureBase>(faceStyleSet.Eyes);
			mouthFeatures = new List<FaceFeatureBase>(faceStyleSet.Mouths);
		}

		private void Start()
		{
			if (player != null)
			{
				PlayerEvents playerEvents = player.PlayerEvents;
				playerEvents.GameOverEvent += OnGameOver;
				playerEvents.PlayerHitEvent += OnPlayerHit;
				playerEvents.ToolHitEvent += OnToolHit;
				playerEvents.ToolPickupEvent += OnToolPickup;
				playerEvents.ToolReleaseEvent += OnToolRelease;
				playerEvents.TeleportEvent += OnTeleport;
				playerEvents.OutfitEquipEvent += OnOutfitEquipped;
				playerEvents.MicrophoneMuteEvent += OnMicrophoneMuted;
				if (emoteExtraFacialFeatures != null)
				{
					bool flag = !player.isLocal;
					emoteExtraFacialFeatures.SetLayerRecursively((!flag) ? Layers.HiddenInFirstPerson : Layers.RemotePlayerPhysics);
				}
			}
		}

		private void OnDestroy()
		{
			if (player != null)
			{
				PlayerEvents playerEvents = player.PlayerEvents;
				playerEvents.GameOverEvent -= OnGameOver;
				playerEvents.PlayerHitEvent -= OnPlayerHit;
				playerEvents.ToolHitEvent -= OnToolHit;
				playerEvents.ToolPickupEvent -= OnToolPickup;
				playerEvents.ToolReleaseEvent -= OnToolRelease;
				playerEvents.TeleportEvent -= OnTeleport;
				playerEvents.OutfitEquipEvent -= OnOutfitEquipped;
				playerEvents.MicrophoneMuteEvent -= OnMicrophoneMuted;
			}
			if (faceStyle != null)
			{
				faceStyle.Dispose();
			}
		}

		private void OnMicrophoneMuted(bool muted)
		{
			animator.SetBool(MuteID, muted);
		}

		private void OnOutfitEquipped(Player.BodyPart bodyPart)
		{
			animator.SetTrigger(SmileID);
		}

		private void OnTeleport()
		{
			animator.SetTrigger(SmileID);
		}

		private void OnToolRelease(Tool tool)
		{
			animator.SetTrigger(SmileID);
		}

		private void OnToolPickup(Tool tool)
		{
			animator.SetTrigger(ConcentrateID);
		}

		private void OnToolHit(Player.BodyPart bodyPart, Tool tool)
		{
			if (bodyPart == Player.BodyPart.Head)
			{
				animator.SetTrigger(HitID);
			}
		}

		private void OnPlayerHit(Player.BodyPart bodyPart, Player otherPlayer, Player.BodyPart otherPlayerBodyPart)
		{
			if (!(otherPlayer == player))
			{
				if (bodyPart == Player.BodyPart.Head && (otherPlayerBodyPart == Player.BodyPart.LeftHand || otherPlayerBodyPart == Player.BodyPart.RightHand))
				{
					BroadcastExpression(HitID);
				}
				else if (bodyPart == Player.BodyPart.Head && otherPlayerBodyPart == Player.BodyPart.Head)
				{
					BroadcastExpression(KissID);
				}
			}
		}

		private void BroadcastExpression(int hashID)
		{
			float unscaledTime = UnityEngine.Time.unscaledTime;
			if (unscaledTime - lastBroadcastTime > 0.5f)
			{
				lastBroadcastTime = unscaledTime;
				player.BroadcastFacialExpression(hashID);
			}
		}

		public void PlayExpression(int hashID)
		{
			animator.SetTrigger(hashID);
		}

		private bool IsEmoteExpression(Expression expression)
		{
			return expression == Expression.DISGUST_EMOTE || expression == Expression.HAPPY_EMOTE || expression == Expression.LAUGH_EMOTE || expression == Expression.SAD_EMOTE;
		}

		private int GetIdFromExpression(Expression expression)
		{
			return expression switch
			{
				Expression.CELEBRATE => CelebrateID, 
				Expression.CONCENTRATING => ConcentrateID, 
				Expression.DISGUST => DisgustID, 
				Expression.DISGUST_EMOTE => EmoteDisgustID, 
				Expression.GOT_HIT => HitID, 
				Expression.HAPPY_EMOTE => EmoteHappyID, 
				Expression.HUGE_SMILE => HugeSmileID, 
				Expression.KISS => KissID, 
				Expression.LAUGH_EMOTE => EmoteLaunghID, 
				Expression.SAD => SadID, 
				Expression.SAD_EMOTE => EmoteSadID, 
				Expression.SMILE => SmileID, 
				_ => -1, 
			};
		}

		private void OnActivityScored(bool thisPlayerScored)
		{
			int trigger = ((!thisPlayerScored) ? DisgustID : CelebrateID);
			animator.SetTrigger(trigger);
		}

		private void OnGameOver(bool thisPlayerWon, float completionPercentage)
		{
			int trigger = ((!thisPlayerWon) ? SadID : HugeSmileID);
			animator.SetTrigger(trigger);
		}

		private void BuildFaceStyle()
		{
			if (faceStyle != null)
			{
				faceStyle.Dispose();
			}
			faceStyle = faceStyleSet.Build(browSelection, eyeSelection, noseSelection, mouthSelection);
			browSprite = faceStyle.Brow.SrcSprites.First();
			eyeSprite = faceStyle.Eye.SrcSprites.First();
			noseSprite = faceStyle.Nose.SrcSprites.First();
			mouthSprite = faceStyle.Mouth.SrcSprites.First();
		}

		private void Update()
		{
			bool flag = false;
			if (faceStyleSet != null && (faceStyle == null || SelectedFaceStyleHash != generatedFaceStyleHash))
			{
				BuildFaceStyle();
				FaceMatProperties.SetTexture(SpriteArrayID, faceStyle.TextureArray);
				generatedFaceStyleHash = SelectedFaceStyleHash;
				flag = true;
			}
			if (UpdateMaterial || flag)
			{
				if (faceStyleSet != null)
				{
					UpdateFaceStyleTextures();
				}
				int num = Mathf.FloorToInt(UnityEngine.Time.realtimeSinceStartup * jitterFPS);
				if (num != lastJitterCount)
				{
					lastJitterCount = num;
					ApplyJitter();
				}
				if ((bool)faceRenderer)
				{
					faceRenderer.SetPropertyBlock(FaceMatProperties);
				}
			}
		}

		private void UpdateFaceStyleTextures()
		{
			FaceMatProperties.SetFloat(BrowIdxID, faceStyle.SpriteUVDepth(browSprite));
			FaceMatProperties.SetFloat(EyeIdxID, faceStyle.SpriteUVDepth(eyeSprite));
			FaceMatProperties.SetFloat(NoseIdxID, faceStyle.SpriteUVDepth(noseSprite));
			FaceMatProperties.SetFloat(MouthIdxID, faceStyle.SpriteUVDepth(mouthSprite));
		}

		private void ApplyJitter()
		{
			if (faceStyleSet != null)
			{
				faceStyle.Brow.NewJitter();
				FaceMatProperties.SetVector(BrowOffsetsID, new Vector4(faceStyle.Brow.DefaultAnchorLeft.x, faceStyle.Brow.DefaultAnchorLeft.y, faceStyle.Brow.DefaultAnchorRight.x, faceStyle.Brow.DefaultAnchorRight.y));
				faceStyle.Eye.NewJitter();
				FaceMatProperties.SetVector(LeftEyeID, new Vector4(faceStyle.Eye.JitteredAnchorLeft.x + eyePositionOffset.x, faceStyle.Eye.JitteredAnchorLeft.y + eyePositionOffset.y, (faceStyle.Eye.JitteredScale.x + eyeScaleOffset) * -1f, faceStyle.Eye.JitteredScale.y + eyeScaleOffset));
				FaceMatProperties.SetVector(RightEyeID, new Vector4(faceStyle.Eye.JitteredAnchorRight.x - eyePositionOffset.x, faceStyle.Eye.JitteredAnchorRight.y + eyePositionOffset.y, faceStyle.Eye.JitteredScale.x + eyeScaleOffset, faceStyle.Eye.JitteredScale.y + eyeScaleOffset));
				faceStyle.Nose.NewJitter();
				FaceMatProperties.SetVector(NoseID, new Vector4(faceStyle.Nose.JitteredAnchor.x, faceStyle.Nose.JitteredAnchor.y, faceStyle.Nose.JitteredScale.x, faceStyle.Nose.JitteredScale.y));
				faceStyle.Mouth.NewJitter();
				FaceMatProperties.SetVector(MouthID, new Vector4(faceStyle.Mouth.JitteredAnchor.x + mouthPositionOffset.x, faceStyle.Mouth.JitteredAnchor.y + mouthPositionOffset.y, faceStyle.Mouth.JitteredScale.x + mouthScaleOffset, faceStyle.Mouth.JitteredScale.y + mouthScaleOffset));
			}
		}

		public void CopyFaceSettingsTo(Renderer otherFaceRenderer, PlayerFacialAnimator other)
		{
			other.faceStyleSet = faceStyleSet;
			other.browSelection = browSelection;
			other.eyeSelection = eyeSelection;
			other.noseSelection = noseSelection;
			other.mouthSelection = mouthSelection;
			other.faceRenderer = otherFaceRenderer;
		}

		public bool IsValidGuid(FaceFeatureType featureType, string guid)
		{
			FaceFeatureBase feature = faceStyleSet.GetFeature(featureType, guid);
			return feature != null;
		}

		public List<FaceFeatureBase> GetAvailableFeatures(FaceFeatureType featureType)
		{
			return featureType switch
			{
				FaceFeatureType.Eye => eyeFeatures, 
				FaceFeatureType.Mouth => mouthFeatures, 
				_ => null, 
			};
		}

		public FaceFeatureBase GetSelectedFaceFeature(FaceFeatureType featureType)
		{
			FaceFeatureBase result = null;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = faceStyleSet.Eyes[eyeSelection];
				break;
			case FaceFeatureType.Mouth:
				result = faceStyleSet.Mouths[mouthSelection];
				break;
			default:
				UnityEngine.Debug.LogWarningFormat("Unrecognized face feature type in GetSelectedFaceFeature: {0}", featureType);
				break;
			}
			return result;
		}

		public int GetSelectedFaceFeatureIndex(FaceFeatureType featureType)
		{
			int result = -1;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = eyeSelection;
				break;
			case FaceFeatureType.Mouth:
				result = mouthSelection;
				break;
			default:
				UnityEngine.Debug.LogWarningFormat("Unrecognized face feature type in GetSelectedFaceFeatureIndex: {0}", featureType);
				break;
			}
			return result;
		}

		public void SetFaceSettings(AvatarFaceSettings settings)
		{
			if (settings != null)
			{
				SetSelectedFaceFeature(FaceFeatureType.Eye, settings.EyeGuid);
				SetFaceFeaturePositionOffset(FaceFeatureType.Eye, settings.EyePositionOffset);
				SetFaceFeatureScaleOffset(FaceFeatureType.Eye, settings.EyeScaleOffset);
				SetSelectedFaceFeature(FaceFeatureType.Mouth, settings.MouthGuid);
				SetFaceFeaturePositionOffset(FaceFeatureType.Mouth, settings.MouthPositionOffset);
				SetFaceFeatureScaleOffset(FaceFeatureType.Mouth, settings.MouthScaleOffset);
			}
		}

		public void SetSelectedFaceFeature(FaceFeatureType featureType, int selectionIndex)
		{
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				if (selectionIndex >= 0 && selectionIndex < faceStyleSet.Eyes.Length)
				{
					eyeSelection = selectionIndex;
					break;
				}
				UnityEngine.Debug.LogWarningFormat("Invalid eye feature index: {0}. Eye list length = {1}", selectionIndex, faceStyleSet.Eyes.Length);
				break;
			case FaceFeatureType.Mouth:
				if (selectionIndex >= 0 && selectionIndex < faceStyleSet.Mouths.Length)
				{
					mouthSelection = selectionIndex;
					break;
				}
				UnityEngine.Debug.LogWarningFormat("Invalid mouth feature index: {0}. Mouth list length = {1}", selectionIndex, faceStyleSet.Mouths.Length);
				break;
			default:
				UnityEngine.Debug.LogWarningFormat("Unrecognized facial feature type in SetFeatureSelection: {0}", featureType);
				break;
			}
		}

		public void SetSelectedFaceFeature(FaceFeatureType featureType, string guid)
		{
			int featureIndex = faceStyleSet.GetFeatureIndex(guid);
			if (featureIndex < 0)
			{
				UnityEngine.Debug.LogWarningFormat("Could not find matching index for given face feature guid: {0}", guid);
			}
			else
			{
				SetSelectedFaceFeature(featureType, featureIndex);
			}
		}

		public void SetFaceFeaturePositionOffset(FaceFeatureType featureType, Vector2 position)
		{
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				eyePositionOffset = ClampFaceFeaturePositionOffset(FaceFeatureType.Eye, position);
				break;
			case FaceFeatureType.Mouth:
				mouthPositionOffset = ClampFaceFeaturePositionOffset(FaceFeatureType.Mouth, position);
				break;
			default:
				UnityEngine.Debug.LogWarningFormat("Unrecognized face feature type in SetFaceFeaturePositionOffset: {0}", featureType);
				break;
			}
		}

		public Vector2 ClampFaceFeaturePositionOffset(FaceFeatureType featureType, Vector2 position)
		{
			Vector2 result = position;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
			{
				float x2 = Mathf.Clamp(position.x, EyesHorizontalPositionRange.x, EyesHorizontalPositionRange.y);
				float num3 = Mathf.Clamp(position.y, EyesVerticalPositionRange.x, EyesVerticalPositionRange.y);
				float num4 = 0.5f + num3 - mouthPositionOffset.y;
				if (num4 < MinEyeAndMouthDistance)
				{
					num3 = MinEyeAndMouthDistance - 0.5f + mouthPositionOffset.y;
				}
				result = new Vector2(x2, num3);
				break;
			}
			case FaceFeatureType.Mouth:
			{
				float x = Mathf.Clamp(position.x, MouthHorizontalPositionRange.x, MouthHorizontalPositionRange.y);
				float num = Mathf.Clamp(position.y, MouthVerticalPositionRange.x, MouthVerticalPositionRange.y);
				float num2 = 0.5f + eyePositionOffset.y - num;
				if (num2 < MinEyeAndMouthDistance)
				{
					num = 0f - MinEyeAndMouthDistance + 0.5f + eyePositionOffset.y;
				}
				result = new Vector2(x, num);
				break;
			}
			}
			return result;
		}

		public bool CanMoveFeature(FaceFeatureType featureType, Vector2 desiredPosition, float minDelta)
		{
			bool result = true;
			Vector2 a = ClampFaceFeaturePositionOffset(featureType, desiredPosition);
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = Vector2.Distance(a, eyePositionOffset) > minDelta;
				break;
			case FaceFeatureType.Mouth:
				result = Vector2.Distance(a, mouthPositionOffset) > minDelta;
				break;
			}
			return result;
		}

		public void SetFaceFeatureScaleOffset(FaceFeatureType featureType, float scale)
		{
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				eyeScaleOffset = ClampFaceFeatureScaleOffset(FaceFeatureType.Eye, scale);
				break;
			case FaceFeatureType.Mouth:
				mouthScaleOffset = ClampFaceFeatureScaleOffset(FaceFeatureType.Mouth, scale);
				break;
			default:
				UnityEngine.Debug.LogWarningFormat("Unrecognized face feature type in SetFaceFeatureScaleOffset: {0}", featureType);
				break;
			}
		}

		public float ClampFaceFeatureScaleOffset(FaceFeatureType featureType, float scale)
		{
			float result = scale;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = Mathf.Clamp(scale, EyeScaleRange.x, EyeScaleRange.y);
				break;
			case FaceFeatureType.Mouth:
				result = Mathf.Clamp(scale, MouthScaleRange.x, MouthScaleRange.y);
				break;
			}
			return result;
		}

		public bool CanScaleFeature(FaceFeatureType featureType, float desiredScale, float minDelta)
		{
			bool result = true;
			float num = ClampFaceFeatureScaleOffset(featureType, desiredScale);
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = Mathf.Abs(num - eyeScaleOffset) > minDelta;
				break;
			case FaceFeatureType.Mouth:
				result = Mathf.Abs(num - mouthScaleOffset) > minDelta;
				break;
			}
			return result;
		}

		public string GetDefaultFaceFeatureGuid(FaceFeatureType featureType)
		{
			string result = string.Empty;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				result = faceStyleSet.Eyes[0].Guid;
				break;
			case FaceFeatureType.Mouth:
				result = faceStyleSet.Mouths[0].Guid;
				break;
			}
			return result;
		}

		public string GetRandomFaceFeatureGuid(FaceFeatureType featureType)
		{
			string result = string.Empty;
			int num = 0;
			switch (featureType)
			{
			case FaceFeatureType.Eye:
				num = UnityEngine.Random.Range(0, faceStyleSet.Eyes.Length);
				result = faceStyleSet.Eyes[num].Guid;
				break;
			case FaceFeatureType.Mouth:
				num = UnityEngine.Random.Range(0, faceStyleSet.Mouths.Length);
				result = faceStyleSet.Mouths[num].Guid;
				break;
			}
			return result;
		}
	}
}
