		handColliders = GetComponentsInChildren<PlayerHandCollider>(includeInactive: true);
		visualRenderers = meshRoot.GetComponentsInChildren<Renderer>();
		PlayerHandRemote = UnityEngine.Object.Instantiate(playerHandRemotePrefab);
		PlayerHandRemote.Player = ThisPlayer;
		PlayerHandRemote.Hand = this;
		ThisPlayer.SetParentPlayerRoot(PlayerHandRemote.transform);
		RigidbodyEx.AddKinematic(this);
		RigidbodyEx.kinematicVelocityCalculationMode.AddValue(isLocal ? RigidbodyEx.KinematicVelocityCalculationMode.None : RigidbodyEx.KinematicVelocityCalculationMode.Position, this);
		RigidbodyEx.LateUpdateEvent += OnRigidbodyVelocityUpdate;
		RigidbodyEx.FreezeCenterOfMassAndInertiaTensor();
		if (isLocal)
		{
			RigidbodyEx.PreProxyUpdateEvent += OnRigidbodyPreProxyUpdate;
			HandAnimator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
		}
		menuLaser.enabled = false;
		menuLaser.material.renderQueue = 3002;
		remoteHandAnimationCullingSqDistance = remoteHandAnimationCullingDistance * remoteHandAnimationCullingDistance;
		_controllerState = new SynchronizedField<ConnectedState>(this, "CS", ConnectedState.NOT_CONNECTED, SetterPermissionMode.AUTHORITY);
		_visualState = new SynchronizedField<VisualState>(this, "HS", VisualState.None, SetterPermissionMode.AUTHORITY, OnVisualStateChanged);
	}

	private void Start()
	{
		Tool.StaticHolderChangedEvent += OnToolHolderChanged;
		Tool[] array = UnityEngine.Object.FindObjectsOfType<Tool>();
		foreach (Tool tool in array)
		{
			OnToolHolderChanged(tool);
		}
		OnVisualStateChanged();
		if (!isLocal)
		{
			RemoteUpdate();
		}
