	protected override void OnDestroy()
	{
		base.OnDestroy();
		MenuFinger.ReleaseLatestPushedButton(ThisPlayer.PhotonPlayer);
		if (RigidbodyEx != null)
		{
			RigidbodyEx.LateUpdateEvent -= OnRigidbodyVelocityUpdate;
			if (isLocal)
			{
				RigidbodyEx.PreProxyUpdateEvent -= OnRigidbodyPreProxyUpdate;
			}
