	private void OnRigidbodyPreProxyUpdate(RigidbodyEx thisRigidbodyEx)
	{
		if (ConcaveMeshWorldCollisionMode != WorldCollisionMode.ALWAYS_DISABLED && (!(SingletonMonoBehaviour<LocalPlayerController>.Instance != null) || !SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode))
		{
			thisRigidbodyEx.targetPosition = ResolveWorldCollision(thisRigidbodyEx.physicsPosition, thisRigidbodyEx.targetPosition, thisRigidbodyEx.targetRotation);
		}
	}

	private Vector3 ResolveWorldCollision(Vector3 currentPosition, Vector3 desiredPosition, Quaternion desiredRotation)
	{
		Vector3 vector = desiredPosition - currentPosition;
		CollisionDetection.CollisionResult collisionResult = CollisionDetection.CollisionResult.OVERLAP;
		Vector3 vector2 = Vector3.zero;
		float num = 0f;
		float num2 = 0f;
		float sqrMagnitude = vector.sqrMagnitude;
		if (sqrMagnitude >= 9f)
		{
			return desiredPosition;
		}
		if (sqrMagnitude >= 1E-05f)
		{
			num = vector.magnitude;
			vector2 = vector / num;
			collisionResult = CollisionDetection.SweepSphere(handCenter.position, worldCollisionRadius, vector2, num, 2048, IsValidWorldCollider, out var hit);
			num2 = hit.distance;
		}
		switch (collisionResult)
		{
		case CollisionDetection.CollisionResult.MISS:
			return desiredPosition;
		case CollisionDetection.CollisionResult.HIT:
			return currentPosition + vector2 * num2;
		default:
		{
			if (CollisionDetection.DepenetrateSphere(handCenter.position, desiredRotation, worldCollisionRadius, 2048, IsValidWorldCollider, out var totalDepenetration))
			{
				return currentPosition + totalDepenetration;
			}
			return desiredPosition;
		}
		}
	}

	private bool IsValidWorldCollider(Collider collider)
	{
		if (ConcaveMeshWorldCollisionMode == WorldCollisionMode.ALWAYS_DISABLED)
		{
			return false;
		}
		MeshCollider meshCollider = collider as MeshCollider;
		if (!(meshCollider != null) || meshCollider.convex)
		{
			return false;
		}
		if (ConcaveMeshWorldCollisionMode == WorldCollisionMode.DEFAULT_DISABLED)
		{
			PlayerHandWorldCollisionConfig component = collider.GetComponent<PlayerHandWorldCollisionConfig>();
			return component != null;
		}
		return true;
	}

	private void Update()
	{
		if (isLocal)
		{
			LocalUpdate();
		}
		else if (this.IsStaggeredUpdateFrame(10))
		{
			RemoteUpdate();
		}
	}

	private void LocalUpdate()
	{
		LocalUpdateVisualState();
	}

	private void RemoteUpdate()
	{
		if (SingletonMonoBehaviour<CameraRig>.Instance != null)
		{
			float sqrMagnitude = (SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position - base.transform.position).sqrMagnitude;
			AnimatorCullingMode animatorCullingMode = ((sqrMagnitude < remoteHandAnimationCullingSqDistance) ? AnimatorCullingMode.CullUpdateTransforms : AnimatorCullingMode.CullCompletely);
			if (HandAnimator.cullingMode != animatorCullingMode)
			{
				HandAnimator.cullingMode = animatorCullingMode;
			}
		}
	}

