	private bool IsVisualStateActive(VisualState state)
	{
		return (CurrentVisualState & state) == state;
	}

	private void OnVisualStateChanged()
	{
		bool flag = IsVisualStateActive(VisualState.DefaultHand);
		bool visible = IsVisualStateActive(VisualState.HeldTool);
		bool flag2 = IsVisualStateActive(VisualState.TeleportHand);
		bool flag3 = IsVisualStateActive(VisualState.MenuHand);
		Renderer[] array = visualRenderers;
		foreach (Renderer renderer in array)
		{
			renderer.gameObject.SetActive(flag);
		}
		PlayerHandCollider[] array2 = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array2)
		{
			if (playerHandCollider != null && !playerHandCollider.IsTrigger)
			{
				playerHandCollider.gameObject.SetActive(flag);
			}
		}
		ThisPlayer.PlayerOutfit.SetHandVisible(Type, flag);
		if (!flag && !flag3)
		{
			ClearHoveredTool();
		}
		menuHandRoot.gameObject.SetActive(flag3);
		if (HeldTool != null)
		{
			HeldTool.SetVisible(visible, flag2);
		}
		PlayerHandRemote.Visible = flag2;
	}

	public void HideHand(bool hide)
	{
		if (IsHidden != hide)
		{
			IsHidden = hide;
			LocalUpdateVisualState();
		}
	}

	private void LocalUpdateVisualState()
	{
		if (!isLocal)
		{
			return;
		}
		bool flag = ThisPlayer.IsVisible && HandConnectedState != ConnectedState.NOT_CONNECTED && !IsHidden;
		VisualState visualState = VisualState.None;
		if (flag)
		{
			bool teleportLaserVisible = PlayerHandRemote.TeleportLaserVisible;
			GetHoveredTool(out var hoveredTool, out var _);
			bool flag2 = showMenuHand && !teleportLaserVisible && (hoveredTool == null || hoveredTool.IsHeld || hoveredTool.PlayerSpawnedEquipment == null || HandInForceUIRegion);
			bool flag3 = HeldTool != null;
			if (teleportLaserVisible)
			{
				visualState |= VisualState.TeleportHand;
				visualState = (VisualState)((int)visualState | ((!flag3) ? 1 : 8));
			}
			if (flag2)
			{
				visualState |= VisualState.MenuHand;
			}
			if (flag3 && !flag2)
			{
				visualState |= VisualState.HeldTool;
			}
			if (!flag3 && !flag2 && !teleportLaserVisible)
			{
				visualState |= VisualState.DefaultHand;
			}
		}
		if (CustomVisualState.HasValue)
		{
			visualState = CustomVisualState.Value;
		}
		if (CurrentVisualState != visualState)
		{
			CurrentVisualState = visualState;
		}
	}

	private float GetMenuLaserAlpha(Vector3 menuTargetPosition, bool clickPressed, bool uiSelected)
	{
		float num = 0.85f;
		if (!clickPressed)
		{
			float time = Vector3.Distance(fingertipTransform.position, menuTargetPosition);
			num *= MenuLaserDistanceAlpha.Evaluate(time);
			if (!uiSelected)
			{
				num *= 0.1f;
			}
		}
		return num;
	}

	public void UpdateMenuHandVisibility(bool hasMenuTarget)
	{
		GetHoveredTool(out var hoveredTool, out var _);
		bool flag = !PlayerHandRemote.TeleportLaserVisible && HandConnectedState != ConnectedState.NOT_CONNECTED && ((HeldTool == null && hoveredTool == null) || menuLaser.enabled || HandInUIRegion);
		if (ExpressoInfoGestureActive && (IsVisualStateActive(VisualState.TeleportHand) || IsVisualStateActive(VisualState.HeldTool)))
		{
			ExpressoInfoGestureActive = false;
		}
		bool flag2 = HeldTool == null && hoveredTool == null && ExpressoInfoGestureActive;
		bool flag3 = (flag && hasMenuTarget) || HandInUIRegion || flag2;
		if (flag3)
		{
			lastMenuHandShowTime = UnityEngine.Time.time;
		}
		if (flag3 || (!flag3 && UnityEngine.Time.time - lastMenuHandShowTime > 0.1f))
		{
			showMenuHand = flag3;
		}
		CanMenuLaserInteract = flag;
	}

	public void GetHoveredTool(out Tool hoveredTool, out bool inPhysicalPickupRange)
	{
		float num = UnityEngine.Time.unscaledTime - _previousHoveredToolTime;
		if (_hoveredTool == null && _previousHoveredTool != null && num <= HOVERED_TOOL_INTERACTION_SLOP_WINDOW)
		{
			hoveredTool = _previousHoveredTool;
			inPhysicalPickupRange = _previousHoveredToolInPhysicalPickupRange;
		}
		else
		{
			hoveredTool = _hoveredTool;
			inPhysicalPickupRange = _hoveredToolInPhysicalPickupRange;
		}
	}

	public void SetHoveredTool(Tool tool, bool inPhysicalPickupRange)
	{
		if (_hoveredTool != tool)
		{
			if (_hoveredTool != null)
			{
				_hoveredTool.HoverEnd();
			}
			_previousHoveredTool = _hoveredTool;
			_previousHoveredToolInPhysicalPickupRange = _hoveredToolInPhysicalPickupRange;
			_previousHoveredToolTime = UnityEngine.Time.unscaledTime;
			_hoveredTool = tool;
			_hoveredToolInPhysicalPickupRange = inPhysicalPickupRange;
			if (_hoveredTool != null)
			{
				_hoveredTool.HoverStart();
			}
		}
		else if (_hoveredTool != null)
		{
			_hoveredToolInPhysicalPickupRange = inPhysicalPickupRange;
		}
	}

	public void ClearHoveredTool()
	{
		SetHoveredTool(null, inPhysicalPickupRange: false);
	}

	public void SetHoveredOutfitTrigger(OutfitTrigger outfitTrigger)
	{
		triggeredOutfit = outfitTrigger;
	}

	public bool TryRemoveTriggeredOutfit(bool buttonDown)
	{
		if (DefaultHandVisualsActive && buttonDown && triggeredOutfit != null && triggeredOutfit.SceneTool != null)
		{
			OutfitTool sceneTool = triggeredOutfit.SceneTool;
			if (sceneTool != null)
			{
				ThisPlayer.PlayerOutfit.RemoveOutfitByHand(triggeredOutfit.OutfitItem.Selection, triggeredOutfit.OutfitItem.CurrentBodyPart);
				sceneTool.Tool.IsEnabled = true;
				sceneTool.DontCollideWithPlayer(1f);
				triggeredOutfit.PositionToolForPickup(sceneTool);
				TryPickupTool(sceneTool.Tool, inPhysicalPickupRange: false);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Null outfitTool in TryRemoveTriggeredOutfit");
			}
			return true;
		}
		return false;
	}

	public bool TryPickupTool(Tool tool, bool inPhysicalPickupRange, bool forceSnapPosition = false)
	{
		bool flag = tool.PlayerSpawnedEquipment != null && tool.PlayerSpawnedEquipment.IsMine;
		PlayerHand playerHand = ((Type != HandType.Left) ? ThisPlayer.LeftHand : ThisPlayer.RightHand);
		bool flag2 = tool.HolderHand == playerHand;
		if (ThisPlayer.CanInteractWithTools && (!tool.IsHeldByPlayer || flag2 || flag))
		{
			if (tool.PlayerSpawnedEquipment != null && !tool.PlayerSpawnedEquipment.TryPickupSpawnedEquipment(ThisPlayer))
			{
				return false;
			}
			GetToolPickupPositionAndRotation(tool, inPhysicalPickupRange, flag2, forceSnapPosition, out var handSpacePickupPosition, out var handSpacePickupRotation);
			tool.HolderInfo = ToolHolderInfo.HeldByPlayer(base.photonView.viewID, handSpacePickupPosition, handSpacePickupRotation, tool.transform.GetLocalUniformScale());
			return true;
		}
		return false;
	}

	public void LocalLockHeldTool()
	{
		if (ThisPlayer.isLocal && !(HeldTool == null))
		{
			HeldTool.IsLocked = true;
		}
	}

	public bool LocalUnlockHeldTool()
	{
		if (!ThisPlayer.isLocal || HeldTool == null)
		{
			return false;
		}
		if (localHeldToolLockedOnRespawn)
		{
			return false;
		}
		if (ToolUnlockBehaviorOverride != null && ToolUnlockBehaviorOverride())
		{
			return false;
		}
		HeldTool.IsLocked = false;
		return true;
	}

	public void LocalLockHeldToolOnRespawn(bool localLocked)
	{
		if (HeldTool == null)
		{
			localHeldToolLockedOnRespawn = false;
			droppedHeldToolDuringRespawn = false;
			return;
		}
		bool flag = localHeldToolLockedOnRespawn;
		if (flag == localLocked)
		{
			return;
		}
		localHeldToolLockedOnRespawn = localLocked;
		if (!localHeldToolLockedOnRespawn)
		{
			if (droppedHeldToolDuringRespawn)
			{
				TryReleaseTool(Vector3.zero, Vector3.zero);
			}
			droppedHeldToolDuringRespawn = false;
		}
	}

	private void GetToolPickupPositionAndRotation(Tool tool, bool inPhysicalPickupRange, bool inMyOtherHand, bool forceSnapPosition, out Vector3 handSpacePickupPosition, out Quaternion handSpacePickupRotation)
	{
		bool flag = (inPhysicalPickupRange && (inMyOtherHand || tool.AlwaysPhysicalPickupOffCenter)) || tool.GravityPickupMode == Tool.GravityPickup.MAINTAIN_POSITION_MAINTAIN_ORIENTATION;
		if (!forceSnapPosition && flag)
		{
			handSpacePickupRotation = base.transform.InverseTransformRotation(tool.transform.rotation);
			handSpacePickupPosition = base.transform.InverseTransformPoint(tool.transform.position);
		}
		else if (!forceSnapPosition && tool.GravityPickupMode == Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION)
		{
			Vector3 vector = ((!(tool.HighlightedCollider != null)) ? tool.transform.position : tool.HighlightedCollider.transform.position);
			Vector3 vector2 = vector - base.transform.position;
			Vector3 gravityPickupDirection = GravityPickupDirection;
			if (Physics.Raycast(base.transform.position, gravityPickupDirection, out var hitInfo, 2f * vector2.magnitude, 1267082240, QueryTriggerInteraction.Ignore))
			{
				vector = hitInfo.point;
			}
			Vector3 position = base.transform.position + tool.transform.position - vector;
			handSpacePickupPosition = base.transform.InverseTransformPoint(position);
			handSpacePickupRotation = base.transform.InverseTransformRotation(tool.transform.rotation);
		}
		else
		{
			tool.GetHolderSpaceHandPickupTransform(base.transform, Type == HandType.Left, out handSpacePickupPosition, out handSpacePickupRotation);
		}
	}

	public bool TryReleaseTool(Vector3 releaseVelocity, Vector3 releaseAngularVelocity)
	{
		if (localHeldToolLockedOnRespawn)
		{
			droppedHeldToolDuringRespawn = true;
			return false;
		}
		if (HeldTool != null)
		{
			HeldTool.SetReleaseVelocity(releaseVelocity, releaseAngularVelocity);
			HeldTool.HolderInfo = ToolHolderInfo.NotHeld;
			ClearHoveredTool();
		}
		return true;
	}

	public void ResetGravityPickupParameters()
	{
		GravityPickupFingerOffset = defaultGravityPickupFingerOffset;
		GravityPickupCapsuleLength = defaultGravityPickupCapsuleLength;
		GravityPickupCapsuleRadius = defaultGravityPickupCapsuleRadius;
		GravityPickupSphereRadius = defaultGravityPickupSphereRadius;
	}

	public void AddIntersectingUIRegion(GameObject region, bool forceRegion = false)
	{
		if (forceRegion && !forceUIRegions.Contains(region))
		{
			forceUIRegions.Add(region);
		}
		else if (!forceRegion && !uiRegions.Contains(region))
		{
			uiRegions.Add(region);
		}
	}

	public void RemoveIntersectingUIRegion(GameObject region, bool forceRegion = false)
	{
		if (forceRegion && forceUIRegions.Contains(region))
		{
			forceUIRegions.Remove(region);
		}
		else if (!forceRegion && uiRegions.Contains(region))
		{
			uiRegions.Remove(region);
		}
	}

	public void DisableMenuLaser()
	{
		menuLaser.enabled = false;
	}

	public void UpdateMenuLaser(Vector3 menuTargetPosition, bool clickPressed, bool uiSelected)
	{
		menuLaser.enabled = true;
		Vector3 normalized = (menuTargetPosition - menuHandVisibleLaserStartPosition.position).normalized;
		menuLaser.SetPosition(0, menuHandVisibleLaserStartPosition.position);
		menuLaser.SetPosition(1, menuTargetPosition - normalized * menuLaser.widthMultiplier / 2f);
		Color black = Color.black;
		menuLaser.startColor = black;
		Color endColor = Color.white * GetMenuLaserAlpha(menuTargetPosition, clickPressed, uiSelected);
		menuLaser.endColor = endColor;
	}

	public bool IsMenuLaserEnabled()
	{
		return menuLaser.enabled;
	}

	public GestureTarget GetGestureTarget(out Vector3 menuTargetPosition, Ray? overrideRay = null)
	{
		float num = 40f;
		menuTargetPosition = menuHandVisibleLaserStartPosition.position + menuHandVisibleLaserStartPosition.forward * num;
		GestureTarget result = null;
		RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
		Ray ray = ((!overrideRay.HasValue) ? new Ray(menuHandVisibleLaserStartPosition.position, menuHandVisibleLaserStartPosition.forward) : overrideRay.Value);
		int num2 = Physics.RaycastNonAlloc(ray, iMMEDIATE_RAYCAST_HITS, num, 496383488, QueryTriggerInteraction.Collide);
		for (int i = 0; i < num2; i++)
		{
			RaycastHit raycastHit = iMMEDIATE_RAYCAST_HITS[i];
			GestureTarget gestureTarget = raycastHit.collider.GetGestureTarget();
			if (gestureTarget != null)
			{
				menuTargetPosition = raycastHit.point;
				result = gestureTarget;
				break;
			}
		}
		return result;
	}

	public void UpdateGestureLaser(bool tryConfirmGestureTarget)
	{
		menuLaser.enabled = true;
		Vector3 menuTargetPosition;
		GestureTarget gestureTarget = GetGestureTarget(out menuTargetPosition);
		menuLaser.SetPosition(0, menuHandVisibleLaserStartPosition.position);
		menuLaser.SetPosition(1, menuTargetPosition);
		Color black = Color.black;
		menuLaser.startColor = black;
		Color endColor = Color.green * ((!(gestureTarget != null)) ? 0.55f : 0.9f);
		menuLaser.endColor = endColor;
		if (gestureTarget != null && tryConfirmGestureTarget)
		{
			gestureTarget.ShowPointConfirmation(this);
			ExpressoInfoGestureActive = false;
		}
	}

	private void OnToolHolderChanged(Tool tool)
	{
		if (tool.HolderHand == this)
		{
			if (HeldTool != tool)
			{
				if (HeldTool != null)
				{
					OnReleaseTool();
				}
				OnPickupTool(tool);
			}
		}
		else if (HeldTool == tool)
		{
			OnReleaseTool();
		}
	}

	private void OnPickupTool(Tool tool)
	{
		PlayerHandCollider[] array = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array)
		{
			if (playerHandCollider != null)
			{
				playerHandCollider.DisableHandToolCollisions(tool);
			}
		}
		HeldTool = tool;
		ClearHoveredTool();
		LocalUpdateVisualState();
		bool visible = IsVisualStateActive(VisualState.HeldTool);
		bool teleporterIsVisible = IsVisualStateActive(VisualState.TeleportHand);
		HeldTool.SetVisible(visible, teleporterIsVisible);
		Vibrate(50);
		if (isLocal && ThisPlayer.BlobShadowProjector != null)
		{
			tool.AddBlobShadowCasters(ThisPlayer.BlobShadowProjector);
		}
		if (this.PickupToolEvent != null)
		{
			this.PickupToolEvent(this, tool);
		}
	}

	private void OnReleaseTool()
	{
		PlayerHandCollider[] array = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array)
		{
			if (playerHandCollider != null)
			{
				playerHandCollider.ReEnableHandToolCollisions(HeldTool);
			}
		}
		if (isLocal && ThisPlayer.BlobShadowProjector != null && HeldTool != null)
		{
			HeldTool.RemoveBlobShadowCasters(ThisPlayer.BlobShadowProjector);
		}
		if (this.ReleaseToolEvent != null)
		{
			this.ReleaseToolEvent(this, HeldTool);
		}
		HeldTool = null;
	}

	public void DisableCollisionForThrowRelease(Tool tool)
	{
		PlayerHandCollider[] array = handColliders;
		foreach (PlayerHandCollider playerHandCollider in array)
		{
			if (playerHandCollider != null)
			{
				playerHandCollider.DisableHandToolCollisions(tool);
				playerHandCollider.ReEnableHandToolCollisions(tool);
			}
		}
	}

	public void Vibrate(int milliseconds = 1, float intensity = 1f)
	{
		if (this.VibrateEvent != null)
		{
			this.VibrateEvent(this, milliseconds, intensity);
		}
	}

	public static void ConnectHandshake(PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
			if (!slaveHand.RigidbodyPickup.IsAttachedTo(masterHand.RigidbodyEx))
			{
				masterHand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: true);
				slaveHand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: true);
				Vector3 holderSpacePickupPosition = masterHand.transform.InverseTransformPoint(masterHand.handshakeConnectionTransform.position);
				Quaternion holderSpacePickupRotation = masterHand.transform.InverseTransformRotation(masterHand.handshakeConnectionTransform.rotation);
				slaveHand.RigidbodyPickup.Pickup(masterHand.RigidbodyEx, holderSpacePickupPosition, holderSpacePickupRotation);
			}
		}
	}

	public static void BreakHandshake(PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
			masterHand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: false);
			slaveHand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: false);
			slaveHand.RigidbodyPickup.Release();
		}
	}

	public static void ConnectCollisionGesture(PlayerHandGestures.Gesture gesture, PlayerHand lhs, PlayerHand rhs)
	{
		if (lhs == null || rhs == null)
		{
			return;
		}
		GetGestureHandRoles(lhs, rhs, out var masterHand, out var slaveHand);
		if (!slaveHand.RigidbodyPickup.IsAttachedTo(masterHand.RigidbodyEx))
		{
			Transform transform = ((gesture != PlayerHandGestures.Gesture.Fistbump) ? masterHand.highFiveConnectionTransform : masterHand.fistbumpConnectionTransform);
			if (transform == null)
			{
				transform = slaveHand.transform;
			}
			Vector3 holderSpacePickupPosition = masterHand.transform.InverseTransformPoint(transform.position);
			Quaternion holderSpacePickupRotation = masterHand.transform.InverseTransformRotation(slaveHand.transform.rotation);
			slaveHand.RigidbodyPickup.Pickup(masterHand.RigidbodyEx, holderSpacePickupPosition, holderSpacePickupRotation);
		}
	}

	public static void BreakCollisionGesture(PlayerHandGestures.Gesture gesture, PlayerHand lhs, PlayerHand rhs)
	{
		if (!(lhs == null) && !(rhs == null))
		{
			GetGestureHandRoles(lhs, rhs, out var _, out var slaveHand);
			slaveHand.RigidbodyPickup.Release();
		}
	}

	public static void ConnectNonPlayerGesture(PlayerHandGestures.Gesture gesture, PlayerHand hand, NonPlayerGestureTarget target)
	{
		if (!(hand == null) && !(target == null) && !target.RigidbodyPickup.IsAttachedTo(hand.RigidbodyEx))
		{
			Transform transform = null;
			switch (gesture)
			{
			case PlayerHandGestures.Gesture.Fistbump:
				transform = hand.fistbumpConnectionTransform;
				break;
			case PlayerHandGestures.Gesture.Highfive:
				transform = hand.highFiveConnectionTransform;
				break;
			case PlayerHandGestures.Gesture.HandshakeStart:
				transform = hand.handshakeConnectionTransform;
				hand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: true);
				break;
			default:
				transform = target.transform;
				break;
			}
			Vector3 holderSpacePickupPosition = hand.transform.InverseTransformPoint(transform.position);
			Quaternion holderSpacePickupRotation = hand.transform.InverseTransformRotation(target.transform.transform.rotation);
			target.RigidbodyPickup.Pickup(hand.RigidbodyEx, holderSpacePickupPosition, holderSpacePickupRotation);
		}
	}

	public static void BreakNonPlayerGesture(PlayerHandGestures.Gesture gesture, PlayerHand hand, NonPlayerGestureTarget target)
	{
		target.RigidbodyPickup.Release();
		target.FinishGesture(gesture);
		if (gesture == PlayerHandGestures.Gesture.HandshakeCancel || gesture == PlayerHandGestures.Gesture.HandshakeSuccess)
		{
			hand.HandAnimator.SetBool(HANDSHAKE_ANIMATOR_ID, value: false);
		}
	}

	private static void GetGestureHandRoles(PlayerHand hand1, PlayerHand hand2, out PlayerHand masterHand, out PlayerHand slaveHand)
	{
		if (hand1.isLocal)
		{
			masterHand = hand1;
			slaveHand = hand2;
		}
		else if (hand2.isLocal)
		{
			masterHand = hand2;
			slaveHand = hand1;
		}
		else if (hand1.photonView.viewID < hand2.photonView.viewID)
		{
			masterHand = hand1;
			slaveHand = hand2;
		}
		else
		{
			masterHand = hand2;
			slaveHand = hand1;
		}
	}

	public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
	{
		if (stream.isReading)
		{
			OpenClosedAxis = (float)stream.ReceiveNext();
		}
		else
		{
			stream.SendNext(OpenClosedAxis);
		}
		PlayerHandRemote.HandlePhotonSerializeView(stream, info);
	}

	private void OnDrawGizmos()
	{
		if (UnityEngine.Application.isPlaying)
		{
			Gizmos.color = Color.green;
			float gravityPickupCapsuleRadius = GravityPickupCapsuleRadius;
			float num = GravityPickupCapsuleLength - 2f * gravityPickupCapsuleRadius;
			int num2 = (int)(num / (2f * gravityPickupCapsuleRadius));
			Vector3 gravityPickupDirection = GravityPickupDirection;
			Vector3 vector = num / (float)num2 * gravityPickupDirection;
			Vector3 vector2 = GravityPickupOrigin + gravityPickupDirection * gravityPickupCapsuleRadius;
			for (int i = 0; i < num2; i++)
			{
				Gizmos.DrawWireSphere(vector2 + i * vector, gravityPickupCapsuleRadius);
			}
			Gizmos.DrawWireSphere(vector2 + num * gravityPickupDirection, gravityPickupCapsuleRadius);
		}
	}

	public static PlayerHand Find(int photonViewId)
	{
		PhotonView photonView = PhotonView.Find(photonViewId);
		if (photonView != null)
		{
			return photonView.GetComponent<PlayerHand>();
		}
		return null;
	}
}
public class PlayerHandCollider : PlayerCollider
{
	private BoxCollider boxCollider;

	private Tool heldTool;

	private Tool lastReleasedTool;

	private float timeOfLastContactWithReleasedTool;

	private const float TIME_SINCE_LAST_CONTACT_THRESHOLD = 0.25f;

	private const int MAX_RAYCAST_HIT = 8;

	private static RaycastHit[] hits = new RaycastHit[8];

	private Vector3 previousPosition = Vector3.zero;

	private bool colliderNeedsReenable;

	private void Update()
	{
		if (!colliderNeedsReenable)
		{
			return;
		}
		if (lastReleasedTool == null)
		{
			colliderNeedsReenable = false;
			lastReleasedTool = null;
			boxCollider.enabled = true;
			return;
		}
		Vector3 boxCenter = base.transform.TransformPoint(boxCollider.center);
		if ((ThisPlayer.isLocal || UnityEngine.Time.unscaledTime - timeOfLastContactWithReleasedTool > 0.25f) && CheckForHitFast(boxCenter))
		{
			timeOfLastContactWithReleasedTool = UnityEngine.Time.unscaledTime;
		}
		if (UnityEngine.Time.unscaledTime - timeOfLastContactWithReleasedTool > 0.25f)
		{
			lastReleasedTool = null;
			boxCollider.enabled = true;
			colliderNeedsReenable = false;
		}
		previousPosition = boxCenter;
	}

	private bool CheckForHitFast(Vector3 boxCenter)
	{
		Vector3 vector = boxCenter - previousPosition;
		Ray ray = new Ray(previousPosition, boxCenter);
		float magnitude = vector.magnitude;
		float num = boxCollider.size.x / 2f * base.transform.lossyScale.x;
		float num2 = boxCollider.size.y / 2f * base.transform.lossyScale.y;
		float num3 = boxCollider.size.z / 2f * base.transform.lossyScale.z;
		float num4 = Mathf.Max(num, num2, num3);
		float num5 = num4 * num4;
		for (int i = 0; i < lastReleasedTool.Colliders.Count; i++)
		{
			ReadOnlyCollection<Collider> readOnlyCollection = lastReleasedTool.Colliders[i].PhysicsColliders;
			for (int j = 0; j < readOnlyCollection.Count; j++)
			{
				Collider collider = readOnlyCollection[j];
				if (collider.enabled && collider.gameObject.activeInHierarchy)
				{
					if (collider.Raycast(ray, out var _, magnitude))
					{
						return true;
					}
					Vector3 vector2 = previousPosition;
					if (magnitude != 0f)
					{
						Vector3 vector3 = vector / magnitude;
						float num6 = Mathf.Clamp(Vector3.Dot(vector3, collider.bounds.center - previousPosition), 0f, magnitude);
						vector2 = previousPosition + num6 * vector3;
					}
					Vector3 vector4 = collider.ClosestPoint(vector2);
					float sqrMagnitude = (vector4 - vector2).sqrMagnitude;
					if (sqrMagnitude < num5)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private bool CheckForHitSlow(Vector3 boxCenter)
	{
		Vector3 vector = boxCenter - previousPosition;
		int num = Physics.BoxCastNonAlloc(boxCenter, 1.05f * boxCollider.size / 2f, vector.normalized, hits, base.transform.rotation, 495330300f);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = hits[i].collider.GetColliderTool();
			if (colliderTool != null && colliderTool == lastReleasedTool)
			{
				return true;
			}
		}
		return false;
	}

	protected override void Awake()
	{
		base.Awake();
		boxCollider = GetComponent<BoxCollider>();
		previousPosition = base.transform.TransformPoint(boxCollider.center);
	}

	protected override void OnEnable()
	{
		if (lastReleasedTool == null)
		{
			base.OnEnable();
		}
		previousPosition = base.transform.TransformPoint(boxCollider.center);
	}

	public void DisableHandToolCollisions(Tool tool)
	{
		if (!base.IsTrigger && !(tool == heldTool) && !(tool == null))
		{
			heldTool = tool;
			lastReleasedTool = null;
			boxCollider.enabled = false;
		}
	}

	public void ReEnableHandToolCollisions(Tool tool)
	{
		if (!base.IsTrigger && !(tool != heldTool) && !(tool == null))
		{
			heldTool = null;
			lastReleasedTool = tool;
			timeOfLastContactWithReleasedTool = UnityEngine.Time.unscaledTime;
			previousPosition = base.transform.TransformPoint(boxCollider.center);
			colliderNeedsReenable = true;
		}
	}
}
