	public bool ApplyRotation(object requester, float yaw)
	{
		if (requester == null || requester != activeRotationOwner)
		{
			return false;
		}
		if (yaw != 0f)
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.transform.InverseTransformPoint(SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position);
			Vector3 point = thisPlayer.TrackingSpace.RigidbodyEx.TargetTransform.TransformPoint(position);
			thisPlayer.TrackingSpace.RigidbodyEx.TargetTransform.RotateAround(point, thisPlayer.TrackingSpace.RigidbodyEx.TargetTransform.up, yaw);
		}
		return true;
	}

