	private void OnPersonalSpaceDistanceChange()
	{
		if (isLocal)
		{
			if (PlayerLocomotion.LocalPlayerPersonalSpaceDistanceChanged != null)
			{
				PlayerLocomotion.LocalPlayerPersonalSpaceDistanceChanged();
			}
		}
		else if (Player.LocalPlayerExists)
		{
			float num = PersonalSpaceDistance;
			if (Player.LocalPlayerExists)
			{
				num = Mathf.Max(num, Player.LocalPlayer.PlayerLocomotion.PersonalSpaceDistance);
			}
			float num2 = Mathf.Max(0.25f, num - 0.25f);
			if (personalSpaceCollider.radius != num2)
			{
				personalSpaceCollider.radius = num2;
			}
		}
	}

