	protected override void Awake()
	{
		base.Awake();
		_personalSpaceDistance = new SynchronizedPlayerField<float>(base.owner, "PlayerTeleportBuffer", 0f, OnPersonalSpaceDistanceChange);
		TeleportOnCooldown = false;
		TeleportCooldownValue = 0f;
		movementAllowed = true;
		rotationAllowed = true;
		lastMovementTime = Now;
		thisPlayer = GetComponent<Player>();
		childNetworkTransforms = GetComponentsInChildren<NetworkTransform>(includeInactive: true);
		AddTeleportCooldown(0.1f, this, int.MinValue);
		AddTeleportMaxHorizontalDistance(6f, this, int.MinValue);
		AddTeleportMaxDropHeight(999.9f, this, int.MinValue);
		AddTeleportMaxHorizontalSurfaceAngle(87f, this, int.MinValue);
		AddTeleportMaxHorizontalDistanceScalar(1f, this, int.MinValue);
		worldBounds = RecRoom.Networking.BitPacker.VALID_POSITION_BOUNDS;
		worldBounds.Expand(-6f);
		this.QueueUpdate(OnPostUpdate, Scheduler.QueueType.PostUpdate);
	}

	private void Start()
	{
		if (thisPlayer.isLocal)
		{
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.PlayerTypeChange = (Action)Delegate.Combine(instance.PlayerTypeChange, new Action(OnPersonalSpaceSettingsChange));
			LocalPlayerController instance2 = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance2.PlayerTypeChange = (Action)Delegate.Combine(instance2.PlayerTypeChange, new Action(OnPlayerTypeChanged));
			SingletonMonoBehaviour<SettingsManager>.Instance.PersonalSpaceDistanceChanged += OnPersonalSpaceSettingsChange;
			OnPersonalSpaceSettingsChange();
		}
		else
		{
			LocalPlayerPersonalSpaceDistanceChanged += OnPersonalSpaceDistanceChange;
			OnPersonalSpaceDistanceChange();
		}
		trail = UnityEngine.Object.Instantiate(playerTrailPrefab);
		thisPlayer.SetParentPlayerRoot(trail.transform);
		thisPlayer.DisablePersonalBubbleForFriendsChangedEvent += new Action(OnPersonalSpaceDistanceChange);
		if (thisPlayer.isLocal)
		{
			trail.gameObject.SetLayerRecursively(Layers.HiddenInFirstPerson);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		LocalPlayerPersonalSpaceDistanceChanged -= OnPersonalSpaceDistanceChange;
		if (SingletonMonoBehaviour<CameraRig>.Instance != null)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopTeleportVignette(0f);
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopContinuousRotationVignette(0f);
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSwipeRotateVignette(0f);
		}
		if (isLocal && SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.PersonalSpaceDistanceChanged -= OnPersonalSpaceSettingsChange;
		}
		if (isLocal && SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
		{
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.PlayerTypeChange = (Action)Delegate.Remove(instance.PlayerTypeChange, new Action(OnPersonalSpaceSettingsChange));
			LocalPlayerController instance2 = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance2.PlayerTypeChange = (Action)Delegate.Remove(instance2.PlayerTypeChange, new Action(OnPlayerTypeChanged));
		}
	}

