	private void OnPostUpdate()
	{
		AuthorityApplyAccumulatedMovement();
		accumulatedDisplacement = Vector3.zero;
		accumulatedCollisionDisplacement = Vector3.zero;
	}

	public void TeleportTo(Vector3 destinationPlayerPosition, Vector3? destinationForward, bool canCarryTools, RigidbodyEx teleportRelativeRigidbody, bool cancelCurrentTeleport = false, bool isLedgeClimb = false)
	{
		if (cancelCurrentTeleport)
		{
			CancelTeleport();
		}
		if (TeleportRunning || RotationBeingModified)
		{
			return;
		}
		if (!canCarryTools)
		{
			thisPlayer.ReleaseToolsFromBothHands();
		}
		TeleportationPortal.LocalPlayerSeat = null;
		if (thisPlayer.LeftHand.HeldTool != null)
		{
			thisPlayer.LeftHand.HeldTool.OnPlayerTeleport(teleportBlindDuration);
		}
		if (thisPlayer.RightHand.HeldTool != null)
		{
			thisPlayer.RightHand.HeldTool.OnPlayerTeleport(teleportBlindDuration);
		}
		PlayerLocomotion.LocalPlayerStartedTeleportEvent.SafeInvoke();
		Vector3 currentFloorPosition = thisPlayer.CurrentFloorPosition;
		if (destinationForward.HasValue && destinationForward.HasValue)
		{
			teleportSchedule = SingletonMonoBehaviour<Scheduler>.Instance.Run(this, RunDiscontinuousTeleportCoroutine(currentFloorPosition, destinationPlayerPosition, destinationForward.Value));
		}
		else
		{
			if (isLedgeClimb)
			{
				base.photonView.RpcAll(RpcOnLedgeClimb);
			}
			teleportSchedule = SingletonMonoBehaviour<Scheduler>.Instance.Run(this, RunContinuousTeleportCoroutine(currentFloorPosition, destinationPlayerPosition, teleportRelativeRigidbody, isLedgeClimb));
		}
		if (!isLedgeClimb)
		{
			base.photonView.RpcAll(RpcTeleport, currentFloorPosition, destinationPlayerPosition);
		}
	}

	public void MoveTo(Vector3 playerFloorPosition, bool insertDiscontinuity = true)
	{
		MoveTo(playerFloorPosition, thisPlayer.TrackingSpace.RigidbodyEx.TargetTransform.forward, insertDiscontinuity, CoordinateSpace.TRACKING_SPACE);
	}

	public void MoveTo(Vector3 playerFloorPosition, Vector3 forward, bool insertDiscontinuity = true, CoordinateSpace forwardVectorCoordinateSpace = CoordinateSpace.PLAYER_SPACE, bool forceSetHeight = false)
	{
		SingletonMonoBehaviour<CullingGroupManager>.Instance.PauseUntilEndOfFrame();
		Vector3 rigPosition;
		Quaternion rigRotation;
		if (SupportsRoomScaleMovement)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.TransformHeadFloorToRigPositionAndOrientation(playerFloorPosition, forward, forwardVectorCoordinateSpace == CoordinateSpace.PLAYER_SPACE, out rigPosition, out rigRotation);
		}
		else
		{
			rigPosition = playerFloorPosition;
			rigRotation = Quaternion.LookRotation(forward, Vector3.up);
		}
		TranslateTrackingSpace(rigPosition, rigRotation, Vector3.zero, Vector3.zero, insertDiscontinuity, forceSetHeight);
		if (insertDiscontinuity)
		{
			NetworkTransform[] array = childNetworkTransforms;
			foreach (NetworkTransform networkTransform in array)
			{
				networkTransform.InsertPositionDiscontinuity();
			}
			if (thisPlayer.LeftHand.HeldTool != null)
			{
				thisPlayer.LeftHand.HeldTool.SnapToHand();
			}
			if (thisPlayer.RightHand.HeldTool != null)
			{
				thisPlayer.RightHand.HeldTool.SnapToHand();
			}
		}
	}

	private void TranslateTrackingSpace(Vector3 position, Quaternion rotation, Vector3 linearVelocity, Vector3 angularVelocity, bool discontinuity, bool forceSetHeight)
	{
		position = position.ValueOrZeroIfBogus();
		rotation = rotation.ValueOrIdentityIfBogus();
		if (!worldBounds.Contains(position))
		{
			position = worldBounds.ClosestPoint(position);
		}
		if (thisPlayer.TrackingSpace.RigidbodyEx.hasParent)
		{
			Transform targetTransform = thisPlayer.TrackingSpace.RigidbodyEx.parent.TargetTransform;
			Vector3 vector = targetTransform.InverseTransformPoint(position);
			Quaternion quaternion = targetTransform.InverseTransformRotation(rotation);
			if (discontinuity)
			{
				thisPlayer.TrackingSpace.RigidbodyEx.SetDiscontinuousLocalPositionAndLocalRotation(vector, quaternion);
				return;
			}
			thisPlayer.TrackingSpace.RigidbodyEx.targetLocalPosition = vector;
			thisPlayer.TrackingSpace.RigidbodyEx.targetLocalRotation = quaternion;
			thisPlayer.TrackingSpace.RigidbodyEx.localVelocity = targetTransform.InverseTransformVector(linearVelocity);
			thisPlayer.TrackingSpace.RigidbodyEx.localAngularVelocity = targetTransform.InverseTransformVector(angularVelocity);
		}
		else if (discontinuity)
		{
			thisPlayer.TrackingSpace.RigidbodyEx.SetDiscontinuousPositionAndRotation(position, rotation);
		}
		else
		{
			thisPlayer.TrackingSpace.RigidbodyEx.targetPosition = position;
			thisPlayer.TrackingSpace.RigidbodyEx.targetRotation = rotation;
			thisPlayer.TrackingSpace.RigidbodyEx.velocity = linearVelocity;
			thisPlayer.TrackingSpace.RigidbodyEx.angularVelocity = angularVelocity;
		}
	}

	public void PauseGravity(object token)
	{
		_gravityPausedFlag.Add(token);
	}

	public void ResumeGravity(object token)
	{
		_gravityPausedFlag.Remove(token);
	}

	public void Move(Vector3 velocity, bool withCollision = true)
	{
		velocity = velocity.ValueOrZeroIfBogus();
		bool hasTokens = movementCollisionRestrictionFlag.HasTokens;
		if (withCollision && !hasTokens)
		{
			accumulatedCollisionDisplacement += velocity * UnityEngine.Time.deltaTime;
		}
		else
		{
			accumulatedDisplacement += velocity * UnityEngine.Time.deltaTime;
		}
	}

	public void RequestJump(float jumpHeight)
	{
		if (CanJump)
		{
			requestedJump = true;
			requestedJumpSpeed = GetJumpSpeed(jumpHeight);
		}
	}

	public bool CanClimb(out ClimbType climbType, out Vector3 climbableSurfaceWallNormal)
	{
		climbType = ClimbType.NONE;
		climbableSurfaceWallNormal = Vector3.zero;
		if (!IsNearClimbableSurface)
		{
			return false;
		}
		climbType = previousMovementData.ClimbType;
		climbableSurfaceWallNormal = previousMovementData.ClimbWallNormal;
		if (climbType == ClimbType.LADDER)
		{
			return true;
		}
		bool flag = !IsGrounded && hasPreviousValidMovementData && previousMovementData.GravityVelocity.y <= 0f;
		if (LatestClimbHeightType == ClimbHeightType.TALL && flag)
		{
			return false;
		}
		if (LatestClimbHeightType == ClimbHeightType.VERY_SHORT && !flag)
		{
			return false;
		}
		return true;
	}

	public void Climb()
	{
		if (!TeleportRunning && CanClimb(out var _, out var _) && hasPreviousValidMovementData)
		{
			requestedJump = false;
			hasJumped = false;
			previousMovementData.GravityVelocity = Vector3.zero;
			previousMovementData.IsNearClimbableSurface = false;
			LatestClimbWallNormal = previousMovementData.ClimbWallNormal;
			LatestClimbType = previousMovementData.ClimbType;
			LatestClimbHeightType = LedgeDistanceToLedgeHeightType(previousMovementData.ClimbDestinationDistanceFromPlayer);
			Vector3 destinationPlayerPosition = previousMovementData.ClimbDestination - Vector3.up * (0.25f + skinThickness);
			TeleportTo(destinationPlayerPosition, null, canCarryTools: true, null, cancelCurrentTeleport: false, isLedgeClimb: true);
		}
	}

	public void CutoffJump(float cutoffHeight)
	{
		if (!IsGrounded)
		{
			float jumpSpeed = GetJumpSpeed(cutoffHeight);
			if (requestedJump)
			{
				requestedJumpSpeed = jumpSpeed;
			}
			else if (hasPreviousValidMovementData && !(Vector3.Dot(previousMovementData.GravityVelocity, Vector3.up) <= 0f))
			{
				previousMovementData.GravityVelocity = Vector3.ClampMagnitude(previousMovementData.GravityVelocity, jumpSpeed);
			}
		}
	}

	private void AuthorityApplyAccumulatedMovement()
	{
		if (base.hasAuthority && !TeleportRunning)
		{
			Vector3 vector = accumulatedDisplacement;
			if (!movementCollisionRestrictionFlag.HasTokens)
			{
				vector += RunMovementCollision(accumulatedCollisionDisplacement);
			}
			Vector3 targetPosition = thisPlayer.TrackingSpace.RigidbodyEx.targetPosition;
			Quaternion targetRotation = thisPlayer.TrackingSpace.RigidbodyEx.targetRotation;
			TranslateTrackingSpace(targetPosition + vector, targetRotation, vector / UnityEngine.Time.deltaTime, Vector3.zero, discontinuity: false, forceSetHeight: false);
		}
	}

	private bool TryReInitializeMovementData(int layerMask, CollisionDetection.ColliderFilter colliderFilter, ref SurfaceSweepData movementData, ref bool movementDataIsValid, ref Vector3 actualDisplacement)
	{
		if (movementData.HasParent)
		{
			if (movementData.Parent == null)
			{
				movementDataIsValid = false;
			}
			else
			{
				movementData.UpdateWorldSpacePositions();
			}
		}
		if (SupportsRoomScaleMovement)
		{
			Vector3 capsuleBottomPosition;
			Vector3 capsuleTopPosition;
			Vector3 capsuleSurfacePosition;
			bool flag = TryCalculateInstantaneousCapsulePosition(layerMask, colliderFilter, movementData.IsGrounded, movementData.GroundNormal, movementDataIsValid, out capsuleBottomPosition, out capsuleTopPosition, out capsuleSurfacePosition);
			if (!flag && !movementDataIsValid)
			{
				return false;
			}
			if (flag)
			{
				if (!GravityIsPaused)
				{
					actualDisplacement += Vector3.Project(capsuleSurfacePosition - thisPlayer.TrackingSpace.RigidbodyEx.physicsPosition, Vector3.up);
				}
				movementData.Parent = thisPlayer.TrackingSpace.RigidbodyEx.parent;
				movementData.CapsuleBottomPositionWorldSpace = capsuleBottomPosition;
				movementData.CapsuleTopPositionWorldSpace = capsuleTopPosition;
			}
		}
		else
		{
			float num = 0.25f + skinThickness;
			float num2 = 1.7f - CrouchHeightOffset + 2f * skinThickness;
			Vector3 physicsPosition = thisPlayer.TrackingSpace.RigidbodyEx.physicsPosition;
			float num3 = num2 - 2f * num;
			Vector3 capsuleBottomPositionWorldSpace = physicsPosition + Vector3.up * num;
			Vector3 capsuleTopPositionWorldSpace = physicsPosition + Vector3.up * (num + num3);
			movementData.Parent = thisPlayer.TrackingSpace.RigidbodyEx.parent;
			movementData.CapsuleBottomPositionWorldSpace = capsuleBottomPositionWorldSpace;
			movementData.CapsuleTopPositionWorldSpace = capsuleTopPositionWorldSpace;
		}
		return true;
	}

	private bool TryCalculateInstantaneousCapsulePosition(int layerMask, CollisionDetection.ColliderFilter colliderFilter, bool isGrounded, Vector3 groundNormal, bool testGeometryOverlap, out Vector3 capsuleBottomPosition, out Vector3 capsuleTopPosition, out Vector3 capsuleSurfacePosition)
	{
		capsuleTopPosition = Vector3.zero;
		capsuleBottomPosition = Vector3.zero;
		capsuleSurfacePosition = Vector3.zero;
		Vector3 physicsPosition = thisPlayer.Head.RigidbodyEx.physicsPosition;
		Vector3 physicsPosition2 = thisPlayer.TrackingSpace.RigidbodyEx.physicsPosition;
		Vector3 vector = physicsPosition2 - physicsPosition;
		vector = Vector3.Project(vector, Vector3.up);
		Vector3 vector2 = physicsPosition + vector;
		float a = vector.magnitude + 0.25f;
		float num = Mathf.Min(a, 1.7f);
		float num2 = Mathf.Max(0.25f, num - 0.5f);
		Vector3 vector3 = vector2 + Vector3.up * (num2 + 0.25f);
		RaycastHit hit;
		switch (CollisionDetection.SweepSphere(vector3, 0.25f, -Vector3.up, num2, layerMask, colliderFilter, out hit))
		{
		case CollisionDetection.CollisionResult.OVERLAP:
			return false;
		case CollisionDetection.CollisionResult.MISS:
		{
			capsuleTopPosition = vector3;
			capsuleBottomPosition = vector3 - Vector3.up * num2;
			capsuleSurfacePosition = capsuleBottomPosition - Vector3.up * 0.25f;
			CollisionDetection.Raycast(capsuleBottomPosition, -Vector3.up, float.MaxValue, layerMask, colliderFilter, out var _);
			return true;
		}
		default:
			capsuleBottomPosition = vector3 - Vector3.up * (hit.distance - skinThickness);
			capsuleTopPosition = capsuleBottomPosition + Vector3.up * num2;
			capsuleSurfacePosition = capsuleBottomPosition - Vector3.up * 0.25f;
			if (testGeometryOverlap)
			{
				Vector3 planeNormal = ((!isGrounded) ? Vector3.up : groundNormal);
				Vector3 vector4 = MathExt.FindRayPlaneIntersectionPoint(physicsPosition, -Vector3.up, physicsPosition2, planeNormal);
				Vector3 lhs = capsuleSurfacePosition - vector4;
				if (Vector3.Dot(lhs, Vector3.up) > 0f && lhs.magnitude > stepHeight)
				{
					return false;
				}
			}
			return true;
		}
	}

	private Vector3 RunMovementCollision(Vector3 desiredDisplacement)
	{
		Vector3 actualDisplacement = Vector3.zero;
		int layerMask = 67128320;
		CollisionDetection.ColliderFilter colliderFilter = CollisionDetection.CollidesWithMovement;
		if (!TryReInitializeMovementData(layerMask, colliderFilter, ref previousMovementData, ref hasPreviousValidMovementData, ref actualDisplacement))
		{
			return Vector3.zero;
		}
		SurfaceSweepData currentMovementData = previousMovementData;
		bool isGrounded = currentMovementData.IsGrounded;
		ApplyJumpingAndGravityMovement(ref currentMovementData, ref desiredDisplacement);
		if (desiredDisplacement.sqrMagnitude < 1.0000001E-06f && currentMovementData.IsGrounded)
		{
			colliderFilter = CollisionDetection.CollidesWithMovementIgnoringPlayersAndEnemies;
		}
		RunMovementSweeps(desiredDisplacement, layerMask, colliderFilter, ref currentMovementData);
		actualDisplacement += currentMovementData.CapsuleBottomPositionWorldSpace - previousMovementData.CapsuleBottomPositionWorldSpace;
		previousMovementData = currentMovementData;
		hasPreviousValidMovementData = true;
		if (currentMovementData.IsGrounded)
		{
			if (!isGrounded)
			{
				base.photonView.RpcAll(RpcOnLand);
			}
			lastValidGroundNormal = currentMovementData.GroundNormal;
		}
		return actualDisplacement;
	}

	private void RunMovementSweeps(Vector3 desiredDisplacement, int layerMask, CollisionDetection.ColliderFilter colliderFilter, ref SurfaceSweepData currentData)
	{
		bool isGrounded = currentData.IsGrounded;
		SurfaceSweepIterative(desiredDisplacement, layerMask, colliderFilter, 8, ref currentData);
		if (isGrounded && !currentData.IsStepping && !GravityIsPaused)
		{
			Vector3 maxClampDisplacement = -Vector3.up * clampDistance;
			GroundClampIterative(maxClampDisplacement, layerMask, colliderFilter, 4, ref currentData);
		}
	}

	private void SurfaceSweepIterative(Vector3 desiredDisplacement, int layerMask, CollisionDetection.ColliderFilter colliderFilter, int maxIterationCount, ref SurfaceSweepData currentData)
	{
		if (currentData.IsTouchingWall)
		{
			Vector3 vector = Vector3.Project(desiredDisplacement, currentData.WallNormal);
			Vector3 vector2 = desiredDisplacement - vector;
			desiredDisplacement = vector2;
			if (Vector3.Dot(vector, currentData.WallNormal) > 0f)
			{
				desiredDisplacement += vector;
			}
		}
		Vector3 remainingDirection = desiredDisplacement.normalized;
		Vector3 vector3 = remainingDirection;
		float remainingDistance = desiredDisplacement.magnitude;
		if (remainingDistance <= 0.001f)
		{
			return;
		}
		if (currentData.IsGrounded)
		{
			remainingDirection = UnityExtensions.ProjectDirectionOntoSurface(remainingDirection, currentData.GroundNormal);
		}
		currentData.IsGrounded = false;
		currentData.IsStepping = false;
		currentData.IsTouchingWall = false;
		currentData.IsNearClimbableSurface = false;
		Vector3 zero = Vector3.zero;
		int i;
		for (i = 0; i < maxIterationCount; i++)
		{
			if (remainingDistance <= 0.001f)
			{
				break;
			}
			Vector3 vector4 = currentData.CapsuleBottomPositionWorldSpace + zero;
			Vector3 vector5 = currentData.CapsuleTopPositionWorldSpace + zero;
			RaycastHit hit;
			switch (CollisionDetection.SweepCapsule(vector4, vector5, 0.25f, remainingDirection, remainingDistance, layerMask, colliderFilter, out hit))
			{
			case CollisionDetection.CollisionResult.OVERLAP:
			{
				if (!CollisionDetection.DepenetrateCapsule(vector4, vector5, 0.25f + skinThickness, layerMask, colliderFilter, out var totalDepenetration))
				{
					return;
				}
				zero += totalDepenetration;
				break;
			}
			case CollisionDetection.CollisionResult.MISS:
				zero += remainingDirection * remainingDistance;
				remainingDistance = 0f;
				break;
			case CollisionDetection.CollisionResult.HIT:
				zero += remainingDirection * (hit.distance - skinThickness);
				switch (CollisionDetection.GetSurfaceType(hit.normal))
				{
				case CollisionDetection.SurfaceType.CEILING:
					remainingDistance = 0f;
					if (Vector3.Dot(hit.normal, currentData.GravityVelocity) <= 0f)
					{
						currentData.GravityVelocity = Vector3.zero;
					}
					break;
				case CollisionDetection.SurfaceType.FLOOR:
					currentData.IsGrounded = true;
					currentData.GroundNormal = hit.normal;
					remainingDistance = Mathf.Max(0f, remainingDistance - hit.distance);
					ProjectRemainingDisplacement(currentData.GroundNormal, ref remainingDirection, ref remainingDistance);
					break;
				case CollisionDetection.SurfaceType.WALL:
				{
					Vector3 stepPoint = Vector3.zero;
					Vector3 vector6 = -1f * Vector3.ProjectOnPlane(hit.normal, Vector3.up).normalized;
					if (FindStep(vector4, vector5, vector6, minStepForwardSearchDistance, layerMask, colliderFilter, out stepPoint))
					{
						currentData.IsStepping = true;
						if (!currentData.IsGrounded)
						{
							currentData.IsGrounded = true;
							currentData.GroundNormal = Vector3.up;
						}
						remainingDirection = UnityExtensions.ProjectDirectionOntoSurface(remainingDirection, hit.normal).normalized;
						break;
					}
					currentData.IsTouchingWall = true;
					currentData.WallNormal = hit.normal;
					if (Mathf.Abs(Vector3.Dot(vector3, Vector3.up)) <= 0.999f)
					{
						vector6 = Vector3.ProjectOnPlane(vector3, Vector3.up).normalized;
					}
					if (TryFindLadder(currentData, vector6, hit, out var ladderDestinationPosition))
					{
						SetClimbData(ref currentData, zero, ladderDestinationPosition, ClimbType.LADDER);
					}
					else
					{
						ClimbType climbType = FindClimbableLedge(vector4, vector5, vector6, 0.5f, layerMask, colliderFilter, out stepPoint);
						if (climbType != ClimbType.NONE)
						{
							SetClimbData(ref currentData, zero, stepPoint, climbType);
						}
					}
					remainingDistance = Mathf.Max(0f, remainingDistance - hit.distance);
					ProjectRemainingDisplacement(hit.normal, ref remainingDirection, ref remainingDistance);
					break;
				}
				}
				break;
			}
		}
		if (i >= maxIterationCount && zero.sqrMagnitude <= desiredDisplacement.sqrMagnitude * 0.25f * 0.25f)
		{
			currentData.IsGrounded = true;
			currentData.GroundNormal = Vector3.up;
		}
		currentData.CapsuleBottomPositionWorldSpace += zero;
		currentData.CapsuleTopPositionWorldSpace += zero;
	}

	private bool TryFindLadder(SurfaceSweepData currentData, Vector3 detectionDirection, RaycastHit hit, out Vector3 ladderDestinationPosition)
	{
		ladderDestinationPosition = Vector3.zero;
		TeleportationPortal teleportationPortal = ((!(hit.collider != null)) ? null : hit.collider.GetComponent<TeleportationPortal>());
		if (teleportationPortal == null || !teleportationPortal.IsLadder)
		{
			return false;
		}
		Vector3 vector = teleportationPortal.DestinationPosition + Vector3.up * CapsuleRadius;
		if ((vector - currentData.CapsuleBottomPositionWorldSpace).y <= 0.2f)
		{
			return false;
		}
		if (Vector3.Dot(currentData.WallNormal, detectionDirection) >= 0f)
		{
			return false;
		}
		if (Vector3.Dot(teleportationPortal.DestinationForward, detectionDirection) <= 0.5f)
		{
			return false;
		}
		ladderDestinationPosition = teleportationPortal.DestinationPosition;
		return true;
	}

	private void SetClimbData(ref SurfaceSweepData currentData, Vector3 displacement, Vector3 destinationPoint, ClimbType climbType)
	{
		Vector3 vector = currentData.CapsuleBottomPositionWorldSpace + displacement;
		float y = (destinationPoint - vector).y;
		if (y >= minLedgeClimbHeight)
		{
			currentData.IsNearClimbableSurface = true;
			currentData.ClimbDestination = destinationPoint;
			currentData.ClimbWallNormal = currentData.WallNormal;
			currentData.ClimbDestinationDistanceFromPlayer = y;
			currentData.ClimbType = climbType;
		}
	}

	private void GroundClampIterative(Vector3 maxClampDisplacement, int layerMask, CollisionDetection.ColliderFilter colliderFilter, int maxIterationCount, ref SurfaceSweepData currentData)
	{
		RaycastHit hit = default(RaycastHit);
		Vector3 zero = Vector3.zero;
		Vector3 remainingDirection = maxClampDisplacement.normalized;
		float remainingDistance = maxClampDisplacement.magnitude;
		for (int i = 0; i < maxIterationCount; i++)
		{
			if (remainingDistance < 0.001f)
			{
				break;
			}
			Vector3 initialCapsuleBottomPosition = currentData.CapsuleBottomPositionWorldSpace + zero;
			Vector3 initialCapsuleTopPosition = currentData.CapsuleTopPositionWorldSpace + zero;
			switch (CollisionDetection.SweepCapsule(initialCapsuleBottomPosition, initialCapsuleTopPosition, 0.25f, remainingDirection, remainingDistance, layerMask, colliderFilter, out hit))
			{
			case CollisionDetection.CollisionResult.OVERLAP:
			{
				if (!CollisionDetection.DepenetrateCapsule(currentData.CapsuleBottomPositionWorldSpace, currentData.CapsuleTopPositionWorldSpace, 0.25f + skinThickness, layerMask, colliderFilter, out var totalDepenetration))
				{
					return;
				}
				currentData.CapsuleBottomPositionWorldSpace += totalDepenetration;
				currentData.CapsuleTopPositionWorldSpace += totalDepenetration;
				break;
			}
			case CollisionDetection.CollisionResult.MISS:
				remainingDistance = 0f;
				break;
			case CollisionDetection.CollisionResult.HIT:
				zero += remainingDirection * (hit.distance - skinThickness);
				remainingDistance = Mathf.Max(0f, remainingDistance - hit.distance);
				switch (CollisionDetection.GetSurfaceType(hit.normal))
				{
				case CollisionDetection.SurfaceType.FLOOR:
					currentData.CapsuleBottomPositionWorldSpace += zero;
					currentData.CapsuleTopPositionWorldSpace += zero;
					currentData.IsGrounded = true;
					currentData.GroundNormal = hit.normal;
					return;
				case CollisionDetection.SurfaceType.WALL:
					ProjectRemainingDisplacement(hit.normal, ref remainingDirection, ref remainingDistance);
					break;
				default:
					remainingDistance = 0f;
					break;
				}
				break;
			}
		}
	}

	private ClimbType FindClimbableLedge(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, Vector3 movementDirection, float movementDistance, int layerMask, CollisionDetection.ColliderFilter colliderFilter, out Vector3 ledgePoint)
	{
		ledgePoint = Vector3.zero;
		Vector3 capsuleBottomPosition2 = capsuleBottomPosition - movementDirection * initialLedgeDetectOffset;
		Vector3 vector = Vector3.zero;
		float num = 0f;
		bool flag = false;
		for (int i = 0; i < ledgeClimbDetectionHeights.Length; i++)
		{
			num = ledgeClimbDetectionHeights[i];
			if (IsOverlapping(capsuleBottomPosition2, Vector3.up * num, layerMask, colliderFilter))
			{
				break;
			}
			vector = Vector3.up * num;
			if (CollisionDetection.SweepSphere(capsuleBottomPosition + vector, 0.25f, movementDirection, movementDistance, layerMask, colliderFilter, out var _) == CollisionDetection.CollisionResult.MISS)
			{
				flag = true;
				break;
			}
		}
		if (!flag)
		{
			return ClimbType.NONE;
		}
		Vector3 vector2 = movementDirection * movementDistance;
		vector += vector2;
		if (!IsOverStandableFloor(capsuleBottomPosition + vector, num, layerMask, colliderFilter, out ledgePoint))
		{
			return ClimbType.NONE;
		}
		Vector3 vector3 = movementDirection * maxMantleLedgeWidth;
		float y = (capsuleTopPosition - capsuleBottomPosition).y;
		if (IsLedgeMantlable(capsuleBottomPosition + vector, vector3, num, layerMask, colliderFilter))
		{
			ledgePoint += vector3;
			float num2 = Mathf.Min(y, Mathf.Max(0f, minMantleWindowHeight - 0.5f));
			if (IsOverlapping(capsuleBottomPosition + vector, Vector3.up * num2, layerMask, colliderFilter) || IsOverlapping(capsuleBottomPosition + vector + vector3, Vector3.up * y, layerMask, colliderFilter))
			{
				return ClimbType.NONE;
			}
			if (IsOverlapping(capsuleBottomPosition + vector, Vector3.up * y, layerMask, colliderFilter))
			{
				return ClimbType.MANTLE;
			}
			return ClimbType.CLAMBER;
		}
		if (IsOverlapping(capsuleBottomPosition + vector, Vector3.up * y, layerMask, colliderFilter))
		{
			return ClimbType.NONE;
		}
		return ClimbType.CLAMBER;
	}

	private bool IsLedgeMantlable(Vector3 capsuleBottomPosition, Vector3 ledgeWidthDisplacement, float searchHeight, int layerMask, CollisionDetection.ColliderFilter colliderFilter)
	{
		if (IsOverlapping(capsuleBottomPosition, ledgeWidthDisplacement, layerMask, colliderFilter))
		{
			return false;
		}
		Vector3 floorPoint;
		return !IsOverStandableFloor(capsuleBottomPosition + ledgeWidthDisplacement, searchHeight, layerMask, colliderFilter, out floorPoint);
	}

	private void ProjectRemainingDisplacement(Vector3 surfaceNormal, ref Vector3 remainingDirection, ref float remainingDistance)
	{
		Vector3 vector = remainingDirection * remainingDistance;
		vector = Vector3.ProjectOnPlane(vector, surfaceNormal);
		remainingDistance = vector.magnitude;
		if (remainingDistance >= Mathf.Epsilon)
		{
			remainingDirection = vector / remainingDistance;
		}
	}

	private bool IsOverlapping(Vector3 capsuleBottomPosition, Vector3 displacement, int layerMask, CollisionDetection.ColliderFilter colliderFilter)
	{
		return CollisionDetection.IsCapsuleColliderOverlapping(capsuleBottomPosition, capsuleBottomPosition + displacement, 0.25f, layerMask, colliderFilter);
	}

	private bool IsOverStandableFloor(Vector3 capsuleBottonPosition, float searchDistance, int layerMask, CollisionDetection.ColliderFilter colliderFilter, out Vector3 floorPoint)
	{
		floorPoint = Vector3.zero;
		RaycastHit hit;
		CollisionDetection.CollisionResult collisionResult = CollisionDetection.SweepSphere(capsuleBottonPosition, 0.25f, -Vector3.up, searchDistance, layerMask, colliderFilter, out hit);
		if (collisionResult != CollisionDetection.CollisionResult.HIT)
		{
			return false;
		}
		if (!CollisionDetection.CanPlayerStandOnCollider(hit.collider, hit.normal))
		{
			return false;
		}
		floorPoint = capsuleBottonPosition - Vector3.up * (hit.distance - skinThickness);
		return true;
	}

	private bool FindStep(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, Vector3 movementDirection, float movementDistance, int layerMask, CollisionDetection.ColliderFilter colliderFilter, out Vector3 stepPoint)
	{
		stepPoint = Vector3.zero;
		Vector3 vector = Vector3.up * stepHeight;
		capsuleBottomPosition += vector;
		capsuleTopPosition += vector;
		if (CollisionDetection.SweepCapsule(capsuleBottomPosition, capsuleTopPosition, 0.25f, movementDirection, movementDistance, layerMask, colliderFilter, out var _) != CollisionDetection.CollisionResult.MISS)
		{
			return false;
		}
		Vector3 vector2 = movementDirection * movementDistance;
		capsuleBottomPosition += vector2;
		capsuleTopPosition += vector2;
		return IsOverStandableFloor(capsuleBottomPosition, stepHeight, layerMask, colliderFilter, out stepPoint);
	}

	private float GetJumpSpeed(float jumpHeight)
	{
		return Mathf.Sqrt(2f * Physics.gravity.magnitude * jumpHeight);
	}

	private void ApplyJumpingAndGravityMovement(ref SurfaceSweepData currentMovementData, ref Vector3 desiredDisplacement)
	{
		if (requestedJump && !GravityIsPaused)
		{
			currentMovementData.IsGrounded = false;
			currentMovementData.GravityVelocity = Vector3.up * requestedJumpSpeed;
			desiredDisplacement = Vector3.ProjectOnPlane(desiredDisplacement, lastValidGroundNormal);
			desiredDisplacement += currentMovementData.GravityVelocity * UnityEngine.Time.deltaTime;
			hasJumped = true;
			base.photonView.RpcAll(RpcOnJump);
		}
		else if (!currentMovementData.IsGrounded && !GravityIsPaused)
		{
			currentMovementData.GravityVelocity += Physics.gravity * UnityEngine.Time.deltaTime;
			currentMovementData.GravityVelocity = Vector3.ClampMagnitude(currentMovementData.GravityVelocity, maxGravitySpeed);
			desiredDisplacement += currentMovementData.GravityVelocity * UnityEngine.Time.deltaTime;
		}
		else
		{
			currentMovementData.GravityVelocity = Vector3.zero;
			hasJumped = false;
			lastGroundedTime = UnityEngine.Time.time;
		}
		requestedJump = false;
	}

	private ClimbHeightType LedgeDistanceToLedgeHeightType(float ledgeDistance)
	{
		if (ledgeDistance >= 1.75f)
		{
			return ClimbHeightType.TALL;
		}
		if (ledgeDistance >= 1f)
		{
			return ClimbHeightType.MEDIUM;
		}
		if (ledgeDistance >= 0.3f)
		{
			return ClimbHeightType.SHORT;
		}
		return ClimbHeightType.VERY_SHORT;
	}

	private void UpdateTeleportCooldown()
	{
		if (teleportCooldownMap.HighestPriorityValue == 0f)
		{
			TeleportCooldownValue = 1f;
		}
		else
		{
			TeleportCooldownValue = Mathf.Clamp01((Now - lastMovementTime) / teleportCooldownMap.HighestPriorityValue);
		}
		TeleportOnCooldown = TeleportRunning || RotationBeingModified || TeleportCooldownValue < 1f;
	}

	private IEnumerator<ISchedule> RunContinuousTeleportCoroutine(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition, RigidbodyEx teleportRelativeRigidbody, bool isClimbing)
	{
		IsClimbing = isClimbing;
		bool vignettingEnabled = SingletonMonoBehaviour<SettingsManager>.Instance.MotionTeleportEnabled || isClimbing;
		float duration = teleportBlindDuration;
		if (isClimbing)
		{
			Vector3 vector = destinationPlayerPosition - sourcePlayerPosition;
			float num = ((!(vector.y <= 0f)) ? vector.magnitude : Vector3.ProjectOnPlane(vector, Vector3.up).magnitude);
			duration = num / climbSpeed;
		}
		Vector3 localSourcePosition = sourcePlayerPosition;
		Vector3 localDestinationPosition = destinationPlayerPosition;
		if (teleportRelativeRigidbody != null)
		{
			localSourcePosition = teleportRelativeRigidbody.transform.InverseTransformPoint(sourcePlayerPosition);
			localDestinationPosition = teleportRelativeRigidbody.transform.InverseTransformPoint(destinationPlayerPosition);
		}
		if (vignettingEnabled)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartTeleportVignette(0f);
		}
		else
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.Blind = true;
		}
		float startTime = UnityEngine.Time.time;
		float endTime = startTime + duration;
		while (UnityEngine.Time.time <= endTime)
		{
			float t = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
			ClimbTimeRemaining = (1f - t) * duration;
			Vector3 localCurrentPosition = localSourcePosition;
			localCurrentPosition = ((!isClimbing) ? GetDefaultTeleportInterpolatedPoint(localSourcePosition, localDestinationPosition, t) : GetLedgeClimbInterpolatedPoint(localSourcePosition, localDestinationPosition, t));
			if (teleportRelativeRigidbody != null)
			{
				localCurrentPosition = teleportRelativeRigidbody.TargetTransform.TransformPoint(localCurrentPosition);
			}
			MoveTo(localCurrentPosition, teleportRelativeRigidbody == null);
			yield return Schedule.NextFrame;
		}
		if (teleportRelativeRigidbody != null)
		{
			localDestinationPosition = teleportRelativeRigidbody.TargetTransform.TransformPoint(localDestinationPosition);
		}
		MoveTo(localDestinationPosition, teleportRelativeRigidbody == null);
		if (vignettingEnabled)
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopTeleportVignette(0.15f);
		}
		else
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.Blind = false;
		}
		Vector3 currentPosition = thisPlayer.CurrentFloorPosition;
		if (!isClimbing)
		{
			PlayTeleportTrail(sourcePlayerPosition, currentPosition);
			thisPlayer.PlayerAudio.OnTeleport();
		}
		hasPreviousValidMovementData = false;
		IsClimbing = false;
		FireTeleportEvent(sourcePlayerPosition, currentPosition);
	}

	private Vector3 GetLedgeClimbInterpolatedPoint(Vector3 sourcePosition, Vector3 destinationPosition, float t)
	{
		Vector3 vector = destinationPosition - sourcePosition;
		Vector3 vector2 = Vector3.ProjectOnPlane(vector, Vector3.up);
		Vector3 vector3 = vector - vector2;
		float num = clamberForwardCurve.Evaluate(t);
		float num2 = clamberUpCurve.Evaluate(t);
		vector = vector2 * num + vector3 * num2;
		return sourcePosition + vector;
	}

	private Vector3 GetDefaultTeleportInterpolatedPoint(Vector3 sourcePosition, Vector3 destinationPosition, float t)
	{
		return Vector3.Lerp(sourcePosition, destinationPosition, t);
	}

	private IEnumerator<ISchedule> RunDiscontinuousTeleportCoroutine(Vector3 sourcePlayerPosition, Vector3 destinationPlayerPosition, Vector3 destinationForward)
	{
		SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.Blind = true;
		CoordinateSpace rotationCoordinateSpace = CoordinateSpace.PLAYER_SPACE;
		MoveTo(destinationPlayerPosition, destinationForward, insertDiscontinuity: true, rotationCoordinateSpace);
		yield return new ScheduleWait(teleportBlindDuration);
		SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.Blind = false;
		hasPreviousValidMovementData = false;
		FireTeleportEvent(sourcePlayerPosition, destinationPlayerPosition);
	}

	private void CancelTeleport()
	{
		this.TeleportCanceled.SafeInvoke(thisPlayer);
		if (TeleportRunning)
		{
			this.SafeStopSchedule(teleportSchedule);
			teleportSchedule = null;
		}
		IsClimbing = false;
		TeleportationPortal.LocalPlayerSeat = null;
		SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopTeleportVignette(0.15f);
		SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.Blind = false;
	}

	[PunRPC]
	private void RpcOnJump()
	{
		thisPlayer.PlayerAudio.OnJump();
	}

	[PunRPC]
	private void RpcOnLand()
	{
		thisPlayer.PlayerAudio.OnLand();
	}

	[PunRPC]
	private void RpcOnLedgeClimb()
	{
		thisPlayer.PlayerAudio.OnLedgeClimb();
	}

	[PunRPC]
	private void RpcTeleport(Vector3 sourceFloorPosition, Vector3 destinationFloorPosition)
	{
		lastLocalMovementTime = UnityEngine.Time.time;
		lastMovementTime = (float)PhotonNetwork.time;
		if (thisPlayer.IsVisible && !thisPlayer.isLocal)
		{
			thisPlayer.PlayerAudio.OnTeleport();
			PlayTeleportTrail(sourceFloorPosition, destinationFloorPosition);
			FireTeleportEvent(sourceFloorPosition, destinationFloorPosition);
		}
	}

	private void FireTeleportEvent(Vector3 sourcePosition, Vector3 destinationPosition)
	{
		if (this.TeleportEvent != null)
		{
			this.TeleportEvent(thisPlayer, sourcePosition, destinationPosition);
		}
		if (PlayerLocomotion.PlayerTeleportedEvent != null)
		{
			PlayerLocomotion.PlayerTeleportedEvent(thisPlayer, sourcePosition, destinationPosition);
		}
		thisPlayer.PlayerEvents.Teleport();
	}

	private void PlayTeleportTrail(Vector3 sourcePosition, Vector3 destinationPosition)
	{
		if (!(thisPlayer != null) || !(trail != null))
		{
			return;
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && thisPlayer.PhotonPlayer != null)
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(thisPlayer.PhotonPlayer);
			if (playerTeam != GameTeam.ANY && trail != null)
			{
				trail.Color = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(playerTeam);
			}
		}
		trail.PlayTeleportTrail(thisPlayer.Head.HeightOffset, sourcePosition, destinationPosition);
	}

	public void OnPlayerDespawn()
	{
		if (trail != null)
		{
			trail.Clear();
		}
		if (thisPlayer != null && thisPlayer.isLocal)
		{
			movementAllowed = false;
			rotationAllowed = false;
			CancelTeleport();
			TeleportationPortal.LocalPlayerSeat = null;
		}
	}

	public void OnPlayerSpawn()
	{
		if (thisPlayer.isLocal)
		{
			hasPreviousValidMovementData = false;
			movementAllowed = true;
			rotationAllowed = true;
		}
	}

	private void OnDrawGizmos()
	{
		if (thisPlayer != null && thisPlayer.isLocal)
		{
			Gizmos.color = Color.blue;
			Gizmos.DrawWireSphere(previousMovementData.CapsuleBottomPositionWorldSpace, 0.25f);
			Gizmos.DrawWireSphere(previousMovementData.CapsuleTopPositionWorldSpace, 0.25f);
			if (hasPreviousValidMovementData && previousMovementData.IsNearClimbableSurface)
			{
				Gizmos.color = Color.yellow;
				Gizmos.DrawWireSphere(previousMovementData.ClimbDestination, 0.25f);
			}
		}
	}
}
public class PlayerModeration : Photon.MonoBehaviour
{
	private Player thisPlayer;

	private float vtkResetTime;

	private static float positiveKarmaSeconds;

	private const float PositiveKarmaUpdateInteval = 600f;

	private Coroutine vtkResponseCoroutine;

	public bool IsVotedForKick { get; private set; }

	public bool InitiatedVoteKickAgainst { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
	}

	private void Update()
	{
		if (isLocal)
		{
			Profile localProfile = Profiles.LocalProfile;
			if ((localProfile.Reputation.Noteriety < 0f || (localProfile.Verified && localProfile.Reputation.CheerCredit < 5)) && !SessionManager.InPrivateSession && PhotonNetwork.playerList.Length > 1)
			{
				positiveKarmaSeconds += UnityEngine.Time.unscaledDeltaTime;
				if (positiveKarmaSeconds >= 600f)
				{
					positiveKarmaSeconds -= 600f;
					Profiles.UpdateLocalProfileKarma(600f);
				}
			}
		}
		else if (IsVotedForKick && vtkResponseCoroutine == null && UnityEngine.Time.unscaledTime > vtkResetTime)
		{
			IsVotedForKick = false;
			ShowVTKFailedNotificationForInitiator();
		}
	}

	public void VoteToKickPlayer(bool initiating)
	{
		InitiatedVoteKickAgainst = initiating;
		VoteToKickResponse(response: true);
	}

	public void DeclineVoteToKickPlayer()
	{
		VoteToKickResponse(response: false);
	}

	private void ShowVTKFailedNotificationForInitiator()
	{
		if (InitiatedVoteKickAgainst && SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
		{
			InitiatedVoteKickAgainst = false;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Kick Voted Failed", "You did not receive enough votes.", 3f);
		}
	}

	private void VoteToKickResponse(bool response)
	{
		VotekickType votekickType = PlayerRoomRoleManager.Instance.CanVoteKick(PhotonNetwork.player, thisPlayer.PhotonPlayer, showNotification: true);
		if (votekickType != VotekickType.Off && !isLocal && !IsVotedForKick && vtkResponseCoroutine == null)
		{
			IsVotedForKick = true;
			vtkResponseCoroutine = StartCoroutine(RunVoteToKickResponse(response, votekickType));
			vtkResetTime = UnityEngine.Time.unscaledTime + SingletonMonoBehaviour<ModerationManager>.Instance.VtkActiveDuration;
		}
	}

	private IEnumerator RunVoteToKickResponse(bool shouldKick, VotekickType type)
	{
		if (type == VotekickType.Instant)
		{
			yield return PlayerReporting.KickPlayerFromEvent(thisPlayer.PlayerId, delegate(string error, OkResponse response)
			{
				if (!response.Success)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Major, "Failed!", response.Message, 4f, 3f);
				}
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError(error);
				}
			});
		}
		else
		{
			AnalyticsHelper.VTKAttempt(thisPlayer.PlayerId, shouldKick);
			yield return PlayerReporting.VoteToKickPlayer(thisPlayer.PlayerId, shouldKick, delegate(string error, OkResponse response)
			{
				if (!response.Success)
				{
					AnalyticsHelper.VTKAttemptError(thisPlayer.PlayerId, response.Message);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Major, "Failed!", response.Message, 4f, 3f);
				}
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError(error);
				}
			});
		}
		vtkResponseCoroutine = null;
	}

	public void ModerationBroadcastKickMessage()
	{
		base.photonView.RpcOthers(RpcModerationBroadcastKickMessage);
	}

	[PunRPC]
	private void RpcModerationBroadcastKickMessage()
	{
		InitiatedVoteKickAgainst = false;
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Medium, $"User {thisPlayer.PlayerName} was vote kicked.", 4f, 2f);
	}
}
