	public void GetObjectiveDescription(int objectiveIndex, out ProgressionManager.ObjectiveTypeDescription description, out string descriptionText)
	{
		description = null;
		descriptionText = null;
		ProgressionManager.Objective currentObjective = GetCurrentObjective(objectiveIndex);
		if (currentObjective != null)
		{
			description = SingletonMonoBehaviour<ProgressionManager>.Instance.GetObjectiveDescription(currentObjective.ObjectiveType);
			if (description != null)
			{
				descriptionText = description.GetFormattedDescriptionText(currentObjective.RequiredScore);
			}
		}
	}

	public bool GetObjectiveLastVisualizedProgress(int objectiveIndex, out int progress)
	{
		ClearStaleProgress();
		bool result = false;
		progress = 0;
		ProgressionManager.Objective currentObjective = GetCurrentObjective(objectiveIndex);
		if (currentObjective != null)
		{
			progress = GetVisualizedProgress(objectiveIndex);
			result = progress >= currentObjective.RequiredScore;
		}
		return result;
	}

	public void SetObjectiveLastVisualizedProgress(int objectiveIndex, int lastVisualizedProgress)
	{
		SetVisualizedProgress(objectiveIndex, lastVisualizedProgress);
	}

	public bool GetObjectiveProgress(int objectiveIndex, out int progress, out int total)
	{
		ClearStaleProgress();
		bool result = false;
		progress = 0;
		total = 0;
		ProgressionManager.Objective currentObjective = GetCurrentObjective(objectiveIndex);
		if (currentObjective != null)
		{
			total = currentObjective.RequiredScore;
			if (GetCompleted(objectiveIndex))
			{
				result = true;
				progress = total;
			}
			else
			{
				result = false;
				progress = GetProgress(objectiveIndex);
			}
		}
		return result;
	}

	public List<ObjectiveDetails> GetAllObjectiveDetails()
	{
		ClearStaleProgress();
		ProgressionManager.Objective[] currentObjectives = GetCurrentObjectives();
		List<ObjectiveDetails> list = null;
		if (currentObjectives != null)
		{
			list = new List<ObjectiveDetails>(currentObjectives.Length);
			for (int i = 0; i < currentObjectives.Length; i++)
			{
				ObjectiveDetails objectiveDetails = new ObjectiveDetails();
				objectiveDetails.completed = GetObjectiveProgress(i, out objectiveDetails.progress, out objectiveDetails.total);
				objectiveDetails.rewardAvailable = false;
				GetObjectiveDescription(i, out var description, out objectiveDetails.helpText);
				objectiveDetails.tooltipText = ((description == null) ? string.Empty : description.ToolTip);
				objectiveDetails.tokenText = GetTokenAmountForChecklistObjective(i).ToString();
				list.Add(objectiveDetails);
			}
		}
		return list;
	}

	private int GetTokenAmountForChecklistObjective(int idx)
	{
		if (Checklist.CurrentObjectives == null || idx < 0 || idx >= Checklist.CurrentObjectives.Count)
		{
			return 0;
		}
		return Checklist.CurrentObjectives[idx].CreditAmount;
	}

	public void CompleteObjective(ProgressionManager.ObjectiveType objective, float completionPercentage = 1f)
	{
		if (!ObjectiveTrackingSuppressed)
		{
			eventBuffer.Clear();
			AddToEventBuffer(objective, completionPercentage);
			UpdateObjectiveProgress();
		}
	}

	private void AddToEventBuffer(ProgressionManager.ObjectiveType objective, float completionPercentage = 1f)
	{
		if (!ObjectiveTrackingSuppressed)
		{
			eventBuffer.Add(new ObjectiveRecord
			{
				objectiveType = objective,
				completionPercentage = completionPercentage,
				roomId = GameSessions.LocalGameSession?.RoomId
			});
		}
	}

	public float GetPercentageComplete()
	{
		ProgressionManager.Objective[] currentObjectives = GetCurrentObjectives();
		if (currentObjectives == null || currentObjectives.Length == 0)
		{
			return 0f;
		}
		int num = currentObjectives.Length;
		int num2 = 0;
		for (int i = 0; i < currentObjectives.Length; i++)
		{
			if (GetCompleted(i))
			{
				num2++;
			}
		}
		return Mathf.Clamp01((float)num2 / (float)num);
	}

	public bool GetAllObjectivesCompleted()
	{
		ProgressionManager.Objective[] currentObjectives = GetCurrentObjectives();
		if (currentObjectives != null)
		{
			for (int i = 0; i < currentObjectives.Length; i++)
			{
				if (!GetCompleted(i))
				{
					return false;
				}
			}
		}
		return true;
	}

	public bool IsRewardAvailable(int objectiveIndex)
	{
		ClearStaleProgress();
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		return objectiveProgress.IsCompleted && !objectiveProgress.IsRewarded;
	}

	public void SetRewardAvailable(int objectiveIndex, bool isAvailable)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		if (isAvailable)
		{
			objectiveProgress.IsCompleted = true;
			objectiveProgress.IsRewarded = false;
		}
		else
		{
			objectiveProgress.IsRewarded = true;
		}
		Objectives.UpdateObjective(objectiveProgress);
	}

