	private void OnGameOver(bool won, float completionPercentage)
	{
		if (UnityEngine.Time.realtimeSinceStartup - lastOnGameOverTime < 20f)
		{
			return;
		}
		lastOnGameOverTime = UnityEngine.Time.realtimeSinceStartup;
		eventBuffer.Clear();
		AddToEventBuffer(ProgressionManager.ObjectiveType.FinishActivity, completionPercentage);
		if (RecRoomSceneManager.CurrentSceneName.Equals("dodgeball", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.DodgeballGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.DodgeballWins, completionPercentage);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName.StartsWith("quest", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.QuestGames, completionPercentage);
			QuestManager questManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager;
			if (questManager != null && questManager.ObjectiveGames != ProgressionManager.ObjectiveType.Default)
			{
				AddToEventBuffer(questManager.ObjectiveGames, completionPercentage);
			}
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.QuestWins, completionPercentage);
				if (questManager != null && questManager.ObjectiveWins != ProgressionManager.ObjectiveType.Default)
				{
					AddToEventBuffer(questManager.ObjectiveWins, completionPercentage);
				}
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName.Equals("soccer", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.SoccerGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.SoccerWins, completionPercentage);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName.Equals("charades", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.CharadesGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.CharadesWinsPerformer, completionPercentage);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneName.Equals("paddleball", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.PaddleballGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.PaddleballWins, completionPercentage);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneFriendlyName.StartsWith("Disc Golf", StringComparison.InvariantCultureIgnoreCase))
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.DiscGolfGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.DiscGolfWins, completionPercentage);
			}
		}
		else if (RecRoomSceneManager.CurrentSceneFriendlyName.StartsWith("Paintball", StringComparison.InvariantCultureIgnoreCase))
		{
			if (gameManager != null)
			{
				switch ((PaintballManager.PaintballMode)gameManager.CurrentMode.ModeType)
				{
				case PaintballManager.PaintballMode.MultiFlagCaptureTheFlag:
					AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballCTFGames, completionPercentage);
					if (won)
					{
						AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballCTFWins, completionPercentage);
					}
					break;
				case PaintballManager.PaintballMode.TeamBattle:
					AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballTeamBattleGames, completionPercentage);
					if (won)
					{
						AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballTeamBattleWins, completionPercentage);
					}
					break;
				case PaintballManager.PaintballMode.FreeForAllBattle:
					AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballFreeForAllGames, completionPercentage);
					if (won)
					{
						AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballFreeForAllWins, completionPercentage);
					}
					break;
				}
				AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballAnyModeGames, completionPercentage);
				if (won)
				{
					AddToEventBuffer(ProgressionManager.ObjectiveType.PaintballAnyModeWins, completionPercentage);
				}
			}
		}
		else if (ArenaManager.Instance != null)
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.ArenaGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.ArenaWins, completionPercentage);
			}
		}
		else if (BowlingManager.Instance != null)
		{
			AddToEventBuffer(ProgressionManager.ObjectiveType.BowlingGames, completionPercentage);
			if (won)
			{
				AddToEventBuffer(ProgressionManager.ObjectiveType.BowlingWins, completionPercentage);
			}
		}
		UpdateObjectiveProgress();
	}

