	private void UpdateObjectiveProgress()
	{
		if (!(gameManager == null) && !gameManager.CustomGameSettings.AllowRewards && trackerType == ObjectiveTrackerType.Dailies)
		{
			eventBuffer.Clear();
			return;
		}
		ClearStaleProgress();
		if (eventBuffer.Count > 0 && PlayerObjectiveTracker.EventBufferUpdated != null)
		{
			PlayerObjectiveTracker.EventBufferUpdated(eventBuffer, trackerType);
		}
		if (GetAllObjectivesCompleted())
		{
			return;
		}
		bool flag = false;
		int num = 0;
		int num2 = 0;
		ProgressionManager.Objective[] currentObjectives = GetCurrentObjectives();
		for (int i = 0; i < currentObjectives.Length; i++)
		{
			if (GetCompleted(i))
			{
				continue;
			}
			foreach (ObjectiveRecord item in eventBuffer)
			{
				ProgressionManager.ObjectiveType objectiveType = item.objectiveType;
				if (currentObjectives[i].ObjectiveType != objectiveType)
				{
					continue;
				}
				AddProgress(i, 1);
				flag = true;
				if (GetProgress(i) < currentObjectives[i].RequiredScore)
				{
					continue;
				}
				if (objectiveType != ProgressionManager.ObjectiveType.AllOtherChallenges)
				{
					num++;
				}
				ObjectiveTrackerType objectiveTrackerType = trackerType;
				switch (objectiveTrackerType)
				{
				case ObjectiveTrackerType.Dailies:
					CompleteObjective(i);
					SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(GetDailyObjectiveType(i), 1f, item.roomId);
					num2++;
					if (GetAllObjectivesCompleted())
					{
						SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(ProgressionManager.ObjectiveType.AllDailyObjectives, 1f, item.roomId);
					}
					break;
				case ObjectiveTrackerType.OrientationList:
				{
					int checkListIdx = i;
					Checklist.CompleteChecklistItem(checkListIdx, delegate(string error)
					{
						if (string.IsNullOrEmpty(error))
						{
							if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CanSpawnGiftPackageInCurrentState)
							{
								Avatars.GiftPackageReceivedEvent += Avatars_GiftPackageReceivedEvent;
							}
							CompleteObjective(checkListIdx);
						}
					});
					break;
				}
				default:
					CompleteObjective(i);
					break;
				}
			}
		}
		if (this.ObjectiveProgressUpdateEvent != null && flag)
		{
			this.ObjectiveProgressUpdateEvent();
		}
		eventBuffer.Clear();
		while (num > 0)
		{
			CompleteObjective(ProgressionManager.ObjectiveType.AllOtherChallenges);
			num--;
		}
		while (num2 > 0 && Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerEvents.DailyChallengeCompleted();
			num2--;
		}
	}

	private void Avatars_GiftPackageReceivedEvent(Avatars.GiftPackage package, bool showImmediate)
	{
		if (package.Message == "Checklist item complete!")
		{
			Avatars.GiftPackageReceivedEvent -= Avatars_GiftPackageReceivedEvent;
			SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(new List<Avatars.GiftPackage> { package }, useSpawnLocation: false, dismissExistingGift: false);
		}
	}

	private ProgressionManager.ObjectiveType GetDailyObjectiveType(int index)
	{
		return index switch
		{
			0 => ProgressionManager.ObjectiveType.DailyObjective1, 
			1 => ProgressionManager.ObjectiveType.DailyObjective2, 
			2 => ProgressionManager.ObjectiveType.DailyObjective3, 
			_ => ProgressionManager.ObjectiveType.Default, 
		};
	}

	private ProgressionManager.Objective GetCurrentObjective(int index)
	{
		ProgressionManager.Objective[] currentObjectives = GetCurrentObjectives();
		if (currentObjectives == null || index < 0 || index >= currentObjectives.Length)
		{
			return null;
		}
		return currentObjectives[index];
	}

	public ProgressionManager.ObjectiveType GetObjectiveType(int index)
	{
		return GetCurrentObjective(index)?.ObjectiveType ?? ProgressionManager.ObjectiveType.Default;
	}

	private ProgressionManager.Objective[] GetCurrentObjectives()
	{
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
		{
			DateTime today = DateTime.Today;
			return Config.DailyObjectives[(int)today.DayOfWeek];
		}
		case ObjectiveTrackerType.OrientationList:
			if (!orientationObjectivesInitialized)
			{
				List<Checklist.ChecklistObjective> currentObjectives = Checklist.CurrentObjectives;
				if (currentObjectives != null && currentObjectives.Count > 0)
				{
					orientationObjectives = new ProgressionManager.Objective[currentObjectives.Count];
					for (int i = 0; i < currentObjectives.Count; i++)
					{
						ProgressionManager.Objective objective = new ProgressionManager.Objective();
						objective.ObjectiveType = currentObjectives[i].Objective;
						objective.RequiredScore = currentObjectives[i].Count;
						ProgressionManager.Objective objective2 = objective;
						orientationObjectives[i] = objective2;
					}
				}
				orientationObjectivesInitialized = true;
			}
			return orientationObjectives;
		default:
			return null;
		}
	}

	public void ClearStaleProgress(bool forciblyClear = false)
	{
		if ((trackerType == ObjectiveTrackerType.Dailies && !HasSeenTodaysObjectives) || forciblyClear)
		{
			if (trackerType == ObjectiveTrackerType.Dailies)
			{
				Objectives.ClearGroup(0, null);
			}
			if (forciblyClear)
			{
				UpdateObjectiveProgress();
				if (this.ObjectiveProgressUpdateEvent != null)
				{
					this.ObjectiveProgressUpdateEvent();
				}
			}
		}
		UpdateLastRecordedObjectiveDate();
	}

	private static DateTime GetCurrentDate()
	{
		return DateTime.Now;
	}

	public static void UpdateLastRecordedObjectiveDate()
	{
		ObjectiveGroupProgress objectiveGroupProgress = Objectives.LookupCachedObjectiveGroup(0);
		if (objectiveGroupProgress == null || objectiveGroupProgress.ClearedAt.ToLocalTime().DayOfYear != GetCurrentDate().ToLocalTime().DayOfYear)
		{
			Objectives.ClearGroup(0, null);
		}
	}

	private void AddProgress(int objectiveIndex, int delta)
	{
		int progress = GetProgress(objectiveIndex);
		SetProgress(objectiveIndex, progress + delta);
	}

	private void SetProgress(int objectiveIndex, int value)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		objectiveProgress.Progress = value;
		Objectives.UpdateObjective(objectiveProgress);
	}

	private void SetVisualizedProgress(int objectiveIndex, int value)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		objectiveProgress.VisualProgress = value;
		Objectives.UpdateObjective(objectiveProgress);
	}

	private int GetGroupID()
	{
		int result = -1;
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
			result = 0;
			break;
		case ObjectiveTrackerType.OrientationList:
			result = 2;
			break;
		}
		return result;
	}

	private int GetProgress(int objectiveIndex)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		return (int)objectiveProgress.Progress;
	}

	private int GetVisualizedProgress(int objectiveIndex)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		return (int)objectiveProgress.VisualProgress;
	}

	private void RecordObjectiveCompleteAnalytics(ProgressionManager.Objective objective)
	{
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
			AnalyticsHelper.DailyObjectiveCompleted(objective);
			break;
		case ObjectiveTrackerType.OrientationList:
			AnalyticsHelper.OrientationObjectiveCompleted(objective);
			break;
		}
	}

	private void RecordAllObjectivesCompleteAnalytics()
	{
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
			AnalyticsHelper.AllDailyObjectivesCompleted();
			break;
		case ObjectiveTrackerType.OrientationList:
			AnalyticsHelper.AllOrientationObjectivesCompleted();
			break;
		}
	}

	private void NotifyPlayerAllObjectivesCompleted(ProgressionManager.ObjectiveTypeDescription description)
	{
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "All Daily Challenges Complete!", 3f, description.NotificationDelay, OnNotificationPlaying);
			break;
		case ObjectiveTrackerType.OrientationList:
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "All Orientation Challenges Complete!", 3f, description.NotificationDelay, OnNotificationPlaying);
			break;
		}
	}

	private void NotifyPlayerSingleObjectiveCompleted(ProgressionManager.ObjectiveTypeDescription description, ProgressionManager.Objective objective)
	{
		string formattedDescriptionText = description.GetFormattedDescriptionText(objective.RequiredScore);
		switch (trackerType)
		{
		case ObjectiveTrackerType.Dailies:
			if (!SingletonMonoBehaviour<TutorialManager>.Instance.HasCompletedTutorial)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Checklist Item Complete!", formattedDescriptionText, 3f, description.NotificationDelay, OnNotificationPlaying);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Daily Challenge Complete!", formattedDescriptionText, 3f, description.NotificationDelay, OnNotificationPlaying);
			}
			break;
		case ObjectiveTrackerType.OrientationList:
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Vital, "Orientation Challenge Complete!", formattedDescriptionText, 3f, description.NotificationDelay, OnNotificationPlaying);
			break;
		}
	}

	private void CompleteObjective(int objectiveIndex)
	{
		ProgressionManager.Objective currentObjective = GetCurrentObjective(objectiveIndex);
		SetCompleted(objectiveIndex, completed: true);
		ProgressionManager.ObjectiveTypeDescription objectiveDescription = SingletonMonoBehaviour<ProgressionManager>.Instance.GetObjectiveDescription(currentObjective.ObjectiveType);
		if (objectiveDescription == null)
		{
			return;
		}
		RecordObjectiveCompleteAnalytics(currentObjective);
		if (GetAllObjectivesCompleted())
		{
			NotifyPlayerAllObjectivesCompleted(objectiveDescription);
			if (PlayerObjectiveTracker.AllObjectivesCompleted != null)
			{
				PlayerObjectiveTracker.AllObjectivesCompleted(trackerType);
			}
			RecordAllObjectivesCompleteAnalytics();
		}
		else
		{
			NotifyPlayerSingleObjectiveCompleted(objectiveDescription, currentObjective);
		}
	}

	private void SetCompleted(int objectiveIndex, bool completed)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		objectiveProgress.IsCompleted = completed;
		Objectives.UpdateObjective(objectiveProgress);
	}

	private bool GetCompleted(int objectiveIndex)
	{
		int groupID = GetGroupID();
		ObjectiveProgress objectiveProgress = Objectives.LookupCachedObjectiveProgress(groupID, objectiveIndex);
		return objectiveProgress.IsCompleted;
	}

	private void OnNotificationPlaying()
	{
		thisPlayer.PlayerAudio.OnObjectiveComplete();
	}
}
[DisallowMultipleComponent]
[RequireComponent(typeof(Player))]
public class PlayerParty : Photon.MonoBehaviour
{
	public static readonly string PartyIdProperty = "PlayerPartyID";

	public static readonly string PartyColorIdProperty = "PlayerPartyColorID";

	private const float MIN_SOCIAL_REQUEST_PERIOD = 2f;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_PartyUpdateReceived;

	[Header("Settings")]
	[Tooltip("Update the party membership list periodically.")]
	[SerializeField]
	private float partyListUpdateInterval = 1f;

	[Header("Feedbackl")]
	[SerializeField]
	private ParticleSystem fistBumpParticles;

	private float lastTimePartyListUpdated;

	private bool partyColorDirty = true;

	private List<Player> groupPlayers;

	private Player thisPlayer;

	private Dictionary<int, float> rateLimitedPlayerDictionary = new Dictionary<int, float>();

	private SynchronizedPlayerField<bool> _isWaitingToJoinAParty;

	private SynchronizedPlayerField<bool> _isWaitingtoMakeFriend;

	private SynchronizedPlayerField<bool> _isWaitingToHighFive;

	private SynchronizedPlayerField<string> _currentPartyId;

	private SynchronizedPlayerField<string> _currentPartyColorId;

	private Color? _partyColor;

	public bool IsInParty => !string.IsNullOrEmpty(CurrentPartyId);

	public int PartySize => IsInParty ? (groupPlayers.Count + 1) : 0;

	public bool IsWaitingtoJoinAParty
	{
		get
		{
			return _isWaitingToJoinAParty.Get();
		}
		set
		{
			_isWaitingToJoinAParty.Set(value);
		}
	}

	public bool IsWaitingToMakeFriend
	{
		get
		{
			return _isWaitingtoMakeFriend.Get();
		}
		set
		{
			_isWaitingtoMakeFriend.Set(value);
		}
	}

	public bool IsWaitingToHighFive
	{
		get
		{
			return _isWaitingToHighFive.Get();
		}
		set
		{
			_isWaitingToHighFive.Set(value);
		}
	}

	public string CurrentPartyId
	{
		get
		{
			return _currentPartyId.Get();
		}
		private set
		{
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId = value;
			}
			if (value != CurrentPartyId)
			{
				if (!string.IsNullOrEmpty(value))
				{
					AnalyticsHelper.PartyJoined(value, PartySize);
				}
				else
				{
					AnalyticsHelper.UpdatePartyUserProperty(value);
				}
			}
			_currentPartyId.Set(value);
			if (string.IsNullOrEmpty(value))
			{
				CurrentPartyColorId = string.Empty;
			}
			else
			{
				UpdatePartyLists(forcePartyChange: true);
				LocalValidatePartyColorId();
			}
			IsWaitingtoJoinAParty = false;
		}
	}

	public string CurrentPartyColorId
	{
		get
		{
			return _currentPartyColorId.Get();
		}
		private set
		{
			_currentPartyColorId.Set(value);
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId = value;
			}
		}
	}

	public Color? PartyColor
	{
		get
		{
			if (partyColorDirty)
			{
				_partyColor = null;
				string currentPartyColorId = CurrentPartyColorId;
				if (!string.IsNullOrEmpty(currentPartyColorId) && SingletonMonoBehaviour<SessionManager>.Instance != null)
				{
					ColorVault.ColorToGuid colorToGuid = SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Find(currentPartyColorId);
					if (colorToGuid != null)
					{
						_partyColor = colorToGuid.color;
						partyColorDirty = false;
					}
				}
			}
			return _partyColor;
		}
	}

	public event Action PartyUpdateReceived
	{
		add
		{
			Action action = this.m_PartyUpdateReceived;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PartyUpdateReceived, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_PartyUpdateReceived;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PartyUpdateReceived, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		thisPlayer = GetComponent<Player>();
		groupPlayers = new List<Player>();
		_currentPartyId = new SynchronizedPlayerField<string>(base.owner, PartyIdProperty, string.Empty, OnPartyIdChanged);
		_currentPartyColorId = new SynchronizedPlayerField<string>(base.owner, PartyColorIdProperty, string.Empty, OnPartyColorChanged);
		_isWaitingToJoinAParty = new SynchronizedPlayerField<bool>(base.owner, "WAITING_FOR_PARTY", defaultValue: false);
		_isWaitingtoMakeFriend = new SynchronizedPlayerField<bool>(base.owner, "WAITING_FOR_FRIEND", defaultValue: false);
		_isWaitingToHighFive = new SynchronizedPlayerField<bool>(base.owner, "WAITING_FOR_HIGHFIVE", defaultValue: false);
		if (isLocal)
		{
			CurrentPartyId = ((SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId == null) ? string.Empty : SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyId);
			SynchronizedField.SendPendingRoomUpdates();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
	}

	private void Start()
	{
		if (isLocal)
		{
			thisPlayer.LeftHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
			thisPlayer.RightHand.Gestures.GestureDetected += PlayerHandGestures_GestureDetected;
		}
	}

	private void Update()
	{
		if (isLocal && UnityEngine.Time.time - lastTimePartyListUpdated > partyListUpdateInterval)
		{
			lastTimePartyListUpdated = UnityEngine.Time.time;
			UpdatePartyLists();
		}
	}

	public void SendHighFive(PhotonPlayer otherPlayer)
	{
		base.photonView.RpcAll(RpcSendHighFive, otherPlayer);
	}

	public void JoinParty(PhotonPlayer otherPlayer, Vector3 feedbackPosition)
	{
		base.photonView.RpcAll(RpcJoinParty, otherPlayer, feedbackPosition);
	}

	public void LeaveCurrentParty()
	{
		if (IsInParty)
		{
			AnalyticsHelper.PartyLeft(CurrentPartyId, groupPlayers.Count);
		}
		groupPlayers.Clear();
		CurrentPartyId = string.Empty;
	}

	public bool IsInPartyWith(Player player)
	{
		return player != null && IsInParty && groupPlayers.Contains(player);
	}

	public void SendFriendRequest(PhotonPlayer otherPlayer, Vector3 feedbackPosition)
	{
		base.photonView.RpcAll(RpcMakeFriendRequest, otherPlayer, feedbackPosition);
	}

	public bool CanInvitePlayer(Player player)
	{
		return player != null && !groupPlayers.Contains(player);
	}

	public void KickPlayer(Player target)
	{
		if (IsInPartyWith(target))
		{
			target.PlayerParty.photonView.RpcPlayer(target.PhotonPlayer, RpcKickedFromParty, CurrentPartyId);
		}
	}

	public long[] GetPlayerIDs()
	{
		UpdatePartyLists();
		if (groupPlayers.Count > 0)
		{
			long[] array = new long[groupPlayers.Count];
			for (int i = 0; i < groupPlayers.Count; i++)
			{
				array[i] = groupPlayers[i].PlayerId;
			}
			return array;
		}
		return null;
	}

	[PunRPC]
	private void RpcMakeFriendRequest(PhotonPlayer otherPlayer, Vector3 feedbackPosition)
	{
		Player player = otherPlayer.ToPlayer();
		if (thisPlayer.isLocal)
		{
			OnMakeFriendRequest(player, feedbackPosition);
		}
		else if (otherPlayer.IsLocal)
		{
			player.PlayerParty.OnMakeFriendRequest(thisPlayer, feedbackPosition);
		}
	}

	private void OnMakeFriendRequest(Player otherPlayer, Vector3 feedbackPosition)
	{
		if (!UpdateRateLimitedPlayers(otherPlayer.PhotonPlayer) && isLocal)
		{
			MakeFriend(otherPlayer, feedbackPosition);
		}
	}

	[PunRPC]
	private void RpcAutoJoinParty(string partyId)
	{
		CurrentPartyId = partyId;
		UpdatePartyLists();
	}

	[PunRPC]
	private void RpcJoinParty(PhotonPlayer otherPlayer, Vector3 feedbackPosition)
	{
		Player player = otherPlayer.ToPlayer();
		if (thisPlayer.isLocal)
		{
			OnPartyJoinRequest(player, feedbackPosition);
		}
		else if (otherPlayer.IsLocal)
		{
			player.PlayerParty.OnPartyJoinRequest(thisPlayer, feedbackPosition);
		}
		else if (IsMaxPhotonPlayer(thisPlayer.PhotonPlayer, otherPlayer))
		{
			OnPartyJoinRequest(player, feedbackPosition);
		}
		else
		{
			player.PlayerParty.OnPartyJoinRequest(thisPlayer, feedbackPosition);
		}
	}

	[PunRPC]
	private void RpcSendHighFive(PhotonPlayer otherPlayer)
	{
		Player player = otherPlayer.ToPlayer();
		if (thisPlayer.isLocal)
		{
			OnSentHighFive();
		}
		else if (otherPlayer.IsLocal)
		{
			player.PlayerParty.OnSentHighFive();
		}
	}

	private void OnSentHighFive()
	{
		IsWaitingToHighFive = false;
	}

	private void OnPartyJoinRequest(Player otherPlayer, Vector3 feedbackPosition)
	{
		if (!UpdateRateLimitedPlayers(otherPlayer.PhotonPlayer))
		{
			thisPlayer.PlayerAudio.OnFistBump(feedbackPosition);
			PlayParticleEffect(fistBumpParticles, feedbackPosition);
			if (isLocal)
			{
				PartyUp(otherPlayer, feedbackPosition);
			}
		}
	}

	private bool UpdateRateLimitedPlayers(PhotonPlayer player)
	{
		int iD = player.ID;
		float time = UnityEngine.Time.time;
		float value;
		bool result = rateLimitedPlayerDictionary.TryGetValue(iD, out value) && time - value <= 2f;
		rateLimitedPlayerDictionary[iD] = time;
		return result;
	}

	private void PartyUp(Player remotePlayer, Vector3 feedbackPosition)
	{
		bool flag = false;
		if (remotePlayer.PlayerParty.IsInParty && !IsInParty)
		{
			CurrentPartyId = remotePlayer.PlayerParty.CurrentPartyId;
			UpdatePartyLists();
			flag = true;
		}
		else if (!remotePlayer.PlayerParty.IsInParty && IsInParty)
		{
			flag = true;
		}
		else if (remotePlayer.PlayerParty.IsInParty && IsInParty && remotePlayer.PlayerParty.CurrentPartyId != CurrentPartyId)
		{
			flag = true;
			if (IsMaxPhotonPlayer(thisPlayer.PhotonPlayer, remotePlayer.PhotonPlayer))
			{
				UpdatePartyLists();
				string currentPartyId = remotePlayer.PlayerParty.CurrentPartyId;
				foreach (Player groupPlayer in groupPlayers)
				{
					groupPlayer.PlayerParty.AutoJoinParty(currentPartyId);
				}
				CurrentPartyId = currentPartyId;
			}
		}
		else if (!remotePlayer.PlayerParty.IsInParty && !IsInParty)
		{
			flag = true;
			if (IsMaxPhotonPlayer(thisPlayer.PhotonPlayer, remotePlayer.PhotonPlayer))
			{
				CurrentPartyId = Guid.NewGuid().ToBase64String();
				remotePlayer.PlayerParty.AutoJoinParty(CurrentPartyId);
			}
		}
		IsWaitingtoJoinAParty = false;
		if (flag)
		{
			thisPlayer.PlayerEvents.PartiedUp();
			WorldSpaceNotification.PlayNext("Party Join", 2f, null, followPlayer: false, feedbackPosition + 0.1f * Vector3.up, 0.3f);
		}
	}

	private void MakeFriend(Player otherPlayer, Vector3 feedbackPosition)
	{
		IsWaitingToMakeFriend = false;
		if (otherPlayer == null)
		{
			return;
		}
		bool flag = false;
		Relationship relationship = Relationships.Get(otherPlayer.PlayerId);
		if (relationship != null)
		{
			if (relationship.Ignored != Relationship.ReciprocalStatus.None)
			{
				WorldSpaceNotification.PlayNext("Player Blocked!", 2f, null, followPlayer: false, feedbackPosition, 0.3f);
				return;
			}
			flag = relationship.Type == Relationship.RelationshipType.Friend;
		}
		if (flag)
		{
			WorldSpaceNotification.PlayNext("Friends", 2f, null, followPlayer: false, feedbackPosition, 0.3f);
			return;
		}
		Relationships.AddFriend(otherPlayer.PlayerId);
		AnalyticsHelper.AddedFriend(otherPlayer);
		WorldSpaceNotification.PlayNext("Friend Added", 2f, null, followPlayer: false, feedbackPosition, 0.3f);
		thisPlayer.PlayerEvents.AddedFriend((int)otherPlayer.PlayerId);
	}

	private bool IsMaxPhotonPlayer(PhotonPlayer thisPlayer, PhotonPlayer otherPlayer)
	{
		return thisPlayer.ID > otherPlayer.ID;
	}

	private void AutoJoinParty(string partyId)
	{
		base.photonView.RpcPlayer(base.photonView.owner, RpcAutoJoinParty, partyId);
	}

	private string GetNextAvailableGroupColorId()
	{
		List<string> list = new List<string>();
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customProperty = player.GetCustomProperty<string>(PartyColorIdProperty);
			if (!string.IsNullOrEmpty(customProperty) && !list.Contains(customProperty))
			{
				list.Add(customProperty);
			}
		}
		SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Colors.Shuffle();
		foreach (ColorVault.ColorToGuid color in SingletonMonoBehaviour<SessionManager>.Instance.GroupColorVault.Colors)
		{
			if (!list.Contains(color.guidString))
			{
				return color.guidString;
			}
		}
		UnityEngine.Debug.LogError("Could not find an unused party color, this is madness. Should never happen in a max 8 player game, add colors to PUNNetworkManager ColorVault.");
		return null;
	}

	private bool IsGroupColorIdAvailable(string playerPartyColorId)
	{
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer player in otherPlayers)
		{
			string customProperty = player.GetCustomProperty<string>(PartyColorIdProperty);
			string customProperty2 = player.GetCustomProperty<string>(PartyIdProperty);
			if (!string.IsNullOrEmpty(customProperty) && playerPartyColorId == customProperty && !string.IsNullOrEmpty(customProperty2) && customProperty2 != CurrentPartyId)
			{
				return false;
			}
		}
		return true;
	}

	[PunRPC]
	private void RpcKickedFromParty(string partyId)
	{
		if (!(partyId != CurrentPartyId))
		{
			LeaveCurrentParty();
		}
	}

	private bool IsValidPartyPlayer(Player player)
	{
		return player != null && player.photonView.owner != null && player.photonView.owner != base.photonView.owner && IsInParty && player.PlayerParty.CurrentPartyId == CurrentPartyId;
	}

	private void UpdatePartyLists(bool forcePartyChange = false)
	{
		bool flag = forcePartyChange;
		if (IsInParty)
		{
			Player[] array = groupPlayers.ToArray();
			foreach (Player player in array)
			{
				if (!IsValidPartyPlayer(player))
				{
					groupPlayers.Remove(player);
					flag = true;
				}
			}
			PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
			foreach (PhotonPlayer photonPlayer in otherPlayers)
			{
				Player player2 = photonPlayer.ToPlayer();
				if (player2 != null && IsValidPartyPlayer(player2) && !groupPlayers.Contains(player2))
				{
					groupPlayers.Add(player2);
					flag = true;
				}
			}
		}
		else if (groupPlayers.Count > 0)
		{
			groupPlayers.Clear();
			flag = true;
		}
		if (flag)
		{
			LocalValidatePartyColorId();
			if (this.PartyUpdateReceived != null)
			{
				this.PartyUpdateReceived();
			}
		}
	}

	private void LocalValidatePartyColorId()
	{
		if (!isLocal || !IsInParty)
		{
			return;
		}
		Player partyAuthority = GetPartyAuthority();
		if (string.IsNullOrEmpty(CurrentPartyColorId) && partyAuthority != null && partyAuthority.isLocal)
		{
			if (!string.IsNullOrEmpty(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId) && IsGroupColorIdAvailable(SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId))
			{
				CurrentPartyColorId = SingletonMonoBehaviour<SessionManager>.Instance.PlayerPartyColorId;
			}
			else
			{
				CurrentPartyColorId = GetNextAvailableGroupColorId();
			}
		}
		if (partyAuthority != null && !partyAuthority.isLocal && partyAuthority.PlayerParty.CurrentPartyColorId != CurrentPartyColorId)
		{
			CurrentPartyColorId = partyAuthority.PlayerParty.CurrentPartyColorId;
		}
	}

	private Player GetPartyAuthority()
	{
		if (IsInParty)
		{
			int iD = PhotonNetwork.player.ID;
			Player result = thisPlayer;
			{
				foreach (Player groupPlayer in groupPlayers)
				{
					if (groupPlayer.PhotonPlayer.ID < iD)
					{
						iD = groupPlayer.PhotonPlayer.ID;
						result = groupPlayer;
					}
				}
				return result;
			}
		}
		return null;
	}

	private void OnPartyIdChanged()
	{
		partyColorDirty = true;
	}

	private void OnPartyColorChanged()
	{
		partyColorDirty = true;
	}

	public virtual void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		UpdatePartyLists(forcePartyChange: true);
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture, Player localPlayer, Player remotePlayer)
	{
		if (isLocal && otherHand != null)
		{
			Vector3 feedbackPosition = Vector3.Lerp(myHand.transform.position, otherHand.transform.position, 0.5f);
			switch (gesture)
			{
			case PlayerHandGestures.Gesture.Highfive:
				SendHighFive(remotePlayer.PhotonPlayer);
				break;
			case PlayerHandGestures.Gesture.HandshakeSuccess:
				SendFriendRequest(remotePlayer.PhotonPlayer, feedbackPosition);
				break;
			case PlayerHandGestures.Gesture.Fistbump:
				JoinParty(remotePlayer.PhotonPlayer, feedbackPosition);
				break;
			}
		}
	}

	private void PlayParticleEffect(ParticleSystem particleSystem, Vector3 position)
	{
		if (particleSystem != null)
		{
			ParticleSystem particleSystem2 = UnityEngine.Object.Instantiate(particleSystem);
			particleSystem2.transform.position = position;
			particleSystem2.Play();
			ParticleSystem.MainModule main = particleSystem2.main;
			UnityEngine.Object.Destroy(particleSystem2.gameObject, main.duration);
		}
	}
}
public class PlayerPartyColorWatchRenderer : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private OutfitItem outfitItem;

	private PlayerParty playerParty;

	private int baseColorShaderId;

	private int accentColorShaderId;

	private Color defaultBaseColor;

	private Color defaultAccentColor;

	private Color lastColor;

	private void Start()
	{
		playerParty = GetComponentInParent<PlayerParty>();
		baseColorShaderId = Shader.PropertyToID("_Red_Col");
		accentColorShaderId = Shader.PropertyToID("_Base_Col");
		Material material = outfitItem.ActiveRenderer.material;
		defaultBaseColor = material.GetColor(baseColorShaderId);
		defaultAccentColor = material.GetColor(accentColorShaderId);
		lastColor = defaultBaseColor;
	}

	private void Update()
	{
		Color value = defaultBaseColor;
		Color value2 = defaultAccentColor;
		if (playerParty != null && playerParty.IsInParty && playerParty.PartyColor.HasValue && playerParty.PartyColor.HasValue)
		{
			value = playerParty.PartyColor.Value;
			value2 = Color.Lerp(value, Color.black, 0.25f);
		}
		if (value != lastColor)
		{
			lastColor = value;
			Material material = outfitItem.ActiveRenderer.material;
			material.SetColor(baseColorShaderId, value);
			material.SetColor(accentColorShaderId, value2);
		}
	}
}
public class PlayerProgression : Photon.MonoBehaviour
{
	public enum Feedback
	{
		LevelUp,
		Cheer
	}

	[Header("Feedback")]
	[SerializeField]
	private PooledParticle levelUpParticlesPrefab;

	[SerializeField]
	private PooledParticle cheerParticlesPrefab;

	private Player thisPlayer;

	private SynchronizedPlayerField<int> _level;

	private SynchronizedPlayerField<bool> _isMember;

	public int Level
	{
		get
		{
			return _level.Get();
		}
		private set
		{
			if (isLocal)
			{
				if (_level.HasValue && value > Level)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "You Leveled Up!", 5f, PlayLevelUpFeedback);
					SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(ProgressionManager.ObjectiveType.LevelUp, 1f, GameSessions.LocalGameSession?.RoomId);
					thisPlayer.PlayerEvents.LevelUp(value);
				}
				_level.Set(value);
			}
		}
	}

	public bool IsMember
	{
		get
		{
			return _isMember.Get();
		}
		private set
		{
			_isMember.Set(value);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		thisPlayer = GetComponent<Player>();
		_level = new SynchronizedPlayerField<int>(base.owner, "PlayerLevel", 1);
		_isMember = new SynchronizedPlayerField<bool>(base.owner, "PlayerMember", defaultValue: false);
		if (isLocal)
		{
			Level = Profiles.LocalProfile.Level;
			Profiles.LocalProfileDownloaded += Profile_LocalProfileDownloaded;
			Profile_LocalProfileDownloaded(Profiles.LocalProfile);
			Profiles.LocalProfileLevelUpdated += Profile_LocalProfileLevelUpdated;
			Profiles.LocalProfileXpUpdated += Profile_LocalProfileXpUpdated;
		}
	}

	protected override void OnDestroy()
	{
		if (isLocal)
		{
			Profiles.LocalProfileDownloaded -= Profile_LocalProfileDownloaded;
			Profiles.LocalProfileLevelUpdated -= Profile_LocalProfileLevelUpdated;
			Profiles.LocalProfileXpUpdated -= Profile_LocalProfileXpUpdated;
		}
		base.OnDestroy();
	}

	private void Profile_LocalProfileXpUpdated(int currentXp, int deltaXp)
	{
		thisPlayer.PlayerEvents.XPUpdated(currentXp);
	}

	private void Profile_LocalProfileLevelUpdated(int level)
	{
		Level = level;
	}

	private void Profile_LocalProfileDownloaded(Profile profile)
	{
		if (isLocal)
		{
			IsMember = profile?.Verified ?? false;
		}
	}

	public void PlayLevelUpFeedback()
	{
		base.photonView.RpcAll(RpcPlayLevelUpFeedback, Feedback.LevelUp);
	}

	public void PlayCheerFeedback()
	{
		base.photonView.RpcAll(RpcPlayLevelUpFeedback, Feedback.Cheer);
	}

	[PunRPC]
	private void RpcPlayLevelUpFeedback(Feedback feedback)
	{
		PooledParticle pooledParticle = null;
		switch (feedback)
		{
		default:
			return;
		case Feedback.LevelUp:
			thisPlayer.PlayerAudio.OnLevelUp();
			pooledParticle = levelUpParticlesPrefab;
			break;
		case Feedback.Cheer:
			thisPlayer.PlayerAudio.OnCheered();
			pooledParticle = cheerParticlesPrefab;
			break;
		}
		PooledParticle pooledParticle2 = ObjectPool.Instance.Acquire(pooledParticle);
		if (pooledParticle2 != null)
		{
			pooledParticle2.Play();
			PlayerFloorPositionFollowing component = pooledParticle2.GetComponent<PlayerFloorPositionFollowing>();
			if (component != null)
			{
				component.TrackedPlayer = thisPlayer;
				return;
			}
			pooledParticle2.transform.position = thisPlayer.CurrentFloorPosition;
			pooledParticle2.transform.rotation = Quaternion.LookRotation(Vector3.right, Vector3.forward);
		}
	}
}
public class PlayerTeleportDecal : UnityEngine.MonoBehaviour
{
	public enum DecalVisibilityMode
	{
		NONE,
		TOOL_HIT,
		BASE_ONLY,
		BASE_AND_BEAM
	}

	public enum DecalTargetValidity
	{
		VALID,
		INVALID
	}

	private static MaterialPropertyBlock INSTANTANEOUS_MATERIAL_PROPERTIES;

	[Header("Visuals")]
	[SerializeField]
	private Transform baseVisual;

	[SerializeField]
	private Transform beamVisual;

	[Header("Tool Hit Visual")]
	[SerializeField]
	private TeleportChargeVisual toolHitVisual;

	[Header("Materials")]
	[SerializeField]
	private Material validMaterial;

	[SerializeField]
	private Material validMaterialNoDepth;

	[SerializeField]
	private Material invalidMaterial;

	[SerializeField]
	private Material invalidMaterialNoDepth;

	[SerializeField]
	private RecRoomQualitySetting[] noDepthSettings = new RecRoomQualitySetting[2]
	{
		RecRoomQualitySetting.PS4,
		RecRoomQualitySetting.Fastest
	};

	[HideInInspector]
	public List<Renderer> Renderers = new List<Renderer>();

	private static int SHADER_COLOR_ID = Shader.PropertyToID("_MainColor");

	private static int ANIMATOR_VALID_ID = Animator.StringToHash("Valid");

	private static int ANIMATOR_VISIBLE_ID = Animator.StringToHash("Visible");

	private static int ANIMATOR_CHARGE_ID = Animator.StringToHash("Charge");

	private static int ANIMATOR_DEFAULT_STATE = Animator.StringToHash("TeleportBeam_Birth");

	private Animator animator;

	private Material _runtimeValidMaterial;

	private Material _runtimeValidMaterialNoDepth;

	private Material activeValidMaterial;

	private Material activeInvalidMaterial;

	private DecalVisibilityMode visibilityMode;

	private DecalTargetValidity targetValidity;

	private Color _color;

	public DecalVisibilityMode VisibilityMode
	{
		get
		{
			return visibilityMode;
		}
		set
		{
			if (visibilityMode != value)
			{
				visibilityMode = value;
				OnVisibilityModeChanged();
			}
		}
	}

	public DecalTargetValidity TargetValidity
	{
		get
		{
			return targetValidity;
		}
		set
		{
			if (targetValidity != value)
			{
				targetValidity = value;
				RefreshValidityVisuals();
			}
		}
	}

	public Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			value.a = DefaultColor.Value.a;
			_color = value;
			UpdateRenderers();
		}
	}

	public static Color? DefaultColor { get; private set; }

	private void Awake()
	{
		AssignMaterialReferencesForQualitySetting(RecRoomQualitySetting.Fantastic);
		if (!DefaultColor.HasValue || !DefaultColor.HasValue)
		{
			_color = activeValidMaterial.GetColor(SHADER_COLOR_ID);
			DefaultColor = Color;
		}
		Color = DefaultColor.Value;
		animator = GetComponentInChildren<Animator>();
		if (animator != null)
		{
			animator.SetBool(ANIMATOR_VISIBLE_ID, value: false);
		}
		Renderers.AddRange(GetComponentsInChildren<Renderer>(includeInactive: true));
		VisibilityMode = DecalVisibilityMode.NONE;
		OnVisibilityModeChanged();
	}

	private void Start()
	{
		SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
		OnQualitySettingChanged(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
	}

	private void OnDestroy()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
		}
	}

	private void OnVisibilityModeChanged()
	{
		bool flag = visibilityMode == DecalVisibilityMode.BASE_AND_BEAM;
		bool flag2 = visibilityMode == DecalVisibilityMode.BASE_AND_BEAM || visibilityMode == DecalVisibilityMode.BASE_ONLY;
		bool flag3 = visibilityMode == DecalVisibilityMode.TOOL_HIT;
		beamVisual.gameObject.SetActive(flag);
		baseVisual.gameObject.SetActive(flag2);
		toolHitVisual.gameObject.SetActive(flag3);
		bool flag4 = flag || flag2 || flag3;
		if (animator != null)
		{
			animator.SetBool(ANIMATOR_VISIBLE_ID, flag4);
			if (!flag4)
			{
				animator.Play(ANIMATOR_DEFAULT_STATE);
			}
		}
	}

	private void OnQualitySettingChanged(RecRoomQualitySetting setting)
	{
		AssignMaterialReferencesForQualitySetting(setting);
		UpdateRenderers();
	}

	private void AssignMaterialReferencesForQualitySetting(RecRoomQualitySetting setting)
	{
		if (noDepthSettings.Contains(setting))
		{
			if (_runtimeValidMaterialNoDepth == null)
			{
				_runtimeValidMaterialNoDepth = new Material(validMaterialNoDepth);
			}
			activeValidMaterial = _runtimeValidMaterialNoDepth;
			activeInvalidMaterial = invalidMaterialNoDepth;
		}
		else
		{
			if (_runtimeValidMaterial == null)
			{
				_runtimeValidMaterial = new Material(validMaterial);
			}
			activeValidMaterial = _runtimeValidMaterial;
			activeInvalidMaterial = invalidMaterial;
		}
	}

	public void UpdatePosition(Vector3 groundPoint, Vector3 groundForward)
	{
		base.transform.position = groundPoint;
		base.transform.rotation = Quaternion.LookRotation(groundForward, Vector3.up);
	}

	public void UpdateCharge(float charge)
	{
		if (animator != null)
		{
			animator.SetFloat(ANIMATOR_CHARGE_ID, Mathf.Clamp01(charge));
		}
	}

	public void UpdateToolHitDecal(bool enabled, float charge, Vector3 toolHitPosition, Vector3 toolHitNormal)
	{
		if (enabled)
		{
			VisibilityMode = DecalVisibilityMode.TOOL_HIT;
			toolHitVisual.Charge = charge;
			toolHitVisual.transform.position = toolHitPosition;
			toolHitVisual.transform.rotation = Quaternion.LookRotation(toolHitNormal, Vector3.up);
		}
	}

	private void RefreshValidityVisuals()
	{
		if (animator != null)
		{
			animator.SetBool(ANIMATOR_VALID_ID, TargetValidity != DecalTargetValidity.INVALID);
		}
		UpdateRenderers();
	}

	private void UpdateRenderers()
	{
		if (INSTANTANEOUS_MATERIAL_PROPERTIES == null)
		{
			INSTANTANEOUS_MATERIAL_PROPERTIES = new MaterialPropertyBlock();
		}
		bool flag = TargetValidity == DecalTargetValidity.VALID;
		foreach (Renderer renderer in Renderers)
		{
			renderer.sharedMaterial = ((!flag) ? activeInvalidMaterial : activeValidMaterial);
			INSTANTANEOUS_MATERIAL_PROPERTIES.Clear();
			if (flag)
			{
				INSTANTANEOUS_MATERIAL_PROPERTIES.SetColor(SHADER_COLOR_ID, Color);
			}
			renderer.SetPropertyBlock(INSTANTANEOUS_MATERIAL_PROPERTIES);
		}
	}
}
namespace RecRoom.Core
{
	public class ToolEquipSlot
	{
		public enum EquipSlotType
		{
			Hip,
			Shoulder,
			Other
		}

		public delegate void EquipAction(Tool tool, ToolEquipSlot thisSlot);

		[NonSerialized]
		public bool HotSwapToolOnDrop = true;

		private EquipSlotType equipSlotType;

		private readonly Photon.MonoBehaviour attachedObject;

		private readonly Transform attachedLocalTransform;

		private SynchronizedField<int> _equippedToolId;

		private Tool _cachedEquippedTool;

		private float lastEquipTime;

		private const float EQUIP_COOLDOWN = 0.5f;

		public EquipAction ToolEquipEvent;

		public EquipAction ToolUnequipEvent;

		public bool IsFull => EquippedTool != null;

		public Tool EquippedTool
		{
			get
			{
				return _cachedEquippedTool;
			}
			private set
			{
				_equippedToolId.Set((!(value != null)) ? (-1) : value.photonView.viewID);
			}
		}

		public EquipSlotType SlotType => equipSlotType;

		public ToolEquipSlot(EquipSlotType equipSlotType, Photon.MonoBehaviour attachedObject, Transform attachedLocalTransform, string id)
		{
			this.equipSlotType = equipSlotType;
			this.attachedObject = attachedObject;
			this.attachedLocalTransform = attachedLocalTransform;
			_equippedToolId = new SynchronizedField<int>(attachedObject, "TES." + id, -1, SetterPermissionMode.AUTHORITY, OnEquippedToolChange);
		}

		public void InitializeOnStart()
		{
			OnEquippedToolChange();
		}

		public bool IsOnEquipCooldown()
		{
			return UnityEngine.Time.time - lastEquipTime < 0.5f;
		}

		public bool TryEquipTool(Tool tool)
		{
			return TryEquipTool(tool, null);
		}

		public bool TryEquipTool(Tool tool, PlayerHand pickupHand)
		{
			if (EquippedTool != null)
			{
				Tool equippedTool = EquippedTool;
				EquippedTool.HolderInfo = ToolHolderInfo.NotHeld;
				if (pickupHand != null && HotSwapToolOnDrop)
				{
					equippedTool.AddLockOnPickup(newValue: true, this);
					pickupHand.TryPickupTool(equippedTool, inPhysicalPickupRange: true);
					equippedTool.RemoveLockOnPickup(this);
				}
			}
			if (!IsOnEquipCooldown())
			{
				EquippedTool = tool;
				return true;
			}
			return false;
		}

		public bool TryRemoveTool(Tool tool)
		{
			if (EquippedTool == tool)
			{
				EquippedTool = null;
				return true;
			}
			return false;
		}

		public void GetAttachPositionRotationWorldSpace(Tool tool, out Vector3 position, out Quaternion rotation)
		{
			tool.GetEquipSlotPickupTransform(equipSlotType, out var localPickupPosition, out var localPickupRotation);
			position = attachedLocalTransform.TransformPoint(localPickupPosition);
			rotation = attachedLocalTransform.TransformRotation(localPickupRotation);
		}

		private void OnEquippedToolChange()
		{
			if (_cachedEquippedTool != null)
			{
				_cachedEquippedTool.PostDetachEvent -= OnEquippedToolDetach;
				if (ToolUnequipEvent != null)
				{
					ToolUnequipEvent(_cachedEquippedTool, this);
				}
			}
			PhotonView photonView = PhotonView.Find(_equippedToolId.Get());
			_cachedEquippedTool = ((!(photonView != null)) ? null : photonView.GetComponent<Tool>());
			if (_cachedEquippedTool != null)
			{
				if (attachedObject.hasAuthority)
				{
					_cachedEquippedTool.photonView.TransferOwnership(PhotonNetwork.player);
					GetAttachPositionRotationWorldSpace(_cachedEquippedTool, out var position, out var rotation);
					Vector3 localPosition = attachedObject.transform.InverseTransformPoint(position);
					Quaternion localRotation = attachedObject.transform.InverseTransformRotation(rotation);
					float localScale = attachedObject.transform.InverseTransformLossyUniformScale(_cachedEquippedTool.transform.GetLossyUniformScale());
					_cachedEquippedTool.AuthorityEquipToPlayer(attachedObject.photonView, localPosition, localRotation, localScale);
				}
				_cachedEquippedTool.PostDetachEvent += OnEquippedToolDetach;
				lastEquipTime = UnityEngine.Time.time;
				if (ToolEquipEvent != null)
				{
					ToolEquipEvent(_cachedEquippedTool, this);
				}
			}
		}

		private void OnEquippedToolDetach(Tool detachedTool)
		{
			if (detachedTool == EquippedTool)
			{
				EquippedTool = null;
			}
		}
	}
