		private Tool GetPreviewTool(PlayerHand hand)
		{
			if (hand == null)
			{
				return null;
			}
			Tool heldTool = hand.HeldTool;
			if (heldTool == null)
			{
				return null;
			}
			if (!thisPlayer.ToolEquipSlots.CanEquipTool(heldTool, hand, this))
			{
				return null;
			}
			return heldTool;
