		public bool TryEquipTool(Tool tool, PlayerHand unequipPickupHand, bool canDisplaceEquippedTool = true)
		{
			if (IsFull && !canDisplaceEquippedTool)
			{
				return false;
			}
			if (!thisPlayer.isLocal)
			{
				return false;
			}
			if (!thisPlayer.CanInteractWithTools)
			{
				return false;
			}
			if (tool == null || tool.IsHeld || !tool.IsValidAttach())
			{
				return false;
			}
			if (!CanEquipTool(tool, unequipPickupHand))
			{
				return false;
			}
			if (CustomEquipBehavior != null && CustomEquipBehavior(tool, this))
			{
				return true;
			}
			return equipSlot.TryEquipTool(tool, unequipPickupHand);
		}

		public void DropTool()
		{
			if (!thisPlayer.isLocal || !equipSlot.IsFull)
			{
				return;
			}
			for (int i = 0; i < customDropConditions.Count; i++)
			{
				if (customDropConditions[i] != null && !customDropConditions[i](equipSlot.EquippedTool, this))
				{
					return;
				}
			}
			equipSlot.TryEquipTool(null);
		}

		public void AddCustomEquipCondition(EquipCondition condition)
		{
			customEquipConditions.Add(condition);
		}

		public void RemoveCustomEquipCondition(EquipCondition condition)
		{
