		}

		public void RemoveCustomDropCondition(DropCondition condition)
		{
			customDropConditions.Remove(condition);
		}

		public bool IsHandInSelectionVolume(Vector3 handPosition)
		{
			return volume.ContainsPoint(handPosition);
		}

		public bool CanEquipTool(Tool tool, PlayerHand droppingHand)
		{
			if (!thisPlayer.CanInteractWithTools)
			{
				return false;
			}
			if (!tool.IsValidAttach())
			{
				return false;
			}
			if (!tool.IsValidEquip(thisPlayer, equipSlot))
			{
				return false;
			}
			if (AutomaticallyEquipToolOnDrop && droppingHand != null && !IsHandInSelectionVolume(droppingHand.RigidbodyEx.targetPosition))
			{
				return false;
			}
			if (equipRestrictionType != RolePickupRestrictionType.NoRestrictions)
			{
				switch (equipRestrictionType)
				{
				case RolePickupRestrictionType.AllRestricted:
					return false;
				case RolePickupRestrictionType.Whitelist:
					if (!TaggedTool.CheckTagRestrictions(tool, whitelist: true, equipRestrictionWhitelist))
					{
						return false;
					}
					break;
				case RolePickupRestrictionType.Blacklist:
					if (!TaggedTool.CheckTagRestrictions(tool, whitelist: false, equipRestrictionBlacklist))
					{
						return false;
					}
					break;
				}
			}
			for (int i = 0; i < customEquipConditions.Count; i++)
			{
				if (!customEquipConditions[i](tool, this))
				{
					return false;
				}
			}
			return true;
		}

		private void OnStaticToolPostRelease(Tool releasedTool)
		{
			if (base.enabled && AutomaticallyEquipToolOnDrop && !(releasedTool == null) && !releasedTool.IsSubTool && releasedTool.IsHeldByPlayer && !(releasedTool.HolderPlayer == null) && !(releasedTool.HolderHand == null) && !(releasedTool.HolderPlayer != thisPlayer) && thisPlayer.ToolEquipSlots.CanEquipTool(releasedTool, releasedTool.HolderHand, this))
			{
				StartCoroutine(DelayedEquip(releasedTool, releasedTool.HolderHand));
			}
		}

		private IEnumerator DelayedEquip(Tool tool, PlayerHand droppingHand)
		{
			yield return null;
			if (droppingHand != null && droppingHand.HeldTool != null)
			{
				droppingHand = null;
			}
			TryEquipTool(tool, droppingHand);
		}

		private void OnSlotEquip(Tool equippedTool, ToolEquipSlot slot)
		{
			equippedTool.AddCustomPickupCondition(EquippedToolCustomPickupCondition);
			if (this.ToolEquipEvent != null)
			{
				this.ToolEquipEvent(equippedTool, this);
			}
		}

		private void OnSlotUnequip(Tool unequippedTool, ToolEquipSlot slot)
		{
			unequippedTool.RemoveCustomPickupCondition(EquippedToolCustomPickupCondition);
			if (this.ToolUnequipEvent != null)
			{
				this.ToolUnequipEvent(unequippedTool, this);
			}
		}

		private bool EquippedToolCustomPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool isPhysicalPickup)
		{
			return selectingPlayer == thisPlayer && volume.ContainsPoint(selectionPoint);
		}

		public void ChangeEquipRestrictions(RolePickupRestrictionType restrictionType, List<string> whitelist, List<string> blacklist)
		{
			RolePickupRestrictionType rolePickupRestrictionType = equipRestrictionType;
			List<string> list = equipRestrictionWhitelist;
			List<string> list2 = equipRestrictionBlacklist;
			equipRestrictionType = restrictionType;
			equipRestrictionWhitelist = whitelist;
			equipRestrictionBlacklist = blacklist;
			bool flag = base.enabled;
			bool flag2 = restrictionType != RolePickupRestrictionType.AllRestricted;
			if (flag2)
			{
				Player.LocalPlayer.Body.AlignWithGravity = true;
			}
			base.enabled = flag2;
			if (base.enabled != flag && this.EnabledChanged != null)
			{
				this.EnabledChanged(base.enabled);
			}
			if (this.EquipRestrictionsChanged == null)
			{
				return;
			}
			bool flag3 = rolePickupRestrictionType != equipRestrictionType;
			int num3;
			if ((list != null || whitelist == null) && (list == null || whitelist != null))
			{
				int? num = list?.Count;
				int valueOrDefault = num.GetValueOrDefault();
				int? num2 = whitelist?.Count;
				num3 = ((valueOrDefault != num2.GetValueOrDefault() || (num.HasValue ^ num2.HasValue)) ? 1 : 0);
			}
			else
			{
				num3 = 1;
			}
			bool flag4 = (byte)num3 != 0;
			int num6;
			if ((list2 != null || blacklist == null) && (list2 == null || blacklist != null))
			{
				int? num4 = list2?.Count;
				int valueOrDefault2 = num4.GetValueOrDefault();
				int? num5 = blacklist?.Count;
				num6 = ((valueOrDefault2 != num5.GetValueOrDefault() || (num4.HasValue ^ num5.HasValue)) ? 1 : 0);
			}
			else
			{
				num6 = 1;
			}
			bool flag5 = (byte)num6 != 0;
			if (!flag4)
			{
				for (int i = 0; i < list.Count; i++)
				{
					if (list[i] != whitelist[i])
					{
						flag4 = true;
						break;
					}
				}
			}
			if (!flag5)
			{
				for (int j = 0; j < list2.Count; j++)
				{
					if (list2[j] != blacklist[j])
					{
						flag5 = true;
						break;
					}
				}
			}
			if (flag3 || flag4 || flag5)
			{
				this.EquipRestrictionsChanged();
			}
		}
	}
