		public bool TryEquipTool(Tool tool, PlayerHand unequipPickupHand, PlayerToolEquipSlot equipSlot, bool canDisplaceEquippedTool = true)
		{
			if (!CanEquipTool(tool, unequipPickupHand, equipSlot))
			{
				return false;
			}
			return equipSlot.TryEquipTool(tool, unequipPickupHand, canDisplaceEquippedTool);
		}

		public bool CanEquipTool(Tool tool, PlayerHand unequipPickupHand, PlayerToolEquipSlot equipSlot)
		{
			if (equipSlot.SlotType == ToolEquipSlot.EquipSlotType.Hip)
			{
				if (HipSlotEnableMode == HipEquipSlotEnableMode.ALL_DISABLED)
				{
					return false;
				}
				if (HipSlotEnableMode == HipEquipSlotEnableMode.ONE_ENABLED && ((equipSlot == LeftHipSlot && RightHipSlot.IsFull) || (equipSlot == RightHipSlot && LeftHipSlot.IsFull)))
				{
					return false;
				}
			}
			return equipSlot.CanEquipTool(tool, unequipPickupHand);
		}

		public void DropAllTools()
		{
			for (int i = 0; i < AllSlots.Length; i++)
			{
				AllSlots[i].DropTool();
			}
		}

		public void EquipTools(EquippedTool[] equippedTools)
		{
			for (int i = 0; i < AllSlots.Length; i++)
			{
				if (equippedTools[i].EquipSlot != null && !equippedTools[i].EquipSlot.IsFull && equippedTools[i].Tool != null)
				{
					equippedTools[i].EquipSlot.TryEquipTool(equippedTools[i].Tool, null, canDisplaceEquippedTool: false);
				}
			}
		}

		public EquippedTool[] GetAllEquippedTools()
		{
			equippedTools.Clear();
			for (int i = 0; i < AllSlots.Length; i++)
			{
				if (AllSlots[i].EquippedTool != null)
				{
					equippedTools.Add(new EquippedTool
					{
						EquipSlot = AllSlots[i],
						Tool = AllSlots[i].EquippedTool
					});
				}
			}
			return equippedTools.ToArray();
		}

		private void OnSlotToolEquip(Tool tool, PlayerToolEquipSlot slot)
		{
			if (thisPlayer.isLocal && thisPlayer.BlobShadowProjector != null)
			{
				tool.AddBlobShadowCasters(thisPlayer.BlobShadowProjector);
			}
			if (this.ToolEquipEvent != null)
			{
				this.ToolEquipEvent(tool);
			}
		}

		private void OnSlotToolUnequip(Tool tool, PlayerToolEquipSlot slot)
		{
			if (thisPlayer.isLocal && thisPlayer.BlobShadowProjector != null)
			{
				tool.RemoveBlobShadowCasters(thisPlayer.BlobShadowProjector);
			}
			if (this.ToolUnequipEvent != null)
			{
				this.ToolUnequipEvent(tool);
			}
		}

		private void OnSlotEnabledChanged(bool enabled)
		{
			if (!Player.LocalPlayerExists)
			{
				return;
			}
			bool alignWithGravity = false;
			for (int i = 0; i < AllSlots.Length; i++)
			{
				if (AllSlots[i].enabled)
				{
					alignWithGravity = true;
					break;
				}
			}
			Player.LocalPlayer.Body.AlignWithGravity = alignWithGravity;
		}
	}
}
