		remove
		{
			Action action = PlayerTrackingSpace.m_OnLocalPlayerTrackingSpaceRigidbodyExLateUpdate;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref PlayerTrackingSpace.m_OnLocalPlayerTrackingSpaceRigidbodyExLateUpdate, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	protected override void Awake()
