	private void PlayerRoleUpdated(PhotonPlayer player, GameRole role)
	{
		if (role != null)
		{
			if (role.HidesName.Overrides && role.HidesName.Value)
			{
				NamesHiddenFlag.Add(this);
			}
			else
			{
				NamesHiddenFlag.Remove(this);
			}
		}
	}

	private void UpdatePlayerName()
	{
		if (isLocal)
		{
			return;
		}
		bool flag = !NamesHiddenFlag.HasTokens && SingletonMonoBehaviour<SettingsManager>.Instance.ShowNames && thisPlayer.IsVisible;
		labelCanvas.gameObject.SetActive(flag);
		if (!flag || base.owner == null)
		{
			return;
		}
		Color color = Color.white;
		Color? teamColor = TeamColor;
		if (teamColor.HasValue)
		{
			color = TeamColor.Value;
		}
		else
		{
			Color? sandboxTeamColor = SandboxTeamColor;
			if (sandboxTeamColor.HasValue)
			{
				color = SandboxTeamColor.Value;
			}
			else if (thisPlayer.PlayerParty.PartyColor.HasValue)
			{
				color = thisPlayer.PlayerParty.PartyColor.Value;
			}
		}
		if (color != cachedLabelColor)
		{
			labelMesh.material.color = color;
			cachedLabelColor = color;
		}
	}

	public void RefreshDeveloperDisplay()
	{
		if (developerDisplay == null)
		{
			return;
		}
		Profile profile = Profiles.Get(thisPlayer.PlayerId);
		if (profile != null && !profile.Developer.GetDecrypted())
		{
			UnityEngine.Object.Destroy(developerDisplay.gameObject);
			return;
		}
		bool flag = profile != null && profile.Developer.GetDecrypted() && thisPlayer.DeveloperDisplayMode != SettingsManager.DeveloperDisplayModes.None && thisPlayer.IsVisible;
		string text = thisPlayer.DeveloperDisplayMode switch
		{
			SettingsManager.DeveloperDisplayModes.Developer => "Developer", 
			SettingsManager.DeveloperDisplayModes.CommunityTeam => "Community Team", 
			_ => string.Empty, 
		};
		developerDisplayText.text = text;
		if (flag != developerDisplay.gameObject.activeSelf)
		{
			developerDisplay.gameObject.SetActive(flag);
		}
	}

