	private void Profiles_OnProfileUpdated(long id)
	{
		if (!(thisPlayer != null) || thisPlayer.PlayerId != id)
		{
			return;
		}
		Profile profile = Profiles.Get(thisPlayer.PlayerId);
		if ((!savedIsBlocked || !nameLabelText.text.StartsWith("[Blocked] ") || !((ObscuredString)nameLabelText.text.Substring(10) != profile.DisplayName)) && (savedIsBlocked || !((ObscuredString)nameLabelText.text != profile.DisplayName)) && savedLevelValue == (int)profile.Level)
		{
			PlayerCheering.CheerCategory? cheerCategory = savedActiveCheer;
			PlayerCheering.CheerCategory valueOrDefault = cheerCategory.GetValueOrDefault();
			PlayerCheering.CheerCategory? activeCheer = profile.GetActiveCheer();
			if (valueOrDefault == activeCheer.GetValueOrDefault() && !(cheerCategory.HasValue ^ activeCheer.HasValue))
			{
				goto IL_00fc;
			}
		}
		SetupNameLabelForProfile(profile);
		goto IL_00fc;
		IL_00fc:
		RefreshDeveloperDisplay();
	}

	private void Relationships_RelationshipUpdated(long? playerId)
	{
		if (thisPlayer != null && thisPlayer.PlayerId == playerId.GetValueOrDefault() && playerId.HasValue)
		{
			Relationship relationship = Relationships.Get(thisPlayer.PlayerId);
			if (relationship != null && relationship.Ignored != Relationship.ReciprocalStatus.None != savedIsBlocked)
			{
				SetupNameLabelForProfile(Profiles.Get(playerId.Value));
			}
		}
	}

	private void OnRecNetMessageListUpdated(Messages.UpdateType updateType)
	{
		if (Messages.MessageList.Count == 0)
		{
			WatchAttractor.ClearMessageNotification();
		}
	}

	private void PlayerHandGestures_GestureDetected(PlayerHand myHand, PlayerHand otherHand, PlayerHandGestures.Gesture gesture, Player localPlayer, Player remotePlayer)
	{
		switch (gesture)
		{
		case PlayerHandGestures.Gesture.Highfive:
		{
			Vector3 position3 = ((!(otherHand == null)) ? ((myHand.transform.position + otherHand.transform.position) / 2f) : myHand.transform.position);
			if (!myHand.Gestures.ShouldSuppressHighFiveEffect && (otherHand == null || !otherHand.Gestures.ShouldSuppressHighFiveEffect))
			{
				thisPlayer.PlayerAudio.OnHighFive(position3);
				PlayParticleEffect(highFiveParticles, position3);
			}
			break;
		}
		case PlayerHandGestures.Gesture.HandshakeStart:
			StartHandshakeFeedback(myHand, otherHand, 2f);
			break;
		case PlayerHandGestures.Gesture.HandshakeCancel:
			StopHandshakeFeedback();
			break;
		case PlayerHandGestures.Gesture.HandshakeSuccess:
			StopHandshakeFeedback();
			PlayHandshakeSuccessParticles(myHand, otherHand);
			break;
		case PlayerHandGestures.Gesture.StopGestureCharging:
			StartStopGestureFeedback(myHand);
			break;
		case PlayerHandGestures.Gesture.StopGestureSuccess:
		{
			StopStopGestureFeedback();
			Vector3 position2 = myHand.transform.position;
			thisPlayer.PlayerAudio.OnStopGestureSuccess(position2);
			PlayParticleEffect(stopGestureSuccessParticles, position2);
			break;
		}
		case PlayerHandGestures.Gesture.StopGestureCancel:
			StopStopGestureFeedback();
			break;
		case PlayerHandGestures.Gesture.CheerGestureCharging:
			StartCheerGestureFeedback(myHand);
			break;
		case PlayerHandGestures.Gesture.CheerGestureSuccess:
		{
			StopCheerGestureFeedback();
			Vector3 position = myHand.transform.position;
			thisPlayer.PlayerAudio.OnCheerGestureSuccess(position);
			PlayParticleEffect(cheerGestureSuccessParticles, position);
			break;
		}
		case PlayerHandGestures.Gesture.CheerGestureCancel:
			StopCheerGestureFeedback();
			break;
		}
		if (isLocal)
		{
			myHand.Vibrate(100);
		}
	}

	private void PlayParticleEffect(ParticleSystem particleSystem, Vector3 position)
	{
		if (particleSystem != null)
		{
			ParticleSystem particleSystem2 = UnityEngine.Object.Instantiate(particleSystem);
			particleSystem2.transform.position = position;
			particleSystem2.Play();
			ParticleSystem.MainModule main = particleSystem2.main;
			UnityEngine.Object.Destroy(particleSystem2.gameObject, main.duration);
		}
	}

	private void UpdateExpressoButtons(PlayerHand leftHand, bool leftHandButtonDown, bool leftHandButtonPressed, PlayerHand rightHand, bool rightHandButtonDown, bool rightHandButtonPressed)
	{
		if (!MenusCanBeOpened)
		{
			return;
		}
		closedExpressoThisFrame = null;
		if (expressoButtonHeldHand == null)
		{
			if (leftHandButtonDown && IsHandAllowedToOpenExpresso(leftHand) && (WatchMenuProjector.AttachedHand.Type != PlayerHand.HandType.Left || !IsWatchMenuOpen))
			{
				expressoButtonHeldHand = thisPlayer.LeftHand;
				expressoButtonPressedStartTime = UnityEngine.Time.time;
				expressoButtonHeldHand.ExpressoInfoGestureActive = !expressoButtonHeldHand.ExpressoInfoGestureActive;
			}
			else if (rightHandButtonDown && IsHandAllowedToOpenExpresso(rightHand) && (WatchMenuProjector.AttachedHand.Type != PlayerHand.HandType.Right || !IsWatchMenuOpen))
			{
				expressoButtonHeldHand = thisPlayer.RightHand;
				expressoButtonPressedStartTime = UnityEngine.Time.time;
				expressoButtonHeldHand.ExpressoInfoGestureActive = !expressoButtonHeldHand.ExpressoInfoGestureActive;
			}
			return;
		}
		if (UnityEngine.Time.time - expressoButtonPressedStartTime >= ((!expressoButtonHeldHand.IsHoldingTool) ? requiredMenuButtonPressTime : requiredMenuButtonPressTimeWithTool) && !openedExpressoUI && !IsWatchMenuOpen)
		{
			ExpressoMenu.ShowUI(show: true, expressoButtonHeldHand);
			openedExpressoUI = true;
		}
		if (ExpressoMenu.Showing)
		{
			expressoButtonHeldHand.AddIntersectingUIRegion(ExpressoMenu.gameObject);
		}
		else
		{
			expressoButtonHeldHand.RemoveIntersectingUIRegion(ExpressoMenu.gameObject);
		}
		if (!((expressoButtonHeldHand.Type != PlayerHand.HandType.Left) ? rightHandButtonPressed : leftHandButtonPressed))
		{
			expressoButtonHeldHand.RemoveIntersectingUIRegion(ExpressoMenu.gameObject);
			if (openedExpressoUI)
			{
				closedExpressoThisFrame = expressoButtonHeldHand;
				openedExpressoUI = false;
				ExpressoMenu.ShowUI(show: false);
			}
			expressoButtonHeldHand = null;
		}
	}

	private bool IsHandAllowedToOpenExpresso(PlayerHand hand)
	{
		bool flag = IsWatchMenuOpen && hand.IsHoldingTool && hand.HeldTool.PlayerSpawnedEquipment != null && hand.HeldTool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.Backpack && hand.HeldTool.IsLocked;
		return !flag;
	}

	private void RefreshNameLabel()
	{
		SetupNameLabelForProfile(Profiles.Get(thisPlayer.PlayerId));
	}

	private void SetupNameLabelForProfile(Profile profile)
	{
		if (profile == null)
		{
			SetupNameLabel(thisPlayer.PlayerName, thisPlayer.PlayerProgression.Level, null, Relationships.Get(thisPlayer.PlayerId));
		}
		else
		{
			SetupNameLabel(profile.DisplayName, profile.Level, profile.GetActiveCheer(), Relationships.Get(profile.Id));
		}
	}

	private void SetupNameLabel(string displayName, int level, PlayerCheering.CheerCategory? activeCheer, Relationship relationship)
	{
		bool activeSelf = labelCanvas.gameObject.activeSelf;
		labelCanvas.gameObject.SetActive(value: true);
		labelCanvas.enabled = true;
		savedIsBlocked = relationship != null && relationship.Ignored != Relationship.ReciprocalStatus.None;
		nameLabelText.text = ((!savedIsBlocked) ? string.Empty : "[Blocked] ") + displayName;
		savedLevelValue = level;
		levelText.text = savedLevelValue.ToString();
		nameLabelText.color = Color.white;
		levelText.color = Color.white;
		levelTextBackground.color = Color.white;
		bool flag = PlayerRoomRoleManager.IsPlayerAHost(thisPlayer.PhotonPlayer);
		levelTextBackground.gameObject.SetActive(!flag);
		levelHostTextBackground.gameObject.SetActive(flag);
		cheerBadge_General.enabled = false;
		cheerBadge_Helpful.enabled = false;
		cheerBadge_Sportsman.enabled = false;
		cheerBadge_GreatHost.enabled = false;
		cheerBadge_Creative.enabled = false;
		Profile profile = Profiles.Get(thisPlayer.PlayerId);
		if (profile != null)
		{
			savedActiveCheer = activeCheer;
			PlayerCheering.CheerCategory? cheerCategory = savedActiveCheer;
			if (cheerCategory.HasValue)
			{
				switch (savedActiveCheer.Value)
				{
				case PlayerCheering.CheerCategory.General:
					cheerBadge_General.enabled = true;
					break;
				case PlayerCheering.CheerCategory.Helpful:
					cheerBadge_Helpful.enabled = true;
					break;
				case PlayerCheering.CheerCategory.Sportmanship:
					cheerBadge_Sportsman.enabled = true;
					break;
				case PlayerCheering.CheerCategory.GreatHost:
					cheerBadge_GreatHost.enabled = true;
					break;
				case PlayerCheering.CheerCategory.Creative:
					cheerBadge_Creative.enabled = true;
					break;
				}
			}
		}
		if (labelTexture == null)
		{
			labelTexture = CanvasUtilities.ConvertToTexture(labelCanvas);
			labelMesh.material.mainTexture = labelTexture;
		}
		else
		{
			CanvasUtilities.ConvertToTexture(labelCanvas, labelTexture);
		}
		labelCanvas.enabled = false;
		labelMesh.gameObject.SetActive(value: true);
		labelCanvas.gameObject.SetActive(activeSelf);
	}

	private void StartStopGestureFeedback(PlayerHand thisHand)
	{
		StopStopGestureFeedback();
		stopGestureLoopingFeedbackCoroutine = StartCoroutine(StopGestureFeedbackCoroutine(thisHand));
	}

	private void StopStopGestureFeedback()
	{
		if (runningStopGestureAudio != null)
		{
			runningStopGestureAudio.Stop();
			runningStopGestureAudio = null;
		}
		if (stopGestureParticles != null)
		{
			UnityEngine.Object.Destroy(stopGestureParticles.gameObject);
		}
		if (stopGestureLoopingFeedbackCoroutine != null)
		{
			StopCoroutine(stopGestureLoopingFeedbackCoroutine);
		}
	}

	private IEnumerator StopGestureFeedbackCoroutine(PlayerHand thisHand)
	{
		runningStopGestureAudio = thisPlayer.PlayerAudio.OnStopGestureCharging(thisHand.transform.position);
		stopGestureParticles = UnityEngine.Object.Instantiate(stopGestureChargeParticles);
		stopGestureParticles.Play();
		float timer = 0f;
		ParticleSystem.MainModule main = stopGestureChargeParticles.main;
		while (timer < main.duration && stopGestureParticles != null)
		{
			stopGestureParticles.transform.position = thisHand.transform.position;
			timer += UnityEngine.Time.deltaTime;
			yield return null;
		}
		if (stopGestureParticles != null)
		{
			UnityEngine.Object.Destroy(stopGestureParticles.gameObject);
		}
		stopGestureParticles = null;
	}

	private void StartCheerGestureFeedback(PlayerHand thisHand)
	{
		StopCheerGestureFeedback();
		stopGestureLoopingFeedbackCoroutine = StartCoroutine(CheerGestureFeedbackCoroutine(thisHand));
	}

	private void StopCheerGestureFeedback()
	{
		if (runningCheerGestureAudio != null)
		{
			runningCheerGestureAudio.Stop();
			runningCheerGestureAudio = null;
		}
		if (cheerGestureParticles != null)
		{
			UnityEngine.Object.Destroy(cheerGestureParticles.gameObject);
		}
		if (cheerGestureLoopingFeedbackCoroutine != null)
		{
			StopCoroutine(cheerGestureLoopingFeedbackCoroutine);
		}
	}

	private IEnumerator CheerGestureFeedbackCoroutine(PlayerHand thisHand)
	{
		runningCheerGestureAudio = thisPlayer.PlayerAudio.OnCheerGestureCharging(thisHand.transform.position);
		cheerGestureParticles = UnityEngine.Object.Instantiate(cheerGestureChargeParticles);
		cheerGestureParticles.Play();
		float timer = 0f;
		ParticleSystem.MainModule main = cheerGestureChargeParticles.main;
		while (timer < main.duration && cheerGestureParticles != null)
		{
			cheerGestureParticles.transform.position = thisHand.transform.position;
			timer += UnityEngine.Time.deltaTime;
			yield return null;
		}
		if (cheerGestureParticles != null)
		{
			UnityEngine.Object.Destroy(cheerGestureParticles.gameObject);
		}
		cheerGestureParticles = null;
	}

	private void StartHandshakeFeedback(PlayerHand thisHand, PlayerHand otherHand, float duration)
	{
		StopHandshakeFeedback();
		handshakeLoopingFeedbackCoroutine = StartCoroutine(HandshakeFeedbackCoroutine(thisHand, otherHand, duration));
	}

	private void StopHandshakeFeedback()
	{
		if (runningHandshakeAudio != null)
		{
			runningHandshakeAudio.Stop();
			runningHandshakeAudio = null;
		}
		if (runningHandshakeParticles != null)
		{
			runningHandshakeParticles.Stop();
			runningHandshakeParticles = null;
		}
		if (handshakeLoopingFeedbackCoroutine != null)
		{
			StopCoroutine(handshakeLoopingFeedbackCoroutine);
		}
	}

	private IEnumerator HandshakeFeedbackCoroutine(PlayerHand thisHand, PlayerHand otherHand, float duration)
	{
		runningHandshakeAudio = AudioManager.Play3DSFX(handshakeChargeAudio, (!(otherHand == null)) ? Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f) : thisHand.transform.position);
		runningHandshakeParticles = ObjectPool.Instance.Acquire(handshakeChargeParticles);
		if (runningHandshakeParticles != null)
		{
			runningHandshakeParticles.SetDuration(duration, setStartLifetime: true);
			runningHandshakeParticles.Play();
		}
		float timer = 0f;
		while (timer < duration)
		{
			runningHandshakeParticles.transform.position = ((!(otherHand == null)) ? Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f) : thisHand.transform.position);
			timer += UnityEngine.Time.deltaTime;
			yield return null;
		}
		if (runningHandshakeParticles != null)
		{
			runningHandshakeParticles.Stop();
			runningHandshakeParticles = null;
		}
	}

	private void PlayHandshakeSuccessParticles(PlayerHand thisHand, PlayerHand otherHand)
	{
		Vector3 vector = ((!(otherHand == null)) ? Vector3.Lerp(thisHand.transform.position, otherHand.transform.position, 0.5f) : thisHand.transform.position);
		AudioManager.Play3DSFX(handshakeSuccessAudio, vector);
		if (handshakeSuccessParticles != null)
		{
			ParticleSystem particleSystem = UnityEngine.Object.Instantiate(handshakeSuccessParticles);
			particleSystem.transform.position = vector;
			particleSystem.Play();
			ParticleSystem.MainModule main = particleSystem.main;
			UnityEngine.Object.Destroy(particleSystem.gameObject, main.duration);
		}
		if (otherHand == null)
		{
			WorldSpaceNotification.PlayNext("Friend Added", 2f, null, followPlayer: false, vector + 0.1f * Vector3.up, 0.3f);
		}
	}
}
