		public bool IsWalkEnabled
		{
			get
			{
				if (thisPlayer.PlayerLocomotion.MovementRestricted)
				{
					return false;
				}
				return !walkDisabledFlag.HasTokens;
			}
		}

		public bool IsSprintEnabled => sprintEnabledMap.HighestPriorityValue;

		public bool CanJump
		{
			get
			{
				if (!jumpEnabledMap.HighestPriorityValue)
				{
					return false;
				}
				if (thisPlayer.PlayerLocomotion.MovementRestricted)
				{
					return false;
				}
				if (!thisPlayer.PlayerLocomotion.CanJump)
				{
					return false;
				}
				if (IsJumping)
				{
					return false;
				}
				return true;
			}
		}

		public bool IsJumping => thisPlayer.PlayerLocomotion.IsJumping;

		public bool CanDodge
		{
			get
			{
				if (!dodgeEnabledMap.HighestPriorityValue)
				{
					return false;
				}
				if (thisPlayer.PlayerLocomotion.MovementRestricted)
				{
					return false;
				}
				if (!thisPlayer.PlayerLocomotion.IsGrounded)
				{
					return false;
				}
				if (IsDodging)
				{
					return false;
				}
				return true;
