		public void ClearWalkVelocityImmediate()
		{
			if (thisPlayer.isLocal)
			{
				StopSprint();
				Velocity = Vector3.zero;
				normalizedSpeed = 0f;
				lastGroundedVelocity *= 0f;
			}
		}

		public void UpdateWalkVelocity(Vector3 normalizedDesiredDirection, float normalizedDesiredSpeed)
		{
			if (!thisPlayer.isLocal)
			{
				return;
			}
			if (!IsWalkEnabled)
			{
				ClearWalkVelocityImmediate();
			}
			else if (!IsDodging && !IsCrouchSliding)
			{
				UpdateSprintOnVelocityChange(normalizedDesiredDirection, normalizedDesiredSpeed, CoordinateSpaceForward);
				Velocity = CalculateWalkVelocityHelper(normalizedDesiredDirection, normalizedDesiredSpeed, CoordinateSpaceForward);
				if (IsSprinting && (!IsSprintAllowed(normalizedDesiredDirection, CoordinateSpaceForward) || normalizedDesiredSpeed < 0.5f))
				{
					StopSprint();
				}
				if (thisPlayer.PlayerLocomotion.IsGrounded)
				{
					normalizedSpeed = Mathf.Clamp01(Velocity.magnitude / defaultWalkSpeed);
					IsWalking = normalizedSpeed >= minWalkFeedbackSpeed;
				}
				else
				{
					normalizedSpeed = 0f;
					IsWalking = true;
				}
			}
		}

		public void RequestSprint()
		{
			if (IsSprintEnabled && !IsSprinting && IsSprintAllowed(Velocity, CoordinateSpaceForward))
			{
				sprintRequested = true;
			}
		}

		public void StopSprint()
		{
			sprintRequested = false;
			if (IsSprinting)
			{
				IsSprinting = false;
			}
		}

		public void StartCrouch()
		{
			IsCrouching = true;
			if (IsSprinting)
			{
				StopSprint();
			}
		}

		public void StopCrouch()
		{
			IsCrouching = false;
		}

		public void StartCrouchSlide()
		{
			StartCrouch();
			TryStartCrouchSlide();
		}

		public void RequestJump()
		{
			if (CanJump)
			{
				thisPlayer.PlayerLocomotion.RequestJump(maxJumpHeight);
			}
		}

		public void RequestDodge(DodgeDirectionType direction)
		{
			if (CanDodge)
			{
				IsDodging = true;
				CurrentDodgeDirection = direction;
				currentDodgeDirectionVector = GetDodgeDirectionVector(direction);
				currentDodgeStartTime = UnityEngine.Time.time;
				DodgeSettings dodgeSettings = GetDodgeSettings(CurrentDodgeDirection);
				thisPlayer.PlayerLocomotion.RequestJump(dodgeSettings.JumpHeight);
			}
		}

		public void CutoffJump()
		{
			if (IsWalkEnabled && !IsCrouching && !thisPlayer.PlayerLocomotion.IsGrounded)
			{
				thisPlayer.PlayerLocomotion.CutoffJump(minJumpHeight);
			}
		}

		protected override void Awake()
		{
			if (thisPlayer.isLocal)
			{
				AddSprintEnabled(enabled: true, this, int.MinValue);
				AddJumpEnabled(enabled: true, this, int.MinValue);
				AddDodgeEnabled(enabled: false, this, int.MinValue);
				AddMaxWalkSpeed(defaultWalkSpeed, this, int.MinValue);
				AddWalkAcceleration(walkAcceleration, this, int.MinValue);
				AddWalkDeceleration(walkDeceleration, this, int.MinValue);
				AddMaxSprintSpeedMultiplier(defaultSprintSpeedMultiplier, this, int.MinValue);
				AddMaxWalkSpeedMultiplier(1f, this);
				AddWalkAccelerationMultiplier(1f, this);
				AddWalkDecelerationMultiplier(1f, this);
				Tool.LocalPlayerCollisionEvent += OnLocalPlayerToolCollision;
				RangedWeapon.LocalPlayerStaticFireEvent += OnLocalPlayerFireRangedWeapon;
			}
		}

		private void Start()
		{
			OnWalkEnabledDisabledChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (thisPlayer != null && thisPlayer.isLocal)
			{
				thisPlayer.PlayerLocomotion.ResumeGravity(this);
				Tool.LocalPlayerCollisionEvent -= OnLocalPlayerToolCollision;
				RangedWeapon.LocalPlayerStaticFireEvent -= OnLocalPlayerFireRangedWeapon;
				if (SingletonMonoBehaviour<CameraRig>.Instance != null)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopWalkingVignette(0f);
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSprintingVignette(0f);
				}
			}
		}

		private void Update()
		{
			if (isLocal)
			{
				UpdateDodge();
				UpdateCrouchSlide();
				thisPlayer.PlayerLocomotion.Move(Velocity);
				UpdateLocalVignetting();
				UpdateLocalFootstepAudio();
				UpdateLocalHeartbeatAudio();
			}
			else
			{
				UpdateRemoteFootstepAudio();
			}
		}

		private void OnWalkEnabledDisabledChange()
		{
			if (!IsWalkEnabled)
			{
				ClearWalkVelocityImmediate();
			}
		}

		private void OnWalkStart()
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartWalkingVignette(0f);
		}

		private void OnWalkEnd()
		{
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopWalkingVignette(0.2f);
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSprintingVignette(0.1f);
		}

		private void OnSprintStart()
		{
			sprintStartTime = UnityEngine.Time.time;
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartSprintingVignette(0.2f);
		}

		private void OnSprintEnd()
		{
			sprintEndTime = UnityEngine.Time.time;
			SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopSprintingVignette(0.1f);
		}

		private Vector3 CalculateWalkVelocityHelper(Vector3 desiredDirection, float desiredNormalizedSpeed, Vector3 sprintForward)
		{
			float magnitude = Velocity.magnitude;
			Vector3 zero = Vector3.zero;
			float num = 0f;
			if (IsSprinting)
			{
				Vector3 vector = Vector3.Project(desiredDirection, sprintForward);
				Vector3 vector2 = desiredDirection - vector;
				vector = vector.normalized;
				float magnitude2 = vector2.magnitude;
				if (magnitude2 >= Mathf.Epsilon)
				{
					vector2 /= magnitude2;
					vector2 *= Mathf.Lerp(0f, maxLateralSprintScaler, magnitude2);
				}
				Vector3 normalized = (vector + vector2).normalized;
				float num2 = maxSprintSpeedMultiplierMap.HighestPriorityValue * maxWalkSpeedMap.HighestPriorityValue;
				zero = normalized * num2;
				num = sprintAcceleration;
			}
			else
			{
				float num3 = desiredNormalizedSpeed * maxWalkSpeedMap.HighestPriorityValue * maxWalkSpeedMultiplierMap.LatestValue;
				if (IsCrouching)
				{
					num3 *= defaultCrouchSpeedMultiplier;
				}
				zero = desiredDirection * num3;
				bool flag = num3 <= magnitude * 0.5f;
				float num4 = walkAccelerationMap.HighestPriorityValue * walkAccelerationMultiplierMap.LatestValue;
				float num5 = walkDecelerationMap.HighestPriorityValue * walkDecelerationMultiplierMap.LatestValue;
				num = ((!flag) ? num4 : num5);
			}
			if (!thisPlayer.PlayerLocomotion.IsGrounded)
			{
				num *= airControlPercentage;
			}
			return Vector3.MoveTowards(Velocity, zero, num * UnityEngine.Time.deltaTime);
		}

		private DodgeSettings GetDodgeSettings(DodgeDirectionType direction)
		{
			return direction switch
			{
				DodgeDirectionType.LEFT => leftDodgeSettings, 
				DodgeDirectionType.RIGHT => rightDodgeSettings, 
				DodgeDirectionType.BACK => backDodgeSettings, 
				_ => forwardDodgeSettings, 
			};
		}

		private Vector3 GetDodgeDirectionVector(DodgeDirectionType direction)
		{
			switch (direction)
			{
			case DodgeDirectionType.FORWARD:
				return CoordinateSpaceForward;
			case DodgeDirectionType.BACK:
				return -1f * CoordinateSpaceForward;
			default:
			{
				Vector3 normalized = Vector3.Cross(Vector3.up, CoordinateSpaceForward).normalized;
				return direction switch
				{
					DodgeDirectionType.RIGHT => normalized, 
					DodgeDirectionType.LEFT => -1f * normalized, 
					_ => Vector3.zero, 
				};
			}
			}
		}

		private void UpdateDodge()
		{
			if (!IsDodging)
			{
				return;
			}
			DodgeSettings dodgeSettings = GetDodgeSettings(CurrentDodgeDirection);
			if (dodgeSettings == null)
			{
				IsDodging = false;
				return;
			}
			float num = UnityEngine.Time.time - currentDodgeStartTime;
			if (num >= dodgeSettings.Duration)
			{
				IsDodging = false;
				return;
			}
			float num2 = dodgeSettings.SpeedCurve.Evaluate(num) * dodgeSettings.MaxSpeed;
			Velocity = num2 * currentDodgeDirectionVector;
		}

		private void UpdateLocalVignetting()
		{
			if (thisPlayer.PlayerLocomotion.IsGrounded)
			{
				float walkingVignetteIntensityInterpolation = ((!IsSprinting) ? normalizedSpeed : 1f);
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.SetWalkingVignetteIntensityInterpolation(walkingVignetteIntensityInterpolation);
			}
		}

		private void UpdateSprintOnVelocityChange(Vector3 desiredVelocityDirection, float desiredNormalizedSpeed, Vector3 cameraForward)
		{
			bool flag = desiredNormalizedSpeed >= 0.5f;
			bool flag2 = IsSprintAllowed(desiredVelocityDirection, cameraForward);
			if (!IsSprinting)
			{
				if (sprintRequested && flag2 && flag)
				{
					IsSprinting = true;
					IsCrouching = false;
				}
			}
			else if (!flag2 || !flag)
			{
				StopSprint();
			}
			sprintRequested = false;
		}

		private bool IsSprintAllowed(Vector3 desiredVelocityDirection, Vector3 cameraForward)
		{
			if (!IsSprintEnabled)
			{
				return false;
			}
			if (Velocity.sqrMagnitude > 0.001f)
			{
				float sprintCameraAngle = GetSprintCameraAngle(desiredVelocityDirection, cameraForward);
				return sprintCameraAngle < maxSprintAngleFromCamera;
			}
			return true;
		}

		private float GetSprintCameraAngle(Vector3 desiredVelocityDirection, Vector3 cameraForward)
		{
			if (Mathf.Abs(Vector3.Dot(desiredVelocityDirection, Vector3.up)) >= 0.9999999f)
			{
				return 90f;
			}
			Vector3 normalized = Vector3.ProjectOnPlane(desiredVelocityDirection, Vector3.up).normalized;
			return Mathf.Abs(Vector3.Angle(cameraForward, normalized));
		}

		private void UpdateCrouchSlide()
		{
			if (IsCrouchSliding)
			{
				float num = Mathf.InverseLerp(crouchSlideStartTime, crouchSlideStartTime + crouchSlideDuration, UnityEngine.Time.time);
				if (num >= 1f)
				{
					IsCrouchSliding = false;
					return;
				}
				float t = crouchSlideSpeedCurve.Evaluate(num);
				float b = maxWalkSpeedMap.HighestPriorityValue * maxWalkSpeedMultiplierMap.LatestValue * defaultCrouchSpeedMultiplier;
				float num2 = Mathf.Lerp(crouchSlideStartSpeed, b, t);
				Velocity = crouchSlideDirection * num2;
			}
		}

		private void TryStartCrouchSlide()
		{
			float magnitude = Velocity.magnitude;
			if (magnitude <= Mathf.Epsilon)
			{
				IsCrouchSliding = false;
				return;
			}
			IsCrouchSliding = true;
			crouchSlideStartTime = UnityEngine.Time.time;
			crouchSlideStartSpeed = magnitude;
			crouchSlideDirection = Velocity / magnitude;
		}

		private bool IsCloseEnoughToLocalPlayerForAudio()
		{
			if (!Player.LocalPlayerExists)
			{
				return false;
			}
			float sqrMagnitude = (thisPlayer.Head.transform.position - Player.LocalPlayer.Head.transform.position).sqrMagnitude;
			return sqrMagnitude < maxDistanceForRemotePlayerFootstepAudio * maxDistanceForRemotePlayerFootstepAudio;
		}

		private void UpdateRemoteFootstepAudio()
		{
			if (normalizedSpeed < 0.001f || !IsCloseEnoughToLocalPlayerForAudio())
			{
				return;
			}
			bool flag = normalizedSpeed > 1f;
			float num = footstepAudioFrequencyCurve.Evaluate(normalizedSpeed);
			if (flag)
			{
				num *= sprintFootstepAudioFrequencyScalar;
			}
			if (num <= 0.001f)
			{
				return;
			}
			float num2 = 1f / num;
			if (UnityEngine.Time.time - lastFootstepAudioPlayTime >= num2)
			{
				float num3 = remotePlayerFootstepAudioVolumeCurve.Evaluate(normalizedSpeed);
				if (flag)
				{
					num3 *= sprintFootstepAudioVolumeScalar;
				}
				thisPlayer.PlayerAudio.PlayRemoteFootstepAudio(num3);
				lastFootstepAudioPlayTime = UnityEngine.Time.time;
			}
		}

		private void UpdateLocalFootstepAudio()
		{
			if (normalizedSpeed < 0.001f)
			{
				return;
			}
			float num = footstepAudioFrequencyCurve.Evaluate(normalizedSpeed);
			if (IsSprinting)
			{
				num *= sprintFootstepAudioFrequencyScalar;
			}
			if (num <= 0.001f)
			{
				return;
			}
			float num2 = 1f / num;
			if (UnityEngine.Time.time - lastFootstepAudioPlayTime >= num2)
			{
				float num3 = localPlayerFootstepAudioVolumeCurve.Evaluate(normalizedSpeed);
				if (IsSprinting)
				{
					num3 *= sprintFootstepAudioVolumeScalar;
				}
				thisPlayer.PlayerAudio.PlayLocalFootstepAudio(num3);
				lastFootstepAudioPlayTime = UnityEngine.Time.time;
			}
		}

		private void UpdateLocalHeartbeatAudio()
		{
			bool flag = IsSprinting && UnityEngine.Time.time - sprintStartTime >= heartbeatAudioStartDelay;
			bool flag2 = !IsSprinting && sprintEndTime - sprintStartTime >= heartbeatAudioStartDelay && UnityEngine.Time.time - sprintEndTime <= heartbeatWindDownDuration;
			if (!flag && !flag2)
			{
				return;
			}
			float value = ((!IsSprinting) ? sprintEndTime : UnityEngine.Time.time);
			float time = Mathf.InverseLerp(sprintStartTime + heartbeatAudioStartDelay, sprintStartTime + heartbeatAudioStartDelay + heartbeatAudioCurveDuration, value);
			float num = heartbeatAudioPeriodCurve.Evaluate(time);
			if (UnityEngine.Time.time - lastHeartbeatAudioPlayTime >= num)
			{
				float spacing = heartbeatAudioBeatSpacingCurve.Evaluate(time);
				float num2 = heartbeatAudioVolumeCurve.Evaluate(time);
				if (flag2)
				{
					float t = Mathf.InverseLerp(sprintEndTime, sprintEndTime + heartbeatWindDownDuration, UnityEngine.Time.time);
					num2 = Mathf.Lerp(num2, 0f, t);
				}
				StartCoroutine(PlayHeartbeatAudioCoroutine(spacing, num2));
				lastHeartbeatAudioPlayTime = UnityEngine.Time.time;
			}
		}

		private IEnumerator PlayHeartbeatAudioCoroutine(float spacing, float volume)
		{
			thisPlayer.PlayerAudio.PlaySprintHeartbeatDownAudio(volume);
			yield return new WaitForSeconds(spacing);
			thisPlayer.PlayerAudio.PlaySprintHeartbeatUpAudio(volume);
		}

		private void OnLocalPlayerToolCollision(Tool hitTool, Collision collision)
		{
			if (!hitTool.IsHeld && hitTool.SupportsPlayerLocomotionAttacks && collision.contacts.Length > 0 && !(Velocity.sqrMagnitude <= 0.01f))
			{
				float magnitude = Velocity.magnitude;
				Vector3 direction = Velocity / magnitude;
				float normalizedForce = Mathf.Clamp01(magnitude / maxWalkSpeedMap.HighestPriorityValue);
				hitTool.ApplyPlayerLocomotionAttack(collision.contacts[0].point, direction, normalizedForce);
			}
		}

		private void OnLocalPlayerFireRangedWeapon(RangedWeapon weapon)
		{
			if (weapon.Tool.IsHeldByPlayer)
			{
				StopSprint();
			}
		}

		public void OnPhotonSerializeView(PhotonStream stream, PhotonMessageInfo info)
		{
			if (stream.isReading)
			{
				normalizedSpeed = (float)stream.ReceiveNext();
			}
			else
			{
				stream.SendNext(normalizedSpeed);
			}
		}
	}
}
namespace RecRoom.Players.Puppet
{
	public struct PuppetTransform
	{
		public Vector3 localPosition;

		public Quaternion localRotation;
	}
	public struct PuppetHandState
	{
