	public class LivePlayerPuppet : PlayerPuppet
	{
		protected LivePlayerPuppetSource source = new LivePlayerPuppetSource();

		protected override IPlayerPuppetSource Source => source;

		public override Player TargetPlayer
		{
			get
			{
				return source.TargetPlayer;
			}
			set
			{
				ClearOutfits();
				if (TargetPlayer != null)
				{
					CleanupPreviousPlayer();
				}
				source.TargetPlayer = value;
				if (TargetPlayer != null)
				{
					SetupNewPlayer();
				}
				OnTargetPlayerChanged(TargetPlayer);
			}
		}

		private void Start()
		{
			if (TargetPlayer == null)
			{
				OnTargetPlayerChanged(TargetPlayer);
			}
		}

		protected override void SetupNewPlayer()
		{
			base.SetupNewPlayer();
			TargetPlayer.OnDestroyEvent += TargetPlayer_OnDestroyEvent;
		}

		protected override void CleanupPreviousPlayer()
		{
			base.CleanupPreviousPlayer();
			TargetPlayer.OnDestroyEvent -= TargetPlayer_OnDestroyEvent;
		}

		protected virtual void OnTargetPlayerChanged(Player targetPlayer)
		{
			source.TargetPlayer = TargetPlayer;
			Refresh();
		}

		private void TargetPlayer_OnDestroyEvent()
		{
			if (this != null)
			{
				TargetPlayer = null;
			}
		}
	}
	public class LivePlayerPuppetSource : IPlayerPuppetSource
	{
		private Player _targetPlayer;

		public Transform SourceRootTransform;

		public Player TargetPlayer
		{
			get
			{
				return _targetPlayer;
			}
			set
			{
				if (_targetPlayer != value)
				{
					_targetPlayer = value;
				}
			}
		}

		public bool ShouldDisplay => _targetPlayer != null && !_targetPlayer.DisplayAsIgnored;

		public Color SkinColor => _targetPlayer.PlayerOutfit.SkinColor.color;

		public Color HairColor => _targetPlayer.PlayerOutfit.HairColor.color;

		public IList<OutfitSelectionToBody> OutfitSelections => _targetPlayer.PlayerOutfit.OutfitSelections;

		public AvatarFaceSettings FaceFeatures => _targetPlayer.PlayerOutfit.FaceFeatures;

		public float AudioVolume => _targetPlayer.AudioMaxForFrame;

		public PuppetTransform Head => SourceToDestination(_targetPlayer.Head.transform);

		public PuppetTransform Body => SourceToDestination(_targetPlayer.Body.transform);

		public PuppetHandState LeftHand => PlayerToPuppetHand(_targetPlayer.LeftHand);

		public PuppetHandState RightHand => PlayerToPuppetHand(_targetPlayer.RightHand);

		private PuppetTransform SourceToDestination(Transform sourceTransform)
		{
			Vector3 localPosition = SourceRootTransform.InverseTransformPoint(sourceTransform.position);
			Quaternion localRotation = SourceRootTransform.InverseTransformRotation(sourceTransform.rotation);
			return new PuppetTransform
			{
				localPosition = localPosition,
				localRotation = localRotation
			};
		}

		private PuppetHandState PlayerToPuppetHand(PlayerHand playerHand)
		{
			return new PuppetHandState
			{
				transform = SourceToDestination(playerHand.transform),
				isMenuHandVisible = playerHand.MenuHandVisualsActive,
				thumbsUpActive = playerHand.ThumbsUpAnimationEnabled,
				openClosedAxis = playerHand.OpenClosedAxis
			};
		}
	}
	public class PlayerMinitar : LivePlayerPuppet
	{
		[Header("Identity")]
		[SerializeField]
		private MeshRenderer labelMesh;

		private float defaultMinitarHeadHeightOffset;

		protected override void Awake()
		{
			base.Awake();
			defaultMinitarHeadHeightOffset = head.transform.localPosition.y;
		}

		private void OnEnable()
		{
			Refresh();
		}

		private void Profiles_OnProfileUpdated(long id)
		{
			if (this != null && base.enabled && TargetPlayer != null && TargetPlayer.PlayerId == id)
			{
				Refresh();
			}
		}

		private void PlayerOutfit_SkinColorChanged(Color obj)
		{
			UpdatePlayerSkinColor();
		}

		private void PlayerOutfit_FaceFeaturesChanged(AvatarFaceSettings settings)
		{
			UpdatePlayerFaceFeatures();
		}

		protected override void SetupNewPlayer()
		{
			source.SourceRootTransform = TargetPlayer.Body.transform;
			base.SetupNewPlayer();
			TargetPlayer.PlayerOutfit.OutfitSelectionChanged += base.UpdatePlayerOutfit;
			TargetPlayer.PlayerOutfit.SkinColorChanged += PlayerOutfit_SkinColorChanged;
			TargetPlayer.PlayerOutfit.FaceFeaturesChanged += PlayerOutfit_FaceFeaturesChanged;
			Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			Refresh();
		}

		protected override void CleanupPreviousPlayer()
		{
			base.CleanupPreviousPlayer();
			if (TargetPlayer != null)
			{
				TargetPlayer.PlayerOutfit.OutfitSelectionChanged -= base.UpdatePlayerOutfit;
				TargetPlayer.PlayerOutfit.SkinColorChanged -= PlayerOutfit_SkinColorChanged;
				TargetPlayer.PlayerOutfit.FaceFeaturesChanged -= PlayerOutfit_FaceFeaturesChanged;
			}
			Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
