		protected override void UpdatePoses()
		{
			base.UpdatePoses();
			Vector3 localPosition = visualRoot.localPosition;
			localPosition.y = defaultMinitarHeadHeightOffset - head.localPosition.y;
			visualRoot.localPosition = localPosition;
			if (TargetPlayer != null)
			{
				base.Head.transform.localScale = TargetPlayer.Head.transform.localScale;
			}
		}
	}
	public abstract class PlayerPuppet : UnityEngine.MonoBehaviour
	{
		[Header("Root")]
		[SerializeField]
		protected Transform visualRoot;

		[Header("Limbs")]
		[SerializeField]
		protected Transform head;

		[SerializeField]
		protected Transform body;

		[SerializeField]
		protected PlayerPuppetHand leftHand;

		[SerializeField]
		protected PlayerPuppetHand rightHand;

		[SerializeField]
		protected PlayerFacialAnimator facialAnimator;

		[Header("Clothing Anchors")]
		[SerializeField]
		protected Transform headPropRoot;

		[SerializeField]
		protected Transform torsoPropRoot;

		[SerializeField]
		protected Renderer[] renderersRequiringSkinColor;

		private List<OutfitItem> outfits = new List<OutfitItem>();

		private OutfitItem.OutfitBodyMapping outfitBodyMapping;

		public Transform Head => head;

		public Transform Body => body;

		public PlayerPuppetHand LeftHand => leftHand;

		public PlayerPuppetHand RightHand => rightHand;

		public PlayerFacialAnimator FacialAnimator => facialAnimator;

		protected virtual bool VisualsActive => Source.ShouldDisplay && visualRoot.gameObject.activeSelf;

		protected abstract IPlayerPuppetSource Source { get; }

		public virtual Player TargetPlayer
		{
			get
			{
				return null;
			}
			set
			{
				throw new InvalidOperationException();
			}
		}

		protected virtual void Awake()
		{
			EnsureOutfitMapping();
		}

		protected virtual void LateUpdate()
		{
			if (VisualsActive)
			{
				UpdatePoses();
			}
		}

		protected virtual void SetupNewPlayer()
		{
			UpdatePlayerOutfit();
			UpdatePlayerSkinColor();
			UpdatePlayerFaceFeatures();
		}

		protected virtual void CleanupPreviousPlayer()
		{
			ClearOutfits();
		}

		public virtual void Refresh()
		{
			bool shouldDisplay = Source.ShouldDisplay;
			visualRoot.gameObject.SetActive(shouldDisplay);
			if (VisualsActive)
			{
				ProcessHandState(PlayerHand.HandType.Left, Source.LeftHand, forceUpdate: true);
				ProcessHandState(PlayerHand.HandType.Right, Source.RightHand, forceUpdate: true);
			}
		}

		protected virtual void UpdatePoses()
		{
			ProcessHandState(PlayerHand.HandType.Left, Source.LeftHand);
			ProcessHandState(PlayerHand.HandType.Right, Source.RightHand);
			ProcessTransform(Source.Head, head);
			ProcessTransform(Source.Body, body);
		}

		private void ProcessHandState(PlayerHand.HandType type, PuppetHandState data, bool forceUpdate = false)
		{
			bool flag = type == PlayerHand.HandType.Left;
			PlayerPuppetHand playerPuppetHand = ((!flag) ? rightHand : leftHand);
			bool isPointingMeshVisible = playerPuppetHand.IsPointingMeshVisible;
			bool isMenuHandVisible = data.isMenuHandVisible;
			if (isPointingMeshVisible != isMenuHandVisible || forceUpdate)
			{
				Player.BodyPart bodyPart = ((!flag) ? Player.BodyPart.RightHand : Player.BodyPart.LeftHand);
				foreach (OutfitItem outfit in outfits)
				{
					if (outfit.CurrentBodyPart == bodyPart)
					{
						outfit.SetVisible(!isMenuHandVisible, this);
					}
				}
			}
			playerPuppetHand.IsPointingMeshVisible = isMenuHandVisible;
			playerPuppetHand.IsThumbsUpActive = data.thumbsUpActive;
			playerPuppetHand.OpenCloseAxis = data.openClosedAxis;
			ProcessTransform(data.transform, playerPuppetHand.transform);
		}

		private void ProcessTransform(PuppetTransform data, Transform destinationTransform)
		{
			destinationTransform.localPosition = data.localPosition;
			destinationTransform.localRotation = data.localRotation;
		}

		protected void UpdatePlayerOutfit()
		{
			EnsureOutfitMapping();
			ClearOutfits();
			foreach (OutfitSelectionToBody outfitSelection in Source.OutfitSelections)
			{
				EquipOutfitSelection(outfitSelection.selection, outfitSelection.bodyPart);
			}
			UpdatePlayerHairColor();
			Refresh();
		}

		protected void UpdatePlayerSkinColor()
		{
			Color skinColor = Source.SkinColor;
			Renderer[] array = renderersRequiringSkinColor;
			foreach (Renderer renderer in array)
			{
				renderer.material.color = skinColor;
			}
		}

		protected void UpdatePlayerHairColor()
		{
			foreach (OutfitItem outfit in outfits)
			{
				outfit.SetHairColor(Source.HairColor);
			}
		}

		protected void UpdatePlayerFaceFeatures()
		{
			if (FacialAnimator != null && Source.FaceFeatures != null)
			{
				FacialAnimator.SetFaceSettings(Source.FaceFeatures);
			}
		}

		protected void ClearOutfits()
		{
			if (outfits == null || outfits.Count <= 0)
			{
				return;
			}
			for (int i = 0; i < outfits.Count; i++)
			{
				OnOutfitItemRemoved(outfits[i]);
				if (outfits[i] != null)
				{
					UnityEngine.Object.Destroy(outfits[i].gameObject);
				}
			}
			outfits.Clear();
		}

		protected virtual void OnOutfitItemRemoved(OutfitItem item)
		{
		}

		public virtual OutfitItem EquipOutfitSelection(OutfitSelection selection, Player.BodyPart bodyPart)
		{
			if (OutfitManager.IsTeamOutfit(selection.outfitItem.Type))
			{
				return null;
			}
			OutfitSelection prefab = selection.GetPrefab();
			if (prefab == null)
			{
				return null;
			}
			OutfitItem outfitItem = PlayerOutfit.InstantiateNewOutfitPrefab(prefab, bodyPart, TargetPlayer, belongsToPuppet: true);
			outfitItem.BindToBody(outfitBodyMapping);
			outfitItem.transform.SetParent(visualRoot);
			outfitItem.transform.localPosition = Vector3.zero;
			outfitItem.gameObject.SetLayerRecursively((Layers)visualRoot.gameObject.layer);
			OnOutfitItemAdded(outfitItem);
			outfits.Add(outfitItem);
			return outfitItem;
		}

		protected virtual void OnOutfitItemAdded(OutfitItem item)
		{
		}

		private void EnsureOutfitMapping()
		{
			if (outfitBodyMapping == null)
			{
				outfitBodyMapping = new OutfitItem.OutfitBodyMapping
				{
					head = headPropRoot,
					torso = torsoPropRoot,
					leftHand = new OutfitItem.OutfitAnimatedBodyMapping
					{
						renderer = leftHand.BaseMesh,
						animator = leftHand.Animator
					},
					rightHand = new OutfitItem.OutfitAnimatedBodyMapping
					{
						renderer = rightHand.BaseMesh,
						animator = rightHand.Animator
					}
				};
			}
		}
	}
	public class PlayerPuppetHand : UnityEngine.MonoBehaviour
	{
		private static readonly int OPEN_CLOSED_ANIMATOR_ID = Animator.StringToHash("OpenClosed");

		private static readonly int THUMBSUP_ANIMATOR_ID = Animator.StringToHash("ThumbsUp");

		[SerializeField]
		private Animator animator;

		[SerializeField]
		private SkinnedMeshRenderer baseMesh;

		[SerializeField]
		private Renderer pointingMesh;

		private bool _isPointingMeshVisible;

		private bool _isThumbsUpActive;

		private float _openCloseAxis;

		public Animator Animator => animator;

		public SkinnedMeshRenderer BaseMesh => baseMesh;

		public Renderer PointingMesh => pointingMesh;

		public bool IsPointingMeshVisible
		{
			get
			{
				return _isPointingMeshVisible;
			}
			set
			{
				if (_isPointingMeshVisible != value)
				{
					baseMesh.gameObject.SetActive(!value);
					pointingMesh.gameObject.SetActive(value);
					_isPointingMeshVisible = value;
				}
			}
		}

		public bool IsThumbsUpActive
		{
			get
			{
				return _isThumbsUpActive;
			}
			set
			{
				if (_isThumbsUpActive != value)
				{
					_isThumbsUpActive = value;
					animator.SetBool(THUMBSUP_ANIMATOR_ID, value);
				}
			}
		}

		public float OpenCloseAxis
		{
			get
			{
				return _openCloseAxis;
			}
			set
			{
				if (_openCloseAxis != value)
				{
					_openCloseAxis = value;
					animator.SetFloat(OPEN_CLOSED_ANIMATOR_ID, value);
				}
			}
		}

		public Color SkinColor
		{
			set
			{
				baseMesh.material.color = value;
				pointingMesh.material.color = value;
			}
		}

		private void Awake()
		{
			baseMesh.material = new Material(baseMesh.sharedMaterial);
			pointingMesh.material = new Material(pointingMesh.sharedMaterial);
		}

		private void OnDestroy()
		{
			UnityEngine.Object.Destroy(baseMesh.material);
			UnityEngine.Object.Destroy(pointingMesh.material);
		}
	}
}
namespace RecRoom
{
	public class QuickTimeEmoteController
	{
		private class QuickTimeEmoteContext
		{
			public readonly EmoteOption EmoteOption;

			public readonly float MinAvailableDuration;

			public readonly float MaxAvailableDuration;

			public float TimeElapsed;

			public QuickTimeEmoteContext(QuickTimeEmote qte)
			{
				MinAvailableDuration = 0.25f;
				MaxAvailableDuration = qte.DurationWindow;
				EmoteOption = qte.Emotes[qte.getWeightedRandomIndex()];
				TimeElapsed = 0f;
			}
		}

		[SerializeField]
		private List<QuickTimeEmote> allQuickTimeEmotes = new List<QuickTimeEmote>();

		private List<QuickTimeEmoteContext> qteContextQueue = new List<QuickTimeEmoteContext>();

		private RecRoomAudioClip onEmoteAvailableSfx;

		private QuickTimeEmoteContext activeEmote;

		private const float DEFAULT_MIN_EMOTE_AVAILABLE_DURATION = 0.25f;

		private bool TryCreateEventContext(EmoteEvent ee)
		{
			QuickTimeEmote byEvent = GetByEvent(ee);
			if (byEvent != null)
			{
				if (UnityEngine.Random.value <= byEvent.ProbabilityToDisplay)
				{
					qteContextQueue.Add(new QuickTimeEmoteContext(byEvent));
				}
				return true;
			}
			return false;
		}

		public void OnPlayerKilledPlayer(PhotonPlayer attacker, PhotonPlayer defender, Weapon weapon, Player.BodyPart defenderImpactBodyPart, Vector3 impactPoint, Vector3 impactSurfaceNormal, int damage, GameCombatManager.PlayerShieldEffect shieldEffect)
		{
			if (attacker.IsLocal)
			{
				TryCreateEventContext(EmoteEvent.Undefined);
			}
			else if (defender.IsLocal)
			{
				TryCreateEventContext(EmoteEvent.PlayerKilledByPlayer);
			}
		}

		public void PlayerKilledEnemy(PhotonPlayer attacker, Weapon attackerWeapon, Enemy defender, Vector3 impactPoint)
		{
			if (attacker.IsLocal)
			{
				TryCreateEventContext(EmoteEvent.PlayerKilledEnemy);
			}
		}

		public void TeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(changingTeamPlayer);
			if (playerTeam == GameTeam.ANY)
			{
				return;
			}
			if (changingTeamPlayer.IsLocal)
			{
				PhotonPlayer[] teammatesOfPlayer = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeammatesOfPlayer(changingTeamPlayer);
				PhotonPlayer[] array = teammatesOfPlayer;
				foreach (PhotonPlayer photonPlayer in array)
				{
					TryCreateEventContext(EmoteEvent.PlayerJoinedTeam);
				}
			}
			else if (playerTeam == NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player))
			{
				TryCreateEventContext(EmoteEvent.TeammateJoinedTeam);
			}
		}

		public void PlayerBowledBall(PhotonPlayer bowler, int points)
		{
			if (bowler.IsLocal)
			{
				switch (points)
				{
				case 0:
					TryCreateEventContext(EmoteEvent.PlayerBowledGutter);
					break;
				case 10:
					TryCreateEventContext(EmoteEvent.PlayerBowledStrikeOrSpare);
					break;
				}
			}
		}

		public void ExitCombat()
		{
			TryCreateEventContext(EmoteEvent.ExitCombat);
		}

		public void ArrivingInRoom()
		{
			TryCreateEventContext(EmoteEvent.PlayerArrivedInRoom);
		}

		public void Scored()
		{
			GameTeam playerTeam = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player);
			GameTeam[] activeTeams = NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetActiveTeams();
			for (int i = 0; i < activeTeams.Length; i++)
			{
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetScore(activeTeams[i]) > NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.GetPreviousScore(activeTeams[i]))
				{
					if (activeTeams[i] == playerTeam)
					{
						TryCreateEventContext(EmoteEvent.TeamScoredPoint);
					}
					else
					{
						TryCreateEventContext(EmoteEvent.OpponentScoredPoint);
					}
					break;
				}
			}
		}

		public void Initialize(RecRoomAudioClip onEmoteAvailableSfx)
		{
			this.onEmoteAvailableSfx = onEmoteAvailableSfx;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDownedPlayerEvent += OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledEnemyEvent += PlayerKilledEnemy;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.ExitingCombatEvent += ExitCombat;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.StatsChangeEvent += Scored;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent += TeamChange;
			}
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += ArrivingInRoom;
			}
			if (BowlingManager.Instance != null)
			{
				BowlingManager.Instance.PlayerBowledEvent += PlayerBowledBall;
			}
		}

		public void Cleanup()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledPlayerEvent += OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerDownedPlayerEvent -= OnPlayerKilledPlayer;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerKilledEnemyEvent -= PlayerKilledEnemy;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.ExitingCombatEvent -= ExitCombat;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.ScoreManager.StatsChangeEvent -= Scored;
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.TeamChangeEvent -= TeamChange;
			}
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= ArrivingInRoom;
			}
			if (BowlingManager.Instance != null)
			{
				BowlingManager.Instance.PlayerBowledEvent -= PlayerBowledBall;
			}
		}

		public void OnUpdate(ScreenPlayerController playerController, ScreenHUD hud, Vector2 viewportPosition, ScreenInputHandler inputHandler)
		{
			QuickTimeEmoteContext quickTimeEmoteContext = activeEmote;
			activeEmote = null;
			for (int num = qteContextQueue.Count - 1; num >= 0; num--)
			{
				QuickTimeEmoteContext quickTimeEmoteContext2 = qteContextQueue[num];
				quickTimeEmoteContext2.TimeElapsed += UnityEngine.Time.deltaTime;
				if (quickTimeEmoteContext2.TimeElapsed >= quickTimeEmoteContext2.MaxAvailableDuration)
				{
					qteContextQueue.RemoveAt(num);
				}
				else if (quickTimeEmoteContext2.TimeElapsed >= quickTimeEmoteContext2.MinAvailableDuration)
				{
					activeEmote = quickTimeEmoteContext2;
				}
			}
			if (activeEmote != null)
			{
				if (quickTimeEmoteContext == null)
				{
					AudioManager.Play2DSFX(onEmoteAvailableSfx);
				}
				hud.EnableEmoteDialog(viewportPosition, inputHandler.QuickCommButton1Sprite, activeEmote.EmoteOption.text);
				if (inputHandler.QuickCommButton1Down)
				{
					playerController.EmoteSystem.QueueEmote(activeEmote.EmoteOption.Emote);
					qteContextQueue.Remove(activeEmote);
					activeEmote = null;
				}
			}
			else
			{
				hud.DisableEmoteDialog();
			}
		}

		private QuickTimeEmote GetByEvent(EmoteEvent ee)
		{
			for (int num = allQuickTimeEmotes.Count - 1; num >= 0; num--)
			{
				if (allQuickTimeEmotes[num].Event == ee)
				{
					return allQuickTimeEmotes[num];
				}
			}
			return null;
		}

		public void AddEmotes(QuickTimeEmote[] emotes)
		{
			allQuickTimeEmotes.AddRange(emotes);
		}

		public void RemoveEmotes(QuickTimeEmote[] emotes)
		{
			foreach (QuickTimeEmote item in emotes)
			{
				allQuickTimeEmotes.Remove(item);
			}
		}
	}
}
namespace RecRoom.Core
{
	public enum EmoteEvent
	{
		Undefined = 0,
		PlayerKilledPlayer = 0,
		PlayerKilledByPlayer = 1,
		PlayerKilledEnemy = 2,
		TeamScoredPoint = 4,
		OpponentScoredPoint = 5,
		PlayerArrivedInRoom = 7,
		PlayerJoinedTeam = 8,
		TeammateJoinedTeam = 9,
		ExitCombat = 10,
		PlayerBowledGutter = 20,
		PlayerBowledStrikeOrSpare = 22
	}
	[Serializable]
	public class EmoteOption
	{
		public string text;

		public ScreenPlayerEmote Emote;

		[Range(0.01f, 1f)]
		public float relativeProbability = 1f;
	}
	[Serializable]
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Quick Time Emote", fileName = "New Quick Time Emote")]
	public class QuickTimeEmote : ScriptableObject
	{
		[Header("Emotes")]
		public EmoteOption[] Emotes;

		[Header("Settings")]
		[Range(0f, 1f)]
		public float ProbabilityToDisplay = 1f;

		public float DurationWindow = 5f;

		public EmoteEvent Event;

		public int getWeightedRandomIndex()
		{
			float num = 0f;
			for (int i = 0; i < Emotes.Length; i++)
			{
				num += Emotes[i].relativeProbability;
			}
			float num2 = UnityEngine.Random.Range(0f, num);
			num = 0f;
			for (int j = 0; j < Emotes.Length; j++)
			{
				num += Emotes[j].relativeProbability;
				if (num2 <= num)
				{
					return j;
				}
			}
			return 0;
		}
	}
}
namespace RecRoom.Core.Screens.PlayerController
{
	public abstract class ScreenContextSensitiveActionController : ScriptableObject
	{
		[Header("Settings")]
