		[NonSerialized]
		private bool attemptingToExit;

		[NonSerialized]
		private float exitAttemptStartTime;

		[NonSerialized]
		private bool hasSetCameraCullMask;

		[NonSerialized]
		private int defaultCameraCullingMask = -1;

		public virtual bool UnlocksMouseCursor => false;

		public virtual string TooltipLabel => startTooltipLabel;

		public virtual bool HasCustomPlayerAnimation => false;

		public virtual bool TryGetCustomStartButtonHoldRequirement(out float holdRequirement)
		{
			holdRequirement = 0f;
			return false;
		}

		public virtual bool CanStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenInputHandler input)
		{
			return true;
		}

		public virtual void OnStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.QuickCommsController.AddRestriction(this);
			player.PlayerWalking.AddSprintEnabled(enabled: false, this, int.MaxValue);
			attemptingToExit = false;
			hasSetCameraCullMask = false;
			defaultCameraCullingMask = camera.cullingMask;
		}

		public abstract bool OnUpdate(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input);

		public virtual void OnStop(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud)
		{
			playerController.QuickCommsController.RemoveRestriction(this);
			camera.cullingMask = defaultCameraCullingMask;
			if (player != null)
			{
				player.PlayerWalking.RemoveSprintEnabled(this);
			}
		}

		public virtual void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera)
		{
		}

		protected void UpdateFirstPersonCameraCullingMask(ScreenPlayerController playerController, Camera camera)
		{
			if (!hasSetCameraCullMask && !playerController.IsAnyCameraControllerBlending)
			{
				hasSetCameraCullMask = true;
				camera.cullingMask = defaultCameraCullingMask & -257;
			}
		}

		protected Vector3 GetOffsetDistanceTargetPlayerPosition(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, float desiredDistance)
		{
			Vector3 playerPosition = playerController.GetPlayerPosition(player);
			Vector3 vector = Vector3.ProjectOnPlane(playerPosition - region.transform.position, Vector3.up);
			float magnitude = vector.magnitude;
			if (magnitude <= Mathf.Epsilon)
			{
				return playerPosition;
			}
			Vector3 vector2 = playerPosition - vector;
			Vector3 vector3 = vector / magnitude;
			float num = Mathf.Max(desiredDistance, magnitude);
			return vector2 + vector3 * num;
		}

		protected bool UpdateExit(ScreenHUD hud, ScreenInputHandler input, float holdDuration, string label, out float progressT)
		{
			progressT = 0f;
			if (!attemptingToExit && input.CancelButtonDown)
			{
				attemptingToExit = true;
				exitAttemptStartTime = UnityEngine.Time.time;
			}
			if (!attemptingToExit)
			{
				return false;
			}
			if (input.UsingKeyboardMouse || holdDuration <= Mathf.Epsilon)
			{
				progressT = 1f;
			}
			else
			{
				progressT = Mathf.InverseLerp(exitAttemptStartTime, exitAttemptStartTime + holdDuration, UnityEngine.Time.time);
			}
			if (!input.CancelButtonPressed || input.CancelButtonUp)
			{
				attemptingToExit = false;
				return false;
			}
			return progressT >= 1f;
		}

		protected void UpdateUICursor(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			bool isOverTarget = UpdateMenuInput(playerController, player, camera, input);
			UpdateCursorPosition(isOverTarget, playerController, camera, hud, input);
		}

		private bool UpdateMenuInput(ScreenPlayerController playerController, Player player, Camera camera, ScreenInputHandler input)
		{
			Ray ray = playerController.CursorSystem.GetRay(camera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, float.MaxValue, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, input.CursorButtonDown, input.CursorButtonUp);
			if (result.UISelectable)
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				offHand.MenuFinger.SetLaserButtonPushed(input.CursorButtonDown, input.CursorButtonUp, player.PhotonPlayer, result.LaserPushButton);
			}
			return result.UISelectable;
		}

		private void UpdateCursorPosition(bool isOverTarget, ScreenPlayerController playerController, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (input.UsingKeyboardMouse)
			{
				playerController.CursorSystem.SetCursorScreenPosition(hud, camera, gameViewFocused, input.CursorMouseScreenPosition);
			}
			else
			{
				playerController.CursorSystem.AccelerateCursor(hud, input.CursorAxis, gameViewFocused, isOverTarget);
			}
		}
	}
