	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Context Sensitive Action Controllers/Dressing Room Action Controller", fileName = "DressingRoomActionController")]
	public class DressingRoomContextSensitiveActionController : ScreenContextSensitiveActionController
	{
		[Header("Exit Settings")]
		[SerializeField]
		private float exitButtonHoldDuration = 0.4f;

		[SerializeField]
		private string exitTooltipLabel = "Stop";

		[SerializeField]
		private Vector2 exitInteractDialogViewportPosition = new Vector2(0f, 0.125f);

		[Header("Camera")]
		[SerializeField]
		private ScreenPlayerCameraSettings cameraSettings;

		[SerializeField]
		private OrbitScreenPlayerCamera cameraController;

		[SerializeField]
		private float cameraBlendDuration = 1f;

		[Header("Steering")]
		[SerializeField]
		private ReachTargetFaceCameraForwardScreenPlayerSteering steeringController;

		[Header("Outfit Tool Selection")]
		[SerializeField]
		private float equipButtonHoldDuration = 0.2f;

		[SerializeField]
		private float maxToolPickingDistance = 10f;

		[SerializeField]
		private float toolPickingRadius = 0.05f;

		[SerializeField]
		private Vector2 toolInteractDialogViewportOffset = new Vector2(0f, 0.066f);

		[Header("Cursor")]
		[SerializeField]
		private ScreenPlayerCursorSettings cursorSettings;

		[Header("Dresser Settings")]
		[SerializeField]
		private float drawerChangeCooldown = 1f;

		[NonSerialized]
		private EquipmentSpawner cachedDresser;

		[NonSerialized]
		private int currentDrawerIndex;

		[NonSerialized]
		private float lastDrawerChangeTime;

		[NonSerialized]
		private bool attemptingToEquip;

		[NonSerialized]
		private Tool attemptingToEquipTool;

		[NonSerialized]
		private float equipAttemptStartTime;

		public override bool CanStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenInputHandler input)
		{
			EquipmentSpawner equipmentSpawner = ((!(region.RootGameObject != null)) ? null : region.RootGameObject.GetComponent<EquipmentSpawner>());
			return equipmentSpawner != null && region.PlayerTargetPositionTransform != null;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			base.OnStart(playerController, player, region, camera, hud, input);
			cachedDresser = ((!(region.RootGameObject != null)) ? null : region.RootGameObject.GetComponent<EquipmentSpawner>());
			if (!(cachedDresser == null))
			{
				InitializeDrawers(cachedDresser);
				attemptingToEquip = false;
				steeringController.PositionTarget = region.PlayerTargetPositionTransform.position;
				playerController.AddSteeringController(steeringController, this, 200);
				playerController.AddCameraSettings(cameraSettings, cameraBlendDuration, this, 200);
				playerController.AddCameraController(cameraController, cameraBlendDuration, this, 200);
				player.PlayerWalking.AddJumpEnabled(enabled: false, this, int.MaxValue);
				playerController.CursorSystem.ShowCursor(hud);
				playerController.CursorSystem.SetCursorSettings(hud, cursorSettings);
				playerController.CursorSystem.SnapToCenter(hud);
				hud.EnableCreationOverlay();
				hud.ClearCreationOverlayControlsDialogs();
				hud.AddCreationOverlayControlsDialog(input.CancelButtonSprite, "Finish");
				hud.AddCreationOverlayControlsDialog(input.PickupButtonSprite, "Put On Outfit");
				hud.AddCreationOverlayControlsDialog(input.OffHandActionButtonSprite, "Cycle Drawers");
				hud.AddCreationOverlayControlsDialog(input.SecondaryActionButtonSprite, "Cycle Drawers");
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (cachedDresser == null)
			{
				return false;
			}
			UpdateFirstPersonCameraCullingMask(playerController, camera);
			string drawerName = GetDrawerName(currentDrawerIndex, cachedDresser);
			hud.ClearCreationOverlayActionDialogs();
			hud.SetCreationOverlayActionLabel(drawerName);
			int decrementedDrawerIndex = GetDecrementedDrawerIndex(cachedDresser);
			string drawerName2 = GetDrawerName(decrementedDrawerIndex, cachedDresser);
			hud.AddCreationOverlayActionDialog(input.OffHandActionButtonSprite, drawerName2);
			if (input.OffHandActionButtonDown)
			{
				TryDecrementDrawer(cachedDresser);
			}
			int incrementedDrawerIndex = GetIncrementedDrawerIndex(cachedDresser);
			string drawerName3 = GetDrawerName(incrementedDrawerIndex, cachedDresser);
			hud.AddCreationOverlayActionDialog(input.SecondaryActionButtonSprite, drawerName3);
			if (input.SecondaryMainHandActionButtonDown)
			{
				TryIncrementDrawer(cachedDresser);
			}
			UpdateToolEquip(playerController, player, camera, hud, input);
			float progressT = 0f;
			if (UpdateExit(hud, input, exitButtonHoldDuration, exitTooltipLabel, out progressT))
			{
				return false;
			}
			if (progressT > 0f)
			{
				hud.EnableInteractDialog(exitInteractDialogViewportPosition, input.CancelButtonSprite, "Finish", progressT);
			}
			return true;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud)
		{
			base.OnStop(playerController, player, region, camera, hud);
			if (cachedDresser != null)
			{
				CloseDrawer(cachedDresser);
			}
			if (player != null)
			{
				ClearHoveredTool(playerController, player);
				player.PlayerWalking.RemoveJumpEnabled(this);
			}
			playerController.RemoveSteeringController(this);
			playerController.RemoveCameraSettings(this);
			playerController.RemoveCameraController(this);
			hud.ClearCreationOverlayControlsDialogs();
			hud.ClearCreationOverlayActionDialogs();
			hud.DisableCreationOverlay();
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera)
		{
		}

		private Tool UpdateHoveredTool(ScreenPlayerController playerController, Player player, Camera camera)
		{
			PlayerHand mainHand = playerController.GetMainHand(player);
			Tool closestTool = GetClosestTool(camera);
			if (closestTool == null)
			{
				mainHand.ClearHoveredTool();
			}
			else
			{
				mainHand.SetHoveredTool(closestTool, inPhysicalPickupRange: false);
			}
			return closestTool;
		}

		private void ClearHoveredTool(ScreenPlayerController playerController, Player player)
		{
			PlayerHand mainHand = playerController.GetMainHand(player);
			mainHand.ClearHoveredTool();
		}

		private Tool GetClosestTool(Camera camera)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			Ray ray = camera.ViewportPointToRay(new Vector3(0.5f, 0.5f, 0f));
			int num = Physics.SphereCastNonAlloc(ray, toolPickingRadius, iMMEDIATE_RAYCAST_HITS, maxToolPickingDistance, 1267084288);
			Tool result = null;
			float num2 = float.MaxValue;
			for (int i = 0; i < num; i++)
			{
				if (!(iMMEDIATE_RAYCAST_HITS[i].distance >= num2))
				{
					Tool colliderTool = iMMEDIATE_RAYCAST_HITS[i].collider.GetColliderTool();
					if (!(colliderTool == null) && IsValidTool(colliderTool))
					{
						result = colliderTool;
						num2 = iMMEDIATE_RAYCAST_HITS[i].distance;
					}
				}
			}
			return result;
		}

		private bool IsValidTool(Tool tool)
		{
			OutfitTool component = tool.GetComponent<OutfitTool>();
			if (component != null)
			{
				return true;
			}
			ToolSkinMapper component2 = tool.GetComponent<ToolSkinMapper>();
			if (component2 != null)
			{
				return true;
			}
			return false;
		}

		private void UpdateToolEquip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			Tool tool = UpdateHoveredTool(playerController, player, camera);
			if (UpdateHoldToEquip(tool, camera, hud, input))
			{
				PickupAndReleaseTool(playerController, player, tool);
				OutfitTool component = tool.GetComponent<OutfitTool>();
				if (component != null)
				{
					component.ApplyToPlayer(player);
				}
				ClearAttemptToEquip();
			}
		}

		private bool UpdateHoldToEquip(Tool tool, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!attemptingToEquip && input.PickupButtonDown && tool != null)
			{
				attemptingToEquip = true;
				equipAttemptStartTime = UnityEngine.Time.time;
			}
			if (tool == null)
			{
				return false;
			}
			float num = 0f;
			if (attemptingToEquip)
			{
				num = Mathf.InverseLerp(equipAttemptStartTime, equipAttemptStartTime + equipButtonHoldDuration, UnityEngine.Time.time);
			}
			string empty = string.Empty;
			OutfitTool component = tool.GetComponent<OutfitTool>();
			empty = ((!(component != null)) ? "Set Favorite Skin" : ((!component.IsAlreadyBeingWorn) ? "Put On" : "Take Off"));
			Vector2 viewportPosition = (Vector2)camera.WorldToViewportPoint(tool.transform.position) + toolInteractDialogViewportOffset;
			hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, empty, num);
			if (!attemptingToEquip)
			{
				return false;
			}
			if (!input.PickupButtonPressed || input.PickupButtonUp)
			{
				attemptingToEquip = false;
				return false;
			}
			return num >= 1f;
		}

		private void ClearAttemptToEquip()
		{
			attemptingToEquip = false;
			attemptingToEquipTool = null;
		}

		private void PickupAndReleaseTool(ScreenPlayerController playerController, Player player, Tool tool)
		{
			playerController.TryDropMainHandTool(player);
			playerController.TryPickupToolMainHand(player, tool);
			playerController.TryDropMainHandTool(player);
		}

		private void InitializeDrawers(EquipmentSpawner equipmentSpawner)
		{
			currentDrawerIndex = 0;
			lastDrawerChangeTime = UnityEngine.Time.time;
			equipmentSpawner.SelectDrawer(currentDrawerIndex);
		}

		private void TryIncrementDrawer(EquipmentSpawner equipmentSpawner)
		{
			if (!(UnityEngine.Time.time - lastDrawerChangeTime < drawerChangeCooldown))
			{
				lastDrawerChangeTime = UnityEngine.Time.time;
				currentDrawerIndex = GetIncrementedDrawerIndex(equipmentSpawner);
				equipmentSpawner.SelectDrawer(currentDrawerIndex);
			}
		}

		private void TryDecrementDrawer(EquipmentSpawner equipmentSpawner)
		{
			if (!(UnityEngine.Time.time - lastDrawerChangeTime < drawerChangeCooldown))
			{
				lastDrawerChangeTime = UnityEngine.Time.time;
				currentDrawerIndex = GetDecrementedDrawerIndex(equipmentSpawner);
				equipmentSpawner.SelectDrawer(currentDrawerIndex);
			}
		}

		private void CloseDrawer(EquipmentSpawner equipmentSpawner)
		{
			equipmentSpawner.DeselectDrawer(currentDrawerIndex);
		}

		private int GetIncrementedDrawerIndex(EquipmentSpawner equipmentSpawner)
		{
			int drawerCount = equipmentSpawner.DrawerCount;
			return (currentDrawerIndex + 1) % drawerCount;
		}

		private int GetDecrementedDrawerIndex(EquipmentSpawner equipmentSpawner)
		{
			int drawerCount = equipmentSpawner.DrawerCount;
			if (currentDrawerIndex <= 0)
			{
				return drawerCount - 1;
			}
			return currentDrawerIndex - 1;
		}

		private string GetDrawerName(int index, EquipmentSpawner equipmentSpawner)
		{
			return equipmentSpawner.GetDrawerName(index);
		}
	}
