		private float minHoldDuration = 0.2f;

		[SerializeField]
		private Vector2 viewportTooltipPosition = new Vector2(0.5f, 0.2f);

		[NonSerialized]
		private float startTime;

		[NonSerialized]
		private bool inputHasBeenReleased;

		public override bool TryGetCustomStartButtonHoldRequirement(out float holdRequirement)
		{
			holdRequirement = 0f;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenInputHandler input)
		{
			PhysicalButtonBase physicalButtonBase = ((!(region.RootGameObject != null)) ? null : region.RootGameObject.GetComponent<PhysicalButtonBase>());
			return physicalButtonBase != null;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			base.OnStart(playerController, player, region, camera, hud, input);
			startTime = UnityEngine.Time.time;
			inputHasBeenReleased = false;
			PhysicalButtonBase physicalButtonBase = ((!(region.RootGameObject != null)) ? null : region.RootGameObject.GetComponent<PhysicalButtonBase>());
			if (physicalButtonBase != null)
			{
				physicalButtonBase.LaserPress(player.PhotonPlayer);
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!inputHasBeenReleased)
			{
				hud.EnableInteractDialog(viewportTooltipPosition, input.PickupButtonSprite, TooltipLabel, 1f);
				inputHasBeenReleased = !input.PickupButtonPressed || input.PickupButtonUp;
			}
			if (UnityEngine.Time.time - startTime <= minHoldDuration)
			{
				return true;
			}
			if (!region.IsLocalPlayerInThisRegion)
			{
				return false;
			}
			return !inputHasBeenReleased;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, ScreensContextSensitiveActionRegion region, Camera camera, ScreenHUD hud)
		{
			base.OnStop(playerController, player, region, camera, hud);
			PhysicalButtonBase physicalButtonBase = ((!(region.RootGameObject != null)) ? null : region.RootGameObject.GetComponent<PhysicalButtonBase>());
			if (physicalButtonBase != null)
			{
				physicalButtonBase.LaserRelease(player.PhotonPlayer);
			}
		}
	}
