namespace RecRoom.Core
{
	public abstract class ScreenSocialActionController : ScriptableObject
	{
		protected delegate bool PlayerTest(Player player);

		[Header("Player Search Settings")]
		[SerializeField]
		protected float maxSearchRadius = 2.5f;

		private const float PLAYER_SEARCH_PERIOD = 0.5f;

		[NonSerialized]
		private float lastSearchTime;

		[NonSerialized]
		private Player cachedNearbyPlayer;

		public abstract bool IsBlocking { get; }

		public abstract bool CanStart(ScreenPlayerController playerController, Player player, ScreenInputHandler input);

		public abstract bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input);

		public abstract void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input);

		public abstract bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input);

		public abstract void OnStop(ScreenPlayerController playerController, Player player);

		public abstract void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player);

		protected Player GetNearbyPlayer(Player thisPlayer, PlayerTest playerTest)
		{
			float time = UnityEngine.Time.time;
			float num = time - lastSearchTime;
			if (num < 0f || num >= 0.5f)
			{
				lastSearchTime = time;
				cachedNearbyPlayer = SearchForNearbyPotentialFriend(thisPlayer, playerTest);
			}
			else if (cachedNearbyPlayer != null && !playerTest(cachedNearbyPlayer))
			{
				cachedNearbyPlayer = null;
			}
			return cachedNearbyPlayer;
		}

		private Player SearchForNearbyPotentialFriend(Player thisPlayer, PlayerTest playerTest)
		{
			Vector3 targetPosition = thisPlayer.TrackingSpace.RigidbodyEx.targetPosition;
			Player result = null;
			float num = maxSearchRadius * maxSearchRadius;
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				if (PhotonNetwork.playerList[i].IsLocal)
				{
					continue;
				}
				Player player = PhotonNetwork.playerList[i].ToPlayer();
				if (!(player == null) && playerTest(player))
				{
					Vector3 position = player.TrackingSpace.transform.position;
					float sqrMagnitude = (position - targetPosition).sqrMagnitude;
					if (sqrMagnitude < num)
					{
						result = player;
						num = sqrMagnitude;
					}
				}
			}
			return result;
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Social Action Controllers/High Five Screen Social Action Controller", fileName = "HighFiveScreenSocialActionController")]
	public class HighFiveScreenSocialActionController : ScreenSocialActionController
	{
		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation highFiveAnimation;

		[Header("Walk Settings")]
		[SerializeField]
		protected float walkSpeedMultiplier;

		[Header("Tooltip")]
		[SerializeField]
		private float tooltipHeight = 1f;

		public override bool IsBlocking => true;

		public override bool CanStart(ScreenPlayerController playerController, Player player, ScreenInputHandler input)
		{
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialHighFiveTarget);
			return nearbyPlayer != null && (player.PlayerParty.IsWaitingToHighFive || input.PickupButtonDown || input.PickupButtonPressed);
		}

		public override bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialHighFiveTarget);
			if (nearbyPlayer != null && !playerController.IsAnimationPlaying(highFiveAnimation))
			{
				Vector2 viewportPosition = camera.WorldToViewportPoint(nearbyPlayer.TrackingSpace.transform.position + Vector3.up * tooltipHeight);
				hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, "High Five");
				return true;
			}
			return false;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.PlayAnimation(highFiveAnimation);
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplier, this);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			return playerController.IsAnimationPlaying(highFiveAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player)
		{
			playerController.RemoveWalkSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1)
			{
				Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialHighFiveTarget);
				if (nearbyPlayer != null)
				{
					PlayerHand mainHand = playerController.GetMainHand(player);
					mainHand.Gestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.Highfive, nearbyPlayer.RightHand, pauseOthers: false);
				}
			}
		}

		private bool IsPlayerPotentialHighFiveTarget(Player player)
		{
			return player.PlayerParty.IsWaitingToHighFive;
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Social Action Controllers/Make Friend Screen Social Action Controller", fileName = "MakeFriendScreenSocialActionController")]
	public class MakeFriendScreenSocialActionController : ScreenSocialActionController
	{
		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation acceptHandshakeAnimation;

		[SerializeField]
		private PlayerAnimation loopingHandshakeAnimation;

		[SerializeField]
		private PlayerAnimation finishHandshakeAnimation;

		[Header("Settings")]
		[SerializeField]
		private float buttonHoldDuration = 1f;

		[SerializeField]
		private float walkSpeedMultiplier;

		[Header("Tooltip")]
		[SerializeField]
		private float tooltipHeight = 1f;

		[NonSerialized]
		private Player handshakePlayer;

		[NonSerialized]
		private float buttonHoldStartTime;

		[NonSerialized]
		private bool isHoldingButton;

		[NonSerialized]
		private bool isPlayingLoopingAnimation;

		public override bool IsBlocking => true;

		public override bool CanStart(ScreenPlayerController playerController, Player player, ScreenInputHandler input)
		{
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialFriend);
			return nearbyPlayer != null && (player.PlayerParty.IsWaitingToMakeFriend || input.PickupButtonDown || input.PickupButtonPressed);
		}

		public override bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (isHoldingButton && handshakePlayer != null)
			{
				Vector2 viewportPosition = camera.WorldToViewportPoint(handshakePlayer.TrackingSpace.transform.position + Vector3.up * tooltipHeight);
				float progress = ((!isHoldingButton) ? 0f : Mathf.InverseLerp(buttonHoldStartTime, buttonHoldStartTime + buttonHoldDuration, UnityEngine.Time.time));
				hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, "Add Friend", progress);
				return true;
			}
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialFriend);
			if (nearbyPlayer != null)
			{
				Vector2 viewportPosition2 = camera.WorldToViewportPoint(nearbyPlayer.TrackingSpace.transform.position + Vector3.up * tooltipHeight);
				hud.EnableInteractDialog(viewportPosition2, input.PickupButtonSprite, "Add Friend");
				return true;
			}
			return false;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			handshakePlayer = GetNearbyPlayer(player, IsPlayerPotentialFriend);
			isHoldingButton = true;
			isPlayingLoopingAnimation = false;
			buttonHoldStartTime = UnityEngine.Time.time;
			playerController.PlayAnimation(acceptHandshakeAnimation);
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplier, this);
			if (handshakePlayer != null)
			{
				PlayerHand mainHand = playerController.GetMainHand(player);
				mainHand.Gestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeStart, handshakePlayer.RightHand, pauseOthers: false);
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (handshakePlayer == null)
			{
				return false;
			}
			if (isHoldingButton)
			{
				if (!input.PickupButtonPressed || input.PickupButtonUp)
				{
					return false;
				}
				if (!isPlayingLoopingAnimation)
				{
					isPlayingLoopingAnimation = true;
					playerController.PlayLoopingAnimation(loopingHandshakeAnimation);
				}
				float num = UnityEngine.Time.time - buttonHoldStartTime;
				if (num >= buttonHoldDuration)
				{
					isHoldingButton = false;
					playerController.PlayUninterruptableAnimation(finishHandshakeAnimation, restartIfAlreadyPlaying: true);
				}
				return true;
			}
			return playerController.IsAnimationPlaying(finishHandshakeAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player)
		{
			if (isHoldingButton && handshakePlayer != null && player != null)
			{
				PlayerHand mainHand = playerController.GetMainHand(player);
				mainHand.Gestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeCancel, handshakePlayer.RightHand, pauseOthers: false);
			}
			handshakePlayer = null;
			playerController.RemoveWalkSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1 && handshakePlayer != null)
			{
				PlayerHand mainHand = playerController.GetMainHand(player);
				mainHand.Gestures.AuthorityTriggerGesture(PlayerHandGestures.Gesture.HandshakeSuccess, handshakePlayer.RightHand, pauseOthers: false);
			}
		}

		private bool IsPlayerPotentialFriend(Player player)
		{
			return player.PlayerParty.IsWaitingToMakeFriend;
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Social Action Controllers/Party Up Screen Social Action Controller", fileName = "PartyUpScreenSocialActionController")]
	public class PartyUpScreenSocialActionController : ScreenSocialActionController
	{
		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation partyUpAnimation;

		[Header("Settings")]
		[SerializeField]
		private float walkSpeedMultiplier;

		[Header("Tooltip")]
		[SerializeField]
		private float tooltipHeight = 1f;

		public override bool IsBlocking => true;

		public override bool CanStart(ScreenPlayerController playerController, Player player, ScreenInputHandler input)
		{
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialPartyMember);
			return nearbyPlayer != null && (player.PlayerParty.IsWaitingtoJoinAParty || input.PickupButtonDown || input.PickupButtonPressed);
		}

		public override bool TryDisplayTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialPartyMember);
			if (nearbyPlayer != null && !playerController.IsAnimationPlaying(partyUpAnimation))
			{
				Vector2 viewportPosition = camera.WorldToViewportPoint(nearbyPlayer.TrackingSpace.transform.position + Vector3.up * tooltipHeight);
				hud.EnableInteractDialog(viewportPosition, input.PickupButtonSprite, "Party Up");
				return true;
			}
			return false;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.PlayAnimation(partyUpAnimation);
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplier, this);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			return playerController.IsAnimationPlaying(partyUpAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player)
		{
			playerController.RemoveWalkSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, ScreenPlayerController playerController, Player player)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1)
			{
				Player nearbyPlayer = GetNearbyPlayer(player, IsPlayerPotentialPartyMember);
				if (nearbyPlayer != null)
				{
					PlayerHand mainHand = playerController.GetMainHand(player);
					Vector3 targetPosition = mainHand.RigidbodyEx.targetPosition;
					player.PlayerParty.JoinParty(nearbyPlayer.PhotonPlayer, targetPosition);
				}
			}
		}

		private bool IsPlayerPotentialPartyMember(Player player)
		{
			return player.PlayerParty.IsWaitingtoJoinAParty;
		}
	}
