		public abstract void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input);

		public abstract void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud);

		public abstract void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud);

		public abstract bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input);

		public abstract void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input);

		public abstract void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud);

		public abstract bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input);

		public abstract void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool);

		protected bool UpdateExitActionButtonHold(ScreenInputHandler input, ScreenHUD hud, float holdDuration, string label, Vector2 viewportTooltipPosition, ref bool isAttemptingToExit, ref float exitAttemptStartTime)
		{
			if (!isAttemptingToExit && input.DropButtonDown)
			{
				isAttemptingToExit = true;
				exitAttemptStartTime = UnityEngine.Time.time;
			}
			if (!isAttemptingToExit)
			{
				return false;
			}
			float num = Mathf.InverseLerp(exitAttemptStartTime, exitAttemptStartTime + holdDuration, UnityEngine.Time.time);
			hud.EnableInteractDialog(viewportTooltipPosition, input.DropToolButtonSprite, label, num);
			if (!input.DropButtonPressed || input.DropButtonUp)
			{
				isAttemptingToExit = false;
				return false;
			}
			return num >= 1f;
		}
	}
}
