		public static event PowerupActivationRequest PowerupActivationRequestedEvent
		{
			add
			{
				PowerupActivationRequest powerupActivationRequest = Powerup.m_PowerupActivationRequestedEvent;
				PowerupActivationRequest powerupActivationRequest2;
				do
				{
					powerupActivationRequest2 = powerupActivationRequest;
					powerupActivationRequest = Interlocked.CompareExchange(ref Powerup.m_PowerupActivationRequestedEvent, (PowerupActivationRequest)Delegate.Combine(powerupActivationRequest2, value), powerupActivationRequest);
				}
				while (powerupActivationRequest != powerupActivationRequest2);
			}
			remove
			{
				PowerupActivationRequest powerupActivationRequest = Powerup.m_PowerupActivationRequestedEvent;
				PowerupActivationRequest powerupActivationRequest2;
				do
				{
					powerupActivationRequest2 = powerupActivationRequest;
					powerupActivationRequest = Interlocked.CompareExchange(ref Powerup.m_PowerupActivationRequestedEvent, (PowerupActivationRequest)Delegate.Remove(powerupActivationRequest2, value), powerupActivationRequest);
				}
				while (powerupActivationRequest != powerupActivationRequest2);
			}
		}

