		public static void RequestPowerupActivation(PowerupType powerupType, PhotonPlayer player)
		{
			if (Powerup.PowerupActivationRequestedEvent != null)
			{
				Powerup.PowerupActivationRequestedEvent(powerupType, player);
			}
		}

		public static Powerup MasterSpawnPowerup(PowerupType powerupType, PhotonPlayer player, int instantiatorPhotonViewId, Dictionary<string, object> instantiationParams)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return null;
			}
			string powerupPrefabName = PowerupSettings.GetPowerupPrefabName(powerupType);
			if (string.IsNullOrEmpty(powerupPrefabName))
			{
				return null;
			}
			object[] data = new object[4] { instantiatorPhotonViewId, instantiationParams, player.ID, powerupType };
			Vector3 position = Vector3.zero;
			Quaternion rotation = Quaternion.identity;
			Player player2 = player.ToPlayer();
			if (player2 != null)
			{
				position = player2.transform.position;
				rotation = player2.transform.rotation;
			}
			GameObject gameObject = PhotonNetwork.InstantiateSceneObject(powerupPrefabName, position, rotation, 1f, 0, data);
			return (!(gameObject != null)) ? null : gameObject.GetComponent<Powerup>();
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
			if (base.photonView.instantiationData != null && base.photonView.instantiationData.Length == 4)
			{
				int num = (int)base.photonView.instantiationData[2];
				TargetPlayer = PhotonPlayer.Find(num);
				if (TargetPlayer != null)
				{
					Type = (PowerupType)base.photonView.instantiationData[3];
					if (base.photonView.owner != TargetPlayer && base.hasAuthority)
					{
						base.photonView.TransferOwnership(TargetPlayer);
					}
					if (Powerup.PowerupInstantiatedEvent != null)
					{
						Powerup.PowerupInstantiatedEvent(this);
					}
					Weapon.EnemyImpactEventStatic += OnWeaponEnemyImpact;
					Weapon.PostImpactEventStatic += OnWeaponPostImpact;
					lifeTimer = new SynchronizedTimer(this, "lt", SetterPermissionMode.MASTER);
					lifeTimer.StartTimerEvent += OnTimerRestart;
					if (PhotonNetwork.isMasterClient)
					{
						MasterRestartTimer();
					}
					PlayActiveEffects();
				}
				else
				{
					UnityEngine.Debug.LogWarningFormat("Powerup {0} instantiated for missing target player with ID {1}", base.gameObject.name, num);
					UnityEngine.Object.Destroy(base.gameObject);
				}
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Powerup {0} instantiated by something other than Photon.", base.gameObject.name);
				UnityEngine.Object.Destroy(base.gameObject);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Weapon.EnemyImpactEventStatic -= OnWeaponEnemyImpact;
			Weapon.PostImpactEventStatic -= OnWeaponPostImpact;
			lifeTimer.StartTimerEvent -= OnTimerRestart;
			StopActiveEffects();
			Player player = TargetPlayer.ToPlayer();
			if (player != null)
			{
				PlayDestroyedEffects(player);
			}
			if (Powerup.PowerupDestroyedEvent != null)
			{
				Powerup.PowerupDestroyedEvent(this);
			}
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		private void Update()
		{
			lifeTimer.UpdateCallbacks();
			if (PhotonNetwork.isMasterClient && lifeTimer.TimerOver)
			{
				MasterCleanup();
			}
		}

		private void LateUpdate()
		{
			Player player = TargetPlayer.ToPlayer();
			if (player != null)
			{
				base.transform.position = player.CurrentFloorPosition;
				if (currentParticles != null)
				{
					currentParticles.transform.position = base.transform.position;
				}
			}
		}

		public void MasterRestartTimer()
		{
			if (PhotonNetwork.isMasterClient)
			{
				lifeTimer.StartTimer(_lifeTime);
			}
		}

		private void OnTimerRestart()
		{
			Player player = TargetPlayer.ToPlayer();
			if (player != null)
			{
				PlaySpawnEffects(player);
			}
			if (Powerup.PowerupEffectsStartedEvent != null)
			{
				Powerup.PowerupEffectsStartedEvent(this);
			}
		}

		protected virtual void PlaySpawnEffects(Player playerAvatar)
		{
			if (spawnSfx != null)
			{
				AudioManager.Play3DSFX(spawnSfx, base.transform);
			}
			if (spawnParticlePrefab != null)
			{
				currentParticles = PlayParticles(spawnParticlePrefab, loop: false);
			}
		}

		protected virtual void PlayDestroyedEffects(Player playerAvatar)
		{
			if (destroyedSfx != null && destroyedSfx.audioClip != null)
			{
				AudioManager.Play3DSFX(destroyedSfx, base.transform);
			}
			if (destroyedParticlePrefab != null)
			{
				currentParticles = PlayParticles(destroyedParticlePrefab, loop: false);
			}
		}

		protected virtual void PlayActiveEffects()
		{
			if (activeLoopSfx != null)
			{
				activeAudioSource = AudioManager.StartLooping3DSFX(activeLoopSfx, base.transform);
			}
			if (activeParticlesPrefab != null)
			{
				currentParticles = PlayParticles(activeParticlesPrefab, loop: true);
			}
			if (TargetPlayer.IsLocal && !string.IsNullOrEmpty(notificationText))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.AddPersistentNotification(notificationText, this);
			}
		}

		protected virtual void StopActiveEffects()
		{
			if (TargetPlayer.IsLocal && !string.IsNullOrEmpty(notificationText))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
			}
			if (currentParticles != null)
			{
				currentParticles.Stop();
			}
			if ((bool)activeAudioSource)
			{
				activeAudioSource.Release();
			}
		}

		protected PooledParticle PlayParticles(PooledParticle prefab, bool loop)
		{
			PooledParticle pooledParticle = null;
			if (prefab != null && TargetPlayer != null && !TargetPlayer.IsLocal)
			{
				Player player = TargetPlayer.ToPlayer();
				if (player != null)
				{
					pooledParticle = ObjectPool.Instance.Acquire(prefab);
					if (pooledParticle != null)
					{
						pooledParticle.Play(player.CurrentFloorPosition, Quaternion.LookRotation(Vector3.up, player.transform.forward), loop);
						return pooledParticle;
					}
				}
			}
			return pooledParticle;
		}

		private void OnWeaponEnemyImpact(Weapon weapon, Enemy defender, WeaponImpact impact, bool hadDamageAuthority)
		{
			if (weapon != null && weapon.Wielder.IsValid && weapon.Wielder.Player != null && weapon.Wielder.Player.PhotonPlayer == TargetPlayer)
			{
				ProcessEnemyImpact(weapon, defender, impact, hadDamageAuthority);
			}
		}

		private void OnWeaponPostImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
		{
			if (!(weapon != null) || !weapon.Wielder.IsValid || !(weapon.Wielder.Player != null) || weapon.Wielder.Player.PhotonPlayer != TargetPlayer)
			{
				return;
			}
			if (impactSfx != null)
			{
				AudioManager.Play3DSFX(impactSfx, impact.Point);
			}
			if (impactDecalPrefab != null)
			{
				ImpactDecal.Spawn(impactDecalPrefab, Color.white, impact.Point, impact.SurfaceNormal, impact.GameObject);
			}
			if (impactParticle != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(impactParticle);
				if ((bool)pooledParticle)
				{
					pooledParticle.Play(impact.Point, Quaternion.LookRotation(impact.SurfaceNormal, Vector3.up));
				}
			}
		}

		protected virtual void ProcessEnemyImpact(Weapon weapon, Enemy defender, WeaponImpact impact, bool hadDamageAuthority)
		{
		}

		private void MasterCleanup()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				PhotonNetwork.Destroy(base.photonView);
			}
		}

		protected void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			if (lifeTimer.TimerOver)
			{
				MasterCleanup();
			}
		}
	}
