	public static class PowerupSettings
	{
		public static PowerupConfig ConfigAsset = CustomSettingsLoader.LoadConfig<PowerupConfig>();

		private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

		public static string FullConfigAssetFilePath => CustomSettingsLoader.GetTrimmedFilePath("Assets/Core/Content/Configs/");

		public static string FullConfigAssetFileName => CustomSettingsLoader.GetAssetFileName<LegacyPowerup>() + ".asset";

		public static string FullConfigAssetFilePathAndFileName => $"{FullConfigAssetFilePath}/{FullConfigAssetFileName}";

		public static void PreloadAssets()
		{
			foreach (object value in System.Enum.GetValues(typeof(PowerupType)))
			{
				string powerupPrefabName = GetPowerupPrefabName((PowerupType)value);
				if (!string.IsNullOrEmpty(powerupPrefabName) && !PhotonNetwork.PrefabCache.ContainsKey(powerupPrefabName))
				{
					PhotonNetwork.PrefabCache.Add(powerupPrefabName, Resources.Load<GameObject>(powerupPrefabName));
				}
			}
		}

		public static string GetPowerupPrefabName(PowerupType powerup)
		{
			PowerupConfig.Config powerupConfig = GetPowerupConfig(powerup);
			if (powerupConfig != null && powerupConfig.Prefab != null)
			{
				return powerupConfig.Prefab.name;
			}
			return null;
		}

		private static PowerupConfig.Config GetPowerupConfig(PowerupType powerup)
		{
			if (ConfigAsset != null && ConfigAsset.Powerups != null && powerup >= PowerupType.QUEST_DAMAGE && (int)powerup < ConfigAsset.Powerups.Length)
			{
				return ConfigAsset.Powerups[(int)powerup];
			}
			return null;
		}
	}
}
public enum PowerupType
{
	INVALID = -1,
	QUEST_DAMAGE,
	SOCCER_SPEED
}
public class ConfigureCameraBasedOnQualitySetting : UnityEngine.MonoBehaviour
{
	public RecRoomQualitySetting[] DisableDepthPassForQualitySettings;

	private void Update()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null && RecroomPrefs.IsReady)
		{
			ApplyQualitySetting();
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
			base.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
		}
	}

	private void OnQualitySettingChanged(RecRoomQualitySetting setting)
	{
		ApplyQualitySetting();
	}

	private void ApplyQualitySetting()
	{
		Camera component = GetComponent<Camera>();
		if (component == null)
		{
			return;
		}
		RecRoomQualitySetting qualitySetting = SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting;
		bool flag = true;
		if (DisableDepthPassForQualitySettings != null)
		{
			for (int i = 0; i < DisableDepthPassForQualitySettings.Length; i++)
			{
				if (DisableDepthPassForQualitySettings[i] == qualitySetting)
				{
					flag = false;
					break;
				}
			}
		}
		if (flag)
		{
			component.depthTextureMode = DepthTextureMode.Depth;
		}
		else
		{
			component.depthTextureMode = DepthTextureMode.None;
		}
		if (component == SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera)
		{
			int value = (flag ? 1 : 0);
			Shader.SetGlobalInt("_DepthAvailable", value);
		}
	}
}
public class DisableBasedOnQualitySetting : UnityEngine.MonoBehaviour
{
	public RecRoomQualitySetting[] RemoveForQualitySettings;

	private bool isInitialized;

	private void Awake()
	{
		TryInitialize();
	}

	private void TryInitialize()
	{
		if (!isInitialized && SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			ApplyQualitySetting();
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
			isInitialized = true;
		}
	}

	public void Update()
	{
		TryInitialize();
		if (isInitialized)
		{
			base.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (isInitialized && SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
		}
	}

	private void OnQualitySettingChanged(RecRoomQualitySetting setting)
	{
		ApplyQualitySetting();
	}

	private void ApplyQualitySetting()
	{
		RecRoomQualitySetting qualitySetting = SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting;
		bool active = true;
		if (RemoveForQualitySettings != null)
		{
			for (int i = 0; i < RemoveForQualitySettings.Length; i++)
			{
				if (RemoveForQualitySettings[i] == qualitySetting)
				{
					active = false;
					break;
				}
			}
		}
		base.gameObject.SetActive(active);
	}
}
