namespace RecRoom.Core.Quality
{
	public class LightQualityOverride : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private struct OverrideSettings
		{
			public RecRoomQualitySetting quality;

			public LightRenderMode renderMode;
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Light _light;

		[SerializeField]
		private OverrideSettings[] overrides;

		private LightRenderMode originalRenderMode;

		private void Start()
		{
			if (overrides.Length == 0)
			{
				UnityEngine.Debug.LogError("LightQualityOverride requires at least one specified override.");
				return;
			}
			originalRenderMode = _light.renderMode;
			ApplyQualitySetting(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
			}
		}

		private void OnQualitySettingChanged(RecRoomQualitySetting setting)
		{
			ApplyQualitySetting(setting);
		}

		private void ApplyQualitySetting(RecRoomQualitySetting setting)
		{
			bool flag = false;
			for (int i = 0; i < overrides.Length; i++)
			{
				if (overrides[i].quality == setting)
				{
					_light.renderMode = overrides[i].renderMode;
					break;
				}
			}
			if (!flag)
			{
				_light.renderMode = originalRenderMode;
			}
		}
	}
	public class ParticleQualityOverride : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public struct OverrideSettings
		{
			public RecRoomQualitySetting quality;

			public int maxParticles;

			public bool enableTrails;

			public bool overrideEmissionRate;

			[Range(0f, 1f)]
			public float emissionRateMultiplier;

			public bool overrideLifetime;

			[Range(0f, 2f)]
			public float lifetimeMultiplier;
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private ParticleSystem particles;

		[SerializeField]
		private OverrideSettings[] overrides;

		private bool originalEmissionEnabled;

		private int originalMaxParticles;

		private bool originalEnableTrails;

		private float originalLifetimeScalar;

		private float originalLifetimeMin;

		private float originalRateOverTimeScalar;

		private float originalRateOverTimeMin;

		private float originalRateOverDistanceScalar;

		private float originalRateOverDistanceMin;

		private ParticleSystem.MainModule mainModule;

		private ParticleSystem.TrailModule trailModule;

		private ParticleSystem.EmissionModule emissionModule;

		private void Start()
		{
			if (overrides.Length == 0)
			{
				UnityEngine.Debug.LogError("ParticleQualityOverride requires at least one specified override.");
				return;
			}
			CacheOriginalValues();
			ApplyQualitySetting(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
			}
		}

		private void OnQualitySettingChanged(RecRoomQualitySetting setting)
		{
			ApplyQualitySetting(setting);
		}

		private void ApplyQualitySetting(RecRoomQualitySetting setting)
		{
			bool flag = false;
			for (int i = 0; i < overrides.Length; i++)
			{
				OverrideSettings overrideSetting = overrides[i];
				if (overrideSetting.quality == setting)
				{
					ApplyOverrideSettings(overrideSetting);
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				ResetSettings();
			}
		}

		private void ApplyOverrideSettings(OverrideSettings overrideSetting)
		{
			mainModule.maxParticles = overrideSetting.maxParticles;
			trailModule.enabled = overrideSetting.enableTrails;
			if (overrideSetting.overrideEmissionRate)
			{
				emissionModule.rateOverTime = ModifyMinMaxCurve(emissionModule.rateOverTime, originalRateOverTimeScalar * overrideSetting.emissionRateMultiplier, originalRateOverTimeMin * overrideSetting.emissionRateMultiplier);
				emissionModule.rateOverDistance = ModifyMinMaxCurve(emissionModule.rateOverDistance, originalRateOverDistanceScalar * overrideSetting.emissionRateMultiplier, originalRateOverDistanceMin * overrideSetting.emissionRateMultiplier);
			}
			if (overrideSetting.overrideLifetime)
			{
				mainModule.startLifetime = ModifyMinMaxCurve(mainModule.startLifetime, originalLifetimeScalar * overrideSetting.lifetimeMultiplier, originalLifetimeMin * overrideSetting.lifetimeMultiplier);
			}
		}

		private void ResetSettings()
		{
			mainModule.maxParticles = originalMaxParticles;
			trailModule.enabled = originalEnableTrails;
			emissionModule.enabled = originalEmissionEnabled;
			mainModule.startLifetime = ModifyMinMaxCurve(mainModule.startLifetime, originalLifetimeScalar, originalLifetimeMin);
			emissionModule.rateOverTime = ModifyMinMaxCurve(emissionModule.rateOverTime, originalRateOverTimeScalar, originalRateOverTimeMin);
			emissionModule.rateOverDistance = ModifyMinMaxCurve(emissionModule.rateOverDistance, originalRateOverDistanceScalar, originalRateOverDistanceMin);
		}

		private void CacheOriginalValues()
		{
			mainModule = particles.main;
			trailModule = particles.trails;
			emissionModule = particles.emission;
			originalEmissionEnabled = emissionModule.enabled;
			originalMaxParticles = mainModule.maxParticles;
			originalEnableTrails = trailModule.enabled;
			CacheMinMaxCurve(mainModule.startLifetime, out originalLifetimeScalar, out originalLifetimeMin);
			CacheMinMaxCurve(emissionModule.rateOverDistance, out originalRateOverDistanceScalar, out originalRateOverDistanceMin);
			CacheMinMaxCurve(emissionModule.rateOverTime, out originalRateOverTimeScalar, out originalRateOverTimeMin);
		}

		private void CacheMinMaxCurve(ParticleSystem.MinMaxCurve curve, out float scalarValue, out float minValue)
		{
			minValue = -1f;
			switch (curve.mode)
			{
			case ParticleSystemCurveMode.Constant:
				scalarValue = curve.constant;
				break;
			case ParticleSystemCurveMode.TwoConstants:
				scalarValue = curve.constantMax;
				minValue = curve.constantMin;
				break;
			case ParticleSystemCurveMode.Curve:
			case ParticleSystemCurveMode.TwoCurves:
				scalarValue = curve.curveMultiplier;
				break;
			default:
				throw new ArgumentException("Unsupported animation curve mode: " + curve.mode);
			}
		}

		private ParticleSystem.MinMaxCurve ModifyMinMaxCurve(ParticleSystem.MinMaxCurve curve, float scalarValue, float minValue)
		{
			switch (curve.mode)
			{
			case ParticleSystemCurveMode.Constant:
				curve.constant = scalarValue;
				break;
			case ParticleSystemCurveMode.TwoConstants:
				curve.constantMax = scalarValue;
				curve.constantMin = minValue;
				break;
			case ParticleSystemCurveMode.Curve:
			case ParticleSystemCurveMode.TwoCurves:
				curve.curveMultiplier = scalarValue;
				break;
			default:
				throw new ArgumentException("Unsupported animation curve mode: " + curve.mode);
			}
			return curve;
		}
	}
}
[RequireComponent(typeof(Terrain))]
public class TerrainQualitySettings : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class Settings
	{
		public RecRoomQualitySetting QualitySetting;

		public float PixelError;

		public float DetailDistance;
	}

	public Settings[] QualitySettingOverrides;

	private Terrain terrain;

	private void Awake()
	{
		terrain = GetComponent<Terrain>();
	}

	private void Start()
	{
		ApplySettings();
		SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
	}

	private void OnQualitySettingChanged(RecRoomQualitySetting setting)
	{
		ApplySettings();
	}

	private void OnDestroy()
	{
		SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
	}

	private void ApplySettings()
	{
		RecRoomQualitySetting qualitySetting = SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting;
		Settings settings = null;
		if (QualitySettingOverrides != null)
		{
			for (int i = 0; i < QualitySettingOverrides.Length; i++)
			{
				if (QualitySettingOverrides[i].QualitySetting == qualitySetting)
				{
					settings = QualitySettingOverrides[i];
					break;
				}
			}
		}
		if (settings != null)
		{
			terrain.heightmapPixelError = settings.PixelError;
			terrain.detailObjectDistance = settings.DetailDistance;
		}
	}
}
