	public class Avatars
	{
		public class GiftPackage : IRecNetObject, IRecNetRequestObject
		{
			public long Id { get; private set; }

			public string ConsumableItemDesc { get; private set; }

			public string AvatarItemDesc { get; private set; }

			public string EquipmentPrefabName { get; private set; }

			public string EquipmentModificationGuid { get; private set; }

			public CurrencyType CurrencyType { get; private set; }

			public int Currency { get; private set; }

			public int Xp { get; private set; }

			public int Level { get; private set; }

			public GiftManager.GiftContext GiftContext { get; private set; }

			public GiftManager.GiftRarity GiftRarity { get; private set; }

			public string Message { get; set; }

			public PlatformManager.PlatformType Platform { get; set; }

			public Material PackageMaterial { get; private set; }

			public GiftPackageVariant PackageVariant { get; private set; }

			public bool HasAvatarItem => !string.IsNullOrEmpty(AvatarItemDesc);

			public bool HasEquipment => !string.IsNullOrEmpty(EquipmentPrefabName);

			public bool Consumed { get; set; }

			public bool IsValid { get; private set; }

			public string ErrorMessage { get; private set; }

			public bool SupportsCurrentPlatform { get; private set; }

			public void Deserialize(Dictionary<string, object> dict)
			{
				if (dict != null && dict.ContainsKey("Id"))
				{
					Id = Util.GetKey<long>("Id", dict);
					AvatarItemDesc = Util.GetKeyOrDefault<string>("AvatarItemDesc", dict);
					ConsumableItemDesc = Util.GetKeyOrDefault<string>("ConsumableItemDesc", dict);
					EquipmentPrefabName = Util.GetKeyOrDefault<string>("EquipmentPrefabName", dict);
					EquipmentModificationGuid = Util.GetKeyOrDefault<string>("EquipmentModificationGuid", dict);
					Platform = (PlatformManager.PlatformType)Util.GetKey<int>("Platform", dict);
					CurrencyType = (CurrencyType)Util.GetKeyOrDefault<int>("CurrencyType", dict);
					Currency = Util.GetKeyOrDefault<int>("Currency", dict);
					if (CurrencyType == CurrencyType.Invalid && Currency != 0)
					{
						UnityEngine.Debug.LogError("Misconfigured GiftPackage. Should have currency and currency type!");
					}
					Xp = Util.GetKey<int>("Xp", dict);
					Level = Util.GetKey<int>("Level", dict);
					if (dict.ContainsKey("GiftRarity"))
					{
						GiftRarity = (GiftManager.GiftRarity)Util.GetKey<int>("GiftRarity", dict);
					}
					else
					{
						GiftRarity = GiftManager.GiftRarity.Common;
					}
					if (dict.ContainsKey("Message"))
					{
						Message = Util.GetKey<string>("Message", dict);
					}
					GiftManager.GiftContext giftContext = GiftManager.GiftContext.Default;
					if (dict.ContainsKey("GiftContext"))
					{
						giftContext = (GiftManager.GiftContext)Util.GetKey<int>("GiftContext", dict);
					}
					SetGiftContext(giftContext);
					SupportsCurrentPlatform = Platform.CanBeUsedByCurrentPlatform();
					IsValid = true;
				}
				else
				{
					if (dict != null && dict.ContainsKey("Message"))
					{
						ErrorMessage = Util.GetKey<string>("Message", dict);
					}
					IsValid = false;
				}
				Consumed = false;
			}

			public void SetGiftContext(GiftManager.GiftContext context)
			{
				GiftContext = context;
				GiftPackageVariant.GiftContextMapping giftContextMap = null;
				PackageVariant = SingletonMonoBehaviour<GiftManager>.Instance.GetPackageVariantByContext(context, out giftContextMap);
				if (giftContextMap != null)
				{
					if (string.IsNullOrEmpty(Message))
					{
						Message = giftContextMap.label;
					}
					PackageMaterial = giftContextMap.material;
				}
			}

			public Dictionary<string, object> Serialize()
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("Id", Id);
				dictionary.Add("ConsumableItemDesc", ConsumableItemDesc);
				dictionary.Add("AvatarItemDesc", AvatarItemDesc);
				dictionary.Add("EquipmentPrefabName", EquipmentPrefabName);
				dictionary.Add("EquipmentModificationGuid", EquipmentModificationGuid);
				dictionary.Add("CurrencyType", (int)CurrencyType);
				dictionary.Add("Currency", Currency);
				dictionary.Add("Xp", Xp);
				dictionary.Add("Level", Level);
				dictionary.Add("Platform", (int)Platform);
				dictionary.Add("GiftContext", (int)GiftContext);
				dictionary.Add("GiftRarity", (int)GiftRarity);
				dictionary.Add("Message", Message);
				return dictionary;
			}
		}

