		private const string AVATAR_API = "api/avatar/";

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action<GiftPackage, bool> m_GiftPackageReceivedEvent;

		public static Dictionary<int, SavedOutfit> LocalSavedOutfits = new Dictionary<int, SavedOutfit>();

		private static bool localAvatarSaveInProgress = false;

		private static bool localAvatarSaveRequested = false;

		public static List<GiftPackage> GiftPackages { get; private set; }

		public static Avatar LocalAvatar { get; private set; }

		public static event Action<GiftPackage, bool> GiftPackageReceivedEvent
		{
			add
			{
				Action<GiftPackage, bool> action = Avatars.m_GiftPackageReceivedEvent;
				Action<GiftPackage, bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref Avatars.m_GiftPackageReceivedEvent, (Action<GiftPackage, bool>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<GiftPackage, bool> action = Avatars.m_GiftPackageReceivedEvent;
				Action<GiftPackage, bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref Avatars.m_GiftPackageReceivedEvent, (Action<GiftPackage, bool>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public static void Initialize()
		{
			Notifications.RegisterHandler(Notifications.PushNotificationId.GiftPackageReceived, OnGiftPackageReceived);
			Notifications.RegisterHandler(Notifications.PushNotificationId.GiftPackageReceivedImmediate, OnGiftPackageReceivedImmediate);
		}

		private static bool IsGiftPackageUsable(GiftPackage package)
		{
			return package != null && package.IsValid && package.SupportsCurrentPlatform && GiftPackages != null && !GiftPackages.Any((GiftPackage g) => g.Id == package.Id);
		}

		private static void OnGiftPackageReceived(Dictionary<string, object> messageDict)
		{
			ParseGiftPackageReceived(messageDict, immediate: false);
		}

		private static void OnGiftPackageReceivedImmediate(Dictionary<string, object> messageDict)
		{
			ParseGiftPackageReceived(messageDict, immediate: true);
		}

		private static void ParseGiftPackageReceived(Dictionary<string, object> messageDict, bool immediate)
		{
			try
			{
				GiftPackage giftPackage = Util.Deserialize<GiftPackage>(messageDict);
				if (IsGiftPackageUsable(giftPackage))
				{
					GiftPackages.Add(giftPackage);
					if (Avatars.GiftPackageReceivedEvent != null)
					{
						Avatars.GiftPackageReceivedEvent(giftPackage, arg2: true);
					}
					if (immediate && Player.LocalPlayerExists && SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Gift package received!", giftPackage.Message, 3f);
					}
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static IEnumerator DowloadGiftPackages(Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v2/gifts", "api/avatar/");
			return Core.Get(requestUri, executeSerially: false).ExpectListResponse<GiftPackage>().HandleWithCallback(delegate(string error, List<GiftPackage> newGifts)
			{
				if (string.IsNullOrEmpty(error))
				{
					GiftPackages = newGifts.Where((GiftPackage g) => g.SupportsCurrentPlatform).ToList();
					Core.SafeInvoke(callback, null);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to download gifts: " + error);
					Core.SafeInvoke(callback, "Failed to download gifts");
				}
			});
		}

		public static IEnumerator LocalRequestGiftPackage(GiftManager.GiftContext context, GiftManager.GiftContext? alternateContext, bool isGameGift, Core.ApiCallback<GiftPackage> callback)
		{
			string requestUri = string.Format("{0}v2/gifts/generate", "api/avatar/");
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			int num = (int)context;
			dictionary.Add("GiftContext", num.ToString());
			dictionary.Add("IsGameGift", isGameGift.ToString());
			if (alternateContext.HasValue)
			{
				dictionary.Add("AlternateGiftContext", ((int)alternateContext.Value/*cast due to .constrained prefix*/).ToString());
			}
			GiftPackageVariant.GiftContextMapping giftContextMap = null;
			SingletonMonoBehaviour<GiftManager>.Instance.GetPackageVariantByContext(context, out giftContextMap);
			if (giftContextMap != null && !string.IsNullOrEmpty(giftContextMap.label))
			{
				dictionary.Add("Message", giftContextMap.label);
			}
			return Core.Post(requestUri, dictionary, executeSerially: false).ExpectResponse<GiftPackage>().HandleWithCallback(delegate(string error, GiftPackage newGift)
			{
				ProcessRequestGiftPackageResponse(error, newGift, callback);
			});
		}

		private static void ProcessRequestGiftPackageResponse(string error, GiftPackage newGift, Core.ApiCallback<GiftPackage> callback)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (!newGift.IsValid)
				{
					Core.SafeInvoke(callback, newGift.ErrorMessage, null);
				}
				else if (GiftPackages.Any((GiftPackage g) => g.Id == newGift.Id))
				{
					Core.SafeInvoke(callback, "Generated duplicate gift!", null);
				}
				else if (!newGift.SupportsCurrentPlatform)
				{
					UnityEngine.Debug.LogError("Generated a gift which this platform does not support!");
					Core.SafeInvoke(callback, "Generated a gift which this platform does not support!", null);
				}
				else
				{
					GiftPackages.Add(newGift);
					Core.SafeInvoke(callback, null, newGift);
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to generate new gift: " + error);
				Core.SafeInvoke(callback, "Failed to generate new gift.", null);
			}
		}

		public static IEnumerator LocalConsumeGiftPackage(GiftPackage gift, Core.ApiCallback callback)
		{
			if (gift.Consumed)
			{
				yield break;
			}
			string requestUri = string.Format("{0}v2/gifts/consume/", "api/avatar/");
			Dictionary<string, string> formData = new Dictionary<string, string>
			{
				{
					"Id",
					gift.Id.ToString()
				},
				{
					"UnlockedLevel",
					gift.Level.ToString()
				}
			};
			gift.Consumed = true;
			int index = GiftPackages.FindIndex((GiftPackage g) => g.Id == gift.Id);
			if (index >= 0 && index < GiftPackages.Count)
			{
				GiftPackages.RemoveAt(index);
				yield return Core.Post(requestUri, formData, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
				{
					if (string.IsNullOrEmpty(error))
					{
						Core.SafeInvoke(callback, null);
						AnalyticsHelper.GiftConsumed(gift);
					}
					else
					{
						UnityEngine.Debug.LogErrorFormat("Failed to consume gift {0} : {1}", gift.Id, error);
						Core.SafeInvoke(callback, error);
					}
				});
			}
			else
			{
				Core.SafeInvoke(callback, "Gift is missing from the list.");
			}
		}

		public static IEnumerator DowloadUnlockedAvatarItems(Core.ApiCallback<List<OutfitSelection>> callback)
		{
			string requestUri = string.Format("{0}v3/items", "api/avatar/");
			yield return Core.Get(requestUri, executeSerially: false).ExpectListResponse<UnlockedAvatarItem>().HandleWithCallback(delegate(string error, List<UnlockedAvatarItem> items)
			{
				if (string.IsNullOrEmpty(error))
				{
					List<OutfitSelection> list = new List<OutfitSelection>(items.Count);
					foreach (UnlockedAvatarItem item in items)
					{
						OutfitSelection outfitSelection = OutfitSelection.Parse(item.AvatarItemDesc);
						if (outfitSelection != null)
						{
							outfitSelection.Level = item.UnlockedLevel;
							outfitSelection.IsPlatformLocked = !item.PlatformMask.SupportsCurrentPlatform();
							list.Add(outfitSelection);
						}
					}
					Core.SafeInvoke(callback, null, list);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to download unlocked avatar items: " + error);
					Core.SafeInvoke(callback, "Failed to download unlocked avatar items", null);
				}
			});
		}

		public static IEnumerator DowloadSavedOutfitSlots(Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v3/saved", "api/avatar/");
			return Core.Get(requestUri, executeSerially: false).ExpectListResponse<SavedOutfit>().HandleWithCallback(delegate(string error, List<SavedOutfit> items)
			{
				if (string.IsNullOrEmpty(error))
				{
					foreach (SavedOutfit item in items)
					{
						LocalSavedOutfits[item.Slot] = item;
					}
					Core.SafeInvoke(callback, null);
				}
				else
				{
					Core.SafeInvoke(callback, "Failed to download saved outfits : " + error);
				}
			});
		}

		public static IEnumerator UpdateSavedOutfit(SavedOutfit savedOutfit, Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v3/saved/set", "api/avatar/");
			return Core.Post(requestUri, savedOutfit, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (LocalSavedOutfits.ContainsKey(savedOutfit.Slot))
					{
						LocalSavedOutfits.Remove(savedOutfit.Slot);
					}
					LocalSavedOutfits[savedOutfit.Slot] = savedOutfit;
					Core.SafeInvoke(callback, null);
				}
				else
				{
					Core.SafeInvoke(callback, "Failed to save outfit ");
				}
			});
		}

		public static IEnumerator DownloadLocalAvatar(Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v2", "api/avatar/");
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<Avatar>().HandleWithCallback(delegate(string error, Avatar avatar)
			{
				if (string.IsNullOrEmpty(error))
				{
					LocalAvatar = avatar;
					PlayerOutfit.ApplyLocalPlayerAvatarSettings(avatar);
					Core.SafeInvoke(callback, null);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to load Rec Room player avatar settings: " + error);
					Core.SafeInvoke(callback, "Failed to load Rec Room player avatar settings");
				}
			});
		}

		public static void SaveLocalAvatarSettings()
		{
			if (localAvatarSaveInProgress)
			{
				localAvatarSaveRequested = true;
				return;
			}
			localAvatarSaveRequested = false;
			string requestUri = string.Format("{0}v2/set", "api/avatar/");
			Core.Post(requestUri, LocalAvatar, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string wwwError)
			{
				localAvatarSaveInProgress = false;
				if (!string.IsNullOrEmpty(wwwError))
				{
					UnityEngine.Debug.LogError("Failed to upload Rec Room player avatar changes: " + wwwError);
					localAvatarSaveRequested = true;
				}
				if (localAvatarSaveRequested)
				{
					SaveLocalAvatarSettings();
				}
			});
		}
	}
	public static class BugReporting
	{
		[Serializable]
		private class BugReportDTO
		{
			public string Summary;

			public string Description;

			public string TestCaseKey;
		}

		public const string MIMETYPE_TXT_PLAIN = "text/plain";

		private const string BUG_REPORTING_API = "api/bugreporting/";

		public static IPromise ReportBug(string summary, string description, byte[] screenshotData, byte[] outputLogData, string testCaseKey)
		{
			string requestUri = string.Format("{0}v1/reportbug", "api/bugreporting/");
			HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
			BugReportDTO bugReportDTO = new BugReportDTO();
			bugReportDTO.Summary = summary;
			bugReportDTO.Description = description;
			bugReportDTO.TestCaseKey = testCaseKey;
			BugReportDTO obj = bugReportDTO;
			hTTPMultiPartForm.AddField("bugReport", JsonUtility.ToJson(obj), Encoding.UTF8);
			int? num = screenshotData?.Length;
			if (num.HasValue && num.GetValueOrDefault() > 0)
			{
				hTTPMultiPartForm.AddBinaryData("screenshotData", screenshotData, "screenshot.png", "image/png");
			}
			int? num2 = outputLogData?.Length;
			if (num2.HasValue && num2.GetValueOrDefault() > 0)
			{
				hTTPMultiPartForm.AddBinaryData("outputLogData", outputLogData, "output_log.txt", "text/plain");
			}
			return Core.Post(requestUri, hTTPMultiPartForm).ExpectHttpStatusSuccess();
		}
	}
