		public static void UpdateChallengeProgress(int mapId, RecNetChallenge challenge)
		{
			string text = ((challenge.ChallengeDefinition == null) ? null : AmplitudeMiniJSON.Json.Serialize(challenge.ChallengeDefinition.Serialize()).Trim());
			if (text != null)
			{
				string requestUri = string.Format("{0}v2/updateProgress", "api/challenge/");
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				dictionary.Add("ChallengeMapId", mapId.ToString());
				dictionary.Add("ChallengeId", challenge.ChallengeId.ToString());
				dictionary.Add("Config", text);
				dictionary.Add("Complete", challenge.ChallengeDefinition.Complete.ToString());
				Core.Post(requestUri, AmplitudeMiniJSON.Json.Serialize(dictionary)).ExpectHttpStatusSuccess().LogErrors("Failed to update objective");
			}
			else
			{
				UnityEngine.Debug.LogError("Trying to update null challenge");
			}
		}
