	public class ChatThread : IRecNetObject, IEquatable<ChatThread>
	{
		private string cachedChatName = string.Empty;

		public long ChatThreadId { get; set; }

		public long LastReadMessageId { get; set; }

		public List<ChatMessage> Messages { get; set; }

		public List<int> PlayerIds { get; set; }

		public bool MayNeedNewFetch { get; set; }

		public long MessagesUpToDateThroughMessageID { get; set; }

		private string chatThreadName { get; set; }

		private DateTime? snoozedUntil { get; set; }

		public bool IsSnoozed
		{
			get
			{
				if (snoozedUntil.HasValue)
				{
					return DateTime.Compare(snoozedUntil.Value, DateTime.UtcNow) > 0;
				}
				return false;
			}
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			ChatThreadId = Util.GetKey<long>("ChatThreadId", dict);
			chatThreadName = Util.GetKey<string>("ChatThreadName", dict);
			LastReadMessageId = Util.GetKey<long>("LastReadMessageId", dict);
			snoozedUntil = Util.GetDateTimeKeyOrDefault("SnoozedUntil", dict);
			if (dict.ContainsKey("Messages"))
			{
				Messages = Util.GetObjectListKey<ChatMessage>("Messages", dict);
				SortMessagesReverseChronological(Messages);
				MayNeedNewFetch = false;
				MessagesUpToDateThroughMessageID = Messages.First().ChatMessageId;
			}
			else
			{
				Messages = new List<ChatMessage> { Util.GetObjectKey<ChatMessage>("LatestMessage", dict) };
				MayNeedNewFetch = true;
				MessagesUpToDateThroughMessageID = -1L;
			}
			PlayerIds = Util.GetListKey<int>("PlayerIds", dict);
			GetChatName(forceRefresh: true);
		}

		public void SetSnoozedUntil(DateTime? endTime)
		{
			snoozedUntil = endTime;
		}

		public string GetChatName(bool forceRefresh = false)
		{
			if (!string.IsNullOrEmpty(chatThreadName))
			{
				return chatThreadName;
			}
			if (forceRefresh)
			{
				IEnumerable<int> enumerable = PlayerIds.Where((int id) => id != (int)(long)Profiles.LocalProfile.Id);
				List<string> list = new List<string>();
				foreach (int item in enumerable)
				{
					Relationship relationship = Relationships.Get(item);
					list.Add(string.Format("{0}{1}", GetPlayerName(item), (relationship == null || !relationship.IsBlocked) ? string.Empty : " [Blocked]"));
				}
				cachedChatName = string.Join(", ", list.ToArray());
			}
			return cachedChatName;
		}

		public string GetPlayerName(int profileId)
		{
			Profile profile = Profiles.Get(profileId);
			if (profile != null)
			{
				return profile.DisplayName;
			}
			return "[Unknown]";
		}

		public void Update(ChatThread chat)
		{
			if (chat.ChatThreadId == ChatThreadId)
			{
				chatThreadName = chat.chatThreadName;
				PlayerIds = chat.PlayerIds;
				LastReadMessageId = chat.LastReadMessageId;
				MayNeedNewFetch = chat.MayNeedNewFetch;
				if (!chat.MayNeedNewFetch)
				{
					MessagesUpToDateThroughMessageID = chat.Messages.First().ChatMessageId;
				}
				else
				{
					MessagesUpToDateThroughMessageID = -1L;
				}
				Messages = chat.Messages;
				SortMessagesReverseChronological(Messages);
			}
		}

		public static void SortMessagesReverseChronological(List<ChatMessage> messsages)
		{
			messsages.Sort((ChatMessage m1, ChatMessage m2) => m2.ChatMessageId.CompareTo(m1.ChatMessageId));
		}

		public override bool Equals(object obj)
		{
			return Equals(obj as ChatThread);
		}

		public bool Equals(ChatThread other)
		{
			return other != null && other.ChatThreadId == ChatThreadId;
		}

		public static bool operator !=(ChatThread ct1, ChatThread ct2)
		{
			if (object.ReferenceEquals(ct1, null))
			{
				return !object.ReferenceEquals(ct2, null);
			}
			return !ct1.Equals(ct2);
		}

		public static bool operator ==(ChatThread ct1, ChatThread ct2)
		{
			if (object.ReferenceEquals(ct1, null))
			{
				return object.ReferenceEquals(ct2, null);
			}
			return ct1.Equals(ct2);
		}

		public override int GetHashCode()
		{
			return ChatThreadId.GetHashCode();
		}
	}
