			SenderPlayerId = Util.GetKey<int>("SenderPlayerId", dict);
			TimeSent = Util.GetDateTimeKey("TimeSent", dict);
			Contents = Util.GetKey<string>("Contents", dict);
			IsSystemMessage = SenderPlayerId == -5;
			Chats.MessageJson messageJson = JsonUtility.FromJson<Chats.MessageJson>(Contents);
			if (messageJson == null || !Chats.IsSupportedVersion(messageJson.Version) || messageJson.Type != Chats.MessageContentType.Text || messageJson.Data == null)
