			{
				return !object.ReferenceEquals(cm2, null);
			}
			return !cm1.Equals(cm2);
		}

		public static bool operator ==(ChatMessage cm1, ChatMessage cm2)
		{
			if (object.ReferenceEquals(cm1, null))
			{
				return object.ReferenceEquals(cm2, null);
			}
			return cm1.Equals(cm2);
		}

