		public enum MessageContentType
		{
			Text
		}

		[Serializable]
		public class MessageJson
		{
			public MessageContentType Type;

			public int Version;

			public string Data;
		}

		public class TextMessageJson : MessageJson
		{
			public bool IsSytemMessage;

			private List<long> missingProfiles = new List<long>();

			private List<long> missingRooms = new List<long>();

			public string FormattedText { get; set; }

			public List<DisplayCardData> DisplayCardData { get; set; }

			public bool HasDisplayCards => DisplayCardData != null && DisplayCardData.Count > 0;

			public void AddMissingProfile(long id)
			{
				if (missingProfiles.Count == 0)
				{
					Profiles.OnProfileUpdated += ProfileUpdated;
				}
				missingProfiles.Add(id);
			}

			public void AddMissingRoom(long id)
			{
				if (missingRooms.Count == 0)
				{
					Rooms.OnRoomDetailsUpdated += RoomDetailsUpdated;
				}
				missingRooms.Add(id);
			}

			public void ProfileUpdated(long id)
			{
				if (missingProfiles.Contains(id))
				{
					missingProfiles.Remove(id);
					UpdateFormattedText();
					if (missingProfiles.Count == 0)
					{
						Profiles.OnProfileUpdated -= ProfileUpdated;
					}
				}
			}

			public void RoomDetailsUpdated(long id)
			{
				if (missingRooms.Contains(id))
				{
					missingRooms.Remove(id);
					UpdateFormattedText();
					if (missingRooms.Count == 0)
					{
						Rooms.OnRoomDetailsUpdated -= RoomDetailsUpdated;
					}
				}
			}

			public void UpdateFormattedText()
			{
				TextMessageJson textMessageJson = GenerateTextMessageJsonFromData(Data, Version, IsSytemMessage);
				FormattedText = textMessageJson.FormattedText;
				DisplayCardData = textMessageJson.DisplayCardData;
			}

			~TextMessageJson()
			{
				Profiles.OnProfileUpdated -= ProfileUpdated;
				Rooms.OnRoomDetailsUpdated -= RoomDetailsUpdated;
			}
		}

