				{
					chatUpdatedCallback2 = chatUpdatedCallback;
					chatUpdatedCallback = Interlocked.CompareExchange(ref Chats.m_OnChatUpdated, (ChatUpdatedCallback)Delegate.Combine(chatUpdatedCallback2, value), chatUpdatedCallback);
				}
				while (chatUpdatedCallback != chatUpdatedCallback2);
			}
			remove
			{
				ChatUpdatedCallback chatUpdatedCallback = Chats.m_OnChatUpdated;
				ChatUpdatedCallback chatUpdatedCallback2;
				do
				{
					chatUpdatedCallback2 = chatUpdatedCallback;
					chatUpdatedCallback = Interlocked.CompareExchange(ref Chats.m_OnChatUpdated, (ChatUpdatedCallback)Delegate.Remove(chatUpdatedCallback2, value), chatUpdatedCallback);
