		}

		public static void Initialize()
		{
			Notifications.OnConnect += OnPushNotificationChannelConnected;
			Notifications.RegisterHandler(Notifications.PushNotificationId.ChatMessageReceived, OnSubscriptionUpdateChat);
		}

		private static void OnPushNotificationChannelConnected()
		{
			foreach (ChatThread value2 in chatCache.Values)
			{
				if (!value2.MayNeedNewFetch)
				{
					value2.MessagesUpToDateThroughMessageID = value2.Messages.First().ChatMessageId;
					value2.MayNeedNewFetch = true;
				}
			}
			string requestUri = new RecNetUrlBuilder("api/chat/", 2, "myChats").WithQueryParam("mode", 0).WithQueryParam("count", 50).Build();
			Core.Get(requestUri, executeSerially: false).ExpectListResponse<ChatThread>().Then(delegate(List<ChatThread> recentChats)
			{
				foreach (ChatThread recentChat in recentChats)
				{
					ChatThread value = null;
					if (chatCache.TryGetValue(recentChat.ChatThreadId, out value))
					{
						long chatMessageId = recentChat.Messages.First().ChatMessageId;
						if (value.MessagesUpToDateThroughMessageID == chatMessageId)
						{
							value.MayNeedNewFetch = false;
						}
						else
						{
							long chatMessageId2 = value.Messages.First().ChatMessageId;
							value.Update(recentChat);
							if (chatMessageId2 != chatMessageId)
							{
								SafeRaiseChatUpdated(value);
							}
						}
					}
					else
					{
						chatCache[recentChat.ChatThreadId] = recentChat;
					}
				}
			})
				.Error(delegate(string error)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to GetNextNChats: {0}", error);
				});
		}

		private static void OnSubscriptionUpdateChat(Dictionary<string, object> message)
		{
			try
			{
				ChatMessage message2 = Util.Deserialize<ChatMessage>(message);
				AddMessageToChatThread(message2);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static void StoreChatsInCache(IEnumerable<ChatThread> chats)
		{
			foreach (ChatThread chat in chats)
			{
				StoreChatInCache(chat);
			}
		}

		private static void StoreChatInCache(ChatThread newChat)
		{
			if (!(newChat == null))
			{
				if (chatCache.TryGetValue(newChat.ChatThreadId, out var value))
				{
					value.Update(newChat);
				}
				else
				{
					chatCache[newChat.ChatThreadId] = newChat;
				}
			}
		}

