		public static IPromise<ChatResults> ReadMessage(long chatId, long messageId)
		{
			if (chatCache.TryGetValue(chatId, out var cachedChat))
			{
				if (cachedChat.LastReadMessageId != messageId)
				{
					long oldLastReadId = cachedChat.LastReadMessageId;
					cachedChat.LastReadMessageId = messageId;
					string requestUri = string.Format("{0}v1/readMessage", "api/chat/");
					ReadMessageRequest readMessageRequest = new ReadMessageRequest();
					readMessageRequest.ChatId = chatId;
					readMessageRequest.MessageId = messageId;
					string json = JsonUtility.ToJson(readMessageRequest);
					return Core.Post(requestUri, json, executeSerially: false).ExpectResponse<ModifyChatResponse>().ContinueWith((ModifyChatResponse response) => response.ChatResult)
						.Then(delegate(ChatResults chatResults)
						{
							if (chatResults != ChatResults.Success)
							{
								cachedChat.LastReadMessageId = oldLastReadId;
								UnityEngine.Debug.LogErrorFormat("Failed to ReadMessage: {0}", chatResults);
							}
						})
						.Error(delegate(string error)
						{
							cachedChat.LastReadMessageId = oldLastReadId;
							UnityEngine.Debug.LogErrorFormat("Failed to ReadMessage: {0}", error);
						});
				}
				return new Promise<ChatResults>().Complete(ChatResults.Success);
			}
			return new Promise<ChatResults>().Complete(ChatResults.ThreadNotFound);
		}

