		public static IPromise<ChatResults> SnoozeChat(long chatId, bool snooze)
		{
			if (chatCache.TryGetValue(chatId, out var cachedChat))
			{
				if ((cachedChat.IsSnoozed && snooze) || (!cachedChat.IsSnoozed && !snooze))
				{
					return new Promise<ChatResults>().Complete(ChatResults.Success);
				}
				string requestUri = string.Format("{0}v1/snoozeChat", "api/chat/");
				SnoozeChatRequest snoozeChatRequest = new SnoozeChatRequest();
				snoozeChatRequest.ChatId = chatId;
				snoozeChatRequest.Snooze = snooze;
				string json = JsonUtility.ToJson(snoozeChatRequest);
				return Core.Post(requestUri, json, executeSerially: false).ExpectResponse<SnoozeChatReponse>().ContinueWith(delegate(SnoozeChatReponse response)
				{
					if (response.ChatResult == ChatResults.Success)
					{
						cachedChat.SetSnoozedUntil(response.SnoozedUntil);
					}
					return response.ChatResult;
				})
					.Error(delegate(string error)
					{
						UnityEngine.Debug.LogErrorFormat("Failed to SnoozeChat: {0}", error);
					});
			}
			return new Promise<ChatResults>().Complete(ChatResults.ThreadNotFound);
		}

