		private static void AddDisplayCardData(TextMessageJson msg, MarkupReplacementType type, long id)
		{
			if (msg.DisplayCardData == null)
			{
				msg.DisplayCardData = new List<DisplayCardData>();
			}
			msg.DisplayCardData.Add(new DisplayCardData
			{
				ReplacementType = type,
				Id = id
			});
		}

		public static TextMessageJson GenerateTextMessageJsonFromData(string messageData, int version, bool isSystemMessage)
		{
			TextMessageJson textMessageJson = new TextMessageJson();
			textMessageJson.Type = MessageContentType.Text;
			textMessageJson.Version = version;
			textMessageJson.Data = messageData;
			textMessageJson.IsSytemMessage = isSystemMessage;
			textMessageJson.FormattedText = messageData;
			textMessageJson.DisplayCardData = new List<DisplayCardData>();
			TextMessageJson textMessageJson2 = textMessageJson;
			if (version != 1)
			{
				UnityEngine.Debug.LogError("Unknown text message version!");
				return textMessageJson2;
			}
			List<StringReplaceData> list = new List<StringReplaceData>();
			StringReplaceData stringReplaceData = null;
			for (int i = 0; i < messageData.Length; i++)
			{
				if (stringReplaceData == null)
				{
					if (messageData[i] != '<')
					{
						continue;
					}
					if (i + 2 >= messageData.Length)
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					stringReplaceData = new StringReplaceData();
					if (messageData[i + 1] == '@' && messageData[i + 2] == 'U')
					{
						stringReplaceData.Type = MarkupReplacementType.Username;
						stringReplaceData.StartIdx = i;
						i += 2;
						continue;
					}
					if (messageData[i + 1] != '^' || messageData[i + 2] != 'R')
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					stringReplaceData.Type = MarkupReplacementType.Roomname;
					stringReplaceData.StartIdx = i;
					i += 2;
				}
				else if (messageData[i] == '|')
				{
					if (stringReplaceData.PipeData != null)
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					stringReplaceData.PipeIdx = i;
					int num = stringReplaceData.StartIdx + 3;
					int num2 = i - num;
					if (num2 <= 0)
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					stringReplaceData.DataString = messageData.Substring(num, num2);
				}
				else
				{
					if (messageData[i] != '>')
					{
						continue;
					}
					if (stringReplaceData.PipeIdx >= 0)
					{
						int num3 = stringReplaceData.PipeIdx + 1;
						int num4 = i - num3;
						if (num4 <= 0)
						{
							UnityEngine.Debug.LogError("Unknown text message format!");
							return textMessageJson2;
						}
						stringReplaceData.PipeData = messageData.Substring(num3, num4);
					}
					else
					{
						int num5 = stringReplaceData.StartIdx + 3;
						int num6 = i - num5;
						if (num6 <= 0)
						{
							UnityEngine.Debug.LogError("Unknown text message format!");
							return textMessageJson2;
						}
						stringReplaceData.DataString = messageData.Substring(num5, num6);
					}
					stringReplaceData.EndIdx = i;
					stringReplaceData.IsValid = true;
					list.Add(stringReplaceData);
					stringReplaceData = null;
				}
			}
			if (stringReplaceData != null)
			{
				UnityEngine.Debug.LogError("Unknown text message format!");
				return textMessageJson2;
			}
			int num7 = 0;
			StringBuilder builder = new StringBuilder();
			foreach (StringReplaceData item in list)
			{
				if (!item.IsValid)
				{
					continue;
				}
				int num8 = item.StartIdx - num7;
				if (num8 > 0)
				{
					builder.Append(messageData.Substring(num7, num8));
				}
				switch (item.Type)
				{
				case MarkupReplacementType.Username:
				{
					int output2 = 0;
					if (!SafeConvertToInt(item.DataString, out output2))
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					Profile profile = Profiles.Get(output2);
					if (profile == null)
					{
						textMessageJson2.AddMissingProfile(output2);
						if (item.PipeData != null)
						{
							builder.Append($"@{item.PipeData}");
						}
						else
						{
							builder.Append("[Unknown Player]");
						}
					}
					else
					{
						if (isSystemMessage)
						{
							builder.Append(profile.DisplayName);
							break;
						}
						builder.Append($"@{profile.Username}");
					}
					AddDisplayCardData(textMessageJson2, MarkupReplacementType.Username, output2);
					break;
				}
				case MarkupReplacementType.Roomname:
				{
					long output = 0L;
					if (!SafeConvertToLong(item.DataString, out output))
					{
						UnityEngine.Debug.LogError("Unknown text message format!");
						return textMessageJson2;
					}
					IPromise<Room> roomById = Rooms.GetRoomById(output);
					if (roomById.HasSucceeded)
					{
						roomById.Then(delegate(Room room)
						{
							builder.Append($"^{room.Name}");
						});
					}
					else
					{
						textMessageJson2.AddMissingRoom(output);
						if (item.PipeData != null)
						{
							builder.Append($"^{item.PipeData}");
						}
						else
						{
							builder.Append("[Unknown Room]");
						}
					}
					AddDisplayCardData(textMessageJson2, MarkupReplacementType.Roomname, output);
					break;
				}
				}
				num7 = item.EndIdx + 1;
			}
			if (num7 < messageData.Length)
			{
				builder.Append(messageData.Substring(num7));
			}
			string text = builder.ToString();
			textMessageJson2.FormattedText = text.Replace("&amp;", "&").Replace("&lt;", "<").Replace("&gt;", ">");
			return textMessageJson2;
		}

		private static bool SafeConvertToInt(string data, out int output)
		{
			try
			{
				output = Convert.ToInt32(data);
				return true;
			}
			catch (Exception)
			{
				output = -1;
				return false;
			}
		}

		private static bool SafeConvertToLong(string data, out long output)
		{
			try
			{
				output = Convert.ToInt64(data);
				return true;
			}
			catch (Exception)
			{
				output = -1L;
				return false;
			}
		}

		public static string ConstructTextMessageFromRaw(string rawText)
		{
			string data = ConvertRawMessageToMarkup(rawText);
			MessageJson messageJson = new MessageJson();
			messageJson.Type = MessageContentType.Text;
			messageJson.Version = 1;
			messageJson.Data = data;
			MessageJson obj = messageJson;
			return JsonUtility.ToJson(obj);
		}

		private static string ConvertRawMessageToMarkup(string rawMessage)
		{
			if (rawMessage == null || rawMessage.Length == 0)
			{
				return string.Empty;
			}
			string text = rawMessage.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;");
			List<StringReplaceData> list = new List<StringReplaceData>();
			StringReplaceData stringReplaceData = null;
			for (int i = 0; i < text.Length; i++)
			{
				if (stringReplaceData == null)
				{
					if (text[i] == '@')
					{
						StringReplaceData stringReplaceData2 = new StringReplaceData();
						stringReplaceData2.Type = MarkupReplacementType.Username;
						stringReplaceData2.StartIdx = i;
						stringReplaceData = stringReplaceData2;
					}
					else if (text[i] == '^')
					{
						StringReplaceData stringReplaceData2 = new StringReplaceData();
						stringReplaceData2.Type = MarkupReplacementType.Roomname;
						stringReplaceData2.StartIdx = i;
						stringReplaceData = stringReplaceData2;
					}
				}
				else if (IsTerminatorCharacter(text[i]) || (text[i] == '.' && (i + 1 >= text.Length || IsTerminatorCharacter(text[i + 1]))))
				{
					stringReplaceData.EndIdx = i - 1;
					stringReplaceData.DataString = text.Substring(stringReplaceData.StartIdx + 1, stringReplaceData.EndIdx - stringReplaceData.StartIdx);
					list.Add(stringReplaceData);
					stringReplaceData = null;
				}
			}
			if (stringReplaceData != null)
			{
				stringReplaceData.EndIdx = text.Length - 1;
				stringReplaceData.DataString = text.Substring(stringReplaceData.StartIdx + 1, stringReplaceData.EndIdx - stringReplaceData.StartIdx);
				list.Add(stringReplaceData);
				stringReplaceData = null;
			}
			if (list.Count == 0)
			{
				return text;
			}
			foreach (StringReplaceData markupGroup in list)
			{
				switch (markupGroup.Type)
				{
				case MarkupReplacementType.Username:
				{
					IPromise<Profile> playerByUsername = Profiles.GetPlayerByUsername(markupGroup.DataString);
					if (playerByUsername.HasSucceeded)
					{
						playerByUsername.Then(delegate(Profile profile)
						{
							markupGroup.Identifier = profile.Id;
							markupGroup.IsValid = true;
						});
					}
					break;
				}
				case MarkupReplacementType.Roomname:
				{
					IPromise<Room> roomByName = Rooms.GetRoomByName(markupGroup.DataString);
					if (roomByName.HasSucceeded)
					{
						roomByName.Then(delegate(Room room)
						{
							markupGroup.Identifier = room.RoomId;
							markupGroup.IsValid = true;
						});
					}
					break;
				}
				}
			}
			int num = 0;
			StringBuilder stringBuilder = new StringBuilder();
			foreach (StringReplaceData item in list)
			{
				if (item.IsValid)
				{
					int num2 = item.StartIdx - num;
					if (num2 > 0)
					{
						stringBuilder.Append(text.Substring(num, num2));
					}
					switch (item.Type)
					{
					case MarkupReplacementType.Username:
						stringBuilder.Append($"<@U{item.Identifier}|{item.DataString}>");
						break;
					case MarkupReplacementType.Roomname:
						stringBuilder.Append($"<^R{item.Identifier}|{item.DataString}>");
						break;
					}
					num = item.EndIdx + 1;
				}
			}
			if (num < text.Length)
			{
				stringBuilder.Append(text.Substring(num));
			}
			return stringBuilder.ToString();
		}

		public static bool IsTerminatorCharacter(char c)
		{
			return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == '?' || c == '!';
		}

		private static void AddMessageToChatThread(ChatMessage message)
		{
			GetChatById(message.ThreadId, message.IsSystemMessage).Then(delegate(ChatThread chat)
			{
				if (chat != null)
				{
					AddMessageToChatThread(chat, message);
					SafeRaiseChatUpdated(chat);
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Could not find thread id {0} for message id {1}", message.ThreadId, message.ChatMessageId);
				}
			});
		}

		private static void AddMessageToChatThread(ChatThread chatThread, ChatMessage message)
		{
			if (!chatThread.Messages.Contains(message))
			{
				chatThread.Messages.Add(message);
				ChatThread.SortMessagesReverseChronological(chatThread.Messages);
			}
		}

		private static void SafeRaiseChatUpdated(ChatThread chatThread)
		{
			try
			{
				if (Chats.OnChatUpdated != null)
				{
					Chats.OnChatUpdated(chatThread);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
