	public class PlayerCheering
	{
		public enum CheerCategory
		{
			General = 0,
			Helpful = 10,
			Sportmanship = 20,
			GreatHost = 30,
			Creative = 40
		}

		private const string CHEER_API = "api/PlayerCheer/";

		private static readonly float CHEER_LIMIT_SECONDS = 60f;

		private static Dictionary<long, float> cheeredPlayerIds = new Dictionary<long, float>();

		public static bool CanCreateCheer(long playerId)
		{
			return !cheeredPlayerIds.ContainsKey(playerId) || cheeredPlayerIds[playerId] + CHEER_LIMIT_SECONDS < UnityEngine.Time.unscaledTime;
		}

		public static IEnumerator CreateCheer(long playerId, CheerCategory cheerCategory, bool anonymous, Core.ApiCallback<OkResponse> callback)
		{
			if (CanCreateCheer(playerId))
			{
				cheeredPlayerIds[playerId] = UnityEngine.Time.unscaledTime;
				string requestUri = string.Format("{0}v1/create", "api/PlayerCheer/");
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				dictionary.Add("PlayerIdTo", playerId.ToString());
				int num = (int)cheerCategory;
				dictionary.Add("CheerCategory", num.ToString());
				dictionary.Add("RoomId", GameSessions.LocalGameSession.RoomId.ToString());
				dictionary.Add("Anonymous", anonymous.ToString());
				return Core.Post(requestUri, dictionary).ExpectResponse<OkResponse>().HandleWithCallback(callback);
			}
			callback?.Invoke(string.Empty, new OkResponse
			{
				Success = false,
				Message = "You have already cheered this player very recently."
			});
			return null;
		}

		public static IEnumerator UpdateSelectedCheer(CheerCategory? cheerCategory, Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v1/SetSelectedCheer", "api/PlayerCheer/");
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			if (cheerCategory.HasValue)
			{
				dictionary.Add("CheerCategory", ((int)cheerCategory.Value/*cast due to .constrained prefix*/).ToString());
			}
			else
			{
				dictionary.Add("CheerCategory", string.Empty);
			}
			return Core.Post(requestUri, dictionary).ExpectHttpStatusSuccess().HandleWithCallback(callback);
		}
	}
