		public static IPromise<string> GetVideoClipURL(string videoName)
		{
			string text = "/video/" + videoName;
			string result = string.Concat(Config.CdnBaseUri, text);
			return new CompletedPromise<string>(result);
		}

		private static string SaveToFile(string filePath, byte[] bytes)
		{
			try
			{
				using (FileStream fileStream = File.Open(filePath, FileMode.Create))
				{
					fileStream.Write(bytes, 0, bytes.Length);
				}
				return filePath;
			}
			catch (Exception arg)
			{
				UnityEngine.Debug.LogError($"Error creating local file for video {filePath}: {arg}");
			}
			return null;
		}

		private static IPromise<byte[]> DownloadVideoBytes(string requestUri)
		{
			return Core.GetFromCDN(requestUri).ContinueWith<byte[]>(delegate(HTTPResponse response)
			{
				if (response.StatusCode == 404 || response.StatusCode == 204)
				{
					return new CompletedPromise<byte[]>(null);
				}
				if (response.StatusCode >= 400)
				{
					string text = "Failed to download video: HTTP Error " + response.StatusCode;
					UnityEngine.Debug.LogError(text);
					return new ErroredPromise<byte[]>(text);
				}
				return new CompletedPromise<byte[]>(response.Data);
			});
		}

		private static void DeletePreviouslyDownloadedVideos()
		{
			string path = Path.Combine(UnityEngine.Application.persistentDataPath, "videos");
			if (!Directory.Exists(path))
			{
				return;
			}
			DirectoryInfo directoryInfo = new DirectoryInfo(path);
			FileInfo[] files = directoryInfo.GetFiles("*.mp4");
			FileInfo[] array = files;
			foreach (FileInfo file in array)
			{
				if (Current?.Videos.Any((CommunityBoardVideoData v) => v.BlobName + ".mp4" == file.Name) == false)
				{
					file.Delete();
				}
			}
		}
	}
