			MatchmakingParams = Util.GetObjectKey<MatchmakingConfigParams>("MatchmakingParams", dict);
			ServerMaintenance = Util.GetObjectKey<ServerMaintenanceDTO>("ServerMaintenance", dict);
			LevelProgressionMap = new Dictionary<int, int>();
			List<object> list = dict["LevelProgressionMaps"] as List<object>;
			for (int i = 0; i < list.Count; i++)
			{
				Dictionary<string, object> dict2 = list[i] as Dictionary<string, object>;
				LevelProgressionMap.Add(Util.GetKey<int>("Level", dict2), Util.GetKey<int>("RequiredXp", dict2));
			}
			List<object> list2 = dict["DailyObjectives"] as List<object>;
			DailyObjectives = new ProgressionManager.Objective[list2.Count][];
			for (int j = 0; j < list2.Count; j++)
			{
				List<object> list3 = list2[j] as List<object>;
				DailyObjectives[j] = new ProgressionManager.Objective[list3.Count];
				for (int k = 0; k < list3.Count; k++)
				{
					Dictionary<string, object> dict3 = list3[k] as Dictionary<string, object>;
					DailyObjectives[j][k] = new ProgressionManager.Objective
					{
						ObjectiveType = (ProgressionManager.ObjectiveType)Util.GetKey<int>("type", dict3),
						RequiredScore = Util.GetKey<int>("score", dict3)
					};
				}
			}
			PhotonConfig = Util.GetObjectKey<PhotonConfig>("PhotonConfig", dict);
		}
