			if (!string.IsNullOrEmpty(ConsumableType) && NetworkedSingletonMonoBehaviour<ConsumableManager>.IsInitialized)
			{
				ConsumableItem = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(ConsumableType);
			}
			Category = ((!(ConsumableItem != null)) ? ConsumableManager.Category.Invalid : ConsumableItem.Category);
		}

