		private static void OnConsumableMappingAdded(Dictionary<string, object> message)
		{
			try
			{
				Consumable consumable = Util.Deserialize<Consumable>(message);
				if (!(consumable != null))
				{
					return;
				}
				if (consumable.IsPlatformLocked)
				{
					if (Consumables.OnPlatformLockedConsumableReceived != null)
					{
						Consumables.OnPlatformLockedConsumableReceived();
					}
				}
				else
				{
					SafeRaiseConsumableAdded(consumable);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnConsumableMappingRemoved(Dictionary<string, object> message)
		{
			try
			{
				Consumable consumable = Util.Deserialize<Consumable>(message);
				if (consumable != null)
				{
					SafeRaiseConsumableRemoved(consumable.Id);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static IEnumerator DowloadUnlockedConsumables(Core.ApiCallback<List<Consumable>> callback)
		{
			string requestUri = string.Format("{0}v1/getUnlocked", "api/consumables/");
			yield return Core.Get(requestUri, executeSerially: false).ExpectListResponse<Consumable>().HandleWithCallback(delegate(string error, List<Consumable> items)
			{
				if (string.IsNullOrEmpty(error))
				{
					List<Consumable> list = items.RemoveAllWhere((Consumable s) => s.IsPlatformLocked);
					if (list.Count > 0 && Consumables.OnPlatformLockedConsumableReceived != null)
					{
						Consumables.OnPlatformLockedConsumableReceived();
					}
					Core.SafeInvoke(callback, null, items);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to download unlocked Consumables: " + error);
					Core.SafeInvoke(callback, "Failed to download unlocked Consumables", null);
				}
			});
		}

		public static IEnumerator ActivateConsumable(Consumable consumable, bool isActive, Core.ApiCallback callback)
		{
			if (consumable.Count <= 0)
			{
				return null;
			}
			if (consumable != null)
			{
				consumable.IsActive = isActive;
			}
			string requestUri = string.Format("{0}v1/updateActive", "api/consumables/");
			ActivateConsumableItemRequest activateConsumableItemRequest = new ActivateConsumableItemRequest();
			activateConsumableItemRequest.Id = consumable.Id;
			activateConsumableItemRequest.IsActive = isActive;
			string json = JsonUtility.ToJson(activateConsumableItemRequest);
			return Core.Post(requestUri, json).ExpectHttpStatusSuccess().HandleWithCallback(callback);
		}

		public static IEnumerator UseConsumable(Consumable consumable, int deltaCount, Core.ApiCallback callback)
		{
			if (consumable.Count <= 0)
			{
				return null;
			}
			string requestUri = string.Format("{0}v1/consume", "api/consumables/");
			ConsumableItemRequest consumableItemRequest = new ConsumableItemRequest();
			consumableItemRequest.Id = consumable.Id;
			consumableItemRequest.DeltaCount = deltaCount;
			string json = JsonUtility.ToJson(consumableItemRequest);
			consumable.Count -= Mathf.Abs(deltaCount);
			return Core.Post(requestUri, json).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
			{
				if (!string.IsNullOrEmpty(error))
				{
					consumable.Count += Mathf.Abs(deltaCount);
				}
				Core.SafeInvoke(callback, error);
			});
		}

		private static void SafeRaiseConsumableAdded(Consumable consumable)
		{
