		}

		private static IPromise<HTTPResponse> CallApi(Uri baseUri, string uri, ConstructRequestCallback constructRequest, bool executeSerially)
		{
			Queue<QueuedApiCall> queue = ((!executeSerially) ? parallelQueue : serialQueue);
			return CallApi(baseUri, uri, constructRequest, queue);
		}

		private static IPromise<HTTPResponse> CallApi(Uri baseUri, string uri, ConstructRequestCallback constructRequest, Queue<QueuedApiCall> queue)
		{
			LazyInit();
			QueuedApiCall queuedApiCall = new QueuedApiCall(baseUri, uri, constructRequest);
			queue.Enqueue(queuedApiCall);
			return queuedApiCall.Promise;
		}

		private static IPromise<HTTPResponse> CallApi(Uri baseUri, string uri, AsyncConstructRequestCallback asyncConstructRequest, Queue<QueuedApiCall> queue)
		{
			LazyInit();
			QueuedApiCall queuedApiCall = new QueuedApiCall(baseUri, uri, asyncConstructRequest);
			queue.Enqueue(queuedApiCall);
			return queuedApiCall.Promise;
		}

		private static IEnumerator ProcessCallApiQueue(Queue<QueuedApiCall> queue)
		{
			int consecutiveRetries = 0;
			float previousErrorTime = 0f;
			while (true)
			{
				yield return new WaitUntil(() => queue.Count > 0);
				if (queue.Count == 0)
				{
					continue;
				}
				QueuedApiCall apiCall = queue.Dequeue();
				Uri uri = new Uri(string.Concat(apiCall.BaseUri, apiCall.Uri));
				HTTPRequest request = null;
				float apiCallDuration = 0f;
				for (int retry = 0; retry < 3; retry++)
				{
					if (request != null)
					{
						request.Dispose();
						request = null;
					}
					if (consecutiveRetries > 0)
					{
						float exponentialBackoff = GetExponentialBackoffTime(consecutiveRetries);
						float timeToWait = exponentialBackoff - (UnityEngine.Time.realtimeSinceStartup - previousErrorTime);
						if (timeToWait > 0f)
						{
							yield return new WaitForSecondsRealtime(timeToWait);
						}
					}
					float startTime = UnityEngine.Time.realtimeSinceStartup;
					if (apiCall.ConstructRequest != null)
					{
						try
						{
							request = apiCall.ConstructRequest(uri);
							if (queue == imageQueue)
							{
								request.Priority = -1;
							}
						}
						catch (Exception exception)
						{
							UnityEngine.Debug.LogException(exception);
						}
					}
					else
					{
						yield return apiCall.AsyncConstructRequest(uri, delegate(HTTPRequest result)
						{
							request = result;
						});
					}
					if (request == null)
					{
						break;
					}
					AddRecNetAuthToken(request);
					yield return request.Send();
					apiCallDuration = UnityEngine.Time.realtimeSinceStartup - startTime;
					if (request.Response == null || request.Response.StatusCode == 429 || (request.Response.StatusCode >= 500 && request.Response.StatusCode < 600))
					{
						consecutiveRetries++;
						previousErrorTime = UnityEngine.Time.realtimeSinceStartup;
						continue;
					}
					if (request.Response.StatusCode == 401)
					{
						consecutiveRetries++;
						previousErrorTime = UnityEngine.Time.realtimeSinceStartup;
					}
					else
					{
						consecutiveRetries = 0;
					}
					break;
				}
				try
				{
					string error = GetError(request, handleHttpStatusCodes: false);
					if (error == null)
					{
						apiCall.Promise.Complete(request.Response);
					}
					else
					{
						apiCall.Promise.Error(error);
					}
				}
				catch (Exception exception2)
				{
					UnityEngine.Debug.LogException(exception2);
				}
				if (request != null)
				{
					request.Dispose();
					request = null;
				}
			}
		}

		public static string GetError(HTTPRequest request, bool handleHttpStatusCodes)
		{
			if (request == null)
			{
				return "Failed to construct Web request";
			}
			switch (request.State)
			{
			case HTTPRequestStates.Aborted:
				return "Aborted";
			case HTTPRequestStates.ConnectionTimedOut:
				return "Connection timed out";
			case HTTPRequestStates.TimedOut:
				return "Response timed out";
			case HTTPRequestStates.Error:
				UnityEngine.Debug.LogException(request.Exception);
				return (request.Exception == null) ? "Unspecified error" : request.Exception.Message;
			case HTTPRequestStates.Finished:
				return (!handleHttpStatusCodes || request.Response.StatusCode < 400) ? null : ("HTTP Error " + request.Response.StatusCode);
			default:
				UnityEngine.Debug.LogError("HTTPRequest is in an invalid state: " + request.State);
				return "Unexpected state";
			}
		}

		public static void SafeInvoke(ApiCallback callback, string error)
		{
			try
			{
				callback?.Invoke(error);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static void SafeInvoke<T>(ApiCallback<T> callback, string error, T response)
		{
			try
			{
				callback?.Invoke(error, response);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static void DispatchOnUnityThread(Action callback)
		{
			lock (eventQueue)
			{
				eventQueue.Enqueue(callback);
			}
		}

		public static IEnumerator RunOnBackgroundThread(Action callback)
		{
			bool complete = false;
			Thread thread = new Thread((ThreadStart)delegate
			{
				try
				{
					callback();
				}
				catch (Exception ex)
				{
					Exception ex2 = ex;
					Exception ex3 = ex2;
					DispatchOnUnityThread(delegate
					{
						UnityEngine.Debug.LogException(ex3);
					});
				}
				finally
				{
					complete = true;
				}
			});
			thread.Start();
			return new WaitUntil(() => complete);
		}

		private static IEnumerator ProcessEventQueue()
		{
			while (true)
			{
				yield return new WaitUntil(() => eventQueue.Count > 0);
				Action callback;
				lock (eventQueue)
				{
					callback = eventQueue.Dequeue();
				}
				try
				{
					callback();
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
		}
	}
