		private const string DATABLOB_API = "api/datablob/";

		private static PromiseCache<string> cachedBlobs = new PromiseCache<string>(128, cacheErrors: false);

		public static IPromise<string> UploadTransientData(DataBlobType blobDataType, byte[] bytes, string oldBlobName = null)
		{
			GameSession localGameSession = GameSessions.LocalGameSession;
			if (localGameSession == null)
			{
				return new ErroredPromise<string>("Not in a game session.");
			}
			string requestUri = new RecNetUrlBuilder("api/datablob/", 1, "uploadtransient").WithQueryParam("blobDataType", (int)blobDataType).WithQueryParam("gameSessionId", localGameSession.GameSessionId).WithQueryParam("oldBlobName", oldBlobName)
				.Build();
			HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
			hTTPMultiPartForm.AddBinaryData("data", bytes);
			return Core.Post(requestUri, hTTPMultiPartForm).ExpectResponse<BlobNameDTO>().ContinueWith((BlobNameDTO response) => response.BlobName)
				.Then(delegate(string name)
				{
					cachedBlobs.SetValue(name, new DataBlob(name, bytes));
				});
		}

		public static void RemoveDataFromCache(string blobName)
		{
			cachedBlobs.Remove(blobName);
		}

		public static void ClearEntireDataCache()
		{
			cachedBlobs.Clear();
		}

		public static IPromise<DataBlob> GetData(string blobName)
		{
			return cachedBlobs.GetOrCreatePromise(blobName, delegate
			{
				string requestUri = $"/data/{Uri.EscapeDataString(blobName)}";
				return Core.GetFromCDN(requestUri).ContinueWith((Func<HTTPResponse, IPromise<DataBlob>>)delegate(HTTPResponse response)
				{
					byte[] data = response.Data;
					if (response.StatusCode >= 400)
					{
						UnityEngine.Debug.LogError("Failed to download data: HTTP Error " + response.StatusCode);
						return new ErroredPromise<DataBlob>("Failed to download data");
					}
					return (data == null || data.Length == 0) ? ((Promise<DataBlob>)new ErroredPromise<DataBlob>("No data downloaded")) : ((Promise<DataBlob>)new CompletedPromise<DataBlob>(new DataBlob(blobName, data)));
				});
			});
		}
	}
