	public class Equipments
	{
		private const string EQUIPMENT_API = "api/equipment/";

		public static IEnumerator DowloadUnlockedEquipments(Core.ApiCallback<List<Equipment>> callback)
		{
			string requestUri = string.Format("{0}v1/getUnlocked", "api/equipment/");
			yield return Core.Get(requestUri, executeSerially: false).ExpectListResponse<Equipment>().HandleWithCallback(delegate(string error, List<Equipment> items)
			{
				if (string.IsNullOrEmpty(error))
				{
					Core.SafeInvoke(callback, null, items);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to download unlocked equipments: " + error);
					Core.SafeInvoke(callback, "Failed to download unlocked items", null);
				}
			});
		}

		public static void UpdateFavorites()
		{
			if (NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance == null || NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.UnlockedEquipments == null)
			{
				return;
			}
			List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
			foreach (Equipment unlockedEquipment in NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.UnlockedEquipments)
			{
				if (unlockedEquipment.IsDirty)
				{
					list.Add(unlockedEquipment.Serialize());
					unlockedEquipment.IsDirty = false;
				}
			}
			if (list.Count > 0)
			{
				string json = AmplitudeMiniJSON.Json.Serialize(list);
				string requestUri = string.Format("{0}v1/update", "api/equipment/");
				Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to upload equipment slot updates");
			}
		}
	}
