		private const string EVENTS_API = "api/events/";

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action m_EventsUpdated;

		private static List<Event> CachedEvents = new List<Event>();

		private static float nextRefreshEventListTime = 0f;

		private const float refreshEventListInterval = 3600f;

		private static long lastEventId = 0L;

		public static event Action EventsUpdated
		{
			add
			{
				Action action = Events.m_EventsUpdated;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref Events.m_EventsUpdated, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = Events.m_EventsUpdated;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref Events.m_EventsUpdated, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private static void RemoveExpiredEvents()
		{
			while (CachedEvents.Count > 0 && CachedEvents[0].EndTime < DateTime.UtcNow)
			{
				CachedEvents.RemoveAt(0);
			}
		}

		public static Event GetNextEvent()
		{
			RemoveExpiredEvents();
			Event obj = ((CachedEvents.Count <= 0) ? null : CachedEvents[0]);
			long num = obj?.EventId ?? 0;
			if (num != lastEventId && Events.EventsUpdated != null)
			{
				lastEventId = num;
				Events.EventsUpdated();
			}
			return obj;
		}

		public static Event GetEventById(long eventId)
		{
			foreach (Event cachedEvent in CachedEvents)
			{
				if (cachedEvent.EventId == eventId)
				{
					return cachedEvent;
				}
			}
			return null;
		}

		public static IPromise RefreshEventList()
		{
			if (UnityEngine.Time.time > nextRefreshEventListTime)
			{
				nextRefreshEventListTime = UnityEngine.Time.time + 3600f;
				string requestUri = string.Format("{0}v3/list", "api/events/");
				return Core.Get(requestUri, executeSerially: false).ExpectListResponse<Event>().Then(delegate(List<Event> events)
				{
					CachedEvents.Clear();
					CachedEvents.AddRange(events);
					CachedEvents.Sort((Event a, Event b) => a.StartTime.CompareTo(b.StartTime));
					Event nextEvent = GetNextEvent();
					if (nextEvent != null)
					{
						Images.GetImage(nextEvent.PosterImageName, generateMipMaps: true, overrideJuniorCheck: true);
					}
				})
					.Error(delegate(string error)
					{
						UnityEngine.Debug.LogErrorFormat("Failed to download event list: {0}", error);
					});
			}
			return new CompletedPromise();
		}

		public static IEnumerator RefreshEventStatus(Event @event)
		{
			string requestUri = string.Format("{0}v1/status/{1}", "api/events/", @event.EventId);
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<EventStatusResponse>().HandleWithCallback(delegate(string error, EventStatusResponse response)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError("Unable to get event status: " + error);
					@event.Status = EventStatus.Unknown;
				}
				else
				{
					@event.Status = response.Status;
				}
			});
		}
	}
