	public static class GameConfigs
	{
		private const string GAMECONFIG_API = "api/gameconfigs/";

		private static readonly string GetAllGameConfigsRequestUri = string.Format("{0}v1/all", "api/gameconfigs/");

		private static readonly TimeSpan RefreshInterval = TimeSpan.FromHours(1.0);

		private static DateTime timeLastRefresh = DateTime.MinValue;

		private static ILookup<string, GameConfig> lookup;

		public static string Get(string key)
		{
			RefreshAsync();
			if (lookup != null && lookup.Contains(key))
			{
				DateTime now = DateTime.UtcNow;
				return (from item in lookup[key].Where(delegate(GameConfig item)
					{
						int result;
						if (item.StartTime.HasValue)
						{
							DateTime? startTime = item.StartTime;
							if (!startTime.HasValue || !(startTime.GetValueOrDefault() <= now))
							{
								result = 0;
								goto IL_0087;
							}
						}
						if (item.EndTime.HasValue)
						{
							DateTime? endTime = item.EndTime;
							result = ((endTime.HasValue && endTime.GetValueOrDefault() > now) ? 1 : 0);
						}
						else
						{
							result = 1;
						}
						goto IL_0087;
						IL_0087:
						return (byte)result != 0;
					})
					select item.Value).FirstOrDefault();
			}
			UnityEngine.Debug.LogWarningFormat("GameConfig not found: \"{0}\"", key);
			return null;
		}

		public static IPromise<bool> RefreshAsync()
		{
			DateTime utcNow = DateTime.UtcNow;
			if (utcNow - timeLastRefresh > RefreshInterval)
			{
				timeLastRefresh = utcNow;
				return GetAllAsync().Then(delegate(List<GameConfig> list)
				{
					lookup = list.ToLookup((GameConfig item) => item.Key);
				}).Error(delegate
				{
					timeLastRefresh = DateTime.MinValue;
				}).ContinueWith((List<GameConfig> list) => true);
			}
			return new CompletedPromise<bool>(result: false);
		}

		private static IPromise<List<GameConfig>> GetAllAsync()
		{
			string getAllGameConfigsRequestUri = GetAllGameConfigsRequestUri;
			return Core.Get(getAllGameConfigsRequestUri).ExpectListResponse<GameConfig>().Error(delegate(string error)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to get all GameConfigs: {0}", error);
			});
		}
	}
