		public static GameSession UpdateCachedGameSession(GameSession gameSession)
		{
			long gameSessionId = gameSession.GameSessionId;
			if (!gameSessionCache.TryGetValue(gameSessionId, out var value) || gameSession.GameSessionsAreDifferent(value))
			{
				gameSessionCache[gameSessionId] = gameSession;
				SafeRaiseGameSessionUpdated(gameSessionId);
				return gameSession;
			}
			return value;
		}

