		private static IPromise<JoinGameErrorCode> JoinHelper(string api, BaseJoinRequest request, long[] expectedPlayerIds)
		{
			string requestUri = string.Format("{0}v3/{1}", "api/gamesessions/", api);
			request.ExpectedPlayerIds = expectedPlayerIds;
			request.RegionPings = CloudRegionPings;
			string json = JsonUtility.ToJson(request);
			return Core.Post(requestUri, json).ExpectResponse<JoinGameSessionResponse>().Error(delegate(string error)
			{
				UnityEngine.Debug.LogErrorFormat("RecNet game session join failed ({0}): {1}", api, error);
				SingletonMonoBehaviour<LocalPlayerController>.Instance.TryRevertVRMovementMode();
			})
				.ContinueWith(delegate(JoinGameSessionResponse response)
				{
					if (response.Result != JoinGameErrorCode.Success)
					{
						UnityEngine.Debug.LogWarningFormat("RecNet game session join failed ({0}): {1}", api, response.Result);
						SingletonMonoBehaviour<LocalPlayerController>.Instance.TryRevertVRMovementMode();
					}
					else
					{
						Rooms.StoreRoomDetailsInCache(response.RoomDetails);
						Presence.UpdateLocalGameSession(response.GameSession);
						SingletonMonoBehaviour<LocalPlayerController>.Instance.ClearPreSwitchRoomVRMovementMode();
					}
					return response.Result;
				});
		}

		public static IEnumerator SetGameInProgress(bool inProgress)
		{
			if (LocalGameSession.GameInProgress == inProgress)
			{
				return new CompletedPromise();
			}
			string requestUri = string.Format("{0}v2/setinprogress", "api/gamesessions/");
			SetInProgressRequest setInProgressRequest = new SetInProgressRequest();
			setInProgressRequest.GameSessionId = LocalGameSession.GameSessionId;
			setInProgressRequest.InProgress = inProgress;
			string json = JsonUtility.ToJson(setInProgressRequest);
			return Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to modify game session in-progress state");
		}

		public static void ReportGameJoinResult(GameSession gameSession, GameJoinResult result)
		{
			if (gameSession != GameSession.OfflineGameSession)
			{
				string requestUri = string.Format("{0}v2/reportjoinresult", "api/gamesessions/");
				long masterPlayerId = ((PhotonNetwork.masterClient == null) ? 0 : PhotonNetwork.masterClient.RecNetProfileId);
				ReportGameJoinResultRequest reportGameJoinResultRequest = new ReportGameJoinResultRequest();
				reportGameJoinResultRequest.GameSessionId = gameSession.GameSessionId;
				reportGameJoinResultRequest.RegionId = gameSession.PhotonRegionId.ToString();
				reportGameJoinResultRequest.RoomId = gameSession.PhotonRoomId;
				reportGameJoinResultRequest.Result = result;
				reportGameJoinResultRequest.MasterPlayerId = masterPlayerId;
				reportGameJoinResultRequest.RecRoomId = gameSession.RoomId;
				string json = JsonUtility.ToJson(reportGameJoinResultRequest);
				Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to report room join result");
			}
		}

