		public static IPromise<Group> GetGroupDetails(long groupId)
		{
			Promise<Group> promise = new Promise<Group>();
			if (groupCache.ContainsKey(groupId))
			{
				return promise.Complete(groupCache[groupId]);
			}
			GetGroupById(groupId, delegate(string error, Group result)
			{
				if (!string.IsNullOrEmpty(error))
				{
					promise.Error(error);
				}
				else if (result == null)
				{
					promise.Error("Group not found");
				}
				else
				{
					promise.Complete(result);
				}
			});
			return promise;
