		private static IEnumerator DeleteGroup(long groupId, Core.ApiCallback<StatusResponse> callback)
		{
			string requestUri = string.Format("{0}v1/delete/{1}", "api/groups/", groupId);
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("GroupId", groupId.ToString());
			return Core.Post(requestUri, dictionary).ExpectResponse<StatusResponse>().HandleWithCallback(ProcessStatusResponse("delete", delegate(string error, StatusResponse response)
			{
				if (response != null && response.Status == GroupRequestStatus.Success)
