				}
				else if (response.Status != GroupRequestStatus.Success)
				{
					UnityEngine.Debug.LogWarningFormat("RecNet group call failed ({0}): {1}", api, response.Status);
				}
				Core.SafeInvoke(callback, error, response);
			};
