		public class ProfileImagePromise : Promise<Texture2D>, IProfileImagePromise
		{
			private Texture2D DefaultProfileTexture => (!(SingletonMonoBehaviour<SessionManager>.Instance != null)) ? null : SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;

			public ProfileImagePromise(IPromise<Texture2D> getImagePromise)
			{
				if (getImagePromise != null)
				{
					getImagePromise.Error(delegate
					{
						Complete(DefaultProfileTexture);
					}).Then(delegate(Texture2D image)
					{
						Complete(image ?? DefaultProfileTexture);
					});
				}
				else
				{
					Complete(DefaultProfileTexture);
				}
			}

			IProfileImagePromise IProfileImagePromise.Then(Action<Texture2D> action)
			{
				Then(action);
				if (!base.IsCompleted)
				{
					action(DefaultProfileTexture);
				}
				return this;
			}
		}

