		public static IPromise<string> UploadShareCamImage(ShareCamImage shareCamImage)
		{
			string requestUri = string.Format("{0}v3/uploadsaved", "api/images/");
			shareCamImage.imageMeta.accessibility = SavedImageAccessibility.Public;
			HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
			hTTPMultiPartForm.AddBinaryData("image", shareCamImage.mainImage, null, "image/jpeg");
			hTTPMultiPartForm.AddBinaryData("altimage", shareCamImage.altImage, null, "image/jpeg");
			hTTPMultiPartForm.AddField("imgMeta", JsonUtility.ToJson(shareCamImage.imageMeta), Encoding.UTF8);
			return Core.PostUsingBackgroundImageUploadQueue(requestUri, hTTPMultiPartForm).ExpectResponse<ImageNameDTO>().ContinueWith((ImageNameDTO response) => response.ImageName)
				.Then(delegate(string imageName)
				{
					bool flag = Profiles.LocalProfile == null || (bool)Profiles.LocalProfile.JuniorProfile;
					string imageRequestUri = GetImageRequestUri(imageName, overrideJuniorCheck: false, null, cropSquare: false);
				});
		}

		public static IPromise<string> UploadSavedImage(AltTextureSet imageSet, SavedImageType savedImageType, List<int> playerIds = null, bool expectsAltImage = true, bool uploadAsJpg = true)
		{
			return imageSet.EncodeAsync(uploadAsJpg, expectsAltImage).ContinueWith(delegate(Tuple<byte[], byte[]> encodeResult)
			{
				byte[] item = encodeResult.Item1;
				byte[] item2 = encodeResult.Item2;
				SavedImageMetaDTO savedImageMetaDTO = new SavedImageMetaDTO
				{
					playerIds = playerIds,
					savedImageType = savedImageType,
					roomId = GameSessions.LocalGameSession.RoomId,
					playerEventId = ((!GameSessions.LocalGameSession.PlayerEventId.HasValue) ? (-1) : GameSessions.LocalGameSession.PlayerEventId.Value),
					accessibility = SavedImageAccessibility.Private
				};
				if (savedImageType == SavedImageType.ShareCamera)
				{
					return UploadShareCamImage(new ShareCamImage
					{
						mainImage = item,
						altImage = item2,
						imageMeta = savedImageMetaDTO
					});
				}
				string text = ((!expectsAltImage) ? "uploadsavedsingle" : "uploadsaved");
				string requestUri = new RecNetUrlBuilder("api/images/", 3, text).Build();
				string mimeType = ((!uploadAsJpg) ? "image/png" : "image/jpeg");
				HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
				hTTPMultiPartForm.AddBinaryData("image", item, null, mimeType);
				if (expectsAltImage)
				{
					hTTPMultiPartForm.AddBinaryData("altimage", item2, null, mimeType);
				}
				hTTPMultiPartForm.AddField("imgMeta", JsonUtility.ToJson(savedImageMetaDTO), Encoding.UTF8);
				return Core.Post(requestUri, hTTPMultiPartForm).ExpectResponse<ImageNameDTO>().ContinueWith((ImageNameDTO response) => response.ImageName)
					.Then(delegate(string imageName)
					{
						bool flag = Profiles.LocalProfile == null || (bool)Profiles.LocalProfile.JuniorProfile;
						string imageRequestUri = GetImageRequestUri(imageName, overrideJuniorCheck: false, null, cropSquare: false);
					});
			});
		}

