		public static IPromise<string> UploadTransientImage(AltTextureSet imageSet, string oldImageName = null, bool expectsAltImage = true, bool uploadAsJpg = false)
		{
			return imageSet.EncodeAsync(uploadAsJpg, expectsAltImage).ContinueWith(delegate(Tuple<byte[], byte[]> encodeResult)
			{
				byte[] item = encodeResult.Item1;
				byte[] item2 = encodeResult.Item2;
				GameSession localGameSession = GameSessions.LocalGameSession;
				if (localGameSession == null)
				{
					return new ErroredPromise<string>("Not in a game session");
				}
				string text = ((!expectsAltImage) ? "uploadtransientsingle" : "uploadtransient");
				string requestUri = new RecNetUrlBuilder("api/images/", 4, text).WithQueryParam("gameSessionId", localGameSession.GameSessionId).WithQueryParam("oldImageName", oldImageName).Build();
				string mimeType = ((!uploadAsJpg) ? "image/png" : "image/jpeg");
				HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
				hTTPMultiPartForm.AddBinaryData("image", item, null, mimeType);
				if (expectsAltImage)
				{
					hTTPMultiPartForm.AddBinaryData("altimage", item2, null, mimeType);
				}
				return Core.Post(requestUri, hTTPMultiPartForm).ExpectResponse<ImageNameDTO>().ContinueWith((ImageNameDTO response) => response.ImageName);
			});
		}

