		public static IPromise SetLocalProfileImage(AltTextureSet profileImageTextureSet)
		{
			return profileImageTextureSet.EncodeAsync(encodeAsJpg: true, includeAltImage: true).ContinueWith(delegate(Tuple<byte[], byte[]> encodeResults)
			{
				byte[] content = encodeResults.Item1;
				byte[] item = encodeResults.Item2;
				if (Profiles.LocalProfile != null && (bool)Profiles.LocalProfile.ForceJuniorImages)
				{
					content = item;
