				string requestUri = string.Format("{0}v3/profile", "api/images/");
				HTTPMultiPartForm hTTPMultiPartForm = new HTTPMultiPartForm();
				hTTPMultiPartForm.AddBinaryData("image", content, null, "image/jpeg");
				hTTPMultiPartForm.AddBinaryData("altimage", item, null, "image/jpeg");
				return Core.Post(requestUri, hTTPMultiPartForm).ExpectHttpStatusSuccess();
			});
		}

