		private static bool IsValidProfileToDownload(Profile profile)
		{
			return profile != null && profile.Verified && !string.IsNullOrEmpty(profile.ProfileImageName) && !Relationships.IsIgnored(profile.Id);
		}

		private static void OnProfileUpdated(long id)
		{
			Profile profile = Profiles.Get(id);
			if (!string.IsNullOrEmpty(profile.ProfileImageName))
			{
				profileImageNameToProfileId[profile.ProfileImageName] = profile.Id;
			}
			if (Notifications.IsSubscribed(id))
			{
				PrecacheProfileImage(id);
			}
		}

		private static void OnSubscriptionsAdded(List<long> profileIds)
		{
			foreach (long profileId in profileIds)
			{
				PrecacheProfileImage(profileId);
			}
		}

		private static bool TryGetProfileIdFromImageName(string imageName, out long profileId)
		{
			if (profileImageNameToProfileId.TryGetValue(imageName, out profileId))
			{
				Profile profile = Profiles.Get(profileId);
				if (profile != null && profile.ProfileImageName == (ObscuredString)imageName)
				{
					return true;
				}
				profileImageNameToProfileId.Remove(imageName);
			}
			profileId = 0L;
			return false;
		}

