		{
			string requestUri = string.Format("{0}v2/named", "api/images/");
			return Core.Get(requestUri, executeSerially: false).ExpectListResponse<NamedImageDTO>().Then(delegate(List<NamedImageDTO> response)
			{
				namedImages = response;
			})
				.Error(delegate(string error)
				{
					UnityEngine.Debug.LogError("Failed to download named image list: " + error);
				});
		}

		public static IPromise<Texture2D> GetNamedImage(string imageName, bool generateMipMaps = true)
		{
			NamedImageDTO namedImageDTO = namedImages.Where((NamedImageDTO n) => n.FriendlyImageName == imageName && n.StartTime < DateTime.UtcNow && n.EndTime > DateTime.UtcNow).FirstOrDefault();
			if (namedImageDTO == null)
			{
				return new CompletedPromise<Texture2D>(null);
			}
			return GetImage(namedImageDTO.ImageName, generateMipMaps, overrideJuniorCheck: true).Then(delegate(Texture2D texture)
			{
				if (texture != null)
				{
					texture.name = imageName;
				}
			});
		}

