		public static void ClearEntireImageCache()
		{
			cachedImages.Clear();
			cachedImageBytes.Clear();
		}

		public static IPromise<Texture2D> GetImage(string imageName, bool generateMipMaps = true, bool overrideJuniorCheck = false, uint? resizeWidth = null, bool cropSquare = false)
		{
			string requestUri = GetImageRequestUri(imageName, overrideJuniorCheck, resizeWidth, cropSquare);
			return cachedImages.GetOrCreatePromise(requestUri, () => cachedImageBytes.GetOrCreatePromise(requestUri, () => DownloadImageBytes(requestUri)).ContinueWith((byte[] imageBytes) => LoadTexture(imageName, imageBytes, generateMipMaps)).Finally(delegate
			{
				cachedImageBytes.Remove(requestUri);
			}));
		}

		private static string GetImageRequestUri(string imageName, bool overrideJuniorCheck, uint? resizeWidth, bool cropSquare)
		{
			StringBuilder stringBuilder = new StringBuilder();
			if ((Profiles.LocalProfile == null || (bool)Profiles.LocalProfile.JuniorProfile) && !overrideJuniorCheck)
			{
				stringBuilder.Append("alt/");
			}
			stringBuilder.Append(Uri.EscapeDataString(imageName));
			List<KeyValuePair<string, string>> list = new List<KeyValuePair<string, string>>();
			if (resizeWidth.HasValue)
			{
				list.Add(new KeyValuePair<string, string>("width", resizeWidth.Value.ToString()));
			}
			if (cropSquare)
			{
				list.Add(new KeyValuePair<string, string>("cropSquare", "1"));
			}
			for (int i = 0; i < list.Count; i++)
			{
				stringBuilder.AppendFormat("{0}{1}={2}", (i != 0) ? "&" : "?", list[i].Key, list[i].Value);
			}
			return stringBuilder.ToString();
		}

		private static IPromise<byte[]> DownloadImageBytes(string requestUri)
		{
			return Core.GetFromImageCDN(requestUri).ContinueWith<byte[]>(delegate(HTTPResponse response)
			{
				if (response.StatusCode == 404 || response.StatusCode == 204)
				{
					return new CompletedPromise<byte[]>(null);
				}
				if (response.StatusCode >= 400)
				{
					string text = "Failed to download image: HTTP Error " + response.StatusCode;
					UnityEngine.Debug.LogError(text);
					return new ErroredPromise<byte[]>(text);
				}
				return new CompletedPromise<byte[]>(response.Data);
			});
		}

		private static Texture2D LoadTexture(string imageName, byte[] imageBytes, bool generateMipMaps)
		{
			Texture2D texture2D = null;
			if (imageBytes != null)
			{
				texture2D = new Texture2D(0, 0, TextureFormat.RGBA32, generateMipMaps);
				texture2D.name = imageName;
				texture2D.LoadImage(imageBytes);
			}
			return texture2D;
		}

		private static void PrecacheImage(string imageName, bool overrideJuniorCheck = false, uint? resizeWidth = null, bool cropSquare = false)
		{
			string requestUri = GetImageRequestUri(imageName, overrideJuniorCheck, resizeWidth, cropSquare);
			if (!cachedImages.ContainsKey(requestUri))
			{
				cachedImageBytes.GetOrCreatePromise(requestUri, () => DownloadImageBytes(requestUri));
			}
		}
	}
