		public static string GetResponseCodeFriendlyMessage(InventionResult result)
		{
			return result switch
			{
				InventionResult.Success => "Success!", 
				InventionResult.PlayerCannotUpload => "Your account is currently restricted from uploading new inventions.", 
				InventionResult.DuplicateName => "You already have an invention with this name. Please choose a different name.", 
				InventionResult.NameTooShort => "Invention name is too short.", 
				InventionResult.NameTooLong => "Invention name is too long.", 
				InventionResult.NotOwner => "You do not own this invention.", 
				InventionResult.DoesNotExist => "You do not own this invention.", 
				InventionResult.ImageDoesNotExist => "Images does not exist.", 
				InventionResult.InventionLimitReached => "You have already saved the maximum number of inventions. Delete existing inventions to save more.", 
				InventionResult.DescriptionTooLong => "Invention description is too long.", 
				InventionResult.InnapropriateName => "Invention name cannot be used. Please choose a different name.", 
				InventionResult.InnapropriateDescription => "Invention description cannot be used. Please try a different description.", 
				InventionResult.CannotBeModified => "Invention is locked for modifications.", 
				_ => "Error updating invention. If this persists, please contact us at support@againstgrav.com", 
			};
		}

		public static IPromise<InventionResponse> UploadNewInvention(byte[] data, string name, string description, string imageName, int instantiateCost, string[] imageList, string[] dataBlobList)
		{
			if (data == null || data.Length == 0 || string.IsNullOrWhiteSpace(name) || string.IsNullOrWhiteSpace(imageName))
			{
				return new ErroredPromise<InventionResponse>("Invalid params for uploading invention");
			}
			if (description == null)
			{
				description = string.Empty;
			}
			string requestUri = string.Format("{0}v1/save", "api/inventions/");
			WWWForm wWWForm = new WWWForm();
			wWWForm.AddBinaryData("data", data);
			NewInventionRequestDTO newInventionRequestDTO = new NewInventionRequestDTO();
			newInventionRequestDTO.name = name;
			newInventionRequestDTO.description = description;
			newInventionRequestDTO.imageName = imageName;
			newInventionRequestDTO.instantiationCost = instantiateCost;
			newInventionRequestDTO.referencedImages = new List<string>(imageList);
			newInventionRequestDTO.referencedData = new List<string>(dataBlobList);
			NewInventionRequestDTO obj = newInventionRequestDTO;
			wWWForm.AddField("newInventionRequest", JsonUtility.ToJson(obj), Encoding.UTF8);
			return Core.Post(requestUri, wWWForm).ExpectResponse<InventionResponse>().Then((Action)delegate
			{
				Cache.InvalidateEntry(GetMyInventionRequestUri);
				if (Inventions.OnNewInventionUploaded != null)
				{
					Inventions.OnNewInventionUploaded();
				}
			});
		}

		public static IPromise<InventionResponse> AddInventionVersion(byte[] data, long inventionId, int newInstantiateCost, string[] imageList, string[] dataBlobList)
		{
			string requestUri = string.Format("{0}v1/addversion?inventionId={1}", "api/inventions/", inventionId);
			WWWForm wWWForm = new WWWForm();
			wWWForm.AddBinaryData("data", data);
			AddVersionInventionRequestDTO addVersionInventionRequestDTO = new AddVersionInventionRequestDTO();
			addVersionInventionRequestDTO.instantiationCost = newInstantiateCost;
			addVersionInventionRequestDTO.referencedImages = new List<string>(imageList);
			addVersionInventionRequestDTO.referencedData = new List<string>(dataBlobList);
			AddVersionInventionRequestDTO obj = addVersionInventionRequestDTO;
			wWWForm.AddField("newVersionRequest", JsonUtility.ToJson(obj), Encoding.UTF8);
			return Core.Post(requestUri, wWWForm).ExpectResponse<InventionResponse>().Then(delegate(InventionResponse response)
			{
				if (response.Status == InventionResult.Success)
				{
					Cache.InvalidateEntry(GetMyInventionRequestUri);
					AddEntryToInventionCache(response.Invention);
					AddEntryToInventionCache(response.InventionVersion);
				}
			});
		}

