		public static IPromise<Invention> GetInvention(long inventionId)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(inventionId, out value))
			{
				return new CompletedPromise<Invention>(value.invention);
			}
			string requestUri = string.Format("{0}v1?inventionId={1}", "api/inventions/", inventionId);
			return Core.Get(requestUri).ExpectResponse<Invention>();
		}

		public static Invention GetInventionCached(long inventionId)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(inventionId, out value))
			{
				return value.invention;
			}
			return null;
		}

		public static IPromise<byte[]> GetInventionData(long inventionId, int versionNum)
		{
			return GetInventionVersion(inventionId, versionNum).ContinueWith(delegate(InventionVersion inventionVersion)
			{
				if (inventionVersion == null)
				{
					return new ErroredPromise<byte[]>("Invention version not found");
				}
				return string.IsNullOrEmpty(inventionVersion.BlobName) ? new ErroredPromise<byte[]>("Missing permission to access data") : GetInventionData(inventionVersion.BlobName);
			});
		}

		public static IPromise<byte[]> GetInventionData(string dataBlobName)
		{
			if (cachedInventionData.ContainsKey(dataBlobName))
			{
				return cachedInventionData[dataBlobName];
			}
			string requestUri = $"/invention/{Uri.EscapeDataString(dataBlobName)}";
			IPromise<byte[]> promise = Core.GetFromCDN(requestUri).ContinueWith((HTTPResponse response) => response.Data);
			cachedInventionData[dataBlobName] = promise;
			promise.Error(delegate
			{
				cachedInventionData.Remove(dataBlobName);
			});
			return promise;
		}

		public static IPromise<InventionVersion> GetInventionVersion(long inventionId, int versionNum)
		{
			InventionVersion inventionVersion = CheckCacheForVersionData(inventionId, versionNum);
			if (inventionVersion != null)
			{
				return new CompletedPromise<InventionVersion>(inventionVersion);
			}
			string requestUri = string.Format("{0}v1/version?inventionId={1}&version={2}", "api/inventions/", inventionId, versionNum);
			return Core.Get(requestUri).ExpectResponse<InventionVersion>().Then(delegate(InventionVersion response)
			{
				AddEntryToInventionCache(response);
			});
		}

		public static IPromise<List<InventionVersion>> GetVersionsForInvention(long inventionId)
		{
			string requestUri = string.Format("{0}v1/versions?inventionId={1}", "api/inventions/", inventionId);
			return Core.Get(requestUri).ExpectListResponse<InventionVersion>().Then(delegate(List<InventionVersion> response)
			{
				foreach (InventionVersion item in response)
				{
					AddEntryToInventionCache(item);
				}
			});
		}

		public static IPromise<InventionResponse> DeleteInvention(long inventionId)
		{
			string requestUri = string.Format("{0}v1/delete?inventionId={1}", "api/inventions/", inventionId);
			return Core.Get(requestUri).ExpectResponse<InventionResponse>().Then(delegate(InventionResponse response)
			{
				if (response.Status == InventionResult.Success)
				{
					RemoveInventionFromCache(inventionId);
					Cache.InvalidateEntry(GetMyInventionRequestUri);
					if (Inventions.OnInventionUpdated != null)
					{
						Inventions.OnInventionUpdated(inventionId);
					}
					if (Inventions.OnInventionDeleted != null)
					{
						Inventions.OnInventionDeleted(inventionId);
					}
				}
			});
		}

		private static void AddEntriesToInventionsCache(List<Invention> inventions)
		{
			foreach (Invention invention in inventions)
			{
				AddEntryToInventionCache(invention);
			}
		}

		private static void AddEntryToInventionCache(Invention invention)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(invention.InventionId, out value))
			{
				value.invention = invention;
			}
			else
			{
				InventionCacheData inventionCacheData = new InventionCacheData();
				inventionCacheData.invention = invention;
				inventionCacheData.versions = new Dictionary<int, InventionVersion>();
				value = inventionCacheData;
				cachedInventions[invention.InventionId] = value;
			}
			if (Inventions.OnInventionUpdated != null)
			{
				Inventions.OnInventionUpdated(invention.InventionId);
			}
		}

		private static void AddEntryToInventionCache(InventionVersion versionData)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(versionData.InventionId, out value))
			{
				value.versions[versionData.VersionNumber] = versionData;
			}
			else
			{
				UnityEngine.Debug.LogWarning("Tried to cache invention version data without invention. This is unexpected.");
			}
			if (Inventions.OnInventionUpdated != null)
			{
				Inventions.OnInventionUpdated(versionData.InventionId);
			}
		}

		private static bool RemoveInventionFromCache(long inventionId)
		{
			return cachedInventions.Remove(inventionId);
		}

		private static Invention CheckCacheForInvention(long inventionId)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(inventionId, out value))
			{
				return value.invention;
			}
			return null;
		}

		private static InventionVersion CheckCacheForVersionData(long inventionId, int versionNumber)
		{
			InventionCacheData value = null;
			if (cachedInventions.TryGetValue(inventionId, out value))
			{
				InventionVersion value2 = null;
				if (value.versions.TryGetValue(versionNumber, out value2))
				{
					return value2;
				}
			}
			return null;
		}
	}
