		private const string LOGIN_API = "api/platformlogin/";

		public static readonly string LockToken = Guid.NewGuid().ToString();

		private static HashSet<long> cachedProfileIds = new HashSet<long>();

		public static string AccessToken { get; private set; }

		public static bool FirstLoginOfTheDay { get; private set; }

		public static bool HasCompetingPlatformCachedLogin { get; private set; }

		public static void Initialize()
		{
			Notifications.RegisterHandler(Notifications.PushNotificationId.RefreshLogin, OnRefreshLogin);
		}

		public static IEnumerator DownloadCachedLoginProfiles(Core.ApiCallback<List<Profile>> callback)
		{
			string requestUri = string.Format("{0}v1/getcachedlogins", "api/platformlogin/");
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("Platform", ((int)SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform/*cast due to .constrained prefix*/).ToString());
			dictionary.Add("PlatformId", SingletonMonoBehaviour<PlatformManager>.Instance.PlatformProfileId.ToString());
			return Core.Post(requestUri, dictionary).ExpectListResponse<Profile>().HandleWithCallback(delegate(string error, List<Profile> profiles)
			{
				if (string.IsNullOrEmpty(error))
				{
					Profiles.StoreProfilesInCache(profiles);
					cachedProfileIds = new HashSet<long>(((IEnumerable<Profile>)profiles).Select((Func<Profile, long>)((Profile p) => p.Id)));
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to retrieve cached login profiles: " + error);
					error = "Failed to load Rec Room accounts";
				}
				Core.SafeInvoke(callback, error, profiles);
			});
		}

		public static bool IsLoginCached()
		{
			return cachedProfileIds.Contains(Core.LocalProfileId);
		}

		public static IEnumerator RemoveCachedLogin(Core.ApiCallback callback = null)
		{
			string requestUri = string.Format("{0}v1/removecachedlogin", "api/platformlogin/");
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("Platform", ((int)SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform/*cast due to .constrained prefix*/).ToString());
			dictionary.Add("PlatformId", SingletonMonoBehaviour<PlatformManager>.Instance.PlatformProfileId.ToString());
			return Core.Post(requestUri, dictionary).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
			{
				if (string.IsNullOrEmpty(error))
				{
					cachedProfileIds.Remove(Core.LocalProfileId);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to remove cached login: " + error);
					error = "Failed to remove cached login";
				}
				Core.SafeInvoke(callback, error);
			});
		}

		private static void OnRefreshLogin(Dictionary<string, object> message)
		{
			if (AccessToken != null)
			{
				RefreshLogin();
			}
		}

		public static IEnumerator RefreshLogin()
		{
			string requestUri = string.Format("{0}v1/refreshlogin", "api/platformlogin/");
			return Core.Get(requestUri).ExpectResponse<RefreshLoginResponse>().HandleWithCallback(delegate(string error, RefreshLoginResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					AccessToken = response.Token;
					if (string.IsNullOrEmpty(response.Token))
					{
						error = "RecNet refused to refresh login token. Attempting to quit game.";
						UnityEngine.Debug.LogError(error);
						UnityEngine.Application.Quit();
					}
					else
					{
						UnityEngine.Debug.LogWarning("REFRESHED TOKEN");
					}
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to refresh login token: " + error);
				}
			});
		}

