		private static IEnumerator LoginHelper(string uri, Func<BaseLoginRequest, object> genRequestCallback, bool cacheLogin, Core.ApiCallback callback)
		{
			AccessToken = null;
			long localTime = DateTime.UtcNow.Ticks;
			BaseLoginRequest baseRequest = new BaseLoginRequest
			{
				Platform = (int)SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform,
				PlatformId = SingletonMonoBehaviour<PlatformManager>.Instance.PlatformProfileId.ToString(),
				AppVersion = BuildSettings.Version,
				BuildTimestamp = BuildSettings.BuildTimestamp,
				ClientTimestamp = localTime,
				DeviceId = SystemInfo.deviceUniqueIdentifier,
				LoginLockToken = LockToken
			};
			string authParams = null;
			yield return SingletonMonoBehaviour<PlatformManager>.Instance.GetAuthParams().Then(delegate(string p)
			{
				authParams = p;
			}).Error(delegate(string e)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to get platform authentication params: {0}", e);
			});
			if (authParams == null)
			{
				Core.SafeInvoke(callback, "Unable to login (code: 2)");
				yield break;
			}
			baseRequest.AuthParams = authParams;
			string requestUri = string.Format("{0}{1}", "api/platformlogin/", uri);
			object request = genRequestCallback(baseRequest);
			string json = JsonUtility.ToJson(request);
			yield return Core.PostUsingLoginQueue(requestUri, json).ExpectResponse<LoginResponse>().Error(delegate(string error)
			{
				UnityEngine.Debug.LogError("RecNet login failed: " + error);
				Core.SafeInvoke(callback, "Unable to login (code: 3)");
			})
				.Then(delegate(LoginResponse response)
				{
					if (!string.IsNullOrEmpty(response.Error))
					{
						UnityEngine.Debug.LogError("RecNet login failed: " + response.Error);
						Core.SafeInvoke(callback, response.Error);
					}
					else
					{
						Core.SetLocalProfileId(response.Player.Id);
						Profiles.StoreProfileInCache(response.Player);
						AccessToken = response.Token;
						FirstLoginOfTheDay = response.FirstLoginOfTheDay;
						AmplitudeAnalyticsClient.SessionId = response.AnalyticsSessionId;
						HasCompetingPlatformCachedLogin = response.CachedPlatformMask.ContainsCompetingPlatforms();
						cachedProfileIds.Add(response.Player.Id);
						Presence.StartHeartbeat();
						Core.SafeInvoke(callback, null);
					}
				});
		}

		public static void Logout()
		{
			Presence.StopHeartbeat();
			if (!string.IsNullOrEmpty(AccessToken))
			{
				Uri uri = new Uri(string.Concat(Core.ApiService, string.Format("{0}v1/logout", "api/platformlogin/")));
				HTTPRequest hTTPRequest = new HTTPRequest(uri, HTTPMethods.Post);
				hTTPRequest.AddField("LoginLockToken", LockToken);
				hTTPRequest.SetHeader("Authorization", "Bearer " + AccessToken);
				hTTPRequest.Send();
				AccessToken = null;
				Core.SetLocalProfileId(0L);
			}
		}
	}
	public class Message : IRecNetObject
	{
		public enum MessageType
		{
			GameInvite = 0,
			GameInviteDeclined = 1,
			GameJoinFailed = 2,
			PartyActivitySwitch = 3,
			FriendInvite = 4,
			VoteToKick = 5,
			RequestGameInvite = 10,
			RequestGameInviteDeclined = 11,
			FriendStatusOnline = 20,
			TextMessage = 30,
			FriendRequestAccepted = 40,
			PlayerCheer = 50,
			PlayerCheerAnonymous = 51,
			RoomCoOwnerAdded = 60,
			RoomCoOwnerRemoved = 61,
			RoomCoOwnerInvited = 62,
			CreatorPublishedNewRoom = 70,
			PlayerEventInvitation = 81,
			CoachMessage = 100
		}

		public long Id { get; private set; }

		public long FromPlayerId { get; private set; }

		public DateTime SentTime { get; private set; }

		public MessageType Type { get; private set; }

		public string Data { get; private set; }

		public long? RoomId { get; private set; }

		public long? PlayerEventId { get; private set; }

		public object Details { get; private set; }

		public DateTime DeserializedAt { get; private set; }

		public static bool IsMessageTypeRecognized(Message message)
		{
			return System.Enum.IsDefined(typeof(MessageType), message.Type);
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			Id = Util.GetKey<long>("Id", dict);
			FromPlayerId = Util.GetKey<long>("FromPlayerId", dict);
			SentTime = Util.GetDateTimeKey("SentTime", dict);
			Type = (MessageType)Util.GetKey<int>("Type", dict);
			Data = Util.GetKey<string>("Data", dict);
			RoomId = Util.GetKeyOrDefault<long?>("RoomId", dict);
			PlayerEventId = Util.GetKeyOrDefault<long?>("PlayerEventId", dict);
			if (Type == MessageType.GameJoinFailed || Type == MessageType.PlayerCheer || Type == MessageType.PlayerCheerAnonymous)
			{
				Details = int.Parse(Data);
			}
			DeserializedAt = DateTime.Now;
		}
	}
