		private static IEnumerator SendMessage(long playerId, Message.MessageType messageType, string data, long? roomId, Core.ApiCallback callback = null)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("ToPlayerId", playerId.ToString());
			int num = (int)messageType;
			dictionary.Add("Type", num.ToString());
			dictionary.Add("Data", data);
			if (roomId.HasValue)
			{
				dictionary.Add("RoomId", roomId.Value.ToString());
			}
			string requestUri = string.Format("{0}v2/send", "api/messages/");
			return Core.Post(requestUri, dictionary, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(callback);
		}

		private static IEnumerator SendMessageMultiple(List<long> playerIds, Message.MessageType messageType, string data, long? roomId, Core.ApiCallback callback = null)
		{
