		}

		public static IEnumerator DeleteMessage(long messageId, Core.ApiCallback callback = null)
		{
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("Id", messageId.ToString());
			int num = MessageList.FindIndex((Message m) => m.Id == messageId);
			if (num != -1)
			{
				MessageList.RemoveAt(num);
				RaiseMessageListUpdatedEvent(UpdateType.Delete);
			}
			string requestUri = string.Format("{0}v2/delete", "api/messages/", messageId);
			return Core.Post(requestUri, dictionary, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(callback);
		}

		private static void RefreshList()
		{
			string requestUri = string.Format("{0}v2/get", "api/messages/");
			Core.Get(requestUri).ExpectListResponse<Message>().HandleWithCallback(delegate(string error, List<Message> newMessageList)
			{
				if (string.IsNullOrEmpty(error))
				{
					MessageList = newMessageList.Where(Message.IsMessageTypeRecognized).ToList();
					foreach (Message message in MessageList)
					{
						Images.PrecacheProfileImage(message.FromPlayerId);
					}
					RaiseMessageListUpdatedEvent(UpdateType.Initial);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to refresh message list: " + error);
					RefreshList();
				}
			});
		}

		private static void OnPushNotificationChannelConnected()
		{
			RefreshList();
		}

		private static void OnMessageReceived(Dictionary<string, object> messageDict)
		{
			try
			{
				Message message = Util.Deserialize<Message>(messageDict);
				if (!Message.IsMessageTypeRecognized(message))
				{
					return;
				}
				int num = MessageList.FindIndex((Message m) => m.Id == message.Id);
				if (num == -1 && !IsMessageStale(message))
				{
					if (message.Type != Message.MessageType.VoteToKick || !MessageList.Exists((Message m) => m.Type == Message.MessageType.VoteToKick && m.FromPlayerId == message.FromPlayerId))
					{
						MessageList.Insert(0, message);
					}
					RaiseMessageAddedEvent(message);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static bool IsMessageStale(Message message)
		{
			PlayerPresence playerPresence = Presence.Get(message.FromPlayerId);
			bool flag = playerPresence != null && playerPresence.GameSession != null && playerPresence.GameSession == GameSessions.LocalGameSession;
			switch (message.Type)
			{
			case Message.MessageType.FriendStatusOnline:
				return flag || (SingletonMonoBehaviour<SettingsManager>.Instance != null && !SingletonMonoBehaviour<SettingsManager>.Instance.ReceiveFriendOnlineStatusNotification);
			case Message.MessageType.VoteToKick:
				return !flag || (DateTime.Now - message.DeserializedAt).TotalSeconds > 59.0;
			case Message.MessageType.GameInvite:
			case Message.MessageType.GameInviteDeclined:
			case Message.MessageType.GameJoinFailed:
			case Message.MessageType.PartyActivitySwitch:
			case Message.MessageType.RequestGameInvite:
			case Message.MessageType.RequestGameInviteDeclined:
				return flag;
			default:
				return false;
			}
		}

		private static void RemoveStaleMessages()
		{
			int num = 0;
			while (num < MessageList.Count)
			{
				Message message = MessageList[num];
				if (IsMessageStale(message))
				{
					DeleteMessage(message.Id);
				}
				else
				{
					num++;
				}
			}
		}

		private static void OnMessageDeleted(Dictionary<string, object> messageDict)
		{
			try
			{
				long messageId = Util.GetKey<long>("Id", messageDict);
				int num = MessageList.FindIndex((Message m) => m.Id == messageId);
				if (num != -1)
				{
					MessageList.RemoveAt(num);
					RaiseMessageListUpdatedEvent(UpdateType.Delete);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void RaiseMessageAddedEvent(Message message)
		{
			try
			{
				if (Messages.OnMessageAdded != null)
				{
					Messages.OnMessageAdded(message);
				}
				Images.PrecacheProfileImage(message.FromPlayerId);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			finally
			{
				RaiseMessageListUpdatedEvent(UpdateType.Add);
			}
		}

		private static void RaiseMessageListUpdatedEvent(UpdateType updateType)
		{
			try
			{
				if (Messages.OnMessageListUpdated != null)
				{
					Messages.OnMessageListUpdated(updateType);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

