		public static IEnumerator LocalRequestPlayerBan(long playerId, PlayerReporting.ReportCategory reportCategory, Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v2/ban", "api/PlayersBanned/");
			ModerationManager.ReportReasonVisual reportReasonVisual = SingletonMonoBehaviour<ModerationManager>.Instance.GetReportReasonVisual(reportCategory);
			string arg = ((reportReasonVisual == null) ? "Code of conduct violation" : reportReasonVisual.text);
			DateTime dateTime = DateTime.UtcNow.AddDays(1.0);
			string value = $"You are banned for {arg}. For any questions contact support@againstgrav.com";
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("PlayerId", playerId.ToString());
			dictionary.Add("Reason", "10");
			dictionary.Add("BanType", "0");
			dictionary.Add("DisplayReason", value);
			dictionary.Add("BannedUntil", dateTime.ToString("MM\\/dd\\/yyyy HH:mm"));
			return Core.Post(requestUri, dictionary, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError("Failed to request PlayerBan : " + error);
				}
				Core.SafeInvoke(callback, error);
			});
		}
	}
