		public static void Initialize()
		{
			Relationships.RelationshipUpdated += delegate
			{
				UpdateSubscriptions();
			};
			RecentPlayers.PlayerListUpdated += delegate
			{
				UpdateSubscriptions();
			};
		}

		public static void RegisterHandler(PushNotificationId id, NotificationHandler callback)
		{
			if (handlers.ContainsKey(id))
			{
				Dictionary<PushNotificationId, NotificationHandler> dictionary;
				PushNotificationId key;
				(dictionary = handlers)[key = id] = (NotificationHandler)Delegate.Combine(dictionary[key], callback);
			}
			else
			{
				handlers.Add(id, callback);
			}
		}

		public static bool IsSubscribed(long profileId)
		{
			return subscriptions.Contains(profileId);
		}

		private static void ReinitializeSubscriptions()
		{
			ClearSubscriptions();
			UpdateSubscriptions();
		}

		private static void ClearSubscriptions()
		{
			List<long> profileIds = subscriptions.ToList();
			subscriptions.Clear();
			SafeRaiseSubscriptionsRemoved(profileIds);
		}

		private static void UpdateSubscriptions()
		{
			if (serverConnection == null || !serverConnection.IsOpen)
			{
				return;
			}
			IEnumerable<long> collection = from r in Relationships.GetAll()
				where r.IsFriendOrPendingFriend
				select r.PlayerID;
			HashSet<long> newSubscriptions = new HashSet<long>(collection);
			newSubscriptions.UnionWith(RecentPlayers.RecentPlayersNotInCurrentRoom);
			newSubscriptions.UnionWith(PhotonNetwork.otherPlayers.Select((PhotonPlayer _) => _.RecNetProfileId));
			newSubscriptions.Add(Core.LocalProfileId);
			if (!newSubscriptions.SetEquals(subscriptions))
			{
				SubscriptionList subscriptionList = new SubscriptionList();
				subscriptionList.PlayerIds = newSubscriptions.ToList();
				SubscriptionList subscriptionList2 = subscriptionList;
				serverConnection.Send("SubscribeToPlayers", subscriptionList2).Then(delegate
				{
					HashSet<long> hashSet = subscriptions;
					subscriptions = newSubscriptions;
					SafeRaiseSubscriptionsRemoved(hashSet.Except(subscriptions).ToList());
					SafeRaiseSubscriptionsAdded(subscriptions.Except(hashSet).ToList());
				}).Error(delegate(string error)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to update notification subscriptions: {0}", error);
				});
			}
		}

		public static IPromise Connect()
		{
			serverConnection = new SignalRHubConnection(new Uri($"{Core.NotificationService}hub/v1"));
			serverConnection.OnOpen = OnOpenInternal;
			serverConnection.OnClosed = OnClosedInternal;
			return serverConnection.Open();
		}

		public static void Disconnect()
		{
			if (serverConnection != null)
			{
				serverConnection.Close();
				serverConnection = null;
			}
		}

		private static void OnOpenInternal(SignalRHubConnection hub)
		{
			if (hub == serverConnection)
			{
				hub.On<string>("Notification", OnNotificationReceived);
				ReinitializeSubscriptions();
				SafeRaiseOnConnect();
			}
		}

		private static void OnClosedInternal(SignalRHubConnection hub)
		{
			if (hub == serverConnection)
			{
				ClearSubscriptions();
			}
		}

		internal static void OnNotificationReceived(string message)
		{
			try
			{
				Dictionary<string, object> dictionary = AmplitudeMiniJSON.Json.Deserialize(message) as Dictionary<string, object>;
				PushNotificationId key = (PushNotificationId)Util.GetKey<int>("Id", dictionary);
				if (handlers.TryGetValue(key, out var value))
				{
					Dictionary<string, object> message2 = (Dictionary<string, object>)dictionary["Msg"];
					value(message2);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void SafeRaiseOnConnect()
		{
			try
			{
				if (Notifications.OnConnect != null)
				{
					Notifications.OnConnect();
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void SafeRaiseSubscriptionsAdded(List<long> profileIds)
		{
			try
			{
				if (Notifications.OnSubscriptionsAdded != null && profileIds.Count != 0)
				{
					Notifications.OnSubscriptionsAdded(profileIds);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void SafeRaiseSubscriptionsRemoved(List<long> profileIds)
		{
			try
			{
				if (Notifications.OnSubscriptionsRemoved != null && profileIds.Count != 0)
				{
					Notifications.OnSubscriptionsRemoved(profileIds);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
