		public float VisualProgress { get; set; }

		public bool IsCompleted { get; set; }

		public bool IsRewarded { get; set; }

		public bool IsDirty { get; set; }

		public ObjectiveProgress()
		{
			IsDirty = false;
		}

		public ObjectiveProgress(ObjectiveProgress other)
		{
			Group = other.Group;
			Index = other.Index;
			Progress = other.Progress;
			VisualProgress = other.VisualProgress;
			IsCompleted = other.IsCompleted;
			IsRewarded = other.IsRewarded;
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			Index = Util.GetKey<int>("Index", dict);
			Group = Util.GetKey<int>("Group", dict);
			Progress = Util.GetKey<float>("Progress", dict);
			VisualProgress = Util.GetKey<float>("VisualProgress", dict);
			IsCompleted = Util.GetKey<bool>("IsCompleted", dict);
			IsRewarded = Util.GetKey<bool>("IsRewarded", dict);
		}

		public Dictionary<string, object> Serialize()
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("Index", Index);
			dictionary.Add("Group", Group);
			dictionary.Add("Progress", Progress);
			dictionary.Add("VisualProgress", VisualProgress);
			dictionary.Add("IsCompleted", IsCompleted);
			dictionary.Add("IsRewarded", IsRewarded);
			return dictionary;
		}

		public bool IsEqual(ObjectiveProgress other)
		{
			return other != null && Group == other.Group && Index == other.Index && Progress == other.Progress && VisualProgress == other.VisualProgress && IsCompleted == other.IsCompleted && IsRewarded == other.IsRewarded;
		}
	}
