	public static class Objectives
	{
		[Serializable]
		private class ObjectiveGroupRequest
		{
			public int Group;
		}

		public class MyProgress : IRecNetObject
		{
			public List<ObjectiveProgress> Objectives { get; set; }

			public List<ObjectiveGroupProgress> ObjectiveGroups { get; set; }

			public void Deserialize(Dictionary<string, object> dict)
			{
				Objectives = Util.GetObjectListKey<ObjectiveProgress>("Objectives", dict);
				ObjectiveGroups = Util.GetObjectListKey<ObjectiveGroupProgress>("ObjectiveGroups", dict);
			}
		}

		private const string OBJECTIVES_API = "api/objectives/";

		private static List<ObjectiveProgress> MyObjectives = new List<ObjectiveProgress>();

		private static List<ObjectiveGroupProgress> MyObjectiveGroups = new List<ObjectiveGroupProgress>();

		private static int numClearsQueued = 0;

		private static bool saveRequested = false;

		private static bool saveObjectivesToRecnetInProgress = false;

		public static bool HasAnyData => MyObjectiveGroups.Count > 0 || MyObjectives.Count > 0;

		public static bool SaveInProgress => saveObjectivesToRecnetInProgress;

		public static ObjectiveGroupProgress LookupCachedObjectiveGroup(int groupID)
		{
			ObjectiveGroupProgress objectiveGroupProgress = InternalLookupCachedObjectiveGroup(groupID);
			if (objectiveGroupProgress == null)
			{
				return null;
			}
			return new ObjectiveGroupProgress(objectiveGroupProgress);
		}

		private static ObjectiveGroupProgress InternalLookupCachedObjectiveGroup(int groupID)
		{
			for (int i = 0; i < MyObjectiveGroups.Count; i++)
			{
				if (MyObjectiveGroups[i].Group == groupID)
				{
					return MyObjectiveGroups[i];
				}
			}
			return null;
		}

		public static ObjectiveProgress LookupCachedObjectiveProgress(int groupID, int objectiveIndex, bool returnDefaultIfNoEntry = true)
		{
			return new ObjectiveProgress(InternalLookupCachedObjectiveProgress(groupID, objectiveIndex, returnDefaultIfNoEntry));
		}

		public static ObjectiveProgress InternalLookupCachedObjectiveProgress(int groupID, int objectiveIndex, bool returnDefaultIfNoEntry = true)
		{
			for (int i = 0; i < MyObjectives.Count; i++)
			{
				if (MyObjectives[i].Group == groupID && MyObjectives[i].Index == objectiveIndex)
				{
					return MyObjectives[i];
				}
			}
			if (returnDefaultIfNoEntry)
			{
				ObjectiveProgress objectiveProgress = new ObjectiveProgress();
				objectiveProgress.Index = objectiveIndex;
				objectiveProgress.Group = groupID;
				objectiveProgress.Progress = 0f;
				objectiveProgress.VisualProgress = 0f;
				objectiveProgress.IsCompleted = false;
				objectiveProgress.IsRewarded = false;
				return objectiveProgress;
			}
			return null;
		}

		public static IEnumerator GetMyObjectiveProgress(Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v1/myprogress", "api/objectives/");
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<MyProgress>().HandleWithCallback(delegate(string error, MyProgress response)
			{
				if (string.IsNullOrEmpty(error))
				{
					MyObjectives = response.Objectives;
					MyObjectiveGroups = response.ObjectiveGroups;
					ValidateGroups();
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Error on server call: {0}. Local objective state will not be reflected in server!", (error == null) ? string.Empty : error);
				}
				Core.SafeInvoke(callback, error);
			});
		}

		private static void ValidateGroups()
		{
			int num = 0;
			for (int i = 0; i < MyObjectives.Count; i++)
			{
				ObjectiveProgress objectiveProgress = MyObjectives[i];
				int num2 = i + 1;
				while (num2 < MyObjectives.Count)
				{
					ObjectiveProgress objectiveProgress2 = MyObjectives[num2];
					if (objectiveProgress.Index == objectiveProgress2.Index && objectiveProgress.Group == objectiveProgress2.Group)
					{
						num++;
						MyObjectives.RemoveAt(num2);
					}
					else
					{
						num2++;
					}
				}
			}
			for (int j = 0; j < MyObjectiveGroups.Count; j++)
			{
				ObjectiveGroupProgress objectiveGroupProgress = MyObjectiveGroups[j];
				int num3 = j + 1;
				while (num3 < MyObjectiveGroups.Count)
				{
					ObjectiveGroupProgress objectiveGroupProgress2 = MyObjectiveGroups[num3];
					if (objectiveGroupProgress.Group == objectiveGroupProgress2.Group)
					{
						num++;
						MyObjectiveGroups.RemoveAt(num3);
					}
					else
					{
						num3++;
					}
				}
			}
			if (num > 0)
			{
				UnityEngine.Debug.LogWarningFormat("Found {0} duplicates in objectives progress from server. Only first will be used.", num);
			}
		}

		public static void UpdateObjective(ObjectiveProgress progress)
		{
			ObjectiveProgress objectiveProgress = InternalLookupCachedObjectiveProgress(progress.Group, progress.Index);
			if (!objectiveProgress.IsEqual(progress))
			{
				MyObjectives.Remove(objectiveProgress);
				ObjectiveProgress objectiveProgress2 = new ObjectiveProgress(progress);
				objectiveProgress2.IsDirty = true;
				MyObjectives.Add(objectiveProgress2);
				Save();
			}
		}

		public static void CompleteGroup(int group)
		{
			ObjectiveGroupProgress objectiveGroupProgress = InternalLookupCachedObjectiveGroup(group);
			if (objectiveGroupProgress == null || !objectiveGroupProgress.IsCompleted)
			{
				if (objectiveGroupProgress == null)
				{
					ObjectiveGroupProgress objectiveGroupProgress2 = new ObjectiveGroupProgress();
					objectiveGroupProgress2.Group = group;
					objectiveGroupProgress2.IsCompleted = true;
					objectiveGroupProgress2.ClearedAt = DateTime.UtcNow;
					objectiveGroupProgress = objectiveGroupProgress2;
					MyObjectiveGroups.Add(objectiveGroupProgress);
				}
				else
				{
					objectiveGroupProgress.IsCompleted = true;
				}
				objectiveGroupProgress.RequiresCompleteOnServer = true;
				Save();
			}
		}

		public static IEnumerator ClearGroup(int group, Core.ApiCallback<ObjectiveGroupProgress> callback)
		{
			ObjectiveGroupProgress objectiveGroupProgress = InternalLookupCachedObjectiveGroup(group);
			if (objectiveGroupProgress == null)
			{
				ObjectiveGroupProgress objectiveGroupProgress2 = new ObjectiveGroupProgress();
				objectiveGroupProgress2.Group = group;
				objectiveGroupProgress2.IsCompleted = false;
				objectiveGroupProgress2.ClearedAt = DateTime.UtcNow;
				objectiveGroupProgress = objectiveGroupProgress2;
				MyObjectiveGroups.Add(objectiveGroupProgress);
			}
			else
			{
				objectiveGroupProgress.IsCompleted = false;
				objectiveGroupProgress.ClearedAt = DateTime.UtcNow;
			}
			for (int i = 0; i < MyObjectives.Count; i++)
			{
				ObjectiveProgress objectiveProgress = MyObjectives[i];
				if (objectiveProgress.Group == group)
				{
					objectiveProgress.IsCompleted = false;
					objectiveProgress.IsRewarded = false;
					objectiveProgress.Progress = 0f;
					objectiveProgress.VisualProgress = 0f;
					objectiveProgress.IsDirty = false;
				}
			}
			string requestUri = string.Format("{0}v1/cleargroup", "api/objectives/");
			ObjectiveGroupRequest objectiveGroupRequest = new ObjectiveGroupRequest();
			objectiveGroupRequest.Group = group;
			string json = JsonUtility.ToJson(objectiveGroupRequest);
			numClearsQueued++;
			return Core.Post(requestUri, json, executeSerially: false).ExpectResponse<ObjectiveGroupProgress>().HandleWithCallback(delegate(string error, ObjectiveGroupProgress response)
			{
				if (string.IsNullOrEmpty(error) && response != null)
				{
					ObjectiveGroupProgress objectiveGroupProgress3 = InternalLookupCachedObjectiveGroup(group);
					if (objectiveGroupProgress3 != null)
					{
						MyObjectiveGroups.Remove(objectiveGroupProgress3);
					}
					MyObjectiveGroups.Add(response);
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Error on server call: {0}. Local objective state will not be reflected in server!", (error == null) ? string.Empty : error);
				}
				numClearsQueued--;
				Core.SafeInvoke(callback, error, response);
			});
		}

		public static void Save()
		{
			saveRequested = true;
			if (!saveObjectivesToRecnetInProgress)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.StartCoroutine(RunSaveObjectivesToRecnet());
			}
		}

		private static IEnumerator RunSaveObjectivesToRecnet()
		{
			saveObjectivesToRecnetInProgress = true;
			bool dirtyFound = false;
			do
			{
				dirtyFound = false;
				saveRequested = false;
				for (int i = 0; i < MyObjectives.Count; i++)
				{
					while (numClearsQueued > 0)
					{
						yield return null;
					}
					ObjectiveProgress objective = MyObjectives[i];
					if (!objective.IsDirty)
					{
						continue;
					}
					string requestUri = string.Format("{0}v1/updateobjective", "api/objectives/");
					objective.IsDirty = false;
					yield return Core.Post(requestUri, objective, executeSerially: false).ExpectHttpStatusSuccess().HandleWithCallback(delegate(string error)
					{
						if (!string.IsNullOrEmpty(error))
						{
							objective.IsDirty = true;
							UnityEngine.Debug.LogErrorFormat("Error on server call: {0}. Local objective state will not be reflected in server!", (error == null) ? string.Empty : error);
						}
					});
					dirtyFound = true;
				}
				for (int i2 = 0; i2 < MyObjectiveGroups.Count; i2++)
				{
					while (numClearsQueued > 0)
					{
						yield return null;
					}
					ObjectiveGroupProgress group = MyObjectiveGroups[i2];
					if (!group.RequiresCompleteOnServer)
					{
						continue;
					}
					if (!group.IsCompleted)
					{
						group.RequiresCompleteOnServer = false;
						continue;
					}
					string requestUri2 = string.Format("{0}v1/completegroup", "api/objectives/");
					string jsonArgs = JsonUtility.ToJson(new ObjectiveGroupRequest
					{
						Group = group.Group
					});
					yield return Core.Post(requestUri2, jsonArgs, executeSerially: false).ExpectResponse<ObjectiveGroupProgress>().HandleWithCallback(delegate(string error, ObjectiveGroupProgress response)
					{
						if (string.IsNullOrEmpty(error) && response != null)
						{
							ObjectiveGroupProgress objectiveGroupProgress = InternalLookupCachedObjectiveGroup(response.Group);
							if (objectiveGroupProgress != null)
							{
								MyObjectiveGroups.Remove(objectiveGroupProgress);
							}
							response.RequiresCompleteOnServer = false;
							MyObjectiveGroups.Add(response);
						}
						else
						{
							UnityEngine.Debug.LogErrorFormat("Error on server call: {0}. Local objective state will not be reflected in server!", (error == null) ? string.Empty : error);
						}
					});
					dirtyFound = true;
				}
			}
			while (dirtyFound || saveRequested);
			saveObjectivesToRecnetInProgress = false;
		}
	}
