	public class LocalPlayerEventInfo : IRecNetObject
	{
		public List<PlayerEvent> Created { get; set; }

		public List<PlayerEventInformation> Responses { get; set; }

		public LocalPlayerEventInfo Sort()
		{
			SortCreatedByStartTime();
			SortResponsesByStartTime();
			return this;
		}

		public LocalPlayerEventInfo SortCreatedByStartTime()
		{
			Created.Sort((PlayerEvent a, PlayerEvent b) => a.StartTime.CompareTo(b.StartTime));
			return this;
		}

		public LocalPlayerEventInfo SortResponsesByStartTime()
		{
			Responses.Sort((PlayerEventInformation a, PlayerEventInformation b) => a.PlayerEvent.StartTime.CompareTo(b.PlayerEvent.StartTime));
			return this;
		}

		public PlayerEvent RemoveCreatedByPlayerEventId(long playerEventId)
		{
			return Created.RemoveWhere((PlayerEvent pe) => pe.PlayerEventId == playerEventId);
		}

		public PlayerEventInformation RemoveResponseByPlayerEventId(long playerEventId)
		{
			return Responses.RemoveWhere((PlayerEventInformation pei) => pei.PlayerEvent.PlayerEventId == playerEventId);
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			Created = Util.GetObjectListKey<PlayerEvent>("Created", dict);
			Responses = Util.GetObjectListKey<PlayerEventInformation>("Responses", dict);
		}
	}
