		public static IEnumerable<PlayerEvent> GetAllEventsForThisPlayerFromCache()
		{
			IEnumerable<PlayerEvent> second = EventCachePlayerIsInvolvedIn.Responses.Select((PlayerEventInformation r) => r.PlayerEvent);
			return from pe in EventCachePlayerIsInvolvedIn.Created.Union(second, new PlayerEventComparer())
				orderby pe.StartTime
				select pe;
		}

		public static IPromise<PlayerEvent> GetPlayerEventById(long playerEventId)
		{
			PlayerEvent playerEvent = EventCachePlayerIsInvolvedIn.Created.Find((PlayerEvent x) => x.PlayerEventId == playerEventId);
			if (playerEvent != null)
			{
				return new CompletedPromise<PlayerEvent>(playerEvent);
			}
			PlayerEventInformation playerEventInformation = EventCachePlayerIsInvolvedIn.Responses.Find((PlayerEventInformation x) => x.PlayerEvent.PlayerEventId == playerEventId);
			if (playerEventInformation != null)
			{
				return new CompletedPromise<PlayerEvent>(playerEventInformation.PlayerEvent);
			}
			IPromise<PlayerEvent> value = null;
			if (EventCachePlayerIsNotInvolvedIn.TryGetValue(playerEventId, out value))
			{
				return value;
			}
			string requestUri = string.Format("{0}v1/{1}", "api/playerevents/", playerEventId);
			value = Core.Get(requestUri, executeSerially: false).ExpectResponse<PlayerEvent>(treat404NotFoundAsNull: true);
			EventCachePlayerIsNotInvolvedIn[playerEventId] = value;
			return value;
		}

