		public static IPromise<CreateModifyPlayerEventResponse> ModifyEvent(PlayerEvent playerEvent, long roomId, string name, string description, DateTime startTime, DateTime endTime, PlayerEventAccessibility accessibility)
		{
			string requestUri = string.Format("{0}v2/{1}", "api/playerevents/", playerEvent.PlayerEventId);
			CreateModifyEventRequest createModifyEventRequest = new CreateModifyEventRequest();
			createModifyEventRequest.RoomId = roomId;
			createModifyEventRequest.Name = name;
			createModifyEventRequest.Description = description;
			createModifyEventRequest.StartTime = startTime;
			createModifyEventRequest.EndTime = endTime;
			createModifyEventRequest.Accessibility = accessibility;
			CreateModifyEventRequest request = createModifyEventRequest;
			return Core.Post(requestUri, request, executeSerially: false).ExpectResponse<CreateModifyPlayerEventResponse>().Then(delegate(CreateModifyPlayerEventResponse response)
			{
				if (response.Result == CreateModifyPlayerEventStatus.Success && (playerEvent.Name != name || playerEvent.StartTime != startTime || playerEvent.Accessibility != accessibility))
				{
					Cache.InvalidateEntry(GetEventsURI());
				}
			});
		}

		public static IPromise<CreateModifyPlayerEventStatus> RespondToEvent(long playerEventId, PlayerEventResponseType responseValue)
		{
			if (playerEventId < 0)
			{
				return new CompletedPromise<CreateModifyPlayerEventStatus>(CreateModifyPlayerEventStatus.DoesNotExist);
			}
			PlayerEventInformation playerEventInformation = EventCachePlayerIsInvolvedIn.Responses.Find((PlayerEventInformation x) => x.PlayerEvent.PlayerEventId == playerEventId);
			if (playerEventInformation != null && playerEventInformation.PlayerEventResponse.Type == responseValue)
			{
				return new CompletedPromise<CreateModifyPlayerEventStatus>(CreateModifyPlayerEventStatus.Success);
			}
			string requestUri = string.Format("{0}v1/respond", "api/playerevents/");
			PlayerEventResponseRequest playerEventResponseRequest = new PlayerEventResponseRequest();
			playerEventResponseRequest.PlayerEventId = playerEventId;
			playerEventResponseRequest.Type = responseValue;
			PlayerEventResponseRequest request = playerEventResponseRequest;
			return Core.Post(requestUri, request, executeSerially: false).ExpectResponse<CreateModifyPlayerEventResult>().ContinueWith((CreateModifyPlayerEventResult response) => response.Result);
		}

		public static IPromise<CreateModifyPlayerEventStatus> DeleteResponse(long playerEventId, PlayerEventResponseType responseValue)
		{
			if (playerEventId < 0)
			{
				return new CompletedPromise<CreateModifyPlayerEventStatus>(CreateModifyPlayerEventStatus.DoesNotExist);
			}
			string requestUri = string.Format("{0}v1/deleteResponse", "api/playerevents/");
			DeleteResponseRequest deleteResponseRequest = new DeleteResponseRequest();
			deleteResponseRequest.PlayerEventId = playerEventId;
			string json = JsonUtility.ToJson(deleteResponseRequest);
			return Core.Post(requestUri, json, executeSerially: false).ExpectResponse<CreateModifyPlayerEventResult>().ContinueWith((CreateModifyPlayerEventResult response) => response.Result);
		}

		public static IPromise<BulkInviteResponse> InvitePlayers(long playerEventId, List<int> invitedPlayerIds)
		{
			if (playerEventId < 0)
			{
				BulkInviteResponse bulkInviteResponse = new BulkInviteResponse();
				bulkInviteResponse.Result = CreateModifyPlayerEventStatus.DoesNotExist;
				return new CompletedPromise<BulkInviteResponse>(bulkInviteResponse);
			}
			string requestUri = string.Format("{0}v1/bulkInvite", "api/playerevents/");
			BulkInviteRequest bulkInviteRequest = new BulkInviteRequest();
			bulkInviteRequest.PlayerEventId = playerEventId;
			bulkInviteRequest.InvitedPlayerIds = invitedPlayerIds;
			string json = JsonUtility.ToJson(bulkInviteRequest);
			return Core.Post(requestUri, json, executeSerially: false).ExpectResponse<BulkInviteResponse>().Then(delegate(BulkInviteResponse response)
			{
				string requestUri2 = string.Format("{0}v1/{1}/responses", "api/playerevents/", playerEventId);
				if (response.Result == CreateModifyPlayerEventStatus.Success || response.FailedInvites.Count < invitedPlayerIds.Count)
				{
					Cache.InvalidateEntry(requestUri2);
				}
			});
		}

		public static IEnumerator DownloadPlayerEventList(Core.ApiCallback callback = null)
		{
			string requestUri = string.Format("{0}v1/all", "api/playerevents/");
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<LocalPlayerEventInfo>().HandleWithCallback(delegate(string error, LocalPlayerEventInfo events)
			{
				if (string.IsNullOrEmpty(error))
				{
					EventCachePlayerIsInvolvedIn = events.Sort();
					Core.SafeInvoke(callback, null);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to download player event list: " + error);
					Core.SafeInvoke(callback, "Failed to download player event list");
				}
			});
		}

