		private static void HandleCreateEvent(PlayerEvent playerEvent)
		{
			DateTime utcNow = DateTime.UtcNow;
			EventCachePlayerIsInvolvedIn.Created.Add(playerEvent);
			EventCachePlayerIsInvolvedIn.SortCreatedByStartTime();
			Cache.InvalidateEntry(GetEventsURI());
			if (PlayerEvents.PlayerEventCreated != null)
			{
				PlayerEvents.PlayerEventCreated(playerEvent);
			}
		}

		private static void HandleUpdateEvent(PlayerEvent playerEvent)
		{
			DateTime utcNow = DateTime.UtcNow;
			if (playerEvent.IsOrganizedByLocalPlayer)
			{
				EventCachePlayerIsInvolvedIn.RemoveCreatedByPlayerEventId(playerEvent.PlayerEventId);
				EventCachePlayerIsInvolvedIn.Created.Add(playerEvent);
			}
			PlayerEventInformation playerEventInformation = EventCachePlayerIsInvolvedIn.RemoveResponseByPlayerEventId(playerEvent.PlayerEventId);
			if (playerEventInformation != null && playerEvent.StartTime > utcNow)
			{
				playerEventInformation.PlayerEvent = playerEvent;
				EventCachePlayerIsInvolvedIn.Responses.Add(playerEventInformation);
			}
			EventCachePlayerIsInvolvedIn.Sort();
			if (PlayerEvents.PlayerEventUpdated != null)
			{
				PlayerEvents.PlayerEventUpdated(playerEvent);
			}
		}

		private static void HandleResponseStateChangedEvent(PlayerEvent playerEvent)
		{
			HandleDeleteEvent(playerEvent.PlayerEventId);
			if (PlayerEvents.PlayerEventStateChanged != null)
			{
				PlayerEvents.PlayerEventStateChanged(playerEvent);
			}
		}

		private static void HandleDeleteEvent(long playerEventId)
		{
			PlayerEvent obj = EventCachePlayerIsInvolvedIn.RemoveCreatedByPlayerEventId(playerEventId);
			EventCachePlayerIsInvolvedIn.RemoveResponseByPlayerEventId(playerEventId);
			Cache.InvalidateEntry(GetEventsURI());
			if (PlayerEvents.PlayerEventDeleted != null)
			{
				PlayerEvents.PlayerEventDeleted(obj);
			}
		}

		private static void HandleResponseChangedEvent(PlayerEventInformation information)
		{
			PlayerEvent playerEvent = information.PlayerEvent;
			PlayerEventResponse playerEventResponse = information.PlayerEventResponse;
			EventCachePlayerIsInvolvedIn.RemoveResponseByPlayerEventId(playerEvent.PlayerEventId);
			if ((playerEventResponse.Type == PlayerEventResponseType.Yes || playerEventResponse.Type == PlayerEventResponseType.Interested) && playerEvent.StartTime > DateTime.UtcNow)
			{
				EventCachePlayerIsInvolvedIn.Responses.Add(information);
				EventCachePlayerIsInvolvedIn.SortResponsesByStartTime();
			}
			if (PlayerEvents.PlayerEventResponseChanged != null)
			{
				PlayerEvents.PlayerEventResponseChanged(playerEvent, playerEventResponse);
			}
		}

		private static void HandleResponseDeletedEvent(long playerEventId)
		{
			PlayerEventInformation playerEventInformation = EventCachePlayerIsInvolvedIn.RemoveResponseByPlayerEventId(playerEventId);
			if (PlayerEvents.PlayerEventResponseDeleted != null)
			{
				PlayerEvents.PlayerEventResponseDeleted(playerEventInformation.PlayerEvent, playerEventInformation.PlayerEventResponse);
			}
		}
	}
