		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static PlayerSubscriptionUpdatedCallback m_PlayerSubscriptionUpdated;

		public static event PlayerSubscriptionUpdatedCallback PlayerSubscriptionUpdated
		{
			add
			{
				PlayerSubscriptionUpdatedCallback playerSubscriptionUpdatedCallback = PlayerSubscriptions.m_PlayerSubscriptionUpdated;
				PlayerSubscriptionUpdatedCallback playerSubscriptionUpdatedCallback2;
				do
				{
					playerSubscriptionUpdatedCallback2 = playerSubscriptionUpdatedCallback;
					playerSubscriptionUpdatedCallback = Interlocked.CompareExchange(ref PlayerSubscriptions.m_PlayerSubscriptionUpdated, (PlayerSubscriptionUpdatedCallback)Delegate.Combine(playerSubscriptionUpdatedCallback2, value), playerSubscriptionUpdatedCallback);
				}
				while (playerSubscriptionUpdatedCallback != playerSubscriptionUpdatedCallback2);
			}
			remove
			{
				PlayerSubscriptionUpdatedCallback playerSubscriptionUpdatedCallback = PlayerSubscriptions.m_PlayerSubscriptionUpdated;
				PlayerSubscriptionUpdatedCallback playerSubscriptionUpdatedCallback2;
				do
				{
					playerSubscriptionUpdatedCallback2 = playerSubscriptionUpdatedCallback;
					playerSubscriptionUpdatedCallback = Interlocked.CompareExchange(ref PlayerSubscriptions.m_PlayerSubscriptionUpdated, (PlayerSubscriptionUpdatedCallback)Delegate.Remove(playerSubscriptionUpdatedCallback2, value), playerSubscriptionUpdatedCallback);
				}
