		public static void Initialize()
		{
			Notifications.OnConnect += OnPushNotificationConnectCallback;
		}

		private static void OnPushNotificationConnectCallback()
		{
			RefreshList();
		}

		private static void RefreshList()
		{
			string requestUri = string.Format("{0}v1/my", "api/playersubscriptions/");
			Core.Get(requestUri).ExpectListResponse<PlayerSubscription>().HandleWithCallback(delegate(string error, List<PlayerSubscription> mySubscriptions)
			{
				if (string.IsNullOrEmpty(error))
				{
					SubscriptionCache.Clear();
					foreach (PlayerSubscription mySubscription in mySubscriptions)
					{
						if (mySubscription != null && !SubscriptionCache.Contains(mySubscription.PlayerID))
						{
							SubscriptionCache.Add(mySubscription.PlayerID);
						}
					}
					RaisePlayerSubscriptionUpdatedEvent(null);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to refresh subscription list: " + error);
				}
			});
		}

		private static Core.ApiCallback<UpdateResponse> ParseSubscriptionCallback(long playerId, bool add, Core.ApiCallback callback)
		{
			return delegate(string error, UpdateResponse response)
			{
				if (string.IsNullOrEmpty(error) && response != null && response.Response == UpdateResponseType.Success)
				{
					if (add && !SubscriptionCache.Contains(playerId))
					{
						SubscriptionCache.Add(playerId);
						RaisePlayerSubscriptionUpdatedEvent(playerId);
					}
					else if (!add && SubscriptionCache.Contains(playerId))
					{
						SubscriptionCache.Remove(playerId);
						RaisePlayerSubscriptionUpdatedEvent(playerId);
					}
				}
				Core.SafeInvoke(callback, error);
			};
		}

		public static IEnumerator SubscribeTo(long playerId, Core.ApiCallback callback = null)
		{
			string requestUri = string.Format("{0}v1/subscribe/{1}", "api/playersubscriptions/", playerId);
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("PlayerId", playerId.ToString());
			return Core.Post(requestUri, dictionary).ExpectResponse<UpdateResponse>().HandleWithCallback(ParseSubscriptionCallback(playerId, add: true, callback));
		}

		public static IEnumerator UnsubscribeFrom(long playerId, Core.ApiCallback callback = null)
		{
			string requestUri = string.Format("{0}v1/unsubscribe/{1}", "api/playersubscriptions/", playerId);
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("PlayerId", playerId.ToString());
			return Core.Post(requestUri, dictionary).ExpectResponse<UpdateResponse>().HandleWithCallback(ParseSubscriptionCallback(playerId, add: false, callback));
		}

		public static bool IsLocalPlayerSubscribedToPlayer(long playerid)
		{
			return SubscriptionCache.Contains(playerid);
		}

		public static bool IsLocalPlayerSubscribedToPlayer(Profile playerProfile)
		{
			return SubscriptionCache.Contains(playerProfile.Id);
		}

		private static void RaisePlayerSubscriptionUpdatedEvent(long? playerId)
		{
			try
			{
				if (PlayerSubscriptions.PlayerSubscriptionUpdated != null)
				{
					PlayerSubscriptions.PlayerSubscriptionUpdated(playerId);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
	public class PlayerPresence : IRecNetObject
	{
		private bool isRemotelyBlocked;

		private bool doIPassRemotePlayersStatusVisibilitySetting = true;

		public long PlayerId { get; private set; }

		public bool IsOnline { get; private set; }

		public GameSession GameSession { get; private set; }

		public LocalPlayerController.PlayerType PlayerType { get; private set; }

		public PlayerStatusVisibility StatusVisibility { get; private set; }

		public bool AppearsOnlineToMe
		{
			get
			{
				if (!IsOnline || isRemotelyBlocked)
				{
					return false;
				}
				if (Presence.IsInSameGameSessionAsMe(this))
				{
					return true;
				}
				return doIPassRemotePlayersStatusVisibilitySetting;
			}
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			PlayerId = Util.GetKey<long>("PlayerId", dict);
			IsOnline = Util.GetKey<bool>("IsOnline", dict);
			PlayerType = (LocalPlayerController.PlayerType)Util.GetKey<int>("PlayerType", dict);
			StatusVisibility = (PlayerStatusVisibility)Util.GetKey<int>("StatusVisibility", dict);
			GameSession = Util.GetObjectKey<GameSession>("GameSession", dict);
			UpdateRemotelyBlocked();
			UpdateDoIPassRemotePlayersStatusVisibilitySetting();
		}

		public void UpdateGameSession(GameSession gameSession)
		{
			GameSession = gameSession;
		}

		public void UpdateRemotelyBlocked()
		{
			Relationship relationship = Relationships.Get(PlayerId);
			isRemotelyBlocked = relationship != null && (relationship.Ignored == Relationship.ReciprocalStatus.Remote || relationship.Ignored == Relationship.ReciprocalStatus.Mutual);
		}

		public void UpdateDoIPassRemotePlayersStatusVisibilitySetting()
		{
			switch (StatusVisibility)
			{
			case PlayerStatusVisibility.Public:
				doIPassRemotePlayersStatusVisibilitySetting = true;
				break;
			case PlayerStatusVisibility.Offline:
				doIPassRemotePlayersStatusVisibilitySetting = false;
				break;
			case PlayerStatusVisibility.FriendsOnly:
			{
				bool? flag = Relationships.Get(PlayerId)?.IsFriend;
				doIPassRemotePlayersStatusVisibilitySetting = flag.HasValue && flag.Value;
				break;
			}
			case PlayerStatusVisibility.FavoriteFriendsOnly:
			{
				Relationship relationship = Relationships.Get(PlayerId);
				if (relationship == null)
				{
					doIPassRemotePlayersStatusVisibilitySetting = false;
				}
				else
				{
					doIPassRemotePlayersStatusVisibilitySetting = relationship.IsFriend && (relationship.Favorited == Relationship.ReciprocalStatus.Remote || relationship.Favorited == Relationship.ReciprocalStatus.Mutual);
				}
				break;
			}
			default:
				UnityEngine.Debug.LogWarning($"Unknown player status visibility: {StatusVisibility}");
				doIPassRemotePlayersStatusVisibilitySetting = false;
				break;
			}
		}
	}
