		public static bool WouldIAppearOnlineToPlayer(PlayerStatusVisibility playerStatusVisibility, PlayerPresence playerPresence)
		{
			if (IsInSameGameSessionAsMe(playerPresence))
			{
				return true;
			}
			switch (playerStatusVisibility)
			{
			case PlayerStatusVisibility.Public:
				return true;
			case PlayerStatusVisibility.Offline:
				return false;
			case PlayerStatusVisibility.FriendsOnly:
				return Relationships.Get(playerPresence.PlayerId)?.IsFriend ?? false;
			case PlayerStatusVisibility.FavoriteFriendsOnly:
			{
				Relationship relationship = Relationships.Get(playerPresence.PlayerId);
				if (relationship == null)
				{
					return false;
				}
				return relationship.IsFriend && (relationship.Favorited == Relationship.ReciprocalStatus.Local || relationship.Favorited == Relationship.ReciprocalStatus.Mutual);
			}
			default:
				UnityEngine.Debug.LogWarning($"Unknown player status visibility: {playerStatusVisibility}");
				return false;
			}
		}

		public static bool IsInSameGameSessionAsMe(PlayerPresence playerPresence)
		{
