		public static string GetPlayerStatusString(PlayerPresence playerPresence)
		{
			if (playerPresence == null)
			{
				return string.Empty;
			}
			if (!playerPresence.AppearsOnlineToMe)
			{
				return "Offline";
			}
			if (playerPresence.GameSession == null)
			{
				return "Rec Room";
			}
			string text = playerPresence.GameSession.Name;
			if (playerPresence.GameSession.GameSessionId == GameSessions.LocalGameSession.GameSessionId)
			{
				text += " [WITH YOU]";
			}
			else if (playerPresence.GameSession.Private)
			{
				text += " [PRIVATE]";
			}
			return text;
		}

