		}

		private static void OnGameSessionUpdated(long gameSessionId)
		{
			GameSession gameSession = GameSessions.Get(gameSessionId);
			foreach (PlayerPresence value in playerPresenceCache.Values)
			{
				if (value.GameSession != null && value.GameSession.GameSessionId == gameSessionId)
				{
					value.UpdateGameSession(gameSession);
					SafeRaisePlayerPresenceUpdated(value.PlayerId);
				}
			}
		}

		private static void OnRelationshipUpdated(long? playerId)
		{
			if (!playerId.HasValue)
			{
				foreach (PlayerPresence value in playerPresenceCache.Values)
				{
					UpdateRemotelyBlocked(value);
					UpdateDoIPassRemotePlayersStatusVisibilitySetting(value);
				}
				return;
			}
			PlayerPresence playerPresence = Get(playerId.Value);
			if (playerPresence != null)
			{
				UpdateRemotelyBlocked(playerPresence);
				UpdateDoIPassRemotePlayersStatusVisibilitySetting(playerPresence);
			}
		}

		private static void UpdateRemotelyBlocked(PlayerPresence presence)
		{
			bool appearsOnlineToMe = presence.AppearsOnlineToMe;
			presence.UpdateRemotelyBlocked();
			if (appearsOnlineToMe != presence.AppearsOnlineToMe)
			{
				SafeRaisePlayerPresenceUpdated(presence.PlayerId);
			}
		}

		private static void UpdateDoIPassRemotePlayersStatusVisibilitySetting(PlayerPresence presence)
		{
			bool appearsOnlineToMe = presence.AppearsOnlineToMe;
			presence.UpdateDoIPassRemotePlayersStatusVisibilitySetting();
			if (appearsOnlineToMe != presence.AppearsOnlineToMe)
			{
				SafeRaisePlayerPresenceUpdated(presence.PlayerId);
			}
		}

		private static void OnSubscriptionUpdatePresence(Dictionary<string, object> message)
		{
			try
			{
				PlayerPresence playerPresence = Util.Deserialize<PlayerPresence>(message);
				UpdateCachedPresence(playerPresence);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void RefreshCachedPlayerPresences(IEnumerable<long> profileIds, bool forceRefresh)
		{
			if (!forceRefresh)
			{
				profileIds = profileIds.Where((long id) => !Notifications.IsSubscribed(id)).ToList();
			}
			if (profileIds.Count() == 0)
			{
				return;
			}
			string requestUri = string.Format("{0}v2/list", "api/presence/");
			string json = AmplitudeMiniJSON.Json.Serialize(profileIds);
			Core.Post(requestUri, json).ExpectListResponse<PlayerPresence>().HandleWithCallback(delegate(string error, List<PlayerPresence> playerPresenceList)
			{
				if (string.IsNullOrEmpty(error))
				{
					foreach (long id in profileIds)
					{
						PlayerPresence playerPresence = playerPresenceList.FirstOrDefault((PlayerPresence p) => p.PlayerId == id);
						if (playerPresence == null)
						{
							playerPresenceCache.Remove(id);
							SafeRaisePlayerPresenceUpdated(id);
						}
						else
						{
							UpdateCachedPresence(playerPresence);
						}
					}
					return;
				}
				UnityEngine.Debug.LogError("Failed to refresh player presence: " + error);
			});
		}

		private static void UpdateCachedPresence(PlayerPresence playerPresence)
		{
			if (playerPresence.GameSession != null)
			{
				GameSession gameSession = GameSessions.UpdateCachedGameSession(playerPresence.GameSession);
				playerPresence.UpdateGameSession(gameSession);
			}
			playerPresenceCache[playerPresence.PlayerId] = playerPresence;
			SafeRaisePlayerPresenceUpdated(playerPresence.PlayerId);
		}

		public static void StartHeartbeat()
		{
			heartbeatCoroutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(HeartbeatCoroutine());
		}

		public static void StopHeartbeat()
		{
			if (heartbeatCoroutine != null)
			{
				heartbeatCoroutine.Cancel();
				heartbeatCoroutine = null;
			}
			if (heartbeatWebSocket != null)
			{
				heartbeatWebSocket.Close();
				heartbeatWebSocket = null;
			}
		}

		private static IEnumerator<ISchedule> HeartbeatCoroutine()
		{
			bool useHeartbeatWebSocket = GameConfigs.Get("UseHeartbeatWebSocket") == "1";
			float nextHeartbeatSendTime = UnityEngine.Time.realtimeSinceStartup + 30f;
			while (true)
			{
				if (UnityEngine.Time.realtimeSinceStartup < nextHeartbeatSendTime)
				{
					yield return Schedule.Wait(1f);
					continue;
				}
				nextHeartbeatSendTime = UnityEngine.Time.realtimeSinceStartup + 30f;
				if (Login.AccessToken != null)
				{
					if (useHeartbeatWebSocket && heartbeatWebSocket == null)
					{
						Uri uri = new Uri(string.Format("{0}{1}", Core.ApiService, "api/presence/v3/heartbeatwebsocket"));
						heartbeatWebSocket = new WebSocket(uri);
						heartbeatWebSocket.OnOpen = delegate
						{
							UnityEngine.Debug.Log("RecNet presence heartbeat channel opened");
						};
						heartbeatWebSocket.OnClosed = delegate
						{
							UnityEngine.Debug.Log("RecNet presence heartbeat channel closed");
						};
						heartbeatWebSocket.OnMessage = OnHeartbeatWebSocketMessage;
						yield return Schedule.AfterCompleted(heartbeatWebSocket.Open().Error(delegate
						{
							UnityEngine.Debug.LogError("Unable to establish presence heartbeat websocket. Switching to fallback method");
							useHeartbeatWebSocket = false;
						}));
					}
					PlayerPresence localPresence = Get(Core.LocalProfileId);
					if (localPresence?.GameSession == null)
					{
						lastHeartbeatReceivedTime = null;
					}
					else
					{
						float? num = lastHeartbeatReceivedTime;
						if (!num.HasValue)
						{
							lastHeartbeatReceivedTime = UnityEngine.Time.realtimeSinceStartup;
						}
						string json = JsonUtility.ToJson(new HeartbeatRequest
						{
							LoginLockToken = Login.LockToken,
							GameSessionId = localPresence.GameSession.GameSessionId
						});
						if (useHeartbeatWebSocket)
						{
							heartbeatWebSocket.Send(json);
						}
						else
						{
							yield return Schedule.AfterCompleted(Core.Post("api/presence/v3/heartbeat", json, executeSerially: false).ExpectResponse<HeartbeatResponse>().Then(OnPresenceHeartbeatResponse)
								.Error(delegate(string error)
								{
									UnityEngine.Debug.LogErrorFormat("RecNet presence heartbeat failed: {0}", error);
								}));
						}
					}
				}
				if (lastHeartbeatReceivedTime.HasValue && UnityEngine.Time.realtimeSinceStartup - lastHeartbeatReceivedTime.Value > 120f)
				{
					lastHeartbeatReceivedTime = null;
					UnityEngine.Debug.LogError("Timed out trying to send presence heartbeats. Disconnecting to offline dormroom.");
					UpdateLocalGameSession(null);
				}
			}
		}

		private static void OnHeartbeatWebSocketMessage(WebSocket socket, string message)
		{
			try
			{
				HeartbeatResponse response = Util.Deserialize<HeartbeatResponse>(message);
				OnPresenceHeartbeatResponse(response);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnPresenceHeartbeatResponse(HeartbeatResponse response)
		{
			if (!string.IsNullOrEmpty(response.Error))
			{
				UnityEngine.Debug.LogErrorFormat("RecNet presence heartbeat rejected: {0}", response.Error);
				return;
			}
			PlayerPresence presence = response.Presence;
			lastHeartbeatReceivedTime = UnityEngine.Time.realtimeSinceStartup;
			PlayerPresence playerPresence = Get(Core.LocalProfileId);
			bool flag = presence.GameSession != null;
			bool flag2 = playerPresence?.GameSession != null;
			if (flag2 != flag || (flag2 && playerPresence.GameSession.GameSessionsAreDifferent(presence.GameSession)))
			{
				UnityEngine.Debug.LogError("RecNet presence heartbeat response indicates local presence is out-of-sync!");
				UpdateCachedPresence(presence);
			}
		}

		private static void SafeRaisePlayerPresenceUpdated(long id)
		{
			try
			{
				if (Presence.OnPlayerPresenceUpdated != null)
				{
					Presence.OnPlayerPresenceUpdated(id);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
