		public RegistrationStatus RegistrationStatus => (RegistrationStatus)(int)_registrationStatus;

		public bool Verified => RegistrationStatus == RegistrationStatus.Registered;

		public ObscuredBool Developer { get; set; }

		public ObscuredBool CanReceiveInvites { get; set; }

		public ObscuredString ProfileImageName { get; set; }

		public ObscuredBool JuniorProfile { get; set; }

		public ObscuredBool ForceJuniorImages { get; set; }

		public ObscuredBool PendingJunior { get; set; }

		public ObscuredBool AvoidJuniors { get; set; }

		public ObscuredBool HasBirthday { get; set; }

		public Reputation Reputation { get; set; }

		public PlatformMapping PlatformId { get; set; }

		public float XpLevelUpProgress
		{
			get
			{
				int key = (int)Level + 1;
				if (Config.LevelProgressionMap.ContainsKey(key))
				{
					int num = Config.LevelProgressionMap[key];
					return (float)(int)XP / (float)num;
				}
				return 1f;
			}
		}

		public PlayerCheering.CheerCategory? GetActiveCheer()
		{
			if (Reputation.SelectedCheer.HasValue)
			{
				PlayerCheering.CheerCategory value = Reputation.SelectedCheer.Value;
				if ((value == PlayerCheering.CheerCategory.General && Reputation.CheerGeneral > 0) || (value == PlayerCheering.CheerCategory.Helpful && Reputation.CheerHelpful > 0) || (value == PlayerCheering.CheerCategory.Sportmanship && Reputation.CheerSportsman > 0) || (value == PlayerCheering.CheerCategory.GreatHost && Reputation.CheerGreatHost > 0) || (value == PlayerCheering.CheerCategory.Creative && Reputation.CheerCreative > 0))
				{
					return value;
				}
			}
			return null;
		}

		public int GetXpRequiredToLevelUp()
		{
			int result = -1;
			if (Verified || (int)Level < 3)
			{
				int key = (int)Level + 1;
				if (Config.LevelProgressionMap.ContainsKey(key))
				{
					result = Config.LevelProgressionMap[key];
				}
			}
			return result;
		}

