		{
			Id = Util.GetKey<long>("Id", dict);
			Username = Util.GetKey<string>("Username", dict);
			DisplayName = Util.GetKey<string>("DisplayName", dict);
			Bio = Util.GetKeyOrDefault<string>("Bio", dict);
			XP = Util.GetKey<int>("XP", dict);
			Level = Util.GetKey<int>("Level", dict);
			_registrationStatus = Util.GetKey<int>("RegistrationStatus", dict);
			Developer = Util.GetKey<bool>("Developer", dict);
			CanReceiveInvites = Util.GetKey<bool>("CanReceiveInvites", dict);
			ProfileImageName = Util.GetKey<string>("ProfileImageName", dict);
			if (string.IsNullOrEmpty(Username))
			{
				Username = "[Unknown]";
				UnityEngine.Debug.LogErrorFormat("Orphan player account {0} ({1}) found.", DisplayName, Id);
			}
			JuniorProfile = Util.GetKey<bool>("JuniorProfile", dict);
			ForceJuniorImages = Util.GetKey<bool>("ForceJuniorImages", dict);
			PendingJunior = Util.GetKey<bool>("PendingJunior", dict);
			HasBirthday = Util.GetKey<bool>("HasBirthday", dict);
			if (dict.ContainsKey("AvoidJuniors"))
			{
				AvoidJuniors = Util.GetKey<bool>("AvoidJuniors", dict);
			}
			Reputation = Util.GetObjectKey<Reputation>("PlayerReputation", dict);
			PlatformId = Util.GetObjectKey<PlatformMapping>("PlatformId", dict);
		}

		internal void RandomizeObscured()
		{
			Id.RandomizeCryptoKey();
			Username.RandomizeCryptoKey();
			if (!string.IsNullOrEmpty(DisplayName))
			{
				DisplayName.RandomizeCryptoKey();
			}
			XP.RandomizeCryptoKey();
			Level.RandomizeCryptoKey();
			_registrationStatus.RandomizeCryptoKey();
			Developer.RandomizeCryptoKey();
			CanReceiveInvites.RandomizeCryptoKey();
			JuniorProfile.RandomizeCryptoKey();
			PendingJunior.RandomizeCryptoKey();
			HasBirthday.RandomizeCryptoKey();
			ForceJuniorImages.RandomizeCryptoKey();
			AvoidJuniors.RandomizeCryptoKey();
		}
	}
