		public static IPromise<Profile> GetPlayerByUsername(string username)
		{
			Profile profile = null;
			foreach (Profile value in profileCache.Values)
			{
				if (value.Username.Equals(username, StringComparison.InvariantCultureIgnoreCase))
				{
					profile = value;
				}
			}
			if (profile != null)
			{
				return new CompletedPromise<Profile>(profile);
			}
			string requestUri = string.Format("{0}v1/getByUsername?name={1}", "api/players/", username);
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<Profile>().Then(StoreProfileInCache)
				.Error(delegate(string error)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to get profile: {0}", error);
				});
		}

		public static Profile Get(long profileId)
		{
			if (!profileCache.TryGetValue(profileId, out var value))
			{
				QueueProfileDownload(profileId);
			}
			return value;
		}

		private static void QueueProfileDownload(long profileId)
		{
			if (downloadCoroutineHost == null)
			{
				GameObject gameObject = new GameObject("DownloadCoroutineHost");
				UnityEngine.Object.DontDestroyOnLoad(gameObject);
				gameObject.hideFlags = HideFlags.HideInHierarchy;
				downloadCoroutineHost = gameObject.AddComponent<RecNetProfile>();
				downloadCoroutineHost.StartCoroutine(DownloadPendingRequestsCoroutine());
			}
			if (!inProgressRequests.Contains(profileId))
			{
				pendingRequests.Add(profileId);
			}
		}

		private static IEnumerator DownloadPendingRequestsCoroutine()
		{
			while (true)
			{
				yield return new WaitUntil(() => pendingRequests.Count > 0);
				List<long> profileIds = pendingRequests.ToList();
				pendingRequests.Clear();
				inProgressRequests.UnionWith(profileIds);
				GetFromServer(profileIds, delegate(string error, List<Profile> profiles)
				{
					inProgressRequests.ExceptWith(profileIds);
					if (!string.IsNullOrEmpty(error))
					{
						pendingRequests.UnionWith(profileIds);
					}
				});
