		public static void CompleteObjectives(List<ProgressionManager.ObjectiveCompletionRecord> objectiveCompletionRecords)
		{
			string requestUri = string.Format("{0}v1/objectives", "api/players/");
			List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
			foreach (ProgressionManager.ObjectiveCompletionRecord objectiveCompletionRecord in objectiveCompletionRecords)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("objectiveType", (int)objectiveCompletionRecord.objectiveType);
				dictionary.Add("additionalXp", objectiveCompletionRecord.additionalXp);
				dictionary.Add("inParty", objectiveCompletionRecord.inParty);
				list.Add(dictionary);
			}
			string json = AmplitudeMiniJSON.Json.Serialize(list);
			Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to complete objectives");
		}

