namespace RecNet
{
	public static class PromiseExtensions
	{
		public static IPromise ExpectHttpStatusSuccess(this IPromise<HTTPResponse> apiCallPromise)
		{
			return apiCallPromise.ContinueWith((Func<HTTPResponse, IPromise>)((HTTPResponse response) => (response.StatusCode >= 400) ? ((Promise)new ErroredPromise("HTTP Error " + response.StatusCode)) : ((Promise)new CompletedPromise())));
		}

		public static IPromise<T> ExpectResponse<T>(this IPromise<HTTPResponse> apiCallPromise, bool treat404NotFoundAsNull = false, bool treatEmptyResponseAsNull = false) where T : IRecNetObject, new()
		{
			Func<string, T> parser = ((!treatEmptyResponseAsNull) ? new Func<string, T>(Util.Deserialize<T>) : new Func<string, T>(Util.DeserializeNullable<T>));
			return DeserializeResponse(apiCallPromise, parser, treat404NotFoundAsNull);
		}

		public static IPromise<List<T>> ExpectListResponse<T>(this IPromise<HTTPResponse> apiCallPromise, bool treat404NotFoundAsNull = false) where T : IRecNetObject, new()
		{
			return DeserializeResponse(apiCallPromise, Util.DeserializeList<T>, treat404NotFoundAsNull);
		}

		private static IPromise<T> DeserializeResponse<T>(IPromise<HTTPResponse> apiCallPromise, Func<string, T> parser, bool treat404NotFoundAsNull)
		{
			return apiCallPromise.ContinueWith<T>(delegate(HTTPResponse response)
			{
				if (response.StatusCode >= 400)
				{
					if (response.StatusCode == 404 && treat404NotFoundAsNull)
					{
						return new CompletedPromise<T>(default(T));
					}
					return new ErroredPromise<T>("HTTP Error " + response.StatusCode);
				}
				if (string.IsNullOrEmpty(response.DataAsText))
				{
					UnityEngine.Debug.LogError("Received blank response when we expected data");
					return new ErroredPromise<T>("Malformed Response");
				}
				T result;
				try
				{
					result = parser(response.DataAsText);
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
					UnityEngine.Debug.LogError("Received malformed RecNet response: '" + response.DataAsText + "'");
					return new ErroredPromise<T>("Malformed Response");
				}
				return new CompletedPromise<T>(result);
			});
		}

		public static IPromise LogErrors(this IPromise promise, string errorPrefix)
		{
			return promise.Error(delegate(string error)
			{
				UnityEngine.Debug.LogError($"{errorPrefix}: {error}");
			});
		}

		public static IPromise<T> LogErrors<T>(this IPromise<T> promise, string errorPrefix)
		{
			return promise.Error(delegate(string error)
			{
				UnityEngine.Debug.LogError($"{errorPrefix}: {error}");
			});
		}

		public static IPromise HandleWithCallback(this IPromise promise, Core.ApiCallback callback)
		{
			return promise.Then(delegate
			{
				Core.SafeInvoke(callback, null);
			}).Error(delegate(string error)
			{
				Core.SafeInvoke(callback, error);
			});
		}

		public static IPromise<T> HandleWithCallback<T>(this IPromise<T> promise, Core.ApiCallback<T> callback)
		{
			return promise.Then(delegate(T result)
			{
				Core.SafeInvoke(callback, null, result);
			}).Error(delegate(string error)
			{
				Core.SafeInvoke(callback, error, default(T));
			});
		}
	}
