	public class RecentPlayers
	{
		private const int MAX_RECENT_PLAYERS = 20;

		private static readonly LinkedList<long> recentPlayersIncludingInCurrentRoom = new LinkedList<long>();

		public static readonly List<long> RecentPlayersNotInCurrentRoom = new List<long>(20);

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action m_PlayerListUpdated;

		public static Dictionary<long, float> PlayersLastSeen = new Dictionary<long, float>();

		private static string RECENT_PLAYERS_PREF => string.Concat("RECENT_PLAYERS_PREF_", Profiles.LocalProfile.Id, "_", Core.ApiService.Host);

		public static event Action PlayerListUpdated
		{
			add
			{
				Action action = RecentPlayers.m_PlayerListUpdated;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref RecentPlayers.m_PlayerListUpdated, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = RecentPlayers.m_PlayerListUpdated;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref RecentPlayers.m_PlayerListUpdated, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public static void Initialize()
		{
			PhotonNetwork.OnJoinedRoom += new Action(Photon_OnJoinedRoom);
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(Photon_OnPhotonPlayerConnected);
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(Photon_OnPhotonPlayerDisconnected);
			RestoreRecentPlayersListFromDisk();
		}

		private static void Photon_OnJoinedRoom()
		{
			UpdatePlayerList();
		}

		private static void Photon_OnPhotonPlayerConnected(PhotonPlayer newPlayer)
		{
			UpdatePlayerList();
		}

		private static void Photon_OnPhotonPlayerDisconnected(PhotonPlayer newPlayer)
		{
			UpdatePlayerList();
		}

		private static void UpdatePlayerList()
		{
			IEnumerable<long> enumerable = from p in PhotonNetwork.otherPlayers
				orderby p.ID
				select p.RecNetProfileId;
			foreach (long item in enumerable)
			{
				recentPlayersIncludingInCurrentRoom.Remove(item);
				recentPlayersIncludingInCurrentRoom.AddFirst(item);
				PlayersLastSeen[item] = UnityEngine.Time.unscaledTime;
			}
			int num = 20 + PhotonNetwork.otherPlayers.Length;
			while (recentPlayersIncludingInCurrentRoom.Count > num)
			{
				recentPlayersIncludingInCurrentRoom.RemoveLast();
			}
			RecentPlayersNotInCurrentRoom.Clear();
			RecentPlayersNotInCurrentRoom.AddRange(recentPlayersIncludingInCurrentRoom.Skip(PhotonNetwork.otherPlayers.Length));
			SaveRecentPlayersListToDisk();
			SafeRaisePlayerListUpdated();
		}

		private static void SaveRecentPlayersListToDisk()
		{
			string value = AmplitudeMiniJSON.Json.Serialize(recentPlayersIncludingInCurrentRoom.Take(20).ToList());
			PlayerPrefs.SetString(RECENT_PLAYERS_PREF, value);
		}

		private static void RestoreRecentPlayersListFromDisk()
		{
			if (!PlayerPrefs.HasKey(RECENT_PLAYERS_PREF))
			{
				return;
			}
			string text = PlayerPrefs.GetString(RECENT_PLAYERS_PREF, null);
			if (string.IsNullOrEmpty(text) || !(AmplitudeMiniJSON.Json.Deserialize(text) is List<object> { Count: >0 } list))
			{
				return;
			}
			try
			{
				recentPlayersIncludingInCurrentRoom.Clear();
				foreach (object item in list)
				{
					recentPlayersIncludingInCurrentRoom.AddLast(long.Parse(item.ToString()));
				}
				SafeRaisePlayerListUpdated();
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void SafeRaisePlayerListUpdated()
		{
			try
			{
				if (RecentPlayers.PlayerListUpdated != null)
				{
					RecentPlayers.PlayerListUpdated();
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
