		public static IPromise<StatUpdates> SendMatchStats(MatchCompleteStats matchStats)
		{
			string requestUri = string.Format("{0}v1/matchcomplete", "api/royale/");
			string json = JsonUtility.ToJson(matchStats);
			Promise<StatUpdates> promise = new Promise<StatUpdates>();
			Core.Post(requestUri, json).ExpectResponse<StatUpdates>().HandleWithCallback(delegate(string error, StatUpdates newStats)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogErrorFormat("RecNet RecRoyaleMatch call failed: {0}", error);
					promise.Error(error);
				}
				else
				{
					if (newStats.NewProgress != null && newStats.NewProgress.Count > 0)
					{
						localPlayerCurrentProgress = newStats.NewProgress.LastItem();
					}
					if (RecNetRecRoyaleStats.OnPlayerStatsReceived != null)
					{
						RecNetRecRoyaleStats.OnPlayerStatsReceived(newStats);
					}
					promise.Complete(newStats);
				}
			});
			return promise;
		}

		private static IEnumerator GetPlayerProgress(Promise<RecRoyalePlayerProgress> promise)
		{
			string requestUri = string.Format("{0}v1/current", "api/royale/");
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<RecRoyalePlayerProgress>().HandleWithCallback(delegate(string error, RecRoyalePlayerProgress newProgress)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogErrorFormat("RecNet RecRoyaleProgress call failed: {0}", error);
					promise.Error(error);
				}
				else
				{
					localPlayerCurrentProgress = newProgress;
					promise.Complete(newProgress);
				}
			});
		}
