		public static void BulkIgnorePlatformUsers(PlatformManager.PlatformType platform, List<ulong> platformPlayerIds)
		{
			string requestUri = string.Format("{0}v1/bulkignoreplatformusers", "api/relationships/");
			BulkBlockPlatformUsersRequest bulkBlockPlatformUsersRequest = new BulkBlockPlatformUsersRequest();
			bulkBlockPlatformUsersRequest.Platform = (int)platform;
			bulkBlockPlatformUsersRequest.PlatformIds = platformPlayerIds.Select((ulong id) => id.ToString()).ToList();
			string json = JsonUtility.ToJson(bulkBlockPlatformUsersRequest);
			Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to bulk ignore platform users");
		}

		private static void RefreshList()
		{
			string requestUri = string.Format("{0}v2/get", "api/relationships/");
			Core.Get(requestUri).ExpectListResponse<Relationship>().HandleWithCallback(delegate(string error, List<Relationship> newRelationshipList)
			{
				if (string.IsNullOrEmpty(error))
				{
					relationshipCache.Clear();
					foreach (Relationship newRelationship in newRelationshipList)
					{
						relationshipCache[newRelationship.PlayerID] = newRelationship;
					}
					RaiseRelationshipUpdatedEvent(null);
				}
				else
				{
					UnityEngine.Debug.LogError("Failed to refresh relationship list: " + error);
					RefreshList();
				}
			});
		}

		private static Core.ApiCallback<Relationship> ParseRelationshipCallback(Core.ApiCallback callback)
		{
			return delegate(string error, Relationship relationship)
			{
				if (string.IsNullOrEmpty(error))
				{
					relationshipCache[relationship.PlayerID] = relationship;
					RaiseRelationshipUpdatedEvent(relationship.PlayerID);
				}
				Core.SafeInvoke(callback, error);
			};
		}

		private static void OnPushNotificationConnectCallback()
		{
			RefreshList();
		}

		private static void OnRelationshipsInvalid(Dictionary<string, object> message)
		{
			RefreshList();
		}

		private static void OnRelationshipChanged(Dictionary<string, object> message)
		{
			try
			{
				Relationship relationship = Util.Deserialize<Relationship>(message);
				relationshipCache[relationship.PlayerID] = relationship;
				RaiseRelationshipUpdatedEvent(relationship.PlayerID);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void RaiseRelationshipUpdatedEvent(long? playerId)
		{
			try
			{
				if (Relationships.RelationshipUpdated != null)
				{
					Relationships.RelationshipUpdated(playerId);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
