		private const string REPORTING_API = "api/PlayerReporting/";

		private static Dictionary<long, float> reportedPlayerIds = new Dictionary<long, float>();

		public static bool IsCurrentPlayerBlocked => CurrentBlockDetail != null && CurrentBlockDetail.Duration > 0;

		public static ModerationBlockDetail CurrentBlockDetail { get; private set; }

		public static void Initialize()
		{
			Notifications.RegisterHandler(Notifications.PushNotificationId.ModerationKick, OnModerationKick);
			Notifications.RegisterHandler(Notifications.PushNotificationId.ModerationKickAttemptFailed, OnModerationKickAttemptFailed);
		}

		public static IEnumerator GetModerationBlockDetails(Core.ApiCallback callback)
		{
			string requestUri = string.Format("{0}v1/moderationBlockDetails", "api/PlayerReporting/");
			return Core.Get(requestUri).ExpectResponse<ModerationBlockDetail>().HandleWithCallback(delegate(string error, ModerationBlockDetail response)
			{
				if (string.IsNullOrEmpty(error))
				{
					CurrentBlockDetail = response;
				}
				else
				{
					UnityEngine.Debug.LogError(error);
				}
				Core.SafeInvoke(callback, error);
			});
		}

		public static bool CanCreateReport(long playerId)
		{
			bool flag = RecentPlayers.PlayersLastSeen.ContainsKey(playerId) && RecentPlayers.PlayersLastSeen[playerId] + 3600f > UnityEngine.Time.unscaledTime;
			bool flag2 = !reportedPlayerIds.ContainsKey(playerId) || reportedPlayerIds[playerId] + 3600f < UnityEngine.Time.unscaledTime;
			return flag && flag2;
		}

		public static IEnumerator CreateReport(long playerId, ReportCategory reportCategory, string details, float? heightReported, Core.ApiCallback<OkResponse> callback)
		{
			if (CanCreateReport(playerId))
			{
				reportedPlayerIds[playerId] = UnityEngine.Time.unscaledTime;
				string requestUri = string.Format("{0}v3/create", "api/PlayerReporting/");
				Dictionary<string, string> dictionary = new Dictionary<string, string>();
				dictionary.Add("PlayerIdReported", playerId.ToString());
				int num = (int)reportCategory;
				dictionary.Add("ReportCategory", num.ToString());
				dictionary.Add("Details", details);
				dictionary.Add("HeightReporter", Player.LocalPlayer.CurrentFloorHeightFromHead.ToString("F2", CultureInfo.InvariantCulture));
				if (heightReported.HasValue)
				{
					dictionary.Add("HeightReported", heightReported.Value.ToString("F2", CultureInfo.InvariantCulture));
				}
				dictionary.Add("RoomId", GameSessions.LocalGameSession.RoomId.ToString());
				return Core.Post(requestUri, dictionary).ExpectResponse<OkResponse>().HandleWithCallback(callback);
			}
			callback?.Invoke(string.Empty, new OkResponse
			{
				Success = false,
				Message = "You have already reported\nthis player very recently."
			});
			return null;
		}

		private static void OnModerationKick(Dictionary<string, object> data)
		{
			try
			{
				ModerationBlockDetail lastBlockDetail = Util.Deserialize<ModerationBlockDetail>(data);
				if (lastBlockDetail == null)
				{
					return;
				}
				CurrentBlockDetail = lastBlockDetail;
				if (PhotonNetwork.offlineMode)
				{
					LocalModerationKickSelf();
					return;
				}
				SessionManager.DeveloperGatedActionCoroutine(delegate
				{
					if (Player.LocalPlayerExists)
					{
						Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO_CANCEL_HOME, "You are being vote kicked for " + lastBlockDetail.ReportCategory, "Do you accept this punishment?", "Kick me :(", "Oh, Hell no!").Then(OnModerationKickConfirmed);
					}
				}, delegate
				{
					LocalModerationKickSelf();
				});
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnModerationKickAttemptFailed(Dictionary<string, object> data)
		{
			try
			{
				ModerationKickFail moderationKickFail = Util.Deserialize<ModerationKickFail>(data);
				if (moderationKickFail != null)
				{
					AnalyticsHelper.ModeratorKickPlayerFailed(moderationKickFail.PlayerIdReported, moderationKickFail.ReportCategory, moderationKickFail.YesVotes, moderationKickFail.NoVotes, PhotonNetwork.playerList.Length);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnModerationKickConfirmed(ConfirmDialogResponses dialogResponse)
		{
			if (Player.LocalPlayerExists && dialogResponse == ConfirmDialogResponses.Affirmative && CurrentBlockDetail != null)
			{
				LocalModerationKickSelf();
			}
		}

		private static void LocalModerationKickSelf()
		{
			if (Player.LocalPlayerExists)
			{
				GameSession localGameSession = GameSessions.LocalGameSession;
				if (localGameSession != null && localGameSession.GameSessionId == CurrentBlockDetail.GameSessionId)
				{
					Player.LocalPlayer.PlayerModeration.ModerationBroadcastKickMessage();
				}
				SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom("Kicked to Dormroom", SessionManager.LoadSceneSources.VOTE_KICKED);
			}
		}

		public static IEnumerator VoteToKickPlayer(long playerId, bool response, Core.ApiCallback<OkResponse> callback)
		{
			string requestUri = string.Format("{0}v2/voteToKick", "api/PlayerReporting/");
			GameSession localGameSession = GameSessions.LocalGameSession;
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			dictionary.Add("PlayerId", playerId.ToString());
