	public class RoomDetails : IRecNetObject
	{
		public static readonly RoomDetails OfflineRoomDetails = new RoomDetails
		{
			Room = Room.OfflineRoom,
			Scenes = new List<RoomScene> { RoomScene.OfflineRoomScene },
			CoOwnerIds = new List<int>(),
			InvitedCoOwnerIds = new List<int>(),
			HostIds = new List<int>(),
			InvitedHostIds = new List<int>(),
			CheerCount = 0,
			FavoriteCount = 0,
			VisitCount = 0
		};

		public List<string> AllTags = new List<string>();

		public List<string> AutoTags = new List<string>();

		public List<string> PlayerAddedTags = new List<string>();

		public List<string> AgTags = new List<string>();

		public Room Room { get; private set; }

		public List<RoomScene> Scenes { get; private set; }

		public List<int> CoOwnerIds { get; private set; }

		public List<int> InvitedCoOwnerIds { get; private set; }

		public List<int> HostIds { get; private set; }

		public List<int> InvitedHostIds { get; private set; }

		public int CheerCount { get; set; }

		public int FavoriteCount { get; set; }

		public int VisitCount { get; set; }

		public RoomRole LocalPlayerRole { get; private set; }

		public void Deserialize(Dictionary<string, object> dict)
		{
			Room = Util.GetObjectKey<Room>("Room", dict);
			Scenes = Util.GetObjectListKey<RoomScene>("Scenes", dict);
			CoOwnerIds = Util.GetListKey<int>("CoOwners", dict);
			InvitedCoOwnerIds = Util.GetListKey<int>("InvitedCoOwners", dict);
			HostIds = Util.GetListKey<int>("Hosts", dict);
			InvitedHostIds = Util.GetListKey<int>("InvitedHosts", dict);
			CheerCount = Util.GetKey<int>("CheerCount", dict);
			FavoriteCount = Util.GetKey<int>("FavoriteCount", dict);
			VisitCount = Util.GetKey<int>("VisitCount", dict);
			int profileId = (int)Profiles.LocalProfile.Id.GetDecrypted();
			LocalPlayerRole = GetPlayerRole(profileId);
			List<RoomTagDTO> objectListKey = Util.GetObjectListKey<RoomTagDTO>("Tags", dict);
			foreach (RoomTagDTO item in objectListKey)
			{
				AllTags.Add(item.Tag);
				switch (item.Type)
				{
				case TagType.AGOnly:
					AgTags.Add(item.Tag);
					break;
				case TagType.General:
					PlayerAddedTags.Add(item.Tag);
					break;
				case TagType.Auto:
					AutoTags.Add(item.Tag);
					break;
				default:
					UnityEngine.Debug.LogErrorFormat("Tag type {0} not supported", item.Type);
					break;
				}
			}
		}

		public RoomRole GetPlayerRole(int profileId)
		{
			if (Room.CreatorPlayerId == profileId)
			{
				return RoomRole.Creator;
			}
			if (CoOwnerIds.Contains(profileId))
			{
				return RoomRole.CoOwner;
			}
			if (HostIds.Contains(profileId))
			{
				return RoomRole.Host;
			}
			return RoomRole.Guest;
		}

		public RoomPermissionValue GetPlayerCoOwnerPermission(int profileId)
		{
			if (CoOwnerIds.Contains(profileId))
			{
				return RoomPermissionValue.True;
			}
			if (InvitedCoOwnerIds.Contains(profileId))
			{
				return RoomPermissionValue.Invited;
			}
			return RoomPermissionValue.False;
		}

		public RoomPermissionValue GetPlayerHostPermission(int profileId)
		{
			if (HostIds.Contains(profileId))
			{
				return RoomPermissionValue.True;
			}
			if (InvitedHostIds.Contains(profileId))
			{
				return RoomPermissionValue.Invited;
			}
			return RoomPermissionValue.False;
		}

		public bool LocalCanModifyPermission(int profileId, RoomRole newRole)
		{
			bool flag = profileId == (long)Profiles.LocalProfile.Id;
			RoomRole playerRole = GetPlayerRole((int)(long)Profiles.LocalProfile.Id);
			if ((flag && newRole > playerRole) || (!flag && newRole >= playerRole))
			{
				return false;
			}
			return true;
		}
	}
