		public class CanJoinStatus
		{
			public bool CanJoinNow;

			public bool CanJoinWithPlayerTypeSwitch;

			public LocalPlayerController.PlayerType SuggestedPlayerType;

			public string FailureString;

			public static CanJoinStatus Success(LocalPlayerController.PlayerType currentPlayerType)
			{
				CanJoinStatus canJoinStatus = new CanJoinStatus();
				canJoinStatus.CanJoinNow = true;
				canJoinStatus.CanJoinWithPlayerTypeSwitch = false;
				canJoinStatus.SuggestedPlayerType = currentPlayerType;
				canJoinStatus.FailureString = string.Empty;
				return canJoinStatus;
			}

			public static CanJoinStatus Failure(LocalPlayerController.PlayerType? suggestedPlayerType, string failureString)
			{
				CanJoinStatus canJoinStatus;
				if (suggestedPlayerType.HasValue)
				{
					canJoinStatus = new CanJoinStatus();
					canJoinStatus.CanJoinNow = false;
					canJoinStatus.CanJoinWithPlayerTypeSwitch = true;
					canJoinStatus.SuggestedPlayerType = suggestedPlayerType.Value;
					canJoinStatus.FailureString = failureString;
					return canJoinStatus;
				}
				canJoinStatus = new CanJoinStatus();
				canJoinStatus.CanJoinNow = false;
				canJoinStatus.CanJoinWithPlayerTypeSwitch = false;
				canJoinStatus.SuggestedPlayerType = LocalPlayerController.PlayerType.UNINITIALIZED;
				canJoinStatus.FailureString = failureString;
				return canJoinStatus;
			}
		}

