		public static event RoomDetailsUpdatedCallback OnRoomDetailsUpdated
		{
			add
			{
				RoomDetailsUpdatedCallback roomDetailsUpdatedCallback = Rooms.m_OnRoomDetailsUpdated;
				RoomDetailsUpdatedCallback roomDetailsUpdatedCallback2;
				do
				{
					roomDetailsUpdatedCallback2 = roomDetailsUpdatedCallback;
					roomDetailsUpdatedCallback = Interlocked.CompareExchange(ref Rooms.m_OnRoomDetailsUpdated, (RoomDetailsUpdatedCallback)Delegate.Combine(roomDetailsUpdatedCallback2, value), roomDetailsUpdatedCallback);
				}
				while (roomDetailsUpdatedCallback != roomDetailsUpdatedCallback2);
			}
			remove
			{
				RoomDetailsUpdatedCallback roomDetailsUpdatedCallback = Rooms.m_OnRoomDetailsUpdated;
				RoomDetailsUpdatedCallback roomDetailsUpdatedCallback2;
				do
				{
					roomDetailsUpdatedCallback2 = roomDetailsUpdatedCallback;
					roomDetailsUpdatedCallback = Interlocked.CompareExchange(ref Rooms.m_OnRoomDetailsUpdated, (RoomDetailsUpdatedCallback)Delegate.Remove(roomDetailsUpdatedCallback2, value), roomDetailsUpdatedCallback);
				}
				while (roomDetailsUpdatedCallback != roomDetailsUpdatedCallback2);
			}
		}

