		public static void Initialize()
		{
			Notifications.RegisterHandler(Notifications.PushNotificationId.SubscriptionUpdateRoom, OnSubscriptionUpdateRoom);
			GameSessions.OnLocalGameSessionUpdated += OnLocalGameSessionUpdated;
			Presence.OnPlayerPresenceUpdated += OnPlayerPresenceUpdated;
		}

		private static void OnSubscriptionUpdateRoom(Dictionary<string, object> message)
		{
			try
			{
				RoomDetails roomDetails = Util.Deserialize<RoomDetails>(message);
				StoreRoomDetailsInCache(roomDetails);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnLocalGameSessionUpdated()
		{
			long roomSceneId = GameSessions.LocalGameSession.RoomSceneId;
			long newRoomId = GameSessions.LocalGameSession.RoomId;
			if (localRoomId == newRoomId && localRoomSceneId == roomSceneId)
			{
				return;
			}
			localRoomId = newRoomId;
			localRoomSceneId = roomSceneId;
			RoomDetails cachedRoomDetails = GetCachedRoomDetails(newRoomId);
			if (cachedRoomDetails != null)
			{
				LocalRoomDetails = cachedRoomDetails;
				if (getRecentRoomsPromise == null)
				{
					return;
				}
				getRecentRoomsPromise.Then(delegate(List<Room> roomList)
				{
					roomList.RemoveWhere((Room r) => r.RoomId == newRoomId);
					roomList.Insert(0, LocalRoomDetails.Room);
				});
				return;
			}
			GetRoomDetails(newRoomId).Then(delegate(RoomDetails roomDetails)
			{
				if (roomDetails != null && roomDetails.Room.RoomId == localRoomId)
				{
					LocalRoomDetails = roomDetails;
					SafeRaiseLocalRoomUpdated();
				}
			});
		}

		private static void OnPlayerPresenceUpdated(long playerId)
		{
			if (playerId == Core.LocalProfileId)
			{
				GameSession gameSession = Presence.Get(playerId).GameSession;
				if (gameSession != null && !string.IsNullOrEmpty(gameSession.DataBlobName))
				{
					GetRoomData(gameSession.DataBlobName);
				}
			}
		}

		public static RoomDetails GetCachedRoomDetails(long roomId)
		{
			roomDetailsCache.TryGetValue(roomId, out var value);
			return value;
		}

		public static void StoreRoomDetailsInCache(RoomDetails roomDetails)
		{
			if (roomDetails != null)
			{
				if (localRoomId == roomDetails.Room.RoomId)
				{
					LocalRoomDetails = roomDetails;
					SafeRaiseLocalRoomUpdated();
				}
				roomDetailsCache[roomDetails.Room.RoomId] = roomDetails;
				SafeRaiseRoomDetailsUpdated(roomDetails.Room.RoomId);
				if (roomDetails.LocalPlayerRole >= RoomRole.CoOwner)
				{
					Cache.InvalidateEntry(GetMyCreatedRoomsRequestUri);
				}
			}
		}

		public static Dictionary<long, int> GetFriendCountInRooms()
		{
			Dictionary<long, int> dictionary = new Dictionary<long, int>();
			IEnumerable<PlayerPresence> enumerable = from r in Relationships.GetAll()
				where r.IsFriend
				select Presence.Get(r.PlayerID) into p
				where p?.IsOnline ?? false
				select p;
			foreach (PlayerPresence item in enumerable)
			{
				if (item.GameSession != null)
				{
					if (dictionary.TryGetValue(item.GameSession.RoomId, out var value))
					{
						dictionary[item.GameSession.RoomId] = value + 1;
					}
					else
					{
						dictionary.Add(item.GameSession.RoomId, 1);
					}
				}
			}
			return dictionary;
		}

