		private static IPromise<List<string>> GetTags(bool getPinned)
		{
			string requestUri = string.Format("{0}v1/filters", "api/rooms/");
			TimeSpan maxCacheAge = new TimeSpan(0, 5, 0);
			return Cache.Get<GetFiltersResponse>(requestUri, maxCacheAge, executeSerially: false).ContinueWith(delegate(GetFiltersResponse response)
			{
				PinnedTags = response.PinnedFilters.Select((string f) => $"{'#'}{f}").ToList();
				PopularTags = response.PopularFilters.Select((string f) => $"{'#'}{f}").ToList();
				return (!getPinned) ? PopularTags : PinnedTags;
			}).Error(delegate(string error)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to get tags: {0}", error);
			});
		}

