		public static IEnumerator CloneRoom(long roomIdToClone, string name, Core.ApiCallback<CreateModifyRoomResponse> callback)
		{
			string requestUri = string.Format("{0}v1/clone", "api/rooms/");
			CloneRoomRequest cloneRoomRequest = new CloneRoomRequest();
			cloneRoomRequest.Name = name;
			cloneRoomRequest.RoomId = roomIdToClone;
			string json = JsonUtility.ToJson(cloneRoomRequest);
			return Core.Post(requestUri, json).ExpectResponse<CreateModifyRoomResponse>().HandleWithCallback(ProcessCreateModifyGameResponse("clone", delegate(string error, CreateModifyRoomResponse response)
			{
				if (string.IsNullOrEmpty(error) && response.Result == CreateModifyRoomStatus.Success)
				{
					Cache.InvalidateEntry(GetMyCreatedRoomsRequestUri);
					AnalyticsHelper.RoomCloned(response.RoomDetails.Room.RoomId);
				}
				Core.SafeInvoke(callback, error, response);
			}));
		}

		public static IEnumerator ModifySceneParent(RoomScene roomScene, long newParentRoomId, Core.ApiCallback<CreateModifyRoomResponse> callback)
		{
			if (roomDetailsCache.TryGetValue(newParentRoomId, out var value) && value.Scenes.Contains(roomScene))
			{
				Core.SafeInvoke(callback, null, new CreateModifyRoomResponse
				{
					Result = CreateModifyRoomStatus.Success,
					RoomDetails = value
				});
				return NoOp();
			}
			string requestUri = string.Format("{0}v1/modify/sceneParent", "api/rooms/");
			ModifySceneParentRequest modifySceneParentRequest = new ModifySceneParentRequest();
			modifySceneParentRequest.RoomSceneId = roomScene.RoomSceneId;
			modifySceneParentRequest.NewParentRoomId = newParentRoomId;
			string json = JsonUtility.ToJson(modifySceneParentRequest);
			return Core.Post(requestUri, json).ExpectResponse<CreateModifyRoomResponse>().Then(delegate(CreateModifyRoomResponse response)
			{
				if (response.Result == CreateModifyRoomStatus.Success)
				{
					StoreRoomDetailsInCache(response.RoomDetails);
					if (response.RoomDetails != null)
					{
						for (int i = 0; i < response.RoomDetails.Scenes.Count; i++)
						{
							if (response.RoomDetails.Scenes[i].RoomSceneId == localRoomSceneId)
							{
								LocalRoomDetails = response.RoomDetails;
								SafeRaiseLocalRoomUpdated();
							}
						}
					}
					if (roomDetailsCache.TryGetValue(roomScene.RoomId, out var value2))
					{
						value2.Scenes.Remove(roomScene);
						if (value2.Scenes.Count == 0)
						{
							roomDetailsCache.Remove(value2.Room.RoomId);
							Cache.InvalidateEntry(GetMyCreatedRoomsRequestUri);
						}
						else
						{
							SafeRaiseRoomDetailsUpdated(roomScene.RoomId);
						}
					}
				}
			})
				.HandleWithCallback(callback);
		}

		public static IEnumerator ModifyRoomTags(long roomId, List<string> autoTags, List<string> playerAddedTags, Core.ApiCallback<ModifyTagsResponse> callback)
		{
			string requestUri = string.Format("{0}v1/modify/tags", "api/rooms/");
			ModifyTagsRequest modifyTagsRequest = new ModifyTagsRequest();
			modifyTagsRequest.RoomId = roomId;
			modifyTagsRequest.AutoTags = autoTags;
			modifyTagsRequest.CustomTags = playerAddedTags.ConvertAll((string ct) => ct.ToLower()).Distinct().ToList();
			string json = JsonUtility.ToJson(modifyTagsRequest);
			return Core.Post(requestUri, json).ExpectResponse<ModifyTagsResponse>().Then(delegate(ModifyTagsResponse response)
			{
				if (response.Result == RoomTagStatus.Success)
				{
					RoomDetails cachedRoomDetails = GetCachedRoomDetails(roomId);
					if (cachedRoomDetails != null)
					{
						cachedRoomDetails.PlayerAddedTags.Clear();
						cachedRoomDetails.PlayerAddedTags.AddRange(playerAddedTags);
						cachedRoomDetails.AutoTags.Clear();
						cachedRoomDetails.AutoTags.AddRange(autoTags);
					}
				}
			})
				.HandleWithCallback(callback);
		}

