		private static Core.ApiCallback<CreateModifyRoomResponse> ProcessCreateModifyGameResponse(string api, Core.ApiCallback<CreateModifyRoomResponse> callback)
		{
			return delegate(string error, CreateModifyRoomResponse response)
			{
				if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogErrorFormat("RecNet room modify failed ({0}): {1}", api, error);
				}
				else if (response.Result != CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogWarningFormat("RecNet room modify failed ({0}): {1}", api, response.Result);
				}
				else
				{
					StoreRoomDetailsInCache(response.RoomDetails);
				}
				Core.SafeInvoke(callback, error, response);
			};
		}

