		public static IEnumerator ModifyPermission(long roomId, int playerId, RoomPermissionValue? isCoOwner, RoomPermissionValue? isHost, Core.ApiCallback<CreateModifyRoomResponse> callback)
		{
			if (roomDetailsCache.TryGetValue(roomId, out var value))
			{
				RoomPermissionValue playerCoOwnerPermission = value.GetPlayerCoOwnerPermission(playerId);
				RoomPermissionValue playerHostPermission = value.GetPlayerHostPermission(playerId);
				if (playerCoOwnerPermission == isCoOwner.GetValueOrDefault() && isCoOwner.HasValue && playerHostPermission == isHost)
				{
					Core.SafeInvoke(callback, "This player already has these permissions!", null);
					return NoOp();
				}
			}
			string requestUri = string.Format("{0}v2/modifyPermissions", "api/rooms/");
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("PlayerId", playerId);
			dictionary.Add("RoomId", roomId);
			Dictionary<string, object> dictionary2 = dictionary;
			if (isHost.HasValue)
			{
				dictionary2.Add("IsHost", (int)isHost.Value);
			}
			if (isCoOwner.HasValue)
			{
				dictionary2.Add("IsOwner", (int)isCoOwner.Value);
			}
			string json = AmplitudeMiniJSON.Json.Serialize(dictionary2);
			return Core.Post(requestUri, json).ExpectResponse<CreateModifyRoomResponse>().HandleWithCallback(ProcessCreateModifyGameResponse("modify permissions", callback));
		}

		public static IPromise<RoomScene> UploadLocalRoomSceneData(byte[] data, List<string> imageList, List<string> dataBlobList)
		{
			string requestUri = string.Format("{0}v2/saveData/{1}", "api/rooms/", GameSessions.LocalGameSession.RoomSceneId);
			WWWForm wWWForm = new WWWForm();
			wWWForm.AddBinaryData("data", data);
			RoomImageListDTO roomImageListDTO = new RoomImageListDTO();
			roomImageListDTO.roomImageList = imageList;
			string value = JsonUtility.ToJson(roomImageListDTO);
			wWWForm.AddField("imgList", value, Encoding.UTF8);
			DataBlobListDTO dataBlobListDTO = new DataBlobListDTO();
			dataBlobListDTO.dataBlobList = dataBlobList;
			string value2 = JsonUtility.ToJson(dataBlobListDTO);
			wWWForm.AddField("dataBlobList", value2, Encoding.UTF8);
			return Core.Post(requestUri, wWWForm).ExpectResponse<RoomScene>();
		}

		public static IPromise<byte[]> GetRoomData(string dataBlobName)
		{
			return roomDataBlobRequests.GetOrCreatePromise(dataBlobName, delegate
			{
				string requestUri = $"/room/{Uri.EscapeDataString(dataBlobName)}";
				return Core.GetFromCDN(requestUri).ContinueWith<byte[]>(delegate(HTTPResponse response)
				{
					byte[] data = response.Data;
					if (response.StatusCode >= 400)
					{
						UnityEngine.Debug.LogError("Failed to download room data: HTTP Error " + response.StatusCode);
						return new ErroredPromise<byte[]>("Failed to download room data");
					}
					if (data == null || data.Length == 0)
					{
						UnityEngine.Debug.LogError("No room data downloaded");
						return new ErroredPromise<byte[]>("No room data downloaded");
					}
					return new CompletedPromise<byte[]>(data);
				});
			});
		}

		private static void PreCacheRoomDataBlob(RoomScene roomScene)
		{
			if (roomScene != null && !string.IsNullOrEmpty(roomScene.DataBlobName))
			{
				GetRoomData(roomScene.DataBlobName);
			}
		}

		public static IEnumerator CheerRoom(Room room, bool cheer, Core.ApiCallback<OkResponse> callback)
		{
			string requestUri = string.Format("{0}v1/cheer", "api/rooms/");
			CheerRequest cheerRequest = new CheerRequest();
			cheerRequest.Cheer = cheer;
			cheerRequest.RoomId = room.RoomId;
			string json = JsonUtility.ToJson(cheerRequest);
			return Core.Post(requestUri, json).ExpectResponse<OkResponse>().HandleWithCallback(delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error) && response.Success)
				{
					AnalyticsHelper.CheeredRoom();
					Cache.InvalidateEntry(GetPersonalRoomDetailsRequestUri(room.RoomId));
					RoomDetails cachedRoomDetails = GetCachedRoomDetails(room.RoomId);
					if (cachedRoomDetails != null)
					{
						if (cheer)
						{
							cachedRoomDetails.CheerCount++;
						}
						else
						{
							cachedRoomDetails.CheerCount--;
						}
						StoreRoomDetailsInCache(cachedRoomDetails);
					}
					Core.SafeInvoke(callback, error, response);
				}
			});
		}

