		public static IPromise<CanJoinStatus> CheckLocalPlayerCanJoinRoom(Room roomToJoin)
		{
			LocalPlayerController.PlayerType currentPlayerType = SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType;
			if (roomToJoin.CreatorPlayerId == (long)Profiles.LocalProfile.Id)
			{
				return new CompletedPromise<CanJoinStatus>(CanJoinStatus.Success(currentPlayerType));
			}
			return new CompletedPromise<CanJoinStatus>(CanPlayerTypeJoinRoomNoOwnerCheck(currentPlayerType, roomToJoin));
		}

		public static CanJoinStatus CheckPlayerCanJoinRoomDetails(int playerId, LocalPlayerController.PlayerType playerType, RoomDetails roomDetails)
		{
			if (roomDetails == null)
			{
				return CanJoinStatus.Failure(null, "Room is null");
			}
			if (roomDetails.GetPlayerRole(playerId) >= RoomRole.CoOwner)
			{
				return CanJoinStatus.Success(playerType);
			}
			return CanPlayerTypeJoinRoomNoOwnerCheck(playerType, roomDetails.Room);
		}

		private static CanJoinStatus CanPlayerTypeJoinRoomNoOwnerCheck(LocalPlayerController.PlayerType playerType, Room room)
		{
			if (room == null)
			{
				return CanJoinStatus.Failure(null, "Invalid room");
			}
			switch (playerType)
			{
			case LocalPlayerController.PlayerType.SCREEN:
				if (room.SupportsScreens)
				{
					return CanJoinStatus.Success(playerType);
				}
				if (room.SupportsTeleportVR && room.SupportsWalkVR)
				{
					return CanJoinStatus.Failure(null, "VR");
				}
				if (room.SupportsTeleportVR)
				{
					return CanJoinStatus.Failure(null, "Teleport VR");
				}
				if (room.SupportsWalkVR)
				{
					return CanJoinStatus.Failure(null, "Walk VR");
				}
				return CanJoinStatus.Failure(null, "Owner");
			case LocalPlayerController.PlayerType.VR_TELEPORT:
				if (room.SupportsTeleportVR)
				{
					return CanJoinStatus.Success(playerType);
				}
				if (room.SupportsWalkVR && room.SupportsScreens)
				{
					return CanJoinStatus.Failure(LocalPlayerController.PlayerType.VR_WALK, "Walk VR or Screen");
				}
				if (room.SupportsWalkVR)
				{
					return CanJoinStatus.Failure(LocalPlayerController.PlayerType.VR_WALK, "Walk VR");
				}
				if (room.SupportsScreens)
				{
					return CanJoinStatus.Failure(null, "Screen");
				}
				return CanJoinStatus.Failure(null, "Owner");
			case LocalPlayerController.PlayerType.VR_WALK:
				if (room.SupportsWalkVR)
				{
					return CanJoinStatus.Success(playerType);
				}
				if (room.SupportsTeleportVR && room.SupportsScreens)
				{
					return CanJoinStatus.Failure(LocalPlayerController.PlayerType.VR_TELEPORT, "Teleport VR or Screen");
				}
				if (room.SupportsTeleportVR)
				{
					return CanJoinStatus.Failure(LocalPlayerController.PlayerType.VR_TELEPORT, "Teleport VR");
				}
				if (room.SupportsScreens)
				{
					return CanJoinStatus.Failure(null, "Screen");
				}
				return CanJoinStatus.Failure(null, "Owner");
			default:
				UnityEngine.Debug.LogWarning("Invalid PlayerType checked in CanPlayerTypeJoinRoom");
				return CanJoinStatus.Failure(null, "Cannot Join Room");
			}
		}

		public static List<string> GenerateAutoTagsForLocalRoom()
