	public static class Security
	{
		public static string GetAntiTamperHash(long timestamp, string applicationDataPath)
		{
			string text = Assembly.GetExecutingAssembly().Location;
			if (string.IsNullOrEmpty(text))
			{
				text = applicationDataPath + "/../GameAssembly.dll";
			}
			if (!File.Exists(text))
			{
				return null;
			}
			byte[] array = File.ReadAllBytes(text);
			array[array.Length - 1] = (byte)(timestamp / 36000000000L % 256);
			byte[] inArray = SHA256.Create().ComputeHash(array);
			return Convert.ToBase64String(inArray);
		}

		public static string GetAntiTamperHash(string filename)
		{
			SHA256 sHA = SHA256.Create();
			byte[] inArray = sHA.ComputeHash(File.ReadAllBytes(filename));
			return Convert.ToBase64String(inArray);
		}

		public static string GetAntiTamperHash(byte[] bytes)
		{
			byte[] inArray = SHA256.Create().ComputeHash(bytes);
			return Convert.ToBase64String(inArray);
		}
	}
