		}

		public IPromise Open(bool autoReconnect = true)
		{
			Close();
			connectionPromise = new Promise();
			ConnectInternal();
			if (autoReconnect)
			{
				connectionPromise.Then(delegate
				{
					this.autoReconnect = true;
				});
			}
			return connectionPromise;
		}

		public void Close()
		{
			autoReconnect = false;
			if (hub != null)
			{
				hub.StartClose();
				hub = null;
			}
			consecutiveConnectRetries = 0;
			lastDisconnectTime = 0f;
			if (connectionPromise != null)
			{
				connectionPromise.Error("Hub closed before it finished opening");
				connectionPromise = null;
			}
		}

		public void On(string methodName, Action callback)
		{
			hub.On(methodName, callback);
		}

		public void On<T1>(string methodName, Action<T1> callback)
		{
			hub.On(methodName, callback);
		}

		public void On<T1, T2>(string methodName, Action<T1, T2> callback)
		{
			hub.On(methodName, callback);
		}

		public void On<T1, T2, T3>(string methodName, Action<T1, T2, T3> callback)
		{
			hub.On(methodName, callback);
		}

		public IPromise Send(string target, params object[] args)
		{
			if (hub == null)
			{
				return new ErroredPromise("No connection to server");
			}
			if (hub.State != ConnectionStates.Connected)
			{
				return new ErroredPromise($"Hub state not connected ({hub.State})");
			}
			Promise promise = new Promise();
			try
			{
				hub.Send(target, args).OnSuccess(delegate
				{
					promise.Complete();
				}).OnError(delegate(Exception ex2)
				{
					promise.Error(ex2.Message);
				});
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogException(ex);
				promise.Error(ex.Message);
			}
			return promise;
		}

		public IPromise<T> Invoke<T>(string target, params object[] args)
		{
			if (hub == null)
			{
				return new ErroredPromise<T>("No connection to server");
			}
			if (hub.State != ConnectionStates.Connected)
			{
				return new ErroredPromise<T>($"Hub state not connected ({hub.State})");
			}
			Promise<T> promise = new Promise<T>();
			try
			{
				hub.Invoke<T>(target, args).OnSuccess(delegate(T result)
				{
					promise.Complete(result);
				}).OnError(delegate(Exception ex2)
				{
					promise.Error(ex2.Message);
				});
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogException(ex);
				promise.Error(ex.Message);
			}
			return promise;
		}

		private void ConnectInternal()
		{
			if (consecutiveConnectRetries > 0)
			{
				float exponentialBackoffTime = GetExponentialBackoffTime(consecutiveConnectRetries);
				if (UnityEngine.Time.realtimeSinceStartup - lastDisconnectTime < exponentialBackoffTime)
				{
					Core.DispatchOnUnityThread(ConnectInternal);
					return;
				}
			}
			hub = new HubConnection(uri, protocol, hubOptions);
			hub.AuthenticationProvider = new BearerTokenAuthProvider(Login.AccessToken);
			hub.OnConnected += OnConnectedInternal;
			hub.OnClosed += OnClosedInternal;
			hub.OnError += OnErrorInternal;
			hub.StartConnect();
		}

		private void OnConnectedInternal(HubConnection hub)
		{
			if (this.hub == hub)
			{
				consecutiveConnectRetries = 0;
				if (connectionPromise != null)
				{
					connectionPromise.Complete();
					connectionPromise = null;
				}
				SafeRaiseOnOpenEvent();
			}
		}

		private void OnClosedInternal(HubConnection hub)
		{
			if (this.hub == hub)
			{
				HandleSocketClosed();
			}
		}

		private void OnErrorInternal(HubConnection hub, string error)
		{
			if (this.hub == hub)
			{
				UnityEngine.Debug.LogErrorFormat("RecNet HubConnection error: {0}", error);
				HandleSocketClosed();
			}
		}

		private float GetExponentialBackoffTime(int retryCount)
		{
			return (retryCount <= 0) ? 0f : ((float)(1 << Mathf.Min(retryCount - 1, 6)));
		}

		private void HandleSocketClosed()
		{
			hub = null;
			if (connectionPromise != null)
			{
				connectionPromise.Error("Failed to connect");
				connectionPromise = null;
			}
			SafeRaiseOnCloseEvent();
			if (autoReconnect)
			{
				consecutiveConnectRetries++;
				lastDisconnectTime = UnityEngine.Time.realtimeSinceStartup;
				ConnectInternal();
			}
		}

		private void SafeRaiseOnOpenEvent()
		{
			try
			{
				if (OnOpen != null)
				{
					OnOpen(this);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private void SafeRaiseOnCloseEvent()
		{
			try
			{
				if (OnClosed != null)
				{
					OnClosed(this);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
