		public int GetCost(CurrencyType currencyType)
		{
			PurchasablePrice purchasablePrice = Prices.FirstOrDefault((PurchasablePrice pp) => pp.CurrencyType == currencyType);
			if (purchasablePrice == null)
			{
				UnityEngine.Debug.LogError($"{currencyType.ToString()} cost not set for PurchasableGiftDrop id {PurchasableItemId}");
