	public class StorefrontGiftDrop : IRecNetObject, IEquatable<StorefrontGiftDrop>
	{
		public int GiftDropId { get; set; }

		public int Level { get; private set; }

		public string FriendlyName { get; private set; }

		public string Tooltip { get; private set; }

		public string ConsumableItemDesc { get; private set; }

		public string AvatarItemDesc { get; private set; }

		public string EquipmentPrefabName { get; private set; }

		public string EquipmentModificationGuid { get; private set; }

		public bool IsQuery { get; private set; }

		public bool Unique { get; private set; }

		public GiftManager.GiftRarity Rarity { get; private set; }

		public GiftManager.GiftBoxContents Content { get; private set; }

		public GiftManager.GiftContext Context { get; private set; }

		public virtual void Deserialize(Dictionary<string, object> dict)
		{
			GiftDropId = Util.GetKey<int>("GiftDropId", dict);
			FriendlyName = Util.GetKeyOrDefault<string>("FriendlyName", dict);
			Tooltip = Util.GetKeyOrDefault<string>("Tooltip", dict);
			AvatarItemDesc = Util.GetKeyOrDefault<string>("AvatarItemDesc", dict);
			ConsumableItemDesc = Util.GetKeyOrDefault<string>("ConsumableItemDesc", dict);
			EquipmentPrefabName = Util.GetKeyOrDefault<string>("EquipmentPrefabName", dict);
			EquipmentModificationGuid = Util.GetKeyOrDefault<string>("EquipmentModificationGuid", dict);
			Rarity = (GiftManager.GiftRarity)Util.GetKey<int>("Rarity", dict);
			IsQuery = Util.GetKey<bool>("IsQuery", dict);
			Unique = Util.GetKey<bool>("Unique", dict);
			Level = Util.GetKeyOrDefault<int>("Level", dict);
			Context = (GiftManager.GiftContext)Util.GetKeyOrDefault<int>("Context", dict);
			if (!string.IsNullOrEmpty(AvatarItemDesc))
			{
				Content = GiftManager.GiftBoxContents.Avatar;
			}
			else if (!string.IsNullOrEmpty(ConsumableItemDesc))
			{
				Content = GiftManager.GiftBoxContents.Consumable;
			}
			else if (!string.IsNullOrEmpty(EquipmentPrefabName))
			{
				Content = GiftManager.GiftBoxContents.Equipment;
			}
			else if (IsQuery)
			{
				Content = GiftManager.GiftBoxContents.Query;
				int num = 0;
				switch (Rarity)
				{
				case GiftManager.GiftRarity.Common:
					num = 1;
					break;
				case GiftManager.GiftRarity.Uncommon:
					num = 2;
					break;
				case GiftManager.GiftRarity.Rare:
					num = 3;
					break;
				case GiftManager.GiftRarity.Epic:
					num = 4;
					break;
				case GiftManager.GiftRarity.Legendary:
					num = 5;
					break;
				}
				FriendlyName = num + " Star Unique Box";
			}
			else
			{
				Content = GiftManager.GiftBoxContents.Unspecified;
			}
		}

		public bool Equals(StorefrontGiftDrop other)
		{
			return GiftDropId == other.GiftDropId;
		}
	}
