		public override void Deserialize(Dictionary<string, object> dict)
		{
			base.Deserialize(dict);
			TierNumber = Util.GetKey<int>("Tier", dict);
			List<Dictionary<string, object>> listKey = Util.GetListKey<Dictionary<string, object>>("Rewards", dict);
			FreeRewards = new List<PurchasableSeasonTierReward>();
			PaidRewards = new List<PurchasableSeasonTierReward>();
			foreach (PurchasableSeasonTierReward item in listKey.Select(Util.Deserialize<PurchasableSeasonTierReward>))
			{
				if (item.RequiresEliteUpgrade)
				{
					PaidRewards.Add(item);
				}
				else
				{
					FreeRewards.Add(item);
				}
			}
		}
