					onLocalPlayerBalanceUpdatedEvent2 = onLocalPlayerBalanceUpdatedEvent;
					onLocalPlayerBalanceUpdatedEvent = Interlocked.CompareExchange(ref Storefronts.m_OnLocalPlayerBalanceUpdated, (OnLocalPlayerBalanceUpdatedEvent)Delegate.Combine(onLocalPlayerBalanceUpdatedEvent2, value), onLocalPlayerBalanceUpdatedEvent);
				}
				while (onLocalPlayerBalanceUpdatedEvent != onLocalPlayerBalanceUpdatedEvent2);
			}
			remove
			{
				OnLocalPlayerBalanceUpdatedEvent onLocalPlayerBalanceUpdatedEvent = Storefronts.m_OnLocalPlayerBalanceUpdated;
				OnLocalPlayerBalanceUpdatedEvent onLocalPlayerBalanceUpdatedEvent2;
				do
				{
					onLocalPlayerBalanceUpdatedEvent2 = onLocalPlayerBalanceUpdatedEvent;
					onLocalPlayerBalanceUpdatedEvent = Interlocked.CompareExchange(ref Storefronts.m_OnLocalPlayerBalanceUpdated, (OnLocalPlayerBalanceUpdatedEvent)Delegate.Remove(onLocalPlayerBalanceUpdatedEvent2, value), onLocalPlayerBalanceUpdatedEvent);
				}
				while (onLocalPlayerBalanceUpdatedEvent != onLocalPlayerBalanceUpdatedEvent2);
			}
		}

		public static void Initialize()
		{
			Notifications.RegisterHandler(Notifications.PushNotificationId.StorefrontBalanceAdd, OnStorefrontBalanceAddReceived);
			Notifications.RegisterHandler(Notifications.PushNotificationId.StorefrontBalancePurchase, OnStorefrontBalancePurchased);
			Notifications.RegisterHandler(Notifications.PushNotificationId.StorefrontBalanceUpdate, OnStorefrontBalanceUpdated);
		}

		private static void OnStorefrontBalanceUpdated(Dictionary<string, object> message)
		{
			try
			{
				BalanceResponseDTO balanceResponse = Util.Deserialize<BalanceResponseDTO>(message);
				UpdateCachedBalance(balanceResponse);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnStorefrontBalancePurchased(Dictionary<string, object> message)
		{
			try
			{
				PurchaseBalanceModificationDTO purchaseBalanceModificationDTO = Util.Deserialize<PurchaseBalanceModificationDTO>(message);
				UnityEngine.Debug.LogWarning($"Purchased {purchaseBalanceModificationDTO.Delta} {purchaseBalanceModificationDTO.CurrencyType} for {purchaseBalanceModificationDTO.Platform} and now have a total balance of {purchaseBalanceModificationDTO.Balance}");
				UpdateCachedBalance(purchaseBalanceModificationDTO.CurrencyType, purchaseBalanceModificationDTO.Platform, purchaseBalanceModificationDTO.Balance);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void OnStorefrontBalanceAddReceived(Dictionary<string, object> message)
		{
			try
			{
				BalanceUpdateResponseDTO<RewardBalanceModificationDTO> balanceUpdateResponseDTO = Util.Deserialize<BalanceUpdateResponseDTO<RewardBalanceModificationDTO>>(message);
				CurrencyType currencyType = balanceUpdateResponseDTO.CurrencyType;
				if (balanceUpdateResponseDTO.BalanceUpdates.Count > 0 && SingletonMonoBehaviour<CurrencyManager>.Instance != null)
				{
					foreach (BalanceUpdateResponseDTO<RewardBalanceModificationDTO>.BalanceUpdateDTO balanceUpdate in balanceUpdateResponseDTO.BalanceUpdates)
					{
						if (balanceUpdate != null && balanceUpdate.Data != null)
						{
							RewardBalanceModificationDTO data = balanceUpdate.Data;
							if (data != null && !data.BalanceInGiftBox && data.BalanceAddType != StorefrontBalanceAddTypes.FromGiftBox)
							{
								int baseAward = data.BaseAward;
								int bonusAward = data.BonusAward;
								int currentCount = data.CurrentCount;
								int rateLimit = data.RateLimit;
								StorefrontBalanceAddTypes balanceAddType = data.BalanceAddType;
								SingletonMonoBehaviour<CurrencyManager>.Instance.ReceiveCurrencyAwardDirectly(Player.LocalPlayer, baseAward, bonusAward, currentCount, rateLimit, balanceAddType, currencyType);
							}
						}
					}
				}
				UpdateCachedBalance(balanceUpdateResponseDTO);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		public static IPromise<GiftDropStorefront> GetStorefront(StorefrontTypes storefrontType)
		{
			if (storefrontCacheExpirationMap.TryGetValue(storefrontType, out var value) && DateTime.UtcNow >= value && cachedStorefront.ContainsKey(storefrontType))
			{
				cachedStorefront.Remove(storefrontType);
				storefrontCacheExpirationMap.Remove(storefrontType);
			}
			return cachedStorefront.GetOrCreatePromise(storefrontType, delegate
			{
				string requestUri = string.Format("{0}v3/giftdropstore/{1}", "api/storefronts/", (int)storefrontType);
				return Core.Get(requestUri, executeSerially: false).ExpectResponse<GiftDropStorefront>().ContinueWith((Func<GiftDropStorefront, IPromise<GiftDropStorefront>>)((GiftDropStorefront response) => (response == null) ? ((Promise<GiftDropStorefront>)new ErroredPromise<GiftDropStorefront>("No storefront data downloaded for " + storefrontType)) : ((Promise<GiftDropStorefront>)new CompletedPromise<GiftDropStorefront>(response))))
					.Then(delegate(GiftDropStorefront storefront)
					{
						if (storefront != null)
						{
							storefrontCacheExpirationMap[storefront.StorefrontType] = storefront.NextUpdate;
							if (storefrontType == StorefrontTypes.Watch)
							{
								storefront.StoreItems = storefront.StoreItems.OrderBy((PurchasableGiftDrop pgd) => pgd.GiftDrops[0].FriendlyName).ToList();
							}
						}
					});
			});
		}

		public static IEnumerator DownloadWatchGiftDropStorefront(Core.ApiCallback callback)
		{
			yield return GetStorefront(StorefrontTypes.Watch).HandleWithCallback(callback);
		}

		public static IEnumerator DownloadStorefrontSeason(StorefrontTypes storefrontType, Core.ApiCallback<StorefrontSeasonDTO> callback)
		{
			if (CurrentSeason != null)
			{
				Core.SafeInvoke(callback, null, CurrentSeason);
				return null;
			}
			string requestUri = string.Format("{0}v1/season/{1}", "api/storefronts/", (int)storefrontType);
			return Core.Get(requestUri, executeSerially: false).ExpectResponse<StorefrontSeasonDTO>(treat404NotFoundAsNull: false, treatEmptyResponseAsNull: true).Then(delegate(StorefrontSeasonDTO season)
			{
				CurrentSeason = season;
			})
				.HandleWithCallback(callback);
		}

		public static void CompleteObjectives(List<StorefrontObjectiveCompletionRecord> objectiveCompletionRecords)
		{
			if (objectiveCompletionRecords == null || objectiveCompletionRecords.Count == 0)
			{
				return;
			}
			string requestUri = string.Format("{0}v1/objectives", "api/storefronts/");
			List<Dictionary<string, object>> list = new List<Dictionary<string, object>>();
			foreach (StorefrontObjectiveCompletionRecord objectiveCompletionRecord in objectiveCompletionRecords)
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				dictionary.Add("objectiveType", (int)objectiveCompletionRecord.objectiveType);
				dictionary.Add("completionPercentage", objectiveCompletionRecord.completionPercentage);
				if (objectiveCompletionRecord.roomId.HasValue)
				{
					dictionary.Add("roomId", objectiveCompletionRecord.roomId.Value);
				}
				list.Add(dictionary);
			}
			string json = AmplitudeMiniJSON.Json.Serialize(list);
			Core.Post(requestUri, json).ExpectHttpStatusSuccess().LogErrors("Failed to complete storefront objectives");
		}

