		public static long? GetBalance(CurrencyType currencyType)
		{
			if (CachedBalances.TryGetValue(currencyType, out var value))
			{
				return SumUsableBalances(value);
			}
			FetchBalance(currencyType);
			return null;
		}

		private static long SumUsableBalances(Dictionary<PlatformManager.PlatformType, long> platformBalances)
		{
			return platformBalances.Where((KeyValuePair<PlatformManager.PlatformType, long> x) => SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform.CanBeUsedByPlatform(x.Key)).Sum((KeyValuePair<PlatformManager.PlatformType, long> x) => x.Value);
		}

		public static bool HasLockedBalance(CurrencyType currencyType)
		{
			if (CachedBalances.TryGetValue(currencyType, out var value))
			{
				return value.Any((KeyValuePair<PlatformManager.PlatformType, long> pb) => !SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform.CanBeUsedByPlatform(pb.Key));
			}
			return false;
		}

		private static void UpdateCachedBalance(BalanceResponseDTO balanceResponse)
		{
			UpdateCachedBalance(balanceResponse.CurrencyType, balanceResponse.Platform, balanceResponse.Balance);
		}

		private static void UpdateCachedBalance(CurrencyType currencyType, PlatformManager.PlatformType platform, long balance)
		{
			Dictionary<PlatformManager.PlatformType, long> value = null;
			if (!CachedBalances.TryGetValue(currencyType, out value))
			{
				value = new Dictionary<PlatformManager.PlatformType, long>();
				CachedBalances[currencyType] = value;
			}
			value[platform] = balance;
			long balance2 = SumUsableBalances(value);
			RaiseBalanceUpdatedEvent(currencyType, balance2);
		}

		private static long UpdateCachedBalances(List<BalanceResponseDTO> responses)
		{
			if (responses.Count > 0)
			{
				Dictionary<PlatformManager.PlatformType, long> dictionary = responses.ToDictionary((BalanceResponseDTO x) => x.Platform, (BalanceResponseDTO x) => x.Balance);
				CurrencyType currencyType = responses[0].CurrencyType;
				CachedBalances[currencyType] = dictionary;
				long num = SumUsableBalances(dictionary);
				RaiseBalanceUpdatedEvent(currencyType, num);
				return num;
			}
			return 0L;
		}

		public static void FetchBalance(CurrencyType currencyType, Core.ApiCallback<long> callback = null)
		{
			string requestUri = string.Format("{0}v4/balance/{1}", "api/storefronts/", (int)currencyType);
			Core.Get(requestUri, executeSerially: false).ExpectListResponse<BalanceResponseDTO>().HandleWithCallback(ParseListBalanceUpdateResponse(callback));
		}

		public static void FetchBalanceAddConfig(CurrencyType currencyType, StorefrontBalanceAddTypes balanceAddType, Core.ApiCallback<StorefrontBalanceAddConfigDTO> callback = null)
		{
			string requestUri = string.Format("{0}v1/balanceAddType/{1}/{2}", "api/storefronts/", (int)currencyType, (int)balanceAddType);
			Core.Get(requestUri, executeSerially: false).ExpectResponse<StorefrontBalanceAddConfigDTO>(treat404NotFoundAsNull: false, treatEmptyResponseAsNull: true).HandleWithCallback(callback);
		}

		public static IEnumerator ModifyBalance(CurrencyType currencyType, IEnumerable<GrantBalanceRequest> balanceAdds, Core.ApiCallback<BalanceUpdateResponseDTO<RewardBalanceModificationDTO>> callback)
		{
			string requestUri = string.Format("{0}v2/balance", "api/storefronts/");
			GrantBalanceRewardDTO grantBalanceRewardDTO = new GrantBalanceRewardDTO();
			grantBalanceRewardDTO.CurrencyType = currencyType;
			grantBalanceRewardDTO.BalanceAdds = balanceAdds.ToList();
			string json = JsonUtility.ToJson(grantBalanceRewardDTO);
			return Core.Post(requestUri, json).ExpectResponse<BalanceUpdateResponseDTO<RewardBalanceModificationDTO>>().HandleWithCallback(ParseBalanceUpdateResponse(callback));
		}

		private static Core.ApiCallback<T> ParseBalanceUpdateResponse<T>(Core.ApiCallback<T> callback) where T : BalanceResponseDTO
		{
			return delegate(string error, T response)
			{
				if (string.IsNullOrEmpty(error))
				{
					UpdateCachedBalance(response);
				}
				Core.SafeInvoke(callback, error, response);
			};
		}

		private static Core.ApiCallback<List<BalanceResponseDTO>> ParseListBalanceUpdateResponse(Core.ApiCallback<long> callback)
		{
			return delegate(string error, List<BalanceResponseDTO> responses)
			{
				long response = 0L;
				if (string.IsNullOrEmpty(error))
				{
					response = UpdateCachedBalances(responses);
				}
				Core.SafeInvoke(callback, error, response);
			};
		}

		private static void RaiseBalanceUpdatedEvent(CurrencyType currencyType, long balance)
		{
			try
			{
				if (Storefronts.OnLocalPlayerBalanceUpdated != null)
				{
					Storefronts.OnLocalPlayerBalanceUpdated(currencyType, balance);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		static Storefronts()
		{
			Storefronts.OnLocalPlayerBalanceUpdated = null;
			storefrontCacheExpirationMap = new Dictionary<StorefrontTypes, DateTime>();
			cachedStorefront = new PromiseCache<StorefrontTypes>(50, cacheErrors: false);
			CachedBalances = new Dictionary<CurrencyType, Dictionary<PlatformManager.PlatformType, long>>();
		}
	}
	public class StringSanitization
	{
		[Serializable]
		public class SanitizeStringRequest
		{
			public string Value = string.Empty;
		}

		public class IsPureStringResponse : IRecNetObject
		{
			public bool IsPure { get; set; }

			public void Deserialize(Dictionary<string, object> dict)
			{
				IsPure = Util.GetKey<bool>("IsPure", dict);
			}
		}

		private const string SANITATION_API = "api/sanitize/";

		public static IEnumerator RequestIsStringPure(string stringValue, Core.ApiCallback<IsPureStringResponse> callback)
		{
			RecNetUrlBuilder recNetUrlBuilder = new RecNetUrlBuilder("api/sanitize/", 1, "isPure");
			string requestUri = recNetUrlBuilder.Build();
			SanitizeStringRequest sanitizeStringRequest = new SanitizeStringRequest();
			sanitizeStringRequest.Value = stringValue;
			string json = JsonUtility.ToJson(sanitizeStringRequest);
			return Core.Post(requestUri, json).ExpectResponse<IsPureStringResponse>().HandleWithCallback(delegate(string e, IsPureStringResponse r)
			{
				if (!string.IsNullOrEmpty(e))
				{
					UnityEngine.Debug.LogError("Error checking string:" + e);
				}
				Core.SafeInvoke(callback, e, r);
			});
		}
	}
	public class TestPass : IRecNetObject
	{
		public int Id;

		public string Name;

		public string Description;

		public DateTime StartDate;

		public DateTime EndDate;

		public bool WasManuallyClosed;

		public List<TestCase> TestCases;

		public List<string> Tags;

		public bool IsClosed
		{
			get
			{
				if (WasManuallyClosed)
				{
					return true;
				}
				DateTime utcNow = DateTime.UtcNow;
				return utcNow < StartDate || utcNow > EndDate;
			}
		}

		public void Deserialize(Dictionary<string, object> dict)
		{
			Id = Util.GetKey<int>("Id", dict);
			Name = Util.GetKey<string>("Name", dict);
			Description = Util.GetKey<string>("Description", dict);
			StartDate = Util.GetDateTimeKey("StartDate", dict);
			EndDate = Util.GetDateTimeKey("EndDate", dict);
			WasManuallyClosed = Util.GetKey<bool>("WasManuallyClosed", dict);
			TestCases = Util.GetObjectListKey<TestCase>("TestCases", dict);
			Tags = Util.GetListKey<string>("Tags", dict);
		}
