	public class Util
	{
		public static T Deserialize<T>(string json) where T : IRecNetObject, new()
		{
			return Deserialize<T>((Dictionary<string, object>)AmplitudeMiniJSON.Json.Deserialize(json));
		}

		public static T DeserializeNullable<T>(string json) where T : IRecNetObject, new()
		{
			Dictionary<string, object> dictionary = (Dictionary<string, object>)AmplitudeMiniJSON.Json.Deserialize(json);
			int? num = dictionary?.Count;
			return (!num.HasValue || num.GetValueOrDefault() <= 0) ? default(T) : Deserialize<T>(dictionary);
		}

		public static T Deserialize<T>(Dictionary<string, object> dict) where T : IRecNetObject, new()
		{
			T result = new T();
			result.Deserialize(dict);
			return result;
		}

		public static List<T> DeserializeList<T>(string json) where T : IRecNetObject, new()
		{
			return DeserializeList<T>((List<object>)AmplitudeMiniJSON.Json.Deserialize(json));
		}

		public static List<T> DeserializeList<T>(List<object> objList) where T : IRecNetObject, new()
		{
			if (objList == null)
			{
				return null;
			}
			List<T> list = new List<T>(objList.Count);
			foreach (object obj in objList)
			{
				Dictionary<string, object> dict = (Dictionary<string, object>)obj;
				list.Add(Deserialize<T>(dict));
			}
			return list;
		}

		public static float GetFormattedFloatKey(string key, Dictionary<string, object> dict)
		{
			string key2 = GetKey<string>(key, dict);
			return float.Parse(key2, NumberStyles.Any, CultureInfo.InvariantCulture);
		}

		public static T GetKey<T>(string key, Dictionary<string, object> dict)
		{
			return (T)Convert.ChangeType(dict[key], typeof(T), CultureInfo.InvariantCulture);
		}

		public static T GetKeyOrDefault<T>(string key, Dictionary<string, object> dict)
		{
			if (dict.ContainsKey(key) && dict[key] != null)
			{
				System.Type typeFromHandle = typeof(T);
				typeFromHandle = Nullable.GetUnderlyingType(typeFromHandle) ?? typeFromHandle;
				return (T)Convert.ChangeType(dict[key], typeFromHandle, CultureInfo.InvariantCulture);
			}
			return default(T);
		}

		public static List<T> GetListKey<T>(string key, Dictionary<string, object> dict)
		{
			List<object> list = (List<object>)dict[key];
			List<T> list2 = new List<T>(list.Count);
			foreach (object item in list)
			{
				list2.Add((T)Convert.ChangeType(item, typeof(T), CultureInfo.InvariantCulture));
			}
			return list2;
		}

		public static List<T> GetListKeyOrNull<T>(string key, Dictionary<string, object> dict)
		{
			if (dict.TryGetValue(key, out var value) && value != null)
			{
				List<object> list = (List<object>)value;
				List<T> list2 = new List<T>(list.Count);
				{
					foreach (object item in list)
					{
						list2.Add((T)Convert.ChangeType(item, typeof(T), CultureInfo.InvariantCulture));
					}
					return list2;
				}
			}
			return null;
		}

		public static T GetObjectKey<T>(string key, Dictionary<string, object> dict) where T : IRecNetObject, new()
		{
			if (dict.ContainsKey(key) && dict[key] != null)
			{
				Dictionary<string, object> dict2 = (Dictionary<string, object>)dict[key];
				return Deserialize<T>(dict2);
			}
			return default(T);
		}

		public static List<T> GetObjectListKey<T>(string key, Dictionary<string, object> dict) where T : IRecNetObject, new()
		{
			List<object> objList = (List<object>)dict[key];
			return DeserializeList<T>(objList);
		}

		public static DateTime GetDateTimeKey(string key, Dictionary<string, object> dict)
		{
			if (dict[key] is string)
			{
				string key2 = GetKey<string>(key, dict);
				DateTime dateTime = DateTime.Parse(key2, CultureInfo.InvariantCulture);
				return dateTime.Kind switch
				{
					DateTimeKind.Local => dateTime.ToUniversalTime(), 
					DateTimeKind.Unspecified => DateTime.SpecifyKind(dateTime, DateTimeKind.Utc), 
					_ => dateTime, 
				};
			}
			long key3 = GetKey<long>(key, dict);
			return new DateTime(key3, DateTimeKind.Utc);
		}

		public static DateTime? GetDateTimeKeyOrDefault(string key, Dictionary<string, object> dict)
		{
			return (!dict.ContainsKey(key) || dict[key] == null) ? ((DateTime?)null) : new DateTime?(GetDateTimeKey(key, dict));
		}
	}
	public class RecNetUrlBuilder
	{
		private readonly string apiBase;

		private readonly int version;

		private readonly string[] pathParts;

		private readonly List<KeyValuePair<string, string>> queryParams = new List<KeyValuePair<string, string>>();

		public RecNetUrlBuilder(string apiBase, int version, params string[] pathParts)
		{
			if (pathParts.Length == 0)
			{
				throw new InvalidOperationException("Must supply at least one Path part for RecNet API Url");
			}
			this.apiBase = SanitizePart(apiBase);
			this.pathParts = pathParts.Select((string pp) => SanitizePart(pp)).ToArray();
			this.version = version;
		}

		private string SanitizePart(string part)
		{
			return part.Trim().Trim('/');
		}

		public RecNetUrlBuilder WithQueryParam(string key, int value)
		{
			return WithQueryParam(key, value.ToString());
		}

		public RecNetUrlBuilder WithQueryParam(string key, long value)
		{
			return WithQueryParam(key, value.ToString());
		}

		public RecNetUrlBuilder WithQueryParam(string key, string value)
		{
			if (!string.IsNullOrEmpty(value))
			{
				queryParams.Add(new KeyValuePair<string, string>(key, value));
			}
			return this;
		}

		public RecNetUrlBuilder WithQueryParam(string key, IEnumerable<int> values)
		{
			return WithQueryParam(key, values.Select((int v) => v.ToString()));
		}

		public RecNetUrlBuilder WithQueryParam(string key, IEnumerable<long> values)
		{
			return WithQueryParam(key, values.Select((long v) => v.ToString()));
		}

		public RecNetUrlBuilder WithQueryParam(string key, IEnumerable<string> values)
		{
			foreach (string value in values)
			{
				if (!string.IsNullOrEmpty(value))
				{
					queryParams.Add(new KeyValuePair<string, string>(key, value));
				}
			}
			return this;
		}

		public string Build()
		{
			string text = string.Join("/", pathParts);
			return $"/{apiBase}/v{version}/{text}{GetQueryString()}";
		}

		private string GetQueryString()
		{
			if (queryParams.Count == 0)
			{
				return string.Empty;
			}
			string[] value = queryParams.Select((KeyValuePair<string, string> kvp) => $"{Uri.EscapeDataString(kvp.Key)}={Uri.EscapeDataString(kvp.Value)}").ToArray();
			return "?" + string.Join("&", value);
		}
	}
	public class WebSocket
	{
		private const int MAX_BACKOFF_EXPONENT = 6;

		public Action<WebSocket> OnOpen;

		public Action<WebSocket> OnClosed;

		public Action<WebSocket, string> OnMessage;

		private Uri uri;

		private BestHTTP.WebSocket.WebSocket socket;

		private int consecutiveConnectRetries;

		private float lastDisconnectTime;

		private bool autoReconnect;

		private Promise connectionPromise;

		public bool IsOpen => socket != null && socket.IsOpen;

		public WebSocket(Uri uri)
		{
			this.uri = uri;
		}

		public IPromise Open(bool autoReconnect = true)
		{
			Close();
			connectionPromise = new Promise();
			ConnectInternal();
			if (autoReconnect)
			{
				connectionPromise.Then(delegate
				{
					this.autoReconnect = true;
				});
			}
			return connectionPromise;
		}

		public void Close()
		{
			autoReconnect = false;
			if (socket != null)
			{
				socket.Close();
				socket = null;
			}
			consecutiveConnectRetries = 0;
			lastDisconnectTime = 0f;
			if (connectionPromise != null)
			{
				connectionPromise.Error("Socket closed before it finished opening");
				connectionPromise = null;
			}
		}

		public void Send(string message)
		{
			if (socket != null)
			{
				socket.Send(message);
			}
		}

		private void ConnectInternal()
		{
			if (consecutiveConnectRetries > 0)
			{
				float exponentialBackoffTime = GetExponentialBackoffTime(consecutiveConnectRetries);
				if (UnityEngine.Time.realtimeSinceStartup - lastDisconnectTime < exponentialBackoffTime)
				{
					Core.DispatchOnUnityThread(ConnectInternal);
					return;
				}
			}
			socket = new BestHTTP.WebSocket.WebSocket(uri);
			socket.InternalRequest.SetHeader("Authorization", "Bearer " + Login.AccessToken);
			BestHTTP.WebSocket.WebSocket webSocket = socket;
			webSocket.OnOpen = (OnWebSocketOpenDelegate)Delegate.Combine(webSocket.OnOpen, new OnWebSocketOpenDelegate(OnOpenInternal));
			BestHTTP.WebSocket.WebSocket webSocket2 = socket;
			webSocket2.OnClosed = (OnWebSocketClosedDelegate)Delegate.Combine(webSocket2.OnClosed, new OnWebSocketClosedDelegate(OnClosedInternal));
			BestHTTP.WebSocket.WebSocket webSocket3 = socket;
			webSocket3.OnError = (OnWebSocketErrorDelegate)Delegate.Combine(webSocket3.OnError, new OnWebSocketErrorDelegate(OnErrorInternal));
			BestHTTP.WebSocket.WebSocket webSocket4 = socket;
			webSocket4.OnMessage = (OnWebSocketMessageDelegate)Delegate.Combine(webSocket4.OnMessage, new OnWebSocketMessageDelegate(OnMessageInternal));
			socket.Open();
		}

		private void OnOpenInternal(BestHTTP.WebSocket.WebSocket webSocket)
		{
			if (webSocket == socket)
			{
				consecutiveConnectRetries = 0;
				if (connectionPromise != null)
				{
					connectionPromise.Complete();
					connectionPromise = null;
				}
				SafeRaiseOnOpenEvent();
			}
		}

		private void OnClosedInternal(BestHTTP.WebSocket.WebSocket webSocket, ushort code, string message)
		{
			if (webSocket == socket)
			{
				HandleSocketClosed();
			}
		}

		private void OnErrorInternal(BestHTTP.WebSocket.WebSocket webSocket, Exception ex)
		{
			if (webSocket == socket)
			{
				if (ex != null)
				{
					UnityEngine.Debug.LogException(ex);
				}
				else
				{
					UnityEngine.Debug.LogError("RecNet WebSocket error");
				}
				if (!webSocket.IsOpen)
				{
					HandleSocketClosed();
				}
			}
		}

		private void OnMessageInternal(BestHTTP.WebSocket.WebSocket webSocket, string message)
		{
			if (webSocket == socket)
			{
				SafeRaiseOnMessageEvent(message);
			}
		}

		private float GetExponentialBackoffTime(int retryCount)
		{
			return (retryCount <= 0) ? 0f : ((float)(1 << Mathf.Min(retryCount - 1, 6)));
		}

		private void HandleSocketClosed()
		{
			socket = null;
			if (connectionPromise != null)
			{
				connectionPromise.Error("Failed to connect");
				connectionPromise = null;
			}
			SafeRaiseOnCloseEvent();
			if (autoReconnect)
			{
				consecutiveConnectRetries++;
				lastDisconnectTime = UnityEngine.Time.realtimeSinceStartup;
				ConnectInternal();
			}
		}

		private void SafeRaiseOnOpenEvent()
		{
			try
			{
				if (OnOpen != null)
				{
					OnOpen(this);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private void SafeRaiseOnCloseEvent()
		{
			try
			{
				if (OnClosed != null)
				{
					OnClosed(this);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private void SafeRaiseOnMessageEvent(string message)
		{
			try
			{
				if (OnMessage != null)
				{
					OnMessage(this, message);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}
}
namespace RecRoom.Core.Creation.Shapes
{
	public class BatchedMeshRenderer : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private bool receiveShadows = true;

		[SerializeField]
		private ShadowCastingMode shadowCastingMode = ShadowCastingMode.On;

		private Dictionary<Material, List<BatchedMesh>> materialToBatchedMeshes = new Dictionary<Material, List<BatchedMesh>>();

		private List<BatchedMesh> batchedMeshes = new List<BatchedMesh>();

		private List<MeshRenderer> meshRenderers = new List<MeshRenderer>();

		private bool isDirty;

		private Dictionary<int, float> customFloatProperties = new Dictionary<int, float>(0);

		private Dictionary<int, Color> customColorProperties = new Dictionary<int, Color>(0);

		private Dictionary<int, Vector4> customVectorProperties = new Dictionary<int, Vector4>(0);

		private Dictionary<int, Matrix4x4> customMatrixProperties = new Dictionary<int, Matrix4x4>(0);

		public int TotalEntryCount
		{
			get
			{
				int num = 0;
				foreach (BatchedMesh batchedMesh in batchedMeshes)
				{
					num += batchedMesh.EntryCount;
				}
				return num;
			}
		}

		public IReadOnlyList<MeshRenderer> MeshRenderers => meshRenderers;

		public void AddToBatchedMesh(DynamicMesh newMesh, Material material, Matrix4x4 meshTransformation)
		{
			BatchedMesh bestFitBatchedMesh = GetBestFitBatchedMesh(newMesh, material);
			bestFitBatchedMesh.AddMesh(newMesh, meshTransformation);
			MarkDirty();
		}

		public void RemoveFromBatchedMesh(DynamicMesh mesh)
		{
			foreach (BatchedMesh batchedMesh in batchedMeshes)
			{
				if (batchedMesh.RemoveMesh(mesh))
				{
					MarkDirty();
					break;
				}
			}
		}

		public void UpdateMeshColor(DynamicMesh mesh, Color color)
		{
			foreach (BatchedMesh batchedMesh in batchedMeshes)
			{
				if (batchedMesh.UpdateMeshColor(mesh, color))
				{
					MarkDirty();
					break;
				}
			}
		}

		public void UpdateMeshVertices(DynamicMesh mesh, Matrix4x4 meshTransformation)
		{
			foreach (BatchedMesh batchedMesh in batchedMeshes)
			{
				if (batchedMesh.UpdateMeshVertices(mesh, meshTransformation))
				{
					MarkDirty();
					break;
				}
			}
		}

		public void MoveBatchedMeshes(Vector3 movement)
		{
			if (batchedMeshes.Count <= 0)
			{
				return;
			}
			foreach (BatchedMesh batchedMesh in batchedMeshes)
			{
				batchedMesh.Move(movement);
			}
			MarkDirty();
		}

		public void SetMaterialProperty(int propertyId, Color color)
		{
			customColorProperties[propertyId] = color;
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			foreach (MeshRenderer meshRenderer in MeshRenderers)
			{
				meshRenderer.GetPropertyBlock(materialPropertyBlock);
				materialPropertyBlock.SetColor(propertyId, color);
				meshRenderer.SetPropertyBlock(materialPropertyBlock);
			}
		}

		public void SetMaterialProperty(int propertyId, float value)
		{
			customFloatProperties[propertyId] = value;
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			foreach (MeshRenderer meshRenderer in MeshRenderers)
			{
				meshRenderer.GetPropertyBlock(materialPropertyBlock);
				materialPropertyBlock.SetFloat(propertyId, value);
				meshRenderer.SetPropertyBlock(materialPropertyBlock);
			}
		}

		public void SetMaterialProperty(int propertyId, Vector4 vector)
		{
			customVectorProperties[propertyId] = vector;
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			foreach (MeshRenderer meshRenderer in MeshRenderers)
			{
				meshRenderer.GetPropertyBlock(materialPropertyBlock);
				materialPropertyBlock.SetVector(propertyId, vector);
				meshRenderer.SetPropertyBlock(materialPropertyBlock);
			}
		}

		public void SetMaterialProperty(int propertyId, Matrix4x4 matrix)
		{
			customMatrixProperties[propertyId] = matrix;
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			foreach (MeshRenderer meshRenderer in MeshRenderers)
			{
				meshRenderer.GetPropertyBlock(materialPropertyBlock);
				materialPropertyBlock.SetMatrix(propertyId, matrix);
				meshRenderer.SetPropertyBlock(materialPropertyBlock);
			}
		}

		private void SetCachedMaterialProperties(Renderer renderer)
		{
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			renderer.GetPropertyBlock(materialPropertyBlock);
			foreach (KeyValuePair<int, float> customFloatProperty in customFloatProperties)
			{
				materialPropertyBlock.SetFloat(customFloatProperty.Key, customFloatProperty.Value);
			}
			foreach (KeyValuePair<int, Color> customColorProperty in customColorProperties)
			{
				materialPropertyBlock.SetColor(customColorProperty.Key, customColorProperty.Value);
			}
			foreach (KeyValuePair<int, Matrix4x4> customMatrixProperty in customMatrixProperties)
			{
				materialPropertyBlock.SetMatrix(customMatrixProperty.Key, customMatrixProperty.Value);
			}
			foreach (KeyValuePair<int, Vector4> customVectorProperty in customVectorProperties)
			{
				materialPropertyBlock.SetVector(customVectorProperty.Key, customVectorProperty.Value);
			}
			renderer.SetPropertyBlock(materialPropertyBlock);
		}

		private void UpdateBatchedMeshOnGPU()
		{
			if (!isDirty)
			{
				return;
			}
			foreach (BatchedMesh batchedMesh in batchedMeshes)
			{
				batchedMesh.CopyChangesToGPU();
			}
			isDirty = false;
		}

		private BatchedMesh GetBestFitBatchedMesh(DynamicMesh mesh, Material material)
		{
			int count = mesh.Vertices.Count;
			BatchedMesh batchedMesh = null;
			if (materialToBatchedMeshes.TryGetValue(material, out var value))
			{
				foreach (BatchedMesh item in value)
				{
					if (item.Vertices.Count + count < 65000)
					{
						batchedMesh = item;
						break;
					}
				}
			}
			if (batchedMesh == null)
			{
				batchedMesh = CreateNewBatchedMesh(material);
			}
			return batchedMesh;
		}

		private BatchedMesh CreateNewBatchedMesh(Material material)
		{
			string text = $"{base.gameObject.name} (BatchedMesh - {material?.name})";
			BatchedMesh batchedMesh = new BatchedMesh(text);
			batchedMeshes.Add(batchedMesh);
			if (!materialToBatchedMeshes.TryGetValue(material, out var value))
			{
				value = new List<BatchedMesh>(1);
				materialToBatchedMeshes[material] = value;
			}
			value.Add(batchedMesh);
			GameObject gameObject = new GameObject(text);
			gameObject.transform.SetParent(base.transform, worldPositionStays: false);
			MeshFilter meshFilter = gameObject.AddComponent<MeshFilter>();
			meshFilter.sharedMesh = batchedMesh.Mesh;
			MeshRenderer meshRenderer = gameObject.AddComponent<MeshRenderer>();
			meshRenderer.sharedMaterial = material;
			meshRenderer.receiveShadows = receiveShadows;
			meshRenderer.shadowCastingMode = shadowCastingMode;
			meshRenderers.Add(meshRenderer);
			SetCachedMaterialProperties(meshRenderer);
			return batchedMesh;
		}

		private void MarkDirty()
		{
			if (!isDirty)
			{
				isDirty = true;
				this.InvokeNextLateUpdate(UpdateBatchedMeshOnGPU);
			}
		}
	}
	public class Curve
	{
		public List<ControlPoint> ControlPoints { get; private set; }

		public float Distance
		{
			get
			{
				float num = 0f;
				if (ControlPoints.Count > 1)
				{
					for (int i = 1; i < ControlPoints.Count; i++)
					{
						num += (ControlPoints[i].Position - ControlPoints[i - 1].Position).magnitude;
					}
				}
				return num;
			}
		}

		public Curve()
		{
			ControlPoints = new List<ControlPoint>();
		}

		public void AddControlPoint(Vector3 position, Vector3 normal, float radius)
		{
			ControlPoints.Add(default(ControlPoint));
			int num = ControlPoints.Count - 1;
			UpdateControlPoint(num, position, normal, radius);
			if (num == 1)
			{
				UpdateControlPoint(0, ControlPoints[0].Position, ControlPoints[0].Normal, ControlPoints[0].Radius);
			}
		}

		public void RemoveControlPoint(int controlPointIndex)
		{
			if (controlPointIndex >= 0 && controlPointIndex < ControlPoints.Count)
			{
				ControlPoints.RemoveAt(controlPointIndex);
				for (int i = controlPointIndex; i < ControlPoints.Count; i++)
				{
					UpdateControlPoint(i, ControlPoints[i].Position, ControlPoints[i].Normal, ControlPoints[i].Radius);
				}
			}
		}

		public void UpdateControlPoint(int controlPointIndex, Vector3 position, Vector3 normal, float radius)
		{
			if (controlPointIndex < 0 || controlPointIndex >= ControlPoints.Count)
			{
				UnityEngine.Debug.LogErrorFormat("Cannot update control point {0} in curve.", controlPointIndex);
				return;
			}
			ControlPoint value = ControlPoints[controlPointIndex];
			value.Position = position;
			value.Radius = radius;
			int num = controlPointIndex - 1;
			if (num >= 0)
			{
				ControlPoint value2 = ControlPoints[num];
				Vector3 normalized = (value.Position - value2.Position).normalized;
				if (normalized.magnitude >= Mathf.Epsilon)
				{
					value2.Tangent = normalized;
					int num2 = num - 1;
					if (num2 >= 0)
					{
						ControlPoint controlPoint = ControlPoints[num2];
						Quaternion quaternion = Quaternion.identity;
						Vector3 axis = Vector3.Cross(controlPoint.Tangent, value2.Tangent);
						if (axis.magnitude > Mathf.Epsilon)
						{
							axis.Normalize();
							float angle = Vector3.Angle(controlPoint.Tangent, value2.Tangent);
							quaternion = Quaternion.AngleAxis(angle, axis);
						}
						if (Mathf.Abs(Vector3.Dot(value2.Tangent, normal)) < 0.8f)
						{
							float num3 = Vector3.SignedAngle(Vector3.ProjectOnPlane(controlPoint.Normal, value2.Tangent), Vector3.ProjectOnPlane(normal, value2.Tangent), value2.Tangent);
							if (Mathf.Abs(num3) > Mathf.Epsilon)
							{
								quaternion = Quaternion.AngleAxis(num3, value2.Tangent) * quaternion;
							}
						}
						value2.Normal = (quaternion * controlPoint.Normal).normalized;
						float num4 = Vector3.Dot(controlPoint.Normal, value2.Normal);
						if (num4 < 0f)
						{
							value2.Normal = -value2.Normal;
						}
					}
					else
					{
						float num5 = Mathf.Abs(Vector3.Dot(value2.Tangent, value2.Normal));
						if (num5 >= Mathf.Epsilon)
						{
							if (num5 >= 1f - Mathf.Epsilon)
							{
								value2.Normal = Vector3.up;
							}
							value2.Normal = Vector3.Cross(value2.Binormal, value2.Tangent).normalized;
						}
					}
				}
				ControlPoints[num] = value2;
				value.Tangent = value2.Tangent;
				value.Normal = value2.Normal;
			}
			else
			{
				value.Normal = normal;
				int num6 = controlPointIndex + 1;
				if (num6 < ControlPoints.Count)
				{
					value.Tangent = (ControlPoints[num6].Position - value.Position).normalized;
				}
				else
				{
					value.Tangent = Quaternion.AngleAxis(90f, Vector3.up) * normal;
				}
			}
			ControlPoints[controlPointIndex] = value;
		}
	}
	public struct ControlPoint
	{
		public Vector3 Position;

		public Vector3 Tangent;

		public Vector3 Normal;

		public float Radius;

		public Vector3 Binormal => Vector3.Cross(Tangent, Normal).normalized;

		public ControlPoint(ControlPoint other)
		{
			Position = other.Position;
			Tangent = other.Tangent;
			Normal = other.Normal;
			Radius = other.Radius;
		}

		public ControlPointData ToControlPointData()
		{
			ControlPointData controlPointData = new ControlPointData();
			controlPointData.Position = Position.ToVector3Data();
			controlPointData.Normal = Normal.ToVector3Data();
			controlPointData.Radius = Radius;
			return controlPointData;
		}

		public static ControlPoint Interpolate(ControlPoint lhs, ControlPoint rhs, float t)
		{
			Quaternion a = Quaternion.LookRotation(lhs.Tangent, lhs.Normal);
			Quaternion b = Quaternion.LookRotation(rhs.Tangent, rhs.Normal);
			Quaternion quaternion = Quaternion.Slerp(a, b, t);
			return new ControlPoint
			{
				Position = Vector3.Lerp(lhs.Position, rhs.Position, t),
				Tangent = quaternion * Vector3.forward,
				Normal = quaternion * Vector3.up,
				Radius = Mathf.Lerp(lhs.Radius, rhs.Radius, t)
			};
		}

		public static ControlPoint InterpolatePositionOnly(ControlPoint lhs, ControlPoint rhs, float t)
		{
			return new ControlPoint
			{
				Position = Vector3.Lerp(lhs.Position, rhs.Position, t),
				Tangent = lhs.Tangent,
				Normal = lhs.Normal,
				Radius = lhs.Radius
			};
		}

		public static ControlPoint InterpolateRotationOnly(ControlPoint lhs, ControlPoint rhs, float t)
		{
			Quaternion a = Quaternion.LookRotation(lhs.Tangent, lhs.Normal);
			Quaternion b = Quaternion.LookRotation(rhs.Tangent, rhs.Normal);
			Quaternion quaternion = Quaternion.Slerp(a, b, t);
			return new ControlPoint
			{
				Position = lhs.Position,
				Tangent = quaternion * Vector3.forward,
				Normal = quaternion * Vector3.up,
				Radius = lhs.Radius
			};
		}
	}
	public abstract class ShapeContainer : Photon.MonoBehaviour, IPersistable
	{
		protected class CurveShape : Shape
		{
			public const float MAX_TUBE_RADIUS = 0.033f;

			private const float MAX_TUBE_DIAMETER = 0.066f;

			private const float MAX_TUBE_DIAMETER_SQR = 0.004356f;

			private Curve curve;

			private CurveMesh extrudedMesh;

			private List<SphereCollider[]> controlPointColliders = new List<SphereCollider[]>();

			public bool HasControlPoints => curve.ControlPoints.Count > 0;

			public int ControlPointCount => curve.ControlPoints.Count;

			protected override DynamicMesh DynamicMesh => extrudedMesh;

			public override float LocalScale
			{
				get
				{
					return base.Transform.GetLocalUniformScale();
				}
				set
				{
					base.Transform.localScale = Vector3.one * value;
				}
			}

			public override float Volume
			{
				get
				{
					float lossyUniformScale = base.Transform.GetLossyUniformScale();
					return curve.Distance * GetCrossSectionAreaForShape(ShapeType) * (lossyUniformScale * lossyUniformScale * lossyUniformScale);
				}
			}

			public override int ColliderCost
			{
				get
				{
					int num = 0;
					if (curve != null)
					{
						int resourceCostForColliderShape = ShapeSettings.GetResourceCostForColliderShape(ShapeType);
						num += curve.ControlPoints.Count * resourceCostForColliderShape;
					}
					return num;
				}
			}

			public override Vector3 CenterOfMass
			{
				get
				{
					if (base.ToolCollider.PhysicsColliders.Count > 0)
					{
						Vector3 zero = Vector3.zero;
						foreach (Collider physicsCollider in base.ToolCollider.PhysicsColliders)
						{
							SphereCollider sphereCollider = physicsCollider as SphereCollider;
							zero += sphereCollider.center;
						}
						return zero / base.ToolCollider.PhysicsColliders.Count;
					}
					return Vector3.zero;
				}
			}

			public CurveShape(Transform parentTransform, Guid id, ShapeType shapeType)
				: base(parentTransform, id, shapeType)
			{
				curve = new Curve();
				if (ShapeType == ShapeType.Tube)
				{
					extrudedMesh = new TubeCurveMesh();
				}
				else if (ShapeType == ShapeType.Ribbon)
				{
					extrudedMesh = new RibbonCurveMesh();
				}
				base.ToolCollider = base.GameObject.AddComponent<ToolCollider>();
				meshFilter.sharedMesh = extrudedMesh.Mesh;
			}

			public bool TryGetControlPointPositionWorldSpace(int controlPointIndex, out Vector3 controlPointPositionWorldSpace)
			{
				if (controlPointIndex < 0 || controlPointIndex >= curve.ControlPoints.Count)
				{
					controlPointPositionWorldSpace = Vector3.zero;
					return false;
				}
				Vector3 position = curve.ControlPoints[controlPointIndex].Position;
				controlPointPositionWorldSpace = base.Transform.TransformPoint(position);
				return true;
			}

			public void AddControlPointWorldSpace(Vector3 positionWorldSpace, Vector3 normalWorldSpace, float radius, bool updateMesh = true)
			{
				Vector3 positionLocalSpace = base.Transform.InverseTransformPoint(positionWorldSpace);
				Vector3 normalLocalSpace = base.Transform.InverseTransformDirection(normalWorldSpace);
				AddControlPointLocalSpace(positionLocalSpace, normalLocalSpace, radius, updateMesh);
			}

			public void AddControlPointLocalSpace(Vector3 positionLocalSpace, Vector3 normalLocalSpace, float radius, bool updateMesh = true)
			{
				curve.AddControlPoint(positionLocalSpace, normalLocalSpace, radius);
				controlPointColliders.Add(null);
				UpdateControlPointColliders(ControlPointCount - 1);
				if (updateMesh)
				{
					Color shapeColor = ShapeSettings.GetShapeColor(base.ShapeColor);
					extrudedMesh.GenerateMeshFromCurve(curve, shapeColor);
				}
			}

			public void UpdateControlPointWorldSpace(int controlPointIndex, Vector3 positionWorldSpace, Vector3 normalWorldSpace, float radius)
			{
				Vector3 position = base.Transform.InverseTransformPoint(positionWorldSpace);
				Vector3 normal = base.Transform.InverseTransformDirection(normalWorldSpace);
				curve.UpdateControlPoint(controlPointIndex, position, normal, radius);
				UpdateControlPointColliders(controlPointIndex);
				Color shapeColor = ShapeSettings.GetShapeColor(base.ShapeColor);
				extrudedMesh.GenerateMeshFromCurve(curve, shapeColor);
			}

			public void RemoveControlPoint(int controlPointIndex)
			{
				curve.RemoveControlPoint(controlPointIndex);
				RemoveControlPointColliders(controlPointIndex);
			}

			private void ReplaceControlPointsLocalSpace(RepeatedField<ControlPointData> newControlPoints)
			{
				int num = 0;
				for (num = 0; num < curve.ControlPoints.Count && num < newControlPoints.Count; num++)
				{
					curve.UpdateControlPoint(num, newControlPoints[num].Position.ToVector3(), newControlPoints[num].Normal.ToVector3(), newControlPoints[num].Radius);
					UpdateControlPointColliders(num);
				}
				for (; num < newControlPoints.Count; num++)
				{
					AddControlPointLocalSpace(newControlPoints[num].Position.ToVector3(), newControlPoints[num].Normal.ToVector3(), newControlPoints[num].Radius, updateMesh: false);
				}
				for (; num < curve.ControlPoints.Count; num++)
				{
					int controlPointIndex = curve.ControlPoints.Count - 1;
					RemoveControlPoint(controlPointIndex);
				}
			}

			public override ShapeData Serialize(Transform parentTransformOverride = null)
			{
				ShapeData shapeData = null;
				int count = curve.ControlPoints.Count;
				if (count > 0)
				{
					shapeData = new ShapeData();
					shapeData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(Id);
					shapeData.ShapeType = (int)ShapeType;
					shapeData.UseUncompressedRotation = !base.WorldBounds.CanCompressRotation();
					shapeData.CurrentLocalPosition = ((!(parentTransformOverride != null)) ? base.Transform.localPosition.ToVector3Data() : parentTransformOverride.InverseTransformPoint(base.Transform.position).ToVector3Data());
					shapeData.CurrentLocalRotation = ((!(parentTransformOverride != null)) ? base.Transform.localRotation.ToVector3Data() : parentTransformOverride.InverseTransformRotation(base.Transform.rotation).ToVector3Data());
					shapeData.Scale = ((!(parentTransformOverride != null)) ? base.Transform.GetLocalUniformScale() : parentTransformOverride.InverseTransformLossyUniformScale(base.Transform.GetLossyUniformScale()));
					shapeData.ShapeColor = (int)base.ShapeColor;
					shapeData.Density = base.Density;
					shapeData.CurveShapeData = new CurveShapeData();
					for (int i = 0; i < count; i++)
					{
						shapeData.CurveShapeData.ControlPoints.Add(curve.ControlPoints[i].ToControlPointData());
					}
				}
				return shapeData;
			}

			public override void Deserialize(ShapeData data)
			{
				base.Transform.localPosition = data.CurrentLocalPosition.ToVector3();
				base.Transform.localRotation = data.CurrentLocalRotation.ToQuaternion();
				LocalScale = data.Scale;
				base.ShapeColor = (ShapeColor)data.ShapeColor;
				base.Density = data.Density;
				RepeatedField<ControlPointData> controlPoints = data.CurveShapeData.ControlPoints;
				ReplaceControlPointsLocalSpace(controlPoints);
				Color shapeColor = ShapeSettings.GetShapeColor(base.ShapeColor);
				extrudedMesh.GenerateMeshFromCurve(curve, shapeColor);
			}

			public static float GetCrossSectionAreaForShape(ShapeType shapeType)
			{
				float result = 0f;
				switch (shapeType)
				{
				case ShapeType.Tube:
					result = 0.0034211944f;
					break;
				case ShapeType.Ribbon:
					result = 3.3E-05f;
					break;
				}
				return result;
			}

			private void UpdateControlPointColliders(int controlPointIndex)
			{
				if (controlPointIndex < 0 || controlPointIndex >= controlPointColliders.Count)
				{
					UnityEngine.Debug.LogErrorFormat("Tried to update control point colliders at control point {0}", controlPointIndex);
					return;
				}
				Vector3 spanStartPosition;
				Vector3 spanEndPosition;
				float spanStartRadius;
				float spanEndRadius;
				int controlPointColliderSpan = GetControlPointColliderSpan(controlPointIndex, out spanStartPosition, out spanEndPosition, out spanStartRadius, out spanEndRadius);
				SphereCollider[] colliderArray = controlPointColliders[controlPointIndex];
				SphereCollider[] array = ResizeColliderArray(colliderArray, controlPointColliderSpan);
				controlPointColliders[controlPointIndex] = array;
				for (int i = 0; i < controlPointColliderSpan; i++)
				{
					float t = Mathf.InverseLerp(0f, controlPointColliderSpan, i);
					array[i].center = Vector3.Lerp(spanStartPosition, spanEndPosition, t);
					array[i].radius = Mathf.Lerp(spanStartRadius, spanEndRadius, t);
				}
			}

			private void RemoveControlPointColliders(int controlPointIndex)
			{
				if (controlPointIndex >= 0 && controlPointIndex < controlPointColliders.Count)
				{
					SphereCollider[] array = controlPointColliders[controlPointIndex];
					for (int i = 0; i < array.Length; i++)
					{
						DestroyCollider(array[i]);
					}
					controlPointColliders.RemoveAt(controlPointIndex);
					if (controlPointIndex < controlPointColliders.Count)
					{
						UpdateControlPointColliders(controlPointIndex);
					}
				}
			}

			private int GetPreviousControlPointIndexWithCollider(int controlPointIndex)
			{
				while (--controlPointIndex > 0)
				{
					if (controlPointColliders[controlPointIndex].Length > 0)
					{
						return controlPointIndex;
					}
				}
				return 0;
			}

			private int GetControlPointColliderSpan(int controlPointIndex, out Vector3 spanStartPosition, out Vector3 spanEndPosition, out float spanStartRadius, out float spanEndRadius)
			{
				ControlPoint controlPoint = curve.ControlPoints[controlPointIndex];
				spanStartPosition = controlPoint.Position;
				spanEndPosition = controlPoint.Position;
				spanStartRadius = controlPoint.Radius;
				spanEndRadius = controlPoint.Radius;
				if (controlPointIndex == 0)
				{
					return 1;
				}
				int previousControlPointIndexWithCollider = GetPreviousControlPointIndexWithCollider(controlPointIndex);
				ControlPoint controlPoint2 = curve.ControlPoints[previousControlPointIndexWithCollider];
				float num = controlPoint2.Radius * 2f;
				float sqrMagnitude = (controlPoint.Position - controlPoint2.Position).sqrMagnitude;
				if (sqrMagnitude <= num * num)
				{
					return 0;
				}
				int num2 = 1;
				float num3 = 3f * num;
				if (sqrMagnitude >= num3 * num3 && num3 >= Mathf.Epsilon)
				{
					spanEndPosition = controlPoint2.Position;
					spanEndRadius = controlPoint2.Radius;
					float num4 = Mathf.Sqrt(sqrMagnitude);
					int num5 = Mathf.FloorToInt(num4 / num3);
					num2 += num5;
				}
				return num2;
			}

			private SphereCollider[] ResizeColliderArray(SphereCollider[] colliderArray, int colliderCount)
			{
				SphereCollider[] array = colliderArray;
				if (colliderArray == null)
				{
					array = new SphereCollider[colliderCount];
				}
				else if (colliderArray.Length > colliderCount)
				{
					array = new SphereCollider[colliderCount];
					Array.Copy(colliderArray, array, colliderCount);
					for (int i = colliderCount; i < colliderArray.Length; i++)
					{
						DestroyCollider(colliderArray[i]);
					}
				}
				else if (colliderArray.Length < colliderCount)
				{
					array = new SphereCollider[colliderCount];
					Array.Copy(colliderArray, array, colliderArray.Length);
				}
				for (int j = 0; j < colliderCount; j++)
				{
					if (array[j] == null)
					{
						array[j] = CreateCollider();
					}
				}
				return array;
			}

			private SphereCollider CreateCollider()
			{
				SphereCollider sphereCollider = base.GameObject.AddComponent<SphereCollider>();
				sphereCollider.center = Vector3.zero;
				sphereCollider.radius = 0.033f;
				base.ToolCollider.AddCollider(sphereCollider);
				return sphereCollider;
			}

			private void DestroyCollider(SphereCollider collider)
			{
				base.ToolCollider.RemoveCollider(collider);
				UnityEngine.Object.Destroy(collider);
			}

			public static CurveShape DeserializeShape(Transform parentTransform, ShapeData data)
			{
				CurveShape curveShape = new CurveShape(parentTransform, RecRoom.Protobuf.ByteStringExtensions.ToGuid(data.Id), (ShapeType)data.ShapeType);
				curveShape.Deserialize(data);
				return curveShape;
			}
		}

		protected class MeshShape : Shape
		{
			private static readonly Vector3 UNIFORM_CENTER_OF_MASS = new Vector3(0.5f, 0.5f, 0.5f);

			private static readonly Vector3 PYRAMID_CENTER_OF_MASS = new Vector3(0.5f, 0.25f, 0.5f);

			private static readonly Vector3 WEDGE_CENTER_OF_MASS = new Vector3(0.5f, 1f / 3f, 1f / 3f);

			private ShapeMesh shapeMesh;

			private Vector3 _aspectRatio = Vector3.one;

			protected override DynamicMesh DynamicMesh => shapeMesh;

			public override float LocalScale
			{
				get
				{
					return base.Transform.GetLocalUniformScale() / _aspectRatio.x;
				}
				set
				{
					base.Transform.localScale = _aspectRatio * value;
				}
			}

			public Vector3 AspectRatio
			{
				get
				{
					return _aspectRatio;
				}
				set
				{
					float localScale = LocalScale;
					_aspectRatio = value;
					base.Transform.localScale = _aspectRatio * localScale;
					OnSizeChange();
				}
			}

			public override int ColliderCost => ShapeSettings.GetResourceCostForColliderShape(ShapeType);

			public override float Volume => GetVolumeForShape(ShapeType, base.Transform.lossyScale);

			public override Vector3 CenterOfMass => GetLocalCenterOfMassForShape(ShapeType);

			public MeshShape(Transform parentTransform, Guid id, ShapeType shapeType)
				: base(parentTransform, id, shapeType)
			{
				shapeMesh = new ShapeMesh(parentTransform, shapeType, ShapeSettings.GetShapeColor(base.ShapeColor));
				meshFilter.sharedMesh = shapeMesh.Mesh;
				base.ToolCollider = base.GameObject.GetComponent<ToolCollider>();
			}

			public static float GetVolumeForShape(ShapeType shape, Vector3 worldSize)
			{
				float result = 0f;
				switch (shape)
				{
				case ShapeType.Box:
					result = worldSize.x * worldSize.y * worldSize.z;
					break;
				case ShapeType.Cylinder:
					result = (float)Math.PI * (worldSize.x / 2f) * (worldSize.z / 2f) * worldSize.y;
					break;
				case ShapeType.Pyramid:
					result = worldSize.x * worldSize.z * worldSize.y / 3f;
					break;
				case ShapeType.Sphere:
					result = 4.1887903f * (worldSize.x / 2f) * (worldSize.y / 2f) * (worldSize.z / 2f);
					break;
				case ShapeType.Wedge:
					result = worldSize.x * worldSize.y * worldSize.z / 2f;
					break;
				}
				return result;
			}

			public static Vector3 GetLocalCenterOfMassForShape(ShapeType shape)
			{
				Vector3 result = Vector3.zero;
				switch (shape)
				{
				case ShapeType.Box:
				case ShapeType.Sphere:
				case ShapeType.Cylinder:
					result = UNIFORM_CENTER_OF_MASS;
					break;
				case ShapeType.Pyramid:
					result = PYRAMID_CENTER_OF_MASS;
					break;
				case ShapeType.Wedge:
					result = WEDGE_CENTER_OF_MASS;
					break;
				}
				return result;
			}

			public override ShapeData Serialize(Transform parentTransformOverride = null)
			{
				ShapeData shapeData = new ShapeData();
				shapeData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(Id);
				shapeData.ShapeType = (int)ShapeType;
				shapeData.UseUncompressedRotation = !base.WorldBounds.CanCompressRotation();
				shapeData.CurrentLocalPosition = ((!(parentTransformOverride != null)) ? base.Transform.localPosition.ToVector3Data() : parentTransformOverride.InverseTransformPoint(base.Transform.position).ToVector3Data());
				shapeData.CurrentLocalRotation = ((!(parentTransformOverride != null)) ? base.Transform.localRotation.ToVector3Data() : parentTransformOverride.InverseTransformRotation(base.Transform.rotation).ToVector3Data());
				float uniformLossyScale = base.Transform.GetLossyUniformScale() / AspectRatio.x;
				float num = base.Transform.GetLocalUniformScale() / AspectRatio.x;
				shapeData.Scale = ((!(parentTransformOverride != null)) ? num : parentTransformOverride.InverseTransformLossyUniformScale(uniformLossyScale));
				shapeData.ShapeColor = (int)base.ShapeColor;
				shapeData.Density = base.Density;
				shapeData.MeshShapeData = new MeshShapeData();
				shapeData.MeshShapeData.AspectRatio = AspectRatio.ToVector3Data();
				return shapeData;
			}

			public override void Deserialize(ShapeData data)
			{
				AspectRatio = data.MeshShapeData.AspectRatio.ToVector3();
				base.Transform.localPosition = data.CurrentLocalPosition.ToVector3();
				base.Transform.localRotation = data.CurrentLocalRotation.ToQuaternion();
				base.Transform.localScale = data.MeshShapeData.AspectRatio.ToVector3() * data.Scale;
				base.ShapeColor = (ShapeColor)data.ShapeColor;
				base.Density = data.Density;
			}

			public static MeshShape DeserializeShape(Transform parentTransform, ShapeData data)
			{
				MeshShape meshShape = new MeshShape(parentTransform, RecRoom.Protobuf.ByteStringExtensions.ToGuid(data.Id), (ShapeType)data.ShapeType);
				meshShape.Deserialize(data);
				return meshShape;
			}

			private void OnSizeChange()
			{
				if (ShapeType == ShapeType.Sphere)
				{
					UpdateSphereShapeColliderType();
				}
			}

			private void UpdateSphereShapeColliderType()
			{
				bool flag = AspectRatio.IsUniform(0.01f);
				Collider collider = ((base.ToolCollider.PhysicsColliders.Count <= 0) ? null : base.ToolCollider.PhysicsColliders[0]);
				SphereCollider sphereCollider = collider as SphereCollider;
				if (flag && sphereCollider == null)
				{
					TryDestroyCollider(collider);
					AddSphereCollider();
				}
				else if (!flag && sphereCollider != null)
				{
					TryDestroyCollider(collider);
					AddBoxCollider();
				}
			}

			private void AddSphereCollider()
			{
				SphereCollider sphereCollider = base.GameObject.AddComponent<SphereCollider>();
				sphereCollider.radius = 0.5f;
				base.ToolCollider.AddCollider(sphereCollider);
			}

			private void AddBoxCollider()
			{
				BoxCollider boxCollider = base.GameObject.AddComponent<BoxCollider>();
				boxCollider.size = Vector3.one;
				base.ToolCollider.AddCollider(boxCollider);
			}

			private void TryDestroyCollider(Collider collider)
			{
				if (collider != null)
				{
					base.ToolCollider.RemoveCollider(collider);
					UnityEngine.Object.Destroy(collider);
				}
			}
		}

		protected abstract class Shape
		{
			protected const int DEFAULT_DENSITY = 10;

			public readonly Guid Id;

			public readonly ShapeType ShapeType;

			private ShapeColor _shapeColor;

			protected MeshFilter meshFilter;

			protected SimpleVolumeBase overlapVolume;

			public ShapeColor ShapeColor
			{
				get
				{
					return _shapeColor;
				}
				set
				{
					_shapeColor = value;
					ApplyColorToMesh();
				}
			}

			public GameObject GameObject { get; private set; }

			public MeshRenderer MeshRenderer { get; private set; }

			public ToolCollider ToolCollider { get; protected set; }

			public Transform Transform { get; private set; }

			public abstract float LocalScale { get; set; }

			public Bounds WorldBounds => ToolCollider.Bounds;

			public abstract int ColliderCost { get; }

			public float Density { get; set; } = 10f;

			public abstract float Volume { get; }

			public abstract Vector3 CenterOfMass { get; }

			protected abstract DynamicMesh DynamicMesh { get; }

			public float Mass => Volume * Density;

			public Vector3 WorldCenterOfMass => Transform.TransformPoint(CenterOfMass);

			public Shape(Transform transform, Guid id, ShapeType shapeType)
			{
				Id = id;
				ShapeType = shapeType;
				GameObject = UnityEngine.Object.Instantiate(ShapeSettings.GetShapePrefab(shapeType), transform, worldPositionStays: true);
				GameObject.layer = transform.gameObject.layer;
				Transform = GameObject.transform;
				meshFilter = GameObject.GetComponent<MeshFilter>();
				MeshRenderer = GameObject.GetComponent<MeshRenderer>();
				overlapVolume = GameObject.GetComponent<SimpleVolumeBase>();
			}

			public void AddToBatchedMesh(BatchedMeshRenderer batchedMeshRenderer)
			{
				Matrix4x4 shapeToBatchedMeshTransform = GetShapeToBatchedMeshTransform(batchedMeshRenderer);
				batchedMeshRenderer.AddToBatchedMesh(DynamicMesh, MeshRenderer.sharedMaterial, shapeToBatchedMeshTransform);
				MeshRenderer.enabled = false;
			}

			public void RemoveFromBatchedMesh(BatchedMeshRenderer batchedMeshRenderer)
			{
				batchedMeshRenderer.RemoveFromBatchedMesh(DynamicMesh);
				MeshRenderer.enabled = true;
			}

			public void UpdateBatchOnVertexPositionChange(BatchedMeshRenderer batchedMeshRenderer)
			{
				Matrix4x4 shapeToBatchedMeshTransform = GetShapeToBatchedMeshTransform(batchedMeshRenderer);
				batchedMeshRenderer.UpdateMeshVertices(DynamicMesh, shapeToBatchedMeshTransform);
			}

			public void UpdateBatchOnColorChange(BatchedMeshRenderer batchedMeshRenderer)
			{
				Color shapeColor = ShapeSettings.GetShapeColor(ShapeColor);
				batchedMeshRenderer.UpdateMeshColor(DynamicMesh, shapeColor);
			}

			private Matrix4x4 GetShapeToBatchedMeshTransform(BatchedMeshRenderer batchedMeshRenderer)
			{
				return batchedMeshRenderer.transform.worldToLocalMatrix * Transform.localToWorldMatrix;
			}

			public bool CheckOverlap(int layerMask, QueryTriggerInteraction queryTriggers, Func<Collider, bool> filterFunc = null)
			{
				Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
				int num = 0;
				if (overlapVolume != null)
				{
					num = overlapVolume.OverlapTest(iMMEDIATE_COLLIDER_HITS, layerMask, queryTriggers);
					if (FilterOverlapResult(iMMEDIATE_COLLIDER_HITS, num, filterFunc))
					{
						return true;
					}
				}
				else
				{
					foreach (Collider physicsCollider in ToolCollider.PhysicsColliders)
					{
						SphereCollider sphereCollider = physicsCollider as SphereCollider;
						if (sphereCollider != null)
						{
							Vector3 position = sphereCollider.transform.TransformPoint(sphereCollider.center);
							float radius = sphereCollider.radius * sphereCollider.transform.lossyScale.x;
							num = Physics.OverlapSphereNonAlloc(position, radius, iMMEDIATE_COLLIDER_HITS, layerMask, QueryTriggerInteraction.Ignore);
							if (FilterOverlapResult(iMMEDIATE_COLLIDER_HITS, num, filterFunc))
							{
								return true;
							}
							continue;
						}
						BoxCollider boxCollider = physicsCollider as BoxCollider;
						if (boxCollider != null)
						{
							Vector3 halfExtents = boxCollider.size.MultiplyComponents(boxCollider.transform.lossyScale) / 2f;
							halfExtents.x = Mathf.Abs(halfExtents.x);
							halfExtents.y = Mathf.Abs(halfExtents.y);
							halfExtents.z = Mathf.Abs(halfExtents.z);
							Vector3 center = boxCollider.transform.TransformPoint(boxCollider.center);
							num = Physics.OverlapBoxNonAlloc(center, halfExtents, iMMEDIATE_COLLIDER_HITS, boxCollider.transform.rotation, layerMask, QueryTriggerInteraction.Ignore);
							if (FilterOverlapResult(iMMEDIATE_COLLIDER_HITS, num, filterFunc))
							{
								return true;
							}
						}
					}
				}
				return false;
			}

			private bool FilterOverlapResult(Collider[] hitResults, int length, Func<Collider, bool> filterFunc)
			{
				if (length > 0)
				{
					if (filterFunc == null)
					{
						return true;
					}
					for (int i = 0; i < length; i++)
					{
						Collider value = hitResults[i];
						if (!ToolCollider.PhysicsColliders.Contains(value) && filterFunc(hitResults[i]))
						{
							return true;
						}
					}
				}
				return false;
			}

			public abstract ShapeData Serialize(Transform parentTransformOverride = null);

			public abstract void Deserialize(ShapeData data);

			private void ApplyColorToMesh()
			{
				if (DynamicMesh != null)
				{
					Color shapeColor = ShapeSettings.GetShapeColor(ShapeColor);
					DynamicMesh.SetCachedColor(shapeColor);
					DynamicMesh.CopyChangesToGPU();
				}
			}
		}

		public enum PhysicsMode
		{
			Environment,
			Decoration,
			Physical_Sticky,
			Trigger,
			Physical
		}

		protected enum RepositionWhenAddingFirstShape
		{
			Never,
			Once,
			Always
		}

		protected class CacheCoherentShapeArray
		{
			private List<Guid> shapeIds = new List<Guid>();

			private List<Shape> shapes = new List<Shape>();

			public IReadOnlyList<Guid> AllShapeIds
			{
				[CompilerGenerated]
				get
				{
					return shapeIds;
				}
			}

			public IEnumerable<Shape> AllShapes
			{
				[CompilerGenerated]
				get
				{
					return shapes;
				}
			}

			public int ShapeCount => shapes.Count;

			public bool ContainsShape(Shape shape)
			{
				return shape != null && ContainsShape(shape.Id);
			}

			public bool ContainsShape(Guid shapeId)
			{
				int shapeIndex = -1;
				return TryGetShapeIndex(shapeId, out shapeIndex);
			}

			public bool ContainsAnyShape(IEnumerable<Guid> searchShapeIds)
			{
				return shapeIds.Any((Guid id) => searchShapeIds.Any((Guid searchId) => searchId == id));
			}

			public Shape GetShapeByIndex(int index)
			{
				return shapes[index];
			}

			public Shape[] GetShapesByIds(Guid[] searchShapeIds)
			{
				if (ShapeCount == 0)
				{
					return new Shape[0];
				}
				return (from id in searchShapeIds
					select GetShapeById(id) into s
					where s != null
					select s).ToArray();
			}

			public bool TryAddShape(Shape shape)
			{
				int shapeIndex = -1;
				if (shape == null || TryGetShapeIndex(shape.Id, out shapeIndex))
				{
					return false;
				}
				shapeIds.Add(shape.Id);
				shapes.Add(shape);
				return true;
			}

			public void RemoveShape(Guid shapeId)
			{
				int shapeIndex = -1;
				if (TryGetShapeIndex(shapeId, out shapeIndex))
				{
					shapeIds.RemoveAt(shapeIndex);
					shapes.RemoveAt(shapeIndex);
				}
			}

			public Shape GetShapeById(Guid shapeId)
			{
				Shape result = null;
				int shapeIndex = -1;
				if (TryGetShapeIndex(shapeId, out shapeIndex))
				{
					result = shapes[shapeIndex];
				}
				return result;
			}

			private bool TryGetShapeIndex(Guid shapeId, out int shapeIndex)
			{
				for (int i = 0; i < shapeIds.Count; i++)
				{
					if (shapeIds[i] == shapeId)
					{
						shapeIndex = i;
						return true;
					}
				}
				shapeIndex = -1;
				return false;
			}
		}

