		{
			base.Awake();
			_physicsMode = new SynchronizedField<int>(this, "PMD", (int)DefaultPhysicsMode, SetterPermissionMode.AUTHORITY, OnPhysicsModeChanged);
			AllShapeContainers.Add(this);
