			Tool.AddCustomPickupCondition(CustomToolPickupCondition);
			Tool.CustomHighlightingBehavior = ToolHighlightingOverride;
			Tool.SelectionType = SelectionRenderer.SelectionType.Shape;
			Tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			Tool.PostResetEvent += OnPostReset;
			Tool.OnCachedSizeUpdated += UpdateNetworkTransformRotationCompression;
			CreationObject.AddResourceCostModifier(new Func<int>(this, (nint)__ldftn(ShapeContainer.get_SandboxResourceCost)), this);
			CreationObject.LockedStatusChangedEvent += OnCreationLockChange;
		}

		protected virtual void Start()
		{
			Tool.RigidbodyEx.localCenterOfMass = Vector3.zero;
			if (Tool.CreationObject != null)
			{
				Tool.CreationObject.AddPropertyHandler("Color", OnRecolor);
			}
			OnShapesChanged();
			OnCreationLockChange(CreationObject);
			OnPhysicsModeChanged();
			RefreshPhysics();
			RefreshTagsAndLayers();
			postStart = true;
		}

		protected override void OnDestroy()
		{
