		public int RaycastPickShapes(Vector3 origin, Vector3 direction, float maxDistance, Guid[] pickedShapeIds, out Vector3 closestHit, ShapeContainer otherToConsider = null)
		{
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = PhysicsExt.IMMEDIATE_RAYCAST_HITS;
			int hitCount = Physics.RaycastNonAlloc(origin, direction, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084289, QueryTriggerInteraction.Collide);
			return FilterCastPickedShapes(hitCount, iMMEDIATE_RAYCAST_HITS, pickedShapeIds, out closestHit, otherToConsider);
		}

		public int SpherecastPickShapes(Vector3 origin, float sphereRadius, Vector3 direction, float maxDistance, Guid[] pickedShapeIds, out Vector3 closestHit, out Collider closestCollider, ShapeContainer otherToConsider = null)
		{
			Shape closestSphereCastHit = PhysicsExt.GetClosestSphereCastHit(origin, sphereRadius, direction, maxDistance, out closestHit, out closestCollider, delegate(Collider c, float distanceSq)
			{
				ToolCollider toolCollider;
				Tool colliderTool = c.GetColliderTool(out toolCollider);
				if ((bool)colliderTool)
				{
					if (colliderTool == Tool)
					{
						return GetShapeFromToolCollider(toolCollider);
					}
					if ((bool)otherToConsider && colliderTool == otherToConsider.Tool)
					{
						return otherToConsider.GetShapeFromToolCollider(toolCollider);
					}
				}
				return (Shape)null;
			});
			if (closestSphereCastHit != null)
			{
				ref Guid reference = ref pickedShapeIds[0];
				reference = closestSphereCastHit.Id;
				return 1;
			}
			return 0;
		}

		public bool CheckShapeOverlaps(int layerMask, QueryTriggerInteraction queryTriggers, Func<Collider, bool> filterFunc = null)
		{
			int shapeCount = shapeArray.ShapeCount;
			for (int i = 0; i < shapeCount; i++)
			{
				if (shapeArray.GetShapeByIndex(i).CheckOverlap(layerMask, queryTriggers, filterFunc))
				{
					return true;
				}
			}
			return false;
		}

		private int FilterCastPickedShapes(int hitCount, RaycastHit[] castPickingHits, Guid[] pickedShapes, out Vector3 closestHitPoint, ShapeContainer otherToConsider)
		{
			int num = 0;
			Shape closestShapeFromCastPick = GetClosestShapeFromCastPick(hitCount, castPickingHits, out closestHitPoint, otherToConsider);
			if (closestShapeFromCastPick != null && num < pickedShapes.Length)
			{
				ref Guid reference = ref pickedShapes[num++];
				reference = closestShapeFromCastPick.Id;
			}
			return num;
		}

		private Shape GetClosestShapeFromCastPick(int hitCount, RaycastHit[] castPickingHits, out Vector3 closestHitPoint, ShapeContainer otherToConsider)
		{
			closestHitPoint = Vector3.zero;
			Shape result = null;
			float num = float.MaxValue;
			for (int i = 0; i < hitCount; i++)
			{
				ToolCollider toolCollider;
				Tool colliderTool = castPickingHits[i].collider.GetColliderTool(out toolCollider);
				if (!(colliderTool == null) && (!(colliderTool != Tool) || (!(otherToConsider == null) && !(colliderTool != otherToConsider.Tool))) && !(castPickingHits[i].distance >= num))
				{
					Shape shapeFromToolCollider = GetShapeFromToolCollider(toolCollider);
					if (shapeFromToolCollider == null && otherToConsider != null)
					{
						shapeFromToolCollider = otherToConsider.GetShapeFromToolCollider(toolCollider);
					}
					if (shapeFromToolCollider != null)
					{
						result = shapeFromToolCollider;
						num = castPickingHits[i].distance;
						closestHitPoint = castPickingHits[i].point;
					}
				}
			}
			return result;
		}

		private Shape GetShapeFromToolCollider(ToolCollider toolCollider)
		{
			int shapeCount = shapeArray.ShapeCount;
			for (int i = 0; i < shapeCount; i++)
			{
				Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
				if (shapeByIndex.ToolCollider == toolCollider)
				{
					return shapeByIndex;
				}
			}
			return null;
		}

		protected virtual void OnShapesChanged()
		{
			if (postStart)
			{
				shapeSynchronizationDirty = true;
				ShapesUnchangedFromRoomData = false;
				if (OnShapesChangedEvent != null)
				{
					OnShapesChangedEvent();
				}
			}
			ScheduleSizeUpdate();
			MarkResourceCostsDirty();
		}

		private void AddShapeInternal(Shape shape, bool addToBatchedMesh)
		{
			if (shapeArray.TryAddShape(shape))
			{
				Tool.AddToolCollider(shape.ToolCollider);
				if (addToBatchedMesh)
				{
					AddToBatchedMesh(shape);
				}
				hasContainedShapes = true;
			}
			else
			{
				UnityEngine.Debug.LogError($"Failed to cleanly add {shape.ShapeType} shape {shape.Id} to ShapeContainer {DebugName}.", this);
			}
			OnShapesChanged();
		}

