		private void RemoteSetMeshShapeAspectRatios(Guid[] shapeIds, Vector3[] aspectRatios)
		{
			if (shapeIds.Length != aspectRatios.Length)
			{
				UnityEngine.Debug.LogError($"ShapeContainer {DebugName} received mismatched arrays when setting shape aspecr ratios ({shapeIds.Length} IDs, {aspectRatios.Length} ratios)");
				return;
			}
			for (int i = 0; i < shapeIds.Length; i++)
			{
				if (shapeArray.GetShapeById(shapeIds[i]) is MeshShape meshShape)
				{
					meshShape.AspectRatio = aspectRatios[i];
					UpdateBatchedShapeVertices(meshShape);
				}
			}
		}

