		public void AuthorityTransferShapesToShapeContainer(Guid[] shapeIds, ShapeContainer shapeContainer)
		{
			if (!base.hasAuthority || shapeContainer == this || shapeContainer == null)
			{
				return;
			}
			Shape[] shapesByIds = shapeArray.GetShapesByIds(shapeIds);
			if (shapesByIds != null && shapesByIds.Length != 0)
			{
				bool flag = shapeContainer.AuthorityPositionContainerAroundShapeIfEmpty(shapesByIds[0]);
				ShapeDataCollection arg = SerializeShapes(shapesByIds, shapeContainer.ShapeRoot);
				base.photonView.RpcAll(RpcTransferShapesToShapeContainer, shapeIds, arg, shapeContainer.photonView.viewID);
				if (flag)
				{
					Physics.SyncTransforms();
				}
			}
		}

		private void TransferShapesToShapeContainerInternal(Guid[] shapeIds, ShapeDataCollection shapeDataCollection, ShapeContainer shapeContainer)
		{
			if (!(shapeContainer == null))
			{
				RemoteDeleteShapes(shapeIds);
				shapeContainer.LocalAddShapesFromData(shapeDataCollection);
			}
		}

		private bool AuthorityPositionContainerAroundShapeIfEmpty(Shape shape)
		{
			if (base.hasAuthority && shapeArray.ShapeCount == 0)
			{
				bool flag = false;
				switch (ShouldRepositionWhenAddingFirstShape)
				{
				case RepositionWhenAddingFirstShape.Always:
					flag = true;
					break;
				case RepositionWhenAddingFirstShape.Once:
					flag = !hasContainedShapes;
					break;
				}
				if (flag)
				{
					base.transform.position = shape.Transform.position;
					base.transform.rotation = shape.Transform.rotation;
					NetworkTransform component = GetComponent<NetworkTransform>();
					if (component != null)
					{
						component.InsertPositionDiscontinuity(forceImmediate: true);
					}
					return true;
				}
			}
			return false;
		}

