		public Guid[] AuthorityCloneShapesToShapeContainer(Guid[] shapeIds, ShapeContainer shapeContainer)
		{
			if (!base.hasAuthority)
			{
				return null;
			}
			if (shapeContainer == this || shapeContainer == null)
			{
				return null;
			}
			Shape[] shapesByIds = shapeArray.GetShapesByIds(shapeIds);
			if (shapesByIds == null || shapesByIds.Length == 0)
			{
				return null;
			}
			shapeContainer.AuthorityPositionContainerAroundShapeIfEmpty(shapesByIds[0]);
			ShapeDataCollection shapeDataCollection = SerializeShapes(shapesByIds, shapeContainer.ShapeRoot);
			Guid[] array = new Guid[shapeDataCollection.Shapes.Count];
			for (int i = 0; i < shapeDataCollection.Shapes.Count; i++)
			{
				ref Guid reference = ref array[i];
				reference = Guid.NewGuid();
				shapeDataCollection.Shapes[i].Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(array[i]);
			}
			base.photonView.RpcAll(RpcCloneShapesToShapeContainer, shapeIds, shapeDataCollection, shapeContainer.photonView.viewID);
			Physics.SyncTransforms();
			return array;
		}

