		}

		protected static ShapeDataCollection SerializeShapes(IEnumerable<Shape> shapesToSerialize, out int colliderCosts, Transform parentTransformOverride = null)
		{
			ShapeDataCollection shapeDataCollection = new ShapeDataCollection();
			colliderCosts = 0;
			if (shapesToSerialize != null)
			{
				int num = 0;
				foreach (Shape item in shapesToSerialize)
				{
					if (item.GameObject == null)
					{
						UnityEngine.Debug.LogErrorFormat("Unable to serialize {0} shape {1} that is missing a corresponding GameObject.", item.ShapeType, num);
						continue;
					}
					ShapeData shapeData = item.Serialize(parentTransformOverride);
					if (shapeData != null)
					{
						shapeDataCollection.Shapes.Add(shapeData);
					}
					colliderCosts += item.ColliderCost;
					num++;
				}
			}
			return shapeDataCollection;
		}

