		public void LocalAddShapesFromRoomData(RoomPersistenceVersion version, PersistenceViewData viewData)
		{
			if (viewData.ShapeContainerData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error adding shapes from persisted ShapeContainerData {0}: data empty.", base.gameObject);
				return;
			}
			VerifyShapeIds(version, viewData);
			VerifyCurveShapeCoordinateSpace(version, viewData);
			VerifyShapeScale(version, viewData);
			LocalAddShapesFromDataInternal(viewData.ShapeContainerData.ShapeCollection, fromRoomData: true);
		}

