		private void LocalAddShapesFromDataInternal(ShapeDataCollection collectionData, bool fromRoomData)
		{
			foreach (ShapeData shape2 in collectionData.Shapes)
			{
				Shape shape = DeserializeShape(ShapeRoot, shape2);
				AddShapeInternal(shape, addToBatchedMesh: true);
			}
			WaitingForShapeData = false;
			UpdateRigidbodyMechanics();
			RefreshTagsAndLayers();
			if (fromRoomData)
			{
				ShapesUnchangedFromRoomData = true;
			}
			if (stickyShape != null)
			{
				stickyShape.RefreshIgnoredColliders();
			}
			if (!postStart)
			{
				Tool.DisableCollision(this);
				this.InvokeNextEndOfFrame(delegate
				{
					Tool.EnableCollision(this);
				});
			}
		}

		private void AuthoritySynchronizeShapes()
		{
			if (base.hasAuthority && !IsEmpty && shapeSynchronizationDirty)
			{
				ShapeDataCollection arg = SerializeShapes();
				base.photonView.RpcAll(RpcSynchronizeShapes, arg);
			}
			shapeSynchronizationDirty = false;
		}

		private void RemoteSynchronizeShapes(ShapeDataCollection collectionData)
		{
			if (WaitingForShapeData)
			{
				UnityEngine.Debug.LogWarning($"Received synchronization data for ShapeContainer {DebugName}, but we're still waiting to receive the initial shape data from the authority.");
				return;
			}
			int shapeCount = shapeArray.ShapeCount;
			if (shapeCount != collectionData.Shapes.Count)
			{
				UnityEngine.Debug.LogErrorFormat("{0} has {1} Shapes but received synchronization data for {2}", DebugName, shapeArray.ShapeCount, collectionData.Shapes.Count);
			}
			for (int i = 0; i < shapeCount && i < collectionData.Shapes.Count; i++)
			{
				Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
				ShapeData data = collectionData.Shapes[i];
				shapeByIndex.Deserialize(data);
				UpdateBatchedShapeVertices(shapeByIndex);
			}
			OnShapesChanged();
			UpdateRigidbodyMechanics();
		}

