		private void RemoteSetLocalShapeTransforms(Guid[] shapeIds, Vector3[] localPositions, Quaternion[] localRotations, float[] localScales)
		{
			if (localPositions != null && shapeIds.Length != localPositions.Length)
			{
				UnityEngine.Debug.LogError($"ShapeContainer {DebugName} received mismatched arrays when setting shape positions ({shapeIds.Length} IDs, {localPositions.Length} positions)");
				return;
			}
			if (localRotations != null && shapeIds.Length != localRotations.Length)
			{
				UnityEngine.Debug.LogError($"ShapeContainer {DebugName} received mismatched arrays when setting shape positions ({shapeIds.Length} IDs, {localPositions.Length} positions)");
				return;
			}
			if (localScales != null && shapeIds.Length != localScales.Length)
			{
				UnityEngine.Debug.LogError($"ShapeContainer {DebugName} received mismatched arrays when setting shape scales ({shapeIds.Length} IDs, {localScales.Length} scales)");
				return;
			}
			for (int i = 0; i < shapeIds.Length; i++)
			{
				Shape shapeById = shapeArray.GetShapeById(shapeIds[i]);
				if (shapeById != null)
				{
					if (localPositions != null)
					{
						shapeById.Transform.localPosition = localPositions[i];
					}
					if (localRotations != null)
					{
						shapeById.Transform.localRotation = localRotations[i];
					}
					if (localScales != null)
					{
						shapeById.LocalScale = localScales[i];
					}
					UpdateBatchedShapeVertices(shapeById);
				}
			}
			OnShapesChanged();
		}

