		protected virtual bool CanMergeShapeContainer(ShapeContainer sourceShapeContainer, PhotonPlayer requestingPlayer)
		{
			if (!CanBeMerged)
			{
				return false;
			}
			if (!sourceShapeContainer.CanBeMerged)
			{
				return false;
			}
			if (sourceShapeContainer.CreationObject.IsLocked && sourceShapeContainer.CreationObject.LockedByPhotonPlayer != requestingPlayer.ID)
			{
				return false;
			}
			int shapesCost = GetShapesCost(sourceShapeContainer.shapeArray.AllShapes, CurrentPhysicsMode);
			int num = SandboxResourceCost + shapesCost;
			if (num > MaxResources)
			{
				return false;
			}
			int cost = shapesCost - sourceShapeContainer.SandboxResourceCost;
			if (!NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(cost))
			{
				return false;
			}
			return true;
		}

