		private float DistanceToToolTransformBehavior(Collider collider, Transform otherTransform, out bool inFrontOfOtherTransform)
		{
			inFrontOfOtherTransform = true;
			Vector3 vector = collider.transform.position;
			SphereCollider sphereCollider = collider as SphereCollider;
			if (sphereCollider != null)
			{
				vector = sphereCollider.transform.TransformPoint(sphereCollider.center);
			}
			else
			{
				BoxCollider boxCollider = collider as BoxCollider;
				if (boxCollider != null)
				{
					vector = boxCollider.transform.TransformPoint(boxCollider.center);
				}
			}
			return (vector - otherTransform.position).magnitude;
		}

		private void RefreshPhysics()
		{
			if (CurrentPhysicsMode == PhysicsMode.Environment || CurrentPhysicsMode == PhysicsMode.Decoration)
			{
				if (Tool.RigidbodyEx.UnityRigidbody != null)
				{
					UnityEngine.Object.Destroy(Tool.RigidbodyEx.UnityRigidbody);
				}
				Tool.RigidbodyEx.UnityRigidbody = null;
				Tool.RigidbodyEx.SetKinematic("PhysicsMode", addKinematic: true);
			}
			else if (CurrentPhysicsMode == PhysicsMode.Trigger)
			{
				if (Tool.RigidbodyEx.UnityRigidbody == null)
				{
					Tool.RigidbodyEx.UnityRigidbody = Tool.gameObject.AddComponent<Rigidbody>();
				}
				Tool.RigidbodyEx.SetKinematic("PhysicsMode", addKinematic: true);
			}
			else if (CurrentPhysicsMode == PhysicsMode.Physical || CurrentPhysicsMode == PhysicsMode.Physical_Sticky)
			{
				if (Tool.RigidbodyEx.UnityRigidbody == null)
				{
					Tool.RigidbodyEx.UnityRigidbody = Tool.gameObject.AddComponent<Rigidbody>();
				}
				Tool.RigidbodyEx.enabled = true;
				Tool.RigidbodyEx.SetKinematic("PhysicsMode", addKinematic: false);
			}
			UpdateRigidbodyMechanics();
		}

		private void UpdateRigidbodyMechanics(bool force = true)
		{
			if (!IsEmpty && (CurrentPhysicsMode == PhysicsMode.Physical || CurrentPhysicsMode == PhysicsMode.Physical_Sticky || force))
			{
				float mass = Tool.RigidbodyEx.mass;
				float num = 0f;
				Vector3 zero = Vector3.zero;
				int shapeCount = shapeArray.ShapeCount;
				for (int i = 0; i < shapeCount; i++)
				{
					Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
					float mass2 = shapeByIndex.Mass;
					num += mass2;
					Vector3 vector = base.transform.InverseTransformPoint(shapeByIndex.WorldCenterOfMass);
					zero += vector * mass2;
				}
				Tool.RigidbodyEx.mass = Mathf.Max(num, 1E-05f);
				Tool.RigidbodyEx.localCenterOfMass = (zero / num).ValueOrZeroIfBogus();
				if (Tool.ConnectableTool != null)
				{
					Tool.ConnectableTool.SetConnectionPoint(0, Tool.RigidbodyEx.worldCenterOfMass);
				}
				Tool.RigidbodyEx.ResetInertiaTensor();
			}
		}

		private void RefreshTagsAndLayers()
		{
			GetPreferredLayers(CurrentPhysicsMode, out var defaultLayer, out var heldLayer, out var equippedLayer, out var attachedLayer);
			string preferredTag = GetPreferredTag(CurrentPhysicsMode);
			SetTagAndLayers(defaultLayer, heldLayer, equippedLayer, attachedLayer, preferredTag);
		}

		private void GetPreferredLayers(PhysicsMode physicsMode, out Layers defaultLayer, out Layers heldLayer, out Layers equippedLayer, out Layers attachedLayer)
		{
			switch (physicsMode)
			{
			case PhysicsMode.Environment:
			case PhysicsMode.Physical_Sticky:
			case PhysicsMode.Physical:
				defaultLayer = Tool.DEFAULT_LAYER;
				heldLayer = Tool.DEFAULT_HELD_LAYER;
				equippedLayer = Tool.DEFAULT_EQUIPPED_LAYER;
				attachedLayer = Tool.DEFAULT_ATTACHED_LAYER;
				break;
			case PhysicsMode.Trigger:
				defaultLayer = Layers.TriggerCollider;
				heldLayer = Layers.TriggerCollider;
				equippedLayer = Layers.TriggerCollider;
				attachedLayer = Layers.TriggerCollider;
				break;
			case PhysicsMode.Decoration:
				defaultLayer = Layers.Decoration;
				heldLayer = Layers.Decoration;
				equippedLayer = Layers.Decoration;
				attachedLayer = Layers.Decoration;
				break;
			default:
				throw new ArgumentException("physicsMode");
			}
		}

		protected virtual string GetPreferredTag(PhysicsMode physicsMode)
		{
			return "Untagged";
		}

		private void SetTagAndLayers(Layers defaultLayer, Layers heldLayer, Layers equippedLayer, Layers attachedLayer, string tag)
		{
			if (string.IsNullOrEmpty(tag))
			{
				tag = "Untagged";
			}
			Tool.DefaultCollisionLayer = defaultLayer;
			Tool.HeldCollisionLayer = heldLayer;
			Tool.EquippedCollisionLayer = equippedLayer;
			Tool.AttachedCollisionLayer = attachedLayer;
			if (!CreationObject.IsLocked)
			{
				Layers layers = (Tool.IsHeldByPlayer ? heldLayer : (Tool.IsEquippedOnPlayer ? equippedLayer : ((!Tool.IsAttachedToObject) ? defaultLayer : attachedLayer)));
				int layer = (int)layers;
				base.gameObject.layer = layer;
				Tool.gameObject.layer = layer;
				ShapeRoot.gameObject.layer = layer;
				int shapeCount = shapeArray.ShapeCount;
				for (int i = 0; i < shapeCount; i++)
				{
					Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
					shapeByIndex.GameObject.layer = layer;
					shapeByIndex.GameObject.tag = tag;
				}
			}
		}

