		public static int GetShapesCost(int colliderCosts, PhysicsMode physicsMode)
		{
			return Mathf.RoundToInt((float)colliderCosts * ShapeSettings.GetResourceMultiplierForPhysicsMode(physicsMode));
		}

		protected static int GetShapesCost(IEnumerable<Shape> shapes, PhysicsMode physicsMode)
		{
			int num = 0;
			foreach (Shape shape in shapes)
			{
				num += shape.ColliderCost;
			}
			return GetShapesCost(num, physicsMode);
		}

		public bool CanAffordToAddShapes(int colliderCosts)
		{
			int shapesCost = GetShapesCost(colliderCosts, CurrentPhysicsMode);
			int num = SandboxResourceCost + shapesCost;
			if (num > MaxResources)
			{
				return false;
			}
			if (!NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(shapesCost))
			{
				return false;
			}
			return true;
		}

		public int GetShapesCost(Guid[] shapeIds)
		{
			Shape[] shapesByIds = shapeArray.GetShapesByIds(shapeIds);
			return GetShapesCost(shapesByIds, CurrentPhysicsMode);
		}

		protected void MarkResourceCostsDirty()
		{
			if (!resourceCostsDirty)
			{
				resourceCostsDirty = true;
				this.InvokeNextEndOfFrame(CreationManager.MarkResourceCostsDirty);
			}
		}

		protected virtual int CalculateResourceCost(PhysicsMode? physicsModeOverride = null)
		{
			if (shapeArray.ShapeCount == 0 && !isSelectedByShapeCreationContext)
			{
				return 0;
			}
			PhysicsMode physicsMode = ((!physicsModeOverride.HasValue) ? CurrentPhysicsMode : physicsModeOverride.Value);
			int shapeContainerCostModificationForPhysicsMode = ShapeSettings.GetShapeContainerCostModificationForPhysicsMode(physicsMode);
			int shapesCost = GetShapesCost(shapeArray.AllShapes, physicsMode);
			return shapeContainerCostModificationForPhysicsMode + shapesCost;
		}

