		private UndoEntry OnRecolor(CreationContext context, params object[] modificationParameters)
		{
			UndoEntry result = null;
			if (modificationParameters != null)
			{
				ShapeColor color = (ShapeColor)modificationParameters[0];
				result = new RecolorShapesInstantUndoEntry(this, AllShapes, context, color);
				AuthoritySetShapeColors(color);
			}
			return result;
		}

		private void PlayAnimateInOutEffect()
		{
			if (SingletonMonoBehaviour<AnimateInOutManager>.Instance != null && !SingletonMonoBehaviour<AnimateInOutManager>.Instance.SuppressAnimations && SessionManager.IsCurrentSceneActive && !Tool.SuppressAnimateInOut)
			{
				int shapeCount = shapeArray.ShapeCount;
				for (int i = 0; i < shapeCount; i++)
				{
					Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
					Bounds worldBounds = shapeByIndex.WorldBounds;
					PooledParticle pooledParticle = ObjectPool.Instance.Acquire(SingletonMonoBehaviour<AnimateInOutManager>.Instance.DefaultEffectPrefab);
					pooledParticle.transform.SetParent(SingletonMonoBehaviour<AnimateInOutManager>.Instance.transform);
					pooledParticle.transform.position = worldBounds.center;
					pooledParticle.transform.rotation = Quaternion.identity;
					pooledParticle.PrimaryParticleSystem.Simulate(0.2f);
					pooledParticle.Play();
					ParticleSystem.ShapeModule shape = pooledParticle.PrimaryParticleSystem.shape;
					shape.scale = worldBounds.size * 1.3f;
					float num = Mathf.Max(worldBounds.size.x, worldBounds.size.y, worldBounds.size.z);
					ParticleSystem.MainModule main = pooledParticle.PrimaryParticleSystem.main;
					main.startSize = num * 0.3f;
				}
			}
		}

		private void ScheduleSizeUpdate()
		{
			if (!isSizeUpdateScheduled)
			{
				isSizeUpdateScheduled = true;
				this.EndOfFrameRoutine(UpdateSizeAndCompressionSetting);
			}
		}

