		public virtual void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			RoomPersistenceVersion version = deserializeParams.version;
			PersistenceViewData viewData = deserializeParams.viewData;
			if (viewData.ShapeContainerData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Shape Container {0}: data empty.", base.gameObject);
			}
			else if (PhotonNetwork.isMasterClient)
			{
				ShapeDataCollection shapeDataCollection = viewData.ShapeContainerData.ShapeCollection;
				if (deserializeParams.assignNewIds)
				{
					shapeDataCollection = viewData.ShapeContainerData.ShapeCollection.Clone();
					foreach (ShapeData shape in shapeDataCollection.Shapes)
					{
						shape.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(Guid.NewGuid());
					}
				}
				if (deserializeParams.isRuntimeCreated)
				{
					AuthorityAddShapes(shapeDataCollection);
				}
				else
				{
					LocalAddShapesFromRoomData(version, viewData);
				}
				if (version >= RoomPersistenceVersion.EXTRUSIONS_PHYSICS_MODE)
				{
					CurrentPhysicsMode = (PhysicsMode)viewData.ShapeContainerData.PhysicsMode;
				}
				else
				{
					CurrentPhysicsMode = ((!viewData.DeprecatedToolData.IsFrozen) ? PhysicsMode.Physical_Sticky : PhysicsMode.Environment);
				}
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat(this, "Tried to deserialize ShapeContainer {0} from a non-master client.", base.gameObject);
			}
		}

		private void VerifyShapeIds(RoomPersistenceVersion version, PersistenceViewData viewData)
		{
			RepeatedField<ShapeData> shapes = viewData.ShapeContainerData.ShapeCollection.Shapes;
			Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.Id);
			byte[] array = null;
			int num = 0;
			for (int i = 0; i < shapes.Count; i++)
			{
				ShapeData shapeData = shapes[i];
				if (!(RecRoom.Protobuf.ByteStringExtensions.ToGuid(shapeData.Id) != Guid.Empty))
				{
					num++;
					if (array == null)
					{
						array = guid.ToByteArray();
					}
					Guid guid2 = new Guid(i, BitConverter.ToInt16(array, 4), BitConverter.ToInt16(array, 6), array[8], array[9], array[10], array[11], array[12], array[13], array[14], array[15]);
					shapeData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(guid2);
				}
			}
			if (num > 0 && version >= RoomPersistenceVersion.SUBEXTRUSIONS_PERSISTED_IDS)
			{
				UnityEngine.Debug.LogError($"{num} invalid IDs found for ShapeContainer {DebugName}", this);
			}
		}

		private void VerifyCurveShapeCoordinateSpace(RoomPersistenceVersion version, PersistenceViewData viewData)
		{
			if (version >= RoomPersistenceVersion.CREATION_OBJECT_ADDED)
			{
				return;
			}
			RepeatedField<ShapeData> shapes = viewData.ShapeContainerData.ShapeCollection.Shapes;
			for (int i = 0; i < shapes.Count; i++)
			{
				ShapeData shapeData = shapes[i];
				if (shapeData.CurveShapeData != null)
				{
					RepeatedField<ControlPointData> controlPoints = shapeData.CurveShapeData.ControlPoints;
					Vector3 coordinateSpaceOrigin = shapeData.DEPRECATEDInitialLocalPosition.ToVector3();
					Quaternion coordinateSpaceRotation = shapeData.DEPRECATEDInitialLocalRotation.ToQuaternion();
					for (int j = 0; j < shapeData.CurveShapeData.ControlPoints.Count; j++)
					{
						controlPoints[j].Position = controlPoints[j].Position.ToVector3().InverseTransformCoordinateSpace(coordinateSpaceOrigin, coordinateSpaceRotation).ToVector3Data();
						controlPoints[j].Normal = controlPoints[j].Normal.ToVector3().InverseTransformCoordinateSpace(Vector3.zero, coordinateSpaceRotation).ToVector3Data();
					}
				}
			}
		}

		private void VerifyShapeScale(RoomPersistenceVersion version, PersistenceViewData viewData)
		{
			if (version >= RoomPersistenceVersion.CREATION_OBJECT_ADDED)
			{
				return;
			}
			RepeatedField<ShapeData> shapes = viewData.ShapeContainerData.ShapeCollection.Shapes;
			for (int i = 0; i < shapes.Count; i++)
			{
				ShapeData shapeData = shapes[i];
				if (shapeData.MeshShapeData != null)
				{
					Vector3 vector = Vector3.one;
					if (shapeData.DEPRECATEDScaleNonUniform != null)
					{
						vector = shapeData.DEPRECATEDScaleNonUniform.ToVector3();
					}
					else if (shapeData.MeshShapeData.LegacyScale != null)
					{
						vector = shapeData.MeshShapeData.LegacyScale.ToVector3();
					}
					float num = (shapeData.Scale = Mathf.Max(vector.x, vector.y, vector.z));
					if (num != 0f)
					{
						Vector3 vector2 = vector / num;
						shapeData.MeshShapeData.AspectRatio = vector2.ToVector3Data();
					}
					else
					{
						shapeData.MeshShapeData.AspectRatio = Vector3.one.ToVector3Data();
					}
				}
				else if (shapeData.CurveShapeData != null)
				{
					if (shapeData.DEPRECATEDScaleNonUniform != null)
					{
						Vector3 vector3 = shapeData.DEPRECATEDScaleNonUniform.ToVector3();
						shapeData.Scale = Mathf.Max(vector3.x, vector3.y, vector3.z);
					}
					else
					{
						shapeData.Scale = 1f;
					}
				}
			}
		}

		public virtual void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.ShapeContainerData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing {0}: Data already specified.", DebugName);
				return;
			}
			viewData.ShapeContainerData = new ShapeContainerData();
			ShapeDataCollection shapeDataCollection = SerializeShapes(base.transform);
			viewData.ShapeContainerData.ShapeCollection = shapeDataCollection;
			viewData.ShapeContainerData.PhysicsMode = (int)CurrentPhysicsMode;
			int shapeCount = shapeArray.ShapeCount;
			if (shapeCount != shapeDataCollection.Shapes.Count)
			{
				outputLog.AppendLine($"Expected {shapeCount} Shapes but output included {shapeDataCollection.Shapes.Count} when serializing Shape Container {viewData.Id}");
			}
		}
	}
	public class DecorationShapeContainer : ShapeContainer
	{
		[SerializeField]
		private int maxResources = 500;

		[SerializeField]
		private float editingBoundsRadius = 2f;

		private List<Shape> outOfBoundsShapes = new List<Shape>();

		private IDisposable outOfBoundsHighlightingToken;

		private IDisposable refreshOutOfBoundsShapesToken;

		private readonly ReactiveProperty<bool> hasOutOfBoundsShapes = new ReactiveProperty<bool>(initialValue: false);

		public override string DebugName => $"Decoration Shape Container {base.PersistenceView.Id}";

		public override string FriendlyName => "Decoration";

		public override int MaxResources => maxResources;

		public override bool DestroyIfEmpty => false;

		public override bool CanBeEditedAfterCreation => true;

		public override bool CanBeMerged => false;

		public override bool CanBeSplit => true;

		public override PhysicsMode DefaultPhysicsMode => PhysicsMode.Decoration;

		protected override RepositionWhenAddingFirstShape ShouldRepositionWhenAddingFirstShape
		{
			[CompilerGenerated]
			get
			{
				return RepositionWhenAddingFirstShape.Never;
			}
		}

		public IReactiveProperty<bool> HasOutOfBoundsShapes => hasOutOfBoundsShapes;

		protected override void Awake()
		{
			base.Awake();
			hasOutOfBoundsShapes.Observe(this, HasOutOfBoundsShapesChanged);
		}

		private void HasOutOfBoundsShapesChanged(bool value)
		{
			if (value)
			{
				if (false)
				{
					WarnShapesOutOfBounds();
				}
				outOfBoundsHighlightingToken = this.Update(HighlightOutOfBoundsShapes);
			}
			else if (outOfBoundsHighlightingToken != null)
			{
				outOfBoundsHighlightingToken.Dispose();
				outOfBoundsHighlightingToken = null;
			}
		}

		protected override void OnShapesChanged()
		{
			base.OnShapesChanged();
			if (refreshOutOfBoundsShapesToken != null)
			{
				refreshOutOfBoundsShapesToken.Dispose();
			}
			refreshOutOfBoundsShapesToken = this.InvokeNextFixedUpdate(RefreshOutOfBoundsShapes);
		}

		private void RefreshOutOfBoundsShapes()
		{
			outOfBoundsShapes.Clear();
			Physics.SyncTransforms();
			float num = editingBoundsRadius * editingBoundsRadius;
			int shapeCount = shapeArray.ShapeCount;
			for (int i = 0; i < shapeCount; i++)
			{
				Shape shapeByIndex = shapeArray.GetShapeByIndex(i);
				if (!(shapeByIndex.MeshRenderer != null))
				{
					continue;
				}
				Bounds worldBounds = shapeByIndex.WorldBounds;
				float sqrMagnitude = base.ShapeRoot.transform.InverseTransformPoint(worldBounds.min).sqrMagnitude;
				if (sqrMagnitude > num)
				{
					outOfBoundsShapes.Add(shapeByIndex);
					continue;
				}
				float sqrMagnitude2 = base.ShapeRoot.transform.InverseTransformPoint(worldBounds.max).sqrMagnitude;
				if (sqrMagnitude2 > num)
				{
					outOfBoundsShapes.Add(shapeByIndex);
				}
			}
			hasOutOfBoundsShapes.Value = outOfBoundsShapes.Count > 0;
		}

		protected virtual void WarnShapesOutOfBounds()
		{
		}

		private void HighlightOutOfBoundsShapes()
		{
			if (false)
			{
				foreach (Shape outOfBoundsShape in outOfBoundsShapes)
				{
					if (outOfBoundsShape.MeshRenderer != null)
					{
						OutlineEffectRenderer.RenderWarningOutline(outOfBoundsShape.MeshRenderer, 1, renderWhenDisabled: true);
					}
				}
				return;
			}
			RenderBatchedOutline(OutlineEffectRenderer.OutlineType.Warning);
		}
	}
	public class BatchedMesh : DynamicMesh
	{
		private class BatchedMeshEntry
		{
			public DynamicMesh mesh;

			public int vertexStartIndex;

			public int indexStartIndex;
		}

		private List<BatchedMeshEntry> batchedMeshes;

		public int EntryCount => batchedMeshes.Count;

		public BatchedMesh(string name)
			: base(name)
		{
			batchedMeshes = new List<BatchedMeshEntry>();
		}

		public void AddMesh(DynamicMesh mesh, Matrix4x4 meshTransformation)
		{
			BatchedMeshEntry batchedMeshEntry = new BatchedMeshEntry();
			batchedMeshEntry.mesh = mesh;
			batchedMeshEntry.vertexStartIndex = base.cachedVertices.Count;
			batchedMeshEntry.indexStartIndex = base.cachedIndices.Count;
			base.cachedTangents.AddRange(mesh.Tangents);
			base.cachedVertexColors.AddRange(mesh.VertexColors);
			base.cachedUVs.AddRange(mesh.UVs);
			int count = base.cachedVertices.Count;
			base.cachedVertices.AddRange(mesh.Vertices);
			base.cachedNormals.AddRange(mesh.Normals);
			Matrix4x4 inverse = meshTransformation.transpose.inverse;
			for (int i = count; i < base.cachedVertices.Count; i++)
			{
				base.cachedVertices[i] = meshTransformation.MultiplyPoint3x4(base.cachedVertices[i]);
				base.cachedNormals[i] = inverse.MultiplyVector(base.cachedNormals[i]).normalized;
			}
			int count2 = base.cachedIndices.Count;
			base.cachedIndices.AddRange(mesh.Indices);
			for (int j = count2; j < base.cachedIndices.Count; j++)
			{
				base.cachedIndices[j] += batchedMeshEntry.vertexStartIndex;
			}
			batchedMeshes.Add(batchedMeshEntry);
		}

		public bool RemoveMesh(DynamicMesh mesh)
		{
			BatchedMeshEntry entryForMesh = GetEntryForMesh(mesh);
			if (entryForMesh != null)
			{
				batchedMeshes.Remove(entryForMesh);
				int count = entryForMesh.mesh.Vertices.Count;
				int count2 = entryForMesh.mesh.Indices.Count;
				base.cachedVertices.RemoveRange(entryForMesh.vertexStartIndex, count);
				base.cachedIndices.RemoveRange(entryForMesh.indexStartIndex, count2);
				base.cachedNormals.RemoveRange(entryForMesh.vertexStartIndex, count);
				base.cachedTangents.RemoveRange(entryForMesh.vertexStartIndex, count);
				base.cachedUVs.RemoveRange(entryForMesh.vertexStartIndex, count);
				base.cachedVertexColors.RemoveRange(entryForMesh.vertexStartIndex, count);
				for (int i = entryForMesh.indexStartIndex; i < base.cachedIndices.Count; i++)
				{
					base.cachedIndices[i] -= count;
				}
				for (int j = 0; j < batchedMeshes.Count; j++)
				{
					if (batchedMeshes[j].indexStartIndex > entryForMesh.indexStartIndex)
					{
						batchedMeshes[j].indexStartIndex -= count2;
						batchedMeshes[j].vertexStartIndex -= count;
					}
				}
				return true;
			}
			return false;
		}

		public bool UpdateMeshColor(DynamicMesh mesh, Color color)
		{
			BatchedMeshEntry entryForMesh = GetEntryForMesh(mesh);
			if (entryForMesh != null)
			{
				SetCachedColor(color, entryForMesh.vertexStartIndex, entryForMesh.mesh.Vertices.Count);
				return true;
			}
			return false;
		}

		public bool UpdateMeshVertices(DynamicMesh mesh, Matrix4x4 meshTransformation)
		{
			BatchedMeshEntry entryForMesh = GetEntryForMesh(mesh);
			if (entryForMesh != null)
			{
				Matrix4x4 inverse = meshTransformation.transpose.inverse;
				int vertexStartIndex = entryForMesh.vertexStartIndex;
				for (int i = 0; i < mesh.cachedVertices.Count; i++)
				{
					int index = i + vertexStartIndex;
					base.cachedVertices[index] = meshTransformation.MultiplyPoint3x4(mesh.cachedVertices[i]);
					base.cachedNormals[index] = inverse.MultiplyVector(mesh.cachedNormals[i]).normalized;
				}
				return true;
			}
			return false;
		}

		public void Move(Vector3 movement)
		{
			for (int i = 0; i < base.cachedVertices.Count; i++)
			{
				base.cachedVertices[i] += movement;
			}
		}

		private BatchedMeshEntry GetEntryForMesh(DynamicMesh mesh)
		{
			BatchedMeshEntry result = null;
			for (int i = 0; i < batchedMeshes.Count; i++)
			{
				if (batchedMeshes[i].mesh == mesh)
				{
					result = batchedMeshes[i];
					break;
				}
			}
			return result;
		}
	}
	public abstract class CurveMesh : DynamicMesh
	{
		protected const float U_WRAPAROUND_DISTANCE = 1f;

		private const float MIN_CORNER_ANGLE = 15f;

		private const float MIN_CORNER_DISTANCE = 0.1f;

		private const float MIN_CORNER_DISTANCE_SQR = 0.010000001f;

		public CurveMesh()
			: base("Curve Mesh")
		{
		}

		public void GenerateMeshFromCurve(Curve curve, Color color)
		{
			int count = base.cachedVertices.Count;
			FreeVertices(count);
			int count2 = base.cachedIndices.Count;
			FreeIndices(count2);
			AddCurveControlPoints(curve, color);
			CopyChangesToGPU();
		}

		private void AddCurveControlPoints(Curve curve, Color color)
		{
			int count = curve.ControlPoints.Count;
			if (count > 0)
			{
				AddStartCap(curve.ControlPoints[0], color);
				AddMeshSegment(curve.ControlPoints[0], curve.ControlPoints[0], color);
				for (int i = 1; i < count; i++)
				{
					TryAddCornerMeshSegments(curve.ControlPoints[i], curve.ControlPoints[i - 1], color);
					AddMeshSegment(curve.ControlPoints[i], curve.ControlPoints[i - 1], color);
				}
				AddEndCap(curve.ControlPoints[count - 1], color);
			}
		}

		private void TryAddCornerMeshSegments(ControlPoint current, ControlPoint previous, Color color)
		{
			float sqrMagnitude = (current.Position - previous.Position).sqrMagnitude;
			float num = Vector3.Angle(previous.Tangent, current.Tangent);
			if (!(sqrMagnitude < 0.010000001f) && !(num < 15f))
			{
				ControlPoint controlPoint = new ControlPoint(previous);
				controlPoint.Position = current.Position - previous.Tangent * 2f * current.Radius;
				ControlPoint controlPoint2 = ControlPoint.Interpolate(previous, current, 0.5f);
				controlPoint2.Position = current.Position;
				ControlPoint controlPoint3 = new ControlPoint(current);
				controlPoint3.Position = current.Position + current.Tangent * 2f * current.Radius;
				ControlPoint controlPoint4 = ControlPoint.Interpolate(controlPoint, controlPoint2, 0.5f);
				ControlPoint controlPoint5 = ControlPoint.Interpolate(controlPoint2, controlPoint3, 0.5f);
				AddMeshSegment(controlPoint, previous, color);
				AddMeshSegment(controlPoint4, previous, color);
				AddMeshSegment(controlPoint2, previous, color);
				AddMeshSegment(controlPoint5, previous, color);
				AddMeshSegment(controlPoint3, previous, color);
			}
		}

		protected abstract void AddMeshSegment(ControlPoint controlPoint, ControlPoint previousControlPoint, Color color);

		protected abstract void AddStartCap(ControlPoint startControlPoint, Color color);

		protected abstract void AddEndCap(ControlPoint endControlPoint, Color color);
	}
	public class TubeCurveMesh : CurveMesh
	{
		private const int SEGMENT_VERTEX_COUNT = 3;

		private const int SEGMENT_INDEX_COUNT = 18;

		private const float SEGMENT_ANGLE = (float)Math.PI * 2f / 3f;

		private const int CAP_INDEX_COUNT = 9;

		protected override void AddMeshSegment(ControlPoint controlPoint, ControlPoint previousControlPoint, Color color)
		{
			int num = AllocateVertices(3);
			AddVertexRing(num, controlPoint, previousControlPoint, color);
			if (base.cachedVertices.Count > 4)
			{
				int indexStartIndex = AllocateIndices(18);
				AddRingIndices(num, indexStartIndex);
			}
		}

		protected override void AddStartCap(ControlPoint startControlPoint, Color color)
		{
			Vector4 tangent = new Vector4(startControlPoint.Binormal.x, startControlPoint.Binormal.y, startControlPoint.Binormal.z, 1f);
			Vector2 uv = new Vector2(0.5f, 0.5f);
			int num = AllocateVertices(1);
			SetVertex(num, startControlPoint.Position, -startControlPoint.Tangent, tangent, color, uv);
			int indexStartIndex = AllocateIndices(9);
			SetStartCapIndices(num, num + 1, indexStartIndex);
		}

		protected override void AddEndCap(ControlPoint endControlPoint, Color color)
		{
			Vector4 tangent = new Vector4(endControlPoint.Binormal.x, endControlPoint.Binormal.y, endControlPoint.Binormal.z, 1f);
			Vector2 uv = new Vector2(0.5f, 0.5f);
			int num = AllocateVertices(1);
			SetVertex(num, endControlPoint.Position, endControlPoint.Tangent, tangent, color, uv);
			int indexStartIndex = AllocateIndices(9);
			SetEndCapIndices(num, num - 3, indexStartIndex);
		}

		private void AddVertexRing(int ringVericesStartIndex, ControlPoint controlPoint, ControlPoint previousControlPoint, Color color)
		{
			float num = 0f;
			float magnitude = (controlPoint.Position - previousControlPoint.Position).magnitude;
			float x = ((ringVericesStartIndex <= 0) ? 0f : base.cachedUVs[ringVericesStartIndex - 1].x) + magnitude / 1f;
			for (int i = 0; i < 3; i++)
			{
				Vector3 vector = controlPoint.Position + controlPoint.Binormal * controlPoint.Radius * Mathf.Cos(num) + controlPoint.Normal * controlPoint.Radius * Mathf.Sin(num);
				Vector3 normalized = (vector - controlPoint.Position).normalized;
				SetVertex(tangent: new Vector4(controlPoint.Tangent.x, controlPoint.Tangent.y, controlPoint.Tangent.z, 1f), uv: new Vector2(x, (float)i / 2f), index: ringVericesStartIndex++, position: vector, normal: normalized, color: color);
				num += (float)Math.PI * 2f / 3f;
			}
		}

		private void AddRingIndices(int newSegmentStartIndex, int indexStartIndex)
		{
			int num = newSegmentStartIndex - 3;
			for (int i = 0; i < 3; i++)
			{
				int num2 = num + i;
				int num3 = num + (i + 1) % 3;
				int value = num2 + 3;
				int value2 = num3 + 3;
				base.cachedIndices[indexStartIndex++] = num2;
				base.cachedIndices[indexStartIndex++] = value2;
				base.cachedIndices[indexStartIndex++] = num3;
				base.cachedIndices[indexStartIndex++] = value2;
				base.cachedIndices[indexStartIndex++] = num2;
				base.cachedIndices[indexStartIndex++] = value;
			}
		}

		private void SetStartCapIndices(int capIndex, int segmentStartIndex, int indexStartIndex)
		{
			for (int i = 0; i < 3; i++)
			{
				int value = segmentStartIndex + i;
				int value2 = segmentStartIndex + (i + 1) % 3;
				base.cachedIndices[indexStartIndex++] = capIndex;
				base.cachedIndices[indexStartIndex++] = value;
				base.cachedIndices[indexStartIndex++] = value2;
			}
		}

		private void SetEndCapIndices(int capIndex, int segmentStartIndex, int indexStartIndex)
		{
			for (int i = 0; i < 3; i++)
			{
				int value = segmentStartIndex + i;
				int value2 = segmentStartIndex + (i + 1) % 3;
				base.cachedIndices[indexStartIndex++] = value;
				base.cachedIndices[indexStartIndex++] = capIndex;
				base.cachedIndices[indexStartIndex++] = value2;
			}
		}
	}
	public class RibbonCurveMesh : CurveMesh
	{
		private const int SEGMENT_VERTEX_COUNT = 2;

		private const int SEGMENT_INDEX_COUNT = 12;

		private const float SEGMENT_ANGLE = (float)Math.PI;

		protected override void AddMeshSegment(ControlPoint controlPoint, ControlPoint previousControlPoint, Color color)
		{
			int num = AllocateVertices(2);
			AddVertexSpan(num, controlPoint, previousControlPoint, color);
			if (base.cachedVertices.Count > 2)
			{
				int indexStartIndex = AllocateIndices(12);
				AddSpanIndices(num, indexStartIndex);
			}
		}

		protected override void AddEndCap(ControlPoint endControlPoint, Color color)
		{
		}

		protected override void AddStartCap(ControlPoint startControlPoint, Color color)
		{
		}

		private void AddVertexSpan(int segmentStartIndex, ControlPoint controlPoint, ControlPoint previousControlPoint, Color color)
		{
			Vector3 position = controlPoint.Position - controlPoint.Binormal * controlPoint.Radius;
			Vector3 position2 = controlPoint.Position + controlPoint.Binormal * controlPoint.Radius;
			Vector4 tangent = new Vector4(controlPoint.Tangent.x, controlPoint.Tangent.y, controlPoint.Tangent.z, 1f);
			float magnitude = (controlPoint.Position - previousControlPoint.Position).magnitude;
			float x = ((segmentStartIndex <= 0) ? 0f : base.cachedUVs[segmentStartIndex - 1].x) + magnitude / 1f;
			Vector2 uv = new Vector2(x, 1f);
			Vector2 uv2 = new Vector2(x, 0f);
			SetVertex(segmentStartIndex++, position, controlPoint.Normal, tangent, color, uv);
			SetVertex(segmentStartIndex++, position2, controlPoint.Normal, tangent, color, uv2);
		}

		private void AddSpanIndices(int newSegmentStartIndex, int indexStartIndex)
		{
			int num = newSegmentStartIndex - 2;
			int value = num;
			int value2 = num + 1;
			int value3 = newSegmentStartIndex + 1;
			base.cachedIndices[indexStartIndex++] = value;
			base.cachedIndices[indexStartIndex++] = value3;
			base.cachedIndices[indexStartIndex++] = newSegmentStartIndex;
			base.cachedIndices[indexStartIndex++] = value3;
			base.cachedIndices[indexStartIndex++] = value;
			base.cachedIndices[indexStartIndex++] = value2;
			base.cachedIndices[indexStartIndex++] = newSegmentStartIndex;
			base.cachedIndices[indexStartIndex++] = value3;
			base.cachedIndices[indexStartIndex++] = value;
			base.cachedIndices[indexStartIndex++] = value2;
			base.cachedIndices[indexStartIndex++] = value;
			base.cachedIndices[indexStartIndex++] = value3;
		}
	}
	public class DynamicMesh
	{
		public List<Vector3> cachedVertices { get; protected set; }

		public List<Vector3> cachedNormals { get; protected set; }

		public List<Vector4> cachedTangents { get; protected set; }

		public List<Color> cachedVertexColors { get; protected set; }

		public List<Vector2> cachedUVs { get; protected set; }

		public List<int> cachedIndices { get; protected set; }

		public Mesh Mesh { get; protected set; }

		public ReadOnlyCollection<Vector3> Vertices => cachedVertices.AsReadOnly();

		public ReadOnlyCollection<int> Indices => cachedIndices.AsReadOnly();

		public ReadOnlyCollection<Vector3> Normals => cachedNormals.AsReadOnly();

		public ReadOnlyCollection<Vector4> Tangents => cachedTangents.AsReadOnly();

		public ReadOnlyCollection<Vector2> UVs => cachedUVs.AsReadOnly();

		public ReadOnlyCollection<Color> VertexColors => cachedVertexColors.AsReadOnly();

		protected DynamicMesh(string name)
		{
			Mesh = new Mesh();
			Mesh.name = name;
			Mesh.MarkDynamic();
			cachedVertices = new List<Vector3>();
			cachedNormals = new List<Vector3>();
			cachedTangents = new List<Vector4>();
			cachedVertexColors = new List<Color>();
			cachedUVs = new List<Vector2>();
			cachedIndices = new List<int>();
		}

		public DynamicMesh(Mesh meshTemplate)
			: this(meshTemplate.name + " (Clone)")
		{
			cachedVertices.AddRange(meshTemplate.vertices);
			cachedIndices.AddRange(meshTemplate.GetIndices(0));
			cachedNormals.AddRange(meshTemplate.normals);
			cachedTangents.AddRange(meshTemplate.tangents);
			meshTemplate.GetUVs(0, cachedUVs);
		}

		public void CopyChangesToGPU()
		{
			Mesh.Clear();
			Mesh.SetVertices(cachedVertices);
			Mesh.SetNormals(cachedNormals);
			Mesh.SetTangents(cachedTangents);
			Mesh.SetColors(cachedVertexColors);
			Mesh.SetUVs(0, cachedUVs);
			Mesh.SetTriangles(cachedIndices, 0);
			Mesh.RecalculateBounds();
		}

		protected void SetVertex(int index, Vector3 position, Vector3 normal, Vector4 tangent, Color color, Vector2 uv)
		{
			cachedVertices[index] = position;
			cachedNormals[index] = normal;
			cachedTangents[index] = tangent;
			cachedVertexColors[index] = color;
			cachedUVs[index] = uv;
		}

		protected int AllocateVertices(int vertexCount)
		{
			int count = cachedVertices.Count;
			for (int i = 0; i < vertexCount; i++)
			{
				cachedVertices.Add(Vector3.zero);
				cachedNormals.Add(Vector3.zero);
				cachedTangents.Add(Vector4.zero);
				cachedVertexColors.Add(Color.blue);
				cachedUVs.Add(Vector2.zero);
			}
			return count;
		}

		protected void FreeVertices(int vertexCount)
		{
			int index = Mathf.Max(0, cachedVertices.Count - vertexCount);
			cachedVertices.RemoveRange(index, vertexCount);
			cachedNormals.RemoveRange(index, vertexCount);
			cachedTangents.RemoveRange(index, vertexCount);
			cachedVertexColors.RemoveRange(index, vertexCount);
			cachedUVs.RemoveRange(index, vertexCount);
		}

		protected int AllocateIndices(int indexCount)
		{
			int count = cachedIndices.Count;
			for (int i = 0; i < indexCount; i++)
			{
				cachedIndices.Add(0);
			}
			return count;
		}

		protected void FreeIndices(int indexCount)
		{
			int index = Mathf.Max(0, cachedIndices.Count - indexCount);
			cachedIndices.RemoveRange(index, indexCount);
		}

		public void SetCachedColor(Color color)
		{
			SetCachedColor(color, 0, cachedVertexColors.Count);
		}

		public void SetCachedColor(Color color, int index, int count)
		{
			int num = index + count;
			for (int i = index; i < num; i++)
			{
				cachedVertexColors[i] = color;
			}
		}
	}
	public class ShapeMesh : DynamicMesh
	{
		private readonly ShapeType shapeType;

		private static DynamicMesh boxMesh;

		private static DynamicMesh sphereMesh;

		private static DynamicMesh cylinderMesh;

		private static DynamicMesh wedgeMesh;

		private static DynamicMesh pyramidMesh;

		private static DynamicMesh triggerVolumeMesh;

		public ShapeMesh(Transform parent, ShapeType shapeType, Color color, bool copyToGPU = true)
			: base("ShapeMesh")
		{
			this.shapeType = shapeType;
			DynamicMesh baseMesh = GetBaseMesh(shapeType);
			base.cachedVertices = baseMesh.cachedVertices;
			base.cachedIndices = baseMesh.cachedIndices;
			base.cachedNormals = baseMesh.cachedNormals;
			base.cachedTangents = baseMesh.cachedTangents;
			base.cachedUVs = baseMesh.cachedUVs;
			for (int i = 0; i < base.cachedVertices.Count; i++)
			{
				base.cachedVertexColors.Add(color);
			}
			if (copyToGPU)
			{
				CopyChangesToGPU();
			}
		}

		public void SetSize(Vector3 size, bool copyToGPU)
		{
			DynamicMesh baseMesh = GetBaseMesh(shapeType);
			List<Vector3> list = baseMesh.cachedVertices;
			base.cachedVertices = new List<Vector3>(list.Count);
			Matrix4x4 matrix4x = Matrix4x4.Scale(size);
			for (int i = 0; i < base.cachedVertices.Count; i++)
			{
				base.cachedVertices[i] = matrix4x * list[i];
			}
		}

		private static DynamicMesh GetBaseMesh(ShapeType shapeType)
		{
			switch (shapeType)
			{
			case ShapeType.Box:
				if (boxMesh == null)
				{
					boxMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.Box));
				}
				return boxMesh;
			case ShapeType.Sphere:
				if (sphereMesh == null)
				{
					sphereMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.Sphere));
				}
				return sphereMesh;
			case ShapeType.Cylinder:
				if (cylinderMesh == null)
				{
					cylinderMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.Cylinder));
				}
				return cylinderMesh;
			case ShapeType.Wedge:
				if (wedgeMesh == null)
				{
					wedgeMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.Wedge));
				}
				return wedgeMesh;
			case ShapeType.Pyramid:
				if (pyramidMesh == null)
				{
					pyramidMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.Pyramid));
				}
				return pyramidMesh;
			case ShapeType.TriggerVolumeBox:
				if (triggerVolumeMesh == null)
				{
					triggerVolumeMesh = new DynamicMesh(ShapeSettings.GetShapeRenderMesh(ShapeType.TriggerVolumeBox));
				}
				return triggerVolumeMesh;
			default:
				return null;
			}
		}
	}
	public enum ShapeType
	{
		Invalid = -1,
		Tube = 0,
		Ribbon = 1,
		Box = 2,
		Sphere = 3,
		Cylinder = 4,
		Wedge = 5,
		Pyramid = 6,
		TriggerVolumeBox = 7,
		MIN_VALUE = -1,
		MAX_VALUE = 7
	}
