	[Obfuscation(Exclude = true)]
	public class ShapeContainerDataBitPacker
	{
		private const float TubeControlPointRadiusCompressionErrorTolerance = 0.005f;

		private const int TubeControlPointRadiusCompressionMinBits = 4;

		private const int TubeControlPointRadiusCompressionMaxBits = 20;

		[RuntimeInitializeOnLoadMethod]
		private static void RegisterRpcSerializationHandlers()
		{
			PhotonRpcSerialization.AddBitPackHandler(CompressShapeContainer, DecompressShapeContainer);
			PhotonRpcSerialization.AddBitPackHandler(CompressShapeContainerCollection, DecompressShapeContainerCollection);
			PhotonRpcSerialization.AddBitPackHandler(CompressShapeCollection, DecompressShapeCollection);
		}

		private static void CompressShapeContainerCollection(RecRoom.Networking.BitPacker bitPacker, ShapeContainerDataCollection collection)
		{
			bitPacker.WriteList(collection.ShapeContainers, CompressShapeContainer);
		}

		private static ShapeContainerDataCollection DecompressShapeContainerCollection(RecRoom.Networking.BitPacker bitPacker)
		{
			ShapeContainerDataCollection shapeContainerDataCollection = new ShapeContainerDataCollection();
			shapeContainerDataCollection.ShapeContainers.AddRange(bitPacker.ReadList(DecompressShapeContainer));
			return shapeContainerDataCollection;
		}

		private static void CompressShapeContainer(RecRoom.Networking.BitPacker bitPacker, ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry entry)
		{
			bitPacker.WriteVarUInt((uint)entry.PhotonViewId);
			bitPacker.WriteBool(entry.Unchanged);
			if (!entry.Unchanged)
			{
				CompressShapeCollection(bitPacker, entry.Shapes);
			}
		}

		private static ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry DecompressShapeContainer(RecRoom.Networking.BitPacker bitPacker)
		{
			ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry shapeContainerDataCollectionEntry = new ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry();
			shapeContainerDataCollectionEntry.PhotonViewId = (int)bitPacker.ReadVarUInt();
			shapeContainerDataCollectionEntry.Unchanged = bitPacker.ReadBool();
			if (!shapeContainerDataCollectionEntry.Unchanged)
			{
				shapeContainerDataCollectionEntry.Shapes = DecompressShapeCollection(bitPacker);
			}
			return shapeContainerDataCollectionEntry;
		}

		private static void CompressShapeCollection(RecRoom.Networking.BitPacker bitPacker, ShapeDataCollection collection)
		{
			bitPacker.WriteList(collection.Shapes, CompressShapes);
		}

		private static ShapeDataCollection DecompressShapeCollection(RecRoom.Networking.BitPacker bitPacker)
		{
			ShapeDataCollection shapeDataCollection = new ShapeDataCollection();
			shapeDataCollection.Shapes.AddRange(bitPacker.ReadList(DecompressShapes));
			return shapeDataCollection;
		}

		private static void CompressShapes(RecRoom.Networking.BitPacker bitPacker, ShapeData shape)
		{
			bitPacker.WriteGuid(RecRoom.Protobuf.ByteStringExtensions.ToGuid(shape.Id));
			bitPacker.WriteInt(shape.ShapeType, -1, 7);
			bitPacker.WriteInt(shape.ShapeColor, 0, 15);
			bitPacker.WritePosition(shape.CurrentLocalPosition.ToVector3());
			bitPacker.WriteRotation(shape.CurrentLocalRotation.ToQuaternion(), !shape.UseUncompressedRotation);
			bitPacker.WriteScale(shape.Scale);
			bitPacker.WriteUncompressedFloat(shape.Density);
			if (ShapeContainer.IsCurveShape((ShapeType)shape.ShapeType))
			{
				float num = ShapeContainer.MAX_CURVE_SHAPE_TUBE_RADIUS * shape.Scale;
				uint maxValue = (uint)(num / 0.005f);
				int radiusRequiredBits = Mathf.Clamp(RecRoom.Networking.BitPacker.RequiredBits(maxValue), 4, 20);
				bitPacker.WriteInt(radiusRequiredBits, 4, 20);
				bitPacker.WriteList(shape.CurveShapeData.ControlPoints, delegate(RecRoom.Networking.BitPacker bp, ControlPointData e)
				{
					CompressTubeControlPoint(bp, e, radiusRequiredBits);
				});
			}
			else if (ShapeContainer.IsMeshShape((ShapeType)shape.ShapeType))
			{
				bitPacker.WriteScale(shape.MeshShapeData.AspectRatio.X);
				bitPacker.WriteScale(shape.MeshShapeData.AspectRatio.Y);
				bitPacker.WriteScale(shape.MeshShapeData.AspectRatio.Z);
			}
		}

		private static ShapeData DecompressShapes(RecRoom.Networking.BitPacker bitPacker)
		{
			ShapeData shapeData = new ShapeData();
			shapeData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(bitPacker.ReadGuid());
			shapeData.ShapeType = bitPacker.ReadInt(-1, 7);
			shapeData.ShapeColor = bitPacker.ReadInt(0, 15);
			shapeData.CurrentLocalPosition = bitPacker.ReadPosition().ToVector3Data();
			shapeData.CurrentLocalRotation = bitPacker.ReadRotation(out var wasCompressed).ToVector3Data();
			shapeData.UseUncompressedRotation = !wasCompressed;
			shapeData.Scale = bitPacker.ReadScale();
			shapeData.Density = bitPacker.ReadUncompressedFloat();
			if (ShapeContainer.IsCurveShape((ShapeType)shapeData.ShapeType))
			{
				int radiusRequiredBits = bitPacker.ReadInt(4, 20);
				shapeData.CurveShapeData = new CurveShapeData();
				shapeData.CurveShapeData.ControlPoints.AddRange(bitPacker.ReadList((RecRoom.Networking.BitPacker bp) => DecompressTubeControlPoint(bp, radiusRequiredBits)));
			}
			else if (ShapeContainer.IsMeshShape((ShapeType)shapeData.ShapeType))
			{
				shapeData.MeshShapeData = new MeshShapeData();
				shapeData.MeshShapeData.AspectRatio = new RecRoom.Protobuf.Vector3Data();
				shapeData.MeshShapeData.AspectRatio.X = bitPacker.ReadScale();
				shapeData.MeshShapeData.AspectRatio.Y = bitPacker.ReadScale();
				shapeData.MeshShapeData.AspectRatio.Z = bitPacker.ReadScale();
			}
			return shapeData;
		}

		private static void CompressTubeControlPoint(RecRoom.Networking.BitPacker bitPacker, ControlPointData controlPoint, int radiusRequiredBits)
		{
			bitPacker.WritePosition(controlPoint.Position.ToVector3());
			bitPacker.WriteNormal(controlPoint.Normal.ToVector3());
			bitPacker.WriteFloat(controlPoint.Radius, 0f, ShapeContainer.MAX_CURVE_SHAPE_TUBE_RADIUS, radiusRequiredBits);
		}

		private static ControlPointData DecompressTubeControlPoint(RecRoom.Networking.BitPacker bitPacker, int radiusRequiredBits)
		{
			ControlPointData controlPointData = new ControlPointData();
			controlPointData.Position = bitPacker.ReadPosition().ToVector3Data();
			controlPointData.Normal = bitPacker.ReadNormal().ToVector3Data();
			controlPointData.Radius = bitPacker.ReadFloat(0f, ShapeContainer.MAX_CURVE_SHAPE_TUBE_RADIUS, radiusRequiredBits);
			return controlPointData;
		}
	}
	public class ShapeManager : Photon.MonoBehaviour
	{
		private bool isPhotonNetworkPaused;

		public static bool AllShapeContainersInitialized
		{
			get
			{
				foreach (ShapeContainer allShapeContainer in ShapeContainer.AllShapeContainers)
				{
					if (allShapeContainer.WaitingForShapeData)
					{
						return false;
					}
				}
				return true;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		}

		private void Start()
		{
			NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.MasterRoomDeserializationCompleteEvent += OnRoomDeserializationComplete;
			foreach (ShapeContainer allShapeContainer in ShapeContainer.AllShapeContainers)
			{
				if (!allShapeContainer.hasAuthority)
				{
					allShapeContainer.MarkWaitingForShapeData();
				}
			}
		}

		protected override void OnDestroy()
		{
			SetPhotonNetworkPaused(paused: false);
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			if (NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.MasterRoomDeserializationCompleteEvent -= OnRoomDeserializationComplete;
			}
			base.OnDestroy();
		}

		private void SetPhotonNetworkPaused(bool paused)
		{
			if (isPhotonNetworkPaused != paused)
			{
				isPhotonNetworkPaused = paused;
				if (paused)
				{
					NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.PauseMessageQueue();
				}
				else
				{
					NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.ResumeMessageQueue();
				}
			}
		}

		private ShapeContainerDataCollection SerializeAuthorityShapeContainers()
		{
			bool flag = !string.IsNullOrEmpty(NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RoomDataBlobName);
			ShapeContainerDataCollection shapeContainerDataCollection = new ShapeContainerDataCollection();
			foreach (ShapeContainer allShapeContainer in ShapeContainer.AllShapeContainers)
			{
				if (allShapeContainer.hasAuthority)
				{
					ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry shapeContainerDataCollectionEntry = new ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry();
					shapeContainerDataCollectionEntry.PhotonViewId = allShapeContainer.photonView.viewID;
					if (flag && allShapeContainer.ShapesUnchangedFromRoomData)
					{
						shapeContainerDataCollectionEntry.Unchanged = true;
					}
					else
					{
						shapeContainerDataCollectionEntry.Shapes = allShapeContainer.SerializeShapes();
					}
					shapeContainerDataCollection.ShapeContainers.Add(shapeContainerDataCollectionEntry);
				}
			}
			return shapeContainerDataCollection;
		}

		private IEnumerator RemoteDeserializeShapeContainers(ShapeContainerDataCollection shapeContainersData)
		{
			bool anyUnchanged = false;
			foreach (ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry shapeContainer in shapeContainersData.ShapeContainers)
			{
				if (shapeContainer.Unchanged)
				{
					anyUnchanged = true;
					break;
				}
			}
			Dictionary<Guid, PersistenceViewData> roomDataShapeContainers = null;
			RoomPersistenceVersion roomDataVersion = RoomPersistenceVersion.INVALID;
			if (anyUnchanged)
			{
				if (!NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.GetRoomDataBlobPromise.IsCompleted)
				{
					SetPhotonNetworkPaused(paused: true);
					yield return NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.GetRoomDataBlobPromise;
					SetPhotonNetworkPaused(paused: false);
				}
				byte[] roomDataBytes = null;
				string roomLoadError = null;
				NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.GetRoomDataBlobPromise.Then(delegate(byte[] data)
				{
					roomDataBytes = data;
				}).Error(delegate(string error)
				{
					roomLoadError = error;
				});
				if (!string.IsNullOrEmpty(roomLoadError))
				{
					SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom(roomLoadError, SessionManager.LoadSceneSources.PERSISTENCE_ERROR);
					yield break;
				}
				try
				{
					PersistedRoomData persistedRoomData = PersistedRoomData.Parser.ParseFrom(roomDataBytes);
					roomDataShapeContainers = BuildRoomDataShapeContainerMap(persistedRoomData);
					roomDataVersion = (RoomPersistenceVersion)persistedRoomData.Version;
				}
				catch (InvalidProtocolBufferException exception)
				{
					UnityEngine.Debug.LogException(exception);
					SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom("Room data is corrupt.", SessionManager.LoadSceneSources.PERSISTENCE_ERROR);
					yield break;
				}
			}
			foreach (ShapeContainerDataCollection.Types.ShapeContainerDataCollectionEntry shapeContainer2 in shapeContainersData.ShapeContainers)
			{
				PhotonView photonView = PhotonView.Find(shapeContainer2.PhotonViewId);
				if (!(photonView != null))
				{
					continue;
				}
				ShapeContainer component = photonView.GetComponent<ShapeContainer>();
				if (!(component != null))
				{
					continue;
				}
				if (shapeContainer2.Unchanged)
				{
					if (component.PersistenceView != null)
					{
						if (!roomDataShapeContainers.TryGetValue(component.PersistenceView.Id, out var value))
						{
							UnityEngine.Debug.LogError("No shape container data available for unchanged shape container!");
							SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom("Failed to load room data.", SessionManager.LoadSceneSources.PERSISTENCE_ERROR);
							break;
						}
						component.LocalAddShapesFromRoomData(roomDataVersion, value);
					}
					else
					{
						UnityEngine.Debug.LogError($"Received ShapeContainerData marked as unchanged for {component.DebugName}, but it does not contain a PersistenceView.");
					}
				}
				else
				{
					component.LocalAddShapesFromData(shapeContainer2.Shapes);
				}
			}
		}

		private Dictionary<Guid, PersistenceViewData> BuildRoomDataShapeContainerMap(PersistedRoomData roomData)
		{
			Dictionary<Guid, PersistenceViewData> dictionary = new Dictionary<Guid, PersistenceViewData>();
			BuildRoomDataShapeContainerMap(roomData.PersistenceViews, dictionary);
			return dictionary;
		}

		private void BuildRoomDataShapeContainerMap(IEnumerable<PersistenceViewData> persistenceViews, Dictionary<Guid, PersistenceViewData> map)
		{
			if (persistenceViews == null || map == null)
			{
				return;
			}
			foreach (PersistenceViewData persistenceView in persistenceViews)
			{
				if (persistenceView.ShapeContainerData != null)
				{
					map.Add(RecRoom.Protobuf.ByteStringExtensions.ToGuid(persistenceView.Id), persistenceView);
				}
				BuildRoomDataShapeContainerMap(persistenceView.ChildViews.Select((ChildPersistenceViewData cv) => cv.Data), map);
			}
		}

		private void OnRoomDeserializationComplete()
		{
			if (PhotonNetwork.otherPlayers.Length > 0)
			{
				ShapeContainerDataCollection shapeContainerDataCollection = SerializeAuthorityShapeContainers();
				if (shapeContainerDataCollection.ShapeContainers.Count > 0)
				{
					base.photonView.RpcOthers(RpcDeserializeShapeContainers, shapeContainerDataCollection);
				}
			}
		}

		private void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
		{
			ShapeContainerDataCollection shapeContainerDataCollection = SerializeAuthorityShapeContainers();
			if (shapeContainerDataCollection.ShapeContainers.Count > 0)
			{
				base.photonView.RpcPlayer(newPlayer, RpcDeserializeShapeContainers, shapeContainerDataCollection);
			}
		}

		[PunRPC]
		private void RpcDeserializeShapeContainers(ShapeContainerDataCollection shapeContainerDataCollection)
		{
			StopAllCoroutines();
			SetPhotonNetworkPaused(paused: false);
			StartCoroutine(RemoteDeserializeShapeContainers(shapeContainerDataCollection));
		}
	}
