	public class StandaloneShapeContainer : ShapeContainer
	{
		public const int MAX_RESOURCES_IN_SINGLE_SHAPE_CONTAINER = 2500;

		private static Transform _shapeContainerRoot;

		protected static Transform ShapeContainerRoot
		{
			get
			{
				if (_shapeContainerRoot == null)
				{
					GameObject gameObject = new GameObject("Shape Container Root");
					gameObject.transform.SetParent(null, worldPositionStays: false);
					_shapeContainerRoot = gameObject.transform;
				}
				return _shapeContainerRoot;
			}
		}

		public override string DebugName => $"Shape Container {base.PersistenceView.Id}";

		public override string FriendlyName => base.CreationObject.UserFriendlyName;

		public override int MaxResources => 2500;

		public override bool DestroyIfEmpty => true;

		public override bool CanBeMerged => true;

		public override bool CanBeSplit => true;

		public override bool CanBeEditedAfterCreation => true;

		public override PhysicsMode DefaultPhysicsMode => PhysicsMode.Environment;

		protected override RepositionWhenAddingFirstShape ShouldRepositionWhenAddingFirstShape
		{
			[CompilerGenerated]
			get
			{
				return RepositionWhenAddingFirstShape.Once;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			base.transform.SetParent(ShapeContainerRoot, worldPositionStays: true);
		}

		protected override void Start()
		{
			base.Start();
			AddSettingsFunctions();
		}

		private void AddSettingsFunctions()
		{
			Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
			dictionary.Add("Decoration", new EnumChoiceData
			{
				enumValue = 1,
				tooltip = "Intangible and unaffected by gravity"
			});
			dictionary.Add("Environment", new EnumChoiceData
			{
				enumValue = 0,
				tooltip = "Solid but unaffected by gravity"
			});
			dictionary.Add("Physical", new EnumChoiceData
			{
				enumValue = 4,
				tooltip = "Solid and affected by gravity"
			});
			dictionary.Add("Sticky", new EnumChoiceData
			{
				enumValue = 2,
				tooltip = "Solid and affected by gravity\nSticks to other objects"
			});
			Dictionary<string, EnumChoiceData> choicesDictionary = dictionary;
			EnumSettingEditEvent settingEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.PropertyDescription.text = "Physics Mode";
				instance.PropertyGetter = SandboxCurrentPhysicsMode_Get;
				instance.PropertySetter = SandboxCurrentPhysicsMode_Set;
			}, choicesDictionary);
			base.CreationObject.AddConfigurableSetting(settingEvent);
		}

		protected override void OnPostReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			base.OnPostReset(thisTool, resetPosition, resetRotation, oldPosition, wasCleanedUp);
			if (PhotonNetwork.isMasterClient && wasCleanedUp && !base.Tool.ToolCleanup.OverridesActive)
			{
				base.CreationObject.MasterDespawn();
			}
		}

		public void SandboxCurrentPhysicsMode_Set(int newValue)
		{
			if (base.hasAuthority)
			{
				int num = CalculateResourceCost((PhysicsMode)newValue);
				if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordResourceCost(num - base.SandboxResourceCost))
				{
					base.CurrentPhysicsMode = (PhysicsMode)newValue;
					return;
				}
				ScreenSpaceNotificationManager instance = SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance;
				PhysicsMode physicsMode = (PhysicsMode)newValue;
				instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Not enough resources to switch to " + physicsMode.ToString() + " mode", 1.5f);
			}
		}

		public int SandboxCurrentPhysicsMode_Get()
		{
			return (int)base.CurrentPhysicsMode;
		}

		protected override string GetPreferredTag(PhysicsMode physicsMode)
		{
			switch (physicsMode)
			{
			case PhysicsMode.Environment:
				return "MovementCollisionAlwaysAllowed";
			case PhysicsMode.Decoration:
			case PhysicsMode.Physical_Sticky:
			case PhysicsMode.Physical:
				return "Untagged";
			default:
				throw new ArgumentException("physicsMode");
			}
		}
	}
}
public class StopVisual : UnityEngine.MonoBehaviour
{
	private List<IgnoreableRenderer> trackedRenderers;

	private void Awake()
	{
		trackedRenderers = new List<IgnoreableRenderer>();
	}

	private void Start()
	{
		AddValidRenderersFromGameObject(base.gameObject);
	}

	private void AddValidRenderersFromGameObject(GameObject go)
	{
		Renderer[] componentsInChildren = go.GetComponentsInChildren<Renderer>(includeInactive: true);
		if (componentsInChildren == null)
		{
			return;
		}
		Renderer[] array = componentsInChildren;
		foreach (Renderer renderer in array)
		{
			if (renderer is ParticleSystemRenderer || renderer is LineRenderer)
			{
				continue;
			}
			bool flag = false;
			for (int j = 0; j < trackedRenderers.Count; j++)
			{
				if (trackedRenderers[j].Renderer == renderer)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				trackedRenderers.Add(new IgnoreableRenderer
				{
					Renderer = renderer,
					SubmeshCount = renderer.GetSubmeshCount()
				});
			}
		}
	}

	public void UpdateIgnoreVisual(bool shouldIgnore)
	{
		foreach (IgnoreableRenderer trackedRenderer in trackedRenderers)
		{
			if (shouldIgnore)
			{
				trackedRenderer.RenderAsIgnored(this, Player.LocalPlayer, null);
			}
		}
	}
}
public class GiftBoxMerchVisual : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct GiftRarityVisual
	{
		public string name;

		public GiftManager.GiftRarity rarity;

		public Material material;
	}

	[SerializeField]
	private MeshRenderer meshRenderer;

	[SerializeField]
	private List<GiftRarityVisual> giftRarityVisuals;

	[SerializeField]
	private Material tokenMaterial;

	public bool SetGiftDrop(StorefrontGiftDrop storefrontGiftDrop)
	{
		if (storefrontGiftDrop.Context == GiftManager.GiftContext.Token)
		{
			meshRenderer.material = tokenMaterial;
			return true;
		}
		return SetRarity(storefrontGiftDrop.Rarity);
	}

	private bool SetRarity(GiftManager.GiftRarity rarity)
	{
		foreach (GiftRarityVisual giftRarityVisual in giftRarityVisuals)
		{
			if (giftRarityVisual.rarity == rarity)
			{
				meshRenderer.material = giftRarityVisual.material;
				return true;
			}
		}
		UnityEngine.Debug.LogError("Could not find a visual setup for rarity : " + rarity, base.gameObject);
		return false;
	}
}
