				SetPlayerBalanceText((!string.IsNullOrEmpty(error)) ? 0 : balance);
			});
			yield return RecNet.Storefronts.GetStorefront(storefrontType).Then(delegate(GiftDropStorefront store)
			{
				giftDropStorefront = store;
			});
			if (giftDropStorefront == null)
			{
				yield break;
			}
			if (itemSetSlots == null || itemSetSlots.Length == 0)
			{
				PopulateItemSlots(giftDropStorefront.StoreItems);
			}
			else
			{
				ClearItemSlots();
				StorefrontItemSetSlot[] array = itemSetSlots;
				foreach (StorefrontItemSetSlot storefrontItemSetSlot in array)
				{
					storefrontItemSetSlot.SetStorefrontItems(giftDropStorefront.StoreItems);
				}
			}
			if (endDateText != null)
			{
				endDateText.text = string.Format(endDateTemplate, FormatDateTime(giftDropStorefront.NextUpdate));
			}
		}

		private void OnDestroy()
		{
			RecNet.Storefronts.OnLocalPlayerBalanceUpdated -= LocalPlayerBalanceUpdated;
		}

		private void Update()
		{
			UpdateCreditAnimation();
			UpdatePlayerInRange();
			UpdatePlayerInteraction();
		}

		public void PopulateItemSlots(List<PurchasableGiftDrop> purchasableGiftDrops)
		{
			for (int i = 0; i < purchasableGiftDrops.Count; i++)
			{
				if (i < itemSlots.Length)
				{
					StorefrontGiftDrop storefrontGiftDrop = purchasableGiftDrops[i].GiftDrops[0];
					StorefrontItemSlot itemSlot = itemSlots[i];
					AssignStoreItemToSlot(storefrontGiftDrop, purchasableGiftDrops[i].GetCost(currencyType), purchasableGiftDrops[i].PurchasableItemId, itemSlot);
				}
			}
		}

		public void ClearItemSlots()
		{
			StorefrontItemSlot[] array = itemSlots;
			foreach (StorefrontItemSlot storefrontItemSlot in array)
			{
				storefrontItemSlot.ClearSlot();
			}
		}

		protected void AssignStoreItemToSlot(StorefrontGiftDrop storefrontGiftDrop, int cost, int purchasableItemId, StorefrontItemSlot itemSlot)
		{
			itemSlot.gameObject.SetActive(value: true);
			itemSlot.SetUpSlot(cost, purchasableItemId, storefrontGiftDrop);
			GameObject gameObject = null;
			if (storefrontGiftDrop.IsQuery)
			{
				GiftBoxMerchVisual giftBoxMerchVisual = UnityEngine.Object.Instantiate(giftBoxMerchVisualPrefab);
				giftBoxMerchVisual.SetGiftDrop(storefrontGiftDrop);
				gameObject = giftBoxMerchVisual.gameObject;
			}
			else
			{
				OutfitSelection outfitSelection = OutfitSelection.Parse(storefrontGiftDrop.AvatarItemDesc);
				if (outfitSelection != null)
				{
					gameObject = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitImposter(outfitSelection);
				}
				else if (!string.IsNullOrEmpty(storefrontGiftDrop.EquipmentPrefabName))
				{
					gameObject = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentImposter(storefrontGiftDrop.EquipmentPrefabName, storefrontGiftDrop.EquipmentModificationGuid);
				}
				else if (!string.IsNullOrEmpty(storefrontGiftDrop.ConsumableItemDesc))
				{
					gameObject = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.SpawnConsumableImposter(storefrontGiftDrop.ConsumableItemDesc);
				}
			}
			if (gameObject != null)
			{
				gameObject.transform.position = itemSlot.transform.position;
				gameObject.transform.rotation = itemSlot.transform.rotation;
				itemSlot.ItemTransform = gameObject.transform;
			}
		}

		private void SelectBoxSpawnPoint(out Vector3 boxPosition, out Quaternion boxRotation)
		{
			boxPosition = Player.LocalPlayer.CurrentFloorPosition + Player.LocalPlayer.TrackingSpace.transform.forward * 0.6f;
			boxRotation = Quaternion.LookRotation(boxPosition - Player.LocalPlayer.CurrentFloorPosition);
			if (boxSpawnPoints.Length <= 0)
			{
				return;
			}
			Transform transform = boxSpawnPoints[0];
			float num = float.MaxValue;
			for (int i = 0; i < boxSpawnPoints.Length; i++)
			{
				float sqrMagnitude = (Player.LocalPlayer.CurrentFloorPosition - boxSpawnPoints[i].position).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					transform = boxSpawnPoints[i];
				}
			}
			boxPosition = transform.position;
			boxRotation = transform.rotation;
		}

		private Vector3 SelectPopupPoint()
		{
			Vector3 zero = Vector3.zero;
			if (popupRoots.Length > 0)
			{
				Transform transform = popupRoots[0];
				float num = float.MaxValue;
				for (int i = 0; i < popupRoots.Length; i++)
				{
					float sqrMagnitude = (Player.LocalPlayer.CurrentFloorPosition - popupRoots[i].position).sqrMagnitude;
					if (sqrMagnitude < num)
					{
						num = sqrMagnitude;
						transform = popupRoots[i];
					}
				}
				return transform.position;
			}
			return Vector3.zero;
		}

		private void UpdateCreditAnimation()
		{
			float num = Mathf.InverseLerp(creditAnimationStartTime, creditAnimationEndTime, UnityEngine.Time.time);
			int num2 = Mathf.RoundToInt(Mathf.Lerp(previousLocalPlayerCredits, localPlayerCredits, num));
			if (num2 != creditAnimationLatestIntValue)
			{
				creditAnimationLatestIntValue = num2;
				SetPlayerBalanceText(creditAnimationLatestIntValue);
			}
			if (num >= 1f)
			{
				currentlyAnimating = false;
			}
		}

		private void UpdatePlayerInteraction()
		{
			if (interactionVolume != null && Player.LocalPlayerExists && interactionVolume.bounds.Contains(Player.LocalPlayer.Body.transform.position))
			{
				AnalyticsHelper.AccumulateTime("Storefront_RecCenter", UnityEngine.Time.unscaledDeltaTime);
			}
		}

		private void UpdatePlayerInRange()
		{
			bool flag = true;
			if (TestForPlayerRange && storefrontActivationVolumes.Length > 0 && Player.LocalPlayerExists && purchaseCoroutine == null)
			{
				BoxCollider[] array = storefrontActivationVolumes;
				foreach (BoxCollider boxCollider in array)
				{
					flag = boxCollider.bounds.Contains(Player.LocalPlayer.Body.transform.position);
					if (flag)
					{
						break;
					}
				}
			}
			if (playerInRangeOfStore != flag)
			{
				FastGraphicRaycaster[] array2 = raycasters;
				foreach (FastGraphicRaycaster fastGraphicRaycaster in array2)
				{
					fastGraphicRaycaster.enabled = flag;
				}
				StorefrontItemSlot[] array3 = itemSlots;
				foreach (StorefrontItemSlot storefrontItemSlot in array3)
				{
					storefrontItemSlot.Active = flag;
				}
				StorefrontItemSetSlot[] array4 = itemSetSlots;
				foreach (StorefrontItemSetSlot storefrontItemSetSlot in array4)
				{
					storefrontItemSetSlot.Active = flag;
				}
			}
			playerInRangeOfStore = flag;
			if (playerInRangeOfStore.HasValue && !playerInRangeOfStore.Value)
			{
				if (confirmationDialog.IsActive)
				{
					confirmationDialog.Cancel(closeDialog: true);
				}
				if (activeSlotsDialog != null && activeSlotsDialog.IsActive)
				{
					activeSlotsDialog.Cancel(closeDialog: true);
				}
			}
		}

		private void LocalPlayerBalanceUpdated(CurrencyType type, long balance)
		{
			if (type == currencyType)
			{
				SetPlayerBalanceText(balance);
			}
		}

		private void SetPlayerBalanceText(long balance)
		{
			UIHelper.SafeSetText(currentBalanceText, string.Concat(Profiles.LocalProfile.DisplayName, " : ", SingletonMonoBehaviour<CurrencyManager>.Instance.ToCurrencyString(balance, currencyType)));
		}

		public void PurchaseItem(StorefrontItemSlot slot)
		{
			PlayerHasMadePurchase = false;
			if (purchaseInProgress)
			{
				return;
			}
			if (slot.AlreadyPurchased)
			{
				ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_ONLY, "You already own this item!", "OK");
				return;
			}
			long? initialBalance = RecNet.Storefronts.GetBalance(currencyType);
			if (initialBalance.HasValue && initialBalance.Value < slot.Cost)
			{
				string pluralCurrencyName = SingletonMonoBehaviour<CurrencyManager>.Instance.GetPluralCurrencyName(currencyType);
				ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_ONLY, $"You don't have enough {pluralCurrencyName}!", "OK");
				return;
			}
			if ((int)Profiles.LocalProfile.Level < slot.Item.Level)
			{
				ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_ONLY, $"You need to be at least leve {Profiles.LocalProfile.Level} to purchase this item!", "OK");
				return;
			}
			purchaseInProgress = true;
			string questionText = $"Are you sure you want to purchase this item for {SingletonMonoBehaviour<CurrencyManager>.Instance.ToCurrencyString(slot.Cost, currencyType)}?";
			StorefrontConfirmationDialog.IDialogPromise dialogPromise = ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_NO, questionText);
			Avatars.GiftPackage giftPackage;
			dialogPromise.OnPlayerResponse = (Action<int>)Delegate.Combine(dialogPromise.OnPlayerResponse, (Action<int>)delegate(int dialogResponse)
			{
				if (dialogResponse == 1)
				{
					PlayerHasMadePurchase = true;
					SelectBoxSpawnPoint(out var giftPosition, out var giftRotation);
					Vector3 vector = SelectPopupPoint();
					if (vector != Vector3.zero)
					{
						statusPopup.transform.position = vector;
					}
					statusPopup.gameObject.SetActive(value: true);
					StorefrontGiftDrop slotItem = slot.Item;
					RecNet.Storefronts.PurchaseItem(storefrontType, currencyType, slot.PurchasableItemId, delegate(string error, RecNet.Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage> response)
					{
						statusPopup.gameObject.SetActive(value: false);
						if (string.IsNullOrEmpty(error) && response.BalanceUpdates.Count == 1 && response.BalanceUpdates[0].UpdateResponse == RecNet.Storefronts.UpdateResponseTypes.OK)
						{
							giftPackage = response.BalanceUpdates[0].Data[0];
							if (!giftPackage.IsValid)
							{
								UnityEngine.Debug.LogError(giftPackage.ErrorMessage);
							}
							else if (Avatars.GiftPackages.Contains(giftPackage))
							{
								UnityEngine.Debug.LogWarning("Bought duplicate gift!");
							}
							else if (giftPackage == null)
							{
								UnityEngine.Debug.LogError("Null gift package!");
							}
							else if (giftPackage.SupportsCurrentPlatform)
							{
								if (purchasedItemAudioClip != null && purchasedItemAudioClip.audioClip != null)
								{
									AudioManager.Play3DSFX(purchasedItemAudioClip, slot.transform.position);
								}
								if (Player.LocalPlayerExists)
								{
									if (string.IsNullOrEmpty(slotItem.AvatarItemDesc))
									{
										Player.LocalPlayer.PlayerEvents.PurchasedNonClothingItem();
									}
									else
									{
										Player.LocalPlayer.PlayerEvents.PurchasedClothingItem();
									}
								}
								AnalyticsHelper.PurchasedItem(storefrontType, AnalyticsHelper.PurchaseLocation.Booth, initialBalance, response.Balance, slotItem, slot.Cost);
								Avatars.GiftPackages.Add(giftPackage);
								purchaseCoroutine = StartCoroutine(WaitAndDequeue(slot, response.Balance, slot.Cost, giftPackage, giftPosition, giftRotation));
							}
						}
						else
						{
							purchaseInProgress = false;
							if (response.BalanceUpdates[0].UpdateResponse == RecNet.Storefronts.UpdateResponseTypes.NoItemAvailable)
							{
								ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_ONLY, "No new items available. Please try again later :(", "OK");
							}
							else
							{
								ShowPopupDialog(confirmationDialog, StorefrontConfirmationDialog.DialogType.YES_ONLY, "Error purchasing item. Please try again later :(", "OK");
							}
							if (response != null)
							{
								string text = ((response.BalanceUpdates.Count <= 0) ? string.Empty : response.BalanceUpdates.Select((RecNet.Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage>.BalanceUpdateDTO r) => ((int)r.UpdateResponse/*cast due to .constrained prefix*/).ToString()).Aggregate((string s, string s1) => s + "," + s1));
								UnityEngine.Debug.LogError(("Responses:" + response == null) ? (string.Empty + "\n" + error) : text);
							}
							else
							{
								UnityEngine.Debug.LogError("Received null response from Storefront!");
							}
						}
					});
				}
				else
				{
					purchaseInProgress = false;
				}
			});
		}

		public void SetItemSetActive(StorefrontItemSetSlot setSlot)
		{
			if (!activeSlotsDialog.IsActive)
			{
				StorefrontConfirmationDialog.IDialogPromise dialogPromise = ShowPopupDialog(activeSlotsDialog, StorefrontConfirmationDialog.DialogType.NO_ONLY, string.Empty, string.Empty, "X");
				PopulateItemSlots(setSlot.PurchasableGiftDrops);
				dialogPromise.OnPlayerResponse = (Action<int>)Delegate.Combine(dialogPromise.OnPlayerResponse, (Action<int>)delegate
				{
					ClearItemSlots();
				});
			}
		}

		private IEnumerator WaitAndDequeue(StorefrontItemSlot slot, long newBalance, int itemCost, Avatars.GiftPackage giftPackage, Vector3 giftPosition, Quaternion giftRotation)
		{
			previousLocalPlayerCredits = newBalance + itemCost;
			localPlayerCredits = newBalance;
			int creditDelta = Mathf.Abs(itemCost);
			float animationDuration = Mathf.Clamp((float)creditDelta / creditChangeRate, 0f, 5f);
			creditAnimationStartTime = UnityEngine.Time.time + creditChangeAnimationDelay;
			creditAnimationEndTime = creditAnimationStartTime + animationDuration;
			Vector3 animateTo = ((!(creditSlot != null)) ? slot.transform.position : creditSlot.position);
			int storeCreditAwardDenomination = Mathf.CeilToInt((float)itemCost / 100f);
			if (boxGiftContextOverride != GiftManager.GiftContext.None)
			{
				giftPackage.SetGiftContext(boxGiftContextOverride);
			}
			Collectible.SpawnCollectibleGroup(collectiblePrefab, creditDelta, storeCreditAwardDenomination, Player.LocalPlayer.Body.transform.position, animateTo, animationDuration);
			currentlyAnimating = true;
			yield return new WaitUntil(() => !currentlyAnimating);
			slot.UpdateUIText();
			yield return SingletonMonoBehaviour<GiftManager>.Instance.DequeueGift(giftPackage, giftPosition, giftRotation, (Avatars.GiftPackage variant) => variant.PackageVariant.dequeueBehavior == GiftPackageVariant.DequeueBehaviors.ConsumeImmediately, 4.4f, delegate
			{
				purchaseInProgress = false;
				PlayerHasMadePurchase = false;
			});
			purchaseCoroutine = null;
		}

		private StorefrontConfirmationDialog.IDialogPromise ShowPopupDialog(StorefrontConfirmationDialog dialog, StorefrontConfirmationDialog.DialogType dialogType, string questionText, string affirmativeText = "Yes", string negativeText = "No")
		{
			Vector3 vector = SelectPopupPoint();
			if (vector != Vector3.zero)
			{
				dialog.transform.position = vector;
			}
			return dialog.ShowDialog(dialogType, questionText, affirmativeText, negativeText);
		}

		private string FormatDateTime(DateTime utcTime)
		{
			TimeSpan timeSpan = utcTime - DateTime.UtcNow;
			if (timeSpan.Ticks < 0)
			{
				return "time has passed!";
			}
			if (timeSpan.TotalDays >= 1.0)
			{
				int num = (int)timeSpan.TotalDays;
				return string.Format("{0} Day{1}", num, (num <= 1) ? string.Empty : "s");
			}
			if (timeSpan.TotalHours > 0.0)
			{
				int num2 = (int)timeSpan.TotalHours;
				return string.Format("{0} Hour{1}", num2, (num2 <= 1) ? string.Empty : "s");
			}
			return "< 1 Hour";
		}

		public void Refresh()
		{
			StartCoroutine(Start());
		}

		public void AddCash()
		{
			StartCoroutine(_AddCash());
		}

		private IEnumerator _AddCash()
		{
			yield break;
		}
	}
	public class StorefrontConfirmationDialog : UnityEngine.MonoBehaviour
	{
		[Flags]
		public enum DialogType
		{
			YES_NO = 3,
			YES_ONLY = 1,
			NO_ONLY = 2
		}

		public interface IDialogPromise
		{
			bool Done { get; }

			int Response { get; }

			Action<int> OnPlayerResponse { get; set; }

			void Respond(int response);
		}

		private sealed class DialogPromise : IDialogPromise
		{
			public bool Done { get; private set; }

			public int Response { get; private set; }

			public Action<int> OnPlayerResponse { get; set; }

			public void Respond(int response)
			{
				Response = response;
				Done = true;
				if (OnPlayerResponse != null)
				{
					OnPlayerResponse(Response);
				}
			}
		}

		private const int YES = 1;

		private const int NO = 2;

		[SerializeField]
		private Text questionText;

		[SerializeField]
		private Text yesText;

		[SerializeField]
		private UnityEngine.UI.Button yesButton;

		[SerializeField]
		private Text noText;

		[SerializeField]
		private UnityEngine.UI.Button noButton;

		[SerializeField]
		private RecRoomAudioClip popupAudio;

		[SerializeField]
		private RecRoomAudioClip buttonAudio;

		public bool IsActive => base.gameObject.activeSelf;

		protected IDialogPromise CurrentPromise { get; private set; }

		protected IDialogPromise CreatePromise()
		{
			if (CurrentPromise != null && !CurrentPromise.Done)
			{
				Cancel(closeDialog: true);
			}
			CurrentPromise = new DialogPromise();
			base.gameObject.SetActive(value: true);
			if (popupAudio != null && popupAudio.audioClip != null)
			{
				AudioManager.Play3DSFX(popupAudio, base.transform);
			}
			return CurrentPromise;
		}

		[SkipRename]
		public void Button_Affirmative()
		{
			Respond(1, shouldClose: true);
		}

		[SkipRename]
		public void Button_Negative()
		{
			Respond(2, shouldClose: true);
		}

		public virtual void Cancel(bool closeDialog)
		{
			Respond(0, closeDialog);
		}

		protected void Respond(int response, bool shouldClose)
		{
			if (shouldClose)
			{
				base.gameObject.SetActive(value: false);
			}
			if (buttonAudio != null && buttonAudio.audioClip != null)
			{
				AudioManager.Play3DSFX(buttonAudio, base.transform);
			}
			CurrentPromise.Respond(response);
		}

		public IDialogPromise ShowDialog(DialogType dialogType, string questionText, string affirmativeText = "Yes", string negativeText = "No")
		{
			UIHelper.SafeSetText(this.questionText, questionText);
			UIHelper.SafeSetText(yesText, affirmativeText);
			UIHelper.SafeSetText(noText, negativeText);
			if (yesButton != null)
			{
				yesButton.gameObject.SetActive((dialogType & DialogType.YES_ONLY) != 0);
			}
			if (noButton != null)
			{
				noButton.gameObject.SetActive((dialogType & DialogType.NO_ONLY) != 0);
			}
			return CreatePromise();
		}
	}
	public class StorefrontInteractionSlot : UnityEngine.MonoBehaviour, IPointerEnterHandler, IPointerExitHandler, IEventSystemHandler
	{
		[Header("Interaction")]
		[SerializeField]
		private UnityEngine.UI.Button button;

		[Header("Hovering")]
		[SerializeField]
		private float hoveredItemRotationSpeed = 45f;

		[SerializeField]
		private float hoveredItemRotateBackSpeed = 360f;

		[SerializeField]
		private Transform hoveredTransform;

		[SerializeField]
		private float hoveredItemSlerpSpeed = 5f;

		protected Storefront storefront;

		private bool itemHovered;

		private float slerpAnimationTime;

		private Quaternion initialRotation = Quaternion.identity;

		private Vector3 initialPosition = Vector3.zero;

		private Transform _itemTransform;

		private bool _active = true;

		public Transform ItemTransform
		{
			get
			{
				return _itemTransform;
			}
			set
			{
				initialPosition = value.position;
				initialRotation = value.rotation;
				_itemTransform = value;
			}
		}

		public bool Active
		{
			get
			{
				return _active;
			}
			set
			{
				if (_active != value)
				{
					_active = value;
					button.enabled = value;
					UpdateUIText();
				}
			}
		}

		private void Update()
		{
			if (ItemTransform != null)
			{
				if (itemHovered)
				{
					ItemTransform.Rotate(Vector3.up, hoveredItemRotationSpeed * UnityEngine.Time.deltaTime);
					Vector3 position = Vector3.Slerp(initialPosition, hoveredTransform.position, slerpAnimationTime);
					ItemTransform.position = position;
					slerpAnimationTime += UnityEngine.Time.deltaTime * hoveredItemSlerpSpeed;
				}
				else
				{
					Quaternion rotation = Quaternion.RotateTowards(ItemTransform.rotation, initialRotation, hoveredItemRotateBackSpeed * UnityEngine.Time.deltaTime);
					ItemTransform.rotation = rotation;
					Vector3 position2 = Vector3.Slerp(hoveredTransform.position, initialPosition, slerpAnimationTime);
					ItemTransform.position = position2;
					slerpAnimationTime += UnityEngine.Time.deltaTime * hoveredItemSlerpSpeed;
				}
			}
		}

		public void Initialize(Storefront storefront)
		{
			this.storefront = storefront;
		}

		public virtual void UpdateUIText()
		{
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			itemHovered = true;
			slerpAnimationTime = 0f;
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			itemHovered = false;
			slerpAnimationTime = 0f;
		}
	}
	public class StorefrontItemSetSlot : StorefrontInteractionSlot
	{
		[Serializable]
		private struct AvatarItemSelection
		{
			public string desc;

			public string avatarItemDesc;
		}

		[Header("Item Display")]
		[SerializeField]
		private bool isConsumableSet;

		[SerializeField]
		private List<AvatarItemSelection> avatarItemSelections;

		[SerializeField]
		private Transform previewTransform;

		private List<string> avatarItemDescs = new List<string>();

		public List<PurchasableGiftDrop> PurchasableGiftDrops { get; private set; }

		private void Awake()
		{
			PurchasableGiftDrops = new List<PurchasableGiftDrop>();
			foreach (AvatarItemSelection avatarItemSelection in avatarItemSelections)
			{
				if (avatarItemSelection.avatarItemDesc != null)
				{
					avatarItemDescs.Add(avatarItemSelection.avatarItemDesc.Trim());
				}
			}
		}

		public void SetStorefrontItems(List<PurchasableGiftDrop> purchasableGiftDrops)
		{
			if (!base.gameObject.activeInHierarchy)
			{
				return;
			}
			foreach (PurchasableGiftDrop purchasableGiftDrop in purchasableGiftDrops)
			{
				StorefrontGiftDrop storefrontGiftDrop = purchasableGiftDrop.GiftDrops[0];
				if (storefrontGiftDrop != null && ((storefrontGiftDrop.Content == GiftManager.GiftBoxContents.Avatar && avatarItemDescs.Contains(storefrontGiftDrop.AvatarItemDesc)) || (isConsumableSet && storefrontGiftDrop.Content == GiftManager.GiftBoxContents.Consumable)))
				{
					PurchasableGiftDrops.Add(purchasableGiftDrop);
				}
			}
			if (PurchasableGiftDrops.Count > 0)
			{
				base.ItemTransform = previewTransform;
			}
		}

		[SkipRename]
		public void Button_SelectSet()
		{
			if (PurchasableGiftDrops != null && PurchasableGiftDrops.Count > 0)
			{
				storefront.SetItemSetActive(this);
			}
		}
	}
	public class StorefrontItemSlot : StorefrontInteractionSlot
	{
		[Header("Item Display")]
		[SerializeField]
		[AutofillOptional(AutofillType.SelfAndChildren, false)]
		private Tooltip tooltip;

		[SerializeField]
		private Text priceText;

		[SerializeField]
		private string defaultPriceText = "Out of Stock";

		[SerializeField]
		private Text countText;

		[SerializeField]
		private Text nameText;

		[SerializeField]
		private Color inactiveTextColor = Color.gray;

		private Color activePriceTextColor;

		private Color activeNameTextColor;

		private OutfitSelection selection;

		private string cachedCount = string.Empty;

		public int PurchasableItemId { get; private set; }

		public int Cost { get; private set; }

		public StorefrontGiftDrop Item { get; private set; }

		public bool AlreadyPurchased
		{
			get
			{
				if (Item != null)
				{
					if (Item.Content == GiftManager.GiftBoxContents.Avatar)
					{
						return NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.IsOutfitUnlockedOnCurrentPlatform(selection);
					}
					if (Item.Content == GiftManager.GiftBoxContents.Equipment)
					{
						return NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.IsEquipmentUnlockedOnCurrentPlatform(Item.EquipmentModificationGuid);
					}
				}
				return false;
			}
		}

		private string Count
		{
			get
			{
				return cachedCount;
			}
			set
			{
				cachedCount = value;
			}
		}

		private void Awake()
		{
			activePriceTextColor = priceText.IfNotNull((Text text) => text.color, Color.white);
			activeNameTextColor = nameText.IfNotNull((Text text) => text.color, Color.white);
			UpdateUIText();
			NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitSelectionUnlocked += OutfitSelectionUnlocked;
			if (tooltip != null)
			{
				tooltip.enabled = false;
			}
		}

		private void OnDestroy()
		{
			if (NetworkedSingletonMonoBehaviour<OutfitManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.OutfitSelectionUnlocked -= OutfitSelectionUnlocked;
			}
		}

		public void SetUpSlot(int cost, int id, StorefrontGiftDrop storefrontGiftDrop)
		{
			Cost = cost;
			PurchasableItemId = id;
			Item = storefrontGiftDrop;
			if (Item != null && Item.Content == GiftManager.GiftBoxContents.Avatar)
			{
				selection = OutfitSelection.Parse(Item.AvatarItemDesc);
			}
			else
			{
				selection = null;
			}
			GetConsumableCount();
			if (tooltip != null && Item != null && !string.IsNullOrEmpty(Item.Tooltip))
			{
				tooltip.enabled = true;
				tooltip.Message = Item.Tooltip;
			}
			UpdateUIText();
		}

		public void ClearSlot()
		{
			Cost = 0;
			PurchasableItemId = 0;
			Item = null;
			if (base.ItemTransform != null)
			{
				UnityEngine.Object.Destroy(base.ItemTransform.gameObject);
			}
			base.gameObject.SetActive(value: false);
		}

		private void OutfitSelectionUnlocked(OutfitSelection unlockedSelection)
		{
			if (unlockedSelection == selection)
			{
				UpdateUIText();
			}
		}

		private void GetConsumableCount()
		{
			if (Item != null && Item.Content == GiftManager.GiftBoxContents.Consumable)
			{
				ConsumableItem consumablePrefab = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(Item.ConsumableItemDesc);
				if (consumablePrefab != null)
				{
					Count = "x" + ((consumablePrefab.LimitType != ConsumableManager.LimitType.Usage) ? "1" : consumablePrefab.LimitCount.ToString());
				}
			}
			else
			{
				Count = string.Empty;
			}
		}

		[SkipRename]
		public void Button_BuyItem()
		{
			if (Item != null)
			{
				storefront.PurchaseItem(this);
			}
		}

		public override void UpdateUIText()
		{
			base.UpdateUIText();
			if (Item != null)
			{
				if (AlreadyPurchased)
				{
					UIHelper.SafeSetText(priceText, "Already Purchased");
				}
				else if (Item.Level > (int)Profiles.LocalProfile.Level)
				{
					UIHelper.SafeSetText(priceText, $"Unlocks at lv {Item.Level}");
				}
				else
				{
					UIHelper.SafeSetText(priceText, SingletonMonoBehaviour<CurrencyManager>.Instance.ToCurrencyString(Cost, storefront.CurrencyType));
				}
				UIHelper.SafeSetText(nameText, Item.FriendlyName);
				UIHelper.SafeSetText(countText, Count);
			}
			else
			{
				UIHelper.SafeSetText(priceText, defaultPriceText);
				UIHelper.SafeSetText(nameText, string.Empty);
				UIHelper.SafeSetText(countText, string.Empty);
			}
			UIHelper.SafeSetColor(priceText, (!base.Active) ? inactiveTextColor : activePriceTextColor);
			UIHelper.SafeSetColor(countText, (!base.Active) ? inactiveTextColor : activeNameTextColor);
			UIHelper.SafeSetColor(nameText, (!base.Active) ? inactiveTextColor : activeNameTextColor);
		}
	}
	public class StorefrontStatusPopup : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private int maxEllipsesCount = 3;

		[SerializeField]
		private Text statusText;

		[SerializeField]
		private RectTransform statusDisplay;

		[SerializeField]
		private float waitForDisplay = 0.75f;

		[SerializeField]
		private string prefix = "Purchasing";

		private float ellipsesTime;

		private float totalTime;

		private int ellipsesCount;

		private void Awake()
		{
			SetStatusText();
		}

		private void OnEnable()
		{
			statusDisplay.gameObject.SetActive(value: false);
			totalTime = 0f;
			ellipsesTime = 0f;
		}

		private void Update()
		{
			if (totalTime < waitForDisplay)
			{
				totalTime += UnityEngine.Time.deltaTime;
				return;
			}
			if (!statusDisplay.gameObject.activeSelf)
			{
				statusDisplay.gameObject.SetActive(value: true);
			}
			if (ellipsesTime > 0.75f)
			{
				ellipsesTime = 0f;
				ellipsesCount = (ellipsesCount + 1) % maxEllipsesCount;
				SetStatusText();
			}
			ellipsesTime += UnityEngine.Time.deltaTime;
		}

		private void SetStatusText()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append(prefix);
			for (int i = 0; i < ellipsesCount + 1; i++)
			{
				stringBuilder.Append(" .");
			}
			UIHelper.SafeSetText(statusText, stringBuilder.ToString());
		}
	}
}
