		}
		private set
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.SavedStreamingMode == StreamingCameraMode.OFF && value == StreamingCameraMode.ON)
			{
				SetupCamera();
			}
			SingletonMonoBehaviour<SettingsManager>.Instance.SavedStreamingMode = value;
			bool flag = SingletonMonoBehaviour<SettingsManager>.Instance.SavedStreamingMode == StreamingCameraMode.ON;
			base.gameObject.SetActive(flag);
			XRSettings.showDeviceView = !flag;
			if (flag)
			{
				renderingCoroutine = StartCoroutine(RunEndOfFrameRender());
			}
			else
			{
				if (renderingCoroutine != null)
				{
					StopCoroutine(renderingCoroutine);
					renderingCoroutine = null;
				}
				CameraTransformToFollow = null;
				AudioListenerMode = AudioListenerModes.Player;
				GreenScreenMode = GreenScreenModes.Off;
			}
			if (localPlayerHUD != null)
			{
				localPlayerHUD.gameObject.SetActive(streamingCamera.enabled);
			}
			if (this.StreamingCameraModeChanged != null)
			{
				this.StreamingCameraModeChanged(SingletonMonoBehaviour<SettingsManager>.Instance.SavedStreamingMode);
