				action = Interlocked.CompareExchange(ref this.m_StreamingCameraModeChanged, (Action<StreamingCameraMode>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<StreamingCameraMode> action = this.m_StreamingCameraModeChanged;
			Action<StreamingCameraMode> action2;
			do
			{
				action2 = action;
