	protected override void Awake()
	{
		base.Awake();
		SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += OnLocalPlayerSpawned;
		SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerDespawned += OnLocalPlayerDespawned;
		GameManager.InitializeLocalPlayerEvent += GameManager_InitializeLocalPlayer;
		GameManager.ResetLocalPlayerEvent += GameManager_ResetLocalPlayer;
		Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerSpawned);
		if (Player.LocalPlayerExists)
		{
			OnLocalPlayerSpawned();
		}
		SceneManager.activeSceneChanged += OnSceneChanged;
		streamingCamera.depthTextureMode = DepthTextureMode.Depth;
		CreateRenderTexture();
		defaultFOV = streamingCamera.fieldOfView;
		defaultCullingMask = streamingCamera.cullingMask;
		firstPersonCullingMask = defaultCullingMask & -257;
		Mode = SingletonMonoBehaviour<SettingsManager>.Instance.SavedStreamingMode;
		streamingCamera.enabled = false;
	}

	protected override void OnDestroy()
	{
		Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerSpawned);
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerEvents.TeleportEvent -= UpdateInterpolatorTargets;
			AudioListenerMode = AudioListenerModes.Player;
			GreenScreenMode = GreenScreenModes.Off;
		}
		if (SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= OnLocalPlayerSpawned;
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerDespawned -= OnLocalPlayerDespawned;
		}
		GameManager.InitializeLocalPlayerEvent -= GameManager_InitializeLocalPlayer;
		GameManager.ResetLocalPlayerEvent -= GameManager_ResetLocalPlayer;
		SceneManager.activeSceneChanged -= OnSceneChanged;
		GameManager_ResetLocalPlayer(localPlayerIsSpectator: false);
	}

	private void LateUpdate()
	{
		if (Mode != StreamingCameraMode.ON)
		{
			return;
		}
		if (CameraTransformToFollow != null && CameraTransformToFollow.IsValid)
		{
			CameraTransformToFollow.GetTransform(out targetPosition, out targetRotation);
			bool flag = (CameraTransformToFollow.IsLocalPlayer && Player.LocalPlayerExists && Player.LocalPlayer.TrackingSpace.RigidbodyEx.hasParent) || CameraTransformToFollow.Type == CameraTransform.CameraType.FirstPerson;
			float? positionSmoothingTimeOverride = CameraTransformToFollow.PositionSmoothingTimeOverride;
			float num = ((!positionSmoothingTimeOverride.HasValue) ? positionSmoothingTime : positionSmoothingTimeOverride.Value);
			if (CameraTransformToFollow.PositionSmoothingTimeMultiplierByDistance != null)
			{
				num *= CameraTransformToFollow.PositionSmoothingTimeMultiplierByDistance.Evaluate(Vector3.Magnitude(base.transform.position - targetPosition));
			}
			if (!flag && num > 0f)
			{
				base.transform.position = Vector3.SmoothDamp(base.transform.position, targetPosition, ref velocity, num);
			}
			else
			{
				base.transform.position = targetPosition;
			}
			if (CameraTransformToFollow.IgnoreCameraRoll)
			{
				Vector3 eulerAngles = targetRotation.eulerAngles;
				eulerAngles.z = 0f;
				targetRotation = Quaternion.Euler(eulerAngles);
			}
			float? rotationSmoothingTimeOverride = CameraTransformToFollow.RotationSmoothingTimeOverride;
			float num2 = ((!rotationSmoothingTimeOverride.HasValue) ? rotationSmoothingTime : rotationSmoothingTimeOverride.Value);
			if (num2 > 0f)
			{
				base.transform.rotation = UnityExtensions.SmoothDamp(base.transform.rotation, targetRotation, ref rotationVelocity, num2);
			}
			else
			{
				base.transform.rotation = targetRotation;
			}
		}
		else if (DefaultCameraTransformToFollow != null && DefaultCameraTransformToFollow.IsValid)
		{
			CameraTransformToFollow = DefaultCameraTransformToFollow;
		}
	}

	private void CreateRenderTexture()
	{
		if (renderTexture != null)
		{
			renderTexture.Release();
			renderTexture = null;
		}
		renderTexture = new RenderTexture(Screen.width, Screen.height, 24);
		renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
		renderTexture.Create();
		streamingCamera.targetTexture = renderTexture;
		if (rawImage != null)
		{
			rawImage.texture = renderTexture;
		}
	}

	private IEnumerator RunEndOfFrameRender()
	{
		while (Mode == StreamingCameraMode.ON)
		{
			if (playerReady && UnityEngine.Time.realtimeSinceStartup - lastRenderTime >= frameDuration)
			{
				UpdateAspectRatio();
				streamingCamera.enabled = true;
				lastRenderTime = UnityEngine.Time.realtimeSinceStartup;
				yield return new WaitForEndOfFrame();
				streamingCamera.enabled = false;
			}
			yield return null;
		}
	}

	private void UpdateAspectRatio()
	{
		int width = Screen.width;
		int height = Screen.height;
		if (screenWidth != width || screenHeight != height)
		{
			screenWidth = width;
			screenHeight = height;
			streamingCamera.ResetAspect();
			CreateRenderTexture();
		}
	}

	protected void GameManager_InitializeLocalPlayer(bool localPlayerIsSpectator, bool localPlayerIsJoinInProgress)
	{
		if (NetworkedSingletonMonoBehaviour<GameRuleManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.HudPrefab != null && localPlayerHUD == null)
		{
			localPlayerHUD = UnityEngine.Object.Instantiate(NetworkedSingletonMonoBehaviour<GameRuleManager>.Instance.HudPrefab);
			localPlayerHUD.Initialize(NetworkedSingletonMonoBehaviour<GameManager>.Instance, PhotonNetwork.player, Layers.TransparentFX, hudRoot);
		}
	}

	protected void GameManager_ResetLocalPlayer(bool localPlayerIsSpectator)
	{
		if (localPlayerHUD != null)
		{
			UnityEngine.Object.Destroy(localPlayerHUD.gameObject);
			localPlayerHUD = null;
		}
	}

	private void OnSceneChanged(Scene previousScene, Scene currentScene)
	{
		listenersSetUp = false;
		sceneSettingsApplied = false;
		GameManager_ResetLocalPlayer(localPlayerIsSpectator: true);
	}

	private void OnLocalPlayerDespawned()
	{
		playerReady = false;
		if (loadingImage != null)
		{
			loadingImage.gameObject.SetActive(value: true);
		}
	}

	private void OnLocalPlayerSpawned()
	{
		SetupCamera();
	}

	private void UpdateInterpolatorTargetsAndSnap()
	{
		UpdateInterpolatorTargets();
		SnapToTarget();
	}

	private void UpdateInterpolatorTargets()
	{
		if (base.enabled)
		{
			Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.forward;
			Vector3 vector = forward;
			vector.y = 0f;
			Vector3 right = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.right;
			right.y = 0f;
			vector.Normalize();
			right.Normalize();
			offset = vector * (0f - backOffset) + right * rightOffset + Vector3.up * upOffset;
			targetPosition = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position + offset;
			targetRotation = Quaternion.LookRotation(forward);
		}
	}

	public void SetCameraTransformToFollow(CameraTransform cameraTransform, InteractionSource source)
	{
		CameraTransformToFollow = cameraTransform;
		AnalyticsHelper.StreamingCamera(Mode, CameraTransformToFollow, FrameRate, source);
	}

	public void SnapToTarget()
	{
		base.transform.position = targetPosition;
		base.transform.rotation = targetRotation;
	}

	private void SetupCamera()
	{
		if (!listenersSetUp && Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerEvents.TeleportEvent += UpdateInterpolatorTargets;
			listenersSetUp = true;
		}
		UpdateInterpolatorTargetsAndSnap();
		if (!sceneSettingsApplied && RecRoomSceneManager.IsInitialized && RecRoomSceneManager.Instance.SceneRenderingSettings != null)
		{
			RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(streamingCamera);
			defaultFarClipPlane = streamingCamera.farClipPlane;
			sceneSettingsApplied = true;
		}
		playerReady = true;
		if (loadingImage != null)
		{
			loadingImage.gameObject.SetActive(value: false);
		}
	}
}
public class CheatManager : SingletonMonoBehaviour<CheatManager>
{
	private bool isValidPlatform = true;

	protected override void Awake()
	{
		base.Awake();
		SceneManager.sceneLoaded += OnSceneLoaded;
	}

	private void Start()
	{
		isValidPlatform = SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Oculus || SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.Steam;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}

	private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
	{
		if (RecRoomSceneManager.IsCurrentSceneAValidActivity)
		{
			if (!SpeedHackDetector.Instance.IsDetectorRunning)
			{
				SpeedHackDetector.StartDetection();
			}
			if (!ObscuredCheatingDetector.Instance.IsDetectorRunning)
			{
				ObscuredCheatingDetector.StartDetection();
			}
			if (isValidPlatform && !RRCheatDetector.Instance.IsDetectorRunning && GameSessions.LocalGameSession.Location != RoomSceneLocations.DORM_ROOM)
			{
				RRCheatDetector.StartDetection();
			}
		}
	}

	public void OnTimeCheatDetected()
	{
		AnalyticsHelper.UnityTimeCheat();
		HandleCheater();
	}

	public void OnObscuredTypeCheatDetected()
	{
		AnalyticsHelper.ObscuredTypeCheat();
		HandleCheater();
	}

	public void OnHeightCheatDetected()
	{
		AnalyticsHelper.HeightChangeCheat();
	}

	public void OnAdvancedMovementCheatDetected()
	{
		AnalyticsHelper.AdvancedMotionCheat();
		HandleCheater("You were too far outside of your playspace.");
	}

	private void HandleCheater(string warningMessage = "Dropping to dormroom due to error [385120]")
	{
		UnityEngine.Debug.LogWarning(warningMessage);
		if (GameSessions.LocalGameSession.Location != RoomSceneLocations.DORM_ROOM)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom(warningMessage, SessionManager.LoadSceneSources.CHEAT);
		}
	}
}
public class ChildControlManager : SingletonMonoBehaviour<ChildControlManager>
{
	[Header("On boot height check")]
	[SerializeField]
	private float minHeightMeters = 1.22f;

	[Header("Second screen warning")]
	[SerializeField]
	private float timeBeforeFadeIn = 1f;

	[SerializeField]
	private float fadeInDuration = 0.5f;

	[SerializeField]
	private float visibleDuration = 0.5f;

	[SerializeField]
	private float fadeOutDuration = 0.5f;

	[SerializeField]
	private Canvas warningCanvas;

	[SerializeField]
	private CanvasRenderer warningElement;

	public void StartShowSecondScreenWarning()
	{
		if (warningCanvas != null && warningElement != null)
		{
			StartCoroutine(ShowSecondScreenWarning());
		}
	}

	public void Initialize()
	{
		StartCoroutine(RunHandleInitialLogin());
	}

	private IEnumerator ShowSecondScreenWarning()
	{
		warningElement.SetAlpha(0f);
		yield return new WaitForSeconds(timeBeforeFadeIn);
		warningCanvas.gameObject.SetActive(value: true);
		float t = 0f;
		while (t < fadeInDuration)
		{
			warningElement.SetAlpha(t / fadeInDuration);
			t += UnityEngine.Time.deltaTime;
			yield return null;
		}
		yield return new WaitForSeconds(visibleDuration);
		t = 0f;
		while (t < fadeOutDuration)
		{
			warningElement.SetAlpha(1f - t / fadeInDuration);
			t += UnityEngine.Time.deltaTime;
			yield return null;
		}
		warningCanvas.gameObject.SetActive(value: false);
	}

	private IEnumerator RunHandleInitialLogin()
	{
		while (!Player.LocalPlayerExists || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		float playerHeight = Player.LocalPlayer.CurrentFloorHeightFromHead;
		if (!(playerHeight <= minHeightMeters))
		{
		}
	}
}
namespace RecRoom.Core.Culling
{
	public interface ICullingGroupListener
	{
		void OnChangedDistanceBand(UpdateLOD oldDistanceBand, UpdateLOD newDistanceBand);
	}
	public interface ICullingGroupEx
	{
		int CullingGroupCount { get; }

		int CullingGroupCapacity { get; }
	}
	public interface ICullingGroupEx<T> : ICullingGroupEx where T : UnityEngine.MonoBehaviour, ICullingGroupListener
	{
		UpdateLOD FindClosestDefaultUpdateLod(float distance);

		void Add(T obj, float radius, TransformTrackRate transformTrackRate = TransformTrackRate.Off);

		void UpdateBoundingSphere(T obj, float? radius = null);

		void Remove(T objectToRemove);

		UpdateLOD GetUpdateLOD(T obj);

		bool GetIsVisibleToTargetCamera(T obj);

		void ChangeTransformTrackRate(T obj, TransformTrackRate newTransformTrackRate);
	}
	public enum UpdateLOD
	{
		TwoPointFiveMeters = 0,
		FiveMeters = 1,
		TenMeters = 2,
		TwentyMeters = 3,
		FiftyMeters = 4,
		HundredMeters = 5,
		FiveHundredMeters = 6,
		GreaterThanFiveHundredMeters = 7,
		Invalid = -1
	}
	public enum TransformTrackRate : byte
	{
		Off,
		Limited,
		Full
	}
	public class CullingGroupManager : SingletonMonoBehaviour<CullingGroupManager>
	{
		private abstract class CullingGroupEx : IDisposable, ICullingGroupEx
		{
			public abstract int CullingGroupCount { get; }

			public abstract int CullingGroupCapacity { get; }

			public abstract void Dispose();

			public abstract void SetPaused(bool paused);
		}

		private class CullingGroupEx<T> : CullingGroupEx, ICullingGroupEx<T>, ICullingGroupEx where T : UnityEngine.MonoBehaviour, ICullingGroupListener
		{
			public enum DistanceRelativeTo : byte
			{
				PlayerHead,
				Camera
			}

			private class TrackedObject
			{
				public T Object;

				public TransformTrackRate TrackTransformRate;

				public Action TrackingDelegate;

				public bool HasUpdated;
			}

			private int cullingGroupCount;

			private int cullingGroupCapacity;

			private readonly int initialCapacity;

			private bool disposed;

			private readonly CullingGroup cullingGroup;

			private BoundingSphere[] currentSpheres;

			private readonly Dictionary<T, int> _objectIndexLookup = new Dictionary<T, int>();

			private readonly Dictionary<int, TrackedObject> _indexToObjectLookup = new Dictionary<int, TrackedObject>();

			private readonly DistanceRelativeTo distanceRelativeTo;

			public override int CullingGroupCount
			{
				[CompilerGenerated]
				get
				{
					return cullingGroupCount;
				}
			}

			public override int CullingGroupCapacity
			{
				[CompilerGenerated]
				get
				{
					return cullingGroupCapacity;
				}
			}

			internal CullingGroupEx(int cullingGroupCapacity, float[] distanceBands, DistanceRelativeTo distanceRelativeTo = DistanceRelativeTo.PlayerHead)
			{
				cullingGroup = new CullingGroup();
				cullingGroupCount = 0;
				initialCapacity = cullingGroupCapacity;
				this.cullingGroupCapacity = initialCapacity;
				this.distanceRelativeTo = distanceRelativeTo;
				currentSpheres = new BoundingSphere[cullingGroupCapacity];
				cullingGroup.SetBoundingSpheres(currentSpheres);
				cullingGroup.SetBoundingSphereCount(cullingGroupCount);
				cullingGroup.SetBoundingDistances(distanceBands);
				CullingGroup obj = cullingGroup;
				obj.onStateChanged = (CullingGroup.StateChanged)Delegate.Combine(obj.onStateChanged, new CullingGroup.StateChanged(OnInternalCullingGroupStateChanged));
				CameraRig.ActiveCameraChangeEvent += OnActiveCameraChanged;
				Player.LocalPlayerCreatedEvent += new Action(OnLocalPlayerCreated);
				OnActiveCameraChanged();
			}

			public override void SetPaused(bool paused)
			{
				cullingGroup.enabled = !paused;
			}

			public UpdateLOD FindClosestDefaultUpdateLod(float distance)
			{
				return CullingGroupManager.FindClosestDefaultUpdateLod(distance);
			}

			public void Add(T obj, float radius, TransformTrackRate transformTrackRate = TransformTrackRate.Off)
			{
				if (!disposed)
				{
					if (_objectIndexLookup.ContainsKey(obj))
					{
						Remove(obj);
					}
					int num = cullingGroupCount++;
					if (num >= cullingGroupCapacity)
					{
						int num2 = cullingGroupCapacity;
						cullingGroupCapacity = Mathf.Max(8, cullingGroupCapacity * 2);
						Array.Resize(ref currentSpheres, cullingGroupCapacity);
						cullingGroup.SetBoundingSpheres(currentSpheres);
						UnityEngine.Debug.LogFormat("Exceeded size of culling group spheres array {0}. Reallocating with length {1}. If you see this message too often, turn up the initial size!", num2, cullingGroupCapacity);
					}
					currentSpheres[num].position = obj.transform.position;
					currentSpheres[num].radius = radius;
					cullingGroup.SetBoundingSphereCount(cullingGroupCount);
					_objectIndexLookup[obj] = num;
					TrackedObject trackedObject = new TrackedObject();
					trackedObject.Object = obj;
					trackedObject.TrackTransformRate = transformTrackRate;
					TrackedObject trackedObject2 = trackedObject;
					_indexToObjectLookup[num] = trackedObject2;
					AddTrackTransformUpdate(trackedObject2);
				}
			}

			public void UpdateBoundingSphere(T obj, float? radius = null)
			{
				if (!disposed && !(obj == null))
				{
					int num = _objectIndexLookup[obj];
					currentSpheres[num].position = obj.transform.position;
					if (radius.HasValue)
					{
						currentSpheres[num].radius = radius.Value;
					}
				}
			}

			public void Remove(T objectToRemove)
			{
				if (!disposed && _objectIndexLookup.ContainsKey(objectToRemove))
				{
					int num = _objectIndexLookup[objectToRemove];
					TrackedObject trackedObject = _indexToObjectLookup[num];
					int key = cullingGroupCount - 1;
					CullingGroup.EraseSwapBack(num, currentSpheres, ref cullingGroupCount);
					cullingGroup.SetBoundingSphereCount(cullingGroupCount);
					if (_indexToObjectLookup.TryGetValue(key, out var value))
					{
						_indexToObjectLookup[num] = value;
						_objectIndexLookup[value.Object] = num;
					}
					_indexToObjectLookup.Remove(key);
					_objectIndexLookup.Remove(objectToRemove);
					RemoveTrackTransformUpdate(trackedObject);
					if (cullingGroupCount == 0 && cullingGroupCapacity > initialCapacity)
					{
						int num2 = cullingGroupCapacity;
						cullingGroupCapacity = initialCapacity;
						Array.Resize(ref currentSpheres, cullingGroupCapacity);
						UnityEngine.Debug.LogFormat("Reverting culling group array of size {0} to initial array capacity {1}!", num2, cullingGroupCapacity);
					}
				}
			}

			public UpdateLOD GetUpdateLOD(T obj)
			{
				if (disposed)
				{
					return UpdateLOD.TwoPointFiveMeters;
				}
				int num = _objectIndexLookup[obj];
				TrackedObject trackedObject = _indexToObjectLookup[num];
				if (!trackedObject.HasUpdated)
				{
					UnityEngine.Debug.LogWarning("Attempting to access UpdateLOD from CullingGroup before it's ready. Wait until the next frame!");
					return UpdateLOD.Invalid;
				}
				return (UpdateLOD)cullingGroup.GetDistance(num);
			}

			public bool GetIsVisibleToTargetCamera(T obj)
			{
				if (disposed)
				{
					return true;
				}
				int num = _objectIndexLookup[obj];
				TrackedObject trackedObject = _indexToObjectLookup[num];
				if (!trackedObject.HasUpdated)
				{
					UnityEngine.Debug.LogWarning("Attempting to access Visibility from CullingGroup before it's ready. Wait until the next frame!");
					return true;
				}
				return cullingGroup.IsVisible(num);
			}

			public void ChangeTransformTrackRate(T obj, TransformTrackRate newTrackRate)
			{
				if (!disposed && _objectIndexLookup.ContainsKey(obj))
				{
					int key = _objectIndexLookup[obj];
					TrackedObject trackedObject = _indexToObjectLookup[key];
					if (trackedObject.TrackTransformRate != newTrackRate)
					{
						RemoveTrackTransformUpdate(trackedObject);
						trackedObject.TrackTransformRate = newTrackRate;
						AddTrackTransformUpdate(trackedObject);
					}
				}
			}

			public override void Dispose()
			{
				disposed = true;
				CameraRig.ActiveCameraChangeEvent -= OnActiveCameraChanged;
				Player.LocalPlayerCreatedEvent -= new Action(OnLocalPlayerCreated);
				foreach (TrackedObject value in _indexToObjectLookup.Values)
				{
					RemoveTrackTransformUpdate(value);
				}
				_indexToObjectLookup.Clear();
				_objectIndexLookup.Clear();
				cullingGroup.Dispose();
			}

			private void AddTrackTransformUpdate(TrackedObject trackedObject)
			{
				if (trackedObject.TrackTransformRate == TransformTrackRate.Off)
				{
					return;
				}
				Action trackingDelegate = delegate
				{
					TrackTransform(trackedObject);
				};
				trackedObject.TrackingDelegate = trackingDelegate;
				if (trackedObject.TrackTransformRate == TransformTrackRate.Full)
				{
					onUpdateTrackedTransforms += trackedObject.TrackingDelegate;
					if (onUpdateTrackedTransformsUpdateToken == null)
					{
						onUpdateTrackedTransformsUpdateToken = SingletonMonoBehaviour<CullingGroupManager>.Instance.Update(UpdateTrackedTransforms);
					}
				}
				else if (trackedObject.TrackTransformRate == TransformTrackRate.Limited)
				{
					onLimitedUpdateTrackedTransforms += trackedObject.TrackingDelegate;
					if (onLimitedUpdateTrackedTransformsUpdateToken == null)
					{
						onLimitedUpdateTrackedTransformsUpdateToken = SingletonMonoBehaviour<CullingGroupManager>.Instance.Update10hz(LimitedUpdateTrackedTransforms);
					}
				}
			}

			private void RemoveTrackTransformUpdate(TrackedObject trackedObject)
			{
				onUpdateTrackedTransforms -= trackedObject.TrackingDelegate;
				if (!onUpdateTrackedTransforms.HasEvent && onUpdateTrackedTransformsUpdateToken != null)
				{
					onUpdateTrackedTransformsUpdateToken.Dispose();
					onUpdateTrackedTransformsUpdateToken = null;
				}
				onLimitedUpdateTrackedTransforms -= trackedObject.TrackingDelegate;
				if (!onLimitedUpdateTrackedTransforms.HasEvent && onLimitedUpdateTrackedTransformsUpdateToken != null)
				{
					onLimitedUpdateTrackedTransformsUpdateToken.Dispose();
					onLimitedUpdateTrackedTransformsUpdateToken = null;
				}
			}

			private void UpdateTrackedTransforms()
			{
				onUpdateTrackedTransforms.Invoke();
			}

			private void LimitedUpdateTrackedTransforms(float deltaTime)
			{
				onLimitedUpdateTrackedTransforms.Invoke();
			}

			private void TrackTransform(TrackedObject trackedObject)
			{
				UpdateBoundingSphere(trackedObject.Object);
			}

			private void OnLocalPlayerCreated()
			{
				if (distanceRelativeTo == DistanceRelativeTo.PlayerHead)
				{
					SetCullingGroupTargets();
				}
			}

			private void OnActiveCameraChanged()
			{
				SetCullingGroupTargets();
			}

			private void OnInternalCullingGroupStateChanged(CullingGroupEvent cullingGroupEvent)
			{
				if (!_indexToObjectLookup.ContainsKey(cullingGroupEvent.index))
				{
					UnityEngine.Debug.LogErrorFormat("No object with index {0} was found for event!", cullingGroupEvent.index);
					return;
				}
				TrackedObject trackedObject = _indexToObjectLookup[cullingGroupEvent.index];
				UpdateLOD updateLOD = ((!trackedObject.HasUpdated) ? UpdateLOD.Invalid : ((UpdateLOD)cullingGroupEvent.previousDistance));
				UpdateLOD currentDistance = (UpdateLOD)cullingGroupEvent.currentDistance;
				trackedObject.HasUpdated = true;
				if (updateLOD != currentDistance)
				{
					trackedObject.Object.OnChangedDistanceBand(updateLOD, currentDistance);
				}
			}

			private void SetCullingGroupTargets()
			{
				if (SingletonMonoBehaviour<CameraRig>.IsInitialized)
				{
					cullingGroup.targetCamera = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera;
				}
				DistanceRelativeTo distanceRelativeTo = this.distanceRelativeTo;
				Transform transform = ((distanceRelativeTo != DistanceRelativeTo.Camera) ? ((!Player.LocalPlayerExists) ? null : Player.LocalPlayer.Head.transform) : ((!SingletonMonoBehaviour<CameraRig>.IsInitialized) ? null : SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform));
				if (transform != null)
				{
					cullingGroup.SetDistanceReferencePoint(transform);
				}
			}
		}

		private struct CullingGroupKey
		{
			public ushort CullingGroupId;

			public System.Type CullingGroupInternalType;
		}

		private const float TWO_POINT_FIVE_METERS = 2.5f;

		private const float FIVE_METERS = 5f;

		private const float TEN_METERS = 10f;

		private const float TWENTY_METERS = 10f;

		private const float FIFTY_METERS = 50f;

		private const float HUNDRED_METERS = 100f;

		private const float FIVE_HUNDRED_METERS = 500f;

		public const ushort DEFAULT_CULLING_GROUP_ID = 0;

		public static readonly float[] DefaultDistanceBands = new float[7] { 2.5f, 5f, 10f, 10f, 50f, 100f, 500f };

		private static readonly Dictionary<CullingGroupKey, CullingGroupEx> cullingGroupExs = new Dictionary<CullingGroupKey, CullingGroupEx>();

		private static IDisposable onUpdateTrackedTransformsUpdateToken;

		private static IDisposable onLimitedUpdateTrackedTransformsUpdateToken;

		private static ActionEvent onLimitedUpdateTrackedTransforms = new ActionEvent();

		private static ActionEvent onUpdateTrackedTransforms = new ActionEvent();

		private ISchedulerPromise endOfFrameSchedule;

		private static bool paused = false;

		protected override void Awake()
		{
			base.Awake();
			SceneManager.sceneLoaded += OnSceneLoaded;
		}

		private void OnSceneLoaded(UnityEngine.SceneManagement.Scene scene, LoadSceneMode mode)
		{
			if (scene.name == "empty")
			{
				ClearCullingGroups();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			SceneManager.sceneLoaded -= OnSceneLoaded;
			ClearCullingGroups();
		}

		private void ClearCullingGroups()
		{
			foreach (CullingGroupEx value in cullingGroupExs.Values)
			{
				value.Dispose();
			}
			cullingGroupExs.Clear();
		}

		public void PauseUntilEndOfFrame()
		{
			if (endOfFrameSchedule != null)
			{
				endOfFrameSchedule.Dispose();
			}
			endOfFrameSchedule = this.InvokeNextEndOfFrame(UnpauseAtEndOfFrame);
			if (paused)
			{
				return;
			}
			paused = true;
			foreach (CullingGroupEx value in cullingGroupExs.Values)
			{
				value.SetPaused(paused: true);
			}
		}

		private void UnpauseAtEndOfFrame()
		{
			paused = false;
			foreach (CullingGroupEx value in cullingGroupExs.Values)
			{
				value.SetPaused(paused: false);
			}
		}

		public ICullingGroupEx<T> GetOrCreateCullingGroup<T>(int cullingGroupArraySize, ushort cullingGroupId = 0) where T : UnityEngine.MonoBehaviour, ICullingGroupListener
		{
			return GetOrCreateCullingGroup<T>(cullingGroupArraySize, DefaultDistanceBands, cullingGroupId);
		}

		private ICullingGroupEx<T> GetOrCreateCullingGroup<T>(int cullingGroupArraySize, float[] distanceBands, ushort cullingGroupId = 0) where T : UnityEngine.MonoBehaviour, ICullingGroupListener
		{
			CullingGroupKey key = new CullingGroupKey
			{
				CullingGroupId = cullingGroupId,
				CullingGroupInternalType = typeof(T)
			};
			if (!cullingGroupExs.TryGetValue(key, out var value))
			{
				value = new CullingGroupEx<T>(cullingGroupArraySize, distanceBands);
				cullingGroupExs[key] = value;
			}
			return (CullingGroupEx<T>)value;
		}

		public static UpdateLOD FindClosestDefaultUpdateLod(float origValue)
		{
			if (origValue > DefaultDistanceBands[6])
			{
				return UpdateLOD.GreaterThanFiveHundredMeters;
			}
			int result = -1;
			float num = float.MaxValue;
			for (int i = 0; i < DefaultDistanceBands.Length; i++)
			{
				float num2 = Mathf.Abs(origValue - DefaultDistanceBands[i]);
				if (num2 <= num)
				{
					num = num2;
					result = i;
				}
			}
			return (UpdateLOD)result;
		}

		public static UpdateLOD MinUpdateLod(UpdateLOD lod1, UpdateLOD lod2)
		{
			return (UpdateLOD)Mathf.Min((int)lod1, (int)lod2);
		}

		public static UpdateLOD MaxUpdateLod(UpdateLOD lod1, UpdateLOD lod2)
		{
			return (UpdateLOD)Mathf.Max((int)lod1, (int)lod2);
		}
	}
	public class UpdateLODOverride
	{
		private UpdateLOD min = UpdateLOD.Invalid;

		private UpdateLOD max = UpdateLOD.Invalid;

		private Dictionary<object, UpdateLOD> tokenMap = new Dictionary<object, UpdateLOD>(0);

		public bool HasTokens
		{
			[CompilerGenerated]
			get
			{
				return tokenMap.Count > 0;
			}
		}

		public UpdateLOD MinValue
		{
			[CompilerGenerated]
			get
			{
				return min;
			}
		}

		public UpdateLOD MaxValue
		{
			[CompilerGenerated]
			get
			{
				return max;
			}
		}

		public bool AddValue(object token, UpdateLOD value)
		{
			tokenMap[token] = value;
			return UpdateMinMax();
		}

		public bool RemoveValue(object token)
		{
			tokenMap.Remove(token);
			return UpdateMinMax();
		}

		private bool UpdateMinMax()
		{
			UpdateLOD updateLOD = min;
			UpdateLOD updateLOD2 = max;
			min = UpdateLOD.GreaterThanFiveHundredMeters;
			max = UpdateLOD.TwoPointFiveMeters;
			foreach (UpdateLOD value in tokenMap.Values)
			{
				if (value <= min)
				{
					min = value;
				}
				if (value >= max)
				{
					max = value;
				}
			}
			return updateLOD != min || updateLOD2 != max;
		}
	}
}
