		[SerializeField]
		private float celebrateParticleSpacing = 0.4f;

		private int storeCreditAwardDenomination = 1;

		private const int numberOfTimesToShowDropItemNote = 5;

		private const string FIRST_TIME_GETTING_RECCENTER_TOKENS = "FIRST_TIME_GETTING_RECCENTER_TICKETS";

		private Coroutine receiveCurrencyAwardsCoroutine;

		public bool IsCurrencyRewardRunning => receiveCurrencyAwardsCoroutine != null;

		public static bool FirstTimeGettingRecCenterTokens
		{
			get
			{
				return RecroomPrefs.GetInt("FIRST_TIME_GETTING_RECCENTER_TICKETS", 1) == 1;
			}
			set
			{
				RecroomPrefs.SetInt("FIRST_TIME_GETTING_RECCENTER_TICKETS", value ? 1 : 0);
				RecroomPrefs.Save();
			}
		}

		private bool LocalPlayerCloseToCurrencyAwardSpawnPosition => Player.LocalPlayerExists && (Player.LocalPlayer.Head.transform.position - Player.LocalPlayer.LastSpawnPosition).magnitude <= 2f;

		public void ReceiveCurrencyAwardDirectly(Player owner, int baseAward, int bonusAward, int currentCount, int rateLimit, StorefrontBalanceAddTypes balanceAddType, CurrencyType currencyType)
		{
			CurrencyTypeSettings currencySettings = GetCurrencySettings(currencyType);
			if (currencySettings != null && !currencySettings.skipAwardNotifications)
			{
				CurrencyAward currencyAward = new CurrencyAward
				{
					baseAward = baseAward,
					bonusAward = bonusAward,
					currentCount = currentCount,
					rateLimit = rateLimit,
					balanceAddType = balanceAddType,
					currencyType = currencyType
				};
				StartCoroutine(RunWaitForGameOverRespawn(currencyAward));
			}
		}

		private IEnumerator RunWaitForGameOverRespawn(CurrencyAward currencyAward)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState == GameStates.POST_GAME)
			{
				yield return new WaitUntil(() => NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentPostGameState != PostGameSubStates.GAME_OVER);
			}
			if (!(NetworkedSingletonMonoBehaviour<GameManager>.Instance == null))
			{
				yield return new WaitUntil(() => !Player.LocalPlayer.IsSpawning);
				yield return new WaitForSeconds(postSpawnDelay);
				Vector3 rotationEuler = Player.LocalPlayer.Body.transform.rotation.eulerAngles;
				Quaternion spawnRotation = Quaternion.Euler(0f, rotationEuler.y, rotationEuler.z);
				StartReceiveCurrencyAwardsCoroutine(spawnPosition: Player.LocalPlayer.Head.transform.position + spawnRotation * Vector3.forward * 1.6f, targetPlayer: Player.LocalPlayer, award: currencyAward, spawnRotation: spawnRotation, fromGiftBox: false);
			}
		}

		public void ReceiveCurrencyAwardFromGiftBox(Player owner, int amount, CurrencyType currencyType, Vector3 spawnPosition, Quaternion spawnRotation)
		{
			CurrencyAward award = new CurrencyAward
			{
				baseAward = amount,
				bonusAward = 0,
				currentCount = 0,
				rateLimit = 0,
				balanceAddType = StorefrontBalanceAddTypes.FromGiftBox,
				currencyType = currencyType
			};
			StartReceiveCurrencyAwardsCoroutine(owner, award, spawnPosition, spawnRotation, fromGiftBox: true);
		}

		public void StartReceiveCurrencyAwardsCoroutine(Player targetPlayer, CurrencyAward award, Vector3 spawnPosition, Quaternion spawnRotation, bool fromGiftBox)
		{
			StopReceiveCurrencyAvardsCoroutine();
			receiveCurrencyAwardsCoroutine = StartCoroutine(RunReceiveCurrencyAward(targetPlayer, award, spawnPosition, spawnRotation, fromGiftBox));
		}

		public void StopReceiveCurrencyAvardsCoroutine()
		{
			if (receiveCurrencyAwardsCoroutine != null)
			{
				StopCoroutine(receiveCurrencyAwardsCoroutine);
			}
		}

		private IEnumerator RunReceiveCurrencyAward(Player targetPlayer, CurrencyAward award, Vector3 spawnPosition, Quaternion spawnRotation, bool fromGiftBox)
		{
			StartCoroutine(RunStartDispenseCurrencyAward(targetPlayer, award.baseAward, spawnPosition, baseAwardNotificationTimings, award.currencyType, fromGiftBox));
			string awardString = string.Empty;
			WorldSpaceNotification notification = null;
			if (!fromGiftBox)
			{
				awardString = string.Format(titleTemplate, GetPluralCurrencyName(award.currencyType));
				notification = WorldSpaceNotification.PlayNext(awardString, 5f, null, followPlayer: false, spawnPosition, 0.9f, billboard: true);
				yield return RunPlayAudioAndVisualEffects(notification, string.Empty, award.baseAward, 0, spawnPosition, spawnRotation, baseAwardNotificationTimings, award.currencyType);
			}
			yield return new WaitForSeconds(postBaseAwardDelay);
			awardString = string.Format(titleTemplate, ToCurrencyString(award.baseAward, award.currencyType));
			if (award.bonusAward > 0)
			{
				StartCoroutine(RunStartDispenseCurrencyAward(targetPlayer, award.baseAward, spawnPosition, baseAwardNotificationTimings, award.currencyType, fromGiftBox));
				if (!fromGiftBox)
				{
					string bonusSubtitle = string.Format(bonusSubtitleTemplate, award.currentCount, award.rateLimit);
					notification.RefreshNotificationText(awardString, 3f, bonusSubtitle);
					yield return RunPlayAudioAndVisualEffects(notification, bonusSubtitle, award.bonusAward, award.baseAward, spawnPosition, spawnRotation, bonusAwardNotificationTimings, award.currencyType);
				}
			}
			else if (award.balanceAddType == StorefrontBalanceAddTypes.WonGameRateLimited && !fromGiftBox)
			{
				notification.RefreshNotificationText(awardString, 3f, awardNoDailySubtitle);
			}
			yield return new WaitForSeconds(preFinishAudioDelay);
			CurrencyTypeSettings settings = GetCurrencySettings(award.currencyType);
			if (settings != null && settings.celebrationFinishAudio != null)
			{
				AudioManager.Play3DSFX(settings.celebrationFinishAudio, spawnPosition);
			}
		}

		private IEnumerator RunStartDispenseCurrencyAward(Player targetPlayer, int awardAmount, Vector3 spawnPosition, NotificationTimings timing, CurrencyType currencyType, bool fromGiftBox)
		{
			yield return new WaitForSeconds(timing.preCollectableDelay);
			CurrencyTypeSettings settings = GetCurrencySettings(currencyType);
			if (settings != null && settings.dispensingCurrencyAudioClip != null)
			{
				AudioManager.Play3DSFX(settings.dispensingCurrencyAudioClip, spawnPosition);
			}
			if (fromGiftBox && settings != null && settings.currencyBoxAwardFx != null)
			{
				SpawnCurrencyCollectableParticleSystem(awardAmount, spawnPosition, settings);
			}
			else
			{
				SpawnCurrencyCollectableAwards(targetPlayer, awardAmount, spawnPosition, timing, currencyType);
			}
		}

		private void SpawnCurrencyCollectableParticleSystem(int awardAmount, Vector3 spawnPosition, CurrencyTypeSettings settings)
		{
			PooledParticle currencyBoxAwardFx = settings.currencyBoxAwardFx;
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(currencyBoxAwardFx);
			ParticleSystem.EmissionModule emission = pooledParticle.PrimaryParticleSystem.emission;
			float num = awardAmount;
			ParticleSystem.MainModule main = pooledParticle.PrimaryParticleSystem.main;
			main.duration *= settings.particleSpawnDurations.Evaluate(num);
			emission.rateOverTimeMultiplier = num * settings.particleSpawnAmounts.Evaluate(num) / main.duration;
			pooledParticle.Play(spawnPosition, Quaternion.identity);
		}

		private void SpawnCurrencyCollectableAwards(Player targetPlayer, int awardAmount, Vector3 spawnPosition, NotificationTimings timing, CurrencyType currencyType)
		{
			Collectible currencyPrefab = GetCurrencyPrefab(currencyType);
			if (currencyPrefab != null)
			{
				StartCoroutine(Collectible.SpawnStaggeredCollectibleGroup(currencyPrefab, awardAmount, storeCreditAwardDenomination, spawnPosition, targetPlayer, automaticallyPickup: true, timing.collectableSpawnDuration, delegate
				{
				}));
			}
			else
			{
				UnityEngine.Debug.LogError(string.Concat("Collectible prefab for ", currencyType, " is null"));
			}
		}

		private IEnumerator RunPlayAudioAndVisualEffects(WorldSpaceNotification notification, string subtitle, int awardAmount, int previousAward, Vector3 spawnPosition, Quaternion rotation, NotificationTimings timing, CurrencyType currencyType)
		{
			if (celebrateParticlePrefab != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(celebrateParticlePrefab);
				if (pooledParticle != null)
				{
					pooledParticle.Play(spawnPosition + rotation * Vector3.right * celebrateParticleSpacing, rotation);
				}
				PooledParticle pooledParticle2 = ObjectPool.Instance.Acquire(celebrateParticlePrefab);
				if (pooledParticle2 != null)
				{
					pooledParticle2.Play(spawnPosition + rotation * Vector3.left * celebrateParticleSpacing, rotation);
				}
			}
			AudioManager.Play3DSFX(timing.celebrationStartAudio, spawnPosition);
			yield return new WaitForSeconds(timing.preCollectableDelay + timing.postCollectableDelay);
			float countdownTimer = timing.awardCountDuration;
			float tickTimer = 0f;
			int totalTicks = Mathf.CeilToInt(countdownTimer / timing.awardCountTickFrequency);
			int countedTicks = 0;
			int countedAward = 0;
			int awardStepSize = awardAmount / totalTicks;
			string title = string.Empty;
			CurrencyTypeSettings settings = GetCurrencySettings(currencyType);
			while (countdownTimer > 0f)
			{
				tickTimer += UnityEngine.Time.deltaTime;
				if (tickTimer >= timing.awardCountTickFrequency)
				{
					countdownTimer -= tickTimer;
					tickTimer = 0f;
					countedTicks++;
					if (settings != null && settings.countingCurrencyAudioClip != null)
					{
						settings.countingCurrencyAudioClip.pitchShift = (float)countedTicks * 0.6f / (float)totalTicks;
						AudioManager.Play3DSFX(settings.countingCurrencyAudioClip, spawnPosition);
					}
					countedAward += awardStepSize;
					if (countedAward > awardAmount)
					{
						break;
					}
					title = string.Format(titleTemplate, ToCurrencyString(previousAward + countedAward, currencyType));
					notification.RefreshNotificationText(title, 3f, subtitle);
				}
				yield return null;
			}
			title = string.Format(titleTemplate, ToCurrencyString(previousAward + awardAmount, currencyType));
			notification.RefreshNotificationText(title, 3f, subtitle);
		}

		private CurrencyTypeSettings GetCurrencySettings(CurrencyType currencyType)
		{
			CurrencyTypeSettings[] array = this.currencyTypeSettings;
			foreach (CurrencyTypeSettings currencyTypeSettings in array)
			{
				if (currencyTypeSettings.currencyType == currencyType)
				{
					return currencyTypeSettings;
				}
			}
			return null;
		}

		public string ToCurrencyString(long balance, CurrencyType currencyType)
		{
			CurrencyTypeSettings currencySettings = GetCurrencySettings(currencyType);
			bool flag = (balance == 0 || balance > 1) && !(currencySettings?.currencyNameSingularOnly ?? false);
			string arg = ((currencySettings == null) ? "Token" : currencySettings.currencyName);
			return string.Format("{0} {1}{2}", balance.ToString(), arg, (!flag) ? string.Empty : "s");
		}

		public string GetPluralCurrencyName(CurrencyType currencyType)
		{
			CurrencyTypeSettings currencySettings = GetCurrencySettings(currencyType);
			if (currencySettings != null)
			{
				return currencySettings.currencyName + ((!currencySettings.currencyNameSingularOnly) ? "s" : string.Empty);
			}
			return "Tokens";
		}

		public Collectible GetCurrencyPrefab(CurrencyType currencyType)
		{
			return GetCurrencySettings(currencyType)?.currencyPrefab;
		}
	}
}
public class DebugGuiManager : SingletonMonoBehaviour<DebugGuiManager>
{
	public bool GUIEnabled = true;

	public bool PerfCountersEnabled = true;

	private GUIStyle headerStyle;

	public PerformanceCounters PerformanceCounters { get; private set; }

	public bool ApplicationHasFocus { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		PerformanceCounters = GetComponent<PerformanceCounters>();
		base.enabled = false;
		ApplicationHasFocus = true;
	}

	public void Initialize()
	{
		base.enabled = SessionManager.IsDeveloper;
	}

	private void OnApplicationFocus(bool hasFocus)
	{
		ApplicationHasFocus = hasFocus;
	}

	private void Update()
	{
		if (Input.GetKeyUp(KeyCode.Slash))
		{
			GUIEnabled = !GUIEnabled;
		}
	}

	private void OnGUI()
	{
		if (!SessionManager.IsDeveloper || !GUIEnabled)
		{
			return;
		}
		if (headerStyle == null)
		{
			headerStyle = new GUIStyle(GUI.skin.label);
			headerStyle.fontStyle = FontStyle.Bold;
		}
		int num = 10;
		if (!PhotonNetwork.insideLobby && PerfCountersEnabled)
		{
			GUI.Box(new Rect(0f, num, 260f, 90f), "Press [/] to hide");
			GUI.Label(new Rect(0f, num += 20, 260f, 20f), "Performance Counters");
			GUI.Label(new Rect(5f, num += 20, 200f, 20f), string.Format("FramesPerSecond: {0}", PerformanceCounters.FPS.ToString("F1")));
			GUI.Label(new Rect(5f, num += 20, 200f, 20f), $"Ping : {PerformanceCounters.RoundTripTime} ± {PhotonNetwork.networkingPeer.RoundTripTimeVariance} (msec)");
		}
		if (!PhotonNetwork.inRoom || PhotonNetwork.playerList.Length <= 0)
		{
			return;
		}
		int num2 = (num += 35);
		GameSession localGameSession = GameSessions.LocalGameSession;
		RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
		GUI.Box(new Rect(0f, num2, 260f, 40f), $"GameSessionId: {localGameSession.GameSessionId}\n{((localRoomDetails == null) ? string.Empty : $"^{localRoomDetails.Room.Name} ({localRoomDetails.Room.RoomId})")}");
		num2 += 50;
		int num3 = PhotonNetwork.playerList.Length;
		GUI.Box(new Rect(0f, num2, 260f, num3 * 20 + 50), $"Version: {BuildSettings.Version}, Players: {num3}");
		GUILayout.BeginVertical();
		GUILayout.Space(num2 + 20);
		foreach (Player item in Player.All)
		{
			if (item != null && item.PhotonPlayer != null)
			{
				GUILayout.BeginHorizontal();
				GUILayout.Label(string.Format("#{0} : {1} {2} {3}", item.PlayerId, item.PlayerName, $"[ping:{item.Ping}]", (!item.PhotonPlayer.IsMasterClient) ? string.Empty : "[Master]"), (!item.isLocal) ? GUI.skin.label : headerStyle, GUILayout.Width(200f));
				GUILayout.EndHorizontal();
			}
		}
		GUILayout.EndVertical();
	}
}
