public enum GameRestartBehaviors
{
	DestroyNew,
	DestroyOld
}
public class GameRoot : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameObject StartupObject;

	[SerializeField]
	private Transform coreSystems;

	[SerializeField]
	private Transform UI;

	public static GameRoot Instance = null;

	public static int index = 0;

	public static HashSet<IGameSingleton> ExistingGameSingletons = new HashSet<IGameSingleton>();

	private static List<GameRoot> GameRoots = new List<GameRoot>();

	public static void AddExistingSingleton(IGameSingleton s)
	{
		ExistingGameSingletons.Add(s);
	}

	private void Awake()
	{
		GameRoots.Add(this);
	}

	private IEnumerator Start()
	{
		GameObject obj = base.gameObject;
		obj.name = obj.name + "_" + index++;
		if (Instance == null)
		{
			Instance = this;
			StartupObject.SetActive(value: true);
		}
		else
		{
			List<IGameSingleton> newSingletons = new List<IGameSingleton>();
			newSingletons.AddRange(GetComponentsInChildren<SingletonMonoBehaviourBase>(includeInactive: true));
			newSingletons.AddRange(GetComponentsInChildren<NetworkedSingletonMonoBehaviourBase>(includeInactive: true));
			newSingletons.AddRange(GetComponentsInChildren<ManagedSingletonObject>(includeInactive: true));
			UnityEngine.Debug.Log(newSingletons.Count + " new singletons");
			List<GameObject> toDestroy = new List<GameObject>();
			StringBuilder logBuilder = new StringBuilder();
			logBuilder.AppendLine("Marking old objects for destroy:");
			foreach (IGameSingleton existingGameSingleton in ExistingGameSingletons)
			{
				if (existingGameSingleton.GameRestartBehavior == GameRestartBehaviors.DestroyOld)
				{
					logBuilder.Append("\t").AppendLine(existingGameSingleton.GameObject.name);
					toDestroy.Add(existingGameSingleton.GameObject);
				}
			}
			logBuilder.AppendLine("Marking new objects for destroy:");
			foreach (IGameSingleton item in newSingletons)
			{
				if (item.GameRestartBehavior == GameRestartBehaviors.DestroyNew)
				{
					logBuilder.Append("\t").AppendLine(item.GameObject.name);
					toDestroy.Add(item.GameObject);
				}
			}
			logBuilder.AppendLine("Destroying:");
			foreach (GameObject item2 in toDestroy)
			{
				logBuilder.Append("\t").AppendLine(item2.name);
				UnityEngine.Object.Destroy(item2);
			}
			UnityEngine.Debug.Log(logBuilder.ToString());
			yield return null;
			yield return MergeRoots(GameRoots);
			StartupObject.SetActive(value: true);
		}
		GameObject bootSequenceObj = new GameObject("BootSequence");
		bootSequenceObj.AddComponent<BootSequence>();
	}

	public static IEnumerator MergeRoots(List<GameRoot> gameRoots)
	{
		if (gameRoots.Count == 2)
		{
			GameRoot gameRoot0 = gameRoots[0];
			GameRoot gameRoot1 = gameRoots[1];
			UnityEngine.Debug.Log(string.Concat("Merging :", gameRoot0, " ", gameRoot1));
			UnityEngine.Debug.Log(string.Concat("GameRoot0 (", gameRoot0, ") has ", gameRoot0.coreSystems.childCount, " CoreSystems"));
			Dictionary<Transform, Transform> newParents = new Dictionary<Transform, Transform>();
			for (int i = 0; i < gameRoot0.coreSystems.childCount; i++)
			{
				Transform child = gameRoot0.coreSystems.GetChild(i);
				newParents[child] = gameRoot1.coreSystems;
			}
			UnityEngine.Debug.Log(string.Concat("GameRoot0 (", gameRoot0, ") has ", gameRoot0.UI.childCount, " UI"));
			for (int j = 0; j < gameRoot0.UI.childCount; j++)
			{
				Transform child2 = gameRoot0.UI.GetChild(j);
				newParents[child2] = gameRoot1.UI;
			}
			foreach (KeyValuePair<Transform, Transform> item in newParents)
			{
				item.Key.SetParent(item.Value);
			}
			yield return null;
			if (gameRoot0.coreSystems.childCount == 0)
			{
				UnityEngine.Object.Destroy(gameRoot0.coreSystems.gameObject);
			}
			if (gameRoot0.UI.childCount == 0)
			{
				UnityEngine.Object.Destroy(gameRoot0.UI.gameObject);
			}
			yield return null;
			for (int k = 0; k < gameRoot0.StartupObject.transform.childCount; k++)
			{
				Transform child3 = gameRoot0.StartupObject.transform.GetChild(k);
				UnityEngine.Debug.LogError("found child" + child3);
			}
			if (gameRoot0.StartupObject.transform.childCount == 0)
			{
				UnityEngine.Object.Destroy(gameRoot0.gameObject);
			}
			Instance = gameRoot1;
		}
		else
		{
			UnityEngine.Debug.LogError("Must be exactly 2 GameRoots to merge. Something went wrong!");
		}
	}

	private void OnDestroy()
	{
		GameRoots.Remove(this);
	}
}
