	private List<Avatars.GiftPackage> giftPackagesToReceive = new List<Avatars.GiftPackage>();

	private float lastGameGiftTime = float.MinValue;

	private Coroutine celebrateEffectCoroutine;

	private GiftBox lastGiftBoxObject;

	public Material DefaultGiftBoxMaterial => variantMap.DefaultGiftBoxMaterial;

