	public void Initialize()
	{
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
		SceneManager.sceneUnloaded += SceneManager_sceneUnloaded;
		playerHeightRange = maxPlayerHeight - minPlayerHeight;
		Avatars.GiftPackageReceivedEvent += OnGiftPackageReceivedEvent;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		SceneManager.sceneLoaded -= SceneManager_sceneLoaded;
		SceneManager.sceneUnloaded -= SceneManager_sceneUnloaded;
		Avatars.GiftPackageReceivedEvent -= OnGiftPackageReceivedEvent;
	}

	private void OnGiftPackageReceivedEvent(Avatars.GiftPackage giftPackage, bool showImmediately)
	{
		if (!showImmediately)
		{
			return;
		}
		if (Player.LocalPlayerExists)
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance?.IsGameRunningOrLoading != true)
			{
				ReceiveGifts(new List<Avatars.GiftPackage> { giftPackage }, useSpawnLocation: false, dismissExistingGift: false);
			}
		}
		else
		{
			receiveGiftsOnNextSceneLoad = true;
		}
	}

	private void SceneManager_sceneUnloaded(Scene scene)
	{
		StopReceiveGiftsCoroutine();
	}

	public GiftPackageVariant GetPackageVariantByContext(GiftContext context)
	{
		GiftPackageVariant.GiftContextMapping giftContextMap = null;
		return variantMap.GetPackageVariantByContext(context, out giftContextMap);
	}

	public GiftPackageVariant GetPackageVariantByContext(GiftContext context, out GiftPackageVariant.GiftContextMapping giftContextMap)
	{
		return variantMap.GetPackageVariantByContext(context, out giftContextMap);
	}

	public void ReceiveGifts(List<Avatars.GiftPackage> giftPackages, bool useSpawnLocation, bool dismissExistingGift)
	{
		if (dismissExistingGift)
		{
			giftPackagesToReceive.AddRange(giftPackages);
			StartReceiveGiftsCoroutine(useSpawnLocation);
		}
		else if (receiveGiftsCoroutine != null)
		{
			giftPackagesToReceive.AddRange(giftPackages);
		}
		else if (ActiveGiftBox != null)
		{
			GiftBox activeGiftBox = ActiveGiftBox;
			activeGiftBox.OnGiftBoxDestroyed = (Action<GiftBox>)Delegate.Combine(activeGiftBox.OnGiftBoxDestroyed, (Action<GiftBox>)delegate(GiftBox giftBox)
			{
				if (giftBox.CloseToPlayer)
				{
					giftPackagesToReceive.Clear();
					giftPackagesToReceive = giftPackages;
					StartReceiveGiftsCoroutine(useSpawnLocation);
				}
			});
		}
		else
		{
			giftPackagesToReceive.Clear();
			giftPackagesToReceive = giftPackages;
			StartReceiveGiftsCoroutine(useSpawnLocation);
		}
	}

	private void StartReceiveGiftsCoroutine(bool useSpawnLocation)
	{
		StopReceiveGiftsCoroutine();
		giftPackagesToReceive = giftPackagesToReceive.Distinct().ToList();
		receiveGiftsCoroutine = StartCoroutine(ReceiveGiftsFromQueue(useSpawnLocation));
	}

	public void StopReceiveGiftsCoroutine()
	{
		if (receiveGiftsCoroutine != null)
		{
			StopCoroutine(receiveGiftsCoroutine);
			receiveGiftsCoroutine = null;
		}
		if (lastGiftBoxObject != null)
		{
			PhotonNetwork.Destroy(lastGiftBoxObject.gameObject);
		}
	}

	private void SceneManager_sceneLoaded(Scene scene, LoadSceneMode mode)
	{
		if ((SessionManager.InDormRoom || SessionManager.InRecCenter || receiveGiftsOnNextSceneLoad) && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Complete)
		{
			ReceiveGifts(Avatars.GiftPackages, useSpawnLocation: true, dismissExistingGift: false);
		}
		receiveGiftsOnNextSceneLoad = false;
	}

	public void GenerateGameGift(GiftContext context)
	{
		if ((NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomGameSettings.AllowRewards) && UnityEngine.Time.realtimeSinceStartup - lastGameGiftTime > 20f)
		{
			if (context == GiftContext.Default)
			{
				context = GiftContext.Game_Drop;
			}
			if (context != GiftContext.None)
			{
				lastGameGiftTime = UnityEngine.Time.realtimeSinceStartup;
				StartCoroutine(RunGenerateGift(context, null, isGameGift: true));
			}
		}
	}

	public void StopReceivingGifts()
	{
		StopReceiveGiftsCoroutine();
	}

	public IEnumerator RunGenerateGift(GiftContext giftContext, GiftContext? alternateGiftContext = null, bool isGameGift = false, GenerateGiftCallback callback = null)
	{
		Avatars.GiftPackage giftPackage = null;
		string error = null;
		yield return Avatars.LocalRequestGiftPackage(giftContext, alternateGiftContext, isGameGift, delegate(string e, Avatars.GiftPackage gift)
		{
			error = e;
			giftPackage = gift;
		});
		if (giftPackage != null)
		{
			AnalyticsHelper.ReceivedGift(giftPackage);
		}
		callback?.Invoke(giftPackage, error);
	}

	private IEnumerator ReceiveGiftsFromQueue(bool useSpawnLocation)
	{
		while (!Player.LocalPlayerExists || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		Vector3 initialPosition = ((!useSpawnLocation) ? Player.LocalPlayer.CurrentFloorPosition : Player.LocalPlayer.LastSpawnPosition);
		Vector3 forwardDirection = Vector3.ProjectOnPlane(Player.LocalPlayer.Head.transform.forward, Vector3.up);
		Quaternion giftRotation = Quaternion.LookRotation(forwardDirection);
		Vector3 giftPosition = initialPosition + giftRotation * Vector3.forward * 0.6f;
		if (giftPackagesToReceive.Count > 0 && useSpawnLocation)
		{
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(SingletonMonoBehaviour<GiftManager>.Instance);
			PlayCelebrateEffect(giftPosition);
		}
		while (Player.LocalPlayerExists && giftPackagesToReceive.Count > 0 && (Player.LocalPlayer.CurrentFloorPosition - initialPosition).sqrMagnitude <= 4f)
		{
			yield return new WaitForSeconds(1f);
			giftPosition.y = GetGiftSpawnHeight(Player.LocalPlayer);
			Avatars.GiftPackage giftPackage = giftPackagesToReceive.LastItem();
			yield return DequeueGift(giftPackage, giftPosition, giftRotation, (Avatars.GiftPackage package) => package.PackageVariant.dequeueBehavior == GiftPackageVariant.DequeueBehaviors.WaitUntilOpenedOrPlayerMoved);
			if (giftPackagesToReceive.Count > 0 && giftPackagesToReceive.LastItem().Id == giftPackage.Id)
			{
				giftPackagesToReceive.RemoveAt(giftPackagesToReceive.Count - 1);
			}
		}
		receiveGiftsCoroutine = null;
	}

	private void PlayCelebrateEffect(Vector3 giftPosition)
	{
		StopCelebrateEffect();
		GiftBox.OnLocalGiftBoxOpened = (Action<GiftBox>)Delegate.Combine(GiftBox.OnLocalGiftBoxOpened, new Action<GiftBox>(OnLocalGiftBoxOpened));
		celebrateEffectCoroutine = StartCoroutine(RunCelebrateEffect(giftPosition));
	}

	private void StopCelebrateEffect()
	{
		if (celebrateEffectCoroutine != null)
		{
			StopCoroutine(celebrateEffectCoroutine);
		}
	}

	private void OnLocalGiftBoxOpened(GiftBox giftBox)
	{
		GiftBox.OnLocalGiftBoxOpened = (Action<GiftBox>)Delegate.Remove(GiftBox.OnLocalGiftBoxOpened, new Action<GiftBox>(OnLocalGiftBoxOpened));
		Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(SingletonMonoBehaviour<GiftManager>.Instance);
		if (celebrationNotification != null)
		{
			celebrationNotification.Stop();
		}
	}

	private IEnumerator RunCelebrateEffect(Vector3 giftPosition)
	{
		yield return new WaitForSeconds(1f);
		if (!SingletonMonoBehaviour<CurrencyManager>.Instance.IsCurrencyRewardRunning)
		{
			Vector3 notificationPosition = giftPosition + Player.LocalPlayer.LastSpawnRotation * Vector3.forward * 0.5f;
			notificationPosition.y = Player.LocalPlayer.Head.transform.position.y;
			Quaternion rotation = Quaternion.LookRotation(Player.LocalPlayer.Head.transform.position - notificationPosition, Vector3.up);
			celebrationNotification = WorldSpaceNotification.PlayNext("You've got\na package!", 5f, null, followPlayer: false, notificationPosition, 1f, billboard: true);
			AudioManager.Play3DSFX(celebrationGiftAudio, notificationPosition);
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(SingletonMonoBehaviour<GiftManager>.Instance);
			if (celebrateParticlePrefab != null)
			{
				for (int i = 0; i < 3; i++)
				{
					PooledParticle effect = ObjectPool.Instance.Acquire(celebrateParticlePrefab);
					if (effect != null)
					{
						effect.Play(notificationPosition + rotation * (i % 2 * Vector3.right) * celebrateParticleSpacing, rotation);
					}
					yield return new WaitForSeconds(1f);
				}
			}
		}
		else
		{
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(SingletonMonoBehaviour<GiftManager>.Instance);
		}
		GiftBox.OnLocalGiftBoxOpened = (Action<GiftBox>)Delegate.Remove(GiftBox.OnLocalGiftBoxOpened, new Action<GiftBox>(OnLocalGiftBoxOpened));
		celebrateEffectCoroutine = null;
	}

	public float GetGiftSpawnHeight(Player player)
	{
		float currentFloorHeightFromHead = player.CurrentFloorHeightFromHead;
		float y = player.Head.transform.position.y;
		return Mathf.Lerp(minGiftHeight, maxGiftHeight, Mathf.Clamp01((currentFloorHeightFromHead - minPlayerHeight) / playerHeightRange)) + (y - currentFloorHeightFromHead);
	}

	public IEnumerator DequeueGift(Avatars.GiftPackage currentGiftPackage, Vector3 boxPosition, Quaternion boxRotation, Func<Avatars.GiftPackage, bool> createPackageFilter, float closeToPlayerDistance = 2.2f, Action<GiftBox> onGiftBoxDestroyed = null)
	{
		if (currentGiftPackage == null || currentGiftPackage.Consumed)
		{
			yield break;
		}
		Dictionary<string, object> instantiationData = new Dictionary<string, object>
		{
			{
				"Owner",
				PhotonNetwork.player.ID
			},
			{
				"GiftJSON",
				AmplitudeMiniJSON.Json.Serialize(currentGiftPackage.Serialize())
			}
		};
		GiftBox giftPrefab = currentGiftPackage.PackageVariant.prefab;
		bool canCreatePackage = createPackageFilter(currentGiftPackage);
		if (giftPrefab != null && canCreatePackage)
		{
			lastGiftBoxObject = PhotonNetwork.InstantiateEx(giftPrefab.name, boxPosition, boxRotation, giftPrefab.transform.localScale.x, 0, -1, instantiationData).GetComponent<GiftBox>();
			lastGiftBoxObject.spawnPosition = boxPosition;
			lastGiftBoxObject.CloseToPlayerDistance = closeToPlayerDistance;
			lastGiftBoxObject.OnGiftBoxDestroyed = onGiftBoxDestroyed;
		}
		else
		{
			onGiftBoxDestroyed.DoIfNotNull(delegate(Action<GiftBox> _)
			{
				_(null);
			});
		}
		if (currentGiftPackage.PackageVariant.dequeueBehavior == GiftPackageVariant.DequeueBehaviors.WaitUntilOpenedOrPlayerMoved)
		{
			while (lastGiftBoxObject != null && lastGiftBoxObject.CloseToPlayer)
			{
				yield return null;
			}
			if (lastGiftBoxObject != null)
			{
				PhotonNetwork.Destroy(lastGiftBoxObject.gameObject);
			}
		}
		else if (currentGiftPackage.PackageVariant.dequeueBehavior == GiftPackageVariant.DequeueBehaviors.ConsumeImmediately)
		{
			StartCoroutine(RunConsumeGift(currentGiftPackage, delegate
			{
			}));
		}
	}

	public IEnumerator RunConsumeGift(Avatars.GiftPackage giftPackage, GiftConsumedCallback callback)
	{
		if (giftPackage != null && !giftPackage.Consumed)
		{
			string error = string.Empty;
			yield return Avatars.LocalConsumeGiftPackage(giftPackage, delegate(string e)
			{
				error = e;
			});
			callback(string.IsNullOrEmpty(error));
			if (!string.IsNullOrEmpty(error))
			{
				UnityEngine.Debug.LogError("Server failed to consume gift " + giftPackage.Id + " : " + error);
			}
			else if (NetworkedSingletonMonoBehaviour<OutfitManager>.Instance != null && giftPackage.HasAvatarItem)
			{
				NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.AddAvatarItemToUnlockedList(giftPackage.AvatarItemDesc, giftPackage.Level);
			}
			else if (NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance != null && giftPackage.HasEquipment)
			{
				NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.UpdateUnlockedEquipmentsFor(giftPackage.EquipmentPrefabName, giftPackage.EquipmentModificationGuid, giftPackage.Level);
			}
		}
		else
		{
			callback(successful: false);
			UnityEngine.Debug.LogError("Unable to consume missing or used gift.");
		}
	}

	public bool IsEquipmentUnlockedOnCurrentPlatform(string equipmentModificationGuid)
	{
		return Avatars.GiftPackages.Any((Avatars.GiftPackage g) => g.SupportsCurrentPlatform && g.HasEquipment && g.EquipmentModificationGuid == equipmentModificationGuid);
	}

	public bool IsOutfitUnlockedOnCurrentPlatform(string avatarItemDesc)
	{
		return Avatars.GiftPackages.Any((Avatars.GiftPackage g) => g.SupportsCurrentPlatform && g.HasAvatarItem && g.AvatarItemDesc == avatarItemDesc);
	}
}
