public class GiftPackageVariantMap : ScriptableObject
{
	[SerializeField]
	private GiftPackageVariant defaultVariant;

	[SerializeField]
	private Material defaultGiftBoxMaterial;

	[SerializeField]
	private GiftPackageVariant[] variants;

	public Material DefaultGiftBoxMaterial => defaultGiftBoxMaterial;

	public GiftPackageVariant GetPackageVariantByContext(GiftManager.GiftContext context, out GiftPackageVariant.GiftContextMapping giftContextMap)
	{
		giftContextMap = null;
		GiftPackageVariant[] array = variants;
		foreach (GiftPackageVariant giftPackageVariant in array)
		{
			if (giftPackageVariant.giftContextMappings == null || giftPackageVariant.giftContextMappings.Length <= 0)
			{
				continue;
			}
			GiftPackageVariant.GiftContextMapping[] giftContextMappings = giftPackageVariant.giftContextMappings;
			foreach (GiftPackageVariant.GiftContextMapping giftContextMapping in giftContextMappings)
			{
				if (giftContextMapping.context == context)
				{
					giftContextMap = giftContextMapping;
					return giftPackageVariant;
				}
			}
		}
		return defaultVariant;
	}
}
public class GlowRarityController : RarityController
{
	[SerializeField]
	private Renderer myRenderer;

	public override void SetRarity(GiftManager.GiftRarity rarity)
	{
		if (myRenderer != null)
		{
			Color glowColor = SingletonMonoBehaviour<GiftManager>.Instance.RarityColorMap.GetGlowColor(rarity, myRenderer.material.GetColor("_TintColor"));
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			myRenderer.GetPropertyBlock(materialPropertyBlock);
			materialPropertyBlock.SetColor("_TintColor", glowColor);
			myRenderer.SetPropertyBlock(materialPropertyBlock);
		}
	}
}
public class RarityColorMap : ScriptableObject
{
	[Serializable]
	private struct RarityColorMapping
	{
		public GiftManager.GiftRarity GiftRarity;

		public Color GlowColor;
	}

	[SerializeField]
	private RarityColorMapping[] rarityColorMappings;

	public Color GetGlowColor(GiftManager.GiftRarity rarity, Color defaultColor)
	{
		for (int i = 0; i < rarityColorMappings.Length; i++)
		{
			if (rarityColorMappings[i].GiftRarity == rarity)
			{
				return rarityColorMappings[i].GlowColor;
			}
		}
		return defaultColor;
	}
}
