public class StampRarityController : RarityController
{
	[SerializeField]
	private GameObject[] stamps = new GameObject[0];

	public override void SetRarity(GiftManager.GiftRarity rarity)
	{
		int num = (int)rarity / 10;
		for (int i = 0; i < stamps.Length; i++)
		{
			bool active = rarity != GiftManager.GiftRarity.None && (i <= num || rarity == GiftManager.GiftRarity.Legendary);
			stamps[i].SetActive(active);
		}
	}
}
public class HileManager : SingletonMonoBehaviour<HileManager>
{
	protected override void OnDestroy()
	{
		base.OnDestroy();
		SceneManager.sceneLoaded -= OnSceneLoaded;
	}

	private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
	{
		if (RecRoomSceneManager.IsCurrentSceneAValidActivity)
		{
			if (!InjectionDetector.Instance.IsDetectorRunning)
			{
				InjectionDetector.StartDetection();
			}
			if (GameSessions.LocalGameSession != null && GameSessions.LocalGameSession.Location != RoomSceneLocations.DORM_ROOM)
			{
				CheckIfCheatEngineIsRunning();
			}
		}
	}

	private void CheckIfCheatEngineIsRunning()
	{
		Process[] processes = Process.GetProcesses();
		foreach (Process process in processes)
		{
			string text = process.ProcessName.ToLower();
			if (text.Contains("cheat") && text.Contains("engine"))
			{
				OnCheatEngineDetected();
			}
		}
	}

	private void OnCheatEngineDetected()
	{
		PlayerReporting.CreateHileWarning(PlayerReporting.HileType.Engine, string.Empty);
		AnalyticsHelper.CheatEngineRunning();
		HandleCheater();
	}

	public void OnInjectionDetected()
	{
		PlayerReporting.CreateHileWarning(PlayerReporting.HileType.Inject, string.Empty);
		AnalyticsHelper.InjectionDetected();
		HandleCheater();
	}

	private void HandleCheater(string warningMessage = "Something went wrong. Please restart RecRoom.")
	{
		UnityEngine.Debug.LogWarning(warningMessage);
		if (GameSessions.LocalGameSession.Location != RoomSceneLocations.DORM_ROOM)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.BootLocalPlayerToDormRoom(warningMessage, SessionManager.LoadSceneSources.AFK);
		}
	}
}
