	public struct Button
	{
		public bool Pressed;

		public bool Down;

		public bool Up;

		public static Button ReadKey(KeyCode key)
		{
			return new Button
			{
				Pressed = Input.GetKey(key),
				Down = Input.GetKeyDown(key),
				Up = Input.GetKeyUp(key)
			};
		}

		public static Button ReadKey(KeyCode[] keys)
		{
			Button result = default(Button);
			foreach (KeyCode key in keys)
			{
				result.Pressed |= Input.GetKey(key);
				result.Down |= Input.GetKeyDown(key);
				result.Up |= Input.GetKeyUp(key);
			}
			return result;
		}

		public static Button ReadInput(string name)
		{
			return new Button
			{
				Pressed = Input.GetButton(name),
				Down = Input.GetButtonDown(name),
				Up = Input.GetButtonUp(name)
			};
		}

		public static Button ReadMouseButton(int key)
		{
			if (key == -1)
			{
				return default(Button);
			}
			return new Button
			{
				Pressed = Input.GetMouseButton(key),
				Down = Input.GetMouseButtonDown(key),
				Up = Input.GetMouseButtonUp(key)
			};
		}

		public static Button ReadAxisButton(AxisButtons axisButtons, AxisButtons.Direction direction)
		{
			return new Button
			{
				Pressed = axisButtons.GetPressed(direction),
				Down = axisButtons.GetDown(direction),
				Up = axisButtons.GetUp(direction)
			};
		}

		public static Button ReadHairTriggerButton(HairTriggerButton hairTriggerButton)
		{
			return new Button
			{
				Pressed = hairTriggerButton.HairTriggerPressed,
				Down = hairTriggerButton.HairTriggerDown,
				Up = hairTriggerButton.HairTriggerUp
			};
		}
	}
	public struct Axis
	{
		public float Value;

		public float Deadzone;

		public bool InDeadzone => Mathf.Abs(Value) < Deadzone;

		public bool ValueAsBool
		{
			get
			{
				return Value > 0.5f;
			}
			set
			{
				Value = (value ? 1 : 0);
			}
		}

		public static Axis ReadAxis(string axisName, float deadzone)
		{
			return new Axis
			{
				Deadzone = deadzone,
				Value = Input.GetAxis(axisName)
			};
		}

		public static Axis ReadAxisUnsigned(string axisName, float deadzone)
		{
			return new Axis
			{
				Deadzone = deadzone,
				Value = Mathf.Abs(Input.GetAxis(axisName))
			};
		}
	}
	public class DiscreteButtonAxis
	{
		public float ReadAxis(Button positiveButton, Button negativeButton)
		{
			return CombineAxis(positiveButton.Pressed, negativeButton.Pressed);
		}

		public float ReadAxis(KeyCode positiveButton, KeyCode negativeButton)
		{
			return CombineAxis(Input.GetKey(positiveButton), Input.GetKey(negativeButton));
		}

		private float CombineAxis(bool positivePressed, bool negativePressed)
		{
			float num = 0f;
			if (positivePressed)
			{
				num += 1f;
			}
			if (negativePressed)
			{
				num -= 1f;
			}
			return num;
		}
	}
	[Serializable]
	public class Axis2DSettings
	{
		private enum DeadzoneType
		{
			RADIAL,
			AXIAL
		}

		[SerializeField]
		private readonly DeadzoneType deadzoneType;

		[SerializeField]
		[FormerlySerializedAs("innerRadialDeadzone")]
		private float innerDeadzone = 0.2f;

		[SerializeField]
		[FormerlySerializedAs("outerRadialDeadzone")]
		private float outerDeadzone = 0.97f;

		[SerializeField]
		private AnimationCurve inputCurve;

		public Vector2 ProcessValue(Vector2 rawValue)
		{
			if (deadzoneType == DeadzoneType.RADIAL)
			{
				float sqrMagnitude = rawValue.sqrMagnitude;
				if (sqrMagnitude <= innerDeadzone * innerDeadzone)
				{
					return Vector2.zero;
				}
				float magnitude = rawValue.magnitude;
				Vector2 vector = rawValue / magnitude;
				float num = Mathf.InverseLerp(innerDeadzone, outerDeadzone, magnitude);
				if (inputCurve != null && inputCurve.length > 0)
				{
					num = inputCurve.Evaluate(num);
				}
				return vector * num;
			}
			Vector2 zero = Vector2.zero;
			float num2 = Mathf.InverseLerp(innerDeadzone, outerDeadzone, Mathf.Abs(rawValue.x));
			if (num2 > 0f)
			{
				zero.x = Mathf.Sign(rawValue.x) * inputCurve.Evaluate(num2);
			}
			float num3 = Mathf.InverseLerp(innerDeadzone, outerDeadzone, Mathf.Abs(rawValue.y));
			if (num3 > 0f)
			{
				zero.y = Mathf.Sign(rawValue.y) * inputCurve.Evaluate(num3);
			}
			return zero;
		}
	}
	[Serializable]
	public class AxisSettings
	{
		[SerializeField]
		private float deadzone = 0.2f;

		[SerializeField]
		private float topDeadzone = 0.97f;

		[SerializeField]
		private AnimationCurve inputCurve;

		public float ProcessValue(float rawValue)
		{
			if (rawValue <= deadzone)
			{
				return 0f;
			}
			float num = Mathf.InverseLerp(deadzone, topDeadzone, rawValue);
			if (inputCurve != null && inputCurve.length > 0)
			{
				num = inputCurve.Evaluate(num);
			}
			return num;
		}

		public static float ProcessValue(float rawValue, AxisSettings settings)
		{
			return settings?.ProcessValue(rawValue) ?? rawValue;
		}
	}
}
namespace RecRoom.Systems
{
	public class InputManager : SingletonMonoBehaviour<InputManager>
	{
		public enum VRInputMode
		{
			Off,
			Debug,
			SteamVR_Vive,
			SteamVR_Oculus,
			SteamVR_WindowsMR,
			Oculus,
			PS4_Move,
			WindowsMR
		}

		public enum ScreenInputMode
		{
			Off,
			PC,
			PS4_DualShock
		}

		[Serializable]
		private class VRConfiguration
		{
			public VRInputMode InputMode;

			public VRInputConfiguration InputConfiguration;
		}

		[Serializable]
		private class ScreenConfiguration
		{
			public ScreenInputMode InputMode;

			public ScreenInputConfiguration InputConfiguration;
		}

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_VRInputHandlersChangedEvent;

		[SerializeField]
		[FormerlySerializedAs("configurations")]
		private VRConfiguration[] vrConfigurations;

		[SerializeField]
		private ScreenConfiguration[] screenConfigurations;

		private VRInputConfiguration activeVRLeftHandConfiguration;

		private VRInputHandler activeVRLeftHandHandler;

		private VRInputHandler activeVRRightHandHandler;

		private VRInputConfiguration activeVRRightHandConfiguration;

		private ScreenInputHandler activeScreenHandler;

		public VRInputMode VRMode { get; private set; }

		public ScreenInputMode ScreenMode { get; private set; }

		public bool ScreenUsingKeyboardMouse => activeScreenHandler != null && activeScreenHandler.UsingKeyboardMouse;

		public VRInputHandler LeftHandVRInputHandler => activeVRLeftHandHandler;

		public VRInputHandler RightHandVRInputHandler => activeVRRightHandHandler;

		public ScreenInputHandler ScreenInputHandler => activeScreenHandler;

		public event Action VRInputHandlersChangedEvent
		{
			add
			{
				Action action = this.m_VRInputHandlersChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_VRInputHandlersChangedEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_VRInputHandlersChangedEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_VRInputHandlersChangedEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			VRMode = GetVRInputMode();
			ScreenMode = GetScreenInputMode();
		}

		private void Start()
		{
			UpdateVRInputHandlers(force: true);
			SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareTypeChanged += UpdateVRInputHandlers;
			activeScreenHandler = InitializeScreenInputHandler(ScreenMode);
			activeScreenHandler.Attach();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CleanupVRInputHandlers();
			if (activeScreenHandler != null)
			{
				activeScreenHandler.Detach();
				activeScreenHandler = null;
			}
			if (SingletonMonoBehaviour<PlatformManager>.Instance != null)
			{
				SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareTypeChanged -= UpdateVRInputHandlers;
			}
		}

		private void Update()
		{
			if (activeVRLeftHandHandler != null)
			{
				activeVRLeftHandHandler.UpdateState();
			}
			if (activeVRRightHandHandler != null)
			{
				activeVRRightHandHandler.UpdateState();
			}
			if (activeScreenHandler != null)
			{
				activeScreenHandler.UpdateState();
			}
		}

		private void UpdateVRInputHandlers()
		{
			UpdateVRInputHandlers(force: false);
		}

		private void UpdateVRInputHandlers(bool force)
		{
			VRInputMode vRMode = VRMode;
			VRMode = GetVRInputMode();
			if (VRMode != vRMode || force)
			{
				CleanupVRInputHandlers();
				activeVRLeftHandHandler = InitializeVRInputHandler(VRMode, VRTrackedController.HandType.LeftHand, out activeVRLeftHandConfiguration);
				activeVRLeftHandHandler.Attach();
				activeVRRightHandHandler = InitializeVRInputHandler(VRMode, VRTrackedController.HandType.RightHand, out activeVRRightHandConfiguration);
				activeVRRightHandHandler.Attach();
				if (this.VRInputHandlersChangedEvent != null)
				{
					this.VRInputHandlersChangedEvent();
				}
			}
		}

		private VRInputHandler InitializeVRInputHandler(VRInputMode inputMode, VRTrackedController.HandType handType, out VRInputConfiguration configurationInstance)
		{
			configurationInstance = null;
			if (inputMode == VRInputMode.Off)
			{
				return VRInputHandler.Empty;
			}
			for (int i = 0; i < vrConfigurations.Length; i++)
			{
				if (vrConfigurations[i].InputMode == inputMode)
				{
					configurationInstance = UnityEngine.Object.Instantiate(vrConfigurations[i].InputConfiguration);
					break;
				}
			}
			if (configurationInstance != null)
			{
				VRInputHandler handler = configurationInstance.GetHandler(handType);
				handler.Initialize(handType, SingletonMonoBehaviour<CameraRig>.Instance.GetTrackedController(handType));
				return handler;
			}
			UnityEngine.Debug.LogError("InputManager.GetVRInputHandler(): Unhandled InputMode: " + inputMode);
			return VRInputHandler.Empty;
		}

		private void CleanupVRInputHandlers()
		{
			if (activeVRLeftHandHandler != null)
			{
				activeVRLeftHandHandler.Detach();
				activeVRLeftHandHandler = null;
			}
			if (activeVRLeftHandConfiguration != null)
			{
				UnityEngine.Object.Destroy(activeVRLeftHandConfiguration);
				activeVRLeftHandConfiguration = null;
			}
			if (activeVRRightHandHandler != null)
			{
				activeVRRightHandHandler.Detach();
				activeVRRightHandHandler = null;
			}
			if (activeVRRightHandConfiguration != null)
			{
				UnityEngine.Object.Destroy(activeVRRightHandConfiguration);
				activeVRRightHandConfiguration = null;
			}
		}

		public ScreenInputHandler InitializeScreenInputHandler(ScreenInputMode inputMode)
		{
			ScreenInputConfiguration screenInputConfiguration = null;
			for (int i = 0; i < screenConfigurations.Length; i++)
			{
				if (screenConfigurations[i].InputMode == inputMode)
				{
					screenInputConfiguration = UnityEngine.Object.Instantiate(screenConfigurations[i].InputConfiguration);
					break;
				}
			}
			if (screenInputConfiguration != null)
			{
				return screenInputConfiguration.GetHandler();
			}
			UnityEngine.Debug.LogError("InputManager.GetScreenInputHandler(): Unhandled InputMode: " + inputMode);
			return ScreenInputHandler.Empty;
		}

		private VRInputMode GetVRInputMode()
		{
			if (SingletonMonoBehaviour<PlatformManager>.Instance != null)
			{
				switch (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform)
				{
				case PlatformManager.PlatformType.Oculus:
					return VRInputMode.Oculus;
				case PlatformManager.PlatformType.PlayStation:
					return VRInputMode.PS4_Move;
				case PlatformManager.PlatformType.Microsoft:
					return VRInputMode.WindowsMR;
				case PlatformManager.PlatformType.Steam:
					return SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareType switch
					{
						PlatformManager.HardwareType.DESKTOP_NO_VR => VRInputMode.Off, 
						PlatformManager.HardwareType.OCULUS => VRInputMode.SteamVR_Oculus, 
						PlatformManager.HardwareType.MICROSOFT_VR => VRInputMode.SteamVR_WindowsMR, 
						_ => VRInputMode.SteamVR_Vive, 
					};
				}
			}
			return VRInputMode.Off;
		}

		private ScreenInputMode GetScreenInputMode()
		{
			if (SingletonMonoBehaviour<PlatformManager>.Instance != null)
			{
				PlatformManager.PlatformType currentPlatform = SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform;
				if (currentPlatform == PlatformManager.PlatformType.PlayStation)
				{
					return ScreenInputMode.PS4_DualShock;
				}
			}
			return ScreenInputMode.PC;
		}
	}
}
