public class ManagedSingletonObject : UnityEngine.MonoBehaviour, IGameSingleton
{
	public static Dictionary<string, ManagedSingletonObject> managedObjects = new Dictionary<string, ManagedSingletonObject>();

	[SerializeField]
	private string guid;

	[SerializeField]
	private GameRestartBehaviors gameRestartBehavior = GameRestartBehaviors.DestroyOld;

	public GameRestartBehaviors GameRestartBehavior => gameRestartBehavior;

	public GameObject GameObject => base.gameObject;

	private void Awake()
	{
		if (managedObjects.ContainsKey(guid))
		{
			if (GameRestartBehavior == GameRestartBehaviors.DestroyNew)
			{
				UnityEngine.Object.Destroy(base.gameObject);
				return;
			}
			ManagedSingletonObject managedSingletonObject = managedObjects[guid];
			if (GameRestartBehavior == GameRestartBehaviors.DestroyOld)
			{
				UnityEngine.Object.Destroy(managedSingletonObject.GameObject);
				managedObjects.Remove(guid);
			}
		}
		managedObjects.Add(guid, this);
		GameRoot.AddExistingSingleton(this);
	}

	private void OnDestroy()
	{
		managedObjects.Remove(guid);
		GameRoot.ExistingGameSingletons.Remove(this);
	}
}
public class ModerationManager : SingletonMonoBehaviour<ModerationManager>
{
	[Serializable]
	public class ReportReasonVisual
	{
		public string text;

		public PlayerReporting.ReportCategory reason;
	}

	[Serializable]
	public class CheerCategoryVisual
	{
		public string text;

		public PlayerCheering.CheerCategory cheerCategory;

		public Color color;
	}

	[Tooltip("How long should we keep the current votes towards a kick? (in seconds)")]
	[SerializeField]
	private float vtkActiveDuration = 30f;

	[Header("Vote kick reason visuals")]
	[SerializeField]
	private List<ReportReasonVisual> reportReasonVisuals;

	[Header("Cheer category visuals")]
	[SerializeField]
	private List<CheerCategoryVisual> cheerCategoryVisuals;

	public float VtkActiveDuration => vtkActiveDuration;

	public ReportReasonVisual GetReportReasonVisual(PlayerReporting.ReportCategory reason)
	{
		foreach (ReportReasonVisual reportReasonVisual in reportReasonVisuals)
		{
			if (reportReasonVisual.reason == reason)
			{
				return reportReasonVisual;
			}
		}
		return null;
	}

	public string GetCheerCategoryText(PlayerCheering.CheerCategory cheerCategory)
	{
		foreach (CheerCategoryVisual cheerCategoryVisual in cheerCategoryVisuals)
		{
			if (cheerCategoryVisual.cheerCategory == cheerCategory)
			{
				return cheerCategoryVisual.text;
			}
		}
		return string.Empty;
	}

	public CheerCategoryVisual GetCheerCategoryVisual(PlayerCheering.CheerCategory cheerCategory)
	{
		foreach (CheerCategoryVisual cheerCategoryVisual in cheerCategoryVisuals)
		{
			if (cheerCategoryVisual.cheerCategory == cheerCategory)
			{
				return cheerCategoryVisual;
			}
		}
		return null;
	}

	public static string GetBannedText()
	{
		float unscaledTime = UnityEngine.Time.unscaledTime;
		ReportReasonVisual reportReasonVisual = SingletonMonoBehaviour<ModerationManager>.Instance.GetReportReasonVisual(PlayerReporting.CurrentBlockDetail.ReportCategory);
		string text = ((reportReasonVisual == null) ? "Misc" : reportReasonVisual.text);
		string message = PlayerReporting.CurrentBlockDetail.Message;
		string arg = (string.IsNullOrEmpty(message) ? ("You are currently blocked for " + text) : message);
		int duration = PlayerReporting.CurrentBlockDetail.Duration;
		int seconds = Mathf.CeilToInt((float)duration - (UnityEngine.Time.unscaledTime - unscaledTime));
		return $"{arg}.\n\nYour ban ends in \n{SecondsToString(seconds)}";
	}

	private static string SecondsToString(int seconds)
	{
		TimeSpan timeSpan = TimeSpan.FromSeconds(seconds);
		StringBuilder stringBuilder = new StringBuilder();
		if (timeSpan.Days >= 1)
		{
			stringBuilder.Append($"{timeSpan.Days:D2} Days ");
		}
		else if (timeSpan.Hours >= 1)
		{
			stringBuilder.Append($"{timeSpan.Hours:D2} Hours");
		}
		else if (timeSpan.Minutes >= 1)
		{
			stringBuilder.Append($"{timeSpan.Minutes:D2} Minutes");
		}
		else
		{
			stringBuilder.Append($"{timeSpan.Seconds:D2} Seconds");
		}
		return stringBuilder.ToString();
	}
}
