public class OOBEFlowBase : UnityEngine.MonoBehaviour
{
	protected struct CancellationData
	{
		public UnityEngine.MonoBehaviour runningBehavior;

		public IEnumerator enumeratorRunning;
	}

	public class InterruptableFlow : CustomYieldInstruction
	{
		public enum FlowState
		{
			Incomplete,
			Complete,
			Fail,
			Timeout
		}

		public bool Complete { get; set; }

		public override bool keepWaiting => !Complete;
	}

	protected List<Renderer> highlightedRenderers = new List<Renderer>();

	private bool isShowingPersistentNotification;

	private List<CancellationData> coroutinesToCancel = new List<CancellationData>();

	private float lastStateTime;

	private InterruptableFlow.FlowState lastStateResult;

	private AudioSource sourceToStop;

	private void Update()
	{
		for (int i = 0; i < highlightedRenderers.Count; i++)
		{
			OutlineEffectRenderer.RenderTutorialOutline(highlightedRenderers[i]);
		}
	}

	protected virtual void OnDestroy()
	{
		if (isShowingPersistentNotification)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
		}
	}

	protected IEnumerator CancelableCoroutine(IEnumerator enumerator)
	{
		return CancelableCoroutine(this, enumerator);
	}

	protected IEnumerator CancelableCoroutine(UnityEngine.MonoBehaviour runner, IEnumerator enumerator)
	{
		CancellationData item = new CancellationData
		{
			runningBehavior = runner,
			enumeratorRunning = enumerator
		};
		coroutinesToCancel.Add(item);
		return enumerator;
	}

	public void CleanUp()
	{
		for (int i = 0; i < coroutinesToCancel.Count; i++)
		{
			UnityEngine.MonoBehaviour runningBehavior = coroutinesToCancel[i].runningBehavior;
			IEnumerator enumeratorRunning = coroutinesToCancel[i].enumeratorRunning;
			runningBehavior.StopCoroutine(enumeratorRunning);
		}
		InternalCleanUp();
	}

	protected virtual void InternalCleanUp()
	{
		Player.LocalPlayer.RemoveToolInteractionRestriction(this);
	}

	protected virtual IEnumerator RunTeleportTrail(Transform[] locations, TeleportTarget teleportTargetToUse, RecRoomAudioClip initialAudio, RecRoomAudioClip repeatingAudio = null, int maxRetries = 3, bool suppressHelpPopup = false, bool helpToRight = true)
	{
		teleportTargetToUse.gameObject.SetActive(value: true);
		for (int i = 0; i < locations.Length; i++)
		{
			teleportTargetToUse.gameObject.transform.position = locations[i].position;
			teleportTargetToUse.gameObject.transform.rotation = locations[i].rotation;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
			{
				yield return CancelableCoroutine(RunTeleportTutorial(teleportTargetToUse, (i != 0) ? null : initialAudio, repeatingAudio, maxRetries, suppressHelpPopup, helpToRight));
			}
			else
			{
				yield return CancelableCoroutine(RunWalkTutorial(teleportTargetToUse, (i != 0) ? null : initialAudio, repeatingAudio, maxRetries, suppressHelpPopup, helpToRight));
			}
		}
		teleportTargetToUse.gameObject.SetActive(value: false);
	}

	protected virtual IEnumerator RunTeleportTutorial(TeleportTarget teleportTarget, RecRoomAudioClip initialAudio, RecRoomAudioClip repeatingAudio = null, int maxRetries = 3, bool suppressHelpPopup = false, bool helpToRight = true)
	{
		Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		VibrateBothHands(Player.LocalPlayer);
		HelpPopup popup = SingletonMonoBehaviour<TutorialManager>.Instance.ShowHelpPopup(TutorialManager.HelpType.TeleportButton, helpToRight);
		if (suppressHelpPopup)
		{
			popup.Active = false;
		}
		Player.LocalPlayer.PlayerLocomotion.TeleportEvent += teleportTarget.OnPlayerTeleported;
		bool playerTeleported = false;
		teleportTarget.gameObject.SetActive(value: true);
		teleportTarget.PlayerTeleportedEvent = delegate(bool inRegion)
		{
			if (inRegion)
			{
				playerTeleported = true;
			}
		};
		yield return CancelableCoroutine(RunInterruptableFlow(() => playerTeleported ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, initialAudio, repeatingAudio, delegate(InterruptableFlow.FlowState result)
		{
			popup.Active = false;
			teleportTarget.gameObject.SetActive(value: false);
			SetNUXStateResult(result);
		}, 15f, maxRetries, "PlayerTeleported"));
		Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= teleportTarget.OnPlayerTeleported;
	}

	protected virtual IEnumerator RunWalkTutorial(TeleportTarget teleportTarget, RecRoomAudioClip initialAudio, RecRoomAudioClip repeatingAudio = null, int maxRetries = 3, bool suppressHelpPopup = false, bool helpToRight = true)
	{
		Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		VibrateBothHands(Player.LocalPlayer);
		ShowHelpPopup(TutorialManager.HelpType.WalkButton);
		if (suppressHelpPopup)
		{
			HideHelpPopup();
		}
		bool playerWalked = false;
		Action onPlayerWalkedToTarget = delegate
		{
			playerWalked = true;
		};
		Collider collider = teleportTarget.GetComponentInChildren<Collider>();
		if (collider != null)
		{
			collider.SetEnabled(enabled: false);
		}
		teleportTarget.gameObject.SetActive(value: true);
		teleportTarget.AllowWalk = true;
		TeleportTarget teleportTarget2 = teleportTarget;
		teleportTarget2.PlayerWalkedToTargetEvent = (Action)Delegate.Combine(teleportTarget2.PlayerWalkedToTargetEvent, onPlayerWalkedToTarget);
		StartCoroutine(teleportTarget.RunCheckForPlayerWalkToTarget(Player.LocalPlayer));
		yield return CancelableCoroutine(RunInterruptableFlow(() => playerWalked ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, initialAudio, repeatingAudio, delegate(InterruptableFlow.FlowState result)
		{
			HideHelpPopup();
			teleportTarget.gameObject.SetActive(value: false);
			if (collider != null)
			{
				collider.SetEnabled(enabled: true);
			}
			SetNUXStateResult(result);
		}, 15f, maxRetries, "PlayerWalked"));
		TeleportTarget teleportTarget3 = teleportTarget;
		teleportTarget3.PlayerWalkedToTargetEvent = (Action)Delegate.Remove(teleportTarget3.PlayerWalkedToTargetEvent, onPlayerWalkedToTarget);
	}

	protected void StartNUXState()
	{
		lastStateTime = UnityEngine.Time.time;
		lastStateResult = InterruptableFlow.FlowState.Incomplete;
	}

	protected void SetNUXStateResult(InterruptableFlow.FlowState stateResult)
	{
		lastStateResult = stateResult;
	}

	protected void FinishNUXState()
	{
		FinishNUXState(lastStateResult);
	}

	protected void FinishNUXState(InterruptableFlow.FlowState stateResult)
	{
		lastStateTime = UnityEngine.Time.time - lastStateTime;
		lastStateResult = stateResult;
		AnalyticsHelper.NUXStepCompleted(SingletonMonoBehaviour<TutorialManager>.Instance.NUXState, lastStateTime, lastStateResult);
	}

	protected IEnumerator RunWaitForPlayerSpawn(float showErrorDelay = 20f)
	{
		float timeStarted = UnityEngine.Time.realtimeSinceStartup;
		while (!Player.LocalPlayerExists || !Player.LocalPlayer.IsInitialized)
		{
			if (!isShowingPersistentNotification && showErrorDelay >= 0f && UnityEngine.Time.realtimeSinceStartup - timeStarted > showErrorDelay)
			{
				isShowingPersistentNotification = true;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.AddPersistentNotification("An unexpected error occurred", "Error code FROSTBITE. Please contact support@againstgrav.com", this);
				UnityEngine.Debug.LogError("OOBEFlowBase.RunWaitForPlayerSpawn(): Error code FROSTBITE");
			}
			yield return null;
		}
		if (isShowingPersistentNotification)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
			isShowingPersistentNotification = false;
		}
	}

	protected IEnumerator RunWaitForUserIsPresent()
	{
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode && !SingletonMonoBehaviour<VRDeviceManager>.Instance.UserInHMD)
		{
			isShowingPersistentNotification = true;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.AddPersistentNotification("Please put on your VR headset", this);
			while (!SingletonMonoBehaviour<VRDeviceManager>.Instance.UserInHMD)
			{
				yield return null;
			}
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.RemovePersistentNotification(this);
			isShowingPersistentNotification = false;
		}
	}

	protected InterruptableFlow RunInterruptableFlow(Func<InterruptableFlow.FlowState> condition, Action<InterruptableFlow.FlowState> onComplete = null, float helpInterval = 15f, int maxHelpCount = 3, string debugString = "")
	{
		return (InterruptableFlow)CancelableCoroutine(RunInterruptableFlow(condition, null, () => (RecRoomAudioClip)null, onComplete, helpInterval, maxHelpCount, debugString));
	}

	protected InterruptableFlow RunInterruptableFlow(Func<InterruptableFlow.FlowState> condition, RecRoomAudioClip initialHelpVO, RecRoomAudioClip repeatingHelp, Action<InterruptableFlow.FlowState> onComplete = null, float helpInterval = 15f, int maxHelpCount = 3, string debugString = "")
	{
		return (InterruptableFlow)CancelableCoroutine(RunInterruptableFlow(condition, initialHelpVO, () => repeatingHelp, onComplete, helpInterval, maxHelpCount, debugString));
	}

	protected InterruptableFlow RunInterruptableFlow(Func<InterruptableFlow.FlowState> condition, RecRoomAudioClip initialHelpVO, Func<RecRoomAudioClip> repeatingHelp, Action<InterruptableFlow.FlowState> onComplete = null, float helpInterval = 15f, int maxHelpCount = 3, string debugString = "")
	{
		InterruptableFlow flow = new InterruptableFlow();
		Coroutine waitRoutine = null;
		Coroutine repeatingHelpVORoutine = null;
		if (initialHelpVO != null)
		{
			sourceToStop = SingletonMonoBehaviour<TutorialManager>.Instance.PlayVO(initialHelpVO);
		}
		Action<InterruptableFlow.FlowState> action = onComplete;
		onComplete = delegate
		{
			sourceToStop.DoIfNotNull(delegate(AudioSource s)
			{
				s.Stop();
			});
			repeatingHelpVORoutine.DoIfNotNull(delegate(Coroutine r)
			{
				StopCoroutine(r);
			});
			waitRoutine.DoIfNotNull(delegate(Coroutine r)
			{
				StopCoroutine(r);
			});
			flow.Complete = true;
		};
		if (action != null)
		{
			onComplete = (Action<InterruptableFlow.FlowState>)Delegate.Combine(onComplete, action);
		}
		TutorialManager instance = SingletonMonoBehaviour<TutorialManager>.Instance;
		waitRoutine = instance.StartCoroutine(CancelableCoroutine(instance, WaitForCondition(condition, onComplete)));
		if (repeatingHelp != null && waitRoutine != null)
		{
			repeatingHelpVORoutine = instance.StartCoroutine(CancelableCoroutine(instance, PlayRepeatingVO(repeatingHelp, helpInterval, maxHelpCount, delegate
			{
				waitRoutine.DoIfNotNull(delegate(Coroutine r)
				{
					StopCoroutine(r);
				});
				onComplete(InterruptableFlow.FlowState.Timeout);
			}, helpInterval)));
		}
		return flow;
	}

	private IEnumerator WaitForCondition(Func<InterruptableFlow.FlowState> condition, Action<InterruptableFlow.FlowState> onComplete)
	{
		while (condition() == InterruptableFlow.FlowState.Incomplete)
		{
			yield return null;
		}
		onComplete(condition());
	}

	private IEnumerator PlayRepeatingVO(Func<RecRoomAudioClip> repeatingHelp, float helpInterval, int maxTries, Action onTimedOut, float timeBetweenInitialAndRepeating = 1.5f)
	{
		int tries = 0;
		if (sourceToStop != null && sourceToStop.clip != null)
		{
			yield return new WaitUntil(() => !sourceToStop.isPlaying);
		}
		yield return new WaitForSecondsRealtime(timeBetweenInitialAndRepeating);
		bool firstLoop = true;
		while (maxTries < 0 || tries++ < maxTries)
		{
			if (!firstLoop)
			{
				yield return new WaitForSecondsRealtime(helpInterval);
			}
			firstLoop = false;
			RecRoomAudioClip helpAudio = repeatingHelp();
			if (helpAudio != null)
			{
				sourceToStop = SingletonMonoBehaviour<TutorialManager>.Instance.PlayVO(repeatingHelp());
				yield return new WaitUntil(() => !sourceToStop.isPlaying);
			}
		}
		UnityEngine.Debug.Log("User didn't complete action in time. Timing out");
		onTimedOut();
	}

	protected void VibrateBothHands(Player player)
	{
		if (player.LeftHand != null)
		{
			player.LeftHand.Vibrate(500);
		}
		if (player.RightHand != null)
		{
			player.RightHand.Vibrate(500);
		}
	}

	protected IEnumerator RunAnimateInOut(AnimateInOut target, bool enable)
	{
		target.gameObject.SetActive(enable);
		yield return new WaitForSeconds(1f);
	}

	protected virtual IEnumerator RunWaitUntilPlayerOpensMenuNoTimeout(Action<InterruptableFlow.FlowState> onComplete, bool playInitialVO = true)
	{
		yield return CancelableCoroutine(RunInterruptableFlow(initialHelpVO: (!playInitialVO) ? null : SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.OpenWatch), repeatingHelp: SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(SingletonMonoBehaviour<TutorialManager>.Instance.GetInputSpecificVOType(TutorialManager.TutorialAudioType.LookAtWristToViewWatch)), condition: () => Player.LocalPlayer.PlayerUI.WatchMenu.FullyVisible ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, onComplete: onComplete, helpInterval: 15f, maxHelpCount: -1, debugString: "WaitUntilPlayerOpensMenuNoTimeout"));
	}

	protected virtual IEnumerator RunWaitUntilPlayerOpensMenuPageNoTimeout(StackedUIFlowBase targetPage, RecRoomAudioClip targetPageHelpAudio, Action<InterruptableFlow.FlowState> onComplete)
	{
		yield return CancelableCoroutine(RunWaitUntilPlayerPerformsWatchActionNoTimeout(() => targetPage.IsCurrentFlow ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, targetPageHelpAudio, onComplete));
	}

	protected virtual IEnumerator RunWaitUntilPlayerPerformsWatchActionNoTimeout(Func<InterruptableFlow.FlowState> condition, RecRoomAudioClip targetPageHelpAudio, Action<InterruptableFlow.FlowState> onComplete)
	{
		RecRoomAudioClip howToOpenMenuAudio = SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.LookAtWristToViewWatch);
		Func<RecRoomAudioClip> currentWatchMenuTutorialAudio = () => (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen) ? howToOpenMenuAudio : targetPageHelpAudio;
		ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
		HideHelpPopup();
		Func<InterruptableFlow.FlowState> openedMenuCheck = delegate
		{
			if (Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
			{
				HideHelpPopup();
				return condition();
			}
			ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
			return InterruptableFlow.FlowState.Incomplete;
		};
		yield return CancelableCoroutine(RunInterruptableFlow(openedMenuCheck, targetPageHelpAudio, currentWatchMenuTutorialAudio, delegate
		{
		}, 15f, -1, string.Empty));
	}

	protected void ShowHelpPopup(TutorialManager.HelpType helpType)
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.ShowScreensHelpPopup(helpType);
		}
		else
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.ShowHelpPopup(helpType);
		}
	}

	protected void HideHelpPopup()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance.ScreensModeNUXEnabled)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.HideScreensHelpPopup();
		}
		else
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.HideHelpPopup();
		}
	}
}
