	public static class CustomPlayerLoopInjector
	{
		private delegate List<PlayerLoopSystem> WrapSystem(List<PlayerLoopSystem> systems, int subsystemIndex);

		[StructLayout((LayoutKind)0, Size = 1)]
		public struct CustomSystems
		{
			[StructLayout((LayoutKind)0, Size = 1)]
			public struct PostUpdateSystem
			{
				[CompilerGenerated]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				private static Action m_OnPostUpdate;

				public static event Action OnPostUpdate
				{
					add
					{
						Action action = PostUpdateSystem.m_OnPostUpdate;
						Action action2;
						do
						{
							action2 = action;
							action = Interlocked.CompareExchange(ref PostUpdateSystem.m_OnPostUpdate, (Action)Delegate.Combine(action2, value), action);
						}
						while (action != action2);
					}
					remove
					{
						Action action = PostUpdateSystem.m_OnPostUpdate;
						Action action2;
						do
						{
							action2 = action;
							action = Interlocked.CompareExchange(ref PostUpdateSystem.m_OnPostUpdate, (Action)Delegate.Remove(action2, value), action);
