			[StructLayout((LayoutKind)0, Size = 1)]
			public struct PreRenderSystem
			{
				[CompilerGenerated]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				private static Action m_OnPreRenderUpdate;

				public static event Action OnPreRenderUpdate
				{
					add
					{
