		private static bool _injected;

		public static bool Injected
		{
			get
			{
				return _injected;
			}
			private set
			{
				_injected = value;
			}
		}

		[RuntimeInitializeOnLoadMethod]
		private static void AppStart()
		{
			PlayerLoopSystem playerLoop = PlayerLoop.GetDefaultPlayerLoop();
			TryInsertSystems(ref playerLoop, typeof(Update), typeof(Update.ScriptRunBehaviourUpdate), null, CustomSystems.PostUpdateSystem.CreateSystem());
			TryInsertSystems(ref playerLoop, typeof(PreLateUpdate), typeof(PreLateUpdate.ScriptRunBehaviourLateUpdate), CustomSystems.RigidbodyExLateUpdateSystem.CreateSystem(), CustomSystems.PreRenderSystem.CreateSystem());
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.PhysicsUpdate, ref playerLoop, typeof(PreUpdate), typeof(PreUpdate.PhysicsUpdate));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.Update, ref playerLoop, typeof(Update), typeof(Update.ScriptRunBehaviourUpdate));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.PostUpdate, ref playerLoop, typeof(Update), typeof(CustomSystems.PostUpdateSystem));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.PhysicsFixedUpdate, ref playerLoop, typeof(FixedUpdate), typeof(FixedUpdate.PhysicsFixedUpdate));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.FixedUpdate, ref playerLoop, typeof(FixedUpdate), typeof(FixedUpdate.ScriptRunBehaviourFixedUpdate));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.RigidbodyExLateUpdate, ref playerLoop, typeof(PreLateUpdate), typeof(CustomSystems.RigidbodyExLateUpdateSystem));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.LateUpdate, ref playerLoop, typeof(PreLateUpdate), typeof(PreLateUpdate.ScriptRunBehaviourLateUpdate));
			TryTimerWrapSubSystem(TimerAnalytics.WrapperKey.PreRenderUpdate, ref playerLoop, typeof(PreLateUpdate), typeof(CustomSystems.PreRenderSystem));
			PlayerLoop.SetPlayerLoop(playerLoop);
			Injected = true;
		}

		private static void TryTimerWrapSubSystem(TimerAnalytics.WrapperKey key, ref PlayerLoopSystem playerLoop, System.Type parentSystemType, System.Type subSystemType)
		{
			TimerAnalytics.CreateWrapper(key);
			PlayerLoopSystem newSystem = CustomSystems.WrapperPreSystem.GetNewSystem(key);
			PlayerLoopSystem newSystem2 = CustomSystems.WrapperPostSystem.GetNewSystem(key);
			TryInsertSystems(ref playerLoop, parentSystemType, subSystemType, newSystem, newSystem2);
		}

		private static void TryInjectAroundSystem(ref PlayerLoopSystem playerLoop, System.Type parentSystemType, System.Type subSystemType, WrapSystem wrapSystem)
		{
			try
			{
				PlayerLoopSystem playerLoopSystem = default(PlayerLoopSystem);
				PlayerLoopSystem[] subSystemList = playerLoop.subSystemList;
				int num = -1;
				for (int i = 0; i < subSystemList.Length; i++)
				{
					PlayerLoopSystem playerLoopSystem2 = subSystemList[i];
					if (playerLoopSystem2.type == parentSystemType)
					{
						playerLoopSystem = playerLoopSystem2;
						num = i;
						break;
					}
				}
				if (num < 0)
				{
					throw new InvalidOperationException($"No parent system of specified type {parentSystemType} was found!");
				}
				PlayerLoopSystem[] subSystemList2 = playerLoopSystem.subSystemList;
				int num2 = -1;
				for (int j = 0; j < subSystemList2.Length; j++)
				{
					PlayerLoopSystem playerLoopSystem3 = subSystemList2[j];
					if (playerLoopSystem3.type == subSystemType)
					{
						num2 = j;
						break;
					}
				}
				if (num2 < 0)
				{
					throw new InvalidOperationException($"No subsystem of specified type {subSystemType} was found!");
				}
				List<PlayerLoopSystem> systems = new List<PlayerLoopSystem>(playerLoopSystem.subSystemList);
				systems = wrapSystem(systems, num2);
				playerLoopSystem.subSystemList = systems.ToArray();
				playerLoop.subSystemList[num] = playerLoopSystem;
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}

		private static void TryInsertSystems(ref PlayerLoopSystem playerLoop, System.Type parentSystemType, System.Type subSystemType, PlayerLoopSystem? before, PlayerLoopSystem? after)
		{
			TryInjectAroundSystem(ref playerLoop, parentSystemType, subSystemType, delegate(List<PlayerLoopSystem> newSubsystemList, int subSystemIndex)
			{
				if (after.HasValue)
				{
					newSubsystemList.Insert(subSystemIndex + 1, after.Value);
				}
				if (before.HasValue)
				{
					newSubsystemList.Insert(subSystemIndex, before.Value);
				}
				return newSubsystemList;
			});
		}
	}
	public static class TimerAnalytics
	{
		public enum WrapperKey
		{
			Update,
			SchedulerUpdate,
			PostUpdate,
			FixedUpdate,
			RigidbodyExLateUpdate,
			LateUpdate,
			PreRenderUpdate,
			PhysicsFixedUpdate,
			PhysicsUpdate
		}

		public class CallWrapper
		{
			public readonly WrapperKey WrapperKey;

			private Stopwatch stopwatch = Stopwatch.StartNew();

			public readonly RollingBufferAverageStats AverageStats;

			private long startTicks;

			private long endTicks;

			public CallWrapper(WrapperKey wrapperKey, int bufferSize = 90)
			{
				WrapperKey = wrapperKey;
				AverageStats = new RollingBufferAverageStats(bufferSize);
				SceneManager.sceneLoaded += ResetTimer;
			}

			public void SetBufferLength(int bufferLength)
			{
				AverageStats.MaxBufferLength = bufferLength;
			}

			private void ResetTimer(Scene newScene, LoadSceneMode loadSceneMode)
			{
				if (newScene.name == "empty")
				{
					stopwatch = Stopwatch.StartNew();
					AverageStats.Reset();
				}
			}

			public void RegisterStart()
			{
				startTicks = stopwatch.ElapsedTicks;
			}

			public void RegisterEnd()
			{
				endTicks = stopwatch.ElapsedTicks;
				long num = endTicks - startTicks;
				AverageStats.Track(num);
			}
		}

		public const int DEFAULT_BUFFER_SIZE = 90;

		public static WrapperKey[] WrapperKeys = (WrapperKey[])System.Enum.GetValues(typeof(WrapperKey));

		private static CallWrapper[] _callWrappers = new CallWrapper[WrapperKeys.Length];

		public static CallWrapper CreateWrapper(WrapperKey key, int bufferSize = 90)
		{
			CallWrapper callWrapper = new CallWrapper(key, bufferSize);
			_callWrappers[(int)key] = callWrapper;
			return callWrapper;
		}

		public static CallWrapper GetWrapper(WrapperKey key)
		{
			return _callWrappers[(int)key];
		}
	}
}
public class PlayerEventNotificationManager : SingletonMonoBehaviour<PlayerEventNotificationManager>
{
	public class PlayerEventInfo
	{
		public string Name;

		public DateTime StartTime;

		public long PlayerEventId;
	}

	private DateTime lastTimeNotified;

	private DateTime? nextEventNotificationTime;

	public Queue<PlayerEventInfo> UnprocessedNotifications = new Queue<PlayerEventInfo>();

	private Coroutine EventTimerCoroutine;

	public void Initialize()
	{
		RecNet.PlayerEvents.PlayerEventStateChanged += OnEventStateChanged;
		RecNet.PlayerEvents.PlayerEventUpdated += OnEventChanged;
		RecNet.PlayerEvents.PlayerEventDeleted += OnEventChanged;
		RecNet.PlayerEvents.PlayerEventResponseChanged += OnEventResponseChanged;
		RecNet.PlayerEvents.PlayerEventResponseDeleted += OnEventResponseChanged;
		lastTimeNotified = DateTime.UtcNow;
		UpdateEventTimer();
	}

	protected override void OnDestroy()
	{
		RecNet.PlayerEvents.PlayerEventStateChanged -= OnEventStateChanged;
		RecNet.PlayerEvents.PlayerEventUpdated -= OnEventChanged;
		RecNet.PlayerEvents.PlayerEventDeleted -= OnEventChanged;
		RecNet.PlayerEvents.PlayerEventResponseChanged -= OnEventResponseChanged;
		RecNet.PlayerEvents.PlayerEventResponseDeleted -= OnEventResponseChanged;
		base.OnDestroy();
	}

	private IEnumerator CheckEventsForNotifications()
	{
		DateTime? dateTime = nextEventNotificationTime;
		if (!dateTime.HasValue)
		{
			yield break;
		}
		float secondsToWait = (float)(nextEventNotificationTime.Value - DateTime.UtcNow).TotalSeconds + 30f;
		yield return new WaitForSecondsRealtime(secondsToWait);
		ReadOnlyCollection<PlayerEventInformation> upcomingEvents = RecNet.PlayerEvents.UpcomingEvents;
		if (upcomingEvents != null && upcomingEvents.Count > 0)
		{
			DateTime utcNow = DateTime.UtcNow;
			for (int i = 0; i < upcomingEvents.Count; i++)
			{
				DateTime startTime = upcomingEvents[i].PlayerEvent.StartTime;
				if (startTime > lastTimeNotified && startTime <= utcNow && upcomingEvents[i].PlayerEventResponse.Type != PlayerEventResponseType.No)
				{
					UnprocessedNotifications.Enqueue(new PlayerEventInfo
					{
						Name = upcomingEvents[i].PlayerEvent.Name,
						StartTime = upcomingEvents[i].PlayerEvent.StartTime,
						PlayerEventId = upcomingEvents[i].PlayerEvent.PlayerEventId
					});
				}
			}
		}
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.ProcessPlayerEventNotifications();
		}
		yield return null;
		UpdateEventTimer();
	}

	private void OnEventChanged(PlayerEvent changedEvent)
	{
		UpdateEventTimer();
	}

	private void OnEventStateChanged(PlayerEvent changedEvent)
	{
		SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = "The event you were in got shut down.";
	}

	private void OnEventResponseChanged(PlayerEvent changedEvent, PlayerEventResponse newResponse)
	{
		UpdateEventTimer();
	}

	private void UpdateEventTimer()
	{
		nextEventNotificationTime = null;
		ReadOnlyCollection<PlayerEventInformation> upcomingEvents = RecNet.PlayerEvents.UpcomingEvents;
		if (upcomingEvents != null && upcomingEvents.Count > 0)
		{
			DateTime utcNow = DateTime.UtcNow;
			for (int i = 0; i < upcomingEvents.Count; i++)
			{
				if (upcomingEvents[i].PlayerEvent.StartTime > utcNow)
				{
					nextEventNotificationTime = upcomingEvents[i].PlayerEvent.StartTime;
					break;
				}
			}
		}
		if (EventTimerCoroutine != null)
		{
			StopCoroutine(EventTimerCoroutine);
			EventTimerCoroutine = null;
		}
		DateTime? dateTime = nextEventNotificationTime;
		if (dateTime.HasValue)
		{
			EventTimerCoroutine = StartCoroutine(CheckEventsForNotifications());
		}
	}
}
public class PlayerFollowCameraManager : Photon.MonoBehaviour
{
	[SerializeField]
	private UIPlayerCamera uIPlayerCameraPrefab;

	[SerializeField]
	private Vector2 uiCameraResolutionOverride = new Vector2(320f, 270f);

	[SerializeField]
	private PlayerFollowCameraTV[] screens;

	[SerializeField]
	private Texture emptyTexture;

	private List<UIPlayerCamera> uIPlayerCameras = new List<UIPlayerCamera>();

	private int activeCameraIndex;

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
	}

	private void Start()
	{
		for (int i = 0; i < screens.Length; i++)
		{
			UIPlayerCamera uIPlayerCamera = UnityEngine.Object.Instantiate(uIPlayerCameraPrefab);
			uIPlayerCamera.Resolution = uiCameraResolutionOverride;
			uIPlayerCameras.Add(uIPlayerCamera);
			screens[i].ClearScreen(emptyTexture);
		}
		Canvas[] componentsInChildren = GetComponentsInChildren<Canvas>(includeInactive: true);
		foreach (Canvas canvas in componentsInChildren)
		{
			canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
		}
		Invoke("ReAssignCameras", 1f);
		Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Player.PlayerCreatedEvent -= new Action<Player>(OnRecRoomPlayerCreated);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
	}

	private void Update()
	{
		for (int i = 0; i < uIPlayerCameras.Count; i++)
		{
			uIPlayerCameras[i].Camera.gameObject.SetActive(i == activeCameraIndex);
		}
		activeCameraIndex = (activeCameraIndex + 1) % uIPlayerCameras.Count;
	}

	private void ReAssignCameras()
	{
		int i;
		for (i = 0; i < PhotonNetwork.playerList.Length; i++)
		{
			screens[i].SetupCamera(PhotonNetwork.playerList[i].TagObject as Player, uIPlayerCameras[i]);
		}
		for (; i < screens.Length; i++)
		{
			screens[i].ClearScreen(emptyTexture);
		}
	}

	private void OnRecRoomPlayerCreated(Player newPlayer)
	{
		ReAssignCameras();
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer otherPlayer)
	{
		if (base.isActiveAndEnabled)
		{
			ReAssignCameras();
		}
	}
}
public class PlayerFollowCameraTV : UnityEngine.MonoBehaviour
{
	public Text PlayerNameText;

	public Transform UIRoot;

	public TeleportationPortal TeleportationPortal;

	public Renderer TargetRenderer;

	public bool IsActive => UIPlayerCamera != null && UIPlayerCamera.IsActive;

	public UIPlayerCamera UIPlayerCamera { get; private set; }

	private void Awake()
	{
		ClearScreen();
	}

	public void SetupCamera(Player player, UIPlayerCamera uIPlayerCamera)
	{
		UIPlayerCamera = uIPlayerCamera;
		UIPlayerCamera.Setup(player, TargetRenderer, TeleportationPortal, UIRoot);
		PlayerNameText.text = ((!(player != null)) ? string.Empty : player.PlayerName);
	}

	public void ClearScreen(Texture emptyTexture = null)
	{
		TargetRenderer.material.mainTexture = emptyTexture;
		TeleportationPortal.gameObject.SetActive(value: false);
		UIRoot.gameObject.SetActive(value: false);
		if (UIPlayerCamera != null)
		{
			UIPlayerCamera.Setup(null);
			UIPlayerCamera = null;
		}
	}

	[SkipRename]
	public void Button_ToggleFollowCameraMode()
	{
		if (UIPlayerCamera != null)
		{
			UIPlayerCamera.CycleFollowMode();
		}
	}
}
