		public GameRole()
			: this(GameRoleId.AG_EVERYONE)
		{
		}

		public GameRole(GameRoleId role, GameRole roleToCopy = null, string roleName = null)
		{
			if (roleToCopy != null)
			{
				rank = roleToCopy.RoleRank;
				Copy(roleToCopy);
			}
			else
			{
				rank = RoleRankHelper.GetRankForGameRole(role);
			}
			RoleId = role;
			if (!string.IsNullOrEmpty(roleName))
			{
				RoleName = roleName;
			}
		}

		public void AddOnRolePermissionUpdatedCallback(OnRolePermissionUpdatedCallback<RolePermission> callback)
		{
			OnRolePermissionUpdated = (OnRolePermissionUpdatedCallback<RolePermission>)Delegate.Combine(OnRolePermissionUpdated, callback);
		}

		public void RemoveOnRolePermissionUpdatedCallback(OnRolePermissionUpdatedCallback<RolePermission> callback)
		{
			OnRolePermissionUpdated = (OnRolePermissionUpdatedCallback<RolePermission>)Delegate.Remove(OnRolePermissionUpdated, callback);
		}

		public void Reset()
		{
			IsModifiedByPlayer = false;
			teleportDelay.Reset();
			canMove.Reset();
			vrWalkSpeed.Reset();
			vrCanSprint.Reset();
			vrSprintSpeedMultiplier.Reset();
			vrCanDualWield.Reset();
			vrCanJump.Reset();
			vrCanDodge.Reset();
			screensDefaultControlType.Reset();
			screensWalkSpeed.Reset();
			screensCanSprint.Reset();
			screensSprintSpeedMultiplier.Reset();
			screensCanJump.Reset();
			screensCanDodge.Reset();
			maxTeleportDistance.Reset();
			maxTeleportDropHeight.Reset();
			maxTeleportAngle.Reset();
			canFly.Reset();
			isInvincible.Reset();
			itemPickupRestrictions.Reset();
			itemPickupWhitelist.Reset();
			itemPickupBlacklist.Reset();
			canSwitchTeams.Reset();
			voiceRolloffMaxDistance.Reset();
			hidesName.Reset();
			enableEquipSlotHip.Reset();
			equipRestrictionsHip.Reset();
			equipHipWhitelist.Reset();
			equipHipBlacklist.Reset();
			equipRestrictionsShoulder.Reset();
			equipShoulderWhitelist.Reset();
			equipShoulderBlacklist.Reset();
		}

		public GameRole CombineWith(GameRole otherRole)
		{
			RoleRank = otherRole.RoleRank;
			if (otherRole.RoleId == GameRoleId.AG_EVERYONE)
			{
				RoleId = GameRoleId.AG_EVERYONE;
			}
			else
			{
				RoleId |= otherRole.RoleId;
			}
			IsModifiedByPlayer |= otherRole.IsModifiedByPlayer;
			teleportDelay.CombineWith(otherRole.teleportDelay);
			canMove.CombineWith(otherRole.canMove);
			vrWalkSpeed.CombineWith(otherRole.vrWalkSpeed);
			vrCanSprint.CombineWith(otherRole.vrCanSprint);
			vrSprintSpeedMultiplier.CombineWith(otherRole.vrSprintSpeedMultiplier);
			vrCanDualWield.CombineWith(otherRole.vrCanDualWield);
			vrCanJump.CombineWith(otherRole.vrCanJump);
			vrCanDodge.CombineWith(otherRole.vrCanDodge);
			screensDefaultControlType.CombineWith(otherRole.screensDefaultControlType);
			screensWalkSpeed.CombineWith(otherRole.screensWalkSpeed);
			screensCanSprint.CombineWith(otherRole.screensCanSprint);
			screensSprintSpeedMultiplier.CombineWith(otherRole.screensSprintSpeedMultiplier);
			screensCanJump.CombineWith(otherRole.screensCanJump);
			screensCanDodge.CombineWith(otherRole.screensCanDodge);
			maxTeleportDistance.CombineWith(otherRole.maxTeleportDistance);
			maxTeleportDropHeight.CombineWith(otherRole.maxTeleportDropHeight);
			maxTeleportAngle.CombineWith(otherRole.maxTeleportAngle);
			canFly.CombineWith(otherRole.canFly);
			isInvincible.CombineWith(otherRole.isInvincible);
			itemPickupRestrictions.CombineWith(otherRole.itemPickupRestrictions);
			itemPickupWhitelist.CombineWith(otherRole.itemPickupWhitelist);
			itemPickupBlacklist.CombineWith(otherRole.itemPickupBlacklist);
			canSwitchTeams.CombineWith(otherRole.canSwitchTeams);
			voiceRolloffMaxDistance.CombineWith(otherRole.voiceRolloffMaxDistance);
			hidesName.CombineWith(otherRole.hidesName);
			enableEquipSlotHip.CombineWith(otherRole.enableEquipSlotHip);
			equipRestrictionsHip.CombineWith(otherRole.equipRestrictionsHip);
			equipHipWhitelist.CombineWith(otherRole.equipHipWhitelist);
			equipHipBlacklist.CombineWith(otherRole.equipHipBlacklist);
			equipRestrictionsShoulder.CombineWith(otherRole.equipRestrictionsShoulder);
			equipShoulderWhitelist.CombineWith(otherRole.equipShoulderWhitelist);
			equipShoulderBlacklist.CombineWith(otherRole.equipShoulderBlacklist);
			return this;
		}

