		public void ApplyRoleModification(RolePermission rolePermission, byte[] permissionUpdate)
		{
			switch (rolePermission)
			{
			case RolePermission.TELEPORT_DELAY:
				teleportDelay.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_MOVE:
				canMove.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_WALK_SPEED:
				vrWalkSpeed.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_CAN_SPRINT:
				vrCanSprint.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_SPRINT_SPEED_MULTIPLIER:
				vrSprintSpeedMultiplier.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_CAN_DUAL_WIELD:
				vrCanDualWield.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_CAN_JUMP:
				vrCanJump.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VR_CAN_DODGE:
				vrCanDodge.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_DEFAULT_CONTROL_TYPE:
				screensDefaultControlType.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_WALK_SPEED:
				screensWalkSpeed.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_CAN_SPRINT:
				screensCanSprint.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_SPRINT_SPEED_MULTIPLIER:
				screensSprintSpeedMultiplier.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_CAN_JUMP:
				screensCanJump.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.SCREENS_CAN_DODGE:
				screensCanDodge.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.MAX_TELEPORT_DISTANCE:
				maxTeleportDistance.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.MAX_TELEPORT_DROP_HEIGHT:
				maxTeleportDropHeight.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.MAX_TELEPORT_ANGLE:
				maxTeleportAngle.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_FLY:
				canFly.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.IS_INVINCIBLE:
				isInvincible.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.ITEM_PICKUP_RESTRICTIONS:
				itemPickupRestrictions.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.ITEM_PICKUP_WHITELIST:
				itemPickupWhitelist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.ITEM_PICKUP_BLACKLIST:
				itemPickupBlacklist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_SWITCH_TEAMS:
				canSwitchTeams.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VOICE_ROLLOFF_MAX_DISTANCE:
				voiceRolloffMaxDistance.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.HIDES_NAME:
				hidesName.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.ENABLE_EQUIP_SLOT_HIP:
				enableEquipSlotHip.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_RESTRICTIONS_HIP:
				equipRestrictionsHip.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_HIP_WHITELIST:
				equipHipWhitelist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_HIP_BLACKLIST:
				equipHipBlacklist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_RESTRICTIONS_SHOULDER:
				equipRestrictionsShoulder.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_SHOULDER_WHITELIST:
				equipShoulderWhitelist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.EQUIP_SHOULDER_BLACKLIST:
				equipShoulderBlacklist.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			default:
				throw new InvalidOperationException("Unknown RolePermission " + rolePermission);
			}
			IsModifiedByPlayer = true;
			if (OnRolePermissionUpdated != null)
			{
				OnRolePermissionUpdated(rolePermission, GetFieldFor(rolePermission));
			}
		}

