namespace RecRoom.Systems.PlayerRoles.UI.Game
{
	public class AddGameRoleConditionalButton : ConditionalButton<Button3D>
	{
		private enum ButtonStates
		{
			Disabled,
			Enabled_Active,
			Enabled_Inactive
		}

		[SerializeField]
		private EditGameRoleOrdersWatchUIFlow editGameRoleOrdersScreen;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tooltip tooltip;

		protected override void OnEnable()
		{
			base.OnEnable();
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			editGameRoleOrdersScreen.OnRoleViewModeChangedEvent += OnRoleViewModeChanged;
		}

		private void OnDisable()
		{
			UnregisterEvents();
		}

		private void OnDestroy()
		{
			UnregisterEvents();
		}

		private void UnregisterEvents()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			if (editGameRoleOrdersScreen != null)
			{
				editGameRoleOrdersScreen.OnRoleViewModeChangedEvent -= OnRoleViewModeChanged;
			}
		}

		private void OnRoleViewModeChanged(RoleViewMode newEditMode)
		{
			UpdateButton();
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer photonPlayer, RoomRole roleDef)
		{
			if (photonPlayer.IsLocal)
			{
				UpdateButton();
			}
		}

		protected override void RunButtonAction()
		{
			int num = base.ButtonState;
			if (num == 1)
			{
				editGameRoleOrdersScreen.Button_AddRole();
			}
		}

		protected override void UpdateButtonState()
		{
			GameRole nextRole;
			if (PlayerGameRoleManager.Instance == null || !PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value || editGameRoleOrdersScreen.RoleViewMode != RoleViewMode.Edit)
			{
				base.ButtonState = 0;
			}
			else if (PlayerGameRoleManager.Instance.PlayerCanCreateRole(PhotonNetwork.player, out nextRole))
			{
				base.ButtonState = 1;
			}
			else
			{
				base.ButtonState = 2;
			}
		}

		protected override bool IsInteractable()
		{
			return base.IsInteractable() && base.ButtonState == 1;
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			bool flag = base.ButtonState != 0;
			if (base.gameObject != null && flag != base.gameObject.activeSelf)
			{
				base.gameObject.SetActive(flag);
			}
		}
	}
