	public class EditGameRoleOrdersWatchUIFlow : WatchUIFlow
	{
		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		[SerializeField]
		private ToggleButton3D showOnlyMyRolesToggle;

		public GameRolePagedGrid grid;

		private bool hasOpened;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<RoleViewMode> m_OnRoleViewModeChangedEvent;

		private RoleViewMode _roleViewMode;

		public RoleViewMode RoleViewMode
		{
			get
			{
				return _roleViewMode;
			}
			set
			{
				RoleViewMode roleViewMode = value;
				if (roleViewMode == RoleViewMode.Edit && !PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value)
				{
					roleViewMode = RoleViewMode.View;
				}
				_roleViewMode = roleViewMode;
				grid.UpdateChildren(_roleViewMode, showOnlyMyRolesToggle.IsOn);
				this.OnRoleViewModeChangedEvent.SafeInvoke(_roleViewMode);
			}
		}

		public event Action<RoleViewMode> OnRoleViewModeChangedEvent
		{
			add
			{
				Action<RoleViewMode> action = this.m_OnRoleViewModeChangedEvent;
				Action<RoleViewMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnRoleViewModeChangedEvent, (Action<RoleViewMode>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<RoleViewMode> action = this.m_OnRoleViewModeChangedEvent;
				Action<RoleViewMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnRoleViewModeChangedEvent, (Action<RoleViewMode>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void Awake()
		{
			RolePermissionEditable[] componentsInChildren = GetComponentsInChildren<RolePermissionEditable>();
			RolePermissionEditable[] array = componentsInChildren;
			foreach (RolePermissionEditable rolePermissionEditable in array)
			{
				rolePermissionEditable.UpdateForPermissionType(RolePermissionTypes.Game);
			}
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			if (!hasOpened)
			{
				RoleViewMode = (PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value ? RoleViewMode.Edit : RoleViewMode.View);
				hasOpened = true;
			}
			else
			{
				grid.UpdateChildren();
			}
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
			OnPlayerRoomRoleDefinitionUpdated(PhotonNetwork.player, PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition());
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
		}

		private void OnPlayerRoomRoleDefinitionUpdated(PhotonPlayer player, RoomRole roleDef)
		{
			if (player.IsLocal && !roleDef.CanEditGameRoles.Value)
			{
				RoleViewMode = RoleViewMode.View;
			}
		}

		public void Toggle_ShowOnlyMyRoles()
		{
			grid.UpdateChildren(_roleViewMode, showOnlyMyRolesToggle.IsOn);
		}

		public void Button_AddRole()
		{
			IPromise<TextInputUIDialog.InputResponse> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.Standard, "New Role Name", "Enter the name of your new role.", "Create", purifyText: true, 40, null, shouldFocusInputField: false));
			promise.Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative)
				{
					string textInput = r.TextInput;
					if (!string.IsNullOrEmpty(textInput))
					{
						if (!(PlayerGameRoleManager.Instance == null))
						{
							GameRole gameRole = PlayerGameRoleManager.Instance.FindActiveRoleByName(textInput);
							if (gameRole == null)
							{
								PlayerGameRoleManager.Instance.LocalRequestCreateRole(textInput);
							}
							else
							{
								Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Role Name Taken!", "That role name is already taken.");
							}
						}
					}
					else
					{
						Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Invalid Role Name!", "Please enter a valid role name.");
					}
				}
			});
		}
	}
	public class EditGameRoleSettingsWatchUIFlow : WatchUIFlow
	{
		[SerializeField]
		private GameRoleId _roleId;

		private bool isDefaultRoleDefinition;

		private RoleViewMode _roleViewMode;

		[SerializeField]
		private RectTransform editableContainer;

		[SerializeField]
		private RolePermissionEditable whitelistedPickupItemsPermission;

		[SerializeField]
		private RolePermissionEditable blacklistedPickupItemsPermission;

		[SerializeField]
		private RolePermissionEditable whitelistedHipEquipItemsPermission;

		[SerializeField]
		private RolePermissionEditable blacklistedHipEquipItemsPermission;

		[SerializeField]
		private RolePermissionEditable whitelistedShoulderEquipItemsPermission;

		[SerializeField]
		private RolePermissionEditable blacklistedShoulderEquipItemsPermission;

		[SerializeField]
		private RadioButton3D sharedButton;

		private List<RolePermissionEditable> roleEditables = new List<RolePermissionEditable>();

		public void SetRoleId(GameRoleId roleId, RoleViewMode roleViewMode, bool isDefaultGameRoleDefinition)
		{
			_roleId = roleId;
			_roleViewMode = roleViewMode;
			isDefaultRoleDefinition = isDefaultGameRoleDefinition;
			OnRoleIdUpdated();
		}

		private void Awake()
		{
			RolePermissionEditable[] componentsInChildren = GetComponentsInChildren<RolePermissionEditable>();
			RolePermissionEditable[] array = componentsInChildren;
			foreach (RolePermissionEditable rolePermissionEditable in array)
			{
				rolePermissionEditable.UpdateForPermissionType(RolePermissionTypes.Game);
			}
			roleEditables.AddRange(GetComponentsInChildren<RolePermissionEditable>(includeInactive: true));
			sharedButton.IsCurrent = true;
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleDefinitionUpdatedEvent += new Action<GameRole>(OnRoleUpdated);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
			OnPlayerRoomRoleDefinitionUpdated(PhotonNetwork.player, PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition());
			OnRoleIdUpdated();
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleDefinitionUpdatedEvent -= new Action<GameRole>(OnRoleUpdated);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
		}

		private void OnPlayerRoomRoleDefinitionUpdated(PhotonPlayer player, RoomRole roleDef)
		{
			if (_roleViewMode == RoleViewMode.Edit && player.IsLocal && !roleDef.CanEditGameRoles.Value)
			{
				SetRoleId(_roleId, RoleViewMode.View, isDefaultRoleDefinition);
			}
		}

		private void OnRoleUpdated(GameRole newRoleDef)
		{
			if (newRoleDef.ItemPickupRestrictions.Overrides && newRoleDef.ItemPickupRestrictions.Value == RolePickupRestrictionType.Whitelist)
			{
				whitelistedPickupItemsPermission.Show(this);
			}
			else
			{
				whitelistedPickupItemsPermission.Hide(this);
			}
			if (newRoleDef.ItemPickupRestrictions.Overrides && newRoleDef.ItemPickupRestrictions.Value == RolePickupRestrictionType.Blacklist)
			{
				blacklistedPickupItemsPermission.Show(this);
			}
			else
			{
				blacklistedPickupItemsPermission.Hide(this);
			}
			if (newRoleDef.EnableEquipSlotHip.Value != HipEquipSlotEnableMode.ALL_DISABLED && newRoleDef.EquipRestrictionsHip.Overrides && newRoleDef.EquipRestrictionsHip.Value == RolePickupRestrictionType.Whitelist)
			{
				whitelistedHipEquipItemsPermission.Show(this);
			}
			else
			{
				whitelistedHipEquipItemsPermission.Hide(this);
			}
			if (newRoleDef.EnableEquipSlotHip.Value != HipEquipSlotEnableMode.ALL_DISABLED && newRoleDef.EquipRestrictionsHip.Overrides && newRoleDef.EquipRestrictionsHip.Value == RolePickupRestrictionType.Blacklist)
			{
				blacklistedHipEquipItemsPermission.Show(this);
			}
			else
			{
				blacklistedHipEquipItemsPermission.Hide(this);
			}
			if (newRoleDef.EquipRestrictionsShoulder.Overrides && newRoleDef.EquipRestrictionsShoulder.Value == RolePickupRestrictionType.Whitelist)
			{
				whitelistedShoulderEquipItemsPermission.Show(this);
			}
			else
			{
				whitelistedShoulderEquipItemsPermission.Hide(this);
			}
			if (newRoleDef.EquipRestrictionsShoulder.Overrides && newRoleDef.EquipRestrictionsShoulder.Value == RolePickupRestrictionType.Blacklist)
			{
				blacklistedShoulderEquipItemsPermission.Show(this);
			}
			else
			{
				blacklistedShoulderEquipItemsPermission.Hide(this);
			}
			SetTitleText(newRoleDef);
		}

		private void OnRoleIdUpdated()
		{
			for (int i = 0; i < roleEditables.Count; i++)
			{
				((IRolePermissionEditable<GameRoleId>)roleEditables[i]).SetRoleId(_roleId, _roleViewMode, isDefaultRoleDefinition);
			}
			GameRole gameRole = null;
			if (PlayerGameRoleManager.Instance != null)
			{
				gameRole = ((!isDefaultRoleDefinition) ? PlayerGameRoleManager.Instance.GetRoleDefinition(_roleId) : PlayerGameRoleManager.Instance.DefaultRoleDefinition);
				OnRoleUpdated(gameRole);
			}
			SetTitleText(gameRole);
		}

		private void SetTitleText(GameRole roleDef)
		{
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				string arg = "Invalid Role";
				if (roleDef != null)
				{
					arg = roleDef.RoleName;
				}
				componentInChildren.Title = string.Format("{0} {1}", (_roleViewMode != RoleViewMode.Edit || isDefaultRoleDefinition) ? "View" : "Edit", arg);
			}
		}
	}
