	public class GameRoleEditRow : UnityEngine.MonoBehaviour
	{
		private GameRole currentGameRole;

		[SerializeField]
		private TextMeshProUGUI text;

		[SerializeField]
		private Button3D moveUpButton;

		[SerializeField]
		private Button3D moveDownButton;

		[SerializeField]
		private Button3D settingsButton;

		[SerializeField]
		private Button3D deleteButton;

		[Header("Role Colors")]
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private UnityEngine.UI.Image bgImage;

		[SerializeField]
		private Color agRoleColor = Color.white;

		[SerializeField]
		private Color defaultRoleColor = Color.white;

		[SerializeField]
		private Color nonAGRoleColor = Color.white;

		[Header("Settings sprites")]
		[SerializeField]
		private UnityEngine.UI.Image settingsButtonImage;

		[SerializeField]
		private Sprite editRoleSprite;

		[SerializeField]
		private Sprite viewRoleSprite;

		private RoleViewMode _roleViewMode;

		private bool _isDefaultGameRoleDefinition;

		private void OnEnable()
		{
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent += new Action(OnRoleOrdersChanged);
		}

		private void OnDisable()
		{
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent -= new Action(OnRoleOrdersChanged);
		}

		private void OnRoleOrdersChanged()
		{
			UpdateButtons();
		}

		public void SetRole(GameRole item, int activeIndex, RoleViewMode roleViewMode, bool isDefaultGameRoleDefinition)
		{
			bool flag = PlayerGameRoleManager.Instance.IsPlayerDefinedRole(item.RoleId);
			_isDefaultGameRoleDefinition = isDefaultGameRoleDefinition;
			_roleViewMode = roleViewMode;
			currentGameRole = item;
			if (currentGameRole != null && text != null)
			{
				text.text = currentGameRole.RoleName;
			}
			Color color = (isDefaultGameRoleDefinition ? defaultRoleColor : ((!flag) ? agRoleColor : nonAGRoleColor));
			if (!isDefaultGameRoleDefinition && activeIndex % 2 == 0)
			{
				color *= 0.85f;
				color.a = 1f;
			}
			bgImage.color = color;
			UpdateButtons();
		}

		private void UpdateButtons()
		{
			bool flag = PlayerGameRoleManager.Instance.IsPlayerDefinedRole(currentGameRole.RoleId);
			bool flag2 = _roleViewMode == RoleViewMode.Edit;
			bool active = flag2 && flag;
			deleteButton.gameObject.SetActive(active);
			moveUpButton.gameObject.SetActive(active);
			moveDownButton.gameObject.SetActive(active);
			settingsButtonImage.sprite = (_isDefaultGameRoleDefinition ? viewRoleSprite : ((_roleViewMode != RoleViewMode.Edit) ? viewRoleSprite : editRoleSprite));
			deleteButton.Interactable = flag2 && currentGameRole != null && PlayerGameRoleManager.Instance.PlayerCanDeleteRole(currentGameRole.RoleId, PhotonNetwork.player);
			settingsButton.Interactable = currentGameRole != null && (!flag2 || PlayerGameRoleManager.Instance.PlayerCanModifyRoleDefinition(PhotonNetwork.player, currentGameRole.RoleId));
			moveUpButton.Interactable = flag2 && currentGameRole != null && PlayerGameRoleManager.Instance.CanMoveRole(PhotonNetwork.player, currentGameRole.RoleId, up: true, out var otherRole);
			moveDownButton.Interactable = flag2 && currentGameRole != null && PlayerGameRoleManager.Instance.CanMoveRole(PhotonNetwork.player, currentGameRole.RoleId, up: false, out otherRole);
		}

		public void Button_MoveUp()
		{
			PlayerGameRoleManager.Instance.PlayerRequestMoveRole(PhotonNetwork.player, currentGameRole.RoleId, up: true);
		}

		public void Button_MoveDown()
		{
			PlayerGameRoleManager.Instance.PlayerRequestMoveRole(PhotonNetwork.player, currentGameRole.RoleId, up: false);
		}

		public void Button_Settings()
		{
			EditGameRoleSettingsWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<EditGameRoleSettingsWatchUIFlow>();
			flowByType.SetRoleId(currentGameRole.RoleId, _roleViewMode, _isDefaultGameRoleDefinition);
			Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
		}

		public void Button_Remove()
		{
			IPromise<ConfirmDialogResponses> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Are you sure?", "Are you sure you want to remove the role \"" + currentGameRole.RoleName + "\"?");
			promise.Then(delegate(ConfirmDialogResponses r)
			{
				if (r == ConfirmDialogResponses.Affirmative)
				{
					PlayerGameRoleManager.Instance.LocalRequestDeleteRole(currentGameRole.RoleId);
				}
			});
		}
	}
	public class GameRolePagedGrid : RecyclerPagedGrid<GameRolePagedGrid.GameRoleUI, GameRoleEditRow>
	{
		public struct GameRoleUI
		{
			public GameRole CurrentGameRole;

			public bool IsDefaultGameRoleDefinition;
		}

		private RoleViewMode _roleViewMode;

		private bool _showOnlyMyRoles;

		private void OnEnable()
		{
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent += new Action(UpdateChildren);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, GameRole>(OnPlayerRolesUpdated);
			UpdateChildren();
		}

		private void OnDisable()
		{
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnRoleOrdersChangedEvent -= new Action(UpdateChildren);
			RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, GameRole>(OnPlayerRolesUpdated);
		}

		private void OnPlayerRolesUpdated(PhotonPlayer player, GameRole roleDef)
		{
			if (player.IsLocal && _showOnlyMyRoles)
			{
				UpdateChildren();
			}
		}

		public void UpdateChildren()
		{
			UpdateChildren(_roleViewMode, _showOnlyMyRoles);
		}

		public void UpdateChildren(RoleViewMode roleViewMode, bool showOnlyMyRoles)
		{
			_roleViewMode = roleViewMode;
			_showOnlyMyRoles = showOnlyMyRoles;
			if (PlayerGameRoleManager.Instance != null)
			{
				List<GameRoleUI> list = (_showOnlyMyRoles ? (from _ in PlayerGameRoleManager.Instance.GetSortedActiveRolesForPlayer(PhotonNetwork.player, reverseOrder: true)
					select new GameRoleUI
					{
						CurrentGameRole = _
					}).ToList() : (from _ in PlayerGameRoleManager.Instance.GetSortedActiveRoles(reverseOrder: true)
					select new GameRoleUI
					{
						CurrentGameRole = _
					}).ToList());
				list.Add(new GameRoleUI
				{
					CurrentGameRole = PlayerGameRoleManager.Instance.DefaultRoleDefinition,
					IsDefaultGameRoleDefinition = true
				});
				SetAllActiveChildren(list, resetPage: false);
			}
		}

		protected override void SetChild(GameRoleUI item, GameRoleEditRow uiElement, int activeIndex)
		{
			uiElement.SetRole(item.CurrentGameRole, activeIndex, _roleViewMode, item.IsDefaultGameRoleDefinition);
		}
	}
}
namespace RecRoom.Systems.PlayerRoles.UI
{
	public class GameRolePermissionsPagedGrid : PagedGrid<RolePermissionEditable>
	{
		private RolePermissionPlayerTypeCategory _currentPermissionCategory = RolePermissionPlayerTypeCategory.Shared;

		public RolePermissionPlayerTypeCategory CurrentPermissionCategory
		{
			get
			{
				return _currentPermissionCategory;
			}
			set
			{
				if (_currentPermissionCategory != value)
				{
					_currentPermissionCategory = value;
					UpdateActiveChildren();
				}
			}
		}

		private void Awake()
		{
			RefreshChildren(includeDisabled: true);
			UpdateActiveChildren();
			foreach (RolePermissionEditable allChild in AllChildren)
			{
				allChild.OnTokenFlagsUpdated = (Action)Delegate.Combine(allChild.OnTokenFlagsUpdated, new Action(UpdateActiveChildren));
			}
		}

		private void OnDestroy()
		{
			if (AllChildren == null)
			{
				return;
			}
			foreach (RolePermissionEditable allChild in AllChildren)
			{
				if (allChild != null)
				{
					allChild.OnTokenFlagsUpdated = (Action)Delegate.Remove(allChild.OnTokenFlagsUpdated, new Action(UpdateActiveChildren));
				}
			}
		}

		private void UpdateActiveChildren()
		{
			SetAllActiveChildren(AllChildren.Where((RolePermissionEditable _) => _.ShouldShow(CurrentPermissionCategory)), resetPage: false);
		}

		[Skip]
		public void Button_SetCategory_SHARED()
		{
			CurrentPermissionCategory = RolePermissionPlayerTypeCategory.Shared;
		}

		[Skip]
		public void Button_SetPlayerMode_VR_TELEPORT()
		{
			CurrentPermissionCategory = RolePermissionPlayerTypeCategory.VR_Teleport;
		}

		[Skip]
		public void Button_SetPlayerMode_VR_WALK()
		{
			CurrentPermissionCategory = RolePermissionPlayerTypeCategory.VR_Walk;
		}

		[Skip]
		public void Button_SetPlayerMode_SCREEN()
		{
			CurrentPermissionCategory = RolePermissionPlayerTypeCategory.Screens;
		}
	}
}
namespace RecRoom.Systems.PlayerRoles.UI.Game
{
	public class GameRolesConditionalButton : ConditionalButton<Button3D>
	{
		private enum RolesButtonState
		{
			Disabled,
			Enabled_HasPermissions,
			Enabled_NoPermissions
		}

		private void Awake()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
		}

		private void OnDestroy()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RoomRole role)
		{
			if (player.IsLocal)
			{
				UpdateButton();
			}
		}

		protected override void RunButtonAction()
		{
			if (PlayerGameRoleManager.Instance != null && IsInteractable())
			{
				EditGameRoleOrdersWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<EditGameRoleOrdersWatchUIFlow>();
				Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
			}
		}

		protected override void UpdateButtonState()
		{
			if (PlayerGameRoleManager.Instance == null || PlayerRoomRoleManager.Instance == null)
			{
				base.ButtonState = 0;
			}
			else if (PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value)
			{
				base.ButtonState = 1;
			}
			else
			{
				base.ButtonState = 2;
			}
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			bool flag = base.ButtonState != 0;
			if (base.gameObject.activeSelf != flag)
			{
				base.gameObject.SetActive(flag);
			}
		}

		protected override bool IsInteractable()
		{
			return base.IsInteractable() && base.ButtonState == 1;
		}
	}
