	public class ToggleGameRolesEditModeConditionalButton : ConditionalButton<Button3D>
	{
		private enum ButtonStates
		{
			Disabled,
			ChangeToEditMode,
			ChangeToViewMode
		}

		[SerializeField]
		private EditGameRoleOrdersWatchUIFlow editGameRoleOrdersScreen;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tooltip tooltip;

		protected override void OnEnable()
		{
			base.OnEnable();
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			editGameRoleOrdersScreen.OnRoleViewModeChangedEvent += OnRoleViewModeChanged;
		}

		private void OnDisable()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			if (editGameRoleOrdersScreen != null)
			{
				editGameRoleOrdersScreen.OnRoleViewModeChangedEvent -= OnRoleViewModeChanged;
			}
		}

		private void OnRoleViewModeChanged(RoleViewMode newRoleViewMode)
		{
			UpdateButton();
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer photonPlayer, RoomRole roleDef)
		{
			if (photonPlayer.IsLocal)
			{
				UpdateButton();
			}
		}

		protected override void RunButtonAction()
		{
			switch (base.ButtonState)
			{
			case 1:
				editGameRoleOrdersScreen.RoleViewMode = RoleViewMode.Edit;
				break;
			case 2:
				editGameRoleOrdersScreen.RoleViewMode = RoleViewMode.View;
				break;
			}
		}

		protected override bool IsInteractable()
		{
			return base.IsInteractable() && (base.ButtonState == 2 || PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value);
		}

		protected override void UpdateButtonState()
		{
			if (editGameRoleOrdersScreen.RoleViewMode == RoleViewMode.Edit)
			{
				base.ButtonState = 2;
			}
			else if (editGameRoleOrdersScreen.RoleViewMode == RoleViewMode.View)
			{
				base.ButtonState = 1;
			}
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			switch (base.ButtonState)
			{
			case 1:
				UIHelper.SafeSetText(base.LabelText, "Edit Roles");
				tooltip.Message = "Edit all game roles";
				break;
			case 2:
				UIHelper.SafeSetText(base.LabelText, "Show My Roles");
				tooltip.Message = "Show only roles I have.";
				break;
			}
		}
	}
	public class VoiceRolloffRolePermissionEditable : IntGameRolePermissionEditable
	{
		protected override int SliderValueToInt(float sliderValue)
		{
			int num = Mathf.Clamp((int)sliderValue, 0, PlayerGameRoleManager.RoleVoiceRolloffDistances.Length - 1);
			return PlayerGameRoleManager.RoleVoiceRolloffDistances[num];
		}

		protected override float IntValueToSliderValue(int rolloffDistance)
		{
			int index = 0;
			PlayerGameRoleManager.FindClosestRolloffDistance(rolloffDistance, out index);
			if (index < 0)
			{
				index = 0;
			}
			return index;
		}
	}
