	public class PlayerGameRoleManager : RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>
	{
		public const int GAME_ROLE_MANAGER_PRIORITY = 10000;

		private readonly ExplicitTokenMap<GameRole> _inGameRoleDefinitionMap = new ExplicitTokenMap<GameRole>();

		[Header("Default Game Roles")]
		[SerializeField]
		private GameRole defaultInGameRole = new GameRole(GameRoleId.AG_IN_GAME, null, "In-Game");

		[SerializeField]
		private GameRole eliminatedRole = new GameRole(GameRoleId.AG_ELIMINATED, null, "Out");

		private static readonly GameRoleId[] allGameRoleIds = (GameRoleId[])System.Enum.GetValues(typeof(GameRoleId));

		private static readonly int[] allRoleIds = allGameRoleIds.Cast<int>().ToArray();

		[Header("Role Audio")]
		[SerializeField]
		private AnimationCurve roleAudioRoleoffCurve = new AnimationCurve();

		public static readonly int[] RoleVoiceRolloffDistances = new int[8] { 0, 1, 5, 10, 25, 50, 100, 500 };

		public new static PlayerGameRoleManager Instance => NetworkedSingletonMonoBehaviour<RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>>.Instance as PlayerGameRoleManager;

		private GameRole InGameRoleDefinition => _inGameRoleDefinitionMap.HighestPriorityValue;

		protected override int[] AllRoleDefinitionIds => allRoleIds;

		protected override string PlayerRoleSynchronizedFieldSuffix => "gr";

		public void AddInGameRoleDefinition(GameRole value, object token, RoleMapPriority priority)
		{
			bool flag = _inGameRoleDefinitionMap.AddValue(value, token, (int)priority);
			if (!NeedsInitialization && flag)
			{
				GetRoleDefinition(InGameRoleDefinition.RoleId).Copy(value);
				UpdateAllPlayerRoleDefinitions();
			}
		}

		public void RemoveInGameRoleDefition(object token)
		{
			bool flag = _inGameRoleDefinitionMap.RemoveValue(token);
			if (!NeedsInitialization && flag)
			{
				GetRoleDefinition(InGameRoleDefinition.RoleId).Copy(InGameRoleDefinition);
				UpdateAllPlayerRoleDefinitions();
			}
		}

		public static int FindClosestRolloffDistance(float trueDistance, out int index)
		{
			index = -1;
			float num = 2.1474836E+09f;
			int result = RoleVoiceRolloffDistances[0];
			for (int i = 0; i < RoleVoiceRolloffDistances.Length; i++)
			{
				int num2 = RoleVoiceRolloffDistances[i];
				float num3 = Mathf.Abs(trueDistance - (float)num2);
				if (num3 <= num)
				{
					result = num2;
					index = i;
					num = num3;
				}
			}
			return result;
		}

		protected override void Awake()
		{
			base.Awake();
			Player.PlayerCreatedEvent += new Action<Player>(OnPlayerCreated);
		}

		protected override void Start()
		{
			RequestAddRole(PhotonNetwork.player, GetDefaultRoleIdForPlayer(PhotonNetwork.player));
			base.Start();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Player.PlayerCreatedEvent -= new Action<Player>(OnPlayerCreated);
		}

		protected override void SetupCustomDefaultRoleDefinitions()
		{
			base.SetupCustomDefaultRoleDefinitions();
			GameRole value = CreateRoleDefinition(2097152, defaultInGameRole);
			AddInGameRoleDefinition(value, this, RoleMapPriority.Default);
		}

		protected override void AddRequiredRoles(ref List<GameRole> newPredefinedRoles)
		{
			base.AddRequiredRoles(ref newPredefinedRoles);
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null)
			{
				return;
			}
			if (newPredefinedRoles.All((GameRole r) => r.RoleId != GameRoleId.AG_IN_GAME))
			{
				GameRole inGameRoleDefinition = InGameRoleDefinition;
				if (inGameRoleDefinition == null)
				{
					UnityEngine.Debug.LogError("Null inGameRole");
				}
				newPredefinedRoles.Add(inGameRoleDefinition);
			}
			GameMode currentMode = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode;
			if (currentMode != null && (currentMode.CombatSettings.SupportsEnemyOnPlayerCombat || currentMode.CombatSettings.SupportsPlayerOnPlayerCombat || currentMode.CombatSettings.SupportsMiscPlayerCombat) && newPredefinedRoles.All((GameRole r) => r.RoleId != GameRoleId.AG_ELIMINATED))
			{
				newPredefinedRoles.Add(eliminatedRole);
			}
		}

		private void OnPlayerCreated(Player player)
		{
			PhotonPlayer photonPlayer = player.PhotonPlayer;
			if (photonPlayer != null)
			{
				if (photonPlayer.IsLocal)
				{
					UpdateAllPlayerRoleDefinitions();
				}
				else
				{
					UpdateOrCreatePlayerRoleDefinition(photonPlayer);
				}
			}
		}

