		protected override PlayerGameRoleData RoleToProtobuf(GameRole roleToCopy)
		{
			return roleToCopy.SerializeToProtobuf();
		}

		protected override void ProtobufToRole(ref GameRole role, PlayerGameRoleData protobuf)
		{
			role.DeserializeFromProtobufData(protobuf);
			if (protobuf.RoleVersion < 2)
			{
				bool overrides = protobuf.TeleportMode.Overrides || protobuf.CanWalk.Overrides;
				bool value = protobuf.TeleportMode.InnerValue != 0 || protobuf.CanWalk.InnerValue;
				role.CanMove.Value = value;
				role.CanMove.Overrides = overrides;
			}
			if (protobuf.RoleVersion < 3)
			{
				role.ScreensCanSprint.Copy(role.VrCanSprint);
				role.ScreensWalkSpeed.Copy(role.VrWalkSpeed);
				role.ScreensSprintSpeedMultiplier.Copy(role.VrSprintSpeedMultiplier);
			}
		}

		protected override int RoleIdTypeToInt(GameRoleId roleId)
		{
			return (int)roleId;
		}

		protected override GameRoleId IntToRoleIdType(int roleId)
		{
			return (GameRoleId)roleId;
		}

		protected override int[] RoleIdTypesToInts(GameRoleId[] roleIds)
		{
			return roleIds?.Cast<int>().ToArray();
		}

