		{
			return RoleIdHelper.IsAGRole((GameRoleId)roleId);
		}

		protected override GameRoleCollectionData GetCollectionFromRoomData(PersistedRoomData roomData)
		{
			return roomData.GameRoleData;
		}

		protected override GameRoleCollectionData ParseRoleCollection(byte[] roleCollectionBytes)
		{
			return GameRoleCollectionData.Parser.ParseFrom(roleCollectionBytes);
		}

		protected override void _DeserializeRoleCollection(GameRoleCollectionData roleCollection)
		{
			if (roleCollection == null)
			{
				return;
			}
			foreach (PlayerGameRoleData gameRole in roleCollection.GameRoles)
			{
				GameRoleId roleId = (GameRoleId)gameRole.RoleId;
				GameRole roleDefinition = GetRoleDefinition(roleId);
				if (!IsPlayerDefinedRole(roleId) && roleDefinition.IsRoleActive)
				{
					gameRole.RoleRank = (int)roleDefinition.RoleRank;
				}
				roleDefinition.DeserializeFromProtobufData(gameRole);
				roleDefinition.IsRoleActive = true;
			}
		}

		protected override void RunBackwardsCompatibilityMigration(PersistedRoomData roomData)
		{
			base.RunBackwardsCompatibilityMigration(roomData);
			RoomPersistenceVersion version = (RoomPersistenceVersion)roomData.Version;
			if (roomData.HostSettings == null || version >= RoomPersistenceVersion.ROOM_ROLES)
			{
				return;
			}
			if (roomData.HostSettings.FlyingPermission == 2)
			{
				GetRoleDefinition(GameRoleId.AG_EVERYONE).CanFly.Value = true;
			}
			if (roomData.SandboxSettings != null && roomData.SandboxSettings.LimitTeleportSpeed)
			{
				GameRole roleDefinition = GetRoleDefinition(GameRoleId.AG_IN_GAME);
				if (!roleDefinition.IsRoleActive || !roleDefinition.TeleportDelay.Overrides)
				{
					roleDefinition.RoleName = "Alive";
					roleDefinition.IsRoleActive = true;
					roleDefinition.TeleportDelay.Value = 1.5f;
				}
			}
		}

		protected override GameRoleCollectionData SerializeRoleCollection()
		{
			List<GameRole> sortedActiveRoles = GetSortedActiveRoles();
			GameRoleCollectionData gameRoleCollectionData = new GameRoleCollectionData();
			gameRoleCollectionData.GameRoles.AddRange(sortedActiveRoles.Select((GameRole r) => r.SerializeToProtobuf()));
			return gameRoleCollectionData;
		}

		protected override void SetCollectionInRoomData(ref PersistedRoomData roomData, GameRoleCollectionData roleCollection)
		{
			roomData.GameRoleData = roleCollection;
		}

		protected override void ApplyPlayerRoleDefinition(PhotonPlayer photonPlayer, GameRole newLocalPlayerRole)
		{
			Player player = photonPlayer.ToPlayer();
			if (!(player != null))
			{
				return;
			}
			ApplyRolePlayerVoiceRolloff(player, newLocalPlayerRole.VoiceRolloffMaxDistance);
			if (!photonPlayer.IsLocal || !Player.LocalPlayerExists)
			{
				return;
			}
			if (!newLocalPlayerRole.CanMove.Value)
			{
				Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			}
			else
			{
				Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			}
			Player.LocalPlayer.ToolEquipSlots.HipSlotEnableMode = newLocalPlayerRole.EnableEquipSlotHip.Value;
			PlayerToolEquipSlot[] allSlots = Player.LocalPlayer.ToolEquipSlots.AllSlots;
			foreach (PlayerToolEquipSlot playerToolEquipSlot in allSlots)
			{
				switch (playerToolEquipSlot.SlotType)
				{
				case ToolEquipSlot.EquipSlotType.Hip:
					playerToolEquipSlot.ChangeEquipRestrictions(newLocalPlayerRole.EquipRestrictionsHip.Value, newLocalPlayerRole.EquipHipWhitelist.Value, newLocalPlayerRole.EquipHipBlacklist.Value);
					break;
				case ToolEquipSlot.EquipSlotType.Shoulder:
					playerToolEquipSlot.ChangeEquipRestrictions(newLocalPlayerRole.EquipRestrictionsShoulder.Value, newLocalPlayerRole.EquipShoulderWhitelist.Value, newLocalPlayerRole.EquipShoulderBlacklist.Value);
					break;
				}
			}
			switch (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType)
			{
			case LocalPlayerController.PlayerType.SCREEN:
				SingletonMonoBehaviour<LocalPlayerController>.Instance.AddScreensDefaultControlType((ScreenPlayerController.ScreenPlayerGenreType)newLocalPlayerRole.ScreensDefaultControlType.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddMaxWalkSpeed(newLocalPlayerRole.ScreensWalkSpeed.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddMaxSprintSpeedMultiplier(newLocalPlayerRole.ScreensSprintSpeedMultiplier.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddSprintEnabled(newLocalPlayerRole.ScreensCanSprint.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddJumpEnabled(newLocalPlayerRole.ScreensCanJump.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddDodgeEnabled(newLocalPlayerRole.ScreensCanDodge.Value, this, 10000);
				break;
			default:
				Player.LocalPlayer.PlayerLocomotion.AddTeleportCooldown(newLocalPlayerRole.TeleportDelay.Value, this, 10000);
				Player.LocalPlayer.PlayerLocomotion.AddTeleportMaxDropHeight(newLocalPlayerRole.MaxTeleportDropHeight.Value, this, 10000);
				Player.LocalPlayer.PlayerLocomotion.AddTeleportMaxHorizontalDistance(newLocalPlayerRole.MaxTeleportDistance.Value, this, 10000);
				Player.LocalPlayer.PlayerLocomotion.AddTeleportMaxHorizontalSurfaceAngle(newLocalPlayerRole.MaxTeleportAngle.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddMaxWalkSpeed(newLocalPlayerRole.VrWalkSpeed.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddMaxSprintSpeedMultiplier(newLocalPlayerRole.VrSprintSpeedMultiplier.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddSprintEnabled(newLocalPlayerRole.VrCanSprint.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddJumpEnabled(newLocalPlayerRole.VrCanJump.Value, this, 10000);
				Player.LocalPlayer.PlayerWalking.AddDodgeEnabled(newLocalPlayerRole.VrCanDodge.Value, this, 10000);
				break;
			}
		}

		private void ApplyRolePlayerVoiceRolloff(Player player, IMutableOverridableField<int> voiceRolloffMaxDistance)
		{
			if (voiceRolloffMaxDistance.Overrides)
			{
				int index;
				int num = FindClosestRolloffDistance(voiceRolloffMaxDistance.Value, out index);
				if (num > 0)
				{
					AudioRolloff audioRolloff = new AudioRolloff();
					audioRolloff.rolloffMode = AudioRolloffMode.Custom;
					audioRolloff.minDistance = 0f;
					audioRolloff.maxDistance = num;
					audioRolloff.customCurve = roleAudioRoleoffCurve;
					AudioRolloff rolloff = audioRolloff;
					player.PlayerAudio.AddVoiceAudioRolloff(rolloff, this, 10000);
				}
				player.SetMuteFlag(Player.MuteFlags.MUTED_BY_GAME_ROLE, num == 0);
			}
			else
			{
				player.SetMuteFlag(Player.MuteFlags.MUTED_BY_GAME_ROLE, enabled: false);
				player.PlayerAudio.RemoveVoiceAudioRolloff(this);
			}
		}

		protected override void RemoveAllRolePermissions()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
			{
				SingletonMonoBehaviour<LocalPlayerController>.Instance.RemoveScreensDefaultControlType(this);
			}
			if (Player.LocalPlayer != null)
			{
				Player.LocalPlayer.PlayerAudio.RemoveVoiceAudioRolloff(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
				Player.LocalPlayer.PlayerWalking.RemoveMaxWalkSpeed(this);
				Player.LocalPlayer.PlayerWalking.RemoveMaxSprintSpeedMultiplier(this);
				Player.LocalPlayer.PlayerWalking.RemoveSprintEnabled(this);
				Player.LocalPlayer.PlayerWalking.RemoveJumpEnabled(this);
				Player.LocalPlayer.PlayerWalking.RemoveDodgeEnabled(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportCooldown(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportMaxDropHeight(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportMaxHorizontalDistance(this);
				Player.LocalPlayer.PlayerLocomotion.RemoveTeleportMaxHorizontalSurfaceAngle(this);
				Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.MUTED_BY_GAME_ROLE, enabled: false);
			}
			for (int i = 0; i < Player.All.Count; i++)
			{
				Player.All[i].SetMuteFlag(Player.MuteFlags.MUTED_BY_GAME_ROLE, enabled: false);
				Player.All[i].PlayerAudio.RemoveVoiceAudioRolloff(this);
			}
		}

		public static bool CanPickupTool(Player selectingPlayer, Tool tool)
		{
			return CanPickupTool(selectingPlayer.PhotonPlayer, tool);
		}

		public static bool CanPickupTool(PhotonPlayer photonPlayer, Tool tool)
		{
			if (!NetworkedSingletonMonoBehaviour<RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>>.IsInitialized)
			{
				return true;
			}
			if (photonPlayer == null)
			{
				return false;
			}
			if (tool.IsSubTool)
			{
				return Instance.CanPhotonPlayerPickupTool(photonPlayer, tool.ParentTool);
			}
			return Instance.CanPhotonPlayerPickupTool(photonPlayer, tool);
		}

		private bool CanPhotonPlayerPickupTool(PhotonPlayer photonPlayer, Tool tool)
		{
			if (tool == null)
			{
				return false;
			}
			GameRole playerRoleDefinition = GetPlayerRoleDefinition(photonPlayer);
			return playerRoleDefinition.ItemPickupRestrictions.Value switch
			{
				RolePickupRestrictionType.NoRestrictions => true, 
				RolePickupRestrictionType.AllRestricted => false, 
				RolePickupRestrictionType.Whitelist => CanWhitelistPickup(playerRoleDefinition, tool), 
				RolePickupRestrictionType.Blacklist => CanBlacklistPickup(playerRoleDefinition, tool), 
				_ => true, 
			};
		}

		private bool CanWhitelistPickup(GameRole playerRoleDef, Tool tool)
		{
			if (tool.PlayerSpawnedEquipment != null)
			{
				return true;
			}
			return TaggedTool.CheckTagRestrictions(tool, whitelist: true, playerRoleDef.ItemPickupWhitelist.Value);
		}

		private bool CanBlacklistPickup(GameRole playerRoleDef, Tool tool)
		{
			return TaggedTool.CheckTagRestrictions(tool, whitelist: false, playerRoleDef.ItemPickupBlacklist.Value);
		}
	}
	public class PlayerRoomRoleManager : RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>
	{
		[Header("Room Role Definitions")]
		[SerializeField]
		private RoomRole defaultRoomHostRole = new RoomRole(RoomRoleId.AG_HOST);

		[SerializeField]
		private RoomRole defaultRoomCoOwnerRole = new RoomRole(RoomRoleId.AG_COOWNER);

		[SerializeField]
		private RoomRole defaultRoomCreatorRole = new RoomRole(RoomRoleId.AG_CREATOR);

		private bool? canTalk;

		private static RoomRoleId[] AllRoomRoleIds = (RoomRoleId[])System.Enum.GetValues(typeof(RoomRoleId));

		private static int[] allRoleIds = AllRoomRoleIds.Cast<int>().ToArray();

		public new static PlayerRoomRoleManager Instance => NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.Instance as PlayerRoomRoleManager;

		protected override int[] AllRoleDefinitionIds => allRoleIds;

		protected override string PlayerRoleSynchronizedFieldSuffix => "rr";

		protected override void Awake()
		{
			base.Awake();
			Player.LocalPlayerCreatedEvent += new Action(OnLocalPlayerCreated);
			RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomUpdated);
		}

		protected override void Start()
		{
			OnLocalRoomUpdated();
			base.Start();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			Player.LocalPlayerCreatedEvent -= new Action(OnLocalPlayerCreated);
			RecNet.Rooms.OnLocalRoomUpdated -= new Action(OnLocalRoomUpdated);
		}

		protected override void AddRequiredRoles(ref List<RoomRole> newPredefinedRoles)
		{
			base.AddRequiredRoles(ref newPredefinedRoles);
			if (newPredefinedRoles.All((RoomRole r) => r.RoleId != RoomRoleId.AG_HOST))
			{
				newPredefinedRoles.Add(defaultRoomHostRole);
			}
			if (newPredefinedRoles.All((RoomRole r) => r.RoleId != RoomRoleId.AG_COOWNER))
			{
				newPredefinedRoles.Add(defaultRoomCoOwnerRole);
			}
			if (newPredefinedRoles.All((RoomRole r) => r.RoleId != RoomRoleId.AG_CREATOR))
			{
				newPredefinedRoles.Add(defaultRoomCreatorRole);
			}
		}

		private void OnLocalRoomUpdated()
		{
			RoomRoleId defaultRoleIdForPlayer = GetDefaultRoleIdForPlayer(PhotonNetwork.player);
			LocalPlayerSetRoles(defaultRoleIdForPlayer);
		}

		private void OnLocalPlayerCreated()
		{
			canTalk = null;
			UpdateLocalPlayerRoleDefinition();
			RefreshAutoAssignedGameRoles();
		}

		protected override RoomRoleId GetDefaultRoleIdForPlayer(PhotonPlayer player)
		{
			RoomRoleId roomRoleId = RoomRoleId.AG_EVERYONE;
			TryGetRoomRole(player, out var roomRole);
			if (roomRole >= RecNet.RoomRole.Host)
			{
				roomRoleId |= RoomRoleId.AG_HOST;
			}
			if (roomRole >= RecNet.RoomRole.CoOwner)
			{
				roomRoleId |= RoomRoleId.AG_COOWNER;
			}
			if (roomRole >= RecNet.RoomRole.Creator)
			{
				roomRoleId |= RoomRoleId.AG_CREATOR;
			}
			return roomRoleId;
		}

		private static bool TryGetRoomRole(PhotonPlayer player, out RecNet.RoomRole roomRole)
		{
			roomRole = RecNet.RoomRole.Guest;
			if (player == null)
			{
				return false;
			}
			RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
			if (localRoomDetails != null)
			{
				roomRole = localRoomDetails.GetPlayerRole((int)player.RecNetProfileId);
				return true;
			}
			if (RecNet.Rooms.LocalRoomDetails.GetPlayerRole((int)player.RecNetProfileId) == RecNet.RoomRole.Creator)
			{
				roomRole = RecNet.RoomRole.Creator;
				return true;
			}
			return false;
		}

		protected override RoomRole CreateRoleDefinition(int newRoleId, RoomRole roleToCopy, string roleName = null)
		{
			return new RoomRole((RoomRoleId)newRoleId, roleToCopy, roleName);
		}

		public override bool IsPlayerDefinedRole(RoomRoleId roleId)
		{
			return RoleIdHelper.IsPlayerDefinedRole(roleId);
		}

		public override bool PlayerCanAssignRole(PhotonPlayer assigner, PhotonPlayer assignee, RoomRoleId roleId)
		{
			if (!base.PlayerCanAssignRole(assigner, assignee, roleId))
			{
				return false;
			}
			if (assigner == null)
			{
				return false;
			}
			if (FindPlayerHighestRoleRank(assigner) <= FindPlayerHighestRoleRank(assignee))
			{
				return false;
			}
			if (!GetPlayerRoleDefinition(assigner).CanEditRoomRoles.Value)
			{
				return false;
			}
			return true;
		}

		public override bool PlayerCanModifyRoleDefinition(PhotonPlayer modifier, RoomRoleId roleId)
		{
			if (!base.PlayerCanModifyRoleDefinition(modifier, roleId))
			{
				return false;
			}
			if (modifier == null)
			{
				return false;
			}
			RoleRank roleRank = FindPlayerHighestRoleRank(modifier);
			if ((roleRank >= GetRoleDefinition(RoomRoleId.AG_COOWNER).RoleRank && GetRoleDefinition(roleId).RoleRank > roleRank) || (roleRank < GetRoleDefinition(RoomRoleId.AG_COOWNER).RoleRank && GetRoleDefinition(roleId).RoleRank >= roleRank))
			{
				return false;
			}
			if (!GetPlayerRoleDefinition(modifier).CanEditRoomRoles.Value)
			{
				return false;
			}
			return true;
		}

		protected override bool PlayerCanModifyRoles(PhotonPlayer player)
		{
			if (!base.PlayerCanModifyRoles(player))
			{
				return false;
			}
			if (player == null)
			{
				return false;
			}
			if (!GetPlayerRoleDefinition(player).CanEditRoomRoles.Value)
			{
				return false;
			}
			return true;
		}

		protected override bool PlayerCanMoveRole(PhotonPlayer mover, RoomRole roleToMove, RoomRole otherRole)
		{
			return base.PlayerCanMoveRole(mover, roleToMove, otherRole) && mover != null && FindPlayerHighestRoleRank(mover) > roleToMove.RoleRank && FindPlayerHighestRoleRank(mover) > otherRole.RoleRank && GetPlayerRoleDefinition(mover).CanEditRoomRoles.Value;
		}

		protected override PlayerRoomRoleData RoleToProtobuf(RoomRole roleToCopy)
		{
			return roleToCopy.SerializeToProtobuf();
		}

		protected override void ProtobufToRole(ref RoomRole role, PlayerRoomRoleData protobuf)
		{
			role.DeserializeFromProtobufData(protobuf);
		}

		protected override int RoleIdTypeToInt(RoomRoleId roleId)
		{
			return (int)roleId;
		}

		protected override RoomRoleId IntToRoleIdType(int roleId)
		{
			return (RoomRoleId)roleId;
		}

		protected override int[] RoleIdTypesToInts(RoomRoleId[] roleIds)
		{
			return roleIds?.Cast<int>().ToArray();
		}

		protected override bool IsAGRole(int roleId)
		{
			return RoleIdHelper.IsAGRole((RoomRoleId)roleId);
		}

		protected override RoomRoleCollectionData GetCollectionFromRoomData(PersistedRoomData roomData)
		{
			return roomData.RoomRoleData;
		}

		protected override RoomRoleCollectionData ParseRoleCollection(byte[] roleCollectionBytes)
		{
			return RoomRoleCollectionData.Parser.ParseFrom(roleCollectionBytes);
		}

		protected override void _DeserializeRoleCollection(RoomRoleCollectionData roleCollection)
		{
			if (roleCollection == null)
			{
				return;
			}
			foreach (PlayerRoomRoleData roomRole in roleCollection.RoomRoles)
			{
				RoomRoleId roleId = (RoomRoleId)roomRole.RoleId;
				RoomRole roleDefinition = GetRoleDefinition(roleId);
				if (!IsPlayerDefinedRole(roleId) && roleDefinition.IsRoleActive)
				{
					roomRole.RoleRank = (int)roleDefinition.RoleRank;
				}
				roleDefinition.DeserializeFromProtobufData(roomRole);
				if (roleId == RoomRoleId.AG_CREATOR)
				{
					roleDefinition.CanEditGameRoles.Value = true;
					roleDefinition.CanEditRoomRoles.Value = true;
				}
			}
		}

		protected override void RunBackwardsCompatibilityMigration(PersistedRoomData roomData)
		{
			base.RunBackwardsCompatibilityMigration(roomData);
			RoomPersistenceVersion version = (RoomPersistenceVersion)roomData.Version;
			if (version >= RoomPersistenceVersion.ROOM_ROLES)
			{
				return;
			}
			HostSettingsData hostSettings = roomData.HostSettings;
			if (hostSettings != null)
			{
				switch ((HostPermission)hostSettings.CircuitEditingPermission)
				{
				case HostPermission.Off:
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanEditCircuits.Value = false;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanEditCircuits.Overrides = false;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanEditCircuits.Overrides = false;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanEditCircuits.Overrides = false;
					break;
				case HostPermission.Hosts:
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanEditCircuits.Value = false;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanEditCircuits.Value = true;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanEditCircuits.Overrides = false;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanEditCircuits.Overrides = false;
					break;
				default:
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanEditCircuits.Value = true;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanEditCircuits.Overrides = false;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanEditCircuits.Overrides = false;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanEditCircuits.Overrides = false;
					break;
				}
				if (hostSettings.OnlyHostsCanInvite)
				{
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanInvite.Value = false;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanInvite.Value = true;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanInvite.Value = true;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanInvite.Value = true;
				}
				if (hostSettings.OnlyHostsCanPrintPolaroids)
				{
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanPrintPhotos.Value = false;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanPrintPhotos.Value = true;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanPrintPhotos.Value = true;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanPrintPhotos.Value = true;
				}
				if (hostSettings.OnlyHostsCanStartGames)
				{
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).CanStartGames.Value = false;
					GetRoleDefinition(RoomRoleId.AG_HOST).CanStartGames.Value = true;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).CanStartGames.Value = true;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).CanStartGames.Value = true;
				}
				if (hostSettings.OnlyHostsCanVoteKick)
				{
					GetRoleDefinition(RoomRoleId.AG_EVERYONE).VoteKickPermission.Value = VotekickType.Off;
					GetRoleDefinition(RoomRoleId.AG_HOST).VoteKickPermission.Value = VotekickType.Instant;
					GetRoleDefinition(RoomRoleId.AG_COOWNER).VoteKickPermission.Value = VotekickType.Instant;
					GetRoleDefinition(RoomRoleId.AG_CREATOR).VoteKickPermission.Value = VotekickType.Instant;
				}
			}
		}

		protected override RoomRoleCollectionData SerializeRoleCollection()
		{
			List<RoomRole> sortedActiveRoles = GetSortedActiveRoles();
			RoomRoleCollectionData roomRoleCollectionData = new RoomRoleCollectionData();
			roomRoleCollectionData.RoomRoles.AddRange(sortedActiveRoles.Select((RoomRole r) => r.SerializeToProtobuf()));
			return roomRoleCollectionData;
		}

		protected override void SetCollectionInRoomData(ref PersistedRoomData roomData, RoomRoleCollectionData roleCollection)
		{
			roomData.RoomRoleData = roleCollection;
		}

		private void RefreshAutoAssignedGameRoles()
		{
			if (!NetworkedSingletonMonoBehaviour<RoleManagerBase<GameRoleId, GameRole.RolePermission, GameRole, PlayerGameRoleData, GameRoleCollectionData>>.IsInitialized || !base.CachedLocalPlayerRoleDefinition.AutoAssignedGameRoles.Overrides)
			{
				return;
			}
			List<string> value = base.CachedLocalPlayerRoleDefinition.AutoAssignedGameRoles.Value;
			List<GameRoleId> list = new List<GameRoleId>();
			for (int i = 0; i < value.Count; i++)
			{
				string newRoleName = value[i];
				GameRole gameRole = PlayerGameRoleManager.Instance.FindActiveRoleByName(newRoleName);
				if (gameRole != null && RoleIdHelper.IsPlayerDefinedRole(gameRole.RoleId))
				{
					list.Add(gameRole.RoleId);
				}
			}
			PlayerGameRoleManager.Instance.RequestToggleRoles(PhotonNetwork.player, list.ToArray(), null);
		}

		public bool IsAtLeastHostRole(RoomRoleId roomRole)
		{
			RoomRole roleDefinition = GetRoleDefinition(roomRole);
			return IsAtLeastHostRole(roleDefinition);
		}

		public bool IsAtLeastHostRole(RoomRole roomRole)
		{
			return roomRole.RoleRank >= GetRoleDefinition(RoomRoleId.AG_HOST).RoleRank;
		}

		public bool IsHostPresent()
		{
			PhotonPlayer[] playerList = PhotonNetwork.playerList;
			foreach (PhotonPlayer player in playerList)
			{
				RoomRole playerRoleDefinition = GetPlayerRoleDefinition(player);
				if (IsAtLeastHostRole(playerRoleDefinition))
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsPlayerAHost(PhotonPlayer player)
		{
			if (Instance == null)
			{
				return false;
			}
			RoleRank roleRank = Instance.FindRoleRank(RoomRoleId.AG_HOST);
			return Instance.GetPlayerRoleDefinition(player).RoleRank >= roleRank;
		}

		public VotekickType CanVoteKick(PhotonPlayer kicker, PhotonPlayer kicked, bool showNotification = false)
		{
			RoomRole playerRoleDefinition = GetPlayerRoleDefinition(kicker);
			RoomRole playerRoleDefinition2 = GetPlayerRoleDefinition(kicked);
			if (playerRoleDefinition.RoleRank < playerRoleDefinition2.RoleRank)
			{
				if (showNotification)
				{
					Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Failed to vote kick", "You cannot kick someone of higher rank!");
				}
				return VotekickType.Off;
			}
			if (playerRoleDefinition.VoteKickPermission.Value == VotekickType.Off)
			{
				if (AnyPlayerRole((RoomRole r) => r.VoteKickPermission.Value != VotekickType.Off))
				{
					if (showNotification)
					{
						Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Failed to vote kick", "The event host has prevented you from vote kicking people.");
					}
					return VotekickType.Off;
				}
				return VotekickType.Vote;
			}
			return playerRoleDefinition.VoteKickPermission.Value;
		}

		protected override void ApplyPlayerRoleDefinition(PhotonPlayer player, RoomRole playerRoleDef)
		{
			if (!player.IsLocal || !Player.LocalPlayerExists)
			{
				return;
			}
			CircuitVisibilityBehaviour.CircuitVisibilityChanged();
			Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.MUTED_BY_ROOM_ROLE, !playerRoleDef.CanTalk.Value);
			if (playerRoleDef.CanTalk.Value != canTalk)
			{
				if (!playerRoleDef.CanTalk.Value)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Talking is " + AllowedString(playerRoleDef.CanTalk) + " for your room role", 3f);
				}
				canTalk = playerRoleDef.CanTalk.Value;
			}
			RefreshAutoAssignedGameRoles();
		}

		protected override void RemoveAllRolePermissions()
		{
			if (Player.LocalPlayer != null)
			{
				Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.MUTED_BY_ROOM_ROLE, enabled: false);
			}
		}

		private string AllowedString(IOverridableField<bool> overridableField)
		{
			return (!overridableField.Value) ? "not allowed" : "enabled";
		}
	}
	public static class RoleRankHelper
	{
		public static RoleRank GetRankForGameRole(GameRoleId roleId)
		{
			return roleId switch
			{
				GameRoleId.AG_EVERYONE => RoleRank.AG_BOTTOM_RANK_1, 
				GameRoleId.AG_IN_GAME => RoleRank.AG_BOTTOM_RANK_2, 
				GameRoleId.AG_ELIMINATED => RoleRank.AG_TOP_RANK_16, 
				_ => (!PlayerGameRoleManager.Instance.IsPlayerDefinedRole(roleId)) ? RoleRank.AG_BOTTOM_RANK_3 : RoleRank.PLAYER_RANK_1, 
			};
		}

		public static RoleRank GetRankForRoomRole(RoomRoleId roleId)
		{
			return roleId switch
			{
				RoomRoleId.AG_EVERYONE => RoleRank.AG_BOTTOM_RANK_1, 
				RoomRoleId.AG_CREATOR => RoleRank.AG_TOP_RANK_16, 
				RoomRoleId.AG_COOWNER => RoleRank.AG_TOP_RANK_15, 
				RoomRoleId.AG_HOST => RoleRank.AG_TOP_RANK_14, 
				_ => (!PlayerRoomRoleManager.Instance.IsPlayerDefinedRole(roleId)) ? RoleRank.AG_BOTTOM_RANK_2 : RoleRank.PLAYER_RANK_1, 
			};
		}

		public static List<RoleRank> GetPlayerRoleRanks()
		{
			List<RoleRank> list = ((RoleRank[])System.Enum.GetValues(typeof(RoleRank))).Where((RoleRank rr) => rr != RoleRank.INVALID && rr >= RoleRank.PLAYER_RANK_1 && rr <= RoleRank.PLAYER_RANK_32).ToList();
			list.Sort();
			return list;
		}

		public static List<RoleRank> GetAGRoleRanks()
		{
			List<RoleRank> list = ((RoleRank[])System.Enum.GetValues(typeof(RoleRank))).Where((RoleRank rr) => rr != RoleRank.INVALID && (rr <= RoleRank.AG_BOTTOM_RANK_16 || rr >= RoleRank.AG_TOP_RANK_1)).ToList();
			list.Sort();
			return list;
		}
	}
	public static class RoleIdHelper
	{
		public const int MAX_ROLE_NAME_LENGTH = 20;

		private static GameRoleId AG_GameRoles = GameRoleId.AG_ROLE_11 | GameRoleId.AG_IN_GAME | GameRoleId.AG_ELIMINATED | GameRoleId.AG_ROLE_3 | GameRoleId.AG_ROLE_4 | GameRoleId.AG_ROLE_5 | GameRoleId.AG_ROLE_6 | GameRoleId.AG_ROLE_7 | GameRoleId.AG_ROLE_8 | GameRoleId.AG_ROLE_9 | GameRoleId.AG_ROLE_10;

		private static RoomRoleId AG_RoomRoles = RoomRoleId.AG_ROLE_11 | RoomRoleId.AG_CREATOR | RoomRoleId.AG_COOWNER | RoomRoleId.AG_HOST | RoomRoleId.AG_ROLE_4 | RoomRoleId.AG_ROLE_5 | RoomRoleId.AG_ROLE_6 | RoomRoleId.AG_ROLE_7 | RoomRoleId.AG_ROLE_8 | RoomRoleId.AG_ROLE_9 | RoomRoleId.AG_ROLE_10;

		public static bool IsAGRole(GameRoleId roleId)
		{
			return (AG_GameRoles & roleId) == roleId;
		}

		public static bool IsPlayerDefinedRole(GameRoleId roleId)
		{
			return !IsAGRole(roleId);
		}

		public static bool IsAGRole(RoomRoleId roleId)
		{
			return (AG_RoomRoles & roleId) == roleId;
		}

		public static bool IsPlayerDefinedRole(RoomRoleId roleId)
		{
			return !IsAGRole(roleId);
		}
	}
