	public abstract class RoleManagerBase<RoleIdType, RolePermissionType, RoleDefinitionType, RoleProtobufType, RoleCollectionProtobufType> : NetworkedSingletonMonoBehaviour<RoleManagerBase<RoleIdType, RolePermissionType, RoleDefinitionType, RoleProtobufType, RoleCollectionProtobufType>>, IPersistableSettings where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, IProtobufRole<RoleProtobufType>, new() where RoleProtobufType : IMessage<RoleProtobufType> where RoleCollectionProtobufType : IMessage<RoleCollectionProtobufType>
	{
		public delegate RoleDefinitionType CreateSynchronizedRoleInstance(int roleId, RoleDefinitionType roleToCopy);

		public delegate bool AnyDelegate(RoleDefinitionType roleDef);

		private class PlayerRole
		{
			private readonly string fieldSuffix;

			private PhotonPlayer player;

			private ObscuredSynchronizedField<int> playerRoles;

			private int? _cachedRoles;

			private int PlayerRoles
			{
				get
				{
					return playerRoles.Get();
				}
				set
				{
					if (player.IsLocal)
					{
						playerRoles.Set(value);
					}
				}
			}

			public event Action<PhotonPlayer, int> PlayerRoleSetUpdatedEvent
			{
				add
				{
					Action<PhotonPlayer, int> action = this.PlayerRoleSetUpdatedEvent;
					Action<PhotonPlayer, int> action2;
					do
					{
						action2 = action;
						action = Interlocked.CompareExchange(ref this.PlayerRoleSetUpdatedEvent, (Action<PhotonPlayer, int>)Delegate.Combine(action2, value), action);
					}
					while (action != action2);
				}
				remove
				{
					Action<PhotonPlayer, int> action = this.PlayerRoleSetUpdatedEvent;
					Action<PhotonPlayer, int> action2;
					do
					{
						action2 = action;
						action = Interlocked.CompareExchange(ref this.PlayerRoleSetUpdatedEvent, (Action<PhotonPlayer, int>)Delegate.Remove(action2, value), action);
					}
					while (action != action2);
				}
			}

			public PlayerRole(string fieldSuffix, PhotonPlayer player, int defaultRole)
			{
				this.fieldSuffix = fieldSuffix.ToUpperInvariant();
				this.player = player;
				playerRoles = new ObscuredSynchronizedField<int>(player, this.fieldSuffix, defaultRole, SetterPermissionMode.ANYONE, OnPlayerRolesUpdated);
			}

			public bool HasRole(int role)
			{
				return (PlayerRoles & role) == role;
			}

			internal bool AddRole(int roleIdToAdd)
			{
				return ModifyPlayerRoles(new int[1] { roleIdToAdd }, null);
			}

			internal bool RemoveRole(int roleIdToRemove)
			{
				return ModifyPlayerRoles(null, new int[1] { roleIdToRemove });
			}

			internal bool ModifyPlayerRoles(int[] rolesToAdd, int[] rolesToRemove)
			{
				int num = PlayerRoles;
				if (rolesToAdd != null)
				{
					for (int i = 0; i < rolesToAdd.Length; i++)
					{
						num |= rolesToAdd[i];
					}
				}
				if (rolesToRemove != null)
				{
					for (int j = 0; j < rolesToRemove.Length; j++)
					{
						num &= ~rolesToRemove[j];
					}
				}
				return SetPlayerRoles(num);
			}

			internal bool SetPlayerRoles(int newPlayerRoles)
			{
				bool result = newPlayerRoles != PlayerRoles;
				PlayerRoles = newPlayerRoles;
				return result;
			}

			internal void Clear()
			{
				SetPlayerRoles(0);
			}

			private void OnPlayerRolesUpdated()
			{
				int? cachedRoles = _cachedRoles;
				if (cachedRoles.GetValueOrDefault() != PlayerRoles || !cachedRoles.HasValue)
				{
					string text = ((!_cachedRoles.HasValue) ? "?" : ToRoleString(_cachedRoles.Value));
					string text2 = ToRoleString(PlayerRoles);
					UnityEngine.Debug.Log($"{fieldSuffix}RC {player}: {text} {text2}");
				}
				_cachedRoles = PlayerRoles;
				this.PlayerRoleSetUpdatedEvent.SafeInvoke(player, PlayerRoles);
			}

			private static string ToRoleString(int roles)
			{
				return roles.ToString();
			}

			public override string ToString()
			{
				return "PlayerRoles[" + player.ID + "] " + ToRoleString(PlayerRoles);
			}
		}

		public static ActionEvent<RoleDefinitionType> OnRoleDefinitionUpdatedEvent = new ActionEvent<RoleDefinitionType>(32, useTryCatch: true);

		public static ActionEvent OnRoleOrdersChangedEvent = new ActionEvent(32, useTryCatch: true);

		public static ActionEvent<PhotonPlayer, RoleDefinitionType> OnPlayerRoleDefinitionUpdatedEvent = new ActionEvent<PhotonPlayer, RoleDefinitionType>(32, useTryCatch: true);

		private Dictionary<RoleIdType, RoleDefinitionType> allRoleDefinitions = new Dictionary<RoleIdType, RoleDefinitionType>();

		[Header("Debugging")]
