		private RoleDefinitionType _cachedLocalPlayerRoleDefinition = new RoleDefinitionType();

		[SerializeField]
		[ReadOnly]
		private List<RoleDefinitionType> allSortedActiveRoleDefinitions = new List<RoleDefinitionType>();

		private Dictionary<int, PlayerRole> playerRoleSets = new Dictionary<int, PlayerRole>();

		private Dictionary<PhotonPlayer, RoleDefinitionType> _playerRoleDefinitions = new Dictionary<PhotonPlayer, RoleDefinitionType>();

		[Header("Role Defaults")]
		[SerializeField]
		private RoleDefinitionType _defaultRoleDefinition;

		private readonly ExplicitTokenMap<RoleDefinitionType> _everyoneRoleDefinitionMap = new ExplicitTokenMap<RoleDefinitionType>();

		protected bool NeedsInitialization = true;

		public RoleDefinitionType CachedLocalPlayerRoleDefinition
		{
			get
			{
				return _cachedLocalPlayerRoleDefinition;
			}
			private set
			{
				_cachedLocalPlayerRoleDefinition = value;
			}
		}

		protected abstract int[] AllRoleDefinitionIds { get; }

		public RoleDefinitionType DefaultRoleDefinition => _defaultRoleDefinition;

		private RoleDefinitionType EveryoneRoleDefinition => _everyoneRoleDefinitionMap.HighestPriorityValue;

		protected abstract string PlayerRoleSynchronizedFieldSuffix { get; }

		public void AddEveryoneRoleDefinition(RoleDefinitionType value, object token, RoleMapPriority priority)
		{
			bool flag = _everyoneRoleDefinitionMap.AddValue(value, token, (int)priority);
			if (!NeedsInitialization && flag)
			{
				RoleDefinitionType everyoneRoleDefinition = EveryoneRoleDefinition;
				RoleDefinitionType roleDefinition = GetRoleDefinition(everyoneRoleDefinition.RoleId);
				roleDefinition.Copy(value);
				UpdateAllPlayerRoleDefinitions();
			}
		}

		public void RemoveEveryoneRoleDefinition(object token)
		{
			bool flag = _everyoneRoleDefinitionMap.RemoveValue(token);
			if (!NeedsInitialization && flag)
			{
				RoleDefinitionType everyoneRoleDefinition = EveryoneRoleDefinition;
				RoleDefinitionType roleDefinition = GetRoleDefinition(everyoneRoleDefinition.RoleId);
				roleDefinition.Copy(EveryoneRoleDefinition);
				UpdateAllPlayerRoleDefinitions();
			}
		}

		protected override void Awake()
		{
			base.Awake();
			InitializeRoles();
			UpdatePredefinedRoles();
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnPhotonMasterClientSwitched);
		}

		protected virtual void Start()
		{
			UpdateAllPlayerRoleDefinitions();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnPhotonMasterClientSwitched);
			RemoveAllRolePermissions();
		}

		protected abstract void RemoveAllRolePermissions();

		protected abstract int RoleIdTypeToInt(RoleIdType roleId);

		protected abstract RoleIdType IntToRoleIdType(int roleId);

		protected abstract int[] RoleIdTypesToInts(RoleIdType[] roleId);

		protected abstract bool IsAGRole(int roleId);

		protected abstract RoleDefinitionType CreateRoleDefinition(int newRoleId, RoleDefinitionType roleToCopy, string roleName = null);

		protected abstract RoleProtobufType RoleToProtobuf(RoleDefinitionType roleToCopy);

		protected abstract void ProtobufToRole(ref RoleDefinitionType role, RoleProtobufType protobuf);

		private bool GetOrCreatePlayerRole(PhotonPlayer player, out PlayerRole role)
		{
			if (!playerRoleSets.TryGetValue(player.ID, out role))
			{
				role = new PlayerRole(PlayerRoleSynchronizedFieldSuffix, player, RoleIdTypeToInt(GetDefaultRoleIdForPlayer(player)));
				role.PlayerRoleSetUpdatedEvent += OnPlayerRoleSetUpdated;
				playerRoleSets[player.ID] = role;
				UpdateOrCreatePlayerRoleDefinition(player);
				return true;
			}
			return false;
		}

		protected virtual RoleIdType GetDefaultRoleIdForPlayer(PhotonPlayer player)
		{
			RoleDefinitionType everyoneRoleDefinition = EveryoneRoleDefinition;
			return everyoneRoleDefinition.RoleId;
		}

		public void RequestAddRole(PhotonPlayer player, RoleIdType roleToAdd)
		{
			RequestToggleRoles(player, roleToAdd, null);
		}

		public void RequestRemoveRole(PhotonPlayer player, RoleIdType roleToRemove)
		{
			RequestToggleRoles(player, null, roleToRemove);
		}

		public void RequestToggleRoles(PhotonPlayer player, RoleIdType? roleToAdd, RoleIdType? roleToRemove)
		{
			RoleIdType[] rolesToAdd = null;
			if (roleToAdd.HasValue)
			{
				rolesToAdd = new RoleIdType[1] { roleToAdd.Value };
			}
			RoleIdType[] rolesToRemove = null;
			if (roleToRemove.HasValue)
			{
				rolesToRemove = new RoleIdType[1] { roleToRemove.Value };
			}
			RequestToggleRoles(player, rolesToAdd, rolesToRemove);
		}

		public void RequestToggleRoles(PhotonPlayer player, RoleIdType[] rolesToAdd, RoleIdType[] rolesToRemove)
		{
			if (PhotonNetwork.inRoom)
			{
				int[] arg = RoleIdTypesToInts(rolesToAdd);
				int[] arg2 = RoleIdTypesToInts(rolesToRemove);
				base.photonView.RpcPlayer(player, RpcLocalPlayerToggleRoles, arg, arg2);
			}
		}

		[PunRPC]
		protected void RpcLocalPlayerToggleRoles(int[] rolesToAdd, int[] rolesToRemove)
		{
			if (PhotonNetwork.inRoom)
			{
				GetOrCreatePlayerRole(PhotonNetwork.player, out var role);
				role.ModifyPlayerRoles(rolesToAdd, rolesToRemove);
			}
		}

		protected void LocalPlayerSetRoles(RoleIdType newRoles)
		{
			if (PhotonNetwork.inRoom)
			{
				GetOrCreatePlayerRole(PhotonNetwork.player, out var role);
				role.SetPlayerRoles(RoleIdTypeToInt(newRoles));
			}
		}

		public void InitializeRoles()
		{
			RoleDefinitionType value = CreateRoleDefinition(0, (RoleDefinitionType)null, "Everyone");
			AddEveryoneRoleDefinition(value, this, RoleMapPriority.Default);
			SetupCustomDefaultRoleDefinitions();
			RoleDefinitionType defaultRoleDefinition = DefaultRoleDefinition;
			defaultRoleDefinition.MarkAllAsOverriden();
			allRoleDefinitions.Clear();
			List<RoleRank> playerRoleRanks = RoleRankHelper.GetPlayerRoleRanks();
			List<RoleRank> aGRoleRanks = RoleRankHelper.GetAGRoleRanks();
			for (int i = 0; i < AllRoleDefinitionIds.Length; i++)
			{
				int num = AllRoleDefinitionIds[i];
				RoleDefinitionType value2 = CreateRoleDefinition(num, (RoleDefinitionType)null);
				List<RoleRank> list = ((!IsAGRole(num)) ? playerRoleRanks : aGRoleRanks);
				RoleRank roleRank = list[0];
				list.RemoveAt(0);
				value2.RoleRank = roleRank;
				value2.IsRoleActive = false;
				allRoleDefinitions.Add(IntToRoleIdType(num), value2);
			}
			NeedsInitialization = false;
			FireOnRoleOrdersChanged();
		}

		protected virtual void SetupCustomDefaultRoleDefinitions()
		{
		}

		public void UpdatePredefinedRoles(List<RoleDefinitionType> newRoleDefs = null)
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			if (newRoleDefs == null)
			{
				newRoleDefs = new List<RoleDefinitionType>();
			}
			RoleDefinitionType everyoneRoleDefinition = EveryoneRoleDefinition;
			int everyoneRoleId = RoleIdTypeToInt(everyoneRoleDefinition.RoleId);
			if (newRoleDefs.All((RoleDefinitionType r) => RoleIdTypeToInt(r.RoleId) != everyoneRoleId))
			{
				RoleDefinitionType everyoneRoleDefinition2 = EveryoneRoleDefinition;
				everyoneRoleDefinition2.IsRoleActive = true;
				newRoleDefs.Add(EveryoneRoleDefinition);
			}
			AddRequiredRoles(ref newRoleDefs);
			HashSet<int> hashSet = new HashSet<int>();
			foreach (RoleDefinitionType newRoleDef in newRoleDefs)
			{
				RoleDefinitionType current = newRoleDef;
				RoleIdType roleId = current.RoleId;
				RoleDefinitionType roleDefinition = GetRoleDefinition(roleId);
				RoleDefinitionType value;
				if (roleDefinition.IsRoleActive && roleDefinition.IsModifiedByPlayer)
				{
					RoleDefinitionType otherRole = current;
					value = roleDefinition.CombineWith(otherRole);
				}
				else
				{
					value = current;
				}
				RoleRank roleRank = current.RoleRank;
				value.RoleRank = roleRank;
				string roleName = current.RoleName;
				value.RoleName = roleName;
				value.IsRoleActive = true;
				allRoleDefinitions[roleId] = value;
				hashSet.Add(RoleIdTypeToInt(roleId));
			}
			List<RoleRank> playerRoleRanks = RoleRankHelper.GetPlayerRoleRanks();
			for (int num = 0; num < AllRoleDefinitionIds.Length; num++)
			{
				RoleIdType roleId2 = IntToRoleIdType(AllRoleDefinitionIds[num]);
				RoleDefinitionType roleDefinition2 = GetRoleDefinition(roleId2);
				if (!playerRoleRanks.Contains(roleDefinition2.RoleRank) && !hashSet.Contains(AllRoleDefinitionIds[num]))
				{
					roleDefinition2.IsRoleActive = false;
				}
			}
			FireOnRoleOrdersChanged();
			MasterReinitializeRoles();
		}

		protected virtual void AddRequiredRoles(ref List<RoleDefinitionType> newPredefinedRoles)
		{
		}

		private void OnRoleDefinitionUpdated(int roleIdInt, RoleDefinitionType roleDef)
		{
			RoleIdType val = IntToRoleIdType(roleIdInt);
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				GetOrCreatePlayerRole(player, out var role);
				if (role.HasRole(roleIdInt))
				{
					UpdateOrCreatePlayerRoleDefinition(player);
				}
			}
			OnRoleDefinitionUpdatedEvent.Invoke(roleDef);
		}

		private void OnPlayerRoleSetUpdated(PhotonPlayer photonPlayer, int updatedRole)
		{
			UpdateOrCreatePlayerRoleDefinition(photonPlayer);
		}

		public List<RoleDefinitionType> GetSortedActiveRoles(bool reverseOrder = false)
		{
			if (allSortedActiveRoleDefinitions != null && !reverseOrder)
			{
				return allSortedActiveRoleDefinitions;
			}
			List<RoleDefinitionType> sortedActiveRoles = GetSortedActiveRoles(null, reverseOrder);
			if (!reverseOrder)
			{
				allSortedActiveRoleDefinitions = sortedActiveRoles;
			}
			return sortedActiveRoles;
		}

		private void UpdateCachedSortedActiveRoles()
		{
			allSortedActiveRoleDefinitions = GetSortedActiveRoles(null, reverseOrder: false);
			if (allSortedActiveRoleDefinitions.Count == 0)
			{
				UnityEngine.Debug.LogWarning(string.Concat(base.gameObject, " Zero active roles!"), base.gameObject);
			}
		}

		public List<RoleDefinitionType> GetSortedActiveRolesForPlayer(PhotonPlayer player, bool reverseOrder = false)
		{
			return GetSortedActiveRoles(player, reverseOrder);
		}

		private List<RoleDefinitionType> GetSortedActiveRoles(PhotonPlayer photonPlayer, bool reverseOrder)
		{
			List<RoleDefinitionType> list = new List<RoleDefinitionType>();
			RoleDefinitionType everyoneRoleDefinition = EveryoneRoleDefinition;
			RoleIdType roleId = everyoneRoleDefinition.RoleId;
			for (int i = 0; i < AllRoleDefinitionIds.Length; i++)
			{
				int roleId2 = AllRoleDefinitionIds[i];
				RoleIdType key = IntToRoleIdType(roleId2);
				RoleDefinitionType item = allRoleDefinitions[key];
				if (!item.IsRoleActive && !item.RoleId.Equals(roleId))
				{
					continue;
				}
				if (photonPlayer != null)
				{
					GetOrCreatePlayerRole(photonPlayer, out var role);
					if (role.HasRole(RoleIdTypeToInt(item.RoleId)))
					{
						list.Add(item);
					}
				}
				else
				{
					list.Add(item);
				}
			}
			list.Sort((RoleDefinitionType roleA, RoleDefinitionType roleB) => ((!reverseOrder) ? 1 : (-1)) * roleA.RoleRank.CompareTo(roleB.RoleRank));
			return list;
		}

		private List<RoleDefinitionType> GetSortedInactivePlayerRoles()
		{
			List<RoleDefinitionType> list = new List<RoleDefinitionType>();
			for (int i = 0; i < AllRoleDefinitionIds.Length; i++)
			{
				int roleId = AllRoleDefinitionIds[i];
				RoleIdType val = IntToRoleIdType(roleId);
				RoleDefinitionType item = allRoleDefinitions[val];
				if (!item.IsRoleActive && IsPlayerDefinedRole(val))
				{
					list.Add(item);
				}
			}
			list.Sort((RoleDefinitionType roleA, RoleDefinitionType roleB) => roleA.RoleRank.CompareTo(roleB.RoleRank));
			return list;
		}

		protected void UpdateLocalPlayerRoleDefinition()
		{
			if (PhotonNetwork.inRoom)
			{
				UpdateOrCreatePlayerRoleDefinition(PhotonNetwork.player);
			}
		}

		protected void UpdateAllPlayerRoleDefinitions()
		{
			if (PhotonNetwork.inRoom)
			{
				for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
				{
					PhotonPlayer player = PhotonNetwork.playerList[i];
					UpdateOrCreatePlayerRoleDefinition(player);
				}
			}
		}

		protected RoleDefinitionType UpdateOrCreatePlayerRoleDefinition(PhotonPlayer player)
		{
			if (!PhotonNetwork.inRoom || player == null)
			{
				return DefaultRoleDefinition;
			}
			if (GetOrCreatePlayerRole(player, out var _))
			{
				return _playerRoleDefinitions[player];
			}
			List<RoleDefinitionType> sortedActiveRolesForPlayer = GetSortedActiveRolesForPlayer(player);
			if (player.IsLocal)
			{
				localPlayerSortedRoleDefinitions = sortedActiveRolesForPlayer;
			}
			RoleDefinitionType value = (RoleDefinitionType)null;
			if (!_playerRoleDefinitions.TryGetValue(player, out value))
			{
				value = new RoleDefinitionType();
			}
			RoleDefinitionType defaultRoleDefinition = DefaultRoleDefinition;
			value.CombineWith(defaultRoleDefinition);
			for (int i = 0; i < sortedActiveRolesForPlayer.Count; i++)
			{
				RoleDefinitionType otherRole = sortedActiveRolesForPlayer[i];
				value.CombineWith(otherRole);
			}
			_playerRoleDefinitions[player] = value;
			if (player.IsLocal)
			{
				CachedLocalPlayerRoleDefinition = value;
			}
			value.IsRoleActive = true;
			ApplyPlayerRoleDefinition(player, value);
			OnPlayerRoleDefinitionUpdatedEvent.Invoke(player, value);
			return value;
		}

		protected abstract void ApplyPlayerRoleDefinition(PhotonPlayer player, RoleDefinitionType playerRoleDef);

		public RoleDefinitionType GetLocalPlayerRoleDefinition()
		{
			return GetPlayerRoleDefinition(PhotonNetwork.player);
		}

		public RoleDefinitionType GetPlayerRoleDefinition(PhotonPlayer player)
		{
			RoleDefinitionType value = (RoleDefinitionType)null;
			if (!_playerRoleDefinitions.TryGetValue(player, out value))
			{
				value = UpdateOrCreatePlayerRoleDefinition(player);
			}
			return value;
		}

		public bool PlayerHasRole(PhotonPlayer photonPlayer, RoleIdType role)
		{
			if (!PhotonNetwork.inRoom || photonPlayer == null)
			{
				return false;
			}
			GetOrCreatePlayerRole(photonPlayer, out var role2);
			return role2.HasRole(RoleIdTypeToInt(role));
		}

		public void RequestPlayerAddRoleToOtherPlayer(PhotonPlayer assigner, PhotonPlayer assignee, RoleIdType roleToAdd)
		{
			if (PlayerCanAssignRole(assigner, assignee, roleToAdd))
			{
				base.photonView.RpcPlayer(assignee, RpcPlayerAddRoleToLocalPlayer, assigner, RoleIdTypeToInt(roleToAdd));
			}
		}

		[PunRPC]
		protected void RpcPlayerAddRoleToLocalPlayer(PhotonPlayer assigner, int roleToAdd)
		{
			if (PlayerCanAssignRole(assigner, PhotonNetwork.player, IntToRoleIdType(roleToAdd)))
			{
				GetOrCreatePlayerRole(PhotonNetwork.player, out var role);
				role.AddRole(roleToAdd);
			}
		}

		public void RequestPlayerRemoveRoleFromOtherPlayer(PhotonPlayer assigner, PhotonPlayer assignee, RoleIdType roleToRemove)
		{
			if (PlayerCanAssignRole(assigner, assignee, roleToRemove))
			{
				base.photonView.RpcPlayer(assignee, RpcPlayerRemoveRoleFromLocalPlayer, assigner, RoleIdTypeToInt(roleToRemove));
			}
		}

		[PunRPC]
		protected void RpcPlayerRemoveRoleFromLocalPlayer(PhotonPlayer assigner, int roleToRemove)
		{
			if (PlayerCanAssignRole(assigner, PhotonNetwork.player, IntToRoleIdType(roleToRemove)))
			{
				GetOrCreatePlayerRole(PhotonNetwork.player, out var role);
				role.RemoveRole(roleToRemove);
			}
