		public bool LocalRequestModifyRolePermission(RoleIdType roleId, RolePermissionType rolePermission, bool overrides, object arg)
		{
			if (!PlayerCanModifyRoleDefinition(PhotonNetwork.player, roleId))
			{
				return false;
			}
			RoleDefinitionType val = allRoleDefinitions[roleId];
			byte[] arg2 = val.RequestRoleModification(rolePermission, overrides, arg);
			base.photonView.RpcMaster(RpcMasterRequestModifyRoleDefinition, roleId, rolePermission, arg2);
			return true;
		}

		[PunRPC]
		protected void RpcMasterRequestModifyRoleDefinition(RoleIdType roleId, RolePermissionType rolePermission, byte[] newPermissionBytes, PhotonMessageInfo messageInfo)
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!PlayerCanModifyRoleDefinition(messageInfo.sender, roleId))
				{
					UnityEngine.Debug.LogWarning(string.Concat(messageInfo.sender, " tried to modify role, but they couldn't!"));
				}
				else
				{
					base.photonView.RpcAll(RpcModifyRoleDefinition, roleId, rolePermission, newPermissionBytes);
				}
			}
		}

		[PunRPC]
		protected void RpcModifyRoleDefinition(RoleIdType roleId, RolePermissionType permission, byte[] newPermissionBytes, PhotonMessageInfo messageInfo)
		{
			RoleDefinitionType val = allRoleDefinitions[roleId];
			val.ApplyRoleModification(permission, newPermissionBytes);
			allRoleDefinitions[roleId] = val;
			OnRoleDefinitionUpdated(RoleIdTypeToInt(roleId), val);
		}

		public void PlayerRequestMoveRole(PhotonPlayer mover, RoleIdType roleIdToMove, bool up)
		{
			if (PhotonNetwork.inRoom && CanMoveRole(mover, roleIdToMove, up, out var otherRole))
			{
				base.photonView.RpcMaster(RpcMasterRequestMoveRole, roleIdToMove, up, otherRole.RoleId);
			}
		}

		[PunRPC]
		protected void RpcMasterRequestMoveRole(RoleIdType roleIdToMove, bool up, RoleIdType expectedOtherRoleId, PhotonMessageInfo messageInfo)
		{
			if (PhotonNetwork.isMasterClient && CanMoveRole(messageInfo.sender, roleIdToMove, up, out var otherRole) && RoleIdTypeToInt(expectedOtherRoleId) == RoleIdTypeToInt(otherRole.RoleId))
			{
				base.photonView.RpcAll(RpcSwapRoleOrder, roleIdToMove, otherRole.RoleId);
			}
		}

		[PunRPC]
		protected void RpcSwapRoleOrder(RoleIdType roleIdToMove, RoleIdType otherRoleId, PhotonMessageInfo messageInfo)
		{
			RoleDefinitionType val = allRoleDefinitions[roleIdToMove];
			RoleDefinitionType val2 = allRoleDefinitions[otherRoleId];
			RoleRank roleRank = val2.RoleRank;
			RoleRank roleRank2 = val.RoleRank;
			val2.RoleRank = roleRank2;
			val.RoleRank = roleRank;
			FireOnRoleOrdersChanged();
		}

		public bool CanMoveRole(PhotonPlayer mover, RoleIdType roleIdToMove, bool up, out RoleDefinitionType otherRole)
		{
			RoleDefinitionType roleDefinition = GetRoleDefinition(roleIdToMove);
			otherRole = (RoleDefinitionType)null;
			if (!IsPlayerDefinedRole(roleIdToMove))
			{
				return false;
			}
			if (!roleDefinition.CanMoveRole)
			{
				return false;
			}
			RoleDefinitionType nextRole = GetNextRole(roleDefinition, up);
			if (nextRole == null || !nextRole.CanMoveRole)
			{
				return false;
			}
			if (mover != null && !PlayerCanMoveRole(mover, roleDefinition, nextRole))
			{
				return false;
			}
			otherRole = nextRole;
			return true;
		}

		private RoleDefinitionType GetNextRole(RoleDefinitionType rowToMove, bool up)
		{
			int indexOffset = (up ? 1 : (-1));
			RoleRank rank = rowToMove.RoleRank;
			return (from _ in allRoleDefinitions
				select _.Value into r
				where r.IsRoleActive && (int)r.RoleRank == (int)rank + indexOffset
				select r).FirstOrDefault();
		}

		protected virtual bool PlayerCanMoveRole(PhotonPlayer mover, RoleDefinitionType roleToMove, RoleDefinitionType otherRole)
		{
			return PhotonNetwork.inRoom;
		}

		public bool PlayerCanCreateRole(PhotonPlayer photonPlayer, out RoleDefinitionType nextRole)
		{
			nextRole = (RoleDefinitionType)null;
			if (!PhotonNetwork.inRoom)
			{
				return false;
			}
			if (!PlayerCanModifyRoles(photonPlayer))
			{
				return false;
			}
			if (!TryGetNextInactivePlayerRole(out nextRole))
			{
				return false;
			}
			return true;
		}

		public bool LocalRequestCreateRole(string newRoleName)
		{
			if (!PlayerCanCreateRole(PhotonNetwork.player, out var _))
			{
				return false;
			}
			base.photonView.RpcMaster(RpcMasterRequestCreateRole, newRoleName);
			return true;
		}

		[PunRPC]
		protected void RpcMasterRequestCreateRole(string newRoleName, PhotonMessageInfo messageInfo)
		{
			if (PhotonNetwork.isMasterClient && PlayerCanCreateRole(messageInfo.sender, out var nextRole))
			{
				base.photonView.RpcAll(RpcAddNewPlayerRole, newRoleName, nextRole.RoleId);
			}
		}

		[PunRPC]
		protected void RpcAddNewPlayerRole(string newRoleName, RoleIdType roleId)
		{
			RoleDefinitionType roleDefinition = GetRoleDefinition(roleId);
			roleDefinition.Reset();
			roleDefinition.RoleName = newRoleName;
			roleDefinition.IsRoleActive = true;
			FireOnRoleOrdersChanged();
		}

		protected virtual bool PlayerCanModifyRoles(PhotonPlayer player)
		{
			return PhotonNetwork.inRoom;
		}

		private bool TryGetNextInactivePlayerRole(out RoleDefinitionType nextRole)
		{
			nextRole = (RoleDefinitionType)null;
			List<RoleDefinitionType> sortedInactivePlayerRoles = GetSortedInactivePlayerRoles();
			if (sortedInactivePlayerRoles.Count > 0)
			{
				nextRole = sortedInactivePlayerRoles[0];
			}
			return nextRole != null;
		}

		public bool PlayerCanDeleteRole(RoleIdType roleIdToRemove, PhotonPlayer photonPlayer)
		{
			if (!PhotonNetwork.inRoom)
			{
				return false;
			}
			if (!IsPlayerDefinedRole(roleIdToRemove))
			{
				return false;
			}
			if (!PlayerCanModifyRoles(photonPlayer))
			{
				return false;
			}
			RoleDefinitionType val = allRoleDefinitions[roleIdToRemove];
			if (!val.IsRoleActive)
			{
				return false;
			}
			return true;
		}

		public bool LocalRequestDeleteRole(RoleIdType roleIdToRemove)
		{
			if (!PlayerCanDeleteRole(roleIdToRemove, PhotonNetwork.player))
			{
				return false;
			}
			base.photonView.RpcMaster(RpcMasterRequestDeleteRole, roleIdToRemove);
			return true;
		}

		[PunRPC]
		protected void RpcMasterRequestDeleteRole(RoleIdType roleIdToRemove, PhotonMessageInfo messageInfo)
		{
			if (PhotonNetwork.isMasterClient && PlayerCanDeleteRole(roleIdToRemove, messageInfo.sender))
			{
				base.photonView.RpcAll(RpcDeletePlayerRole, roleIdToRemove);
			}
		}

		[PunRPC]
		protected void RpcDeletePlayerRole(RoleIdType roleIdToRemove, PhotonMessageInfo messageInfo)
		{
			RoleDefinitionType val = allRoleDefinitions[roleIdToRemove];
			val.IsRoleActive = false;
			if (PhotonNetwork.isMasterClient)
			{
				PhotonPlayer[] playerList = PhotonNetwork.playerList;
				foreach (PhotonPlayer player in playerList)
				{
					GetOrCreatePlayerRole(player, out var role);
					role.RemoveRole(RoleIdTypeToInt(roleIdToRemove));
				}
			}
			FireOnRoleOrdersChanged();
		}

		public abstract bool IsPlayerDefinedRole(RoleIdType roleId);

		public bool AnyRole(AnyDelegate any)
		{
			foreach (RoleDefinitionType value in allRoleDefinitions.Values)
			{
				if (any(value))
				{
					return true;
				}
			}
			return false;
		}

		public bool AnyPlayerRole(AnyDelegate any)
		{
			for (int i = 0; i < PhotonNetwork.playerList.Length; i++)
			{
				PhotonPlayer player = PhotonNetwork.playerList[i];
				RoleDefinitionType playerRoleDefinition = GetPlayerRoleDefinition(player);
				if (any(playerRoleDefinition))
				{
					return true;
				}
			}
			return false;
		}

		private void FireOnRoleOrdersChanged()
		{
			UpdateCachedSortedActiveRoles();
			UpdateAllPlayerRoleDefinitions();
			OnRoleOrdersChangedEvent.Invoke();
		}

		public RoleDefinitionType FindActiveRoleByName(string newRoleName)
		{
			return (from _ in allRoleDefinitions
				select _.Value into r
				where r.IsRoleActive && r.RoleName.ToLowerInvariant() == newRoleName.ToLowerInvariant()
				select r).FirstOrDefault();
		}

		public RoleDefinitionType GetRoleDefinition(RoleIdType roleId)
		{
			return allRoleDefinitions[roleId];
		}

		public virtual bool PlayerCanModifyRoleDefinition(PhotonPlayer modifier, RoleIdType roleId)
		{
			return PhotonNetwork.inRoom;
		}

		public virtual bool PlayerCanAssignRole(PhotonPlayer assigner, PhotonPlayer assignee, RoleIdType roleId)
		{
			return PhotonNetwork.inRoom;
		}

		protected RoleRank FindPlayerHighestRoleRank(PhotonPlayer player)
		{
			RoleDefinitionType playerRoleDefinition = GetPlayerRoleDefinition(player);
			return playerRoleDefinition.RoleRank;
		}

		public RoleRank FindRoleRank(RoleIdType roleId)
		{
			if (allRoleDefinitions.TryGetValue(roleId, out var value))
			{
				return value.RoleRank;
			}
			UnityEngine.Debug.LogError("RoleId with no Rank!");
			return RoleRank.INVALID;
		}

		private void OnPhotonPlayerConnected(PhotonPlayer photonPlayer)
		{
			if (PhotonNetwork.isMasterClient)
			{
				base.photonView.RpcPlayer(photonPlayer, RpcReinitializeRoles, SerializeRoleCollection().ToByteArray());
			}
			GetOrCreatePlayerRole(photonPlayer, out var _);
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer photonPlayer)
		{
			_playerRoleDefinitions.Remove(photonPlayer);
			DestroyPlayerRoleset(photonPlayer.ID);
		}

		private void DestroyPlayerRoleset(int photonPlayerID)
		{
			if (playerRoleSets.TryGetValue(photonPlayerID, out var value))
			{
				value.Clear();
				playerRoleSets.Remove(photonPlayerID);
			}
		}

		private void OnPhotonMasterClientSwitched(PhotonPlayer newMaster)
		{
			MasterReinitializeRoles();
		}

		private void MasterReinitializeRoles()
		{
			if (PhotonNetwork.isMasterClient && PhotonNetwork.otherPlayers.Length > 0)
			{
				base.photonView.RpcOthers(RpcReinitializeRoles, SerializeRoleCollection().ToByteArray());
			}
		}

		[PunRPC]
		protected void RpcReinitializeRoles(byte[] roleCollectionBytes, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
				DeserializeRoleCollection(ParseRoleCollection(roleCollectionBytes));
			}
		}

		protected abstract RoleCollectionProtobufType GetCollectionFromRoomData(PersistedRoomData roomData);

		protected abstract void SetCollectionInRoomData(ref PersistedRoomData roomData, RoleCollectionProtobufType roleCollection);

		protected void DeserializeRoleCollection(RoleCollectionProtobufType roleCollection)
		{
			for (int i = 0; i < AllRoleDefinitionIds.Length; i++)
			{
				RoleIdType roleId = IntToRoleIdType(AllRoleDefinitionIds[i]);
				if (IsPlayerDefinedRole(roleId))
				{
					RoleDefinitionType roleDefinition = GetRoleDefinition(roleId);
					roleDefinition.IsRoleActive = false;
				}
			}
			_DeserializeRoleCollection(roleCollection);
			FireOnRoleOrdersChanged();
		}

		protected abstract RoleCollectionProtobufType ParseRoleCollection(byte[] roleCollectionBytes);

		protected abstract void _DeserializeRoleCollection(RoleCollectionProtobufType roleCollection);

		protected abstract RoleCollectionProtobufType SerializeRoleCollection();

		protected virtual void RunBackwardsCompatibilityMigration(PersistedRoomData roomData)
		{
		}

		public void DeserializeFrom(PersistedRoomData roomData)
		{
			RoleCollectionProtobufType collectionFromRoomData = GetCollectionFromRoomData(roomData);
			DeserializeRoleCollection(collectionFromRoomData);
			RunBackwardsCompatibilityMigration(roomData);
			MasterReinitializeRoles();
		}

		public void SerializeTo(ref PersistedRoomData roomData)
		{
			RoleCollectionProtobufType roleCollection = SerializeRoleCollection();
			SetCollectionInRoomData(ref roomData, roleCollection);
		}
	}
