		public RoomRole CombineWith(RoomRole otherRole)
		{
			RoleRank = otherRole.RoleRank;
			if (otherRole.RoleId == RoomRoleId.AG_EVERYONE)
			{
				RoleId = RoomRoleId.AG_EVERYONE;
			}
			else
			{
				RoleId |= otherRole.RoleId;
			}
			IsModifiedByPlayer |= otherRole.IsModifiedByPlayer;
			canEditRoomRoles.CombineWith(otherRole.canEditRoomRoles);
			canEditGameRoles.CombineWith(otherRole.canEditGameRoles);
			voteKickPermission.CombineWith(otherRole.voteKickPermission);
			canInvite.CombineWith(otherRole.canInvite);
			canEditCircuits.CombineWith(otherRole.canEditCircuits);
			canTalk.CombineWith(otherRole.canTalk);
			canPrintPhotos.CombineWith(otherRole.canPrintPhotos);
			canStartGames.CombineWith(otherRole.canStartGames);
			canChangeGameMode.CombineWith(otherRole.canChangeGameMode);
			canSelfRevive.CombineWith(otherRole.canSelfRevive);
			canEditGameSettings.CombineWith(otherRole.canEditGameSettings);
			autoAssignedGameRoles.CombineWith(otherRole.autoAssignedGameRoles);
			canUseMakerPen.CombineWith(otherRole.canUseMakerPen);
			canUseDeleteAllButton.CombineWith(otherRole.canUseDeleteAllButton);
			return this;
		}

