			canInvite.Copy(roleToCopy.canInvite);
			canEditCircuits.Copy(roleToCopy.canEditCircuits);
			canTalk.Copy(roleToCopy.canTalk);
			canPrintPhotos.Copy(roleToCopy.canPrintPhotos);
			canStartGames.Copy(roleToCopy.canStartGames);
			canChangeGameMode.Copy(roleToCopy.canChangeGameMode);
			canSelfRevive.Copy(roleToCopy.canSelfRevive);
			canEditGameSettings.Copy(roleToCopy.canEditGameSettings);
			autoAssignedGameRoles.Copy(roleToCopy.autoAssignedGameRoles);
			canUseMakerPen.Copy(roleToCopy.canUseMakerPen);
