		public byte[] RequestRoleModification(RolePermission rolePermission, bool overrides, object arg)
		{
			return rolePermission switch
			{
				RolePermission.CAN_EDIT_ROOM_ROLES => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_EDIT_GAME_ROLES => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.VOTE_KICK_PERMISSION => new MutableOverridableInt(overrides, (int)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_INVITE => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_EDIT_CIRCUITS => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_TALK => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_PRINT_PHOTOS => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_START_GAMES => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_CHANGE_GAME_MODE => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_SELF_REVIVE => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_EDIT_GAME_SETTINGS => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.AUTO_ASSIGNED_GAME_ROLES => new MutableOverridableListString(overrides, (List<string>)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_USE_MAKER_PEN => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				RolePermission.CAN_USE_DELETE_ALL_BUTTON => new MutableOverridableBool(overrides, (bool)arg).SerializeToProtobuf().ToByteArray(), 
				_ => throw new InvalidOperationException("Unknown RolePermission " + rolePermission), 
			};
		}

		public void ApplyRoleModification(RolePermission rolePermission, byte[] permissionUpdate)
		{
			switch (rolePermission)
			{
			case RolePermission.CAN_EDIT_ROOM_ROLES:
				canEditRoomRoles.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_EDIT_GAME_ROLES:
				canEditGameRoles.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.VOTE_KICK_PERMISSION:
				voteKickPermission.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_INVITE:
				canInvite.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_EDIT_CIRCUITS:
				canEditCircuits.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_TALK:
				canTalk.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_PRINT_PHOTOS:
				canPrintPhotos.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_START_GAMES:
				canStartGames.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_CHANGE_GAME_MODE:
				canChangeGameMode.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_SELF_REVIVE:
				canSelfRevive.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_EDIT_GAME_SETTINGS:
				canEditGameSettings.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.AUTO_ASSIGNED_GAME_ROLES:
				autoAssignedGameRoles.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_USE_MAKER_PEN:
				canUseMakerPen.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			case RolePermission.CAN_USE_DELETE_ALL_BUTTON:
				canUseDeleteAllButton.DeserializeFromProtobufBytes(permissionUpdate);
				break;
			default:
				throw new InvalidOperationException("Unknown RolePermission " + rolePermission);
			}
			IsModifiedByPlayer = true;
			if (OnRolePermissionUpdated != null)
			{
				OnRolePermissionUpdated(rolePermission, GetFieldFor(rolePermission));
			}
		}

		public IOverridableField GetFieldFor(RolePermission rolePermission)
		{
			return rolePermission switch
			{
				RolePermission.CAN_EDIT_ROOM_ROLES => canEditRoomRoles, 
				RolePermission.CAN_EDIT_GAME_ROLES => canEditGameRoles, 
				RolePermission.VOTE_KICK_PERMISSION => voteKickPermission, 
				RolePermission.CAN_INVITE => canInvite, 
				RolePermission.CAN_EDIT_CIRCUITS => canEditCircuits, 
				RolePermission.CAN_TALK => canTalk, 
				RolePermission.CAN_PRINT_PHOTOS => canPrintPhotos, 
				RolePermission.CAN_START_GAMES => canStartGames, 
				RolePermission.CAN_CHANGE_GAME_MODE => canChangeGameMode, 
				RolePermission.CAN_SELF_REVIVE => canSelfRevive, 
				RolePermission.CAN_EDIT_GAME_SETTINGS => canEditGameSettings, 
				RolePermission.AUTO_ASSIGNED_GAME_ROLES => autoAssignedGameRoles, 
				RolePermission.CAN_USE_MAKER_PEN => canUseMakerPen, 
				RolePermission.CAN_USE_DELETE_ALL_BUTTON => canUseDeleteAllButton, 
				_ => throw new InvalidOperationException("Unknown RolePermission " + rolePermission), 
			};
		}

		public PlayerRoomRoleData SerializeToProtobuf()
		{
			PlayerRoomRoleData playerRoomRoleData = new PlayerRoomRoleData();
			playerRoomRoleData.RoleId = (int)RoleId;
			playerRoomRoleData.RoleRank = (int)RoleRank;
			playerRoomRoleData.RoleVersion = 5;
			playerRoomRoleData.IsModifiedByPlayer = IsModifiedByPlayer;
			playerRoomRoleData.IsRoleActive = IsRoleActive;
			playerRoomRoleData.RoleName = RoleName;
			playerRoomRoleData.CanEditRoomRoles = canEditRoomRoles.SerializeToProtobuf();
			playerRoomRoleData.CanEditGameRoles = canEditGameRoles.SerializeToProtobuf();
			playerRoomRoleData.VoteKickPermission = voteKickPermission.SerializeToProtobuf();
			playerRoomRoleData.CanInvite = canInvite.SerializeToProtobuf();
			playerRoomRoleData.CanEditCircuits = canEditCircuits.SerializeToProtobuf();
			playerRoomRoleData.CanTalk = canTalk.SerializeToProtobuf();
			playerRoomRoleData.CanPrintPhotos = canPrintPhotos.SerializeToProtobuf();
			playerRoomRoleData.CanStartGames = canStartGames.SerializeToProtobuf();
			playerRoomRoleData.CanChangeGameMode = canChangeGameMode.SerializeToProtobuf();
			playerRoomRoleData.CanSelfRevive = canSelfRevive.SerializeToProtobuf();
			playerRoomRoleData.CanEditGameSettings = canEditGameSettings.SerializeToProtobuf();
			playerRoomRoleData.AutoAssignedGameRoles = autoAssignedGameRoles.SerializeToProtobuf();
			playerRoomRoleData.CanUseMakerPen = canUseMakerPen.SerializeToProtobuf();
			playerRoomRoleData.CanUseDeleteAllButton = canUseDeleteAllButton.SerializeToProtobuf();
			return playerRoomRoleData;
		}

		public void DeserializeFromProtobufData(PlayerRoomRoleData protobufData)
		{
			RoleRank = (RoleRank)protobufData.RoleRank;
			IsRoleActive = protobufData.IsRoleActive;
			IsModifiedByPlayer = protobufData.IsModifiedByPlayer;
			RoleName = protobufData.RoleName;
			if (protobufData.RoleVersion >= 0)
			{
				canEditRoomRoles.DeserializeFromProtobuf(protobufData.CanEditRoomRoles);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canEditGameRoles.DeserializeFromProtobuf(protobufData.CanEditGameRoles);
			}
			if (protobufData.RoleVersion >= 0)
			{
				voteKickPermission.DeserializeFromProtobuf(protobufData.VoteKickPermission);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canInvite.DeserializeFromProtobuf(protobufData.CanInvite);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canEditCircuits.DeserializeFromProtobuf(protobufData.CanEditCircuits);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canTalk.DeserializeFromProtobuf(protobufData.CanTalk);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canPrintPhotos.DeserializeFromProtobuf(protobufData.CanPrintPhotos);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canStartGames.DeserializeFromProtobuf(protobufData.CanStartGames);
			}
			if (protobufData.RoleVersion >= 3)
			{
				canChangeGameMode.DeserializeFromProtobuf(protobufData.CanChangeGameMode);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canSelfRevive.DeserializeFromProtobuf(protobufData.CanSelfRevive);
			}
			if (protobufData.RoleVersion >= 0)
			{
				canEditGameSettings.DeserializeFromProtobuf(protobufData.CanEditGameSettings);
			}
			if (protobufData.RoleVersion >= 0)
			{
				autoAssignedGameRoles.DeserializeFromProtobuf(protobufData.AutoAssignedGameRoles);
			}
			if (protobufData.RoleVersion >= 4)
			{
				canUseMakerPen.DeserializeFromProtobuf(protobufData.CanUseMakerPen);
			}
			if (protobufData.RoleVersion >= 5)
			{
				canUseDeleteAllButton.DeserializeFromProtobuf(protobufData.CanUseDeleteAllButton);
			}
			RoleId = (RoomRoleId)protobufData.RoleId;
		}
	}
