	public class EditRoomRoleOrdersWatchUIFlow : WatchUIFlow
	{
		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		[SerializeField]
		private ToggleButton3D showOnlyMyRolesToggle;

		public RoomRolePagedGrid grid;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<RoleViewMode> m_OnRoleViewModeChangedEvent;

		private RoleViewMode _roleViewMode = RoleViewMode.Invalid;

		public RoleViewMode RoleViewMode
		{
			get
			{
				return _roleViewMode;
			}
			set
			{
				RoleViewMode roleViewMode = value;
				if (roleViewMode == RoleViewMode.Edit && !PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value)
				{
					roleViewMode = RoleViewMode.View;
				}
				if (roleViewMode != _roleViewMode)
				{
					_roleViewMode = roleViewMode;
					grid.UpdateChildren(_roleViewMode, showOnlyMyRolesToggle.IsOn);
					this.OnRoleViewModeChangedEvent.SafeInvoke(_roleViewMode);
				}
			}
		}

		public event Action<RoleViewMode> OnRoleViewModeChangedEvent
		{
			add
			{
				Action<RoleViewMode> action = this.m_OnRoleViewModeChangedEvent;
				Action<RoleViewMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnRoleViewModeChangedEvent, (Action<RoleViewMode>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<RoleViewMode> action = this.m_OnRoleViewModeChangedEvent;
				Action<RoleViewMode> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnRoleViewModeChangedEvent, (Action<RoleViewMode>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void Awake()
		{
			RolePermissionEditable[] componentsInChildren = GetComponentsInChildren<RolePermissionEditable>();
			RolePermissionEditable[] array = componentsInChildren;
			foreach (RolePermissionEditable rolePermissionEditable in array)
			{
				rolePermissionEditable.UpdateForPermissionType(RolePermissionTypes.Room);
			}
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			RoleViewMode = (PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditRoomRoles.Value ? RoleViewMode.Edit : RoleViewMode.View);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
			OnPlayerRoomRoleDefinitionUpdated(PhotonNetwork.player, PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition());
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoomRoleDefinitionUpdated);
		}

		private void OnPlayerRoomRoleDefinitionUpdated(PhotonPlayer player, RoomRole roleDef)
		{
			if (player.IsLocal)
			{
				RoleViewMode roleViewMode = RoleViewMode;
				RoleViewMode = (roleDef.CanEditRoomRoles.Value ? RoleViewMode.Edit : RoleViewMode.View);
				if (roleViewMode == RoleViewMode)
				{
					grid.UpdateChildren(_roleViewMode, showOnlyMyRolesToggle.IsOn);
				}
			}
		}

		public void Toggle_ShowOnlyMyRoles()
		{
			grid.UpdateChildren(_roleViewMode, showOnlyMyRolesToggle.IsOn);
		}

		public void Button_AddRole()
		{
			IPromise<TextInputUIDialog.InputResponse> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.Standard, "New Role Name", "Enter the name of your new role.", "Create", purifyText: true, 40, null, shouldFocusInputField: false));
			promise.Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative)
				{
					string textInput = r.TextInput;
					if (!string.IsNullOrEmpty(textInput))
					{
						RoomRole roomRole = PlayerRoomRoleManager.Instance.FindActiveRoleByName(textInput);
						if (roomRole == null)
						{
							PlayerRoomRoleManager.Instance.LocalRequestCreateRole(textInput);
						}
						else
						{
							Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Role Name Taken!", "That role name is already taken.");
						}
					}
					else
					{
						Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Invalid Role Name!", "Please enter a valid role name.");
					}
				}
			});
		}
	}
	public class EditRoomRoleSettingsWatchUIFlow : WatchUIFlow
	{
		[SerializeField]
		private RoomRoleId _roleId;

		private bool isDefaultRoleDefinition;

		private RoleViewMode _roleViewMode;

		private List<RolePermissionEditable> roleEditables = new List<RolePermissionEditable>();

		[SerializeField]
		private PagedGrid socialPermissionsPagedGrid;

		[SerializeField]
		private IntRoomRolePermissionEditable hostVoteKickEditable;

		[SerializeField]
		private NonHostVotekickEditable nonHostVoteKickEditable;

		[SerializeField]
		private PagedGrid creativePermissionsPagedGrid;

		[SerializeField]
		private BoolRoomRolePermissionEditable canEditRoomRolesEditable;

		[SerializeField]
		private BoolRoomRolePermissionEditable canEditGameRolesEditable;

		[SerializeField]
		private BoolRoomRolePermissionEditable canUseMakerPenEditable;

		public void SetRoleId(RoomRoleId roleId, RoleViewMode roleViewMode, bool isDefaultGameRoleDefinition)
		{
			_roleId = roleId;
			_roleViewMode = roleViewMode;
			isDefaultRoleDefinition = isDefaultGameRoleDefinition;
			OnRoleIdUpdated();
		}

		private void Awake()
		{
			RolePermissionEditable[] componentsInChildren = GetComponentsInChildren<RolePermissionEditable>();
			RolePermissionEditable[] array = componentsInChildren;
			foreach (RolePermissionEditable rolePermissionEditable in array)
			{
				rolePermissionEditable.UpdateForPermissionType(RolePermissionTypes.Room);
			}
			roleEditables.AddRange(GetComponentsInChildren<RolePermissionEditable>(includeInactive: true));
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			OnPlayerRoleDefinitionUpdated(PhotonNetwork.player, PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition());
			OnRoleIdUpdated();
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RoomRole roleDef)
		{
			if (player.IsLocal && !PlayerRoomRoleManager.Instance.PlayerCanModifyRoleDefinition(player, _roleId))
			{
				SetRoleId(_roleId, RoleViewMode.View, isDefaultRoleDefinition);
			}
		}

		private void OnRoleIdUpdated()
		{
			for (int i = 0; i < roleEditables.Count; i++)
			{
				((IRolePermissionEditable<RoomRoleId>)roleEditables[i]).SetRoleId(_roleId, _roleViewMode, isDefaultRoleDefinition);
			}
			RoomRole roleDefinition = PlayerRoomRoleManager.Instance.GetRoleDefinition(RoomRoleId.AG_HOST);
			RoomRole roleDefinition2 = PlayerRoomRoleManager.Instance.GetRoleDefinition(RoomRoleId.AG_CREATOR);
			bool flag = PlayerRoomRoleManager.Instance.FindRoleRank(_roleId) >= roleDefinition.RoleRank;
			bool flag2 = PlayerRoomRoleManager.Instance.FindRoleRank(_roleId) >= roleDefinition2.RoleRank;
			if (flag)
			{
				socialPermissionsPagedGrid.RemoveIgnoredChild(hostVoteKickEditable.transform);
				socialPermissionsPagedGrid.AddIgnoredChild(nonHostVoteKickEditable.transform);
			}
			else
			{
				socialPermissionsPagedGrid.AddIgnoredChild(hostVoteKickEditable.transform);
				socialPermissionsPagedGrid.RemoveIgnoredChild(nonHostVoteKickEditable.transform);
			}
			socialPermissionsPagedGrid.RefreshChildren(includeDisabled: true);
			if (flag && !flag2)
			{
				creativePermissionsPagedGrid.RemoveIgnoredChild(canEditGameRolesEditable.transform);
				creativePermissionsPagedGrid.RemoveIgnoredChild(canEditRoomRolesEditable.transform);
			}
			else
			{
				creativePermissionsPagedGrid.AddIgnoredChild(canEditGameRolesEditable.transform);
				creativePermissionsPagedGrid.AddIgnoredChild(canEditRoomRolesEditable.transform);
			}
			if (!GameSessions.LocalGameSession.IsSandbox)
			{
				creativePermissionsPagedGrid.AddIgnoredChild(canUseMakerPenEditable.transform);
			}
			creativePermissionsPagedGrid.RefreshChildren(includeDisabled: true);
			RoomRole titleText = null;
			if (PlayerRoomRoleManager.Instance != null)
			{
				titleText = ((!isDefaultRoleDefinition) ? PlayerRoomRoleManager.Instance.GetRoleDefinition(_roleId) : PlayerRoomRoleManager.Instance.DefaultRoleDefinition);
			}
			SetTitleText(titleText);
		}

		private void SetTitleText(RoomRole roleDef)
		{
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				string arg = "[Invalid Role]";
				if (roleDef != null)
				{
					arg = roleDef.RoleName;
				}
				componentInChildren.Title = $"{arg} Permissions";
			}
		}
	}
