			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnRoleOrdersChangedEvent -= new Action(OnRoleOrdersChanged);
		}

		private void OnRoleOrdersChanged()
		{
			UpdateButtons();
		}

		public void SetRole(RoomRole item, int activeIndex, RoleViewMode roleViewMode, bool isDefaultGameRoleDefinition)
		{
			bool flag = PlayerRoomRoleManager.Instance.IsPlayerDefinedRole(item.RoleId);
			_isDefaultGameRoleDefinition = isDefaultGameRoleDefinition;
			_roleViewMode = roleViewMode;
			settingsButtonImage.sprite = (isDefaultGameRoleDefinition ? viewRoleSprite : ((_roleViewMode != RoleViewMode.Edit) ? viewRoleSprite : editRoleSprite));
			currentRoomRole = item;
			if (currentRoomRole != null && text != null)
			{
				text.text = currentRoomRole.RoleName;
			}
			Color color = (isDefaultGameRoleDefinition ? defaultRoleColor : ((!flag) ? agRoleColor : nonAGRoleColor));
			if (!isDefaultGameRoleDefinition && activeIndex % 2 == 0)
			{
				color *= 0.85f;
				color.a = 1f;
			}
			bgImage.color = color;
			UpdateButtons();
		}

		private void UpdateButtons()
		{
			bool flag = PlayerRoomRoleManager.Instance.IsPlayerDefinedRole(currentRoomRole.RoleId);
			bool flag2 = _roleViewMode == RoleViewMode.Edit;
			bool active = flag2 && flag;
			deleteButton.gameObject.SetActive(active);
			moveUpButton.gameObject.SetActive(value: false);
			moveDownButton.gameObject.SetActive(value: false);
			addRemovePlayerButton.Interactable = !_isDefaultGameRoleDefinition && currentRoomRole.RoleId != RoomRoleId.AG_EVERYONE && currentRoomRole.RoleId != RoomRoleId.AG_CREATOR;
			settingsButtonImage.sprite = (_isDefaultGameRoleDefinition ? viewRoleSprite : ((_roleViewMode != RoleViewMode.Edit) ? viewRoleSprite : editRoleSprite));
			deleteButton.Interactable = flag2 && currentRoomRole != null && currentRoomRole.RoleId != RoomRoleId.AG_CREATOR && PlayerRoomRoleManager.Instance.PlayerCanDeleteRole(currentRoomRole.RoleId, PhotonNetwork.player);
			settingsButton.Interactable = currentRoomRole != null && (!flag2 || PlayerRoomRoleManager.Instance.PlayerCanModifyRoleDefinition(PhotonNetwork.player, currentRoomRole.RoleId));
			moveUpButton.Interactable = flag2 && currentRoomRole != null && PlayerRoomRoleManager.Instance.CanMoveRole(PhotonNetwork.player, currentRoomRole.RoleId, up: true, out var otherRole);
			moveDownButton.Interactable = flag2 && currentRoomRole != null && PlayerRoomRoleManager.Instance.CanMoveRole(PhotonNetwork.player, currentRoomRole.RoleId, up: false, out otherRole);
		}

		public void Button_MoveUp()
		{
			PlayerRoomRoleManager.Instance.PlayerRequestMoveRole(PhotonNetwork.player, currentRoomRole.RoleId, up: true);
		}

		public void Button_MoveDown()
		{
			PlayerRoomRoleManager.Instance.PlayerRequestMoveRole(PhotonNetwork.player, currentRoomRole.RoleId, up: false);
		}

		public void Button_AddRemovePlayer()
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryConfirmationDialog(addRemovePlayersRoomRolesDialog, currentRoomRole, (WatchAttractor.EffectFlags)0);
		}

		public void Button_Settings()
		{
			EditRoomRoleSettingsWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<EditRoomRoleSettingsWatchUIFlow>();
			flowByType.SetRoleId(currentRoomRole.RoleId, _roleViewMode, _isDefaultGameRoleDefinition);
			Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
		}

		public void Button_Remove()
		{
			IPromise<ConfirmDialogResponses> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Are you sure?", "Are you sure you want to remove the role \"" + currentRoomRole.RoleName + "\"?");
			promise.Then(delegate(ConfirmDialogResponses r)
			{
				if (r == ConfirmDialogResponses.Affirmative)
				{
					PlayerRoomRoleManager.Instance.LocalRequestDeleteRole(currentRoomRole.RoleId);
				}
			});
		}
	}
	public class RoomRolePagedGrid : RecyclerPagedGrid<RoomRolePagedGrid.RoomRoleUI, RoomRoleEditRow>
	{
		public struct RoomRoleUI
		{
			public RoomRole CurrentRoomRole;

			public bool IsDefaultRoleDefinition;
		}

		private RoleViewMode _viewMode;

		private bool _showOnlyMyRoles;

		private void OnEnable()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnRoleOrdersChangedEvent += new Action(UpdateChildren);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRolesUpdated);
			UpdateChildren();
		}

		private void OnDisable()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnRoleOrdersChangedEvent -= new Action(UpdateChildren);
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRolesUpdated);
		}

		private void OnPlayerRolesUpdated(PhotonPlayer player, RoomRole roleDef)
		{
			if (player.IsLocal && _viewMode == RoleViewMode.View)
			{
				UpdateChildren();
			}
		}

		public void UpdateChildren()
		{
			UpdateChildren(_viewMode, _showOnlyMyRoles);
		}

		public void UpdateChildren(RoleViewMode viewMode, bool showOnlyMyRoles)
		{
			_viewMode = viewMode;
			_showOnlyMyRoles = showOnlyMyRoles;
			if (PlayerRoomRoleManager.Instance != null)
			{
				List<RoomRoleUI> list = (showOnlyMyRoles ? (from _ in PlayerRoomRoleManager.Instance.GetSortedActiveRolesForPlayer(PhotonNetwork.player, reverseOrder: true)
					select new RoomRoleUI
					{
						CurrentRoomRole = _
					}).ToList() : (from _ in PlayerRoomRoleManager.Instance.GetSortedActiveRoles(reverseOrder: true)
					select new RoomRoleUI
					{
						CurrentRoomRole = _
					}).ToList());
				list.Add(new RoomRoleUI
				{
					CurrentRoomRole = PlayerRoomRoleManager.Instance.DefaultRoleDefinition,
					IsDefaultRoleDefinition = true
				});
				SetAllActiveChildren(list, resetPage: false);
			}
		}

		protected override void SetChild(RoomRoleUI item, RoomRoleEditRow uiElement, int activeIndex)
		{
			uiElement.SetRole(item.CurrentRoomRole, activeIndex, _viewMode, item.IsDefaultRoleDefinition);
		}
	}
	public class RoomRolesConditionalButton : ConditionalButton<Button3D>
	{
		private enum RolesButtonState
		{
			Disabled,
			Enabled_HasPermissions,
			Enabled_NoPermissions
		}

		private void Awake()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
		}

		private void OnDestroy()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RoomRole role)
		{
			if (player.IsLocal)
			{
				UpdateButton();
			}
		}

		protected override void RunButtonAction()
		{
			if (PlayerRoomRoleManager.Instance != null && IsInteractable())
			{
				EditRoomRoleOrdersWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<EditRoomRoleOrdersWatchUIFlow>();
				Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
			}
		}

		protected override void UpdateButtonState()
		{
			if (PlayerGameRoleManager.Instance == null || PlayerRoomRoleManager.Instance == null)
			{
				base.ButtonState = 0;
			}
			else if (PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditGameRoles.Value)
			{
				base.ButtonState = 1;
			}
			else
			{
				base.ButtonState = 2;
			}
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			bool flag = base.ButtonState != 0;
			if (base.gameObject.activeSelf != flag)
			{
				base.gameObject.SetActive(flag);
			}
		}

		protected override bool IsInteractable()
		{
			return base.IsInteractable() && base.ButtonState == 1;
		}
