	public class TagListRoomRolePermissionEditable : TagListRolePermissionEditable<RoomRoleId, RoomRole.RolePermission, RoomRole>
	{
		internal override RolePermissionTypes PermissionType => RolePermissionTypes.Room;

		protected override RoomRole GetRoleDefinition(bool isDefaultSet)
		{
			if (PlayerRoomRoleManager.Instance == null)
			{
				return null;
			}
			return isDefaultSet ? PlayerRoomRoleManager.Instance.DefaultRoleDefinition : PlayerRoomRoleManager.Instance.GetRoleDefinition(base.currentlyEditingRoleId);
		}

		protected override bool IsPermissionValid(RoomRole.RolePermission rolePermission)
		{
			return rolePermission != RoomRole.RolePermission.INVALID;
		}

		protected override bool _RequestModificationFromManager(RoomRoleId roleId, RoomRole.RolePermission rolePermission, bool overrides, object arg)
		{
