	public class ToggleRoomRolesEditModeConditionalButton : ConditionalButton<Button3D>
	{
		private enum ButtonStates
		{
			Disabled,
			ChangeToEditMode,
			ChangeToViewMode
		}

		[SerializeField]
		private EditRoomRoleOrdersWatchUIFlow editRoomRoleOrdersScreen;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tooltip tooltip;

		protected override void OnEnable()
		{
			base.OnEnable();
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			editRoomRoleOrdersScreen.OnRoleViewModeChangedEvent += OnRoleViewModeChanged;
		}

		private void OnDisable()
		{
			RoleManagerBase<RoomRoleId, RoomRole.RolePermission, RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RoomRole>(OnPlayerRoleDefinitionUpdated);
			if (editRoomRoleOrdersScreen != null)
			{
				editRoomRoleOrdersScreen.OnRoleViewModeChangedEvent -= OnRoleViewModeChanged;
			}
		}

		private void OnRoleViewModeChanged(RoleViewMode newEditMode)
		{
			UpdateButton();
		}

		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer photonPlayer, RoomRole roleDef)
		{
			if (photonPlayer.IsLocal)
			{
				UpdateButton();
			}
		}

		protected override void RunButtonAction()
		{
			switch (base.ButtonState)
			{
			case 1:
				editRoomRoleOrdersScreen.RoleViewMode = RoleViewMode.Edit;
				break;
			case 2:
				editRoomRoleOrdersScreen.RoleViewMode = RoleViewMode.View;
				break;
			}
		}

		protected override void UpdateButtonState()
		{
			if (editRoomRoleOrdersScreen.RoleViewMode == RoleViewMode.Edit)
			{
				base.ButtonState = 2;
			}
			else if (editRoomRoleOrdersScreen.RoleViewMode == RoleViewMode.View && PlayerRoomRoleManager.Instance.CachedLocalPlayerRoleDefinition.CanEditRoomRoles.Value)
			{
				base.ButtonState = 1;
			}
			else
			{
				base.ButtonState = 0;
			}
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			switch (base.ButtonState)
			{
			case 1:
				UIHelper.SafeSetText(base.LabelText, "Edit Roles");
				tooltip.Message = "Edit all Room roles";
				break;
			case 2:
				UIHelper.SafeSetText(base.LabelText, "Show My Roles");
				tooltip.Message = "Show only roles I have.";
				break;
			}
		}
	}
}
namespace RecRoom.Systems.PlayerRoles.UI
{
	public interface IRolePermissionEditable<RoleIdType>
	{
		void SetRoleId(RoleIdType roleId, RoleViewMode roleViewMode, bool isDefaultRoleDefinition);
	}
	internal enum RolePermissionTypes
	{
		Game,
		Room
	}
	public enum RolePermissionPlayerTypeCategory
	{
		VR_Walk,
		VR_Teleport,
		Screens,
		Shared
	}
	public abstract class RolePermissionEditable : UnityEngine.MonoBehaviour
	{
		public Action OnTokenFlagsUpdated;

		private readonly TokenFlag hideTokenFlags = new TokenFlag();

		[SerializeField]
		private List<RolePermissionPlayerTypeCategory> _visibleForCategories = new List<RolePermissionPlayerTypeCategory> { RolePermissionPlayerTypeCategory.Shared };

		public List<RolePermissionPlayerTypeCategory> VisibleForCategories => _visibleForCategories;

		internal abstract RolePermissionTypes PermissionType { get; }

		public void Hide(object token)
		{
			hideTokenFlags.Add(token);
			OnTokenFlagsUpdated.SafeInvoke();
		}

		public void Show(object token)
		{
			hideTokenFlags.Remove(token);
			OnTokenFlagsUpdated.SafeInvoke();
		}

		internal void UpdateForPermissionType(RolePermissionTypes rolePermissionType)
		{
			if (PermissionType != rolePermissionType)
			{
				UnityEngine.Object.Destroy(this);
			}
		}

		internal bool ShouldShow(RolePermissionPlayerTypeCategory currentPermissionCategory)
		{
			return VisibleForCategories.Contains(currentPermissionCategory) && !hideTokenFlags.HasTokens;
		}
	}
	public abstract class RolePermissionEditableBase<RoleIdType, RolePermissionType, RoleDefinitionType> : RolePermissionEditable, IRolePermissionEditable<RoleIdType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
	{
		[SerializeField]
		protected RolePermissionType permission;

		[SerializeField]
		protected ToggleButton3D overridesToggle;

		private RoleDefinitionType currentlyEditingRole;

		public bool Interactable => RoleViewMode == RoleViewMode.Edit && !IsDefaultRoleDefinition;

		protected RoleIdType currentlyEditingRoleId { get; private set; }

		protected bool IsDefaultRoleDefinition { get; private set; }

		protected RoleViewMode RoleViewMode { get; private set; }

		protected abstract RoleDefinitionType GetRoleDefinition(bool isDefaultSet);

		public abstract void Button_ToggleOverride(bool isOn);

		protected void UpdateVisuals()
		{
			if (overridesToggle.Interactable != Interactable)
			{
				overridesToggle.Interactable = Interactable;
			}
			bool flag = !IsDefaultRoleDefinition;
			if (overridesToggle.gameObject.activeSelf != flag)
			{
				overridesToggle.gameObject.SetActive(flag);
			}
			_UpdateVisuals();
		}

		protected abstract void _UpdateVisuals();

		protected abstract bool IsPermissionValid(RolePermissionType rolePermission);

		private void Start()
		{
			currentlyEditingRole = GetRoleDefinition(IsDefaultRoleDefinition);
		}

		private void OnEnable()
		{
			currentlyEditingRole = GetRoleDefinition(IsDefaultRoleDefinition);
			OnRoleDefinitionUpdated();
		}

		private void OnDestroy()
		{
			if (currentlyEditingRole != null)
			{
				ref RoleDefinitionType reference = ref currentlyEditingRole;
				OnRolePermissionUpdatedCallback<RolePermissionType> callback = OnRoleDefinitionUpdated;
				reference.RemoveOnRolePermissionUpdatedCallback(callback);
			}
		}

		public void SetRoleId(RoleIdType newRoleId, RoleViewMode roleViewMode, bool isDefaultRoleDefinition)
		{
			IsDefaultRoleDefinition = isDefaultRoleDefinition;
			RoleViewMode = roleViewMode;
			currentlyEditingRoleId = newRoleId;
			if (currentlyEditingRole != null)
			{
				ref RoleDefinitionType reference = ref currentlyEditingRole;
				OnRolePermissionUpdatedCallback<RolePermissionType> callback = OnRoleDefinitionUpdated;
				reference.RemoveOnRolePermissionUpdatedCallback(callback);
			}
			currentlyEditingRole = GetRoleDefinition(isDefaultRoleDefinition);
			if (currentlyEditingRole != null)
			{
				ref RoleDefinitionType reference2 = ref currentlyEditingRole;
				OnRolePermissionUpdatedCallback<RolePermissionType> callback2 = OnRoleDefinitionUpdated;
				reference2.AddOnRolePermissionUpdatedCallback(callback2);
				OnRoleDefinitionUpdated();
			}
			UpdateVisuals();
		}

		private void OnRoleDefinitionUpdated()
		{
			if (IsPermissionValid(permission) && currentlyEditingRole != null)
			{
				ref RoleDefinitionType reference = ref currentlyEditingRole;
				RolePermissionType rolePermission = permission;
				IOverridableField fieldFor = reference.GetFieldFor(rolePermission);
				OnRoleDefinitionUpdated(permission, fieldFor);
			}
		}

		private void OnRoleDefinitionUpdated(RolePermissionType newPermission, IOverridableField overridableField)
		{
			if (IsPermissionValid(newPermission) && newPermission.Equals(permission))
			{
				OnRolePermissionUpdated(overridableField);
			}
		}

		protected abstract void OnRolePermissionUpdated(IOverridableField overridableField);
	}
	public abstract class RoleEditableBase<InnerType, RoleIdType, RolePermissionType, RoleDefinitionType> : RolePermissionEditableBase<RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
	{
		public abstract IMutableOverridableField<InnerType> CachedField { get; }

		protected abstract bool _RequestModificationFromManager(RoleIdType roleId, RolePermissionType rolePermission, bool overrides, object arg);

		protected override void OnRolePermissionUpdated(IOverridableField newRoleDefinition)
		{
			UpdateCachedStateAndVisual(newRoleDefinition.Overrides, (InnerType)newRoleDefinition.ObjectValue);
		}

		protected void UpdateCachedStateAndVisual(bool overrides, InnerType value)
		{
			CachedField.Value = value;
			CachedField.Overrides = overrides;
			UpdateVisuals();
		}

		protected void RequestModification(bool overrides, InnerType value)
		{
			if (!base.IsDefaultRoleDefinition && _RequestModificationFromManager(base.currentlyEditingRoleId, permission, overrides, value))
			{
				UpdateCachedStateAndVisual(overrides, value);
			}
		}
	}
	public abstract class SliderRoleEditableBase<InnerType, RoleIdType, RolePermissionType, RoleDefinitionType> : RoleEditableBase<InnerType, RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
	{
		[SerializeField]
		protected Slider3D valueSlider;

		[SerializeField]
		protected GameObject textLabels;

		protected override void _UpdateVisuals()
		{
			valueSlider.Interactable = base.Interactable;
			valueSlider.gameObject.SetActive(CachedField.Overrides);
			textLabels.SetActive(CachedField.Overrides);
		}
