	public abstract class IntRolePermissionEditable<RoleIdType, RolePermissionType, RoleDefinitionType> : SliderRoleEditableBase<int, RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
	{
		private MutableOverridableInt cachedField = new MutableOverridableInt();

		public override IMutableOverridableField<int> CachedField => cachedField;

		protected virtual int SliderValueToInt(float sliderValue)
		{
			return (int)valueSlider.FloatOrRoundedValue;
		}

		protected virtual float IntValueToSliderValue(int value)
		{
			return value;
		}

		public void Slider_OnValueChanged(float sliderVal)
		{
			int num = SliderValueToInt(valueSlider.FloatOrRoundedValue);
			bool overrides = CachedField.Overrides;
			if (num != CachedField.Value)
			{
				RequestModification(overrides, num);
			}
		}

		public override void Button_ToggleOverride(bool newOverrides)
		{
			int value = CachedField.Value;
			if (newOverrides != CachedField.Overrides)
			{
				RequestModification(newOverrides, value);
			}
		}

		protected override void _UpdateVisuals()
		{
			base._UpdateVisuals();
			overridesToggle.IsOn = CachedField.Overrides;
			valueSlider.value = IntValueToSliderValue(CachedField.Value);
		}
	}
	public abstract class FloatRolePermissionEditable<RoleIdType, RolePermissionType, RoleDefinitionType> : SliderRoleEditableBase<float, RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
	{
		private TextMeshProUGUI titleText;

		private string titleBase;

		[SerializeField]
		private string titleNumberUnit = string.Empty;

		private MutableOverridableFloat cachedField = new MutableOverridableFloat();

		public override IMutableOverridableField<float> CachedField => cachedField;

		private void Awake()
		{
			titleText = valueSlider.titleText;
			if (titleText != null)
			{
				titleBase = titleText.text;
			}
