		public void Slider_OnValueChanged(float newSliderValue)
		{
			bool overrides = CachedField.Overrides;
			if (newSliderValue != CachedField.Value)
			{
				RequestModification(overrides, newSliderValue);
			}
		}

		public override void Button_ToggleOverride(bool newOverrides)
		{
			float value = CachedField.Value;
			if (newOverrides != CachedField.Overrides)
			{
				RequestModification(newOverrides, value);
			}
		}

		protected override void _UpdateVisuals()
		{
			base._UpdateVisuals();
			overridesToggle.IsOn = CachedField.Overrides;
			valueSlider.value = CachedField.Value;
			if (titleText != null)
			{
				if (CachedField.Overrides)
				{
					string text = string.Format("{0} {1}{2}", titleBase, CachedField.Value.ToString("F1"), titleNumberUnit);
					titleText.text = text;
