	public abstract class BoolRolePermissionEditable<RoleIdType, RolePermissionType, RoleDefinitionType> : SliderRoleEditableBase<bool, RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
