	public abstract class TagListRolePermissionEditable<RoleIdType, RolePermissionType, RoleDefinitionType> : RoleEditableBase<List<string>, RoleIdType, RolePermissionType, RoleDefinitionType> where RoleIdType : struct where RolePermissionType : struct where RoleDefinitionType : class, IRole<RoleIdType, RolePermissionType, RoleDefinitionType>, new()
