		private MutableOverridableListString cachedField = new MutableOverridableListString(overrides: false, new List<string>());

		public override IMutableOverridableField<List<string>> CachedField => cachedField;

		public override void Button_ToggleOverride(bool newOverrides)
		{
			List<string> value = CachedField.Value;
			if (newOverrides != CachedField.Overrides)
			{
				RequestModification(newOverrides, value);
