			{
				return;
			}
			IPromise<TagEditDialog.InputResponse> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(tagEditDialog, (TagEditDialog dialog) => dialog.ShowDialog(CachedField.Value, maxTags));
			promise.Then(delegate(TagEditDialog.InputResponse r)
