	public class RoleEditDialog : UIDialog<RoleEditDialog.RoleType, List<string>, int, bool, RoleEditDialog.InputResponse>
	{
		public enum RoleType
		{
			Room,
			Game
		}

		public struct InputResponse
		{
			public List<string> NewRoles;

			public ConfirmDialogResponses Response;
		}

		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		[SerializeField]
		private RolePagedGrid pagedGrid;

		[SerializeField]
		private Button3D addRoleButton;

		internal List<string> CurrentRoles = new List<string>();

		private int maxRoles = 5;

		private RoleType roleType = RoleType.Game;

		private bool requirePlayerRoles;

		private InputResponse CreateResponse(ConfirmDialogResponses response)
		{
			return new InputResponse
			{
				NewRoles = CurrentRoles,
				Response = response
			};
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(CreateResponse(ConfirmDialogResponses.Cancel), shouldCloseDialog);
		}

		public override IPromise<InputResponse> ShowDialog(RoleType roleType, List<string> currentRoles = null, int maxRoles = 5, bool requirePlayerRoles = false)
		{
			if (currentRoles != null)
			{
				CurrentRoles = currentRoles;
			}
			this.roleType = roleType;
			this.maxRoles = maxRoles;
			this.requirePlayerRoles = requirePlayerRoles;
			pagedGrid.UpdateChildren(CurrentRoles);
			OnRoleCountChanged();
			return base.ShowDialog();
		}

		public void Button_AddRole()
		{
			if (!Player.LocalPlayerExists)
			{
				return;
			}
			IPromise<TextInputUIDialog.InputResponse> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.Alphanumeric, "Enter New Role", "Enter new role", "Add", purifyText: false, 20, RoleAllowedValidationFunction, shouldFocusInputField: false));
			promise.Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative && !string.IsNullOrEmpty(r.TextInput))
				{
					string item = r.TextInput.Trim().ToLower();
					if (!CurrentRoles.Contains(item))
					{
						CurrentRoles.Add(item);
						pagedGrid.UpdateChildren(CurrentRoles);
						OnRoleCountChanged();
					}
				}
			});
		}

		private bool RoleAllowedValidationFunction(TextMeshProUGUI infoText, string input)
		{
			string text = input.Trim().ToLowerInvariant();
			if (CurrentRoles.Contains(text))
			{
				UIHelper.SafeSetText(infoText, "Already adding that role!");
				infoText.gameObject.SetActive(value: true);
				return false;
			}
			if (!requirePlayerRoles)
			{
				UIHelper.SafeSetText(infoText, string.Empty);
				infoText.gameObject.SetActive(value: false);
				return true;
			}
			switch (roleType)
			{
			case RoleType.Game:
			{
				GameRole gameRole = PlayerGameRoleManager.Instance.FindActiveRoleByName(text);
				if (gameRole != null && RoleIdHelper.IsAGRole(gameRole.RoleId))
				{
					UIHelper.SafeSetText(infoText, "Must be player created role!");
					infoText.gameObject.SetActive(value: true);
					return false;
				}
				UIHelper.SafeSetText(infoText, string.Empty);
				infoText.gameObject.SetActive(value: false);
				return true;
			}
			case RoleType.Room:
			{
				RoomRole roomRole = PlayerRoomRoleManager.Instance.FindActiveRoleByName(text);
				if (roomRole != null && RoleIdHelper.IsAGRole(roomRole.RoleId))
				{
					UIHelper.SafeSetText(infoText, "Must be player created role!");
					infoText.gameObject.SetActive(value: true);
					return false;
				}
				UIHelper.SafeSetText(infoText, string.Empty);
				infoText.gameObject.SetActive(value: false);
				return true;
			}
			default:
				throw new InvalidOperationException("Unknown role type");
			}
		}

		public void Button_Done()
		{
			Respond(CreateResponse(ConfirmDialogResponses.Affirmative), shouldCloseDialog: true);
		}

		internal void RemoveRole(string tag)
		{
			if (CurrentRoles.Remove(tag))
			{
				OnRoleCountChanged();
				pagedGrid.UpdateChildren(CurrentRoles);
			}
		}

		private void OnRoleCountChanged()
		{
			addRoleButton.Interactable = CurrentRoles.Count < maxRoles;
		}
	}
