	public class RoleRow : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private TextMeshProUGUI uiText;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private UnityEngine.UI.Image bgImage;

		private Color color;

		private Color darkColor;

		private string currentRole;

		private RoleEditDialog tagEditDialog;

		private void Awake()
		{
			color = bgImage.color;
			darkColor = bgImage.color * 0.85f;
			darkColor.a = color.a;
		}

		public void SetRole(string newRole, int activeIndex, RoleEditDialog tagEditDialog)
		{
			this.tagEditDialog = tagEditDialog;
			currentRole = newRole;
			if (newRole != null)
			{
				uiText.text = "#" + newRole;
			}
			if (activeIndex % 2 == 0)
			{
				color *= 0.85f;
				color.a = 1f;
			}
			bgImage.color = ((activeIndex % 2 != 0) ? darkColor : color);
		}

		public void Button_Delete()
		{
			if (tagEditDialog != null)
			{
				tagEditDialog.RemoveRole(currentRole);
			}
		}
	}
