	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip becomeMemberToUseThisClip;

	[Header("Objectives")]
	[SerializeField]
	private ObjectiveTypeDescription[] objectiveTypeDescriptions;

	private Dictionary<ObjectiveType, ObjectiveTypeDescription> objectiveDescriptionMap = new Dictionary<ObjectiveType, ObjectiveTypeDescription>();

	[Tooltip("These are milestone objectives, they cause the objective records to be published to the server and cause you to get XP.\nAll the game ending events and dailies are major.")]
	[SerializeField]
	private List<ObjectiveType> majorObjectiveTypes;

	[Tooltip("How often can I request a flush of objective records to the server.")]
	[SerializeField]
	private float minConsequtiveFlushInterval = 5f;

	[Header("Registration Nudge")]
	[SerializeField]
	private RecRoomAudioClip registerToLevelUpVO;

	private List<ObjectiveCompletionRecord> objectiveCompletionRecords = new List<ObjectiveCompletionRecord>();

	private List<Storefronts.StorefrontObjectiveCompletionRecord> storefrontObjectiveCompletionRecords = new List<Storefronts.StorefrontObjectiveCompletionRecord>();

	private float lastFlushTime;

	private bool flushRequested;

	public RecRoomAudioClip BecomeMemberToUseThisClip => becomeMemberToUseThisClip;

	public float LocalXPProgression
	{
		get
		{
			int xpRequiredToLevelUp = Profiles.LocalProfile.GetXpRequiredToLevelUp();
			if (xpRequiredToLevelUp <= 0)
			{
				return 1f;
			}
			return (float)(int)Profiles.LocalProfile.XP / (float)xpRequiredToLevelUp;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		PlayerObjectiveTracker.EventBufferUpdated += PlayerObjectiveTracker_EventBufferUpdated;
	}

	private void Update()
	{
		if (flushRequested && UnityEngine.Time.time - lastFlushTime > minConsequtiveFlushInterval)
		{
			FlushObjectiveRecords();
		}
	}

	public void Initialize()
	{
		ObjectiveTypeDescription[] array = objectiveTypeDescriptions;
		foreach (ObjectiveTypeDescription objectiveTypeDescription in array)
		{
			if (!objectiveDescriptionMap.ContainsKey(objectiveTypeDescription.ObjectiveType))
			{
				objectiveDescriptionMap.Add(objectiveTypeDescription.ObjectiveType, objectiveTypeDescription);
			}
			else
			{
				UnityEngine.Debug.LogError("objectiveTypeDescriptions has duplicate entries for " + objectiveTypeDescription.ObjectiveType);
			}
		}
		StartCoroutine(RunHandleInitialLogin());
		SceneManager.activeSceneChanged += SceneManager_activeSceneChanged;
	}

	private void SceneManager_activeSceneChanged(Scene arg0, Scene arg1)
	{
		objectiveCompletionRecords.Clear();
	}

	private IEnumerator RunHandleInitialLogin()
	{
		while (!Player.LocalPlayerExists || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		if (Login.FirstLoginOfTheDay)
		{
			LocalCompleteObjective(ObjectiveType.FirstSessionOfDay, 1f, GameSessions.LocalGameSession?.RoomId);
			if (Profiles.LocalProfile.IsLevelCappedByRegistration() && registerToLevelUpVO != null && registerToLevelUpVO.audioClip != null)
			{
				AudioManager.Play2DSFX(registerToLevelUpVO);
			}
		}
	}

	public void LocalCompleteObjective(ObjectiveType type, float completionPercentage, long? roomId, int additionalXp = 0)
	{
		if (type != ObjectiveType.Default || additionalXp > 0)
		{
			objectiveCompletionRecords.Add(new ObjectiveCompletionRecord(type, additionalXp, Player.LocalPlayer.PlayerParty.PartySize > 1));
			storefrontObjectiveCompletionRecords.Add(new Storefronts.StorefrontObjectiveCompletionRecord
			{
				objectiveType = type,
				completionPercentage = completionPercentage,
				roomId = roomId
			});
			if (majorObjectiveTypes.Contains(type))
			{
				RequestObjectiveCompletionRecordFlush();
			}
		}
	}

	private bool IsOOBEObjective(ObjectiveType type)
	{
		return type == ObjectiveType.OOBE_GoToActivity || type == ObjectiveType.OOBE_GoToLockerRoom || type == ObjectiveType.OOBE_FinishActivity;
	}

	public void RequestObjectiveCompletionRecordFlush()
	{
		flushRequested = true;
	}

	private void FlushObjectiveRecords()
	{
		flushRequested = false;
		lastFlushTime = UnityEngine.Time.time;
		if (objectiveCompletionRecords.Count != 0)
		{
			if (objectiveCompletionRecords.Count > 0)
			{
				List<ObjectiveCompletionRecord> list = new List<ObjectiveCompletionRecord>();
				list.AddRange(objectiveCompletionRecords);
				Profiles.CompleteObjectives(list);
				objectiveCompletionRecords.Clear();
			}
			if (storefrontObjectiveCompletionRecords.Count > 0)
			{
				List<Storefronts.StorefrontObjectiveCompletionRecord> list2 = new List<Storefronts.StorefrontObjectiveCompletionRecord>();
				list2.AddRange(storefrontObjectiveCompletionRecords);
				Storefronts.CompleteObjectives(list2);
				storefrontObjectiveCompletionRecords.Clear();
			}
		}
	}

	public ObjectiveTypeDescription GetObjectiveDescription(ObjectiveType objectiveType)
	{
		objectiveDescriptionMap.TryGetValue(objectiveType, out var value);
		return value;
	}

	private void PlayerObjectiveTracker_EventBufferUpdated(List<PlayerObjectiveTracker.ObjectiveRecord> eventBuffer, PlayerObjectiveTracker.ObjectiveTrackerType trackerType)
	{
		if (trackerType != PlayerObjectiveTracker.ObjectiveTrackerType.Dailies)
		{
			return;
		}
		foreach (PlayerObjectiveTracker.ObjectiveRecord item in eventBuffer)
		{
			ObjectiveTypeDescription objectiveDescription = GetObjectiveDescription(item.objectiveType);
			if (objectiveDescription != null)
			{
				LocalCompleteObjective(objectiveDescription.ObjectiveType, item.completionPercentage, item.roomId);
			}
		}
	}
}
public class RecnetPreferencesMissingException : Exception
{
}
public static class RecroomPrefs
{
	public delegate void DownloadPreferencesCallback(string error);

	public class Preference
	{
		public string value;

		public bool isDirty;

		public Preference(string v, bool d)
		{
			value = v;
			isDirty = d;
		}
	}

	private static bool downloadedFromRecnet = false;

	private static bool savePreferencesToRecnetInProgress = false;

	private static bool saveRequested = false;

	private static Dictionary<string, Preference> preferences = new Dictionary<string, Preference>();

	public static int CurrentDay => DateTime.Today.DayOfYear;

	public static bool IsReady => downloadedFromRecnet;

	private static void CheckReady()
	{
		if (!downloadedFromRecnet)
		{
			throw new RecnetPreferencesMissingException();
		}
	}

	public static IEnumerator DowloadLocalPlayerPreferences(DownloadPreferencesCallback callback)
	{
		string error = null;
		yield return Settings.DowloadLocalPlayerSettings(delegate(string e, List<Setting> newPreferences)
		{
			error = e;
			if (string.IsNullOrEmpty(e))
			{
				foreach (Setting newPreference in newPreferences)
				{
					SetPreference(newPreference.Key, newPreference.Value, isDirty: false);
				}
			}
		});
		if (string.IsNullOrEmpty(error))
		{
			downloadedFromRecnet = true;
			string value = PlayerPrefs.GetString("google_analytics_clientid_pref_key");
			if (!string.IsNullOrEmpty(value))
			{
				SetString("google_analytics_clientid_pref_key", value);
			}
			Save();
		}
		callback(error);
	}

	private static IEnumerator RunSavePreferencesToRecnet()
	{
		CheckReady();
		savePreferencesToRecnetInProgress = true;
		bool dirtyFound = false;
		do
		{
			dirtyFound = false;
			string[] preferencesKeys = new string[preferences.Keys.Count];
			preferences.Keys.CopyTo(preferencesKeys, 0);
			saveRequested = false;
			string[] array = preferencesKeys;
			foreach (string key in array)
			{
				Preference original = preferences[key];
				if (!original.isDirty)
				{
					continue;
				}
				string originalValue = original.value;
				yield return Settings.StoreLocalPlayerSetting(new Setting
				{
					Key = key,
					Value = originalValue
				}, delegate(string e)
				{
					if (string.IsNullOrEmpty(e) && original.value == originalValue)
					{
						original.isDirty = false;
					}
				});
				dirtyFound = true;
			}
		}
		while (dirtyFound || saveRequested);
		savePreferencesToRecnetInProgress = false;
	}

	public static void Save()
	{
		saveRequested = true;
		if (!savePreferencesToRecnetInProgress && SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.StartCoroutine(RunSavePreferencesToRecnet());
		}
	}

	public static void DeleteKey(string key)
	{
		CheckReady();
		SetPreference(key, null);
	}

	public static bool HasKey(string key)
	{
		CheckReady();
		return preferences.ContainsKey(key);
	}

	public static int GetInt(string key, int defaultValue)
	{
		if (HasKey(key))
		{
			return int.Parse(preferences[key].value);
		}
		return defaultValue;
	}

	public static float GetFloat(string key, float defaultValue)
	{
		if (HasKey(key))
		{
			return float.Parse(preferences[key].value, NumberStyles.Any, CultureInfo.InvariantCulture);
		}
		return defaultValue;
	}

	public static string GetString(string key, string defaultValue = "")
	{
		if (HasKey(key))
		{
			return preferences[key].value;
		}
		return defaultValue;
	}

	public static void SetInt(string key, int value)
	{
		CheckReady();
		SetPreference(key, value.ToString(CultureInfo.InvariantCulture));
	}

	public static void SetFloat(string key, float value)
	{
		CheckReady();
		SetPreference(key, value.ToString(CultureInfo.InvariantCulture));
	}

	public static void SetString(string key, string value)
	{
		CheckReady();
		SetPreference(key, value);
	}

	private static void SetPreference(string key, string value, bool isDirty = true)
	{
		if (preferences.ContainsKey(key))
		{
			if (preferences[key].value != value)
			{
				preferences[key].value = value;
				preferences[key].isDirty = isDirty;
			}
		}
		else if (value != null)
		{
			preferences.Add(key, new Preference(value, isDirty));
		}
	}
}
