namespace RecRoom.Core
{
	public interface IReactiveProperty<T>
	{
		T Value { get; }

		IDisposable Observe(Action<T> onValueChanged);

		IDisposable Observe(UnityEngine.Object context, Action<T> onValueChanged);
	}
	public class ReactiveProperty<T> : IReactiveProperty<T>
	{
		private class Receipt : IDisposable
		{
			private readonly Action disposed;

			public Receipt(Action disposed)
			{
				this.disposed = disposed;
			}

			public void Dispose()
			{
				disposed();
			}
		}

		private static GameObject _defaultContext;

		private readonly List<Tuple<UnityEngine.Object, Action<T>>> observers = new List<Tuple<UnityEngine.Object, Action<T>>>();

		private T _value;

		private static UnityEngine.Object DefaultContext
		{
			get
			{
				if (_defaultContext == null)
				{
					_defaultContext = new GameObject("RxProp.DefaultContext");
					_defaultContext.hideFlags = HideFlags.HideAndDontSave;
					if (UnityEngine.Application.isPlaying)
					{
						UnityEngine.Object.DontDestroyOnLoad(_defaultContext);
					}
				}
				return _defaultContext;
			}
		}

		public T Value
		{
			get
			{
				return _value;
			}
			set
			{
				if (!AreEqual(_value, value))
				{
					_value = value;
					NotifyObservers();
				}
			}
		}

		public ReactiveProperty()
			: this(default(T))
		{
		}

		public ReactiveProperty(T initialValue)
		{
			_value = initialValue;
		}

		private static bool AreEqual(T a, T b)
		{
			return (a == null && b == null) || (a != null && b != null && a.Equals(b));
		}

		public void ForceUpdate(T newValue)
		{
			_value = newValue;
			NotifyObservers();
		}

		public IDisposable Observe(Action<T> onValueChanged)
		{
			return Observe(DefaultContext, onValueChanged);
		}

		public IDisposable Observe(UnityEngine.Object context, Action<T> onValueChanged)
		{
			Tuple<UnityEngine.Object, Action<T>> tup = Tuple.Create(context, onValueChanged);
			observers.Add(tup);
			return new Receipt(delegate
			{
				observers.Remove(tup);
			});
		}

		private void NotifyObservers()
		{
			observers.RemoveAllWhere((Tuple<UnityEngine.Object, Action<T>> tup) => !tup.Item1);
			for (int num = 0; num < observers.Count; num++)
			{
				try
				{
					observers[num].Item2(_value);
				}
				catch (Exception exception)
				{
					UnityEngine.Debug.LogException(exception);
				}
			}
		}
	}
