	public interface ISchedulerPromise : IPromise, ISchedule, IDisposable, IEnumerator
	{
		void Cancel();

		ISchedulerPromise Canceled(Action onCanceled);
	}
	public sealed class Scheduler : SingletonMonoBehaviour<Scheduler>
	{
		public enum QueueType
		{
			Update,
			PostUpdate,
			FixedUpdate,
			RigidbodyExLateUpdate,
			LateUpdate,
			PreRender,
			EndOfFrame
		}

		private sealed class SchedulerPromise : Promise, ISchedulerPromise, IPromise, ISchedule, IDisposable, IEnumerator
		{
			private readonly List<Action> canceled = new List<Action>(1);

			QueueType ISchedule.Queue => QueueType.Update;

			float ISchedule.NextPossibleReady => 0f;

			bool ISchedule.Ready()
			{
				return base.IsCompleted;
			}

			public void Cancel()
			{
				try
				{
					Exception ex = null;
					foreach (Action item in canceled)
					{
						try
						{
							item();
						}
						catch (Exception ex2)
						{
							ex = ex2;
						}
					}
					Exception ex3 = ExecuteFinallyFuncs();
					if (ex != null)
					{
						throw ex;
					}
					if (ex3 != null)
					{
						throw ex3;
					}
				}
				finally
				{
					ClearQueuedActionLists();
				}
			}

			public ISchedulerPromise Canceled(Action onCanceled)
			{
				canceled.Add(onCanceled);
				return this;
			}

			public void Dispose()
			{
				Cancel();
			}
		}

		private sealed class SchedulerCoroutine
		{
			private readonly SchedulerPromise promise;

			private readonly Behaviour context;

			private readonly bool wasCreatedWithContext;

			public IEnumerator<ISchedule> Coroutine { get; private set; }

			public ISchedule CurrentSchedule { get; private set; }

			public bool Paused
			{
				get
				{
					if (!wasCreatedWithContext)
					{
						return false;
					}
					if ((bool)context)
					{
						return !context.isActiveAndEnabled;
					}
					return false;
				}
			}

			public bool Canceled { get; private set; }

			public string Name { get; private set; }

			public float NextUpdateKey { get; set; }

			public SchedulerCoroutine(IEnumerator<ISchedule> coroutine, Behaviour context, SchedulerPromise promise)
			{
				Coroutine = coroutine;
				this.promise = promise;
				this.context = context;
				wasCreatedWithContext = context != null;
				promise.Canceled(delegate
				{
					Canceled = true;
				});
				string name = coroutine.GetType().Name;
				if ((bool)context)
				{
					Name = $"[Coroutine (Context {context.name}) {name}]";
				}
				else
				{
					Name = $"[Coroutine {name}]";
				}
			}

			public ISchedule Step()
			{
				if (wasCreatedWithContext && !context)
				{
					promise.Cancel();
					return null;
				}
				try
				{
					if (Coroutine.MoveNext())
					{
						CurrentSchedule = Coroutine.Current;
						return CurrentSchedule;
					}
				}
				catch (Exception ex)
				{
					if (promise.HasErrorHandler)
					{
						promise.Error(ex.ToString());
					}
					else
					{
						UnityEngine.Debug.LogException(ex);
					}
					return null;
				}
				promise.Complete();
				return null;
			}

			public override string ToString()
			{
				if (CurrentSchedule == null)
				{
					return "[SchedulerCoroutine (Completed)]";
				}
				return string.Format("[SchedulerCoroutine ({0}){1}]", CurrentSchedule, (!Paused) ? string.Empty : " Paused");
			}
		}

		private sealed class SchedulerQueue
		{
			private class SortCoroutinesChronologically : IComparer<SchedulerCoroutine>
			{
				public int Compare(SchedulerCoroutine x, SchedulerCoroutine y)
				{
					int num = x.NextUpdateKey.CompareTo(y.NextUpdateKey);
					if (num == 0)
					{
						num = x.Coroutine.GetHashCode().CompareTo(y.Coroutine.GetHashCode());
					}
					return num;
				}
			}

			public enum SubQueue
			{
				Immediate,
				Future
			}

			private enum TickResult
			{
				None,
				Remove,
				Reinsert
			}

			public struct ReinsertBuffer
			{
				public QueueType QueueType;

				public SubQueue SubQueue;

				public List<SchedulerCoroutine> Coroutines;
			}

			private bool lockedForUpdate;

			private readonly SchedulerCoroutine[] singleCoroutineArrayBuffer = new SchedulerCoroutine[1];

			private readonly List<SchedulerCoroutine> immediateCoroutines = new List<SchedulerCoroutine>();

			private readonly Stack<int> immediateUpdateHoles = new Stack<int>();

			private readonly SortedSet<SchedulerCoroutine> futureCoroutines = new SortedSet<SchedulerCoroutine>(new SortCoroutinesChronologically());

			private readonly List<SchedulerCoroutine> toRemoveBuffer = new List<SchedulerCoroutine>();

			public QueueType Queue { get; private set; }

			public ReinsertBuffer[,] ReinsertionQueues { get; }

			public SchedulerQueue(QueueType queue)
			{
				Queue = queue;
				Array values = System.Enum.GetValues(typeof(QueueType));
				Array values2 = System.Enum.GetValues(typeof(SubQueue));
				ReinsertionQueues = new ReinsertBuffer[values.Length, values2.Length];
				for (int i = 0; i < values.Length; i++)
				{
					for (int j = 0; j < values2.Length; j++)
					{
						ref ReinsertBuffer reference = ref ReinsertionQueues[i, j];
						reference = new ReinsertBuffer
						{
							QueueType = (QueueType)values.GetValue(i),
							SubQueue = (SubQueue)values2.GetValue(j),
							Coroutines = new List<SchedulerCoroutine>()
						};
					}
				}
			}

			public void InsertSingleCoroutine(SchedulerCoroutine coroutine)
			{
				singleCoroutineArrayBuffer[0] = coroutine;
				if (coroutine.CurrentSchedule.NextPossibleReady > 0f)
				{
					InsertFutures(singleCoroutineArrayBuffer);
				}
				else
				{
					InsertImmediates(singleCoroutineArrayBuffer);
				}
			}

			public void InsertImmediates(IEnumerable<SchedulerCoroutine> coroutines)
			{
				if (lockedForUpdate)
				{
					QueueMultipleForReinsert(coroutines);
					return;
				}
				foreach (SchedulerCoroutine coroutine in coroutines)
				{
					coroutine.NextUpdateKey = coroutine.CurrentSchedule.NextPossibleReady;
					if (immediateUpdateHoles.Count > 0)
					{
						immediateCoroutines[immediateUpdateHoles.Pop()] = coroutine;
					}
					else
					{
						immediateCoroutines.Add(coroutine);
					}
				}
			}

			public void InsertFutures(IEnumerable<SchedulerCoroutine> coroutines)
			{
				if (lockedForUpdate)
				{
					QueueMultipleForReinsert(coroutines);
					return;
				}
				foreach (SchedulerCoroutine coroutine in coroutines)
				{
					coroutine.NextUpdateKey = coroutine.CurrentSchedule.NextPossibleReady;
				}
				futureCoroutines.UnionWith(coroutines);
			}

			private void QueueForReinsert(SchedulerCoroutine coroutine)
			{
				SubQueue subQueue = ((coroutine.CurrentSchedule.NextPossibleReady > 0f) ? SubQueue.Future : SubQueue.Immediate);
				ReinsertionQueues[(int)coroutine.CurrentSchedule.Queue, (int)subQueue].Coroutines.Add(coroutine);
			}

			private void QueueMultipleForReinsert(IEnumerable<SchedulerCoroutine> coroutines)
			{
				foreach (SchedulerCoroutine coroutine in coroutines)
				{
					QueueForReinsert(coroutine);
				}
			}

			private TickResult TickCoroutine(SchedulerCoroutine coroutine)
			{
				TickResult result = TickResult.None;
				float nextPossibleReady = coroutine.CurrentSchedule.NextPossibleReady;
				if (coroutine.NextUpdateKey != coroutine.CurrentSchedule.NextPossibleReady)
				{
					throw new InvalidOperationException("NextPossibleReady can only be changed when a coroutine is ticked (when ISchedule.Ready() returns true");
				}
				if (coroutine.CurrentSchedule.Ready())
				{
					ISchedule schedule = coroutine.Step();
					bool flag = schedule != null && schedule.Queue != Queue;
					bool flag2 = schedule != null && nextPossibleReady != schedule.NextPossibleReady;
					if (schedule == null)
					{
						result = TickResult.Remove;
					}
					else if (flag || flag2)
					{
						result = TickResult.Reinsert;
					}
				}
				return result;
			}

			public void Update(float currentTime)
			{
				lockedForUpdate = true;
				try
				{
					DoImmediateUpdates();
					DoFutureUpdates(currentTime);
				}
				finally
				{
					lockedForUpdate = false;
				}
			}

			private void DoImmediateUpdates()
			{
				for (int i = 0; i < immediateCoroutines.Count; i++)
				{
					SchedulerCoroutine schedulerCoroutine = immediateCoroutines[i];
					if (schedulerCoroutine == null)
					{
						continue;
					}
					if (schedulerCoroutine.Canceled)
					{
						immediateCoroutines[i] = null;
						immediateUpdateHoles.Push(i);
					}
					else if (!schedulerCoroutine.Paused)
					{
						TickResult tickResult = TickCoroutine(schedulerCoroutine);
						if (tickResult == TickResult.Remove || tickResult == TickResult.Reinsert)
						{
							immediateCoroutines[i] = null;
							immediateUpdateHoles.Push(i);
						}
						if (tickResult == TickResult.Reinsert)
						{
							QueueForReinsert(schedulerCoroutine);
						}
					}
				}
			}

			private void DoFutureUpdates(float now)
			{
				try
				{
					foreach (SchedulerCoroutine futureCoroutine in futureCoroutines)
					{
						if (futureCoroutine.Canceled)
						{
							toRemoveBuffer.Add(futureCoroutine);
						}
						else if (!futureCoroutine.Paused)
						{
							if (futureCoroutine.CurrentSchedule.NextPossibleReady > now)
							{
								break;
							}
							TickResult tickResult = TickCoroutine(futureCoroutine);
							if (tickResult == TickResult.Remove || tickResult == TickResult.Reinsert)
							{
								toRemoveBuffer.Add(futureCoroutine);
							}
							if (tickResult == TickResult.Reinsert)
							{
								QueueForReinsert(futureCoroutine);
							}
						}
					}
				}
				finally
				{
					futureCoroutines.ExceptWith(toRemoveBuffer);
					toRemoveBuffer.Clear();
				}
			}
		}

		private SchedulerQueue[] queues;

		private Coroutine endOfFrameRoutine;

		private WaitForEndOfFrame waitForEndOfFrame = new WaitForEndOfFrame();

		public ISchedulerTimer Timer { get; set; }

		protected override void Awake()
		{
			TimerAnalytics.CreateWrapper(TimerAnalytics.WrapperKey.SchedulerUpdate);
			Timer = new DefaultTimer();
			Array values = System.Enum.GetValues(typeof(QueueType));
			queues = new SchedulerQueue[values.Length];
			for (int i = 0; i < queues.Length; i++)
			{
				queues[i] = new SchedulerQueue((QueueType)i);
			}
			CustomPlayerLoopInjector.CustomSystems.PostUpdateSystem.OnPostUpdate += OnPostUpdate;
			CustomPlayerLoopInjector.CustomSystems.RigidbodyExLateUpdateSystem.OnRigidbodyExLateUpdate += OnRigidbodyExLateUpdate;
			CustomPlayerLoopInjector.CustomSystems.PreRenderSystem.OnPreRenderUpdate += OnPreRenderUpdate;
			base.Awake();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CustomPlayerLoopInjector.CustomSystems.PostUpdateSystem.OnPostUpdate -= OnPostUpdate;
			CustomPlayerLoopInjector.CustomSystems.RigidbodyExLateUpdateSystem.OnRigidbodyExLateUpdate -= OnRigidbodyExLateUpdate;
			CustomPlayerLoopInjector.CustomSystems.PreRenderSystem.OnPreRenderUpdate -= OnPreRenderUpdate;
		}

		private SchedulerQueue GetQueue(QueueType type)
		{
			return queues[(int)type];
		}

		private void OnEnable()
		{
			endOfFrameRoutine = StartCoroutine(EndOfFrameRoutine());
		}

		private void OnDisable()
		{
			if (endOfFrameRoutine != null)
			{
				StopCoroutine(endOfFrameRoutine);
				endOfFrameRoutine = null;
			}
		}

		private void Update()
		{
			TimerAnalytics.GetWrapper(TimerAnalytics.WrapperKey.SchedulerUpdate).RegisterStart();
			UpdateQueue(QueueType.Update);
			TimerAnalytics.GetWrapper(TimerAnalytics.WrapperKey.SchedulerUpdate).RegisterEnd();
		}

		private void OnPostUpdate()
		{
			UpdateQueue(QueueType.PostUpdate);
		}

		private void OnRigidbodyExLateUpdate()
		{
			UpdateQueue(QueueType.RigidbodyExLateUpdate);
		}

		private void FixedUpdate()
		{
			UpdateQueue(QueueType.FixedUpdate);
		}

		private void LateUpdate()
		{
			UpdateQueue(QueueType.LateUpdate);
		}

		private void OnPreRenderUpdate()
		{
			UpdateQueue(QueueType.PreRender);
		}

		private IEnumerator EndOfFrameRoutine()
		{
			while (true)
			{
				yield return waitForEndOfFrame;
				UpdateQueue(QueueType.EndOfFrame);
			}
		}

		public ISchedulerPromise Run(Behaviour context, IEnumerator<ISchedule> coroutineToRun)
		{
			SchedulerPromise schedulerPromise = new SchedulerPromise();
			SchedulerCoroutine schedulerCoroutine = new SchedulerCoroutine(coroutineToRun, context, schedulerPromise);
			ISchedule schedule = schedulerCoroutine.Step();
			if (schedule != null)
			{
				GetQueue(schedule.Queue).InsertSingleCoroutine(schedulerCoroutine);
			}
			return schedulerPromise;
		}

		public ISchedulerPromise Run(IEnumerator<ISchedule> coroutineToRun)
		{
			return Run(null, coroutineToRun);
		}

		public void UpdateQueue(QueueType currentQueueType)
		{
			SchedulerQueue queue = GetQueue(currentQueueType);
			queue.Update(Timer.Time);
			FlushReinserts(queue);
		}

		private void FlushReinserts(SchedulerQueue currentQueue)
		{
			SchedulerQueue.ReinsertBuffer[,] reinsertionQueues = currentQueue.ReinsertionQueues;
			int length = reinsertionQueues.GetLength(0);
			int length2 = reinsertionQueues.GetLength(1);
			for (int i = 0; i < length; i++)
			{
				for (int j = 0; j < length2; j++)
				{
					SchedulerQueue.ReinsertBuffer reinsertBuffer = reinsertionQueues[i, j];
					SchedulerQueue queue = GetQueue(reinsertBuffer.QueueType);
					SchedulerQueue.SubQueue subQueue = reinsertBuffer.SubQueue;
					if (reinsertBuffer.Coroutines.Count != 0)
					{
						if (subQueue == SchedulerQueue.SubQueue.Future)
						{
							queue.InsertFutures(reinsertBuffer.Coroutines);
						}
						else
						{
							queue.InsertImmediates(reinsertBuffer.Coroutines);
						}
						reinsertBuffer.Coroutines.Clear();
					}
				}
			}
		}
	}
	public class ScheduleRate : ISchedule
	{
		private readonly float firstUpdateTime;

		private int timesUpdated;

		private readonly float secondsPerUpdate;

		public float TargetHz { get; private set; }

		public Scheduler.QueueType Queue { get; private set; }

		public float NextPossibleReady { get; private set; }

		public float DeltaTime { get; private set; }

		public ScheduleRate(float targetRateHz, Scheduler.QueueType queue = Scheduler.QueueType.Update)
		{
			TargetHz = targetRateHz;
			secondsPerUpdate = 1f / targetRateHz;
			Queue = queue;
			firstUpdateTime = SingletonMonoBehaviour<Scheduler>.Instance.Timer.Time + UnityEngine.Random.value * secondsPerUpdate;
			NextPossibleReady = firstUpdateTime;
			DeltaTime = secondsPerUpdate;
		}

		public bool Ready()
		{
			timesUpdated++;
			NextPossibleReady = firstUpdateTime + (float)timesUpdated * DeltaTime;
			return true;
		}

		public override string ToString()
		{
			return $"[ScheduleRate {TargetHz:n2}hz, Next {NextPossibleReady:n2}]";
		}
	}
	public static class ThrottledUpdateRateExtensions
	{
		public static IEnumerator<ISchedule> UpdateCoroutine(float hz, Scheduler.QueueType queue, Action<float> update)
		{
			ScheduleRate schedule = new ScheduleRate(hz, queue);
			while (true)
			{
				yield return schedule;
				update(schedule.DeltaTime);
			}
		}

