		public ScheduleWait(float seconds, Scheduler.QueueType queue = Scheduler.QueueType.Update)
		{
			waitTime = seconds;
			NextPossibleReady = SingletonMonoBehaviour<Scheduler>.Instance.Timer.Time + waitTime;
			Queue = queue;
		}

		public bool Ready()
		{
			NextPossibleReady = SingletonMonoBehaviour<Scheduler>.Instance.Timer.Time + waitTime;
			return true;
		}
	}
	public static class DelayedUpdateExtensions
	{
		private static IEnumerator<ISchedule> DelayedCoroutine(float seconds, Scheduler.QueueType queue, Action function)
		{
			yield return Schedule.Wait(seconds, queue);
			function?.Invoke();
		}

		private static IEnumerator<ISchedule> InvokeRepeatedCoroutine(float seconds, Scheduler.QueueType queue, Action function)
		{
			ISchedule wait = Schedule.Wait(seconds, queue);
			while (true)
			{
				yield return wait;
				if (function != null)
				{
					function();
					continue;
				}
				break;
			}
		}

		public static IDisposable InvokeRepeated(this UnityEngine.MonoBehaviour behaviour, float seconds, Action function)
		{
			return behaviour.InvokeRepeated(seconds, Scheduler.QueueType.Update, function);
		}

		public static ISchedulerPromise InvokeRepeated(this UnityEngine.MonoBehaviour behaviour, float seconds, Scheduler.QueueType queue, Action function)
		{
			return SingletonMonoBehaviour<Scheduler>.Instance.Run(behaviour, InvokeRepeatedCoroutine(seconds, queue, function));
		}

		public static ISchedulerPromise InvokeNextUpdate(this UnityEngine.MonoBehaviour behaviour, Action function)
		{
			return SingletonMonoBehaviour<Scheduler>.Instance.Run(behaviour, DelayedCoroutine(0f, Scheduler.QueueType.Update, function));
		}

