	private DateTime? lastFriendImportUTC
	{
		get
		{
			if (PlayerPrefs.HasKey("LastFriendImportUTC"))
			{
				long result = 3618432000L;
				long.TryParse(PlayerPrefs.GetString("LastFriendImportUTC"), out result);
				return new DateTime(result);
			}
			return null;
		}
		set
		{
			if (!value.HasValue)
			{
				if (PlayerPrefs.HasKey("LastFriendImportUTC"))
				{
					PlayerPrefs.DeleteKey("LastFriendImportUTC");
				}
			}
			else
			{
				PlayerPrefs.SetString("LastFriendImportUTC", value.Value.Ticks.ToString());
			}
		}
	}

