	{
	}

	private IEnumerator RunSendStatusUpdateToFriends(PlayerStatusVisibility? oldPlayerStatusVisibility, bool showOnlineFriendCount)
	{
		while (!Player.LocalPlayerExists || !Player.LocalPlayer.IsInitialized)
		{
			yield return null;
		}
		List<long> playerIds = new List<long>();
		foreach (Relationship relationship in Relationships.GetAll())
		{
			if (relationship.Type == Relationship.RelationshipType.Friend)
			{
				PlayerPresence presence = null;
				do
				{
					presence = Presence.Get(relationship.PlayerID);
					yield return null;
				}
				while (presence == null);
				bool didIAppearOnlineToPlayer = oldPlayerStatusVisibility.HasValue && Presence.WouldIAppearOnlineToPlayer(oldPlayerStatusVisibility.Value, presence);
				bool doIAppearOnlineToPlayer = Presence.WouldIAppearOnlineToPlayer(SingletonMonoBehaviour<SettingsManager>.Instance.PlayerStatusVisibility, presence);
				if (presence.AppearsOnlineToMe && doIAppearOnlineToPlayer && !didIAppearOnlineToPlayer)
				{
					playerIds.Add(relationship.PlayerID);
				}
			}
		}
		if (SingletonMonoBehaviour<SettingsManager>.Instance.SendFriendOnlineStatusNotification && playerIds.Count > 0)
		{
			Messages.SendStatusOnlineToFriends(playerIds);
		}
		if (showOnlineFriendCount)
		{
			yield return new WaitForSeconds(5f);
			int onlineFriendCount = playerIds.Count;
			if (onlineFriendCount > 0 && SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
			{
				string titleText = string.Format("You have {0} friend{1} online.", onlineFriendCount, (onlineFriendCount != 1) ? "s" : string.Empty);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, titleText, 3f);
			}
		}
	}

	public bool RateLimitAllowsTextMessage(long invitedPlayerId)
	{
		return RateLimitAllowsInvite(invitedPlayerId, 10f, lastTextMessageTimes);
	}

	public bool RateLimitAllowsRequestInvite(long invitedPlayerId)
	{
		return RateLimitAllowsInvite(invitedPlayerId, 30f, lastRequestInviteTimes);
	}

	public bool RateLimitAllowsOnlineInvite(long invitedPlayerId)
	{
		return RateLimitAllowsInvite(invitedPlayerId, 30f, lastOnlineInviteTimes);
	}

	public bool RateLimitAllowsOfflineInvite(long invitedPlayerId)
	{
		return RateLimitAllowsInvite(invitedPlayerId, 300f, lastOfflineInviteTimes);
	}

	private bool RateLimitAllowsInvite(long invitedPlayerId, float minInterval, Dictionary<long, float> lastInviteTimes)
	{
		float value = 0f;
		if (!lastInviteTimes.TryGetValue(invitedPlayerId, out value))
		{
			value = float.MinValue;
		}
		bool result = false;
		if (UnityEngine.Time.realtimeSinceStartup > value + minInterval)
		{
			result = true;
		}
		List<long> list = new List<long>();
		foreach (KeyValuePair<long, float> lastInviteTime in lastInviteTimes)
		{
			float num = UnityEngine.Time.realtimeSinceStartup - 30f;
			if (lastInviteTime.Value < num)
			{
				list.Add(lastInviteTime.Key);
			}
		}
		foreach (long item in list)
		{
			lastInviteTimes.Remove(item);
		}
		return result;
	}

	public void InvitePlayerToGame(long invitedPlayerId, string invitedPlayerName, string invitedPlayerStatus)
	{
		if (!RateLimitAllowsOnlineInvite(invitedPlayerId))
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Spam Alert!", "You can't invite that player again yet. Please wait a few seconds, and try again.");
			return;
		}
		if (!PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanInvite.Value)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Failed to invite", "Non-hosts have been prevented from inviting people.");
			return;
		}
		AnalyticsHelper.SentGameInvite(Player.LocalPlayer, invitedPlayerId, invitedPlayerStatus, GameManager.IsSandboxActive, PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player));
		lastOnlineInviteTimes[invitedPlayerId] = UnityEngine.Time.realtimeSinceStartup;
		Messages.SendGameInvite(invitedPlayerId, delegate(string error)
		{
			if (string.IsNullOrEmpty(error))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Invited", invitedPlayerName, 3f);
				lastOnlineInviteTimes[invitedPlayerId] = UnityEngine.Time.realtimeSinceStartup;
			}
			else
			{
				UnityEngine.Debug.LogError("Unable to send game invite: " + error);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Could not invite", invitedPlayerName, 3f);
				lastOnlineInviteTimes[invitedPlayerId] = float.MinValue;
			}
		});
	}

	public void OfflineInvitePlayerToGame(long invitedPlayerId, string playerName)
	{
		if (!RateLimitAllowsOfflineInvite(invitedPlayerId))
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Spam Alert!", "You can't invite that player again yet. Please wait a few seconds, and try again.");
			return;
		}
		lastOfflineInviteTimes[invitedPlayerId] = UnityEngine.Time.realtimeSinceStartup;
		if (!CanSendOfflineMessageTo(invitedPlayerId))
		{
			return;
		}
		Messages.SendOfflineInvite(invitedPlayerId, delegate(string error, string message)
		{
			bool flag = !string.IsNullOrEmpty(error);
			bool flag2 = !string.IsNullOrEmpty(message);
			if (!flag && !flag2)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Invited " + playerName, 3f);
				AnalyticsHelper.SentOfflineInvite(Player.LocalPlayer, invitedPlayerId, GameManager.IsSandboxActive, PlayerRoomRoleManager.IsPlayerAHost(PhotonNetwork.player));
				lastOfflineInviteTimes[invitedPlayerId] = UnityEngine.Time.realtimeSinceStartup;
			}
			else
			{
				if (flag)
				{
					UnityEngine.Debug.LogError("Unable to send offline invite: " + error + " - " + message);
				}
				else
				{
					UnityEngine.Debug.LogWarning("Unable to send offline invite: " + message);
				}
				lastOfflineInviteTimes[invitedPlayerId] = float.MinValue;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Could not invite " + playerName, message, 3f);
			}
		});
	}

	public void Initialize()
	{
