		RecNet.Notifications.RegisterHandler(RecNet.Notifications.PushNotificationId.ProfileJuniorStatusUpdate, OnJuniorStatusUpdate);
		RecNet.Notifications.RegisterHandler(RecNet.Notifications.PushNotificationId.ServerMaintenance, OnServerMaintenanceReceived);
		HandleServerMaintenanceTimer(fromInitialize: true);
