	private void TryBackupShareCamImages()
	{
		if (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.PlayStation)
		{
			return;
		}
		try
		{
			DirectoryInfo directoryInfo = new DirectoryInfo(Path.Combine(UnityEngine.Application.temporaryCachePath, "ShareCam"));
			if (!directoryInfo.Exists)
			{
				return;
			}
			FileInfo[] files = directoryInfo.GetFiles();
			FileInfo[] array = files;
			foreach (FileInfo file in array)
			{
				BinaryFormatter binaryFormatter = new BinaryFormatter();
				FileStream fileStream = file.Open(FileMode.Open);
				Images.ShareCamImage shareCamImage = (Images.ShareCamImage)binaryFormatter.Deserialize(fileStream);
				fileStream.Close();
				Images.UploadShareCamImage(shareCamImage).Then((Action<string>)delegate
				{
					file.Delete();
				});
			}
		}
		catch (Exception ex)
		{
			UnityEngine.Debug.LogError("Error retrieving share cam images: " + ex);
		}
	}

	private void OnServerMaintenanceReceived(Dictionary<string, object> message)
	{
		ServerMaintenanceDTO serverMaintenanceDTO = Util.Deserialize<ServerMaintenanceDTO>(message);
		if (Config.ServerMaintenance != null)
		{
			Config.ServerMaintenance.StartsInMinutes = serverMaintenanceDTO.StartsInMinutes;
		}
		HandleServerMaintenanceTimer(fromInitialize: false);
	}

	private void HandleServerMaintenanceTimer(bool fromInitialize)
	{
		bool flag = Config.ServerMaintenance != null && Config.ServerMaintenance.StartsInMinutes > 0;
		if (flag && maintenanceTimerCoroutine == null)
		{
			maintenanceTimerCoroutine = StartCoroutine(RunHandleServerMaintenanceTimer(fromInitialize));
		}
		else if (!flag && maintenanceTimerCoroutine != null)
		{
			StopCoroutine(maintenanceTimerCoroutine);
			maintenanceTimerCoroutine = null;
		}
	}

	private IEnumerator RunHandleServerMaintenanceTimer(bool fromInitialize)
	{
		while (Config.ServerMaintenance.StartsInMinutes > 0)
		{
			Config.ServerMaintenance.StartsInMinutes--;
			if (maintenanceWarningCoroutine == null && Config.ServerMaintenance.StartsInMinutes <= 60)
			{
				ServerMaintenanceMinutesVO serverMaintenanceMinutesVO = null;
				ServerMaintenanceMinutesVO[] array = serverMaintenanceMinuteVOs;
				foreach (ServerMaintenanceMinutesVO serverMaintenanceMinutesVO2 in array)
				{
					if (serverMaintenanceMinutesVO2.minutes == Config.ServerMaintenance.StartsInMinutes)
					{
						serverMaintenanceMinutesVO = serverMaintenanceMinutesVO2;
						break;
					}
				}
				if (serverMaintenanceMinutesVO != null || fromInitialize)
				{
					maintenanceWarningCoroutine = StartCoroutine(RunShowServerMaintenanceWarning(serverMaintenanceMinutesVO));
					fromInitialize = false;
				}
			}
			yield return new WaitForSeconds(60f);
		}
		maintenanceTimerCoroutine = null;
	}

	private IEnumerator RunShowServerMaintenanceWarning(ServerMaintenanceMinutesVO serverMaintenanceVO)
	{
		bool playerWasNotReady = false;
		while (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerUI == null || Player.LocalPlayer.PlayerUI.WatchMenu == null)
		{
			playerWasNotReady = true;
			yield return null;
		}
		if (playerWasNotReady)
		{
			yield return new WaitForSeconds(1f);
		}
		int minsRemaining = serverMaintenanceVO?.minutes ?? Config.ServerMaintenance.StartsInMinutes;
		string warningMessage = $"Server will reset in {minsRemaining} mins!";
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Scheduled Maintenance", warningMessage);
		if (serverMaintenanceVO != null)
		{
			AudioManager.Play2DSFX(this.serverMaintenanceVO);
			yield return new WaitForSeconds(this.serverMaintenanceVO.audioClip.length);
			AudioManager.Play2DSFX(serverMaintenanceVO.voClip);
		}
		maintenanceWarningCoroutine = null;
	}

	private void OnJuniorStatusUpdate(Dictionary<string, object> notificationMessage)
	{
		JuniorUpdate juniorUpdate = Util.Deserialize<JuniorUpdate>(notificationMessage);
		UnityEngine.Debug.Log(string.Concat("Junior Status Update:\n\tUT:", juniorUpdate.JuniorUpdateType, "\n\tIsJunior:", juniorUpdate.IsJunior, "\n\tMustQuit:", juniorUpdate.MustQuitGame));
		JuniorUpdateRoutineConfig juniorUpdateRoutineConfig = null;
		switch (juniorUpdate.JuniorUpdateType)
		{
		case JuniorUpdateType.Voluntary:
			juniorUpdateRoutineConfig = ((!juniorUpdate.IsJunior) ? VoluntaryNonJunior : ((!juniorUpdate.MustQuitGame) ? VoluntaryJunior : VoluntaryJunior_MustQuitGame));
			break;
		case JuniorUpdateType.Forced:
			juniorUpdateRoutineConfig = ((!juniorUpdate.IsJunior) ? ForcedNonJunior : ((!juniorUpdate.MustQuitGame) ? ForcedJunior : ForcedJunior_MustQuitGame));
			break;
		case JuniorUpdateType.DateChange:
			juniorUpdateRoutineConfig = DateChangeNonJunior;
			break;
		}
		juniorUpdateRoutineConfig.LockRoom = juniorUpdate.MustQuitGame;
		if (juniorStatusUpdateMessageRoutine != null)
		{
			StopCoroutine(juniorStatusUpdateMessageRoutine);
		}
		juniorStatusUpdateMessageRoutine = StartCoroutine(WaitForPlayerSpawnAndShowMessage(juniorUpdateRoutineConfig));
	}

	private unsafe IEnumerator WaitForPlayerSpawnAndShowMessage(JuniorUpdateRoutineConfig config)
	{
		yield return new WaitUntil(new Func<bool>(null, (nint)(delegate*<bool>)(&SessionManager.get_InDormRoom)));
		yield return new WaitUntil(() => Player.LocalPlayerExists && !Player.LocalPlayer.IsSpawning);
		if (config.LockRoom)
		{
			DormroomSceneManager dormroomSceneManager = RecRoomSceneManager.Instance as DormroomSceneManager;
			if (dormroomSceneManager != null)
			{
				dormroomSceneManager.LockRoom(config.Title, config.Message);
			}
		}
		else
		{
			UIConfirmationDialog.DialogType dialogType = ((SingletonMonoBehaviour<TutorialManager>.Instance.NUXState < TutorialManager.NUXFlowState.Complete) ? UIConfirmationDialog.DialogType.YES_ONLY : UIConfirmationDialog.DialogType.OK_CANCEL);
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(dialogType, config.Title, config.Message);
		}
	}

