	private void LocalProfileDownloaded(Profile profile)
	{
		SetIsJunior();
	}

	public void SetIsJunior()
	{
		bool isJunior = Profiles.LocalProfile.IsJunior();
		bool? flag = wasJunior;
		if (flag == true != isJunior || !flag.HasValue)
		{
			AnalyticsHelper.UpdateJuniorStatus(Profiles.LocalProfile);
			this.OnJuniorStatusChanged.DoIfNotNull(delegate(Action<bool> _)
			{
				_(isJunior);
			});
			foreach (JuniorVisibilityObject item in JuniorVisibilityObject.All)
			{
				item.SetJunior(isJunior);
			}
			UnityEngine.Debug.LogWarningFormat("Junior flag is now {0}active!", (!isJunior) ? "in" : string.Empty);
			if (isJunior)
			{
				PhotonVoiceSettings.Instance.AutoTransmit = false;
				PhotonVoiceNetwork.Disconnect();
				Images.ClearEntireImageCache();
			}
			else
			{
				PhotonVoiceSettings.Instance.AutoTransmit = true;
				PhotonVoiceNetwork.Connect();
			}
		}
		wasJunior = isJunior;
	}

	private IEnumerator FirstPlayerBootRoutine()
	{
		while (!Player.LocalPlayerExists || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		yield return new WaitForSeconds(1f);
		CrashDumpCheck();
		if (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState >= TutorialManager.NUXFlowState.Complete)
		{
			yield return new WaitForSeconds(1f);
			yield return FriendImportCheck();
		}
	}

	private IEnumerator UploadCrashDumps(List<DirectoryInfo> crashDumps)
	{
		foreach (DirectoryInfo dump in crashDumps)
		{
			try
			{
				FileInfo[] files = dump.GetFiles();
				string text = string.Empty;
				string text2 = string.Empty;
				FileInfo[] array = files;
				foreach (FileInfo fileInfo in array)
				{
					if (fileInfo.Name == "output_log.txt")
					{
						text2 = fileInfo.ReadLines("OUTPUTING STACK TRACE", "END OF STACKTRACE");
					}
					else if (fileInfo.Name == "error.log")
					{
						text = fileInfo.ReadLines(2, 1);
					}
				}
				if (!string.IsNullOrEmpty(text) || !string.IsNullOrEmpty(text2))
				{
					AnalyticsHelper.CrashDumpDetails(text, text2);
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			CrashDumpUtil.Ignore(dump);
			yield return null;
		}
	}

