	public bool CanSendOfflineMessageTo(long playerId)
	{
		Profile profile = Profiles.Get(playerId);
		if (Profiles.LocalProfile.IsJunior() || profile.IsJunior())
		{
			return false;
		}
		if (profile != null && (!profile.Verified || !profile.CanReceiveInvites))
		{
			return false;
		}
		return true;
	}

	public void RunGoToPlayerEvent(PlayerEvent targetEvent, LoadSceneSources loadSceneSource)
	{
		AnalyticsHelper.GotoEventFailureReason gotoEventFailureReason = AnalyticsHelper.GotoEventFailureReason.None;
		if (targetEvent != null && (targetEvent.IsHappeningNow || targetEvent.IsOrganizedByLocalPlayer))
		{
			if (!JuniorEventCheck(playNotification: true))
			{
				gotoEventFailureReason = AnalyticsHelper.GotoEventFailureReason.JuniorsProhibited;
			}
			else
			{
				GoToPlayerEventInternal(targetEvent, loadSceneSource);
			}
		}
		else
		{
			gotoEventFailureReason = AnalyticsHelper.GotoEventFailureReason.EventNotActive;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Event not active", "Check the event details", 3f);
		}
		if (gotoEventFailureReason != AnalyticsHelper.GotoEventFailureReason.None)
		{
			AnalyticsHelper.GoToPlayerEventFailed(targetEvent, gotoEventFailureReason);
		}
	}

	private void GoToPlayerEventInternal(PlayerEvent targetEvent, LoadSceneSources loadSceneSource)
	{
		if (RecRoomSceneManager.Instance != null)
		{
			RoomOwnerGate(delegate
			{
				QuestProgressGate(delegate
				{
					string title = "Go to " + targetEvent.Name;
					PartyGate(title, delegate
					{
						LoadSceneSource = loadSceneSource;
						JoinPlayerEvent(targetEvent, JoinRoomInviteMode.InviteParty);
					}, delegate
					{
						LoadSceneSource = loadSceneSource;
						JoinPlayerEvent(targetEvent, JoinRoomInviteMode.LeaveParty);
					});
				});
			});
		}
		else
		{
			UnityEngine.Debug.LogError("Button_JoinEvent RecRoomSceneManager is null.");
		}
	}

	public void RunJoinRoom(string roomName, LoadSceneSources loadSceneSource, bool isPrivate, List<string> searchTagsUsed, Action<GameSessions.JoinGameErrorCode> onResponseCallback = null)
	{
		RunJoinRoom(roomName, null, loadSceneSource, isPrivate, searchTagsUsed, onResponseCallback);
	}

	public void RunJoinRoom(string roomName, string roomSceneName, LoadSceneSources loadSceneSource, bool isPrivate, List<string> searchTagsUsed, Action<GameSessions.JoinGameErrorCode> onResponseCallback = null)
	{
		if (!(RecRoomSceneManager.Instance != null) || roomName == null)
		{
			return;
		}
		if (this.OnSwitchRoomRequested != null)
		{
			CancelSwitchRoomsRequest cancelSwitchRoomsRequest = new CancelSwitchRoomsRequest();
			this.OnSwitchRoomRequested(cancelSwitchRoomsRequest);
			if (cancelSwitchRoomsRequest.IsCancelRequested)
			{
				UnityEngine.Debug.Log("JoinRoom request canceled");
				return;
			}
		}
		if (!JuniorRoomCheck(roomName, playNotification: true))
		{
			return;
		}
		RoomOwnerGate(delegate
		{
			QuestProgressGate(delegate
			{
				if (roomName == "DormRoom")
				{
					JoinRoom("DormRoom", null, isPrivate: false, searchTagsUsed, JoinRoomInviteMode.LeaveParty);
				}
				else
				{
					string title = $"Going to ^{roomName}";
					PartyGate(title, delegate
					{
						LoadSceneSource = loadSceneSource;
						GoToRoom(roomName, roomSceneName, isPrivate, loadSceneSource, JoinRoomInviteMode.InviteParty, searchTagsUsed, onResponseCallback);
					}, delegate
					{
						LoadSceneSource = loadSceneSource;
						GoToRoom(roomName, roomSceneName, isPrivate, loadSceneSource, JoinRoomInviteMode.LeaveParty, searchTagsUsed, onResponseCallback);
					});
				}
			});
		});
	}

