	public void RequestGameInvite(long playerId, string playerName, string playerStatus)
	{
		if (!JuniorPlayerJoinCheck(playerId))
		{
			return;
		}
		if (!RateLimitAllowsRequestInvite(playerId))
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, "Spam Alert!", "You can't request an invite from that player again yet. Please wait a few seconds, and try again.");
			return;
		}
		lastRequestInviteTimes[playerId] = UnityEngine.Time.realtimeSinceStartup;
		AnalyticsHelper.RequestGameInvite(Player.LocalPlayer, playerId, playerStatus);
		Messages.SendRequestGameInvite(playerId, delegate(string error)
		{
			if (string.IsNullOrEmpty(error))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Request Sent", playerName, 3f);
				lastRequestInviteTimes[playerId] = UnityEngine.Time.realtimeSinceStartup;
			}
			else
			{
				UnityEngine.Debug.LogError("Unable to send game invite request: " + error);
				lastRequestInviteTimes[playerId] = float.MinValue;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Could not send request", playerName, 3f);
			}
		});
	}

	public bool JuniorPlayerJoinCheck(long joinPlayerId, bool playNotification = false)
	{
		if (Profiles.LocalProfile != null && !Profiles.LocalProfile.HasBirthday)
		{
			UnityEngine.Debug.LogError("Tried to go somewhere without a valid birthday!");
			return false;
		}
		if (!Profiles.LocalProfile.IsJunior())
		{
			return true;
		}
		PlayerPresence playerPresence = Presence.Get(joinPlayerId);
		if (playerPresence != null && playerPresence.GameSession != null)
		{
			return JuniorGameSessionCheck(playerPresence.GameSession, playNotification);
		}
		if (playNotification)
		{
			PlayJuniorWarningMessage();
		}
		return false;
	}

