	private void RegistrationGate(string friendlyName, string title, Action<bool> OnConfirmed, Action<bool> OnRejected = null)
	{
		bool locked = true;
		string bodyText;
		string yesText;
		string noText;
		if (Profiles.LocalProfile.RegistrationStatus == RegistrationStatus.Unregistered)
		{
			bodyText = $"Register your account for free to access {friendlyName}!";
			yesText = "Register";
			noText = "Not now";
		}
		else
		{
			yesText = "Resend";
			noText = "OK";
			bodyText = $"To access {friendlyName}, verify your account by clicking the link in the email we sent.";
		}
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, title, bodyText, yesText, noText).Then(delegate(ConfirmDialogResponses r)
		{
			switch (r)
			{
			case ConfirmDialogResponses.Affirmative:
				if (OnConfirmed != null)
				{
					OnConfirmed(locked);
				}
				break;
			case ConfirmDialogResponses.Negative:
				if (OnRejected != null)
				{
					OnRejected(locked);
				}
				break;
			}
		});
	}

	private void LocalPlayerLeaveParty()
