	private void PartyGate(string title, Action OnConfirmed, Action OnRejected = null)
	{
		if (!Player.LocalPlayerExists)
		{
			OnConfirmed();
			return;
		}
		int partySize = Player.LocalPlayer.PlayerParty.PartySize;
		if (partySize <= 1)
		{
			OnConfirmed();
			return;
		}
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(title, "Do you want to invite your party to go with you?").Then(delegate(ConfirmDialogResponses r)
		{
			switch (r)
			{
			case ConfirmDialogResponses.Affirmative:
				OnConfirmed();
				break;
			case ConfirmDialogResponses.Negative:
				OnRejected?.Invoke();
				break;
			}
		});
	}

	private void RoomOwnerGate(Action OnConfirmed, Action OnRejected = null)
	{
		if (!Player.LocalPlayerExists)
		{
			OnConfirmed();
			return;
		}
		if (!GameSessions.LocalGameSession.IsSandbox || !PlayerRoomRoleManager.Instance.PlayerHasRole(PhotonNetwork.player, RoomRoleId.AG_COOWNER))
		{
			OnConfirmed();
			return;
		}
		DateTime dateTime = RecNet.Rooms.LocalRoomScene.DataModifiedAt.ToLocalTime();
		TimeSpan timeSpan = DateTime.Now - dateTime;
		TimeSpan timeSpan2 = DateTime.Now - lastLocalPlayerSpawnTime;
		if (timeSpan.TotalSeconds < (double)minPromptToSaveRoomTimeSeconds || timeSpan2.TotalSeconds < (double)minPromptToSaveRoomTimeSeconds)
		{
			OnConfirmed();
			return;
		}
		RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
		string titleText = $"Leave ^{localRoomDetails.Room.Name} without saving?";
		string empty = string.Empty;
		string text;
		int num;
		if (timeSpan.Days > 0)
		{
			text = "day";
			num = timeSpan.Days;
		}
		else if (timeSpan.Hours > 0)
		{
			text = "hour";
			num = timeSpan.Hours;
		}
		else if (timeSpan.Minutes > 0)
		{
			text = "minute";
			num = timeSpan.Minutes;
		}
		else
		{
			text = "second";
			num = timeSpan.Seconds;
		}
		empty = string.Format("This room was last saved {0} {1}{2} ago.\n(Last saved at {3} on {4})", num, text, (num <= 1) ? string.Empty : "s", dateTime.ToShortTimeString(), dateTime.ToShortDateString());
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(titleText, empty).Then(delegate(ConfirmDialogResponses r)
		{
			switch (r)
			{
			case ConfirmDialogResponses.Affirmative:
				OnConfirmed();
				break;
			case ConfirmDialogResponses.Negative:
				OnRejected?.Invoke();
				break;
			}
		});
	}

	private void GoToRoom(string roomName, string roomSceneName, bool isPrivate, LoadSceneSources loadSceneSource, JoinRoomInviteMode inviteMode, List<string> searchTagsUsed, Action<GameSessions.JoinGameErrorCode> onResponseCallback = null)
	{
		string localRoomName = ((RecNet.Rooms.LocalRoomDetails == null) ? string.Empty : RecNet.Rooms.LocalRoomDetails.Room.Name);
		JoinRoom(roomName, roomSceneName, isPrivate, searchTagsUsed, inviteMode).Then(delegate(GameSessions.JoinGameErrorCode response)
		{
			AnalyticsHelper.RoomJoinRequest(roomName, loadSceneSource, localRoomName, response.ToString());
			if (onResponseCallback != null)
			{
				onResponseCallback(response);
			}
		});
	}

	private void QuestProgressGate(Action OnConfirmed, Action OnRejected = null)
	{
		if (!Player.LocalPlayerExists || NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager == null)
		{
			OnConfirmed();
			return;
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState != GameStates.GAME_RUNNING && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CanContinue)
		{
			OnConfirmed();
			return;
		}
		string arg = string.Empty;
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.Locations.Length > 0 && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.Locations[0] == RoomSceneLocations.CRESCENDO_OF_THE_BLOOD_MOON)
		{
			arg = "  (Silver banked at checkpoints will be saved)";
		}
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Leave Quest", $"Are you sure you want to leave?  You will lose your current progress on this quest.{arg}").Then(delegate(ConfirmDialogResponses r)
		{
			switch (r)
			{
			case ConfirmDialogResponses.Affirmative:
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance as QuestManager != null)
				{
					OnConfirmed();
				}
				break;
			case ConfirmDialogResponses.Negative:
				OnRejected?.Invoke();
				break;
			}
		});
	}

