	[Obfuscation(Exclude = false)]
	public static Coroutine DeveloperGatedActionCoroutine(Action developerAction = null, Action nonDeveloperAction = null)
	{
		return SingletonMonoBehaviour<SessionManager>.Instance.StartCoroutine(GateRoutine(developerAction, nonDeveloperAction));
	}

	private static IEnumerator GateRoutine(Action developerAction = null, Action nonDeveloperAction = null)
	{
		bool remoteIsDeveloper = false;
		bool localIsDeveloper = IsDeveloper;
		if (IsDeveloper)
		{
			yield return Profiles.GetFromServer(RecNet.Core.LocalProfileId, delegate(string e, Profile profile)
			{
				if (string.IsNullOrEmpty(e) && profile.Developer.GetDecrypted())
				{
					remoteIsDeveloper = true;
				}
			});
		}
		if (remoteIsDeveloper)
		{
			developerAction?.Invoke();
			yield break;
		}
		if (localIsDeveloper)
		{
			AnalyticsHelper.DeveloperFlagCheat();
		}
		nonDeveloperAction?.Invoke();
	}

	private IEnumerator FriendImportCheck()
	{
		DateTime? lastFriendImport = lastFriendImportUTC;
		if (!lastFriendImport.HasValue || !(lastFriendImport.Value.Add(new TimeSpan(24, 0, 0)) > DateTime.UtcNow))
		{
			doneImporting = false;
			yield return RunImportFriends(AnalyticsHelper.ImportFriendsSources.BootCheck);
			yield return new WaitUntil(() => doneImporting);
			lastFriendImportUTC = DateTime.UtcNow;
		}
	}

	public void ImportFriends(AnalyticsHelper.ImportFriendsSources source)
	{
		StartCoroutine(RunImportFriends(source));
	}

	private IEnumerator RunImportFriends(AnalyticsHelper.ImportFriendsSources source)
	{
		yield return FriendImporter.GetPlatformFriendProfiles(delegate(List<Profile> platformFriends)
		{
			if (FriendImporter.CanImportAFriend(platformFriends) && !Player.LocalPlayer.PlayerUI.WatchMenu.AreMessagesPaused)
			{
				Player.LocalPlayer.PlayerUI.WatchMenu.PlayAttract();
				Profile[] importableFriends = platformFriends.Where(UnityExtensions.CanSendFriendRequest).ToArray();
				Player.LocalPlayer.PlayerUI.WatchMenu.ShowImportFriendsDialog().Then(delegate(ConfirmDialogResponses r)
				{
					if (r == ConfirmDialogResponses.Affirmative)
					{
						AnalyticsHelper.ImportAllPlatformFriends(importableFriends.Count(), source);
						StartCoroutine(FriendImporter.SendAllFriendRequests(this, importableFriends.ToArray()));
					}
					DoneImporting();
				});
			}
			else
			{
				DoneImporting();
			}
		});
	}

	private void DoneImporting()
	{
		doneImporting = true;
		if (DoneImportingAction != null)
		{
			DoneImportingAction();
		}
	}

	private GameSessions.JoinGameErrorCode? CheckForCachedRoomJoinResponse(string roomName)
	{
		CleanupRoomJoinCache();
		for (int i = 0; i < recentFailedRoomRequests.Count; i++)
		{
			if (recentFailedRoomRequests[i].roomName == roomName)
			{
				return recentFailedRoomRequests[i].cachedResponse;
			}
		}
		return null;
	}

	private void CleanupRoomJoinCache()
	{
		if (recentFailedRoomRequests.Count == 0)
		{
			return;
		}
		DateTime timeUTC = DateTime.UtcNow.AddSeconds(-60.0);
		int num = recentFailedRoomRequests.Count - 1;
		for (int i = 0; i < recentFailedRoomRequests.Count; i++)
		{
			if (!recentFailedRoomRequests[i].IsResponseOlderThan(timeUTC))
			{
				num = i - 1;
				break;
			}
		}
		if (num >= 0)
		{
			recentFailedRoomRequests.RemoveRange(0, num + 1);
		}
	}

	private void CacheRoomFailureResponseIfNoOlderEntry(string roomName, GameSessions.JoinGameErrorCode response)
	{
		for (int i = 0; i < recentFailedRoomRequests.Count; i++)
		{
			if (recentFailedRoomRequests[i].roomName == roomName)
			{
				return;
			}
		}
		RoomJoinRequestRecord item = new RoomJoinRequestRecord
		{
			roomName = roomName,
			requestTimeUTC = DateTime.UtcNow,
			cachedResponse = response
		};
		recentFailedRoomRequests.Add(item);
	}

	private IPromise<GameSessions.JoinGameErrorCode> JoinRoom(string roomName, string roomSceneName, bool isPrivate, List<string> searchTagsUsed, JoinRoomInviteMode inviteMode)
	{
		if (inviteMode == JoinRoomInviteMode.PartyAutoFollow || inviteMode == JoinRoomInviteMode.EveryoneAutoFollow)
		{
			throw new Exception("AutoFollow mode is not supported for JoinRoom");
		}
		return JoinHelper($"Going to ^{roomName}{((roomSceneName == null) ? string.Empty : $".{roomSceneName}")}", inviteMode, delegate(long[] additionalPlayers)
		{
			GameSessions.JoinGameErrorCode? joinGameErrorCode = CheckForCachedRoomJoinResponse(roomName);
			return joinGameErrorCode.HasValue ? new CompletedPromise<GameSessions.JoinGameErrorCode>(joinGameErrorCode.Value) : GameSessions.JoinRoom(roomName, roomSceneName, isPrivate, additionalPlayers, searchTagsUsed, GetRecNetAdditionalPlayerJoinMode(inviteMode)).Then(delegate(GameSessions.JoinGameErrorCode response)
			{
				if (response != GameSessions.JoinGameErrorCode.Success)
				{
					CacheRoomFailureResponseIfNoOlderEntry(roomName, response);
				}
			});
		});
	}

	private void JoinRoomScene(string roomSceneName, JoinRoomInviteMode inviteMode)
	{
		JoinHelper("Going to " + roomSceneName, inviteMode, delegate(long[] additionalPlayers)
		{
			GameSessions.AdditionalPlayerJoinMode recNetAdditionalPlayerJoinMode = GetRecNetAdditionalPlayerJoinMode(inviteMode);
			return GameSessions.JoinRoomScene(roomSceneName, additionalPlayers, recNetAdditionalPlayerJoinMode);
		});
	}

	private void JoinPlayerEvent(PlayerEvent ev, JoinRoomInviteMode inviteMode)
	{
		if (inviteMode == JoinRoomInviteMode.PartyAutoFollow || inviteMode == JoinRoomInviteMode.EveryoneAutoFollow)
