			throw new Exception("AutoFollow mode is not supported for JoinEvent");
		}
		JoinHelper("Joining event : " + ev.Name, inviteMode, delegate(long[] additionalPlayers)
		{
			AnalyticsHelper.GoToPlayerEvent(ev, SingletonMonoBehaviour<SessionManager>.Instance.LoadSceneSource);
			return GameSessions.JoinPlayerEvent(ev, additionalPlayers);
		});
