	public void JoinPlayer(long playerId, JoinRoomInviteMode inviteMode)
	{
		if (inviteMode == JoinRoomInviteMode.PartyAutoFollow || inviteMode == JoinRoomInviteMode.EveryoneAutoFollow)
		{
			throw new Exception("AutoFollow mode is not supported for JoinPlayer");
		}
		PhotonPlayer[] otherPlayers = PhotonNetwork.otherPlayers;
		foreach (PhotonPlayer photonPlayer in otherPlayers)
		{
			if (photonPlayer.RecNetProfileId == playerId)
			{
				return;
			}
		}
		Profile profile = Profiles.Get(playerId);
		string message = string.Format("Joining {0}", (profile == null) ? "player" : profile.DisplayName.ToString().Truncate(20, "..."));
		JoinHelper(message, inviteMode, (long[] additionalPlayers) => GameSessions.JoinPlayer(playerId, additionalPlayers));
	}

	private void JoinGameSession(GameSession gameSession, JoinRoomInviteMode inviteMode)
	{
		if (inviteMode == JoinRoomInviteMode.PartyAutoFollow || inviteMode == JoinRoomInviteMode.EveryoneAutoFollow)
		{
			throw new Exception("AutoFollow mode is not supported for JoinGameSession");
		}
		JoinHelper("Joining game", inviteMode, (long[] additionalPlayers) => GameSessions.JoinInstance(gameSession.GameSessionId, additionalPlayers));
	}

	private IPromise<GameSessions.JoinGameErrorCode> JoinHelper(string message, JoinRoomInviteMode inviteMode, Func<long[], IPromise<GameSessions.JoinGameErrorCode>> joinAction)
	{
		if (LeaveSceneStarted)
		{
			return new ErroredPromise<GameSessions.JoinGameErrorCode>("Join game already in progress");
		}
		LeaveSceneStarted = true;
		long[] arg = null;
		switch (inviteMode)
		{
		case JoinRoomInviteMode.LeaveParty:
			LocalPlayerLeaveParty();
			break;
		case JoinRoomInviteMode.InviteParty:
		case JoinRoomInviteMode.PartyAutoFollow:
			if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerParty.PartySize > 1)
			{
				arg = Player.LocalPlayer.PlayerParty.GetPlayerIDs();
			}
			break;
		case JoinRoomInviteMode.EveryoneAutoFollow:
			arg = PhotonNetwork.otherPlayers.Select((PhotonPlayer p) => p.RecNetProfileId).ToArray();
			break;
		}
		StartCoroutine(RunJoinHelperNotification(message));
		return joinAction(arg).Error(delegate
		{
			LeaveSceneStarted = false;
			ScreenSpaceNotificationManager.NotificationType style = ScreenSpaceNotificationManager.NotificationType.Medium;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(style, "Unable to change rooms", "If this persists, contact support", 5f);
		}).Then(delegate(GameSessions.JoinGameErrorCode response)
		{
			if (response != GameSessions.JoinGameErrorCode.Success)
			{
				LeaveSceneStarted = false;
				ScreenSpaceNotificationManager.NotificationType style = ScreenSpaceNotificationManager.NotificationType.Medium;
				string title = null;
				string message2 = null;
				GetJoinGameErrorCodeMessage(response, out title, out message2);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(style, title, message2, 5f);
				if (response == GameSessions.JoinGameErrorCode.RegistrationRequired && Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerUI.WatchMenu.ShowRegistrationDialog(fromReminder: false, Profiles.LocalProfile.IsJunior(), message2);
				}
			}
		});
	}

	public static void GetJoinGameErrorCodeMessage(GameSessions.JoinGameErrorCode errorCode, out string title, out string message)
	{
		title = "Unable to change rooms";
		message = string.Empty;
		switch (errorCode)
		{
		case GameSessions.JoinGameErrorCode.AlreadyInTargetGameSession:
			break;
		case GameSessions.JoinGameErrorCode.AlreadyInBestGameSession:
			title = "Unable to change rooms";
			message = "Already in best lobby available";
			break;
		case GameSessions.JoinGameErrorCode.NoSuchGame:
			title = "Unable to Join Room";
			message = "Room does not exist";
			break;
		case GameSessions.JoinGameErrorCode.PlayerNotOnline:
			title = "Unable to Join Player";
			message = "Player is not in Rec Room";
			break;
		case GameSessions.JoinGameErrorCode.InsufficientSpace:
			title = "Room Full";
			message = "There is no more space in this room";
			break;
		case GameSessions.JoinGameErrorCode.EventNotStarted:
			title = "Event Not Started";
			message = "The event has not yet started";
			break;
		case GameSessions.JoinGameErrorCode.EventAlreadyFinished:
			title = "Event Finished";
			message = "The event has already finished";
			break;
		case GameSessions.JoinGameErrorCode.EventCreatorNotReady:
			title = "Event Not Ready";
			message = "The host hasn't opened this event yet";
			break;
		case GameSessions.JoinGameErrorCode.BlockedFromRoom:
			title = "Blocked";
			message = "You have been blocked from this room";
			break;
		case GameSessions.JoinGameErrorCode.ProfileLocked:
			title = "Profile Locked";
			message = "You have been locked in this room";
			break;
		case GameSessions.JoinGameErrorCode.NoBirthday:
			title = "No Birthday";
			message = "Please enter your birth date";
			break;
		case GameSessions.JoinGameErrorCode.MarkedForDelete:
			title = "Please Restart";
			message = "You must restart the game to keep playing";
			break;
		case GameSessions.JoinGameErrorCode.JuniorNotAllowed:
			title = "Juniors Prohibited";
			message = "Not available to junior profiles";
			break;
		case GameSessions.JoinGameErrorCode.RegistrationRequired:
			title = "Registration Required";
			message = "Register your account to access this room";
			break;
		case GameSessions.JoinGameErrorCode.Banned:
			title = "Profile Timeout";
			message = "Your profile is in timeout. Conduct@againstgrav.com";
			break;
		case GameSessions.JoinGameErrorCode.ScreenModeNotAllowed:
			title = "Screen Mode Not Supported";
			message = "The room you tried to join does not support screen mode.";
			break;
		case GameSessions.JoinGameErrorCode.VRModeNotAllowed:
			title = "VR Mode Not Supported";
			message = "The room you tried to join is screen mode only.";
			break;
		case GameSessions.JoinGameErrorCode.UpdateRequired:
			title = "Update Required";
			message = "Please quit Rec Room and download the update.";
			break;
		case GameSessions.JoinGameErrorCode.NoSuchRoom:
			title = "Unable to Join Room";
			message = "Room does not exist";
			break;
		case GameSessions.JoinGameErrorCode.RoomCreatorNotReady:
			title = "Room Not Ready";
			message = "The host hasn't opened this room yet";
			break;
		case GameSessions.JoinGameErrorCode.RoomIsNotActive:
			title = "Unable to Join Room";
			message = "Room is not active. conduct@againstgrav.com";
			break;
		case GameSessions.JoinGameErrorCode.RoomBlockingCreator:
			title = "Unable to Join Room";
			message = "You are blocking the creator of this room.";
			break;
		case GameSessions.JoinGameErrorCode.RoomBlockedByCreator:
			title = "Unable to Join Room";
			message = "You are being blocked by the creator of this room.";
			break;
		case GameSessions.JoinGameErrorCode.RoomIsPrivate:
			title = "Unable to Join Room";
			message = "Room is private.";
			break;
		case GameSessions.JoinGameErrorCode.PlayerTypeNotSupported:
			title = "Unable to Join Room";
			message = "Room does not support your player type.";
			break;
		case (GameSessions.JoinGameErrorCode)19:
		case (GameSessions.JoinGameErrorCode)26:
		case (GameSessions.JoinGameErrorCode)27:
		case (GameSessions.JoinGameErrorCode)28:
		case (GameSessions.JoinGameErrorCode)29:
			break;
		}
	}

	private IEnumerator RunJoinHelperNotification(string message)
	{
		int progress = 0;
		while (LeaveSceneStarted)
		{
			string dots = progress switch
			{
				0 => ".", 
				1 => "..", 
				_ => "...", 
			};
			int num = progress + 1;
			progress = num % 3;
			string subTitle = $"{message}{dots}";
			if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, string.Empty, subTitle, 1f, null, updateIfSameStyle: true);
			}
			yield return new WaitForSeconds(0.5f);
		}
	}
