	public float PersonalSpaceDistance => GetPersonalSpaceDistance(PersonalSpace);

	public PersonalSpaceType PersonalSpace
	{
		get
		{
			if (Profiles.LocalProfile.IsJunior())
			{
				return juniorTeleportBuffer;
			}
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				return PersonalSpaceType.Small;
			}
			return (PersonalSpaceType)GetIntProperty(TELEPORT_BUFFER_PREF, 1);
		}
		set
		{
			SetIntProperty(TELEPORT_BUFFER_PREF, (int)value, sendAnalytics: true, value.ToString());
			if (this.PersonalSpaceDistanceChanged != null)
			{
				this.PersonalSpaceDistanceChanged();
			}
		}
	}

	public IgnoreBuffer IgnoreBuffer
	{
		get
		{
			return (!Profiles.LocalProfile.IsJunior()) ? ((IgnoreBuffer)GetIntProperty(IGNORE_BUFFER_PREF, 2)) : juniorIgnoreBuffer;
		}
		set
		{
			SetIntProperty(IGNORE_BUFFER_PREF, (int)value, sendAnalytics: true, value.ToString());
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.IgnoreBuffer = IgnoreBuffer;
			}
		}
	}

	public PlayerStatusVisibility PlayerStatusVisibility
	{
		get
		{
			return (PlayerStatusVisibility)GetIntProperty(PLAYER_STATUS_VISIBILITY_PREF);
		}
		set
		{
			PlayerStatusVisibility playerStatusVisibility = PlayerStatusVisibility;
			if (value != playerStatusVisibility)
			{
				SetIntProperty(PLAYER_STATUS_VISIBILITY_PREF, (int)value, sendAnalytics: true, string.Empty);
				if (AnalyticsHelper.HasClientInitialized)
				{
					AnalyticsHelper.UpdatePlayerStatusVisibility();
				}
				if (this.PlayerStatusVisibilityChanged != null)
				{
					this.PlayerStatusVisibilityChanged(playerStatusVisibility, value);
				}
			}
		}
	}

