	private void ApplyQualitySetting()
	{
		bool flag = false;
		string text = QualitySetting.ToString();
		int index = QualitySettings.names.Length - 1;
		for (int i = 0; i < QualitySettings.names.Length; i++)
		{
			if (text == QualitySettings.names[i])
			{
				index = i;
				flag = true;
				break;
			}
		}
		if (!flag)
		{
			UnityEngine.Debug.LogError("Could not find the Quality Setting named " + text);
			return;
		}
		UnityEngine.Debug.Log($"Changing the Quality Setting to \"{text}\"");
		QualitySettings.SetQualityLevel(index, applyExpensiveChanges: true);
	}

	[PreBuildValidationStep("Verify Default Quality Setting is Fantastic", BuildPlatform.All, BuildFlavor.All)]
	private static void VerifyDefaultQualitySetting()
	{
		if (QualitySettings.names[QualitySettings.GetQualityLevel()] != "Fantastic")
		{
			PreBuildValidationSteps.Warn("Default quality setting is not set to Fantastic");
		}
	}

	protected override void Awake()
	{
		base.Awake();
		teleportBufferSizeMap = new Dictionary<PersonalSpaceType, float>();
		for (int i = 0; i < teleportBufferSizes.Length; i++)
		{
			if (!teleportBufferSizeMap.ContainsKey(teleportBufferSizes[i].buffer))
			{
				teleportBufferSizeMap.Add(teleportBufferSizes[i].buffer, teleportBufferSizes[i].distance);
			}
			else
			{
				UnityEngine.Debug.LogError("TeleportBufferSize can not contain duplicate values for " + teleportBufferSizes[i].buffer);
			}
		}
		if (teleportBufferSizes.Length != System.Enum.GetValues(typeof(PersonalSpaceType)).Length)
		{
			UnityEngine.Debug.LogError("TeleportBufferSizes does not have correct number of values.");
		}
		ignoreBufferSizeMap = new Dictionary<IgnoreBuffer, IgnoreBufferSize>();
		for (int j = 0; j < ignoreBufferSizes.Length; j++)
		{
			if (!ignoreBufferSizeMap.ContainsKey(ignoreBufferSizes[j].buffer))
			{
				ignoreBufferSizeMap.Add(ignoreBufferSizes[j].buffer, ignoreBufferSizes[j]);
			}
			else
			{
				UnityEngine.Debug.LogError("IgnoreBufferSize can not contain duplicate values for " + ignoreBufferSizes[j].buffer);
			}
		}
		if (ignoreBufferSizes.Length != System.Enum.GetValues(typeof(IgnoreBuffer)).Length)
		{
			UnityEngine.Debug.LogError("ignoreBufferSizes does not have correct number of values.");
		}
	}

	public void Initialize()
	{
		UnityEngine.Debug.Log("Quality setting : " + QualitySetting);
		ApplyQualitySetting();
		AnalyticsHelper.TotalSessionCount(++TotalSessionCount);
		AnalyticsHelper.SettingsInitialized();
	}

	public float GetPersonalSpaceDistance(PersonalSpaceType buffer)
	{
		return teleportBufferSizeMap[buffer];
	}

	public IgnoreBufferSize GetIgnoreBufferSize(IgnoreBuffer buffer)
	{
		return ignoreBufferSizeMap[buffer];
	}

	public void TemporarilyIncreaseComfortSettings()
	{
		if (TemporarilyIncreaseComfortSettingsRoutine != null)
		{
			SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumePercentage *= 2f;
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.IgnoreBuffer = IgnoreBuffer;
			}
			StopCoroutine(TemporarilyIncreaseComfortSettingsRoutine);
		}
		TemporarilyIncreaseComfortSettingsRoutine = StartCoroutine(RunTemporarilyIncreaseComfortSettings());
	}

	private IEnumerator RunTemporarilyIncreaseComfortSettings()
	{
		if (Player.LocalPlayerExists)
		{
			VoiceVolumeUpdated = false;
			IgnoreBubbleUpdated = false;
			float tempVol = SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumePercentage;
			IgnoreBuffer tempBuffer = Player.LocalPlayer.IgnoreBuffer;
			SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumePercentage /= 2f;
			Player.LocalPlayer.IgnoreBuffer = IgnoreBuffer.Large;
			while (Player.LocalPlayerExists && Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
			{
				yield return null;
			}
			if (!VoiceVolumeUpdated)
			{
				SingletonMonoBehaviour<AudioManager>.Instance.VoiceVolumePercentage = tempVol;
			}
			if (!IgnoreBubbleUpdated && Player.LocalPlayerExists)
			{
				Player.LocalPlayer.IgnoreBuffer = tempBuffer;
			}
			TemporarilyIncreaseComfortSettingsRoutine = null;
		}
	}

	private int GetIntProperty(string propertyName, int defaultValue = 0)
	{
		if (!intPropertyMap.ContainsKey(propertyName))
		{
			intPropertyMap.Add(propertyName, RecroomPrefs.GetInt(propertyName, defaultValue));
		}
		return intPropertyMap[propertyName];
	}

	private bool GetBoolProperty(string propertyName, bool defaultValue)
	{
		return GetIntProperty(propertyName, defaultValue ? 1 : 0) > 0;
	}

	private float GetFloatProperty(string propertyName, float defaultValue = 0f)
	{
		if (!floatPropertyMap.ContainsKey(propertyName))
		{
			floatPropertyMap.Add(propertyName, RecroomPrefs.GetFloat(propertyName, defaultValue));
		}
		return floatPropertyMap[propertyName];
	}

	private bool SetBoolProperty(string propertyName, bool value, bool sendAnalytics = true)
	{
		return SetIntProperty(propertyName, value ? 1 : 0, sendAnalytics, (!value) ? "false" : "true");
	}

	private bool SetIntProperty(string propertyName, int value, bool sendAnalytics = true, string analyticsLabel = "")
	{
		int intProperty = GetIntProperty(propertyName);
		if (intProperty != value)
		{
			intPropertyMap[propertyName] = value;
			RecroomPrefs.SetInt(propertyName, value);
			RecroomPrefs.Save();
			return true;
		}
		return false;
	}

	private bool SetFloatProperty(string propertyName, float value, bool sendAnalytics = true, string analyticsLabel = "")
	{
		float floatProperty = GetFloatProperty(propertyName);
		if (floatProperty != value)
		{
			floatPropertyMap[propertyName] = value;
			RecroomPrefs.SetFloat(propertyName, value);
			RecroomPrefs.Save();
			return true;
		}
		return false;
	}
}
public abstract class SingletonMonoBehaviourBase : UnityEngine.MonoBehaviour, IGameSingleton
{
	[SerializeField]
	private GameRestartBehaviors gameRestartBehavior = GameRestartBehaviors.DestroyOld;

	public virtual GameRestartBehaviors GameRestartBehavior => gameRestartBehavior;

	public GameObject GameObject => base.gameObject;
}
public class SplitTesting : SingletonMonoBehaviour<SplitTesting>
{
	[SkipRename]
	public enum PaddleballSocialNUX_2018_01_11
	{
		SkipSocialNUX,
		RunSocialNUX,
		VideoSocialNUX
	}

	[SkipRename]
	public enum AlternateNUXFirstActivity_2018_06_12
	{
		Paddleball,
		Paintball,
		UGCRoom
	}

	[SkipRename]
	public enum TokensAndDressUpNUX_2018_07_16
	{
		SkipTokensAndDressUpNUX,
		RunTokensAndDressUpNUX
	}

	[SkipRename]
	public enum ScreensNUX_2018_08_02
	{
		EnableScreensNUX,
		DisableScreensNUX
	}

	private const string SAVED_SPLIT_TEST_PLAYER_PREFS_KEY = "SplitTestAssignedSegments";

	private const int SERIALIZATION_VERSION = 1;

	private Dictionary<string, List<string>> activeTests = new Dictionary<string, List<string>>();

	private Dictionary<string, string> savedPlayerSegments = new Dictionary<string, string>();

	private Dictionary<string, string> softServerOverrides = new Dictionary<string, string>();

	private Dictionary<string, string> hardServerOverrides = new Dictionary<string, string>();

	public void ForceExperimentSegmentIfUnassigned(string experimentName, string segmentAssignment)
	{
		if (!IsValidExperimentValue(experimentName, segmentAssignment))
		{
			UnityEngine.Debug.LogErrorFormat("Forced experiment value {0} for test {1} isn't valid", segmentAssignment, experimentName);
		}
		else if (!IsAssignedToExperiment(experimentName))
		{
			savedPlayerSegments.Add(experimentName, segmentAssignment);
			AmplitudeAnalyticsClient.Identify().WithUserProperty(experimentName, segmentAssignment).LogAsync();
		}
	}

	public void OverrideViaCommandLineArgs(string[] overrideValues)
	{
		if (overrideValues == null)
		{
			return;
		}
		foreach (string text in overrideValues)
		{
			string matchedExperiment = null;
			string matchedSegment = null;
			if (FindMatchingExperimentAndSegment(text, out matchedExperiment, out matchedSegment))
			{
				UnityEngine.Debug.LogFormat("Split Test command line override: {0} -- {1} / {2}", text, matchedExperiment, matchedSegment);
				if (savedPlayerSegments.ContainsKey(matchedExperiment))
				{
					savedPlayerSegments[matchedExperiment] = matchedSegment;
				}
				else
				{
					savedPlayerSegments.Add(matchedExperiment, matchedSegment);
				}
				AmplitudeAnalyticsClient.Identify().WithUserProperty(matchedExperiment, matchedSegment).LogAsync();
			}
			else
			{
				UnityEngine.Debug.LogFormat("Failed to find matching experiment for override: {0}", text);
			}
		}
	}

	public bool IsAssignedToExperiment(string experimentName, bool countServerOverrides = true)
	{
		if (!IsActiveExperiment(experimentName))
		{
			return false;
		}
		if (countServerOverrides)
		{
			return savedPlayerSegments.ContainsKey(experimentName) || softServerOverrides.ContainsKey(experimentName) || hardServerOverrides.ContainsKey(experimentName);
		}
		return savedPlayerSegments.ContainsKey(experimentName);
	}

	public string GetExperimentSegment(string experimentName)
	{
		if (!IsActiveExperiment(experimentName))
		{
			return null;
		}
		if (hardServerOverrides.ContainsKey(experimentName))
		{
			return hardServerOverrides[experimentName];
		}
		string text = null;
		if (savedPlayerSegments.ContainsKey(experimentName))
		{
			text = savedPlayerSegments[experimentName];
		}
		if (text == null)
		{
			bool flag = false;
			if (softServerOverrides.ContainsKey(experimentName))
			{
				text = softServerOverrides[experimentName];
				flag = true;
			}
			else
			{
				List<string> list = activeTests[experimentName];
				int count = list.Count;
				int index = UnityEngine.Random.Range(0, count);
				text = list[index];
			}
			savedPlayerSegments.Add(experimentName, text);
			string value = ((!flag) ? text : ("SERVER_" + text));
			AmplitudeAnalyticsClient.Identify().WithUserProperty(experimentName, value).LogAsync();
			SaveExperimentSegments();
		}
		return text;
	}

	public void RegisterServerSettings(string softOverrideData, string hardOverrideData)
	{
		if (softOverrideData != null)
		{
			ParseAndAssign(softOverrideData, softServerOverrides);
		}
		if (hardOverrideData != null)
		{
			ParseAndAssign(hardOverrideData, hardServerOverrides);
		}
	}

	public bool LoadSavedExperimentSegments()
	{
		savedPlayerSegments.Clear();
		if (!RecroomPrefs.IsReady)
		{
			return false;
		}
		if (RecroomPrefs.HasKey("SplitTestAssignedSegments"))
		{
			string data = RecroomPrefs.GetString("SplitTestAssignedSegments", string.Empty);
			savedPlayerSegments = Deserialize(data);
		}
		List<string> list = new List<string>();
		foreach (string key in savedPlayerSegments.Keys)
		{
			if (!IsActiveExperiment(key))
			{
				list.Add(key);
			}
		}
		if (list.Count > 0)
		{
			for (int i = 0; i < list.Count; i++)
			{
				savedPlayerSegments.Remove(list[i]);
			}
			SaveExperimentSegments();
		}
		return true;
	}

	protected override void Awake()
	{
		base.Awake();
		RegisterExperiment(typeof(PaddleballSocialNUX_2018_01_11));
		RegisterExperiment(typeof(AlternateNUXFirstActivity_2018_06_12));
		RegisterExperiment(typeof(TokensAndDressUpNUX_2018_07_16));
		RegisterExperiment(typeof(ScreensNUX_2018_08_02));
	}

	private void RegisterExperiment(System.Type enumType)
	{
		if (!enumType.IsEnum)
		{
			UnityEngine.Debug.LogError("Tried to add experiment using that that wasn't an enum: " + enumType.ToString());
			return;
		}
		string experimentName = enumType.ToString();
		string[] names = System.Enum.GetNames(enumType);
		RegisterExperiment(experimentName, new List<string>(names));
	}

	private void RegisterExperiment(string experimentName, List<string> experimentSegments)
	{
		activeTests.Add(experimentName, experimentSegments);
	}

	private void SaveExperimentSegments()
	{
		string value = Serialize(savedPlayerSegments);
		RecroomPrefs.SetString("SplitTestAssignedSegments", value);
		RecroomPrefs.Save();
	}

	private bool IsActiveExperiment(string experimentName)
	{
		return activeTests.ContainsKey(experimentName);
	}

	private bool IsValidExperimentValue(string experimentName, string experimentAssignment)
	{
		if (!IsActiveExperiment(experimentName))
		{
			return false;
		}
		if (!activeTests[experimentName].Contains(experimentAssignment))
		{
			return false;
		}
		return true;
	}

	private void ParseAndAssign(string serverData, Dictionary<string, string> saveLocation)
	{
		char[] separator = new char[1] { ';' };
		string[] array = serverData.Split(separator, StringSplitOptions.RemoveEmptyEntries);
		if (array == null || array.Length == 0)
		{
			return;
		}
		int num = 0;
		char[] separator2 = new char[1] { '=' };
		for (int i = 0; i < array.Length; i++)
		{
			string text = array[i].Trim();
			string[] array2 = text.Split(separator2, StringSplitOptions.RemoveEmptyEntries);
			if (array2 == null || array2.Length != 2)
			{
				num++;
				continue;
			}
			string text2 = "SplitTesting+" + array2[0];
			string text3 = (saveLocation[text2] = array2[1]);
			UnityEngine.Debug.LogFormat("ST override: {0} = {1}", text2, text3);
		}
		if (num > 0)
		{
			UnityEngine.Debug.LogWarningFormat("ST override format errors ({1}): {0}", serverData, num);
		}
	}

	private bool FindMatchingExperimentAndSegment(string suppliedSegment, out string matchedExperiment, out string matchedSegment)
	{
		suppliedSegment = suppliedSegment.ToLower();
		foreach (string key in activeTests.Keys)
		{
			List<string> list = activeTests[key];
			foreach (string item in list)
			{
				if (item.ToLower() == suppliedSegment)
				{
					matchedExperiment = key;
					matchedSegment = item;
					return true;
				}
			}
		}
		matchedExperiment = null;
		matchedSegment = null;
		return false;
	}

	private static string Serialize(Dictionary<string, string> assignedSegments)
	{
		string arg = AmplitudeMiniJSON.Json.Serialize(assignedSegments);
		return $"{1}|{arg}";
	}

	private static Dictionary<string, string> Deserialize(string data)
	{
		if (string.IsNullOrEmpty(data))
		{
			return new Dictionary<string, string>();
		}
		int result = -1;
		string assignmentsAsString = null;
		int num = data.IndexOf('|');
		if (num >= 0)
		{
			assignmentsAsString = data.Substring(num + 1);
			string s = data.Substring(0, num);
			if (!int.TryParse(s, out result))
			{
				result = -1;
			}
		}
		if (result == 1)
		{
			return Deserialize_v1(assignmentsAsString);
		}
		UnityEngine.Debug.LogErrorFormat("Invalid saved data for SplitTesting. Clearing data. Version: {0}, Raw Data: {1}", result, data);
		return new Dictionary<string, string>();
	}

	private static Dictionary<string, string> Deserialize_v1(string assignmentsAsString)
	{
		Dictionary<string, string> dictionary = new Dictionary<string, string>();
		if (AmplitudeMiniJSON.Json.Deserialize(assignmentsAsString) is Dictionary<string, object> dictionary2)
		{
			dictionary = new Dictionary<string, string>();
			foreach (KeyValuePair<string, object> item in dictionary2)
			{
				dictionary.Add(item.Key, (string)item.Value);
			}
		}
		return dictionary;
	}
}
public static class StringCipher
{
	private const int Keysize = 256;

	private const int DerivationIterations = 1000;

	public static byte[] Encrypt(byte[] plainTextBytes, string passPhrase)
	{
		byte[] array = Generate256BitsOfRandomEntropy();
		byte[] array2 = Generate256BitsOfRandomEntropy();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(passPhrase, array, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateEncryptor(bytes, array2);
		using MemoryStream memoryStream = new MemoryStream();
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write);
		cryptoStream.Write(plainTextBytes, 0, plainTextBytes.Length);
		cryptoStream.FlushFinalBlock();
		byte[] first = array;
		first = first.Concat(array2).ToArray();
		first = first.Concat(memoryStream.ToArray()).ToArray();
		memoryStream.Close();
		cryptoStream.Close();
		return first;
	}

	public static byte[] Decrypt(byte[] cipherTextBytesWithSaltAndIv, string passPhrase)
	{
		byte[] salt = cipherTextBytesWithSaltAndIv.Take(32).ToArray();
		byte[] rgbIV = cipherTextBytesWithSaltAndIv.Skip(32).Take(32).ToArray();
		byte[] array = cipherTextBytesWithSaltAndIv.Skip(64).Take(cipherTextBytesWithSaltAndIv.Length - 64).ToArray();
		Rfc2898DeriveBytes rfc2898DeriveBytes = new Rfc2898DeriveBytes(passPhrase, salt, 1000);
		byte[] bytes = rfc2898DeriveBytes.GetBytes(32);
		using RijndaelManaged rijndaelManaged = new RijndaelManaged();
		rijndaelManaged.BlockSize = 256;
		rijndaelManaged.Mode = CipherMode.CBC;
		rijndaelManaged.Padding = PaddingMode.PKCS7;
		using ICryptoTransform transform = rijndaelManaged.CreateDecryptor(bytes, rgbIV);
		using MemoryStream memoryStream = new MemoryStream(array);
		using CryptoStream cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Read);
		byte[] array2 = new byte[array.Length];
		cryptoStream.Read(array2, 0, array2.Length);
		memoryStream.Close();
		cryptoStream.Close();
		return array2;
	}

	private static byte[] Generate256BitsOfRandomEntropy()
	{
		byte[] array = new byte[32];
		RNGCryptoServiceProvider rNGCryptoServiceProvider = new RNGCryptoServiceProvider();
		rNGCryptoServiceProvider.GetBytes(array);
		return array;
	}
}
public class CoCAreaToDetect : UnityEngine.MonoBehaviour
{
	public delegate void DrawingDetected(CoCAreaToDetect area);

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private DrawingDetected m_DrawingDetectedEvent;

	[SerializeField]
	private float minContactTime = 0.5f;

	private float contactStartTime = -1f;

	public bool IsDrawn { get; private set; }

	public event DrawingDetected DrawingDetectedEvent
	{
		add
		{
			DrawingDetected drawingDetected = this.m_DrawingDetectedEvent;
			DrawingDetected drawingDetected2;
			do
			{
				drawingDetected2 = drawingDetected;
				drawingDetected = Interlocked.CompareExchange(ref this.m_DrawingDetectedEvent, (DrawingDetected)Delegate.Combine(drawingDetected2, value), drawingDetected);
			}
			while (drawingDetected != drawingDetected2);
		}
		remove
		{
			DrawingDetected drawingDetected = this.m_DrawingDetectedEvent;
			DrawingDetected drawingDetected2;
			do
			{
				drawingDetected2 = drawingDetected;
				drawingDetected = Interlocked.CompareExchange(ref this.m_DrawingDetectedEvent, (DrawingDetected)Delegate.Remove(drawingDetected2, value), drawingDetected);
			}
			while (drawingDetected != drawingDetected2);
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		WhiteboardPen componentInParent = other.GetComponentInParent<WhiteboardPen>();
		if (componentInParent != null && other.transform == componentInParent.BrushTip && contactStartTime < 0f)
		{
			contactStartTime = UnityEngine.Time.time;
		}
	}

	private void OnTriggerExit(Collider other)
	{
		WhiteboardPen componentInParent = other.GetComponentInParent<WhiteboardPen>();
		if (componentInParent != null && other.transform == componentInParent.BrushTip && UnityEngine.Time.time - contactStartTime > minContactTime && !IsDrawn)
		{
			IsDrawn = true;
			if (this.DrawingDetectedEvent != null)
			{
				this.DrawingDetectedEvent(this);
			}
		}
	}
}
public class CodeOfConductForm : UnityEngine.MonoBehaviour
{
	public Action<bool> CoCFinishSigning;

	[SerializeField]
	private float outOfInteractionZoneDelay = 2f;

	private bool isInteracting;

	[Header("Areas to detect")]
	[SerializeField]
	private CoCAreaToDetect over13Area;

	[SerializeField]
	private CoCAreaToDetect under13Area;

	[SerializeField]
	private CoCAreaToDetect signatureArea;

	private bool? isUnder13;

	private bool isSigned;

	public bool IsCompleted { get; private set; }

	private void Awake()
	{
		over13Area.DrawingDetectedEvent += OnOver13Event;
		under13Area.DrawingDetectedEvent += OnUnder13Event;
		signatureArea.DrawingDetectedEvent += OnSignatureDetectedEvent;
	}

	private void OnSignatureDetectedEvent(CoCAreaToDetect area)
	{
		isSigned = true;
	}

	private void OnUnder13Event(CoCAreaToDetect area)
	{
		isUnder13 = true;
	}

	private void OnOver13Event(CoCAreaToDetect area)
	{
		if (!under13Area.IsDrawn)
		{
			isUnder13 = false;
		}
	}

	private void OnTriggerEnter(Collider other)
	{
		WhiteboardPen componentInParent = other.GetComponentInParent<WhiteboardPen>();
		if (componentInParent != null && other.transform == componentInParent.BrushTip)
		{
			isInteracting = true;
			CancelInvoke();
		}
	}

	private void OnTriggerExit(Collider other)
	{
		WhiteboardPen componentInParent = other.GetComponentInParent<WhiteboardPen>();
		if (componentInParent != null && other.transform == componentInParent.BrushTip)
		{
			isInteracting = false;
			Invoke("CheckIfCompleted", outOfInteractionZoneDelay);
		}
	}

	private void CheckIfCompleted()
	{
		if (isSigned && !isInteracting)
		{
			IsCompleted = true;
			if (CoCFinishSigning != null)
			{
				CoCFinishSigning(obj: false);
			}
		}
	}
}
