	public override string FriendlyName()
	{
		return "CreateCustomRoomPart2";
	}

	public override bool ShouldRun()
	{
		return true;
	}

	public override void SetupTeachingMoment()
	{
		base.SetupTeachingMoment();
		numMakerPenExtrusions = 0f;
		readyForSaveTutorial = false;
		readyForSaveNameTutorial = false;
		hasGrabbedMakerPen = false;
		hasDrawnSphere = false;
	}

	protected override void InternalCleanUp()
	{
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.Backpack.BackpackToolEnabledChange -= OnBackpackUsed;
			Player.LocalPlayer.Backpack.BackpackToolGrabbed -= OnBackpackToolGrabbed;
		}
		RemoveMakerPenCallbacks();
		if (sphereButton != null)
		{
			sphereButton.AttractHighlighted = false;
		}
		if (playerMakerPen != null)
		{
			playerMakerPen.MainScreen.OpenPaletteButton.AttractHighlighted = false;
			playerMakerPen.MainScreen.DoneEditingButton.AttractHighlighted = false;
		}
		SingletonMonoBehaviour<SessionManager>.Instance.OnSwitchRoomRequested -= OnPlayerTriesToLeave;
		if (homeScreen != null)
		{
			homeScreen.ClearHighlights();
		}
	}

	public override IEnumerator RunTeachingMoment()
	{
		while (!Player.LocalPlayerExists)
		{
			yield return null;
		}
		while (watchMenu == null)
		{
			watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			yield return null;
		}
		homeScreen = watchMenu.GetFlowByType<HomeScreenFlow>();
		thisRoomMenu = watchMenu.GetFlowByType<ThisRoomWatchUIFlow>();
		bool wasLoadSuccess = false;
		yield return NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.TeachableMomentLoadRoomData(binaryRoomData).Then((Action)delegate
		{
			wasLoadSuccess = true;
		});
		if (!wasLoadSuccess)
		{
			UnityEngine.Debug.LogWarning("Failed to load tutorial data for teachable moment");
			status = CompletionStatus.Error;
			yield break;
		}
		yield return new WaitForSeconds(1.5f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(welcomeToSpaceVO);
		yield return new WaitForSeconds(0.25f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(makerPenInfoVO);
		PlayerBackpack playerBackpack = Player.LocalPlayer.Backpack;
		if (!playerBackpack.IsInUse(PlayerBackpackToolType.MAKER_PEN))
		{
			if (playerBackpack.FavoriteToolType != PlayerBackpackToolType.MAKER_PEN)
			{
				playerBackpack.SetFavoriteTool(PlayerBackpackToolType.MAKER_PEN);
			}
			playerBackpack.BackpackToolEnabledChange += OnBackpackUsed;
			playerBackpack.BackpackToolGrabbed += OnBackpackToolGrabbed;
			yield return new WaitForSeconds(0.25f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(howToGetMakerPenVO);
			yield return CancelableCoroutine(RunInterruptableFlow(() => hasGrabbedMakerPen ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, null, howToGetMakerPenVO.AudioClip, null, 15f, -1, string.Empty));
		}
		playerMakerPen = playerBackpack.GetBackpackTool(PlayerBackpackToolType.MAKER_PEN).GetComponent<MakerPen>();
		AddMakerPenCallbacks();
		yield return new WaitForSeconds(0.5f);
		float previousThingsDrawn = numMakerPenExtrusions;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(drawSomethingVO);
		yield return new WaitForSeconds(0.25f);
		yield return CancelableCoroutine(RunInterruptableFlow(() => (numMakerPenExtrusions >= previousThingsDrawn + 1f) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, null, drawSomethingVO.AudioClip, null, 15f, -1, string.Empty));
		hasExitedShapeMode = false;
		playerMakerPen.MainScreen.DoneEditingButton.AttractHighlighted = true;
		yield return new WaitForSeconds(0.5f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(pressDoneEditingVO);
		yield return CancelableCoroutine(RunInterruptableFlow(() => hasExitedShapeMode ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, null, pressDoneEditingVO.AudioClip, null, 15f, -1, string.Empty));
		playerMakerPen.MainScreen.DoneEditingButton.AttractHighlighted = false;
		yield return new WaitForSeconds(0.25f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(greatVO);
		yield return new WaitForSeconds(0.25f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(justTheBeginningVO);
		yield return new WaitForSeconds(0.5f);
		if (!playerMakerPen.MoveablePaletteMenu.IsMenuVisible)
		{
			playerMakerPen.MainScreen.OpenPaletteButton.AttractHighlighted = true;
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(openPaletteVO);
			yield return CancelableCoroutine(RunInterruptableFlow(() => playerMakerPen.MoveablePaletteMenu.IsMenuVisible ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, null, openPaletteVO.AudioClip, null, 15f, -1, string.Empty));
			yield return new WaitForSeconds(0.25f);
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(excellentVO);
			playerMakerPen.MainScreen.OpenPaletteButton.AttractHighlighted = false;
		}
		yield return new WaitForSeconds(0.5f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(paletteToSelectVO);
		yield return new WaitForSeconds(0.25f);
		sphereButton = playerMakerPen.PaletteMainScreen.GetButtonForShape(ShapeType.Sphere);
		sphereButton.AttractHighlighted = true;
		hasDrawnSphere = false;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(drawASphereVO);
		yield return CancelableCoroutine(RunInterruptableFlow(() => hasDrawnSphere ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, null, drawASphereVO.AudioClip, null, 15f, -1, string.Empty));
		sphereButton.AttractHighlighted = false;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(greatVO);
		yield return new WaitForSeconds(0.25f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(experimentVO);
		tutorialVideosButton.SetActive(value: true);
		readyForSaveTutorial = false;
		SingletonMonoBehaviour<SessionManager>.Instance.OnSwitchRoomRequested += OnPlayerTriesToLeave;
		Stopwatch creationTimeStopwatch = Stopwatch.StartNew();
		while (!readyForSaveTutorial)
		{
			if (creationTimeStopwatch.Elapsed.TotalMinutes >= 2.5 || (watchMenu.FullyVisible && thisRoomMenu.IsCurrentFlow))
			{
				readyForSaveTutorial = true;
			}
			yield return null;
		}
		SingletonMonoBehaviour<SessionManager>.Instance.OnSwitchRoomRequested -= OnPlayerTriesToLeave;
		status = CompletionStatus.Finished;
		yield return new WaitForSeconds(0.5f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(saveRoomIntroVO);
		if (!watchMenu.FullyVisible)
		{
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVOClip(SingletonMonoBehaviour<TutorialManager>.Instance.GetTutorialAudio(TutorialManager.TutorialAudioType.OpenWatch));
		}
		if (!thisRoomMenu.IsCurrentFlow)
		{
			yield return new WaitForSeconds(0.5f);
			watchMenu.PopAllFlows();
			Button3DBase thisRoomButton = homeScreen.GetButtonForFlow<ThisRoomWatchUIFlow>();
			thisRoomButton.AttractHighlighted = true;
			yield return CancelableCoroutine(RunWaitUntilPlayerOpensMenuPageNoTimeout(thisRoomMenu, tapThisRoomVO.AudioClip, null));
			thisRoomButton.AttractHighlighted = false;
		}
		yield return new WaitForSeconds(0.5f);
		Button3D saveButton = thisRoomMenu.RoomDetails.SaveButton;
		saveButton.AttractHighlighted = true;
		saveButton.UpEvent += delegate
		{
			readyForSaveNameTutorial = true;
		};
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(tapSaveVO);
		saveButton.AttractHighlighted = false;
		while (!readyForSaveNameTutorial)
		{
			yield return null;
		}
		yield return new WaitForSeconds(2f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(youveLearnedItAllVO);
	}

	private void OnBackpackUsed(Tool tool, PlayerBackpackToolType toolType, bool inUse)
	{
		if (toolType == PlayerBackpackToolType.MAKER_PEN && inUse)
		{
			hasGrabbedMakerPen = true;
		}
	}

	private void OnBackpackToolGrabbed(PlayerBackpackToolType toolType)
	{
		if (toolType == PlayerBackpackToolType.MAKER_PEN)
		{
			hasGrabbedMakerPen = true;
		}
	}

	private void OnMakerPenUsed(MakerPen.ToolMode tool)
	{
		if (tool == MakerPen.ToolMode.CreateShape || tool == MakerPen.ToolMode.CreateObject)
		{
			numMakerPenExtrusions += 1f;
		}
		else
		{
			numMakerPenExtrusions += 0.2f;
		}
		if (tool == MakerPen.ToolMode.CreateShape)
		{
			MakerPen component = Player.LocalPlayer.Backpack.GetBackpackTool(PlayerBackpackToolType.MAKER_PEN).GetComponent<MakerPen>();
			if (component != null && component.CurrentShapeType == ShapeType.Sphere)
			{
				hasDrawnSphere = true;
			}
		}
	}

	private void OnMakerPenModeChanged(MakerPen.ToolMode newTool, MakerPen.TargetMode newMode)
	{
		if (newMode == MakerPen.TargetMode.Object)
		{
			hasExitedShapeMode = true;
		}
	}

	private void OnPlayerTriesToLeave(SessionManager.CancelSwitchRoomsRequest cancelRequest)
	{
		cancelRequest.RequestTransitionCancel();
		readyForSaveTutorial = true;
	}

	private bool AddMakerPenCallbacks()
	{
		if (playerMakerPen == null)
		{
			return false;
		}
		numMakerPenExtrusions = 0f;
		MakerPen makerPen = playerMakerPen;
		makerPen.OnToolUsed = (Action<MakerPen.ToolMode>)Delegate.Combine(makerPen.OnToolUsed, new Action<MakerPen.ToolMode>(OnMakerPenUsed));
		MakerPen makerPen2 = playerMakerPen;
		makerPen2.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Combine(makerPen2.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
		return true;
	}

	private void RemoveMakerPenCallbacks()
	{
		if (!(playerMakerPen == null))
		{
			numMakerPenExtrusions = 0f;
			MakerPen makerPen = playerMakerPen;
			makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Remove(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			MakerPen makerPen2 = playerMakerPen;
			makerPen2.OnToolUsed = (Action<MakerPen.ToolMode>)Delegate.Remove(makerPen2.OnToolUsed, new Action<MakerPen.ToolMode>(OnMakerPenUsed));
		}
	}

