			if (localPlayerHasCreatedRooms != true && localPlayerHasCreatedRooms.HasValue && SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR && !SingletonMonoBehaviour<TutorialManager>.Instance.HasUserTried(TutorialManager.UserTracking.Tutorial_CreateCustomRoom) && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Complete && SingletonMonoBehaviour<SettingsManager>.Instance.TotalSessionCount >= 5)
			{
				return true;
			}
		}
		return false;
	}

	public override void SetupTeachingMoment()
	{
		base.SetupTeachingMoment();
		watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		homeScreen = watchMenu.GetFlowByType<HomeScreenFlow>();
		createRoomMenu = watchMenu.GetFlowByType<CreateRoomScreen>();
	}

	protected override void InternalCleanUp()
	{
		if (Player.LocalPlayerExists)
		{
			watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = null;
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			SingletonMonoBehaviour<TutorialManager>.Instance.HideHelpPopup();
			Player.LocalPlayer.PlayerUI.WatchAttractor.StopNotificationEffect();
			homeScreen.ClearHighlights();
		}
	}

	public override IEnumerator RunTeachingMoment()
	{
		if (!SkipAskPrompt)
		{
			yield return new WaitForSeconds(2f);
			watchMenu.PopAllFlows();
			Player.LocalPlayer.PlayerLocomotion.AddMovementRestriction(this);
			ConfirmDialogResponses response = ConfirmDialogResponses.Cancel;
			bool hasResponse = false;
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO_NOTNOW, "Learn to create your own room?", "Do you want to spend a few minutes learning how to make your own custom room?").Then(delegate(ConfirmDialogResponses r)
			{
				response = r;
				hasResponse = true;
			});
			if (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
			{
				Player.LocalPlayer.PlayerUI.WatchMenuProjector.AuthorityOpenMenuDetached();
			}
			yield return CancelableCoroutine(RunWaitUntilPlayerPerformsWatchActionNoTimeout(() => hasResponse ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, learnToMakeCustomRoomVO.AudioClip, null));
			if (response == ConfirmDialogResponses.Negative)
			{
				SingletonMonoBehaviour<TutorialManager>.Instance.MarkUserTried(TutorialManager.UserTracking.Tutorial_CreateCustomRoom);
				status = CompletionStatus.OptedOut;
				yield break;
			}
			if (response == ConfirmDialogResponses.Cancel)
			{
				status = CompletionStatus.RemindLater;
				yield break;
			}
		}
		else
		{
			watchMenu.PopAllFlows();
		}
		Button3DBase customRoomsButton = homeScreen.GetButtonForFlow<CreateRoomScreen>();
		homeScreen.HighlightButton<CreateRoomScreen>();
		watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = customRoomsButton;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(greatLetsGetStartedVO);
		if (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
		{
			HelpPopup popup = SingletonMonoBehaviour<TutorialManager>.Instance.ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
			Player.LocalPlayer.PlayerUI.WatchAttractor.PlayNotificationEffect(isMessageNotification: false);
			yield return CancelableCoroutine(RunWaitUntilPlayerOpensMenuNoTimeout(null));
			Player.LocalPlayer.PlayerUI.WatchAttractor.StopNotificationEffect();
			popup.Active = false;
		}
		yield return CancelableCoroutine(RunWaitUntilPlayerOpensMenuPageNoTimeout(createRoomMenu, tapCreateRoomVO.AudioClip, null));
		homeScreen.ClearHighlights();
		createRoomMenu.ShowBaseRoomsSubscreen();
		while (!createRoomMenu.BaseRoomsButtonsPopulated)
		{
			yield return null;
		}
		string tutorialRoomName = "PerformanceHall";
		int pageIndex = createRoomMenu.FindPageIndexOfBaseRoom(tutorialRoomName);
		createRoomMenu.SetBaseRoomsCurrentPage(Mathf.Max(0, pageIndex));
		Button3D performanceHallButton = null;
		BaseRoomButton[] roomButtons = createRoomMenu.GetComponentsInChildren<BaseRoomButton>();
		for (int num = 0; num < roomButtons.Length; num++)
		{
			if (roomButtons[num].CurrentRoom.Name == tutorialRoomName)
			{
				performanceHallButton = roomButtons[num].gameObject.GetComponentInChildren<Button3D>();
				break;
			}
		}
		if (performanceHallButton == null)
		{
			UnityEngine.Debug.LogWarning("Did not find expected performance hall button in teachable moment");
			yield break;
		}
		performanceHallButton.AttractHighlighted = true;
		watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = performanceHallButton;
		status = CompletionStatus.Finished;
		bool performanceHallButtonClicked = false;
		UnityAction onPerformanceHallButtonClick = delegate
		{
			performanceHallButtonClicked = true;
			SingletonMonoBehaviour<TutorialManager>.Instance.MarkUserTried(TutorialManager.UserTracking.Tutorial_CreateCustomRoom);
			watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = null;
		};
		performanceHallButton.OnClick.AddListener(onPerformanceHallButtonClick);
		bool cloneDialogOpen = false;
		Action onCloneDialogOpen = delegate
		{
			cloneDialogOpen = true;
		};
		CreateRoomScreen createRoomScreen = createRoomMenu;
		createRoomScreen.CloneDialogOpened = (Action)Delegate.Combine(createRoomScreen.CloneDialogOpened, onCloneDialogOpen);
		Action<bool> onCloneDialogClose = delegate
		{
			cloneDialogOpen = false;
		};
		CreateRoomScreen createRoomScreen2 = createRoomMenu;
		createRoomScreen2.CloneDialogClosed = (Action<bool>)Delegate.Combine(createRoomScreen2.CloneDialogClosed, onCloneDialogClose);
		Player.LocalPlayerSpawnEvent += new Action(OnPlayerRespawn);
		yield return RunInterruptableFlow(() => performanceHallButtonClicked ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, selectALocationVO.AudioClip, selectALocationVO.AudioClip, delegate
		{
		}, 15f, -1, "ClickPerformanceHall");
		while (!cloneDialogOpen)
		{
			yield return null;
		}
		yield return RunInterruptableFlow(() => (!cloneDialogOpen) ? InterruptableFlow.FlowState.Complete : InterruptableFlow.FlowState.Incomplete, chooseARoomNameVO.AudioClip, chooseARoomNameVO.AudioClip, delegate
		{
		}, 15f, -1, "ChooseRoomName");
		performanceHallButton.OnClick.RemoveListener(onPerformanceHallButtonClick);
		CreateRoomScreen createRoomScreen3 = createRoomMenu;
		createRoomScreen3.CloneDialogOpened = (Action)Delegate.Remove(createRoomScreen3.CloneDialogOpened, onCloneDialogOpen);
		CreateRoomScreen createRoomScreen4 = createRoomMenu;
		createRoomScreen4.CloneDialogClosed = (Action<bool>)Delegate.Remove(createRoomScreen4.CloneDialogClosed, onCloneDialogClose);
	}

	private static void OnPlayerRespawn()
	{
		Player.LocalPlayerSpawnEvent -= new Action(OnPlayerRespawn);
		if (GameSessions.LocalGameSession.Location != RoomSceneLocations.PERFORMANCE_HALL)
		{
			UnityEngine.Debug.LogWarningFormat("Expected player to be in room with base room performance hall. Instead ended up in: {0}. Canceling TM.", GameSessions.LocalGameSession.Location);
		}
		else
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.TryTeachableMoment<CreateCustomRoomPart2TeachableMoment>();
		}
	}
}
public class CustomRoomsBrowsingTeachableMoment : TeachableMoment
{
	private const int SESSION_COUNT_REQUIRED = 3;

	[Header("VO")]
	[SerializeField]
	private TutorialManager.VOClip welcomeBackVO;

	[SerializeField]
	private TutorialManager.VOClip customRoomsTeaserVO;

	[SerializeField]
	private TutorialManager.VOClip checkThemOutVO;

	[SerializeField]
	private TutorialManager.VOClip tapCustomRoomsVO;

	[SerializeField]
	private TutorialManager.VOClip chooseAnInterestingRoomVO;

	[NonSerialized]
	public bool SkipDescriptionVO;

	[NonSerialized]
	public bool SkipToRoomBrowserVOandHighlight;

	private WatchUI watchMenu;

	private HomeScreenFlow homeScreen;

	private RoomButton featuredRoomButton;

	private int teleportCount;

	private const int NUM_TELEPORTS_TO_CANCEL_TM = 2;

	public override string FriendlyName()
	{
		return "CustomRoomBrowsing";
	}

	[SkipRename]
	public void Button_ForceTMToRun()
	{
		SingletonMonoBehaviour<TutorialManager>.Instance.ForceTeachableMomentToPlay(this);
	}

	public override bool ShouldRun()
	{
		if (Player.LocalPlayerExists && !Profiles.LocalProfile.IsJunior())
		{
			bool? localPlayerHasCreatedRooms = RecNet.Rooms.LocalPlayerHasCreatedRooms;
			if (localPlayerHasCreatedRooms != true && localPlayerHasCreatedRooms.HasValue && !SingletonMonoBehaviour<TutorialManager>.Instance.HasUserTried(TutorialManager.UserTracking.HasVisitedCustomRoom) && !SingletonMonoBehaviour<TutorialManager>.Instance.HasUserTried(TutorialManager.UserTracking.Tutorial_CustomRoomBrowser) && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState == TutorialManager.NUXFlowState.Complete && SingletonMonoBehaviour<SettingsManager>.Instance.TotalSessionCount >= 3)
			{
				return true;
			}
		}
		return false;
	}

	public override void SetupTeachingMoment()
	{
		base.SetupTeachingMoment();
		watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		homeScreen = watchMenu.GetFlowByType<HomeScreenFlow>();
		teleportCount = 0;
	}

	protected override void InternalCleanUp()
	{
		if (Player.LocalPlayerExists)
		{
			watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = null;
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
			Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= OnTeleportInsteadOfTutorial;
			SingletonMonoBehaviour<TutorialManager>.Instance.HideHelpPopup();
			Player.LocalPlayer.PlayerUI.WatchAttractor.StopNotificationEffect();
			homeScreen.ClearHighlights();
			if (featuredRoomButton != null)
			{
				featuredRoomButton.GoToButton.AttractHighlighted = true;
				featuredRoomButton = null;
			}
		}
	}

	private void OnTeleportInsteadOfTutorial(Player p, Vector3 source, Vector3 dest)
	{
		teleportCount++;
		if (teleportCount >= 2)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.CancelTeachableMomentIfActive(this);
			Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= OnTeleportInsteadOfTutorial;
		}
	}

	public override IEnumerator RunTeachingMoment()
	{
		BrowseRoomsScreen customRoomsMenu = watchMenu.GetFlowByType<BrowseRoomsScreen>();
		customRoomsMenu.Button_HotDisplayMode();
		if (!SkipToRoomBrowserVOandHighlight)
		{
			watchMenu.PopAllFlows();
			if (!SkipDescriptionVO)
			{
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(welcomeBackVO);
				yield return new WaitForSeconds(0.25f);
				yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(customRoomsTeaserVO);
				yield return new WaitForSeconds(0.25f);
			}
			yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(checkThemOutVO);
			SingletonMonoBehaviour<TutorialManager>.Instance.MarkUserTried(TutorialManager.UserTracking.Tutorial_CustomRoomBrowser);
			Player.LocalPlayer.PlayerLocomotion.TeleportEvent += OnTeleportInsteadOfTutorial;
			if (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
			{
				HelpPopup popup = SingletonMonoBehaviour<TutorialManager>.Instance.ShowHelpPopup(TutorialManager.HelpType.OpenWatch);
				Player.LocalPlayer.PlayerUI.WatchAttractor.PlayNotificationEffect(isMessageNotification: false);
				yield return CancelableCoroutine(RunWaitUntilPlayerOpensMenuNoTimeout(null));
				Player.LocalPlayer.PlayerUI.WatchAttractor.StopNotificationEffect();
				popup.Active = false;
			}
			Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= OnTeleportInsteadOfTutorial;
			watchMenu.PopAllFlows();
			homeScreen.HighlightButton<BrowseRoomsScreen>();
			yield return CancelableCoroutine(RunWaitUntilPlayerOpensMenuPageNoTimeout(customRoomsMenu, tapCustomRoomsVO.AudioClip, null));
			homeScreen.ClearHighlights();
		}
		else
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.MarkUserTried(TutorialManager.UserTracking.Tutorial_CustomRoomBrowser);
		}
		RoomButtonPagedGrid browseGrid = watchMenu.GetComponentInChildren<RoomButtonPagedGrid>();
		while (featuredRoomButton == null)
		{
			featuredRoomButton = browseGrid.GetFirstEnabledButton();
			yield return null;
		}
		featuredRoomButton.GoToButton.AttractHighlighted = true;
		status = CompletionStatus.Finished;
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(chooseAnInterestingRoomVO);
	}
}
public class HelpPopup : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RawImage contentImage;

	[SerializeField]
	private Animator animator;

	private Coroutine updatePositionCoroutine;

	private Vector3? positionOverride;

	private Vector3 currentQuadrant = Vector3.zero;

	private bool forceUpdatePosition;

	private bool preferRight = true;

	private bool active;

	public bool Active
	{
		get
		{
			return active;
		}
		set
		{
			active = value;
			base.gameObject.SetActive(value);
			Visible = value;
		}
	}

	public bool PreferRightHandPlacement
	{
		get
		{
			return preferRight;
		}
		set
		{
			preferRight = value;
		}
	}

	private bool Visible
	{
		set
		{
			if (animator.gameObject.activeSelf)
			{
				animator.SetBool("Visible", value);
			}
		}
	}

	private void Awake()
	{
		Player.LocalPlayer.PlayerLocomotion.TeleportEvent += OnPlayerTeleported;
	}

	private void Update()
	{
		if (Active)
		{
			UpdatePosition();
		}
	}

	private void OnDestroy()
	{
		if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerLocomotion != null)
		{
			Player.LocalPlayer.PlayerLocomotion.TeleportEvent -= OnPlayerTeleported;
		}
	}

	private void OnPlayerTeleported(Player player, Vector3 sourceLocation, Vector3 destinationLocation)
	{
		forceUpdatePosition = true;
	}

	public void UpdatePosition(Vector3? positionOverride = null)
	{
		this.positionOverride = positionOverride;
		forceUpdatePosition = true;
	}

	private void UpdatePosition()
	{
		if (!Player.LocalPlayerExists)
		{
			return;
		}
		float num = Player.LocalPlayer.CurrentFloorHeightFromHead * 0.75f;
		Vector3 position = base.transform.position;
		if (positionOverride.HasValue)
		{
			position = positionOverride.Value;
		}
		else
		{
			Vector3 currentFloorPosition = Player.LocalPlayer.CurrentFloorPosition;
			Vector3 rhs = ZeroedY(Player.LocalPlayer.Body.transform.forward);
			Vector3 zero = Vector3.zero;
			Vector3 zero2 = Vector3.zero;
			float num2 = Vector3.Dot(Vector3.forward, rhs);
			float num3 = Vector3.Dot(Vector3.right, rhs);
			zero = ((num2 > 0.5f) ? Vector3.forward : ((num2 < -0.5f) ? Vector3.back : ((!(num3 >= 0.5f)) ? Vector3.left : Vector3.right)));
			if (zero != currentQuadrant || forceUpdatePosition)
			{
				zero2 = Vector3.Cross(SingletonMonoBehaviour<CameraRig>.Instance.transform.up, zero);
				Vector3 vector = currentFloorPosition + (zero + zero2 * 0.45f) + Vector3.up * num;
				Vector3 vector2 = currentFloorPosition + (zero - zero2 * 0.45f) + Vector3.up * num;
				Vector3 vector3 = vector;
				Vector3 vector4 = vector2;
				if (!PreferRightHandPlacement)
				{
					vector3 = vector2;
					vector4 = vector;
				}
				Vector3 vector5 = vector3 - Player.LocalPlayer.Head.transform.position;
				position = ((!Physics.Raycast(Player.LocalPlayer.Head.transform.position, vector5.normalized, vector5.magnitude, 3073)) ? vector3 : vector4);
				currentQuadrant = zero;
				forceUpdatePosition = false;
			}
		}
		position.y = num;
		base.transform.position = position;
	}

	private Vector3 ZeroedY(Vector3 vector)
	{
		vector.y = 0f;
		return vector;
	}

	public void SetContent(Texture2D content)
	{
		contentImage.texture = content;
	}
}
