public class NUXGoblin : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RecRoomAudioClip[] attractNoises;

	private bool loopNoise;

	public GestureTarget StopTarget { get; private set; }

	private void Awake()
	{
		StopTarget = GetComponent<GestureTarget>();
	}

	public void StartGoblinNoise()
	{
		if (!loopNoise)
		{
			loopNoise = true;
			StartCoroutine(PlayGoblinNoise());
		}
	}

	private IEnumerator PlayGoblinNoise()
	{
		while (loopNoise)
		{
			SFXAudioSource source = AudioManager.Play3DSFX(attractNoises[UnityEngine.Random.Range(0, attractNoises.Length)], base.transform);
			UnityEngine.Debug.Log("start playing");
			while (source.AudioSource.isPlaying)
			{
				yield return null;
			}
			UnityEngine.Debug.Log("end playing");
			yield return new WaitForSeconds(UnityEngine.Random.Range(2, 6));
		}
	}

	public void StopGoblinNoise()
	{
		loopNoise = false;
	}
}
[DisallowMultipleComponent]
public class NUXTeleportRestriction : TeleportRestriction
{
	private enum NUXRegion
	{
		NonNUX,
		DoorToRug,
		EntireRug
	}

	[SerializeField]
	private NUXRegion regionType;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private TeleportationPortal portal;

	private Collider thisCollider;

	protected override void Awake()
	{
		base.Awake();
		thisCollider = GetComponent<Collider>();
		SingletonMonoBehaviour<TutorialManager>.Instance.OnNUXStateChangeEvent += OnNUXStateChange;
		OnNUXStateChange(SingletonMonoBehaviour<TutorialManager>.Instance.NUXState);
	}

	private void OnNUXStateChange(TutorialManager.NUXFlowState state)
	{
		switch (state)
		{
		case TutorialManager.NUXFlowState.Teleport:
			base.MovementBlocked = regionType == NUXRegion.DoorToRug;
			break;
		case TutorialManager.NUXFlowState.ChooseHairSkin:
		case TutorialManager.NUXFlowState.ChooseShirt1:
		case TutorialManager.NUXFlowState.ChooseShirt2:
		case TutorialManager.NUXFlowState.OpenMenu:
		case TutorialManager.NUXFlowState.HomeScreen:
			base.MovementBlocked = regionType == NUXRegion.EntireRug;
			break;
		case TutorialManager.NUXFlowState.SCREENS_Walk:
		case TutorialManager.NUXFlowState.VR_Walk:
			base.MovementBlocked = false;
			break;
		default:
			base.MovementBlocked = false;
			break;
		}
		if (portal != null)
		{
			portal.IsLocked = base.MovementBlocked;
		}
		if (thisCollider != null && regionType == NUXRegion.NonNUX)
		{
			thisCollider.enabled = true;
		}
	}

	private void OnDestroy()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.OnNUXStateChangeEvent -= OnNUXStateChange;
		}
	}
}
public abstract class TeachableMoment : OOBEFlowBase
{
	public enum CompletionStatus
	{
		NotSet,
		Finished,
		Canceled,
		OptedOut,
		RemindLater,
		Error
	}

	protected CompletionStatus status;

	protected bool cancelOnLocalPlayerDestroyed = true;

	protected bool cancelOnGameStart = true;

	public CompletionStatus Status => status;

	public bool ShouldCancelOnLocalPlayerDestroyed => cancelOnLocalPlayerDestroyed;

	public bool ShouldCancelOnGameStart => cancelOnGameStart;

	public abstract bool ShouldRun();

	public virtual void SetupTeachingMoment()
	{
		status = CompletionStatus.NotSet;
	}

	public abstract IEnumerator RunTeachingMoment();

	public abstract string FriendlyName();

	public static string CompletionStatusToString(CompletionStatus status)
	{
		return status switch
		{
			CompletionStatus.NotSet => "NotSet", 
			CompletionStatus.Finished => "Finished", 
			CompletionStatus.Canceled => "Canceled", 
			CompletionStatus.OptedOut => "OptedOut", 
			CompletionStatus.RemindLater => "RemindLater", 
			_ => "UnknownValue", 
		};
	}

	protected virtual void Awake()
	{
		if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.RegisterTeachableMoment(this);
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (SingletonMonoBehaviour<TutorialManager>.Instance != null)
		{
			SingletonMonoBehaviour<TutorialManager>.Instance.CancelTeachableMomentIfActive(this);
			SingletonMonoBehaviour<TutorialManager>.Instance.UnregisterTeachableMoment(this);
		}
	}
}
[ExecuteInEditMode]
public class TeleportTarget : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private PulsingBeam beam;

	[SerializeField]
	private float targetRadius = 2.5f;

	public Action<bool> PlayerTeleportedEvent;

	public Action PlayerWalkedToTargetEvent;

	public bool AllowWalk { get; set; }

	private void Awake()
	{
		SetScale();
	}

	private void SetScale()
	{
		base.transform.localScale = new Vector3(targetRadius * 2f, 1f, targetRadius * 2f);
	}

	public void OnPlayerTeleported(Player player, Vector3 sourceLocation, Vector3 destinationLocation)
	{
		bool obj = Vector3.Distance(destinationLocation, base.transform.position) <= targetRadius;
		if (PlayerTeleportedEvent != null)
		{
			PlayerTeleportedEvent(obj);
		}
	}

	public IEnumerator RunCheckForPlayerWalkToTarget(Player player)
	{
		if (!AllowWalk || !(player != null))
		{
			yield break;
		}
		bool playerWalkedInside = false;
		while (!playerWalkedInside)
		{
			playerWalkedInside = Vector3.Distance(player.CurrentFloorPosition, base.transform.position) <= targetRadius;
			if (!playerWalkedInside)
			{
				yield return new WaitForSeconds(0.1f);
			}
		}
		if (PlayerWalkedToTargetEvent != null)
		{
			PlayerWalkedToTargetEvent();
		}
	}

	private void OnDrawGizmos()
	{
		Color color = Gizmos.color;
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.position, targetRadius);
		Gizmos.color = color;
	}
}
