	public bool HasCompletedTutorial
	{
		get
		{
			bool? hasCompletedTutorial = _hasCompletedTutorial;
			if (!hasCompletedTutorial.HasValue)
			{
				if (!RecroomPrefs.IsReady)
				{
					return false;
				}
				NUXFlowState defaultValue = NUXFlowState.NotRan;
				if (RecroomPrefs.GetInt("Recroom.OOBE", (int)defaultValue) == 100)
				{
					_hasCompletedTutorial = true;
					localState = NUXFlowState.Complete;
				}
				else
				{
					_hasCompletedTutorial = false;
				}
			}
			bool? hasCompletedTutorial2 = _hasCompletedTutorial;
			return hasCompletedTutorial2.Value;
		}
		set
		{
			_hasCompletedTutorial = value;
		}
	}

	public NUXFlowState NUXState
	{
		get
		{
			if (HasCompletedTutorial)
			{
				return localState;
			}
			NUXFlowState nUXFlowState = NUXFlowState.NotRan;
			if (!RecroomPrefs.IsReady)
			{
				return nUXFlowState;
			}
			return (NUXFlowState)RecroomPrefs.GetInt("Recroom.OOBE", (int)nUXFlowState);
		}
		set
		{
			if (!HasCompletedTutorial)
			{
				RecroomPrefs.SetInt("Recroom.OOBE", (int)value);
				RecroomPrefs.Save();
				if (value == NUXFlowState.Complete)
				{
					HasCompletedTutorial = true;
				}
			}
			else
			{
				localState = value;
			}
			if (this.OnNUXStateChangeEvent != null)
			{
				this.OnNUXStateChangeEvent(value);
			}
		}
	}

	public bool SuppressActivityNameNotification => !HasCompletedTutorial && (SessionManager.InRecCenter || SessionManager.InDormRoom);

	public bool CanRemoveOutfit => GameSessions.LocalGameSession.Location == RoomSceneLocations.DORM_ROOM && NUXState == NUXFlowState.Complete;

	public bool ScreensModeNUXEnabled
	{
		get
		{
			if (Player.LocalPlayerExists && !SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				return false;
			}
			if (!screensNUXSplitTestEnabled.HasValue)
			{
				string experimentName = typeof(SplitTesting.ScreensNUX_2018_08_02).ToString();
				string text = SplitTesting.ScreensNUX_2018_08_02.EnableScreensNUX.ToString();
				SingletonMonoBehaviour<SplitTesting>.Instance.ForceExperimentSegmentIfUnassigned(experimentName, text);
				screensNUXSplitTestEnabled = SingletonMonoBehaviour<SplitTesting>.Instance.GetExperimentSegment(experimentName) == text;
			}
			return screensNUXSplitTestEnabled.Value;
		}
	}

	public bool IsTeachableMomentPlaying => activeMoment != null;

	public event NUXStateChange OnNUXStateChangeEvent
	{
		add
		{
			NUXStateChange nUXStateChange = this.m_OnNUXStateChangeEvent;
			NUXStateChange nUXStateChange2;
			do
			{
				nUXStateChange2 = nUXStateChange;
				nUXStateChange = Interlocked.CompareExchange(ref this.m_OnNUXStateChangeEvent, (NUXStateChange)Delegate.Combine(nUXStateChange2, value), nUXStateChange);
			}
			while (nUXStateChange != nUXStateChange2);
		}
		remove
		{
			NUXStateChange nUXStateChange = this.m_OnNUXStateChangeEvent;
			NUXStateChange nUXStateChange2;
			do
			{
				nUXStateChange2 = nUXStateChange;
				nUXStateChange = Interlocked.CompareExchange(ref this.m_OnNUXStateChangeEvent, (NUXStateChange)Delegate.Remove(nUXStateChange2, value), nUXStateChange);
			}
			while (nUXStateChange != nUXStateChange2);
		}
	}

	public void Initialize()
	{
		if (PickedUpStickyToolNumberOfTimes < 5)
		{
			Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
		}
		if (SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += OnLocalPlayerSpawned;
		}
		else
		{
			UnityEngine.Debug.LogError("SessionManager is null");
		}
		LocationToFirstTimeMapping = new List<KeyValuePair<RoomSceneLocations, NewUser_FirstTimeIn>>();
		LocationToFirstTimeMapping.Add(new KeyValuePair<RoomSceneLocations, NewUser_FirstTimeIn>(RoomSceneLocations.REC_CENTER, NewUser_FirstTimeIn.RecCenter));
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (SingletonMonoBehaviour<SessionManager>.Instance != null)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= OnLocalPlayerSpawned;
		}
	}

	public void SetFirstTimeInForNewUser()
	{
		foreach (NewUser_FirstTimeIn value in System.Enum.GetValues(typeof(NewUser_FirstTimeIn)))
		{
			if (value != NewUser_FirstTimeIn.INVALID)
			{
				SetIsFirstTimeIn(value, firstTime: true);
			}
		}
		Player.PlayerCreatedEvent += new Action<Player>(OnRecRoomPlayerCreated);
		SetIsFirstTimeIn(NewUser_FirstTimeIn.PunchCardRewardTutorial, firstTime: false);
	}

	public bool GetIsFirstTimeInActivity(RoomSceneLocations location)
	{
		NewUser_FirstTimeIn firstTimeInFlagForActivity = GetFirstTimeInFlagForActivity(location);
		if (firstTimeInFlagForActivity == NewUser_FirstTimeIn.INVALID)
		{
			return false;
		}
		return GetIsFirstTimeIn(firstTimeInFlagForActivity);
	}

	private NewUser_FirstTimeIn GetFirstTimeInFlagForActivity(RoomSceneLocations location)
	{
		NewUser_FirstTimeIn result = NewUser_FirstTimeIn.INVALID;
		for (int i = 0; i < LocationToFirstTimeMapping.Count; i++)
		{
			if (LocationToFirstTimeMapping[i].Key == location)
			{
				result = LocationToFirstTimeMapping[i].Value;
				break;
			}
		}
		return result;
	}

	public bool GetIsFirstTimeIn(NewUser_FirstTimeIn action)
	{
		return ((uint)RecroomPrefs.GetInt("FIRST_TIME_IN_FLAGS", 0) & (uint)action) != 0;
	}

	public void SetIsFirstTimeInActivity(RoomSceneLocations activity, bool firstTime)
	{
		NewUser_FirstTimeIn firstTimeInFlagForActivity = GetFirstTimeInFlagForActivity(activity);
		if (firstTimeInFlagForActivity != NewUser_FirstTimeIn.INVALID)
		{
			SetIsFirstTimeIn(firstTimeInFlagForActivity, firstTime);
		}
	}

	public void SetIsFirstTimeIn(NewUser_FirstTimeIn action, bool firstTime)
	{
		int num = RecroomPrefs.GetInt("FIRST_TIME_IN_FLAGS", 0);
		num = ((!firstTime) ? (num & (int)(~action)) : (num | (int)action));
		RecroomPrefs.SetInt("FIRST_TIME_IN_FLAGS", num);
		RecroomPrefs.Save();
	}

	public bool HasUserTried(UserTracking action)
	{
		return ((uint)RecroomPrefs.GetInt("USER_TRACKING", 0) & (uint)action) != 0;
	}

	public void MarkUserTried(UserTracking action, bool didTry = true)
	{
		int num = RecroomPrefs.GetInt("USER_TRACKING", 0);
		num = ((!didTry) ? (num & (int)(~action)) : (num | (int)action));
		RecroomPrefs.SetInt("USER_TRACKING", num);
		RecroomPrefs.Save();
	}

	private void OnLocalPlayerSpawned()
	{
		RoomSceneLocations location = GameSessions.LocalGameSession.Location;
		if (location != RoomSceneLocations.INVALID)
		{
			SetIsFirstTimeInActivity(location, firstTime: false);
		}
	}

	private void OnRecRoomPlayerCreated(Player player)
	{
		if (player != null && player.isLocal && PickedUpStickyToolNumberOfTimes < 5)
		{
			Tool.StaticLockedToolPickedUpEvent += Tool_OnLockedToolPickedUp;
		}
	}

	private void Tool_OnLockedToolPickedUp(Tool tool)
	{
		GameManager gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (tool.HolderPlayer.isLocal && (gameManager == null || !gameManager.IsGameRunning))
		{
			PickedUpStickyToolNumberOfTimes++;
			if (PickedUpStickyToolNumberOfTimes >= 5)
			{
				Tool.StaticLockedToolPickedUpEvent -= Tool_OnLockedToolPickedUp;
				Player.PlayerCreatedEvent -= new Action<Player>(OnRecRoomPlayerCreated);
			}
			tool.PostReleaseEvent += Tool_PostReleaseEvent;
			if (dropItemNote != null)
			{
				UnityEngine.Object.Destroy(dropItemNote);
			}
			dropItemNote = UnityEngine.Object.Instantiate(dropItemNotePrefab);
			dropItemNote.GetComponent<DropItemNote>().RefreshNote(tool);
			StartCoroutine(RunHideDropItemNoteCountdown(tool));
		}
	}

	private IEnumerator RunHideDropItemNoteCountdown(Tool tool)
	{
		yield return new WaitForSeconds(8f);
		while (dropItemNote != null && dropItemNote.transform.localScale.x > 0f)
		{
			float dimension = dropItemNote.transform.localScale.x - 0.1f;
			dropItemNote.transform.localScale = new Vector3(dimension, dimension, dimension);
			yield return null;
		}
		if (dropItemNote != null)
		{
			tool.PostReleaseEvent -= Tool_PostReleaseEvent;
			UnityEngine.Object.Destroy(dropItemNote);
		}
	}

	private void Tool_PostReleaseEvent(Tool tool)
	{
		if (dropItemNote != null)
		{
			tool.PostReleaseEvent -= Tool_PostReleaseEvent;
			UnityEngine.Object.Destroy(dropItemNote);
		}
	}

	private void OnGameEnded()
	{
		Player.LocalPlayer.DailiesObjectiveTracker.CompleteObjective(ProgressionManager.ObjectiveType.OOBE_FinishActivity);
		OOBEObjectivesGranted |= OOBEObjectivesFlags.FinishActivity;
		GameManager gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (gameManager != null)
		{
			gameManager.GameEndedEvent -= OnGameEnded;
		}
	}

