	private ScreenHUD.DialogContent? GetScreensDialogContent(HelpType helpType)
	{
		ScreenInputHandler screenInputHandler = SingletonMonoBehaviour<InputManager>.Instance.ScreenInputHandler;
		if (screenInputHandler != null)
		{
			switch (helpType)
			{
			case HelpType.WalkButton:
				return new ScreenHUD.DialogContent(screenInputHandler.WalkButtonSprite, "Walk");
			case HelpType.Laser:
				return new ScreenHUD.DialogContent(screenInputHandler.LookButtonSprite, "Move Cursor");
			case HelpType.SwipeButton:
				return new ScreenHUD.DialogContent(screenInputHandler.LookButtonSprite, "Turn Camera");
			case HelpType.GrabButton:
				return new ScreenHUD.DialogContent(screenInputHandler.PickupButtonSprite, "Grab");
			case HelpType.OpenWatch:
				return new ScreenHUD.DialogContent(screenInputHandler.MenuButtonSprite, "Open Watch");
			}
		}
		return null;
	}

	public RecRoomAudioClip GetTutorialAudio(TutorialAudioType audioType)
	{
		return tutorialAudioConfigs.GetTutorialAudio(audioType);
	}

	public AudioSource PlayTutorialVO(TutorialAudioType audioType)
	{
		RecRoomAudioClip tutorialAudio = GetTutorialAudio(audioType);
		return PlayVO(tutorialAudio);
	}

	public IEnumerator RunPlayVOClip(RecRoomAudioClip audioClip)
	{
		PlayVO(audioClip);
		while (IsPlayingVO)
		{
			yield return null;
		}
	}

	public IEnumerator RunPlayVOClip(TutorialAudioType audioType)
	{
		yield return RunPlayVOClip(GetTutorialAudio(audioType));
	}

	public IEnumerator RunPlayVO(VOClip vo)
	{
		if (vo.preDuration > 0f)
		{
			yield return new WaitForSeconds(vo.preDuration);
		}
		yield return RunPlayVOClip(vo.AudioClip);
		if (vo.postDuration > 0f)
		{
			yield return new WaitForSeconds(vo.postDuration);
		}
	}

	public AudioSource PlayVO(RecRoomAudioClip recClip)
	{
		if (voAudioSource.isPlaying)
		{
			voAudioSource.Stop();
		}
		voAudioSource.clip = recClip.audioClip;
		voAudioSource.volume = recClip.volume;
		if (recClip.pitchVariation > 0f)
		{
			voAudioSource.pitch = 1f + UnityEngine.Random.Range(0f - recClip.pitchVariation, recClip.pitchVariation);
		}
		else
		{
			voAudioSource.pitch = 1f;
		}
		voAudioSource.Play();
		return voAudioSource;
	}

	public AudioSource Play3DVO(RecRoomAudioClip recClip, Vector3 position)
	{
		if (voAudioSource3D.isPlaying)
		{
			voAudioSource3D.Stop();
		}
		voAudioSource3D.clip = recClip.audioClip;
		voAudioSource3D.volume = recClip.volume;
		if (recClip.pitchVariation > 0f)
		{
			voAudioSource3D.pitch = 1f + UnityEngine.Random.Range(0f - recClip.pitchVariation, recClip.pitchVariation);
		}
		else
		{
			voAudioSource3D.pitch = 1f;
		}
		voAudioSource3D.transform.position = position;
		voAudioSource3D.Play();
		return voAudioSource3D;
	}

	public TutorialAudioType GetInputSpecificVOType(TutorialAudioType audioType)
	{
		TutorialAudioType result = audioType;
		if (ScreensModeNUXEnabled)
		{
			switch (audioType)
			{
			case TutorialAudioType.SwipeRotateToHighlightedShirt:
				result = TutorialAudioType.SCREENS_TurnUntilYoureFacingTheHighlightedShirt;
				break;
			case TutorialAudioType.GrabWhiteAndOrangeShirt:
				result = TutorialAudioType.GrabWhiteAndOrangeShirt;
				break;
			case TutorialAudioType.LookAtWristToViewWatch:
				result = TutorialAudioType.SCREENS_NowLetsLookAtYourWatch;
				break;
			case TutorialAudioType.Q2A_YouCanBringUpYourWatchAtAnyTime:
				result = TutorialAudioType.SCREENS_YouCanBringUpYourWatchAtAnyTime;
				break;
			case TutorialAudioType.WhenReadyOpenShirtDrawer:
				result = TutorialAudioType.SCREENS_WhenReadyOpenShirtDrawer;
				break;
			}
		}
		else if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.VR_WALK)
		{
			result = ((audioType != TutorialAudioType.SwipeRotateToHighlightedShirt) ? audioType : TutorialAudioType.RotateToHighlightedShirt_RightController);
		}
		return result;
	}

	public void RegisterTeachableMoment(TeachableMoment moment)
	{
		registeredMoments.AddUnique(moment);
	}

	public void UnregisterTeachableMoment(TeachableMoment moment)
	{
		registeredMoments.Remove(moment);
		registeredMoments.RemoveNulls();
	}

	public bool TryTeachableMoment<T>() where T : TeachableMoment
	{
		T teachableMoment = GetTeachableMoment<T>();
		if (teachableMoment != null)
		{
			return TryTeachableMoment(teachableMoment);
		}
		return false;
	}

	public T GetTeachableMoment<T>() where T : TeachableMoment
	{
		for (int i = 0; i < registeredMoments.Count; i++)
		{
			if (registeredMoments[i] != null && registeredMoments[i] is T)
			{
				return registeredMoments[i] as T;
			}
		}
		return (T)null;
	}

	public bool ForceTeachableMomentToPlay(TeachableMoment moment)
	{
		if (moment == null)
		{
			return false;
		}
		if (activeMoment != null)
		{
			CancelCurrentTeachingMoment();
		}
		StartTeachableMomentInternal(moment);
		return true;
	}

	public bool TryTeachableMoment(TeachableMoment moment)
	{
		if (moment == null || activeMoment != null || !moment.ShouldRun())
		{
			return false;
		}
		StartTeachableMomentInternal(moment);
		return true;
	}

	private void StartTeachableMomentInternal(TeachableMoment moment)
	{
		activeMoment = moment;
		if (activeMoment.ShouldCancelOnLocalPlayerDestroyed)
		{
			Player.PlayerDestroyedEvent += new Action<Player>(CancelOnLocalPlayerDestroyed);
		}
		if (activeMoment.ShouldCancelOnGameStart)
		{
			GameManager gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (gameManager != null)
			{
				gameManager.GameStartedEvent += CancelCurrentTeachingMoment;
			}
		}
		teachingCoroutine = StartCoroutine(RunActiveTeachableMoment());
	}

	private void CancelOnLocalPlayerDestroyed(Player player)
	{
		if (player.isLocal)
		{
			CancelCurrentTeachingMoment();
		}
	}

	private void CancelCurrentTeachingMoment()
	{
		CancelTeachableMomentIfActive(activeMoment);
	}

	private IEnumerator RunActiveTeachableMoment()
	{
		SingletonMonoBehaviour<GiftManager>.Instance.StopReceivingGifts();
		AnalyticsHelper.TeachableMomentStarted(activeMoment.FriendlyName());
		activeMomentStartTime = DateTime.UtcNow;
		activeMoment.SetupTeachingMoment();
		internalRunTMEnumerator = activeMoment.RunTeachingMoment();
		yield return internalRunTMEnumerator;
		AnalyticsHelper.TeachableMomentEnded(timeSpent: (float)(DateTime.UtcNow - activeMomentStartTime).TotalSeconds, name: activeMoment.FriendlyName(), status: activeMoment.Status);
		Player.PlayerDestroyedEvent -= new Action<Player>(CancelOnLocalPlayerDestroyed);
		GameManager gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (gameManager != null)
		{
			gameManager.GameStartedEvent -= CancelCurrentTeachingMoment;
		}
		TeachableMoment toCleanUp = activeMoment;
		activeMoment = null;
		teachingCoroutine = null;
		internalRunTMEnumerator = null;
		toCleanUp.CleanUp();
	}

	public void CancelTeachableMomentIfActive(TeachableMoment moment)
	{
		if (!(moment != null) || !(activeMoment == moment))
		{
			return;
		}
		double totalSeconds = (DateTime.UtcNow - activeMomentStartTime).TotalSeconds;
		TeachableMoment.CompletionStatus completionStatus = activeMoment.Status;
		if (completionStatus == TeachableMoment.CompletionStatus.NotSet)
		{
			completionStatus = TeachableMoment.CompletionStatus.Canceled;
		}
		AnalyticsHelper.TeachableMomentEnded(activeMoment.FriendlyName(), completionStatus, (float)totalSeconds);
		if (this != null)
		{
			StopCoroutine(teachingCoroutine);
			StopCoroutine(internalRunTMEnumerator);
		}
		Player.PlayerDestroyedEvent -= new Action<Player>(CancelOnLocalPlayerDestroyed);
		if (RecRoomSceneManager.Instance != null)
		{
			GameManager gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (gameManager != null)
			{
				gameManager.GameStartedEvent -= CancelCurrentTeachingMoment;
			}
		}
		activeMoment.CleanUp();
		activeMoment = null;
		teachingCoroutine = null;
		internalRunTMEnumerator = null;
	}

	public void PlayAttentionHelper(Vector3 position, bool playAudio = true)
	{
		PooledParticle pooledParticle = ObjectPool.Instance.Acquire(attentionHelperVFXPrefab);
		if (pooledParticle != null)
		{
			pooledParticle.Play(position, Quaternion.identity);
		}
		if (playAudio)
		{
			AudioManager.Play3DSFX(attentionHelperAudio, position);
		}
	}
