public class WatchChallengesTeachableMoment : TeachableMoment
{
	[Header("VO")]
	[SerializeField]
	private TutorialManager.VOClip oneLastTipVO;

	[SerializeField]
	private TutorialManager.VOClip takeALookAtTheOrientationChallengesVO;

	[SerializeField]
	private TutorialManager.VOClip pressChallengesVO;

	[SerializeField]
	private TutorialManager.VOClip completingTheseChallengesVO;

	[SerializeField]
	private TutorialManager.VOClip haveFunVO;

	[NonSerialized]
	public bool Suppress;

	private WatchUI watchMenu;

	private HomeScreenFlow homeScreen;

	public override string FriendlyName()
	{
		return "ShowWatchChallenges";
	}

	public override bool ShouldRun()
	{
		if (Suppress)
		{
			return false;
		}
		bool flag = !SingletonMonoBehaviour<TutorialManager>.Instance.GetIsFirstTimeIn(TutorialManager.NewUser_FirstTimeIn.WatchChallenges);
		bool flag2 = SingletonMonoBehaviour<TutorialManager>.Instance.NUXState <= TutorialManager.NUXFlowState.Q2A_ClickPaddleball || (SingletonMonoBehaviour<TutorialManager>.Instance.NUXState >= TutorialManager.NUXFlowState.TDU_OpenTokensBox && SingletonMonoBehaviour<TutorialManager>.Instance.NUXState <= TutorialManager.NUXFlowState.TDU_Teleport);
		if (flag || flag2 || RecRoomSceneManager.HasRunningGame || !Player.LocalPlayerExists)
		{
			return false;
		}
		return true;
	}

	public override void SetupTeachingMoment()
	{
		base.SetupTeachingMoment();
		watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		homeScreen = watchMenu.GetFlowByType<HomeScreenFlow>();
	}

	protected override void InternalCleanUp()
	{
		if (Player.LocalPlayerExists)
		{
			watchMenu.BasicInteractionRestriction.AllowOnlyThisItem = null;
			Player.LocalPlayer.PlayerLocomotion.RemoveMovementRestriction(this);
		}
	}

	public override IEnumerator RunTeachingMoment()
	{
		yield return new WaitForSeconds(1f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(oneLastTipVO);
		yield return new WaitForSeconds(1f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(takeALookAtTheOrientationChallengesVO);
		SingletonMonoBehaviour<TutorialManager>.Instance.SetIsFirstTimeIn(TutorialManager.NewUser_FirstTimeIn.WatchChallenges, firstTime: false);
		WatchUI.SetToast(ToastIds.Challenges, "NEW");
		Player.LocalPlayer.PlayerUI.WatchAttractor.PlayNotificationEffect(isMessageNotification: false);
		WatchUI watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		ChecklistWatchUIFlow checklistMenu = watchMenu.GetFlowByType<ChecklistWatchUIFlow>();
		while (!Player.LocalPlayer.PlayerUI.IsWatchMenuOpen)
		{
			yield return null;
		}
		homeScreen.HighlightButton<ChecklistWatchUIFlow>();
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(pressChallengesVO);
		while (!checklistMenu.IsCurrentFlow)
		{
			yield return null;
		}
		homeScreen.ClearHighlights();
		yield return new WaitForSeconds(1f);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(completingTheseChallengesVO);
		yield return SingletonMonoBehaviour<TutorialManager>.Instance.RunPlayVO(haveFunVO);
		status = CompletionStatus.Finished;
	}
}
namespace RecRoom.Core.Updates
{
	public class DynamicUpdateGroup : UpdateGroupBase<DynamicUpdateGroupObject>
	{
		public float costThreshold;

		public DynamicUpdateGroup(float costThreshold, bool callWhenDisabled, int[] maxPerQualitySetting)
		{
			this.costThreshold = costThreshold;
			base.callWhenDisabled = callWhenDisabled;
			base.maxPerQualitySetting = maxPerQualitySetting;
		}
	}
	public class DynamicUpdateGroupObject : UpdateGroupObjectBase, IComparable<DynamicUpdateGroupObject>
	{
		public DynamicUpdateManager.ComputeCost costFunction;

		public float currentCost;

		public DynamicUpdateGroupObject(Behaviour behaviour, DynamicUpdateManager.ComputeCost costFunction, UpdateFunction updateFunction)
		{
			base.behaviour = behaviour;
			this.costFunction = costFunction;
			base.updateFunction = updateFunction;
			currentCost = float.MaxValue;
		}

		int IComparable<DynamicUpdateGroupObject>.CompareTo(DynamicUpdateGroupObject other)
		{
			return currentCost.CompareTo(other.currentCost);
		}
	}
	public class DynamicUpdateManager : UpdateManagerBase<DynamicUpdateGroup, DynamicUpdateGroupObject>
	{
		public delegate float ComputeCost();

		public delegate bool IsVisible();

		public delegate Transform GetTransform();

		private static DynamicUpdateManager _instance;

		private static bool cachedPlayerExists;

		private static Transform cachedCameraTransform;

		public static DynamicUpdateManager Instance
		{
			get
			{
				if (_instance == null)
				{
					GameObject gameObject = new GameObject("DynamicUpdateManager");
					UnityEngine.Object.DontDestroyOnLoad(gameObject);
					_instance = gameObject.AddComponent<DynamicUpdateManager>();
				}
				return _instance;
			}
		}

		public static ComputeCost DefaultCostFunction(IsVisible isVisible, GetTransform getTransform)
		{
			return delegate
			{
				if (!cachedPlayerExists || !isVisible())
				{
					return float.MaxValue;
				}
				Transform transform = cachedCameraTransform;
				Transform transform2 = getTransform();
				return (transform2.position - transform.position).sqrMagnitude;
			};
		}

		public void RegisterGroup(string groupName, float costThreshold, bool callWhenDisabled, int[] maxPerQualitySetting)
		{
			RegisterGroupDetails(groupName, new DynamicUpdateGroup(costThreshold, callWhenDisabled, maxPerQualitySetting));
		}

		public void RegisterObject(string groupName, Behaviour behaviour, ComputeCost costFunction, UpdateGroupObjectBase.UpdateFunction updateFunction)
		{
			RegisterObjectDetails(groupName, new DynamicUpdateGroupObject(behaviour, costFunction, updateFunction));
		}

		protected override void UpdateGroups(IEnumerable<DynamicUpdateGroup> groups, int qualitySetting)
		{
			cachedPlayerExists = Player.LocalPlayerExists;
			if (cachedPlayerExists)
			{
				cachedCameraTransform = Player.LocalPlayer.Head.transform;
			}
			foreach (DynamicUpdateGroup group in groups)
			{
				if (group.dynamicObjects.Count == 0)
				{
					break;
				}
				int num = group.maxPerQualitySetting[qualitySetting];
				for (int i = 0; i < group.dynamicObjects.Count; i++)
				{
					DynamicUpdateGroupObject dynamicUpdateGroupObject = group.dynamicObjects[i];
					dynamicUpdateGroupObject.currentCost = ((!dynamicUpdateGroupObject.behaviour.isActiveAndEnabled) ? float.MaxValue : dynamicUpdateGroupObject.costFunction());
				}
				group.dynamicObjects.Sort();
				int num2 = 0;
				for (int j = 0; j < group.dynamicObjects.Count; j++)
				{
					DynamicUpdateGroupObject dynamicUpdateGroupObject2 = group.dynamicObjects[j];
					bool flag = num2 >= num;
					if (flag && !group.callWhenDisabled)
					{
						break;
					}
					bool flag2 = !flag && dynamicUpdateGroupObject2.currentCost < group.costThreshold;
					if (flag2 || group.callWhenDisabled)
					{
						dynamicUpdateGroupObject2.updateFunction(flag2);
						if (flag2)
						{
							num2++;
						}
					}
				}
			}
		}
	}
	public class StaggeredUpdateGroup : UpdateGroupBase<StaggeredUpdateGroupObject>
	{
		public int lastUpdatedIndex;

		public StaggeredUpdateGroup(bool callWhenDisabled, int[] maxPerQualitySetting)
		{
			base.callWhenDisabled = callWhenDisabled;
			base.maxPerQualitySetting = maxPerQualitySetting;
		}
	}
	public class StaggeredUpdateGroupObject : UpdateGroupObjectBase
	{
		public StaggeredUpdateGroupObject(Behaviour behaviour, UpdateFunction updateFunction)
		{
			base.behaviour = behaviour;
			base.updateFunction = updateFunction;
		}
	}
	public class StaggeredUpdateManager : UpdateManagerBase<StaggeredUpdateGroup, StaggeredUpdateGroupObject>
	{
		private static StaggeredUpdateManager _instance;

		public static StaggeredUpdateManager Instance
		{
			get
			{
				if (_instance == null)
				{
					GameObject gameObject = new GameObject("StaggeredUpdateManager");
					UnityEngine.Object.DontDestroyOnLoad(gameObject);
					_instance = gameObject.AddComponent<StaggeredUpdateManager>();
				}
				return _instance;
			}
		}

		public void RegisterGroup(string groupName, bool callWhenDisabled, int[] maxPerQualitySetting)
		{
			RegisterGroupDetails(groupName, new StaggeredUpdateGroup(callWhenDisabled, maxPerQualitySetting));
		}

		public void RegisterObject(string groupName, Behaviour behaviour, UpdateGroupObjectBase.UpdateFunction updateFunction)
		{
			RegisterObjectDetails(groupName, new StaggeredUpdateGroupObject(behaviour, updateFunction));
		}

		protected override void UpdateGroups(IEnumerable<StaggeredUpdateGroup> groups, int qualitySetting)
		{
			foreach (StaggeredUpdateGroup group in groups)
			{
				if (group.dynamicObjects.Count == 0)
				{
					break;
				}
				int num = group.maxPerQualitySetting[qualitySetting];
				int num2 = (group.lastUpdatedIndex + 1) % group.dynamicObjects.Count;
				int num3 = 0;
				int num4 = num2;
				do
				{
					bool flag = num3 >= num;
					if (flag && !group.callWhenDisabled)
					{
						break;
					}
					bool flag2 = !flag && group.dynamicObjects[num4].behaviour.isActiveAndEnabled;
					StaggeredUpdateGroupObject staggeredUpdateGroupObject = group.dynamicObjects[num4];
					if (flag2 || group.callWhenDisabled)
					{
						staggeredUpdateGroupObject.updateFunction(flag2);
						if (flag2)
						{
							group.lastUpdatedIndex = num4;
							num3++;
						}
					}
					num4 = (num4 + 1) % group.dynamicObjects.Count;
				}
				while (num4 != num2);
			}
		}
	}
	public abstract class UpdateGroupBase<TObject> where TObject : UpdateGroupObjectBase
	{
		public bool callWhenDisabled;

		public int[] maxPerQualitySetting;

		public List<TObject> dynamicObjects = new List<TObject>();

		public bool RemoveObject(Behaviour behaviour)
		{
			for (int i = 0; i < dynamicObjects.Count; i++)
			{
				if (dynamicObjects[i].behaviour == behaviour)
				{
					dynamicObjects.RemoveAt(i);
					return true;
				}
			}
			return false;
		}
	}
	public abstract class UpdateGroupObjectBase
	{
		public delegate void UpdateFunction(bool shouldUpdate);

		public Behaviour behaviour;

		public UpdateFunction updateFunction;
	}
	public abstract class UpdateManagerBase<TGroup, TObject> : UnityEngine.MonoBehaviour where TGroup : UpdateGroupBase<TObject> where TObject : UpdateGroupObjectBase
	{
		private Dictionary<string, TGroup> updateGroups = new Dictionary<string, TGroup>();

		public bool IsGroupRegistered(string groupName)
		{
			return updateGroups.ContainsKey(groupName);
		}

		protected void RegisterGroupDetails(string groupName, TGroup groupDetails)
		{
			if (!IsGroupRegistered(groupName))
			{
				updateGroups.Add(groupName, groupDetails);
			}
		}

		protected void RegisterObjectDetails(string groupName, TObject objectDetails)
		{
			TGroup val = updateGroups[groupName];
			val.dynamicObjects.Add(objectDetails);
		}

		public void UnregisterObject(string groupName, Behaviour behaviour)
		{
			if (updateGroups.ContainsKey(groupName))
			{
				TGroup val = updateGroups[groupName];
				val.RemoveObject(behaviour);
			}
		}

		private void Update()
		{
			int qualitySetting = 0;
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null && RecroomPrefs.IsReady)
			{
				qualitySetting = (int)SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting;
			}
			Dictionary<string, TGroup>.ValueCollection values = updateGroups.Values;
			UpdateGroups(values, qualitySetting);
		}

		protected abstract void UpdateGroups(IEnumerable<TGroup> groups, int qualitySetting);
	}
}
