	public class AutomaticHolsteringTool : Photon.MonoBehaviour
	{
		[SerializeField]
		private ToolEquipSlot.EquipSlotType equipSlotType;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private ToolPlayerAttractor attractor;

		private SynchronizedField<int> _permanentOwnerId;

		private PlayerToolEquipSlot manuallySelectedEquipSlot;

		public Tool Tool => _tool;

		public PhotonPlayer PermanentOwnerPlayer
		{
			get
			{
				return PhotonPlayer.Find(_permanentOwnerId.Get());
			}
			set
			{
				_permanentOwnerId.Set(value?.ID ?? (-1));
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_permanentOwnerId = new SynchronizedField<int>(this, "POID", -1, SetterPermissionMode.AUTHORITY, OnPermanentOwnerChanged);
			Tool.PostPickupEvent += OnToolPickup;
			Tool.PostResetEvent += OnToolReset;
			Tool.PostAttachEvent += OnToolAttach;
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			Tool.AllowedToTransferOwnershipOnCollision = false;
		}

		private void Start()
		{
			OnPermanentOwnerChanged();
		}

		protected override void OnDestroy()
		{
			Tool.PostPickupEvent -= OnToolPickup;
			Tool.PostResetEvent -= OnToolReset;
			Tool.PostAttachEvent -= OnToolAttach;
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			base.OnDestroy();
		}

		private void OnToolPickup(Tool tool)
		{
			if (tool.HolderPlayer != null && tool.HolderPlayer.isLocal)
			{
				PhotonPlayer permanentOwnerPlayer = PermanentOwnerPlayer;
				if (base.hasAuthority && (permanentOwnerPlayer == null || permanentOwnerPlayer != tool.HolderPlayer.PhotonPlayer))
				{
					PermanentOwnerPlayer = tool.HolderPlayer.PhotonPlayer;
				}
			}
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (wasCleanedUp)
			{
				if (Tool.hasAuthority && PermanentOwnerPlayer != null)
				{
					TryAutomaticEquipTool();
				}
			}
			else if (base.hasAuthority)
			{
				PermanentOwnerPlayer = null;
			}
		}

		private void OnToolAttach(Tool tool)
		{
			if (!tool.IsEquippedOnPlayer)
			{
				return;
			}
			PhotonPlayer photonPlayer = PermanentOwnerPlayer;
			PhotonPlayer photonPlayer2 = tool.HolderPlayer?.PhotonPlayer;
			if (photonPlayer == null)
			{
				PermanentOwnerPlayer = photonPlayer2;
				photonPlayer = photonPlayer2;
			}
			if (photonPlayer == null || photonPlayer2 != photonPlayer)
			{
				return;
			}
			PlayerToolEquipSlot[] allSlots = photonPlayer.ToPlayer().ToolEquipSlots.AllSlots;
			foreach (PlayerToolEquipSlot playerToolEquipSlot in allSlots)
			{
				if (playerToolEquipSlot.EquippedTool == tool)
				{
					manuallySelectedEquipSlot = playerToolEquipSlot;
					break;
				}
			}
		}

		private void TryAutomaticEquipTool(PlayerHand equippingHand = null)
		{
			PhotonPlayer permanentOwnerPlayer = PermanentOwnerPlayer;
			if (permanentOwnerPlayer == null || !Tool.hasAuthority)
			{
				return;
			}
			Player player = permanentOwnerPlayer.ToPlayer();
			PlayerToolEquipSlot playerToolEquipSlot = manuallySelectedEquipSlot;
			if (playerToolEquipSlot == null || !player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, playerToolEquipSlot))
			{
				playerToolEquipSlot = null;
				switch (equipSlotType)
				{
				case ToolEquipSlot.EquipSlotType.Hip:
					if (player.DominantHand.Type == PlayerHand.HandType.Left)
					{
						if (player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, player.ToolEquipSlots.LeftHipSlot))
						{
							playerToolEquipSlot = player.ToolEquipSlots.LeftHipSlot;
						}
						else if (player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, player.ToolEquipSlots.RightHipSlot))
						{
							playerToolEquipSlot = player.ToolEquipSlots.RightHipSlot;
						}
					}
					else if (player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, player.ToolEquipSlots.RightHipSlot))
					{
						playerToolEquipSlot = player.ToolEquipSlots.RightHipSlot;
					}
					else if (player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, player.ToolEquipSlots.LeftHipSlot))
					{
						playerToolEquipSlot = player.ToolEquipSlots.LeftHipSlot;
					}
					break;
				case ToolEquipSlot.EquipSlotType.Shoulder:
					if (player.ToolEquipSlots.CanEquipTool(Tool, equippingHand, player.ToolEquipSlots.ShoulderSlot))
					{
						playerToolEquipSlot = player.ToolEquipSlots.ShoulderSlot;
					}
					break;
				}
			}
			if (playerToolEquipSlot != null)
			{
				player.ToolEquipSlots.TryEquipTool(Tool, equippingHand, playerToolEquipSlot);
			}
			else if (base.hasAuthority)
			{
				PermanentOwnerPlayer = null;
			}
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer disconnectedPlayer)
		{
			PhotonPlayer permanentOwnerPlayer = PermanentOwnerPlayer;
			if (permanentOwnerPlayer != null && permanentOwnerPlayer == disconnectedPlayer)
			{
				permanentOwnerPlayer = null;
			}
		}

		private void OnPermanentOwnerChanged()
		{
			PhotonPlayer permanentOwnerPlayer = PermanentOwnerPlayer;
			bool flag = permanentOwnerPlayer != null;
			Tool.SupportsAnimateIn = !flag;
			if (attractor != null)
			{
				attractor.OverrideSetEnableOnReset(!flag);
			}
		}
	}
}
public class Ball : Photon.MonoBehaviour
{
	public Tool Tool { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		Tool = GetComponent<Tool>();
		if (Tool != null)
		{
			Tool.CustomApplyForceModifier = ModifyForce;
		}
	}

	private void ModifyForce(ref Vector3 force, Vector3 position)
	{
		Vector3 normalized = (Tool.RigidbodyEx.physicsPosition - position).normalized;
		force = normalized * force.magnitude;
	}
}
