		public void MasterReset()
		{
			if (PhotonNetwork.isMasterClient)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.masterClient);
				}
				stateMachine.EnterState(0);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (Handle != null)
			{
				handleDefaultLocalPosition = base.transform.InverseTransformPoint(Handle.transform.position);
				handleDefaultLocalRotation = base.transform.InverseTransformRotation(Handle.transform.rotation);
				Handle.SuppressAnimateInOut = true;
				Handle.AttachEnabled = false;
				if (Handle.RigidbodyEx != null)
				{
					Handle.RigidbodyEx.AddKinematic(this);
				}
				Handle.AddCustomPickupCondition(CustomHandlePickupCondition);
				Handle.photonView.OwnerChangedEvent += OnHandleOwnerChange;
			}
			if (animatorVisibilityGroup != null)
			{
				animatorVisibilityGroup.VisibilityChangedEvent.Add(OnAnimatorVisibilityChanged);
			}
			stateMachine = new AutoScheduledSynchronizedStateMachine(this, "SSM", SetterPermissionMode.AUTHORITY);
			stateMachine.AddState(0, OnEnterClosedState, OnExitClosedState, this.OnUpdateClosedState, UpdateClosedStateAuthorityUpdateHz, UpdateClosedStateNonAuthorityUpdateHz);
			stateMachine.AddState(1, OnEnterOpeningState, OnExitOpeningState, this.OnUpdateOpeningState, UpdateOpeningStateAuthorityUpdateHz, UpdateOpeningStateNonAuthorityUpdateHz);
			stateMachine.AddState(2, OnEnterOpenState, OnExitOpenState, this.OnUpdateOpenState, UpdateOpenStateAuthorityUpdateHz, UpdateOpenStateNonAuthorityUpdateHz);
		}

		protected virtual void Start()
		{
			if (additionalHandleScreenCollider != null && Handle != null)
			{
				Handle.AddToolCollider(additionalHandleScreenCollider);
				LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				instance.DisplayModeChange = (Action)Delegate.Combine(instance.DisplayModeChange, new Action(OnPlayerDisplayModeChange));
				OnPlayerDisplayModeChange();
			}
			if (additionalHandleRenderers != null && Handle != null)
			{
				for (int i = 0; i < additionalHandleRenderers.Length; i++)
				{
					Handle.AddRenderer(additionalHandleRenderers[i]);
				}
			}
			stateMachine.Start(0);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
			{
				LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				instance.DisplayModeChange = (Action)Delegate.Remove(instance.DisplayModeChange, new Action(OnPlayerDisplayModeChange));
			}
			if (Handle != null)
			{
				Handle.photonView.OwnerChangedEvent -= OnHandleOwnerChange;
			}
			if (animatorVisibilityGroup != null)
			{
				animatorVisibilityGroup.VisibilityChangedEvent.Remove(OnAnimatorVisibilityChanged);
			}
		}

		private void OnEnable()
		{
			if (base.hasAuthority && stateMachine.IsInitialized)
			{
				stateMachine.EnterState(0);
			}
		}

		private void OnAnimatorVisibilityChanged(bool isVisible)
		{
			if (isVisible)
			{
				SetAnimatorState();
			}
		}

		private bool CustomHandlePickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return OnlyInteractionAllowedPlayer == null || selectingPlayer.PhotonPlayer == OnlyInteractionAllowedPlayer;
		}

		private void OnHandleOwnerChange(int ownerId)
		{
			if (Handle != null && Handle.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
		}

		private void OnPlayerDisplayModeChange()
		{
			if (additionalHandleScreenCollider != null)
			{
				additionalHandleScreenCollider.gameObject.SetActive(SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode);
			}
		}

		private void SetAnimatorState()
		{
			if (animator != null)
			{
				ushort currentStateId = stateMachine.CurrentStateId;
				animator.SetInteger(ANIMATOR_STATE_ID, currentStateId);
			}
		}

		protected virtual void OnEnterClosedState(ushort previousStateId, ushort previousSubStateId)
		{
			SetAnimatorState();
			if (Handle != null && additionalHandleScreenCollider != null && !additionalHandleScreenCollider.gameObject.activeSelf)
			{
				additionalHandleScreenCollider.gameObject.SetActive(SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode);
			}
			if (Handle != null && Handle.hasAuthority)
			{
				Handle.AuthorityResetToDefault(base.transform.TransformPoint(handleDefaultLocalPosition), base.transform.TransformRotation(handleDefaultLocalRotation), sleepPhysics: true);
			}
			if (CloseEvent != null)
			{
				CloseEvent(this);
			}
		}

		protected virtual void OnExitClosedState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		protected virtual void OnEnterOpeningState(ushort previousStateId, ushort previousSubStateId)
		{
			SetAnimatorState();
			if (Handle != null && additionalHandleScreenCollider != null && additionalHandleScreenCollider.gameObject.activeSelf)
			{
				additionalHandleScreenCollider.gameObject.SetActive(value: false);
			}
			if (OpeningEvent != null)
			{
				OpeningEvent(this);
			}
		}

		protected virtual void OnExitOpeningState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		protected virtual void OnEnterOpenState(ushort previousStateId, ushort previousSubStateId)
		{
			SetAnimatorState();
			if (Handle != null && additionalHandleScreenCollider != null && additionalHandleScreenCollider.gameObject.activeSelf)
			{
				additionalHandleScreenCollider.gameObject.SetActive(value: false);
			}
			if (Handle != null && Handle.hasAuthority)
			{
				Handle.AuthorityDisableAndMovetoLastSpawnPoint();
			}
			if (OpenEvent != null)
			{
				OpenEvent(this);
			}
		}

		protected virtual void OnExitOpenState(ushort nextStateId, ushort nextSubStateId)
		{
		}
	}
