		private float FillScale
		{
			set
			{
				if (value == 0f)
				{
					fill.gameObject.SetActive(value: false);
					return;
				}
				fill.gameObject.SetActive(value: true);
				fill.localScale = new Vector3(value * initialFillScale, fill.localScale.y, fill.localScale.z);
			}
		}

		public event Charged ChargedEvent
		{
			add
			{
				Charged charged = this.m_ChargedEvent;
				Charged charged2;
				do
				{
					charged2 = charged;
					charged = Interlocked.CompareExchange(ref this.m_ChargedEvent, (Charged)Delegate.Combine(charged2, value), charged);
				}
				while (charged != charged2);
			}
			remove
			{
				Charged charged = this.m_ChargedEvent;
				Charged charged2;
				do
				{
					charged2 = charged;
					charged = Interlocked.CompareExchange(ref this.m_ChargedEvent, (Charged)Delegate.Remove(charged2, value), charged);
				}
				while (charged != charged2);
			}
		}

