		{
			base.Awake();
			collisionTracker = new PlayerButtonCollisionTracker(canOnlyPushLocally: false, canPushWithTools: false, pushingToolsMustBeHeld: false);
			stateMachine.AddState(0, OnEnterDeactivatedStae, null, null);
			stateMachine.AddState(1, OnEnterActivatedState, null, null);
			stateMachine.AddState(1, 0, OnEnterUnpressedSubState, null, null);
			stateMachine.AddState(1, 1, OnEnterChargingSubState, OnExitChargingSubState, OnUpdateChargingSubState);
			stateMachine.AddState(1, 2, OnEnterDischargingSubState, OnExitDischargingSubState, OnUpdateDischargingSubState);
			stateMachine.AddState(1, 3, OnEnterChargedSubState, null, null);
			initialFillScale = fill.localScale.x;
			if (fill != null)
			{
				FillScale = 0f;
			}
			Activated = true;
		}

		private void OnDisable()
		{
			if (Activated)
			{
				stateMachine.EnterState(1, 0);
			}
			StopChargeAudio();
			StopDischargeAudio();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			StopChargeAudio();
			StopDischargeAudio();
		}

		protected override void OnTriggerEnter(Collider collider)
		{
			base.OnTriggerEnter(collider);
			Player.BodyPart bodyPart;
			Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null && bodyPart.IsHand())
			{
				pressingPlayer = colliderPlayer.PhotonPlayer;
				pressingPlayerHand = colliderPlayer.GetHand(bodyPart);
			}
		}

		protected override void PlayerPushedButton(PhotonPlayer pushingPlayer)
		{
			base.PlayerPushedButton(pushingPlayer);
			stateMachine.EnterState(1, 1);
		}

		protected override void PlayerReleasedButton(PhotonPlayer pushingPlayer)
		{
			base.PlayerReleasedButton(pushingPlayer);
			if (Activated && GetPressingPlayersCount() == 0)
			{
				if (stateMachine.CurrentSubStateId == 1)
				{
					stateMachine.EnterState(1, 2);
				}
				else
				{
					stateMachine.EnterState(1, 0);
				}
			}
		}

		private void Update()
		{
			stateMachine.Update();
		}

		private void OnEnterDeactivatedStae(ushort previousStateId, ushort previousSubStateId)
		{
			collisionTracker.TrackedColliders.Clear();
			nonPhysicalPressers.Clear();
			pressingPlayerHand = null;
			pressingPlayer = null;
			if (buttonRenderers != null)
			{
				for (int i = 0; i < buttonRenderers.Length; i++)
				{
					buttonRenderers[i].material.SetColor(buttonColorId, deactivatedButtonColor);
				}
			}
			if (buttonLabelTextRenderer != null)
			{
				buttonLabelTextRenderer.material.SetColor(textColorId, deactivatedButtonLabelTextColor);
			}
			interpolator.TargetTransform = pressedTransform;
		}

		private void OnEnterActivatedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (buttonRenderers != null)
			{
				for (int i = 0; i < buttonRenderers.Length; i++)
				{
					buttonRenderers[i].material.SetColor(buttonColorId, ButtonColor);
				}
			}
			if (buttonLabelTextRenderer != null)
			{
				buttonLabelTextRenderer.material.SetColor(textColorId, ButtonTextColor);
			}
			interpolator.TargetTransform = unpressedTransform;
		}

		private void OnEnterUnpressedSubState(ushort previousStateId, ushort previousSubStateId)
		{
			pressingPlayerHand = null;
			pressingPlayer = null;
			interpolator.TargetTransform = unpressedTransform;
			ChargeAmount = 0f;
		}

		private void OnEnterChargingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			StartChargeAudio();
			interpolator.TargetTransform = pressedTransform;
		}

		private void OnUpdateChargingSubState()
		{
			if (GetPressingPlayersCount() == 0 || !TestCustomChargeConditions(pressingPlayer, pressingPlayerHand))
			{
				stateMachine.EnterState(1, 0);
			}
			if (pressingPlayerHand != null && pressingPlayerHand.isLocal)
			{
				pressingPlayerHand.Vibrate(1, vibrationIntensity);
			}
			float num = 1f / ChargeDuration;
			ChargeAmount = Mathf.Clamp01(ChargeAmount + num * UnityEngine.Time.deltaTime);
			if (ChargeAmount >= 1f)
			{
				stateMachine.EnterState(1, 3);
			}
		}

		private void OnExitChargingSubState(ushort nextStateId, ushort nextSubStateId)
		{
			StopChargeAudio();
		}

		private void OnEnterDischargingSubState(ushort previousStateId, ushort previousSubStateId)
		{
			pressingPlayerHand = null;
			pressingPlayer = null;
			interpolator.TargetTransform = unpressedTransform;
			StartDischargeAudio();
		}

		private void OnUpdateDischargingSubState()
		{
			float num = 1f / DischargeDuration;
			ChargeAmount = Mathf.Clamp01(ChargeAmount - num * UnityEngine.Time.deltaTime);
		}

		private void OnExitDischargingSubState(ushort nextStateId, ushort nextSubStateId)
		{
			StopDischargeAudio();
		}

		private void OnEnterChargedSubState(ushort previousStateId, ushort previousSubStateId)
		{
			interpolator.TargetTransform = pressedTransform;
			AudioManager.Play3DSFX(successAudio, base.transform);
			if (this.ChargedEvent != null)
			{
				this.ChargedEvent(this);
			}
		}

		private void StartChargeAudio()
		{
			StopChargeAudio();
			chargeAudioSource = AudioManager.StartLooping3DSFX(chargeAudio, base.transform);
		}

		private void StopChargeAudio()
		{
			if (chargeAudioSource != null)
			{
				AudioManager.StopLoopingSFX(chargeAudioSource);
				chargeAudioSource = null;
			}
		}

		private void StartDischargeAudio()
		{
			StopDischargeAudio();
			dischargeAudioSource = AudioManager.StartLooping3DSFX(dischargeAudio, base.transform);
		}

		private void StopDischargeAudio()
		{
			if (dischargeAudioSource != null)
			{
				AudioManager.StopLoopingSFX(dischargeAudioSource);
				dischargeAudioSource = null;
			}
		}

		public void AddCustomChargeCondition(ChargeCondition condition)
		{
			customChargeConditions.Add(condition);
		}

		public void RemoveCustomChargeCondition(ChargeCondition condition)
		{
			customChargeConditions.Remove(condition);
		}

		private bool TestCustomChargeConditions(PhotonPlayer player, PlayerHand playerHand)
		{
			for (int i = 0; i < customChargeConditions.Count; i++)
			{
				if (!customChargeConditions[i](this, player, playerHand))
				{
					return false;
				}
			}
			return true;
		}
	}
}
public class NetworkedPhysicalButton : PhysicalButtonBase, IPersistable
{
	private MomentarySourceNodeVisualization momentarySourceNode;

	private ButtonCircuitNodeDisplay buttonSourceNode;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Tool tool;

	private SynchronizedField<bool> _signalIsPlayerID;

	private SynchronizedField<int> _currentlyPressingPlayerId;

	public bool SignalIsPlayerID
	{
		get
		{
			return _signalIsPlayerID.Get();
		}
		set
		{
			_signalIsPlayerID.Set(value);
		}
	}

	private int currentlyPressingPlayerId
	{
		get
		{
			return _currentlyPressingPlayerId.Get();
		}
		set
		{
			_currentlyPressingPlayerId.Set(value);
		}
	}

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		momentarySourceNode = GetComponent<MomentarySourceNodeVisualization>();
		buttonSourceNode = GetComponent<ButtonCircuitNodeDisplay>();
		collisionTracker = new PlayerButtonCollisionTracker(canOnlyPushLocally: false, canPushWithTools: true, pushingToolsMustBeHeld: false);
		_signalIsPlayerID = new SynchronizedField<bool>(this, "PB_SIPI", defaultValue: false, SetterPermissionMode.ANYONE);
		_currentlyPressingPlayerId = new SynchronizedField<int>(this, "PB_CPPI", -1, SetterPermissionMode.MASTER);
		tool.KinematicOnSleep = true;
	}

	private void Start()
	{
		CreationObject component = GetComponent<CreationObject>();
		if (component != null)
		{
			BoolSettingEditEvent settingEvent = new BoolSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultBoolUIControlPrefab, delegate(CreationObjectSettingBooleanUIControl instance)
			{
				instance.PropertyDescription.text = "Send Player as signal output";
				instance.PropertyGetter = SignalIsPlayerID_Get;
				instance.PropertySetter = SignalIsPlayerID_Set;
			});
			component.AddConfigurableSetting(settingEvent);
		}
	}

	public void SignalIsPlayerID_Set(bool newValue)
	{
		SignalIsPlayerID = newValue;
	}

	public bool SignalIsPlayerID_Get()
	{
		return SignalIsPlayerID;
	}

	protected override void PlayerPushedButton(PhotonPlayer pushingPlayer)
	{
		if (pushingPlayer != null)
		{
			currentlyPressingPlayerId = pushingPlayer.ID;
		}
		base.PlayerPushedButton(pushingPlayer);
	}

	protected override void PlayerReleasedButton(PhotonPlayer player)
	{
		base.PlayerReleasedButton(player);
		PhotonPlayer somePressingPlayer = GetSomePressingPlayer();
		if (somePressingPlayer == null)
		{
			currentlyPressingPlayerId = -1;
		}
		else
		{
			currentlyPressingPlayerId = somePressingPlayer.ID;
		}
	}

	public void SendMomentarySourceOutput(PhysicalButtonBase button, Player player)
	{
		if (momentarySourceNode != null)
		{
			momentarySourceNode.SetOutput(OutputSlot.R, 1);
			momentarySourceNode.SetOutput(OutputSlot.G, player.PhotonPlayer.ID);
		}
		SendButtonStateOutput(ButtonState.Pressed, player);
	}

	public void SendButtonStateOutput(ButtonState state, Player player)
	{
		if (buttonSourceNode != null)
		{
			int signal = ((!SignalIsPlayerID) ? 1 : player.PhotonPlayer.ID);
			int signal2 = ((!SignalIsPlayerID) ? GetPressingPlayersCount() : player.PhotonPlayer.ID);
			switch (state)
			{
			case ButtonState.Pressed:
				buttonSourceNode.SetOutput(OutputSlot.R, signal);
				buttonSourceNode.SetOutput(OutputSlot.G, signal2);
				break;
			case ButtonState.Released:
				buttonSourceNode.SetOutput(OutputSlot.B, signal);
				buttonSourceNode.SetOutput(OutputSlot.G, 0);
				break;
			case ButtonState.Transferred:
				buttonSourceNode.SetOutput(OutputSlot.G, signal2);
				break;
			}
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData != null && deserializeParams.viewData.ButtonData != null)
		{
			SignalIsPlayerID = deserializeParams.viewData.ButtonData.SignalIsPlayerId;
		}
		else
		{
			SignalIsPlayerID = false;
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.ButtonData == null)
		{
			viewData.ButtonData = new ButtonData();
		}
		viewData.ButtonData.SignalIsPlayerId = SignalIsPlayerID;
	}
}
public abstract class PhysicalButtonBase : Photon.MonoBehaviour
{
	public enum ButtonState
	{
		Pressed,
		Transferred,
		Released
	}

	[Serializable]
	public class PhysicalButtonPressEvent : UnityEvent<PhysicalButtonBase, Player>
	{
	}

	[Serializable]
	public class PhysicalButtonStateEvent : UnityEvent<ButtonState, Player>
	{
	}

	[SerializeField]
	protected float instanceLimitDuration = 0.5f;

	[SerializeField]
	private RecRoomAudioClip onButtonPressAudio;

	protected PlayerButtonCollisionTracker collisionTracker;

	protected List<PhotonPlayer> nonPhysicalPressers = new List<PhotonPlayer>();

	private List<PhotonPlayer> released;

	public PhysicalButtonPressEvent pressEvent;

	public PhysicalButtonStateEvent onReleaseEvent;

	public PhysicalButtonStateEvent onPressTransferEvent;

	protected float lastButtonPressTime;

	public virtual bool ToolIsReady
	{
		get
		{
			Tool component = GetComponent<Tool>();
			return component == null || !component.IsHeldByPlayer;
		}
	}

	protected bool OnPressCooldown => UnityEngine.Time.time - lastButtonPressTime <= instanceLimitDuration;

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(RemoveTrackedPlayer);
		this.UpdateAtRate(15f, delegate
		{
			UpdateColliders();
		});
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(RemoveTrackedPlayer);
	}

	private void UpdateColliders()
	{
		if (collisionTracker.UpdateColliders(out released))
		{
			PlayerReleasedButton(released[0]);
		}
	}

	public void LaserPress(PhotonPlayer player)
	{
		if (base.photonView != null)
		{
			base.photonView.RpcAll(RpcNonPhysicalPressButton, player);
		}
		else
		{
			RpcNonPhysicalPressButton(player);
		}
	}

	public void LaserRelease(PhotonPlayer player)
	{
		if (base.photonView != null)
		{
			base.photonView.RpcAll(RpcNonPhysicalReleaseButton, player);
		}
		else
		{
			RpcNonPhysicalReleaseButton(player);
		}
	}

	[PunRPC]
	public void RpcNonPhysicalPressButton(PhotonPlayer player)
	{
		NonPhysicalButtonPress(player);
	}

	[PunRPC]
	public void RpcNonPhysicalReleaseButton(PhotonPlayer player)
	{
		NonPhysicalButtonRelease(player);
	}

	public PhotonPlayer GetSomePressingPlayer()
	{
		Collider collider;
		return GetSomePressingPlayer(out collider);
	}

	public PhotonPlayer GetSomePressingPlayer(out Collider collider)
	{
		foreach (KeyValuePair<PhotonPlayer, List<Collider>> trackedCollider in collisionTracker.TrackedColliders)
		{
			if (trackedCollider.Value.Count > 0)
			{
				collider = trackedCollider.Value[trackedCollider.Value.Count - 1];
				return trackedCollider.Key;
			}
		}
		collider = null;
		return (nonPhysicalPressers.Count <= 0) ? null : nonPhysicalPressers[0];
	}

	public virtual int GetPressingPlayersCount()
	{
		return collisionTracker.CurrentlyInsideVolumeCount + nonPhysicalPressers.Count;
	}

	private void NonPhysicalButtonPress(PhotonPlayer player)
	{
		if (!nonPhysicalPressers.Contains(player))
		{
			int pressingPlayersCount = GetPressingPlayersCount();
			nonPhysicalPressers.Add(player);
			if (pressingPlayersCount == 0)
			{
				PlayerPushedButton(player);
			}
		}
	}

	private void NonPhysicalButtonRelease(PhotonPlayer player)
	{
		nonPhysicalPressers.Remove(player);
		PlayerReleasedButton(player);
	}

	protected virtual void PlayerPushedButton(PhotonPlayer pushingPlayer)
	{
		lastButtonPressTime = UnityEngine.Time.time;
		if (onButtonPressAudio != null)
		{
			AudioManager.Play3DSFX(onButtonPressAudio, base.transform.position);
		}
		pressEvent.Invoke(this, pushingPlayer?.ToPlayer());
	}

	protected virtual void OnTriggerEnter(Collider collider)
	{
		if (OnPressCooldown || !ToolIsReady)
		{
			return;
		}
		int pressingPlayersCount = GetPressingPlayersCount();
		if (collisionTracker.OnColliderEntered(collider, out var entered))
		{
			if (pressingPlayersCount == 0)
			{
				PlayerPushedButton(entered);
			}
			else if (onPressTransferEvent != null)
			{
				onPressTransferEvent.Invoke(ButtonState.Transferred, entered.ToPlayer());
			}
		}
	}

	protected virtual void OnTriggerExit(Collider other)
	{
		if (collisionTracker.OnColliderExited(other, out var exited))
		{
			PlayerReleasedButton(exited);
		}
	}

	protected virtual void PlayerReleasedButton(PhotonPlayer player)
	{
		if (GetPressingPlayersCount() == 0)
		{
			if (onReleaseEvent != null)
			{
				lastButtonPressTime = UnityEngine.Time.time;
				onReleaseEvent.Invoke(ButtonState.Released, player.ToPlayer());
			}
			return;
		}
		PhotonPlayer somePressingPlayer = GetSomePressingPlayer();
		if (somePressingPlayer != null)
		{
			if (onPressTransferEvent != null)
			{
				onPressTransferEvent.Invoke(ButtonState.Transferred, somePressingPlayer.ToPlayer());
			}
		}
		else if (onReleaseEvent != null)
		{
			lastButtonPressTime = UnityEngine.Time.time;
			onReleaseEvent.Invoke(ButtonState.Released, player.ToPlayer());
		}
	}

	private void RemoveTrackedPlayer(PhotonPlayer photonPlayer)
	{
		if (collisionTracker.RemoveTrackedColliderKey(photonPlayer))
		{
			PlayerReleasedButton(photonPlayer);
		}
		if (nonPhysicalPressers.Contains(photonPlayer))
		{
			NonPhysicalButtonRelease(photonPlayer);
		}
	}
}
public class SimplePhysicalButton : PhysicalButtonBase
{
	[SerializeField]
	private bool canPushWithTools = true;

	[SerializeField]
	private bool pushingToolsMustBeHeld = true;

	[SerializeField]
	private bool canOnlyPushLocally;

	[SerializeField]
	[FormerlySerializedAs("canOnlyBePushedByPlayer")]
	private bool canOnlyPushWhenPlayerExists = true;

	protected override void Awake()
	{
		base.Awake();
		collisionTracker = new PlayerButtonCollisionTracker(canOnlyPushLocally, canPushWithTools, pushingToolsMustBeHeld);
	}

	protected override void OnTriggerEnter(Collider collider)
	{
		if (!base.OnPressCooldown)
		{
			if (!canOnlyPushWhenPlayerExists)
			{
				PlayerPushedButton(null);
			}
			else
			{
				base.OnTriggerEnter(collider);
			}
		}
	}
}
public class Card : Photon.MonoBehaviour
{
	[SerializeField]
	private Text text;

	[SerializeField]
	private string hiddenWordString = "No Peeking!";

	[SerializeField]
	private GameObject aprilFoolsText;

	private SynchronizedField<string> _word;

	private bool _wordHidden;

	public Tool Tool { get; private set; }

	public string Word
	{
		get
		{
			return _word.Get();
		}
		set
		{
			_word.Set(value);
		}
	}

	public bool WordHidden
	{
		get
		{
			return _wordHidden;
		}
		set
		{
			_wordHidden = value;
			UpdateUIText();
		}
	}

	private void OnWordChange()
	{
		UpdateUIText();
	}

	private void UpdateUIText()
	{
		if (WordHidden)
		{
			text.text = hiddenWordString;
		}
		else
		{
			text.text = Word;
		}
		if (aprilFoolsText != null)
		{
			aprilFoolsText.SetActive(value: false);
		}
	}

	protected override void Awake()
	{
