		Tool = GetComponent<Tool>();
		if (Tool != null)
		{
			Tool.KinematicOnReset = true;
			Tool.PostResetEvent += OnReset;
		}
		ToolCleanup component = GetComponent<ToolCleanup>();
		if (component != null)
		{
			component.enabled = false;
		}
