	private void Start()
	{
		if (Tool != null)
		{
			Tool.SetCollisionLayer(Layers.DynamicPhysicsIgnoreDynamicPhysics);
		}
		UpdateUIText();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostResetEvent -= OnReset;
		}
	}

	private void OnReset(Tool thisTool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		Tool.SetCollisionLayer(Layers.DynamicPhysicsIgnoreDynamicPhysics);
	}

	public void ShowAprilFoolsText()
	{
		if (aprilFoolsText != null)
		{
			aprilFoolsText.SetActive(value: true);
		}
	}
}
public class CardBox : Photon.MonoBehaviour
{
	[Header("Card Spawning")]
	[SerializeField]
	private Transform cardSpawnRoot;

	[SerializeField]
	private float cardRespawnDuration = 0.5f;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip dispenseCard;

	private static readonly CharadesWord DEFAULT_WORD = new CharadesWord("RecRoom");

	private Coroutine showAprilFoolsText;

	private List<CharadesWord> words = new List<CharadesWord>();

	private SynchronizedField<float> _lastCardDespawnTime;

	private SynchronizedField<bool> _dirty;

	private SynchronizedField<int> _currentCardIndex;

	private SynchronizedField<int> _previousCardIndex;

	private SynchronizedField<string> _currentWord;

	private SynchronizedField<int> _currentWordDifficulty;

	private SynchronizedField<string> _previousWord;

	public List<Card> Cards { get; private set; }

	private bool dirty
	{
		get
		{
			return _dirty.Get();
		}
		set
		{
			_dirty.Set(value);
		}
	}

	private float lastDirtyTime
	{
		get
		{
			return _lastCardDespawnTime.Get();
		}
		set
		{
			_lastCardDespawnTime.Set(value);
		}
	}

	private int currentCardIndex
	{
		get
		{
			return _currentCardIndex.Get();
		}
		set
		{
			_currentCardIndex.Set(value);
		}
	}

	private int previousCardIndex
	{
		get
		{
			return _previousCardIndex.Get();
		}
		set
		{
			_previousCardIndex.Set(value);
		}
	}

	private Card previousCard => Cards[previousCardIndex];

	private Card currentCard => Cards[currentCardIndex];

	public string CurrentWord
	{
		get
		{
			return _currentWord.Get();
		}
		set
		{
			_currentWord.Set(value);
		}
	}

	public CharadesWord.CharadesWordsDifficulty CurrentWordDifficulty
	{
		get
		{
			return (CharadesWord.CharadesWordsDifficulty)_currentWordDifficulty.Get();
		}
		set
		{
			_currentWordDifficulty.Set((int)value);
		}
	}

	public string PreviousWord
	{
		get
		{
			return _previousWord.Get();
		}
		set
		{
			_previousWord.Set(value);
		}
	}

	private int currentWordIndex { get; set; }

	private int previousWordIndex { get; set; }

	public void UpdateLocalPlayerCardVisibility(bool isVisible)
	{
		if (previousCard != null)
		{
			previousCard.WordHidden = !isVisible;
		}
		if (currentCard != null)
		{
			currentCard.WordHidden = !isVisible;
		}
	}

	public void MasterClearCards()
	{
		if (!PhotonNetwork.isMasterClient)
		{
			return;
		}
		currentCardIndex = 1;
		previousCardIndex = 0;
		if (Cards != null)
		{
			for (int i = 0; i < Cards.Count; i++)
			{
				Cards[i].Tool.Disable();
			}
		}
		dirty = true;
		lastDirtyTime = (float)PhotonNetwork.time;
	}

	private void IncrementWordIndices()
	{
		previousWordIndex = currentWordIndex;
		currentWordIndex++;
		if (currentWordIndex >= words.Count)
		{
			ShuffleWords();
			currentWordIndex = 0;
		}
	}

	private void ShuffleWords()
	{
		words.Shuffle();
	}

	private void UpdateCurrentWord()
	{
		PreviousWord = CurrentWord;
		CurrentWord = ((words.Count <= 0) ? DEFAULT_WORD.EN_US : words[currentWordIndex].EN_US);
		CurrentWordDifficulty = ((words.Count > 0) ? words[currentWordIndex].Difficulty : CharadesWord.CharadesWordsDifficulty.Easy);
	}

	protected override void Awake()
	{
		base.Awake();
		_dirty = new SynchronizedField<bool>(this, "DIRTY", defaultValue: true, SetterPermissionMode.ANYONE);
		_lastCardDespawnTime = new SynchronizedField<float>(this, "LAST_CARD_DESPAWN_TIME", -1f, SetterPermissionMode.ANYONE);
		_currentCardIndex = new SynchronizedField<int>(this, "CURRENT_CARD_INDEX", 0, SetterPermissionMode.ANYONE);
		_previousCardIndex = new SynchronizedField<int>(this, "PREVIOUS_CARD_INDEX", 0, SetterPermissionMode.ANYONE);
		_currentWord = new SynchronizedField<string>(this, "CURRENT_WORD", DEFAULT_WORD.EN_US, SetterPermissionMode.MASTER);
		_currentWordDifficulty = new SynchronizedField<int>(this, "CURRENT_WORD_DIFFICULTY", 0, SetterPermissionMode.MASTER);
		_previousWord = new SynchronizedField<string>(this, "PREVIOUS_WORD", DEFAULT_WORD.EN_US, SetterPermissionMode.MASTER);
		currentWordIndex = 0;
		Cards = this.FindAllObjectsOfType<Card>();
	}

	private void Start()
	{
		GetWordsAsync().Then(delegate(List<CharadesWord> downloadedWords)
		{
			List<CharadesWord> list = new List<CharadesWord>(downloadedWords);
			SetWords(list);
			MasterClearCards();
		});
	}

	private IPromise<List<CharadesWord>> GetWordsAsync()
	{
		return Cache.GetList<CharadesWord>("api/activities/charades/v1/words", TimeSpan.MaxValue, executeSerially: false).Error(delegate(string error)
		{
			UnityEngine.Debug.LogErrorFormat("Failed to retrive Charades words: {0}", error);
		});
	}

	private void SetWords(List<CharadesWord> charadeswords)
	{
		words = charadeswords;
		UnityEngine.Debug.Log("Found " + words.Count + " words");
		ShuffleWords();
		for (int i = 0; i < Cards.Count; i++)
		{
			Cards[i].Tool.PostPickupEvent += OnToolPickup;
		}
		if (PhotonNetwork.isMasterClient && Cards.Count <= 1)
		{
			UnityEngine.Debug.LogError("Not enough cards in the scene to double buffer cards.");
		}
		UpdateCurrentWord();
	}

	private void Update()
	{
		if (PhotonNetwork.isMasterClient && Cards != null && dirty && (float)PhotonNetwork.time - lastDirtyTime >= cardRespawnDuration)
		{
			int num = currentCardIndex;
			currentCardIndex = previousCardIndex;
			previousCardIndex = num;
			currentCard.Tool.MasterResetToDefault(cardSpawnRoot.position, cardSpawnRoot.rotation);
			IncrementWordIndices();
			UpdateCurrentWord();
			currentCard.Word = CurrentWord;
			dirty = false;
		}
	}

	private void OnToolPickup(Tool tool)
	{
		Card component = tool.GetComponent<Card>();
		if (tool.hasAuthority && component != null)
		{
			base.photonView.RpcMaster(RpcMasterRequestCardPickup, component);
		}
	}

	private void MasterRequestCardPickup(Card card)
	{
		if (PhotonNetwork.isMasterClient && card == currentCard)
		{
			if (showAprilFoolsText != null)
			{
				StopCoroutine(showAprilFoolsText);
				showAprilFoolsText = null;
			}
			previousCard.Tool.Disable();
			if (!dirty)
			{
				dirty = true;
				lastDirtyTime = (float)PhotonNetwork.time;
			}
			UpdateCurrentWord();
			base.photonView.RpcAll(RpcOnCardPickup);
		}
	}

	[PunRPC]
	private void RpcMasterRequestCardPickup(Card card)
	{
		if (card != null)
		{
			MasterRequestCardPickup(card);
		}
	}

	[PunRPC]
	private void RpcOnCardPickup()
	{
		AudioManager.Play3DSFX(dispenseCard, base.transform);
	}
}
