	protected override void Awake()
	{
		base.Awake();
		throwerId = new SynchronizedField<int>(this, "THROWER_ID", PhotonPlayer.Invalid, SetterPermissionMode.AUTHORITY);
		_checkpointId = new SynchronizedField<int>(this, "CHECKPOINT_ID", -1, SetterPermissionMode.AUTHORITY);
		_lastPickupPosition = new SynchronizedField<Vector3>(this, "LAST_PICKUP_POS", Vector3.zero, SetterPermissionMode.AUTHORITY, OnLastPickupPositionChanged);
		_hazarded = new SynchronizedField<bool>(this, "HAZARDED", defaultValue: false, SetterPermissionMode.AUTHORITY);
		_consecutiveCatches = new SynchronizedField<int>(this, "CATCHES", 0, SetterPermissionMode.AUTHORITY, OnConsecutiveCatchesChanged);
		teamColor = GetComponent<TeamColorRenderer>();
		discTrails = GetComponentsInChildren<DiscGolfDiscTrail>(includeInactive: true);
		Tool.PostPickupEvent += OnPostPickup;
		Tool.PostReleaseEvent += OnPostRelease;
		Tool.PostResetEvent += OnReset;
		Tool.CustomAuthorityResetOnKillzoneBehavior = AuthorityResetOnKillzoneBehavior;
		TrailEnabled = false;
	}

	private void Start()
	{
		UpdateTeamColor();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostPickupEvent -= OnPostPickup;
			Tool.PostReleaseEvent -= OnPostRelease;
			Tool.PostResetEvent -= OnReset;
		}
	}

	private void FixedUpdate()
	{
		bool flag = false;
		bool flag2 = Tool.RigidbodyEx.IsSleeping();
		if (!flag2 && !Tool.IsHeld)
		{
			float magnitude = Tool.RigidbodyEx.angularVelocity.magnitude;
			Vector3 force = GetLiftAcceleration(magnitude) * Tool.RigidbodyEx.mass;
			if (force.sqrMagnitude > 0.0001f)
			{
				Tool.RigidbodyEx.AddForce(force);
				Tool.RigidbodyEx.AddForce(CurveForce);
				float num = Mathf.Clamp01(magnitude / MaxAngularVelocity) * Vector3.Dot(Vector3.up, base.transform.up) * Tool.RigidbodyEx.mass * angularStabilityModifier;
				Vector3 lhs = Quaternion.AngleAxis(num * magnitude * 57.29578f * angularStabilityPercent / angularStabilitySpeed, Tool.RigidbodyEx.angularVelocity) * base.transform.up;
				float z = Mathf.Clamp(DifferenceZ / (curveScaleFactor / 1000f) / 5f, -30f, 30f);
				Vector3 vector = Vector3.ProjectOnPlane(Tool.RigidbodyEx.velocity, Vector3.up);
				if (vector == Vector3.zero)
				{
					vector = Vector3.forward;
				}
				Vector3 rhs = Quaternion.LookRotation(vector) * Quaternion.Euler(0f, 0f, z) * Vector3.up;
				Vector3 vector2 = Vector3.Cross(lhs, rhs);
				Tool.RigidbodyEx.AddTorque(vector2 * angularStabilitySpeed * angularStabilitySpeed * num);
			}
			flag = magnitude < 0.1f && Tool.RigidbodyEx.velocity.magnitude < 0.01f;
			if (recordingTelemetry)
			{
				UpdateTelemetry();
			}
		}
		if (flag2)
		{
			flag = true;
		}
		bool flag3 = !flag2;
		if (wasMoving && !flag3 && base.hasAuthority && Thrower != null && this.DiscStopMovingEvent != null)
		{
			this.DiscStopMovingEvent(this, Thrower);
		}
		wasMoving = flag3;
		if (!(beamRenderer != null))
		{
			return;
		}
		if (BeamEnabled)
		{
			if (!wasShowBeam && flag)
			{
				showBeamTime = UnityEngine.Time.time;
			}
			if (flag && UnityEngine.Time.time - showBeamTime > 0.5f)
			{
				beamRenderer.gameObject.SetActive(value: true);
				beamRenderer.transform.position = base.transform.position;
				beamRenderer.transform.rotation = Quaternion.LookRotation(Vector3.forward) * Quaternion.Euler(beamRotationOffset);
			}
			else
			{
				beamRenderer.gameObject.SetActive(value: false);
			}
			wasShowBeam = flag;
		}
		else
		{
			beamRenderer.gameObject.SetActive(value: false);
			wasShowBeam = false;
		}
	}

	private void OnReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		if (base.hasAuthority)
		{
			Thrower = null;
			ConsecutiveCatches = 0;
		}
		TrailEnabled = false;
		if (this.DiscResetEvent != null)
		{
			this.DiscResetEvent(this, resetPosition, resetRotation);
		}
	}

	public void UpdateTeamColor()
	{
		if (Team == GameTeam.ANY || !(teamColor != null))
		{
			return;
		}
		teamColor.Team = Team;
		beamRenderer.material.SetColor("_TintColor", teamColor.Color);
		if (Tool != null && (Tool.SkinMapper == null || !Tool.SkinMapper.HasActiveSkin))
		{
			DiscGolfDiscTrail[] array = discTrails;
			foreach (DiscGolfDiscTrail discGolfDiscTrail in array)
			{
				discGolfDiscTrail.Color = teamColor.Color;
			}
		}
	}

	private void OnPostPickup(Tool tool)
	{
		PhotonPlayer thrower = Thrower;
		if (base.hasAuthority)
		{
			if (tool.HolderPlayer != null && thrower != null && tool.HolderPlayer.PhotonPlayer != thrower)
			{
				ConsecutiveCatches++;
			}
			else
			{
				ConsecutiveCatches = 0;
			}
			Thrower = null;
			Hazarded = false;
			SyncedLastPickupPosition = base.transform.position;
		}
		TrailEnabled = false;
		if (this.DiscPickupEvent != null)
		{
			this.DiscPickupEvent(this, tool.HolderPlayer.PhotonPlayer, thrower);
		}
	}

	private void OnPostRelease(Tool tool)
	{
		float time = Mathf.Clamp01(tool.RigidbodyEx.velocity.magnitude / MaxVelocity);
		float num = ThrowAssistCurve.Evaluate(time) * ThrowAssistMultiplier;
		tool.RigidbodyEx.velocity *= num;
		if (Mathf.Abs(tool.RigidbodyEx.angularVelocity.y) >= minAngularVelocityForLift)
		{
			float magnitude = Vector3.ProjectOnPlane(tool.RigidbodyEx.velocity, Vector3.up).magnitude;
			tool.RigidbodyEx.angularVelocity = base.transform.up * linearToAngularVelocity.EvaluateNonNormalized(magnitude);
		}
		Vector3 normalized = tool.RigidbodyEx.velocity.normalized;
		Vector3 up = base.transform.up;
		Vector3 lhs = Vector3.Cross(normalized, up);
		up = Vector3.Cross(lhs, normalized);
		Vector3 vector = -Physics.gravity;
		vector = Vector3.ProjectOnPlane(vector, normalized);
		float num2 = up.AngleSignedVector3(vector, normalized);
		for (DifferenceZ = 0f - num2; DifferenceZ < -180f; DifferenceZ += 360f)
		{
		}
		while (DifferenceZ > 180f)
		{
			DifferenceZ -= 360f;
		}
		float num3 = 5f;
		if (Mathf.Abs(DifferenceZ) < num3)
		{
			DifferenceZ = 0f;
		}
		else
		{
			DifferenceZ *= curveScaleFactor / 1000f;
		}
		if (tool.HolderHand != null)
		{
			tool.HolderHand.Vibrate(100);
		}
		if (calculatesTelemetry)
		{
			currentThrowInitVel = tool.RigidbodyEx.velocity;
			LastThrowInitialSpeed = currentThrowInitVel.magnitude;
			if (LastThrowInitialSpeed > MaxThrowInitialSpeed)
			{
				MaxThrowInitialSpeed = LastThrowInitialSpeed;
			}
			currentThrowInitPos = base.transform.position;
			recordingTelemetry = true;
		}
		if (base.hasAuthority)
		{
			Thrower = ((!(tool.HolderView != null)) ? null : tool.HolderView.owner);
		}
		TrailEnabled = true;
		LastReleasePosition = base.transform.position;
		if (this.DiscThrowEvent != null)
		{
			this.DiscThrowEvent(this, tool.HolderPlayer.PhotonPlayer);
		}
	}

	private void OnLastPickupPositionChanged()
	{
		Tool.LastWorldSpacePickupPosition = SyncedLastPickupPosition;
		Tool.LastWorldSpacePickupRotation = Quaternion.identity;
	}

	private void OnConsecutiveCatchesChanged()
	{
		if (ConsecutiveCatches > 0 && (NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || !NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning) && !GameManager.IsSandboxActive)
		{
			Vector3 vector = Vector3.up * 0.35f;
			WorldSpaceNotification.PlayNext("Catch! " + ConsecutiveCatches, 3f, null, followPlayer: false, base.transform.position + vector);
		}
	}

	public Vector3 GetLiftAcceleration(float angularSpeed)
	{
		float num = Mathf.Clamp01(angularSpeed / MaxAngularVelocity);
		float num2 = Vector3.Dot(Vector3.up, base.transform.up);
		float num3 = num2 * num;
		return -Physics.gravity * num3 * AirLiftModifier;
	}

	private void UpdateTelemetry()
	{
		if (base.transform.position.y - currentThrowInitPos.y > currentThrowMaxHeight)
		{
			currentThrowMaxHeight = base.transform.position.y - currentThrowInitPos.y;
		}
		float sqrMagnitude = Tool.RigidbodyEx.velocity.sqrMagnitude;
		if (sqrMagnitude > currentThrowMaxSqrSpeed)
		{
			currentThrowMaxSqrSpeed = sqrMagnitude;
		}
	}

	private void CalculateThrowTelemetry()
	{
		recordingTelemetry = false;
		LastThrowDistance = (base.transform.position - currentThrowInitPos).magnitude;
		LastThrowMaxHeight = currentThrowMaxHeight;
		LastThrowMaxSpeed = currentThrowMaxHeight;
		Vector3 vector = Vector3.Project(base.transform.position - currentThrowInitPos, currentThrowInitVel.normalized);
		LastThrowMaxCurveDeviation = (base.transform.position - (currentThrowInitPos + vector)).magnitude;
		if (LastThrowDistance > MaxThrowDistance)
		{
			MaxThrowDistance = LastThrowDistance;
		}
		if (LastThrowMaxHeight > MaxThrowHeight)
		{
			MaxThrowHeight = LastThrowMaxHeight;
		}
		if (LastThrowMaxSpeed > MaxThrowSpeed)
		{
			MaxThrowSpeed = LastThrowMaxSpeed;
		}
		if (LastThrowInitialSpeed > MaxThrowInitialSpeed)
		{
			MaxThrowInitialSpeed = LastThrowInitialSpeed;
		}
		if (LastThrowMaxCurveDeviation > MaxThrowCurveDeviation)
		{
			MaxThrowCurveDeviation = LastThrowMaxCurveDeviation;
		}
	}

	private void OnCollisionEnter(Collision collision)
	{
		CalculateThrowTelemetry();
		if (Thrower == null)
		{
			return;
		}
		PhotonView colliderPhotonView = collision.GetColliderPhotonView();
		DiscGolfGoal discGolfGoal = ((!(colliderPhotonView != null)) ? null : colliderPhotonView.GetComponent<DiscGolfGoal>());
		if (discGolfGoal != null)
		{
			if (this.DiscScoreEvent != null)
			{
				this.DiscScoreEvent(this, discGolfGoal, Thrower);
			}
			return;
		}
		if (base.hasAuthority)
		{
			if (CalculateConsecutiveCatchesCoroutine != null)
			{
				StopCoroutine(CalculateConsecutiveCatchesCoroutine);
			}
			CalculateConsecutiveCatchesCoroutine = StartCoroutine(RunCalculateConsecutiveCatches(collision.collider));
		}
		if (this.CollidedWithSolid != null)
		{
			this.CollidedWithSolid(this, collision.collider, Thrower);
		}
	}

	private IEnumerator RunCalculateConsecutiveCatches(Collider hitCollider)
	{
		yield return new WaitForSeconds(0.5f);
		if ((double)Tool.RigidbodyEx.velocity.sqrMagnitude < 0.05 || CollisionDetection.CanPlayerStandOnCollider(hitCollider))
		{
			ConsecutiveCatches = -1;
			DiscGolfDiscTrail[] array = discTrails;
			foreach (DiscGolfDiscTrail discGolfDiscTrail in array)
			{
				discGolfDiscTrail.StartTrailFade();
			}
		}
	}

	private bool AuthorityResetOnKillzoneBehavior(Tool thisTool, Killzone killzone)
	{
		if (SessionManager.InDiscGolf && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			if (Thrower != null && this.DiscHazardEvent != null)
			{
				this.DiscHazardEvent(this, killzone, Thrower);
			}
			return true;
		}
		return false;
	}
}
public abstract class DrawingBase : Photon.MonoBehaviour
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private Tool tool;

	[Header("Brush Properties")]
	[SerializeField]
	private DrawingSurface.DrawingSurfaceType _drawingSurfaceType;

	[SerializeField]
	private Transform _brushTip;

	[SerializeField]
	protected float maxDrawingOffset = 0.1f;

	[SerializeField]
	protected float minControlPointDistance = 0.001f;

	[SerializeField]
	private AnimationCurve vibrationCurve = AnimationCurve.Linear(0f, 1f, 1f, 1f);

	[SerializeField]
	private float minVelocityForVibrate = 0.001f;

	[SerializeField]
	private Material _drawingMaterial;

	private Material drawingMaterialInstance;

	private Vector2 lastPosition = Vector2.zero;

	private Vector2 planePos = Vector2.zero;

	private Vector2 normalizedPlanePos = Vector2.zero;

	protected float distanceToPlane = float.MaxValue;

	private TimestampedRollingBufferVector3 velocityBuffer = new TimestampedRollingBufferVector3();

	private bool _isDrawing;

	private float timeSinceLastPulse = float.MaxValue;

	private float pulseInterval;

	[SerializeField]
	private float soundVelocityThreshold;

	[SerializeField]
	private RecRoomAudioClip brushDownClip;

	[SerializeField]
	private RecRoomAudioClip brushLoopClip;

	private SFXAudioSource loopingSource;

	public Tool Tool => tool;

	public DrawingSurface CurrentSurface { get; set; }

	public DrawingSurface.DrawingSurfaceType DrawingSurfaceType => _drawingSurfaceType;

	public Transform BrushTip => _brushTip;

	public Material DrawingMaterial
	{
		get
		{
			if (drawingMaterialInstance == null)
			{
				drawingMaterialInstance = UnityEngine.Object.Instantiate(_drawingMaterial);
			}
			return drawingMaterialInstance;
		}
	}

	public Vector2 Velocity { get; private set; }

	public Vector2 OnPlanePos => planePos;

	public Vector2 NormalizedPlanePos => normalizedPlanePos;

	public bool IsDrawing
	{
		get
		{
			return _isDrawing;
		}
		set
		{
			if (_isDrawing != value)
			{
				_isDrawing = value;
				if (_isDrawing)
				{
					PenDown();
				}
				else
				{
					PenUp();
				}
			}
		}
	}

	protected override void Awake()
	{
		base.Awake();
		Tool.PostReleaseEvent += OnPostRelease;
	}

	protected virtual void Update()
	{
		bool isDrawing = false;
		if (CurrentSurface != null && CurrentSurface.IsOverPlane(BrushTip.transform.position, out planePos, out distanceToPlane))
		{
			normalizedPlanePos = CurrentSurface.NormalizedBoardSpace(planePos);
			if (distanceToPlane < maxDrawingOffset)
			{
				Vector2 vector = planePos - lastPosition;
				velocityBuffer.Add(UnityEngine.Time.time, vector);
				Vector3 value = vector;
				if (velocityBuffer.TryGetAverageValueOverTime(UnityEngine.Time.time - 0.1f, UnityEngine.Time.time, out value))
				{
					Velocity = value;
				}
				lastPosition = planePos;
				isDrawing = true;
				AuthorityAddControlPoint(CurrentSurface);
			}
		}
		IsDrawing = isDrawing;
		VibrationUpdate();
		SoundUpdate();
	}

	protected abstract void AuthorityAddControlPoint(DrawingSurface currentSurface);

	protected abstract void AuthorityFinishStroke();

	private void VibrationUpdate()
	{
		if (!isLocal || !IsDrawing)
		{
			return;
		}
		pulseInterval = ((!(Velocity.magnitude > minVelocityForVibrate)) ? float.MaxValue : vibrationCurve.Evaluate(Velocity.magnitude));
		if (timeSinceLastPulse >= pulseInterval)
		{
			if (Tool != null && Tool.HolderHand != null)
			{
				Tool.HolderHand.Vibrate(1, 0.5f);
			}
			timeSinceLastPulse = 0f;
		}
		timeSinceLastPulse += UnityEngine.Time.deltaTime;
	}

	public void PenDown()
	{
		if (brushDownClip != null)
		{
			AudioManager.Play3DSFX(brushDownClip, base.transform);
		}
		if (isLocal && Tool != null && Tool.HolderHand != null)
		{
			Tool.HolderHand.Vibrate();
		}
	}

	public void PenUp()
	{
		if (isLocal && Tool != null && Tool.HolderHand != null)
		{
			Tool.HolderHand.Vibrate();
		}
	}

	protected virtual void SoundUpdate()
	{
		if (brushLoopClip == null || !(brushLoopClip.audioClip != null))
		{
			return;
		}
		if (IsDrawing && Velocity.magnitude > soundVelocityThreshold)
		{
			if (loopingSource == null)
			{
				loopingSource = AudioManager.Play3DSFX(brushLoopClip, base.transform);
				loopingSource.Loop();
			}
		}
		else if (loopingSource != null)
		{
			loopingSource.Stop();
			loopingSource = null;
		}
	}

	private void OnPostRelease(Tool tool)
	{
		PenUp();
	}
}
public abstract class DrawingBase<ControlPointType> : DrawingBase where ControlPointType : class, IDrawingControlPoint<ControlPointType>
{
	protected Stroke<ControlPointType> currentStroke;

	protected override void Update()
	{
		base.Update();
		if (!base.IsDrawing && currentStroke != null)
		{
			AuthorityFinishStroke();
		}
	}

	protected Stroke<ControlPointType> CreateNewStroke(DrawingSurface drawingSurface, ControlPointType firstControlPoint, bool localPlayerIsDrawing)
	{
		return drawingSurface.CreateStroke(firstControlPoint, base.DrawingMaterial, localPlayerIsDrawing);
	}

	protected abstract ControlPointType CreateNewControlPoint();

	public void AddControlPoint(DrawingSurface surface, ControlPointType newCP, long drawingPlayerPhotonId)
	{
		if (currentStroke == null)
		{
			bool localPlayerIsDrawing = drawingPlayerPhotonId == PhotonNetwork.player.ID;
			currentStroke = CreateNewStroke(surface, newCP, localPlayerIsDrawing);
		}
		else
		{
			currentStroke.AddControlPoint(newCP);
		}
	}

	public void FinishStroke()
	{
		if (currentStroke != null)
		{
			currentStroke.Finished = true;
		}
		currentStroke = null;
	}

	protected override void AuthorityAddControlPoint(DrawingSurface surface)
	{
		if (!base.hasAuthority || base.CurrentSurface.WaitingForDownload)
		{
			return;
		}
		if (currentStroke != null && currentStroke.LastControlPoint != null)
		{
			Vector2 a = base.NormalizedPlanePos;
			ControlPointType lastControlPoint = currentStroke.LastControlPoint;
			if (!(Vector2.Distance(a, lastControlPoint.Position) > minControlPointDistance))
			{
				return;
			}
		}
		ControlPointType val = CreateNewControlPoint();
		int num = ((!(base.Tool.HolderPlayer != null) || base.Tool.HolderPlayer.PhotonPlayer == null) ? PhotonPlayer.Invalid : base.Tool.HolderPlayer.PhotonPlayer.ID);
		if (!Profiles.LocalProfile.IsJunior())
		{
			base.photonView.RpcAll(RpcAddControlPoint, surface, val, num);
		}
		else
		{
			AddControlPoint(surface, val, num);
		}
	}

	protected override void AuthorityFinishStroke()
	{
		if (base.hasAuthority)
		{
			if (!Profiles.LocalProfile.IsJunior())
			{
				base.photonView.RpcAll(RpcFinishStroke);
			}
			else
			{
				FinishStroke();
			}
		}
	}

	[PunRPC]
	protected void RpcAddControlPoint(DrawingSurface surface, ControlPointType controlPoint, int drawingPlayerPhotonId)
	{
		AddControlPoint(surface, controlPoint, drawingPlayerPhotonId);
	}

	[PunRPC]
	protected void RpcFinishStroke()
	{
		FinishStroke();
	}
}
public interface IStroke
{
	Material Material { get; }

	bool Finished { get; set; }

	bool MeshNeedsRebuild { get; }

	void UpdateMesh(MeshFilter meshFilter);

	void MarkRendered();
}
public class Stroke<ControlPointType> : IStroke where ControlPointType : class, IDrawingControlPoint<ControlPointType>
{
	public readonly List<ControlPointType> controlPoints = new List<ControlPointType>();

	public readonly List<ControlPointType> toRemove = new List<ControlPointType>();

	public readonly List<Vector3> Vertices = new List<Vector3>();

	public readonly List<Vector2> UVs = new List<Vector2>();

	public readonly List<int> Tris = new List<int>();

	public readonly Material material;

	public Material Material => material;

	public ControlPointType LastControlPoint { get; protected set; }

	public bool Finished { get; set; }

	public bool MeshNeedsRebuild { get; private set; }

	public Stroke(ControlPointType startPoint, Material material)
	{
		this.material = material;
		AddControlPoint(startPoint);
	}

	public void AddControlPoint(ControlPointType newPoint)
	{
		controlPoints.Add(newPoint);
		LastControlPoint = newPoint;
		MeshNeedsRebuild = true;
	}

	public void MarkRendered()
	{
		for (int i = 0; i < controlPoints.Count; i++)
		{
			ControlPointType val = controlPoints[i];
			val.Rendered = true;
		}
	}

	public void UpdateMesh(MeshFilter meshFilter)
	{
		Mesh mesh = meshFilter.mesh;
		mesh.Clear();
		Vertices.Clear();
		UVs.Clear();
		Tris.Clear();
		toRemove.Clear();
		for (int i = 0; i < controlPoints.Count; i++)
		{
			ControlPointType val = controlPoints[i];
			if (i == 0)
			{
				List<Vector3> vertices = Vertices;
				List<Vector2> uVs = UVs;
				List<int> tris = Tris;
				val.Stamp(vertices, uVs, tris);
			}
			else
			{
				ControlPointType val2 = controlPoints[i - 1];
				int index = i;
				List<Vector3> vertices2 = Vertices;
				List<Vector2> uVs2 = UVs;
				List<int> tris2 = Tris;
				val.UpdateForControlPoint(val2, index, vertices2, uVs2, tris2);
				toRemove.Add(val2);
			}
		}
		for (int j = 0; j < toRemove.Count; j++)
		{
			controlPoints.Remove(toRemove[j]);
		}
		mesh.vertices = Vertices.ToArray();
		mesh.uv = UVs.ToArray();
		mesh.triangles = Tris.ToArray();
		MeshNeedsRebuild = false;
	}
}
public interface IDrawingControlPoint<ControlPointType> where ControlPointType : class, IDrawingControlPoint<ControlPointType>
{
	Vector2 Position { get; }

	bool Rendered { get; set; }

	void Stamp(List<Vector3> Vertices, List<Vector2> UVs, List<int> Tris);

	void UpdateForControlPoint(ControlPointType lastPoint, int index, List<Vector3> Vertices, List<Vector2> UVs, List<int> Tris);
}
public class QuadControlPoint : IDrawingControlPoint<QuadControlPoint>
{
	private static readonly int[] indices = new int[4] { 0, 1, 2, 3 };

	private readonly Vector3 center = Vector3.zero;

	private readonly Vector3 tr = Vector3.zero;

	private readonly Vector3 tl = Vector3.zero;

	private readonly Vector3 bl = Vector3.zero;

	private readonly Vector3 br = Vector3.zero;

	private Vector3[] allPoints;

	private Vector3 surfaceNormal;

	private const int byteSize = 40;

	public static readonly byte[] memVector2 = new byte[40];

	public Vector2 Position => center;

	public bool Rendered { get; set; }

	public QuadControlPoint(Vector3 center, Vector3 tr, Vector3 tl, Vector3 bl, Vector3 br)
	{
		this.center = center;
		this.tr = tr;
		this.tl = tl;
		this.bl = bl;
		this.br = br;
		Vector3 normalized = Vector3.Cross(tr - tl, tr - br).normalized;
		surfaceNormal = normalized;
		allPoints = new Vector3[4] { tr, tl, bl, br };
	}

	public void AddVertsAndUVs(List<Vector3> verts, List<Vector2> uvs)
	{
		verts.Add(tr);
		verts.Add(tl);
		verts.Add(bl);
		verts.Add(br);
		Vector2 item = Vector3.one;
		uvs.Add(item);
		item.x = 0f;
		uvs.Add(item);
		item.y = 0f;
		uvs.Add(item);
		item.x = 1f;
		uvs.Add(item);
	}

	public void AddTris(List<int> tris, int startIndex)
	{
		tris.Add(startIndex + 1);
		tris.Add(startIndex + 2);
		tris.Add(startIndex);
		tris.Add(startIndex + 2);
		tris.Add(startIndex + 3);
		tris.Add(startIndex);
	}

	public void AddInitialQuad(List<Vector3> verts, List<Vector2> uvs, List<int> tris)
	{
		AddVertsAndUVs(verts, uvs);
		AddTris(tris, 0);
	}

	public List<int> EdgeVerts(QuadControlPoint other, bool trailing = false)
	{
		List<int> list = new List<int>(indices);
		float[] xDist = new float[4];
		float[] yDist = new float[4];
		Vector3 vector = other.center - center;
		Vector3 vector2 = Vector3.Lerp(center, other.center, 0.5f);
		Vector3 normalized = vector.normalized;
		Vector3 onNormal = Vector3.Cross(normalized, surfaceNormal);
		for (int i = 0; i < allPoints.Length; i++)
		{
			Vector3 vector3 = allPoints[i] - vector2;
			Vector3 rhs = Vector3.Project(vector3, onNormal);
			Vector3 lhs = Vector3.Cross(normalized, rhs);
			float num = Mathf.Sign(Vector3.Dot(lhs, surfaceNormal));
			xDist[i] = rhs.magnitude * num;
			Vector3 vector4 = Vector3.Project(vector2 - allPoints[i], normalized);
			yDist[i] = vector4.magnitude;
		}
		list.Sort((int a, int b) => yDist[a].CompareTo(yDist[b]));
		List<int> range = list.GetRange(0, 3);
		range.Sort(delegate(int a, int b)
		{
			float value = xDist[a];
			float value2 = xDist[b];
			return (!trailing) ? value.CompareTo(value2) : value2.CompareTo(value);
		});
		return range;
	}

	public static short Serialize(StreamBuffer outStream, object customobject)
	{
		QuadControlPoint quadControlPoint = (QuadControlPoint)customobject;
		lock (memVector2)
		{
			byte[] array = memVector2;
			int targetOffset = 0;
			Vector3 vector = quadControlPoint.center;
			Protocol.Serialize(vector.x, array, ref targetOffset);
			Vector3 vector2 = quadControlPoint.center;
			Protocol.Serialize(vector2.y, array, ref targetOffset);
			Vector3 vector3 = quadControlPoint.tr;
			Protocol.Serialize(vector3.x, array, ref targetOffset);
			Vector3 vector4 = quadControlPoint.tr;
			Protocol.Serialize(vector4.y, array, ref targetOffset);
			Vector3 vector5 = quadControlPoint.tl;
			Protocol.Serialize(vector5.x, array, ref targetOffset);
			Vector3 vector6 = quadControlPoint.tl;
			Protocol.Serialize(vector6.y, array, ref targetOffset);
			Vector3 vector7 = quadControlPoint.bl;
			Protocol.Serialize(vector7.x, array, ref targetOffset);
			Vector3 vector8 = quadControlPoint.bl;
			Protocol.Serialize(vector8.y, array, ref targetOffset);
			Vector3 vector9 = quadControlPoint.br;
			Protocol.Serialize(vector9.x, array, ref targetOffset);
			Vector3 vector10 = quadControlPoint.br;
			Protocol.Serialize(vector10.y, array, ref targetOffset);
			outStream.Write(array, 0, 40);
		}
		return 40;
	}

	public static object Deserialize(StreamBuffer inStream, short length)
	{
		Vector2 vector = default(Vector2);
		Vector2 vector2 = default(Vector2);
		Vector2 vector3 = default(Vector2);
		Vector2 vector4 = default(Vector2);
		Vector2 vector5 = default(Vector2);
		lock (memVector2)
		{
			inStream.Read(memVector2, 0, 40);
			int offset = 0;
			Protocol.Deserialize(out vector.x, memVector2, ref offset);
			Protocol.Deserialize(out vector.y, memVector2, ref offset);
			Protocol.Deserialize(out vector2.x, memVector2, ref offset);
			Protocol.Deserialize(out vector2.y, memVector2, ref offset);
			Protocol.Deserialize(out vector3.x, memVector2, ref offset);
			Protocol.Deserialize(out vector3.y, memVector2, ref offset);
			Protocol.Deserialize(out vector4.x, memVector2, ref offset);
			Protocol.Deserialize(out vector4.y, memVector2, ref offset);
			Protocol.Deserialize(out vector5.x, memVector2, ref offset);
			Protocol.Deserialize(out vector5.y, memVector2, ref offset);
		}
		return new QuadControlPoint(vector, vector2, vector3, vector4, vector5);
	}

	public void Stamp(List<Vector3> Vertices, List<Vector2> UVs, List<int> Tris)
	{
		AddInitialQuad(Vertices, UVs, Tris);
	}

	public void UpdateForControlPoint(QuadControlPoint trailingPoint, int index, List<Vector3> Vertices, List<Vector2> UVs, List<int> Tris)
	{
		AddVertsAndUVs(Vertices, UVs);
		int num = (index - 1) * 4;
		int num2 = index * 4;
		List<int> list = EdgeVerts(trailingPoint);
		List<int> list2 = trailingPoint.EdgeVerts(this, trailing: true);
		Tris.Add(num2 + list[0]);
		Tris.Add(num + list2[0]);
		Tris.Add(num2 + list[1]);
		Tris.Add(num2 + list[1]);
		Tris.Add(num + list2[0]);
		Tris.Add(num + list2[1]);
		Tris.Add(num2 + list[1]);
		Tris.Add(num + list2[1]);
		Tris.Add(num2 + list[2]);
		Tris.Add(num2 + list[2]);
		Tris.Add(num + list2[1]);
		Tris.Add(num + list2[2]);
		AddTris(Tris, num2);
	}
}
