public class DrawingSurface : Photon.MonoBehaviour, IPersistable, IPreSerializationPersistable
{
	public enum AntiAliasing
	{
		ONE = 1,
		TWO = 2,
		FOUR = 4,
		EIGHT = 8
	}

	public enum DrawingSurfaceType
	{
		None,
		Whiteboard
	}

	public static Texture2D ClearTexture;

	public Texture2D ClearReference;

	[Header("Surface Config")]
	[SerializeField]
	private DrawingSurfaceType drawingSurfaceType;

	[Header("Coordinate Mapping")]
	[SerializeField]
	private Transform drawingRectMin;

	[SerializeField]
	private Transform drawingRectMax;

	private Rect drawingBounds = default(Rect);

	[Header("Rendering")]
	[SerializeField]
	private Renderer surfaceRenderer;

	[SerializeField]
	private int resolution = 512;

	[SerializeField]
	private AntiAliasing antiAliasing = AntiAliasing.EIGHT;

	private bool surfaceTextureIsDirty;

	private SynchronizedField<bool> _masterSurfaceTextureHasBeenModified;

	[SerializeField]
	private bool debugWaitForDownload;

	[SerializeField]
	private RenderTexture remoteRenderTexture;

	[SerializeField]
	private RenderTexture localRenderTexture;

	private CommandBuffer remoteCommandBuffer;

	private CommandBuffer localCommandBuffer;

	private Camera mainCamera;

	private float lastSendToAllTime = -1f;

	private SynchronizedField<string> _lastUploadedImageName;

	private PhotonPlayer currentlyUploadingPlayer;

	private bool _waitingForDownload;

	private bool wasWaiting;

	private List<IStroke> remoteStrokes = new List<IStroke>();

	private List<IStroke> localStrokes = new List<IStroke>();

	private List<IStroke> finished = new List<IStroke>();

	private AltTextureSet cachedSurfaceTextureSet = new AltTextureSet(usePalette: false);

	private Dictionary<IStroke, DrawingObject> RendererDict = new Dictionary<IStroke, DrawingObject>();

	public List<DrawingObject> DrawingObjectPool = new List<DrawingObject>();

	[SerializeField]
	private DrawingObject drawingObjectPrefab;

	[SerializeField]
	[FormerlySerializedAs("maxImagePendingWaitTime")]
	private float maxSerializeUploadWaitTime = 5f;

	public float WHRatio => surfaceRenderer.transform.localScale.x / surfaceRenderer.transform.localScale.y;

	public bool SurfaceTextureIsDirty
	{
		get
		{
			return surfaceTextureIsDirty;
		}
		private set
		{
			surfaceTextureIsDirty = value;
			if (value)
			{
				MasterSurfaceTextureModifiedFromDefault = true;
				cachedSurfaceTextureSet.DestroyTextures();
			}
		}
	}

	public bool MasterSurfaceTextureModifiedFromDefault
	{
		get
		{
			return _masterSurfaceTextureHasBeenModified.Get();
		}
		private set
		{
			_masterSurfaceTextureHasBeenModified.Set(value);
		}
	}

	public string LastUploadedImageName
	{
		get
		{
			return _lastUploadedImageName.Get();
		}
		private set
		{
			_lastUploadedImageName.Set(value);
		}
	}

	public bool BlockObjectPersistance => false;

	public Texture2D InitialTexture { get; private set; }

	public int PhotonId => base.photonView.viewID;

	public Vector3 Right => base.transform.right;

	public Vector3 Up => base.transform.up;

	public Vector3 Normal => base.transform.forward;

	public float RendererScale => (drawingRectMax.position - drawingRectMin.position).magnitude;

	public int Resolution => resolution;

	public bool WaitingForUpload => currentlyUploadingPlayer != null;

	public bool WaitingForDownload
	{
		get
		{
			return _waitingForDownload;
		}
		private set
		{
			_waitingForDownload = value;
			if (!_waitingForDownload && MarkedDirtyDuringWait)
			{
				MarkedDirtyDuringWait = false;
				MarkDirty();
			}
		}
	}

	public bool WaitingForData => WaitingForUpload || WaitingForDownload;

	public bool MarkedDirtyDuringWait { get; private set; }

	private bool ShouldWaitToRender => WaitingForData;

	protected override void Awake()
	{
		base.Awake();
		mainCamera = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera;
		if (surfaceRenderer == null)
		{
			UnityEngine.Application.Quit();
			throw new Exception("I need a surface renderer to not crash!");
		}
		_lastUploadedImageName = new SynchronizedField<string>(this, "LIN", string.Empty, SetterPermissionMode.ANYONE);
		_masterSurfaceTextureHasBeenModified = new SynchronizedField<bool>(this, "MOD", defaultValue: false, SetterPermissionMode.MASTER);
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		remoteRenderTexture = new RenderTexture(resolution, resolution, 0, RenderTextureFormat.ARGB32);
		remoteRenderTexture.antiAliasing = (int)antiAliasing;
		InitialTexture = (Texture2D)surfaceRenderer.material.GetTexture("_DrawingTex");
		if (InitialTexture == null)
		{
			if (ClearTexture == null)
			{
				ClearTexture = Resources.Load<Texture2D>("ClearTexture");
			}
			InitialTexture = ClearTexture;
			ClearReference = ClearTexture;
		}
		SetDrawingTexture();
		ShowDefaultTexture();
		if (drawingRectMin != null && drawingRectMax != null)
		{
			drawingBounds = Rect.MinMaxRect(drawingRectMax.localPosition.x, drawingRectMin.localPosition.y, drawingRectMin.localPosition.x, drawingRectMax.localPosition.y);
			return;
		}
		throw new Exception("Drawing Bounds need to be set for DrawingSurface to work!");
	}

	private void Update()
	{
		bool flag = false;
		if (ShouldWaitToRender)
		{
			wasWaiting = true;
			RemoveCommandBuffers();
			return;
		}
		if (wasWaiting)
		{
			flag = true;
			wasWaiting = false;
		}
		foreach (IStroke item in finished)
		{
			flag |= RemovePendingStroke(item);
		}
		finished.Clear();
		if (flag)
		{
			RebuildCommandBuffers();
		}
		if (remoteStrokes.Count <= 0 && localStrokes.Count <= 0)
		{
			return;
		}
		foreach (IStroke remoteStroke in remoteStrokes)
		{
			if (remoteStroke.MeshNeedsRebuild)
			{
				remoteStroke.UpdateMesh(GetDrawingObject(remoteStroke).MeshFilter);
			}
			if (remoteStroke.Finished)
			{
				finished.Add(remoteStroke);
			}
		}
		foreach (IStroke localStroke in localStrokes)
		{
			if (localStroke.MeshNeedsRebuild)
			{
				localStroke.UpdateMesh(GetDrawingObject(localStroke).MeshFilter);
			}
			if (localStroke.Finished)
			{
				finished.Add(localStroke);
			}
		}
	}

	private void OnDrawGizmos()
	{
		if (drawingRectMin != null && drawingRectMax != null)
		{
			Gizmos.color = Color.red.WithAlpha(0.5f);
			Gizmos.DrawLine(drawingRectMin.position, drawingRectMax.position);
		}
		Gizmos.color = Color.blue.WithAlpha(0.5f);
		Gizmos.DrawRay(base.transform.position, Normal);
		Gizmos.color = Color.green.WithAlpha(0.5f);
		Gizmos.DrawRay(base.transform.position, Up);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		RenderTexture.active = null;
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
	}

	private void MarkDirty()
	{
		if (WaitingForData)
		{
			MarkedDirtyDuringWait = true;
		}
		else
		{
			SurfaceTextureIsDirty = true;
		}
	}

	public void SetDrawingTexture(Texture tex = null)
	{
		if (tex != null)
		{
			surfaceRenderer.material.SetTexture("_DrawingTex", tex);
			return;
		}
		RenderTexture value;
		if (Profiles.LocalProfile.IsJunior())
		{
			localRenderTexture = new RenderTexture(resolution, resolution, 0, RenderTextureFormat.ARGB32);
			localRenderTexture.antiAliasing = (int)antiAliasing;
			value = localRenderTexture;
		}
		else
		{
			value = remoteRenderTexture;
		}
		surfaceRenderer.material.SetTexture("_DrawingTex", value);
	}

	private void RemoveCommandBuffers()
	{
		if (remoteCommandBuffer != null)
		{
			mainCamera.RemoveCommandBuffer(CameraEvent.AfterEverything, remoteCommandBuffer);
			remoteCommandBuffer = null;
		}
		if (localCommandBuffer != null)
		{
			mainCamera.RemoveCommandBuffer(CameraEvent.AfterEverything, localCommandBuffer);
			localCommandBuffer = null;
		}
	}

	private void RebuildCommandBuffers()
	{
		if (ShouldWaitToRender)
		{
			return;
		}
		RemoveCommandBuffers();
		if (remoteStrokes.Count > 0)
		{
			remoteCommandBuffer = new CommandBuffer
			{
				name = "Draw Remote Mesh"
			};
			remoteCommandBuffer.SetRenderTarget(remoteRenderTexture);
			foreach (IStroke remoteStroke in remoteStrokes)
			{
				remoteCommandBuffer.DrawRenderer(GetDrawingObject(remoteStroke).Renderer, remoteStroke.Material);
			}
			mainCamera.AddCommandBuffer(CameraEvent.AfterEverything, remoteCommandBuffer);
		}
		if (!Profiles.LocalProfile.IsJunior() || localStrokes.Count <= 0 || !(localRenderTexture != null))
		{
			return;
		}
		localCommandBuffer = new CommandBuffer
		{
			name = "Draw Local Mesh"
		};
		localCommandBuffer.SetRenderTarget(localRenderTexture);
		foreach (IStroke localStroke in localStrokes)
		{
			localCommandBuffer.DrawRenderer(GetDrawingObject(localStroke).Renderer, localStroke.Material);
		}
		mainCamera.AddCommandBuffer(CameraEvent.AfterEverything, localCommandBuffer);
	}

	public float DistanceToPlane(Vector3 worldPos)
	{
		return base.transform.InverseTransformPoint(worldPos).z;
	}

	public bool IsOverPlane(Vector3 position, out Vector2 onPlanePos, out float distanceToPlane)
	{
		Vector3 vector = base.transform.InverseTransformPoint(position);
		distanceToPlane = Vector3.Dot(position - drawingRectMin.position, Normal) / Normal.magnitude;
		vector.z = 0f;
		onPlanePos = vector;
		return drawingBounds.Contains(vector);
	}

	public Vector2 WorldToNormalizedBoardPos(Vector3 worldPos)
	{
		return NormalizedBoardSpace(WorldToBoardSpace(worldPos));
	}

	public Vector3 OnDrawingPlane(Vector3 worldPos)
	{
		Vector3 vector = worldPos - drawingRectMin.position;
		Vector3 vector2 = Vector3.Project(vector, Normal);
		return worldPos - vector2;
	}

	public Vector3 WorldToBoardSpace(Vector3 worldPos)
	{
		Vector3 position = OnDrawingPlane(worldPos);
		return base.transform.InverseTransformPoint(position);
	}

	public Vector2 NormalizedBoardSpace(Vector2 localPos)
	{
		Vector2 point = localPos * -1f;
		Vector2 vector = Rect.PointToNormalized(drawingBounds, point);
		return vector * 2f - new Vector2(1f, 1f);
	}

	public void OnSurfaceTriggerEnter(Collider other)
	{
		if (other.CompareTag("BrushTool"))
		{
			DrawingBase componentInParent = other.GetComponentInParent<DrawingBase>();
			if (componentInParent != null && (componentInParent.DrawingSurfaceType & drawingSurfaceType) != DrawingSurfaceType.None)
			{
				componentInParent.CurrentSurface = this;
			}
		}
	}

	public void OnSurfaceTriggerExit(Collider other)
	{
		if (other.CompareTag("BrushTool"))
		{
			DrawingBase componentInParent = other.GetComponentInParent<DrawingBase>();
			if (componentInParent != null && (componentInParent.DrawingSurfaceType & drawingSurfaceType) != DrawingSurfaceType.None)
			{
				componentInParent.CurrentSurface = null;
			}
		}
	}

	public void OnPhotonPlayerConnected(PhotonPlayer newPlayer)
	{
		if (PhotonNetwork.isMasterClient && MasterSurfaceTextureModifiedFromDefault)
		{
			SendCurrentDrawingSurfaceState(newPlayer);
		}
	}

	public void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if (currentlyUploadingPlayer != player)
		{
			return;
		}
		currentlyUploadingPlayer = null;
		if (!PhotonNetwork.isMasterClient)
		{
			base.photonView.RpcPlayer(PhotonNetwork.masterClient, RpcRequestImage);
			return;
		}
		PhotonPlayer photonPlayer = PhotonNetwork.otherPlayers.FirstOrDefault();
		if (photonPlayer != null)
		{
			base.photonView.RpcPlayer(photonPlayer, RpcRequestImage);
		}
	}

	public AltTextureSet ExportDrawingSurface()
	{
		if (cachedSurfaceTextureSet.MainTexture == null)
		{
			Texture2D mainTexture = AltTextureSet.RenderTextureToTexture2D(remoteRenderTexture, TextureFormat.ARGB32);
			cachedSurfaceTextureSet.MainTexture = mainTexture;
		}
		return cachedSurfaceTextureSet;
	}

	private void SendCurrentDrawingSurfaceState(PhotonPlayer newPlayer)
	{
		SendDrawingSurfaceState(uploadLocalState: true, newPlayer);
	}

	private void SendLastDrawingSurfaceStateToAll()
	{
		SendDrawingSurfaceState(uploadLocalState: false, null);
	}

	private void SendDrawingSurfaceState(bool uploadLocalState, PhotonPlayer specificPlayer)
	{
		if (SurfaceTextureIsDirty && uploadLocalState)
		{
			if (specificPlayer != null)
			{
				base.photonView.RpcPlayer(specificPlayer, RpcNotifyUploadPending);
			}
			else
			{
				base.photonView.RpcAll(RpcNotifyUploadPending);
			}
			UploadDrawingSurfaceState().Then(delegate(string newImageName)
			{
				if (specificPlayer != null)
				{
					base.photonView.RpcPlayer(specificPlayer, RpcDownloadImage, newImageName);
				}
				else
				{
					base.photonView.RpcAll(RpcDownloadImage, newImageName);
				}
			}).Error(delegate
			{
				UnityEngine.Debug.LogError("Failed to upload image on DrawingSurface. Will try again later.");
				SingletonMonoBehaviour<Scheduler>.Instance.Run(SendDrawingSurfaceStateLater(uploadLocalState, specificPlayer));
			});
		}
		else if (specificPlayer != null)
		{
			base.photonView.RpcPlayer(specificPlayer, RpcDownloadImage, LastUploadedImageName);
		}
		else
		{
			base.photonView.RpcAll(RpcDownloadImage, LastUploadedImageName);
		}
		if (specificPlayer == null)
		{
			lastSendToAllTime = UnityEngine.Time.realtimeSinceStartup;
		}
	}

	private IEnumerator<ISchedule> SendDrawingSurfaceStateLater(bool useLocalState, PhotonPlayer specificPlayer)
	{
		float queueTime = UnityEngine.Time.realtimeSinceStartup;
		yield return Schedule.Wait(15f);
		if (PhotonNetwork.otherPlayers.Contains(specificPlayer) && queueTime > lastSendToAllTime)
		{
			SendDrawingSurfaceState(useLocalState, specificPlayer);
		}
	}

	private IPromise<string> UploadDrawingSurfaceState()
	{
		SurfaceTextureIsDirty = false;
		MasterSurfaceTextureModifiedFromDefault = true;
		AltTextureSet imageSet = ExportDrawingSurface();
		return Images.UploadTransientImage(imageSet, LastUploadedImageName, expectsAltImage: false).Then(delegate(string newImageName)
		{
			LastUploadedImageName = newImageName;
		}).Error(delegate
		{
			SurfaceTextureIsDirty = true;
		});
	}

	private void ShowDefaultTexture()
	{
		if (!(this == null))
		{
			if (remoteRenderTexture != null)
			{
				Graphics.Blit(InitialTexture, remoteRenderTexture);
			}
			if (localRenderTexture != null)
			{
				Graphics.Blit(InitialTexture, localRenderTexture);
			}
			SurfaceTextureIsDirty = false;
			currentlyUploadingPlayer = null;
			cachedSurfaceTextureSet.DestroyTextures();
		}
	}

	[PunRPC]
	private void RpcRequestImage(PhotonMessageInfo photonMessageInfo)
	{
		SendCurrentDrawingSurfaceState(photonMessageInfo.sender);
	}

	[PunRPC]
	private void RpcNotifyUploadPending(PhotonMessageInfo messageInfo)
	{
		currentlyUploadingPlayer = messageInfo.sender;
	}

	[PunRPC]
	private void RpcDownloadImage(string newImageName)
	{
		currentlyUploadingPlayer = null;
		if (!string.IsNullOrEmpty(newImageName))
		{
			RefreshImageFromCDN(newImageName);
		}
		else
		{
			ShowDefaultTexture();
		}
	}

	private void RefreshImageFromCDN(string newImageName)
	{
		WaitingForDownload = true;
		Images.GetImage(newImageName, generateMipMaps: false, overrideJuniorCheck: true).Then(delegate(Texture2D t)
		{
			if (this != null && t != null && t.name == newImageName)
			{
				OnImageDownloaded(t);
			}
			else
			{
				ShowDefaultTexture();
			}
		}).Error(delegate(string e)
		{
			UnityEngine.Debug.LogErrorFormat("Error downloading DrawingSurface texture: {0}", e);
			ShowDefaultTexture();
		})
			.Finally(delegate
			{
				WaitingForDownload = false;
			});
	}

	private void OnImageDownloaded(Texture2D incomingTex)
	{
		if (incomingTex == null)
		{
			UnityEngine.Debug.LogError("Received null DrawingSurface state. Resetting!");
			ShowDefaultTexture();
			return;
		}
		Graphics.Blit(incomingTex, remoteRenderTexture);
		SurfaceTextureIsDirty = false;
		MasterSurfaceTextureModifiedFromDefault = true;
		cachedSurfaceTextureSet.DestroyTextures();
	}

	private void AddPendingStroke(IStroke pendingStroke, bool localPlayerIsDrawing)
	{
		bool flag = Profiles.LocalProfile.IsJunior();
		bool flag2 = false;
		if ((!flag || (flag && !localPlayerIsDrawing)) && !remoteStrokes.Contains(pendingStroke))
		{
			remoteStrokes.Add(pendingStroke);
			flag2 = true;
		}
		if (flag && localPlayerIsDrawing)
		{
			localStrokes.Add(pendingStroke);
			flag2 = true;
		}
		MarkDirty();
		if (flag2)
		{
			RebuildCommandBuffers();
		}
	}

	private bool RemovePendingStroke(IStroke pendingStroke)
	{
		ReleaseDrawingObject(pendingStroke);
		return remoteStrokes.Remove(pendingStroke) || localStrokes.Remove(pendingStroke);
	}

	public Stroke<ControlPointType> CreateStroke<ControlPointType>(ControlPointType startPoint, Material material, bool localPlayerIsDrawing) where ControlPointType : class, IDrawingControlPoint<ControlPointType>
	{
		Stroke<ControlPointType> stroke = new Stroke<ControlPointType>(startPoint, material);
		AddPendingStroke(stroke, localPlayerIsDrawing);
		return stroke;
	}

	public DrawingObject GetDrawingObject(IStroke stroke)
	{
		DrawingObject drawingObject = null;
		if (RendererDict.ContainsKey(stroke))
		{
			drawingObject = RendererDict[stroke];
		}
		else
		{
			foreach (DrawingObject item in DrawingObjectPool)
			{
				if (!item.gameObject.activeInHierarchy)
				{
					drawingObject = item;
					break;
				}
			}
			if (drawingObject == null)
			{
				drawingObject = UnityEngine.Object.Instantiate(drawingObjectPrefab);
				DrawingObjectPool.Add(drawingObject);
			}
		}
		if (!drawingObject.gameObject.activeInHierarchy)
		{
			drawingObject.gameObject.SetActive(value: true);
		}
		RendererDict[stroke] = drawingObject;
		return drawingObject;
	}

	public void ReleaseDrawingObject(IStroke stroke)
	{
		DrawingObject drawingObject = GetDrawingObject(stroke);
		drawingObject.ClearMesh();
		drawingObject.gameObject.SetActive(value: false);
		RendererDict.Remove(stroke);
	}

	public IEnumerator<ISchedule> PreSerialize(StringBuilder outputLog, bool savedToDisk)
	{
		if (!savedToDisk && MasterSurfaceTextureModifiedFromDefault && (SurfaceTextureIsDirty || LastUploadedImageName == null))
		{
			float time = 0f;
			while (WaitingForData && time < maxSerializeUploadWaitTime)
			{
				time += UnityEngine.Time.unscaledDeltaTime;
				yield return Schedule.NextFrame;
			}
			IPromise<string> uploadPromise = UploadDrawingSurfaceState();
			yield return Schedule.AfterCompleted(uploadPromise);
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData.DrawingSurfaceData == null || (deserializeParams.viewData.DrawingSurfaceData.IsModified && deserializeParams.viewData.ImageData == null))
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing DrawingSurface {0}: data empty.", base.gameObject);
		}
		else if (deserializeParams.viewData.DrawingSurfaceData.IsModified)
		{
			LastUploadedImageName = deserializeParams.viewData.ImageData.ImageName;
			if (!string.IsNullOrEmpty(LastUploadedImageName))
			{
				SendLastDrawingSurfaceStateToAll();
			}
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.DrawingSurfaceData != null || viewData.ImageData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing DrawingSurface {0}: Data already specified.", base.gameObject);
			return;
		}
		viewData.ImageData = new ImageData();
		viewData.DrawingSurfaceData = new DrawingSurfaceData();
		viewData.DrawingSurfaceData.IsModified = MasterSurfaceTextureModifiedFromDefault;
		if (MasterSurfaceTextureModifiedFromDefault && LastUploadedImageName != null)
		{
			NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.PersistTransientImage(LastUploadedImageName);
			viewData.ImageData.ImageName = LastUploadedImageName;
			if (transientData.imageNamesToPersist == null)
			{
				transientData.imageNamesToPersist = new List<string>();
			}
			transientData.imageNamesToPersist.Add(LastUploadedImageName);
		}
		else
		{
			viewData.ImageData.ImageName = string.Empty;
		}
	}
}
public class DrawingToolRigidbodyPickup : RigidbodyPickup
{
	[SerializeField]
	private bool forceRotationNearSurface;

	[SerializeField]
	private AnimationCurve nearSurfaceRotationCurve = AnimationCurve.Linear(0f, 1f, 1f, 0f);

	private DrawingBase drawingTool;

	public override Quaternion TargetRotation
	{
		get
		{
			if (forceRotationNearSurface && drawingTool.CurrentSurface != null)
			{
				Quaternion targetRotation = base.TargetRotation;
				Vector3 fromDirection = targetRotation * Vector3.up;
				Vector3 normal = drawingTool.CurrentSurface.Normal;
				Quaternion quaternion = Quaternion.FromToRotation(fromDirection, normal);
				float time = drawingTool.CurrentSurface.DistanceToPlane(drawingTool.BrushTip.transform.position);
				float t = nearSurfaceRotationCurve.Evaluate(time);
				return Quaternion.Lerp(targetRotation, quaternion * targetRotation, t);
			}
			return base.TargetRotation;
		}
	}

	public override Vector3 TargetPosition
	{
		get
		{
			Vector3 targetPosition = base.TargetPosition;
			if (drawingTool.CurrentSurface != null && drawingTool.CurrentSurface.IsOverPlane(targetPosition, out var onPlanePos, out var distanceToPlane) && distanceToPlane < 0f)
			{
				return drawingTool.CurrentSurface.transform.TransformPoint(onPlanePos);
			}
			return targetPosition;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		drawingTool = GetComponent<DrawingBase>();
	}
}
public class DrawingTriggerListener : UnityEngine.MonoBehaviour
{
	private DrawingSurface surface;

	private void Awake()
	{
		surface = GetComponentInParent<DrawingSurface>();
	}

	private void OnTriggerEnter(Collider other)
	{
		surface.OnSurfaceTriggerEnter(other);
	}

	private void OnTriggerExit(Collider other)
	{
		surface.OnSurfaceTriggerExit(other);
	}
}
public class Eraser : DrawingBase<QuadControlPoint>
{
	public Transform TR;

	public Transform TL;

	public Transform BL;

	public Transform BR;

	protected override QuadControlPoint CreateNewControlPoint()
	{
		Vector2 vector = base.CurrentSurface.WorldToNormalizedBoardPos(base.transform.position);
		Vector2 vector2 = base.CurrentSurface.WorldToNormalizedBoardPos(TR.transform.position);
		Vector2 vector3 = base.CurrentSurface.WorldToNormalizedBoardPos(TL.transform.position);
		Vector2 vector4 = base.CurrentSurface.WorldToNormalizedBoardPos(BL.transform.position);
		Vector2 vector5 = base.CurrentSurface.WorldToNormalizedBoardPos(BR.transform.position);
		return new QuadControlPoint(vector, vector3, vector2, vector5, vector4);
	}
}
public class GreenScreen : UnityEngine.MonoBehaviour
{
	[Header("Green Screen")]
	[SerializeField]
	private List<Renderer> screenRenderers;

	[SerializeField]
	private List<Color> screenColors;

	private int colorIndex;

	[SerializeField]
	private Canvas canvas;

	private Tool tool;

	private bool screenCollisionActive;

	private void Awake()
	{
		screenColors.Add(screenRenderers[0].sharedMaterial.color);
		colorIndex = screenColors.Count - 1;
		canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PostPickupEvent += OnPostPickup;
			tool.PostReleaseEvent += OnPostRelease;
			tool.RigidbodyEx.AddKinematic(this);
		}
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.PostPickupEvent -= OnPostPickup;
			tool.PostReleaseEvent -= OnPostRelease;
		}
	}

	private void OnPostRelease(Tool tool)
	{
		tool.RigidbodyEx.useGravity = false;
		canvas.gameObject.SetActive(value: true);
	}

	private void OnPostPickup(Tool tool)
	{
		canvas.gameObject.SetActive(value: false);
	}

	[SkipRename]
	public void Button_SwapColor()
	{
		colorIndex = ++colorIndex % screenColors.Count;
		foreach (Renderer screenRenderer in screenRenderers)
		{
			screenRenderer.sharedMaterial.color = screenColors[colorIndex];
		}
	}

	[SkipRename]
	public void Button_ToggleCollision()
	{
		screenCollisionActive = !screenCollisionActive;
		foreach (Renderer screenRenderer in screenRenderers)
		{
			Collider component = screenRenderer.GetComponent<Collider>();
			if (component != null)
			{
				component.enabled = screenCollisionActive;
			}
		}
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, (!screenCollisionActive) ? "Screen collisions off" : "Screen collisions active", 2f);
	}

	[SkipRename]
	public void Button_FixRotation()
	{
		base.transform.rotation = Quaternion.Euler(0f, base.transform.rotation.eulerAngles.y, 0f);
	}

	[SkipRename]
	public void Button_FixPosition()
	{
		Vector3 position = base.transform.position;
		position.y = Player.LocalPlayer.CurrentFloorPosition.y + 1.51f;
		base.transform.position = position;
	}

	[SkipRename]
	public void Button_HideUI()
	{
		canvas.gameObject.SetActive(value: false);
	}
}
