public class WhiteboardPen : DrawingBase<QuadControlPoint>, ICustomImposterBehavior
{
	[SerializeField]
	private AnimationCurve radiusCurve;

	[FormerlySerializedAs("defaultPenColor")]
	[SerializeField]
	public Color PenColor = Color.blue;

	[SerializeField]
	private Renderer meshRenderer;

	[SerializeField]
	private float _strokeRadius = 0.005f;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private SandboxColorable sandboxColorable;

	protected float StrokeRadius
	{
		get
		{
			if (base.CurrentSurface != null)
			{
				if (distanceToPlane < 0f)
				{
					return _strokeRadius;
				}
				return radiusCurve.Evaluate(distanceToPlane) * _strokeRadius;
			}
			return _strokeRadius;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		if (radiusCurve == null)
		{
			radiusCurve = AnimationCurve.Linear(0f, StrokeRadius, 0.1f, StrokeRadius);
		}
	}

	private void Start()
	{
		ProcessCreationObjectOverrides();
		if (sandboxColorable != null)
		{
			sandboxColorable.SandboxColorChangedEvent += OnSandboxColorChanged;
		}
		SetColors();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (sandboxColorable != null)
		{
			sandboxColorable.SandboxColorChangedEvent -= OnSandboxColorChanged;
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = PenColor;
		Gizmos.DrawSphere(base.BrushTip.position, 0.01f);
	}

	private void OnSandboxColorChanged()
	{
		PenColor = sandboxColorable.Color;
		SetColors();
	}

	private void SetColors()
	{
		if (meshRenderer != null)
		{
			meshRenderer.material.SetColor("_Green_Col", PenColor);
			meshRenderer.material.SetColor("_Base_Col", PenColor);
		}
		if (base.DrawingMaterial != null)
		{
			base.DrawingMaterial.SetColor("_Color", PenColor);
		}
	}

	protected override QuadControlPoint CreateNewControlPoint()
	{
		Vector2 vector = base.CurrentSurface.WorldToNormalizedBoardPos(base.BrushTip.position);
		Vector2 vector2 = base.CurrentSurface.WorldToNormalizedBoardPos(base.BrushTip.position + base.CurrentSurface.Up * StrokeRadius + -base.CurrentSurface.Right * StrokeRadius);
		Vector2 vector3 = base.CurrentSurface.WorldToNormalizedBoardPos(base.BrushTip.position + base.CurrentSurface.Up * StrokeRadius + base.CurrentSurface.Right * StrokeRadius);
		Vector2 vector4 = base.CurrentSurface.WorldToNormalizedBoardPos(base.BrushTip.position + -base.CurrentSurface.Up * StrokeRadius + base.CurrentSurface.Right * StrokeRadius);
		Vector2 vector5 = base.CurrentSurface.WorldToNormalizedBoardPos(base.BrushTip.position + -base.CurrentSurface.Up * StrokeRadius + -base.CurrentSurface.Right * StrokeRadius);
		return new QuadControlPoint(vector, vector3, vector2, vector5, vector4);
	}

	private void ProcessCreationObjectOverrides()
	{
		if (base.Tool.CreationObject != null)
		{
			if (base.Tool.CreationObject.ColorOverride.HasValue)
			{
				PenColor = base.Tool.CreationObject.ColorOverride.Value;
			}
			else
			{
				base.Tool.CreationObject.ColorOverride = PenColor;
			}
		}
	}

	void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
	{
		PenColor = parameters.colorOverride;
		SetColors();
	}
}
