public static class PlayerBackpackToolSettings
{
	private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

	public static PlayerBackpackToolConfig ConfigAsset = CustomSettingsLoader.LoadConfig<PlayerBackpackToolConfig>();

	public static void PreloadAssets()
	{
		foreach (object value in System.Enum.GetValues(typeof(PlayerBackpackToolType)))
		{
			string toolPrefabName = GetToolPrefabName((PlayerBackpackToolType)value);
			if (!string.IsNullOrEmpty(toolPrefabName) && !PhotonNetwork.PrefabCache.ContainsKey(toolPrefabName))
			{
				PhotonNetwork.PrefabCache.Add(toolPrefabName, Resources.Load<GameObject>(toolPrefabName));
			}
		}
	}

	public static Tool GetToolPrefab(PlayerBackpackToolType toolType)
	{
		return GetToolConfig(toolType)?.Prefab;
	}

	public static string GetToolPrefabName(PlayerBackpackToolType toolType)
	{
		PlayerBackpackToolConfig.Config toolConfig = GetToolConfig(toolType);
		if (toolConfig != null && toolConfig.Prefab != null)
		{
			return toolConfig.Prefab.name;
		}
		return null;
	}

	public static string GetToolFriendlyName(PlayerBackpackToolType toolType)
	{
		PlayerBackpackToolConfig.Config toolConfig = GetToolConfig(toolType);
		if (toolConfig != null)
		{
			return toolConfig.FriendlyName;
		}
		return "None";
	}

	public static Vector3 GetToolSpawnRotationEuler(PlayerBackpackToolType toolType)
	{
		return GetToolConfig(toolType)?.SpawnRotation ?? Vector3.zero;
	}

	public static List<PlayerBackpackToolType> GetAllToolTypes()
	{
		List<PlayerBackpackToolType> list = new List<PlayerBackpackToolType>();
		if (ConfigAsset != null && ConfigAsset.Configs != null)
		{
			PlayerBackpackToolConfig.Config[] configs = ConfigAsset.Configs;
			foreach (PlayerBackpackToolConfig.Config config in configs)
			{
				list.Add(config.ToolType);
			}
		}
		return list;
	}

	public static PlayerBackpackToolConfig.Config[] GetAllToolConfigs()
	{
		if (ConfigAsset != null && ConfigAsset.Configs != null)
		{
			return ConfigAsset.Configs;
		}
		return new PlayerBackpackToolConfig.Config[0];
	}

	public static PlayerBackpackToolConfig.Config GetToolConfig(PlayerBackpackToolType toolType)
	{
		if (ConfigAsset != null && ConfigAsset.Configs != null && toolType >= PlayerBackpackToolType.SHARE_CAM && (int)toolType < ConfigAsset.Configs.Length)
		{
			return ConfigAsset.Configs[(int)toolType];
		}
		return null;
	}
}
[DisallowMultipleComponent]
public class SpawnableTool : UnityEngine.MonoBehaviour, IPersistable
{
	public SpawnableToolType Type;

	[SerializeField]
	private SerializedGuid prefabId;

	[NonSerialized]
	public int InstantiationTag = -1;

	public Tool Tool { get; set; }

	public Guid PrefabId
	{
		get
		{
			return prefabId.Value;
		}
		set
		{
		}
	}

	public bool BlockObjectPersistance => false;

	private void Awake()
	{
		if (Tool == null)
		{
			Tool = GetComponent<Tool>();
		}
	}

	public void Enable(bool enabled)
	{
		if (Tool == null)
		{
			base.gameObject.SetActive(enabled);
		}
		else if (PhotonNetwork.isMasterClient)
		{
			Tool.IsEnabled = enabled;
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData.SpawnableToolData == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing SpawnableTool {0}: No type specified in data.", base.gameObject);
			return;
		}
		Guid guid = RecRoom.Protobuf.ByteStringExtensions.ToGuid(deserializeParams.viewData.SpawnableToolData.PrefabId);
		if (guid != PrefabId)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing SpawnableTool {0}: Serialized GUID {1} does not match prefab value {2}", base.gameObject, guid, PrefabId);
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.SpawnableToolData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing SpawnableTool {0}: Type already specified in data.", base.gameObject);
		}
		else
		{
			viewData.SpawnableToolData = new SpawnableToolData();
			viewData.SpawnableToolData.PrefabId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(PrefabId);
		}
	}
}
