public class SpawnableToolConfig : ScriptableObject
{
	public enum Category
	{
		INVALID = -1,
		WEAPON,
		SPORTS,
		DECORATION,
		KITCHEN,
		TOYS,
		CREATIVE,
		FURNITURE,
		DYNAMIC,
		MATH_CHIPS,
		GAME_CHIPS,
		OTHER_CHIPS,
		GIZMOS,
		OTHER_GADGETS
	}

	public enum CustomGameEquipmentSet
	{
		INVALID,
		COMBAT
	}

	public enum ToolConnectabilityType
	{
		NOT_CONNECTABLE,
		AUTOMATIC,
		CUSTOM
	}

	[Serializable]
	public class Config
	{
		public string UniqueName = string.Empty;

		public string FriendlyName = string.Empty;

		public string Description = string.Empty;

		public string[] DefaultTagNames;

		public Tool Prefab;

		public Vector3 SpawnRotation = Vector3.zero;

		public Color ColorOverride = Color.clear;

		public GameTeam TeamOverride = GameTeam.ANY;

		public bool AvailableInMakerPen;

		[ConditionalField("AvailableInMakerPen")]
		public Category Category = Category.INVALID;

		[RecRoom.ReadOnly]
		public int SandboxResourceCost = 1;

		public CircuitNodeType CircuitNodeType;

		[Tooltip("AUTOMATIC (default): Add standard connectable tool scripts when assigning components. NOT_CONNECTABLE: Remove all connectable tool scripts when assigning components. CUSTOM: Do nothing (scripts are presumed to be set manually).")]
		public ToolConnectabilityType ToolConnectability = ToolConnectabilityType.AUTOMATIC;

		public CustomGameEquipmentSet[] AvailableInCustomGameSets;

		[HideInInspector]
		public int CostsAssignedId;
	}

	[SerializeField]
	[FormerlySerializedAs("Equipment")]
	public Config[] Configs;

	public bool CheckSandboxCosts(out string message)
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < Configs.Length; i++)
		{
			Config config = Configs[i];
			if (config.CostsAssignedId != i)
			{
				stringBuilder.AppendLine("Resource Cost not set for equipment: " + Configs[i].UniqueName);
			}
		}
		message = stringBuilder.ToString();
		return string.IsNullOrEmpty(message);
	}

	public bool CheckCompiledEnum(out string message)
	{
		string[] enumNames = System.Enum.GetNames(typeof(SpawnableToolType));
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < Configs.Length; i++)
		{
			Config config = Configs[i];
			if (!enumNames.Contains(config.UniqueName))
			{
				stringBuilder.AppendLine("No matching enum for equipment: " + Configs[i].UniqueName);
			}
		}
		for (int j = 0; j < enumNames.Length; j++)
		{
			if (enumNames[j] != "INVALID" && !Configs.Any((Config e) => e.UniqueName == enumNames[j]))
			{
				stringBuilder.AppendLine("No matching equipment config for SpawnableTool enum: " + enumNames[j]);
			}
		}
		message = stringBuilder.ToString();
		return string.IsNullOrEmpty(message);
	}
}
public static class SpawnableToolSettings
{
	private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

	public static SpawnableToolConfig ConfigAsset = CustomSettingsLoader.LoadConfig<SpawnableToolConfig>();

	public static SpawnableToolCategoryConfig CategoryConfigAsset = CustomSettingsLoader.LoadConfig<SpawnableToolCategoryConfig>();

	public static Dictionary<Guid, SpawnableToolConfig.Config> PersistenceGuidToConfigMap;

	private static List<SpawnableToolCategoryConfig.CategoryConfig>[] groupToCategoryConfigMapping;

	private static List<SpawnableToolType>[] categoryToSpawnableToolMapping;

	public static string FullConfigAssetFilePath => CustomSettingsLoader.GetTrimmedFilePath("Assets/Core/Content/Configs/");

	public static string FullConfigAssetFileName => CustomSettingsLoader.GetAssetFileName<SpawnableToolConfig>() + ".asset";

	public static string FullConfigAssetFilePathAndFileName => $"{FullConfigAssetFilePath}/{FullConfigAssetFileName}";

	public static void PreloadAssets()
	{
		foreach (object value in System.Enum.GetValues(typeof(SpawnableToolType)))
		{
			string spawnableToolPrefabName = GetSpawnableToolPrefabName((SpawnableToolType)value);
			if (!string.IsNullOrEmpty(spawnableToolPrefabName) && !PhotonNetwork.PrefabCache.ContainsKey(spawnableToolPrefabName))
			{
				PhotonNetwork.PrefabCache.Add(spawnableToolPrefabName, Resources.Load<GameObject>(spawnableToolPrefabName));
			}
		}
	}

	private static void InitGroupToCategoryConfigMapping()
	{
		if (groupToCategoryConfigMapping != null)
		{
			return;
		}
		groupToCategoryConfigMapping = new List<SpawnableToolCategoryConfig.CategoryConfig>[System.Enum.GetValues(typeof(SpawnableToolCategoryConfig.Group)).Length];
		for (int i = 0; i < groupToCategoryConfigMapping.Length; i++)
		{
			groupToCategoryConfigMapping[i] = new List<SpawnableToolCategoryConfig.CategoryConfig>();
		}
		SpawnableToolCategoryConfig.CategoryConfig[] categoryConfigs = CategoryConfigAsset.CategoryConfigs;
		foreach (SpawnableToolCategoryConfig.CategoryConfig categoryConfig in categoryConfigs)
		{
			if (categoryConfig.Category != SpawnableToolConfig.Category.INVALID && categoryConfig.Group != SpawnableToolCategoryConfig.Group.INVALID)
			{
				groupToCategoryConfigMapping[(int)categoryConfig.Group].Add(categoryConfig);
			}
		}
	}

	public static List<SpawnableToolCategoryConfig.CategoryConfig> GetCategoryConfigsByGroup(SpawnableToolCategoryConfig.Group group)
	{
		InitGroupToCategoryConfigMapping();
		return groupToCategoryConfigMapping[(int)group];
	}

	public static List<SpawnableToolType> GetSpawnableToolsByGroup(SpawnableToolCategoryConfig.Group group)
	{
		List<SpawnableToolType> list = new List<SpawnableToolType>();
		List<SpawnableToolCategoryConfig.CategoryConfig> categoryConfigsByGroup = GetCategoryConfigsByGroup(group);
		foreach (SpawnableToolCategoryConfig.CategoryConfig item in categoryConfigsByGroup)
		{
			list.AddRange(GetSpawnableToolsByCategory(item.Category));
		}
		return list;
	}

	public static List<SpawnableToolType> GetSpawnableToolsByCategory(SpawnableToolConfig.Category category)
	{
		if (categoryToSpawnableToolMapping == null)
		{
			categoryToSpawnableToolMapping = new List<SpawnableToolType>[System.Enum.GetValues(typeof(SpawnableToolConfig.Category)).Length];
			for (int i = 0; i < categoryToSpawnableToolMapping.Length; i++)
			{
				categoryToSpawnableToolMapping[i] = new List<SpawnableToolType>();
			}
			SpawnableToolConfig.Config[] configs = ConfigAsset.Configs;
			foreach (SpawnableToolConfig.Config config in configs)
			{
				SpawnableToolType spawnableToolConfigType = GetSpawnableToolConfigType(config);
				if (spawnableToolConfigType != SpawnableToolType.INVALID && config.Category != SpawnableToolConfig.Category.INVALID && config.AvailableInMakerPen)
				{
					categoryToSpawnableToolMapping[(int)config.Category].Add(spawnableToolConfigType);
				}
			}
		}
		return categoryToSpawnableToolMapping[(int)category];
	}

	public static SpawnableToolCategoryConfig.Group GetSpawnableToolGroup(SpawnableToolType spawnableTool)
	{
		InitGroupToCategoryConfigMapping();
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableTool);
		if (spawnableToolConfig != null)
		{
			List<SpawnableToolCategoryConfig.CategoryConfig>[] array = groupToCategoryConfigMapping;
			foreach (List<SpawnableToolCategoryConfig.CategoryConfig> list in array)
			{
				if (list.Select((SpawnableToolCategoryConfig.CategoryConfig cc) => cc.Category).Contains(spawnableToolConfig.Category))
				{
					return list[0].Group;
				}
			}
		}
		return SpawnableToolCategoryConfig.Group.INVALID;
	}

	public static Guid GetSpawnableToolPrefabId(SpawnableToolType spawnableToolType)
	{
		Tool spawnableToolPrefab = GetSpawnableToolPrefab(spawnableToolType);
		if (spawnableToolPrefab != null)
		{
			SpawnableTool component = spawnableToolPrefab.GetComponent<SpawnableTool>();
			if (component != null)
			{
				return component.PrefabId;
			}
		}
		return Guid.Empty;
	}

	public static SpawnableToolConfig.Config GetSpawnableToolConfig(Guid prefabId)
	{
		CollectGuidMappings();
		if (PersistenceGuidToConfigMap.TryGetValue(prefabId, out var value))
		{
			return value;
		}
		return null;
	}

	public static string GetSpawnableToolPrefabName(Guid prefabId)
	{
		CollectGuidMappings();
		Tool spawnableToolPrefab = GetSpawnableToolPrefab(prefabId);
		if (spawnableToolPrefab != null)
		{
			return spawnableToolPrefab.name;
		}
		return null;
	}

	public static Tool GetSpawnableToolPrefab(Guid prefabId)
	{
		CollectGuidMappings();
		if (PersistenceGuidToConfigMap.TryGetValue(prefabId, out var value) && value != null && value.Prefab != null)
		{
			return value.Prefab;
		}
		return null;
	}

	public static SpawnableToolType GetSpawnableToolType(Guid prefabId)
	{
		Tool spawnableToolPrefab = GetSpawnableToolPrefab(prefabId);
		if (spawnableToolPrefab != null)
		{
			SpawnableTool component = spawnableToolPrefab.GetComponent<SpawnableTool>();
			if (component != null)
			{
				return component.Type;
			}
		}
		return SpawnableToolType.INVALID;
	}

	public static Tool GetSpawnableToolPrefab(SpawnableToolType spawnableToolType)
	{
		return GetSpawnableToolConfig(spawnableToolType)?.Prefab;
	}

	public static string GetSpawnableToolPrefabName(SpawnableToolType spawnableToolType)
	{
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableToolType);
		if (spawnableToolConfig != null && spawnableToolConfig.Prefab != null)
		{
			return spawnableToolConfig.Prefab.name;
		}
		return null;
	}

	public static string GetSpawnableToolFriendlyName(SpawnableToolType spawnableToolType)
	{
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableToolType);
		if (spawnableToolConfig != null)
		{
			return spawnableToolConfig.FriendlyName;
		}
		return "None";
	}

	public static string GetSpawnableToolDescription(SpawnableToolType spawnableToolType)
	{
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableToolType);
		if (spawnableToolConfig != null)
		{
			return spawnableToolConfig.Description;
		}
		return string.Empty;
	}

	public static Color GetSpawnableToolColorOverride(SpawnableToolType spawnableToolType)
	{
		return GetSpawnableToolConfig(spawnableToolType)?.ColorOverride ?? Color.clear;
	}

	public static GameTeam GetSpawnableToolTeamOverride(SpawnableToolType spawnableToolType)
	{
		return GetSpawnableToolConfig(spawnableToolType)?.TeamOverride ?? GameTeam.ANY;
	}

	public static Quaternion GetSpawnableToolSpawnRotation(SpawnableToolType spawnableToolType)
	{
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableToolType);
		if (spawnableToolConfig != null)
		{
			return Quaternion.Euler(spawnableToolConfig.SpawnRotation);
		}
		return Quaternion.identity;
	}

	public static string[] GetSpawnableToolDefaultTags(SpawnableToolType spawnableToolType)
	{
		SpawnableToolConfig.Config spawnableToolConfig = GetSpawnableToolConfig(spawnableToolType);
		if (spawnableToolConfig != null)
		{
			return spawnableToolConfig.DefaultTagNames;
		}
		return new string[0];
	}

	public static SpawnableToolType GetSpawnableToolConfigType(SpawnableToolConfig.Config spawnableToolConfig)
	{
		if (ConfigAsset != null && ConfigAsset.Configs != null)
		{
			for (int i = 0; i < ConfigAsset.Configs.Length; i++)
			{
				if (ConfigAsset.Configs[i] == spawnableToolConfig)
				{
					return (SpawnableToolType)i;
				}
			}
		}
		return SpawnableToolType.INVALID;
	}

	public static SpawnableToolConfig.Config GetSpawnableToolConfig(SpawnableToolType spawnableToolType)
	{
		if (ConfigAsset != null && ConfigAsset.Configs != null && spawnableToolType >= SpawnableToolType.PAINTBALL_PISTOL && (int)spawnableToolType < ConfigAsset.Configs.Length)
		{
			return ConfigAsset.Configs[(int)spawnableToolType];
		}
		return null;
	}

	public static Tool GetSpawnableToolPrefab(string prefabName)
	{
		return GetSpawnableToolConfig(prefabName)?.Prefab;
	}

	public static SpawnableToolType GetSpawnableToolType(string prefabName)
	{
		Tool spawnableToolPrefab = GetSpawnableToolPrefab(prefabName);
		if (spawnableToolPrefab != null)
		{
			SpawnableTool component = spawnableToolPrefab.GetComponent<SpawnableTool>();
			if (component != null)
			{
				return component.Type;
			}
		}
		return SpawnableToolType.INVALID;
	}

	public static SpawnableToolConfig.Config GetSpawnableToolConfig(string prefabName)
	{
		if (ConfigAsset != null && ConfigAsset.Configs != null)
		{
			return ConfigAsset.Configs.FirstOrDefault((SpawnableToolConfig.Config e) => e.Prefab.name == prefabName);
		}
		return null;
	}

	public static int GetSpawnableToolSandboxResourceCost(SpawnableToolType spawnableToolType)
	{
		CollectGuidMappings();
		return GetSpawnableToolConfig(spawnableToolType)?.SandboxResourceCost ?? 0;
	}

	public static int GetSpawnableToolSandboxResourceCost(Guid prefabId)
	{
		CollectGuidMappings();
		if (PersistenceGuidToConfigMap.TryGetValue(prefabId, out var value) && value != null)
		{
			return value.SandboxResourceCost;
		}
		return 0;
	}

	private static void CollectGuidMappings()
	{
		if ((PersistenceGuidToConfigMap != null && PersistenceGuidToConfigMap.Count != 0) || !(ConfigAsset != null) || ConfigAsset.Configs == null)
		{
			return;
		}
		PersistenceGuidToConfigMap = new Dictionary<Guid, SpawnableToolConfig.Config>();
		SpawnableToolConfig.Config[] configs = ConfigAsset.Configs;
		foreach (SpawnableToolConfig.Config config in configs)
		{
			if (config != null && config.Prefab != null)
			{
				SpawnableTool component = config.Prefab.GetComponent<SpawnableTool>();
				if (component != null)
				{
					PersistenceGuidToConfigMap[component.PrefabId] = config;
				}
			}
		}
	}

	public static IEnumerable<SpawnableToolType> GetCustomGameEquipmentSet(SpawnableToolConfig.CustomGameEquipmentSet set, params SpawnableToolType[] ignoreTypes)
	{
		if (ConfigAsset == null)
		{
			return new SpawnableToolType[0];
		}
		return from type in ConfigAsset.Configs.Where((SpawnableToolConfig.Config config) => config.AvailableInCustomGameSets.Contains(set)).Select(GetSpawnableToolConfigType)
			where !ignoreTypes.Contains(type)
			select type;
	}
}
