public class Flag : Photon.MonoBehaviour
{
	public delegate void FlagAtGoal(Flag thisFlag, GameTeam goalTeam, Player capturePlayer);

	public delegate void FlagRelease(Flag thisFlag, Player dropPlayer);

	public delegate void FlagPickup(Flag thisFlag, Player pickupPlayer);

	public delegate void FlagReset(Flag thisFlag);

	[Header("Team")]
	[SerializeField]
	private GameTeam team = GameTeam.ANY;

	[Header("Mode")]
	[SerializeField]
	private GameModeType mode;

	[Header("Beam")]
	[SerializeField]
	private Renderer beamRenderer;

	[Header("Flag")]
	[SerializeField]
	private Transform flagRoot;

	[SerializeField]
	private Transform flagStandinRoot;

	[SerializeField]
	private float flagStandinMaxScale = 0.95f;

	private SynchronizedField<bool> _atHomeGoal;

	private SynchronizedField<bool> _atEnemyGoal;

	private SynchronizedField<GameTeam> _enemyGoalTeam;

	private TeamColorRenderer teamColor;

	private List<FlagGoal> homeGoals = new List<FlagGoal>();

	private List<FlagGoal> enemyGoals = new List<FlagGoal>();

	public FlagAtGoal FlagAtGoalEvent;

	public FlagRelease FlagReleaseEvent;

	public FlagPickup FlagPickupEvent;

	public FlagReset FlagResetEvent;

	public GameTeam Team => team;

	public GameModeType Mode => mode;

	public bool AtHomeGoal
	{
		get
		{
			return _atHomeGoal.Get();
		}
		private set
		{
			_atHomeGoal.Set(value);
		}
	}

	public bool AtEnemyGoal
	{
		get
		{
			return _atEnemyGoal.Get();
		}
		private set
		{
			_atEnemyGoal.Set(value);
		}
	}

	public GameTeam EnemyGoalTeam
	{
		get
		{
			return _enemyGoalTeam.Get();
		}
		private set
		{
			_enemyGoalTeam.Set(value);
		}
	}

	public Tool Tool { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		teamColor = GetComponent<TeamColorRenderer>();
		Tool = GetComponent<Tool>();
		if (Tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
		}
		else
		{
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PostReleaseEvent += OnPostRelease;
			Tool.PostResetEvent += OnReset;
			Tool.KinematicOnReset = true;
		}
		_atHomeGoal = new SynchronizedField<bool>(this, "AT_HOME_GOAL", defaultValue: false, SetterPermissionMode.AUTHORITY);
		_atEnemyGoal = new SynchronizedField<bool>(this, "AT_ENEMY_GOAL", defaultValue: false, SetterPermissionMode.AUTHORITY);
		_enemyGoalTeam = new SynchronizedField<GameTeam>(this, "ENEMY_GOAL_TEAM", GameTeam.ANY, SetterPermissionMode.AUTHORITY);
		List<FlagGoal> list = this.FindAllObjectsOfType<FlagGoal>();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].Mode == Mode)
			{
				if (list[i].Team == team)
				{
					homeGoals.Add(list[i]);
				}
				else
				{
					enemyGoals.Add(list[i]);
				}
			}
		}
		OnToolScaleChanged(Tool);
	}

	private void OnToolScaleChanged(Tool thisTool)
	{
		if (flagRoot != null && flagStandinRoot != null)
		{
			bool flag = base.transform.lossyScale.x <= flagStandinMaxScale;
			flagStandinRoot.gameObject.SetActive(flag);
			flagRoot.gameObject.SetActive(!flag);
		}
	}

	private void Start()
	{
		ProcessCreationObjectOverrides();
		UpdateTeamColor();
	}

	private void OnDisable()
	{
		if (base.hasAuthority)
		{
			AtEnemyGoal = false;
			AtHomeGoal = false;
		}
	}

	private void Update()
	{
		beamRenderer.enabled = true;
		Vector3 position;
		if (Tool.IsHeld && Tool.Owner != null)
		{
			if (Tool.Owner == Player.LocalPlayer)
			{
				beamRenderer.enabled = false;
			}
			position = Tool.Owner.CurrentFloorPosition;
		}
		else if (!TryGetBeamPosition(out position))
		{
			position = base.transform.position;
		}
		beamRenderer.transform.position = position;
		beamRenderer.transform.rotation = Quaternion.LookRotation(Vector3.up);
		if (!base.hasAuthority)
		{
			return;
		}
		bool atEnemyGoal = AtEnemyGoal;
		GameTeam atGoalTeam;
		bool flag = IsAtGoal(enemyGoals, out atGoalTeam);
		if (flag != atEnemyGoal)
		{
			EnemyGoalTeam = atGoalTeam;
			AtEnemyGoal = flag;
			if (flag && FlagAtGoalEvent != null)
			{
				FlagAtGoalEvent(this, EnemyGoalTeam, Tool.Owner);
			}
		}
		bool atHomeGoal = AtHomeGoal;
		GameTeam atGoalTeam2;
		bool flag2 = IsAtGoal(homeGoals, out atGoalTeam2);
		if (atHomeGoal != flag2)
		{
			AtHomeGoal = flag2;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		if (base.hasAuthority && FlagPickupEvent != null)
		{
			FlagPickupEvent(this, tool.HolderPlayer);
		}
	}

	private void OnPostRelease(Tool tool)
	{
		if (base.hasAuthority && FlagReleaseEvent != null)
		{
			FlagReleaseEvent(this, tool.HolderPlayer);
		}
	}

	private void OnReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		if (wasCleanedUp && FlagResetEvent != null)
		{
			FlagResetEvent(this);
		}
	}

	private bool IsAtGoal(List<FlagGoal> goals, out GameTeam atGoalTeam)
	{
		bool result = false;
		atGoalTeam = GameTeam.ANY;
		for (int i = 0; i < goals.Count; i++)
		{
			if (goals[i].gameObject.activeSelf && Vector3.ProjectOnPlane(goals[i].transform.position - base.transform.position, Vector3.up).sqrMagnitude <= goals[i].Radius * goals[i].Radius)
			{
				result = true;
				atGoalTeam = goals[i].Team;
				break;
			}
		}
		return result;
	}

	private bool TryGetBeamPosition(out Vector3 position)
	{
		if (Physics.Raycast(base.transform.position + Vector3.up * 0.1f, -Vector3.up, out var hitInfo, float.MaxValue, 2048, QueryTriggerInteraction.Ignore))
		{
			position = hitInfo.point;
			return true;
		}
		position = Vector3.zero;
		return false;
	}

	private void UpdateTeamColor()
	{
		if (teamColor != null)
		{
			teamColor.Team = team;
			if (beamRenderer != null)
			{
				Color color = teamColor.Color;
				float a = beamRenderer.material.GetColor("_TintColor").a;
				color.a = a;
				beamRenderer.material.SetColor("_TintColor", color);
			}
		}
	}

	private void ProcessCreationObjectOverrides()
	{
		if (Tool.CreationObject.TeamOverride.HasValue)
		{
			team = Tool.CreationObject.TeamOverride.Value;
		}
		else
		{
			Tool.CreationObject.TeamOverride = team;
		}
	}
}
namespace RecRoom.Core
{
	public sealed class GiftBox : Photon.MonoBehaviour
	{
		private struct RigidbodyFixer
		{
			public Rigidbody Rigidbody;

			public Vector3 LocalPosition;

			public Quaternion LocalRotation;
		}

		public const float DEFAULT_CLOSE_TO_PLAYER_DISTANCE = 2.2f;

		private List<RigidbodyFixer> rigidbodyFixers = new List<RigidbodyFixer>();

		private static readonly Vector3 GiftSpawnPosition = new Vector3(0f, 0f, 0f);

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private BaseOpenableChest chest;

		[SerializeField]
		private GiftBoxEquipmentContainer toolContainer;

		[SerializeField]
		private PooledParticle xpBoxOpenedParticlePrefab;

		[SerializeField]
		private PooledParticle itemBoxOpenedParticlePrefab;

		[SerializeField]
		private Transform boxOpenedParticleRoot;

		[SerializeField]
		private Transform toolAnchor;

		[SerializeField]
		private Text xpText;

		[SerializeField]
		private Text nameTagText;

		[SerializeField]
		private Text labelText;

		[SerializeField]
		private float remotePlayerXpBonusDistance = 7f;

		[SerializeField]
		private Animator toolAnchorAnimator;

		[SerializeField]
		private float timeBeforeDerez = 2f;

		[SerializeField]
		private RecRoomAudioClip boxAppearAudio;

		[Tooltip("XP box | Outfit item | Equipment item")]
		[SerializeField]
		private RecRoomAudioClip[] boxOpenAudio = new RecRoomAudioClip[3];

		[SerializeField]
		private Renderer[] variantMaterialRenderers;

		private Avatars.GiftPackage giftPackage;

		private PhotonPlayer giftOwner;

		private PlayerSpawnedEquipment spawnedEquipment;

		private SynchronizedField<GiftManager.GiftBoxContents> _boxContents;

		private SynchronizedField<int> _boxContentViewId;

		public float CloseToPlayerDistance = 2.2f;

		public Action<GiftBox> OnGiftBoxDestroyed;

		public static Action<GiftBox> OnLocalGiftBoxOpened = null;

		public Vector3 spawnPosition { get; set; }

		public Transform ToolAnchor => toolAnchor;

		public bool IsOwnerLocal => giftOwner != null && giftOwner.IsLocal;

		public GiftManager.GiftBoxContents BoxContents
		{
			get
			{
				return _boxContents.Get();
			}
			private set
			{
				_boxContents.Set(value);
			}
		}

		public int BoxContentViewId
		{
			get
			{
				return _boxContentViewId.Get();
			}
			private set
			{
				_boxContentViewId.Set(value);
			}
		}

		public bool CloseToPlayer => Player.LocalPlayerExists && (Player.LocalPlayer.CurrentFloorPosition - base.transform.position).magnitude <= CloseToPlayerDistance;

		protected override void Awake()
		{
			base.Awake();
			BaseOpenableChest baseOpenableChest = chest;
			baseOpenableChest.OpeningEvent = (BaseOpenableChest.ChestAction)Delegate.Combine(baseOpenableChest.OpeningEvent, new BaseOpenableChest.ChestAction(OnChestOpening));
			BaseOpenableChest baseOpenableChest2 = chest;
			baseOpenableChest2.OpenEvent = (BaseOpenableChest.ChestAction)Delegate.Combine(baseOpenableChest2.OpenEvent, new BaseOpenableChest.ChestAction(OnChestOpen));
			_boxContents = new SynchronizedField<GiftManager.GiftBoxContents>(this, "GC", GiftManager.GiftBoxContents.Unspecified, SetterPermissionMode.AUTHORITY);
			_boxContentViewId = new SynchronizedField<int>(this, "GCV", -1, SetterPermissionMode.AUTHORITY);
			Dictionary<string, object> dictionary = base.photonView.instantiationData[1] as Dictionary<string, object>;
			int iD = (int)dictionary["Owner"];
			giftOwner = PhotonPlayer.Find(iD);
			string json = (string)dictionary["GiftJSON"];
			try
			{
				Dictionary<string, object> dict = AmplitudeMiniJSON.Json.Deserialize(json) as Dictionary<string, object>;
				giftPackage = Util.Deserialize<Avatars.GiftPackage>(dict);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				giftPackage = null;
			}
			GiftManager.GiftRarity rarity = ((giftPackage != null) ? giftPackage.GiftRarity : GiftManager.GiftRarity.Common);
			RarityController[] componentsInChildren = GetComponentsInChildren<RarityController>(includeInactive: true);
			foreach (RarityController rarityController in componentsInChildren)
			{
				rarityController.SetRarity(rarity);
			}
			SetMaterialForGiftPackage(giftPackage);
			SetLabelForGiftPackage(giftPackage);
			if (giftPackage != null && IsOwnerLocal)
			{
				OutfitSelection outfitSelection = OutfitSelection.Parse(giftPackage.AvatarItemDesc);
				if (outfitSelection != null)
				{
					OutfitTool outfitTool = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitToolForLocalPlayer(outfitSelection, PlayerSpawnedEquipment.Purpose.GiftBox, giftPackage.Level);
					Tool tool = outfitTool.Tool;
					spawnedEquipment = tool.PlayerSpawnedEquipment;
					tool.transform.position = GiftSpawnPosition;
					BoxContents = GiftManager.GiftBoxContents.Avatar;
					InitializeRigidbodyFixers();
				}
				else if (!string.IsNullOrEmpty(giftPackage.EquipmentPrefabName))
				{
					Equipment selection = Equipment.Create(giftPackage.EquipmentPrefabName, giftPackage.EquipmentModificationGuid, giftPackage.Level);
					Tool tool2 = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentForLocalPlayer(selection, GiftSpawnPosition, Quaternion.identity, 1f, PlayerSpawnedEquipment.Purpose.GiftBox, giftPackage.Level);
					spawnedEquipment = tool2.PlayerSpawnedEquipment;
					BoxContents = GiftManager.GiftBoxContents.Equipment;
				}
				else if (!string.IsNullOrEmpty(giftPackage.ConsumableItemDesc))
				{
					Tool tool3 = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.SpawnConsumableForLocalPlayer(giftPackage.ConsumableItemDesc, null, GiftSpawnPosition, Quaternion.identity, 1f, PlayerSpawnedEquipment.Purpose.GiftBox, giftPackage.Level);
					spawnedEquipment = tool3.PlayerSpawnedEquipment;
					BoxContents = GiftManager.GiftBoxContents.Consumable;
					InitializeRigidbodyFixers();
				}
				else if (giftPackage.CurrencyType != CurrencyType.Invalid && giftPackage.Currency > 0)
				{
					BoxContents = GiftManager.GiftBoxContents.Currency;
				}
				else if (giftPackage.Xp > 0)
				{
					BoxContents = GiftManager.GiftBoxContents.XP;
				}
				if (spawnedEquipment != null)
				{
					spawnedEquipment.Tool.IsEnabled = false;
				}
			}
			if (xpText != null)
			{
				xpText.text = string.Empty;
			}
			if (nameTagText != null)
			{
				nameTagText.text = giftOwner.NickName.Truncate(16, "...");
			}
		}

		private void Update()
		{
			if (!chest.IsOpen || !toolAnchorAnimator.enabled)
			{
				return;
			}
			foreach (RigidbodyFixer rigidbodyFixer in rigidbodyFixers)
			{
				if (rigidbodyFixer.Rigidbody != null)
				{
					rigidbodyFixer.Rigidbody.transform.localPosition = rigidbodyFixer.LocalPosition;
					rigidbodyFixer.Rigidbody.transform.localRotation = rigidbodyFixer.LocalRotation;
				}
			}
		}

		private void InitializeRigidbodyFixers()
		{
			if (rigidbodyFixers.Count == 0 && spawnedEquipment != null)
			{
				Rigidbody[] componentsInChildren = spawnedEquipment.GetComponentsInChildren<Rigidbody>();
				foreach (Rigidbody rigidbody in componentsInChildren)
				{
					RigidbodyFixer item = new RigidbodyFixer
					{
						Rigidbody = rigidbody,
						LocalPosition = rigidbody.transform.localPosition,
						LocalRotation = rigidbody.transform.localRotation
					};
					rigidbodyFixers.Add(item);
				}
			}
		}

		private void SetLabelForGiftPackage(Avatars.GiftPackage giftPackage)
		{
			if (labelText != null)
			{
				if (giftPackage != null && !string.IsNullOrEmpty(giftPackage.Message))
				{
					labelText.text = giftPackage.Message;
				}
				else
				{
					labelText.canvas.gameObject.SetActive(value: false);
				}
			}
		}

		private void SetMaterialForGiftPackage(Avatars.GiftPackage giftPackage)
		{
			if (giftPackage != null)
			{
				Material material = ((!(giftPackage.PackageMaterial != null)) ? SingletonMonoBehaviour<GiftManager>.Instance.DefaultGiftBoxMaterial : giftPackage.PackageMaterial);
				Renderer[] array = variantMaterialRenderers;
				foreach (Renderer renderer in array)
				{
					renderer.material = material;
				}
			}
		}

		private void Start()
		{
			chest.OnlyInteractionAllowedPlayer = giftOwner;
			if (boxOpenAudio != null)
			{
				AudioManager.Play3DSFX(boxAppearAudio, base.transform);
			}
			if (IsOwnerLocal && spawnedEquipment != null)
			{
				BoxContentViewId = spawnedEquipment.photonView.viewID;
			}
		}

		protected override void OnDestroy()
		{
			if (chest != null)
			{
				BaseOpenableChest baseOpenableChest = chest;
				baseOpenableChest.OpeningEvent = (BaseOpenableChest.ChestAction)Delegate.Remove(baseOpenableChest.OpeningEvent, new BaseOpenableChest.ChestAction(OnChestOpening));
				BaseOpenableChest baseOpenableChest2 = chest;
				baseOpenableChest2.OpenEvent = (BaseOpenableChest.ChestAction)Delegate.Remove(baseOpenableChest2.OpenEvent, new BaseOpenableChest.ChestAction(OnChestOpen));
			}
			if (OnGiftBoxDestroyed != null)
			{
				OnGiftBoxDestroyed(this);
			}
			DetatchAndDestroyContents();
			base.OnDestroy();
		}

		private void DetatchAndDestroyContents()
		{
			if (!(spawnedEquipment != null))
			{
				return;
			}
			spawnedEquipment.photonView.OnPreDestroyOfRuntimeParentedPhotonView -= PrepareForPhotonDestroy;
			if (!spawnedEquipment.Tool.IsHeld)
			{
				spawnedEquipment.Tool.SetParentTransform(null, worldPositionStays: true);
			}
			if (spawnedEquipment.IsMine)
			{
				spawnedEquipment.PickupAttemptEvent -= OnToolPickupAttempt;
				if (!spawnedEquipment.Tool.IsHeld)
				{
					PhotonNetwork.Destroy(spawnedEquipment.photonView);
					spawnedEquipment = null;
				}
			}
		}

		private void PrepareForPhotonDestroy()
		{
			DetatchAndDestroyContents();
		}

		private void OnChestOpening(BaseOpenableChest chest)
		{
			if (IsOwnerLocal && giftPackage != null && giftPackage.PackageVariant.dequeueBehavior != GiftPackageVariant.DequeueBehaviors.ConsumeImmediately)
			{
				SingletonMonoBehaviour<GiftManager>.Instance.StartCoroutine(SingletonMonoBehaviour<GiftManager>.Instance.RunConsumeGift(giftPackage, delegate
				{
				}));
			}
		}

		private void OnChestOpen(BaseOpenableChest chest)
		{
			if (giftPackage != null)
			{
				ApplyGiftPackageXp();
			}
			toolAnchorAnimator.SetTrigger("Spawn");
			Tool tool = Tool.Find(BoxContentViewId);
			if (IsOwnerLocal && tool != null)
			{
				tool.IsEnabled = true;
			}
			spawnedEquipment = ((!(tool != null)) ? null : tool.PlayerSpawnedEquipment);
			if (spawnedEquipment != null)
			{
				toolContainer.AttachTool(spawnedEquipment.Tool);
				spawnedEquipment.Tool.AddCustomPickupCondition(CustomGiftToolPickupCondition);
				spawnedEquipment.Tool.SuppressAnimateInOut = true;
				InitializeRigidbodyFixers();
				spawnedEquipment.photonView.OnPreDestroyOfRuntimeParentedPhotonView += PrepareForPhotonDestroy;
				if (spawnedEquipment.Tool.IsEnabled && !base.gameObject.activeSelf)
				{
					base.gameObject.SetActive(value: true);
				}
				if (IsOwnerLocal)
				{
					spawnedEquipment.PickupAttemptEvent += OnToolPickupAttempt;
				}
			}
			else
			{
				if (giftPackage != null && xpText != null)
				{
					if (giftPackage.CurrencyType != CurrencyType.Invalid && giftPackage.Currency > 0)
					{
						xpText.text = SingletonMonoBehaviour<CurrencyManager>.Instance.ToCurrencyString(giftPackage.Currency, giftPackage.CurrencyType);
						xpText.canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
						SingletonMonoBehaviour<CurrencyManager>.Instance.ReceiveCurrencyAwardFromGiftBox(giftOwner.ToPlayer(), giftPackage.Currency, giftPackage.CurrencyType, boxOpenedParticleRoot.position, boxOpenedParticleRoot.rotation);
					}
					else
					{
						xpText.text = giftPackage.Xp + " XP";
						xpText.canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
					}
				}
				if (IsOwnerLocal)
				{
					StartCoroutine(DismissBox());
				}
			}
			if (IsOwnerLocal && OnLocalGiftBoxOpened != null)
			{
				OnLocalGiftBoxOpened(this);
			}
			PlayBoxOpenEffects();
		}

		private void ApplyGiftPackageXp()
		{
			if (giftPackage != null && giftPackage.Xp > 0 && Player.LocalPlayerExists && (IsOwnerLocal || (Player.LocalPlayer.CurrentFloorPosition - base.transform.position).magnitude <= remotePlayerXpBonusDistance))
			{
				int additionalXp = Mathf.CeilToInt((float)giftPackage.Xp * ((!IsOwnerLocal) ? 0.1f : 1f));
				SingletonMonoBehaviour<ProgressionManager>.Instance.LocalCompleteObjective(ProgressionManager.ObjectiveType.Default, 1f, GameSessions.LocalGameSession?.RoomId, additionalXp);
			}
		}

		private void OnToolPickupAttempt(PlayerSpawnedEquipment spawnedEquipment)
		{
			if (IsOwnerLocal && this.spawnedEquipment != null)
			{
				spawnedEquipment.Tool.SuppressAnimateInOut = false;
				spawnedEquipment.photonView.OnPreDestroyOfRuntimeParentedPhotonView -= PrepareForPhotonDestroy;
				toolAnchorAnimator.enabled = false;
				StartCoroutine(DismissBox());
			}
		}

		private bool CustomGiftToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return thisTool.Owner != null && thisTool.Owner == selectingPlayer;
		}

		private void PlayBoxOpenEffects()
		{
			PooledParticle pooledParticle = null;
			if ((BoxContents == GiftManager.GiftBoxContents.Avatar || BoxContents == GiftManager.GiftBoxContents.Equipment) && itemBoxOpenedParticlePrefab != null)
			{
				pooledParticle = ObjectPool.Instance.Acquire(itemBoxOpenedParticlePrefab);
			}
			else if (BoxContents == GiftManager.GiftBoxContents.XP)
			{
				pooledParticle = ObjectPool.Instance.Acquire(xpBoxOpenedParticlePrefab);
			}
			if (pooledParticle != null)
			{
				pooledParticle.Play(boxOpenedParticleRoot.position, boxOpenedParticleRoot.rotation);
			}
			if (BoxContents != GiftManager.GiftBoxContents.Unspecified && boxOpenAudio != null && boxOpenAudio.Length > (int)BoxContents)
			{
				RecRoomAudioClip recRoomAudioClip = boxOpenAudio[(int)BoxContents];
				if (recRoomAudioClip != null)
				{
					AudioManager.Play3DSFX(recRoomAudioClip, base.transform.position);
				}
			}
		}

		private IEnumerator DismissBox()
		{
			yield return new WaitForSeconds(timeBeforeDerez);
			PhotonNetwork.Destroy(base.gameObject);
		}
	}
}
public abstract class GroupSearch : UnityEngine.MonoBehaviour
{
	private Collider[] overlapTestColliders;

	protected virtual void Awake()
	{
		overlapTestColliders = new Collider[256];
	}

	public ToolGroup FindGroup(ToolGroupElement thisGroupableTool = null, ToolGroup thisGroup = null)
	{
		ToolGroup result = null;
		int num = UpdateOverlapTest(testTriggers: false);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = overlapTestColliders[i].GetColliderTool();
			ToolGroup toolGroup = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<ToolGroup>());
			if (toolGroup != null && toolGroup != thisGroup && toolGroup.Size > 0 && (thisGroupableTool == null || toolGroup.CanAddChild(thisGroupableTool)) && (thisGroup == null || toolGroup.CanAddGroup(thisGroup)))
			{
				result = toolGroup;
				break;
			}
		}
		return result;
	}

	public ToolGroupElement FindGroupableTool(ToolGroupElement thisGroupableTool = null)
	{
		ToolGroupElement result = null;
		int num = UpdateOverlapTest(testTriggers: true);
		for (int i = 0; i < num; i++)
		{
			Tool colliderTool = overlapTestColliders[i].GetColliderTool();
			ToolGroupElement toolGroupElement = ((!(colliderTool != null)) ? null : colliderTool.GetComponent<ToolGroupElement>());
			if (toolGroupElement != null && toolGroupElement != thisGroupableTool && !toolGroupElement.IsInGroup && (thisGroupableTool == null || toolGroupElement.CanAddTool(thisGroupableTool)))
			{
				result = toolGroupElement;
				break;
			}
		}
		return result;
	}

	protected abstract void GetOverlapGeometry(out Vector3 center, out Vector3 size);

	protected int UpdateOverlapTest(bool testTriggers)
	{
		GetOverlapGeometry(out var center, out var size);
		center = base.transform.TransformPoint(center);
		size = base.transform.lossyScale.MultiplyComponents(size);
		return Physics.OverlapBoxNonAlloc(center, size / 2f, overlapTestColliders, base.transform.rotation, 495330304, (!testTriggers) ? QueryTriggerInteraction.Ignore : QueryTriggerInteraction.Collide);
	}

	private void OnDrawGizmos()
	{
		GetOverlapGeometry(out var center, out var size);
		Gizmos.color = Color.red;
		Matrix4x4 matrix = Matrix4x4.TRS(base.transform.TransformPoint(center), base.transform.rotation, base.transform.lossyScale.MultiplyComponents(size));
		Gizmos.matrix = matrix;
		Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		Gizmos.matrix = Matrix4x4.identity;
	}
}
public class GroupSearchBoxCollider : GroupSearch
{
	[SerializeField]
	private BoxCollider overlapCollider;

	protected override void Awake()
	{
		base.Awake();
		overlapCollider.isTrigger = true;
		overlapCollider.enabled = false;
	}

	protected override void GetOverlapGeometry(out Vector3 center, out Vector3 size)
	{
		center = overlapCollider.center;
		size = overlapCollider.size;
	}
}
public class GroupSearchCustomGeometry : GroupSearch
{
	[SerializeField]
	private Vector3 buffer = new Vector3(0.02f, 0.02f, 0.02f);

	[NonSerialized]
	public Vector3 Center;

	[NonSerialized]
	public Vector3 Size;

	protected override void GetOverlapGeometry(out Vector3 center, out Vector3 size)
	{
		center = Center;
		size = Size + buffer;
	}
}
public class HandheldCamera : Photon.MonoBehaviour
{
	[Header("Camera")]
	[SerializeField]
	private Camera camera;

	[SerializeField]
	private Transform lensTransform;

	[SerializeField]
	private Vector2 lowResolution = new Vector2(320f, 180f);

	[SerializeField]
	private Vector2 highResolution = new Vector2(640f, 360f);

	[SerializeField]
	private bool hideOwner = true;

	[Header("Screens")]
	[SerializeField]
	private Renderer[] screenRenderers;

	[SerializeField]
	private Renderer externalScreenRenderer;

	[SerializeField]
	private Material screenRenderMaterial;

	[SerializeField]
	private Material defaultScreenMaterial;

	[Header("Smoothing")]
	[SerializeField]
	private float positionSmoothingTime = 0.25f;

	[Header("Capture Feedback")]
	[SerializeField]
	private GameObject recordingFeedback;

	[SerializeField]
	private Slider recordingProgressFeedback;

	[SerializeField]
	private GameObject exportingFeedback;

	[SerializeField]
	private Text savedFeedback;

	private RenderTexture renderTexture;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private bool? usingHighResolution;

	private float aspect = 1f;

	private VideoCapture videoCapture;

	private Material screenRenderMaterialCopy;

	private Animator animator;

	private static readonly int triggerId = Animator.StringToHash("Trigger");

	private static readonly int screenAnimationId = Animator.StringToHash("ScreenOpen");

	private float triggerAmount;

	private bool screenOpen;

	[NonSerialized]
	public bool RemoteControl;

	public Tool Tool { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		aspect = lowResolution.x / lowResolution.y;
		videoCapture = GetComponent<VideoCapture>();
		if (videoCapture != null)
		{
			videoCapture.RecordingCamera = camera;
			videoCapture.CaptureStartedEvent += OnCaptureStarted;
			videoCapture.ExportStartedEvent += OnExportStarted;
			videoCapture.ExportFinishedEvent += OnExportFinished;
		}
		exportingFeedback.SetActive(value: false);
		recordingFeedback.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		savedFeedback.gameObject.SetActive(value: false);
		screenRenderMaterialCopy = new Material(screenRenderMaterial);
		animator = GetComponentInChildren<Animator>();
		Tool = GetComponent<Tool>();
		if (Tool != null)
		{
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PostReleaseEvent += OnPostRelease;
			Tool.InputUpEvent += OnInputUp;
			Tool.InputDownEvent += OnInputDown;
			Tool.InputCancelledEvent += OnInputCancelled;
		}
	}

	private void Start()
	{
		camera.aspect = aspect;
		camera.gameObject.name = base.gameObject.name + "_Camera";
		camera.transform.SetParent(null, worldPositionStays: true);
		SwitchTextureResolution(useHighResolution: false);
		if (externalScreenRenderer != null)
		{
			externalScreenRenderer.material = screenRenderMaterialCopy;
		}
		OpenScreen(Tool != null && Tool.IsHeld);
	}

	private void SwitchTextureResolution(bool useHighResolution)
	{
		if (!usingHighResolution.HasValue || usingHighResolution.Value != useHighResolution)
		{
			usingHighResolution = useHighResolution;
			Vector2 vector = ((!useHighResolution) ? lowResolution : highResolution);
			renderTexture = new RenderTexture((int)vector.x, (int)vector.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			if (camera != null)
			{
				camera.targetTexture = renderTexture;
			}
			screenRenderMaterialCopy.mainTexture = renderTexture;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		if (hideOwner && tool.HolderPlayer == Player.LocalPlayer)
		{
			camera.cullingMask &= -257;
		}
		OpenScreen(open: true);
	}

	private void OnPostRelease(Tool tool)
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
		if (hideOwner && tool.HolderPlayer == Player.LocalPlayer)
		{
			camera.cullingMask |= 256;
		}
		OpenScreen(open: false);
	}

	private void OnInputDown(Tool thisTool)
	{
		if (base.hasAuthority)
		{
			StartCapturing();
		}
	}

	private void OnInputUp(Tool tool)
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	private void OnUnlock(Tool tool)
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	private void OnInputCancelled(Tool tool)
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	private void OnDisable()
	{
		if (base.hasAuthority)
		{
			FinishCapturing();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PostReleaseEvent += OnPostRelease;
			Tool.InputUpEvent += OnInputUp;
			Tool.InputDownEvent += OnInputDown;
			Tool.InputCancelledEvent += OnInputCancelled;
		}
		if (videoCapture != null)
		{
			videoCapture.CaptureStartedEvent -= OnCaptureStarted;
			videoCapture.ExportStartedEvent -= OnExportStarted;
			videoCapture.ExportFinishedEvent -= OnExportFinished;
		}
		if (renderTexture != null)
		{
			UnityEngine.Object.Destroy(renderTexture);
		}
		if (camera != null)
		{
			UnityEngine.Object.Destroy(camera.gameObject);
		}
	}

	private void Update()
	{
		if (!RemoteControl)
		{
			camera.transform.position = Vector3.SmoothDamp(camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
			camera.transform.rotation = UnityExtensions.SmoothDamp(camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
		}
		else
		{
			camera.transform.position = lensTransform.position;
			camera.transform.rotation = lensTransform.rotation;
		}
		if (base.hasAuthority)
		{
			SetTrigger((!(Tool != null)) ? 0f : Tool.InputAmount);
			UpdateCapture();
		}
	}

	private void OnRenderImage(RenderTexture src, RenderTexture dest)
	{
		Graphics.Blit(renderTexture, dest);
	}

	public void StartCapturing()
	{
		SwitchTextureResolution(useHighResolution: true);
		if (videoCapture != null && !videoCapture.IsCapturing)
		{
			videoCapture.StartCapture();
		}
	}

	public void FinishCapturing()
	{
		if (videoCapture != null && videoCapture.IsCapturing)
		{
			videoCapture.FinishCapture();
			videoCapture.SaveToDisk();
		}
		SwitchTextureResolution(useHighResolution: false);
	}

	private void UpdateCapture()
	{
		if (!(videoCapture != null) || !videoCapture.IsCapturing)
		{
			return;
		}
		if (!RemoteControl && Tool != null && !Tool.IsHeld)
		{
			FinishCapturing();
			return;
		}
		float num = videoCapture.UpdateFrame(renderTexture);
		recordingProgressFeedback.value = num;
		if (num >= 1f)
		{
			FinishCapturing();
		}
	}

	private void OnCaptureStarted()
	{
		recordingFeedback.gameObject.SetActive(value: true);
		recordingProgressFeedback.gameObject.SetActive(value: true);
	}

	private void OnExportStarted()
	{
		recordingFeedback.gameObject.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		exportingFeedback.SetActive(value: true);
	}

	private void OnExportFinished(string filename)
	{
		exportingFeedback.SetActive(value: false);
		StartCoroutine(DisplayFileSaveFeedbackCoroutine(filename));
	}

	private IEnumerator DisplayFileSaveFeedbackCoroutine(string filename)
	{
		filename = Path.GetFileName(filename);
		savedFeedback.gameObject.SetActive(value: true);
		savedFeedback.text = filename + " Saved!";
		yield return new WaitForSeconds(2f);
		savedFeedback.gameObject.SetActive(value: false);
	}

	public void OpenScreen(bool open)
	{
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetBool(screenAnimationId, open);
		}
		if (externalScreenRenderer == null)
		{
			camera.enabled = open;
		}
		if (screenOpen != open)
		{
			screenOpen = open;
			Renderer[] array = screenRenderers;
			foreach (Renderer renderer in array)
			{
				renderer.material = ((!open) ? defaultScreenMaterial : screenRenderMaterialCopy);
			}
		}
		base.enabled = screenOpen;
	}

	private void SetTrigger(float trigger)
	{
		triggerAmount = trigger;
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetFloat(triggerId, triggerAmount);
		}
	}
}
public class HandheldCameraRemote : Photon.MonoBehaviour
{
	private enum DollyMode
	{
		Stationary,
		Linear,
		Orbit
	}

	[Header("Camera Remote Settings")]
	[SerializeField]
	private HandheldCamera camera;

	[SerializeField]
	private DollyMode mode;

	[SerializeField]
	private float dollyTime;

	[SerializeField]
	private Transform startPosition;

	[Tooltip("Only valid for linear dolly mode")]
	[SerializeField]
	private Transform endPosition;

	[Tooltip("Only valid for orbit dolly mode")]
	[SerializeField]
	private Transform orbitCenter;

	private Tool tool;

	private bool initialized;

	private bool recording;

	private float fullRenderScale;

	protected override void Awake()
	{
		base.Awake();
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PostPickupEvent += OnPostPickup;
			tool.InputDownEvent += OnInputDown;
		}
	}

	private void Update()
	{
		if (!initialized)
		{
			initialized = true;
			camera.Tool.ToolCleanup.PauseCleanup(this);
			camera.Tool.RigidbodyEx.AddKinematic(this);
			camera.RemoteControl = true;
			camera.OpenScreen(open: true);
		}
		if (base.hasAuthority)
		{
			ComputeCameraView(UnityEngine.Time.time, out var position, out var rotation);
			camera.transform.position = position;
			camera.transform.rotation = rotation;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (tool != null)
		{
			tool.PostPickupEvent -= OnPostPickup;
			tool.InputDownEvent -= OnInputDown;
		}
	}

	private void ComputeCameraView(float elapsedTime, out Vector3 position, out Quaternion rotation)
	{
		position = startPosition.position;
		rotation = startPosition.rotation;
		float num = elapsedTime / dollyTime;
		switch (mode)
		{
		case DollyMode.Linear:
			if (!(endPosition != null))
			{
				break;
			}
			if (num > 1f)
			{
				int num2 = Mathf.FloorToInt(num);
				num -= (float)num2;
				if (num2 % 2 == 1)
				{
					num = 1f - num;
				}
			}
			position = Vector3.Lerp(startPosition.position, endPosition.position, num);
			rotation = Quaternion.Slerp(startPosition.rotation, endPosition.rotation, num);
			break;
		case DollyMode.Orbit:
			if (orbitCenter != null)
			{
				Quaternion quaternion = Quaternion.AngleAxis(360f * num, Vector3.up);
				Vector3 vector = orbitCenter.InverseTransformPoint(startPosition.position);
				Quaternion quaternion2 = orbitCenter.InverseTransformRotation(startPosition.rotation);
				position = orbitCenter.TransformPoint(quaternion * vector);
				rotation = orbitCenter.TransformRotation(quaternion * quaternion2);
			}
			break;
		}
	}

	private void OnPostPickup(Tool tool)
	{
		camera.photonView.TransferOwnership(tool.HolderPlayer.PhotonPlayer);
	}

	private void OnInputDown(Tool thisTool)
	{
		if (base.hasAuthority)
		{
			if (!recording)
			{
				recording = true;
				fullRenderScale = Mathf.Max(1f, XRSettings.eyeTextureResolutionScale);
				XRSettings.eyeTextureResolutionScale = fullRenderScale / 2f;
				camera.StartCapturing();
			}
			else
			{
				recording = false;
				XRSettings.eyeTextureResolutionScale = Mathf.Max(1f, fullRenderScale);
				camera.FinishCapturing();
			}
		}
	}
}
public class HandheldStreamerCamera : Photon.MonoBehaviour
{
	private static readonly int TRIGGER_ID = Animator.StringToHash("Trigger");

	private static readonly int SCREEN_ANIMATION_ID = Animator.StringToHash("ScreenOpen");

	[Autofill(AutofillType.Self, false)]
	public Tool Tool;

	[Header("Streaming")]
	public CameraTransform mainCameraTransform = new CameraTransform();

	public string Name = "Handheld (forward)";

	public CameraTransform frontFacingCameraTransform = new CameraTransform();

	public string frontFacingName = "Handheld (backward)";

	public Transform LensTransform;

	public AnimationCurve PositionSmoothingTimeMultiplierByDistance;

	[Header("Screens")]
	[SerializeField]
	private Renderer[] screenRenderers;

	[SerializeField]
	private Material screenRenderMaterial;

	[SerializeField]
	private Material defaultScreenMaterial;

	private Material screenRenderMaterialCopy;

	private Animator animator;

	private float triggerAmount;

	private bool screenOpen;

	[NonSerialized]
	public bool RemoteControl;

	protected override void Awake()
	{
		base.Awake();
		mainCameraTransform.FollowsLocalPlayer = false;
		mainCameraTransform.Transform = LensTransform;
		mainCameraTransform.PositionOffset = Vector3.zero;
		mainCameraTransform.RotationOffset = Quaternion.identity;
		mainCameraTransform.UpdateTransformOnlyOnTeleport = false;
		mainCameraTransform.Name = Name;
		mainCameraTransform.Type = CameraTransform.CameraType.Handheld;
		mainCameraTransform.HideCameraMesh = true;
		mainCameraTransform.PositionSmoothingTimeMultiplierByDistance = PositionSmoothingTimeMultiplierByDistance;
		frontFacingCameraTransform.FollowsLocalPlayer = false;
		frontFacingCameraTransform.Transform = LensTransform;
		frontFacingCameraTransform.PositionOffset = Vector3.zero;
		frontFacingCameraTransform.RotationOffset = Quaternion.Euler(0f, 180f, 0f);
		frontFacingCameraTransform.UpdateTransformOnlyOnTeleport = false;
		frontFacingCameraTransform.Name = frontFacingName;
		frontFacingCameraTransform.Type = CameraTransform.CameraType.Handheld;
		frontFacingCameraTransform.HideCameraMesh = true;
		frontFacingCameraTransform.PositionSmoothingTimeMultiplierByDistance = PositionSmoothingTimeMultiplierByDistance;
		screenRenderMaterialCopy = new Material(screenRenderMaterial);
		animator = GetComponentInChildren<Animator>();
		if (Tool != null)
		{
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PostReleaseEvent += OnPostRelease;
			Tool.AddCustomPickupCondition(CustomPickupCondition);
		}
	}

	private void Start()
	{
		if (Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.SpawningPlayer == Player.LocalPlayer)
		{
			this.Update(UpdateTrigger);
		}
	}

	private bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		return selectingPlayer == thisTool.PlayerSpawnedEquipment.SpawningPlayer;
	}

	private void UpdateTrigger()
	{
		if (base.hasAuthority)
		{
			SetTrigger((!(Tool != null)) ? 0f : Tool.InputAmount);
		}
	}

	private void OnPostPickup(Tool tool)
	{
		Tool.RigidbodyEx.RemoveKinematic(this);
	}

	private void OnPostRelease(Tool tool)
	{
		Tool.RigidbodyEx.AddKinematic(this);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PostReleaseEvent += OnPostRelease;
		}
	}

	public void OpenScreen(bool open)
	{
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetBool(SCREEN_ANIMATION_ID, open);
		}
		if (screenOpen != open)
		{
			screenOpen = open;
			Renderer[] array = screenRenderers;
			foreach (Renderer renderer in array)
			{
				renderer.material = ((!open) ? defaultScreenMaterial : screenRenderMaterialCopy);
			}
		}
	}

	public void SetTexture(RenderTexture rt)
	{
		screenRenderMaterialCopy.mainTexture = rt;
	}

	private void SetTrigger(float trigger)
	{
		triggerAmount = trigger;
		if (animator != null && animator.isActiveAndEnabled)
		{
			animator.SetFloat(TRIGGER_ID, triggerAmount);
		}
	}
}
namespace RecRoom.Core
{
	public class HingedLidChest : BaseOpenableChest
	{
		[SerializeField]
		private Tool lidHandle;

		[SerializeField]
		private bool automaticallyOpenOnPickup;

		[SerializeField]
		private float fullyOpenLidAngle = 120f;

		[SerializeField]
		private float openEnoughLidAngle = 90f;

		[SerializeField]
		private Transform lidHingeTransform;

		[SerializeField]
		private RecRoomAudioClip liftingLidAudio;

		private Vector3 closedLidOrientation = Vector3.zero;

		private static readonly int ANIMATOR_OPENING_ID = Animator.StringToHash("Opening");

		public override Tool Handle => lidHandle;

		protected override float UpdateOpeningStateAuthorityUpdateHz
		{
			[CompilerGenerated]
			get
			{
				return -1f;
			}
		}

		protected override float UpdateOpeningStateNonAuthorityUpdateHz
		{
			[CompilerGenerated]
			get
			{
				return -1f;
			}
		}

		protected override void Awake()
		{
			base.OnUpdateOpeningState += _OnUpdateOpeningState;
			base.Awake();
			closedLidOrientation = (lidHandle.transform.position - lidHingeTransform.position).normalized;
			lidHandle.SuppressAnimateInOut = true;
			lidHandle.PostPickupEvent += OnHandlePickup;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			lidHandle.PostPickupEvent -= OnHandlePickup;
		}

		protected override void OnEnterClosedState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterClosedState(previousStateId, previousSubStateId);
			lidHandle.EnablePickup(this);
		}

		protected override void OnEnterOpeningState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterOpeningState(previousStateId, previousSubStateId);
			AudioManager.Play3DSFX(liftingLidAudio, base.transform);
		}

		private void _OnUpdateOpeningState()
		{
			if (base.hasAuthority && (automaticallyOpenOnPickup || lidHandle == null || !lidHandle.IsHeld))
			{
				stateMachine.EnterState(2);
			}
			else if (lidHandle.HolderHand != null)
			{
				Vector3 normalized = (lidHandle.HolderHand.transform.position - lidHingeTransform.position).normalized;
				float num = Mathf.Abs(Vector3.Angle(closedLidOrientation, normalized));
				float normalizedTime = Mathf.Clamp01(num / fullyOpenLidAngle);
				animator.Play(ANIMATOR_OPENING_ID, 0, normalizedTime);
				if (base.hasAuthority && num >= openEnoughLidAngle)
				{
					stateMachine.EnterState(2);
				}
			}
		}

		protected override void OnEnterOpenState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterOpenState(previousStateId, previousSubStateId);
			lidHandle.DisablePickup(this);
		}

		private void OnHandlePickup(Tool tool)
		{
			if (base.hasAuthority && stateMachine.CurrentStateId == 0)
			{
				if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
				{
					stateMachine.EnterState(2);
				}
				else
				{
					stateMachine.EnterState(1);
				}
			}
		}
	}
	public class HoldToOpenChest : BaseOpenableChest
	{
		[SerializeField]
		private Tool lidHandle;

		[Header("Hold To Open")]
		[SerializeField]
		private float openHoldDuration = 2f;

		[SerializeField]
		private PooledParticle openHoldParticlePrefab;

		[SerializeField]
		private float particleOffsetDistance = 0.33f;

		[SerializeField]
		private float maxHandleMoveDistanceSqr = 1f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip handleGrabAudio;

		[SerializeField]
		private RecRoomAudioClip openingProgressAudio;

		[SerializeField]
		private RecRoomAudioClip openAudio;

		private float openingStartTime;

		private float openingStartHandleHolderDistanceSqr;

		private PooledParticle currentParticles;

		private SFXAudioSource loopingAudio;

		public override Tool Handle => lidHandle;

		protected override float UpdateOpeningStateNonAuthorityUpdateHz
		{
			[CompilerGenerated]
			get
			{
				return 0f;
			}
		}

		protected override void Awake()
		{
			base.OnUpdateOpeningState += _OnUpdateOpeningState;
			base.Awake();
			lidHandle.AddCustomScreensHoldToPickupDuration(openHoldDuration, this);
			lidHandle.RigidbodyEx.AddKinematic(this);
			lidHandle.NetworkTransform.SynchronizationReadingEnabled = false;
			lidHandle.NetworkTransform.SynchronizationWritingEnabled = false;
			lidHandle.PostPickupEvent += OnHandlePickup;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			lidHandle.PostPickupEvent -= OnHandlePickup;
		}

		protected override void OnEnterClosedState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterClosedState(previousStateId, previousSubStateId);
			lidHandle.EnablePickup(this);
		}

		protected override void OnEnterOpeningState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterOpeningState(previousStateId, previousSubStateId);
			openingStartTime = UnityEngine.Time.time;
			StopLoopingFeedback();
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					stateMachine.EnterState(2);
				});
			}
			else if (lidHandle.IsHeldByPlayer && lidHandle.HolderPlayer != null && lidHandle.HolderPlayer.isLocal)
			{
				openingStartHandleHolderDistanceSqr = (lidHandle.HolderHand.transform.position - base.transform.position).sqrMagnitude;
				StartLoopingFeedback(lidHandle.HolderHand.transform.position, openHoldDuration);
			}
		}

		private void _OnUpdateOpeningState()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			if (UnityEngine.Time.time - openingStartTime >= openHoldDuration)
			{
				stateMachine.EnterState(2);
				return;
			}
			if (lidHandle == null || !lidHandle.IsHeldByPlayer || lidHandle.HolderHand == null)
			{
				stateMachine.EnterState(0);
				return;
			}
			Vector3 position = lidHandle.HolderHand.transform.position;
			if (currentParticles != null)
			{
				GetParticlePositionRotation(position, out var position2, out var rotation);
				currentParticles.transform.position = position2;
				currentParticles.transform.rotation = rotation;
			}
			float sqrMagnitude = (position - base.transform.position).sqrMagnitude;
			if (sqrMagnitude - openingStartHandleHolderDistanceSqr >= maxHandleMoveDistanceSqr)
			{
				stateMachine.EnterState(0);
			}
		}

		protected override void OnExitOpeningState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitOpeningState(nextStateId, nextSubStateId);
			StopLoopingFeedback();
			if (nextStateId == 2)
			{
				AudioManager.Play3DSFX(openAudio, base.transform.position);
			}
		}

		protected override void OnEnterOpenState(ushort previousStateId, ushort previousSubStateId)
		{
			if (lidHandle.HolderPlayer != null && lidHandle.HolderPlayer.isLocal)
			{
				lidHandle.HolderPlayer.PlayerEvents.OpenedChest();
			}
			base.OnEnterOpenState(previousStateId, previousSubStateId);
			lidHandle.DisablePickup(this);
		}

		private void StartLoopingFeedback(Vector3 holderPosition, float maxDuration)
		{
			StopLoopingFeedback();
			currentParticles = ObjectPool.Instance.Acquire(openHoldParticlePrefab);
			if (currentParticles != null)
			{
				currentParticles.SetDuration(maxDuration, setStartLifetime: true);
				GetParticlePositionRotation(holderPosition, out var position, out var rotation);
				currentParticles.Play(position, rotation);
			}
			loopingAudio = AudioManager.Play3DSFX(openingProgressAudio, base.transform.position);
		}

		private void GetParticlePositionRotation(Vector3 holderPosition, out Vector3 position, out Quaternion rotation)
		{
			Vector3 normalized = (holderPosition - lidHandle.transform.position).normalized;
			position = lidHandle.transform.position + normalized * particleOffsetDistance;
			rotation = Quaternion.LookRotation(-normalized);
		}

		private void StopLoopingFeedback()
		{
			if (currentParticles != null)
			{
				currentParticles.Stop();
				currentParticles = null;
			}
			if (loopingAudio != null)
			{
				AudioManager.StopLoopingSFX(loopingAudio);
				loopingAudio = null;
			}
		}

		private void OnHandlePickup(Tool tool)
		{
			AudioManager.Play3DSFX(handleGrabAudio, tool.transform);
			if (base.hasAuthority && stateMachine.CurrentStateId == 0)
			{
				stateMachine.EnterState(1);
			}
		}
	}
}
namespace RecRoom.Tools
{
	public class CharadesPen : Photon.MonoBehaviour
	{
		private struct ErrorDetails
		{
			public CreationResult result;

			public string errorMessage;

			public CreationObject creationObject;

			public int culpritId;

			public DateTime errorTime;

			public bool IsDifferent(ErrorDetails other)
			{
				return result != other.result || errorMessage != other.errorMessage || creationObject != other.creationObject || culpritId != other.culpritId;
			}

			public static ErrorDetails NoError()
			{
				return new ErrorDetails
				{
					result = CreationResult.Success,
					errorMessage = null,
					creationObject = null,
					culpritId = PhotonPlayer.Invalid,
					errorTime = DateTime.UtcNow
				};
			}
		}

		private SynchronizedField<int> _creationContextId;

		private Color[] extrusionColors;

		[SerializeField]
		private ShapeColor defaultColor;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private MakerPenVisuals _penVisuals;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		private ShapeColor _selectedColor;

		private ErrorDetails lastErrorDetails = ErrorDetails.NoError();

		private const float secondsBetweenSameErrorMessage = 3f;

		public CreationContext CreationContext { get; private set; }

		public MakerPenVisuals PenVisuals => _penVisuals;

		public Vector3 ActionPointerPosition
		{
			get
			{
				Vector3 position = ((!_penVisuals.LaserPointerEnabled) ? Vector3.zero : _penVisuals.LaserPointerPosition);
				return _penVisuals.ExtrusionPoint.TransformPoint(position);
			}
		}

		public Quaternion ActionPointerRotation => _penVisuals.ExtrusionPoint.rotation;

		public ShapeType CurrentShapeType { get; private set; }

		public Tool Tool => _tool;

		public CharadesPenBasicUIFlow PenBasicUIFlow { get; set; }

		public ShapeColor SelectedColor
		{
			get
			{
				return _selectedColor;
			}
			set
			{
				_selectedColor = value;
				OnSelectedColorChange();
			}
		}

		private void OnCreationContextIdChange()
		{
			if (CreationContext != null)
			{
				CreationContext.OnCreationContextError -= HandleCreationContextError;
				if (CreationContext.photonView.viewID != _creationContextId.Get() && CreationContext.authority == Player.LocalPlayer.PhotonPlayer)
				{
					PhotonNetwork.Destroy(CreationContext.photonView);
				}
			}
			PhotonView photonView = PhotonView.Find(_creationContextId.Get());
			CreationContext = ((!(photonView != null)) ? null : photonView.GetComponent<CreationContext>());
			if (CreationContext != null)
			{
				CreationContext.OnCreationContextError += HandleCreationContextError;
			}
		}

		private void InitializeCreationContext()
		{
			_creationContextId = new SynchronizedField<int>(this, "CREATION_CONTEXT", -1, SetterPermissionMode.AUTHORITY, OnCreationContextIdChange);
			if (base.hasAuthority)
			{
				AuthorityInstantiateNewCreationContext();
			}
			OnCreationContextIdChange();
		}

		private void AuthorityInstantiateNewCreationContext()
		{
			if (base.hasAuthority)
			{
				CreationContext creationContext = CreationContext.Instantiate();
				creationContext.ShapeCreationContext.ShouldRenderWorldFadeMask = false;
				_creationContextId.Set(creationContext.photonView.viewID);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			InitializeCreationContext();
			extrusionColors = ShapeSettings.ConfigAsset.ShapeColors;
			SelectedColor = defaultColor;
			Tool.AddCustomPickupCondition(CustomPickupCondition);
			Tool.PreReleaseEvent += OnPreRelease;
			Tool.PostReleaseEvent += OnRelease;
			Tool.PostPickupEvent += OnPickup;
			Tool.PostResetEvent += OnReset;
		}

		private void Start()
		{
			PenBasicUIFlow = Tool.Menu.GetFlowByType<CharadesPenBasicUIFlow>();
			if (PenBasicUIFlow != null)
			{
				PenBasicUIFlow.CharadesPen = this;
				PenBasicUIFlow.AssignColorsToColorPicker(extrusionColors);
			}
			OnSelectedColorChange();
		}

		private void OnDisable()
		{
			HandleRelease();
		}

		protected override void OnDestroy()
		{
			Tool.PreReleaseEvent -= OnPreRelease;
			Tool.PostReleaseEvent -= OnRelease;
			Tool.PostPickupEvent -= OnPickup;
			Tool.PostResetEvent -= OnReset;
			Tool.RemoveCustomPickupCondition(CustomPickupCondition);
			PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
			PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: true);
			base.OnDestroy();
		}

		public bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (Profiles.LocalProfile.IsJunior())
			{
				return false;
			}
			if (selectingPlayer != null && (selectingPlayer.LeftHand.HeldTool?.GetComponent<CharadesPen>() != null || selectingPlayer.RightHand.HeldTool?.GetComponent<CharadesPen>() != null))
			{
				return false;
			}
			return true;
		}

		protected void OnPickup(Tool tool)
		{
			if (tool.IsHeldByPlayer)
			{
				if (tool.HolderPlayer.isLocal)
				{
					PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: false);
				}
				if (base.hasAuthority && (CreationContext == null || CreationContext.authority != Player.LocalPlayer.PhotonPlayer))
				{
					AuthorityInstantiateNewCreationContext();
				}
			}
		}

		private void OnPreRelease(Tool tool)
		{
			PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: true);
		}

		protected void OnRelease(Tool tool)
		{
			HandleRelease();
			if (!Tool.RigidbodyEx.isKinematic)
			{
				Tool.RigidbodyEx.UnityRigidbody.ResetCenterOfMass();
			}
		}

		private void OnReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			AuthorityResetToDefaults();
		}

		private void HandleRelease()
		{
			if (CreationContext != null)
			{
				CreationContext.ShapeCreationContext.DeselectShapeContainer();
			}
		}

		public void AuthorityResetToDefaults()
		{
			if (base.hasAuthority)
			{
				SelectedColor = defaultColor;
			}
		}

		public void SelectShapeColor(ShapeColor desiredColor)
		{
			if ((int)desiredColor < extrusionColors.Length)
			{
				SelectedColor = desiredColor;
			}
		}

		public void SelectShapeType(ShapeType shapeType)
		{
			CurrentShapeType = shapeType;
		}

		private void OnSelectedColorChange()
		{
			PenVisuals.UpdateTubeColor(extrusionColors[(int)SelectedColor]);
			if (Tool.HolderHand != null)
			{
				Tool.HolderHand.Vibrate(30);
			}
		}

		private void OnPhotonPlayerDisconnected(PhotonPlayer oldPlayer)
		{
			if (base.hasAuthority && Tool.Owner.PhotonPlayer == oldPlayer)
			{
				HandleRelease();
			}
		}

		private void HandleCreationContextError(CreationResult result, string errorMessage, CreationObject creationObject, PhotonPlayer culprit)
		{
			ErrorDetails errorDetails = new ErrorDetails
			{
				result = result,
				errorMessage = errorMessage,
				creationObject = creationObject,
				culpritId = (culprit?.ID ?? PhotonPlayer.Invalid),
				errorTime = DateTime.UtcNow
			};
			if (errorDetails.IsDifferent(lastErrorDetails) || (errorDetails.errorTime - lastErrorDetails.errorTime).TotalSeconds >= 3.0)
			{
				lastErrorDetails = errorDetails;
			}
		}
	}
