		public event Action<bool> OnPaletteMenuOpenCloseEvent
		{
			add
			{
				Action<bool> action = this.m_OnPaletteMenuOpenCloseEvent;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPaletteMenuOpenCloseEvent, (Action<bool>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<bool> action = this.m_OnPaletteMenuOpenCloseEvent;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OnPaletteMenuOpenCloseEvent, (Action<bool>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		private void OnCreationContextIdChange()
		{
			if (CreationContext != null)
			{
				CreationContext.OnCreationContextError -= HandleCreationContextError;
				if (CreationContext.photonView.viewID != _creationContextId.Get() && CreationContext.authority == Player.LocalPlayer.PhotonPlayer)
				{
					PhotonNetwork.Destroy(CreationContext.photonView);
				}
			}
			PhotonView photonView = PhotonView.Find(_creationContextId.Get());
			CreationContext = ((!(photonView != null)) ? null : photonView.GetComponent<CreationContext>());
			if (CreationContext != null)
			{
				CreationContext.OnCreationContextError += HandleCreationContextError;
				CreationContext.ShapeCreationContext.SelectedShapeContainerChangedEvent += OnShapeCreationContextSelectedShapeContainerChangedEvent;
			}
		}

		private void InitializeCreationContext()
		{
			_creationContextId = new SynchronizedField<int>(this, "CREATION_CONTEXT", -1, SetterPermissionMode.AUTHORITY, OnCreationContextIdChange);
			if (base.hasAuthority)
			{
				AuthorityInstantiateNewCreationContext();
			}
			OnCreationContextIdChange();
		}

		private void AuthorityInstantiateNewCreationContext()
		{
			if (base.hasAuthority)
			{
				CreationContext creationContext = CreationContext.Instantiate();
				creationContext.ShapeCreationContext.ShouldRenderWorldFadeMask = fadeWorldInShapeMode;
				creationContext.ShapeCreationContext.LockOwnershipToLocalPlayer();
				_creationContextId.Set(creationContext.photonView.viewID);
			}
		}

		public static bool IsCreationToolMode(ToolMode toolMode)
		{
			return toolMode == ToolMode.CreateShape || toolMode == ToolMode.CreateObject || toolMode == ToolMode.CreateTrigger || toolMode == ToolMode.CreateInventionInstance;
		}

		protected override void Awake()
		{
			base.Awake();
			InitializeCreationContext();
			_currentMode = new SynchronizedField<ToolMode, TargetMode>(this, "MP_CM", ToolMode.CreateShape, TargetMode.Object, SetterPermissionMode.AUTHORITY, OnCurrentModeChanged);
			extrusionColors = ShapeSettings.ConfigAsset.ShapeColors;
			SelectedColor = defaultColor;
			Tool.PreReleaseEvent += OnPreRelease;
			Tool.PostReleaseEvent += OnRelease;
			Tool.PostPickupEvent += OnPickup;
			Tool.photonView.OwnerChangedEvent += OnPhotonViewOwnerChange;
			mergeOperation.Initialize(this);
			splitOperation.Initialize(this);
			selectInventionOperation.Initialize(this);
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
			if (!LocalPlayerCanUseCreationMode)
			{
				AuthoritySelectModeInternal(ToolMode.Disabled, CurrentTargetMode, ToolModeChangeReason.Default, force: true);
			}
		}

		private void Start()
		{
			Tool.AddCustomPickupCondition(CustomPickupCondition);
			if (IsMine)
			{
				if (paletteMenu != null)
				{
					paletteMenu.MakerPen = this;
				}
				MainScreen = Tool.Menu.GetFlowByType<MakerPenMainScreen>();
				if (paletteMenu != null && paletteMenu.Tool != null)
				{
					PaletteMainScreen = paletteMenu.Tool.Menu.GetFlowByType<MakerPenPaletteMainScreen>();
				}
				QuickActionMenu = UnityEngine.Object.Instantiate(quickActionMenuPrefab);
				QuickActionMenu.CloseMenu();
				OnSelectedColorChange();
				OnCurrentModeChanged();
				if (NetworkedSingletonMonoBehaviour<CreationManager>.IsInitialized)
				{
					CreationManager.AllSpawnedObjectsDestroyedEvent += OnAllSpawnedObjectsDestroyed;
				}
			}
		}

		private void OnDisable()
		{
			HandleRelease();
		}

		protected override void OnDestroy()
		{
			Tool.PreReleaseEvent -= OnPreRelease;
			Tool.PostReleaseEvent -= OnRelease;
			Tool.PostPickupEvent -= OnPickup;
			Tool.photonView.OwnerChangedEvent -= OnPhotonViewOwnerChange;
			PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: true);
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
			CreationManager.AllSpawnedObjectsDestroyedEvent -= OnAllSpawnedObjectsDestroyed;
			base.OnDestroy();
		}

		public bool CustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (Profiles.LocalProfile.IsJunior() || !IsMine)
			{
				return false;
			}
			return true;
		}

		public static void ShowCannotUseFeedback()
		{
			if (!LocalPlayerCanUseCreationMode)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, (!GameSessions.LocalGameSession.IsSandbox) ? "Your Maker Pen can only be\nused in Sandbox rooms" : "You don't have permission to use\nyour Maker Pen in this room", 3f);
			}
		}

		protected void OnPickup(Tool tool)
		{
			if (tool.IsHeldByPlayer && tool.HolderPlayer.isLocal)
			{
				if (LocalPlayerCanUseCreationMode)
				{
					PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: false);
				}
				else
				{
					ShowCannotUseFeedback();
				}
			}
		}

		private void OnPreRelease(Tool tool)
		{
			PlayerCollisionDisplacementVRMovementController.SetEnabled(this, enabled: true);
		}

		protected void OnRelease(Tool tool)
		{
			HandleRelease();
			if (!Tool.RigidbodyEx.isKinematic)
			{
				Tool.RigidbodyEx.UnityRigidbody.ResetCenterOfMass();
			}
			AuthoritySelectModeInternal(CurrentToolMode, TargetMode.Object, ToolModeChangeReason.Default, force: true);
		}

		private void HandleRelease()
		{
			AuthorityHidePaletteMenu();
			if (CreationContext != null)
			{
				CreationContext.ShapeCreationContext.DeselectShapeContainer();
			}
		}

		public void AuthorityResetToDefaults()
		{
			if (base.hasAuthority)
			{
				SelectedColor = defaultColor;
				AuthoritySelectModeInternal(ToolMode.CreateShape, TargetMode.Object, ToolModeChangeReason.Default, force: true);
				CurrentConstraintMode = ConstraintMode.Free;
				Snapping.ToggleSnapObjects(snap: false);
				CurveRadiusModifier = -1f;
			}
		}

		private void HandleCreationContextError(CreationResult result, string errorMessage, CreationObject creationObject, PhotonPlayer culprit)
		{
			ErrorDetails errorDetails = new ErrorDetails
			{
				result = result,
				errorMessage = errorMessage,
				creationObject = creationObject,
				culpritId = (culprit?.ID ?? PhotonPlayer.Invalid),
				errorTime = DateTime.UtcNow
			};
			if (errorDetails.IsDifferent(lastErrorDetails) || (errorDetails.errorTime - lastErrorDetails.errorTime).TotalSeconds >= 3.0)
			{
				lastErrorDetails = errorDetails;
				RaiseInvalidActionPerformed(result, errorMessage, culprit);
			}
		}

		public void RaiseInvalidActionPerformed(CreationResult result, string errorMessage, PhotonPlayer culprit)
		{
			string text = string.Empty;
			string arg = ((culprit == null) ? "another player" : culprit.NickName);
			switch (result)
			{
			case CreationResult.Failure_InsufficientResources:
				text = "Not enough ink";
				break;
			case CreationResult.Failure_LockedByOther:
				text = $"Being edited by {arg}";
				break;
			case CreationResult.Failure_HeldByOther:
				text = $"Being held by {arg}";
				break;
			case CreationResult.Failure_NoAuthority:
				text = "It is locked by someone else";
				break;
			case CreationResult.Failure_SettingsChangedByOther:
				text = $"Changed by {arg}";
				break;
			case CreationResult.Failure_ToolFrozen:
				text = "Object is frozen";
				break;
			case CreationResult.Failure_Parented:
				text = "Object is connected to something else";
				break;
			case CreationResult.Failure_ObjectDoesNotExist:
				text = "Object no longest exists";
				break;
			case CreationResult.Failure_ObjectAlreadyExists:
				text = "Object already exists";
				break;
			case CreationResult.Failure_ParentChanged:
				text = "Object's parent has changed";
				break;
			case CreationResult.Failure_ToolHeld:
				text = "Object is currently held";
				break;
			case CreationResult.Failure_NetworkError:
				text = "Network error";
				break;
			case CreationResult.Failure_PermissionDenied:
				text = "Permission denied";
				break;
			}
			if (!string.IsNullOrEmpty(errorMessage))
			{
				if (!string.IsNullOrEmpty(text))
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, errorMessage, text, 1.5f);
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, errorMessage, 1.5f);
				}
			}
		}

		public void AuthoritySelectMode(ToolMode desiredTool, TargetMode desiredTarget)
		{
			while (!PenToolStackIsEmpty)
			{
				AuthorityPopPenTool();
			}
			AuthoritySelectModeInternal(desiredTool, desiredTarget, ToolModeChangeReason.Default, force: false);
		}

		private void AuthoritySelectModeInternal(ToolMode desiredTool, TargetMode desiredTarget, ToolModeChangeReason reason, bool force)
		{
			if (base.hasAuthority && (!ToolModeLocked || force))
			{
				if (!LocalPlayerCanUseCreationMode)
				{
					desiredTool = ToolMode.Disabled;
				}
				ToolTypeChangeReason = reason;
				_currentMode.Set(desiredTool, desiredTarget);
			}
		}

		public void AuthorityPushPenTool(ToolMode toolMode)
		{
			if (base.hasAuthority)
			{
				toolStack.Push(CurrentToolMode);
				AuthoritySelectModeInternal(toolMode, CurrentTargetMode, ToolModeChangeReason.StackPush, force: false);
			}
		}

		public void AuthorityPopPenTool()
		{
			if (base.hasAuthority && toolStack.Count > 0)
			{
				AuthoritySelectModeInternal(toolStack.Pop(), CurrentTargetMode, ToolModeChangeReason.StackPop, force: false);
			}
		}

