		public void TriggerUndo()
		{
			if (!(UndoStack != null) || !UndoStack.CanUndo)
			{
				return;
			}
			UndoStack.RequestUndo().Then(delegate(CreationResult result)
			{
				if (result != CreationResult.Success)
				{
					RaiseInvalidActionPerformed(result, "Undo failed", null);
				}
			});
		}

		public void TriggerRedo()
		{
			if (!(UndoStack != null) || !UndoStack.CanRedo)
			{
				return;
			}
			UndoStack.RequestRedo().Then(delegate(CreationResult result)
			{
				if (result != CreationResult.Success)
				{
					RaiseInvalidActionPerformed(result, "Redo failed", null);
				}
			});
		}

