		private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RecRoom.Systems.PlayerRoles.RoomRole roleDef)
		{
			if (player.IsLocal && CurrentToolMode == ToolMode.Disabled)
			{
				AuthoritySelectModeInternal(LastCreationToolMode, CurrentTargetMode, ToolModeChangeReason.Default, force: true);
			}
		}

		private void OnShapeCreationContextSelectedShapeContainerChangedEvent()
		{
			if (base.hasAuthority)
			{
				this.InvokeNextEndOfFrame(HandleSelectedShapeContainerChanged);
			}
		}

		private void HandleSelectedShapeContainerChanged()
		{
			if (base.hasAuthority)
			{
				bool flag = CreationContext.ShapeCreationContext.SelectedShapeContainer != null;
				if (flag && CurrentTargetMode != TargetMode.Shape)
				{
					AuthoritySelectModeInternal(CurrentToolMode, TargetMode.Shape, ToolModeChangeReason.Default, force: true);
				}
				else if (!flag && CurrentTargetMode == TargetMode.Shape)
				{
					AuthoritySelectModeInternal(CurrentToolMode, TargetMode.Object, ToolModeChangeReason.Default, force: true);
				}
			}
		}

		private void OnAllSpawnedObjectsDestroyed()
		{
			AuthoritySelectMode(CurrentToolMode, TargetMode.Object);
		}

		private void OnCurrentModeChanged()
		{
			if (CurrentTargetMode == TargetMode.Object && base.hasAuthority && lastTargetMode == TargetMode.Shape)
			{
				AudioManager.Play2DSFX(enterPlayModeAudio);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "DONE EDITING", 1.5f);
			}
			if (CurrentToolMode == ToolMode.Disabled)
			{
				Tool.MenuProjector.ForceMenuClose = true;
				AuthorityHidePaletteMenu();
			}
			else
			{
				Tool.MenuProjector.ForceMenuClose = false;
			}
			ToolMode currentToolMode = CurrentToolMode;
			if (IsCreationToolMode(currentToolMode))
			{
				LastCreationToolMode = currentToolMode;
			}
			lastTargetMode = CurrentTargetMode;
			if (OnModeChanged != null)
			{
				OnModeChanged(CurrentToolMode, CurrentTargetMode);
			}
		}

		private void OnSelectedColorChange()
		{
			PenVisuals.UpdateTubeColor(extrusionColors[(int)SelectedColor]);
			if (Tool.HolderHand != null)
			{
				Tool.HolderHand.Vibrate(30);
			}
		}

		private void OnPhotonViewOwnerChange(int ownerId)
		{
			if (paletteMenu != null)
			{
				paletteMenu.Tool.photonView.TransferOwnership(ownerId);
			}
		}

		public void FireToolUsedEvent()
		{
			if (OnToolUsed != null)
			{
				OnToolUsed(CurrentToolMode);
			}
		}
	}
