	[Serializable]
	public class MakerPenMergeOperation : MakerPenOperation
	{
		public bool CanMergeSelection
		{
			get
			{
				if (base.CreationContext.SelectionCount < 2)
				{
					return false;
				}
				foreach (CreationObject item in base.CreationContext.CurrentSelection)
				{
					ShapeContainer component = item.GetComponent<ShapeContainer>();
					if (component == null || !component.CanBeMerged)
					{
						return false;
					}
				}
				return true;
			}
		}

		public IPromise<string> TryMergeSelection()
		{
			if (!CanMergeSelection)
			{
				return new ErroredPromise<string>("Cannot merge current selection");
			}
			Promise<string> promise = new Promise<string>();
			ShapeContainer destContainer = null;
			List<ShapeContainer> containersToMerge = new List<ShapeContainer>();
			foreach (CreationObject item in base.CreationContext.CurrentSelection)
			{
				ShapeContainer component = item.GetComponent<ShapeContainer>();
				containersToMerge.Add(component);
				if (destContainer == null)
				{
					destContainer = component;
				}
				else if (ShapeSettings.GetResourceMultiplierForPhysicsMode(destContainer.CurrentPhysicsMode) > ShapeSettings.GetResourceMultiplierForPhysicsMode(component.CurrentPhysicsMode))
				{
					destContainer = component;
				}
			}
			containersToMerge.Remove(destContainer);
			foreach (ShapeContainer item2 in containersToMerge)
			{
				if (destContainer.Hack_ContainsDuplicateShapeIds(item2))
				{
					return new CompletedPromise<string>("Merge failed: Fix coming soon!");
				}
			}
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SerializeSpawnableTemplate(containersToMerge.Select((ShapeContainer c) => c.CreationObject)).Then(delegate(CreationManager.SerializeTemplateResult result)
			{
				MergeShapeContainersUndoEntry entry = new MergeShapeContainersUndoEntry(destContainer, containersToMerge, result.spawnableTemplateData, base.CreationContext);
				bool flag = base.CreationContext.TryMergeShapeSelection(destContainer, containersToMerge);
				if (flag)
				{
					base.MakerPen.UndoStack.Add(entry);
				}
				string payload = ((!flag) ? "Merge failed..." : "Merged!");
				promise.Complete(payload);
			}).Error(delegate(string errMsg)
			{
				promise.Error(errMsg);
			});
			return promise;
		}
	}
	[Serializable]
	public class MakerPenSelectInventionOperation : MakerPenOperation
	{
		public bool CanSelectInvention
		{
			get
			{
				if (!base.CreationContext.HasSelection)
				{
					return false;
				}
				CreationObject creationObject = base.CreationContext.CurrentSelection.Last();
				return creationObject.InventionPiece.IsTrackingInvention && base.CreationContext.ExistsUnselectedInventionObjects(creationObject);
			}
		}

		public IPromise<string> TrySelectRestOfInvention()
		{
			CreationObject creationObject = base.CreationContext.CurrentSelection.Last();
			if (base.CreationContext.TrySelectRestOfInvention(creationObject) == CreationResult.Success)
			{
				return new CompletedPromise<string>("Invention selected!");
			}
			return new CompletedPromise<string>("An invention piece\ncould not be selected");
		}
	}
	[Serializable]
	public class MakerPenSplitOperation : MakerPenOperation
	{
		public bool CanSplitSelection => base.ShapeCreationContext.HasSelection && base.ShapeCreationContext.SelectedShapeContainer.CanBeSplit && !base.ShapeCreationContext.SelectedShapeContainer.IsEmpty;

		public IPromise<string> TrySplitSelection()
		{
			if (!CanSplitSelection)
			{
				return new ErroredPromise<string>("Cannot split current selection");
			}
			Promise<string> promise = new Promise<string>();
			ShapeContainer selectedShapeContainer = base.ShapeCreationContext.SelectedShapeContainer;
			int shapeColliderCosts;
			ShapeDataCollection shapeData = base.ShapeCreationContext.SerializeSelectedShapes(out shapeColliderCosts);
			base.ShapeCreationContext.TrySplitSelectedShapes().Then(delegate(ShapeContainer splitContainer)
			{
				IPromise<CreationManager.SerializeTemplateResult> promise2 = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SerializeSpawnableTemplate(new CreationObject[1] { splitContainer.CreationObject }).Then(delegate(CreationManager.SerializeTemplateResult result)
				{
					SplitShapeContainersUndoEntry entry = new SplitShapeContainersUndoEntry(selectedShapeContainer, splitContainer, shapeData, shapeColliderCosts, result.spawnableTemplateData, base.CreationContext);
					base.MakerPen.UndoStack.Add(entry);
					promise.Complete("Shapes split!");
				}).Error(delegate(string errMsg)
				{
					promise.Error(errMsg);
				});
			}).Error(delegate(string errMsg)
			{
				promise.Error(errMsg);
			});
			return promise;
		}
	}
	internal class MakerPenSelectionCache
	{
		private class Data
		{
			public CreationObject obj;

			public Vector3 position;

			public Quaternion rotation;
		}

		public static MakerPenSelectionCache Instance = new MakerPenSelectionCache();

		private const int RELEASE_ROLLBACK_FRAMES = 4;

		private List<Data> data = new List<Data>();

		public void CacheSelection(CreationContext context)
		{
			data.Clear();
			foreach (CreationObject item in context.CurrentSelection)
			{
				data.Add(new Data
				{
					obj = item,
					position = item.transform.position,
					rotation = item.transform.rotation
				});
			}
		}

		public void CalculateVelocityOnAll()
		{
			foreach (Data datum in data)
			{
				RigidbodyEx rigidbodyEx = datum.obj.Tool.RigidbodyEx;
				Vector3 position = datum.obj.transform.position;
				rigidbodyEx.velocity = ((position - datum.position) / UnityEngine.Time.deltaTime).ValueOrZeroIfBogus();
				datum.position = position;
				Quaternion rotation = datum.obj.transform.rotation;
				Vector3 vector = UnityExtensions.AngularDisplacementFromTo(datum.rotation, rotation) / UnityEngine.Time.deltaTime;
				rigidbodyEx.angularVelocity = vector.ValueOrZeroIfBogus();
				datum.rotation = rotation;
			}
		}

		public void DeselectAndApplyVelocityOnAll(CreationContext context)
		{
			foreach (Data datum in data)
			{
				RigidbodyEx rigidbodyEx = datum.obj.Tool.RigidbodyEx;
				float startTimeInPast = 4f * UnityEngine.Time.fixedDeltaTime;
				Vector3 averageHistoricalKinematicLinearVelocity = rigidbodyEx.GetAverageHistoricalKinematicLinearVelocity(startTimeInPast);
				Vector3 averageHistoricalKinematicAngularVelocity = rigidbodyEx.GetAverageHistoricalKinematicAngularVelocity(startTimeInPast);
				context.RemoveFromSelection(datum.obj);
				rigidbodyEx.velocity = averageHistoricalKinematicLinearVelocity;
				rigidbodyEx.angularVelocity = averageHistoricalKinematicAngularVelocity;
			}
			data.Clear();
		}
	}
