	public class MakerPenSnapping
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_ActiveChangeEvent;

		public bool _isActive;

		private static readonly float SIN_45 = Mathf.Sin((float)Math.PI / 4f);

		public bool IsActive
		{
			get
			{
				return _isActive;
			}
			private set
			{
				if (_isActive != value)
				{
					_isActive = value;
					if (this.ActiveChangeEvent != null)
					{
						this.ActiveChangeEvent();
					}
				}
			}
		}

		public Vector3 StickyPos { get; private set; }

		public float GridSize { get; private set; } = 0.1f;

		public float SnapRotateAngleIncrement { get; private set; } = 15f;

		public event Action ActiveChangeEvent
		{
			add
			{
				Action action = this.m_ActiveChangeEvent;
				Action action2;
