		public void ToggleSnapObjects(bool snap)
		{
			IsActive = snap;
		}

		public void SelectGridSize(float newGridSize)
		{
			GridSize = newGridSize;
		}

		public void SelectAngleSnapIncrement(float newAngleSnapIncrement)
		{
			SnapRotateAngleIncrement = newAngleSnapIncrement;
		}

		public Vector3 SnapToCorner(Vector3 position)
		{
			position.x = (float)Math.Round(position.x / GridSize) * GridSize;
			position.y = (float)Math.Round(position.y / GridSize) * GridSize;
			position.z = (float)Math.Round(position.z / GridSize) * GridSize;
			return position;
		}

		private float AvoidZero(float value)
		{
			if (value >= 0f)
			{
				return Mathf.Max(GridSize, value);
			}
			return Mathf.Min(0f - GridSize, value);
		}

		public float SnapToSize(float val, bool avoidZero)
		{
			if (avoidZero)
			{
				val = AvoidZero(val);
			}
			return (float)Math.Round(val / GridSize) * GridSize;
		}

		public Vector3 SnapToSize(Vector3 size, bool avoidZero)
		{
			size.x = SnapToSize(size.x, avoidZero);
			size.y = SnapToSize(size.y, avoidZero);
			size.z = SnapToSize(size.z, avoidZero);
			return size;
		}

		public Vector3 SnapToCenter(Vector3 position)
		{
			Vector3 vector = Vector3.one * (GridSize * 0.5f);
			return SnapToCorner(position - vector) + vector;
		}

		private float SnapInternal(float val, float size)
		{
			float a = Mathf.Round(size / GridSize);
			a = Mathf.Max(a, 1f) * 0.5f;
			float num = Mathf.Round((val - size * 0.5f) / GridSize);
			return (num + a) * GridSize;
		}

		public Vector3 SnapToNearestTranslationIncrement(Vector3 position, Bounds selectionBounds)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnapToCenter)
			{
				position.x = SnapInternal(position.x, selectionBounds.size.x);
				position.y = SnapInternal(position.y, selectionBounds.size.y);
				position.z = SnapInternal(position.z, selectionBounds.size.z);
				return position;
			}
			Bounds bounds = selectionBounds;
			bounds.center = position;
			float num = bounds.min.x - Mathf.Round(bounds.min.x / GridSize) * GridSize;
			float num2 = bounds.min.y - Mathf.Round(bounds.min.y / GridSize) * GridSize;
			float num3 = bounds.min.z - Mathf.Round(bounds.min.z / GridSize) * GridSize;
			float num4 = bounds.max.x - Mathf.Round(bounds.max.x / GridSize) * GridSize;
			float num5 = bounds.max.y - Mathf.Round(bounds.max.y / GridSize) * GridSize;
			float num6 = bounds.max.z - Mathf.Round(bounds.max.z / GridSize) * GridSize;
			float x = ((!(Mathf.Abs(num) < Mathf.Abs(num4))) ? num4 : num);
			float y = ((!(Mathf.Abs(num2) < Mathf.Abs(num5))) ? num5 : num2);
			float z = ((!(Mathf.Abs(num3) < Mathf.Abs(num6))) ? num6 : num3);
			Vector3 vector = new Vector3(x, y, z);
			position -= vector;
			return position;
		}

		public static Vector3 GetClosestAxis(Vector3 dir, Quaternion rot)
		{
			Vector3 vector = Quaternion.Inverse(rot) * dir;
			if (Mathf.Abs(vector.x) > SIN_45)
			{
				return rot * Vector3.right * Mathf.Sign(vector.x);
			}
			if (Mathf.Abs(vector.y) > SIN_45)
			{
				return rot * Vector3.up * Mathf.Sign(vector.y);
			}
			return rot * Vector3.forward * Mathf.Sign(vector.z);
		}

		public Quaternion SnapToNearestRotationIncrement(Quaternion rotation)
		{
			if (SnapRotateAngleIncrement > 0f)
			{
				Quaternion rotation2 = Quaternion.LookRotation(GetClosestAxis(Vector3.forward, rotation), GetClosestAxis(Vector3.up, rotation));
				Quaternion quaternion = Quaternion.Inverse(rotation2) * rotation;
				Vector3 eulerAngles = rotation2.eulerAngles;
				eulerAngles.z = Mathf.Round(eulerAngles.z / SnapRotateAngleIncrement) * SnapRotateAngleIncrement;
				eulerAngles = Quaternion.Euler(eulerAngles).eulerAngles;
				eulerAngles.x = Mathf.Round(eulerAngles.x / SnapRotateAngleIncrement) * SnapRotateAngleIncrement;
				eulerAngles = Quaternion.Euler(eulerAngles).eulerAngles;
				eulerAngles.y = Mathf.Round(eulerAngles.y / SnapRotateAngleIncrement) * SnapRotateAngleIncrement;
				rotation2 = Quaternion.Euler(eulerAngles);
				rotation = rotation2 * quaternion;
			}
			return rotation;
		}

		public void UpdateStickyCenterPoint(Vector3 position)
		{
			StickyPos = SnapToCenter((!InsideStickyRegion(position)) ? position : StickyPos);
		}

		private bool InsideStickyRegion(Vector3 position)
		{
			float num = GridSize * 0.5f + Mathf.Min(GridSize * 0.2f, 0.1f);
			Vector3 vector = StickyPos - position;
			return Mathf.Abs(vector.x) < num && Mathf.Abs(vector.y) < num && Mathf.Abs(vector.z) < num;
		}
	}
	public class MakerPenVisuals : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private MakerPen makerPen;

		[SerializeField]
		private Transform extrusionPoint;

		[Header("Colors")]
		[SerializeField]
		private Renderer extruderStick;

		[Header("Pointer")]
		[SerializeField]
		private LineRenderer pointerLineRenderer;

		[SerializeField]
		private MeshRenderer pointerHitIndicator;

		[SerializeField]
		private float laserMaxDistanceDefault = 50f;

		[SerializeField]
		private float laserVisualMaxDistance = 15f;

		[Header("Snapping")]
		[SerializeField]
		private Transform gridSnapLineRenderersParent;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[SerializeField]
		private Animator animator;

		private LineRenderer[] gridSnapLineRenderers = new LineRenderer[0];

		private IDisposable localUpdateToken;

		private TokenMap<float> laserMaxDistanceOverride = new TokenMap<float>();

		private bool laserPointerEnabled;

		private static readonly int triggerId = Animator.StringToHash("TriggerOpenClose");

		private static readonly int extruderStickId = Animator.StringToHash("TubeRemaining");

		private float _triggerAmount;

		private float _tubeRemaining = 1f;

		public Tool Tool => _tool;

		public float LaserMaxDistance
		{
			get
			{
				if (laserMaxDistanceOverride.ContainsValues)
				{
					return laserMaxDistanceOverride.LatestValue;
				}
				return laserMaxDistanceDefault;
			}
		}

		public Vector3 LaserPointerPosition => pointerHitIndicator.transform.position;

		public Transform LaserPointerHitTransform => pointerHitIndicator.transform;

		public bool LaserPointerEnabled
		{
			get
			{
				return laserPointerEnabled;
			}
			set
			{
				laserPointerEnabled = value;
				pointerLineRenderer.gameObject.SetActive(laserPointerEnabled);
			}
		}

		public Vector3? LaserPointerTarget { get; set; }

		public Transform ExtrusionPoint => extrusionPoint;

		private float TriggerAmount
		{
			get
			{
				return _triggerAmount;
			}
			set
			{
				_triggerAmount = value;
				if (animator != null && animator.isActiveAndEnabled)
				{
					animator.SetFloat(triggerId, _triggerAmount);
				}
			}
		}

		private float TubeRemaining
		{
			get
			{
				return _tubeRemaining;
			}
			set
			{
				_tubeRemaining = value;
				if (animator != null && animator.isActiveAndEnabled)
				{
					animator.SetFloat(extruderStickId, _tubeRemaining);
				}
			}
		}

		private bool IsHeldByLocalPlayer => Tool.IsHeldByPlayer && Tool.HolderView.isLocal;

		private void Awake()
		{
			Tool.PostPickupEvent += Tool_PostPickupEvent;
			Tool.PostReleaseEvent += Tool_PostReleaseEvent;
			pointerLineRenderer.gameObject.SetActive(laserPointerEnabled);
			animator = GetComponentInChildren<Animator>();
			if (gridSnapLineRenderersParent != null)
			{
				gridSnapLineRenderers = gridSnapLineRenderersParent.GetComponentsInChildren<LineRenderer>(includeInactive: true);
			}
		}

		private void Start()
		{
			this.Update10hz(StaggeredUpdate);
		}

		private void OnDisable()
		{
			TriggerAmount = 0f;
		}

		private void OnDestroy()
		{
			Tool.PostPickupEvent -= Tool_PostPickupEvent;
			Tool.PostReleaseEvent -= Tool_PostReleaseEvent;
		}

		private void LocalUpdate()
		{
			if (IsHeldByLocalPlayer)
			{
				UpdateLocalLaserPointer();
			}
		}

		private void StaggeredUpdate(float deltaTime)
		{
			if (Tool.hasAuthority)
			{
				TriggerAmount = Tool.InputAmount;
				TubeRemaining = Mathf.Max(0f, 1f - (float)CreationManager.ActiveSandboxResourceCost / 30000f);
				if (makerPen != null)
				{
					bool enableGrid = makerPen.Snapping.IsActive && makerPen.CurrentToolMode == MakerPen.ToolMode.CreateShape;
					UpdateGridSnapVisuals(enableGrid);
				}
			}
			if (!IsHeldByLocalPlayer)
			{
				UpdateLaserPointerVisualOnly();
			}
		}

		private void Tool_PostPickupEvent(Tool thisTool)
		{
			if (IsHeldByLocalPlayer && localUpdateToken == null)
			{
				localUpdateToken = this.Update(LocalUpdate);
			}
		}

		private void Tool_PostReleaseEvent(Tool thisTool)
		{
			this.SafeStopSchedule(localUpdateToken);
			localUpdateToken = null;
		}

		public void SetLaserMaxDistance(float distance, object token)
		{
			laserMaxDistanceOverride.AddValue(distance, token);
		}

		public void ResetLaserMaxDistance(object token)
		{
			laserMaxDistanceOverride.RemoveValue(token);
		}

		private void UpdateLocalLaserPointer()
		{
			if (LaserPointerTarget.HasValue)
			{
				SetLaserPointerPosition(LaserPointerTarget.Value);
				return;
			}
			Vector3 pointerEndPosition = GetPointerEndPosition(LaserMaxDistance);
			SetLaserPointerPosition(pointerEndPosition);
		}

		private void UpdateLaserPointerVisualOnly()
		{
			if (LaserPointerEnabled)
			{
				RaycastHit hitInfo = default(RaycastHit);
				Vector3 laserPointerPosition = ((!Physics.Raycast(extrusionPoint.transform.position, extrusionPoint.transform.forward, out hitInfo, laserVisualMaxDistance, 1267084289, QueryTriggerInteraction.Ignore)) ? GetPointerEndPosition(laserVisualMaxDistance) : hitInfo.point);
				SetLaserPointerPosition(laserPointerPosition);
			}
		}

		private void SetLaserPointerPosition(Vector3 endPosition)
		{
			pointerHitIndicator.transform.position = endPosition;
			pointerLineRenderer.SetPosition(0, extrusionPoint.transform.position);
			pointerLineRenderer.SetPosition(1, endPosition);
		}

		public void SetLaserPointerColor(Color color)
		{
			pointerLineRenderer.material.SetColor(ShaderIDs.MAIN_COLOR, color);
			pointerLineRenderer.material.SetColor(ShaderIDs.SCANLINE_COLOR, color);
			pointerHitIndicator.material.SetColor(ShaderIDs.MAIN_COLOR, color);
			pointerHitIndicator.material.SetColor(ShaderIDs.SCANLINE_COLOR, color);
		}

		private Vector3 GetPointerEndPosition(float distance)
		{
			return extrusionPoint.transform.position + extrusionPoint.transform.forward * distance;
		}

		public void UpdateGridSnapVisuals(bool enableGrid)
		{
			if (gridSnapLineRenderers.Length == 0)
			{
				return;
			}
			if (enableGrid && IsHeldByLocalPlayer && makerPen != null)
			{
				float gridSize = makerPen.Snapping.GridSize;
				Vector3 stickyPos = makerPen.Snapping.StickyPos;
				stickyPos -= Vector3.one * (gridSize * 0.5f);
				int num = 2;
				int num2 = 2;
				int num3 = 2;
				int num4 = 0;
				float x = stickyPos.x;
				float z;
				float y;
				for (int i = 0; i < num2; i++)
				{
					y = stickyPos.y + (float)i * gridSize;
					for (int j = 0; j < num3; j++)
					{
						z = stickyPos.z + (float)j * gridSize;
						Vector3 vector = new Vector3(x, y, z);
						Vector3 position = vector + Vector3.right * gridSize;
						gridSnapLineRenderers[num4].SetPosition(0, vector);
						gridSnapLineRenderers[num4].SetPosition(1, position);
						num4++;
					}
				}
				y = stickyPos.y;
				for (int k = 0; k < num; k++)
				{
					x = stickyPos.x + (float)k * gridSize;
					for (int l = 0; l < num3; l++)
					{
						z = stickyPos.z + (float)l * gridSize;
						Vector3 vector = new Vector3(x, y, z);
						Vector3 position = vector + Vector3.up * gridSize;
						gridSnapLineRenderers[num4].SetPosition(0, vector);
						gridSnapLineRenderers[num4].SetPosition(1, position);
						num4++;
					}
				}
				z = stickyPos.z;
				for (int m = 0; m < num; m++)
				{
					x = stickyPos.x + (float)m * gridSize;
					for (int n = 0; n < num2; n++)
					{
						y = stickyPos.y + (float)n * gridSize;
						Vector3 vector = new Vector3(x, y, z);
						Vector3 position = vector + Vector3.forward * gridSize;
						gridSnapLineRenderers[num4].SetPosition(0, vector);
						gridSnapLineRenderers[num4].SetPosition(1, position);
						num4++;
					}
				}
			}
			if (gridSnapLineRenderers[0].enabled != enableGrid)
			{
				for (int num5 = 0; num5 < gridSnapLineRenderers.Length; num5++)
				{
					gridSnapLineRenderers[num5].enabled = enableGrid;
				}
			}
		}

		public void UpdateTubeColor(Color newColor)
		{
			extruderStick.material.color = newColor;
		}
	}
}
