			Controller = controller;
		}

		public virtual void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
		}

		public virtual void OnUpdateState()
		{
		}

		public virtual void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
		}

		protected int UpdateGravityPicking<T>(ISelectionContext<T> context, T[] pickingResults, ref Vector3 lastHitPoint, ref Collider lastHitCollider, out bool useMagnet)
		{
			if (OffHand.HeldTool != null)
			{
				useMagnet = false;
				return 0;
			}
			Vector3 physicalPickupOrigin = OffHand.PhysicalPickupOrigin;
			int num = context.SpherecastPick(physicalPickupOrigin, OffHand.PhysicalPickupSphereRadius, OffHand.GravityPickupDirection, OffHand.GravityPickupCapsuleLength, pickingResults, out lastHitPoint, out lastHitCollider);
			float physicalPickupSphereRadius = OffHand.PhysicalPickupSphereRadius;
			useMagnet = num > 0 && (lastHitPoint - physicalPickupOrigin).sqrMagnitude > physicalPickupSphereRadius * physicalPickupSphereRadius;
			return num;
		}

		protected bool AreRaycastObjectHitsAllInSelection()
		{
			return IsAlreadySelected(ObjectContext, RAYCAST_OBJECTS_LAST_HIT_COUNT, RAYCAST_OBJECTS_RESULTS);
		}

		protected bool AreRaycastShapeHitsAllInSelection()
		{
			return IsAlreadySelected(ShapeContext, RAYCAST_SHAPES_LAST_HIT_COUNT, RAYCAST_SHAPES_RESULTS);
		}

		protected bool IsAlreadySelected<T>(ISelectionContext<T> context, int lastHitCount, T[] pickingResults)
		{
			if (lastHitCount <= 0)
			{
				return false;
			}
			bool result = true;
			for (int i = 0; i < lastHitCount; i++)
			{
				if (!context.IsSelected(pickingResults[i]))
				{
					result = false;
					break;
				}
			}
			return result;
		}
	}
	[Serializable]
	public class MakerPenVROffHandTranslate<T> : MakerPenVROffHandOperation
	{
		[NonSerialized]
		protected bool clearSelectionOnRelease;

		[NonSerialized]
		protected bool isPerformingMove;

		[NonSerialized]
		protected Vector3 pickupRelativePivotPoint;

		[NonSerialized]
		protected float pickupStartTime;

		[NonSerialized]
		protected float magnetDuration;

		[NonSerialized]
		protected Quaternion handRotationOffset;

		[NonSerialized]
		protected Vector3 objectPickupOffset;

		[NonSerialized]
		protected Vector3 worldPickupPosition;

		[NonSerialized]
		protected Quaternion prevSnappedRot;

		[NonSerialized]
		protected Vector3 prevSnappedPos;

		[NonSerialized]
		protected Vector3 prevFrameSelectionWorldPos;

		[NonSerialized]
		protected UndoEntry pendingUndoEntry;

		private const float MAGNET_DURATION_MIN = 0.03f;

		private const float MAGNET_DURATION_MAX = 0.15f;

		private const float SNAPPING_STICKYNESS = 0.4f;

		private const float SNAPPING_SMOOTHNESS = 0.3f;

		private const float SNAPPING_ROT_SMOOTHNESS = 0.4f;

		private RotatedBoundsCollision rotatedBoundsCollision = new RotatedBoundsCollision();

		protected virtual ISelectionContext<T> SelectionContext { get; }

		protected virtual int MaxAllowedBounds => 1;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousSubStateId);
			isPerformingMove = false;
			clearSelectionOnRelease = false;
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			FinishMovement();
		}

		protected virtual MakerPen.ToolMode GetMakerPenToolToPush()
		{
			return MakerPen.ToolMode.OffHandCompanion;
		}

		protected void UpdateInternal(T[] pickingResults, ref int lastHitCount, ref Vector3 lastHitPoint, ref Collider lastHitCollider)
		{
			if (base.OffHand.HeldTool != null)
			{
				FinishMovement();
			}
			else if (isPerformingMove)
			{
				if (base.OffHandInput.HairTriggerButtonPressed || base.OffHandInput.HairPickupButtonPressed)
				{
					UpdateMovement();
				}
				else
				{
					FinishMovement();
				}
			}
			else
			{
				lastHitCount = UpdateGravityPicking(SelectionContext, pickingResults, ref lastHitPoint, ref lastHitCollider, out var useMagnet);
				if (useMagnet && !ValidateGravityPicks(pickingResults, lastHitCount))
				{
					lastHitCount = 0;
				}
				if (lastHitCount > 0)
				{
					SelectionContext.RenderHoverHighlight(lastHitCount, pickingResults);
				}
				if ((base.OffHandInput.HairTriggerButtonDown || base.OffHandInput.HairPickupButtonDown) && lastHitCount > 0 && (base.OffHand.DefaultHandVisualsActive || base.OffHand.ExpressoInfoGestureActive))
				{
					base.MakerPen.AuthorityPushPenTool(GetMakerPenToolToPush());
					base.MakerPen.ToolModeLocked = true;
					bool flag = IsAlreadySelected(SelectionContext, lastHitCount, pickingResults);
					if (!flag)
					{
						SelectionContext.RemoveAllFromSelection();
						SelectionContext.AddToSelection(lastHitCount, pickingResults);
					}
					clearSelectionOnRelease = !flag;
					InitializeMovement(useMagnet, lastHitPoint);
				}
			}
			base.OffHand.HideHand(isPerformingMove);
		}

		protected virtual bool ValidateGravityPicks(T[] pickingResults, int numResults)
		{
			return true;
		}

		protected virtual void InitializeMovement(bool useGravityPickup, Vector3 pickupPosition)
		{
			if (base.MakerPen.Snapping.IsActive)
			{
				base.Controller.TranslationSnappingVisualization.Enable(SelectionContext, base.MakerPen.Snapping.GridSize);
			}
			isPerformingMove = true;
			objectPickupOffset = Quaternion.Inverse(SelectionContext.SelectionTransform.rotation) * (pickupPosition - SelectionContext.SelectionTransform.position);
			if (useGravityPickup && !base.MakerPen.Snapping.IsActive)
			{
				worldPickupPosition = pickupPosition;
				magnetDuration = Mathf.Lerp(0.03f, 0.15f, Mathf.Min(Vector3.Distance(worldPickupPosition, base.OffHand.PhysicalPickupOrigin), 1f));
			}
			else
			{
				magnetDuration = 0f;
			}
			handRotationOffset = Quaternion.Inverse(base.OffHand.PhysicalPickupOriginTransform.rotation) * SelectionContext.SelectionTransform.rotation;
			pickupStartTime = UnityEngine.Time.realtimeSinceStartup;
			prevSnappedRot = SelectionContext.SelectionTransform.rotation;
			prevSnappedPos = SelectionContext.SelectionBounds.center;
			SelectionRenderer.Enabled = false;
			rotatedBoundsCollision.ClearBounds();
			if (base.MakerPen.AlignToObjects && AllowCollisionSnapping())
			{
				rotatedBoundsCollision.SetupBounds(SelectionContext, MaxAllowedBounds, pickupPosition, SelectionContext.SelectionTransform.rotation, base.MakerPen.AlignToEdges);
			}
			prevFrameSelectionWorldPos = SelectionContext.SelectionTransform.position;
		}

		protected virtual bool AllowCollisionSnapping()
		{
			return true;
		}

		protected virtual bool IgnoreCollision(Collider collider)
		{
			Tool colliderTool = collider.GetColliderTool();
			if (colliderTool == base.MakerPen.Tool)
			{
				return true;
			}
			foreach (ToolCollider selectionToolCollider in SelectionContext.GetSelectionToolColliders())
			{
				if (selectionToolCollider.Tool == colliderTool)
				{
					return true;
				}
			}
			return false;
		}

		protected void UpdateMovement()
		{
			if (!isPerformingMove)
			{
				return;
			}
			float t = ((!(magnetDuration > 0f)) ? 1f : Math.Min((UnityEngine.Time.realtimeSinceStartup - pickupStartTime) / magnetDuration, 1f));
			Vector3 newPivotPoint = Vector3.Lerp(worldPickupPosition, base.OffHand.PhysicalPickupOrigin, t);
			Vector3 vector = SelectionContext.SelectionTransform.position - prevFrameSelectionWorldPos;
			if (vector.sqrMagnitude > float.Epsilon)
			{
				objectPickupOffset -= Quaternion.Inverse(SelectionContext.SelectionTransform.rotation) * vector;
				if (base.MakerPen.AlignToObjects && AllowCollisionSnapping())
				{
					UnityEngine.Debug.Log("Recalculating bounds");
					rotatedBoundsCollision.ClearBounds();
					rotatedBoundsCollision.SetupBounds(SelectionContext, MaxAllowedBounds, newPivotPoint, SelectionContext.SelectionTransform.rotation, base.MakerPen.AlignToEdges);
				}
			}
			bool isActive = base.MakerPen.Snapping.IsActive;
			bool freezeRotationOnMove = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.FreezeRotationOnMove;
			Quaternion newPenRotation = ((!freezeRotationOnMove) ? (base.OffHand.PhysicalPickupOriginTransform.rotation * handRotationOffset) : SelectionContext.SelectionTransform.rotation);
			rotatedBoundsCollision.UpdateCollisionSnapping(ref newPivotPoint, ref newPenRotation, !isActive, !freezeRotationOnMove, IgnoreCollision);
			if (!freezeRotationOnMove)
			{
				if (isActive)
				{
					newPenRotation = Quaternion.Slerp(newPenRotation, prevSnappedRot, 0.4f);
					prevSnappedRot = base.MakerPen.Snapping.SnapToNearestRotationIncrement(newPenRotation);
					newPenRotation = Quaternion.Slerp(prevSnappedRot, SelectionContext.SelectionTransform.rotation, 0.4f);
				}
				Quaternion angularDisplacement = newPenRotation * Quaternion.Inverse(SelectionContext.SelectionTransform.rotation);
				SelectionContext.RotateSelection(angularDisplacement, SelectionContext.SelectionBounds.center);
			}
			Vector3 vector2 = newPivotPoint - SelectionContext.SelectionTransform.rotation * objectPickupOffset;
			vector2 += SelectionContext.SelectionBounds.center - SelectionContext.SelectionTransform.position;
			if (isActive)
			{
				Vector3 position = Vector3.Lerp(vector2, prevSnappedPos, 0.4f);
				prevSnappedPos = base.MakerPen.Snapping.SnapToNearestTranslationIncrement(position, SelectionContext.SelectionBounds);
				vector2 = Vector3.Lerp(prevSnappedPos, SelectionContext.SelectionBounds.center, 0.3f);
			}
			Vector3 linearDisplacement = vector2 - SelectionContext.SelectionBounds.center;
			SelectionContext.TranslateSelection(linearDisplacement);
			prevFrameSelectionWorldPos = SelectionContext.SelectionTransform.position;
		}

		protected void FinishMovement()
		{
			base.Controller.TranslationSnappingVisualization.Disable();
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(base.ObjectContext);
				base.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			if (clearSelectionOnRelease)
			{
				ReleaseSelection();
				clearSelectionOnRelease = false;
			}
			isPerformingMove = false;
			SelectionRenderer.Enabled = true;
			base.MakerPen.ToolModeLocked = false;
			base.OffHand.HideHand(hide: false);
			if (base.MakerPen.CurrentToolMode == MakerPen.ToolMode.OffHandCompanion || base.MakerPen.CurrentToolMode == MakerPen.ToolMode.Manipulate)
			{
				base.MakerPen.AuthorityPopPenTool();
			}
		}

		protected virtual void ReleaseSelection()
		{
			SelectionContext.RemoveAllFromSelection();
		}
	}
	[Serializable]
	public class MakerPenVROffHandTranslate_Object : MakerPenVROffHandTranslate<CreationObject>
	{
		protected override ISelectionContext<CreationObject> SelectionContext
		{
			[CompilerGenerated]
			get
			{
				return base.ObjectContext;
			}
		}

		public override void OnUpdateState()
		{
			bool isActive = base.MakerPen.Snapping.IsActive;
			if (!isActive)
			{
				MakerPenSelectionCache.Instance.CacheSelection(base.ObjectContext);
			}
			base.OnUpdateState();
			UpdateInternal(MakerPenVROffHandOperation.RAYCAST_OBJECTS_RESULTS, ref MakerPenVROffHandOperation.RAYCAST_OBJECTS_LAST_HIT_COUNT, ref MakerPenVROffHandOperation.RAYCAST_OBJECTS_LAST_HIT_POINT, ref MakerPenVROffHandOperation.RAYCAST_OBJECTS_LAST_HIT_COLLIDER);
			if (!isActive)
			{
				MakerPenSelectionCache.Instance.CalculateVelocityOnAll();
			}
		}

		protected override void InitializeMovement(bool useGravityPickup, Vector3 pickupPosition)
		{
			base.ObjectContext.DisableDynamicCollisionForSelectionUntilDeSelected();
			base.InitializeMovement(useGravityPickup, pickupPosition);
			pendingUndoEntry = new TransformObjectsUndoEntry("move", base.ObjectContext.CurrentSelection, base.ObjectContext, transformRotations: true);
		}

		protected override void ReleaseSelection()
		{
			base.OffHand.DisableCollisionForThrowRelease(base.ObjectContext.CurrentSelection?.FirstOrDefault()?.Tool);
			if (!base.MakerPen.Snapping.IsActive)
			{
				MakerPenSelectionCache.Instance.DeselectAndApplyVelocityOnAll(base.ObjectContext);
			}
			else
			{
				SelectionContext.RemoveAllFromSelection();
			}
		}

		protected override bool ValidateGravityPicks(CreationObject[] pickingResults, int numResults)
		{
			CreationObject creationObject = pickingResults[0];
			return numResults > 0 && !creationObject.IsFrozen && creationObject.Tool.CanBePickedUp;
		}

		protected override bool AllowCollisionSnapping()
		{
			return base.ObjectContext.SelectionCount == 1;
		}
	}
