	[Serializable]
	public abstract class MakerPenVRTool
	{
		[SerializeField]
		private float minPointerHoverThreshold = 0.01f;

		[SerializeField]
		private float maxPointerHoverThreshold = 0.4f;

		[SerializeField]
		private float minPointerHoverThresholdDist = 0.5f;

		[SerializeField]
		private float maxPointerHoverThresholdDist = 10f;

		protected static CreationObject[] RAYCAST_OBJECTS_RESULTS = new CreationObject[256];

		protected static int RAYCAST_OBJECTS_LAST_HIT_COUNT = 0;

		protected static Vector3 RAYCAST_OBJECTS_LAST_HIT_POINT = Vector3.zero;

		protected static Collider RAYCAST_OBJECTS_LAST_HIT_COLLIDER = null;

		protected static Guid[] RAYCAST_SHAPES_RESULTS = new Guid[256];

		protected static int RAYCAST_SHAPES_LAST_HIT_COUNT = 0;

		protected static Vector3 RAYCAST_SHAPES_LAST_HIT_POINT = Vector3.zero;

		protected static Collider RAYCAST_SHAPES_LAST_HIT_COLLIDER = null;

		protected static ConnectionPoint[] RAYCAST_CONNECTION_POINTS_RESULTS = new ConnectionPoint[256];

		protected static int RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT = 0;

		protected static Vector3 RAYCAST_CONNECTION_POINTS_LAST_HIT_POINT = Vector3.zero;

		[SerializeField]
		private bool pointerEnabled = true;

		[SerializeField]
		[ConditionalField("PointerEnabled")]
		protected Color pointerColor = Color.white;

		[NonSerialized]
		private GameObject previouslyHoveredObject;

		private Vector3 previousHitPoint;

		private float previousHitDistance;

		[NonSerialized]
		private MakerPen.TargetMode targetMode;

		[NonSerialized]
		private MakerPen.ToolMode toolMode;

		[NonSerialized]
		private VRCreationController _controller;

		public bool PointerEnabled => pointerEnabled;

		protected VRCreationController Controller
		{
			get
			{
				return _controller;
			}
			private set
			{
				_controller = value;
			}
		}

		protected MakerPen MakerPen => Controller.MakerPen;

		protected MakerPenVisuals PenVisuals => Controller.MakerPen.PenVisuals;

		protected CreationContext ObjectContext => Controller.CreationContext;

		protected ShapeCreationContext ShapeContext => Controller.CreationContext.ShapeCreationContext;

		protected ConnectionCreationContext ConnectionContext => Controller.CreationContext.ConnectionCreationContext;

		protected VRInputHandler Input => Controller.ToolInput;

		protected virtual bool ShouldRenderConnectionHover
		{
			[CompilerGenerated]
			get
			{
				return false;
			}
		}

		public MakerPenVRTool()
		{
		}

		public virtual void Initialize(VRCreationController controller, MakerPen.TargetMode targetMode, MakerPen.ToolMode toolMode)
		{
			Controller = controller;
			this.targetMode = targetMode;
			this.toolMode = toolMode;
		}

		public virtual void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			PenVisuals.SetLaserPointerColor(pointerColor);
			PenVisuals.LaserPointerEnabled = PointerEnabled;
			PenVisuals.LaserPointerTarget = null;
		}

		public virtual void OnUpdateState()
		{
			UpdateHoverAndTooltips();
		}

		public virtual void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			PenVisuals.LaserPointerEnabled = false;
		}

		public void PushAsActiveTool()
		{
			if (MakerPen.CurrentTargetMode != targetMode)
			{
				UnityEngine.Debug.LogError($"Trying to push {this} as active MakerPen tool, but the MakerPen is in invalid target mode {MakerPen.CurrentTargetMode}");
			}
			else
			{
				MakerPen.AuthorityPushPenTool(toolMode);
			}
		}

		protected void UpdateObjectPicking(bool shouldRenderHover, OutlineEffectRenderer.OutlineType? outlineType = null)
		{
			UpdatePicking(ObjectContext, RAYCAST_OBJECTS_RESULTS, ref RAYCAST_OBJECTS_LAST_HIT_COUNT, ref RAYCAST_OBJECTS_LAST_HIT_POINT, ref RAYCAST_OBJECTS_LAST_HIT_COLLIDER, shouldRenderHover, outlineType);
		}

		protected bool AreRaycastObjectHitsAllInSelection()
		{
			return IsAlreadySelected(ObjectContext, RAYCAST_OBJECTS_LAST_HIT_COUNT, RAYCAST_OBJECTS_RESULTS);
		}

		protected void UpdateShapePicking(bool shouldRenderHover, OutlineEffectRenderer.OutlineType? outlineType = null)
		{
			UpdatePicking(ShapeContext, RAYCAST_SHAPES_RESULTS, ref RAYCAST_SHAPES_LAST_HIT_COUNT, ref RAYCAST_SHAPES_LAST_HIT_POINT, ref RAYCAST_SHAPES_LAST_HIT_COLLIDER, shouldRenderHover, outlineType);
		}

		protected bool AreRaycastShapeHitsAllInSelection()
		{
			return IsAlreadySelected(ShapeContext, RAYCAST_SHAPES_LAST_HIT_COUNT, RAYCAST_SHAPES_RESULTS);
		}

		protected Vector3 GetDesiredCreationPosition()
		{
			return GetDesiredCreationPosition(Vector3.zero);
		}

		protected Vector3 GetDesiredCreationPosition(Vector3 offset)
		{
			return MakerPen.ActionPointerPosition + offset;
		}

		protected void UpdateConnectionPointer(bool shouldRenderHover)
		{
			RaycastConnectionPointsFromPen();
			if (RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT > 0)
			{
				if (shouldRenderHover)
				{
					ConnectionContext.RenderHoverHighlight(RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT, RAYCAST_CONNECTION_POINTS_RESULTS);
				}
				PenVisuals.LaserPointerTarget = RAYCAST_CONNECTION_POINTS_LAST_HIT_POINT;
			}
			else
			{
				PenVisuals.LaserPointerTarget = null;
			}
		}

		protected void RaycastConnectionPointsFromPen()
		{
			RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT = ConnectionContext.RaycastPickConnectionPoints(PenVisuals.ExtrusionPoint.position, PenVisuals.ExtrusionPoint.forward, PenVisuals.LaserMaxDistance, RAYCAST_CONNECTION_POINTS_RESULTS, out RAYCAST_CONNECTION_POINTS_LAST_HIT_POINT);
		}

		private void UpdateHoverAndTooltips()
		{
			UpdateConnectionPointer(ShouldRenderConnectionHover);
			Tooltip tooltip = null;
			Vector3 value = Vector3.zero;
			bool flag = RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT > 0;
			bool flag2 = RAYCAST_OBJECTS_LAST_HIT_COUNT > 0 && RAYCAST_OBJECTS_RESULTS[0] != null;
			if (flag || flag2)
			{
				GameObject gameObject = ((!flag) ? RAYCAST_OBJECTS_RESULTS[0].gameObject : RAYCAST_CONNECTION_POINTS_RESULTS[0].gameObject);
				value = ((!flag) ? RAYCAST_OBJECTS_LAST_HIT_POINT : RAYCAST_CONNECTION_POINTS_LAST_HIT_POINT);
				tooltip = gameObject.GetComponent<Tooltip>();
				previouslyHoveredObject = gameObject;
				previousHitPoint = value;
				previousHitDistance = (previousHitPoint - PenVisuals.ExtrusionPoint.position).magnitude;
			}
			else if (previouslyHoveredObject != null)
			{
				float value2 = Vector3.Distance(PenVisuals.ExtrusionPoint.position, previousHitPoint);
				float t = Mathf.Clamp01(Mathf.InverseLerp(minPointerHoverThresholdDist, maxPointerHoverThresholdDist, value2));
				float num = Mathf.Lerp(minPointerHoverThreshold, maxPointerHoverThreshold, t);
				Vector3 vector = PenVisuals.ExtrusionPoint.position + PenVisuals.ExtrusionPoint.forward * previousHitDistance;
				if ((vector - previousHitPoint).sqrMagnitude < num * num)
				{
					tooltip = previouslyHoveredObject.GetComponent<Tooltip>();
					value = vector;
				}
				else
				{
					previouslyHoveredObject = null;
				}
			}
			if (tooltip != null)
			{
				tooltip.Refresh();
				PenVisuals.LaserPointerTarget = value;
				tooltip.SetHoverPoint(PenVisuals.LaserPointerHitTransform);
			}
		}

		private void UpdatePicking<T>(ISelectionContext<T> context, T[] pickingResults, ref int lastHitCount, ref Vector3 lastHitPoint, ref Collider lastHitCollider, bool shouldRenderHover, OutlineEffectRenderer.OutlineType? outlineType)
		{
			lastHitCount = context.RaycastPick(PenVisuals.ExtrusionPoint.position, PenVisuals.ExtrusionPoint.forward, PenVisuals.LaserMaxDistance, pickingResults, out lastHitPoint, out lastHitCollider);
			if (lastHitCount > 0)
			{
				if (shouldRenderHover)
				{
					if (outlineType.HasValue)
					{
						context.RenderHoverHighlight(lastHitCount, pickingResults, outlineType.Value);
					}
					else
					{
						context.RenderHoverHighlight(lastHitCount, pickingResults);
					}
				}
				PenVisuals.LaserPointerTarget = lastHitPoint;
			}
			else
			{
				PenVisuals.LaserPointerTarget = null;
			}
		}

		private bool IsAlreadySelected<T>(ISelectionContext<T> context, int lastHitCount, T[] pickingResults)
		{
			if (lastHitCount <= 0)
			{
				return false;
			}
			bool result = true;
			for (int i = 0; i < lastHitCount; i++)
			{
				if (!context.IsSelected(pickingResults[i]))
				{
					result = false;
					break;
				}
			}
			return result;
		}
	}
	[Serializable]
	public class MakerPenVRClone : MakerPenVRTool
	{
		private Vector3 selectionStartPenRelativePosition;

		private Quaternion selectionStartPenRelativeRotation;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(!base.Input.HairTriggerButtonPressed);
			if (!base.Input.HairTriggerButtonDown || MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT <= 0)
			{
				return;
			}
			if (!AreRaycastObjectHitsAllInSelection())
			{
				base.ObjectContext.RemoveAllFromSelection();
				base.ObjectContext.AddToSelection(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_OBJECTS_RESULTS);
			}
			base.ObjectContext.DisableDynamicCollisionForSelectionUntilDeSelected();
			IPromise<CreationManager.SpawnTemplateResult> promise = base.ObjectContext.CloneSelection();
			promise.Then(delegate(CreationManager.SpawnTemplateResult result)
			{
				SingletonMonoBehaviour<Scheduler>.Instance.Run(base.MakerPen, base.ObjectContext.WaitForValidBoundsOnCloneResult(result, delegate
				{
					OnCloneResult(result);
				}));
			});
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
		}

		private void OnCloneResult(CreationManager.SpawnTemplateResult data)
		{
			if (data.result != CreationResult.Success || data.spawnedTools == null)
			{
				return;
			}
			base.ObjectContext.RemoveAllFromSelection();
			foreach (Tool spawnedTool in data.spawnedTools)
			{
				base.ObjectContext.AddToSelection(spawnedTool.CreationObject);
			}
			base.ObjectContext.DisableDynamicCollisionForSelectionUntilDeSelected();
			base.Controller.TranslateTool.PushAsActiveTool(new CreateObjectsUndoEntry("clone", base.ObjectContext.CurrentSelection, base.ObjectContext));
		}
	}
	[Serializable]
	public class MakerPenVRClone_Shape : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateShapePicking(!base.Input.HairTriggerButtonPressed);
			if (base.Input.HairTriggerButtonDown && MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0)
			{
				if (!AreRaycastShapeHitsAllInSelection())
				{
					base.ShapeContext.RemoveAllFromSelection();
					base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_SHAPES_RESULTS);
				}
				CreationResult creationResult = base.ShapeContext.TryCloneSelectedShapes();
				if (creationResult == CreationResult.Success)
				{
					CloneShapesUndoEntry pendingUndoEntry = new CloneShapesUndoEntry(base.ShapeContext.SelectedShapeContainer, base.ShapeContext.CurrentSelection, base.ObjectContext);
					base.Controller.TranslateShapeTool.PushAsActiveTool(pendingUndoEntry);
					base.ShapeContext.CheckNotifyResourceLimits();
				}
				else
				{
					base.MakerPen.RaiseInvalidActionPerformed(creationResult, "Clone failed", null);
				}
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
		}
	}
	[Serializable]
	public class MakerPenVRConnect : MakerPenVRTool
	{
		[SerializeField]
		private CircuitLinkVisual connectionVisualPrefab;

		private CircuitLinkVisual _connectionVisual;

		private float visualBeamDistance;

		private CircuitLinkVisual ConnectionVisual
		{
			get
			{
				if (_connectionVisual == null)
				{
					_connectionVisual = UnityEngine.Object.Instantiate(connectionVisualPrefab);
					_connectionVisual.gameObject.name = "MakerPenConnectionVisual";
				}
				return _connectionVisual;
			}
		}

		protected override bool ShouldRenderConnectionHover
		{
			[CompilerGenerated]
			get
			{
				return true;
			}
		}

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			base.ObjectContext.RemoveAllFromSelection();
			SetConnectionLineRendererEnabled(enabled: false);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			if (base.Input.HairTriggerButtonUp)
			{
				if (base.ConnectionContext.HasStartPoint)
				{
					if (MakerPenVRTool.RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT == 1)
					{
						base.ConnectionContext.ConnectToStartPoint(MakerPenVRTool.RAYCAST_CONNECTION_POINTS_RESULTS[0]);
					}
					base.ConnectionContext.DeselectStartPoint();
					SetConnectionLineRendererEnabled(enabled: false);
				}
			}
			else if (base.Input.HairTriggerButtonDown)
			{
				if (MakerPenVRTool.RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT == 1 && base.ConnectionContext.SelectStartPoint(MakerPenVRTool.RAYCAST_CONNECTION_POINTS_RESULTS[0]))
				{
					SetConnectionLineRendererEnabled(enabled: true);
					visualBeamDistance = (MakerPenVRTool.RAYCAST_CONNECTION_POINTS_LAST_HIT_POINT - base.PenVisuals.ExtrusionPoint.position).magnitude + 0.25f;
				}
			}
			else if (base.Input.HairTriggerButtonPressed && base.ConnectionContext.HasStartPoint)
			{
				Vector3 vector = base.PenVisuals.LaserPointerPosition;
				if (MakerPenVRTool.RAYCAST_CONNECTION_POINTS_LAST_HIT_COUNT == 0)
				{
					vector = base.PenVisuals.ExtrusionPoint.position + visualBeamDistance * base.PenVisuals.ExtrusionPoint.forward;
					base.PenVisuals.LaserPointerTarget = vector;
				}
				ConnectionVisual.LineRenderer.startColor = base.ConnectionContext.ConnectionColor;
				Vector3 connectionStartPosition = base.ConnectionContext.ConnectionStartPosition;
				ConnectionVisual.LineRenderer.SetPositions(new Vector3[2] { connectionStartPosition, vector });
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			base.ConnectionContext.DeselectStartPoint();
			SetConnectionLineRendererEnabled(enabled: false);
		}

		private void SetConnectionLineRendererEnabled(bool enabled)
		{
			ConnectionVisual.LineRenderer.gameObject.SetActive(enabled);
			ConnectionVisual.CircuitVisibilityBehaviour.ForceDisabled = !enabled;
		}
	}
	[Serializable]
	public class MakerPenVRCreateEquipment : MakerPenVRTool
	{
		private bool moveEquipmentOnReceive;

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			if (base.Input.HairTriggerButtonDown)
			{
				SpawnableToolType selectedEquipmentType = GetSelectedEquipmentType();
				if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordTool(selectedEquipmentType))
				{
					Vector3 position = CalculateSpawnPosition(selectedEquipmentType);
					Quaternion rotation = base.MakerPen.ActionPointerRotation;
					if (base.MakerPen.Snapping.IsActive)
					{
						rotation = base.MakerPen.Snapping.SnapToNearestRotationIncrement(rotation);
					}
					moveEquipmentOnReceive = true;
					NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnTool(selectedEquipmentType, position, rotation, 1f).Then(delegate(Tool tool)
					{
						OnEquipmentReceived(tool);
					});
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Not enough ink!", 3f);
				}
			}
			else if (base.Input.HairTriggerButtonUp)
			{
				moveEquipmentOnReceive = false;
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			moveEquipmentOnReceive = false;
			base.OnExitState(nextStateId, nextSubStateId);
		}

		private void OnEquipmentReceived(Tool receivedTool)
		{
			if (moveEquipmentOnReceive && (bool)receivedTool)
			{
				moveEquipmentOnReceive = false;
				base.ObjectContext.RemoveAllFromSelection();
				base.ObjectContext.AddToSelection(receivedTool.CreationObject);
				base.Controller.TranslateTool.PushAsActiveTool(new CreateObjectsUndoEntry("create", base.ObjectContext.CurrentSelection, base.ObjectContext));
			}
		}

		private SpawnableToolType GetSelectedEquipmentType()
		{
			return base.MakerPen.SelectedSpawnableToolType;
		}

		private Vector3 CalculateSpawnPosition(SpawnableToolType equipmentToSpawn)
		{
			Vector3 offset = Vector3.zero;
			GameObject gameObject = SpawnableToolSettings.GetSpawnableToolPrefab(equipmentToSpawn).gameObject;
			gameObject.transform.position = Vector3.zero;
			Bounds bounds = gameObject.CalculateRendererBounds();
			if (bounds.extents.sqrMagnitude > Mathf.Epsilon)
			{
				float num = Mathf.Max(bounds.extents.x, bounds.extents.z);
				offset = base.PenVisuals.ExtrusionPoint.forward * num;
			}
			Vector3 vector = GetDesiredCreationPosition(offset);
			if (base.MakerPen.Snapping.IsActive)
			{
				vector = base.MakerPen.Snapping.SnapToCorner(vector);
			}
			return vector;
		}
	}
	[Serializable]
	public class MakerPenVRCreateInvention : MakerPenVRTool
	{
		private bool isSelectingOnDrag;

		private float minCollisionDist;

		private const float DRAG_SELECT_DISTANCE_THRESHOLD = 2f;

		private CreationObject lastSelectedObject;

		private Vector3 lastHitPoint = Vector3.zero;

		private bool lastClickWasMenuClick;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			base.ObjectContext.RemoveAllFromSelection();
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			if (base.MakerPen.IsSelectingInventionObjects)
			{
				UpdateSelection();
			}
		}

		private void UpdateSelection()
		{
			RaycastHit hitInfo;
			bool flag = base.MakerPen.QuickActionMenu.UpdateHover(new Ray(base.PenVisuals.ExtrusionPoint.position, base.PenVisuals.ExtrusionPoint.forward), out hitInfo, base.PenVisuals.LaserMaxDistance);
			if (flag)
			{
				base.PenVisuals.LaserPointerTarget = hitInfo.point;
				MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT = 0;
			}
			else
			{
				UpdateObjectPicking(shouldRenderHover: true);
			}
			if (base.Input.HairTriggerButtonDown)
			{
				if (flag)
				{
					base.MakerPen.QuickActionMenu.TryClick();
					lastClickWasMenuClick = true;
					return;
				}
				lastClickWasMenuClick = false;
				base.MakerPen.QuickActionMenu.CloseMenu();
				minCollisionDist = float.MaxValue;
				isSelectingOnDrag = false;
				if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
				{
					for (int i = 0; i < MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT; i++)
					{
						CreationObject creationObject = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[i];
						if (base.ObjectContext.IsSelected(creationObject))
						{
							base.ObjectContext.RemoveFromSelection(creationObject);
							lastSelectedObject = null;
							continue;
						}
						isSelectingOnDrag = true;
						minCollisionDist = Vector3.Distance(base.PenVisuals.ExtrusionPoint.position, MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT) + 2f;
						base.ObjectContext.AddToSelection(creationObject);
						lastHitPoint = MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT;
						lastSelectedObject = creationObject;
					}
				}
				else
				{
					base.ObjectContext.RemoveAllFromSelection();
					lastSelectedObject = null;
				}
			}
			else if (base.Input.HairTriggerButtonPressed && !lastClickWasMenuClick)
			{
				if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT <= 0)
				{
					return;
				}
				for (int j = 0; j < MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT; j++)
				{
					CreationObject creationObject2 = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[j];
					if (isSelectingOnDrag != base.ObjectContext.IsSelected(creationObject2) && Vector3.Distance(base.PenVisuals.ExtrusionPoint.position, MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT) < minCollisionDist)
					{
						if (isSelectingOnDrag)
						{
							base.ObjectContext.AddToSelection(creationObject2);
							lastHitPoint = MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT;
							lastSelectedObject = creationObject2;
						}
						else
						{
							base.ObjectContext.RemoveFromSelection(creationObject2);
							lastSelectedObject = null;
						}
					}
				}
			}
			else if (base.Input.HairTriggerButtonUp && !lastClickWasMenuClick)
			{
				UpdateAvailableContextActions();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			base.ObjectContext.RemoveAllFromSelection();
		}

		private void UpdateAvailableContextActions()
		{
			base.MakerPen.QuickActionMenu.CloseMenu();
			base.MakerPen.QuickActionMenu.ClearAllButtons();
			if (lastSelectedObject != null && base.MakerPen.SelectInventionOperation.CanSelectInvention)
			{
				base.MakerPen.QuickActionMenu.AddButton("Select entire invention", QuickActionButton.PositionDefaults.Right, base.MakerPen.SelectInventionOperation.TrySelectRestOfInvention);
				base.MakerPen.QuickActionMenu.ShowMenuHint(lastHitPoint);
			}
		}
	}
	[Serializable]
	public class MakerPenVRCreateInventionInstance : MakerPenVRTool
	{
		private bool moveInstanceOnReceive;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousSubStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			if (base.Input.HairTriggerButtonDown)
			{
				Invention invention = base.MakerPen.SelectedInvention;
				NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CanAffordInventionInstance(invention.InventionId, invention.CurrentVersionNumber).Then(delegate(bool canAfford)
				{
					if (canAfford)
					{
						CalculateSpawnPosition(invention).Then(delegate(Vector3 spawnLocation)
						{
							Quaternion rotation = base.MakerPen.ActionPointerRotation;
							if (base.MakerPen.Snapping.IsActive)
							{
								rotation = base.MakerPen.Snapping.SnapToNearestRotationIncrement(rotation);
							}
							moveInstanceOnReceive = true;
							NetworkedSingletonMonoBehaviour<CreationManager>.Instance.RequestSpawnInventionInstance(invention, spawnLocation, rotation, 1f).Then(delegate(CreationManager.SpawnTemplateResult result)
							{
								OnSpawnInstanceResultReceived(result);
							}).Error(delegate
							{
								SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Cannot spawn from Invention", 1.5f);
							});
						}).Error(delegate
						{
							SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Cannot spawn from Invention", "Error calculating spawn position", 1.5f);
						});
					}
					else
					{
						base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_InsufficientResources, "Cannot spawn from Invention", null);
					}
				});
			}
			else if (base.Input.HairTriggerButtonUp)
			{
				moveInstanceOnReceive = false;
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			moveInstanceOnReceive = false;
			base.OnExitState(nextStateId, nextSubStateId);
		}

		private void OnSpawnInstanceResultReceived(CreationManager.SpawnTemplateResult data)
		{
			if (data.result != CreationResult.Success || data.spawnedTools == null)
			{
				return;
			}
			base.ObjectContext.RemoveAllFromSelection();
			foreach (Tool spawnedTool in data.spawnedTools)
			{
				base.ObjectContext.AddToSelection(spawnedTool.CreationObject);
			}
			CreateObjectsUndoEntry createObjectsUndoEntry = new CreateObjectsUndoEntry("create", "invention", base.ObjectContext.CurrentSelection, base.ObjectContext);
			if (moveInstanceOnReceive)
			{
				moveInstanceOnReceive = false;
				base.Controller.TranslateTool.PushAsActiveTool(createObjectsUndoEntry);
			}
			else
			{
				base.MakerPen.UndoStack.Add(createObjectsUndoEntry);
			}
		}

		private IPromise<Vector3> CalculateSpawnPosition(Invention invention)
		{
			Vector3 positionOffset = Vector3.zero;
			Promise<Vector3> spawnPositionPromise = new Promise<Vector3>();
			NetworkedSingletonMonoBehaviour<CreationManager>.Instance.GetInventionExtents(invention).Then(delegate(Vector3 extents)
			{
				if (extents.sqrMagnitude > Mathf.Epsilon)
				{
					float num = Mathf.Max(extents.x, extents.z);
					positionOffset = base.PenVisuals.ExtrusionPoint.forward * num;
				}
				Vector3 vector = GetDesiredCreationPosition(positionOffset);
				if (base.MakerPen.Snapping.IsActive)
				{
					vector = base.MakerPen.Snapping.SnapToCorner(vector);
				}
				spawnPositionPromise.Complete(vector);
			}).Error(delegate
			{
				spawnPositionPromise.Error("Error calculating invention spawn position");
			});
			return spawnPositionPromise;
		}
	}
	[Serializable]
	public class MakerPenVRCreateShape : MakerPenVRTool
	{
		[SerializeField]
		private MakerPenShapeCreationLogic shapeCreator = new MakerPenShapeCreationLogic();

		private bool checkForRelease;

		public void SetAsActiveToolAndStartDrawing()
		{
			base.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateShape, MakerPen.TargetMode.Shape);
			checkForRelease = false;
		}

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			checkForRelease = true;
			base.OnEnterState(previousStateId, previousStateId);
			shapeCreator.Initialize(base.MakerPen, base.ObjectContext, base.ShapeContext, base.Input);
			if (!base.ShapeContext.HasSelectedShapeContainer)
			{
				base.ObjectContext.RemoveAllFromSelection();
				base.ShapeContext.CreateAndSelectShapeContainer(SpawnableToolType.SHAPE_CONTAINER);
			}
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			Vector3 desiredCreationPosition = GetDesiredCreationPosition();
			base.MakerPen.Snapping.UpdateStickyCenterPoint(desiredCreationPosition);
			if (!shapeCreator.IsExtruding && shapeCreator.ShouldStartCreation(checkForRelease))
			{
				checkForRelease = true;
				if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit || base.ShapeContext.IsOverCostLimit)
				{
					base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_InsufficientResources, "Creation failed", null);
					if (base.ShapeContext.IsEmpty)
					{
						base.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateShape, MakerPen.TargetMode.Object);
					}
				}
				else
				{
					base.ShapeContext.CheckNotifyResourceLimits();
					Vector3 position = ((!base.MakerPen.Snapping.IsActive) ? desiredCreationPosition : base.MakerPen.Snapping.StickyPos);
					shapeCreator.StartCreatingShape(base.MakerPen.CurrentShapeType, base.MakerPen.SelectedColor, position);
				}
			}
			else
			{
				shapeCreator.UpdateCreatingShape();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			shapeCreator.FinalizeShape();
		}
	}
	[Serializable]
	public class MakerPenShapeCreationLogic : VRShapeCreationLogic
	{
		[NonSerialized]
		public MakerPen makerPen;

		public void Initialize(MakerPen pen, CreationContext context, ShapeCreationContext shapeContext, VRInputHandler input)
		{
			makerPen = pen;
			base.Initialize(context, shapeContext, input);
		}

		protected override Vector3 CreationPosition()
		{
			if (makerPen.Snapping.IsActive)
			{
				return makerPen.Snapping.StickyPos;
			}
			return makerPen.ActionPointerPosition;
		}

		protected override Vector3 SnapPosition(Vector3 pos)
		{
			if (makerPen.Snapping.IsActive)
			{
				return makerPen.Snapping.SnapToCorner(pos);
			}
			return pos;
		}

		protected override float GetMinSize()
		{
			if (makerPen.Snapping.IsActive)
			{
				return makerPen.Snapping.GridSize;
			}
			return base.GetMinSize();
		}

		protected override Quaternion CreationRotation()
		{
			Quaternion quaternion = makerPen.ActionPointerRotation;
			if (makerPen.Snapping.IsActive)
			{
				quaternion = makerPen.Snapping.SnapToNearestRotationIncrement(quaternion);
			}
			return quaternion;
		}

		protected override Transform AudioTransform()
		{
			return makerPen.PenVisuals.ExtrusionPoint;
		}

		protected override bool UseRadiusModifier()
		{
			return makerPen.LockCurveRadiusActive;
		}

		protected override float RadiusModifier()
		{
			return makerPen.CurveRadiusModifier;
		}

		protected override bool IsConstrainedMode()
		{
			return makerPen.CurrentConstraintMode == MakerPen.ConstraintMode.Constrained;
		}

		protected override void HandleError(CreationResult result, string errorMessage, PhotonPlayer culprit)
		{
			makerPen.RaiseInvalidActionPerformed(result, errorMessage, culprit);
			activeShapeType = ShapeType.Invalid;
			if (result == CreationResult.Failure_InsufficientResources && shapeContext.IsEmpty)
			{
				makerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateShape, MakerPen.TargetMode.Object);
			}
		}

		protected override void OnShapeFinalized()
		{
			base.OnShapeFinalized();
			foreach (Guid item in shapeContext.CurrentSelection)
			{
				makerPen.UndoStack.Add(new DrawShapeUndoEntry(shapeContext.SelectedShapeContainer, item, context));
			}
		}
	}
	[Serializable]
	public class MakerPenVRCreateShape_Object : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousSubStateId);
			base.PenVisuals.LaserPointerEnabled = false;
		}

		public override void OnUpdateState()
		{
