			base.MakerPen.Snapping.UpdateStickyCenterPoint(GetDesiredCreationPosition());
			if (base.Input.HairTriggerButtonDown)
			{
				if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance.IsOverCostLimit)
				{
					base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_InsufficientResources, "Creation failed", null);
