					base.Controller.CreateShapeTool.SetAsActiveToolAndStartDrawing();
				}
			}
		}
	}
	[Serializable]
	public class MakerPenVRCreateTrigger : MakerPenVRTool
	{
		[SerializeField]
		private RecRoomAudioClip loopingExtrusionAudio;

		private ShapeType activeShapeType = ShapeType.Invalid;

		private SFXAudioSource extrusionLoopAudioSource;

		private float lastMeshShapeSizeSynchronizeTime;

		private Vector3 lastMeshShapeCreationPosition = Vector3.zero;

		private bool wasTriggerPressedOnEnter;

		private const float MESH_SHAPE_SYNCHRONIZE_SIZE_MAX_TIME_INTERVAL = 0.1f;

		private const float MESH_SHAPE_MIN_SIZE = 0.01f;

		private bool IsExtruding => activeShapeType != ShapeType.Invalid;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			base.ObjectContext.RemoveAllFromSelection();
			base.ShapeContext.CreateAndSelectShapeContainer(SpawnableToolType.TRIGGER_VOLUME);
			wasTriggerPressedOnEnter = base.Input.HairTriggerButtonPressed;
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			if (base.Input.HairTriggerButtonDown || wasTriggerPressedOnEnter)
			{
				wasTriggerPressedOnEnter = false;
				Vector3 desiredCreationPosition = GetDesiredCreationPosition();
				StartLoopingExtrusionAudio();
				activeShapeType = ShapeType.TriggerVolumeBox;
				lastMeshShapeCreationPosition = desiredCreationPosition;
				ShapeCreationContext.ShapeCreationResult shapeCreationResult = base.ShapeContext.TryCreateAndSelectMeshShapeInSelectedShapeContainer(activeShapeType, ShapeColor.COLOR_0, desiredCreationPosition, Quaternion.identity, Vector3.one * 0.01f);
				if (shapeCreationResult.result == CreationResult.Success)
				{
					UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges: true);
				}
				else
				{
					base.MakerPen.RaiseInvalidActionPerformed(shapeCreationResult.result, "Creating trigger volume failed", null);
				}
			}
			else if (base.Input.HairTriggerButtonUp)
			{
				FinalizeShape();
			}
			else if (base.Input.HairTriggerButtonPressed)
			{
				bool broadcastChanges = UnityEngine.Time.unscaledTime - lastMeshShapeSizeSynchronizeTime >= 0.1f;
				UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges);
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			FinalizeShape();
		}

		private void FinalizeShape()
		{
			if (IsExtruding)
			{
				UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges: true);
				base.MakerPen.UndoStack.Add(new CreateObjectsUndoEntry("create", base.ObjectContext.CurrentSelection, base.ObjectContext));
			}
			base.ShapeContext.RemoveAllFromSelection();
			activeShapeType = ShapeType.Invalid;
			StopLoopingExtrusionAudio();
			base.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.CreateTrigger, MakerPen.TargetMode.Object);
		}

		private void StartLoopingExtrusionAudio()
		{
			if (extrusionLoopAudioSource == null)
			{
				extrusionLoopAudioSource = AudioManager.StartLooping3DSFX(loopingExtrusionAudio, base.PenVisuals.ExtrusionPoint);
			}
		}

		private void StopLoopingExtrusionAudio()
		{
			if (extrusionLoopAudioSource != null)
			{
				AudioManager.StopLoopingSFX(extrusionLoopAudioSource);
				extrusionLoopAudioSource = null;
			}
		}

		private void UpdateSelectedMeshShapeSizeAndPosition(bool broadcastChanges)
		{
			Vector3 desiredCreationPosition = GetDesiredCreationPosition();
			Vector3 vector = desiredCreationPosition - lastMeshShapeCreationPosition;
			Vector3 vector2 = new Vector3(Mathf.Sign(vector.x), Mathf.Sign(vector.y), Mathf.Sign(vector.z));
			Vector3 aspectRatio = new Vector3(Mathf.Max(0.01f, Mathf.Abs(vector.x)), Mathf.Max(0.01f, Mathf.Abs(vector.y)), Mathf.Max(0.01f, Mathf.Abs(vector.z)));
			Vector3 vector3 = new Vector3(vector2.x * aspectRatio.x, vector2.y * aspectRatio.y, vector2.z * aspectRatio.z);
			base.ShapeContext.UpdateSelectedMeshShapeAspectRatio(aspectRatio, broadcastChanges);
			Vector3 vector4 = new Vector3((!(vector3.x < 0f)) ? 0f : vector3.x, (!(vector3.y < 0f)) ? 0f : vector3.y, (!(vector3.z < 0f)) ? 0f : vector3.z);
			Vector3 vector5 = lastMeshShapeCreationPosition + vector4;
			base.ShapeContext.TryGetSelectedMeshShapePosition(out var position);
			Vector3 linearDisplacement = vector5 - position;
			base.ShapeContext.TranslateSelection(linearDisplacement);
			if (broadcastChanges)
			{
				lastMeshShapeSizeSynchronizeTime = UnityEngine.Time.unscaledTime;
			}
		}
	}
