	[Serializable]
	public class MakerPenVRDelete : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(!base.Input.HairTriggerButtonPressed, OutlineEffectRenderer.OutlineType.Warning);
			if (!base.Input.HairTriggerButtonDown)
			{
				return;
			}
			if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
			{
				if (AreRaycastObjectHitsAllInSelection())
				{
					DeleteSelectedObjects();
					return;
				}
				base.ObjectContext.RemoveAllFromSelection();
				if (base.ObjectContext.AddToSelection(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_OBJECTS_RESULTS))
				{
					DeleteSelectedObjects();
				}
			}
			else
			{
				base.ObjectContext.RemoveAllFromSelection();
			}
		}

		private void DeleteSelectedObjects()
		{
			CreationObject[] cachedSelection = base.ObjectContext.CurrentSelection.ToArray();
			base.ObjectContext.SerializeSelection().Then(delegate(SpawnableTemplateData data)
			{
				DeleteObjectsUndoEntry entry = new DeleteObjectsUndoEntry(cachedSelection, data, base.ObjectContext);
				base.MakerPen.UndoStack.Add(entry);
			}).Finally(delegate
			{
				base.ObjectContext.SetSelection(cachedSelection.Length, cachedSelection);
				base.ObjectContext.DeleteSelection();
				base.ObjectContext.RemoveAllFromSelection();
			});
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
		}
	}
