	[Serializable]
	public class MakerPenVREditShape : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousSubStateId);
			base.ObjectContext.RemoveAllFromSelection();
			base.ObjectContext.ShapeCreationContext.RemoveAllFromSelection();
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(shouldRenderHover: true);
			if (!base.Input.HairTriggerButtonDown || MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT != 1)
			{
				return;
			}
			ShapeContainer componentForCollider = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[0].GetComponentForCollider<ShapeContainer>(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COLLIDER);
			if (componentForCollider != null && componentForCollider.CanBeEditedAfterCreation)
			{
				if (MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[0].IsFrozen)
				{
					base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_Generic, "Cannot edit frozen object", null);
				}
				else if (base.ShapeContext.TrySelectShapeContainer(componentForCollider))
				{
					base.MakerPen.AuthoritySelectMode(MakerPen.ToolMode.Move, MakerPen.TargetMode.Shape);
				}
				else
				{
					base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_Generic, "Object cannot be edited right now", null);
				}
			}
			else
			{
				base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_Generic, "Cannot edit this type of object", null);
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
		}
	}
	[Serializable]
	public class MakerPenVRFreeze : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(!base.Input.HairTriggerButtonPressed);
			if (!base.Input.HairTriggerButtonDown)
			{
				return;
			}
			if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
			{
				if (!AreRaycastObjectHitsAllInSelection())
				{
					base.ObjectContext.RemoveAllFromSelection();
					base.ObjectContext.AddToSelection(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_OBJECTS_RESULTS);
				}
				bool flag = base.ObjectContext.HasAnyUnfrozenObject();
				UndoEntry undoEntry = null;
				if (flag)
				{
					undoEntry = new FreezeObjectsUndoEntry(base.ObjectContext.CurrentSelection, base.ObjectContext);
				}
				if (base.ObjectContext.SetSelectionFrozen(flag))
				{
					if (undoEntry == null)
					{
						undoEntry = new UnfreezeObjectsUndoEntry(base.ObjectContext.CurrentSelection, base.ObjectContext);
					}
					base.MakerPen.UndoStack.Add(undoEntry);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.Format("Object{0} {1}", (base.ObjectContext.SelectionCount <= 1) ? string.Empty : "s", (!flag) ? "unfrozen" : "frozen"), 3f);
					base.ObjectContext.RemoveAllFromSelection();
				}
			}
			else
			{
				base.ObjectContext.RemoveAllFromSelection();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
		}
	}
	[Serializable]
	public class MakerPenVRManipulate_Shape : MakerPenVRTool
	{
		private bool hasSelectedHandle;

		private ShapeManipulationHandleInfo handleInfo;

		private Vector3 initialOffset;

		private float lastSynchronizeTime;

		private const float MANIPULATION_SYNCHRONIZE_TIME_INTERVAL = 0.1f;

		private ShapeManipulationManager shapeManipulationManager = new ShapeManipulationManager();

		private UndoEntry pendingUndoEntry;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			hasSelectedHandle = false;
			if (base.ShapeContext.SelectionCount > 1)
			{
				base.ShapeContext.RemoveAllFromSelection();
			}
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			shapeManipulationManager.UpdateHandles(hasSelectedHandle ? null : base.ShapeContext);
			UpdateShapePicking(!hasSelectedHandle);
			bool flag = base.ShapeContext.SelectionCount == 1 && MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0 && base.ShapeContext.IsSelected(MakerPenVRTool.RAYCAST_SHAPES_RESULTS[0]);
			ShapeManipulationHandle shapeManipulationHandle = null;
			if (!hasSelectedHandle)
			{
				if (flag)
				{
					shapeManipulationHandle = shapeManipulationManager.GetClosest(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_POINT);
				}
				else
				{
					shapeManipulationHandle = shapeManipulationManager.RayCast(base.PenVisuals.ExtrusionPoint.position, base.PenVisuals.ExtrusionPoint.forward);
					if ((bool)shapeManipulationHandle)
					{
						float num = Vector3.Dot(shapeManipulationHandle.transform.position - base.PenVisuals.ExtrusionPoint.position, base.PenVisuals.ExtrusionPoint.forward);
						base.PenVisuals.LaserPointerTarget = base.PenVisuals.ExtrusionPoint.position + base.PenVisuals.ExtrusionPoint.forward * num;
					}
				}
			}
			else
			{
				shapeManipulationHandle = shapeManipulationManager.AddHandle(handleInfo, base.ShapeContext.TryGetSelectedMeshShapeTransform(), base.ShapeContext);
			}
			if ((bool)shapeManipulationHandle)
			{
				shapeManipulationHandle.Highlight();
			}
			if (base.Input.HairTriggerButtonDown)
			{
				hasSelectedHandle = shapeManipulationHandle != null;
				if (!hasSelectedHandle && !flag)
				{
					if (!base.MakerPen.ToolModeLocked)
					{
						base.ShapeContext.RemoveAllFromSelection();
						if (MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0)
						{
							base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_RESULTS[0]);
						}
					}
				}
				else
				{
					if (!hasSelectedHandle)
					{
						return;
					}
					if (shapeManipulationHandle.info.TryGetWorldPos(base.ShapeContext, out var worldPos))
					{
						initialOffset = base.PenVisuals.ExtrusionPoint.InverseTransformPoint(worldPos);
						lastSynchronizeTime = UnityEngine.Time.unscaledTime;
						handleInfo = shapeManipulationHandle.info;
						base.PenVisuals.LaserPointerEnabled = false;
						SelectionRenderer.Enabled = false;
						if (base.MakerPen.Snapping.IsActive && !base.MakerPen.ToolModeLocked)
						{
							base.Controller.TranslationSnappingVisualization.Enable(base.ShapeContext, base.MakerPen.Snapping.GridSize);
						}
						pendingUndoEntry = new ManipulateShapesUndoEntry(base.ShapeContext.SelectedShapeContainer, base.ShapeContext.CurrentSelection, base.ObjectContext);
					}
					else
					{
						hasSelectedHandle = false;
					}
				}
			}
			else if (base.Input.HairTriggerButtonPressed)
			{
				UpdateMovement();
			}
			else if (base.Input.HairTriggerButtonUp)
			{
				FinishMovement();
			}
		}

		private void UpdateMovement()
		{
			if (hasSelectedHandle)
			{
				Vector3 newPos = base.PenVisuals.ExtrusionPoint.TransformPoint(initialOffset);
				bool flag = UnityEngine.Time.unscaledTime - lastSynchronizeTime >= 0.1f;
				if (flag)
				{
					lastSynchronizeTime = UnityEngine.Time.unscaledTime;
				}
				handleInfo.Move(newPos, base.MakerPen.Snapping, base.ShapeContext, flag);
			}
		}

		private void FinishMovement()
		{
			if (hasSelectedHandle)
			{
				handleInfo.FinalizeManipulation(base.ShapeContext);
			}
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(base.ObjectContext);
				base.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			hasSelectedHandle = false;
			base.PenVisuals.LaserPointerEnabled = true;
			base.PenVisuals.LaserPointerTarget = null;
			SelectionRenderer.Enabled = !base.MakerPen.ToolModeLocked;
			if (!base.MakerPen.ToolModeLocked)
			{
				base.Controller.TranslationSnappingVisualization.Disable();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			FinishMovement();
			shapeManipulationManager.ClearHandles();
			base.OnExitState(nextStateId, nextSubStateId);
		}
	}
