	[Serializable]
	public class MakerPenVRRepaint_Shape : MakerPenVRTool
	{
		private RecolorShapesContinuousUndoEntry undoEntry;

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateShapePicking(!base.Input.HairTriggerButtonPressed);
			SelectionRenderer.Enabled = !base.Input.HairTriggerButtonPressed && base.ShapeContext.SelectionCount > 1;
			if (base.Input.HairTriggerButtonDown)
			{
				if (MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0)
				{
					bool flag = AreRaycastShapeHitsAllInSelection();
					if (!flag)
					{
						base.ShapeContext.RemoveAllFromSelection();
						base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_SHAPES_RESULTS);
					}
					TryRecolorSelection();
					if (!flag)
					{
						base.ShapeContext.RemoveAllFromSelection();
					}
				}
				else
				{
					base.ShapeContext.RemoveAllFromSelection();
				}
			}
			else if (base.Input.HairTriggerButtonPressed)
			{
				if (base.ShapeContext.SelectionCount <= 1 && MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0 && !AreRaycastShapeHitsAllInSelection())
				{
					base.ShapeContext.RemoveAllFromSelection();
					base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_SHAPES_RESULTS);
					TryRecolorSelection();
				}
			}
			else if (base.Input.HairTriggerButtonUp)
			{
				FinishRecoloring();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			SelectionRenderer.Enabled = true;
			FinishRecoloring();
			base.OnExitState(nextStateId, nextSubStateId);
		}

		private bool TryRecolorSelection()
		{
			ShapeColor color = base.MakerPen.SelectedColor;
			ShapeDataCollection shapeDataCollection = base.ShapeContext.SerializeSelectedShapes();
			if (shapeDataCollection.Shapes.Any((ShapeData s) => s.ShapeColor != (int)color))
			{
				if (undoEntry == null)
				{
					undoEntry = new RecolorShapesContinuousUndoEntry(base.ShapeContext.SelectedShapeContainer, base.ObjectContext);
				}
				undoEntry.AddOrUpdateShapeData(shapeDataCollection, color);
				base.ShapeContext.RecolorSelectedShapes(color);
				return true;
			}
			return false;
		}

		private void FinishRecoloring()
		{
			if (undoEntry != null)
			{
				undoEntry.Finalize(base.ObjectContext);
				base.MakerPen.UndoStack.Add(undoEntry);
				undoEntry = null;
			}
		}
	}
	[Serializable]
	public class MakerPenVRRotate<T> : MakerPenVRTool
	{
		private enum RotationMode
		{
			NONE,
			PITCH,
			YAW,
			FREE
		}

		private const float MIN_HAND_ROTATION = 3f;

		private const float MIN_HAND_MOVEMENT = 5f;

		private static readonly Vector3 handRotationScale = new Vector3(2f, 2f, 2f);

		private static readonly Vector2 handMovementScale = new Vector2(2.5f, 4f);

		private Vector3 centerPivotPoint;

		private Vector3 pitchAxis;

		private Quaternion prevRotationToHandPosition;

		private Quaternion startHandRotation;

		private Quaternion handToSelectionRotation;

		private Quaternion prevSelectionRotation;

		private Quaternion targetSelectionRotation;

		private Vector2 movementAccumulation;

		protected bool clearSelectionOnRelease;

		protected UndoEntry pendingUndoEntry;

		private RotationMode currentRotationMode;

		protected virtual ISelectionContext<T> SelectionContext { get; }

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			movementAccumulation = Vector2.zero;
			currentRotationMode = RotationMode.NONE;
		}

		private Vector3 SnapToClosestAxis(Vector3 direction, Quaternion rotation)
		{
			Vector3 vector = rotation * Vector3.right;
			Vector3 vector2 = rotation * Vector3.up;
			Vector3 vector3 = rotation * Vector3.forward;
			Vector3 vector4 = default(Vector3);
			vector4.x = Vector3.Dot(pitchAxis, vector);
			vector4.y = Vector3.Dot(pitchAxis, vector2);
			vector4.z = Vector3.Dot(pitchAxis, vector3);
			if (Mathf.Abs(vector4.x) > Mathf.Abs(vector4.y))
			{
				if (Mathf.Abs(vector4.x) > Mathf.Abs(vector4.z))
				{
					return vector * Mathf.Sign(vector4.x);
				}
			}
			else if (Mathf.Abs(vector4.y) > Mathf.Abs(vector4.z))
			{
				return vector2 * Mathf.Sign(vector4.y);
			}
			return vector3 * Mathf.Sign(vector4.z);
		}

		protected void InitializeRotation(Quaternion baseRotation)
		{
			SelectionRenderer.Enabled = false;
			centerPivotPoint = SelectionContext.SelectionBounds.center;
			pitchAxis = Vector3.Scale(base.MakerPen.transform.right, new Vector3(-1f, 0f, -1f)).normalized;
			pitchAxis = SnapToClosestAxis(pitchAxis, baseRotation);
			prevRotationToHandPosition = GetRotationToHandPosition();
			startHandRotation = base.MakerPen.transform.rotation;
			handToSelectionRotation = Quaternion.Inverse(startHandRotation) * baseRotation;
			base.PenVisuals.LaserPointerEnabled = false;
			targetSelectionRotation = baseRotation;
			prevSelectionRotation = targetSelectionRotation;
		}

		protected void RotationDone()
		{
			base.PenVisuals.LaserPointerEnabled = true;
			if (clearSelectionOnRelease)
			{
				SelectionContext.RemoveAllFromSelection();
			}
			SelectionRenderer.Enabled = true;
			movementAccumulation = Vector2.zero;
			currentRotationMode = RotationMode.NONE;
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(base.ObjectContext);
				base.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			RotationDone();
		}

		private Quaternion GetRotationToHandPosition()
		{
			Vector3 vector = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position - Vector3.up * 0.3f;
			return Quaternion.LookRotation(base.MakerPen.transform.position - vector, base.MakerPen.transform.up);
		}

		protected void UpdateRotation()
		{
			Vector3 zero = Vector3.zero;
			Quaternion rotation = base.MakerPen.transform.rotation;
			Vector3 eulerAngles = (Quaternion.Inverse(startHandRotation) * rotation).eulerAngles;
			zero.x = Mathf.DeltaAngle(0f, eulerAngles.x);
			zero.y = Mathf.DeltaAngle(0f, eulerAngles.y);
			zero.z = Mathf.DeltaAngle(0f, eulerAngles.z);
			Quaternion rotationToHandPosition = GetRotationToHandPosition();
			Vector3 eulerAngles2 = prevRotationToHandPosition.InverseTransformRotation(rotationToHandPosition).eulerAngles;
			prevRotationToHandPosition = rotationToHandPosition;
			movementAccumulation.x += Mathf.DeltaAngle(0f, eulerAngles2.x);
			movementAccumulation.y += Mathf.DeltaAngle(0f, eulerAngles2.y);
			switch (currentRotationMode)
			{
			case RotationMode.NONE:
			{
				float magnitude = movementAccumulation.magnitude;
				float magnitude2 = zero.magnitude;
				if (magnitude2 * 0.5f > magnitude)
				{
					if (magnitude2 > 3f)
					{
						currentRotationMode = RotationMode.FREE;
					}
				}
				else if (magnitude > 5f)
				{
					if (Mathf.Abs(movementAccumulation.y) > Mathf.Abs(movementAccumulation.x))
					{
						currentRotationMode = RotationMode.YAW;
						movementAccumulation.y = 0f;
					}
					else
					{
						currentRotationMode = RotationMode.PITCH;
						movementAccumulation.x = 0f;
					}
				}
				break;
			}
			case RotationMode.PITCH:
			{
				float x = movementAccumulation.x;
				Vector2 vector = handMovementScale;
				Quaternion angularDisplacement2 = Quaternion.AngleAxis(x * vector.x, pitchAxis);
				SnapDisplacement(ref angularDisplacement2);
				SelectionContext.RotateSelection(angularDisplacement2, centerPivotPoint);
				movementAccumulation.x = 0f;
				break;
			}
			case RotationMode.YAW:
			{
				float num = 0f - movementAccumulation.y;
				Vector2 vector2 = handMovementScale;
				Quaternion angularDisplacement3 = Quaternion.AngleAxis(num * vector2.y, Vector3.up);
				SnapDisplacement(ref angularDisplacement3);
				SelectionContext.RotateSelection(angularDisplacement3, centerPivotPoint);
				movementAccumulation.y = 0f;
				break;
			}
			case RotationMode.FREE:
			{
				Quaternion quaternion = Quaternion.Euler(Vector3.Scale(zero, handRotationScale));
				Quaternion quaternion2 = startHandRotation * quaternion * handToSelectionRotation;
				Quaternion angularDisplacement;
				if (base.MakerPen.Snapping.IsActive)
				{
					Quaternion quaternion3 = base.MakerPen.Snapping.SnapToNearestRotationIncrement(quaternion2);
					angularDisplacement = quaternion3 * Quaternion.Inverse(prevSelectionRotation);
					prevSelectionRotation = quaternion3;
				}
				else
				{
					angularDisplacement = quaternion2 * Quaternion.Inverse(prevSelectionRotation);
					prevSelectionRotation = quaternion2;
				}
				SelectionContext.RotateSelection(angularDisplacement, centerPivotPoint);
				break;
			}
			}
		}

		private void SnapDisplacement(ref Quaternion angularDisplacement)
		{
			if (base.MakerPen.Snapping.IsActive)
			{
				targetSelectionRotation = angularDisplacement * targetSelectionRotation;
				Quaternion quaternion = base.MakerPen.Snapping.SnapToNearestRotationIncrement(targetSelectionRotation);
				angularDisplacement = quaternion * Quaternion.Inverse(prevSelectionRotation);
				prevSelectionRotation = quaternion;
			}
		}
	}
