	[Serializable]
	public class MakerPenVRScale<T> : MakerPenVRTool
	{
		protected UndoEntry pendingUndoEntry;

		private float scaleToExtentsRatio = 1f;

		private Vector3 startSelectionPosition = Vector3.zero;

		private Vector3 scaleDir;

		private float startScale;

		private Plane scalePlane;

		protected bool clearSelectionOnRelease;

		private bool scalingInProgress;

		private const float CENTER_AIM_ANGLE_THRESHOLD = 4f;

		private const float CENTER_AIM_MOVE_DAMPENER = 0.15f;

		private const int MAX_SCALE_STEPS = 4;

		private static readonly float MIN_SNAP_SCALE = Mathf.Pow(0.5f, 4f);

		private static readonly float MAX_SNAP_SCALE = Mathf.Pow(2f, 4f);

		protected virtual ISelectionContext<T> SelectionContext { get; }

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			scalingInProgress = false;
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			ScalingDone();
		}

		protected void StartScaling(Vector3 hitPoint)
		{
			base.PenVisuals.LaserPointerEnabled = false;
			SelectionRenderer.Enabled = false;
			Transform transform = base.PenVisuals.ExtrusionPoint.transform;
			startSelectionPosition = SelectionContext.SelectionBounds.center;
			scalePlane = new Plane(transform.forward, startSelectionPosition);
			float num = Vector3.Angle(startSelectionPosition - transform.position, transform.forward);
			if (num < 4f || num > 90f)
			{
				float num2 = Vector3.Distance(startSelectionPosition, transform.position) * 0.15f;
				startSelectionPosition = hitPoint - (transform.right * num2 + transform.up * num2);
			}
			scaleDir = hitPoint - startSelectionPosition;
			scaleDir -= transform.forward * Vector3.Dot(transform.forward, scaleDir);
			scaleDir.Normalize();
			startScale = SelectionContext.SelectionScale;
			scaleToExtentsRatio = startScale / GetScaleValueFromInput();
			scalingInProgress = true;
		}

		private float GetScaleValueFromInput()
		{
			Ray ray = new Ray(base.PenVisuals.ExtrusionPoint.transform.position, base.PenVisuals.ExtrusionPoint.transform.forward);
			float enter = 0f;
			scalePlane.Raycast(ray, out enter);
			Vector3 point = ray.GetPoint(enter);
			return Mathf.Max(Vector3.Dot(scaleDir, point - startSelectionPosition), 0.001f);
		}

		protected void UpdateScaling()
		{
			if (scalingInProgress)
			{
				float scaleValueFromInput = GetScaleValueFromInput();
				float scale = scaleValueFromInput * scaleToExtentsRatio;
				scale = SnapScale(scale);
				SelectionContext.ScaleSelection(scale - SelectionContext.SelectionScale, SelectionContext.SelectionBounds.center);
				if (base.MakerPen.Snapping.IsActive)
				{
					Vector3 vector = base.MakerPen.Snapping.SnapToNearestTranslationIncrement(SelectionContext.SelectionBounds.center, SelectionContext.SelectionBounds);
					Vector3 linearDisplacement = vector - SelectionContext.SelectionBounds.center;
					SelectionContext.TranslateSelection(linearDisplacement);
				}
			}
		}

		private float SnapScale(float scale)
		{
			if (base.MakerPen.Snapping.IsActive)
			{
				float num = scale / startScale;
				float num2 = 1f;
				if (num > 1f)
				{
					while (Mathf.Abs(num2 - num) > Mathf.Abs(num2 * 2f - num) && num2 < MAX_SNAP_SCALE)
					{
						num2 *= 2f;
					}
				}
				else
				{
					while (Mathf.Abs(num2 - num) > Mathf.Abs(num2 * 0.5f - num) && num2 > MIN_SNAP_SCALE)
					{
						num2 *= 0.5f;
					}
				}
				scale = num2 * startScale;
			}
			return scale;
		}

		protected void ScalingDone()
		{
			base.PenVisuals.LaserPointerEnabled = true;
			SelectionRenderer.Enabled = true;
			if (pendingUndoEntry != null)
			{
				pendingUndoEntry.Finalize(base.ObjectContext);
				base.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			if (clearSelectionOnRelease)
			{
				SelectionContext.RemoveAllFromSelection();
			}
			scalingInProgress = false;
		}
	}
	[Serializable]
