	[Serializable]
	public class MakerPenVRSelect : MakerPenVRTool
	{
		private bool isSelectingOnDrag;

		private float minCollisionDist;

		private const float DRAG_SELECT_DISTANCE_THRESHOLD = 2f;

		private CreationObject lastSelectedObject;

		private Vector3 lastHitPoint = Vector3.zero;

		private bool lastClickWasMenuClick;

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			RaycastHit hitInfo;
			bool flag = base.MakerPen.QuickActionMenu.UpdateHover(new Ray(base.PenVisuals.ExtrusionPoint.position, base.PenVisuals.ExtrusionPoint.forward), out hitInfo, base.PenVisuals.LaserMaxDistance);
			if (flag)
			{
				base.PenVisuals.LaserPointerTarget = hitInfo.point;
				MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT = 0;
			}
			else
			{
				UpdateObjectPicking(shouldRenderHover: true);
			}
			if (base.Input.HairTriggerButtonDown)
			{
				if (flag)
				{
					base.MakerPen.QuickActionMenu.TryClick();
					lastClickWasMenuClick = true;
					return;
				}
				lastClickWasMenuClick = false;
				base.MakerPen.QuickActionMenu.CloseMenu();
				minCollisionDist = float.MaxValue;
				isSelectingOnDrag = false;
				if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
				{
					bool flag2 = false;
					for (int i = 0; i < MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT; i++)
					{
						if (MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[i].IsFrozen)
						{
							flag2 = true;
							break;
						}
					}
					if (flag2)
					{
						base.MakerPen.RaiseInvalidActionPerformed(CreationResult.Failure_ToolFrozen, "Cannot select frozen object", null);
						return;
					}
					for (int j = 0; j < MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT; j++)
					{
						CreationObject creationObject = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[j];
						if (base.ObjectContext.IsSelected(creationObject))
						{
							base.ObjectContext.RemoveFromSelection(creationObject);
							lastSelectedObject = null;
							continue;
						}
						isSelectingOnDrag = true;
						minCollisionDist = Vector3.Distance(base.PenVisuals.ExtrusionPoint.position, MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT) + 2f;
						base.ObjectContext.AddToSelection(creationObject);
						lastHitPoint = MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT;
						lastSelectedObject = creationObject;
					}
				}
				else
				{
					base.ObjectContext.RemoveAllFromSelection();
					lastSelectedObject = null;
				}
			}
			else if (base.Input.HairTriggerButtonPressed && !lastClickWasMenuClick)
			{
				if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT <= 0)
				{
					return;
				}
				for (int k = 0; k < MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT; k++)
				{
					CreationObject creationObject2 = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[k];
					if (isSelectingOnDrag != base.ObjectContext.IsSelected(creationObject2) && !creationObject2.IsFrozen && Vector3.Distance(base.PenVisuals.ExtrusionPoint.position, MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT) < minCollisionDist)
					{
						if (isSelectingOnDrag)
						{
							base.ObjectContext.AddToSelection(creationObject2);
							lastHitPoint = MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT;
							lastSelectedObject = creationObject2;
						}
						else
						{
							base.ObjectContext.RemoveFromSelection(creationObject2);
							lastSelectedObject = null;
						}
					}
				}
			}
			else if (base.Input.HairTriggerButtonUp && !lastClickWasMenuClick)
			{
				UpdateAvailableContextActions();
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			base.MakerPen.QuickActionMenu.CloseMenu();
		}

		private void UpdateAvailableContextActions()
		{
			base.MakerPen.QuickActionMenu.CloseMenu();
			base.MakerPen.QuickActionMenu.ClearAllButtons();
			bool flag = false;
			if (lastSelectedObject != null)
			{
				if (base.MakerPen.SelectInventionOperation.CanSelectInvention)
				{
					base.MakerPen.QuickActionMenu.AddButton("Select entire invention", QuickActionButton.PositionDefaults.Right, base.MakerPen.SelectInventionOperation.TrySelectRestOfInvention);
					flag = true;
				}
				if (base.MakerPen.MergeOperation.CanMergeSelection)
				{
					base.MakerPen.QuickActionMenu.AddButton("Merge Shapes", QuickActionButton.PositionDefaults.Top, base.MakerPen.MergeOperation.TryMergeSelection);
					flag = true;
				}
				if (flag)
				{
					base.MakerPen.QuickActionMenu.ShowMenuHint(lastHitPoint);
				}
			}
		}
	}
