				{
					return;
				}
				for (int j = 0; j < MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT; j++)
				{
					if (isSelectingOnDrag != base.ShapeContext.IsSelected(MakerPenVRTool.RAYCAST_SHAPES_RESULTS[j]) && Vector3.Distance(base.PenVisuals.ExtrusionPoint.position, MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_POINT) < minCollisionDist)
					{
						if (isSelectingOnDrag)
						{
							base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_RESULTS[j]);
							lastSelectedShape = MakerPenVRTool.RAYCAST_SHAPES_RESULTS[j];
							lastHitPoint = MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_POINT;
						}
						else
						{
							base.ShapeContext.RemoveFromSelection(MakerPenVRTool.RAYCAST_SHAPES_RESULTS[j]);
							lastSelectedShape = Guid.Empty;
						}
					}
				}
			}
