	[Serializable]
	public class MakerPenVRSettings : MakerPenVRTool
	{
		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousSubStateId);
			if (base.ObjectContext.SelectionCount == 1)
			{
				TryEditSettings(base.ObjectContext.CurrentSelection.First());
			}
		}

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(!base.Input.HairTriggerButtonPressed);
			if (!base.Input.HairTriggerButtonDown)
			{
				return;
			}
			if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
			{
				CreationObject creationObject = MakerPenVRTool.RAYCAST_OBJECTS_RESULTS[0];
				base.ObjectContext.RemoveAllFromSelection();
				if (base.ObjectContext.AddToSelection(creationObject) && !TryEditSettings(creationObject))
				{
					base.ObjectContext.RemoveAllFromSelection();
				}
			}
			else
			{
				base.ObjectContext.RemoveAllFromSelection();
				TryCloseEditSettings();
