		{
			if (creationObject == null || !base.ObjectContext.IsSelected(creationObject))
			{
				return false;
			}
			base.MakerPen.RequestInteractableSettingsUI(creationObject);
			return true;
		}

		private void TryCloseEditSettings()
		{
			base.MakerPen.CloseInteractableSettingsUI();
		}
	}
