	[Serializable]
	public abstract class MakerPenVRTranslate<T> : MakerPenVRTool
	{
		private const float MAGNET_DURATION_MIN = 0.03f;

		private const float MAGNET_DURATION_MAX = 0.15f;

		private const float SNAPPING_STICKYNESS = 0.4f;

		private const float SNAPPING_SMOOTHNESS = 0.3f;

		private const float SNAPPING_ROT_SMOOTHNESS = 0.4f;

		private const float SPRINGY_ARMS_FACTOR = 1f;

		protected bool clearSelectionOnRelease;

		protected Vector3 penRelativePivotPoint;

		protected Vector3 pivotPoint;

		protected Quaternion prevGridSnappedRot;

		protected Vector3 prevGridSnappedPos;

		protected UndoEntry pendingUndoEntry;

		private float startHandDistance;

		private Vector3 selectionToHitPointOffset;

		private Quaternion penToSelectionRotationOffset;

		private RotatedBoundsCollision rotatedBoundsCollision = new RotatedBoundsCollision();

		protected virtual ISelectionContext<T> SelectionContext { get; }

		protected virtual int MaxAllowedBounds => 1;

		protected virtual bool AllowCollisionSnapping()
		{
			return true;
		}

		public override void OnEnterState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterState(previousStateId, previousStateId);
			if (SelectionContext.HasSelection && base.Input.HairTriggerButtonPressed && !base.MakerPen.PenToolStackIsEmpty)
			{
				InitializeMovement(SelectionContext.SelectionBounds.center);
				clearSelectionOnRelease = SelectionContext.SelectionCount == 1;
			}
			else
			{
				base.PenVisuals.LaserPointerEnabled = true;
				base.PenVisuals.LaserPointerTarget = null;
				clearSelectionOnRelease = false;
			}
		}

		public override void OnExitState(ushort nextStateId, ushort nextSubStateId)
		{
			base.OnExitState(nextStateId, nextSubStateId);
			SelectionRenderer.Enabled = true;
			if (clearSelectionOnRelease)
			{
				SelectionContext.RemoveAllFromSelection();
			}
			base.Controller.TranslationSnappingVisualization.Disable();
		}

		public void PushAsActiveTool(UndoEntry pendingUndoEntry)
		{
			this.pendingUndoEntry = pendingUndoEntry;
			PushAsActiveTool();
		}

		private float GetHandDistance()
		{
			Vector3 b = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.position - Vector3.up * 0.3f;
			return Vector3.Distance(base.MakerPen.transform.position, b);
		}

		protected void InitializeMovement(Vector3 hitPos)
		{
			pivotPoint = hitPos;
			penRelativePivotPoint = base.PenVisuals.ExtrusionPoint.transform.InverseTransformPoint(pivotPoint);
			selectionToHitPointOffset = Quaternion.Inverse(SelectionContext.SelectionTransform.rotation) * (hitPos - SelectionContext.SelectionTransform.position);
			penToSelectionRotationOffset = Quaternion.Inverse(base.PenVisuals.ExtrusionPoint.transform.rotation) * SelectionContext.SelectionTransform.rotation;
			base.PenVisuals.LaserPointerEnabled = false;
			SelectionRenderer.Enabled = false;
			if (base.MakerPen.Snapping.IsActive)
			{
				base.Controller.TranslationSnappingVisualization.Enable(SelectionContext, base.MakerPen.Snapping.GridSize);
			}
			startHandDistance = GetHandDistance();
			prevGridSnappedPos = SelectionContext.SelectionBounds.center;
			prevGridSnappedRot = SelectionContext.SelectionTransform.rotation;
			rotatedBoundsCollision.ClearBounds();
			if (base.MakerPen.AlignToObjects && AllowCollisionSnapping())
			{
				rotatedBoundsCollision.SetupBounds(SelectionContext, MaxAllowedBounds, pivotPoint, base.PenVisuals.ExtrusionPoint.transform.rotation, base.MakerPen.AlignToEdges);
			}
		}

		protected void MovementDone()
		{
			base.PenVisuals.LaserPointerEnabled = true;
			SelectionRenderer.Enabled = true;
			base.Controller.TranslationSnappingVisualization.Disable();
			if (pendingUndoEntry != null)
			{
				if (!pendingUndoEntry.IsFinalized)
				{
					pendingUndoEntry.Finalize(base.ObjectContext);
				}
				base.MakerPen.UndoStack.Add(pendingUndoEntry);
				pendingUndoEntry = null;
			}
			if (clearSelectionOnRelease)
			{
				SelectionContext.RemoveAllFromSelection();
				clearSelectionOnRelease = false;
			}
			if (!base.MakerPen.PenToolStackIsEmpty)
			{
				base.MakerPen.AuthorityPopPenTool();
			}
		}

		protected void UpdateMovement()
		{
			if (!SelectionContext.HasSelection)
			{
				return;
			}
			bool isActive = base.MakerPen.Snapping.IsActive;
			float num = GetHandDistance() - startHandDistance;
			num = 1f + num * 1f;
			Vector3 newPivotPoint = base.PenVisuals.ExtrusionPoint.TransformPoint(penRelativePivotPoint * num);
			bool freezeRotationOnMove = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.FreezeRotationOnMove;
			Quaternion newPenRotation = ((!freezeRotationOnMove) ? base.PenVisuals.ExtrusionPoint.transform.rotation : (SelectionContext.SelectionTransform.rotation * Quaternion.Inverse(penToSelectionRotationOffset)));
			rotatedBoundsCollision.UpdateCollisionSnapping(ref newPivotPoint, ref newPenRotation, !isActive, !freezeRotationOnMove, IgnoreCollision);
			if (!freezeRotationOnMove)
			{
				Quaternion quaternion = newPenRotation * penToSelectionRotationOffset;
				if (isActive)
				{
					quaternion = Quaternion.Slerp(quaternion, prevGridSnappedRot, 0.4f);
					prevGridSnappedRot = base.MakerPen.Snapping.SnapToNearestRotationIncrement(quaternion);
					quaternion = Quaternion.Slerp(prevGridSnappedRot, SelectionContext.SelectionTransform.rotation, 0.4f);
				}
				Quaternion angularDisplacement = quaternion * Quaternion.Inverse(SelectionContext.SelectionTransform.rotation);
				SelectionContext.RotateSelection(angularDisplacement, SelectionContext.SelectionBounds.center);
			}
			Vector3 vector = newPivotPoint - SelectionContext.SelectionTransform.rotation * selectionToHitPointOffset;
			vector += SelectionContext.SelectionBounds.center - SelectionContext.SelectionTransform.position;
			if (isActive)
			{
				Vector3 position = Vector3.Lerp(vector, prevGridSnappedPos, 0.4f);
				prevGridSnappedPos = base.MakerPen.Snapping.SnapToNearestTranslationIncrement(position, SelectionContext.SelectionBounds);
				vector = Vector3.Lerp(prevGridSnappedPos, SelectionContext.SelectionBounds.center, 0.3f);
			}
			Vector3 linearDisplacement = vector - SelectionContext.SelectionBounds.center;
			SelectionContext.TranslateSelection(linearDisplacement);
		}

		protected bool IgnoreCollision(Collider collider)
		{
			Tool colliderTool = collider.GetColliderTool();
			if (colliderTool == base.MakerPen.Tool)
			{
				return true;
			}
			foreach (ToolCollider selectionToolCollider in SelectionContext.GetSelectionToolColliders())
			{
				if (selectionToolCollider.Tool == colliderTool)
				{
					return true;
				}
			}
			return false;
		}
	}
	[Serializable]
	public class MakerPenVRTranslate_Object : MakerPenVRTranslate<CreationObject>
	{
		protected override ISelectionContext<CreationObject> SelectionContext => base.ObjectContext;

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateObjectPicking(!base.Input.HairTriggerButtonPressed);
			bool isActive = base.MakerPen.Snapping.IsActive;
			if (base.Input.HairTriggerButtonUp)
			{
				if (clearSelectionOnRelease)
				{
					if (isActive)
					{
						SelectionContext.RemoveAllFromSelection();
					}
					else
					{
						MakerPenSelectionCache.Instance.DeselectAndApplyVelocityOnAll(base.ObjectContext);
					}
					clearSelectionOnRelease = false;
				}
				MovementDone();
			}
			else if (base.Input.HairTriggerButtonDown)
			{
				if (MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT > 0)
				{
					bool flag = AreRaycastObjectHitsAllInSelection();
					if (!flag)
					{
						base.ObjectContext.RemoveAllFromSelection();
						base.ObjectContext.AddToSelection(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_OBJECTS_RESULTS);
					}
					if (base.ObjectContext.HasSelection)
					{
						base.ObjectContext.DisableDynamicCollisionForSelectionUntilDeSelected();
						clearSelectionOnRelease = !flag;
						pendingUndoEntry = new TransformObjectsUndoEntry("move", base.ObjectContext.CurrentSelection, base.ObjectContext, transformRotations: true);
						InitializeMovement(MakerPenVRTool.RAYCAST_OBJECTS_LAST_HIT_POINT);
					}
				}
				else
				{
					SelectionContext.RemoveAllFromSelection();
				}
			}
			else if (base.Input.HairTriggerButtonPressed)
			{
				if (!isActive)
				{
					MakerPenSelectionCache.Instance.CacheSelection(base.ObjectContext);
				}
				UpdateMovement();
				if (!isActive)
				{
					MakerPenSelectionCache.Instance.CalculateVelocityOnAll();
				}
			}
		}

		protected override bool AllowCollisionSnapping()
		{
			return base.ObjectContext.SelectionCount == 1;
		}
	}
	[Serializable]
	public class MakerPenVRTranslate_Shape : MakerPenVRTranslate<Guid>
	{
		protected override ISelectionContext<Guid> SelectionContext => base.ShapeContext;

		protected override int MaxAllowedBounds => 10;

		public override void OnUpdateState()
		{
			base.OnUpdateState();
			UpdateShapePicking(!base.Input.HairTriggerButtonPressed);
			if (base.Input.HairTriggerButtonUp)
			{
				MovementDone();
			}
			else if (base.Input.HairTriggerButtonDown)
			{
				if (MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT > 0)
				{
					bool flag = AreRaycastShapeHitsAllInSelection();
					if (!flag)
					{
						base.ShapeContext.RemoveAllFromSelection();
						base.ShapeContext.AddToSelection(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_COUNT, MakerPenVRTool.RAYCAST_SHAPES_RESULTS);
					}
					clearSelectionOnRelease = !flag;
					pendingUndoEntry = new TransformShapesUndoEntry("move", base.ShapeContext.SelectedShapeContainer, base.ShapeContext.CurrentSelection, base.ObjectContext, transformRotations: true);
					InitializeMovement(MakerPenVRTool.RAYCAST_SHAPES_LAST_HIT_POINT);
				}
				else
				{
					SelectionContext.RemoveAllFromSelection();
				}
			}
			else if (base.Input.HairTriggerButtonPressed)
			{
				UpdateMovement();
			}
		}
	}
