namespace RecRoom
{
	public class ShapeManipulationHandle : UnityEngine.MonoBehaviour
	{
		[HideInInspector]
		public ShapeManipulationHandleInfo info;

		private const float MIN_HANDLE_SIZE = 0.02f;

		private const float MAX_HANDLE_SIZE = 0.15f;

		[SerializeField]
		private Material highlightMaterial;

		[SerializeField]
		private Material highlightZOffMaterial;

		[SerializeField]
		private Renderer meshRenderer;

		private Material[] defaultMaterials;

		private Material[] highlightMaterials;

		private void Awake()
		{
			defaultMaterials = meshRenderer.sharedMaterials;
			highlightMaterials = new Material[2] { highlightZOffMaterial, highlightMaterial };
		}

		public void UpdateInfo(ShapeManipulationHandleInfo newInfo, Transform shapeTransform)
		{
			meshRenderer.sharedMaterials = defaultMaterials;
			info = newInfo;
			Vector3 forward = shapeTransform.rotation * info.axis;
			Vector3 vector = shapeTransform.TransformPoint(info.offset);
			Vector3 vector2 = vector - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
			float magnitude = vector2.magnitude;
			vector2 /= magnitude;
			float num = Mathf.Clamp(info.size * 0.04f + magnitude * 0.02f, 0.02f, 0.15f);
			base.transform.localScale = Vector3.one * num;
			base.transform.position = vector;
			base.transform.rotation = Quaternion.LookRotation(forward);
		}

		public void Highlight()
		{
			meshRenderer.sharedMaterials = highlightMaterials;
			base.transform.localScale = base.transform.localScale * 1.5f;
		}
	}
	public struct ShapeManipulationHandleInfo
	{
		private const float MIN_SHAPE_AXIS_SIZE = 0.001f;

		public Vector3 offset;

		public Vector3 axis;

		public int index;

		public float size;

		public bool TryGetWorldPos(ShapeCreationContext context, out Vector3 worldPos)
		{
			Transform transform = context.TryGetSelectedMeshShapeTransform();
			if ((bool)transform)
			{
				worldPos = transform.TransformPoint(offset);
				return true;
			}
			worldPos = Vector3.zero;
			return false;
		}

		public void FinalizeManipulation(ShapeCreationContext context)
		{
			Vector3 zero = Vector3.zero;
			if (context.TryGetSelectedMeshShapeAspectRatio(out zero))
			{
				context.UpdateSelectedMeshShapeAspectRatio(zero, broadcastChangesOverNetwork: true);
			}
		}

		public void Move(Vector3 newPos, MakerPenSnapping snapping, ShapeCreationContext context, bool broadCastChangesOverNetwork)
		{
			MoveMeshShape(newPos, snapping, context, broadCastChangesOverNetwork);
		}

		private void MoveMeshShape(Vector3 newPos, MakerPenSnapping snapping, ShapeCreationContext context, bool broadCastChangesOverNetwork)
		{
			Transform transform = context.TryGetSelectedMeshShapeTransform();
			if (!transform)
			{
				return;
			}
			bool flag = index > 2;
			Vector3 vector = transform.rotation * axis;
			Vector3 rhs = ((!flag) ? vector : (-vector));
			Vector3 vector2 = transform.TransformPoint(offset);
			float num = Vector3.Dot(newPos - vector2, vector);
			Vector3 lhs = transform.TransformVector(Vector3.one);
			float num2 = Vector3.Dot(lhs, rhs);
			float a = num2 + num;
			a = Mathf.Max(a, 0.001f);
			if (snapping.IsActive)
			{
				float val = (a + num2) * 0.5f;
				a = snapping.SnapToSize(val, avoidZero: true);
			}
			Vector3 vector3 = vector * (a - num2);
			Vector3 zero = Vector3.zero;
			if (context.TryGetSelectedMeshShapeAspectRatio(out zero))
			{
				Vector3 vector4 = transform.InverseTransformDirection(vector3);
				vector4 /= transform.GetLossyUniformScale() / zero.x;
				if (flag)
				{
					vector4 = -vector4;
				}
				context.UpdateSelectedMeshShapeAspectRatio(zero + vector4, broadCastChangesOverNetwork);
				if (flag)
				{
					context.TranslateSelection(vector3);
				}
			}
		}
	}
	public class ShapeManipulationManager
	{
		private List<ShapeManipulationHandle> handles = new List<ShapeManipulationHandle>();

		private int numActiveHandles;

		private ShapeManipulationHandle CreateHandle(Transform root)
		{
			return UnityEngine.Object.Instantiate(ShapeSettings.ShapeManipulationHandlePrefab, root);
		}

		private ShapeManipulationHandle GetNewHandle(Transform root)
		{
			if (numActiveHandles >= handles.Count)
			{
				handles.Add(CreateHandle(root));
			}
			ShapeManipulationHandle shapeManipulationHandle = handles[numActiveHandles++];
			if (shapeManipulationHandle == null)
			{
				shapeManipulationHandle = CreateHandle(root);
			}
			shapeManipulationHandle.gameObject.SetActive(value: true);
			return shapeManipulationHandle;
		}

		private void InitHandleList()
		{
			while (numActiveHandles > 0)
			{
				handles[--numActiveHandles].gameObject.SetActive(value: false);
			}
		}

		public void ClearHandles()
		{
			foreach (ShapeManipulationHandle handle in handles)
			{
				SafeDestroy.GameObject(handle.gameObject);
			}
			handles.Clear();
			numActiveHandles = 0;
		}

		public void UpdateHandles(ShapeCreationContext context)
		{
			InitHandleList();
			if (context != null)
			{
				Transform transform = context.TryGetSelectedMeshShapeTransform();
				if (transform != null)
				{
					float magnitude = (Quaternion.Inverse(transform.rotation) * transform.TransformVector(Vector3.one)).magnitude;
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(1f, 0.5f, 0.5f),
						axis = Vector3.right,
						index = 0,
						size = magnitude
					}, transform, context);
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(0.5f, 1f, 0.5f),
						axis = Vector3.up,
						index = 1,
						size = magnitude
					}, transform, context);
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(0.5f, 0.5f, 1f),
						axis = Vector3.forward,
						index = 2,
						size = magnitude
					}, transform, context);
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(0.5f, 0f, 0.5f),
						axis = -Vector3.up,
						index = 3,
						size = magnitude
					}, transform, context);
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(0f, 0.5f, 0.5f),
						axis = -Vector3.right,
						index = 4,
						size = magnitude
					}, transform, context);
					AddHandle(new ShapeManipulationHandleInfo
					{
						offset = new Vector3(0.5f, 0.5f, 0f),
						axis = -Vector3.forward,
						index = 5,
						size = magnitude
					}, transform, context);
				}
			}
		}

		public ShapeManipulationHandle AddHandle(ShapeManipulationHandleInfo info, Transform transform, ShapeCreationContext context)
		{
			ShapeManipulationHandle newHandle = GetNewHandle(context.transform);
			newHandle.UpdateInfo(info, transform);
			return newHandle;
		}

		public ShapeManipulationHandle RayCast(Vector3 startPos, Vector3 dir)
		{
			ShapeManipulationHandle result = null;
			float num = float.MaxValue;
			for (int i = 0; i < numActiveHandles; i++)
			{
				Vector3 position = handles[i].transform.position;
				float num2 = Vector3.Dot(dir, position - startPos);
				if (num2 > 0f)
				{
					Vector3 vector = startPos + dir * num2;
					float sqrMagnitude = (position - vector).sqrMagnitude;
					float sqrMagnitude2 = handles[i].transform.localScale.sqrMagnitude;
					if (sqrMagnitude < num && sqrMagnitude < sqrMagnitude2)
					{
						result = handles[i];
						num = sqrMagnitude;
					}
				}
			}
			return result;
		}

		public ShapeManipulationHandle GetClosest(Vector3 worldPos)
		{
			ShapeManipulationHandle result = null;
			float num = float.MaxValue;
			for (int i = 0; i < numActiveHandles; i++)
			{
				float sqrMagnitude = (handles[i].transform.position - worldPos).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					result = handles[i];
					num = sqrMagnitude;
				}
			}
			return result;
		}
	}
