	[Serializable]
	public abstract class VRShapeCreationLogic
	{
		private class TriggerHistory
		{
			public struct Entry
			{
				public float value;

				public float time;
			}

			private const float MAX_HISTORY_DURATION = 0.1f;

			private const float MIN_INPUT_VALUE = 0.04f;

			private Queue<Entry> history = new Queue<Entry>();

			private Entry oldestEntry;

			private float latestValue;

			private bool hasBeenReleased;

			public void Initialize(VRInputHandler input)
			{
				hasBeenReleased = false;
				history.Clear();
				oldestEntry = new Entry
				{
					value = input.HairTriggerInputValueNormalized,
					time = UnityEngine.Time.unscaledTime
				};
			}

			public void Update(VRInputHandler input)
			{
				float hairTriggerInputValueNormalized = input.HairTriggerInputValueNormalized;
				float unscaledTime = UnityEngine.Time.unscaledTime;
				latestValue = hairTriggerInputValueNormalized;
				if (unscaledTime - oldestEntry.time < 0.1f)
				{
					oldestEntry.value = hairTriggerInputValueNormalized;
					return;
				}
				Entry item = new Entry
				{
					value = hairTriggerInputValueNormalized,
					time = unscaledTime
				};
				history.Enqueue(item);
				while (unscaledTime - history.Peek().time > 0.1f)
				{
					oldestEntry = history.Dequeue();
				}
			}

			public void Clear()
			{
				hasBeenReleased = false;
			}

			public bool CanStartCreation(VRInputHandler input, bool checkForRelease)
			{
				bool flag = input.HairTriggerInputValueNormalized >= 0.04f;
				if (checkForRelease && !hasBeenReleased)
				{
					hasBeenReleased = !flag;
					return false;
				}
				return flag;
			}

			public bool WasReleased()
			{
				return latestValue < 0.04f;
			}

			public float GetHistoricalValue()
			{
				return oldestEntry.value;
			}
		}

