			return false;
		}

		protected virtual float RadiusModifier()
		{
			return 1f;
		}

		protected virtual bool IsConstrainedMode()
		{
			return false;
		}

		protected virtual void HandleError(CreationResult result, string errorMessage, PhotonPlayer culprit)
		{
		}

		public virtual void Initialize(CreationContext context, ShapeCreationContext shapeContext, VRInputHandler input)
		{
			this.context = context;
			this.shapeContext = shapeContext;
			this.input = input;
			triggerHistory.Clear();
		}

		public bool ShouldStartCreation(bool checkForRelease = true)
		{
			return triggerHistory.CanStartCreation(input, checkForRelease);
		}

		public void StartCreatingShape(ShapeType type, ShapeColor color, Vector3 position)
		{
			StartLoopingExtrusionAudio();
			triggerHistory.Initialize(input);
			activeShapeType = type;
			if (IsCurveShape(activeShapeType))
			{
				StartCreatingCurveShape(color, position);
				return;
			}
			lastMeshShapeCreationPosition = position;
			ShapeCreationContext.ShapeCreationResult shapeCreationResult = shapeContext.TryCreateAndSelectMeshShapeInSelectedShapeContainer(activeShapeType, color, position, Quaternion.identity, Vector3.one * 0.01f);
			if (shapeCreationResult.result == CreationResult.Success)
			{
				UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges: true);
			}
			else
			{
				HandleError(shapeCreationResult.result, "Creation failed", null);
			}
		}

		public void UpdateCreatingShape()
		{
			if (IsExtruding)
			{
				triggerHistory.Update(input);
				if (triggerHistory.WasReleased())
				{
					FinalizeShape();
					return;
				}
				if (IsCurveShape(activeShapeType))
				{
					UpdateCurrentCurveShape();
					return;
				}
				bool broadcastChanges = UnityEngine.Time.unscaledTime - lastMeshShapeSizeSynchronizeTime >= 0.1f;
				UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges);
			}
		}

		public void FinalizeShape()
		{
			if (IsExtruding)
			{
				if (IsCurveShape(activeShapeType))
				{
					FinishCurrentCurveShape();
				}
				else
				{
					UpdateSelectedMeshShapeSizeAndPosition(broadcastChanges: true);
				}
			}
			OnShapeFinalized();
			shapeContext.RemoveAllFromSelection();
			activeShapeType = ShapeType.Invalid;
			StopLoopingExtrusionAudio();
		}

		protected virtual void OnShapeFinalized()
		{
		}

		protected virtual Vector3 SnapPosition(Vector3 pos)
		{
			return pos;
		}

		protected virtual float GetMinSize()
		{
			return 0.01f;
		}

		private bool IsCurveShape(ShapeType type)
		{
			return type == ShapeType.Ribbon || type == ShapeType.Tube;
		}

		private bool IsMeshShape(ShapeType type)
		{
			return !IsCurveShape(type);
		}

		private float GetRadiusFromInput()
		{
			if (UseRadiusModifier())
			{
				return RadiusModifier() * maxTubeRadius;
			}
			float historicalValue = triggerHistory.GetHistoricalValue();
			AnimationCurve animationCurve = pressureToThicknessCurveVive;
			InputManager.VRInputMode vRMode = SingletonMonoBehaviour<InputManager>.Instance.VRMode;
			if (vRMode == InputManager.VRInputMode.SteamVR_Oculus || vRMode == InputManager.VRInputMode.Oculus)
			{
				animationCurve = pressureToThicknessCurveOculus;
			}
			return animationCurve.Evaluate(historicalValue) * maxTubeRadius;
		}

		private void StartLoopingExtrusionAudio()
		{
			if (extrusionLoopAudioSource == null)
			{
				extrusionLoopAudioSource = AudioManager.StartLooping3DSFX(loopingExtrusionAudio, AudioTransform());
			}
		}

		private void StopLoopingExtrusionAudio()
		{
			if (extrusionLoopAudioSource != null)
			{
				AudioManager.StopLoopingSFX(extrusionLoopAudioSource);
				extrusionLoopAudioSource = null;
			}
		}

		private void StartCreatingCurveShape(ShapeColor color, Vector3 position)
		{
			Quaternion initialRotation = CreationRotation();
			float radiusFromInput = GetRadiusFromInput();
			ShapeCreationContext.ShapeCreationResult shapeCreationResult = shapeContext.TryCreateAndSelectCurveShapeInSelectedShapeContainer(activeShapeType, color, position, initialRotation, radiusFromInput);
			if (shapeCreationResult.result == CreationResult.Success)
			{
				UpdateSelectedCurveShapeControlPoint(mustAddControlPoint: true);
				UpdateSelectedCurveShapeControlPoint(mustAddControlPoint: true);
			}
			else
			{
				HandleError(shapeCreationResult.result, "Creation failed", null);
			}
		}

		private void UpdateCurrentCurveShape()
		{
			if (IsConstrainedMode())
			{
				UpdateConstrainedCurveShapeControlPoint(mustBroadcastChanges: false);
			}
			else
			{
				UpdateSelectedCurveShapeControlPoint(mustAddControlPoint: false);
			}
		}

		private void FinishCurrentCurveShape()
		{
			if (IsConstrainedMode())
			{
				UpdateConstrainedCurveShapeControlPoint(mustBroadcastChanges: true);
			}
			else
			{
				UpdateSelectedCurveShapeControlPoint(mustAddControlPoint: true);
			}
		}

		private void UpdateConstrainedCurveShapeControlPoint(bool mustBroadcastChanges)
		{
			GetCurveShapeControlPointData(out var position, out var rotation, out var radius);
			bool flag = UnityEngine.Time.unscaledTime - lastCurveShapeControlPointAddTime >= 0.1f;
			bool broadcastChangesOverNetwork = mustBroadcastChanges || flag;
			Vector3 controlPointPosition = Vector3.zero;
			if (shapeContext.TryGetSelectedCurveShapeFirstControlPointPosition(out controlPointPosition))
			{
				shapeContext.UpdateSelectedCurveShapeFirstControlPoint(controlPointPosition, rotation * Vector3.back, radius, broadcastChangesOverNetwork);
			}
			shapeContext.UpdateSelectedCurveShapeLatestControlPoint(position, rotation * Vector3.back, radius, broadcastChangesOverNetwork);
		}

		private void UpdateSelectedCurveShapeControlPoint(bool mustAddControlPoint)
		{
			GetCurveShapeControlPointData(out var position, out var rotation, out var radius);
			Vector3 controlPointPosition = Vector3.zero;
			shapeContext.TryGetSelectedCurveShapePreviousControlPointPosition(out controlPointPosition);
			shapeContext.UpdateSelectedCurveShapeLatestControlPoint(position, rotation * Vector3.back, radius, broadcastChangesOverNetwork: false);
			if (mustAddControlPoint || NeedToAddNewControlPoint(controlPointPosition, position))
			{
				lastCurveShapeControlPointAddTime = UnityEngine.Time.unscaledTime;
				CreationResult creationResult = shapeContext.TryAddSelectedCurveShapeControlPoint(position, rotation * Vector3.back, radius);
				if (creationResult != CreationResult.Success)
				{
					HandleError(creationResult, "Creation failed", null);
				}
			}
		}

		private bool NeedToAddNewControlPoint(Vector3 latestControlPointPosition, Vector3 desiredControlPointPosition)
		{
			float sqrMagnitude = (latestControlPointPosition - desiredControlPointPosition).sqrMagnitude;
			if (sqrMagnitude < Mathf.Epsilon)
			{
				return false;
			}
			if (sqrMagnitude >= 0.0001f)
			{
				return true;
			}
			return false;
		}

		private void GetCurveShapeControlPointData(out Vector3 position, out Quaternion rotation, out float radius)
		{
			position = CreationPosition();
			rotation = CreationRotation();
			radius = GetRadiusFromInput();
		}

		private void UpdateSelectedMeshShapeSizeAndPosition(bool broadcastChanges)
		{
			Vector3 lhs = CreationPosition();
			Vector3 vector = Vector3.Min(lhs, lastMeshShapeCreationPosition);
			Vector3 vector2 = Vector3.Max(lhs, lastMeshShapeCreationPosition);
			Vector3 vector3 = Vector3.one * GetMinSize();
			vector = SnapPosition(vector - vector3 * 0.5f);
			vector2 = SnapPosition(vector2 + vector3 * 0.5f);
			Vector3 lhs2 = vector2 - vector;
			if (IsConstrainedMode())
			{
				float num = Mathf.Max(lhs2.x, lhs2.y, lhs2.z);
				lhs2 = Vector3.one * num;
				if (lhs.x > lastMeshShapeCreationPosition.x)
				{
					vector2.x = vector.x + lhs2.x;
				}
				else
				{
					vector.x = vector2.x - lhs2.x;
				}
				if (lhs.y > lastMeshShapeCreationPosition.y)
				{
					vector2.y = vector.y + lhs2.y;
				}
				else
				{
					vector.y = vector2.y - lhs2.y;
				}
				if (lhs.z > lastMeshShapeCreationPosition.z)
				{
					vector2.z = vector.z + lhs2.z;
				}
				else
				{
					vector.z = vector2.z - lhs2.z;
				}
			}
			lhs2 = Vector3.Max(lhs2, vector3);
			shapeContext.UpdateSelectedMeshShapeAspectRatio(lhs2, broadcastChanges);
			shapeContext.TryGetSelectedMeshShapePosition(out var position);
			Vector3 linearDisplacement = Vector3.Lerp(vector, vector2, 0.5f) - lhs2 * 0.5f - position;
			shapeContext.TranslateSelection(linearDisplacement);
			if (broadcastChanges)
			{
				lastMeshShapeSizeSynchronizeTime = UnityEngine.Time.unscaledTime;
			}
		}
	}
}
public class MirrorCameraOutput : UnityEngine.MonoBehaviour
{
	public bool MirrorImage = true;

	private static Material MirrorMaterialInstance;

	[SerializeField]
	private Material mirrorMat;

	private void Awake()
	{
