	}
}
namespace RecRoom.Tools
{
	public class MovablePlatform : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[SerializeField]
		private float occupiedCollisionCapsuleHeight = 1.5f;

		[SerializeField]
		private float occupiedCollisionCapsuleRadius = 0.25f;

		private void Awake()
		{
			tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			tool.KinematicOnSleep = true;
			tool.AddCustomPickupCondition(CustomToolPickupCondition);
		}

		private bool CustomToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			Vector3 position = base.transform.position;
			Vector3 end = position + Vector3.up * occupiedCollisionCapsuleHeight;
			return !Physics.CheckCapsule(position, end, occupiedCollisionCapsuleRadius, 1053184);
		}
	}
	public class MoveableProp : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private RigidbodyEx rigidbodyEx;

		[SerializeField]
		private bool useMovementCollision = true;

		[SerializeField]
		private bool hasDetailedColliders;

		[SerializeField]
		[ConditionalField("hasDetailedColliders")]
		private Collider[] detailedColliders;

		[SerializeField]
		[ConditionalField("hasDetailedColliders")]
		private Collider[] defaultColliders;

		private void Awake()
		{
			tool.AlwaysPhysicalPickupOffCenter = true;
			tool.SleepOnStart = true;
			tool.KinematicOnSleep = true;
			tool.IgnorePickupDirection = true;
		}

		private void Start()
		{
			tool.PostPickupEvent += OnToolPostPickup;
			rigidbodyEx.IsKinematicChangedEvent += UpdateKinematicState;
			UpdateKinematicState(rigidbodyEx);
		}

		private void OnToolPostPickup(Tool thisTool)
		{
			SetActiveColliders(useDetailed: false);
		}

		private void OnDestroy()
		{
			if (rigidbodyEx != null)
			{
				rigidbodyEx.IsKinematicChangedEvent -= UpdateKinematicState;
			}
		}

		private void UpdateKinematicState(RigidbodyEx rigidbodyEx)
		{
			bool isKinematic = rigidbodyEx.isKinematic;
			if (isKinematic)
			{
				tool.GravityPickupMode = Tool.GravityPickup.DISABLED;
			}
			else
			{
				tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			}
			bool flag = isKinematic && !tool.IsHeld;
			SetActiveColliders(flag);
			UpdateMovementCollision(flag);
		}

		private void SetActiveColliders(bool useDetailed)
		{
			if (hasDetailedColliders)
			{
				Collider[] array = ((!useDetailed) ? detailedColliders : defaultColliders);
				Collider[] array2 = ((!useDetailed) ? defaultColliders : detailedColliders);
				Collider[] array3 = array;
				foreach (Collider collider in array3)
				{
					collider.enabled = false;
				}
				Collider[] array4 = array2;
				foreach (Collider collider2 in array4)
				{
					collider2.enabled = true;
				}
			}
		}

		private void UpdateMovementCollision(bool isStatic)
		{
			if (!useMovementCollision)
			{
				return;
			}
			string text = ((!isStatic) ? "MovementCollisionAlwaysAllowed" : "Untagged");
			string text2 = ((!isStatic) ? "Untagged" : "MovementCollisionAlwaysAllowed");
			foreach (ToolCollider collider in tool.Colliders)
			{
				foreach (Collider physicsCollider in collider.PhysicsColliders)
				{
					if (!physicsCollider.isTrigger && physicsCollider.gameObject.CompareTag(text))
					{
						physicsCollider.gameObject.tag = text2;
					}
				}
			}
		}
	}
}
public class MoveableSeating : UnityEngine.MonoBehaviour
{
	private const Tool.GravityPickup DEFAULT_GRAVITY_PICKUP = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;

	[Header("Sit Requirements")]
	[SerializeField]
	private bool mustBeRightSideUp = true;

	[Header("Tool side effects")]
	[SerializeField]
	private bool makeToolKinematicWhileSleeping = true;

	[SerializeField]
	private bool disableGravityPickupWhileSleeping = true;

	[Header("Occupied settings")]
	[SerializeField]
	private Transform occupiedCollisionCapsuleStart;

	[SerializeField]
	private float occupiedCollisionCapsuleHeight = 2f;

	[SerializeField]
	private float occupiedCollisionCapsuleRadius = 0.25f;

	private Tool tool;

	private bool toolIsNull = true;

	private TeleportationPortal[] portals;

	private DynamicTeleportRestriction[] teleportRestrictions;

	private bool cachedIsSleeping;

	private void Awake()
	{
		tool = GetComponent<Tool>();
		toolIsNull = tool == null;
		if (!toolIsNull)
		{
			tool.AddCustomPickupCondition(CustomToolPickupCondition);
			tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
			tool.AlwaysPhysicalPickupOffCenter = true;
			tool.IgnorePickupDirection = true;
		}
		portals = GetComponentsInChildren<TeleportationPortal>();
		teleportRestrictions = GetComponentsInChildren<DynamicTeleportRestriction>();
		if ((portals == null || portals.Length == 0) && (teleportRestrictions == null || teleportRestrictions.Length == 0))
		{
			UnityEngine.Debug.LogError(base.name + " is missing teleportation portal or teleport restriction components.");
		}
	}

	private void Update()
	{
		bool flag = CanSit();
		if (!toolIsNull && !tool.IsHeld)
		{
			bool flag2 = flag || tool.RigidbodyEx.IsSleeping();
			if (makeToolKinematicWhileSleeping && cachedIsSleeping != flag2)
			{
				cachedIsSleeping = flag2;
				tool.RigidbodyEx.SetKinematic(this, flag2);
			}
			if (disableGravityPickupWhileSleeping)
			{
				tool.GravityPickupMode = ((!flag2) ? Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION : Tool.GravityPickup.DISABLED);
			}
		}
		if (portals != null)
		{
			for (int i = 0; i < portals.Length; i++)
			{
				portals[i].enabled = flag;
			}
		}
		if (teleportRestrictions != null)
		{
			for (int j = 0; j < teleportRestrictions.Length; j++)
			{
				teleportRestrictions[j].MovementBlocked = !flag;
			}
		}
	}

	private bool CanSit()
	{
		if (!toolIsNull && tool.IsHeld)
		{
			return false;
		}
		if (!toolIsNull && tool.RigidbodyEx.velocity.sqrMagnitude > 0.0001f)
		{
			return false;
		}
		if (mustBeRightSideUp && Vector3.Dot(base.transform.up, Vector3.up) < 0.95f)
		{
			return false;
		}
		return true;
	}

	private bool CustomToolPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
	{
		Vector3 position = occupiedCollisionCapsuleStart.position;
		Vector3 end = position + Vector3.up * occupiedCollisionCapsuleHeight;
		return !CanSit() || !Physics.CheckCapsule(position, end, occupiedCollisionCapsuleRadius, 1053184);
	}

	private void OnDrawGizmosSelected()
	{
		if (occupiedCollisionCapsuleStart != null)
		{
			Gizmos.color = Color.green;
			Vector3 position = occupiedCollisionCapsuleStart.position;
			Vector3 vector = position + Vector3.up * occupiedCollisionCapsuleHeight;
			Gizmos.DrawWireSphere(position, occupiedCollisionCapsuleRadius);
			Gizmos.DrawLine(position, vector);
			Gizmos.DrawWireSphere(vector, occupiedCollisionCapsuleRadius);
		}
	}
}
