			else if (!isTrigger && this.ServerPlayerCollisionEnterEvent != null)
			{
				this.ServerPlayerCollisionEnterEvent(base.gameObject, player, playerBodyPart, collisionPoint);
			}
		}
	}

	private void FireToolCollisionRpc(bool isTrigger, Tool hitTool, Vector3 point)
	{
		if (!(hitTool == lastToolCollision) || !(UnityEngine.Time.time - lastToolCollisionTime <= 0.5f))
		{
			lastToolCollision = hitTool;
			lastToolCollisionTime = UnityEngine.Time.time;
			if (IsOnline && base.hasAuthority)
			{
				base.photonView.RpcMaster(RpcMasterToolCollisionEnterEvent, isTrigger, hitTool, point);
			}
		}
	}

	private void FirePlayerCollisionRpc(bool isTrigger, Player hitPlayer, Player.BodyPart bodyPart, Vector3 point)
	{
		if (!(hitPlayer == lastPlayerCollision) || !(UnityEngine.Time.time - lastPlayerCollisionTime <= 0.5f))
		{
			lastPlayerCollision = hitPlayer;
			lastPlayerCollisionTime = UnityEngine.Time.time;
			if (IsOnline && base.hasAuthority)
			{
				base.photonView.RpcMaster(RpcMasterPlayerCollisionEnterEvent, isTrigger, hitPlayer, bodyPart, point);
			}
		}
	}
}
[RequireComponent(typeof(Tool))]
[RequireComponent(typeof(OutfitRenderSetup))]
public class OutfitTool : Photon.MonoBehaviour
{
	public enum PlayerEquipState
	{
		None = -1,
		Wearing,
		NotWearing,
		Attaching
	}

	[NonSerialized]
	public bool EquipOnCollision = true;

	public Action<PlayerEquipState> EquipStateChanged;

	private PlayerEquipState _equipState = PlayerEquipState.None;

	private bool canCollideWithPlayer = true;

	private float dontCollideWithPlayerStartTime;

	private float dontCollideWithPlayerDuration;

	private Player.BodyPart matchingBodyPart = Player.BodyPart.None;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private OutfitRenderSetup renderSetup;

	private ToolCollider _toolCollider;

	public Player Wearer => (!(Tool != null) || !(Tool.PlayerSpawnedEquipment != null)) ? null : Tool.PlayerSpawnedEquipment.SpawningPlayer;

	public bool IsWearerLocal => Wearer != null && Wearer.isLocal;

	public PlayerEquipState EquipState
	{
		get
		{
			return _equipState;
		}
		set
		{
			if (_equipState == value)
			{
				return;
			}
			_equipState = value;
			PlayerEquipState equipState = _equipState;
			if ((equipState == PlayerEquipState.Attaching || equipState == PlayerEquipState.Wearing) && Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.IsNew)
			{
				Tool.PlayerSpawnedEquipment.IsNew = false;
				OutfitSelection outfitSelection = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.UnlockedOutfitSelections.FindLast((OutfitSelection s) => s.Equals(OutfitSelection));
				if (outfitSelection != null)
				{
					outfitSelection.IsNew = false;
				}
			}
			if (Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.IsMine && (_equipState == PlayerEquipState.Wearing || _equipState == PlayerEquipState.NotWearing))
			{
				bool isWearing = _equipState == PlayerEquipState.Wearing || (matchingBodyPart.IsHand() && Player.LocalPlayer.PlayerOutfit.IsWearing(OutfitSelection));
				Tool.PlayerSpawnedEquipment.IsWearing = isWearing;
			}
			if (EquipStateChanged != null)
			{
				EquipStateChanged(value);
			}
		}
	}

	public bool IsAlreadyBeingWorn => EquipState == PlayerEquipState.Wearing;

	public OutfitSelection OutfitSelection { get; private set; }

	private Renderer GhostRenderer => renderSetup.GhostRenderer;

	public Renderer ItemRenderer => renderSetup.ItemRenderer;

	public ToolCollider ToolCollider
	{
		get
		{
			if (_toolCollider == null)
			{
				_toolCollider = ((!(Tool != null) || Tool.Colliders == null) ? null : Tool.Colliders[0]);
			}
			return _toolCollider;
		}
	}

	public Tool Tool { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		Tool = GetComponent<Tool>();
		if (Tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
		}
		else
		{
			if (Tool.InstantiationParameters != null && Tool.InstantiationParameters.TryGetValue("OutfitSelection", out var value))
			{
				OutfitSelection = OutfitSelection.Parse((string)value);
			}
			Tool.CustomHandSpacePickupTransformModifier = HandSpacePickupTransformModifier;
			Tool.PostPickupEvent += OnPostPickup;
			Tool.PreReleaseEvent += OnPreRelease;
			Tool.PostReleaseEvent += OnPostRelease;
		}
		base.gameObject.name = OutfitSelection.FriendlyName + "_Outfit";
		renderSetup.OutfitSelection = OutfitSelection;
		matchingBodyPart = OutfitManager.GetMatchingBodyPart(OutfitSelection.outfitItem.Type);
	}

	private void Start()
	{
		Tool.HeldCollisionLayer = Layers.DynamicPhysicsIgnoreStaticPhysics;
		if (OutfitSelection.outfitItem.UsesHairColor && Wearer != null)
		{
			bool flag = OutfitSelection.outfitItem.Type == OutfitManager.OutfitType.Mouth;
			ColorVault.ColorToGuid colorToGuid = ((!flag) ? Wearer.PlayerOutfit.HairColor : Wearer.PlayerOutfit.BeardColor);
			if (colorToGuid != null)
			{
				PlayerOutfit_ColorChanged(colorToGuid.color, (!flag) ? AvatarColor.ColorType.Hair : AvatarColor.ColorType.Beard);
			}
			if (IsWearerLocal)
			{
				Player.LocalPlayer.PlayerOutfit.HairColorChanged += PlayerOutfit_ColorChanged;
			}
		}
		if (IsWearerLocal && Player.LocalPlayer.PlayerOutfit.IsWearing(OutfitSelection))
		{
			EquipState = PlayerEquipState.Wearing;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostPickupEvent -= OnPostPickup;
			Tool.PreReleaseEvent -= OnPreRelease;
			Tool.PostReleaseEvent -= OnPostRelease;
		}
		if (Player.LocalPlayerExists && OutfitSelection != null && OutfitSelection.outfitItem.UsesHairColor)
		{
			Player.LocalPlayer.PlayerOutfit.HairColorChanged -= PlayerOutfit_ColorChanged;
		}
	}

	protected void Update()
	{
		if (Player.LocalPlayerExists && Wearer != null && Wearer.isLocal && !canCollideWithPlayer && UnityEngine.Time.time - dontCollideWithPlayerStartTime > dontCollideWithPlayerDuration)
		{
			canCollideWithPlayer = true;
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		if (!collider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics) || !EquipOnCollision || !Tool.IsHeld)
		{
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
		if (canCollideWithPlayer && colliderPlayer != null && colliderPlayer.isLocal && IsWearerLocal)
		{
			bool flag = bodyPart.IsHand();
			PlayerHand playerHand = null;
			if (flag)
			{
				playerHand = ((bodyPart != Player.BodyPart.LeftHand) ? Tool.Owner.RightHand : Tool.Owner.LeftHand);
			}
			if ((!flag || Tool.HolderHand != playerHand) && OutfitManager.IsMatchingBodyPart(bodyPart, OutfitSelection.outfitItem.Type) && Tool.IsHeld)
			{
				SetOutfitToPlayer(colliderPlayer, bodyPart);
			}
		}
	}

	private void PlayerOutfit_ColorChanged(Color color, AvatarColor.ColorType colorType)
	{
		AvatarColor.ColorType colorType2 = ((OutfitSelection.outfitItem.Type != OutfitManager.OutfitType.Mouth) ? AvatarColor.ColorType.Hair : AvatarColor.ColorType.Beard);
		if (colorType2 == colorType)
		{
			Tool.SetRenderMainColor(color);
		}
	}

	private void SetRendererVisible(Renderer renderer, bool visible)
	{
		renderer.gameObject.SetActive(visible);
		renderer.enabled = visible;
	}

	public void DontCollideWithPlayer(float duration)
	{
		dontCollideWithPlayerDuration = duration;
		dontCollideWithPlayerStartTime = UnityEngine.Time.time;
		canCollideWithPlayer = false;
	}

	public Player.BodyPart GetEquipTargetPlayerBodyPart()
	{
		return OutfitManager.GetMatchingBodyPart(OutfitSelection.outfitItem.Type);
	}

	public void ApplyToPlayer(Player player)
	{
		Player.BodyPart equipTargetPlayerBodyPart = GetEquipTargetPlayerBodyPart();
		SetOutfitToPlayer(player, equipTargetPlayerBodyPart);
		switch (equipTargetPlayerBodyPart)
		{
		case Player.BodyPart.LeftHand:
			SetOutfitToPlayer(player, Player.BodyPart.RightHand);
			break;
		case Player.BodyPart.RightHand:
			SetOutfitToPlayer(player, Player.BodyPart.LeftHand);
			break;
		}
	}

	private void SetOutfitToPlayer(Player player, Player.BodyPart bodyPart)
	{
		if (EquipState == PlayerEquipState.Attaching)
		{
			return;
		}
		if (player != null)
		{
			if (EquipState == PlayerEquipState.Wearing && (!bodyPart.IsHand() || player.PlayerOutfit.IsWearing(OutfitSelection, bodyPart)))
			{
				if (Tool.IsHeld)
				{
					Tool.HolderInfo = ToolHolderInfo.NotHeld;
				}
				if (player.PlayerOutfit.RemoveOutfitByHand(OutfitSelection, bodyPart))
				{
					EquipState = PlayerEquipState.NotWearing;
				}
				return;
			}
			player.PlayerOutfit.SetOutfitByHand(OutfitSelection, bodyPart);
			if (bodyPart.IsHand() && Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.GiftBox)
			{
				Player.BodyPart bodyPart2 = ((bodyPart != Player.BodyPart.LeftHand) ? Player.BodyPart.LeftHand : Player.BodyPart.RightHand);
				player.PlayerOutfit.SetOutfitByHand(OutfitSelection, bodyPart2);
			}
			if (Tool.IsHeld)
			{
				EquipState = PlayerEquipState.Attaching;
				Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
			else
			{
				EquipState = PlayerEquipState.Wearing;
			}
		}
		else
		{
			UnityEngine.Debug.LogError(string.Concat("SetOutfitToPlayer has null player. BodyPart : ", bodyPart, " - ", base.gameObject.GetGameObjectHierarchy()));
		}
	}

	private void OnPostPickup(Tool tool)
	{
		Tool.SetUsingGravityRigidBody(usingGravity: false);
		ToolCollider.enabled = true;
		SetRendererVisible(GhostRenderer, visible: false);
		SetRendererVisible(ItemRenderer, visible: true);
		Tool.SuppressAnimateInOut = false;
	}

	private void OnPreRelease(Tool thisTool)
	{
		if (Tool.IsEnabled)
		{
			DontCollideWithPlayer(1f);
		}
	}

	private void OnPostRelease(Tool tool)
	{
		if (Tool.IsEnabled)
		{
			Tool.SetUsingGravityRigidBody(usingGravity: false);
			SetStateForToolRelease(tool.HolderPlayer);
		}
	}

	private bool AttachToPlayer(Player player)
	{
		if (EquipState == PlayerEquipState.Attaching)
		{
			EquipState = PlayerEquipState.Wearing;
			return true;
		}
		if (EquipState == PlayerEquipState.Wearing)
		{
			return true;
		}
		return false;
	}

	private void SetStateForToolRelease(Player player)
	{
		if (!AttachToPlayer(player))
		{
			EquipState = PlayerEquipState.NotWearing;
		}
	}

	private void HandSpacePickupTransformModifier(Transform handTransform, bool isLeftHand, ref Vector3 position, ref Quaternion rotation)
	{
		position = Vector3.zero;
		rotation = handTransform.InverseTransformRotation(base.transform.rotation);
	}

	public static OutfitTool LocalFind(OutfitSelection selection, PlayerSpawnedEquipment.Purpose purpose)
	{
		foreach (PlayerSpawnedEquipment item in PlayerSpawnedEquipment.All)
		{
			if (item != null && item.IsMine && item.Tool != null && item.ToolPurpose == purpose)
			{
				OutfitTool component = item.GetComponent<OutfitTool>();
				if (component != null && component.OutfitSelection == selection)
				{
					return component;
				}
			}
		}
		return null;
	}

	public static List<OutfitTool> LocalFindAll(OutfitSelection selection, PlayerSpawnedEquipment.Purpose purpose)
	{
		List<OutfitTool> list = new List<OutfitTool>();
		foreach (PlayerSpawnedEquipment item in PlayerSpawnedEquipment.All)
		{
			if (item != null && item.IsMine && item.Tool != null && item.ToolPurpose == purpose)
			{
				OutfitTool component = item.GetComponent<OutfitTool>();
				if (component != null && component.OutfitSelection == selection)
				{
					list.Add(component);
				}
			}
		}
		return list;
	}
}
public class OutfitToolCleanup : ToolCleanup
{
}
public class PermanentOwnerToolModifier : UnityEngine.MonoBehaviour
{
	[NonSerialized]
	public PhotonPlayer permanentOwner;

	public Tool Tool { get; private set; }

	private void Awake()
	{
		Tool = GetComponent<Tool>();
		if (Tool != null)
		{
			Tool.AddCustomPickupCondition(ToolPickupCondition);
		}
	}

	private bool ToolPickupCondition(Tool tool, Player player, Vector3 selectionPoint, bool physicalPickup)
