public class PlayerHandWorldCollisionConfig : UnityEngine.MonoBehaviour
{
}
public class PlayerWorldCollisionConfig : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private PlayerCollisionDisplacementVRMovementController.WorldCollisionType playerCollisionType = PlayerCollisionDisplacementVRMovementController.WorldCollisionType.HEAD_AND_BODY;

	public PlayerCollisionDisplacementVRMovementController.WorldCollisionType PlayerCollisionType => playerCollisionType;
