public class Polaroid : Photon.MonoBehaviour, IPersistable
{
	private const int MAX_POLAROIDS_PER_GUEST = 3;

	private static readonly List<Polaroid> allPolaroids = new List<Polaroid>();

	[Header("Image")]
	[SerializeField]
	private RendererMaterialPair pictureRenderer;

	private GameManager gameManager;

	private SynchronizedField<bool> _isGrabbable;

	private SynchronizedField<bool> _isKinematic;

	private SynchronizedField<string> _imageName;

	private SynchronizedField<int> _guestCreatorId;

	private SynchronizedField<long> _localCreatedTime;

	public Tool Tool { get; private set; }

	public bool IsGrabbable
	{
		get
		{
			return _isGrabbable.Get();
		}
		set
		{
			_isGrabbable.Set(value);
		}
	}

	public bool IsKinematic
	{
		get
		{
			return _isKinematic.Get();
		}
		set
		{
			_isKinematic.Set(value);
		}
	}

	private string ImageName
	{
		get
		{
			return _imageName.Get();
		}
		set
		{
			_imageName.Set(value);
		}
	}

	private int GuestCreatorId
	{
		get
		{
			return _guestCreatorId.Get();
		}
		set
		{
			_guestCreatorId.Set(value);
		}
	}

	private long LocalGuestCreatedTime
	{
		get
		{
			return _localCreatedTime.Get();
		}
		set
		{
			_localCreatedTime.Set(value);
		}
	}

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		Tool = GetComponent<Tool>();
		if (Tool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
		}
		Tool.PostResetEvent += OnToolReset;
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		_isKinematic = new SynchronizedField<bool>(this, "PIK", defaultValue: false, SetterPermissionMode.ANYONE, OnIsKinematicChanged);
		_isGrabbable = new SynchronizedField<bool>(this, "PPIG", defaultValue: true, SetterPermissionMode.AUTHORITY, OnIsGrabbledChanged);
		_imageName = new SynchronizedField<string>(this, "PIN", string.Empty, SetterPermissionMode.ANYONE, OnImageNameChanged);
		_guestCreatorId = new SynchronizedField<int>(this, "PCID", -1, SetterPermissionMode.MASTER_OR_AUTHORITY);
		_localCreatedTime = new SynchronizedField<long>(this, "PCCT", 0L, SetterPermissionMode.AUTHORITY);
		OnIsKinematicChanged();
		OnIsGrabbledChanged();
		OnImageNameChanged();
		allPolaroids.Add(this);
	}

	private void Start()
	{
		gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (gameManager != null)
		{
			gameManager.StateChangeEvent += OnGameManagerStateChange;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Tool.PostResetEvent -= OnToolReset;
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		if (gameManager != null)
		{
			gameManager.StateChangeEvent -= OnGameManagerStateChange;
		}
		allPolaroids.Remove(this);
	}

	private void OnIsKinematicChanged()
	{
		if (IsKinematic)
		{
			Tool.RigidbodyEx.AddKinematic(this);
		}
		else
		{
			Tool.RigidbodyEx.RemoveKinematic(this);
		}
	}

	private void OnIsGrabbledChanged()
	{
		Tool.SetPickupEnabled(IsGrabbable, this);
	}

	private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		bool flag = GuestCreatorId != -1;
		if (base.hasAuthority && wasCleanedUp && flag)
		{
			PhotonNetwork.Destroy(base.gameObject);
		}
	}

	private void OnGameManagerStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		if (currentStateId == 2 && previousStateId != 2)
		{
			bool flag = GuestCreatorId != -1;
			if (base.hasAuthority && flag)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}
	}

	public void AuthoritySetImageName(IPromise<string> imageNamePromise)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		imageNamePromise.Then(delegate(string imageName)
		{
			if (this != null)
			{
				ImageName = imageName;
			}
		});
	}

	private void OnImageNameChanged()
	{
		if (string.IsNullOrEmpty(ImageName))
		{
			return;
		}
		Images.GetImage(ImageName).Then(delegate(Texture2D t)
		{
			if (this != null && t != null && t.name == ImageName)
			{
				pictureRenderer.Material.mainTexture = t;
			}
		});
	}

	private void OnPhotonPlayerDisconnected(PhotonPlayer player)
	{
		if ((base.hasAuthority || (base.photonView.owner == player && PhotonNetwork.isMasterClient)) && player.RecNetProfileId == GuestCreatorId && !PlayerRoomRoleManager.IsPlayerAHost(player))
		{
			PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
		}
	}

	public static Polaroid TryMasterSpawnPolaroidForPlayer(Vector3 position, Quaternion rotation, PhotonPlayer player)
	{
		Polaroid polaroid = null;
		if (PhotonNetwork.isMasterClient)
		{
			if (!PlayerRoomRoleManager.Instance.GetPlayerRoleDefinition(player).CanPrintPhotos.Value)
			{
				return null;
			}
			bool flag = !PlayerRoomRoleManager.IsPlayerAHost(player);
			if (flag)
			{
				IEnumerable<Polaroid> source = allPolaroids.Where((Polaroid p) => p.GuestCreatorId == player.RecNetProfileId);
				int num = source.Count();
				if (num >= 3)
				{
					Polaroid polaroid2 = source.OrderBy((Polaroid p) => p.LocalGuestCreatedTime).First();
					PhotonNetwork.GetOwnershipAndDestroy(polaroid2.gameObject);
				}
			}
			Tool tool = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.MasterSpawnTool(SpawnableToolType.POLAROID, position, rotation, 1f);
			if ((bool)tool)
			{
				polaroid = tool.GetComponent<Polaroid>();
				if (polaroid != null)
				{
					if (flag)
					{
						polaroid.GuestCreatorId = (int)player.RecNetProfileId;
						polaroid.LocalGuestCreatedTime = DateTime.Now.Ticks;
					}
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("Polaroid component not found when spawning {0}. Destroying.", tool.gameObject);
					PhotonNetwork.GetOwnershipAndDestroy(tool.gameObject);
				}
			}
		}
		return polaroid;
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData.ImageData == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing Polaroid {0}: data empty.", base.gameObject);
		}
		else
		{
			ImageName = deserializeParams.viewData.ImageData.ImageName;
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.ImageData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing Polaroid {0}: Data already specified.", base.gameObject);
			return;
		}
		NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.PersistTransientImage(ImageName);
		viewData.ImageData = new ImageData
		{
			ImageName = ImageName
		};
		if (transientData.imageNamesToPersist == null)
		{
			transientData.imageNamesToPersist = new List<string>();
		}
		transientData.imageNamesToPersist.Add(ImageName);
		GuestCreatorId = -1;
	}
}
public class PolaroidRigidbodyPickup : RigidbodyPickup
{
	[SerializeField]
	private float castDistance = 0.1f;

	[SerializeField]
	private BoxCollider overlapCollider;

	[SerializeField]
	private AnimationCurve nearSurfaceRotationCurve = AnimationCurve.Linear(0f, 1f, 1f, 0f);

	private RaycastHit raycastHit;

	private RaycastHit tempRaycastHit;

	private bool isBehindSurface;

	private bool hitSomething;

	private Vector3 BoxWorldCenter => base.transform.TransformPoint(overlapCollider.center);

	public override Quaternion TargetRotation
	{
		get
		{
			if (tool.IsHeld && raycastHit.collider != null)
			{
				Quaternion targetRotation = base.TargetRotation;
				Vector3 fromDirection = targetRotation * -Vector3.forward;
				Vector3 normal = raycastHit.normal;
				Quaternion quaternion = Quaternion.FromToRotation(fromDirection, normal);
				float time = 0f;
				if (!isBehindSurface)
				{
					time = Vector3.Distance(BoxWorldCenter, raycastHit.point);
				}
				float t = nearSurfaceRotationCurve.Evaluate(time);
				return Quaternion.Lerp(targetRotation, quaternion * targetRotation, t);
			}
			return base.TargetRotation;
		}
	}

	public override Vector3 TargetPosition
	{
		get
		{
			Vector3 targetPosition = base.TargetPosition;
			IsOriginalPositionBehindSurface(targetPosition);
			if (tool.IsHeld && raycastHit.collider != null && isBehindSurface)
			{
				Vector3 vector = Vector3.Project(raycastHit.point - targetPosition, raycastHit.normal);
				return targetPosition + vector;
			}
			return targetPosition;
		}
	}

	private void IsOriginalPositionBehindSurface(Vector3 position)
	{
		float num = Vector3.Dot(position - raycastHit.point, raycastHit.normal);
		if (num < 0f)
		{
			isBehindSurface = true;
		}
		else
		{
			isBehindSurface = false;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		raycastHit = default(RaycastHit);
	}

	private void FixedUpdate()
	{
		if (!(tool != null) || !tool.IsHeld)
		{
			return;
		}
		Vector3 boxWorldCenter = BoxWorldCenter;
		Vector3 halfExtents = overlapCollider.size.MultiplyComponents(overlapCollider.transform.lossyScale) / 2f;
		hitSomething = Physics.BoxCast(boxWorldCenter, halfExtents, base.transform.forward, out tempRaycastHit, base.transform.rotation, castDistance, 496385536, QueryTriggerInteraction.Ignore);
		if (raycastHit.collider == null && hitSomething)
		{
			raycastHit = tempRaycastHit;
		}
		else
		{
			if (!(raycastHit.collider != tempRaycastHit.collider))
			{
				return;
			}
			bool flag = false;
			Collider[] array = Physics.OverlapBox(boxWorldCenter, halfExtents, base.transform.rotation, 496385536, QueryTriggerInteraction.Ignore);
			Collider[] array2 = array;
			foreach (Collider collider in array2)
			{
				if (raycastHit.collider == collider)
				{
					flag = true;
					break;
				}
			}
			if (!flag)
			{
				raycastHit = default(RaycastHit);
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
	}
}
