public abstract class RecRoomCollider : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float kinematicBounciness = 0.6f;

	[SerializeField]
	private ColliderImpactType impactType;

	[NonSerialized]
	public RigidbodyEx ThisRigidbodyEx;

	private List<Collider> physicsColliders = new List<Collider>();

	public float KinematicBounciness => kinematicBounciness;

	public ColliderImpactType ImpactType => impactType;

	public ReadOnlyCollection<Collider> PhysicsColliders => physicsColliders.AsReadOnly();

	public Bounds Bounds
	{
		get
		{
			Bounds result;
			if (physicsColliders == null || physicsColliders.Count == 0)
			{
				result = default(Bounds);
			}
			else
			{
				result = physicsColliders[0].bounds;
				for (int i = 1; i < physicsColliders.Count; i++)
				{
					result.Encapsulate(physicsColliders[i].bounds);
				}
			}
			return result;
		}
	}

	public bool IsTrigger
	{
		get
		{
			bool result = false;
			if (physicsColliders != null)
			{
				foreach (Collider physicsCollider in physicsColliders)
				{
					if (physicsCollider.isTrigger)
					{
						result = true;
						break;
					}
				}
			}
			return result;
		}
		set
		{
			if (physicsColliders == null)
			{
				return;
			}
			foreach (Collider physicsCollider in physicsColliders)
			{
				physicsCollider.isTrigger = value;
			}
		}
	}

	protected virtual void Awake()
	{
		physicsColliders.AddRange(GetComponents<Collider>());
	}

	protected virtual void OnEnable()
	{
		if (physicsColliders == null || physicsColliders.Count <= 0)
		{
			return;
		}
		foreach (Collider physicsCollider in physicsColliders)
		{
			physicsCollider.enabled = true;
		}
	}

	protected virtual void OnDisable()
	{
		if (physicsColliders == null || physicsColliders.Count <= 0)
		{
			return;
		}
		foreach (Collider physicsCollider in physicsColliders)
		{
			physicsCollider.enabled = false;
		}
	}

	public void IgnoreCollision(RecRoomCollider[] otherRecRoomColliders, bool ignore)
	{
		foreach (RecRoomCollider recRoomCollider in otherRecRoomColliders)
		{
			IgnoreCollision(recRoomCollider.physicsColliders, ignore);
		}
	}

	public void IgnoreCollision(RecRoomCollider otherRecRoomCollider, bool ignore)
	{
		IgnoreCollision(otherRecRoomCollider.physicsColliders, ignore);
	}

	public void IgnoreCollision(IEnumerable<Collider> otherColliders, bool ignore)
	{
		if (physicsColliders == null)
		{
			return;
		}
		foreach (Collider physicsCollider in physicsColliders)
		{
			foreach (Collider otherCollider in otherColliders)
			{
				Physics.IgnoreCollision(physicsCollider, otherCollider, ignore);
			}
		}
	}

	public void AddCollider(Collider collider)
	{
		if (collider.gameObject == base.gameObject)
		{
			physicsColliders.Add(collider);
		}
	}

	public void RemoveCollider(Collider collider)
	{
		physicsColliders.Remove(collider);
	}

	public virtual Vector3 GetCollisionNormal(Collision collision)
	{
		Vector3 vector = Vector3.zero;
		if (ThisRigidbodyEx != null)
		{
			vector = ThisRigidbodyEx.velocity;
		}
		if (vector.sqrMagnitude < Mathf.Epsilon)
		{
			vector = collision.relativeVelocity.normalized;
		}
		else
		{
			vector.Normalize();
		}
		Vector3 vector2 = Vector3.zero;
		if (collision.contacts != null && collision.contacts.Length > 0)
		{
			ContactPoint contactPoint = collision.contacts[0];
			vector2 = contactPoint.normal;
			Vector3 vector3 = -vector2;
			Vector3 origin = contactPoint.point - vector3;
			if (Physics.Raycast(origin, vector3, out var hitInfo, 2f, 1 << base.gameObject.layer) && Vector3.Dot(hitInfo.normal, vector2) >= 0f)
			{
				vector2 = hitInfo.normal;
			}
		}
		if (vector.sqrMagnitude > Mathf.Epsilon && Vector3.Dot(vector2, vector) < 0.3f)
		{
			vector2 = vector;
		}
		return vector2;
	}

	public bool IsOverlapping(RigidbodyEx otherRigidbodyEx)
	{
		Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
		int num = Physics.OverlapSphereNonAlloc(Bounds.center, Bounds.extents.magnitude, iMMEDIATE_COLLIDER_HITS, 1 << otherRigidbodyEx.gameObject.layer);
		for (int i = 0; i < num; i++)
		{
			if (iMMEDIATE_COLLIDER_HITS[i].gameObject == otherRigidbodyEx.gameObject)
			{
				return true;
			}
		}
		return false;
	}
}
[Serializable]
public struct RendererMaterialPair
{
