namespace RecRoom.Tools
{
	public class RoomDoor : Photon.MonoBehaviour, IPersistable
	{
		[Header("UI")]
		[SerializeField]
		private TextMesh roomNameText;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private TeleportationPortal teleportationPortal;

		private bool _locked;

		private readonly Dictionary<string, EnumChoiceData> subroomOptions = new Dictionary<string, EnumChoiceData>();

		private CreationObject creationObject;

		private EnumSettingEditEvent pickSubroomEditEvent;

		private EnumSettingEditEvent inviteModeEditEvent;

		private SynchronizedField<string, RoomDoorData.Types.RoomDoorTargetType, RoomDoorData.Types.RoomDoorInviteMode> _targetData;

		public string TargetName => _targetData.Get1();

		public RoomDoorData.Types.RoomDoorTargetType TargetType => _targetData.Get2();

		public RoomDoorData.Types.RoomDoorInviteMode InviteMode => _targetData.Get3();

		public Tool Tool => _tool;

		public bool BlockObjectPersistance => false;

		public bool IsLocked => _locked;

		protected override void Awake()
		{
			base.Awake();
			_targetData = new SynchronizedField<string, RoomDoorData.Types.RoomDoorTargetType, RoomDoorData.Types.RoomDoorInviteMode>(this, "TD", string.Empty, RoomDoorData.Types.RoomDoorTargetType.Room, RoomDoorData.Types.RoomDoorInviteMode.Normal, SetterPermissionMode.MASTER_OR_AUTHORITY, OnTargetDataChanged);
		}

		private void Start()
		{
			creationObject = GetComponent<CreationObject>();
			SetupCreationObjectSettings();
			OnTargetDataChanged();
			RecNet.Rooms.OnLocalRoomUpdated.Add(OnLocalRoomUpdate);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			RecNet.Rooms.OnLocalRoomUpdated.Remove(OnLocalRoomUpdate);
		}

		public void ProcessCircuitInput(int signal)
		{
			_locked = CircuitNode.SignalToBool(signal);
			teleportationPortal.IsLocked = _locked;
			UpdateDoorState();
		}

		private void OnLocalRoomUpdate()
		{
			UpdateCreationObjectSettings();
		}

		private void OnTargetDataChanged()
		{
			UpdateDoorState();
			UpdateCreationObjectSettings();
		}

		private void SetupCreationObjectSettings()
		{
			StringSettingEditEvent settingEvent = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultStringUIControlPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, "Link to Room");
				instance.PropertyGetter = TargetRoomName_Get;
				instance.PropertySetter = TargetRoomName_Set;
				instance.SetDialogOptions("Link to Room", "Enter a ^roomname to link to that room");
			});
			creationObject.AddConfigurableSetting(0, settingEvent);
			Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
			dictionary.Add("Normal", new EnumChoiceData
			{
				enumValue = 1,
				tooltip = "Players exit as individuals"
			});
			dictionary.Add("Party Auto-Follow", new EnumChoiceData
			{
				enumValue = 2,
				tooltip = "Exiting will cause all party-members to exit"
			});
			dictionary.Add("Everyone Auto-Follow", new EnumChoiceData
			{
				enumValue = 3,
				tooltip = "Exiting will cause everyone in room to exit"
			});
			Dictionary<string, EnumChoiceData> choicesDictionary = dictionary;
			inviteModeEditEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.PropertyDescription.text = "Invite Mode";
				instance.PropertyGetter = InviteMode_Get;
				instance.PropertySetter = InviteMode_Set;
			}, choicesDictionary);
		}

		private void UpdateCreationObjectSettings()
		{
			if (creationObject == null)
			{
				return;
			}
			creationObject.RemoveConfigurableSetting(pickSubroomEditEvent);
			subroomOptions.Clear();
			RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
			for (int i = 0; i < localRoomDetails.Scenes.Count; i++)
			{
				if (localRoomDetails.Scenes[i].RoomSceneId != GameSessions.LocalGameSession.RoomSceneId)
				{
					subroomOptions.Add(localRoomDetails.Scenes[i].Name, new EnumChoiceData
					{
						enumValue = i
					});
				}
			}
			pickSubroomEditEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.GetComponent<FriendlyIntPagedGrid>()?.SetEmptyDisplayText("This room has no other subrooms.");
				instance.PropertyDescription.text = "Link to Subroom";
				instance.PropertyGetter = TargetSubroom_Get;
				instance.PropertySetter = TargetSubroom_Set;
			}, subroomOptions);
			creationObject.AddConfigurableSetting(1, pickSubroomEditEvent);
			if (TargetType == RoomDoorData.Types.RoomDoorTargetType.RoomScene)
			{
				creationObject.RemoveConfigurableSetting(inviteModeEditEvent);
				creationObject.AddConfigurableSetting(2, inviteModeEditEvent);
			}
			else
			{
				creationObject.RemoveConfigurableSetting(inviteModeEditEvent);
			}
			creationObject.RaiseObjectSettingsFunctionsChangedEvent();
		}

		private IPromise TrySetTargetData(string name, RoomDoorData.Types.RoomDoorTargetType type, RoomDoorData.Types.RoomDoorInviteMode inviteMode)
		{
			return ValidateTargetData(name, type, inviteMode).Then(delegate
			{
				_targetData.Set(name, type, inviteMode);
			});
		}

		private IPromise ValidateTargetData(string name, RoomDoorData.Types.RoomDoorTargetType type, RoomDoorData.Types.RoomDoorInviteMode inviteMode)
		{
			if (type == RoomDoorData.Types.RoomDoorTargetType.UnknownType || inviteMode == RoomDoorData.Types.RoomDoorInviteMode.UnknownMode)
			{
				return new ErroredPromise("Invalid data");
			}
			Promise promise = new Promise();
			switch (type)
			{
			case RoomDoorData.Types.RoomDoorTargetType.Room:
				RecNet.Rooms.GetRoomByName(name).Then((Action<RecNet.Room>)delegate
				{
					if (this != null)
					{
						promise.Complete();
					}
				}).Error(delegate
				{
					if (this != null)
					{
						promise.Error($"Can't find room ^{name}");
					}
				});
				break;
			case RoomDoorData.Types.RoomDoorTargetType.RoomScene:
			{
				RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
				RoomScene roomScene = localRoomDetails.Scenes.FirstOrDefault((RoomScene s) => s.Name == name);
				if (roomScene != null)
				{
					promise.Complete();
				}
				else
				{
					promise.Error($"Can't find subroom {name}");
				}
				break;
			}
			}
			return promise;
		}

		private void TargetRoomName_Set(object obj)
		{
			string targetName = obj.ToString();
			TrySetTargetData(targetName, RoomDoorData.Types.RoomDoorTargetType.Room, InviteMode).Then(delegate
			{
				ShowMessage("Success", "Linked door to ^" + targetName);
			}).Error(delegate(string e)
			{
				ShowMessage("Failed", e);
			});
		}

		private string TargetRoomName_Get()
		{
			if (TargetType == RoomDoorData.Types.RoomDoorTargetType.Room)
			{
				return TargetName;
			}
			return string.Empty;
		}

		private void TargetSubroom_Set(int sceneIndex)
		{
			RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
			if (sceneIndex >= 0 && sceneIndex < localRoomDetails.Scenes.Count)
			{
				string text = localRoomDetails.Scenes[sceneIndex].Name;
				TrySetTargetData(text, RoomDoorData.Types.RoomDoorTargetType.RoomScene, InviteMode).Then(delegate
				{
					ShowMessage("Success", "Target type updated");
				}).Error(delegate(string e)
				{
					ShowMessage("Failed", e);
				});
			}
			else
			{
				ShowMessage("Failed", "Subroom not found");
			}
		}

		private int TargetSubroom_Get()
		{
			if (TargetType == RoomDoorData.Types.RoomDoorTargetType.RoomScene)
			{
				RoomDetails localRoomDetails = RecNet.Rooms.LocalRoomDetails;
				return localRoomDetails.Scenes.FindIndex((RoomScene s) => s.Name == TargetName);
			}
			return -1;
		}

		private void InviteMode_Set(int newValue)
		{
			TrySetTargetData(TargetName, TargetType, (RoomDoorData.Types.RoomDoorInviteMode)newValue);
		}

		private int InviteMode_Get()
		{
			return (int)InviteMode;
		}

		private void UpdateDoorState()
		{
			if (teleportationPortal != null)
			{
				switch (TargetType)
				{
				case RoomDoorData.Types.RoomDoorTargetType.Room:
					teleportationPortal.ChangeMode(TeleportationPortal.PortalMode.Room);
					teleportationPortal.TargetName = TargetName;
					break;
				case RoomDoorData.Types.RoomDoorTargetType.RoomScene:
					teleportationPortal.ChangeMode(TeleportationPortal.PortalMode.RoomScene);
					teleportationPortal.TargetName = TargetName;
					switch (InviteMode)
					{
					case RoomDoorData.Types.RoomDoorInviteMode.PartyAutoFollow:
						teleportationPortal.JoinRoomSceneInviteMode = SessionManager.JoinRoomInviteMode.PartyAutoFollow;
						break;
					case RoomDoorData.Types.RoomDoorInviteMode.EveryoneAutoFollow:
						teleportationPortal.JoinRoomSceneInviteMode = SessionManager.JoinRoomInviteMode.EveryoneAutoFollow;
						break;
					default:
						teleportationPortal.JoinRoomSceneInviteMode = SessionManager.JoinRoomInviteMode.InviteParty;
						break;
					}
					break;
				}
			}
			if (IsLocked)
			{
				roomNameText.text = "LOCKED";
			}
			else if (!string.IsNullOrEmpty(TargetName))
			{
				string arg = ((TargetType != RoomDoorData.Types.RoomDoorTargetType.Room) ? string.Empty : "^");
				string text = string.Format("{0}{1}", arg, TargetName.Truncate(17, "..."));
				roomNameText.text = text;
			}
			else
			{
				roomNameText.text = "Not Active!";
			}
		}

		private void ShowMessage(string title, string message)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, title, message, 4f);
		}

		public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			if (deserializeParams.viewData.RoomDoorData == null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error deserializing RoomDoor {0}: data empty.", base.gameObject);
				return;
			}
			PersistenceViewData viewData = deserializeParams.viewData;
			if (deserializeParams.version < RoomPersistenceVersion.EVERYTHING_A_ROOM)
			{
				long roomIdDeprecated = viewData.RoomDoorData.RoomIdDeprecated;
				RecNet.Rooms.GetRoomById(roomIdDeprecated).Then(delegate(RecNet.Room room)
				{
					TrySetTargetData(room.Name, RoomDoorData.Types.RoomDoorTargetType.Room, RoomDoorData.Types.RoomDoorInviteMode.Normal);
				});
			}
			else
			{
				TrySetTargetData(viewData.RoomDoorData.TargetName, viewData.RoomDoorData.TargetType, viewData.RoomDoorData.InviteMode);
			}
		}

		public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (viewData.RoomDoorData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing RoomDoor {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.RoomDoorData = new RoomDoorData
			{
				TargetName = TargetName,
				TargetType = TargetType,
				InviteMode = InviteMode
			};
		}
	}
	public class ScenePerfToolCoroutineRoot : UnityEngine.MonoBehaviour
