	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Block Melee Weapon Screen Controller", fileName = "BlockMeleeWeaponScreenController")]
	public class BlockMeleeWeaponScreenController : ScreenToolController
	{
		[Header("Animations")]
		[SerializeField]
		private PlayerAnimation[] blockComboAnimations;

		[SerializeField]
		private float maxBlockComboWindow = 1f;

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig attackBlockCameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[NonSerialized]
		private int blockComboIndex;

		[NonSerialized]
		private float lastBlockFinishTime;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => false;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			PlayerHand offHand = playerController.GetOffHand(player);
			Tool heldTool = offHand.HeldTool;
			if (heldTool != null && heldTool != tool)
			{
				MeleeWeapon component = heldTool.GetComponent<MeleeWeapon>();
				if (component != null && component.IsShield)
				{
					return false;
				}
			}
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			return genreController != null && genreController.IsLockingOnToSomething;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			if (component != null && !component.IsBroken)
			{
				if (UnityEngine.Time.time - lastBlockFinishTime > maxBlockComboWindow)
				{
					blockComboIndex = 0;
				}
				else
				{
					blockComboIndex = (blockComboIndex + 1) % blockComboAnimations.Length;
				}
				PlayerAnimation animation = blockComboAnimations[blockComboIndex];
				playerController.PlayLoopingAnimation(animation);
				component.ManualBlockingEnabled = true;
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			return genreController != null && genreController.IsLockingOnToSomething;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			lastBlockFinishTime = UnityEngine.Time.time;
			if (tool != null)
			{
				MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
				component.ManualBlockingEnabled = false;
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			component.BlocksEnemyAttacksAutomatically = false;
			component.ManualBlockingEnabled = false;
			component.BlockAttackEvent += OnWeaponBlock;
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			component.BlocksEnemyAttacksAutomatically = true;
			component.ManualBlockingEnabled = false;
			component.BlockAttackEvent -= OnWeaponBlock;
		}

		private void OnWeaponBlock(Vector3 blockPoint)
		{
			CameraShake.SetShake(attackBlockCameraShake);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Disabled Maker Pen Screen Controller", fileName = "DisabledMakerPenScreenController")]
	public class DisabledMakerPenScreenController : ScreenToolController
	{
		private float lastNotificationTime;

		private float notificationDuration = 3f;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
