	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Fire Cannon Screen Controller", fileName = "FireCannonScreenController")]
	public class FireCannonScreenController : ScreenToolController
	{
		private enum State
		{
			INVALID,
			AIMING,
			FIRING,
			RECOILING
		}

		[Header("Animation")]
		[SerializeField]
		private BlendedPlayerAnimation aimingAnimation;

		[SerializeField]
		private BlendedPlayerAnimation fireAnimation;

		[SerializeField]
		private BlendedPlayerAnimation recoilAnimation;

		[Header("Camera Settings")]
		[SerializeField]
		private ScreenPlayerCameraSettings cameraSettings;

		[SerializeField]
		private float cameraFadeTime = 0.4f;

		[SerializeField]
		private float maxCameraRotationSpeed = 180f;

		[Header("Aiming Settings")]
		[SerializeField]
		private float aimSpeed = 80f;

		[SerializeField]
		private float aimSmoothTime = 0.2f;

		[SerializeField]
		private ScreensCameraInputGamepadSettings aimInputSettings;

		[Header("Exit Settings")]
		[SerializeField]
		protected float exitButtonHoldDuration = 0.2f;

		[SerializeField]
		private Vector2 exitButtonViewportPosition = new Vector2(0.5f, 0.25f);

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig fireCameraShake = CameraShake.CameraShakeConfig.DefaultHeavyShake;

		[NonSerialized]
		private ScreenCameraInput cameraInputController = new ScreenCameraInput();

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private ScreenInputHandler cachedInput;

		[NonSerialized]
		private float aimYawNormalized;

		[NonSerialized]
		private float aimPitchNormalized;

		[NonSerialized]
		private float yawVelocity;

		[NonSerialized]
		private float pitchVelocity;

		[NonSerialized]
		private bool isAttemptingExit;

		[NonSerialized]
		private float exitAttemptStartTime;

		private const float TARGET_DISTANCE = 30f;

		private State _currentState;

		private State CurrentState
		{
			get
			{
				return _currentState;
			}
			set
			{
				State currentState = _currentState;
				if (currentState == value)
				{
					return;
				}
				_currentState = value;
				if (cachedPlayerController != null)
				{
					switch (_currentState)
					{
					case State.AIMING:
						cachedPlayerController.PlayLoopingAnimation(aimingAnimation);
						break;
					case State.FIRING:
						cachedPlayerController.PlayAnimation(fireAnimation);
						break;
					case State.RECOILING:
						cachedPlayerController.PlayAnimation(recoilAnimation);
						break;
					}
				}
			}
		}

		public override bool PlayerMovementAllowed => false;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return true;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isAttemptingExit = false;
			cachedInput = input;
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			if (component != null)
			{
				component.Tool.RigidbodyPickup.Release();
				component.GetNormalizedAimPitchYaw(out aimPitchNormalized, out aimYawNormalized);
				QuestCannon cannonFromHandle = GetCannonFromHandle(component);
				Tool tool2 = cannonFromHandle.Lighter.Tool;
				playerController.TryPickupToolOffHand(player, tool2, playAnimation: true);
			}
			playerController.AddCameraSettings(cameraSettings, cameraFadeTime, this, 200);
			playerController.AddGameplayCursorVisibilityRestriction(this);
			CurrentState = State.AIMING;
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			UpdateState(playerController, player, camera, tool, hud, input);
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			float blendParameter = UpdateCannonRotation(component);
			aimingAnimation.AnimationAsset.SetBlendParameter(blendParameter);
			fireAnimation.AnimationAsset.SetBlendParameter(blendParameter);
			recoilAnimation.AnimationAsset.SetBlendParameter(blendParameter);
			UpdatePlayerPosition(playerController, player, camera, component);
			return CurrentState != State.INVALID;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			playerController.TryDropOffHandTool(player);
			playerController.TryDropMainHandTool(player, tryPickupFromEquipSlot: true);
			playerController.RemoveCameraSettings(this);
			playerController.RemoveGameplayCursorVisibilityRestriction(this);
			cachedInput = null;
			CurrentState = State.INVALID;
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1 && CurrentState == State.FIRING)
			{
				SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
				QuestCannon cannonFromHandle = GetCannonFromHandle(component);
				if (!(cannonFromHandle == null))
				{
					cannonFromHandle.RequestFire(PhotonNetwork.player);
				}
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Fire");
			hud.AddToolActionDialog(input.DropToolButtonSprite, "Exit Cannon");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			cachedPlayerController = playerController;
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			if (component != null)
			{
				QuestCannon cannonFromHandle = GetCannonFromHandle(component);
				if (cannonFromHandle != null)
				{
					cannonFromHandle.LocalPlayerFireEvent += OnCannonFire;
				}
			}
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			cachedPlayerController = null;
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			if (component != null)
			{
				QuestCannon cannonFromHandle = GetCannonFromHandle(component);
				if (cannonFromHandle != null)
				{
					cannonFromHandle.LocalPlayerFireEvent -= OnCannonFire;
				}
			}
		}

		private void UpdateAiming(SwivelToolHandle swivelHandle, ScreenPlayerController playerController, Camera camera, ScreenInputHandler input)
		{
			float absoluteYawAngleFromNormalizedYawAngle = swivelHandle.GetAbsoluteYawAngleFromNormalizedYawAngle(aimYawNormalized);
			float absolutePitchAngleFromNormalizedPitchAngle = swivelHandle.GetAbsolutePitchAngleFromNormalizedPitchAngle(aimPitchNormalized);
			Vector2 rotationDeltaAngles = cameraInputController.GetRotationDeltaAngles(input, aimInputSettings, aimSpeed, UnityEngine.Time.deltaTime);
			rotationDeltaAngles.x *= -1f;
			absoluteYawAngleFromNormalizedYawAngle += rotationDeltaAngles.x;
			absolutePitchAngleFromNormalizedPitchAngle += rotationDeltaAngles.y;
			swivelHandle.GetTransformFromNormalizedYawPitch(aimPitchNormalized, aimYawNormalized, out var position, out var rotation);
			Vector3 target = position + rotation * Vector3.forward * 30f;
			UpdateCameraRotation(camera, target);
			aimYawNormalized = swivelHandle.GetNormalizedYawAngleFromAbsoluteYawAngle(absoluteYawAngleFromNormalizedYawAngle);
			aimPitchNormalized = swivelHandle.GetNormalizedPitchAngleFromAbsolutePitchAngle(absolutePitchAngleFromNormalizedPitchAngle);
		}

		private void UpdatePlayerPosition(ScreenPlayerController playerController, Player player, Camera camera, SwivelToolHandle cannonHandle)
		{
			SwivelTool swivelToolFromHandle = GetSwivelToolFromHandle(cannonHandle);
			if (!(swivelToolFromHandle == null))
			{
				Vector3 vector = Vector3.ProjectOnPlane(swivelToolFromHandle.ScreenWieldTransform.position - player.TrackingSpace.RigidbodyEx.targetPosition, Vector3.up);
				player.PlayerLocomotion.Move(vector / UnityEngine.Time.deltaTime);
				player.TrackingSpace.RigidbodyEx.targetRotation = swivelToolFromHandle.ScreenWieldTransform.rotation;
			}
		}

		private void UpdateCameraRotation(Camera camera, Vector3 target)
		{
			Vector3 forward = target - camera.transform.position;
			Quaternion to = Quaternion.LookRotation(forward);
			camera.transform.rotation = Quaternion.RotateTowards(camera.transform.rotation, to, maxCameraRotationSpeed * UnityEngine.Time.deltaTime);
		}

		private float UpdateCannonRotation(SwivelToolHandle swivelHandle)
		{
			float yaw = 0f;
			float pitch = 0f;
			swivelHandle.GetNormalizedAimPitchYaw(out pitch, out yaw);
			yaw = Mathf.SmoothDampAngle(yaw, aimYawNormalized, ref yawVelocity, aimSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			pitch = Mathf.SmoothDampAngle(pitch, aimPitchNormalized, ref pitchVelocity, aimSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			swivelHandle.AuthoritySetNormalizedAimPitchYaw(pitch, yaw);
			return pitch;
		}

		private void UpdateState(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			switch (CurrentState)
			{
			case State.AIMING:
				UpdateAimingState(playerController, player, camera, tool, hud, input);
				break;
			case State.FIRING:
				UpdateFiringState(playerController, player, camera, tool, input);
				break;
			case State.RECOILING:
				UpdateRecoilingState();
				break;
			}
		}

		private void UpdateAimingState(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (UpdateExitActionButtonHold(input, hud, exitButtonHoldDuration, "Exit Cannon", exitButtonViewportPosition, ref isAttemptingExit, ref exitAttemptStartTime))
			{
				CurrentState = State.INVALID;
				return;
			}
			if (cachedInput.PrimaryMainHandActionButtonDown)
			{
				CurrentState = State.FIRING;
				return;
			}
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			UpdateAiming(component, playerController, camera, input);
		}

		private void UpdateFiringState(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenInputHandler input)
		{
			if (!cachedPlayerController.IsAnimationPlaying(fireAnimation))
			{
				CurrentState = State.AIMING;
				return;
			}
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			UpdateAiming(component, playerController, camera, input);
		}

		private void UpdateRecoilingState()
		{
			if (!cachedPlayerController.IsAnimationPlaying(recoilAnimation))
			{
				CurrentState = State.AIMING;
			}
		}

		private SwivelTool GetSwivelToolFromHandle(SwivelToolHandle swivelHandle)
		{
			if (swivelHandle == null)
			{
				return null;
			}
			if (swivelHandle.Tool.ParentTool == null)
			{
				return null;
			}
			return swivelHandle.Tool.ParentTool.GetComponent<SwivelTool>();
		}

		private QuestCannon GetCannonFromHandle(SwivelToolHandle swivelHandle)
		{
			if (swivelHandle == null)
			{
				return null;
			}
			if (swivelHandle.Tool.ParentTool == null)
			{
				return null;
			}
			return swivelHandle.Tool.ParentTool.GetComponent<QuestCannon>();
		}

		private void OnCannonFire(RangedWeapon rangedWeapon)
		{
			CurrentState = State.RECOILING;
			CameraShake.SetShake(fireCameraShake);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Fire Longbow Screen Controller", fileName = "FireLongbowScreenController")]
	public class FireLongbowScreenController : ScreenToolController
	{
		[Header("Animation")]
		[SerializeField]
		private BlendedPlayerAnimation chargeAnimationBlend;

		[Header("Charging")]
		[SerializeField]
		private float maxChargeDuration = 1.5f;

		[SerializeField]
		private AnimationCurve chargeCurve;

		[SerializeField]
		private float maximumRateOfFire = 10f;

		[Header("Aim Down Sights")]
		[SerializeField]
		private ScreenPlayerAimDownSightsSettings aimDownSightsSettings;

		private bool isCharging;

		private float chargeStartTime;

		private float lastFireTime;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			float num = UnityEngine.Time.time - lastFireTime;
			if (maximumRateOfFire == 0f || num < 1f / maximumRateOfFire)
			{
				return false;
			}
			return input.PrimaryMainHandActionButtonPressed;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isCharging = false;
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			Bow component = tool.GetComponent<Bow>();
			if (!isCharging)
			{
				if (input.PrimaryMainHandActionButtonDown || input.PrimaryMainHandActionButtonPressed)
				{
					StartCharging(playerController, player, component);
				}
			}
			else
			{
				float time = Mathf.InverseLerp(chargeStartTime, chargeStartTime + maxChargeDuration, UnityEngine.Time.time);
				float num = chargeCurve.Evaluate(time);
				chargeAnimationBlend.AnimationAsset.SetBlendParameter(num);
				if (!input.PrimaryMainHandActionButtonPressed)
				{
					FireAndStopCharging(playerController, player, component, num);
				}
			}
			return isCharging;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			if (tool != null)
			{
				Bow component = tool.GetComponent<Bow>();
				FireAndStopCharging(playerController, player, component, 0f);
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Draw Bow (Hold)");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			lastFireTime = 0f;
			Bow component = tool.GetComponent<Bow>();
			component.FireArrowOnStringPickupRelease = false;
			if (aimDownSightsSettings != null)
			{
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
				ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(genreType);
				if (genreController != null)
				{
					genreController.AddAimDownSightsSettings(aimDownSightsSettings, this);
				}
			}
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			Bow component = tool.GetComponent<Bow>();
			component.FireArrowOnStringPickupRelease = true;
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(genreType);
			if (genreController != null)
			{
				genreController.RemoveAimDownSightsSettings(this);
			}
		}

		private void StartCharging(ScreenPlayerController playerController, Player player, Bow bow)
		{
			if (!isCharging)
			{
				isCharging = true;
				chargeStartTime = UnityEngine.Time.time;
				chargeAnimationBlend.AnimationAsset.SetBlendParameter(0f);
				playerController.PlayLoopingAnimation(chargeAnimationBlend);
				playerController.TryPickupToolOffHand(player, bow.BowString.Tool);
				bow.ReadyArrow();
			}
		}

		private void FireAndStopCharging(ScreenPlayerController playerController, Player player, Bow bow, float chargeT)
		{
			if (isCharging)
			{
				isCharging = false;
				bow.AuthorityFireArrowAtPoint(playerController.GazeTarget, chargeT);
				playerController.TryDropOffHandTool(player);
				lastFireTime = UnityEngine.Time.time;
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Fire Mirror Cannon Screen Controller", fileName = "FireMirrorCannonScreenController")]
	public class FireMirrorCannonScreenController : ScreenToolController
	{
		[Header("Animation")]
		[SerializeField]
		private BlendedPlayerAnimation aimingAnimation;

		[SerializeField]
		private BlendedPlayerAnimation fireAnimation;

		[Header("Camera Settings")]
		[SerializeField]
		private ScreenPlayerCameraSettings cameraSettings;

		[SerializeField]
		private float cameraFadeTime = 0.4f;

		[SerializeField]
		private float maxCameraRotationSpeed = 180f;

		[Header("Player Settings")]
		[SerializeField]
		private float maxPlayerTranslateSpeed = 10f;

		[SerializeField]
		private float maxPlayerRotateSpeed = 540f;

		[Header("Aiming Settings")]
		[SerializeField]
		private float aimSpeed = 80f;

		[SerializeField]
		private float aimSmoothTime = 0.2f;

		[SerializeField]
		private ScreensCameraInputGamepadSettings aimInputSettings;

		[Header("Exit Settings")]
		[SerializeField]
		protected float exitButtonHoldDuration = 0.2f;

		[SerializeField]
		private Vector2 exitButtonViewportPosition = new Vector2(0.5f, 0.25f);

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig minFiringCameraShake = CameraShake.CameraShakeConfig.DefaultLightShake;

		[SerializeField]
		private CameraShake.CameraShakeConfig maxFiringCameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		private const float TARGET_DISTANCE = 30f;

		[NonSerialized]
		private ScreenCameraInput cameraInputController = new ScreenCameraInput();

		[NonSerialized]
		private float aimYawNormalized;

		[NonSerialized]
		private float aimPitchNormalized;

		[NonSerialized]
		private float yawVelocity;

		[NonSerialized]
		private float pitchVelocity;

		[NonSerialized]
		private bool isFiring;

		[NonSerialized]
		private bool isAttemptingExit;

		[NonSerialized]
		private float exitAttemptStartTime;

		public override bool PlayerMovementAllowed => false;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return true;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isAttemptingExit = false;
			isFiring = false;
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			if (component != null)
			{
				component.Tool.RigidbodyPickup.Release();
				component.GetNormalizedAimPitchYaw(out aimPitchNormalized, out aimYawNormalized);
			}
			playerController.AddCameraSettings(cameraSettings, cameraFadeTime, this, 200);
			playerController.AddGameplayCursorVisibilityRestriction(this);
			playerController.PlayLoopingAnimation(aimingAnimation);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			SwivelToolHandle component = tool.GetComponent<SwivelToolHandle>();
			if (component == null || UpdateExitActionButtonHold(input, hud, exitButtonHoldDuration, "Exit Cannon", exitButtonViewportPosition, ref isAttemptingExit, ref exitAttemptStartTime))
			{
				playerController.TryDropMainHandTool(player);
				return true;
			}
			MirrorCannon mirrorCannonFromHandle = GetMirrorCannonFromHandle(component);
			bool flag = isFiring;
			isFiring = mirrorCannonFromHandle.Firing;
			if (flag && !isFiring)
			{
				playerController.PlayLoopingAnimation(aimingAnimation);
			}
			else if (!flag && isFiring)
			{
				playerController.PlayLoopingAnimation(fireAnimation);
			}
			float blendParameter = UpdateAiming(component, playerController, camera, input);
			UpdatePlayerPosition(playerController, player, camera, component);
			if (isFiring)
			{
				fireAnimation.AnimationAsset.SetBlendParameter(blendParameter);
				CameraShake.CameraShakeConfig shake = CameraShake.CameraShakeConfig.Lerp(minFiringCameraShake, maxFiringCameraShake, mirrorCannonFromHandle.ChargePercentage);
				CameraShake.SetShake(shake);
			}
			else
			{
				aimingAnimation.AnimationAsset.SetBlendParameter(blendParameter);
			}
			return true;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			playerController.RemoveCameraSettings(this);
			playerController.RemoveGameplayCursorVisibilityRestriction(this);
			if (player != null)
			{
				playerController.TryDropOffHandTool(player);
				playerController.TryDropMainHandTool(player, tryPickupFromEquipSlot: true);
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.DropToolButtonSprite, "Exit Cannon");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		private float UpdateAiming(SwivelToolHandle swivelHandle, ScreenPlayerController playerController, Camera camera, ScreenInputHandler input)
		{
			float absoluteYawAngleFromNormalizedYawAngle = swivelHandle.GetAbsoluteYawAngleFromNormalizedYawAngle(aimYawNormalized);
			float absolutePitchAngleFromNormalizedPitchAngle = swivelHandle.GetAbsolutePitchAngleFromNormalizedPitchAngle(aimPitchNormalized);
			Vector2 rotationDeltaAngles = cameraInputController.GetRotationDeltaAngles(input, aimInputSettings, aimSpeed, UnityEngine.Time.deltaTime);
			rotationDeltaAngles.x *= -1f;
			absoluteYawAngleFromNormalizedYawAngle += rotationDeltaAngles.x;
			absolutePitchAngleFromNormalizedPitchAngle += rotationDeltaAngles.y;
			swivelHandle.GetTransformFromNormalizedYawPitch(aimPitchNormalized, aimYawNormalized, out var position, out var rotation);
			Vector3 target = position + rotation * Vector3.forward * 30f;
			UpdateCameraRotation(camera, target);
			aimYawNormalized = swivelHandle.GetNormalizedYawAngleFromAbsoluteYawAngle(absoluteYawAngleFromNormalizedYawAngle);
			aimPitchNormalized = swivelHandle.GetNormalizedPitchAngleFromAbsolutePitchAngle(absolutePitchAngleFromNormalizedPitchAngle);
			float yaw = 0f;
			float pitch = 0f;
			swivelHandle.GetNormalizedAimPitchYaw(out pitch, out yaw);
			yaw = Mathf.SmoothDampAngle(yaw, aimYawNormalized, ref yawVelocity, aimSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			pitch = Mathf.SmoothDampAngle(pitch, aimPitchNormalized, ref pitchVelocity, aimSmoothTime, float.MaxValue, UnityEngine.Time.deltaTime);
			swivelHandle.AuthoritySetNormalizedAimPitchYaw(pitch, yaw);
			return pitch;
		}

		private void UpdateCameraRotation(Camera camera, Vector3 target)
		{
			Vector3 forward = target - camera.transform.position;
			Quaternion to = Quaternion.LookRotation(forward);
			camera.transform.rotation = Quaternion.RotateTowards(camera.transform.rotation, to, maxCameraRotationSpeed * UnityEngine.Time.deltaTime);
		}

		private void UpdatePlayerPosition(ScreenPlayerController playerController, Player player, Camera camera, SwivelToolHandle swivelHandle)
		{
			SwivelTool swivelToolFromHandle = GetSwivelToolFromHandle(swivelHandle);
			if (!(swivelToolFromHandle == null))
			{
				Vector3 vector = Vector3.ProjectOnPlane(swivelToolFromHandle.ScreenWieldTransform.position - player.TrackingSpace.RigidbodyEx.targetPosition, Vector3.up);
				Vector3 vector2 = vector / UnityEngine.Time.deltaTime;
				vector2 = Vector3.ClampMagnitude(vector2, maxPlayerTranslateSpeed);
				player.PlayerLocomotion.Move(vector2);
				player.TrackingSpace.RigidbodyEx.targetRotation = Quaternion.RotateTowards(player.TrackingSpace.RigidbodyEx.targetRotation, swivelToolFromHandle.ScreenWieldTransform.rotation, maxPlayerRotateSpeed * UnityEngine.Time.deltaTime);
			}
		}

		private SwivelTool GetSwivelToolFromHandle(SwivelToolHandle swivelHandle)
		{
			if (swivelHandle == null)
			{
				return null;
			}
			if (swivelHandle.Tool.ParentTool == null)
			{
				return null;
			}
			return swivelHandle.Tool.ParentTool.GetComponent<SwivelTool>();
		}

		private MirrorCannon GetMirrorCannonFromHandle(SwivelToolHandle swivelHandle)
		{
			if (swivelHandle == null)
			{
				return null;
			}
			if (swivelHandle.Tool.ParentTool == null)
			{
				return null;
			}
			return swivelHandle.Tool.ParentTool.GetComponent<MirrorCannon>();
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Fire Ranged Weapon Screen Controller", fileName = "FireRangedWeaponScreenController")]
	public class FireRangedWeaponScreenController : ScreenToolController
	{
		[Header("Recoil")]
		[SerializeField]
		private PlayerAnimation recoilAnimation;

		[Header("Aim Down Sights")]
		[SerializeField]
		private ScreenPlayerAimDownSightsSettings aimDownSightsSettings;

		[Header("Configuration")]
		[SerializeField]
		private bool runsUntilInputUp;

		[SerializeField]
		private bool disarmOnTotalAmmoExhaustion;

		[Header("Reticle")]
		[SerializeField]
		private ScreenPlayerRangedWeaponCrosshairSettings crosshairSettings;

		[SerializeField]
		private bool hideReticle;

		[Header("Accuracy")]
		[SerializeField]
		private ScreenPlayerRangedWeaponAccuracySettings accuracySettings;

		[Header("Breakable Weapons")]
		[SerializeField]
		private PlayerAnimation weaponBreakAnimation;

		[SerializeField]
		private RecRoomAudioClip weaponBreak2DAudio;

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig onFireCameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private Player cachedPlayer;

		[NonSerialized]
		private float crosshairTickDistance;

		[NonSerialized]
		private float crosshairTickDistanceVelocity;

		[NonSerialized]
		private float spreadRadius;

		[NonSerialized]
		private float accuracyRadiusVelocity;

		private bool hasFired;

		private bool deferredFirstShot;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => false;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			RangedWeapon component = tool.GetComponent<RangedWeapon>();
			if (component == null)
			{
				return false;
			}
			if (!component.HasEnoughMagazineAmmunition)
			{
				return false;
			}
			return input.PrimaryMainHandActionButtonDown || (runsUntilInputUp && input.PrimaryMainHandActionButtonPressed);
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hasFired = false;
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(genreType);
			deferredFirstShot = genreController != null && !genreController.IsActionReadyAnimationPlaying();
			if (genreController != null)
			{
				genreController.PlayActionReadyAnimation();
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			RangedWeapon component = tool.GetComponent<RangedWeapon>();
			UpdateRangedWeaponGazeTarget(playerController, player, camera, component);
			if (!hasFired)
			{
				if (deferredFirstShot && playerController.IsAnimationFadingIn())
				{
					return true;
				}
				hasFired = true;
				tool.InputDown();
			}
			bool flag = false;
			if (input.PrimaryMainHandActionButtonPressed)
			{
				flag = true;
				tool.InputPressed();
			}
			if (input.PrimaryMainHandActionButtonUp)
			{
				flag = true;
				tool.InputUp();
			}
			return runsUntilInputUp && flag;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			tool.InputCancelled();
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			if (crosshairSettings != null)
			{
				UpdateCrosshair(playerController, player, hud, crosshairSettings);
			}
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Fire");
			hud.AddToolActionDialog(input.AimDownSightsButtonSprite, "Aim");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			cachedPlayerController = playerController;
			cachedPlayer = player;
			if (crosshairSettings != null)
			{
				InitializeCrosshairTicks(playerController, player, hud, crosshairSettings);
			}
			else
			{
				playerController.CursorSystem.HideCrosshair(hud);
			}
			if (crosshairSettings != null || hideReticle)
			{
				playerController.AddGameplayCursorVisibilityRestriction(this);
			}
			if (aimDownSightsSettings != null)
			{
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
				ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(genreType);
				if (genreController != null)
				{
					genreController.AddAimDownSightsSettings(aimDownSightsSettings, this);
				}
			}
			RangedWeapon component = tool.GetComponent<RangedWeapon>();
			if (component != null)
			{
				component.LocalPlayerFireEvent += OnWeaponFire;
			}
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			cachedPlayerController = null;
			cachedPlayer = null;
			if (tool != null)
			{
				tool.InputCancelled();
				RangedWeapon component = tool.GetComponent<RangedWeapon>();
				if (component != null)
				{
					component.HasOverridenTargetPoint = false;
					component.LocalPlayerFireEvent -= OnWeaponFire;
				}
			}
			playerController.RemoveGameplayCursorVisibilityRestriction(this);
			playerController.ResetCursor(hud);
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(genreType);
			if (genreController != null)
			{
				genreController.RemoveAimDownSightsSettings(this);
			}
		}

		private void UpdateRangedWeaponGazeTarget(ScreenPlayerController playerController, Player player, Camera camera, RangedWeapon rangedWeapon)
		{
			rangedWeapon.HasOverridenTargetPoint = true;
			Vector3 gazeTarget = playerController.GazeTarget;
			if (accuracySettings != null)
			{
				UpdateSpreadRadius(playerController, player, accuracySettings);
				Vector2 vector = UnityEngine.Random.insideUnitCircle * spreadRadius * playerController.NormalizedGazeTargetDistance;
				Vector3 right = camera.transform.right;
				Vector3 up = camera.transform.up;
				gazeTarget += right * vector.x + up * vector.y;
			}
			rangedWeapon.OverrideTargetPoint = gazeTarget;
		}

		private void InitializeCrosshairTicks(ScreenPlayerController playerController, Player player, ScreenHUD hud, ScreenPlayerRangedWeaponCrosshairSettings settings)
		{
			crosshairTickDistance = settings.GetTickDistance(player, IsAimingDownSights(playerController));
			crosshairTickDistanceVelocity = 0f;
		}

		private void UpdateCrosshair(ScreenPlayerController playerController, Player player, ScreenHUD hud, ScreenPlayerRangedWeaponCrosshairSettings settings)
		{
			float tickDistance = settings.GetTickDistance(player, IsAimingDownSights(playerController));
			crosshairTickDistance = Mathf.SmoothDamp(crosshairTickDistance, tickDistance, ref crosshairTickDistanceVelocity, settings.GetTickDistanceChangeTime());
			playerController.CursorSystem.SetCrosshairTickDistance(hud, crosshairTickDistance);
			playerController.CursorSystem.ShowCrosshair(hud);
		}

		private void InitializeSpreadRadius(ScreenPlayerController playerController, Player player, ScreenPlayerRangedWeaponAccuracySettings settings)
		{
			spreadRadius = settings.GetSpreadRadius(player, IsAimingDownSights(playerController));
			accuracyRadiusVelocity = 0f;
		}

		private void UpdateSpreadRadius(ScreenPlayerController playerController, Player player, ScreenPlayerRangedWeaponAccuracySettings settings)
		{
			float target = settings.GetSpreadRadius(player, IsAimingDownSights(playerController));
			spreadRadius = Mathf.SmoothDamp(spreadRadius, target, ref accuracyRadiusVelocity, settings.GetSpreadRadiusChangeTime());
		}

		private bool IsAimingDownSights(ScreenPlayerController playerController)
		{
			ShooterScreenPlayerGenre genreController = playerController.GetGenreController<ShooterScreenPlayerGenre>(ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER);
			return genreController != null && genreController.IsAimingDownSights;
		}

		private void OnWeaponFire(RangedWeapon rangedWeapon)
		{
			CameraShake.SetShake(onFireCameraShake);
			if (recoilAnimation != null && recoilAnimation.AnimationAsset != null && cachedPlayerController != null)
			{
				cachedPlayerController.PlayUninterruptableAnimation(recoilAnimation, restartIfAlreadyPlaying: true);
			}
			if (rangedWeapon != null && rangedWeapon.IsAmmoTotallyExhausted && disarmOnTotalAmmoExhaustion && cachedPlayer != null && cachedPlayerController != null)
			{
				AudioManager.Play2DSFX(weaponBreak2DAudio);
				if (weaponBreakAnimation != null && weaponBreakAnimation.AnimationAsset != null)
				{
					cachedPlayerController.PlayUninterruptableAnimation(weaponBreakAnimation, restartIfAlreadyPlaying: true);
				}
				cachedPlayerController.TryDropMainHandTool(cachedPlayer, tryPickupFromEquipSlot: true);
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Maker Pen Screen Controller", fileName = "MakerPenScreenController")]
	public class MakerPenScreenController : ScreenToolController
	{
		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation loopingAnimation;

		[Header("Settings")]
		[SerializeField]
		private ScreenCreationController creationController;

		[Header("Input")]
		[SerializeField]
		private float exitCreationModeButtonHoldDuration = 0.4f;

		[SerializeField]
		private Vector2 exitInteractDialogViewportPosition = new Vector2(0.5f, 0.15f);

		[NonSerialized]
		private bool exitButtonHeld;

		[NonSerialized]
		private float exitButtonHoldStartTime;

		public override bool PlayerMovementAllowed => false;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return MakerPen.LocalPlayerCanUseCreationMode;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.PlayLoopingAnimation(loopingAnimation);
			MakerPen component = tool.GetComponent<MakerPen>();
			component.PenVisuals.LaserPointerEnabled = false;
			exitButtonHeld = false;
			creationController.OnEnterMode(playerController, player, camera, hud, component.CreationContext, input, component);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!MakerPen.LocalPlayerCanUseCreationMode)
			{
				return false;
			}
			if (!tool.IsHeld)
			{
				return false;
			}
			return creationController.OnUpdate();
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			creationController.OnExitMode();
			if (MakerPen.LocalPlayerCanUseCreationMode)
			{
				playerController.TryDropMainHandTool(player);
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		private bool UpdateExitButton(ScreenHUD hud, ScreenInputHandler input)
		{
			if (!exitButtonHeld && input.FavoriteToolButtonDown)
			{
				exitButtonHeld = true;
				exitButtonHoldStartTime = UnityEngine.Time.time;
			}
			if (exitButtonHeld)
			{
				float num = Mathf.InverseLerp(exitButtonHoldStartTime, exitButtonHoldStartTime + exitCreationModeButtonHoldDuration, UnityEngine.Time.time);
				hud.EnableInteractDialog(exitInteractDialogViewportPosition, input.FavoriteToolSprite, "Exit Maker Pen", num);
				if (num >= 1f)
				{
					return true;
				}
				if (!input.FavoriteToolButtonPressed || input.FavoriteToolButtonUp)
				{
					exitButtonHeld = false;
				}
			}
			return false;
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Open Tear Strip Chest Screen Controller", fileName = "OpenTearStripChestScreenController")]
	public class OpenTearStripChestScreenController : ScreenToolController
	{
		[Header("Open Animation")]
		[SerializeField]
		private PlayerAnimation openAnimation;

		public override bool PlayerMovementAllowed => false;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			TearStripTab component = tool.GetComponent<TearStripTab>();
			return component != null && !component.IsTorn;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.PlayUninterruptableAnimation(openAnimation, restartIfAlreadyPlaying: true);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (tool != null)
			{
				TearStripTab component = tool.GetComponent<TearStripTab>();
				if (!(component != null))
				{
				}
			}
			return playerController.IsAnimationPlaying(openAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			if (tool != null)
			{
				TearOffStrip(playerController, player, tool);
				EnableTearStripTearing(tool, enabled: true);
				playerController.TryDropMainHandTool(player, tryPickupFromEquipSlot: true);
			}
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1:
				EnableTearStripTearing(tool, enabled: true);
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_2:
				TearOffStrip(playerController, player, tool);
				break;
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			EnableTearStripTearing(tool, enabled: false);
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			EnableTearStripTearing(tool, enabled: true);
		}

		private void TearOffStrip(ScreenPlayerController playerController, Player player, Tool tool)
		{
			TearStripTab component = tool.GetComponent<TearStripTab>();
			if (component != null && !component.IsTorn)
			{
				component.TearOff();
			}
		}

		private void EnableTearStripTearing(Tool tool, bool enabled)
		{
			if (tool != null)
			{
				TearStripTab component = tool.GetComponent<TearStripTab>();
				if (component != null)
				{
					component.TearingEnabled = enabled;
				}
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Outfit Tool Equip Screen Controller", fileName = "OutfitToolEquipScreenController")]
	public class OutfitToolEquipScreenController : ScreenToolController
	{
		private enum AnimationType
		{
			HEAD,
			CHEST,
			HAND
		}

		[SerializeField]
		private PlayerAnimation chestAnimation;

		[SerializeField]
		private PlayerAnimation headAnimation;

		[SerializeField]
		private PlayerAnimation handAnimation;

		private AnimationType animationType = AnimationType.CHEST;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return input.PrimaryMainHandActionButtonDown || input.PrimaryMainHandActionButtonPressed;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			OutfitTool component = tool.GetComponent<OutfitTool>();
			if (component != null)
			{
				switch (component.GetEquipTargetPlayerBodyPart())
				{
				case Player.BodyPart.Head:
				case Player.BodyPart.Mouth:
					animationType = AnimationType.HEAD;
					break;
				case Player.BodyPart.LeftHand:
				case Player.BodyPart.RightHand:
					animationType = AnimationType.HAND;
					break;
				default:
					animationType = AnimationType.CHEST;
					break;
				}
			}
			else
			{
				animationType = AnimationType.CHEST;
			}
			PlayerAnimation bodyPartEquipAnimation = GetBodyPartEquipAnimation();
			playerController.PlayAnimation(bodyPartEquipAnimation);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			PlayerAnimation bodyPartEquipAnimation = GetBodyPartEquipAnimation();
			return playerController.IsAnimationPlaying(bodyPartEquipAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1)
			{
				OutfitTool component = tool.GetComponent<OutfitTool>();
				if (component != null)
				{
					component.ApplyToPlayer(player);
				}
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Put On");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			OutfitTool component = tool.GetComponent<OutfitTool>();
			component.EquipOnCollision = false;
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			OutfitTool component = tool.GetComponent<OutfitTool>();
			component.EquipOnCollision = true;
		}

		private PlayerAnimation GetBodyPartEquipAnimation()
		{
			return animationType switch
			{
				AnimationType.HAND => handAnimation, 
				AnimationType.HEAD => headAnimation, 
				_ => chestAnimation, 
			};
		}
	}
