	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Reload Ranged Weapon Screen Controller", fileName = "ReloadRangedWeaponScreenController")]
	public class ReloadRangedWeaponScreenController : ScreenToolController
	{
		[SerializeField]
		private PlayerAnimation reloadAnimation;

		private WeaponReloader reloader;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			RangedWeapon component = tool.GetComponent<RangedWeapon>();
			if (component == null)
			{
				return false;
			}
			if (component.MagazineAmmunitionNormalized == 1f)
			{
				return false;
			}
			if (component.MagazineAmmunition == 0 && input.PrimaryMainHandActionButtonDown)
			{
				return true;
			}
			if (input.UsingKeyboardMouse)
			{
				return input.SecondaryMainHandActionButtonDown;
			}
			return input.PickupButtonUp;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			playerController.PlayAnimation(reloadAnimation);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			return playerController.IsAnimationPlaying(reloadAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			ReleaseReloader(playerController, player);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1:
				PickupReloader(playerController, player);
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_2:
			{
				ReleaseReloader(playerController, player);
				RangedWeapon component = tool.GetComponent<RangedWeapon>();
				if (component != null)
				{
					component.ReloadAmmunition();
				}
				break;
			}
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (input.UsingKeyboardMouse)
			{
				hud.AddToolActionDialog(input.SecondaryActionButtonSprite, "Reload");
			}
			else
			{
				hud.AddToolActionDialog(input.PickupButtonSprite, "Reload");
			}
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			reloader = tool.GetComponentInChildren<WeaponReloader>();
			if (reloader != null)
			{
				reloader.ReloadsAutomatically = false;
			}
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			if (reloader != null)
			{
				reloader.ReloadsAutomatically = true;
			}
			reloader = null;
		}

		private void PickupReloader(ScreenPlayerController playerController, Player player)
		{
			if (reloader != null)
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				if (offHand.HeldTool == null)
				{
					playerController.TryPickupToolOffHand(player, reloader.Tool);
				}
			}
		}

		private void ReleaseReloader(ScreenPlayerController playerController, Player player)
		{
			if (reloader != null && player != null)
			{
				PlayerHand offHand = playerController.GetOffHand(player);
				if (offHand.HeldTool == reloader.Tool)
				{
					playerController.TryDropOffHandTool(player);
				}
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Share Camera Screen Controller", fileName = "ShareCameraScreenController")]
	public class ShareCameraScreenController : ScreenToolController
	{
		private enum State
		{
			INVALID,
			FRAMING_FORWARD_PHOTO,
			FRAMING_SELFIE_PHOTO,
			TAKING_PHOTO,
			REVIEWING_PHOTO
		}

		[Header("Camera Settings")]
		[SerializeField]
		private ScreenPlayerCameraSettings framingForwardCameraSettings;

		[SerializeField]
		private ScreenPlayerCameraSettings framingSelfieCameraSettings;

		[SerializeField]
		private float cameraTransitionDuration = 0.5f;

		[Header("Camera Controls")]
		[SerializeField]
		private OrbitScreenPlayerCamera framingCameraController;

		[SerializeField]
		private StationaryScreenPlayerCamera stationaryCameraController;

		[Header("Steering Controller")]
		[SerializeField]
		private FaceTargetScreenPlayerSteering steeringController;

		[SerializeField]
		private StationaryFaceTargetScreenPlayerSteering stationarySteeringController;

		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation loopingAnimation;

		[SerializeField]
		private PlayerAnimation loopingSelfieModeAnimation;

		[Header("Menu Settings")]
		[SerializeField]
		private float menuVerticalBufferPercentage = 0.8f;

		[SerializeField]
		private ScreenPlayerCursorSettings framingCursorSettings;

		[SerializeField]
		private ScreenPlayerCursorSettings reviewingCursorSettings;

		[Header("Input")]
		[SerializeField]
		private float exitCreationModeButtonHoldDuration = 0.4f;

		[SerializeField]
		private Vector2 exitInteractDialogViewportPosition = new Vector2(0.5f, 0.15f);

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private ShareCamera cachedShareCamera;

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private Player cachedPlayer;

		[NonSerialized]
		private Camera cachedCamera;

		[NonSerialized]
		private ScreenHUD cachedHud;

		[NonSerialized]
		private ScreenInputHandler cachedInput;

		[NonSerialized]
		private bool exitButtonHeld;

		[NonSerialized]
		private float exitButtonHoldStartTime;

		[NonSerialized]
		private bool initialized;

		[NonSerialized]
		private bool wasInSelfieMode;

		[NonSerialized]
		private bool hasSetCameraCullMask;

		[NonSerialized]
		private int defaultCameraCullingMask = -1;

		[NonSerialized]
		private float lastPhotoTime;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return true;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			cachedShareCamera = ((!(tool != null)) ? null : tool.GetComponent<ShareCamera>());
			cachedPlayerController = playerController;
			cachedPlayer = player;
			cachedCamera = camera;
			cachedHud = hud;
			cachedInput = input;
			exitButtonHeld = false;
			wasInSelfieMode = false;
			defaultCameraCullingMask = camera.cullingMask;
			cachedShareCamera.TimerIsActive = false;
			cachedShareCamera.IsMenuVisibilityManagedInternally = false;
			if (cachedShareCamera.Tool.MenuProjector != null)
			{
				cachedShareCamera.Tool.MenuProjector.GazeOpenSupported = false;
				cachedShareCamera.Tool.MenuProjector.AuthorityDetachMenuFromTool();
				cachedShareCamera.Tool.MenuProjector.IsMenuVisible = false;
			}
			playerController.AddMenuOpeningRestriction(this);
			playerController.QuickCommsController.AddRestriction(this);
			EnableHudDialogContent(cachedHud);
			stateMachine.EnterState(1);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			stateMachine.Update();
			bool flag = UpdateExitButton(hud, input);
			return !flag;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			stateMachine.EnterState(0);
			if (cachedShareCamera != null)
			{
				cachedShareCamera.Tool.MenuProjector.GazeOpenSupported = true;
				cachedShareCamera.AuthorityClearScreensExplicitCameraTransform();
				cachedShareCamera.IsMenuVisibilityManagedInternally = true;
				if (cachedShareCamera.Tool.MenuProjector != null)
				{
					cachedShareCamera.Tool.MenuProjector.AuthorityAttachMenuToTool();
				}
			}
			if (cachedPlayerController != null)
			{
				playerController.RemoveCameraController(this);
				playerController.RemoveCameraSettings(this);
				playerController.RemoveSteeringController(this);
				playerController.RemoveCrouchRestriction(this);
				playerController.RemoveMenuOpeningRestriction(this);
				playerController.QuickCommsController.RemoveRestriction(this);
			}
			if (cachedPlayer != null)
			{
				cachedPlayer.PlayerWalking.RemoveJumpEnabled(this);
			}
			if (cachedHud != null)
			{
				ClearHudControlsDialogs(cachedHud);
				ClearHudToolDialogs(cachedHud);
				DisableHudDialogContent(cachedHud);
			}
			if (cachedCamera != null)
			{
				cachedCamera.cullingMask = defaultCameraCullingMask;
			}
			cachedShareCamera = null;
			cachedPlayerController = null;
			cachedPlayer = null;
			cachedCamera = null;
			cachedHud = null;
			cachedInput = null;
			playerController.TryDropMainHandTool(player);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			LazyInitialize();
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		private bool UpdateExitButton(ScreenHUD hud, ScreenInputHandler input)
		{
			State currentStateId = (State)stateMachine.CurrentStateId;
			if (!exitButtonHeld && input.CancelButtonDown && currentStateId != State.REVIEWING_PHOTO)
			{
				exitButtonHeld = true;
				exitButtonHoldStartTime = UnityEngine.Time.time;
			}
			if (exitButtonHeld)
			{
				float num = Mathf.InverseLerp(exitButtonHoldStartTime, exitButtonHoldStartTime + exitCreationModeButtonHoldDuration, UnityEngine.Time.time);
				hud.EnableInteractDialog(exitInteractDialogViewportPosition, input.CancelButtonSprite, "Exit Share Cam", num);
				if (num >= 1f)
				{
					return true;
				}
				if (!input.CancelButtonPressed || input.CancelButtonUp)
				{
					exitButtonHeld = false;
				}
			}
			return false;
		}

		private void OnEnterFramingForwardPhotoState(ushort previousStateId, ushort previousSubStateId)
		{
			hasSetCameraCullMask = false;
			wasInSelfieMode = false;
			EnableHudDialogContent(cachedHud);
			cachedShareCamera.EnterActiveState();
			cachedShareCamera.Tool.MenuProjector.IsMenuVisible = false;
			cachedPlayerController.PlayLoopingAnimation(loopingAnimation);
			cachedPlayerController.CursorSystem.ShowCursor(cachedHud);
			cachedPlayerController.CursorSystem.SetCursorSettings(cachedHud, framingCursorSettings);
			cachedPlayerController.CursorSystem.SnapToCenter(cachedHud);
			cachedPlayerController.AddCameraSettings(framingForwardCameraSettings, cameraTransitionDuration, this, 1000);
			cachedPlayerController.AddCameraController(framingCameraController, cameraTransitionDuration, this, 1000);
			steeringController.TargetTransform = cachedCamera.transform;
			cachedPlayerController.AddSteeringController(steeringController, this, 1000);
		}

		private void OnUpdateFramingForwardPhotoState()
		{
			if (!hasSetCameraCullMask && !cachedPlayerController.IsAnyCameraControllerBlending)
			{
				hasSetCameraCullMask = true;
				cachedCamera.cullingMask = defaultCameraCullingMask & -257;
			}
			ClearHudControlsDialogs(cachedHud);
			AddHudControlsDialog(cachedHud, cachedInput.CancelButtonSprite, "Exit Share Camera");
			ClearHudToolDialogs(cachedHud);
			SetHudLabel(cachedHud, "Photo Mode");
			AddHudToolDialog(cachedHud, cachedInput.PrimaryActionButtonSprite, "Take Photo");
			AddHudToolDialog(cachedHud, cachedInput.SecondaryMenuButtonSprite, "Selfie Mode");
			if (cachedInput.PrimaryMainHandActionButtonDown)
			{
				stateMachine.EnterState(3);
			}
			else if (cachedInput.SecondaryMenuButtonDown)
			{
				stateMachine.EnterState(2);
			}
		}

		private void OnEnterFramingSelfiePhotoState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedCamera.cullingMask = defaultCameraCullingMask;
			wasInSelfieMode = true;
			EnableHudDialogContent(cachedHud);
			cachedShareCamera.EnterActiveState();
			cachedShareCamera.Tool.MenuProjector.IsMenuVisible = false;
			cachedPlayerController.PlayLoopingAnimation(loopingSelfieModeAnimation);
			cachedPlayerController.CursorSystem.ShowCursor(cachedHud);
			cachedPlayerController.CursorSystem.SetCursorSettings(cachedHud, framingCursorSettings);
			cachedPlayerController.CursorSystem.SnapToCenter(cachedHud);
			cachedPlayerController.AddCameraSettings(framingSelfieCameraSettings, cameraTransitionDuration, this, 1000);
			cachedPlayerController.AddCameraController(framingCameraController, cameraTransitionDuration, this, 1000);
			steeringController.TargetTransform = cachedCamera.transform;
			cachedPlayerController.AddSteeringController(steeringController, this, 1000);
		}

		private void OnUpdateFramingSelfiePhotoState()
		{
			ClearHudControlsDialogs(cachedHud);
			AddHudControlsDialog(cachedHud, cachedInput.CancelButtonSprite, "Exit Share Camera");
			ClearHudToolDialogs(cachedHud);
			SetHudLabel(cachedHud, "Selfie Mode");
			AddHudToolDialog(cachedHud, cachedInput.PrimaryActionButtonSprite, "Take Selfie");
			AddHudToolDialog(cachedHud, cachedInput.SecondaryMenuButtonSprite, "Photo Mode");
			if (cachedInput.PrimaryMainHandActionButtonDown)
			{
				stateMachine.EnterState(3);
			}
			else if (cachedInput.SecondaryMenuButtonDown)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnEnterTakingPhotoState(ushort previousStateId, ushort previousSubStateId)
		{
			lastPhotoTime = UnityEngine.Time.time;
			DisableHudDialogContent(cachedHud);
			cachedPlayerController.AddCameraController(stationaryCameraController, 0f, this, 1000);
			stationarySteeringController.GazeTargetTransform = cachedCamera.transform;
			cachedPlayerController.AddSteeringController(stationarySteeringController, this, 1000);
			cachedShareCamera.Tool.MenuProjector.IsMenuVisible = false;
			cachedShareCamera.AuthoritySetScreensExplicitCameraTransform(cachedCamera.transform.position, cachedCamera.transform.rotation);
			cachedShareCamera.TakePicture();
			cachedPlayerController.CursorSystem.HideCursor(cachedHud);
		}

		private void OnUpdateTakingPhotoState()
		{
			if (UnityEngine.Time.time - lastPhotoTime >= 0.2f)
			{
				stateMachine.EnterState(4);
			}
		}

		private void OnExitTakingPhotoState(ushort nextStateId, ushort nextSubStateId)
		{
			EnableHudDialogContent(cachedHud);
		}

		private void OnEnterReviewingPhotoState(ushort previousStateId, ushort previousSubStateId)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = false;
			DisableHudDialogContent(cachedHud);
			cachedPlayerController.AddCameraController(stationaryCameraController, 0f, this, 1000);
			stationarySteeringController.GazeTargetTransform = cachedCamera.transform;
			cachedPlayerController.AddSteeringController(stationarySteeringController, this, 1000);
			cachedPlayerController.CursorSystem.ShowCursor(cachedHud);
			cachedPlayerController.CursorSystem.SetCursorSettings(cachedHud, reviewingCursorSettings);
			cachedPlayerController.CursorSystem.SnapToCenter(cachedHud);
			cachedHud.WorldSpaceUIAnchor.Attach(cachedShareCamera.Tool.MenuProjector, cachedShareCamera.Tool.Menu, menuVerticalBufferPercentage, resetPositionOnDetach: false);
			cachedShareCamera.Tool.MenuProjector.IsMenuVisible = true;
			cachedPlayer.PlayerWalking.AddJumpEnabled(enabled: false, this, int.MaxValue);
		}

		private void OnUpdateReviewingPhotoState()
		{
			bool isOverTarget = UpdateMenuInput();
			UpdateCursorPosition(isOverTarget);
			AddHudToolDialog(cachedHud, cachedInput.CancelButtonSprite, "Finish Reviewing");
			if (cachedShareCamera.IsInActiveState() || cachedInput.CreationCancelButtonDown || cachedInput.MenuButtonDown)
			{
				stateMachine.EnterState((ushort)((!wasInSelfieMode) ? 1 : 2));
			}
		}

		private void OnExitReviewingPhotoState(ushort nextStateId, ushort nextSubStateId)
		{
			SingletonMonoBehaviour<LocalPlayerController>.Instance.IsCursorLocked = true;
			cachedShareCamera.Tool.MenuProjector.IsMenuVisible = false;
			cachedHud.WorldSpaceUIAnchor.Detach();
			cachedPlayer.PlayerWalking.RemoveJumpEnabled(this);
		}

		private bool UpdateMenuInput()
		{
			Ray ray = cachedPlayerController.CursorSystem.GetRay(cachedCamera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, 0f, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, cachedInput.CursorButtonDown, cachedInput.CursorButtonUp);
			return result.UISelectable;
		}

		private void UpdateCursorPosition(bool isOverTarget)
		{
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (cachedInput.UsingKeyboardMouse)
			{
				cachedPlayerController.CursorSystem.SetCursorScreenPosition(cachedHud, cachedCamera, gameViewFocused, cachedInput.CursorMouseScreenPosition);
			}
			else
			{
				cachedPlayerController.CursorSystem.AccelerateCursor(cachedHud, cachedInput.CursorAxis, gameViewFocused, isOverTarget);
			}
		}

		private void LazyInitialize()
		{
			if (!initialized)
			{
				initialized = true;
				stateMachine.AddState(0, null, null, null);
				stateMachine.AddState(1, OnEnterFramingForwardPhotoState, null, OnUpdateFramingForwardPhotoState);
				stateMachine.AddState(2, OnEnterFramingSelfiePhotoState, null, OnUpdateFramingSelfiePhotoState);
				stateMachine.AddState(3, OnEnterTakingPhotoState, OnExitTakingPhotoState, OnUpdateTakingPhotoState);
				stateMachine.AddState(4, OnEnterReviewingPhotoState, OnExitReviewingPhotoState, OnUpdateReviewingPhotoState);
				stateMachine.EnterState(0);
			}
		}

		public void EnableHudDialogContent(ScreenHUD hud)
		{
			if (hud != null)
			{
				hud.EnableCreationOverlay();
			}
		}

		public void DisableHudDialogContent(ScreenHUD hud)
		{
			if (hud != null)
			{
				hud.DisableCreationOverlay();
			}
		}

		public void AddHudToolDialog(ScreenHUD hud, Sprite icon, string text)
		{
			if (hud != null)
			{
				hud.AddCreationOverlayActionDialog(icon, text);
			}
		}

		public void AddHudControlsDialog(ScreenHUD hud, Sprite icon, string text)
		{
			if (hud != null)
			{
				hud.AddCreationOverlayControlsDialog(icon, text);
			}
		}

		public void SetHudLabel(ScreenHUD hud, string label)
		{
			if (hud != null)
			{
				hud.SetCreationOverlayActionLabel(label);
			}
		}

		private void ClearHudToolDialogs(ScreenHUD hud)
		{
			if (hud != null)
			{
				hud.ClearCreationOverlayActionDialogs();
			}
		}

		private void ClearHudControlsDialogs(ScreenHUD hud)
		{
			if (hud != null)
			{
				hud.ClearCreationOverlayControlsDialogs();
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Swing Melee Weapon Screen Controller", fileName = "SwingMeleeWeaponScreenController")]
	public class SwingMeleeWeaponScreenController : ScreenToolController
	{
		private enum State
		{
			IDLE,
			ATTACK_START,
			LIGHT_ATTACK,
			CHARGE_ATTACK,
			CHARGE_ATTACK_RELEASE,
			CHARGE_ATTACK_OUTRO,
			ATTACK_FINISHED
		}

		[Serializable]
		private class LightAttack
		{
			public PlayerAnimation Animation;

			public float NormalizedDamage;
		}

		[Serializable]
		private class ChargeAttack
		{
			public PlayerAnimation IntroAnimation;

			public PlayerAnimation LoopAnimation;

			public PlayerAnimation ReleaseAnimation;

			public PlayerAnimation OutroAnimation;

			public float NormalizedDamage = 1f;

			public float RequiredChargeDuration;
		}

		[Header("Light Attacks")]
		[SerializeField]
		private LightAttack[] lightAttackCombo;

		[SerializeField]
		private float maxLightAttackComboWindow = 0.33f;

		[SerializeField]
		private RecRoomAudioClip swingSFX;

		[Header("Light Attack Physics")]
		[SerializeField]
		private float lightAttackWalkSpeedMultiplier = 1f;

		[Header("Charge Attack")]
		[SerializeField]
		private bool supportsChargeAttack = true;

		[SerializeField]
		private ChargeAttack chargeAttack;

		[SerializeField]
		private RecRoomAudioClip chargeStartSFX;

		[SerializeField]
		private RecRoomAudioClip chargeReleaseSFX;

		[Header("Charge Attack Physics")]
		[SerializeField]
		private float chargeAttackWalkSpeedMultiplier;

		[SerializeField]
		private float chargeAttackReleaseWalkSpeedMultiplier;

		[Header("Misc")]
		[SerializeField]
		private float maximumAttackRadius = 3f;

		[Header("Breakables")]
		[SerializeField]
		private PlayerAnimation weaponBreakAnimation;

		[SerializeField]
		private RecRoomAudioClip weaponBreak2DAudio;

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig attackImpactCameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private ScreenInputHandler cachedInput;

		[NonSerialized]
		private MeleeWeapon cachedWeapon;

		[NonSerialized]
		private bool isInitialized;

		[NonSerialized]
		private float normalizedAttackDamage;

		[NonSerialized]
		private bool isBlockingSelf;

		[NonSerialized]
		private float attackStartTime;

		[NonSerialized]
		private int lightAttackComboIndex;

		[NonSerialized]
		private float lastLightAttackFinishTime;

		[NonSerialized]
		private float chargeStartTime;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => isBlockingSelf;

		private void LazyInitialize()
		{
			if (!isInitialized)
			{
				stateMachine.AddState(0, null, null, null);
				stateMachine.AddState(1, OnEnterAttackStartState, null, OnUpdateAttackStartState);
				stateMachine.AddState(2, OnEnterLightAttackState, OnExitLightAttackState, OnUpdateLightAttackState);
				stateMachine.AddState(3, OnEnterChargeAttackState, null, OnUpdateChargeAttackState);
				stateMachine.AddState(4, OnEnterChargeAttackReleaseState, OnExitChargeAttackReleaseState, OnUpdateChargeAttackReleaseState);
				stateMachine.AddState(5, OnEnterChargeAttackOutroState, OnExitChargeAttackOutroState, OnUpdateChargeAttackOutroState);
				stateMachine.AddState(6, null, null, null);
				isInitialized = true;
			}
		}

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return IsAnyInputDown(input);
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isBlockingSelf = true;
			cachedPlayerController = playerController;
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			if (genreController != null)
			{
				genreController.TryStartAutoTargetPointOfInterest(maximumAttackRadius);
			}
			cachedInput = input;
			cachedWeapon = tool.GetComponent<MeleeWeapon>();
			cachedWeapon.PostImpactEvent += OnWeaponImpact;
			stateMachine.EnterState(1);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (cachedWeapon == null || cachedWeapon.IsBroken)
			{
				AudioManager.Play2DSFX(weaponBreak2DAudio);
				if (weaponBreakAnimation != null && weaponBreakAnimation.AnimationAsset != null)
				{
					playerController.PlayUninterruptableAnimation(weaponBreakAnimation, restartIfAlreadyPlaying: true);
				}
				playerController.TryDropMainHandTool(player, tryPickupFromEquipSlot: true);
				return false;
			}
			if (!tool.IsHeld)
			{
				return false;
			}
			stateMachine.Update();
			return stateMachine.CurrentStateId != 6;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			stateMachine.EnterState(0);
			if (cachedPlayerController != null)
			{
				cachedPlayerController.RemoveWalkSpeedMultiplier(this);
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
				ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
				if (genreController != null)
				{
					genreController.TryStopAutoTargetPointOfInterest();
				}
				cachedPlayerController = null;
			}
			if (cachedWeapon != null)
			{
				cachedWeapon.StopManualSwing();
				cachedWeapon.ManualBlockingEnabled = false;
				cachedWeapon.PostImpactEvent -= OnWeaponImpact;
				cachedWeapon = null;
			}
			cachedInput = null;
			isBlockingSelf = false;
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1:
				AudioManager.Play2DSFX(swingSFX);
				component.StartManualSwing(normalizedAttackDamage);
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_2:
				component.StopManualSwing();
				isBlockingSelf = false;
				break;
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			if (input.UsingKeyboardMouse)
			{
				if (genreController != null && genreController.IsLockingOnToSomething)
				{
					hud.AddToolActionDialog(input.JumpButtonSprite, "Dodge");
				}
				else
				{
					hud.AddToolActionDialog(input.AimDownSightsButtonSprite, "Block / Lock On (Hold)");
				}
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Quick Attack (Click)");
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Charge Attack (Hold)");
			}
			else
			{
				if (genreController != null && genreController.IsLockingOnToSomething)
				{
					hud.AddToolActionDialog(input.JumpButtonSprite, "Dodge");
				}
				else
				{
					hud.AddToolActionDialog(input.AimDownSightsButtonSprite, "Block / Lock On (Hold)");
				}
				hud.AddToolActionDialog(input.SecondaryActionButtonSprite, "Quick Attack");
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Charge Attack (Hold)");
			}
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			LazyInitialize();
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			component.CalculateSwingingAutomatically = false;
			component.BlocksEnemyAttacksAutomatically = false;
			component.ManualBlockingEnabled = false;
			stateMachine.EnterState(0);
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			stateMachine.EnterState(0);
			MeleeWeapon component = tool.GetComponent<MeleeWeapon>();
			component.StopManualSwing();
			component.CalculateSwingingAutomatically = true;
			component.BlocksEnemyAttacksAutomatically = true;
			component.ManualBlockingEnabled = false;
		}

		private void OnEnterAttackStartState(ushort previousStateId, ushort previousSubStateId)
		{
			attackStartTime = UnityEngine.Time.time;
		}

		private void OnUpdateAttackStartState()
		{
			if (!supportsChargeAttack)
			{
				stateMachine.EnterState(2);
			}
			else if (cachedInput.UsingKeyboardMouse)
			{
				float num = UnityEngine.Time.time - attackStartTime;
				if (num >= 0.2f)
				{
					stateMachine.EnterState(3);
				}
				else if (!cachedInput.PrimaryMainHandActionButtonPressed)
				{
					stateMachine.EnterState(2);
				}
			}
			else if (cachedInput.PrimaryMainHandActionButtonPressed)
			{
				stateMachine.EnterState(3);
			}
			else if (cachedInput.SecondaryMainHandActionButtonPressed)
			{
				stateMachine.EnterState(2);
			}
			else
			{
				stateMachine.EnterState(6);
			}
		}

		private void OnEnterLightAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedWeapon.ManualBlockingEnabled = true;
			cachedPlayerController.AddWalkSpeedMultiplier(lightAttackWalkSpeedMultiplier, this);
			if (UnityEngine.Time.time - lastLightAttackFinishTime <= maxLightAttackComboWindow)
			{
				lightAttackComboIndex = (lightAttackComboIndex + 1) % lightAttackCombo.Length;
			}
			else
			{
				lightAttackComboIndex = 0;
			}
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			cachedPlayerController.PlayAnimation(lightAttack.Animation);
			normalizedAttackDamage = lightAttack.NormalizedDamage;
		}

		private void OnUpdateLightAttackState()
		{
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			if (!cachedPlayerController.IsAnimationPlaying(lightAttack.Animation))
			{
				stateMachine.EnterState(6);
			}
		}

		private void OnExitLightAttackState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedWeapon.ManualBlockingEnabled = false;
			lastLightAttackFinishTime = UnityEngine.Time.time;
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			AudioManager.Play2DSFX(chargeStartSFX);
			normalizedAttackDamage = chargeAttack.NormalizedDamage;
			chargeStartTime = UnityEngine.Time.time;
			cachedPlayerController.AddWalkSpeedMultiplier(chargeAttackWalkSpeedMultiplier, this);
			if (chargeAttack.IntroAnimation != null && chargeAttack.IntroAnimation.AnimationAsset != null)
			{
				cachedPlayerController.PlayAnimation(chargeAttack.IntroAnimation);
			}
			else
			{
				cachedPlayerController.PlayLoopingAnimation(chargeAttack.LoopAnimation);
			}
		}

		private void OnUpdateChargeAttackState()
		{
			float num = UnityEngine.Time.time - chargeStartTime;
			if (!cachedInput.PrimaryMainHandActionButtonPressed)
			{
				if (num >= chargeAttack.RequiredChargeDuration)
				{
					stateMachine.EnterState(4);
				}
				else
				{
					stateMachine.EnterState(6);
				}
			}
			else if (chargeAttack.IntroAnimation != null && chargeAttack.IntroAnimation.AnimationAsset != null && !cachedPlayerController.IsAnimationPlaying(chargeAttack.IntroAnimation))
			{
				cachedPlayerController.PlayLoopingAnimation(chargeAttack.LoopAnimation);
			}
		}

		private void OnEnterChargeAttackReleaseState(ushort previousStateId, ushort previousSubStateId)
		{
			AudioManager.Play2DSFX(chargeReleaseSFX);
			cachedWeapon.ManualBlockingEnabled = true;
			normalizedAttackDamage = 1f;
			cachedPlayerController.AddWalkSpeedMultiplier(chargeAttackReleaseWalkSpeedMultiplier, this);
			cachedPlayerController.PlayAnimation(chargeAttack.ReleaseAnimation);
		}

		private void OnUpdateChargeAttackReleaseState()
		{
			if (!cachedPlayerController.IsAnimationPlaying(chargeAttack.ReleaseAnimation))
			{
				if (chargeAttack.OutroAnimation != null && chargeAttack.OutroAnimation.AnimationAsset != null)
				{
					stateMachine.EnterState(5);
				}
				else
				{
					stateMachine.EnterState(6);
				}
			}
		}

		private void OnExitChargeAttackReleaseState(ushort nextStateId, ushort nextSubStateId)
		{
			if (nextStateId != 5)
			{
				cachedWeapon.ManualBlockingEnabled = false;
			}
		}

		private void OnEnterChargeAttackOutroState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedPlayerController.PlayAnimation(chargeAttack.OutroAnimation);
		}

		private void OnUpdateChargeAttackOutroState()
		{
			if (!cachedPlayerController.IsAnimationPlaying(chargeAttack.OutroAnimation))
			{
				stateMachine.EnterState(6);
			}
		}

		private void OnExitChargeAttackOutroState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedWeapon.ManualBlockingEnabled = false;
		}

		private bool IsAnyInputDown(ScreenInputHandler inputHandler)
		{
			if (inputHandler.UsingKeyboardMouse)
			{
				return inputHandler.PrimaryMainHandActionButtonPressed;
			}
			return inputHandler.PrimaryMainHandActionButtonPressed || inputHandler.SecondaryMainHandActionButtonDown;
		}

		private void OnWeaponImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
		{
			CameraShake.SetShake(attackImpactCameraShake);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Swing Paddle Screen Controller", fileName = "SwingPaddleScreenController")]
	public class SwingPaddleScreenController : ScreenToolController
	{
		[Header("Animation")]
		[SerializeField]
		private PlayerAnimation primarySwing;

		[SerializeField]
		private PlayerAnimation secondarySwing;

		[Header("Movement Settings")]
		[SerializeField]
		private float swingingWalkSpeedMultiplier;

		[SerializeField]
		private float swingingCameraSpeedMultiplier;

		private bool isSecondary;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return input.PrimaryMainHandActionButtonDown || (input.SecondaryMainHandActionButtonDown && secondarySwing.AnimationAsset != null);
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isSecondary = input.SecondaryMainHandActionButtonDown && secondarySwing.AnimationAsset != null;
			playerController.PlayAnimation((!isSecondary) ? primarySwing : secondarySwing);
			playerController.AddWalkSpeedMultiplier(swingingWalkSpeedMultiplier, this);
			playerController.AddCameraSpeedMultiplier(swingingCameraSpeedMultiplier, this);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			return playerController.IsAnimationPlaying((!isSecondary) ? primarySwing : secondarySwing);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			playerController.RemoveWalkSpeedMultiplier(this);
			playerController.RemoveCameraSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Swing");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Throw Bowling Ball Screen Controller", fileName = "ThrowBowlingBallScreenController")]
	public class ThrowBowlingBallScreenController : ScreenToolController
	{
		[Header("Bowl Animation")]
		[SerializeField]
		private PlayerAnimation bowlWindUpAnimation;

		[SerializeField]
		private PlayerAnimation bowlReleaseAnimation;

		[Header("Physics Curves")]
		[SerializeField]
		private AnimationCurve windUpSpeedCurve;

		[SerializeField]
		private AnimationCurve releaseSpeedCurve;

		[Header("Throw Physics")]
		[SerializeField]
		private float minThrowSpeed = 3f;

		[SerializeField]
		private float maxThrowSpeed = 10f;

		[SerializeField]
		private float maxWalkSpeedThrowSpeedMultiplier = 1.5f;

		[SerializeField]
		private float maxThrowWalkSpeed = 4f;

		[Header("Walking Physics")]
		[SerializeField]
		private float walkSpeedMultiplier = 0.5f;

		[SerializeField]
		private float walkDecelerationMultiplier = 0.25f;

		[Header("Crosshair Settings")]
		[SerializeField]
		private float minChargeCrosshairDistance = 0.03f;

		[SerializeField]
		private float maxChargeCrosshairDistance = 0.01f;

		[SerializeField]
		private AnimationCurve windUpCrosshairDistanceCurve;

		[SerializeField]
		private AnimationCurve releaseCrosshairDistanceCurve;

		private bool isRunning;

		private bool hasThrown;

		private bool isWinding;

		private bool isValidThrow;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return input.PrimaryMainHandActionButtonDown || input.PrimaryMainHandActionButtonPressed;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isRunning = true;
			hasThrown = false;
			isWinding = true;
			isValidThrow = false;
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplier, this);
			playerController.AddWalkDecelerationMultiplier(walkDecelerationMultiplier, this);
			playerController.PlayAnimation(bowlWindUpAnimation);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (isWinding && !playerController.IsAnimationPlaying(bowlWindUpAnimation))
			{
				isWinding = false;
				playerController.PlayAnimation(bowlReleaseAnimation);
			}
			if ((input.PrimaryMainHandActionButtonUp || !input.PrimaryMainHandActionButtonPressed) && !hasThrown)
			{
				hasThrown = true;
				if (!isValidThrow)
				{
					ThrowToolWithHandVelocity(playerController, player, playerController.LeftHandVelocity, playerController.RightHandVelocity);
				}
				else
				{
					float throwPhysics = GetThrowPhysics(playerController);
					float normalizedWalkSpeed = GetNormalizedWalkSpeed(player);
					float num = Mathf.Lerp(1f, maxWalkSpeedThrowSpeedMultiplier, normalizedWalkSpeed);
					throwPhysics *= num;
					ThrowToolWithSpeed(playerController, player, throwPhysics);
				}
			}
			return isWinding || playerController.IsAnimationPlaying(bowlReleaseAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			isRunning = false;
			playerController.RemoveWalkSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.THROW_TOOL:
				ThrowToolWithHandVelocity(playerController, player, leftHandVelocity, rightHandVelocity);
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1:
				isValidThrow = false;
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_2:
				isValidThrow = true;
				break;
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			float crosshairDistance = GetCrosshairDistance(playerController);
			playerController.CursorSystem.SetCrosshairTickDistance(hud, crosshairDistance);
			playerController.CursorSystem.ShowCrosshair(hud, (ScreenHUD.CrosshairTickMasks)28);
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Charge Roll (Hold)");
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Roll (Release)");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			isRunning = false;
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			playerController.ResetCursor(hud);
			playerController.RemoveWalkDecelerationMultiplier(this);
		}

		private void ThrowToolWithHandVelocity(ScreenPlayerController playerController, Player player, Vector3 leftHandVelocity, Vector3 rightHandVelocity)
		{
			PlayerHand mainHand = playerController.GetMainHand(player);
			Vector3 linearVelocity = rightHandVelocity;
			if (mainHand.Type == PlayerHand.HandType.Left)
			{
				linearVelocity = leftHandVelocity;
			}
			playerController.TryThrowMainHandTool(player, linearVelocity);
		}

		private void ThrowToolWithSpeed(ScreenPlayerController playerController, Player player, float throwSpeed)
		{
			playerController.TryThrowMainHandTool(player, throwSpeed);
		}

		private float GetNormalizedWalkSpeed(Player player)
		{
			Vector3 velocity = player.PlayerWalking.Velocity;
			Vector3 forward = player.TrackingSpace.RigidbodyEx.TargetTransform.forward;
			Vector3 vector = Vector3.Project(velocity, forward);
			Vector3 vector2 = velocity - vector;
			if (Vector3.Dot(vector, forward) <= 0f)
			{
				vector = Vector3.zero;
			}
			float magnitude = (vector + vector2).magnitude;
			return Mathf.InverseLerp(0f, maxThrowWalkSpeed, magnitude);
		}

		private float GetThrowPhysics(ScreenPlayerController playerController)
		{
			if (!isRunning)
			{
				return 0f;
			}
			float num = 0f;
			float activeAnimationNormalizedTimeElapsed = playerController.GetActiveAnimationNormalizedTimeElapsed();
			return Mathf.Lerp(t: (!isWinding) ? releaseSpeedCurve.Evaluate(activeAnimationNormalizedTimeElapsed) : windUpSpeedCurve.Evaluate(activeAnimationNormalizedTimeElapsed), a: minThrowSpeed, b: maxThrowSpeed);
		}

		private float GetCrosshairDistance(ScreenPlayerController playerController)
		{
			float num = 0f;
			if (!isRunning)
			{
				num = windUpCrosshairDistanceCurve.Evaluate(0f);
			}
			else
			{
				float activeAnimationNormalizedTimeElapsed = playerController.GetActiveAnimationNormalizedTimeElapsed();
				num = ((!isWinding) ? releaseCrosshairDistanceCurve.Evaluate(activeAnimationNormalizedTimeElapsed) : windUpCrosshairDistanceCurve.Evaluate(activeAnimationNormalizedTimeElapsed));
			}
			return Mathf.Lerp(minChargeCrosshairDistance, maxChargeCrosshairDistance, num);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Throw Disc Golf Disc Screen Controller", fileName = "ThrowDiscGolfDiscScreenController")]
	public class ThrowDiscGolfDiscScreenController : ScreenToolController
	{
		[Header("Charge Animation")]
		[SerializeField]
		private BlendedPlayerAnimation chargeAnimationBlend;

		[Header("Throw Animation")]
		[SerializeField]
		private PlayerAnimation lightThrowAnimation;

		[SerializeField]
		private PlayerAnimation heavyThrowAnimation;

		[Header("Charging")]
		[SerializeField]
		private float maxChargeDuration = 1.5f;

		[SerializeField]
		private AnimationCurve chargeCurve;

		[Header("Throws")]
		[SerializeField]
		private float minHeavyThrowCharge = 0.5f;

		[SerializeField]
		private AnimationCurve throwSpeedCurve;

		[SerializeField]
		private AnimationCurve throwAngularSpeedNormalizedCurve;

		[Header("Curve")]
		[SerializeField]
		private AnimationCurve throwCurveNormalizedAngleCurve;

		[SerializeField]
		private float maxThrowCurveAngle = 30f;

		[Header("Movement Settings")]
		[SerializeField]
		private float walkSpeedMultiplierWhileCharging = 0.5f;

		[SerializeField]
		private float cameraSpeedMultiplierWhileCharging = 0.5f;

		private bool isCharging;

		private float chargeStartTime;

		private float chargeT;

		private float maxCurveInput;

		private bool isLightThrow = true;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return input.PrimaryMainHandActionButtonDown || input.PrimaryMainHandActionButtonPressed;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isCharging = true;
			chargeStartTime = UnityEngine.Time.time;
			chargeT = 0f;
			chargeAnimationBlend.AnimationAsset.SetBlendParameter(chargeT);
			isLightThrow = true;
			maxCurveInput = 0f;
			playerController.PlayLoopingAnimation(chargeAnimationBlend);
			playerController.AddWalkSpeedMultiplier(walkSpeedMultiplierWhileCharging, this);
			playerController.AddCameraSpeedMultiplier(cameraSpeedMultiplierWhileCharging, this);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (isCharging)
			{
				if (!tool.IsHeld)
				{
					return false;
				}
				float time = Mathf.InverseLerp(chargeStartTime, chargeStartTime + maxChargeDuration, UnityEngine.Time.time);
				chargeT = chargeCurve.Evaluate(time);
				chargeAnimationBlend.AnimationAsset.SetBlendParameter(chargeT);
				if (input.PrimaryMainHandActionButtonUp || !input.PrimaryMainHandActionButtonPressed)
				{
					UpdateCurveInput(input);
					isCharging = false;
					isLightThrow = chargeT < minHeavyThrowCharge;
					playerController.PlayUninterruptableAnimation((!isLightThrow) ? heavyThrowAnimation : lightThrowAnimation);
				}
				return true;
			}
			UpdateCurveInput(input);
			return playerController.IsAnimationPlaying((!isLightThrow) ? heavyThrowAnimation : lightThrowAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			playerController.RemoveWalkSpeedMultiplier(this);
			playerController.RemoveCameraSpeedMultiplier(this);
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			if (animationEvent == PlayerAnimationEvent.AnimationEventType.THROW_TOOL)
			{
				float throwSpeed = throwSpeedCurve.Evaluate(chargeT);
				float num = throwAngularSpeedNormalizedCurve.Evaluate(chargeT);
				Vector3 angularVelocity = tool.transform.up * num * DiscGolfDisc.MaxAngularVelocity;
				Vector3 forward = tool.transform.forward;
				Vector3 normalized = Vector3.ProjectOnPlane(forward, camera.transform.up).normalized;
				float curveAngle = GetCurveAngle();
				Quaternion quaternion = Quaternion.AngleAxis(curveAngle, camera.transform.forward);
				Vector3 upwards = quaternion * camera.transform.up;
				tool.transform.rotation = Quaternion.LookRotation(normalized, upwards);
				playerController.TryThrowMainHandTool(player, throwSpeed, angularVelocity);
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Throw");
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			playerController.AddGameplayCursorVisibilityRestriction(this);
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			playerController.RemoveGameplayCursorVisibilityRestriction(this);
		}

		private void UpdateCurveInput(ScreenInputHandler input)
		{
			float x = input.CameraAxisGamepad.x;
			if (Mathf.Abs(x) > Mathf.Abs(maxCurveInput))
			{
				maxCurveInput = x;
			}
		}

		private float GetCurveAngle()
		{
			float time = Mathf.Abs(maxCurveInput);
			return throwCurveNormalizedAngleCurve.Evaluate(time) * maxThrowCurveAngle * -1f * Mathf.Sign(maxCurveInput);
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Throw Tool Screen Controller", fileName = "ThrowToolScreenController")]
	public class ThrowToolScreenController : ScreenToolController
	{
		[Header("Throw Charge Animation")]
		[SerializeField]
		private PlayerAnimation throwChargeAnimation;

		[Header("Throw Animation")]
		[SerializeField]
		private PlayerAnimation throwAnimation;

		[Header("Physics Settings")]
		[SerializeField]
		private float throwSpeed = 12f;

		[SerializeField]
		private float throwAngularSpeed = 360f;

		[SerializeField]
		private bool throwTowardsGazeTarget = true;

		private bool isCharging;

		private bool usingPrecisionAim;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => true;

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			if (usingPrecisionAim)
			{
				requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
				return true;
			}
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return IsThrowButtonPressed(tool, input);
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isCharging = true;
			usingPrecisionAim = false;
			playerController.PlayLoopingAnimation(throwChargeAnimation);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (isCharging)
			{
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
				ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
				usingPrecisionAim = genreController == null || !genreController.HasLockedOnPointOfInterest;
				if (IsThrowButtonReleased(tool, input))
				{
					playerController.PlayUninterruptableAnimation(throwAnimation, restartIfAlreadyPlaying: true);
					isCharging = false;
				}
				return true;
			}
			return playerController.IsAnimationPlaying(throwAnimation);
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			isCharging = false;
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.THROW_TOOL:
				ThrowTool(playerController, player, tool, leftHandVelocity, rightHandVelocity);
				break;
			case PlayerAnimationEvent.AnimationEventType.DROP_TOOL:
				DropTool(playerController, tool, player);
				break;
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (tool.IsScreensOffHand)
			{
				hud.AddToolActionDialog(input.OffHandActionButtonSprite, "Throw");
			}
			else
			{
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Throw");
			}
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			Grenade component = tool.GetComponent<Grenade>();
			if (component != null)
			{
				component.AutomaticallyArmOnNextRelease = false;
			}
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		private bool IsThrowButtonPressed(Tool tool, ScreenInputHandler input)
		{
			if (tool.IsScreensOffHand)
			{
				return input.OffHandActionButtonDown || input.OffHandActionButtonPressed;
			}
			return input.PrimaryMainHandActionButtonDown || input.PrimaryMainHandActionButtonPressed;
		}

		private bool IsThrowButtonReleased(Tool tool, ScreenInputHandler input)
		{
			if (tool.IsScreensOffHand)
			{
				return input.OffHandActionButtonUp || !input.OffHandActionButtonPressed;
			}
			return input.PrimaryMainHandActionButtonUp || !input.PrimaryMainHandActionButtonPressed;
		}

		private void ThrowTool(ScreenPlayerController playerController, Player player, Tool tool, Vector3 leftHandVelocity, Vector3 rightHandVelocity)
		{
			Vector3 angularVelocity = UnityEngine.Random.onUnitSphere * throwAngularSpeed * ((float)Math.PI / 180f);
			if (throwTowardsGazeTarget)
			{
				ThrowToolAtGazeTarget(playerController, player, tool, angularVelocity);
			}
			else
			{
				ThrowToolWithAnimationVelocity(playerController, player, tool, leftHandVelocity, rightHandVelocity, angularVelocity);
			}
			Grenade grenade = ((!(tool != null)) ? null : tool.GetComponent<Grenade>());
			if (grenade != null && grenade.hasAuthority)
			{
				grenade.AuthorityStartCooking();
			}
		}

		private void ThrowToolWithAnimationVelocity(ScreenPlayerController playerController, Player player, Tool tool, Vector3 leftHandVelocity, Vector3 rightHandVelocity, Vector3 angularVelocity)
		{
			bool isScreensOffHand = tool.IsScreensOffHand;
			PlayerHand playerHand = ((!isScreensOffHand) ? playerController.GetMainHand(player) : playerController.GetOffHand(player));
			Vector3 normalized = ((playerHand.Type != PlayerHand.HandType.Left) ? rightHandVelocity : leftHandVelocity).normalized;
			Vector3 linearVelocity = normalized * throwSpeed;
			if (isScreensOffHand)
			{
				playerController.TryThrowOffHandTool(player, linearVelocity, angularVelocity);
			}
			else
			{
				playerController.TryThrowMainHandTool(player, linearVelocity, angularVelocity);
			}
		}

		private void ThrowToolAtGazeTarget(ScreenPlayerController playerController, Player player, Tool tool, Vector3 angularVelocity)
		{
			if (tool.IsScreensOffHand)
			{
				playerController.TryThrowOffHandTool(player, throwSpeed, angularVelocity);
			}
			else
			{
				playerController.TryThrowMainHandTool(player, throwSpeed, angularVelocity);
			}
		}

		private void DropTool(ScreenPlayerController playerController, Tool tool, Player player)
		{
			if (tool.IsScreensOffHand)
			{
				playerController.TryDropOffHandTool(player);
			}
			else
			{
				playerController.TryDropMainHandTool(player);
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Whip Screen Controller", fileName = "WhipScreenController")]
	public class WhipScreenController : ScreenToolController
	{
		private enum State
		{
			IDLE,
			ATTACK_START,
			LIGHT_ATTACK_UNCOIL,
			LIGHT_ATTACK_CRACK,
			CHARGE_ATTACK,
			CHARGE_ATTACK_UNCOIL,
			CHARGE_ATTACK_CRACK,
			ATTACK_FINISHED
		}

		[Serializable]
		private class LightAttack
		{
			public PlayerAnimation UncoilAnimation;

			public PlayerAnimation UncoiledLoopAnimation;

			public PlayerAnimation CrackAnimation;

			public float NormalizedDamage;
		}

		[Header("Light Attacks")]
		[SerializeField]
		private LightAttack[] lightAttackCombo;

		[SerializeField]
		private float maxLightAttackComboWindow = 0.33f;

		[SerializeField]
		private float lightAttackWalkSpeedMultiplier = 1f;

		[SerializeField]
		private float lightAttackUncoilSpeed = 15f;

		[SerializeField]
		private bool lightAttackWhipPopperUsesGravity;

		[Header("Charge Attack")]
		[SerializeField]
		private PlayerAnimation chargeAttackLoopAnimation;

		[SerializeField]
		private PlayerAnimation chargeAttackUncoilIntroAnimation;

		[SerializeField]
		private PlayerAnimation chargeAttackUncoilLoopAnimation;

		[SerializeField]
		private PlayerAnimation chargeAttackCrackAnimation;

		[SerializeField]
		private float chargeAttackWalkSpeedMultiplier = 1f;

		[SerializeField]
		private float chargeAttackReleaseWalkSpeedMultiplier = 1f;

		[SerializeField]
		private float chargeAttackUncoilSpeed = 15f;

		[SerializeField]
		private bool chargeAttackWhipPopperUsesGravity;

		[Header("Camera Shake")]
		[SerializeField]
		private CameraShake.CameraShakeConfig attackImpactCameraShake = CameraShake.CameraShakeConfig.DefaultMediumShake;

		[Header("Uncoiling")]
		[SerializeField]
		private float minUncoilingDistance = 3f;

		[SerializeField]
		private float maxUncoilingDistance = 7f;

		[Header("Cracking")]
		[SerializeField]
		private float minCrackSpeed = 5f;

		[SerializeField]
		private float maxCrackSpeed = 10f;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private Player cachedPlayer;

		[NonSerialized]
		private ScreenInputHandler cachedInput;

		[NonSerialized]
		private Whip cachedWhip;

		[NonSerialized]
		private bool isInitialized;

		[NonSerialized]
		private float normalizedAttackDamage;

		[NonSerialized]
		private bool isBlockingSelf;

		[NonSerialized]
		private bool isCharging;

		[NonSerialized]
		private float attackStartTime;

		[NonSerialized]
		private int lightAttackComboIndex;

		[NonSerialized]
		private float lastLightAttackFinishTime;

		[NonSerialized]
		private float lastUncoilStartTime;

		[NonSerialized]
		private float lastUncoilDuration;

		[NonSerialized]
		private bool isUncoiling;

		[NonSerialized]
		private int lastLightCrackFrame;

		[NonSerialized]
		private int lastChargeCrackFrame;

		public override bool PlayerMovementAllowed => true;

		public override bool IsBlockingOthers => true;

		public override bool IsBlockingSelf => isBlockingSelf;

		private void LazyInitialize()
		{
			if (!isInitialized)
			{
				stateMachine.AddState(0, null, null, null);
				stateMachine.AddState(1, OnEnterAttackStartState, null, OnUpdateAttackStartState);
				stateMachine.AddState(2, OnEnterLightAttackUncoilState, null, OnUpdateLightAttackUncoilState);
				stateMachine.AddState(3, OnEnterLightAttackCrackState, OnExitLightAttackCrackState, OnUpdateLightAttackCrackState);
				stateMachine.AddState(4, OnEnterChargeAttackState, null, OnUpdateChargeAttackState);
				stateMachine.AddState(5, OnEnterChargeAttackUncoilState, null, OnUpdateChargeAttackUncoilState);
				stateMachine.AddState(6, OnEnterChargeAttackCrackState, OnExitChargeAttackCrackState, OnUpdateChargeAttackCrackState);
				stateMachine.AddState(7, null, null, null);
				isInitialized = true;
			}
		}

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			if (isCharging)
			{
				requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.THIRD_PERSON_SHOOTER;
			}
			else
			{
				requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			}
			return true;
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return IsAnyInputDown(input);
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			isBlockingSelf = true;
			isCharging = false;
			cachedPlayerController = playerController;
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			if (genreController != null)
			{
				genreController.TryStartAutoTargetPointOfInterest(minUncoilingDistance + 1f);
			}
			cachedPlayer = player;
			cachedInput = input;
			cachedWhip = tool.GetComponent<Whip>();
			cachedWhip.PostImpactEvent += OnWeaponImpact;
			stateMachine.EnterState(1);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (!tool.IsHeld)
			{
				return false;
			}
			stateMachine.Update();
			return stateMachine.CurrentStateId != 7;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			stateMachine.EnterState(0);
			StartCrack(isAiming: false);
			if (cachedPlayerController != null)
			{
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
				ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
				if (genreController != null)
				{
					genreController.TryStopAutoTargetPointOfInterest();
				}
				cachedPlayerController.RemoveWalkSpeedMultiplier(this);
				cachedPlayerController.RemovePlayerRotationFaceVelocityRestriction(this);
				cachedPlayerController = null;
			}
			if (cachedWhip != null)
			{
				cachedWhip.PostImpactEvent -= OnWeaponImpact;
				cachedWhip = null;
			}
			cachedPlayer = null;
			cachedInput = null;
			isBlockingSelf = false;
			isCharging = false;
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
			bool isAiming = isCharging;
			switch (animationEvent)
			{
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_1:
				StartUncoiling(isAiming);
				break;
			case PlayerAnimationEvent.AnimationEventType.CUSTOM_ACTION_2:
				StartCrack(isAiming);
				break;
			}
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
			ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
			if (input.UsingKeyboardMouse)
			{
				if (genreController != null && genreController.IsLockingOnToSomething)
				{
					hud.AddToolActionDialog(input.JumpButtonSprite, "Dodge");
				}
				else
				{
					hud.AddToolActionDialog(input.AimDownSightsButtonSprite, "Block / Lock On (Hold)");
				}
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Quick Attack (Click)");
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Aim Attack (Hold)");
			}
			else
			{
				if (genreController != null && genreController.IsLockingOnToSomething)
				{
					hud.AddToolActionDialog(input.JumpButtonSprite, "Dodge");
				}
				else
				{
					hud.AddToolActionDialog(input.AimDownSightsButtonSprite, "Block / Lock On (Hold)");
				}
				hud.AddToolActionDialog(input.SecondaryActionButtonSprite, "Quick Attack");
				hud.AddToolActionDialog(input.PrimaryActionButtonSprite, "Aim Attack (Hold)");
			}
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			LazyInitialize();
			Whip component = tool.GetComponent<Whip>();
			component.GestureWhipping = false;
			component.HasOverridenTargetPoint = false;
			stateMachine.EnterState(0);
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			stateMachine.EnterState(0);
			Whip component = tool.GetComponent<Whip>();
			component.DisablePopperGravity = false;
			component.GestureWhipping = true;
			component.HasOverridenTargetPoint = false;
		}

		private void OnEnterAttackStartState(ushort previousStateId, ushort previousSubStateId)
		{
			attackStartTime = UnityEngine.Time.time;
		}

		private void OnUpdateAttackStartState()
		{
			if (cachedInput.UsingKeyboardMouse)
			{
				float num = UnityEngine.Time.time - attackStartTime;
				if (num >= 0.2f)
				{
					stateMachine.EnterState(4);
				}
				else if (!cachedInput.PrimaryMainHandActionButtonPressed)
				{
					stateMachine.EnterState(2);
				}
			}
			else if (cachedInput.SecondaryMainHandActionButtonPressed)
			{
				stateMachine.EnterState(2);
			}
			else
			{
				stateMachine.EnterState(4);
			}
		}

		private void OnEnterLightAttackUncoilState(ushort previousStateId, ushort previousSubStateId)
		{
			cachedWhip.DisablePopperGravity = !lightAttackWhipPopperUsesGravity;
			cachedPlayerController.AddPlayerRotationFaceVelocityRestriction(this);
			cachedPlayerController.AddWalkSpeedMultiplier(lightAttackWalkSpeedMultiplier, this);
			if (UnityEngine.Time.time - lastLightAttackFinishTime <= maxLightAttackComboWindow)
			{
				lightAttackComboIndex = (lightAttackComboIndex + 1) % lightAttackCombo.Length;
			}
			else
			{
				lightAttackComboIndex = 0;
			}
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			cachedPlayerController.PlayAnimation(lightAttack.UncoilAnimation);
			normalizedAttackDamage = lightAttack.NormalizedDamage;
			isUncoiling = false;
		}

		private void OnUpdateLightAttackUncoilState()
		{
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			if (isUncoiling)
			{
				if (!cachedPlayerController.IsAnimationPlaying(lightAttack.UncoilAnimation) && !cachedPlayerController.IsAnimationPlaying(lightAttack.UncoiledLoopAnimation))
				{
					cachedPlayerController.PlayLoopingAnimation(lightAttack.UncoiledLoopAnimation);
				}
				float num = UnityEngine.Time.time - lastUncoilStartTime;
				if (num >= lastUncoilDuration || cachedWhip.PopperHitSomething)
				{
					isUncoiling = false;
					stateMachine.EnterState(3);
				}
			}
		}

		private void OnEnterLightAttackCrackState(ushort previousStateId, ushort previousSubStateId)
		{
			lastLightCrackFrame = UnityEngine.Time.frameCount;
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			cachedPlayerController.PlayAnimation(lightAttack.CrackAnimation);
		}

		private void OnUpdateLightAttackCrackState()
		{
			LightAttack lightAttack = lightAttackCombo[lightAttackComboIndex];
			if (!cachedPlayerController.IsAnimationPlaying(lightAttack.CrackAnimation) && UnityEngine.Time.frameCount != lastLightCrackFrame)
			{
				stateMachine.EnterState(7);
			}
		}

		private void OnExitLightAttackCrackState(ushort nextStateId, ushort nextSubStateId)
		{
			cachedPlayerController.RemovePlayerRotationFaceVelocityRestriction(this);
			lastLightAttackFinishTime = UnityEngine.Time.time;
			isBlockingSelf = false;
		}

		private void OnEnterChargeAttackState(ushort previousStateId, ushort previousSubStateId)
		{
			isCharging = true;
			normalizedAttackDamage = 1f;
			cachedWhip.DisablePopperGravity = !chargeAttackWhipPopperUsesGravity;
			cachedPlayerController.AddWalkSpeedMultiplier(chargeAttackWalkSpeedMultiplier, this);
			cachedPlayerController.PlayLoopingAnimation(chargeAttackLoopAnimation);
		}

		private void OnUpdateChargeAttackState()
		{
			if (!cachedInput.PrimaryMainHandActionButtonPressed)
			{
				stateMachine.EnterState(5);
			}
		}

		private void OnEnterChargeAttackUncoilState(ushort previousStateId, ushort previousSubStateId)
		{
			normalizedAttackDamage = 1f;
			cachedPlayerController.AddWalkSpeedMultiplier(chargeAttackReleaseWalkSpeedMultiplier, this);
			cachedPlayerController.PlayAnimation(chargeAttackUncoilIntroAnimation);
		}

		private void OnUpdateChargeAttackUncoilState()
		{
			if (isUncoiling)
			{
				if (!cachedPlayerController.IsAnimationPlaying(chargeAttackUncoilIntroAnimation) && !cachedPlayerController.IsAnimationPlaying(chargeAttackUncoilLoopAnimation))
				{
					cachedPlayerController.PlayLoopingAnimation(chargeAttackUncoilLoopAnimation);
				}
				float num = UnityEngine.Time.time - lastUncoilStartTime;
				if (num >= lastUncoilDuration || cachedWhip.PopperHitSomething || cachedInput.PrimaryMainHandActionButtonDown)
				{
					isUncoiling = false;
					stateMachine.EnterState(6);
				}
			}
		}

		private void OnEnterChargeAttackCrackState(ushort previousStateId, ushort previousSubStateId)
		{
			lastChargeCrackFrame = UnityEngine.Time.frameCount;
			cachedPlayerController.PlayAnimation(chargeAttackCrackAnimation);
		}

		private void OnUpdateChargeAttackCrackState()
		{
			if (!cachedPlayerController.IsAnimationPlaying(chargeAttackCrackAnimation) && UnityEngine.Time.frameCount != lastChargeCrackFrame)
			{
				stateMachine.EnterState(7);
			}
		}

		private void OnExitChargeAttackCrackState(ushort nextStateId, ushort nextSubStateId)
		{
			isCharging = false;
		}

		private bool IsAnyInputDown(ScreenInputHandler inputHandler)
		{
			if (inputHandler.UsingKeyboardMouse)
			{
				return inputHandler.PrimaryMainHandActionButtonDown;
			}
			return inputHandler.PrimaryMainHandActionButtonDown || inputHandler.SecondaryMainHandActionButtonDown;
		}

		private void OnWeaponImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
		{
			CameraShake.SetShake(attackImpactCameraShake);
		}

		private Vector3 GetWhipDirection(ScreenPlayerController playerController, Player player, Whip whip, bool isAiming)
		{
			Vector3 targetPosition = whip.Tool.RigidbodyEx.targetPosition;
			Vector3 gazeTarget = playerController.GazeTarget;
			Vector3 vector = (gazeTarget - targetPosition).normalized;
			if (!isAiming)
			{
				Vector3 targetPosition2 = player.TrackingSpace.RigidbodyEx.targetPosition;
				Vector3 normalized = Vector3.ProjectOnPlane(gazeTarget - targetPosition2, Vector3.up).normalized;
				Vector3 vector2 = gazeTarget - targetPosition;
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
				ActionAdventureScreenPlayerGenre genreController = playerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
				if (genreController != null && genreController.HasNearbyPointOfInterest)
				{
					vector2 = genreController.NearbyPointOfInterestPosition - targetPosition;
				}
				vector2 = vector2.normalized;
				if (genreController != null && genreController.HasLockedOnPointOfInterest)
				{
					vector = vector2;
				}
				else if (Vector3.Dot(vector2, normalized) > 0f)
				{
					Vector3 normalized2 = Vector3.Cross(Vector3.up, vector).normalized;
					vector = Vector3.ProjectOnPlane(vector2, normalized2).normalized;
				}
			}
			return vector;
		}

		private void StartUncoiling(bool isAiming)
		{
			Vector3 whipDirection = GetWhipDirection(cachedPlayerController, cachedPlayer, cachedWhip, isAiming);
			float num = 1f;
			float num2 = 0f;
			if (isCharging)
			{
				num = chargeAttackUncoilSpeed;
				num2 = maxUncoilingDistance;
			}
			else
			{
				num = lightAttackUncoilSpeed;
				num2 = minUncoilingDistance;
				ScreenPlayerController.ScreenPlayerGenreType genreType = ScreenPlayerController.ScreenPlayerGenreType.ACTION_ADVENTURE;
				ActionAdventureScreenPlayerGenre genreController = cachedPlayerController.GetGenreController<ActionAdventureScreenPlayerGenre>(genreType);
				if (genreController != null && genreController.HasLockedOnPointOfInterest)
				{
					num2 = Mathf.Clamp(genreController.LockedOnPointOfInterestDistance, minUncoilingDistance, maxUncoilingDistance);
				}
			}
			lastUncoilDuration = num2 / num;
			cachedWhip.AuthorityManualUncoil(whipDirection * num);
			isUncoiling = true;
			lastUncoilStartTime = UnityEngine.Time.time;
		}

		private void StartCrack(bool isAiming)
		{
			Vector3 whipDirection = GetWhipDirection(cachedPlayerController, cachedPlayer, cachedWhip, isAiming);
			float num = Mathf.Lerp(minCrackSpeed, maxCrackSpeed, normalizedAttackDamage);
			cachedWhip.AuthorityManualCrack(-whipDirection * num);
		}
	}
}
