		Tool.PostPickupEvent += Tool_PostPickupEvent;
		Tool.HolderChangedEvent += Tool_HolderChangedEvent;
		Tool.VisibilityChangeEvent += Tool_VisibilityChangedEvent;
		shareCamStateMachine = new ManualUpdateStateMachine();
		shareCamStateMachine.AddState(4, OnEnterDisabledState, null, null);
		shareCamStateMachine.AddState(0, OnEnterActiveState, null, null);
		shareCamStateMachine.AddState(1, OnEnterPreviewState, null, null);
		shareCamStateMachine.AddState(3, OnEnterShareState, null, null);
		shareCamStateMachine.AddState(2, null, null, null);
		shareCamModeStateMachine = new ManualUpdateStateMachine();
		shareCamModeStateMachine.AddState(0, OnEnterPngState, null, null);
		shareCamModeStateMachine.AddState(1, OnEnterGifState, null, null);
		shareCamModeStateMachine.AddState(2, OnEnterMp4State, null, null);
		_tripodIsActive = new SynchronizedField<bool>(this, "SC_TRIPOD", defaultValue: false, SetterPermissionMode.AUTHORITY, OnTripodToggled);
		_timerIsActive = new SynchronizedField<bool>(this, "SC_TIMER", defaultValue: false, SetterPermissionMode.AUTHORITY, OnTimerToggled);
		_takePictureButtonPressed = new SynchronizedField<bool>(this, "SC_TPBP", defaultValue: false, SetterPermissionMode.AUTHORITY, OnTakePictureButtonPressedChange);
		_flashActivated = new SynchronizedField<bool>(this, "SC_FA", defaultValue: false, SetterPermissionMode.AUTHORITY, OnFlashValueChange);
		_isMenuVisibilityManagedInternally = new SynchronizedField<bool>(this, "SC_IMVMI", defaultValue: true, SetterPermissionMode.AUTHORITY);
		_isRecording = new SynchronizedField<bool>(this, "SC_IR", defaultValue: false, SetterPermissionMode.ANYONE, OnIsRecordingChanged);
		_screensExplicitCameraTransform = new SynchronizedField<bool, Vector3, Quaternion>(this, "SC_SCREENS_ECTR", defaultVal1: false, Vector3.zero, Quaternion.identity, SetterPermissionMode.AUTHORITY);
		animator = GetComponentInChildren<Animator>();
		frontCameraOutput = GetComponentInChildren<MirrorCameraOutput>();
		shareCamStateMachine.StateChangeEvent += ShareCamStateMachine_StateChangeEvent;
		shareCamModeStateMachine.StateChangeEvent += ShareCamStateMachine_StateChangeEvent;
	}

	private void Start()
	{
		if (isMine && gesturePreviewHudPrefab != null)
		{
			gesturePreviewHud = UnityEngine.Object.Instantiate(gesturePreviewHudPrefab);
			gesturePreviewHud.SetActive(value: false);
		}
		if (isMine && Tool != null && Tool.PlayerSpawnedEquipment != null && Tool.PlayerSpawnedEquipment.ToolPurpose == PlayerSpawnedEquipment.Purpose.Backpack)
		{
			ShareCameraUIFlow flowByType = Tool.Menu.GetFlowByType<ShareCameraUIFlow>();
			if (flowByType != null)
			{
				flowByType.Initialize(Tool.Menu);
				flowByType.InitializeShareCamera(this);
			}
			ShareCameraSettingsUIFlow flowByType2 = Tool.Menu.GetFlowByType<ShareCameraSettingsUIFlow>();
			if (flowByType2 != null)
			{
				flowByType2.Initialize(Tool.Menu);
				flowByType2.InitializeShareCamera(this);
			}
			Tool.PlayerSpawnedEquipment.CustomShouldUseLongerDistanceForBackpackCleanup = ShouldUseLongerDistanceForBackpackCleanup;
		}
		else if (Tool.MenuProjector != null)
		{
			Tool.MenuProjector.gameObject.SetActive(value: false);
		}
		CreationManager.ActiveSandboxResourcesChangedEvent += OnActiveSandboxResourcesChanged;
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
		backCamera.aspect = SixteenNineAspectRatio;
		frontCamera.aspect = SixteenNineAspectRatio;
		SwitchTextureResolution(ResolutionType.LOW);
		backCamera.depthTextureMode = DepthTextureMode.Depth;
		frontCamera.depthTextureMode = DepthTextureMode.Depth;
		backCamera.enabled = false;
		frontCamera.enabled = false;
		if (RecRoomSceneManager.IsInitialized && RecRoomSceneManager.Instance.SceneRenderingSettings != null)
		{
			RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(backCamera);
			RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(frontCamera);
		}
		shareCamStateMachine.Initialize(4);
		shareCamModeStateMachine.Initialize(0);
		currentVideoCapture = pngCapture;
		if (Tool != null)
		{
			Tool.InputDownEvent += OnInputDown;
			if (Tool.PlayerSpawnedEquipment != null)
			{
				playerName.text = Tool.PlayerSpawnedEquipment.SpawningPlayer.PlayerName;
			}
		}
		OnTimerToggled();
		OnTakePictureButtonPressedChange();
		OnFlashValueChange();
		if (isMine)
		{
			if (!DynamicUpdateManager.Instance.IsGroupRegistered("ShareCams"))
			{
				int[] array = new int[6];
				array[0] = 1;
				array[4] = 1;
				array[1] = 1;
				array[2] = 1;
				array[3] = 1;
				array[5] = 1;
				DynamicUpdateManager.Instance.RegisterGroup("ShareCams", screenRefreshCutoffDistance * screenRefreshCutoffDistance, callWhenDisabled: false, array);
			}
			if (Tool != null && Tool.SkinMapper != null)
			{
				Tool.SkinMapper.LocalApplyFavoriteSkin();
			}
			DynamicUpdateManager.Instance.RegisterObject("ShareCams", this, DynamicCostFunction, DynamicUpdate);
			shareCamStateMachine.EnterState(0);
		}
	}

	private void OnDisable()
	{
		spawnAndTakePictureCoroutine = null;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (currentVideoCapture != null)
		{
			currentVideoCapture.ExportFinishedEvent -= OnExportFinishedEvent;
		}
		if (Tool != null)
		{
			Tool.InputDownEvent -= OnInputDown;
			Tool.PostPickupEvent -= Tool_PostPickupEvent;
			Tool.HolderChangedEvent -= Tool_HolderChangedEvent;
			Tool.VisibilityChangeEvent -= Tool_VisibilityChangedEvent;
		}
		if (NetworkedSingletonMonoBehaviour<CreationManager>.Instance != null)
		{
			CreationManager.ActiveSandboxResourcesChangedEvent -= OnActiveSandboxResourcesChanged;
		}
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
		if (highResPictureTextureSet != null)
		{
			highResPictureTextureSet.DestroyTextures();
		}
		if (mediumResPictureTextureSet != null)
		{
			mediumResPictureTextureSet.DestroyTextures();
		}
		if (lowResPictureTextureSet != null)
		{
			lowResPictureTextureSet.DestroyTextures();
		}
		if (renderTexture != null)
		{
			renderTexture.Release();
		}
		Camera.onPostRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPostRender, new Camera.CameraCallback(ApplyOverlay));
		DynamicUpdateManager.Instance.UnregisterObject("ShareCams", this);
	}

