	public void UpdateFilter(CameraFilterConsumableItem consumable)
	{
		bool flag = overlaySetting.overlayTexture == null;
		if (consumable == null)
		{
			currentFilter = FilterType.NONE;
			filterVolume.sharedProfile = null;
			overlaySetting.overlayTexture = null;
			overlaySetting.overlayMaterial = null;
		}
		else
		{
			currentFilter = consumable.FilterType;
			filterVolume.sharedProfile = consumable.PostProcessProfile;
			overlaySetting.overlayTexture = consumable.OverlayTexture;
			overlaySetting.overlayMaterial = consumable.OverlayMaterial;
		}
		if (flag && overlaySetting.overlayTexture != null)
		{
			Camera.onPostRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPostRender, new Camera.CameraCallback(ApplyOverlay));
		}
		else if (!flag && overlaySetting.overlayTexture == null)
		{
			Camera.onPostRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPostRender, new Camera.CameraCallback(ApplyOverlay));
		}
	}

	private void ApplyOverlay(Camera cam)
	{
		if (overlaySetting.overlayTexture != null && (cam == backCamera || cam == frontCamera))
		{
			float num = (float)overlaySetting.overlayTexture.width / (float)overlaySetting.overlayTexture.height;
			float num2 = (float)cam.activeTexture.width / (float)cam.activeTexture.height;
			Vector2 vector;
			Vector2 vector2;
			if (num > num2)
			{
				float num3 = num / num2;
				vector = new Vector2(1f / num3, 1f);
				vector2 = new Vector2((num3 - 1f) / 2f / num3, 0f);
			}
			else
			{
				float num4 = num2 / num;
				vector = new Vector2(1f, 1f / num4);
				vector2 = new Vector2(0f, (num4 - 1f) / 2f / num4);
			}
			overlaySetting.overlayMaterial.SetVector(scaleOffsetTexID, new Vector4(vector.x, vector.y, vector2.x, vector2.y));
			Graphics.Blit(overlaySetting.overlayTexture, cam.activeTexture, overlaySetting.overlayMaterial);
		}
	}

	private void UpdateScreenTexture()
	{
		Texture texture = null;
		switch (shareCamStateMachine.CurrentStateId)
		{
		case 0:
			videoPlayer.enabled = false;
			texture = renderTexture;
			break;
		case 1:
		case 3:
			switch ((ShareCamMode)shareCamModeStateMachine.CurrentStateId)
			{
			case ShareCamMode.GIF:
				if (Tool.PlayerSpawnedEquipment.IsMine)
				{
					StartCoroutine(RunShowGif());
				}
				else
				{
					texture = lowResPictureTextureSet.MainTexture;
				}
				break;
			case ShareCamMode.MP4:
				if (Tool.PlayerSpawnedEquipment.IsMine)
				{
					videoPlayer.url = mp4Capture.CurrentVideoUrl;
					videoPlayer.Play();
				}
				else
				{
					texture = lowResPictureTextureSet.MainTexture;
				}
				break;
			default:
				texture = lowResPictureTextureSet.MainTexture;
				break;
			}
			break;
		default:
			videoPlayer.enabled = false;
			texture = null;
			break;
		}
		SafeRaiseScreenRenderEvent(texture);
	}

	private IEnumerator RunShowGif()
	{
		List<RenderTexture> gifTextures = new List<RenderTexture>();
		foreach (RenderTexture gifRenderTexture in gifCapture.GifRenderTextures)
		{
			Vector2 vector = lowResolution;
			int width = (int)vector.x;
			Vector2 vector2 = lowResolution;
			RenderTexture renderTexture = new RenderTexture(width, (int)vector2.y, 0);
			Graphics.Blit(gifRenderTexture, renderTexture);
			gifTextures.Add(renderTexture);
		}
		float frametime = 0.1f;
		float secondsUntilNextFrame = 0f;
		int currentIndex = 0;
		while (shareCamStateMachine.CurrentStateId == 1 || shareCamStateMachine.CurrentStateId == 3)
		{
			if (secondsUntilNextFrame <= 0f)
			{
				SafeRaiseScreenRenderEvent(gifTextures[currentIndex]);
				secondsUntilNextFrame += frametime;
				int num = currentIndex + 1;
				currentIndex = num % gifTextures.Count;
			}
			secondsUntilNextFrame -= Mathf.Min(UnityEngine.Time.deltaTime, 1f / 30f);
			yield return null;
		}
		gifTextures.Clear();
	}

	private void SwitchTextureResolution(ResolutionType newResolutionType)
	{
		if (resolutionType != newResolutionType)
		{
			resolutionType = newResolutionType;
			Vector2 vector = lowResolution;
			float sixteenNineAspectRatio = SixteenNineAspectRatio;
			switch (newResolutionType)
			{
			case ResolutionType.HIGH:
				vector = highResolution;
				break;
			case ResolutionType.MEDIUM:
				vector = mediumResolution;
				break;
			}
			if (renderTexture != null)
			{
				renderTexture.Release();
			}
			renderTexture = new RenderTexture((int)vector.x, (int)vector.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			backCamera.targetTexture = renderTexture;
			frontCamera.targetTexture = renderTexture;
			backCamera.aspect = sixteenNineAspectRatio;
			frontCamera.aspect = sixteenNineAspectRatio;
		}
	}

