	public void UpdateShareCameraGesture(bool gestureButtonDown)
	{
		Vector3 position;
		Quaternion rotation;
		bool flag = DetectShareCameraGesture(out position, out rotation);
		if (gesturePreviewHud != null)
		{
			if (flag && !gesturePreviewHud.activeSelf && !lastGestureReadyStartTime.HasValue)
			{
				lastGestureReadyStartTime = UnityEngine.Time.time;
			}
			else if (!flag)
			{
				lastGestureReadyStartTime = null;
			}
			bool active = flag && lastGestureReadyStartTime.HasValue && UnityEngine.Time.time - lastGestureReadyStartTime.Value > 0.5f && (!takePictureButtonPressed || CurrentState != ShareCamState.ACTIVE) && spawnAndTakePictureCoroutine == null;
			gesturePreviewHud.SetActive(active);
			if (gesturePreviewHud.gameObject.activeSelf)
			{
				gesturePreviewHud.transform.position = position;
				gesturePreviewHud.transform.rotation = rotation;
			}
		}
		if (flag && gestureButtonDown)
		{
			SpawnAndTakePictureAt(position, rotation, isBackCameraActive: true, isTimerActive: false, takePicture: true);
		}
	}

	private bool DetectShareCameraGesture(out Vector3 position, out Quaternion rotation)
	{
		position = Vector3.zero;
		rotation = Quaternion.identity;
		Player localPlayer = Player.LocalPlayer;
		PlayerHand leftHand = localPlayer.LeftHand;
		PlayerHand rightHand = localPlayer.RightHand;
		if (SingletonMonoBehaviour<SettingsManager>.Instance.ShareCameraGestureEnabled && leftHand != null && rightHand != null && !leftHand.IsHoldingTool && !rightHand.IsHoldingTool)
		{
			Vector3 vector = (leftHand.transform.position + rightHand.transform.position) / 2f;
			Vector3 normalized = (vector - localPlayer.Head.transform.position).normalized;
			float num = Vector3.Dot(normalized, localPlayer.Head.transform.forward);
			float num2 = Vector3.Dot(leftHand.FingerDirection, rightHand.FingerDirection);
			float num3 = Vector3.Dot(leftHand.ThumbDirection, -localPlayer.Head.transform.forward);
			float magnitude = (leftHand.transform.position - rightHand.transform.position).magnitude;
			float magnitude2 = (vector - localPlayer.Head.transform.position).magnitude;
			position = vector + localPlayer.Head.transform.forward * 0.1f;
			rotation = localPlayer.Head.transform.rotation.RemoveRoll();
			return num3 >= 0.88f && num2 >= 0.88f && num >= 0.88f && magnitude2 >= 0.1f && spawnGestureHandDistanceBounds.WithinBounds(magnitude);
		}
		return false;
	}

	public void LocalSpawnAndTakeSelfie(bool takePicture)
	{
		if (Player.LocalPlayerExists && isMine)
		{
			Transform transform = Player.LocalPlayer.Head.transform;
			Quaternion quaternion = Quaternion.Euler(0f, transform.rotation.eulerAngles.y, 0f);
			Vector3 vector = transform.position + quaternion * Vector3.forward * 1.5f;
			Vector3 vector2 = transform.position - vector;
			vector2.y = 0f;
			Quaternion rotation = Quaternion.LookRotation(-vector2.normalized, Vector3.up);
			SpawnAndTakePictureAt(vector, rotation, isBackCameraActive: false, isTimerActive: true, takePicture);
		}
	}

	public void SpawnAndTakePictureAt(Vector3 position, Quaternion rotation, bool isBackCameraActive, bool isTimerActive, bool takePicture)
	{
		if (spawnAndTakePictureCoroutine == null && isMine)
		{
			Tool.SuppressAnimateInOut = true;
			Player.LocalPlayer.Backpack.UseTool(PlayerBackpackToolType.SHARE_CAM);
			Tool.SuppressAnimateInOut = false;
			this.InvokeNextEndOfFrame(delegate
			{
				spawnAndTakePictureCoroutine = StartCoroutine(RunSpawnAndTakePictureAt(position, rotation, isBackCameraActive, isTimerActive, takePicture));
			});
		}
	}

	private void Update()
	{
		wasVisibleInPreviousFrame = onScreenWillRenderWasCalled;
		onScreenWillRenderWasCalled = false;
	}

	private void DynamicUpdate(bool shouldUpdate)
	{
		if (shouldUpdate)
		{
			this.InvokeNextEndOfFrame(delegate
			{
				currentCamera.Render();
			});
			lastCameraRenderTime = UnityEngine.Time.time;
			UpdateMenuSize();
		}
	}

	private void UpdateMenuSize()
	{
		if (!isMine || !Tool.MenuProjector.IsMenuVisible || !IsMenuVisibilityManagedInternally)
		{
			return;
		}
		SizeOption size = Tool.Menu.Size;
		bool flag = false;
		if (!Tool.IsHeld && TripodIsActive)
		{
			float sqrMagnitude = (base.transform.position - Player.LocalPlayer.Head.transform.position).sqrMagnitude;
			if ((size == SizeOption.NORMAL && sqrMagnitude >= maxDistanceToExpand * maxDistanceToExpand) || (size == SizeOption.LARGE && sqrMagnitude >= minDistanceToExpand * minDistanceToExpand))
			{
				flag = true;
			}
		}
		if (size == SizeOption.NORMAL && flag)
		{
			Tool.Menu.Size = SizeOption.LARGE;
		}
		else if (size == SizeOption.LARGE && !flag)
		{
			Tool.Menu.Size = SizeOption.NORMAL;
		}
	}

	private float DynamicCostFunction()
	{
		if (!Player.LocalPlayerExists)
		{
			return float.MaxValue;
		}
		if (!wasVisibleInPreviousFrame)
		{
			return float.MaxValue;
		}
		float num = UnityEngine.Time.time - lastCameraRenderTime;
		float num2 = 0f;
		bool flag = false;
		if (screenRefreshFramerate < Mathf.Epsilon)
		{
			flag = num > 0f;
		}
		else
		{
			num2 = 1f / screenRefreshFramerate;
			flag = num >= num2;
		}
		if (!flag)
		{
			return float.MaxValue;
		}
		if (isMine)
		{
			return 0f;
		}
		float sqrMagnitude = (Player.LocalPlayer.Head.transform.position - base.transform.position).sqrMagnitude;
		if (sqrMagnitude > screenRefreshCutoffDistance * screenRefreshCutoffDistance)
		{
			return float.MaxValue;
		}
		float num3 = num - num2;
		float num4 = num3 * num3 * num3 * num3 * num3;
		return Mathf.Max(0.5f, sqrMagnitude - num4);
	}

