	private void OnTripodToggled()
	{
		if (TripodIsActive)
		{
			Tool.RigidbodyEx.AddKinematic(this);
		}
		else
		{
			disableTripodOnNextPickup = false;
			Tool.RigidbodyEx.RemoveKinematic(this);
			if (isMine && !Tool.IsHeld && IsMenuVisibilityManagedInternally)
			{
				Tool.MenuProjector.IsMenuVisible = false;
			}
		}
		Tool.RigidbodyEx.useGravity = !TripodIsActive;
		UpdateGravityPickupMode();
		SafeRaiseRefreshUIEvent();
	}

	private void UpdateGravityPickupMode()
	{
		Tool.GravityPickupMode = ((TripodIsActive || Tool.IsHeldByPlayer) ? Tool.GravityPickup.DISABLED : Tool.GravityPickup.SNAP_POSITION_SNAP_ORIENTATION);
	}

	private void OnTakePictureButtonPressedChange()
	{
		if (shareCamModeStateMachine.CurrentStateId != 0)
		{
			return;
		}
		PlayAudio(buttonPressAudio);
		if (takePictureButtonPressed)
		{
			if (isMine)
			{
				StartCoroutine(CreatorRunTakePicture());
			}
			else
			{
				StartCoroutine(RunTakePictureCountdown());
			}
		}
	}

	private IEnumerator RunShowFeedback(string text, bool isTemporary, string followUpText = null)
	{
		PlayAudio(successAudio);
		SafeRaiseFeedbackTextEvent(text);
		if (!string.IsNullOrEmpty(followUpText))
		{
			yield return new WaitForSeconds(2.5f);
			SafeRaiseFeedbackTextEvent(followUpText);
		}
		if (isTemporary)
		{
			yield return new WaitForSeconds(2.5f);
			SafeRaiseFeedbackTextEvent(null);
		}
	}

