	private void TakeLowResPicture()
	{
		if (isMine)
		{
			if (lowResPictureTextureSet != null)
			{
				lowResPictureTextureSet.DestroyTextures();
			}
			frontCameraOutput.MirrorImage = false;
			TakePictureInternal(lowResPictureTextureSet, currentCamera, renderTexture);
		}
