	private IEnumerator RunTakePictureCountdown()
	{
		if (TimerIsActive)
		{
			PlayAudio(countDownTickAudio);
			ShowTimerNotification("3");
			yield return new WaitForSeconds(1f);
			PlayAudio(countDownTickAudio);
			ShowTimerNotification("2");
			yield return new WaitForSeconds(1f);
			PlayAudio(countDownTickAudio);
			ShowTimerNotification("1");
			yield return new WaitForSeconds(1f);
		}
		PlayAudio(shutterAudio);
		yield return new WaitForEndOfFrame();
		animator.SetTrigger(flashVisualId);
	}

	private void ShowTimerNotification(string text)
	{
		if (isMine && Tool.Menu.Size == SizeOption.LARGE)
		{
			WorldSpaceNotification.PlayNext(text, 1f, null, followPlayer: false, base.transform.position + Vector3.up * 0.25f, 0.5f);
		}
		else
		{
			WorldSpaceNotification.PlayNext(text, 1f, null, followPlayer: false, base.transform.position + Vector3.up * 0.15f, 0.3f);
		}
	}

	private IEnumerator CreatorRunTakePicture()
	{
		if (BackCameraIsActive)
		{
			flashActivated = true;
		}
		yield return StartCoroutine(RunTakePictureCountdown());
		flashActivated = false;
		frontCameraOutput.MirrorImage = false;
		SwitchTextureResolution(ResolutionType.HIGH);
		TakePictureInternal(highResPictureTextureSet, currentCamera, renderTexture);
		polaroidPictureUploadPromise = null;
		lowResPictureTextureSet.MainTexture = highResPictureTextureSet.MainTexture;
		lowResPictureTextureSet.AltTexture = highResPictureTextureSet.AltTexture;
		GetPlayersInPicture();
		if (this.OnPictureTaken != null)
		{
			this.OnPictureTaken(currentFilter);
		}
		SwitchTextureResolution(ResolutionType.LOW);
		shareCamStateMachine.EnterState(1);
	}

	private void TakePictureInternal(AltTextureSet altTextureSet, Camera camera, RenderTexture renderTexture)
	{
		Vector3 position = camera.transform.position;
		Quaternion rotation = camera.transform.rotation;
		if (IsScreensExplicitTransformSet)
		{
			camera.transform.position = ScreensExplicitTransformPosition;
			camera.transform.rotation = ScreensExplicitTransformRotation;
		}
		altTextureSet.Render(camera, renderTexture);
		camera.transform.position = position;
		camera.transform.rotation = rotation;
	}

	private void GetPlayersInPicture()
	{
		visiblePlayerIds.Clear();
		foreach (Player item in Player.All)
		{
			bool flag = false;
			PlayerFacialAnimator componentInChildren = item.Head.GetComponentInChildren<PlayerFacialAnimator>(includeInactive: true);
			if (componentInChildren != null)
			{
				Renderer faceRenderer = componentInChildren.FaceRenderer;
				if (faceRenderer.IsInFov(currentCamera))
				{
					LayerMasks layermask = (LayerMasks)496385537;
					float maxDistance = Vector3.Distance(item.Head.transform.position, currentCamera.transform.position);
					RaycastHit[] array = Physics.RaycastAll(currentCamera.transform.position, item.Head.transform.position - currentCamera.transform.position, maxDistance, (int)layermask);
					flag = true;
					RaycastHit[] array2 = array;
					for (int i = 0; i < array2.Length; i++)
					{
						RaycastHit raycastHit = array2[i];
						PlayerCollider component = raycastHit.collider.GetComponent<PlayerCollider>();
						if (component == null || (component.ThisPlayer != item && (Tool.HolderPlayer == null || component.ThisPlayer != Tool.HolderPlayer || Tool.HolderHand != Tool.HolderPlayer.GetHand(component.BodyPart))))
						{
							StickyBase stickyBase = null;
							ToolCollider component2 = raycastHit.collider.GetComponent<ToolCollider>();
							if (!(component2 != null))
							{
								flag = false;
								break;
							}
							stickyBase = component2.Tool.GetComponent<StickyBase>();
							if (stickyBase == null || stickyBase.AttachedPlayer != item)
							{
								flag = false;
								break;
							}
						}
					}
				}
			}
			if (flag)
			{
				visiblePlayerIds.Add((int)item.PlayerId);
			}
		}
	}

	private void SaveToTempLocation()
	{
		if (SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform == PlatformManager.PlatformType.PlayStation)
		{
			return;
		}
		Images.ShareCamImage imageData = new Images.ShareCamImage
		{
			mainImage = mediumResPictureTextureSet.MainTexture.EncodeToJPG(80),
			altImage = mediumResPictureTextureSet.AltTexture.EncodeToJPG(80),
			imageMeta = new Images.SavedImageMetaDTO
			{
				playerIds = visiblePlayerIds,
				savedImageType = Images.SavedImageType.ShareCamera,
				roomId = GameSessions.LocalGameSession.RoomId,
				playerEventId = ((!GameSessions.LocalGameSession.PlayerEventId.HasValue) ? (-1) : GameSessions.LocalGameSession.PlayerEventId.Value),
				accessibility = Images.SavedImageAccessibility.Private
			}
		};
		string path = Path.Combine(UnityEngine.Application.temporaryCachePath, "ShareCam");
		BackgroundWorker backgroundWorker = new BackgroundWorker();
		backgroundWorker.DoWork += delegate
		{
			Directory.CreateDirectory(path);
			BinaryFormatter binaryFormatter = new BinaryFormatter();
			FileStream fileStream = File.Create(VideoCapture.CurrentFileName);
			binaryFormatter.Serialize(fileStream, imageData);
			fileStream.Close();
		};
		backgroundWorker.RunWorkerCompleted += delegate(object sender, RunWorkerCompletedEventArgs e)
		{
			if (e.Error != null)
			{
				UnityEngine.Debug.LogError("Error saving temp share cam image: " + e.Error);
			}
		};
		backgroundWorker.RunWorkerAsync();
	}

	private void UploadPicture(bool showUploadedFeedback = true)
	{
		isUploading = true;
		if (showUploadedFeedback)
		{
			StartCoroutine(RunShowFeedback("Uploading...", isTemporary: false));
		}
		Images.UploadSavedImage(highResPictureTextureSet, Images.SavedImageType.ShareCamera, visiblePlayerIds).Error(delegate(string error)
		{
			UnityEngine.Debug.LogError("Failed to upload saved image: " + error);
			if (showUploadedFeedback)
			{
				StartCoroutine(RunShowFeedback("Error uploading", isTemporary: true));
			}
		}).Then((Action)delegate
		{
			if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.UploadedPhoto();
			}
			if (showUploadedFeedback)
			{
				StartCoroutine(RunShowFeedback("Uploaded!", isTemporary: true));
			}
		})
			.Finally(delegate
			{
				isUploading = false;
			});
	}

	private void UpdateCurrentVideoCapture()
	{
		switch ((ShareCamMode)shareCamModeStateMachine.CurrentStateId)
		{
		case ShareCamMode.GIF:
			currentVideoCapture = gifCapture;
			break;
		case ShareCamMode.MP4:
			currentVideoCapture = mp4Capture;
			break;
		default:
			currentVideoCapture = pngCapture;
			break;
		}
	}

	private IEnumerator RunRecordVideo(float framerate)
	{
		float frametime = 1f / framerate;
		float secondsUntilNextRender = 0f;
		while (IsRecording)
		{
			yield return new WaitForEndOfFrame();
			if (secondsUntilNextRender <= 0f)
			{
				float num = currentVideoCapture.UpdateFrame(renderTexture);
				if (num >= 1f)
				{
					IsRecording = false;
				}
				secondsUntilNextRender += frametime;
			}
			secondsUntilNextRender -= Mathf.Min(UnityEngine.Time.deltaTime, 1f / 30f);
		}
	}

	private void OnIsRecordingChanged()
	{
		if (isInPngMode)
		{
			return;
		}
		if (IsRecording)
		{
			if (isMine)
			{
				TakeLowResPicture();
				if (shareCamModeStateMachine.CurrentStateId == 2)
				{
					SwitchTextureResolution(ResolutionType.MEDIUM);
					SafeRaiseScreenRenderEvent(renderTexture);
				}
				currentVideoCapture.StartCapture();
				StartCoroutine(RunRecordVideo((shareCamModeStateMachine.CurrentStateId != 2) ? 10f : 30f));
			}
		}
		else if (isMine)
		{
			currentVideoCapture.FinishCapture();
			videoPlayer.enabled = true;
			SwitchTextureResolution(ResolutionType.LOW);
			shareCamStateMachine.EnterState(1);
		}
	}

	private void SaveToDisk()
