	private void StartPrintPolaroidCoroutine()
	{
		if (!IsPrintingPolaroid)
		{
			StartCoroutine(RunShowFeedback("Printing...", isTemporary: true));
			StopPrintPolaroidCoroutine();
			printPolaroidCoroutine = StartCoroutine(RunPrintPolaroid());
		}
	}

	private void StopPrintPolaroidCoroutine()
	{
		this.SafeStopCoroutine(printPolaroidCoroutine);
		printPolaroidCoroutine = null;
		SafeRaiseRefreshUIEvent();
	}

	private IEnumerator RunPrintPolaroid()
	{
		HasPrintedPolaroid = true;
		SafeRaiseRefreshUIEvent();
		attachedPolaroid = null;
		waitingForPolaroidSpawn = true;
		if (polaroidPictureUploadPromise == null)
		{
			AltTextureSet altTextureSet = CreateResizedSquareTextureSet(highResPictureTextureSet, polaroidResolutionHeight);
			polaroidPictureUploadPromise = Images.UploadTransientImage(altTextureSet, null, expectsAltImage: true, uploadAsJpg: true).Error(delegate(string error)
			{
				UnityEngine.Debug.LogError("Failed to upload polaroid image: " + error);
			});
			altTextureSet.DestroyTextures();
		}
		IPromise<string> uploadPromise = polaroidPictureUploadPromise;
		base.photonView.RpcMaster(RpcMasterSpawnPolaroid);
		float requestTimeoutTime = UnityEngine.Time.realtimeSinceStartup + 5f;
		while (waitingForPolaroidSpawn && UnityEngine.Time.realtimeSinceStartup < requestTimeoutTime)
		{
			yield return null;
		}
		Polaroid polaroid = attachedPolaroid;
		if (polaroid != null)
		{
			polaroid.photonView.TransferOwnership(PhotonNetwork.player);
			polaroid.AuthoritySetImageName(uploadPromise);
			polaroid.IsGrabbable = false;
			polaroid.IsKinematic = true;
			polaroid.Tool.PrePickupEvent += OnPolaroidRemovedFromCamera;
			PlayAudio(printAudio);
			float prePrintStartTime = UnityEngine.Time.time;
			while (UnityEngine.Time.time - prePrintStartTime < 1.5f)
			{
				polaroid.transform.position = polaroidStartTransform.position;
				polaroid.transform.rotation = polaroidStartTransform.rotation;
				yield return null;
			}
			Vector3 oldLocalPosition = base.transform.InverseTransformPoint(polaroidStartTransform.position);
			Vector3 localEndPosition = base.transform.InverseTransformPoint(polaroidEndTransform.position);
			float printStartTime = UnityEngine.Time.time;
			while (polaroid.transform.position != polaroidEndTransform.position && UnityEngine.Time.time - printStartTime < 1f)
			{
				polaroid.transform.position = base.transform.TransformPoint(Vector3.MoveTowards(oldLocalPosition, localEndPosition, polaroidPrintSpeed * UnityEngine.Time.deltaTime));
				oldLocalPosition = base.transform.InverseTransformPoint(polaroid.transform.position);
				polaroid.transform.rotation = polaroidStartTransform.rotation;
				yield return null;
			}
			polaroid.IsGrabbable = true;
			StartCoroutine(RunShowFeedback("Printed!", isTemporary: true));
			while (attachedPolaroid != null)
			{
				polaroid.transform.position = polaroidEndTransform.position;
				polaroid.transform.rotation = polaroidEndTransform.rotation;
				yield return null;
			}
			polaroid.IsKinematic = false;
		}
		printPolaroidCoroutine = null;
		SafeRaiseRefreshUIEvent();
	}

	private AltTextureSet CreateResizedSquareTextureSet(AltTextureSet originalTextureSet, int squareHeight)
	{
		AltTextureSet altTextureSet = new AltTextureSet();
		RenderTexture temporary = RenderTexture.GetTemporary((int)((float)squareHeight * SixteenNineAspectRatio), squareHeight, 24);
		Graphics.Blit(originalTextureSet.MainTexture, temporary);
		altTextureSet.MainTexture = AltTextureSet.RenderTextureToTexture2DCropSquare(temporary);
		if (originalTextureSet.AltTexture == originalTextureSet.MainTexture)
		{
			altTextureSet.AltTexture = altTextureSet.MainTexture;
		}
		else
		{
			Graphics.Blit(originalTextureSet.AltTexture, temporary);
			altTextureSet.AltTexture = AltTextureSet.RenderTextureToTexture2DCropSquare(temporary);
		}
		RenderTexture.ReleaseTemporary(temporary);
		return altTextureSet;
	}

	private void OnPolaroidRemovedFromCamera(Tool polaroidTool)
	{
		attachedPolaroid = null;
		polaroidTool.PrePickupEvent -= OnPolaroidRemovedFromCamera;
	}

	private void SafeRaiseRefreshUIEvent()
	{
		if (this.RefreshUIEvent != null)
		{
			this.RefreshUIEvent();
		}
	}

	private void SafeRaiseScreenRenderEvent(Texture texture)
	{
		if (this.ScreenRenderEvent != null)
		{
			this.ScreenRenderEvent(texture);
		}
	}

	private void SafeRaiseFeedbackTextEvent(string feedback)
	{
		if (this.FeedbackTextEvent != null)
		{
			this.FeedbackTextEvent(feedback);
		}
	}

	private IEnumerator RunUploadToRecNet(bool showUploadedFeedback = true)
	{
		HasSharedOnRecNet = true;
		SafeRaiseRefreshUIEvent();
		if (isUploading)
		{
			yield break;
		}
		if (highResPictureTextureSet == null)
		{
			UnityEngine.Debug.LogError("No highResPictureTexture to send");
			StartCoroutine(RunShowFeedback("Image not found", isTemporary: true));
			yield break;
		}
		UploadPicture(showUploadedFeedback);
		while (isUploading)
		{
			yield return null;
		}
		if (showUploadedFeedback)
		{
			StartCoroutine(RunShowFeedback("Shared on www.rec.net", isTemporary: true));
		}
	}

	private bool TryTakeOwnership()
	{
		if (base.hasAuthority)
		{
			return true;
		}
		if (!base.hasAuthority && Tool.AllowedToTakeOwnership)
		{
			base.photonView.TransferOwnership(PhotonNetwork.player);
			return true;
		}
		return false;
	}

	[PunRPC]
	private void RpcMasterSpawnPolaroid(PhotonMessageInfo messageInfo)
	{
		if (PhotonNetwork.isMasterClient)
		{
			PhotonPlayer sender = messageInfo.sender;
			if (sender != null)
			{
				Polaroid arg = Polaroid.TryMasterSpawnPolaroidForPlayer(polaroidStartTransform.position, base.transform.rotation, sender);
				base.photonView.RpcPlayer(sender, RpcSpawnPolaroidResponse, arg);
			}
		}
	}

	[PunRPC]
	private void RpcSpawnPolaroidResponse(Polaroid polaroid)
	{
		waitingForPolaroidSpawn = false;
		attachedPolaroid = polaroid;
	}

	private IEnumerator RunSpawnAndTakePictureAt(Vector3 position, Quaternion rotation, bool isbackCameraActive, bool isTimerActive, bool takePicture)
	{
		if (Tool.PlayerSpawnedEquipment != null)
		{
			if (Tool.IsHeld)
			{
				Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (Tool.IsHeld)
			{
				Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
			PlayAudio(gestureDetectedAudio);
			disableTripodOnNextPickup = true;
			Tool.RigidbodyEx.SetDiscontinuousPositionAndRotation(position, rotation);
			Tool.Menu.Size = SizeOption.NORMAL;
			yield return null;
			shareCamStateMachine.EnterState(0);
			shareCamModeStateMachine.EnterState(0);
			TimerIsActive = isTimerActive;
			BackCameraIsActive = isbackCameraActive;
			TripodIsActive = true;
			Tool.RigidbodyEx.RemoveKinematic(Tool.PlayerSpawnedEquipment);
			UpdateGravityPickupMode();
			yield return null;
			if (takePicture)
			{
				Tool.SetVisible(visible: false);
				TakePicture();
				yield return null;
				Tool.SetVisible(visible: true);
			}
		}
		yield return null;
		if (isMine)
		{
			Tool.MenuProjector.IsMenuVisible = true;
		}
		spawnAndTakePictureCoroutine = null;
	}
}
namespace RecRoom.Tools
{
	public class SqueezeBox : Photon.MonoBehaviour
	{
		[SerializeField]
		private SqueezeBoxHandle[] handles;

		[SerializeField]
		private SkinnedMeshRenderer handleMeshRenderer;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip[] chordAudioClips;

		[SerializeField]
		private FloatValueCurve handleSpeedToAudioIntensity;

		[Header("Physics")]
		[SerializeField]
		private float restingDistanceBetweenHandles = 0.5f;

		[SerializeField]
		private float maxLinearSpringForce = 1f;

		private const float MIN_COMPRESSION_SPEED_FOR_SOUND = 0.05f;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private AudioSource audioSource;

		private float previousDistanceBetweenHandles;

		private float currentCompressionSpeed;

		private SynchronizedField<int> _chordIndex;

		public int ChordIndex
		{
			get
			{
				return _chordIndex.Get();
			}
			set
			{
				_chordIndex.Set(value);
			}
		}

		public bool IsBeingPlayed => handles[0].Tool.IsHeld && handles[1].Tool.IsHeld;

		protected override void Awake()
		{
			base.Awake();
			_chordIndex = new SynchronizedField<int>(this, "C", 0, SetterPermissionMode.AUTHORITY, OnChordIndexChanged);
			SqueezeBoxHandle[] array = handles;
			foreach (SqueezeBoxHandle squeezeBoxHandle in array)
			{
				squeezeBoxHandle.Tool.PostPickupEvent += OnHandlePickup;
				squeezeBoxHandle.Tool.AddCustomPickupCondition(CustomPickupCondition);
				squeezeBoxHandle.Tool.AddRenderer(handleMeshRenderer);
			}
		}

		private void Start()
		{
			OnChordIndexChanged();
		}

		private void Update()
		{
			UpdateInput();
			UpdateAudio();
			DebugVR.Log("compression speed: " + currentCompressionSpeed.ToString("F2") + ", volume: " + handleSpeedToAudioIntensity.EvaluateNonNormalized(currentCompressionSpeed).ToString("F2") + ", chord: " + ChordIndex);
		}

		private void FixedUpdate()
		{
			UpdateHandleVelocity();
			if (base.hasAuthority && !IsBeingPlayed)
			{
				UpdateSpringPhysics();
			}
		}

		protected override void OnDestroy()
		{
			SqueezeBoxHandle[] array = handles;
			foreach (SqueezeBoxHandle squeezeBoxHandle in array)
			{
				squeezeBoxHandle.Tool.PostPickupEvent -= OnHandlePickup;
			}
			base.OnDestroy();
		}

		private bool CustomPickupCondition(Tool tool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			bool flag = true;
			bool flag2 = true;
			SqueezeBoxHandle[] array = handles;
			foreach (SqueezeBoxHandle squeezeBoxHandle in array)
			{
				if (squeezeBoxHandle.Tool.IsHeldByPlayer)
				{
					flag = false;
					if (selectingPlayer != null && squeezeBoxHandle.Tool.HolderPlayer != selectingPlayer)
					{
						flag2 = false;
					}
				}
			}
			return flag || flag2;
		}

		private void OnHandlePickup(Tool tool)
		{
			base.photonView.TransferOwnership(tool.owner);
		}

		private void OnHandleInputChanged(Tool tool)
		{
			if (base.hasAuthority)
			{
				ChordIndex = GetChordIndexForInput(handles[0].Tool.InputAmount >= 0.9f, handles[1].Tool.InputAmount >= 0.9f);
			}
		}

		private void UpdateInput()
		{
			if (base.hasAuthority && IsBeingPlayed)
			{
				int chordIndexForInput = GetChordIndexForInput(handles[0].Tool.InputAmount >= 0.9f, handles[1].Tool.InputAmount >= 0.9f);
				if (chordIndexForInput != ChordIndex)
				{
					ChordIndex = chordIndexForInput;
				}
			}
		}

		private void UpdateAudio()
		{
			if (IsBeingPlayed && !audioSource.isPlaying)
			{
				audioSource.Play();
			}
			else if (!IsBeingPlayed && audioSource.isPlaying)
			{
				audioSource.Stop();
			}
			if (audioSource.isPlaying)
			{
				audioSource.volume = handleSpeedToAudioIntensity.EvaluateNonNormalized(currentCompressionSpeed);
			}
		}

		private void OnChordIndexChanged()
		{
			audioSource.clip = chordAudioClips[ChordIndex].audioClip;
		}

		private int GetChordIndexForInput(bool input1, bool input2)
		{
			int result = 0;
			if (input1 && !input2)
			{
				result = 1;
			}
			else if (!input1 && input2)
			{
				result = 2;
			}
			else if (input1 && input2)
			{
				result = 3;
			}
			return result;
		}

		private void UpdateSpringPhysics()
		{
			float num = 1f - previousDistanceBetweenHandles / restingDistanceBetweenHandles;
			Vector3 vector = maxLinearSpringForce * num * (handles[0].transform.position - handles[1].transform.position).normalized;
			Vector3 force = (handles[0].Tool.IsHeld ? Vector3.zero : ((!handles[1].Tool.IsHeld) ? (vector / 2f) : vector));
			Vector3 force2 = (handles[1].Tool.IsHeld ? Vector3.zero : ((!handles[0].Tool.IsHeld) ? (-vector / 2f) : (-vector)));
			handles[0].Tool.RigidbodyEx.AddForce(force, ForceMode.Acceleration);
			handles[1].Tool.RigidbodyEx.AddForce(force2, ForceMode.Acceleration);
			Transform transform = (handles[0].Tool.IsHeld ? handles[0].Tool.transform : ((!handles[1].Tool.IsHeld) ? handles[0].Tool.transform.parent : handles[1].Tool.transform));
			SqueezeBoxHandle[] array = handles;
			foreach (SqueezeBoxHandle squeezeBoxHandle in array)
			{
				if (!squeezeBoxHandle.Tool.IsHeld && !squeezeBoxHandle.Tool.transform.rotation.AlmostEquals(transform.rotation, 5f))
				{
					squeezeBoxHandle.Tool.transform.rotation = Quaternion.Slerp(squeezeBoxHandle.Tool.transform.rotation, transform.rotation, 0.5f);
				}
			}
		}

		private void UpdateHandleVelocity()
		{
			float magnitude = (handles[0].Tool.transform.position - handles[1].transform.position).magnitude;
			currentCompressionSpeed = Mathf.Abs((magnitude - previousDistanceBetweenHandles) / UnityEngine.Time.fixedDeltaTime);
			previousDistanceBetweenHandles = magnitude;
		}
	}
	public class SqueezeBoxHandle : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
