			Tool.PostPickupEvent -= OnToolPickup;
			Tool.PostReleaseEvent -= OnToolRelease;
		}

		private void OnToolPickup(Tool tool)
		{
		}

		private void OnToolRelease(Tool tool)
		{
		}
	}
	public sealed class SimpleSticky : StickyBase
	{
		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private SimpleVolumeBase overlapVolume;

		[SerializeField]
		private LayerMasks layerMask = LayerMasks.StickyTargets;

		protected override void AuthorityProcessStickyToolReleased()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
			int num = overlapVolume.OverlapTest(iMMEDIATE_COLLIDER_HITS, (int)layerMask, QueryTriggerInteraction.Ignore);
			bool flag = false;
			for (int i = 0; i < num; i++)
			{
				PhotonView componentInParent = iMMEDIATE_COLLIDER_HITS[i].gameObject.GetComponentInParent<PhotonView>();
				if (componentInParent != null && componentInParent != base.photonView)
				{
					AuthorityTryAttach(componentInParent);
					flag = true;
					break;
				}
			}
			if (!flag && num > 1)
			{
				AuthorityTryAttach(null);
			}
		}
	}
}
public abstract class StickyBase : Photon.MonoBehaviour, IPersistable, IPreDeserializationPersistable
{
	private static readonly List<Collider> STATIC_COLLIDERS_A = new List<Collider>();

	private static readonly List<Collider> STATIC_COLLIDERS_B = new List<Collider>();

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Tool _tool;

	[SerializeField]
	private bool onlyMasterCanAttach;

	[SerializeField]
	private bool disableCollidersWhenAttached;

	private StickyBase parent;

	private readonly List<StickyBase> children = new List<StickyBase>();

	private SynchronizedField<bool> _isStaticallyAttached;

	public Tool Tool => _tool;

	public StickyBase TreeRoot
	{
		get
		{
			if (parent != null)
			{
				return parent.TreeRoot;
			}
			return this;
		}
	}

	public IReadOnlyList<StickyBase> Children
	{
		[CompilerGenerated]
		get
		{
			return children;
		}
	}

	public bool IsTreeRoot => parent == null;

	public Tool RootNonStickyTool => TreeRoot.AttachedTool;

	public bool IsAttached { get; private set; }

	public bool IsAttachedToPhotonView { get; private set; }

	public PhotonView AttachedPhotonView { get; private set; }

	public Tool AttachedTool { get; private set; }

	public Player AttachedPlayer { get; private set; }

	public Vector3 AttachedRelativePosition
	{
		get
		{
			if (!IsAttached)
			{
				return Vector3.zero;
			}
			if (Tool.IsAttachedToObject)
			{
				return Tool.HolderInfo.RelativePosition;
			}
			return base.transform.position;
		}
	}

	public Quaternion AttachedRelativeRotation
	{
		get
		{
			if (!IsAttached)
			{
				return Quaternion.identity;
			}
			if (Tool.IsAttachedToObject)
			{
				return Tool.HolderInfo.RelativeRotation;
			}
			return base.transform.rotation;
		}
	}

	private bool IsStaticallyAttached
	{
		get
		{
			return _isStaticallyAttached.Get();
		}
		set
		{
			_isStaticallyAttached.Set(value);
		}
	}

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		_isStaticallyAttached = new SynchronizedField<bool>(this, "SB_SA", defaultValue: false, SetterPermissionMode.MASTER_OR_AUTHORITY, OnIsStaticallyAttachedChanged);
		Tool.HolderChangedEvent += OnToolHolderChanged;
		Tool.PostReleaseEvent += OnToolReleased;
	}

	protected virtual void Start()
	{
		OnIsStaticallyAttachedChanged();
	}

	protected override void OnDestroy()
	{
		OnDetach();
		base.OnDestroy();
	}

	private void OnAttachedViewOwnerChanged(int newOwnerId)
	{
		if (PhotonNetwork.player.ID == newOwnerId)
		{
			base.photonView.TransferOwnership(newOwnerId);
		}
	}

	private void OnToolReleased(Tool thisTool)
	{
		this.EndOfFrameRoutine(delegate
		{
			if (base.hasAuthority && !Tool.IsHeld)
			{
				AuthorityProcessStickyToolReleased();
			}
		});
	}

	protected abstract void AuthorityProcessStickyToolReleased();

	private void OnToolHolderChanged(Tool thisTool)
	{
		PhotonView holderView = Tool.HolderView;
		if (holderView != AttachedPhotonView)
		{
			OnDetach();
			if (Tool.IsAttachedToObject)
			{
				OnAttach();
			}
		}
		if (Tool.IsHeld && base.hasAuthority)
		{
			IsStaticallyAttached = false;
		}
	}

	private void OnIsStaticallyAttachedChanged()
	{
		if (IsStaticallyAttached)
		{
			OnAttach();
		}
	}

	private void OnAttach()
	{
		IsAttached = true;
		AttachedPhotonView = Tool.HolderView;
		Tool.RigidbodyEx.AddKinematic(this);
		Tool.ToolCleanup.PauseCleanup(this);
		if (disableCollidersWhenAttached)
		{
			foreach (ToolCollider collider in Tool.Colliders)
			{
				collider.IsTrigger = true;
			}
		}
		if (!(AttachedPhotonView != null))
		{
			return;
		}
		AttachedPhotonView.OwnerChangedEvent += OnAttachedViewOwnerChanged;
		StickyBase component = AttachedPhotonView.GetComponent<StickyBase>();
		if (component != null)
		{
			AddToStickyTree(component);
			IgnoreTreeColliders(component.TreeRoot, this, ignore: true);
		}
		AttachedTool = AttachedPhotonView.GetComponent<Tool>();
		if (AttachedTool != null)
		{
			AttachedTool.ToolCleanup.PauseCleanup(this);
		}
		else
		{
			PlayerCollider componentInChildren = AttachedPhotonView.GetComponentInChildren<PlayerCollider>();
			if (componentInChildren != null)
			{
				AttachedPlayer = componentInChildren.ThisPlayer;
			}
		}
		Tool rootNonStickyTool = RootNonStickyTool;
		if (rootNonStickyTool != null)
		{
			ToolIgnoreTreeColliders(rootNonStickyTool, this, ignore: true);
		}
	}

	private void OnDetach()
	{
		if (disableCollidersWhenAttached)
		{
			foreach (ToolCollider collider in Tool.Colliders)
			{
				collider.IsTrigger = false;
			}
		}
		if (AttachedPhotonView != null)
		{
			AttachedPhotonView.OwnerChangedEvent -= OnAttachedViewOwnerChanged;
			if (AttachedTool != null)
			{
				AttachedTool.ToolCleanup.ResumeCleanup(this);
			}
		}
		Tool rootNonStickyTool = RootNonStickyTool;
		if (rootNonStickyTool != null)
		{
			ToolIgnoreTreeColliders(rootNonStickyTool, this, ignore: false);
		}
		if (!IsTreeRoot)
		{
			IgnoreTreeColliders(TreeRoot, this, ignore: false);
		}
		Tool.RigidbodyEx.RemoveKinematic(this);
		Tool.ToolCleanup.ResumeCleanup(this);
		RemoveFromStickyTree();
		IsAttached = false;
		AttachedPhotonView = null;
		AttachedTool = null;
		AttachedPlayer = null;
	}

	public virtual bool AuthorityTryAttach(PhotonView connectedPhotonView)
	{
		if (!base.hasAuthority)
		{
			return false;
		}
		bool flag = connectedPhotonView != null;
		StickyBase treeRoot = TreeRoot;
		if (treeRoot != this)
		{
			return treeRoot.AuthorityTryAttach(connectedPhotonView);
		}
		if (!IsAttachmentValid(PhotonNetwork.player, connectedPhotonView))
		{
			return false;
		}
		if (flag)
		{
			Vector3 relativePosition = connectedPhotonView.transform.InverseTransformPoint(base.transform.position);
			Quaternion relativeRotation = connectedPhotonView.transform.InverseTransformRotation(base.transform.rotation);
			AuthorityRequestAttachToPhotonView(connectedPhotonView, relativePosition, relativeRotation);
		}
		else if (!Tool.IsHeld)
		{
			Tool.NetworkTransform.InsertPositionDiscontinuity();
			IsStaticallyAttached = true;
		}
		return true;
	}

	private void AuthorityRequestAttachToPhotonView(PhotonView connectedPhotonView, Vector3 relativePosition, Quaternion relativeRotation)
	{
		if (base.hasAuthority)
		{
			if (onlyMasterCanAttach)
			{
				base.photonView.RpcMaster(RpcMasterRequestAttachToObject, connectedPhotonView, relativePosition, relativeRotation);
			}
			else
			{
				AuthorityOrMasterAttachToPhotonView(connectedPhotonView, relativePosition, relativeRotation);
			}
		}
	}

	private void AuthorityOrMasterAttachToPhotonView(PhotonView connectedPhotonView, Vector3 relativePosition, Quaternion relativeRotation)
	{
		if ((!onlyMasterCanAttach) ? base.hasAuthority : PhotonNetwork.isMasterClient)
		{
			float relativeScale = connectedPhotonView.transform.InverseTransformLossyUniformScale(Tool.transform.GetLossyUniformScale());
			Tool.HolderInfo = ToolHolderInfo.AttachedToObject(connectedPhotonView.viewID, relativePosition, relativeRotation, relativeScale);
			SynchronizedField.SendPendingRoomUpdates();
		}
		else
		{
			UnityEngine.Debug.LogWarningFormat("Unable to attach sticky object {0} to photonView {1}: Permission denied", base.gameObject, (!(connectedPhotonView != null)) ? "NULL" : connectedPhotonView.ToString());
		}
	}

	[PunRPC]
	protected void RpcMasterRequestAttachToObject(PhotonView connectedPhotonView, Vector3 relativePosition, Quaternion relativeRotation)
	{
		if (PhotonNetwork.isMasterClient)
		{
			AuthorityOrMasterAttachToPhotonView(connectedPhotonView, relativePosition, relativeRotation);
		}
	}

	private bool IsAttachmentValid(PhotonPlayer attachingPlayer, PhotonView connectedPhotonView)
	{
		if (attachingPlayer == null)
		{
			return false;
		}
		if (base.photonView.authority != attachingPlayer)
		{
			return false;
		}
		if (Tool.IsFrozen)
		{
			return false;
		}
		if (connectedPhotonView == null)
		{
			return true;
		}
		StickyBase componentInChildren = connectedPhotonView.GetComponentInChildren<StickyBase>();
		if (TreeContainsElement(componentInChildren, this))
		{
			return false;
		}
		return true;
	}

	protected static bool TreeContainsElement(StickyBase tree, StickyBase element)
	{
		bool alreadyInTree = false;
		if (tree != null && element != null)
		{
			TraverseTree(tree.TreeRoot, delegate(StickyBase sticky)
			{
				if (sticky == element)
				{
					alreadyInTree = true;
				}
			});
		}
		return alreadyInTree;
	}

	public static int TreeSize(StickyBase root)
	{
		int size = 0;
		TraverseTree(root, delegate
		{
			size++;
		});
		return size;
	}

	public static int TreeDepth(StickyBase tree)
	{
		int num = 0;
		StickyBase stickyBase = tree;
		while (!stickyBase.IsTreeRoot)
		{
			num++;
			stickyBase = stickyBase.parent;
		}
		return num;
	}

	public static void GatherTreeColliders(StickyBase root, List<Collider> colliders)
	{
		colliders.Clear();
		TraverseTree(root, delegate(StickyBase node)
		{
			GatherNodeColliders(node, colliders);
		});
	}

	public static void GatherTreeCollidersIgnoreSubtree(StickyBase root, StickyBase ignoreSubtree, List<Collider> colliders)
	{
		colliders.Clear();
		TraverseTree(root, ignoreSubtree, ignoreNodeChildren: true, delegate(StickyBase node)
		{
			GatherNodeColliders(node, colliders);
		});
	}

	public static void GatherTreeCollidersIgnoreNode(StickyBase root, StickyBase ignoreNode, List<Collider> colliders)
	{
		colliders.Clear();
		TraverseTree(root, ignoreNode, ignoreNodeChildren: false, delegate(StickyBase node)
		{
			GatherNodeColliders(node, colliders);
		});
	}

	public static void GatherNodeColliders(StickyBase node, List<Collider> colliders)
	{
		if (node != null)
		{
			colliders.AddRange(node.GetComponentsInChildren<Collider>(includeInactive: true));
			colliders.AddRange(node.GetComponentsInParent<Collider>(includeInactive: true));
		}
	}

	protected void AddToStickyTree(StickyBase otherSticky)
	{
		if (parent == null)
		{
			otherSticky.children.Add(this);
			parent = otherSticky;
			return;
		}
		StickyBase treeRoot = otherSticky.TreeRoot;
		StickyBase treeRoot2 = TreeRoot;
		treeRoot.children.Add(treeRoot2);
		treeRoot2.parent = treeRoot;
	}

	protected void RemoveFromStickyTree()
	{
		if (!(parent == null))
		{
			parent.children.Remove(this);
			parent = null;
		}
	}

	public void RefreshIgnoredColliders()
	{
		if (IsAttached || Children.Count > 0)
		{
			IgnoreNodeColliders(TreeRoot, this, ignore: true);
			Tool rootNonStickyTool = RootNonStickyTool;
			if (rootNonStickyTool != null)
			{
				ToolIgnoreNodeColliders(rootNonStickyTool, this, ignore: true);
			}
		}
	}

	public static void IgnoreTreeColliders(StickyBase tree1, StickyBase tree2, bool ignore)
	{
		List<Collider> sTATIC_COLLIDERS_A = STATIC_COLLIDERS_A;
		List<Collider> sTATIC_COLLIDERS_B = STATIC_COLLIDERS_B;
		GatherTreeCollidersIgnoreSubtree(tree1, tree2, sTATIC_COLLIDERS_A);
		GatherTreeCollidersIgnoreSubtree(tree2, tree1, sTATIC_COLLIDERS_B);
		foreach (Collider item in sTATIC_COLLIDERS_A)
		{
			foreach (Collider item2 in sTATIC_COLLIDERS_B)
			{
				Physics.IgnoreCollision(item, item2, ignore);
			}
		}
	}

	public static void IgnoreNodeColliders(StickyBase tree, StickyBase node, bool ignore)
	{
		List<Collider> sTATIC_COLLIDERS_A = STATIC_COLLIDERS_A;
		List<Collider> sTATIC_COLLIDERS_B = STATIC_COLLIDERS_B;
		GatherTreeCollidersIgnoreNode(tree, node, sTATIC_COLLIDERS_A);
		GatherNodeColliders(node, sTATIC_COLLIDERS_B);
		foreach (Collider item in sTATIC_COLLIDERS_A)
		{
			foreach (Collider item2 in sTATIC_COLLIDERS_B)
			{
				Physics.IgnoreCollision(item, item2, ignore);
			}
		}
	}

	public static void ToolIgnoreTreeColliders(Tool tool, StickyBase treeRoot, bool ignore)
	{
		List<Collider> sTATIC_COLLIDERS_A = STATIC_COLLIDERS_A;
		GatherTreeColliders(treeRoot, sTATIC_COLLIDERS_A);
		IgnoreToolColliders(tool, sTATIC_COLLIDERS_A, ignore);
	}

	public static void ToolIgnoreNodeColliders(Tool tool, StickyBase node, bool ignore)
	{
		List<Collider> sTATIC_COLLIDERS_A = STATIC_COLLIDERS_A;
		GatherNodeColliders(node, sTATIC_COLLIDERS_A);
		IgnoreToolColliders(tool, sTATIC_COLLIDERS_A, ignore);
	}

	private static void IgnoreToolColliders(Tool tool, List<Collider> colliders, bool ignore)
	{
		foreach (ToolCollider collider in tool.Colliders)
		{
			foreach (Collider physicsCollider in collider.PhysicsColliders)
			{
				foreach (Collider collider2 in colliders)
				{
					Physics.IgnoreCollision(physicsCollider, collider2, ignore);
				}
			}
		}
	}

	public static void TraverseTree(StickyBase root, Action<StickyBase> operation)
	{
		TraverseTree(root, null, ignoreNodeChildren: false, operation);
	}

	public static void TraverseTree(StickyBase root, StickyBase ignoreNode, bool ignoreNodeChildren, Action<StickyBase> operation)
	{
		bool flag = root == ignoreNode;
		if (!flag)
		{
			operation(root);
		}
		if (flag && ignoreNodeChildren)
		{
			return;
		}
		foreach (StickyBase child in root.children)
		{
			TraverseTree(child, operation);
		}
	}

	public static string StickyTreeToString(StickyBase root, int nodeIndex = 0, int depth = 0)
	{
		string empty = string.Empty;
		string text = string.Empty;
		for (int i = 0; i < depth; i++)
		{
			text += " ";
		}
		string text2 = empty;
		empty = text2 + text + "|-" + nodeIndex + "\n";
		foreach (StickyBase child in root.children)
		{
			nodeIndex++;
			empty += StickyTreeToString(child, nodeIndex, depth + 1);
		}
		return empty;
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (viewData.StickyData != null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error serializing StickyBase {0}: Data already specified.", base.gameObject);
			return;
		}
		viewData.StickyData = new StickyData();
		if (!IsAttached)
		{
			return;
		}
		viewData.StickyData.IsAttached = IsAttached;
		viewData.StickyData.AttachedRelativePosition = AttachedRelativePosition.ValueOrZeroIfBogus().ToVector3Data();
		viewData.StickyData.AttachedRelativeRotation = AttachedRelativeRotation.ValueOrIdentityIfBogus().ToVector3Data();
		if (AttachedPhotonView != null)
		{
			PersistenceView component = AttachedPhotonView.GetComponent<PersistenceView>();
			if (component != null)
			{
				viewData.StickyData.ConnectedViewId = RecRoom.Protobuf.ByteStringExtensions.ToByteString(component.Id);
			}
			else
			{
				viewData.StickyData.IsAttached = false;
			}
		}
	}

	public void PreDeserialize(RoomPersistenceVersion version, PersistenceViewData viewData, Dictionary<Guid, Guid> persistenceViewIdMappings)
	{
		if (viewData.StickyData == null)
		{
			UnityEngine.Debug.LogErrorFormat(this, "Error deserializing StickyBase {0}: data empty.", base.gameObject);
		}
		else
		{
			if (!viewData.StickyData.IsAttached)
			{
				return;
			}
			Guid guid = ((!(viewData.StickyData.ConnectedViewId != null)) ? Guid.Empty : RecRoom.Protobuf.ByteStringExtensions.ToGuid(viewData.StickyData.ConnectedViewId));
			if (guid == Guid.Empty)
			{
				AuthorityTryAttach(null);
				return;
			}
			if (persistenceViewIdMappings != null && persistenceViewIdMappings.ContainsKey(guid))
			{
				guid = persistenceViewIdMappings[guid];
			}
			PersistenceView parentPersistenceView = null;
			if (!TryGetParentPersistenceView(guid, out parentPersistenceView))
			{
				UnityEngine.Debug.LogError("Unable to deserialize StickyBase, invalid parent persistence view id.");
				return;
			}
			Vector3 position = viewData.StickyData.AttachedRelativePosition.ToVector3().ValueOrZeroIfBogus();
			Quaternion rotation = Quaternion.Euler(viewData.StickyData.AttachedRelativeRotation.ToVector3().ValueOrZeroIfBogus());
			if (version == RoomPersistenceVersion.INITIAL)
			{
				position = parentPersistenceView.transform.InverseTransformPoint(base.transform.position);
			}
			base.transform.position = parentPersistenceView.transform.TransformPoint(position);
			base.transform.rotation = parentPersistenceView.transform.TransformRotation(rotation);
			AuthorityTryAttach(parentPersistenceView.photonView);
		}
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
	}

	protected bool TryGetParentPersistenceView(Guid guid, out PersistenceView parentPersistenceView)
	{
		return PersistenceView.AllViews.TryGetValue(guid, out parentPersistenceView);
	}
}
namespace RecRoom.Tools
{
	public sealed class StickyShapeContainer : StickyBase
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		[FormerlySerializedAs("extrusion")]
		private ShapeContainer shapeContainer;

		private ISchedulerPromise refreshCollidersOnShapeChange;

		public ShapeContainer ShapeContainer => shapeContainer;

		protected override void Awake()
		{
			base.Awake();
			ShapeContainer obj = ShapeContainer;
			obj.OnShapesChangedEvent = (Action)Delegate.Combine(obj.OnShapesChangedEvent, new Action(OnShapeContainerShapesChanged));
		}

		protected override void Start()
		{
			base.Start();
			OnShapeContainerShapesChanged();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			ShapeContainer obj = ShapeContainer;
			obj.OnShapesChangedEvent = (Action)Delegate.Remove(obj.OnShapesChangedEvent, new Action(OnShapeContainerShapesChanged));
		}

		protected override void AuthorityProcessStickyToolReleased()
		{
			if (!base.hasAuthority || shapeContainer.CurrentPhysicsMode != ShapeContainer.PhysicsMode.Physical_Sticky)
			{
				return;
			}
			bool stuckToSomething = false;
			StickyBase.TraverseTree(base.TreeRoot, delegate(StickyBase node)
			{
				if (!stuckToSomething)
				{
					StickyShapeContainer stickyShapeContainer = node as StickyShapeContainer;
					if (stickyShapeContainer != null)
					{
						stuckToSomething = stickyShapeContainer.TryUpdateSticking();
					}
				}
			});
		}

		public bool TryUpdateSticking()
		{
			if (shapeContainer.CheckShapeOverlaps(496383488, QueryTriggerInteraction.Ignore, TryAttachToPhotonViewOnCollider))
			{
				return true;
			}
			if (shapeContainer.CheckShapeOverlaps(2049, QueryTriggerInteraction.Ignore))
			{
				return AuthorityTryAttach(null);
			}
			return false;
		}

		private bool TryAttachToPhotonViewOnCollider(Collider collider)
		{
			PhotonView componentInParent = collider.GetComponentInParent<PhotonView>();
			if (componentInParent != null && componentInParent != base.photonView)
			{
				TryMergeIntoCostume(collider);
				if (AuthorityTryAttach(componentInParent))
				{
					return true;
				}
			}
			return false;
		}

		private void TryMergeIntoCostume(Collider collider)
		{
			if (shapeContainer is StandaloneShapeContainer)
			{
				CostumePiece componentInParent = collider.GetComponentInParent<CostumePiece>();
				if (componentInParent != null)
				{
					componentInParent.PromptToMergeExtrusion((StandaloneShapeContainer)shapeContainer);
				}
			}
		}

		private void OnShapeContainerShapesChanged()
		{
			if (refreshCollidersOnShapeChange == null || refreshCollidersOnShapeChange.IsCompleted)
			{
				refreshCollidersOnShapeChange = this.InvokeNextLateUpdate(base.RefreshIgnoredColliders);
			}
		}
	}
