namespace RecRoom.Tools.Tags
{
	public class TaggedTool : Photon.MonoBehaviour, IPersistable
	{
		public const int MAX_TAGS = 5;

		private bool displayTagsDirty;

		private bool defaultTagsInitialized;

		private int[] defaultTagIds;

		private int[] previousTagIds;

		private SynchronizedField<int[]> _tagIds;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool tool;

		private string[] displayTags;

		bool IPersistable.BlockObjectPersistance => false;

		private int[] TagIds
		{
			get
			{
				return _tagIds.Get();
			}
			set
			{
				_tagIds.Set(value);
			}
		}

		public Tool Tool => tool;

		public IEnumerable<string> DisplayTags
		{
			get
			{
				if (displayTags == null || displayTagsDirty)
				{
					displayTags = TagIds.Select((int id) => NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetTag(id)).ToArray();
					displayTagsDirty = false;
				}
				return displayTags;
			}
		}

		private void Start()
		{
			if (tool.CreationObject != null)
			{
				ButtonSettingEditEvent settingEvent = new ButtonSettingEditEvent((MakerPenPaletteConfigScreen creationObject) => creationObject.EditTagsButtonUIControlPrefab, delegate(CreationObjectSettingButtonUIControl instance)
				{
					instance.PropertyValueText.text = ((TagIds.Length <= 0) ? "This object does not have any tags." : string.Join("\n", DisplayTags.Select((string t) => $"#{t}")));
					instance.PropertyDescription.text = "Edit Tags?";
					instance.PropertySetter = delegate(bool pressed)
					{
						if (pressed && instance.MakerPen != null)
						{
							instance.MakerPen.ShowEditTagsUI();
						}
					};
				});
				tool.CreationObject.AddConfigurableSetting(settingEvent);
			}
			InitializeDefaultTagIds();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (_tagIds != null && !SessionManager.IsLoadingOrQuitting)
			{
				ReportTagUsage(TagIds, null);
			}
		}

		private void OnTagsChanged()
		{
			displayTagsDirty = true;
			int[] tagIds = TagIds;
			ReportTagUsage(previousTagIds, tagIds);
			previousTagIds = tagIds;
		}

		public bool HasTag(string tag)
		{
			int tagId;
			return HasTag(tag, out tagId);
		}

		private bool HasTag(string tag, out int tagId)
		{
			tagId = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetTagId(tag);
			return TagIds.Contains(tagId);
		}

		public void RequestAddTag(string tag)
		{
			if (CanAddTag(tag))
			{
				base.photonView.RpcMaster(MasterAddTag, new string[1] { tag });
			}
		}

		public void ResetTags()
		{
			TagIds = defaultTagIds;
		}

		public void RemoveTag(string tag)
		{
			if (!HasTag(tag, out var tagId))
			{
				return;
			}
			int[] tagIds = TagIds;
			int[] array = new int[tagIds.Length - 1];
			int num = 0;
			for (int i = 0; i < tagIds.Length; i++)
			{
				if (tagIds[i] != tagId)
				{
					array[num] = tagIds[i];
					num++;
				}
			}
			TagIds = array;
		}

		private void ReportTagUsage(int[] oldIds, int[] newIds)
		{
			if (!(NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance != null))
			{
				return;
			}
			if (oldIds != null)
			{
				foreach (int num in oldIds)
				{
					if (newIds == null || !newIds.Contains(num))
					{
						NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.RemoveTagUsage(this, num);
					}
				}
			}
			if (newIds == null)
			{
				return;
			}
			foreach (int num2 in newIds)
			{
				if (oldIds == null || !oldIds.Contains(num2))
				{
					NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.AddTagUsage(this, num2);
				}
			}
		}

		public void CopyTags(TaggedTool src)
		{
			base.photonView.RpcMaster(MasterAddTag, src.DisplayTags.ToArray());
		}

		private bool CanAddTag(string tag)
		{
			return !HasTag(tag) && TagIds.Length < 5;
		}

		public void InitializeDefaultTagIds()
		{
			if (!defaultTagsInitialized)
			{
				SpawnableTool component = GetComponent<SpawnableTool>();
				if (component != null)
				{
					defaultTagIds = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetDefaultTagIdsForEquipment(component.Type);
				}
				else
				{
					defaultTagIds = new int[0];
				}
				_tagIds = new SynchronizedField<int[]>(this, "TID", defaultTagIds, SetterPermissionMode.ANYONE, OnTagsChanged);
				defaultTagsInitialized = true;
				OnTagsChanged();
			}
		}

		[PunRPC]
		private void MasterAddTag(string[] tags)
		{
			if (!PhotonNetwork.isMasterClient || TagIds.Length == 5)
			{
				return;
			}
			int num = 0;
			foreach (string text in tags)
			{
				if (!HasTag(text))
				{
					num++;
				}
			}
			if (num == 0)
			{
				return;
			}
			int num2 = Math.Min(TagIds.Length + num, 5);
			int[] array = new int[num2];
			if (TagIds.Length > 0)
			{
				TagIds.CopyTo(array, 0);
			}
			int num3 = TagIds.Length;
			foreach (string text2 in tags)
			{
				if (!HasTag(text2))
				{
					int num4 = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.GetTagId(text2);
					if (num4 == -1)
					{
						num4 = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance.MasterAddTag(text2);
					}
					array[num3++] = num4;
					if (num3 == num2)
					{
						break;
					}
				}
			}
			TagIds = array;
		}

		public static bool CheckTagRestrictions(Tool tool, bool whitelist, List<string> tags)
		{
			if (tool.Tags == null)
			{
				return !whitelist;
			}
			for (int i = 0; i < tags.Count; i++)
			{
				if (tool.Tags.HasTag(tags[i]))
				{
					return whitelist;
				}
			}
			return !whitelist;
		}

		void IPersistable.DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			TaggedToolData taggedToolData = deserializeParams.viewData.TaggedToolData;
			if (taggedToolData == null || taggedToolData.TagData == null)
			{
				return;
			}
			RepeatedField<string> tags = taggedToolData.TagData.Tags;
			ToolTagManager instance = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance;
			int[] array = new int[tags.Count];
			for (int i = 0; i < array.Length; i++)
			{
				int num = instance.GetTagId(tags[i]);
				if (num == -1 && deserializeParams.isRuntimeCreated)
				{
					num = instance.MasterAddTag(tags[i]);
				}
				array[i] = num;
			}
			SingletonMonoBehaviour<Scheduler>.Instance.Run(this, SetCustomTagsAfterDefaultsInitialized(array));
		}

		private IEnumerator<ISchedule> SetCustomTagsAfterDefaultsInitialized(int[] tagIds)
		{
			yield return Schedule.Until(() => _tagIds != null);
			TagIds = tagIds;
		}

		void IPersistable.SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			if (!_tagIds.HasValue)
			{
				return;
			}
			bool flag = false;
			int[] tagIds = TagIds;
			if (tagIds.Length != defaultTagIds.Length)
			{
				flag = true;
			}
			else
			{
				for (int i = 0; i < tagIds.Length; i++)
				{
					if (tagIds[i] != defaultTagIds[i])
					{
						flag = true;
					}
				}
			}
			if (flag)
			{
				TaggedToolData taggedToolData = new TaggedToolData();
				taggedToolData.TagData = new TagData();
				RepeatedField<string> tags = taggedToolData.TagData.Tags;
				ToolTagManager instance = NetworkedSingletonMonoBehaviour<ToolTagManager>.Instance;
				int[] array = tagIds;
				foreach (int tagId in array)
				{
					string item = instance.GetTag(tagId);
					tags.Add(item);
				}
				viewData.TaggedToolData = taggedToolData;
			}
		}
	}
	public class ToolTagManager : NetworkedSingletonMonoBehaviour<ToolTagManager>, IPersistableSettings
	{
		private class TagInfo
		{
			private readonly List<TaggedTool> taggedTools = new List<TaggedTool>();

			private readonly int tagId;

			public bool HasTaggedTools => taggedTools.Count > 0;

			public TagInfo(int tagId)
			{
				this.tagId = tagId;
			}

			public void AddTaggedTool(TaggedTool tool)
			{
				if (tool.Tool.IsHeldByPlayer)
				{
					taggedTools.Insert(0, tool);
				}
				else
				{
					taggedTools.Add(tool);
				}
				tool.Tool.HolderChangedEvent += OnToolHolderChanged;
			}

			public bool RemoveTaggedTool(TaggedTool tool)
			{
				if (tool.Tool != null)
				{
					tool.Tool.HolderChangedEvent -= OnToolHolderChanged;
				}
				return taggedTools.Remove(tool);
			}

			public TaggedTool GetLeastRecentlyUsedTaggedTool()
			{
				if (taggedTools.Count > 0)
				{
					TaggedTool taggedTool = taggedTools[taggedTools.Count - 1];
					MoveToolToFront(taggedTool);
					return taggedTool;
				}
				return null;
			}

			private void OnToolHolderChanged(Tool thisTool)
			{
				if (thisTool.IsHeldByPlayer && thisTool.Tags != null)
				{
					MoveToolToFront(thisTool.Tags);
				}
			}

			private void MoveToolToFront(TaggedTool tags)
			{
				if (taggedTools.Count > 1 && taggedTools.Remove(tags))
				{
					taggedTools.Insert(0, tags);
				}
			}

			public ReadOnlyCollection<TaggedTool> GetAllTaggedTools()
			{
				return taggedTools.AsReadOnly();
			}
		}

		public const int MAX_TAG_NAME_LENGTH = 25;

		private const int DEFAULT_RUNTIME_TAG_LENGTH = 12;

		private static readonly List<TaggedTool> EMPTY_TOOL_LIST = new List<TaggedTool>(0);

		private static readonly Dictionary<SpawnableToolType, int[]> DefaultToolTagIds = new Dictionary<SpawnableToolType, int[]>();

		private static IndexedMap<string> _defaultTagIndices = null;

		private IndexedMap<string> runtimeTagIndices;

		private Dictionary<int, TagInfo> tagInfoDictionary = new Dictionary<int, TagInfo>();

		private bool tagsInitialized;

		private static IndexedMap<string> DefaultTagIndices
		{
			get
			{
				if (_defaultTagIndices == null)
				{
					InitializeDefaultTags();
				}
				return _defaultTagIndices;
			}
		}

		private int RuntimeIndexOffset => DefaultTagIndices.Count;

		public static string FormatTag(string tag)
		{
			if (tag.Length > 25)
			{
				string text = tag.ToLower().Substring(0, 25);
				UnityEngine.Debug.LogWarningFormat("TagManager: Shortening tag name from {0} to {1}", tag, text);
				tag = text;
			}
			return tag;
		}

		protected override void Awake()
		{
			base.Awake();
			PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
			runtimeTagIndices = new IndexedMap<string>(12);
		}

		private void Start()
		{
			if (PhotonNetwork.isMasterClient)
			{
				tagsInitialized = true;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		private static void InitializeDefaultTags()
		{
			SpawnableToolConfig.Config[] configs = SpawnableToolSettings.ConfigAsset.Configs;
			_defaultTagIndices = new IndexedMap<string>(configs.Length);
			SpawnableToolConfig.Config[] configs2 = SpawnableToolSettings.ConfigAsset.Configs;
			foreach (SpawnableToolConfig.Config config in configs2)
			{
				string[] defaultTagNames = config.DefaultTagNames;
				foreach (string text in defaultTagNames)
				{
					string value = FormatTag(text);
					if (!string.IsNullOrEmpty(value))
					{
						_defaultTagIndices.TryAdd(value);
					}
				}
			}
		}

		private void OnPhotonPlayerConnected(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient)
			{
				IndexedMap<string>.Pair[] arg = runtimeTagIndices.ToArray();
				base.photonView.RpcPlayer(player, RemoteSetRuntimeTags, arg);
			}
		}

		private void OnMasterClientSwitched(PhotonPlayer player)
		{
			if (PhotonNetwork.isMasterClient)
			{
				IndexedMap<string>.Pair[] arg = runtimeTagIndices.ToArray();
				base.photonView.RpcOthers(RemoteSetRuntimeTags, arg);
			}
		}

		public string GetTag(int tagId)
		{
			if (tagId < RuntimeIndexOffset)
			{
				return DefaultTagIndices.GetValue(tagId);
			}
			int index = GlobalToRuntimeIndex(tagId);
			return runtimeTagIndices.GetValue(index);
		}

		public int GetTagId(string tag)
		{
			int index = DefaultTagIndices.GetIndex(tag);
			if (index == -1)
			{
				index = runtimeTagIndices.GetIndex(tag);
				if (index != -1)
				{
					return RuntimeToGlobalIndex(index);
				}
				return -1;
			}
			return index;
		}

		public int[] GetDefaultTagIdsForEquipment(SpawnableToolType equipmentType)
		{
			if (!DefaultToolTagIds.TryGetValue(equipmentType, out var value))
			{
				string[] spawnableToolDefaultTags = SpawnableToolSettings.GetSpawnableToolDefaultTags(equipmentType);
				value = new int[spawnableToolDefaultTags.Length];
				for (int i = 0; i < spawnableToolDefaultTags.Length; i++)
				{
					if ((value[i] = GetTagId(spawnableToolDefaultTags[i])) == -1)
					{
						UnityEngine.Debug.LogErrorFormat("Default tag ID missing for tag {0}");
					}
				}
				DefaultToolTagIds[equipmentType] = value;
			}
			return value;
		}

		public int MasterAddTag(string tag)
		{
			tag = FormatTag(tag);
			int num = -1;
			if (!string.IsNullOrEmpty(tag) && PhotonNetwork.isMasterClient)
			{
				num = RuntimeToGlobalIndex(runtimeTagIndices.Count);
				base.photonView.RpcAll(RemoteAddTag, tag, num);
			}
			return num;
		}

		private void LocalAddRuntimeTag(string tag, int id)
		{
			int index = GlobalToRuntimeIndex(id);
			bool flag = runtimeTagIndices.TryAdd(tag, index);
		}

		public TaggedTool GetLeastRecentlyUsedTool(string tag)
		{
			int tagId = GetTagId(tag);
			return GetLeastRecentlyUsedTool(tagId);
		}

		public TaggedTool GetLeastRecentlyUsedTool(int tagId)
		{
			return GetTagInfo(tagId, allocateIfEmpty: false)?.GetLeastRecentlyUsedTaggedTool();
		}

		public ReadOnlyCollection<TaggedTool> GetToolsWithTag(string tag)
		{
			int tagId = GetTagId(tag);
			return GetToolsWithTag(tagId);
		}

		public ReadOnlyCollection<TaggedTool> GetToolsWithTag(int id)
		{
			TagInfo tagInfo = GetTagInfo(id, allocateIfEmpty: false);
			if (tagInfo != null)
			{
				return tagInfo.GetAllTaggedTools();
			}
			return EMPTY_TOOL_LIST.AsReadOnly();
		}

		public void AddTagUsage(TaggedTool tool, int id)
		{
			TagInfo tagInfo = GetTagInfo(id, allocateIfEmpty: true);
			tagInfo.AddTaggedTool(tool);
		}

		public void RemoveTagUsage(TaggedTool tool, int id)
		{
			if (!SessionManager.IsLoadingOrQuitting)
			{
				GetTagInfo(id, allocateIfEmpty: false)?.RemoveTaggedTool(tool);
			}
		}

		private TagInfo GetTagInfo(int tagId, bool allocateIfEmpty)
		{
			TagInfo value = null;
			if (!tagInfoDictionary.TryGetValue(tagId, out value) && allocateIfEmpty)
			{
				value = new TagInfo(tagId);
				tagInfoDictionary[tagId] = value;
			}
			return value;
		}

		private int GlobalToRuntimeIndex(int id)
		{
			return id - RuntimeIndexOffset;
		}

		private int RuntimeToGlobalIndex(int id)
		{
			return id + RuntimeIndexOffset;
		}

		[PunRPC]
		private void RemoteAddTag(string tag, int id)
		{
			LocalAddRuntimeTag(tag, id);
		}

		[PunRPC]
		private void RemoteSetRuntimeTags(IndexedMap<string>.Pair[] tagPairs, PhotonMessageInfo messageInfo)
		{
			if (messageInfo.sender.IsMasterClient)
			{
				runtimeTagIndices = IndexedMap<string>.FromArray(tagPairs, expand: true);
				tagsInitialized = true;
			}
		}

		public static short SerializeTagPair(StreamBuffer outStream, object customObject)
		{
			IndexedMap<string>.Pair pair = (IndexedMap<string>.Pair)customObject;
			short num = (short)Encoding.UTF8.GetBytes(pair.value).Length;
			int num2 = 6 + num;
			byte[] array = new byte[num2];
			int targetOffset = 0;
			Protocol.Serialize(num, array, ref targetOffset);
			Protocol.Serialize(pair.index, array, ref targetOffset);
			Array.Copy(Encoding.UTF8.GetBytes(pair.value), 0, array, targetOffset, num);
			outStream.Write(array, 0, num2);
			return (short)num2;
		}

		public static object DeserializeTagPair(StreamBuffer inStream, short length)
		{
			IndexedMap<string>.Pair pair = default(IndexedMap<string>.Pair);
			byte[] array = new byte[2];
			int offset = 0;
			inStream.Read(array, 0, 2);
			Protocol.Deserialize(out short value, array, ref offset);
			byte[] array2 = new byte[4 + value];
			inStream.Read(array2, 0, 4 + value);
			offset = 0;
			Protocol.Deserialize(out pair.index, array2, ref offset);
			pair.value = Encoding.UTF8.GetString(array2, offset, value);
			return pair;
		}

		void IPersistableSettings.DeserializeFrom(PersistedRoomData roomData)
		{
			ToolTagSettingsData toolTagSettingsData = roomData.ToolTagSettingsData;
			if (runtimeTagIndices.Count != 0 || toolTagSettingsData == null || toolTagSettingsData.RuntimeTagData == null || toolTagSettingsData.RuntimeTagData.Tags.Count <= 0)
			{
				return;
			}
			RepeatedField<string> tags = toolTagSettingsData.RuntimeTagData.Tags;
			foreach (string item in tags)
			{
				runtimeTagIndices.TryAdd(item);
			}
			if (PhotonNetwork.otherPlayers.Length > 0)
			{
				IndexedMap<string>.Pair[] arg = runtimeTagIndices.ToArray();
				base.photonView.RpcOthers(RemoteSetRuntimeTags, arg);
			}
			tagsInitialized = true;
		}

		void IPersistableSettings.SerializeTo(ref PersistedRoomData roomData)
		{
			TagData tagData = new TagData();
			if (runtimeTagIndices.Count > 0)
			{
				foreach (IndexedMap<string>.Pair item in (IEnumerable<IndexedMap<string>.Pair>)runtimeTagIndices)
				{
					TagInfo tagInfo = GetTagInfo(GetTagId(item.value), allocateIfEmpty: false);
					if (tagInfo != null && tagInfo.HasTaggedTools)
					{
						tagData.Tags.Add(item.value);
					}
				}
			}
			roomData.ToolTagSettingsData = new ToolTagSettingsData
			{
				RuntimeTagData = tagData
			};
		}
	}
	public class TagEditDialog : UIDialog<List<string>, int, TagEditDialog.InputResponse>
	{
		public struct InputResponse
		{
			public List<string> NewTags;

			public ConfirmDialogResponses Response;
		}

		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		[SerializeField]
		private TagPagedGrid pagedGrid;

		[SerializeField]
		private Button3D addTagButton;

		internal List<string> CurrentTags = new List<string>();

		private int maxTags = 5;

		private InputResponse CreateResponse(ConfirmDialogResponses response)
		{
			return new InputResponse
			{
				NewTags = CurrentTags,
				Response = response
			};
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(CreateResponse(ConfirmDialogResponses.Cancel), shouldCloseDialog);
		}

		public override IPromise<InputResponse> ShowDialog(List<string> currentTags = null, int maxTags = 5)
		{
			if (currentTags != null)
			{
				CurrentTags = currentTags;
			}
			this.maxTags = maxTags;
			pagedGrid.UpdateChildren(CurrentTags);
			OnTagCountChanged();
			return base.ShowDialog();
		}

		public void Button_AddTag()
		{
			if (!Player.LocalPlayerExists)
			{
				return;
			}
			IPromise<TextInputUIDialog.InputResponse> promise = Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.Alphanumeric, "Enter New Tag", "Enter new tag", "Add", purifyText: false, 25, null, shouldFocusInputField: true));
			promise.Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative && !string.IsNullOrEmpty(r.TextInput))
				{
					string item = ToolTagManager.FormatTag(r.TextInput);
					if (!CurrentTags.Contains(item))
					{
						CurrentTags.Add(item);
						pagedGrid.UpdateChildren(CurrentTags);
						OnTagCountChanged();
					}
				}
			});
		}

		public void Button_Done()
		{
			Respond(CreateResponse(ConfirmDialogResponses.Affirmative), shouldCloseDialog: true);
		}

		internal void RemoveTag(string tag)
		{
			if (CurrentTags.Remove(tag))
			{
				OnTagCountChanged();
				pagedGrid.UpdateChildren(CurrentTags);
			}
		}

		private void OnTagCountChanged()
		{
			addTagButton.Interactable = CurrentTags.Count < maxTags;
		}
	}
