[DisallowMultipleComponent]
public class TeamColorRenderer : Photon.MonoBehaviour, ICustomImposterBehavior
{
	public delegate void SetColorBehavior(Color color, bool resetToDefault);

	[SerializeField]
	private bool teamSetByOwner = true;

	[SerializeField]
	private RendererMaterialPair[] teamColorRenderers;

	[SerializeField]
	private string colorPropertyName = "_Color";

	[SerializeField]
	private bool applyToSkins;

	public SetColorBehavior CustomSetColorBehavior;

	private Tool tool;

	private GameManager gameManager;

	private Color? overrideColor;

	private int colorPropertyId;

	private Color[] defaultColors;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_ColorChangeEvent;

	private GameTeam _team = GameTeam.ANY;

	private Color _color = Color.green;

	public bool TeamSetByOwner => teamSetByOwner;

	public GameTeam Team
	{
		get
		{
			return _team;
		}
		set
		{
			_team = value;
			UpdateColor();
		}
	}

	public bool IsValidTeam
	{
		get
		{
			if (!GameSessions.LocalGameSession.IsSandbox && gameManager != null && gameManager.TeamManager.MaxTeamCount <= 1)
			{
				return false;
			}
			return _team != GameTeam.ANY;
		}
	}

	public Color Color => _color;

	public event Action ColorChangeEvent
	{
		add
		{
			Action action = this.m_ColorChangeEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ColorChangeEvent, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_ColorChangeEvent;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ColorChangeEvent, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void UpdateColor()
	{
		Color? color = overrideColor;
		if (color.HasValue && overrideColor.HasValue)
		{
			SetColor(overrideColor.Value, resetMaterialsToDefault: false);
		}
		else if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			SetColor(NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamColor(Team), !IsValidTeam);
		}
		else
		{
			SetColor(GameTeamSettings.GetDefaultTeamColor(Team), !IsValidTeam);
		}
	}

	protected override void Awake()
	{
		base.Awake();
		CacheDefaultColors();
		tool = GetComponent<Tool>();
		if (tool != null && teamSetByOwner)
		{
			tool.PostPickupEvent += OnToolPickup;
			tool.PostReleaseEvent += OnToolRelease;
			tool.PostResetEvent += OnToolReset;
		}
	}

	private void Start()
	{
		gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
		UpdateColor();
		if (teamSetByOwner)
		{
			RefreshOwnerTeam();
		}
		if (tool.SkinMapper != null)
		{
			tool.SkinMapper.ActiveSkinChanged += SkinMapper_ActiveSkinChanged;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnGameTeamChange;
		}
		if (tool != null)
		{
			tool.PostPickupEvent -= OnToolPickup;
			tool.PostReleaseEvent -= OnToolRelease;
			tool.PostResetEvent -= OnToolReset;
		}
	}

	private void OnToolPickup(Tool tool)
	{
		RefreshOwnerTeam();
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent += OnGameTeamChange;
		}
	}

	private void OnToolRelease(Tool tool)
	{
		if (gameManager != null)
		{
			gameManager.TeamManager.TeamChangeEvent -= OnGameTeamChange;
		}
	}

	private void OnToolReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		Team = GameTeam.ANY;
	}

	private void SkinMapper_ActiveSkinChanged(EquipmentSkin skin)
	{
		if (skin == null || applyToSkins)
		{
			UpdateColor();
		}
	}

	private void OnGameTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		if (base.owner == changingTeamPlayer && tool.IsHeld && teamSetByOwner)
		{
			RefreshOwnerTeam();
		}
	}

	public void SetOverrideColor(Color color)
	{
		overrideColor = color;
		UpdateColor();
	}

	public void ClearOverrideColor()
	{
		overrideColor = null;
		UpdateColor();
	}

	public void ClearOwnerTeam()
	{
		Team = GameTeam.ANY;
	}

	public void RefreshOwnerTeam()
	{
		if (teamSetByOwner)
		{
			PhotonPlayer player = base.photonView.owner;
			if (gameManager != null && !gameManager.IsDisabled)
			{
				Team = gameManager.TeamManager.GetPlayerTeam(player);
			}
		}
	}

	void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
	{
		Team = parameters.teamOverride;
	}

	private void CacheDefaultColors()
	{
		colorPropertyId = Shader.PropertyToID(colorPropertyName);
		defaultColors = new Color[teamColorRenderers.Length];
		for (int i = 0; i < teamColorRenderers.Length; i++)
		{
			ref Color reference = ref defaultColors[i];
			reference = teamColorRenderers[i].Material.GetColor(colorPropertyId);
		}
	}

	private void SetColor(Color color, bool resetMaterialsToDefault)
	{
		_color = color;
		if (teamColorRenderers != null && teamColorRenderers.Length > 0 && (applyToSkins || tool == null || tool.SkinMapper == null || !tool.SkinMapper.HasActiveSkin))
		{
			if (defaultColors == null)
			{
				CacheDefaultColors();
			}
			for (int i = 0; i < teamColorRenderers.Length; i++)
			{
				Color value = color;
				if (resetMaterialsToDefault)
				{
					value = defaultColors[i];
				}
				teamColorRenderers[i].Material.SetColor(colorPropertyId, value);
			}
		}
		if (CustomSetColorBehavior != null)
		{
			CustomSetColorBehavior(color, resetMaterialsToDefault);
		}
		if (this.ColorChangeEvent != null)
		{
			this.ColorChangeEvent();
		}
	}
}
