	public class TearStripChest : BaseOpenableChest
	{
		[Autofill(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		private TearStripTab stripTab;

		[SerializeField]
		private float openingDuration = 1f;

		private Timer timer = new Timer();

		public override Tool Handle => stripTab.Tool;

		protected override float UpdateOpeningStateNonAuthorityUpdateHz
		{
			[CompilerGenerated]
			get
			{
				return 0f;
			}
		}

		protected override float UpdateClosedStateNonAuthorityUpdateHz
		{
			[CompilerGenerated]
			get
			{
				return 0f;
			}
		}

		private void OnStripTornOff(TearStripTab thisTab)
		{
			if (base.hasAuthority && stateMachine.CurrentStateId != 2)
			{
				stateMachine.EnterState(2);
			}
		}

		protected override void Awake()
		{
			base.OnUpdateClosedState += _OnUpdateClosedState;
			base.OnUpdateOpeningState += _OnUpdateOpeningState;
			base.Awake();
		}

		private void _OnUpdateClosedState()
		{
			if (base.hasAuthority && stripTab.IsTorn)
			{
				stateMachine.EnterState(1);
			}
		}

		protected override void OnEnterOpeningState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterOpeningState(previousStateId, previousSubStateId);
			timer.StartTimer(openingDuration);
		}

		private void _OnUpdateOpeningState()
		{
			if (base.hasAuthority && timer.TimerOver)
			{
				stateMachine.EnterState(2);
			}
		}

		protected override void OnEnterOpenState(ushort previousStateId, ushort previousSubStateId)
		{
			base.OnEnterOpenState(previousStateId, previousSubStateId);
			if (!stripTab.IsTorn)
			{
				stripTab.TearOff();
			}
		}
	}
