namespace RecRoom.Core
{
	public class TearStripTab : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Tool tool;

		[Autofill(AutofillType.SelfAndParent, false)]
		[SerializeField]
		private TearStripChest chest;

		[Header("Tear Strip")]
		[SerializeField]
		private RecRoomAudioClip poppingSound;

		[SerializeField]
		private SkinnedMeshRenderer meshRenderer;

		[SerializeField]
		private Transform transformWhenTearing;

		[Header("Autotear Settings")]
		[SerializeField]
		private float autoTearStartPercentage = 0.5f;

		[SerializeField]
		private float autoTearDuration = 0.5f;

		public bool TearingEnabled = true;

		private bool isAutoTearing;

		private bool torn;

		private bool tearing;

		private ToolCleanup toolCleanup;

		private int linksPopped;

		private Transform[] linkBones;

		private BezierPath stripPath;

		private Vector3 unbrokenStripEnd;

		private float unbrokenStripLength;

		private float maxStripLength;

		private Vector3 unbrokenStripTangent;

		private float linkLength;

		public Tool Tool => tool;

		public AxisConstrainedRigidbodyPickup ConstrainedRigidbodyPickup { get; private set; }

		public bool IsTorn => torn;

		public TearStripChest Chest => chest;

		private void Awake()
		{
			if (Tool == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing tool component.");
			}
			else
			{
				Tool.PostPickupEvent += OnPostPickup;
				Tool.PostReleaseEvent += OnPostRelease;
				Tool.PostResetEvent += OnReset;
				Tool.AllowedToTransferOwnershipOnCollision = false;
				Tool.RigidbodyEx.AddKinematic(this);
				Tool.CustomAuthorityResetOnKillzoneBehavior = AuthorityResetOnKillzoneBehavior;
			}
			ConstrainedRigidbodyPickup = GetComponent<AxisConstrainedRigidbodyPickup>();
			if (meshRenderer != null)
			{
				linkBones = meshRenderer.bones;
			}
			stripPath = new BezierPath();
			if (linkBones.Length > 0)
			{
				unbrokenStripTangent = linkBones[0].up;
				unbrokenStripEnd = linkBones.LastItem().position;
				maxStripLength = (linkBones[0].position - unbrokenStripEnd).magnitude;
				linkLength = maxStripLength / (float)(linkBones.Length - 1);
				unbrokenStripLength = maxStripLength - linkLength;
				ConstrainedRigidbodyPickup.sphericalRestrictionCenter = unbrokenStripEnd;
				ConstrainedRigidbodyPickup.sphericalRestrictionRadius = linkLength;
				ConstrainedRigidbodyPickup.constrainToSphere = true;
			}
		}

		private void FixedUpdate()
		{
			if (tearing && !torn && Tool.HolderHand != null && TearingEnabled)
			{
				Vector3 vector = Tool.HolderHand.transform.position - unbrokenStripEnd;
				float num = maxStripLength - unbrokenStripLength;
				if (linksPopped < linkBones.Length - 1 && Vector3.Dot(vector, base.transform.parent.right) > linkLength && vector.sqrMagnitude > num * num)
				{
					TearLink(vector, num);
				}
				UpdateLinks(vector, num);
			}
			else if (isAutoTearing)
			{
				UpdateLinks(base.transform.parent.right, maxStripLength - unbrokenStripLength);
			}
		}

		private void UpdateLinks(Vector3 unbrokenToHand, float maxDistanceUnbrokenToTab)
		{
			stripPath.Clear();
			float magnitude = (base.transform.position - unbrokenStripEnd).magnitude;
			unbrokenStripEnd = linkBones[0].position + unbrokenStripTangent * unbrokenStripLength;
			Vector3 controlPoint = unbrokenStripEnd + unbrokenStripTangent * magnitude / 5f;
			Vector3 controlPoint2 = base.transform.position - unbrokenToHand.normalized * magnitude / 3f;
			stripPath.AddCurve(unbrokenStripEnd, controlPoint, controlPoint2, base.transform.position);
			Transform transform = null;
			int num = linkBones.Length - linksPopped - 1;
			for (int i = num; i < linkBones.Length - 1; i++)
			{
				transform = linkBones[i];
				transform.position = stripPath.EvaluatePath((float)(i - num) / (float)linksPopped);
				Vector3 zero = Vector3.zero;
				Vector3 normalized = Vector3.Cross(rhs: (i != linkBones.Length - 2) ? (linkBones[i + 1].position - transform.position) : (base.transform.position - transform.position), lhs: base.transform.up).normalized;
				transform.LookAt(transform.position + normalized);
			}
			ConstrainedRigidbodyPickup.sphericalRestrictionCenter = unbrokenStripEnd;
			ConstrainedRigidbodyPickup.sphericalRestrictionRadius = maxDistanceUnbrokenToTab;
		}

		private IEnumerator AutoTear()
		{
			isAutoTearing = true;
			float popTimePerLink = autoTearDuration / (float)(linkBones.Length - linksPopped);
			while (linksPopped < linkBones.Length - 1)
			{
				TearLink(base.transform.parent.right, maxStripLength - unbrokenStripLength);
				yield return new WaitForSeconds(popTimePerLink);
			}
			if (Tool.HolderHand == null)
			{
				Tool.RigidbodyEx.useGravity = true;
				Tool.RigidbodyEx.RemoveKinematic(this);
			}
		}

		private void TearLink(Vector3 unbrokenToHand, float maxDistanceUnbrokenToTab)
		{
			unbrokenStripLength = Mathf.Max(unbrokenStripLength - linkLength, 0f);
			PopLink();
			linksPopped++;
			if (linksPopped == linkBones.Length - Mathf.RoundToInt((float)linkBones.Length * autoTearStartPercentage))
			{
				StartCoroutine(AutoTear());
			}
			else if (linksPopped >= linkBones.Length - 1)
			{
				TearOff();
			}
		}

		private void OnDestroy()
		{
			if (Tool != null)
			{
				Tool.PostPickupEvent -= OnPostPickup;
				Tool.PostReleaseEvent -= OnPostRelease;
				Tool.PostResetEvent -= OnReset;
			}
		}

		private bool AuthorityResetOnKillzoneBehavior(Tool thisTool, Killzone killzone)
		{
			return true;
		}

		private void OnPostPickup(Tool tool)
		{
			tearing = true;
			if (transformWhenTearing != null)
			{
				base.transform.SetParent(transformWhenTearing);
			}
		}

		private void OnPostRelease(Tool tool)
		{
			if (torn)
			{
				tool.RigidbodyEx.useGravity = true;
				tool.RigidbodyEx.RemoveKinematic(this);
			}
		}

		private void OnReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (tool.hasAuthority && wasCleanedUp)
			{
				PhotonNetwork.Destroy(base.gameObject);
			}
		}

		public void TearOff()
		{
			ConstrainedRigidbodyPickup.SetAllConstraints(constrain: false);
			meshRenderer.enabled = false;
			torn = true;
		}

		private void PopLink()
		{
			AudioManager.Play3DSFX(poppingSound, base.transform.position);
			if (Tool.HolderHand != null && Tool.HolderHand.isLocal)
			{
				Tool.HolderHand.Vibrate(50);
			}
		}
	}
}
[DisallowMultipleComponent]
public sealed class Tool : Photon.MonoBehaviour, IPostDeserializationPersistable, IPlayerPointOfInterest
{
	public enum GravityPickup
	{
		SNAP_POSITION_SNAP_ORIENTATION = 0,
		SNAP_POSITION_MAINTAIN_ORIENTATION = 1,
		MAINTAIN_POSITION_MAINTAIN_ORIENTATION = 2,
		DISABLED = -1
	}

	public enum ScreenToolPickupType
	{
		MAIN_HAND_HELD,
		TEMPORARY_OFF_HAND_HELD,
		INTERACT_WITHOUT_HANDS,
		REQUIRES_BOTH_HANDS,
		PERMANENT_OFF_HAND_HELD
