	public bool IsLocked
	{
		get
		{
			return _isLocked;
		}
		set
		{
			if (_isLocked != value)
			{
				_isLocked = value;
				OnIsLockedChanged();
			}
		}
	}

	public bool IsEnabled
	{
		get
		{
			return _isEnabled.Get();
		}
		set
		{
			if (IsEnabled != value && (base.hasAuthority || PhotonNetwork.isMasterClient))
			{
				if (this.AuthorityPreEnabledChangeEvent != null)
				{
					this.AuthorityPreEnabledChangeEvent(this, value);
				}
				_isEnabled.Set(value);
			}
		}
	}

	public bool IsFrozen => CreationObject != null && CreationObject.IsFrozen;

	public bool ManagesOwnIgnoreState
	{
		get
		{
			return _managesOwnIgnoreState.Get();
		}
		set
		{
			_managesOwnIgnoreState.Set(value);
		}
	}

	public Player Owner
	{
		get
		{
			if (base.authority != null)
			{
				return base.authority.TagObject as Player;
			}
			return Player.LocalPlayer;
		}
	}

	public bool IsVisible
	{
		get
		{
			if (CustomVisibilityBehavior != null)
			{
				return CustomVisibilityBehavior();
			}
			return _isVisible;
		}
		private set
		{
			_isVisible = value;
			UpdateRendererVisibility();
			SetCollisionEnabled(_isVisible, isVisibleToken);
		}
	}

