	public bool AllowedToTakeOwnership
	{
		get
		{
			if (CreationObject != null && CreationObject.IsLocked && !CreationObject.LocalPlayerHasLock)
			{
				return false;
			}
			if ((IsHeldByPlayer || IsEquippedOnPlayer) && HolderPlayer != null && HolderPlayer != Player.LocalPlayer && (PlayerSpawnedEquipment == null || !PlayerSpawnedEquipment.IsMine))
			{
				return false;
			}
			return true;
		}
	}

	public bool IsScreensOffHand => screenSettings.PickupType == ScreenToolPickupType.PERMANENT_OFF_HAND_HELD || screenSettings.PickupType == ScreenToolPickupType.TEMPORARY_OFF_HAND_HELD;

	public ScreenToolPickupType ScreenPickupType => screenSettings.PickupType;

	public bool ScreenPickupWithLeftHand => screenSettings.PickupWithLeftHand;

	public bool IsValidPointOfInterest
	{
		get
		{
			if (!screenSettings.SupportsPointOfInterest)
			{
				return false;
			}
			if (customScreensValidPointOfInterestConditions.Count > 0)
			{
				foreach (ScreensValidPointOfInterestCondition customScreensValidPointOfInterestCondition in customScreensValidPointOfInterestConditions)
				{
					if (!customScreensValidPointOfInterestCondition(this))
					{
						return false;
					}
				}
			}
			if (IsHeld)
			{
				return false;
			}
			return true;
		}
	}

