	public ToolUI Menu
	{
		get
		{
			Tool tool = ((!(ParentTool != null)) ? this : ParentTool);
			if (_menu == null && (tool.PlayerSpawnedEquipment == null || tool.PlayerSpawnedEquipment.IsMine) && menuSettings.menuPrefab != null && menuSettings.menuProjector != null && menuSettings.menuAnchorTransform != null)
			{
				_menu = UnityEngine.Object.Instantiate(menuSettings.menuPrefab, menuSettings.menuAnchorTransform, worldPositionStays: false);
				_menu.transform.localPosition = Vector3.zero;
				_menu.transform.localRotation = Quaternion.identity;
				_menu.transform.localScale = Vector3.one;
				_menu.MenuBoxCollider.gameObject.transform.SetParent(menuSettings.menuProjector.transform);
			}
			return _menu;
		}
	}

