	public Tool ParentTool
	{
		get
		{
			return _parentTool;
		}
		private set
		{
			if (_parentTool != value)
			{
				if (_parentTool != null)
				{
					_parentTool.childTools.Remove(this);
				}
				_parentTool = value;
				if (_parentTool != null && !_parentTool.childTools.Contains(this))
				{
					_parentTool.childTools.Add(this);
				}
			}
		}
	}

