	{
		if (animateInOut != null)
		{
			animateInOut.PlayEffect(animIn, position, rotation, dontSuppress);
		}
	}

	public void AuthoritySetAnimateInOut(bool shouldAnimateIn, bool shouldAnimateOut)
	{
		if (base.hasAuthority)
		{
			base.photonView.RpcAll(RpcSetAnimateInOut, shouldAnimateIn, shouldAnimateOut);
		}
	}

	public bool TryGetPickupTooltipString(ref string tooltipString)
	{
		if (screenSettings.HasPickupTooltipString)
		{
			tooltipString = screenSettings.PickupTooltipString;
			return true;
		}
		return false;
	}

	public void AddLockOnPickup(bool newValue, object token)
	{
		_lockOnPickup.AddValue(newValue, token);
	}

	public void RemoveLockOnPickup(object token)
	{
		_lockOnPickup.RemoveValue(token);
	}

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		PhotonNetwork.OnPhotonPlayerDisconnected += new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		base.photonView.OnPreDestroyOfRuntimeParentedPhotonView += OnRuntimeParentedPhotonViewDestroyed;
		SpawnableTool component = GetComponent<SpawnableTool>();
		spawnableToolType = ((!(component != null)) ? SpawnableToolType.INVALID : component.Type);
		if (base.transform.parent != null)
		{
			ParentTool = base.transform.parent.GetComponentInParent<Tool>();
		}
		LastSpawnPosition = (LastWorldSpacePickupPosition = base.transform.position);
		LastSpawnRotation = (LastWorldSpacePickupRotation = base.transform.rotation);
		NetworkTransform.RunCollisionDetectionWhileExtrapolating = true;
		NetworkTransform obj = NetworkTransform;
		obj.ValidPositionBoundsExceeded = (Action)Delegate.Combine(obj.ValidPositionBoundsExceeded, new Action(OnValidPositionBoundsExceeded));
		RigidbodyEx.SleepChangedEvent += OnSleepChanged;
		if (collisionSettings.DynamicKinematicCollisionsCanBeApplied)
		{
			RigidbodyEx.LateUpdateEvent += UpdateDynamicKinematicCollision;
		}
		if (animateInOut == null && !renderSettings.SuppressAnimateInOut)
		{
			animateInOut = base.gameObject.AddComponent<AnimateInOut>();
			if (IsSubTool)
			{
				SuppressAnimateInOut = true;
			}
		}
		else if (animateInOut != null)
		{
			if (renderSettings.SuppressAnimateInOut)
			{
				UnityEngine.Object.Destroy(animateInOut);
				animateInOut = null;
			}
			else
			{
				SuppressAnimateInOut = IsSubTool || animateInOut.SuppressAnimation;
				SupportsAnimateIn = animateInOut.SupportsAnimateIn;
				SupportsAnimateOut = animateInOut.SupportsAnimateOut;
			}
		}
		if (Animator != null && !renderSettings.ShouldAnimateWhileNotHeld)
		{
			Animator.enabled = false;
		}
		InitializeColliders();
		InitializeRenderers();
		if (!IsSubTool)
		{
			ToolCleanup = ToolCleanup.VerifyToolCleanup(base.gameObject);
		}
		_isEnabled = new SynchronizedField<bool>(this, "TE", defaultValue: true, SetterPermissionMode.MASTER_OR_AUTHORITY, OnIsEnabledChanged);
		_managesOwnIgnoreState = new SynchronizedField<bool>(this, "TMOIS", !IsSubTool, SetterPermissionMode.MASTER, RefreshCheckForIgnoredSchedulerUpdates);
		_holderInfo = new SynchronizedField<ToolHolderInfo>(this, "TH", ToolHolderInfo.NotHeld, SetterPermissionMode.ANYONE, OnHolderInfoChanged);
		AddLockOnPickup(interactionSettings.LockOnPickup, LOCK_ON_PICKUP_TOKEN);
		WasRuntimeInstantiated = base.photonView.instantiationData != null && base.photonView.instantiationData.Length > 0;
		if (!IsSubTool && WasRuntimeInstantiated && Tool.StaticToolInstantiatedEvent != null)
		{
			Tool.StaticToolInstantiatedEvent(this);
			if (InstantiationParameters != null && InstantiationParameters.ContainsKey("InvisibleOnSpawn"))
			{
				IsVisible = false;
			}
		}
		PostAwake = true;
		if (this.PostAwakeEvent != null)
		{
			this.PostAwakeEvent(this);
		}
		RigidbodyEx obj2 = RigidbodyEx;
		obj2.OnDistanceBandChangedEvent = (Action<UpdateLOD, UpdateLOD>)Delegate.Combine(obj2.OnDistanceBandChangedEvent, new Action<UpdateLOD, UpdateLOD>(OnDistanceBandChanged));
		SingletonMonoBehaviour<Scheduler>.Instance.Run(this, WaitAndInitializeHolder());
		PhotonView obj3 = base.photonView;
		obj3.OnCachedAuthorityChanged = (PhotonView.OnCachedAuthorityChangedEvent)Delegate.Combine(obj3.OnCachedAuthorityChanged, new PhotonView.OnCachedAuthorityChangedEvent(OnCachedAuthorityChanged));
	}

	private void OnCachedAuthorityChanged(PhotonPlayer newAuthority)
	{
		CheckShouldClampRigidbodyVelocity();
		CheckForCancellableInput();
	}

	private void CheckForCancellableInput()
	{
		if (_inputPressed && !IsHeld && base.hasAuthority)
		{
			InputCancelled();
		}
	}

	private void Start()
	{
		Layers collisionLayer = DefaultCollisionLayer;
		if (IsAttachedToObject)
		{
			collisionLayer = AttachedCollisionLayer;
		}
		else if (IsHeldByPlayer)
		{
			collisionLayer = HeldCollisionLayer;
		}
		else if (IsEquippedOnPlayer)
		{
			collisionLayer = EquippedCollisionLayer;
		}
		SetCollisionLayer(collisionLayer);
		if (SleepOnStart)
		{
			rigidbodyEx.Sleep();
			OnSleepChanged(RigidbodyEx);
		}
		if (KinematicOnReset)
		{
			RigidbodyEx.AddKinematic(ResetKinematicToken);
		}
		SetMaxAngularVelocity();
		OnIsEnabledChanged();
		HoverEnd();
		RefreshCheckForIgnoredSchedulerUpdates();
		localScaleWhenSizeCached = base.transform.GetLocalUniformScale();
		this.Update1hz(StaggeredUpdateRoutine);
		PostStart = true;
		if (this.PostStartEvent != null)
		{
			this.PostStartEvent(this);
		}
	}

	private void StaggeredUpdateRoutine(float deltaTime)
	{
		CheckCachedApproximateSizeNeedsUpdate();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (this.DestroyEvent != null)
		{
			this.DestroyEvent(this);
		}
		if (HolderView != null)
		{
			HolderView.OnDestroyEvent -= OnHolderDestroyed;
		}
		if (HolderTool != null)
		{
			HolderTool.AuthorityPreEnabledChangeEvent -= OnAttachedParentToolEnabledChange;
		}
		if (RigidbodyEx != null)
		{
			RigidbodyEx.SleepChangedEvent -= OnSleepChanged;
			RigidbodyEx.LateUpdateEvent -= UpdateDynamicKinematicCollision;
			RigidbodyEx obj = RigidbodyEx;
			obj.OnDistanceBandChangedEvent = (Action<UpdateLOD, UpdateLOD>)Delegate.Remove(obj.OnDistanceBandChangedEvent, new Action<UpdateLOD, UpdateLOD>(OnDistanceBandChanged));
		}
		if (childTools != null && childTools.Count > 0)
		{
			for (int num = childTools.Count - 1; num >= 0; num--)
			{
				if (childTools[num] != null)
				{
					UnityEngine.Object.Destroy(childTools[num].gameObject);
				}
			}
		}
		if (NetworkTransform != null)
		{
			NetworkTransform obj2 = NetworkTransform;
			obj2.ValidPositionBoundsExceeded = (Action)Delegate.Remove(obj2.ValidPositionBoundsExceeded, new Action(OnValidPositionBoundsExceeded));
		}
		PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		PhotonNetwork.OnPhotonPlayerDisconnected -= new Action<PhotonPlayer>(OnPhotonPlayerDisconnected);
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		base.photonView.OnPreDestroyOfRuntimeParentedPhotonView -= OnRuntimeParentedPhotonViewDestroyed;
		PhotonView obj3 = base.photonView;
		obj3.OnCachedAuthorityChanged = (PhotonView.OnCachedAuthorityChangedEvent)Delegate.Remove(obj3.OnCachedAuthorityChanged, new PhotonView.OnCachedAuthorityChangedEvent(OnCachedAuthorityChanged));
	}

