		OnHolderInfoChanged();
	}

	public void KillzoneResetImmediately(Killzone killzone)
	{
		if (IsHeld || !base.hasAuthority)
		{
			return;
		}
		lastKillzoneResetFrame = UnityEngine.Time.frameCount;
		ClearQueuedKillzones();
		if (CustomAuthorityResetOnKillzoneBehavior != null)
		{
			Delegate[] invocationList = CustomAuthorityResetOnKillzoneBehavior.GetInvocationList();
			Delegate[] array = invocationList;
			for (int i = 0; i < array.Length; i++)
			{
				ResetOnKillzoneBehavior resetOnKillzoneBehavior = (ResetOnKillzoneBehavior)array[i];
				if (resetOnKillzoneBehavior(this, killzone))
				{
					return;
				}
			}
		}
		switch ((!(killzone != null)) ? Killzone.ToolCollisionEffect.RESET_LAST_PICKUP_POINT : killzone.GetToolCollisionEffect(this))
		{
		case Killzone.ToolCollisionEffect.RESET_LAST_PICKUP_POINT:
			AuthorityResetToLastPickup(cleanUp: true);
			break;
		case Killzone.ToolCollisionEffect.RESET_LAST_SPAWN_POINT:
			AuthorityResetToLastSpawnPosition(cleanUp: true);
			break;
		case Killzone.ToolCollisionEffect.DISABLE:
			AuthorityDisableAndMovetoLastSpawnPoint();
			break;
		}
	}

	public void QueueKillzoneReset(Killzone killzone)
	{
		if (!intersectingKillzones.Contains(killzone))
		{
			intersectingKillzones.Add(killzone);
		}
		if (killzoneUpdateToken == null)
		{
			killzoneUpdateToken = this.UpdateAtRate(4f, ResolveQueuedKillzones);
		}
	}

	public void RemoveQueuedKillzone(Killzone killzone)
	{
		if (intersectingKillzones.Remove(killzone) && intersectingKillzones.Count == 0 && killzoneUpdateToken != null)
		{
			killzoneUpdateToken.Dispose();
			killzoneUpdateToken = null;
		}
	}

	private void ClearQueuedKillzones()
	{
		intersectingKillzones.Clear();
		if (killzoneUpdateToken != null)
		{
			killzoneUpdateToken.Dispose();
			killzoneUpdateToken = null;
		}
	}

	private void ResolveQueuedKillzones(float deltaTime)
	{
		if (base.hasAuthority && RigidbodyEx.IsSleeping() && lastKillzoneResetFrame != UnityEngine.Time.frameCount)
		{
			KillzoneResetImmediately(intersectingKillzones[0]);
		}
	}

