	public void SetParentTransform(Transform newParent, bool worldPositionStays)
	{
		Transform parent = base.transform.parent;
		if (!(parent != newParent))
		{
			return;
		}
		if (newParent == null)
		{
			if (DoDestroyOnLoadParentTransform == null)
			{
				DoDestroyOnLoadParentTransform = new GameObject("DoDestroyOnLoadRoot").transform;
			}
			SetParentTransform(DoDestroyOnLoadParentTransform, worldPositionStays: true);
		}
		base.transform.SetParent(newParent, worldPositionStays);
		foreach (Tool childTool in childTools)
		{
			if (childTool != null && !childTool.IsAttachedToObject && childTool.transform.parent == parent)
			{
				childTool.SetParentTransform(newParent, worldPositionStays);
			}
		}
	}

