	public void AuthorityResetToDefault(Vector3 position, Quaternion rotation, bool sleepPhysics, bool wasCleanedUp = false)
	{
		if (base.hasAuthority)
		{
			bool isHeld = IsHeld;
			HolderInfo = ToolHolderInfo.NotHeld;
			if (isHeld)
			{
				SynchronizedField.SendPendingRoomUpdates();
			}
			bool isEnabled = IsEnabled;
			Vector3 position2 = base.transform.position;
			Quaternion rotation2 = base.transform.rotation;
			if (position2 != position || !rotation2.Equals(rotation))
			{
				base.transform.position = position;
				base.transform.rotation = rotation;
			}
			Snap();
			if (sleepPhysics || (wasCleanedUp && SleepOnCleanup))
			{
				RigidbodyEx.Sleep();
			}
			IsEnabled = true;
			base.photonView.RpcAll(RpcOnReset, position, rotation, isEnabled, position2, rotation2, wasCleanedUp);
		}
	}

