	private void OnReset(Vector3 position, Quaternion rotation, bool wasEnabled, Vector3 oldPosition, Quaternion oldRotation, bool wasCleanedUp)
	{
		if (this.PreResetEvent != null)
		{
			this.PreResetEvent(this, position, rotation, oldPosition, wasCleanedUp);
		}
		if (KinematicOnReset)
		{
			RigidbodyEx.AddKinematic(ResetKinematicToken);
		}
		AudioManager.Play3DSFX(audioSettings.ResetAudio, base.transform.position);
		if (wasEnabled && !SuppressAnimateInOut)
		{
			if (SupportsAnimateOut)
			{
				PlayAnimateInOutEffect(animIn: false, oldPosition, oldRotation);
			}
			if (SupportsAnimateIn)
			{
				PlayAnimateInOutEffect(animIn: true);
			}
		}
		ClearQueuedKillzones();
		LastSpawnPosition = (LastWorldSpacePickupPosition = position);
		LastSpawnRotation = (LastWorldSpacePickupRotation = rotation);
		SetCollisionLayer(DefaultCollisionLayer);
		if (this.PostResetEvent != null)
		{
			this.PostResetEvent(this, position, rotation, oldPosition, wasCleanedUp);
		}
	}

