	{
		UnityEngine.Debug.LogWarningFormat(this, "{0} has exceeded the valid position bounds {1}. Resetting to last spawn position", base.gameObject.GetGameObjectHierarchy(), RigidbodyEx.physicsPosition);
		AuthorityResetToDefault(LastSpawnPosition, LastSpawnRotation, sleepPhysics: true, wasCleanedUp: true);
	}

