	private void OnHolderInfoChanged()
	{
		if (!(HolderInfo != previousHolderInfo))
		{
			return;
		}
		bool flag = HolderInfo.IsHeld != previousHolderInfo.IsHeld;
		bool holderTypeChanged = HolderInfo.Type != previousHolderInfo.Type;
		Player player = null;
		if (previousHolderInfo.IsHeld)
		{
			if (previousHolderInfo.Type == ToolHolderInfo.HolderType.HELD_BY_PLAYER)
			{
				OnRelease();
			}
			else
			{
				OnDetach();
			}
			player = HolderPlayer;
			PreviousNonNullHolderPlayer = HolderPlayer;
		}
		previousHolderInfo = HolderInfo;
		RigidbodyEx.RemoveKinematic(ResetKinematicToken);
		if (!HolderInfo.IsHeld)
		{
			IsHeld = false;
			HolderView = null;
			HolderHand = null;
			HolderPlayer = null;
			HolderTool = null;
			IsHeldByPlayer = false;
			IsEquippedOnPlayer = false;
			IsAttachedToObject = false;
		}
		else
		{
			HolderView = PhotonView.Find(HolderInfo.PhotonViewId);
			if (HolderView == null)
			{
				if (base.hasAuthority)
				{
					HolderInfo = ToolHolderInfo.NotHeld;
				}
				return;
			}
			IsHeld = true;
			IsHeldByPlayer = HolderInfo.Type == ToolHolderInfo.HolderType.HELD_BY_PLAYER;
			IsAttachedToObject = HolderInfo.Type == ToolHolderInfo.HolderType.ATTACHED_TO_OBJECT;
			IsEquippedOnPlayer = HolderInfo.Type == ToolHolderInfo.HolderType.EQUIPPED_ON_PLAYER;
			if (IsHeldByPlayer)
			{
				HolderHand = ((!(HolderView != null)) ? null : HolderView.GetComponent<PlayerHand>());
				HolderPlayer = ((!(HolderHand != null)) ? null : HolderHand.owner.ToPlayer());
				HolderTool = null;
			}
			else
			{
				HolderHand = null;
				HolderPlayer = HolderView.GetComponentInParent<Player>();
				HolderTool = HolderView.GetComponent<Tool>();
			}
			if (IsHeldByPlayer)
			{
				bool holderOwnerChanged = player != HolderPlayer;
				OnPickup(holderOwnerChanged, holderTypeChanged);
			}
			else
			{
				OnAttach();
			}
			if (CreationObject != null && CreationObject.LocalPlayerHasLock)
			{
				CreationObject.LockedByPhotonPlayer = PhotonPlayer.Invalid;
			}
		}
		bool flag2 = HolderPlayer != null && HolderPlayer.isLocal;
		rigidbodyEx.CullingGroupSphereTransformTrackRate = ((!flag2) ? TransformTrackRate.Limited : TransformTrackRate.Full);
		if (flag2)
		{
			rigidbodyEx.AddUpdateLodOverride(this, UpdateLOD.TwoPointFiveMeters);
		}
		else
		{
			rigidbodyEx.RemoveUpdateLodOverride(this);
		}
		if (flag)
		{
			CheckShouldClampRigidbodyVelocity();
			CheckForCancellableInput();
		}
		if (Tool.StaticHolderChangedEvent != null)
		{
			Tool.StaticHolderChangedEvent(this);
		}
		if (this.HolderChangedEvent != null)
		{
			this.HolderChangedEvent(this);
		}
	}

	private void OnHolderDestroyed()
	{
		HolderView.OnDestroyEvent -= OnHolderDestroyed;
		HolderInfo = ToolHolderInfo.NotHeld;
	}

	private void OnHolderOwnerChange(int newOwnerId)
	{
		if (PhotonNetwork.player.ID == newOwnerId && !base.hasAuthority)
		{
			base.photonView.TransferOwnership(PhotonNetwork.player);
		}
	}

	private void ReevaluateIsHeld()
	{
		if (IsHeld && PhotonNetwork.isMasterClient && PhotonView.Find(HolderInfo.PhotonViewId) == null)
		{
			HolderInfo = ToolHolderInfo.NotHeld;
		}
	}

	private void OnPickup(bool holderOwnerChanged, bool holderTypeChanged)
	{
		if (this.PrePickupEvent != null)
		{
			this.PrePickupEvent(this);
		}
		SetCollisionLayer(HeldCollisionLayer);
		if (HolderView.isMine)
		{
			base.photonView.TransferOwnership(PhotonNetwork.player);
			if (LockOnPickup && (holderOwnerChanged || holderTypeChanged))
			{
				IsLocked = true;
			}
		}
		LastWorldSpacePickupPosition = base.transform.position;
		LastWorldSpacePickupRotation = base.transform.rotation;
		hasCustomReleaseVelocity = false;
		if (KinematicOnSleep)
		{
			RigidbodyEx.WakeUp();
		}
		if (HolderHand != null && (RemotelyRunRigidbodyPickupWhenHeld || HolderHand.isLocal))
		{
			RigidbodyPickup.Pickup(HolderHand.RigidbodyEx, HolderInfo.RelativePosition, HolderInfo.RelativeRotation);
		}
		if (Animator != null && !renderSettings.ShouldAnimateWhileNotHeld)
		{
			Animator.enabled = true;
		}
		AudioManager.Play3DSFX(audioSettings.PickupAudio, base.transform.position);
		if (HolderPlayer != null)
		{
			HolderPlayer.PlayerEvents.ToolPickup(this);
			if (HolderPlayer.isLocal)
			{
				ChallengeEvents.ToolPickedUp(this);
			}
		}
		if (this.PostPickupEvent != null)
		{
			this.PostPickupEvent(this);
		}
		if (LockOnPickup && Tool.StaticLockedToolPickedUpEvent != null)
		{
			Tool.StaticLockedToolPickedUpEvent(this);
		}
	}

	private void OnRelease()
	{
		if (this.PreReleaseEvent != null)
		{
			this.PreReleaseEvent(this);
		}
		IsLocked = false;
		Vector3 velocity = Vector3.zero;
		Vector3 angularVelocity = Vector3.zero;
		if (ReleaseWithVelocity)
		{
			if (!hasCustomReleaseVelocity)
			{
				float startTimeInPast = 4f * UnityEngine.Time.fixedDeltaTime;
				releaseLinearVelocity = RigidbodyEx.GetAverageHistoricalKinematicLinearVelocity(startTimeInPast);
				releaseAngularVelocity = RigidbodyEx.GetAverageHistoricalKinematicAngularVelocity(startTimeInPast);
			}
			if (RigidbodyEx.constraints != RigidbodyConstraints.None)
			{
				releaseLinearVelocity = RigidbodyEx.GetConstrainedVelocity(releaseLinearVelocity);
				releaseAngularVelocity = RigidbodyEx.GetConstrainedAngularVelocity(releaseAngularVelocity);
			}
			velocity = releaseLinearVelocity * interactionSettings.ThrowSpeedMultiplier;
			angularVelocity = releaseAngularVelocity.ValueOrZeroIfBogus();
		}
		SetVisible(visible: true);
		RigidbodyPickup.Release();
		SetCollisionLayer(DefaultCollisionLayer);
		StopTeleportDisableCollision();
		if (Animator != null && !renderSettings.ShouldAnimateWhileNotHeld)
		{
			Animator.enabled = false;
		}
		if (ReleaseWithVelocity)
		{
			RigidbodyEx.velocity = velocity;
			RigidbodyEx.angularVelocity = angularVelocity;
		}
		RecRoomAudioClip clip = ((!(RigidbodyEx.velocity.magnitude < 0.5f)) ? audioSettings.ThrowAudio : audioSettings.DropAudio);
		AudioManager.Play3DSFX(clip, base.transform.position);
		if (HolderPlayer != null)
		{
			HolderPlayer.PlayerEvents.ToolRelease(this);
		}
		if (this.PostReleaseEvent != null)
		{
			this.PostReleaseEvent(this);
		}
		if (Tool.StaticToolPostReleaseEvent != null)
		{
			Tool.StaticToolPostReleaseEvent(this);
		}
	}

	private void OnAttach()
	{
		if (this.PreAttachEvent != null)
		{
			this.PreAttachEvent(this);
		}
		if (HolderView.isMine)
		{
			base.photonView.TransferOwnership(PhotonNetwork.player);
		}
		NetworkTransform.SynchronizationReadingEnabled = false;
		NetworkTransform.SynchronizationWritingEnabled = false;
		if (IsAttachedToObject)
		{
			SetCollisionLayer(AttachedCollisionLayer);
		}
		else if (IsEquippedOnPlayer)
		{
			SetCollisionLayer(EquippedCollisionLayer);
		}
		else
		{
			UnityEngine.Debug.LogError($"Attaching tool {this} to {HolderView} with unexpected hold type {HolderInfo.Type}.");
		}
		RigidbodyEx.AddKinematic(AttachedKinematicToken);
		parentOnAttach = base.transform.parent;
		hasCustomReleaseVelocity = false;
		SetParentTransform(HolderView.gameObject.transform, worldPositionStays: false);
		base.transform.localPosition = HolderInfo.RelativePosition;
		base.transform.localRotation = HolderInfo.RelativeRotation;
		base.transform.SetLocalUniformScale(HolderInfo.RelativeScale);
		if (HolderTool != null)
		{
			HolderTool.AuthorityPreEnabledChangeEvent += OnAttachedParentToolEnabledChange;
		}
		if (this.PostAttachEvent != null)
		{
			this.PostAttachEvent(this);
		}
	}

	private void OnDetach()
	{
		if (this.PreDetachEvent != null)
		{
			this.PreDetachEvent(this);
		}
		float lossyUniformScale = base.transform.GetLossyUniformScale();
		SetParentTransform(parentOnAttach, worldPositionStays: true);
		base.transform.SetLocalUniformScale(lossyUniformScale);
		SetCollisionLayer(DefaultCollisionLayer);
		if (!hasCustomReleaseVelocity)
		{
			float startSecondsAgo = 4f * UnityEngine.Time.fixedDeltaTime;
			float endSecondsAgo = 0f;
			releaseLinearVelocity = RigidbodyEx.GetAverageHistoricalKinematicLinearVelocity(startSecondsAgo, endSecondsAgo) * interactionSettings.ThrowSpeedMultiplier;
			releaseAngularVelocity = RigidbodyEx.GetAverageHistoricalKinematicAngularVelocity(startSecondsAgo, endSecondsAgo).ValueOrZeroIfBogus();
		}
		NetworkTransform.SynchronizationReadingEnabled = true;
		NetworkTransform.SynchronizationWritingEnabled = true;
		RigidbodyEx.RemoveKinematic(AttachedKinematicToken);
		RigidbodyEx.velocity = releaseLinearVelocity;
		RigidbodyEx.angularVelocity = releaseAngularVelocity;
		if (HolderTool != null)
		{
			HolderTool.AuthorityPreEnabledChangeEvent -= OnAttachedParentToolEnabledChange;
		}
		if (this.PostDetachEvent != null)
		{
			this.PostDetachEvent(this);
		}
	}

	private void OnAttachedParentToolEnabledChange(Tool thisTool, bool enabled)
	{
		if (!enabled)
		{
			if (!base.hasAuthority)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			HolderInfo = ToolHolderInfo.NotHeld;
		}
	}

	private void OnIsLockedChanged()
	{
		bool isLocked = IsLocked;
		if (HolderPlayer != null)
		{
			HolderPlayer.PlayerEvents.ToolLocked(this, isLocked);
		}
		if (isLocked)
		{
			OnLock();
		}
		else
		{
			OnUnlock();
		}
		if (SingletonMonoBehaviour<AudioManager>.Instance != null)
		{
			AudioManager.Play3DSFX((!isLocked) ? SingletonMonoBehaviour<AudioManager>.Instance.ToolUnLockedAudio : SingletonMonoBehaviour<AudioManager>.Instance.ToolLockedAudio, base.transform.position);
		}
	}

