	private void StartTeleportDisableCollision(float teleportDuration)
	{
		StopTeleportDisableCollision();
		DisableCollision(teleportCollisionToken);
		teleportDisableCollisionsPromise = this.InvokeInUpdate(teleportDuration, null);
		teleportDisableCollisionsPromise.Finally(delegate
		{
			EnableCollision(teleportCollisionToken);
			teleportDisableCollisionsPromise = null;
		});
	}

	private void StopTeleportDisableCollision()
	{
		this.SafeStopSchedule(teleportDisableCollisionsPromise);
	}

