	private void GetHandPickupTransform(bool isLeftHand, out Vector3 position, out Quaternion rotation)
	{
		PickupTransforms pickupTransforms = ((!isLeftHand) ? interactionSettings.RightHandPickupTransforms : interactionSettings.LeftHandPickupTransforms);
		if (interactionSettings.OptimizedPickupTransforms)
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode && pickupTransforms.HasOculus)
			{
				position = pickupTransforms.OculusPosition;
				rotation = pickupTransforms.OculusRotation;
				return;
			}
			switch (SingletonMonoBehaviour<InputManager>.Instance.VRMode)
			{
			case InputManager.VRInputMode.SteamVR_Vive:
			case InputManager.VRInputMode.PS4_Move:
				if (pickupTransforms.HasSteamVrVive)
				{
					position = pickupTransforms.SteamVrVivePosition;
					rotation = pickupTransforms.SteamVrViveRotation;
					return;
				}
				break;
			case InputManager.VRInputMode.SteamVR_Oculus:
				if (pickupTransforms.HasSteamVrOculus)
				{
					position = pickupTransforms.SteamVrOculusPosition;
					rotation = pickupTransforms.SteamVrOculusRotation;
					return;
				}
				break;
			case InputManager.VRInputMode.Oculus:
				if (pickupTransforms.HasSteamVrOculus)
				{
					position = pickupTransforms.OculusPosition;
					rotation = pickupTransforms.OculusRotation;
					return;
				}
				break;
			case InputManager.VRInputMode.SteamVR_WindowsMR:
			case InputManager.VRInputMode.WindowsMR:
				if (pickupTransforms.HasSteamVrMicrosoft)
				{
					position = pickupTransforms.SteamVrMicrosoftPosition;
					rotation = pickupTransforms.SteamVrMicrosoftRotation;
					return;
				}
				if (pickupTransforms.HasSteamVrOculus)
				{
					position = pickupTransforms.SteamVrOculusPosition;
					rotation = pickupTransforms.SteamVrOculusRotation;
					return;
				}
				break;
			}
			position = ((!pickupTransforms.HasDefault) ? Vector3.zero : pickupTransforms.DefaultPosition);
			rotation = ((!pickupTransforms.HasDefault) ? Quaternion.identity : pickupTransforms.DefaultRotation);
		}
		else
		{
			Transform transform = null;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				transform = pickupTransforms.Oculus;
			}
			switch (SingletonMonoBehaviour<InputManager>.Instance.VRMode)
			{
			case InputManager.VRInputMode.SteamVR_Vive:
			case InputManager.VRInputMode.PS4_Move:
				transform = pickupTransforms.SteamVrVive;
				break;
			case InputManager.VRInputMode.SteamVR_Oculus:
				transform = pickupTransforms.SteamVrOculus;
				break;
			case InputManager.VRInputMode.Oculus:
				transform = pickupTransforms.Oculus;
				break;
			case InputManager.VRInputMode.SteamVR_WindowsMR:
			case InputManager.VRInputMode.WindowsMR:
				transform = ((!(pickupTransforms.SteamVrMicrosoft != null)) ? pickupTransforms.SteamVrOculus : pickupTransforms.SteamVrMicrosoft);
				break;
			}
			if (transform == null)
			{
				transform = pickupTransforms.Default;
			}
			position = ((!(transform != null)) ? Vector3.zero : transform.InverseTransformPoint(base.transform.position));
			rotation = ((!(transform != null)) ? Quaternion.identity : transform.InverseTransformRotation(base.transform.rotation));
		}
	}

	public void GetEquipSlotPickupTransform(ToolEquipSlot.EquipSlotType slotType, out Vector3 localPickupPosition, out Quaternion localPickupRotation)
	{
		localPickupPosition = Vector3.zero;
		localPickupRotation = Quaternion.identity;
		if (interactionSettings.OptimizedPickupTransforms)
		{
			if (slotType == ToolEquipSlot.EquipSlotType.Hip && interactionSettings.HasHipEquipSlot)
			{
				localPickupPosition = interactionSettings.HipEquipSlotPosition;
				localPickupRotation = interactionSettings.HipEquipSlotRotation;
			}
			else if (slotType == ToolEquipSlot.EquipSlotType.Shoulder && interactionSettings.HasShoulderEquipSlot)
			{
				localPickupPosition = interactionSettings.ShoulderEquipSlotPosition;
				localPickupRotation = interactionSettings.ShoulderEquipSlotRotation;
			}
		}
		else
		{
			Transform transform = ((slotType != ToolEquipSlot.EquipSlotType.Hip) ? interactionSettings.ShoulderEquipSlotOrientationTransform : interactionSettings.HipEquipSlotOrientationTransform);
			if (transform != null)
			{
				localPickupPosition = transform.InverseTransformPoint(base.transform.position);
				localPickupRotation = transform.InverseTransformRotation(base.transform.rotation);
			}
		}
	}

	public bool IsValidPickup(Player selectingPlayer, Vector3 selectionPoint, bool inPhysicalPickupRange)
	{
		if (!interactionSettings.CanBePickedUp)
		{
			return false;
		}
		if (!PickupEnabled)
		{
			return false;
		}
		if (!AllowedToTakeOwnership)
		{
			return false;
		}
		if (CreationObject != null && CreationObject.IsFrozen)
		{
			return false;
		}
		if (!PlayerGameRoleManager.CanPickupTool(selectingPlayer, this))
		{
			return false;
		}
		if (customPickupConditions.Count > 0)
		{
			foreach (PickupCondition customPickupCondition in customPickupConditions)
			{
				if (!customPickupCondition(this, selectingPlayer, selectionPoint, inPhysicalPickupRange))
				{
					return false;
				}
			}
		}
		if (IsHeldByPlayer && (Owner != selectingPlayer || !inPhysicalPickupRange) && (PlayerSpawnedEquipment == null || !PlayerSpawnedEquipment.IsMine))
		{
			return false;
		}
		if (!inPhysicalPickupRange && GravityPickupMode == GravityPickup.DISABLED)
		{
			return false;
		}
		if (!IsVisible && !IsSubTool)
		{
			return false;
		}
		if (IsLocked)
		{
			return false;
		}
		return true;
	}

	public float DistanceToTransform(Collider collider, Transform otherTransform, out bool inFrontOfTransform)
	{
		if (CustomDistanceToTransformBehavior != null)
		{
			return CustomDistanceToTransformBehavior(collider, otherTransform, out inFrontOfTransform);
		}
		Vector3 vector = collider.ClosestPoint(otherTransform.position);
		Vector3 lhs = vector - otherTransform.position;
		inFrontOfTransform = Vector3.Dot(lhs, otherTransform.right) >= -0.01f;
		return lhs.magnitude;
	}

	public bool IsValidAttach()
	{
		if (!AttachEnabled)
		{
			return false;
		}
