			foreach (EquipCondition customEquipCondition in customEquipConditions)
			{
				if (!customEquipCondition(this, equippingPlayer, equipSlot))
				{
					return false;
				}
			}
		}
		return true;
	}

	public float GetCachedApproximateSize()
	{
		if (!isCachedSizeInitialized)
		{
			UpdateCachedApproximateSize();
		}
		return cachedApproximateColliderSize;
	}

	public void UpdateCachedApproximateSize()
	{
		cachedApproximateColliderSize = GetColliderBounds(includeInactive: true).size.magnitude;
		localScaleWhenSizeCached = base.transform.GetLocalUniformScale();
		isCachedSizeInitialized = true;
	}

	private void CheckCachedApproximateSizeNeedsUpdate()
	{
		if (Math.Abs(localScaleWhenSizeCached - base.transform.GetLocalUniformScale()) > float.Epsilon)
		{
			UpdateCachedApproximateSize();
			if (this.OnCachedSizeUpdated != null)
			{
				this.OnCachedSizeUpdated();
			}
		}
	}

	public Bounds GetColliderBounds(bool includeInactive = false)
	{
		Bounds result = default(Bounds);
		bool flag = false;
		for (int i = 0; i < Colliders.Count; i++)
		{
			if (Colliders[i] != null && (includeInactive || Colliders[i].isActiveAndEnabled))
			{
				if (!flag)
				{
					result = Colliders[i].Bounds;
					flag = true;
				}
				else
				{
					result.Encapsulate(Colliders[i].Bounds);
				}
			}
		}
		return result;
	}

	public void AddToolCollider(ToolCollider collider)
	{
		collider.Tool = this;
		collider.ThisRigidbodyEx = RigidbodyEx;
		if (!Colliders.Contains(collider))
		{
			Colliders.Add(collider);
		}
	}

	public void SetCollisionLayer(Layers layer)
	{
		foreach (ToolCollider collider in Colliders)
		{
			collider.gameObject.layer = (int)layer;
		}
	}

	public void IgnoreCollision(Tool otherTool, bool ignore)
	{
		for (int i = 0; i < Colliders.Count; i++)
		{
			for (int j = 0; j < otherTool.Colliders.Count; j++)
			{
				Colliders[i].IgnoreCollision(otherTool.Colliders[j], ignore);
			}
		}
	}

	public void IgnoreCollision(Collider other, bool ignore)
	{
		for (int i = 0; i < Colliders.Count; i++)
		{
			for (int j = 0; j < Colliders[i].PhysicsColliders.Count; j++)
			{
				Physics.IgnoreCollision(Colliders[i].PhysicsColliders[j], other, ignore);
			}
		}
	}

	public void EnableCollision(object token)
	{
		SetCollisionEnabled(enabled: true, token);
	}

	public void DisableCollision(object token)
	{
		SetCollisionEnabled(enabled: false, token);
	}

	public void SetCollisionEnabled(bool enabled, object token)
	{
		bool collisionEnabled = CollisionEnabled;
		if (enabled)
		{
			_collisionDisabledFlag.Remove(token);
		}
		else
		{
			_collisionDisabledFlag.Add(token);
		}
		bool collisionEnabled2 = CollisionEnabled;
		if (collisionEnabled2 == collisionEnabled)
		{
			return;
		}
		foreach (ToolCollider collider in Colliders)
		{
			collider.enabled = collisionEnabled2;
		}
	}

	private bool TryTransferOwnershipOnCollision(PhotonPlayer desiredOwner)
	{
		bool result = false;
		if (desiredOwner != null && desiredOwner.IsLocal && !base.hasAuthority && AllowedToTakeOwnership && AllowedToTransferOwnershipOnCollision && !IsHeld)
		{
			result = true;
			base.photonView.TransferOwnership(desiredOwner);
		}
		return result;
	}

	private void InitializeColliders()
	{
		Colliders = new List<ToolCollider>();
		Collider[] componentsInChildren = GetComponentsInChildren<Collider>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			Collider collider = componentsInChildren[i];
			if (!collider.enabled || !collider.gameObject.activeSelf || !(collider.GetComponentInParent<Tool>() == this) || collisionSettings.IgnoredColliders.Contains(collider))
			{
				continue;
			}
			if (!collider.isTrigger)
			{
				CreateToolCollider(componentsInChildren[i].gameObject);
				continue;
			}
			ToolCollider component = collider.GetComponent<ToolCollider>();
			if (component != null)
			{
				AddToolCollider(component);
			}
		}
	}

	private void CreateToolCollider(GameObject gameObject)
	{
		ToolCollider toolCollider = gameObject.GetComponent<ToolCollider>();
		if (toolCollider == null)
		{
			toolCollider = gameObject.AddComponent<ToolCollider>();
		}
		AddToolCollider(toolCollider);
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (collision.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics) && !RigidbodyPickup.InterpolatingToTarget)
		{
			Tool colliderTool = collision.GetColliderTool();
			if (colliderTool != null)
			{
				if (colliderTool.IsHeld)
				{
					OnDynamicKinematicCollision(colliderTool.RigidbodyEx, collision);
				}
				if (base.hasAuthority)
				{
					colliderTool.TryTransferOwnershipOnCollision(base.owner);
				}
				return;
			}
		}
		if (!collision.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
		{
			return;
		}
		Player.BodyPart bodyPart;
		Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
		if (colliderPlayer != null)
		{
			colliderPlayer.PlayerEvents.ToolHit(bodyPart, this);
			if (colliderPlayer.isLocal)
			{
				TryTransferOwnershipOnCollision(colliderPlayer.PhotonPlayer);
			}
			switch (bodyPart)
			{
			case Player.BodyPart.LeftHand:
				colliderPlayer.LeftHand.Vibrate(50);
				break;
			case Player.BodyPart.RightHand:
				colliderPlayer.RightHand.Vibrate(50);
				break;
			}
			if (colliderPlayer.isLocal && Tool.LocalPlayerCollisionEvent != null)
			{
				Tool.LocalPlayerCollisionEvent(this, collision);
			}
		}
	}

	private void OnCollisionExit(Collision collision)
	{
		if (collision.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics))
		{
			Tool colliderTool = collision.GetColliderTool();
			if (colliderTool != null && colliderTool.IsHeld)
			{
				OnDynamicKinematicCollision(colliderTool.RigidbodyEx, collision);
			}
		}
	}

	private void OnTriggerEnter(Collider collider)
	{
		if (collider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
		{
			Player.BodyPart bodyPart;
			Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null)
			{
				colliderPlayer.PlayerEvents.ToolHit(bodyPart, this);
			}
			return;
		}
		Killzone colliderKillzone = collider.GetColliderKillzone();
		if (base.hasAuthority && !(colliderKillzone == null) && colliderKillzone.ResetsTools && UnityEngine.Time.frameCount != lastKillzoneResetFrame && !IsSubTool)
		{
			if (colliderKillzone.ResetsToolsOnEnter)
			{
				KillzoneResetImmediately(colliderKillzone);
			}
			else
			{
				QueueKillzoneReset(colliderKillzone);
			}
		}
	}

	private void OnTriggerExit(Collider collider)
	{
		Killzone colliderKillzone = collider.GetColliderKillzone();
		if (base.hasAuthority && !(colliderKillzone == null))
		{
			RemoveQueuedKillzone(colliderKillzone);
		}
	}

