	public void AddRenderer(Renderer renderer)
	{
		if (!renderSettings.RenderersThatDoNotHoverHighlight.Contains(renderer) && !(renderer is ParticleSystemRenderer))
		{
			Mesh mesh = renderer.GetMesh();
			RendererInstance item = new RendererInstance
			{
				Renderer = renderer,
				Mesh = mesh,
				SubMeshCount = ((!(mesh != null)) ? 1 : mesh.subMeshCount)
			};
			renderer.enabled = IsVisible;
			renderers.Add(item);
		}
	}

	public bool TryRemoveRenderer(Renderer renderer)
	{
		if (renderer != null && renderers != null)
		{
			int num = -1;
			if ((num = renderers.FindIndex((RendererInstance r) => r.Renderer == renderer)) >= 0)
			{
				renderers.RemoveAt(num);
				return true;
			}
			if ((num = renderSettings.RenderersThatDoNotHoverHighlight.FindIndex(renderer)) >= 0)
			{
				renderSettings.RenderersThatDoNotHoverHighlight[num] = null;
			}
		}
		return false;
	}

