	public bool TryRemoveUIRenderer(Canvas uiRenderer)
	{
		int num = -1;
		if (uiRenderer != null && uiRenderers != null && (num = uiRenderers.FindIndex((Canvas r) => r == uiRenderer)) >= 0)
		{
			uiRenderers.RemoveAt(num);
			return true;
		}
		return false;
	}

