			{
				renderers[i].Renderer.materials[j].color = color;
			}
		}
	}

	public void RenderPreview(Vector3 position, Quaternion rotation)
	{
		for (int i = 0; i < renderers.Count; i++)
		{
			if (renderers[i].Renderer != null && renderers[i].Renderer.gameObject.activeInHierarchy && renderers[i].Renderer.isVisible)
			{
				Vector3 v = base.transform.InverseTransformPoint(renderers[i].Renderer.transform.position);
				Quaternion rotation2 = base.transform.InverseTransformRotation(renderers[i].Renderer.transform.rotation);
				Vector3 worldSpacePosition = v.TransformCoordinateSpace(position, rotation);
				Quaternion worldSpaceRotation = rotation.TransformRotation(rotation2);
				PreviewVisualRenderer.RenderPreviewVisual(renderers[i].Mesh, renderers[i].SubMeshCount, worldSpacePosition, worldSpaceRotation, renderers[i].Renderer.transform.lossyScale);
			}
		}
		if (ChildTools.Count <= 0)
		{
			return;
		}
		foreach (Tool childTool in ChildTools)
		{
			Vector3 v2 = base.transform.InverseTransformPoint(childTool.transform.position);
			Quaternion rotation3 = base.transform.InverseTransformRotation(childTool.transform.rotation);
			Vector3 position2 = v2.TransformCoordinateSpace(position, rotation);
			Quaternion rotation4 = rotation.TransformRotation(rotation3);
			childTool.RenderPreview(position2, rotation4);
		}
	}

