	public void SetCustomIgnoredSettings(CustomIgnoreSettings settings)
	{
		customIgnoreSettings = settings;
		SetIgnored(ignored: true, customIgnoredSettingsToken);
	}

	public void ClearCustomIgnoredSettings()
	{
		customIgnoreSettings = null;
		SetIgnored(ignored: false, customIgnoredSettingsToken);
	}

	private void SetIgnored(bool ignored, object token)
	{
		bool ignored2 = Ignored;
		if (ignored)
		{
			_ignoredFlag.Add(token);
		}
		else
		{
			_ignoredFlag.Remove(token);
		}
		bool ignored3 = Ignored;
		if (ignored3 == ignored2)
		{
			return;
		}
		if (Ignored)
		{
			foreach (Canvas uiRenderer in uiRenderers)
			{
				uiRenderer.gameObject.SetActive(value: false);
			}
		}
		else if (IsVisible)
		{
			foreach (Canvas uiRenderer2 in uiRenderers)
			{
				uiRenderer2.gameObject.SetActive(value: true);
			}
		}
		if (Ignored)
		{
			if (ignoredRenderingUpdateToken == null)
			{
				ignoredRenderingUpdateToken = this.Update(UpdateIgnoredRendering);
			}
		}
		else if (ignoredRenderingUpdateToken != null)
		{
			ignoredRenderingUpdateToken.Dispose();
			ignoredRenderingUpdateToken = null;
		}
		if (this.IgnoredChangeEvent != null)
		{
			this.IgnoredChangeEvent(this, Ignored);
		}
	}

	private void InitializeRenderers()
	{
		Renderer[] componentsInChildren = GetComponentsInChildren<Renderer>(includeInactive: true);
		foreach (Renderer renderer in componentsInChildren)
		{
			if (renderer.GetComponentInParent<StackedUIFlowBase>() == null && renderer.GetComponentInParent<Tool>() == this)
			{
				AddRenderer(renderer);
			}
		}
		Canvas[] componentsInChildren2 = GetComponentsInChildren<Canvas>(includeInactive: true);
		for (int j = 0; j < componentsInChildren2.Length; j++)
		{
			if (componentsInChildren2[j].GetComponent<StackedUIFlowBase>() == null && componentsInChildren2[j].GetComponentInParent<ToolUI>() == null && componentsInChildren2[j].GetComponentInParent<Tool>() == this)
			{
				AddUIRenderer(componentsInChildren2[j]);
			}
		}
	}

