	private void RefreshCheckForIgnoredSchedulerUpdates()
	{
		if (checkForIgnoredRenderingUpdateToken != null)
		{
			checkForIgnoredRenderingUpdateToken.Dispose();
			checkForIgnoredRenderingUpdateToken = null;
			if (!ManagesOwnIgnoreState && ParentTool != null)
			{
				SetIgnored(ParentTool.Ignored, checkForIgnoredRenderingToken);
			}
		}
		if (ManagesOwnIgnoreState && CanBeIgnored && (PhotonNetwork.otherPlayers.Length > 0 || CameraIgnoreBubble.AllBubbles.Count > 0))
		{
			float num = checkForIgnoredUpdateRates[updateLod];
			if (num < 0f)
			{
				checkForIgnoredRenderingUpdateToken = this.Update(CheckForIgnoredRendering);
			}
			else if (num > 0f)
			{
				checkForIgnoredRenderingUpdateToken = this.UpdateAtRate(num, CheckForIgnoredRendering);
			}
		}
	}

	private void OnDistanceBandChanged(UpdateLOD oldUpdateLod, UpdateLOD newUpdateLod)
	{
		updateLod = newUpdateLod;
		RefreshCheckForIgnoredSchedulerUpdates();
	}

	private void CheckForIgnoredRendering(float deltaTime)
	{
		CheckForIgnoredRendering();
	}

	private void CheckForIgnoredRendering()
	{
		SetIgnored(CheckShouldIgnore(out ignoringPlayer, out ignoringCamera), checkForIgnoredRenderingToken);
	}

	private void UpdateIgnoredRendering()
	{
		if (customIgnoreSettings.HasValue)
		{
			RenderAsIgnored(customIgnoreSettings.Value);
			for (int i = 0; i < childTools.Count; i++)
			{
				childTools[i].RenderAsIgnored(customIgnoreSettings.Value);
			}
		}
		else if (ignoringPlayer != null)
		{
			RenderAsIgnored(ignoringPlayer);
			for (int j = 0; j < childTools.Count; j++)
			{
				childTools[j].RenderAsIgnored(ignoringPlayer);
			}
		}
		else if (ignoringCamera != null)
		{
			RenderAsIgnored(ignoringCamera);
			for (int k = 0; k < childTools.Count; k++)
			{
				childTools[k].RenderAsIgnored(ignoringCamera);
			}
		}
	}

	private bool CheckShouldIgnore(out Player ignoringPlayer, out CameraIgnoreBubble ignoringCamera)
	{
		ignoringPlayer = null;
		ignoringCamera = null;
		if (!CanBeIgnored)
		{
			return false;
		}
		if (HolderPlayer != null && HolderPlayer.isLocal)
		{
			float num = float.MaxValue;
			Player localPlayer = Player.LocalPlayer;
			List<Player> all = Player.All;
			for (int i = 0; i < all.Count; i++)
			{
				Player player = all[i];
				if (player != localPlayer && !player.DisplayAsIgnored && IgnoreEffectRenderer.ShouldIgnoreTool(player, this, out var projectedSqDistance) && projectedSqDistance < num)
				{
					num = projectedSqDistance;
					ignoringPlayer = player;
				}
			}
		}
		else if (Player.LocalPlayerExists)
		{
			Player localPlayer2 = Player.LocalPlayer;
			if (IgnoreEffectRenderer.ShouldIgnoreTool(localPlayer2, this))
			{
				ignoringPlayer = localPlayer2;
			}
		}
		if (ignoringPlayer == null)
		{
			foreach (CameraIgnoreBubble allBubble in CameraIgnoreBubble.AllBubbles)
			{
				if (IgnoreEffectRenderer.ShouldIgnoreTool(allBubble, this))
				{
					ignoringCamera = allBubble;
					break;
				}
			}
		}
		return ignoringPlayer != null || ignoringCamera != null;
	}

	private void RenderAsIgnored(Player ignoringPlayer)
	{
		Player holderPlayer = HolderPlayer;
		for (int i = 0; i < renderers.Count; i++)
