	public bool ApplyAttackAndTryTakeOwnership(Weapon weapon, WeaponDamageType damageType, Vector3 point)
	{
		if (!base.hasAuthority)
		{
			TryTransferOwnershipOnCollision(PhotonNetwork.player);
		}
		base.photonView.RpcAll(RpcApplyAttack, weapon, damageType, point);
		return base.hasAuthority;
	}

	private void RemoteApplyAttack(Weapon weapon, WeaponDamageType damageType, Vector3 point)
	{
		if (UnityEngine.Time.time - lastAttackAppliedTime > 0.25f)
		{
			AudioManager.Play3DSFX((!isLocal) ? audioSettings.RemoteAttackAppliedAudio : audioSettings.LocalAttackAppliedAudio, point);
		}
		lastAttackAppliedTime = UnityEngine.Time.time;
		if (this.AttackAppliedEvent != null)
		{
			this.AttackAppliedEvent(this, weapon, damageType, point);
		}
	}

	private void CheckShouldClampRigidbodyVelocity()
	{
		if (base.hasAuthority && !IsHeld && (hasDynamicMaxSpeed || interactionSettings.HasMaxThrowSpeed))
		{
			if (clampRigidbodyVelocityUpdateToken == null)
			{
				clampRigidbodyVelocityUpdateToken = this.Update(ClampRigidbodyVelocityUpdate);
			}
		}
		else if (clampRigidbodyVelocityUpdateToken != null)
		{
			clampRigidbodyVelocityUpdateToken.Dispose();
			clampRigidbodyVelocityUpdateToken = null;
		}
	}

	private void ClampRigidbodyVelocityUpdate()
	{
		float num = float.MaxValue;
		if (hasDynamicMaxSpeed)
		{
			num = Mathf.Min(dynamicMaxSpeed, num);
		}
		if (interactionSettings.HasMaxThrowSpeed)
		{
			num = Mathf.Min(interactionSettings.MaxThrowSpeed, num);
		}
		RigidbodyEx.velocity = Vector3.ClampMagnitude(RigidbodyEx.velocity, num);
	}

	public void ApplyPlayerLocomotionAttack(Vector3 position, Vector3 direction, float normalizedForce)
	{
		if (SupportsPlayerLocomotionAttacks)
		{
			ApplyAttackAndTryTakeOwnership(null, WeaponDamageType.DEFAULT, position);
			if (base.hasAuthority)
			{
				float num = Mathf.Lerp(PlayerLocomotionAttackMinForce, PlayerLocomotionAttackMaxForce, normalizedForce);
				AuthorityApplyForce(direction * num, position, ForceMode.Impulse);
			}
		}
	}

	public void AuthorityApplyForce(Vector3 force, Vector3 position, ForceMode forceMode)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (ConnectableTool != null && ConnectableTool.IsParented)
		{
			if (ConnectableTool.ParentIsTool)
			{
				ConnectableTool.ParentTool.AuthorityApplyForce(force, position, forceMode);
			}
		}
		else if (!IsHeld && !IsFrozen && !IsSubTool && !RigidbodyEx.UsesKinematicForces)
		{
			if (CustomApplyForceModifier != null)
			{
				CustomApplyForceModifier(ref force, position);
			}
			RigidbodyEx.AddForceAtPosition(force, position, forceMode);
			if (this.AuthorityForceAppliedEvent != null)
			{
				this.AuthorityForceAppliedEvent(this, force, position);
			}
		}
	}

	public void AuthorityChangeVelocity(Vector3 velocity, Vector3 angularVelocity)
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (ConnectableTool != null && ConnectableTool.IsParented)
		{
			if (ConnectableTool.ParentIsTool)
			{
				ConnectableTool.ParentTool.AuthorityChangeVelocity(velocity, angularVelocity);
			}
		}
		else if (!IsHeld && !IsFrozen && !RigidbodyEx.UsesKinematicForces)
		{
			if (CustomVelocityChangeModifier != null)
			{
				CustomVelocityChangeModifier(ref velocity, ref angularVelocity, base.transform.position);
			}
			if (hasDynamicMaxSpeed)
			{
				velocity = Vector3.ClampMagnitude(velocity, dynamicMaxSpeed);
			}
			RigidbodyEx.velocity = velocity;
			RigidbodyEx.angularVelocity = angularVelocity;
			if (this.AuthorityVelocityChangeEvent != null)
			{
				this.AuthorityVelocityChangeEvent(this, velocity, angularVelocity);
			}
		}
	}

	public void SetDynamicMaxSpeed(float maxSpeed)
	{
		hasDynamicMaxSpeed = true;
		dynamicMaxSpeed = maxSpeed;
		CheckShouldClampRigidbodyVelocity();
	}

	public void ClearDynamicMaxSpeed()
	{
		hasDynamicMaxSpeed = false;
		CheckShouldClampRigidbodyVelocity();
	}

	public void SnapToHand()
	{
