	private void OnSleepChanged(RigidbodyEx rigidbodyEx)
	{
		bool flag = RigidbodyEx.IsSleeping();
		if (KinematicOnSleep && flag)
		{
			RigidbodyEx.AddKinematic(SleepingKinematicToken);
			RigidbodyEx.Sleep();
		}
		else
		{
			RigidbodyEx.RemoveKinematic(SleepingKinematicToken);
		}
	}

	public Tool SelectForwardedTool(Player selectingPlayer, bool physicalPickupSelection, Collider selectedCollider = null)
	{
