	}

	public CreationObject SelectForwardedCreationObject(Player selectingPlayer, bool physicalPickupSelection, Collider selectedCollider)
	{
		Tool tool = this;
		while (tool != null)
		{
			if (tool.CreationObject != null)
			{
				return tool.CreationObject;
			}
			Tool tool2 = tool.SelectForwardedTool(selectingPlayer, physicalPickupSelection, selectedCollider);
			if (tool2 == tool)
			{
				break;
			}
			tool = tool2;
		}
		return null;
	}

	private void UpdateDynamicKinematicCollision(RigidbodyEx rigidbodyEx)
	{
		previousPreviousVelocity = previousVelocity;
		previousVelocity = ((!RigidbodyEx.isKinematic) ? RigidbodyEx.velocity : Vector3.zero);
		if (lastDynamicKinematicRigidbodyEx == null)
		{
			return;
		}
		if (dynamicKinematicCollisionThisFrame)
		{
			dynamicKinematicCollisionThisFrame = false;
			lastDynamicKinematicCollisionTime = UnityEngine.Time.unscaledTime;
			RigidbodyEx.velocity = dynamicKinematicCollisionVelocity;
			RigidbodyEx.angularVelocity = dynamicKinematicCollisionAngularVelocity;
		}
		foreach (ToolCollider collider in Colliders)
		{
			if (collider.IsOverlapping(lastDynamicKinematicRigidbodyEx))
			{
				lastDynamicKinematicCollisionTime = UnityEngine.Time.unscaledTime;
				break;
			}
		}
		if (UnityEngine.Time.unscaledTime - lastDynamicKinematicCollisionTime > 0.25f)
		{
			DisableDynamicKinematicCollisions(disable: false);
			lastDynamicKinematicRigidbodyEx = null;
		}
	}

	private void OnDynamicKinematicCollision(RigidbodyEx rigidbodyEx, Collision collision)
	{
		if (collisionSettings.DynamicKinematicCollisionsCanBeApplied && !(lastDynamicKinematicRigidbodyEx != null) && !(collision.impulse.magnitude <= Mathf.Epsilon))
		{
			Tool colliderTool = collision.GetColliderTool();
			if (!(colliderTool != null) || colliderTool.collisionSettings.CanApplyDynamicKinematicCollisions)
			{
				CalculateDynamicKinematicCollisionPhysics(rigidbodyEx, collision, out dynamicKinematicCollisionVelocity, out dynamicKinematicCollisionAngularVelocity);
				dynamicKinematicCollisionThisFrame = true;
				lastDynamicKinematicRigidbodyEx = rigidbodyEx;
				DisableDynamicKinematicCollisions(disable: true);
			}
		}
	}

	private void CalculateDynamicKinematicCollisionPhysics(RigidbodyEx rigidbodyEx, Collision collision, out Vector3 linearVelocity, out Vector3 angularVelocity)
	{
		float mass = RigidbodyEx.mass;
		Vector3 vector = previousPreviousVelocity;
		Vector3 vector2 = mass * vector;
		float mass2 = rigidbodyEx.mass;
		Vector3 velocity = rigidbodyEx.velocity;
		Vector3 vector3 = mass2 * velocity;
		Vector3 vector4 = velocity - vector;
		RecRoomCollider component = collision.collider.GetComponent<RecRoomCollider>();
		Vector3 collisionNormal = component.GetCollisionNormal(collision);
		float kinematicBounciness = component.KinematicBounciness;
		linearVelocity = (collisionNormal * ((vector2 + vector3 + mass2 * kinematicBounciness * vector4) / (mass + mass2)).magnitude).ClampedValueOrZeroIfBogus(1000f);
		Vector3 rhs = Vector3.ProjectOnPlane(velocity, collisionNormal);
		Vector3 normalized = Vector3.Cross(-collisionNormal, rhs).normalized;
		angularVelocity = (normalized * rhs.magnitude * collisionSettings.DynamicKinematicCollisionSpin * ((float)Math.PI / 180f)).ClampedValueOrZeroIfBogus(1000f);
	}

	public void DisableDynamicKinematicCollisions(bool disable)
	{
		if (disable)
		{
			SetCollisionLayer(TOOL_COLLISION_DISABLED_LAYER);
		}
		else if (IsHeld)
		{
			SetCollisionLayer(HeldCollisionLayer);
		}
		else
		{
			SetCollisionLayer(DefaultCollisionLayer);
		}
	}

