namespace RecRoom.Tools
{
	public class ToolAccessory : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		[Autofill(AutofillType.Parent, false)]
		[SerializeField]
		protected Tool parentTool;

		[AutofillOptional(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		protected Animator animator;

		[SerializeField]
		private Renderer[] additionalHighlightRenderers;

		protected Vector3 localPosition = Vector3.zero;

		protected Quaternion localRotation = Quaternion.identity;

		protected float localScale = 1f;

		protected bool initialized;

		public Tool Tool => _tool;

		protected virtual void Awake()
		{
			Tool.AttachedCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			Tool.GravityPickupMode = Tool.GravityPickup.DISABLED;
			Tool.AlwaysPhysicalPickupOffCenter = true;
			Tool.AllowedToTransferOwnershipOnCollision = false;
			Tool.CanBeLocked = false;
			Tool.ReleaseWithVelocity = false;
			Tool.DefaultCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicPhysics;
			Tool.HeldCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerPhysics;
			Tool.CustomSelectionForwarding = ToolSelectionForwarding;
			if (parentTool == null)
			{
				UnityEngine.Debug.LogError(base.name + " does not have a Tool in its parent list.");
				return;
			}
			parentTool.photonView.OwnerChangedEvent += OnParentToolOwnershipTransfer;
			if (parentTool.PostAwake)
			{
				OnParentToolPostAwake(parentTool);
			}
			else
			{
				parentTool.PostAwakeEvent += OnParentToolPostAwake;
			}
			localPosition = parentTool.transform.InverseTransformPoint(base.transform.position);
			localRotation = parentTool.transform.InverseTransformRotation(base.transform.rotation);
			localScale = parentTool.transform.InverseTransformLossyUniformScale(base.transform.GetLossyUniformScale());
			if (Tool.PostAwake)
			{
				OnToolPostAwake(Tool);
			}
			else
			{
				Tool.PostAwakeEvent += OnToolPostAwake;
			}
		}

		private void OnToolPostAwake(Tool tool)
		{
			base.transform.SetParent(parentTool.transform.parent, worldPositionStays: true);
		}

		private void OnParentToolPostAwake(Tool parentTool)
		{
			parentTool.EnabledChangeEvent += OnParentToolEnabled;
			parentTool.PostPickupEvent += OnParentToolPostPickup;
			parentTool.PostReleaseEvent += OnParentToolPostRelease;
			parentTool.OwnerTeleportEvent += OnParentToolTeleport;
			parentTool.OwnerRotateInPlaceEvent += OnParentToolRotateInPlace;
			parentTool.VisibilityChangeEvent += OnParentToolVisibilityChanged;
			parentTool.HoverStartEvent += OnParentToolHoverStart;
			parentTool.HoverEndEvent += OnParentToolHoverEnd;
			parentTool.RigidbodyEx.SleepChangedEvent += OnParentToolSleepChange;
		}

		protected virtual void Start()
		{
			for (int i = 0; i < additionalHighlightRenderers.Length; i++)
			{
				Tool.AddRenderer(additionalHighlightRenderers[i]);
			}
			initialized = true;
		}

		protected virtual void OnDestroy()
		{
			if (Tool != null)
			{
				Tool.PostAwakeEvent -= OnToolPostAwake;
			}
			if (parentTool != null)
			{
				parentTool.PostAwakeEvent -= OnParentToolPostAwake;
				parentTool.VisibilityChangeEvent -= OnParentToolVisibilityChanged;
				parentTool.EnabledChangeEvent -= OnParentToolEnabled;
				parentTool.PostPickupEvent -= OnParentToolPostPickup;
				parentTool.PostReleaseEvent -= OnParentToolPostRelease;
				parentTool.OwnerTeleportEvent -= OnParentToolTeleport;
				parentTool.OwnerRotateInPlaceEvent -= OnParentToolRotateInPlace;
				parentTool.RigidbodyEx.SleepChangedEvent -= OnParentToolSleepChange;
				parentTool.photonView.OwnerChangedEvent -= OnParentToolOwnershipTransfer;
			}
		}

		protected virtual void OnEnable()
		{
		}

		protected virtual void OnParentToolPostPickup(Tool parentToolTool)
		{
		}

		protected virtual void OnParentToolSleepChange(RigidbodyEx parentToolRigidbody)
		{
		}

		protected virtual void OnParentToolPostRelease(Tool parentToolTool)
		{
			if (Tool.IsHeldByPlayer && Tool.hasAuthority)
			{
				Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
		}

		private void OnParentToolTeleport(Tool parentToolTool, float duration)
		{
			Tool.OnPlayerTeleport(duration);
		}

		private void OnParentToolRotateInPlace(Tool parentToolTool, float angle, float duration)
		{
			Tool.OnPlayerRotateInPlace(angle, duration);
		}

		protected virtual Tool ToolSelectionForwarding(Player player, bool physicalPickup, Collider selectedCollider)
		{
			if (parentTool == null || (parentTool.IsHeldByPlayer && parentTool.HolderPlayer == player))
			{
				return Tool;
			}
			return parentTool;
		}

		private void OnParentToolVisibilityChanged(bool isVisible, bool remoteVisible)
		{
			Tool.SetVisible(parentTool.IsVisible);
		}

		protected virtual void OnParentToolEnabled(Tool tool)
		{
			if (Tool.hasAuthority)
			{
				Tool.IsEnabled = parentTool.IsEnabled;
			}
		}

		private void OnParentToolOwnershipTransfer(int parentToolOwnerId)
		{
			Tool.photonView.TransferOwnership(parentToolOwnerId);
		}

		private void OnParentToolHoverStart(Tool tool)
		{
			Tool.HoverStart();
		}

		private void OnParentToolHoverEnd(Tool tool)
		{
			Tool.HoverEnd();
		}
	}
}
public class ToolCleanup : Photon.MonoBehaviour, IPersistable
{
	public struct CleanupOverrides
	{
		public const float MIN_PLAYER_DISTANCE = 1.5f;

		public const float MIN_CLEANUP_DELAY = 1f;

		public const float MAX_CLEANUP_DELAY = 30f;

		private const int CLEANUP_DELAY_BITS = 10;

		private static readonly RecRoom.Networking.BitPacker bitPacker = new RecRoom.Networking.BitPacker();

		public bool IsActive;

		public Vector3 Position;

		public Quaternion Rotation;

		public float Delay;

		public static CleanupOverrides Default => new CleanupOverrides
		{
			IsActive = false,
			Position = Vector3.zero,
			Rotation = Quaternion.identity,
			Delay = 15f
		};

		public static short Serialize(StreamBuffer outStream, object customobject)
		{
			CleanupOverrides cleanupOverrides = (CleanupOverrides)customobject;
			lock (bitPacker)
			{
				bitPacker.StartWriting(outStream);
				bitPacker.WriteBool(cleanupOverrides.IsActive);
				if (cleanupOverrides.IsActive)
				{
					bitPacker.WritePosition(cleanupOverrides.Position);
					bitPacker.WriteQuaternion(cleanupOverrides.Rotation);
					bitPacker.WriteFloat(cleanupOverrides.Delay, 1f, 30f, 10);
				}
				return (short)bitPacker.FinishWriting();
			}
		}

		public static object Deserialize(StreamBuffer inStream, short length)
		{
			CleanupOverrides cleanupOverrides = default(CleanupOverrides);
			lock (bitPacker)
			{
				bitPacker.StartReading(inStream, length);
				cleanupOverrides.IsActive = bitPacker.ReadBool();
				if (cleanupOverrides.IsActive)
				{
					cleanupOverrides.Position = bitPacker.ReadPosition();
					cleanupOverrides.Rotation = bitPacker.ReadQuaternion();
					cleanupOverrides.Delay = bitPacker.ReadFloat(1f, 30f, 10);
				}
				bitPacker.FinishReading();
			}
			return cleanupOverrides;
		}
	}

	public delegate bool GetPositionAndOrientationBehavior(out Vector3 position, out Quaternion orientation);

	private const string STAGGERED_UPDATE_GROUP = "ToolCleanup";

	private const float DEFAULT_CLEANUP_DELAY = 15f;

	[Tooltip("Whether or not this tool should be excluded from cleanup")]
	[SerializeField]
	private bool excludeFromCleanup;

	[Tooltip("Whether to allow users to configure custom cleanup settings via the Maker Pen")]
	[SerializeField]
	private bool allowUserOverrides = true;

	[Tooltip("Min distance from original spawn position before a tool is considered eligible for cleanup")]
	public float MinDisplacementBeforeCleanup = 0.1f;

	[Tooltip("Min distance from the closest player before a tool is considered eligible for cleanup")]
	[FormerlySerializedAs("MinPlayerDistanceBeforeCleanup")]
	public float defaultMinPlayerDistanceBeforeCleanup = 3f;

	[Tooltip("How many degrees this object must have rotated in order to be considered rotated")]
	public float MinRotationAngleBeforeCleanup = 30f;

	[Tooltip("Delay before eligible tools are cleaned up")]
	[FormerlySerializedAs("DelayUntilCleanup")]
	public float defaultDelayUntilCleanup = 15f;

	[Tooltip("Whether to try and check if this object moved or rotated only after its rigidbody has come to rest")]
	[FormerlySerializedAs("TestRigidbody")]
	public bool OnlyCleanupWhenSleeping;

	[NonSerialized]
	public Player Owner;

	public GetPositionAndOrientationBehavior CustomGetResetPositionAndOrientationBehavior;

	private Tool tool;

	private Vector3 lastResetPosition;

	private Quaternion lastResetRotation;

	private SynchronizedField<CleanupOverrides> _overrides;

	private SynchronizedField<bool> _forceCleanupQueued;

	private bool isResetting;

	private bool hasMoved;

	private float resetTimerStart;

	private TokenFlag pauseTokens = new TokenFlag();

	public bool ForceCleanupQueued
	{
		get
		{
			return _forceCleanupQueued.Get();
		}
		private set
		{
			_forceCleanupQueued.Set(value);
		}
	}

	public bool IsPaused
	{
		get
		{
			if (pauseTokens.HasTokens)
			{
				return true;
			}
			if (OverridesActive)
			{
				return false;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.RunToolCleanup)
			{
				return true;
			}
			return excludeFromCleanup;
		}
	}

	public bool OverridesActive => Overrides.IsActive;

	private bool HasTranslated => Vector3.Distance(base.transform.position, ResetPosition) > MinDisplacementBeforeCleanup;

	private bool HasRotated => Quaternion.Angle(ResetRotation, base.transform.rotation) >= MinRotationAngleBeforeCleanup;

	private bool CouldCleanup => base.enabled && (!OnlyCleanupWhenSleeping || tool.RigidbodyEx.IsSleeping()) && !tool.IsHeld && !tool.IsFrozen && (tool.CreationObject == null || !tool.CreationObject.IsLocked);

	private bool IsCloseToAnyPlayer
	{
		get
		{
			float minPlayerDistanceBeforeCleanup = MinPlayerDistanceBeforeCleanup;
			return minPlayerDistanceBeforeCleanup > 0f && Player.IsCloseToAnyPlayer(base.transform.position, minPlayerDistanceBeforeCleanup);
		}
	}

	private CleanupOverrides Overrides
	{
		get
		{
			return _overrides.Get();
		}
		set
		{
			_overrides.Set(value);
		}
	}

	private Vector3 ResetPosition
	{
		get
		{
			if (Overrides.IsActive)
			{
				return Overrides.Position;
			}
			return lastResetPosition;
		}
	}

	private Quaternion ResetRotation
	{
		get
		{
			if (Overrides.IsActive)
			{
				return Overrides.Rotation;
			}
			return lastResetRotation;
		}
	}

	private float DelayUntilCleanup
	{
		get
		{
			if (Overrides.IsActive)
			{
				return Overrides.Delay;
			}
			return defaultDelayUntilCleanup;
		}
	}

	private float MinPlayerDistanceBeforeCleanup
	{
		get
		{
			if (Overrides.IsActive)
			{
				return 1.5f;
			}
			return defaultMinPlayerDistanceBeforeCleanup;
		}
	}

	public bool BlockObjectPersistance => false;

	protected override void Awake()
	{
		base.Awake();
		tool = GetComponent<Tool>();
		if (tool == null)
		{
			UnityEngine.Debug.LogError($"{this} is missing a tool component.");
		}
		tool.PostResetEvent += OnReset;
		_overrides = new SynchronizedField<CleanupOverrides>(this, "TC_O", CleanupOverrides.Default, SetterPermissionMode.MASTER_OR_AUTHORITY);
		_forceCleanupQueued = new SynchronizedField<bool>(this, "TC_MD", defaultValue: false, SetterPermissionMode.AUTHORITY);
		OnReset(tool, base.transform.position, base.transform.rotation, base.transform.position, wasCleanedUp: true);
	}

	private void Start()
	{
		if (tool.CreationObject != null && allowUserOverrides)
		{
			PrefabTypeSettingEditEvent<CreationObjectSettingToolCleanupUIControl, CleanupOverrides>.GetPrefabForEditEvent prefabResolver = (MakerPenPaletteConfigScreen creationObject) => creationObject.DefaultToolCleanupUIControlPrefab;
			ToolCleanupSettingEditEvent settingEvent = new ToolCleanupSettingEditEvent(prefabResolver, delegate(CreationObjectSettingToolCleanupUIControl instance)
			{
				UIHelper.SafeSetText(instance.PropertyDescription, "Respawn");
				instance.PropertyGetter = SandboxOverride_Get;
				instance.PropertySetter = SandboxOverride_Set;
				UIHelper.SafeSetText(instance.PropertyDescription, "Respawn");
			});
			tool.CreationObject.AddConfigurableSetting(settingEvent);
		}
		if (!StaggeredUpdateManager.Instance.IsGroupRegistered("ToolCleanup"))
		{
			int[] array = new int[6];
			array[0] = 1;
			array[4] = 1;
			array[1] = 1;
			array[2] = 1;
			array[3] = 1;
			array[5] = 1;
			StaggeredUpdateManager.Instance.RegisterGroup("ToolCleanup", callWhenDisabled: false, array);
		}
		StaggeredUpdateManager.Instance.RegisterObject("ToolCleanup", this, DynamicUpdate);
	}

	private void DynamicUpdate(bool shouldUpdate)
	{
		if (ForceCleanupQueued || !IsPaused)
		{
			CheckCleanup();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (StaggeredUpdateManager.Instance != null)
		{
			StaggeredUpdateManager.Instance.UnregisterObject("ToolCleanup", this);
		}
		tool.PostResetEvent -= OnReset;
	}

	private void OnReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		isResetting = false;
		hasMoved = false;
		if (base.hasAuthority)
		{
			ForceCleanupQueued = false;
		}
		lastResetPosition = position;
		lastResetRotation = rotation;
	}

	public void AuthorityQueueForceCleanup()
	{
		if (base.hasAuthority)
		{
			ForceCleanupQueued = true;
			resetTimerStart = UnityEngine.Time.time;
		}
	}

	public void PauseCleanup(object token)
	{
		pauseTokens.Add(token);
	}

	public void ResumeCleanup(object token)
	{
		pauseTokens.Remove(token);
	}

	public void CheckCleanup()
	{
		if (Owner != null)
		{
			CheckCleanupOwner(Owner);
		}
		else
		{
			CheckCleanupOwnerless();
		}
	}

	private void CheckCleanupOwnerless()
	{
		if (!isResetting && !(tool == null))
		{
			if (!ForceCleanupQueued && (!hasMoved || !tool.hasAuthority || !base.gameObject.activeSelf))
			{
				hasMoved = HasTranslated || HasRotated;
				resetTimerStart = UnityEngine.Time.time;
			}
			else if (!CouldCleanup)
			{
				resetTimerStart = UnityEngine.Time.time;
			}
			else if ((ForceCleanupQueued || !IsCloseToAnyPlayer) && resetTimerStart + DelayUntilCleanup < UnityEngine.Time.time)
			{
				isResetting = true;
				AuthorityReset();
			}
		}
	}

	private void CheckCleanupOwner(Player owner)
	{
		if (isResetting || tool == null)
		{
			return;
		}
		if (!hasMoved || !tool.PlayerSpawnedEquipment.IsMine || !base.gameObject.activeSelf)
		{
			hasMoved = HasTranslated || HasRotated;
			resetTimerStart = UnityEngine.Time.time;
		}
		else if (!CouldCleanup || IsCloseToPlayer(owner))
		{
			resetTimerStart = UnityEngine.Time.time;
		}
		else if (resetTimerStart + DelayUntilCleanup < UnityEngine.Time.time)
		{
			isResetting = true;
			if (!tool.hasAuthority)
			{
				tool.photonView.TransferOwnership(PhotonNetwork.player);
			}
			AuthorityReset();
		}
	}

	private void AuthorityReset()
	{
		if (CustomGetResetPositionAndOrientationBehavior == null || !CustomGetResetPositionAndOrientationBehavior(out var position, out var orientation))
		{
			position = ResetPosition;
			orientation = ResetRotation;
		}
		tool.AuthorityResetToDefault(position, orientation, sleepPhysics: false, wasCleanedUp: true);
	}

	private bool IsCloseToPlayer(Player player)
	{
		if (player != null)
		{
			float minPlayerDistanceBeforeCleanup = MinPlayerDistanceBeforeCleanup;
			return (player.CurrentFloorPosition - tool.transform.position).sqrMagnitude < minPlayerDistanceBeforeCleanup * minPlayerDistanceBeforeCleanup;
		}
		return false;
	}

	public void SandboxOverride_Set(CleanupOverrides newOverrides)
	{
		if (newOverrides.IsActive && !Overrides.IsActive)
		{
			newOverrides.Position = tool.transform.position;
			newOverrides.Rotation = tool.transform.rotation;
		}
		else
		{
			newOverrides.Position = Overrides.Position;
			newOverrides.Rotation = Overrides.Rotation;
		}
		Overrides = newOverrides;
	}

	public CleanupOverrides SandboxOverride_Get()
	{
		return Overrides;
	}

	public void AuthorityClearSettingOverrides()
	{
		Overrides = CleanupOverrides.Default;
	}

	public void DeserializeFrom(PersistableDeserializeParams deserializeParams)
	{
		if (deserializeParams.viewData.ToolCleanupData != null)
		{
			ToolCleanupData.Types.CleanupOverrides overrides = deserializeParams.viewData.ToolCleanupData.Overrides;
			if (overrides != null)
			{
				Overrides = new CleanupOverrides
				{
					IsActive = true,
					Position = overrides.Position.ToVector3(),
					Rotation = overrides.Rotation.ToQuaternion(),
					Delay = overrides.Delay
				};
			}
		}
	}

	public void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
	{
		if (Overrides.IsActive)
		{
			if (viewData.ToolCleanupData != null)
			{
				UnityEngine.Debug.LogErrorFormat(this, "Error serializing ToolCleanup {0}: Data already specified.", base.gameObject);
				return;
			}
			viewData.ToolCleanupData = new ToolCleanupData();
			viewData.ToolCleanupData.Overrides = new ToolCleanupData.Types.CleanupOverrides
			{
				Position = Overrides.Position.ToVector3Data(),
				Rotation = Overrides.Rotation.ToVector3Data(),
				Delay = Overrides.Delay
			};
		}
	}

	public static ToolCleanup VerifyToolCleanup(GameObject gameObject)
	{
		ToolCleanup toolCleanup = gameObject.GetComponent<ToolCleanup>();
		if (toolCleanup == null)
		{
			toolCleanup = gameObject.AddComponent<ToolCleanup>();
		}
		return toolCleanup;
	}
}
public class ToolCollider : RecRoomCollider
{
	[HideInInspector]
	public Tool Tool;
}
public abstract class ToolGroup : Photon.MonoBehaviour
{
	protected List<ToolGroupElement> children = new List<ToolGroupElement>();

	protected BoxCollider groupBoxCollider;

	protected Bounds groupBounds = default(Bounds);

	[SerializeField]
	protected GroupSearchCustomGeometry defaultSearchCollider;

	[SerializeField]
	protected GroupSearchCustomGeometry heldSearchCollider;

	private Coroutine delayedRemoveUpdateCoroutine;

	protected static readonly Vector3[] CornerMasks = new Vector3[8]
	{
		new Vector3(1f, 1f, -1f),
		new Vector3(1f, -1f, -1f),
		new Vector3(-1f, 1f, -1f),
		new Vector3(-1f, -1f, -1f),
		new Vector3(1f, 1f, 1f),
		new Vector3(1f, -1f, 1f),
		new Vector3(-1f, 1f, 1f),
		new Vector3(-1f, -1f, 1f)
	};

	private ToolGroup _hoveredGroup;

	[SerializeField]
	private float removeMinDistance = 0.05f;

	public Tool Tool { get; private set; }

	protected GroupSearchCustomGeometry SearchCollider => (!Tool.IsHeld || !(heldSearchCollider != null)) ? defaultSearchCollider : heldSearchCollider;

	public int Size => children.Count;

	public IEnumerable<ToolGroupElement> Children => children;

	protected ToolGroup hoveredGroup
	{
		get
		{
			return _hoveredGroup;
		}
		set
		{
			if (!(_hoveredGroup == value))
			{
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddGroupHighlight(null);
				}
				_hoveredGroup = value;
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddGroupHighlight(this);
				}
			}
		}
	}

	protected bool DelayedUpdateCoroutineIsRunning => delayedRemoveUpdateCoroutine != null;

	private bool DefaultAddHighlightEnabled
	{
		set
		{
			for (int i = 0; i < children.Count; i++)
			{
				bool frontAddHighlightEnabled = i == children.Count - 1 && value;
				children[i].FrontAddHighlightEnabled = frontAddHighlightEnabled;
				children[i].BackAddHighlightEnabled = false;
			}
		}
	}

	protected override void Awake()
	{
		base.Awake();
		PhotonNetwork.OnPhotonPlayerConnected += new Action<PhotonPlayer>(OnPhotonPlayerConnected);
		groupBoxCollider = GetComponentInChildren<BoxCollider>();
		DisplayAddToolHighlight(null);
		DisplayAddGroupHighlight(null);
		Tool = GetComponent<Tool>();
		if (Tool != null)
		{
			Tool.PostReleaseEvent += OnPostRelease;
			Tool.HoverStartEvent += OnHoverStart;
			Tool.HoverEndEvent += OnHoverEnd;
			Tool.VisibilityChangeEvent += OnVisibilityChange;
			Tool.CustomVisibilityBehavior = VisibilityBehavior;
			Tool.CustomSelectionForwarding = ToolSelectionForwarding;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Tool != null)
		{
			Tool.PostReleaseEvent -= OnPostRelease;
			Tool.HoverStartEvent -= OnHoverStart;
			Tool.HoverEndEvent -= OnHoverEnd;
			Tool.VisibilityChangeEvent -= OnVisibilityChange;
		}
		PhotonNetwork.OnPhotonPlayerConnected -= new Action<PhotonPlayer>(OnPhotonPlayerConnected);
	}

	public void AuthorityDestroy()
	{
		if (base.hasAuthority)
		{
			PhotonNetwork.Destroy(base.gameObject);
		}
	}

	public void AuthorityAddChildren(ToolGroupElement[] children)
	{
		if (base.hasAuthority && children != null && children.Length > 0 && CanAddChild(children[0]))
		{
			Vector3[] array = new Vector3[children.Length];
			Quaternion[] array2 = new Quaternion[children.Length];
			for (int i = 0; i < children.Length; i++)
			{
				ref Vector3 reference = ref array[i];
				reference = base.transform.InverseTransformPoint(children[i].transform.position);
				ref Quaternion reference2 = ref array2[i];
				reference2 = base.transform.InverseTransformRotation(children[i].transform.rotation);
			}
			AuthorityAddChildren(children, array, array2);
		}
	}

	public void AuthorityAddChildren(ToolGroupElement[] children, Vector3[] localPositions, Quaternion[] localRotations)
	{
		if (base.hasAuthority && children != null && localPositions != null && localRotations != null && children.Length > 0 && children.Length == localPositions.Length && children.Length == localRotations.Length && CanAddChild(children[0]))
		{
			int[] array = new int[children.Length];
			for (int i = 0; i < children.Length; i++)
			{
				array[i] = children[i].photonView.viewID;
			}
			int desiredNewChildIndex = GetDesiredNewChildIndex(children[0], localPositions[0], localRotations[0]);
			base.photonView.RpcAll(RpcAddChildren, array, localPositions, localRotations, desiredNewChildIndex);
		}
	}

	public void AuthorityAddChild(ToolGroupElement child)
	{
		Vector3 localPosition = base.transform.InverseTransformPoint(child.transform.position);
		Quaternion localRotation = base.transform.InverseTransformRotation(child.transform.rotation);
		AuthorityAddChild(child, localPosition, localRotation);
	}

	public void AuthorityAddChild(ToolGroupElement child, Vector3 localPosition, Quaternion localRotation)
	{
		if (base.hasAuthority && ((child != null) & CanAddChild(child)))
		{
			int desiredNewChildIndex = GetDesiredNewChildIndex(child, localPosition, localRotation);
			base.photonView.RpcAll(RpcAddChild, child, localPosition, localRotation, desiredNewChildIndex);
		}
	}

	public void AuthorityAddGroup(ToolGroup group)
	{
		if (base.hasAuthority && group != null && group.hasAuthority && CanAddGroup(group))
		{
			ToolGroupElement[] array = group.children.ToArray();
			group.AuthorityClearTools();
			AuthorityAddChildren(array);
		}
	}

	public void AuthorityRemoveChild(ToolGroupElement child)
	{
		if (base.hasAuthority && child != null)
		{
			base.photonView.RpcAll(RpcRemoveChild, child);
		}
	}

	public void AuthorityClearTools()
	{
		if (base.hasAuthority)
		{
			base.photonView.RpcAll(RpcClearChildren);
		}
	}

	public void AuthorityReorderTools(int[] toolPhotonViewIds)
	{
		if (base.hasAuthority)
		{
			base.photonView.RpcAll(RpcReorderChildren, toolPhotonViewIds);
		}
	}

	private void AddChild(ToolGroupElement child, Vector3 localPosition, Quaternion localRotation, int desiredIndex, bool applyChangesToEntireGroup = true)
	{
		if (child != this && !children.Contains(child))
		{
			OnAddChild(child);
			if (base.hasAuthority && Size == 0 && child.Tool.IsHeld && child.Tool.Owner.isLocal)
			{
				ToolHolderInfo holderInfo = child.Tool.HolderInfo;
				child.Tool.HolderInfo = ToolHolderInfo.NotHeld;
				Tool.HolderInfo = holderInfo;
			}
			if (desiredIndex >= 0 && desiredIndex < children.Count)
			{
				children.Insert(desiredIndex, child);
			}
			else
			{
				children.Add(child);
			}
			child.Group = this;
			child.UpdateGroupLayout(localPosition, localRotation, localPosition, localRotation);
			child.Tool.SetCollisionLayer(child.Tool.HeldCollisionLayer);
			for (int i = 0; i < child.Tool.Colliders.Count; i++)
			{
				child.Tool.Colliders[i].IsTrigger = true;
			}
			if (applyChangesToEntireGroup)
			{
				UpdateGroupLayout();
				UpdateGroupCollider();
			}
		}
	}

	protected void StartDelayedUpdateOnRemove(ToolGroupElement removedTool)
	{
		StopDelayedUpdateOnRemove();
		delayedRemoveUpdateCoroutine = StartCoroutine(DelayedUpdateGroupOnRemove(removedTool));
	}

	protected void StopDelayedUpdateOnRemove()
	{
		if (DelayedUpdateCoroutineIsRunning)
		{
			StopCoroutine(delayedRemoveUpdateCoroutine);
			delayedRemoveUpdateCoroutine = null;
		}
	}

	private IEnumerator DelayedUpdateGroupOnRemove(ToolGroupElement removedTool)
	{
		while (!((removedTool.transform.position - base.transform.position).sqrMagnitude > removeMinDistance * removeMinDistance))
		{
			yield return null;
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
		delayedRemoveUpdateCoroutine = null;
	}

	private void RemoveChild(ToolGroupElement child, bool removingSingleTool = true)
	{
		if (!(child.Group == this) || !children.Contains(child))
		{
			return;
		}
		children.Remove(child);
		child.Group = null;
		child.Tool.RigidbodyPickup.Release();
		child.Tool.SetVisible(visible: true);
		Tool.SetCollisionLayer(Layers.DynamicPhysics);
		for (int i = 0; i < child.Tool.Colliders.Count; i++)
		{
			child.Tool.Colliders[i].IsTrigger = false;
		}
		OnRemoveChild(child);
		if (removingSingleTool)
		{
			StartCoroutine(DelayedUpdateGroupOnRemove(child));
			if (base.hasAuthority && Size == 0 && Tool.IsHeld && Tool.Owner.isLocal)
			{
				Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
		}
	}

	private void ClearChildren()
	{
		while (children.Count > 0)
		{
			RemoveChild(children[0], removingSingleTool: false);
		}
	}

	private void ReorderChildren(int[] photonViewIds)
	{
		for (int i = 0; i < photonViewIds.Length; i++)
		{
			PhotonView photonView = PhotonView.Find(photonViewIds[i]);
			if (photonView != null)
			{
				ToolGroupElement component = photonView.GetComponent<ToolGroupElement>();
				if (component != null)
				{
					children[i] = component;
				}
			}
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
	}

	protected virtual void OnAddChild(ToolGroupElement child)
	{
	}

	protected virtual void OnRemoveChild(ToolGroupElement child)
	{
	}

	protected virtual int GetDesiredNewChildIndex(ToolGroupElement newChild, Vector3 localPosition, Quaternion localRotation)
	{
		return -1;
	}

	public virtual bool CanAddChild(ToolGroupElement child)
	{
		return true;
	}

	public virtual bool CanAddGroup(ToolGroup group)
	{
		return true;
	}

	public void AuthorityClone(ToolGroup oldGroup)
	{
		if (base.hasAuthority)
		{
			if (!Tool.IsHeld && oldGroup.Tool.IsHeld && oldGroup.Tool.Owner.isLocal)
			{
				ToolHolderInfo holderInfo = oldGroup.Tool.HolderInfo;
				oldGroup.Tool.HolderInfo = ToolHolderInfo.NotHeld;
				Tool.HolderInfo = holderInfo;
			}
			base.transform.position = oldGroup.transform.position;
			base.transform.rotation = oldGroup.transform.rotation;
			AuthorityAddGroup(oldGroup);
			OnCloned(oldGroup);
		}
	}

	protected virtual void Update()
	{
		UpdateHover();
	}

	protected void UpdateHover()
	{
		if (!base.hasAuthority)
		{
			hoveredGroup = null;
		}
		else
		{
			hoveredGroup = SearchCollider.FindGroup(null, this);
		}
	}

	protected void TryAddToHoveredGroup()
	{
		if (base.hasAuthority && hoveredGroup != null)
		{
			if (!hoveredGroup.hasAuthority)
			{
				hoveredGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (hoveredGroup.hoveredGroup == this)
			{
				hoveredGroup.hoveredGroup = null;
			}
			hoveredGroup.AuthorityAddGroup(this);
			hoveredGroup = null;
			AuthorityDestroy();
		}
	}

	protected virtual void OnCloned(ToolGroup oldGroup)
	{
	}

	public virtual void DisplayAddToolHighlight(ToolGroupElement toolToAdd)
	{
		DefaultAddHighlightEnabled = toolToAdd != null;
	}

	public virtual void DisplayAddGroupHighlight(ToolGroup groupToAdd)
	{
		DefaultAddHighlightEnabled = groupToAdd != null;
	}

	private void OnPostRelease(Tool tool)
	{
		TryAddToHoveredGroup();
	}

	public virtual ToolGroupElement GetHighlightedChildInGroup(ToolGroupElement child, Player player, bool physicalPickup)
	{
		return null;
	}

	protected virtual Tool ToolSelectionForwarding(Player selectingPlayer, bool physicalPickupSelection, Collider selectedCollider)
	{
		return null;
	}

	private void OnVisibilityChange(bool visible, bool isRemoteVisible = false)
	{
		for (int i = 0; i < children.Count; i++)
		{
			children[i].Tool.SetVisible(visible, isRemoteVisible);
		}
	}

	private bool VisibilityBehavior()
	{
		for (int i = 0; i < children.Count; i++)
		{
			if (children[i].Tool.IsVisible)
			{
				return true;
			}
		}
		return false;
	}

	public virtual void OnChildInGroupHoverStart(ToolGroupElement child)
	{
	}

	public virtual void OnChildInGroupHoverEnd(ToolGroupElement child)
	{
	}

	protected virtual void OnHoverStart(Tool thisTool)
	{
		if (Size > 0)
		{
			for (int i = 0; i < children.Count; i++)
			{
				children[i].Tool.HoverStart();
			}
		}
	}

	protected virtual void OnHoverEnd(Tool thisTool)
	{
		if (Size > 0)
		{
			for (int i = 0; i < children.Count; i++)
			{
				children[i].Tool.HoverEnd();
			}
		}
	}

	protected virtual void UpdateGroupLayout()
	{
	}

	protected void UpdateGroupCollider()
	{
		if (!(groupBoxCollider != null))
		{
			return;
		}
		groupBounds.center = Vector3.zero;
		groupBounds.size = Vector3.zero;
		for (int i = 0; i < children.Count; i++)
		{
			Vector3 vector = children[i].LocalBoundingBox.center.TransformCoordinateSpace(children[i].ColliderLocalPosition, children[i].ColliderLocalRotation);
			for (int j = 0; j < CornerMasks.Length; j++)
			{
				Vector3 vector2 = Vector3.Scale(children[i].LocalBoundingBox.extents, CornerMasks[j]).TransformCoordinateSpace(Vector3.zero, children[i].ColliderLocalRotation);
				groupBounds.Encapsulate(vector + vector2);
			}
		}
		groupBoxCollider.center = groupBounds.center;
		groupBoxCollider.size = groupBounds.size;
		SearchCollider.Center = groupBoxCollider.center;
		SearchCollider.Size = groupBoxCollider.size;
	}

	[PunRPC]
	protected void RpcAddChild(ToolGroupElement child, Vector3 localPosition, Quaternion localRotation, int desiredIndex)
	{
		if (child != null && child != this)
		{
			AddChild(child, localPosition, localRotation, desiredIndex);
		}
	}

	[PunRPC]
	protected void RpcAddChildren(int[] childrenPhotonViewIds, Vector3[] localPositions, Quaternion[] localRotations, int desiredStartingIndex)
	{
		for (int i = 0; i < childrenPhotonViewIds.Length; i++)
		{
			PhotonView photonView = PhotonView.Find(childrenPhotonViewIds[i]);
			if (photonView != null)
			{
				ToolGroupElement component = photonView.GetComponent<ToolGroupElement>();
				if (component != null && component != this)
				{
					AddChild(component, localPositions[i], localRotations[i], desiredStartingIndex + i, applyChangesToEntireGroup: false);
				}
			}
		}
		UpdateGroupLayout();
		UpdateGroupCollider();
	}

	[PunRPC]
	protected void RpcRemoveChild(ToolGroupElement child)
	{
		if (child != null && child != this)
		{
			RemoveChild(child);
		}
	}

	[PunRPC]
	protected void RpcClearChildren()
	{
		ClearChildren();
	}

	[PunRPC]
	protected void RpcInitializeGroup(int[] childrenPhotonViewIds, Vector3[] childrenLocalPositions, Quaternion[] childrenLocalRotations)
	{
		RpcAddChildren(childrenPhotonViewIds, childrenLocalPositions, childrenLocalRotations, -1);
	}

	[PunRPC]
	protected void RpcReorderChildren(int[] childrenPhotonViewIds)
	{
		ReorderChildren(childrenPhotonViewIds);
	}

	protected virtual void OnPhotonPlayerConnected(PhotonPlayer otherPlayer)
	{
		if (base.hasAuthority)
		{
			int[] array = new int[children.Count];
			Vector3[] array2 = new Vector3[children.Count];
			Quaternion[] array3 = new Quaternion[children.Count];
			for (int i = 0; i < children.Count; i++)
			{
				array[i] = children[i].photonView.viewID;
				ref Vector3 reference = ref array2[i];
				reference = children[i].GroupLocalPosition;
				ref Quaternion reference2 = ref array3[i];
				reference2 = children[i].GroupLocalRotation;
			}
			base.photonView.RpcPlayer(otherPlayer, RpcInitializeGroup, array, array2, array3);
		}
	}

	protected void TransferOwnership(PhotonPlayer newOwner)
	{
		foreach (ToolGroupElement child in children)
		{
			child.photonView.TransferOwnership(newOwner);
		}
		base.photonView.TransferOwnership(newOwner);
	}
}
[RequireComponent(typeof(Tool))]
public abstract class ToolGroupElement : Photon.MonoBehaviour
{
	[Header("Groupable Tool")]
	[SerializeField]
	private GameObject frontGroupAddHighlightVisual;

	[SerializeField]
	private GameObject backGroupAddHighlightVisual;

	[SerializeField]
	protected GroupSearch defaultSearchCollider;

	[SerializeField]
	protected GroupSearch heldSearchCollider;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Tool tool;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private VisibleInCamera visibleInCamera;

	private SynchronizedField<int> _thisGroupId;

	[NonSerialized]
	public ToolGroup Group;

	private ToolGroupElement[] newGroupInitialTools;

	private ToolGroupElement _hoveredGroupableTool;

	private ToolGroup _hoveredGroup;

	public ToolGroup ThisGroup
	{
		get
		{
			PhotonView photonView = PhotonView.Find(_thisGroupId.Get());
			return (!(photonView != null)) ? null : photonView.GetComponent<ToolGroup>();
		}
		set
		{
			int newValue = ((!(value != null)) ? (-1) : value.photonView.viewID);
			_thisGroupId.Set(newValue);
		}
	}

	public Vector3 GroupLocalPosition { get; protected set; }

	public Quaternion GroupLocalRotation { get; protected set; }

	public Vector3 ColliderLocalPosition { get; protected set; }

	public Quaternion ColliderLocalRotation { get; protected set; }

	public Bounds LocalBoundingBox { get; private set; }

	public Tool Tool => tool;

	public VisibleInCamera VisibleInCamera => visibleInCamera;

	public bool IsInGroup => Group != null;

	protected ToolGroupElement hoveredGroupableTool
	{
		get
		{
			return _hoveredGroupableTool;
		}
		set
		{
			if (!(_hoveredGroupableTool == value))
			{
				if (_hoveredGroupableTool != null)
				{
					_hoveredGroupableTool.DisplayAddToolHighlight(null);
				}
				_hoveredGroupableTool = value;
				if (_hoveredGroupableTool != null)
				{
					_hoveredGroupableTool.DisplayAddToolHighlight(this);
				}
			}
		}
	}

	protected ToolGroup hoveredGroup
	{
		get
		{
			return _hoveredGroup;
		}
		set
		{
			if (!(_hoveredGroup == value))
			{
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddToolHighlight(null);
				}
				_hoveredGroup = value;
				if (_hoveredGroup != null)
				{
					_hoveredGroup.DisplayAddToolHighlight(this);
				}
			}
		}
	}

	public bool FrontAddHighlightEnabled
	{
		get
		{
			return frontGroupAddHighlightVisual != null && frontGroupAddHighlightVisual.activeSelf;
		}
		set
		{
			if (frontGroupAddHighlightVisual != null)
			{
				frontGroupAddHighlightVisual.SetActive(value);
			}
		}
	}

	public bool BackAddHighlightEnabled
	{
		get
		{
			return backGroupAddHighlightVisual != null && backGroupAddHighlightVisual.activeSelf;
		}
		set
		{
			if (backGroupAddHighlightVisual != null)
			{
				backGroupAddHighlightVisual.SetActive(value);
			}
		}
	}

	protected GroupSearch SearchCollider => (!Tool.IsHeld || !(heldSearchCollider != null)) ? defaultSearchCollider : heldSearchCollider;

	protected abstract string GroupPrefabName { get; }

	protected override void Awake()
	{
		base.Awake();
		GroupLocalPosition = Vector3.zero;
		GroupLocalRotation = Quaternion.identity;
		DisplayAddToolHighlight(null);
		Tool.PrePickupEvent += OnPrePickup;
		Tool.PostReleaseEvent += OnPostRelease;
		Tool.HoverStartEvent += OnHoverStart;
		Tool.HoverEndEvent += OnHoverEnd;
		Tool.CustomSelectionForwarding = ToolSelectionForwarding;
	}

	protected virtual void Start()
	{
		Quaternion rotation = base.transform.rotation;
		base.transform.rotation = Quaternion.identity;
		Bounds colliderBounds = Tool.GetColliderBounds();
		LocalBoundingBox = new Bounds(base.transform.InverseTransformPoint(colliderBounds.center), colliderBounds.size);
		base.transform.rotation = rotation;
		Tool.RigidbodyPickup.ReachedTargetEvent += OnReachedHand;
		Renderer[] array = null;
		if (frontGroupAddHighlightVisual != null)
		{
			array = frontGroupAddHighlightVisual.GetComponentsInChildren<Renderer>();
			for (int i = 0; i < array.Length; i++)
			{
				Tool.TryRemoveRenderer(array[i]);
			}
		}
		if (backGroupAddHighlightVisual != null)
		{
			array = backGroupAddHighlightVisual.GetComponentsInChildren<Renderer>();
			for (int j = 0; j < array.Length; j++)
			{
				Tool.TryRemoveRenderer(array[j]);
			}
		}
	}

	protected override void OnDestroy()
	{
		if (IsInGroup && Group.hasAuthority)
		{
			Group.AuthorityRemoveChild(this);
		}
		Tool.PrePickupEvent -= OnPrePickup;
		Tool.PostReleaseEvent -= OnPostRelease;
		Tool.HoverStartEvent -= OnHoverStart;
		Tool.HoverEndEvent -= OnHoverEnd;
		Tool.RigidbodyPickup.ReachedTargetEvent -= OnReachedHand;
		base.OnDestroy();
	}

	public virtual bool CanAddTool(ToolGroupElement tool)
	{
		return true;
	}

	protected virtual void Update()
	{
		UpdateHover();
		if (!Tool.IsHeld && (FrontAddHighlightEnabled || BackAddHighlightEnabled))
		{
			FrontAddHighlightEnabled = false;
			BackAddHighlightEnabled = false;
		}
	}

	public void UpdateGroupLayout(Vector3 localPosition, Quaternion localRotation, Vector3 colliderLocalPosition, Quaternion colliderLocalRotation)
	{
		if (IsInGroup)
		{
			GroupLocalPosition = localPosition;
			GroupLocalRotation = localRotation;
			ColliderLocalPosition = colliderLocalPosition;
			ColliderLocalRotation = colliderLocalRotation;
			Tool.RigidbodyPickup.Pickup(Group.Tool.RigidbodyEx, GroupLocalPosition, GroupLocalRotation);
		}
	}

	private void OnPrePickup(Tool tool)
	{
		if (IsInGroup)
		{
			if (!Group.hasAuthority && tool.HolderPlayer.isLocal)
			{
				Group.photonView.TransferOwnership(PhotonNetwork.player);
			}
			ToolGroup toolGroup = Group;
			Group.AuthorityRemoveChild(this);
			if (toolGroup.Size == 0)
			{
				toolGroup.AuthorityDestroy();
			}
		}
	}

	private void OnReachedHand()
	{
	}

	private void OnPostRelease(Tool tool)
	{
		if (IsInGroup && !tool.HolderPlayer.isLocal)
		{
			UpdateGroupLayout(GroupLocalPosition, GroupLocalRotation, ColliderLocalPosition, ColliderLocalRotation);
		}
		TryAddToHoveredGroup();
	}

	private void UpdateHover()
	{
		if (IsInGroup || !base.hasAuthority)
		{
			hoveredGroupableTool = null;
			hoveredGroup = null;
			return;
		}
		hoveredGroupableTool = SearchCollider.FindGroupableTool(this);
		if (hoveredGroupableTool != null)
		{
			hoveredGroup = null;
		}
		else
		{
			hoveredGroup = SearchCollider.FindGroup(this);
		}
	}

	protected void TryAddToHoveredGroup()
	{
		if (!base.hasAuthority)
		{
			return;
		}
		if (hoveredGroup != null)
		{
			if (!hoveredGroup.hasAuthority)
			{
				hoveredGroup.photonView.TransferOwnership(PhotonNetwork.player);
			}
			hoveredGroup.AuthorityAddChild(this);
			hoveredGroup = null;
		}
		else if (hoveredGroupableTool != null)
		{
			ToolGroup toolGroup = hoveredGroupableTool.CreateNewGroup();
			if (hoveredGroupableTool.hoveredGroupableTool == this)
			{
				hoveredGroupableTool.hoveredGroupableTool = null;
			}
			toolGroup.AuthorityAddChild(hoveredGroupableTool);
			toolGroup.AuthorityAddChild(this);
			hoveredGroupableTool = null;
		}
	}

	private void InitializeNewGroup(ToolGroup newGroup)
	{
		if (newGroupInitialTools != null && newGroupInitialTools.Length > 0)
		{
			for (int i = 0; i < newGroupInitialTools.Length; i++)
			{
				newGroupInitialTools[i].hoveredGroupableTool = null;
			}
			newGroup.AuthorityAddChildren(newGroupInitialTools);
		}
	}

	public ToolGroup CreateNewGroup()
	{
		if (PhotonNetwork.isMasterClient)
		{
			return MasterCreateNewGroup();
		}
		RequestMasterCreateNewGroup();
		return AuthorityCreateTemporaryGroup();
	}

	private void RequestMasterCreateNewGroup()
	{
		base.photonView.RpcMaster(RpcMasterCreateNewGroup);
	}

	private ToolGroup MasterCreateNewGroup()
	{
		ToolGroup result = null;
		if (PhotonNetwork.isMasterClient)
		{
			result = PhotonNetwork.InstantiateSceneObject(GroupPrefabName, base.transform.position, base.transform.rotation, 1f, 0, null).GetComponent<ToolGroup>();
		}
		return result;
	}

	private ToolGroup AuthorityCreateTemporaryGroup()
	{
		return PhotonNetwork.Instantiate(GroupPrefabName, base.transform.position, base.transform.rotation, 1f, 0, null).GetComponent<ToolGroup>();
	}

	private void OnMasterGroupCreation(ToolGroup newGroup)
	{
		if (!newGroup.hasAuthority)
		{
			newGroup.photonView.TransferOwnership(PhotonNetwork.player);
		}
		if (!IsInGroup || (Group.Tool.IsHeld && !Group.Tool.Owner.isLocal))
		{
			newGroup.AuthorityDestroy();
			return;
		}
		ToolGroup toolGroup = Group;
		newGroup.AuthorityClone(toolGroup);
		toolGroup.AuthorityDestroy();
	}

	public virtual void DisplayAddToolHighlight(ToolGroupElement toolToAdd)
	{
		FrontAddHighlightEnabled = toolToAdd != null;
		BackAddHighlightEnabled = false;
	}

	private void OnHoverStart(Tool thisTool)
	{
		if (IsInGroup)
		{
			Group.OnChildInGroupHoverStart(this);
		}
	}

	private void OnHoverEnd(Tool thisTool)
	{
		if (IsInGroup)
		{
			Group.OnChildInGroupHoverEnd(this);
		}
	}

	private Tool ToolSelectionForwarding(Player selectingPlayer, bool physicalPickupSelection, Collider selectedCollider)
	{
		if (IsInGroup)
		{
			ToolGroupElement highlightedChildInGroup = Group.GetHighlightedChildInGroup(this, selectingPlayer, physicalPickupSelection);
			if (highlightedChildInGroup != null)
			{
				return highlightedChildInGroup.Tool;
			}
			return Group.Tool;
		}
		return Tool;
	}

	[PunRPC]
	protected void RpcMasterCreateNewGroup(PhotonMessageInfo messageInfo)
	{
		PhotonPlayer sender = messageInfo.sender;
		if (PhotonNetwork.isMasterClient && sender != null)
		{
			ToolGroup toolGroup = MasterCreateNewGroup();
			if (toolGroup != null)
			{
				base.photonView.RpcPlayer(sender, RpcOnMasterGroupCreation, toolGroup);
			}
		}
	}

	[PunRPC]
	protected void RpcOnMasterGroupCreation(ToolGroup group)
	{
		if (group != null)
		{
			OnMasterGroupCreation(group);
		}
	}
}
namespace RecRoom
