public sealed class ToolHolderInfo : IEquatable<ToolHolderInfo>
{
	public enum HolderType : byte
	{
		HELD_BY_PLAYER = 0,
		ATTACHED_TO_OBJECT = 1,
		EQUIPPED_ON_PLAYER = 2,
		INVALID = byte.MaxValue
	}

	public readonly int PhotonViewId;

	public readonly HolderType Type;

	public readonly Vector3 RelativePosition;

	public readonly Quaternion RelativeRotation;

	public readonly float RelativeScale;

	public static readonly ToolHolderInfo NotHeld = new ToolHolderInfo(HolderType.INVALID, 0, Vector3.zero, Quaternion.identity, 1f);

	private const short memBufferSize = 37;

	private static readonly byte[] memBuffer = new byte[37];

	public bool IsHeld => PhotonViewId != 0;

	private ToolHolderInfo(HolderType type, int photonViewId, Vector3 relativePosition, Quaternion relativeRotation, float relativeScale)
	{
		Type = type;
		PhotonViewId = photonViewId;
		RelativePosition = relativePosition;
		RelativeRotation = relativeRotation;
		RelativeScale = relativeScale;
	}

	public static ToolHolderInfo HeldByPlayer(int photonViewId, Vector3 relativePosition, Quaternion relativeRotation, float relativeScale)
	{
		return new ToolHolderInfo(HolderType.HELD_BY_PLAYER, photonViewId, relativePosition, relativeRotation, relativeScale);
	}

	public static ToolHolderInfo EquippedOnPlayer(int photonViewId, Vector3 relativePosition, Quaternion relativeRotation, float relativeScale)
	{
		return new ToolHolderInfo(HolderType.EQUIPPED_ON_PLAYER, photonViewId, relativePosition, relativeRotation, relativeScale);
	}

	public static ToolHolderInfo AttachedToObject(int photonViewId, Vector3 relativePosition, Quaternion relativeRotation, float relativeScale)
	{
		return new ToolHolderInfo(HolderType.ATTACHED_TO_OBJECT, photonViewId, relativePosition, relativeRotation, relativeScale);
	}

	public override string ToString()
	{
		if (IsHeld)
		{
			return string.Format("PV{0} T{1} R{2} S{3}", PhotonViewId, RelativePosition.ToString("F2"), RelativeRotation.ToString("F2"), RelativeScale.ToString("F2"));
		}
		return "Not Held";
	}

	public override int GetHashCode()
	{
		int num = 17;
		num = num * 23 + Type.GetHashCode();
		num = num * 23 + PhotonViewId.GetHashCode();
		num = num * 23 + RelativePosition.GetHashCode();
		num = num * 23 + RelativeRotation.GetHashCode();
		return num * 23 + RelativeScale.GetHashCode();
	}

	public override bool Equals(object obj)
	{
		if (object.ReferenceEquals(obj, null))
		{
			return false;
		}
		if (object.ReferenceEquals(obj, this))
		{
			return true;
		}
		ToolHolderInfo toolHolderInfo = obj as ToolHolderInfo;
		if (object.ReferenceEquals(toolHolderInfo, null))
		{
			return false;
		}
		return IsEqual(toolHolderInfo);
	}

	public bool Equals(ToolHolderInfo other)
	{
		if (object.ReferenceEquals(other, null))
		{
			return false;
		}
		if (object.ReferenceEquals(other, this))
		{
			return true;
		}
		return IsEqual(other);
	}

	public static bool operator ==(ToolHolderInfo lhs, ToolHolderInfo rhs)
	{
		if (object.ReferenceEquals(lhs, rhs))
		{
			return true;
		}
		if (object.ReferenceEquals(lhs, null) || object.ReferenceEquals(rhs, null))
		{
			return false;
		}
		return lhs.IsEqual(rhs);
	}

	public static bool operator !=(ToolHolderInfo lhs, ToolHolderInfo rhs)
	{
		return !(lhs == rhs);
	}

	private bool IsEqual(ToolHolderInfo other)
	{
		return Type == other.Type && PhotonViewId == other.PhotonViewId && RelativePosition == other.RelativePosition && RelativeRotation == other.RelativeRotation && RelativeScale == other.RelativeScale;
	}

	public static short Serialize(StreamBuffer outStream, object customobject)
	{
		ToolHolderInfo toolHolderInfo = (ToolHolderInfo)customobject;
		lock (memBuffer)
		{
			memBuffer[0] = (byte)toolHolderInfo.Type;
			int targetOffset = 1;
			Protocol.Serialize(toolHolderInfo.PhotonViewId, memBuffer, ref targetOffset);
			Vector3 relativePosition = toolHolderInfo.RelativePosition;
			Protocol.Serialize(relativePosition.x, memBuffer, ref targetOffset);
			Vector3 relativePosition2 = toolHolderInfo.RelativePosition;
			Protocol.Serialize(relativePosition2.y, memBuffer, ref targetOffset);
			Vector3 relativePosition3 = toolHolderInfo.RelativePosition;
			Protocol.Serialize(relativePosition3.z, memBuffer, ref targetOffset);
			Quaternion relativeRotation = toolHolderInfo.RelativeRotation;
			Protocol.Serialize(relativeRotation.x, memBuffer, ref targetOffset);
			Quaternion relativeRotation2 = toolHolderInfo.RelativeRotation;
			Protocol.Serialize(relativeRotation2.y, memBuffer, ref targetOffset);
			Quaternion relativeRotation3 = toolHolderInfo.RelativeRotation;
			Protocol.Serialize(relativeRotation3.z, memBuffer, ref targetOffset);
			Quaternion relativeRotation4 = toolHolderInfo.RelativeRotation;
			Protocol.Serialize(relativeRotation4.w, memBuffer, ref targetOffset);
			Protocol.Serialize(toolHolderInfo.RelativeScale, memBuffer, ref targetOffset);
			outStream.Write(memBuffer, 0, 37);
		}
		return 37;
	}

	public static object Deserialize(StreamBuffer inStream, short length)
	{
		HolderType type;
		int value;
		Vector3 relativePosition = default(Vector3);
		Quaternion relativeRotation = default(Quaternion);
		float value2;
		lock (memBuffer)
		{
			inStream.Read(memBuffer, 0, 37);
			type = (HolderType)memBuffer[0];
			int offset = 1;
			Protocol.Deserialize(out value, memBuffer, ref offset);
			Protocol.Deserialize(out relativePosition.x, memBuffer, ref offset);
			Protocol.Deserialize(out relativePosition.y, memBuffer, ref offset);
			Protocol.Deserialize(out relativePosition.z, memBuffer, ref offset);
			Protocol.Deserialize(out relativeRotation.x, memBuffer, ref offset);
			Protocol.Deserialize(out relativeRotation.y, memBuffer, ref offset);
			Protocol.Deserialize(out relativeRotation.z, memBuffer, ref offset);
			Protocol.Deserialize(out relativeRotation.w, memBuffer, ref offset);
			Protocol.Deserialize(out value2, memBuffer, ref offset);
		}
		return new ToolHolderInfo(type, value, relativePosition, relativeRotation, value2);
	}
}
public static class ToolJointConstructor
{
	private const bool linearLocked = true;

	private const float linearLimit = 0f;

	private const float linearLimitBounciness = 0f;

	private const float linearLimitContactDistance = 0f;

	private const float linearSpring = 20f;

	private const float linearSpringDamper = 0.25f;

	private const bool angularLocked = false;

	private const float angularLimit = 0f;

	private const float angularLimitBounciness = 0f;

	private const float angularLimitContactDistance = 0f;

	private const float angularSpring = 20f;

	private const float angularSpringDamper = 0.25f;

	public static Joint AddConfigurableJoint(GameObject jointGameObject)
	{
		ConfigurableJoint configurableJoint = jointGameObject.AddComponent<ConfigurableJoint>();
		configurableJoint.xMotion = ConfigurableJointMotion.Locked;
		configurableJoint.yMotion = ConfigurableJointMotion.Locked;
		configurableJoint.zMotion = ConfigurableJointMotion.Locked;
		configurableJoint.linearLimit = new SoftJointLimit
		{
			limit = 0f,
			bounciness = 0f,
			contactDistance = 0f
		};
		configurableJoint.linearLimitSpring = new SoftJointLimitSpring
		{
			spring = 20f,
			damper = 0.25f
		};
		configurableJoint.angularXMotion = ConfigurableJointMotion.Limited;
		configurableJoint.angularYMotion = ConfigurableJointMotion.Limited;
		configurableJoint.angularZMotion = ConfigurableJointMotion.Limited;
		SoftJointLimit softJointLimit = new SoftJointLimit
		{
			limit = 0f,
			bounciness = 0f,
			contactDistance = 0f
		};
		configurableJoint.lowAngularXLimit = softJointLimit;
		configurableJoint.highAngularXLimit = softJointLimit;
		configurableJoint.angularYLimit = softJointLimit;
		configurableJoint.angularZLimit = softJointLimit;
		SoftJointLimitSpring softJointLimitSpring = new SoftJointLimitSpring
		{
			spring = 20f,
			damper = 0.25f
		};
		configurableJoint.angularXLimitSpring = softJointLimitSpring;
		configurableJoint.angularYZLimitSpring = softJointLimitSpring;
		return configurableJoint;
	}
}
public class ToolPlayerAttractor : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool enabledOnReset = true;

	[SerializeField]
	private bool enableOnPoolSpawn;

	[SerializeField]
	private bool enabledOnRelease;

	private Tool thisTool;

	private PulsingBeam pulsingBeam;

	private bool _suppressAttractor;

	public bool SuppressAttractor
	{
		get
		{
			return _suppressAttractor;
		}
		set
		{
			_suppressAttractor = value;
			if (_suppressAttractor)
			{
				pulsingBeam.gameObject.SetActive(value: false);
			}
		}
	}

	private void Awake()
	{
		pulsingBeam = GetComponentInChildren<PulsingBeam>(includeInactive: true);
		if (pulsingBeam == null)
		{
			UnityEngine.Debug.LogError("ToolPlayerAttactor missing required pulsing beam.");
			return;
		}
		thisTool = GetComponent<Tool>();
		if (thisTool == null)
		{
			UnityEngine.Debug.LogError(base.name + " is missing a tool component.");
			return;
		}
		thisTool.PostPickupEvent += OnThisToolPickup;
		thisTool.PostAttachEvent += OnThisToolAttach;
		thisTool.PostResetEvent += OnThisToolReset;
		thisTool.PostReleaseEvent += OnThisToolReleased;
		thisTool.PostDetachEvent += OnThisToolDetach;
	}

	private void Start()
	{
		if (thisTool != null)
		{
			Renderer[] componentsInChildren = pulsingBeam.GetComponentsInChildren<Renderer>(includeInactive: true);
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				thisTool.TryRemoveRenderer(componentsInChildren[i]);
			}
		}
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ModeChangeEvent += OnGameManagerModeChanged;
		}
		TrySetBeamActive(enabledOnReset || (thisTool.SpawnedFromPool && enableOnPoolSpawn));
	}

	private void OnDestroy()
	{
		thisTool.PostPickupEvent -= OnThisToolPickup;
		thisTool.PostAttachEvent -= OnThisToolAttach;
		thisTool.PostResetEvent -= OnThisToolReset;
		thisTool.PostReleaseEvent -= OnThisToolReleased;
		thisTool.PostDetachEvent -= OnThisToolDetach;
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.ModeChangeEvent -= OnGameManagerModeChanged;
		}
	}

	private void OnGameManagerModeChanged()
	{
		if (!thisTool.IsHeld)
		{
			TrySetBeamActive(enabledOnReset);
		}
	}

	public void OverrideSetEnableOnRelease(bool enableOnRelease)
	{
		enabledOnRelease = enableOnRelease;
	}

	public void OverrideSetEnableOnReset(bool enableOnReset)
	{
		enabledOnReset = enableOnReset;
	}

	public void SetColor(Color color)
	{
		if (pulsingBeam != null)
		{
			pulsingBeam.SetColor(color);
		}
	}

	private void TrySetBeamActive(bool active)
	{
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.ShowToolPlayerAttractors)
		{
			active = false;
		}
		if (SuppressAttractor)
		{
			active = false;
		}
		pulsingBeam.gameObject.SetActive(active);
	}

	private void OnThisToolPickup(Tool tool)
	{
		TrySetBeamActive(active: false);
	}

	private void OnThisToolAttach(Tool tool)
	{
		TrySetBeamActive(active: false);
	}

	private void OnThisToolReset(Tool tool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		TrySetBeamActive(enabledOnReset && (enableOnPoolSpawn || !thisTool.SpawnedFromPool));
	}

	private void OnThisToolReleased(Tool tool)
	{
		TrySetBeamActive(enabledOnRelease);
	}

	private void OnThisToolDetach(Tool tool)
	{
		TrySetBeamActive(enabledOnRelease);
	}
}
public class ToolTrail : UnityEngine.MonoBehaviour
{
	[Header("Held Trails")]
	[SerializeField]
	private bool visibleWhileHeld = true;

	[SerializeField]
	private float heldTime = 2f;

	[Header("Release Trails")]
	[SerializeField]
	private bool visibleUponRelease = true;

	[SerializeField]
	private float releaseTime = 2f;

	[SerializeField]
	private bool fadeOutUponRelease;

	[SerializeField]
	private float releaseFadeOutDuration = 1f;

	[Header("Force Applied Trails")]
	[FormerlySerializedAs("visibleAfterForceApplied")]
	[SerializeField]
	private bool visibleAfterAttackApplied = true;

	[SerializeField]
	private float forceAppliedTime = 2f;

	[SerializeField]
	private bool fadeOutAfterForceApplied = true;

	[SerializeField]
	private float forceAppliedFadeOutDuration = 1f;

	private Tool thisTool;

	private TrailRenderer trailRenderer;

	private Coroutine releaseFadeCoroutine;

	private void Awake()
	{
		thisTool = GetComponentInParent<Tool>();
		thisTool.PostReleaseEvent += OnRelease;
		thisTool.PostPickupEvent += OnPickup;
		thisTool.AttackAppliedEvent += OnAttackApplied;
		thisTool.PostResetEvent += OnReset;
		trailRenderer = GetComponent<TrailRenderer>();
	}

	private void Start()
	{
		HideTrail();
	}

	private void OnDisable()
	{
		StopReleaseFadeCoroutine();
	}

	private void OnDestroy()
	{
		thisTool.PostReleaseEvent -= OnRelease;
		thisTool.PostPickupEvent -= OnPickup;
		thisTool.AttackAppliedEvent -= OnAttackApplied;
	}

	private void OnReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
	{
		HideTrail();
	}

	private void OnRelease(Tool tool)
	{
		if (!visibleUponRelease)
		{
			HideTrail();
			return;
		}
		ShowTrail(releaseTime);
		if (fadeOutUponRelease)
		{
			StartFadeCoroutine(releaseFadeOutDuration, releaseTime);
		}
	}

	private void OnPickup(Tool tool)
	{
		StopReleaseFadeCoroutine();
		if (!visibleWhileHeld)
		{
			HideTrail();
		}
		else
		{
			ShowTrail(heldTime);
		}
	}

	private void OnAttackApplied(Tool thisTool, Weapon weapon, WeaponDamageType damageType, Vector3 point)
	{
		StopReleaseFadeCoroutine();
		if (!visibleAfterAttackApplied)
		{
			HideTrail();
			return;
		}
		ShowTrail(forceAppliedTime);
		if (fadeOutAfterForceApplied)
		{
			StartFadeCoroutine(forceAppliedFadeOutDuration, forceAppliedTime);
		}
	}

	private void StartFadeCoroutine(float duration, float maxTime)
	{
		StopReleaseFadeCoroutine();
		if (thisTool != null && thisTool.gameObject.activeSelf)
		{
			releaseFadeCoroutine = StartCoroutine(ReleaseFadeCoroutine(duration, maxTime));
		}
	}

	private void StopReleaseFadeCoroutine()
	{
		if (releaseFadeCoroutine != null)
		{
			StopCoroutine(releaseFadeCoroutine);
			releaseFadeCoroutine = null;
		}
	}

	private IEnumerator ReleaseFadeCoroutine(float duration, float maxTime)
	{
		float timeRemaining = duration;
		while (timeRemaining >= 0f)
		{
			yield return null;
			timeRemaining -= UnityEngine.Time.deltaTime;
			float t = timeRemaining / duration;
			trailRenderer.time = maxTime * t;
		}
		HideTrail();
		releaseFadeCoroutine = null;
	}

	private void HideTrail()
	{
		trailRenderer.enabled = false;
		trailRenderer.time = 0f;
	}

	private void ShowTrail(float lifetime)
	{
		trailRenderer.enabled = true;
		trailRenderer.time = lifetime;
	}
}
namespace RecRoom.Tools
{
	public class TranslationSnappingVisualization : UnityEngine.MonoBehaviour
	{
		private static int SHADER_COLOR_ID = Shader.PropertyToID("_MainColor");

		public LineRenderer[] boundsLineRenderers;

		public LineRenderer[] gridLineRenderers;

		[SerializeField]
		private Color boundsMainColor = Color.green;

		private IDisposable updateToken;

		private ISelectionBounds boundsContext;

		private float snapIncrement;

		private void Awake()
		{
			LineRenderer[] array = boundsLineRenderers;
			foreach (LineRenderer lineRenderer in array)
			{
				lineRenderer.material.SetColor(SHADER_COLOR_ID, boundsMainColor);
			}
		}

		public void Enable(ISelectionBounds boundsContext, float snapIncrement)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingShowGrid)
			{
				this.snapIncrement = snapIncrement;
				this.boundsContext = boundsContext;
				base.gameObject.SetActive(value: true);
				updateToken = this.Update30hz(StaggeredUpdate);
			}
		}

		public void Disable()
		{
			if (updateToken != null)
			{
				updateToken.Dispose();
			}
			updateToken = null;
			base.gameObject.SetActive(value: false);
		}

		private void StaggeredUpdate(float deltaTime)
		{
			Bounds selectionBounds = boundsContext.SelectionBounds;
			Vector3 center = selectionBounds.center;
			Vector3 vector = center - selectionBounds.size / 2f;
			Vector3 vector2 = vector + Vector3.right * selectionBounds.size.x;
			Vector3 vector3 = vector2 + Vector3.forward * selectionBounds.size.z;
			Vector3 vector4 = vector + Vector3.forward * selectionBounds.size.z;
			Vector3 vector5 = center + selectionBounds.size / 2f;
			Vector3 vector6 = vector5 + Vector3.left * selectionBounds.size.x;
			Vector3 vector7 = vector6 + Vector3.back * selectionBounds.size.z;
			Vector3 vector8 = vector5 + Vector3.back * selectionBounds.size.z;
			boundsLineRenderers[0].SetPositions(new Vector3[2] { vector, vector2 });
			boundsLineRenderers[1].SetPositions(new Vector3[2] { vector2, vector3 });
			boundsLineRenderers[2].SetPositions(new Vector3[2] { vector3, vector4 });
			boundsLineRenderers[3].SetPositions(new Vector3[2] { vector4, vector });
			boundsLineRenderers[4].SetPositions(new Vector3[2] { vector5, vector6 });
			boundsLineRenderers[5].SetPositions(new Vector3[2] { vector6, vector7 });
			boundsLineRenderers[6].SetPositions(new Vector3[2] { vector7, vector8 });
			boundsLineRenderers[7].SetPositions(new Vector3[2] { vector8, vector5 });
			boundsLineRenderers[8].SetPositions(new Vector3[2] { vector5, vector3 });
			boundsLineRenderers[9].SetPositions(new Vector3[2] { vector6, vector4 });
			boundsLineRenderers[10].SetPositions(new Vector3[2] { vector7, vector });
			boundsLineRenderers[11].SetPositions(new Vector3[2] { vector8, vector2 });
			float num = 0f;
			num = ((snapIncrement <= 0.01f) ? (snapIncrement / 10f) : ((!(snapIncrement <= 0.1f)) ? (snapIncrement / 200f) : (snapIncrement / 40f)));
			for (int i = 0; i < boundsLineRenderers.Length; i++)
			{
				boundsLineRenderers[i].enabled = true;
				boundsLineRenderers[i].startWidth = num;
				boundsLineRenderers[i].endWidth = num;
			}
			int num2 = 4;
			int num3 = 4;
			int num4 = 4;
			float num5 = Mathf.Round((center.x - selectionBounds.size.x / 2f) / snapIncrement) * snapIncrement;
			float num6 = Mathf.Round((center.x + selectionBounds.size.x / 2f) / snapIncrement) * snapIncrement;
			float num7 = Mathf.Round((center.y - selectionBounds.size.y / 2f) / snapIncrement) * snapIncrement;
			float num8 = Mathf.Round((center.y + selectionBounds.size.y / 2f) / snapIncrement) * snapIncrement;
			float num9 = Mathf.Round((center.z - selectionBounds.size.z / 2f) / snapIncrement) * snapIncrement;
			float num10 = Mathf.Round((center.z + selectionBounds.size.z / 2f) / snapIncrement) * snapIncrement;
			float num11 = Mathf.Abs(num6 - num5) + 2f * snapIncrement;
			float num12 = Mathf.Abs(num8 - num7) + 2f * snapIncrement;
			float num13 = Mathf.Abs(num10 - num9) + 2f * snapIncrement;
			float num15;
			float num14 = (num15 = 0f);
			int num16 = 0;
			float x = Mathf.Round((center.x - selectionBounds.size.x / 2f) / snapIncrement - 1f) * snapIncrement;
			for (int j = 0; j < num3; j++)
			{
				num14 = GetStartForAxisIndex("y", j, selectionBounds, center, num12, snapIncrement);
				for (int k = 0; k < num4; k++)
				{
					num15 = GetStartForAxisIndex("z", k, selectionBounds, center, num13, snapIncrement);
					Vector3 vector9 = new Vector3(x, num14, num15);
					Vector3 position = vector9 + Vector3.right * num11;
					gridLineRenderers[num16].enabled = true;
					gridLineRenderers[num16].SetPosition(0, vector9);
					gridLineRenderers[num16].SetPosition(1, position);
					num16++;
				}
			}
			num14 = Mathf.Round((center.y - selectionBounds.size.y / 2f) / snapIncrement - 1f) * snapIncrement;
			for (int l = 0; l < num2; l++)
			{
				x = GetStartForAxisIndex("x", l, selectionBounds, center, num11, snapIncrement);
				for (int m = 0; m < num4; m++)
				{
					num15 = GetStartForAxisIndex("z", m, selectionBounds, center, num13, snapIncrement);
					Vector3 vector9 = new Vector3(x, num14, num15);
					Vector3 position = vector9 + Vector3.up * num12;
					gridLineRenderers[num16].enabled = true;
					gridLineRenderers[num16].SetPosition(0, vector9);
					gridLineRenderers[num16].SetPosition(1, position);
					num16++;
				}
			}
			num15 = Mathf.Round((center.z - selectionBounds.size.z / 2f) / snapIncrement - 1f) * snapIncrement;
			for (int n = 0; n < num2; n++)
			{
				x = GetStartForAxisIndex("x", n, selectionBounds, center, num11, snapIncrement);
				for (int num17 = 0; num17 < num3; num17++)
				{
					num14 = GetStartForAxisIndex("y", num17, selectionBounds, center, num12, snapIncrement);
					Vector3 vector9 = new Vector3(x, num14, num15);
					Vector3 position = vector9 + Vector3.forward * num13;
					gridLineRenderers[num16].enabled = true;
					gridLineRenderers[num16].SetPosition(0, vector9);
					gridLineRenderers[num16].SetPosition(1, position);
					num16++;
				}
			}
			for (int num18 = 0; num18 < gridLineRenderers.Length; num18++)
			{
				gridLineRenderers[num18].startWidth = num;
				gridLineRenderers[num18].endWidth = num;
			}
		}

		private float GetStartForAxisIndex(string axis, int index, Bounds meshBounds, Vector3 meshBoundsCenter, float lineLength, float snapIncrement)
		{
			float result = 0f;
			switch (axis)
			{
			case "x":
				switch (index)
				{
				case 0:
					result = Mathf.Round((meshBoundsCenter.x - meshBounds.size.x / 2f) / snapIncrement - 1f) * snapIncrement;
					break;
				case 1:
					result = Mathf.Round((meshBoundsCenter.x - meshBounds.size.x / 2f) / snapIncrement) * snapIncrement;
					break;
				case 2:
					result = Mathf.Round((meshBoundsCenter.x + meshBounds.size.x / 2f) / snapIncrement) * snapIncrement;
					break;
				case 3:
					result = Mathf.Round((meshBoundsCenter.x + meshBounds.size.x / 2f) / snapIncrement + 1f) * snapIncrement;
					break;
				}
				break;
			case "y":
				switch (index)
				{
				case 0:
					result = Mathf.Round((meshBoundsCenter.y - meshBounds.size.y / 2f) / snapIncrement - 1f) * snapIncrement;
					break;
				case 1:
					result = Mathf.Round((meshBoundsCenter.y - meshBounds.size.y / 2f) / snapIncrement) * snapIncrement;
					break;
				case 2:
					result = Mathf.Round((meshBoundsCenter.y + meshBounds.size.y / 2f) / snapIncrement) * snapIncrement;
					break;
				case 3:
					result = Mathf.Round((meshBoundsCenter.y + meshBounds.size.y / 2f) / snapIncrement + 1f) * snapIncrement;
					break;
				}
				break;
			case "z":
				switch (index)
				{
				case 0:
					result = Mathf.Round((meshBoundsCenter.z - meshBounds.size.z / 2f) / snapIncrement - 1f) * snapIncrement;
					break;
				case 1:
					result = Mathf.Round((meshBoundsCenter.z - meshBounds.size.z / 2f) / snapIncrement) * snapIncrement;
					break;
				case 2:
					result = Mathf.Round((meshBoundsCenter.z + meshBounds.size.z / 2f) / snapIncrement) * snapIncrement;
					break;
				case 3:
					result = Mathf.Round((meshBoundsCenter.z + meshBounds.size.z / 2f) / snapIncrement + 1f) * snapIncrement;
					break;
				}
				break;
			}
			return result;
		}
	}
}
