		public override bool CanBeSplit => false;

		public override PhysicsMode DefaultPhysicsMode
		{
			[CompilerGenerated]
			get
			{
				return PhysicsMode.Trigger;
			}
		}

		protected override RepositionWhenAddingFirstShape ShouldRepositionWhenAddingFirstShape
		{
			[CompilerGenerated]
			get
			{
				return RepositionWhenAddingFirstShape.Once;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			triggerVolumeNode = GetComponent<TriggerVolumeInputNodeDisplay>();
			_currentTriggerMode = new SynchronizedField<int>(this, "TV_CM", 0, SetterPermissionMode.ANYONE, OnCurrentTriggerModeChanged);
			_filterTags = new SynchronizedField<string[]>(this, "TV_FT", new string[0], SetterPermissionMode.ANYONE, OnFilterTagsChanged);
			PlayerLocomotion.LocalPlayerStartedTeleportEvent += OnLocalPlayerStartedTeleport;
			PlayerLocomotion.PlayerTeleportedEvent += OnPlayerTeleported;
			CircuitManager.PreEvaluateEvent += ResolveCircuits;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PlayerLocomotion.LocalPlayerStartedTeleportEvent -= OnLocalPlayerStartedTeleport;
			PlayerLocomotion.PlayerTeleportedEvent -= OnPlayerTeleported;
			CircuitManager.PreEvaluateEvent -= ResolveCircuits;
		}

		protected override void Start()
		{
			base.Start();
			Dictionary<string, EnumChoiceData> dictionary = new Dictionary<string, EnumChoiceData>();
			dictionary.Add("Players", new EnumChoiceData
			{
				enumValue = 0
			});
			dictionary.Add("Objects", new EnumChoiceData
			{
				enumValue = 1
			});
			Dictionary<string, EnumChoiceData> choicesDictionary = dictionary;
			EnumSettingEditEvent settingEvent = new EnumSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => editableUIFlow.DefaultEnumUIControlPrefab, delegate(CreationObjectSettingFriendlyIntControl instance)
			{
				instance.PropertyDescription.text = "Keeps Track Of";
				instance.PropertyGetter = CurrentMode_Get;
				instance.PropertySetter = CurrentMode_Set;
			}, choicesDictionary);
			StringSettingEditEvent settingEvent2 = new StringSettingEditEvent((MakerPenPaletteConfigScreen editableUIFlow) => tagEditPrefab, delegate(CreationObjectSettingStringUIControl instance)
			{
				instance.PropertyDescription.text = "Filter By";
				instance.PropertyGetter = FilterTags_Get;
				instance.PropertySetter = FilterTags_Set;
				instance.SetDialogOptions("Filter By Tag", "Only detect objects with tag...", TMP_InputField.ContentType.Alphanumeric, purifyString: true, 25);
				instance.UpdateControlFunction = delegate(CreationObjectSettingStringUIControl ui)
				{
					ui.PropertyValueText.text = FilterTags_Get();
				};
			});
			base.CreationObject.AddConfigurableSetting(settingEvent);
			base.CreationObject.AddConfigurableSetting(settingEvent2);
			OnCurrentTriggerModeChanged();
			OnFilterTagsChanged();
		}

		public void CurrentMode_Set(int newValue)
		{
			if (base.hasAuthority)
			{
				CurrentMode = (Mode)newValue;
			}
		}

		public int CurrentMode_Get()
		{
			return (int)CurrentMode;
		}

		public void FilterTags_Set(string tagName)
		{
			FilterTags = new string[1] { ToolTagManager.FormatTag(tagName) };
		}

		public string FilterTags_Get()
		{
			string result = string.Empty;
			if (FilterTags.Length > 0)
			{
				result = FilterTags[0];
			}
			return result;
		}

		private void OnCurrentTriggerModeChanged()
		{
			Color color = ((CurrentMode != Mode.Player) ? toolModeColor : playerModeColor);
			MaterialPropertyBlock materialPropertyBlock = new MaterialPropertyBlock();
			foreach (Shape allShape in shapeArray.AllShapes)
			{
				allShape.MeshRenderer.GetPropertyBlock(materialPropertyBlock);
				materialPropertyBlock.SetColor(ShaderIDs.MAIN_COLOR, color);
				allShape.MeshRenderer.SetPropertyBlock(materialPropertyBlock);
			}
			batchedMeshRenderer.SetMaterialProperty(ShaderIDs.MAIN_COLOR, color);
		}

		private void OnFilterTagsChanged()
		{
			tooltip.Message = defaultFilterTooltip;
			if (FilterTags.Length > 0 && !string.IsNullOrEmpty(FilterTags[0]))
			{
				tooltip.Message = "#" + string.Join(", #", FilterTags);
			}
		}

		protected override void OnShapesChanged()
		{
			base.OnShapesChanged();
			CenterNonShapeObjects();
		}

		private void CenterNonShapeObjects()
		{
			if (shapeArray.ShapeCount > 0)
			{
				Shape shapeByIndex = shapeArray.GetShapeByIndex(0);
				if (shapeByIndex != null)
				{
					circuitOutputs.transform.position = shapeByIndex.Transform.TransformPoint(0f, 0.5f, 0.5f);
				}
			}
		}

		private void ToolEnter(Tool tool)
		{
			if (IsTrackedWithFilters(tool))
			{
				toolsToResolve.Add(tool);
				int value = toolEnters.GetOrCreate(tool) + 1;
				toolEnters[tool] = value;
			}
		}

		private void ToolExit(Tool tool)
		{
			if (IsTrackedWithFilters(tool))
			{
				toolsToResolve.Add(tool);
				int value = toolExits.GetOrCreate(tool) + 1;
				toolExits[tool] = value;
			}
		}

		private void PlayerEnter(PhotonPlayer player)
		{
			playersToResolve.Add(player);
			int value = playerEnters.GetOrCreate(player) + 1;
			playerEnters[player] = value;
		}

		private void PlayerExit(PhotonPlayer player)
		{
			playersToResolve.Add(player);
			int value = playerExits.GetOrCreate(player) + 1;
			playerExits[player] = value;
		}

		private void ResolveCircuits()
		{
			if (playerCollisionTracker.UpdateColliders(out releasedPlayers) && CurrentMode == Mode.Player)
			{
				for (int i = 0; i < releasedPlayers.Count; i++)
				{
					PhotonPlayer player = releasedPlayers[i];
					PlayerExit(player);
				}
			}
			if (toolCollisionTracker.UpdateColliders(out releasedTools) && CurrentMode == Mode.Tool)
			{
				for (int j = 0; j < releasedTools.Count; j++)
				{
					Tool tool = releasedTools[j];
					ToolExit(tool);
				}
			}
			ResolveCircuitSignals(triggerVolumeNode, playersToResolve, playerEnters, playerExits, QueuePlayerEnter, QueuePlayerExit);
			ResolveCircuitSignals(triggerVolumeNode, toolsToResolve, toolEnters, toolExits, QueueToolEnter, QueueToolExit);
			if (PhotonNetwork.isMasterClient)
			{
				int num = 0;
				num = ((CurrentMode != Mode.Player) ? CurrentCountWithFilters() : playerCollisionTracker.CurrentlyInsideVolumeCount);
				triggerVolumeNode.SetOutput(OutputSlot.G, num);
			}
		}

		private void EvaluatePlayerToolHolderChange(Tool tool)
		{
			Player holderPlayer = tool.HolderPlayer;
			bool flag = holderPlayer != null && holderPlayer.PhotonPlayer != null;
			List<Collider> value = null;
			if (flag)
			{
				playerCollisionTracker.TrackedColliders.TryGetValue(holderPlayer.PhotonPlayer, out value);
			}
			Player previousNonNullHolderPlayer = tool.PreviousNonNullHolderPlayer;
			bool flag2 = previousNonNullHolderPlayer != null && previousNonNullHolderPlayer.PhotonPlayer != null;
			List<Collider> value2 = new List<Collider>();
			if (flag2 && playerCollisionTracker.TrackedColliders.TryGetValue(previousNonNullHolderPlayer.PhotonPlayer, out value2))
			{
				Collider[] componentsInChildren = tool.GetComponentsInChildren<Collider>();
				foreach (Collider item in componentsInChildren)
				{
					if (value2.Remove(item) && flag && value != null && !value.Contains(item))
					{
						value.Add(item);
					}
				}
				if (flag && value != null && value.Count > 0)
				{
					playerCollisionTracker.TrackedColliders[holderPlayer.PhotonPlayer] = value;
				}
				if (value2.Count == 0)
				{
					playerCollisionTracker.RemoveTrackedColliderKey(previousNonNullHolderPlayer.PhotonPlayer);
					PlayerExit(previousNonNullHolderPlayer.PhotonPlayer);
				}
			}
			ResolveCircuits();
		}

		private static void ResolveCircuitSignals<T>(TriggerVolumeInputNodeDisplay node, HashSet<T> set, Dictionary<T, int> enters, Dictionary<T, int> exits, Action<T> queueEnter, Action<T> queueExit)
		{
			if (PhotonNetwork.isMasterClient)
			{
				foreach (T item in set)
				{
					int orCreate = enters.GetOrCreate(item);
					int num = exits.GetOrCreate(item) * -1;
					int num2 = orCreate + num;
					if (num2 == 0)
					{
						queueEnter(item);
						queueExit(item);
					}
					else if (num2 > 0)
					{
						queueEnter(item);
					}
					else
					{
						queueExit(item);
					}
				}
			}
			set.Clear();
			enters.Clear();
			exits.Clear();
		}

		private void QueuePlayerEnter(PhotonPlayer player)
		{
			int iD = player.ID;
			triggerVolumeNode.SetOutput(OutputSlot.R, iD);
		}

		private void QueuePlayerExit(PhotonPlayer player)
		{
			int iD = player.ID;
			triggerVolumeNode.SetOutput(OutputSlot.B, iD);
		}

		private void QueueToolEnter(Tool enteredTool)
		{
			int photonViewId = enteredTool.PhotonViewId;
			triggerVolumeNode.SetOutput(OutputSlot.R, photonViewId);
		}

		private void QueueToolExit(Tool exitedTool)
		{
			int photonViewId = exitedTool.PhotonViewId;
			triggerVolumeNode.SetOutput(OutputSlot.B, photonViewId);
		}

		private void OnLocalPlayerStartedTeleport()
		{
			inZoneAtStartOfTeleport = playerCollisionTracker.IsInZone(PhotonNetwork.player);
		}

		private void OnPlayerTeleported(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
		{
			if (!player.isLocal || CurrentMode != Mode.Player || inZoneAtStartOfTeleport || playerCollisionTracker.IsInZone(PhotonNetwork.player))
			{
				return;
			}
			Vector3 point = sourceGroundPosition + Vector3.up * playerCapsuleHeight;
			Vector3 vector = destinationGroundPosition - sourceGroundPosition;
			float magnitude = vector.magnitude;
			Vector3 direction = vector / magnitude;
			foreach (Shape allShape in shapeArray.AllShapes)
			{
				foreach (Collider physicsCollider in allShape.ToolCollider.PhysicsColliders)
				{
					if (physicsCollider.CapsuleCast(sourceGroundPosition, point, playerCapsuleRadius, direction, magnitude, out var _))
					{
						base.photonView.RpcMaster(FireEnterExitEvents);
						return;
					}
				}
			}
		}

		[PunRPC]
		private void FireEnterExitEvents(PhotonMessageInfo photonMessageInfo)
		{
			if (CurrentMode == Mode.Player)
			{
				PlayerEnter(photonMessageInfo.sender);
				PlayerExit(photonMessageInfo.sender);
				int currentlyInsideVolumeCount = playerCollisionTracker.CurrentlyInsideVolumeCount;
				triggerVolumeNode.SetOutput(OutputSlot.G, currentlyInsideVolumeCount);
			}
		}

		private void OnTriggerEnter(Collider otherCollider)
		{
			if (ignoredColliders.Contains(otherCollider))
			{
				return;
			}
			if (playerCollisionTracker.OnColliderEntered(otherCollider, out var entered) && CurrentMode == Mode.Player)
			{
				PlayerEnter(entered);
			}
			if (toolCollisionTracker.OnColliderEntered(otherCollider, out var entered2))
			{
				if (CurrentMode == Mode.Tool)
				{
					ToolEnter(entered2);
				}
				entered2.HolderChangedEvent -= EvaluatePlayerToolHolderChange;
				entered2.HolderChangedEvent += EvaluatePlayerToolHolderChange;
			}
		}

		private void OnTriggerExit(Collider otherCollider)
		{
			if (ignoredColliders.Contains(otherCollider))
			{
				return;
			}
			if (playerCollisionTracker.OnColliderExited(otherCollider, out var exited) && CurrentMode == Mode.Player)
			{
				PlayerExit(exited);
			}
			if (toolCollisionTracker.OnColliderExited(otherCollider, out var exited2))
			{
				exited2.HolderChangedEvent -= EvaluatePlayerToolHolderChange;
				if (CurrentMode == Mode.Tool)
				{
					ToolExit(exited2);
				}
			}
		}

		public int CurrentCountWithFilters()
		{
			if (FilterTags.Length == 0 || string.IsNullOrEmpty(FilterTags[0]))
			{
				return toolCollisionTracker.CurrentlyInsideVolumeCount;
			}
			int num = 0;
			foreach (KeyValuePair<Tool, List<Collider>> trackedCollider in toolCollisionTracker.TrackedColliders)
			{
				if (IsTrackedWithFilters(trackedCollider.Key))
				{
					num++;
				}
			}
			return num;
		}

		public bool IsTrackedWithFilters(Tool colliderKey)
		{
			string[] filterTags = FilterTags;
			foreach (string text in filterTags)
			{
				if (colliderKey.Tags != null && colliderKey.Tags.HasTag(text))
				{
					return true;
				}
			}
			return FilterTags.Length == 0 || string.IsNullOrEmpty(FilterTags[0]);
		}

		public override void DeserializeFrom(PersistableDeserializeParams deserializeParams)
		{
			PersistenceViewData viewData = deserializeParams.viewData;
			bool modifiedShapes = false;
			if (viewData != null && viewData.TriggerVolumeData != null)
			{
				VerifyLegacyShapeData(deserializeParams.version, ref viewData, out modifiedShapes);
				CurrentMode = (Mode)viewData.TriggerVolumeData.ModeId;
				if (viewData.TriggerVolumeData.FilterTags != null)
				{
					FilterTags = new string[viewData.TriggerVolumeData.FilterTags.Tags.Count];
					viewData.TriggerVolumeData.FilterTags.Tags.CopyTo(FilterTags, 0);
				}
			}
			base.DeserializeFrom(deserializeParams);
			if (modifiedShapes)
			{
				base.ShapesUnchangedFromRoomData = false;
			}
		}

		private void VerifyLegacyShapeData(RoomPersistenceVersion version, ref PersistenceViewData viewData, out bool modifiedShapes)
		{
			if (version >= RoomPersistenceVersion.CREATION_OBJECT_ADDED)
			{
				modifiedShapes = false;
				return;
			}
			viewData.ShapeContainerData = new ShapeContainerData();
			viewData.ShapeContainerData.PhysicsMode = (int)DefaultPhysicsMode;
			ShapeDataCollection shapeDataCollection = new ShapeDataCollection();
			viewData.ShapeContainerData.ShapeCollection = shapeDataCollection;
			ShapeData shapeData = new ShapeData();
			shapeData.Id = RecRoom.Protobuf.ByteStringExtensions.ToByteString(Guid.NewGuid());
			shapeData.ShapeType = 7;
			shapeData.CurrentLocalPosition = viewData.TriggerVolumeData.DEPRECATEDPosition;
			shapeData.CurrentLocalRotation = Quaternion.identity.ToVector3Data();
			shapeData.DEPRECATEDScaleNonUniform = viewData.TriggerVolumeData.DEPRECATEDScale;
			shapeData.MeshShapeData = new MeshShapeData();
			shapeDataCollection.Shapes.Add(shapeData);
			modifiedShapes = true;
		}

		public override void SerializeTo(ref PersistenceViewData viewData, ref TransientDataToPersist transientData, StringBuilder outputLog)
		{
			base.SerializeTo(ref viewData, ref transientData, outputLog);
			if (viewData.TriggerVolumeData == null)
			{
				viewData.TriggerVolumeData = new TriggerVolumeData();
			}
			viewData.TriggerVolumeData.ModeId = (int)CurrentMode;
			viewData.TriggerVolumeData.FilterTags = new TagData();
			viewData.TriggerVolumeData.FilterTags.Tags.AddRange(FilterTags);
		}

		void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
		{
			GameObject shapePrefab = ShapeSettings.GetShapePrefab(ShapeType.TriggerVolumeBox);
			UnityEngine.Object.Instantiate(shapePrefab, base.transform);
		}
	}
}
namespace RecRoom
{
	public abstract class TriggerCollisionTracker<T> where T : class
	{
		private struct ColliderToRemove
		{
			public T Key;

			public Collider Collider;
		}

		private HashSet<Collider> allColliders = new HashSet<Collider>();

		public Dictionary<T, List<Collider>> TrackedColliders = new Dictionary<T, List<Collider>>();

		private List<ColliderToRemove> toRemove = new List<ColliderToRemove>();

		protected bool detectTriggers = true;

		public int CurrentlyInsideVolumeCount => TrackedColliders.Count;

		public bool OnColliderEntered(Collider addedCollider, out T entered)
		{
			entered = (T)null;
			if (!detectTriggers && addedCollider.isTrigger)
			{
				return false;
			}
			allColliders.Add(addedCollider);
			bool result = false;
			if (GetTrackedColliderKey(addedCollider, out entered))
			{
				if (!TrackedColliders.TryGetValue(entered, out var value))
				{
					value = new List<Collider>();
					result = true;
				}
				if (!value.Contains(addedCollider))
				{
					value.Add(addedCollider);
				}
				TrackedColliders[entered] = value;
			}
			return result;
		}

		public bool OnColliderDestroyed(T key, Collider destroyedCollider, out T exited)
		{
			return OnColliderExited(key, destroyedCollider, out exited);
		}

		public bool OnColliderExited(Collider removedCollider, out T exited)
		{
			if (GetTrackedColliderKey(removedCollider, out exited))
			{
				return OnColliderExited(exited, removedCollider, out exited);
			}
			return false;
		}

		private bool OnColliderExited(T key, Collider removedCollider, out T exited)
		{
			allColliders.Remove(removedCollider);
			bool result = false;
			exited = key;
			if (key != null)
			{
				if (TrackedColliders.ContainsKey(key))
				{
					List<Collider> list = TrackedColliders[key];
					list.Remove(removedCollider);
					if (list.Count == 0)
					{
						result = RemoveTrackedColliderKey(key);
					}
					else
					{
						TrackedColliders[key] = list;
					}
				}
			}
			else
			{
				UnityEngine.Debug.LogError("TriggerVolumeCollisionTracker.OnColliderExited key is null -eric");
			}
			return result;
		}

		public bool UpdateColliders(out List<T> stoppedPressing)
		{
			stoppedPressing = new List<T>();
			if (TrackedColliders.Count == 0)
			{
				return false;
			}
			toRemove.Clear();
			foreach (KeyValuePair<T, List<Collider>> trackedCollider in TrackedColliders)
			{
				List<Collider> value = trackedCollider.Value;
				for (int i = 0; i < value.Count; i++)
				{
					if (value[i] == null || !value[i].enabled || !value[i].gameObject.activeInHierarchy)
					{
						ColliderToRemove item = new ColliderToRemove
						{
							Key = trackedCollider.Key,
							Collider = value[i]
						};
						toRemove.Add(item);
					}
				}
			}
			for (int j = 0; j < toRemove.Count; j++)
			{
				if (OnColliderDestroyed(toRemove[j].Key, toRemove[j].Collider, out var exited))
				{
					stoppedPressing.Add(exited);
				}
			}
			return stoppedPressing.Count > 0;
		}

		public virtual bool RemoveTrackedColliderKey(T key)
		{
			return TrackedColliders.Remove(key);
		}

		public bool IsInZone(T key)
		{
			return TrackedColliders.ContainsKey(key);
		}

		protected abstract bool GetTrackedColliderKey(Collider collider, out T collisionKey);
	}
	public class PlayerTriggerVolumeCollisionTracker : TriggerCollisionTracker<PhotonPlayer>
	{
		protected override bool GetTrackedColliderKey(Collider collider, out PhotonPlayer collisionKey)
		{
			Player.BodyPart bodyPart = Player.BodyPart.None;
			collisionKey = null;
			Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null && bodyPart != Player.BodyPart.None)
			{
				collisionKey = colliderPlayer.PhotonPlayer;
				return true;
			}
			Tool colliderTool = collider.GetColliderTool();
			if (colliderTool != null && colliderTool.PlayerSpawnedEquipment == null && colliderTool.IsHeldByPlayer)
			{
				collisionKey = colliderTool.HolderPlayer.PhotonPlayer;
			}
			return collisionKey != null;
		}
	}
	public class ToolTriggerVolumeCollisionTracker : TriggerCollisionTracker<Tool>
	{
		protected override bool GetTrackedColliderKey(Collider collider, out Tool collisionKey)
		{
			collisionKey = collider.GetColliderTool();
			if (collisionKey?.ExcludeFromTriggerVolume == true)
			{
				collisionKey = null;
			}
			else if (collisionKey?.IsSubTool == true)
			{
				collisionKey = collisionKey.ParentTool;
			}
			return collisionKey != null;
		}
	}
	public class PlayerButtonCollisionTracker : TriggerCollisionTracker<PhotonPlayer>
	{
		private readonly bool canOnlyPushLocally;

		private readonly bool canPushWithTools;

		private readonly bool pushingToolsMustBeHeld;

		public PlayerButtonCollisionTracker(bool canOnlyPushLocally, bool canPushWithTools, bool pushingToolsMustBeHeld)
		{
			detectTriggers = false;
			this.canOnlyPushLocally = canOnlyPushLocally;
			this.canPushWithTools = canPushWithTools;
			this.pushingToolsMustBeHeld = pushingToolsMustBeHeld;
		}

		protected override bool GetTrackedColliderKey(Collider collider, out PhotonPlayer collisionKey)
		{
			collisionKey = null;
			Player.BodyPart bodyPart;
			Player colliderPlayer = collider.GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null)
			{
				collisionKey = collider.GetColliderPlayer(out bodyPart).PhotonPlayer;
			}
			Tool tool = null;
			if (collisionKey == null && canPushWithTools)
			{
				tool = collider.GetColliderTool();
				if (tool != null && !tool.ExcludeFromTriggerVolume)
				{
					if (tool.IsHeldByPlayer)
					{
						collisionKey = tool.HolderPlayer.PhotonPlayer;
						bodyPart = ((!(tool.HolderHand != null)) ? Player.BodyPart.None : tool.HolderHand.BodyPart);
					}
					else if (!pushingToolsMustBeHeld && tool.Owner != null)
					{
						collisionKey = tool.Owner.PhotonPlayer;
						bodyPart = Player.BodyPart.None;
					}
				}
			}
			if (collisionKey == null)
			{
				collisionKey = GetFakePlayerOverride(collider, out bodyPart);
			}
			return collisionKey != null && (!canOnlyPushLocally || collisionKey.IsLocal) && (bodyPart.IsHand() || (canPushWithTools && tool != null));
		}

		private PhotonPlayer GetFakePlayerOverride(Collider collider, out Player.BodyPart bodyPart)
		{
			FakePlayerCollider component = collider.GetComponent<FakePlayerCollider>();
			if (component == null)
			{
				bodyPart = Player.BodyPart.None;
				return null;
			}
			bodyPart = component.BodyPart;
			return PhotonNetwork.player;
		}
	}
}
