	private UnityEngine.UI.Button startRecordingButton;

	[SerializeField]
	private UnityEngine.UI.Button stopRecordingButton;

	[SerializeField]
	private UnityEngine.UI.Button takeScreenShotButton;

	private Tool tool;

	private ResolutionType resolutionType = ResolutionType.None;

	private RenderTexture renderTexture;

	private Material screenRenderMaterialCopy;

	private float fullRenderScale;

	private Vector3 velocity = Vector3.zero;

	private Vector3 rotationVelocity = Vector3.zero;

	private static readonly int screenAnimationId = Animator.StringToHash("ScreenOpen");

	private bool _isStreaming;

	private bool _smoothPosition = true;

	private Coroutine startRecordingCoroutine;

	public bool IsRecording => videoCapture.IsCapturing;

	public bool IsStreaming
	{
		get
		{
			return _isStreaming;
		}
		set
		{
			_isStreaming = value;
		}
	}

	public bool SmoothPosition
	{
		get
		{
			return _smoothPosition;
		}
		set
		{
			_smoothPosition = value;
		}
	}

	private void Awake()
	{
		videoCapture.RecordingCamera = camera;
		videoCapture.CaptureStartedEvent += OnCaptureStarted;
		videoCapture.ExportStartedEvent += OnExportStarted;
		videoCapture.ExportFinishedEvent += OnExportFinished;
		if (pngCapture != null)
		{
			pngCapture.RecordingCamera = camera;
		}
		exportingFeedback.SetActive(value: false);
		recordingFeedback.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		savedFeedback.gameObject.SetActive(value: false);
		canvas.worldCamera = UIInputModule.Instance.ControllerCamera;
		tool = GetComponent<Tool>();
		if (tool != null)
		{
			tool.PostPickupEvent += OnPostPickup;
			tool.PostReleaseEvent += OnPostRelease;
			tool.GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
		}
	}

	private void OnDestroy()
	{
		if (tool != null)
		{
			tool.PostPickupEvent -= OnPostPickup;
			tool.PostReleaseEvent -= OnPostRelease;
		}
		videoCapture.CaptureStartedEvent -= OnCaptureStarted;
		videoCapture.ExportStartedEvent -= OnExportStarted;
		videoCapture.ExportFinishedEvent -= OnExportFinished;
	}

	private void Start()
	{
		screenRenderMaterialCopy = new Material(screenRenderMaterial);
		Renderer[] array = screenRenderers;
		foreach (Renderer renderer in array)
		{
			renderer.material = screenRenderMaterialCopy;
		}
		float aspect = lowResolution.x / lowResolution.y;
		camera.aspect = aspect;
		previewCamera.aspect = aspect;
		camera.gameObject.name = base.gameObject.name + "_Camera";
		camera.transform.SetParent(null, worldPositionStays: true);
		previewCamera.gameObject.name = base.gameObject.name + "_PreviewCamera";
		previewCamera.transform.SetParent(null, worldPositionStays: true);
		SwitchTextureResolution(ResolutionType.Low);
		camera.depthTextureMode = DepthTextureMode.Depth;
		previewCamera.depthTextureMode = DepthTextureMode.Depth;
		GetComponentInChildren<Animator>().SetBool(screenAnimationId, value: true);
		fovSlider.value = camera.fieldOfView;
		fovSliderLabel.text = fovSlider.value.ToString("F0");
		startRecordingButton.interactable = true;
		stopRecordingButton.interactable = false;
	}

	private void SwitchTextureResolution(ResolutionType newRresolutionType)
	{
		if (resolutionType != newRresolutionType)
		{
			resolutionType = newRresolutionType;
			Vector2 vector = lowResolution;
			switch (resolutionType)
			{
			case ResolutionType.High:
				vector = highResolution;
				break;
			case ResolutionType.Ultra:
				vector = ultraResolution;
				break;
			}
			renderTexture = new RenderTexture((int)vector.x, (int)vector.y, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			if (camera != null)
			{
				camera.targetTexture = renderTexture;
			}
			if (previewCamera != null)
			{
				previewCamera.targetTexture = renderTexture;
			}
			screenRenderMaterialCopy.mainTexture = renderTexture;
		}
	}

	private void Update()
	{
		if (SmoothPosition)
		{
			camera.transform.position = Vector3.SmoothDamp(camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
			camera.transform.rotation = UnityExtensions.SmoothDamp(camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
			previewCamera.transform.position = Vector3.SmoothDamp(camera.transform.position, lensTransform.position, ref velocity, positionSmoothingTime);
			previewCamera.transform.rotation = UnityExtensions.SmoothDamp(camera.transform.rotation, lensTransform.rotation, ref rotationVelocity, positionSmoothingTime);
		}
		else
		{
			camera.transform.position = lensTransform.position;
			camera.transform.rotation = lensTransform.rotation;
			previewCamera.transform.position = lensTransform.position;
			previewCamera.transform.rotation = lensTransform.rotation;
		}
		if (IsRecording)
		{
			float num = videoCapture.UpdateFrame(renderTexture);
			recordingProgressFeedback.value = num;
			if (num >= 1f)
			{
				FinishCapturing();
			}
		}
	}

	private void StartCapturing()
	{
		SwitchTextureResolution(ResolutionType.High);
		fullRenderScale = Mathf.Max(1f, XRSettings.eyeTextureResolutionScale);
		XRSettings.eyeTextureResolutionScale = fullRenderScale / 2f;
		if (!IsRecording)
		{
			videoCapture.StartCapture();
		}
		if (canvas != null)
		{
			takeScreenShotButton.interactable = false;
			startRecordingButton.interactable = false;
			stopRecordingButton.interactable = true;
		}
	}

	private void FinishCapturing()
	{
		if (IsRecording)
		{
			videoCapture.FinishCapture();
			videoCapture.SaveToDisk();
		}
		SwitchTextureResolution(ResolutionType.Low);
		XRSettings.eyeTextureResolutionScale = Mathf.Max(1f, fullRenderScale);
		if (canvas != null)
		{
			startRecordingButton.interactable = true;
			stopRecordingButton.interactable = false;
			takeScreenShotButton.interactable = true;
		}
	}

	public void ToggleRecording()
	{
		if (!IsRecording)
		{
			StartCapturing();
		}
		else
		{
			FinishCapturing();
		}
	}

	public void ToggleStreaming()
	{
		if (!IsStreaming)
		{
			IsStreaming = true;
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetMode(StreamingCameraController.StreamingCameraMode.ON, StreamingCameraController.InteractionSource.TutorialCam);
			CameraTransform cameraTransform = new CameraTransform();
			cameraTransform.Transform = camera.transform;
			cameraTransform.FollowsLocalPlayer = false;
			cameraTransform.PositionSmoothingTimeOverride = 0f;
			cameraTransform.RotationSmoothingTimeOverride = 0f;
			CameraTransform cameraTransform2 = cameraTransform;
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetCameraTransformToFollow(cameraTransform2, StreamingCameraController.InteractionSource.TutorialCam);
		}
		else
		{
			IsStreaming = false;
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetMode(StreamingCameraController.StreamingCameraMode.OFF, StreamingCameraController.InteractionSource.TutorialCam);
		}
	}

	public void SetPositionSmoothingTime(float t)
	{
		positionSmoothingTime = t;
	}

	private void OnRenderImage(RenderTexture src, RenderTexture dest)
	{
		Graphics.Blit(renderTexture, dest);
	}

	private void OnCaptureStarted()
	{
		recordingFeedback.gameObject.SetActive(value: true);
		recordingProgressFeedback.gameObject.SetActive(value: true);
	}

	private void OnExportStarted()
	{
		recordingFeedback.gameObject.SetActive(value: false);
		recordingProgressFeedback.gameObject.SetActive(value: false);
		exportingFeedback.SetActive(value: true);
	}

	private void OnExportFinished(string filename)
	{
		exportingFeedback.SetActive(value: false);
		StartCoroutine(DisplayFileSaveFeedbackCoroutine(filename));
	}

	private IEnumerator DisplayFileSaveFeedbackCoroutine(string filename)
	{
		filename = Path.GetFileName(filename);
		savedFeedback.gameObject.SetActive(value: true);
		savedFeedback.text = filename + " Saved!";
		yield return new WaitForSeconds(2f);
		savedFeedback.gameObject.SetActive(value: false);
	}

	private void OnPostPickup(Tool tool)
	{
		if (canvas != null)
		{
			canvas.gameObject.SetActive(value: false);
		}
	}

	private void OnPostRelease(Tool tool)
	{
		if (canvas != null)
		{
			canvas.gameObject.SetActive(value: true);
		}
	}

	[SkipRename]
	public void Slider_FOVValueChange(float value)
	{
		camera.fieldOfView = value;
		previewCamera.fieldOfView = value;
		fovSliderLabel.text = fovSlider.value.ToString("F0");
	}

	[SkipRename]
	public void Button_ToggleCameraUIMask()
	{
		int num = 32;
		bool flag = (camera.cullingMask & num) == num;
		if (flag)
		{
			camera.cullingMask &= ~num;
			previewCamera.cullingMask &= ~num;
		}
		else
		{
			camera.cullingMask |= num;
			previewCamera.cullingMask |= num;
		}
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, (!flag) ? "UI is will be recorded." : "UI will NOT be recorded!", 2f);
	}

	[SkipRename]
	public void Button_StartRecording()
	{
		startRecordingButton.interactable = false;
		stopRecordingButton.interactable = true;
		startRecordingCoroutine = StartCoroutine(RunStartRecording());
	}

	private IEnumerator RunStartRecording()
	{
		yield return new WaitForSeconds(0.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "3", 1f);
		yield return new WaitForSeconds(1.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "2", 1f);
		yield return new WaitForSeconds(1.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "1", 1f);
		yield return new WaitForSeconds(1.1f);
		if (!IsRecording)
		{
			StartCapturing();
		}
	}

	[SkipRename]
	public void Button_StopRecording()
	{
		StopCoroutine(startRecordingCoroutine);
		startRecordingCoroutine = null;
		if (IsRecording)
		{
			FinishCapturing();
		}
		startRecordingButton.interactable = true;
		stopRecordingButton.interactable = false;
	}

	[SkipRename]
	public void Button_TakeScreenShot()
	{
		takeScreenShotButton.interactable = false;
		StartCoroutine(RunTakeScreenShot());
	}

	private IEnumerator RunTakeScreenShot()
	{
		yield return new WaitForSeconds(0.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "3", 1f);
		yield return new WaitForSeconds(1.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "2", 1f);
		yield return new WaitForSeconds(1.1f);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "1", 1f);
		yield return new WaitForSeconds(1.1f);
		if (!IsRecording)
		{
			SwitchTextureResolution(ResolutionType.Ultra);
			yield return null;
			pngCapture.StartCapture();
			pngCapture.UpdateFrame(renderTexture);
			yield return null;
			SwitchTextureResolution(ResolutionType.Low);
			yield return null;
			takeScreenShotButton.interactable = true;
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Thanks!", 1f);
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "No screen shots during recordind!", 1f);
		}
	}

	[SkipRename]
	public void Button_HideUI()
	{
		canvas.gameObject.SetActive(value: false);
	}
}
namespace RecRoom.Tools
{
	[Serializable]
	[CreateAssetMenu(menuName = "RecRoom/VR Mode/VR Tool Controllers/Charades Pen VR Controller", fileName = "CharadesPenVRController")]
	public class CharadesPenVRController : VRToolController
	{
		[NonSerialized]
		private CharadesPen charadesPen;

		[SerializeField]
		private CharadesPenShapeCreationLogic shapeCreator = new CharadesPenShapeCreationLogic();

		private IPromise<ShapeContainer> cachedContainerPromise;

		private CreationContext creationContext => charadesPen.CreationContext;

		public override bool CanStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			return tool.GetComponent<CharadesPen>() != null && tool.IsHeldByPlayer && player == tool.HolderPlayer;
		}

		public override void OnStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			playerController.AddToolPickupCondition(PlayerToolPickupCondition);
			charadesPen = tool.GetComponent<CharadesPen>();
			shapeCreator.Initialize(charadesPen, charadesPen.CreationContext, charadesPen.CreationContext.ShapeCreationContext, toolInput);
			creationContext.RemoveAllFromSelection();
			RequestShapeContainerIfNotPending();
		}

		public override bool OnUpdate(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			if (!shapeCreator.IsExtruding && shapeCreator.ShouldStartCreation())
			{
				shapeCreator.StartCreatingShape(charadesPen.CurrentShapeType, charadesPen.SelectedColor, charadesPen.ActionPointerPosition);
				return tool.IsHeldByPlayer;
			}
			if (!creationContext.ShapeCreationContext.HasSelectedShapeContainer)
			{
				RequestShapeContainerIfNotPending();
			}
			else
			{
				shapeCreator.UpdateCreatingShape();
			}
			return tool.IsHeldByPlayer;
		}

		public override void OnStop(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			shapeCreator.FinalizeShape();
			creationContext.ShapeCreationContext.RemoveAllFromSelection();
			creationContext.RemoveAllFromSelection();
			charadesPen = null;
			cachedContainerPromise = null;
			playerController.RemoveToolPickupCondition(PlayerToolPickupCondition);
		}

		private bool PlayerToolPickupCondition(Tool tool, Player player, Vector3 pickupPosition, bool inPhysicalPickupRange)
		{
			CharadesPen component = tool.GetComponent<CharadesPen>();
			if (component != null && component != charadesPen)
			{
				return false;
			}
			MakerPen component2 = tool.GetComponent<MakerPen>();
			if (component2 != null)
			{
				return false;
			}
			return true;
		}

		private void RequestShapeContainerIfNotPending()
		{
			if (cachedContainerPromise == null)
			{
				cachedContainerPromise = creationContext.ShapeCreationContext.CreateAndSelectShapeContainer(SpawnableToolType.SHAPE_CONTAINER);
				cachedContainerPromise.Then(delegate(ShapeContainer container)
				{
					container.CurrentPhysicsMode = ShapeContainer.PhysicsMode.Physical_Sticky;
				}).Finally(delegate
				{
					cachedContainerPromise = null;
				});
			}
		}
	}
	[Serializable]
	public class CharadesPenShapeCreationLogic : VRShapeCreationLogic
	{
		[NonSerialized]
		public CharadesPen charadesPen;

		public void Initialize(CharadesPen pen, CreationContext context, ShapeCreationContext shapeContext, VRInputHandler input)
		{
			charadesPen = pen;
			base.Initialize(context, shapeContext, input);
		}

		protected override Vector3 CreationPosition()
		{
			return charadesPen.ActionPointerPosition;
		}

		protected override Quaternion CreationRotation()
		{
			return charadesPen.ActionPointerRotation;
		}

		protected override Transform AudioTransform()
		{
			return charadesPen.PenVisuals.ExtrusionPoint;
		}
	}
