	[CreateAssetMenu(menuName = "RecRoom/VR Mode/VR Tool Controllers/Pool Cue VR Controller", fileName = "PoolCueVRController")]
	public class PoolCueVRController : VRToolController
	{
		private PoolCue cue;

		private PoolCueAimGrip aimGrip;

		private PlayerHand shootingHand;

		private PlayerHand aimingHand;

		public override bool CanStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			return true;
		}

		public override void OnStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			shootingHand = holderHand;
			aimingHand = offHand;
			cue = tool.GetComponent<PoolCue>();
			aimGrip = cue.GetComponentInChildren<PoolCueAimGrip>();
			cue.BallHit += OnBallHit;
		}

		public override void OnStop(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			if (cue != null)
			{
				cue.BallHit -= OnBallHit;
			}
			cue = null;
			aimGrip = null;
			shootingHand = null;
			aimingHand = null;
		}

		public override bool OnUpdate(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			if (aimGrip.IsPickedUp)
			{
				switch (cue.CurrentState)
				{
				case PoolCue.State.Aiming:
					if (toolInput.HairTriggerButtonPressed)
					{
						cue.ShootingHandStartPosition = shootingHand.transform.position;
						cue.ShootingLockedPosition = cue.transform.position;
						cue.ShootingLockedRotation = cue.transform.rotation;
						cue.CurrentState = PoolCue.State.Shooting;
					}
					break;
				case PoolCue.State.Shooting:
					if (!toolInput.HairTriggerButtonPressed)
					{
						cue.CurrentState = PoolCue.State.Aiming;
					}
					break;
				}
			}
			return true;
		}

		private void OnBallHit(float force)
		{
			shootingHand.Vibrate(200, 1f * Mathf.Clamp01(force));
			aimingHand.Vibrate(20, 0.5f * Mathf.Clamp01(force));
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/VR Mode/VR Tool Controllers/Whip Gesture VR Controller", fileName = "WhipGestureVRController")]
	public class WhipGestureVRController : VRToolController
	{
		public override bool CanStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			return tool.IsHeldByPlayer && player == tool.HolderPlayer;
		}

		public override void OnStart(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			Whip component = tool.GetComponent<Whip>();
			if (component != null)
			{
				component.DisablePopperGravity = false;
			}
			toolInput.TransformUpdateEvent += OnHolderHandTrackerUpdated;
		}

		public override bool OnUpdate(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			return tool.IsHeldByPlayer;
		}

		public override void OnStop(VRPlayerController playerController, Player player, Tool tool, PlayerHand holderHand, PlayerHand offHand, VRInputHandler toolInput, VRInputHandler offHandInput)
		{
			if (toolInput != null)
			{
				toolInput.TransformUpdateEvent -= OnHolderHandTrackerUpdated;
			}
		}

		private void OnHolderHandTrackerUpdated(VRInputHandler inputHandler)
		{
			PlayerHand playerHand = ((inputHandler.HandType != VRTrackedController.HandType.LeftHand) ? Player.LocalPlayer.RightHand : Player.LocalPlayer.LeftHand);
			if (!playerHand.IsHoldingTool)
			{
				inputHandler.TransformUpdateEvent -= OnHolderHandTrackerUpdated;
				return;
			}
			Whip component = playerHand.HeldTool.GetComponent<Whip>();
			if (component == null)
			{
				inputHandler.TransformUpdateEvent -= OnHolderHandTrackerUpdated;
				return;
			}
			component.Tool.HolderHand.RigidbodyEx.GetWorldKinematicVelocitiesAtWorldSpacePoint(component.PopperPrimedPosition, (float)inputHandler.VelocityRollbackStartFrame * UnityEngine.Time.fixedDeltaTime, (float)inputHandler.VelocityRollbackEndFrame * UnityEngine.Time.fixedDeltaTime, inputHandler.LinearVelocityAverageMethod, inputHandler.AngularVelocityAverageMethod, out var linearVelocity, out var _);
			if (inputHandler.ThrowDirectionFollowsHeldTool)
			{
				linearVelocity = linearVelocity.magnitude * component.Tool.RigidbodyEx.velocity.normalized;
			}
			component?.UpdateWhippingGesture(linearVelocity);
		}
	}
}
public class AdjustWeaponForQualitySetting : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct WeaponSettings
	{
		public RecRoomQualitySetting QualitySetting;

		public ImpactDecal ImpactDecalOverride;

		public PooledParticle ImpactParticleOverride;
	}

	[SerializeField]
	private WeaponSettings[] overrideSettings;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Weapon weapon;

	private WeaponSettings defaultSettings;

	private void Start()
	{
		defaultSettings.ImpactDecalOverride = weapon.ImpactDecal;
		defaultSettings.ImpactParticleOverride = weapon.ImpactParticles;
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null && RecroomPrefs.IsReady)
		{
			ApplyQualitySetting();
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
			base.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
		}
	}

	private void OnQualitySettingChanged(RecRoomQualitySetting setting)
	{
		ApplyQualitySetting();
	}

	private void ApplyQualitySetting()
	{
		RecRoomQualitySetting qualitySetting = SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting;
		bool flag = false;
		if (overrideSettings != null)
		{
			for (int i = 0; i < overrideSettings.Length; i++)
			{
				if (overrideSettings[i].QualitySetting == qualitySetting)
				{
					weapon.ImpactDecal = overrideSettings[i].ImpactDecalOverride;
					weapon.ImpactParticles = overrideSettings[i].ImpactParticleOverride;
					flag = true;
					break;
				}
			}
		}
		if (!flag)
		{
			weapon.ImpactDecal = defaultSettings.ImpactDecalOverride;
			weapon.ImpactParticles = defaultSettings.ImpactParticleOverride;
		}
	}
