		public virtual void Fire(Vector3 position, Quaternion rotation, Vector3 initialVelocity, float impactForce, float chargeAmount, List<Rigidbody> ignoredRigidbodies, WeaponRaycastCollider.CollisionFilter collisionFilter, float maxLifetime, byte bulletId, bool overrideAndDisableGravity = false)
