				this.EndOfFrameRoutine(EnableParticles);
			}
			if (audioLoop != null && audioLoop.audioClip != null)
			{
				loopingAudioSource = AudioManager.StartLooping3DSFX(audioLoop, base.transform);
			}
			if (legacyAnimator != null && triggerMapping != null)
			{
				string animationForTrigger = triggerMapping.GetAnimationForTrigger(ANIMATION_FIRE_ID);
				legacyAnimator.Play(animationForTrigger);
			}
			else if (animator != null)
			{
				animator.SetTrigger(ANIMATION_FIRE_ID);
			}
		}

