				{
					InstancedShaderPropertyDescriptor instancedShaderPropertyDescriptor = new InstancedShaderPropertyDescriptor
					{
						Type = InstancedShaderPropertyType.COLOR,
						ShaderPropertyId = dynamicColorShaderPropertyId
					};
					instancedRenderer = BulletInstanceRenderer.Instance.Register(visualRenderer, instancedShaderPropertyDescriptor);
				}
				else
				{
					instancedRenderer = BulletInstanceRenderer.Instance.Register(visualRenderer);
				}
				if (instancedRenderer == null)
				{
