		private void Update()
		{
			if (supportsDynamicColor)
			{
				Color color = dynamicColor;
				if (supportsDynamicColorDistanceFading && SingletonMonoBehaviour<CameraRig>.Instance != null)
				{
					float sqrMagnitude = (base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.transform.position).sqrMagnitude;
					float t = Mathf.InverseLerp(minFadeDistanceFromCamera * minFadeDistanceFromCamera, maxFadeDistanceFromCamera * maxFadeDistanceFromCamera, sqrMagnitude);
					color.a = Mathf.SmoothStep(minFadeDistanceAlpha, maxFadeDistanceAlpha, t);
				}
				ApplyColor(dynamicColorShaderPropertyId, color);
			}
		}

		protected virtual void FixedUpdate()
		{
			float num = UnityEngine.Time.fixedTime - fireTime;
			if (num >= lifetime)
			{
				Release(base.transform.position);
				return;
