			Vector3 colliderOrigin = ColliderOrigin;
			base.transform.position += velocity * UnityEngine.Time.fixedDeltaTime;
			bool flag = false;
			if (selfDestructDistance > 0f && SqrDistanceTraveled > selfDestructDistance * selfDestructDistance)
			{
				base.transform.position = origin + Vector3.Normalize(base.transform.position - origin) * selfDestructDistance;
			}
			base.transform.LookAt(base.transform.position + velocity);
