		public virtual void Release(Vector3 finalPosition)
		{
			base.transform.position = finalPosition;
			base.enabled = false;
			HitPlayer = null;
			HitEnemy = null;
			BulletGroup = null;
			if (loopingAudioSource != null)
			{
				AudioManager.StopLoopingSFX(loopingAudioSource);
			}
			if (base.gameObject.activeSelf)
			{
				RaiseDestroyedEvent();
				StartCoroutine(WaitForFinishCoroutine(finalPosition));
			}
			else
			{
				CompleteRelease();
			}
		}

		private IEnumerator WaitForFinishCoroutine(Vector3 finalPosition)
		{
			float stretchDistanceOnFinish = StretchDistance;
			float stretchFinishDuration = 0f;
			if (supportsVisualStretching)
			{
				stretchFinishDuration = ((!calculateStretchFinishTime) ? explicitStretchFinishTime : (StretchDistance / velocity.magnitude));
			}
			float stretchDistanceOnImpact = StretchDistance;
			float timer = 0f;
			while (timer < stretchFinishDuration || (trail != null && trail.Running))
			{
				yield return null;
				timer += UnityEngine.Time.deltaTime;
				if (supportsVisualStretching && stretchDistanceOnImpact > 0f)
				{
					float t = Mathf.InverseLerp(0f, stretchFinishDuration, timer);
					StretchDistance = Mathf.Lerp(stretchDistanceOnFinish, 0f, t);
					if (supportsAnimatedDynamicColorBlending)
					{
						float num = StretchDistance / stretchDistanceOnImpact;
						Color color = Color.Lerp(dynamicColor, animatedDynamicColorBlendingTargetColor, 1f - num);
						ApplyColor(dynamicColorShaderPropertyId, color);
					}
				}
			}
			CompleteRelease();
		}

		protected void CompleteRelease()
		{
			if (trail != null)
			{
				trail.enabled = false;
			}
			if (particles != null)
			{
				particles.Clear();
				ParticleSystem.EmissionModule emission = particles.emission;
				emission.enabled = false;
			}
			if (supportsVisualStretching)
			{
				StretchDistance = 0f;
			}
			if (supportsInstancedRendering)
			{
				BulletInstanceRenderer.Instance.DisableInstancedRenderer(instancedRenderer);
			}
			ObjectPool.Instance.Release(this);
		}

		protected void RaiseDestroyedEvent()
		{
			if (this.DestroyEvent != null)
			{
				this.DestroyEvent(this);
			}
		}

		private bool RetryCastCollisionOnInitialOverlap(Vector3 initialOverlapPosition, out WeaponRaycastHit hit)
		{
			Vector3 previousPosition = RollbackPosition(initialOverlapPosition, 2);
			return raycastCollider.RunMovingCollision(previousPosition, initialOverlapPosition, Radius, 362036736, ignoredRigidbodies, collisionFilter, out hit) && hit.Distance != 0f;
		}

		private Vector3 RollbackPosition(Vector3 currentPosition, int rollbackFrames)
		{
			float num = (float)rollbackFrames * UnityEngine.Time.fixedDeltaTime;
			Vector3 vector = ((!IsGravityApplied) ? Vector3.zero : (-Physics.gravity * gravityRatio));
			Vector3 vector2 = -velocity;
			Vector3 vector3 = vector2 * num + 0.5f * vector * num * num;
			return currentPosition + vector3;
		}

		protected virtual void OnRaycastCollisionEnter(WeaponRaycastHit raycastCollision)
