				Vector3 normalized = velocity.normalized;
				Vector3 vector2 = Vector3.Reflect(normalized, impact.SurfaceNormal);
				base.transform.position = impact.Point + impact.SurfaceNormal * 1.1f * Radius;
				velocity = vector2 * num2;
				return;
			}
			bool flag = hitGameObject.IsInLayerMask(destroyOnLayers);
			switch (hitType)
			{
			case HitType.Player:
				OnPlayerHit(HitPlayer, bodyPart, impact);
				break;
			case HitType.Enemy:
				OnEnemyHit(HitEnemy, hitEnemyArmorType, impact);
				break;
			case HitType.Tool:
				OnToolHit(tool, impact);
				break;
			case HitType.Trap:
				OnTrapHit(trap, impact);
				break;
			default:
				OnOtherHit(impact);
				break;
			}
			if (flag)
			{
				Vector3 point = raycastCollision.Point;
				if (visualRenderer != null)
				{
					point -= velocity.normalized * Radius;
				}
				Release(point);
			}
		}

		private bool CollisionIsIgnored(WeaponRaycastHit hit)
		{
			float num = UnityEngine.Time.fixedTime - fireTime;
			return num < ignoreStaticCollisionsDuration && hit.Collider.gameObject.IsInLayerMask(LayerMasks.StaticPhysics);
		}

		public void SetBulletGroup(BulletGroup group)
		{
			if (BulletGroup == null)
			{
				BulletGroup = group;
			}
			else
			{
				UnityEngine.Debug.LogError("Cannot set the bullet group multiple times for the same bullet.");
			}
		}

		private void OnPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (ValidateHitWithGroup(hitPlayer.gameObject) && this.PlayerImpactEvent != null)
			{
				this.PlayerImpactEvent(this, hitPlayer, hitBodyPart, impact);
			}
		}

		private void OnEnemyHit(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact)
		{
			if (ValidateHitWithGroup(hitEnemy.gameObject) && this.EnemyImpactEvent != null)
			{
				this.EnemyImpactEvent(this, hitEnemy, hitEnemyArmorType, impact);
			}
		}

		private void OnToolHit(Tool tool, WeaponImpact impact)
		{
			if (ValidateHitWithGroup(tool.gameObject) && this.ToolImpactEvent != null)
			{
				this.ToolImpactEvent(this, tool, impact);
			}
		}

		private void OnTrapHit(Trap trap, WeaponImpact impact)
		{
			if (ValidateHitWithGroup(trap.gameObject) && this.TrapImpactEvent != null)
			{
				this.TrapImpactEvent(this, trap, impact);
			}
		}

		private void OnOtherHit(WeaponImpact impact)
		{
			if (ValidateHitWithGroup(impact.GameObject) && this.OtherImpactEvent != null)
			{
				this.OtherImpactEvent(this, impact);
			}
		}

		private bool ValidateHitWithGroup(GameObject hitObject)
		{
			if (BulletGroup != null)
			{
				if (BulletGroup.HasHitTarget(hitObject) && BulletGroup.LimitOneImpactPerTarget)
				{
					return false;
				}
				BulletGroup.AddHitTarget(hitObject);
			}
			return true;
		}

		private bool InstancedRenderingSupported()
		{
			if (!enableInstancedVisualRendering)
			{
				return false;
			}
			if (visualRenderer == null || visualRenderer.sharedMaterials.Length > 1 || !visualRenderer.sharedMaterial.enableInstancing)
			{
				return false;
			}
			if (!SystemInfo.supportsInstancing)
			{
				return false;
			}
			return true;
		}

		private void ApplyColor(int colorId, Color color)
		{
			if (supportsInstancedRendering)
			{
				instancedRenderer.Color = color;
			}
			else if (visualRenderer != null)
			{
				if (materialProperties == null)
				{
					materialProperties = new MaterialPropertyBlock();
				}
				materialProperties.SetColor(colorId, color);
				visualRenderer.SetPropertyBlock(materialProperties);
			}
		}

		private void OnDrawGizmos()
		{
			Gizmos.color = Color.green;
			Gizmos.DrawWireSphere(ColliderOrigin, colliderRadius);
			Gizmos.color = Color.white;
			Gizmos.DrawWireSphere(ColliderOrigin, Radius);
		}
	}
	public class BulletGroup
	{
		public delegate void BulletGroupAction(BulletGroup group);

		private readonly List<Bullet> livingBullets;

		private readonly List<GameObject> hitTargets = new List<GameObject>();

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private BulletGroupAction m_DeactivatedEvent;

		private bool _isActive;

		public int LivingBulletCount => livingBullets.Count;

		public IEnumerable<Bullet> Bullets => livingBullets;

		public bool IsActive
		{
			get
			{
				return _isActive;
			}
			private set
			{
				if (_isActive != value)
				{
					_isActive = value;
					if (_isActive)
					{
						AllocatedTime = UnityEngine.Time.time;
						hitTargets.Clear();
					}
					else if (this.DeactivatedEvent != null)
					{
						this.DeactivatedEvent(this);
					}
				}
			}
		}

		public float AllocatedTime { get; private set; }

		public bool LimitOneImpactPerTarget { get; private set; }

		public event BulletGroupAction DeactivatedEvent
		{
			add
			{
				BulletGroupAction bulletGroupAction = this.m_DeactivatedEvent;
				BulletGroupAction bulletGroupAction2;
				do
				{
					bulletGroupAction2 = bulletGroupAction;
					bulletGroupAction = Interlocked.CompareExchange(ref this.m_DeactivatedEvent, (BulletGroupAction)Delegate.Combine(bulletGroupAction2, value), bulletGroupAction);
				}
				while (bulletGroupAction != bulletGroupAction2);
			}
			remove
			{
				BulletGroupAction bulletGroupAction = this.m_DeactivatedEvent;
				BulletGroupAction bulletGroupAction2;
				do
				{
					bulletGroupAction2 = bulletGroupAction;
					bulletGroupAction = Interlocked.CompareExchange(ref this.m_DeactivatedEvent, (BulletGroupAction)Delegate.Remove(bulletGroupAction2, value), bulletGroupAction);
				}
				while (bulletGroupAction != bulletGroupAction2);
			}
		}

		public BulletGroup(int capacity, bool limitOneImpactPerTarget)
		{
			livingBullets = new List<Bullet>(capacity);
			LimitOneImpactPerTarget = limitOneImpactPerTarget;
		}

		public void Add(Bullet bullet)
		{
			if (bullet.enabled)
			{
				livingBullets.Add(bullet);
				bullet.SetBulletGroup(this);
				bullet.DestroyEvent += OnBulletDestroyed;
				IsActive = true;
			}
		}

		public void Remove(Bullet bullet)
		{
			bullet.DestroyEvent -= OnBulletDestroyed;
			livingBullets.Remove(bullet);
			if (livingBullets.Count == 0)
			{
				IsActive = false;
			}
		}

		public void AddHitTarget(GameObject target)
		{
			if (!hitTargets.Contains(target))
			{
				hitTargets.Add(target);
			}
		}

		public bool HasHitTarget(GameObject target)
		{
			return hitTargets.Contains(target);
		}

		public bool Contains(Bullet bullet)
		{
			return livingBullets.Contains(bullet);
		}

		public void DestroyAllBullets()
		{
			foreach (Bullet livingBullet in livingBullets)
			{
				if (livingBullet.enabled)
				{
					livingBullet.DestroyEvent -= OnBulletDestroyed;
					livingBullet.Release(livingBullet.transform.position);
				}
			}
			livingBullets.Clear();
			IsActive = false;
		}

		private void OnBulletDestroyed(Bullet bullet)
		{
			Remove(bullet);
		}
	}
	public class BulletGroupTracker
	{
		private readonly List<BulletGroup> bulletGroups = new List<BulletGroup>();

		private int perGroupCapacity;

		private bool limitOneImpactPerTarget;

		public float LivingBulletCount
		{
			get
			{
				int num = 0;
				for (int i = 0; i < bulletGroups.Count; i++)
				{
					num += bulletGroups[i].LivingBulletCount;
				}
				return num;
			}
		}

		public BulletGroupTracker(int perGroupCapacity, bool limitOneImpactPerTarget)
		{
			this.perGroupCapacity = perGroupCapacity;
			this.limitOneImpactPerTarget = limitOneImpactPerTarget;
		}

		public BulletGroup GetNewOrEmptyBulletGroup()
		{
			BulletGroup bulletGroup = null;
			foreach (BulletGroup bulletGroup2 in bulletGroups)
			{
				if (!bulletGroup2.IsActive)
				{
					bulletGroup = bulletGroup2;
				}
			}
			if (bulletGroup == null)
			{
				bulletGroup = new BulletGroup(perGroupCapacity, limitOneImpactPerTarget);
				bulletGroups.Add(bulletGroup);
			}
			return bulletGroup;
		}

		public BulletGroup GetBulletGroupContainingBullet(Bullet bullet)
		{
			foreach (BulletGroup bulletGroup in bulletGroups)
			{
				if (bulletGroup.Contains(bullet))
				{
					return bulletGroup;
				}
			}
			return null;
		}

		public BulletGroup GetMostRecentActiveGroup()
		{
			float num = 0f;
			BulletGroup result = null;
			foreach (BulletGroup bulletGroup in bulletGroups)
			{
				if (bulletGroup.IsActive && bulletGroup.AllocatedTime > num)
				{
					num = bulletGroup.AllocatedTime;
					result = bulletGroup;
				}
			}
			return result;
		}
	}
