namespace RecRoom.Core.Rendering
{
	public enum InstancedShaderPropertyType
	{
		COLOR
	}
	public struct InstancedShaderPropertyDescriptor
	{
		public InstancedShaderPropertyType Type;

		public int ShaderPropertyId;
	}
	public class InstancedRenderer
	{
		public readonly long Id;

		public readonly Transform Transform;

		public Color Color = Color.black;

		public InstancedRenderer(long id, Transform transform)
		{
			Id = id;
			Transform = transform;
		}
	}
	public class BulletInstanceRenderer : UnityEngine.MonoBehaviour
	{
		private class InstancedRendererContainer
		{
			private static readonly int INVALID_SHADER_PROPERTY_ID = -1;

			private static readonly int MAX_INSTANCE_COUNT = 128;

			private readonly InstancedShaderPropertyDescriptor[] shaderProperties;

			private readonly Mesh mesh;

			private readonly Material material;

			private readonly Matrix4x4[] matrices;

			private readonly Vector4[] colors;

			private readonly int colorShaderPropertyId;

			private readonly MaterialPropertyBlock materialPropertyBlock;

			private List<InstancedRenderer> instances = new List<InstancedRenderer>();

			public InstancedRendererContainer(Mesh mesh, Material material, params InstancedShaderPropertyDescriptor[] shaderProperties)
			{
				this.shaderProperties = shaderProperties;
				this.mesh = mesh;
				this.material = material;
				matrices = new Matrix4x4[MAX_INSTANCE_COUNT];
				colorShaderPropertyId = INVALID_SHADER_PROPERTY_ID;
				if (shaderProperties == null || shaderProperties.Length <= 0)
				{
					return;
				}
				materialPropertyBlock = new MaterialPropertyBlock();
				for (int i = 0; i < shaderProperties.Length; i++)
				{
					if (shaderProperties[i].Type == InstancedShaderPropertyType.COLOR && colors == null)
					{
						colorShaderPropertyId = shaderProperties[i].ShaderPropertyId;
						colors = new Vector4[MAX_INSTANCE_COUNT];
						materialPropertyBlock.SetVectorArray(colorShaderPropertyId, colors);
					}
				}
			}

			public void AddInstance(InstancedRenderer instance)
			{
				instances.Add(instance);
			}

			public void RemoveInstance(InstancedRenderer instance)
			{
				instances.Remove(instance);
			}

			public void Render()
			{
				if (instances.Count <= 0)
				{
					return;
				}
				int num = Mathf.Min(instances.Count, matrices.Length);
				for (int i = 0; i < num; i++)
				{
					ref Matrix4x4 reference = ref matrices[i];
					reference = instances[i].Transform.localToWorldMatrix;
					if (colorShaderPropertyId != INVALID_SHADER_PROPERTY_ID)
					{
						ref Vector4 reference2 = ref colors[i];
						reference2 = instances[i].Color.linear;
					}
				}
				if (colorShaderPropertyId != INVALID_SHADER_PROPERTY_ID)
				{
					materialPropertyBlock.SetVectorArray(colorShaderPropertyId, colors);
				}
				Graphics.DrawMeshInstanced(mesh, 0, material, matrices, num, materialPropertyBlock);
			}
		}

		private static BulletInstanceRenderer _instance;

		private static GameObject _singleton;

		private Dictionary<long, InstancedRendererContainer> instanceRendererContainers = new Dictionary<long, InstancedRendererContainer>();

		public static BulletInstanceRenderer Instance
		{
			get
			{
				if (_instance == null)
				{
					_singleton = new GameObject();
					_instance = _singleton.AddComponent<BulletInstanceRenderer>();
					_singleton.name = "[BulletInstanceRenderer]";
				}
				return _instance;
			}
		}

		public static bool IsInitialized => _instance != null;

		private void Awake()
		{
			if (base.gameObject != _singleton)
			{
				UnityEngine.Object.DestroyImmediate(base.gameObject);
			}
		}

		private void LateUpdate()
		{
			Render();
		}

		public InstancedRenderer Register(Renderer renderer, params InstancedShaderPropertyDescriptor[] shaderPropertyDescriptors)
		{
			InstancedRenderer result = null;
			if (renderer is MeshRenderer)
			{
				MeshFilter component = renderer.GetComponent<MeshFilter>();
				Mesh mesh = ((!(component != null)) ? null : component.sharedMesh);
				Material sharedMaterial = renderer.sharedMaterial;
				if (mesh != null && sharedMaterial != null)
				{
					int num = mesh.GetInstanceID() & (sharedMaterial.GetInstanceID() << 0);
					InstancedRendererContainer value = null;
					if (!instanceRendererContainers.TryGetValue(num, out value))
					{
						instanceRendererContainers.Add(num, new InstancedRendererContainer(mesh, sharedMaterial, shaderPropertyDescriptors));
					}
					result = new InstancedRenderer(num, renderer.transform);
					UnityEngine.Object.Destroy(renderer);
				}
			}
			return result;
		}

		public void EnableInstancedRenderer(InstancedRenderer instance)
		{
			InstancedRendererContainer value = null;
			if (instanceRendererContainers.TryGetValue(instance.Id, out value))
			{
				value.AddInstance(instance);
			}
		}

		public void DisableInstancedRenderer(InstancedRenderer instance)
		{
			InstancedRendererContainer value = null;
			if (instanceRendererContainers.TryGetValue(instance.Id, out value))
			{
				value.RemoveInstance(instance);
			}
		}

		private void Render()
		{
			foreach (InstancedRendererContainer value in instanceRendererContainers.Values)
			{
				value.Render();
			}
		}
	}
}
public class BulletTrail : LineRendererTrail
{
	private Vector3 previousPosition;

	private bool isStopped;

	protected override void OnEnable()
	{
		base.OnEnable();
		AddNewPosition(base.transform.position, base.transform.up, UnityEngine.Time.time);
	}

	public override void Clear()
	{
		base.Clear();
		isStopped = false;
	}

	protected override void Update()
	{
		if (!isStopped && (base.transform.position - previousPosition).sqrMagnitude >= minSpacingSqr)
		{
			AddNewPosition(base.transform.position, base.transform.up, UnityEngine.Time.time);
		}
		base.Update();
	}

	protected override void AddNewPosition(Vector3 newPosition, Vector3 newTangent, float addTime)
	{
		base.AddNewPosition(newPosition, newTangent, addTime);
		previousPosition = newPosition;
	}

	public void Stop()
	{
		if (!isStopped)
		{
			AddNewPosition(base.transform.position, base.transform.up, UnityEngine.Time.time);
			isStopped = true;
		}
	}
}
