		private PooledParticle triggerPullParticlesPrefab;

		[SerializeField]
		private Transform triggerPullParticleTransform;

		[SerializeField]
		private PooledParticle countdownParticlesPrefab;

		[Header("Haptics")]
		[SerializeField]
		private float vibrationIntensity = 0.7f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip prepareFiringAudio;

		[SerializeField]
		private RecRoomAudioClip fireDelayLoopingAudio;

		private Transform particleRoot;

		private PooledParticle countdownParticles;

		private Coroutine countdownCoroutine;

		private SFXAudioSource fireDelayLoopingAudioSource;

		private static readonly int PREPARE_FIRING_ANIMATION_ID = Animator.StringToHash("PrepareFiring");

		public bool IsCountingDown => countdownCoroutine != null;

		public event Trigger CountdownStartedEvent
		{
			add
			{
				Trigger trigger = this.m_CountdownStartedEvent;
				Trigger trigger2;
				do
				{
					trigger2 = trigger;
					trigger = Interlocked.CompareExchange(ref this.m_CountdownStartedEvent, (Trigger)Delegate.Combine(trigger2, value), trigger);
				}
				while (trigger != trigger2);
			}
			remove
			{
				Trigger trigger = this.m_CountdownStartedEvent;
				Trigger trigger2;
				do
				{
					trigger2 = trigger;
					trigger = Interlocked.CompareExchange(ref this.m_CountdownStartedEvent, (Trigger)Delegate.Remove(trigger2, value), trigger);
				}
				while (trigger != trigger2);
			}
		}

		public event Trigger TriggeredEvent
		{
			add
			{
				Trigger trigger = this.m_TriggeredEvent;
				Trigger trigger2;
				do
				{
					trigger2 = trigger;
					trigger = Interlocked.CompareExchange(ref this.m_TriggeredEvent, (Trigger)Delegate.Combine(trigger2, value), trigger);
				}
				while (trigger != trigger2);
			}
			remove
			{
				Trigger trigger = this.m_TriggeredEvent;
				Trigger trigger2;
				do
				{
					trigger2 = trigger;
					trigger = Interlocked.CompareExchange(ref this.m_TriggeredEvent, (Trigger)Delegate.Remove(trigger2, value), trigger);
				}
				while (trigger != trigger2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			particleRoot = new GameObject("ParticleRoot").transform;
			particleRoot.SetParent(fuseStartTransform, worldPositionStays: false);
			if (tool != null)
			{
				tool.PostResetEvent += OnToolReset;
				tool.InputDownEvent += OnInputDown;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (tool != null)
			{
				tool.PostResetEvent -= OnToolReset;
				tool.InputDownEvent -= OnInputDown;
			}
		}

		public void AuthorityTryFire()
		{
			if (base.hasAuthority && !IsCountingDown)
			{
				if (!weapon.HasEnoughMagazineAmmunition)
				{
					weapon.TryPlayOutOfAmmoFeedback();
				}
				else if (!weapon.IsMisfire && !weapon.IsOnCooldown)
				{
					AuthorityPrepareDelayedFiring();
				}
			}
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			StopDelayedFiring();
		}

		private void OnInputDown(Tool thisTool)
		{
			AuthorityTryFire();
		}

		private void FireTriggerEvent()
		{
			StopDelayedFiring();
			if (this.TriggeredEvent != null)
			{
				this.TriggeredEvent(this);
			}
		}

		private void AuthorityPrepareDelayedFiring()
		{
			base.photonView.RpcAll(RpcPrepareDelayedFiring);
		}

		private void RemotePrepareDelayedFiring()
		{
			StopDelayedFiring();
			countdownCoroutine = StartCoroutine(DelayedFiringCoroutine());
			if (this.CountdownStartedEvent != null)
			{
				this.CountdownStartedEvent(this);
			}
		}

		private void StopDelayedFiring()
		{
			this.SafeStopCoroutine(countdownCoroutine);
			StopDelayLoopingAudio();
			StopParticles();
		}

		private IEnumerator DelayedFiringCoroutine()
		{
			AudioManager.Play3DSFX(prepareFiringAudio, fuseStartTransform);
			if (playPrepareFiringAnimation)
			{
				weapon.SetAnimationTrigger(PREPARE_FIRING_ANIMATION_ID);
			}
			float t = 0f;
			while (t < inputResponseDelay)
			{
				t += UnityEngine.Time.deltaTime;
				yield return null;
			}
			StartDelayLoopingAudio();
			StartParticles();
			for (t = 0f; t < 1f; t += UnityEngine.Time.deltaTime / delay)
			{
				if (fuseEndTransform != null)
				{
					particleRoot.position = Vector3.Lerp(fuseStartTransform.position, fuseEndTransform.position, t);
				}
				if (tool.IsHeld && vibrationIntensity > 0f)
				{
					tool.HolderHand.Vibrate(5, vibrationIntensity);
				}
				yield return null;
			}
			FireTriggerEvent();
			countdownCoroutine = null;
		}

		private void StartParticles()
		{
			if (triggerPullParticlesPrefab != null && triggerPullParticleTransform != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(triggerPullParticlesPrefab);
				pooledParticle.Play(triggerPullParticleTransform.position, triggerPullParticleTransform.rotation);
			}
			if (countdownParticles == null && countdownParticlesPrefab != null)
			{
				countdownParticles = ObjectPool.Instance.Acquire(countdownParticlesPrefab);
				countdownParticles.Play(particleRoot, loop: true);
			}
		}

		private void StopParticles()
		{
			if (countdownParticles != null)
			{
				countdownParticles.Stop();
				countdownParticles = null;
			}
		}

		private void StartDelayLoopingAudio()
		{
			StopDelayLoopingAudio();
			fireDelayLoopingAudioSource = AudioManager.StartLooping3DSFX(fireDelayLoopingAudio, fuseStartTransform);
		}

		private void StopDelayLoopingAudio()
		{
			if (fireDelayLoopingAudioSource != null)
			{
				AudioManager.StopLoopingSFX(fireDelayLoopingAudioSource);
				fireDelayLoopingAudioSource = null;
			}
		}

		[PunRPC]
		private void RpcPrepareDelayedFiring()
		{
			RemotePrepareDelayedFiring();
		}
	}
