	public void Explode(Vector3 position, float radius, float force, Player ignorePlayer = null)
	{
		Explode(position, radius, force, DEFAULT_FALLOFF_CURVE, DEFAULT_FALLOFF_CURVE, 1f, ignorePlayer);
	}

	public void Explode(Vector3 position, float radius, float force, AnimationCurve damageFalloff, AnimationCurve forceFalloff, float maxPlayerDamageFalloff, Player ignorePlayer = null)
	{
		INSTANTAENOUSLY_HIT_OBJECTS.Clear();
		Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
		int num = Physics.OverlapSphereNonAlloc(position, radius, iMMEDIATE_COLLIDER_HITS, 496383488, QueryTriggerInteraction.Ignore);
		for (int i = 0; i < num; i++)
		{
			Collider collider = iMMEDIATE_COLLIDER_HITS[i];
			Vector3 vector = collider.ClosestPoint(position);
			float magnitude = Vector3.ProjectOnPlane(vector - position, Vector3.up).magnitude;
			float num2 = magnitude / radius;
			Vector3 normalized = (collider.transform.position - position).normalized;
			WeaponImpact impact = new WeaponImpact
			{
				Velocity = Vector3.zero,
				Force = normalized * (force * forceFalloff.Evaluate(num2)),
				GameObject = collider.gameObject,
				Point = vector,
				Distance = magnitude,
				SurfaceNormal = -normalized,
				PreAttackChargeAmount = damageFalloff.Evaluate(num2)
			};
			Player player = null;
			Enemy enemy = null;
			Tool tool = null;
			Trap trap = null;
			EnemyArmorType hitEnemyArmorType;
			if ((player = collider.GetColliderPlayer(out var _)) != null && (ignorePlayer == null || player != ignorePlayer) && num2 <= maxPlayerDamageFalloff)
			{
				if (!INSTANTAENOUSLY_HIT_OBJECTS.Contains(player.gameObject))
				{
					INSTANTAENOUSLY_HIT_OBJECTS.Add(player.gameObject);
					if (this.PlayerImpactEvent != null)
					{
						this.PlayerImpactEvent(player, Player.BodyPart.Torso, impact);
					}
				}
			}
			else if ((enemy = collider.GetColliderEnemy(out hitEnemyArmorType)) != null)
			{
				if (!INSTANTAENOUSLY_HIT_OBJECTS.Contains(enemy.gameObject))
				{
					INSTANTAENOUSLY_HIT_OBJECTS.Add(enemy.gameObject);
					if (this.EnemyImpactEvent != null)
					{
						this.EnemyImpactEvent(enemy, EnemyArmorType.NORMAL, impact);
					}
				}
			}
			else if ((tool = collider.GetColliderTool()) != null)
			{
				if (!INSTANTAENOUSLY_HIT_OBJECTS.Contains(tool.gameObject))
				{
					INSTANTAENOUSLY_HIT_OBJECTS.Add(tool.gameObject);
					if (this.ToolImpactEvent != null)
					{
						this.ToolImpactEvent(tool, impact);
					}
				}
			}
			else if ((trap = collider.GetColliderTrap()) != null && !INSTANTAENOUSLY_HIT_OBJECTS.Contains(trap.gameObject))
			{
				INSTANTAENOUSLY_HIT_OBJECTS.Add(trap.gameObject);
				if (this.TrapImpactEvent != null)
				{
					this.TrapImpactEvent(trap, impact);
				}
			}
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class ExplosiveRangedWeapon : RangedWeapon
	{
		[Header("Direct Damage")]
		[SerializeField]
		private bool applyDirectDamage;

		[SerializeField]
		private PooledParticle directDamageParticles;

		[SerializeField]
		private RecRoomAudioClip directDamageImpactAudio;

		[Header("Explosives")]
		[SerializeField]
		private float explosionDelay;

		[SerializeField]
		protected float explosionRadius = 2f;

		[SerializeField]
		protected float explosionForce = 30f;

		[SerializeField]
		protected PooledParticle explosionParticles;

		[SerializeField]
		protected RecRoomAudioClip explosionAudio;

		[SerializeField]
		protected AnimationCurve forceFalloff = AnimationCurve.Linear(0f, 1f, 1f, 1f);

		[SerializeField]
		protected AnimationCurve damageFalloff = AnimationCurve.Linear(0f, 1f, 1f, 1f);

		[SerializeField]
		[Range(0f, 1f)]
		protected float maxPlayerDamageFalloff = 1f;

		protected Explosive explosive = new Explosive();

		private Bullet lastShot;

		private GameObject lastExplosion;

		protected override void Awake()
		{
			base.Awake();
			explosive.PlayerImpactEvent += OnExplosivePlayerImpact;
			explosive.EnemyImpactEvent += OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent += OnExplosiveTrapImpact;
			explosive.ToolImpactEvent += OnExplosiveToolImpact;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			explosive.PlayerImpactEvent -= OnExplosivePlayerImpact;
			explosive.EnemyImpactEvent -= OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent -= OnExplosiveTrapImpact;
			explosive.ToolImpactEvent -= OnExplosiveToolImpact;
		}

		protected override bool CanDisablePostTotalAmmunitionExhaustion()
		{
			return (!lastShot || !lastShot.enabled) && (!lastExplosion || !lastExplosion.activeSelf);
		}

		protected override Bullet AcquireBullet(Bullet prefab = null)
		{
			return lastShot = base.AcquireBullet(prefab);
		}

		protected override void OnBulletDestroyed(Bullet bullet, Vector3 position)
		{
			base.OnBulletDestroyed(bullet, position);
			if (lastShot == bullet)
			{
				lastShot = null;
			}
			if (applyDirectDamage)
			{
				PlayParticles(directDamageParticles, position);
				if (base.transform != null)
				{
					AudioManager.Play3DSFX(directDamageImpactAudio, base.transform);
				}
			}
			lastExplosion = base.gameObject;
			Explode(explosionDelay, position, explosionRadius);
		}

		protected void AuthorityManualExplode(float delay, Vector3 position, float radius, float chargeAmount = 1f)
		{
			if (base.hasAuthority)
			{
				base.photonView.RpcAll(RpcManualExplode, delay, position, radius, chargeAmount);
			}
		}

		[PunRPC]
		protected void RpcManualExplode(float delay, Vector3 position, float radius, float chargeAmount)
		{
			Explode(delay, position, radius, chargeAmount);
		}

		protected virtual void Explode(float delay, Vector3 position, float radius, float chargeAmount = 1f)
		{
			if (delay <= Mathf.Epsilon)
			{
				ExplodeInternal(position, radius, chargeAmount);
			}
			else
			{
				StartCoroutine(ExplodeCoroutine(delay, position, radius, chargeAmount));
			}
		}

		private IEnumerator ExplodeCoroutine(float delay, Vector3 position, float radius, float chargeAmount = 1f)
		{
			yield return new WaitForSeconds(delay);
			ExplodeInternal(position, radius, chargeAmount);
		}

		protected void ExplodeInternal(Vector3 position, float radius, float chargeAmount = 1f, float explosionParticleSizeMultiplier = 1f)
		{
			PooledParticle pooledParticle = PlayParticles(explosionParticles, position, forceOverrideColor: true, explosionParticleSizeMultiplier);
			if ((bool)pooledParticle)
			{
				lastExplosion = pooledParticle.gameObject;
			}
			AudioManager.Play3DSFX(explosionAudio, position);
			explosive.Explode(position, radius, explosionForce, damageFalloff, forceFalloff, maxPlayerDamageFalloff);
		}

		protected override void OnBulletPlayerImpact(Bullet bullet, Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
			if (applyDirectDamage)
			{
				base.OnBulletPlayerImpact(bullet, player, bodyPart, impact);
			}
		}

		protected override void OnBulletEnemyImpact(Bullet bullet, Enemy enemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			if (applyDirectDamage)
			{
				base.OnBulletEnemyImpact(bullet, enemy, enemyArmorType, impact);
			}
		}

		protected override void OnBulletToolImpact(Bullet bullet, Tool hitTool, WeaponImpact impact)
		{
			if (applyDirectDamage)
			{
				base.OnBulletToolImpact(bullet, hitTool, impact);
			}
		}

		protected override void OnBulletTrapImpact(Bullet bullet, Trap trap, WeaponImpact impact)
		{
			if (applyDirectDamage)
			{
				base.OnBulletTrapImpact(bullet, trap, impact);
			}
		}

		protected virtual void OnExplosivePlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			OnPlayerImpact(hitPlayer, hitBodyPart, impact);
		}

		protected virtual void OnExplosiveEnemyImpact(Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			if (!(base.Wielder.Enemy != null))
			{
				OnEnemyImpact(hitEnemy, EnemyArmorType.NORMAL, impact);
				if (base.hasAuthority && hitEnemy.hasAuthority)
				{
					hitEnemy.AuthorityOnDamageApplyForce(WeaponDamageType.EXPLOSIVE, armorType, impact.Force, impact.Point);
				}
			}
		}

		protected virtual void OnExplosiveToolImpact(Tool hitTool, WeaponImpact impact)
		{
			if (!(hitTool == base.Tool))
			{
				OnToolImpact(hitTool, impact);
				if (base.hasAuthority && hitTool.hasAuthority)
				{
					hitTool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Impulse);
				}
			}
		}

		protected virtual void OnExplosiveTrapImpact(Trap hitTrap, WeaponImpact impact)
		{
			OnTrapImpact(hitTrap, impact);
			if (base.hasAuthority && hitTrap.hasAuthority)
			{
				hitTrap.AuthorityOnDamageApplyForce(WeaponDamageType.EXPLOSIVE, impact.Force, impact.Point);
			}
		}

		public override int GetPlayerImpactDamage(Player.BodyPart hitBodyPart, float preAttackChargeAmount, bool selfDamage)
		{
			return Mathf.RoundToInt((float)base.GetPlayerImpactDamage(hitBodyPart, preAttackChargeAmount, selfDamage) * Mathf.Clamp01(preAttackChargeAmount));
		}
	}
	public class ExplosiveWeaponAddon : Photon.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Weapon weapon;

		[AutofillOptional(AutofillType.Self, false)]
		[SerializeField]
		private BreakableObject breakableObject;

		[Header("Explosion")]
		[SerializeField]
		private float radius = 3f;

		[SerializeField]
		private float force = 30f;

		[SerializeField]
		private int damage = 100;

		[SerializeField]
		private bool canDamageHolderPlayer;

		[SerializeField]
		private bool canExplodeWhenHeld;

		[Header("Feedback")]
		[SerializeField]
		private PooledParticle explosionParticles;

		[SerializeField]
		private RecRoomAudioClip explosionAudio;

		private Explosive explosive = new Explosive();

		protected override void Awake()
		{
			base.Awake();
			explosive.PlayerImpactEvent += OnExplosivePlayerImpact;
			explosive.ToolImpactEvent += OnExplosiveToolImpact;
			explosive.EnemyImpactEvent += OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent += OnExplosiveTrapImpact;
			if (weapon != null)
			{
				weapon.PostImpactEvent += OnWeaponPostImpact;
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			explosive.PlayerImpactEvent -= OnExplosivePlayerImpact;
			explosive.ToolImpactEvent -= OnExplosiveToolImpact;
			explosive.EnemyImpactEvent -= OnExplosiveEnemyImpact;
			explosive.TrapImpactEvent -= OnExplosiveTrapImpact;
			if (weapon != null)
			{
				weapon.PostImpactEvent -= OnWeaponPostImpact;
			}
		}

		private void OnWeaponPostImpact(Weapon weapon, WeaponImpact impact, bool hadDamageAuthority)
		{
			if (hadDamageAuthority && base.hasAuthority && (!(breakableObject != null) || breakableObject.CanShatter) && (canExplodeWhenHeld || !weapon.Tool.IsHeld))
			{
				base.photonView.RpcAll(RpcExplode, impact.Point);
			}
		}

		private void RemoteExplode(Vector3 point)
		{
			if (explosionParticles != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(explosionParticles);
				if (pooledParticle != null)
				{
					pooledParticle.Play(point, Quaternion.identity);
				}
			}
			AudioManager.Play3DSFX(explosionAudio, point);
			Player ignorePlayer = null;
			if (!canDamageHolderPlayer && weapon != null && weapon.Tool != null && weapon.Tool.HolderPlayer != null)
			{
				ignorePlayer = weapon.Tool.HolderPlayer;
			}
			explosive.Explode(point, radius, force, ignorePlayer);
		}

		private void OnExplosivePlayerImpact(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (weapon != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestWeaponOnPlayerDamage(weapon, WeaponDamageType.EXPLOSIVE, hitPlayer, hitBodyPart, impact);
			}
		}

		private void OnExplosiveToolImpact(Tool hitTool, WeaponImpact impact)
		{
			if (weapon != null && hitTool != weapon.Tool && base.hasAuthority)
			{
				hitTool.ApplyAttackAndTryTakeOwnership(weapon, WeaponDamageType.EXPLOSIVE, impact.Point);
				if (hitTool.hasAuthority)
				{
					hitTool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Impulse);
				}
			}
		}

		private void OnExplosiveEnemyImpact(Enemy hitEnemy, EnemyArmorType armorType, WeaponImpact impact)
		{
			if (!(weapon != null) || !(weapon.Wielder.Enemy == null))
			{
				return;
			}
			bool hadDamageAuthority = false;
			if (base.hasAuthority)
			{
				if (!hitEnemy.hasAuthority)
				{
					hitEnemy.TransferOwnership(PhotonNetwork.player);
				}
				hadDamageAuthority = hitEnemy.AuthorityTryApplyAttack(base.authority, weapon, WeaponDamageType.EXPLOSIVE, armorType, damage, impact);
				hitEnemy.AuthorityOnDamageApplyForce(WeaponDamageType.EXPLOSIVE, armorType, impact.Force, impact.Point);
			}
			weapon.RaiseEnemyImpactEvent(hitEnemy, armorType, impact, hadDamageAuthority);
		}

		private void OnExplosiveTrapImpact(Trap trap, WeaponImpact impact)
		{
			if (weapon != null && base.hasAuthority)
			{
				if (!trap.hasAuthority)
				{
					trap.photonView.TransferOwnership(PhotonNetwork.player);
				}
				trap.AuthorityApplyDamage(WeaponDamageType.EXPLOSIVE, damage, impact.Point, impact.SurfaceNormal);
			}
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.blue;
			Gizmos.DrawWireSphere(base.transform.position, radius);
		}

		[PunRPC]
		private void RpcExplode(Vector3 point)
		{
			RemoteExplode(point);
		}
	}
}
public class ImpactDecal : UnityEngine.MonoBehaviour
{
	private static readonly Vector3 DEFAULT_MIN_MAX_DECAL_SCALE = new Vector2(0.8f, 1.2f);

	[SerializeField]
	private float lifetime = 2f;

	[SerializeField]
	private float fadeOutTime = 1f;

	[SerializeField]
	private float bias = 0.01f;

	[SerializeField]
	private Vector2 defaultMinMaxScale = new Vector2(0.8f, 1.2f);

	private Renderer[] renderers;

	private Vector3 defaultScale = Vector3.one;

	private float enableTime;

	private Transform targetParent;

	private Quaternion targetLocalRotation = Quaternion.identity;

	private Vector3 targetLocalPosition = Vector3.zero;

	private Color _color;

	public Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			_color = value;
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				renderer.material.color = _color;
			}
		}
	}

	public static void Spawn(ImpactDecal prefab, Color color, Vector3 position, Vector3 normal, GameObject parent)
	{
		Spawn(prefab, color, position, normal, parent, 0f);
	}

	public static void Spawn(ImpactDecal prefab, Color color, Vector3 position, Vector3 normal, GameObject parent, float randomOffset)
	{
		Spawn(prefab, color, position, normal, parent, randomOffset, DEFAULT_MIN_MAX_DECAL_SCALE);
	}

	public static void Spawn(ImpactDecal prefab, Color color, Vector3 position, Vector3 normal, GameObject parent, float randomOffset, Vector2 minMaxScale)
	{
		ImpactDecal impactDecal = ObjectPool.Instance.Acquire(prefab);
		if (impactDecal != null)
		{
			if (randomOffset > 0f)
			{
				Vector3 vector = UnityEngine.Random.insideUnitCircle * randomOffset;
				vector = Quaternion.LookRotation(normal) * vector;
				position += vector;
			}
			impactDecal.Color = color;
			impactDecal.Splat(position, normal, parent, minMaxScale.x, minMaxScale.y);
		}
	}

	private void Awake()
	{
		renderers = GetComponentsInChildren<Renderer>();
		defaultScale = base.transform.localScale;
	}

	private void OnEnable()
	{
		enableTime = -1f;
	}

	private void OnDisable()
	{
		if (base.gameObject.activeSelf)
		{
			ReleaseDecal();
		}
	}

	private void ReleaseDecal()
	{
		ObjectPool.Instance.Release(this);
		targetParent = null;
	}

	private void Update()
	{
		if (enableTime < 0f)
		{
			return;
		}
		if (targetParent != null && !targetParent.gameObject.activeSelf)
		{
			ReleaseDecal();
			return;
		}
		float num = UnityEngine.Time.time - enableTime;
		if (num > lifetime)
		{
			float num2 = num - lifetime;
			Color color = Color;
			color.a = 1f - Mathf.Clamp01(num2 / fadeOutTime);
			Color = color;
			if (num2 >= fadeOutTime)
			{
				ReleaseDecal();
			}
		}
		UpdatePosition();
	}

	private void UpdatePosition()
	{
		if (targetParent != null)
		{
			base.transform.position = targetParent.TransformPoint(targetLocalPosition);
			base.transform.rotation = targetParent.TransformRotation(targetLocalRotation);
		}
	}

	public void Splat(Vector3 position, Vector3 normal, GameObject hitGameObject)
	{
		Splat(position, normal, hitGameObject, defaultMinMaxScale.x, defaultMinMaxScale.y);
	}

	public void Splat(Vector3 position, Vector3 normal, GameObject hitGameObject, float minScale, float maxScale)
	{
		targetParent = hitGameObject.transform;
		Quaternion rotation = Quaternion.LookRotation(-normal, Vector3.up) * Quaternion.Euler(0f, 0f, UnityEngine.Random.Range(0f, 360f));
		targetLocalRotation = targetParent.InverseTransformRotation(rotation);
		targetLocalPosition = targetParent.InverseTransformPoint(position + normal * bias);
		Vector3 vector = defaultScale * UnityEngine.Random.Range(minScale, maxScale);
		Vector3 lossyScale = base.transform.lossyScale;
		if (lossyScale != vector)
		{
			Vector3 b = new Vector3(base.transform.localScale.x / lossyScale.x, base.transform.localScale.y / lossyScale.y, base.transform.localScale.z / lossyScale.z);
			base.transform.localScale = Vector3.Scale(vector, b);
		}
		base.enabled = true;
		enableTime = UnityEngine.Time.time;
		UpdatePosition();
	}
}
namespace RecRoom.Core.Combat
{
	public class MeleeWeapon : Weapon, ICustomImposterBehavior
	{
		private enum SwingState
		{
			NOT_SWINGING,
			SWINGING,
			POST_SWING,
			DISABLED
		}

		protected class Hit
		{
			public readonly UnityEngine.Object Target;

			public readonly int Tag;

			public readonly Vector3 LinearVelocity;

			public readonly Vector3 AngularVelocity;

			public readonly WeaponDamageType DamageType;

			private readonly float startTime;

			private readonly int attackCount;

			public bool StillColliding => TimeSinceHitStart <= 0.2f && Target != null;

			private float TimeSinceHitStart => UnityEngine.Time.time - startTime;

			public Hit(UnityEngine.Object target, int tag, float startTime, int attackCount, WeaponDamageType damageType, Vector3 linearVelocity, Vector3 angularVelocity)
			{
				Target = target;
				Tag = tag;
				this.startTime = startTime;
				this.attackCount = attackCount;
				DamageType = damageType;
				LinearVelocity = linearVelocity;
				AngularVelocity = angularVelocity;
			}

			public bool HasExpired(int attackCount)
			{
				return TimeSinceHitStart > 0.66f || attackCount != this.attackCount || Target == null;
			}
		}

