		public bool CanBlockEnemyMeleeAttacks => canBlockEnemyMeleeAttacks && (BlocksEnemyAttacksAutomatically || ManualBlockingEnabled);

		public bool CanBeBlockedByEnemies => !IsThrow() || canBeBlockedByEnemiesWhileThrown;

		public bool IsBroken => isDestructible && GetRemainingDestructibleChunkCount() <= 1;

		protected override Color WeaponColor => (!(base.TeamColor != null) || !base.TeamColor.IsValidTeam) ? impactColor : base.TeamColor.Color;

		protected override void Awake()
		{
			base.Awake();
			base.DefenderHasDamageAuthority = true;
			_calculateSwingingAutomatically = new SynchronizedField<bool>(this, "CSWINGAUTO", defaultValue: true, SetterPermissionMode.AUTHORITY);
			_blocksEnemyAttacksAutomatically = new SynchronizedField<bool>(this, "BEAATO", defaultValue: true, SetterPermissionMode.AUTHORITY);
			_manualBlockingEnabled = new SynchronizedField<bool>(this, "MANBLOCK", defaultValue: false, SetterPermissionMode.AUTHORITY);
			int maximumDestructibleChunkDurability = GetMaximumDestructibleChunkDurability();
			_durability = new SynchronizedField<int>(this, "DURAB", maximumDestructibleChunkDurability, SetterPermissionMode.AUTHORITY, OnDurabilityChange);
			if (base.Tool != null)
			{
				if (supportSwingSpringiness)
				{
					base.Tool.RigidbodyPickup.PhysicsJointSpringSettings = defaultSpringSettings;
				}
				base.Tool.RigidbodyPickup.PickupWithPhysicsJoint = supportSwingSpringiness;
				if (isDestructible)
				{
					base.Tool.AddCustomPickupCondition(DestructibleCustomPickupCondition);
					base.Tool.AddCustomEquipCondition(DestructibleCustomEquipCondition);
				}
				if (base.IsShield)
				{
					base.Tool.SupportsToolOverlap = true;
				}
				base.Tool.EnabledChangeEvent += OnToolEnabledChange;
				base.Tool.PostPickupEvent += OnPostPickup;
				base.Tool.PostReleaseEvent += OnPostRelease;
				base.Tool.OwnerTeleportEvent += OnOwnerTeleport;
				base.Tool.OwnerRotateInPlaceEvent += OnOwnerRotateInPlace;
				base.Tool.VisibilityChangeEvent += OnVisibilityChange;
				base.Tool.HolderHandVelocityUpdateEvent += UpdateAutomaticSwing;
			}
			InitializeMeleeWeaponColliders();
		}

		protected override void Start()
		{
			base.Start();
			CheckIfDestroyAfterDestruction();
			InitializeTrails();
			InitializeDestructibleChunks();
			UpdateMeleeColliderCollisonEnabled(base.Wielder.Enemy != null);
			if (base.TeamColor != null)
			{
				base.TeamColor.ColorChangeEvent += OnTeamColorChange;
				OnTeamColorChange();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CleanupMeleeWeaponColliders();
			if (base.Tool != null)
			{
				base.Tool.EnabledChangeEvent -= OnToolEnabledChange;
				base.Tool.PostPickupEvent -= OnPostPickup;
				base.Tool.PostReleaseEvent -= OnPostRelease;
				base.Tool.OwnerTeleportEvent -= OnOwnerTeleport;
				base.Tool.OwnerRotateInPlaceEvent -= OnOwnerRotateInPlace;
				base.Tool.VisibilityChangeEvent -= OnVisibilityChange;
				base.Tool.HolderHandVelocityUpdateEvent -= UpdateAutomaticSwing;
				if (base.TeamColor != null)
				{
					base.TeamColor.ColorChangeEvent -= OnTeamColorChange;
				}
			}
		}

		public override void AddImpactIgnoredRigidbody(Rigidbody rigidbody)
		{
			base.AddImpactIgnoredRigidbody(rigidbody);
			for (int i = 0; i < meleeColliders.Length; i++)
			{
				meleeColliders[i].AddIgnoredRigidbody(rigidbody);
			}
		}

		private void FixedUpdate()
		{
			UpdateHits();
			if (!CalculateSwingingAutomatically)
			{
				UpdateManualSwingTrail();
			}
			else if (!base.Tool.IsHeld)
			{
				UpdateAutomaticSwing(base.Tool);
			}
		}

		protected override void OnWielderChange()
		{
			base.OnWielderChange();
			if (base.Wielder.Enemy != null)
			{
				UpdateMeleeColliderCollisonEnabled(collisionEnabled: true);
			}
		}

		private void OnPostPickup(Tool tool)
		{
			UpdateMeleeColliderCollisonEnabled(collisionEnabled: true);
			UpdateCenterOfMass();
		}

		private void OnPostRelease(Tool tool)
		{
			alreadyHitOnThrow = false;
			bool collisionEnabled = supportsThrowDamage && base.Tool.RigidbodyEx.velocity.sqrMagnitude >= minThrowDamageSpeed * minThrowDamageSpeed;
			UpdateMeleeColliderCollisonEnabled(collisionEnabled);
			if (isDestructible)
			{
				int remainingDestructibleChunkCount = GetRemainingDestructibleChunkCount();
				if (remainingDestructibleChunkCount <= 1 && !DurabilityDelayedDestructionCoroutineIsRunning())
				{
					StartDurabilityDelayedDestructionCoroutine();
				}
			}
			UpdateCenterOfMass(forceReset: true);
		}

		protected virtual void OnToolEnabledChange(Tool tool)
		{
			if (tool != null && !tool.IsEnabled)
			{
				StopDurabilityDelayedDestructionCoroutine();
				ResetDestructibleChunks();
			}
		}

		protected override void OnReset(Tool thisTool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasEnabled)
		{
			base.OnReset(thisTool, position, rotation, oldPosition, wasEnabled);
			if (base.hasAuthority)
			{
				Durability = GetMaximumDestructibleChunkDurability();
			}
			attackCount = 0;
			alreadyHitOnThrow = false;
			StopDurabilityDelayedDestructionCoroutine();
			CheckIfDestroyAfterDestruction();
			ResetDestructibleChunks();
		}

		private void OnOwnerRotateInPlace(Tool thisTool, float angle, float duration)
		{
			playerRotateFinishTime = UnityEngine.Time.time + duration;
			TemporarilyDisableSwing(duration);
		}

		private void OnOwnerTeleport(Tool thisTool, float duration)
		{
			playerTeleportFinishTime = UnityEngine.Time.time + duration;
			TemporarilyDisableSwing(duration);
		}

		public void StartManualSwing(float manualSwingNormalizedSpeed)
		{
			if (!CalculateSwingingAutomatically)
			{
				this.manualSwingNormalizedSpeed = manualSwingNormalizedSpeed;
				if (swingState != SwingState.SWINGING)
				{
					swingState = SwingState.SWINGING;
					OnSwingStart();
				}
			}
		}

		public void StopManualSwing()
		{
			if (!CalculateSwingingAutomatically)
			{
				manualSwingNormalizedSpeed = 0f;
				swingState = SwingState.NOT_SWINGING;
			}
		}

		public bool IsSwing()
		{
			bool flag = UnityEngine.Time.time < playerTeleportFinishTime || UnityEngine.Time.time < playerRotateFinishTime;
			bool flag2 = (base.Tool.HolderHand != null && base.Tool.HolderHand.HandOnlyVelocity.magnitude >= 3f) || swingState == SwingState.SWINGING;
			return base.Tool.IsHeld && !base.Tool.RigidbodyPickup.InterpolatingToTarget && flag2 && !flag;
		}

		private void OnSwingStart()
		{
			bool flag = UnityEngine.Time.time < playerTeleportFinishTime || UnityEngine.Time.time < playerRotateFinishTime;
			if (((base.Tool.HolderView != null && base.Tool.HolderView.isLocal && CalculateSwingingAutomatically) || !flag) && base.WeaponAudio != null)
			{
				base.WeaponAudio.OnSwing(base.transform);
			}
			swingStartTime = UnityEngine.Time.time;
			attackCount++;
		}

		private void UpdateManualSwingTrail()
		{
			if (!CalculateSwingingAutomatically)
			{
				float targetTrailOpacity = 0f;
				if ((base.Tool.IsHeld && showTrailOnSwing && IsSwing()) || (!base.Tool.IsHeld && showTrailOnThrow))
				{
					targetTrailOpacity = 1f;
				}
				UpdateTrailOpacity(targetTrailOpacity);
			}
		}

		private void UpdateAutomaticSwing(Tool tool)
		{
			if (!CalculateSwingingAutomatically)
			{
				return;
			}
			float num = ((!(base.Tool.HolderHand != null)) ? base.Tool.RigidbodyEx.velocity.magnitude : base.Tool.HolderHand.HandOnlyVelocity.magnitude);
			switch (swingState)
			{
			case SwingState.DISABLED:
				if (UnityEngine.Time.time - swingDisableStartTime > swingDisableDuration)
				{
					swingState = SwingState.NOT_SWINGING;
				}
				break;
			case SwingState.NOT_SWINGING:
				if (num >= 3f && base.Tool.IsHeld)
				{
					if (supportSwingSpringiness)
					{
						base.Tool.RigidbodyPickup.PhysicsJointSpringSettings = swingSpringSettings;
					}
					swingState = SwingState.SWINGING;
					OnSwingStart();
				}
				break;
			case SwingState.SWINGING:
				if (!base.Tool.IsHeld || (num < 3f && UnityEngine.Time.time - swingStartTime >= 0.33f))
				{
					postSwingStartTime = UnityEngine.Time.time;
					swingState = SwingState.POST_SWING;
				}
				break;
			case SwingState.POST_SWING:
				if (base.Tool.IsHeld && num >= 3f)
				{
					swingState = SwingState.SWINGING;
					OnSwingStart();
				}
				else if (UnityEngine.Time.time - postSwingStartTime >= 0.33f || num < 0.5f)
				{
					if (supportSwingSpringiness)
					{
						base.Tool.RigidbodyPickup.PhysicsJointSpringSettings = defaultSpringSettings;
					}
					swingState = SwingState.NOT_SWINGING;
				}
				break;
			}
			float targetTrailOpacity = 0f;
			if ((base.Tool.IsHeld && showTrailOnSwing) || (!base.Tool.IsHeld && showTrailOnThrow))
			{
				targetTrailOpacity = Mathf.InverseLerp(3f, 5f, num);
			}
			UpdateTrailOpacity(targetTrailOpacity);
		}

		private void TemporarilyDisableSwing(float duration)
		{
			swingState = SwingState.DISABLED;
			swingDisableStartTime = UnityEngine.Time.time;
			swingDisableDuration = duration;
		}

