		private void InitializeDestructibleChunks()
		{
			if (destructibleChunks != null)
			{
				for (int i = 0; i < destructibleChunks.Length; i++)
				{
					destructibleChunks[i].Initialize(this);
				}
				OnDurabilityChange();
			}
		}

		private void ResetDestructibleChunks()
		{
			if (destructibleChunks != null)
			{
				for (int i = 0; i < destructibleChunks.Length; i++)
				{
					destructibleChunks[i].DurabilityDamageTaken = 0;
					destructibleChunks[i].IsEnabled = true;
				}
			}
		}

		private void UpdateDestructibleChunkMeleeCollision()
		{
			if (destructibleChunks != null)
			{
				for (int i = 0; i < destructibleChunks.Length; i++)
				{
					destructibleChunks[i].UpdateMeleeCollisionEnabled();
				}
			}
		}

		private void UpdateDestructibleChunkTrailVisibility()
		{
			if (destructibleChunks != null)
			{
				for (int i = 0; i < destructibleChunks.Length; i++)
				{
					destructibleChunks[i].UpdateTrailVisibility();
				}
			}
		}

		private bool DestructibleCustomPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			if (canPickupLastDestructibleChunk)
			{
				return true;
			}
			int remainingDestructibleChunkCount = GetRemainingDestructibleChunkCount();
			return remainingDestructibleChunkCount > 1;
		}

		private bool DestructibleCustomEquipCondition(Tool thisTool, Player equippingPlayer, ToolEquipSlot equipSlot)
		{
			if (canPickupLastDestructibleChunk)
			{
				return true;
			}
			int remainingDestructibleChunkCount = GetRemainingDestructibleChunkCount();
			return remainingDestructibleChunkCount > 1;
		}

		private float GetRemainingDestructibleChunkDamageMultiplier()
		{
			float num = 0f;
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				if (destructibleChunks[i].IsEnabled)
				{
					num += destructibleChunks[i].WeaponAttackContribution;
				}
			}
			return num;
		}

		private int GetRemainingDestructibleChunkCount()
		{
			int num = 0;
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				if (destructibleChunks[i].IsEnabled)
				{
					num++;
				}
			}
			return num;
		}

		private int GetMaximumDestructibleChunkDurability()
		{
			int num = 0;
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				num = Mathf.Max(num, destructibleChunks[i].Durability);
			}
			return num;
		}

		private void OnDurabilityChange()
		{
			if (!isDestructible)
			{
				return;
			}
			int maximumDestructibleChunkDurability = GetMaximumDestructibleChunkDurability();
			int num = maximumDestructibleChunkDurability - Durability;
			int num2 = 0;
			int num3 = 0;
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				if (destructibleChunks[i].IsEnabled)
				{
					num2++;
				}
				destructibleChunks[i].DurabilityDamageTaken = num;
				bool flag = num < destructibleChunks[i].Durability;
				destructibleChunks[i].IsEnabled = flag;
				if (flag)
				{
					num3++;
				}
			}
			if (num2 != num3)
			{
				UpdateCenterOfMass();
			}
			if (isDestructible && num3 <= 1 && !base.Tool.IsHeld && !DurabilityDelayedDestructionCoroutineIsRunning())
			{
				StartDurabilityDelayedDestructionCoroutine();
			}
		}

		private void AuthorityApplyDurabilityDamage(Vector3 impactVelocity, Vector3 surfaceNormal, int durabilityDamage)
		{
			if (!base.hasAuthority || !isDestructible)
			{
				return;
			}
			int maximumDestructibleChunkDurability = GetMaximumDestructibleChunkDurability();
			int num = maximumDestructibleChunkDurability - Durability;
			int num2 = num + durabilityDamage;
			int num3 = GetRemainingDestructibleChunkCount();
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				if (destructibleChunks[i].Durability > num && destructibleChunks[i].Durability <= num2)
				{
					num3--;
					bool arg = num3 == 0;
					Vector3 originPosition = destructibleChunks[i].OriginPosition;
					Vector3 arg2 = Vector3.Reflect(impactVelocity, surfaceNormal);
					base.photonView.RpcAll(RpcOnChunkDestruction, i, originPosition, arg2, arg);
				}
			}
			Durability -= durabilityDamage;
		}

		private void RemoteOnChunkDestruction(int chunkIndex, Vector3 breakPoint, Vector3 chunkVelocity, bool lastChunk)
		{
			if (chunkIndex < 0 || chunkIndex >= destructibleChunks.Length)
			{
				return;
			}
			float magnitude = chunkVelocity.magnitude;
			Vector3 vector = chunkVelocity / magnitude;
			if (!lastChunk)
			{
				float num = magnitude * 0.1f;
				Vector3 initialVelocity = vector * num;
				destructibleChunks[chunkIndex].Shatter(initialVelocity, 3f);
			}
			if (chunkBreakParticles != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(chunkBreakParticles);
				if (pooledParticle != null)
				{
					float startSpeedMultiplier = magnitude * 0.5f;
					ParticleSystem.MainModule main = pooledParticle.PrimaryParticleSystem.main;
					main.startSpeedMultiplier = startSpeedMultiplier;
					pooledParticle.Play(breakPoint, Quaternion.LookRotation(vector));
				}
			}
			AudioManager.Play3DSFX(chunkBreakAudio, breakPoint);
			if (base.Tool.IsHeldByPlayer && base.Tool.HolderPlayer.isLocal)
			{
				PlayMeleeWeaponChunkDestructionHaptics();
			}
		}

		private bool DurabilityDelayedDestructionCoroutineIsRunning()
		{
			return durabilityDelayedDestructionCoroutine != null;
		}

		private void StartDurabilityDelayedDestructionCoroutine()
		{
			StopDurabilityDelayedDestructionCoroutine();
			durabilityDelayedDestructionCoroutine = StartCoroutine(DurabilityDelayedDestructionCoroutine());
		}

		private void StopDurabilityDelayedDestructionCoroutine()
		{
			if (durabilityDelayedDestructionCoroutine != null)
			{
				StopCoroutine(durabilityDelayedDestructionCoroutine);
				durabilityDelayedDestructionCoroutine = null;
			}
		}

		private IEnumerator DurabilityDelayedDestructionCoroutine()
		{
			if (base.Tool != null)
			{
				base.Tool.SuppressAnimateInOut = true;
			}
			float startTime = UnityEngine.Time.time;
			float endtime = startTime + 4.1f;
			while (UnityEngine.Time.time < endtime)
			{
				yield return null;
			}
			if (base.Tool != null)
			{
				if (base.Tool.ToolCleanup.OverridesActive && base.hasAuthority)
				{
					base.Tool.ToolCleanup.AuthorityQueueForceCleanup();
				}
				else if (PhotonNetwork.isMasterClient)
				{
					if (destroyAfterDestruction)
					{
						PhotonNetwork.GetOwnershipAndDestroy(base.gameObject);
					}
					else
					{
						base.Tool.MasterDisableAndMoveToLastSpawnPosition();
					}
				}
			}
			durabilityDelayedDestructionCoroutine = null;
		}

		private void PlayMeleeWeaponChunkDestructionHaptics()
		{
			if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal)
			{
				base.Tool.HolderHand.Vibrate(1000);
			}
		}

		private void CheckIfDestroyAfterDestruction()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.DestroyBrokenEquipment)
			{
				destroyAfterDestruction = true;
			}
			else
			{
				destroyAfterDestruction = false;
			}
		}

		private bool IsThrow()
		{
			return !base.Tool.IsHeld && supportsThrowDamage;
		}

		protected override void OnRigidbodySleepChange(RigidbodyEx toolRigidbody)
		{
			base.OnRigidbodySleepChange(toolRigidbody);
			if (!base.Tool.IsHeld && supportsThrowDamage && base.Tool.RigidbodyEx.IsSleeping())
			{
				UpdateMeleeColliderCollisonEnabled(collisionEnabled: false);
			}
		}

		private void InitializeMeleeWeaponColliders()
		{
			meleeColliders = GetComponentsInChildren<MeleeWeaponCollider>(includeInactive: true);
			bool flag = base.Tool != null;
			for (int i = 0; i < meleeColliders.Length; i++)
			{
				MeleeWeaponCollider meleeWeaponCollider = meleeColliders[i];
				if (flag)
				{
					meleeWeaponCollider.AddIgnoredRigidbody(base.Tool.RigidbodyEx.UnityRigidbody);
					if (base.Tool.IsSubTool)
					{
						meleeWeaponCollider.AddIgnoredRigidbody(base.Tool.ParentTool.RigidbodyEx.UnityRigidbody);
					}
				}
				meleeWeaponCollider.SupportsStationaryCollisionTests = supportsStationaryCollisionTests;
				meleeWeaponCollider.PlayerImpactEvent += OnMeleeColliderPlayerImpact;
				meleeWeaponCollider.EnemyImpactEvent += OnMeleeColliderEnemyImpact;
				meleeWeaponCollider.ToolImpactEvent += OnMeleeColliderToolImpact;
				meleeWeaponCollider.TrapImpactEvent += OnMeleeColliderTrapImpact;
				meleeWeaponCollider.OtherImpactEvent += OnMeleeColliderOtherImpact;
			}
		}

		private void CleanupMeleeWeaponColliders()
		{
			for (int i = 0; i < meleeColliders.Length; i++)
			{
				MeleeWeaponCollider meleeWeaponCollider = meleeColliders[i];
				meleeWeaponCollider.PlayerImpactEvent -= OnMeleeColliderPlayerImpact;
				meleeWeaponCollider.EnemyImpactEvent -= OnMeleeColliderEnemyImpact;
				meleeWeaponCollider.ToolImpactEvent -= OnMeleeColliderToolImpact;
				meleeWeaponCollider.TrapImpactEvent -= OnMeleeColliderTrapImpact;
				meleeWeaponCollider.OtherImpactEvent -= OnMeleeColliderOtherImpact;
			}
		}

		private void UpdateMeleeColliderCollisonEnabled(bool collisionEnabled)
		{
			for (int i = 0; i < meleeColliders.Length; i++)
			{
				meleeColliders[i].enabled = collisionEnabled;
			}
			UpdateDestructibleChunkMeleeCollision();
			base.enabled = collisionEnabled;
		}

		private void UpdateCenterOfMass(bool forceReset = false)
		{
			if (!base.Tool.IsHeld || forceReset)
			{
				base.Tool.RigidbodyEx.UnityRigidbody.ResetCenterOfMass();
			}
			else
			{
				base.Tool.RigidbodyEx.localCenterOfMass = base.Tool.HolderInfo.RelativePosition;
			}
		}

		private void OnCollisionEnter(Collision collision)
		{
			RunCustomCollisionResolution(collision);
		}

		private void OnCollisionStay(Collision collision)
		{
			RunCustomCollisionResolution(collision);
		}

		private void OnCollisionExit(Collision collision)
		{
			RunCustomCollisionResolution(collision);
		}

		private void RunCustomCollisionResolution(Collision collision)
		{
			if (!base.hasAuthority || !base.Tool.IsHeld)
			{
				return;
			}
			if (collision.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics))
			{
				Player.BodyPart bodyPart;
				Player colliderPlayer = collision.GetColliderPlayer(out bodyPart);
				if (colliderPlayer != null)
				{
					return;
				}
			}
			if (collision.gameObject.IsInLayerMask(LayerMasks.EnemyPhysics))
			{
				EnemyArmorType hitEnemyArmorType;
				Enemy colliderEnemy = collision.GetColliderEnemy(out hitEnemyArmorType);
				if (colliderEnemy != null)
				{
					RunEnemyCustomCollisionResolution(colliderEnemy, collision);
					return;
				}
			}
			if (!collision.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics))
			{
				return;
			}
			Tool colliderTool = collision.GetColliderTool();
			if (colliderTool != null)
			{
				RunToolCustomCollisionResolution(colliderTool);
				return;
			}
			Trap colliderTrap = collision.GetColliderTrap();
			if (colliderTrap != null)
			{
				RunTrapCustomCollisionResolution(colliderTrap);
			}
		}

		private Hit GetEnemyHit(Enemy target)
		{
			return GetHit(target, enemyHits);
		}

		private Hit GetToolHit(Tool target)
		{
			return GetHit(target, toolHits);
		}

		private Hit GetTrapHit(Trap target)
		{
			return GetHit(target, trapHits);
		}

		private Hit GetPlayerHit(Player target)
		{
			return GetHit(target, playerHits);
		}

		private Hit GetHit(UnityEngine.Object target, List<Hit> allHits)
		{
			for (int i = 0; i < allHits.Count; i++)
			{
				if (allHits[i].Target == target)
				{
					return allHits[i];
				}
			}
			return null;
		}

		private void UpdateHits()
		{
			UpdateEnemyHits();
			UpdatePlayerHits();
			UpdateToolHits();
			UpdateTrapHits();
		}

		private void UpdateEnemyHits()
		{
			if (enemyHits.Count <= 0)
			{
				return;
			}
			hitsToClear.Clear();
			for (int i = 0; i < enemyHits.Count; i++)
			{
				Hit hit = enemyHits[i];
				if (hit.StillColliding)
				{
					Enemy enemy = (Enemy)hit.Target;
					if (enemy != null && enemy.hasAuthority)
					{
						EnemyArmorType armorType = (EnemyArmorType)hit.Tag;
						enemy.AuthorityOnDamageChangeVelocity(hit.DamageType, armorType, hit.LinearVelocity, hit.AngularVelocity);
					}
				}
				if (hit.HasExpired(attackCount))
				{
					hitsToClear.Add(hit);
				}
			}
			for (int j = 0; j < hitsToClear.Count; j++)
			{
				Enemy enemy2 = (Enemy)hitsToClear[j].Target;
				if (enemy2 != null)
				{
					ReEnableEnemyCollision(enemy2);
				}
				enemyHits.Remove(hitsToClear[j]);
			}
		}

		private void UpdatePlayerHits()
		{
			if (playerHits.Count <= 0)
			{
				return;
			}
			hitsToClear.Clear();
			for (int i = 0; i < playerHits.Count; i++)
			{
				Hit hit = playerHits[i];
				if (hit.HasExpired(attackCount))
				{
					hitsToClear.Add(hit);
				}
			}
			for (int j = 0; j < hitsToClear.Count; j++)
			{
				playerHits.Remove(hitsToClear[j]);
			}
		}

		private void UpdateToolHits()
		{
			if (toolHits.Count <= 0)
			{
				return;
			}
			hitsToClear.Clear();
			for (int i = 0; i < toolHits.Count; i++)
			{
				Hit hit = toolHits[i];
				if (hit.StillColliding)
				{
					Tool tool = (Tool)hit.Target;
					if (tool != null && tool.hasAuthority)
					{
						tool.AuthorityChangeVelocity(hit.LinearVelocity, hit.AngularVelocity);
					}
				}
				if (hit.HasExpired(attackCount))
				{
					hitsToClear.Add(hit);
				}
			}
			for (int j = 0; j < hitsToClear.Count; j++)
			{
				Tool tool2 = (Tool)hitsToClear[j].Target;
				if (tool2 != null)
				{
					ReEnableToolCollision(tool2);
				}
				toolHits.Remove(hitsToClear[j]);
			}
		}

		private void UpdateTrapHits()
		{
			if (trapHits.Count <= 0)
			{
				return;
			}
			hitsToClear.Clear();
			for (int i = 0; i < trapHits.Count; i++)
			{
				Hit hit = trapHits[i];
				if (hit.StillColliding)
				{
					Trap trap = (Trap)hit.Target;
					if (trap != null && trap.hasAuthority)
					{
						trap.AuthorityOnDamageChangeVelocity(DamageType, hit.LinearVelocity, hit.AngularVelocity);
					}
				}
				if (hit.HasExpired(attackCount))
				{
					hitsToClear.Add(hit);
				}
			}
			for (int j = 0; j < hitsToClear.Count; j++)
			{
				trapHits.Remove(hitsToClear[j]);
			}
		}

		private void AddEnemyHit(Enemy enemy, EnemyArmorType armorType, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			enemyHits.Add(new Hit(enemy, (int)armorType, UnityEngine.Time.time, attackCount, DamageType, linearVelocity, angularVelocity));
			if (base.Tool.IsHeld)
			{
				DisableEnemyCollision(enemy);
			}
		}

		private void AddPlayerHit(Player target)
		{
			playerHits.Add(new Hit(target, -1, UnityEngine.Time.time, attackCount, DamageType, Vector3.zero, Vector3.zero));
		}

		private void AddToolHit(Tool tool, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			toolHits.Add(new Hit(tool, -1, UnityEngine.Time.time, attackCount, DamageType, linearVelocity, angularVelocity));
			if (base.Tool.IsHeld)
			{
				DisableToolCollision(tool);
			}
		}

		private void AddTrapHit(Trap trap, Vector3 linearVelocity, Vector3 angularVelocity)
		{
			trapHits.Add(new Hit(trap, -1, UnityEngine.Time.time, attackCount, DamageType, linearVelocity, angularVelocity));
		}

		public override void NotifyWeaponDealtPlayerOnPlayerDamage(Player hitPlayer)
		{
			base.NotifyWeaponDealtPlayerOnPlayerDamage(hitPlayer);
			AuthorityApplyDurabilityDamage(lastPlayerImpact.Velocity, lastPlayerImpact.SurfaceNormal, 1);
		}

		private void OnMeleeColliderPlayerImpact(MeleeWeaponCollider collider, Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if ((!(base.Wielder.Player != null) || !(base.Wielder.Player == hitPlayer)) && GetPlayerHit(hitPlayer) == null)
			{
				if (IsSwing())
				{
					OnSwingPlayerHit(hitPlayer, hitBodyPart, impact);
				}
				else if (IsThrow() && !alreadyHitOnThrow)
				{
					OnThrowPlayerHit(hitPlayer, hitBodyPart, impact);
				}
			}
		}

		private void OnSwingPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			PlayMeleeImpactHaptics();
			OnPlayerHit(hitPlayer, hitBodyPart, impact);
		}

		private void OnThrowPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (hitPlayer.isLocal && !base.hasAuthority && base.Tool.AllowedToTakeOwnership)
			{
				base.photonView.TransferOwnership(PhotonNetwork.player);
			}
			if (base.hasAuthority)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					ProcessOnThrowPlayerHit(hitPlayer, hitBodyPart, impact);
				});
			}
		}

		private void ProcessOnThrowPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			if (IsThrow() && GetPlayerHit(hitPlayer) == null)
			{
				alreadyHitOnThrow = true;
				OnPlayerHit(hitPlayer, hitBodyPart, impact);
			}
		}

		private void OnPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
		{
			lastPlayerImpact = impact;
			AddPlayerHit(hitPlayer);
			OnPlayerImpact(hitPlayer, hitBodyPart, impact);
		}

		private void OnMeleeColliderEnemyImpact(MeleeWeaponCollider collider, Enemy hitEnemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			if (!(base.Wielder.Enemy != null) && GetEnemyHit(hitEnemy) == null)
			{
				if (IsSwing())
				{
					OnSwingEnemyHit(hitEnemy, enemyArmorType, impact);
				}
				else if (IsThrow() && !alreadyHitOnThrow)
				{
					OnThrowEnemyHit(hitEnemy, enemyArmorType, impact);
				}
			}
		}

		private void OnSwingEnemyHit(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact)
		{
			PlayMeleeImpactHaptics();
			OnEnemyHit(hitEnemy, hitEnemyArmorType, impact);
		}

		private void OnThrowEnemyHit(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact)
		{
			alreadyHitOnThrow = true;
			OnEnemyHit(hitEnemy, hitEnemyArmorType, impact);
		}

		private void OnEnemyHit(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact)
		{
			float normalizedWeaponSpeed = (impact.PreAttackChargeAmount = GetMeleeImpactNormalizedValue());
			Vector3 normalized = impact.Velocity.normalized;
			Vector3 normalized2 = (impact.Point - hitEnemy.RigidbodyEx.worldCenterOfMass).normalized;
			Vector3 normalized3 = Vector3.Cross(normalized2, normalized).normalized;
			float meleeImpactImpulseSpeed = GetMeleeImpactImpulseSpeed(normalizedWeaponSpeed);
			float num = GetMeleeImpactImpulseAngularSpeed(normalizedWeaponSpeed) * ((float)Math.PI / 180f);
			AddEnemyHit(hitEnemy, hitEnemyArmorType, normalized * meleeImpactImpulseSpeed, normalized3 * num);
			if (OnEnemyImpact(hitEnemy, hitEnemyArmorType, impact))
			{
				AuthorityApplyDurabilityDamage(impact.Velocity, impact.SurfaceNormal, 1);
			}
		}

		private void RunEnemyCustomCollisionResolution(Enemy enemy, Collision collision)
		{
			if (!enemy.hasAuthority)
			{
				enemy.TransferOwnership(PhotonNetwork.player);
			}
			Hit enemyHit = GetEnemyHit(enemy);
			if (enemyHit != null)
			{
				EnemyArmorType armorType = (EnemyArmorType)enemyHit.Tag;
				enemy.AuthorityOnDamageChangeVelocity(enemyHit.DamageType, armorType, enemyHit.LinearVelocity, enemyHit.AngularVelocity);
			}
		}

		private void DisableEnemyCollision(Enemy enemy)
		{
			if (!(enemy != null))
			{
				return;
			}
			foreach (ToolCollider collider in base.Tool.Colliders)
			{
				collider.IgnoreCollision(enemy.Colliders, ignore: true);
			}
		}

		private void ReEnableEnemyCollision(Enemy enemy)
		{
			if (!(enemy != null))
			{
				return;
			}
			foreach (ToolCollider collider in base.Tool.Colliders)
			{
				collider.IgnoreCollision(enemy.Colliders, ignore: false);
			}
		}

		private void OnMeleeColliderToolImpact(MeleeWeaponCollider collider, Tool hitTool, WeaponImpact impact)
		{
			if (!(hitTool == base.Tool) && (!hitTool.IsHeld || !base.Tool.IsHeld || !(hitTool.HolderPlayer == base.Tool.HolderPlayer)) && GetToolHit(hitTool) == null)
			{
				if (IsSwing())
				{
					OnSwingToolHit(hitTool, impact);
				}
				else if (IsThrow() && !alreadyHitOnThrow)
				{
					OnThrowToolHit(hitTool, impact);
				}
			}
		}

		private void OnSwingToolHit(Tool hitTool, WeaponImpact impact)
		{
			PlayMeleeImpactHaptics();
			OnToolHit(hitTool, impact);
		}

		private void OnThrowToolHit(Tool hitTool, WeaponImpact impact)
		{
			alreadyHitOnThrow = true;
			OnToolHit(hitTool, impact);
		}

		private void OnToolHit(Tool hitTool, WeaponImpact impact)
		{
			float normalizedWeaponSpeed = (impact.PreAttackChargeAmount = GetMeleeImpactNormalizedValue());
			Vector3 normalized = impact.Velocity.normalized;
			Vector3 normalized2 = (impact.Point - hitTool.RigidbodyEx.worldCenterOfMass).normalized;
			Vector3 normalized3 = Vector3.Cross(normalized2, normalized).normalized;
			float meleeImpactImpulseSpeed = GetMeleeImpactImpulseSpeed(normalizedWeaponSpeed);
			float num = GetMeleeImpactImpulseAngularSpeed(normalizedWeaponSpeed) * ((float)Math.PI / 180f);
			AddToolHit(hitTool, normalized * meleeImpactImpulseSpeed, normalized3 * num);
			OnToolImpact(hitTool, impact);
			if (hitTool.IsHeldByPlayer)
			{
				AddPlayerHit(hitTool.HolderPlayer);
			}
		}

		protected override void OnPlayerHeldToolImpact(Tool hitTool, WeaponImpact impact)
		{
			if (GetPlayerHit(hitTool.HolderPlayer) == null)
			{
				base.OnPlayerHeldToolImpact(hitTool, impact);
			}
			else
			{
				OnOtherHit(impact);
			}
		}

		private void RunToolCustomCollisionResolution(Tool hitTool)
		{
			if (base.hasAuthority && hitTool != base.Tool && hitTool.hasAuthority)
			{
				Hit toolHit = GetToolHit(hitTool);
				if (toolHit != null)
				{
					hitTool.AuthorityChangeVelocity(toolHit.LinearVelocity, toolHit.AngularVelocity);
				}
			}
		}

		private void DisableToolCollision(Tool otherTool)
		{
			if (otherTool != null)
			{
				base.Tool.IgnoreCollision(otherTool, ignore: true);
			}
		}

		private void ReEnableToolCollision(Tool otherTool)
		{
			if (otherTool != null)
			{
				base.Tool.IgnoreCollision(otherTool, ignore: false);
			}
		}

		private void OnMeleeColliderTrapImpact(MeleeWeaponCollider collider, Trap hitTrap, WeaponImpact impact)
		{
			if (GetTrapHit(hitTrap) == null)
			{
				if (IsSwing())
				{
					OnSwingTrapHit(hitTrap, impact);
				}
				else if (IsThrow() && !alreadyHitOnThrow)
				{
					OnThrowTrapHit(hitTrap, impact);
				}
			}
		}

		private void OnSwingTrapHit(Trap hitTrap, WeaponImpact impact)
		{
			PlayMeleeImpactHaptics();
			OnTrapHit(hitTrap, impact);
		}

		private void OnThrowTrapHit(Trap hitTrap, WeaponImpact impact)
		{
			alreadyHitOnThrow = true;
			OnTrapHit(hitTrap, impact);
		}

		private void OnTrapHit(Trap hitTrap, WeaponImpact impact)
		{
			float normalizedWeaponSpeed = (impact.PreAttackChargeAmount = GetMeleeImpactNormalizedValue());
			Vector3 normalized = impact.Velocity.normalized;
			Vector3 vector = ((!(hitTrap.RigidbodyEx != null)) ? hitTrap.transform.position : hitTrap.RigidbodyEx.worldCenterOfMass);
			Vector3 normalized2 = (impact.Point - vector).normalized;
			Vector3 normalized3 = Vector3.Cross(normalized2, normalized).normalized;
			float meleeImpactImpulseSpeed = GetMeleeImpactImpulseSpeed(normalizedWeaponSpeed);
			float num = GetMeleeImpactImpulseAngularSpeed(normalizedWeaponSpeed) * ((float)Math.PI / 180f);
			AddTrapHit(hitTrap, normalized * meleeImpactImpulseSpeed, normalized3 * num);
			OnTrapImpact(hitTrap, impact);
		}

		private void RunTrapCustomCollisionResolution(Trap trap)
		{
			if (base.hasAuthority && trap != null)
			{
				if (!trap.hasAuthority)
				{
					trap.photonView.TransferOwnership(PhotonNetwork.player);
				}
				Hit trapHit = GetTrapHit(trap);
				if (trapHit != null)
				{
					trap.AuthorityOnDamageChangeVelocity(DamageType, trapHit.LinearVelocity, trapHit.AngularVelocity);
				}
			}
		}

		private void OnMeleeColliderOtherImpact(MeleeWeaponCollider collider, WeaponImpact impact)
		{
			if (!OtherHitOnCooldown())
			{
				if (IsSwing())
				{
					OnSwingOtherHit(impact);
				}
				else if (IsThrow() && !alreadyHitOnThrow)
				{
					OnThrowOtherHit(impact);
				}
			}
		}

		private void OnSwingOtherHit(WeaponImpact impact)
		{
			PlayMeleeImpactHaptics();
			OnOtherHit(impact);
		}

		private void OnThrowOtherHit(WeaponImpact impact)
		{
			alreadyHitOnThrow = true;
			OnOtherHit(impact);
		}

		private void OnOtherHit(WeaponImpact impact)
		{
			lastOtherHitTime = UnityEngine.Time.time;
			OnOtherImpact(impact);
		}

		private bool OtherHitOnCooldown()
		{
			return UnityEngine.Time.time - lastOtherHitTime <= 0.25f;
		}

		public override int GetPlayerImpactDamage(Player.BodyPart hitBodyPart, float preAttackChargeAmount, bool isSelfDamage)
		{
			int playerImpactDamage = base.GetPlayerImpactDamage(hitBodyPart, preAttackChargeAmount, isSelfDamage);
			return Mathf.RoundToInt(GetDamageMultiplier() * (float)playerImpactDamage);
		}

		public override int GetEnemyDamage(float chargeAmount = 0f)
		{
			int enemyDamage = base.GetEnemyDamage(chargeAmount);
			return Mathf.RoundToInt(GetDamageMultiplier() * (float)enemyDamage);
		}

		private float GetDamageMultiplier()
		{
			float num = 1f;
			if (supportsThrowDamage && IsThrow())
			{
				num *= throwDamageMultiplier;
			}
			if (isDestructible)
			{
				num *= GetRemainingDestructibleChunkDamageMultiplier();
			}
			return num;
		}

		protected float GetMeleeImpactNormalizedValue()
		{
			if (base.Tool.IsHeldByPlayer && base.Tool.HolderHand != null)
			{
				if (CalculateSwingingAutomatically)
				{
					float magnitude = base.Tool.HolderHand.HandOnlyVelocity.magnitude;
					return Mathf.InverseLerp(3f, 5f, magnitude);
				}
				return manualSwingNormalizedSpeed;
			}
			float magnitude2 = base.Tool.RigidbodyEx.velocity.magnitude;
			return Mathf.InverseLerp(1f, 5f, magnitude2);
		}

		protected float GetMeleeImpactImpulseSpeed(float normalizedWeaponSpeed)
		{
			return Mathf.Lerp(minSpeedImpulseSpeed, maxSpeedImpulseSpeed, normalizedWeaponSpeed);
		}

		protected float GetMeleeImpactImpulseAngularSpeed(float normalizedWeaponSpeed)
		{
			return Mathf.Lerp(minSpeedImpulseAngularSpeed, maxSpeedImpulseAngularSpeed, normalizedWeaponSpeed);
		}

		protected Vector3 GetMeleeImpactForce(Vector3 impactVelocity)
		{
			return impactVelocity * base.Tool.RigidbodyEx.mass / UnityEngine.Time.fixedDeltaTime;
		}

		protected void PlayMeleeImpactHaptics(float duration = 0.2f)
		{
			if (base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal)
			{
				base.Tool.HolderHand.Vibrate((int)(duration * 1000f));
			}
		}

		private void InitializeTrails()
		{
			trails = GetComponentsInChildren<DynamicMeshTrail>();
			if (!(base.Tool != null))
			{
				return;
			}
			for (int i = 0; i < trails.Length; i++)
			{
				Renderer[] componentsInChildren = trails[i].GetComponentsInChildren<Renderer>();
				for (int j = 0; j < componentsInChildren.Length; j++)
				{
					base.Tool.TryRemoveRenderer(componentsInChildren[j]);
				}
			}
		}

		private void UpdateTrailOpacity(float targetTrailOpacity)
		{
			float smoothTime = trailFadeInSmoothSpeed;
			if (targetTrailOpacity < trailOpacity)
			{
				smoothTime = trailFadeOutSmoothSpeed;
			}
			trailOpacity = Mathf.SmoothDamp(trailOpacity, targetTrailOpacity, ref trailOpacityVelocity, smoothTime);
			if (trailOpacity > 0f)
			{
				for (int i = 0; i < trails.Length; i++)
				{
					if (!trails[i].enabled)
					{
						trails[i].enabled = true;
					}
					trails[i].Opacity = trailOpacity;
				}
				return;
			}
			for (int j = 0; j < trails.Length; j++)
			{
				if (trails[j].enabled)
				{
					trails[j].enabled = false;
				}
			}
		}

		private void UpdateTrailColor(Color color)
		{
			for (int i = 0; i < trails.Length; i++)
			{
				trails[i].Color = color;
			}
		}

		private void UpdateTrailVisibility(bool isVisible)
		{
			if (trails != null)
			{
				for (int i = 0; i < trails.Length; i++)
				{
					trails[i].enabled = isVisible;
				}
			}
			UpdateDestructibleChunkTrailVisibility();
		}

		[PunRPC]
		private void RpcOnChunkDestruction(int chunkIndex, Vector3 breakPoint, Vector3 chunkVelocity, bool lastChunk)
		{
			RemoteOnChunkDestruction(chunkIndex, breakPoint, chunkVelocity, lastChunk);
		}

		void ICustomImposterBehavior.PrepareImposter(ImposterParameters parameters)
		{
			if (!isDestructible)
			{
				return;
			}
			for (int i = 0; i < destructibleChunks.Length; i++)
			{
				foreach (MeleeWeaponChunk.DurabilityGameObject durabilityGameObject in destructibleChunks[i].DurabilityGameObjects)
				{
					if (i < 0 || durabilityGameObject.MinimumVisibilityDamage > 0)
					{
						UnityEngine.Object.DestroyImmediate(durabilityGameObject.GameObject);
					}
				}
			}
		}
	}
	[Serializable]
	public class MeleeWeaponChunk
	{
		[Serializable]
		public struct DurabilityGameObject
		{
			public GameObject GameObject;

			public int MinimumVisibilityDamage;

			public int MaximumVisibilityDamage;
		}

		[Header("Config")]
		[SerializeField]
		private int durability;

		[SerializeField]
		private float weaponAttackContribution;

		[Header("References")]
		[SerializeField]
		private Transform origin;

		[SerializeField]
		private DurabilityGameObject[] durabilityGameObjects;

		[SerializeField]
		private RagdollPiece[] ragdollPieces;

		[SerializeField]
		private MeleeWeaponCollider[] meleeColliders;

		[SerializeField]
		private DynamicMeshTrail[] trails;

		private Weapon weapon;

		private bool isShattered;

		private bool _isEnabled = true;

		public Vector3 OriginPosition
		{
			get
			{
				if (origin != null)
				{
					return origin.position;
				}
				if (weapon != null)
				{
					return weapon.transform.position;
				}
				return Vector3.zero;
			}
		}

		public int Durability => durability;

		public IEnumerable<DurabilityGameObject> DurabilityGameObjects => durabilityGameObjects;

		public float WeaponAttackContribution => weaponAttackContribution;

		public int DurabilityDamageTaken
		{
			set
			{
				UpdateDurabilityGameObjects(value);
			}
		}

		public bool IsEnabled
		{
			get
			{
				return _isEnabled;
			}
			set
			{
				_isEnabled = value;
				UpdateMeleeCollisionEnabled();
				UpdateTrailVisibility();
				if (value)
				{
					ResetShatter();
				}
				else
				{
					DisableAllRagdollPieces();
				}
			}
		}

		public void Initialize(MeleeWeapon weapon)
		{
			this.weapon = weapon;
			isShattered = false;
			DurabilityDamageTaken = 0;
		}

		public void Shatter(Vector3 initialVelocity, float shatterSpeed)
		{
			isShattered = true;
			for (int i = 0; i < ragdollPieces.Length; i++)
			{
				ragdollPieces[i].gameObject.SetActive(value: true);
				ragdollPieces[i].StartRagdoll(initialVelocity, OriginPosition, shatterSpeed);
			}
		}

		public void UpdateMeleeCollisionEnabled()
		{
			for (int i = 0; i < meleeColliders.Length; i++)
			{
				meleeColliders[i].enabled &= IsEnabled;
			}
		}

		public void UpdateTrailVisibility()
		{
			for (int i = 0; i < trails.Length; i++)
			{
				trails[i].enabled &= IsEnabled;
			}
		}

		private void DisableAllRagdollPieces()
		{
			if (!isShattered)
			{
				for (int i = 0; i < ragdollPieces.Length; i++)
				{
					ragdollPieces[i].gameObject.SetActive(value: false);
				}
			}
		}

		private void ResetShatter()
		{
			isShattered = false;
			for (int i = 0; i < ragdollPieces.Length; i++)
			{
				ragdollPieces[i].gameObject.SetActive(value: true);
				ragdollPieces[i].StopRagdoll();
			}
		}

		private void UpdateDurabilityGameObjects(int damageTaken)
		{
			if (durabilityGameObjects != null)
			{
				for (int i = 0; i < durabilityGameObjects.Length; i++)
				{
					durabilityGameObjects[i].GameObject.SetActive(damageTaken >= durabilityGameObjects[i].MinimumVisibilityDamage && damageTaken <= durabilityGameObjects[i].MaximumVisibilityDamage);
				}
			}
		}
	}
}
