	private void Start()
	{
		previousPosition = base.transform.position;
		cachedLayerMask = 0;
		if (includedLayers != null)
		{
			for (int i = 0; i < includedLayers.Length; i++)
			{
				cachedLayerMask |= (int)includedLayers[i];
			}
		}
		if (excludedLayers != null)
		{
			for (int j = 0; j < excludedLayers.Length; j++)
			{
				cachedLayerMask &= (int)(~excludedLayers[j]);
			}
		}
	}

	private void OnEnable()
	{
		previousPosition = base.transform.position;
	}

	public void AddIgnoredRigidbody(Rigidbody rigidbody)
	{
		if (!ignoredRigidbodies.Contains(rigidbody))
		{
			ignoredRigidbodies.Add(rigidbody);
		}
	}

	private void FixedUpdate()
	{
		Vector3 velocity = (base.transform.position - previousPosition) / UnityEngine.Time.fixedDeltaTime;
		int hitCount = raycastCollider.RunAllMovingCollisions(previousPosition, base.transform.position, radius, cachedLayerMask, ignoredRigidbodies, null, ref hits);
		if (!RunCollisionResponse(hitCount, velocity) && SupportsStationaryCollisionTests)
		{
			hitCount = raycastCollider.RunAllStationaryCollisions(base.transform.position, radius, ignoredRigidbodies, null, ref hits);
			RunCollisionResponse(hitCount, velocity);
		}
		previousPosition = base.transform.position;
	}

	private bool RunCollisionResponse(int hitCount, Vector3 velocity)
	{
		bool result = false;
		for (int i = 0; i < hitCount; i++)
		{
			if (!(hits[i].Distance <= 0f))
			{
				result = true;
				WeaponImpact impact = new WeaponImpact
				{
					Velocity = velocity,
					Force = Vector3.zero,
					GameObject = hits[i].Collider.gameObject,
					Point = hits[i].Point,
					Distance = 0f,
					SurfaceNormal = hits[i].Normal,
					PreAttackChargeAmount = 0f
				};
				Player player = null;
				Enemy enemy = null;
				Tool tool = null;
				Trap trap = null;
				EnemyArmorType hitEnemyArmorType;
				if ((player = hits[i].Collider.GetColliderPlayer(out var bodyPart)) != null)
				{
					OnPlayerHit(player, bodyPart, impact);
				}
				else if ((enemy = hits[i].Collider.GetColliderEnemy(out hitEnemyArmorType)) != null)
				{
					OnEnemyHit(enemy, hitEnemyArmorType, impact);
				}
				else if ((tool = hits[i].Collider.GetColliderTool()) != null)
				{
					OnToolHit(tool, impact);
				}
				else if ((trap = hits[i].Collider.GetColliderTrap()) != null)
				{
					OnTrapHit(trap, impact);
				}
				else
				{
					OnOtherHit(impact);
				}
				if (this.AnyImpactEvent != null)
				{
					this.AnyImpactEvent(this, impact);
				}
			}
		}
		return result;
	}

	private void OnPlayerHit(Player hitPlayer, Player.BodyPart hitBodyPart, WeaponImpact impact)
	{
		if (this.PlayerImpactEvent != null)
		{
			this.PlayerImpactEvent(this, hitPlayer, hitBodyPart, impact);
		}
	}

	private void OnEnemyHit(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact)
	{
		if (this.EnemyImpactEvent != null)
		{
			this.EnemyImpactEvent(this, hitEnemy, hitEnemyArmorType, impact);
		}
	}

	private void OnToolHit(Tool tool, WeaponImpact impact)
	{
		if (this.ToolImpactEvent != null)
		{
			this.ToolImpactEvent(this, tool, impact);
		}
	}

	private void OnTrapHit(Trap trap, WeaponImpact impact)
	{
		if (this.TrapImpactEvent != null)
		{
			this.TrapImpactEvent(this, trap, impact);
		}
	}

	private void OnOtherHit(WeaponImpact impact)
	{
		if (this.OtherImpactEvent != null)
		{
			this.OtherImpactEvent(this, impact);
		}
	}

	private void OnDrawGizmosSelected()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawWireSphere(base.transform.position, radius);
	}
}
public class PersistentBulletTrail : BulletTrail
{
	[SerializeField]
	private AnimationCurve alphaFadeOutCurve;

	[SerializeField]
	private AnimationCurve widthFadeOutCurve;

	[SerializeField]
	private float finalWidthScale = 4f;

	private float startTime;

	public float FinalWidthScale { get; set; }

	protected override void Awake()
	{
		base.Awake();
		FinalWidthScale = finalWidthScale;
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		fadeAlpha = 1f;
		Color = Color;
		widthScale = 1f;
		Widths = Widths;
		startTime = UnityEngine.Time.time;
	}

	protected override void Update()
	{
		base.Update();
		float time = Mathf.InverseLerp(startTime, startTime + base.Lifetime, UnityEngine.Time.time);
		fadeAlpha = Mathf.Lerp(1f, 0f, alphaFadeOutCurve.Evaluate(time));
		Color = Color;
		widthScale = Mathf.Lerp(1f, FinalWidthScale, widthFadeOutCurve.Evaluate(time));
		Widths = Widths;
	}
}
namespace RecRoom.Core.Combat
{
	public abstract class RangedWeapon : Weapon
