		public bool IsOnCooldown => maximumFiringRate == 0f || TimeSinceLastFire <= 1f / maximumFiringRate;

		public bool IsMisfire
		{
			get
			{
				if (IsOutOfBounds)
				{
					return true;
				}
				if (base.Trap != null)
				{
					return false;
				}
				if (!base.Tool.IsHeld || base.Tool.HolderPlayer == null)
				{
					return false;
				}
				if (base.Tool.HolderPlayer.IsOutOfWorldBounds || base.Tool.HolderPlayer.IsOverlappingWorld)
				{
					return true;
				}
				return false;
			}
		}

		public Vector3 AimOrigin => barrelTransform.position;

		public Vector3 AimDirection
		{
			get
			{
				Vector3 result = barrelTransform.forward;
				if (HasOverridenTargetPoint)
				{
					result = (OverrideTargetPoint - AimOrigin).normalized;
				}
				return result;
			}
		}

		protected float TimeSinceLastFire => UnityEngine.Time.time - lastFireTime;

		private bool IsOutOfBounds
		{
			get
			{
				if (IsOverlappingWorld())
				{
					return true;
				}
				if (GameSessions.LocalGameSession != null && !GameSessions.LocalGameSession.IsSandbox && !ActivityBounds.PointInBounds(base.transform.position))
				{
					return true;
				}
				return false;
			}
