					rangedWeaponAction = Interlocked.CompareExchange(ref RangedWeapon.m_LocalPlayerStaticFireEvent, (RangedWeaponAction)Delegate.Remove(rangedWeaponAction2, value), rangedWeaponAction);
				}
				while (rangedWeaponAction != rangedWeaponAction2);
			}
		}

		public event RangedWeaponAction LocalPlayerFireEvent
		{
			add
			{
				RangedWeaponAction rangedWeaponAction = this.m_LocalPlayerFireEvent;
				RangedWeaponAction rangedWeaponAction2;
				do
				{
					rangedWeaponAction2 = rangedWeaponAction;
					rangedWeaponAction = Interlocked.CompareExchange(ref this.m_LocalPlayerFireEvent, (RangedWeaponAction)Delegate.Combine(rangedWeaponAction2, value), rangedWeaponAction);
				}
				while (rangedWeaponAction != rangedWeaponAction2);
			}
			remove
			{
				RangedWeaponAction rangedWeaponAction = this.m_LocalPlayerFireEvent;
				RangedWeaponAction rangedWeaponAction2;
				do
				{
					rangedWeaponAction2 = rangedWeaponAction;
					rangedWeaponAction = Interlocked.CompareExchange(ref this.m_LocalPlayerFireEvent, (RangedWeaponAction)Delegate.Remove(rangedWeaponAction2, value), rangedWeaponAction);
				}
				while (rangedWeaponAction != rangedWeaponAction2);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			if (barrelTransform == null)
			{
				barrelTransform = base.transform;
			}
			if (frontSightTransform != null && rearSightTransform != null)
			{
				Vector3 vector = base.transform.InverseTransformVector(barrelTransform.forward);
				Vector3 vector2 = base.transform.InverseTransformVector(barrelTransform.up);
				Vector3 vector3 = Vector3.Project(barrelTransform.localPosition - frontSightTransform.localPosition, vector2);
				Vector3 vector4 = barrelTransform.localPosition + vector * sightAccuracyDistance;
				Vector3 vector5 = frontSightTransform.localPosition + vector3;
				Vector3 vector6 = vector4 - vector5;
				Vector3 vector7 = Vector3.Project(rearSightTransform.localPosition, vector) + Vector3.Project(barrelTransform.localPosition, vector2);
				float num = (vector4 - vector7).magnitude * vector3.magnitude / vector6.magnitude;
				rearSightTransform.localPosition = vector7 + vector2 * num;
			}
		}

		public void SetConfigurationData(RangedWeaponData configurationData)
		{
			if (configurationData.AmmoMagazineCapacity > 0)
			{
				supportsAmmunition = true;
				ammunitionMagazineSize = configurationData.AmmoMagazineCapacity;
				defaultMagazineAmmunition = ammunitionMagazineSize;
				if (configurationData.AmmoTotalCapacity > 0)
				{
					hasInfiniteReserveAmmunition = false;
					maximumTotalAmmunition = configurationData.AmmoTotalCapacity;
				}
				else
				{
					hasInfiniteReserveAmmunition = true;
				}
				disablePostTotalAmmunitionExhaustion = configurationData.ResetOnTotalAmmoExhaustion;
				if (!configurationData.ResetOnTotalAmmoExhaustion)
				{
					disarmOnTotalAmmunitionExhaustion = false;
				}
				ResetAmmunition();
			}
			else
			{
				supportsAmmunition = false;
			}
			maximumFiringRate = configurationData.RateOfFire;
			maximumAutomaticFiringRate = configurationData.AutomaticRateOfFire;
			bulletFireSpeed = configurationData.MaxProjectileSpeed;
			for (int i = 0; i < playerDamageSettings.Length; i++)
			{
				float num = ((playerDamageSettings[i].BodyPart != Player.BodyPart.Head) ? 1f : configurationData.CriticalHitDamageMultiplier);
				ref PlayerDamageSetting reference = ref playerDamageSettings[i];
				reference = new PlayerDamageSetting
				{
					BodyPart = playerDamageSettings[i].BodyPart,
					Damage = Mathf.RoundToInt(configurationData.ProjectileDamage * num)
				};
			}
		}

		public virtual void Fire(float chargeAmount = 1f)
		{
			Fire(AimDirection * bulletFireSpeed, chargeAmount);
		}

		public virtual void Fire(Vector3 velocity, float chargeAmount = 1f)
		{
			if (base.SupportsAmmunition)
			{
				if (automaticallyReloadMagazine && base.MagazineAmmunition <= 0)
				{
					ReloadAmmunition();
				}
				DecrementAmmunition();
			}
			if (playHapticsOnFire && base.Tool.IsHeldByPlayer && base.Tool.HolderHand.isLocal)
			{
				base.Tool.HolderHand.Vibrate(20, 0.5f);
			}
			if (base.Tool.Owner != null && base.Tool.Owner.isLocal)
			{
				if (RangedWeapon.LocalPlayerStaticFireEvent != null)
				{
					RangedWeapon.LocalPlayerStaticFireEvent(this);
				}
				if (this.LocalPlayerFireEvent != null)
				{
					this.LocalPlayerFireEvent(this);
				}
			}
			lastFireTime = UnityEngine.Time.time;
			base.photonView.RpcAll(RpcFireShot, barrelTransform.position, barrelTransform.rotation, velocity, chargeAmount, IsMisfire, ShotId++);
		}

		protected virtual void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			if (isMisfire)
			{
				base.WeaponAudio.OnMisfire();
				return;
			}
			if (hasRecoilAnimation)
			{
				SetAnimationTrigger(recoilId);
			}
			if (chargeAmount >= 1f)
			{
				base.WeaponAudio.OnFireHard();
			}
			else
			{
				base.WeaponAudio.OnFireSoft();
			}
			if (muzzleFlashPrefab != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(muzzleFlashPrefab);
				if (pooledParticle != null)
				{
					if (overrideMuzzleFlashParticleStartColor)
					{
						pooledParticle.SetColor(WeaponColor);
					}
					pooledParticle.Play(muzzleFlashOrigin);
				}
			}
			if (hasReloadEffect)
			{
				PlayDelayedReload();
			}
		}

		protected virtual void FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			Bullet bullet = AcquireBullet(prefab);
			if (bullet != null)
			{
				bullet.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, shotId, overrideAndDisableGravity);
			}
		}

		protected virtual Bullet FireBullet(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, float maxLifetime, byte shotId, bool overrideAndDisableGravity = false, WeaponRaycastCollider.CollisionFilter collisionFilter = null, Bullet prefab = null)
		{
			Bullet bullet = AcquireBullet(prefab);
			if (bullet != null)
			{
				bullet.Fire(position, rotation, velocity, bulletImpactForce.GetImpactForce(chargeAmount), chargeAmount, AllRigidbodies, collisionFilter, maxLifetime, shotId, overrideAndDisableGravity);
			}
			return bullet;
		}

		protected virtual Bullet AcquireBullet(Bullet prefab = null)
		{
			if (prefab == null)
			{
				prefab = bulletPrefab;
			}
			Bullet bullet = null;
			if (prefab != null)
			{
				bullet = ObjectPool.Instance.Acquire(prefab);
				if (bullet != null)
				{
					bullet.DestroyEvent += OnBulletDestroy;
					bullet.PlayerImpactEvent += OnBulletPlayerImpact;
					bullet.EnemyImpactEvent += OnBulletEnemyImpact;
					bullet.ToolImpactEvent += OnBulletToolImpact;
					bullet.TrapImpactEvent += OnBulletTrapImpact;
					bullet.OtherImpactEvent += OnBulletOtherImpact;
					bullet.Color = WeaponColor;
				}
			}
			return bullet;
		}

		private void OnBulletDestroy(Bullet bullet)
		{
			bullet.DestroyEvent -= OnBulletDestroy;
			bullet.PlayerImpactEvent -= OnBulletPlayerImpact;
			bullet.EnemyImpactEvent -= OnBulletEnemyImpact;
			bullet.ToolImpactEvent -= OnBulletToolImpact;
			bullet.TrapImpactEvent -= OnBulletTrapImpact;
			bullet.OtherImpactEvent -= OnBulletOtherImpact;
			OnBulletDestroyed(bullet, bullet.transform.position);
		}

		protected virtual void OnBulletDestroyed(Bullet bullet, Vector3 position)
		{
		}

		protected virtual void OnBulletPlayerImpact(Bullet bullet, Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
			OnPlayerImpact(player, bodyPart, impact);
		}

		protected virtual void OnBulletEnemyImpact(Bullet bullet, Enemy enemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			OnEnemyImpact(enemy, enemyArmorType, impact);
			if (base.hasAuthority && enemy.hasAuthority)
			{
				enemy.AuthorityOnDamageApplyForce(DamageType, enemyArmorType, impact.Force, impact.Point);
			}
		}

		protected virtual void OnBulletToolImpact(Bullet bullet, Tool hitTool, WeaponImpact impact)
		{
			OnToolImpact(hitTool, impact);
			if (base.hasAuthority && hitTool.hasAuthority)
			{
				hitTool.AuthorityApplyForce(impact.Force, impact.Point, ForceMode.Impulse);
			}
		}

		protected virtual void OnBulletTrapImpact(Bullet bullet, Trap trap, WeaponImpact impact)
		{
			OnTrapImpact(trap, impact);
			if (base.hasAuthority && trap.hasAuthority)
			{
				trap.AuthorityOnDamageApplyForce(DamageType, impact.Force, impact.Point);
			}
		}

		protected virtual void OnBulletOtherImpact(Bullet bullet, WeaponImpact impact)
		{
			OnOtherImpact(impact);
		}

		private void PlayDelayedReload()
		{
			StopDelayedReload();
			delayedPumpCoroutine = StartCoroutine(PlayDelayedReloadCoroutine());
		}

		private void StopDelayedReload()
		{
			if (delayedPumpCoroutine != null)
			{
				StopCoroutine(delayedPumpCoroutine);
			}
		}

		private IEnumerator PlayDelayedReloadCoroutine()
		{
			yield return new WaitForSeconds(reloadDelay);
			base.WeaponAudio.OnReload();
			SetAnimationTrigger(reloadId);
			delayedPumpCoroutine = null;
		}

		public override void TryPlayOutOfAmmoFeedback()
		{
			base.TryPlayOutOfAmmoFeedback();
			if (hasOutOfAmmoFireAnimation && base.TotalAmmunition == 0 && !base.HasInfiniteReserveAmmunition)
			{
				SetAnimationTrigger(fireFailId);
			}
		}

		protected override void OnAmmunitionChange()
		{
			base.OnAmmunitionChange();
			if (hasAmmunitionStateVisuals)
			{
				bool flag = base.TotalAmmunition != 0 || base.HasInfiniteReserveAmmunition;
				hasAmmunitionRemainingVisualRoot.SetActive(flag);
				outOfAmmoVisualRoot.SetActive(!flag);
			}
		}

		protected bool IsOverlappingWorld()
		{
			bool flag = false;
			if (worldOverlapCollider != null)
			{
				flag = worldOverlapCollider.CheckOverlap(2048, QueryTriggerInteraction.Ignore);
				if (!flag)
				{
					int overlapNonAlloc = worldOverlapCollider.GetOverlapNonAlloc(495330304, QueryTriggerInteraction.Ignore, overlapHitResults);
					for (int i = 0; i < overlapNonAlloc; i++)
					{
						Tool colliderTool = overlapHitResults[i].GetColliderTool();
						if (colliderTool != null && colliderTool != this && colliderTool.SupportsToolOverlap)
						{
							flag = true;
							break;
						}
					}
				}
			}
			return flag;
		}

		[PunRPC]
		protected void RpcFireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool misFire, byte shotId)
		{
			FireShot(position, rotation, velocity, chargeAmount, IsMisfire, shotId);
		}

		static RangedWeapon()
		{
			RangedWeapon.LocalPlayerStaticFireEvent = null;
			overlapHitResults = new Collider[10];
		}
	}
	public class RangedWeaponFlipReload : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private RangedWeapon rangedWeapon;

		[SerializeField]
		private float minFlipAngle = 270f;

		private bool trackingFlipReload;

		private Quaternion previousRotation = Quaternion.identity;

		private float totalFlipReloadAngle;

		private float lastToolReleaseTime;

		private Vector3 lastToolReleasePosition = Vector3.zero;

		private void Awake()
		{
			rangedWeapon.Tool.PostPickupEvent += OnWeaponPostPickup;
			rangedWeapon.Tool.PostReleaseEvent += OnWeaponPostRelease;
		}

		private void OnDestroy()
		{
			rangedWeapon.Tool.PostPickupEvent -= OnWeaponPostPickup;
			rangedWeapon.Tool.PostReleaseEvent -= OnWeaponPostRelease;
		}

		private void OnWeaponPostPickup(Tool tool)
		{
			trackingFlipReload = false;
		}

		private void OnWeaponPostRelease(Tool tool)
		{
			trackingFlipReload = true;
			lastToolReleaseTime = UnityEngine.Time.unscaledTime;
			lastToolReleasePosition = base.transform.position;
			totalFlipReloadAngle = 0f;
		}

		private void FixedUpdate()
		{
			if (rangedWeapon.hasAuthority && trackingFlipReload)
			{
				totalFlipReloadAngle += Quaternion.Angle(base.transform.rotation, previousRotation);
				if (totalFlipReloadAngle >= minFlipAngle)
				{
					rangedWeapon.ReloadAmmunition();
					trackingFlipReload = false;
				}
				else if (UnityEngine.Time.unscaledTime - lastToolReleaseTime > 3f || lastToolReleasePosition.y - base.transform.position.y >= 0.1f)
				{
					trackingFlipReload = false;
				}
			}
			previousRotation = base.transform.rotation;
		}
	}
}
namespace RecRoom.Tools.Weapons
{
	public class SpreadRangedWeapon : RangedWeapon
	{
		[Serializable]
		protected class SpreadTarget
		{
			public Transform Start;

			public Transform End;

			public Bullet bulletOverride;

			public float minCharge;
		}

		[Header("Spread")]
		[SerializeField]
		protected float maxDistance = 3f;

		[SerializeField]
		[FormerlySerializedAs("sprayTargetEndRoot")]
		protected Transform spreadTargetEndRoot;

		[SerializeField]
		[FormerlySerializedAs("sprayTargets")]
		protected SpreadTarget[] spreadTargets;

		[Header("Bullet Tracking")]
		[SerializeField]
		protected bool trackBulletGroups;

		[SerializeField]
		protected bool limitOneImpactPerTarget;

		protected BulletGroupTracker bulletTracker;

		protected override void Awake()
		{
			base.Awake();
			if (trackBulletGroups)
			{
				bulletTracker = new BulletGroupTracker(spreadTargets.Length, limitOneImpactPerTarget);
			}
			for (int i = 0; i < spreadTargets.Length; i++)
			{
				if (spreadTargets[i].End != null && spreadTargets[i].End.transform.parent != spreadTargetEndRoot)
				{
					spreadTargets[i].End.transform.SetParent(spreadTargetEndRoot, worldPositionStays: true);
				}
			}
		}

		protected override void FireShot(Vector3 position, Quaternion rotation, Vector3 velocity, float chargeAmount, bool isMisfire, byte shotId)
		{
			base.FireShot(position, rotation, velocity, chargeAmount, isMisfire, shotId);
			if (isMisfire)
			{
				return;
			}
			BulletGroup bulletGroup = null;
			if (trackBulletGroups)
			{
				bulletGroup = bulletTracker.GetNewOrEmptyBulletGroup();
			}
			Vector3 normalized = velocity.normalized;
			Vector3 rhs = rotation * Vector3.right;
			Vector3 upwards = Vector3.Cross(normalized, rhs);
			rotation = Quaternion.LookRotation(normalized, upwards);
			float maxLifetime = maxDistance / bulletFireSpeed;
			spreadTargetEndRoot.localPosition = new Vector3(0f, 0f, maxDistance);
			for (int i = 0; i < spreadTargets.Length; i++)
			{
				if (!(chargeAmount < spreadTargets[i].minCharge))
				{
					Vector3 vector = position;
					if (spreadTargets[i].Start != null)
					{
						Vector3 v = barrelTransform.InverseTransformPoint(spreadTargets[i].Start.position);
						vector = v.TransformCoordinateSpace(position, rotation);
					}
					Vector3 vector2 = normalized;
					if (spreadTargets[i].End != null)
					{
						Vector3 v2 = barrelTransform.InverseTransformPoint(spreadTargets[i].End.position);
						Vector3 vector3 = v2.TransformCoordinateSpace(position, rotation);
						vector2 = (vector3 - vector).normalized;
					}
					Bullet bullet = FireBullet(vector, rotation, vector2 * bulletFireSpeed, chargeAmount, maxLifetime, (byte)(shotId + i), overrideAndDisableGravity: false, null, spreadTargets[i].bulletOverride);
					bulletGroup?.Add(bullet);
				}
			}
			ShotId += (byte)spreadTargets.Length;
		}

		private void OnDrawGizmosSelected()
		{
			if (spreadTargets == null)
			{
				return;
			}
			SpreadTarget[] array = spreadTargets;
			foreach (SpreadTarget spreadTarget in array)
			{
				if (!(spreadTarget.End == null))
				{
					Vector3 vector = ((!(spreadTarget.Start != null)) ? barrelTransform.position : spreadTarget.Start.position);
					Gizmos.color = Color.yellow;
					Gizmos.DrawWireSphere(vector, 0.05f);
					Vector3 position = spreadTarget.End.position;
					Gizmos.color = Color.white;
					Gizmos.DrawLine(vector, position);
					Gizmos.color = Color.yellow;
					Gizmos.DrawWireSphere(position, 0.05f);
				}
			}
		}
	}
}
