			{
				int revision = _wielderId.Revision;
				if (cachedWielderRevision != revision)
				{
					cachedWielderRevision = revision;
					cachedWielder = new Combatant(_wielderId.Get());
				}
				return cachedWielder;
			}
			set
			{
				_wielderId.Set(value.ID);
