		public float LastAmmunitionChangeTime => _ammunition.Get3();

		public int TotalAmmunition
		{
			get
			{
				if (hasInfiniteReserveAmmunition)
				{
					return MagazineAmmunition;
				}
				return MagazineAmmunition + ReserveAmmunition;
			}
		}

		public float TotalAmmunitionNormalized
		{
			get
			{
				if (hasInfiniteReserveAmmunition)
				{
					return 1f;
				}
				return Mathf.InverseLerp(0f, maximumTotalAmmunition, TotalAmmunition);
			}
		}

		public float MagazineAmmunitionNormalized => Mathf.InverseLerp(0f, ammunitionMagazineSize, MagazineAmmunition);

		public bool HasEnoughMagazineAmmunition
		{
			get
			{
				if (!SupportsAmmunition)
				{
					return true;
				}
				if (IsReloading)
				{
					return false;
				}
				if (MagazineAmmunition > 0)
				{
					return true;
				}
				if (automaticallyReloadMagazine && ReserveAmmunition > 0)
				{
					return true;
				}
				return false;
			}
		}

		public bool IsAmmoTotallyExhausted => supportsAmmunition && !hasInfiniteReserveAmmunition && TotalAmmunition == 0;

		public bool SupportsAmmunition => supportsAmmunition;

		public bool HasInfiniteReserveAmmunition => hasInfiniteReserveAmmunition;

