		protected override void Awake()
		{
			base.Awake();
			_wielderId = new SynchronizedField<int>(this, "WDID", (base.owner == null) ? (-1) : base.owner.ID, SetterPermissionMode.AUTHORITY, OnWielderChange);
			int defaultVal = Mathf.Max(0, maximumTotalAmmunition - defaultMagazineAmmunition);
			_ammunition = new SynchronizedField<int, int, float>(this, "AMMO", defaultMagazineAmmunition, defaultVal, (float)PhotonNetwork.time, SetterPermissionMode.AUTHORITY, OnAmmunitionChange);
			if (Tool != null)
			{
				Tool.PostReleaseEvent += OnPostReleaseEvent;
				Tool.PostPickupEvent += OnPostPickupEvent;
				Tool.PostResetEvent += OnReset;
				Tool.AddCustomPickupCondition(CustomToolAmmunitionPickupCondition);
				Tool.AddCustomEquipCondition(CustomToolAmmunitionEquipCondition);
				if (Tool.PostAwake)
				{
					OnToolPostAwake(Tool);
				}
				else
				{
					Tool.PostAwakeEvent += OnToolPostAwake;
				}
				if (Tool.RigidbodyEx != null)
				{
					Tool.RigidbodyEx.SleepChangedEvent += OnRigidbodySleepChange;
				}
			}
		}

		private void OnToolPostAwake(Tool tool)
		{
			PostAwake = true;
			if (this.ToolPostAwakeEvent != null)
			{
				this.ToolPostAwakeEvent();
			}
		}

		protected virtual void Start()
		{
			gameManager = ((!(RecRoomSceneManager.Instance != null)) ? null : NetworkedSingletonMonoBehaviour<GameManager>.Instance);
			if (Tool != null)
			{
				AllRigidbodies.Add(Tool.RigidbodyEx.UnityRigidbody);
				if (Tool.SpawnedFromPool)
				{
					Tool.AddLockOnPickup(newValue: true, DEFAULT_LOCK_ON_PICKUP_TOKEN);
				}
			}
			if (supportsAmmunition)
			{
				CheckForInfiniteAmmo();
				OnAmmunitionChange();
				ammunitionInitialized = true;
			}
			if (Animator != null && disableAnimatorOnSleep)
			{
				Animator.enabled = false;
			}
			OnWielderChange();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (Tool != null)
			{
				Tool.PostReleaseEvent -= OnPostReleaseEvent;
				Tool.PostPickupEvent -= OnPostPickupEvent;
				Tool.PostResetEvent -= OnReset;
				Tool.PostAwakeEvent -= OnToolPostAwake;
				if (Tool.RigidbodyEx != null)
				{
					Tool.RigidbodyEx.SleepChangedEvent -= OnRigidbodySleepChange;
				}
			}
		}

		public virtual void AddImpactIgnoredRigidbody(Rigidbody rigidbody)
		{
			if (!AllRigidbodies.Contains(rigidbody))
			{
				AllRigidbodies.Add(rigidbody);
			}
		}

		private void OnPostReleaseEvent(Tool tool)
		{
			if (supportsAmmunitionAnimation)
			{
				SetAnimationBool(ANIMATION_IS_HELD_ID, value: false);
			}
			if (base.hasAuthority && TotalAmmunition == 0 && !hasInfiniteReserveAmmunition && disablePostTotalAmmunitionExhaustion)
			{
				StartDisablePostTotalAmmunitionExhaustionCoroutine();
			}
		}

		private void OnPostPickupEvent(Tool tool)
		{
			Wielder = new Combatant(base.owner);
			if (Animator != null && disableAnimatorOnSleep)
			{
				Animator.enabled = true;
			}
			if (supportsAmmunitionAnimation)
			{
				SetAnimationBool(ANIMATION_IS_HELD_ID, value: true);
			}
		}

		protected virtual void OnRigidbodySleepChange(RigidbodyEx toolRigidbody)
		{
			if (!Tool.IsHeld && toolRigidbody.IsSleeping() && Animator != null && disableAnimatorOnSleep)
			{
				Animator.enabled = false;
			}
		}

		public void OnBlockAttack(Vector3 position)
		{
			if (this.BlockAttackEvent != null)
			{
				this.BlockAttackEvent(position);
			}
		}

		public void AuthorityOnEnemyApplyAttack(Enemy enemy, WeaponImpact impact)
		{
			if (base.hasAuthority)
			{
				bool hadDamageAuthority = false;
				bool wasBlocked = false;
				if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
				{
					hadDamageAuthority = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestEnemyOnToolDamage(enemy, Tool, impact.Point, out wasBlocked);
				}
				if (wasBlocked)
				{
					OnBlockAttack(impact.Point);
				}
				if (this.EnemyAppliedAttackEvent != null)
				{
					this.EnemyAppliedAttackEvent(this, impact, hadDamageAuthority);
				}
			}
		}

		public void RaisePostImpactEvent(WeaponImpact impact, bool damageAuthority)
		{
			if (this.PostImpactEvent != null)
			{
				this.PostImpactEvent(this, impact, damageAuthority);
			}
			if (Weapon.PostImpactEventStatic != null)
			{
				Weapon.PostImpactEventStatic(this, impact, damageAuthority);
			}
		}

		public virtual int GetPlayerImpactDamage(Player.BodyPart hitBodyPart, float preAttackChargeAmount, bool isSelfDamage)
		{
			int num = 0;
			if (playerDamageSettings != null)
			{
				for (int i = 0; i < playerDamageSettings.Length; i++)
				{
					if (playerDamageSettings[i].BodyPart == hitBodyPart)
					{
						num = playerDamageSettings[i].Damage;
						break;
					}
				}
			}
			if (isSelfDamage)
			{
				num = Mathf.Min(num, maxSelfDamage);
			}
			return num;
		}

		protected virtual void OnPlayerImpact(Player player, Player.BodyPart bodyPart, WeaponImpact impact)
		{
			bool flag = false;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestWeaponOnPlayerDamage(this, damageType, player, bodyPart, impact);
			}
			WeaponAudio.OnPlayerImpact(impact.Point);
			PlayImpactParticles(impact);
			SpawnImpactDecal(impact);
			if (this.PlayerImpactEvent != null)
			{
				this.PlayerImpactEvent(this, player, bodyPart, impact, flag);
			}
			RaisePostImpactEvent(impact, flag);
		}

		public virtual void NotifyWeaponDealtPlayerOnPlayerDamage(Player hitPlayer)
		{
			if (this.DealtPlayerOnPlayerDamageEvent != null)
			{
				this.DealtPlayerOnPlayerDamageEvent(hitPlayer);
			}
		}

		public virtual int GetEnemyDamage(float chargeAmount = 0f)
		{
			return enemyDamageSettings.GetDamageAmount(chargeAmount);
		}

		protected virtual bool OnEnemyImpact(Enemy enemy, EnemyArmorType enemyArmorType, WeaponImpact impact)
		{
			bool flag = false;
			if (Enemy.IsShield(enemyArmorType))
			{
				WeaponAudio.OnEnemyShieldHit(impact.Point);
			}
			else if (impact.PreAttackChargeAmount >= 0.5f)
			{
				WeaponAudio.OnEnemyHitHard(impact.Point);
			}
			else
			{
				WeaponAudio.OnEnemyHit(impact.Point);
			}
			PlayImpactParticles(impact);
			SpawnImpactDecal(impact);
			if (base.hasAuthority)
			{
				if (!enemy.hasAuthority)
				{
					enemy.TransferOwnership(PhotonNetwork.player);
				}
				if (Enemy.IsCriticalHit(enemyArmorType) && !canApplyCriticalHits)
				{
					enemyArmorType = EnemyArmorType.NORMAL;
				}
				int enemyDamage = GetEnemyDamage(impact.PreAttackChargeAmount);
				flag = enemy.AuthorityTryApplyAttack(base.authority, this, DamageType, enemyArmorType, enemyDamage, impact);
			}
			RaiseEnemyImpactEvent(enemy, enemyArmorType, impact, flag);
			RaisePostImpactEvent(impact, flag);
			return flag;
		}

		public void RaiseEnemyImpactEvent(Enemy hitEnemy, EnemyArmorType hitEnemyArmorType, WeaponImpact impact, bool hadDamageAuthority)
		{
			if (this.EnemyImpactEvent != null)
			{
				this.EnemyImpactEvent(this, hitEnemy, impact, hadDamageAuthority);
			}
			if (Weapon.EnemyImpactEventStatic != null)
			{
				Weapon.EnemyImpactEventStatic(this, hitEnemy, impact, hadDamageAuthority);
			}
		}

		protected virtual void DealEnemySecondaryDamage(Enemy enemy, WeaponImpact impact)
		{
			WeaponAudio.OnEnemySecondaryDamage(impact.Point);
			if (secondaryDamageParticlePrefab != null)
			{
				PlayImpactParticles(impact, secondaryDamageParticlePrefab);
			}
			if (base.hasAuthority)
			{
				if (!enemy.hasAuthority)
				{
					enemy.TransferOwnership(PhotonNetwork.player);
				}
				int damageAmount = secondaryEnemyDamageSettings.GetDamageAmount(impact.PreAttackChargeAmount);
				enemy.AuthorityTryApplyAttack(base.authority, this, SecondaryDamageType, EnemyArmorType.NORMAL, damageAmount, impact);
				enemy.AuthorityOnDamageApplyForce(DamageType, EnemyArmorType.NORMAL, impact.Force, impact.Point);
			}
		}

		protected virtual void OnToolImpact(Tool hitTool, WeaponImpact impact)
		{
			if (hitTool == Tool || hitTool == null)
			{
				return;
			}
			Weapon component = hitTool.GetComponent<Weapon>();
			CheckForExplosion(component, this);
			if (IsValidPlayerToolHit(hitTool))
			{
				if (component != null && component.IsShield && hitTool.IsHeldByPlayer && hitTool.HolderPlayer.isLocal && RecRoomSceneManager.HasRunningGame && Wielder.Player != null && Wielder.Player != hitTool.HolderPlayer)
				{
					ChallengeEvents.ShieldBlock(Wielder.Player.PhotonPlayer, hitTool.HolderPlayer.PhotonPlayer, hitTool);
				}
				OnPlayerHeldToolImpact(hitTool, impact);
			}
			else
			{
				if (base.hasAuthority)
				{
					hitTool.ApplyAttackAndTryTakeOwnership(this, damageType, impact.Point);
				}
				OnOtherImpact(impact);
			}
		}

		protected virtual void OnPlayerHeldToolImpact(Tool hitTool, WeaponImpact impact)
		{
			bool flag = false;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestWeaponOnToolDamage(this, DamageType, hitTool.Owner, hitTool, impact);
			}
			WeaponAudio.OnPlayerImpact(impact.Point);
			PlayImpactParticles(impact);
			SpawnImpactDecal(impact);
			if (this.PlayerToolImpactEvent != null)
			{
				this.PlayerToolImpactEvent(this, hitTool, impact, flag);
			}
			RaisePostImpactEvent(impact, flag);
		}

		private bool IsValidPlayerToolHit(Tool hitTool)
		{
			if (!hitTool.IsHeld)
			{
				return false;
			}
			if (hitTool.IsHeldByPlayer)
			{
				return true;
			}
			if (!hitTool.IsSubTool)
			{
				return true;
			}
			return hitTool.ParentTool == null || hitTool.ParentTool.IsHeld;
		}

		protected virtual void OnTrapImpact(Trap trap, WeaponImpact impact)
		{
			bool damageAuthority = false;
			if (base.hasAuthority)
			{
				if (!trap.hasAuthority)
				{
					trap.photonView.TransferOwnership(PhotonNetwork.player);
				}
				int enemyDamage = GetEnemyDamage(impact.PreAttackChargeAmount);
				trap.AuthorityApplyDamage(DamageType, enemyDamage, impact.Point, impact.SurfaceNormal);
				damageAuthority = true;
			}
			OnOtherImpact(impact, damageAuthority);
		}

		private void CheckForExplosion(Weapon hitWeapon, Weapon hittingWeapon)
		{
			if (hitWeapon != null && Wielder.IsValid && Wielder.IsLocal && Wielder.Player != null && hitWeapon != null && hitWeapon.DamageType == WeaponDamageType.EXPLOSIVE && hittingWeapon.canTriggerExplosives)
			{
				hitWeapon.HitExplosive(Wielder.Player, hittingWeapon);
			}
		}

		protected virtual void HitExplosive(Player hittingPlayer, Weapon hittingWeapon)
		{
		}

