		protected virtual void OnWielderChange()
		{
		}

		protected virtual void OnReset(Tool thisTool, Vector3 position, Quaternion rotation, Vector3 oldPosition, bool wasEnabled)
		{
			if (base.hasAuthority)
			{
				Wielder = Combatant.Invalid;
				CheckForInfiniteAmmo();
				if (SupportsAmmunition)
				{
					ResetAmmunition();
				}
			}
		}

		public void ReloadAmmunition()
		{
			if (!base.hasAuthority)
			{
				return;
			}
			int num = ammunitionMagazineSize;
			if (num < 0)
			{
				UnityEngine.Debug.LogError($"Reloading {0}, but the magazine size is set to {num}. Assuming that we actually want it to be 1.", this);
				num = 1;
			}
			if (MagazineAmmunition == num)
			{
				PlayReloadFeedback();
				return;
			}
			int magazineAmmunition = MagazineAmmunition;
			int num2 = ReserveAmmunition;
			if (hasInfiniteReserveAmmunition)
			{
				magazineAmmunition = num;
			}
			else
			{
				int a = num - magazineAmmunition;
				int num3 = Mathf.Min(a, num2);
				if (num3 <= 0)
				{
					UnityEngine.Debug.LogError($"Calculated an ammo delta of {num3} when reloading {0}. Clamping to 0 instead.", this);
					num3 = 0;
				}
				magazineAmmunition += num3;
				num2 -= num3;
			}
			SetAmmunition(magazineAmmunition, num2);
		}

		protected void ResetAmmunition()
		{
			int reserveAmmunition = Mathf.Max(0, maximumTotalAmmunition - defaultMagazineAmmunition);
			SetAmmunition(defaultMagazineAmmunition, reserveAmmunition);
		}

		protected void DecrementAmmunition()
		{
			SetAmmunition(MagazineAmmunition - 1, ReserveAmmunition);
		}

		public void ForceAmmunitionValuesOnSpawn(int magazineAmmunition, int reserveAmmunition)
		{
			SetAmmunition(magazineAmmunition, reserveAmmunition);
		}

		private void SetAmmunition(int magazineAmmunition, int reserveAmmunition)
		{
			if (CustomSetReserveAmmoBehavior != null)
			{
				CustomSetReserveAmmoBehavior(this, reserveAmmunition);
				reserveAmmunition = 0;
			}
			float newValue = (float)PhotonNetwork.time;
			_ammunition.Set(magazineAmmunition, reserveAmmunition, newValue);
		}

		protected virtual void OnAmmunitionChange()
		{
			if (this.AmmunitionChangeEvent != null)
			{
				this.AmmunitionChangeEvent();
			}
			if (MagazineAmmunition == 0 && ammunitionInitialized)
			{
				WeaponAudio.OnLastRoundSpent();
			}
			if (MagazineAmmunition == ammunitionMagazineSize)
			{
				ClearOutOFAmmoAttempts();
				PlayReloadFeedback();
			}
			if (supportsAmmunitionAnimation)
			{
				SetAnimationInt(ANIMATION_AMMUNITION_ID, MagazineAmmunition);
			}
			if (base.hasAuthority && TotalAmmunition == 0 && !hasInfiniteReserveAmmunition)
			{
				if (Tool.IsHeldByPlayer && disarmOnTotalAmmunitionExhaustion)
				{
					StartDisarmOnTotalAmmunitionExhaustionCoroutine();
				}
				else if (!Tool.IsHeldByPlayer && disablePostTotalAmmunitionExhaustion)
				{
					StartDisablePostTotalAmmunitionExhaustionCoroutine();
				}
			}
		}

		private void PlayReloadFeedback()
		{
			WeaponAudio.OnReload();
		}

		private bool CustomToolAmmunitionPickupCondition(Tool thisTool, Player selectingPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return !SupportsAmmunition || hasInfiniteReserveAmmunition || !disablePostTotalAmmunitionExhaustion || TotalAmmunition > 0;
		}

		private bool CustomToolAmmunitionEquipCondition(Tool thisTool, Player equippingPlayer, ToolEquipSlot equipSlot)
		{
			return !SupportsAmmunition || hasInfiniteReserveAmmunition || !disablePostTotalAmmunitionExhaustion || TotalAmmunition > 0;
		}

		public virtual void TryPlayOutOfAmmoFeedback()
		{
			WeaponAudio.OnOutOfAmmoFire();
			outOfAmmoAttemptCount++;
			if (outOfAmmoAttemptCount % 3 != 0)
			{
				return;
			}
			if (!hasInfiniteReserveAmmunition && ReserveAmmunition == 0)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "OUT OF AMMO", 3f);
				return;
			}
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "RELOAD YOUR WEAPON!", 1.5f);
			if (this.OnReloadNotificationPlayed != null)
			{
				this.OnReloadNotificationPlayed();
			}
		}

		protected void ClearOutOFAmmoAttempts()
		{
			outOfAmmoAttemptCount = 0;
		}

		private void StartDisarmOnTotalAmmunitionExhaustionCoroutine()
		{
			StopDisablePostTotalAmmunitionExhaustionCoroutine();
			StopDisarmOnTotalAmmunitionExhaustionCoroutine();
			disarmOnTotalAmmunitionExhaustionCoroutine = StartCoroutine(DisarmOnTotalAmmunitionExhaustionCoroutine());
		}

		private void StopDisarmOnTotalAmmunitionExhaustionCoroutine()
		{
			if (disarmOnTotalAmmunitionExhaustionCoroutine != null)
			{
				StopCoroutine(disarmOnTotalAmmunitionExhaustionCoroutine);
				disarmOnTotalAmmunitionExhaustionCoroutine = null;
			}
		}

		private IEnumerator DisarmOnTotalAmmunitionExhaustionCoroutine()
		{
			float disarmTime = UnityEngine.Time.time + 0.25f;
			while (UnityEngine.Time.time < disarmTime)
			{
				yield return null;
			}
			if (base.hasAuthority && Tool.IsHeldByPlayer && Tool.HolderPlayer.TryDisarm(Tool))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "OUT OF AMMO", 3f);
			}
			disarmOnTotalAmmunitionExhaustionCoroutine = null;
		}

		private void StartDisablePostTotalAmmunitionExhaustionCoroutine()
		{
			StopDisarmOnTotalAmmunitionExhaustionCoroutine();
			StopDisablePostTotalAmmunitionExhaustionCoroutine();
			disablePostTotalAmmunitionExhaustionCoroutine = StartCoroutine(DisablePostTotalAmmunitionExhaustionCoroutine());
		}

		private void StopDisablePostTotalAmmunitionExhaustionCoroutine()
		{
			if (disablePostTotalAmmunitionExhaustionCoroutine != null)
			{
				StopCoroutine(disablePostTotalAmmunitionExhaustionCoroutine);
				disablePostTotalAmmunitionExhaustionCoroutine = null;
			}
		}

		protected virtual bool CanDisablePostTotalAmmunitionExhaustion()
		{
			return true;
		}

		private IEnumerator DisablePostTotalAmmunitionExhaustionCoroutine()
		{
			while ((!Tool.RigidbodyEx.isKinematic && !Tool.RigidbodyEx.IsSleeping()) || !CanDisablePostTotalAmmunitionExhaustion())
			{
				yield return null;
			}
			if (base.hasAuthority)
			{
				Tool.AuthorityDisableAndMovetoLastSpawnPoint();
			}
			disablePostTotalAmmunitionExhaustionCoroutine = null;
		}

		private void CheckForInfiniteAmmo()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentMode.GameEquipmentSettings.InfiniteReserveAmmo)
			{
				hasInfiniteReserveAmmunition = true;
				if (hasInfiniteAmmoInSandbox)
				{
					supportsAmmunition = false;
				}
			}
		}

		protected void SpawnImpactDecal(WeaponImpact impact)
		{
			if (CanSpawnImpactDecal(impact.GameObject, impactDecalPrefab))
			{
				ImpactDecal.Spawn(impactDecalPrefab, WeaponColor, impact.Point, impact.SurfaceNormal, impact.GameObject, randomImpactSplatOffset, minMaxImpactDecalScale);
			}
		}

		protected void SpawnImpactDecal(WeaponImpact impact, Vector2 minMaxDecalScale)
		{
			if (CanSpawnImpactDecal(impact.GameObject, impactDecalPrefab))
			{
				ImpactDecal.Spawn(impactDecalPrefab, WeaponColor, impact.Point, impact.SurfaceNormal, impact.GameObject, randomImpactSplatOffset, minMaxDecalScale);
			}
		}

		protected void SpawnImpactDecal(ImpactDecal desiredPrefab, WeaponImpact impact)
		{
			ImpactDecal prefab = ((!(desiredPrefab != null)) ? impactDecalPrefab : desiredPrefab);
			if (CanSpawnImpactDecal(impact.GameObject, prefab))
			{
				ImpactDecal.Spawn(prefab, WeaponColor, impact.Point, impact.SurfaceNormal, impact.GameObject, randomImpactSplatOffset, minMaxImpactDecalScale);
			}
		}

		protected void SpawnImpactDecal(ImpactDecal desiredPrefab, WeaponImpact impact, Vector2 minMaxDecalScale)
		{
			ImpactDecal prefab = ((!(desiredPrefab != null)) ? impactDecalPrefab : desiredPrefab);
			if (CanSpawnImpactDecal(impact.GameObject, prefab))
			{
				ImpactDecal.Spawn(prefab, WeaponColor, impact.Point, impact.SurfaceNormal, impact.GameObject, randomImpactSplatOffset, minMaxDecalScale);
			}
		}

		private bool CanSpawnImpactDecal(GameObject hitGameObject, ImpactDecal prefab)
		{
			if (prefab == null)
			{
				return false;
			}
			if (SingletonMonoBehaviour<SettingsManager>.Instance.IgnoreBubbleActive)
			{
				PlayerHead component = hitGameObject.GetComponent<PlayerHead>();
				if (component != null && component.isLocal && Tool.Owner.PhotonPlayer != null && !Tool.Owner.isLocal)
				{
					bool flag = gameManager != null && gameManager.CurrentState == GameStates.GAME_RUNNING;
					bool flag2 = gameManager != null && gameManager.TeamManager.PlayersAreTeammates(component.Player.PhotonPlayer, Tool.Owner.PhotonPlayer);
					if (!flag || flag2)
					{
						return false;
					}
				}
			}
			return true;
		}

		protected PooledParticle PlayParticles(PooledParticle particlePrefab, Vector3 position, bool forceOverrideColor = false, float sizeMultiplier = 1f)
		{
			if (particlePrefab != null)
			{
				PooledParticle pooledParticle = ObjectPool.Instance.Acquire(particlePrefab);
				if (pooledParticle != null)
				{
					for (int i = 0; i < pooledParticle.AllParticleSystems.Length; i++)
					{
						if (overrideParticleStartColor || forceOverrideColor)
						{
							pooledParticle.SetColor(WeaponColor);
						}
					}
					pooledParticle.Play(position, Quaternion.identity, loop: false, sizeMultiplier);
				}
				return pooledParticle;
			}
			return null;
		}

		protected void PlayImpactParticles(WeaponImpact impact, PooledParticle prefab = null)
		{
			if (prefab == null)
			{
				prefab = impactParticlePrefab;
			}
			if (!(prefab != null))
			{
				return;
			}
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(prefab);
			if (pooledParticle != null)
			{
				Vector3 forward = -impact.Velocity.normalized;
				if (overrideParticleStartColor)
				{
					pooledParticle.SetColor(WeaponColor);
				}
				pooledParticle.Play(impact.Point, Quaternion.LookRotation(forward, Vector3.up));
			}
		}

