		public bool ImpactAlreadyRegistered(byte impactId)
		{
			float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
			float num = times[impactId];
			times[impactId] = realtimeSinceStartup;
			return realtimeSinceStartup - num < 1f;
		}

		static Weapon()
		{
			Weapon.PostImpactEventStatic = null;
			Weapon.EnemyImpactEventStatic = null;
			ANIMATION_IS_HELD_ID = Animator.StringToHash("IsHeld");
			ANIMATION_AMMUNITION_ID = Animator.StringToHash("Ammunition");
