	public class WeaponAccessory : ToolAccessory
	{
		[Autofill(AutofillType.Parent, false)]
		[SerializeField]
		protected Weapon parentWeapon;

		protected override void Awake()
		{
			base.Awake();
			if (parentWeapon == null)
			{
				UnityEngine.Debug.LogError(base.name + " is not parented to a weapon.");
				return;
			}
			parentWeapon.BoolAnimatorEvent += OnWeaponBoolAnimatorEvent;
			parentWeapon.FloatAnimatorEvent += OnWeaponFloatAnimatorEvent;
			parentWeapon.TriggerAnimatorEvent += OnWeaponTriggerAnimatorEvent;
			parentWeapon.IntAnimatorEvent += OnWeaponIntAnimatorEvent;
		}

		protected override void OnDestroy()
		{
			if (parentWeapon != null)
			{
				parentWeapon.BoolAnimatorEvent -= OnWeaponBoolAnimatorEvent;
				parentWeapon.FloatAnimatorEvent -= OnWeaponFloatAnimatorEvent;
				parentWeapon.TriggerAnimatorEvent -= OnWeaponTriggerAnimatorEvent;
				parentWeapon.IntAnimatorEvent -= OnWeaponIntAnimatorEvent;
			}
			base.OnDestroy();
		}

		private void OnWeaponFloatAnimatorEvent(int id, float value)
		{
			if (animator != null && animator.isActiveAndEnabled)
