	private RecRoomAudioClip onEnemySecondaryDamage;

	private SFXAudioSource fullyChargedLoopingAudio;

	private SFXAudioSource chargeAudio;

	public bool IsLoopingFullyChargedAudio => fullyChargedLoopingAudio != null;

	public void OnFireHard()
	{
		AudioManager.Play3DSFX(onFire, base.transform);
	}

	public void OnFireSoft()
	{
		if (onFireSoft == null || onFireSoft.audioClip == null)
		{
			OnFireHard();
		}
		else
		{
			AudioManager.Play3DSFX(onFireSoft, base.transform);
		}
	}

	public void OnCharge(float timeSinceChargeStart = 0f)
	{
		OnStopCharge();
		chargeAudio = AudioManager.Play3DSFX(onCharge, base.transform, null, OnChargeAudioFinished);
		if (timeSinceChargeStart > Mathf.Epsilon)
		{
			chargeAudio.Scrub(timeSinceChargeStart);
		}
	}

	private void OnChargeAudioFinished(SFXAudioSource sfxAudioSource)
	{
		if (sfxAudioSource == chargeAudio)
		{
			chargeAudio = null;
		}
	}

	public void OnStopCharge()
	{
		if (chargeAudio != null)
		{
			AudioManager.StopLoopingSFX(chargeAudio);
			chargeAudio = null;
		}
	}

	public void OnFullyChargedLoopStart()
	{
		OnFullyChargedLoopStop();
		fullyChargedLoopingAudio = AudioManager.StartLooping3DSFX(onFullyChargedLoop, base.transform);
	}

	public void OnFullyChargedLoopStop()
	{
		if (fullyChargedLoopingAudio != null)
		{
			AudioManager.StopLoopingSFX(fullyChargedLoopingAudio);
			fullyChargedLoopingAudio = null;
		}
	}

	public void OnLastRoundSpent()
	{
		AudioManager.Play3DSFX(onLastRoundSpent, base.transform);
	}

	public void OnReload()
	{
		AudioManager.Play3DSFX(onReload, base.transform);
	}

	public void OnOutOfAmmoFire()
	{
		AudioManager.Play3DSFX(onOutOfAmmoFire, base.transform);
	}

	public void OnMisfire()
	{
		AudioManager.Play3DSFX(onMisfire, base.transform);
	}

	public void OnSwing(Transform audioPlayTransform)
	{
		AudioManager.Play3DSFX(onSwing, audioPlayTransform);
	}

	public void OnPlayerImpact(Vector3 position)
	{
		AudioManager.Play3DSFX(onHitPlayer, position);
	}

	public void OnEnemyHit(Vector3 position)
	{
		AudioManager.Play3DSFX(onEnemyHit, position);
	}

	public void OnEnemyHitHard(Vector3 position)
	{
		AudioManager.Play3DSFX(onEnemyHitHard, position);
	}

	public void OnEnemyShieldHit(Vector3 position)
	{
		AudioManager.Play3DSFX(onEnemyHitShield, position);
	}

	public void OnEnemySecondaryDamage(Vector3 position)
	{
		AudioManager.Play3DSFX(onEnemySecondaryDamage, position);
	}

	public void OnEnvironmentImpact(Vector3 position)
	{
		AudioManager.Play3DSFX(onHitEnvironment, position);
	}

	private void OnDestroy()
	{
		OnStopCharge();
		OnFullyChargedLoopStop();
	}
}
