public struct WeaponRaycastHit
{
	public float Distance;

	public Vector3 Point;

	public Vector3 Normal;

	public Collider Collider;

	public Rigidbody Rigidbody;
}
public class WeaponRaycastCollider
{
	public delegate bool CollisionFilter(Rigidbody potentialHitRigidbody);

	private RaycastHit[] hits = new RaycastHit[20];

	private Collider[] stationaryHits = new Collider[5];

	private RaycastHitComparer raycastHitComparer = new RaycastHitComparer();

	public bool RunMovingCollision(Vector3 previousPosition, Vector3 currentPosition, float radius, int layerMask, List<Rigidbody> ignoredRigidbodies, CollisionFilter collisionFilter, out WeaponRaycastHit hit)
	{
		hit = default(WeaponRaycastHit);
		int num = UpdateCollisionResults(previousPosition, currentPosition, layerMask, radius);
		for (int i = 0; i < num; i++)
		{
			if ((ignoredRigidbodies == null || !ignoredRigidbodies.Contains(hits[i].rigidbody)) && (collisionFilter == null || collisionFilter(hits[i].rigidbody)))
			{
				CopyRaycastHitToWeaponRaycastHit(hits[i], ref hit);
				return true;
			}
		}
		return false;
	}

	public int RunAllMovingCollisions(Vector3 previousPosition, Vector3 currentPosition, float radius, int layerMask, List<Rigidbody> ignoredRigidbodies, CollisionFilter collisionFilter, ref WeaponRaycastHit[] outHits)
	{
		int num = 0;
		int num2 = UpdateCollisionResults(previousPosition, currentPosition, layerMask, radius);
		for (int i = 0; i < num2; i++)
		{
			if (num >= outHits.Length)
			{
				break;
			}
			if ((ignoredRigidbodies == null || !ignoredRigidbodies.Contains(hits[i].rigidbody)) && (collisionFilter == null || collisionFilter(hits[i].rigidbody)) && !HitsArrayContainsRigidbody(outHits, num, hits[i].rigidbody))
			{
				CopyRaycastHitToWeaponRaycastHit(hits[i], ref outHits[num++]);
			}
		}
		return num;
	}

	public int RunAllStationaryCollisions(Vector3 position, float radius, List<Rigidbody> ignoredRigidbodies, CollisionFilter collisionFilter, ref WeaponRaycastHit[] outHits)
	{
		int num = 0;
		int num2 = UpdateStationaryCollisionResults(position, radius);
		for (int i = 0; i < num2; i++)
		{
			if (num >= outHits.Length)
			{
				break;
			}
			if ((ignoredRigidbodies == null || !ignoredRigidbodies.Contains(hits[i].rigidbody)) && (collisionFilter == null || collisionFilter(hits[i].rigidbody)))
			{
				Rigidbody attachedRigidbody = stationaryHits[i].attachedRigidbody;
				if (!HitsArrayContainsRigidbody(outHits, num, attachedRigidbody))
				{
					CopyColliderHitToWeaponRaycastHit(stationaryHits[i], position, radius, ref outHits[num++]);
				}
			}
		}
		return num;
	}

	private int UpdateCollisionResults(Vector3 previousPosition, Vector3 currentPosition, int layerMask, float radius)
	{
		Vector3 vector = currentPosition - previousPosition;
		if (vector.sqrMagnitude <= Mathf.Epsilon)
		{
			return 0;
		}
		float magnitude = vector.magnitude;
		Vector3 direction = vector / magnitude;
		int num = Physics.SphereCastNonAlloc(previousPosition, radius, direction, hits, magnitude, layerMask, QueryTriggerInteraction.Ignore);
		if (hits == null || num == 0)
		{
			return 0;
		}
		Array.Sort(hits, 0, num, raycastHitComparer);
		return num;
	}

	private int UpdateStationaryCollisionResults(Vector3 currentPosition, float radius)
	{
		return Physics.OverlapSphereNonAlloc(currentPosition, radius, stationaryHits, 362036736, QueryTriggerInteraction.Ignore);
	}

	private bool HitsArrayContainsRigidbody(WeaponRaycastHit[] hitsArray, int arraySize, Rigidbody rigidbody)
	{
		for (int i = 0; i < arraySize; i++)
		{
			if (hitsArray[i].Rigidbody == rigidbody)
			{
				return true;
			}
		}
		return false;
	}

	private void CopyRaycastHitToWeaponRaycastHit(RaycastHit raycastHit, ref WeaponRaycastHit weaponRaycastHit)
	{
		weaponRaycastHit.Distance = raycastHit.distance;
		weaponRaycastHit.Point = raycastHit.point;
		weaponRaycastHit.Normal = raycastHit.normal;
		weaponRaycastHit.Collider = raycastHit.collider;
		weaponRaycastHit.Rigidbody = raycastHit.rigidbody;
	}

	private void CopyColliderHitToWeaponRaycastHit(Collider hitCollider, Vector3 testPosition, float testRadius, ref WeaponRaycastHit weaponRaycastHit)
	{
		Vector3 normalized = (hitCollider.transform.position - testPosition).normalized;
		weaponRaycastHit.Distance = testRadius;
		weaponRaycastHit.Point = testPosition + normalized * testRadius;
		weaponRaycastHit.Normal = normalized;
		weaponRaycastHit.Collider = hitCollider;
		weaponRaycastHit.Rigidbody = hitCollider.attachedRigidbody;
	}
}
namespace RecRoom.Tools.Weapons
{
	public class WeaponReloader : WeaponAccessory
	{
		private enum ReloaderType
		{
			PUMP,
			PULL
		}

		private const float FULLY_PULLED_NORMALIZED_VALUE = 0.99f;

		[Header("Reloader")]
		[SerializeField]
		private ReloaderType reloaderType = ReloaderType.PULL;

		[SerializeField]
		private Transform emptyClipTransform;

		[SerializeField]
		private Transform fullClipTransform;

		[SerializeField]
		private float extraPullDistance = 0.05f;

		[Header("Feedback")]
		[SerializeField]
		private RecRoomAudioClip pullTickAudio;

		[SerializeField]
		private int pullTickCount = 10;

		[SerializeField]
		private float returnToConstraintSpeed = 20f;

		[Header("Weapon Animation")]
		[SerializeField]
		private bool animateParentWeaponReloader;

		private static readonly int RELOADER_BLEND_ID = Animator.StringToHash("ReloaderBlend");

		private const float MAX_PITCH_SHIFT = 0.45f;

		[NonSerialized]
		public bool ReloadsAutomatically = true;

		private PlungerRigidbodyPickup plungerRigidbodyPickup;

		private Vector3 weaponSpaceEmptyClipPosition = Vector3.zero;

		private Quaternion weaponSpaceEmptyClipRotation = Quaternion.identity;

		private Vector3 localTranslationDirection = Vector3.zero;

		private float fullClipPullDistance;

		private bool wasFullyPulled;

		private float previousTickDistance;

		private float? returnDistance;

		private Coroutine highlightReloaderRoutine;

		private int TotalTickCount => pullTickCount + 1;

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.IgnorePickupDirection = true;
				base.Tool.AddCustomPickupCondition(CustomPickupCondition);
				base.Tool.PostPickupEvent += OnPostPickup;
				base.Tool.PostReleaseEvent += OnPostRelease;
				base.Tool.PostAttachEvent += OnPostAttach;
				base.Tool.PostResetEvent += OnReset;
				base.Tool.RigidbodyEx.AddKinematic(this);
			}
			if (parentWeapon == null)
			{
				UnityEngine.Debug.LogError(base.name + " is missing weapon reference.");
			}
			else
			{
				parentWeapon.OnReloadNotificationPlayed += OnReloadNotificationPlayed;
				parentWeapon.AmmunitionChangeEvent += OnAmmunitionChange;
				weaponSpaceEmptyClipPosition = parentWeapon.transform.InverseTransformPoint(emptyClipTransform.position);
				weaponSpaceEmptyClipRotation = parentWeapon.transform.InverseTransformRotation(emptyClipTransform.rotation);
			}
			Vector3 vector = emptyClipTransform.InverseTransformPoint(fullClipTransform.position);
			localTranslationDirection = vector.normalized;
			fullClipPullDistance = vector.magnitude;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= OnPostPickup;
				base.Tool.PostReleaseEvent -= OnPostRelease;
				base.Tool.PostAttachEvent -= OnPostAttach;
				base.Tool.PostResetEvent -= OnReset;
			}
			if (parentWeapon != null)
			{
				parentWeapon.AmmunitionChangeEvent -= OnAmmunitionChange;
				parentWeapon.OnReloadNotificationPlayed -= OnReloadNotificationPlayed;
			}
		}

		protected override void Start()
		{
			base.Start();
			plungerRigidbodyPickup = base.Tool.RigidbodyPickup as PlungerRigidbodyPickup;
			plungerRigidbodyPickup.ConstraintPickup = parentWeapon.Tool.RigidbodyPickup;
			plungerRigidbodyPickup.ConstraintOffsetPosition = weaponSpaceEmptyClipPosition;
			plungerRigidbodyPickup.ConstraintOffsetRotation = weaponSpaceEmptyClipRotation;
			plungerRigidbodyPickup.ConstraintLocalAxis = localTranslationDirection;
			plungerRigidbodyPickup.MinimumConstraintDistance = 0f;
			plungerRigidbodyPickup.MaximumConstraintDistance = fullClipPullDistance + extraPullDistance;
			OnAmmunitionChange();
			UpdateEnabledDisabled();
			if (!base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToWeapon(force: false);
			}
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			if (initialized && !base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToWeapon(force: false);
			}
		}

		private void Update()
		{
			if (base.Tool.hasAuthority && base.Tool.IsHeld && plungerRigidbodyPickup != null)
			{
				float num = Mathf.InverseLerp(0f, fullClipPullDistance, plungerRigidbodyPickup.CurrentDistance);
				if (Mathf.Abs(num - previousTickDistance) >= 1f / (float)TotalTickCount)
				{
					PlayPullTickFeedback(num);
					previousTickDistance = num;
				}
				bool flag = num >= 0.99f;
				if (flag && !wasFullyPulled)
				{
					if (ReloadsAutomatically)
					{
						parentWeapon.ReloadAmmunition();
					}
					StopHighlightReloaderRoutine();
				}
				wasFullyPulled = flag;
			}
			UpdateParentAnimation();
		}

		private void OnPostPickup(Tool tool)
		{
			wasFullyPulled = false;
			float num = Mathf.InverseLerp(0f, fullClipPullDistance, (!(plungerRigidbodyPickup != null)) ? 0f : plungerRigidbodyPickup.CurrentDistance);
			int num2 = (int)((float)TotalTickCount * num);
			previousTickDistance = (float)num2 / (float)TotalTickCount;
			parentWeapon.IsReloading = true;
		}

		private void OnPostRelease(Tool tool)
		{
			parentWeapon.IsReloading = false;
			if (plungerRigidbodyPickup != null)
			{
				returnDistance = plungerRigidbodyPickup.CurrentDistance;
				plungerRigidbodyPickup.CurrentDistance = 0f;
			}
			if (base.Tool.hasAuthority)
			{
				this.EndOfFrameRoutine(delegate
				{
					AuthorityAttachToWeapon(force: false);
				});
			}
		}

		private void OnPostAttach(Tool tool)
		{
			if (parentWeapon.Tool.IsHeldByPlayer && base.Tool.hasAuthority && base.isActiveAndEnabled && returnDistance.HasValue)
			{
				StartCoroutine(ReturnLerpRoutine(returnDistance.Value));
			}
		}

		private void OnReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			UnityEngine.Debug.LogErrorFormat("Resetting reloader subtool {0}. Subtools generally shouldn't be manually reset.", this);
			AuthorityAttachToWeapon(force: false);
		}

		protected override void OnParentToolEnabled(Tool tool)
		{
			base.OnParentToolEnabled(tool);
			OnAmmunitionChange();
		}

		protected override void OnParentToolPostPickup(Tool tool)
		{
			base.OnParentToolPostPickup(tool);
			UpdateEnabledDisabled();
		}

		protected override void OnParentToolSleepChange(RigidbodyEx weaponRigidbody)
		{
			UpdateEnabledDisabled();
		}

		private void OnAmmunitionChange()
		{
			if (initialized && base.gameObject.activeInHierarchy && plungerRigidbodyPickup != null && !base.Tool.IsHeld)
			{
				UpdateRigidbodyFollowingConstraints();
				AuthorityAttachToWeapon(force: true);
			}
		}

		private void OnReloadNotificationPlayed()
		{
			StopHighlightReloaderRoutine();
			highlightReloaderRoutine = StartCoroutine(RunHighlightReloader());
		}

		private void StopHighlightReloaderRoutine()
		{
			if (highlightReloaderRoutine != null)
			{
				StopCoroutine(highlightReloaderRoutine);
			}
			highlightReloaderRoutine = null;
		}

		private IEnumerator RunHighlightReloader()
		{
			float startTime = UnityEngine.Time.time;
			while (UnityEngine.Time.time < startTime + 3f)
			{
				base.Tool.RenderTutorialOutline();
				yield return null;
			}
		}

		private void AuthorityAttachToWeapon(bool force)
		{
			if (base.Tool.hasAuthority && parentWeapon != null && (force || base.Tool.HolderView != parentWeapon.photonView))
			{
				base.Tool.AuthorityAttachToObject(parentWeapon.photonView, weaponSpaceEmptyClipPosition, weaponSpaceEmptyClipRotation, localScale);
			}
		}

		private IEnumerator ReturnLerpRoutine(float returnDistance)
		{
			float returnVelocity = 0f;
			float duration = returnDistance / returnToConstraintSpeed * 1.25f;
			float timer = 0f;
			while (timer < duration && base.Tool.IsAttachedToObject)
			{
				yield return null;
				timer += UnityEngine.Time.deltaTime;
				returnDistance = Mathf.SmoothDamp(returnDistance, 0f, ref returnVelocity, 0.1f, returnToConstraintSpeed, UnityEngine.Time.deltaTime);
				base.Tool.transform.localPosition = base.Tool.HolderInfo.RelativePosition + localTranslationDirection * returnDistance;
				base.Tool.transform.localRotation = base.Tool.HolderInfo.RelativeRotation;
			}
			if (base.Tool.IsAttachedToObject)
			{
				base.Tool.transform.localPosition = base.Tool.HolderInfo.RelativePosition;
				base.Tool.transform.localRotation = base.Tool.HolderInfo.RelativeRotation;
			}
		}

		private void UpdateParentAnimation()
		{
			if (animateParentWeaponReloader)
			{
				float value = parentWeapon.MagazineAmmunitionNormalized;
				if (plungerRigidbodyPickup != null && base.Tool.IsHeld && !parentWeapon.HasEnoughMagazineAmmunition)
				{
					float num = Mathf.InverseLerp(0f, fullClipPullDistance, plungerRigidbodyPickup.CurrentDistance);
					value = num;
				}
				parentWeapon.SetAnimationFloat(RELOADER_BLEND_ID, value);
			}
		}

		private void UpdateRigidbodyFollowingConstraints()
		{
			if (plungerRigidbodyPickup != null)
			{
				if (reloaderType == ReloaderType.PULL)
				{
					plungerRigidbodyPickup.MinimumConstraintDistance = Mathf.Lerp(0f, fullClipPullDistance, parentWeapon.MagazineAmmunitionNormalized);
					plungerRigidbodyPickup.MaximumConstraintDistance = fullClipPullDistance;
				}
				else if (reloaderType == ReloaderType.PUMP)
				{
					plungerRigidbodyPickup.MinimumConstraintDistance = 0f;
					plungerRigidbodyPickup.MaximumConstraintDistance = fullClipPullDistance;
				}
				plungerRigidbodyPickup.MaximumConstraintDistance += extraPullDistance;
			}
		}

		private bool CustomPickupCondition(Tool thisTool, Player pickupPlayer, Vector3 selectionPoint, bool physicalPickup)
		{
			return parentWeapon.TotalAmmunition != 0 || parentWeapon.HasInfiniteReserveAmmunition;
		}

		private void PlayPullTickFeedback(float normalizedPullAmount)
		{
			if (base.Tool.IsHeld && !(parentWeapon == null) && parentWeapon.Tool.IsHeld)
			{
				if (pullTickAudio != null)
				{
					pullTickAudio.pitchShift = 0.45f * normalizedPullAmount;
					AudioManager.Play3DSFX(pullTickAudio, base.transform);
				}
				if (parentWeapon.Tool.IsHeldByPlayer && parentWeapon.Tool.HolderHand != null && parentWeapon.Tool.HolderHand.isLocal && base.Tool.IsHeldByPlayer && base.Tool.HolderHand != null && base.Tool.HolderHand.isLocal)
				{
					base.Tool.HolderHand.Vibrate(20, 0.5f);
					parentWeapon.Tool.HolderHand.Vibrate(20, 0.5f);
				}
			}
		}

		private void UpdateEnabledDisabled()
		{
			base.enabled = parentWeapon != null && (parentWeapon.Tool.IsHeld || !parentWeapon.Tool.RigidbodyEx.IsSleeping());
		}
	}
	public class WeaponStabilizationGrip : WeaponAccessory
	{
		private StabilizedRigidbodyPickup weaponRigidbodyPickup;

		private PlungerRigidbodyPickup thisRigidbodyPickup;

		protected override void Awake()
		{
			base.Awake();
			if (base.Tool != null)
			{
				base.Tool.IgnorePickupDirection = true;
				base.Tool.PostPickupEvent += OnPostPickup;
				base.Tool.PostReleaseEvent += OnPostRelease;
				base.Tool.PostResetEvent += OnReset;
			}
		}

		protected override void Start()
		{
			base.Start();
			weaponRigidbodyPickup = parentWeapon.Tool.RigidbodyPickup as StabilizedRigidbodyPickup;
			if (weaponRigidbodyPickup == null)
			{
				UnityEngine.Debug.LogError(parentWeapon.name + "missing stabilizer rigidbody pickup.");
				return;
			}
			weaponRigidbodyPickup.StabilizerSeparationEvent += OnStabilizerSeparated;
			thisRigidbodyPickup = base.Tool.RigidbodyPickup as PlungerRigidbodyPickup;
			thisRigidbodyPickup.ConstraintPickup = weaponRigidbodyPickup;
			thisRigidbodyPickup.ConstraintOffsetPosition = localPosition;
			thisRigidbodyPickup.ConstraintOffsetRotation = localRotation;
			thisRigidbodyPickup.ConstraintLocalAxis = Vector3.forward;
			thisRigidbodyPickup.MinimumConstraintDistance = 0f;
			thisRigidbodyPickup.MaximumConstraintDistance = 0f;
			if (!base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToWeapon();
			}
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			if (initialized && !base.Tool.IsHeldByPlayer)
			{
				AuthorityAttachToWeapon();
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (base.Tool != null)
			{
				base.Tool.PostPickupEvent -= OnPostPickup;
				base.Tool.PostReleaseEvent -= OnPostRelease;
				base.Tool.PostResetEvent -= OnReset;
			}
			if (weaponRigidbodyPickup != null)
			{
				weaponRigidbodyPickup.StabilizerSeparationEvent -= OnStabilizerSeparated;
			}
		}

		private void OnPostPickup(Tool tool)
		{
			if (base.Tool.HolderHand == null)
			{
				UnityEngine.Debug.LogError("No HolderHand set in WeaponStabilizationGrip.OnPostPickup");
				return;
			}
			if (base.Tool.HolderHand.isLocal)
			{
				weaponRigidbodyPickup.Stabilizer = base.Tool.HolderHand.RigidbodyEx.TargetTransform;
			}
			else
			{
				weaponRigidbodyPickup.Stabilizer = base.Tool.HolderHand.transform;
			}
			weaponRigidbodyPickup.StabilizerOffsetPosition = base.Tool.HolderInfo.RelativePosition;
			weaponRigidbodyPickup.StabilizerOffsetRotation = Quaternion.FromToRotation(weaponRigidbodyPickup.StabilizedForward, weaponRigidbodyPickup.transform.forward);
		}

		private void OnPostRelease(Tool tool)
		{
			weaponRigidbodyPickup.Stabilizer = null;
			this.EndOfFrameRoutine(AuthorityAttachToWeapon);
		}

		private void OnReset(Tool tool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			UnityEngine.Debug.LogErrorFormat("Resetting stabilization subtool {0}. Subtools generally shouldn't be manually reset.", this);
			AuthorityAttachToWeapon();
		}

		private void OnStabilizerSeparated()
		{
			if (base.Tool.IsHeld && base.Tool.hasAuthority)
			{
				base.Tool.HolderInfo = ToolHolderInfo.NotHeld;
			}
		}

		private void AuthorityAttachToWeapon()
		{
			if (base.Tool.hasAuthority && parentWeapon != null)
			{
				base.Tool.AuthorityAttachToObject(parentWeapon.photonView, localPosition, localRotation, localScale);
			}
		}
	}
}
public class StreamerGUI : UnityEngine.MonoBehaviour
{
	public Texture cameraTexture;

	public Texture cameraTextureOff;

	public float AutoHideDuration = 10f;

	private static bool showGUI;

	private float lastGUIInteractionTime;

	public static bool ShowGUI => showGUI;

	private void Update()
	{
		if (showGUI && UnityEngine.Time.time - lastGUIInteractionTime > AutoHideDuration)
		{
			showGUI = false;
		}
	}

	private void OnGUI()
	{
		if (!Player.LocalPlayerExists || !SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
		{
			return;
		}
		bool flag = false;
		float num = 500f;
		GUILayout.BeginArea(new Rect((float)Screen.width - num - 1f, 1f, num, 250f));
		GUILayout.BeginVertical();
		GUILayout.BeginHorizontal();
		GUILayout.FlexibleSpace();
		if (GUILayout.Button((!showGUI) ? "+" : "-", GUILayout.Width(16f), GUILayout.Height(16f)))
		{
			showGUI = !showGUI;
			flag = true;
			Cursor.visible = true;
		}
		GUILayout.EndHorizontal();
		if (showGUI)
		{
			GUILayout.BeginHorizontal();
			GUILayout.FlexibleSpace();
			bool flag2 = SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.Mode == StreamingCameraController.StreamingCameraMode.ON;
			if (GUILayout.Button((!flag2) ? cameraTexture : cameraTextureOff, GUILayout.Width(24f), GUILayout.Height(24f)))
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetMode((!flag2) ? StreamingCameraController.StreamingCameraMode.ON : StreamingCameraController.StreamingCameraMode.OFF, StreamingCameraController.InteractionSource.ScreenUI);
				flag = true;
			}
			CameraTransform.CameraType selectedCameraType = CameraTransform.CameraType.Unspecified;
			if (flag2 && SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow != null)
			{
				selectedCameraType = SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow.Type;
				flag = true;
			}
			flag |= CameraTypeSelection(flag2, selectedCameraType, CameraTransform.CameraType.FirstPerson, "1st (Smooth)");
			flag |= CameraTypeSelection(flag2, selectedCameraType, CameraTransform.CameraType.ThirdPerson, "3rd (Follow)");
			flag |= CameraTypeSelection(flag2, selectedCameraType, CameraTransform.CameraType.ThirdPersonFace, "3rd (Face)");
			flag |= CameraTypeSelection(flag2, selectedCameraType, CameraTransform.CameraType.ThirdPersonTeleportOnly, "3rd (Teleport)");
			GUILayout.EndHorizontal();
			if (SingletonMonoBehaviour<StreamingCameraController>.IsInitialized && flag2)
			{
				GUILayout.BeginHorizontal();
				GUILayout.FlexibleSpace();
				GUILayout.Label("Stream Frame Rate", GUI.skin.box);
				flag |= FrameRateSelectionButton(StreamingCameraController.FrameRates._15);
				flag |= FrameRateSelectionButton(StreamingCameraController.FrameRates._30);
				flag |= FrameRateSelectionButton(StreamingCameraController.FrameRates._45);
				flag |= FrameRateSelectionButton(StreamingCameraController.FrameRates._60);
				GUILayout.EndHorizontal();
				GUILayout.BeginHorizontal();
				GUILayout.FlexibleSpace();
				GUILayout.Label("Stream Field of View", GUI.skin.box);
				flag |= FoVSelectionButton(StreamingCameraController.FOVs.TwentyDegrees);
				flag |= FoVSelectionButton(StreamingCameraController.FOVs.FiftyDegrees);
				flag |= FoVSelectionButton(StreamingCameraController.FOVs.Default);
				flag |= FoVSelectionButton(StreamingCameraController.FOVs.NinetyDegrees);
				flag |= FoVSelectionButton(StreamingCameraController.FOVs.OneHundredTwentyDegrees);
				GUILayout.EndHorizontal();
				GUILayout.BeginHorizontal();
				GUILayout.FlexibleSpace();
				GUILayout.Label("Audio Listening Source", GUI.skin.box);
				flag |= AudioListenerSelectionButton(StreamingCameraController.AudioListenerModes.Player);
				flag |= AudioListenerSelectionButton(StreamingCameraController.AudioListenerModes.StreamCamera);
				GUILayout.EndHorizontal();
				GUILayout.BeginHorizontal();
				GUILayout.FlexibleSpace();
				GUILayout.Label("Green Screen", GUI.skin.box);
				flag |= GreenScreenSelectionButton(StreamingCameraController.GreenScreenModes.Off);
				flag |= GreenScreenSelectionButton(StreamingCameraController.GreenScreenModes.TwoMeters);
				flag |= GreenScreenSelectionButton(StreamingCameraController.GreenScreenModes.FiveMeters);
				flag |= GreenScreenSelectionButton(StreamingCameraController.GreenScreenModes.TenMeters);
				flag |= GreenScreenSelectionButton(StreamingCameraController.GreenScreenModes.OneHundredMeters);
				GUILayout.EndHorizontal();
			}
			GUI.enabled = true;
		}
		GUILayout.EndVertical();
		GUILayout.EndArea();
		if (flag)
		{
			lastGUIInteractionTime = UnityEngine.Time.time;
		}
	}

	private bool CameraTypeSelection(bool streamingOn, CameraTransform.CameraType selectedCameraType, CameraTransform.CameraType thisCameraType, string buttonText)
	{
		GUI.enabled = streamingOn && selectedCameraType != thisCameraType;
		if (GUILayout.Button(buttonText, GUILayout.Width(100f), GUILayout.Height(24f)))
