public class ActivityContextMenu : UnityEngine.MonoBehaviour
{
	private GameManager gameManager;

	public UnityEngine.UI.Button PlayButton;

	public UnityEngine.UI.Button ReplayButton;

	public UnityEngine.UI.Button RestartButton;

	private void Start()
	{
		gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (gameManager != null)
		{
			gameManager.StateChangeEvent += OnGameStateChanged;
			gameManager.TeamManager.TeamChangeEvent += OnTeamChange;
		}
	}

	private void OnDestroy()
	{
		if (gameManager != null)
		{
			gameManager.StateChangeEvent -= OnGameStateChanged;
			gameManager.TeamManager.TeamChangeEvent -= OnTeamChange;
		}
	}

	private void OnEnable()
	{
		UpdateButtons();
	}

	private void OnGameStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateButtons();
	}

	private void OnTeamChange(PhotonPlayer changingTeamPlayer, bool isDisconnecting)
	{
		UpdateButtons();
	}

	private void UpdateButtons()
	{
		bool flag = gameManager != null;
		bool interactable = flag && gameManager.ReadyToPlay;
		PlayButton.gameObject.SetActive(flag && gameManager.CurrentState == GameStates.PRE_GAME);
		PlayButton.interactable = interactable;
		ReplayButton.gameObject.SetActive(value: false);
		RestartButton.gameObject.SetActive(flag && gameManager.CurrentState == GameStates.GAME_RUNNING);
		RestartButton.interactable = interactable;
	}
}
namespace RecRoom
{
	public class AGVirtualKeyboard : UnityEngine.MonoBehaviour
	{
		private const float HYDRATION_DURATION = 0.3f;

		private const string VISIBILITY_ANIM_NAME = "KeyboardActive";

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private Punchkeyboard punchkeyboard;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Animator animator;

		[SerializeField]
		private GameObject keyboardRoot;

		private bool _isOpen;

		public Action OnAnyKeyPressed;

		private object token;

		private Transform originalParent;

		private IDisposable keyboardHydrationRoutine;

		public bool IsOpen
		{
			get
			{
				return _isOpen;
			}
			private set
			{
				if (_isOpen != value)
				{
					_isOpen = value;
					keyboardRoot.SetActive(_isOpen);
				}
			}
		}

		public bool KeysEnabled
		{
			get
			{
				return punchkeyboard.KeysEnabled;
			}
			set
			{
				punchkeyboard.KeysEnabled = value;
			}
		}

		private void Awake()
		{
			keyboardRoot.SetActive(_isOpen);
			originalParent = base.gameObject.transform.parent;
		}

		private void Start()
		{
			Punchkeyboard obj = punchkeyboard;
			obj.OnAnyKeyPressed = (Action)Delegate.Combine(obj.OnAnyKeyPressed, new Action(OnPunchkeyboardKeyPressed));
		}

		private void OnDestroy()
		{
			if (punchkeyboard != null)
			{
				Punchkeyboard obj = punchkeyboard;
				obj.OnAnyKeyPressed = (Action)Delegate.Remove(obj.OnAnyKeyPressed, new Action(OnPunchkeyboardKeyPressed));
			}
		}

		public void ShowKeyboard(object token, Transform parentTransform)
		{
			if (!IsOpen || this.token != token)
			{
				if (keyboardHydrationRoutine != null)
				{
					keyboardHydrationRoutine.Dispose();
					keyboardHydrationRoutine = null;
				}
				keyboardHydrationRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(RunShowKeyboardRoutine(parentTransform));
				this.token = token;
			}
		}

		public void ShowKeyboard(object token, Vector3 worldPosition, Quaternion worldRotation)
		{
			if (!IsOpen || this.token != token)
			{
				if (keyboardHydrationRoutine != null)
				{
					keyboardHydrationRoutine.Dispose();
					keyboardHydrationRoutine = null;
				}
				keyboardHydrationRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(RunShowKeyboardRoutine(worldPosition, worldRotation));
				this.token = token;
			}
		}

		public void HideKeyboard(object token, bool immediate = false)
		{
			if (IsOpen && token == this.token)
			{
				HideKeyboard(immediate);
			}
		}

		public void ForceHideKeyboard(bool immediate)
		{
			HideKeyboard(immediate);
		}

		private void HideKeyboard(bool immediate)
		{
			if (IsOpen)
			{
				if (keyboardHydrationRoutine != null)
				{
					keyboardHydrationRoutine.Dispose();
					keyboardHydrationRoutine = null;
				}
				keyboardHydrationRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(RunHideKeyboardRoutine(immediate));
				token = null;
			}
		}

		private IEnumerator<ISchedule> RunShowKeyboardRoutine(Transform parentTransform)
		{
			IsOpen = true;
			base.transform.SetParent(parentTransform, worldPositionStays: false);
			punchkeyboard.KeysEnabled = false;
			animator.SetBool("KeyboardActive", value: true);
			yield return Schedule.Wait(0.3f);
			punchkeyboard.KeysEnabled = true;
		}

		private IEnumerator<ISchedule> RunShowKeyboardRoutine(Vector3 worldPosition, Quaternion worldRotation)
		{
			IsOpen = true;
			base.transform.position = worldPosition;
			base.transform.rotation = worldRotation;
			punchkeyboard.KeysEnabled = false;
			animator.SetBool("KeyboardActive", value: true);
			yield return Schedule.Wait(0.3f);
			punchkeyboard.KeysEnabled = true;
		}

		private IEnumerator<ISchedule> RunHideKeyboardRoutine(bool immediate)
		{
			if (!immediate)
			{
				punchkeyboard.KeysEnabled = false;
				animator.SetBool("KeyboardActive", value: false);
				yield return Schedule.Wait(0.3f);
			}
			base.transform.SetParent(originalParent, worldPositionStays: false);
			IsOpen = false;
		}

		private void OnPunchkeyboardKeyPressed()
		{
			if (OnAnyKeyPressed != null)
			{
				OnAnyKeyPressed();
			}
		}
	}
}
public class BasicInteractionRestriction : UIInteractionRestriction
{
	private bool _allElementsRestricted;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<bool> m_OnRestrictionUpdated;

	private HashSet<Selectable> specificAllowedElements = new HashSet<Selectable>();

	private HashSet<Selectable> specificRestrictedElements = new HashSet<Selectable>();

	public bool HasAnyActiveRestrictions => AllElementsRestricted || specificAllowedElements.Count > 0 || specificRestrictedElements.Count > 0;

	public bool AllElementsRestricted
	{
		get
		{
			return _allElementsRestricted;
		}
		set
		{
			_allElementsRestricted = value;
			if (_allElementsRestricted)
			{
				AllowOnlyThisItem = null;
			}
			UpdateRestrictionsCallback();
		}
	}

	public Selectable AllowOnlyThisItem
	{
		set
		{
			if (value != null)
			{
				AllElementsRestricted = false;
				specificAllowedElements.Clear();
				AddToAllowedSet(value);
			}
			else
			{
				specificAllowedElements.Clear();
				UpdateRestrictionsCallback();
			}
		}
	}

	public event Action<bool> OnRestrictionUpdated
	{
		add
		{
			Action<bool> action = this.m_OnRestrictionUpdated;
			Action<bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnRestrictionUpdated, (Action<bool>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<bool> action = this.m_OnRestrictionUpdated;
			Action<bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnRestrictionUpdated, (Action<bool>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void UpdateRestrictionsCallback()
	{
		if (this.OnRestrictionUpdated != null)
		{
			bool flag = specificAllowedElements.Count > 0;
			this.OnRestrictionUpdated(flag || AllElementsRestricted);
		}
	}

	public void AddToAllowedSet(Selectable element)
	{
		specificAllowedElements.Add(element);
		UpdateRestrictionsCallback();
	}

	public void RemoveFromAllowedSet(Selectable element)
	{
		specificAllowedElements.Remove(element);
		UpdateRestrictionsCallback();
	}

	public void RestrictElement(Selectable element, bool restricted)
	{
		if (restricted)
		{
			specificRestrictedElements.Add(element);
		}
		else
		{
			specificRestrictedElements.Remove(element);
		}
		UpdateRestrictionsCallback();
	}

	public override bool CanInteract(Selectable selectable)
	{
		if (specificAllowedElements.Count > 0)
		{
			return specificAllowedElements.Contains(selectable);
		}
		return !AllElementsRestricted && !specificRestrictedElements.Contains(selectable);
	}
}
