		private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

		public static string FullConfigAssetFilePath => CustomSettingsLoader.GetTrimmedFilePath("Assets/Core/Content/Configs/");

		public static string FullConfigAssetFileName => CustomSettingsLoader.GetAssetFileName<ContextualEmotesConfig>() + ".asset";

		public static string FullConfigAssetFilePathAndFileName => $"{FullConfigAssetFilePath}/{FullConfigAssetFileName}";

		public static ContextualEmotesConfig.ExpressoEmote GetExpressoEmote(string emoteName)
		{
			if (ConfigAsset != null && ConfigAsset.Emotes != null)
			{
				for (int i = 0; i < ConfigAsset.Emotes.Length; i++)
				{
					if (ConfigAsset.Emotes[i].emoteUniqueName.Equals(emoteName))
					{
						return ConfigAsset.Emotes[i];
					}
				}
			}
			return null;
		}

		public static ContextualEmotesConfig.ExpressoEmote GetExpressoEmote(int emoteConfigIndex)
		{
			if (ConfigAsset != null && ConfigAsset.Emotes != null && emoteConfigIndex >= 0 && ConfigAsset.Emotes.Length > emoteConfigIndex)
			{
				return ConfigAsset.Emotes[emoteConfigIndex];
			}
			return null;
		}

		public static int GetExpressoEmoteConfigIndex(string emoteName)
		{
			if (ConfigAsset != null && ConfigAsset.Emotes != null)
			{
				for (int i = 0; i < ConfigAsset.Emotes.Length; i++)
				{
					if (ConfigAsset.Emotes[i].emoteUniqueName.Equals(emoteName))
					{
						return i;
					}
				}
			}
			return -1;
		}
