	public class ExpressoButton : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public class ExpressoButtonInteraction : UnityEvent
		{
		}

		public enum ExpressoButtonState
		{
			Disabled = -1,
			Idle,
			Enter,
			Stay,
			Exit
		}

		public int ButtonIndex;

		[SerializeField]
		private GameObject triggerVolume;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private BoxCollider interactionCollider;

		[Header("Interactions")]
		public bool CloseMenuOnInteraction = true;

		public ExpressoButtonInteraction OnInteractionEnter;

		public ExpressoButtonInteraction OnInteractionStay;

		public ExpressoButtonInteraction OnInteractionExit;

		public ExpressoButtonInteraction OnButtonActivated;

		public ExpressoButtonInteraction OnButtonDeactivated;

		[Header("Audio and Visuals")]
		public RecRoomAudioClip enterAudio;

		public RecRoomAudioClip stayAudio;

		public RecRoomAudioClip exitAudio;

		public float exitAnimationDuration = 0.25f;

		[SerializeField]
		private UnityEngine.UI.Image toggledIcon;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, true)]
		private UnityEngine.UI.Image buttonIcon;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private Text buttonLabel;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private Animator animator;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, true)]
		private RectTransform UICanvasTransfrom;

		private ExpressoUIFlow parentFlow;

		private static readonly int buttonStateHash = Animator.StringToHash("State");

		private ExpressoButtonState currentButtonState;

		private SFXAudioSource stayInteractionAudioSource;

		private Collider[] collidersInTrigger = new Collider[16];

		private bool _active = true;

		public bool Active
		{
			get
			{
				return _active;
			}
			set
			{
				bool flag = _active != value;
				_active = value;
				if (!flag)
				{
					return;
				}
				triggerVolume.SetActive(_active);
				if (_active)
				{
					base.gameObject.SetActive(_active);
					if (OnButtonActivated != null)
					{
						OnButtonActivated.Invoke();
					}
				}
				else
				{
					if (OnButtonDeactivated != null)
					{
						OnButtonDeactivated.Invoke();
					}
					if (currentButtonState > ExpressoButtonState.Idle)
					{
						StartCoroutine(RunDisable());
					}
					else
					{
						base.gameObject.SetActive(value: false);
					}
				}
				currentButtonState = ExpressoButtonState.Idle;
			}
		}

		public ExpressoButtonState ButtonState => currentButtonState;

		public GameObject TriggerVolume => triggerVolume;

		public UnityEngine.UI.Image Icon => buttonIcon;

		public Text Label => buttonLabel;

		public bool Toggled
		{
			get
			{
				return toggledIcon != null && toggledIcon.enabled;
			}
			set
			{
				if (toggledIcon != null)
				{
					toggledIcon.enabled = value;
				}
			}
		}

		private void Awake()
		{
			parentFlow = GetComponentInParent<ExpressoUIFlow>();
			if (parentFlow != null)
			{
				UICanvasTransfrom.rotation = parentFlow.transform.rotation;
			}
		}

		private void Start()
		{
			ExpressoButtonConfig activityExpressoButtonConfig = Player.LocalPlayer.PlayerUI.ExpressoMenu.GetActivityExpressoButtonConfig(ButtonIndex);
			if (activityExpressoButtonConfig != null)
			{
				buttonIcon.sprite = activityExpressoButtonConfig.buttonIcon;
				buttonLabel.text = activityExpressoButtonConfig.buttonLabel;
				CloseMenuOnInteraction = activityExpressoButtonConfig.CloseMenuOnInteraction;
				OnButtonActivated = activityExpressoButtonConfig.OnButtonActivated;
				OnButtonDeactivated = activityExpressoButtonConfig.OnButtonDeactivated;
				OnInteractionEnter = activityExpressoButtonConfig.OnInteractionEnter;
				OnInteractionStay = activityExpressoButtonConfig.OnInteractionStay;
				OnInteractionExit = activityExpressoButtonConfig.OnInteractionExit;
			}
			buttonIcon.enabled = buttonIcon.sprite != null;
			buttonLabel.enabled = !string.IsNullOrEmpty(buttonLabel.text);
		}

		private void Update()
		{
			if (Active)
			{
				UpdateButtonState();
			}
		}

		private void TriggerInteractionDelegate(ExpressoButtonInteraction interaction)
		{
			interaction?.Invoke();
			if (CloseMenuOnInteraction)
			{
				Player.LocalPlayer.PlayerUI.ExpressoMenu.ShowUI(show: false);
			}
		}

		private void UpdateButtonState()
		{
			PlayerHand playerHand = CheckButtonHandCollisions();
			ExpressoButtonState expressoButtonState = currentButtonState;
			if (playerHand != null)
			{
				switch (currentButtonState)
				{
				case ExpressoButtonState.Idle:
					currentButtonState = ExpressoButtonState.Enter;
					if (enterAudio != null)
					{
						AudioManager.Play3DSFX(enterAudio, base.transform);
					}
					TriggerInteractionDelegate(OnInteractionEnter);
					break;
				case ExpressoButtonState.Enter:
					currentButtonState = ExpressoButtonState.Stay;
					break;
				case ExpressoButtonState.Stay:
					TriggerInteractionDelegate(OnInteractionStay);
					if (stayAudio != null && stayInteractionAudioSource == null)
					{
						stayInteractionAudioSource = AudioManager.StartLooping3DSFX(stayAudio, base.transform);
					}
					break;
				}
			}
			else
			{
				if (currentButtonState == ExpressoButtonState.Stay || currentButtonState == ExpressoButtonState.Enter)
				{
					TriggerInteractionDelegate(OnInteractionExit);
					if (stayInteractionAudioSource != null)
					{
						stayInteractionAudioSource.Stop();
						stayInteractionAudioSource = null;
					}
					if (exitAudio != null)
					{
						AudioManager.Play3DSFX(exitAudio, base.transform);
					}
				}
				currentButtonState = ExpressoButtonState.Idle;
			}
			if (currentButtonState != expressoButtonState)
			{
				animator.SetIntegerIfActive(buttonStateHash, (int)currentButtonState);
			}
		}

		private PlayerHand CheckButtonHandCollisions()
		{
			Vector3 halfExtents = interactionCollider.size / 2f;
			halfExtents.x *= interactionCollider.transform.localScale.x;
			halfExtents.y *= interactionCollider.transform.localScale.y;
			halfExtents.z *= interactionCollider.transform.localScale.z;
			int num = Physics.OverlapBoxNonAlloc(interactionCollider.transform.position + interactionCollider.center, halfExtents, collidersInTrigger, interactionCollider.transform.rotation);
			PlayerHand result = null;
			if (num > 0)
			{
				PlayerHand playerHand = null;
				for (int i = 0; i < num; i++)
				{
					playerHand = collidersInTrigger[i].GetColliderPlayerHand();
					if (playerHand != null && playerHand == Player.LocalPlayer.PlayerUI.ExpressoMenu.OperatingHand)
					{
						result = playerHand;
						break;
					}
				}
			}
			return result;
		}

		private IEnumerator RunDisable()
		{
			float startTime = UnityEngine.Time.time;
			while (UnityEngine.Time.time - startTime < exitAnimationDuration)
			{
				animator.SetIntegerIfActive(buttonStateHash, 1);
				yield return null;
			}
			base.gameObject.SetActive(value: false);
		}
	}
