	public class ExpressoUI : UnityEngine.MonoBehaviour
	{
		public enum InteractionType
		{
			Translate,
			Twist
		}

		[SerializeField]
		private ExpressoUIFlow rootFlowPrefab;

		[SerializeField]
		private RecRoomAudioClip showUIAudio;

		[SerializeField]
		private bool alignToHandRotation;

		[SerializeField]
		private ActivitySpecificExpressoButtonConfigs[] activitySpecificButtonConfigs;

		[Header("Hand following")]
		[SerializeField]
		private float handFollowDuration = 0.1f;

		[SerializeField]
		[Range(0f, 1f)]
		private float initialVelocityMultiplier = 0.95f;

		private bool showing;

		private bool followingHandMomentum;

		private float followingHandStartTime;

		private List<ExpressoUIFlow> flowInstances = new List<ExpressoUIFlow>();

		private Stack<ExpressoUIFlow> flowStack = new Stack<ExpressoUIFlow>();

		private PlayerHand operatingHand;

		public PlayerHand OperatingHand => operatingHand;

		public bool Showing => showing;

		private ExpressoUIFlow CurrentFlow => flowStack.Peek();

		private void Awake()
		{
			ExpressoUIFlow flowFromPrefab = GetFlowFromPrefab(rootFlowPrefab);
			if (flowFromPrefab != null)
			{
				flowFromPrefab.transform.localPosition = Vector3.zero;
				flowFromPrefab.transform.localRotation = Quaternion.identity;
				flowStack.Push(flowFromPrefab);
			}
			else
			{
				UnityEngine.Debug.LogError("Expresso Menu was initialized without a Root Flow.");
			}
		}

		private void FixedUpdate()
		{
			if (followingHandMomentum)
			{
				UpdateFlowPosition();
			}
		}

		public void ShowUI(bool show, PlayerHand hand = null)
		{
			if (show == showing)
			{
				return;
			}
			showing = show;
			if (show)
			{
				operatingHand = hand;
				if (operatingHand != null)
				{
					operatingHand.Vibrate(50);
				}
				if (showUIAudio != null)
				{
					AudioManager.Play3DSFX(showUIAudio, base.transform);
				}
				base.transform.position = hand.transform.position;
				base.transform.rotation = GetMenuRotation();
			}
			else
			{
				while (PopFlow(activateTop: false))
				{
				}
				operatingHand = null;
			}
			Player.LocalPlayer.EmotesManager.LocalChoosingEmote(showing);
			CurrentFlow.Active = show;
		}

		public void PushFlow(ExpressoUIFlow flowPrefab, bool disablePrevious = true, bool displaceAlongHandVelocity = false)
		{
			if (OperatingHand != null)
			{
				OperatingHand.ExpressoInfoGestureActive = false;
			}
			ExpressoUIFlow flowFromPrefab = GetFlowFromPrefab(flowPrefab);
			if (flowFromPrefab != null)
			{
				if (disablePrevious)
				{
					flowStack.Peek().Active = false;
				}
				flowFromPrefab.Active = true;
				flowStack.Push(flowFromPrefab);
				Vector3 position = operatingHand.transform.position;
				if (displaceAlongHandVelocity)
				{
					followingHandStartTime = UnityEngine.Time.time;
					followingHandMomentum = true;
				}
				flowFromPrefab.transform.position = position;
				flowFromPrefab.transform.rotation = GetMenuRotation();
				PlayerHand playerHand = LocalGetMenuHand();
				if (playerHand != null)
				{
					playerHand.Vibrate(200);
				}
			}
		}

		private PlayerHand LocalGetMenuHand()
		{
			if (Player.LocalPlayer.RightHand != null && Player.LocalPlayer.RightHand.MenuHandVisualsActive)
			{
				return Player.LocalPlayer.RightHand;
			}
			if (Player.LocalPlayer.LeftHand != null && Player.LocalPlayer.LeftHand.MenuHandVisualsActive)
			{
				return Player.LocalPlayer.LeftHand;
			}
			return null;
		}

		public bool PopFlow(bool activateTop = true)
		{
			if (flowStack.Count > 1)
			{
				ExpressoUIFlow expressoUIFlow = flowStack.Pop();
				expressoUIFlow.Active = false;
				flowStack.Peek().Active = activateTop;
				return true;
			}
			return false;
		}

		private ExpressoUIFlow GetFlowFromPrefab(ExpressoUIFlow flowPrefab)
		{
			ExpressoUIFlow expressoUIFlow = null;
			foreach (ExpressoUIFlow flowInstance in flowInstances)
			{
				if (flowInstance.UniqueName == flowPrefab.UniqueName)
				{
					expressoUIFlow = flowInstance;
				}
			}
			if (expressoUIFlow == null)
			{
				expressoUIFlow = UnityEngine.Object.Instantiate(flowPrefab, base.transform, worldPositionStays: false);
				flowInstances.Add(expressoUIFlow);
			}
			return expressoUIFlow;
		}

		private void UpdateFlowPosition()
		{
			if (OperatingHand != null && Showing)
			{
				float num = (UnityEngine.Time.time - followingHandStartTime) / handFollowDuration;
				if (num >= 1f)
				{
					followingHandMomentum = false;
					return;
				}
				Vector3 vector = OperatingHand.RigidbodyEx.velocity * Mathf.Lerp(initialVelocityMultiplier, 0f, num);
				CurrentFlow.transform.position += vector * UnityEngine.Time.fixedDeltaTime;
				CurrentFlow.transform.rotation = GetMenuRotation();
			}
		}

		public ExpressoButtonConfig GetActivityExpressoButtonConfig(int buttonIndex)
		{
			ExpressoButtonConfig[] array = null;
			RoomSceneLocations location = GameSessions.LocalGameSession.Location;
			ActivitySpecificExpressoButtonConfigs[] array2 = activitySpecificButtonConfigs;
			foreach (ActivitySpecificExpressoButtonConfigs activitySpecificExpressoButtonConfigs in array2)
			{
				if (AGRoomSettings.GetRoomSceneLocationReplicationId(location) == activitySpecificExpressoButtonConfigs.location.LocationId)
				{
					ExpressoButtonConfig[] buttonConfigs = activitySpecificExpressoButtonConfigs.buttonConfigs;
					foreach (ExpressoButtonConfig expressoButtonConfig in buttonConfigs)
					{
						if (expressoButtonConfig.buttonIndex == buttonIndex)
						{
							return expressoButtonConfig;
						}
					}
				}
				else if (!string.IsNullOrEmpty(activitySpecificExpressoButtonConfigs.location.ToString()))
				{
					array = activitySpecificExpressoButtonConfigs.buttonConfigs;
				}
			}
			if (array != null)
			{
				ExpressoButtonConfig[] array3 = array;
				foreach (ExpressoButtonConfig expressoButtonConfig2 in array3)
				{
					if (expressoButtonConfig2.buttonIndex == buttonIndex)
					{
						return expressoButtonConfig2;
					}
				}
			}
			return null;
		}

		private Quaternion GetMenuRotation()
		{
			Quaternion result = Quaternion.identity;
			if (operatingHand != null)
			{
				if (alignToHandRotation)
				{
					result = operatingHand.transform.rotation;
				}
				else
				{
					Vector3 rhs = Vector3.Cross(Vector3.up, operatingHand.FingerDirection);
					Vector3 upwards = Vector3.Cross(operatingHand.FingerDirection, rhs);
					result = Quaternion.LookRotation(operatingHand.FingerDirection, upwards);
				}
			}
			return result;
		}
	}
	public class ExpressoUIFlow : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Tooltip("The unuqie name for this flow, used for caching purposes instead of TAGS.")]
		private string uniqueName = string.Empty;

		[SerializeField]
		[Tooltip("Whether the previous Expresso flow on the stack should be deactivated when this one is pushed onto the stack")]
		private bool closePreviousMenuOnStart = true;

		[SerializeField]
		[Tooltip("Objects that will be enabled/disabled along with this flow.")]
		private GameObject[] objectsToEnableDisable;

		[Header("Hand following")]
		[SerializeField]
		[Tooltip("If it set to true, this flow will appear ahead of where the hand is moving to avoid accidentally hitting another button as soon as it appears.")]
		private bool leadHandMovementOnStart;

		protected ExpressoButton[] buttons;

		private bool _active;

		public string UniqueName => uniqueName;

		public virtual bool Active
		{
			get
			{
				return _active;
			}
			set
			{
				_active = value;
				if (buttons != null)
				{
					SetAllButtonsActive(_active);
				}
				if (objectsToEnableDisable != null)
				{
					GameObject[] array = objectsToEnableDisable;
					foreach (GameObject gameObject in array)
					{
						gameObject.SetActive(_active);
					}
				}
			}
		}

		protected virtual void Start()
		{
			if (buttons == null || buttons.Length == 0)
			{
				buttons = GetComponentsInChildren<ExpressoButton>(includeInactive: true);
			}
			Active = Active;
		}

		public void PushFlow(ExpressoUIFlow flowPrefab)
		{
			if (Player.LocalPlayer.PlayerUI.ExpressoMenu != null)
			{
				Player.LocalPlayer.PlayerUI.ExpressoMenu.PushFlow(flowPrefab, flowPrefab.closePreviousMenuOnStart, flowPrefab.leadHandMovementOnStart);
			}
		}

		protected void SetAllButtonsActive(bool active)
		{
			ExpressoButton[] array = buttons;
			foreach (ExpressoButton expressoButton in array)
			{
				expressoButton.Active = active;
			}
		}

		public void ExpressoButtonInteracted(string debugString)
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, debugString, 1f);
		}

		public void ExpressoEmote(string emoteName)
		{
			Player.LocalPlayer.EmotesManager.LocalEmote(emoteName);
		}
	}
	public class RootExpressoUIFlow : ExpressoUIFlow
	{
	}
