	public class UtilityExpressoUIFlow : ExpressoUIFlow
	{
		public static bool startedPTT;

		[SerializeField]
		private ExpressoButtonSpawner micFunctionButtonSpawner;

		[SerializeField]
		private ExpressoButtonSpawner emoteBubbleToggleButtonSpawner;

		private ExpressoButton micFunctionButton;

		private Vector3 micFunctionButtonDefaultScale = Vector3.one;

		private ExpressoButton emoteBubbleToggleButton;

		private const float cameraDistanceFromHead = 0.5f;

		public override bool Active
		{
			get
			{
				return base.Active;
			}
			set
			{
				base.Active = value;
				if (micFunctionButton != null)
				{
					micFunctionButton.Toggled = SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.PushToTalk;
					if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.Mute)
					{
						micFunctionButton.gameObject.SetActive(value: false);
					}
				}
			}
		}

		protected override void Start()
		{
			base.Start();
			if (micFunctionButtonSpawner != null)
			{
				micFunctionButton = micFunctionButtonSpawner.GetComponentInChildren<ExpressoButton>();
				if (micFunctionButton != null)
				{
					micFunctionButtonDefaultScale = micFunctionButton.TriggerVolume.transform.localScale;
					micFunctionButton.Toggled = SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.PushToTalk;
					if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.Mute)
					{
						micFunctionButton.gameObject.SetActive(value: false);
					}
				}
			}
			if (emoteBubbleToggleButtonSpawner != null)
			{
				emoteBubbleToggleButton = emoteBubbleToggleButtonSpawner.GetComponentInChildren<ExpressoButton>();
				if (emoteBubbleToggleButton != null)
				{
					emoteBubbleToggleButton.Toggled = Player.LocalPlayer.EmotesManager.UsingEmoteBubble;
				}
			}
		}

		public void SpawnShareCameraAndTakePicture()
		{
			if (Player.LocalPlayerExists)
			{
				Tool backpackTool = Player.LocalPlayer.Backpack.GetBackpackTool(PlayerBackpackToolType.SHARE_CAM);
				ShareCamera component = backpackTool.GetComponent<ShareCamera>();
				if (component != null)
				{
					Transform transform = Player.LocalPlayer.Head.transform;
					component.SpawnAndTakePictureAt(transform.position + transform.forward * 0.5f, transform.rotation.RemoveRoll(), isBackCameraActive: true, isTimerActive: false, takePicture: true);
				}
			}
		}

		public void ToggleMicrophoneFunction(bool activate)
		{
			if (!Player.LocalPlayer.UserIsPresent)
			{
				return;
			}
			bool mute = Player.LocalPlayer.Mute;
			if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.PushToTalk)
			{
				Player.LocalPlayer.ExpressoPushToTalkPressed = activate;
			}
			else if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.AlwaysOn)
			{
				Player.LocalPlayer.SetMuteFlag(Player.MuteFlags.EXPRESSO_MUTE, activate);
			}
			if (mute != Player.LocalPlayer.Mute)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Microphone: " + ((!Player.LocalPlayer.Mute) ? "ON" : "OFF"), 1.5f);
			}
			if (micFunctionButton != null)
			{
				ExpressoButton[] array = buttons;
				foreach (ExpressoButton expressoButton in array)
				{
					if (expressoButton != micFunctionButton)
					{
						expressoButton.Active = false;
					}
				}
			}
			GrowMicFunctionButtonCollider(activate);
		}

		public void GrowMicFunctionButtonCollider(bool grow)
		{
			if (micFunctionButton != null)
			{
				if (grow)
				{
					startedPTT = true;
					micFunctionButton.TriggerVolume.transform.localScale *= 2.3f;
				}
				else
				{
					micFunctionButton.TriggerVolume.transform.localScale = micFunctionButtonDefaultScale;
				}
			}
		}

		public void ShowDetachedMenu()
		{
			Player.LocalPlayer.PlayerUI.WatchMenuProjector.AuthorityOpenMenuDetached();
		}

		public void ToggleUsingEmoteBubble()
		{
			Player.LocalPlayer.EmotesManager.ToggleUsingEmoteBubble();
			if (emoteBubbleToggleButton != null)
			{
				emoteBubbleToggleButton.Toggled = Player.LocalPlayer.EmotesManager.UsingEmoteBubble;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Emote bubble: " + ((!Player.LocalPlayer.EmotesManager.UsingEmoteBubble) ? "DISABLED" : "ENABLED"), 1.5f);
			}
		}
	}
