		{
			Relationships.RelationshipUpdated -= RelationshipUpdated;
			Presence.OnPlayerPresenceUpdated -= PlayerPresenceUpdated;
		}
	}

	public override void SetProfile(Profile profile)
	{
		if (base.CurrentProfile != null)
		{
			OnDestroy();
		}
		base.SetProfile(profile);
		RelationshipUpdated(base.CurrentProfile.Id);
		PlayerPresenceUpdated(base.CurrentProfile.Id);
		OnlineStatusChanged();
	}

	private void PlayerPresenceUpdated(long id)
	{
		if (base.CurrentProfile != null && id == (long)base.CurrentProfile.Id)
		{
			PlayerPresence playerPresence = Presence.Get(id);
			IsOnline = playerPresence?.AppearsOnlineToMe ?? false;
			if (StatusType == PlayerResultStatusType.RecNetStatus)
			{
				StatusText = Presence.GetPlayerStatusString(playerPresence);
			}
		}
	}

	private void RelationshipUpdated(long? playerId)
	{
		if (base.CurrentProfile != null && (!playerId.HasValue || (playerId.GetValueOrDefault() == (long)base.CurrentProfile.Id && playerId.HasValue)))
		{
			Relationship relationship = Relationships.Get(base.CurrentProfile.Id);
			if (StatusType == PlayerResultStatusType.RelationshipStatus)
			{
				GetStatusTextFromRelationship(relationship);
			}
			CanSendFriendRequest = base.CurrentProfile.CanSendFriendRequest();
		}
	}

	private void GetStatusTextFromRelationship(Relationship relationship)
	{
		if (relationship == null)
		{
			StatusText = "Not friends yet!";
			return;
		}
		switch (relationship.Type)
		{
		case Relationship.RelationshipType.None:
			StatusText = "Not friends yet!";
			break;
		case Relationship.RelationshipType.FriendRequestSent:
			StatusText = "Already sent request!";
			break;
		case Relationship.RelationshipType.FriendRequestReceived:
			StatusText = "Already receieved request!";
			break;
		case Relationship.RelationshipType.Friend:
			StatusText = "Already friends!";
			break;
		}
	}

	public void SendFriendRequest()
	{
		if (CanSendFriendRequest)
		{
			StartCoroutine(SendFriendRequestRoutine());
		}
		else
		{
			UnityEngine.Debug.Log("Can't send friend request");
		}
	}

	private IEnumerator SendFriendRequestRoutine()
	{
		yield return Relationships.SendFriendRequest(base.CurrentProfile.Id, delegate(string e)
		{
			if (string.IsNullOrEmpty(e))
			{
				if (Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerEvents.AddedFriend((int)(long)base.CurrentProfile.Id);
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("Error sending friend request:" + e);
			}
		});
	}

	[SkipRename]
	public void Button_SendFriendRequest()
	{
		SendFriendRequest();
	}

	[SkipRename]
	public void Button_ShowMore()
	{
		if (ShowDetailsAction != null)
		{
			ShowDetailsAction.Invoke(base.CurrentProfile);
		}
	}
}
