namespace AGUI.Inputs
{
	public class KeyboardInputField : UnityEngine.MonoBehaviour, ISubmitHandler, IEventSystemHandler
	{
		public readonly ActionEvent<string> Submitted = new ActionEvent<string>(0);

		public readonly ActionEvent DeselectedWithoutSubmit = new ActionEvent(0);

		[SerializeField]
		[Autofill(AutofillType.SelfAndParent, false)]
		private TMP_InputField inputField;

		[SerializeField]
		private bool deselectOnSubmit = true;

		private int lastSubmitFrame = -1;

		public static TMP_InputField FocusedInputField
		{
			get
			{
				KeyboardInputField focusedInputField = KeyboardInputFieldManager.Instance.FocusedInputField;
				if (focusedInputField != null)
				{
					return focusedInputField.inputField;
				}
				return null;
			}
		}

		public TMP_InputField InputField => inputField;

		private void Awake()
		{
			KeyboardInputFieldManager.Instance.Register(this);
			inputField.onEndEdit.AddListener(delegate
			{
				if (inputField.lineType != TMP_InputField.LineType.MultiLineNewline && (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter)))
				{
					HandleSubmit();
				}
				else if (base.gameObject.activeInHierarchy)
				{
					this.EndOfFrameRoutine(OnEndEditWithoutSubmit);
				}
				else
				{
					OnEndEditWithoutSubmit();
				}
			});
		}

		private void OnDestroy()
		{
			KeyboardInputFieldManager.Instance.Unregister(this);
		}

		public void OnSubmit(BaseEventData eventData)
		{
			HandleSubmit();
		}

		private void OnEndEditWithoutSubmit()
		{
			if (UnityEngine.Time.frameCount > lastSubmitFrame + 1)
			{
				DeselectedWithoutSubmit.Invoke();
			}
		}

		private void HandleSubmit()
		{
			lastSubmitFrame = UnityEngine.Time.frameCount;
			this.EndOfFrameRoutine(delegate
			{
				if (deselectOnSubmit)
				{
					EventSystem.current.SetSelectedGameObject(null);
				}
				else
				{
					EventSystem.current.SetSelectedGameObject(inputField.gameObject);
				}
			});
			Submitted.Invoke(inputField.text);
		}
	}
	public class KeyboardInputFieldManager : UnityEngine.MonoBehaviour
	{
		private static KeyboardInputFieldManager _instance;

		private List<KeyboardInputField> keyboardInputs = new List<KeyboardInputField>();

		public static KeyboardInputFieldManager Instance
		{
			get
			{
				if (_instance == null)
				{
					GameObject gameObject = new GameObject("KeyboardInputFieldManager");
					gameObject.hideFlags = HideFlags.HideAndDontSave;
					UnityEngine.Object.DontDestroyOnLoad(gameObject);
					_instance = gameObject.AddComponent<KeyboardInputFieldManager>();
				}
				return _instance;
			}
		}

		public KeyboardInputField FocusedInputField { get; private set; }

		private void Update()
		{
			FocusedInputField = FindFocusedInputField(FocusedInputField);
		}

		public void Register(KeyboardInputField inputField)
		{
			keyboardInputs.Add(inputField);
		}

		public void Unregister(KeyboardInputField inputField)
		{
			keyboardInputs.Remove(inputField);
		}

		private KeyboardInputField FindFocusedInputField(KeyboardInputField prevFocusedField)
		{
			GameObject currentSelectedGameObject = EventSystem.current.currentSelectedGameObject;
			if (currentSelectedGameObject != null)
			{
				foreach (KeyboardInputField keyboardInput in keyboardInputs)
				{
					if (keyboardInput.gameObject == currentSelectedGameObject && keyboardInput.gameObject.activeInHierarchy)
					{
						return keyboardInput;
					}
				}
			}
			return null;
		}
	}
}
public class LoadingRotate : UnityEngine.MonoBehaviour
{
	private Quaternion originalRotation;

	[SerializeField]
	private float rotationSpeed = 360f;

	private bool rotate = true;

	private void Awake()
	{
		originalRotation = base.transform.localRotation;
	}

	private void OnEnable()
	{
		base.transform.localRotation = originalRotation;
	}

	private void Update()
	{
		if (rotate)
		{
			Quaternion quaternion = Quaternion.AngleAxis(UnityEngine.Time.deltaTime * (0f - rotationSpeed), new Vector3(0f, 0f, 1f));
			base.transform.localRotation *= quaternion;
		}
		else if (base.transform.rotation != originalRotation)
		{
			base.transform.localRotation = originalRotation;
		}
	}

	public void Stop()
	{
		rotate = false;
	}

	public void Start()
	{
		rotate = true;
	}
}
