	public class PagedGrid : PagedGrid<Transform>
	{
	}
	public abstract class PagedGrid<ListType> : VirtualPagedGrid<ListType> where ListType : UnityEngine.Component
	{
		protected List<ListType> AllChildren = new List<ListType>();

		private List<ListType> ignoredChildren;

		private bool childrenSet;

		protected virtual void Start()
		{
			if (!childrenSet)
			{
				RefreshChildren();
			}
		}

		public void AddIgnoredChild(ListType child)
		{
			if (ignoredChildren == null)
			{
				ignoredChildren = new List<ListType>();
			}
			ignoredChildren.Add(child);
			DeactivateChild(child);
			child.gameObject.hideFlags = HideFlags.NotEditable;
		}

		public void RemoveIgnoredChild(ListType child)
		{
			child.gameObject.hideFlags = HideFlags.None;
			if (ignoredChildren != null && ignoredChildren.Remove(child))
			{
				ActivateChild(child);
			}
		}

		public override void UpdateGrid()
		{
			if (AllChildren.Count > 0)
			{
				base.UpdateGrid();
			}
		}

		public void RefreshChildren(bool includeDisabled = false)
		{
			AllChildren = CollectChildren(includeDisabled);
			SetAllActiveChildren(AllChildren);
			childrenSet = true;
		}

		protected virtual void ActivateChild(ListType child)
		{
			child.gameObject.SetActive(value: true);
		}

		protected virtual void DeactivateChild(ListType child)
		{
			child.gameObject.SetActive(value: false);
		}

		protected override void ActivateCurrentPageActiveChildren(IList<ListType> activeChildren)
		{
			for (int i = 0; i < AllChildren.Count; i++)
			{
				ListType val = AllChildren[i];
				if (activeChildren.Contains(val))
				{
					ActivateChild(val);
				}
				else
				{
					DeactivateChild(val);
				}
			}
		}

		private List<ListType> CollectChildren(bool includeDisabled)
		{
			List<ListType> list = new List<ListType>(gridBaseTransform.childCount);
			foreach (object item in gridBaseTransform)
			{
				Transform transform = item as Transform;
				if (includeDisabled || transform.gameObject.activeSelf)
				{
					ListType component = transform.GetComponent<ListType>();
					if (component != null && (ignoredChildren == null || !ignoredChildren.Contains(component)))
					{
						list.Add(component);
					}
				}
			}
			return list;
		}

		protected override void EditorVerifyPrefab()
		{
		}
	}
	public abstract class RecyclerPagedGrid<ListType, GridMemberType> : VirtualPagedGrid<ListType> where GridMemberType : UnityEngine.Component
	{
		[Header("Children")]
		[SerializeField]
		protected GridMemberType childPrefab;

		[SerializeField]
		protected LayoutElement spacerElement;

		protected List<GridMemberType> childUIElements = new List<GridMemberType>();

		protected virtual void Awake()
		{
			if (childUIElements.Count < base.PageSize)
			{
				AddChildUIElements(base.PageSize - childUIElements.Count);
			}
		}

		private void AddChildUIElements(int number)
		{
			for (int i = 0; i < number; i++)
			{
				GridMemberType val = UnityEngine.Object.Instantiate(childPrefab);
				SetupNewChild(val);
				AddChild(val, updateGrid: false);
			}
			if (spacerElement != null)
			{
				spacerElement.transform.SetAsLastSibling();
			}
		}

		public virtual void SetLoading()
		{
			SetAllActiveChildren(Enumerable.Empty<ListType>());
			UIHelper.SafeSetText(emptyDisplayText, "Loading...");
		}

		protected override void SetAllActiveChildren(IEnumerable<ListType> allActiveChildren, bool resetPage = true)
		{
			if (childUIElements.Count < base.PageSize)
			{
				AddChildUIElements(base.PageSize - childUIElements.Count);
			}
			base.SetAllActiveChildren(allActiveChildren, resetPage);
		}

		protected virtual void SetupNewChild(GridMemberType newGridMember)
		{
		}

		protected abstract void SetChild(ListType item, GridMemberType uiElement, int activeIndex);

		protected override void ActivateCurrentPageActiveChildren(IList<ListType> activeChildren)
		{
			int num = 0;
			for (int i = 0; i < childUIElements.Count; i++)
			{
				bool flag = i < activeChildren.Count;
				GridMemberType val = childUIElements[i];
				val.gameObject.SetActive(flag);
				if (flag)
				{
					SetChild(activeChildren[i], childUIElements[i], num++);
				}
			}
		}

		public override void SetPageSize(int value, bool updateGrid = true)
		{
			if (childUIElements.Count < value)
			{
				AddChildUIElements(value - childUIElements.Count);
				StackedUIFlowBase componentInParent = GetComponentInParent<StackedUIFlowBase>();
				if (componentInParent != null)
				{
					componentInParent.RefreshResizableElements();
				}
			}
			base.SetPageSize(value, updateGrid);
		}

		private void AddChild(GridMemberType child, bool updateGrid = true)
		{
			child.transform.SetParent(gridBaseTransform, worldPositionStays: false);
			childUIElements.Add(child);
			if (updateGrid)
			{
				UpdateGrid();
			}
		}
	}
	public abstract class VirtualPagedGrid : UnityEngine.MonoBehaviour
	{
		[Header("Displays")]
		[SerializeField]
		protected GameObject emptyDisplay;

		[SerializeField]
		protected TextMeshProUGUI emptyDisplayText;

		[SerializeField]
		protected GameObject nonEmptyInfoText;

		[SerializeField]
		protected RectTransform gridBaseTransform;

		[Header("Paging")]
		[SerializeField]
		protected RectTransform pageControls;

		[SerializeField]
		private Selectable previousPageButton;

		[SerializeField]
		private Selectable nextPageButton;

		[SerializeField]
		protected PageDisplay pageDisplay;

		[SerializeField]
		[FormerlySerializedAs("PageSize")]
		[Range(1f, 40f)]
		private int pageSize = 6;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_PageChangeEvent;

		private int currentPage;

		public Selectable PreviousPageButton => previousPageButton;

		public Selectable NextPageButton => nextPageButton;

		public int PageSize => pageSize;

		public int TotalPages { get; protected set; }

		public int CurrentPage => currentPage;

		public event Action PageChangeEvent
		{
			add
			{
				Action action = this.m_PageChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_PageChangeEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_PageChangeEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_PageChangeEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public void SetEmptyDisplayText(string newText)
		{
			if (emptyDisplayText != null)
			{
				emptyDisplayText.text = newText;
			}
		}

		public virtual void SetPageSize(int value, bool updateGrid = true)
		{
			value = Mathf.Max(1, value);
			if (pageSize != value)
			{
				int num = currentPage * pageSize;
				pageSize = value;
				CalculateTotalPages();
				int num2 = 0;
				if (pageSize != 0)
				{
					num2 = num / pageSize;
				}
				if (num2 != CurrentPage)
				{
					SetCurrentPage(num2, updateGrid: false);
				}
				if (updateGrid)
				{
					UpdateGrid();
				}
			}
		}

		public void SetCurrentPage(int page, bool updateGrid = true)
		{
			page = Mathf.Clamp(page, 0, TotalPages - 1);
			if (currentPage != page)
			{
				currentPage = page;
				if (updateGrid)
				{
					UpdateGrid();
				}
				if (this.PageChangeEvent != null)
				{
					this.PageChangeEvent();
				}
			}
		}

		public abstract void UpdateGrid();

		protected abstract void CalculateTotalPages();

		[SkipRename]
		public void Button_GoBack()
		{
			int page = ((CurrentPage - 1 >= 0) ? (CurrentPage - 1) : 0);
			SetCurrentPage(page);
		}

		[SkipRename]
		public void Button_GoForward()
		{
			int page = ((CurrentPage + 1 >= TotalPages) ? (TotalPages - 1) : (CurrentPage + 1));
			SetCurrentPage(page);
		}

		public void EditorWillSavePrefab()
		{
			if (!UnityEngine.Application.isPlaying)
			{
				EditorVerifyPrefab();
			}
		}

		protected virtual void EditorVerifyPrefab()
		{
		}
	}
	public abstract class VirtualPagedGrid<ListType> : VirtualPagedGrid
	{
		private List<ListType> _allActiveChildren = new List<ListType>();

		protected List<ListType> AllActiveChildren
		{
			get
			{
				return _allActiveChildren;
			}
			private set
			{
				_allActiveChildren = value;
			}
		}

		protected virtual void SetAllActiveChildren(IEnumerable<ListType> allActiveChildren, bool resetPage = true)
		{
			AllActiveChildren = allActiveChildren.ToList();
			if (resetPage)
			{
				SetCurrentPage(0, updateGrid: false);
			}
			UpdateGrid();
		}

		protected virtual void ActivateCurrentPageActiveChildren(IList<ListType> activeChildren)
		{
		}

		public override void UpdateGrid()
		{
			int count = AllActiveChildren.Count;
			if (emptyDisplay != null)
			{
				emptyDisplay.SetActive(count == 0);
				gridBaseTransform.gameObject.SetActive(count != 0);
			}
			if (nonEmptyInfoText != null)
			{
				nonEmptyInfoText.SetActive(count > 0);
			}
			CalculateTotalPages();
			SetCurrentPage(base.CurrentPage, updateGrid: false);
			if (pageControls != null)
			{
				pageControls.gameObject.SetActive(base.TotalPages > 1);
			}
			if (base.PreviousPageButton != null)
			{
				base.PreviousPageButton.interactable = base.CurrentPage > 0;
			}
			if (base.NextPageButton != null)
			{
				base.NextPageButton.interactable = base.CurrentPage < base.TotalPages - 1;
			}
			if (pageDisplay != null)
			{
				pageDisplay.UpdatePageDisplay(base.CurrentPage, base.TotalPages);
			}
			CalculateAndActivateChildren();
			LayoutRebuilder.MarkLayoutForRebuild(gridBaseTransform);
			if (pageControls != null)
			{
				LayoutRebuilder.MarkLayoutForRebuild((RectTransform)pageControls.transform);
			}
		}

		protected virtual void CalculateAndActivateChildren()
		{
			int skip = base.CurrentPage * base.PageSize;
			List<ListType> activeChildren = AllActiveChildren.SkipTake(skip, base.PageSize).ToList();
			ActivateCurrentPageActiveChildren(activeChildren);
		}

		protected override void CalculateTotalPages()
		{
			int count = AllActiveChildren.Count;
			base.TotalPages = ((count == 0) ? 1 : ((count + base.PageSize - 1) / base.PageSize));
		}
	}
	public class PageDisplay : UnityEngine.MonoBehaviour
	{
		[Header("Dot Display")]
		[SerializeField]
		private RectTransform dotDisplay;

		[SerializeField]
		private RectTransform[] dots = new RectTransform[0];

		[SerializeField]
		private Vector3 smallDotScale = new Vector3(0.5f, 0.5f, 0.5f);

		[Header("Text Display")]
		[SerializeField]
		private RectTransform textDisplay;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private TextMeshProUGUI pagingText;

		public void UpdatePageDisplay(int currentPage, int totalPages)
		{
			bool flag = totalPages > dots.Length;
			textDisplay.gameObject.SetActive(flag);
			dotDisplay.gameObject.SetActive(!flag);
			if (flag)
			{
				pagingText.text = $"{currentPage + 1} / {totalPages}";
				return;
			}
			for (int i = 0; i < dots.Length; i++)
			{
				bool flag2 = i == currentPage;
				RectTransform rectTransform = dots[i];
				rectTransform.localScale = ((!flag2) ? smallDotScale : Vector3.one);
				rectTransform.gameObject.SetActive(i < totalPages);
			}
		}
	}
}
