public class PlayerEventSpecificText : UnityEngine.MonoBehaviour
{
	public enum PlayerEventTextField
	{
		Name,
		Description
	}

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private PlayerEventSpecificUIBehaviour playerEventWatcher;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private TextMeshProUGUI text;

	[SerializeField]
	private PlayerEventTextField playerEventPropertyToWatch;

	protected virtual void Awake()
	{
		playerEventWatcher = GetComponent<PlayerEventSpecificUIBehaviour>();
		playerEventWatcher.PlayerEventUpdated += new Action<PlayerEvent>(OnPlayerEventUpdated);
	}

	protected virtual void OnDestroy()
	{
		if (playerEventWatcher != null)
		{
			playerEventWatcher.PlayerEventUpdated -= new Action<PlayerEvent>(OnPlayerEventUpdated);
		}
	}

	protected virtual void OnEnable()
	{
		OnPlayerEventUpdated(playerEventWatcher.PlayerEventData);
	}

	private void OnPlayerEventUpdated(PlayerEvent eventData)
	{
		if (eventData == null)
		{
			text.text = string.Empty;
			return;
		}
		switch (playerEventPropertyToWatch)
		{
		case PlayerEventTextField.Name:
			text.text = eventData.Name;
			break;
		case PlayerEventTextField.Description:
			text.text = eventData.Description;
			break;
		default:
			text.text = "Unknown field";
			break;
		}
	}
}
namespace AGUI.StackedUI
{
	public class PlayerEventSpecificUIBehaviour : UnityEngine.MonoBehaviour
	{
		public ActionEvent<PlayerEvent> PlayerEventUpdated = new ActionEvent<PlayerEvent>();

		private long playerEventId = -1L;

		public PlayerEvent PlayerEventData { get; private set; }

		private void OnEnable()
		{
			RecNet.PlayerEvents.PlayerEventUpdated += OnPlayerEventUpdated;
			RefreshCachedEvent();
		}

		private void OnDisable()
		{
			RecNet.PlayerEvents.PlayerEventUpdated += OnPlayerEventUpdated;
		}

		private void OnPlayerEventUpdated(PlayerEvent eventData)
		{
			if (eventData != null && eventData.PlayerEventId == playerEventId)
			{
				PlayerEventData = eventData;
				PlayerEventUpdated.Invoke(PlayerEventData);
			}
		}

		public void SetPlayerEventId(long? id)
		{
			if (id.HasValue)
			{
				playerEventId = id.Value;
			}
			else
			{
				playerEventId = -1L;
			}
			RefreshCachedEvent();
			PlayerEventUpdated.Invoke(PlayerEventData);
		}

		private void RefreshCachedEvent()
		{
			PlayerEventData = null;
			if (playerEventId == -1)
			{
				return;
			}
			RecNet.PlayerEvents.GetPlayerEventById(playerEventId).Then(delegate(PlayerEvent eventData)
			{
				if (this != null && eventData.PlayerEventId == playerEventId)
				{
					PlayerEventData = eventData;
					PlayerEventUpdated.Invoke(PlayerEventData);
				}
			});
		}
	}
}
public class PlayerInfoUIControl : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool showGuestUsername = true;

	[SerializeField]
	private TextMeshProUGUI guestText;

	[SerializeField]
	private TextMeshProUGUI displayNameText;

	[SerializeField]
	private TextMeshProUGUI usernameText;

	[SerializeField]
	private TextMeshProUGUI levelText;

	[SerializeField]
	private RawImage profileImage;

	private Profile currentProfile;

	private int Level
	{
		set
		{
			levelText.text = value.ToString();
		}
	}

	public Profile CurrentProfile => currentProfile;

	protected virtual void Start()
	{
		Profiles.OnProfileUpdated += PlayerProfileUpdated;
	}

	protected virtual void OnDestroy()
	{
		Profiles.OnProfileUpdated -= PlayerProfileUpdated;
	}

	private void PlayerProfileUpdated(long id)
	{
		if (CurrentProfile != null && (long)CurrentProfile.Id == id)
		{
			SetProfile(Profiles.Get(id));
		}
	}

	public virtual void SetProfile(Profile profile)
	{
		currentProfile = profile;
		if (profile == null)
		{
			return;
		}
		UIHelper.SafeSetActive(guestText, !profile.Verified);
		UIHelper.SafeSetText(usernameText, "@" + profile.Username);
		UIHelper.SafeSetActive(usernameText, showGuestUsername || profile.Verified);
		UIHelper.SafeSetText(displayNameText, profile.DisplayName);
		UIHelper.SafeSetText(levelText, profile.Level.ToString());
		Images.GetProfileImage(profile).Then(delegate(Texture2D image)
		{
			if (this != null && currentProfile == profile)
			{
				UIHelper.SafeSetTexture(profileImage, image);
			}
		});
	}
