public class ProfileSelectionMenu : UnityEngine.MonoBehaviour
{
	public enum WatchMenuAnimationState
	{
		Hidden,
		Hydrate,
		Visible,
		Dehydrate,
		PlayerMenu_Transition,
		PlayerMenu_Refresh,
		PlayerMenu_KeyboardActive,
		PlayerMenu_KeyboardInactive
	}

	private const float KEYBOARD_HYDRATION_DURATION = 0.3f;

	[SerializeField]
	private GameObject keyboardRoot;

	[SerializeField]
	private AGVirtualKeyboard keyboardPrefab;

	private AGVirtualKeyboard keyboard;

	private Animator Animator;

	private WatchMenuAnimationState menuStateLastUpdate;

	private Dictionary<int, WatchMenuAnimationState> hashStateDictionary = new Dictionary<int, WatchMenuAnimationState>();

	public bool IsMenuOpen { get; private set; }

	public bool IsKeyboardOpen => keyboard != null && keyboard.IsOpen;

	public ProfileSelectionStackedUI playerlessWatchUI { get; private set; }

	public bool IsMenuAnimationVisible => MenuAnimationState != WatchMenuAnimationState.Hidden;

	public WatchMenuAnimationState MenuAnimationState
	{
		get
		{
			if (Animator != null && Animator.gameObject.activeInHierarchy)
			{
				int shortNameHash = Animator.GetCurrentAnimatorStateInfo(0).shortNameHash;
				return hashStateDictionary[shortNameHash];
			}
			return WatchMenuAnimationState.Hidden;
		}
	}

	public AGVirtualKeyboard Keyboard => keyboard;

	private void Awake()
	{
		Animator = base.gameObject.GetComponent<Animator>();
		WatchMenuAnimationState[] array = (WatchMenuAnimationState[])System.Enum.GetValues(typeof(WatchMenuAnimationState));
		for (int i = 0; i < array.Length; i++)
		{
			WatchMenuAnimationState value = array[i];
			string text = value.ToString();
			int key = Animator.StringToHash(text);
			hashStateDictionary[key] = value;
		}
		keyboard = UnityEngine.Object.Instantiate(keyboardPrefab, Vector3.zero, Quaternion.identity);
		keyboard.transform.SetParent(keyboardRoot.transform, worldPositionStays: false);
		keyboard.transform.localPosition = new Vector3(0f, 0f, -0.06f);
		keyboard.transform.localScale = Vector3.one / 3f * 2f;
	}

	private void Update()
	{
		WatchMenuAnimationState watchMenuAnimationState = menuStateLastUpdate;
		menuStateLastUpdate = MenuAnimationState;
		if (MenuAnimationState != watchMenuAnimationState && MenuAnimationState == WatchMenuAnimationState.Hidden)
		{
			SetChildrenActive(active: false);
		}
	}

	public void OpenMenu(bool showkeyboard = false)
	{
		if (!IsMenuOpen)
		{
			IsMenuOpen = true;
			SetChildrenActive(active: true);
			if (showkeyboard)
			{
				ShowKeyboard();
			}
			Animator.SetBool("Visible", value: true);
		}
	}

	public void CloseMenu()
	{
		if (IsMenuOpen)
		{
			IsMenuOpen = false;
			HideKeyboard();
			Animator.SetBool("Visible", value: false);
		}
	}

	public void ShowKeyboard()
	{
		if (keyboard != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
		{
			keyboard.ShowKeyboard(this, keyboardRoot.transform);
		}
	}

	public void HideKeyboard()
	{
		if (keyboard != null)
		{
			keyboard.HideKeyboard(this);
		}
	}

	internal void TriggerTransition()
	{
		Animator.SetTrigger("Transition");
	}

	internal void TriggerRefresh()
	{
		Animator.SetTrigger("Refresh");
	}

	private void SetChildrenActive(bool active)
	{
		for (int i = 0; i < base.transform.childCount; i++)
		{
			GameObject gameObject = base.transform.GetChild(i).gameObject;
			if (gameObject != keyboardRoot)
			{
				gameObject.SetActive(active);
			}
		}
	}
}
