	{
		foreach (StackedUIFlowBase allFlow in base.AllFlows)
		{
			Button3DBase[] componentsInChildren = allFlow.GetComponentsInChildren<Button3DBase>(includeInactive: true);
			Button3DBase[] array = componentsInChildren;
			foreach (Button3DBase button3DBase in array)
			{
				button3DBase.ButtonDownAudio = buttonDownAudio;
				button3DBase.ButtonUpAudio = buttonUpAudio;
			}
		}
