	protected override bool RefreshTopFlowInternal()
	{
		if (Menu != null && Menu.IsMenuAnimationVisible)
		{
			Menu.TriggerRefresh();
		}
		return base.RefreshTopFlowInternal();
	}

	protected override void FlowTransition(StackedUIFlowBase newFlow, StackedUIFlowBase oldFlow)
	{
		base.FlowTransition(newFlow, oldFlow);
		if (Menu != null && Menu.IsMenuAnimationVisible)
		{
			Menu.TriggerTransition();
		}
	}

	protected override void OnUIOpened()
	{
		base.OnUIOpened();
		if (watchOpenAudioSource != null)
		{
			watchOpenAudioSource.Stop();
		}
		if (watchOpenedAudio != null && watchOpenedAudio.audioClip != null)
		{
			watchOpenAudioSource = AudioManager.Play3DSFX(watchOpenedAudio, base.transform);
		}
	}

