	{
		base.OnFlowsInitialized();
		LoginDialog = GetFlowByType<UILoginDialog>();
		if (LoginDialog == null)
		{
			UnityEngine.Debug.LogError("No login dialog found");
		}
		BirthdayDialog = GetFlowByType<UIBirthdayDialog>();
		if (BirthdayDialog == null)
		{
			UnityEngine.Debug.LogError("No birthday dialog found");
		}
		RegistrationDialog = GetFlowByType<UIRegistrationDialog>();
		if (RegistrationDialog == null)
		{
			UnityEngine.Debug.LogError("No registration dialog found");
		}
		VerifyEmailDialog = GetFlowByType<UIVerifyEmailDialog>();
		if (VerifyEmailDialog == null)
		{
			UnityEngine.Debug.LogError("No verify email dialog found");
		}
		AccountStatusDialog = GetFlowByType<UIAccountStatusDialog>();
		if (AccountStatusDialog == null)
		{
			UnityEngine.Debug.LogError("No account selection dialog found");
		}
		StartAccountDialog = GetFlowByType<UIStartAccountCreationDialog>();
		if (StartAccountDialog == null)
		{
			UnityEngine.Debug.LogError("No start account dialog found");
		}
		ScreensModeAccountDialog = GetFlowByType<UIScreensModeAccountCreationDialog>();
		if (ScreensModeAccountDialog == null)
		{
			UnityEngine.Debug.LogError("No screens mode account dialog found");
		}
		ProfileSelectionFlow = GetFlowByType<ProfileSelectionUIFlow>();
