	public IPromise<ConfirmDialogResponses> ShowConfirmationDialog(UIConfirmationDialog.DialogType dialogType, string titleText, string bodyText, string yesText = "Yes", string noText = "No")
	{
		IPromise<ConfirmDialogResponses> result = ConfirmationDialog.ShowDialog(dialogType, titleText, bodyText, yesText, noText);
		PushFlow(ConfirmationDialog);
		return result;
	}

	public IPromise<R> ShowTemporaryDialog<R>(UIDialog<R> dialogPrefab, WatchAttractor.EffectFlags notificationEffects = ~WatchAttractor.EffectFlags.Text)
	{
		UIDialog<R> newDialog = UnityEngine.Object.Instantiate(dialogPrefab, base.transform, worldPositionStays: false);
		if ((bool)newDialog)
		{
			InitializeFlow(newDialog);
			PushFlow(newDialog);
			IPromise<R> promise = newDialog.ShowDialog();
			promise.Then((Action)delegate
			{
				UnityEngine.Object.Destroy(newDialog.gameObject);
			});
			return promise;
		}
		return null;
	}

