		if (titleOverride != null)
		{
			BirthdayDialog.SetTitleText(titleOverride);
		}
		IPromise<DateTime?> result = BirthdayDialog.ShowDialog().Then(delegate(DateTime? date)
		{
			if (onValidDate != null)
			{
				onValidDate(date.Value);
			}
		});
		PushFlow(BirthdayDialog);
		return result;
	}

	public IPromise<ConfirmDialogResponses> ShowAccountStatusDialog(UIAccountStatusDialog.Status status)
