[RequireComponent(typeof(RoomSpecificUIBehaviour))]
public abstract class RoomBasedConditionalButton<T> : ConditionalButton<T> where T : Button3DBase
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	protected RoomSpecificUIBehaviour roomWatcher;

	protected virtual void Awake()
	{
		roomWatcher = GetComponent<RoomSpecificUIBehaviour>();
		roomWatcher.RoomDetailsUpdated += new Action<RoomDetails>(OnRoomUpdated);
		if (roomWatcher.RoomDetails != null)
		{
			OnRoomUpdated(roomWatcher.RoomDetails);
		}
	}

	protected virtual void OnDestroy()
	{
		if (roomWatcher != null)
		{
			roomWatcher.RoomDetailsUpdated -= new Action<RoomDetails>(OnRoomUpdated);
		}
	}

	private void OnRoomUpdated(RoomDetails roomDetails)
	{
		UpdateButtonState();
	}

	protected override void RunButtonAction()
	{
		if (roomWatcher.RoomDetails == null)
		{
			UnityEngine.Debug.LogWarning("Conditional Button attempted button press without room!");
		}
	}

	protected sealed override void UpdateButtonState()
	{
		if (roomWatcher.RoomDetails == null)
		{
			base.ButtonState = 0;
		}
		else
		{
			UpdateRoomBasedButtonState();
		}
	}

	protected abstract void UpdateRoomBasedButtonState();
}
public class RoomDetailConditionalButton : RoomBasedConditionalButton<Button3D>
{
