	protected override void RunButtonAction()
	{
		if (base.ButtonState != 0 && Player.LocalPlayerExists && roomWatcher.RoomDetails != null)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowRoomDetails(roomWatcher.RoomDetails.Room.RoomId);
		}
