[RequireComponent(typeof(RoomSpecificUIBehaviour))]
public class RoomSpecificText : UnityEngine.MonoBehaviour
{
	public enum RoomTextField
	{
		Name,
		Description
	}

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private RoomSpecificUIBehaviour roomwatcher;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private TextMeshProUGUI text;

	[SerializeField]
	private RoomTextField roomPropertyToWatch;

	protected virtual void Awake()
	{
		roomwatcher = GetComponent<RoomSpecificUIBehaviour>();
		roomwatcher.RoomDetailsUpdated += new Action<RoomDetails>(OnRoomUpdated);
	}

	protected virtual void OnDestroy()
	{
		if (roomwatcher != null)
		{
			roomwatcher.RoomDetailsUpdated -= new Action<RoomDetails>(OnRoomUpdated);
		}
	}

	protected virtual void OnEnable()
	{
		OnRoomUpdated(roomwatcher.RoomDetails);
	}

	private void OnRoomUpdated(RoomDetails roomDetails)
	{
		if (roomDetails == null)
		{
			text.text = string.Empty;
			return;
		}
		switch (roomPropertyToWatch)
		{
		case RoomTextField.Name:
			text.text = $"^{roomDetails.Room.Name}";
			break;
		case RoomTextField.Description:
			text.text = roomDetails.Room.Description;
			break;
		default:
			text.text = "Unknown field";
			break;
		}
	}
}
namespace AGUI.StackedUI
{
	public class RoomSpecificUIBehaviour : UnityEngine.MonoBehaviour
	{
		public ActionEvent<RoomDetails> RoomDetailsUpdated = new ActionEvent<RoomDetails>();

		private long roomId = -1L;

		public RoomDetails RoomDetails { get; private set; }

		private void OnEnable()
		{
			RecNet.Rooms.OnRoomDetailsUpdated += OnRoomDetailsUpdated;
			if (roomId != -1)
			{
				OnRoomDetailsUpdated(roomId);
			}
		}

		private void OnDisable()
		{
			RecNet.Rooms.OnRoomDetailsUpdated -= OnRoomDetailsUpdated;
		}

		private void OnRoomDetailsUpdated(long id)
		{
			if (roomId == id)
			{
				RefreshCachedRoom();
			}
		}

		public void SetRoomId(long? id)
		{
			if (id.HasValue)
			{
				roomId = id.Value;
			}
			else
			{
				roomId = -1L;
			}
			RefreshCachedRoom();
			RoomDetailsUpdated.Invoke(RoomDetails);
		}

		private void RefreshCachedRoom()
		{
			if (roomId != -1)
			{
				RoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
			}
			else
			{
				RoomDetails = null;
			}
		}
	}
}
