	[DisallowMultipleComponent]
	public class ChargeButton3D : Button3D
	{
		public delegate void Charged(ChargeButton3D button);

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Charged m_ChargedEvent;

		[SerializeField]
		private UnityEngine.UI.Image fillImage;

		[SerializeField]
		private float chargeDuration = 1f;

		[SerializeField]
		private float vibrationIntensity = 0.5f;

		[SerializeField]
		private RecRoomAudioClip chargeAudio;

		private SFXAudioSource chargeAudioSource;

		private Coroutine chargeRoutine;

		public event Charged ChargedEvent
		{
			add
			{
				Charged charged = this.m_ChargedEvent;
				Charged charged2;
				do
				{
					charged2 = charged;
					charged = Interlocked.CompareExchange(ref this.m_ChargedEvent, (Charged)Delegate.Combine(charged2, value), charged);
				}
				while (charged != charged2);
			}
			remove
			{
				Charged charged = this.m_ChargedEvent;
				Charged charged2;
				do
				{
					charged2 = charged;
					charged = Interlocked.CompareExchange(ref this.m_ChargedEvent, (Charged)Delegate.Remove(charged2, value), charged);
				}
				while (charged != charged2);
			}
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			StopChargeRoutine();
		}

		protected override void PhysicalButtonDownEvent(bool forcedPress = false)
		{
			base.PhysicalButtonDownEvent(forcedPress);
			StopChargeRoutine();
			chargeRoutine = StartCoroutine(ChargeRoutine());
		}

		protected override void PhysicalButtonUpEvent(bool forcedPress = false)
		{
			base.PhysicalButtonUpEvent(forcedPress);
			StopChargeRoutine();
		}

		protected override void PhysicalButtonCanceledEvent()
		{
			base.PhysicalButtonCanceledEvent();
			StopChargeRoutine();
		}

		private IEnumerator ChargeRoutine()
		{
			if (chargeAudio != null)
			{
				chargeAudioSource = AudioManager.Play3DSFX(chargeAudio, base.transform);
			}
			for (float timeElapsed = 0f; timeElapsed < chargeDuration; timeElapsed += UnityEngine.Time.deltaTime)
			{
				if (fillImage != null)
				{
					float fillAmount = timeElapsed / chargeDuration;
					fillImage.fillAmount = fillAmount;
				}
				if (base.MenuFinger != null && base.MenuFinger.isLocal)
				{
					base.MenuFinger.InputHandler.Vibrate(1, vibrationIntensity);
				}
				yield return null;
			}
			if (this.ChargedEvent != null)
			{
				this.ChargedEvent(this);
			}
			StopChargeRoutine();
		}

		private void StopChargeRoutine()
		{
			this.SafeStopCoroutine(chargeRoutine);
			chargeRoutine = null;
			if (chargeAudioSource != null)
			{
				chargeAudioSource.Release();
				chargeAudioSource = null;
			}
			if (fillImage != null)
			{
				fillImage.fillAmount = 0f;
			}
		}
	}
	[DisallowMultipleComponent]
	public abstract class ConditionalButton : UnityEngine.MonoBehaviour
	{
		protected const int DISABLED_STATE = 0;

		private int buttonState = int.MinValue;

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		protected Button3DBase button;

		[SerializeField]
		private TextMeshProUGUI labelText;

		[SerializeField]
		private UnityEngine.UI.Image buttonImage;

		protected int ButtonState
		{
			get
			{
				return buttonState;
			}
			set
			{
				int num = buttonState;
				buttonState = value;
				if (!num.Equals(buttonState))
				{
					UpdateUIForNewButtonState();
					button.Interactable = IsInteractable();
				}
			}
		}

		protected TextMeshProUGUI LabelText => labelText;

		protected UnityEngine.UI.Image ButtonImage => buttonImage;

		public void Button_Action()
		{
			if (button.Interactable)
			{
				RunButtonAction();
			}
		}

		protected virtual void OnEnable()
		{
			UpdateButton();
		}

		public void UpdateButton()
		{
			UpdateButtonState();
			UpdateUIForNewButtonState();
			button.Interactable = IsInteractable();
		}

		protected abstract void UpdateButtonState();

		protected virtual void UpdateUIForNewButtonState()
		{
		}

		protected virtual bool IsInteractable()
		{
			return ButtonState != 0;
		}

		protected abstract void RunButtonAction();
	}
	public abstract class ConditionalButton<T> : ConditionalButton where T : Button3DBase
	{
		public T Button => (T)button;
	}
