{
	public class TextInputUIDialog : UIDialog<TMP_InputField.ContentType, string, string, string, bool, int, TextInputUIDialog.TextValidationFunction, bool, TextInputUIDialog.InputResponse>
	{
		public delegate bool TextValidationFunction(TextMeshProUGUI infoText, string input);

		public struct InputResponse
		{
			public string TextInput;

			public ConfirmDialogResponses Response;
		}

		[SerializeField]
		private TextMeshProUGUI titleText;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private TextMeshProUGUI okText;

		[SerializeField]
		private TextMeshProUGUI infoText;

		private bool purifyText;

		[Autofill(AutofillType.SelfAndChildren, false)]
		[SerializeField]
		private ValidatedButtonInputField textInputField;

		private TextValidationFunction textValidationFunction;

		private static InputResponse cancelResponse = new InputResponse
		{
			Response = ConfirmDialogResponses.Cancel,
			TextInput = string.Empty
		};

		private Coroutine stringCheckRoutine;

		private bool submitEnabled = true;

		public ValidatedButtonInputField TextInputField => textInputField;

		public override IPromise<InputResponse> ShowDialog(TMP_InputField.ContentType contentType, string titleText, string bodyText, string affirmativeText = "Ok", bool purifyText = false, int characterLimit = -1, TextValidationFunction textValidationFunction = null, bool shouldFocusInputField = false)
		{
			this.textValidationFunction = textValidationFunction;
			TextInputField.InputField.contentType = contentType;
			if (characterLimit > 0)
			{
				TextInputField.InputField.characterLimit = characterLimit;
			}
			this.purifyText = purifyText;
			UIHelper.SafeSetText(this.titleText, titleText);
			UIHelper.SafeSetText(this.bodyText, bodyText);
			UIHelper.SafeSetText(okText, affirmativeText);
			if (shouldFocusInputField && TextInputField.InputField3D != null)
			{
				TextInputField.InputField3D.SelectInputField();
			}
			return base.ShowDialog();
		}

		public void Button_Submit()
		{
			if (!submitEnabled)
			{
				return;
			}
			infoText.gameObject.SetActive(value: false);
			submitEnabled = false;
			if (textValidationFunction != null && !textValidationFunction(infoText, textInputField.Text))
			{
				return;
			}
			if (purifyText)
			{
				if (stringCheckRoutine != null)
				{
					StopCoroutine(stringCheckRoutine);
				}
				stringCheckRoutine = StartCoroutine(PurifyAndAccept());
			}
			else
			{
				InputResponse response = new InputResponse
				{
					Response = ConfirmDialogResponses.Affirmative,
					TextInput = textInputField.Text
				};
				Respond(response, shouldCloseDialog: true);
				submitEnabled = true;
			}
		}

		private IEnumerator PurifyAndAccept()
		{
			if (string.IsNullOrEmpty(textInputField.Text))
			{
				InputResponse response = new InputResponse
				{
					Response = ConfirmDialogResponses.Affirmative,
					TextInput = textInputField.Text
				};
				Respond(response, shouldCloseDialog: true);
				submitEnabled = true;
				yield break;
			}
			yield return StringSanitization.RequestIsStringPure(textInputField.Text, delegate(string error, StringSanitization.IsPureStringResponse isPureStringResponse)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (isPureStringResponse.IsPure)
					{
						InputResponse response2 = new InputResponse
						{
							Response = ConfirmDialogResponses.Affirmative,
							TextInput = textInputField.Text
						};
						Respond(response2, shouldCloseDialog: true);
					}
					else
					{
						infoText.text = "Please check the Rec Room Code of Conduct";
						infoText.gameObject.SetActive(value: true);
					}
				}
				else
				{
					infoText.text = "Error setting message. Please try again.";
					infoText.gameObject.SetActive(value: true);
				}
				submitEnabled = true;
			});
		}

		public void Button_Cancel()
		{
			Respond(cancelResponse, shouldCloseDialog: true);
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(cancelResponse, shouldCloseDialog);
		}
	}
	public class UIConfirmationDialog : ConfirmUIDialog<UIConfirmationDialog.DialogType, string, string, string, string>
	{
		[Flags]
		public enum DialogType
		{
			YES_NO_CANCEL_HOME = 0xF,
			OK_CANCEL = 0xD,
			YES_NO = 3,
			LOCKED = 0,
			YES_ONLY = 1,
			YES_NO_CANCEL = 7,
			OK_CANCEL_TEXT = 0x1D,
			YES_NO_NOTNOW = 0x23
		}

		private const int YES = 1;

		private const int NO = 2;

		private const int BACK = 4;

		private const int HOME = 8;

		private const int TEXT = 16;

		private const int NOTNOW = 32;

		[SerializeField]
		private TextMeshProUGUI titleText;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private TextMeshProUGUI yesText;

		[SerializeField]
		private TextMeshProUGUI noText;

		[SerializeField]
		private TextMeshProUGUI notNowText;

		[SerializeField]
		private ValidatedButtonInputField textInputField;

		[SerializeField]
		private GameObject textInputGroup;

		[SerializeField]
		private RectTransform yesButton;

		[SerializeField]
		private RectTransform noButton;

		[SerializeField]
		private RectTransform notNowButton;

		[SerializeField]
		private PagedTextMeshPro3D pagedText;

		public ValidatedButtonInputField TextInputField => textInputField;

		public override IPromise<ConfirmDialogResponses> ShowDialog(DialogType dialogType, string titleText, string bodyText, string affirmativeText = "Yes", string negativeText = "No")
		{
			UIHelper.SafeSetText(this.titleText, titleText);
			pagedText.SetText(bodyText);
			UIHelper.SafeSetText(yesText, affirmativeText);
			UIHelper.SafeSetText(noText, negativeText);
			if (yesButton != null)
			{
				yesButton.gameObject.SetActive((dialogType & DialogType.YES_ONLY) != 0);
			}
			if (noButton != null)
			{
				noButton.gameObject.SetActive((dialogType & (DialogType)2) != 0);
			}
			if (notNowButton != null)
			{
				notNowButton.gameObject.SetActive((dialogType & (DialogType)32) != 0);
			}
			if (textInputGroup != null)
			{
				textInputGroup.SetActive((dialogType & (DialogType)16) != 0);
			}
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				componentInChildren.ShowBackButton = (dialogType & (DialogType)4) != 0;
				componentInChildren.ShowHomeButton = (dialogType & (DialogType)8) != 0;
			}
			else
			{
				UnityEngine.Debug.LogWarning("UIConfirmationDialog.ShowDialog(): ScreenHeader not found");
			}
			return base.ShowDialog();
		}

		public void UpdateBodyText(string bodyText)
		{
			UIHelper.SafeSetText(this.bodyText, bodyText);
		}
	}
	public abstract class UIDialog : StackedUIFlowBase
