	public abstract class UIDialog<R> : UIDialog
	{
		protected Promise<R> CurrentPromise { get; private set; }

		protected IPromise<R> CreatePromise()
		{
			if (CurrentPromise != null)
			{
				ForceCancel(shouldCloseDialog: true);
			}
			CurrentPromise = new Promise<R>();
			return CurrentPromise;
		}

		protected void Respond(R response, bool shouldCloseDialog)
		{
			if (CurrentPromise != null)
			{
				if (shouldCloseDialog)
				{
					base.UIBase.PopFlow();
				}
				Promise<R> currentPromise = CurrentPromise;
				CurrentPromise = null;
				currentPromise.Complete(response);
			}
		}

		public virtual IPromise<R> ShowDialog()
		{
			return CreatePromise();
		}
	}
