namespace AGUI.StackedUI
{
	public class DisabledUIFlowRoot : UnityEngine.MonoBehaviour
	{
		private void Awake()
		{
			SceneManager.sceneUnloaded += SceneManager_sceneUnloaded;
		}

		private void OnDestroy()
		{
			SceneManager.sceneUnloaded -= SceneManager_sceneUnloaded;
		}

		private void SceneManager_sceneUnloaded(Scene arg0)
		{
			DestroyOrphanedFlows();
		}

		private void DestroyOrphanedFlows()
		{
			foreach (Transform item in base.transform)
			{
				StackedUIFlowBase component = item.GetComponent<StackedUIFlowBase>();
				if (component != null)
				{
					if (component.UIBase == null)
					{
						UnityEngine.Object.Destroy(component.gameObject);
					}
				}
				else
				{
					UnityEngine.Debug.LogWarningFormat("Object {0} parented under the DisabledUIFlowRoot, but it isn't a StackedUIFlow. That's odd.", item.gameObject);
				}
			}
		}
	}
	public class InputField3D : ClickableReleaseButton
	{
		[NonSerialized]
		private new TextMeshProUGUI label;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private TMP_InputField _inputField;

		private TextMeshProUGUI _placeholder;

		private bool? wasToggledOnDown;

		public TMP_InputField InputField => _inputField;

		public string Text
		{
			get
			{
				return _inputField.text;
			}
			set
			{
				_inputField.text = value;
			}
		}

		private TextMeshProUGUI Placeholder
		{
			get
			{
				if (_placeholder == null)
				{
					_placeholder = InputField.placeholder.GetComponent<TextMeshProUGUI>();
				}
				return _placeholder;
			}
		}

		public string PlaceholderText
		{
			get
			{
				if (Placeholder != null)
				{
					return Placeholder.text;
				}
				return null;
			}
			set
			{
				if (Placeholder != null)
				{
					Placeholder.text = value;
				}
			}
		}

		public bool IsFocused
		{
			get
			{
				if (InputField == null)
				{
					return false;
				}
				return InputField.isFocused;
			}
		}

		protected override float MaxSquashScale => 1f;

		protected override float ReleaseAxisValue => 0.5f;

		protected override void Awake()
		{
			base.Awake();
			if (GetComponent<DisabledAltRenderedObject>() == null)
			{
				base.gameObject.AddComponent<DisabledAltRenderedObject>();
			}
		}

		protected override void Update()
		{
			base.Update();
			RefreshVisuals();
		}

		protected override void PhysicalButtonDownEvent(bool forcedPress = false)
		{
			wasToggledOnDown = base.Toggled;
			base.PhysicalButtonDownEvent(forcedPress);
		}

		protected override void PhysicalButtonCanceledEvent()
		{
			base.PhysicalButtonCanceledEvent();
			if (wasToggledOnDown.HasValue && wasToggledOnDown.Value)
			{
				SelectInputField();
			}
			else
			{
				DeselectInputField();
			}
			wasToggledOnDown = null;
		}

		protected override void PhysicalButtonUpEvent(bool forcedPress)
		{
			base.PhysicalButtonUpEvent(forcedPress);
			wasToggledOnDown = null;
		}

		public override void SetAxisValue(float newAxisValue, bool force = false)
		{
			if (IsFocused)
			{
				newAxisValue = Mathf.Max(newAxisValue, ReleaseAxisValue);
			}
			base.SetAxisValue(newAxisValue);
		}

		protected override float GetDesiredAxisValue()
		{
			if (IsFocused)
			{
				return ReleaseAxisValue;
			}
			return base.GetDesiredAxisValue();
		}

		protected override bool CanInteract()
		{
			return true;
		}

		protected override void OnButtonActionInternal()
		{
			if (wasToggledOnDown.HasValue && wasToggledOnDown.Value)
			{
				DeselectInputField();
			}
			else
			{
				SelectInputField();
			}
		}

		private void RefreshVisuals()
		{
			base.Toggled = IsFocused;
			if (!base.Toggled)
			{
				InputField.DeactivateInputField();
			}
			InputField.interactable = base.currentSelectionState != SelectionState.Disabled;
		}

		public void SelectInputField()
		{
			if (IsActive())
			{
				EventSystem.current.SetSelectedGameObject(InputField.gameObject);
				InputField.ActivateInputField();
				this.EndOfFrameRoutine(delegate
				{
					InputField.MoveTextEnd(shift: false);
				});
			}
		}

		public void DeselectInputField()
		{
			InputField.DeactivateInputField();
			if (EventSystem.current != null && EventSystem.current.currentSelectedGameObject == InputField.gameObject)
			{
				EventSystem.current.SetSelectedGameObject(null);
			}
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			if (InputField != null)
			{
				DeselectInputField();
			}
		}
	}
}
public class PagedTextMeshPro3D : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameObject pagingControls;

	[SerializeField]
	private Button3D upButton;

	[SerializeField]
	private Button3D downButton;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private TMP_Text textMesh;

	public void SetText(string text)
	{
		textMesh.text = text;
		textMesh.pageToDisplay = 1;
		this.InvokeNextEndOfFrame(delegate
		{
			pagingControls.SetActive(textMesh.textInfo.pageCount > 1);
			if (textMesh.textInfo.pageCount == 1)
			{
				textMesh.alignment = TextAlignmentOptions.Center;
			}
			else
			{
				textMesh.alignment = TextAlignmentOptions.TopLeft;
				UpdateButtons();
			}
		});
	}

	private void UpdateButtons()
	{
		Mathf.Clamp(textMesh.pageToDisplay, 1, textMesh.textInfo.pageCount);
		upButton.Interactable = textMesh.pageToDisplay != 1;
		downButton.Interactable = textMesh.pageToDisplay != textMesh.textInfo.pageCount;
	}

	[SkipRename]
	public void Button_Up()
	{
		textMesh.pageToDisplay--;
		UpdateButtons();
	}

	[SkipRename]
	public void Button_Down()
	{
		textMesh.pageToDisplay++;
		UpdateButtons();
	}
}
