	public class PlayerProfileResult3D : PlayerInfoUIControl
	{
		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action<Profile> m_DeleteProfileAction;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private Button3D deleteProfileButton;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private UnityEngine.UI.Image backgroundImage;

		[SerializeField]
		private Color onlineColor;

		[SerializeField]
		private Color offlineColor;

		public static event Action<Profile> DeleteProfileAction
		{
			add
			{
				Action<Profile> action = PlayerProfileResult3D.m_DeleteProfileAction;
				Action<Profile> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref PlayerProfileResult3D.m_DeleteProfileAction, (Action<Profile>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<Profile> action = PlayerProfileResult3D.m_DeleteProfileAction;
				Action<Profile> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref PlayerProfileResult3D.m_DeleteProfileAction, (Action<Profile>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public override void SetProfile(Profile profile)
		{
			base.SetProfile(profile);
			bool flag = Presence.Get(profile.Id)?.AppearsOnlineToMe ?? false;
			deleteProfileButton.Interactable = !flag;
			backgroundImage.color = ((!flag) ? offlineColor : onlineColor);
		}

		[SkipRename]
		public void Button_DeleteProfile()
		{
			if (PlayerProfileResult3D.DeleteProfileAction != null)
			{
				PlayerProfileResult3D.DeleteProfileAction(base.CurrentProfile);
			}
		}
	}
