	public class RadioGroup3DBase<T> : UnityEngine.MonoBehaviour where T : RadioButton3D
	{
		[SerializeField]
		private List<T> buttonGroup = new List<T>();

		public List<T> Buttons => buttonGroup;

		private void Awake()
		{
			if (buttonGroup.Count == 0)
			{
				FindChildButtons();
			}
			else
			{
				RefreshButtonListeners();
			}
		}

		internal void RefreshButtonListeners()
		{
			foreach (T button in Buttons)
			{
				button.OnClick.RemoveListener(OnButtonClicked);
				button.OnClick.AddListener(OnButtonClicked);
			}
		}

		internal void FindChildButtons()
		{
			foreach (Transform item in base.transform)
			{
				T component = item.GetComponent<T>();
				if (component != null)
				{
					AddButton(component);
				}
			}
		}

		public void AddButton(T newButton)
		{
			if (!buttonGroup.Contains(newButton))
			{
				buttonGroup.Add(newButton);
			}
			newButton.OnClick.RemoveListener(OnButtonClicked);
			newButton.OnClick.AddListener(OnButtonClicked);
		}

		public void AddButtons(List<T> newButtons)
		{
			foreach (T newButton in newButtons)
			{
				AddButton(newButton);
			}
		}

		protected void OnButtonClicked(RadioButton3D pressedButton)
		{
			SetSelectionStates((RadioButton3D b) => b == pressedButton);
		}

		public void SetSelectionStates(Func<RadioButton3D, bool> isCurrentButton)
		{
			foreach (T item in buttonGroup)
			{
				T current = item;
				if (!isCurrentButton(current))
				{
					current.ForceRelease();
					current.IsCurrent = false;
				}
				else
				{
					current.IsCurrent = true;
				}
			}
		}

		private void OnDestroy()
		{
			foreach (T item in buttonGroup)
			{
				if (item != null)
				{
					item.OnClick.RemoveListener(OnButtonClicked);
				}
			}
		}
	}
	public class RadioGroup3D : RadioGroup3DBase<RadioButton3D>
	{
	}
	public abstract class ResizableElementBase : UnityEngine.MonoBehaviour
	{
		public abstract void Resize(SizeOption size);
	}
	public abstract class ResizableElementBase<T> : ResizableElementBase where T : ResizableElementBase<T>.SizeSettingsBase
	{
		[Serializable]
		public class SizeSettingsBase
		{
			public SizeOption size;
		}

		protected abstract T[] SizeSettings { get; }

		public override void Resize(SizeOption size)
		{
			for (int i = 0; i < SizeSettings.Length; i++)
			{
				T val = SizeSettings[i];
				if (val != null && val.size == size)
				{
					ApplySettings(val);
					break;
				}
			}
		}

		protected abstract void ApplySettings(T settings);
	}
