	[RequireComponent(typeof(RectTransform))]
	public class Slider3D : Slider
	{
		[Serializable]
		public class OnSlider3DValueUpdateEvent : UnityEvent<float>
		{
		}

		[Serializable]
		public struct SliderValue
		{
			public int Value;

			public string Label;
		}

		public OnSlider3DValueUpdateEvent OnSlider3DValueChanged;

		public OnSlider3DValueUpdateEvent OnSlider3DReleased;

		private StackedUIBase uiBase;

		[SerializeField]
		private SliderHandleButton Handle;

		[SerializeField]
		private TextMeshProUGUI textLabelPrefab;

		[SerializeField]
		private GameObject slotPrefab;

		public TextMeshProUGUI titleText;

		[SerializeField]
		private Transform slotsParent;

		[SerializeField]
		private Transform textLabelsParent;

		[SerializeField]
		private bool UseWholeNumbers;

		private PlayerHand playerHand;

		private Collider playerHandCollider;

		private float lerpTime;

		private float xOffset;

		private bool downLastFrame;

		private TextMeshProUGUI[] _textLabels;

		private float lastEventActualValue = float.MinValue;

		private float? pointerDownValue;

		protected StackedUIBase UIBase
		{
			get
			{
				if (uiBase == null)
				{
					StackedUIBase[] componentsInParent = base.gameObject.GetComponentsInParent<StackedUIBase>(includeInactive: true);
					uiBase = ((componentsInParent.Length <= 0) ? null : componentsInParent[0]);
					if (uiBase == null && UnityEngine.Application.isPlaying)
					{
						UnityEngine.Debug.LogWarning("Expected a StackedUIBase, but none found!", base.gameObject);
					}
				}
				return uiBase;
			}
		}

		public bool UsingWholeNumbers => UseWholeNumbers;

		public TextMeshProUGUI[] TextLabels
		{
			get
			{
				if (_textLabels == null && textLabelsParent != null)
				{
					_textLabels = textLabelsParent.GetComponentsInChildren<TextMeshProUGUI>();
				}
				return _textLabels;
			}
		}

		public bool Interactable
		{
			get
			{
				return base.interactable;
			}
			set
			{
				base.interactable = value;
				Handle.Interactable = value;
			}
		}

		public float FloatOrRoundedValue
		{
			get
			{
				if (UseWholeNumbers)
				{
					return Mathf.Round(value);
				}
				return value;
			}
		}

		protected override void Awake()
		{
			if (base.wholeNumbers)
			{
				base.wholeNumbers = false;
				UseWholeNumbers = true;
			}
			base.onValueChanged.AddListener(OnSliderValueUpdate);
		}

		private void OnSliderValueUpdate(float value)
		{
			if (OnSlider3DValueChanged != null && lastEventActualValue != FloatOrRoundedValue)
			{
				lastEventActualValue = FloatOrRoundedValue;
				OnSlider3DValueChanged.Invoke(FloatOrRoundedValue);
			}
		}

		private void Update()
		{
			if (!(Handle != null))
			{
				return;
			}
			if ((UIBase == null || UIBase.CanInteract(this)) && Handle.ButtonPressed && Handle.MenuFinger != null)
			{
				Vector3 position = Handle.MenuFinger.FingertipTransform.position;
				Vector3 vector = base.transform.InverseTransformPoint(position);
				float a;
				float b;
				float num;
				switch (base.direction)
				{
				case Direction.RightToLeft:
					a = ((RectTransform)base.transform).rect.xMax;
					b = ((RectTransform)base.transform).rect.xMin;
					num = vector.x;
					break;
				case Direction.BottomToTop:
					a = ((RectTransform)base.transform).rect.yMin;
					b = ((RectTransform)base.transform).rect.yMax;
					num = vector.y;
					break;
				case Direction.TopToBottom:
					a = ((RectTransform)base.transform).rect.yMax;
					b = ((RectTransform)base.transform).rect.yMin;
					num = vector.y;
					break;
				default:
					a = ((RectTransform)base.transform).rect.xMin;
					b = ((RectTransform)base.transform).rect.xMax;
					num = vector.x;
					break;
				}
				base.normalizedValue = Mathf.InverseLerp(a, b, num);
			}
			if (!Handle.ButtonPressed && UseWholeNumbers)
			{
				if (downLastFrame)
				{
					lerpTime = 0f;
				}
				if (!Mathf.Approximately(value, FloatOrRoundedValue))
				{
					value = Mathf.Lerp(value, FloatOrRoundedValue, lerpTime);
				}
				lerpTime += UnityEngine.Time.deltaTime;
			}
			downLastFrame = Handle.ButtonPressed;
		}

		public void PhysicalButtonDownEvent(bool forcedPress)
		{
			HandleSliderPressed();
		}

		public void PhysicalButtonUpEvent(bool forcedPress)
		{
			HandleSliderReleased();
		}

		public override void OnPointerDown(PointerEventData eventData)
		{
			if (UIBase.CanInteract(this))
			{
				pointerDownValue = value;
				base.OnPointerDown(eventData);
			}
			else
			{
				pointerDownValue = null;
			}
		}

		public override void OnPointerUp(PointerEventData eventData)
		{
			if (UIBase.CanInteract(this))
			{
				base.OnPointerUp(eventData);
				if (pointerDownValue.HasValue && pointerDownValue.Value != value && OnSlider3DReleased != null)
				{
					OnSlider3DReleased.Invoke(FloatOrRoundedValue);
				}
			}
			pointerDownValue = null;
		}

		public override void OnDrag(PointerEventData eventData)
		{
			if (UIBase.CanInteract(this) && Handle.ButtonPressed)
			{
				base.OnDrag(eventData);
			}
		}

		public void SetUpSlider(string title, SliderValue[] sliderValues, int defaultValue)
		{
			UseWholeNumbers = true;
			base.minValue = sliderValues[0].Value;
			base.maxValue = sliderValues[sliderValues.Length - 1].Value;
			UIHelper.SafeSetText(titleText, title);
			if (slotPrefab != null && slotsParent != null)
			{
				SpawnSlots(sliderValues, slotPrefab, slotsParent);
			}
			if (textLabelPrefab != null && textLabelsParent != null)
			{
				SpawnTextLabels(sliderValues, textLabelPrefab, textLabelsParent);
			}
			value = defaultValue;
		}

		public void SetUpSlider(string title, int[] labelValues, int defaultValue)
		{
			SliderValue[] array = new SliderValue[labelValues.Length];
			for (int i = 0; i < labelValues.Length; i++)
			{
				ref SliderValue reference = ref array[i];
				reference = new SliderValue
				{
					Value = labelValues[i]
				};
			}
			SetUpSlider(title, array, defaultValue);
		}

		public void SpawnSlots(SliderValue[] sliderValues, GameObject slotPrefab, Transform slotsParent)
		{
			float num = value;
			try
			{
				for (int num2 = slotsParent.childCount - 1; num2 >= 0; num2--)
				{
					SafeDestroy.GameObject(slotsParent.GetChild(num2).gameObject);
				}
				for (int i = 0; i < sliderValues.Length; i++)
				{
					GameObject gameObject = UnityEngine.Object.Instantiate(slotPrefab, slotsParent);
					RectTransform rectTransform = gameObject.transform as RectTransform;
					PositionElementForSliderValue(rectTransform, sliderValues[i].Value);
				}
			}
			finally
			{
				value = num;
			}
		}

		public void SpawnTextLabels(SliderValue[] sliderValues, TextMeshProUGUI labelPrefab, Transform textLabelsParent)
		{
			float num = value;
			try
			{
				for (int num2 = textLabelsParent.childCount - 1; num2 >= 0; num2--)
				{
					SafeDestroy.GameObject(textLabelsParent.GetChild(num2).gameObject);
				}
				for (int i = 0; i < sliderValues.Length; i++)
				{
					TextMeshProUGUI textMeshProUGUI = UnityEngine.Object.Instantiate(labelPrefab, textLabelsParent);
					RectTransform rectTransform = textMeshProUGUI.transform as RectTransform;
					PositionElementForSliderValue(rectTransform, sliderValues[i].Value, sliderValues.Length, expandOffAxis: true);
					textMeshProUGUI.text = (string.IsNullOrEmpty(sliderValues[i].Label) ? sliderValues[i].Value.ToString() : sliderValues[i].Label);
				}
			}
			finally
			{
				value = num;
			}
		}

		private void HandleSliderPressed()
		{
			if (UIBase.CanInteract(this) && IsInteractable() && IsActive() && Handle.Interactable)
			{
				Handle.SetPointerPressed(pressed: true);
			}
		}

		private void HandleSliderReleased()
		{
			if (UIBase.CanInteract(this))
			{
				Handle.SetPointerPressed(pressed: false);
				if (UseWholeNumbers)
				{
					value = Mathf.Round(value);
				}
				if (OnSlider3DReleased != null)
				{
					OnSlider3DReleased.Invoke(FloatOrRoundedValue);
				}
			}
		}

		private void PositionElementForSliderValue(RectTransform transform, float value, int elementCountToScaleFor = -1, bool expandOffAxis = false)
		{
			Vector2 anchorMin = Vector2.one * 0.5f;
			Vector2 anchorMax = Vector2.one * 0.5f;
			Vector2 offsetMin = transform.offsetMin;
			Vector2 offsetMax = transform.offsetMax;
			bool flag = base.direction == Direction.RightToLeft || base.direction == Direction.TopToBottom;
			float num = Mathf.InverseLerp(base.minValue, base.maxValue, value);
			float num2 = ((!flag) ? num : (1f - num));
			int index;
			int index2;
			if (base.direction == Direction.LeftToRight || base.direction == Direction.RightToLeft)
			{
				index = 0;
				index2 = 1;
			}
			else
			{
				index = 1;
				index2 = 0;
			}
			anchorMin[index] = num2;
			anchorMax[index] = num2;
			if (elementCountToScaleFor > 0)
			{
				float num3 = 1f / (float)elementCountToScaleFor;
				float num4 = num3 * 0.5f;
				anchorMin[index] -= num4;
				anchorMax[index] += num4;
				offsetMin[index] = 0f;
				offsetMax[index] = 0f;
			}
			if (expandOffAxis)
			{
				anchorMin[index2] = 0f;
				anchorMax[index2] = 1f;
				offsetMin[index2] = 0f;
				offsetMax[index2] = 0f;
			}
			transform.anchorMin = anchorMin;
			transform.anchorMax = anchorMax;
			transform.offsetMin = offsetMin;
			transform.offsetMax = offsetMax;
			transform.pivot = new Vector2(0.5f, 0.5f);
			transform.anchoredPosition3D = Vector3.zero;
		}
	}
}
