		private void InitializeFlows()
		{
			StackedUIFlowBase[] componentsInChildren = GetComponentsInChildren<StackedUIFlowBase>(includeInactive: true);
			List<StackedUIFlowBase> list = new List<StackedUIFlowBase>();
			foreach (StackedUIFlowBase flowPrefab in FlowPrefabs)
			{
				if (flowPrefab != null)
				{
					list.Add(UnityEngine.Object.Instantiate(flowPrefab));
				}
				else
				{
					UnityEngine.Debug.LogError("Error setting up menu. Flow was null!");
				}
			}
			AllFlows.AddRange(componentsInChildren);
			AllFlows.AddRange(list);
			foreach (StackedUIFlowBase allFlow in AllFlows)
			{
				InitializeFlow(allFlow);
			}
			foreach (StackedUIFlowBase allFlow2 in AllFlows)
			{
				allFlow2.OnAllFlowsInitialized();
			}
			OnFlowsInitialized();
		}

