		protected virtual void PushFlowInternal(StackedUIFlowBase flow)
		{
			UIDialog uIDialog = CurrentFlow as UIDialog;
			if (uIDialog != null && !uIDialog.IsInstanced)
			{
				uIDialog.ForceCancel(shouldCloseDialog: true);
			}
			flowStack.Push(flow);
			if (CurrentFlow != null)
			{
				DisableFlow(CurrentFlow, flow, flowOnStack: true);
			}
			EnableFlow(flow, CurrentFlow);
		}

