		}

		protected virtual bool RefreshTopFlowInternal()
		{
			return true;
		}

		protected virtual bool PopFlowInternal()
		{
			if (flowStack.Count > 1)
			{
				StackedUIFlowBase oldFlow = flowStack.Pop();
				StackedUIFlowBase newFlow = flowStack.Peek();
				DisableFlow(oldFlow, newFlow, flowOnStack: false);
				EnableFlow(newFlow, oldFlow);
				return true;
			}
			return false;
		}

		private void EnableFlow(StackedUIFlowBase newFlow, StackedUIFlowBase oldFlow)
		{
			CurrentFlow = newFlow;
			AttachFlowToScreenBase(CurrentFlow);
			FlowTransition(newFlow, oldFlow);
			SetDefaultSizeForFlow(newFlow);
			CurrentFlow.OnFlowEntered(oldFlow);
		}

		private void DisableFlow(StackedUIFlowBase oldFlow, StackedUIFlowBase newFlow, bool flowOnStack)
		{
			oldFlow.OnFlowExited(newFlow, flowOnStack);
			AttachFlowToDisabledRoot(oldFlow);
		}

		protected virtual void FlowTransition(StackedUIFlowBase newFlow, StackedUIFlowBase oldFlow)
		{
		}

		private void AttachFlowToScreenBase(StackedUIFlowBase flow)
		{
			if (flow != null)
			{
				flow.transform.SetParent(screenBase, worldPositionStays: false);
				flow.transform.localPosition = Vector3.zero;
				flow.transform.localScale = Vector3.one;
				flow.transform.localRotation = Quaternion.identity;
				RectTransform rectTransform = flow.transform as RectTransform;
				rectTransform.anchorMin = Vector2.zero;
				rectTransform.anchorMax = Vector2.one;
				rectTransform.offsetMin = Vector2.zero;
				rectTransform.offsetMax = Vector2.zero;
				flow.gameObject.SetActive(value: true);
			}
		}

		private void AttachFlowToDisabledRoot(StackedUIFlowBase flow)
		{
			flow.gameObject.SetActive(value: false);
			flow.transform.SetParent(DisabledFlowRoot, worldPositionStays: false);
		}

		private void SetDefaultSizeForFlow(StackedUIFlowBase flow)
		{
			SizeOption newSize = Size;
			if (flow.ForceSpecificSize)
			{
				newSize = flow.ForcedSize;
			}
			else if (!SupportsResizing)
			{
				newSize = UISizeSettings.DefaultSize(SizeConfigKey, SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode);
			}
			SetSize(newSize, notifyCurrentFlow: false);
		}

		private void SetSize(SizeOption newSize, bool notifyCurrentFlow)
		{
			if (currentSize == newSize)
			{
				return;
			}
			currentSize = newSize;
			if (UISizeSettings.TryGetSize(SizeConfigKey, Size, out var dimensions))
			{
				canvasRectTransform.sizeDelta = dimensions;
				if (notifyCurrentFlow && CurrentFlow != null)
				{
					CurrentFlow.Resize(Size);
				}
			}
			OnSizeChanged();
		}

		public bool CanInteract(Selectable selectable)
		{
			for (int i = 0; i < baseUiRestrictions.Length; i++)
			{
				if (baseUiRestrictions[i].gameObject.activeInHierarchy && !baseUiRestrictions[i].CanInteract(selectable))
				{
					return false;
				}
			}
			if (CurrentFlow != null && !CurrentFlow.CanInteract(selectable))
			{
				return false;
			}
			return true;
		}

		public T GetFlowByType<T>() where T : StackedUIFlowBase
		{
			foreach (StackedUIFlowBase allFlow in AllFlows)
			{
				T val = allFlow as T;
				if (val != null)
				{
					return val;
				}
			}
			return (T)null;
		}

		private float CalculateCanvasRelativeScale()
		{
			float num = 1f;
			Transform parent = Canvas.transform;
			while (true)
			{
				num *= parent.localScale.y;
				if (parent == base.transform)
				{
					break;
				}
				parent = parent.parent;
			}
			return num;
		}
	}
