	public class ToggleGroup3D : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private List<ToggleButton3D> buttonGroup = new List<ToggleButton3D>();

		public List<ToggleButton3D> Buttons => buttonGroup;

		private void Awake()
		{
			foreach (Transform item in base.transform)
			{
				ToggleButton3D componentInChildren = item.GetComponentInChildren<ToggleButton3D>();
				if (componentInChildren != null)
				{
					AddButton(componentInChildren);
				}
			}
		}

		public void AddButton(ToggleButton3D newButton)
		{
			if (!buttonGroup.Contains(newButton))
			{
				buttonGroup.Add(newButton);
			}
			newButton.OnValueChanged += OnValueChanged;
		}

		private void OnValueChanged(ToggleButton3D button, bool isOn)
		{
			if (!isOn)
			{
				return;
			}
			foreach (ToggleButton3D item in buttonGroup)
			{
				if (button != item)
				{
					item.ForceRelease();
				}
			}
		}

		public void AddButtons(List<ToggleButton3D> newButtons)
		{
			foreach (ToggleButton3D newButton in newButtons)
			{
				AddButton(newButton);
			}
		}

		private void OnDestroy()
		{
			foreach (ToggleButton3D item in buttonGroup)
			{
				if (item != null)
				{
					item.OnValueChanged -= OnValueChanged;
				}
			}
		}
	}
	public class UI3DScaler : UIBehaviour
	{
		[Serializable]
		public enum ZScaleMatch
		{
			NONE,
			X,
			Y
		}

		[SerializeField]
		private RectTransform facePlaneTransform;

		[SerializeField]
		private Vector3 scaleModifier = Vector3.one;

		[SerializeField]
		private Canvas _canvas;

		public ZScaleMatch zScaleMatch;

		public Canvas ThisCanvas
		{
			get
			{
				if (_canvas == null)
				{
					FetchRootCanvas();
				}
				return _canvas;
			}
			set
			{
				_canvas = value;
			}
		}

		public void FetchRootCanvas()
		{
			Transform root = base.transform.root;
			Canvas[] componentsInChildren = root.GetComponentsInChildren<Canvas>(includeInactive: true);
			foreach (Canvas canvas in componentsInChildren)
			{
				if (canvas.isRootCanvas)
				{
					_canvas = canvas;
					break;
				}
			}
		}

		protected override void OnRectTransformDimensionsChange()
		{
			base.OnRectTransformDimensionsChange();
			if (ThisCanvas != null)
			{
				Refresh();
			}
		}

		public void Refresh()
		{
			if (ThisCanvas == null)
			{
				UnityEngine.Debug.LogWarning("Missing canvas on " + base.gameObject.name + "!", base.gameObject);
				return;
			}
			RectTransform rectTransform = base.transform.parent as RectTransform;
			float height = rectTransform.rect.height;
			float width = rectTransform.rect.width;
			float num = 1f / ThisCanvas.transform.localScale.x;
			float num2 = 1f / ThisCanvas.transform.localScale.y;
			float num3 = 1f / ThisCanvas.transform.localScale.z;
			float num4 = width / num;
			float num5 = height / num2;
			float num6 = 1f;
			if (facePlaneTransform != null)
			{
				Vector3 localScale = facePlaneTransform.localScale;
				num4 *= localScale.x;
				num5 *= localScale.y;
			}
			Vector3 localScale2 = new Vector3(num * num4, num2 * num5, num3 * zScaleMatch switch
			{
				ZScaleMatch.X => num4, 
				ZScaleMatch.Y => num5, 
				_ => (!(facePlaneTransform != null)) ? 1f : (Mathf.Abs(facePlaneTransform.localPosition.z) / num3), 
			}).MultiplyComponents(scaleModifier);
			if (!(localScale2.x <= 0f) && !(localScale2.y <= 0f) && !(localScale2.z <= 0f))
			{
				base.transform.localScale = localScale2;
				for (int i = 0; i < base.transform.childCount; i++)
				{
					base.transform.GetChild(i).transform.localScale = Vector3.one;
				}
			}
		}
	}
