	public static class UISizeSettings
	{
		private const string ConfigsAssetFilePath = "Assets/Core/Content/Configs/";

		private static UISizeConfig ConfigAsset = CustomSettingsLoader.LoadConfig<UISizeConfig>();

		public static bool TryGetSize(string key, SizeOption sizeOption, out Vector2 dimensions)
		{
			if (ConfigAsset != null && !string.IsNullOrEmpty(key))
			{
				UISizeConfig.UISizeDefinitions uISizeDefinitions = ConfigAsset.sizeDefinitions.FirstOrDefault((UISizeConfig.UISizeDefinitions d) => d.key == key);
				if (uISizeDefinitions != null)
				{
					UISizeConfig.SizeDefinition sizeDefinition = uISizeDefinitions.sizes.FirstOrDefault((UISizeConfig.SizeDefinition d) => d.size == sizeOption);
					if (sizeDefinition != null)
					{
						dimensions = sizeDefinition.dimensions;
						return true;
					}
					UnityEngine.Debug.LogWarningFormat("UI size definition with key '{0}' has no definition for size {1}", key, sizeOption);
				}
				else
				{
					UnityEngine.Debug.LogWarningFormat("No UI size definitions found for key: {0}", key);
				}
			}
			dimensions = Vector2.zero;
			return false;
		}

		public static SizeOption DefaultSize(string key, LocalPlayerController.DisplayMode displayMode)
		{
			if (ConfigAsset != null && !string.IsNullOrEmpty(key))
			{
				UISizeConfig.UISizeDefinitions uISizeDefinitions = ConfigAsset.sizeDefinitions.FirstOrDefault((UISizeConfig.UISizeDefinitions d) => d.key == key);
				if (uISizeDefinitions != null)
				{
					switch (displayMode)
					{
					case LocalPlayerController.DisplayMode.SCREEN:
						return uISizeDefinitions.defaultScreensSize;
					case LocalPlayerController.DisplayMode.VR:
						return uISizeDefinitions.defaultVrSize;
					}
				}
			}
			return SizeOption.NORMAL;
		}

		public static SizeOption[] SupportedSizes(string key)
		{
			if (ConfigAsset != null && !string.IsNullOrEmpty(key))
			{
				UISizeConfig.UISizeDefinitions uISizeDefinitions = ConfigAsset.sizeDefinitions.FirstOrDefault((UISizeConfig.UISizeDefinitions d) => d.key == key);
				if (uISizeDefinitions != null)
				{
					return uISizeDefinitions.sizes.Select((UISizeConfig.SizeDefinition s) => s.size).ToArray();
				}
			}
			return null;
		}
	}
}
