public class ValidatedButtonInputField : UnityEngine.MonoBehaviour
{
	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_OnSubmitAction;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_OnNonSubmitEndEditAction;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private InputField3D inputField3D;

	[SerializeField]
	[Autofill(AutofillType.SelfAndChildren, false)]
	private KeyboardInputField keyboardInputField;

	[SerializeField]
	public Button3D submitButton;

	public Func<string, bool> IsValidFunction = (string s) => true;

	private TextMeshProUGUI _placeholderText;

	public string PlaceholderText
	{
		set
		{
			if (_placeholderText == null)
			{
				_placeholderText = InputField.placeholder.GetComponent<TextMeshProUGUI>();
			}
			_placeholderText.text = value;
		}
	}

	public string Text
	{
		get
		{
			return InputField.text;
		}
		set
		{
			InputField.text = value;
		}
	}

	public TMP_InputField InputField => keyboardInputField.InputField;

	public InputField3D InputField3D => inputField3D;

	public bool Interactable
	{
		set
		{
			InputField.interactable = value;
			if (inputField3D != null)
			{
				inputField3D.Interactable = value;
			}
			if (submitButton != null)
			{
				submitButton.Interactable = value && IsValidFunction(InputField.text);
			}
		}
	}

	public event Action OnSubmitAction
	{
		add
		{
			Action action = this.m_OnSubmitAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnSubmitAction, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_OnSubmitAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnSubmitAction, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public event Action OnNonSubmitEndEditAction
	{
		add
		{
			Action action = this.m_OnNonSubmitEndEditAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnNonSubmitEndEditAction, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_OnNonSubmitEndEditAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnNonSubmitEndEditAction, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Awake()
	{
		if (InputField.onEndEdit.GetPersistentEventCount() > 0)
		{
			UnityEngine.Debug.LogWarning("Persistent event assigned for " + InputField.gameObject.name + ". Use ValidatedButtonInputField's OnSubmit() or OnNonSubmitEndEditAction() instead!", InputField.gameObject);
		}
		keyboardInputField.Submitted.Add(OnSubmit);
		keyboardInputField.DeselectedWithoutSubmit.Add(OnDeselectedWithoutSubmit);
		InputField.onValueChanged.AddListener(delegate
		{
			ValidateInput();
		});
	}

	private void Start()
	{
		ValidateInput();
	}

	public void Select()
	{
		InputField.ActivateInputField();
		InputField.Select();
	}

	private void ValidateInput()
	{
		if (submitButton != null)
		{
			submitButton.Interactable = IsValidFunction(InputField.text);
		}
	}

	private void OnDeselectedWithoutSubmit()
	{
		if (this.OnNonSubmitEndEditAction != null)
		{
			this.OnNonSubmitEndEditAction();
		}
	}

	private void OnSubmit(string text)
	{
		if (IsValidFunction(text))
		{
			if (submitButton != null)
			{
				submitButton.OnClick.Invoke();
			}
			if (this.OnSubmitAction != null)
			{
				this.OnSubmitAction();
			}
		}
		else if (this.OnNonSubmitEndEditAction != null)
		{
			this.OnNonSubmitEndEditAction();
		}
	}
}
