public class AutoScaledText : Text
{
	public string CharactersNeeded = "0123456789";

	[SerializeField]
	private List<int> fontSizesAllowed = new List<int>();

	private List<CharacterInfo> characterInfoApproximationsPerFontSize;

	private RectTransform myTransform;

	private bool isInitialized;

	public override string text
	{
		get
		{
			return base.text;
		}
		set
		{
			base.text = value;
			DetermineFontSizeToUse();
		}
	}

	protected override void Awake()
	{
		if (fontSizesAllowed.Count == 0)
		{
			fontSizesAllowed.Add(30);
		}
		base.resizeTextForBestFit = false;
		myTransform = (RectTransform)base.transform;
		base.Awake();
	}

	protected override void Start()
	{
		fontSizesAllowed.Sort();
		int count = fontSizesAllowed.Count;
		characterInfoApproximationsPerFontSize = new List<CharacterInfo>(count);
		PreCacheFonts();
		char ch = CharactersNeeded[0];
		for (int i = 0; i < count; i++)
		{
			int size = fontSizesAllowed[i];
			CharacterInfo info = default(CharacterInfo);
			base.font.GetCharacterInfo(ch, out info, size);
			characterInfoApproximationsPerFontSize.Add(info);
		}
		isInitialized = true;
		DetermineFontSizeToUse();
		base.Start();
	}

	public override void SetLayoutDirty()
	{
		DetermineFontSizeToUse();
		base.SetLayoutDirty();
	}

	public override void SetVerticesDirty()
	{
		DetermineFontSizeToUse();
		base.SetVerticesDirty();
	}

	private void PreCacheFonts()
	{
		if (!(base.font == null))
		{
			for (int i = 0; i < fontSizesAllowed.Count; i++)
			{
				base.font.RequestCharactersInTexture(CharactersNeeded, fontSizesAllowed[i]);
			}
		}
	}

	public void DetermineFontSizeToUse()
	{
		if (!isInitialized || !UnityEngine.Application.isPlaying)
		{
			return;
		}
		int length = text.Length;
		Vector2 vector = myTransform.rect.size * 0.95f;
		int num = -1;
		for (int num2 = fontSizesAllowed.Count - 1; num2 >= 0; num2--)
		{
			CharacterInfo characterInfo = characterInfoApproximationsPerFontSize[num2];
			float num3 = fontSizesAllowed[num2];
			float num4 = characterInfo.glyphWidth;
			float num5 = num4 * (float)length;
			if (num3 <= vector.y && num5 < vector.x)
			{
				num = num2;
				break;
			}
		}
		if (num < 0)
		{
			num = 0;
		}
		base.fontSize = fontSizesAllowed[num];
	}
}
public class Billboard : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool invertY;

	private void LateUpdate()
	{
		if (SingletonMonoBehaviour<CameraRig>.Instance != null && SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera != null)
		{
			Vector3 vector = -SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
			vector = ((!(Vector3.Dot(vector, Vector3.up) >= 1f - Mathf.Epsilon)) ? Vector3.ProjectOnPlane(vector, Vector3.up).normalized : Vector3.forward);
			Vector3 up = Vector3.up;
			if (invertY)
			{
				up *= -1f;
			}
			base.transform.rotation = Quaternion.LookRotation(vector, up);
		}
	}
}
namespace AGUI
{
	[DisallowMultipleComponent]
	public class BlinkingImage : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		[FormerlySerializedAs("image")]
		private UnityEngine.UI.Image _image;

		[SerializeField]
		private float blinkDuration = 1.5f;

		[SerializeField]
		private Color blinkColor = Color.white;

		private Color startColor;

		private Color prevColor;

		private Coroutine blinkRoutine;

		public UnityEngine.UI.Image Image => _image;

		private void OnEnable()
		{
			blinkRoutine = StartCoroutine(BlinkRoutine());
		}

		private void OnDisable()
		{
			this.SafeStopCoroutine(blinkRoutine);
			Image.color = startColor;
		}

		private IEnumerator BlinkRoutine()
		{
			startColor = Image.color;
			prevColor = startColor;
			yield return null;
			while (true)
			{
				for (float t = 0f; t < 1f; t += UnityEngine.Time.deltaTime / blinkDuration)
				{
					if (prevColor != Image.color)
					{
						startColor = Image.color;
					}
					float colorT = ((!(t < 0.5f)) ? (2f - t * 2f) : (t * 2f));
					Image.color = Color.Lerp(startColor, blinkColor, colorT);
					prevColor = Image.color;
					yield return null;
				}
			}
		}
	}
}
public class BootSequence : UnityEngine.MonoBehaviour
{
	private const string PROFILE_SELECTION_SCENE = "ProfileSelection";

	private const string SPLASH_SCREEN_SCENE = "splash_screen";

	private const string ROOM_CALIBRATION_SCENE = "room_calibration";

	private const float CheckForVRDeviceTimeout = 10f;

	private string _debugStatusText;

	private PerfClock clock = new PerfClock("BootSequence");

	private string error;

	private StackTrace errorStackTrace;

	private bool waitingForCalibration;

	private const string GAMESESSION_PREFIX = "+gamesession:";

	private const string ROOMNAME_COMMAND_PREFIX = "+roomname:";

	public const string PROFILE_COMMAND_PREFIX = "+profile:";

	public const string TEST_PLATFORM_ID_PREFIX = "+platformid:";

	public const string SPLIT_TEST_OVERRIDES_PREFIX = "+splittest:";

	private string DebugStatusText
	{
		get
		{
			return _debugStatusText;
		}
		set
		{
			_debugStatusText = value;
		}
	}

	private bool success => string.IsNullOrEmpty(error);

	private void InitializeCallback(string error)
	{
		if (!string.IsNullOrEmpty(error) && string.IsNullOrEmpty(this.error))
		{
			this.error = error;
			errorStackTrace = new StackTrace(fNeedFileInfo: true);
		}
	}

	private IEnumerator Start()
	{
		clock.Start("(Total)");
		clock.Start("(Waiting for Rec Room)");
		clock.Start("(Before Login)");
		UnityEngine.Debug.LogFormat("Build version: {0}", BuildSettings.Version);
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: false, prepForLevelSwitch: true, suppressEffect: true);
		Screen.fullScreen = true;
		GameObject[] rootGameObjects = SceneManager.GetActiveScene().GetRootGameObjects();
		foreach (GameObject target in rootGameObjects)
		{
			UnityEngine.Object.DontDestroyOnLoad(target);
		}
		UnityEngine.AsyncOperation profileSelectionLoad = StartLoadSceneAsync("ProfileSelection");
		Coroutine photonPingCR = StartCoroutine(NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.PingPhotonRegions());
		SingletonMonoBehaviour<LocalPlayerController>.Instance.EnterSplashScreenState();
		DebugStatusText = "Starting PreInitialize...";
		clock.Start("PlatformManager.PreInitialize");
		yield return SingletonMonoBehaviour<PlatformManager>.Instance.PreInitialize();
		clock.Stop("PlatformManager.PreInitialize");
		DebugStatusText = "Preloading assets...";
		EnemySettings.PreloadAssets();
		SpawnableToolSettings.PreloadAssets();
		PlayerBackpackToolSettings.PreloadAssets();
		PowerupSettings.PreloadAssets();
		clock.Start("FinishLoadSceneAsync(PROFILE_SELECTION_SCENE)");
		yield return FinishLoadSceneAsync("ProfileSelection", profileSelectionLoad);
		clock.Stop("FinishLoadSceneAsync(PROFILE_SELECTION_SCENE)");
		SingletonMonoBehaviour<LocalPlayerController>.Instance.OnSplashScreenLoad(SingletonMonoBehaviour<SplashScreenSpawnPoint>.Instance);
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: true, prepForLevelSwitch: false, suppressEffect: true, 1f);
		UnityEngine.AsyncOperation splashScreenLoad = StartLoadSceneAsync("splash_screen");
		if (success)
		{
			DebugStatusText = "Connecting to RecNet...";
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.UpdateStatus("Connecting to RecNet...", enableButtons: false);
			clock.Start("Core.ConnectToRecNet");
			yield return RecNet.Core.ConnectToRecNet(InitializeCallback);
			clock.Stop("Core.ConnectToRecNet");
		}
		if (success)
		{
			DebugStatusText = "Downloading config settings...";
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.UpdateStatus("Downloading config settings...", enableButtons: false);
			clock.Start("Config.DownloadConfigSettings");
			yield return Config.DownloadConfigSettings(InitializeCallback);
			clock.Stop("Config.DownloadConfigSettings");
		}
		if (success)
		{
			clock.Start("GameConfigs.RefreshAsync");
			yield return GameConfigs.RefreshAsync().Error(delegate(string error)
			{
				UnityEngine.Debug.LogError("Error calling GameConfigs.RefreshAsync(): " + error);
				InitializeCallback("Failed to download required data");
			});
			clock.Stop("GameConfigs.RefreshAsync");
		}
		if (success)
		{
			DebugStatusText = "Initializing VR Platform...";
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.UpdateStatus("Initializing VR platform...", enableButtons: false);
			clock.Start("PlatformManager.Initialize");
			yield return SingletonMonoBehaviour<PlatformManager>.Instance.Initialize(InitializeCallback);
			clock.Stop("PlatformManager.Initialize");
		}
		if (success)
		{
			LogPlatformInfo();
		}
		clock.Start("ProfileSelectionManager.InitializeAndOpenMenu");
		SingletonMonoBehaviour<ProfileSelectionManager>.Instance.InitializeAndOpenMenu();
		clock.Stop("ProfileSelectionManager.InitializeAndOpenMenu");
		clock.Start("ProfileSelectionManager.ProfileSelectionFlow.UpdateGridWithProfiles");
		SingletonMonoBehaviour<ProfileSelectionManager>.Instance.ProfileSelectionFlow.UpdateGridWithProfiles();
		clock.Stop("ProfileSelectionManager.ProfileSelectionFlow.UpdateGridWithProfiles");
		clock.Stop("(Before Login)");
		clock.Pause("(Waiting for Rec Room)");
		clock.Start("(Login)");
		if (success)
		{
			DebugStatusText = "Waiting for login...";
			clock.Start("ProfileSelectionManager.WaitForLogIn");
			yield return SingletonMonoBehaviour<ProfileSelectionManager>.Instance.WaitForLogIn();
			clock.Stop("ProfileSelectionManager.WaitForLogIn");
		}
		clock.Stop("(Login)");
		clock.Resume("(Waiting for Rec Room)");
		clock.Start("(After Login)");
		if (success)
		{
			yield return Presence.SetPlayerType(SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType).Error(delegate
			{
				InitializeCallback("Failed to set screen mode");
			});
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.PlayerTypeChange = (Action)Delegate.Combine(instance.PlayerTypeChange, new Action(Presence.OnPlayerTypeChanged));
		}
		if (success)
		{
			clock.Start("Notifications.Connect");
			yield return RecNet.Notifications.Connect().Error(delegate
			{
				InitializeCallback("Failed to connect to RecNet Notifications");
			});
			clock.Stop("Notifications.Connect");
		}
		if (success && SingletonMonoBehaviour<ProfileSelectionManager>.Instance.ForceAccountVerification && !LocalProfileHasRegistered())
		{
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Menu.OpenMenu();
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.ShowAccountStatusDialog(UIAccountStatusDialog.Status.PendingEmailVerification);
			yield return new WaitUntil(() => LocalProfileHasRegistered());
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.Closed();
		}
		bool calibratedThisSession = false;
		if (success && RoomCalibration.RequiresCalibration)
		{
			DebugStatusText = "Waiting for Calibration...";
			calibratedThisSession = true;
			clock.Pause("(Waiting for Rec Room)");
			clock.Start("WaitForCalibration");
			yield return WaitForCalibration();
			clock.Stop("WaitForCalibration");
			clock.Resume("(Waiting for Rec Room)");
		}
		clock.Start("(Splash Screen transition)");
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: false, prepForLevelSwitch: true, suppressEffect: true, 1f);
		clock.Start("FinishLoadSceneAsync(SPLASH_SCREEN_SCENE)");
		yield return FinishLoadSceneAsync("splash_screen", splashScreenLoad);
		clock.Stop("FinishLoadSceneAsync(SPLASH_SCREEN_SCENE)");
		SingletonMonoBehaviour<LocalPlayerController>.Instance.OnSplashScreenLoad(SingletonMonoBehaviour<SplashScreenSpawnPoint>.Instance);
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: true, prepForLevelSwitch: false, suppressEffect: true, 1f);
		clock.Stop("(Splash Screen transition)");
		if (success)
		{
			DebugStatusText = "Post login initialize...";
			clock.Start("PlatformManager.PostLoginInitialize");
			yield return SingletonMonoBehaviour<PlatformManager>.Instance.PostLoginInitialize(InitializeCallback);
			clock.Stop("PlatformManager.PostLoginInitialize");
		}
		if (success)
		{
			DebugStatusText = "Downloading required data...";
			clock.Start("Config.DownloadAmplitudeSettings");
			yield return Config.DownloadAmplitudeSettings(InitializeCallback);
			clock.Stop("Config.DownloadAmplitudeSettings");
		}
		if (success)
		{
			clock.Start("AnalyticsHelper.OnPlatformAndProfileInitialized");
			yield return AnalyticsHelper.OnPlatformAndProfileInitialized();
			clock.Stop("AnalyticsHelper.OnPlatformAndProfileInitialized");
			LogProfileInfo();
		}
		if (success && !Profiles.LocalProfile.IsJunior())
		{
			Images.ClearEntireImageCache();
		}
		if (success)
		{
			Images.PrecacheProfileImage(RecNet.Core.LocalProfileId);
		}
		if (success)
		{
			AsyncBatch batch = AsyncBatch.Create(base.transform);
			batch.Add("Images.DownloadNamedImageMappings", Images.DownloadNamedImageMappings());
			batch.Add("Avatars.DownloadLocalAvatar", Avatars.DownloadLocalAvatar(InitializeCallback));
			batch.Add("RecroomPrefs.DownloadLocalPlayerPreferences", RecroomPrefs.DowloadLocalPlayerPreferences(InitializeCallback));
			batch.Add("OutfitManager.DownloadUnlockedAvatarItems", NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.DownloadUnlockedAvatarItems(InitializeCallback));
			batch.Add("Avatars.DownloadSavedOutfitSlots", Avatars.DowloadSavedOutfitSlots(InitializeCallback));
			batch.Add("EquipmentManager.DownloadUnlockedEquipments", NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.DownloadUnlockedEquipments(InitializeCallback));
			batch.Add("ConsumableManager.DownloadPurchasedConsumables", NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.DownloadPurchasedConsumables(InitializeCallback));
			batch.Add("Avatars.DownloadGiftPackages", Avatars.DowloadGiftPackages(InitializeCallback));
			batch.Add("Storefronts.DownloadWatchGiftDropStorefront", Storefronts.DownloadWatchGiftDropStorefront(null));
			batch.Add("Objectives.GetMyObjectiveProgress", Objectives.GetMyObjectiveProgress(InitializeCallback));
			batch.Add("QuickPlay.GetAndClear", QuickPlays.GetAndClear());
			batch.Add("Checklist.GetCurrentChecklist", Checklist.GetCurrentChecklist(InitializeCallback));
			batch.Add("Rooms.GetMyCreatedRooms", RecNet.Rooms.GetMyCreatedRooms());
			batch.Add("PlayerEvents.DownloadPlayerEventList", RecNet.PlayerEvents.DownloadPlayerEventList(InitializeCallback));
			batch.Add("CommunityBoard.GetCurrentChecklist", CommunityBoard.GetCurrentCommunityBoardData());
			clock.Start("Wait for AsyncBatch");
			while (success && !batch.IsCompleted)
			{
				yield return null;
			}
			clock.Stop("Wait for AsyncBatch");
		}
		if (success)
		{
			SingletonMonoBehaviour<SplitTesting>.Instance.LoadSavedExperimentSegments();
			string text = PUNNetworkManager.CheckCommandLineArgsFor("+splittest:");
			if (!string.IsNullOrEmpty(text))
			{
				UnityEngine.Debug.LogFormat("SplitTest override args: {0}", text);
				string[] array = text.Split(';');
				if (array != null && array.Length > 0)
				{
					SingletonMonoBehaviour<SplitTesting>.Instance.OverrideViaCommandLineArgs(array);
				}
			}
			string text2 = GameConfigs.Get("splitTestSoftOverrides");
			string text3 = GameConfigs.Get("splitTestHardOverrides");
			if (text2 != null || text3 != null)
			{
				clock.Start("SplitTesting.RegisterServerSettings");
				SingletonMonoBehaviour<SplitTesting>.Instance.RegisterServerSettings(text2, text3);
				clock.Stop("SplitTesting.RegisterServerSettings");
			}
		}
		if (success)
		{
			clock.Start("Wait for photonPingCR");
			yield return photonPingCR;
			clock.Stop("Wait for photonPingCR");
			if (PhotonNetwork.networkingPeer.AvailableRegions != null)
			{
				AnalyticsHelper.LogPhotonPings();
			}
			else
			{
				AnalyticsHelper.LogPhotonPingFailure();
				InitializeCallback("Unable to connect to RecNet game servers");
			}
		}
		if (success)
		{
			yield return SingletonMonoBehaviour<SplashScreenManager>.Instance.WaitForMinimumSplashDuration();
			DebugStatusText = "Initializing core systems...";
			clock.Start("InitializeCoreSystems");
			InitializeCoreSystems();
			clock.Stop("InitializeCoreSystems");
			SingletonMonoBehaviour<SettingsManager>.Instance.PlayerStatusVisibilityChanged += Presence.OnPlayerStatusVisibilityChanged;
			if (!calibratedThisSession && RoomCalibration.UsesRoomCalibration && !SingletonMonoBehaviour<TutorialManager>.Instance.HasCompletedTutorial)
			{
				clock.Pause("(Waiting for Rec Room)");
				clock.Start("WaitForCalibration");
				yield return WaitForCalibration();
				clock.Stop("WaitForCalibration");
				clock.Resume("(Waiting for Rec Room)");
			}
			DebugStatusText = "Loading initial scene...";
			clock.Start("LoadInitialScene");
			yield return LoadInitialScene(InitializeCallback);
			clock.Stop("LoadInitialScene");
		}
		clock.Stop("(After Login)");
		clock.Stop("(Waiting for Rec Room)");
		clock.Stop("(Total)");
		if (!success)
		{
			SingletonMonoBehaviour<SplashScreenManager>.Instance.ShowErrorMessage(error);
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine(error);
			if (errorStackTrace != null)
			{
				stringBuilder.AppendLine(errorStackTrace.ToString());
			}
			UnityEngine.Debug.LogError(stringBuilder.ToString());
		}
		clock.StopAll();
		try
		{
			AnalyticsHelper.BootSequence(error, clock);
		}
		catch
		{
		}
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private bool LocalProfileHasRegistered()
	{
		return Profiles.LocalProfile != null && Profiles.LocalProfile.RegistrationStatus == RegistrationStatus.Registered;
	}

	private void LogPlatformInfo()
	{
		string format = "Platform Info:\r\n    Platform: {0}\r\n    Hardware: {1}\r\n    Platform Profile Name: {2}";
		string message = string.Format(format, SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform, SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareType, SingletonMonoBehaviour<PlatformManager>.Instance.PlatformProfileName);
		UnityEngine.Debug.Log(message);
	}

	private void LogProfileInfo()
	{
		string format = "Profile Info:\r\n    Profile ID: {0}\r\n    Profile DisplayName: {1}\r\n    Junior Profile: {2}\r\n    SID: {3}";
		Profile localProfile = Profiles.LocalProfile;
		string message = string.Format(format, localProfile.Id, localProfile.DisplayName, localProfile.JuniorProfile, AmplitudeAnalyticsClient.SessionId);
		UnityEngine.Debug.Log(message);
	}

	private void InitializeCoreSystems()
	{
		NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.Initialize();
		SingletonMonoBehaviour<DebugGuiManager>.Instance.Initialize();
		SingletonMonoBehaviour<SettingsManager>.Instance.Initialize();
		SingletonMonoBehaviour<TutorialManager>.Instance.Initialize();
		SingletonMonoBehaviour<AudioManager>.Instance.Initialize();
		SingletonMonoBehaviour<GiftManager>.Instance.Initialize();
		SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.Initialize();
		SingletonMonoBehaviour<PlayerEventNotificationManager>.Instance.Initialize();
		RecentPlayers.Initialize();
		if (SessionManager.IsDeveloper)
		{
			GoogleAnalytics.Client.UpdateHeaders();
		}
		string s = GameConfigs.Get("GASamplingRatio");
		float result = 0f;
		if (float.TryParse(s, out result))
		{
			GoogleAnalytics.SamplingRatio = result;
		}
		SingletonMonoBehaviour<ProgressionManager>.Instance.Initialize();
		SingletonMonoBehaviour<SessionManager>.Instance.Initialize();
		SingletonMonoBehaviour<ChildControlManager>.Instance.Initialize();
		AACCompilerCrashWorkAround();
	}

	private void AACCompilerCrashWorkAround()
	{
		string path = Path.Combine(UnityEngine.Application.temporaryCachePath, "libfaac-win64.dll");
		bool flag = File.Exists(path);
		string path2 = Path.Combine(UnityEngine.Application.dataPath, "FAAC_SelfBuild");
		bool flag2 = Directory.Exists(path2);
		if (!flag && flag2)
		{
			UnityEngine.Debug.LogError("Detected failed previous FAAC build. Automatically disabling video cameras.");
			SingletonMonoBehaviour<SettingsManager>.Instance.H264Plugin = false;
			try
			{
				Directory.Delete(path2, recursive: true);
			}
			catch
			{
			}
		}
	}

	private UnityEngine.AsyncOperation StartLoadSceneAsync(string sceneName)
	{
		UnityEngine.AsyncOperation asyncOperation = SceneManager.LoadSceneAsync(sceneName);
		asyncOperation.allowSceneActivation = false;
		return asyncOperation;
	}

	private IEnumerator FinishLoadSceneAsync(string sceneName, UnityEngine.AsyncOperation loadingOperation)
	{
		if (!loadingOperation.isDone)
		{
			loadingOperation.allowSceneActivation = true;
			yield return new WaitUntil(() => loadingOperation.isDone);
		}
		if (!SceneManager.GetSceneByName(sceneName).IsValid())
		{
			SceneManager.LoadScene(sceneName);
		}
	}

	private IEnumerator WaitForCalibration()
	{
		waitingForCalibration = true;
		RoomCalibration.LoadDormRoomOnCompletion = false;
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: false, prepForLevelSwitch: true, suppressEffect: true, 1f);
		SceneManager.LoadScene("room_calibration");
		yield return SingletonMonoBehaviour<CameraFade>.Instance.Fade(fadeIn: true, prepForLevelSwitch: false, suppressEffect: true, 1f);
		RoomCalibration.OnRoomCalibrationCompleted += OnRoomCalibrationCompleted;
		while (waitingForCalibration)
		{
			yield return null;
		}
	}

	private void OnRoomCalibrationCompleted()
	{
		RoomCalibration.OnRoomCalibrationCompleted -= OnRoomCalibrationCompleted;
		waitingForCalibration = false;
	}

	private IEnumerator LoadInitialScene(RecNet.Core.ApiCallback callback)
	{
		PhotonNetwork.player.SetCustomProperties("prev_activity", "boot");
		long? playerToJoin = null;
		string gameSessionArg = string.Empty;
		string roomNameArg = string.Empty;
		string roomSceneNameArg = null;
		if (!PlayerReporting.IsCurrentPlayerBlocked)
		{
			playerToJoin = NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.CheckCommandLineArgsForRichPresenceJoin();
			gameSessionArg = PUNNetworkManager.CheckCommandLineArgsFor("+gamesession:");
			roomNameArg = PUNNetworkManager.CheckCommandLineArgsFor("+roomname:");
			if (!playerToJoin.HasValue && (QuickPlays.Current?.TargetPlayerId).HasValue)
			{
				int? targetPlayerId = QuickPlays.Current.TargetPlayerId;
				playerToJoin = ((!targetPlayerId.HasValue) ? ((long?)null) : new long?(targetPlayerId.Value));
			}
			if (roomNameArg == null && QuickPlays.Current?.RoomName != null)
			{
				roomNameArg = QuickPlays.Current.RoomName;
			}
		}
		IPromise<GameSessions.JoinGameErrorCode> customJoinGamePromise = null;
		if (!string.IsNullOrEmpty(roomNameArg))
		{
			customJoinGamePromise = GameSessions.JoinRoom(roomNameArg, roomSceneNameArg);
		}
		else if (!string.IsNullOrEmpty(gameSessionArg))
		{
			customJoinGamePromise = GameSessions.JoinInstance(long.Parse(gameSessionArg), null);
		}
		else if (playerToJoin.HasValue)
		{
			customJoinGamePromise = GameSessions.JoinPlayer(playerToJoin.Value, null);
		}
		if (customJoinGamePromise != null && !PlayerReporting.IsCurrentPlayerBlocked)
		{
			bool success = false;
			yield return customJoinGamePromise.Then(delegate(GameSessions.JoinGameErrorCode response)
			{
				if (response != GameSessions.JoinGameErrorCode.Success)
				{
					string title = null;
					string message = null;
					SessionManager.GetJoinGameErrorCodeMessage(response, out title, out message);
					if (!string.IsNullOrEmpty(roomNameArg))
					{
						title += $" ^{roomNameArg}";
					}
					SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle = title;
					SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = message;
				}
				else
				{
					callback(null);
					success = true;
				}
			});
			if (success)
			{
				yield break;
			}
		}
		yield return GameSessions.GoToDormRoom().Error(delegate(string error)
		{
			UnityEngine.Debug.LogError("Unable to connect to game session: " + error);
			callback("Unable to connect to RecNet game session");
		}).Then(delegate(GameSessions.JoinGameErrorCode response)
		{
			if (response != GameSessions.JoinGameErrorCode.Success)
			{
				UnityEngine.Debug.LogError("Unable to connect to game session: " + response);
				callback("Unable to connect to RecNet game session");
			}
			else
			{
				callback(null);
			}
		});
	}
}
