public class CachedViewManager : UnityEngine.MonoBehaviour
{
	private static readonly string baseMaterialResourcePath = "legacy_CachedView_mat";

	private string group;

	private static Material baseMaterial;

	private static Dictionary<string, CachedViewManager> groups = new Dictionary<string, CachedViewManager>();

	private static Vector3 currentMasterPositionOffset = Vector3.zero;

	private static GameObject cachedViewObjectsRoot = null;

	private GameObject cameraGameObject;

	private Canvas masterCanvas;

	private ImposterGraphicRaycaster masterObjectRaycaster;

	private Camera masterCamera;

	private List<GameObject> allImposters = new List<GameObject>();

	private RenderTexture sharedRenderTexture;

	private Material sharedMaterial;

	private bool isMarkedForRender;

	private float targetAspectRatio;

	private float targetSize;

	private static Material BaseMaterial
	{
		get
		{
			if (baseMaterial == null)
			{
				baseMaterial = Resources.Load<Material>(baseMaterialResourcePath);
			}
			return baseMaterial;
		}
	}

	public Canvas MasterCanvas => masterCanvas;

	public ImposterGraphicRaycaster MasterObjectRaycaster => masterObjectRaycaster;

	public Camera MasterCamera => masterCamera;

	public static CachedViewManager Get(string group)
	{
		if (!groups.TryGetValue(group, out var value))
		{
			GameObject gameObject = new GameObject($"CachedViewManager (\"{group}\")");
			value = gameObject.AddComponent<CachedViewManager>();
			value.group = group;
			value.sharedRenderTexture = new RenderTexture(1024, 1024, 24)
			{
				filterMode = FilterMode.Bilinear,
				anisoLevel = 4,
				autoGenerateMips = false,
				useMipMap = false,
				antiAliasing = 4
			};
			value.sharedMaterial = new Material(BaseMaterial);
			value.sharedMaterial.mainTexture = value.sharedRenderTexture;
			groups.Add(group, value);
			if (cachedViewObjectsRoot == null)
			{
				cachedViewObjectsRoot = new GameObject("CachedView Master Objects");
			}
			value.transform.SetParent(cachedViewObjectsRoot.transform);
		}
		return value;
	}

	private void OnDestroy()
	{
		groups.Remove(group);
	}

	public void AddView(CachedView cachedView)
	{
		GameObject item = SetupImposter(cachedView);
		allImposters.Add(item);
	}

	public void RemoveImposter(GameObject imposterGameObject)
	{
		allImposters.Remove(imposterGameObject);
	}

	public void MarkForRender()
	{
		isMarkedForRender = true;
	}

	public void Update()
	{
		if (!isMarkedForRender)
		{
			masterCamera.enabled = false;
			return;
		}
		Dictionary<string, CachedViewManager>.ValueCollection values = groups.Values;
		CachedViewManager cachedViewManager = values.ElementAt(UnityEngine.Time.frameCount % values.Count);
		if (cachedViewManager != this)
		{
			masterCamera.enabled = false;
			return;
		}
		if (masterCamera.aspect != targetAspectRatio || masterCamera.orthographicSize != targetSize)
		{
			masterCamera.aspect = targetAspectRatio;
			masterCamera.orthographicSize = targetSize;
		}
		masterCamera.enabled = true;
		isMarkedForRender = false;
	}

	private GameObject SetupImposter(CachedView cachedView)
	{
		Transform parent = cachedView.transform.parent;
		GameObject gameObject = new GameObject($"CachedView Imposter ({group})");
		gameObject.SetLayerRecursively(Layers.UI);
		cachedView.transform.SetParent(base.transform, worldPositionStays: false);
		gameObject.transform.SetParent(parent, worldPositionStays: false);
		Canvas canvas = gameObject.AddComponent<Canvas>();
		gameObject.AddComponent<CanvasScaler>();
		UnityEngine.UI.Image image = gameObject.AddComponent<UnityEngine.UI.Image>();
		image.material = sharedMaterial;
		ImposterGraphicRaycaster imposterGraphicRaycaster = gameObject.AddComponent<ImposterGraphicRaycaster>();
		imposterGraphicRaycaster.ImposterViewManager = this;
		gameObject.transform.localPosition = cachedView.transform.localPosition;
		gameObject.transform.localRotation = cachedView.transform.localRotation;
		gameObject.transform.localScale = cachedView.transform.localScale;
		RectTransform rectTransform = (RectTransform)gameObject.transform;
		RectTransform rectTransform2 = (RectTransform)cachedView.transform;
		Vector2 sizeDelta = rectTransform2.sizeDelta;
		rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, sizeDelta.x);
		rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, sizeDelta.y);
		BoxCollider boxCollider = gameObject.AddComponent<BoxCollider>();
		boxCollider.size = new Vector3(sizeDelta.x, sizeDelta.y, 1f);
		MeshFilter meshFilter = gameObject.AddComponent<MeshFilter>();
		Vector3[] array = new Vector3[4];
		((RectTransform)canvas.transform).GetLocalCorners(array);
		meshFilter.mesh = new Mesh
		{
			vertices = array
		};
		MeshRenderer meshRenderer = gameObject.AddComponent<MeshRenderer>();
		meshRenderer.lightProbeUsage = LightProbeUsage.Off;
		meshRenderer.reflectionProbeUsage = ReflectionProbeUsage.Off;
		meshRenderer.shadowCastingMode = ShadowCastingMode.Off;
		meshRenderer.motionVectorGenerationMode = MotionVectorGenerationMode.ForceNoMotion;
		meshRenderer.receiveShadows = false;
		if (masterCanvas == null)
		{
			GameObject gameObject2 = cachedView.gameObject;
			UnityEngine.Object.Destroy(cachedView);
			masterCanvas = gameObject2.GetComponent<Canvas>();
			if (masterCanvas.worldCamera == null)
			{
				masterCanvas.worldCamera = UIInputModule.Instance.ControllerCamera;
			}
			BaseRaycaster component = gameObject2.gameObject.GetComponent<BaseRaycaster>();
			if (component != null)
			{
				UnityEngine.Object.Destroy(component);
			}
			masterObjectRaycaster = gameObject2.AddComponent<ImposterGraphicRaycaster>();
			masterObjectRaycaster.ignoresAllInput = true;
			gameObject2.ReplaceLayerRecursively(Layers.UI, Layers.CachedView);
			CanvasUtilities.GetCanvasWidthHeight(masterCanvas, out var width, out var _);
			float num = 1f;
			currentMasterPositionOffset += new Vector3(width + num, 0f, 0f);
			Vector3 position = currentMasterPositionOffset;
			currentMasterPositionOffset += new Vector3(width + num, 0f, 0f);
			gameObject2.transform.position = position;
			gameObject2.transform.rotation = Quaternion.identity;
			cameraGameObject = new GameObject($"CachedView Camera ({group})");
			cameraGameObject.transform.SetParent(gameObject2.transform, worldPositionStays: false);
			masterCamera = cameraGameObject.AddComponent<Camera>();
			masterCamera.clearFlags = CameraClearFlags.Color;
			masterCamera.backgroundColor = new Color(0f, 0f, 0f, 0f);
			masterCamera.cullingMask = int.MinValue;
			masterCamera.renderingPath = RenderingPath.Forward;
			masterCamera.useOcclusionCulling = false;
			masterCamera.allowHDR = false;
			masterCamera.allowMSAA = false;
			masterCamera.stereoTargetEye = StereoTargetEyeMask.None;
			masterCamera.targetTexture = sharedRenderTexture;
			masterCamera.orthographic = true;
			CanvasUtilities.MatchOrthographicCameraToCanvas(masterCamera, masterCanvas);
			targetSize = masterCamera.orthographicSize;
			targetAspectRatio = masterCamera.aspect;
		}
		else
		{
			UnityEngine.Object.Destroy(cachedView.gameObject);
		}
		return gameObject;
	}
}
public class CanvasUtilities
{
	private const Layers renderLayer = Layers.Water;

	private const int layerMask = 16;

	private static Camera renderCam;

	public static RenderTexture ConvertToTexture(Canvas theCanvas)
	{
		RectTransform rectTransform = theCanvas.transform as RectTransform;
		RenderTexture renderTexture = new RenderTexture((int)rectTransform.rect.width, (int)rectTransform.rect.height, 24, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Default);
		ConvertToTexture(theCanvas, renderTexture);
		return renderTexture;
	}

	public static void ConvertToTexture(Canvas theCanvas, RenderTexture texToUse)
	{
		Camera camera = GetRenderCam();
		camera.targetTexture = texToUse;
		MatchOrthographicCameraToCanvas(camera, theCanvas);
		int layer = theCanvas.gameObject.layer;
		theCanvas.gameObject.ReplaceLayerRecursively((Layers)layer, Layers.Water);
		camera.Render();
		theCanvas.gameObject.ReplaceLayerRecursively(Layers.Water, (Layers)layer);
		camera.targetTexture = null;
	}

	public static void GetCanvasWidthHeight(Canvas canvas, out float width, out float height)
	{
		if (canvas.renderMode == RenderMode.WorldSpace)
		{
			Vector2 sizeDelta = ((RectTransform)canvas.transform).sizeDelta;
			width = sizeDelta.x * canvas.transform.lossyScale.x;
			height = sizeDelta.y * canvas.transform.lossyScale.y;
		}
		else
		{
			width = canvas.pixelRect.width;
			height = canvas.pixelRect.height;
		}
	}

	public static void MatchOrthographicCameraToCanvas(Camera camera, Canvas canvasToUse)
	{
		if (canvasToUse.renderMode != RenderMode.WorldSpace)
		{
			canvasToUse.worldCamera = camera;
		}
		GetCanvasWidthHeight(canvasToUse, out var width, out var height);
		camera.gameObject.transform.position = canvasToUse.transform.position - canvasToUse.transform.forward;
		camera.gameObject.transform.rotation = Quaternion.LookRotation(canvasToUse.transform.forward);
		camera.orthographicSize = height / 2f;
		camera.aspect = width / height;
	}

	private static Camera GetRenderCam()
	{
		if (renderCam == null)
		{
			GameObject gameObject = new GameObject("CanvasToTextureCam");
			UnityEngine.Object.DontDestroyOnLoad(gameObject);
			gameObject.SetActive(value: false);
			renderCam = gameObject.AddComponent<Camera>();
			renderCam.clearFlags = CameraClearFlags.Color;
			renderCam.backgroundColor = new Color(0f, 0f, 0f, 0f);
			renderCam.cullingMask = 16;
			renderCam.renderingPath = RenderingPath.Forward;
			renderCam.useOcclusionCulling = false;
			renderCam.allowHDR = false;
			renderCam.allowMSAA = false;
			renderCam.stereoTargetEye = StereoTargetEyeMask.None;
			renderCam.orthographic = true;
		}
		return renderCam;
	}
}
public class DailyObjectiveView : UnityEngine.MonoBehaviour
{
	[SerializeField]
	protected TextMeshProUGUI description;

	[SerializeField]
	protected TextMeshProUGUI progressLabel;

	[SerializeField]
	protected Slider progressSlider;

	[SerializeField]
	protected GameObject completionVisual;

	[SerializeField]
	protected Tooltip tooltip;

	[SerializeField]
	private GameObject tokenObject;

	[SerializeField]
	private TextMeshProUGUI tokenValueText;

	public void UpdateTokenText(string newText)
	{
		if (tokenValueText != null)
		{
			tokenValueText.text = newText;
		}
	}

	public virtual void UpdateProgress(int progress, int total, bool completed, bool rewardAvailable, string helpText, string tooltipText)
	{
		if (completed)
		{
			completionVisual.SetActive(value: true);
			progressSlider.value = 1f;
			progressLabel.gameObject.SetActive(value: false);
			if (tokenObject != null)
			{
				tokenObject.SetActive(value: false);
			}
		}
		else
		{
			completionVisual.SetActive(value: false);
			progressSlider.value = (((float)total != 0f) ? Mathf.Clamp01((float)progress / (float)total) : 0f);
			if (total > 1)
			{
				progressLabel.gameObject.SetActive(value: true);
				progressLabel.text = "(" + progress + "/" + total + ")";
			}
			else
			{
				progressLabel.gameObject.SetActive(value: false);
			}
			if (tokenObject != null)
			{
				tokenObject.SetActive(value: true);
			}
		}
		description.text = helpText;
		tooltip.Message = tooltipText;
	}

	public virtual void AnimateProgress(int prevProgress, int currProgress, int total, bool wasCompleted, bool isCompleted, bool rewardAvailable, string helpText, string tooltipText, Action onAnimComplete)
	{
		UpdateProgress(currProgress, total, isCompleted, rewardAvailable, helpText, tooltipText);
		onAnimComplete?.Invoke();
	}
}
