namespace RecRoom
{
	[AddComponentMenu("Event/Fast Graphic Raycaster")]
	[RequireComponent(typeof(Canvas))]
	public class FastGraphicRaycaster : BaseRaycaster
	{
		private struct GraphicContainer
		{
			public Graphic Graphic;

			public int Depth;

			public Bounds Bounds;
		}

		protected Canvas cachedCanvas;

		protected Camera cachedEventCamera;

		private bool isInitialized;

		[NonSerialized]
		private List<Graphic> m_RaycastResults = new List<Graphic>();

		private int cachedFrame = -1;

		private List<GraphicContainer> m_CachedGraphics = new List<GraphicContainer>();

		private Vector3[] tempWorldCorners = new Vector3[4];

		[NonSerialized]
		private List<GraphicContainer> m_SortedGraphics = new List<GraphicContainer>();

		public override Camera eventCamera => cachedEventCamera;

		protected FastGraphicRaycaster()
		{
		}

		public override void Raycast(PointerEventData eventData, List<RaycastResult> resultAppendList)
		{
			if (!InitializeIfNeeded())
			{
				return;
			}
			Vector2 position = eventData.position;
			Ray ray = cachedEventCamera.ScreenPointToRay(position);
			float num = float.MaxValue;
			m_RaycastResults.Clear();
			Raycast(cachedCanvas, cachedEventCamera, position, ray, m_RaycastResults);
			for (int i = 0; i < m_RaycastResults.Count; i++)
			{
				GameObject gameObject = m_RaycastResults[i].gameObject;
				Vector3 lhs = cachedEventCamera.transform.rotation * Vector3.forward;
				Vector3 rhs = gameObject.transform.rotation * Vector3.forward;
				if (!(Vector3.Dot(lhs, rhs) > 0f))
				{
					continue;
				}
				float num2 = 0f;
				if (cachedEventCamera == null)
				{
					num2 = 0f;
				}
				else
				{
					Transform transform = gameObject.transform;
					Vector3 forward = transform.forward;
					num2 = Vector3.Dot(forward, transform.position - ray.origin) / Vector3.Dot(forward, ray.direction);
					if (num2 < 0f)
					{
						continue;
					}
				}
				if (!(num2 >= num))
				{
					RaycastResult item = new RaycastResult
					{
						gameObject = gameObject,
						module = this,
						distance = num2,
						screenPosition = position,
						index = resultAppendList.Count,
						depth = m_RaycastResults[i].depth,
						sortingLayer = cachedCanvas.sortingLayerID,
						sortingOrder = cachedCanvas.sortingOrder
					};
					resultAppendList.Add(item);
				}
			}
		}

		protected bool InitializeIfNeeded()
		{
			if (!isInitialized)
			{
				if (cachedCanvas == null)
				{
					cachedCanvas = GetComponent<Canvas>();
					if (cachedCanvas == null)
					{
						return false;
					}
					if (cachedCanvas.renderMode != RenderMode.WorldSpace)
					{
						UnityEngine.Debug.LogError("AGGraphicRaycaster expects a WorldSpace canvas");
					}
				}
				if (cachedEventCamera == null)
				{
					cachedEventCamera = cachedCanvas.worldCamera;
					if (cachedEventCamera == null)
					{
						return false;
					}
				}
				isInitialized = true;
			}
			return isInitialized;
		}

		private void Raycast(Canvas canvas, Camera eventCamera, Vector2 pointerPosition, Ray ray, List<Graphic> results)
		{
			if (UnityEngine.Time.frameCount != cachedFrame)
			{
				cachedFrame = UnityEngine.Time.frameCount;
				m_CachedGraphics.Clear();
				IList<Graphic> graphicsForCanvas = GraphicRegistry.GetGraphicsForCanvas(canvas);
				int count = graphicsForCanvas.Count;
				for (int i = 0; i < count; i++)
				{
					Graphic graphic = graphicsForCanvas[i];
					if (!graphic.raycastTarget)
					{
						continue;
					}
					int depth = graphic.depth;
					if (depth == -1)
					{
						continue;
					}
					graphic.rectTransform.GetWorldCorners(tempWorldCorners);
					Vector3 vector = tempWorldCorners[0];
					float num = vector.x;
					float num2 = num;
					float num3 = vector.y;
					float num4 = num3;
					float num5 = vector.z;
					float num6 = num5;
					for (int j = 1; j < 4; j++)
					{
						Vector3 vector2 = tempWorldCorners[j];
						float x = vector2.x;
						float y = vector2.y;
						float z = vector2.z;
						if (x < num)
						{
							num = x;
						}
						if (x > num2)
						{
							num2 = x;
						}
						if (y < num3)
						{
							num3 = y;
						}
						if (y > num4)
						{
							num4 = y;
						}
						if (z < num5)
						{
							num5 = z;
						}
						if (z > num6)
						{
							num6 = z;
						}
					}
					Vector3 center = new Vector3((num + num2) / 2f, (num3 + num4) / 2f, (num5 + num6) / 2f);
					Vector3 size = new Vector3(num2 - num, num4 - num3, num6 - num5);
					Bounds bounds = new Bounds(center, size);
					m_CachedGraphics.Add(new GraphicContainer
					{
						Depth = depth,
						Graphic = graphic,
						Bounds = bounds
					});
				}
			}
			int count2 = m_CachedGraphics.Count;
			for (int k = 0; k < count2; k++)
			{
				GraphicContainer item = m_CachedGraphics[k];
				if (item.Bounds.IntersectRay(ray) && RectTransformUtility.RectangleContainsScreenPoint(item.Graphic.rectTransform, pointerPosition, eventCamera) && item.Graphic.Raycast(pointerPosition, eventCamera))
				{
					m_SortedGraphics.Add(item);
				}
			}
			m_SortedGraphics.Sort((GraphicContainer a, GraphicContainer b) => a.Depth.CompareTo(b.Depth));
			for (int num7 = 0; num7 < m_SortedGraphics.Count; num7++)
			{
				results.Add(m_SortedGraphics[num7].Graphic);
			}
			m_SortedGraphics.Clear();
		}
	}
}
public class HealthBar : UnityEngine.MonoBehaviour
{
	private static int colorID = Shader.PropertyToID("_TintColor");

	[Header("Background")]
	[SerializeField]
	private GameObject backgroundVisualGroup;

	[Header("Main Health Slider")]
	[SerializeField]
	private GameObject mainHealthVisual;

	[SerializeField]
	private float damageHealthChangeDelay = 0.5f;

	[SerializeField]
	private Color healthColor = Color.red;

	[Header("Damage Slider")]
	[SerializeField]
	private GameObject damagedHealthVisual;

	[SerializeField]
	private GameObject damagedHealthTransform;

	[SerializeField]
	private float damagedHealthChangeTime = 1f;

	[SerializeField]
	private Color damageColor = new Color(1f, 1f, 0f, 1f);

	[Header("Enable Disable Fading")]
	[SerializeField]
	private float fadeInDuration = 0.1f;

	[SerializeField]
	private float fadeOutDuration = 0.5f;

	[Header("View Fading")]
	[SerializeField]
	private bool onlyShowWhenDamaged;

	[SerializeField]
	private bool supportsViewFading = true;

	[SerializeField]
	private float fullyOpaqueDistance = 10f;

	[SerializeField]
	private float fullyTransparentDistance = 16f;

	[Header("Local Damage Fading")]
	[SerializeField]
	private float localDamageVisibleDuration = 0.2f;

	[SerializeField]
	private float localDamageFadingDuration = 0.1f;

	[NonSerialized]
	public bool AlwaysViewVisible;

	private Material backgroundMaterial;

	private Material healthMaterial;

	private Material damageMaterial;

	private float lastHealthChangeTime;

	private float damagedHealthChangeSpeed;

	private float normalizedHealth;

	private float lastLocalDamageHealthChangeTime;

	private Coroutine fadeCoroutine;

	private bool alphaIsDirty = true;

	private Renderer[] renderers;

	private float _enableDisableFadeAlpha = 1f;

	private float _damageMaterialFadeAlpha = 1f;

	private float _viewFadeAlpha = 1f;

	public float Alpha => (!AlwaysViewVisible) ? (EnableDisableFadeAlpha * ViewFadeAlpha) : 1f;

	private float EnableDisableFadeAlpha
	{
		get
		{
			return _enableDisableFadeAlpha;
		}
		set
		{
			_enableDisableFadeAlpha = value;
			alphaIsDirty = true;
		}
	}

	private float DamageMaterialFadeAlpha
	{
		get
		{
			return _damageMaterialFadeAlpha;
		}
		set
		{
			_damageMaterialFadeAlpha = value;
			alphaIsDirty = true;
		}
	}

	private float ViewFadeAlpha
	{
		get
		{
			return _viewFadeAlpha;
		}
		set
		{
			_viewFadeAlpha = value;
			alphaIsDirty = true;
		}
	}

	private void Awake()
	{
		backgroundMaterial = InitializeMaterialOnVisualGroup(backgroundVisualGroup, healthColor);
		healthMaterial = InitializeMaterialOnVisualGroup(mainHealthVisual, healthColor);
		damageMaterial = InitializeMaterialOnVisualGroup(damagedHealthVisual, damageColor);
		renderers = GetComponentsInChildren<Renderer>(includeInactive: true);
		if (onlyShowWhenDamaged)
		{
			SetVisible(visible: false);
		}
	}

	private Material InitializeMaterialOnVisualGroup(GameObject visualGroupRoot, Color color)
	{
		Renderer[] componentsInChildren = visualGroupRoot.GetComponentsInChildren<Renderer>(includeInactive: true);
		Material material = new Material(componentsInChildren[0].sharedMaterial);
		material.SetColor(colorID, color);
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].sharedMaterial = material;
		}
		return material;
	}

	private void Update()
	{
		UpdateDamageFading();
		UpdateViewFading();
		damagedHealthVisual.transform.position = damagedHealthTransform.transform.position;
		if (alphaIsDirty)
		{
			OnAlphaChange();
		}
	}

	public void ResetHealth(float health, float maxHealth)
	{
		OnHealthChange(health, maxHealth, localPlayerCausedDamage: false);
		SetSliderValue(damagedHealthVisual, 0f);
		SetSliderValue(mainHealthVisual, normalizedHealth);
	}

	private void SetSliderValue(GameObject obj, float value)
	{
		Vector3 localScale = obj.transform.localScale;
		localScale.x = value;
		obj.transform.localScale = localScale;
		bool active = value > 0f;
		obj.SetActive(active);
	}

	public void OnHealthChange(float health, float maxHealth, bool localPlayerCausedDamage)
	{
		DamageMaterialFadeAlpha = 1f;
		float num = normalizedHealth;
		normalizedHealth = Mathf.InverseLerp(0f, maxHealth, health);
		lastHealthChangeTime = UnityEngine.Time.time;
		SetSliderValue(mainHealthVisual, normalizedHealth);
		SetSliderValue(damagedHealthVisual, Mathf.Max(0f, num - normalizedHealth));
		if (onlyShowWhenDamaged)
		{
			SetVisible(health != maxHealth);
		}
		if (localPlayerCausedDamage)
		{
			lastLocalDamageHealthChangeTime = UnityEngine.Time.time;
		}
	}

	private void SetVisible(bool visible)
	{
		if (renderers != null)
		{
			Renderer[] array = renderers;
			foreach (Renderer renderer in array)
			{
				renderer.enabled = visible;
			}
		}
	}

	private void OnAlphaChange()
	{
		ApplyAlphaChange(backgroundMaterial);
		ApplyAlphaChange(healthMaterial);
		ApplyAlphaChange(damageMaterial, DamageMaterialFadeAlpha);
		alphaIsDirty = false;
	}

	private void ApplyAlphaChange(Material material, float alphaMultiplier = 1f)
	{
		float alpha = Alpha;
		Color color = material.GetColor(colorID);
		color.a = alpha * alphaMultiplier;
		material.SetColor(colorID, color);
	}

	public void FadeIn()
	{
		base.gameObject.SetActive(value: true);
		StopFadeCoroutine();
		fadeCoroutine = StartCoroutine(FadeInCoroutine());
	}

	public void FadeOut()
	{
		base.gameObject.SetActive(value: true);
		StopFadeCoroutine();
		fadeCoroutine = StartCoroutine(FadeOutCoroutine());
	}

	private IEnumerator FadeInCoroutine()
	{
		base.gameObject.SetActive(value: true);
		yield return FadeCoroutine(fadeInDuration, 0f, 1f);
	}

	private IEnumerator FadeOutCoroutine()
	{
		yield return FadeCoroutine(fadeOutDuration, 1f, 0f);
		base.gameObject.SetActive(value: false);
	}

	private IEnumerator FadeCoroutine(float duration, float initialAlpha, float finalAlpha)
	{
		EnableDisableFadeAlpha = initialAlpha;
		float timer = 0f;
		while (timer < duration)
		{
			yield return null;
			timer += UnityEngine.Time.deltaTime;
			EnableDisableFadeAlpha = Mathf.Lerp(initialAlpha, finalAlpha, Mathf.Clamp01(timer / duration));
		}
		EnableDisableFadeAlpha = finalAlpha;
	}

	private void StopFadeCoroutine()
	{
		if (fadeCoroutine != null)
		{
			StopCoroutine(fadeCoroutine);
			fadeCoroutine = null;
		}
	}

	private void UpdateDamageFading()
	{
		if (UnityEngine.Time.time - lastHealthChangeTime >= damageHealthChangeDelay)
		{
			DamageMaterialFadeAlpha = Mathf.SmoothDamp(DamageMaterialFadeAlpha, 0f, ref damagedHealthChangeSpeed, damagedHealthChangeTime);
		}
	}

	private void UpdateViewFading()
	{
		if (AlwaysViewVisible)
		{
			ViewFadeAlpha = 1f;
			return;
		}
		float a = 0f;
		if (UnityEngine.Time.time - lastLocalDamageHealthChangeTime <= localDamageVisibleDuration + localDamageFadingDuration)
		{
			float num = lastLocalDamageHealthChangeTime + localDamageVisibleDuration;
			float b = num + localDamageFadingDuration;
			float t = Mathf.InverseLerp(num, b, UnityEngine.Time.time);
			a = Mathf.SmoothStep(1f, 0f, t);
		}
		float b2 = 0f;
		if (supportsViewFading && SingletonMonoBehaviour<CameraRig>.Instance != null && SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera != null)
		{
			Vector3 vector = Vector3.ProjectOnPlane(base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position, Vector3.up);
			float t2 = Mathf.InverseLerp(fullyTransparentDistance * fullyTransparentDistance, fullyOpaqueDistance * fullyOpaqueDistance, vector.sqrMagnitude);
			b2 = Mathf.SmoothStep(0f, 1f, t2);
		}
		ViewFadeAlpha = Mathf.Max(a, b2);
	}
}
namespace RecRoom
{
	public class ImposterGraphicRaycaster : FastGraphicRaycaster
	{
		public CachedViewManager ImposterViewManager;

		private Collider cachedCollider;

		public bool ignoresAllInput;

		protected override void OnDestroy()
		{
			if (ImposterViewManager != null)
			{
				ImposterViewManager.RemoveImposter(base.gameObject);
			}
			base.OnDestroy();
		}

		private void OnWillRenderObject()
		{
			ImposterViewManager.MarkForRender();
		}

		public override void Raycast(PointerEventData eventData, List<RaycastResult> resultAppendList)
		{
			if (ignoresAllInput || !ImposterViewManager.MasterObjectRaycaster.enabled)
			{
				return;
			}
			InitializeIfNeeded();
			Camera worldCamera = ImposterViewManager.MasterCanvas.worldCamera;
			Vector2 position = eventData.position;
			Ray ray = worldCamera.ScreenPointToRay(position);
			if (cachedCollider == null)
			{
				cachedCollider = base.gameObject.GetComponent<Collider>();
			}
			RaycastHit hitInfo = default(RaycastHit);
			if (cachedCollider.Raycast(ray, out hitInfo, worldCamera.farClipPlane))
			{
				Vector3 vector = base.transform.InverseTransformPoint(hitInfo.point);
				Vector2 sizeDelta = ((RectTransform)base.transform).sizeDelta;
				Vector2 vector2 = new Vector2(vector.x / sizeDelta.x + 0.5f, vector.y / sizeDelta.y + 0.5f);
				float num = ImposterViewManager.MasterCamera.pixelHeight;
				float num2 = ImposterViewManager.MasterCamera.pixelWidth;
				Vector2 position2 = new Vector2(vector2.x * num2, vector2.y * num);
				Vector2 position3 = eventData.position;
				eventData.position = position2;
				cachedCanvas = ImposterViewManager.MasterCanvas;
				cachedEventCamera = ImposterViewManager.MasterCamera;
				int count = resultAppendList.Count;
				base.Raycast(eventData, resultAppendList);
				eventData.position = position3;
				for (int i = count; i < resultAppendList.Count; i++)
				{
					RaycastResult value = resultAppendList[i];
					value.distance = hitInfo.distance;
					value.screenPosition = eventData.position;
					value.worldPosition = hitInfo.point;
					value.worldNormal = -hitInfo.normal;
					resultAppendList[i] = value;
				}
			}
		}
	}
}
