public class LeaderboardBodyView : ProjectorUIElementView
{
	[SerializeField]
	private GameObject loadingUI;

	[Header("Rows")]
	[SerializeField]
	private LeaderboardRowView rowPrefab;

	[SerializeField]
	private int maxRowCount = 10;

	private LeaderboardRowView[] rows;

	private ElementColors _colors;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			for (int i = 0; i < rows.Length; i++)
			{
				rows[i].Colors = _colors;
			}
		}
	}

	public void SetDataModel(LeaderboardUIDataModel model)
	{
		int i = 0;
		loadingUI.SetActive(model.IsLoading);
		if (!model.IsLoading)
		{
			for (; i < model.Entries.Length && i < rows.Length; i++)
			{
				rows[i].gameObject.SetActive(value: true);
				rows[i].SetDataModel(model.Entries[i]);
			}
		}
		for (; i < rows.Length; i++)
		{
			rows[i].gameObject.SetActive(value: false);
