	public string Score;
}
public class LeaderboardController : UnityEngine.MonoBehaviour
{
	[Serializable]
	private struct LeaderboardParams
	{
		public string FullTitle;

		public string ShortTitle;

		public string ScoreLabel;

		public ProgressionManager.ObjectiveType Objective;

		public bool SortAscending;
	}

	[SerializeField]
	private LeaderboardView view;

	[SerializeField]
	private int numRows = 10;

	[SerializeField]
	private LeaderboardParams[] leaderboardParams;

	private GameManager gameManager;

	private bool isOverall;

	private bool isGlobal;

	private int currentLeaderboardIdx;

	private Leaderboard[] leaderboards;

	private bool[] leaderboardsAreDirty;

	private LeaderboardUIDataModel dataModel;

	private bool dataIsDirty = true;

	private bool requiresDelayedViewInit;

	private bool isInitialized;

	private void Start()
	{
		int num = leaderboardParams.Length;
		leaderboards = new Leaderboard[num];
		leaderboardsAreDirty = new bool[num];
		for (int i = 0; i < num; i++)
		{
			leaderboardsAreDirty[i] = true;
		}
		gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		if (gameManager != null)
		{
			gameManager.StateChangeEvent += OnGameStateChanged;
		}
		if (GetComponentInChildren<CachedView>() != null)
		{
			requiresDelayedViewInit = true;
		}
		if (!requiresDelayedViewInit)
		{
			InitializeView();
		}
	}

	private void InitializeView()
	{
		int num = leaderboardParams.Length;
		if (view == null)
		{
			view = GetComponentInChildren<LeaderboardView>();
			if (view == null)
			{
				ImposterGraphicRaycaster componentInChildren = GetComponentInChildren<ImposterGraphicRaycaster>();
				if (componentInChildren != null)
				{
					view = componentInChildren.ImposterViewManager.MasterCanvas.gameObject.GetComponentInChildren<LeaderboardView>();
				}
			}
		}
		view.TimeSpanButtonPressEvent += OnTimeSpanButtonPressed;
		view.UserSetButtonPressEvent += OnUserSetButtonPressed;
		view.StatTypeButtonPressEvent += OnStatTypeButtonPressed;
		dataModel = new LeaderboardUIDataModel();
		dataModel.HasMultipleLeaderboards = num > 1;
		dataModel.Entries = new LeaderboardEntryDataModel[numRows];
		for (int i = 0; i < numRows; i++)
		{
			dataModel.Entries[i] = new LeaderboardEntryDataModel();
		}
		Profiles.OnProfileUpdated += OnProfileUpdated;
		UpdateDataModel();
		UpdateLeaderboard(currentLeaderboardIdx);
		dataIsDirty = false;
		isInitialized = true;
	}

	private void OnDestroy()
	{
		Profiles.OnProfileUpdated -= OnProfileUpdated;
		if (gameManager != null)
		{
			gameManager.StateChangeEvent -= OnGameStateChanged;
		}
		if (view != null)
		{
			view.TimeSpanButtonPressEvent -= OnTimeSpanButtonPressed;
			view.UserSetButtonPressEvent -= OnUserSetButtonPressed;
			view.StatTypeButtonPressEvent -= OnStatTypeButtonPressed;
		}
	}

	private void Update()
	{
		if (requiresDelayedViewInit)
		{
			InitializeView();
			requiresDelayedViewInit = false;
		}
		if (dataIsDirty && isInitialized)
		{
			UpdateDataModel();
			dataIsDirty = false;
		}
	}

	private void OnGameStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		if (currentStateId == 3 && currentSubStateId == 1)
		{
			for (int i = 0; i < leaderboards.Length; i++)
			{
				leaderboardsAreDirty[i] = true;
				leaderboards[i] = null;
			}
			UpdateLeaderboard(currentLeaderboardIdx);
		}
	}

	private void OnProfileUpdated(long id)
	{
		if (dataModel.Entries.Any((LeaderboardEntryDataModel entry) => entry.ProfileId == id))
		{
			dataIsDirty = true;
		}
	}

	private void OnTimeSpanButtonPressed()
	{
		isOverall = !isOverall;
		dataIsDirty = true;
	}

	private void OnUserSetButtonPressed()
	{
		isGlobal = !isGlobal;
		dataIsDirty = true;
	}

	private void OnStatTypeButtonPressed()
	{
		currentLeaderboardIdx = (currentLeaderboardIdx + 1) % leaderboards.Length;
		if (leaderboardsAreDirty[currentLeaderboardIdx])
		{
			UpdateLeaderboard(currentLeaderboardIdx);
		}
		dataIsDirty = true;
	}

	private void UpdateDataModel()
	{
		Leaderboard leaderboard = leaderboards[currentLeaderboardIdx];
		dataModel.IsOverall = isOverall;
		dataModel.IsGlobal = isGlobal;
		dataModel.IsLoading = leaderboard == null;
		dataModel.FullTitle = leaderboardParams[currentLeaderboardIdx].FullTitle;
		dataModel.ShortTitle = leaderboardParams[currentLeaderboardIdx].ShortTitle;
		dataModel.ScoreLabel = leaderboardParams[currentLeaderboardIdx].ScoreLabel;
		List<Leaderboard.Entry> list = null;
		if (leaderboard != null)
		{
			list = (isOverall ? ((!isGlobal) ? leaderboard.FriendsOverall : leaderboard.GlobalOverall) : ((!isGlobal) ? leaderboard.FriendsPeriodic : leaderboard.GlobalPeriodic));
		}
		for (int i = 0; i < numRows; i++)
		{
			if (list != null && list.Count > i)
			{
				long playerId = list[i].PlayerId;
				dataModel.Entries[i].IsActive = true;
				dataModel.Entries[i].IsLocal = playerId == RecNet.Core.LocalProfileId;
				dataModel.Entries[i].ProfileId = playerId;
				dataModel.Entries[i].Profile = Profiles.Get(playerId);
				dataModel.Entries[i].Score = list[i].Count.ToString();
				dataModel.Entries[i].Order = ((list[i].Order == 999999) ? string.Empty : list[i].Order.ToString());
			}
			else
			{
				dataModel.Entries[i].IsActive = false;
			}
		}
		view.SetDataModel(dataModel);
	}

	private void UpdateLeaderboard(int idx)
	{
		leaderboardsAreDirty[idx] = false;
		RecNet.Leaderboards.Get(leaderboardParams[idx].Objective, leaderboardParams[idx].SortAscending, numRows, delegate(string error, Leaderboard result)
		{
			if (!string.IsNullOrEmpty(error))
			{
				leaderboardsAreDirty[idx] = true;
				UnityEngine.Debug.LogError("Failed to retrieve leaderboard: " + error);
			}
			else
			{
				leaderboards[idx] = result;
				dataIsDirty = true;
			}
		});
	}
}
