public class LeaderboardRowView : ProjectorUIElementView
{
	[SerializeField]
	private Text orderText;

	[SerializeField]
	private RawImage profileImage;

	[SerializeField]
	private Text nameText;

	[SerializeField]
	private Text scoreText;

	private Profile currentProfile;

	protected override void Awake()
	{
		base.Awake();
		ReloadProfileImage();
	}

	public void SetDataModel(LeaderboardEntryDataModel dataModel)
	{
		bool flag = currentProfile != dataModel.Profile;
		currentProfile = dataModel.Profile;
		orderText.text = ((!dataModel.IsActive) ? string.Empty : dataModel.Order);
		scoreText.text = ((!dataModel.IsActive) ? string.Empty : dataModel.Score);
		nameText.text = ((!dataModel.IsActive || dataModel.Profile == null) ? string.Empty : ((string)dataModel.Profile.DisplayName));
		profileImage.gameObject.SetActive(dataModel.IsActive);
		if (flag)
		{
			ReloadProfileImage();
		}
		ApplyColors(dataModel.IsActive && dataModel.IsLocal);
	}

	private void ReloadProfileImage()
	{
		Profile profile = currentProfile;
		Images.GetProfileImage(profile).Then(delegate(Texture2D image)
		{
			if (this != null && currentProfile == profile)
			{
				profileImage.texture = image;
			}
		});
	}
}
