	{
		if (thisCanvas != null && UIInputModule.Instance != null)
		{
			thisCanvas.worldCamera = UIInputModule.Instance.ControllerCamera;
		}
		ProjectorUIElementView.ElementColors colors = new ProjectorUIElementView.ElementColors
		{
			TextColor = textColor,
			BackgroundColor = primaryColor,
			DefaultBackgroundAlpha = defaultBackgroundAlpha,
