	{
		this.dataModel = dataModel;
		isDirty = true;
	}

	private void UpdateView()
	{
		if (isDirty && initialized)
		{
			thisRaycaster.enabled = true;
			header.SetDataModel(dataModel);
			footer.SetDataModel(dataModel);
			body.SetDataModel(dataModel);
			isDirty = false;
		}
	}
