	public class CharadesPenBasicUIFlow : ToolUIFlow
	{
		[SerializeField]
		protected RadioGroup3D shapeRadioGroup;

		protected ColorPickerScreen colorPickerScreen;

		public CharadesPen CharadesPen { get; set; }

		protected override string SizeConfigKey => "MAKER_PEN";

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			CharadesPen = base.ToolUI.Tool.GetComponent<CharadesPen>();
			colorPickerScreen = GetComponentInChildren<ColorPickerScreen>();
		}

		public override void StackedUIOpened()
		{
			base.StackedUIOpened();
			UpdateUIElements();
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			UpdateUIElements();
		}

		public override void UpdateUIElements()
		{
			if (!(CharadesPen == null))
			{
				int index = 0;
				switch (CharadesPen.CurrentShapeType)
				{
				case ShapeType.Tube:
					index = 0;
					break;
				case ShapeType.Box:
					index = 1;
					break;
				case ShapeType.Sphere:
					index = 2;
					break;
				}
				if (!shapeRadioGroup.Buttons[index].IsCurrent)
				{
					shapeRadioGroup.Buttons[index].ForcePressed();
				}
				if (!colorPickerScreen.Buttons[(int)CharadesPen.SelectedColor].IsCurrent)
				{
					colorPickerScreen.Buttons[(int)CharadesPen.SelectedColor].ForcePressed();
				}
			}
		}

		public void SelectColor(int colorIndex)
		{
			if (CharadesPen != null)
			{
				CharadesPen.SelectShapeColor((ShapeColor)colorIndex);
			}
		}

		public virtual void SelectShape(int shapeIndex)
		{
			if (CharadesPen != null)
			{
				CharadesPen.SelectShapeType((ShapeType)shapeIndex);
			}
		}

		public void AssignColorsToColorPicker(Color[] colors)
		{
			if (colorPickerScreen != null)
			{
				colorPickerScreen.AvailableColors = colors;
			}
		}
	}
}
