	public class CreationObjectSettingEnumUIControl : BaseCreationObjectSettingEnumUIControl<CreationObjectSettingEnumUIControl>
	{
	}
	public struct EnumChoiceData
	{
		public int enumValue;

		public string tooltip;
	}
	public abstract class BaseCreationObjectSettingEnumUIControl<T> : CreationObjectSettingPropertyUIControl<int, T> where T : CreationObjectSettingPropertyUIControl<int, T>
	{
		[SerializeField]
		private RadioButton3D enumRadioButtonPrefab;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private RadioGroup3D radioButtonGroup;

		private Dictionary<string, EnumChoiceData> choicesDictionary;

		public int Selected
		{
			get
			{
				foreach (RadioButton3D button in radioButtonGroup.Buttons)
				{
					if (button.IsCurrent)
					{
						return GetRadioButtonEnumValue(button);
					}
				}
				return 0;
			}
		}

		internal void SetEnumOptions(Dictionary<string, EnumChoiceData> choicesDictionary, int selected)
		{
			this.choicesDictionary = choicesDictionary;
			if (choicesDictionary == null)
			{
				return;
			}
			foreach (KeyValuePair<string, EnumChoiceData> item in choicesDictionary)
			{
				RadioButton3D radioButton3D = UnityEngine.Object.Instantiate(enumRadioButtonPrefab, radioButtonGroup.transform);
				radioButton3D.Label.text = item.Key;
				radioButton3D.IsCurrent = selected == item.Value.enumValue;
				radioButtonGroup.AddButton(radioButton3D);
				radioButton3D.OnClick.AddListener(OnRadioButtonClicked);
				Tooltip component = radioButton3D.GetComponent<Tooltip>();
				if (!string.IsNullOrEmpty(item.Value.tooltip))
				{
					if (component != null)
					{
						component.Message = item.Value.tooltip;
					}
				}
				else
				{
					component?.SetEnabled(enabled: false);
				}
			}
		}

		private void OnEnable()
		{
			RadioButton3D radioButton3D = null;
			foreach (RadioButton3D button in radioButtonGroup.Buttons)
			{
				if (radioButton3D == null && button.IsCurrent)
				{
					radioButton3D = button;
					radioButton3D.IsCurrent = true;
				}
				else
				{
					button.IsCurrent = false;
				}
			}
		}

		protected virtual void OnRadioButtonClicked(RadioButton3D button)
		{
			if (choicesDictionary != null)
			{
				int radioButtonEnumValue = GetRadioButtonEnumValue(button);
				SetPropertyValue(radioButtonEnumValue);
			}
		}

		protected int GetRadioButtonEnumValue(RadioButton3D button)
		{
			EnumChoiceData value = new EnumChoiceData
			{
				enumValue = -1
			};
			if (choicesDictionary != null)
			{
				choicesDictionary.TryGetValue(button.Label.text, out value);
			}
			return value.enumValue;
		}
	}
