		public void SetSegmentLabels(string[] segmentLabels, int[] segmentValues, int defaultValue)
		{
			if (segmentLabels == null || segmentValues == null)
			{
				UnityEngine.Debug.LogError("Cannot set null segment labels or segment values.");
				return;
			}
			if (segmentLabels.Length != segmentValues.Length)
			{
				UnityEngine.Debug.LogError("Segment labels and segment values arrays must be of the same length.");
				return;
			}
			Slider3D.SliderValue[] array = new Slider3D.SliderValue[segmentLabels.Length];
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Label = segmentLabels[i];
				array[i].Value = segmentValues[i];
			}
			slider.SetUpSlider(PropertyDescription.text, array, defaultValue);
			if (PropertyValueText != null)
			{
				PropertyValueText.enabled = false;
			}
		}

		[SkipRename]
		public void OnSliderChanged(float newValue)
		{
			UIHelper.SafeSetText(PropertyValueText, ((int)slider.FloatOrRoundedValue/*cast due to .constrained prefix*/).ToString());
		}

