	public abstract class CreationObjectSettingPropertyUIControl<T, UIControlType> : BaseCreationObjectSettingPropertyUIControl where UIControlType : CreationObjectSettingPropertyUIControl<T, UIControlType>
	{
		public Action<T> PropertySetter;

		public Func<bool> InteractibleGetter;

		public Func<T> PropertyGetter;

		public Action<UIControlType> UpdateControlFunction;

		public event Action OnDestroyEvent
		{
			add
			{
				Action action = this.OnDestroyEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.OnDestroyEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.OnDestroyEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.OnDestroyEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected void SetPropertyValue(T newValue)
		{
			if (PropertySetter != null)
			{
				PropertySetter(newValue);
			}
			UpdateControl();
		}

		public sealed override void UpdateControl()
		{
			if (UpdateControlFunction != null)
			{
				UpdateControlFunction((UIControlType)this);
			}
			_UpdateControl();
		}

		protected virtual void _UpdateControl()
		{
		}

		protected virtual void OnDestroy()
		{
			if (this.OnDestroyEvent != null)
			{
				this.OnDestroyEvent();
			}
		}
	}
	public class CreationObjectSettingStringUIControl : CreationObjectSettingPropertyUIControl<string, CreationObjectSettingStringUIControl>
	{
		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private Button3D modifyButton;

		[SerializeField]
		[AutofillOptional(AutofillType.SelfAndChildren, false)]
		private Tooltip buttonTooltip;

		private string dialogInputFieldDescription = string.Empty;

		private string dialogTitle = "Enter Text";

		private bool purifyString;

		private TMP_InputField.ContentType contentType = TMP_InputField.ContentType.Alphanumeric;

		private int characterLimit = -1;

		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		public void SetTooltip(string tooltip)
		{
			buttonTooltip.Message = tooltip;
		}

		public void SetDialogOptions(string dialogTitle, string dialogInputFieldDescription, TMP_InputField.ContentType contentType = TMP_InputField.ContentType.Alphanumeric, bool purifyString = false, int characterLimit = -1)
		{
			this.dialogTitle = dialogTitle;
			this.dialogInputFieldDescription = dialogInputFieldDescription;
			this.contentType = contentType;
			this.purifyString = purifyString;
			this.characterLimit = characterLimit;
		}

		private void Start()
		{
			modifyButton.OnClick.AddListener(OnModifyButtonClick);
		}

		private void OnModifyButtonClick()
		{
			MakerPenPaletteUI paletteMenuToolUI = base.MakerPen.PaletteMenuToolUI;
			paletteMenuToolUI.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(contentType, dialogTitle, dialogInputFieldDescription, "Ok", purifyString, characterLimit, null, shouldFocusInputField: true)).Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative)
				{
					SetPropertyValue(r.TextInput);
				}
			});
		}

		protected override void _UpdateControl()
		{
			base._UpdateControl();
			UIHelper.SafeSetText(PropertyValueText, PropertyGetter());
