	public class CreationObjectSettingToolCleanupUIControl : CreationObjectSettingPropertyUIControl<ToolCleanup.CleanupOverrides, CreationObjectSettingToolCleanupUIControl>
	{
		[SerializeField]
		private ToggleButton3D activeToggleButton;

		[SerializeField]
		private Slider3D delaySlider;

		[SerializeField]
		private TextMeshProUGUI delayValueText;

		private ToolCleanup.CleanupOverrides overrides;

		protected override void _UpdateControl()
		{
			if (PropertyGetter != null)
			{
				overrides = PropertyGetter();
				delaySlider.minValue = 1f;
				delaySlider.maxValue = 30f;
				RefreshUI();
			}
		}

		private void RefreshUI()
		{
			activeToggleButton.IsOn = overrides.IsActive;
			delaySlider.value = overrides.Delay;
			SetDelayValueText((int)overrides.Delay);
		}

		private void SetDelayValueText(int delay)
		{
			delayValueText.text = $"{delay}s";
		}

		private void RaisePropertyChangedEvent()
		{
			SetPropertyValue(overrides);
			RefreshUI();
		}

		[SkipRename]
		public void OnActiveToggleValueChanged(bool newValue)
		{
			if (newValue != overrides.IsActive)
			{
				overrides.IsActive = newValue;
				RaisePropertyChangedEvent();
			}
		}

		[SkipRename]
		public void OnDelaySliderChanged(float newValue)
		{
			SetDelayValueText((int)delaySlider.FloatOrRoundedValue);
		}

		[SkipRename]
		public void OnDelaySliderReleased(float newValue)
		{
			int num = (int)delaySlider.FloatOrRoundedValue;
			if (overrides.Delay != (float)num)
			{
				overrides.Delay = num;
				RaisePropertyChangedEvent();
			}
		}
	}
