namespace RecRoom
{
	public class SelectorNodeConfigEditableUIControl : CreationObjectSettingPropertyUIControl<SelectorNode.SelectorConfig, SelectorNodeConfigEditableUIControl>
	{
		private SelectorNode.SelectorConfig cachedConfig;

		private int index = -1;

		[SerializeField]
		private Color[] colors = new Color[7];

		[SerializeField]
		private UnityEngine.UI.Image backgroundImage;

		[SerializeField]
		private TextMeshProUGUI compareModeButtonText;

		[SerializeField]
		private TextMeshProUGUI compareValueText;

		private SignalComparisonHelper.ComparerModes[] comparerModes = (SignalComparisonHelper.ComparerModes[])System.Enum.GetValues(typeof(SignalComparisonHelper.ComparerModes));

		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		internal void SetConfig(int index, SelectorNode.SelectorConfig config)
		{
			this.index = index;
			cachedConfig = config;
			UpdateControl();
		}

		public void OnNodeModified()
		{
			cachedConfig = PropertyGetter();
			UpdateControl();
		}

		protected override void _UpdateControl()
		{
			base._UpdateControl();
			if (index >= 0)
			{
				UIHelper.SafeSetColor(backgroundImage, colors[index]);
			}
			UIHelper.SafeSetText(compareModeButtonText, SignalComparisonHelper.GetModeSymbol(cachedConfig.CompareMode));
			UIHelper.SafeSetText(compareValueText, cachedConfig.CompareValue.ToString());
		}

		public void Button_OnModeButtonPressed()
		{
			int num = Array.IndexOf(comparerModes, cachedConfig.CompareMode);
			int num2 = (num + 1) % comparerModes.Length;
			cachedConfig.CompareMode = comparerModes[num2];
			SetPropertyValue(cachedConfig);
		}

		public void Button_Increment(int increment)
		{
			int compareValue = cachedConfig.CompareValue;
			compareValue += increment;
			cachedConfig.CompareValue = compareValue;
			SetPropertyValue(cachedConfig);
		}

		public void Button_Input()
		{
			MakerPenPaletteUI paletteMenuToolUI = base.MakerPen.PaletteMenuToolUI;
			paletteMenuToolUI.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.IntegerNumber, "Enter a number", "Enter a number to compare against", "Ok", purifyText: false, -1, null, shouldFocusInputField: true)).Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative && int.TryParse(r.TextInput, out var result))
				{
					cachedConfig.CompareValue = result;
					SetPropertyValue(cachedConfig);
				}
			});
		}
	}
}
