	public class InventionButton : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		public RadioButton3D _selectInventnionButton;

		[SerializeField]
		private TextMeshProUGUI inventionName;

		[SerializeField]
		private Button3D infoButton;

		[SerializeField]
		private RawImage inventionImage;

		public Invention CurrentInvention { get; private set; }

		public RadioButton3D SelectInventionButton => _selectInventnionButton;

		public RadioButton3D.OnRadioButton3DClick SelectButtonAction => _selectInventnionButton.OnClick;

		public Button3D.OnButton3DClick InfoButtonAction => infoButton.OnClick;

		public void SetInvention(Invention invention)
		{
			if (CurrentInvention == invention)
			{
				return;
			}
			CurrentInvention = invention;
			UIHelper.SafeSetText(inventionName, CurrentInvention.Name);
			inventionImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
			if (CurrentInvention == null)
			{
				return;
			}
			Images.GetInventionImage(CurrentInvention).Then(delegate(Texture2D texture)
			{
				if (this != null && texture != null && CurrentInvention != null && CurrentInvention.ImageName == texture.name)
				{
					inventionImage.texture = texture;
				}
			});
		}

		public void OnEnable()
		{
			if (CurrentInvention != null)
			{
				OnInventionUpdated(CurrentInvention.InventionId);
			}
			Inventions.OnInventionUpdated += OnInventionUpdated;
		}

		public void OnDisable()
		{
			Inventions.OnInventionUpdated -= OnInventionUpdated;
		}

		private void OnInventionUpdated(long invention)
		{
			if (CurrentInvention != null && CurrentInvention.InventionId == invention)
			{
				Invention inventionCached = Inventions.GetInventionCached(invention);
				if (inventionCached != null)
				{
					SetInvention(inventionCached);
				}
			}
		}
	}
	public class InventionPagedGrid : RecyclerPagedGrid<Invention, InventionButton>
	{
		[Serializable]
		public class InventionSelectedEvent : UnityEvent<Invention>
		{
		}

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RadioGroup3D radioGroup;

		public InventionSelectedEvent OnInventionSelectedEvent;

		public InventionSelectedEvent OnInventionInfoEvent;

		private Invention selectedInvention;

		private RadioButton3D selectedRadioButton;

		private bool selectedOnCurrentPage;

		private void Start()
		{
			if (OnInventionSelectedEvent != null)
			{
				foreach (InventionButton childUIElement in childUIElements)
				{
					InventionButton innerChild = childUIElement;
					innerChild.SelectButtonAction.AddListener(delegate(RadioButton3D isOn)
					{
						if ((bool)isOn)
						{
							selectedInvention = innerChild.CurrentInvention;
							selectedRadioButton = innerChild.SelectInventionButton;
						}
						OnInventionSelectedEvent.Invoke(innerChild.CurrentInvention);
					});
					innerChild.InfoButtonAction.AddListener(delegate
					{
						OnInventionInfoEvent.Invoke(innerChild.CurrentInvention);
					});
				}
			}
			base.PageChangeEvent += UpdateSelectedButton;
		}

		private void UpdateSelectedButton()
		{
			radioGroup.SetSelectionStates((RadioButton3D b) => selectedOnCurrentPage && b == selectedRadioButton);
			selectedOnCurrentPage = false;
		}

		protected override void SetupNewChild(InventionButton button)
		{
			base.SetupNewChild(button);
			radioGroup.AddButton(button.SelectInventionButton);
		}

		private void ResetSelectedInvention()
		{
			selectedInvention = null;
			selectedRadioButton = null;
			selectedOnCurrentPage = false;
			radioGroup.SetSelectionStates((RadioButton3D b) => false);
		}

		public void SetInventions(IEnumerable<Invention> inventions, Invention selected)
		{
			if (inventions.Count() == 0)
			{
				SetAllActiveChildren(Enumerable.Empty<Invention>());
				UIHelper.SafeSetText(emptyDisplayText, "Create an Invention by selecting multiple objects, then hitting the Create Inventions button on your Maker Pen menu.");
				return;
			}
			ResetSelectedInvention();
			selectedInvention = selected;
			SetAllActiveChildren(inventions.OrderByDescending((Invention invention) => invention.ModifiedAt));
			UpdateSelectedButton();
		}

		protected override void SetChild(Invention invention, InventionButton button, int activeIndex)
		{
			if (invention == selectedInvention)
			{
				selectedOnCurrentPage = true;
				selectedRadioButton = button.SelectInventionButton;
			}
			button.SetInvention(invention);
		}
	}
