		[SerializeField]
		private ToggleButton3D snappingAlignToObjectsButton;

		public Action<MakerPen.ToolMode> ToolSelectionButtonPressed;

		public Action UndoButtonPressed;

		public Action RedoButtonPressed;

		public Action ExitEditButtonPressed;

		public Action CreateInventionButtonPressed;

		public Action PaletteMenuRequestButtonPressed;

		public Button3D OpenPaletteButton => openPaletteButton;

		public Button3D DoneEditingButton => doneEditingButton;

		private void Start()
		{
			MakerPen.OnPaletteMenuOpenCloseEvent += OnPaletteMenuOpenCloseChanged;
			MakerPen makerPen = MakerPen;
			makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Combine(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			OnMakerPenModeChanged(MakerPen.CurrentToolMode, MakerPen.CurrentTargetMode);
			MakerPen.CreationContext.SelectionChangedEvent += CreationContext_SelectionChangedEvent;
			MakerPen.CreationContext.ShapeCreationContext.SelectionChangedEvent += ShapeCreationContext_SelectionChangedEvent;
			if (MakerPen.UndoStack != null)
			{
				MakerPen.UndoStack.EntriesChanged.Add(OnEditCommandStackChanged);
				OnEditCommandStackChanged();
			}
			if (openPaletteButton != null)
			{
				openPaletteButton.Interactable = !SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode;
			}
			Toggle_SnapObjects(SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingActive);
			if (snappingButton != null)
			{
				snappingButton.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingActive;
			}
			Toggle_AlignToObjects(SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingAlignToObjects);
			if (snappingAlignToObjectsButton != null)
			{
				snappingAlignToObjectsButton.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingAlignToObjects;
			}
			UpdateManipulateButton();
			UpdateFreezeButton();
		}

		private void UpdateManipulateButton()
		{
			bool interactable = MakerPen.CurrentTargetMode == MakerPen.TargetMode.Shape;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
			{
				interactable = false;
			}
			manipulateButton.Interactable = interactable;
		}

		private void UpdateFreezeButton()
		{
			if (freezeButton != null)
			{
				freezeButton.Interactable = MakerPen.CurrentTargetMode == MakerPen.TargetMode.Object;
			}
		}

		private void CreationContext_SelectionChangedEvent()
		{
		}

		private void ShapeCreationContext_SelectionChangedEvent()
		{
			UpdateManipulateButton();
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (MakerPen != null)
			{
				MakerPen.OnPaletteMenuOpenCloseEvent -= OnPaletteMenuOpenCloseChanged;
				MakerPen makerPen = MakerPen;
				makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Remove(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
				MakerPen.CreationContext.SelectionChangedEvent -= CreationContext_SelectionChangedEvent;
				MakerPen.CreationContext.ShapeCreationContext.SelectionChangedEvent -= ShapeCreationContext_SelectionChangedEvent;
				if (MakerPen.UndoStack != null)
				{
					MakerPen.UndoStack.EntriesChanged.Remove(OnEditCommandStackChanged);
				}
			}
		}

		private void OnPaletteMenuOpenCloseChanged(bool isOpen)
		{
			UIHelper.SafeSetText(openPaletteButton.Label, (!isOpen) ? "Open Palette" : "Close Palette");
		}

		private void OnMakerPenModeChanged(MakerPen.ToolMode toolMode, MakerPen.TargetMode targetMode)
		{
			if (MakerPen.IsCreationToolMode(toolMode))
			{
				modeButtonsGroup.SetSelectionStates((RadioButton3D b) => b == createButton);
			}
			else
			{
				modeButtonsGroup.SetSelectionStates(delegate(RadioButton3D b)
				{
					MakerPenToolRadioButton makerPenToolRadioButton = b as MakerPenToolRadioButton;
					return makerPenToolRadioButton != null && makerPenToolRadioButton.PenTool == toolMode;
				});
			}
			editButton.Interactable = targetMode == MakerPen.TargetMode.Object;
			doneEditingButton.Interactable = targetMode == MakerPen.TargetMode.Shape;
			UpdateManipulateButton();
			UpdateFreezeButton();
		}

		private void OnEditCommandStackChanged()
		{
			bool canUndo = MakerPen.UndoStack.CanUndo;
			string text = ((!canUndo) ? "Undo" : $"Undo {MakerPen.UndoStack.UndoLabel}");
			undoButton.Interactable = canUndo;
			undoButton.Label.text = text;
			bool canRedo = MakerPen.UndoStack.CanRedo;
			string text2 = ((!canRedo) ? "Redo" : $"Redo {MakerPen.UndoStack.RedoLabel}");
			redoButton.Interactable = canRedo;
			redoButton.Label.text = text2;
		}

