					_targetConfigurable = value;
					InitializeEditableProperties();
					if (_targetConfigurable != null)
					{
						_targetConfigurable.ObjectSettingsFunctionsChanged += OnTargetObjectSettingsFunctionsChanged;
					}
				}
			}
		}

		public override void StackedUIOpened()
		{
			base.StackedUIOpened();
			foreach (BaseCreationObjectSettingPropertyUIControl propertyControl in propertyControls)
			{
				propertyControl.UpdateControl();
			}
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			foreach (BaseCreationObjectSettingPropertyUIControl propertyControl in propertyControls)
			{
				propertyControl.UpdateControl();
			}
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
		}

		private void OnTargetObjectSettingsFunctionsChanged()
		{
			InitializeEditableProperties();
		}

		private void InitializeEditableProperties()
		{
			foreach (BaseCreationObjectSettingPropertyUIControl propertyControl in propertyControls)
			{
				UnityEngine.Object.Destroy(propertyControl.gameObject);
			}
			propertyControls.Clear();
			if (TargetConfigurable != null)
			{
				editableObjectNameText.text = TargetConfigurable.FriendlyName;
				foreach (SettingsEditEvent objectSettingsFunction in TargetConfigurable.ObjectSettingsFunctions)
				{
					BaseCreationObjectSettingPropertyUIControl baseCreationObjectSettingPropertyUIControl = objectSettingsFunction.CreateEditableControl(this, controlsRootTransform);
					baseCreationObjectSettingPropertyUIControl.MakerPen = MakerPen;
					propertyControls.Add(baseCreationObjectSettingPropertyUIControl);
				}
				this.InvokeNextEndOfFrame(delegate
				{
					if (pagedGrid != null)
					{
						pagedGrid.RefreshChildren(includeDisabled: true);
					}
				});
			}
			else if (base.IsCurrentFlow)
			{
				base.UIBase.PopFlow();
			}
		}
	}
	public class MakerPenPaletteInventionCreationScreen : MakerPenPaletteUIFlowBase
	{
		public const int MAX_CREATON_SCREEN_STACK_DEPTH = 2;

		[SerializeField]
		private GameObject instructionsSubscreen;

		[SerializeField]
		private GameObject resultSubscreen;

		[SerializeField]
		private Button3D nextButton;

		[SerializeField]
		private TextMeshProUGUI mainText;

		[SerializeField]
		private TextMeshProUGUI objectCountText;

		[SerializeField]
		private TextMeshProUGUI resultText;

		[SerializeField]
		private float minUpdateInventionInterval = 5f;

		[Header("Dialogs")]
		[SerializeField]
		private EnterInventionNameDialog enterInventionNameDialog;

		[SerializeField]
		private EnterInventionDescriptionDialog enterInventionDescriptionDialog;

		[SerializeField]
		private TakeInventionPictureDialog takeInventionPictureDialog;

		private Invention targetInvention;

		private AltTextureSet createInventionTextureSet;

		private string createInventionName;

		private string createInventionDescription;

		private float nextUpdateInventionPressTime = float.MinValue;

		private bool skipObjectSelection;

		public static bool IsInventionCreationScreenOrSubScreen(StackedUIFlowBase flow)
		{
			return flow is MakerPenPaletteInventionCreationScreen || IsInventionCreationTempDialog(flow);
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			if (MakerPen == null)
			{
				return;
			}
			instructionsSubscreen.SetActive(value: true);
			resultSubscreen.SetActive(value: false);
			if (!IsInventionCreationTempDialog(oldFlow))
			{
				if (skipObjectSelection)
				{
					ShowEnterNameDialog();
					return;
				}
				MakerPen.StartInventionObjectsSelection();
				MakerPen.CreationContext.OnSelectionChanged += new Action<CreationObject, bool>(OnSelectionChanged);
				OnSelectionChanged(null, selected: false);
				MakerPen makerPen = MakerPen;
				makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Combine(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			}
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			if (!stillOnStack && MakerPen != null)
			{
				if (MakerPen.CreationContext != null)
				{
					MakerPen.CreationContext.OnSelectionChanged -= new Action<CreationObject, bool>(OnSelectionChanged);
				}
				MakerPen makerPen = MakerPen;
				makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Remove(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
				if (MakerPen.IsSelectingInventionObjects)
				{
					MakerPen.CancelInventionObjectsSelection();
				}
			}
		}

		[SkipRename]
		public void Button_Done()
		{
			string text = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.CheckObjectsCanBeSavedAsInvention(MakerPen.CreationContext.CurrentSelection, -1L);
			if (!string.IsNullOrEmpty(text))
			{
				ShowResults(text);
				return;
			}
			MakerPen.CompleteInventionObjectsSelection();
			ShowEnterNameDialog();
		}

		[SkipRename]
		public void Button_Cancel()
		{
			MakerPen.CancelInventionObjectsSelection();
		}

		public void SkipObjectSelection(bool skip)
		{
			skipObjectSelection = skip;
		}

		private void ShowEnterNameDialog()
		{
			MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(enterInventionNameDialog, targetInvention, out var dialogInstance).Then(delegate(EnterTextDialogResponse nameResponse)
			{
				if (nameResponse.responseType == ConfirmDialogResponses.Affirmative)
				{
					createInventionName = nameResponse.text;
					ShowEnterDescriptionDialog();
				}
				else
				{
					MakerPen.StartInventionObjectsSelection();
				}
			});
			if (dialogInstance != null)
			{
				EnterInventionNameDialog component = dialogInstance.GetComponent<EnterInventionNameDialog>();
				if (component != null)
				{
					component.SetButtonText("Next", "Back");
				}
			}
		}

		private void ShowEnterDescriptionDialog()
		{
			MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(enterInventionDescriptionDialog, targetInvention, out var dialogInstance).Then(delegate(EnterTextDialogResponse descriptionResponse)
			{
				if (descriptionResponse.responseType == ConfirmDialogResponses.Affirmative)
				{
					createInventionDescription = descriptionResponse.text;
					ShowTakePictureDialog();
				}
				else
				{
					ShowEnterNameDialog();
				}
			});
			if (dialogInstance != null)
			{
				EnterInventionDescriptionDialog component = dialogInstance.GetComponent<EnterInventionDescriptionDialog>();
				if (component != null)
				{
					component.SetButtonText("Next", "Back");
				}
			}
		}

		private void ShowTakePictureDialog()
		{
			MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(takeInventionPictureDialog, targetInvention).Then(delegate(TakePictureDialogResponse takePictureResponse)
			{
				if (takePictureResponse.responseType == ConfirmDialogResponses.Affirmative)
				{
					if (takePictureResponse.photoSet == null)
					{
						UnityEngine.Debug.LogError("Received a null photo set with an affirmative dialog response from Take Picture dialog, this shouldn't happen.");
					}
					else if (targetInvention == null)
					{
						createInventionTextureSet = new AltTextureSet();
						createInventionTextureSet.DeepCopyTextures(takePictureResponse.photoSet);
						SaveNewInvention();
					}
					else
					{
						SaveNewInventionVersion();
					}
				}
				else
				{
					ShowEnterDescriptionDialog();
				}
			});
		}

		private void SaveNewInvention()
		{
			if (!(UnityEngine.Time.realtimeSinceStartup < nextUpdateInventionPressTime))
			{
				nextUpdateInventionPressTime = UnityEngine.Time.realtimeSinceStartup + minUpdateInventionInterval;
				ShowResults("Creating...");
				MakerPen.SaveCurrentSelectionAsNewInvention(createInventionName, createInventionDescription, createInventionTextureSet).Then(HandleSaveNewInventionResponse).Error(delegate(string error)
				{
					ShowResults(string.Format("Unable to save selection as invention: {0}", error ?? "Unknown error"));
				});
			}
		}

		private void SaveNewInventionVersion()
		{
			if (!(UnityEngine.Time.realtimeSinceStartup < nextUpdateInventionPressTime))
			{
				nextUpdateInventionPressTime = UnityEngine.Time.realtimeSinceStartup + minUpdateInventionInterval;
				ShowResults($"Saving new version of {targetInvention.Name}...");
				MakerPen.SaveCurrentSelectionAsNewVersionOfInvention(targetInvention.InventionId).Then(HandleSaveNewInventionVersionResponse).Error(delegate(string error)
				{
					ShowResults(string.Format("Unable to save new version of invention: {0}", error ?? "Unknown error"));
				});
			}
		}

		private void HandleSaveNewInventionResponse(CreationManager.InventionUpdateResult response)
		{
			if (response.result != CreationResult.Success)
			{
				UnityEngine.Debug.LogError($"Error saving invention: {response.result}");
			}
			switch (response.result)
			{
			case CreationResult.Success:
				Inventions.GetInvention(response.inventionId).Then(delegate(Invention invention)
				{
					ShowDetailsScreen(invention);
					if (!SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
					{
						MakerPen.PaletteMainScreen.Button_InventionSelected(invention);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Press the trigger to spawn your invention", 3f);
					}
				});
				ShowResults("Successfully saved!");
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Successfully saved!", 3f);
				break;
			default:
				if (response.serverResult != InventionResult.Success)
				{
					string responseCodeFriendlyMessage = Inventions.GetResponseCodeFriendlyMessage(response.serverResult);
					ShowResults(responseCodeFriendlyMessage);
				}
				else
				{
					ShowResults("Unable to save selection as invention. If this persists, please contact the developers at support@againstgrav.com.");
				}
				break;
			}
		}

		private void HandleSaveNewInventionVersionResponse(CreationManager.InventionUpdateResult response)
		{
			if (response.result != CreationResult.Success)
			{
				UnityEngine.Debug.LogError($"Error updating invention: {response.result}");
			}
			switch (response.result)
			{
			case CreationResult.Success:
				Inventions.GetInvention(response.inventionId).Then(delegate(Invention invention)
				{
					ShowDetailsScreen(invention);
					if (!SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
					{
						MakerPen.PaletteMainScreen.Button_InventionSelected(invention);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Press the trigger to spawn your invention", 3f);
					}
				});
				ShowResults("Successfully updated!");
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Successfully updated!", 3f);
				break;
			default:
				if (response.serverResult != InventionResult.Success)
				{
					string responseCodeFriendlyMessage = Inventions.GetResponseCodeFriendlyMessage(response.serverResult);
					ShowResults(responseCodeFriendlyMessage);
				}
				else
				{
					ShowResults("Unable to update invention. If this persists, please contact the developers at support@againstgrav.com.");
				}
				break;
			}
		}

		private void ShowDetailsScreen(Invention invention)
		{
			MakerPen.MoveablePaletteMenu.CloseInventionCreationFlow();
			MakerPen.MoveablePaletteMenu.ShowInventionDetailsFlow(invention);
		}

		private void ShowResults(string text)
		{
			instructionsSubscreen.SetActive(value: false);
			resultSubscreen.SetActive(value: true);
			resultText.text = text;
		}

		private void OnSelectionChanged(CreationObject obj, bool selected)
		{
			int selectionCount = MakerPen.CreationContext.SelectionCount;
			UpdateObjectCountText(selectionCount);
			nextButton.Interactable = selectionCount > 0;
		}

		private void OnMakerPenModeChanged(MakerPen.ToolMode toolMode, MakerPen.TargetMode targetMode)
		{
			if (toolMode != MakerPen.ToolMode.CreateInvention)
			{
				MakerPen.MoveablePaletteMenu.CloseInventionCreationFlow();
			}
		}

		public void SetTargetInvention(Invention invention)
		{
			targetInvention = invention;
			createInventionTextureSet = null;
		}

		private void UpdateObjectCountText(int objectCount)
		{
			if (objectCountText != null)
			{
				objectCountText.text = $"Objects selected: {objectCount}";
			}
		}

		private static bool IsInventionCreationTempDialog(StackedUIFlowBase flow)
		{
			return flow is EnterInventionNameDialog || flow is EnterInventionDescriptionDialog || flow is TakeInventionPictureDialog;
		}
	}
}
public class MakerPenPaletteInventionDetailsScreen : MakerPenPaletteUIFlowBase
{
	[Header("Dialogs")]
	[SerializeField]
	private TakeInventionPictureDialog takeInventionPictureDialog;

	[SerializeField]
	private EnterInventionNameDialog enterInventionNameDialog;

	[SerializeField]
	private EnterInventionDescriptionDialog enterInventionDescriptionDialog;

	[Header("Name")]
	[SerializeField]
	private TextMeshProUGUI inventionName;

	[SerializeField]
	private Button3D editNameButton;

	[Header("Description")]
	[SerializeField]
	private TextMeshProUGUI inventionDescription;

	[SerializeField]
	private Button3D editDescriptionButton;

	[Header("Tags")]
	[SerializeField]
	private TextMeshProUGUI inventionTags;

	[SerializeField]
	private Button3D editTagsButton;

	[SerializeField]
	private Tooltip tagsTooltip;

	[Header("Image")]
	[SerializeField]
	private RawImage inventionImage;

	[SerializeField]
	private Button3D editImageButton;

	[Header("Creator Info")]
	[SerializeField]
	private PlayerInfoUIControl creatorInfo;

	[SerializeField]
	private Button3D creatorInfoButton;

	[Header("Saving")]
	[SerializeField]
	private Button3D updateInventionObjectsButton;

	[SerializeField]
	private float minUpdateInventionInterval = 5f;

	[Header("General")]
	[SerializeField]
	private TextMeshProUGUI inkCostText;

	[SerializeField]
	private TextMeshProUGUI infoText;

	[SerializeField]
	private float inkCostLowThreshold = 0.02f;

	[SerializeField]
	private float inkCostMediumThreshold = 0.05f;

	[SerializeField]
	private Button3D deleteButton;

	private Invention targetInvention;

	private PlayerDetailsWatchUIFlow playerDetailsFlow;

	private WatchUI watchMenu;

	private Profile creatorProfile;

	private Coroutine queuedUpdateDetailsRoutine;

	private AltTextureSet createInventionTextureSet;

	private string createInventionName;

	private string createInventionDescription;

	private float nextUpdateInventionPressTime = float.MinValue;

	private void Awake()
	{
		WatchUI.LocalPlayerAndWatchMenuSpawned += OnLocalPlayerAndWatchMenuSpawned;
		OnLocalPlayerAndWatchMenuSpawned();
	}

	private void OnEnable()
	{
		Inventions.OnInventionUpdated += OnInventionUpdated;
		if (targetInvention != null)
		{
			OnInventionUpdated(targetInvention.InventionId);
		}
		QueueUpdateDetails();
	}

	private void OnDisable()
	{
		Inventions.OnInventionUpdated -= OnInventionUpdated;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		WatchUI.LocalPlayerAndWatchMenuSpawned -= OnLocalPlayerAndWatchMenuSpawned;
		Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
	}

	public void SetTargetInvention(Invention invention)
	{
		targetInvention = invention;
		createInventionTextureSet = null;
		UpdateDetails();
		UpdateUIState(string.Empty, enableButtons: true);
	}

	private void UpdateUIState(string statusText, bool enableButtons)
	{
		infoText.text = statusText;
		if (targetInvention == null)
		{
			UnityEngine.Debug.LogWarning("Target invention should not be null on Invention Details screen");
			return;
		}
		creatorInfoButton.Interactable = enableButtons && targetInvention.CreatorPlayerId != (long)Profiles.LocalProfile.Id;
		updateInventionObjectsButton.Interactable = enableButtons;
		editNameButton.Interactable = enableButtons;
		editDescriptionButton.Interactable = enableButtons;
		editTagsButton.Interactable = enableButtons;
		editImageButton.Interactable = enableButtons;
	}

	private void QueueUpdateDetails()
	{
		if (targetInvention != null && base.isActiveAndEnabled)
		{
			this.SafeStopCoroutine(queuedUpdateDetailsRoutine);
			queuedUpdateDetailsRoutine = this.EndOfFrameRoutine(delegate
			{
				UpdateDetails();
				queuedUpdateDetailsRoutine = null;
			});
		}
	}

	private void ShowDefaultDetails()
	{
		inventionName.text = "Name";
		inventionDescription.text = "Description";
		inventionTags.text = "#tags";
		tagsTooltip.Message = string.Empty;
		inventionImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
		creatorProfile = Profiles.LocalProfile;
		creatorInfo.SetProfile(Profiles.LocalProfile);
		UpdatePlayerSpecificUI(Profiles.LocalProfile.Id);
		UpdateInkCostText();
		UpdateUIState(string.Empty, enableButtons: true);
	}

	private void UpdateDetails()
	{
		if (targetInvention == null)
		{
			ShowDefaultDetails();
			return;
		}
		inventionName.text = targetInvention.Name;
		if (!string.IsNullOrEmpty(targetInvention.Description))
		{
			inventionDescription.text = targetInvention.Description;
		}
		else
		{
			inventionDescription.text = "No description yet";
		}
		inventionImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
		Images.GetInventionImage(targetInvention).Then(delegate(Texture2D texture)
		{
			if (this != null && texture != null && targetInvention != null && targetInvention.ImageName == texture.name)
			{
				inventionImage.texture = texture;
			}
		});
		creatorProfile = Profiles.Get(targetInvention.CreatorPlayerId);
		Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
		if (creatorProfile == null)
		{
			creatorInfoButton.Interactable = false;
			creatorInfo.SetProfile(creatorProfile);
			UpdatePlayerSpecificUI(null);
		}
		else
		{
			Profiles_OnProfileUpdated(targetInvention.CreatorPlayerId);
		}
		UpdateInkCostText();
	}

	private void DeleteInvention()
	{
		UpdateUIState("Deleting...", enableButtons: false);
		Inventions.DeleteInvention(targetInvention.InventionId).Then(delegate(InventionResponse result)
		{
			if (result.Status == InventionResult.Success)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Successfully deleted", 3f);
				MakerPen.PaletteMenuToolUI.PopFlow();
			}
			else
			{
				UpdateUIState("Failed to delete Invention :(", enableButtons: true);
			}
		}).Error(delegate(string error)
		{
			UnityEngine.Debug.LogError($"Failed to delete invention: {error}");
			UpdateUIState("Failed to delete Invention :(", enableButtons: true);
		});
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		if (targetInvention != null && targetInvention.CreatorPlayerId == id)
		{
			creatorProfile = Profiles.Get(id);
			creatorInfoButton.Interactable = (long)Profiles.LocalProfile.Id != id;
			creatorInfo.SetProfile(creatorProfile);
			UpdatePlayerSpecificUI(id);
		}
	}

	private void OnInventionUpdated(long inventionId)
	{
		if (targetInvention != null && targetInvention.InventionId == inventionId)
		{
			targetInvention = Inventions.GetInventionCached(inventionId);
			QueueUpdateDetails();
		}
	}

	private void OnLocalPlayerAndWatchMenuSpawned()
	{
		if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerUI.WatchMenu != null)
		{
			WatchUI.LocalPlayerAndWatchMenuSpawned -= OnLocalPlayerAndWatchMenuSpawned;
			watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			playerDetailsFlow = watchMenu.GetFlowByType<PlayerDetailsWatchUIFlow>();
		}
	}

	private void HandleCreateModifyResponse(CreationManager.InventionUpdateResult response)
	{
		if (response.result != CreationResult.Success)
		{
			UnityEngine.Debug.LogError($"Error saving invention: {response.result}");
		}
		switch (response.result)
		{
		case CreationResult.Success:
			Inventions.GetInvention(response.inventionId).Then(delegate(Invention invention)
			{
				SetTargetInvention(invention);
			});
			UpdateUIState("Successfully saved!", enableButtons: true);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Successfully saved!", 3f);
			break;
		default:
			if (response.serverResult != InventionResult.Success)
			{
				string responseCodeFriendlyMessage = Inventions.GetResponseCodeFriendlyMessage(response.serverResult);
				UpdateUIState(responseCodeFriendlyMessage, enableButtons: true);
			}
			else
			{
				UpdateUIState("Unable to save selection as invention. If this persists, please contact the developers at support@againstgrav.com.", enableButtons: true);
			}
			break;
		}
		QueueUpdateDetails();
	}

	[SkipRename]
	public void Button_EditName()
	{
		MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(enterInventionNameDialog, targetInvention).Then(delegate(EnterTextDialogResponse nameResponse)
		{
			if (nameResponse.responseType == ConfirmDialogResponses.Affirmative && !string.IsNullOrEmpty(nameResponse.text))
			{
				createInventionName = nameResponse.text;
				inventionName.text = nameResponse.text;
			}
		});
	}

	[SkipRename]
	public void Button_EditDescription()
	{
		MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(enterInventionDescriptionDialog, targetInvention).Then(delegate(EnterTextDialogResponse descriptionResponse)
		{
			if (descriptionResponse.responseType == ConfirmDialogResponses.Affirmative && descriptionResponse.text != null)
			{
				createInventionDescription = descriptionResponse.text;
				inventionDescription.text = descriptionResponse.text;
			}
		});
	}

	[SkipRename]
	public void Button_EditTags()
	{
	}

	[SkipRename]
	public void Button_UpdateImage()
	{
		MakerPen.PaletteMenuToolUI.ShowTemporaryDialog(takeInventionPictureDialog, targetInvention).Then(delegate(TakePictureDialogResponse takePictureResponse)
		{
			if (takePictureResponse.responseType == ConfirmDialogResponses.Affirmative && targetInvention == null && takePictureResponse.photoSet != null)
			{
				createInventionTextureSet = new AltTextureSet();
				createInventionTextureSet.DeepCopyTextures(takePictureResponse.photoSet);
				inventionImage.texture = createInventionTextureSet.MainTexture;
			}
		});
	}

	[SkipRename]
	public void Button_AddInventionVersion()
	{
		if (targetInvention != null)
		{
			MakerPen.RequestInventionUpdate(targetInvention);
		}
	}

	[SkipRename]
	public void Button_CreatorInfo()
	{
		if (playerDetailsFlow != null)
		{
			playerDetailsFlow.SetProfile(creatorProfile);
			watchMenu.PushFlow(playerDetailsFlow);
			watchMenu.PlayAttract();
		}
	}

	[SkipRename]
	public void Button_DeleteButton()
	{
		MakerPen.PaletteMenuToolUI.ShowConfirmationDialog("Confirm delete Invention?", "This action CANNOT be undone!").Then(delegate(ConfirmDialogResponses response)
		{
			if (response == ConfirmDialogResponses.Affirmative)
			{
				DeleteInvention();
			}
		});
	}

	private void UpdatePlayerSpecificUI(long? profileId)
	{
		PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>();
		foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
		{
			playerSpecificUIBehaviour.SetPlayer(profileId);
		}
	}

	private void UpdateInkCostText()
	{
		if (targetInvention == null)
		{
			return;
		}
		inkCostText.text = string.Empty;
		Inventions.GetInventionVersion(targetInvention.InventionId, targetInvention.CurrentVersionNumber).Then(delegate(InventionVersion inventionVersion)
		{
			if (inventionVersion != null)
			{
				float num = (float)inventionVersion.InstantiationCost / 30000f;
				string arg = ((num < inkCostLowThreshold) ? "Low" : ((!(num < inkCostMediumThreshold)) ? "High" : "Medium"));
				inkCostText.text = $"Ink Cost: {arg}";
			}
		});
	}
}
namespace RecRoom.AGUI.ToolUIs
{
	public class MakerPenPaletteMainScreen : MakerPenPaletteUIFlowBase
	{
		public enum DisplayMode
		{
			None,
			ShapesAndColors,
			Gadgets,
			Props,
			Settings,
			Inventions
		}

		private const int INKUSAGE_MEDIUM_THRESHOLD = 70;

		private const int INKUSAGE_FULL_THRESHOLD = 95;

		[Header("Subscreens")]
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
