		[SerializeField]
		private Subscreen inventionsSubscreen;

		[SerializeField]
		private RadioButton3D gadgetsRadioButton;

		[SerializeField]
		private RadioButton3D propsRadioButton;

		[Header("Header")]
		[SerializeField]
		private Slider inkBar;

		[SerializeField]
		private TextMeshProUGUI inkPercentageText;

		[SerializeField]
		private UnityEngine.UI.Image inkFillImage;

		[SerializeField]
		private Color inkUsageLittleFill;

		[SerializeField]
		private Color inkUsageMediumFill;

		[SerializeField]
		private Color inkUsageFullFill;

		[SerializeField]
		private TextMeshProUGUI selectedItemText;

		[Header("Shapes and Colors")]
