		[Header("Spawnable Tools Subscreen")]
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private SpawnableToolPagedGrid spawnableToolPagedGrid;

		[SerializeField]
		private RadioGroup3D spawnableToolsFilterGroup;

		[SerializeField]
		private Button3D enableGadgetsButton;

		[Header("Inventions Subscreen")]
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private InventionPagedGrid inventionPagedGrid;

		[SerializeField]
		private RadioGroup3D inventionsFilterGroup;

		[SerializeField]
		private string[] inventionFilterNames = new string[0];

		[Header("Settings")]
		[SerializeField]
		private ToggleButton3D desatWorldToggle;

		[SerializeField]
		private ToggleButton3D uniformShapesToggle;

		[SerializeField]
		private ToggleButton3D snapToCenterToggle;

		[SerializeField]
		private ToggleButton3D freezeRotationToggle;

		[SerializeField]
		private ToggleButton3D alignToEdgesToggle;

		[SerializeField]
		private ToggleButton3D showGridToggle;

		[SerializeField]
		private Slider3D gridSnapSlider;

		[SerializeField]
		private Slider3D angleSnapSlider;

		[SerializeField]
		private Slider3D lockCurveRadiusSlider;

		[SerializeField]
		private ToggleButton3D playStopGizmosToggle;

		[SerializeField]
		private ToggleButton3D hideGadgetsToggle;

		[SerializeField]
		private Button3D deleteAllButton;

		private RadioButton3D[] spawnableToolFilterButtons = new RadioButton3D[0];

		private RadioButton3D[] inventionFilterButtons = new RadioButton3D[0];

		private RadioButton3D[] colorButtons = new RadioButton3D[0];

		private RadioButton3D[] shapeButtons = new RadioButton3D[0];

		private bool hasSetUpDefaultButtons;

		private SpawnableToolType currentlySelectedProp = SpawnableToolType.INVALID;

		private bool cacheCanEditGadgets;

		private Invention currentlySelectedInvention;

		public Action<ShapeType> ShapeTypeSelectionButtonPressed;

		public Action<ShapeColor> ShapeColorSelectionButtonPressed;

		public Action<SpawnableToolType> SpawnableToolSelectionButtonPressed;

		public Action<Invention> InventionSelectionButtonPressed;

		private int _gadgetsfilterIndex;

		private int _propsfilterIndex;

		private int _inventionsfilterIndex;

		private DisplayMode _displayMode;

		private int CurrentGadgetsFilterIndex
		{
			get
			{
				return _gadgetsfilterIndex;
			}
			set
			{
				if (value != _gadgetsfilterIndex)
				{
					_gadgetsfilterIndex = value;
					UpdatePagedGridForDisplayMode();
				}
			}
		}

		private int CurrentPropsFilterIndex
		{
			get
			{
				return _propsfilterIndex;
			}
			set
			{
				if (value != _propsfilterIndex)
				{
					_propsfilterIndex = value;
					UpdatePagedGridForDisplayMode();
				}
			}
		}

		private int CurrentInventionFilterIndex
		{
			get
			{
				return _inventionsfilterIndex;
			}
			set
			{
				if (value != _inventionsfilterIndex)
				{
					_inventionsfilterIndex = value;
					UpdatePagedGridForDisplayMode();
				}
			}
		}

		private DisplayMode CurrentDisplayMode
		{
			get
			{
				return _displayMode;
			}
			set
			{
				if (value != _displayMode)
				{
					_displayMode = value;
					switch (value)
					{
					case DisplayMode.Gadgets:
						UpdateSpawnableToolFilterButtons(SpawnableToolCategoryConfig.Group.GAGDETS);
						break;
					case DisplayMode.Props:
						UpdateSpawnableToolFilterButtons(SpawnableToolCategoryConfig.Group.PROPS);
						break;
					}
					UpdatePagedGridForDisplayMode();
				}
			}
		}

		private bool CanEditGadgets => NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanEditCircuits.Value;

		private bool CanChangeCanEditGadget => NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanEditRoomRoles.Value;

		private bool CanDeleteAll => NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanUseDeleteAllButton.Value;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			spawnableToolFilterButtons = spawnableToolsFilterGroup.GetComponentsInChildren<RadioButton3D>(includeInactive: true);
			spawnableToolsFilterGroup.AddButtons(spawnableToolFilterButtons.ToList());
			for (int i = 0; i < spawnableToolFilterButtons.Length; i++)
			{
				int temp = i;
				spawnableToolFilterButtons[temp].OnClick.AddListener(delegate
				{
					Button_FilterSpawnableTools(temp);
				});
				spawnableToolFilterButtons[temp].gameObject.SetActive(value: false);
			}
			inventionFilterButtons = inventionsFilterGroup.GetComponentsInChildren<RadioButton3D>(includeInactive: true);
			inventionsFilterGroup.AddButtons(inventionFilterButtons.ToList());
			for (int num = 0; num < inventionFilterButtons.Length; num++)
			{
				int temp2 = num;
				inventionFilterButtons[temp2].OnClick.AddListener(delegate
				{
					Button_FilterInventions(temp2);
				});
				if (temp2 < inventionFilterNames.Length)
				{
					UIHelper.SafeSetText(inventionFilterButtons[temp2].Label, inventionFilterNames[temp2]);
				}
				else
				{
					inventionFilterButtons[temp2].gameObject.SetActive(value: false);
				}
			}
			colorButtons = colorButtonsRadioGroup.GetComponentsInChildren<RadioButton3D>(includeInactive: true);
			colorButtonsRadioGroup.AddButtons(colorButtons.ToList());
			Color[] shapeColors = ShapeSettings.ConfigAsset.ShapeColors;
			for (int num2 = 0; num2 < colorButtons.Length; num2++)
			{
				int temp3 = num2;
				colorButtons[temp3].OnClick.AddListener(delegate
				{
					Button_SelectColor(temp3);
				});
				if (temp3 < shapeColors.Length)
				{
					colorButtons[num2].BaseColor = shapeColors[temp3];
					colorButtons[num2].ToggleColor = shapeColors[temp3];
				}
			}
			shapeButtons = shapeButtonsRadioGroup.GetComponentsInChildren<RadioButton3D>(includeInactive: true);
			shapeButtonsRadioGroup.AddButtons(shapeButtons.ToList());
			for (int num3 = 0; num3 < shapeButtons.Length; num3++)
			{
				int temp4 = num3;
				shapeButtons[temp4].OnClick.AddListener(delegate
				{
					Button_SelectShape(temp4);
				});
			}
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdatedEvent);
			if (NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance.GizmosPlayingChanged.Add(OnGizmosPlayingChanged);
			}
			cacheCanEditGadgets = CanEditGadgets;
			MakerPen.Snapping.ActiveChangeEvent += OnSnapObjectsChange;
			MakerPen makerPen = MakerPen;
			makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Combine(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			Inventions.OnNewInventionUploaded += OnNewInventionUploaded;
			Inventions.OnInventionDeleted += OnInventionDeleted;
		}

		private void Start()
		{
			CreationManager.ActiveSandboxResourcesChangedEvent += UpdateInkCost;
			UpdateInkCost();
			CurrentDisplayMode = DisplayMode.ShapesAndColors;
		}

		private void OnEnable()
		{
			this.InvokeNextEndOfFrame(delegate
			{
				if (MakerPen != null && !hasSetUpDefaultButtons)
				{
					SelectShapeButton(MakerPen.CurrentShapeType);
					InitializeSettings();
					if (MakerPen.CreationContext != null && MakerPen.CreationContext.ShapeCreationContext != null)
					{
						desatWorldToggle.IsOn = MakerPen.CreationContext.ShapeCreationContext.ShouldRenderWorldFadeMask;
					}
					gridSnapSlider.Interactable = MakerPen.Snapping.IsActive;
					gridSnapSlider.value = ShapeSettings.GetSnapGridSizeIndex(MakerPen.Snapping.GridSize);
					angleSnapSlider.Interactable = MakerPen.Snapping.IsActive;
					angleSnapSlider.value = ShapeSettings.GetAngleSnapIncrementIndex(MakerPen.Snapping.SnapRotateAngleIncrement);
					lockCurveRadiusSlider.value = ShapeSettings.GetCurveThicknessModifierIndex(MakerPen.CurveRadiusModifier);
					hideGadgetsToggle.Interactable = CanEditGadgets;
					hideGadgetsToggle.IsOn = CircuitVisibilityBehaviour.HideForLocalPlayer;
					alignToEdgesToggle.IsOn = MakerPen.AlignToEdges;
					showGridToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnappingShowGrid;
					snapToCenterToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.SnapToCenter;
					freezeRotationToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.MakerPen.FreezeRotationOnMove;
					inventionsFilterGroup.SetSelectionStates((RadioButton3D b) => b == inventionFilterButtons[CurrentInventionFilterIndex]);
					deleteAllButton.Interactable = CanDeleteAll;
					hasSetUpDefaultButtons = true;
				}
				playStopGizmosToggle.IsOn = SandboxGizmoManager.GizmosPlaying;
				UpdateInkCost();
				if (CurrentDisplayMode == DisplayMode.Gadgets)
				{
					gadgetsRadioButton.ForcePressed();
				}
				else if (CurrentDisplayMode == DisplayMode.Props)
				{
					propsRadioButton.ForcePressed();
				}
			});
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CircuitVisibilityBehaviour.HideForLocalPlayer = false;
			CreationManager.ActiveSandboxResourcesChangedEvent -= UpdateInkCost;
			Inventions.OnNewInventionUploaded -= OnNewInventionUploaded;
			Inventions.OnInventionDeleted -= OnInventionDeleted;
			RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdatedEvent);
			if (NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<SandboxGizmoManager>.Instance.GizmosPlayingChanged.Remove(OnGizmosPlayingChanged);
			}
			if (MakerPen != null)
			{
				MakerPen.Snapping.ActiveChangeEvent -= OnSnapObjectsChange;
				MakerPen makerPen = MakerPen;
				makerPen.OnModeChanged = (Action<MakerPen.ToolMode, MakerPen.TargetMode>)Delegate.Remove(makerPen.OnModeChanged, new Action<MakerPen.ToolMode, MakerPen.TargetMode>(OnMakerPenModeChanged));
			}
		}

		public void SelectShapeButton(ShapeType shapeType)
		{
			if (TrySelectButton((int)shapeType, shapeButtons, shapeButtonsRadioGroup))
			{
				UpdateSelectedItemText(shapeType.ToString());
			}
		}

		public RadioButton3D GetButtonForShape(ShapeType shapeType)
		{
			if (shapeType < ShapeType.Tube || (int)shapeType >= shapeButtons.Length)
			{
				return null;
			}
			return shapeButtons[(int)shapeType];
		}

		public void DeselectAllShapeButtons()
		{
			DeselectAllButtons(shapeButtonsRadioGroup);
			ClearSelectedItemText();
		}

		public void SelectPropButton(SpawnableToolType prop)
		{
			currentlySelectedProp = prop;
			UpdateSelectedItemText(SpawnableToolSettings.GetSpawnableToolFriendlyName(prop));
		}

		public void DeselectAllPropButtons()
		{
			currentlySelectedProp = SpawnableToolType.INVALID;
			UpdatePagedGridForDisplayMode();
			ClearSelectedItemText();
		}

		public void SelectInventionButton(Invention invention)
		{
			currentlySelectedInvention = invention;
			UpdateSelectedItemText(invention.Name);
		}

		public void DeselectAllInventionButtons()
		{
			currentlySelectedInvention = null;
			UpdatePagedGridForDisplayMode();
			ClearSelectedItemText();
		}

		public void SelectColorButton(ShapeColor color)
		{
			TrySelectButton((int)color, colorButtons, colorButtonsRadioGroup);
		}

		public void DeselectAllColorButtons()
		{
			DeselectAllButtons(colorButtonsRadioGroup);
		}

		public void SelectShapeConstraintButton(MakerPen.ConstraintMode constraintMode)
		{
			uniformShapesToggle.IsOn = constraintMode == MakerPen.ConstraintMode.Constrained;
		}

		private bool TrySelectButton(int index, RadioButton3D[] buttons, RadioGroup3D radioButtonGroup)
		{
			if (index < 0 || index >= buttons.Length)
			{
				DeselectAllButtons(radioButtonGroup);
				return false;
			}
			RadioButton3D button = buttons[index];
			radioButtonGroup.SetSelectionStates((RadioButton3D b) => b == button);
			return true;
		}

		private void DeselectAllButtons(RadioGroup3D radioButtonGroup)
		{
			radioButtonGroup.SetSelectionStates((RadioButton3D b) => false);
		}

		private void UpdatePagedGridForDisplayMode()
		{
			switch (CurrentDisplayMode)
			{
			case DisplayMode.Inventions:
				subscreenControl.ShowSubscreen(inventionsSubscreen);
				UpdateInventions();
				break;
			case DisplayMode.ShapesAndColors:
				subscreenControl.ShowSubscreen(shapesAndColorsSubscreen);
				break;
			case DisplayMode.Settings:
				subscreenControl.ShowSubscreen(settingsSubscreen);
				break;
			case DisplayMode.Gadgets:
				subscreenControl.ShowSubscreen(spawnableToolSubscreen);
				UpdateGadgets();
				break;
			case DisplayMode.Props:
				subscreenControl.ShowSubscreen(spawnableToolSubscreen);
				UpdateProps();
				break;
			}
		}

		private void UpdateGadgets()
		{
			gadgetsRadioButton.ForcePressed();
			if (CanEditGadgets)
			{
				List<SpawnableToolCategoryConfig.CategoryConfig> categoryConfigsByGroup = SpawnableToolSettings.GetCategoryConfigsByGroup(SpawnableToolCategoryConfig.Group.GAGDETS);
				spawnableToolPagedGrid.SetSpawnableTools(SpawnableToolSettings.GetSpawnableToolsByCategory(categoryConfigsByGroup[CurrentGadgetsFilterIndex].Category), currentlySelectedProp);
			}
			else
			{
				enableGadgetsButton.gameObject.SetActive(CanChangeCanEditGadget);
				spawnableToolPagedGrid.SetEmptyDisplayText((!CanChangeCanEditGadget) ? "The room owner has disabled gadget visibility for your role." : "Enable gadget visibility to view the available gadgets.");
				spawnableToolPagedGrid.SetSpawnableTools(Enumerable.Empty<SpawnableToolType>(), SpawnableToolType.INVALID);
			}
		}

		private void UpdateProps()
		{
			propsRadioButton.ForcePressed();
			List<SpawnableToolCategoryConfig.CategoryConfig> categoryConfigsByGroup = SpawnableToolSettings.GetCategoryConfigsByGroup(SpawnableToolCategoryConfig.Group.PROPS);
			spawnableToolPagedGrid.SetSpawnableTools(SpawnableToolSettings.GetSpawnableToolsByCategory(categoryConfigsByGroup[CurrentPropsFilterIndex].Category), currentlySelectedProp);
		}

		private void UpdateInventions()
		{
			inventionPagedGrid.SetLoading();
			Inventions.GetLocalPlayerInventions().Then(delegate(List<Invention> inventions)
			{
				if (this != null)
				{
					if (inventions != null)
					{
						inventionPagedGrid.SetInventions(inventions, currentlySelectedInvention);
					}
					else
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Failed to load Inventions", 1.5f);
						inventionPagedGrid.SetInventions(new List<Invention>(), null);
					}
				}
			}).Error(delegate
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Failed to load Inventions", 1.5f);
				inventionPagedGrid.SetInventions(new List<Invention>(), null);
			});
		}

		private void UpdateSpawnableToolFilterButtons(SpawnableToolCategoryConfig.Group group)
		{
			List<SpawnableToolCategoryConfig.CategoryConfig> categoryConfigsByGroup = SpawnableToolSettings.GetCategoryConfigsByGroup(group);
			for (int i = 0; i < spawnableToolFilterButtons.Length; i++)
			{
				if (i < categoryConfigsByGroup.Count)
				{
					UIHelper.SafeSetText(spawnableToolFilterButtons[i].Label, categoryConfigsByGroup[i].FriendlyName);
					spawnableToolFilterButtons[i].gameObject.SetActive(value: true);
				}
				else
				{
					spawnableToolFilterButtons[i].gameObject.SetActive(value: false);
				}
			}
			int buttonIndex = 0;
			if (group == SpawnableToolCategoryConfig.Group.GAGDETS)
			{
				if (!CanEditGadgets)
				{
					spawnableToolsFilterGroup.SetSelectionStates((RadioButton3D b) => false);
					RadioButton3D[] array = spawnableToolFilterButtons;
					foreach (RadioButton3D radioButton3D in array)
					{
						radioButton3D.Interactable = false;
					}
					return;
				}
				buttonIndex = CurrentGadgetsFilterIndex;
			}
			else
			{
				buttonIndex = CurrentPropsFilterIndex;
			}
			spawnableToolsFilterGroup.SetSelectionStates((RadioButton3D b) => b == spawnableToolFilterButtons[buttonIndex]);
			RadioButton3D[] array2 = spawnableToolFilterButtons;
			foreach (RadioButton3D radioButton3D2 in array2)
			{
				radioButton3D2.Interactable = true;
			}
		}

		private void ClearSelectedItemText()
		{
			UIHelper.SafeSetText(selectedItemText, string.Empty);
		}

		private void UpdateSelectedItemText(string friendlyName)
		{
			if (string.IsNullOrEmpty(friendlyName))
			{
				UIHelper.SafeSetText(selectedItemText, string.Empty);
			}
			else
			{
				UIHelper.SafeSetText(selectedItemText, $"Currently Selected: {friendlyName}");
			}
		}

		public void ShowTab(DisplayMode displayMode)
		{
			CurrentDisplayMode = ((displayMode == DisplayMode.None) ? DisplayMode.ShapesAndColors : displayMode);
			if (!base.IsCurrentFlow)
			{
				base.UIBase.PushFlow(this);
			}
		}

		private void OnSnapObjectsChange()
		{
			gridSnapSlider.Interactable = MakerPen.Snapping.IsActive;
			angleSnapSlider.Interactable = MakerPen.Snapping.IsActive;
		}

		private void OnMakerPenModeChanged(MakerPen.ToolMode toolMode, MakerPen.TargetMode targetMode)
		{
			if (toolMode != MakerPen.ToolMode.CreateInventionInstance && MakerPen.IsCreationToolMode(toolMode))
			{
				DeselectAllInventionButtons();
			}
		}

		private void UpdateInkCost()
		{
			if (base.isActiveAndEnabled && NetworkedSingletonMonoBehaviour<CreationManager>.Instance != null)
			{
				float num = (float)CreationManager.ActiveSandboxResourceCost / 30000f;
				inkBar.normalizedValue = Mathf.Clamp01(num);
				inkPercentageText.text = $"{Math.Round(num * 100f, 2)}%";
				if (num < 70f)
				{
					inkFillImage.color = inkUsageLittleFill;
				}
				else if (num < 95f)
				{
					inkFillImage.color = inkUsageMediumFill;
				}
				else
				{
					inkFillImage.color = inkUsageFullFill;
				}
			}
		}

		private void OnPlayerRoleDefinitionUpdatedEvent(PhotonPlayer photonPlayer, RecRoom.Systems.PlayerRoles.RoomRole roomRole)
		{
			if (!photonPlayer.IsLocal)
			{
				return;
			}
			if (cacheCanEditGadgets != CanEditGadgets)
			{
				cacheCanEditGadgets = CanEditGadgets;
				hideGadgetsToggle.Interactable = CanEditGadgets;
				if (CurrentDisplayMode == DisplayMode.Gadgets)
				{
					UpdatePagedGridForDisplayMode();
					UpdateSpawnableToolFilterButtons(SpawnableToolCategoryConfig.Group.GAGDETS);
				}
			}
			deleteAllButton.Interactable = CanDeleteAll;
		}

		private void OnGizmosPlayingChanged(bool isPlaying)
		{
			playStopGizmosToggle.IsOn = isPlaying;
		}

		private void OnNewInventionUploaded()
		{
			UpdateInventions();
		}

		private void OnInventionDeleted(long id)
		{
			UpdateInventions();
		}

		[SkipRename]
		public void Button_Close()
		{
			MakerPen.AuthorityHidePaletteMenu();
		}

		[SkipRename]
		public void Button_ShapesAndColors()
		{
			CurrentDisplayMode = DisplayMode.ShapesAndColors;
			if (MakerPen.CurrentToolMode != MakerPen.ToolMode.CreateShape)
			{
				DeselectAllShapeButtons();
			}
		}

		[SkipRename]
		public void Button_Gadgets()
		{
			CurrentDisplayMode = DisplayMode.Gadgets;
		}

		[SkipRename]
		public void Button_Props()
		{
			CurrentDisplayMode = DisplayMode.Props;
		}

		[SkipRename]
		public void Button_Inventions()
		{
			CurrentDisplayMode = DisplayMode.Inventions;
			if (MakerPen.CurrentToolMode != MakerPen.ToolMode.CreateInvention)
			{
				DeselectAllInventionButtons();
			}
		}

		[SkipRename]
		public void Button_Settings()
		{
			CurrentDisplayMode = DisplayMode.Settings;
		}

		[SkipRename]
		public void Button_FilterSpawnableTools(int index)
		{
			if (CurrentDisplayMode == DisplayMode.Gadgets)
			{
				CurrentGadgetsFilterIndex = index;
			}
			else if (CurrentDisplayMode == DisplayMode.Props)
			{
				CurrentPropsFilterIndex = index;
			}
		}

		[SkipRename]
		public void Button_SpawnableToolSelected(SpawnableToolType spawnableTool)
		{
			if (SpawnableToolSelectionButtonPressed != null)
			{
				SpawnableToolSelectionButtonPressed(spawnableTool);
			}
		}

		[SkipRename]
		public void Button_EnableGadgetEditing()
		{
			if (CanChangeCanEditGadget)
			{
