	public class MakerPenPaletteMoveableToolMenu : MoveableToolMenu
	{
		[SerializeField]
		private Transform keyboardRoot;

		[SerializeField]
		private Transform handleRoot;

		private MakerPenPaletteUI _paletteUI;

		public MakerPen MakerPen { get; set; }

		public MakerPenPaletteUI PaletteUI
		{
			get
			{
				if (_paletteUI == null && MakerPen != null && MakerPen.IsMine)
				{
					_paletteUI = base.Tool.Menu as MakerPenPaletteUI;
				}
				return _paletteUI;
			}
		}

		private MakerPenPaletteMainScreen MainScreen { get; set; }

		private MakerPenPaletteConfigScreen ConfigScreen { get; set; }

		private MakerPenPaletteTagsScreen TagsScreen { get; set; }

		private MakerPenPaletteInventionCreationScreen InventionCreationScreen { get; set; }

		private MakerPenPaletteInventionDetailsScreen InventionDetailsScreen { get; set; }

		protected override Vector3 PositionOffsetFromHead
		{
			get
			{
				Vector3 result = defaultOffsetFromHead;
				Transform transform = MakerPen.Tool.MenuProjector.transform;
				Transform transform2 = Player.LocalPlayer.Head.transform;
				Vector3 lhs = (transform.position - transform2.position).ZeroY();
				Vector3 rhs = transform2.right.ZeroY();
				if (!(Vector3.Dot(lhs, rhs) < 0f))
				{
					result.x = 0f - result.x;
				}
				return result;
			}
		}

		private void Start()
		{
			if (!(MakerPen != null) || !MakerPen.IsMine)
			{
				return;
			}
			MainScreen = base.Tool.Menu.GetFlowByType<MakerPenPaletteMainScreen>();
			ConfigScreen = base.Tool.Menu.GetFlowByType<MakerPenPaletteConfigScreen>();
			TagsScreen = base.Tool.Menu.GetFlowByType<MakerPenPaletteTagsScreen>();
			InventionCreationScreen = base.Tool.Menu.GetFlowByType<MakerPenPaletteInventionCreationScreen>();
			InventionDetailsScreen = base.Tool.Menu.GetFlowByType<MakerPenPaletteInventionDetailsScreen>();
			if (Player.LocalPlayer.PlayerUI.LocalVirtualKeyboard != null && MakerPen != null)
			{
				this.Update10hz(delegate
				{
					LocalUpdateKeyboardState();
				});
			}
		}

		public void ShowMainScreenTab(MakerPenPaletteMainScreen.DisplayMode displayMode)
		{
			base.Tool.Menu.PopAllFlows();
			MainScreen.ShowTab(displayMode);
			if (!base.IsMenuVisible)
			{
				MakerPen.AuthorityShowPaletteMenu();
			}
		}

		public void ShowConfigFlow(IConfigurable configurableObject)
		{
			if (configurableObject != null)
			{
				ConfigScreen.TargetConfigurable = configurableObject;
				ShowMenuWithFlow<MakerPenPaletteConfigScreen>();
			}
		}

		public void UpdateConfigFlow(IConfigurable configurableObject)
		{
			if (base.Tool.Menu.CurrentFlow == ConfigScreen)
			{
				ConfigScreen.TargetConfigurable = configurableObject;
			}
		}

		public void CloseConfigFlow()
		{
			if (base.Tool.Menu.CurrentFlow is MakerPenPaletteConfigScreen)
			{
				base.Tool.Menu.PopFlow();
			}
		}

		public void ShowInventionDetailsFlow(Invention invention)
		{
			InventionDetailsScreen.SetTargetInvention(invention);
			ShowMenuWithFlow<MakerPenPaletteInventionDetailsScreen>();
		}

		public void CloseInventionDetailsFlow()
		{
			if (base.Tool.Menu.CurrentFlow is MakerPenPaletteInventionDetailsScreen)
			{
				base.Tool.Menu.PopFlow();
			}
		}

		public void ShowInventionCreationFlow(Invention invention)
		{
			InventionCreationScreen.SetTargetInvention(invention);
			ShowMenuWithFlow<MakerPenPaletteInventionCreationScreen>();
		}

		public void CloseInventionCreationFlow()
		{
			int num = 0;
			if (MakerPenPaletteInventionCreationScreen.IsInventionCreationScreenOrSubScreen(base.Tool.Menu.CurrentFlow) && num < 2)
			{
				base.Tool.Menu.PopFlow();
				num++;
			}
		}

		public void PushInventionCreationFlow(Invention invention, bool skipObjectSelection = false)
		{
			InventionCreationScreen.SetTargetInvention(invention);
			if (skipObjectSelection)
			{
				InventionCreationScreen.SkipObjectSelection(skip: true);
			}
			if (!(base.Tool.Menu.CurrentFlow is MakerPenPaletteInventionCreationScreen))
			{
				base.Tool.Menu.PushFlow<MakerPenPaletteInventionCreationScreen>();
			}
		}

		public void ShowEditTagsUI()
		{
			CreationObject creationObject = null;
			if (MakerPen.CreationContext.HasSelection)
			{
				creationObject = MakerPen.CreationContext.CurrentSelection.First();
			}
			if (creationObject != null)
			{
				TagsScreen.InitializeObjectData(creationObject);
				ShowMenuWithFlow<MakerPenPaletteTagsScreen>();
			}
		}

		public void EnableHandles(bool enabled)
		{
			if (handleRoot != null)
			{
				handleRoot.gameObject.SetActive(enabled);
			}
		}

		private void ShowMenuWithFlow<T>() where T : MakerPenPaletteUIFlowBase
		{
			if (!(base.Tool.Menu.CurrentFlow is T))
			{
				base.Tool.Menu.PushFlow<T>();
			}
			if (!base.IsMenuVisible)
			{
				MakerPen.AuthorityShowPaletteMenu();
			}
		}

		private void LocalUpdateKeyboardState()
		{
			if (!Player.LocalPlayerExists || Player.LocalPlayer.PlayerUI.LocalVirtualKeyboard == null)
			{
				return;
			}
			bool flag = false;
			if (base.IsMenuVisible)
			{
				TMP_InputField focusedInputField = KeyboardInputField.FocusedInputField;
				flag = focusedInputField != null && focusedInputField.transform.HasParent(base.transform) && SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode;
			}
			if (flag != Player.LocalPlayer.PlayerUI.LocalVirtualKeyboard.IsOpen)
			{
				if (flag)
				{
					Player.LocalPlayer.PlayerUI.LocalVirtualKeyboard.ShowKeyboard(this, keyboardRoot);
				}
				else
				{
					Player.LocalPlayer.PlayerUI.LocalVirtualKeyboard.HideKeyboard(this);
				}
			}
		}
	}
}
namespace RecRoom.Tools.Tags
{
	public class MakerPenPaletteTagsScreen : MakerPenPaletteUIFlowBase
	{
		[SerializeField]
		private TextMeshProUGUI editableObjectNameText;

		[SerializeField]
		private RectTransform propertiesGridTransform;

		[SerializeField]
		private Transform bottomRow;

		[SerializeField]
		private Button3D addTagButton;

		[Header("Editing")]
		public SandboxReadonlyListItemUIControl TagsStringUIPrefab;

		[SerializeField]
		private TextInputUIDialog textInputDialogPrefab;

		private TaggedTool currentTaggedTool;

		private readonly List<SandboxReadonlyListItemUIControl> tagsUIControls = new List<SandboxReadonlyListItemUIControl>();

		public void InitializeObjectData(CreationObject creationObject)
		{
			foreach (SandboxReadonlyListItemUIControl tagsUIControl in tagsUIControls)
			{
				UnityEngine.Object.Destroy(tagsUIControl.gameObject);
			}
			tagsUIControls.Clear();
			editableObjectNameText.text = creationObject.UserFriendlyName;
			currentTaggedTool = creationObject.Tool.Tags;
			InitializeTagData();
		}

		private void InitializeTagData()
		{
			if (currentTaggedTool != null)
			{
				foreach (string displayTag in currentTaggedTool.DisplayTags)
				{
					SandboxReadonlyListItemUIControl item = CreateTagEditor(displayTag, propertiesGridTransform);
					tagsUIControls.Add(item);
				}
			}
			RefreshAddTagInteractable();
		}

		private void RefreshAddTagInteractable()
		{
			addTagButton.Interactable = currentTaggedTool != null && tagsUIControls.Count < 5;
		}

		private SandboxReadonlyListItemUIControl CreateTagEditor(string tag, Transform parentTransform)
		{
			SandboxReadonlyListItemUIControl uiInstance = UnityEngine.Object.Instantiate(TagsStringUIPrefab);
			uiInstance.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
			uiInstance.transform.SetParent(parentTransform, worldPositionStays: false);
			uiInstance.DeleteButton.OnClick.AddListener(delegate
			{
				OnDeleteTagButtonClick(uiInstance);
			});
			bottomRow.SetAsLastSibling();
			uiInstance.PropertyGetter = () => tag;
			uiInstance.UpdateControl();
			return uiInstance;
		}

		public void ExistingTagProperty_Set(string newTag)
		{
			List<string> list = new List<string>();
			foreach (SandboxReadonlyListItemUIControl tagsUIControl in tagsUIControls)
			{
				list.Add(tagsUIControl.PropertyGetter());
			}
			foreach (string displayTag in currentTaggedTool.DisplayTags)
			{
				if (displayTag != newTag && !list.Contains(displayTag))
				{
					currentTaggedTool.RemoveTag(displayTag);
				}
			}
			if (!list.Contains(newTag))
			{
				currentTaggedTool.RequestAddTag(newTag);
			}
		}

		public void OnAddTagButtonClick()
		{
			MakerPenPaletteUI paletteMenuToolUI = MakerPen.PaletteMenuToolUI;
			paletteMenuToolUI.ShowTemporaryDialog(textInputDialogPrefab, (TextInputUIDialog dialog) => dialog.ShowDialog(TMP_InputField.ContentType.Alphanumeric, "Add Tag", $"Enter new tag for {editableObjectNameText.text}", "Ok", purifyText: true, 25, null, shouldFocusInputField: true)).Then(delegate(TextInputUIDialog.InputResponse r)
			{
				if (r.Response == ConfirmDialogResponses.Affirmative)
				{
					string text = r.TextInput.ToLower();
					tagsUIControls.Add(CreateTagEditor(text, propertiesGridTransform));
					currentTaggedTool.RequestAddTag(text);
					RefreshAddTagInteractable();
				}
			});
		}

		public void OnResetToDefaultsButtonClick()
		{
			foreach (SandboxReadonlyListItemUIControl tagsUIControl in tagsUIControls)
			{
				currentTaggedTool.RemoveTag(tagsUIControl.PropertyGetter());
				UnityEngine.Object.Destroy(tagsUIControl.gameObject);
			}
			tagsUIControls.Clear();
			currentTaggedTool.ResetTags();
			InitializeTagData();
		}

		public void OnDeleteTagButtonClick(SandboxReadonlyListItemUIControl instance)
		{
			tagsUIControls.Remove(instance);
			currentTaggedTool.RemoveTag(instance.PropertyGetter());
			UnityEngine.Object.Destroy(instance.gameObject);
			RefreshAddTagInteractable();
		}
	}
}
namespace RecRoom.AGUI.ToolUIs
{
	public class MakerPenPaletteUI : ToolUI
	{
		public const string SIZE_CONFIG_KEY = "MAKER_PEN_PALETTE";

		private UIConfirmationDialog confirmationDialog;

		protected override string SizeConfigKey => "MAKER_PEN_PALETTE";

		protected override void OnFlowsInitialized()
		{
			base.OnFlowsInitialized();
			confirmationDialog = GetFlowByType<UIConfirmationDialog>();
			if (confirmationDialog == null)
			{
				UnityEngine.Debug.LogError("No confirmation dialog found");
			}
		}

		public IPromise<ConfirmDialogResponses> ShowConfirmationDialog(string titleText, string bodyText)
		{
			return ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, titleText, bodyText, "Yes");
		}

		public IPromise<ConfirmDialogResponses> ShowConfirmationDialog(UIConfirmationDialog.DialogType dialogType, string titleText, string bodyText, string yesText, string noText = "No")
		{
			IPromise<ConfirmDialogResponses> result = confirmationDialog.ShowDialog(dialogType, titleText, bodyText, yesText, noText);
			PushFlow(confirmationDialog);
			return result;
		}

		public IPromise<ResponseType> ShowTemporaryDialog<DialogType, ResponseType>(DialogType dialogPrefab, Func<DialogType, IPromise<ResponseType>> createPromiseFunc) where DialogType : UIDialog<ResponseType>
		{
			DialogType newDialog = UnityEngine.Object.Instantiate(dialogPrefab, base.transform, worldPositionStays: false);
			newDialog.IsInstanced = true;
			if ((bool)newDialog)
			{
				InitializeFlow(newDialog);
				PushFlow(newDialog);
				IPromise<ResponseType> promise = createPromiseFunc(newDialog);
				promise.Then((Action)delegate
				{
					UnityEngine.Object.Destroy(newDialog.gameObject);
				});
				return promise;
			}
			return null;
		}

		public IPromise<R> ShowTemporaryDialog<T1, R>(UIDialog<T1, R> dialogPrefab, T1 param)
		{
			UIDialog<R> dialogInstance;
			return ShowTemporaryDialog(dialogPrefab, param, out dialogInstance);
		}

		public IPromise<R> ShowTemporaryDialog<T1, R>(UIDialog<T1, R> dialogPrefab, T1 param, out UIDialog<R> dialogInstance)
		{
			UIDialog<T1, R> newDialog = UnityEngine.Object.Instantiate(dialogPrefab, base.transform, worldPositionStays: false);
			newDialog.IsInstanced = true;
			if ((bool)newDialog)
			{
				InitializeFlow(newDialog);
				PushFlow(newDialog);
				IPromise<R> promise = newDialog.ShowDialog(param);
				promise.Then((Action)delegate
				{
					UnityEngine.Object.Destroy(newDialog.gameObject);
				});
				dialogInstance = newDialog;
				dialogInstance.IsInstanced = true;
				return promise;
			}
			dialogInstance = null;
			return null;
		}
	}
