	public class SpawnableToolButton : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private float visualSize = 0.03f;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RadioButton3D _radioButton;

		[SerializeField]
		private Transform toolRoot;

		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private Tooltip tooltip;

		public Action<SpawnableToolType> OnButtonClicked;

		public SpawnableToolType CurrentSpawnableTool { get; private set; }

		public RadioButton3D RadioButton => _radioButton;

		public RadioButton3D.OnRadioButton3DClick ButtonAction => RadioButton.OnClick;

		private void Awake()
		{
			CurrentSpawnableTool = SpawnableToolType.INVALID;
		}

		public void SetSpawnableTool(SpawnableToolType spawnableTool, StackedUIBase stackedUIBase)
		{
			if (CurrentSpawnableTool == spawnableTool)
			{
				return;
			}
			foreach (Transform item in toolRoot)
			{
				UnityEngine.Object.Destroy(item.gameObject);
			}
			CurrentSpawnableTool = spawnableTool;
			UIHelper.SafeSetText(RadioButton.Label, SpawnableToolSettings.GetSpawnableToolFriendlyName(spawnableTool));
			if (tooltip != null)
			{
				string spawnableToolDescription = SpawnableToolSettings.GetSpawnableToolDescription(spawnableTool);
				if (string.IsNullOrEmpty(spawnableToolDescription))
				{
					tooltip.SetEnabled(enabled: false);
				}
				else
				{
					tooltip.SetEnabled(enabled: true);
					tooltip.Message = spawnableToolDescription;
				}
			}
			Delayed3DUIObjectSpawner orAddComponent = toolRoot.gameObject.GetOrAddComponent<Delayed3DUIObjectSpawner>();
			orAddComponent.Initialize(stackedUIBase, delegate(Transform parent)
			{
				GameObject gameObject = NetworkedSingletonMonoBehaviour<CreationManager>.Instance.SpawnToolImposter(CurrentSpawnableTool, parent);
				SpawnableToolCategoryConfig.Group spawnableToolGroup = SpawnableToolSettings.GetSpawnableToolGroup(CurrentSpawnableTool);
				gameObject.transform.AssignCorrectScale(visualSize, spawnableToolGroup == SpawnableToolCategoryConfig.Group.GAGDETS);
				gameObject.transform.localPosition = Vector3.zero;
			});
		}
	}
	public class SpawnableToolPagedGrid : RecyclerPagedGrid<SpawnableToolType, SpawnableToolButton>
	{
		[Serializable]
		public class SpawnableToolSelectedEvent : UnityEvent<SpawnableToolType>
		{
		}

		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private StackedUIFlowBase uiFlowBase;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RadioGroup3D radioGroup;

		public SpawnableToolSelectedEvent OnSpawnableToolSelectedEvent;

		private SpawnableToolType selectedSpawnableTool = SpawnableToolType.INVALID;

		private RadioButton3D selectedRadioButton;

		private bool selectedOnCurrentPage;

		private void Start()
		{
			if (OnSpawnableToolSelectedEvent != null)
			{
				foreach (SpawnableToolButton childUIElement in childUIElements)
				{
					SpawnableToolButton innerChild = childUIElement;
					innerChild.ButtonAction.AddListener(delegate(RadioButton3D isOn)
					{
						if ((bool)isOn)
						{
							selectedSpawnableTool = innerChild.CurrentSpawnableTool;
							selectedRadioButton = innerChild.RadioButton;
						}
						OnSpawnableToolSelectedEvent.Invoke(innerChild.CurrentSpawnableTool);
					});
				}
			}
			base.PageChangeEvent += UpdateSelectedButton;
		}

		private void UpdateSelectedButton()
		{
			radioGroup.SetSelectionStates((RadioButton3D b) => selectedOnCurrentPage && b == selectedRadioButton);
			selectedOnCurrentPage = false;
		}

		protected override void SetupNewChild(SpawnableToolButton button)
		{
			base.SetupNewChild(button);
			radioGroup.AddButton(button.RadioButton);
		}

		private void ResetSelectedSpawnableTool()
		{
			selectedSpawnableTool = SpawnableToolType.INVALID;
			selectedRadioButton = null;
			selectedOnCurrentPage = false;
			radioGroup.SetSelectionStates((RadioButton3D b) => false);
		}

		public void SetSpawnableTools(IEnumerable<SpawnableToolType> toolTypes, SpawnableToolType selected)
		{
			ResetSelectedSpawnableTool();
			selectedSpawnableTool = selected;
			SetAllActiveChildren(toolTypes.OrderBy(SpawnableToolSettings.GetSpawnableToolFriendlyName));
			UpdateSelectedButton();
		}

		protected override void SetChild(SpawnableToolType spawnableTool, SpawnableToolButton button, int activeIndex)
		{
			if (spawnableTool == selectedSpawnableTool)
			{
				selectedOnCurrentPage = true;
				selectedRadioButton = button.RadioButton;
			}
			button.SetSpawnableTool(spawnableTool, uiFlowBase.UIBase);
		}
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class TakeInventionPictureDialog : TakePictureDialog<Invention>
	{
		private Invention targetInvention;

		public override IPromise<TakePictureDialogResponse> ShowDialog(Invention invention)
		{
			targetInvention = invention;
			return ShowDialog();
		}

		protected override void ProcessPicture()
		{
			if (targetInvention != null)
			{
				Images.UploadSavedImage(photoSet, Images.SavedImageType.InventionThumbnail).Error(delegate(string uploadError)
				{
					UnityEngine.Debug.LogError("Failed to upload invention image: " + uploadError);
					UpdateUI(uploadError, enableButtons: true);
				}).Then(delegate(string imageName)
				{
					UpdateUI("Setting as invention image...", enableButtons: false);
					Inventions.UpdateInventionImage(targetInvention.InventionId, imageName).Error(delegate(string errMsg)
					{
						UnityEngine.Debug.LogError("Failed to update invention image: " + errMsg);
						UpdateUI("Failed to update invention image: " + errMsg, enableButtons: true);
					}).Then(HandleModifyResponse);
				});
			}
			else
			{
				Respond(new TakePictureDialogResponse(ConfirmDialogResponses.Affirmative, photoSet), shouldCloseDialog: true);
			}
		}

		private void HandleModifyResponse(InventionResponse response)
		{
			if (response.Status == InventionResult.Success)
			{
				Respond(new TakePictureDialogResponse(ConfirmDialogResponses.Affirmative, photoSet), shouldCloseDialog: true);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Invention picture updated!", 3f);
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Failed to update invention image: " + response.Status);
				string responseCodeFriendlyMessage = Inventions.GetResponseCodeFriendlyMessage(response.Status);
				UpdateUI(responseCodeFriendlyMessage, enableButtons: true);
			}
		}
	}
}
