namespace RecRoom.AGUI.ToolUIs
{
	public class MoveableToolMenu : Photon.MonoBehaviour
	{
		[SerializeField]
		protected Vector3 defaultOffsetFromHead = new Vector3(0.5f, -0.15f, 0.5f);

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tool _tool;

		private SynchronizedField<bool> _menuState;

		private PhotonView attachedObjectPhotonView;

		public Tool Tool => _tool;

		public bool IsMenuVisible => _menuState.Get();

		protected virtual Vector3 PositionOffsetFromHead => defaultOffsetFromHead;

		protected override void Awake()
		{
			base.Awake();
			Tool.RigidbodyEx.AddKinematic(this);
			Tool.AlwaysPhysicalPickupOffCenter = true;
			Tool.IgnorePickupDirection = true;
			Tool.GravityPickupMode = Tool.GravityPickup.DISABLED;
			Tool.DefaultCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			Tool.AttachedCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			Tool.EquippedCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			Tool.HeldCollisionLayer = Layers.DynamicPhysicsIgnoreDynamicAndPlayerAndEnemyPhysics;
			Tool.PostReleaseEvent += Tool_PostReleaseEvent;
			_menuState = new SynchronizedField<bool>(this, "MvTlMn", defaultValue: false, SetterPermissionMode.AUTHORITY, OnDetachedMenuVisibleChanged);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (Tool != null)
			{
				Tool.PostReleaseEvent -= Tool_PostReleaseEvent;
			}
		}

		private void Tool_PostReleaseEvent(Tool thisTool)
		{
			if (Tool.hasAuthority && attachedObjectPhotonView != null)
			{
				this.InvokeNextEndOfFrame(delegate
				{
					Vector3 localPosition = attachedObjectPhotonView.transform.InverseTransformPoint(base.transform.position);
					Quaternion localRotation = attachedObjectPhotonView.transform.InverseTransformRotation(base.transform.rotation);
					float localScale = attachedObjectPhotonView.transform.InverseTransformLossyUniformScale(base.transform.GetLossyUniformScale());
					Tool.AuthorityAttachToObject(attachedObjectPhotonView, localPosition, localRotation, localScale);
				});
			}
		}

		private void OnDetachedMenuVisibleChanged()
		{
			if (IsMenuVisible)
			{
				Tool.MenuProjector.IsMenuVisible = true;
			}
			else
			{
				Tool.MenuProjector.IsMenuVisible = false;
			}
		}

		public void ShowMenu()
		{
			_menuState.Set(newValue: true);
		}

		public void ShowMenuMainScreen()
		{
			Tool.Menu.PopAllFlows();
			_menuState.Set(newValue: true);
		}

		public void OpenAndAttachMenu(PhotonView attachedPhotonView)
		{
			Transform transform = Player.LocalPlayer.Head.transform;
			Vector3 position = transform.position;
			Vector3 normalized = transform.right.ZeroY().normalized;
			Vector3 normalized2 = transform.forward.ZeroY().normalized;
			Vector3 positionOffsetFromHead = PositionOffsetFromHead;
			Vector3 vector = positionOffsetFromHead.TransformCoordinateSpace(position, normalized, Vector3.up, normalized2);
			Vector3 forward = (vector - position).ZeroY();
			Quaternion rotation = Quaternion.LookRotation(forward, Vector3.up);
			base.transform.position = vector;
			base.transform.rotation = rotation;
			if (Tool.hasAuthority && attachedPhotonView != null && (!Tool.IsHeld || Tool.HolderView != attachedPhotonView))
			{
				attachedObjectPhotonView = attachedPhotonView;
				Vector3 localPosition = attachedPhotonView.transform.InverseTransformPoint(base.transform.position);
				Quaternion localRotation = attachedPhotonView.transform.InverseTransformRotation(base.transform.rotation);
				float localScale = attachedPhotonView.transform.InverseTransformLossyUniformScale(base.transform.GetLossyUniformScale());
				Tool.AuthorityAttachToObject(attachedPhotonView, localPosition, localRotation, localScale);
			}
			_menuState.Set(newValue: true);
		}

		public void HideMenu()
		{
			if (_menuState != null)
			{
				_menuState.Set(newValue: false);
			}
		}
	}
}
public class NotificationLineControl : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class NotificationLineControlConfig
	{
		public float zTranslationWrapLimit = 0.1f;

		public float zTranslationRate = 0.01f;

		public float jitterFPS = 20f;
	}

	private Vector3 initialLocalPosition;

	private Vector3 initialScale;

	private Vector3 minJitter;

	private Vector3 maxJitter;

	private Vector3 jitterScale;

	private float zTrans;

	[HideInInspector]
	public NotificationLineControlConfig Config;

	private Coroutine jitterCoroutine;

	private void Awake()
	{
		initialLocalPosition = base.transform.localPosition;
		initialScale = base.transform.localScale;
		minJitter = new Vector3(initialScale.x - initialScale.x / 10f, initialScale.y - initialScale.y / 10f, initialScale.z - initialScale.z / 10f);
		maxJitter = new Vector3(initialScale.x + initialScale.x / 10f, initialScale.y + initialScale.y / 10f, initialScale.z + initialScale.z / 10f);
		SetRandomJitterScale();
	}

	private void OnEnable()
	{
		zTrans = 0f;
		base.transform.localPosition = initialLocalPosition;
		base.transform.localScale = initialScale;
		if (jitterCoroutine != null)
		{
			StopCoroutine(jitterCoroutine);
		}
		StartCoroutine(JitterCoroutine());
	}

	private void SetRandomJitterScale()
	{
		float x = UnityEngine.Random.Range(minJitter.x, maxJitter.x);
		float y = UnityEngine.Random.Range(minJitter.y, maxJitter.y);
		float z = UnityEngine.Random.Range(minJitter.z, maxJitter.z);
		jitterScale = new Vector3(x, y, z);
	}

	private IEnumerator JitterCoroutine()
	{
		while (true)
		{
			yield return new WaitForSeconds(1f / Config.jitterFPS);
			SetRandomJitterScale();
		}
	}

	private void Update()
	{
		zTrans += Config.zTranslationRate * UnityEngine.Time.deltaTime;
		zTrans %= Config.zTranslationWrapLimit;
		Vector3 localPosition = initialLocalPosition;
		localPosition.z += zTrans;
		base.transform.localPosition = localPosition;
		base.transform.localScale = jitterScale;
		base.transform.forward = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
	}
}
public class NotificationProjectorBeam : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float notificationDistanceFromWatch = 0.3f;

	[SerializeField]
	private float iconVerticalDistFromCenter = 0.2f;

	[SerializeField]
	private float iconHorizontalDistFromCenter = 0.15f;

	[SerializeField]
	private float minimumScaleFactor = 0.2f;

	private WatchMenuProjector watchMenuProjector;

	private LineRenderer beam;

	private SpriteRenderer notificationIcon;

	private float originalScaleFactor;

	private void Start()
	{
		beam = GetComponent<LineRenderer>();
		watchMenuProjector = Player.LocalPlayer.PlayerUI.WatchMenuProjector;
		notificationIcon = GetComponentInChildren<SpriteRenderer>();
		originalScaleFactor = notificationIcon.transform.localScale.x;
	}

	private void Update()
	{
		Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform;
		beam.SetPosition(0, base.transform.position);
		Vector3 position = transform.position;
		position -= transform.up * iconVerticalDistFromCenter;
		position += transform.forward;
		if (Vector3.Dot(base.transform.position - transform.position, transform.right) > 0f)
		{
			position += transform.right * iconHorizontalDistFromCenter;
		}
		else
		{
			position -= transform.right * iconHorizontalDistFromCenter;
		}
		float num = Vector3.Dot(transform.forward, (base.transform.position - transform.position).normalized);
		if (num > 0f)
		{
			notificationIcon.transform.position = Vector3.Lerp(position, base.transform.position + base.transform.forward * notificationDistanceFromWatch, num);
			notificationIcon.transform.localScale = Vector3.one * Mathf.Lerp(originalScaleFactor, minimumScaleFactor, num);
			beam.SetPosition(1, notificationIcon.transform.position);
		}
		else
		{
			notificationIcon.transform.position = position;
			notificationIcon.transform.localScale = Vector3.one * originalScaleFactor;
			beam.SetPosition(1, position);
		}
		notificationIcon.transform.forward = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform.forward;
		if (watchMenuProjector.AttachedHand.Type == PlayerHand.HandType.Left)
		{
			Vector3 localScale = notificationIcon.transform.localScale;
			localScale.x *= -1f;
			notificationIcon.transform.localScale = localScale;
		}
	}
}
