[Serializable]
public class PlayerHandOverlapRegionEvent : UnityEvent<PlayerHand, bool>
{
}
public class PlayerHandOverlapRegion : UnityEngine.MonoBehaviour
{
	private class HandOverlapData
	{
		public PlayerHand hand;

		public bool isIn;

		public bool isInRegionThisFrame;

		public bool wasInRegionLastFrame;

		public float inStartTime;

		public float outStartTime;
	}

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action<PlayerHand, bool> m_HandOverlapChanged;

	[SerializeField]
	private PlayerHandOverlapRegionEvent onOverlapChanged;

	[SerializeField]
	private BoxCollider boxCollider;

	[SerializeField]
	[Tooltip("How long the hand has to be in region before we detect enter.")]
	private float enterDelay;

	[SerializeField]
	[Tooltip("How long the hand has to be out of region before we detect exit.")]
	private float exitDelay;

	private HandOverlapData leftData = new HandOverlapData();

	private HandOverlapData rightData = new HandOverlapData();

	private Tool ParentTool { get; set; }

	public event Action<PlayerHand, bool> HandOverlapChanged
	{
		add
		{
			Action<PlayerHand, bool> action = this.m_HandOverlapChanged;
			Action<PlayerHand, bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_HandOverlapChanged, (Action<PlayerHand, bool>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<PlayerHand, bool> action = this.m_HandOverlapChanged;
			Action<PlayerHand, bool> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_HandOverlapChanged, (Action<PlayerHand, bool>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Awake()
	{
		if (base.gameObject.GetComponentInParent<ToolMenuProjector>() == null)
		{
			ParentTool = GetComponentInParent<Tool>();
		}
	}

	private void Update()
	{
		if (!Player.LocalPlayerExists)
		{
			return;
		}
		leftData.hand = Player.LocalPlayer.LeftHand;
		rightData.hand = Player.LocalPlayer.RightHand;
		if (leftData != null && rightData != null)
		{
			leftData.isInRegionThisFrame = false;
			rightData.isInRegionThisFrame = false;
			if (!IsHandExcluded(PlayerHand.HandType.Left) && boxCollider.Contains(Player.LocalPlayer.LeftHand.FingertipTransform.position))
			{
				leftData.isInRegionThisFrame = true;
			}
			if (!IsHandExcluded(PlayerHand.HandType.Right) && boxCollider.Contains(Player.LocalPlayer.RightHand.FingertipTransform.position))
			{
				rightData.isInRegionThisFrame = true;
			}
			EvaluateOverlapData(leftData);
			EvaluateOverlapData(rightData);
		}
	}

	private void OnDisable()
	{
		if (leftData != null && leftData.isIn)
		{
			leftData.isIn = false;
			FireChangeEvent(leftData);
		}
		if (rightData != null && rightData.isIn)
		{
			rightData.isIn = false;
			FireChangeEvent(rightData);
		}
	}

	private bool IsHandExcluded(PlayerHand.HandType handType)
	{
		return ParentTool != null && ParentTool.IsHeldByPlayer && ParentTool.HolderHand != null && ParentTool.HolderHand.isLocal && ParentTool.HolderHand.Type == handType;
	}

	private void EvaluateOverlapData(HandOverlapData data)
	{
		bool flag = false;
		if (data.isInRegionThisFrame)
		{
			if (!data.wasInRegionLastFrame)
			{
				data.inStartTime = UnityEngine.Time.time;
			}
			if (!data.isIn && UnityEngine.Time.time - data.inStartTime > enterDelay)
			{
				data.isIn = true;
				flag = true;
			}
		}
		else
		{
			if (data.wasInRegionLastFrame)
			{
				data.outStartTime = UnityEngine.Time.time;
			}
			if (data.isIn && UnityEngine.Time.time - data.outStartTime > exitDelay)
			{
				data.isIn = false;
				flag = true;
			}
		}
		if (flag)
		{
			FireChangeEvent(data);
		}
		data.wasInRegionLastFrame = data.isInRegionThisFrame;
	}

	private void FireChangeEvent(HandOverlapData data)
	{
		if (onOverlapChanged != null)
		{
			onOverlapChanged.Invoke(data.hand, data.isIn);
		}
		if (this.HandOverlapChanged != null)
		{
			this.HandOverlapChanged(data.hand, data.isIn);
		}
	}
}
