public class PlayerOverlapRegion : UnityEngine.MonoBehaviour
{
	private class OverlapData
	{
		public Player player;

		public Player.BodyPart bodyPart;

		public bool isIn;

		public bool isInRegionThisFrame;

		public bool wasInRegionLastFrame;

		public float inStartTime;

		public float outStartTime;
	}

	[SerializeField]
	private PlayerOverlapRegionEvent onOverlapChanged;

	[SerializeField]
	private SphereCollider sphereCollider;

	[SerializeField]
	private List<Player.BodyPart> targetBodyParts;

	[SerializeField]
	[Tooltip("How long the body part has to be in region before we detect enter.")]
	private float enterDelay;

	[SerializeField]
	[Tooltip("How long the body part has to be out of region before we detect exit.")]
	private float exitDelay;

	private List<OverlapData> overlapDatas = new List<OverlapData>();

	private void Start()
	{
		if (targetBodyParts == null || targetBodyParts.Count == 0)
		{
			UnityEngine.Debug.LogErrorFormat("PlayerOverlapRegion needs at least one target body part. {0}", base.gameObject.GetGameObjectHierarchy());
			base.gameObject.SetActive(value: false);
		}
		else
		{
			NetworkedSingletonMonoBehaviour<PUNNetworkManager>.Instance.PhotonPlayerDisconnected += PUNNetworkManager_PhotonPlayerDisconnected;
		}
	}

	private void PUNNetworkManager_PhotonPlayerDisconnected(PhotonPlayer pPlayer)
	{
		OverlapData[] array = overlapDatas.ToArray();
		foreach (OverlapData overlapData in array)
		{
			if (overlapData.player == null)
			{
				overlapDatas.Remove(overlapData);
			}
		}
	}

	private void Update()
	{
		if (!Player.LocalPlayerExists)
		{
			return;
		}
		Collider[] iMMEDIATE_COLLIDER_HITS = PhysicsExt.IMMEDIATE_COLLIDER_HITS;
		int num = Physics.OverlapSphereNonAlloc(base.transform.TransformPoint(sphereCollider.center), sphereCollider.radius, iMMEDIATE_COLLIDER_HITS, 1053184);
		for (int i = 0; i < num; i++)
		{
			Player.BodyPart bodyPart;
			Player colliderPlayer = iMMEDIATE_COLLIDER_HITS[i].GetColliderPlayer(out bodyPart);
			if (colliderPlayer != null && targetBodyParts.Contains(bodyPart))
			{
				SetOrCreateOverlapData(colliderPlayer, bodyPart);
			}
		}
		foreach (OverlapData overlapData in overlapDatas)
		{
			EvaluateOverlapData(overlapData);
		}
	}

	private void SetOrCreateOverlapData(Player colliderPlayer, Player.BodyPart colliderBodyPart)
	{
		OverlapData overlapData = null;
		foreach (OverlapData overlapData3 in overlapDatas)
		{
			if (overlapData3.player != null && overlapData3.player == colliderPlayer && overlapData3.bodyPart == colliderBodyPart)
			{
				overlapData = overlapData3;
				break;
			}
		}
		if (overlapData == null)
		{
			OverlapData overlapData2 = new OverlapData();
			overlapData2.player = colliderPlayer;
			overlapData2.bodyPart = colliderBodyPart;
			overlapData = overlapData2;
			overlapDatas.Add(overlapData);
		}
		overlapData.isInRegionThisFrame = true;
	}

	private void OnDisable()
	{
		if (overlapDatas == null)
		{
			return;
		}
		foreach (OverlapData overlapData in overlapDatas)
		{
			if (overlapData.isIn)
			{
				overlapData.isIn = false;
				FireChangeEvent(overlapData);
			}
		}
	}

	private void EvaluateOverlapData(OverlapData data)
	{
		bool flag = false;
		if (data.isInRegionThisFrame)
		{
			if (!data.wasInRegionLastFrame)
			{
				data.inStartTime = UnityEngine.Time.time;
			}
			if (!data.isIn && UnityEngine.Time.time - data.inStartTime > enterDelay)
			{
				data.isIn = true;
				flag = true;
			}
		}
		else
		{
			if (data.wasInRegionLastFrame)
			{
				data.outStartTime = UnityEngine.Time.time;
			}
			if (data.isIn && UnityEngine.Time.time - data.outStartTime > exitDelay)
			{
				data.isIn = false;
				flag = true;
			}
		}
		if (flag)
		{
			FireChangeEvent(data);
		}
		data.wasInRegionLastFrame = data.isInRegionThisFrame;
		data.isInRegionThisFrame = false;
	}

	private void FireChangeEvent(OverlapData data)
	{
		if (onOverlapChanged != null)
		{
			onOverlapChanged.Invoke(data.player, data.bodyPart, data.isIn);
		}
	}
}
