namespace AGUI
{
	[DisallowMultipleComponent]
	public class ProgressBar : UnityEngine.MonoBehaviour
	{
		public enum FillOrigin
		{
			LEFT,
			RIGHT,
			TOP,
			BOTTOM
		}

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		[FormerlySerializedAs("image")]
		private UnityEngine.UI.Image _image;

		[SerializeField]
		[FormerlySerializedAs("fillOrigin")]
		private FillOrigin _origin;

		[SerializeField]
		[Range(0f, 1f)]
		private float _fillAmount;

		public UnityEngine.UI.Image Image => _image;

		public FillOrigin Origin
		{
			get
			{
				return _origin;
			}
			set
			{
				if (_origin != value)
				{
					_origin = value;
					UpdateFill();
				}
			}
		}

		public float FillAmount
		{
			get
			{
				return _fillAmount;
			}
			set
			{
				value = Mathf.Clamp01(value);
				if (_fillAmount != value)
				{
					_fillAmount = value;
					UpdateFill();
				}
			}
		}

		private void Start()
		{
			UpdateFill();
		}

		public void UpdateFill()
		{
			_image.rectTransform.anchorMin = Vector2.zero;
			_image.rectTransform.anchorMax = Vector2.one;
			switch (_origin)
			{
			case FillOrigin.LEFT:
				_image.rectTransform.anchorMax = new Vector2(FillAmount, 1f);
				break;
			case FillOrigin.RIGHT:
				_image.rectTransform.anchorMin = new Vector2(1f - FillAmount, 0f);
				break;
			case FillOrigin.BOTTOM:
				_image.rectTransform.anchorMax = new Vector2(1f, FillAmount);
				break;
			case FillOrigin.TOP:
				_image.rectTransform.anchorMin = new Vector2(0f, 1f - FillAmount);
				break;
			}
		}
	}
}
namespace RecRoom.Core
{
	public abstract class ProjectorBase : UnityEngine.MonoBehaviour
	{
		public enum VisibilityState
		{
			Default,
			ForceClosed,
			ForceOpen
		}

		[Header("Proximity")]
		[SerializeField]
		private float innerProximityTriggerRadius = 2f;

		[SerializeField]
		private float outerProximityTriggerRadius = 10f;

		[Header("Angle")]
		[SerializeField]
		[Range(0f, 180f)]
		private float maxOpeningAngle = 180f;

		[SerializeField]
		[Range(0f, 180f)]
		private float maxRotationAngle = 180f;

		[SerializeField]
		[Range(0f, 180f)]
		private float maxUprightOffsetAngle = 180f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip openAudioClip;

		[SerializeField]
		private RecRoomAudioClip closeAudioClip;

		[SerializeField]
		private RecRoomAudioClip ambientHumAudioClip;

		private static readonly int rotationYawAnimatorFloat = Animator.StringToHash("Rotate");

		private static readonly int openAnimatorBool = Animator.StringToHash("Open");

		private static readonly int fullyOpenAnimatorState = Animator.StringToHash("OpenIdle");

		private static readonly int fullyClosedAnimatorState = Animator.StringToHash("CloseIdle");

		protected Animator animator;

		private SFXAudioSource humSource;

		private Coroutine fadeHumAudioCoroutine;

		[NonSerialized]
		public VisibilityState Visibility;

		[NonSerialized]
		public Transform TargetTransform;

		private bool _open;

		protected bool Open
		{
			get
			{
				return _open;
			}
			set
			{
				if (_open != value)
				{
					if (value)
					{
						AudioManager.Play3DSFX(openAudioClip, base.transform.position);
						FadeInAmbientHum();
					}
					else
					{
						AudioManager.Play3DSFX(closeAudioClip, base.transform.position);
						FadeOutScoreboardHum();
					}
					_open = value;
					animator.SetBool(openAnimatorBool, _open);
				}
			}
		}

		public bool FullyOpen => Open && animator.GetCurrentAnimatorStateInfo(0).shortNameHash == fullyOpenAnimatorState;

		public bool FullyClosed => !Open && animator.GetCurrentAnimatorStateInfo(0).shortNameHash == fullyClosedAnimatorState;

		private float RotationYaw
		{
			set
			{
				animator.SetFloat(rotationYawAnimatorFloat, value);
			}
		}

		protected virtual void Awake()
		{
			animator = GetComponentInChildren<Animator>();
		}

		private void Start()
		{
			Open = false;
		}

		protected virtual void Update()
		{
			if (!(TargetTransform != null) && !Player.LocalPlayerExists)
			{
				return;
			}
			if (Visibility == VisibilityState.ForceClosed)
			{
				Open = false;
				return;
			}
			Vector3 vector = ((!(TargetTransform != null)) ? Player.LocalPlayer.Head.transform.position : TargetTransform.position);
			Vector3 vector2 = Vector3.ProjectOnPlane(vector - base.transform.position, Vector3.up);
			Vector3 normalized = vector2.normalized;
			Vector3 normalized2 = Vector3.ProjectOnPlane(base.transform.forward, Vector3.up).normalized;
			float num = Vector3.Angle(normalized2, normalized);
			if (Visibility == VisibilityState.ForceOpen)
			{
				Open = true;
			}
			else
			{
				float sqrMagnitude = vector2.sqrMagnitude;
				if (sqrMagnitude <= outerProximityTriggerRadius * outerProximityTriggerRadius && sqrMagnitude >= innerProximityTriggerRadius * innerProximityTriggerRadius)
				{
					float num2 = Vector3.Angle(Vector3.up, base.transform.up);
					if (num <= maxOpeningAngle && num2 <= maxUprightOffsetAngle)
					{
						Open = CustomOpeningRestrictions();
					}
					else
					{
						Open = false;
					}
				}
				else
				{
					Open = false;
				}
			}
			if (Open && maxRotationAngle > 0f)
			{
				float num3 = Mathf.Sign(Vector3.Dot(Vector3.Cross(normalized2, normalized), Vector3.up));
				RotationYaw = Mathf.Min(maxRotationAngle, num) * num3;
			}
		}

		private void OnDisable()
		{
			if (Open)
			{
				AudioManager.StopLoopingSFX(humSource);
				humSource = null;
				fadeHumAudioCoroutine = null;
				_open = false;
				animator.SetBoolIfActive(openAnimatorBool, _open);
			}
		}

		protected virtual bool CustomOpeningRestrictions()
		{
			return true;
		}

		private void FadeInAmbientHum()
		{
			if (base.enabled)
			{
				StopFadeHumCoroutine();
				fadeHumAudioCoroutine = StartCoroutine(FadeInAmbientHumCoroutine());
			}
		}

		private void FadeOutScoreboardHum()
		{
			if (base.enabled)
			{
				StopFadeHumCoroutine();
				fadeHumAudioCoroutine = StartCoroutine(FadeOutAmbientHumCoroutine());
			}
			else
			{
				AudioManager.StopLoopingSFX(humSource);
				humSource = null;
				fadeHumAudioCoroutine = null;
			}
		}

		private IEnumerator FadeInAmbientHumCoroutine()
		{
			if (humSource == null)
			{
				humSource = AudioManager.StartLooping3DSFX(ambientHumAudioClip, base.transform);
			}
			yield return SingletonMonoBehaviour<AudioManager>.Instance.RunChangeAudioVolume(humSource.AudioSource, 0f, ambientHumAudioClip.volume, 3f);
			fadeHumAudioCoroutine = null;
		}

		private IEnumerator FadeOutAmbientHumCoroutine()
		{
			yield return SingletonMonoBehaviour<AudioManager>.Instance.RunChangeAudioVolume(humSource.AudioSource, ambientHumAudioClip.volume, 0f, 1f);
			AudioManager.StopLoopingSFX(humSource);
			humSource = null;
			fadeHumAudioCoroutine = null;
		}

		private void StopFadeHumCoroutine()
		{
			if (fadeHumAudioCoroutine != null)
			{
				StopCoroutine(fadeHumAudioCoroutine);
				fadeHumAudioCoroutine = null;
			}
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.red;
			Gizmos.DrawWireSphere(base.transform.position, innerProximityTriggerRadius);
			Gizmos.color = Color.green;
			Gizmos.DrawWireSphere(base.transform.position, outerProximityTriggerRadius);
			if (maxOpeningAngle < 180f)
			{
				Gizmos.color = Color.yellow;
				Gizmos.DrawLine(base.transform.position, base.transform.position + Quaternion.Euler(0f, maxOpeningAngle, 0f) * base.transform.forward * outerProximityTriggerRadius);
				Gizmos.DrawLine(base.transform.position, base.transform.position + Quaternion.Euler(0f, 0f - maxOpeningAngle, 0f) * base.transform.forward * outerProximityTriggerRadius);
			}
		}
	}
}
public class ProjectorUIElementView : UnityEngine.MonoBehaviour
{
