public class PunchCardObjectiveView : DailyObjectiveView
{
	[SerializeField]
	private Button3D giftPackageButton;

	[SerializeField]
	private Animator giftPackageButtonAnimator;

	[SerializeField]
	private GameObject statusMessageObject;

	[SerializeField]
	private Text statusMessageText;

	private IEnumerator queuedProgressAnimation;

	private Coroutine progressAnimation;

	private static float minimumAnimation_pct = 0.01f;

	private static float progressAnimationTime = 1f;

	private static float animationDelayTime = 0.25f;

	private bool cachedRewardAvailable;

	public void AddRewardButtonOnClick(UnityAction onClick)
	{
		if (giftPackageButton != null)
		{
			giftPackageButton.OnClick.AddListener(onClick);
		}
	}

	public void RemoveRewardButtonOnClickListener(UnityAction onClick)
	{
		if (giftPackageButton != null)
		{
			giftPackageButton.OnClick.RemoveListener(onClick);
		}
	}

	public void ClearRewardButtonListeners()
	{
		if (giftPackageButton != null)
		{
			giftPackageButton.OnClick.RemoveAllListeners();
		}
	}

	public void ShowStatusMessage(string message)
	{
		if (string.IsNullOrEmpty(message))
		{
			ClearStatusMessage();
			return;
		}
		statusMessageText.text = message;
		statusMessageObject.SetActive(value: true);
	}

	public void ClearStatusMessage()
	{
		statusMessageText.text = string.Empty;
		statusMessageObject.SetActive(value: false);
	}

	public override void UpdateProgress(int progress, int total, bool completed, bool rewardAvailable, string helpText, string tooltipText)
	{
		base.UpdateProgress(progress, total, completed, rewardAvailable, helpText, tooltipText);
		cachedRewardAvailable = rewardAvailable;
		if (giftPackageButton != null)
		{
			giftPackageButtonAnimator.gameObject.SetActive(rewardAvailable);
			tooltip.enabled = !rewardAvailable;
			if (rewardAvailable)
			{
				giftPackageButtonAnimator.SetBool("Visible", value: true);
			}
		}
		progressLabel.gameObject.SetActive(value: false);
	}

	private void OnEnable()
	{
		if (queuedProgressAnimation != null)
		{
			StopAnimation();
			progressAnimation = StartCoroutine(queuedProgressAnimation);
		}
		if (cachedRewardAvailable)
		{
			giftPackageButtonAnimator.SetBool("Visible", value: true);
		}
	}

	private void OnDestroy()
	{
		queuedProgressAnimation = null;
	}

	public override void AnimateProgress(int prevProgress, int currProgress, int total, bool wasCompleted, bool isCompleted, bool rewardAvailable, string helpText, string tooltipText, Action onAnimComplete)
	{
		StopAnimation();
		if (prevProgress != currProgress || wasCompleted != isCompleted)
		{
			queuedProgressAnimation = ProgressAnimation(prevProgress, currProgress, total, wasCompleted, isCompleted, rewardAvailable, helpText, tooltipText, onAnimComplete);
			if (base.isActiveAndEnabled)
			{
				progressAnimation = StartCoroutine(queuedProgressAnimation);
			}
		}
		else
		{
			UpdateProgress(currProgress, total, isCompleted, rewardAvailable, helpText, tooltipText);
			onAnimComplete?.Invoke();
		}
	}

	private void StopAnimation()
	{
		if (progressAnimation != null)
		{
			StopCoroutine(progressAnimation);
			progressAnimation = null;
		}
	}

	private IEnumerator ProgressAnimation(int prevProgress, int currProgress, int total, bool wasCompleted, bool isCompleted, bool rewardAvailable, string helpText, string tooltipText, Action onAnimComplete)
	{
		completionVisual.SetActive(value: false);
		description.text = helpText;
		tooltip.Message = tooltipText;
		float startPct = (((float)total != 0f) ? Mathf.Clamp01((float)prevProgress / (float)total) : 0f);
		float targetPct = (((float)total != 0f) ? Mathf.Clamp01((float)currProgress / (float)total) : 0f);
		if (targetPct < startPct || Mathf.Abs(targetPct - startPct) < minimumAnimation_pct)
		{
			UpdateProgress(currProgress, total, isCompleted, rewardAvailable, helpText, tooltipText);
			onAnimComplete?.Invoke();
			yield break;
		}
		float delayedTime = 0f;
		while (delayedTime < animationDelayTime)
		{
			delayedTime += UnityEngine.Time.deltaTime;
			yield return null;
		}
		float animationSpeed = (targetPct - startPct) / progressAnimationTime;
		float displayPct = startPct;
		while (displayPct < targetPct)
		{
			yield return null;
			displayPct += animationSpeed * UnityEngine.Time.deltaTime;
			progressSlider.value = Mathf.Clamp01(displayPct);
		}
		progressSlider.value = targetPct;
		if (isCompleted)
		{
			completionVisual.SetActive(value: true);
			progressSlider.value = 1f;
		}
		if (giftPackageButton != null)
		{
			giftPackageButtonAnimator.gameObject.SetActive(rewardAvailable);
			if (rewardAvailable)
			{
				giftPackageButtonAnimator.SetBool("Visible", value: true);
			}
			tooltip.enabled = !rewardAvailable;
		}
		cachedRewardAvailable = rewardAvailable;
		queuedProgressAnimation = null;
		onAnimComplete?.Invoke();
	}
}
namespace RecRoom
{
	public class QuickActionButton : UnityEngine.MonoBehaviour
	{
		public enum PositionDefaults
		{
			Right,
			Bottom,
			Left,
			Top
		}

		[SerializeField]
		private TextMesh textMesh;

		[SerializeField]
		private Collider buttonCollision;

		[SerializeField]
		private Transform backgroundTransform;

		[SerializeField]
		private Vector2 backgroundHorizontalPadding = new Vector2(0.05f, 0.05f);

		[SerializeField]
		private float hoveredAlpha = 0.9f;

		private Renderer textRenderer;

		private Renderer backgroundRenderer;

		private float defaultTextAlpha;

		private float defaultBackgroundAlpha;

		private Func<IPromise<string>> clickAction;

		private PositionDefaults positioning;

		private ISchedulerPromise fadeCoroutine;

		private float targetTextAlpha = 0.9f;

		private float targetBackgroundAlpha = 0.9f;

		private Vector3 targetLocalPosition = Vector3.zero;

		private Vector3 targetLocalScale = Vector3.one;

		private static float animateDegrees = 90f;

		private static float fadeSpeed = 20f;

		private void Awake()
		{
			textRenderer = textMesh.GetComponent<Renderer>();
			textRenderer.material.renderQueue = 10000;
			backgroundRenderer = buttonCollision.GetComponent<Renderer>();
			backgroundRenderer.material.renderQueue = 9999;
			defaultTextAlpha = textRenderer.material.color.a;
			defaultBackgroundAlpha = backgroundRenderer.material.color.a;
			targetTextAlpha = defaultTextAlpha;
			targetBackgroundAlpha = defaultBackgroundAlpha;
		}

		public void Hide()
		{
			ForceStopAnimateIn();
			base.gameObject.SetActive(value: false);
		}

		public void Show()
		{
			base.gameObject.SetActive(value: true);
			fadeCoroutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(RunAnimateIn());
		}

		public void Configure(string buttonText, Vector3 menuCenter, PositionDefaults positioning, Func<IPromise<string>> onClick)
		{
			clickAction = onClick;
			textMesh.text = buttonText;
			this.positioning = positioning;
			AlignToNewCenter(menuCenter);
		}

		public void AlignToNewCenter(Vector3 newMenuCenter)
		{
			float scaleFactorForCameraDistance = QuickActionMenu.GetScaleFactorForCameraDistance(SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera, newMenuCenter);
			base.transform.localScale = new Vector3(scaleFactorForCameraDistance, scaleFactorForCameraDistance, scaleFactorForCameraDistance);
			Vector3 offset = GetOffset(positioning);
			Vector3 position = newMenuCenter + base.transform.right * scaleFactorForCameraDistance * offset.x + base.transform.up * scaleFactorForCameraDistance * offset.y + base.transform.forward * scaleFactorForCameraDistance * offset.z;
			base.transform.position = position;
			targetLocalPosition = base.transform.localPosition;
			targetLocalScale = base.transform.localScale;
			if (base.gameObject.activeSelf)
			{
				SingletonMonoBehaviour<Scheduler>.Instance.Run(RunUpdateBoundsSize());
			}
		}

		public bool Raycast(Ray ray, out RaycastHit hit, float maxDist)
		{
			return buttonCollision.Raycast(ray, out hit, maxDist);
		}

		public IPromise<string> Click()
		{
			IPromise<string> result = null;
			if (clickAction != null)
			{
				result = clickAction();
			}
			return result;
		}

		public void SetHovered(bool isHovered)
		{
			if (isHovered)
			{
				targetTextAlpha = hoveredAlpha;
				targetBackgroundAlpha = hoveredAlpha;
				textRenderer.SetColorAlpha(hoveredAlpha);
				backgroundRenderer.SetColorAlpha(hoveredAlpha);
			}
			else
			{
				targetTextAlpha = defaultTextAlpha;
				targetBackgroundAlpha = defaultBackgroundAlpha;
				textRenderer.SetColorAlpha(defaultTextAlpha);
				backgroundRenderer.SetColorAlpha(defaultBackgroundAlpha);
			}
		}

		private IEnumerator<ISchedule> RunUpdateBoundsSize()
		{
			yield return Schedule.NextFrame;
			UpdateBoundsSizeImmediate();
		}

		private void UpdateBoundsSizeImmediate()
		{
			Vector3 localScale = base.transform.localScale;
			base.transform.localScale = Vector3.one;
			Quaternion rotation = textMesh.transform.rotation;
			textMesh.transform.rotation = Quaternion.identity;
			Bounds bounds = textRenderer.bounds;
			Vector3 size = bounds.size;
			textMesh.transform.rotation = rotation;
			base.transform.localScale = localScale;
			backgroundTransform.transform.localScale = new Vector3(size.x + backgroundHorizontalPadding.x, size.y + backgroundHorizontalPadding.y, size.z);
			Vector3 localPosition = textMesh.transform.InverseTransformPoint(bounds.center);
			localPosition.z = 0f;
			backgroundTransform.transform.localPosition = localPosition;
		}

		private IEnumerator<ISchedule> RunAnimateIn()
		{
			textRenderer.SetColorAlpha(0f);
			backgroundRenderer.SetColorAlpha(0f);
			yield return Schedule.NextFrame;
			UpdateBoundsSizeImmediate();
			float initXDegrees = 0f;
			float initYDegrees = 0f;
			float initZDegrees = 0f;
			if (Mathf.Abs(targetLocalPosition.x) > 0.01f || Mathf.Abs(targetLocalPosition.y) > 0.01f)
			{
				float f = Mathf.Atan2(targetLocalPosition.y, targetLocalPosition.x);
				float num = Mathf.Sin(f);
				float num2 = Mathf.Cos(f);
				initYDegrees = -1f * animateDegrees * num2;
				initXDegrees = -1f * animateDegrees * num;
			}
			Quaternion initialLocalRotation = Quaternion.Euler(initXDegrees, initYDegrees, initZDegrees);
			Quaternion targetLocalRotation = Quaternion.identity;
			float t = 0f;
			while (t < 0.99f)
			{
				t = Mathf.SmoothStep(t, 1f, UnityEngine.Time.deltaTime * fadeSpeed);
				textRenderer.SetColorAlpha(targetTextAlpha * t);
				backgroundRenderer.SetColorAlpha(targetBackgroundAlpha * t);
				base.transform.localPosition = t * targetLocalPosition;
				base.transform.localScale = Mathf.Max(0.01f, t) * targetLocalScale;
				base.transform.localRotation = Quaternion.Slerp(initialLocalRotation, targetLocalRotation, t);
				yield return Schedule.NextFrame;
			}
			textRenderer.SetColorAlpha(targetTextAlpha);
			backgroundRenderer.SetColorAlpha(targetBackgroundAlpha);
			base.transform.localPosition = targetLocalPosition;
			base.transform.localScale = targetLocalScale;
		}

		private void ForceStopAnimateIn()
		{
			if (fadeCoroutine != null)
			{
				fadeCoroutine.Cancel();
				base.transform.localPosition = targetLocalPosition;
				base.transform.localScale = targetLocalScale;
				fadeCoroutine = null;
			}
		}

		private Vector3 GetOffset(PositionDefaults positioning)
		{
			return positioning switch
			{
				PositionDefaults.Bottom => new Vector3(0f, -0.1f, 0f), 
				PositionDefaults.Left => new Vector3(-0.25f, 0f, 0f), 
				PositionDefaults.Top => new Vector3(0f, 0.1f, 0f), 
				_ => new Vector3(0.25f, 0f, 0f), 
			};
		}
	}
	public class QuickActionMenu : UnityEngine.MonoBehaviour
	{
		private enum MenuStates
		{
			Closed,
			Hint,
			Open,
			SelectionFeedback
		}

		public struct ButtonConfig
		{
			public string buttonText;

			public QuickActionButton.PositionDefaults positioning;

			public Func<IPromise<string>> onClick;

			public ButtonConfig(string buttonText, QuickActionButton.PositionDefaults positioning, Func<IPromise<string>> onClick)
			{
				this.buttonText = buttonText;
				this.positioning = positioning;
				this.onClick = onClick;
			}
		}

		public const int INVALID_BUTTON_ID = -1;

		[SerializeField]
		private GameObject menuHint;

		[SerializeField]
		private Collider menuHintCollider;

		[SerializeField]
		private TextMesh feedbackText;

		[SerializeField]
		private QuickActionButton buttonPrefab;

		[SerializeField]
		private int maxButtons;

		[SerializeField]
		private Animator menuHintAnimator;

		private QuickActionButton[] quickActionButtonPool;

		private bool[] buttonsUsed;

		private ManualUpdateStateMachine menuStateMachine;

		private ISchedulerPromise feedbackStateTimer;

		private Renderer feedbackTextRenderer;

		private RaycastHit lastHit;

		private bool lastRaycastWasHit;

		private static float animDuration = 1.2f;

		private static float localPosYDelta = 0.05f;

		private static float menuHintScaleMultiplier_Screen = 0.5f;

		private static float menuHintScaleMultiplier_VR = 1f;

		private static float distForScaleOne_VR = 3f;

		private static float distForScaleOne_Screen = 1f;

		private const float clampedMinDistance = 2.75f;

		private MenuStates CurrentState => (MenuStates)menuStateMachine.CurrentStateId;

		private void Awake()
		{
			quickActionButtonPool = new QuickActionButton[maxButtons];
			buttonsUsed = new bool[maxButtons];
			for (int i = 0; i < maxButtons; i++)
			{
				buttonsUsed[i] = false;
				quickActionButtonPool[i] = UnityEngine.Object.Instantiate(buttonPrefab, base.transform);
				quickActionButtonPool[i].Hide();
			}
			menuHint.gameObject.SetActive(value: false);
			feedbackTextRenderer = feedbackText.GetComponent<Renderer>();
			feedbackTextRenderer.material.renderQueue = 10000;
			feedbackText.gameObject.SetActive(value: false);
			menuStateMachine = new ManualUpdateStateMachine();
			menuStateMachine.AddState(0, null, null, null);
			menuStateMachine.AddState(1, OnEnterHintState, OnExitHintState, null);
			menuStateMachine.AddState(2, OnEnterOpenState, OnExitOpenState, null);
			menuStateMachine.AddState(3, OnEnterFeedbackState, OnExitFeedbackState, null);
			menuStateMachine.EnterState(0);
		}

		private void OnEnterHintState(ushort otherStateId, ushort otherSubStateId)
		{
			float scaleFactorForCameraDistance = GetScaleFactorForCameraDistance(SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera, base.transform.position);
			scaleFactorForCameraDistance = ((!IsScreenMode()) ? (scaleFactorForCameraDistance * menuHintScaleMultiplier_VR) : (scaleFactorForCameraDistance * menuHintScaleMultiplier_Screen));
			menuHint.transform.localScale = new Vector3(scaleFactorForCameraDistance, scaleFactorForCameraDistance, scaleFactorForCameraDistance);
			menuHint.gameObject.SetActive(value: true);
			menuHintAnimator.Play("OpenMenuHintAnim");
		}

		private void OnExitHintState(ushort otherStateId, ushort otherSubStateId)
		{
			menuHint.gameObject.SetActive(value: false);
		}

		private void OnEnterOpenState(ushort otherStateId, ushort otherSubStateId)
		{
			for (int i = 0; i < buttonsUsed.Length; i++)
			{
				if (buttonsUsed[i])
				{
					quickActionButtonPool[i].Show();
				}
			}
		}

		private void OnExitOpenState(ushort otherStateId, ushort otherSubStateId)
		{
			for (int i = 0; i < buttonsUsed.Length; i++)
			{
				quickActionButtonPool[i].Hide();
			}
		}

		private void OnEnterFeedbackState(ushort otherStateId, ushort otherSubStateId)
		{
			feedbackTextRenderer.SetColorAlpha(1f);
			feedbackText.gameObject.SetActive(value: true);
			feedbackStateTimer = SingletonMonoBehaviour<Scheduler>.Instance.Run(AnimateFeedback());
		}

		private void OnExitFeedbackState(ushort otherStateId, ushort otherSubStateId)
		{
			feedbackText.gameObject.SetActive(value: false);
			if (feedbackStateTimer != null)
			{
				feedbackStateTimer.Cancel();
				feedbackStateTimer = null;
			}
		}

		public void ConfigureMenu(ButtonConfig[] buttonConfigs)
		{
			ClearAllButtons();
			for (int i = 0; i < buttonConfigs.Length; i++)
			{
				ButtonConfig buttonConfig = buttonConfigs[i];
				AddButton(buttonConfig.buttonText, buttonConfig.positioning, buttonConfig.onClick);
			}
		}

		public int AddButton(string buttonText, QuickActionButton.PositionDefaults positioning, Func<IPromise<string>> onClick)
		{
			for (int i = 0; i < buttonsUsed.Length; i++)
			{
				if (!buttonsUsed[i])
				{
					buttonsUsed[i] = true;
					quickActionButtonPool[i].Configure(buttonText, base.transform.position, positioning, onClick);
					if (menuStateMachine.CurrentStateId == 2)
					{
						quickActionButtonPool[i].Show();
					}
					break;
				}
			}
			return -1;
		}

		public void RemoveButton(int buttonId)
		{
			if (buttonId >= 0 && buttonId < buttonsUsed.Length)
			{
				buttonsUsed[buttonId] = false;
				quickActionButtonPool[buttonId].Hide();
			}
		}

		public void ClearAllButtons()
		{
			for (int i = 0; i < buttonsUsed.Length; i++)
			{
				RemoveButton(i);
			}
			if (menuStateMachine.CurrentStateId == 2)
			{
				CloseMenu();
			}
		}

		public void ShowMenuHint(Vector3 position)
		{
			ShowMenuHint(position, new Vector3(0.1f, 0f, 0f));
		}

		public void ShowMenuHint(Vector3 position, Vector3 scaledCameraOffset)
		{
			PositionMenuRoot(position, scaledCameraOffset);
			menuStateMachine.EnterState(1);
		}

		public void HideMenuHint()
		{
			if (menuStateMachine.CurrentStateId == 1)
			{
				menuStateMachine.EnterState(0);
			}
		}

		public void OpenMenu()
		{
			menuStateMachine.EnterState(2);
		}

		public void OpenMenu(Vector3 position, Vector3 scaledCameraOffset)
		{
			PositionMenuRoot(position, scaledCameraOffset);
			OpenMenu();
		}

		public void CloseMenu()
		{
			menuStateMachine.EnterState(0);
		}

		public bool UpdateHover(Ray ray, out RaycastHit hitInfo, float maxDist)
		{
			bool flag = false;
			hitInfo = default(RaycastHit);
			if (CurrentState == MenuStates.Hint)
			{
				flag = menuHintCollider.Raycast(ray, out lastHit, maxDist);
				hitInfo = lastHit;
				menuHintAnimator.SetBool("IsHovered", flag);
			}
			else if (CurrentState == MenuStates.Open)
			{
				bool flag2 = false;
				for (int i = 0; i < maxButtons; i++)
				{
					if (!flag2 && buttonsUsed[i])
					{
						flag = quickActionButtonPool[i].Raycast(ray, out lastHit, maxDist);
						quickActionButtonPool[i].SetHovered(flag);
						if (flag)
						{
							hitInfo = lastHit;
							flag2 = true;
						}
					}
					else
					{
						quickActionButtonPool[i].SetHovered(isHovered: false);
					}
				}
			}
			lastRaycastWasHit = flag;
			return flag;
		}

		public bool TryClick()
		{
			if (!lastRaycastWasHit)
			{
				CloseMenu();
				return false;
			}
			if (CurrentState == MenuStates.Hint)
			{
				menuStateMachine.EnterState(2);
			}
			else if (CurrentState == MenuStates.Open)
			{
				QuickActionButton selectedButton = lastHit.collider?.GetComponentInParent<QuickActionButton>();
				if (selectedButton == null)
				{
					return false;
				}
				IPromise<string> promise = selectedButton.Click();
				if (promise == null)
				{
					ShowFeedbackForButton(selectedButton, null);
				}
				else
				{
					promise.Then(delegate(string feedbackMsg)
					{
						ShowFeedbackForButton(selectedButton, feedbackMsg);
					});
				}
			}
			return true;
		}

		private void ShowFeedbackForButton(QuickActionButton button, string clickFeedbackMessage)
		{
			if (!string.IsNullOrEmpty(clickFeedbackMessage))
			{
				feedbackText.text = clickFeedbackMessage;
				feedbackText.transform.position = button.transform.position;
				feedbackText.transform.localScale = button.transform.localScale;
				menuStateMachine.EnterState(3);
			}
			else
			{
				menuStateMachine.EnterState(0);
			}
		}

		private IEnumerator<ISchedule> AnimateFeedback()
		{
			float initialLocalPosY = feedbackText.transform.localPosition.y;
			for (float animTime = 0f; animTime < animDuration; animTime += SingletonMonoBehaviour<Scheduler>.Instance.Timer.DeltaTime)
			{
				float pctElapsed = animTime / animDuration;
				feedbackTextRenderer.SetColorAlpha(1f - pctElapsed);
				Vector3 newLocalPos = feedbackText.transform.localPosition;
				newLocalPos.y = initialLocalPosY + pctElapsed * localPosYDelta;
				feedbackText.transform.localPosition = newLocalPos;
				yield return Schedule.NextFrame;
			}
			feedbackTextRenderer.SetColorAlpha(0f);
			menuStateMachine.EnterState(0);
			feedbackStateTimer = null;
		}

		private void PositionMenuRoot(Vector3 position, Vector3 scaledCameraOffset)
		{
			Camera activeCamera = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera;
			float scaleFactorForCameraDistance = GetScaleFactorForCameraDistance(activeCamera, position);
			position = position + activeCamera.transform.right * scaleFactorForCameraDistance * scaledCameraOffset.x + activeCamera.transform.up * scaleFactorForCameraDistance * scaledCameraOffset.y + activeCamera.transform.forward * scaleFactorForCameraDistance * scaledCameraOffset.z;
			Vector3 forward = position - activeCamera.transform.position;
			Quaternion rotation = Quaternion.LookRotation(forward, Vector3.up);
			base.transform.SetPositionAndRotation(position, rotation);
			for (int i = 0; i < maxButtons; i++)
			{
				if (buttonsUsed[i])
				{
					quickActionButtonPool[i].AlignToNewCenter(position);
				}
			}
		}

		public static float GetScaleFactorForCameraDistance(Camera cam, Vector3 worldPosition)
		{
			float num = ((!IsScreenMode()) ? distForScaleOne_VR : distForScaleOne_Screen);
			float magnitude = (cam.transform.position - worldPosition).magnitude;
			magnitude = Math.Max(2.75f, magnitude);
			return magnitude / num;
		}

		private static bool IsScreenMode()
		{
			return SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.SCREEN;
		}
	}
	public class RecentImageProjector : Photon.MonoBehaviour
	{
		[SerializeField]
		private MeshRenderer projecterRenderer;

		[SerializeField]
		private GameObject projectorDisplay;

		[SerializeField]
		private float photoDisplayTime = 7f;

		[SerializeField]
		private TextMeshPro usernameText;

		[SerializeField]
		private TextMeshPro roomNameText;

		[SerializeField]
		private BoxCollider viewingArea;

		[SerializeField]
		private Texture2D[] offlineImages;

		private const uint TARGET_IMAGE_WIDTH = 512u;

		private SynchronizedField<int> _slideshowIdx;

		private SynchronizedField<string> _slideshowCurrImageName;

		private SynchronizedField<string> _slideshowNextImageName;

		private SynchronizedField<string> _slideshowCurrPhotographerName;

		private SynchronizedField<string> _slideshowCurrRoomName;

		private List<Images.SlideshowImageDTO> imageList;

		private DateTime? validTill;

		private DateTime? lastRequestTime;

		private float lastSwitchTime;

		private Coroutine showNextPhotoCoroutine;

		private Coroutine refreshListCoroutine;

		private IPromise<Texture2D> nextImagePromise;

		private IPromise<Texture2D> currImagePromise;

		private int consecutiveLocalImageFailures;

		private const int MAX_CONSECUTIVE_FAILURES = 4;

		private bool shouldShowImagesForLocalPlayer = true;

		private int CurrentSlideshowIdx
		{
			get
			{
				return _slideshowIdx.Get();
			}
			set
			{
				_slideshowIdx.Set(value);
			}
		}

		private string CurrentSlideshowImageName
		{
			get
			{
				return _slideshowCurrImageName.Get();
			}
			set
			{
				_slideshowCurrImageName.Set(value);
			}
		}

		private string NextSlideshowImageName
		{
			get
			{
				return _slideshowNextImageName.Get();
			}
			set
			{
				_slideshowNextImageName.Set(value);
			}
		}

		private string CurrentSlideshowPhotographerName
		{
			get
			{
				return _slideshowCurrPhotographerName.Get();
			}
			set
			{
				_slideshowCurrPhotographerName.Set(value);
			}
		}

		private string CurrentSlideshowRoomName
		{
			get
			{
				return _slideshowCurrRoomName.Get();
			}
			set
			{
				_slideshowCurrRoomName.Set(value);
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_slideshowIdx = new SynchronizedField<int>(this, "SSWIDX", 0, SetterPermissionMode.MASTER);
			_slideshowCurrImageName = new SynchronizedField<string>(this, "SSWCN", string.Empty, SetterPermissionMode.MASTER, OnCurrentImageChanged);
			_slideshowNextImageName = new SynchronizedField<string>(this, "SSWNN", string.Empty, SetterPermissionMode.MASTER, OnNextImageChanged);
			_slideshowCurrPhotographerName = new SynchronizedField<string>(this, "SSWCP", string.Empty, SetterPermissionMode.MASTER, OnCurrentPhotographerChanged);
			_slideshowCurrRoomName = new SynchronizedField<string>(this, "SSWCR", string.Empty, SetterPermissionMode.MASTER, OnCurrentRoomChanged);
			OnCurrentPhotographerChanged();
			OnCurrentRoomChanged();
			lastSwitchTime = UnityEngine.Time.realtimeSinceStartup;
			UpdateImageListIfOutOfDate();
			PhotonNetwork.OnMasterClientSwitched += new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			PhotonNetwork.OnMasterClientSwitched -= new Action<PhotonPlayer>(OnMasterClientSwitched);
		}

		private IEnumerator ShowNextPhotoWhenReady()
		{
			yield return null;
			while (true)
			{
				UpdateImageListIfOutOfDate();
				float timeSinceLastSwitch = UnityEngine.Time.realtimeSinceStartup - lastSwitchTime;
				float delayTimeSeconds = photoDisplayTime - timeSinceLastSwitch;
				if (delayTimeSeconds > 0f)
				{
					yield return new WaitForSeconds(delayTimeSeconds);
				}
				else if (imageList != null)
				{
					int maxImageIdx = imageList.Count;
					CurrentSlideshowIdx = (CurrentSlideshowIdx + 1) % maxImageIdx;
					CurrentSlideshowImageName = imageList[CurrentSlideshowIdx].ImageName;
					int nextSlideshowIdx = (CurrentSlideshowIdx + 1) % maxImageIdx;
					NextSlideshowImageName = imageList[nextSlideshowIdx].ImageName;
					string photographerName = string.Empty;
					if (!string.IsNullOrEmpty(imageList[CurrentSlideshowIdx].Username))
					{
						photographerName = "@" + imageList[CurrentSlideshowIdx].Username;
					}
					CurrentSlideshowPhotographerName = photographerName;
					string roomname = string.Empty;
					if (!string.IsNullOrEmpty(imageList[CurrentSlideshowIdx].RoomName))
					{
						roomname = "^" + imageList[CurrentSlideshowIdx].RoomName;
					}
					CurrentSlideshowRoomName = roomname;
					yield return null;
				}
				else
				{
					float waitTimeSeconds = 1f;
					yield return new WaitForSeconds(waitTimeSeconds);
				}
			}
		}

		private void UpdateImageListIfOutOfDate()
		{
			if (!PhotonNetwork.isMasterClient)
			{
				return;
			}
			DateTime utcNow = DateTime.UtcNow;
			bool flag = validTill.HasValue && utcNow > validTill.Value;
			bool flag2 = lastRequestTime.HasValue && (utcNow - lastRequestTime.Value).TotalSeconds < 30.0;
			DateTime? previousValidTill = validTill;
			if (imageList == null || (flag && !flag2))
			{
				lastRequestTime = DateTime.UtcNow;
				Images.GetCurrentSlideshowInfo().Then(delegate(Images.SlideshowInfoDTO slideshowInfo)
				{
					if (this != null)
					{
						if (slideshowInfo != null && slideshowInfo.Images.Count > 0)
						{
							imageList = slideshowInfo.Images;
							validTill = slideshowInfo.ValidTill;
							if (PhotonNetwork.isMasterClient)
							{
								if (!previousValidTill.HasValue || !(previousValidTill.Value == slideshowInfo.ValidTill))
								{
									CurrentSlideshowIdx = 0;
									CurrentSlideshowImageName = imageList[CurrentSlideshowIdx].ImageName;
									int count = imageList.Count;
									int index = (CurrentSlideshowIdx + 1) % count;
									NextSlideshowImageName = imageList[index].ImageName;
								}
								if (showNextPhotoCoroutine == null)
								{
									showNextPhotoCoroutine = StartCoroutine(ShowNextPhotoWhenReady());
								}
							}
						}
						else if (PhotonNetwork.isMasterClient)
						{
							DisableProjector();
							if (showNextPhotoCoroutine != null)
							{
								StopCoroutine(showNextPhotoCoroutine);
								showNextPhotoCoroutine = null;
							}
							float num = 15f;
							if (slideshowInfo != null)
							{
								imageList = slideshowInfo.Images;
								validTill = slideshowInfo.ValidTill;
								float b = (float)(validTill.Value - DateTime.UtcNow).TotalSeconds;
								num = Mathf.Max(num, b);
							}
							if (refreshListCoroutine != null)
							{
								StopCoroutine(refreshListCoroutine);
								refreshListCoroutine = null;
							}
							refreshListCoroutine = StartCoroutine(RefreshListInSeconds(num));
						}
					}
				});
			}
			else if (showNextPhotoCoroutine == null)
			{
				showNextPhotoCoroutine = StartCoroutine(ShowNextPhotoWhenReady());
			}
		}

		private IEnumerator RefreshListInSeconds(float seconds)
		{
			yield return new WaitForSeconds(seconds);
			UpdateImageListIfOutOfDate();
		}

		private void OnCurrentImageChanged()
		{
			lastSwitchTime = UnityEngine.Time.realtimeSinceStartup;
			string currImageName = CurrentSlideshowImageName;
			if (!shouldShowImagesForLocalPlayer)
			{
				DisableProjector();
			}
			else if (string.IsNullOrEmpty(CurrentSlideshowImageName))
			{
				Texture2D offlineImageToUse = GetOfflineImageToUse();
				AssignImageToProjector(offlineImageToUse);
			}
			else if (currImageName == NextSlideshowImageName && nextImagePromise != null)
			{
				currImagePromise = nextImagePromise;
				currImagePromise.Then(delegate(Texture2D texture)
				{
					if (this != null && currImageName == CurrentSlideshowImageName)
					{
						consecutiveLocalImageFailures = 0;
						AssignImageToProjector(texture);
					}
					else
					{
						consecutiveLocalImageFailures++;
						if (consecutiveLocalImageFailures >= 4)
						{
							UnityEngine.Debug.LogWarning("Shutting down local projector -- image requests took too long");
							shouldShowImagesForLocalPlayer = false;
							DisableProjector();
						}
					}
				});
				currImagePromise.Error(delegate
				{
					consecutiveLocalImageFailures++;
					if (consecutiveLocalImageFailures >= 4)
					{
						UnityEngine.Debug.LogWarning("Shutting down local projector -- consecutive image failures");
						shouldShowImagesForLocalPlayer = false;
						DisableProjector();
					}
				});
			}
			else if (IsLocalPlayerInViewingRange())
			{
				currImagePromise = Images.GetImage(currImageName, generateMipMaps: false, overrideJuniorCheck: false, 512u).Then(delegate(Texture2D texture)
				{
					if (this != null && currImageName == CurrentSlideshowImageName)
					{
						AssignImageToProjector(texture);
					}
				});
			}
			else
			{
				Texture2D offlineImageToUse2 = GetOfflineImageToUse();
				AssignImageToProjector(offlineImageToUse2);
			}
		}

		private void OnNextImageChanged()
		{
			if (IsLocalPlayerInViewingRange() && shouldShowImagesForLocalPlayer)
			{
				nextImagePromise = Images.GetImage(NextSlideshowImageName, generateMipMaps: false, overrideJuniorCheck: false, 512u);
			}
			else
			{
				nextImagePromise = null;
			}
		}

		private bool IsLocalPlayerInViewingRange()
		{
			if (viewingArea == null)
			{
				return true;
			}
			if (Player.LocalPlayerExists)
			{
				return viewingArea.Contains(Player.LocalPlayer.Head.transform.position);
			}
			return false;
		}

		private Texture2D GetOfflineImageToUse()
		{
			if (offlineImages == null || offlineImages.Length == 0)
			{
				return null;
			}
			int num = CurrentSlideshowIdx % offlineImages.Length;
			return offlineImages[num];
		}

		private void OnCurrentPhotographerChanged()
		{
			if (usernameText != null && shouldShowImagesForLocalPlayer)
			{
				usernameText.text = CurrentSlideshowPhotographerName;
			}
			else
			{
				usernameText.text = string.Empty;
			}
		}

		private void OnCurrentRoomChanged()
		{
			if (roomNameText != null && shouldShowImagesForLocalPlayer)
			{
				roomNameText.text = CurrentSlideshowRoomName;
			}
			else
			{
				roomNameText.text = string.Empty;
			}
		}

		private void AssignImageToProjector(Texture2D image)
		{
			if (image != null)
			{
				projectorDisplay.SetActive(value: true);
				projecterRenderer.material.mainTexture = image;
			}
			else
			{
				DisableProjector();
			}
		}

		private void DisableProjector()
		{
			projectorDisplay.SetActive(value: false);
			projecterRenderer.material.mainTexture = null;
			if (roomNameText != null)
			{
				roomNameText.text = string.Empty;
			}
			if (usernameText != null)
			{
				usernameText.text = string.Empty;
			}
		}

		private void OnMasterClientSwitched(PhotonPlayer newMasterClient)
		{
			if (PhotonNetwork.isMasterClient)
			{
				UpdateImageListIfOutOfDate();
			}
			else if (showNextPhotoCoroutine != null)
			{
				StopCoroutine(showNextPhotoCoroutine);
				showNextPhotoCoroutine = null;
			}
		}
	}
}
public class GameScoreboardBodyView : ProjectorUIElementView
{
	[Header("Team Rows")]
	[SerializeField]
	private GameScoreboardTeamRowView teamRowPrefab;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private ScoreboardPagedGrid scoreboardPagedGrid;

	private List<GameScoreboardTeamRowView> toDestroy = new List<GameScoreboardTeamRowView>();

	[NonSerialized]
	public List<GameScoreboardTeamRowView> TeamRows = new List<GameScoreboardTeamRowView>();

	private ElementColors _colors;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			for (int i = 0; i < TeamRows.Count; i++)
			{
				TeamRows[i].Colors = _colors;
			}
		}
	}

	public void SetGameModel(GameUIState state, GameUIDataModel model)
	{
		toDestroy.Clear();
		for (int i = 0; i < model.TeamCount || i < TeamRows.Count; i++)
		{
			if (i >= model.TeamCount && i < TeamRows.Count)
			{
				toDestroy.Add(TeamRows[i]);
				continue;
			}
			GameScoreboardTeamRowView gameScoreboardTeamRowView = ((i < TeamRows.Count) ? TeamRows[i] : CreateTeamRow());
			ElementColors colors = Colors;
			colors.BackgroundColor = model.TeamModels[i].Color;
			gameScoreboardTeamRowView.Colors = colors;
			gameScoreboardTeamRowView.SetTeamModel(state, model, model.TeamModels[i], model.HasScore, model.HasRank, model.HideStatsInUI);
		}
		for (int j = 0; j < toDestroy.Count; j++)
		{
			GameScoreboardTeamRowView gameScoreboardTeamRowView2 = toDestroy[j];
			UnityEngine.Object.Destroy(gameScoreboardTeamRowView2.gameObject);
			TeamRows.Remove(gameScoreboardTeamRowView2);
		}
		scoreboardPagedGrid.SetPageSize(model.ScoreboardPageSize, updateGrid: false);
		scoreboardPagedGrid.SetTeamRows(TeamRows);
	}

	private GameScoreboardTeamRowView CreateTeamRow()
	{
		GameScoreboardTeamRowView gameScoreboardTeamRowView = UnityEngine.Object.Instantiate(teamRowPrefab, base.transform, worldPositionStays: false);
		TeamRows.Add(gameScoreboardTeamRowView);
		return gameScoreboardTeamRowView;
	}
}
public class GameScoreboardFooterView : ProjectorUIElementView
{
	[Serializable]
	private struct ButtonColumnView
	{
		public GameObject ButtonColumn;

		public UnityEngine.UI.Button Button;

		public Text ButtonText;
	}

	[Header("Text")]
	[SerializeField]
	private GameObject configRow;

	[SerializeField]
	private Text configText;

	[Header("Buttons")]
	[SerializeField]
	private GameObject buttonRow;

	[SerializeField]
	private ButtonColumnView joinGameButtonColumn;

	[SerializeField]
	private ButtonColumnView startGameButtonColumn;

	[SerializeField]
	private ButtonColumnView startOverGameButtonColumn;

	[SerializeField]
	private UnityEngine.UI.Button startGameEarlyButton;

	[SerializeField]
	private ButtonColumnView switchTeamButtonColumn;

	[SerializeField]
	private ButtonColumnView switchNextMapButtonColumn;

	[SerializeField]
	private GameObject nextMapLabelColumn;

	[SerializeField]
	private Text nextMapLabelText;

	[SerializeField]
	private ButtonColumnView viewResultsButtonColumn;

	[SerializeField]
	private Tooltip startGameButtonTooltip;

	private const string JOINING_TEXT = "JOINING...";

	private const string JOIN_TEXT = "JOIN";

	private const string LEAVE_TEXT = "SPECTATE";

	private const string NEXT_TEXT = "NEXT";

	private const string RESULTS_TEXT = "RESULTS";

	private const string START_TEXT = "START";

	private const string CONTINUE_TEXT = "CONTINUE";

	private const string START_TOOLTIP_END = " required to start";

	public bool CanStartGameEarly => NetworkedSingletonMonoBehaviour<GameManager>.Instance.allowDevsAndCommunityTeamToStartWhileWaitingForPlayers && (bool)Profiles.LocalProfile.Developer;

	public void SetGameModel(GameUIState state, GameUIDataModel model)
	{
		string text = ((model.RequiredTeamCount <= 1) ? string.Empty : (model.RequiredTeamCount + " teams of ")) + model.RequiredTeamSize + " player" + ((model.RequiredTeamSize <= 1) ? string.Empty : "s");
		switch (state)
		{
		case GameUIState.WAITING_FOR_PLAYERS:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: true);
			viewResultsButtonColumn.ButtonColumn.SetActive(model.SupportsPreviousGameResults);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "RESULTS";
			joinGameButtonColumn.ButtonColumn.SetActive(value: false);
			switchNextMapButtonColumn.ButtonColumn.SetActive(value: false);
			nextMapLabelColumn.SetActive(value: false);
			startGameButtonColumn.ButtonColumn.SetActive(value: true);
			startGameButtonColumn.Button.interactable = false;
			startGameButtonTooltip.enabled = true;
			startGameButtonTooltip.Message = text + " required to start";
			startOverGameButtonColumn.ButtonColumn.SetActive(value: false);
			startGameEarlyButton.gameObject.SetActive(CanStartGameEarly);
			switchTeamButtonColumn.ButtonColumn.SetActive(model.UseTeamSwitchButton);
			switchTeamButtonColumn.Button.interactable = model.LocalPlayer.CanSwitchTeams;
			break;
		case GameUIState.PRE_GAME:
			configRow.SetActive(value: false);
			configText.text = model.ModeName;
			buttonRow.SetActive(value: true);
			switchNextMapButtonColumn.ButtonColumn.SetActive(value: false);
			nextMapLabelColumn.SetActive(value: false);
			viewResultsButtonColumn.ButtonColumn.SetActive(model.SupportsPreviousGameResults);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "RESULTS";
			if (model.LocalPlayer.IsSpectator)
			{
				startGameButtonColumn.ButtonColumn.SetActive(value: false);
				startOverGameButtonColumn.ButtonColumn.SetActive(value: false);
				switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
				joinGameButtonColumn.ButtonColumn.SetActive(value: true);
				joinGameButtonColumn.Button.interactable = model.LocalPlayer.CanJoinGame;
				joinGameButtonColumn.ButtonText.text = "JOIN";
				break;
			}
			buttonRow.SetActive(value: true);
			joinGameButtonColumn.ButtonColumn.SetActive(model.LocalPlayer.CanLeaveGame);
			joinGameButtonColumn.Button.interactable = true;
			joinGameButtonColumn.ButtonText.text = "SPECTATE";
			startGameButtonColumn.ButtonColumn.SetActive(value: true);
			startGameButtonColumn.Button.interactable = model.LocalPlayer.CanStartGame;
			startGameButtonColumn.ButtonText.text = ((!model.CanContinue) ? "START" : "CONTINUE");
			startGameButtonTooltip.enabled = !model.LocalPlayer.CanStartGame;
			startGameButtonTooltip.Message = text + " required to start";
			startGameEarlyButton.gameObject.SetActive(CanStartGameEarly);
			startGameEarlyButton.interactable = !model.LocalPlayer.CanStartGame;
			startOverGameButtonColumn.ButtonColumn.SetActive(model.CanContinue);
			startOverGameButtonColumn.Button.interactable = model.LocalPlayer.CanStartGame || (bool)Profiles.LocalProfile.Developer;
			switchTeamButtonColumn.ButtonColumn.SetActive(model.UseTeamSwitchButton);
			switchTeamButtonColumn.Button.interactable = model.LocalPlayer.CanSwitchTeams;
			break;
		case GameUIState.GAME_STARTING:
			configRow.SetActive(value: true);
			configText.text = model.ModeName;
			buttonRow.SetActive(!model.LocalPlayer.IsSpectator);
			viewResultsButtonColumn.ButtonColumn.SetActive(value: false);
			startGameButtonColumn.ButtonColumn.SetActive(value: false);
			startOverGameButtonColumn.ButtonColumn.SetActive(value: false);
			joinGameButtonColumn.ButtonColumn.SetActive(value: false);
			switchNextMapButtonColumn.ButtonColumn.SetActive(value: false);
			nextMapLabelColumn.SetActive(value: false);
			switchTeamButtonColumn.ButtonColumn.SetActive(model.UseTeamSwitchButton);
			switchTeamButtonColumn.Button.interactable = false;
			break;
		case GameUIState.GAME_ON:
			configRow.SetActive(value: true);
			configText.text = model.ModeName;
			if (model.SupportsTeamSwitching && model.LocalPlayer.CanSwitchTeams)
			{
				buttonRow.SetActive(value: true);
				switchTeamButtonColumn.ButtonColumn.SetActive(model.UseTeamSwitchButton);
				switchTeamButtonColumn.Button.interactable = false;
			}
			else
			{
				buttonRow.SetActive(value: false);
			}
			break;
		case GameUIState.GAME_RUNNING:
			if (model.LocalPlayer.IsSpectator)
			{
				configRow.SetActive(value: false);
				buttonRow.SetActive(value: true);
				startGameButtonColumn.ButtonColumn.SetActive(value: false);
				startOverGameButtonColumn.ButtonColumn.SetActive(value: false);
				switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
				switchNextMapButtonColumn.ButtonColumn.SetActive(value: false);
				nextMapLabelColumn.SetActive(value: false);
				joinGameButtonColumn.ButtonColumn.SetActive(value: true);
				bool flag = model.SupportsJoinInProgress && model.LocalPlayer.CanJoinGame;
				joinGameButtonColumn.ButtonText.text = ((!flag) ? "JOIN" : "JOINING...");
				joinGameButtonColumn.Button.interactable = flag;
			}
			else
			{
				bool flag2 = string.IsNullOrEmpty(model.PresenceString);
				configRow.SetActive(!flag2);
				if (!flag2)
				{
					configText.text = model.PresenceString.ToUpper();
				}
				buttonRow.SetActive(value: false);
			}
			break;
		case GameUIState.GAME_OVER:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: false);
			break;
		case GameUIState.RESULTS_LOCKED:
		case GameUIState.RESULTS:
			configRow.SetActive(value: false);
			buttonRow.SetActive(value: true);
			joinGameButtonColumn.ButtonColumn.SetActive(value: false);
			startGameButtonColumn.ButtonColumn.SetActive(value: false);
			startOverGameButtonColumn.ButtonColumn.SetActive(value: false);
			switchTeamButtonColumn.ButtonColumn.SetActive(value: false);
			if (model.SupportsMapSwitching)
			{
				switchNextMapButtonColumn.ButtonColumn.SetActive(value: true);
				nextMapLabelColumn.SetActive(value: true);
				nextMapLabelText.text = "NEXT MAP: " + model.NextMapName.ToUpper();
			}
			else
			{
				switchNextMapButtonColumn.ButtonColumn.SetActive(value: false);
				nextMapLabelColumn.SetActive(value: false);
			}
			viewResultsButtonColumn.ButtonColumn.SetActive(state != GameUIState.RESULTS_LOCKED);
			viewResultsButtonColumn.Button.interactable = true;
			viewResultsButtonColumn.ButtonText.text = "NEXT";
			break;
		}
		ApplyColors(useHighlightAlpha: false);
	}
}
public class GameScoreboardHeaderView : ProjectorUIElementView
{
	[Header("Title")]
	[SerializeField]
	private Text titleText;

	[Header("Timer")]
	[SerializeField]
	private GameObject timerColumn;

	[SerializeField]
	private Text timerText;

	[Header("Subtitle")]
	[SerializeField]
	private GameObject subtitleRow;

	[SerializeField]
	private GameObject subtitleColumn;

	[SerializeField]
	private Text subtitleText;

	[Header("Subtitle Score")]
	[SerializeField]
	private GameObject subtitleScoreColumn;

	[SerializeField]
	private Text subtitleScoreText;

	[SerializeField]
	private UnityEngine.UI.Button modeToggleButton;

	[Header("Team Header")]
	[SerializeField]
	private GameScoreboardTeamHeaderView teamHeader;

	private const string PRE_GAME_TEXT = "PRE-GAME";

	private const string MATCHMAKING_TEXT = "LOOKING FOR PLAYERS";

	private const string GAME_STARTING_TEXT = "STARTING IN";

	private const string GAME_ON_TEXT = "GAME ON";

	private const string GAME_OVER_TEXT = "GAME OVER";

	private const string GAME_RUNNING_TEXT = "GAME IN PROGRESS";

	private const string POST_GAME_TEXT = "NEXT GAME IN";

	private const string POST_GAME_FOREVER_TEXT = "GAME OVER";

	private const string RESULTS_TEXT = "PREVIOUS RESULTS";

	private ElementColors _colors;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			teamHeader.Colors = _colors;
		}
	}

	public void SetTimerDataModel(GameUIState state, GameUITimerDataModel timerDataModel)
	{
		switch (state)
		{
		case GameUIState.PRE_GAME:
		case GameUIState.WAITING_FOR_PLAYERS:
			timerText.text = timerDataModel.GameDuration;
			break;
		case GameUIState.GAME_ON:
		case GameUIState.GAME_RUNNING:
		case GameUIState.GAME_OVER:
		case GameUIState.RESULTS:
			timerText.text = timerDataModel.GameTimeRemaining;
			break;
		case GameUIState.GAME_STARTING:
		case GameUIState.RESULTS_LOCKED:
			timerText.text = timerDataModel.GameStateTransitionTimeRemaining;
			break;
		}
	}

	public void SetGameModel(GameUIState state, GameUIDataModel model)
	{
		teamHeader.SetGameModel(state, model);
		switch (state)
		{
		case GameUIState.WAITING_FOR_PLAYERS:
			titleText.text = "LOOKING FOR PLAYERS";
			subtitleRow.SetActive(value: true);
			subtitleColumn.SetActive(value: true);
			subtitleScoreColumn.SetActive(value: true);
			subtitleText.text = model.ModeName.ToUpper();
			subtitleScoreText.text = model.WinCondition;
			if (modeToggleButton != null)
			{
				modeToggleButton.interactable = model.SupportsModeSwitching && model.LocalPlayer.CanChangeMode;
			}
			teamHeader.gameObject.SetActive(value: false);
			break;
		case GameUIState.PRE_GAME:
			titleText.text = "PRE-GAME";
			timerColumn.SetActive(value: true);
			subtitleRow.SetActive(value: true);
			subtitleColumn.SetActive(value: true);
			subtitleScoreColumn.SetActive(value: true);
			subtitleText.text = model.ModeName.ToUpper();
			subtitleScoreText.text = model.WinCondition;
			if (modeToggleButton != null)
			{
				modeToggleButton.interactable = model.SupportsModeSwitching && model.LocalPlayer.CanChangeMode;
			}
			teamHeader.gameObject.SetActive(value: false);
			break;
		case GameUIState.GAME_STARTING:
			titleText.text = "STARTING IN";
			timerColumn.SetActive(value: true);
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: false);
			break;
		case GameUIState.GAME_ON:
			titleText.text = "GAME ON";
			timerColumn.SetActive(value: false);
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: false);
			break;
		case GameUIState.GAME_RUNNING:
			titleText.text = "GAME IN PROGRESS";
			timerColumn.SetActive(value: true);
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: true);
			break;
		case GameUIState.GAME_OVER:
			titleText.text = "GAME OVER";
			timerColumn.SetActive(value: false);
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: true);
			break;
		case GameUIState.RESULTS_LOCKED:
			if (model.StaysInPostGameForever)
			{
				titleText.text = "GAME OVER";
				timerColumn.SetActive(value: false);
			}
			else
			{
				titleText.text = "NEXT GAME IN";
				timerColumn.SetActive(value: true);
			}
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: true);
			break;
		case GameUIState.RESULTS:
			titleText.text = "PREVIOUS RESULTS";
			timerColumn.SetActive(value: true);
			subtitleRow.SetActive(value: false);
			teamHeader.gameObject.SetActive(value: true);
			break;
		}
		ApplyColors(useHighlightAlpha: false);
	}
}
public class GameScoreboardPlayerRowView : ProjectorUIElementView
{
	[Header("Stat Columns")]
	[SerializeField]
	private GameScoreboardPlayerStatColumnView statColumnPrefab;

	[SerializeField]
	private int maxStatColumnCount = 4;

	[SerializeField]
	private Text nameText;

	[SerializeField]
	private LayoutElement layoutElement;

	private GameScoreboardPlayerStatColumnView[] statColumns = new GameScoreboardPlayerStatColumnView[0];

	[NonSerialized]
	public GameScoreboardTeamRowView GameScoreboardTeamRowView;

	private ElementColors _colors;

	public Text NameText => nameText;

	public LayoutElement LayoutElement => layoutElement;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			for (int i = 0; i < statColumns.Length; i++)
			{
				statColumns[i].Colors = _colors;
			}
		}
	}

	public void SetPlayerModel(GameUIState state, GameUIPlayerDataModel playerModel, bool supportsScore, bool supportsRank, bool[] hidePlayerStatsInUI)
	{
		bool flag = state == GameUIState.GAME_OVER || state == GameUIState.RESULTS || state == GameUIState.RESULTS_LOCKED;
		bool flag2 = flag || state == GameUIState.GAME_RUNNING;
		bool flag3 = supportsScore && flag2;
		bool flag4 = supportsRank && flag;
		bool flag5 = flag3 || flag4;
		nameText.text = ((!playerModel.Active) ? string.Empty : playerModel.Name.ToUpper());
		int i = 0;
		int num = -1;
		if (flag2)
		{
			for (; i < playerModel.StatCount && i < statColumns.Length; i++)
			{
				bool flag6 = !hidePlayerStatsInUI[i];
				statColumns[i].gameObject.SetActive(flag6);
				if (flag6)
				{
					statColumns[i].SetStatModel(playerModel.Stats[i], playerModel.Active, playerModel.IsLocal);
					statColumns[i].SetSize(GameScoreboardPlayerStatColumnView.Size.SMALL);
					num = i;
				}
			}
		}
		if (num >= 0 && !flag5)
		{
			statColumns[num].SetSize(GameScoreboardPlayerStatColumnView.Size.LARGE);
		}
		for (; i < statColumns.Length; i++)
		{
			statColumns[i].gameObject.SetActive(value: false);
		}
		ApplyColors(playerModel.Active && playerModel.IsLocal);
	}

	protected override void Awake()
	{
		base.Awake();
		statColumns = new GameScoreboardPlayerStatColumnView[maxStatColumnCount];
		for (int i = 0; i < maxStatColumnCount; i++)
		{
			statColumns[i] = UnityEngine.Object.Instantiate(statColumnPrefab);
			statColumns[i].transform.SetParent(base.transform, worldPositionStays: false);
			statColumns[i].gameObject.SetActive(value: false);
		}
	}
}
