public class GameScoreboardTeamRowView : ProjectorUIElementView
{
	[Header("Player Rows")]
	[SerializeField]
	private GameScoreboardPlayerRowView playerRowPrefab;

	[SerializeField]
	private Transform playerRowRoot;

	[SerializeField]
	private UnityEngine.UI.Button joinTeamButton;

	[Header("Score")]
	[SerializeField]
	private Text scoreText;

	[SerializeField]
	private GameObject scoreColumn;

	[SerializeField]
	private Text rankText;

	private List<GameScoreboardPlayerRowView> toDestroy = new List<GameScoreboardPlayerRowView>();

	[NonSerialized]
	public List<GameScoreboardPlayerRowView> PlayerRows = new List<GameScoreboardPlayerRowView>();

	private GameScoreboardView gameScoreboardView;

	private GameTeam cachedGameTeam = GameTeam.ANY;

	private ElementColors _colors;

	public override ElementColors Colors
	{
		get
		{
			return _colors;
		}
		set
		{
			_colors = value;
			for (int i = 0; i < PlayerRows.Count; i++)
			{
				PlayerRows[i].Colors = _colors;
			}
		}
	}

	public int ActivePlayerRowCount { get; private set; }

	public GameScoreboardPlayerRowView GetPlayerRow(int index)
	{
		return (index >= PlayerRows.Count) ? null : PlayerRows[index];
	}

	public void SetTeamModel(GameUIState state, GameUIDataModel model, GameUITeamDataModel teamModel, bool supportsScore, bool supportsRank, bool[] hideStatsInUI)
	{
		bool flag = supportsScore && (state == GameUIState.GAME_RUNNING || state == GameUIState.GAME_OVER || state == GameUIState.RESULTS || state == GameUIState.RESULTS_LOCKED);
		bool flag2 = supportsRank && (state == GameUIState.GAME_OVER || state == GameUIState.RESULTS || state == GameUIState.RESULTS_LOCKED);
		scoreColumn.SetActive(flag || flag2);
		scoreText.transform.parent.gameObject.SetActive(flag);
		scoreText.text = ((!teamModel.Active) ? "-" : teamModel.Score.ToString());
		rankText.transform.parent.gameObject.SetActive(flag2);
		rankText.text = ((!teamModel.Active) ? string.Empty : teamModel.Rank);
		ActivePlayerRowCount = teamModel.PlayerModels.Length;
		toDestroy.Clear();
		bool flag3 = state == GameUIState.WAITING_FOR_PLAYERS || (!model.LocalPlayer.IsSpectator && state == GameUIState.PRE_GAME);
		bool flag4 = NetworkedSingletonMonoBehaviour<GameManager>.Instance == null || NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetPlayerTeam(PhotonNetwork.player) == teamModel.GameTeam;
		joinTeamButton.gameObject.SetActive(model.UseTeamJoinButton && flag3 && !flag4);
		joinTeamButton.interactable = model.LocalPlayer.CanSwitchTeams && NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.GetTeamVacancy(teamModel.GameTeam) > 0;
		for (int i = 0; i < ActivePlayerRowCount || i < PlayerRows.Count; i++)
		{
			if (i >= ActivePlayerRowCount && i < PlayerRows.Count)
			{
				toDestroy.Add(PlayerRows[i]);
				continue;
			}
			GameScoreboardPlayerRowView gameScoreboardPlayerRowView = ((i < PlayerRows.Count) ? PlayerRows[i] : CreatePlayerRow());
			gameScoreboardPlayerRowView.Colors = Colors;
			gameScoreboardPlayerRowView.SetPlayerModel(state, teamModel.PlayerModels[i], supportsScore, supportsRank, hideStatsInUI);
		}
		for (int j = 0; j < toDestroy.Count; j++)
		{
			GameScoreboardPlayerRowView gameScoreboardPlayerRowView2 = toDestroy[j];
			UnityEngine.Object.Destroy(gameScoreboardPlayerRowView2.gameObject);
			PlayerRows.Remove(gameScoreboardPlayerRowView2);
		}
		cachedGameTeam = teamModel.GameTeam;
		ApplyColors(teamModel.IsLocal);
	}

	public void ClickJoinTeamButton()
	{
		gameScoreboardView.Button_JoinTeam(cachedGameTeam);
	}

	protected override void Awake()
	{
		base.Awake();
		gameScoreboardView = GetComponentInParent<GameScoreboardView>();
	}

	private GameScoreboardPlayerRowView CreatePlayerRow()
	{
		GameScoreboardPlayerRowView gameScoreboardPlayerRowView = UnityEngine.Object.Instantiate(playerRowPrefab);
		gameScoreboardPlayerRowView.transform.SetParent(playerRowRoot, worldPositionStays: false);
		gameScoreboardPlayerRowView.GameScoreboardTeamRowView = this;
		PlayerRows.Add(gameScoreboardPlayerRowView);
		return gameScoreboardPlayerRowView;
	}
}
public class GameScoreboardView : GameUIView
{
