		this.dataModel = dataModel;
		isDirty = true;
	}

	public override void SetTimerDataModel(GameUIState state, GameUITimerDataModel timerDataModel)
	{
		header.SetTimerDataModel(state, timerDataModel);
	}

	private void UpdateView()
	{
		if (isDirty && initialized)
		{
			if (thisRaycaster != null)
			{
				thisRaycaster.enabled = state == GameUIState.PRE_GAME || state == GameUIState.GAME_STARTING || state == GameUIState.WAITING_FOR_PLAYERS || state == GameUIState.RESULTS || (state == GameUIState.RESULTS_LOCKED && dataModel.SupportsMapSwitching) || (state == GameUIState.GAME_RUNNING && dataModel.LocalPlayer.IsSpectator);
			}
			header.SetGameModel(state, dataModel);
			footer.SetGameModel(state, dataModel);
			body.SetGameModel(state, dataModel);
			isDirty = false;
		}
	}
