public class ScoreboardPagedGrid : VirtualPagedGrid<GameScoreboardTeamRowView>
{
	[SerializeField]
	private LayoutElement layoutExpander;

	public void SetTeamRows(List<GameScoreboardTeamRowView> teamRowViews)
	{
		base.SetAllActiveChildren(teamRowViews, resetPage: false);
	}

	public override void UpdateGrid()
	{
		List<GameScoreboardPlayerRowView> list = new List<GameScoreboardPlayerRowView>();
		for (int i = 0; i < base.AllActiveChildren.Count; i++)
		{
			for (int j = 0; j < base.AllActiveChildren[i].ActivePlayerRowCount; j++)
			{
				list.Add(base.AllActiveChildren[i].PlayerRows[j]);
			}
		}
		int count = list.Count;
		if (emptyDisplay != null)
		{
			emptyDisplay.SetActive(count == 0);
			gridBaseTransform.gameObject.SetActive(count != 0);
		}
		if (nonEmptyInfoText != null)
		{
			nonEmptyInfoText.SetActive(count > 0);
		}
		base.TotalPages = ((count == 0) ? 1 : ((count + base.PageSize - 1) / base.PageSize));
		SetCurrentPage(Mathf.Clamp(base.CurrentPage, 0, base.TotalPages - 1), updateGrid: false);
		int skip = base.CurrentPage * base.PageSize;
		pageControls.gameObject.SetActive(base.TotalPages > 1);
		base.PreviousPageButton.interactable = base.CurrentPage > 0;
		base.NextPageButton.interactable = base.CurrentPage < base.TotalPages - 1;
		if (pageDisplay != null)
		{
			pageDisplay.UpdatePageDisplay(base.CurrentPage, base.TotalPages);
		}
		float num = ((RectTransform)base.transform).sizeDelta.y / (float)base.PageSize;
		List<GameScoreboardPlayerRowView> list2 = list.SkipTake(skip, base.PageSize).ToList();
		bool flag = list2.Count == base.PageSize;
		if (!flag)
		{
			int num2 = base.PageSize - list2.Count;
			layoutExpander.preferredHeight = (float)num2 * num;
			layoutExpander.transform.SetAsLastSibling();
		}
		layoutExpander.gameObject.SetActive(!flag);
		List<GameScoreboardTeamRowView> list3 = list2.Select((GameScoreboardPlayerRowView apr) => apr.GameScoreboardTeamRowView).Distinct().ToList();
		for (int num3 = 0; num3 < list.Count; num3++)
		{
			bool active = list2.Contains(list[num3]);
			list[num3].gameObject.SetActive(active);
			list[num3].LayoutElement.minHeight = num;
		}
		for (int num4 = 0; num4 < base.AllActiveChildren.Count; num4++)
		{
			bool active2 = list3.Contains(base.AllActiveChildren[num4]);
			base.AllActiveChildren[num4].gameObject.SetActive(active2);
		}
		LayoutRebuilder.MarkLayoutForRebuild(gridBaseTransform);
		LayoutRebuilder.MarkLayoutForRebuild((RectTransform)pageControls.transform);
	}
}
namespace RecRoom.Core
{
	public class ScreenHUD : UnityEngine.MonoBehaviour
	{
		public enum CrosshairTickMasks
		{
			TOP = 2,
			BOTTOM = 4,
			LEFT = 8,
			RIGHT = 16,
			LEFT_AND_RIGHT = 24,
			TOP_AND_BOTTOM = 6,
			ALL = 30
		}

		private enum CrosshairTicks
		{
			TOP = 1,
			BOTTOM,
			LEFT,
			RIGHT
		}

		public struct DialogContent
		{
			public readonly Sprite sprite;

			public readonly string text;

			public DialogContent(Sprite sprite, string text)
			{
				this.sprite = sprite;
				this.text = text;
			}
		}

		[Serializable]
		private class Dialog
		{
			public RectTransform Root;

			public UnityEngine.UI.Image Icon;

			public Text Text;

			public UnityEngine.UI.Image ProgressVisual;

			public RectTransform HighlightCard;

			public bool IsEnabled => Root.gameObject.activeSelf;

			public void Enable()
			{
				if (!Root.gameObject.activeSelf)
				{
					Root.gameObject.SetActive(value: true);
				}
			}

			public void Disable()
			{
				if (Root.gameObject.activeSelf)
				{
					Root.gameObject.SetActive(value: false);
				}
				SetProgress(0f);
				EnableHighlight(enable: false);
			}

			public void SetPosition(Vector2 anchoredPosition)
			{
				if (Root.anchoredPosition != anchoredPosition)
				{
					Root.anchoredPosition = anchoredPosition;
				}
			}

			public void EnableHighlight(bool enable)
			{
				if (HighlightCard != null && HighlightCard.gameObject.activeSelf != enable)
				{
					HighlightCard.gameObject.SetActive(enable);
				}
			}

			public void SetContent(DialogContent content, float progress = 0f)
			{
				if (Icon.sprite != content.sprite)
				{
					Icon.sprite = content.sprite;
				}
				if (Text.text != content.text)
				{
					Text.text = content.text;
				}
				SetProgress(progress);
			}

			private void SetProgress(float progress)
			{
				if (!(ProgressVisual != null))
				{
					return;
				}
				if (progress == 0f)
				{
					if (ProgressVisual.gameObject.activeSelf)
					{
						ProgressVisual.gameObject.SetActive(value: false);
					}
					return;
				}
				if (!ProgressVisual.gameObject.activeSelf)
				{
					ProgressVisual.gameObject.SetActive(value: true);
				}
				Color color = ProgressVisual.color;
				color.a = progress;
				ProgressVisual.color = color;
			}
		}

