		public void EnableCrosshair(CrosshairTickMasks ticksEnabledMask)
		{
			if (!IsCrosshairEnabled)
			{
				crosshairRoot.gameObject.SetActive(base.enabled);
				if (base.enabled)
				{
					EnableCrosshairTick(topTickRoot, ticksEnabledMask, CrosshairTicks.TOP);
					EnableCrosshairTick(bottomTickRoot, ticksEnabledMask, CrosshairTicks.BOTTOM);
					EnableCrosshairTick(leftTickRoot, ticksEnabledMask, CrosshairTicks.LEFT);
					EnableCrosshairTick(rightTickRoot, ticksEnabledMask, CrosshairTicks.RIGHT);
				}
			}
		}

		private void EnableCrosshairTick(RectTransform tickTransform, CrosshairTickMasks mask, CrosshairTicks tickType)
		{
			int num = 1 << (int)tickType;
			tickTransform.gameObject.SetActive(((uint)num & (uint)mask) == (uint)num);
		}

