		{
			toolActionRoot.gameObject.SetActive(value: true);
			int num = -1;
			for (int i = 0; i < toolActionDialogs.Length; i++)
			{
				if (!toolActionDialogs[i].IsEnabled)
				{
					num = i;
					break;
