		public void EnableTutorialDialog(Vector2 viewportPosition, DialogContent content)
		{
			tutorialDialogs[0].Enable();
			tutorialDialogs[0].SetContent(content);
			for (int i = 1; i < tutorialDialogs.Length; i++)
			{
				tutorialDialogs[i].Disable();
			}
			if (!tutorialDialogRoot.gameObject.activeSelf)
			{
				tutorialDialogRoot.gameObject.SetActive(value: true);
			}
			SetViewportPosition(tutorialDialogRoot, viewportPosition, dialogSafezoneSize);
		}

		public void EnableTutorialDialog(Vector2 viewportPosition, List<DialogContent> contentList)
		{
			int num = Mathf.Min(contentList.Count, tutorialDialogs.Length);
			if (num < 1)
			{
				return;
			}
			for (int i = 0; i < tutorialDialogs.Length; i++)
			{
				if (i < num)
				{
					tutorialDialogs[i].Enable();
					tutorialDialogs[i].SetContent(contentList[i]);
				}
				else
				{
					tutorialDialogs[i].Disable();
				}
			}
			if (!tutorialDialogRoot.gameObject.activeSelf)
			{
				tutorialDialogRoot.gameObject.SetActive(value: true);
			}
			SetViewportPosition(tutorialDialogRoot, viewportPosition, dialogSafezoneSize);
		}

		public void DisableTutorialDialog()
		{
			Dialog[] array = tutorialDialogs;
			foreach (Dialog dialog in array)
			{
				dialog.Disable();
			}
			if (tutorialDialogRoot.gameObject.activeSelf)
			{
				tutorialDialogRoot.gameObject.SetActive(value: false);
			}
		}

		public void EnableCreationOverlay()
		{
			if (!creationOverlayRoot.gameObject.activeSelf)
			{
				creationOverlayRoot.gameObject.SetActive(value: true);
			}
		}

		public void DisableCreationOverlay()
		{
			if (creationOverlayRoot.gameObject.activeSelf)
			{
				creationOverlayRoot.gameObject.SetActive(value: false);
			}
		}

		public void SetCreationOverlayActionLabel(string label)
		{
			if (creationOverlayLabel.text != label)
			{
				creationOverlayLabel.text = label;
			}
		}

		public void ClearCreationOverlayActionDialogs()
		{
			for (int i = 0; i < creationOverlayActionDialogs.Length; i++)
			{
				creationOverlayActionDialogs[i].Disable();
			}
		}

		public void AddCreationOverlayActionDialog(Sprite icon, string text)
		{
			AddCreationOverlayActionDialog(new DialogContent(icon, text));
		}

		public void AddCreationOverlayActionDialog(DialogContent content)
		{
			int num = -1;
			for (int i = 0; i < creationOverlayActionDialogs.Length; i++)
			{
				if (!creationOverlayActionDialogs[i].IsEnabled)
				{
					num = i;
					break;
				}
			}
			if (num >= 0)
			{
				creationOverlayActionDialogs[num].Enable();
				creationOverlayActionDialogs[num].SetContent(content);
			}
		}

		public void ClearCreationOverlayControlsDialogs()
		{
			for (int i = 0; i < creationOverlayControlsDialogs.Length; i++)
			{
				creationOverlayControlsDialogs[i].Disable();
			}
		}

		public void AddCreationOverlayControlsDialog(Sprite icon, string text)
		{
			AddCreationOverlayControlsDialog(new DialogContent(icon, text));
		}

		public void AddCreationOverlayControlsDialog(DialogContent content)
		{
			int num = -1;
			for (int i = 0; i < creationOverlayControlsDialogs.Length; i++)
			{
				if (!creationOverlayControlsDialogs[i].IsEnabled)
				{
					num = i;
					break;
				}
			}
			if (num >= 0)
			{
				creationOverlayControlsDialogs[num].Enable();
				creationOverlayControlsDialogs[num].SetContent(content);
			}
		}

		private void ResetDialog(Dialog dialog, Vector2 positionViewportSpace, Vector2 safezoneSizeViewportSpace, DialogContent content, float progress = 0f)
		{
			dialog.Enable();
			Vector2 anchoredPositionFromViewportPosition = GetAnchoredPositionFromViewportPosition(positionViewportSpace, safezoneSizeViewportSpace);
			dialog.SetPosition(anchoredPositionFromViewportPosition);
			dialog.SetContent(content, progress);
		}

		private void SetViewportPosition(RectTransform rectTransform, Vector2 positionViewportSpace, Vector2 safezoneSizeViewportSpace)
		{
			Vector2 anchoredPositionFromViewportPosition = GetAnchoredPositionFromViewportPosition(positionViewportSpace, safezoneSizeViewportSpace);
			if (rectTransform.anchoredPosition != anchoredPositionFromViewportPosition)
			{
				rectTransform.anchoredPosition = anchoredPositionFromViewportPosition;
			}
		}

		private Vector2 GetAnchoredPositionFromViewportPosition(Vector2 positionViewportSpace, Vector2 safezoneSizeViewportSpace)
		{
			Vector2 vector = safezoneSizeViewportSpace / 2f;
			Vector2 vector2 = new Vector2(0.5f, 0.5f);
			Vector2 vector3 = vector2 - vector;
			Vector2 vector4 = vector2 + vector;
			positionViewportSpace = new Vector2(Mathf.Clamp(positionViewportSpace.x, vector3.x, vector4.x), Mathf.Clamp(positionViewportSpace.y, vector3.y, vector4.y));
			Vector2 sizeDelta = canvasRect.sizeDelta;
			return new Vector2(positionViewportSpace.x * sizeDelta.x, positionViewportSpace.y * sizeDelta.y);
		}

		private Vector2 GetViewportPosition(RectTransform rectTransform)
		{
			Vector2 sizeDelta = canvasRect.sizeDelta;
			Vector2 anchoredPosition = rectTransform.anchoredPosition;
			return new Vector2(anchoredPosition.x / sizeDelta.x, anchoredPosition.y / sizeDelta.y);
		}
	}
}
namespace RecRoom.UI
