	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Menu Controllers/Emote Radial Menu Screen Controller", fileName = "EmoteRadialMenuScreenController")]
	public class EmoteRadialMenuScreenController : ScreenMenuController
	{
		[SerializeField]
		private EmoteRadialMenuContainer menuContainerPrefab;

		[SerializeField]
		private ScreenPlayerCursorSettings cursorSettings;

		[SerializeField]
		private float minMouseCursorDeadzone = 0.1f;

		[SerializeField]
		private float minCursorAxisDeadzone = 0.8f;

		[SerializeField]
		private float deadzoneExitSlopTime = 0.33f;

		[SerializeField]
		private float delayOpenIfQTEContext = 0.5f;

		[SerializeField]
		private float verticalBufferPercentage = 8f;

		private EmoteRadialMenuContainer menuContainer;

		private ScreenPlayerController cachedPlayerController;

		private Player cachedPlayer;

		private Vector2 totalMouseDelta;

		private float lastValidInputTime;

		private float lastValidInputAngle;

		private float delayedTimePassed;

		public override bool AllowsPlayerWalking => false;

		public override bool HasPlayerAnimation => false;

		public override void Initialize(ScreenPlayerController playerController)
		{
			menuContainer = UnityEngine.Object.Instantiate(menuContainerPrefab, SingletonMonoBehaviour<LocalPlayerController>.Instance.transform);
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override bool CanOpen(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (menuContainer.IsOpen || menuContainer.IsOpening || input.ChatButtonDown || player.ChatMenuRequested)
			{
				return true;
			}
			return false;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			cachedPlayer = player;
			cachedPlayerController = playerController;
			totalMouseDelta = Vector2.zero;
			playerController.CursorSystem.SetCursorSettings(hud, cursorSettings);
			playerController.CursorSystem.SnapToCenter(hud);
			if (input.UsingKeyboardMouse)
			{
				playerController.CursorSystem.ShowCursor(hud);
			}
			else
			{
				playerController.CursorSystem.HideCursor(hud);
			}
			menuContainer.Menu.EnableChatButton(!Profiles.LocalProfile.IsJunior());
			menuContainer.Menu.ChatEmoteRequestedEvent += OnChatEmoteRequested;
			menuContainer.Menu.EmoteRequestedEvent += OnEmoteRequested;
			menuContainer.Menu.PartyUpRequestedEvent += OnPartyUpRequested;
			menuContainer.Menu.FirstFlowIsChatMenu = input.ChatButtonDown || player.ChatMenuRequested;
			menuContainer.Open();
			hud.WorldSpaceUIAnchor.Attach(menuContainer.Menu, verticalBufferPercentage, resetPositionOnDetach: false);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (input.CancelButtonDown && !menuContainer.IsClosing)
			{
				menuContainer.Close();
			}
			if (!menuContainer.IsOpen && !menuContainer.IsOpening)
			{
				return false;
			}
			cachedPlayerController = playerController;
			cachedPlayer = player;
			if (menuContainer.Menu.IsInCursorFlow)
			{
				if (!playerController.CursorSystem.IsCursorEnabled(hud))
				{
					playerController.CursorSystem.ShowCursor(hud);
				}
			}
			else
			{
				if (playerController.CursorSystem.IsCursorEnabled(hud))
				{
					playerController.CursorSystem.HideCursor(hud);
				}
				UpdateRadialButtons(camera, input);
			}
			return true;
		}

		public override void OnLateUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud)
		{
			menuContainer.Menu.ChatEmoteRequestedEvent -= OnChatEmoteRequested;
			menuContainer.Menu.EmoteRequestedEvent -= OnEmoteRequested;
			menuContainer.Menu.PartyUpRequestedEvent -= OnPartyUpRequested;
			hud.WorldSpaceUIAnchor.Detach();
			if (player != null)
			{
				player.ChatMenuRequested = false;
			}
			if (!menuContainer.IsClosing)
			{
				menuContainer.Close();
			}
		}

		private void UpdateRadialButtons(Camera camera, ScreenInputHandler input)
		{
			if (menuContainer.IsClosing)
			{
				return;
			}
			bool flag = false;
			float num = 0f;
			if (input.UsingKeyboardMouse)
			{
				totalMouseDelta += input.CursorMouseDeltaScreenPosition;
				flag = totalMouseDelta.sqrMagnitude <= minMouseCursorDeadzone * minMouseCursorDeadzone;
				if (!flag)
				{
					num = Vector2.SignedAngle(Vector2.up, totalMouseDelta);
				}
			}
			else
			{
				flag = input.CursorAxis.sqrMagnitude <= minCursorAxisDeadzone * minCursorAxisDeadzone;
				if (!flag)
				{
					num = Vector2.SignedAngle(Vector2.up, input.CursorAxis);
				}
			}
			if (num < 0f)
			{
				num += 360f;
			}
			if (!flag)
			{
				lastValidInputTime = UnityEngine.Time.time;
				lastValidInputAngle = num;
			}
			if (flag && !input.UsingKeyboardMouse && UnityEngine.Time.time - lastValidInputTime <= deadzoneExitSlopTime)
			{
				flag = false;
				num = lastValidInputAngle;
			}
		}

		private void OnChatEmoteRequested(string message)
		{
			cachedPlayer.EmotesManager.SendChatEmote(message);
		}

		private void OnEmoteRequested(ScreenPlayerEmote emote)
		{
			if (emote != null)
			{
				cachedPlayerController.EmoteSystem.QueueEmote(emote);
			}
		}

		private void OnPartyUpRequested()
		{
			cachedPlayer.PlayerParty.IsWaitingtoJoinAParty = !cachedPlayer.PlayerParty.IsWaitingtoJoinAParty;
		}
	}
}
namespace RecRoom.Tools
{
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Tool Controllers/Tool Menu Screen Controller", fileName = "ToolMenuScreenController")]
	public class ToolMenuScreenController : ScreenToolController
	{
		[SerializeField]
		private ScreenPlayerCursorSettings cursorSettings;

		[SerializeField]
		private float verticalBufferPercentage = 8f;

		private int stateEnteredFrameCount;

		public override bool PlayerMovementAllowed
		{
			[CompilerGenerated]
			get
			{
				return false;
			}
		}

		public override bool IsBlockingOthers
		{
			[CompilerGenerated]
			get
			{
				return true;
			}
		}

		public override bool IsBlockingSelf
		{
			[CompilerGenerated]
			get
			{
				return true;
			}
		}

		public override bool TryGetRequiredControlType(out ScreenPlayerController.ScreenPlayerGenreType requiredControlType)
		{
			requiredControlType = ScreenPlayerController.ScreenPlayerGenreType.INVALID;
			return false;
		}

		public override void OnToolPickup(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			if (tool.MenuProjector != null)
			{
				tool.MenuProjector.GazeOpenSupported = false;
			}
			playerController.AddMenuOpeningRestriction(this);
		}

		public override void OnToolRelease(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
			if (tool != null && tool.MenuProjector != null)
			{
				tool.MenuProjector.GazeOpenSupported = true;
			}
			playerController.RemoveMenuOpeningRestriction(this);
		}

		public override bool CanStart(ScreenPlayerController playerController, Player player, Tool tool, ScreenInputHandler input)
		{
			return tool.Menu != null && input.MenuButtonDown;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			stateEnteredFrameCount = UnityEngine.Time.frameCount;
			tool.MenuProjector.DismissMenuWhenNotGazing = false;
			tool.MenuProjector.IsMenuVisible = true;
			playerController.CursorSystem.SetCursorSettings(hud, cursorSettings);
			playerController.CursorSystem.SnapToCenter(hud);
			hud.WorldSpaceUIAnchor.Attach(tool.Menu, verticalBufferPercentage, resetPositionOnDetach: false);
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
			if (UnityEngine.Time.frameCount > stateEnteredFrameCount && (input.MenuButtonDown || input.CancelButtonDown))
			{
				return false;
			}
			if (!tool.IsHeld)
			{
				return false;
			}
			bool isOverTarget = UpdateMenuInput(playerController, camera, input);
			UpdateCursorPosition(playerController, camera, hud, input, isOverTarget);
			return true;
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, Tool tool, ScreenHUD hud)
		{
			if (tool != null)
			{
				tool.MenuProjector.IsMenuVisible = false;
				tool.MenuProjector.DismissMenuWhenNotGazing = true;
			}
			hud.WorldSpaceUIAnchor.Detach();
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void UpdateCursor(ScreenPlayerController playerController, Player player, Tool tool, ScreenHUD hud)
		{
		}

		public override void OnAnimationEvent(PlayerAnimationEvent.AnimationEventType animationEvent, Vector3 leftHandVelocity, Vector3 rightHandVelocity, ScreenPlayerController playerController, Player player, Camera camera, Tool tool)
		{
		}

		private bool UpdateMenuInput(ScreenPlayerController playerController, Camera camera, ScreenInputHandler input)
		{
			Ray ray = playerController.CursorSystem.GetRay(camera);
			UIInputModule.Instance.GetNewResults(0, uiInteractionEnabled: true, ray.origin, ray.direction, float.MaxValue, 0f, testAngleFromHead: false, out var result);
			UIInputModule.Instance.SendButtonInput(0, input.CursorButtonDown, input.CursorButtonUp);
			return result.UISelectable;
		}

		private void UpdateCursorPosition(ScreenPlayerController playerController, Camera camera, ScreenHUD hud, ScreenInputHandler input, bool isOverTarget)
		{
			bool gameViewFocused = SingletonMonoBehaviour<LocalPlayerController>.Instance.GameViewFocused;
			if (input.UsingKeyboardMouse)
			{
				playerController.CursorSystem.SetCursorScreenPosition(hud, camera, gameViewFocused, input.CursorMouseScreenPosition);
			}
			else
			{
				playerController.CursorSystem.AccelerateCursor(hud, input.CursorAxis, gameViewFocused, isOverTarget);
			}
		}
	}
}
namespace RecRoom.UI
{
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Menu Controllers/Watch Menu Screen Controller", fileName = "WatchMenuScreenController")]
	public class WatchMenuScreenController : ScreenMenuController
	{
		[SerializeField]
		private ScreenPlayerCursorSettings cursorSettings;

		[SerializeField]
		private float verticalBufferPercentage = 8f;

		[SerializeField]
		private PlayerAnimation playerAnimation;

		[SerializeField]
		private bool closeRequested;

		public override bool AllowsPlayerWalking => false;

		public override bool HasPlayerAnimation => true;

		public override void Initialize(ScreenPlayerController playerController)
		{
		}

		public override void TryAddTooltip(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			Player lockedOnPlayer = GetLockedOnPlayer(playerController);
			if (lockedOnPlayer != null)
			{
				hud.AddToolActionDialog(input.MenuButtonSprite, "View Profile");
			}
		}

		public override bool CanOpen(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			return player.PlayerUI.WatchMenuProjector.IsMenuOpen || input.MenuButtonDown;
		}

		public override void OnStart(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			closeRequested = false;
			playerController.PlayLoopingAnimation(playerAnimation);
			playerController.CursorSystem.SetCursorSettings(hud, cursorSettings);
			playerController.CursorSystem.SnapToCenter(hud);
			if (player != null && player.Backpack != null)
			{
				player.Backpack.BackpackToolEnabledChange += OnBackpackToolEnableChange;
			}
			player.PlayerUI.WatchMenuProjector.HideProjectionVisuals(this);
			if (!player.PlayerUI.WatchMenuProjector.IsMenuOpen)
			{
				player.PlayerUI.WatchMenuProjector.AuthorityOpenMenuDetached(force: true);
			}
			hud.WorldSpaceUIAnchor.Attach(player.PlayerUI.WatchMenu, verticalBufferPercentage, resetPositionOnDetach: false);
			Player lockedOnPlayer = GetLockedOnPlayer(playerController);
			if (lockedOnPlayer != null)
			{
				PlayerDetailsWatchUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<PlayerDetailsWatchUIFlow>();
				flowByType.SetPlayer(lockedOnPlayer);
				player.PlayerUI.WatchMenu.PushFlow(flowByType);
			}
		}

		public override bool OnUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
			if (input.CancelButtonDown)
			{
				if (player.PlayerUI.WatchMenu.FlowStackCount <= 1)
				{
					return false;
				}
				player.PlayerUI.WatchMenu.PopFlow();
			}
			if (closeRequested || input.MenuButtonDown || !player.PlayerUI.WatchMenuProjector.IsMenuOpen)
			{
				return false;
			}
			return true;
		}

		public override void OnLateUpdate(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud, ScreenInputHandler input)
		{
		}

		public override void OnStop(ScreenPlayerController playerController, Player player, Camera camera, ScreenHUD hud)
		{
			hud.WorldSpaceUIAnchor.Detach();
			if (player != null)
			{
				if (player.Backpack != null)
				{
					player.Backpack.BackpackToolEnabledChange -= OnBackpackToolEnableChange;
				}
				if (player.PlayerUI.WatchMenuProjector.IsMenuOpen)
				{
					player.PlayerUI.WatchMenuProjector.AuthorityCloseMenu();
				}
				player.PlayerUI.WatchMenuProjector.ShowProjectionVisuals(this);
			}
		}

		private void OnBackpackToolEnableChange(Tool tool, PlayerBackpackToolType toolType, bool isEnabled)
		{
			if (isEnabled)
			{
				closeRequested = true;
			}
		}

		private Player GetLockedOnPlayer(ScreenPlayerController playerController)
		{
			SocialScreenPlayerGenre genreController = playerController.GetGenreController<SocialScreenPlayerGenre>(ScreenPlayerController.ScreenPlayerGenreType.SOCIAL);
			return (!(genreController != null)) ? null : genreController.LockedOnPointOfInterestPlayer;
		}
	}
