			}
			container.Close();
		}

		private void OnChatEmoteSelected(string message)
		{
			if (this.ChatEmoteRequestedEvent != null)
			{
				this.ChatEmoteRequestedEvent(message);
			}
			container.Close();
		}

		private void OnPartyUpEmoteSelected()
		{
			if (this.PartyUpRequestedEvent != null)
			{
				this.PartyUpRequestedEvent();
			}
			container.Close();
		}
	}
}
public class EmoteRadialMenuButton : UnityEngine.MonoBehaviour
{
