namespace RecRoom.UI
{
	public class EmoteRadialMenuContainer : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Animator animator;

		[SerializeField]
		[Autofill(AutofillType.SelfAndChildren, false)]
		private EmoteRadialMenu menu;

		private Coroutine delayedOpenCloseCoroutine;

		public EmoteRadialMenu Menu => menu;

		public bool IsOpen { get; private set; }

		public bool IsOpening => delayedOpenCloseCoroutine != null && !IsOpen;

		public bool IsClosing => delayedOpenCloseCoroutine != null && IsOpen;

		private void Awake()
		{
			IsOpen = true;
			Close();
		}

		public void Open()
		{
			if (!IsOpen && !IsOpening)
			{
				StartDelayedOpenClose(open: true);
			}
		}

		public void Close()
		{
			if (IsOpen && !IsClosing)
			{
				StartDelayedOpenClose(open: false);
			}
		}

		public void TriggerTransition()
		{
			if (animator != null)
			{
				animator.SetTrigger("Transition");
			}
		}

		private void StartDelayedOpenClose(bool open)
		{
			StopDelayedOpenClose();
			delayedOpenCloseCoroutine = StartCoroutine(DelayedOpenClose(open));
		}

		private void StopDelayedOpenClose()
		{
			if (delayedOpenCloseCoroutine != null)
			{
				StopCoroutine(delayedOpenCloseCoroutine);
				delayedOpenCloseCoroutine = null;
			}
		}

		private IEnumerator DelayedOpenClose(bool open)
		{
			animator.SetBool("Visible", open);
			yield return new WaitForSeconds(0.25f);
			IsOpen = open;
			delayedOpenCloseCoroutine = null;
		}
	}
}
[DisallowMultipleComponent]
public class EmoteRadialMenuFlow : StackedUIFlowBase
{
	public delegate void Cancelation();

	public delegate void EmoteSelection(ScreenPlayerEmote emote);

	public delegate void PartyUp();

	[SerializeField]
	private Material defaultButtonMaterial;

	[SerializeField]
	private Material highlightButtonMaterial;

	[Header("Buttons")]
	[SerializeField]
	private EmoteRadialMenuButton[] emoteButtons;

	[SerializeField]
	private EmoteRadialMenuButton chatButton;

	[SerializeField]
	private EmoteRadialMenuButton partyUpButton;

	private EmoteRadialMenu radialMenu;

	private List<EmoteRadialMenuButton> allButtons = new List<EmoteRadialMenuButton>();

	public Cancelation CancelButtonSelected;

	public EmoteSelection EmoteButtonSelected;

	public PartyUp PartyUpButtonSelected;

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		radialMenu = uiBase as EmoteRadialMenu;
		for (int i = 0; i < emoteButtons.Length; i++)
		{
			emoteButtons[i].SelectionCallback = OnEmoteButtonSelected;
			allButtons.Add(emoteButtons[i]);
		}
		chatButton.SelectionCallback = OnChatEmoteButtonSelected;
		allButtons.Add(chatButton);
		partyUpButton.SelectionCallback = OnPartyUpButtonSelected;
		allButtons.Add(partyUpButton);
		for (int j = 0; j < allButtons.Count; j++)
		{
			allButtons[j].InitializeHighlightMaterials(defaultButtonMaterial, highlightButtonMaterial);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		radialMenu.IsInCursorFlow = false;
	}

	public void EnableChatButton(bool isEnabled)
	{
		chatButton.IsEnabled = isEnabled;
	}

	public void SetEmotes(IEnumerable<ScreenPlayerEmote> emotes)
	{
		int i = 0;
		foreach (ScreenPlayerEmote emote in emotes)
		{
			if (i >= emoteButtons.Length)
			{
				break;
			}
			emoteButtons[i].IsEnabled = true;
			emoteButtons[i].SetEmote(emote);
			i++;
		}
		for (; i < emoteButtons.Length; i++)
		{
			emoteButtons[i].IsEnabled = false;
		}
	}

	public void UpdateRadialButtons(bool inDeadzone, float selectionAngle, bool selectHighlightedButton)
	{
		EmoteRadialMenuButton emoteRadialMenuButton = UpdateButtonHighlight(inDeadzone, selectionAngle);
		if (selectHighlightedButton)
		{
			if (emoteRadialMenuButton == null)
			{
				OnNullButtonSelected();
			}
			else
			{
				emoteRadialMenuButton.OnSelect();
			}
		}
	}

	private void OnNullButtonSelected()
	{
		if (CancelButtonSelected != null)
		{
			CancelButtonSelected();
		}
	}

	private void OnEmoteButtonSelected(EmoteRadialMenuButton button)
	{
		if (EmoteButtonSelected != null)
		{
			EmoteButtonSelected((!(button != null)) ? null : button.Emote);
		}
	}

	private void OnChatEmoteButtonSelected(EmoteRadialMenuButton button)
	{
		radialMenu.EnterChatFlow();
	}

	private void OnPartyUpButtonSelected(EmoteRadialMenuButton button)
	{
		if (PartyUpButtonSelected != null)
		{
			PartyUpButtonSelected();
		}
	}

	private EmoteRadialMenuButton UpdateButtonHighlight(bool inDeadzone, float selectionAngle)
	{
		int num = -1;
		if (!inDeadzone)
		{
			float num2 = float.MaxValue;
			for (int i = 0; i < allButtons.Count; i++)
			{
				if (allButtons[i].IsEnabled)
				{
					float deltaAngle = allButtons[i].GetDeltaAngle(selectionAngle);
					if (deltaAngle < num2)
					{
						num2 = deltaAngle;
						num = i;
					}
				}
			}
		}
		for (int j = 0; j < allButtons.Count; j++)
		{
			allButtons[j].IsHighlighted = j == num;
		}
		return (num < 0) ? null : allButtons[num];
	}
}
namespace RecRoom.Core.Screens.UI
{
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/UI/Quick Comms Menu", fileName = "QuickCommsMenu")]
