		public QuickCommsMenuPage GetPageByIndex(int index)
		{
			QuickCommsMenuPage result = null;
			if (index >= 0 && index < pages.Length)
			{
				result = pages[index];
			}
			return result;
		}

		public QuickCommsMenuPage GetPageByName(string pageName)
		{
