	[Serializable]
	public class QuickCommsMenuController
	{
		private enum State
		{
			RESTRICTED,
			CLOSED,
			OPEN,
			COOLDOWN
		}

		[Header("Timing Settings")]
		[SerializeField]
		private float pageTimeoutDuration = 2f;

		[SerializeField]
		private float cooldownDuration = 1f;

		[SerializeField]
		private float cooldownShortcutDuration = 0.25f;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip menuOpenAudio;

		[SerializeField]
		private RecRoomAudioClip pageTransitionAudio;

		[SerializeField]
		private RecRoomAudioClip pageTimeoutAudio;

		[SerializeField]
		private RecRoomAudioClip emoteSelectionAudio;

		[NonSerialized]
		private ManualUpdateStateMachine stateMachine = new ManualUpdateStateMachine();

		[NonSerialized]
		private ScreenPlayerController cachedPlayerController;

		[NonSerialized]
		private Player cachedPlayer;

		[NonSerialized]
		private ScreenHUD cachedHud;

		[NonSerialized]
		private ScreenInputHandler cachedInput;

		[NonSerialized]
		private QuickCommsMenu currentMenu;

		[NonSerialized]
		private QuickCommsMenuPage currentMenuPage;

		[NonSerialized]
		private float lastInputPressedTime;

		[NonSerialized]
		private float cooldownStartTime;

		[NonSerialized]
		private bool isOnNestedPage;

		[NonSerialized]
		private TokenMap<QuickCommsMenu> menuMap = new TokenMap<QuickCommsMenu>();

		[NonSerialized]
		private TokenFlag restrictionFlag = new TokenFlag();

		[NonSerialized]
		private TokenFlag alwaysVisibleRequirementFlag = new TokenFlag();

		public void Initialize()
		{
			stateMachine.AddState(0, OnEnterRestrictedState, null, null);
			stateMachine.AddState(1, null, null, OnUpdateClosedState);
			stateMachine.AddState(2, OnEnterOpenState, OnExitOpenState, OnUpdateOpenState);
			stateMachine.AddState(3, OnEnterCooldownState, null, OnUpdateCooldownState);
			stateMachine.EnterState(1);
		}

		public void AddMenu(QuickCommsMenu menu, object token)
		{
			menuMap.AddValue(menu, token);
			OnMenuChange();
		}

		public void RemoveMenu(object token)
		{
			menuMap.RemoveValue(token);
			OnMenuChange();
		}

		public void AddRestriction(object token)
		{
			restrictionFlag.Add(token);
			OnRestrictionsChange();
		}

		public void RemoveRestriction(object token)
		{
			restrictionFlag.Remove(token);
			OnRestrictionsChange();
		}

		public void AddAlwaysVisibleRequirement(object token)
		{
			alwaysVisibleRequirementFlag.Add(token);
		}

		public void RemoveAlwaysVisibleRequirement(object token)
		{
			alwaysVisibleRequirementFlag.Remove(token);
			if (stateMachine.CurrentStateId == 2)
			{
				stateMachine.EnterState(1);
			}
		}

		public void OnUpdate(ScreenPlayerController playerController, Player player, ScreenHUD hud, ScreenInputHandler input)
		{
			cachedPlayerController = playerController;
			cachedPlayer = player;
			cachedHud = hud;
			cachedInput = input;
			stateMachine.Update();
		}

		private void OnEnterRestrictedState(ushort previousStateId, ushort previousSubStateId)
		{
			if (cachedHud != null)
			{
				cachedHud.DisableQuickCommsVisual();
			}
		}

		private void OnUpdateClosedState()
		{
			int menuInputPressedIndex = GetMenuInputPressedIndex();
			if (menuInputPressedIndex >= 0 || alwaysVisibleRequirementFlag.HasTokens)
			{
				stateMachine.EnterState(2);
			}
			else if (cachedHud != null)
			{
				cachedHud.DisableQuickCommsVisual();
			}
		}

		private void OnEnterOpenState(ushort previousStateId, ushort previousSubStateId)
		{
			if (!alwaysVisibleRequirementFlag.HasTokens)
			{
				AudioManager.Play2DSFX(menuOpenAudio);
			}
			lastInputPressedTime = UnityEngine.Time.time;
			isOnNestedPage = false;
			currentMenu = menuMap.LatestValue;
			SwitchPage(((object)currentMenu != null) ? currentMenu.GetPageByIndex(0) : null);
		}

		private void OnUpdateOpenState()
		{
			if (currentMenuPage == null)
			{
				stateMachine.EnterState(1);
				return;
			}
			int menuInputPressedIndex = GetMenuInputPressedIndex();
			EnableHUDVisualForCurrentPage(menuInputPressedIndex);
			if (menuInputPressedIndex >= 0)
			{
				lastInputPressedTime = UnityEngine.Time.time;
			}
			else if (cachedInput.QuickCommButton1Up)
			{
				RunMenuEntry(QuickCommsMenuPage.EntryType.UP);
			}
			else if (cachedInput.QuickCommButton2Up)
			{
				RunMenuEntry(QuickCommsMenuPage.EntryType.LEFT);
			}
			else if (cachedInput.QuickCommButton3Up)
			{
				RunMenuEntry(QuickCommsMenuPage.EntryType.RIGHT);
			}
			else if (cachedInput.QuickCommButton4Up)
			{
				RunMenuEntry(QuickCommsMenuPage.EntryType.DOWN);
			}
			else if ((isOnNestedPage || !alwaysVisibleRequirementFlag.HasTokens) && UnityEngine.Time.time - lastInputPressedTime >= pageTimeoutDuration)
			{
				AudioManager.Play2DSFX(pageTimeoutAudio);
				stateMachine.EnterState(3);
			}
		}

		private void OnExitOpenState(ushort nextStateId, ushort nextSubStateId)
		{
			currentMenuPage = null;
		}

		private void OnEnterCooldownState(ushort previousStateId, ushort previousSubStateId)
		{
			cooldownStartTime = UnityEngine.Time.time;
		}

		private void OnUpdateCooldownState()
		{
			float num = UnityEngine.Time.time - cooldownStartTime;
			int menuInputPressedIndex = GetMenuInputPressedIndex();
			if ((num >= cooldownShortcutDuration && menuInputPressedIndex >= 0) || num >= cooldownDuration)
			{
				stateMachine.EnterState(1);
			}
			else if (cachedHud != null)
			{
				cachedHud.DisableQuickCommsVisual();
			}
		}

		private void RunMenuEntry(QuickCommsMenuPage.EntryType entryType)
		{
			QuickCommsMenuEntry entryByType = currentMenuPage.GetEntryByType(entryType);
			if (entryByType == null)
			{
				return;
			}
			QuickCommsMenuEntry.EntryBehavior entryBehavior = entryByType.GetEntryBehavior();
			if (entryBehavior == QuickCommsMenuEntry.EntryBehavior.LOAD_PAGE)
			{
				string loadPageName = entryByType.GetLoadPageName();
				QuickCommsMenuPage pageByName = currentMenu.GetPageByName(loadPageName);
				if (SwitchPage(pageByName))
				{
					isOnNestedPage = true;
					AudioManager.Play2DSFX(pageTransitionAudio);
					return;
				}
			}
			if (entryBehavior == QuickCommsMenuEntry.EntryBehavior.PLAY_EMOTE)
			{
				ScreenPlayerEmote emote = entryByType.GetEmote();
				if (emote != null)
				{
					cachedPlayerController.EmoteSystem.QueueEmote(emote);
				}
			}
			if (entryBehavior == QuickCommsMenuEntry.EntryBehavior.START_SOCIAL_GESTURE)
			{
				switch (entryByType.GetSocialGestureType())
				{
				case QuickCommsMenuEntry.SocialGestureType.HIGH_FIVE:
					cachedPlayer.PlayerParty.IsWaitingToHighFive = true;
					break;
				case QuickCommsMenuEntry.SocialGestureType.MAKE_FRIEND:
					cachedPlayer.PlayerParty.IsWaitingToMakeFriend = true;
					break;
				case QuickCommsMenuEntry.SocialGestureType.PARTY_UP:
					cachedPlayer.PlayerParty.IsWaitingtoJoinAParty = true;
					break;
				}
			}
			if (entryBehavior == QuickCommsMenuEntry.EntryBehavior.TOGGLE_CHAT_MENU)
			{
				cachedPlayer.ChatMenuRequested = !cachedPlayer.ChatMenuRequested;
			}
			if (entryBehavior == QuickCommsMenuEntry.EntryBehavior.TOGGLE_PUSH_TO_TALK && SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.PushToTalk)
			{
				cachedPlayer.ExpressoPushToTalkPressed = !cachedPlayer.ExpressoPushToTalkPressed;
			}
			AudioManager.Play2DSFX(emoteSelectionAudio);
			stateMachine.EnterState(3);
		}

		private bool SwitchPage(QuickCommsMenuPage page)
		{
			if (page != null)
			{
				currentMenuPage = page;
				return true;
			}
			return false;
		}

		private string GetEntryName(QuickCommsMenuEntry entry)
		{
			if (entry == null)
			{
				return null;
			}
			return entry.GetEntryBehavior() switch
			{
				QuickCommsMenuEntry.EntryBehavior.LOAD_PAGE => entry.GetLoadPageName(), 
				QuickCommsMenuEntry.EntryBehavior.PLAY_EMOTE => entry.GetEmoteName(), 
				QuickCommsMenuEntry.EntryBehavior.START_SOCIAL_GESTURE => entry.GetSocialGestureName(), 
				QuickCommsMenuEntry.EntryBehavior.TOGGLE_PUSH_TO_TALK => GetPushToTalkLabel(), 
				QuickCommsMenuEntry.EntryBehavior.TOGGLE_CHAT_MENU => "Open Chat Menu", 
				_ => null, 
			};
		}

		private string GetPushToTalkLabel()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat != VoiceChat.PushToTalk || cachedPlayer == null)
			{
				return "PTT Is Not Enabled";
			}
			if (cachedPlayer.ExpressoPushToTalkPressed)
			{
				return "PTT: Turn On Mic";
			}
			return "PTT: Turn Off Mic";
		}

		private int GetMenuInputPressedIndex()
		{
			if (cachedInput.QuickCommButton1Pressed)
			{
				return 0;
			}
			if (cachedInput.QuickCommButton2Pressed)
			{
				return 1;
			}
			if (cachedInput.QuickCommButton3Pressed)
			{
				return 2;
			}
			if (cachedInput.QuickCommButton4Pressed)
			{
				return 3;
			}
			return -1;
		}

		private void EnableHUDVisualForCurrentPage(int pressedIndex)
		{
			if (!(cachedHud == null) && cachedInput != null && currentMenuPage != null)
			{
				cachedHud.EnableQuickCommsVisual(currentMenuPage.GetName(), cachedInput.QuickCommButton1Sprite, GetEntryName(currentMenuPage.GetEntryByType(QuickCommsMenuPage.EntryType.UP)), cachedInput.QuickCommButton2Sprite, GetEntryName(currentMenuPage.GetEntryByType(QuickCommsMenuPage.EntryType.LEFT)), cachedInput.QuickCommButton3Sprite, GetEntryName(currentMenuPage.GetEntryByType(QuickCommsMenuPage.EntryType.RIGHT)), cachedInput.QuickCommButton4Sprite, GetEntryName(currentMenuPage.GetEntryByType(QuickCommsMenuPage.EntryType.DOWN)));
				cachedHud.HighlightQuickCommDialog(pressedIndex);
			}
		}

		private void OnRestrictionsChange()
		{
			if (restrictionFlag.HasTokens && stateMachine.CurrentStateId != 0)
			{
				stateMachine.EnterState(0);
			}
			else if (!restrictionFlag.HasTokens && stateMachine.CurrentStateId == 0)
			{
				stateMachine.EnterState(1);
			}
		}

		private void OnMenuChange()
		{
			QuickCommsMenu latestValue = menuMap.LatestValue;
			if (latestValue != currentMenu)
			{
				currentMenu = latestValue;
				if (stateMachine.CurrentStateId == 2)
				{
					SwitchPage(((object)currentMenu != null) ? currentMenu.GetPageByIndex(0) : null);
				}
			}
		}
	}
	[Serializable]
	public class QuickCommsMenuEntry
	{
		public enum EntryBehavior
		{
			NONE,
			LOAD_PAGE,
			PLAY_EMOTE,
			START_SOCIAL_GESTURE,
			TOGGLE_PUSH_TO_TALK,
			TOGGLE_CHAT_MENU
		}

		public enum SocialGestureType
		{
			NONE,
			PARTY_UP,
			MAKE_FRIEND,
			HIGH_FIVE
		}

		[Header("Config")]
		[SerializeField]
		private EntryBehavior entryBehavior = EntryBehavior.LOAD_PAGE;

		[SerializeField]
		[ConditionalField("entryBehavior", 1)]
		private string loadPageName;

		[SerializeField]
		[ConditionalField("entryBehavior", 2)]
		private string emoteName;

		[SerializeField]
		[ConditionalField("entryBehavior", 2)]
		private ScreenPlayerEmote emote;

		[SerializeField]
		[ConditionalField("entryBehavior", 3)]
		private string socialGestureName;

		[SerializeField]
		[ConditionalField("entryBehavior", 3)]
		private SocialGestureType socialGestureType;

		public EntryBehavior GetEntryBehavior()
		{
			return entryBehavior;
		}

		public string GetLoadPageName()
		{
			return (entryBehavior != EntryBehavior.LOAD_PAGE) ? null : loadPageName;
		}

		public string GetEmoteName()
		{
			return (entryBehavior != EntryBehavior.PLAY_EMOTE) ? null : emoteName;
		}

		public ScreenPlayerEmote GetEmote()
		{
			return (entryBehavior != EntryBehavior.PLAY_EMOTE) ? null : emote;
		}

		public string GetSocialGestureName()
		{
			return (entryBehavior != EntryBehavior.START_SOCIAL_GESTURE) ? null : socialGestureName;
		}

		public SocialGestureType GetSocialGestureType()
		{
			return (entryBehavior == EntryBehavior.START_SOCIAL_GESTURE) ? socialGestureType : SocialGestureType.NONE;
		}
	}
	[Serializable]
	public class QuickCommsMenuPage
	{
		public enum EntryType
		{
			UP,
			DOWN,
			LEFT,
			RIGHT
		}

		[SerializeField]
		private string name;

		[SerializeField]
		private QuickCommsMenuEntry upEntry;

		[SerializeField]
		private QuickCommsMenuEntry leftEntry;

		[SerializeField]
		private QuickCommsMenuEntry rightEntry;

		[SerializeField]
		private QuickCommsMenuEntry downEntry;

		public string GetName()
		{
			return name;
		}

		public bool IsName(string name)
		{
			return string.Compare(this.name, name, ignoreCase: true) == 0;
		}

		public QuickCommsMenuEntry GetEntryByType(EntryType entryType)
		{
			return entryType switch
			{
				EntryType.UP => upEntry, 
				EntryType.DOWN => downEntry, 
				EntryType.LEFT => leftEntry, 
				EntryType.RIGHT => rightEntry, 
				_ => null, 
			};
		}
	}
}
namespace RecRoom.UI
{
	[ExecuteInEditMode]
	[DisallowMultipleComponent]
	public class RadialUILayout : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private RectTransform[] children;

		[SerializeField]
		private float totalArcAngle = 360f;

		[SerializeField]
		private float wedgeArcAngle = 30f;

		[SerializeField]
		private float radius = 100f;

		[SerializeField]
		private bool applyRotation;

		private void Update()
		{
			if (children != null)
			{
				LayoutChildren();
			}
		}

		private void LayoutChildren()
		{
			int num = children.Length;
			int num2 = (int)Mathf.Floor(Mathf.Min(totalArcAngle, 360f) / wedgeArcAngle);
			float num3 = 0f;
			int num4 = 0;
			int i = 0;
			while (num4 < num2 && i < num)
			{
				if (!(children[i] == null))
				{
					children[i].gameObject.SetActive(value: true);
					Quaternion quaternion = Quaternion.Euler(0f, 0f, num3);
					Vector3 vector = quaternion * Vector3.up;
					Vector3 vector2 = vector * radius;
					children[i].anchoredPosition = new Vector2(vector2.x, vector2.y);
					children[i].rotation = ((!applyRotation) ? Quaternion.identity : quaternion);
					num3 += wedgeArcAngle;
					num4++;
				}
				i++;
			}
			for (; i < num; i++)
			{
				if (children[i] != null)
				{
					children[i].gameObject.SetActive(value: false);
				}
			}
		}
	}
}
namespace RecRoom.Core.Screens
{
	public class ScreensContextSensitiveActionRegion : UnityEngine.MonoBehaviour
	{
		public static List<ScreensContextSensitiveActionRegion> LocalPlayerOverlappingRegions = new List<ScreensContextSensitiveActionRegion>();

		[Header("Object References")]
		[SerializeField]
		private GameObject rootGameObject;

		[Header("Action Controller")]
		[SerializeField]
		private ScreenContextSensitiveActionController actionController;

		[Header("Action Transforms")]
		[SerializeField]
		private Transform playerGazeTargetTransform;

		[SerializeField]
		private Transform playerPositionTargetTransform;

		[SerializeField]
		private Transform cameraTargetPositionTransform;

		[Header("Region Settings")]
		[SerializeField]
		private float regionRadius = 3f;

		[SerializeField]
		private float maxAngleFromForward = 90f;

		private bool _isLocalPlayerInThisRegion;

		public ScreenContextSensitiveActionController ActionController => actionController;

		public GameObject RootGameObject => rootGameObject;

		public Transform PlayerGazeTargetTransform => playerGazeTargetTransform;

		public Transform PlayerTargetPositionTransform => playerPositionTargetTransform;

		public Transform CameraTargetPositionTransform => cameraTargetPositionTransform;

		public bool IsLocalPlayerInThisRegion => _isLocalPlayerInThisRegion;

		private void Awake()
		{
			this.LateUpdate30hz(StaggeredUpdate);
		}

		private void OnDestroy()
		{
			LocalPlayerOverlappingRegions.Remove(this);
		}

		private void OnDrawGizmos()
		{
			Gizmos.color = Color.blue;
			Gizmos.DrawWireSphere(base.transform.position, regionRadius);
		}

		private void StaggeredUpdate(float deltaTime)
		{
			bool flag = false;
			bool flag2 = false;
			if (Player.LocalPlayer != null)
			{
				float num = regionRadius;
				float num2 = maxAngleFromForward;
				if (_isLocalPlayerInThisRegion)
				{
					num *= 1.2f;
					num2 *= 1.2f;
				}
				Player localPlayer = Player.LocalPlayer;
				Vector3 vector = base.transform.position - Player.LocalPlayer.Head.RigidbodyEx.targetPosition;
				flag = vector.sqrMagnitude <= num * num;
				Vector3 normalized = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				float num3 = Vector3.Angle(localPlayer.TrackingSpace.RigidbodyEx.TargetTransform.forward, normalized);
				flag2 = num3 <= num2;
			}
			SetLocalPlayerIsInThisRegion(flag && flag2);
		}

		private void SetLocalPlayerIsInThisRegion(bool value)
		{
			bool isLocalPlayerInThisRegion = _isLocalPlayerInThisRegion;
			if (isLocalPlayerInThisRegion != value)
			{
				_isLocalPlayerInThisRegion = value;
				if (_isLocalPlayerInThisRegion && !LocalPlayerOverlappingRegions.Contains(this))
				{
					LocalPlayerOverlappingRegions.Add(this);
				}
				else
				{
					LocalPlayerOverlappingRegions.Remove(this);
				}
			}
		}
	}
}
public class ScreenSpaceNotification : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class NotificationText
	{
		public Text Text;

		public Outline Outline;

		public int FontSize
		{
			set
			{
				Text.fontSize = value;
			}
		}

		public Color Color
		{
			get
			{
				return Text.color;
			}
			set
			{
				Text.color = value.WithAlpha(Alpha);
			}
		}

		public float Alpha
		{
			get
			{
				return Text.color.a;
			}
			set
			{
				Color color = Text.color;
				color.a = value;
				Text.color = color;
				if (Outline != null)
				{
					Color effectColor = Outline.effectColor;
					effectColor.a = value;
					Outline.effectColor = effectColor;
				}
			}
		}
	}

	public NotificationText Title;

	public NotificationText Subtitle;

	public MeshRenderer DesaturationBackdrop;

	[Header("Animation Config")]
	public FloatValueCurve DesaturationEaseInCurve;

	public FloatValueCurve DesaturationEaseOutCurve;

	public FloatValueCurve AlphaEaseInCurve;

	public FloatValueCurve AlphaEaseOutCurve;

	public Vector3ValueCurve CameraOffsetEaseInCurve;

	public Vector3ValueCurve CameraOffsetEaseOutCurve;

	private Color initialTitleColor;

	private Color initialSubtitleColor;

	private Material desatBackgroundMaterial;

	private static int DesaturationAmountParameterId;

	public Vector3 positionCameraSpace { get; set; }

	private void Awake()
	{
		DesaturationAmountParameterId = Shader.PropertyToID("_DesaturationAmount");
		desatBackgroundMaterial = DesaturationBackdrop.material;
		SetTextAlpha(0f);
		SetBackgroundDesatAmount(0f);
		initialTitleColor = Title.Color;
		initialSubtitleColor = Subtitle.Color;
	}

	public void SetTextAlpha(float alpha)
	{
		Title.Alpha = alpha;
		Subtitle.Alpha = alpha;
	}

	public void SetBackgroundDesatAmount(float desatAmount)
	{
		desatBackgroundMaterial.SetFloat(DesaturationAmountParameterId, desatAmount);
	}

	private void LateUpdate()
	{
		if (!(SingletonMonoBehaviour<CameraRig>.Instance == null))
		{
			Vector3 position = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
			Vector3 up = Vector3.up;
			Vector3 vector = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
			Vector3 vector2 = Vector3.Cross(vector, up);
			up = Vector3.Cross(vector2, vector);
			base.transform.position = positionCameraSpace.TransformCoordinateSpace(position, vector2, up, vector);
			if ((base.transform.position - position).sqrMagnitude > 0.001f)
			{
				vector = Vector3.ProjectOnPlane(base.transform.position - position, up).normalized;
			}
			base.transform.rotation = Quaternion.LookRotation(vector, up);
		}
	}

	public void ResetColors()
	{
		Title.Color = initialTitleColor;
		Subtitle.Color = initialSubtitleColor;
	}
}
