public class ScreenSpaceNotificationManager : SingletonMonoBehaviour<ScreenSpaceNotificationManager>
{
	public enum NotificationType
	{
		Vital,
		Major,
		Medium,
		Minor
	}

	private delegate bool Interruption();

	private class NotificationDescriptor
	{
		public NotificationType Type;

		public string Title;

		public Color? TitleColor;

		public string Subtitle;

		public Color? SubtitleColor;

		public float Duration;

		public Action Callback;

		public CancelNotificationToken CancelationToken;
	}

	private struct PersistentNotificationData
	{
		public string Title;

		public string Subtitle;
	}

	private class CancelNotificationToken : IDisposable
	{
		public bool IsCanceled;

		public void Dispose()
		{
			IsCanceled = true;
		}
	}

	[SerializeField]
	private ScreenSpaceNotification vitalNotification;

	[SerializeField]
	private ScreenSpaceNotification majorNotification;

	[SerializeField]
	private ScreenSpaceNotification mediumNotification;

	[SerializeField]
	private ScreenSpaceNotification minorNotification;

	[SerializeField]
	private ScreenSpaceNotification persistentNotification;

	private Queue<NotificationDescriptor> vitalNotificationQueue;

	private NotificationDescriptor nextNotificationDescriptor;

	private NotificationDescriptor currentNotificationDescriptor;

	private ScreenSpaceNotification currentNotification;

	private bool isCurrentNotificationActive;

	private TokenMap<PersistentNotificationData> persistentNotificationMap = new TokenMap<PersistentNotificationData>();

	private bool highestPriorityPersistentNotificationChanged;

	private ScreenSpaceNotification currentPersistentNotification;

	private RecRoomAudioClip notificationAudio;

	private float notificationTimer;

	private float notificationWaitDuration;

	private bool Paused => Player.LocalPlayerExists && Player.LocalPlayer.IsSpawning;

	public bool IsPlaying => minorNotification.gameObject.activeInHierarchy || mediumNotification.gameObject.activeInHierarchy || majorNotification.gameObject.activeInHierarchy || vitalNotification.isActiveAndEnabled;

	protected override void Awake()
	{
		base.Awake();
		vitalNotificationQueue = new Queue<NotificationDescriptor>();
		vitalNotification.gameObject.SetActive(value: false);
		majorNotification.gameObject.SetActive(value: false);
		mediumNotification.gameObject.SetActive(value: false);
		minorNotification.gameObject.SetActive(value: false);
		persistentNotification.gameObject.SetActive(value: false);
	}

	private void Start()
	{
		StartCoroutine(NotificationDisplayCoroutine());
		StartCoroutine(PersistentNotificationDisplayCoroutine());
	}

	public void SetNotificationAudio(RecRoomAudioClip notificationAudio)
	{
		this.notificationAudio = notificationAudio;
	}

	public void ClearNotificationAudio()
	{
		notificationAudio = null;
	}

	public IDisposable Play(NotificationType style, string titleText, float duration, Action callback = null, bool updateIfSameStyle = false)
	{
		return Play(style, titleText, null, null, null, duration, callback, updateIfSameStyle);
	}

	public IDisposable Play(NotificationType style, string titleText, Color titleColor, float duration, Action callback = null)
	{
		return Play(style, titleText, titleColor, null, null, duration, callback);
	}

	public IDisposable Play(NotificationType style, string titleText, string subtitleText, float duration, Action callback = null, bool updateIfSameStyle = false)
	{
		return Play(style, titleText, null, subtitleText, null, duration, callback, updateIfSameStyle);
	}

	public IDisposable Play(NotificationType style, string titleText, Color titleColor, string subtitleText, float duration, Action callback = null)
	{
		return Play(style, titleText, titleColor, subtitleText, null, duration, callback);
	}

	public IDisposable Play(NotificationType style, string titleText, string subtitleText, Color subtitleColor, float duration, Action callback = null)
	{
		return Play(style, titleText, null, subtitleText, subtitleColor, duration, callback);
	}

	public IDisposable Play(NotificationType style, string titleText, Color? titleColor, string subtitleText, Color? subtitleColor, float duration, Action callback = null, bool updateIfSameStyle = false)
	{
		CancelNotificationToken cancelNotificationToken = new CancelNotificationToken();
		NotificationDescriptor notificationDescriptor = new NotificationDescriptor();
		notificationDescriptor.Type = style;
		notificationDescriptor.Title = titleText;
		notificationDescriptor.TitleColor = titleColor;
		notificationDescriptor.Subtitle = subtitleText;
		notificationDescriptor.SubtitleColor = subtitleColor;
		notificationDescriptor.Duration = duration;
		notificationDescriptor.Callback = callback;
		notificationDescriptor.CancelationToken = cancelNotificationToken;
		NotificationDescriptor item = notificationDescriptor;
		if (updateIfSameStyle && isCurrentNotificationActive && currentNotificationDescriptor.Type == style && style != NotificationType.Vital)
		{
			currentNotificationDescriptor = item;
			currentNotification = InitializeNotification(currentNotification, currentNotificationDescriptor, resetColors: false);
			UpdateNotificationWaitTime();
			return cancelNotificationToken;
		}
		if (style == NotificationType.Vital)
		{
			nextNotificationDescriptor = null;
			vitalNotificationQueue.Enqueue(item);
		}
		else if (vitalNotificationQueue.Count == 0 && (currentNotificationDescriptor == null || currentNotificationDescriptor.CancelationToken.IsCanceled || currentNotificationDescriptor.Type >= style) && (nextNotificationDescriptor == null || nextNotificationDescriptor.CancelationToken.IsCanceled || nextNotificationDescriptor.Type >= style))
		{
			nextNotificationDescriptor = item;
		}
		return cancelNotificationToken;
	}

	public void PlayDelayed(NotificationType style, string titleText, float duration, float delay, Action callback = null)
	{
		PlayDelayed(style, titleText, null, duration, delay, callback);
	}

	public void PlayDelayed(NotificationType style, string titleText, string subtitleText, float duration, float delay, Action callback = null)
	{
		StartCoroutine(EnqueueNotificationCoroutine(style, titleText, subtitleText, duration, delay, callback));
	}

	public void AddPersistentNotification(string titleText, object token)
	{
		persistentNotificationMap.AddValue(new PersistentNotificationData
		{
			Title = titleText,
			Subtitle = null
		}, token);
		highestPriorityPersistentNotificationChanged = true;
	}

	public void AddPersistentNotification(string titleText, string subtitleText, object token)
	{
		persistentNotificationMap.AddValue(new PersistentNotificationData
		{
			Title = titleText,
			Subtitle = subtitleText
		}, token);
		highestPriorityPersistentNotificationChanged = true;
	}

	public void RemovePersistentNotification(object token)
	{
		object latestToken = persistentNotificationMap.LatestToken;
		persistentNotificationMap.RemoveValue(token);
		if (latestToken != persistentNotificationMap.LatestToken)
		{
			highestPriorityPersistentNotificationChanged = true;
		}
	}

	public void UpdatePersistentNotificationTitle(string title, object token)
	{
		if (persistentNotificationMap.TryGetValue(token, out var value))
		{
			PersistentNotificationData value2 = new PersistentNotificationData
			{
				Title = title,
				Subtitle = value.Subtitle
			};
			persistentNotificationMap.AddValue(value2, token);
			if (persistentNotificationMap.LatestToken == token && currentPersistentNotification != null)
			{
				currentPersistentNotification.Title.Text.text = title;
			}
		}
	}

	public void UpdatePersistentNotificationSubtitle(string subtitle, object token)
	{
		if (persistentNotificationMap.TryGetValue(token, out var value))
		{
			PersistentNotificationData value2 = new PersistentNotificationData
			{
				Title = value.Title,
				Subtitle = subtitle
			};
			persistentNotificationMap.AddValue(value2, token);
			if (persistentNotificationMap.LatestToken == token && currentPersistentNotification != null)
			{
				currentPersistentNotification.Subtitle.Text.text = subtitle;
			}
		}
	}

	private IEnumerator EnqueueNotificationCoroutine(NotificationType style, string titleText, string subtitleText, float duration, float delay, Action callback)
	{
		yield return new WaitForSeconds(delay);
		Play(style, titleText, subtitleText, duration, callback);
	}

	private ScreenSpaceNotification InitializeNotification(ScreenSpaceNotification notification, NotificationDescriptor descriptor, bool resetColors)
	{
		notification.gameObject.SetActive(value: true);
		if (resetColors)
		{
			notification.ResetColors();
		}
		notification.Title.Text.text = descriptor.Title;
		notification.Subtitle.Text.text = descriptor.Subtitle;
		if (descriptor.TitleColor.HasValue)
		{
			notification.Title.Color = descriptor.TitleColor.Value;
		}
		if (descriptor.SubtitleColor.HasValue)
		{
			notification.Subtitle.Color = descriptor.SubtitleColor.Value;
		}
		if (resetColors)
		{
			notification.SetTextAlpha(0f);
			notification.SetBackgroundDesatAmount(0f);
		}
		return notification;
	}

	private void ResetNotification(ScreenSpaceNotification notification)
	{
		notification.gameObject.SetActive(value: false);
	}

	private IEnumerator AnimateNotification(ScreenSpaceNotification notification, Interruption higherPriorityNotificationPending, bool animateIn)
	{
		float duration = ((!animateIn) ? notification.CameraOffsetEaseOutCurve.Duration : notification.CameraOffsetEaseInCurve.Duration);
		Vector3ValueCurve posCurve = ((!animateIn) ? notification.CameraOffsetEaseOutCurve : notification.CameraOffsetEaseInCurve);
		FloatValueCurve alphaCurve = ((!animateIn) ? notification.AlphaEaseOutCurve : notification.AlphaEaseInCurve);
		FloatValueCurve desatCurve = ((!animateIn) ? notification.DesaturationEaseOutCurve : notification.DesaturationEaseInCurve);
		float timer = 0f;
		while (timer < posCurve.Duration && !higherPriorityNotificationPending())
		{
			float t = timer / duration;
			notification.positionCameraSpace = posCurve.Evaluate(t);
			notification.SetTextAlpha(alphaCurve.Evaluate(t));
			notification.SetBackgroundDesatAmount(desatCurve.Evaluate(t));
			if (!Paused)
			{
				timer += UnityEngine.Time.deltaTime;
			}
			yield return null;
		}
		float finalAlpha = ((!animateIn || higherPriorityNotificationPending()) ? 0f : 1f);
		float finalDesat = ((!animateIn || higherPriorityNotificationPending()) ? 0f : 1f);
		notification.SetTextAlpha(finalAlpha);
		notification.SetBackgroundDesatAmount(finalDesat);
	}

	private ScreenSpaceNotification GetNotificationFromType(NotificationType type)
	{
		return type switch
		{
			NotificationType.Vital => vitalNotification, 
			NotificationType.Major => majorNotification, 
			NotificationType.Medium => mediumNotification, 
			NotificationType.Minor => minorNotification, 
			_ => null, 
		};
	}

	private IEnumerator NotificationDisplayCoroutine()
	{
		while (true)
		{
			yield return new WaitUntil(() => AnyNotificationsPending());
			currentNotificationDescriptor = GetNextNotificationDescriptor();
			currentNotification = GetNotificationFromType(currentNotificationDescriptor.Type);
			currentNotification = InitializeNotification(currentNotification, currentNotificationDescriptor, resetColors: true);
			if (currentNotificationDescriptor.Callback != null)
			{
				currentNotificationDescriptor.Callback();
			}
			if (notificationAudio != null && notificationAudio.audioClip != null)
			{
				AudioManager.Play2DSFX(notificationAudio);
			}
			isCurrentNotificationActive = true;
			yield return AnimateNotification(currentNotification, ShouldInterruptCurrentNotification, animateIn: true);
			yield return WaitForNotificationDuration();
			isCurrentNotificationActive = false;
			yield return AnimateNotification(currentNotification, ShouldInterruptCurrentNotification, animateIn: false);
			ResetNotification(currentNotification);
			currentNotification = null;
			currentNotificationDescriptor = null;
		}
	}

	private bool AnyNotificationsPending()
	{
		return vitalNotificationQueue.Count > 0 || nextNotificationDescriptor != null;
	}

	private bool ShouldInterruptCurrentNotification()
	{
		if (currentNotificationDescriptor.CancelationToken.IsCanceled)
		{
			return true;
		}
		if (currentNotificationDescriptor.Type != NotificationType.Vital && (vitalNotificationQueue.Count > 0 || (nextNotificationDescriptor != null && nextNotificationDescriptor.Type <= currentNotificationDescriptor.Type)))
		{
			return true;
		}
		return false;
	}

	private NotificationDescriptor GetNextNotificationDescriptor()
	{
		if (vitalNotificationQueue.Count > 0)
		{
			return vitalNotificationQueue.Dequeue();
		}
		NotificationDescriptor result = nextNotificationDescriptor;
		nextNotificationDescriptor = null;
		return result;
	}

	private void UpdateNotificationWaitTime()
	{
		notificationWaitDuration = Mathf.Max(0f, currentNotificationDescriptor.Duration - currentNotification.CameraOffsetEaseInCurve.Duration - currentNotification.AlphaEaseOutCurve.Duration);
		notificationTimer = 0f;
	}

	private IEnumerator WaitForNotificationDuration()
	{
		UpdateNotificationWaitTime();
		while (notificationTimer < notificationWaitDuration && !ShouldInterruptCurrentNotification())
		{
			if (!Paused)
			{
				notificationTimer += UnityEngine.Time.deltaTime;
			}
			yield return null;
		}
	}

	private IEnumerator PersistentNotificationDisplayCoroutine()
	{
		while (true)
		{
			yield return new WaitUntil(() => AnyPersistentNotificationsPending());
			NotificationDescriptor currentPersistentDescriptor = GetNextPersistentNotificationDescriptor();
			currentPersistentNotification = persistentNotification;
			InitializeNotification(persistentNotification, currentPersistentDescriptor, resetColors: true);
			highestPriorityPersistentNotificationChanged = false;
			yield return AnimateNotification(currentPersistentNotification, HigherPriorityPersistentNotificationPending, animateIn: true);
			yield return WaitForPersistentNotificationToStop();
			yield return AnimateNotification(currentPersistentNotification, HigherPriorityPersistentNotificationPending, animateIn: false);
			ResetNotification(currentPersistentNotification);
			currentPersistentNotification = null;
		}
	}

	private bool AnyPersistentNotificationsPending()
	{
		return persistentNotificationMap.ContainsValues;
	}

	private NotificationDescriptor GetNextPersistentNotificationDescriptor()
	{
		PersistentNotificationData latestValue = persistentNotificationMap.LatestValue;
		NotificationDescriptor notificationDescriptor = new NotificationDescriptor();
		notificationDescriptor.Type = NotificationType.Minor;
		notificationDescriptor.Title = latestValue.Title;
		notificationDescriptor.Subtitle = latestValue.Subtitle;
		notificationDescriptor.Duration = float.MaxValue;
		notificationDescriptor.Callback = null;
		return notificationDescriptor;
	}

	private IEnumerator WaitForPersistentNotificationToStop()
	{
		while (persistentNotificationMap.ContainsValues && !HigherPriorityPersistentNotificationPending())
		{
			yield return null;
		}
	}

	private bool HigherPriorityPersistentNotificationPending()
	{
		return highestPriorityPersistentNotificationChanged;
	}
}
namespace RecRoom.Core
{
	public class ScreenWorldSpaceUIAnchor : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private Camera parentCamera;

		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private CameraIgnoreBubble ignoreBubble;

		private Vector3 attachedObjectPrevLocalPosition;

		private Quaternion attachedObjectPrevLocalRotation;

		private float attachedObjectWorldSpaceSize;

		private Quaternion attachedObjectLocalRotation;

		private bool resetPositionOnDetach;

		private float verticalBufferPercentage;

		private ISchedulerPromise attachedUIRoutinePromise;

		public StackedUIBase AttachedUI { get; private set; }

		public GameObject AttachedGameObject { get; private set; }

		private Quaternion UIRotation => parentCamera.transform.rotation;

		private Vector3 GetUIPosition(float worldSpaceSize, float verticalBufferPercentage)
		{
			float distanceFromProjectionCameraToFillFOV = parentCamera.GetDistanceFromProjectionCameraToFillFOV(worldSpaceSize, verticalBufferPercentage);
			return parentCamera.transform.position + parentCamera.transform.forward * distanceFromProjectionCameraToFillFOV;
		}

		private void Start()
		{
			ignoreBubble.enabled = false;
		}

		public void Attach(StackedUIBase uiBase, float verticalBufferPercentage, bool resetPositionOnDetach)
		{
			Detach();
			Attach(uiBase.gameObject, uiBase.WorldSpaceCanvasSize.y, Quaternion.identity, verticalBufferPercentage, resetPositionOnDetach);
			AttachedUI = uiBase;
		}

		public void Attach(MenuProjector menuProjector, StackedUIBase menu, float verticalBufferPercentage, bool resetPositionOnDetach)
		{
			Detach();
			Attach(menuProjector.gameObject, menu.WorldSpaceCanvasSize.y, Quaternion.identity, verticalBufferPercentage, resetPositionOnDetach);
			AttachedUI = menu;
		}

		public void Attach(GameObject newObject, float worldSpaceSize, Quaternion localRotation, float verticalBufferPercentage, bool resetPositionOnDetach)
		{
			if (newObject != null)
			{
				AttachedGameObject = newObject;
				attachedObjectPrevLocalPosition = newObject.transform.localPosition;
				attachedObjectPrevLocalRotation = newObject.transform.localRotation;
				attachedObjectWorldSpaceSize = worldSpaceSize;
				attachedObjectLocalRotation = localRotation;
				this.verticalBufferPercentage = verticalBufferPercentage;
				this.resetPositionOnDetach = resetPositionOnDetach;
				attachedUIRoutinePromise = SingletonMonoBehaviour<Scheduler>.Instance.Run(UpdateAttachedPositionRoutine());
				ignoreBubble.enabled = true;
			}
		}

		public void Detach()
		{
			if (AttachedGameObject != null)
			{
				if (resetPositionOnDetach)
				{
					AttachedGameObject.transform.localPosition = attachedObjectPrevLocalPosition;
					AttachedGameObject.transform.localRotation = attachedObjectPrevLocalRotation;
				}
				AttachedGameObject = null;
				AttachedUI = null;
			}
			ignoreBubble.enabled = false;
			if (attachedUIRoutinePromise != null)
			{
				attachedUIRoutinePromise.Cancel();
				attachedUIRoutinePromise = null;
			}
		}

		private IEnumerator<ISchedule> UpdateAttachedPositionRoutine()
		{
			yield return Schedule.NextLateUpdate;
			while (AttachedGameObject != null)
			{
				AttachedGameObject.transform.position = GetUIPosition(attachedObjectWorldSpaceSize, verticalBufferPercentage);
				AttachedGameObject.transform.rotation = UIRotation * attachedObjectLocalRotation;
				yield return Schedule.NextLateUpdate;
			}
		}
	}
}
public class SplashScreenManager : SingletonMonoBehaviour<SplashScreenManager>
{
	[SerializeField]
	private float minSplashDuration = 5f;

	[Header("Error Canvas")]
	[SerializeField]
	private Canvas errorMessageCanvas;

	[SerializeField]
	private Text errorMessageTextBox;

	[Header("Audio")]
	[SerializeField]
	private bool is2DAudio = true;

	[SerializeField]
	private Transform audioTransform3D;

	[SerializeField]
	private RecRoomAudioClip normalSplashScreenAudio;

	[SerializeField]
	private RecRoomAudioClip NUXSplashScreenAudio;

	[Header("Splash screen selection")]
	[SerializeField]
	private GameObject NUXSplashScreen;

	[SerializeField]
	private GameObject normalSplashScreen;

	private float startTime;

	private SFXAudioSource playingAudio;

	private RecRoomAudioClip splashScreenAudioToPlay;

	private const string LOCAL_NUM_SESSIONS = "NumSessions";

	public bool StayForeverInLoadingScene => false;

	protected override void Awake()
	{
		base.Awake();
		errorMessageCanvas.gameObject.SetActive(value: false);
	}

	private void Start()
	{
		SelectAppropriateSplashScreen();
		startTime = UnityEngine.Time.time;
		if (splashScreenAudioToPlay != null && splashScreenAudioToPlay.audioClip != null)
		{
			if (is2DAudio || audioTransform3D == null)
			{
				playingAudio = AudioManager.Play2DSFX(splashScreenAudioToPlay);
			}
			else
			{
				playingAudio = AudioManager.Play3DSFX(splashScreenAudioToPlay, audioTransform3D);
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (playingAudio != null)
		{
			AudioManager.StopLoopingSFX(playingAudio);
			playingAudio = null;
		}
	}

	private void SelectAppropriateSplashScreen()
	{
		int num = 0;
		if (PlayerPrefs.HasKey("NumSessions"))
		{
			num = PlayerPrefs.GetInt("NumSessions");
		}
		NUXSplashScreen.SetActive(num == 0);
		normalSplashScreen.SetActive(num > 0);
		splashScreenAudioToPlay = ((num != 0) ? normalSplashScreenAudio : NUXSplashScreenAudio);
		PlayerPrefs.SetInt("NumSessions", num + 1);
		PlayerPrefs.Save();
	}

	public void ShowErrorMessage(string message)
	{
		errorMessageTextBox.text = message;
		errorMessageCanvas.gameObject.SetActive(value: true);
	}

	public IEnumerator WaitForMinimumSplashDuration()
	{
		float elapsed = UnityEngine.Time.time - startTime;
		float remaining = minSplashDuration - elapsed;
		if (remaining > 0f)
		{
			yield return new WaitForSeconds(remaining);
		}
	}
}
[RequireComponent(typeof(RectTransform))]
public class ThrobbingUIElement : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float maxThrobScale = 2f;

	[SerializeField]
	private float throbFrequency = 1f;

	private RectTransform thisTransform;

	private float startingScale;

	private float throbStartTime;

	private bool active;

	public bool Active
	{
		get
		{
			return active;
		}
		set
		{
			active = value;
			if (active)
			{
				throbStartTime = UnityEngine.Time.time;
			}
			if (thisTransform != null)
			{
				thisTransform.localScale = new Vector3(startingScale, startingScale);
			}
		}
	}

	private void Awake()
	{
		thisTransform = GetComponent<RectTransform>();
		startingScale = thisTransform.localScale.x;
		throbStartTime = UnityEngine.Time.time;
	}

	private void Update()
	{
		if (Active)
		{
			float num = startingScale + Mathf.Abs(Mathf.Sin((float)Math.PI * throbFrequency * (UnityEngine.Time.time - throbStartTime))) * (maxThrobScale * startingScale);
			thisTransform.localScale = new Vector3(num, num);
		}
	}
}
