namespace RecRoom.AGUI
{
	public class ToolMenuProjector : MenuProjector
	{
		public enum ToolMenuAnimationState
		{
			Hidden,
			Hydrate,
			Visible,
			Dehydrate,
			PlayerMenu_Transition,
			PlayerMenu_Refresh
		}

		[SerializeField]
		private Transform menuAnchor;

		[SerializeField]
		private GameObject projectionRoot;

		[SerializeField]
		private GameObject screenRoot;

		[SerializeField]
		private Renderer projectionRenderer;

		[SerializeField]
		private WatchGazeTracker.GazeParameters menuOpenParameters;

		[SerializeField]
		private WatchGazeTracker.GazeParameters menuCloseParameters;

		[SerializeField]
		private float menuDistanceFromProjectionRoot = 0.1f;

		[SerializeField]
		private WatchVisual dwellVisual;

		[SerializeField]
		private Transform sharedMenuRoot;

		[SerializeField]
		private Transform localMenuRoot;

		[SerializeField]
		private Transform remoteMenuRoot;

		[SerializeField]
		private bool menuOpenDwellEnabled = true;

		[SerializeField]
		private float menuOpenDwellDuration = 1f;

		[SerializeField]
		private bool detachMenuOnUnlockButtonPressed = true;

		[SerializeField]
		private bool dismissMenuWhenNotGazing = true;

		private float menuInteractionPausedEndTime;

		private Coroutine menuInteractionPauseRoutine;

		private bool dwellingOnMenu;

		private bool dwellAllowed = true;

		private float dwellStartTime;

		private bool forcedOpenUntilGazed;

		private float lastForceOpenTime;

		private Dictionary<int, ToolMenuAnimationState> hashStateDictionary = new Dictionary<int, ToolMenuAnimationState>();

		[NonSerialized]
		public bool GazeOpenSupported = true;

		public bool ForceMenuClose;

		private SynchronizedField<bool> _isMenuVisible;

		private SynchronizedField<bool, Vector3, Quaternion> _projectorDetachInfo;

		private Animator Animator { get; set; }

		public Tool Tool { get; private set; }

		public bool IsMenuOpen { get; private set; }

		public bool DismissMenuWhenNotGazing
		{
			get
			{
				return dismissMenuWhenNotGazing;
			}
			set
			{
				dismissMenuWhenNotGazing = value;
			}
		}

		public bool IsMenuVisible
		{
			get
			{
				return _isMenuVisible.Get();
			}
			set
			{
				_isMenuVisible.Set(value);
			}
		}

		public bool IsAttachedToTool => !_projectorDetachInfo.Get1();

		public Vector3 DetachedPosition => Tool.Owner.TrackingSpace.transform.TransformPoint(_projectorDetachInfo.Get2());

		public Quaternion DetachedRotation => Tool.Owner.TrackingSpace.transform.TransformRotation(_projectorDetachInfo.Get3());

		public bool IsMenuAnimationVisible => MenuAnimationState != ToolMenuAnimationState.Hidden;

		public ToolMenuAnimationState MenuAnimationState
		{
			get
			{
				if (Animator != null && Animator.gameObject.activeInHierarchy)
				{
					int shortNameHash = Animator.GetCurrentAnimatorStateInfo(0).shortNameHash;
					return hashStateDictionary[shortNameHash];
				}
				return ToolMenuAnimationState.Hidden;
			}
		}

		private bool AnyToolInput => Tool.InputAmount > 0.01f;

		private bool ShouldDismissMenu => ForceMenuClose || (IsAttachedToTool && !forcedOpenUntilGazed && dismissMenuWhenNotGazing && (!Tool.IsVisible || (AnyToolInput && UnityEngine.Time.time - lastForceOpenTime > 1.5f) || !GazingAtMenu(menuCloseParameters)));

		private void Awake()
		{
			Animator = base.gameObject.GetComponent<Animator>();
			ToolMenuAnimationState[] array = (ToolMenuAnimationState[])System.Enum.GetValues(typeof(ToolMenuAnimationState));
			for (int i = 0; i < array.Length; i++)
			{
				ToolMenuAnimationState value = array[i];
				string text = value.ToString();
				int key = Animator.StringToHash(text);
				hashStateDictionary[key] = value;
			}
			Tool = base.gameObject.GetComponentInParent<Tool>();
			Tool.PostPickupEvent += OnToolPickup;
			Tool.PreReleaseEvent += OnToolRelease;
			Tool.PostResetEvent += OnToolReset;
			menuOpenParameters.CalculateDotProductThresholds();
			menuCloseParameters.CalculateDotProductThresholds();
			_isMenuVisible = new SynchronizedField<bool>(Tool, "MTF_MV", defaultValue: false, SetterPermissionMode.ANYONE, OnMenuVisibleChanged);
			_projectorDetachInfo = new SynchronizedField<bool, Vector3, Quaternion>(Tool, "MTF_MD", defaultVal1: false, Vector3.zero, Quaternion.identity, SetterPermissionMode.ANYONE, OnProjectorDetachInfoChanged);
			Player.PlayerDestroyedEvent += new Action<Player>(OnPlayerDestroyed);
		}

		private void OnDestroy()
		{
			Player.PlayerDestroyedEvent -= new Action<Player>(OnPlayerDestroyed);
			if (Tool != null)
			{
				Tool.PostPickupEvent -= OnToolPickup;
				Tool.PreReleaseEvent -= OnToolRelease;
				Tool.PostResetEvent -= OnToolReset;
			}
		}

		private void Update()
		{
			ToolMenuAnimationState menuAnimationState = MenuAnimationState;
			if (sharedMenuRoot.gameObject.activeSelf && menuAnimationState == ToolMenuAnimationState.Hidden)
			{
				sharedMenuRoot.gameObject.SetActive(value: false);
			}
			else if (!sharedMenuRoot.gameObject.activeSelf && (menuAnimationState == ToolMenuAnimationState.Hydrate || menuAnimationState == ToolMenuAnimationState.Visible))
			{
				sharedMenuRoot.gameObject.SetActive(value: true);
			}
			if (Tool.IsHeldByPlayer && Tool.HolderHand != null)
			{
				if (IsAttachedToTool && IsMenuAnimationVisible)
				{
					projectionRoot.transform.position = base.transform.position;
					projectionRoot.transform.rotation = base.transform.rotation;
					screenRoot.transform.position = base.transform.position - base.transform.forward * menuDistanceFromProjectionRoot;
					screenRoot.transform.rotation = base.transform.rotation;
				}
				if (Tool.Owner.isLocal)
				{
					if (IsMenuOpen)
					{
						if (ShouldDismissMenu)
						{
							IsMenuVisible = false;
						}
						else if (forcedOpenUntilGazed && GazingAtMenu(menuOpenParameters))
						{
							forcedOpenUntilGazed = false;
						}
					}
					else if (menuOpenDwellEnabled && !ForceMenuClose)
					{
						UpdateMenuOpening();
					}
				}
				else
				{
					RefreshMenuPosition();
				}
			}
			Tool tool = ((!(Tool.ParentTool != null)) ? Tool : Tool.ParentTool);
			if (tool.PlayerSpawnedEquipment == null || tool.PlayerSpawnedEquipment.IsMine)
			{
				Tool.Menu.FullyVisible = MenuAnimationState == ToolMenuAnimationState.Visible;
			}
		}

		private void UpdateMenuOpening()
		{
			if (!dwellingOnMenu)
			{
				if (dwellVisual != null)
				{
					dwellVisual.ResetDwellVisual();
				}
				if (!GazingAtMenu(menuOpenParameters))
				{
					dwellAllowed = true;
				}
				else if (Tool.IsVisible && !AnyToolInput && dwellAllowed)
				{
					dwellingOnMenu = true;
					dwellStartTime = UnityEngine.Time.time;
				}
				return;
			}
			float num = Mathf.InverseLerp(dwellStartTime, dwellStartTime + menuOpenDwellDuration, UnityEngine.Time.time);
			if (dwellVisual != null)
			{
				dwellVisual.SetDwellVisualProgress(num);
			}
			if (!Tool.IsVisible || AnyToolInput || !GazingAtMenu(menuCloseParameters))
			{
				dwellingOnMenu = false;
			}
			else if (num >= 1f)
			{
				AuthorityAttachMenuToTool();
				IsMenuVisible = true;
				dwellingOnMenu = false;
				dwellAllowed = false;
				if (dwellVisual != null)
				{
					dwellVisual.ResetDwellVisual();
				}
			}
		}

		public void ForceMenuOpenUntilGazed()
		{
			if (!IsMenuOpen)
			{
				forcedOpenUntilGazed = true;
				IsMenuVisible = true;
			}
			lastForceOpenTime = UnityEngine.Time.time;
		}

		private bool GazingAtMenu(WatchGazeTracker.GazeParameters parameters)
		{
			if (!Tool.IsHeld)
			{
				return false;
			}
			if (!GazeOpenSupported)
			{
				return false;
			}
			Vector3 normalized = (menuAnchor.position - Tool.Owner.Head.transform.position).normalized;
			Vector3 forward = Tool.Owner.Head.transform.forward;
			Vector3 forward2 = menuAnchor.forward;
			Vector3 up = menuAnchor.up;
			Vector3 up2 = Tool.Owner.Head.transform.up;
			float num = Vector3.Dot(normalized, forward);
			float num2 = Vector3.Dot(normalized, forward2);
			float num3 = Vector3.Dot(up, up2);
			return num >= parameters.MaxFovDot && num2 >= parameters.MaxPitchDot && num3 >= parameters.MaxRollDot;
		}

		private void OnMenuVisibleChanged()
		{
			if (IsMenuVisible)
			{
				RefreshMenuPosition();
				OpenMenu();
			}
			else
			{
				CloseMenu();
			}
		}

		public void OpenMenu()
		{
			if (!IsMenuOpen)
			{
				IsMenuOpen = true;
				SetMenuRootState(enable: true);
				Animator.SetBool("Visible", value: true);
			}
		}

		public void CloseMenu()
		{
			if (IsMenuOpen)
			{
				IsMenuOpen = false;
				Animator.SetBool("Visible", value: false);
			}
		}

		private void SetMenuRootState(bool enable)
		{
			if (Tool == null)
			{
				UnityEngine.Debug.LogWarningFormat("Unable to enable menu objects on ToolMenuProjector {0}. Tool is null.", this);
				return;
			}
			bool flag = ((!(Tool.PlayerSpawnedEquipment == null)) ? Tool.PlayerSpawnedEquipment.IsMine : (Tool.owner != null && Tool.owner.IsLocal));
			sharedMenuRoot.gameObject.SetActive(enable);
			localMenuRoot.gameObject.SetActive(enable && flag);
			remoteMenuRoot.gameObject.SetActive(enable && !flag);
		}

		private void OnToolReset(Tool thisTool, Vector3 resetPosition, Quaternion resetRotation, Vector3 oldPosition, bool wasCleanedUp)
		{
			if (IsMenuOpen)
			{
				IsMenuVisible = false;
			}
		}

		private void OnToolPickup(Tool tool)
		{
			if (tool.HolderHand != null)
			{
				tool.HolderHand.ToolUnlockBehaviorOverride = UnlockButtonPressedOverride;
			}
		}

		private void OnToolRelease(Tool tool)
		{
			if (tool.HolderHand != null)
			{
				tool.HolderHand.ToolUnlockBehaviorOverride = null;
			}
			if (IsMenuOpen && detachMenuOnUnlockButtonPressed)
			{
				IsMenuVisible = false;
			}
			AuthorityAttachMenuToTool();
		}

		private bool UnlockButtonPressedOverride()
		{
			if (detachMenuOnUnlockButtonPressed && IsMenuOpen)
			{
				if (IsAttachedToTool)
				{
					AuthorityDetachMenuFromTool(base.transform.position, base.transform.rotation);
				}
				else
				{
					IsMenuVisible = false;
					AuthorityAttachMenuToTool();
				}
				return true;
			}
			return false;
		}

		public void AuthorityDetachMenuFromTool()
		{
			AuthorityDetachMenuFromTool(base.OptimalDetachedMenuPositionWorldSpace, base.OptimalDetachedMenuRotationWorldSpace);
		}

		public void AuthorityDetachMenuFromTool(Vector3 detachPositionWorldSpace, Quaternion detachRotationWorldSpace)
		{
			if (Tool.hasAuthority && Tool.Owner != null)
			{
				Vector3 newValue = Tool.Owner.TrackingSpace.RigidbodyEx.TargetTransform.InverseTransformPoint(detachPositionWorldSpace);
				Quaternion newValue2 = Tool.Owner.TrackingSpace.RigidbodyEx.TargetTransform.InverseTransformRotation(detachRotationWorldSpace);
				_projectorDetachInfo.Set(newValue1: true, newValue, newValue2);
			}
		}

		public void AuthorityAttachMenuToTool()
		{
			if (Tool.hasAuthority)
			{
				_projectorDetachInfo.Set(newValue1: false, Vector3.zero, Quaternion.identity);
			}
		}

		private void OnProjectorDetachInfoChanged()
		{
			if (!(this == null))
			{
				if (IsAttachedToTool)
				{
					base.transform.SetParent(menuAnchor);
				}
				else
				{
					base.transform.SetParent(Tool.Owner.TrackingSpace.transform);
				}
				if (projectionRenderer != null)
				{
					projectionRenderer.gameObject.SetActive(IsAttachedToTool);
				}
			}
		}

		private void RefreshMenuPosition()
		{
			if (!(this == null))
			{
				if (!IsAttachedToTool)
				{
					base.transform.position = DetachedPosition;
					base.transform.rotation = DetachedRotation;
				}
				else
				{
					base.transform.localPosition = Vector3.zero;
					base.transform.localRotation = Quaternion.identity;
				}
			}
		}

		private void OnPlayerDestroyed(Player destroyedPlayer)
		{
			if (Tool.PreviousNonNullHolderPlayer != null && Tool.PreviousNonNullHolderPlayer == destroyedPlayer)
			{
				AuthorityAttachMenuToTool();
				base.transform.SetParent(menuAnchor, worldPositionStays: false);
				CloseMenu();
				Animator.enabled = true;
				UnityEngine.MonoBehaviour[] components = GetComponents<UnityEngine.MonoBehaviour>();
				foreach (UnityEngine.MonoBehaviour monoBehaviour in components)
				{
					monoBehaviour.enabled = true;
				}
			}
		}

		public void TemporarilyPauseMenuInteraction(float duration)
		{
			menuInteractionPausedEndTime = Mathf.Max(UnityEngine.Time.time + duration, menuInteractionPausedEndTime);
			this.SafeStopCoroutine(menuInteractionPauseRoutine);
			menuInteractionPauseRoutine = StartCoroutine(RunTemporaryDisableMenuInteraction(menuInteractionPausedEndTime - UnityEngine.Time.time));
		}

		private IEnumerator RunTemporaryDisableMenuInteraction(float duration)
		{
			ToolUI toolMenu = Tool.GetComponentInChildren<ToolUI>();
			if (toolMenu != null)
			{
				toolMenu.BasicInteractionRestriction.AllElementsRestricted = true;
				yield return new WaitForSeconds(duration);
				toolMenu.BasicInteractionRestriction.AllElementsRestricted = false;
			}
		}
	}
}
[DisallowMultipleComponent]
public class Tooltip : UnityEngine.MonoBehaviour
{
	public Action<Tooltip> RefreshEvent;

	public string Message = "Hello";

	public float ShowDelay = 0.75f;

	[Tooltip("Ignore the interactable state of the selectable when deciding whether to pop tooltip (useful when using Slider as progress bar)")]
	public bool IgnoreSelectable;

	[SerializeField]
	private TooltipUI.FontConfig fontConfig;

	private TooltipUI tooltipUI;

	private Coroutine monitorHoverRoutine;

	private bool isHovered;

	private Transform cursor;

	public bool Hovered { get; set; }

	private void OnDisable()
	{
		Hide();
	}

	public void SetHoverPoint(Transform hoveredCursor)
	{
		if (base.gameObject.activeInHierarchy && base.enabled)
		{
			isHovered = true;
			if (cursor == null)
			{
				cursor = hoveredCursor;
			}
			if (monitorHoverRoutine == null)
			{
				monitorHoverRoutine = StartCoroutine(MonitorHoverRoutine());
			}
		}
	}

	private void Hide()
	{
		if (tooltipUI != null)
		{
			tooltipUI.Release();
			tooltipUI = null;
		}
		cursor = null;
		this.SafeStopCoroutine(monitorHoverRoutine);
		monitorHoverRoutine = null;
	}

	private void Show(Vector3 position, Quaternion rotation)
	{
		if (tooltipUI == null)
		{
			tooltipUI = TooltipUI.Acquire(Message, position, rotation);
			tooltipUI.CurrentFontConfig = fontConfig;
		}
	}

	private IEnumerator MonitorHoverRoutine()
	{
		float hoverStartTime = UnityEngine.Time.time;
		while (true)
		{
			yield return new WaitForEndOfFrame();
			if (!isHovered || cursor == null || !cursor.gameObject.activeSelf)
			{
				break;
			}
			Vector3 position = cursor.position;
			Vector3 rotationEuler = cursor.rotation.eulerAngles;
			rotationEuler.z = 0f;
			Quaternion rotation = Quaternion.Euler(rotationEuler);
			if (tooltipUI != null)
			{
				tooltipUI.transform.position = position;
				tooltipUI.transform.rotation = rotation;
			}
			else if (UnityEngine.Time.time - hoverStartTime >= ShowDelay)
			{
				Show(position, rotation);
			}
			isHovered = false;
		}
		Hide();
	}

	internal void Refresh()
	{
		if (RefreshEvent != null)
		{
			RefreshEvent(this);
		}
	}
}
public class TooltipUI : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class FontConfig
	{
		public Font Font;

		[Range(1f, 124f)]
		public int FontSize = 20;
	}

	public static List<TooltipUI> All = new List<TooltipUI>();

	[SerializeField]
	private TextMesh textMesh;

	[SerializeField]
	private Transform background;

	[SerializeField]
	private Vector2 backgroundHorizontalPadding = new Vector2(0.05f, 0.05f);

	[SerializeField]
	private AnimationCurve sizeOverDistanceCurve;

	private Renderer textRenderer;

	private Renderer backgroundRenderer;

	private float defaultTextAlpha;

	private float defaultBackgroundAlpha;

	private FontConfig defaultFontConfig;

	private float fadeSpeed = 10f;

	public string Message
	{
		get
		{
			return textMesh.text;
		}
		set
		{
			textMesh.text = value;
			StartCoroutine(RunUpdateBoundsSize());
		}
	}

	public FontConfig CurrentFontConfig
	{
		set
		{
			FontConfig fontConfig = value;
			if (fontConfig == null || fontConfig.Font == null)
			{
				fontConfig = defaultFontConfig;
			}
			textMesh.font = fontConfig.Font;
			textMesh.fontSize = fontConfig.FontSize;
			textRenderer.material.mainTexture = textMesh.font.material.mainTexture;
		}
	}

	private void Awake()
	{
		All.Add(this);
		base.gameObject.SetActive(value: false);
		textRenderer = textMesh.GetComponent<Renderer>();
		textRenderer.material.renderQueue = 10000;
		defaultFontConfig = new FontConfig
		{
			Font = textMesh.font,
			FontSize = textMesh.fontSize
		};
		backgroundRenderer = background.GetComponent<Renderer>();
		backgroundRenderer.material.renderQueue = 9999;
		defaultTextAlpha = textRenderer.material.color.a;
		defaultBackgroundAlpha = backgroundRenderer.material.color.a;
	}

	private void OnDestroy()
	{
		All.Remove(this);
	}

	private void OnDisable()
	{
		if (textRenderer != null)
		{
			textRenderer.SetColorAlpha(0f);
			backgroundRenderer.SetColorAlpha(0f);
		}
	}

	private IEnumerator RunUpdateBoundsSize()
	{
		yield return null;
		Vector3 scale = base.transform.localScale;
		base.transform.localScale = Vector3.one;
		Quaternion rotation = textMesh.transform.rotation;
		textMesh.transform.rotation = Quaternion.identity;
		Bounds bounds = textRenderer.bounds;
		Vector3 boundsSize = bounds.size;
		textMesh.transform.rotation = rotation;
		base.transform.localScale = scale;
		background.transform.localScale = new Vector3(boundsSize.x + backgroundHorizontalPadding.x, boundsSize.y + backgroundHorizontalPadding.y, boundsSize.z);
		Vector3 localBackgroundPosition = textMesh.transform.InverseTransformPoint(bounds.center);
		localBackgroundPosition.z = 0f;
		background.transform.localPosition = localBackgroundPosition;
	}

	public static TooltipUI Acquire(string message, Vector3 initialPosition, Quaternion initialRotation)
	{
		foreach (TooltipUI item in All)
		{
			if (item != null && !item.gameObject.activeSelf)
			{
				float magnitude = (SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position - initialPosition).magnitude;
				float num = item.sizeOverDistanceCurve.Evaluate(magnitude);
				item.transform.position = initialPosition;
				item.transform.rotation = initialRotation;
				item.transform.localScale = new Vector3(num, num, num);
				item.gameObject.SetActive(value: true);
				item.Message = message.Replace("\\n", Environment.NewLine);
				item.StartCoroutine(item.RunFadeIn());
				return item;
			}
		}
		return null;
	}

	public void Release()
	{
		base.gameObject.SetActive(value: false);
	}

	private IEnumerator RunFadeIn()
	{
		float t = 0f;
		while (t < 1f)
		{
			t = Mathf.SmoothStep(t, 1f, UnityEngine.Time.deltaTime * fadeSpeed);
			textRenderer.SetColorAlpha(defaultTextAlpha * t);
			backgroundRenderer.SetColorAlpha(defaultBackgroundAlpha * t);
			yield return null;
		}
	}
}
