namespace RecRoom.Core.UI
{
	public class UIInputModule : BaseInputModule
	{
		public struct UIInputResult
		{
			public GameObject UIEnteredObject;

			public Vector3? UIRaycastPosition;

			public Vector3 UIRaycastHitNormal;

			public PhysicalButtonBase LaserPushButton;

			public RaycastHit? LaserPushButtonHit;

			public bool UISelectable;
		}

		public static UIInputModule Instance;

		private const float MIN_LASER_PUSH_BUTTON_DISTANCE = 0.2f;

		private const float CONTROLLER_CAMERA_FAR_CLIP = 20f;

		[Tooltip("Generated cursors")]
		public Transform[] Cursors;

		private GameObject[] CurrentPoint;

		private GameObject[] CurrentPressed;

		private GameObject[] CurrentDragging;

		private PointerEventData[] PointEvents;

		[Tooltip("Generated non rendering camera (used for raycasting ui)")]
		public Camera ControllerCamera;

		[SerializeField]
		private int maxCursorCount = 2;

		[Tooltip("AG : max UI interaction angle from head look direction")]
		public float MaxUIHeadAngle = 40f;

		protected override void Awake()
		{
			base.Awake();
			Instance = this;
			ControllerCamera = new GameObject("Controller UI Camera").AddComponent<Camera>();
			UnityEngine.Object.DontDestroyOnLoad(ControllerCamera);
			ControllerCamera.clearFlags = CameraClearFlags.Nothing;
			ControllerCamera.cullingMask = 0;
			ControllerCamera.stereoTargetEye = StereoTargetEyeMask.None;
			ControllerCamera.nearClipPlane = 0.01f;
			ControllerCamera.farClipPlane = 20f;
			ControllerCamera.enabled = false;
			ControllerCamera.depth = -100f;
			Cursors = new Transform[maxCursorCount];
			for (int i = 0; i < Cursors.Length; i++)
			{
				GameObject gameObject = new GameObject("Cursor " + i);
				UnityEngine.Object.DontDestroyOnLoad(gameObject);
				Cursors[i] = gameObject.GetComponent<Transform>();
			}
			CurrentPoint = new GameObject[Cursors.Length];
			CurrentPressed = new GameObject[Cursors.Length];
			CurrentDragging = new GameObject[Cursors.Length];
			PointEvents = new PointerEventData[Cursors.Length];
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (ControllerCamera != null)
			{
				UnityEngine.Object.Destroy(ControllerCamera.gameObject);
			}
			for (int i = 0; i < Cursors.Length; i++)
			{
				if (Cursors[i] != null)
				{
					UnityEngine.Object.Destroy(Cursors[i].gameObject);
				}
			}
		}

		private static int RaycastResultComparer(RaycastResult a, RaycastResult b)
		{
			float num = Mathf.Abs(a.distance - b.distance);
			if (num >= 0.0001f)
			{
				return a.distance.CompareTo(b.distance);
			}
			return b.depth.CompareTo(a.depth);
		}

		private static RaycastResult FindClosestRaycast(List<RaycastResult> results)
		{
			results.Sort(RaycastResultComparer);
			return BaseInputModule.FindFirstRaycast(results);
		}

		private bool GetLookPointerEventData(int index, float maxUIInteractionDistance, bool testAgainstHeadAngle, bool uiInteractionEnabled, ref UIInputResult result)
		{
			if (PointEvents[index] == null)
			{
				PointEvents[index] = new PointerEventData(base.eventSystem);
			}
			else
			{
				PointEvents[index].Reset();
			}
			PointEvents[index].delta = Vector2.zero;
			PointEvents[index].position = new Vector2(Screen.width / 2, Screen.height / 2);
			PointEvents[index].scrollDelta = Vector2.zero;
			bool flag = false;
			if (uiInteractionEnabled)
			{
				base.eventSystem.RaycastAll(PointEvents[index], m_RaycastResultCache);
				PointEvents[index].pointerCurrentRaycast = FindClosestRaycast(m_RaycastResultCache);
				if (PointEvents[index].pointerCurrentRaycast.gameObject != null)
				{
					RectTransform component = PointEvents[index].pointerCurrentRaycast.gameObject.GetComponent<RectTransform>();
					bool flag2 = false;
					Vector3 worldPoint;
					if (PointEvents[index].pointerCurrentRaycast.worldPosition != Vector3.zero)
					{
						flag2 = true;
						worldPoint = PointEvents[index].pointerCurrentRaycast.worldPosition;
					}
					else if (RectTransformUtility.ScreenPointToWorldPointInRectangle(component, PointEvents[index].position, PointEvents[index].enterEventCamera, out worldPoint))
					{
						flag2 = true;
					}
					if (flag2)
					{
						Vector3 vector = worldPoint - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
						Vector3 forward = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.forward;
						float distance = PointEvents[index].pointerCurrentRaycast.distance;
						if (distance < maxUIInteractionDistance && (!testAgainstHeadAngle || Vector3.Angle(vector, forward) < MaxUIHeadAngle) && !Physics.Raycast(ControllerCamera.transform.position, ControllerCamera.transform.forward, distance - 0.1f, 495336448, QueryTriggerInteraction.Ignore))
						{
							flag = true;
						}
					}
				}
			}
			if (!flag)
			{
				PointEvents[index].pointerCurrentRaycast = default(RaycastResult);
			}
			result.UISelectable = false;
			if (PointEvents[index].pointerCurrentRaycast.isValid)
			{
				bool flag3 = false;
				foreach (GameObject item in PointEvents[index].hovered)
				{
					if (!(item != null))
					{
						continue;
					}
					Selectable component2 = item.gameObject.GetComponent<Selectable>();
					bool flag4 = true;
					if (component2 != null)
					{
						if (component2.IsInteractable())
						{
							result.UISelectable = true;
						}
						else
						{
							flag4 = false;
						}
					}
					if (!flag3)
					{
						Tooltip component3 = item.gameObject.GetComponent<Tooltip>();
						if (component3 != null && (flag4 || component3.IgnoreSelectable))
						{
							component3.SetHoverPoint(Cursors[index]);
							flag3 = true;
						}
					}
				}
			}
			m_RaycastResultCache.Clear();
			return true;
		}

		private void UpdateCursor(int index, Vector3 laserStartPosition, PointerEventData pointData, ref UIInputResult result)
		{
			if (PointEvents[index].pointerCurrentRaycast.gameObject != null)
			{
				Cursors[index].gameObject.SetActive(value: true);
				if (pointData.pointerEnter != null)
				{
					RectTransform component = pointData.pointerEnter.GetComponent<RectTransform>();
					Vector3 worldPoint = Vector3.zero;
					Quaternion rotation = Quaternion.identity;
					bool flag = false;
					if (pointData.pointerCurrentRaycast.worldPosition != Vector3.zero)
					{
						flag = true;
						worldPoint = pointData.pointerCurrentRaycast.worldPosition;
						rotation = Quaternion.LookRotation(pointData.pointerCurrentRaycast.worldNormal);
					}
					else if (RectTransformUtility.ScreenPointToWorldPointInRectangle(component, pointData.position, pointData.enterEventCamera, out worldPoint))
					{
						flag = true;
						rotation = component.rotation;
					}
					if (flag)
					{
						Cursors[index].position = worldPoint;
						Cursors[index].rotation = rotation;
						result.UIRaycastPosition = worldPoint;
						result.UIEnteredObject = pointData.pointerEnter;
						result.UIRaycastHitNormal = pointData.pointerCurrentRaycast.worldNormal;
					}
				}
			}
			else if (result.LaserPushButtonHit.HasValue)
			{
				Cursors[index].gameObject.SetActive(value: true);
				Cursors[index].position = result.LaserPushButtonHit.Value.point;
				Cursors[index].rotation = Quaternion.LookRotation(result.LaserPushButtonHit.Value.normal);
				result.UIRaycastPosition = result.LaserPushButtonHit.Value.point;
				result.UIEnteredObject = result.LaserPushButtonHit.Value.collider.gameObject;
				result.UIRaycastHitNormal = result.LaserPushButtonHit.Value.normal;
				result.UISelectable = true;
			}
			else
			{
				Cursors[index].gameObject.SetActive(value: false);
				result.UIRaycastPosition = null;
				result.UIEnteredObject = null;
			}
		}

		private bool SendUpdateEventToSelectedObject()
		{
			if (base.eventSystem.currentSelectedGameObject == null)
			{
				return false;
			}
			BaseEventData baseEventData = GetBaseEventData();
			ExecuteEvents.Execute(base.eventSystem.currentSelectedGameObject, baseEventData, ExecuteEvents.updateSelectedHandler);
			return baseEventData.used;
		}

		private void Update()
		{
			UpdateModule();
		}

		public override void Process()
		{
		}

		public void GetNewResults(int cursorId, bool uiInteractionEnabled, Vector3 position, Vector3 forward, float maxUIInteractDistance, float maxPushButtonDistance, bool testAngleFromHead, out UIInputResult result)
		{
			result = default(UIInputResult);
			SendUpdateEventToSelectedObject();
			if (cursorId < 0 || cursorId >= Cursors.Length)
			{
				return;
			}
			ControllerCamera.transform.position = position;
			ControllerCamera.transform.forward = forward;
			if (!GetLookPointerEventData(cursorId, maxUIInteractDistance, testAngleFromHead, uiInteractionEnabled, ref result))
			{
				return;
			}
			CurrentPoint[cursorId] = PointEvents[cursorId].pointerCurrentRaycast.gameObject;
			HandlePointerExitAndEnter(PointEvents[cursorId], CurrentPoint[cursorId]);
			RaycastHit? laserPushButtonHit = null;
			if (!PointEvents[cursorId].pointerCurrentRaycast.isValid)
			{
				int layerMask = -33285;
				RaycastHit hit;
				CollisionDetection.CollisionResult collisionResult = CollisionDetection.Raycast(position, forward, maxPushButtonDistance, layerMask, PushButtonCollisionFilter, QueryTriggerInteraction.Collide, out hit);
				if (collisionResult == CollisionDetection.CollisionResult.HIT && hit.distance >= 0.2f && Vector3.Dot(hit.transform.up, forward) < 0f)
				{
					laserPushButtonHit = hit;
					result.LaserPushButton = hit.collider.GetComponent<PhysicalButtonBase>();
				}
			}
			result.LaserPushButtonHit = laserPushButtonHit;
			UpdateCursor(cursorId, position, PointEvents[cursorId], ref result);
		}

		public void SendButtonInput(int cursorId, bool buttonDown, bool buttonUp)
		{
			if (cursorId < 0 || cursorId >= Cursors.Length)
			{
				return;
			}
			if (buttonDown)
			{
				PointEvents[cursorId].pressPosition = PointEvents[cursorId].position;
				PointEvents[cursorId].pointerPressRaycast = PointEvents[cursorId].pointerCurrentRaycast;
				PointEvents[cursorId].pointerPress = null;
				if (CurrentPoint[cursorId] != null)
				{
					CurrentPressed[cursorId] = CurrentPoint[cursorId];
					GameObject gameObject = ExecuteEvents.ExecuteHierarchy(CurrentPressed[cursorId], PointEvents[cursorId], ExecuteEvents.pointerDownHandler);
					if (gameObject == null)
					{
						gameObject = ExecuteEvents.ExecuteHierarchy(CurrentPressed[cursorId], PointEvents[cursorId], ExecuteEvents.pointerClickHandler);
						if (gameObject != null)
						{
							CurrentPressed[cursorId] = gameObject;
						}
					}
					else
					{
						CurrentPressed[cursorId] = gameObject;
						ExecuteEvents.Execute(gameObject, PointEvents[cursorId], ExecuteEvents.pointerClickHandler);
					}
					if (gameObject != null)
					{
						PointEvents[cursorId].pointerPress = gameObject;
						CurrentPressed[cursorId] = gameObject;
					}
					ExecuteEvents.Execute(CurrentPressed[cursorId], PointEvents[cursorId], ExecuteEvents.beginDragHandler);
					PointEvents[cursorId].pointerDrag = CurrentPressed[cursorId];
					CurrentDragging[cursorId] = CurrentPressed[cursorId];
				}
			}
			if (buttonUp)
			{
				if ((bool)CurrentDragging[cursorId])
				{
					ExecuteEvents.Execute(CurrentDragging[cursorId], PointEvents[cursorId], ExecuteEvents.endDragHandler);
					if (CurrentPoint[cursorId] != null)
					{
						ExecuteEvents.ExecuteHierarchy(CurrentPoint[cursorId], PointEvents[cursorId], ExecuteEvents.dropHandler);
					}
					PointEvents[cursorId].pointerDrag = null;
					CurrentDragging[cursorId] = null;
				}
				if ((bool)CurrentPressed[cursorId])
				{
					ExecuteEvents.Execute(CurrentPressed[cursorId], PointEvents[cursorId], ExecuteEvents.pointerUpHandler);
					PointEvents[cursorId].rawPointerPress = null;
					PointEvents[cursorId].pointerPress = null;
					CurrentPressed[cursorId] = null;
				}
			}
			if (CurrentDragging[cursorId] != null)
			{
				ExecuteEvents.Execute(CurrentDragging[cursorId], PointEvents[cursorId], ExecuteEvents.dragHandler);
			}
		}

		private bool PushButtonCollisionFilter(Collider collider)
		{
			return collider.GetComponent<PhysicalButtonBase>();
		}
	}
}
public class UIProjector : ProjectorBase
{
	[Header("UI View")]
	[SerializeField]
	private Canvas viewPrefab;

	[SerializeField]
	private Transform viewParent;

	[Header("Active Modes")]
	[SerializeField]
	private ModeRestriction.GameMode supportedModes = ModeRestriction.GameMode.ALL;

	[SerializeField]
	private GameModeType[] dontOpenInGameModes;

	[Header("Screens Transforms")]
	[SerializeField]
	private Transform screensGazeTargetTransform;

	[SerializeField]
	private Transform screensCameraPositionTransform;

	private Canvas uiView;

	public Transform ScreensGazeTargetTransform => screensGazeTargetTransform;

	public Transform ScreensCameraPositionTransform => screensCameraPositionTransform;

	protected override void Awake()
	{
		base.Awake();
		uiView = UnityEngine.Object.Instantiate(viewPrefab);
		uiView.transform.SetParent(viewParent, worldPositionStays: false);
		uiView.transform.localPosition = Vector3.zero;
		uiView.transform.localRotation = Quaternion.identity;
		if ((bool)uiView.gameObject.GetComponent<CachedView>())
		{
			uiView = null;
		}
	}

	protected override void Update()
	{
		base.Update();
		if (!Player.LocalPlayerExists)
		{
			return;
		}
		if (uiView == null)
		{
			ImposterGraphicRaycaster componentInChildren = GetComponentInChildren<ImposterGraphicRaycaster>();
			if (componentInChildren != null)
			{
				uiView = componentInChildren.gameObject.GetComponent<Canvas>();
			}
		}
		if (uiView != null)
		{
			uiView.gameObject.SetActive(!base.FullyClosed);
		}
	}

	protected override bool CustomOpeningRestrictions()
	{
		GameManager instance = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
		return ModeRestriction.IsSupported(supportedModes) && (instance == null || instance.CurrentMode == null || !dontOpenInGameModes.Contains(instance.CurrentMode.ModeType)) && NetworkedSingletonMonoBehaviour<HostManager>.Instance.AllowScoreboards;
	}
}
public class WorldSpaceNotification : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RectTransform notificationRoot;

	[SerializeField]
	private ScreenSpaceNotification.NotificationText title;

	[SerializeField]
	private ScreenSpaceNotification.NotificationText subtitle;

	[SerializeField]
	private FloatValueCurve alphaEaseInCurve;

	[SerializeField]
	private FloatValueCurve heightEaseInCurve;

	private Coroutine playCoroutine;

	private static WorldSpaceNotification _defaultNotificationPrefab;

	private float totalWaitDuration;

	private bool isActivePlaying;

	public bool IsPlaying => playCoroutine != null;

	public FollowTarget FollowTarget { get; private set; }

	public Color Color
	{
		set
		{
			title.Color = value;
			subtitle.Color = value;
		}
	}

	private static WorldSpaceNotification DefaultNotificationPrefab
	{
		get
		{
			if (_defaultNotificationPrefab == null)
			{
				_defaultNotificationPrefab = Resources.Load<WorldSpaceNotification>("[DefaultWorldSpaceNotification]");
			}
			return _defaultNotificationPrefab;
		}
	}

	private void Awake()
	{
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
		FollowTarget = GetComponent<FollowTarget>();
	}

	public void Stop()
	{
		if (playCoroutine != null)
		{
			StopCoroutine(playCoroutine);
			playCoroutine = null;
		}
		ObjectPool.Instance.Release(this);
		base.gameObject.SetActive(value: false);
	}

	public void Play(string titleText, float duration = 5f, string subtitleText = null, bool followPlayer = true, bool billboard = false)
	{
		if (playCoroutine != null)
		{
			StopCoroutine(playCoroutine);
			playCoroutine = null;
		}
		base.gameObject.SetActive(value: true);
		playCoroutine = StartCoroutine(PlayCoroutine(titleText, subtitleText, duration, followPlayer, billboard));
	}

	private IEnumerator PlayCoroutine(string titleText, string subtitleText, float duration, bool followPlayer, bool billboard, WorldSpaceNotification prefab = null)
	{
		isActivePlaying = true;
		title.Text.text = titleText;
		subtitle.Text.text = subtitleText;
		Vector3 up = Vector3.up;
		Vector3 forward = base.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
		if (!billboard)
		{
			forward = Vector3.ProjectOnPlane(forward, up).normalized;
		}
		if (FollowTarget == null || !followPlayer)
		{
			base.transform.rotation = Quaternion.LookRotation(forward, up);
		}
		float easeInDuration = alphaEaseInCurve.Duration;
		float easeOutDuration = alphaEaseInCurve.Duration;
		float waitDuration = Mathf.Max(0f, duration - easeInDuration - easeOutDuration);
		float startTime = UnityEngine.Time.time;
		float endTime = startTime + easeOutDuration;
		Vector3 initialPosition = base.transform.position;
		while (UnityEngine.Time.time <= endTime)
		{
			float t = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
			if (FollowTarget == null || !followPlayer)
			{
				base.transform.position = initialPosition + Vector3.up * heightEaseInCurve.Evaluate(t);
			}
			float alpha = alphaEaseInCurve.Evaluate(t);
			title.Alpha = alpha;
			subtitle.Alpha = alpha;
			yield return null;
		}
		title.Alpha = 1f;
		subtitle.Alpha = 1f;
		yield return WaitDuration(waitDuration);
		startTime = UnityEngine.Time.time;
		endTime = startTime + easeOutDuration;
		initialPosition = base.transform.position;
		while (UnityEngine.Time.time <= endTime)
		{
			float t2 = Mathf.InverseLerp(startTime, endTime, UnityEngine.Time.time);
			if (FollowTarget == null || !followPlayer)
			{
				base.transform.position = initialPosition + Vector3.down * heightEaseInCurve.Evaluate(t2);
			}
			float alpha2 = 1f - alphaEaseInCurve.Evaluate(t2);
			title.Alpha = alpha2;
			subtitle.Alpha = alpha2;
			yield return null;
		}
		title.Alpha = 0f;
		subtitle.Alpha = 0f;
		playCoroutine = null;
		ObjectPool.Instance.Release(this);
	}

	public bool RefreshNotificationText(string titleText, float duration, string subtitleText = null)
	{
		if (isActivePlaying)
		{
			title.Text.text = titleText;
			subtitle.Text.text = subtitleText;
			totalWaitDuration = duration;
			return true;
		}
		return false;
	}

	private IEnumerator WaitDuration(float waitDuration)
	{
		for (totalWaitDuration = waitDuration; totalWaitDuration > 0f; totalWaitDuration -= UnityEngine.Time.deltaTime)
		{
			yield return null;
		}
		isActivePlaying = false;
	}

	public static WorldSpaceNotification PlayNext(string titleText, float duration = 5f, string subtitleText = null, bool followPlayer = true, Vector3? worldSpacePosition = null, float scaleOverride = 1f, bool billboard = false)
	{
		return PlayNext(DefaultNotificationPrefab, titleText, duration, subtitleText, followPlayer, worldSpacePosition, scaleOverride, billboard);
	}

	public static WorldSpaceNotification PlayNext(WorldSpaceNotification prefab, string titleText, float duration = 5f, string subtitleText = null, bool followPlayer = true, Vector3? worldSpacePosition = null, float scaleOverride = 1f, bool billboard = false)
	{
		if (prefab == null)
		{
			prefab = DefaultNotificationPrefab;
		}
		WorldSpaceNotification worldSpaceNotification = ObjectPool.Instance.Acquire(prefab);
		if (worldSpaceNotification != null)
		{
			if (followPlayer && worldSpaceNotification.FollowTarget != null)
			{
				worldSpaceNotification.FollowTarget.Target = ((!Player.LocalPlayerExists) ? SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform : Player.LocalPlayer.Head.transform);
				worldSpaceNotification.FollowTarget.ForceUpdate();
			}
			else
			{
				worldSpaceNotification.transform.position = ((!worldSpacePosition.HasValue) ? (Player.LocalPlayer.Head.transform.position + Player.LocalPlayer.Head.transform.forward) : worldSpacePosition.Value);
				Vector3 vector = worldSpaceNotification.transform.position - SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position;
				if (!billboard)
				{
					vector = Vector3.ProjectOnPlane(vector, Vector3.up).normalized;
				}
				worldSpaceNotification.transform.rotation = Quaternion.LookRotation(vector, Vector3.up);
			}
			worldSpaceNotification.notificationRoot.localScale = Vector3.one * scaleOverride;
			worldSpaceNotification.Play(titleText, duration, subtitleText, followPlayer, billboard);
			return worldSpaceNotification;
		}
		return null;
	}
}
