namespace RecRoom.PNG
{
	public class PngEncoder
	{
		public static IPromise<byte[]> Encode(Texture2D texture, bool usePalette = false)
		{
			if (texture == null)
			{
				return new ErroredPromise<byte[]>("Null texture cannot be encoded");
			}
			if (usePalette)
			{
				return EncodePalettePNG(texture);
			}
			return EncodeStandardPNG(texture);
		}

		public static IPromise<ImageColors> Decode(byte[] bytes)
		{
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			backgroundWorker.DoWork += delegate(object sender, DoWorkEventArgs args)
			{
				MemoryStream inputStream = new MemoryStream(bytes);
				PngReader pngReader = new PngReader(inputStream);
				ImageInfo imgInfo = pngReader.ImgInfo;
				PngChunkPLTE pLTE = pngReader.GetMetadata().GetPLTE();
				PngChunkTRNS tRNS = pngReader.GetMetadata().GetTRNS();
				int[] array = null;
				List<Color>[] array2 = new List<Color>[imgInfo.Rows];
				for (int i = 0; i < imgInfo.Rows; i++)
				{
					List<Color> list = new List<Color>();
					ImageLine imageLine = pngReader.ReadRow(i);
					if (pLTE != null)
					{
						int num = ((tRNS == null) ? 3 : 4);
						array = ImageLineHelper.Palette2rgb(imageLine, pLTE, tRNS, array);
						for (int j = 0; j < array.Length; j += num)
						{
							int[] array3 = new int[num];
							array3[0] = array[j];
							array3[1] = array[j + 1];
							array3[2] = array[j + 2];
							if (num == 4)
							{
								array3[3] = array[j + 3];
							}
							list.Add(new IntColor(array3).Color);
						}
					}
					else
					{
						for (int k = 0; k < imgInfo.Cols; k++)
						{
							int num2 = k * imgInfo.Channels;
							int num3 = imageLine.Scanline[num2];
							int num4 = imageLine.Scanline[num2 + 1];
							int num5 = imageLine.Scanline[num2 + 2];
							int num6 = 255;
							if (imgInfo.Channels == 4)
							{
								num6 = imageLine.Scanline[num2 + 3];
							}
							IntColor intColor = new IntColor(new int[4] { num3, num4, num5, num6 });
							list.Add(intColor.Color);
						}
					}
					array2[imgInfo.Rows - i - 1] = list;
				}
				pngReader.End();
				List<Color> list2 = new List<Color>();
				for (int l = 0; l < array2.Length; l++)
				{
					list2.AddRange(array2[l]);
				}
				args.Result = new ImageColors
				{
					Colors = list2.ToArray(),
					Width = imgInfo.Cols,
					Height = imgInfo.Rows
				};
			};
			Promise<ImageColors> promise = new Promise<ImageColors>();
			backgroundWorker.RunWorkerCompleted += CreateWorkerCompletedEventHandler(promise);
			backgroundWorker.RunWorkerAsync();
			return promise;
		}

		private static IPromise<byte[]> EncodeStandardPNG(Texture2D texture)
		{
			Color[] pixels = texture.GetPixels();
			int width = texture.width;
			int height = texture.height;
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			backgroundWorker.DoWork += delegate(object sender, DoWorkEventArgs args)
			{
				ImageInfo imageInfo = new ImageInfo(width, height, 8, alpha: true);
				MemoryStream memoryStream = new MemoryStream();
				PngWriter pngWriter = new PngWriter(memoryStream, imageInfo);
				for (int num = imageInfo.Rows - 1; num >= 0; num--)
				{
					ImageLine imageLine = new ImageLine(imageInfo);
					for (int i = 0; i < imageInfo.Cols; i++)
					{
						IntColor intColor = new IntColor(pixels[num * imageInfo.Cols + i]);
						ImageLineHelper.SetPixel(imageLine, i, intColor.Red, intColor.Green, intColor.Blue, intColor.Alpha);
					}
					pngWriter.WriteRow(imageLine, imageInfo.Rows - num - 1);
				}
				pngWriter.End();
				byte[] result = memoryStream.ToArray();
				args.Result = result;
			};
			Promise<byte[]> promise = new Promise<byte[]>();
			backgroundWorker.RunWorkerCompleted += CreateWorkerCompletedEventHandler(promise);
			backgroundWorker.RunWorkerAsync();
			return promise;
		}

		private static IPromise<byte[]> EncodePalettePNG(Texture2D texture)
		{
			Color[] pixels = texture.GetPixels();
			int width = texture.width;
			int height = texture.height;
			BackgroundWorker backgroundWorker = new BackgroundWorker();
			backgroundWorker.DoWork += delegate(object sender, DoWorkEventArgs args)
			{
				ImageInfo imageInfo = new ImageInfo(width, height, 8, alpha: false, grayscale: false, palette: true);
				MemoryStream memoryStream = new MemoryStream();
				PngWriter pngWriter = new PngWriter(memoryStream, imageInfo);
				PngChunkPLTE pngChunkPLTE = pngWriter.GetMetadata().CreatePLTEChunk();
				NeuQuantCS neuQuantCS = new NeuQuantCS(imageInfo.Cols, imageInfo.Rows, NeuQuantCS.CreatePixelGetterFromPixels(imageInfo, pixels));
				bool parReserveAlphaColor = true;
				neuQuantCS.SetParReserveAlphaColor(parReserveAlphaColor);
				neuQuantCS.Run();
				int colorCount = neuQuantCS.GetColorCount();
				pngChunkPLTE.SetNentries(colorCount);
				for (int i = 0; i < colorCount; i++)
				{
					int[] color = neuQuantCS.GetColor(i);
					pngChunkPLTE.SetEntry(i, color[0], color[1], color[2]);
				}
				int transparentIndex = neuQuantCS.GetTransparentIndex();
				if (transparentIndex >= 0)
				{
					PngChunkTRNS pngChunkTRNS = pngWriter.GetMetadata().CreateTRNSChunk();
					pngChunkTRNS.setIndexEntryAsTransparent(transparentIndex);
				}
				for (int num = imageInfo.Rows - 1; num >= 0; num--)
				{
					ImageLine imageLine = new ImageLine(imageInfo);
					for (int j = 0; j < imageInfo.Cols; j++)
					{
						IntColor intColor = new IntColor(pixels[num * imageInfo.Cols + j]);
						int num2 = neuQuantCS.Lookup(intColor.Red, intColor.Green, intColor.Blue, intColor.Alpha);
						imageLine.Scanline[j] = num2;
					}
					pngWriter.WriteRow(imageLine, imageInfo.Rows - num - 1);
				}
				pngWriter.End();
				byte[] result = memoryStream.ToArray();
				args.Result = result;
			};
			Promise<byte[]> promise = new Promise<byte[]>();
			backgroundWorker.RunWorkerCompleted += CreateWorkerCompletedEventHandler(promise);
			backgroundWorker.RunWorkerAsync();
			return promise;
		}

		private static RunWorkerCompletedEventHandler CreateWorkerCompletedEventHandler<T>(Promise<T> promise)
		{
			return delegate(object sender, RunWorkerCompletedEventArgs e)
			{
				RecNet.Core.DispatchOnUnityThread(delegate
				{
					if (e.Cancelled)
					{
						promise.Error("Cancelled");
					}
					else if (e.Error != null)
					{
						UnityEngine.Debug.LogException(e.Error);
						promise.Error(e.Error.Message);
					}
					else
					{
						promise.Complete((T)e.Result);
					}
				});
			};
		}
	}
	public struct IntColor
	{
		public int[] ColorInts;

		public Color Color;

		public int Red => ColorInts[0];

		public int Green => ColorInts[1];

		public int Blue => ColorInts[2];

		public int Alpha => ColorInts[3];

		public IntColor(Color c)
		{
			Color = c;
			ColorInts = new int[4];
			ColorInts[0] = Mathf.CeilToInt(Mathf.Lerp(0f, 255f, c.r));
			ColorInts[1] = Mathf.CeilToInt(Mathf.Lerp(0f, 255f, c.g));
			ColorInts[2] = Mathf.CeilToInt(Mathf.Lerp(0f, 255f, c.b));
			ColorInts[3] = Mathf.CeilToInt(Mathf.Lerp(0f, 255f, c.a));
		}

		public IntColor(int[] rgba)
		{
			ColorInts = new int[4];
			for (int i = 0; i < ColorInts.Length; i++)
			{
				if (i < rgba.Length)
				{
					ColorInts[i] = rgba[i];
				}
				else
				{
					ColorInts[i] = 1;
				}
			}
			float r = Mathf.InverseLerp(0f, 255f, rgba[0]);
			float g = Mathf.InverseLerp(0f, 255f, rgba[1]);
			float b = Mathf.InverseLerp(0f, 255f, rgba[2]);
			float a = Mathf.InverseLerp(0f, 255f, rgba[3]);
			Color = new Color(r, g, b, a);
		}
	}
	public class ImageColors
	{
		public Color[] Colors { get; set; }

		public int Width { get; set; }

		public int Height { get; set; }

		public override string ToString()
		{
			return $"{Width}w x {Height}h Colors: {Colors.Length}";
		}
	}
}
[Serializable]
public class AltTextureSet
{
	[SerializeField]
	private bool usePalette;

	[SerializeField]
	private Texture2D _mainTexture;

	[SerializeField]
	private Texture2D _altTexture;

	private static readonly IPromise<byte[]> nullEncodePromise = new CompletedPromise<byte[]>(null);

	private IPromise<byte[]> mainJpgPromise;

	private IPromise<byte[]> altJpgPromise;

	private IPromise<byte[]> mainPngPromise;

	private IPromise<byte[]> altPngPromise;

	public Texture2D MainTexture
	{
		get
		{
			return _mainTexture;
		}
		set
		{
			if (_mainTexture != value)
			{
				mainPngPromise = null;
				mainJpgPromise = null;
				_mainTexture = value;
			}
		}
	}

	public Texture2D AltTexture
	{
		get
		{
			return _altTexture;
		}
		set
		{
			if (_altTexture != value)
			{
				altPngPromise = null;
				altJpgPromise = null;
				_altTexture = value;
			}
		}
	}

	public IPromise<byte[]> MainJPGPromise
	{
		get
		{
			if (mainJpgPromise == null)
			{
				mainJpgPromise = new CompletedPromise<byte[]>(MainTexture.EncodeToJPG(80));
			}
			return mainJpgPromise;
		}
	}

	public IPromise<byte[]> AltJPGPromise
	{
		get
		{
			if (altJpgPromise == null)
			{
				altJpgPromise = new CompletedPromise<byte[]>(AltTexture.EncodeToJPG(80));
			}
			return altJpgPromise;
		}
	}

	public IPromise<byte[]> MainPNGPromise
	{
		get
		{
			if (mainPngPromise == null)
			{
				mainPngPromise = PngEncoder.Encode(MainTexture, usePalette);
			}
			return mainPngPromise;
		}
	}

	public IPromise<byte[]> AltPNGPromise
	{
		get
		{
			if (altPngPromise == null)
			{
				altPngPromise = PngEncoder.Encode(AltTexture, usePalette);
			}
			return altPngPromise;
		}
	}

	public bool Rendered => MainTexture != null && AltTexture != null;

	public AltTextureSet()
		: this(usePalette: false)
	{
	}

	public AltTextureSet(bool usePalette)
	{
		this.usePalette = usePalette;
	}

	public void DeepCopyTextures(AltTextureSet src)
	{
		if (src != null)
		{
			if (src.MainTexture != null)
			{
				MainTexture = new Texture2D(src.MainTexture.width, src.MainTexture.height, src.MainTexture.format, mipmap: false);
				Graphics.CopyTexture(src.MainTexture, MainTexture);
			}
			if (src.AltTexture != null)
			{
				AltTexture = new Texture2D(src.AltTexture.width, src.AltTexture.height, src.AltTexture.format, mipmap: false);
				Graphics.CopyTexture(src.AltTexture, AltTexture);
			}
		}
	}

	public IPromise<Tuple<byte[], byte[]>> EncodeAsync(bool encodeAsJpg, bool includeAltImage)
	{
		IPromise<byte[]> p = ((!encodeAsJpg) ? MainPNGPromise : MainJPGPromise);
		IPromise<byte[]> p2 = nullEncodePromise;
		if (includeAltImage)
		{
			p2 = ((!encodeAsJpg) ? AltPNGPromise : AltJPGPromise);
		}
		return new AggregatePromise<byte[], byte[]>(p, p2);
	}

	public void Render(Camera currentCamera, RenderTexture cameraRenderTexture)
	{
		for (int i = 0; i < AltRenderedObject.All.Count; i++)
		{
			AltRenderedObject.All[i].PreRender();
		}
		currentCamera.Render();
		DestroyTexture(AltTexture);
		AltTexture = RenderTextureToTexture2D(cameraRenderTexture);
		for (int j = 0; j < AltRenderedObject.All.Count; j++)
		{
			if (!AltRenderedObject.All[j].NeverRender)
			{
				AltRenderedObject.All[j].PostRender();
			}
		}
		DestroyTexture(MainTexture);
		if (Profiles.LocalProfile != null && !Profiles.LocalProfile.JuniorProfile)
		{
			currentCamera.Render();
			MainTexture = RenderTextureToTexture2D(cameraRenderTexture);
		}
		else
		{
			MainTexture = AltTexture;
		}
		for (int k = 0; k < AltRenderedObject.All.Count; k++)
		{
			if (AltRenderedObject.All[k].NeverRender)
			{
				AltRenderedObject.All[k].PostRender();
			}
		}
	}

	public void DestroyTextures()
	{
		DestroyTexture(MainTexture);
		mainPngPromise = null;
		DestroyTexture(AltTexture);
		altPngPromise = null;
	}

	public static Texture2D RenderTextureToTexture2D(RenderTexture renderTexture, TextureFormat textureFormat = TextureFormat.RGB24)
	{
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = renderTexture;
		int width = renderTexture.width;
		int height = renderTexture.height;
		Texture2D texture2D = new Texture2D(width, height, textureFormat, mipmap: false);
		texture2D.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
		texture2D.Apply();
		RenderTexture.active = active;
		return texture2D;
	}

	public static Texture2D RenderTextureToTexture2DCropSquare(RenderTexture renderTexture, TextureFormat textureFormat = TextureFormat.RGB24)
	{
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = renderTexture;
		int width = renderTexture.width;
		int height = renderTexture.height;
		Texture2D texture2D = new Texture2D(height, height, textureFormat, mipmap: false);
		int num = (width - height) / 2;
		texture2D.ReadPixels(new Rect(num, 0f, height, height), 0, 0);
		texture2D.Apply();
		RenderTexture.active = active;
		return texture2D;
	}

	private static void DestroyTexture(Texture2D tex)
	{
		if (tex != null)
		{
			UnityEngine.Object.Destroy(tex);
		}
	}
}
namespace RecRoom.Async
{
	public class AggregatePromise<T1, T2> : Promise<Tuple<T1, T2>>
	{
		public AggregatePromise(IPromise<T1> p1, IPromise<T2> p2)
		{
			AggregatePromise<T1, T2> aggregatePromise = this;
			p1.Error(OnError);
			p2.Error(OnError);
			p1.Then(delegate(T1 r1)
			{
				p2.Then(delegate(T2 item)
				{
					aggregatePromise.Complete(Tuple.Create(r1, item));
				});
			});
		}

		private void OnError(string error)
		{
			if (!base.IsCompleted)
			{
				Error(error);
			}
		}
	}
	public class AggregatePromise<T1, T2, T3> : Promise<Tuple<T1, T2, T3>>
	{
		public AggregatePromise(IPromise<T1> p1, IPromise<T2> p2, IPromise<T3> p3)
		{
			AggregatePromise<T1, T2, T3> aggregatePromise = this;
			p1.Error(OnError);
			p2.Error(OnError);
			p3.Error(OnError);
			p1.Then(delegate(T1 r1)
			{
				p2.Then(delegate(T2 item)
				{
					p3.Then(delegate(T3 item2)
					{
						aggregatePromise.Complete(Tuple.Create(r1, item, item2));
					});
				});
			});
		}

		private void OnError(string error)
		{
			if (!base.IsCompleted)
			{
				Error(error);
			}
		}
	}
	public class AggregatePromise<T1, T2, T3, T4> : Promise<Tuple<T1, T2, T3, T4>>
	{
		public AggregatePromise(IPromise<T1> p1, IPromise<T2> p2, IPromise<T3> p3, IPromise<T4> p4)
		{
			AggregatePromise<T1, T2, T3, T4> aggregatePromise = this;
			p1.Error(OnError);
			p2.Error(OnError);
			p3.Error(OnError);
			p4.Error(OnError);
			p1.Then(delegate(T1 r1)
			{
				p2.Then(delegate(T2 item)
				{
					p3.Then(delegate(T3 item2)
					{
						p4.Then(delegate(T4 item3)
						{
							aggregatePromise.Complete(Tuple.Create(r1, item, item2, item3));
						});
					});
				});
			});
		}

		private void OnError(string error)
		{
			if (!base.IsCompleted)
			{
				Error(error);
			}
		}
	}
	public class AggregatePromise<T1, T2, T3, T4, T5> : Promise<Tuple<T1, T2, T3, T4, T5>>
	{
		public AggregatePromise(IPromise<T1> p1, IPromise<T2> p2, IPromise<T3> p3, IPromise<T4> p4, IPromise<T5> p5)
		{
			AggregatePromise<T1, T2, T3, T4, T5> aggregatePromise = this;
			p1.Error(OnError);
			p2.Error(OnError);
			p3.Error(OnError);
			p4.Error(OnError);
			p5.Error(OnError);
			p1.Then(delegate(T1 r1)
			{
				p2.Then(delegate(T2 item)
				{
					p3.Then(delegate(T3 item2)
					{
						p4.Then(delegate(T4 item3)
						{
							p5.Then(delegate(T5 item4)
							{
								aggregatePromise.Complete(Tuple.Create(r1, item, item2, item3, item4));
							});
						});
					});
				});
			});
		}

		private void OnError(string error)
		{
			if (!base.IsCompleted)
			{
				Error(error);
			}
		}
	}
	public class AggregatePromise<T1, T2, T3, T4, T5, T6> : Promise<Tuple<T1, T2, T3, T4, T5, T6>>
	{
		public AggregatePromise(IPromise<T1> p1, IPromise<T2> p2, IPromise<T3> p3, IPromise<T4> p4, IPromise<T5> p5, IPromise<T6> p6)
