	public class HomogenousAggregatePromise<T> : Promise<List<T>>
	{
		private int uncompletedPromiseCount;

		private T[] promiseResults;

		public HomogenousAggregatePromise(List<IPromise<T>> promises)
		{
			if (promises.Count == 0)
			{
				Complete(new List<T>());
				return;
			}
			uncompletedPromiseCount = promises.Count;
			promiseResults = new T[promises.Count];
			for (int i = 0; i < promises.Count; i++)
			{
				int promiseI = i;
				promises[i].Then(delegate(T result)
				{
					promiseResults[promiseI] = result;
					uncompletedPromiseCount--;
					if (uncompletedPromiseCount == 0)
					{
						Complete(new List<T>(promiseResults));
					}
				}).Error(OnError);
			}
		}

		private void OnError(string error)
		{
			if (!base.IsCompleted)
			{
				Error(error);
			}
		}
	}
	public class AsyncBatch : UnityEngine.MonoBehaviour
	{
		private struct Operation
		{
			public string Name;

			public IPromise Promise;

			public float? StartTime;

			public float? EndTime;
		}

		private List<Operation> operations = new List<Operation>();

		public bool IsCompleted { get; private set; }

		public static AsyncBatch Create(Transform parent)
		{
			GameObject gameObject = new GameObject("AsyncBatch");
			gameObject.transform.SetParent(parent, worldPositionStays: false);
			return gameObject.AddComponent<AsyncBatch>();
		}

		private IEnumerator Start()
		{
			while (true)
			{
				if (!IsCompleted)
				{
					bool isCompleted = true;
					for (int i = 0; i < operations.Count; i++)
					{
						Operation operation = operations[i];
						float? endTime = operation.EndTime;
						if (!endTime.HasValue && operation.Promise.IsCompleted)
						{
							operation.EndTime = UnityEngine.Time.realtimeSinceStartup;
						}
						float? endTime2 = operation.EndTime;
						if (!endTime2.HasValue)
						{
							isCompleted = false;
							break;
						}
					}
					IsCompleted = isCompleted;
				}
				yield return null;
			}
		}

		public void Add(string name, IPromise promise)
		{
			operations.Add(new Operation
			{
				Name = name,
				Promise = promise,
				StartTime = UnityEngine.Time.realtimeSinceStartup
			});
			IsCompleted = false;
		}

		public void Add(string name, IEnumerator coroutine)
		{
			Promise promise = new Promise();
			StartCoroutine(PromiseCoroutine(promise, coroutine));
			Add(name, promise);
		}

		private IEnumerator PromiseCoroutine(Promise promise, IEnumerator coroutine)
		{
			yield return coroutine;
			promise.Complete();
		}
	}
