	public class PromiseCache<TKey>
	{
		private class CacheEntry
		{
			public TKey Key;

			public IPromise Promise;

			public DateTime ExpiresAt;
		}

		private Dictionary<TKey, CacheEntry> cache;

		private LinkedList<CacheEntry> expirationList;

		private LinkedList<CacheEntry> leastRecentlyUsedList;

		private int cacheSize;

		private bool cacheErrors;

		public PromiseCache(int? cacheSize = 128, bool cacheErrors = true)
		{
			if (cacheSize.HasValue && cacheSize.Value < 1)
			{
				throw new ArgumentException("Negative cache size specified", "cacheSize");
			}
			this.cacheSize = ((!cacheSize.HasValue) ? int.MaxValue : cacheSize.Value);
			this.cacheErrors = cacheErrors;
			cache = new Dictionary<TKey, CacheEntry>();
			expirationList = new LinkedList<CacheEntry>();
			leastRecentlyUsedList = new LinkedList<CacheEntry>();
		}

		public bool ContainsKey(TKey key)
		{
			return cache.ContainsKey(key);
		}

		public IPromise<TValue> GetPromise<TValue>(TKey key)
		{
			IPromise<TValue> promise = null;
			RemoveExpiredEntries();
			if (cache.TryGetValue(key, out var value))
			{
				promise = value.Promise as IPromise<TValue>;
				if (promise == null)
				{
					UnityEngine.Debug.LogErrorFormat("Cached promise has wrong response type ({0})", key);
				}
				else
				{
					AddToHeadOfLRUList(value);
				}
			}
			return promise;
		}

		public void SetValue<TValue>(TKey key, TValue value)
		{
			SetPromise(key, new CompletedPromise<TValue>(value), TimeSpan.MaxValue);
		}

		public void SetValue<TValue>(TKey key, TValue value, TimeSpan maxCacheAge)
		{
			SetPromise(key, new CompletedPromise<TValue>(value), maxCacheAge);
		}

		public void SetPromise<TValue>(TKey key, IPromise<TValue> promise)
		{
			SetPromise(key, promise, TimeSpan.MaxValue);
		}

		public void SetPromise<TValue>(TKey key, IPromise<TValue> promise, TimeSpan maxCacheAge)
		{
			Remove(key);
			if (!cacheErrors && promise.HasError)
			{
				return;
			}
			CacheEntry cacheEntry = new CacheEntry
			{
				Key = key,
				Promise = promise,
				ExpiresAt = ((!(maxCacheAge == TimeSpan.MaxValue)) ? (DateTime.UtcNow + maxCacheAge) : DateTime.MaxValue)
			};
			cache.Add(key, cacheEntry);
			AddToHeadOfLRUList(cacheEntry);
			AddToExpirationList(cacheEntry);
			if (cacheErrors)
			{
				return;
			}
			promise.Error(delegate
			{
				if (cache.TryGetValue(key, out var value) && value == cacheEntry)
				{
					RemoveCacheEntry(cacheEntry);
				}
			});
		}

		public IPromise<TValue> GetOrCreatePromise<TValue>(TKey key, Func<IPromise<TValue>> createPromiseCallback)
		{
			return GetOrCreatePromise(key, createPromiseCallback, TimeSpan.MaxValue);
		}

		public IPromise<TValue> GetOrCreatePromise<TValue>(TKey key, Func<IPromise<TValue>> createPromiseCallback, TimeSpan maxCacheAge)
		{
			IPromise<TValue> promise = GetPromise<TValue>(key);
			if (promise == null)
			{
				promise = createPromiseCallback();
				SetPromise(key, promise, maxCacheAge);
			}
			return promise;
		}

		public void Remove(TKey key)
		{
			if (cache.TryGetValue(key, out var value))
			{
				RemoveCacheEntry(value);
			}
		}

		public void Clear()
		{
			cache.Clear();
			leastRecentlyUsedList.Clear();
			expirationList.Clear();
		}

		private void AddToHeadOfLRUList(CacheEntry cacheEntry)
		{
			if (cacheSize >= int.MaxValue)
			{
				return;
			}
			leastRecentlyUsedList.Remove(cacheEntry);
			leastRecentlyUsedList.AddFirst(cacheEntry);
			if (leastRecentlyUsedList.Count > cacheSize)
			{
				CacheEntry value = leastRecentlyUsedList.Last.Value;
				cache.Remove(value.Key);
				leastRecentlyUsedList.RemoveLast();
				if (value.ExpiresAt != DateTime.MaxValue)
				{
					expirationList.Remove(value);
				}
			}
		}

		private void AddToExpirationList(CacheEntry cacheEntry)
		{
			if (!(cacheEntry.ExpiresAt != DateTime.MaxValue))
			{
				return;
			}
			if (expirationList.Count == 0 || expirationList.First.Value.ExpiresAt < cacheEntry.ExpiresAt)
			{
				expirationList.AddFirst(cacheEntry);
				return;
			}
			LinkedListNode<CacheEntry> linkedListNode = expirationList.First;
			LinkedListNode<CacheEntry> next = linkedListNode.Next;
			while (next != null && next.Value.ExpiresAt > cacheEntry.ExpiresAt)
			{
				linkedListNode = next;
				next = linkedListNode.Next;
			}
			expirationList.AddAfter(linkedListNode, cacheEntry);
		}

		private void RemoveExpiredEntries()
		{
			DateTime utcNow = DateTime.UtcNow;
			while (expirationList.Count > 0)
			{
				CacheEntry value = expirationList.Last.Value;
				if (value.ExpiresAt < utcNow)
				{
					cache.Remove(value.Key);
					leastRecentlyUsedList.Remove(value);
					expirationList.RemoveLast();
					continue;
				}
				break;
			}
		}

		private void RemoveCacheEntry(CacheEntry cacheEntry)
		{
			cache.Remove(cacheEntry.Key);
			leastRecentlyUsedList.Remove(cacheEntry);
			if (cacheEntry.ExpiresAt != DateTime.MaxValue)
			{
				expirationList.Remove(cacheEntry);
			}
		}
	}
