namespace RecRoom
{
	public enum AutofillType
	{
		Self,
		Parent,
		Children,
		SelfAndParent,
		SelfAndChildren
	}
	public class AutofillAttribute : PropertyAttribute
	{
		public AutofillType Type { get; private set; }

		public virtual bool IsOptional => false;

		public bool IncludeSelf => Type == AutofillType.Self || Type == AutofillType.SelfAndChildren || Type == AutofillType.SelfAndParent;

		public bool AcceptFirst { get; private set; }

		public AutofillAttribute(AutofillType type = AutofillType.Self, bool acceptFirstOfMultiple = false)
		{
			Type = type;
			AcceptFirst = acceptFirstOfMultiple;
		}
	}
	public class AutofillOptionalAttribute : AutofillAttribute
	{
		public override bool IsOptional => true;

		public AutofillOptionalAttribute(AutofillType type = AutofillType.Self, bool acceptFirstOfMultiple = false)
			: base(type, acceptFirstOfMultiple)
		{
		}
	}
	[StructLayout((LayoutKind)0, Size = 1)]
	public struct CachedProperty
	{
		public struct UntilCleared<T>
		{
			private T value;

			private bool hasValue;

			public T Get(Func<T> getter)
			{
				if (!hasValue)
				{
					value = getter();
					hasValue = true;
				}
				return value;
			}

			public void Clear()
			{
				hasValue = false;
			}
		}

		public struct PerFrame<T>
		{
			private T value;

			private bool hasValue;

			private int frame;

			public T Get(Func<T> getter)
			{
				int frameCount = UnityEngine.Time.frameCount;
				if (!hasValue || frameCount != frame)
				{
					value = getter();
					hasValue = true;
					frame = frameCount;
				}
				return value;
			}

			public void Clear()
			{
				hasValue = false;
			}
		}
	}
	public class CircularBuffer<T> : IEnumerable<T>, IEnumerable
	{
		[Serializable]
		public struct Enumerator : IEnumerator<T>, IEnumerator, IDisposable
		{
			private CircularBuffer<T> buffer;

			private int index;

			private int version;

			private T current;

			object IEnumerator.Current
			{
				get
				{
					if (index == 0 || index > buffer.Count)
					{
						throw new InvalidOperationException("CircularBuffer enumerator is not enumerating.");
					}
					return Current;
				}
			}

			public T Current => current;

			public Enumerator(CircularBuffer<T> buffer)
			{
				this.buffer = buffer;
				index = 0;
				version = buffer.version;
				current = default(T);
			}

			public void Dispose()
			{
			}

			public bool MoveNext()
			{
				CheckVersion();
				int count = buffer.Count;
				if (index < count)
				{
					current = buffer[index];
					index++;
					return true;
				}
				return false;
			}

			void IEnumerator.Reset()
			{
				CheckVersion();
				index = 0;
				current = default(T);
			}

			private void CheckVersion()
			{
				if (version != buffer.version)
				{
					throw new InvalidOperationException("CircularBuffer has been changed during enumeration.");
				}
			}
		}

		private T[] entries;

		private int startIndex;

		private int endIndex;

		private int version;

		public int Count
		{
			get
			{
				if (endIndex < 0)
				{
					return 0;
				}
				int num = startIndex;
				int num2 = endIndex;
				if (startIndex > endIndex)
				{
					num2 += entries.Length;
				}
				return 1 + num2 - num;
			}
		}

		public T this[int index]
		{
			get
			{
				return entries[ExternalToInternalIndex(index)];
			}
			set
			{
				entries[ExternalToInternalIndex(index)] = value;
				version++;
			}
		}

		public CircularBuffer(int capacity)
		{
			entries = new T[capacity];
			Clear();
		}

		public void Add(T t)
		{
			if (endIndex < 0)
			{
				endIndex = startIndex;
			}
			else
			{
				endIndex = ClampIndexToRange(endIndex + 1);
				if (endIndex == startIndex)
				{
					startIndex = ClampIndexToRange(startIndex + 1);
				}
			}
			entries[endIndex] = t;
			version++;
		}

		public void AddRange(IEnumerable<T> range)
		{
			if (range is IList<T> list)
			{
				for (int i = 0; i < list.Count; i++)
				{
					Add(list[i]);
				}
				return;
			}
			foreach (T item in range)
			{
				Add(item);
			}
		}

		public void Clear()
		{
			startIndex = 0;
			endIndex = -1;
			version++;
		}

		public void RemoveFromFront(int count)
		{
			if (count >= Count)
			{
				Clear();
			}
			else
			{
				startIndex = ClampIndexToRange(startIndex + count);
			}
			version++;
		}

		public void RemoveFromEnd(int count)
		{
			if (count >= Count)
			{
				Clear();
			}
			else
			{
				endIndex = ClampIndexToRange(endIndex - count);
			}
			version++;
		}

		public void CopyTo(T[] array)
		{
			if (array == null)
			{
				throw new ArgumentNullException();
			}
			int count = Count;
			if (array.Length < count)
			{
				throw new ArgumentException("Destination array is not large enough to copy CircularBuffer's contents to.");
			}
			if (count > 0)
			{
				if (endIndex >= startIndex)
				{
					Array.Copy(entries, startIndex, array, 0, count);
					return;
				}
				int num = entries.Length - startIndex;
				Array.Copy(entries, startIndex, array, 0, num);
				Array.Copy(entries, 0, array, num, endIndex + 1);
			}
		}

		public Enumerator GetEnumerator()
		{
			return new Enumerator(this);
		}

		IEnumerator<T> IEnumerable<T>.GetEnumerator()
		{
			return new Enumerator(this);
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return new Enumerator(this);
		}

		private int ExternalToInternalIndex(int index)
		{
			if (index < 0 || index >= Count)
			{
				throw new IndexOutOfRangeException($"Index {index} outside of CircularBuffer's range");
			}
			return ClampIndexToRange(startIndex + index);
		}

		private int ClampIndexToRange(int index)
		{
			int num = entries.Length;
			index %= num;
			if (index < 0)
			{
				index = num + index;
			}
			return index;
		}
	}
}
namespace RecRoom.Core
{
	public static class CollisionDetection
	{
		public enum CollisionResult
		{
			MISS,
			HIT,
			OVERLAP
		}

		public enum SurfaceType
		{
			WALL,
			FLOOR,
			CEILING
		}

		public delegate bool ColliderFilter(Collider collider);

		private const float EPSILON = 0.001f;

		private const float MIN_DEPENETRATION_DISTANCE = 0.0001f;

		private const float MIN_WALL_ANGLE = 45f;

		private static readonly Collider[] STATIC_UNFILTERED_COLLIDERS = new Collider[256];

		private static readonly Collider[] STATIC_FILTERED_COLLIDERS = new Collider[256];

		private static readonly RaycastHit[] STATIC_RAYCAST_HITS = new RaycastHit[256];

		private static SphereCollider _sharedSphereCollider = null;

		private static CapsuleCollider _sharedCapsuleCollider = null;

		private static SphereCollider SharedSphereCollider
		{
			get
			{
				if (_sharedSphereCollider == null)
				{
					GameObject gameObject = new GameObject("SharedCollisionDetectionSphereCollider");
					gameObject.hideFlags = HideFlags.HideAndDontSave | HideFlags.HideInInspector;
					_sharedSphereCollider = gameObject.AddComponent<SphereCollider>();
					_sharedSphereCollider.center = Vector3.zero;
					_sharedSphereCollider.gameObject.layer = 2;
					_sharedSphereCollider.isTrigger = true;
				}
				return _sharedSphereCollider;
			}
		}

		private static CapsuleCollider SharedCapsuleCollider
		{
			get
			{
				if (_sharedCapsuleCollider == null)
				{
					GameObject gameObject = new GameObject("SharedCollisionDetectionCapsuleCollider");
					gameObject.hideFlags = HideFlags.HideAndDontSave | HideFlags.HideInInspector;
					_sharedCapsuleCollider = gameObject.AddComponent<CapsuleCollider>();
					_sharedCapsuleCollider.center = Vector3.zero;
					_sharedCapsuleCollider.gameObject.layer = 2;
					_sharedCapsuleCollider.isTrigger = true;
				}
				return _sharedCapsuleCollider;
			}
		}

		public static CollisionResult Raycast(Vector3 initialPosition, Vector3 direction, float maxDistance, int layerMask, out RaycastHit hit)
		{
			return Raycast(initialPosition, direction, maxDistance, layerMask, null, out hit);
		}

		public static CollisionResult Raycast(Vector3 initialPosition, Vector3 direction, float maxDistance, int layerMask, ColliderFilter filter, out RaycastHit hit)
		{
			return Raycast(initialPosition, direction, maxDistance, layerMask, filter, QueryTriggerInteraction.Ignore, out hit);
		}

		public static CollisionResult Raycast(Vector3 initialPosition, Vector3 direction, float maxDistance, int layerMask, ColliderFilter filter, QueryTriggerInteraction triggerInteraction, out RaycastHit hit)
		{
			int hitCount = Physics.RaycastNonAlloc(initialPosition, direction, STATIC_RAYCAST_HITS, maxDistance, layerMask, triggerInteraction);
			return ProcessStaticCollisionHits(hitCount, maxDistance, filter, out hit);
		}

		public static Vector3 RunSphereCollisionDisplacement(Vector3 spherePosition, float sphereRadius, float skinThickness, Vector3 desiredDisplacement, int layerMask, int maxIterations, float minMovementDistance = 0.001f)
		{
			bool hitSomething = false;
			return RunSphereCollisionDisplacement(spherePosition, sphereRadius, skinThickness, desiredDisplacement, layerMask, maxIterations, minMovementDistance, out hitSomething);
		}

		public static Vector3 RunSphereCollisionDisplacement(Vector3 spherePosition, float sphereRadius, float skinThickness, Vector3 desiredDisplacement, int layerMask, int maxIterations, float minMovementDistance, out bool hitSomething)
		{
			hitSomething = false;
			Vector3 vector = spherePosition;
			Vector3 vector2 = desiredDisplacement;
			for (int i = 0; i < maxIterations; i++)
			{
				float magnitude = vector2.magnitude;
				if (magnitude <= minMovementDistance)
				{
					break;
				}
				Vector3 vector3 = vector2 / magnitude;
				RaycastHit hit;
				switch (SweepSphere(spherePosition, sphereRadius, vector3, magnitude, layerMask, out hit))
				{
				case CollisionResult.OVERLAP:
				{
					float sphereRadius2 = sphereRadius + skinThickness;
					if (DepenetrateSphere(spherePosition, Quaternion.identity, sphereRadius2, layerMask, out var totalDepenetration))
					{
						spherePosition += totalDepenetration;
						continue;
					}
					break;
				}
				case CollisionResult.MISS:
					spherePosition += vector2;
					vector2 *= 0f;
					continue;
				case CollisionResult.HIT:
					spherePosition += vector3 * (hit.distance - skinThickness);
					magnitude = Mathf.Max(0f, magnitude - hit.distance);
					vector2 = magnitude * vector3;
					vector2 = Vector3.ProjectOnPlane(vector2, hit.normal);
					hitSomething = true;
					continue;
				default:
					continue;
				}
				spherePosition = vector;
				break;
			}
			return spherePosition;
		}

		public static CollisionResult SweepSphere(Vector3 initialSpherePosition, float sphereRadius, Vector3 direction, float maxDistance, int layerMask, out RaycastHit hit)
		{
			return SweepSphere(initialSpherePosition, sphereRadius, direction, maxDistance, layerMask, null, out hit);
		}

		public static CollisionResult SweepSphere(Vector3 initialSpherePosition, float sphereRadius, Vector3 direction, float maxDistance, int layerMask, ColliderFilter filter, out RaycastHit hit)
		{
			int hitCount = Physics.SphereCastNonAlloc(initialSpherePosition, sphereRadius, direction, STATIC_RAYCAST_HITS, maxDistance, layerMask, QueryTriggerInteraction.Ignore);
			return ProcessStaticCollisionHits(hitCount, maxDistance, filter, out hit);
		}

		public static bool DepenetrateSphere(Vector3 spherePosition, Quaternion sphereOrientation, float sphereRadius, int layerMask, out Vector3 totalDepenetration)
		{
			return DepenetrateSphere(spherePosition, sphereOrientation, sphereRadius, layerMask, null, out totalDepenetration);
		}

		public static bool DepenetrateSphere(Vector3 spherePosition, Quaternion sphereOrientation, float sphereRadius, int layerMask, ColliderFilter colliderFilter, out Vector3 totalDepenetration)
		{
			totalDepenetration = Vector3.zero;
			int sphereColliderOverlaps = GetSphereColliderOverlaps(spherePosition, sphereRadius, layerMask, colliderFilter, STATIC_FILTERED_COLLIDERS);
			if (sphereColliderOverlaps > 0)
			{
				return TryGetSphereDepenetration(spherePosition, sphereOrientation, sphereRadius, sphereColliderOverlaps, STATIC_FILTERED_COLLIDERS, out totalDepenetration);
			}
			return false;
		}

		public static Collider GetSphereColliderOverlap(Vector3 spherePosition, float sphereRadius, int layerMask, ColliderFilter colliderFilter, QueryTriggerInteraction triggerInteraction)
		{
			int sphereColliderOverlaps = GetSphereColliderOverlaps(spherePosition, sphereRadius, layerMask, colliderFilter, triggerInteraction, STATIC_FILTERED_COLLIDERS);
			if (sphereColliderOverlaps > 0)
			{
				return STATIC_FILTERED_COLLIDERS[0];
			}
			return null;
		}

		public static int GetSphereColliderOverlaps(Vector3 spherePosition, float sphereRadius, int layerMask, ColliderFilter colliderFilter, Collider[] overlappingColliders)
		{
			return GetSphereColliderOverlaps(spherePosition, sphereRadius, layerMask, colliderFilter, QueryTriggerInteraction.Ignore, overlappingColliders);
		}

		public static int GetSphereColliderOverlaps(Vector3 spherePosition, float sphereRadius, int layerMask, ColliderFilter colliderFilter, QueryTriggerInteraction triggerInteraction, Collider[] overlappingColliders)
		{
			int colliderCount = Physics.OverlapSphereNonAlloc(spherePosition, sphereRadius + 0.001f, STATIC_UNFILTERED_COLLIDERS, layerMask, triggerInteraction);
			return FilterColliders(colliderCount, STATIC_UNFILTERED_COLLIDERS, colliderFilter, overlappingColliders);
		}

		public static bool TryGetSphereDepenetration(Vector3 spherePosition, Quaternion sphereOrientation, float sphereRadius, int potentialColliderCount, Collider[] potentialColliders, out Vector3 totalDepenetration)
		{
			SharedSphereCollider.radius = sphereRadius + 0.001f;
			return TryGetColliderDepenetration(SharedSphereCollider, spherePosition, sphereOrientation, potentialColliderCount, potentialColliders, out totalDepenetration);
		}

		public static CollisionResult SweepCapsule(Vector3 initialCapsuleBottomPosition, Vector3 initialCapsuleTopPosition, float capsuleRadius, Vector3 direction, float maxDistance, int layerMask, out RaycastHit hit)
		{
			return SweepCapsule(initialCapsuleBottomPosition, initialCapsuleTopPosition, capsuleRadius, direction, maxDistance, layerMask, null, out hit);
		}

		public static CollisionResult SweepCapsule(Vector3 initialCapsuleBottomPosition, Vector3 initialCapsuleTopPosition, float capsuleRadius, Vector3 direction, float maxDistance, int layerMask, ColliderFilter filter, out RaycastHit hit)
		{
			int hitCount = Physics.CapsuleCastNonAlloc(initialCapsuleBottomPosition, initialCapsuleTopPosition, capsuleRadius, direction, STATIC_RAYCAST_HITS, maxDistance, layerMask, QueryTriggerInteraction.Ignore);
			return ProcessStaticCollisionHits(hitCount, maxDistance, filter, out hit);
		}

		public static bool DepenetrateCapsule(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, float capsuleRadius, int layerMask, out Vector3 totalDepenetration)
		{
			return DepenetrateCapsule(capsuleBottomPosition, capsuleTopPosition, capsuleRadius, layerMask, null, out totalDepenetration);
		}

		public static bool DepenetrateCapsule(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, float capsuleRadius, int layerMask, ColliderFilter colliderFilter, out Vector3 totalDepenetration)
		{
			totalDepenetration = Vector3.zero;
			int capsuleColliderOverlaps = GetCapsuleColliderOverlaps(capsuleBottomPosition, capsuleTopPosition, capsuleRadius, layerMask, colliderFilter, STATIC_FILTERED_COLLIDERS);
			if (capsuleColliderOverlaps <= 0)
			{
				return false;
			}
			float num = 0f;
			Quaternion capsuleOrientation = Quaternion.identity;
			Vector3 capsulePosition = capsuleBottomPosition;
			Vector3 vector = capsuleTopPosition - capsuleBottomPosition;
			if (vector.sqrMagnitude > 0.001f)
			{
				num = vector.magnitude;
				Vector3 vector2 = vector / num;
				capsuleOrientation = Quaternion.LookRotation(Vector3.forward, vector2);
				capsulePosition = capsuleBottomPosition + vector2 * (num / 2f);
			}
			num += 2f * capsuleRadius;
			return TryGetCapsuleDepenetration(capsulePosition, capsuleOrientation, capsuleRadius, num, capsuleColliderOverlaps, STATIC_FILTERED_COLLIDERS, out totalDepenetration);
		}

		public static int GetCapsuleColliderOverlaps(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, float capsuleRadius, int layerMask, Collider[] overlappingColliders)
		{
			return GetCapsuleColliderOverlaps(capsuleBottomPosition, capsuleTopPosition, capsuleRadius, layerMask, null, overlappingColliders);
		}

		public static int GetCapsuleColliderOverlaps(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, float capsuleRadius, int layerMask, ColliderFilter colliderFilter, Collider[] overlappingColliders)
		{
			int colliderCount = Physics.OverlapCapsuleNonAlloc(capsuleBottomPosition, capsuleTopPosition, capsuleRadius + 0.001f, STATIC_UNFILTERED_COLLIDERS, layerMask, QueryTriggerInteraction.Ignore);
			return FilterColliders(colliderCount, STATIC_UNFILTERED_COLLIDERS, colliderFilter, overlappingColliders);
		}

		public static bool IsCapsuleColliderOverlapping(Vector3 capsuleBottomPosition, Vector3 capsuleTopPosition, float capsuleRadius, int layerMask, ColliderFilter colliderFilter)
		{
			return GetCapsuleColliderOverlaps(capsuleBottomPosition, capsuleTopPosition, capsuleRadius, layerMask, colliderFilter, STATIC_FILTERED_COLLIDERS) > 0;
		}

		public static bool TryGetCapsuleDepenetration(Vector3 capsulePosition, Quaternion capsuleOrientation, float capsuleRadius, float capsuleHeight, int potentialColliderCount, Collider[] potentialColliders, out Vector3 totalDepenetration)
		{
			SharedCapsuleCollider.radius = capsuleRadius + 0.001f;
			SharedCapsuleCollider.height = capsuleHeight + 0.002f;
			return TryGetColliderDepenetration(SharedCapsuleCollider, capsulePosition, capsuleOrientation, potentialColliderCount, potentialColliders, out totalDepenetration);
		}

		public static Collider GetBoxColliderOverlap(Vector3 worldSpaceCenter, Quaternion worldSpaceOrientation, Vector3 worldSpaceSize, int layerMask, ColliderFilter colliderFilter, QueryTriggerInteraction triggerInteraction)
		{
			int boxColliderOverlap = GetBoxColliderOverlap(worldSpaceCenter, worldSpaceOrientation, worldSpaceSize, layerMask, colliderFilter, triggerInteraction, STATIC_FILTERED_COLLIDERS);
			if (boxColliderOverlap > 0)
			{
				return STATIC_FILTERED_COLLIDERS[0];
			}
			return null;
		}

		public static int GetBoxColliderOverlap(Vector3 worldSpaceCenter, Quaternion worldSpaceOrientation, Vector3 worldSpaceSize, int layerMask, ColliderFilter colliderFilter, Collider[] overlappingColliders)
		{
			return GetBoxColliderOverlap(worldSpaceCenter, worldSpaceOrientation, worldSpaceSize, layerMask, colliderFilter, QueryTriggerInteraction.Ignore, overlappingColliders);
		}

		public static int GetBoxColliderOverlap(Vector3 worldSpaceCenter, Quaternion worldSpaceOrientation, Vector3 worldSpaceSize, int layerMask, ColliderFilter colliderFilter, QueryTriggerInteraction triggerInteraction, Collider[] overlappingColliders)
		{
			int colliderCount = Physics.OverlapBoxNonAlloc(worldSpaceCenter, worldSpaceSize / 2f, STATIC_UNFILTERED_COLLIDERS, worldSpaceOrientation, layerMask, triggerInteraction);
			return FilterColliders(colliderCount, STATIC_UNFILTERED_COLLIDERS, colliderFilter, overlappingColliders);
		}

		public static SurfaceType GetSurfaceType(Vector3 surfaceNormal)
		{
			float num = Vector3.Angle(surfaceNormal, Vector3.up);
			if (num <= 45f)
			{
				return SurfaceType.FLOOR;
			}
			if (num >= 135f)
			{
				return SurfaceType.CEILING;
			}
			return SurfaceType.WALL;
		}

		public static bool CollidesWithMovement(Collider collider)
		{
			return collider.gameObject.layer == 14 || CollidesWithMovementIgnoringMovementBlockers(collider);
		}

		public static bool CollidesWithMovementIgnoringPlayers(Collider collider)
		{
			if (collider.gameObject.IsInLayerMask(LayerMasks.AnyPlayerPhysics) || collider.gameObject.CompareTag("Player"))
			{
				return false;
			}
			return CollidesWithMovement(collider);
		}

		public static bool CollidesWithMovementIgnoringPlayersAndEnemies(Collider collider)
		{
			if (collider.gameObject.IsInLayerMask(LayerMasks.EnemyPhysics))
			{
				return false;
			}
			return CollidesWithMovementIgnoringPlayers(collider);
		}

		public static bool CollidesWithMovementIgnoringMovementBlockers(Collider collider)
		{
			return collider.gameObject.layer == 11 || collider.gameObject.layer == 26 || (collider.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics) && collider.CompareTag("MovementCollisionAlwaysAllowed"));
		}

		public static bool CanPlayerStandOnCollider(Collider collider)
		{
			if (collider.gameObject.layer == 11)
			{
				return !collider.CompareTag("MovementRestricted");
			}
			if (collider.gameObject.IsInLayerMask(LayerMasks.ToolAndEnemyPhysics))
			{
				return collider.CompareTag("MovementCollisionAlwaysAllowed");
			}
			return false;
		}

		public static bool CanPlayerStandOnCollider(Collider collider, Vector3 surfaceNormal)
		{
			if (GetSurfaceType(surfaceNormal) != SurfaceType.FLOOR)
			{
				return false;
			}
			return CanPlayerStandOnCollider(collider);
		}

		public static bool IsSphereOverColliderPlayerCanStandOn(Vector3 point, float sphereTestRadius, float sphereTestHeight)
		{
			RaycastHit hit;
			return IsSphereOverColliderPlayerCanStandOn(point, sphereTestRadius, sphereTestHeight, out hit);
		}

		public static bool IsSphereOverColliderPlayerCanStandOn(Vector3 point, float sphereTestRadius, float sphereTestHeight, out RaycastHit hit)
		{
			CollisionResult collisionResult = SweepSphere(point, sphereTestRadius, Vector3.down, sphereTestHeight, 67128320, out hit);
			if (collisionResult != CollisionResult.HIT)
			{
				return false;
			}
			return CanPlayerStandOnCollider(hit.collider, hit.normal);
		}

		public static Vector3 RunOrbitCameraCollision(Vector3 targetPosition, Vector3 desiredCameraPosition, float minDistanceFromTarget, float collisionSphereRadius)
		{
			Vector3 vector = desiredCameraPosition - targetPosition;
			float magnitude = vector.magnitude;
			if (magnitude < Mathf.Epsilon)
			{
				return targetPosition;
			}
			Vector3 vector2 = vector / magnitude;
			RaycastHit hit;
			CollisionResult collisionResult = SweepSphere(targetPosition, collisionSphereRadius, vector2, magnitude, 67128320, CollidesWithMovementIgnoringMovementBlockers, out hit);
			if (collisionResult == CollisionResult.HIT)
			{
				return targetPosition + vector2 * Mathf.Max(minDistanceFromTarget, hit.distance);
			}
			return desiredCameraPosition;
		}

		private static int FilterColliders(int colliderCount, Collider[] unfilteredColliders, ColliderFilter filter, Collider[] results)
		{
			int result = 0;
			for (int i = 0; i < colliderCount && i < results.Length; i++)
			{
				if (filter == null || filter(STATIC_UNFILTERED_COLLIDERS[i]))
				{
					results[result++] = STATIC_UNFILTERED_COLLIDERS[i];
				}
			}
			return result;
		}

		private static bool TryGetColliderDepenetration(Collider thisCollider, Vector3 thisColliderPosition, Quaternion thisColliderRotation, int potentialColliderCount, Collider[] potentialColliders, out Vector3 totalDepenetration)
		{
			bool result = false;
			totalDepenetration = Vector3.zero;
			for (int i = 0; i < potentialColliderCount; i++)
			{
				if (Physics.ComputePenetration(thisCollider, thisColliderPosition, thisColliderRotation, potentialColliders[i], potentialColliders[i].transform.position, potentialColliders[i].transform.rotation, out var direction, out var distance))
				{
					result = true;
					distance = Mathf.Max(0.0001f, distance - 0.001f);
					Vector3 vector = (direction * distance).ValueOrZeroIfBogus();
					totalDepenetration += vector;
				}
			}
			return result;
		}

		private static CollisionResult ProcessStaticCollisionHits(int hitCount, float maxDistance, ColliderFilter filter, out RaycastHit hit)
		{
			int num = -1;
			CollisionResult result = CollisionResult.MISS;
			for (int i = 0; i < hitCount; i++)
			{
				if (filter == null || filter(STATIC_RAYCAST_HITS[i].collider))
				{
					if (STATIC_RAYCAST_HITS[i].distance == 0f)
					{
						num = i;
						result = CollisionResult.OVERLAP;
						break;
					}
					if (num < 0 || STATIC_RAYCAST_HITS[i].distance < maxDistance)
					{
						maxDistance = STATIC_RAYCAST_HITS[i].distance;
						num = i;
						result = CollisionResult.HIT;
					}
				}
			}
			if (num < 0 || num >= STATIC_RAYCAST_HITS.Length)
			{
				hit = default(RaycastHit);
			}
			else
			{
				hit = STATIC_RAYCAST_HITS[num];
			}
			return result;
		}
	}
}
