public class CrashDumpUtil
{
	public const string CRASHDUMP_FILENAME = "crash.dmp";

	public const string OUTPUTLOG_FILENAME = "output_log.txt";

	public const string ERRORLOG_FILENAME = "error.log";

	public const string IGNORE_DUMP_FILE_NAME = ".agignore";

	public static HashSet<string> CRASH_DUMP_FILES = new HashSet<string> { "output_log.txt", "error.log", "crash.dmp" };

	internal static Func<string, bool> CrashDumpFileFilter = (string fileName) => CRASH_DUMP_FILES.Contains(fileName);

	public static List<DirectoryInfo> CheckForCrashDumps()
	{
		List<DirectoryInfo> list = new List<DirectoryInfo>();
		int num = 0;
		try
		{
			string text = $"{UnityEngine.Application.persistentDataPath}/Crashes";
			UnityEngine.Debug.Log("Looking for crash dumps in " + text);
			DirectoryInfo directoryInfo = new DirectoryInfo(text);
			if (directoryInfo.Exists)
			{
				DirectoryInfo[] directories = directoryInfo.GetDirectories();
				DirectoryInfo[] array = directories;
				foreach (DirectoryInfo directoryInfo2 in array)
				{
					if (IsCrashDumpDirectory(directoryInfo2))
					{
						if (!IsCrashDumpDirectoryIgnored(directoryInfo2))
						{
							list.Add(directoryInfo2);
						}
						else
						{
							num++;
						}
					}
				}
			}
			else
			{
				UnityEngine.Debug.LogWarning("No crash dump directory found!");
			}
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
		UnityEngine.Debug.LogFormat("Crash Dump Report:\n\tNew: {0}\n\tPreviously Sent: {1}", list.Count, num);
		return list;
	}

	private static bool IsCrashDumpDirectory(DirectoryInfo di)
	{
		return File.Exists(Path.Combine(di.FullName, "crash.dmp"));
	}

	private static bool IsCrashDumpDirectoryIgnored(DirectoryInfo di)
	{
		return File.Exists(Path.Combine(di.FullName, ".agignore"));
	}

	public static void Ignore(DirectoryInfo crashDump)
	{
		try
		{
			string path = Path.Combine(crashDump.FullName, ".agignore");
			if (!File.Exists(path))
			{
				using (StreamWriter streamWriter = File.CreateText(path))
				{
					streamWriter.WriteLine("This file makes sure we don't ask you to upload again! -Rec Room");
					return;
				}
			}
		}
		catch (Exception)
		{
		}
	}

	public static void Ignore(List<DirectoryInfo> crashDumps)
	{
		foreach (DirectoryInfo crashDump in crashDumps)
		{
			Ignore(crashDump);
		}
	}
}
