public static class CustomSettingsLoader
{
	private const string ResourcesDirectoryName = "Resources";

	public static T LoadConfig<T>(string name = null) where T : ScriptableObject
	{
		return (T)Resources.Load(GetAssetFileName<T>(name), typeof(T));
	}

	public static string GetAssetFileName<T>(string name = null)
	{
		if (string.IsNullOrEmpty(name))
		{
			return typeof(T).Name;
		}
		return typeof(T).Name + "_" + name;
	}

	public static string GetTrimmedFilePath(string filePath)
	{
		filePath = filePath.Replace("\\", "/");
		if (filePath.EndsWith("/"))
		{
			filePath.Remove(filePath.Length - 1, 1);
		}
		if (!filePath.EndsWith("Resources"))
		{
			filePath += "/Resources";
		}
		return filePath;
	}
}
namespace DebugUtils
{
	public class ValueOverTime
	{
		private class ValueOverTimeElement
		{
			public Color Color;

			public List<Vector2> ValueHistories = new List<Vector2>();

			public int Average
			{
				get
				{
					if (ValueHistories.Count > 0)
					{
						return Mathf.RoundToInt(ValueHistories.Sum((Vector2 p) => p.y) / (float)ValueHistories.Count);
					}
					return 0;
				}
			}

			public float Min
			{
				get
				{
					if (ValueHistories.Count > 0)
					{
						return ValueHistories.Min((Vector2 p) => p.y);
					}
					return float.MaxValue;
				}
			}

			public float Max
			{
				get
				{
					if (ValueHistories.Count > 0)
					{
						return ValueHistories.Max((Vector2 p) => p.y);
					}
					return float.MinValue;
				}
			}
		}

		private string name;

		private float graphTimeLength;

		private float? overrideMin;

		private float? overrideMax;

		private bool useUnscaledTime;

		private List<ValueOverTimeElement> elements = new List<ValueOverTimeElement>();

		private static GUIStyle topLeftJustify;

		private static GUIStyle bottomLeftJustify;

		private static GUIStyle headerStyle;

		private float Timestamp => (!useUnscaledTime) ? UnityEngine.Time.time : UnityEngine.Time.realtimeSinceStartup;

		public ValueOverTime(string name, Color color, float graphTimeLength, float? overrideMin = null, float? overrideMax = null, bool useUnscaledTime = true)
			: this(name, 1, new Color[1] { color }, graphTimeLength, overrideMin, overrideMax)
		{
		}

		public ValueOverTime(string name, int elementCount, Color[] elementColors, float graphTimeLength, float? overrideMin = null, float? overrideMax = null, bool useUnscaledTime = true)
		{
			this.name = name;
			this.graphTimeLength = graphTimeLength;
			this.overrideMin = overrideMin;
			this.overrideMax = overrideMax;
			this.useUnscaledTime = useUnscaledTime;
			for (int i = 0; i < elementCount && i < elementColors.Length; i++)
			{
				elements.Add(new ValueOverTimeElement
				{
					Color = elementColors[i]
				});
			}
		}

		public void AddDataPoint(float value)
		{
			AddDataPoint(new float[1] { value });
		}

		public void AddDataPoint(float[] values)
		{
			for (int i = 0; i < values.Length && i < elements.Count; i++)
			{
				while (elements[i].ValueHistories.Count > 0 && Timestamp - elements[i].ValueHistories[0].x > graphTimeLength)
				{
					elements[i].ValueHistories.RemoveAt(0);
				}
				elements[i].ValueHistories.Add(new Vector2(Timestamp, values[i]));
			}
		}

		public void DrawGraph(Rect screenRect)
		{
			LazyInitGuiResources();
			if (UnityEngine.Event.current.type == EventType.Repaint && elements.Count > 0)
			{
				GUI.Box(screenRect, string.Empty, GUI.skin.box);
				screenRect.xMin += 1f;
				screenRect.xMax -= 1f;
				screenRect.yMin += 1f;
				screenRect.yMax -= 1f;
				Rect valueRect = new Rect
				{
					xMin = Timestamp - graphTimeLength,
					xMax = Timestamp,
					yMin = Mathf.Floor((!overrideMin.HasValue) ? Mathf.Min(-1f, elements.Min((ValueOverTimeElement e) => e.Min)) : overrideMin.Value),
					yMax = Mathf.Ceil((!overrideMax.HasValue) ? Mathf.Max(1f, elements.Max((ValueOverTimeElement e) => e.Max)) : overrideMax.Value)
				};
				DrawLine(new Vector2(valueRect.xMin, 0f), new Vector2(valueRect.xMax, 0f), valueRect, screenRect, Color.black);
				for (int num = 0; num < elements.Count; num++)
				{
					DrawPolyLine(elements[num].ValueHistories, valueRect, screenRect, elements[num].Color);
				}
				GUI.Label(screenRect, ((int)valueRect.yMax/*cast due to .constrained prefix*/).ToString(), topLeftJustify);
				GUI.Label(screenRect, ((int)valueRect.yMin/*cast due to .constrained prefix*/).ToString(), bottomLeftJustify);
				GUI.Label(screenRect, $"{name} (Avg: {elements[elements.Count - 1].Average})", headerStyle);
			}
		}

		private void LazyInitGuiResources()
		{
			if (topLeftJustify == null)
			{
				topLeftJustify = new GUIStyle(GUI.skin.label);
				topLeftJustify.alignment = TextAnchor.UpperLeft;
			}
			if (bottomLeftJustify == null)
			{
				bottomLeftJustify = new GUIStyle(GUI.skin.label);
				bottomLeftJustify.alignment = TextAnchor.LowerLeft;
			}
			if (headerStyle == null)
			{
				headerStyle = new GUIStyle(GUI.skin.label);
				headerStyle.alignment = TextAnchor.UpperCenter;
			}
		}

		private void DrawLine(Vector2 pointA, Vector2 pointB, Rect valueRect, Rect screenRect, Color color)
		{
			Drawing.DrawLine(ScaleToRect(pointA, valueRect, screenRect), ScaleToRect(pointB, valueRect, screenRect), color, 1f, antiAlias: false);
		}

		private void DrawPolyLine(IEnumerable<Vector2> points, Rect valueRect, Rect screenRect, Color color)
		{
			Drawing.DrawPolyLine(points.Select((Vector2 p) => ScaleToRect(p, valueRect, screenRect)), color, 1f, antiAlias: true);
		}

		public static Vector2 ScaleToRect(Vector2 point, Rect valueRect, Rect screenRect)
		{
			point.x = Mathf.Lerp(screenRect.xMin, screenRect.xMax, (point.x - valueRect.xMin) / valueRect.width);
			point.y = Mathf.Lerp(screenRect.yMax, screenRect.yMin, (point.y - valueRect.yMin) / valueRect.height);
			return point;
		}
	}
	public class EventsOverTime
	{
		private struct EventData
		{
			public float Time;

			public Color Color;
		}

		private List<EventData> valueHistories = new List<EventData>();

		private float graphTimeLength;

		public EventsOverTime(float graphTimeLength)
		{
			this.graphTimeLength = graphTimeLength;
		}

		public void AddDataPoint(Color color)
		{
			while (valueHistories.Count > 0 && UnityEngine.Time.realtimeSinceStartup - valueHistories[0].Time > graphTimeLength)
			{
				valueHistories.RemoveAt(0);
			}
			valueHistories.Add(new EventData
			{
				Time = UnityEngine.Time.realtimeSinceStartup,
				Color = color
			});
		}

		public void DrawLines(Rect screenRect)
		{
			if (UnityEngine.Event.current.type == EventType.Repaint)
			{
				screenRect.xMin += 1f;
				screenRect.xMax -= 1f;
				screenRect.yMin += 1f;
				screenRect.yMax -= 1f;
				Rect valueRect = new Rect
				{
					xMin = UnityEngine.Time.realtimeSinceStartup - graphTimeLength,
					xMax = UnityEngine.Time.realtimeSinceStartup
				};
				Vector2 point = new Vector2(0f, -1f);
				Vector2 point2 = new Vector2(0f, 1f);
				for (int i = 0; i < valueHistories.Count; i++)
				{
					point.x = valueHistories[i].Time;
					point2.x = valueHistories[i].Time;
					Drawing.DrawLine(ValueOverTime.ScaleToRect(point, valueRect, screenRect), ValueOverTime.ScaleToRect(point2, valueRect, screenRect), valueHistories[i].Color, 1f, antiAlias: false);
				}
			}
		}
	}
}
