public class Dispatcher : UnityEngine.MonoBehaviour
{
	private static Dispatcher _instance;

	private static volatile bool _queued = false;

	private static List<Action> _backlog = new List<Action>(8);

	private static List<Action> _actions = new List<Action>(8);

	public static void RunAsync(Action action)
	{
		ThreadPool.QueueUserWorkItem(delegate
		{
			action();
		});
	}

	public static void RunAsync(Action<object> action, object state)
	{
		ThreadPool.QueueUserWorkItem(delegate(object o)
		{
			action(o);
		}, state);
	}

	public static void RunOnMainThread(Action action)
	{
		lock (_backlog)
		{
			_backlog.Add(action);
			_queued = true;
		}
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
	private static void Initialize()
	{
		if (_instance == null)
		{
			_instance = new GameObject("Dispatcher").AddComponent<Dispatcher>();
			UnityEngine.Object.DontDestroyOnLoad(_instance.gameObject);
		}
	}

	private void Update()
	{
		if (!_queued)
		{
			return;
		}
		lock (_backlog)
		{
			List<Action> actions = _actions;
			_actions = _backlog;
			_backlog = actions;
			_queued = false;
		}
		foreach (Action action in _actions)
		{
			action();
		}
		_actions.Clear();
	}
}
namespace RecRoom
{
	public class DollyController : UnityEngine.MonoBehaviour
	{
		public bool forceVertical;

		private bool snapping;

		private Tool tool;

		private Transform snapTransform;

		private void Awake()
		{
			tool = GetComponent<Tool>();
			tool.PostReleaseEvent += OnToolRelease;
		}

		public void SetSnapTransform(Transform t)
		{
			snapTransform = t;
		}

		public void SetSnapping(bool doSnapping)
		{
			snapping = doSnapping;
		}

		public void ForceVertical()
		{
			base.transform.rotation = Quaternion.Euler(0f, base.transform.rotation.eulerAngles.y, 0f);
		}

		private void OnToolRelease(Tool tool)
		{
			if (forceVertical)
			{
				ForceVertical();
			}
			if (snapping)
			{
				if (snapTransform != null)
				{
					Vector3 vector = Vector3.Project(base.transform.position - snapTransform.position, snapTransform.right);
					base.transform.rotation = snapTransform.rotation;
					base.transform.position = snapTransform.position + vector;
				}
				else
				{
					UnityEngine.Debug.Log("Could not snap because snapTransform is null :-(");
				}
			}
		}

		private void OnDestroy()
		{
			tool.PostReleaseEvent -= OnToolRelease;
		}
	}
}
