		public static bool CapsuleCast(this Collider collider, Vector3 point1, Vector3 point2, float radius, Vector3 direction, float maxDistance, out RaycastHit hitInfo)
		{
			QueryTriggerInteraction queryTriggerInteraction = ((!collider.isTrigger) ? QueryTriggerInteraction.Ignore : QueryTriggerInteraction.Collide);
			int num = Physics.CapsuleCastNonAlloc(point1, point2, radius, direction, raycastHits, maxDistance, 1 << collider.gameObject.layer, queryTriggerInteraction);
			for (int i = 0; i < num; i++)
			{
				if (raycastHits[i].collider == collider)
				{
					hitInfo = raycastHits[i];
					return true;
				}
			}
			hitInfo = default(RaycastHit);
			return false;
		}

