		}

		public static bool CheckOverlap(this BoxCollider collider, Vector3 position, Quaternion orientation, int layerMask, QueryTriggerInteraction triggerInteraction)
		{
			Vector3 center = collider.center.TransformCoordinateSpace(position, orientation);
			Vector3 halfExtents = collider.size / 2f;
			return Physics.CheckBox(center, halfExtents, orientation, layerMask, triggerInteraction);
		}

		public static int Overlap(this BoxCollider collider, Collider[] hits, int layerMask, QueryTriggerInteraction triggerInteraction)
		{
