		public static int Overlap(this BoxCollider collider, Vector3 position, Quaternion orientation, Collider[] hits, int layerMask, QueryTriggerInteraction triggerInteraction)
		{
			Vector3 center = collider.center.TransformCoordinateSpace(position, orientation);
			Vector3 halfExtents = collider.size / 2f;
			return Physics.OverlapBoxNonAlloc(center, halfExtents, hits, orientation, layerMask, triggerInteraction);
		}

		public static bool Contains(this BoxCollider boxCollider, Vector3 worldPosition)
		{
			Vector3 vector = boxCollider.transform.InverseTransformPoint(worldPosition) - boxCollider.center;
			float num = boxCollider.size.x * 0.5f;
			float num2 = boxCollider.size.y * 0.5f;
			float num3 = boxCollider.size.z * 0.5f;
			return vector.x < num && vector.x > 0f - num && vector.y < num2 && vector.y > 0f - num2 && vector.z < num3 && vector.z > 0f - num3;
		}

		public static bool CheckOverlap(this CapsuleCollider collider, int layerMask, QueryTriggerInteraction triggerInteraction)
		{
			Vector3 direction = Vector3.right;
			if (collider.direction == 1)
			{
				direction = Vector3.up;
			}
			else if (collider.direction == 2)
			{
				direction = Vector3.forward;
			}
			Vector3 normalized = collider.transform.TransformDirection(direction).normalized;
			float num = Mathf.Max(0f, collider.height - 2f * collider.radius);
			Vector3 vector = collider.transform.TransformPoint(collider.center);
			return Physics.CheckCapsule(vector - normalized * num, vector + normalized * num, collider.radius, layerMask, triggerInteraction);
		}
	}
