		public static void SetEnabled(this UnityEngine.Component component, bool enabled)
		{
			if (component is Behaviour)
			{
				((Behaviour)component).enabled = enabled;
				return;
			}
			if (component is Animator)
			{
				((Animator)component).enabled = enabled;
				return;
			}
			if (component is Collider)
			{
				((Collider)component).enabled = enabled;
				return;
			}
			if (component is Renderer)
			{
				((Renderer)component).enabled = enabled;
				return;
			}
			if (component is LODGroup)
			{
				((LODGroup)component).enabled = enabled;
				return;
			}
			if (component is Cloth)
			{
				((Cloth)component).enabled = enabled;
				return;
			}
			UnityEngine.Debug.LogWarningFormat("Unable to enable / disable component: {0}", component);
		}

		public static bool GetEnabled(this UnityEngine.Component component)
		{
			if (component is Behaviour)
			{
				return ((Behaviour)component).enabled;
			}
			if (component is Animator)
			{
				return ((Animator)component).enabled;
			}
			if (component is Collider)
			{
				return ((Collider)component).enabled;
			}
			if (component is Renderer)
			{
				return ((Renderer)component).enabled;
			}
			if (component is LODGroup)
			{
				return ((LODGroup)component).enabled;
			}
			if (component is Cloth)
			{
				return ((Cloth)component).enabled;
			}
			UnityEngine.Debug.LogWarningFormat("Unable to enable / disable component: {0}", component);
			return false;
		}
