namespace RecRoom
{
	public static class ListExt
	{
		private static System.Random random = new System.Random();

		public static void Shuffle<T>(this IList<T> list)
		{
			for (int num = list.Count - 1; num > 1; num--)
			{
				int index = random.Next(num + 1);
				T value = list[index];
				list[index] = list[num];
				list[num] = value;
			}
		}
	}
	public static class MathExt
	{
		private static readonly List<float> INSTANTANEOUS_FLOATS = new List<float>();

		private static readonly List<float> INSTANTANEOUS_FLOATS2 = new List<float>();

		public static float GetNthHighestValue(this IList<float> values, int n)
		{
			if (n > values.Count / 2 + 1)
			{
				return values.GetNthLowestValue(values.Count + 1 - n);
			}
			return values.GetNthHighestValue(n, 1f);
		}

		public static float GetNthLowestValue(this IList<float> values, int n)
		{
			if (n > values.Count / 2 + 1)
			{
				return values.GetNthHighestValue(values.Count + 1 - n);
			}
			return values.GetNthHighestValue(n, -1f);
		}

		public static void CartesianPointToSphericalRadians(Vector3 cartesionPoint, out float pitchRadians, out float yawRadians, out float radius)
		{
			radius = cartesionPoint.magnitude;
			pitchRadians = Mathf.Asin(cartesionPoint.y / radius);
			yawRadians = Mathf.Atan2(cartesionPoint.x, 0f - cartesionPoint.z);
		}

		public static void CartesianPointToSphericalDegrees(Vector3 cartesionPoint, out float pitchDegrees, out float yawDegrees, out float radius)
		{
			CartesianPointToSphericalRadians(cartesionPoint, out var pitchRadians, out var yawRadians, out radius);
			pitchDegrees = pitchRadians * 57.29578f;
			yawDegrees = yawRadians * 57.29578f;
		}

		public static Vector3 SphericalPointRadiansToCartesian(float pitchRadians, float yawRadians, float radius)
		{
			float num = Mathf.Sin(pitchRadians);
			float num2 = Mathf.Cos(pitchRadians);
			float num3 = Mathf.Sin(yawRadians);
			float num4 = Mathf.Cos(yawRadians);
			return new Vector3(radius * num2 * num3, radius * num, -1f * radius * num2 * num4);
		}

		public static Vector3 SphericalPointDegreestoCartesian(float pitchDegrees, float yawDegrees, float radius)
		{
			return SphericalPointRadiansToCartesian(pitchDegrees * ((float)Math.PI / 180f), yawDegrees * ((float)Math.PI / 180f), radius);
		}

		public static Vector3 FindRayPlaneIntersectionPoint(Vector3 rayPoint, Vector3 rayDirection, Vector3 planePoint, Vector3 planeNormal)
		{
			float num = Vector3.Dot(planePoint - rayPoint, planeNormal) / Vector3.Dot(rayDirection, planeNormal);
			return rayPoint + rayDirection * num;
		}

		private static float GetNthHighestValue(this IList<float> values, int n, float modifier)
		{
			if (values.Count == 0)
			{
				return float.NaN;
			}
			if (n <= 0)
			{
				n = 1;
			}
			INSTANTANEOUS_FLOATS2.Clear();
			INSTANTANEOUS_FLOATS2.AddRange(values);
			INSTANTANEOUS_FLOATS2.Shuffle();
			INSTANTANEOUS_FLOATS.Clear();
			int index = 0;
			int num = 0;
			for (int i = 0; i < INSTANTANEOUS_FLOATS2.Count; i++)
			{
				float num2 = INSTANTANEOUS_FLOATS2[i] * modifier;
				if (i < n)
				{
					INSTANTANEOUS_FLOATS.Add(num2);
					if (num2 < INSTANTANEOUS_FLOATS[index])
					{
						index = i;
					}
					if (num2 > INSTANTANEOUS_FLOATS[num])
					{
						num = i;
					}
				}
				else
				{
					if (!(num2 > INSTANTANEOUS_FLOATS[index]))
					{
						continue;
					}
					INSTANTANEOUS_FLOATS[index] = num2;
					if (num2 > (float)num)
					{
						num = i;
					}
					float num3 = float.MaxValue;
					for (int j = 0; j < INSTANTANEOUS_FLOATS.Count; j++)
					{
						if (INSTANTANEOUS_FLOATS[j] < num3)
						{
							num3 = INSTANTANEOUS_FLOATS[j];
							index = j;
						}
					}
				}
			}
			return INSTANTANEOUS_FLOATS[index] / modifier;
		}
	}
