	public static class PhysicsExt
	{
		public const float EPSILON = 0.0001f;

		public const int MAX_RAYCAST_HITS = 256;

		public static Collider[] IMMEDIATE_COLLIDER_HITS = new Collider[256];

		public static RaycastHit[] IMMEDIATE_RAYCAST_HITS = new RaycastHit[256];

		public static T GetClosestSphereCastHit<T>(Vector3 origin, float radius, Vector3 direction, float maxDistance, out Vector3 hitPoint, out Collider collider, Func<Collider, float, T> validateColliderFunc)
		{
			hitPoint = origin + direction * maxDistance;
			T result = default(T);
			collider = null;
			RaycastHit[] iMMEDIATE_RAYCAST_HITS = IMMEDIATE_RAYCAST_HITS;
			int num = Physics.SphereCastNonAlloc(origin, radius, direction, iMMEDIATE_RAYCAST_HITS, maxDistance, 1267084289, QueryTriggerInteraction.Collide);
			float num2 = float.MaxValue;
			for (int i = 0; i < num; i++)
			{
				RaycastHit raycastHit = iMMEDIATE_RAYCAST_HITS[i];
				Vector3 vector = ((!(raycastHit.distance > float.Epsilon)) ? raycastHit.collider.ClosestPoint(origin) : raycastHit.point);
				float sqrMagnitude = (vector - origin).sqrMagnitude;
				if (sqrMagnitude < num2)
				{
					T val = validateColliderFunc(raycastHit.collider, sqrMagnitude);
					if (val != null)
					{
						num2 = sqrMagnitude;
						hitPoint = vector;
						result = val;
						collider = raycastHit.collider;
					}
				}
			}
			return result;
		}
	}
