	public static class StringExt
	{
		public static string SplitPascalCaseIntoWords(string pascalCaseString)
		{
			if (string.IsNullOrWhiteSpace(pascalCaseString))
			{
				return pascalCaseString;
			}
			int num = 0;
			int i = 0;
			StringBuilder stringBuilder = new StringBuilder();
			while (true)
			{
				if (i < pascalCaseString.Length && !char.IsLower(pascalCaseString[i]))
				{
					i++;
					continue;
				}
				if (i == pascalCaseString.Length)
				{
					break;
				}
				if (i - 1 > num)
				{
					int num2 = i - 1;
					if (stringBuilder.Length > 0)
					{
						stringBuilder.Append(' ');
					}
					stringBuilder.Append(pascalCaseString.Substring(num, num2 - num));
					num = num2;
					i = num2;
				}
				else
				{
					for (; i < pascalCaseString.Length && char.IsLower(pascalCaseString[i]); i++)
					{
					}
					if (stringBuilder.Length > 0)
					{
						stringBuilder.Append(' ');
					}
					stringBuilder.Append(pascalCaseString.Substring(num, i - num));
					num = i;
				}
			}
			if (i > num)
			{
				if (stringBuilder.Length > 0)
				{
					stringBuilder.Append(' ');
				}
				stringBuilder.Append(pascalCaseString.Substring(num, i - num));
			}
			return stringBuilder.ToString();
		}
	}
	public static class TransformExt
	{
		public static Vector3 YawForward(this Transform transform)
		{
			float t = Vector3.Dot(transform.forward, transform.forward.ZeroY().normalized);
			return Vector3.Lerp(transform.forward, transform.up, t).ZeroY().normalized;
		}

		public static Vector3 YawForwardBasic(this Transform transform)
		{
			return (transform.forward + transform.up + Vector3.Cross(Vector3.up, transform.right)).ZeroY().normalized;
		}

		public static Vector3 ViewportPointToWorldPoint(this Transform transform, Vector2 viewportCoordinate, float buttonThickness = 0f)
		{
			return ((RectTransform)transform).ViewportPointToWorldPoint(viewportCoordinate, buttonThickness);
		}

		public static Vector3 ViewportPointToWorldPoint(this RectTransform transform, Vector2 viewportCoordinate, float buttonThickness = 0f)
		{
			Vector3[] array = new Vector3[4];
			transform.GetWorldCorners(array);
			Vector3 vector = array[1] - array[0];
			Vector3 vector2 = array[3] - array[0];
			Vector3 normalized = Vector3.Cross(vector, vector2).normalized;
			return array[0] + vector * viewportCoordinate.y + vector2 * viewportCoordinate.x + normalized * buttonThickness;
		}
	}
}
