	public static Texture2D CropToCenteredSquare(this Texture2D oldTex)
	{
		int num = Mathf.Min(oldTex.height, oldTex.width);
		int num2 = Mathf.Abs(oldTex.height - oldTex.width) / 2;
		Color[] pixels = ((oldTex.height < oldTex.width) ? oldTex.GetPixels(num2, 0, num, num) : oldTex.GetPixels(0, num2, num, num));
		Texture2D texture2D = new Texture2D(num, num);
		texture2D.SetPixels(pixels);
		texture2D.Apply();
		return texture2D;
	}

