	public static IEnumerator DownsizeTextureSet(AltTextureSet original, Vector2 imageSize, int numSamples, Action<AltTextureSet> onDone)
	{
		AltTextureSet downsizedTexureSet = new AltTextureSet();
		yield return DownsizeTexture(original.MainTexture, imageSize, numSamples, delegate(Texture2D t)
		{
			downsizedTexureSet.MainTexture = t;
		});
		yield return DownsizeTexture(original.AltTexture, imageSize, numSamples, delegate(Texture2D t)
		{
			downsizedTexureSet.AltTexture = t;
		});
		onDone?.Invoke(downsizedTexureSet);
	}

	public static IEnumerator DownsizeTexture(Texture2D original, Vector2 imageSize, int numSamples, Action<Texture2D> onDone)
	{
		int width = original.width;
		int height = original.height;
		Texture2D scaledDownSelfie = UnityEngine.Object.Instantiate(original);
		int xDownsizePerSample = (int)((float)width - imageSize.x) / numSamples;
		int yDownsizePerSample = (int)((float)height - imageSize.y) / numSamples;
		for (int i = 1; i < numSamples - 1; i++)
		{
			TextureScale.Bilinear(scaledDownSelfie, width - i * xDownsizePerSample, height - i * yDownsizePerSample);
			yield return null;
		}
		TextureScale.Bilinear(scaledDownSelfie, (int)imageSize.x, (int)imageSize.y);
		onDone(scaledDownSelfie);
	}

	public static int GetStableHashCode(this string s)
	{
		uint num = 2166136261u;
		for (int i = 0; i < s.Length; i++)
		{
			num ^= s[i];
			num *= 16777619;
			num = 1664525 * num + 1013904223;
		}
		return (int)num;
	}

	public static IEnumerable<T> SkipTake<T>(this IEnumerable<T> enumerable, int skip, int take)
	{
		if (skip > 0)
		{
			enumerable = enumerable.Skip(skip);
		}
		return enumerable.Take(take);
	}

	public static void ThrowIfNull<T>(this UnityEngine.Component component, T value, string message) where T : class
	{
		if (value == null)
		{
			throw new NullReferenceException(message);
