	public static List<T> FindAllObjectsOfType<T>(this GameObject gameObject) where T : UnityEngine.Component
	{
		return FindAllObjectsOfType<T>();
	}

	public static List<T> FindAllObjectsOfType<T>() where T : UnityEngine.Component
	{
		List<T> list = new List<T>();
		for (int i = 0; i < SceneManager.sceneCount; i++)
		{
			GameObject[] rootGameObjects = SceneManager.GetSceneAt(i).GetRootGameObjects();
			foreach (GameObject gameObject in rootGameObjects)
			{
				list.AddRange(gameObject.GetComponentsInChildren<T>(includeInactive: true));
			}
		}
		return list;
	}

	public static T GetOrAddComponent<T>(this GameObject gameObject) where T : UnityEngine.Component
	{
		T val = gameObject.GetComponent<T>();
		if (!val)
		{
			val = gameObject.AddComponent<T>();
		}
		return val;
	}

	public static T GetComponentInParent<T>(this UnityEngine.Component component, bool includeDisabled) where T : UnityEngine.Component
	{
		return component.gameObject.GetComponentInParent<T>(includeDisabled);
	}

	public static T GetComponentInParent<T>(this GameObject gameObject, bool includeDisabled) where T : UnityEngine.Component
	{
		if (includeDisabled)
		{
			Transform transform = gameObject.transform;
			while (transform != null)
			{
				T component = transform.GetComponent<T>();
				if (component != null)
				{
					return component;
				}
				transform = transform.parent;
			}
			return (T)null;
		}
		return gameObject.GetComponentInParent<T>();
	}

