	public static float GetHorizontalFieldOfView(this Camera camera)
	{
		float num = (float)Math.PI / 180f * camera.fieldOfView;
		return 2f * Mathf.Atan(Mathf.Tan(num / 2f) * camera.aspect) * 57.29578f;
	}

	public static float GetDistanceFromProjectionCameraToFillFOV(this Camera thisCamera, float worldSpaceHeight, float verticalBufferPercentage)
	{
		worldSpaceHeight = GetWorldSpaceHeightWithBuffer(worldSpaceHeight, verticalBufferPercentage);
		float cameraFovRatio = GetCameraFovRatio(thisCamera);
		return worldSpaceHeight / cameraFovRatio;
	}

	private static float GetWorldSpaceHeightWithBuffer(float worldSpaceHeight, float verticalBufferPercentage)
	{
		float num = verticalBufferPercentage / 100f;
		float num2 = 1f + num;
		return worldSpaceHeight * num2;
	}

	private static float GetCameraFovRatio(Camera camera)
	{
		return 2f * Mathf.Tan(0.5f * camera.fieldOfView * ((float)Math.PI / 180f));
	}

	public static void RotateOrbitCamera(this Camera thisCamera, float deltaPitch, float deltaYaw, float minAngleFromUp, float minAngleFromDown)
	{
		thisCamera.transform.Rotate(0f, deltaYaw, 0f, Space.World);
		float num = Vector3.SignedAngle(thisCamera.transform.forward, Vector3.up, -thisCamera.transform.right);
		float value = num + deltaPitch;
		float num2 = Mathf.Clamp(value, minAngleFromUp, 180f - minAngleFromDown);
		float xAngle = num2 - num;
		thisCamera.transform.Rotate(xAngle, 0f, 0f, Space.Self);
	}

