	public static bool CalculateCombinedExtents(IEnumerable<UnityEngine.Component> components, out Vector3 extents)
	{
		extents = Vector3.zero;
		Bounds bounds = default(Bounds);
		bool flag = false;
		foreach (UnityEngine.Component component in components)
		{
			if (GetCombinedRendererBounds(component.gameObject, out var bounds2, ignoreInactive: true))
			{
				if (flag)
				{
					bounds.Encapsulate(bounds2);
					continue;
				}
				bounds = bounds2;
				flag = true;
			}
		}
		if (flag)
		{
			extents = bounds.extents;
			return true;
		}
		return false;
	}

	public static Bounds CalculateRendererBounds(this GameObject gameobject)
	{
		Bounds result = new Bounds(gameobject.transform.position, Vector3.zero);
		Renderer[] componentsInChildren = gameobject.GetComponentsInChildren<Renderer>();
		Renderer[] array = componentsInChildren;
		foreach (Renderer renderer in array)
		{
			if (renderer != null && renderer.enabled && renderer.gameObject.activeSelf)
			{
				result.Encapsulate(renderer.bounds);
			}
		}
		return result;
	}

	public static Vector3 CalculateCorrectScale(this Transform transform, float originalRadius, bool includeTriggers = false)
	{
		Transform parent = transform.parent;
		transform.parent = null;
		Bounds bounds = new Bounds(transform.position, Vector3.zero);
		Collider[] componentsInChildren = transform.gameObject.GetComponentsInChildren<Collider>(includeInactive: true);
		if (componentsInChildren.Length > 0)
		{
			Collider[] array = componentsInChildren;
			foreach (Collider collider in array)
			{
				if (collider != null && (includeTriggers || !collider.isTrigger) && collider.gameObject.activeSelf)
				{
					bool enabled = collider.enabled;
					collider.enabled = true;
					bounds.Encapsulate(collider.bounds);
					collider.enabled = enabled;
				}
			}
		}
		else
		{
			bounds = transform.gameObject.CalculateRendererBounds();
		}
		transform.position = bounds.center;
		transform.parent = parent;
		if (bounds.extents == Vector3.zero)
		{
			UnityEngine.Debug.LogErrorFormat("No valid bounds found for {0}", transform.name, transform);
			return Vector3.one;
		}
		float num = bounds.extents.MaxComponent() + bounds.extents.MinComponent();
		float num2 = originalRadius / num / ((!(parent != null)) ? 1f : parent.lossyScale.y);
		return Vector3.one * num2;
	}

	public static void AssignCorrectScale(this Transform transform, float originalRadius, bool includeTriggers = false)
	{
		transform.localScale = transform.CalculateCorrectScale(originalRadius, includeTriggers);
	}

