		}
		while (transform != null);
		return false;
	}

	public static bool IsLossyScaleInverted(this Transform transform)
	{
		Vector3 lossyScale = transform.lossyScale;
		float num = Mathf.Sign(transform.lossyScale.x * transform.lossyScale.y * transform.lossyScale.z);
		return num < 0f;
