	public static void SetLocalUniformScale(this Transform transform, float uniformScale)
	{
		Vector3 vector = Vector3.one * uniformScale;
		if (transform.localScale != vector)
		{
			transform.localScale = vector;
		}
	}

	public static float InverseTransformLossyUniformScale(this Transform transform, float uniformLossyScale)
	{
		float lossyUniformScale = transform.GetLossyUniformScale();
		if (lossyUniformScale < Mathf.Epsilon)
		{
			return 0f;
		}
		return uniformLossyScale / lossyUniformScale;
	}

