	public static int FindIndex<T>(this T[] array, T value)
	{
		for (int i = 0; i < array.Length; i++)
		{
			ref readonly T reference = ref array[i];
			object obj = value;
			if (reference.Equals(obj))
			{
				return i;
			}
		}
		return -1;
	}

	public static int LastIndexOf<T>(this T[] array, T value)
	{
		int result = -1;
		for (int i = 0; i < array.Length; i++)
		{
			ref readonly T reference = ref array[i];
			object obj = value;
			if (reference.Equals(obj))
			{
				result = i;
			}
		}
		return result;
	}

