	public static float SolveQuadraticEquationMaxValue(float a, float b, float c)
	{
		SolveQuadraticEquation(a, b, c, out var lowerResult, out var upperResult);
		return Mathf.Max(lowerResult, upperResult);
	}

	public static float SolveQuadraticEquationMinValue(float a, float b, float c)
	{
		SolveQuadraticEquation(a, b, c, out var lowerResult, out var upperResult);
		return Mathf.Min(lowerResult, upperResult);
	}

	public static void SolveQuadraticEquation(float a, float b, float c, out float lowerResult, out float upperResult)
	{
		float num = Mathf.Sqrt(b * b - 4f * a * c);
		lowerResult = (0f - b - num) / (2f * a);
		upperResult = (0f - b + num) / (2f * a);
	}

