	public static void Shuffle<T>(this IList<T> list)
	{
		int num = list.Count;
		System.Random random = new System.Random((int)DateTime.UtcNow.Ticks);
		while (num > 1)
		{
			int index = random.Next(0, num);
			num--;
			T value = list[index];
			list[index] = list[num];
			list[num] = value;
		}
	}

	public static T LastItem<T>(this IList<T> list)
	{
