			yield return t.name;
			t = t.parent;
		}
	}

	public static float ReMapRange(this float value, Vector2 range, Vector2 newRange)
	{
		float num = range.y - range.x;
		float num2 = (value - range.x) / num;
		float num3 = newRange.y - newRange.x;
		return newRange.x + num3 * num2;
	}

