	public static bool GetCombinedRendererBounds(IEnumerable<Renderer> renderers, out Bounds bounds, bool ignoreInactive = false)
	{
		bool flag = false;
		bounds = default(Bounds);
		foreach (Renderer renderer in renderers)
		{
			if (!(renderer is ParticleSystemRenderer) && !(renderer is TrailRenderer) && !(renderer is LineRenderer) && (!ignoreInactive || (renderer.enabled && renderer.gameObject.activeSelf)))
			{
				if (!flag)
				{
					bounds = renderer.bounds;
					flag = true;
				}
				else if (renderer != null)
				{
					bounds.Encapsulate(renderer.bounds);
				}
			}
		}
		return flag;
	}

	public static void GetTexture2D(this RenderTexture frame, ref Texture2D texture, bool cropSidesToSquare = false)
	{
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = frame;
		if (texture == null)
		{
			int num = Mathf.Min(frame.width, frame.height);
			texture = new Texture2D((!cropSidesToSquare) ? frame.width : num, (!cropSidesToSquare) ? frame.height : num, TextureFormat.ARGB32, mipmap: false);
		}
		if (cropSidesToSquare)
		{
			texture.ReadPixels(new Rect((float)(texture.width - texture.height) / 2f, 0f, texture.height, texture.height), 0, 0);
		}
		else
		{
			texture.ReadPixels(new Rect(0f, 0f, texture.width, texture.height), 0, 0);
		}
		texture.Apply();
		RenderTexture.active = active;
	}

