	public static Texture2D Downsample(this Texture2D virtualPhoto, Vector2 imageSize, int numDownsamples = 2)
	{
		int width = virtualPhoto.width;
		int height = virtualPhoto.height;
		Texture2D texture2D = UnityEngine.Object.Instantiate(virtualPhoto);
		int num = (int)((float)width - imageSize.x) / numDownsamples;
		int num2 = (int)((float)height - imageSize.y) / numDownsamples;
		for (int i = 1; i < numDownsamples - 1; i++)
		{
			TextureScale.Bilinear(texture2D, width - i * num, height - i * num2);
		}
		TextureScale.Bilinear(texture2D, (int)imageSize.x, (int)imageSize.y);
		return texture2D;
	}

