	public static Vector3 GetLegacyProjectileMotionInitialVelocity(Vector3 origin, Vector3 target, float maxRange, float speed, out float totalLifetime)
	{
		Vector3 vector = target - origin;
		Vector3 vector2 = Vector3.ProjectOnPlane(vector, Vector3.up);
		Vector3 normalized = vector2.normalized;
		if (vector2.sqrMagnitude >= maxRange * maxRange)
		{
			vector = vector - vector2 + normalized * maxRange;
		}
		float sqrMagnitude = Physics.gravity.sqrMagnitude;
		float num = speed * speed + Vector3.Dot(vector, Physics.gravity);
		float num2 = num * num - sqrMagnitude * vector.sqrMagnitude;
		totalLifetime = 0f;
		if (num2 < 0f)
		{
			float num3 = speed * Mathf.Cos((float)Math.PI / 6f);
			totalLifetime = maxRange / num3;
		}
		else
		{
			float num4 = Mathf.Sqrt(num2);
			totalLifetime = Mathf.Sqrt((num - num4) * 2f / sqrMagnitude);
		}
		return vector / totalLifetime - Physics.gravity * totalLifetime / 2f;
	}

	public static Vector3 GetProjectileMotionInitialVelocity(Vector3 origin, Vector3 target, float speed, out float totalLifetime)
	{
		float projectileMotionLaunchAngleDegrees = GetProjectileMotionLaunchAngleDegrees(origin, target, speed);
		Vector3 normalized = Vector3.ProjectOnPlane(target - origin, Vector3.up).normalized;
		Vector3 normalized2 = Vector3.Cross(normalized, Vector3.up).normalized;
		totalLifetime = 0f;
		return Quaternion.AngleAxis(projectileMotionLaunchAngleDegrees, normalized2) * normalized * speed;
	}

	private static float GetProjectileMotionLaunchAngleDegrees(Vector3 origin, Vector3 target, float speed)
	{
		Vector3 vector = target - origin;
		float num = Vector3.Dot(vector, Vector3.up);
		float magnitude = Vector3.ProjectOnPlane(vector, Vector3.up).magnitude;
		float num2 = Vector3.Dot(Physics.gravity, -Vector3.up);
		float num3 = speed * speed;
		float num4 = num3 * num3;
		float num5 = magnitude * magnitude;
		float num6 = num4 - num2 * (num2 * num5 + 2f * num3 * num);
		if (num6 < 0f)
		{
			return 45f;
		}
		float num7 = num2 * magnitude;
		float num8 = Mathf.Sqrt(num6);
		float num9 = Mathf.Atan((num3 + num8) / num7) * 57.29578f;
		float num10 = Mathf.Atan((num3 - num8) / num7) * 57.29578f;
		if (Mathf.Abs(num9) < Mathf.Abs(num10))
		{
			return num9;
		}
		return num10;
	}

