	public static string ReadLines(this FileInfo file, string startPattern, string endPattern)
	{
		string text = string.Empty;
		if (file != null && file.Exists)
		{
			using StreamReader streamReader = file.OpenText();
			bool flag = false;
			string empty = string.Empty;
			while ((empty = streamReader.ReadLine()) != null)
			{
				if (flag)
				{
					if (!string.IsNullOrEmpty(endPattern) && empty.Contains(endPattern))
					{
						break;
					}
					text = text + empty + Environment.NewLine;
				}
				else if (!string.IsNullOrEmpty(startPattern) && empty.Contains(startPattern))
				{
					flag = true;
				}
			}
		}
		return text.Trim();
	}

	public static string ReadLines(this FileInfo file, int startLine, int numberOfLinesToRead)
	{
		string text = string.Empty;
		if (file != null && file.Exists)
		{
			using StreamReader streamReader = file.OpenText();
			int num = 0;
			string empty = string.Empty;
			while ((empty = streamReader.ReadLine()) != null && num < startLine + numberOfLinesToRead)
			{
				if (num >= startLine)
				{
					text = text + empty + Environment.NewLine;
				}
				num++;
			}
		}
		return text.Trim();
	}

