	public static bool ContainsCompetingPlatforms(this PlatformManager.PlatformMask mask)
	{
		return mask == PlatformManager.PlatformMask.All || (mask.HasFlag(PlatformManager.PlatformMask.PlayStation) && (mask.HasFlag(PlatformManager.PlatformMask.Steam) || mask.HasFlag(PlatformManager.PlatformMask.Oculus) || mask.HasFlag(PlatformManager.PlatformMask.Microsoft)));
	}

	public static bool SupportsCurrentPlatform(this PlatformManager.PlatformMask mask)
	{
		return mask.SupportsPlatform(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform);
	}

	public static bool SupportsPlatform(this PlatformManager.PlatformMask mask, PlatformManager.PlatformType platform)
	{
		return mask == PlatformManager.PlatformMask.All || platform == PlatformManager.PlatformType.All || (platform == PlatformManager.PlatformType.PlayStation && mask.HasFlag(PlatformManager.PlatformMask.PlayStation)) || (platform != PlatformManager.PlatformType.PlayStation && (mask.HasFlag(PlatformManager.PlatformMask.Oculus) || mask.HasFlag(PlatformManager.PlatformMask.Microsoft) || mask.HasFlag(PlatformManager.PlatformMask.Steam)));
	}

	public static bool CanBeUsedByCurrentPlatform(this PlatformManager.PlatformType platformType)
	{
		return platformType.CanBeUsedByPlatform(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform);
	}

	public static bool CanBeUsedByPlatform(this PlatformManager.PlatformType currentPlatform, PlatformManager.PlatformType desiredPlatform)
	{
		return currentPlatform == PlatformManager.PlatformType.All || desiredPlatform == PlatformManager.PlatformType.All || (currentPlatform == PlatformManager.PlatformType.PlayStation && desiredPlatform == PlatformManager.PlatformType.PlayStation) || (currentPlatform != PlatformManager.PlatformType.PlayStation && desiredPlatform != PlatformManager.PlatformType.PlayStation);
	}
