namespace RecRoom
{
	public static class Vector3Ext
	{
		public static Vector3 Average(this IEnumerable<Vector3> vectors)
		{
			int num = 0;
			Vector3 zero = Vector3.zero;
			foreach (Vector3 vector in vectors)
			{
				num++;
				zero += vector;
			}
			if (num == 0)
			{
				return Vector3.zero;
			}
			return zero / num;
		}

		public static float SqDistance(Vector3 a, Vector3 b)
		{
			return (a - b).sqrMagnitude;
		}

		public static Vector3 TransformCoordinateSpace(this Vector3 v, Vector3 coordinateSpaceOrigin, Vector3 coordinateSpaceRight, Vector3 coordinateSpaceUp, Vector3 coordinateSpaceForward)
		{
			return coordinateSpaceOrigin + v.x * coordinateSpaceRight + v.y * coordinateSpaceUp + v.z * coordinateSpaceForward;
		}

		public static Vector3 TransformCoordinateSpace(this Vector3 v, Vector3 coordinateSpaceOrigin, Quaternion coordinateSpaceRotation)
		{
			return coordinateSpaceOrigin + coordinateSpaceRotation * v;
		}

		public static Vector3 InverseTransformCoordinateSpace(this Vector3 v, Vector3 coordinateSpaceOrigin, Quaternion coordinateSpaceRotation)
		{
			Quaternion quaternion = Quaternion.Inverse(coordinateSpaceRotation);
			return quaternion * (v - coordinateSpaceOrigin);
		}

		public static bool IsUniform(this Vector3 thisVector, float epsilon = 0.001f)
		{
			float num = Mathf.Abs(thisVector.x);
			float num2 = Mathf.Abs(thisVector.y);
			float num3 = Mathf.Abs(thisVector.z);
			return Mathf.Abs(num - num2) <= epsilon && Mathf.Abs(num - num3) <= epsilon && Mathf.Abs(num2 - num3) <= epsilon;
		}

		public static bool InsideLineSegment(this Vector3 position, Vector3 pointA, Vector3 pointB, Vector3 lineAB, out float distanceVariance)
		{
			Vector3 lhs = position - pointA;
			Vector3 vector = pointA + lineAB * Vector3.Dot(lhs, lineAB);
			float sqrMagnitude = (vector - pointA).sqrMagnitude;
			float sqrMagnitude2 = (vector - pointB).sqrMagnitude;
			float sqrMagnitude3 = (pointA - pointB).sqrMagnitude;
			distanceVariance = Mathf.Max(sqrMagnitude, sqrMagnitude2) / sqrMagnitude3;
			return sqrMagnitude <= sqrMagnitude3 && sqrMagnitude2 <= sqrMagnitude3;
		}

		public static float MaxComponent(this Vector3 v)
		{
			return Mathf.Max(v.x, Mathf.Max(v.y, v.z));
		}

		public static float MinComponent(this Vector3 v)
		{
			return Mathf.Min(v.x, Mathf.Min(v.y, v.z));
		}

		public static Vector3 ValueOrZeroIfBogus(this Vector3 vector)
		{
			float x = vector.x;
			float y = vector.y;
			float z = vector.z;
			if (float.IsNaN(x) || float.IsInfinity(x) || float.IsNaN(y) || float.IsInfinity(y) || float.IsNaN(z) || float.IsInfinity(z))
			{
				return default(Vector3);
			}
			return vector;
		}

		public static Vector3 ClampedValueOrZeroIfBogus(this Vector3 vector, float maxMagnitude)
		{
			float x = vector.x;
			float y = vector.y;
			float z = vector.z;
			if (float.IsNaN(x) || float.IsInfinity(x) || float.IsNaN(y) || float.IsInfinity(y) || float.IsNaN(z) || float.IsInfinity(z))
			{
				return default(Vector3);
			}
			if (vector.sqrMagnitude > maxMagnitude * maxMagnitude)
			{
				return Vector3.ClampMagnitude(vector, maxMagnitude);
			}
			return vector;
		}

		public static bool IsZero(this Vector3 vector)
		{
			return vector.x == 0f && vector.y == 0f && vector.z == 0f;
		}

		public static bool IsNaN(this Vector3 vector)
		{
			return float.IsNaN(vector.x) || float.IsNaN(vector.y) || float.IsNaN(vector.z);
		}

		public static bool IsInfinity(this Vector3 vector)
		{
			return float.IsInfinity(vector.x) || float.IsInfinity(vector.y) || float.IsInfinity(vector.z);
		}

		public static Vector3 MultiplyComponents(this Vector3 me, Vector3 other)
		{
			return new Vector3(me.x * other.x, me.y * other.y, me.z * other.z);
		}

		public static Vector3 DivideComponents(this Vector3 me, Vector3 other)
		{
			return new Vector3(me.x / other.x, me.y / other.y, me.z / other.z);
		}

		public static float AngleSignedVector3(this Vector3 from, Vector3 to, Vector3? up = null)
		{
			up = ((!up.HasValue) ? Vector3.up : up.Value);
			return Vector3.Angle(from, to) * Mathf.Sign(Vector3.Dot(Vector3.Cross(from, to), up.GetValueOrDefault()));
		}

		public static Vector3 ZeroY(this Vector3 vector)
		{
			vector.y = 0f;
			return vector;
		}
	}
}
