public class FramerateCounter : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float refreshSeconds = 1f;

	private int frames;

	private float minFrameFps;

	private float timeLastReset;

	private void Update()
	{
		frames++;
		minFrameFps = Mathf.Min(minFrameFps, 1f / UnityEngine.Time.unscaledDeltaTime);
		float num = UnityEngine.Time.realtimeSinceStartup - timeLastReset;
		if (num >= refreshSeconds)
		{
			float num2 = (float)frames / num;
			float num3 = minFrameFps;
			DebugVR.LogFormatPersistent("FPS", "Avg: {0:0.0}, Min: {1:0.0}", num2, num3);
			frames = 0;
			timeLastReset = UnityEngine.Time.realtimeSinceStartup;
			minFrameFps = float.MaxValue;
		}
	}
}
public class FramerateRollingWindow
{
	private float[] frameTimings;

	private int lastFrameOutsideWindow;

	private int currentFrame;

	private float windowSizeSeconds;

	public FramerateRollingWindow(float windowToMonitorInSeconds)
	{
		windowSizeSeconds = windowToMonitorInSeconds;
		frameTimings = new float[(int)(200f * windowToMonitorInSeconds) + 1];
		Reset();
	}

	public void Reset()
	{
		lastFrameOutsideWindow = 0;
		currentFrame = -1;
	}

	public bool RecordFrame(float currentFrameTime, out float rollingFPS)
	{
		currentFrame++;
		if (currentFrame >= frameTimings.Length)
		{
			currentFrame = 0;
		}
		frameTimings[currentFrame] = currentFrameTime;
		bool flag = false;
		int num = lastFrameOutsideWindow;
		while (currentFrameTime - frameTimings[num] > windowSizeSeconds)
		{
			flag = true;
			lastFrameOutsideWindow = num;
			num++;
			if (num >= frameTimings.Length)
			{
				num = 0;
			}
			if (num == currentFrame)
			{
				break;
			}
		}
		if (!flag)
		{
			rollingFPS = -1f;
			return false;
		}
		int num2 = 1 + currentFrame - lastFrameOutsideWindow;
		if (lastFrameOutsideWindow > currentFrame)
		{
			num2 = currentFrame + 1 + (frameTimings.Length - lastFrameOutsideWindow);
		}
		float num3 = currentFrameTime - frameTimings[lastFrameOutsideWindow];
		rollingFPS = (float)num2 / num3;
		return true;
	}
}
public class FriendImporter
{
	private static List<Profile> platformFriends;

	public static bool SendingFriendRequests { get; private set; }

	public static IEnumerator GetPlatformFriendProfiles(Action<List<Profile>> callback)
	{
		if (platformFriends == null)
		{
			yield return GetPlatformFriendsProfilesAndMapping();
		}
		callback(platformFriends);
	}

	private static IEnumerator GetPlatformFriendsProfilesAndMapping()
	{
		return SingletonMonoBehaviour<PlatformManager>.Instance.GetPlatformFriendIds().ContinueWith((List<ulong> friendIds) => Profiles.GetFromServer(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentPlatform, friendIds)).Then(delegate(List<Profile> friends)
		{
			platformFriends = (from pr in friends
				where !pr.JuniorProfile
				where (long)pr.Id != RecNet.Core.LocalProfileId
				orderby !pr.CanSendFriendRequest(), pr.DisplayName.GetDecrypted()
				select pr).ToList();
		})
			.Error(delegate(string error)
			{
				UnityEngine.Debug.LogErrorFormat("Failed to lookup platform friends on RecNet: {0}", error);
				platformFriends = new List<Profile>();
			});
	}

	public static bool CanImportAFriend(IEnumerable<Profile> profiles)
	{
		return profiles?.Any(UnityExtensions.CanSendFriendRequest) ?? false;
	}

	public static IEnumerator SendAllFriendRequests(UnityEngine.MonoBehaviour coroutineObject, params Profile[] players)
	{
		SendingFriendRequests = true;
		int requestsRemaining = players.Length;
		foreach (Profile profile in players)
		{
			coroutineObject.StartCoroutine(Relationships.SendFriendRequest(profile.Id, delegate
			{
				requestsRemaining--;
			}));
		}
		yield return new WaitUntil(() => requestsRemaining <= 0);
		SendingFriendRequests = false;
	}

	public static void SendFriendRequest(UnityEngine.MonoBehaviour coroutineObject, Profile profile)
	{
		coroutineObject.StartCoroutine(Relationships.SendFriendRequest(profile.Id, delegate
		{
		}));
	}
}
namespace RecRoom
{
	public static class FunctionalHelpers
	{
		public static IEnumerable<Tuple<T, U>> Zip<T, U>(this IEnumerable<T> first, IEnumerable<U> second)
		{
			IEnumerator<T> itr1 = first.GetEnumerator();
			IEnumerator<U> itr2 = second.GetEnumerator();
			while (itr1.MoveNext() && itr2.MoveNext())
			{
				yield return Tuple.Create(itr1.Current, itr2.Current);
			}
		}

		public static MemoT Reduce<SrcT, MemoT>(this IEnumerable<SrcT> sequence, MemoT memo, Func<SrcT, MemoT, MemoT> reduceFunc)
		{
			foreach (SrcT item in sequence)
			{
				memo = reduceFunc(item, memo);
			}
			return memo;
		}

		public static MemoT Reduce<SrcT, MemoT>(this IEnumerable<SrcT> sequence, MemoT memo, Func<SrcT, MemoT, int, MemoT> reduceFunc)
		{
			int num = 0;
			foreach (SrcT item in sequence)
			{
				memo = reduceFunc(item, memo, num++);
			}
			return memo;
		}
	}
}
public class GameViewDebug : UnityEngine.MonoBehaviour
{
	private struct Line
	{
		public Vector3 Start;

		public Vector3 End;

		public Color Color;
	}

	private static GameViewDebug _instance;

	private static Material _lineMaterial;

	private List<Line> lines = new List<Line>();

	private static GameViewDebug instance
	{
		get
		{
			if (_instance == null)
			{
				_instance = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.gameObject.AddComponent<GameViewDebug>();
			}
			return _instance;
		}
	}

	private static Material lineMaterial
	{
		get
		{
			if (_lineMaterial == null)
			{
				Shader shader = Shader.Find("AG/Lines/Color Blended");
				if (shader != null)
				{
					_lineMaterial = new Material(shader);
					_lineMaterial.hideFlags = HideFlags.HideAndDontSave;
					_lineMaterial.shader.hideFlags = HideFlags.HideAndDontSave;
				}
				else
				{
					UnityEngine.Debug.LogError("GameViewDebug failed to locate the line shader with the given name.");
				}
			}
			return _lineMaterial;
		}
	}

	public static void DrawLine(Vector3 start, Vector3 end)
	{
		DrawLine(start, end, Color.white);
	}

	public static void DrawLine(Vector3 start, Vector3 end, Color color)
	{
		instance.lines.Add(new Line
		{
			Start = start,
			End = end,
			Color = color
		});
	}

	public static void DrawBounds(Bounds bounds)
	{
		DrawBounds(bounds, Color.white);
	}

	public static void DrawBounds(Bounds bounds, Color color)
	{
		DrawBox(bounds.center, bounds.size, Matrix4x4.identity, color);
	}

	public static void DrawBoxCollider(BoxCollider boxCollider)
	{
		DrawBoxCollider(boxCollider, Color.white);
	}

	public static void DrawBoxCollider(BoxCollider boxCollider, Color color)
	{
		Matrix4x4 trs = Matrix4x4.TRS(boxCollider.transform.position, boxCollider.transform.rotation, boxCollider.transform.lossyScale);
		DrawBox(boxCollider.center, boxCollider.size, trs, color);
	}

	public static void DrawBox(Vector3 center, Vector3 size, Color color)
	{
		DrawBox(center, size, Matrix4x4.identity, color);
	}

	public static void DrawBox(Vector3 center, Vector3 size, Matrix4x4 trs, Color color)
	{
		Vector3[] boxCorners = GetBoxCorners(center, size, trs);
		DrawLine(boxCorners[0], boxCorners[1], color);
		DrawLine(boxCorners[1], boxCorners[2], color);
		DrawLine(boxCorners[2], boxCorners[3], color);
		DrawLine(boxCorners[3], boxCorners[0], color);
		DrawLine(boxCorners[4], boxCorners[5], color);
		DrawLine(boxCorners[5], boxCorners[6], color);
		DrawLine(boxCorners[6], boxCorners[7], color);
		DrawLine(boxCorners[7], boxCorners[4], color);
		DrawLine(boxCorners[0], boxCorners[4], color);
		DrawLine(boxCorners[1], boxCorners[5], color);
		DrawLine(boxCorners[2], boxCorners[6], color);
		DrawLine(boxCorners[3], boxCorners[7], color);
	}

	private static Vector3[] GetBoxCorners(Vector3 center, Vector3 size, Matrix4x4 trs)
	{
		Vector3[] array = new Vector3[8]
		{
			new Vector3(-0.5f, -0.5f, -0.5f),
			new Vector3(0.5f, -0.5f, -0.5f),
			new Vector3(0.5f, 0.5f, -0.5f),
			new Vector3(-0.5f, 0.5f, -0.5f),
			new Vector3(-0.5f, -0.5f, 0.5f),
			new Vector3(0.5f, -0.5f, 0.5f),
			new Vector3(0.5f, 0.5f, 0.5f),
			new Vector3(-0.5f, 0.5f, 0.5f)
		};
		for (int i = 0; i < array.Length; i++)
		{
			array[i].Scale(size);
			array[i] += center;
			ref Vector3 reference = ref array[i];
			reference = trs.MultiplyPoint(array[i]);
		}
		return array;
	}

	private void OnPostRender()
	{
		if (lineMaterial != null)
		{
			GL.Begin(1);
			lineMaterial.SetPass(0);
			for (int i = 0; i < lines.Count; i++)
			{
				GL.Color(lines[i].Color);
				GL.Vertex3(lines[i].Start.x, lines[i].Start.y, lines[i].Start.z);
				GL.Vertex3(lines[i].End.x, lines[i].End.y, lines[i].End.z);
			}
			GL.End();
		}
		lines.Clear();
	}
}
public static class GUIExtensions
{
	private static GUIStyle tabPaneStyle;

	private static GUIStyle defaultSelectedTabStyle;

	private static GUIStyle defaultUnselectedTabStyle;

	public static int BeginTabs(int selected, params string[] labels)
	{
		if (tabPaneStyle == null)
		{
			tabPaneStyle = new GUIStyle(GUI.skin.box);
			tabPaneStyle.margin.top = 0;
		}
		if (defaultSelectedTabStyle == null)
		{
			defaultSelectedTabStyle = new GUIStyle(GUI.skin.box);
			defaultSelectedTabStyle.normal.textColor = GUI.skin.label.normal.textColor;
			defaultSelectedTabStyle.fixedWidth = 100f;
			defaultSelectedTabStyle.alignment = TextAnchor.MiddleLeft;
			defaultSelectedTabStyle.clipping = TextClipping.Clip;
			defaultSelectedTabStyle.margin.bottom = 0;
		}
		if (defaultUnselectedTabStyle == null)
		{
			defaultUnselectedTabStyle = new GUIStyle(GUI.skin.label);
			defaultUnselectedTabStyle.margin = defaultSelectedTabStyle.margin;
			defaultUnselectedTabStyle.padding = defaultSelectedTabStyle.padding;
			defaultUnselectedTabStyle.fixedWidth = defaultSelectedTabStyle.fixedWidth;
			defaultUnselectedTabStyle.alignment = defaultSelectedTabStyle.alignment;
			defaultUnselectedTabStyle.clipping = TextClipping.Clip;
			defaultUnselectedTabStyle.margin.bottom = 0;
		}
		return BeginTabs(selected, labels, tabPaneStyle, defaultSelectedTabStyle, defaultUnselectedTabStyle);
	}

	public static int BeginTabs(int selected, string[] labels, GUIStyle tabPaneStyle, GUIStyle selectedTabStyle, GUIStyle unselectedTabStyle)
	{
		GUILayout.BeginVertical();
		GUILayout.BeginHorizontal();
		for (int i = 0; i < labels.Length; i++)
		{
			GUIStyle style = ((i != selected) ? unselectedTabStyle : selectedTabStyle);
			if (GUILayout.Button(labels[i], style))
			{
				selected = i;
			}
		}
		GUILayout.FlexibleSpace();
		GUILayout.EndHorizontal();
		GUILayout.BeginVertical(tabPaneStyle);
		return selected;
	}

	public static void EndTabs()
	{
		GUILayout.EndVertical();
		GUILayout.EndVertical();
	}
}
