	[Skip]
	public abstract class ListEvent<T> : ListEvent
	{
		protected struct ModificationData
		{
			public enum Type
			{
				ADD,
				REMOVE,
				CLEAR
			}

			public Type type;

			public T action;
		}

		protected bool isIterating;

		protected readonly bool useTryCatch;

		protected readonly List<T> actionList;

		private readonly List<ModificationData> queuedModifications;

		public bool HasEvent => actionList.Count > 0;

		public ListEvent(int capacity, bool useTryCatch)
		{
			this.useTryCatch = useTryCatch;
			actionList = new List<T>(capacity);
			queuedModifications = new List<ModificationData>();
			isIterating = false;
		}

		protected void ProcessQueuedModifications()
		{
			for (int i = 0; i < queuedModifications.Count; i++)
			{
				switch (queuedModifications[i].type)
				{
				case ModificationData.Type.ADD:
					actionList.Add(queuedModifications[i].action);
					break;
				case ModificationData.Type.REMOVE:
					actionList.Remove(queuedModifications[i].action);
					break;
				case ModificationData.Type.CLEAR:
					actionList.Clear();
					break;
				}
			}
			queuedModifications.Clear();
		}

		public void Add(T action)
		{
			if (action == null)
			{
				return;
			}
			lock (actionList)
			{
				if (isIterating)
				{
					queuedModifications.Add(new ModificationData
					{
						type = ModificationData.Type.ADD,
						action = action
					});
				}
				else
				{
					actionList.Add(action);
				}
			}
		}

		public void Remove(T action)
		{
			if (action == null)
			{
				return;
			}
			lock (actionList)
			{
				if (isIterating)
				{
					queuedModifications.Add(new ModificationData
					{
						type = ModificationData.Type.REMOVE,
						action = action
					});
				}
				else
				{
					actionList.Remove(action);
				}
			}
		}

		public void Clear()
		{
			lock (actionList)
			{
				if (isIterating)
				{
					queuedModifications.Add(new ModificationData
					{
						type = ModificationData.Type.CLEAR
					});
				}
				else
				{
					actionList.Clear();
				}
			}
		}
	}
