						}
					}
					else
					{
						for (int j = 0; j < actionList.Count; j++)
						{
							actionList[j]();
						}
					}
				}
				finally
				{
					ProcessQueuedModifications();
					isIterating = false;
				}
			}
		}

		public override void DynamicInvoke(object[] args)
		{
			if (args != null && args.Length != 0)
