public class MainTextureOverride : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Renderer renderer;

	[Header("Texture Overrides")]
	[SerializeField]
	private Texture2D defaultTexture;

	[SerializeField]
	private Texture2D steamVrVive;

	[SerializeField]
	private Texture2D steamVrOculus;

	[SerializeField]
	private Texture2D steamVrMicrosoft;

	[SerializeField]
	private Texture2D oculus;

	[SerializeField]
	private Texture2D ps4Move;

	[SerializeField]
	private Texture2D microsoftVr;

	private void Start()
	{
		Texture2D texture2D = null;
		switch (SingletonMonoBehaviour<InputManager>.Instance.VRMode)
		{
		case InputManager.VRInputMode.SteamVR_Vive:
			texture2D = steamVrVive;
			break;
		case InputManager.VRInputMode.SteamVR_Oculus:
			texture2D = steamVrOculus;
			break;
		case InputManager.VRInputMode.SteamVR_WindowsMR:
			texture2D = steamVrMicrosoft ?? microsoftVr;
			break;
		case InputManager.VRInputMode.Oculus:
			texture2D = oculus;
			break;
		case InputManager.VRInputMode.PS4_Move:
			texture2D = ps4Move;
			break;
		case InputManager.VRInputMode.WindowsMR:
			texture2D = microsoftVr;
			break;
		}
		if (texture2D == null)
		{
			texture2D = defaultTexture;
		}
		if (texture2D != null)
		{
			renderer.material.mainTexture = texture2D;
		}
	}
}
public class ManagedMonoBehaviour : UnityEngine.MonoBehaviour, IManagedUpdate
{
	private bool usesUpdate;

	private bool usesLateUpdate;

	private bool usesFixedUpdate;

	public bool UsesUpdate
	{
		get
		{
			return usesUpdate;
		}
		protected set
		{
			usesUpdate = value;
		}
	}

	public bool UsesLateUpdate
	{
		get
		{
			return usesLateUpdate;
		}
		protected set
		{
			usesLateUpdate = value;
		}
	}

	public bool UsesFixedUpdate
	{
		get
		{
			return usesFixedUpdate;
		}
		protected set
		{
			usesFixedUpdate = value;
		}
	}

	public virtual void ManagedUpdate()
	{
	}

	public virtual void ManagedLateUpdate()
	{
	}

	public virtual void ManagedFixedUpdate()
	{
	}

	protected virtual void OnEnable()
	{
		ManagedUpdater.Instance.Add(this);
	}

	protected virtual void OnDisable()
	{
		ManagedUpdater.Instance.Remove(this);
	}
}
public class ManagedUpdater : UnityEngine.MonoBehaviour
{
	private class ManagedUpdateData
	{
		public IManagedUpdate obj;
	}

	private static ManagedUpdater instance;

	private LinkedList<ManagedUpdateData> updates = new LinkedList<ManagedUpdateData>();

	private LinkedList<ManagedUpdateData> lateUpdates = new LinkedList<ManagedUpdateData>();

	private LinkedList<ManagedUpdateData> fixedUpdates = new LinkedList<ManagedUpdateData>();

	private List<IManagedUpdate> addQueue = new List<IManagedUpdate>();

	private List<IManagedUpdate> removeQueue = new List<IManagedUpdate>();

	public static ManagedUpdater Instance
	{
		get
		{
			if (instance == null)
			{
				GameObject gameObject = new GameObject("ManagedUpdater");
				instance = gameObject.AddComponent<ManagedUpdater>();
				UnityEngine.Object.DontDestroyOnLoad(gameObject);
			}
			return instance;
		}
	}

	public void Add(IManagedUpdate toAdd)
	{
		addQueue.Add(toAdd);
	}

	public void Remove(IManagedUpdate toRemove)
	{
		InternalRemove(toRemove);
		addQueue.Remove(toRemove);
	}

	private void ProcessAddAndRemoveQueues()
	{
		for (int i = 0; i < addQueue.Count; i++)
		{
			InternalAdd(addQueue[i]);
		}
		addQueue.Clear();
		for (int j = 0; j < removeQueue.Count; j++)
		{
			InternalRemove(removeQueue[j]);
		}
		removeQueue.Clear();
	}

	private void InternalAdd(IManagedUpdate toAdd)
	{
		ManagedUpdateData managedUpdateData = new ManagedUpdateData();
		managedUpdateData.obj = toAdd;
		if (toAdd.UsesUpdate)
		{
			updates.AddLast(managedUpdateData);
		}
		if (toAdd.UsesLateUpdate)
		{
			lateUpdates.AddLast(managedUpdateData);
		}
		if (toAdd.UsesFixedUpdate)
		{
			fixedUpdates.AddLast(managedUpdateData);
		}
	}

	private void InternalRemove(IManagedUpdate toRemove)
	{
		if (toRemove.UsesUpdate)
		{
			LinkedListNode<ManagedUpdateData> linkedListNode = FindInList(updates, toRemove);
			if (linkedListNode != null)
			{
				updates.Remove(linkedListNode);
			}
		}
		if (toRemove.UsesLateUpdate)
		{
			LinkedListNode<ManagedUpdateData> linkedListNode2 = FindInList(lateUpdates, toRemove);
			if (linkedListNode2 != null)
			{
				lateUpdates.Remove(linkedListNode2);
			}
		}
		if (toRemove.UsesFixedUpdate)
		{
			LinkedListNode<ManagedUpdateData> linkedListNode3 = FindInList(fixedUpdates, toRemove);
			if (linkedListNode3 != null)
			{
				fixedUpdates.Remove(linkedListNode3);
			}
		}
	}

	private LinkedListNode<ManagedUpdateData> FindInList(LinkedList<ManagedUpdateData> list, IManagedUpdate obj)
	{
		LinkedListNode<ManagedUpdateData> linkedListNode = list.First;
		while (linkedListNode != null && linkedListNode.Value.obj != obj)
		{
			linkedListNode = linkedListNode.Next;
		}
		return linkedListNode;
	}

	private void FixedUpdate()
	{
		for (LinkedListNode<ManagedUpdateData> linkedListNode = fixedUpdates.First; linkedListNode != null; linkedListNode = linkedListNode.Next)
		{
			linkedListNode.Value.obj.ManagedFixedUpdate();
		}
	}

	private void LateUpdate()
	{
		for (LinkedListNode<ManagedUpdateData> linkedListNode = lateUpdates.First; linkedListNode != null; linkedListNode = linkedListNode.Next)
		{
			linkedListNode.Value.obj.ManagedLateUpdate();
		}
		ProcessAddAndRemoveQueues();
	}

	private void Update()
	{
		for (LinkedListNode<ManagedUpdateData> linkedListNode = updates.First; linkedListNode != null; linkedListNode = linkedListNode.Next)
		{
			linkedListNode.Value.obj.ManagedUpdate();
		}
	}
}
public class MersenneTwister : System.Random
{
	private const int N = 624;

	private const int M = 397;

	private const uint MatrixA = 2567483615u;

	private const uint UpperMask = 2147483648u;

	private const uint LowerMask = 2147483647u;

	private const uint TemperingMaskB = 2636928640u;

	private const uint TemperingMaskC = 4022730752u;

	private readonly uint[] _mt = new uint[624];

	private short _mti;

	private static readonly uint[] _mag01 = new uint[2] { 0u, 2567483615u };

	private const double FiftyThreeBitsOf1s = 9007199254740991.0;

