public class NetworkedSingletonMonoBehaviour<T> : NetworkedSingletonMonoBehaviourBase where T : NetworkedSingletonMonoBehaviour<T>
{
	private static T instance;

	public static T Instance
	{
		get
		{
			return instance;
		}
		private set
		{
			if (instance == null)
			{
				instance = value;
			}
			else
			{
				UnityEngine.Debug.LogError("Created more than one singleton of " + typeof(T).ToString() + "!");
			}
		}
	}

	public static bool IsInitialized => Instance != null;

	protected override void Awake()
	{
		base.Awake();
		instance = (T)this;
		GameRoot.AddExistingSingleton(this);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (instance == this)
		{
			instance = (T)null;
		}
		GameRoot.ExistingGameSingletons.Remove(this);
	}
}
