						scanlineByte[num] & 0xFF,
						scanlineByte[num + 1] & 0xFF,
						scanlineByte[num + 2] & 0xFF
					};
				}
				int[] scanlineInt = png.ReadRowInt(row).GetScanlineInt();
				int num2 = col * imgInfo.Channels;
				return imgInfo.Alpha ? new int[4]
				{
					scanlineInt[num2],
					scanlineInt[num2 + 1],
					scanlineInt[num2 + 2],
					scanlineInt[num2 + 3]
