		public static IPixelGetter CreatePixelGetterFromPixels(ImageInfo imageInfo, Color[] pixels)
		{
			return new PixelsPixelGetter(imageInfo, pixels);
		}

		public static IPixelGetter CreatePixelGetterFromPngReader(PngReader png)
		{
			if (png.ImgInfo.Indexed || png.ImgInfo.Greyscale || png.ImgInfo.BitDepth < 8)
			{
				throw new Exception("Bad image type " + png.ImgInfo);
			}
			return new PngReaderPixelGetter(png);
		}
