public class ObjectPool : UnityEngine.MonoBehaviour
{
	private readonly Dictionary<Behaviour, ObjectPoolEntry> poolEntries = new Dictionary<Behaviour, ObjectPoolEntry>();

	private static ObjectPool _instance;

	private static GameObject _singleton;

	public static ObjectPool Instance
	{
		get
		{
			if (_instance == null)
			{
				_singleton = new GameObject();
				_instance = _singleton.AddComponent<ObjectPool>();
				_singleton.name = "[ObjectPool]";
			}
			return _instance;
		}
	}

	private void Awake()
	{
		if (base.gameObject != _singleton)
		{
			UnityEngine.Object.DestroyImmediate(base.gameObject);
		}
	}

	public T Acquire<T>(T prefab) where T : Behaviour
	{
		ObjectPoolEntry objectPoolEntry = FindOrCreatePool(prefab);
		if (objectPoolEntry != null)
		{
			return (T)objectPoolEntry.Acquire();
		}
		return (T)null;
	}

	public bool Release<T>(T obj) where T : Behaviour
	{
		PooledObject component = obj.GetComponent<PooledObject>();
		if (component != null)
		{
			if (component.PoolEntry != null)
			{
				return component.PoolEntry.Release(obj);
			}
			UnityEngine.Debug.LogErrorFormat($"PooledObject {obj} has an invalid PoolEntry reference!");
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat($"Tried to release {obj}, but it is not a PooledObject!");
		}
		UnityEngine.Object.Destroy(obj.gameObject);
		return false;
	}

	public void Prefill<T>(T prefab, int numInstances) where T : Behaviour
	{
		FindOrCreatePool(prefab)?.Prefill(numInstances);
	}

	public void SetMaxInstances<T>(T prefab, int maxInstances) where T : Behaviour
	{
		FindOrCreatePool(prefab)?.SetMaxInstances(maxInstances);
	}

	private ObjectPoolEntry FindOrCreatePool<T>(T newPrefab) where T : Behaviour
	{
		if (newPrefab != null)
		{
			ObjectPoolEntry objectPoolEntry = FindEntryForPrefab(newPrefab);
			if (objectPoolEntry == null)
			{
				objectPoolEntry = new ObjectPoolEntry<T>(newPrefab, this);
				poolEntries.Add(newPrefab, objectPoolEntry);
			}
			return objectPoolEntry;
		}
		return null;
	}

	private ObjectPoolEntry FindEntryForPrefab(Behaviour prefab)
	{
		poolEntries.TryGetValue(prefab, out var value);
		return value;
	}

	public void TrackInstantiation(string objectName)
	{
	}

	public void EnableStats(bool shouldEnable)
	{
	}

	public void ResetStats()
	{
	}
}
namespace RecRoom
{
	public abstract class ObjectPoolEntry
	{
		public abstract Behaviour Prefab { get; }

		public abstract string Name { get; }

		public abstract int InstanceCount { get; }

		public abstract void Prefill(int count);

		public abstract void SetMaxInstances(int maxInstances);

		public abstract Behaviour Acquire();

		public abstract bool Release(Behaviour behaviour);

		protected void SetPooledObjectActive(Behaviour obj, bool active, bool containsAnimation, bool pumpAnimationOnce = false)
		{
			if (obj is SFXAudioSource)
			{
				(obj as SFXAudioSource).enabled = active;
			}
			else if (containsAnimation)
			{
				Animation componentInChildren = obj.gameObject.GetComponentInChildren<Animation>();
				if (pumpAnimationOnce)
				{
					componentInChildren.Sample();
				}
				RecursiveSetActive(obj.transform, active);
			}
			else
			{
				obj.gameObject.SetActive(active);
			}
		}

		protected void RecursiveSetActive(Transform xform, bool active)
		{
			UnityEngine.Component[] components = xform.GetComponents<UnityEngine.Component>();
			foreach (UnityEngine.Component component in components)
			{
				if (component is Animation)
				{
					if (active)
					{
						(component as Animation).Sample();
					}
					else
					{
						(component as Animation).Stop();
					}
				}
				else if (component is UnityEngine.MonoBehaviour)
				{
					(component as UnityEngine.MonoBehaviour).enabled = active;
				}
				else if (component is Renderer)
				{
					(component as Renderer).enabled = active;
				}
			}
			int childCount = xform.childCount;
			for (int j = 0; j < childCount; j++)
			{
				RecursiveSetActive(xform.GetChild(j), active);
			}
		}
	}
	public class ObjectPoolEntry<T> : ObjectPoolEntry where T : Behaviour
	{
		private T prefab;

		private ObjectPool parentPool;

		private bool containsAnimation;

		private int maxInstances = -1;

		private Queue<T> availableInstances = new Queue<T>();

		private Queue<T> activeInstances = new Queue<T>();

		public override Behaviour Prefab => prefab;

		public override string Name => prefab.name;

		public override int InstanceCount => availableInstances.Count + activeInstances.Count;

		public ObjectPoolEntry(T prefab, ObjectPool parentPool)
		{
			this.prefab = prefab;
			this.parentPool = parentPool;
			containsAnimation = prefab.GetComponentInChildren<Animation>(includeInactive: true);
		}

		public override void Prefill(int count)
		{
			int instanceCount = InstanceCount;
			for (int i = instanceCount; i < count; i++)
			{
				T val = SpawnNewInstance();
				SetPooledObjectActive(val, active: false, containsAnimation, pumpAnimationOnce: true);
				availableInstances.Enqueue(val);
			}
			if (maxInstances > 0 && count > maxInstances)
			{
				UnityEngine.Debug.LogWarning($"ObjectPoolEntry for prefab {prefab} had a max instance count of {maxInstances}, but has now been prefilled with {count} instances. Adjusting...");
				maxInstances = count;
			}
		}

		public override void SetMaxInstances(int maxInstances)
		{
			if (InstanceCount > maxInstances)
			{
				UnityEngine.Debug.LogWarning($"Attempted to set max instance count of {maxInstances} for ObjectPoolEntry for prefab {prefab}, but it already contains {InstanceCount} instances. Adjusting...");
				maxInstances = InstanceCount;
			}
			this.maxInstances = maxInstances;
		}

		public override Behaviour Acquire()
		{
			while (availableInstances.Count > 0)
			{
				T val = availableInstances.Dequeue();
				if (val != null)
				{
					SetPooledObjectActive(val, active: true, containsAnimation);
					return val;
				}
				UnityEngine.Debug.LogError($"ObjectPool ({Name}) contains a null entry!");
			}
			if (prefab == null)
			{
				UnityEngine.Debug.LogError($"ObjectPool ({Name}) contains a null Prefab reference!");
				return null;
			}
			if (maxInstances > 0 && InstanceCount > maxInstances)
			{
				UnityEngine.Debug.LogWarning($"ObjectPool ({Name}) exceeded max instances of {maxInstances}. Recycling oldest live instance...");
				T val2 = activeInstances.Dequeue();
				if (val2 != null)
				{
					activeInstances.Enqueue(val2);
					return val2;
				}
				UnityEngine.Debug.LogError($"ObjectPoolEntry ({Name}) contains a null entry!");
			}
			return SpawnNewInstance();
		}

		public override bool Release(Behaviour behaviour)
		{
			T val = (T)behaviour;
			if (availableInstances.Contains(val))
			{
				return false;
			}
			SetPooledObjectActive(val, active: false, containsAnimation);
			availableInstances.Enqueue(val);
			if (parentPool != null)
			{
				val.transform.SetParent(parentPool.transform, worldPositionStays: false);
			}
			return true;
		}

		private T SpawnNewInstance()
		{
			parentPool.TrackInstantiation(Name);
			T result = UnityEngine.Object.Instantiate(prefab);
			PooledObject pooledObject = result.gameObject.AddComponent<PooledObject>();
			pooledObject.PoolEntry = this;
			result.transform.SetParent(parentPool.transform, worldPositionStays: false);
			return result;
		}
	}
}
public class ObjectPoolPreFill : UnityEngine.MonoBehaviour
{
	[Serializable]
	public struct PrefillDataEntry
	{
		public Behaviour prefab;

		public int numInstances;
	}

	public List<PrefillDataEntry> PrefillData = new List<PrefillDataEntry>();

	private void Start()
	{
		DateTime utcNow = DateTime.UtcNow;
		ObjectPool instance = ObjectPool.Instance;
		instance.EnableStats(shouldEnable: false);
		for (int i = 0; i < PrefillData.Count; i++)
		{
			instance.Prefill(PrefillData[i].prefab, PrefillData[i].numInstances);
		}
		instance.EnableStats(shouldEnable: true);
		instance.ResetStats();
		DateTime utcNow2 = DateTime.UtcNow;
		TimeSpan timeSpan = utcNow2 - utcNow;
		UnityEngine.Debug.LogFormat("Object pool prefill time (s): {0}", timeSpan.TotalSeconds);
		Console.WriteLine("Prefill time (s): {0}", timeSpan.TotalSeconds);
	}
}
