public class PooledParticle : UnityEngine.MonoBehaviour
{
	private enum FollowType
	{
		NONE,
		POSITION,
		ROTATION,
		POSITION_AND_ROTATION,
		VELOCITY
	}

	[Serializable]
	public class ColorConfiguration
	{
		[SerializeField]
		private ParticleSystem particleSystem;

		[SerializeField]
		private bool setStartColor;

		[SerializeField]
		private bool setMinColorOverLifetime;

		[SerializeField]
		private bool setMaxColorOverLifetime;

		public ColorConfiguration(ParticleSystem mainParticles)
		{
			particleSystem = mainParticles;
			setStartColor = true;
		}

		public void SetColor(Color color)
		{
			if (setStartColor)
			{
				ParticleSystem.MainModule main = particleSystem.main;
				main.startColor = color;
			}
			if (setMinColorOverLifetime || setMaxColorOverLifetime)
			{
				ParticleSystem.ColorOverLifetimeModule colorOverLifetime = particleSystem.colorOverLifetime;
				Gradient gradient = colorOverLifetime.color.gradient;
				GradientColorKey[] colorKeys = gradient.colorKeys;
				if (setMinColorOverLifetime)
				{
					colorKeys[0].color = color;
				}
				if (setMaxColorOverLifetime)
				{
					colorKeys[colorKeys.Length - 1].color = color;
				}
				gradient.SetKeys(colorKeys, gradient.alphaKeys);
				colorOverLifetime.color = gradient;
			}
		}
	}

	[SerializeField]
	protected ColorConfiguration[] colorConfigurations;

	[NonSerialized]
	public bool IsLooping;

	private ParticleSystem.MinMaxGradient[] startColors;

	private bool colorsDirty;

	private float initialSizeMultiplier;

	private float maxDuration;

	private Transform followTarget;

	private Vector3 followVelocity = Vector3.zero;

	private Vector3 followWorldSpaceOffset = Vector3.zero;

	private FollowType followTypeValue;

	public ParticleSystem PrimaryParticleSystem { get; private set; }

	public ParticleSystem[] AllParticleSystems { get; private set; }

	private FollowType followType
	{
		get
		{
			return followTypeValue;
		}
		set
		{
			followTypeValue = value;
			base.enabled = followTypeValue != FollowType.NONE;
		}
	}

	public static PooledParticle TryPlayPrefab(PooledParticle prefab, Vector3 position, Quaternion rotation)
	{
		PooledParticle pooledParticle = ((!(prefab != null)) ? null : ObjectPool.Instance.Acquire(prefab));
		if (pooledParticle != null)
		{
			pooledParticle.Play(position, rotation);
		}
		return pooledParticle;
	}

	public static PooledParticle TryPlayPrefab(PooledParticle prefab, Vector3 position)
	{
		return TryPlayPrefab(prefab, position, Quaternion.identity);
	}

	private void Reset()
	{
		ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>(includeInactive: true);
		if (componentsInChildren != null)
		{
			colorConfigurations = new ColorConfiguration[componentsInChildren.Length];
			for (int i = 0; i < colorConfigurations.Length; i++)
			{
				colorConfigurations[i] = new ColorConfiguration(componentsInChildren[i]);
			}
		}
	}

	protected virtual void Awake()
	{
		PrimaryParticleSystem = GetComponent<ParticleSystem>();
		ParticleSystem.MainModule main = PrimaryParticleSystem.main;
		main.playOnAwake = false;
		initialSizeMultiplier = main.startSizeMultiplier;
		AllParticleSystems = GetComponentsInChildren<ParticleSystem>(includeInactive: true);
		CalculateMaxDuration();
		followType = FollowType.NONE;
	}

	private void Update()
	{
		if (followType != FollowType.NONE)
		{
			if (followType == FollowType.VELOCITY)
			{
				base.transform.position += followVelocity * UnityEngine.Time.deltaTime;
			}
			if ((followType == FollowType.POSITION || followType == FollowType.POSITION_AND_ROTATION) && followTarget != null)
			{
				base.transform.position = followTarget.position + followWorldSpaceOffset;
			}
			if ((followType == FollowType.ROTATION || followType == FollowType.POSITION_AND_ROTATION) && followTarget != null)
			{
				base.transform.rotation = followTarget.rotation;
			}
		}
	}

	private void DeferredHide()
	{
		if (colorsDirty)
		{
			ResetColors();
		}
		CancelInvoke("DeferredHide");
		ObjectPool.Instance.Release(this);
	}

	public void SetDuration(float duration, bool setStartLifetime = false)
	{
		if (PrimaryParticleSystem.isPlaying)
		{
			PrimaryParticleSystem.Stop();
		}
		ParticleSystem.MainModule main = PrimaryParticleSystem.main;
		main.duration = duration;
		if (setStartLifetime)
		{
			main.startLifetime = duration;
		}
		CalculateMaxDuration();
	}

	public void Play(Transform followTransform)
	{
		Play(followTransform, loop: false);
	}

	public void Play(Transform followTransform, bool loop, float sizeMultiplier = -1f)
	{
		Play(followTransform.position, followTransform.rotation, loop, sizeMultiplier);
		followType = FollowType.POSITION_AND_ROTATION;
		followTarget = followTransform;
		followWorldSpaceOffset = Vector3.zero;
	}

	public void Play(Transform followTransform, Vector3 followWorldSpaceOffset, bool loop, float sizeMultiplier = -1f)
	{
		Play(followTransform.position, followTransform.rotation, loop, sizeMultiplier);
		followType = FollowType.POSITION_AND_ROTATION;
		followTarget = followTransform;
		this.followWorldSpaceOffset = followWorldSpaceOffset;
	}

	public void Play(Transform followPosition, Quaternion rotation, bool loop = false, float sizeMultiplier = -1f)
	{
		Play(followPosition.position, rotation, loop, sizeMultiplier);
		followType = FollowType.POSITION;
		followTarget = followPosition;
		followWorldSpaceOffset = Vector3.zero;
	}

	public void Play(Transform followPosition, Vector3 followWorldSpaceOffset, Quaternion rotation, bool loop = false, float sizeMultiplier = -1f)
	{
		Play(followPosition.position, rotation, loop, sizeMultiplier);
		followType = FollowType.POSITION;
		followTarget = followPosition;
		this.followWorldSpaceOffset = followWorldSpaceOffset;
	}

	public void Play(Vector3 position, Quaternion rotation, Vector3 velocity, bool loop = false, float sizeMultiplier = -1f)
	{
		Play(loop, sizeMultiplier);
		followType = FollowType.VELOCITY;
		followVelocity = velocity;
		base.transform.position = position;
		base.transform.rotation = rotation;
	}

	public void Play(Vector3 position, Quaternion rotation, bool loop = false, float sizeMultiplier = -1f)
	{
		Play(loop, sizeMultiplier);
		followType = FollowType.NONE;
		base.transform.position = position;
		base.transform.rotation = rotation;
	}

	public void Play(bool loop = false, float sizeMultiplier = -1f)
	{
		if (sizeMultiplier > 0f)
		{
			ParticleSystem.MainModule main = PrimaryParticleSystem.main;
			main.startSizeMultiplier = sizeMultiplier * initialSizeMultiplier;
		}
		PrimaryParticleSystem.Play();
		followType = FollowType.NONE;
		if (!loop)
		{
			Invoke("DeferredHide", maxDuration);
		}
	}

	public void Stop()
	{
		PrimaryParticleSystem.Stop();
		DeferredHide();
	}

	private void CacheColors()
	{
		startColors = new ParticleSystem.MinMaxGradient[AllParticleSystems.Length];
		for (int i = 0; i < AllParticleSystems.Length; i++)
		{
			ref ParticleSystem.MinMaxGradient reference = ref startColors[i];
			reference = AllParticleSystems[i].main.startColor;
		}
	}

	public void ResetColors()
	{
		if (colorsDirty && startColors != null)
		{
			for (int i = 0; i < AllParticleSystems.Length; i++)
			{
				ParticleSystem.MainModule main = AllParticleSystems[i].main;
				main.startColor = startColors[i];
			}
		}
		colorsDirty = false;
	}

	public void SetColor(Color color)
	{
		if (startColors == null)
		{
			CacheColors();
		}
		if (colorConfigurations != null && colorConfigurations.Length > 0)
		{
			ColorConfiguration[] array = colorConfigurations;
			foreach (ColorConfiguration colorConfiguration in array)
			{
				colorConfiguration.SetColor(color);
			}
		}
		else
		{
			for (int j = 0; j < AllParticleSystems.Length; j++)
			{
				ParticleSystem.MainModule main = AllParticleSystems[j].main;
				float alpha = 1f;
				if (main.startColor.mode == ParticleSystemGradientMode.Color)
				{
					alpha = main.startColor.color.a;
				}
				Color color2 = color.WithAlpha(alpha);
				main.startColor = color2;
			}
		}
		colorsDirty = true;
	}

	private void CalculateMaxDuration()
	{
		maxDuration = 0f;
		ParticleSystem[] allParticleSystems = AllParticleSystems;
		foreach (ParticleSystem particleSystem in allParticleSystems)
		{
			ParticleSystem.MainModule main = particleSystem.main;
			maxDuration = Mathf.Max(maxDuration, main.duration + main.startLifetime.constant);
		}
	}
}
public class OnPreRenderCallbacks : UnityEngine.MonoBehaviour
{
	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_PreRender;

	public event Action PreRender
	{
		add
		{
			Action action = this.m_PreRender;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PreRender, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_PreRender;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_PreRender, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void OnPreRender()
	{
		if (this.PreRender != null)
		{
			this.PreRender();
		}
	}
}
