namespace RecRoom.Utils.OverridableFields
{
	public interface IOverridableField
	{
		bool Overrides { get; }

		object ObjectValue { get; }
	}
	public interface IOverridableField<T> : IOverridableField
	{
		T Value { get; }
	}
	public interface IMutableOverridableField<T> : IOverridableField<T>, IOverridableField
	{
		new bool Overrides { get; set; }

		new T Value { get; set; }

		void CombineWith(IOverridableField<T> other);

		void Copy(IOverridableField<T> other);

		void Reset();
	}
	public interface ISynchronizedOverridableField<T> : IMutableOverridableField<T>, IOverridableField<T>, IOverridableField
	{
		bool IsDirty { get; }

		event Action OnFieldUpdatedEvent;
	}
	public interface IProtobufSerializableOverridableField<InnerType, ProtobufType> where ProtobufType : IMessage<ProtobufType>
	{
		ProtobufType SerializeToProtobuf();
	}
	public interface IProtobufDeserializableOverridableField<T, InnerType, ProtobufType> where T : IMutableOverridableField<InnerType> where ProtobufType : IMessage<ProtobufType>
	{
		void DeserializeFromProtobuf(ProtobufType proto);

		void DeserializeFromProtobufBytes(byte[] protoBytes);
	}
	[Serializable]
	public struct OverridableInt : IOverridableField<int>, IProtobufSerializableOverridableField<int, OverridableIntData>, IOverridableField
	{
		[SerializeField]
		private bool overrides;

		[SerializeField]
		private int value;

		public bool Overrides => overrides;

		public object ObjectValue => Value;

		public int Value => value;

		public OverridableInt(int value)
		{
			overrides = true;
			this.value = value;
