			OverridableColorData proto = OverridableColorData.Parser.ParseFrom(protoBytes);
			DeserializeFromProtobuf(proto);
		}

		public override void DeserializeFromProtobuf(OverridableColorData proto)
		{
			Value = proto.InnerValue.ToColor();
			Overrides = proto.Overrides;
		}

		public override OverridableColorData SerializeToProtobuf()
		{
			OverridableColorData overridableColorData = new OverridableColorData();
			overridableColorData.Overrides = Overrides;
			overridableColorData.InnerValue = Value.ToColorData();
			return overridableColorData;
		}
	}
}
namespace RecRoom.Core
{
	public class ParticleEventListener : UnityEngine.MonoBehaviour
	{
		public delegate void ParticleCollision(ParticleEventListener listener, Collider other, IEnumerable<ParticleCollisionEvent> collisions);

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private ParticleCollision m_CollisionEvent;

		private static readonly List<ParticleCollisionEvent> INSTANTANEOUS_PARTICLE_COLLISIONS = new List<ParticleCollisionEvent>();

		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private ParticleSystem particles;

		public event ParticleCollision CollisionEvent
		{
			add
			{
				ParticleCollision particleCollision = this.m_CollisionEvent;
				ParticleCollision particleCollision2;
				do
				{
					particleCollision2 = particleCollision;
					particleCollision = Interlocked.CompareExchange(ref this.m_CollisionEvent, (ParticleCollision)Delegate.Combine(particleCollision2, value), particleCollision);
				}
				while (particleCollision != particleCollision2);
			}
			remove
			{
				ParticleCollision particleCollision = this.m_CollisionEvent;
				ParticleCollision particleCollision2;
				do
				{
					particleCollision2 = particleCollision;
					particleCollision = Interlocked.CompareExchange(ref this.m_CollisionEvent, (ParticleCollision)Delegate.Remove(particleCollision2, value), particleCollision);
				}
				while (particleCollision != particleCollision2);
			}
		}

		private void OnParticleCollision(GameObject other)
		{
			INSTANTANEOUS_PARTICLE_COLLISIONS.Clear();
			int collisionEvents = particles.GetCollisionEvents(other, INSTANTANEOUS_PARTICLE_COLLISIONS);
			Collider collider = null;
			if (collisionEvents > 0)
			{
				collider = INSTANTANEOUS_PARTICLE_COLLISIONS[0].colliderComponent as Collider;
				int count = INSTANTANEOUS_PARTICLE_COLLISIONS.Count;
				if (collisionEvents < count)
				{
					INSTANTANEOUS_PARTICLE_COLLISIONS.RemoveRange(collisionEvents, count - collisionEvents);
				}
			}
			if (this.CollisionEvent != null && collider != null)
			{
				this.CollisionEvent(this, collider, INSTANTANEOUS_PARTICLE_COLLISIONS);
			}
		}
	}
}
