namespace RecRoom.Utils.Perf
{
	public class PerfClock
	{
		public class Item
		{
			public string Name;

			public Stopwatch Stopwatch = new Stopwatch();

			public Item(string name)
			{
				Name = name;
			}
		}

		private Dictionary<string, Item> dictionary = new Dictionary<string, Item>();

		private List<Item> list = new List<Item>();

		private readonly string title;

		public IReadOnlyCollection<Item> Items => list.AsReadOnly();

		public bool ShowInHeadset { get; set; }

		public PerfClock(string title)
		{
			this.title = title;
		}

		public void Start(string name)
		{
			if (dictionary.ContainsKey(name))
			{
				UnityEngine.Debug.LogWarning("Item already exists: " + name);
				return;
			}
			Item item = new Item(name);
			list.Add(item);
			dictionary.Add(name, item);
			item.Stopwatch.Start();
			if (ShowInHeadset)
			{
				DebugVR.LogPersistent("PerfClock", name);
			}
		}

		public void Pause(string name)
		{
			if (!dictionary.TryGetValue(name, out var value))
			{
				UnityEngine.Debug.LogWarning("Item doesn't exist: " + name);
			}
			else
			{
				value.Stopwatch.Stop();
			}
		}

		public void Resume(string name)
		{
			if (!dictionary.TryGetValue(name, out var value))
			{
				UnityEngine.Debug.LogWarning("Item doesn't exist: " + name);
			}
			else
			{
				value.Stopwatch.Start();
			}
		}

		public void Stop(string name)
		{
			if (!dictionary.TryGetValue(name, out var value))
			{
				UnityEngine.Debug.LogWarning("Item doesn't exist: " + name);
				return;
			}
			value.Stopwatch.Stop();
			if (ShowInHeadset)
			{
				DebugVR.ClearPersistent("PerfClock");
			}
		}

		public void StopAll()
		{
			foreach (Item item in list)
			{
				if (item.Stopwatch.IsRunning)
				{
					item.Stopwatch.Stop();
				}
			}
			if (ShowInHeadset)
			{
				DebugVR.ClearPersistent("PerfClock");
			}
		}

		public void Log()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("PerfClock: " + title);
			foreach (Item item in list)
			{
				stringBuilder.AppendLine(item.Name + ": " + item.Stopwatch.ElapsedMilliseconds);
			}
			UnityEngine.Debug.Log(stringBuilder.ToString());
		}
	}
	public class PerfTesterCameraRenderTimer : UnityEngine.MonoBehaviour
	{
		public Stopwatch RenderStopWatch;

		[ReadOnly]
		public bool StartQueued;

		[ReadOnly]
		public int FrameStart;

		[ReadOnly]
		public bool Running;

		[SerializeField]
		private int captureFrameCount = 100;

		public int renderCount;

		private void Awake()
		{
			Camera.onPreRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPreRender, new Camera.CameraCallback(PreRender));
			Camera.onPostRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPostRender, new Camera.CameraCallback(PostRender));
		}

		private void PreRender(Camera cam)
		{
			if (StartQueued)
			{
				StartQueued = false;
				Running = true;
				FrameStart = UnityEngine.Time.frameCount;
				RenderStopWatch = Stopwatch.StartNew();
				renderCount++;
			}
			else if (Running)
			{
				RenderStopWatch.Start();
				renderCount++;
			}
		}

		private void PostRender(Camera cam)
		{
			if (!Running)
			{
				return;
			}
			renderCount--;
			if (renderCount == 0)
			{
				RenderStopWatch.Stop();
				int num = UnityEngine.Time.frameCount - FrameStart;
				if (num >= captureFrameCount)
				{
					TimeSpan elapsed = RenderStopWatch.Elapsed;
					UnityEngine.Debug.Log(num + " Frames: " + ((float)elapsed.Milliseconds / (float)num).ToString("F5") + "ms");
					UnityEngine.Debug.Log("High Res: " + Stopwatch.IsHighResolution);
					Running = false;
					Camera.onPreRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPreRender, new Camera.CameraCallback(PreRender));
					Camera.onPostRender = (Camera.CameraCallback)Delegate.Remove(Camera.onPostRender, new Camera.CameraCallback(PostRender));
				}
			}
		}

		public void QueueTest()
		{
			Camera.onPreRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPreRender, new Camera.CameraCallback(PreRender));
			Camera.onPostRender = (Camera.CameraCallback)Delegate.Combine(Camera.onPostRender, new Camera.CameraCallback(PostRender));
			StartQueued = true;
		}

		private void Update()
		{
			if (Input.GetKeyDown(KeyCode.Alpha9))
			{
				UnityEngine.Debug.Log("Queueing Render Capture");
				QueueTest();
			}
		}
	}
	public class PerfTesterPostUpdate : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private PerfTesterPreUpdate preUpdate;

		[SerializeField]
		private int captureFrameCount = 100;

		private void Update()
		{
			if (preUpdate.Running)
			{
				preUpdate.FrameStopWatch.Stop();
				int num = UnityEngine.Time.frameCount - preUpdate.FrameStart;
				if (num >= captureFrameCount)
				{
					TimeSpan elapsed = preUpdate.FrameStopWatch.Elapsed;
					UnityEngine.Debug.Log(num + " Frames: " + ((float)elapsed.Milliseconds / (float)num).ToString("F5") + "ms");
					UnityEngine.Debug.Log("High Res: " + Stopwatch.IsHighResolution);
					preUpdate.Running = false;
				}
			}
			if (Input.GetKeyDown(KeyCode.Alpha0))
			{
				UnityEngine.Debug.Log("Queueing Capture");
				preUpdate.StartQueued = true;
			}
		}
	}
	public class PerfTesterPreUpdate : UnityEngine.MonoBehaviour
	{
		public Stopwatch FrameStopWatch;

		[ReadOnly]
		public int FrameStart;

		[ReadOnly]
		public bool StartQueued;

		[ReadOnly]
		public bool Running;

		private void Update()
		{
			if (StartQueued)
			{
				StartQueued = false;
				Running = true;
				FrameStart = UnityEngine.Time.frameCount;
				FrameStopWatch = Stopwatch.StartNew();
			}
			else if (Running)
			{
				FrameStopWatch.Start();
			}
		}
	}
}
public class PerformanceCounters : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class HistogramData
	{
		public string name;

		public Vector2 bounds;

		public bool InBounds(float value)
		{
			return bounds.WithinBounds(value);
		}
	}

	[SerializeField]
	private float updateIntervalFps = 1f;

	[SerializeField]
	private float updateIntervalRtt = 3f;

	private int frameCountFps;

	private float nextUpdateFps;

	private int frameCountRtt;

	private float nextUpdateRtt;

	private float accumulatedFPS;

	private int accumulatedRtt;

	public int? averageRtt;

	public float FPS { get; private set; }

	public int RoundTripTime
	{
		get
		{
			if (averageRtt.HasValue)
			{
				int? num = averageRtt;
				return num.Value;
			}
			return PhotonNetwork.GetPing() + PhotonNetwork.networkingPeer.RoundTripTimeVariance / 2;
		}
	}

	private void Start()
	{
		Reset();
		SceneManager.sceneLoaded += SceneManager_sceneLoaded;
	}

	private void OnDestroy()
	{
		SceneManager.sceneLoaded -= SceneManager_sceneLoaded;
	}

	private void Update()
	{
		UpdateFps();
		UpdateRtt();
	}

	private void UpdateRtt()
	{
		if (PhotonNetwork.inRoom)
		{
			frameCountRtt++;
			accumulatedRtt += PhotonNetwork.GetPing();
			if (UnityEngine.Time.time > nextUpdateRtt && frameCountRtt > 0)
			{
				averageRtt = accumulatedRtt / frameCountRtt;
				accumulatedRtt = 0;
				nextUpdateRtt = UnityEngine.Time.time + updateIntervalRtt;
				frameCountRtt = 0;
			}
		}
	}

	private void UpdateFps()
	{
		frameCountFps++;
		accumulatedFPS += UnityEngine.Time.timeScale / UnityEngine.Time.deltaTime;
		if (UnityEngine.Time.time > nextUpdateFps && frameCountFps > 0)
		{
			FPS = accumulatedFPS / (float)frameCountFps;
			accumulatedFPS = 0f;
			nextUpdateFps = UnityEngine.Time.time + updateIntervalFps;
			frameCountFps = 0;
		}
	}

	private void Reset()
	{
		ResetFps();
		ResetRtt();
	}

	private void ResetRtt()
	{
		averageRtt = null;
		frameCountRtt = 0;
		accumulatedRtt = 0;
		nextUpdateRtt = UnityEngine.Time.time + updateIntervalRtt;
	}

	private void ResetFps()
	{
		FPS = 0f;
		frameCountFps = 0;
		accumulatedRtt = 0;
		nextUpdateFps = UnityEngine.Time.time + updateIntervalFps;
	}

	private void SceneManager_sceneLoaded(Scene arg0, LoadSceneMode arg1)
	{
		ResetFps();
		ResetRtt();
	}
}
