	public class PlayerTypeDeactivateObject : UnityEngine.MonoBehaviour
	{
		public LocalPlayerController.PlayerType[] playerTypes;

		private void Awake()
		{
			if (playerTypes.Length == 0)
			{
				UnityEngine.Debug.LogWarning("PlayerTypeDeactivateObject requires at least one player type.");
				return;
			}
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.PlayerTypeChange = (Action)Delegate.Combine(instance.PlayerTypeChange, new Action(Refresh));
			Refresh();
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
			{
				LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
				instance.PlayerTypeChange = (Action)Delegate.Remove(instance.PlayerTypeChange, new Action(Refresh));
			}
		}

		private void Refresh()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && base.gameObject != null)
			{
				bool flag = playerTypes.Contains(SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType);
				base.gameObject.SetActive(!flag);
			}
		}
	}
