namespace RecRoom.Core.DataStructures
{
	public class RotatedBounds
	{
		public Vector3 center;

		public Quaternion rotation;

		public Vector3 halfSize;

		public bool GetConvexBounds(Collider collider, ref Bounds bounds)
		{
			BoxCollider boxCollider = collider as BoxCollider;
			if ((bool)boxCollider)
			{
				bounds = new Bounds(boxCollider.center, boxCollider.size);
				return true;
			}
			SphereCollider sphereCollider = collider as SphereCollider;
			if ((bool)sphereCollider)
			{
				bounds = new Bounds(sphereCollider.center, Vector3.one * (sphereCollider.radius * 2f));
				return true;
			}
			MeshCollider meshCollider = collider as MeshCollider;
			if ((bool)meshCollider && meshCollider.convex && (bool)meshCollider.sharedMesh)
			{
				Mesh sharedMesh = meshCollider.sharedMesh;
				bounds = new Bounds(sharedMesh.bounds.center, sharedMesh.bounds.size);
				return true;
			}
			return false;
		}

		public bool GetConvexMeshBounds(Collider collider, ref Bounds bounds)
		{
			return false;
		}

		public bool InitializeFromConvexBounds(Collider c)
		{
			Bounds bounds = default(Bounds);
			if (!GetConvexBounds(c, ref bounds))
			{
				return false;
			}
			center = c.transform.TransformPoint(bounds.center);
			rotation = c.transform.rotation;
			halfSize.x = Vector3.Distance(center, c.transform.TransformPoint(bounds.center + Vector3.right * bounds.extents.x));
			halfSize.y = Vector3.Distance(center, c.transform.TransformPoint(bounds.center + Vector3.up * bounds.extents.y));
			halfSize.z = Vector3.Distance(center, c.transform.TransformPoint(bounds.center + Vector3.forward * bounds.extents.z));
			return true;
		}

		public void Encapsulate(RotatedBounds other)
		{
			Quaternion quaternion = Quaternion.Inverse(rotation);
			Quaternion quaternion2 = quaternion * other.rotation;
			Vector3 vector = quaternion2 * (Vector3.right * other.halfSize.x);
			Vector3 vector2 = quaternion2 * (Vector3.up * other.halfSize.y);
			Vector3 vector3 = quaternion2 * (Vector3.forward * other.halfSize.z);
			Vector3 vector4 = quaternion * (other.center - center);
			Vector3 min = -halfSize;
			Vector3 max = halfSize;
			Vector3 vector5 = vector4 + vector2;
			UpdateMinMax(ref min, ref max, vector5 + vector + vector3);
			UpdateMinMax(ref min, ref max, vector5 + vector - vector3);
			UpdateMinMax(ref min, ref max, vector5 - vector + vector3);
			UpdateMinMax(ref min, ref max, vector5 - vector - vector3);
			Vector3 vector6 = vector4 - vector2;
			UpdateMinMax(ref min, ref max, vector6 + vector + vector3);
			UpdateMinMax(ref min, ref max, vector6 + vector - vector3);
			UpdateMinMax(ref min, ref max, vector6 - vector + vector3);
			UpdateMinMax(ref min, ref max, vector6 - vector - vector3);
			Vector3 vector7 = (min + max) * 0.5f;
			halfSize = (max - min) * 0.5f;
			center += rotation * vector7;
		}

		private static void UpdateMinMax(ref Vector3 min, ref Vector3 max, Vector3 pos)
		{
			min = Vector3.Min(min, pos);
			max = Vector3.Max(max, pos);
		}
	}
	public class RotatedBoundsCollision
	{
		private Vector3 collisionPoint;

		private Vector3 collisionDir;

		private bool hadCollisionLastFrame;

		private bool delaySnapping;

		private Vector3 collisionPivotPoint;

		private Quaternion collisionRotation;

		private Vector3 prevPivotPoint;

		private const float COLLISION_STICKY_STRENGTH = 0.6f;

		private const float MAX_ALIGNMENT_DISTANCE_FRACTION = 0.2f;

		private const float MAX_ALIGNMENT_DISTANCE = 0.1f;

		private const float MAX_ALIGNMENT_ANGLE = 15f;

		private const int MAX_NUM_COLLIDERS_ALLOWED = 100;

		private bool DEBUG_DRAW;

		private bool alignToEdges;

		private static List<GameObject> debugObjects = new List<GameObject>();

		private static Material debugMaterial;

		protected static List<RotatedBounds> localBounds = new List<RotatedBounds>(100);

		protected static RotatedBounds[] localBoundsMemory = null;

		private int localMemoryBoundsIndex;

		private RotatedBounds colliderBounds = new RotatedBounds();

		private static readonly float SIN_45 = Mathf.Sin((float)Math.PI / 4f);

		public static void ClearDebugObjects()
		{
			foreach (GameObject debugObject in debugObjects)
			{
				SafeDestroy.GameObject(debugObject);
			}
			debugObjects.Clear();
		}

		public static void AddDebugBox(Vector3 pos, Vector3 size, Quaternion rot, Color color)
		{
			if (debugMaterial == null)
			{
				debugMaterial = new Material(Shader.Find("Sprites/Default"));
			}
			GameObject gameObject = GameObject.CreatePrimitive(PrimitiveType.Cube);
			gameObject.GetComponent<Collider>().enabled = false;
			gameObject.GetComponent<Renderer>().material = debugMaterial;
			color.a = 0.1f;
			gameObject.GetComponent<Renderer>().material.color = color;
			gameObject.transform.position = pos;
			gameObject.transform.localScale = size + Vector3.one * 0.01f;
			gameObject.transform.rotation = rot;
			debugObjects.Add(gameObject);
		}

		private void InitBoundsMemory()
		{
			localMemoryBoundsIndex = 0;
			if (localBoundsMemory == null)
			{
				localBoundsMemory = new RotatedBounds[100];
				for (int i = 0; i < 100; i++)
				{
					localBoundsMemory[i] = new RotatedBounds();
				}
			}
		}

		private RotatedBounds TryGetNewPreAllocatedBounds()
		{
			if (localMemoryBoundsIndex < 100)
			{
				return localBoundsMemory[localMemoryBoundsIndex++];
			}
			return null;
		}

		public void ClearBounds()
		{
			ClearDebugObjects();
			localBounds.Clear();
		}

		public void SetupBounds(ISelectionColliderInterface selectionContext, int maxAllowedBounds, Vector3 pivotPoint, Quaternion pivotRotation, bool shouldAlignToEdges)
		{
			alignToEdges = shouldAlignToEdges;
			hadCollisionLastFrame = false;
			delaySnapping = true;
			collisionPivotPoint = pivotPoint;
			collisionRotation = pivotRotation;
			prevPivotPoint = pivotPoint;
			InitBoundsMemory();
			int num = 0;
			foreach (ToolCollider selectionToolCollider in selectionContext.GetSelectionToolColliders())
			{
				num += selectionToolCollider.PhysicsColliders.Count;
			}
			if (num > 100)
			{
				return;
			}
			foreach (ToolCollider selectionToolCollider2 in selectionContext.GetSelectionToolColliders())
			{
				foreach (Collider physicsCollider in selectionToolCollider2.PhysicsColliders)
				{
					RotatedBounds rotatedBounds = TryGetNewPreAllocatedBounds();
					if (rotatedBounds == null)
					{
						break;
					}
					if (rotatedBounds.InitializeFromConvexBounds(physicsCollider))
					{
						localBounds.Add(rotatedBounds);
					}
				}
			}
			localBounds.Sort((RotatedBounds a, RotatedBounds b) => b.halfSize.sqrMagnitude.CompareTo(a.halfSize.sqrMagnitude));
			int num2 = localBounds.Count;
			while (num2 > maxAllowedBounds)
			{
				num2--;
				localBounds[0].Encapsulate(localBounds[num2]);
				localBounds.RemoveAt(num2);
			}
			Quaternion quaternion = Quaternion.Inverse(pivotRotation);
			foreach (RotatedBounds localBound in localBounds)
			{
				localBound.center = quaternion * (localBound.center - pivotPoint);
				localBound.rotation = quaternion * localBound.rotation;
			}
		}

		public void UpdateCollisionSnapping(ref Vector3 newPivotPoint, ref Quaternion newPenRotation, bool lerpToDest, bool allowRotation, Func<Collider, bool> ignoreCollision)
		{
			if (hadCollisionLastFrame)
			{
				Vector3 vector = newPivotPoint - prevPivotPoint;
				vector -= collisionDir * Vector3.Dot(vector, collisionDir) * 0.6f;
				collisionPoint += vector;
				prevPivotPoint = newPivotPoint;
				newPivotPoint = collisionPoint;
			}
			else
			{
				prevPivotPoint = newPivotPoint;
				collisionPoint = newPivotPoint;
			}
			Vector3 newPos = newPivotPoint;
			Quaternion newRot = newPenRotation;
			if (SnapToCollision(ref newPos, ref newRot, ignoreCollision))
			{
				if (!delaySnapping)
				{
					Vector3 vector2 = newPos - newPivotPoint;
					if (vector2.sqrMagnitude > float.Epsilon)
					{
						vector2.Normalize();
						collisionDir = vector2;
						hadCollisionLastFrame = true;
					}
					else
					{
						hadCollisionLastFrame = false;
					}
					if (lerpToDest && hadCollisionLastFrame)
					{
						collisionPivotPoint = Vector3.Lerp(collisionPivotPoint, newPos, 0.4f);
						collisionRotation = Quaternion.Slerp(collisionRotation, newRot, 0.3f);
					}
					else
					{
						collisionPivotPoint = newPos;
						collisionRotation = newRot;
					}
					newPivotPoint = collisionPivotPoint;
					if (allowRotation)
					{
						newPenRotation = collisionRotation;
					}
				}
			}
			else
			{
				delaySnapping = false;
				hadCollisionLastFrame = false;
				collisionPivotPoint = newPivotPoint;
				collisionRotation = newPenRotation;
			}
		}

		private bool SnapToCollision(ref Vector3 newPos, ref Quaternion newRot, Func<Collider, bool> ignoreCollision)
		{
			bool result = false;
			foreach (RotatedBounds localBound in localBounds)
			{
				Vector3 newPos2 = newPos + newRot * localBound.center;
				Quaternion newRot2 = newRot * localBound.rotation;
				if (SnapToCollisionInternal(ref newPos2, ref newRot2, localBound.halfSize, ignoreCollision))
				{
					result = true;
					newRot = newRot2 * Quaternion.Inverse(localBound.rotation);
					newPos = newPos2 - newRot * localBound.center;
				}
			}
			return result;
		}

		private bool AlignToCollider(Vector3 boundsPos, Quaternion boundsRot, Vector3 boundsHalfSize, Collider collider, out Vector3 newPos, out Quaternion newRot, out Vector3 normalAxis)
		{
			newPos = boundsPos;
			newRot = boundsRot;
			normalAxis = Vector3.zero;
			MeshCollider meshCollider = collider as MeshCollider;
			if ((bool)meshCollider)
			{
				if (meshCollider.convex)
				{
					Vector3 vector = collider.ClosestPoint(boundsPos);
					Vector3 normal = boundsPos - vector;
					if (normal.sqrMagnitude > float.Epsilon)
					{
						float magnitude = normal.magnitude;
						normal /= magnitude;
						SnapToConvexMeshCollider(meshCollider, ref newPos, ref newRot, normal, magnitude, boundsHalfSize);
					}
					return true;
				}
				return false;
			}
			return SnapToBoxCollider(ref newPos, ref newRot, boundsHalfSize, collider, ref normalAxis);
		}

		private bool SnapToCollisionInternal(ref Vector3 newPos, ref Quaternion newRot, Vector3 boundsHalfSize, Func<Collider, bool> ignoreCollision)
		{
			bool result = false;
			Collider[] array = Physics.OverlapBox(newPos, boundsHalfSize, newRot, 159788032, QueryTriggerInteraction.Ignore);
			if (DEBUG_DRAW)
			{
				AddDebugBox(newPos, boundsHalfSize * 2f, newRot, (array.Length <= 1) ? Color.yellow : Color.green);
			}
			List<Vector3> list = new List<Vector3>();
			Collider[] array2 = array;
			foreach (Collider collider in array2)
			{
				if (ignoreCollision(collider) || !AlignToCollider(newPos, newRot, boundsHalfSize, collider, out var newPos2, out var newRot2, out var normalAxis))
				{
					continue;
				}
				result = true;
				Vector3 vector = newPos2 - newPos;
				foreach (Vector3 item in list)
				{
					vector -= item * Mathf.Max(Vector3.Dot(vector, item), 0f);
				}
				if (vector.sqrMagnitude > Mathf.Epsilon)
				{
					list.Add(normalAxis);
					newRot = newRot2;
					newPos += vector;
				}
			}
			return result;
		}

		private bool SnapToBoxCollider(ref Vector3 newPos, ref Quaternion newRot, Vector3 boundsHalfSize, Collider collider, ref Vector3 normalAxis)
		{
			if (!colliderBounds.InitializeFromConvexBounds(collider))
			{
				return false;
			}
			float num = Mathf.Min(boundsHalfSize.x, Mathf.Min(boundsHalfSize.y, boundsHalfSize.z)) * 0.5f;
			float num2 = Mathf.Max(colliderBounds.halfSize.x, Mathf.Max(colliderBounds.halfSize.y, colliderBounds.halfSize.z));
			if (num2 < num)
			{
				if (DEBUG_DRAW)
				{
					AddDebugBox(colliderBounds.center, colliderBounds.halfSize * 2f, colliderBounds.rotation, Color.red);
				}
				return false;
			}
			if (DEBUG_DRAW)
			{
				AddDebugBox(colliderBounds.center, colliderBounds.halfSize * 2f, colliderBounds.rotation, Color.blue);
			}
			Vector3 bestAxis = Vector3.zero;
			float bestOffset = float.MinValue;
			bool flag = SnapCollisionToAxis(colliderBounds.rotation * Vector3.right, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.x, ref bestAxis, ref bestOffset);
			flag |= SnapCollisionToAxis(colliderBounds.rotation * Vector3.up, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.y, ref bestAxis, ref bestOffset);
			if (!(flag | SnapCollisionToAxis(colliderBounds.rotation * Vector3.forward, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.z, ref bestAxis, ref bestOffset)))
			{
				newRot = RotateToFitDirection(bestAxis, newRot);
				newPos -= bestAxis * bestOffset;
			}
			if (alignToEdges)
			{
				AlignCollisionToAxis(colliderBounds.rotation * Vector3.right, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.x, bestAxis);
				AlignCollisionToAxis(colliderBounds.rotation * Vector3.up, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.y, bestAxis);
				AlignCollisionToAxis(colliderBounds.rotation * Vector3.forward, ref newPos, ref newRot, boundsHalfSize, colliderBounds.center, colliderBounds.halfSize.z, bestAxis);
			}
			normalAxis = -bestAxis;
			return true;
		}

		private void SnapToConvexMeshCollider(MeshCollider c, ref Vector3 newPos, ref Quaternion newRot, Vector3 normal, float dist, Vector3 boundsHalfSize)
		{
			float axisSizeFromDirection = GetAxisSizeFromDirection(newRot, normal, boundsHalfSize);
			float num = dist - axisSizeFromDirection;
			newRot = RotateToFitDirection(normal, newRot);
			newPos -= normal * num;
		}

		public static Vector3 GetClosestAxis(Vector3 dir, Quaternion rot)
		{
			Vector3 vector = Quaternion.Inverse(rot) * dir;
			if (Mathf.Abs(vector.x) > SIN_45)
			{
				return rot * Vector3.right * Mathf.Sign(vector.x);
			}
			if (Mathf.Abs(vector.y) > SIN_45)
			{
				return rot * Vector3.up * Mathf.Sign(vector.y);
			}
			return rot * Vector3.forward * Mathf.Sign(vector.z);
		}

		private static float GetAxisSizeFromDirection(Quaternion rot, Vector3 dir, Vector3 size)
		{
			Vector3 vector = Quaternion.Inverse(rot) * dir;
			if (Mathf.Abs(vector.x) > SIN_45)
			{
				return size.x;
			}
			if (Mathf.Abs(vector.y) > SIN_45)
			{
				return size.y;
			}
			return size.z;
		}

		private static Quaternion RotateToFitDirection(Vector3 direction, Quaternion rotation)
		{
			Vector3 closestAxis = GetClosestAxis(direction, rotation);
			float angle = Vector3.Angle(closestAxis, direction);
			Quaternion quaternion = Quaternion.AngleAxis(angle, Vector3.Cross(closestAxis, direction));
			return quaternion * rotation;
		}

		private static bool SnapCollisionToAxis(Vector3 axis, ref Vector3 position, ref Quaternion rotation, Vector3 boundsHalfSize, Vector3 colliderPos, float colliderHalfSize, ref Vector3 bestAxis, ref float bestOffset)
		{
			Vector3 lhs = position - colliderPos;
			float num = Vector3.Dot(lhs, axis);
			if (num < 0f)
			{
				num = 0f - num;
				axis = -axis;
			}
			float axisSizeFromDirection = GetAxisSizeFromDirection(rotation, axis, boundsHalfSize);
			float num2 = num - (axisSizeFromDirection + colliderHalfSize);
			if (num2 >= 0f)
			{
				rotation = RotateToFitDirection(axis, rotation);
				position -= axis * num2;
				bestOffset = num2;
				bestAxis = axis;
				return true;
			}
			if (num2 > bestOffset)
			{
				bestOffset = num2;
				bestAxis = axis;
			}
			return false;
		}

		private static void AlignCollisionToAxis(Vector3 axis, ref Vector3 position, ref Quaternion rotation, Vector3 boundsHalfSize, Vector3 colliderPos, float colliderHalfSize, Vector3 ignoreAxis)
		{
			if (Mathf.Abs(Vector3.Dot(axis, ignoreAxis)) > 0.9f)
			{
				return;
			}
			Vector3 lhs = position - colliderPos;
			float num = Vector3.Dot(lhs, axis);
			if (num < 0f)
			{
				num = 0f - num;
				axis = -axis;
			}
			float axisSizeFromDirection = GetAxisSizeFromDirection(rotation, axis, boundsHalfSize);
			float num2 = ((!(axisSizeFromDirection > colliderHalfSize)) ? (num - (colliderHalfSize - axisSizeFromDirection)) : (num - (axisSizeFromDirection - colliderHalfSize)));
			float b = Mathf.Max(Mathf.Min(axisSizeFromDirection * 0.2f, colliderHalfSize), Mathf.Min(colliderHalfSize * 0.2f, axisSizeFromDirection));
			b = Mathf.Min(0.1f, b);
			if (Mathf.Abs(num2) < b)
			{
				Quaternion quaternion = RotateToFitDirection(axis, rotation);
				if (Quaternion.Angle(quaternion, rotation) < 15f)
				{
					position -= axis * num2;
					rotation = quaternion;
				}
			}
		}
	}
}
