public class ScalePulse : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float scalePulseAmount;

	[SerializeField]
	private float scalePulseSpeed;

	private float startingScale;

	private void Awake()
	{
		startingScale = base.transform.localScale.x;
		scalePulseSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void Update()
	{
		Vector3 localScale = base.transform.localScale;
		localScale.z = (localScale.y = (localScale.x = startingScale + Mathf.Sin(UnityEngine.Time.time * scalePulseSpeed) * scalePulseAmount));
		base.transform.localScale = localScale;
	}
}
namespace RecRoom.Core.Rendering
{
	public class SceneCulling
	{
		private List<Light> cullableLights = new List<Light>();

		private List<Renderer> cullableRenderers = new List<Renderer>();

		public void FindCullables(Transform root)
		{
			Light[] componentsInChildren = root.GetComponentsInChildren<Light>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				cullableLights.Add(componentsInChildren[i]);
			}
			Renderer[] componentsInChildren2 = root.GetComponentsInChildren<Renderer>();
			for (int j = 0; j < componentsInChildren2.Length; j++)
			{
				if (IsCullable(componentsInChildren2[j]))
				{
					cullableRenderers.Add(componentsInChildren2[j]);
				}
			}
		}

		public void Cull(bool cullingEnabled)
		{
			for (int i = 0; i < cullableLights.Count; i++)
			{
				if (cullableLights[i] != null)
				{
					cullableLights[i].enabled = !cullingEnabled;
				}
			}
			for (int j = 0; j < cullableRenderers.Count; j++)
			{
				if (cullableRenderers[j] != null)
				{
					cullableRenderers[j].enabled = !cullingEnabled;
				}
			}
		}

		private bool IsCullable(Renderer renderer)
		{
			return renderer.enabled && renderer.gameObject.activeSelf && renderer.gameObject.IsInLayerMask(LayerMasks.DefaultOrStaticPhysics);
		}
	}
}
