namespace RecRoom
{
	public class SecretCode
	{
		private KeyCode[] keysCode;

		private string stringCode;

		private int index;

		public SecretCode(string code)
		{
			stringCode = code;
		}

		public SecretCode(KeyCode[] code)
		{
			keysCode = code;
		}

		public bool Check()
		{
			if (Input.anyKeyDown)
			{
				if (stringCode != null)
				{
					return CheckStringCode();
				}
				return CheckKeysCode();
			}
			return false;
		}

		private bool CheckStringCode()
		{
			if (Input.inputString.Length != 1)
			{
				index = 0;
				return false;
			}
			if (Input.inputString[0] != stringCode[index])
			{
				index = 0;
				return false;
			}
			index++;
			if (index >= stringCode.Length)
			{
				index = 0;
				return true;
			}
			return false;
		}

		private bool CheckKeysCode()
		{
			if (!Input.GetKeyDown(keysCode[index]))
			{
				index = 0;
				return false;
			}
			index++;
			if (index >= keysCode.Length)
			{
				index = 0;
				return true;
			}
			return false;
		}
	}
