public class SingletonMonoBehaviour<T> : SingletonMonoBehaviourBase where T : SingletonMonoBehaviour<T>
{
	private static T instance;

	public static T Instance
	{
		get
		{
			return instance;
		}
		private set
		{
			if (instance == null)
			{
				instance = value;
			}
			else
			{
				UnityEngine.Debug.LogError("Created more than one singleton of " + typeof(T).ToString() + "!");
			}
		}
	}

	public static bool IsInitialized => Instance != null;

	protected virtual void Awake()
	{
		if (instance != null && GameRestartBehavior == GameRestartBehaviors.DestroyNew)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		instance = (T)this;
		GameRoot.AddExistingSingleton(this);
	}

	protected virtual void OnDestroy()
	{
		if (instance == this)
		{
			instance = (T)null;
		}
		GameRoot.ExistingGameSingletons.Remove(this);
	}
}
