namespace RecRoom
{
	public class SynchronizedComponent<T> where T : Photon.MonoBehaviour
	{
		private SynchronizedField<int> _synchronizedViewId;

		private PhotonView cachedPhotonView;

		private T cachedComponentReference;

		public SynchronizedComponent(Photon.MonoBehaviour component, string id, SetterPermissionMode permissionMode, Action onChangeCallback = null)
		{
			_synchronizedViewId = new SynchronizedField<int>(component, id, 0, permissionMode, onChangeCallback);
		}

		public T Get()
		{
			if (cachedComponentReference == null || cachedPhotonView.viewID != _synchronizedViewId.Get())
			{
				cachedPhotonView = PhotonView.Find(_synchronizedViewId.Get());
				cachedComponentReference = (((object)cachedPhotonView != null) ? cachedPhotonView.GetComponent<T>() : ((T)null));
			}
			return cachedComponentReference;
		}

