public enum SetterPermissionMode
{
	AUTHORITY,
	MASTER,
	ANYONE,
	MASTER_OR_AUTHORITY
}
public abstract class SynchronizedField
{
	private const int MAX_UPDATES_PER_FLUSH = 50;

	private const string SetterInfoKey = "S";

	protected readonly PhotonPlayer player;

	protected readonly Photon.MonoBehaviour component;

	protected readonly string key;

	protected readonly SetterPermissionMode permissionMode;

	protected readonly Action callback;

	private bool lastSetLocally;

	private bool suppressCallback;

	private readonly string callbackProfilingLabel;

	private int revision;

	private bool alreadyDisposed;

	protected static Dictionary<string, Action<object, int>> RoomPropertyCallbackMap;

	protected static Dictionary<PhotonPlayer, Dictionary<string, Action<object, int>>> PlayerPropertyCallbackMaps;

	private static ExitGames.Client.Photon.Hashtable pendingRoomPropertyUpdates;

	private static List<string> pendingRoomPropertyUpdatesOrder;

	private static ExitGames.Client.Photon.Hashtable pendingPlayerPropertyUpdates;

	private static List<string> pendingPlayerPropertyUpdatesOrder;

	protected virtual object cachedValue { get; set; }

	public bool HasValue => cachedValue != null;

	public int Revision => revision;

	static SynchronizedField()
	{
		RoomPropertyCallbackMap = new Dictionary<string, Action<object, int>>();
		PlayerPropertyCallbackMaps = new Dictionary<PhotonPlayer, Dictionary<string, Action<object, int>>>();
		pendingRoomPropertyUpdates = new ExitGames.Client.Photon.Hashtable();
		pendingRoomPropertyUpdatesOrder = new List<string>();
		pendingPlayerPropertyUpdates = new ExitGames.Client.Photon.Hashtable();
		pendingPlayerPropertyUpdatesOrder = new List<string>();
		PhotonNetwork.OnPhotonCustomRoomPropertiesChanged += new Action<ExitGames.Client.Photon.Hashtable>(ProcessRoomPropertyUpdates);
		PhotonNetwork.OnPhotonPlayerPropertiesChanged += new Action<PhotonPlayer, ExitGames.Client.Photon.Hashtable>(ProcessPlayerPropertyUpdates);
		PhotonNetwork.OnPhotonPlayerDisconnected += (Action<PhotonPlayer>)delegate(PhotonPlayer otherPlayer)
		{
			UnregisterPlayerPropertyCallbacks(otherPlayer);
			if (PhotonNetwork.isMasterClient)
			{
