	protected SynchronizedField(PhotonPlayer player, Photon.MonoBehaviour component, string key, SetterPermissionMode permissionMode, Action callback)
	{
		this.player = player;
		this.component = component;
		this.key = key;
		this.permissionMode = permissionMode;
		this.callback = callback;
		callbackProfilingLabel = ((callback == null || !(callback.Method != null)) ? $"SynchronizedFieldCallback({key})" : $"{callback.Method.DeclaringType.Name}.{callback.Method.Name}()");
		if (component != null)
		{
			component.photonView.OnDestroying += RemoveCallback;
			component.OnDestroyEvent += Dispose;
		}
		AddCallback();
	}

	~SynchronizedField()
	{
		Dispose();
	}

	private void Dispose()
	{
		if (!alreadyDisposed)
		{
			alreadyDisposed = true;
			if (component != null)
			{
				component.photonView.OnDestroying -= RemoveCallback;
				component.OnDestroyEvent -= Dispose;
			}
			RemoveCallback();
			if (player == null && PhotonNetwork.inRoom)
			{
				Set(null);
			}
		}
	}

	protected void Initialize(bool enforceInitialValue, object initialValue)
	{
		cachedValue = ((player != null) ? GetPlayerValue(player, key) : GetRoomValue(key));
		if (enforceInitialValue && cachedValue != null && HasPermissionToEnforceInitialValue())
		{
			suppressCallback = true;
			Set(initialValue);
			suppressCallback = false;
		}
	}

	protected void Set(object newValue)
	{
		if (HasPermissionToSet() && !ObjectsAreEqual(newValue, cachedValue))
		{
			if (player == null)
			{
				SetRoomValue(key, newValue);
