			else
			{
				SetPlayerValue(player, key, newValue);
			}
			lastSetLocally = true;
			OnValueChanged(newValue);
		}
	}

	private void AddCallback()
	{
		Dictionary<string, Action<object, int>> value;
		if (player == null)
		{
			value = RoomPropertyCallbackMap;
		}
		else if (!PlayerPropertyCallbackMaps.TryGetValue(player, out value))
		{
			value = new Dictionary<string, Action<object, int>>();
			PlayerPropertyCallbackMaps.Add(player, value);
		}
		AddToCallbackMap(value, key, OnPhotonPropertyChanged);
