	private void RemoveCallback(PhotonView destroyingPhotonView = null)
	{
		Dictionary<string, Action<object, int>> value;
		if (player == null)
		{
			RemoveFromCallbackMap(RoomPropertyCallbackMap, key, OnPhotonPropertyChanged);
		}
		else if (PlayerPropertyCallbackMaps.TryGetValue(player, out value))
		{
			RemoveFromCallbackMap(value, key, OnPhotonPropertyChanged);
			if (value.Count == 0)
			{
				PlayerPropertyCallbackMaps.Remove(player);
			}
		}
	}

	private bool HasPermissionToEnforceInitialValue()
	{
		if (player == null)
		{
			bool isMasterClient = PhotonNetwork.isMasterClient;
			bool flag = component != null && component.hasAuthority;
			return (permissionMode == SetterPermissionMode.ANYONE && isMasterClient) || (permissionMode == SetterPermissionMode.MASTER && isMasterClient) || (permissionMode == SetterPermissionMode.AUTHORITY && flag) || (permissionMode == SetterPermissionMode.MASTER_OR_AUTHORITY && isMasterClient);
		}
		return false;
	}

	private bool HasPermissionToSet()
	{
		if (player == null)
		{
			bool isMasterClient = PhotonNetwork.isMasterClient;
			bool flag = component != null && component.hasAuthority;
			return permissionMode == SetterPermissionMode.ANYONE || (permissionMode == SetterPermissionMode.MASTER && isMasterClient) || (permissionMode == SetterPermissionMode.AUTHORITY && flag) || (permissionMode == SetterPermissionMode.MASTER_OR_AUTHORITY && (isMasterClient || flag));
