	private void OnPhotonPropertyChanged(object newValue, int setterId)
	{
		if (setterId != PhotonNetwork.player.ID)
		{
			lastSetLocally = false;
		}
		if (!lastSetLocally)
		{
			OnValueChanged(newValue);
		}
	}

	private void OnValueChanged(object newValue)
	{
		if (!alreadyDisposed)
		{
			object b = cachedValue;
			cachedValue = newValue;
			revision = (revision + 1) % int.MaxValue;
			if (!suppressCallback && callback != null && !ObjectsAreEqual(newValue, b))
			{
				callback();
			}
		}
	}

	public static void SetLocalPlayerValue<T>(string key, T value)
	{
		SetPlayerValue(PhotonNetwork.player, key, ToSerializablePhotonObject(value));
	}

	private static void SetPlayerValue(PhotonPlayer player, string key, object value)
	{
		if (pendingPlayerPropertyUpdates.ContainsKey(key))
		{
			SendPendingPlayerUpdates();
		}
		else if (pendingPlayerPropertyUpdates.Count > 50)
		{
			SendPendingPlayerUpdates();
		}
		pendingPlayerPropertyUpdates[key] = value;
		pendingPlayerPropertyUpdatesOrder.Add(key);
	}

	private static object GetPlayerValue(PhotonPlayer player, string key)
	{
		player.CustomProperties.TryGetValue(key, out var value);
		return value;
	}

	private static void SetRoomValue(string key, object value)
	{
		if (PhotonNetwork.inRoom)
		{
			if (pendingRoomPropertyUpdates.ContainsKey(key))
			{
				SendPendingRoomUpdates();
			}
			else if (pendingRoomPropertyUpdates.Count > 50)
			{
				SendPendingRoomUpdates();
			}
			pendingRoomPropertyUpdates[key] = value;
			pendingRoomPropertyUpdatesOrder.Add(key);
		}
	}

	private static object GetRoomValue(string key)
	{
		object value = null;
		if (PhotonNetwork.inRoom)
		{
			PhotonNetwork.room.CustomProperties.TryGetValue(key, out value);
		}
		return value;
	}

	public static void UnregisterAllRoomPropertyCallbacks()
	{
		RoomPropertyCallbackMap.Clear();
	}

	public static void UnregisterAllPlayerPropertyCallbacks()
	{
		PlayerPropertyCallbackMaps.Clear();
	}

	public static void UnregisterPlayerPropertyCallbacks(PhotonPlayer player)
	{
		PlayerPropertyCallbackMaps.Remove(player);
	}

	public static void ProcessRoomPropertyUpdates(ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		InvokeCallbacksForProperties(propertiesThatChanged, RoomPropertyCallbackMap);
	}

	public static void ProcessPlayerPropertyUpdates(PhotonPlayer player, ExitGames.Client.Photon.Hashtable propertiesThatChanged)
	{
		if (PlayerPropertyCallbackMaps.TryGetValue(player, out var value))
		{
			InvokeCallbacksForProperties(propertiesThatChanged, value);
		}
	}

	private static void InvokeCallbacksForProperties(ExitGames.Client.Photon.Hashtable propertiesThatChanged, Dictionary<string, Action<object, int>> callbackMap)
	{
		GetSetterInfoFromPropertyUpdate(propertiesThatChanged, out var setterId, out var propertySequence);
		if (propertySequence != null)
		{
			string[] array = propertySequence;
			foreach (string text in array)
			{
				if (callbackMap.TryGetValue(text, out var value))
				{
					value(propertiesThatChanged[text], setterId);
				}
				propertiesThatChanged.Remove(text);
			}
		}
		foreach (object key in propertiesThatChanged.Keys)
		{
			if (key is string text2 && callbackMap.TryGetValue(text2, out var value2))
			{
				value2(propertiesThatChanged[text2], setterId);
			}
		}
	}

	private static void AddToCallbackMap(Dictionary<string, Action<object, int>> callbackMap, string key, Action<object, int> callback)
	{
		if (callbackMap.ContainsKey(key))
		{
			Dictionary<string, Action<object, int>> dictionary;
			string text;
			(dictionary = callbackMap)[text = key] = (Action<object, int>)Delegate.Combine(dictionary[text], callback);
		}
		else
		{
			callbackMap[key] = callback;
		}
	}

	private static void RemoveFromCallbackMap(Dictionary<string, Action<object, int>> callbackMap, string key, Action<object, int> callback)
	{
		if (callbackMap.ContainsKey(key))
		{
			Dictionary<string, Action<object, int>> dictionary;
			string text;
			(dictionary = callbackMap)[text = key] = (Action<object, int>)Delegate.Remove(dictionary[text], callback);
			if (callbackMap[key] == null)
			{
				callbackMap.Remove(key);
			}
		}
	}

	public static void SendPendingRoomUpdates()
	{
		if (PhotonNetwork.inRoom && pendingRoomPropertyUpdates.Count > 0)
		{
			AddSetterInfoToPendingUpdates(pendingRoomPropertyUpdates, pendingRoomPropertyUpdatesOrder);
			PhotonNetwork.room.SetCustomProperties(pendingRoomPropertyUpdates, PUNNetworkManager.PhotonRoomPropertiesBugWorkaround);
			pendingRoomPropertyUpdates.Clear();
			pendingRoomPropertyUpdatesOrder.Clear();
		}
	}

	public static void SendPendingPlayerUpdates()
	{
		if (pendingPlayerPropertyUpdates.Count > 0)
		{
			AddSetterInfoToPendingUpdates(pendingPlayerPropertyUpdates, pendingPlayerPropertyUpdatesOrder);
			PhotonNetwork.player.SetCustomProperties(pendingPlayerPropertyUpdates);
			pendingPlayerPropertyUpdates.Clear();
			pendingPlayerPropertyUpdatesOrder.Clear();
		}
	}

	private static void AddSetterInfoToPendingUpdates(ExitGames.Client.Photon.Hashtable pendingUpdates, List<string> pendingUpdateOrder)
	{
		pendingUpdates["S"] = ((pendingUpdateOrder.Count <= 1) ? ((object)PhotonNetwork.player.ID) : new object[2]
		{
			PhotonNetwork.player.ID,
			pendingUpdateOrder.ToArray()
		});
	}

	private static void GetSetterInfoFromPropertyUpdate(ExitGames.Client.Photon.Hashtable propertiesThatChanged, out int setterId, out string[] propertySequence)
	{
		setterId = PhotonPlayer.Invalid;
		propertySequence = null;
		if (propertiesThatChanged.TryGetValue("S", out var value) && value != null)
		{
			if (value is int)
			{
				setterId = (int)value;
				return;
			}
			object[] array = (object[])value;
			setterId = (int)array[0];
			propertySequence = (string[])array[1];
		}
	}

	public static void AbandonPendingRoomPropertyUpdates()
	{
		pendingRoomPropertyUpdates.Clear();
		pendingRoomPropertyUpdatesOrder.Clear();
	}

	public static void ClearAllRoomPropertiesForPlayer(PhotonPlayer player)
	{
		string prefix = FormatRoomDataPlayerKey(player, string.Empty);
		ClearAllRoomPropertiesForPrefix(prefix);
	}

	public static void ClearAllRoomPropertiesForPhotonObject(Photon.MonoBehaviour component)
	{
		string prefix = FormatRoomDataPhotonObjectKey(component, string.Empty);
		ClearAllRoomPropertiesForPrefix(prefix);
	}

	public static void ClearAllRoomPropertiesForMissingPlayers()
	{
		if (!PhotonNetwork.inRoom)
		{
			return;
		}
		HashSet<string> hashSet = new HashSet<string>();
		PhotonPlayer[] playerList = PhotonNetwork.playerList;
		foreach (PhotonPlayer photonPlayer in playerList)
		{
			hashSet.Add(photonPlayer.ID.ToString());
		}
		foreach (string key in PhotonNetwork.room.CustomProperties.Keys)
		{
			if (!key.StartsWith("P"))
			{
				continue;
			}
			string[] array = key.Split('.');
			if (array.Length <= 1 || array[0].Length <= 1)
			{
				continue;
			}
			try
			{
				string item = array[0].Substring(1);
				if (!hashSet.Contains(item))
				{
					pendingRoomPropertyUpdates[key] = null;
					RoomPropertyCallbackMap.Remove(key);
				}
			}
			catch
			{
			}
		}
	}

	private static void ClearAllRoomPropertiesForPrefix(string prefix)
	{
		if (!PhotonNetwork.inRoom)
		{
			return;
		}
		foreach (string key in PhotonNetwork.room.CustomProperties.Keys)
		{
			if (key.StartsWith(prefix))
			{
				pendingRoomPropertyUpdates[key] = null;
				RoomPropertyCallbackMap.Remove(key);
			}
		}
	}

	protected static string FormatRoomDataPlayerKey(PhotonPlayer player, string key)
	{
		return $"P{player.ID}.{key}";
	}

	protected static string FormatRoomDataPhotonObjectKey(Photon.MonoBehaviour component, string key)
	{
		return $"{component.photonView.viewID}.{key}";
	}

	protected static object ToSerializablePhotonObject<T>(T value)
	{
		System.Type typeFromHandle = typeof(T);
		if (typeFromHandle.IsEnum)
		{
			System.Type underlyingType = System.Enum.GetUnderlyingType(typeFromHandle);
			return Convert.ChangeType(value, underlyingType, CultureInfo.InvariantCulture);
		}
		if (typeFromHandle == typeof(uint))
		{
			return (int)(uint)(object)value;
		}
		if (typeFromHandle == typeof(ulong))
		{
			return (long)(ulong)(object)value;
		}
		if (typeFromHandle == typeof(ushort))
		{
			return (short)(ushort)(object)value;
		}
		return value;
	}

	protected static T FromSerializablePhotonObject<T>(object value)
	{
		System.Type typeFromHandle = typeof(T);
		if (typeFromHandle.IsEnum)
		{
			value = System.Enum.ToObject(typeFromHandle, value);
		}
		else if (typeFromHandle == typeof(uint))
		{
			value = (uint)(int)value;
		}
		else if (typeFromHandle == typeof(ulong))
		{
			value = (ulong)(long)value;
		}
		else if (typeFromHandle == typeof(ushort))
		{
			value = (ushort)(short)value;
		}
		return (T)value;
	}

	protected static bool ObjectsAreEqual(object a, object b)
	{
		IList list = a as IList;
		IList list2 = b as IList;
		if (list != null && list2 != null)
		{
			int count = list.Count;
			int count2 = list2.Count;
			if (count != count2)
			{
				return false;
			}
			for (int i = 0; i < count; i++)
			{
				if (!ObjectsAreEqual(list[i], list2[i]))
				{
					return false;
				}
			}
			return true;
		}
		return object.Equals(a, b);
	}

	public static string ConvertPropToString(object value)
	{
		IList list = value as IList;
		if (value is string result)
		{
			return result;
		}
		if (list != null)
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.Append("[");
			for (int i = 0; i < list.Count; i++)
			{
				if (i > 0)
				{
					stringBuilder.Append(", ");
				}
				stringBuilder.Append(ConvertPropToString(list[i]));
			}
			stringBuilder.Append("]");
			return stringBuilder.ToString();
		}
		if (value != null)
		{
			return value.ToString();
		}
		return "<null>";
	}
}
