public class TextureScale
{
	public class ThreadData
	{
		public int start;

		public int end;

		public ThreadData(int s, int e)
		{
			start = s;
			end = e;
		}
	}

	private enum Method
	{
		Point,
		Bilinear,
		Average
	}

	private static Color[] texColors;

	private static Color[] newColors;

	private static int w;

	private static float ratioX;

	private static float ratioY;

	private static int w2;

	private static int finishCount;

	private static Mutex mutex;

	public static void Point(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Point);
	}

	public static void Bilinear(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Bilinear);
	}

	public static void Average(Texture2D tex, int newWidth, int newHeight)
	{
		ThreadedScale(tex, newWidth, newHeight, Method.Average);
	}

	private static void ThreadedScale(Texture2D tex, int newWidth, int newHeight, Method method)
	{
		texColors = tex.GetPixels();
		newColors = new Color[newWidth * newHeight];
		switch (method)
		{
		case Method.Point:
			ratioX = (float)tex.width / (float)newWidth;
			ratioY = (float)tex.height / (float)newHeight;
			break;
		case Method.Bilinear:
			ratioX = 1f / ((float)newWidth / (float)(tex.width - 1));
			ratioY = 1f / ((float)newHeight / (float)(tex.height - 1));
			break;
		default:
			ratioX = (float)tex.width / (float)newWidth;
			ratioY = (float)tex.height / (float)newHeight;
			break;
		}
		w = tex.width;
		w2 = newWidth;
		int num = Mathf.Min(SystemInfo.processorCount, newHeight);
		int num2 = newHeight / num;
		finishCount = 0;
		if (mutex == null)
		{
			mutex = new Mutex(initiallyOwned: false);
		}
		if (num > 1)
		{
			int num3 = 0;
			ThreadData parameter;
			for (num3 = 0; num3 < num - 1; num3++)
			{
				parameter = new ThreadData(num2 * num3, num2 * (num3 + 1));
				Thread thread = new Thread(method switch
				{
					Method.Point => PointScale, 
					Method.Bilinear => BilinearScale, 
					_ => AverageScale, 
				});
				thread.Start(parameter);
			}
			parameter = new ThreadData(num2 * num3, newHeight);
			switch (method)
			{
			case Method.Point:
				PointScale(parameter);
				break;
			case Method.Bilinear:
				BilinearScale(parameter);
				break;
			default:
				AverageScale(parameter);
				break;
			}
			while (finishCount < num)
			{
				Thread.Sleep(1);
			}
		}
		else
		{
			ThreadData obj = new ThreadData(0, newHeight);
			switch (method)
			{
			case Method.Point:
				PointScale(obj);
				break;
			case Method.Bilinear:
				BilinearScale(obj);
				break;
			default:
				AverageScale(obj);
				break;
			}
		}
		tex.Resize(newWidth, newHeight);
		tex.SetPixels(newColors);
		tex.Apply();
	}

	public static void BilinearScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int num = (int)Mathf.Floor((float)i * ratioY);
			int num2 = num * w;
			int num3 = (num + 1) * w;
			int num4 = i * w2;
			for (int j = 0; j < w2; j++)
			{
				int num5 = (int)Mathf.Floor((float)j * ratioX);
				float value = (float)j * ratioX - (float)num5;
				ref Color reference = ref newColors[num4 + j];
				reference = ColorLerpUnclamped(ColorLerpUnclamped(texColors[num2 + num5], texColors[num2 + num5 + 1], value), ColorLerpUnclamped(texColors[num3 + num5], texColors[num3 + num5 + 1], value), (float)i * ratioY - (float)num);
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	public static void PointScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int num = (int)(ratioY * (float)i) * w;
			int num2 = i * w2;
			for (int j = 0; j < w2; j++)
			{
				ref Color reference = ref newColors[num2 + j];
				reference = texColors[(int)((float)num + ratioX * (float)j)];
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	private static Color GridAverage(int x, int y, float ratioX, float ratioY)
	{
		float num = 0f;
		float num2 = 0f;
		float num3 = 0f;
		float num4 = 0f;
		int num5 = 0;
		int num6 = (int)(0f - ratioX) / 2;
		int num7 = (int)(0f - ratioY) / 2;
		int num8 = (int)ratioX / 2;
		int num9 = (int)ratioY / 2;
		for (int i = num6; i <= num8; i++)
		{
			for (int j = num7; j <= num9; j++)
			{
				int num10 = y + j + (int)(ratioX * (float)(x + i));
				if (num10 >= 0 && num10 < texColors.Length)
				{
					num += texColors[num10].r;
					num2 += texColors[num10].g;
					num3 += texColors[num10].b;
					num4 += texColors[num10].a;
					num5++;
				}
			}
		}
		num /= (float)num5;
		num2 /= (float)num5;
		num3 /= (float)num5;
		num4 /= (float)num5;
		return new Color(num, num2, num3, num4);
	}

	public static void AverageScale(object obj)
	{
		ThreadData threadData = (ThreadData)obj;
		for (int i = threadData.start; i < threadData.end; i++)
		{
			int y = (int)(ratioY * (float)i) * w;
			int num = i * w2;
			for (int j = 0; j < w2; j++)
			{
				ref Color reference = ref newColors[num + j];
				reference = GridAverage(j, y, ratioX, ratioY);
			}
		}
		mutex.WaitOne();
		finishCount++;
		mutex.ReleaseMutex();
	}

	private static Color ColorLerpUnclamped(Color c1, Color c2, float value)
	{
		return new Color(c1.r + (c2.r - c1.r) * value, c1.g + (c2.g - c1.g) * value, c1.b + (c2.b - c1.b) * value, c1.a + (c2.a - c1.a) * value);
	}
}
public class Timer
{
	public delegate void Callback();

	private struct TimerCallback
	{
		public Callback Callback;

		public float TimeRemaining;

		public float TimeElapsed;

		public bool IsRecurring;

		public float RecurringDelay;
	}

	private List<TimerCallback> timerCallbacks = new List<TimerCallback>();

	private List<int> callbackRemoveIndices = new List<int>();

	public virtual float StartTime { get; private set; }

	public virtual float EndTime { get; private set; }

	public virtual float Duration => EndTime - StartTime;

	public virtual float PausedTimeElapsed { get; private set; }

	public virtual float PausedTimeRemaining { get; private set; }

	public virtual bool IsPaused { get; private set; }

	public float TimeElapsed => (!IsPaused) ? Mathf.Clamp((float)PhotonNetwork.time - StartTime, 0f, float.MaxValue) : PausedTimeElapsed;

	public float TimeRemaining => (!IsPaused) ? Mathf.Clamp(EndTime - (float)PhotonNetwork.time, 0f, float.MaxValue) : PausedTimeRemaining;

	public bool TimerOver => TimeRemaining <= 0f;

	public void StartTimer(float maxRunningTime)
	{
		ClearCallbacks();
		float num = (float)PhotonNetwork.time;
		StartTimerInternal(num, num + maxRunningTime);
	}

	public void StartTimerWithoutMaxRunningTime()
	{
		float maxRunningTime = float.MaxValue - (float)PhotonNetwork.time;
		StartTimer(maxRunningTime);
	}

	public void Pause()
	{
		if (!IsPaused)
		{
			PauseInternal();
		}
	}

	public void Resume()
	{
		if (IsPaused)
		{
			float num = (float)PhotonNetwork.time;
			StartTimerInternal(num, num + PausedTimeRemaining);
		}
	}

	protected virtual void StartTimerInternal(float startTime, float endTime)
	{
		StartTime = startTime;
		EndTime = endTime;
		IsPaused = false;
	}

	protected virtual void PauseInternal()
	{
		PausedTimeElapsed = TimeElapsed;
		PausedTimeRemaining = TimeRemaining;
		IsPaused = true;
	}

	public void UpdateCallbacks()
	{
		callbackRemoveIndices.Clear();
		float timeElapsed = TimeElapsed;
		float num = timeElapsed + 1f;
		float timeRemaining = TimeRemaining;
		float num2 = timeRemaining + 1f;
		for (int i = 0; i < timerCallbacks.Count; i++)
		{
			if ((timeElapsed <= timerCallbacks[i].TimeElapsed && num > timerCallbacks[i].TimeElapsed) || (timeRemaining <= timerCallbacks[i].TimeRemaining && num2 > timerCallbacks[i].TimeRemaining))
			{
				timerCallbacks[i].Callback();
				if (timerCallbacks[i].IsRecurring)
				{
					TimerCallback value = timerCallbacks[i];
					value.TimeRemaining -= value.RecurringDelay;
					value.TimeElapsed += value.RecurringDelay;
					timerCallbacks[i] = value;
				}
				else
				{
					callbackRemoveIndices.Add(i);
				}
			}
		}
		for (int num3 = callbackRemoveIndices.Count - 1; num3 >= 0; num3--)
		{
			timerCallbacks.RemoveAt(callbackRemoveIndices[num3]);
		}
	}

	public void ClearCallbacks()
	{
		timerCallbacks.Clear();
	}

	public void AddTimeElapsedCallback(float deltaTime, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = 2.1474836E+09f,
			TimeElapsed = TimeElapsed + deltaTime,
			IsRecurring = false,
			RecurringDelay = 0f
		});
	}

	public void AddTimeElapsedCallback(float deltaTime, float recurringDelay, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = 2.1474836E+09f,
			TimeElapsed = TimeElapsed + deltaTime,
			IsRecurring = true,
			RecurringDelay = recurringDelay
		});
	}

	public void AddTimeRemainingCallback(float timeRemaining, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = timeRemaining,
			TimeElapsed = 2.1474836E+09f,
			IsRecurring = false,
			RecurringDelay = 0f
		});
	}

	public void AddTimeRemainingCallback(float timeRemaining, float recurringDelay, Callback callback)
	{
		timerCallbacks.Add(new TimerCallback
		{
			Callback = callback,
			TimeRemaining = timeRemaining,
			TimeElapsed = 2.1474836E+09f,
			IsRecurring = true,
			RecurringDelay = recurringDelay
		});
	}
}
public class TriggerToAnimationMapping : UnityEngine.MonoBehaviour
{
	[Serializable]
	private struct TriggerClipMapping
	{
		public string TriggerName;

		public AnimationClip Animation;
	}

	[SerializeField]
	private List<TriggerClipMapping> triggerToClipMappings = new List<TriggerClipMapping>();

	private Dictionary<int, string> animIDToName = new Dictionary<int, string>();

	private void Awake()
	{
		for (int i = 0; i < triggerToClipMappings.Count; i++)
		{
			string triggerName = triggerToClipMappings[i].TriggerName;
			AnimationClip animation = triggerToClipMappings[i].Animation;
			int key = Animator.StringToHash(triggerName);
			animIDToName[key] = animation.name;
		}
	}

	public string GetAnimationForTrigger(int animatorHash)
	{
		if (animIDToName.ContainsKey(animatorHash))
		{
			return animIDToName[animatorHash];
		}
		return null;
	}
}
