public class TutorialCameraDollyManager : UnityEngine.MonoBehaviour
{
	public enum DollyMode
	{
		Stationary,
		Linear,
		Orbit
	}

	public TutorialCamera camera;

	public DollyMode mode;

	public float dollyTime;

	private GameObject startPositionObject;

	private Transform startPosition;

	private GameObject endPositionObject;

	private Transform endPosition;

	private GameObject orbitCenterObject;

	private Transform orbitCenter;

	private bool moving;

	private bool snapping;

	private bool looping;

	private bool easing;

	private float startTime;

	private bool wasSmoothingPosition = true;

	private void Awake()
	{
		mode = DollyMode.Stationary;
		dollyTime = 5f;
		startTime = UnityEngine.Time.time;
	}

	private void Update()
	{
		if (moving)
		{
			ComputeCameraView(UnityEngine.Time.time - startTime, out var position, out var rotation);
			camera.transform.position = position;
			camera.transform.rotation = rotation;
		}
	}

	public void SetSnapping(bool doSnap)
	{
		snapping = doSnap;
		if (startPosition != null)
		{
			startPositionObject.GetComponent<DollyController>().SetSnapping(snapping);
		}
		if (endPosition != null)
		{
			endPositionObject.GetComponent<DollyController>().SetSnapping(snapping);
		}
	}

	public void SetEasing(bool doEasing)
	{
		easing = doEasing;
	}

	public void MakeVertical()
	{
		if (startPosition != null)
		{
			startPositionObject.GetComponent<DollyController>().ForceVertical();
		}
		if (endPosition != null)
		{
			endPositionObject.GetComponent<DollyController>().ForceVertical();
		}
		if (orbitCenter != null)
		{
			orbitCenterObject.GetComponent<DollyController>().ForceVertical();
		}
	}

	public void SnapDollyStartToCamera()
	{
		if (startPosition != null)
		{
			startPosition.position = base.transform.position;
			startPosition.rotation = base.transform.rotation;
		}
	}

	public void SnapDollyEndToCamera()
	{
		if (endPosition != null)
		{
			endPosition.position = base.transform.position;
			endPosition.rotation = base.transform.rotation;
		}
	}

	public void StartMovingDelayed(float seconds)
	{
		StartCoroutine(StartMovingDelayedCoRoutine(seconds));
	}

	private IEnumerator StartMovingDelayedCoRoutine(float seconds)
	{
		if (camera != null && startPosition != null)
		{
			base.transform.position = startPosition.position;
			base.transform.rotation = startPosition.rotation;
			wasSmoothingPosition = camera.SmoothPosition;
			camera.SmoothPosition = false;
			yield return new WaitForSeconds(seconds);
			startTime = UnityEngine.Time.time;
			moving = true;
		}
	}

	public void StopMoving()
	{
		moving = false;
		camera.SmoothPosition = wasSmoothingPosition;
	}

	private void ComputeCameraView(float elapsedTime, out Vector3 position, out Quaternion rotation)
	{
		position = startPosition.position;
		rotation = startPosition.rotation;
		float num = elapsedTime / dollyTime;
		switch (mode)
		{
		case DollyMode.Linear:
			if (!(endPosition != null))
			{
				break;
			}
			if (num > 1f)
			{
				if (!looping)
				{
					num = 1f;
				}
				else
				{
					int num3 = Mathf.FloorToInt(num);
					num -= (float)num3;
					if (num3 % 2 == 1)
					{
						num = 1f - num;
					}
				}
			}
			if (!easing)
			{
				position = Vector3.Lerp(startPosition.position, endPosition.position, num);
			}
			else
			{
				position = new Vector3(Mathf.SmoothStep(startPosition.position.x, endPosition.position.x, num), Mathf.SmoothStep(startPosition.position.y, endPosition.position.y, num), Mathf.SmoothStep(startPosition.position.z, endPosition.position.z, num));
			}
			rotation = Quaternion.Slerp(startPosition.rotation, endPosition.rotation, num);
			break;
		case DollyMode.Orbit:
			if (orbitCenter != null)
			{
				if (num > 1f && easing)
				{
					num = 1f;
				}
				float num2 = num;
				if (easing)
				{
					num2 = Mathf.SmoothStep(0f, 1f, num);
				}
				Quaternion quaternion = Quaternion.AngleAxis(360f * num2, Vector3.up);
				Vector3 vector = orbitCenter.InverseTransformPoint(startPosition.position);
				Quaternion quaternion2 = orbitCenter.InverseTransformRotation(startPosition.rotation);
				position = orbitCenter.TransformPoint(quaternion * vector);
				rotation = orbitCenter.TransformRotation(quaternion * quaternion2);
			}
			break;
		}
	}

	public void TearDown()
	{
		mode = DollyMode.Stationary;
		startPosition = null;
		endPosition = null;
		orbitCenter = null;
		SessionManager.DeveloperGatedActionCoroutine(delegate
		{
			if (startPositionObject != null)
			{
				PhotonNetwork.Destroy(startPositionObject);
				startPositionObject = null;
			}
			if (endPositionObject != null)
			{
				PhotonNetwork.Destroy(endPositionObject);
				endPositionObject = null;
			}
			if (orbitCenterObject != null)
			{
				PhotonNetwork.Destroy(orbitCenterObject);
				orbitCenterObject = null;
			}
		});
	}

	public void SharedSetup()
	{
		TearDown();
		SessionManager.DeveloperGatedActionCoroutine(delegate
		{
			Vector3 forward = Player.LocalPlayer.Head.transform.forward;
			forward.y = -0.5f;
			forward.z = 1f;
			Vector3 position = Player.LocalPlayer.Head.transform.position + forward;
			Quaternion rotation = Quaternion.Euler(0f, 0f - Player.LocalPlayer.Head.transform.rotation.eulerAngles.y, 0f);
			startPositionObject = PhotonNetwork.Instantiate("[DollyStart]", position, rotation, 1f, 0);
			if (startPositionObject != null)
			{
				startPositionObject.GetComponent<Tool>().GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
				startPositionObject.GetComponent<DollyController>().SetSnapping(snapping);
				startPosition = startPositionObject.transform;
			}
		});
	}

	public void SetupLinear()
	{
		SharedSetup();
		SessionManager.DeveloperGatedActionCoroutine(delegate
		{
			Vector3 forward = Player.LocalPlayer.Head.transform.forward;
			forward.y = -0.5f;
			forward.z = -1f;
			Vector3 position = Player.LocalPlayer.Head.transform.position + forward;
			Quaternion rotation = Quaternion.Euler(0f, 0f - Player.LocalPlayer.Head.transform.rotation.eulerAngles.y, 0f);
			endPositionObject = PhotonNetwork.Instantiate("[DollyEnd]", position, rotation, 1f, 0);
			if (endPositionObject != null)
			{
				endPositionObject.GetComponent<Tool>().GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
				endPositionObject.GetComponent<DollyController>().SetSnapping(snapping);
				endPosition = endPositionObject.transform;
				if (startPosition != null)
				{
					endPositionObject.GetComponent<DollyController>().SetSnapTransform(startPosition);
				}
				if (endPosition != null)
				{
					startPositionObject.GetComponent<DollyController>().SetSnapTransform(endPosition);
				}
			}
		});
		mode = DollyMode.Linear;
	}

	public void SetupOrbit()
	{
		SharedSetup();
		SessionManager.DeveloperGatedActionCoroutine(delegate
		{
			Vector3 forward = Player.LocalPlayer.Head.transform.forward;
			forward.y = -0.5f;
			forward.z = -1f;
			Vector3 position = Player.LocalPlayer.Head.transform.position + forward;
			Quaternion rotation = Quaternion.Euler(0f, 0f - Player.LocalPlayer.Head.transform.rotation.eulerAngles.y, 0f);
			orbitCenterObject = PhotonNetwork.Instantiate("[DollyOrbit]", position, rotation, 1f, 0);
			if (orbitCenterObject != null)
			{
				orbitCenterObject.GetComponent<Tool>().GravityPickupMode = Tool.GravityPickup.SNAP_POSITION_MAINTAIN_ORIENTATION;
				orbitCenter = orbitCenterObject.transform;
			}
		});
		mode = DollyMode.Orbit;
	}
}
public abstract class ValueCurve<T>
{
	[SerializeField]
	protected AnimationCurve curve;

	[SerializeField]
	protected T minValue;

	[SerializeField]
	protected T maxValue;

	[SerializeField]
	protected float duration;

	public T Value { get; private set; }

	public float Duration => duration;

	public T Evaluate(float t)
	{
		Value = Interpolate(minValue, maxValue, curve.Evaluate(t));
		return Value;
	}

	public T EvaluateNonNormalized(float t)
	{
		return Evaluate(t / Duration);
	}

	protected abstract T Interpolate(T lhs, T rhs, float t);
}
[Serializable]
public class FloatValueCurve : ValueCurve<float>
{
	protected override float Interpolate(float lhs, float rhs, float t)
	{
		return Mathf.Lerp(lhs, rhs, t);
	}
}
[Serializable]
public class Vector3ValueCurve : ValueCurve<Vector3>
{
	protected override Vector3 Interpolate(Vector3 lhs, Vector3 rhs, float t)
	{
		return Vector3.Lerp(lhs, rhs, t);
	}
}
[Serializable]
public class ColorValueCurve : ValueCurve<Color>
{
	protected override Color Interpolate(Color lhs, Color rhs, float t)
	{
		return Color.Lerp(lhs, rhs, t);
	}
}
namespace RecRoom.Core.Updates
{
	public class VisibilityGroup : UnityEngine.MonoBehaviour, ICullingGroupListener
	{
		[SerializeField]
		[FormerlySerializedAs("minCullingUpdateLod")]
		[Tooltip("Objects within this distance are never disabled, even if they are not visible")]
		private UpdateLOD minVisibilityUpdateLod = UpdateLOD.FiveMeters;

		[SerializeField]
		[Tooltip("Only update if within or equal to this UpdateLOD")]
		private UpdateLOD maxVisibilityUpdateLod = UpdateLOD.FiftyMeters;

		[SerializeField]
		private UnityEngine.Component[] trackedComponents;

		[SerializeField]
		private GameObject[] trackedObjects;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private VisibleInCamera visibleInCamera;

		private UpdateLOD _currentUpdateLod;

		private IDisposable updateToken;

		public readonly ActionEvent<bool> VisibilityChangedEvent = new ActionEvent<bool>();

		private bool wasVisible = true;

		private static ICullingGroupEx<VisibilityGroup> visibilityGroupCullingGroup;

		public UpdateLOD CurrentUpdateLod
		{
			[CompilerGenerated]
			get
			{
				return _currentUpdateLod;
			}
		}

		private void Awake()
		{
			InitializeTrackedComponents();
			visibilityGroupCullingGroup = SingletonMonoBehaviour<CullingGroupManager>.Instance.GetOrCreateCullingGroup<VisibilityGroup>(150, 0);
			visibilityGroupCullingGroup.Add(this, 1f, TransformTrackRate.Limited);
		}

		private void Start()
		{
			RefreshSchedulerUpdate();
		}

		private void OnDestroy()
		{
			if (visibilityGroupCullingGroup != null)
			{
				visibilityGroupCullingGroup.Remove(this);
			}
		}

		private void UpdateRoutine(float deltaTime)
		{
			bool flag = CheckVisibility();
			if (flag != wasVisible)
			{
				UpdateVisibility(flag);
				VisibilityChangedEvent.Invoke(flag);
				wasVisible = flag;
			}
		}

		private bool CheckVisibility()
		{
			if (CurrentUpdateLod <= minVisibilityUpdateLod)
			{
				return true;
			}
			if (CurrentUpdateLod > maxVisibilityUpdateLod)
			{
				return false;
			}
			return visibleInCamera.IsVisible;
		}

		private void UpdateVisibility(bool isVisible)
		{
			UnityEngine.Component[] array = trackedComponents;
			foreach (UnityEngine.Component component in array)
			{
				component.SetEnabled(isVisible);
			}
			GameObject[] array2 = trackedObjects;
			foreach (GameObject gameObject in array2)
			{
				gameObject.SetActive(isVisible);
			}
		}

		private void InitializeTrackedComponents()
		{
			UnityEngine.Component[] array = trackedComponents;
			foreach (UnityEngine.Component component in array)
			{
				if (component is Animator)
				{
					((Animator)component).cullingMode = AnimatorCullingMode.AlwaysAnimate;
				}
			}
		}

		private void OnDrawGizmosSelected()
		{
			if (SingletonMonoBehaviour<CameraRig>.Instance != null)
			{
				if (wasVisible)
				{
					Gizmos.color = Color.green;
				}
				else
				{
					Gizmos.color = Color.yellow;
				}
				UnityEngine.Debug.LogFormat("Distance to {0}: {1}", this, Vector3.Distance(base.transform.position, SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera.transform.position));
			}
		}

		private void RefreshSchedulerUpdate()
		{
			if (CurrentUpdateLod <= maxVisibilityUpdateLod)
			{
				if (updateToken == null)
				{
					updateToken = this.Update10hz(UpdateRoutine);
				}
			}
			else if (updateToken != null)
			{
				updateToken.Dispose();
				updateToken = null;
				if (wasVisible)
				{
					UpdateVisibility(isVisible: false);
					VisibilityChangedEvent.Invoke(t: false);
					wasVisible = false;
				}
			}
		}

		public void OnChangedDistanceBand(UpdateLOD oldDistanceBand, UpdateLOD newDistanceBand)
		{
			_currentUpdateLod = newDistanceBand;
			RefreshSchedulerUpdate();
		}
	}
}
namespace RecRoom
{
	public class VisibleInCamera : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private GameObject[] otherRendererRoots;

		[NonSerialized]
		public List<Renderer> renderers = new List<Renderer>();

		private bool isVisible;

		private int lastRecalculate = -1;

		public bool IsVisible
		{
			get
			{
				if (lastRecalculate != UnityEngine.Time.frameCount)
				{
					lastRecalculate = UnityEngine.Time.frameCount;
					isVisible = CalculateIsVisible();
				}
				return isVisible;
			}
		}

		private void Awake()
		{
			renderers.AddRange(GetComponentsInChildren<Renderer>(includeInactive: true));
			if (otherRendererRoots != null)
			{
				for (int i = 0; i < otherRendererRoots.Length; i++)
				{
					renderers.AddRange(otherRendererRoots[i].GetComponentsInChildren<Renderer>(includeInactive: true));
				}
			}
		}

		protected virtual bool CalculateIsVisible()
		{
			foreach (Renderer renderer in renderers)
			{
				if (renderer != null && renderer.isVisible)
				{
					return true;
				}
			}
			return false;
		}
	}
}
