namespace RecRoom
{
	public class SimpleSphereVolume : SimpleVolumeBase
	{
		[SerializeField]
		private Vector3 center = Vector3.zero;

		[SerializeField]
		private float radius = 0.5f;

		private float sqRadius;

		public override Vector3 WorldSpaceCenter => base.transform.TransformPoint(center);

		public float WorldSpaceRadius => base.transform.lossyScale.x * radius;

		private void Awake()
		{
			sqRadius = radius * radius;
		}

		public override bool ContainsPoint(Vector3 point)
		{
			return (base.transform.InverseTransformPoint(point) - center).sqrMagnitude <= sqRadius;
		}

		public override int OverlapTest(Collider[] results, int layerMask, QueryTriggerInteraction queryTriggers)
		{
			return Physics.OverlapSphereNonAlloc(WorldSpaceCenter, WorldSpaceRadius, results, layerMask, queryTriggers);
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.green;
			Gizmos.DrawWireSphere(WorldSpaceCenter, WorldSpaceRadius);
		}
	}
	public class SimpleVolume : SimpleVolumeBase
	{
		[SerializeField]
		private Vector3 center = Vector3.zero;

		[SerializeField]
		private Vector3 localSize = Vector3.one;

		public override Vector3 WorldSpaceCenter => base.transform.TransformPoint(center);

		public Vector3 WorldSpaceSize => Vector3.Scale(base.transform.lossyScale, localSize);

		public override bool ContainsPoint(Vector3 point)
		{
			Vector3 vector = localSize / 2f;
			Vector3 vector2 = base.transform.InverseTransformPoint(point) - center;
			return vector2.x < vector.x && vector2.x > 0f - vector.x && vector2.y < vector.y && vector2.y > 0f - vector.y && vector2.z < vector.z && vector2.z > 0f - vector.z;
		}

		public override int OverlapTest(Collider[] results, int layerMask, QueryTriggerInteraction queryTriggers)
		{
			return Physics.OverlapBoxNonAlloc(WorldSpaceCenter, WorldSpaceSize * 0.5f, results, base.transform.rotation, layerMask, queryTriggers);
		}

		private void OnDrawGizmosSelected()
		{
			Gizmos.color = Color.green;
			Gizmos.matrix = Matrix4x4.TRS(WorldSpaceCenter, base.transform.rotation, WorldSpaceSize);
			Gizmos.DrawWireCube(Vector3.zero, Vector3.one);
		}
	}
	public abstract class SimpleVolumeBase : UnityEngine.MonoBehaviour
	{
		public abstract Vector3 WorldSpaceCenter { get; }

		public abstract bool ContainsPoint(Vector3 point);

		public abstract int OverlapTest(Collider[] results, int layerMask, QueryTriggerInteraction queryTriggers);

		public bool ContainsPhotonPlayer(PhotonPlayer photonPlayer)
		{
			Player player = photonPlayer.ToPlayer();
			return ContainsPlayer(player);
		}

		public bool ContainsPlayer(Player player)
		{
			if (player == null)
			{
				return false;
			}
			return ContainsPoint(player.CurrentFloorPosition);
		}
	}
	public static class VolumeHelpers
	{
		public static bool AllPlayersOverlapping(IEnumerable<PhotonPlayer> photonPlayers, SimpleVolumeBase volume)
		{
			if (photonPlayers == null)
			{
				return true;
			}
			foreach (PhotonPlayer photonPlayer in photonPlayers)
			{
				if (!volume.ContainsPhotonPlayer(photonPlayer))
				{
					return false;
				}
			}
			return true;
		}

		public static bool AllPlayersOverlapping(IEnumerable<PhotonPlayer> photonPlayers, SimpleVolumeBase[] volumes)
		{
			if (photonPlayers == null)
			{
				return true;
			}
			foreach (PhotonPlayer photonPlayer in photonPlayers)
			{
				if (!PlayerInsideVolumes(photonPlayer, volumes))
				{
					return false;
				}
			}
			return true;
		}

		public static int GetOverlappingPlayerCount(IEnumerable<PhotonPlayer> photonPlayers, SimpleVolumeBase volume)
		{
			if (photonPlayers == null)
			{
				return 0;
			}
			int num = 0;
			foreach (PhotonPlayer photonPlayer in photonPlayers)
			{
				if (volume.ContainsPhotonPlayer(photonPlayer))
				{
					num++;
				}
			}
			return num;
		}

		public static int GetOverlappingPlayerCount(IEnumerable<PhotonPlayer> photonPlayers, SimpleVolumeBase[] volumes)
		{
			if (photonPlayers == null)
			{
				return 0;
			}
			int num = 0;
			foreach (PhotonPlayer photonPlayer in photonPlayers)
			{
				if (PlayerInsideVolumes(photonPlayer, volumes))
				{
					num++;
				}
			}
			return num;
		}

		private static bool PlayerInsideVolumes(PhotonPlayer photonPlayer, SimpleVolumeBase[] volumes)
		{
			for (int i = 0; i < volumes.Length; i++)
			{
				if (volumes[i].ContainsPhotonPlayer(photonPlayer))
				{
					return true;
				}
			}
			return false;
		}
	}
}
