namespace RecRoom.Core.Vehicles
{
	[RequireComponent(typeof(RigidbodyEx))]
	public abstract class BaseVehicle : Photon.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		protected RigidbodyEx rigidbodyEx;

		[Header("Screen Controls")]
		[SerializeField]
		private ScreenVehicleController screenController;

		protected float lastRiderEnterTime = float.MinValue;

		protected float lastRiderExitTime = float.MinValue;

		private PhotonPlayer _cachedRider;

		private SynchronizedField<int> _riderId;

		public Action<BaseVehicle, PhotonPlayer> PlayerBoardEvent;

		public Action<BaseVehicle, PhotonPlayer> PlayerExitEvent;

		private const float VIGNETTE_FADE_IN_TIME = 0f;

		private const float VIGNETTE_FADE_OUT_TIME = 0.2f;

		public RigidbodyEx RigidbodyEx => rigidbodyEx;

		public PhotonPlayer Rider
		{
			get
			{
				return _cachedRider;
			}
			private set
			{
				_riderId.Set(value?.ID ?? (-1));
			}
		}

		protected override void Awake()
		{
			base.Awake();
			_riderId = new SynchronizedField<int>(this, "VEHICLE.RID", -1, SetterPermissionMode.AUTHORITY, OnRiderChange);
			rigidbodyEx.AddKinematic(this);
			rigidbodyEx.EnableProxyMovement(this);
			rigidbodyEx.AddUpdateLodOverride(this, UpdateLOD.TwoPointFiveMeters);
		}

		protected virtual void Start()
		{
			OnRiderChange();
			SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehiclesChanged += OnTVModeVehiclesChanged;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehiclesChanged -= OnTVModeVehiclesChanged;
			}
			if (rigidbodyEx != null)
			{
				rigidbodyEx.RemoveUpdateLodOverride(this);
			}
			if (Rider != null && Rider.IsLocal)
			{
				if (SingletonMonoBehaviour<CameraRig>.Instance != null)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopVehicleVignette(0f);
				}
				if (SingletonMonoBehaviour<CameraRig>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehicles)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.IsTVMode = false;
				}
			}
		}

		public void LocalPlayerBoard()
		{
			if (Player.LocalPlayerExists && Rider == null && !Player.LocalPlayer.IsInVehicle)
			{
				if (!base.hasAuthority)
				{
					base.photonView.TransferOwnership(PhotonNetwork.player);
				}
				Rider = PhotonNetwork.player;
			}
		}

		public ScreenVehicleController GetScreenController()
		{
			return screenController;
		}

		protected abstract void GetLocalRiderLocalPositionRotation(out Vector3 position, out Quaternion rotation);

		protected virtual void OnRiderChange()
		{
			PhotonPlayer photonPlayer = PhotonPlayer.Find(_riderId.Get());
			if (_cachedRider != photonPlayer)
			{
				if (_cachedRider != null)
				{
					OnRiderExit(_cachedRider);
				}
				_cachedRider = photonPlayer;
				if (_cachedRider != null)
				{
					OnRiderBoard(_cachedRider);
				}
			}
		}

		protected virtual void OnRiderBoard(PhotonPlayer newRider)
		{
			lastRiderEnterTime = UnityEngine.Time.time;
			if (newRider.IsLocal)
			{
				Player localPlayer = Player.LocalPlayer;
				GetLocalRiderLocalPositionRotation(out var position, out var rotation);
				localPlayer.TrackingSpace.RigidbodyEx.parent = rigidbodyEx;
				localPlayer.TrackingSpace.RigidbodyEx.targetLocalPosition = position;
				localPlayer.TrackingSpace.RigidbodyEx.targetLocalRotation = rotation;
				localPlayer.BoardedVehicle = this;
				localPlayer.EnableOutOfBoundsCheck(enable: false);
				localPlayer.PlayerWalking.AddWalkDisabled(this);
				localPlayer.PlayerWalking.AddJumpEnabled(enabled: false, this, int.MaxValue);
				localPlayer.PlayerLocomotion.PauseGravity(this);
				localPlayer.PlayerLocomotion.TeleportEvent += OnLocalRiderTeleport;
				Player.LocalPlayerSpawnEvent += new Action(OnLocalPlayerRespawn);
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StartVehicleVignette(0f);
				if (SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehicles)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.IsTVMode = true;
				}
			}
			if (PlayerBoardEvent != null)
			{
				PlayerBoardEvent(this, newRider);
			}
		}

		protected virtual void OnRiderExit(PhotonPlayer exitingRider)
		{
			if (exitingRider.IsLocal)
			{
				Player localPlayer = Player.LocalPlayer;
				localPlayer.TrackingSpace.RigidbodyEx.parent = null;
				localPlayer.BoardedVehicle = null;
				localPlayer.EnableOutOfBoundsCheck(enable: true);
				localPlayer.PlayerWalking.RemoveWalkDisabled(this);
				localPlayer.PlayerWalking.RemoveJumpEnabled(this);
				localPlayer.PlayerLocomotion.ResumeGravity(this);
				localPlayer.PlayerLocomotion.TeleportEvent -= OnLocalRiderTeleport;
				Player.LocalPlayerSpawnEvent -= new Action(OnLocalPlayerRespawn);
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.StopVehicleVignette(0.2f);
				if (SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehicles)
				{
					SingletonMonoBehaviour<CameraRig>.Instance.IsTVMode = false;
				}
			}
		}

		private void OnTVModeVehiclesChanged()
		{
			if (Rider != null && Rider.IsLocal)
			{
				SingletonMonoBehaviour<CameraRig>.Instance.IsTVMode = SingletonMonoBehaviour<SettingsManager>.Instance.TVModeVehicles;
			}
		}

		private void OnLocalRiderTeleport(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
		{
			if (Rider != null && Rider.IsLocal)
			{
				Rider = null;
			}
		}

		private void OnLocalPlayerRespawn()
		{
			if (Rider != null && Rider.IsLocal)
			{
				Rider = null;
			}
		}
	}
	[CreateAssetMenu(menuName = "RecRoom/Screen Mode/Screen Vehicle Controllers/Glider Vehicle Screen Controller", fileName = "GliderVehicleScreenController")]
	public class GliderScreenVehicleController : ScreenVehicleController
	{
		[Header("Player Animation")]
		[SerializeField]
		private PlayerAnimation playerAnimation;

		[Header("Camera Settings")]
		[SerializeField]
		private ScreenPlayerCameraSettings cameraSettings;

		[SerializeField]
		private float cameraSettingsFadeDuration = 0.5f;

		[Header("Vehicle Controls")]
		[SerializeField]
		private float steeringInputAccelerateTime = 0.5f;

		[SerializeField]
		private float steeringInputDecelerateTime = 0.15f;

		[SerializeField]
		private float throttleInputAccelerateTime = 0.5f;

		[SerializeField]
		private float throttleInputDecelerateTime = 0.15f;

		private float throttleVelocity;

		private float steeringVelocity;

		private float throttle;

		private float steering;

		public override void OnEnter(ScreenPlayerController playerController, Player player, BaseVehicle vehicle, ScreenInputHandler input)
		{
			throttle = 0f;
			steering = 0f;
			throttleVelocity = 0f;
			steeringVelocity = 0f;
			BattleRoyaleGlider component = vehicle.GetComponent<BattleRoyaleGlider>();
			component.InDirectSteerMode = true;
			playerController.AddCameraSettings(cameraSettings, cameraSettingsFadeDuration, this, 200);
			playerController.PlayLoopingAnimation(playerAnimation);
		}

		public override void OnUpdate(ScreenPlayerController playerController, Player player, BaseVehicle vehicle, ScreenInputHandler input)
		{
			float y = input.WalkAxis.y;
			float smoothTime = ((!(Mathf.Abs(y) >= Mathf.Abs(throttle))) ? throttleInputDecelerateTime : throttleInputAccelerateTime);
			throttle = Mathf.SmoothDamp(throttle, y, ref throttleVelocity, smoothTime);
			float num = -1f * input.WalkAxis.x;
			float smoothTime2 = ((!(Mathf.Abs(num) >= Mathf.Abs(steering))) ? steeringInputDecelerateTime : steeringInputAccelerateTime);
			steering = Mathf.SmoothDamp(steering, num, ref steeringVelocity, smoothTime2);
			BattleRoyaleGlider component = vehicle.GetComponent<BattleRoyaleGlider>();
			component.SteerDirectly(throttle, steering);
			player.TrackingSpace.RigidbodyEx.targetRotation = component.RigidbodyEx.targetRotation;
		}

		public override void OnExit(ScreenPlayerController playerController, Player player, BaseVehicle vehicle, ScreenInputHandler input)
		{
			if (vehicle != null)
			{
				BattleRoyaleGlider component = vehicle.GetComponent<BattleRoyaleGlider>();
				component.InDirectSteerMode = false;
			}
			playerController.RemoveCameraSettings(this);
		}
	}
}
namespace RecRoom
{
	public class AnimateInOut : UnityEngine.MonoBehaviour
	{
		private static readonly List<Renderer> INSTANTANEOUS_RENDERERS = new List<Renderer>();

		[Header("Prefab")]
		[SerializeField]
		private PooledParticle effectPrefab;

		[Header("Bounds")]
		[SerializeField]
		[ConditionalField("HasBoundingVolume", false)]
		private Transform boundsRendererRoot;

		[SerializeField]
		[ConditionalField("HasBoundingVolume", false)]
		private List<Renderer> ignoredRenderers = new List<Renderer>();

		[SerializeField]
		[ConditionalField("HasBoundsRendererRoot", false)]
		private SimpleVolume boundingVolume;

		[Header("Timing")]
		[SerializeField]
		private float animInStartOffset = 0.2f;

		[SerializeField]
		private float animOutStartOffset = 0.2f;

		[Header("Effect Support")]
		[FormerlySerializedAs("supportsAnimateIn")]
		public bool SupportsAnimateIn = true;

		[FormerlySerializedAs("supportsAnimateOut")]
		public bool SupportsAnimateOut = true;

		public bool SuppressAnimation;

		private PooledParticle latestEffect;

		private bool updatePositionWhilePlaying = true;

		private List<Renderer> renderers;

		private bool started;

		private bool HasBoundsRendererRoot => boundsRendererRoot != null;

		private bool HasBoundingVolume => boundingVolume != null;

		private void Start()
		{
			started = true;
			PlayAnimateIn();
		}

		private void OnEnable()
		{
			PlayAnimateIn();
		}

		private void PlayAnimateIn()
		{
			if (started && !SuppressAnimation && SupportsAnimateIn)
			{
				PlayEffect(animIn: true);
			}
		}

		private void OnDisable()
		{
			if (!SuppressAnimation && SupportsAnimateOut && SessionManager.IsCurrentSceneActive)
			{
				PlayEffect(animIn: false);
			}
		}

		public void PlayEffect(bool animIn, Vector3? position = null, Quaternion? rotation = null, bool dontSuppress = false)
		{
			if (SingletonMonoBehaviour<AnimateInOutManager>.Instance != null && (dontSuppress || !SingletonMonoBehaviour<AnimateInOutManager>.Instance.SuppressAnimations))
			{
				if (effectPrefab == null)
				{
					effectPrefab = SingletonMonoBehaviour<AnimateInOutManager>.Instance.DefaultEffectPrefab;
				}
				latestEffect = ObjectPool.Instance.Acquire(effectPrefab);
				latestEffect.transform.parent = SingletonMonoBehaviour<AnimateInOutManager>.Instance.transform;
				UpdateEffectPosition((!position.HasValue || !position.HasValue) ? base.transform.position : position.Value, (!rotation.HasValue || !rotation.HasValue) ? base.transform.rotation : rotation.Value);
				latestEffect.PrimaryParticleSystem.Simulate((!animIn) ? animOutStartOffset : animInStartOffset);
				latestEffect.Play();
				updatePositionWhilePlaying = animIn && !position.HasValue;
				if (base.gameObject.activeInHierarchy)
				{
					StartCoroutine(RunAnimateInOut(animIn));
				}
			}
		}

		private IEnumerator RunAnimateInOut(bool animIn)
		{
			while (latestEffect != null)
			{
				if (latestEffect.PrimaryParticleSystem.isPlaying && updatePositionWhilePlaying)
				{
					UpdateEffectPosition(base.transform.position, base.transform.rotation);
				}
				if (!latestEffect.gameObject.activeSelf)
				{
					latestEffect = null;
				}
				yield return null;
			}
		}

		public void StopEffect()
		{
			if (latestEffect != null)
			{
				latestEffect.Stop();
				latestEffect = null;
			}
		}

		private void UpdateEffectPosition(Vector3 position, Quaternion rotation)
		{
			if (GetEffectBounds(out var bounds))
			{
				latestEffect.transform.position = bounds.center - base.transform.position + position;
				latestEffect.transform.rotation = rotation;
				ParticleSystem.ShapeModule shape = latestEffect.PrimaryParticleSystem.shape;
				shape.scale = bounds.size * 1.3f;
				float num = Mathf.Max(bounds.size.x, bounds.size.y, bounds.size.z);
				ParticleSystem.MainModule main = latestEffect.PrimaryParticleSystem.main;
				main.startSize = num * 0.3f;
			}
			else
			{
				latestEffect.transform.position = position;
			}
		}

		private bool GetEffectBounds(out Bounds bounds)
		{
			if (boundingVolume != null)
			{
				bounds = new Bounds(boundingVolume.WorldSpaceCenter, boundingVolume.WorldSpaceSize);
				return true;
			}
			Transform transform = ((!HasBoundsRendererRoot) ? base.transform : boundsRendererRoot);
			if (renderers == null)
			{
				renderers = new List<Renderer>();
				GatherRenderersRecursive(transform, renderers);
			}
			return UnityExtensions.GetCombinedRendererBounds(renderers, out bounds);
		}

		private void GatherRenderersRecursive(Transform transform, List<Renderer> renderers)
		{
			int count = renderers.Count;
			if (!transform.GetComponent<ImpactDecal>())
			{
				INSTANTANEOUS_RENDERERS.Clear();
				transform.GetComponents(INSTANTANEOUS_RENDERERS);
				renderers.AddRange(INSTANTANEOUS_RENDERERS.Where((Renderer r) => !ignoredRenderers.Contains(r)));
			}
			foreach (Transform item in transform)
			{
				if (!item.GetComponent<AnimateInOut>())
				{
					GatherRenderersRecursive(item, renderers);
				}
			}
		}
	}
}
public class AnimateInOutManager : SingletonMonoBehaviour<AnimateInOutManager>
{
	private const float START_OFFSET = 0.2f;

	public PooledParticle DefaultEffectPrefab;

	[NonSerialized]
	public bool SuppressAnimations = true;

	public static void PlayOneOff(Bounds bounds)
	{
		if (!SingletonMonoBehaviour<AnimateInOutManager>.Instance.SuppressAnimations)
		{
			PooledParticle pooledParticle = ObjectPool.Instance.Acquire(SingletonMonoBehaviour<AnimateInOutManager>.Instance.DefaultEffectPrefab);
			if (pooledParticle != null)
			{
				pooledParticle.transform.SetParent(SingletonMonoBehaviour<AnimateInOutManager>.Instance.transform);
				pooledParticle.transform.position = bounds.center;
				ParticleSystem.ShapeModule shape = pooledParticle.PrimaryParticleSystem.shape;
				shape.scale = bounds.size * 1.3f;
				float num = Mathf.Max(bounds.size.x, bounds.size.y, bounds.size.z);
				ParticleSystem.MainModule main = pooledParticle.PrimaryParticleSystem.main;
				main.startSize = num * 0.3f;
				pooledParticle.PrimaryParticleSystem.Simulate(0.2f);
				pooledParticle.Play();
			}
		}
	}

	private void OnApplicationQuit()
	{
		SuppressAnimations = true;
	}
}
