[ExecuteInEditMode]
public class BobbingMotion : UnityEngine.MonoBehaviour
{
	public enum Axis
	{
		X,
		Y,
		Z
	}

	[SerializeField]
	private Axis bobAxis = Axis.Y;

	[SerializeField]
	private float scaleBobAmount;

	[SerializeField]
	private float scaleBobSpeed;

	[SerializeField]
	private bool inWorldSpace;

	private float bobHeight;

	private Vector3 BobAxis
	{
		get
		{
			Vector3 zero = Vector3.zero;
			zero = bobAxis switch
			{
				Axis.X => Vector3.right, 
				Axis.Z => Vector3.forward, 
				_ => Vector3.up, 
			};
			if (inWorldSpace && base.transform.parent != null)
			{
				zero = base.transform.parent.InverseTransformDirection(zero);
			}
			return zero;
		}
	}

	private void Awake()
	{
		scaleBobSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void Update()
	{
		base.transform.localPosition = BobAxis * Mathf.Sin(UnityEngine.Time.time * scaleBobSpeed) * scaleBobAmount;
	}
}
public class CameraFade : SingletonMonoBehaviour<CameraFade>
{
	[SerializeField]
	private float fadeOutDelay = 0.4f;

	[SerializeField]
	private float fadeInDelay = 0.4f;

	[SerializeField]
	private float fadeOutDuration = 0.25f;

	[SerializeField]
	private float fadeInDuration = 0.25f;

	[SerializeField]
	private AnimateInOut effect;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip RezOutAudio;

	[SerializeField]
	private RecRoomAudioClip RezInAudio;

	private Coroutine fadeCoroutine;

	private bool compositorSuspended;

	[NonSerialized]
	public bool SuppressAnimateInOutEffects;

	public float TotalFadeInDuration => fadeInDelay + fadeInDuration;

	public float TotalFadeOutDuration => fadeOutDelay + fadeOutDuration;

	public bool IsFading => fadeCoroutine != null;

	protected override void Awake()
	{
		base.Awake();
	}

	public Coroutine Fade(bool fadeIn, bool prepForLevelSwitch = false, bool suppressEffect = false, float overrideDuration = 0f)
	{
		if (fadeCoroutine != null)
		{
			StopCoroutine(fadeCoroutine);
		}
		fadeCoroutine = StartCoroutine(FadeCoroutine(fadeIn, prepForLevelSwitch, suppressEffect, overrideDuration));
		return fadeCoroutine;
	}

	private IEnumerator FadeCoroutine(bool fadeIn, bool prepForLevelSwitch, bool suppressEffect, float overrideDuration)
	{
		if (!suppressEffect && !SuppressAnimateInOutEffects)
		{
			effect.StopEffect();
			effect.PlayEffect(fadeIn, null, null, dontSuppress: true);
			if (RezInAudio.audioClip != null && RezOutAudio.audioClip != null)
			{
				AudioManager.Play2DSFX((!fadeIn) ? RezOutAudio : RezInAudio);
			}
		}
		if (fadeIn)
		{
			yield return new WaitForSeconds(fadeInDelay);
			if ((bool)SingletonMonoBehaviour<CameraRig>.Instance)
			{
				bool fadeDone = false;
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.FadeIn((overrideDuration != 0f) ? overrideDuration : fadeInDuration).Finally(delegate
				{
					fadeDone = true;
				});
				while (!fadeDone)
				{
					yield return null;
				}
			}
			SingletonMonoBehaviour<AnimateInOutManager>.Instance.SuppressAnimations = false;
		}
		else
		{
			SingletonMonoBehaviour<AnimateInOutManager>.Instance.SuppressAnimations = true;
			if (!suppressEffect && !SuppressAnimateInOutEffects)
			{
				yield return new WaitForSeconds(fadeOutDelay);
			}
			if ((bool)SingletonMonoBehaviour<CameraRig>.Instance)
			{
				bool fadeDone2 = false;
				SingletonMonoBehaviour<CameraRig>.Instance.ImageEffects.FadeOut((overrideDuration != 0f) ? overrideDuration : fadeOutDuration).Finally(delegate
				{
					fadeDone2 = true;
				});
				while (!fadeDone2)
				{
					yield return null;
				}
			}
		}
		fadeCoroutine = null;
	}
}
public class CollisionParticles : UnityEngine.MonoBehaviour
{
	[Serializable]
	public class ParticlesToLayer
	{
		public string Name;

		public ParticleSystem ParticleSystemPrefab;

		public LayerMask Layers;

		public string Tag = string.Empty;

		[Tooltip("Per particle cooldown to limit the number of consequtive plays. Set it to the particle duration")]
		public float InstanceLimitDuration;

		private ParticleSystem particleSystemInstance;

		public float LastInstanceTime { get; set; }

		public ParticleSystem GetParticleSystem()
		{
			if (particleSystemInstance == null)
			{
				particleSystemInstance = UnityEngine.Object.Instantiate(ParticleSystemPrefab);
			}
			return particleSystemInstance;
		}

		public bool CanPlay(GameObject go)
		{
			int num = 1 << go.layer;
			if (UnityEngine.Time.time - LastInstanceTime > InstanceLimitDuration && (Layers.value & num) != 0 && (string.IsNullOrEmpty(Tag) || go.CompareTag(Tag)))
			{
				LastInstanceTime = UnityEngine.Time.time;
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	public ParticlesToLayer[] particleMappings;

	[SerializeField]
	[Tooltip("MeleeWeaponColliders that can trigger the collision audio in addition to normal physics collisions.")]
	private MeleeWeaponCollider[] meleeWeaponColliders;

	private Tool thisTool;

	private void Awake()
	{
		thisTool = GetComponent<Tool>();
	}

	private void OnDestroy()
	{
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
			if (particleSystem != null)
			{
				particleSystem.Stop();
				UnityEngine.Object.Destroy(particleSystem.gameObject);
			}
		}
	}

	private void OnEnable()
	{
		MeleeWeaponCollider[] array = meleeWeaponColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.AnyImpactEvent += OnMeleeColliderImpact;
		}
	}

	private void OnDisable()
	{
		MeleeWeaponCollider[] array = meleeWeaponColliders;
		foreach (MeleeWeaponCollider meleeWeaponCollider in array)
		{
			meleeWeaponCollider.AnyImpactEvent -= OnMeleeColliderImpact;
		}
	}

	private void OnMeleeColliderImpact(MeleeWeaponCollider thisCollider, WeaponImpact impact)
	{
		ProcessCollision(impact.GameObject);
	}

	private void OnCollisionEnter(Collision collision)
	{
		if (!(thisTool != null) || !thisTool.IsHeld)
		{
			ProcessCollision(collision.collider.gameObject);
		}
	}

	private void ProcessCollision(GameObject colliderObject)
	{
		ParticlesToLayer[] array = particleMappings;
		foreach (ParticlesToLayer particlesToLayer in array)
		{
			if (particlesToLayer.CanPlay(colliderObject))
			{
				ParticleSystem particleSystem = particlesToLayer.GetParticleSystem();
				if (particleSystem != null)
				{
					particleSystem.Stop();
					particleSystem.transform.position = base.transform.position;
					particleSystem.Play();
				}
				break;
			}
		}
	}
}
namespace RecRoom.Core.Rendering
{
	public abstract class CommandBufferRenderer<T> : UnityEngine.MonoBehaviour
	{
		protected struct RenderInstance
		{
			public Renderer Renderer;

			public Material Material;

			public int SubMeshCount;

			public bool DoNotRender;

			public bool RenderWhenDisabled;

			public T RenderData;
		}

		protected class RenderInstanceCollection
		{
			private List<RenderInstance> instances;

			private HashSet<Renderer> renderers;

			public int Capacity => instances.Capacity;

			public int Count => instances.Count;

			public RenderInstance this[int key] => instances[key];

			public RenderInstanceCollection(int capacity)
			{
				instances = new List<RenderInstance>(capacity);
				renderers = new HashSet<Renderer>();
			}

			public bool TryAdd(Renderer renderer, Material material, int subMeshCount, T data, bool renderWhenDisabled = false, bool doNotRender = false)
			{
				if (renderer != null && instances.Count <= instances.Capacity && !renderers.Contains(renderer))
				{
					instances.Add(new RenderInstance
					{
						Renderer = renderer,
						Material = material,
						SubMeshCount = subMeshCount,
						RenderWhenDisabled = renderWhenDisabled,
						DoNotRender = doNotRender,
						RenderData = data
					});
					renderers.Add(renderer);
					return true;
				}
				return false;
			}

			public void Clear()
			{
				instances.Clear();
				renderers.Clear();
			}
		}

		private class CachedMaterialPropertyBlock
		{
			private Renderer cachedRenderer;

			private MaterialPropertyBlock materialProperties;

			public bool IsCached { get; private set; }

			public MaterialPropertyBlock CachedMaterialProperties
			{
				get
				{
					if (IsCached)
					{
						return materialProperties;
					}
					return null;
				}
			}

			public CachedMaterialPropertyBlock()
			{
				cachedRenderer = null;
				materialProperties = new MaterialPropertyBlock();
			}

			public void CacheProperties(Renderer renderer)
			{
				if (IsCached)
				{
					UnityEngine.Debug.LogErrorFormat("Attempted to cache material properties from renderer {0} on an already-cached property block", renderer.gameObject.name);
				}
				else
				{
					renderer.GetPropertyBlock(materialProperties);
					cachedRenderer = renderer;
					IsCached = true;
				}
			}

			public void RestoreProperties()
			{
				if (IsCached)
				{
					cachedRenderer.SetPropertyBlock(materialProperties);
					materialProperties.Clear();
					cachedRenderer = null;
					IsCached = false;
				}
			}
		}

		private static MaterialPropertyBlock INSTANTANEOUS_MATERIAL_PROPERTIES;

		private static CachedMaterialPropertyBlock[] cachedMaterialProperties;

		private Camera camera;

		protected CommandBuffer commandBuffer;

		protected abstract RenderInstanceCollection InstancesToRender { get; }

		protected abstract string BufferName { get; }

		protected virtual CameraEvent RenderEvent => CameraEvent.AfterForwardOpaque;

		protected virtual bool UseLightProbes => true;

		protected virtual bool OverrideMaterialProperties => true;

		protected virtual void Awake()
		{
			if (INSTANTANEOUS_MATERIAL_PROPERTIES == null)
			{
				INSTANTANEOUS_MATERIAL_PROPERTIES = new MaterialPropertyBlock();
			}
			if (cachedMaterialProperties == null && OverrideMaterialProperties)
			{
				if (InstancesToRender.Capacity == 0)
				{
					UnityEngine.Debug.LogWarningFormat("{0}: CommandBufferRenderers should allocate their instance collections before Awake().");
				}
				cachedMaterialProperties = new CachedMaterialPropertyBlock[InstancesToRender.Capacity];
				for (int i = 0; i < cachedMaterialProperties.Length; i++)
				{
					cachedMaterialProperties[i] = new CachedMaterialPropertyBlock();
				}
			}
			commandBuffer = new CommandBuffer();
			commandBuffer.name = BufferName;
			camera = GetComponent<Camera>();
			camera.AddCommandBuffer(RenderEvent, commandBuffer);
			StartCoroutine(ClearInstancesToRenderCoroutine());
		}

		protected virtual void OnPreRender()
		{
			if (commandBuffer == null)
			{
				return;
			}
			commandBuffer.Clear();
			for (int i = 0; i < InstancesToRender.Count; i++)
			{
				RenderInstance instance = InstancesToRender[i];
				Renderer renderer = instance.Renderer;
				if (instance.DoNotRender || !(renderer != null) || !UnityExtensions.IsInMask(renderer.gameObject.layer, camera.cullingMask) || ((!renderer.enabled || !renderer.isVisible) && !instance.RenderWhenDisabled) || !renderer.gameObject.activeInHierarchy)
				{
					continue;
				}
				if (OverrideMaterialProperties)
				{
					if (i >= cachedMaterialProperties.Length)
					{
						UnityEngine.Debug.LogWarningFormat("{0}: CommandBuffer has exceeded the maximum renderers for a frame. Unable to modify material properties.", base.gameObject.name);
					}
					else
					{
						cachedMaterialProperties[i].CacheProperties(renderer);
						renderer.GetPropertyBlock(INSTANTANEOUS_MATERIAL_PROPERTIES);
						SetMaterialProperties(instance, ref INSTANTANEOUS_MATERIAL_PROPERTIES);
						renderer.SetPropertyBlock(INSTANTANEOUS_MATERIAL_PROPERTIES);
					}
				}
				for (int j = 0; j < instance.SubMeshCount; j++)
				{
					commandBuffer.DrawRenderer(instance.Renderer, instance.Material, j, -1);
				}
			}
		}

		protected virtual void OnPostRender()
		{
			if (!OverrideMaterialProperties)
			{
				return;
			}
			for (int i = 0; i < InstancesToRender.Count && i < cachedMaterialProperties.Length; i++)
			{
				if (cachedMaterialProperties[i].IsCached)
				{
					cachedMaterialProperties[i].RestoreProperties();
				}
			}
		}

		protected virtual void SetMaterialProperties(RenderInstance instance, ref MaterialPropertyBlock propertyBlock)
		{
			if (instance.Renderer.lightProbeUsage != LightProbeUsage.Off && UseLightProbes)
			{
				MaterialLightingUtil.SetLightProbeMaterialProperties(instance.Renderer, ref propertyBlock);
			}
		}

		private IEnumerator ClearInstancesToRenderCoroutine()
		{
			WaitForEndOfFrame waitForEndOfFrame = new WaitForEndOfFrame();
			while (true)
			{
				yield return waitForEndOfFrame;
				InstancesToRender.Clear();
			}
		}
	}
}
public abstract class CustomTrail : UnityEngine.MonoBehaviour
{
	protected const int MAX_POINTS = 128;

	[Header("Visuals")]
	[SerializeField]
	protected Material[] materials;

	[SerializeField]
	protected bool castShadows;

	[SerializeField]
	protected bool receiveShadows;

	[Header("Layout")]
	[SerializeField]
	protected float lifetime = 5f;

	[SerializeField]
	protected Vector2 alphas = new Vector2(0f, 1f);

	[SerializeField]
	protected Vector2 widths = new Vector2(0.2f, 0.8f);

	[SerializeField]
	protected float minSpacing = 0.01f;

	[Header("End Caps")]
	[SerializeField]
	protected bool displayStartCap;

	[SerializeField]
	protected Renderer startCap;

	[SerializeField]
	protected bool displayEndCap;

	[SerializeField]
	protected Renderer endCap;

	protected static int ParticleMaterialColorId = -1;

	protected float fadeAlpha = 1f;

	protected float widthScale = 1f;

	protected float minSpacingSqr;

	protected bool lineDirty = true;

	protected RecRoom.CircularBuffer<float> pointTimeStamps = new RecRoom.CircularBuffer<float>(128);

	protected RecRoom.CircularBuffer<Vector3> points = new RecRoom.CircularBuffer<Vector3>(128);

	protected RecRoom.CircularBuffer<Vector3> tangents = new RecRoom.CircularBuffer<Vector3>(128);

	protected RecRoom.CircularBuffer<float> segmentLengths;

	public abstract Color Color { get; set; }

	public abstract Vector2 Widths { get; set; }

	public float Lifetime { get; set; }

	public bool Running => points.Count > 0;

	public float Length
	{
		get
		{
			if (TrackLength)
			{
				float num = 0f;
				{
					foreach (float segmentLength in segmentLengths)
					{
						num += segmentLength;
					}
					return num;
				}
			}
			throw new InvalidOperationException($"Custom trail type {GetType()} does not support tracking trail length.");
		}
	}

	protected virtual bool TrackLength => false;

	protected virtual bool RenderersEnabled
	{
		set
		{
			if (startCap != null)
			{
				startCap.enabled = value;
			}
			if (endCap != null)
			{
				endCap.enabled = value;
			}
		}
	}

	protected abstract void ApplyPoints();

	public virtual void Clear()
	{
		pointTimeStamps.Clear();
		points.Clear();
		tangents.Clear();
		if (segmentLengths != null)
		{
			segmentLengths.Clear();
		}
		lineDirty = true;
		UpdateLine();
	}

	protected virtual void Awake()
	{
		Lifetime = lifetime;
		if (TrackLength)
		{
			segmentLengths = new RecRoom.CircularBuffer<float>(128);
		}
		ParticleMaterialColorId = Shader.PropertyToID("_TintColor");
		minSpacingSqr = minSpacing * minSpacing;
		if (materials == null || materials.Length == 0)
		{
			UnityEngine.Debug.LogError("Trail on " + base.gameObject.name + " is missing materials.");
			return;
		}
		Widths = widths;
		Color = Color.white;
	}

	protected virtual void OnEnable()
	{
		RenderersEnabled = true;
		Clear();
	}

	protected virtual void OnDisable()
	{
		RenderersEnabled = false;
		Clear();
	}

	protected virtual void Update()
	{
		UpdateLine();
	}

	protected void UpdateLine()
	{
		float num = UnityEngine.Time.time - Lifetime;
		int i;
		for (i = 0; i < pointTimeStamps.Count && pointTimeStamps[i] <= num; i++)
		{
		}
		if (i > 0)
		{
			pointTimeStamps.RemoveFromFront(i);
			points.RemoveFromFront(i);
			tangents.RemoveFromFront(i);
			if (TrackLength)
			{
				segmentLengths.RemoveFromFront(i);
				if (segmentLengths.Count > 0)
				{
					segmentLengths[0] = 0f;
				}
			}
			lineDirty = true;
		}
		if (lineDirty)
		{
			ApplyPoints();
			lineDirty = false;
		}
		if (points.Count < 2)
		{
			RenderersEnabled = false;
		}
		else if (points.Count > 1)
		{
			if (displayStartCap && startCap != null)
			{
				startCap.transform.position = points[0];
				Vector3 normalized = (points[0] - points[1]).normalized;
				startCap.transform.rotation = Quaternion.LookRotation(normalized);
			}
			if (displayEndCap && endCap != null)
			{
				int count = points.Count;
				endCap.transform.position = points[count - 1];
				Vector3 normalized2 = (points[count - 2] - points[count - 1]).normalized;
				endCap.transform.rotation = Quaternion.LookRotation(normalized2);
			}
		}
	}

	protected virtual void AddNewPosition(Vector3 newPosition, Vector3 newTangent, float addTime)
	{
		if (TrackLength)
		{
			if (points.Count > 0)
			{
				segmentLengths.Add((newPosition - points[points.Count - 1]).magnitude);
			}
			else
			{
				segmentLengths.Add(0f);
			}
		}
		points.Add(newPosition);
		tangents.Add(newTangent);
		pointTimeStamps.Add(addTime);
		lineDirty = true;
		RenderersEnabled = true;
	}
}
namespace RecRoom.VFX
{
	public class DecalSpawningParticleSystem : UnityEngine.MonoBehaviour
	{
		private const int MAX_COLLISION_DECALS_PER_FRAME = 5;

		[SerializeField]
		private ImpactDecal collisionImpactDecalPrefab;

		[SerializeField]
		private Color decalColor = Color.white;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private ParticleSystem collideableParticleSystem;

		private List<ParticleCollisionEvent> particleCollisionEvents = new List<ParticleCollisionEvent>();

		private void OnParticleCollision(GameObject other)
		{
			if (!(collisionImpactDecalPrefab == null))
			{
				int collisionEvents = collideableParticleSystem.GetCollisionEvents(other, particleCollisionEvents);
				for (int i = 0; i < collisionEvents; i++)
				{
					ImpactDecal.Spawn(collisionImpactDecalPrefab, decalColor, particleCollisionEvents[i].intersection, particleCollisionEvents[i].normal, other);
				}
			}
		}
	}
}
[RequireComponent(typeof(Camera))]
public class DesaturateEffect : UnityEngine.MonoBehaviour
{
	public enum Mode
	{
		FullScreen,
		PartialScreen,
		TargetedToOverlayUI
	}

	[SerializeField]
	private Shader desaturateEffectShader;

	[SerializeField]
	private Mode mode;

	[Header("PartialScreen Mode Config")]
	[SerializeField]
	private Vector2 partialScreenBottomLeft = new Vector2(0f, 0.2f);

	[SerializeField]
	private Vector2 partialScreenTopRight = new Vector2(1f, 0.4f);

	[SerializeField]
	[Range(0f, 1f)]
	private float partialScreenEdgeFade = 0.02f;

	[Header("TargetedToOverlayUI Mode Config")]
	[SerializeField]
	private int maskTextureSize = 256;

	[SerializeField]
	private int expandIterations = 4;

	[SerializeField]
	private int blurIterations = 2;

	[Header("Desaturation Config")]
	[SerializeField]
	[Range(0f, 1f)]
	private float maxDesaturation = 1f;

	[SerializeField]
	[Range(0f, 1f)]
	private float desaturatedBlackLevel;

	[SerializeField]
	[Range(0f, 1f)]
	private float desaturatedWhiteLevel = 1f;

	private Camera camera;

	private Camera desaturateMaskGenerator;

	private RenderTexture desaturateMaskTexture;

	private Material desaturateMaterial;

	private float currentDesaturation;

	private static int SampleOffsetPropId;

	private static int RegionParamsPropId;

	private static int ScreenEdgeFadePropId;

	private static int DesaturationAmountPropId;

	private static int ColorMappingParamsPropId;

	private static int DesaturationMaskPropId;

	public float DesaturationLevel
	{
		get
		{
			return currentDesaturation;
		}
		set
		{
			currentDesaturation = value;
			base.enabled = currentDesaturation > 0f || mode == Mode.TargetedToOverlayUI;
		}
	}

	public Mode CurrentMode
	{
		get
		{
			return mode;
		}
		set
		{
			mode = value;
			base.enabled = currentDesaturation > 0f || mode == Mode.TargetedToOverlayUI;
		}
	}

	private void Awake()
	{
		SampleOffsetPropId = Shader.PropertyToID("_SampleOffset");
		RegionParamsPropId = Shader.PropertyToID("_RegionParams");
		ScreenEdgeFadePropId = Shader.PropertyToID("_ScreenEdgeFade");
		DesaturationAmountPropId = Shader.PropertyToID("_DesaturationAmount");
		ColorMappingParamsPropId = Shader.PropertyToID("_ColorMappingParams");
		DesaturationMaskPropId = Shader.PropertyToID("_DesaturationMask");
		camera = GetComponent<Camera>();
		int num = maskTextureSize;
		int height = maskTextureSize;
		if (camera.stereoEnabled)
		{
			num *= 2;
		}
		desaturateMaskTexture = new RenderTexture(num, height, 0);
		GameObject gameObject = new GameObject("DesatMaskGenerator", typeof(Camera));
		desaturateMaskGenerator = gameObject.GetComponent<Camera>();
		desaturateMaskGenerator.transform.parent = base.transform;
		desaturateMaskGenerator.cullingMask = 4194304;
		desaturateMaskGenerator.clearFlags = CameraClearFlags.Color;
		desaturateMaskGenerator.backgroundColor = Color.clear;
		desaturateMaskGenerator.targetTexture = desaturateMaskTexture;
		desaturateMaskGenerator.enabled = false;
		desaturateMaterial = new Material(desaturateEffectShader);
	}

	private void OnPreRender()
	{
		if (mode == Mode.TargetedToOverlayUI)
		{
			GenerateDesatMask();
		}
	}

	private void GenerateDesatMask()
	{
		if (camera.stereoEnabled)
		{
			desaturateMaskGenerator.worldToCameraMatrix = camera.GetStereoViewMatrix(Camera.StereoscopicEye.Left);
			desaturateMaskGenerator.projectionMatrix = camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Left);
			desaturateMaskGenerator.rect = new Rect(0f, 0f, 0.5f, 1f);
			desaturateMaskGenerator.Render();
			desaturateMaskGenerator.worldToCameraMatrix = camera.GetStereoViewMatrix(Camera.StereoscopicEye.Right);
			desaturateMaskGenerator.projectionMatrix = camera.GetStereoProjectionMatrix(Camera.StereoscopicEye.Right);
			desaturateMaskGenerator.rect = new Rect(0.5f, 0f, 0.5f, 1f);
			desaturateMaskGenerator.Render();
		}
		else
		{
			desaturateMaskGenerator.worldToCameraMatrix = camera.worldToCameraMatrix;
			desaturateMaskGenerator.projectionMatrix = camera.projectionMatrix;
			desaturateMaskGenerator.rect = new Rect(0f, 0f, 1f, 1f);
			desaturateMaskGenerator.Render();
		}
		int width = desaturateMaskTexture.width / 4;
		int height = desaturateMaskTexture.height / 4;
		RenderTexture renderTexture = RenderTexture.GetTemporary(width, height, 0);
		desaturateMaterial.EnableKeyword("COMBINE_MAX");
		desaturateMaterial.SetFloat(SampleOffsetPropId, 0.5f);
		Graphics.Blit(desaturateMaskTexture, renderTexture, desaturateMaterial, 0);
		desaturateMaterial.SetFloat(SampleOffsetPropId, 1f);
		for (int i = 0; i < expandIterations; i++)
		{
			RenderTexture temporary = RenderTexture.GetTemporary(width, height, 0);
			Graphics.Blit(renderTexture, temporary, desaturateMaterial, 0);
			RenderTexture.ReleaseTemporary(renderTexture);
			renderTexture = temporary;
		}
		desaturateMaterial.DisableKeyword("COMBINE_MAX");
		for (int j = 0; j < blurIterations; j++)
		{
			desaturateMaterial.SetFloat(SampleOffsetPropId, 0.5f + (float)j * 0.6f);
			RenderTexture temporary2 = RenderTexture.GetTemporary(width, height, 0);
			Graphics.Blit(renderTexture, temporary2, desaturateMaterial, 0);
			RenderTexture.ReleaseTemporary(renderTexture);
			renderTexture = temporary2;
		}
		Graphics.Blit(renderTexture, desaturateMaskTexture);
		RenderTexture.ReleaseTemporary(renderTexture);
	}

	private void OnRenderImage(RenderTexture source, RenderTexture destination)
	{
		desaturateMaterial.SetKeywordEnabled("FULL_SCREEN_DESATURATION", mode == Mode.FullScreen);
		desaturateMaterial.SetKeywordEnabled("PARTIAL_SCREEN_DESATURATION", mode == Mode.PartialScreen);
		desaturateMaterial.SetKeywordEnabled("USE_DESATURATION_MASK", mode == Mode.TargetedToOverlayUI);
		desaturateMaterial.SetVector(ColorMappingParamsPropId, new Vector4(desaturatedWhiteLevel - desaturatedBlackLevel, desaturatedBlackLevel, maxDesaturation, 0f));
		if (mode == Mode.TargetedToOverlayUI)
		{
			desaturateMaterial.SetTexture(DesaturationMaskPropId, desaturateMaskTexture);
		}
		else
		{
			desaturateMaterial.SetVector(RegionParamsPropId, new Vector4(partialScreenBottomLeft.x, partialScreenBottomLeft.y, partialScreenTopRight.x, partialScreenTopRight.y));
			desaturateMaterial.SetFloat(ScreenEdgeFadePropId, partialScreenEdgeFade);
			desaturateMaterial.SetFloat(DesaturationAmountPropId, currentDesaturation);
		}
		Graphics.Blit(source, destination);
	}
}
public class DynamicMeshTrail : CustomTrail
{
	private enum TangentDirection
	{
		Up,
		Forward,
		Right
	}

	private static readonly List<Vector3> INSTANTANEOUS_VERTICES = new List<Vector3>(256);

	private static readonly List<Color> INSTANTANEOUS_VERTEX_COLORS = new List<Color>(256);

	private static readonly List<Vector2> INSTANTANEOUS_UVS = new List<Vector2>(256);

	private static readonly List<int> INSTANTANEOUS_INDICES = new List<int>(1536);

	[SerializeField]
	private TangentDirection tangentDirection;

	[NonSerialized]
	public bool CanAddPoints = true;

	private Mesh[] doubleBufferedMeshes;

	private int meshIndex;

	private bool shouldDrawMesh;

	protected Vector3 previousPosition;

	private bool _autoDisableOnSleep = true;

	private const float DISABLE_DELAY = 2f;

	private float disableAtTime = float.MaxValue;

	private RigidbodyEx rigidbodyEx;

	private Color color;

	private Vector2 _widths;

	public bool AutoDisableOnSleep
	{
		get
		{
			return _autoDisableOnSleep;
		}
		set
		{
			_autoDisableOnSleep = value;
			if (!_autoDisableOnSleep)
			{
				disableAtTime = float.MaxValue;
			}
		}
	}

	public float Opacity
	{
		get
		{
			return fadeAlpha;
		}
		set
		{
			fadeAlpha = value;
		}
	}

	protected virtual Vector3 NewPositionTangent
	{
		get
		{
			Vector3 result = Vector3.zero;
			switch (tangentDirection)
			{
			case TangentDirection.Up:
				result = base.transform.up;
				break;
			case TangentDirection.Forward:
				result = base.transform.forward;
				break;
			case TangentDirection.Right:
				result = base.transform.right;
				break;
			}
			return result;
		}
	}

	private Mesh Mesh => doubleBufferedMeshes[meshIndex];

	public override Color Color
	{
		get
		{
			return color;
		}
		set
		{
			color = value;
		}
	}

	public override Vector2 Widths
	{
		get
		{
			return _widths;
		}
		set
		{
			_widths = value;
		}
	}

	protected override bool RenderersEnabled
	{
		set
		{
			shouldDrawMesh = value;
			base.RenderersEnabled = value;
		}
	}

	protected override void Awake()
	{
		base.Awake();
		doubleBufferedMeshes = new Mesh[2];
		for (int i = 0; i < doubleBufferedMeshes.Length; i++)
		{
			doubleBufferedMeshes[i] = new Mesh();
			doubleBufferedMeshes[i].MarkDynamic();
		}
		rigidbodyEx = GetComponentInParent<RigidbodyEx>();
		if (rigidbodyEx != null)
		{
			rigidbodyEx.SleepChangedEvent += RigidbodyEx_SleepChangedEvent;
			RigidbodyEx_SleepChangedEvent(rigidbodyEx);
		}
	}

	private void RigidbodyEx_SleepChangedEvent(RigidbodyEx obj)
	{
		if (AutoDisableOnSleep)
		{
			if (obj.IsSleeping())
			{
				disableAtTime = UnityEngine.Time.time + 2f;
			}
			else
			{
				base.enabled = true;
			}
		}
	}

	private void OnDestroy()
	{
		if (rigidbodyEx != null)
		{
			rigidbodyEx.SleepChangedEvent -= RigidbodyEx_SleepChangedEvent;
		}
	}

	protected override void Update()
	{
		if (CanAddPoints && (base.transform.position - previousPosition).sqrMagnitude >= minSpacingSqr)
		{
			AddNewPosition(base.transform.position, NewPositionTangent, UnityEngine.Time.time);
		}
		if (shouldDrawMesh)
		{
			Graphics.DrawMesh(Mesh, Matrix4x4.identity, materials[0], 0);
		}
		base.Update();
		if (UnityEngine.Time.time >= disableAtTime)
		{
			disableAtTime = float.MaxValue;
			base.enabled = false;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		AddNewPosition(base.transform.position, NewPositionTangent, UnityEngine.Time.time);
	}

	protected override void AddNewPosition(Vector3 newPosition, Vector3 newTangent, float addTime)
	{
		base.AddNewPosition(newPosition, newTangent, addTime);
		previousPosition = newPosition;
	}

	protected override void ApplyPoints()
	{
		meshIndex = (meshIndex + 1) % doubleBufferedMeshes.Length;
		INSTANTANEOUS_VERTICES.Clear();
		INSTANTANEOUS_UVS.Clear();
		INSTANTANEOUS_VERTEX_COLORS.Clear();
		INSTANTANEOUS_INDICES.Clear();
		Color a = this.color;
		a.a = alphas[0] * fadeAlpha;
		Color color = this.color;
		color.a = alphas[1] * fadeAlpha;
		float num = Widths[0] * widthScale;
		float num2 = Widths[1] * widthScale;
		Vector2 zero = Vector2.zero;
		int count = points.Count;
		for (int i = 0; i < count; i++)
		{
			float num3 = Mathf.InverseLerp(0f, count, i);
			float num4 = Mathf.Lerp(num, num2, num3) * 0.5f;
			INSTANTANEOUS_VERTICES.Add(points[i] + tangents[i] * num4);
			INSTANTANEOUS_VERTICES.Add(points[i] - tangents[i] * num4);
			Color item = Color.Lerp(a, color, num3);
			INSTANTANEOUS_VERTEX_COLORS.Add(item);
			INSTANTANEOUS_VERTEX_COLORS.Add(item);
			zero.x = 1f - num3;
			zero.y = 1f;
			INSTANTANEOUS_UVS.Add(zero);
			zero.y = 0f;
			INSTANTANEOUS_UVS.Add(zero);
		}
		int num5 = Mathf.Max(0, count - 1);
		for (int j = 0; j < num5; j++)
		{
			int num6 = j * 2;
			INSTANTANEOUS_INDICES.Add(num6);
			INSTANTANEOUS_INDICES.Add(num6 + 2);
			INSTANTANEOUS_INDICES.Add(num6 + 1);
			INSTANTANEOUS_INDICES.Add(num6 + 2);
			INSTANTANEOUS_INDICES.Add(num6 + 3);
			INSTANTANEOUS_INDICES.Add(num6 + 1);
			INSTANTANEOUS_INDICES.Add(num6 + 2);
			INSTANTANEOUS_INDICES.Add(num6);
			INSTANTANEOUS_INDICES.Add(num6 + 3);
			INSTANTANEOUS_INDICES.Add(num6);
			INSTANTANEOUS_INDICES.Add(num6 + 1);
			INSTANTANEOUS_INDICES.Add(num6 + 3);
		}
		Mesh.Clear(keepVertexLayout: true);
		Mesh.SetVertices(INSTANTANEOUS_VERTICES);
		Mesh.SetColors(INSTANTANEOUS_VERTEX_COLORS);
		Mesh.SetUVs(0, INSTANTANEOUS_UVS);
		Mesh.SetTriangles(INSTANTANEOUS_INDICES, 0);
		if (displayStartCap && startCap != null)
		{
			startCap.material.color = a;
			float num7 = num / 2f / startCap.transform.lossyScale.x;
			startCap.transform.localScale *= num7;
		}
		if (displayEndCap && endCap != null)
		{
			endCap.material.SetColor(CustomTrail.ParticleMaterialColorId, color);
			float num8 = num2 / 2f / endCap.transform.lossyScale.x;
			endCap.transform.localScale *= num8;
		}
	}

	public void StartTrailFade()
	{
		if (pointTimeStamps.Count <= 0)
		{
			return;
		}
		float num = base.Lifetime - (UnityEngine.Time.time - pointTimeStamps[0]);
		if (num > 0f)
		{
			for (int i = 0; i < pointTimeStamps.Count; i++)
			{
				pointTimeStamps[i] -= num;
			}
		}
	}
}
namespace RecRoom.Core.Rendering
{
	[Serializable]
	public class EnvironmentLightingSettings
	{
		[SerializeField]
		private Material skybox;

		[SerializeField]
		private Light sun;

		[SerializeField]
		private AmbientMode ambientMode;

		[SerializeField]
		private SphericalHarmonicsL2 ambientProbe;

		[SerializeField]
		private float ambientIntensity;

		[SerializeField]
		private Color ambientSkyColor;

		[SerializeField]
		private Color ambientEquatorColor;

		[SerializeField]
		private Color ambientGroundColor;

		[SerializeField]
		private Color ambientLight;

		[SerializeField]
		private DefaultReflectionMode defaultReflectionMode;

		[SerializeField]
		private int defaultReflectionResolution;

		[SerializeField]
		private Cubemap customReflection;

		[SerializeField]
		private float reflectionIntensity;

		[SerializeField]
		private int reflectionBounces;

		private static EnvironmentLightingSettings defaultSceneSettings = new EnvironmentLightingSettings();

		public void ApplySettingsToScene()
		{
			RenderSettings.ambientEquatorColor = ambientEquatorColor;
			RenderSettings.ambientGroundColor = ambientGroundColor;
			RenderSettings.ambientIntensity = ambientIntensity;
			RenderSettings.ambientLight = ambientLight;
			RenderSettings.ambientMode = ambientMode;
			RenderSettings.ambientProbe = ambientProbe;
			RenderSettings.ambientSkyColor = ambientSkyColor;
			RenderSettings.customReflection = customReflection;
			RenderSettings.defaultReflectionMode = defaultReflectionMode;
			RenderSettings.defaultReflectionResolution = defaultReflectionResolution;
			RenderSettings.reflectionBounces = reflectionBounces;
			RenderSettings.reflectionIntensity = reflectionIntensity;
			RenderSettings.skybox = skybox;
			RenderSettings.sun = sun;
		}

