namespace RecRoom.Core.ImageEffects
{
	public class FadeImageEffect
	{
		private float _fade;

		private bool _blind;

		private ISchedulerPromise activeFadeRoutine;

		private readonly PostProcessProfile globalProfile;

		public float Fade
		{
			get
			{
				return _fade;
			}
			set
			{
				_fade = value;
				UpdateSSFX();
			}
		}

		public bool Blind
		{
			get
			{
				return _blind;
			}
			set
			{
				_blind = value;
				UpdateSSFX();
			}
		}

		public FadeImageEffect(PostProcessProfile globalProfile)
		{
			this.globalProfile = globalProfile;
			UpdateSSFX();
		}

		private void UpdateSSFX()
		{
			float x = ((!Blind) ? Fade : 1f);
			if (globalProfile.TryGetSettings<ComfortSettings>(out var outSetting))
			{
				outSetting.fadeEffect.Override(x);
			}
		}

		public ISchedulerPromise FadeIn(float duration)
		{
			if (activeFadeRoutine != null)
			{
				activeFadeRoutine.Cancel();
			}
			activeFadeRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(FadeCoroutine(fadeIn: true, duration));
			return activeFadeRoutine;
		}

		public ISchedulerPromise FadeOut(float duration)
		{
			if (activeFadeRoutine != null)
			{
				activeFadeRoutine.Cancel();
			}
			activeFadeRoutine = SingletonMonoBehaviour<Scheduler>.Instance.Run(FadeCoroutine(fadeIn: false, duration));
			return activeFadeRoutine;
		}

		private IEnumerator<ISchedule> FadeCoroutine(bool fadeIn, float duration)
		{
			float initialFade = Fade;
			float finalFade = ((!fadeIn) ? 1f : 0f);
			float timer = 0f;
			while (timer < duration)
			{
				float t = timer / duration;
				Fade = Mathf.Lerp(initialFade, finalFade, t);
				timer += UnityEngine.Time.deltaTime;
				yield return Schedule.NextFrame;
			}
			Fade = finalFade;
			yield return Schedule.NextFrame;
		}
	}
}
