	public class IgnoreEffectRenderer : CommandBufferRenderer<IgnoreEffectRenderer.IgnoreEffectData>
	{
		public struct IgnoreEffectData
		{
			public Vector3 FadeCenter;

			public float FadeStartDistance;

			public float FadeCompleteDistance;

			public float MinAlpha;

			public Color? ColorOverride;
		}

		private static class ShaderIds
		{
			public static int COLOR_ID = Shader.PropertyToID("_TintColor");

			public static int FADE_CENTER_ID = Shader.PropertyToID("_FadeCenter");

			public static int FADE_START_SQ_DISTANCE_ID = Shader.PropertyToID("_FadeStartSqDistance");

			public static int FADE_START_COMPLETE_DISTANCE_ID = Shader.PropertyToID("_FadeCompleteSqDistance");

			public static int MIN_ALPHA_ID = Shader.PropertyToID("_MinAlpha");
		}

		private const int MAX_RENDERERS = 128;

		private const float MIN_LOCAL_VISUALS_IGNORE_CHECK_SQ_DISTANCE = 12.25f;

		private const float MAX_VERTICAL_IGNORE_DISTANCE = 2f;

		private static readonly RecRoomQualitySetting[] DEPTH_TEST_DISABLED_QUALITIES = new RecRoomQualitySetting[2]
		{
			RecRoomQualitySetting.Fastest,
			RecRoomQualitySetting.PS4
		};

		private const string DEPTH_TEST_KEYWORD = "DEPTH_TEST_ON";

		private const float TOOL_BOUNDING_RADIUS_MULTIPLIER = 1.5f;

		private static Material _ignoreEffectMaterial = null;

		private static Material[] _doNotRenderMaterials = null;

		private static Color? _ignoreMaterialColor;

		private static readonly RenderInstanceCollection renderers = new RenderInstanceCollection(128);

		private static readonly Dictionary<Renderer, Material[]> cachedRendererMaterials = new Dictionary<Renderer, Material[]>();

		private static IgnoreBufferSize blockedIgnoreBufferSize;

		private static Material IgnoreEffectMaterial
		{
			get
			{
				if (_ignoreEffectMaterial == null)
				{
					_ignoreEffectMaterial = new Material(Resources.Load<Material>("legacy_PlayerIgnored_mat"));
				}
				return _ignoreEffectMaterial;
			}
		}

		private static Material[] DoNotRenderMaterials
		{
			get
			{
				if (_doNotRenderMaterials == null)
				{
					_doNotRenderMaterials = new Material[1];
					_doNotRenderMaterials[0] = Resources.Load<Material>("legacy_DoNotRender_mat");
				}
				return _doNotRenderMaterials;
			}
		}

		private static Color IgnoreMaterialColor
		{
			get
			{
				if (!_ignoreMaterialColor.HasValue)
				{
					_ignoreMaterialColor = IgnoreEffectMaterial.GetColor(ShaderIds.COLOR_ID);
				}
				return _ignoreMaterialColor.Value;
			}
		}

		protected override RenderInstanceCollection InstancesToRender => renderers;

		protected override CameraEvent RenderEvent => CameraEvent.BeforeForwardAlpha;

		protected override string BufferName => "Draw IgnoredPlayers";

		public static void HideIgnoredItem(Renderer renderer, int subMeshCount)
		{
			RenderIgnoredItem(renderer, subMeshCount, hideOnly: true, Vector3.zero, 0f, 0f);
		}

		public static void RenderIgnoredItem(Renderer renderer, int subMeshCount, Player ignoringPlayer, Player ignoredPlayer = null, float minAlpha = -1f, Color? color = null)
		{
			IgnoreBufferSize ignoreBufferSize = ignoringPlayer.IgnoreBufferSize;
			float fadeStartDistance;
			float invisibleDistance;
			if (ignoringPlayer.isLocal)
			{
				if (ignoredPlayer != null && ignoredPlayer.DisplayAsIgnored)
				{
					fadeStartDistance = blockedIgnoreBufferSize.localDistance;
					invisibleDistance = blockedIgnoreBufferSize.invisibleDistance;
				}
				else
				{
					fadeStartDistance = ignoreBufferSize.localDistance;
					invisibleDistance = ignoreBufferSize.invisibleDistance;
				}
			}
			else
			{
				fadeStartDistance = ignoreBufferSize.remoteDistance;
				invisibleDistance = ignoreBufferSize.invisibleDistance;
			}
			RenderIgnoredItem(renderer, subMeshCount, hideOnly: false, ignoringPlayer.Head.transform.position, fadeStartDistance, invisibleDistance, minAlpha, color);
		}

		public static void RenderIgnoredItem(Renderer renderer, int subMeshCount, bool hideOnly, Vector3 fadeCenter, float fadeStartDistance, float fadeCompleteDistance, float minAlpha = -1f, Color? color = null)
		{
			IgnoreEffectData data = new IgnoreEffectData
			{
				FadeCenter = fadeCenter,
				FadeStartDistance = fadeStartDistance,
				FadeCompleteDistance = fadeCompleteDistance,
				MinAlpha = minAlpha,
				ColorOverride = color
			};
			renderers.TryAdd(renderer, IgnoreEffectMaterial, subMeshCount, data, renderWhenDisabled: false, hideOnly);
		}

		public static bool ShouldIgnoreTool(Player ignoringPlayer, Tool otherPlayerTool)
		{
			float projectedSqDistance;
			return ShouldIgnoreTool(ignoringPlayer, otherPlayerTool, out projectedSqDistance);
		}

		public static bool ShouldIgnoreTool(Player ignoringPlayer, Tool otherPlayerTool, out float projectedSqDistance)
		{
			bool result = false;
			projectedSqDistance = -1f;
			Player holderPlayer = otherPlayerTool.HolderPlayer;
			if (holderPlayer != null && holderPlayer != ignoringPlayer)
			{
				if (holderPlayer.isLocal && (holderPlayer.Head.transform.position - ignoringPlayer.Head.transform.position).sqrMagnitude > 12.25f)
				{
					return false;
				}
				Vector3 closestPointToTool = GetClosestPointToTool(otherPlayerTool, ignoringPlayer.Head.transform.position);
				if (TryGetProjectedIgnoreDistance(ignoringPlayer, closestPointToTool, out projectedSqDistance))
				{
					result = ShouldIgnore(ignoringPlayer, holderPlayer, projectedSqDistance);
				}
			}
			return result;
		}

		public static bool ShouldIgnoreTool(CameraIgnoreBubble ignoreBubble, Tool tool)
		{
			Player holderPlayer = tool.HolderPlayer;
			if (holderPlayer != null)
			{
				Vector3 position = ignoreBubble.Camera.transform.position;
				Vector3 closestPointToTool = GetClosestPointToTool(tool, position);
				if (TryGetProjectedIgnoreDistance(position, closestPointToTool, out var sqDistance))
				{
					float radius = ignoreBubble.Radius;
					return sqDistance < radius * radius;
				}
			}
			return false;
		}

		public static bool ShouldIgnorePlayerVisual(Player ignoringPlayer, PlayerIgnoreVisual otherPlayerVisual)
		{
			float projectedSqDistance;
			return ShouldIgnorePlayerVisual(ignoringPlayer, otherPlayerVisual, out projectedSqDistance);
		}

		public static bool ShouldIgnorePlayerVisual(Player ignoringPlayer, PlayerIgnoreVisual otherPlayerVisual, out float projectedSqDistance)
		{
			Player thisPlayer = otherPlayerVisual.ThisPlayer;
			if (ignoringPlayer == thisPlayer)
			{
				projectedSqDistance = -1f;
				return false;
			}
			if (ignoringPlayer.isLocal && thisPlayer.DisplayAsIgnored)
			{
				projectedSqDistance = -1f;
				return true;
			}
			if (thisPlayer.isLocal)
			{
				float sqrMagnitude = (thisPlayer.Head.transform.position - ignoringPlayer.Head.transform.position).sqrMagnitude;
				if (sqrMagnitude > 12.25f)
				{
					projectedSqDistance = -1f;
					return false;
				}
			}
			bool result = false;
			if (TryGetProjectedIgnoreDistance(ignoringPlayer, otherPlayerVisual.transform.position, out projectedSqDistance))
			{
				result = ShouldIgnore(ignoringPlayer, thisPlayer, projectedSqDistance, otherPlayerVisual.BufferRadius);
			}
			return result;
		}

		public static bool ShouldIgnorePlayerVisual(CameraIgnoreBubble ignoreBubble, PlayerIgnoreVisual playerVisual)
		{
			if (TryGetProjectedIgnoreDistance(ignoreBubble.Camera.transform.position, playerVisual.transform.position, out var sqDistance))
			{
				float radius = ignoreBubble.Radius;
				return sqDistance < radius * radius;
			}
			return false;
		}

		private static bool TryGetProjectedIgnoreDistance(Player player, Vector3 testPosition, out float sqDistance)
		{
			return TryGetProjectedIgnoreDistance(player.Head.transform.position, testPosition, out sqDistance);
		}

		private static bool TryGetProjectedIgnoreDistance(Vector3 centerPosition, Vector3 testPosition, out float sqDistance)
		{
			sqDistance = -1f;
			float num = Mathf.Abs(centerPosition.y - testPosition.y);
			if (num > 2f)
			{
				return false;
			}
			float num2 = testPosition.x - centerPosition.x;
			float num3 = testPosition.z - centerPosition.z;
			sqDistance = num2 * num2 + num3 * num3;
			if (sqDistance < 0.01f)
			{
				sqDistance = 0f;
			}
			return true;
		}

		private static bool ShouldIgnore(Player ignoringPlayer, Player ignoredPlayer, float projectedDistanceSqrd, float visualBufferRadius = 0f)
		{
			float num = -1f;
			IgnoreBufferSize ignoreBufferSize = ignoringPlayer.IgnoreBufferSize;
			if (ignoringPlayer.isLocal)
			{
				if (ignoredPlayer.DisplayAsIgnored)
				{
					return true;
				}
				if (ignoringPlayer.IgnoreBuffer != IgnoreBuffer.Disabled && (!ignoringPlayer.DisablePersonalBubbleForFriends || !ignoredPlayer.IsFriend))
				{
					num = ignoreBufferSize.localDistance;
				}
			}
			else if (ignoredPlayer.isLocal)
			{
				if (ignoringPlayer.DisplayAsIgnored)
				{
					return false;
				}
				if (ignoringPlayer.IgnoreBuffer != IgnoreBuffer.Disabled && (!ignoringPlayer.DisablePersonalBubbleForFriends || !ignoringPlayer.IsFriend))
				{
					num = ignoreBufferSize.remoteDistance;
				}
			}
			if (num > 0f)
			{
				num += visualBufferRadius;
				return projectedDistanceSqrd <= num * num;
			}
			return false;
		}

		private static Vector3 GetClosestPointToTool(Tool tool, Vector3 targetPosition)
		{
			Bounds colliderBounds = tool.GetColliderBounds();
			if (colliderBounds.size.sqrMagnitude <= Mathf.Epsilon)
			{
				colliderBounds = tool.GetColliderBounds(includeInactive: true);
			}
			return colliderBounds.ClosestPoint(targetPosition);
		}

		private void Start()
		{
			SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned += OnLocalPlayerSpawned;
			SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged += OnQualitySettingChanged;
		}

		private void OnDestroy()
		{
			if (SingletonMonoBehaviour<SessionManager>.Instance != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.OnLocalPlayerSpawned -= OnLocalPlayerSpawned;
			}
			if (SingletonMonoBehaviour<SettingsManager>.Instance != null)
			{
				SingletonMonoBehaviour<SettingsManager>.Instance.QualitySettingChanged -= OnQualitySettingChanged;
			}
		}

		private void OnLocalPlayerSpawned()
		{
			OnQualitySettingChanged(SingletonMonoBehaviour<SettingsManager>.Instance.QualitySetting);
			blockedIgnoreBufferSize = SingletonMonoBehaviour<SettingsManager>.Instance.GetIgnoreBufferSize(IgnoreBuffer.Blocked);
		}

		private void OnQualitySettingChanged(RecRoomQualitySetting setting)
		{
			if (DEPTH_TEST_DISABLED_QUALITIES.Contains(setting))
			{
				IgnoreEffectMaterial.DisableKeyword("DEPTH_TEST_ON");
			}
			else
			{
				IgnoreEffectMaterial.EnableKeyword("DEPTH_TEST_ON");
			}
		}

		protected override void OnPreRender()
		{
			base.OnPreRender();
			cachedRendererMaterials.Clear();
			for (int i = 0; i < InstancesToRender.Count; i++)
			{
				Renderer renderer = InstancesToRender[i].Renderer;
				if (renderer != null)
				{
					cachedRendererMaterials[renderer] = renderer.sharedMaterials;
					renderer.sharedMaterials = DoNotRenderMaterials;
				}
			}
		}

		protected override void OnPostRender()
		{
			base.OnPostRender();
			for (int i = 0; i < InstancesToRender.Count; i++)
			{
				Renderer renderer = InstancesToRender[i].Renderer;
				if (renderer != null)
				{
					cachedRendererMaterials.TryGetValue(renderer, out var value);
					if (value != null)
					{
						renderer.sharedMaterials = value;
					}
				}
			}
		}

		protected override void SetMaterialProperties(RenderInstance instance, ref MaterialPropertyBlock propertyBlock)
		{
			base.SetMaterialProperties(instance, ref propertyBlock);
			if (instance.RenderData.ColorOverride.HasValue)
			{
				propertyBlock.SetColor(ShaderIds.COLOR_ID, instance.RenderData.ColorOverride.Value.WithAlpha(IgnoreMaterialColor.a));
			}
			if (instance.RenderData.MinAlpha > 0f)
			{
				propertyBlock.SetFloat(ShaderIds.MIN_ALPHA_ID, instance.RenderData.MinAlpha);
			}
			propertyBlock.SetVector(ShaderIds.FADE_CENTER_ID, instance.RenderData.FadeCenter);
			propertyBlock.SetFloat(ShaderIds.FADE_START_SQ_DISTANCE_ID, instance.RenderData.FadeStartDistance);
			propertyBlock.SetFloat(ShaderIds.FADE_START_COMPLETE_DISTANCE_ID, instance.RenderData.FadeCompleteDistance);
		}
	}
}
