namespace RecRoom.VFX
{
	public enum JitterOffsetMode
	{
		OriginalTexture,
		AtlasTexture
	}
	[Serializable]
	public class JitteringSprite
	{
		public Renderer renderer;

		public bool applyToOnlyOneRendererMaterial;

		public int rendererMaterialIndex = -1;

		public Sprite sprite;

		public int jitterFPS = 6;

		public Vector2 maxJitterOffset;

		public Vector2 maxJitterScale;

		[Tooltip("Whether to use original texture rect or atlas rect for offset and scale of jitter")]
		public JitterOffsetMode offsetMode;

		public float phaseOffset;

		private float lastJitterPhase = float.MinValue;

		private Vector2 jitterOffset;

		private Vector3 jitterScale;

		public bool UseOneMaterialMode => applyToOnlyOneRendererMaterial && rendererMaterialIndex >= 0 && rendererMaterialIndex < renderer.materials.Length;

		public MaterialPropertyBlock MaterialProperties { get; private set; }

		public void UpdateSprite(Sprite spriteOverride = null)
		{
			if (spriteOverride != null)
			{
				sprite = spriteOverride;
			}
			float num = phaseOffset + UnityEngine.Time.time;
			float num2 = 1f / (float)jitterFPS;
			float num3 = num - lastJitterPhase;
			if (num3 < num2)
			{
				return;
			}
			lastJitterPhase = num;
			jitterOffset.x = UnityEngine.Random.Range(0f - maxJitterOffset.x, maxJitterOffset.x);
			jitterOffset.y = UnityEngine.Random.Range(0f - maxJitterOffset.y, maxJitterOffset.y);
			jitterScale.x = UnityEngine.Random.Range(0f - maxJitterScale.x, maxJitterScale.x);
			jitterScale.y = UnityEngine.Random.Range(0f - maxJitterScale.y, maxJitterScale.y);
			if (sprite != null && renderer != null)
			{
				Rect rect = ((offsetMode != JitterOffsetMode.OriginalTexture) ? sprite.textureRect : sprite.rect);
				Vector2 vector = new Vector2(rect.position.x / (float)sprite.texture.width, rect.position.y / (float)sprite.texture.height);
				Vector2 vector2 = new Vector2(rect.size.x / (float)sprite.texture.width, rect.size.y / (float)sprite.texture.height);
				Vector2 vector3 = vector + vector2 * 0.5f;
				vector3 += new Vector2(vector2.x * jitterOffset.x, vector2.y * jitterOffset.y);
				vector2 += new Vector2(vector2.x * jitterScale.x, vector2.y * jitterScale.y);
				vector = vector3 - vector2 * 0.5f;
				if (UseOneMaterialMode)
				{
					ApplyAnimationToSingleMaterial(vector, vector2);
				}
				else
				{
					ApplyAnimationToPropertyBlock(vector, vector2);
				}
			}
		}

		private void ApplyAnimationToPropertyBlock(Vector2 offset, Vector2 scale)
		{
			if (MaterialProperties == null)
			{
				MaterialProperties = new MaterialPropertyBlock();
			}
			MaterialProperties.SetTexture("_MainTex", sprite.texture);
			MaterialProperties.SetVector("_MainTex_ST", new Vector4(scale.x, scale.y, offset.x, offset.y));
			renderer.SetPropertyBlock(MaterialProperties);
		}

		private void ApplyAnimationToSingleMaterial(Vector2 offset, Vector2 scale)
		{
			renderer.materials[rendererMaterialIndex].SetTexture("_MainTex", sprite.texture);
			renderer.materials[rendererMaterialIndex].SetVector("_MainTex_ST", new Vector4(scale.x, scale.y, offset.x, offset.y));
		}
	}
	[Serializable]
	public class JitteringTransform
	{
		public Transform transform;

		public int jitterFPS = 6;

		public Vector2 maxJitterOffset;

		public Vector2 maxJitterScale;

		private float lastJitterTime;

		private Vector2 jitterOffset;

		private Vector3 jitterScale;

		private Vector3 defaultLocalPosition = Vector3.zero;

		private Vector3 defaultLocalScale = Vector3.one;

		private bool savedDefaultValues;

		public void SaveDefaultTransformValues()
		{
			if (transform != null)
			{
				defaultLocalPosition = transform.localPosition;
				defaultLocalScale = transform.localScale;
				savedDefaultValues = true;
			}
		}

		public void UpdateTransform()
		{
			if (!savedDefaultValues)
			{
				SaveDefaultTransformValues();
			}
			float num = 1f / (float)jitterFPS;
			float num2 = UnityEngine.Time.time - lastJitterTime;
			if (num2 >= num)
			{
				lastJitterTime = UnityEngine.Time.time;
				jitterOffset.x = UnityEngine.Random.Range(0f - maxJitterOffset.x, maxJitterOffset.x);
				jitterOffset.y = UnityEngine.Random.Range(0f - maxJitterOffset.y, maxJitterOffset.y);
				jitterScale.x = UnityEngine.Random.Range(0f - maxJitterScale.x, maxJitterScale.x);
				jitterScale.y = UnityEngine.Random.Range(0f - maxJitterScale.y, maxJitterScale.y);
				if (transform != null)
				{
					Vector3 localPosition = new Vector3(defaultLocalPosition.x + jitterOffset.x, defaultLocalPosition.y + jitterOffset.y, defaultLocalPosition.z);
					Vector3 localScale = new Vector3(defaultLocalScale.x + jitterScale.x, defaultLocalScale.y + jitterScale.y, defaultLocalScale.z);
					transform.localScale = localScale;
					transform.localPosition = localPosition;
				}
			}
		}
	}
}
public class LineRendererTrail : CustomTrail
{
	private static readonly Vector3[] SCRATCH_POSITIONS = new Vector3[128];

	[Header("Texture")]
	[SerializeField]
	private bool scaleTexture;

	private LineRenderer[] renderers;

	private Color _color = Color.white;

	private Vector2 _widths;

	private bool hasTexture;

	public override Color Color
	{
		get
		{
			return _color;
		}
		set
		{
			_color = value;
			if (renderers != null)
			{
				Color color = value;
				color.a = alphas.x * fadeAlpha;
				Color color2 = value;
				color2.a = alphas.y * fadeAlpha;
				for (int i = 0; i < renderers.Length; i++)
				{
					renderers[i].startColor = color;
					renderers[i].endColor = color2;
				}
				if (displayStartCap && startCap != null)
				{
					startCap.material.SetColor(CustomTrail.ParticleMaterialColorId, color);
				}
				if (displayEndCap && endCap != null)
				{
					endCap.material.SetColor(CustomTrail.ParticleMaterialColorId, color2);
				}
			}
		}
	}

	public override Vector2 Widths
	{
		get
		{
			return _widths;
		}
		set
		{
			_widths = value;
			for (int i = 0; i < renderers.Length; i++)
			{
				renderers[i].startWidth = _widths[0] * widthScale;
				renderers[i].endWidth = _widths[1] * widthScale;
			}
			if (displayStartCap && startCap != null)
			{
				float num = _widths[0] * widthScale / 2f / startCap.transform.lossyScale.x;
				startCap.transform.localScale *= num;
			}
			if (displayEndCap && endCap != null)
			{
				float num2 = _widths[1] * widthScale / 2f / endCap.transform.lossyScale.x;
				endCap.transform.localScale *= num2;
			}
		}
	}

	protected override bool TrackLength => hasTexture && scaleTexture;

	protected override void Awake()
	{
		renderers = new LineRenderer[materials.Length];
		LineRenderer[] componentsInChildren = GetComponentsInChildren<LineRenderer>(includeInactive: true);
		int i;
		for (i = 0; i < renderers.Length && i < componentsInChildren.Length; i++)
		{
			renderers[i] = componentsInChildren[i];
		}
		GameObject gameObject = base.gameObject;
		for (; i < renderers.Length; i++)
		{
			if (i > 0)
			{
				gameObject = new GameObject(materials[i].name);
				gameObject.transform.SetParent(base.transform, worldPositionStays: false);
			}
			renderers[i] = gameObject.AddComponent<LineRenderer>();
		}
		for (; i < componentsInChildren.Length; i++)
		{
			UnityEngine.Object.Destroy(componentsInChildren[i]);
		}
		for (i = 0; i < renderers.Length; i++)
		{
			renderers[i].sharedMaterial = UnityEngine.Object.Instantiate(materials[i]);
			if (renderers[i].sharedMaterial.mainTexture != null && scaleTexture)
			{
				hasTexture = true;
			}
			renderers[i].shadowCastingMode = (castShadows ? ShadowCastingMode.On : ShadowCastingMode.Off);
			renderers[i].receiveShadows = receiveShadows;
		}
		base.Awake();
	}

	protected void OnDestroy()
	{
		for (int i = 0; i < renderers.Length; i++)
		{
			UnityEngine.Object.Destroy(renderers[i].sharedMaterial);
		}
	}

	protected override void ApplyPoints()
	{
		if (renderers == null)
		{
			return;
		}
		int count = points.Count;
		Vector2 mainTextureScale = Vector2.zero;
		if (count > 0)
		{
			points.CopyTo(SCRATCH_POSITIONS);
			if (TrackLength)
			{
				mainTextureScale = new Vector2(base.Length, 1f);
			}
		}
		for (int i = 0; i < renderers.Length; i++)
		{
			renderers[i].positionCount = count;
			if (count > 0)
			{
				renderers[i].SetPositions(SCRATCH_POSITIONS);
				if (TrackLength)
				{
					renderers[i].sharedMaterial.mainTextureScale = mainTextureScale;
				}
			}
		}
	}
}
public class LoadingScreen : SingletonMonoBehaviour<LoadingScreen>
{
	[SerializeField]
	private WaitCursor waitCursor;

	private Camera camera;

	private Camera cachedCamera;

	private int currentEye;

	private bool savedFogState;

	private bool isVisible;

	public bool IsVisible
	{
		get
		{
			return isVisible;
		}
		set
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
			{
				value = false;
			}
			if (value != isVisible)
			{
				isVisible = value;
				if (isVisible)
				{
					base.gameObject.SetActive(value: true);
					OnShow();
				}
				else
				{
					base.gameObject.SetActive(value: false);
					OnHide();
				}
			}
		}
	}

	protected override void Awake()
	{
		base.Awake();
		base.gameObject.SetActive(value: false);
		base.transform.SetPositionAndRotation(new Vector3(9999f, 9999f, 9999f), Quaternion.identity);
		Camera main = Camera.main;
		camera = base.gameObject.AddComponent<Camera>();
		camera.cullingMask = 4194304;
		camera.clearFlags = CameraClearFlags.Color;
		camera.backgroundColor = Color.black;
		camera.useOcclusionCulling = false;
	}

	private void OnEnable()
	{
		UpdateCachedCamera();
	}

	private void Update()
	{
		UpdateCachedCamera();
		currentEye = 0;
	}

	private void OnPreRender()
	{
		savedFogState = RenderSettings.fog;
		RenderSettings.fog = false;
	}

	private void OnPostRender()
	{
		RenderSettings.fog = savedFogState;
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
		{
			RenderVR();
		}
		else
		{
			RenderScreens();
		}
	}

	private void OnShow()
	{
		waitCursor.Reset();
	}

	private void OnHide()
	{
	}

	private IEnumerator DelayedDeactivate()
	{
		yield return new WaitForEndOfFrame();
		yield return new WaitForEndOfFrame();
		yield return new WaitForEndOfFrame();
		yield return new WaitForEndOfFrame();
		base.gameObject.SetActive(value: false);
	}

	private void RenderScreens()
	{
		RenderTexture dest = null;
		if (isVisible)
		{
			Graphics.Blit(RenderTexture.active, dest);
		}
		else
		{
			Graphics.Blit(Texture2D.blackTexture, dest);
		}
	}

	private void UpdateCachedCamera()
	{
		if (cachedCamera != SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera)
		{
			cachedCamera = SingletonMonoBehaviour<CameraRig>.Instance.ActiveCamera;
			camera.allowHDR = cachedCamera.allowHDR;
			camera.allowMSAA = cachedCamera.allowMSAA;
			camera.stereoSeparation = cachedCamera.stereoSeparation;
			camera.stereoConvergence = cachedCamera.stereoConvergence;
			camera.stereoTargetEye = cachedCamera.stereoTargetEye;
			camera.depth = GetCameraDepth();
		}
	}

	private void RenderVR()
	{
		currentEye++;
	}

	private int GetCameraDepth()
	{
		return 99;
	}
}
public class MaterialLightingUtil
{
	private static readonly Vector4[] shaderCoefficients = new Vector4[3];

	private static readonly int SHADER_ID_SHAr = Shader.PropertyToID("unity_SHAr");

	private static readonly int SHADER_ID_SHAg = Shader.PropertyToID("unity_SHAg");

	private static readonly int SHADER_ID_SHAb = Shader.PropertyToID("unity_SHAb");

	private static readonly int SHADER_ID_SHBr = Shader.PropertyToID("unity_SHBr");

	private static readonly int SHADER_ID_SHBg = Shader.PropertyToID("unity_SHBg");

	private static readonly int SHADER_ID_SHBb = Shader.PropertyToID("unity_SHBb");

	private static readonly int SHADER_ID_SHC = Shader.PropertyToID("unity_SHC");

	public static void SetLightProbeMaterialProperties(Renderer renderer, ref MaterialPropertyBlock propertyBlock)
	{
		LightProbes.GetInterpolatedProbe(renderer.transform.position, renderer, out var probe);
		for (int i = 0; i < 3; i++)
		{
			shaderCoefficients[i].x = probe[i, 3];
			shaderCoefficients[i].y = probe[i, 1];
			shaderCoefficients[i].z = probe[i, 2];
			shaderCoefficients[i].w = probe[i, 0] - probe[i, 6];
		}
		propertyBlock.SetVector(SHADER_ID_SHAr, shaderCoefficients[0]);
		propertyBlock.SetVector(SHADER_ID_SHAg, shaderCoefficients[1]);
		propertyBlock.SetVector(SHADER_ID_SHAb, shaderCoefficients[2]);
		for (int j = 0; j < 3; j++)
		{
			shaderCoefficients[j].x = probe[j, 4];
			shaderCoefficients[j].y = probe[j, 6];
			shaderCoefficients[j].z = probe[j, 5];
			shaderCoefficients[j].w = probe[j, 7];
		}
		propertyBlock.SetVector(SHADER_ID_SHBr, shaderCoefficients[0]);
		propertyBlock.SetVector(SHADER_ID_SHBg, shaderCoefficients[1]);
		propertyBlock.SetVector(SHADER_ID_SHBb, shaderCoefficients[2]);
		shaderCoefficients[0].x = probe[0, 8];
		shaderCoefficients[0].y = probe[2, 8];
		shaderCoefficients[0].z = probe[1, 8];
		shaderCoefficients[0].w = 1f;
		propertyBlock.SetVector(SHADER_ID_SHC, shaderCoefficients[0]);
	}
}
namespace RecRoom.Core.ImageEffects
{
	[DisallowMultipleComponent]
	public class MonochromeImageEffect : UnityEngine.MonoBehaviour
	{
		private Coroutine animatingRoutine;

		private PostProcessProfile profile;

		public bool IsMonochrome => MonochromeAmount > Mathf.Epsilon;

		public float MonochromeAmount { get; private set; }

		public void Initialize(PostProcessProfile globalProfile)
		{
			profile = globalProfile;
		}

		public void LerpToMonochromeAmount(float targetAmount, float timeToLerp = 0.2f)
		{
			if (animatingRoutine != null)
			{
				StopCoroutine(animatingRoutine);
			}
			animatingRoutine = StartCoroutine(AnimateMonochrome(profile, targetAmount, timeToLerp));
		}

		private IEnumerator AnimateMonochrome(PostProcessProfile profile, float target, float time)
		{
			float velocity = 0f;
			if (profile.TryGetSettings<ComfortSettings>(out var comfortSettings))
			{
				for (float t = 0f; t < 1f; t += UnityEngine.Time.unscaledDeltaTime / time)
				{
					MonochromeAmount = Mathf.SmoothDamp(MonochromeAmount, target, ref velocity, time);
					comfortSettings.grayscaleEffect.Override(MonochromeAmount);
					yield return 0;
				}
				comfortSettings.grayscaleEffect.Override(target);
			}
			else
			{
				UnityEngine.Debug.LogWarning("Cannot animate to Monochrome, Profile has no ComfortSettings", profile);
			}
		}
	}
}
