[ExecuteInEditMode]
[RequireComponent(typeof(ParticleSystem))]
public class ParticleOscillator : UnityEngine.MonoBehaviour
{
	public enum OscillationVariable
	{
		StartSpeed
	}

	[SerializeField]
	private OscillationVariable variableToOscillate;

	[SerializeField]
	private float frequency = 3f;

	[SerializeField]
	private float minValue;

	[SerializeField]
	private float maxValue = 1f;

	private ParticleSystem particle;

	private void Awake()
	{
		particle = GetComponent<ParticleSystem>();
	}

	private void Update()
	{
		if (particle.isPlaying)
		{
			float num = minValue + (maxValue - minValue) * (1f + Mathf.Sin(UnityEngine.Time.realtimeSinceStartup * 2f * (float)Math.PI * frequency)) / 2f;
			if (variableToOscillate == OscillationVariable.StartSpeed)
			{
				ParticleSystem.MainModule main = particle.main;
				main.startSpeed = num;
			}
		}
	}
}
public class ParticleSystemsPlay : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool destroyOnDone = true;

	[SerializeField]
	private float destroyLifeTimeOverride = 5f;

	private void Start()
	{
		float num = destroyLifeTimeOverride;
		ParticleSystem[] componentsInChildren = GetComponentsInChildren<ParticleSystem>();
		foreach (ParticleSystem particleSystem in componentsInChildren)
		{
			num = Mathf.Max(num, particleSystem.main.startLifetime.constant);
			particleSystem.Clear();
			particleSystem.Play();
		}
		if (destroyOnDone)
		{
			UnityEngine.Object.Destroy(base.gameObject, num);
		}
	}
}
public class PlayerTrail : LineRendererTrail
{
	[SerializeField]
	[Tooltip("Rate that trail will fade from tip to head.  In units of m/s.")]
	private float fadeOutRate = 10f;

	public void PlayTeleportTrail(Vector3 playerHeadOffset, Vector3 startPlayerPosition, Vector3 endPlayerPosition)
	{
		Clear();
		Vector3 vector = endPlayerPosition - startPlayerPosition;
		float magnitude = vector.magnitude;
		if (!(magnitude <= Mathf.Epsilon))
		{
			Vector3 vector2 = vector / magnitude;
			int num = Mathf.RoundToInt(magnitude / minSpacing);
			float num2 = magnitude / (float)num;
			float num3 = magnitude / fadeOutRate;
			float num4 = num3 / (float)num;
			playerHeadOffset -= Vector3.up * widths.y / 2f;
			startPlayerPosition += playerHeadOffset;
			endPlayerPosition += playerHeadOffset;
			for (int i = 0; i < num; i++)
			{
				AddNewPosition(startPlayerPosition + vector2 * i * num2, Vector3.up, UnityEngine.Time.time + (float)i * num4);
			}
		}
	}
}
public class PreviewVisualRenderer : UnityEngine.MonoBehaviour
{
	private struct RenderInstance
	{
		public Mesh Mesh;

		public Material Material;

		public int SubMeshCount;

		public Matrix4x4 WorldMatrix;
	}

	private Camera camera;

	private CommandBuffer commandBuffer;

	private static List<RenderInstance> renderInstances = new List<RenderInstance>();

	private static Material _previewVisualMaterial = null;

	private static Material _previewOutlineMaterial = null;

	private static Material PreviewVisualMaterial
	{
		get
		{
			if (_previewVisualMaterial == null)
			{
				_previewVisualMaterial = Resources.Load<Material>("legacy_PreviewVisual_mat");
			}
			return _previewVisualMaterial;
		}
	}

	private static Material PreviewOutlineMaterial
	{
		get
		{
			if (_previewOutlineMaterial == null)
			{
				_previewOutlineMaterial = Resources.Load<Material>("legacy_ToolOutline_mat");
			}
			return _previewOutlineMaterial;
		}
	}

	public static void RenderPreviewVisual(Mesh mesh, int subMeshCount, Vector3 worldSpacePosition, Quaternion worldSpaceRotation, Vector3 worldSpaceScale)
	{
		RenderInstance item = new RenderInstance
		{
			Mesh = mesh,
			Material = PreviewVisualMaterial,
			SubMeshCount = subMeshCount,
			WorldMatrix = Matrix4x4.TRS(worldSpacePosition, worldSpaceRotation, worldSpaceScale)
		};
		renderInstances.Add(item);
		item.Material = PreviewOutlineMaterial;
		renderInstances.Add(item);
	}

	private void Awake()
	{
		commandBuffer = new CommandBuffer();
		commandBuffer.name = "Draw Preview Visuals";
		camera = GetComponent<Camera>();
		camera.AddCommandBuffer(CameraEvent.BeforeForwardAlpha, commandBuffer);
		StartCoroutine(ClearInstancesToRenderCoroutine());
	}

	private void OnPreRender()
	{
		if (commandBuffer == null)
		{
			return;
		}
		commandBuffer.Clear();
		foreach (RenderInstance renderInstance in renderInstances)
		{
			if (!(renderInstance.Mesh == null) && !(renderInstance.Material == null))
			{
				for (int i = 0; i < renderInstance.SubMeshCount; i++)
				{
					commandBuffer.DrawMesh(renderInstance.Mesh, renderInstance.WorldMatrix, renderInstance.Material, i, -1);
				}
			}
		}
	}

	private IEnumerator ClearInstancesToRenderCoroutine()
	{
		WaitForEndOfFrame waitForEndOfFrame = new WaitForEndOfFrame();
		while (true)
		{
			yield return waitForEndOfFrame;
			renderInstances.Clear();
		}
	}
}
public class PulsingBeam : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private bool gravityAligned;

	[SerializeField]
	private float scalePulseAmount;

	[SerializeField]
	private float scalePulseSpeed;

	[NonSerialized]
	public float BlinkFrequency = 1f;

	private float _blinkStartTime;

	private bool _isBlinking;

	private float initialHeight;

	private float initialRadialScale;

	private MeshRenderer cylinderRenderer;

	private MaterialPropertyBlock materialPropertyBlock;

	private static readonly int COLOR_SHADER_ID = Shader.PropertyToID("_Color");

	public bool IsBlinking
	{
		get
		{
			return _isBlinking;
		}
		set
		{
			bool isBlinking = _isBlinking;
			_isBlinking = value;
			if (!isBlinking && _isBlinking)
			{
				_blinkStartTime = UnityEngine.Time.time;
			}
		}
	}

	private float BlinkStartTime => _blinkStartTime;

	private void Awake()
	{
		initialHeight = base.transform.localScale.y;
		initialRadialScale = base.transform.localScale.x;
		scalePulseSpeed += UnityEngine.Random.Range(-0.2f, 0.2f);
	}

	private void OnEnable()
	{
		IsBlinking = false;
	}

	private void Update()
	{
		if (gravityAligned)
		{
			base.transform.rotation = Quaternion.LookRotation(Vector3.forward, Vector3.up);
		}
		Vector3 localScale = base.transform.localScale;
		localScale.z = (localScale.x = initialRadialScale + Mathf.Sin(UnityEngine.Time.time * scalePulseSpeed) * scalePulseAmount);
		if (IsBlinking)
		{
			float num = UnityEngine.Time.time - BlinkStartTime;
			float t = num * BlinkFrequency % 1f;
			t = Mathf.Lerp(1f, 0f, t);
			float num2 = Mathf.Round(t);
			localScale.y = num2 * initialHeight;
		}
		else
		{
			localScale.y = initialHeight;
		}
		base.transform.localScale = localScale;
	}

	public void SetColor(Color color)
	{
		if (cylinderRenderer == null)
		{
			cylinderRenderer = GetComponentInChildren<MeshRenderer>(includeInactive: true);
		}
		if (materialPropertyBlock == null)
		{
			materialPropertyBlock = new MaterialPropertyBlock();
		}
		materialPropertyBlock.SetColor(COLOR_SHADER_ID, color);
		cylinderRenderer.SetPropertyBlock(materialPropertyBlock);
	}
}
