namespace RecRoom.Core.ImageEffects
{
	[DisallowMultipleComponent]
	public class VignetteImageEffect : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private struct VignetteSettings
		{
			public Color Color;

			public float Intensity;

			public float Smoothness;

			public bool SupportsIntensityRange;

			public float MinRangeIntensity;

			public float MaxRangeIntensity;

			public static VignetteSettings Default = new VignetteSettings
			{
				Color = Color.black,
				Intensity = 0.72f,
				Smoothness = 0.1f
			};
		}

		private class VignetteLayer
		{
			public string Name;

			public Color Color;

			public float DefaultIntensity;

			public bool IsComfort;

			public bool SupportsIntensityRange;

			public float MinRangeIntensity;

			public float MaxRangeIntensity;

			public float Smoothness;

			public float TimeToFadeIn;

			public float RangeInterpolation;

			public bool IsFadingOut;

			public float FadeOutStartTime;

			public float TimeToFadeOut;

			public readonly int Priority;

			public float FadeOutEndTime => FadeOutStartTime + 2f * TimeToFadeOut;

			public VignetteLayer(int priority, string name, bool isComfort = false)
			{
				Priority = priority;
				Name = name;
				IsComfort = isComfort;
			}

			public float GetIntensity()
			{
				float num = GetBaseIntensity();
				if (IsFadingOut)
				{
					float t = Mathf.InverseLerp(FadeOutStartTime, FadeOutEndTime, UnityEngine.Time.time);
					num = Mathf.Lerp(num, 0f, t);
				}
				return num;
			}

			private float GetBaseIntensity()
			{
				if (SupportsIntensityRange)
				{
					return Mathf.Lerp(MinRangeIntensity, MaxRangeIntensity, RangeInterpolation);
				}
				return DefaultIntensity;
			}
		}

		[SerializeField]
		private VignetteSettings teleportSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings walkSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings sprintSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings flySettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings vehicleSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings continuousRotationSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings swipeRotateSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings worldCollisionSettings = VignetteSettings.Default;

		[SerializeField]
		private VignetteSettings takeDamageSettings = VignetteSettings.Default;

		private const float MIN_VISIBLE_SMOOTHNESS = 0.1f;

		private const float MIN_VISIBLE_INTENSITY = 0.25f;

		private const float INTENSITY_EPSILON = 0.001f;

		private readonly List<VignetteLayer> layerPriorityQueue = new List<VignetteLayer>();

		private VignetteLayer continuousRotationLayer = new VignetteLayer(10, "Continuous Rotation", isComfort: true);

		private VignetteLayer swipeRotateLayer = new VignetteLayer(20, "Swipe Rotate", isComfort: true);

		private VignetteLayer teleportLayer = new VignetteLayer(50, "Teleport", isComfort: true);

		private VignetteLayer flyLayer = new VignetteLayer(60, "Fly", isComfort: true);

		private VignetteLayer walkLayer = new VignetteLayer(70, "Walk", isComfort: true);

		private VignetteLayer sprintLayer = new VignetteLayer(71, "Sprint", isComfort: true);

		private VignetteLayer vehicleLayer = new VignetteLayer(72, "Vehicle", isComfort: true);

		private VignetteLayer worldCollisionLayer = new VignetteLayer(80, "World Collision");

		private VignetteLayer takeDamageLayer = new VignetteLayer(100, "Take Damage");

		private float intensityVelocity;

		private float smoothnessVelocity;

		private float timeToFadeOut;

		private PostProcessProfile globalProfile;

		private VignetteLayer TopLayer
		{
			get
			{
				bool comfortVignettingEnabled = ComfortVignettingEnabled;
				for (int num = layerPriorityQueue.Count - 1; num >= 0; num--)
				{
					VignetteLayer vignetteLayer = layerPriorityQueue[num];
					if (comfortVignettingEnabled || !vignetteLayer.IsComfort)
					{
						return vignetteLayer;
					}
				}
				return null;
			}
		}

		private bool ComfortVignettingEnabled => SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode && !SingletonMonoBehaviour<CameraRig>.Instance.IsTVMode;

		public void Initialize(PostProcessProfile globalProfile)
		{
			this.globalProfile = globalProfile;
		}

		private void Update()
		{
			UpdateLayers();
		}

		public void StartWorldCollisionVignette(float fadeInDuration)
		{
			StartLayer(worldCollisionLayer, worldCollisionSettings, fadeInDuration);
		}

		public void StopWorldCollisionVignette(float fadeOutDuration)
		{
			StopLayer(worldCollisionLayer, fadeOutDuration);
		}

		public void StartTeleportVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortTeleport)
			{
				StartLayer(teleportLayer, teleportSettings, fadeInDuration);
			}
		}

		public void StopTeleportVignette(float fadeOutDuration)
		{
			StopLayer(teleportLayer, fadeOutDuration);
		}

		public void StartFlyVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortFly)
			{
				StartLayer(flyLayer, flySettings, fadeInDuration);
			}
		}

		public void StopFlyVignette(float fadeOutDuration)
		{
			StopLayer(flyLayer, fadeOutDuration);
		}

		public void StartContinuousRotationVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortSmoothRotate)
			{
				StartLayer(continuousRotationLayer, continuousRotationSettings, fadeInDuration);
			}
		}

		public void StopContinuousRotationVignette(float fadeOutDuration)
		{
			StopLayer(continuousRotationLayer, fadeOutDuration);
		}

		public void StartSwipeRotateVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortSwipeRotate)
			{
				StartLayer(swipeRotateLayer, swipeRotateSettings, fadeInDuration);
			}
		}

		public void StopSwipeRotateVignette(float fadeOutDuration)
		{
			StopLayer(swipeRotateLayer, fadeOutDuration);
		}

		public void StartWalkingVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortWalk)
			{
				StartLayer(walkLayer, walkSettings, fadeInDuration);
			}
		}

		public void StopWalkingVignette(float fadeOutDuration)
		{
			StopLayer(walkLayer, fadeOutDuration);
		}

		public void StartVehicleVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortVehicles)
			{
				StartLayer(vehicleLayer, vehicleSettings, fadeInDuration);
			}
		}

		public void StopVehicleVignette(float fadeOutDuration)
		{
			StopLayer(vehicleLayer, fadeOutDuration);
		}

		public void StartSprintingVignette(float fadeInDuration)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.ComfortSprint)
			{
				StartLayer(sprintLayer, sprintSettings, fadeInDuration);
			}
		}

		public void StopSprintingVignette(float fadeOutDuration)
		{
			StopLayer(sprintLayer, fadeOutDuration);
		}

		public void SetWalkingVignetteIntensityInterpolation(float interpolation)
		{
			walkLayer.RangeInterpolation = interpolation;
		}

		public void SetVehicleVignetteIntensityInterpolation(float interpolation)
		{
			vehicleLayer.RangeInterpolation = interpolation;
		}

		public void StartTakeDamageVignette(float fadeInDuration)
		{
			StartLayer(takeDamageLayer, takeDamageSettings, fadeInDuration);
		}

		public void StopTakeDamageVignette(float fadeOutDuration)
		{
			StopLayer(takeDamageLayer, fadeOutDuration);
		}

		private void StartLayer(VignetteLayer layer, VignetteSettings settings, float timeToStart)
		{
			if (TryAddLayer(layer) || layer.IsFadingOut)
			{
				layer.Color = settings.Color;
				layer.Smoothness = settings.Smoothness;
				layer.DefaultIntensity = settings.Intensity;
				layer.SupportsIntensityRange = settings.SupportsIntensityRange;
				layer.MinRangeIntensity = settings.MinRangeIntensity;
				layer.MaxRangeIntensity = settings.MaxRangeIntensity;
				layer.IsFadingOut = false;
				layer.TimeToFadeIn = timeToStart;
				layer.RangeInterpolation = 0f;
			}
		}

		private void StopLayer(VignetteLayer layer, float timeToStop)
		{
			if (layerPriorityQueue.Contains(layer))
			{
				if (timeToStop <= UnityEngine.Time.deltaTime)
				{
					RemoveLayer(layer);
					return;
				}
				layer.IsFadingOut = true;
				layer.FadeOutStartTime = UnityEngine.Time.time;
				layer.TimeToFadeOut = timeToStop;
			}
		}

		private void UpdateLayers()
		{
			RemoveFadedOutLayers();
			ComfortSettings outSetting;
			if (!globalProfile)
			{
				UnityEngine.Debug.LogWarning("Missing PostProcessing on VignetteImageEffect", this);
			}
			else if (globalProfile.TryGetSettings<ComfortSettings>(out outSetting))
			{
				float smoothTime = timeToFadeOut;
				float target = 0.1f;
				float target2 = 0.25f;
				VignetteLayer maximumIntensityLayer = GetMaximumIntensityLayer();
				bool flag = maximumIntensityLayer != null;
				if (flag)
				{
					target2 = maximumIntensityLayer.GetIntensity();
					target = maximumIntensityLayer.Smoothness;
					VignetteLayer topLayer = TopLayer;
					outSetting.vignetteColor.Override(topLayer.Color);
					smoothTime = ((!topLayer.IsFadingOut) ? topLayer.TimeToFadeIn : topLayer.TimeToFadeOut);
				}
				float num = outSetting.vignettePower.value;
				float value = outSetting.vignetteSmoothness.value;
				if (flag && num < 0.25f)
				{
					num = 0.25f;
				}
				else if (!flag && num < 0.251f)
				{
					num = 0f;
					outSetting.vignetteColor.Override(Color.black);
				}
				outSetting.vignetteSmoothness.Override(Mathf.SmoothDamp(value, target, ref smoothnessVelocity, smoothTime));
				outSetting.vignettePower.Override(Mathf.SmoothDamp(num, target2, ref intensityVelocity, smoothTime));
			}
		}

		private void RemoveFadedOutLayers()
		{
			while (layerPriorityQueue.Count != 0)
			{
				VignetteLayer topLayer = TopLayer;
				if (topLayer == null || !topLayer.IsFadingOut || UnityEngine.Time.time < topLayer.FadeOutEndTime)
				{
					break;
				}
				RemoveLayer(topLayer);
			}
		}

		private bool TryAddLayer(VignetteLayer layer)
		{
			if (!layerPriorityQueue.Contains(layer))
			{
				layerPriorityQueue.Add(layer);
				SortPriorityQueue();
				return true;
			}
			return false;
		}

		private void RemoveLayer(VignetteLayer layer)
		{
			if (layerPriorityQueue.Contains(layer))
			{
				layerPriorityQueue.Remove(layer);
				SortPriorityQueue();
			}
		}

		private void SortPriorityQueue()
		{
			layerPriorityQueue.Sort((VignetteLayer a, VignetteLayer b) => a.Priority.CompareTo(b.Priority));
		}

		private VignetteLayer GetMaximumIntensityLayer()
		{
			bool comfortVignettingEnabled = ComfortVignettingEnabled;
			VignetteLayer result = null;
			float num = 0f;
			for (int i = 0; i < layerPriorityQueue.Count; i++)
			{
				VignetteLayer vignetteLayer = layerPriorityQueue[i];
				if (comfortVignettingEnabled || !vignetteLayer.IsComfort)
				{
					float intensity = vignetteLayer.GetIntensity();
					if (intensity > num)
					{
						num = intensity;
						result = vignetteLayer;
					}
				}
			}
			return result;
		}
	}
}
[ExecuteInEditMode]
public class WaitCursor : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Material waitCursorMaterial;

	[SerializeField]
	private int WaitCursorRows = 1;

	[SerializeField]
	private int WaitCursorColumns = 1;

	private static readonly int ANIMATION_RATE = 15;

	private float timeUntilNextFrame;

	private int currentFrame;

	private int TileAndOffsetPropertyID;

	private void Awake()
	{
		TileAndOffsetPropertyID = Shader.PropertyToID("_MainTex_ST");
	}

	private void Start()
	{
		Reset();
	}

	private void Update()
	{
		UpdateMaterial();
	}

	public void Reset()
	{
		currentFrame = 0;
		timeUntilNextFrame = 1f / (float)ANIMATION_RATE;
		UpdateMaterial();
	}

	private void UpdateMaterial()
	{
		int num = currentFrame;
		timeUntilNextFrame -= UnityEngine.Time.deltaTime;
		if (timeUntilNextFrame <= 0f)
		{
			currentFrame++;
			timeUntilNextFrame = 1f / (float)ANIMATION_RATE;
		}
		int num2 = num % (WaitCursorRows * WaitCursorColumns);
		int num3 = num2 / WaitCursorColumns;
		int num4 = num2 % WaitCursorColumns;
		float num5 = 1f / (float)WaitCursorColumns;
		float num6 = 1f / (float)WaitCursorRows;
		waitCursorMaterial.SetVector(TileAndOffsetPropertyID, new Vector4(num5, num6, (float)num4 * num5, 1f - num6 - (float)num3 * num6));
	}
}
namespace RecRoom.Core.Rendering
{
	public class WorldFadeRenderer : CommandBufferRenderer<byte>
	{
		private const int MAX_MASKS = 64;

		private static bool USE_FAST_RENDERING = false;

		private static Mesh _screenQuad = null;

		private static Material objectMaskMaterial;

		private static Material screenFadeFastMaterial;

		private static readonly RenderInstanceCollection masksToRender = new RenderInstanceCollection(64);

		private static Mesh ScreenQuad
		{
			get
			{
				if (_screenQuad == null)
				{
					_screenQuad = new Mesh();
					Vector3[] vertices = new Vector3[4]
					{
						new Vector3(-0.5f, -0.5f, 0f),
						new Vector3(0.5f, -0.5f, 0f),
						new Vector3(-0.5f, 0.5f, 0f),
						new Vector3(0.5f, 0.5f, 0f)
					};
					_screenQuad.vertices = vertices;
					int[] indices = new int[6] { 0, 1, 2, 1, 3, 2 };
					_screenQuad.SetIndices(indices, MeshTopology.Triangles, 0);
					_screenQuad.UploadMeshData(markNoLongerReadable: true);
				}
				return _screenQuad;
			}
		}

		protected override RenderInstanceCollection InstancesToRender => masksToRender;

		protected override string BufferName => "Draw World Fade";

		protected override bool UseLightProbes => false;

		protected override CameraEvent RenderEvent => CameraEvent.AfterSkybox;

		protected override bool OverrideMaterialProperties => false;

		public static void SetMaterials(Material objectMask, Material screenFadeFast)
		{
			objectMaskMaterial = objectMask;
			screenFadeFastMaterial = screenFadeFast;
		}

		public static void RenderMask(Renderer renderer, int subMeshCount = 1)
		{
			masksToRender.TryAdd(renderer, objectMaskMaterial, subMeshCount, 0, renderWhenDisabled: true);
		}

		protected override void OnPreRender()
		{
			base.OnPreRender();
			if (InstancesToRender.Count > 0 && USE_FAST_RENDERING)
			{
				commandBuffer.DrawMesh(ScreenQuad, Matrix4x4.identity, screenFadeFastMaterial);
			}
		}

		public static bool ShouldRenderImageEffect()
		{
			return !USE_FAST_RENDERING && masksToRender.Count > 0;
		}
	}
}
namespace RecRoom.Core.ImageEffects
{
	public class WorldSpaceCameraBlinders : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		private float gradientStartAngle = 90f;

		[SerializeField]
		private float gradientEndAngle = 120f;

		[SerializeField]
		private float gradientMaxAngle = 160f;

		[SerializeField]
		private Camera targetCamera;

		[NonSerialized]
		public Transform DesiredForwardTransform;

		public bool BlindersEnabled
		{
			get
			{
				return false;
			}
			set
			{
			}
		}

		private void LateUpdate()
		{
			if (BlindersEnabled)
			{
				Vector3 normalized = Vector3.ProjectOnPlane(DesiredForwardTransform.forward, Vector3.up).normalized;
				Vector3 normalized2 = Vector3.ProjectOnPlane(targetCamera.transform.forward, Vector3.up).normalized;
				float num = normalized.AngleSignedVector3(normalized2);
				float num2 = Mathf.Abs(num);
				float num3 = Mathf.InverseLerp(gradientStartAngle, gradientEndAngle, num2);
				if (num3 > 0f)
				{
					if (num2 >= gradientMaxAngle)
					{
						SetFullDarkGradient();
					}
					else if (num >= 0f)
					{
						SetClockwiseGradient(num3);
					}
					else
					{
						SetCounterClockwiseGradient(num3);
					}
					return;
				}
			}
			SetDefaultGradient();
		}

		private void SetDefaultGradient()
		{
		}

		private void SetFullDarkGradient()
		{
		}

		private void SetClockwiseGradient(float gradient)
		{
		}

		private void SetCounterClockwiseGradient(float gradient)
		{
		}
	}
}
public class GifCapture : VideoCapture
{
	private float lastGifCaptureTime;

	private float gifCaptureStartTime;

	private Coroutine gifExportCoroutine;

	private List<RenderTexture> gifCaptureTextures = new List<RenderTexture>();

	private string latestFilename;

	public ReadOnlyCollection<RenderTexture> GifRenderTextures => gifCaptureTextures.AsReadOnly();

	public override string ExportDirectory => base.ExportDirectory + "Gifs\\";

	public override void StartCapture()
	{
		if (gifExportCoroutine == null)
		{
			base.IsCapturing = true;
			gifCaptureStartTime = UnityEngine.Time.unscaledTime;
			lastGifCaptureTime = 0f;
			gifCaptureTextures.Clear();
			FireCaptureStartedEvent();
		}
	}

	public override void FinishCapture()
	{
		if (base.IsCapturing)
		{
			base.IsCapturing = false;
		}
		latestFilename = VideoCapture.CurrentFileName;
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		float result = 0f;
		if (base.IsCapturing)
		{
			if (UnityEngine.Time.unscaledTime - lastGifCaptureTime >= capturePeriod)
			{
				lastGifCaptureTime = UnityEngine.Time.unscaledTime;
				RenderTexture temporary = RenderTexture.GetTemporary(frame.width, frame.height, 0);
				Graphics.Blit(frame, temporary);
				gifCaptureTextures.Add(temporary);
			}
			result = (UnityEngine.Time.unscaledTime - gifCaptureStartTime) / maxDuration;
		}
		return result;
	}

	public override void SaveToDisk()
	{
		if (gifExportCoroutine != null)
		{
			StopCoroutine(gifExportCoroutine);
		}
		gifExportCoroutine = StartCoroutine(GifExportCoroutine());
	}

	private IEnumerator GifExportCoroutine()
	{
		FireExportStartedEvent();
		if (!File.Exists(ExportDirectory + latestFilename + ".gif"))
		{
			MemoryStream memStream = new MemoryStream();
			yield return CaptureTheGIF.Instance.MakeGif(gifCaptureTextures, capturePeriod, memStream, closeWhenDone: false);
			FileStream file = CaptureTheGIF.MakeFile(ExportDirectory, latestFilename);
			try
			{
				Thread thread = new Thread((ThreadStart)delegate
				{
					memStream.WriteTo(file);
					file.Flush();
					file.Close();
				});
				thread.Start();
				while (thread.ThreadState == ThreadState.Running)
				{
					yield return null;
				}
			}
			finally
			{
				if (file != null)
				{
					((IDisposable)file).Dispose();
				}
			}
		}
		FireExportFinishedEvent(latestFilename);
		gifExportCoroutine = null;
	}
}
public class MP4Capture : VideoCapture
{
	[Header("MP4")]
	[SerializeField]
	private Material blitMaterial;

	[SerializeField]
	private int videoBitrateMBPS = 8;

	private fcAPI.fcMP4Context mp4Context;

	private fcAPI.fcStream mp4OutputStream;

	private fcAPI.fcMP4Config mp4Config = fcAPI.fcMP4Config.default_value;

	private int videoId;

	private float captureStartTime;

	private string latestFilename;

	private string latestFullTempFilename;

	private RenderTexture scratchBuffer;

	private AudioSource localMicCaptureSource;

	private float[] micAudio;

	private float[] audioMixBuffer;

	private float fullRenderScale;

	private AudioListenerSingleton audioListener;

	public string CurrentVideoUrl = string.Empty;

	private static string CurrentTempFilename => UnityEngine.Application.temporaryCachePath + VideoCapture.CurrentFileName;

	public override string ExportDirectory => base.ExportDirectory + "Videos\\";

	protected override void Awake()
	{
		base.Awake();
	}

	protected override void Start()
	{
		base.Start();
		if (SingletonMonoBehaviour<SettingsManager>.Instance.H264Plugin)
		{
			audioListener = SingletonMonoBehaviour<AudioListenerSingleton>.Instance;
			if (audioListener != null)
			{
				audioListener.AudioFilter += OnMainAudioFilter;
			}
			localMicCaptureSource = base.gameObject.AddComponent<AudioSource>();
			localMicCaptureSource.clip = SharedMicrophone.GetMicrophone(PhotonVoiceNetwork.MicrophoneDevice, (int)PhotonVoiceSettings.Instance.SamplingRate);
			localMicCaptureSource.loop = true;
			fcAPI.fcMP4SetFAACPackagePath(UnityEngine.Application.streamingAssetsPath + "/UTJ/FrameCapturer/FAAC_SelfBuild.zip");
			fcAPI.fcMP4SetFAACUnzipPath(UnityEngine.Application.dataPath);
			fcAPI.fcSetModulePath(UnityEngine.Application.temporaryCachePath);
			fcAPI.fcMP4DownloadCodecBegin();
		}
		else
		{
			base.enabled = false;
		}
	}

	private void OnDestroy()
	{
		if (audioListener != null)
		{
			AttachAudioListener(attachToRecorder: false);
			audioListener.AudioFilter -= OnMainAudioFilter;
		}
	}

	public override void StartCapture()
	{
		if (!SingletonMonoBehaviour<SettingsManager>.Instance.H264Plugin || !base.enabled)
		{
			WorldSpaceNotification.PlayNext("Video camera is disabled! (check SETTINGS)", 1f, null, followPlayer: false, base.transform.position + Vector3.up * 0.1f, 0.1f);
			return;
		}
		fullRenderScale = Mathf.Max(1f, XRSettings.eyeTextureResolutionScale);
		XRSettings.eyeTextureResolutionScale = fullRenderScale / 2f;
		if (!base.IsCapturing)
		{
			base.IsCapturing = true;
			captureStartTime = UnityEngine.Time.unscaledTime;
			CurrentVideoUrl = string.Empty;
			InitializeContext();
			InitializeScratchBuffer();
			AttachAudioListener(attachToRecorder: true);
			localMicCaptureSource.Play();
			FireCaptureStartedEvent();
		}
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		float result = 0f;
		if (base.IsCapturing)
		{
			Graphics.Blit(frame, scratchBuffer, blitMaterial);
			videoId = fcAPI.fcMP4AddVideoFrameTexture(mp4Context, scratchBuffer, UnityEngine.Time.unscaledTime, videoId);
			GL.IssuePluginEvent(fcAPI.fcGetRenderEventFunc(), videoId);
			result = (UnityEngine.Time.unscaledTime - captureStartTime) / maxDuration;
		}
		return result;
	}

	public override void FinishCapture()
	{
		if (base.IsCapturing)
		{
			base.IsCapturing = false;
			ReleaseContext();
			localMicCaptureSource.Stop();
			AttachAudioListener(attachToRecorder: false);
		}
		XRSettings.eyeTextureResolutionScale = Mathf.Max(1f, fullRenderScale);
		CurrentVideoUrl = latestFullTempFilename;
	}

	public override void SaveToDisk()
	{
		FireExportStartedEvent();
		if (!File.Exists(GetFullFilename(latestFilename)))
		{
			File.Copy(latestFullTempFilename, GetFullFilename(latestFilename));
		}
		FireExportFinishedEvent(latestFilename);
	}

	private void AttachAudioListener(bool attachToRecorder)
	{
		if (audioListener != null)
		{
			if (attachToRecorder)
			{
				audioListener.transform.parent = RecordingCamera.transform;
				audioListener.transform.localPosition = Vector3.zero;
				audioListener.transform.localRotation = Quaternion.identity;
				audioListener.transform.localScale = Vector3.one;
			}
			else
			{
				SingletonMonoBehaviour<CameraRig>.Instance.AttachTransformToActiveCamera(audioListener.transform);
			}
		}
	}

	private void OnMainAudioFilter(float[] samples, int channels)
	{
		if (base.IsCapturing && channels == mp4Config.audio_num_channels)
		{
			if (audioMixBuffer == null || audioMixBuffer.Length != samples.Length)
			{
				audioMixBuffer = new float[samples.Length];
			}
			if (micAudio == null || micAudio.Length != samples.Length)
			{
				micAudio = new float[samples.Length];
			}
			for (int i = 0; i < samples.Length; i++)
			{
				audioMixBuffer[i] = samples[i] + micAudio[i] / 2f;
			}
			fcAPI.fcMP4AddAudioFrame(mp4Context, audioMixBuffer, audioMixBuffer.Length);
		}
	}

	private void OnAudioFilterRead(float[] samples, int channels)
	{
		if (micAudio == null || micAudio.Length != samples.Length)
		{
			micAudio = new float[samples.Length];
		}
		Array.Copy(samples, micAudio, samples.Length);
		Array.Clear(samples, 0, samples.Length);
	}

	private void InitializeContext()
	{
		mp4Config = fcAPI.fcMP4Config.default_value;
		mp4Config.audio = true;
		mp4Config.audio_bitrate = 64000;
		mp4Config.audio_sampling_rate = AudioSettings.outputSampleRate;
		mp4Config.audio_num_channels = fcAPI.fcGetNumAudioChannels();
		mp4Config.video = true;
		mp4Config.video_height = RecordingCamera.targetTexture.height;
		mp4Config.video_width = RecordingCamera.targetTexture.width;
		mp4Config.video_max_framerate = frameRate;
		mp4Config.video_bitrate = videoBitrateMBPS * 1024 * 1024;
		mp4Context = fcAPI.fcMP4CreateContext(ref mp4Config);
		latestFilename = VideoCapture.CurrentFileName;
		latestFullTempFilename = GetFullFilename(CurrentTempFilename);
		mp4OutputStream = fcAPI.fcCreateFileStream(latestFullTempFilename);
		fcAPI.fcMP4AddOutputStream(mp4Context, mp4OutputStream);
	}

	private void InitializeScratchBuffer()
	{
		if (scratchBuffer != null)
		{
			if (scratchBuffer.IsCreated() && scratchBuffer.width == mp4Config.video_width && scratchBuffer.height == mp4Config.video_height)
			{
				return;
			}
			ReleaseScratchBuffer();
		}
		scratchBuffer = new RenderTexture(mp4Config.video_width, mp4Config.video_height, 0, RenderTextureFormat.ARGB32);
		scratchBuffer.wrapMode = TextureWrapMode.Repeat;
		scratchBuffer.Create();
	}

	private void ReleaseContext()
	{
		fcAPI.fcGuard(delegate
		{
			fcAPI.fcEraseDeferredCall(videoId);
			videoId = 0;
			if (mp4Context.ptr != IntPtr.Zero)
			{
				fcAPI.fcMP4DestroyContext(mp4Context);
				mp4Context.ptr = IntPtr.Zero;
			}
			if (mp4OutputStream.ptr != IntPtr.Zero)
			{
				fcAPI.fcDestroyStream(mp4OutputStream);
				mp4OutputStream.ptr = IntPtr.Zero;
			}
		});
	}

	private void ReleaseScratchBuffer()
	{
		if (scratchBuffer != null)
		{
			scratchBuffer.Release();
			scratchBuffer = null;
		}
	}

	private string GetFullFilename(string filename)
	{
		return Path.Combine(ExportDirectory, filename + ".mp4");
	}
}
public class PngCapture : VideoCapture
{
	public override string ExportDirectory => base.ExportDirectory + "Pngs\\";

	public override void StartCapture()
	{
		base.IsCapturing = true;
		FireCaptureStartedEvent();
	}

	public override void FinishCapture()
	{
		base.IsCapturing = false;
	}

	public override float UpdateFrame(RenderTexture frame)
	{
		if (!base.IsCapturing)
		{
			return 0f;
		}
		base.IsCapturing = false;
		Texture2D texture2D = GetTexture2D(frame);
		SaveTexture2D(texture2D);
		UnityEngine.Object.Destroy(texture2D);
		return 1f;
	}

	public Texture2D GetTexture2D(RenderTexture frame)
	{
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = frame;
		Texture2D texture2D = new Texture2D(frame.width, frame.height, TextureFormat.ARGB32, mipmap: false);
		texture2D.ReadPixels(new Rect(0f, 0f, texture2D.width, texture2D.height), 0, 0);
		texture2D.Apply();
		RenderTexture.active = active;
		return texture2D;
	}

	public void SaveTexture2D(Texture2D texture)
	{
		FireExportStartedEvent();
		string fullFilename = GetFullFilename(VideoCapture.CurrentFileName);
		try
		{
			byte[] bytes = texture.EncodeToPNG();
			File.WriteAllBytes(fullFilename, bytes);
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
		}
		FireExportFinishedEvent(fullFilename);
	}

	public override void SaveToDisk()
	{
	}

	private string GetFullFilename(string filename)
	{
		return Path.Combine(ExportDirectory, filename + ".png");
	}
}
