				{
					buttonAction2 = buttonAction;
					buttonAction = Interlocked.CompareExchange(ref this.m_CanceledEvent, (ButtonAction)Delegate.Remove(buttonAction2, value), buttonAction);
				}
				while (buttonAction != buttonAction2);
			}
		}

		protected virtual float GetDesiredAxisValue()
		{
			if (ButtonPressed)
			{
				return PressAxisValue;
			}
			if (Interactable)
			{
				return 0f;
			}
			return DisabledAxisValue;
		}

		protected void UpdateButtonSelectionState()
		{
			SelectionState newSelectionState = GetNewSelectionState();
			if (newSelectionState != selectionState)
			{
				DoStateTransition(newSelectionState, instant: false);
			}
			selectionState = newSelectionState;
		}

		private SelectionState GetNewSelectionState()
		{
			if (!IsInteractable())
			{
				return SelectionState.Disabled;
			}
			if (ButtonPressed)
			{
				return SelectionState.Pressed;
			}
			if (IsHighlighted)
			{
				return SelectionState.Highlighted;
			}
			return SelectionState.Normal;
		}

		protected override void DoStateTransition(SelectionState state, bool instant)
		{
			base.DoStateTransition(state, instant);
			Color color = state switch
			{
				SelectionState.Normal => base.colors.normalColor, 
				SelectionState.Highlighted => base.colors.highlightedColor, 
				SelectionState.Pressed => base.colors.pressedColor, 
				SelectionState.Disabled => base.colors.disabledColor, 
				_ => Color.black, 
			};
			for (int i = 0; i < otherSelectionTargetGraphics.Count; i++)
			{
				if (otherSelectionTargetGraphics[i] != null)
				{
					otherSelectionTargetGraphics[i].CrossFadeColor(color * base.colors.colorMultiplier, (!instant) ? base.colors.fadeDuration : 0f, ignoreTimeScale: true, useAlpha: true);
				}
			}
		}

		protected override void Start()
		{
			base.Start();
			if (UIBase == null)
			{
				ui3dScaler.FetchRootCanvas();
			}
			else
			{
				ui3dScaler.ThisCanvas = UIBase.Canvas;
			}
			SetAxisValue(GetDesiredAxisValue());
			started = true;
			if (UnityEngine.Application.isPlaying)
			{
				base.gameObject.SetTagRecursively("Button3D");
			}
		}

		protected override void Awake()
		{
			Graphic[] componentsInChildren = object2d.GetComponentsInChildren<Graphic>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				if (componentsInChildren[i] != base.targetGraphic && componentsInChildren[i].GetComponent<IgnoreUIButtonHighlight>() == null)
				{
					otherSelectionTargetGraphics.Add(componentsInChildren[i]);
				}
			}
			Toggled = false;
			ui3dScaler = GetComponentInChildren<UI3DScaler>(includeInactive: true);
			if (ui3dScaler == null)
			{
				UnityEngine.Debug.LogError("3D Button " + base.name + " is missing 3d scalar.");
			}
			collider3D = ui3dScaler.GetComponentInChildren<BoxCollider>();
			if (collider3D == null)
			{
				UnityEngine.Debug.LogError("3D Button " + base.name + " is missing a collider.");
			}
			else
			{
				Collider3DSize = ((!ButtonPressed) ? 1f : 1.5f);
			}
			Navigation navigation = base.navigation;
			navigation.mode = Navigation.Mode.None;
			base.navigation = navigation;
			if (UnityEngine.Application.isPlaying && toastId != ToastIds.None)
			{
				CreateToast();
			}
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			lastPressTime = UnityEngine.Time.realtimeSinceStartup;
			if (started)
			{
				SetAxisValue(GetDesiredAxisValue(), force: true);
			}
		}

		protected override void OnDisable()
		{
			base.OnDisable();
			ReleaseMenuFinger(forceCancel: true);
		}

		protected virtual void Update()
		{
			if (MenuFinger != null && Interactable && MenuFinger.isLocal)
			{
				if (UIBase != null && !UIBase.CanInteract(this))
				{
					return;
				}
				if (!MenuFinger.gameObject.activeInHierarchy)
				{
					ReleaseMenuFinger();
				}
				else if (!(UnityEngine.Time.realtimeSinceStartup - lastPressTime < 0.3f))
				{
					Vector3 position = MenuFinger.FingertipTransform.position;
					Vector3 vector = base.transform.InverseTransformPoint(position);
					float axisValue = constraints.GetAxisValue(vector.z);
					if (axisValue != cachedAxisValue)
					{
						UpdateButtonPress(axisValue);
						SetAxisValue(axisValue);
					}
				}
			}
			else
			{
				UpdateButtonWithoutMenuFinger();
				Vector3 localPosition = object2d.transform.localPosition;
				DesiredAxisValue = GetDesiredAxisValue();
				float axisValue2 = constraints.GetAxisValue(localPosition.z);
				if (Mathf.Abs(axisValue2 - DesiredAxisValue) > 0.001f)
				{
					float newAxisValue = Mathf.Lerp(axisValue2, DesiredAxisValue, buttonMoveTime);
					SetAxisValue(newAxisValue);
					isAtDesiredAxisValue = false;
				}
				else if (!isAtDesiredAxisValue)
				{
					SetAxisValue(DesiredAxisValue);
					isAtDesiredAxisValue = true;
				}
				buttonMoveTime += UnityEngine.Time.deltaTime * buttonMoveSpeed;
			}
		}

		private void CreateToast()
		{
			GameObject original = Resources.Load("[Toast]") as GameObject;
			toast = UnityEngine.Object.Instantiate(original, object2d.transform, worldPositionStays: false).GetComponent<Toast>();
			toast.ToastId = toastId;
			if (toastId == ToastIds.NewRoom)
			{
				Vector3 localPosition = toast.transform.localPosition;
				localPosition.y /= 5f;
				toast.transform.localPosition = localPosition;
			}
		}

		public virtual void SetAxisValue(float newAxisValue, bool force = false)
		{
			if (object2d != null && (force || newAxisValue != cachedAxisValue))
			{
				cachedAxisValue = newAxisValue;
				float offset = constraints.GetOffset(newAxisValue);
				float num = Mathf.Lerp(1f, MaxSquashScale, newAxisValue);
				Vector3 localPosition = object2d.transform.localPosition;
				localPosition.z = offset;
				object2d.transform.localPosition = localPosition;
				Vector3 localScale = object2d.transform.localScale;
				localScale.x = num;
				localScale.y = num;
				object2d.transform.localScale = localScale;
				if (ui3dScaler != null)
				{
					ui3dScaler.Refresh();
				}
				float colliderHeight = constraints.GetOffset(0f) / offset;
				SetColliderHeight(colliderHeight);
			}
		}

		private void SetColliderHeight(float colliderScale)
		{
			if (collider3D != null && !float.IsNaN(colliderScale))
			{
				Vector3 size = collider3D.size;
				size.y = Collider3DSize * colliderScale;
				collider3D.size = size;
			}
		}

		private void UpdateButtonWithoutMenuFinger()
		{
			if (ButtonPressed != PointerPressed)
			{
				ButtonPressed = PointerPressed;
			}
		}

		private void UpdateButtonPress(float buttonAxis)
		{
			if (ButtonPressed)
			{
				if (buttonAxis < ReleaseAxisValue)
				{
					ButtonPressed = false;
				}
			}
			else if (buttonAxis > PressAxisValue)
			{
				ButtonPressed = true;
			}
		}

		protected virtual void PhysicalButtonDownEvent(bool forcedPress = false)
		{
			if (!forcedPress)
			{
				if (MenuFinger != null && MenuFinger.InputHandler != null)
				{
					MenuFinger.InputHandler.Vibrate(10, 0.5f);
				}
				OnButtonDownAudio();
			}
			if (this.DownEvent != null)
			{
				this.DownEvent(this);
			}
		}

		protected virtual void PhysicalButtonUpEvent(bool forcedPress = false)
		{
			if (!forcedPress)
			{
				if (MenuFinger != null && MenuFinger.InputHandler != null)
				{
					MenuFinger.InputHandler.Vibrate(10, 0.5f);
				}
				OnButtonUpAudio();
			}
			if (this.UpEvent != null)
			{
				this.UpEvent(this);
			}
		}

		protected virtual void PhysicalButtonCanceledEvent()
		{
			if (this.CanceledEvent != null)
			{
				this.CanceledEvent(this);
			}
		}

		public void TrySetMenuFinger(MenuFinger menuFinger)
		{
			if (MenuFinger == null)
			{
				MenuFinger = menuFinger;
			}
		}

		public void TryReleaseMenuFinger(MenuFinger menuFinger)
		{
			if (MenuFinger == menuFinger)
			{
				ReleaseMenuFinger();
			}
		}

		protected void ReleaseMenuFinger(bool forceCancel = false)
		{
			MenuFinger = null;
			buttonMoveTime = 0f;
			CancelButtonPress(forceCancel);
		}

		public override void OnPointerDown(PointerEventData eventData)
		{
			base.OnPointerDown(eventData);
			if (Interactable)
			{
				PointerPressed = true;
			}
		}

		public override void OnPointerUp(PointerEventData eventData)
		{
			base.OnPointerUp(eventData);
			if (Interactable && eventData.button == PointerEventData.InputButton.Left)
			{
				PointerPressed = false;
			}
		}

		public void ForcePressed()
		{
			if (IsActive() && Interactable && !(UIBase == null))
			{
				PhysicalButtonDownEvent(forcedPress: true);
				PhysicalButtonUpEvent(forcedPress: true);
				UpdateButtonSelectionState();
			}
		}

		protected void CancelButtonPress(bool forceCancel = false)
		{
			if (ButtonPressed && (forceCancel || UnityEngine.Time.realtimeSinceStartup - lastPressTime > hairTriggerCancelThreshold))
			{
				_buttonCancelled = true;
			}
			PointerPressed = false;
			ButtonPressed = false;
		}

		public override void OnPointerEnter(PointerEventData eventData)
		{
			pointerInside = true;
			UpdateButtonSelectionState();
		}

		public override void OnPointerExit(PointerEventData eventData)
		{
			pointerInside = false;
			if (PointerPressed)
			{
				CancelButtonPress();
			}
			UpdateButtonSelectionState();
		}

		protected void OnButtonDownAudio()
		{
			if (ButtonDownAudio != null)
			{
				Transform followTarget = ((!(uiBase != null)) ? base.transform : uiBase.transform);
				AudioManager.Play3DSFX(ButtonDownAudio, followTarget);
			}
		}

		protected void OnButtonUpAudio()
		{
			if (ButtonUpAudio != null)
			{
				Transform followTarget = ((!(uiBase != null)) ? base.transform : uiBase.transform);
				AudioManager.Play3DSFX(ButtonUpAudio, followTarget);
			}
		}
	}
	public abstract class ClickableButton : Button3DBase
	{
		public bool SelectOnClick = true;

		protected abstract bool CanInteract();

		protected void OnButtonAction(bool forced = false)
		{
			if (forced || base.UIBase == null || (base.UIBase.CanInteract(this) && CanInteract()))
			{
				if (SelectOnClick)
				{
					EventSystem.current.SetSelectedGameObject(base.gameObject);
				}
				OnButtonActionInternal();
			}
		}

		protected abstract void OnButtonActionInternal();
	}
	public abstract class ClickableReleaseButton : ClickableButton
	{
		protected override void PhysicalButtonUpEvent(bool forcedPress)
		{
			base.PhysicalButtonUpEvent(forcedPress);
			OnButtonAction(forcedPress);
		}
	}
	public abstract class ClickablePressButton : ClickableButton
	{
		protected override void PhysicalButtonDownEvent(bool forcedPress)
		{
			base.PhysicalButtonDownEvent(forcedPress);
			OnButtonAction(forcedPress);
		}
	}
