namespace RecRoom
{
	public class IntRangeUIRotator : UIRotator
	{
		[SerializeField]
		protected int start;

		[SerializeField]
		protected int end;

		[SerializeField]
		protected string intFormat;

		[SerializeField]
		private string unselectedString = "--";

		protected List<int> intValues = new List<int>();

		public int? Value
		{
			get
			{
				if (Count > 0 && base.Index >= 0 && base.Index < intValues.Count)
				{
					return intValues[base.Index];
				}
				return null;
			}
		}

		public override int Count => intValues.Count;

		protected override void GenerateValues(int defaultIndex = -1)
		{
			int? value = Value;
			int num = base.Index;
			base.GenerateValues();
			intValues.Clear();
			for (int i = start; i <= end; i++)
			{
				intValues.Add(i);
			}
			if (value.HasValue)
			{
				if (intValues.Contains(value.Value))
				{
					base.Index = intValues.IndexOf(value.Value);
				}
				else if (value.Value > intValues.Max())
				{
					base.Index = intValues.Count - 1;
				}
				else
				{
					base.Index = defaultIndex;
				}
			}
			else
			{
				base.Index = defaultIndex;
			}
		}

		protected override void SetText()
		{
			if (base.Index >= 0 && base.Index < intValues.Count)
			{
				string text = ((!string.IsNullOrEmpty(intFormat)) ? string.Format(intFormat, Value) : Value.ToString());
				selectorText.text = text;
			}
			else
			{
				selectorText.text = unselectedString;
			}
		}
	}
	public class MonthDaysUIRotator : IntRangeUIRotator
	{
		[SerializeField]
		private IntRangeUIRotator monthRotator;

		[SerializeField]
		private IntRangeUIRotator yearPrefixRotator;

		[SerializeField]
		private IntRangeUIRotator yearSuffixRotator;

		protected override void GenerateValues(int defaultIndex = -1)
		{
			int? value = monthRotator.Value;
			int? num = AgeCheckUIDialog.YearCalc(yearPrefixRotator.Value, yearSuffixRotator.Value);
			start = 1;
			if (value.HasValue && num.HasValue)
			{
				end = DateTime.DaysInMonth(num.Value, value.Value);
			}
			else
			{
				end = 31;
			}
			base.GenerateValues(defaultIndex);
		}
	}
	public class MonthUIRotator : IntRangeUIRotator
	{
		[SerializeField]
		private List<string> Months = new List<string>();

		protected override void GenerateValues(int defaultIndex = -1)
		{
			start = 1;
			end = Months.Count;
			base.GenerateValues(defaultIndex);
		}

		protected override void SetText()
		{
			if (base.Index >= 0 && base.Index < intValues.Count)
			{
				string arg = ((!string.IsNullOrEmpty(intFormat)) ? string.Format(intFormat, base.Value) : base.Value.ToString());
				selectorText.text = $"{Months[base.Index]} ({arg})";
			}
			else
			{
				base.SetText();
			}
		}
	}
