	[ExecuteInEditMode]
	public abstract class UIRotator : UnityEngine.MonoBehaviour
	{
		[Serializable]
		private class UIRotatorValueChangedEvent : UnityEvent<UIRotator>
		{
		}

		[SerializeField]
		protected Text selectorText;

		[SerializeField]
		protected Selectable focusableElement;

		[SerializeField]
		private UIRotatorValueChangedEvent valueChangedEvent;

		private int index;

		[SerializeField]
		protected int resetIndex = -1;

		public int Index
		{
			get
			{
				return index;
			}
			set
			{
				if (index != value)
				{
					index = value;
					valueChangedEvent.DoIfNotNull(delegate(UIRotatorValueChangedEvent _)
					{
						_.Invoke(this);
					});
					SetText();
				}
			}
		}

		public abstract int Count { get; }

		private void Awake()
		{
			Regen();
			Reset();
		}

		public void Regen()
		{
			GenerateValues();
		}

		public void Select()
		{
			if (focusableElement != null)
			{
				focusableElement.Select();
			}
		}

		protected virtual void GenerateValues(int defaultIndex = -1)
		{
			Index = defaultIndex;
		}

		public void RandomValue()
		{
			if (Count > 0)
			{
				Index = UnityEngine.Random.Range(0, Count);
			}
		}

		protected abstract void SetText();

		public void Reset()
		{
			Index = -1;
		}

		[SkipRename]
		public void Button_Next()
		{
			if (Count > 0)
			{
				Index = (Index + 1) % Count;
			}
			else
			{
				Index = 0;
			}
		}

		[SkipRename]
		public void Button_Previous()
		{
			if (Count > 0)
			{
				int num = Mathf.Max(Index, 0);
				Index = (num - 1 + Count) % Count;
			}
			else
			{
				Index = 0;
			}
		}
	}
	public class YearSuffixUIRotator : IntRangeUIRotator
	{
		[SerializeField]
		private IntRangeUIRotator yearPrefixRotator;

		protected override void GenerateValues(int defaultIndex = 0)
		{
			start = 0;
			if (yearPrefixRotator.Value == 19)
			{
				end = 99;
			}
			else if (yearPrefixRotator.Value == 20)
			{
				end = DateTime.Now.Year % 100;
			}
			base.GenerateValues(0);
		}
	}
}
