public abstract class EnumSlider<T> : UnityEngine.MonoBehaviour where T : struct, IConvertible
{
	[Autofill(AutofillType.Children, false)]
	[SerializeField]
	private Slider3D slider;

	[SerializeField]
	private T[] options;

	public T Value
	{
		get
		{
			int num = (int)slider.value;
			if (num >= 0 && num < options.Length)
			{
				return options[num];
			}
			return options[0];
		}
		set
		{
			int num = options.FindIndex(value);
			if (num >= 0)
			{
				slider.value = num;
				return;
			}
			UnityEngine.Debug.LogErrorFormat("No index found for slider option {0}", value);
		}
	}

	public bool Interactable
	{
		get
		{
			return slider.Interactable;
		}
		set
		{
			slider.Interactable = value;
		}
	}
