namespace RecRoom
{
	public class Delayed3DUIObjectSpawner : UnityEngine.MonoBehaviour
	{
		private Action<Transform> onBecameFullyVisible;

		private StackedUIBase _uiBase;

		public StackedUIBase UIBase
		{
			get
			{
				return _uiBase;
			}
			private set
			{
				if (_uiBase != null)
				{
					_uiBase.FullyVisibleChanged -= VisibilityChanged;
				}
				_uiBase = value;
				if (_uiBase != null && !_uiBase.FullyVisible)
				{
					_uiBase.FullyVisibleChanged += VisibilityChanged;
				}
			}
		}

		public void Initialize(StackedUIBase uiBase, Action<Transform> onBecameFullyVisible)
		{
			UIBase = uiBase;
			this.onBecameFullyVisible = onBecameFullyVisible;
			VisibilityChanged(UIBase.FullyVisible);
		}

		private void OnDestroy()
		{
			UIBase = null;
		}

		private void VisibilityChanged(bool isFullyVisible)
		{
			if (isFullyVisible)
			{
				onBecameFullyVisible.SafeInvoke(base.transform);
				onBecameFullyVisible = null;
				UIBase = null;
			}
		}
	}
}
