	public int CurrentPage
	{
		get
		{
			return currentPage;
		}
		set
		{
			if (currentPage != value)
			{
				currentPage = value;
				Validate();
				NotifyChanged();
			}
		}
	}

	public int TotalItems => (source != null) ? source.Count() : 0;

	public int CurrentItem => Math.Min(TotalItems, (currentPage + 1) * itemsPerPage);

	public int TotalPages
	{
		get
		{
			int totalItems = TotalItems;
			if (totalItems == 0)
			{
				return 1;
			}
			int num = totalItems / itemsPerPage;
			int num2 = ((totalItems % itemsPerPage != 0) ? 1 : 0);
			return num + num2;
		}
	}

	public event Action Changed
	{
		add
		{
			Action action = this.Changed;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.Changed, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.Changed;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.Changed, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public PagedList(IEnumerable<T> source = null, int itemsPerPage = 10)
	{
		this.source = source;
		this.itemsPerPage = itemsPerPage;
	}

	public IEnumerable<T> GetPage()
	{
		Validate();
		return source.SkipTake(currentPage * itemsPerPage, itemsPerPage);
	}

	private void Validate()
	{
		currentPage = Math.Min(currentPage, TotalPages - 1);
	}

	private void NotifyChanged()
	{
		if (this.Changed != null)
		{
			this.Changed();
		}
	}
}
