public class CustomUIMask : UnityEngine.MonoBehaviour
{
	private enum MaskMode
	{
		RENDER_WHERE_MASK_EXISTS,
		RENDER_WHERE_MASK_DOES_NOT_EXIST
	}

	[Header("Masking Settings")]
	[SerializeField]
	public StencilLayer stencilLayer = StencilLayer.UI_BUTTON_MASK;

	[SerializeField]
	private MaskMode maskMode;

	private Material[] materialInstances;

	private float StencilComparison => maskMode switch
	{
		MaskMode.RENDER_WHERE_MASK_EXISTS => 3f, 
		MaskMode.RENDER_WHERE_MASK_DOES_NOT_EXIST => 6f, 
		_ => 0f, 
	};

	private void Awake()
	{
		int num = Mathf.Clamp(1 << (int)stencilLayer, 0, 255);
		MaskableGraphic[] componentsInChildren = GetComponentsInChildren<MaskableGraphic>(includeInactive: true);
		materialInstances = new Material[componentsInChildren.Length];
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			Material material = componentsInChildren[i].material;
			materialInstances[i] = UnityEngine.Object.Instantiate(material);
			ConfigureMaterialInstance(materialInstances[i], num);
			componentsInChildren[i].material = materialInstances[i];
		}
	}

	private void ConfigureMaterialInstance(Material material, float mask)
	{
		material.SetFloat(ShaderIDs.STENCIL_VALUE, 255f);
		material.SetFloat(ShaderIDs.STENCIL_COMPARISON, StencilComparison);
		material.SetFloat(ShaderIDs.STENCIL_READ_MASK, mask);
		material.SetFloat(ShaderIDs.STENCIL_WRITE_MASK, mask);
	}

	private void OnDestroy()
	{
		if (materialInstances != null)
		{
			Material[] array = materialInstances;
			foreach (Material obj in array)
			{
				UnityEngine.Object.Destroy(obj);
			}
		}
	}
}
