public class CameraTransform
{
	public enum CameraType
	{
		Unspecified,
		StreamPoint,
		FirstPerson,
		ThirdPerson,
		ThirdPersonTeleportOnly,
		ThirdPersonFace,
		Handheld
	}

	public Quaternion RotationOffset = Quaternion.identity;

	public CameraType Type;

	public bool IsLocalPlayer;

	private bool _updateTransformOnlyOnTeleport;

	private Vector3 savedPosition;

	private Quaternion savedRotation;

	public bool FollowsLocalPlayer { get; set; }

	public Transform Transform { get; set; }

	public Vector3 PositionOffset { get; set; }

	public bool HideCameraMesh { get; set; }

	public bool CullFirstPersonAvatar { get; set; }

	public bool IgnoreCameraRoll { get; set; }

	public float? FOVOverride { get; set; }

	public float? PositionSmoothingTimeOverride { get; set; }

	public AnimationCurve PositionSmoothingTimeMultiplierByDistance { get; set; }

	public float? RotationSmoothingTimeOverride { get; set; }

	public bool UpdateTransformOnlyOnTeleport
	{
		get
		{
			return _updateTransformOnlyOnTeleport;
		}
		set
		{
			_updateTransformOnlyOnTeleport = value;
			if (value && Player.LocalPlayerExists && FollowsLocalPlayer)
			{
				Player.LocalPlayer.PlayerEvents.TeleportEvent += UpdateTransform;
				Player.LocalPlayerSpawnEvent += new Action(UpdateTransform);
				SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.StreamingCameraModeChanged += StreamingCameraModeChanged;
			}
		}
	}

	public string Name { get; set; }

	public bool IsValid => Transform != null;

	public bool IsPreviewed { get; set; }

	private void StreamingCameraModeChanged(StreamingCameraController.StreamingCameraMode mode)
	{
		if (mode == StreamingCameraController.StreamingCameraMode.ON)
		{
			UpdateTransform();
		}
	}

	public void GetTransform(out Vector3 position, out Quaternion rotation)
	{
		rotation = ((!UpdateTransformOnlyOnTeleport) ? (Transform.rotation * RotationOffset) : savedRotation);
		position = ((!UpdateTransformOnlyOnTeleport) ? (Transform.position + rotation * PositionOffset) : savedPosition);
	}

	private void UpdateTransform()
	{
		if (UpdateTransformOnlyOnTeleport && FollowsLocalPlayer && Transform != null)
		{
			savedRotation = Quaternion.LookRotation(Vector3.ProjectOnPlane(Transform.forward, Vector3.up));
			savedPosition = Transform.position + savedRotation * PositionOffset;
		}
	}
}
public class SpectatorWatchUIFlow : WatchUIFlow
{
	[Serializable]
	private struct SliderToFrameRateSetting
	{
		public string name;

		public int SliderValue;

		public StreamingCameraController.FrameRates frameRate;
	}

	[Serializable]
	private struct SliderToFOVSetting
	{
		public string name;

		public int SliderValue;

		public StreamingCameraController.FOVs fov;
	}

	[Serializable]
	private struct SliderToGreenScreenSetting
	{
		public string name;

		public int SliderValue;

		public StreamingCameraController.GreenScreenModes mode;
	}

	[Header("SpectatorWatchUIFlow")]
	public RawImage StreamerCamMainImage;

	public Text CurrentPreviewName;

	[SerializeField]
	private Vector2 previewResolution = new Vector2(240f, 180f);

	[SerializeField]
	private Texture2D streamNotAvailableTexture;

	[SerializeField]
	private Texture2D selectStreamTexture;

	[Header("Frame rate Settings Slider Mappings")]
	[SerializeField]
	private SliderToFrameRateSetting[] sliderToFrameRateSettings;

	[Header("FOV Settings Slider Mappings")]
	[SerializeField]
	private SliderToFOVSetting[] sliderToFOVSettings;

	[Header("Green Screen Settings Slider Mappings")]
	[SerializeField]
	private SliderToGreenScreenSetting[] sliderToGreenScreenSettings;

	[SerializeField]
	private Slider3D fpsSlider;

	[SerializeField]
	private Slider3D fovSlider;

	[SerializeField]
	private Slider3D audioListenerPositionSlider;

	[SerializeField]
	private Slider3D greenScreenSlider;

	[SerializeField]
	private ToggleButton3D useHandheldToggle;

	[SerializeField]
	private GameObject handheldCameraPrefab;

	private Camera previewCamera;

	private SpectatorStreamPreviewScreen[] previewScreens;

	private int currentScreenIndex;

	private CameraTransform currentStreamerCamera;

	private Texture2D mainImageTexture;

	private SpectatorStreamPoint[] streamPoints;

	private static HandheldStreamerCamera handheldCamera;

	private static List<CameraTransform> cameraTransforms = new List<CameraTransform>();

	private bool otherPlayersHidden;

	private static CameraTransform.CameraType defaultCameraType = CameraTransform.CameraType.ThirdPerson;

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		cameraTransforms.Clear();
		previewCamera = GetComponentInChildren<Camera>(includeInactive: true);
		previewCamera.aspect = previewResolution.x / previewResolution.y;
		previewCamera.targetTexture = new RenderTexture((int)previewResolution.x, (int)previewResolution.y, 24);
		previewCamera.depthTextureMode = DepthTextureMode.Depth;
		Player.LocalPlayer.SetParentPlayerRoot(previewCamera.transform);
		StreamerCamMainImage.texture = selectStreamTexture;
		currentStreamerCamera = null;
		SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollowChanged += CurrentStreamingCamera_CameraTransformToFollowChanged;
		foreach (Player item in Player.All)
		{
			Player_OnPlayerCreated(item);
		}
		Player.PlayerCreatedEvent += new Action<Player>(Player_OnPlayerCreated);
		if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent += OnLocalPlayerTeamChange;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += OnGameStateChange;
		}
		UpdateCameraVisibility();
		AddSceneStreamPoints();
		fpsSlider.value = (from s in sliderToFrameRateSettings
			where s.frameRate == SingletonMonoBehaviour<StreamingCameraController>.Instance.FrameRate
			select s.SliderValue).FirstOrDefault();
		fovSlider.value = (from s in sliderToFOVSettings
			where s.fov == SingletonMonoBehaviour<StreamingCameraController>.Instance.FoV
			select s.SliderValue).FirstOrDefault();
		audioListenerPositionSlider.value = 0f;
		greenScreenSlider.value = 0f;
		previewScreens = GetComponentsInChildren<SpectatorStreamPreviewScreen>(includeInactive: true);
		for (int num = 0; num < previewScreens.Length; num++)
		{
			SpectatorStreamPreviewScreen spectatorStreamPreviewScreen = previewScreens[num];
			spectatorStreamPreviewScreen.ButtonPressedEvent += Screen_ButtonPressedEvent;
			spectatorStreamPreviewScreen.StreamButton.Interactable = false;
			AssignNextAvailableCameraTransform(spectatorStreamPreviewScreen, 1);
		}
	}

	private void CurrentStreamingCamera_CameraTransformToFollowChanged(CameraTransform cameraTransform)
	{
		if (cameraTransform == null)
		{
			currentStreamerCamera = null;
			CurrentPreviewName.text = "Select a stream";
		}
		else
		{
			currentStreamerCamera = cameraTransform;
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetMode(StreamingCameraController.StreamingCameraMode.ON, StreamingCameraController.InteractionSource.WatchUI);
			CurrentPreviewName.text = cameraTransform.Name + ":";
		}
	}

	private void Update()
	{
		if (!Player.LocalPlayerExists || !base.isActiveAndEnabled)
		{
			return;
		}
		if (SingletonMonoBehaviour<StreamingCameraController>.Instance != null && SingletonMonoBehaviour<StreamingCameraController>.Instance.StreamingCamera != null)
		{
			StreamerCamMainImage.texture = SingletonMonoBehaviour<StreamingCameraController>.Instance.StreamingCamera.activeTexture;
		}
		else if (currentStreamerCamera != null && currentStreamerCamera.IsValid && (currentStreamerCamera.FollowsLocalPlayer || !otherPlayersHidden))
		{
			RenderPreview(currentStreamerCamera, ref mainImageTexture);
			StreamerCamMainImage.texture = mainImageTexture;
		}
		else
		{
			StreamerCamMainImage.texture = streamNotAvailableTexture;
		}
		SpectatorStreamPreviewScreen spectatorStreamPreviewScreen = previewScreens[currentScreenIndex];
		if (spectatorStreamPreviewScreen.CameraTransform != null)
		{
			if (spectatorStreamPreviewScreen.CameraTransform.IsValid && (spectatorStreamPreviewScreen.CameraTransform.FollowsLocalPlayer || !otherPlayersHidden))
			{
				RenderPreview(spectatorStreamPreviewScreen.CameraTransform, ref spectatorStreamPreviewScreen.TargetTexture, square: true);
				spectatorStreamPreviewScreen.TargetImage.texture = spectatorStreamPreviewScreen.TargetTexture;
				spectatorStreamPreviewScreen.StreamButton.Interactable = true;
			}
			else if (otherPlayersHidden && !spectatorStreamPreviewScreen.CameraTransform.FollowsLocalPlayer)
			{
				spectatorStreamPreviewScreen.TargetImage.texture = streamNotAvailableTexture;
				spectatorStreamPreviewScreen.StreamButton.Interactable = false;
			}
			else
			{
				spectatorStreamPreviewScreen.CameraTransform = null;
				spectatorStreamPreviewScreen.TargetImage.texture = streamNotAvailableTexture;
				spectatorStreamPreviewScreen.StreamButton.Interactable = false;
			}
		}
		currentScreenIndex = ++currentScreenIndex % previewScreens.Length;
	}

	private void RenderPreview(CameraTransform camera, ref Texture2D texture, bool square = false)
	{
		camera.GetTransform(out var position, out var rotation);
		previewCamera.transform.position = position;
		previewCamera.transform.rotation = rotation;
		previewCamera.Render();
		previewCamera.targetTexture.GetTexture2D(ref texture, square);
	}

	private void OnEnable()
	{
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.Mode == StreamingCameraController.StreamingCameraMode.ON)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow != null)
			{
				CurrentStreamingCamera_CameraTransformToFollowChanged(SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow);
			}
			else
			{
				CurrentStreamingCamera_CameraTransformToFollowChanged(SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.DefaultCameraTransformToFollow);
			}
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (handheldCamera != null)
		{
			handheldCamera.Tool.InputDownEvent -= OnHandheldCameraInputDown;
		}
		Player.PlayerCreatedEvent -= new Action<Player>(Player_OnPlayerCreated);
		if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.LocalPlayerTeamChangeEvent -= OnLocalPlayerTeamChange;
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent -= OnGameStateChange;
		}
		if (SingletonMonoBehaviour<SettingsManager>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCameraExists)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollowChanged -= CurrentStreamingCamera_CameraTransformToFollowChanged;
		}
	}

	private void Player_OnPlayerCreated(Player player)
	{
		if (player.isLocal)
		{
			CameraTransform cameraTransform = new CameraTransform();
			cameraTransform.IsLocalPlayer = true;
			cameraTransform.FollowsLocalPlayer = true;
			cameraTransform.Transform = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform;
			cameraTransform.PositionOffset = Vector3.forward * 0.15f;
			cameraTransform.UpdateTransformOnlyOnTeleport = false;
			cameraTransform.Name = player.PlayerName + " (POV)";
			cameraTransform.HideCameraMesh = true;
			cameraTransform.CullFirstPersonAvatar = true;
			cameraTransform.FOVOverride = 65f;
			cameraTransform.Type = CameraTransform.CameraType.FirstPerson;
			CameraTransform item = cameraTransform;
			cameraTransforms.Add(item);
			cameraTransform = new CameraTransform();
			cameraTransform.IsLocalPlayer = true;
			cameraTransform.FollowsLocalPlayer = true;
			cameraTransform.Transform = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform;
			cameraTransform.PositionOffset = Vector3.forward * -1.2f + Vector3.up * 0.05f + Vector3.right * 0.2f;
			cameraTransform.UpdateTransformOnlyOnTeleport = false;
			cameraTransform.IgnoreCameraRoll = true;
			cameraTransform.Name = player.PlayerName + " (Follow)";
			cameraTransform.Type = CameraTransform.CameraType.ThirdPerson;
			CameraTransform item2 = cameraTransform;
			cameraTransforms.Add(item2);
			cameraTransform = new CameraTransform();
			cameraTransform.IsLocalPlayer = true;
			cameraTransform.FollowsLocalPlayer = true;
			cameraTransform.Transform = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform;
			cameraTransform.PositionOffset = -Vector3.forward * 1.4f;
			cameraTransform.RotationOffset = Quaternion.Euler(0f, 180f, 0f);
			cameraTransform.UpdateTransformOnlyOnTeleport = false;
			cameraTransform.IgnoreCameraRoll = true;
			cameraTransform.Name = player.PlayerName + " (Face)";
			cameraTransform.Type = CameraTransform.CameraType.ThirdPersonFace;
			CameraTransform item3 = cameraTransform;
			cameraTransforms.Add(item3);
			cameraTransform = new CameraTransform();
			cameraTransform.IsLocalPlayer = true;
			cameraTransform.FollowsLocalPlayer = true;
			cameraTransform.Transform = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHmdCamera.transform;
			cameraTransform.PositionOffset = Vector3.forward * -1.5f;
			cameraTransform.UpdateTransformOnlyOnTeleport = true;
			cameraTransform.IgnoreCameraRoll = true;
			cameraTransform.Name = player.PlayerName + " (Teleport only)";
			cameraTransform.FOVOverride = 85f;
			cameraTransform.Type = CameraTransform.CameraType.ThirdPersonTeleportOnly;
			CameraTransform item4 = cameraTransform;
			cameraTransforms.Add(item4);
			LocalSetCameraTransformToFollowByType(defaultCameraType, StreamingCameraController.InteractionSource.None);
		}
	}

	public static void LocalSetCameraTransformToFollowByType(CameraTransform.CameraType cameraType, StreamingCameraController.InteractionSource source)
	{
		foreach (CameraTransform cameraTransform in cameraTransforms)
		{
			if (cameraTransform.Type == cameraType && cameraTransform.IsLocalPlayer)
			{
				SetCameraTransformToFollow(cameraTransform, source);
				break;
			}
		}
	}

	private static void SetCameraTransformToFollow(CameraTransform cameraTransform, StreamingCameraController.InteractionSource source)
	{
		if (cameraTransform != null && cameraTransform.IsLocalPlayer)
		{
			defaultCameraType = cameraTransform.Type;
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.DefaultCameraTransformToFollow = cameraTransform;
		}
		if (SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.Mode == StreamingCameraController.StreamingCameraMode.ON)
		{
			if (handheldCamera != null)
			{
				handheldCamera.OpenScreen(cameraTransform == handheldCamera.mainCameraTransform || cameraTransform == handheldCamera.frontFacingCameraTransform);
			}
			SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.SetCameraTransformToFollow(cameraTransform, source);
		}
	}

	private void OnLocalPlayerTeamChange()
	{
		UpdateCameraVisibility();
	}

	private void OnGameStateChange(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateCameraVisibility();
	}

	private void UpdateCameraVisibility()
	{
		otherPlayersHidden = RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.TeamManager.IsPlayerSpectator(PhotonNetwork.player);
	}

	private void Screen_ButtonPressedEvent(SpectatorStreamPreviewScreen screen, SpectatorStreamPreviewScreen.ButtonAction buttonAction)
	{
		switch (buttonAction)
		{
		case SpectatorStreamPreviewScreen.ButtonAction.SetPreview:
			if (screen.CameraTransform != null && screen.CameraTransform.IsValid && screen.CameraTransform != SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow)
			{
				SetCameraTransformToFollow(screen.CameraTransform, StreamingCameraController.InteractionSource.WatchUI);
			}
			break;
		case SpectatorStreamPreviewScreen.ButtonAction.Next:
			AssignNextAvailableCameraTransform(screen, 1);
			break;
		case SpectatorStreamPreviewScreen.ButtonAction.Previous:
			AssignNextAvailableCameraTransform(screen, -1);
			break;
		}
	}

	private void AssignNextAvailableCameraTransform(SpectatorStreamPreviewScreen screen, int direction)
	{
		int num = ((screen.CameraTransform != null) ? cameraTransforms.FindIndex((CameraTransform c) => c == screen.CameraTransform) : 0);
		for (int num2 = 0; num2 < cameraTransforms.Count; num2++)
		{
			num += direction;
			if (num >= cameraTransforms.Count)
			{
				num = 0;
			}
			else if (num < 0)
			{
				num = cameraTransforms.Count - 1;
			}
			if (cameraTransforms[num] != null && cameraTransforms[num].IsValid && !cameraTransforms[num].IsPreviewed)
			{
				screen.CameraTransform = cameraTransforms[num];
				break;
			}
		}
	}

	private void AssignNextAvailableCameraTransformOfType(SpectatorStreamPreviewScreen screen, CameraTransform.CameraType type)
	{
		int num = ((screen.CameraTransform != null) ? cameraTransforms.FindIndex((CameraTransform c) => c == screen.CameraTransform) : 0);
		int num2 = 0;
		while (num2 < cameraTransforms.Count)
		{
			num2++;
			num = ++num % cameraTransforms.Count;
			if (cameraTransforms[num] != null && cameraTransforms[num].Type == type && cameraTransforms[num].IsValid && !cameraTransforms[num].IsPreviewed)
			{
				screen.CameraTransform = cameraTransforms[num];
				break;
			}
		}
	}

	public void Button_ToggleHandheldCamera(bool on)
	{
		if (on)
		{
			UseHandheldCamera();
		}
		else
		{
			RecallHandheldCamera();
		}
	}

	public void UseHandheldCamera()
	{
		if (handheldCamera == null)
		{
			Dictionary<string, object> dictionary = new Dictionary<string, object>();
			dictionary.Add("Owner", PhotonNetwork.player.ID);
			dictionary.Add("Purpose", 4);
			Dictionary<string, object> instantiationParameters = dictionary;
			Transform transform = SingletonMonoBehaviour<CameraRig>.Instance.VrModeHMDCameraTransformYawOnly ?? Player.LocalPlayer.Head.transform;
			Tool tool = Tool.PhotonInstantiate(handheldCameraPrefab.name, transform.TransformPoint(Vector3.forward), Quaternion.identity, 1f, Player.LocalPlayer.photonView.viewID, instantiationParameters);
			if (tool != null)
			{
				handheldCamera = tool.GetComponent<HandheldStreamerCamera>();
				cameraTransforms.Add(handheldCamera.mainCameraTransform);
				cameraTransforms.Add(handheldCamera.frontFacingCameraTransform);
				SetCameraTransformToFollow(handheldCamera.mainCameraTransform, StreamingCameraController.InteractionSource.WatchUI);
				handheldCamera.Tool.InputDownEvent += OnHandheldCameraInputDown;
				handheldCamera.SetTexture(SingletonMonoBehaviour<StreamingCameraController>.Instance.StreamingCamera.activeTexture);
			}
		}
		else
		{
			if (!cameraTransforms.Contains(handheldCamera.mainCameraTransform))
			{
				cameraTransforms.Add(handheldCamera.mainCameraTransform);
			}
			if (!cameraTransforms.Contains(handheldCamera.frontFacingCameraTransform))
			{
				cameraTransforms.Add(handheldCamera.frontFacingCameraTransform);
			}
			handheldCamera.Tool.AuthorityResetToDefault(Player.LocalPlayer.Head.transform.TransformPoint(Vector3.forward), Quaternion.identity, sleepPhysics: true, wasCleanedUp: true);
		}
		UIHelper.SafeSetText(useHandheldToggle.Label, "Recall");
	}

	public void RecallHandheldCamera()
	{
		cameraTransforms.Remove(handheldCamera.mainCameraTransform);
		cameraTransforms.Remove(handheldCamera.frontFacingCameraTransform);
		SpectatorStreamPreviewScreen[] array = previewScreens;
		foreach (SpectatorStreamPreviewScreen spectatorStreamPreviewScreen in array)
		{
			if (spectatorStreamPreviewScreen.CameraTransform == null || spectatorStreamPreviewScreen.CameraTransform == handheldCamera.mainCameraTransform || spectatorStreamPreviewScreen.CameraTransform == handheldCamera.frontFacingCameraTransform)
			{
				AssignNextAvailableCameraTransform(spectatorStreamPreviewScreen, 1);
			}
		}
		if (SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera != null && (SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow == handheldCamera.mainCameraTransform || SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow == handheldCamera.frontFacingCameraTransform))
		{
			SetCameraTransformToFollow(previewScreens[0].CameraTransform, StreamingCameraController.InteractionSource.HandheldTool);
		}
		handheldCamera.Tool.AuthorityDisableAndMove(Vector3.zero, Quaternion.identity);
		UIHelper.SafeSetText(useHandheldToggle.Label, "Use");
	}

	private void OnHandheldCameraInputDown(Tool thisTool)
	{
		if (thisTool == handheldCamera.Tool && SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera != null)
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.CurrentStreamingCamera.CameraTransformToFollow != handheldCamera.mainCameraTransform)
			{
				SetCameraTransformToFollow(handheldCamera.mainCameraTransform, StreamingCameraController.InteractionSource.HandheldTool);
			}
			else
			{
				SetCameraTransformToFollow(handheldCamera.frontFacingCameraTransform, StreamingCameraController.InteractionSource.HandheldTool);
			}
		}
	}

	public void Slider_FrameRateValueChange(float value)
	{
		int num = (int)value;
		for (int i = 0; i < sliderToFrameRateSettings.Length; i++)
		{
			if (num == sliderToFrameRateSettings[i].SliderValue)
			{
				SingletonMonoBehaviour<StreamingCameraController>.Instance.SetFrameRate(sliderToFrameRateSettings[i].frameRate, StreamingCameraController.InteractionSource.WatchUI);
				return;
			}
		}
		UnityEngine.Debug.LogError("Frame ratevalue was invalid. You need to update the slider to frame rate mappings");
	}

	public void Slider_FOVValueChange(float value)
	{
		int num = (int)value;
		for (int i = 0; i < sliderToFOVSettings.Length; i++)
		{
			if (num == sliderToFOVSettings[i].SliderValue)
			{
				SingletonMonoBehaviour<StreamingCameraController>.Instance.SetFieldOfView(sliderToFOVSettings[i].fov, StreamingCameraController.InteractionSource.WatchUI);
				previewCamera.fieldOfView = (float)sliderToFOVSettings[i].fov;
				return;
			}
		}
		UnityEngine.Debug.LogError("FOV value was invalid. You need to update the slider to FOV mappings");
	}

	public void Slider_AudioListenerPositionValueChange(float value)
	{
		int listenerMode = (int)value;
		SingletonMonoBehaviour<StreamingCameraController>.Instance.SetAudioListenerMode(listenerMode, StreamingCameraController.InteractionSource.WatchUI);
	}

	public void Slider_GreenScreenValueChange(float value)
	{
		int num = (int)value;
		for (int i = 0; i < sliderToGreenScreenSettings.Length; i++)
		{
			if (num == sliderToGreenScreenSettings[i].SliderValue)
			{
				StreamingCameraController.GreenScreenModes mode = sliderToGreenScreenSettings[i].mode;
				SingletonMonoBehaviour<StreamingCameraController>.Instance.SetGreenScreen(mode, StreamingCameraController.InteractionSource.WatchUI);
				previewCamera.clearFlags = ((mode == StreamingCameraController.GreenScreenModes.Off) ? CameraClearFlags.Skybox : CameraClearFlags.Color);
				previewCamera.farClipPlane = ((mode != StreamingCameraController.GreenScreenModes.Off) ? ((float)mode) : 100f);
				return;
			}
		}
		UnityEngine.Debug.LogError("Greenscreen value was invalid. You need to update the slider to green screen mappings");
	}

	private void AddSceneStreamPoints()
	{
		streamPoints = UnityEngine.Object.FindObjectsOfType<SpectatorStreamPoint>();
		SpectatorStreamPoint[] array = streamPoints;
		foreach (SpectatorStreamPoint spectatorStreamPoint in array)
		{
			spectatorStreamPoint.CameraTransform.Type = CameraTransform.CameraType.StreamPoint;
			cameraTransforms.Add(spectatorStreamPoint.CameraTransform);
		}
	}
}
public class BugReportingUIFlow : WatchUIFlow
{
	[HideInInspector]
	public string TestCaseKey;

	[HideInInspector]
	public Texture2D Screenshot;

	[SerializeField]
	private InputField3D summaryField;

	[SerializeField]
	private InputField3D descriptionField;

	[SerializeField]
	private RawImage screenshotImage;

	[SerializeField]
	private TextMeshProUGUI screenshotText;

	[SerializeField]
	private TakeBugScreenshotDialog attachScreenshotDialog;

	[SerializeField]
	private GameObject contentPanel;

	[SerializeField]
	private GameObject loadingPanel;

	[SerializeField]
	private Button3D attachScreenshotButton;

	[SerializeField]
	private Button3D submitButton;

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (!(oldFlow is TakeBugScreenshotDialog))
		{
			summaryField.InputField.text = string.Empty;
			descriptionField.InputField.text = string.Empty;
			screenshotImage.texture = null;
			attachScreenshotButton.GetComponent<AspectRatioFitter>().aspectRatio = 1f;
			screenshotText.gameObject.SetActive(value: true);
			summaryField.InputField.onValueChanged.AddListener(delegate
			{
				ValidateAndUpdateUi();
			});
			descriptionField.InputField.onValueChanged.AddListener(delegate
			{
				ValidateAndUpdateUi();
			});
		}
		ValidateAndUpdateUi();
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		if (!stillOnStack)
		{
			summaryField.InputField.onValueChanged.RemoveAllListeners();
			descriptionField.InputField.onValueChanged.RemoveAllListeners();
			TestCaseKey = null;
			Screenshot = null;
		}
	}

	public void ValidateAndUpdateUi()
	{
		bool flag = !string.IsNullOrWhiteSpace(summaryField.InputField.text);
		bool flag2 = !string.IsNullOrWhiteSpace(descriptionField.InputField.text);
		submitButton.interactable = flag && flag2;
	}

	[SkipRename]
	public void Button_AttachScreenshot()
	{
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryConfirmationDialog(attachScreenshotDialog, RecNet.Rooms.LocalRoomDetails?.Room, (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses response)
		{
			if (response == ConfirmDialogResponses.Affirmative)
			{
				screenshotImage.texture = Screenshot;
				attachScreenshotButton.GetComponent<AspectRatioFitter>().aspectRatio = (float)Screenshot.width / (float)Screenshot.height;
				screenshotText.gameObject.SetActive(value: false);
			}
		});
	}

	[SkipRename]
	public void Button_Submit()
	{
		byte[] screenshotData = null;
		if (Screenshot != null)
		{
			screenshotData = Screenshot.EncodeToPNG();
		}
		byte[] array = null;
		try
		{
			array = ReadOutputLog();
		}
		catch (Exception ex)
		{
			array = Encoding.UTF8.GetBytes($"Failed reading output log.\n\n{ex.Message}\n\n{ex.StackTrace}");
		}
		contentPanel.SetActive(value: false);
		loadingPanel.SetActive(value: true);
		BugReporting.ReportBug(summaryField.Text, descriptionField.Text, screenshotData, array, TestCaseKey).Then(delegate
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Thank you for reporting this bug! The development team will investigate the issue soon.", 3f);
			Player.LocalPlayer.PlayerUI.WatchMenu.PopFlow();
		}).Error(delegate
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Failed reporting the bug.", 3f);
		})
			.Finally(delegate
			{
				contentPanel.SetActive(value: true);
				loadingPanel.SetActive(value: false);
			});
	}

	private string GetOutputLogPath()
	{
		return Environment.ExpandEnvironmentVariables($"%userprofile%/AppData/LocalLow/{UnityEngine.Application.companyName}/{UnityEngine.Application.productName}/output_log.txt");
	}

	private byte[] ReadOutputLog()
	{
		string outputLogPath = GetOutputLogPath();
		return (!File.Exists(outputLogPath)) ? null : WriteSafeFileReadAllBytes(outputLogPath);
	}

	private byte[] WriteSafeFileReadAllBytes(string path)
	{
		using FileStream fileStream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite);
		byte[] array = new byte[fileStream.Length];
		fileStream.Read(array, 0, (int)fileStream.Length);
		return array;
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class TakeBugScreenshotDialog : ConfirmUIDialog<RecNet.Room>
	{
		[SerializeField]
		private Button3D flipCameraButton;

		[SerializeField]
		private Button3D takePictureButton;

		[SerializeField]
		private Button3D clearPictureButton;

		[SerializeField]
		private Button3D attachButton;

		[SerializeField]
		private Camera roomCamera;

		[SerializeField]
		private RawImage screenshotImage;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip shutterAudio;

		public RenderTexture renderTexture;

		private AltTextureSet roomPhotoSet = new AltTextureSet();

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			renderTexture = new RenderTexture(2560, 1440, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			roomCamera.targetTexture = renderTexture;
			roomCamera.aspect = ShareCamera.SixteenNineAspectRatio;
			roomCamera.depthTextureMode = DepthTextureMode.Depth;
			if (RecRoomSceneManager.IsInitialized && RecRoomSceneManager.Instance.SceneRenderingSettings != null)
			{
				RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(roomCamera);
			}
			UpdateUi(tookPicture: false);
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			CleanupResources();
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(RecNet.Room room)
		{
			UpdateUi(tookPicture: false);
			return base.ShowDialog();
		}

		private void UpdateUi(bool tookPicture)
		{
			flipCameraButton.gameObject.SetActive(!tookPicture);
			takePictureButton.gameObject.SetActive(!tookPicture);
			clearPictureButton.gameObject.SetActive(tookPicture);
			attachButton.gameObject.SetActive(tookPicture);
			if (!tookPicture)
			{
				screenshotImage.texture = renderTexture;
			}
			else
			{
				screenshotImage.texture = roomPhotoSet.MainTexture;
			}
		}

		private void CleanupResources()
		{
			if (renderTexture != null)
			{
				renderTexture.Release();
			}
			if (roomPhotoSet != null)
			{
				roomPhotoSet.DestroyTextures();
			}
		}

		[SkipRename]
		public void Button_FlipCamera()
		{
			roomCamera.transform.rotation = Quaternion.LookRotation(-roomCamera.transform.forward, roomCamera.transform.up);
		}

		[SkipRename]
		public void Button_TakePicture()
		{
			AudioManager.Play3DSFX(shutterAudio, base.transform.position);
			roomPhotoSet.Render(roomCamera, renderTexture);
			UpdateUi(tookPicture: true);
		}

		[SkipRename]
		public void Button_ClearPicture()
		{
			CleanupResources();
			UpdateUi(tookPicture: false);
		}

		[SkipRename]
		public void Button_Save()
		{
			BugReportingUIFlow flowByType = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<BugReportingUIFlow>();
			renderTexture.GetTexture2D(ref flowByType.Screenshot);
			Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
		}
	}
}
public class ChecklistWatchUIFlow : PlayerWatchUIFlow
{
	[SerializeField]
	private TextMeshProUGUI weeklyChallengeTimeRemaining;

	[SerializeField]
	private string weeklyChallengePrefix = "New Weekly Challenges in ";

	[SerializeField]
	private TextMeshProUGUI themeText;

	[SerializeField]
	private ObjectiveChecklist[] checklists;

	[SerializeField]
	private RectTransform weeklyChallengesDisabledDisplay;

	[SerializeField]
	private TextMeshProUGUI weeklyChallengesDisabledReasonText;

	[SerializeField]
	private GameObject challengeSubscreenButtons;

	[Header("Subscreens")]
	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private SubscreenControl subscreenControl;

	[SerializeField]
	private Subscreen dailySubscreen;

	[SerializeField]
	private Subscreen weeklySubscreen;

	[SerializeField]
	private Subscreen orientationSubscreen;

	private bool listSelected;

	private TimeSpan nextChallengesTimeSpan;

	private int lastSeconds = -1;

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		SetProfile(Profiles.LocalProfile);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		subscreenControl.ActiveSubscreenChanged -= OnActiveSubscreenChanged;
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		UpdateAllObjectives();
		SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.OnWeeklyChallengeUpdated += UpdateAllObjectives;
		SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeEnabledStateChanged += UpdateWeeklyChallengesDisabledDisplay;
		Player.LocalPlayer.DailiesObjectiveTracker.ObjectiveProgressUpdateEvent += UpdateAllObjectives;
		Player.LocalPlayer.OrientationObjectiveTracker.ObjectiveProgressUpdateEvent += UpdateAllObjectives;
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap != null)
		{
			string themeString = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.ThemeString;
			if (!string.IsNullOrEmpty(themeString))
			{
				themeText.text = themeString;
			}
		}
		if (!listSelected)
		{
			subscreenControl.ActiveSubscreenChanged += OnActiveSubscreenChanged;
			challengeSubscreenButtons.SetActive(value: true);
			if (!Player.LocalPlayer.OrientationObjectiveTracker.GetAllObjectivesCompleted())
			{
				orientationSubscreen.Button.ForcePressed();
			}
			else
			{
				dailySubscreen.Button.ForcePressed();
			}
			listSelected = true;
		}
		UpdateWeeklyChallengesDisabledDisplay();
		UpdateToasts();
	}

	private void OnActiveSubscreenChanged()
	{
		if (subscreenControl.ActiveSubscreen == dailySubscreen)
		{
			PlayerObjectiveTracker.UpdateLastRecordedObjectiveDate();
			AnalyticsHelper.LookedAtChallenges(ObjectiveChecklist.ObjectiveListType.Daily);
			WatchUI.SetToast(ToastIds.DailyChallenges, string.Empty);
		}
		else if (subscreenControl.ActiveSubscreen == weeklySubscreen)
		{
			SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.UpdateLastSeenChallengeMapId();
			AnalyticsHelper.LookedAtChallenges(ObjectiveChecklist.ObjectiveListType.Weekly);
			WatchUI.SetToast(ToastIds.WeeklyChallenges, string.Empty);
		}
		else if (subscreenControl.ActiveSubscreen == orientationSubscreen)
		{
			AnalyticsHelper.LookedAtChallenges(ObjectiveChecklist.ObjectiveListType.Orientation);
			WatchUI.SetToast(ToastIds.OrientationChallenges, string.Empty);
		}
	}

	private void UpdateToasts()
	{
		OnActiveSubscreenChanged();
		if (!SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.HasSeenThisWeeksChallenges)
		{
			WatchUI.SetToast(ToastIds.WeeklyChallenges, "NEW");
		}
		if (!PlayerObjectiveTracker.HasSeenTodaysObjectives)
		{
			WatchUI.SetToast(ToastIds.DailyChallenges, "NEW");
		}
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance != null)
		{
			SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.OnWeeklyChallengeUpdated -= UpdateAllObjectives;
			SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeEnabledStateChanged -= UpdateWeeklyChallengesDisabledDisplay;
		}
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.DailiesObjectiveTracker.ObjectiveProgressUpdateEvent -= UpdateAllObjectives;
			Player.LocalPlayer.OrientationObjectiveTracker.ObjectiveProgressUpdateEvent -= UpdateAllObjectives;
		}
	}

	private void Update()
	{
		if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.HasValue)
		{
			nextChallengesTimeSpan = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.Value - (DateTime.UtcNow + SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.TimeDiff.Value);
			if (nextChallengesTimeSpan.Seconds != lastSeconds)
			{
				ShowWeeklyTimeRemaining();
				lastSeconds = nextChallengesTimeSpan.Seconds;
			}
		}
	}

	private void ShowWeeklyTimeRemaining()
	{
		string text = TimeSpanToString();
		UIHelper.SafeSetText(weeklyChallengeTimeRemaining, weeklyChallengePrefix + text);
	}

	private string TimeSpanToString()
	{
		if (!SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.EndAtUTC.HasValue || !SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.TimeDiff.HasValue)
		{
			return string.Format("{0:D2}:{1:D2}:{2:D2}:{0:D2}", 0, 0, 0, 0);
		}
		if (nextChallengesTimeSpan.TotalSeconds < 0.0)
		{
			return string.Format("{0:D2}:{1:D2}:{2:D2}:{0:D2}", 0, 0, 0, 0);
		}
		int days = nextChallengesTimeSpan.Days;
		int hours = nextChallengesTimeSpan.Hours;
		int minutes = nextChallengesTimeSpan.Minutes;
		int seconds = nextChallengesTimeSpan.Seconds;
		return $"{days:D2}:{hours:D2}:{minutes:D2}:{seconds:D2}";
	}

	private void UpdateAllObjectives()
	{
		Player localPlayer = Player.LocalPlayer;
		if (localPlayer == null)
		{
			return;
		}
		ObjectiveChecklist[] array = checklists;
		foreach (ObjectiveChecklist objectiveChecklist in array)
		{
			bool flag = objectiveChecklist.UpdateAllObjectives();
			if (objectiveChecklist.ListType == ObjectiveChecklist.ObjectiveListType.Orientation)
			{
				bool isCurrent = (orientationSubscreen.Button as RadioButton3D).IsCurrent;
				orientationSubscreen.Button.gameObject.SetActive(!flag);
				if (isCurrent && flag)
				{
					dailySubscreen.Button.ForcePressed();
				}
			}
		}
	}

	private void UpdateWeeklyChallengesDisabledDisplay()
	{
		WeeklyChallengeManager.WeeklyChallengesStates weeklyChallengesState = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.WeeklyChallengesState;
		string text = string.Empty;
		switch (weeklyChallengesState)
		{
		case WeeklyChallengeManager.WeeklyChallengesStates.Disabled_Sandbox:
			text = "Turn off sandbox to re-enable Challenges";
			break;
		case WeeklyChallengeManager.WeeklyChallengesStates.Disabled_CustomGameRules:
			text = "Return to default game rules to re-enable Challenges";
			break;
		}
		UIHelper.SafeSetText(weeklyChallengesDisabledReasonText, text);
		UIHelper.SafeSetActive(weeklyChallengesDisabledDisplay, weeklyChallengesState != WeeklyChallengeManager.WeeklyChallengesStates.Enabled);
	}

	public void ShowDailySubscreen()
	{
		subscreenControl.ShowSubscreen(dailySubscreen);
	}

	public void ShowOrientationSubscreen()
	{
		subscreenControl.ShowSubscreen(orientationSubscreen);
	}
}
