	private float scaledRewardSize = 0.03f;

	private GameObject reward;

	[SerializeField]
	private ObjectivesPagedGrid objectivesPagedGrid;

	public Action OnRewardClaimed;

	public Action<GameObject> OnRewardObjectSpawned;

	private static bool hasCachedAwardAmounts;

	private static int dailyAwardAmount;

	private static int allDailiesAwardAmount;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private static Action m_onCachedValuesUpdated;

	public ObjectiveListType ListType => listType;

	private static event Action onCachedValuesUpdated
	{
		add
		{
			Action action = ObjectiveChecklist.m_onCachedValuesUpdated;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref ObjectiveChecklist.m_onCachedValuesUpdated, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = ObjectiveChecklist.m_onCachedValuesUpdated;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref ObjectiveChecklist.m_onCachedValuesUpdated, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Start()
	{
		onCachedValuesUpdated += UpdateTokenValues;
		UpdateTokenValues();
		CacheAwardValuesIfNecessary();
	}

	private void OnDestroy()
	{
		onCachedValuesUpdated -= UpdateTokenValues;
	}

	private void UpdateTokenValues()
	{
		string newText = string.Empty;
		string text = string.Empty;
		if (ListType == ObjectiveListType.Daily && hasCachedAwardAmounts)
		{
			newText = dailyAwardAmount.ToString();
			text = allDailiesAwardAmount.ToString();
		}
		for (int i = 0; i < objectiveViews.Length; i++)
		{
			objectiveViews[i].UpdateTokenText(newText);
		}
		if (allCompleteTokenText != null)
		{
			allCompleteTokenText.text = text;
		}
	}

	public bool UpdateAllObjectives()
	{
		return ListType switch
		{
			ObjectiveListType.Weekly => UpdateWeeklyObjectives(), 
			ObjectiveListType.Orientation => UpdateOrientationObjectives(), 
			_ => UpdateDailyObjectives(), 
		};
	}

	private bool UpdateDailyObjectives()
	{
		Player localPlayer = Player.LocalPlayer;
		if (localPlayer != null)
		{
			SpawnReward();
			if (allObjectivesCompleteImage != null)
			{
				allObjectivesCompleteImage.gameObject.SetActive(localPlayer.DailiesObjectiveTracker.GetAllObjectivesCompleted());
			}
			for (int i = 0; i < objectiveViews.Length; i++)
			{
				localPlayer.DailiesObjectiveTracker.GetObjectiveDescription(i, out var description, out var descriptionText);
				if (description != null)
				{
					bool rewardAvailable = false;
					int progress;
					int total;
					bool objectiveProgress = localPlayer.DailiesObjectiveTracker.GetObjectiveProgress(i, out progress, out total);
					objectiveViews[i].UpdateProgress(progress, total, objectiveProgress, rewardAvailable, descriptionText, description.ToolTip);
				}
			}
			bool allObjectivesCompleted = localPlayer.DailiesObjectiveTracker.GetAllObjectivesCompleted();
			if (rewardBackground != null)
			{
				rewardBackground.color = ((!allObjectivesCompleted) ? notRewardedColor : rewardedColor);
			}
			return allObjectivesCompleted;
		}
		return true;
	}

	private bool UpdateOrientationObjectives()
	{
		Player localPlayer = Player.LocalPlayer;
		if (localPlayer != null)
		{
			bool allObjectivesCompleted = localPlayer.OrientationObjectiveTracker.GetAllObjectivesCompleted();
			if (allObjectivesCompleteImage != null)
			{
				allObjectivesCompleteImage.gameObject.SetActive(allObjectivesCompleted);
			}
			List<ObjectiveDetails> allObjectiveDetails = localPlayer.OrientationObjectiveTracker.GetAllObjectiveDetails();
			if (objectivesPagedGrid != null && allObjectiveDetails != null)
			{
				objectivesPagedGrid.SetObjectiveDetails(allObjectiveDetails);
			}
			return allObjectivesCompleted;
		}
		return true;
	}

	private bool UpdateWeeklyObjectives()
	{
		SpawnReward();
		for (int i = 0; i < objectiveViews.Length; i++)
		{
			if (SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap != null && SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.Challenges != null && i < SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.Challenges.Count)
			{
				RecNetChallenge recNetChallenge = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.Challenges[i];
				if (recNetChallenge != null)
				{
					IChallenge challengeDefinition = recNetChallenge.ChallengeDefinition;
					if (recNetChallenge != null && challengeDefinition != null)
					{
						ChallengeProgress progress = challengeDefinition.Progress;
						string description = recNetChallenge.Description;
						string tooltip = recNetChallenge.Tooltip;
						bool rewardAvailable = false;
						objectiveViews[i].UpdateProgress(progress.Count, progress.Total, challengeDefinition.Complete, rewardAvailable, description, tooltip);
						continue;
					}
				}
			}
			objectiveViews[i].UpdateProgress(1, 1, completed: true, rewardAvailable: false, "Check back later!", "Check back later for more challenges!");
		}
		return SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.AllObjectivesComplete;
	}

	private void SpawnReward(int rewardNumber = 0)
	{
		if (!(reward == null))
		{
			return;
		}
		GameObject gameObject = null;
		if (listType == ObjectiveListType.Daily && giftboxPrefab != null)
		{
			gameObject = UnityEngine.Object.Instantiate(giftboxPrefab);
			gameObject.transform.position = rewardRoot.position;
			gameObject.transform.rotation = rewardRoot.rotation;
			gameObject.transform.parent = rewardRoot;
		}
		else
		{
			if (listType != ObjectiveListType.Weekly || SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap == null)
			{
				return;
			}
			ChallengeGift challengeGift = SingletonMonoBehaviour<WeeklyChallengeManager>.Instance.ChallengeMap.Gifts[rewardNumber];
			if (challengeGift == null)
			{
				return;
			}
			OutfitSelection outfitSelection = OutfitSelection.Parse(challengeGift.AvatarItemDesc);
			if (outfitSelection != null)
			{
				gameObject = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitImposter(outfitSelection);
			}
			else if (!string.IsNullOrEmpty(challengeGift.EquipmentPrefabName))
			{
				gameObject = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentImposter(challengeGift.EquipmentPrefabName, challengeGift.EquipmentModificationGuid);
			}
			if (gameObject != null)
			{
				if (!rewardUsedForFullSizeDisplay)
				{
					gameObject.transform.AssignCorrectScale(scaledRewardSize);
				}
				Transform parent = rewardRoot;
				reward = gameObject;
				if (OnRewardObjectSpawned != null)
				{
					OnRewardObjectSpawned(gameObject);
				}
				gameObject.transform.SetParent(parent, worldPositionStays: true);
				gameObject.transform.localPosition = Vector3.zero;
				gameObject.transform.localRotation = Quaternion.identity;
			}
		}
	}

	private static void CacheAwardValuesIfNecessary()
	{
		if (hasCachedAwardAmounts)
		{
			return;
		}
		hasCachedAwardAmounts = true;
		Storefronts.FetchBalanceAddConfig(CurrencyType.RecCenterTokens, StorefrontBalanceAddTypes.DailyChallenge, delegate(string error, StorefrontBalanceAddConfigDTO balanceDTO)
		{
			if (!string.IsNullOrEmpty(error) || balanceDTO == null)
			{
				hasCachedAwardAmounts = false;
			}
			else
			{
				dailyAwardAmount = balanceDTO.BaseAward;
				if (ObjectiveChecklist.onCachedValuesUpdated != null)
				{
					ObjectiveChecklist.onCachedValuesUpdated();
				}
			}
		});
		Storefronts.FetchBalanceAddConfig(CurrencyType.RecCenterTokens, StorefrontBalanceAddTypes.AllDailyChallenges, delegate(string error, StorefrontBalanceAddConfigDTO balanceDTO)
		{
			if (!string.IsNullOrEmpty(error) || balanceDTO == null)
			{
				hasCachedAwardAmounts = false;
			}
			else
			{
				allDailiesAwardAmount = balanceDTO.BaseAward;
				if (ObjectiveChecklist.onCachedValuesUpdated != null)
				{
					ObjectiveChecklist.onCachedValuesUpdated();
				}
			}
		});
	}
}
public class WeeklyChallengeManager : SingletonMonoBehaviour<WeeklyChallengeManager>
{
	public enum WeeklyChallengesStates
	{
		Enabled,
		Disabled_Sandbox,
		Disabled_CustomGameRules
	}

	public const string LAST_SEEN_CHALLENGE_MAP_ID = "Recroom.ChallengeMap";

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_ChallengeEnabledStateChanged;

	[SerializeField]
	private string challengeNotificationStringFormat = "Weekly Challenge {0}   {1}/{2}";

	private Coroutine WaitForNewChallengesCoroutine;

	private Dictionary<int, Coroutine> waitRoutines = new Dictionary<int, Coroutine>();

	private Dictionary<int, Coroutine> flushRoutines = new Dictionary<int, Coroutine>();

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_OnWeeklyChallengeUpdated;

	private Coroutine updatedChallengeRoutine;

	public bool AllObjectivesComplete
	{
		get
		{
			if (ChallengeMap == null || ChallengeMap.Challenges == null || ChallengeMap.Challenges.Count <= 0)
			{
				return false;
			}
			bool result = true;
			foreach (RecNetChallenge challenge in ChallengeMap.Challenges)
			{
				if (challenge.ChallengeDefinition == null || !challenge.ChallengeDefinition.Complete)
				{
					result = false;
				}
			}
			return result;
		}
	}

	public WeeklyChallengesStates WeeklyChallengesState
	{
		get
		{
			if (RecRoomSceneManager.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				if (GameManager.IsSandboxActive)
				{
					return WeeklyChallengesStates.Disabled_Sandbox;
				}
				if (!NetworkedSingletonMonoBehaviour<GameManager>.Instance.CustomGameSettings.AllowRewards)
				{
					return WeeklyChallengesStates.Disabled_CustomGameRules;
				}
			}
			return WeeklyChallengesStates.Enabled;
		}
	}

	public bool HasSeenThisWeeksChallenges
	{
		get
		{
			int num = RecroomPrefs.GetInt("Recroom.ChallengeMap", 0);
			return ChallengeMap != null && ChallengeMap.ChallengeMapId == num;
		}
	}

	public ChallengeMap ChallengeMap { get; private set; }

	public DateTime? EndAtUTC { get; internal set; }

	public TimeSpan? TimeDiff { get; internal set; }

	public float SecondsUntilNewChallenges { get; private set; }

	public event Action ChallengeEnabledStateChanged
	{
		add
		{
			Action action = this.m_ChallengeEnabledStateChanged;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ChallengeEnabledStateChanged, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_ChallengeEnabledStateChanged;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_ChallengeEnabledStateChanged, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public event Action OnWeeklyChallengeUpdated
	{
		add
		{
			Action action = this.m_OnWeeklyChallengeUpdated;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnWeeklyChallengeUpdated, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_OnWeeklyChallengeUpdated;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_OnWeeklyChallengeUpdated, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public void Initialize()
	{
		StartCoroutine(FetchWeeklyChallenges());
	}

	private IEnumerator FetchWeeklyChallenges()
	{
		yield return Challenges.GetCurrentChallenges(delegate(string error, Challenges.ChallengeMapResponse response)
		{
			if (string.IsNullOrEmpty(error) && response.Success)
			{
				ChallengeMap = response.ChallengeMap;
				EndAtUTC = ChallengeMap.EndAt;
				DateTime serverTime = ChallengeMap.ServerTime;
				TimeDiff = serverTime - DateTime.UtcNow;
				WaitForNewChallenges();
				InitializeWeeklyChallenges(ChallengeMap.Challenges, ChallengeMap.CompleteAll);
			}
			else
			{
				ChallengeMap = null;
				EndAtUTC = null;
				TimeDiff = null;
			}
			this.OnWeeklyChallengeUpdated.DoIfNotNull(delegate(Action _)
			{
				_();
			});
		});
	}

	private void WaitForNewChallenges()
	{
		if (WaitForNewChallengesCoroutine != null)
		{
			StopCoroutine(WaitForNewChallengesCoroutine);
		}
		WaitForNewChallengesCoroutine = StartCoroutine(WaitForNewChallengesRoutine());
	}

	private IEnumerator WaitForNewChallengesRoutine()
	{
		SecondsUntilNewChallenges = (float)(EndAtUTC.Value - (DateTime.UtcNow + TimeDiff.Value)).TotalSeconds;
		if (SecondsUntilNewChallenges < 0f)
		{
			SecondsUntilNewChallenges = 120f;
		}
		yield return new WaitForSecondsRealtime(SecondsUntilNewChallenges);
		GetNewChallenges();
	}

	private void GetNewChallenges()
	{
		if (ChallengeMap != null)
		{
			foreach (RecNetChallenge challenge in ChallengeMap.Challenges)
			{
				IChallenge challengeDefinition = challenge.ChallengeDefinition;
				if (challengeDefinition != null && !challengeDefinition.Complete)
				{
					ChallengeEvents.ChallengeEvent -= challengeDefinition.EvaluateEvent;
					challenge.ChallengeDefinitionCompleteEvent -= OnChallengeComplete;
					challenge.ChallengeDefinitionUpdateEvent -= OnChallengeUpdated;
					challenge.ChallengeDefinitionUpdateServerEvent -= UpdateServerWithChallengeStatus;
					challenge.ChallengeNotificationEvent -= OnChallengeNotify;
				}
			}
		}
		StartCoroutine(FetchWeeklyChallenges());
	}

	private void InitializeWeeklyChallenges(List<RecNetChallenge> weeklyChallenges, bool completeAll)
	{
		int num = 1;
		int num2 = 0;
		foreach (RecNetChallenge weeklyChallenge in weeklyChallenges)
		{
			IChallenge challengeDefinition = weeklyChallenge.ChallengeDefinition;
			if (challengeDefinition == null || (challengeDefinition.Complete && weeklyChallenge.Complete))
			{
				num2++;
				continue;
			}
			challengeDefinition.UpdateServerOnReset = true;
			challengeDefinition.IsMasterChallenge = true;
			ChallengeEvents.ChallengeEvent += challengeDefinition.EvaluateEvent;
			weeklyChallenge.ChallengeDefinitionCompleteEvent += OnChallengeComplete;
			weeklyChallenge.ChallengeDefinitionUpdateEvent += OnChallengeUpdated;
			weeklyChallenge.ChallengeDefinitionUpdateServerEvent += UpdateServerWithChallengeStatus;
			weeklyChallenge.ChallengeNotificationEvent += OnChallengeNotify;
			weeklyChallenge.Slot = num++;
			if (challengeDefinition.Complete && !weeklyChallenge.Complete)
			{
				FlushChallenge(weeklyChallenge);
			}
		}
		if (!completeAll && num2 == weeklyChallenges.Count)
		{
			FlushChallenge(weeklyChallenges.FirstOrDefault());
		}
	}

	private void OnChallengeUpdated(RecNetChallenge challenge)
	{
		this.OnWeeklyChallengeUpdated.DoIfNotNull(delegate(Action _)
		{
			_();
		});
		if (waitRoutines.ContainsKey(challenge.ChallengeId) && waitRoutines[challenge.ChallengeId] != null)
		{
			Coroutine routine = waitRoutines[challenge.ChallengeId];
			StopCoroutine(routine);
		}
		waitRoutines[challenge.ChallengeId] = StartCoroutine(WaitAndFlushChallenge(challenge));
	}

	private void OnChallengeNotify(RecNetChallenge challenge, int count, int total)
	{
		string titleText = string.Format(challengeNotificationStringFormat, challenge.Slot, count, total);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, titleText, 3f);
	}

	private IEnumerator WaitAndFlushChallenge(RecNetChallenge challenge)
	{
		yield return new WaitForSeconds(30f);
		FlushChallenge(challenge);
	}

	private void FlushChallenge(RecNetChallenge challenge)
	{
		if (challenge != null)
		{
			if (waitRoutines.ContainsKey(challenge.ChallengeId) && waitRoutines[challenge.ChallengeId] != null)
			{
				Coroutine routine = waitRoutines[challenge.ChallengeId];
				StopCoroutine(routine);
			}
			if (flushRoutines.ContainsKey(challenge.ChallengeId) && flushRoutines[challenge.ChallengeId] != null)
			{
				Coroutine routine2 = flushRoutines[challenge.ChallengeId];
				StopCoroutine(routine2);
			}
			FlushChallengeRoutine(challenge);
		}
	}

	private void FlushChallengeRoutine(RecNetChallenge challenge)
	{
		challenge.Config = AmplitudeMiniJSON.Json.Serialize(challenge.ChallengeDefinition.Serialize()).Trim();
		Challenges.UpdateChallengeProgress(ChallengeMap.ChallengeMapId, challenge);
	}

	private void UpdateServerWithChallengeStatus(RecNetChallenge challenge)
	{
		FlushChallenge(challenge);
	}

	private void OnChallengeComplete(RecNetChallenge challenge)
	{
		AnalyticsHelper.CompletedWeeklyChallenge(challenge);
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Weekly Challenge Complete!", 3f);
		ChallengeEvents.ChallengeEvent -= challenge.ChallengeDefinition.EvaluateEvent;
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerEvents.WeeklyChallengeCompleted();
		}
		this.OnWeeklyChallengeUpdated.DoIfNotNull(delegate(Action _)
		{
			_();
		});
		if (AllObjectivesComplete)
		{
			AnalyticsHelper.CompletedAllWeeklyChallenges();
		}
	}

	public void UpdateLastSeenChallengeMapId()
	{
		if (ChallengeMap != null)
		{
			RecroomPrefs.SetInt("Recroom.ChallengeMap", ChallengeMap.ChallengeMapId);
			RecroomPrefs.Save();
		}
	}

	public void CustomGameSettingsChanged()
	{
		this.ChallengeEnabledStateChanged.DoIfNotNull(delegate(Action _)
		{
			_();
		});
	}

	public void SandboxStatusChanged()
	{
		this.ChallengeEnabledStateChanged.DoIfNotNull(delegate(Action _)
		{
			_();
		});
	}
}
