	private Button3D peopleButton;

	[SerializeField]
	private Button3D messagesButton;

	[SerializeField]
	private Button3D checklistButton;

	[SerializeField]
	private Button3D backpackButton;

	[SerializeField]
	private Button3D storeButton;

	[SerializeField]
	private Button3D dormRoomButton;

	[SerializeField]
	private Button3D recCenterButton;

	[SerializeField]
	private Button3D exitButton;

	[SerializeField]
	[FormerlySerializedAs("extraPanel")]
	private RectTransform devMenuPanel;

	[SerializeField]
	[FormerlySerializedAs("buttonPrefab")]
	private Button3D devButtonPrefab;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private PlayerProfileUIControl playerProfileUIControl;

	private Dictionary<System.Type, Button3DBase> typeButtonMap = new Dictionary<System.Type, Button3DBase>();

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		if (devMenuPanel != null)
		{
			devMenuPanel.gameObject.SetActive(value: false);
		}
		playerProfileUIControl.SetProfile(Profiles.LocalProfile);
		SetExitButtonState();
		ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
		if (componentInChildren != null)
		{
			int showReportBugButton;
			if (!RecNet.Core.IsDevBuildOrDevEnv)
			{
				ObscuredBool? obscuredBool = Profiles.LocalProfile?.Developer;
				showReportBugButton = (((bool)((!obscuredBool.HasValue) ? ((ObscuredBool)false) : obscuredBool.Value)) ? 1 : 0);
			}
			else
			{
				showReportBugButton = 1;
			}
			componentInChildren.ShowReportBugButton = (byte)showReportBugButton != 0;
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		UpdateToast();
	}

	public override void OnAllFlowsInitialized()
	{
		base.OnAllFlowsInitialized();
		SetButtonOnClick<ProfileWatchUIFlow>(profileButton);
		SetButtonOnClick<SettingsWatchUIFlow>(settingsButton);
		SetButtonOnClick<PeopleWatchUIFlow>(peopleButton);
		SetButtonOnClick<MessagesWatchUIFlow>(messagesButton);
		SetButtonOnClick<ChecklistWatchUIFlow>(checklistButton);
		SetButtonOnClick<BackpackScreen>(backpackButton);
		SetButtonOnClick<StoreScreen>(storeButton);
		SetButtonOnClick<BrowseRoomsScreen>(browseRoomsButton);
		SetButtonOnClick<EventsScreen>(eventsButton);
		SetButtonOnClick<CreateRoomScreen>(createRoomButton);
		SetButtonOnClick<ThisRoomWatchUIFlow>(thisRoomButton);
		if (!(base.WatchUI != null))
		{
			return;
		}
		int num = 0;
		if ((bool)Profiles.LocalProfile.Developer)
		{
			TestCaseManagementWatchUIFlow tcmFlow = base.UIBase.GetFlowByType<TestCaseManagementWatchUIFlow>();
			if (tcmFlow != null)
			{
				ButtonConfig component = tcmFlow.GetComponent<ButtonConfig>();
				if (component != null)
				{
					Button3D button3D = UnityEngine.Object.Instantiate(devButtonPrefab);
					button3D.transform.SetParent(devMenuPanel.transform, worldPositionStays: false);
					button3D.OnClick.AddListener(delegate
					{
						base.WatchUI.PushFlow(tcmFlow);
					});
					UIHelper.SafeSetText(button3D.GetComponentInChildren<Text>(), component.ButtonText);
					num++;
				}
			}
		}
		devMenuPanel.gameObject.SetActive(num > 0);
	}

	private void SetButtonOnClick<T>(Button3D button) where T : StackedUIFlowBase
	{
		if (button == null)
		{
			UnityEngine.Debug.LogErrorFormat("HomeScreenFlow.SetButtonOnClick() - button is null, type={0}", typeof(T));
			return;
		}
		T flow = base.UIBase.GetFlowByType<T>();
		if (flow != null)
		{
			typeButtonMap[typeof(T)] = button;
			button.OnClick.AddListener(delegate
			{
				GoToFlow(flow);
			});
		}
	}

	public Button3DBase GetButtonForFlow<T>()
	{
		if (typeButtonMap.TryGetValue(typeof(T), out var value))
		{
			return value;
		}
		return null;
	}

	public void LockButton<T>(bool locked)
	{
		Button3DBase buttonForFlow = GetButtonForFlow<T>();
		if (buttonForFlow != null)
		{
			buttonForFlow.Interactable = !locked;
		}
	}

	private void GoToFlow(StackedUIFlowBase flow)
	{
		base.UIBase.PushFlow(flow);
	}

	public void HighlightButton<T>()
	{
		foreach (System.Type key in typeButtonMap.Keys)
		{
			if (key == typeof(T))
			{
				Button3DBase button3DBase = typeButtonMap[key];
				if (button3DBase != null)
				{
					button3DBase.AttractHighlighted = true;
				}
			}
		}
	}

	public void ClearHighlights()
	{
		foreach (System.Type key in typeButtonMap.Keys)
		{
			Button3DBase button3DBase = typeButtonMap[key];
			if (button3DBase != null)
			{
				button3DBase.AttractHighlighted = false;
			}
		}
		dormRoomButton.AttractHighlighted = false;
		recCenterButton.AttractHighlighted = false;
