namespace AGUI.StackedUI.Dialog
{
	public class UIMessageDialog : ConfirmUIDialog
	{
		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private Button3D yesButton;

		[SerializeField]
		private Button3D noButton;

		[SerializeField]
		private Transform detailPanel;

		[SerializeField]
		private Graphic detailBackgroundImage;

		[SerializeField]
		private TextMeshProUGUI detailText;

		[SerializeField]
		private TextMeshProUGUI timestampText;

		[SerializeField]
		private GameObject playerDetailsPanel;

		[SerializeField]
		private GameObject roomDetailsPanel;

		[SerializeField]
		private GameObject playerEventDetailsPanel;

		private MessageDialogController GetMessageDialogController(RecNet.Message.MessageType messageType)
		{
			switch (messageType)
			{
			case RecNet.Message.MessageType.GameInvite:
				return new GameInviteController();
			case RecNet.Message.MessageType.GameInviteDeclined:
				return new GameInviteDeclinedController();
			case RecNet.Message.MessageType.GameJoinFailed:
				return new GameJoinFailedController();
			case RecNet.Message.MessageType.PartyActivitySwitch:
				return new PartyActivitySwitchController();
			case RecNet.Message.MessageType.FriendInvite:
				return new FriendInviteController();
			case RecNet.Message.MessageType.VoteToKick:
				return new VoteToKickController();
			case RecNet.Message.MessageType.RequestGameInvite:
				return new RequestGameInviteController();
			case RecNet.Message.MessageType.RequestGameInviteDeclined:
				return new RequestGameInviteDeclinedController();
			case RecNet.Message.MessageType.FriendStatusOnline:
				return new FriendStatusOnlineController();
			case RecNet.Message.MessageType.CoachMessage:
				return new CoachMessageController();
			case RecNet.Message.MessageType.PlayerCheer:
			case RecNet.Message.MessageType.PlayerCheerAnonymous:
				return new CheerMessageController();
			case RecNet.Message.MessageType.FriendRequestAccepted:
				return new FriendRequestAcceptedController();
			case RecNet.Message.MessageType.RoomCoOwnerAdded:
				return new RoomCoOwnerAddedMessageController();
			case RecNet.Message.MessageType.RoomCoOwnerRemoved:
				return new RoomCoOwnerRemovedMessageController();
			case RecNet.Message.MessageType.RoomCoOwnerInvited:
				return new RoomCoOwnerInvitedMessageController();
			case RecNet.Message.MessageType.CreatorPublishedNewRoom:
				return new CreatorPublishedNewRoomMessageController();
			case RecNet.Message.MessageType.PlayerEventInvitation:
				return new PlayerEventInvitationMessageController();
			default:
				throw new NotImplementedException();
			}
		}

		private void InitializeButton(Button3D button, TextMeshProUGUI label, bool interactible, string value)
		{
			button.Interactable = interactible;
			if (string.IsNullOrEmpty(value))
			{
				button.gameObject.SetActive(value: false);
				label.text = string.Empty;
			}
			else
			{
				button.gameObject.SetActive(value: true);
				label.text = value;
			}
		}

		private void DeleteMessage(RecNet.Message message)
		{
			Messages.DeleteMessage(message.Id);
		}

		public void ShowDialog(RecNet.Message message)
		{
			MessageDialogController controller = GetMessageDialogController(message.Type);
			try
			{
				controller.UIDialog = this;
				controller.UIBase = base.UIBase;
				controller.SetMessage(message);
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
				UnityEngine.Debug.LogWarningFormat("{0}.SetMessage() threw an exception. Deleting message.Id: {1}.", controller.GetType().Name, message.Id);
				DeleteMessage(message);
				return;
			}
			RefreshVisuals(controller);
			PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
			{
				if (message.Type == RecNet.Message.MessageType.PlayerCheerAnonymous)
				{
					playerSpecificUIBehaviour.SetPlayer(null);
				}
				else
				{
					playerSpecificUIBehaviour.SetPlayer(message.FromPlayerId);
				}
			}
			RoomSpecificUIBehaviour[] componentsInChildren2 = GetComponentsInChildren<RoomSpecificUIBehaviour>(includeInactive: true);
			foreach (RoomSpecificUIBehaviour roomSpecificUIBehaviour in componentsInChildren2)
			{
				roomSpecificUIBehaviour.SetRoomId(message.RoomId);
			}
			PlayerEventSpecificUIBehaviour[] componentsInChildren3 = GetComponentsInChildren<PlayerEventSpecificUIBehaviour>(includeInactive: true);
			foreach (PlayerEventSpecificUIBehaviour playerEventSpecificUIBehaviour in componentsInChildren3)
			{
				playerEventSpecificUIBehaviour.SetPlayerEventId(message.PlayerEventId);
			}
			CreatePromise().Then(delegate(ConfirmDialogResponses response)
			{
				switch (response)
				{
				case ConfirmDialogResponses.Affirmative:
					controller.Yes();
					DeleteMessage(message);
					break;
				case ConfirmDialogResponses.Negative:
					controller.No();
					DeleteMessage(message);
					break;
				}
			});
		}

		public void RefreshVisuals(MessageDialogController controller)
		{
			bodyText.text = controller.Body;
			playerDetailsPanel.SetActive(controller.IsPlayerDetailEnabled);
			roomDetailsPanel.SetActive(controller.IsRoomDetailEnabled);
			playerEventDetailsPanel.SetActive(controller.IsPlayerEventDetailEnabled);
			InitializeButton(yesButton, yesButton.Label, controller.IsYesEnabled, controller.YesLabel);
			InitializeButton(noButton, noButton.Label, controller.IsNoEnabled, controller.NoLabel);
			detailPanel.gameObject.SetActive(!string.IsNullOrEmpty(controller.Detail));
			detailBackgroundImage.color = controller.DetailColor;
			detailText.text = controller.Detail;
			timestampText.text = controller.Message.SentTime.ToLocalTime().ToString("G");
		}
	}
}
public class MessageConditionalButton : PlayerBasedConditionalButton<Button3D>
{
	private const int MIN_NOTERIETY_FOR_MESSAGE_PRIVILIDGE = -10;

	protected override void UpdatePlayerBasedButtonState()
	{
		base.ButtonState = ((playerWatcher.PlayerId.HasValue && CanSendTextMessageTo(playerWatcher.PlayerId.Value)) ? 1 : 0);
	}

	public static bool CanSendTextMessageTo(long playerId)
	{
		Profile profile = Profiles.Get(playerId);
		if (profile == null || !SingletonMonoBehaviour<SessionManager>.Instance.RateLimitAllowsTextMessage(playerId) || Profiles.LocalProfile.IsJunior() || profile.IsJunior())
		{
			return false;
		}
		Relationship.RelationshipType relationshipType = Relationships.Get(profile.Id)?.Type ?? Relationship.RelationshipType.None;
		bool flag = relationshipType == Relationship.RelationshipType.Friend;
		bool flag2 = Profiles.LocalProfile.Reputation.Noteriety >= -10f;
		if (flag && flag2)
		{
			return true;
		}
		return false;
	}
}
