	public class CreatorPublishedNewRoomMessageController : MessageDialogController
	{
		private long roomId;

		private long creatorId = -1L;

		protected override void Initialize()
		{
			base.IsRoomDetailEnabled = true;
			base.IsPlayerDetailEnabled = false;
			base.IsPlayerEventDetailEnabled = false;
			long? num = base.Message.RoomId;
			roomId = ((!num.HasValue) ? ((long)base.Message.Details) : num.Value);
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
			Profile profile = null;
			if (cachedRoomDetails != null)
			{
				creatorId = cachedRoomDetails.Room.CreatorPlayerId;
				profile = Profiles.Get(creatorId);
				if (profile == null)
				{
					Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
				}
			}
			else
			{
				RecNet.Rooms.GetRoomDetails(roomId).Then(delegate(RoomDetails downloadedRoom)
				{
					this?.RoomSyncedCallback(downloadedRoom);
				});
			}
			SetBodyText(cachedRoomDetails?.Room, profile);
			base.YesLabel = "Visit!";
			base.NoLabel = "Dismiss";
		}

		private void SetBodyText(RecNet.Room room, Profile profile)
		{
			base.Body = string.Format("{0} created a new room: {1}", (profile == null) ? "<creator info loading...>" : profile.DisplayName.ToString(), (room == null) ? "<room name loading...>" : ("^" + room.Name));
		}

		public override void Yes()
		{
			base.Yes();
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
			if (cachedRoomDetails != null)
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(cachedRoomDetails.Room.Name, SessionManager.LoadSceneSources.NOTIFICATION_NEW_ROOM_FROM_CREATOR, isPrivate: false, null);
			}
		}

		private void RoomSyncedCallback(RoomDetails roomDetails)
		{
			Profile profile = null;
			creatorId = roomDetails.Room.CreatorPlayerId;
			profile = Profiles.Get(creatorId);
			if (profile == null)
			{
				Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			}
			SetBodyText(roomDetails.Room, profile);
			base.UIDialog.RefreshVisuals(this);
		}

		private void Profiles_OnProfileUpdated(long id)
		{
			if (id == creatorId)
			{
				Profile profile = Profiles.Get(creatorId);
				SetBodyText(RecNet.Rooms.GetCachedRoomDetails(roomId)?.Room, profile);
				base.UIDialog.RefreshVisuals(this);
				Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
			}
		}
	}
