	public class GameInviteController : MessageDialogController
	{
		private RecNet.Rooms.CanJoinStatus playerTypeJoinStatus;

		protected override void Initialize()
		{
			PlayerPresence playerPresence = Presence.Get(base.Message.FromPlayerId);
			if (playerPresence != null)
			{
				base.Body = "Loading...";
				base.IsYesEnabled = false;
				base.IsNoEnabled = false;
				playerTypeJoinStatus = null;
				RecNet.Rooms.GetRoomById(playerPresence.GameSession.RoomId).Then(delegate(RecNet.Room room)
				{
					RecNet.Rooms.CheckLocalPlayerCanJoinRoom(room).Then(delegate(RecNet.Rooms.CanJoinStatus canJoinStatus)
					{
						if (this != null)
						{
							playerTypeJoinStatus = canJoinStatus;
							base.NoLabel = "Decline";
							if (playerTypeJoinStatus.CanJoinNow)
							{
								base.Body = "...sent you an invite! Want to join them?";
								base.YesLabel = "Go now!";
							}
							else if (playerTypeJoinStatus.CanJoinWithPlayerTypeSwitch)
							{
								base.Body = $"...sent you an invite to a room that is only accessible to {canJoinStatus.FailureString} players.\n\nWould you like to switch to {LocalPlayerController.GetPlayerModeDescription(canJoinStatus.SuggestedPlayerType)} and join?";
								base.YesLabel = "Switch";
							}
							base.IsYesEnabled = true;
							base.IsNoEnabled = true;
							base.UIDialog.RefreshVisuals(this);
						}
					});
				});
			}
			else
			{
				base.Body = "...sent you an invite! Want to join them?";
				base.YesLabel = "Go now!";
				base.NoLabel = "Decline";
			}
		}

		public override void Yes()
		{
			if (playerTypeJoinStatus != null && playerTypeJoinStatus.SuggestedPlayerType != LocalPlayerController.PlayerType.SCREEN)
			{
				if (playerTypeJoinStatus.SuggestedPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
				{
					SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = VRMovementMode.TELEPORT;
					SingletonMonoBehaviour<LocalPlayerController>.Instance.SetVRDisplayMode();
				}
				else
				{
					SingletonMonoBehaviour<SettingsManager>.Instance.VRMovementMode = VRMovementMode.WALK;
					SingletonMonoBehaviour<LocalPlayerController>.Instance.SetVRDisplayMode();
				}
			}
			AnalyticsHelper.GameInviteMessageResponse(base.Message, accepted: true);
			SingletonMonoBehaviour<SessionManager>.Instance.RunJoinPlayer(base.Message.FromPlayerId, SessionManager.LoadSceneSources.ACCEPTED_GAME_INVITE);
		}

		public override void No()
		{
			AnalyticsHelper.GameInviteMessageResponse(base.Message, accepted: false);
			Messages.SendGameInviteDeclined(base.Message.FromPlayerId);
		}
	}
