	public abstract class MessageDialogController
	{
		public string Body { get; protected set; }

		public string Detail { get; protected set; }

		public Color DetailColor { get; protected set; }

		public string YesLabel { get; protected set; }

		public string NoLabel { get; protected set; }

		public bool IsYesEnabled { get; protected set; }

		public bool IsNoEnabled { get; protected set; }

		public bool IsPlayerDetailEnabled { get; protected set; }

		public bool IsRoomDetailEnabled { get; protected set; }

		public bool IsPlayerEventDetailEnabled { get; protected set; }

		public RecNet.Message Message { get; private set; }

		public StackedUIBase UIBase { get; set; }

		public UIMessageDialog UIDialog { get; set; }

		private void Reset()
		{
			Body = null;
			Detail = null;
			DetailColor = Color.gray;
			YesLabel = null;
			NoLabel = null;
			IsYesEnabled = true;
			IsNoEnabled = true;
			UIBase = null;
			IsPlayerDetailEnabled = true;
			IsRoomDetailEnabled = false;
			IsPlayerEventDetailEnabled = false;
		}

		public void SetMessage(RecNet.Message message)
		{
			Reset();
			Message = message;
			Initialize();
		}

		protected abstract void Initialize();

		public virtual void Yes()
		{
		}

		public virtual void No()
		{
		}
	}
