		}
	}
	public class PlayerEventInvitationMessageController : MessageDialogController
	{
		private long roomId;

		private long eventOwnerId = -1L;

		private long eventId = -1L;

		private PlayerEvent eventData;

		protected override void Initialize()
		{
			base.IsPlayerEventDetailEnabled = true;
			base.IsRoomDetailEnabled = false;
			base.IsPlayerDetailEnabled = false;
			long? num = base.Message.RoomId;
			roomId = ((!num.HasValue) ? (-1) : num.Value);
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
			if (cachedRoomDetails == null)
			{
				RecNet.Rooms.GetRoomDetails(roomId).Then(delegate(RoomDetails downloadedRoom)
				{
					this?.RoomSyncedCallback(downloadedRoom);
				});
			}
			eventOwnerId = base.Message.FromPlayerId;
			Profile profile = Profiles.Get(eventOwnerId);
			if (profile == null)
			{
				Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			}
			long? playerEventId = base.Message.PlayerEventId;
			eventId = ((!playerEventId.HasValue) ? (-1) : playerEventId.Value);
			eventData = null;
			RecNet.PlayerEvents.GetPlayerEventById(eventId).Then(delegate(PlayerEvent eventDetails)
			{
				if (this != null)
				{
					eventData = eventDetails;
					Profile profile2 = Profiles.Get(eventOwnerId);
					RoomDetails cachedRoomDetails2 = RecNet.Rooms.GetCachedRoomDetails(roomId);
					SetBodyText(cachedRoomDetails2, profile2, eventData);
					base.UIDialog.RefreshVisuals(this);
				}
			});
			SetBodyText(cachedRoomDetails, profile, eventData);
			base.YesLabel = "Going";
			base.NoLabel = "Skip";
		}

		private void SetBodyText(RoomDetails roomDetails, Profile profile, PlayerEvent eventDetails)
		{
			base.Body = string.Format("{0} invited you to the event '{1}' in room {2}\n\nTime: {3}", (profile == null) ? "<creator info loading...>" : profile.DisplayName.ToString(), (eventDetails == null) ? "<event name loading...>" : eventDetails.Name, (roomDetails == null) ? "<room name loading...>" : ("^" + roomDetails.Room.Name), (eventDetails == null) ? "<event time loading...>" : eventDetails.StartTime.ToLocalTime().ToString("G"));
		}

		public override void Yes()
		{
			base.Yes();
			AnalyticsHelper.RSVPToEvent(eventData, eventId, PlayerEventResponseType.Yes);
			RecNet.PlayerEvents.RespondToEvent(eventId, PlayerEventResponseType.Yes);
		}

		public override void No()
		{
			base.No();
			AnalyticsHelper.RSVPToEvent(eventData, eventId, PlayerEventResponseType.No);
			RecNet.PlayerEvents.RespondToEvent(eventId, PlayerEventResponseType.No);
		}

		private void RoomSyncedCallback(RoomDetails roomDetails)
		{
			Profile profile = Profiles.Get(eventOwnerId);
			SetBodyText(roomDetails, profile, eventData);
			base.UIDialog.RefreshVisuals(this);
		}

		private void Profiles_OnProfileUpdated(long id)
		{
			if (id == eventOwnerId)
			{
				Profile profile = Profiles.Get(eventOwnerId);
				RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId);
				SetBodyText(cachedRoomDetails, profile, eventData);
				base.UIDialog.RefreshVisuals(this);
				Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
			}
		}
	}
	public class RequestGameInviteController : MessageDialogController
