public class MessagesScreenItem : UnityEngine.MonoBehaviour
{
	[Serializable]
	private class _MessageColors
	{
		public Color GameInvite;

		public Color GameInviteDeclined;

		public Color GameJoinFailed;

		public Color PartyActivitySwitch;

		public Color FriendInvite;

		public Color VoteToKick;

		public Color RequestGameInvite;

		public Color RequestGameInviteDeclined;

		public Color FriendStatusOnline;

		public Color TextMessage;

		public Color CoachMessage;

		public Color RoomCoOwnerAddedMessage;

		public Color RoomCoOwnerRemovedMessage;

		public Color CheerMessage;

		public Color FriendRequestAccepted;

		public Color CreatorPublishedNewRoom;

		public Color PlayerEventInvitation;
	}

	[SerializeField]
	private TextMeshProUGUI contentText;

	[SerializeField]
	private UnityEngine.UI.Image backgroundImage;

	[SerializeField]
	private GameObject profileButton;

	[SerializeField]
	private GameObject roomDetailsButton;

	private RecNet.Message model;

	[SerializeField]
	private _MessageColors MessageColors;

	public RecNet.Message Model
	{
		get
		{
			return model;
		}
		set
		{
			model = value;
			Refresh();
		}
	}

	private void Refresh()
	{
		ConfigureLayout(model);
		contentText.text = FormatMessage(model);
		backgroundImage.color = GetColorForMessageType(model.Type);
		PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>();
		foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
		{
			if (model.Type == RecNet.Message.MessageType.PlayerCheerAnonymous)
			{
				playerSpecificUIBehaviour.SetPlayer(null);
			}
			else
			{
				playerSpecificUIBehaviour.SetPlayer(model.FromPlayerId);
			}
		}
		RoomSpecificUIBehaviour[] componentsInChildren2 = GetComponentsInChildren<RoomSpecificUIBehaviour>(includeInactive: true);
		foreach (RoomSpecificUIBehaviour roomSpecificUIBehaviour in componentsInChildren2)
		{
			roomSpecificUIBehaviour.SetRoomId(model.RoomId);
		}
		PlayerEventSpecificUIBehaviour[] componentsInChildren3 = GetComponentsInChildren<PlayerEventSpecificUIBehaviour>(includeInactive: true);
		foreach (PlayerEventSpecificUIBehaviour playerEventSpecificUIBehaviour in componentsInChildren3)
		{
			playerEventSpecificUIBehaviour.SetPlayerEventId(model.PlayerEventId);
		}
	}

	private void ConfigureLayout(RecNet.Message message)
	{
		switch (message.Type)
		{
		case RecNet.Message.MessageType.CreatorPublishedNewRoom:
			profileButton.SetActive(value: false);
			roomDetailsButton.SetActive(value: true);
			break;
		case RecNet.Message.MessageType.PlayerEventInvitation:
			profileButton.SetActive(value: false);
			roomDetailsButton.SetActive(value: true);
			break;
		default:
			profileButton.SetActive(value: true);
			roomDetailsButton.SetActive(value: false);
			break;
		}
	}

	private string FormatMessage(RecNet.Message message)
	{
		switch (message.Type)
		{
		case RecNet.Message.MessageType.GameInvite:
		case RecNet.Message.MessageType.PartyActivitySwitch:
			return "Game Invite";
		case RecNet.Message.MessageType.GameInviteDeclined:
			return "Game Invite Declined";
		case RecNet.Message.MessageType.GameJoinFailed:
		{
			int num = (int)message.Details;
			return (num != 0) ? ("Failed To Join Your Game (+" + num + " party members)") : "Failed To Join Your Game";
		}
		case RecNet.Message.MessageType.FriendInvite:
			return "Friend Request";
		case RecNet.Message.MessageType.FriendRequestAccepted:
			return "Friend Request Accepted";
		case RecNet.Message.MessageType.VoteToKick:
			return "Vote to kick?";
		case RecNet.Message.MessageType.FriendStatusOnline:
			return "Friend is Online";
		case RecNet.Message.MessageType.RequestGameInvite:
			return "Request Invite";
		case RecNet.Message.MessageType.RequestGameInviteDeclined:
			return "Request Invite Declined";
		case RecNet.Message.MessageType.PlayerCheer:
		case RecNet.Message.MessageType.PlayerCheerAnonymous:
		{
			PlayerCheering.CheerCategory cheerCategory = (PlayerCheering.CheerCategory)message.Details;
			string cheerCategoryText = SingletonMonoBehaviour<ModerationManager>.Instance.GetCheerCategoryText(cheerCategory);
			string arg2 = ((message.Type != RecNet.Message.MessageType.PlayerCheerAnonymous) ? string.Empty : " [Anonymous]");
			return $"Cheers - {cheerCategoryText}{arg2}";
		}
		case RecNet.Message.MessageType.CoachMessage:
			return "Message from Coach";
		case RecNet.Message.MessageType.RoomCoOwnerAdded:
		case RecNet.Message.MessageType.RoomCoOwnerRemoved:
		case RecNet.Message.MessageType.RoomCoOwnerInvited:
		{
			long? roomId3 = message.RoomId;
			long roomId2 = ((!roomId3.HasValue) ? ((long)message.Details) : roomId3.Value);
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId2);
			if (cachedRoomDetails == null)
			{
				RecNet.Rooms.GetRoomDetails(roomId2).Then((Action<RoomDetails>)delegate
				{
					if (this != null)
					{
						Refresh();
					}
				});
			}
			if (message.Type == RecNet.Message.MessageType.RoomCoOwnerAdded)
			{
				return string.Format("You are added as co-owner to {0}", (cachedRoomDetails == null) ? "<room name loading...>" : ("^" + cachedRoomDetails.Room.Name));
			}
			if (message.Type == RecNet.Message.MessageType.RoomCoOwnerRemoved)
			{
				return string.Format("You are no longer a co-owner of {0}", (cachedRoomDetails == null) ? "<room name loading...>" : ("^" + cachedRoomDetails.Room.Name));
			}
			if (message.Type == RecNet.Message.MessageType.RoomCoOwnerInvited)
			{
				return string.Format("You were invited to be a co-owner to {0}", (cachedRoomDetails == null) ? "<room name loading...>" : ("^" + cachedRoomDetails.Room.Name));
			}
			throw new NotImplementedException();
		}
		case RecNet.Message.MessageType.CreatorPublishedNewRoom:
		{
			long? roomId4 = message.RoomId;
			long roomId2 = ((!roomId4.HasValue) ? ((long)message.Details) : roomId4.Value);
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId2);
			string arg = "<creator loading...>";
			if (cachedRoomDetails != null)
			{
				Profile profile2 = Profiles.Get(cachedRoomDetails.Room.CreatorPlayerId);
				if (profile2 != null)
				{
					arg = profile2.DisplayName;
				}
				else
				{
					Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
				}
			}
			else
			{
				RecNet.Rooms.GetRoomDetails(roomId2).Then((Action<RoomDetails>)delegate
				{
					if (this != null)
					{
						Refresh();
					}
				});
			}
			return string.Format("{0} created a new room: {1}", arg, (cachedRoomDetails == null) ? "<room name loading...>" : ("^" + cachedRoomDetails.Room.Name));
		}
		case RecNet.Message.MessageType.PlayerEventInvitation:
		{
			long? playerEventId = message.PlayerEventId;
			long playerEventId2 = ((!playerEventId.HasValue) ? (-1) : playerEventId.Value);
			long? roomId = message.RoomId;
			long roomId2 = ((!roomId.HasValue) ? ((long)message.Details) : roomId.Value);
			RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(roomId2);
			string arg = "<creator loading...>";
			if (cachedRoomDetails != null)
			{
				Profile profile = Profiles.Get(message.FromPlayerId);
				if (profile != null)
				{
					arg = profile.DisplayName;
				}
				else
				{
					Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
				}
			}
			else
			{
				RecNet.Rooms.GetRoomDetails(roomId2).Then((Action<RoomDetails>)delegate
				{
					if (this != null)
					{
						Refresh();
					}
				});
			}
			PlayerEvent eventData = null;
			IPromise<PlayerEvent> promise = RecNet.PlayerEvents.GetPlayerEventById(playerEventId2).Then(delegate(PlayerEvent eventDetails)
			{
				eventData = eventDetails;
			});
			if (eventData == null)
			{
				promise.Then(delegate(PlayerEvent eventDetails)
				{
					if (eventDetails != null && this != null)
					{
						Refresh();
					}
				});
			}
			return string.Format("{0} invited you to the event '{1}' in room {2}", arg, (eventData == null) ? "<event details loading...>" : eventData.Name, (cachedRoomDetails == null) ? "<room name loading...>" : ("^" + cachedRoomDetails.Room.Name));
		}
		default:
			UnityEngine.Debug.LogErrorFormat("MessagesScreenItem.FormatMessage() - Unhandled MessageType: {0}", model.Type);
			return model.Type.ToString();
		}
	}

	private Color GetColorForMessageType(RecNet.Message.MessageType messageType)
	{
		switch (messageType)
		{
		case RecNet.Message.MessageType.GameInvite:
			return MessageColors.GameInvite;
		case RecNet.Message.MessageType.GameInviteDeclined:
			return MessageColors.GameInviteDeclined;
		case RecNet.Message.MessageType.GameJoinFailed:
			return MessageColors.GameJoinFailed;
		case RecNet.Message.MessageType.PartyActivitySwitch:
			return MessageColors.PartyActivitySwitch;
		case RecNet.Message.MessageType.FriendInvite:
			return MessageColors.FriendInvite;
		case RecNet.Message.MessageType.VoteToKick:
			return MessageColors.VoteToKick;
		case RecNet.Message.MessageType.RequestGameInvite:
			return MessageColors.RequestGameInvite;
		case RecNet.Message.MessageType.RequestGameInviteDeclined:
			return MessageColors.RequestGameInviteDeclined;
		case RecNet.Message.MessageType.FriendStatusOnline:
			return MessageColors.FriendStatusOnline;
		case RecNet.Message.MessageType.CoachMessage:
			return MessageColors.CoachMessage;
		case RecNet.Message.MessageType.PlayerCheer:
		case RecNet.Message.MessageType.PlayerCheerAnonymous:
			return MessageColors.CheerMessage;
		case RecNet.Message.MessageType.FriendRequestAccepted:
			return MessageColors.FriendRequestAccepted;
		case RecNet.Message.MessageType.RoomCoOwnerAdded:
		case RecNet.Message.MessageType.RoomCoOwnerInvited:
			return MessageColors.RoomCoOwnerAddedMessage;
		case RecNet.Message.MessageType.RoomCoOwnerRemoved:
			return MessageColors.RoomCoOwnerRemovedMessage;
		case RecNet.Message.MessageType.CreatorPublishedNewRoom:
			return MessageColors.CreatorPublishedNewRoom;
		case RecNet.Message.MessageType.PlayerEventInvitation:
			return MessageColors.PlayerEventInvitation;
		default:
			UnityEngine.Debug.LogErrorFormat("MessagesScreenItem.GetColorForMessageType() - Unhandled MessageType: {0}", messageType);
			return Color.gray;
		}
	}

	[SkipRename]
	public void Button_Delete()
	{
		Messages.DeleteMessage(model.Id);
	}

	[SkipRename]
	public void Button_ShowDetails()
	{
		WatchUI componentInParent = GetComponentInParent<WatchUI>();
		if (componentInParent != null)
		{
			componentInParent.ShowMessageDialog(model);
		}
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
		Refresh();
	}
}
public class MessagesWatchUIFlow : WatchUIFlow
{
	[Header("Messages / Notifications")]
	[SerializeField]
	private MessagesScreenItem itemTemplate;

	[SerializeField]
	private RectTransform contentPanel;

	[SerializeField]
	private Transform pageNumberPanel;

	[SerializeField]
	private Transform noMessagesPanel;

	[SerializeField]
	private Selectable previousPageButton;

	[SerializeField]
	private Selectable nextPageButton;

	[SerializeField]
	private TextMeshProUGUI currentPageText;

	[SerializeField]
	private TextMeshProUGUI totalPagesText;

	[SerializeField]
	private int itemsPerPage = 5;

	[SerializeField]
	private int largeItemsPerPage = 5;

	private PagedList<RecNet.Message> pagedMessageList;

	[Header("Subscreens")]
	[SerializeField]
	private SubscreenControl subscreenControl;

	[SerializeField]
	private Subscreen notificationsSubscreen;

	[SerializeField]
	private Subscreen chatsSubscreen;

	[Header("Chats")]
	[SerializeField]
	private ChooseFriendsDialog chooseFriendsDialogPrefab;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private ChatThreadPagedGrid chatThreadPagedGrid;

	private ChatThreadScreen chatThreadScreen;

	private PlayerDetailsWatchUIFlow playerDetailsScreen;

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		if (Profiles.LocalProfile.IsJunior())
		{
			subscreenControl.SetDefaultSubscreen(notificationsSubscreen);
			return;
		}
		playerDetailsScreen = base.WatchUI.GetFlowByType<PlayerDetailsWatchUIFlow>();
		chatThreadScreen = base.WatchUI.GetFlowByType<ChatThreadScreen>();
		chatThreadPagedGrid.SetChatThreads(Enumerable.Empty<ChatThread>());
		chatThreadPagedGrid.SetEmptyDisplayText("Loading...");
		Chats.OnChatUpdated += UpdateChats;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Chats.OnChatUpdated -= UpdateChats;
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (Profiles.LocalProfile.IsJunior())
		{
			subscreenControl.ShowSubscreen(notificationsSubscreen);
		}
		else
		{
			if (oldFlow.GetType() == typeof(HomeScreenFlow))
			{
				if (Messages.MessageList.Count > 0)
				{
					subscreenControl.ShowSubscreen(notificationsSubscreen);
				}
				else
				{
					subscreenControl.ShowSubscreen(chatsSubscreen);
				}
				subscreenControl.ActiveSubscreen.Button.ForcePressed();
			}
			UpdateChats(null);
		}
		if (pagedMessageList == null)
		{
			pagedMessageList = new PagedList<RecNet.Message>(Messages.MessageList, itemsPerPage);
		}
		Resize(base.WatchUI.Size, enteringFlow: false);
		pagedMessageList.Changed += OnPagedMessageListChanged;
		Messages.OnMessageListUpdated += OnRecNetMessageListUpdated;
		Refresh();
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		Messages.OnMessageListUpdated -= OnRecNetMessageListUpdated;
		if (pagedMessageList != null)
		{
			pagedMessageList.Changed -= OnPagedMessageListChanged;
		}
		Clear();
	}

	protected override void Resize(SizeOption size, bool enteringFlow)
	{
		base.Resize(size, enteringFlow);
		if (pagedMessageList != null)
		{
			pagedMessageList.ItemsPerPage = ((size != SizeOption.LARGE) ? itemsPerPage : largeItemsPerPage);
			Refresh();
		}
	}

	private void OnPagedMessageListChanged()
	{
		Refresh();
	}

	private void OnRecNetMessageListUpdated(Messages.UpdateType updateType)
	{
		Refresh();
	}

	private void Clear()
	{
		for (int i = 0; i < contentPanel.childCount; i++)
		{
			Transform child = contentPanel.GetChild(i);
			UnityEngine.Object.Destroy(child.gameObject);
		}
	}

	private void Refresh()
	{
		Clear();
		foreach (RecNet.Message item in pagedMessageList.GetPage())
		{
			MessagesScreenItem messagesScreenItem = UnityEngine.Object.Instantiate(itemTemplate);
			messagesScreenItem.transform.SetParent(contentPanel, worldPositionStays: false);
			messagesScreenItem.Model = item;
		}
		previousPageButton.interactable = pagedMessageList.CurrentPage > 0;
		nextPageButton.interactable = pagedMessageList.CurrentPage < pagedMessageList.TotalPages - 1;
		currentPageText.text = (pagedMessageList.CurrentPage + 1).ToString();
		totalPagesText.text = pagedMessageList.TotalPages.ToString();
		pageNumberPanel.gameObject.SetActive(pagedMessageList.TotalItems > 0);
		noMessagesPanel.gameObject.SetActive(pagedMessageList.TotalItems == 0);
	}

	private void UpdateChats(ChatThread chatThread)
	{
		Chats.GetRecentChats().Then(delegate(List<ChatThread> chats)
		{
			chatThreadPagedGrid.SetChatThreads(chats);
			if (chats.Count == 0)
			{
				chatThreadPagedGrid.SetEmptyDisplayText("No chat messages");
			}
		});
	}

	[SkipRename]
	public void Button_PreviousPage()
	{
		pagedMessageList.CurrentPage--;
	}

	[SkipRename]
	public void Button_NextPage()
	{
		pagedMessageList.CurrentPage++;
	}

	[SkipRename]
	public void Button_StartNewChatThread()
	{
		if (Profiles.LocalProfile.IsJunior() || !(chooseFriendsDialogPrefab != null))
		{
			return;
		}
		base.WatchUI.ShowTemporaryDialog(chooseFriendsDialogPrefab, ChooseFriendsDialog.DisplayMode.StartChat, null, (WatchAttractor.EffectFlags)0).Then(delegate(List<Profile> profiles)
		{
			if (chatThreadScreen != null)
			{
				chatThreadScreen.ShowScreen(profiles, ChatThreadScreen.CreateChatSource.CreateChatScreen);
			}
		});
	}

	[SkipRename]
	public void Button_OpenChatThread(ChatThread chatThread)
	{
		if (chatThreadScreen != null && !Profiles.LocalProfile.IsJunior())
		{
			chatThreadScreen.ShowScreen(chatThread);
		}
	}

	[SkipRename]
	public void Button_PlayerDetails(int playerId)
	{
		if (playerDetailsScreen != null)
		{
			Profile profile = Profiles.Get(playerId);
			if (profile != null)
			{
				playerDetailsScreen.SetProfile(profile);
				base.UIBase.PushFlow(playerDetailsScreen);
			}
		}
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class UINUXReportDialog : ConfirmUIDialog
	{
		[SerializeField]
		private Button3D[] reportButtons;

		private void Awake()
		{
			reportButtons[0].AttractHighlighted = true;
		}

		[SkipRename]
		public void Button_Report()
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.PlayDelayed(ScreenSpaceNotificationManager.NotificationType.Major, "Thanks for your report.", "We will investigate.", 4f, 0.5f);
			if (reportButtons != null)
			{
				Button3D[] array = reportButtons;
				foreach (Button3D button3D in array)
				{
					button3D.Interactable = false;
				}
			}
			Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}
