public class CheerPlayerWatchUIFlow : PlayerWatchUIFlow
{
	[SerializeField]
	private ToggleButton3D anonymousToggle;

	[Header("Credits")]
	[SerializeField]
	private TextMeshProUGUI cheerCreditText;

	[SerializeField]
	private string cheerCreditString;

	[SerializeField]
	private string cheerNoCreditString;

	[SerializeField]
	private string cheerGuestCreditString;

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		RefreshCreditText();
	}

	private void RefreshCreditText()
	{
		Profile localProfile = Profiles.LocalProfile;
		string text = cheerGuestCreditString;
		anonymousToggle.gameObject.SetActive(localProfile.Verified);
		if (localProfile.Verified)
		{
			text = ((localProfile.Reputation.CheerCredit != 0) ? string.Format(cheerCreditString, localProfile.Reputation.CheerCredit) : cheerNoCreditString);
		}
		cheerCreditText.text = text;
	}

	public void Button_General()
	{
		CheerPlayerHelper(PlayerCheering.CheerCategory.General);
	}

	public void Button_Helpful()
	{
		CheerPlayerHelper(PlayerCheering.CheerCategory.Helpful);
	}

	public void Button_Sportmanship()
	{
		CheerPlayerHelper(PlayerCheering.CheerCategory.Sportmanship);
	}

	public void Button_GreatHost()
	{
		CheerPlayerHelper(PlayerCheering.CheerCategory.GreatHost);
	}

	public void Button_Creative()
	{
		CheerPlayerHelper(PlayerCheering.CheerCategory.Creative);
	}

	private void CheerPlayerHelper(PlayerCheering.CheerCategory cheerCategory)
	{
		if (base.CurrentProfile != null)
		{
			CreateCheer(base.CurrentProfile.Id, cheerCategory, anonymousToggle.IsOn);
			PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>();
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
			{
				playerSpecificUIBehaviour.SetPlayer(base.CurrentProfile.Id);
			}
		}
	}

	private void CreateCheer(long playerId, PlayerCheering.CheerCategory cheerCategory, bool anonymous)
	{
		PlayerCheering.CreateCheer(playerId, cheerCategory, anonymous, delegate(string wwwError, OkResponse okResponse)
		{
			if (!string.IsNullOrEmpty(wwwError))
			{
				UnityEngine.Debug.LogError("Failed to cheer player " + wwwError);
			}
			if (okResponse.Success)
			{
				AnalyticsHelper.CheerPlayer(playerId, cheerCategory, anonymous);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Your cheer is sent.", 3f);
				if (Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerEvents.CheeredPlayer();
				}
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, okResponse.Message, 4f);
			}
			RefreshCreditText();
		});
	}
}
public class FriendConditionalButton : PlayerBasedConditionalButton<Button3D>
{
	public enum FriendButtonState
	{
		Disabled,
		Friend,
		Unfriend,
		Pending,
		Blocked
	}

	[SerializeField]
	private Sprite friendSprite;

	[SerializeField]
	private Sprite unfriendSprite;

	[SerializeField]
	private string friendButtonTooltipText;

	[SerializeField]
	private string unfriendButtonTooltipText;

	[SerializeField]
	private string pendingFriendButtonTooltipText;

	[SerializeField]
	private string blockedButtonTooltipText;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private Tooltip tooltip;

	protected override void RunButtonAction()
	{
		switch ((FriendButtonState)base.ButtonState)
		{
		case FriendButtonState.Friend:
			SendFriendRequest();
			break;
		case FriendButtonState.Unfriend:
			TryUnfriend();
			break;
		}
	}

	private void TryUnfriend()
	{
		if (!playerWatcher.PlayerId.HasValue)
		{
			return;
		}
		string bodyText = $"Are you sure you want to unfriend\n{playerWatcher.CurrentProfile.DisplayName}\n@{playerWatcher.CurrentProfile.Username}? ";
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog("Unfriend?", bodyText).Then(delegate(ConfirmDialogResponses r)
		{
			if (r == ConfirmDialogResponses.Affirmative)
			{
				Relationships.RemoveFriend(playerWatcher.PlayerId.Value);
			}
		});
	}

	protected override void UpdatePlayerBasedButtonState()
	{
		Relationship.RelationshipType relationshipType = Relationship.RelationshipType.None;
		Relationship relationship = ((!playerWatcher.PlayerId.HasValue) ? null : Relationships.Get(playerWatcher.PlayerId.Value));
		bool flag = false;
		if (relationship != null)
		{
			relationshipType = relationship.Type;
			flag = relationship.Ignored != Relationship.ReciprocalStatus.None;
		}
		switch (relationshipType)
		{
		case Relationship.RelationshipType.None:
			base.ButtonState = ((!flag) ? 1 : 4);
			break;
		case Relationship.RelationshipType.Friend:
			base.ButtonState = 2;
			break;
		case Relationship.RelationshipType.FriendRequestSent:
		case Relationship.RelationshipType.FriendRequestReceived:
			base.ButtonState = ((!flag) ? 3 : 4);
			break;
		default:
			base.ButtonState = 0;
			break;
		}
	}

	protected override bool IsInteractable()
	{
		return base.IsInteractable() && base.ButtonState != 3 && base.ButtonState != 4;
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		if (base.LabelText != null)
		{
			switch ((FriendButtonState)base.ButtonState)
			{
			case FriendButtonState.Unfriend:
				base.LabelText.text = "Unfriend";
				UIHelper.SafeSetSprite(base.ButtonImage, unfriendSprite);
				button.targetGraphic.color = button.ToggleColor;
				tooltip.Message = unfriendButtonTooltipText;
				break;
			case FriendButtonState.Blocked:
				base.LabelText.text = "Blocked";
				UIHelper.SafeSetSprite(base.ButtonImage, unfriendSprite);
				button.targetGraphic.color = button.ToggleColor;
				tooltip.Message = blockedButtonTooltipText;
				break;
			case FriendButtonState.Pending:
				base.LabelText.text = "Pending";
				UIHelper.SafeSetSprite(base.ButtonImage, friendSprite);
				button.targetGraphic.color = button.BaseColor;
				tooltip.Message = pendingFriendButtonTooltipText;
				break;
			default:
				base.LabelText.text = "Friend";
				UIHelper.SafeSetSprite(base.ButtonImage, friendSprite);
				button.targetGraphic.color = button.BaseColor;
				tooltip.Message = friendButtonTooltipText;
				break;
			}
		}
	}

	private void SendFriendRequest()
	{
		Relationships.SendFriendRequest(playerWatcher.PlayerId.Value, delegate(string error)
		{
			if (!string.IsNullOrEmpty(error))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Failed to send friend request.", 2f);
			}
			else if (Player.LocalPlayerExists)
			{
				Player.LocalPlayer.PlayerEvents.AddedFriend((int)playerWatcher.PlayerId.Value);
			}
		});
	}
}
public class GoToConditionalButton : PlayerBasedConditionalButton<Button3D>
{
	public enum GoToButtonState
	{
		Disabled,
		Join,
		RequestJoin,
		Full,
		PlayerTypeDisallowed
	}

	private RecNet.Rooms.CanJoinStatus playerTypeJoinStatus;

	private PlayerPresence GetPlayerPresence()
	{
		return (!playerWatcher.PlayerId.HasValue) ? null : Presence.Get(playerWatcher.PlayerId.Value);
	}

	protected override void UpdatePlayerBasedButtonState()
	{
		if (SingletonMonoBehaviour<SessionManager>.Instance.LeaveSceneStarted)
		{
			base.ButtonState = 0;
			return;
		}
		PlayerPresence playerPresence = GetPlayerPresence();
		if (playerPresence == null || playerPresence.GameSession == null || !playerPresence.AppearsOnlineToMe)
		{
			base.ButtonState = 0;
			return;
		}
		if (Player.FindLocalPlayer(playerWatcher.PlayerId.Value) != null)
		{
			base.ButtonState = 0;
			return;
		}
		if (playerPresence.GameSession.Location == RoomSceneLocations.INVALID)
		{
			base.ButtonState = 0;
			return;
		}
		if (!SingletonMonoBehaviour<SessionManager>.Instance.JuniorPlayerJoinCheck(playerWatcher.PlayerId.Value))
		{
			base.ButtonState = 0;
			return;
		}
		if (playerPresence.GameSession.IsFull)
		{
			base.ButtonState = 3;
			return;
		}
		Relationship.RelationshipType relationshipType = Relationships.Get(playerWatcher.PlayerId.Value)?.Type ?? Relationship.RelationshipType.None;
		if (relationshipType == Relationship.RelationshipType.Friend && !playerPresence.GameSession.Private)
		{
			base.ButtonState = 1;
		}
		else if (SingletonMonoBehaviour<SessionManager>.Instance.RateLimitAllowsRequestInvite(playerWatcher.PlayerId.Value))
		{
			base.ButtonState = 2;
		}
		else
		{
			base.ButtonState = 0;
			Invoke("UpdateButton", 5f);
		}
		playerTypeJoinStatus = null;
		RecNet.Rooms.GetRoomById(playerPresence.GameSession.RoomId).Then(delegate(RecNet.Room room)
		{
			RecNet.Rooms.CheckLocalPlayerCanJoinRoom(room).Then(delegate(RecNet.Rooms.CanJoinStatus canJoinStatus)
			{
				playerTypeJoinStatus = canJoinStatus;
				if (!playerTypeJoinStatus.CanJoinNow && !playerTypeJoinStatus.CanJoinWithPlayerTypeSwitch)
				{
					base.ButtonState = 4;
				}
			});
		});
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		switch ((GoToButtonState)base.ButtonState)
		{
		case GoToButtonState.Full:
			UIHelper.SafeSetText(base.LabelText, "Game Full");
			break;
		case GoToButtonState.PlayerTypeDisallowed:
		{
			string text = ((playerTypeJoinStatus == null) ? "Cannot join" : playerTypeJoinStatus.FailureString);
			UIHelper.SafeSetText(base.LabelText, text);
			break;
		}
		default:
			UIHelper.SafeSetText(base.LabelText, "Go To");
			break;
		}
	}

	protected override void RunButtonAction()
	{
		if (playerTypeJoinStatus == null || playerTypeJoinStatus.CanJoinNow)
		{
			TryJoin();
		}
		else if (playerTypeJoinStatus.CanJoinWithPlayerTypeSwitch)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowSwitchPlayerTypeAndJoinDialog(playerTypeJoinStatus, TryJoin);
		}
		else
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowPlayerTypeNotAllowedDialog(playerTypeJoinStatus);
		}
	}

	private void TryJoin()
	{
		switch ((GoToButtonState)base.ButtonState)
		{
		case GoToButtonState.Join:
			SingletonMonoBehaviour<SessionManager>.Instance.RunJoinPlayer(playerWatcher.PlayerId.Value, SessionManager.LoadSceneSources.PEOPLE_MENU);
			break;
		case GoToButtonState.RequestJoin:
			SingletonMonoBehaviour<SessionManager>.Instance.RequestGameInvite(playerWatcher.PlayerId.Value, playerWatcher.CurrentProfile.DisplayName, Presence.GetPlayerStatusString(GetPlayerPresence()));
			break;
		}
		UpdateButton();
	}

	protected override bool IsInteractable()
	{
		return base.IsInteractable() && (base.ButtonState == 1 || base.ButtonState == 2);
	}
}
public class IgnoreConditionalButton : PlayerBasedConditionalButton<ToggleButton3D>
{
	public enum IgnoreButtonState
	{
		Disabled,
		Ignore,
		Unignore
	}

	private bool isOptimistic;

	protected override void RunButtonAction()
	{
		if (isOptimistic)
		{
			return;
		}
		bool flag = base.ButtonState == 1;
		UpdateButtonState(flag);
		foreach (MuteConditionalButton item in MuteConditionalButton.All)
		{
			item.UpdateButtonState(flag);
		}
		Player.SavePlayerIgnored(playerWatcher.PlayerId.Value, flag);
	}

	protected override void UpdatePlayerBasedButtonState()
	{
		UpdateButtonState();
	}

	private void UpdateButtonState(bool? optimisticValue = null)
	{
		bool flag = false;
		isOptimistic = optimisticValue.HasValue;
		if (!isOptimistic)
		{
			Relationship relationship = ((!playerWatcher.PlayerId.HasValue) ? null : Relationships.Get(playerWatcher.PlayerId.Value));
			if (relationship != null)
			{
				flag = relationship.Ignored == Relationship.ReciprocalStatus.Local || relationship.Ignored == Relationship.ReciprocalStatus.Mutual;
			}
		}
		else
		{
			flag = optimisticValue.Value;
		}
		if (base.Button.IsOn != flag)
		{
			base.Button.IsOn = flag;
		}
		base.ButtonState = ((!flag) ? 1 : 2);
		if (isOptimistic)
		{
			UpdateUIForNewButtonState();
		}
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		if (base.LabelText != null)
		{
			IgnoreButtonState ignoreButtonState = (IgnoreButtonState)base.ButtonState;
			if (ignoreButtonState == IgnoreButtonState.Unignore)
			{
				base.LabelText.text = "Unblock";
			}
			else
			{
				base.LabelText.text = "Block";
			}
		}
	}
}
public class InviteConditionalButton : PlayerBasedConditionalButton<Button3D>
{
	public enum InviteButtonState
	{
		Disabled,
		OnlineInvite,
		OfflineInvite,
		Full,
		PlayerTypeDisallowed
	}

	private RecNet.Rooms.CanJoinStatus playerTypeJoinStatus;

	private string defaultLabel = "Invite";

	protected override void Awake()
	{
		base.Awake();
		if (base.LabelText != null)
		{
			defaultLabel = base.LabelText.text;
		}
	}

	protected override void UpdatePlayerBasedButtonState()
	{
		InviteButtonState inviteButtonState = InviteButtonState.Disabled;
		PlayerPresence playerPresence = Presence.Get(playerWatcher.PlayerId.Value);
		bool flag = playerPresence?.AppearsOnlineToMe ?? false;
		Player player = Player.FindLocalPlayer(playerWatcher.PlayerId.Value);
		Relationship.RelationshipType relationshipType = Relationships.Get(playerWatcher.PlayerId.Value)?.Type ?? Relationship.RelationshipType.None;
		bool flag2 = relationshipType == Relationship.RelationshipType.Friend;
		bool flag3 = flag && player == null;
		if (!SessionManager.InDormRoom)
		{
			if (flag)
			{
				GameSession localGameSession = GameSessions.LocalGameSession;
				bool flag4 = localGameSession != null && !localGameSession.IsFull;
				playerTypeJoinStatus = RecNet.Rooms.CheckPlayerCanJoinRoomDetails((int)playerPresence.PlayerId, playerPresence.PlayerType, RecNet.Rooms.LocalRoomDetails);
				if (flag3 && flag4)
				{
					if (playerTypeJoinStatus.CanJoinNow || playerTypeJoinStatus.CanJoinWithPlayerTypeSwitch)
					{
						if (SingletonMonoBehaviour<SessionManager>.Instance.RateLimitAllowsOnlineInvite(playerWatcher.PlayerId.Value))
						{
							inviteButtonState = InviteButtonState.OnlineInvite;
						}
						else
						{
							Invoke("UpdatePlayerBasedButtonState", 5f);
						}
					}
					else
					{
						inviteButtonState = InviteButtonState.PlayerTypeDisallowed;
					}
				}
			}
			else if (!Profiles.LocalProfile.IsJunior() && !playerWatcher.CurrentProfile.IsJunior() && flag2 && playerWatcher.CurrentProfile.Verified)
			{
				if (SingletonMonoBehaviour<SessionManager>.Instance.RateLimitAllowsOfflineInvite(playerWatcher.PlayerId.Value))
				{
					inviteButtonState = InviteButtonState.OfflineInvite;
				}
				else
				{
					Invoke("UpdatePlayerBasedButtonState", 5f);
				}
			}
		}
		base.ButtonState = (int)inviteButtonState;
	}

	protected override void RunButtonAction()
	{
		switch ((InviteButtonState)base.ButtonState)
		{
		case InviteButtonState.OnlineInvite:
		{
			PlayerPresence playerPresence = Presence.Get(playerWatcher.PlayerId.Value);
			string playerStatusString = Presence.GetPlayerStatusString(playerPresence);
			SingletonMonoBehaviour<SessionManager>.Instance.InvitePlayerToGame(playerWatcher.PlayerId.Value, playerWatcher.CurrentProfile.DisplayName, playerStatusString);
			break;
		}
		case InviteButtonState.OfflineInvite:
			SingletonMonoBehaviour<SessionManager>.Instance.OfflineInvitePlayerToGame(playerWatcher.PlayerId.Value, playerWatcher.CurrentProfile.DisplayName);
			break;
		}
		UpdateButtonState();
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		switch ((InviteButtonState)base.ButtonState)
		{
		case InviteButtonState.Full:
			UIHelper.SafeSetText(base.LabelText, "Game Full");
			break;
		case InviteButtonState.PlayerTypeDisallowed:
			if (RecNet.Rooms.LocalRoomDetails.Room.SupportsScreens)
			{
				UIHelper.SafeSetText(base.LabelText, "In VR Mode");
			}
			else
			{
				UIHelper.SafeSetText(base.LabelText, "In Screen Mode");
			}
			break;
		default:
			UIHelper.SafeSetText(base.LabelText, defaultLabel);
			break;
		}
	}

	protected override bool IsInteractable()
	{
		return base.IsInteractable() && (base.ButtonState == 1 || base.ButtonState == 2);
	}
}
