	private Coroutine showImportFriendsButtonRoutine;

	private List<Profile> platformFriendProfiles = new List<Profile>();

	private string searchString = string.Empty;

	private Coroutine searchRoutine;

	private PlayerSpecificUIBehaviour.PlayerDisplayMode peopleDisplayMode;

	private PlayerSpecificUIBehaviour.PlayerDisplayMode PeopleDisplayMode
	{
		get
		{
			return peopleDisplayMode;
		}
		set
		{
			if (peopleDisplayMode != value)
			{
				peopleDisplayMode = value;
				UpdateGridForDisplayMode(resetPage: true);
			}
		}
	}

	private void Awake()
	{
		peopleDisplayMode = defaultDisplayMode;
		pagedGrid.PageChangeEvent += OnGridPageChange;
		searchField.IsValidFunction = delegate(string query)
		{
			searchString = query;
			return !string.IsNullOrEmpty(query) && query.Length >= 2;
		};
	}

	public override void OnAllFlowsInitialized()
	{
		base.OnAllFlowsInitialized();
		playerDetailsFlow = base.UIBase.GetFlowByType<PlayerDetailsWatchUIFlow>();
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		bool flag = oldFlow.GetType() == typeof(PlayerDetailsWatchUIFlow);
		UpdateGridForDisplayMode(!flag);
		if (oldFlow.GetType() == typeof(HomeScreenFlow))
		{
			TargetRoom = RecNet.Rooms.LocalRoomDetails;
		}
		UpdateButtonPresses();
		Relationships.RelationshipUpdated += RelationshipUpdated;
		Presence.OnPlayerPresenceUpdated += PresenceUpdated;
		Player.PlayerCreatedEvent += new Action<Player>(LocalPlayersUpdated);
		Player.PlayerDestroyedEvent += new Action<Player>(LocalPlayersUpdated);
		RecentPlayers.PlayerListUpdated += OnRecentPlayersListUpdated;
		if (!flag)
		{
			int num = GetNearbyPlayersList().Count();
			if (num > 0)
			{
				nearbyPlayersRadioButton.ForcePressed();
			}
			else if (PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Nearby || PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.None)
			{
				friendsRadioButton.ForcePressed();
			}
		}
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		Relationships.RelationshipUpdated -= RelationshipUpdated;
		Presence.OnPlayerPresenceUpdated -= PresenceUpdated;
		Player.PlayerCreatedEvent -= new Action<Player>(LocalPlayersUpdated);
		Player.PlayerDestroyedEvent -= new Action<Player>(LocalPlayersUpdated);
		RecentPlayers.PlayerListUpdated -= OnRecentPlayersListUpdated;
	}

	protected override void Resize(SizeOption size, bool enteringFlow)
	{
		base.Resize(size, enteringFlow);
		if (!enteringFlow)
		{
			UpdatePageGridSize(size, updateGrid: true);
		}
	}

	private void UpdateGridForDisplayMode(bool resetPage = false, bool keepFoundProfiles = false)
	{
		importFriendsGroup.SetActive(value: false);
		bool flag = false;
		switch (PeopleDisplayMode)
		{
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Recent:
			currentProfiles = GetRecentPlayersList();
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Nearby:
			currentProfiles = GetNearbyPlayersList();
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends:
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Club:
			currentProfiles = GetFriendsList();
			if (base.gameObject.activeInHierarchy)
			{
				if (showImportFriendsButtonRoutine != null)
				{
					StopCoroutine(showImportFriendsButtonRoutine);
					showImportFriendsButtonRoutine = null;
				}
				showImportFriendsButtonRoutine = StartCoroutine(ShowImportFriendsRoutine());
			}
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Find:
			flag = true;
			if (!keepFoundProfiles)
			{
				currentProfiles = Enumerable.Empty<Profile>();
				searchField.Text = string.Empty;
				showImportFriendsButtonRoutine = StartCoroutine(ShowImportFriendsRoutine());
			}
			break;
		default:
			throw new NotImplementedException("Unknown error fetching profiles");
		}
		searchRow.SetActive(flag);
		UpdatePageGridSize(base.WatchUI.Size, updateGrid: false);
		noResultsText.gameObject.SetActive(currentProfiles.Count() <= 0 && !flag);
		noResultsText.text = noOneHereString;
		pagedGrid.SetProfiles(currentProfiles, PeopleDisplayMode, resetPage);
	}

	private void UpdatePageGridSize(SizeOption size, bool updateGrid)
	{
		bool flag = PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Find;
		if (size == SizeOption.LARGE)
		{
			pagedGrid.SetPageSize((!flag) ? largeGridSize : largeSearchGridSize, updateGrid);
		}
		else
		{
			pagedGrid.SetPageSize((!flag) ? defaultGridSize : searchGridSize, updateGrid);
		}
	}

	private void UpdateButtonPresses()
	{
		RadioButton3D radioButton3D = null;
		switch (PeopleDisplayMode)
		{
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Recent:
			radioButton3D = recentPlayersRadioButton;
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Nearby:
			radioButton3D = nearbyPlayersRadioButton;
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends:
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Club:
			radioButton3D = friendsRadioButton;
			break;
		case PlayerSpecificUIBehaviour.PlayerDisplayMode.Find:
			radioButton3D = FindRadioButton;
			break;
		}
		if (radioButton3D != null)
		{
			radioButton3D.ForcePressed();
		}
	}

	private void DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode displayMode)
	{
		if (!Player.LocalPlayer.PlayerUI.WatchMenu.Locked)
		{
			base.UIBase.RefreshTopFlow();
			PeopleDisplayMode = displayMode;
		}
	}

	private IEnumerable<Profile> GetNearbyPlayersList()
	{
		return from p in Player.All
			where !p.isLocal
			select Profiles.Get(p.PlayerId) into prof
			where prof != null
			select prof;
	}

	private IEnumerable<Profile> GetFriendsList()
	{
		return from r in Relationships.GetAll()
			where r.IsFriendOrPendingFriend
			orderby r.IsFriend
			select Profiles.Get(r.PlayerID) into prof
			where prof != null
			select prof;
	}

	private IEnumerable<Profile> GetRecentPlayersList()
	{
		List<long> recentPlayersNotInCurrentRoom = RecentPlayers.RecentPlayersNotInCurrentRoom;
		return from prof in recentPlayersNotInCurrentRoom.Select(Profiles.Get)
			where prof != null
			select prof;
	}

	private IEnumerator ShowImportFriendsRoutine()
	{
		yield return FriendImporter.GetPlatformFriendProfiles(delegate(List<Profile> friends)
		{
			platformFriendProfiles = friends;
		});
		bool canImportFriend = FriendImporter.CanImportAFriend(platformFriendProfiles);
		importFriendsGroup.SetActive(canImportFriend);
		importFriendsText.gameObject.SetActive(canImportFriend);
		if (canImportFriend)
		{
			noResultsText.gameObject.SetActive(value: false);
			importFriendsText.text = "It looks like some of your " + SingletonMonoBehaviour<PlatformManager>.Instance.PlatformName + " friends already play Rec Room.\nClick the Find Friends button to see who they are!";
		}
		else
		{
			noResultsText.gameObject.SetActive(value: true);
		}
	}

	[SkipRename]
	public void Button_ShowDetails(Profile profile)
	{
		if (playerDetailsFlow != null)
		{
			playerDetailsFlow.SetProfile(profile);
			playerDetailsFlow.TargetRoom = TargetRoom;
			base.UIBase.PushFlow(playerDetailsFlow);
		}
	}

	[SkipRename]
	public void Button_SetNearbyDisplayMode()
	{
		DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode.Nearby);
	}

	[SkipRename]
	public void Button_SetRecentDisplayMode()
	{
		DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode.Recent);
	}

	[SkipRename]
	public void Button_SetFriendsDisplayMode()
	{
		DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends);
	}

	[SkipRename]
	public void Button_SetFindDisplayMode()
	{
		DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode.Find);
	}

	[SkipRename]
	public void Button_SetClubDisplayMode()
	{
		DisplayModeButtonPressed(PlayerSpecificUIBehaviour.PlayerDisplayMode.Club);
	}

	[SkipRename]
	public void Button_FindPlatformFriends()
	{
		if (FindFriendsAction != null)
		{
			FindFriendsAction();
		}
		SingletonMonoBehaviour<SessionManager>.Instance.ImportFriends((SingletonMonoBehaviour<TutorialManager>.Instance.NUXState != TutorialManager.NUXFlowState.ImportFriendsScreen) ? AnalyticsHelper.ImportFriendsSources.Watch : AnalyticsHelper.ImportFriendsSources.NUX);
	}

	[SkipRename]
	public void Button_Search()
	{
		if (!string.IsNullOrEmpty(searchString))
		{
			AnalyticsHelper.SearchedForPlayer();
			if (searchRoutine != null)
			{
				StopCoroutine(searchRoutine);
			}
			searchRoutine = StartCoroutine(RunSearch(searchString));
		}
	}

	private IEnumerator RunSearch(string searchString)
	{
		searchField.Interactable = false;
		importFriendsGroup.SetActive(value: false);
		currentProfiles = Enumerable.Empty<Profile>();
		noResultsText.text = "Searching...";
		float startTime = UnityEngine.Time.realtimeSinceStartup;
		List<Profile> profiles = new List<Profile>();
		bool searchingForUsername = false;
		if (searchString.StartsWith("@"))
		{
			searchingForUsername = true;
			searchString = searchString.Substring(1);
		}
		yield return Profiles.SearchForPlayer(searchString, delegate(string error, List<Profile> playerList)
		{
			if (string.IsNullOrEmpty(error))
			{
				profiles = playerList;
			}
		});
		profiles.RemoveAll((Profile p) => (long)p.Id == (long)Profiles.LocalProfile.Id);
		if (searchingForUsername)
		{
			profiles.Sort((Profile p1, Profile p2) => string.Compare(p1.Username.GetDecrypted(), p2.Username.GetDecrypted()));
		}
		else
		{
			profiles.Sort((Profile p1, Profile p2) => string.Compare(p1.DisplayName.GetDecrypted(), p2.DisplayName.GetDecrypted()));
		}
		currentProfiles = profiles;
		float timeDiff = UnityEngine.Time.realtimeSinceStartup - startTime;
		if (timeDiff < minSearchTime)
		{
			yield return new WaitForSecondsRealtime(minSearchTime - timeDiff);
		}
		importFriendsGroup.SetActive(value: false);
		pagedGrid.SetProfiles(currentProfiles, PeopleDisplayMode, resetPage: true);
		if (profiles.Count == 0)
		{
			noResultsText.gameObject.SetActive(value: true);
			noResultsText.text = noSearchResultsString;
		}
		searchField.Interactable = true;
	}

	private void OnRecentPlayersListUpdated()
	{
		if (PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Recent)
		{
			UpdateGridForDisplayMode();
		}
	}

	private void PresenceUpdated(long id)
	{
		if (currentProfiles != null && currentProfiles.Any((Profile prof) => prof.Id.GetDecrypted() == id))
		{
			UpdateGridForDisplayMode(resetPage: false, keepFoundProfiles: true);
		}
	}

	private void RelationshipUpdated(long? playerId)
	{
		if (PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends)
		{
			UpdateGridForDisplayMode();
		}
	}

	private void LocalPlayersUpdated(Player modifiedPlayer)
	{
		if (modifiedPlayer != null && modifiedPlayer != Player.LocalPlayer && PeopleDisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Nearby)
		{
			UpdateGridForDisplayMode();
		}
	}

	private void OnGridPageChange()
	{
		base.UIBase.RefreshTopFlow();
	}
}
namespace RecRoom.AGUI
{
	public class PlatformFriendButton : UnityEngine.MonoBehaviour
	{
		[Autofill(AutofillType.Self, false)]
		[SerializeField]
		private Button3D button;

		[Header("Player Info")]
		[SerializeField]
		private RawImage rrImage;

		[SerializeField]
		private Text rrName;

		[SerializeField]
		private RawImage platformImage;

		[SerializeField]
		private Text platformName;

		[Header("Icons")]
		[SerializeField]
		private UnityEngine.UI.Image addFriendImage;

		[SerializeField]
		private Sprite tick;

		[SerializeField]
		private Sprite addFriend;

		private Profile profile;

		public Button3D.OnButton3DClick ButtonAction => button.OnClick;

		public void SetChild(Profile profile)
		{
			this.profile = profile;
			Images.GetProfileImage(profile).Then(delegate(Texture2D image)
			{
				if (this != null && this.profile == profile)
				{
					rrImage.texture = image;
				}
			});
			rrName.text = profile.DisplayName.GetDecrypted();
			platformName.text = string.Empty;
			platformImage.texture = null;
			SingletonMonoBehaviour<PlatformManager>.Instance.GetPlatformFriendName(profile.PlatformId.PlatformId).Then(delegate(string name)
			{
				if (this != null && this.profile == profile)
				{
					platformName.text = name;
				}
			});
			SingletonMonoBehaviour<PlatformManager>.Instance.GetPlatformFriendPicture(profile.PlatformId.PlatformId).Then(delegate(Texture picture)
			{
				if (this != null && this.profile == profile)
				{
					platformImage.texture = picture;
				}
			});
			Relationship relationship = Relationships.Get(profile.Id);
			if (relationship != null && relationship.Type == Relationship.RelationshipType.FriendRequestSent)
			{
				button.Interactable = false;
				addFriendImage.sprite = tick;
			}
			else
			{
				button.Interactable = true;
				addFriendImage.sprite = addFriend;
			}
		}

		public void AddFriend()
		{
			FriendImporter.SendFriendRequest(SingletonMonoBehaviour<SessionManager>.Instance, profile);
			button.Interactable = false;
			addFriendImage.sprite = tick;
		}
	}
}
