[RequireComponent(typeof(PlayerSpecificUIBehaviour))]
public abstract class PlayerBasedConditionalButton<T> : ConditionalButton<T> where T : Button3DBase
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	protected PlayerSpecificUIBehaviour playerWatcher;

	protected virtual void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += UpdateButtonState;
	}

	protected virtual void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= UpdateButtonState;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		Relationships.RelationshipUpdated += OnRelationshipUpdated;
		Presence.OnPlayerPresenceUpdated += OnPlayerPresenceUpdated;
	}

	protected virtual void OnDisable()
	{
		Relationships.RelationshipUpdated -= OnRelationshipUpdated;
		Presence.OnPlayerPresenceUpdated -= OnPlayerPresenceUpdated;
	}

	private void OnRelationshipUpdated(long? playerId)
	{
		if (!playerId.HasValue || playerWatcher.PlayerId == playerId)
		{
			UpdateButtonState();
		}
	}

	private void OnPlayerPresenceUpdated(long id)
	{
		if (playerWatcher.PlayerId == id)
		{
			UpdateButtonState();
		}
	}

	protected override void RunButtonAction()
	{
		if (!playerWatcher.PlayerId.HasValue)
		{
			UnityEngine.Debug.LogWarning("Conditional Button attempted button press without player!");
		}
	}

	protected sealed override void UpdateButtonState()
	{
		if (!playerWatcher.PlayerId.HasValue)
		{
			base.ButtonState = 0;
		}
		else
		{
			UpdatePlayerBasedButtonState();
		}
	}

	protected abstract void UpdatePlayerBasedButtonState();
}
