public class PlayerDetailsWatchUIFlow : PlayerWatchUIFlow
{
	[SerializeField]
	private SubscreenControl subscreenControl;

	[SerializeField]
	private Subscreen profileSubscreen;

	[SerializeField]
	private PlayerMinitar minitarPrefab;

	[SerializeField]
	private Transform minitarTransform;

	[SerializeField]
	private float minitarScale = 187f;

	[SerializeField]
	private TextMeshProUGUI bioTitle;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private RoomButtonPagedGrid roomsGrid;

	private PlayerMinitar minitar;

	private RoomDetails _targetRoom;

	public RoomDetails TargetRoom
	{
		get
		{
			return _targetRoom;
		}
		set
		{
			_targetRoom = value;
		}
	}

	private void Start()
	{
		Player.LocalPlayer.PlayerUI.WatchMenu.FullyVisibleChanged += WatchMenu_FullyVisibleChanged;
	}

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		minitar = UnityEngine.Object.Instantiate(minitarPrefab, minitarTransform, worldPositionStays: false);
		minitar.transform.localScale = Vector3.one * minitarScale / minitarTransform.lossyScale.x;
		minitarTransform.gameObject.SetActive(value: false);
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (Profiles.LocalProfile.IsJunior())
		{
			subscreenControl.ShowSubscreen(profileSubscreen);
		}
	}

	private void WatchMenu_FullyVisibleChanged(bool fullyVisible)
	{
		if (base.isActiveAndEnabled)
		{
			minitarTransform.gameObject.SetActive(fullyVisible);
			UpdateCheerCountToast();
		}
	}

	private void UpdateCheerCountToast()
	{
		WatchUI.SetToast(ToastIds.CheerCount, Profiles.LocalProfile.Reputation.CheerCredit.ToString());
	}

	public override void SetProfile(Profile profile)
	{
		base.SetProfile(profile);
		Player player = ((profile == null) ? null : Player.FindLocalPlayer(profile.Id));
		if (player != null)
		{
			minitar.gameObject.SetActive(value: true);
			minitar.TargetPlayer = player;
		}
		else
		{
			minitar.gameObject.SetActive(value: false);
			minitar.TargetPlayer = null;
		}
		string username = $"@{profile.Username}";
		bioTitle.text = username + "'s Bio";
		roomsGrid.SetLoading();
		RecNet.Rooms.SearchRooms(username).Then(delegate(List<RecNet.Room> rooms)
		{
			if (this != null && base.CurrentProfile != null && username == $"@{base.CurrentProfile.Username}")
			{
				roomsGrid.SetRooms(rooms, null);
			}
		});
	}

	[SkipRename]
	public void Button_Stop()
	{
		StopPlayerWatchUIFlow flowByType = base.UIBase.GetFlowByType<StopPlayerWatchUIFlow>();
		flowByType.SetProfile(base.CurrentProfile);
		base.UIBase.PushFlow(flowByType);
	}

	[SkipRename]
	public void Button_Cheer()
	{
		CheerPlayerWatchUIFlow flowByType = base.UIBase.GetFlowByType<CheerPlayerWatchUIFlow>();
		flowByType.SetProfile(base.CurrentProfile);
		base.UIBase.PushFlow(flowByType);
	}

	[SkipRename]
	public void Button_SendMessage()
	{
		ChatThreadScreen flowByType = base.UIBase.GetFlowByType<ChatThreadScreen>();
		flowByType.ShowScreen(new List<Profile> { base.CurrentProfile }, ChatThreadScreen.CreateChatSource.PlayerDetailsScreen);
	}
