public class PlayerSpecificCheerBadges : UnityEngine.MonoBehaviour
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private PlayerSpecificUIBehaviour playerWatcher;

	[Header("Cheer badges")]
	[SerializeField]
	private UnityEngine.UI.Image cheerBadge_General;

	[SerializeField]
	private UnityEngine.UI.Image cheerBadge_Helpful;

	[SerializeField]
	private UnityEngine.UI.Image cheerBadge_Sportsman;

	[SerializeField]
	private UnityEngine.UI.Image cheerBadge_GreatHost;

	[SerializeField]
	private UnityEngine.UI.Image cheerBadge_Creative;

	protected PlayerSpecificUIBehaviour PlayerWatcher => playerWatcher;

	protected virtual void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
	}

	protected virtual void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	protected virtual void OnEnable()
	{
		PlayerIdUpdated();
	}

	private void PlayerIdUpdated()
	{
		cheerBadge_General.gameObject.SetActive(value: false);
		cheerBadge_Helpful.gameObject.SetActive(value: false);
		cheerBadge_Sportsman.gameObject.SetActive(value: false);
		cheerBadge_GreatHost.gameObject.SetActive(value: false);
		cheerBadge_Creative.gameObject.SetActive(value: false);
		if (!playerWatcher.PlayerId.HasValue)
		{
			return;
		}
		Profile profile = Profiles.Get(playerWatcher.PlayerId.Value);
		if (profile != null)
		{
			if (profile.Reputation.CheerGeneral > 0)
			{
				cheerBadge_General.gameObject.SetActive(value: true);
			}
			if (profile.Reputation.CheerHelpful > 0)
			{
				cheerBadge_Helpful.gameObject.SetActive(value: true);
			}
			if (profile.Reputation.CheerSportsman > 0)
			{
				cheerBadge_Sportsman.gameObject.SetActive(value: true);
			}
			if (profile.Reputation.CheerGreatHost > 0)
			{
				cheerBadge_GreatHost.gameObject.SetActive(value: true);
			}
			if (profile.Reputation.CheerCreative > 0)
			{
				cheerBadge_Creative.gameObject.SetActive(value: true);
			}
		}
	}
}
