[RequireComponent(typeof(TextMeshProUGUI))]
[RequireComponent(typeof(PlayerSpecificUIBehaviour))]
public abstract class PlayerSpecificText : UnityEngine.MonoBehaviour
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private PlayerSpecificUIBehaviour playerWatcher;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private TextMeshProUGUI text;

	protected PlayerSpecificUIBehaviour PlayerWatcher => playerWatcher;

	protected TextMeshProUGUI Text => text;

	protected virtual void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
	}

	protected virtual void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	protected virtual void OnEnable()
	{
		PlayerIdUpdated();
	}

