	{
		SetText(playerWatcher.CurrentProfile);
	}

	protected abstract void SetText(Profile currentProfile);
}
public class PlayerSpecificVoiceIndicator : UnityEngine.MonoBehaviour
{
	[Autofill(AutofillType.SelfAndParent, false)]
	[SerializeField]
	private PlayerSpecificUIBehaviour playerWatcher;

	[SerializeField]
	private UnityEngine.UI.Image voiceIcon;

	[SerializeField]
	private UnityEngine.UI.Image muteIcon;

	[SerializeField]
	private UnityEngine.UI.Image afkIcon;

	private float lastAlpha = -1f;

	private Player thisPlayer;

	private void Awake()
	{
		if (playerWatcher == null)
		{
			base.enabled = false;
		}
		else
		{
			playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
		}
	}

	private void Update()
	{
		if (thisPlayer != null)
		{
			bool mute = thisPlayer.Mute;
			bool userIsPresent = thisPlayer.UserIsPresent;
			voiceIcon.gameObject.SetActive(!mute && userIsPresent);
			muteIcon.gameObject.SetActive(mute && userIsPresent);
			if (!mute && userIsPresent)
			{
				float num = ((!(thisPlayer.AudioMaxForFrame <= PhotonVoiceSettings.Instance.VoiceDetectionThreshold)) ? Mathf.Min(thisPlayer.AudioMaxForFrame, 1f) : 0f);
				if (num != lastAlpha)
				{
					lastAlpha = num;
					voiceIcon.color = voiceIcon.color.WithAlpha(num);
				}
			}
		}
		else
		{
			voiceIcon.gameObject.SetActive(value: false);
			muteIcon.gameObject.SetActive(value: false);
		}
	}

	private void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	private void OnEnable()
	{
		PlayerIdUpdated();
		Player.PlayerCreatedEvent += new Action<Player>(OnPlayerCreated);
		Player.PlayerDestroyedEvent += new Action<Player>(OnPlayerDestroyed);
	}

	private void OnDisable()
	{
		Player.PlayerCreatedEvent -= new Action<Player>(OnPlayerCreated);
		Player.PlayerDestroyedEvent -= new Action<Player>(OnPlayerDestroyed);
	}

	private void OnPlayerCreated(Player player)
	{
		if (playerWatcher.CurrentProfile != null && player.PlayerId == (long)playerWatcher.CurrentProfile.Id)
		{
			thisPlayer = Player.FindLocalPlayer(playerWatcher.CurrentProfile.Id);
		}
	}

	private void OnPlayerDestroyed(Player player)
	{
		if (playerWatcher.CurrentProfile != null && player.PlayerId == (long)playerWatcher.CurrentProfile.Id)
		{
			thisPlayer = null;
		}
	}

	private void PlayerIdUpdated()
	{
		if (!(playerWatcher == null))
		{
			if (playerWatcher.CurrentProfile != null)
			{
				thisPlayer = Player.FindLocalPlayer(playerWatcher.CurrentProfile.Id);
			}
			else
			{
				thisPlayer = null;
			}
		}
	}
}
public class PlayerStatusText : PlayerSpecificText
{
	protected override void OnEnable()
	{
		base.OnEnable();
		Presence.OnPlayerPresenceUpdated += PlayerPresenceUpdated;
		if (base.PlayerWatcher.DisplayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends)
		{
			Relationships.RelationshipUpdated += RelationshipUpdated;
		}
		Player.PlayerDestroyedEvent += new Action<Player>(PlayerDestroyed);
	}

	protected void OnDisable()
	{
		Player.PlayerDestroyedEvent -= new Action<Player>(PlayerDestroyed);
		Presence.OnPlayerPresenceUpdated -= PlayerPresenceUpdated;
		Relationships.RelationshipUpdated -= RelationshipUpdated;
	}

	private void RelationshipUpdated(long? playerId)
	{
		if (base.PlayerWatcher.CurrentProfile == null || !playerId.HasValue || ((long)base.PlayerWatcher.CurrentProfile.Id == playerId.GetValueOrDefault() && playerId.HasValue))
		{
			SetText(base.PlayerWatcher.CurrentProfile);
		}
	}

	private void PlayerPresenceUpdated(long id)
	{
		SetText(base.PlayerWatcher.CurrentProfile);
	}

	private void PlayerDestroyed(Player player)
	{
		SetText(base.PlayerWatcher.CurrentProfile);
	}

	protected override void SetText(Profile currentProfile)
	{
		base.Text.text = GetStatusText(currentProfile, base.PlayerWatcher.DisplayMode);
	}

	public static string GetStatusText(Profile profile, PlayerSpecificUIBehaviour.PlayerDisplayMode displayMode)
	{
		if (profile == null)
		{
			return string.Empty;
		}
		Relationship relationship = Relationships.Get(profile.Id);
		if (displayMode == PlayerSpecificUIBehaviour.PlayerDisplayMode.Friends && relationship != null && (relationship.Type == Relationship.RelationshipType.FriendRequestReceived || relationship.Type == Relationship.RelationshipType.FriendRequestSent))
		{
			return "Friend request pending";
		}
		PlayerPresence playerPresence = Presence.Get(profile.Id);
		return Presence.GetPlayerStatusString(playerPresence);
	}
}
[RequireComponent(typeof(PlayerSpecificUIBehaviour))]
public class PlayerTooltipUpdater : UnityEngine.MonoBehaviour
{
	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private PlayerSpecificUIBehaviour playerWatcher;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private Tooltip tooltip;

	private string withPresenceTooltipFormat = "<i>@{0}</i>\n{1}";

	private string withoutPresenceTooltipFormat = "<i>@{0}</i>";

	private void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
	}

	private void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	private void OnEnable()
	{
		Presence.OnPlayerPresenceUpdated += PresenceUpdated;
		PlayerIdUpdated();
	}

	private void PresenceUpdated(long id)
	{
		if (playerWatcher.PlayerId == id)
		{
			PlayerIdUpdated();
		}
	}

	private void OnDisable()
	{
		Presence.OnPlayerPresenceUpdated -= PresenceUpdated;
	}

	private void PlayerIdUpdated()
	{
		if (playerWatcher.CurrentProfile == null)
		{
			tooltip.Message = string.Empty;
			return;
		}
		string statusText = PlayerStatusText.GetStatusText(playerWatcher.CurrentProfile, playerWatcher.DisplayMode);
		if (!string.IsNullOrEmpty(statusText))
		{
			tooltip.Message = string.Format(withPresenceTooltipFormat, playerWatcher.CurrentProfile.Username, statusText);
		}
		else
		{
			tooltip.Message = string.Format(withoutPresenceTooltipFormat, playerWatcher.CurrentProfile.Username);
		}
	}
}
public abstract class PlayerWatchUIFlow : WatchUIFlow
{
	private PlayerSpecificUIBehaviour[] playerSpecificUIBehaviours = new PlayerSpecificUIBehaviour[0];

	public Profile CurrentProfile { get; private set; }

	public void SetPlayer(Player player)
	{
		SetProfile((!(player != null)) ? null : Profiles.Get(player.PlayerId));
	}

	public virtual void SetProfile(Profile profile)
	{
		CurrentProfile = profile;
		if (playerSpecificUIBehaviours.Length == 0)
		{
			playerSpecificUIBehaviours = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
		}
		long? id = ((CurrentProfile == null) ? ((long?)null) : new long?(CurrentProfile.Id));
		PlayerSpecificUIBehaviour[] array = playerSpecificUIBehaviours;
		foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in array)
		{
			playerSpecificUIBehaviour.SetPlayer(id);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		SetProfile((CurrentProfile == null) ? null : Profiles.Get(CurrentProfile.Id));
	}
}
