public class ReportWatchUIFlow : PlayerWatchUIFlow
{
	[SerializeField]
	private ToggleGroup3D toggleGroup;

	[SerializeField]
	private ToggleButton3D underageToggle;

	[SerializeField]
	private ToggleButton3D sexualBehaviorToggle;

	[SerializeField]
	private ToggleButton3D gameExploitToggle;

	[SerializeField]
	private ToggleButton3D discriminatoryBehaviorToggle;

	[SerializeField]
	private ToggleButton3D inapproriateNameToggle;

	[SerializeField]
	private InputField3D descriptionTextField;

	[SerializeField]
	private TextMeshProUGUI charCount;

	[SerializeField]
	private Button3D submitButton;

	[SerializeField]
	private GameObject codeOfConductPrefab;

	private GameObject codeOfConduct;

	private WatchUI watchMenu;

	private bool waitingForConfirmation;

	public Action<ReportWatchUIFlow> CreateReportAction;

	public Func<ReportWatchUIFlow, bool> CanIssueReportAction;

	public PlayerReporting.ReportCategory Category { get; private set; }

	public string Description => descriptionTextField.Text;

	private void Start()
	{
		submitButton.Interactable = false;
		if (Player.LocalPlayerExists)
		{
			watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
			Player.LocalPlayer.PlayerEvents.MenuVisibleEvent += OnMenuOpenCloseChanged;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Player.LocalPlayerExists)
		{
			Player.LocalPlayer.PlayerEvents.MenuVisibleEvent -= OnMenuOpenCloseChanged;
		}
	}

	private void OnMenuOpenCloseChanged(bool visible)
	{
		if (base.IsCurrentFlow || waitingForConfirmation)
		{
			UpdateCoC(visible);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		UpdateCoC(visible: true);
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		UpdateCoC(visible: false);
	}

	private void UpdateCoC(bool visible)
	{
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
		{
			return;
		}
		if (visible)
		{
			Transform transform = ((!(watchMenu != null)) ? base.transform : watchMenu.transform);
			Vector3 vector = transform.position + transform.right * 0.75f;
			Quaternion rotation = Quaternion.LookRotation(vector - Player.LocalPlayer.Head.transform.position, Vector3.up);
			if (codeOfConduct != null)
			{
				codeOfConduct.transform.position = vector;
				codeOfConduct.transform.rotation = rotation;
			}
			else
			{
				codeOfConduct = UnityEngine.Object.Instantiate(codeOfConductPrefab, vector, rotation);
			}
		}
		if (codeOfConduct != null)
		{
			codeOfConduct.SetActive(visible);
		}
	}

	public void ClearForm()
	{
		foreach (ToggleButton3D button in toggleGroup.Buttons)
		{
			button.IsOn = false;
		}
		descriptionTextField.Text = string.Empty;
		submitButton.Interactable = false;
	}

	public override void SetProfile(Profile profile)
	{
		if (base.CurrentProfile == null || (long)base.CurrentProfile.Id != (long)profile.Id)
		{
			ClearForm();
		}
		base.SetProfile(profile);
	}

	private void ReportHelper(PlayerReporting.ReportCategory category)
	{
		Category = category;
		submitButton.Interactable = Category != PlayerReporting.ReportCategory.Unknown;
	}

	[SkipRename]
	public void Toggle_Underage(bool isOn)
	{
		ReportHelper(isOn ? PlayerReporting.ReportCategory.CoC_Underage : PlayerReporting.ReportCategory.Unknown);
	}

	[SkipRename]
	public void Toggle_SexualBehavior(bool isOn)
	{
		ReportHelper(isOn ? PlayerReporting.ReportCategory.CoC_Sexual : PlayerReporting.ReportCategory.Unknown);
	}

	[SkipRename]
	public void Toggle_DiscriminatoryBehavior(bool isOn)
	{
		ReportHelper(isOn ? PlayerReporting.ReportCategory.CoC_Discrimination : PlayerReporting.ReportCategory.Unknown);
	}

	[SkipRename]
	public void Toggle_Trolling(bool isOn)
	{
		ReportHelper(isOn ? PlayerReporting.ReportCategory.CoC_Trolling : PlayerReporting.ReportCategory.Unknown);
	}

	[SkipRename]
	public void Toggle_Inappropriate(bool isOn)
	{
		ReportHelper(isOn ? PlayerReporting.ReportCategory.CoC_NameOrProfile : PlayerReporting.ReportCategory.Unknown);
	}

	[SkipRename]
	public void Button_Submit()
	{
		if (CanIssueReportAction != null && !CanIssueReportAction(this))
		{
			return;
		}
		waitingForConfirmation = true;
		watchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Confirm report?", "You CANNOT undo this action. Players who send false reports or abuse the reporting system will be penalized.", "Yes", "No", (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses r)
		{
			waitingForConfirmation = false;
			if (r == ConfirmDialogResponses.Affirmative)
			{
				CreateReportAction(this);
				watchMenu.PopFlow();
				if (codeOfConduct != null)
				{
					UpdateCoC(visible: false);
				}
			}
		});
	}

	[SkipRename]
	public void OnTextValueChanged(string newText)
	{
		if (string.IsNullOrEmpty(newText))
		{
			charCount.text = "0";
			return;
		}
		int length = newText.Length;
		charCount.text = length.ToString();
	}
}
public class StopPlayerWatchUIFlow : PlayerWatchUIFlow
{
	[SerializeField]
	private PlayerMinitar minitarPrefab;

	[SerializeField]
	private Transform minitarTransform;

