		{
			watchMenu.FullyVisibleChanged += WatchMenu_FullyVisibleChanged;
		}
	}

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		minitar = UnityEngine.Object.Instantiate(minitarPrefab, minitarTransform, worldPositionStays: false);
		minitar.transform.localScale = Vector3.one * minitarScale / minitarTransform.lossyScale.x;
		minitarTransform.gameObject.SetActive(value: false);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (watchMenu != null)
		{
			watchMenu.FullyVisibleChanged -= WatchMenu_FullyVisibleChanged;
		}
	}

	private void WatchMenu_FullyVisibleChanged(bool fullyVisible)
	{
		if (base.isActiveAndEnabled)
		{
			minitarTransform.gameObject.SetActive(fullyVisible);
		}
	}

	private void OnEnable()
	{
		if (base.IsCurrentFlow)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.TemporarilyIncreaseComfortSettings();
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		SingletonMonoBehaviour<SettingsManager>.Instance.TemporarilyIncreaseComfortSettings();
	}

	public override void SetProfile(Profile profile)
	{
		base.SetProfile(profile);
		Player player = Player.FindLocalPlayer(profile.Id);
		if (player != null)
		{
			minitar.gameObject.SetActive(value: true);
			minitar.TargetPlayer = player;
		}
		else
		{
			minitar.TargetPlayer = null;
			minitar.gameObject.SetActive(value: false);
		}
	}

