	{
		Player Target = Player.FindLocalPlayer(base.CurrentProfile.Id);
		if (!(Target != null))
		{
			return;
		}
		watchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Confirmation", string.Concat("Are you sure you want to start a vote kick for ", base.CurrentProfile.DisplayName, "?")).Then(delegate(ConfirmDialogResponses r)
		{
			if (r == ConfirmDialogResponses.Affirmative)
			{
				Target.PlayerModeration.VoteToKickPlayer(initiating: true);
				AnalyticsHelper.VTKInitiated(Target.PlayerId);
			}
		});
	}

	public void Button_Report()
	{
		base.WatchUI.ShowPlayerReportScreen(base.CurrentProfile);
	}

	public void MuteAndIgnorePlayer(Player confirmIgnorePlayer)
	{
		Player.SavePlayerMuted(base.CurrentProfile.Id, mute: true);
		Player.SavePlayerIgnored(base.CurrentProfile.Id, ignore: true);
	}
}
public class SubscribeConditionalButton : PlayerBasedConditionalButton<Button3D>
{
	public enum SubscribeButtonState
	{
		Disabled,
		Subscribe,
		Unsubscribe
	}

	[SerializeField]
	private Sprite subscribeSprite;

	[SerializeField]
	private Sprite unsubscribeSprite;

	[SerializeField]
	private string subscribeTooltipText;

	[SerializeField]
	private string unsubscribeTooltipText;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private Tooltip tooltip;

	[SerializeField]
	private SubscriberCountText textToForceUpdate;

	[SerializeField]
	private string amplitudeEventContextLabel = string.Empty;

	protected override void OnEnable()
	{
		base.OnEnable();
		PlayerSubscriptions.PlayerSubscriptionUpdated += OnPlayerSubscriptionsUpdated;
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		PlayerSubscriptions.PlayerSubscriptionUpdated -= OnPlayerSubscriptionsUpdated;
	}

	private void OnPlayerSubscriptionsUpdated(long? playerid)
	{
		UpdatePlayerBasedButtonState();
	}

	protected override void RunButtonAction()
	{
		switch ((SubscribeButtonState)base.ButtonState)
		{
		case SubscribeButtonState.Subscribe:
			SubscribeToPlayer();
			break;
		case SubscribeButtonState.Unsubscribe:
			UnsubscribeFromPlayer();
			break;
		}
	}

	private void SubscribeToPlayer()
	{
		if (!playerWatcher.PlayerId.HasValue)
		{
			return;
		}
		base.ButtonState = 0;
		PlayerSubscriptions.SubscribeTo(playerWatcher.PlayerId.Value, delegate(string error)
		{
			if (string.IsNullOrEmpty(error))
			{
				AnalyticsHelper.SubscribeEvent(amplitudeEventContextLabel);
				if (Player.LocalPlayerExists)
				{
					Player.LocalPlayer.PlayerEvents.SubscribedToPlayer();
				}
				playerWatcher.CurrentProfile.Reputation.SubscriberCount++;
				if (textToForceUpdate != null)
				{
					textToForceUpdate.ForceUpdate(playerWatcher.CurrentProfile);
				}
			}
		});
	}

	private void UnsubscribeFromPlayer()
	{
		if (!playerWatcher.PlayerId.HasValue)
		{
			return;
		}
		base.ButtonState = 0;
		PlayerSubscriptions.UnsubscribeFrom(playerWatcher.PlayerId.Value, delegate(string error)
		{
			if (string.IsNullOrEmpty(error))
			{
				AnalyticsHelper.UnsubscribeEvent(amplitudeEventContextLabel);
				playerWatcher.CurrentProfile.Reputation.SubscriberCount--;
				if (textToForceUpdate != null)
				{
					textToForceUpdate.ForceUpdate(playerWatcher.CurrentProfile);
				}
			}
		});
	}

	protected override void UpdatePlayerBasedButtonState()
	{
		bool flag = false;
		if (playerWatcher.CurrentProfile != null)
		{
			flag = PlayerSubscriptions.IsLocalPlayerSubscribedToPlayer(playerWatcher.CurrentProfile);
		}
		if (playerWatcher.CurrentProfile == Profiles.LocalProfile)
		{
			base.ButtonState = 0;
		}
		else
		{
			base.ButtonState = ((!flag) ? 1 : 2);
		}
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		if (base.LabelText != null)
		{
			switch ((SubscribeButtonState)base.ButtonState)
			{
			case SubscribeButtonState.Subscribe:
				base.LabelText.text = "Subscribe";
				UIHelper.SafeSetSprite(base.ButtonImage, subscribeSprite);
				button.targetGraphic.color = button.BaseColor;
				tooltip.Message = subscribeTooltipText;
				break;
			case SubscribeButtonState.Unsubscribe:
				base.LabelText.text = "Unsubscribe";
				UIHelper.SafeSetSprite(base.ButtonImage, unsubscribeSprite);
				button.targetGraphic.color = button.ToggleColor;
				tooltip.Message = unsubscribeTooltipText;
				break;
			}
		}
	}
}
