namespace RecRoom
{
	public class VoteKickConditionalButton : PlayerBasedConditionalButton<Button3D>
	{
		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Tooltip tooltip;

		protected override void UpdatePlayerBasedButtonState()
		{
			bool flag = false;
			if (SessionManager.InRecRoyale && NetworkedSingletonMonoBehaviour<GameManager>.IsInitialized && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunningOrLoading)
			{
				tooltip.Message = "Vote kick disabled while game in progress";
			}
			else if (playerWatcher.PlayerId.HasValue)
			{
				Player player = Player.FindLocalPlayer(playerWatcher.PlayerId.Value);
				if (player != null)
				{
					flag = !player.PlayerModeration.IsVotedForKick;
					tooltip.Message = "Already started vote kick";
				}
				else
				{
					tooltip.Message = "Player is not in this room";
				}
			}
			if (flag)
			{
				base.ButtonState = 1;
				tooltip.Message = "Start a vote kick";
			}
			else
			{
				base.ButtonState = 0;
			}
		}
	}
}
namespace AGUI.StackedUI
{
	public class BackpackScreen : WatchUIFlow
	{
		public enum DisplayMode
		{
			Invalid = -1,
			Tools,
			Film,
			Potions,
			Food,
			Other
		}

		[Header("Buttons")]
		[SerializeField]
		private RadioButton3D toolsConsumablesButton;

		[SerializeField]
		private RadioButton3D filmConsumablesButton;

		[SerializeField]
		private RadioButton3D potionsConsumablesButton;

		[SerializeField]
		private RadioButton3D foodConsumablesButton;

		[SerializeField]
		private RadioButton3D otherConsumablesButton;

		[Header("Labels")]
		[SerializeField]
		private RectTransform favoriteToolInfo;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private BackpackToolButtonPagedGrid backpackToolPagedGrid;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private ConsumablesPagedGrid consumablesPagedGrid;

		private List<Consumable> currentConsumables = new List<Consumable>();

		private ConsumableManager consumableManager;

		private DisplayMode _consumablesDisplayMode = DisplayMode.Invalid;

		private DisplayMode ConsumablesDisplayMode
		{
			get
			{
				return _consumablesDisplayMode;
			}
			set
			{
				if (_consumablesDisplayMode != value)
				{
					_consumablesDisplayMode = value;
					UpdateGridForDisplayMode();
				}
			}
		}

		private void Awake()
		{
			consumableManager = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance;
			consumableManager.OnPurchasedConsumableChanged += OnPurchasedConsumableChanged;
		}

		protected override void OnDestroy()
		{
			consumableManager.OnPurchasedConsumableChanged -= OnPurchasedConsumableChanged;
			base.OnDestroy();
		}

		private void OnEnable()
		{
			this.InvokeNextEndOfFrame(delegate
			{
				UpdateButtonPresses();
			});
			if (favoriteToolInfo != null)
			{
				favoriteToolInfo.gameObject.SetActive(SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentDisplayMode == LocalPlayerController.DisplayMode.VR);
			}
		}

		private void UpdateButtonPresses()
		{
			switch (ConsumablesDisplayMode)
			{
			case DisplayMode.Tools:
				toolsConsumablesButton.ForcePressed();
				break;
			case DisplayMode.Film:
				filmConsumablesButton.ForcePressed();
				break;
			case DisplayMode.Food:
				foodConsumablesButton.ForcePressed();
				break;
			case DisplayMode.Potions:
				potionsConsumablesButton.ForcePressed();
				break;
			case DisplayMode.Other:
				otherConsumablesButton.ForcePressed();
				break;
			}
		}

		private void UpdateGridForDisplayMode()
		{
			if (!base.IsCurrentFlow)
			{
				return;
			}
			if (ConsumablesDisplayMode == DisplayMode.Tools)
			{
				backpackToolPagedGrid.SetBackpackTools(PlayerBackpackToolSettings.GetAllToolTypes());
				return;
			}
			switch (ConsumablesDisplayMode)
			{
			case DisplayMode.Film:
				currentConsumables = GetFilmConsumablesList();
				break;
			case DisplayMode.Potions:
				currentConsumables = GetPotionConsumablesList();
				break;
			case DisplayMode.Food:
				currentConsumables = GetFoodConsumablesList();
				break;
			case DisplayMode.Other:
				currentConsumables = GetOtherConsumablesList();
				break;
			default:
				throw new NotImplementedException("Unknown consumable category");
			}
			consumablesPagedGrid.SetConsumables(currentConsumables, ConsumablesDisplayMode);
		}

		private List<Consumable> GetActiveConsumablesList()
		{
			return consumableManager.ActiveConsumables.Values.ToList();
		}

		private List<Consumable> GetFilmConsumablesList()
		{
			return consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.CameraFilter);
		}

		private List<Consumable> GetPotionConsumablesList()
		{
			List<Consumable> latestPurchasedConsumablesInCategory = consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.Potion_Head);
			latestPurchasedConsumablesInCategory.AddRange(consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.Potion_Hand));
			latestPurchasedConsumablesInCategory.AddRange(consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.Potion_HairDye));
			return latestPurchasedConsumablesInCategory;
		}

		private List<Consumable> GetFoodConsumablesList()
		{
			return consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.Food);
		}

		private List<Consumable> GetOtherConsumablesList()
		{
			return consumableManager.GetLatestPurchasedConsumablesInCategory(ConsumableManager.Category.KO_Customization);
		}

		private void DisplayModeButtonPressed(DisplayMode displayMode)
		{
			ConsumablesDisplayMode = displayMode;
		}

		private void OnPurchasedConsumableChanged(Consumable consumable, bool added)
		{
			UpdateGridForDisplayMode();
		}

		[SkipRename]
		public void Button_ToggleActiveState(Consumable consumable)
		{
			ConsumableTool consumableTool = ConsumableTool.FindConsumableTool(consumable.Category);
			bool flag = false;
			if (consumableTool != null)
			{
				flag = consumable.Id == consumableTool.Consumable.Id && consumableTool.Purpose != PlayerSpawnedEquipment.Purpose.GiftBox;
				PhotonNetwork.GetOwnershipAndDestroy(consumableTool.gameObject);
			}
			if (consumableManager.IsConsumableOfTypeActive(consumable.ConsumableType))
			{
				AnalyticsHelper.ConsumableDeactivatedManually(consumable.ConsumableItem.FriendlyName, consumable.Category, consumable.Count, consumable.ActiveDurationMinutes);
				consumableManager.DeactivateConsumableOfCategory(consumable.Category, showNotification: true);
			}
			else if (!flag)
			{
				GiftBox activeGiftBox = SingletonMonoBehaviour<GiftManager>.Instance.ActiveGiftBox;
				if (activeGiftBox != null && activeGiftBox.BoxContents == GiftManager.GiftBoxContents.Consumable)
				{
					SingletonMonoBehaviour<GiftManager>.Instance.StopReceiveGiftsCoroutine();
				}
				if (consumable.ConsumableItem.ConsumableTool != null)
				{
					Transform transform = Player.LocalPlayer.Head.transform;
					Vector3 position = transform.position + transform.forward * 0.9f + Vector3.down * 0.3f;
					consumableManager.SpawnConsumableForLocalPlayer(consumable.ConsumableType, consumable.Id, position, Quaternion.identity, 1f, PlayerSpawnedEquipment.Purpose.None, null);
					Player.LocalPlayer.PlayerUI.WatchMenuProjector.AuthorityCloseMenu();
				}
				else
				{
					consumableManager.ActivateConsumable(consumable, showNotification: true);
				}
			}
		}

		[SkipRename]
		public void Button_SetToolsDisplayMode()
		{
			DisplayModeButtonPressed(DisplayMode.Tools);
		}

		[SkipRename]
		public void Button_SetFilmDisplayMode()
		{
			DisplayModeButtonPressed(DisplayMode.Film);
		}

		[SkipRename]
		public void Button_SetPotionsDisplayMode()
		{
			DisplayModeButtonPressed(DisplayMode.Potions);
		}

		[SkipRename]
		public void Button_SetFoodDisplayMode()
		{
			DisplayModeButtonPressed(DisplayMode.Food);
		}

		[SkipRename]
		public void Button_SetOtherDisplayMode()
		{
			DisplayModeButtonPressed(DisplayMode.Other);
		}

		[SkipRename]
		public void Toggle_FavoriteTool(bool isOn, PlayerBackpackToolType favoriteToolType)
		{
			Player.LocalPlayer.Backpack.SetFavoriteTool((!isOn) ? PlayerBackpackToolType.INVALID : favoriteToolType);
		}

		[SkipRename]
		public void Toggle_UseTool(bool isOn, PlayerBackpackToolType toolType)
		{
			if (isOn)
			{
				Player.LocalPlayer.Backpack.UseTool(toolType);
			}
			else
			{
				Player.LocalPlayer.Backpack.RecallTool(toolType);
			}
