[RequireComponent(typeof(ToggleButton3D))]
public class ConsumableButton : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private ToggleButton3D toggle;

	[SerializeField]
	[Autofill(AutofillType.SelfAndChildren, false)]
	private Tooltip tooltip;

	[SerializeField]
	private float visualSize = 0.025f;

	[SerializeField]
	private Transform consumableRoot;

	[SerializeField]
	private Text consumableName;

	[SerializeField]
	private Text count;

	[SerializeField]
	private Text timeLeft;

	[SerializeField]
	private GameObject useText;

	public Consumable CurrentConsumable { get; private set; }

	public ToggleButton3D.OnToggleButton3DClick ButtonAction => toggle.OnClick;

	private void Awake()
	{
		if (NetworkedSingletonMonoBehaviour<ConsumableManager>.IsInitialized)
		{
			NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.OnActiveConsumableChanged += OnActiveConsumableChanged;
		}
		ButtonAction.AddListener(delegate
		{
			useText.SetActive(!toggle.IsOn);
		});
	}

	private void OnDestroy()
	{
		if (NetworkedSingletonMonoBehaviour<ConsumableManager>.IsInitialized)
		{
			NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.OnActiveConsumableChanged -= OnActiveConsumableChanged;
		}
	}

	private void OnEnable()
	{
		if (CurrentConsumable != null)
		{
			RefreshVisuals();
		}
	}

	private void OnActiveConsumableChanged(Consumable consumable, bool isActive)
	{
		if (CurrentConsumable != null && consumable.ConsumableType == CurrentConsumable.ConsumableType)
		{
			RefreshVisuals();
		}
	}

	public void SetConsumable(Consumable consumable, StackedUIBase stackedUIBase)
	{
		if (CurrentConsumable == consumable)
		{
			return;
		}
		CurrentConsumable = consumable;
		foreach (Transform item in consumableRoot)
		{
			UnityEngine.Object.Destroy(item.gameObject);
		}
		if (!(CurrentConsumable == null))
		{
			Delayed3DUIObjectSpawner orAddComponent = consumableRoot.gameObject.GetOrAddComponent<Delayed3DUIObjectSpawner>();
			orAddComponent.Initialize(stackedUIBase, delegate(Transform parent)
			{
				GameObject gameObject = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.SpawnConsumableImposter(CurrentConsumable.ConsumableType);
				gameObject.transform.SetParent(parent, worldPositionStays: true);
				gameObject.transform.AssignCorrectScale(visualSize);
				gameObject.transform.localPosition = Vector3.zero;
				gameObject.transform.localRotation = Quaternion.identity;
			});
			consumableName.text = CurrentConsumable.ConsumableItem.FriendlyName;
			if (tooltip != null)
			{
				tooltip.Message = CurrentConsumable.ConsumableItem.FriendlyName;
				tooltip.enabled = !string.IsNullOrEmpty(tooltip.Message);
			}
			RefreshVisuals();
		}
	}

	private void RefreshVisuals()
	{
		if (!base.gameObject.activeInHierarchy)
		{
			return;
		}
		List<Consumable> allPurchasedConsumablesOfType = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetAllPurchasedConsumablesOfType(CurrentConsumable.ConsumableType);
		if (CurrentConsumable.ConsumableItem.LimitType == ConsumableManager.LimitType.Usage)
		{
			int num = 0;
			foreach (Consumable item in allPurchasedConsumablesOfType)
			{
				num += item.Count;
			}
			count.text = "x" + num;
		}
		else
		{
			count.text = "x" + allPurchasedConsumablesOfType.Count;
		}
		bool flag = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.IsConsumableOfTypeActive(CurrentConsumable.ConsumableType);
		if (CurrentConsumable.ConsumableItem.LimitType == ConsumableManager.LimitType.Time || CurrentConsumable.ConsumableItem.LimitType == ConsumableManager.LimitType.RealWorldTime)
		{
			StopAllCoroutines();
			if (flag)
			{
				int remainingCount = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetRemainingCount(CurrentConsumable);
				timeLeft.text = GetTimeLeftString(remainingCount);
				StartCoroutine(RunUpdateTime(remainingCount));
			}
			else
			{
				timeLeft.text = GetTimeLeftString(CurrentConsumable.Count);
			}
		}
		else
		{
			timeLeft.text = string.Empty;
		}
		ConsumableTool consumableTool = ConsumableTool.FindConsumableTool(CurrentConsumable.Id);
		toggle.IsOn = flag || (consumableTool != null && consumableTool.gameObject.activeSelf);
		useText.SetActive(!toggle.IsOn);
	}

	private IEnumerator RunUpdateTime(int seconds)
	{
		while (seconds > 0 && CurrentConsumable != null && CurrentConsumable.IsActive)
		{
			timeLeft.text = GetTimeLeftString(seconds);
			seconds--;
			yield return new WaitForSecondsRealtime(1f);
		}
	}

	private string GetTimeLeftString(int seconds)
	{
		TimeSpan timeSpan = TimeSpan.FromSeconds(seconds);
		if (timeSpan.Days > 0)
		{
			return $"{timeSpan.Days + 1} days";
		}
		return timeSpan.ToString();
	}
}
namespace AGUI.StackedUI
{
	public class ConsumablesPagedGrid : RecyclerPagedGrid<Consumable, ConsumableButton>
	{
		[Serializable]
		public class ConsumableSelectedEvent : UnityEvent<Consumable>
		{
		}

		[SerializeField]
		private StackedUIFlowBase uiFlowBase;

		public ConsumableSelectedEvent OnConsumableSelectedEvent;

		private void Start()
		{
			if (OnConsumableSelectedEvent == null)
			{
				return;
			}
			foreach (ConsumableButton childUIElement in childUIElements)
			{
				ConsumableButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate
				{
					OnConsumableSelectedEvent.Invoke(innerChild.CurrentConsumable);
				});
			}
		}

		public void SetConsumables(IEnumerable<Consumable> consumables, BackpackScreen.DisplayMode displayMode)
		{
			List<Consumable> allActiveChildren = consumables.OrderByDescending((Consumable c) => c.Category).ToList();
			SetAllActiveChildren(allActiveChildren);
		}

		protected override void SetChild(Consumable consumable, ConsumableButton button, int activeIndex)
		{
			button.SetConsumable(consumable, uiFlowBase.UIBase);
		}
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class UIJuniorChangeNameDialog : ConfirmUIDialog
	{
		[SerializeField]
		private StringUIRotator adjectiveRotator;

		[SerializeField]
		private StringUIRotator nounRotator;

		[SerializeField]
		private Button3D submitButton;

		private List<string> adjectives;

		private List<string> nouns;

		private string newDisplayName;

		public override IPromise<ConfirmDialogResponses> ShowDialog()
		{
			StartCoroutine(RunGetWordLists());
			return base.ShowDialog();
		}

		private IEnumerator RunGetWordLists()
		{
			if (adjectives != null && nouns != null)
			{
				yield break;
			}
			yield return Profiles.GetNameGenerationOptions(delegate(string error, Profiles.NameGenDTO nameGenDTO)
			{
				if (string.IsNullOrEmpty(error))
				{
					adjectives = nameGenDTO.Adjectives;
					nouns = nameGenDTO.Nouns;
				}
			});
			adjectiveRotator.Values = adjectives;
			adjectiveRotator.Reset();
			nounRotator.Values = nouns;
			nounRotator.Reset();
			string[] words = (from m in Regex.Matches(Profiles.LocalProfile.DisplayName.GetDecrypted(), "(^[a-z]+|[A-Z]+(?![a-z])|[A-Z][a-z]+)").OfType<Match>()
				select m.Value).ToArray();
			if (words.Length == 2)
			{
				adjectiveRotator.Index = adjectiveRotator.Values.IndexOf(words[0]);
				nounRotator.Index = nounRotator.Values.IndexOf(words[1]);
			}
		}

		[SkipRename]
		public void Button_RotatorValueChanged()
		{
			bool flag = adjectiveRotator.Index >= 0 && adjectiveRotator.Index < adjectiveRotator.Count;
			bool flag2 = nounRotator.Index >= 0 && nounRotator.Index < nounRotator.Count;
			newDisplayName = (adjectiveRotator.Value + nounRotator.Value).Trim();
			submitButton.Interactable = flag && flag2 && newDisplayName != Profiles.LocalProfile.DisplayName.GetDecrypted() && newDisplayName.Length >= 2;
		}

		[SkipRename]
		public void Button_Submit()
		{
			submitButton.Interactable = false;
			Profiles.UpdateLocalProfileDisplayName(newDisplayName, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (response.Success)
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Name Updated!", 3f);
					}
					else
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, response.Message, 4f);
					}
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Error updating name!", 3f);
				}
				if (base.isActiveAndEnabled)
				{
					Button_Affirmative();
				}
			});
		}
	}
	public class UIOfflineInvitesDialog : ConfirmUIDialog
	{
		[Header("Why Phone Number")]
		[SerializeField]
		private GameObject whyPhoneNumberGroup;

		[Header("Enter Number")]
		[SerializeField]
		private GameObject enterNumberGroup;

		[SerializeField]
		private TextMeshProUGUI currentPhoneNumberText;

		[SerializeField]
		private ValidatedButtonInputField countryCodeField;

		[SerializeField]
		private ValidatedButtonInputField phoneNumberField;

		[SerializeField]
		private TextMeshProUGUI enterNumberInfoText;

		[SerializeField]
		private Button3D submitButton;

		[SerializeField]
		private Button3D whatsThisButton;

		[Header("Verification")]
		[SerializeField]
		private GameObject verificationGroup;

		[SerializeField]
		private ValidatedButtonInputField verificationField;

		[SerializeField]
		private TextMeshProUGUI verificationInfoText;

		[SerializeField]
		private Button3D verifyButton;

		private Coroutine sendTextRoutine;

		private string fullPhoneNumber;

		private string phoneNumber = string.Empty;

		private string countryCode = string.Empty;

		private Coroutine verifyRoutine;

		private string verificationCode = string.Empty;

		private const int NANP = 1;

		private void Awake()
		{
			countryCodeField.IsValidFunction = delegate(string countryCode)
			{
				this.countryCode = countryCode;
				return IsPhoneNumberValid(phoneNumber) && IsValidCountryCode(this.countryCode);
			};
			phoneNumberField.IsValidFunction = delegate(string phoneNumber)
			{
				this.phoneNumber = phoneNumber;
				return IsPhoneNumberValid(this.phoneNumber) && IsValidCountryCode(countryCode);
			};
			verificationField.IsValidFunction = delegate(string code)
			{
				verificationCode = code;
				return IsVerificationCodeValid(code);
			};
		}

		private void OnEnable()
		{
			whyPhoneNumberGroup.SetActive(value: false);
			enterNumberGroup.SetActive(value: true);
			verificationGroup.SetActive(value: false);
			SetEnterNumberInfoText(string.Empty, enableButtons: true);
			currentPhoneNumberText.text = string.Empty;
			Profiles.GetPhoneLastFour(OnPhoneNumberUpdated);
		}

		private void OnPhoneNumberUpdated(string error, string phoneLastFour)
		{
			if (!string.IsNullOrEmpty(phoneLastFour))
			{
				currentPhoneNumberText.text = $"Current phone ends with: {phoneLastFour}";
			}
			else
			{
				currentPhoneNumberText.text = "No current phone number";
			}
		}

		private bool IsValidCountryCode(string countryCode)
		{
			string text = new string(countryCode.Where(char.IsDigit).ToArray());
			return text.Length > 0 && text.Length <= 3;
		}

		private bool IsPhoneNumberValid(string newDisplayName)
		{
			string text = new string(newDisplayName.Where(char.IsDigit).ToArray());
			GetMinMaxCharsFromCountryCode(countryCode, out var minChars, out var maxChars);
			return text.Length >= minChars && text.Length <= maxChars;
		}

		private bool IsVerificationCodeValid(string code)
		{
			return code.Trim().Length == 6;
		}

		private void GetMinMaxCharsFromCountryCode(string countryCode, out int minChars, out int maxChars)
		{
			int result = -1;
			if (!int.TryParse(countryCode, out result))
			{
				maxChars = 15;
				minChars = 7;
			}
			else if (result == 1)
			{
				minChars = 10;
				maxChars = 10;
			}
			else
			{
				minChars = 4;
				maxChars = 15 - countryCode.Length;
			}
		}

		private void SetEnterNumberInfoText(string info, bool enableButtons)
		{
			enterNumberInfoText.text = info;
			countryCodeField.Interactable = enableButtons;
			phoneNumberField.Interactable = enableButtons;
			whatsThisButton.Interactable = enableButtons;
			submitButton.Interactable = enableButtons;
		}

		private void SetVerificationInfoText(string info, bool enableButtons)
		{
			verificationInfoText.text = info;
			verificationField.Interactable = enableButtons;
			verifyButton.Interactable = enableButtons;
		}

		[SkipRename]
		public void Button_Neat()
		{
			whyPhoneNumberGroup.SetActive(value: false);
			enterNumberGroup.SetActive(value: true);
		}

		[SkipRename]
		public void Button_WhatsThis()
		{
			whyPhoneNumberGroup.SetActive(value: true);
			enterNumberGroup.SetActive(value: false);
		}

		[SkipRename]
		public void Button_Submit()
		{
			if (sendTextRoutine != null || Profiles.LocalProfile == null || (bool)Profiles.LocalProfile.JuniorProfile)
			{
				return;
			}
			SetEnterNumberInfoText("Sending you a text...", enableButtons: false);
			fullPhoneNumber = $"{countryCode}{phoneNumber}";
			sendTextRoutine = StartCoroutine(Profiles.UpdateLocalProfilePhoneNumber(fullPhoneNumber, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (response.Success)
					{
						enterNumberGroup.SetActive(value: false);
						verificationGroup.SetActive(value: true);
						verificationInfoText.text = string.Empty;
					}
					else
					{
						SetEnterNumberInfoText(response.Message, enableButtons: true);
					}
				}
				else
				{
					SetEnterNumberInfoText("Error submitting phone number. Please try again.", enableButtons: true);
				}
				sendTextRoutine = null;
			}));
			AnalyticsHelper.MarkPhoneVerified(verified: false);
		}

		[SkipRename]
		public void Button_Verify()
		{
			if (verifyRoutine != null)
			{
				StopCoroutine(verifyRoutine);
			}
			SetVerificationInfoText("Verifying...", enableButtons: false);
			verifyRoutine = StartCoroutine(Profiles.VerifyLocalProfilePhoneNumber(verificationCode.Trim(), fullPhoneNumber, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (response.Success)
					{
						SetVerificationInfoText("Success!", enableButtons: false);
						AnalyticsHelper.MarkPhoneVerified(verified: true);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Successfully updated!", 3f);
						Player.LocalPlayer.PlayerUI.WatchMenu.PopFlow();
					}
					else
					{
						SetVerificationInfoText(response.Message, enableButtons: true);
					}
				}
				else
				{
					SetVerificationInfoText("Error submitting verification code. Please try again.", enableButtons: true);
