	public class UISelfieDialog : ConfirmUIDialog
	{
		[Header("Selfie")]
		[SerializeField]
		private GameObject selfieGroup;

		[SerializeField]
		private Button3D takeSelfieButton;

		[SerializeField]
		private Text takeSelfieButtonText;

		[SerializeField]
		private Button3D acceptButton;

		[SerializeField]
		private Camera selfieCamera;

		[SerializeField]
		private RawImage selfieImage;

		[SerializeField]
		private Text countdownText;

		[Header("Uploading")]
		[SerializeField]
		private GameObject uploadingGroup;

		[SerializeField]
		private Text uploadingDescriptionText;

		[SerializeField]
		private LoadingRotate loadingRotate;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip countDownTickAudio;

		[SerializeField]
		private RecRoomAudioClip shutterAudio;

		private RenderTexture renderTexture;

		private AltTextureSet selfiePhotoSet = new AltTextureSet();

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private static Action<bool> m_SelfieUpdatedAction;

		private IDisposable _updateToken;

		private Vector3 velocity = Vector3.zero;

		public static event Action<bool> SelfieUpdatedAction
		{
			add
			{
				Action<bool> action = UISelfieDialog.m_SelfieUpdatedAction;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref UISelfieDialog.m_SelfieUpdatedAction, (Action<bool>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<bool> action = UISelfieDialog.m_SelfieUpdatedAction;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref UISelfieDialog.m_SelfieUpdatedAction, (Action<bool>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			selfieGroup.SetActive(value: true);
			countdownText.gameObject.SetActive(value: false);
			uploadingGroup.SetActive(value: false);
			acceptButton.Interactable = false;
			renderTexture = new RenderTexture(2560, 1440, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			selfieCamera.targetTexture = renderTexture;
			selfieCamera.aspect = ShareCamera.SixteenNineAspectRatio;
			selfieCamera.depthTextureMode = DepthTextureMode.Depth;
			if (RecRoomSceneManager.IsInitialized && RecRoomSceneManager.Instance.SceneRenderingSettings != null)
			{
				RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(selfieCamera);
			}
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null && SingletonMonoBehaviour<LocalPlayerController>.Instance.CurrentPlayerType == LocalPlayerController.PlayerType.SCREEN)
			{
				velocity = Vector3.zero;
				_updateToken = this.Update30hz(UpdateCamPosition);
			}
		}

		private void UpdateCamPosition(float deltaTime)
		{
			selfieCamera.transform.position = Vector3.SmoothDamp(selfieCamera.transform.position, Player.LocalPlayer.Head.transform.position + Player.LocalPlayer.Head.transform.forward, ref velocity, deltaTime, float.PositiveInfinity, deltaTime);
			selfieCamera.transform.LookAt(Player.LocalPlayer.Head.transform.position);
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			if (_updateToken != null)
			{
				_updateToken.Dispose();
				_updateToken = null;
			}
			velocity = Vector3.zero;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (renderTexture != null)
			{
				renderTexture.Release();
			}
			if (selfiePhotoSet != null)
			{
				selfiePhotoSet.DestroyTextures();
			}
		}

		private void OnEnable()
		{
			countdownText.gameObject.SetActive(value: false);
			takeSelfieButton.Interactable = true;
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog()
		{
			SetCameraRenderTexture();
			return base.ShowDialog();
		}

		private void SetCameraRenderTexture()
		{
			selfieImage.texture = renderTexture;
		}

		private IEnumerator RunTakeSelfie()
		{
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: true);
			countdownText.text = "3";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "2";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "1";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(shutterAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: false);
			selfiePhotoSet.Render(selfieCamera, renderTexture);
			selfieImage.texture = selfiePhotoSet.MainTexture;
			takeSelfieButton.Interactable = true;
			takeSelfieButtonText.text = "Retake selfie";
			acceptButton.Interactable = true;
		}

		[SkipRename]
		public void Button_TakeSelfie()
		{
			takeSelfieButton.Interactable = false;
			SetCameraRenderTexture();
			StartCoroutine(RunTakeSelfie());
		}

		[SkipRename]
		public void Button_Accept()
		{
			selfieGroup.SetActive(value: false);
			uploadingGroup.SetActive(value: true);
			uploadingDescriptionText.text = "Uploading...";
			Images.SetLocalProfileImage(selfiePhotoSet).Then(delegate
			{
				uploadingDescriptionText.text = "Successfully uploaded!";
				if (UISelfieDialog.SelfieUpdatedAction != null)
				{
					UISelfieDialog.SelfieUpdatedAction(obj: true);
				}
			}).Error(delegate(string e)
			{
				if (string.IsNullOrEmpty(e))
				{
					e = "Error uploading selfie. Please try again.";
				}
				uploadingDescriptionText.text = e;
				if (UISelfieDialog.SelfieUpdatedAction != null)
				{
					UISelfieDialog.SelfieUpdatedAction(obj: false);
				}
			})
				.Finally(delegate
				{
					loadingRotate.Stop();
				});
		}
	}
}
namespace RecRoom
{
	public class MemberConditionalButton : UnityEngine.MonoBehaviour
	{
		private enum ConditionType
		{
			Action,
			Interactivity,
			Visibility
		}

		[SerializeField]
		private Tooltip tooltip;

		[SerializeField]
		private string memberTooltip = "member";

		[SerializeField]
		private string nonMemberTooltip = "non member";

		[SerializeField]
		private ConditionType conditionType;

		[SerializeField]
		private UnityEvent OnMemberClicked;

		[SerializeField]
		private UnityEvent OnNonMemberClicked;

		[SerializeField]
		private bool membersCanInteract = true;

		[SerializeField]
		private bool membersCanSee = true;

		[SerializeField]
		[AutofillOptional(AutofillType.Self, false)]
		private Button3D button;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private ClickableReleaseButton clickableReleaseButton;

		private bool cachedIsMember;

		private void Awake()
		{
			cachedIsMember = Profiles.LocalProfile.Verified;
			UpdateVisibilityAndInteractivity();
			if (conditionType == ConditionType.Action && button != null)
			{
				button.OnClick.AddListener(InvokeButtonClick);
			}
			Profiles.LocalProfileDownloaded += Profiles_LocalProfileDownloaded;
		}

		private void OnDestroy()
		{
			Profiles.LocalProfileDownloaded -= Profiles_LocalProfileDownloaded;
		}

		private void Profiles_LocalProfileDownloaded(Profile localProfile)
		{
			if (localProfile.Verified != cachedIsMember)
			{
				cachedIsMember = localProfile.Verified;
				UpdateVisibilityAndInteractivity();
			}
		}

		private void UpdateVisibilityAndInteractivity()
		{
			if (clickableReleaseButton != null)
			{
				switch (conditionType)
				{
				case ConditionType.Interactivity:
					clickableReleaseButton.Interactable = ((!membersCanInteract) ? (!cachedIsMember) : cachedIsMember);
					break;
				case ConditionType.Visibility:
					clickableReleaseButton.gameObject.SetActive((!membersCanSee) ? (!cachedIsMember) : cachedIsMember);
					break;
				}
			}
			if (tooltip != null)
			{
				tooltip.Message = ((!cachedIsMember) ? nonMemberTooltip : memberTooltip);
			}
		}

		private void InvokeButtonClick()
		{
			if (cachedIsMember)
			{
				OnMemberClicked.Invoke();
			}
			else
			{
				OnNonMemberClicked.Invoke();
			}
		}
	}
}
