[RequireComponent(typeof(PlayerSpecificUIBehaviour))]
public class ProfileImage : UnityEngine.MonoBehaviour
{
	private const float GRAYSCALE_ON = 1f;

	private const float GRAYSCALE_OFF = 0f;

	[Autofill(AutofillType.Self, false)]
	[SerializeField]
	private RawImage profileImage;

	private PlayerSpecificUIBehaviour playerWatcher;

	[SerializeField]
	private bool useGrayscaleForOfflinePlayer;

	private void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
		UpdateProfileImage();
		if (useGrayscaleForOfflinePlayer)
		{
			Material material = profileImage.material;
			Material material2 = UnityEngine.Object.Instantiate(material);
			profileImage.material = material2;
		}
		else
		{
			profileImage.material.SetFloat("_Grayscale", 0f);
		}
	}

	private void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	private void OnEnable()
	{
		Presence.OnPlayerPresenceUpdated += OnPresenceUpdated;
	}

	private void OnDisable()
	{
		Presence.OnPlayerPresenceUpdated -= OnPresenceUpdated;
	}

	private void OnPresenceUpdated(long id)
	{
		if (playerWatcher.PlayerId.HasValue && id == playerWatcher.PlayerId)
		{
			UpdateProfilePresence();
		}
	}

	private void PlayerIdUpdated()
	{
		UpdateProfileImage();
		UpdateProfilePresence();
	}

	private void UpdateProfileImage()
	{
		Profile profile = playerWatcher.CurrentProfile;
		Images.GetProfileImage(profile).Then(delegate(Texture2D image)
		{
			if (this != null && playerWatcher.CurrentProfile == profile)
			{
				profileImage.texture = image;
			}
		});
	}

	private void UpdateProfilePresence()
	{
		if (useGrayscaleForOfflinePlayer && playerWatcher.PlayerId.HasValue)
		{
			PlayerPresence playerPresence = Presence.Get(playerWatcher.PlayerId.Value);
			float value = ((playerPresence != null && playerPresence.AppearsOnlineToMe) ? 0f : 1f);
			profileImage.materialForRendering.SetFloat("_Grayscale", value);
		}
	}
}
public class ProfilePagedGrid : RecyclerPagedGrid<Profile, PlayerButton>
{
	[SerializeField]
	private FoundPlayerResult.ShowDetailsEvent ShowDetailsEvent;

	private PlayerSpecificUIBehaviour.PlayerDisplayMode displayMode;

	private void Start()
	{
		if (ShowDetailsEvent == null)
		{
			return;
		}
		foreach (PlayerButton childUIElement in childUIElements)
		{
			PlayerButton innerChild = childUIElement;
			innerChild.ButtonAction.AddListener(delegate
			{
				ShowDetailsEvent.Invoke(innerChild.CurrentProfile);
			});
		}
	}

	public void SetProfiles(IEnumerable<Profile> profiles, PlayerSpecificUIBehaviour.PlayerDisplayMode displayMode, bool resetPage)
	{
		this.displayMode = displayMode;
		List<Profile> allActiveChildren = ((displayMode != PlayerSpecificUIBehaviour.PlayerDisplayMode.Recent) ? profiles.OrderByDescending(OrderByRelationship).ThenBy(delegate(Profile profile)
		{
			PlayerPresence playerPresence = Presence.Get(profile.Id);
			return playerPresence == null || !playerPresence.AppearsOnlineToMe;
		}).ThenBy(delegate(Profile profile)
		{
			Relationship relationship = Relationships.Get(profile.Id);
			return relationship == null || !relationship.IsFavorited;
		})
			.ThenBy((Profile profile) => profile.DisplayName.GetDecrypted())
			.ThenBy((Profile profile) => profile.Username.GetDecrypted())
			.ToList() : profiles.ToList());
		SetAllActiveChildren(allActiveChildren, resetPage);
	}

	private int OrderByRelationship(Profile profile)
	{
		Relationship relationship = Relationships.Get(profile.Id);
		Relationship.RelationshipType relationshipType = relationship?.Type ?? Relationship.RelationshipType.None;
		if (relationship != null && relationship.Ignored != Relationship.ReciprocalStatus.None)
		{
			return -1;
		}
		switch (relationshipType)
		{
		case Relationship.RelationshipType.Friend:
			return 2;
		case Relationship.RelationshipType.FriendRequestSent:
		case Relationship.RelationshipType.FriendRequestReceived:
			return 1;
		default:
			return 0;
		}
	}

	protected override void SetChild(Profile profile, PlayerButton button, int activeIndex)
	{
		button.SetProfile(profile, displayMode);
	}
}
