	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private Action m_RegisterButtonPressedAction;

	private PlayerMinitar playerMinitar;

	private int bioMaxCharCount = 255;

	private string bio;

	public event Action RegisterButtonPressedAction
	{
		add
		{
			Action action = this.m_RegisterButtonPressedAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_RegisterButtonPressedAction, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = this.m_RegisterButtonPressedAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref this.m_RegisterButtonPressedAction, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	private void Start()
	{
		offlineInvitesButtonText.text = ((!Profiles.LocalProfile.Verified) ? "Offline Invites" : "Update Phone #");
		Player.LocalPlayer.PlayerUI.WatchMenu.FullyVisibleChanged += WatchMenu_FullyVisibleChanged;
		displayNameInputField.InputField.onEndEdit.AddListener(OnDisplayNameFieldEndEdit);
		displayNameInputField.InputField.onValidateInput = OnDisplayNameFieldValidate;
		displayNameInputField.OnSubmitAction += OnDisplayNameFieldSubmitAction;
		bioField.OnSubmitAction += UpdateBio;
		bioField.IsValidFunction = delegate(string text)
		{
			bio = text.Trim();
			if (string.IsNullOrEmpty(bio))
			{
				charLeft.text = bioMaxCharCount.ToString();
			}
			else
			{
				charLeft.text = (bioMaxCharCount - bio.Length).ToString();
			}
			return bio.Length > 0 && bio.Length <= bioMaxCharCount;
		};
		saveButton.Interactable = false;
		subscreenControl.ActiveSubscreenChanged += SubscreenControl_ActiveSubscreenChanged;
