		{
			bodyText = "Register your account for free to " + action + "!";
			yesText = "Register";
			noText = "Not now";
		}
		else
		{
			yesText = "Resend";
			noText = "OK";
			bodyText = "To " + action + ", you first need to verify your account by clicking the link in the email we sent.";
		}
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Members only!", bodyText, yesText, noText).Then(delegate(ConfirmDialogResponses r)
