	{
		Profile localProfile = Profiles.LocalProfile;
		cheerGeneralToggle.Interactable = localProfile.Reputation.CheerGeneral > 0;
		cheerHelpfulToggle.Interactable = localProfile.Reputation.CheerHelpful > 0;
		cheerSportsmanToggle.Interactable = localProfile.Reputation.CheerSportsman > 0;
		cheerGreatHostToggle.Interactable = localProfile.Reputation.CheerGreatHost > 0;
		cheerCreativeToggle.Interactable = localProfile.Reputation.CheerCreative > 0;
		if (localProfile.Reputation.SelectedCheer.HasValue)
		{
			switch (localProfile.Reputation.SelectedCheer.Value)
			{
			case PlayerCheering.CheerCategory.General:
				cheerGeneralToggle.IsOn = true;
				break;
			case PlayerCheering.CheerCategory.Helpful:
				cheerHelpfulToggle.IsOn = true;
				break;
			case PlayerCheering.CheerCategory.Sportmanship:
				cheerSportsmanToggle.IsOn = true;
				break;
			case PlayerCheering.CheerCategory.GreatHost:
				cheerGreatHostToggle.IsOn = true;
				break;
			case PlayerCheering.CheerCategory.Creative:
				cheerCreativeToggle.IsOn = true;
				break;
			}
		}
		if (playerMinitar != null)
		{
			playerMinitar.Refresh();
		}
	}

	private char OnDisplayNameFieldValidate(string text, int charIndex, char addedChar)
	{
		if (ProfileExtensions.DisplaynameValidateRegex.IsMatch(addedChar.ToString()))
		{
			return addedChar;
		}
		return '\0';
	}

	private void OnDisplayNameFieldEndEdit(string value)
	{
		displayNameInputField.Text = Profiles.LocalProfile.DisplayName;
	}

	private void OnDisplayNameFieldSubmitAction()
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			return;
		}
		string newDisplayName = displayNameInputField.Text.Trim();
		if (IsDisplayNameValid(newDisplayName))
		{
			Profiles.UpdateLocalProfileDisplayName(newDisplayName, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (response.Success)
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Name Updated!", 3f);
					}
					else
					{
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Error updating name!", response.Message, 5f);
						UnityEngine.Debug.LogError("Failed to update display name: " + response.Message);
					}
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Error updating name!", response.Message, 5f);
					UnityEngine.Debug.LogError("Failed to update display name: " + error);
				}
				displayNameInputField.InputField3D.DeselectInputField();
			});
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Invalid name!", 3f);
			displayNameInputField.InputField3D.DeselectInputField();
		}
	}

	private void UpdateBio()
	{
		if (Profiles.LocalProfile.IsJunior())
		{
			return;
		}
		UpdateBioTabUI("Updating...", buttonsInteractable: false);
		Profiles.UpdateLocalProfileBio(bio, delegate(string error, OkResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Success)
				{
					UpdateBioTabUI("Successfully updated bio!", buttonsInteractable: false);
					if (Player.LocalPlayer != null)
					{
						Player.LocalPlayer.PlayerEvents.UpdatedPlayerBio();
					}
				}
				else
				{
					UpdateBioTabUI("Failed to update bio: " + response.Message, buttonsInteractable: true);
					UnityEngine.Debug.LogError("Failed to update bio: " + response.Message);
				}
			}
			else
			{
				UpdateBioTabUI("Error updating bio: " + response.Message, buttonsInteractable: true);
				UnityEngine.Debug.LogError("Failed to update bio: " + error);
			}
		});
	}

	private void UpdateBioTabUI(string text, bool buttonsInteractable)
	{
		infoText.text = text;
		bioField.Interactable = buttonsInteractable;
	}

