	private void SelectedCheerChangedHelper(PlayerCheering.CheerCategory category, bool isOn)
	{
		PlayerCheering.CheerCategory? selectedCheer = Profiles.LocalProfile.Reputation.SelectedCheer;
		if (isOn && (!selectedCheer.HasValue || selectedCheer.Value != category))
		{
			PlayerCheering.UpdateSelectedCheer(category, null);
		}
		else if (!isOn && selectedCheer.HasValue && selectedCheer.Value == category)
		{
			PlayerCheering.UpdateSelectedCheer(null, null);
		}
	}
