public class SavedOutfitsWatchUIFlow : WatchUIFlow
{
	[SerializeField]
	private Texture2D emptySlotTexture;

	[SerializeField]
	private Texture2D loadingPreviewSlotTexture;

	private UISavedOutfitSlot[] uISavedOutfitSlots;

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		uISavedOutfitSlots = base.gameObject.GetComponentsInChildren<UISavedOutfitSlot>(includeInactive: true);
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		UISavedOutfitSlot[] array = uISavedOutfitSlots;
		foreach (UISavedOutfitSlot uISavedOutfitSlot in array)
		{
			SavedOutfit value = null;
			Avatars.LocalSavedOutfits.TryGetValue(uISavedOutfitSlot.SlotIndex, out value);
