namespace AGUI.StackedUI.Dialog
{
	public class SaveOutfitSlotWatchUIFlow : WatchUIFlow
	{
		[Header("Selfie")]
		[SerializeField]
		private GameObject selfieGroup;

		[SerializeField]
		private Button3D takeSelfieButton;

		[SerializeField]
		private Text takeSelfieButtonText;

		[SerializeField]
		private Button3D acceptButton;

		[SerializeField]
		private Camera selfieCamera;

		[SerializeField]
		private RawImage selfieImage;

		[SerializeField]
		private Text countdownText;

		[Header("Uploading")]
		[SerializeField]
		private GameObject uploadingGroup;

		[SerializeField]
		private Text uploadingDescriptionText;

		[SerializeField]
		private LoadingRotate loadingRotate;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip countDownTickAudio;

		[SerializeField]
		private RecRoomAudioClip shutterAudio;

		private RenderTexture renderTexture;

		private AltTextureSet selfiePhotoSet = new AltTextureSet();

		private string defaultTakePictureText = string.Empty;

		private int currentSlotIndex;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			renderTexture = new RenderTexture(256, 256, 4);
			selfieCamera.targetTexture = renderTexture;
			defaultTakePictureText = takeSelfieButtonText.text;
		}

		private void OnEnable()
		{
			countdownText.gameObject.SetActive(value: false);
			takeSelfieButton.Interactable = true;
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			SetCameraRenderTexture();
			selfieGroup.SetActive(value: true);
			uploadingGroup.SetActive(value: false);
			countdownText.gameObject.SetActive(value: false);
			acceptButton.Interactable = false;
			takeSelfieButtonText.text = defaultTakePictureText;
			uploadingDescriptionText.text = string.Empty;
		}

		private void SetCameraRenderTexture()
		{
			selfieImage.texture = renderTexture;
		}

		private IEnumerator RunTakeSelfie()
		{
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: true);
			countdownText.text = "3";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "2";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "1";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(shutterAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: false);
			selfiePhotoSet.Render(selfieCamera, renderTexture);
			selfieImage.texture = selfiePhotoSet.MainTexture;
			takeSelfieButton.Interactable = true;
			takeSelfieButtonText.text = "Retake picture";
			acceptButton.Interactable = true;
		}

		[SkipRename]
		public void Button_TakeSelfie()
		{
			takeSelfieButton.Interactable = false;
			SetCameraRenderTexture();
			StartCoroutine(RunTakeSelfie());
		}

		public void SetSlotIndex(int slotIndex)
		{
			currentSlotIndex = slotIndex;
		}

		[SkipRename]
		public void Button_Accept()
		{
			selfieGroup.SetActive(value: false);
			uploadingGroup.SetActive(value: true);
			uploadingDescriptionText.text = "Uploading...";
			SavedOutfit savedOutfit = Player.LocalPlayer.PlayerOutfit.LocalGetCurrentOutfit();
			if (savedOutfit != null)
			{
				savedOutfit.Slot = currentSlotIndex;
				SingletonMonoBehaviour<SessionManager>.Instance.StartCoroutine(RunUploadSavedOutfit(selfiePhotoSet, savedOutfit));
			}
			else
			{
				uploadingDescriptionText.text = "Failed to get local outfit data. Try again later!";
			}
		}

		private IEnumerator RunUploadSavedOutfit(AltTextureSet textureSet, SavedOutfit savedOutfit)
		{
			string previewImageName = string.Empty;
			yield return Images.UploadSavedImage(textureSet, Images.SavedImageType.OutfitThumbnail).Error(delegate(string error)
			{
				uploadingDescriptionText.text = "Failed to upload image, error : " + error;
			}).Then(delegate(string imageName)
			{
				previewImageName = imageName;
			});
			if (!string.IsNullOrEmpty(previewImageName))
			{
				savedOutfit.PreviewImageName = previewImageName;
				yield return Avatars.UpdateSavedOutfit(savedOutfit, delegate(string error)
				{
					if (string.IsNullOrEmpty(error))
					{
						uploadingDescriptionText.text = "Successfully saved!";
						if (Player.LocalPlayerExists)
						{
							Player.LocalPlayer.PlayerEvents.SavedOutfitSlot();
						}
					}
					else
					{
						uploadingDescriptionText.text = "Failed to save, error : " + error;
					}
				});
			}
			loadingRotate.Stop();
			yield return new WaitForSeconds(2f);
			if (base.IsCurrentFlow)
			{
				base.UIBase.PopFlow();
			}
		}
	}
}
public class UISavedOutfitSlot : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Button3D loadButton;

	[SerializeField]
	private RawImage previewImage;

	[SerializeField]
	private int slotIndex;

	private SavedOutfit savedOutfit;

	public int SlotIndex => slotIndex;

	[SkipRename]
	public void Button_Load()
	{
		if (savedOutfit != null && !string.IsNullOrEmpty(savedOutfit.OutfitSelections))
		{
			PlayerOutfit playerOutfit = Player.LocalPlayer.PlayerOutfit;
			playerOutfit.LocalLoadSavedOutfit(savedOutfit);
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Loaded saved outfit", 3f);
		}
		else
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Error", "Failed to load saved outfit", 3f);
		}
	}

	[SkipRename]
	public void Button_Save()
	{
		WatchUI watchMenu = Player.LocalPlayer.PlayerUI.WatchMenu;
		SaveOutfitSlotWatchUIFlow flowByType = watchMenu.GetFlowByType<SaveOutfitSlotWatchUIFlow>();
		flowByType.SetSlotIndex(slotIndex);
		watchMenu.PushFlow(flowByType);
	}

	public void SetSavedOutfit(SavedOutfit newSavedOutfit, Texture2D emptyTexture, Texture2D loadingPreviewTexture)
	{
		savedOutfit = newSavedOutfit;
		loadButton.Interactable = savedOutfit != null;
		if (savedOutfit != null)
		{
			previewImage.texture = loadingPreviewTexture;
			if (string.IsNullOrEmpty(savedOutfit.PreviewImageName))
			{
				return;
			}
			Images.GetImage(savedOutfit.PreviewImageName).Then(delegate(Texture2D t)
			{
				if (this != null && savedOutfit != null && savedOutfit.PreviewImageName == t.name)
				{
					previewImage.texture = t;
				}
			});
		}
		else
		{
			previewImage.texture = emptyTexture;
		}
	}
}
