	private Dictionary<string, GameObject> spawnedTools = new Dictionary<string, GameObject>();

	private void Start()
	{
		recordingFeedback.SetActive(value: false);
	}

	[SkipRename]
	public void ButtonPress_SpawnTutorialCamera()
	{
		SessionManager.DeveloperGatedActionCoroutine(delegate
		{
			DestroyTutorialCamera();
			Vector3 forward = Player.LocalPlayer.Head.transform.forward;
			forward.y = -0.5f;
			Vector3 position = Player.LocalPlayer.Head.transform.position + forward;
			Quaternion rotation = Quaternion.Euler(0f, 0f - Player.LocalPlayer.Head.transform.rotation.eulerAngles.y, 0f);
			tutorialCamera = PhotonNetwork.Instantiate("[TutorialCamera]", position, rotation, 1f, 0);
			if (tutorialCamera != null)
			{
				tutorialCameraDollyManager = tutorialCamera.gameObject.GetComponent<TutorialCameraDollyManager>();
				tutorialCameraDollyManager.dollyTime = dollySpeedSlider.value;
				dollySpeedLabel.text = $"Dolly Speed ({dollySpeedSlider.value:0.00})";
			}
		});
		AnalyticsHelper.DebugAction("SpawnTutorialCamera");
	}

	[SkipRename]
	public void ButtonPress_DestroyTutorialCamera()
	{
		DestroyTutorialCamera();
	}

	private void DestroyTutorialCamera()
	{
		if (tutorialCamera != null)
		{
			tutorialCameraDollyManager.TearDown();
			tutorialCameraDollyManager.mode = TutorialCameraDollyManager.DollyMode.Stationary;
			PhotonNetwork.Destroy(tutorialCamera);
			tutorialCamera = null;
