		{
			tutorialCameraDollyManager.SetEasing(DoEasing);
		}
	}

	[SkipRename]
	public void SetSmoothing(bool DoSmooth)
	{
		if (tutorialCamera != null)
		{
			TutorialCamera component = tutorialCamera.GetComponent<TutorialCamera>();
			if (DoSmooth)
			{
				component.SetPositionSmoothingTime(0.25f);
			}
			else
			{
				component.SetPositionSmoothingTime(0.05f);
			}
		}
	}

	[SkipRename]
	public void MakeVertical()
	{
		tutorialCamera.transform.rotation = Quaternion.Euler(0f, base.transform.rotation.eulerAngles.y, 0f);
		if (tutorialCameraDollyManager != null)
		{
			tutorialCameraDollyManager.MakeVertical();
		}
