	{
		if (!(tutorialCamera != null))
		{
			return;
		}
		TutorialCamera component = tutorialCamera.GetComponent<TutorialCamera>();
		component.ToggleRecording();
		if (component.IsRecording)
		{
			recordingFeedback.SetActive(value: true);
		}
		else
		{
			recordingFeedback.SetActive(value: false);
		}
		if (tutorialCameraDollyManager != null)
		{
