namespace RecRoom
{
	public class AgeCheckUIDialog : ConfirmUIDialog
	{
		[SerializeField]
		private MonthUIRotator monthRotator;

		[SerializeField]
		private IntRangeUIRotator yearPrefixRotator;

		[SerializeField]
		private IntRangeUIRotator yearSuffixRotator;

		[SerializeField]
		private IntRangeUIRotator dayRotator;

		[SerializeField]
		private Button3D okButton;

		private int? Year => YearCalc(yearPrefixRotator.Value, yearSuffixRotator.Value);

		public DateTime? BirthDate
		{
			get
			{
				if (Year.HasValue && monthRotator.Value.HasValue && dayRotator.Value.HasValue)
				{
					try
					{
						return new DateTime(Year.Value, monthRotator.Value.Value, dayRotator.Value.Value);
					}
					catch
					{
						return null;
					}
				}
				return null;
			}
		}

		private void Start()
		{
			Rotator_UpdateOKButton();
		}

		public static int? YearCalc(int? yearPrefix, int? yearSuffix)
		{
			if (yearPrefix.HasValue && yearSuffix.HasValue)
			{
				return yearPrefix.Value * 100 + yearSuffix.Value;
			}
			return null;
		}

		[SkipRename]
		public void Rotator_UpdateOKButton()
		{
			okButton.enabled = BirthDate.HasValue;
		}
	}
}
