		[SerializeField]
		private Button3D loginButton;

		[SerializeField]
		private Button3D createButton;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private TextMeshProUGUI emptyDisplayInfoText;

		[SerializeField]
		private ProfileSelectionPagedGrid pagedGrid;

		[SerializeField]
		private GameObject createProfilePerPlayerReminder;

		private TextMeshProUGUI activeInfoText;

		private void Awake()
		{
			pagedGrid.PageChangeEvent += OnGridPageChange;
		}

		protected override void OnDestroy()
		{
			pagedGrid.PageChangeEvent -= OnGridPageChange;
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			UpdateGridWithProfiles();
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Menu.HideKeyboard();
		}

		public void UpdateGridWithProfiles()
		{
			List<Profile> cachedProfiles = SingletonMonoBehaviour<ProfileSelectionManager>.Instance.cachedProfiles;
			pagedGrid.SetProfiles(cachedProfiles);
			int count = cachedProfiles.Count;
			if (count > 0)
			{
				activeInfoText = infoText;
			}
			else
			{
				activeInfoText = emptyDisplayInfoText;
			}
			createProfilePerPlayerReminder.gameObject.SetActive(count > 0 && count < 3);
		}

		private void OnGridPageChange()
		{
			base.UIBase.RefreshTopFlow();
		}

		public void SetInfoText(string info, bool enableButtons)
		{
			activeInfoText.text = info;
			loginButton.Interactable = enableButtons;
			createButton.Interactable = enableButtons;
			pagedGrid.EnableAllButtons(enableButtons);
		}

		[SkipRename]
		public void Button_SelectProfile(Profile profile)
		{
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.LoginToCachedProfile(profile);
		}

		[SkipRename]
		public void Button_CreateProfile()
		{
			bool result = false;
			if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode && bool.TryParse(GameConfigs.Get("Screens.ForceWaitlist"), out result) && result)
			{
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.ShowScreensModeAccountCreationDialog();
			}
			else
			{
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.CreateNewAccount();
			}
		}

		[SkipRename]
		public void Button_Login()
		{
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Login();
		}
	}
	public class UIAccountStatusDialog : ConfirmUIDialog<UIAccountStatusDialog.Status>
	{
		public enum Status
		{
			Creating,
			CreateSuccess,
			CreateFail,
			PendingJunior,
			Banned,
			PendingEmailVerification
		}

		[SerializeField]
		private Text titleText;

		[SerializeField]
		private Text bodyText;

		[SerializeField]
		private Button3D helpPageButton;

		[SerializeField]
		private Button3D okButton;

		[SerializeField]
		private Text okButtonText;

		[SerializeField]
		private Button3D reEnterEmailButton;

		private const string CREATE_SUCCESS_TEXT = "Please ensure everyone active at your location knows:\n\n1. One player per account\n2. Players 12 and younger may ONLY be active on a junior account";

		private const string PENDING_JR_TEXT = "A moderator has activated junior status on this account. Junior accounts support players 12 or younger. Please enter a parent / guardian’s email or contact conduct@againstgrav.com to appeal.";

		private const string PENDING_VERIFICATION_TEXT = "Please finish registration using the email you received.";

		public override IPromise<ConfirmDialogResponses> ShowDialog(Status status)
		{
			UpdateUIState(status);
			return base.ShowDialog();
		}

		public void UpdateUIState(Status status, string text = null)
		{
			switch (status)
			{
			case Status.Creating:
				titleText.text = "Account creation";
				bodyText.text = "Creating your account...";
				helpPageButton.gameObject.SetActive(value: false);
				okButton.gameObject.SetActive(value: false);
				reEnterEmailButton.gameObject.SetActive(value: false);
				break;
			case Status.CreateSuccess:
				titleText.text = string.Concat("Account \"", Profiles.LocalProfile.DisplayName, "\" created");
				bodyText.text = "Please ensure everyone active at your location knows:\n\n1. One player per account\n2. Players 12 and younger may ONLY be active on a junior account";
				helpPageButton.gameObject.SetActive(value: true);
				okButton.gameObject.SetActive(value: true);
				okButtonText.text = "Launch game";
				reEnterEmailButton.gameObject.SetActive(value: false);
				break;
			case Status.CreateFail:
				titleText.text = "Error creating account";
				bodyText.text = ((!string.IsNullOrEmpty(text)) ? text : "Unknown error occurred.");
				helpPageButton.gameObject.SetActive(value: false);
				okButton.gameObject.SetActive(value: true);
				okButtonText.text = "Back";
				reEnterEmailButton.gameObject.SetActive(value: false);
				break;
			case Status.PendingJunior:
				titleText.text = "Junior status activated";
				bodyText.text = "A moderator has activated junior status on this account. Junior accounts support players 12 or younger. Please enter a parent / guardian’s email or contact conduct@againstgrav.com to appeal.";
				helpPageButton.gameObject.SetActive(value: true);
				okButton.gameObject.SetActive(value: true);
				okButtonText.text = "Continue";
				reEnterEmailButton.gameObject.SetActive(value: false);
				break;
			case Status.PendingEmailVerification:
				titleText.text = "Waiting for email verification";
				bodyText.text = "Please finish registration using the email you received.";
				helpPageButton.gameObject.SetActive(value: false);
				okButton.gameObject.SetActive(value: false);
				reEnterEmailButton.gameObject.SetActive(value: true);
				break;
			case Status.Banned:
				titleText.text = "You have been banned for";
				bodyText.text = ModerationManager.GetBannedText();
				helpPageButton.gameObject.SetActive(value: false);
				okButton.gameObject.SetActive(value: false);
				reEnterEmailButton.gameObject.SetActive(value: false);
				break;
			}
		}

		public void Button_HelpPage()
		{
			WebBrowser.ShowHelpWebPage();
		}

		public override void Button_Affirmative()
		{
			Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: false);
		}

		public void Button_ReenterEmail()
		{
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.ShowVerifyEmailDialog(null, Profiles.LocalProfile.IsJunior()).Then((Action)delegate
			{
				SingletonMonoBehaviour<ProfileSelectionManager>.Instance.StackedUI.ShowAccountStatusDialog(Status.PendingEmailVerification);
			});
		}
	}
	public class UIBirthdayDialog : UIDateSelectionDialog
	{
		private void Awake()
		{
			customDateValidation = BirthdayDateValidation;
		}

		private string BirthdayDateValidation(int month, int day, int year)
		{
			DateTime now = DateTime.Now;
			if (year >= now.Year - 1 || year < now.Year - 120)
			{
				return "That year doesn't make sense!";
			}
			if (month < 1 || month > 12)
			{
				return "That month doesn't make sense!";
			}
			return null;
		}
	}
	public class UILoginDialog : ConfirmUIDialog
	{
		public static Action<string, string, bool> OnLoginSubmitted;

		[SerializeField]
		private ValidatedButtonInputField usernameField;

		[SerializeField]
		private ValidatedButtonInputField passwordField;

		[SerializeField]
		private ToggleButton3D rememberMeToggle;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private Button3D submitButton;

		private string username = string.Empty;

		private string password = string.Empty;

		private void Start()
		{
			usernameField.InputField3D.SelectInputField();
			rememberMeToggle.IsOn = true;
		}

		public void SetInfoText(string info, bool enableButtons)
		{
			infoText.text = info;
			usernameField.Interactable = enableButtons;
			passwordField.Interactable = enableButtons;
			rememberMeToggle.Interactable = enableButtons;
			submitButton.Interactable = enableButtons;
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog()
		{
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Menu.ShowKeyboard();
			infoText.text = string.Empty;
			usernameField.IsValidFunction = delegate(string username)
			{
				this.username = username;
				return this.username.Trim().Length >= 2 && password.Trim().Length >= 8;
			};
			passwordField.IsValidFunction = delegate(string pw)
			{
				password = pw;
				return username.Trim().Length >= 2 && password.Trim().Length >= 8;
			};
			return base.ShowDialog();
		}

		[SkipRename]
		public void Button_Submit()
		{
			if (OnLoginSubmitted != null)
			{
				OnLoginSubmitted(username, password, rememberMeToggle.IsOn);
			}
		}
	}
	public class UIRegistrationDialog : ConfirmUIDialog<bool, bool, string>
	{
		public static Action<string> OnValidEmailEntered;

		public static Action OnPrivacyPolicySelected;

		public static Action OnWhyRegisterSelected;

		[Header("Registration")]
		[SerializeField]
		private GameObject registrationGroup;

		[SerializeField]
		private TextMeshProUGUI additionalContextText;

		[SerializeField]
		private TextMeshProUGUI descriptionText;

		[SerializeField]
		private ValidatedButtonInputField emailInputField;

		[SerializeField]
		private Button3D skipButton;

		[SerializeField]
		private Button3D submitButton;

		[SerializeField]
		private Button3D privacyPolicyButton;

		[SerializeField]
		private Button3D whyRegisterButton;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[Header("Confirmation")]
		[SerializeField]
		private GameObject confirmationGroup;

		[SerializeField]
		private Button3D resendButton;

		[SerializeField]
		private TextMeshProUGUI resentText;

		[Header("Why Register")]
		[SerializeField]
		private GameObject whyRegisterGroup;

		[SerializeField]
		private TextMeshProUGUI byConfirmingText;

		private float resendInterval = 10f;

		private bool emailValid;

		private string email = string.Empty;

		private bool gaveEmailBefore;

		private bool forceRegistration;

		private bool inProfileSelectionScene;

		private void Start()
		{
			emailInputField.InputField3D.SelectInputField();
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			inProfileSelectionScene = SceneManagerHelper.ActiveSceneName == "ProfileSelection";
			if (!inProfileSelectionScene)
			{
				SetUpFlow();
			}
		}

		public void SetUpFlow()
		{
			if (SingletonMonoBehaviour<LocalPlayerController>.IsInitialized && SingletonMonoBehaviour<LocalPlayerController>.Instance.InScreenDisplayMode)
			{
				int result = 0;
				if (int.TryParse(GameConfigs.Get("Screens.ForceVerification"), out result) && result == 1)
				{
					forceRegistration = true;
				}
			}
			else
			{
				int result2 = 0;
				if (int.TryParse(GameConfigs.Get("VR.ForceVerification"), out result2) && result2 == 1)
				{
					forceRegistration = true;
				}
			}
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				componentInChildren.ShowBackButton = !forceRegistration && !inProfileSelectionScene;
				componentInChildren.ShowExpandButton = !inProfileSelectionScene;
			}
			emailInputField.IsValidFunction = delegate(string email)
			{
				this.email = email;
				emailValid = UnityExtensions.IsValidEmail(email);
				return emailValid;
			};
			SetUpRegistrationGroup();
		}

		private void SetUpRegistrationGroup()
		{
			skipButton.gameObject.SetActive(!forceRegistration && inProfileSelectionScene);
			submitButton.Interactable = false;
			infoText.text = string.Empty;
		}

		public void SetTitleText(string titleText)
		{
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				componentInChildren.Title = titleText;
			}
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(bool fromReminder, bool isJunior, string additionalContext)
		{
			gaveEmailBefore = Profiles.LocalProfile != null && Profiles.LocalProfile.RegistrationStatus == RegistrationStatus.PendingEmailVerification;
			registrationGroup.SetActive(!gaveEmailBefore || fromReminder);
			confirmationGroup.SetActive(gaveEmailBefore && !fromReminder);
			whyRegisterGroup.SetActive(value: false);
			descriptionText.text = ((!isJunior) ? "Enter your email:" : "Enter your parent / guardian's email:");
			additionalContextText.text = additionalContext;
			additionalContextText.gameObject.SetActive(!string.IsNullOrEmpty(additionalContext));
			byConfirmingText.text = ((!isJunior) ? "By confirming your email you can..." : "By confirming your parent/guardian's email you can...");
			return base.ShowDialog();
		}

		public void SetInfoText(string info, bool enableButtons)
		{
			infoText.text = info;
			emailInputField.Interactable = enableButtons;
			skipButton.Interactable = enableButtons;
			submitButton.Interactable = enableButtons;
			privacyPolicyButton.Interactable = enableButtons;
			whyRegisterButton.Interactable = enableButtons;
		}

		private IEnumerator ShowResentFeedback()
		{
			resendButton.Interactable = false;
			resentText.text = "Email resent!";
			yield return new WaitForSeconds(resendInterval);
			resentText.text = string.Empty;
			resendButton.Interactable = true;
		}

		private IEnumerator UploadEmail()
		{
			if (!UnityExtensions.IsValidEmail(email))
			{
				yield break;
			}
			yield return Login.RegisterAccount(email, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (!response.Success)
					{
						SetInfoText(response.Message, enableButtons: true);
					}
					else
					{
						SetInfoText("Success!", enableButtons: true);
						SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Success!", "Check your email", 3f);
						Player.LocalPlayer.PlayerUI.WatchMenu.PopFlow();
					}
				}
				else
				{
					SetInfoText("Error! Failed to set email.", enableButtons: true);
					UnityEngine.Debug.LogError(error);
				}
			});
		}

		[SkipRename]
		public void Button_WhyRegister()
		{
			if (OnWhyRegisterSelected != null)
			{
				OnWhyRegisterSelected();
			}
			whyRegisterGroup.SetActive(value: true);
			registrationGroup.SetActive(value: false);
		}

		[SkipRename]
		public void Button_Neat()
		{
			whyRegisterGroup.SetActive(value: false);
			registrationGroup.SetActive(value: true);
		}

		[SkipRename]
		public void Button_Skip()
		{
			if (OnValidEmailEntered != null)
			{
				OnValidEmailEntered(null);
			}
			if (!inProfileSelectionScene)
			{
				Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
			}
		}

		[SkipRename]
		public void Button_ShowPrivacyPolicy()
		{
			if (OnPrivacyPolicySelected != null)
			{
				OnPrivacyPolicySelected();
			}
			WebBrowser.ShowPrivacyPolicyWebPage();
		}

		[SkipRename]
		public void Button_Submit()
		{
			if (OnValidEmailEntered != null)
			{
				OnValidEmailEntered(email);
			}
			if (!inProfileSelectionScene)
			{
				SetInfoText("Setting email...", enableButtons: false);
				StartCoroutine(UploadEmail());
			}
		}

		[SkipRename]
		public void Button_Resend()
		{
			SetUpRegistrationGroup();
			registrationGroup.SetActive(value: true);
			confirmationGroup.SetActive(value: false);
			emailInputField.InputField3D.ForcePressed();
		}
	}
