	public class UIVerifyEmailDialog : ConfirmUIDialog<bool>
	{
		[Header("WhyConfirm")]
		[SerializeField]
		private GameObject whyConfirmGroup;

		[SerializeField]
		private TextMeshProUGUI byConfirmingText;

		[Header("InputEmail")]
		[SerializeField]
		private GameObject inputEmailGroup;

		[SerializeField]
		private ValidatedButtonInputField emailInputField;

		[SerializeField]
		private TextMeshProUGUI infoTextField;

		[SerializeField]
		private Button3D sendEmailButton;

		[Header("ConfirmPrompt")]
		[SerializeField]
		private GameObject confirmPromptGroup;

		[Header("Skip buttons")]
		[SerializeField]
		private Button3D whyConfirmSkipButton;

		public Action<string, string> AnalyticsAction;

		private bool emailValid;

		private string email = string.Empty;

		private DateTime? lastPressTime;

		private float secondsBetweenEmailSubmits = 15f;

		private Coroutine sendDelayCoroutine;

		private Coroutine displayDelayCoroutine;

		private bool isJunior = true;

		private const string CONFIRM_EMAIL_BENEFITS = "confirmEmailBenefits";

		private const string CONFIRM_EMAIL_INPUT = "confirmEmailInput";

		private const string CONFIRM_EMAIL_SENT = "confirmEmailSent";

		private const string CONFIRM_EMAIL_ERROR = "confirmEmailError";

		private const string RESULT_OK = "okay";

		private const string RESULT_LATER = "later";

		private const string RESULT_SUCCESS = "success";

		private const string SEND_LINK = "sendLink";

		private const string PRIVACY_POLICY = "privacyPolicy";

		private const string REENTER_EMAIL = "reenterEmail";

		private const string DONE = "done";

		private const string FAIL_TO_SEND = "failToSend";

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			SetUpFlow();
		}

		public void SetUpFlow()
		{
			emailInputField.IsValidFunction = delegate(string email)
			{
				this.email = email;
				emailValid = UnityExtensions.IsValidEmail(email);
				return emailValid;
			};
			SetUpWhyConfirmGroup();
		}

		private void SetUpWhyConfirmGroup()
		{
			whyConfirmGroup.SetActive(value: true);
			inputEmailGroup.SetActive(value: false);
			confirmPromptGroup.SetActive(value: false);
			if (whyConfirmSkipButton != null)
			{
				whyConfirmSkipButton.gameObject.SetActive(!SingletonMonoBehaviour<ProfileSelectionManager>.Instance.ForceAccountVerification);
			}
			SetInfoText(string.Empty);
			byConfirmingText.text = ((!isJunior) ? "By confirming your email you can..." : "By confirming your parent/guardian's email you can...");
		}

		private void SetUpInputEmailGroup()
		{
			whyConfirmGroup.SetActive(value: false);
			inputEmailGroup.SetActive(value: true);
			confirmPromptGroup.SetActive(value: false);
			SetInfoText(string.Empty);
			emailInputField.InputField3D.SelectInputField();
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Menu.ShowKeyboard();
			if (sendDelayCoroutine != null && displayDelayCoroutine == null)
			{
				displayDelayCoroutine = StartCoroutine(DisplayWaitTimeToUser());
			}
		}

		private void SetUpConfirmPromptGroup()
		{
			whyConfirmGroup.SetActive(value: false);
			inputEmailGroup.SetActive(value: false);
			confirmPromptGroup.SetActive(value: true);
			SingletonMonoBehaviour<ProfileSelectionManager>.Instance.Menu.HideKeyboard();
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(bool isJunior)
		{
			this.isJunior = isJunior;
			SetUpWhyConfirmGroup();
			return base.ShowDialog();
		}

		private void SetInfoText(string message)
		{
			infoTextField.text = message;
		}

		private IEnumerator DisableSendButtonForTime(float disableTime)
		{
			sendEmailButton.Interactable = false;
			yield return new WaitForSeconds(disableTime);
			sendEmailButton.Interactable = true;
			sendDelayCoroutine = null;
		}

		private IEnumerator DisplayWaitTimeToUser()
		{
			double delayTimeRemaining = 0.0;
			while (true)
			{
				double num;
				delayTimeRemaining = (num = (double)secondsBetweenEmailSubmits - (DateTime.UtcNow - lastPressTime.Value).TotalSeconds);
				if (!(num > 0.0))
				{
					break;
				}
				int fullSecondsRemaining = (int)Math.Ceiling(delayTimeRemaining);
				SetInfoText(string.Format("Please wait {0} {1} before sending another email", fullSecondsRemaining, (!(delayTimeRemaining > 1.0)) ? "second" : "seconds"));
				yield return null;
			}
			SetInfoText(string.Empty);
			displayDelayCoroutine = null;
		}

		private void AllowSendingImmediately()
		{
			lastPressTime = null;
			if (sendDelayCoroutine != null)
			{
				StopCoroutine(sendDelayCoroutine);
				sendDelayCoroutine = null;
			}
			if (displayDelayCoroutine != null)
			{
				StopCoroutine(displayDelayCoroutine);
				displayDelayCoroutine = null;
			}
			sendEmailButton.Interactable = true;
		}

		private IEnumerator UploadEmail()
		{
			DateTime? dateTime = lastPressTime;
			if (dateTime.HasValue && (DateTime.UtcNow - lastPressTime.Value).TotalSeconds < (double)secondsBetweenEmailSubmits)
			{
				SetInfoText("Please wait a few seconds before sending another email");
				yield break;
			}
			lastPressTime = DateTime.UtcNow;
			sendDelayCoroutine = StartCoroutine(DisableSendButtonForTime(secondsBetweenEmailSubmits));
			LogAnalytics("confirmEmailInput", "sendLink");
			SetInfoText("Sending confirmation...");
			if (!UnityExtensions.IsValidEmail(email))
			{
				yield break;
			}
			yield return Login.RegisterAccount(email, delegate(string error, OkResponse response)
			{
				if (string.IsNullOrEmpty(error))
				{
					if (!response.Success)
					{
						LogAnalytics("confirmEmailError", null);
						SetInfoText(response.Message);
						AllowSendingImmediately();
					}
					else
					{
						LogAnalytics("confirmEmailSent", "success");
						SetUpConfirmPromptGroup();
					}
				}
				else
				{
					LogAnalytics("confirmEmailError", "failToSend");
					SetInfoText("Error! Failed to send email.");
					UnityEngine.Debug.LogError(error);
					AllowSendingImmediately();
				}
			});
		}

		private void LogAnalytics(string majorStep, string minorStep)
		{
			if (AnalyticsAction != null)
			{
				AnalyticsAction(majorStep, minorStep);
			}
		}

		[SkipRename]
		public void Button_WhyConfirm_ConfirmNow()
		{
			LogAnalytics("confirmEmailBenefits", "okay");
			SetUpInputEmailGroup();
		}

		[SkipRename]
		public void Button_WhyConfirm_Later()
		{
			LogAnalytics("confirmEmailBenefits", "later");
			Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_InputEmail_SendLink()
		{
			email = emailInputField.Text;
			StartCoroutine(UploadEmail());
		}

		[SkipRename]
		public void Button_InputEmail_Later()
		{
			LogAnalytics("confirmEmailInput", "later");
			Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_InputEmail_ShowPrivacyPolicy()
		{
			LogAnalytics("confirmEmailInput", "privacyPolicy");
			WebBrowser.ShowPrivacyPolicyWebPage();
		}

		[SkipRename]
		public void Button_ConfirmPrompt_ReEnterEmail()
		{
			LogAnalytics("confirmEmailSent", "reenterEmail");
