	public class CloneRoomUIDialog : UIDialog<RecNet.Room, RecNet.Room>
	{
		[SerializeField]
		private ValidatedButtonInputField roomNameField;

		[SerializeField]
		private TextMeshProUGUI descriptionText;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private Button3D cancelButton;

		[SerializeField]
		private Button3D saveButton;

		private string roomName = string.Empty;

		private RecNet.Room targetRoom;

		private bool resetInfoText;

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(null, shouldCloseDialog: true);
		}

		public override IPromise<RecNet.Room> ShowDialog(RecNet.Room room)
		{
			targetRoom = room;
			if (targetRoom != null)
			{
				SetInfoText(string.Empty, activeButtons: true);
				descriptionText.text = $"This will create a new, private copy of ^{targetRoom.Name} with you as the owner.";
				roomNameField.Text = string.Empty;
			}
			else
			{
				UnityEngine.Debug.LogError("targetRoom is null");
			}
			return base.ShowDialog();
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			roomNameField.IsValidFunction = delegate(string name)
			{
				roomName = name.Trim();
				return NameFieldIsValid();
			};
		}

		private bool NameFieldIsValid()
		{
			if (roomName.Length <= 2)
			{
				infoText.text = "^name too short!";
			}
			else
			{
				if (roomName.IsAlphaNumeric())
				{
					if (resetInfoText)
					{
						resetInfoText = false;
						infoText.text = string.Empty;
					}
					return true;
				}
				infoText.text = "^name can only contain letters and numbers!";
			}
			resetInfoText = true;
			return false;
		}

		private void SetInfoText(string info, bool activeButtons)
		{
			if (!string.IsNullOrEmpty(info))
			{
				infoText.text = info;
			}
			roomNameField.Interactable = activeButtons;
			cancelButton.Interactable = activeButtons;
			saveButton.Interactable = activeButtons;
		}

		private void HandleCreateResponse(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to create room for copying: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					Respond(response.RoomDetails.Room, shouldCloseDialog: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					SetInfoText("You can't copy rooms!", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					SetInfoText("Error copy room. You do not have permission!", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DuplicateName:
					SetInfoText("Failed to copy room. There is already a room called ^" + roomName, activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.ReservedName:
					SetInfoText("Failed to copy room. \"" + roomName + "\" is a reserved ^name.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomHasNoDataBlob:
					SetInfoText("Failed to copy room. Room has no data to copy. Save the current room first.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateName:
					SetInfoText("Failed to copy room. \"" + roomName + "\" contains inappropriate words.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateDescription:
					SetInfoText("Failed to copy room. \"" + RecNet.Rooms.LocalRoomDetails.Room.Description + "\" contains inappropriate words.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.TooManyRooms:
					SetInfoText("Failed to copy room. You have hit the maximum number of allowed rooms :(", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PlayerHasRoomUnderModerationReview:
					SetInfoText("Failed to copy room. You have a room under moderation review. Contact conduct@againstgrav.com", activeButtons: true);
					break;
				default:
					SetInfoText("Error copying room. If this persists, please contact the developers at support@againstgrav.com.", activeButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to copy room: " + error);
				SetInfoText("Failed to copy room: " + error, activeButtons: true);
			}
		}

		[SkipRename]
		public void Button_Cancel()
		{
			Respond(null, shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_Copy()
		{
			if (NameFieldIsValid())
			{
				SetInfoText("Copying...", activeButtons: false);
				RecNet.Rooms.CloneRoom(targetRoom.RoomId, roomName, HandleCreateResponse);
			}
		}
	}
	public class UIReportRoomDialog : ConfirmUIDialog<RoomDetails>
	{
		[SerializeField]
