		private TextMeshProUGUI infoText;

		private RoomDetails roomDetails;

		private string reportDetails;

		private int reportMaxCharCount = 160;

		private WatchUI watchMenu;

		private bool waitingForConfirmation;

		private bool buttonsEnabled = true;

		public PlayerReporting.ReportCategory Category { get; private set; }

		public override IPromise<ConfirmDialogResponses> ShowDialog(RoomDetails roomDetails)
		{
			SetInfoText(string.Empty, enableButtons: true);
			this.roomDetails = roomDetails;
			roomName.text = "^" + roomDetails.Room.Name;
