		private void SetInfoText(string info, bool enableButtons)
		{
			buttonsEnabled = enableButtons;
			infoText.text = info;
			descriptionTextField.Interactable = enableButtons;
			RefreshReportButtonState();
		}

		public void Button_Report()
		{
			waitingForConfirmation = true;
			watchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Confirm report?", "You CANNOT undo this action. Players who send false reports or abuse the reporting system will be penalized.", "Yes", "No", (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses r)
			{
				waitingForConfirmation = false;
				if (r == ConfirmDialogResponses.Affirmative)
				{
