	public class UIRestoreRoomDialog : ConfirmUIDialog
	{
		[SerializeField]
		private Text infoText;

		[SerializeField]
		private Text statusHeaderText;

		[SerializeField]
		private Dropdown historyDropDown;

		[SerializeField]
		private Button3D cancelButton;

		[SerializeField]
		private Button3D restoreButton;

		private RoomPersistenceManager persistenceManager;

		private List<RecNet.Rooms.RoomDataHistoryDTO> history;

		public override IPromise<ConfirmDialogResponses> ShowDialog()
		{
			persistenceManager = NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance;
			RefreshUI(enableButtons: false, "Downloading save history...");
			RecNet.Rooms.GetRoomDataHistory(RecNet.Rooms.LocalRoomScene.RoomSceneId, delegate(string e, List<RecNet.Rooms.RoomDataHistoryDTO> response)
			{
				if (string.IsNullOrEmpty(e))
				{
					history = response;
					RefreshUI(enableButtons: true, "Retrieved save history from server (that's good)");
				}
				else
				{
					RefreshUI(enableButtons: false, "Could not retrieve save history from server :-(");
				}
			});
			return base.ShowDialog();
		}

		private void RefreshUI(bool enableButtons, string statusMessage)
		{
			DateTime dateTime = RecNet.Rooms.LocalRoomScene.DataModifiedAt.ToLocalTime();
			string text = $"This room was last saved at {dateTime.ToShortTimeString()} on {dateTime.ToShortDateString()}\n\n";
			text += "Careful! Restoring will discard all unsaved changes...";
			infoText.text = text;
			historyDropDown.interactable = enableButtons;
			restoreButton.Interactable = enableButtons;
			int num = 1;
			historyDropDown.ClearOptions();
			List<Dropdown.OptionData> list = new List<Dropdown.OptionData>();
			list.Add(new Dropdown.OptionData($"{num}: {DateToHistoryString(RecNet.Rooms.LocalRoomScene.DataModifiedAt)} [Latest]"));
			num++;
			DateTime? lastAutosaveTime = NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.GetLastAutosaveTime();
			if (lastAutosaveTime.HasValue && DateTime.Compare(lastAutosaveTime.Value, RecNet.Rooms.LocalRoomScene.DataModifiedAt) > 0)
			{
				list.Add(new Dropdown.OptionData($"{num}: {DateToHistoryString(lastAutosaveTime.Value)} [Backup]"));
				num++;
			}
			if (history != null)
			{
				foreach (RecNet.Rooms.RoomDataHistoryDTO item in history)
				{
					list.Add(new Dropdown.OptionData($"{num}: {DateToHistoryString(item.CreatedAt)}"));
					num++;
				}
			}
			historyDropDown.AddOptions(list);
			historyDropDown.RefreshShownValue();
			statusHeaderText.text = statusMessage;
		}

		private string DateToHistoryString(DateTime dateTime)
		{
			DateTime dateTime2 = dateTime.ToLocalTime();
			return $"{dateTime2.ToShortTimeString()} on {dateTime2.ToShortDateString()}";
		}

		[SkipRename]
		public void Button_Restore()
		{
			RefreshUI(enableButtons: false, "Restoring ... ");
			int value = historyDropDown.value;
			if (value > 0)
			{
				if (historyDropDown.options[value]?.text?.EndsWith("[Backup]") == true)
				{
					persistenceManager.TryReloadRoomAutosave();
					base.UIBase.PopFlow();
					return;
				}
				RecNet.Rooms.RoomDataHistoryDTO roomDataHistoryDTO = history[value - 1];
				RecNet.Rooms.RestoreToRoomDataHistory(roomDataHistoryDTO.RoomDataHistoryId, delegate(string e, RecNet.Rooms.CreateModifyRoomSceneResponse response)
				{
					if (string.IsNullOrEmpty(e) && response != null && response.Result == RecNet.Rooms.CreateModifyRoomStatus.Success)
					{
						persistenceManager.RequestReloadRoomData();
						base.UIBase.PopFlow();
					}
					else
					{
						RefreshUI(enableButtons: true, "Uh oh... could not restore this save file :-(");
					}
				});
			}
			else
			{
				persistenceManager.RequestReloadRoomData();
				base.UIBase.PopFlow();
			}
		}
	}
}
