public class GoToRoomConditionalButton : ConditionalButton<Button3D>
{
	private enum GoToBehavior
	{
		PublicInstance,
		PrivateInstance,
		AlwaysAsk,
		PublicInstanceChooseEntrySubroom
	}

	public enum GoToRoomButtonState
	{
		Disabled,
		Room_DNE,
		Join,
		Full
	}

	private const string REC_CENTER = "RecCenter";

	[Tooltip("If the room is instanced, this makes the button go to a private instance of it. Otherwise disables the button.")]
	[SerializeField]
	private GoToBehavior goToBehavior;

	private RecNet.Rooms.CanJoinStatus playerTypeJoinStatus;

	private List<string> searchTags;

	private GoToRoomButtonState? _forcedButtonState;

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private static Action m_OnButtonAction;

	private RecNet.Room _targetRoom;

	private Coroutine privatePublicSwitchRoomRoutine;

	public GoToRoomButtonState? ForcedButtonState
	{
		get
		{
			return _forcedButtonState;
		}
		set
		{
			GoToRoomButtonState? forcedButtonState = _forcedButtonState;
			if (forcedButtonState.GetValueOrDefault() != value.GetValueOrDefault() || (forcedButtonState.HasValue ^ value.HasValue))
			{
				_forcedButtonState = value;
				UpdateButtonState();
			}
		}
	}

	public RecNet.Room TargetRoom => _targetRoom;

	public bool AttractHighlighted
	{
		get
		{
			return button.AttractHighlighted;
		}
		set
		{
			button.AttractHighlighted = value;
		}
	}

	public static event Action OnButtonAction
	{
		add
		{
			Action action = GoToRoomConditionalButton.m_OnButtonAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref GoToRoomConditionalButton.m_OnButtonAction, (Action)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action action = GoToRoomConditionalButton.m_OnButtonAction;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref GoToRoomConditionalButton.m_OnButtonAction, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public void SetTarget(RecNet.Room targetRoom, List<string> searchTagsUsed)
	{
		_targetRoom = targetRoom;
		searchTags = searchTagsUsed;
		UpdateButtonState();
	}

	protected override void UpdateButtonState()
	{
		if (SingletonMonoBehaviour<SessionManager>.Instance.LeaveSceneStarted)
		{
			base.ButtonState = 0;
		}
		else
		{
			UpdateButtonStateRoom();
		}
	}

	private void UpdateButtonStateRoom()
	{
		if (ForcedButtonState.HasValue)
		{
			base.ButtonState = (int)ForcedButtonState.Value;
			return;
		}
		if (TargetRoom == null)
		{
			base.ButtonState = 1;
			return;
		}
		if (TargetRoom.Name == "RecCenter" && goToBehavior == GoToBehavior.PrivateInstance)
		{
			base.ButtonState = 0;
			return;
		}
		if (!SingletonMonoBehaviour<SessionManager>.Instance.JuniorRoomCheck(TargetRoom.Name))
		{
			base.ButtonState = 0;
			return;
		}
		if (!TargetRoom.IsActive)
		{
			base.ButtonState = 0;
			return;
		}
		if (!TargetRoom.IsPublished && goToBehavior == GoToBehavior.PrivateInstance)
		{
			base.ButtonState = 0;
			return;
		}
		if (TargetRoom.RoomId == GameSessions.LocalGameSession.RoomId && !TargetRoom.IsPublished)
		{
			base.ButtonState = 0;
			return;
		}
		base.ButtonState = 2;
		long roomId = TargetRoom.RoomId;
		playerTypeJoinStatus = null;
		RecNet.Rooms.CheckLocalPlayerCanJoinRoom(TargetRoom).Then(delegate(RecNet.Rooms.CanJoinStatus canJoinStatus)
		{
			playerTypeJoinStatus = canJoinStatus;
		});
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		switch ((GoToRoomButtonState)base.ButtonState)
		{
		case GoToRoomButtonState.Full:
			UIHelper.SafeSetText(base.LabelText, "Game Full");
			return;
		case GoToRoomButtonState.Room_DNE:
			UIHelper.SafeSetText(base.LabelText, "No Game");
			return;
		}
		if (goToBehavior == GoToBehavior.PrivateInstance)
		{
			UIHelper.SafeSetText(base.LabelText, "Go to Private");
		}
		else
		{
			UIHelper.SafeSetText(base.LabelText, "Go To");
		}
	}

	protected override bool IsInteractable()
	{
		GoToRoomButtonState goToRoomButtonState = (GoToRoomButtonState)base.ButtonState;
		return base.IsInteractable() && goToRoomButtonState != GoToRoomButtonState.Full && goToRoomButtonState != GoToRoomButtonState.Room_DNE;
	}

	protected override void RunButtonAction()
	{
		if (playerTypeJoinStatus == null || playerTypeJoinStatus.CanJoinNow)
		{
			TryJoin();
		}
		else if (playerTypeJoinStatus.CanJoinWithPlayerTypeSwitch)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowSwitchPlayerTypeAndJoinDialog(playerTypeJoinStatus, TryJoin);
		}
		else
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowPlayerTypeNotAllowedDialog(playerTypeJoinStatus);
		}
	}

	private void TryJoin()
	{
		int num = base.ButtonState;
		base.ButtonState = 0;
		if (goToBehavior == GoToBehavior.AlwaysAsk && TargetRoom != null && TargetRoom.IsPublished && TargetRoom.Name != "RecCenter")
		{
			if (privatePublicSwitchRoomRoutine == null)
			{
				privatePublicSwitchRoomRoutine = SingletonMonoBehaviour<SessionManager>.Instance.StartCoroutine(RunPrivatePublicSwitchRoom());
				base.ButtonState = num;
			}
			return;
		}
		List<string> capturedSearchTags = searchTags;
		RecNet.Rooms.GetRoomDetails(TargetRoom.RoomId).Then(delegate(RoomDetails roomDetails)
		{
			if (roomDetails != null)
			{
				bool flag = roomDetails.Scenes.Count > 1 && roomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner;
				bool flag2 = roomDetails.Scenes.Count((RoomScene s) => s.CanMatchmakeInto) > 1 && (goToBehavior == GoToBehavior.PrivateInstance || goToBehavior == GoToBehavior.PublicInstanceChooseEntrySubroom);
				if (flag || flag2)
				{
					Player.LocalPlayer.PlayerUI.WatchMenu.ShowChooseSubroomDialog(roomDetails, goToBehavior == GoToBehavior.PrivateInstance, capturedSearchTags).Then(delegate(ConfirmDialogResponses response)
					{
						if (response == ConfirmDialogResponses.Affirmative)
						{
							GoToRoomConditionalButton.OnButtonAction.SafeInvoke();
						}
						else
						{
							SingletonMonoBehaviour<LocalPlayerController>.Instance.TryRevertVRMovementMode();
						}
					});
				}
				else
				{
					SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(TargetRoom.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, goToBehavior == GoToBehavior.PrivateInstance, capturedSearchTags);
					GoToRoomConditionalButton.OnButtonAction.SafeInvoke();
				}
			}
			else
			{
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(TargetRoom.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, goToBehavior == GoToBehavior.PrivateInstance, capturedSearchTags);
				GoToRoomConditionalButton.OnButtonAction.SafeInvoke();
			}
		});
	}

	private IEnumerator RunPrivatePublicSwitchRoom()
	{
		if (!Player.LocalPlayerExists)
		{
			yield break;
		}
		List<string> capturedSearchTags = searchTags;
		yield return Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO_CANCEL, "Go to ^" + TargetRoom.Name, "Do you want to join a public version or create a new private version of this room?", "Private", "Public").Then(delegate(ConfirmDialogResponses r)
		{
			switch (r)
			{
			case ConfirmDialogResponses.Affirmative:
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(TargetRoom.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, isPrivate: true, capturedSearchTags);
				break;
			case ConfirmDialogResponses.Negative:
				SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(TargetRoom.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, isPrivate: false, capturedSearchTags);
				break;
			}
		});
		privatePublicSwitchRoomRoutine = null;
	}
}
namespace RecRoom
{
	public class ReviveButton : ConditionalButton<Button3D>
	{
		private enum ReviveButtonState
		{
			Disabled,
			Enabled_Inactive,
			Enabled_Active
		}

		private void Awake()
		{
			GameCombatManager.LocalPlayerChangedToAliveEvent += PlayerAliveStateChanged;
			GameCombatManager.LocalPlayerChangedToDeadEvent += PlayerAliveStateChanged;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += GameStateChanged;
			}
		}

		private void OnDestroy()
		{
			GameCombatManager.LocalPlayerChangedToAliveEvent -= PlayerAliveStateChanged;
			GameCombatManager.LocalPlayerChangedToDeadEvent -= PlayerAliveStateChanged;
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent -= GameStateChanged;
			}
		}

		private void GameStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			if (currentStateId != previousStateId)
			{
				UpdateButton();
			}
		}

		private void PlayerAliveStateChanged()
		{
			UpdateButton();
		}

		protected override void RunButtonAction()
		{
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.RequestLocalHostRevive();
			}
		}

		protected override void UpdateButtonState()
		{
			bool flag = GameManager.IsSandboxActive && NetworkedSingletonMonoBehaviour<RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>>.IsInitialized && PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanSelfRevive.Value;
			bool flag2 = NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning && !NetworkedSingletonMonoBehaviour<GameManager>.Instance.CombatManager.PlayerIsAlive(PhotonNetwork.player);
			if (flag && flag2)
			{
				base.ButtonState = 2;
			}
			else if (flag && !flag2)
			{
				base.ButtonState = 1;
			}
			else
			{
				base.ButtonState = 0;
			}
		}

		protected override void UpdateUIForNewButtonState()
		{
			base.UpdateUIForNewButtonState();
			ReviveButtonState reviveButtonState = (ReviveButtonState)base.ButtonState;
			bool flag = reviveButtonState == ReviveButtonState.Enabled_Active || reviveButtonState == ReviveButtonState.Enabled_Inactive;
			if (flag != base.gameObject.activeSelf)
			{
				base.gameObject.SetActive(flag);
			}
		}

		protected override bool IsInteractable()
		{
			return base.IsInteractable() && base.ButtonState == 2;
		}
	}
}
