public class RoomImage : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private RawImage roomImage;

	[SerializeField]
	[AutofillOptional(AutofillType.Self, false)]
	private RoomSpecificUIBehaviour roomWatcher;

	private RecNet.Room room;

	private void Awake()
	{
		Material material = roomImage.material;
		Material material2 = UnityEngine.Object.Instantiate(material);
		roomImage.material = material2;
		roomImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
		if (roomWatcher != null)
		{
			roomWatcher.RoomDetailsUpdated += new Action<RoomDetails>(OnRoomDetailsUpdated);
			room = ((roomWatcher.RoomDetails == null) ? null : roomWatcher.RoomDetails.Room);
		}
		UpdateRoomImage();
	}

	private void OnDestroy()
	{
		if (roomWatcher != null)
		{
			roomWatcher.RoomDetailsUpdated -= new Action<RoomDetails>(OnRoomDetailsUpdated);
		}
	}

	private void OnRoomDetailsUpdated(RoomDetails roomDetails)
	{
		room = roomDetails?.Room;
		UpdateRoomImage();
	}

	public void SetRoom(RecNet.Room room)
	{
		this.room = room;
		UpdateRoomImage();
	}

	private void UpdateRoomImage()
	{
		roomImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
		if (room == null)
		{
			return;
		}
		Images.GetRoomImage(room).Then(delegate(Texture2D texture)
		{
			if (this != null && texture != null && room != null && room.ImageName == texture.name)
			{
				roomImage.texture = texture;
			}
		});
	}
}
namespace AGUI.StackedUI
{
	public class RoomRoleVisibilityObject : VisibilityRestriction
	{
		[SerializeField]
		[Autofill(AutofillType.SelfAndParent, false)]
		private RoomSpecificUIBehaviour roomWatcher;

		[SerializeField]
		private bool guestVisible;

		[SerializeField]
		private bool hostVisible;

		[SerializeField]
		private bool ownerVisible;

		[SerializeField]
		private bool creatorVisibile;

		private RoomDetails room;

		private void OnDestroy()
		{
			roomWatcher.RoomDetailsUpdated -= new Action<RoomDetails>(OnRoomUpdated);
		}

		protected override void OnInitialize()
		{
			base.OnInitialize();
			roomWatcher.RoomDetailsUpdated += new Action<RoomDetails>(OnRoomUpdated);
		}

		private void OnRoomUpdated(RoomDetails room)
		{
			this.room = room;
			RefreshVisibility();
		}

		protected override void RefreshVisibility()
		{
			bool active = false;
			if (room == null)
			{
				if (RecNet.Rooms.LocalRoomDetails.LocalPlayerRole == RecNet.RoomRole.Creator)
				{
					active = creatorVisibile;
				}
			}
			else
			{
				switch (room.LocalPlayerRole)
				{
				case RecNet.RoomRole.Creator:
					active = creatorVisibile;
					break;
				case RecNet.RoomRole.CoOwner:
					active = ownerVisible;
					break;
				case RecNet.RoomRole.Host:
					active = hostVisible;
					break;
				case RecNet.RoomRole.Guest:
					active = guestVisible;
					break;
				}
			}
			base.gameObject.SetActive(active);
		}
	}
}
public class ThisRoomWatchUIFlow : WatchUIFlow
{
	[SerializeField]
	[Autofill(AutofillType.SelfAndChildren, false)]
	private SubscreenControl subscreenControl;

	[Header("Scoreboard")]
	[SerializeField]
	private Subscreen scoreboardSubscreen;

	[SerializeField]
	private RectTransform emptyScoreboardDisplayRoot;

	[SerializeField]
	private GameObject gameScoreboardRoot;

	[Header("Details")]
	[SerializeField]
	private Subscreen detailsSubscreen;

	[Autofill(AutofillType.Children, false)]
	public UIRoomDetails RoomDetails;

	[Header("Setup")]
	[SerializeField]
	private Button3D publishRoomButton;

	[SerializeField]
	private Button3D generalSetupButton;

	[SerializeField]
	private Button3D subroomsButton;

	[SerializeField]
	private Button3D gameSetupButton;

	[SerializeField]
	private PublishRoomDialog publishRoomDialog;

	[Header("Room Specific Subscreen")]
	[SerializeField]
	private Subscreen roomSpecificSubscreen;

	[SerializeField]
	private RoomSpecificSubscreenUI recRoyalUIPrefab;

	private GameManager gameManager;

	private RoomSpecificSubscreenUI roomSpecificSubscreenUI;

	private string roomLimitLabel;

	private long targetRoomId;

	private List<string> searchTagsUsed;

	private ScreenHeader screenHeader;

	public static bool CanShowRoomSpecificSubscreen => SessionManager.InRecRoyale && !GameSessions.LocalGameSession.IsSandbox;

	public override void Initialize(StackedUIBase uiBase)
	{
		InitializeRoomSpecificSubscreenUI();
		base.Initialize(uiBase);
		GameUIView componentInChildren = GetComponentInChildren<GameScoreboardView>(includeInactive: true);
		if (RecRoomSceneManager.Instance != null)
		{
			gameManager = NetworkedSingletonMonoBehaviour<GameManager>.Instance;
			if (gameManager != null)
			{
				gameManager.UIManager.AddGameUIView(componentInChildren);
			}
		}
		componentInChildren.gameObject.SetTagRecursively("Untagged");
		screenHeader = GetComponentInChildren<ScreenHeader>();
	}

	private void InitializeRoomSpecificSubscreenUI()
	{
		roomSpecificSubscreen.Button.gameObject.SetActive(CanShowRoomSpecificSubscreen);
		if (CanShowRoomSpecificSubscreen)
		{
			Transform transform = UnityEngine.Object.Instantiate(recRoyalUIPrefab).transform;
			transform.SetParent(roomSpecificSubscreen.transform, worldPositionStays: false);
			transform.localPosition = Vector3.zero;
			transform.localRotation = Quaternion.identity;
			transform.localScale = Vector3.one;
			roomSpecificSubscreenUI = transform.GetComponentInChildren<RoomSpecificSubscreenUI>();
			roomSpecificSubscreenUI.Initialize(this);
			subscreenControl.SetDefaultSubscreen(roomSpecificSubscreen);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (oldFlow.GetType() == typeof(HomeScreenFlow) || targetRoomId == 0)
		{
			targetRoomId = GameSessions.LocalGameSession.RoomId;
			searchTagsUsed = null;
		}
		scoreboardSubscreen.Button.gameObject.SetActive(targetRoomId == GameSessions.LocalGameSession.RoomId);
		if (gameManager != null)
		{
			gameManager.StateChangeEvent += OnGameManagerStateChanged;
		}
		if (CanShowRoomSpecificSubscreen && roomSpecificSubscreenUI != null)
		{
			roomSpecificSubscreenUI.OnFlowEntered(oldFlow);
		}
		RecNet.Rooms.OnRoomDetailsUpdated += OnRoomDetailsUpdated;
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent += new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
		if (screenHeader != null)
		{
			screenHeader.Title = "This Room";
		}
		UpdateAllTabs();
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		if (gameManager != null)
		{
			gameManager.StateChangeEvent -= OnGameManagerStateChanged;
		}
		RecNet.Rooms.OnRoomDetailsUpdated -= OnRoomDetailsUpdated;
		RoleManagerBase<RoomRoleId, RecRoom.Systems.PlayerRoles.RoomRole.RolePermission, RecRoom.Systems.PlayerRoles.RoomRole, PlayerRoomRoleData, RoomRoleCollectionData>.OnPlayerRoleDefinitionUpdatedEvent -= new Action<PhotonPlayer, RecRoom.Systems.PlayerRoles.RoomRole>(OnPlayerRoleDefinitionUpdated);
	}

	public void ShowRoomDetails(long roomId, List<string> searchTagsUsed = null)
	{
		targetRoomId = roomId;
		this.searchTagsUsed = searchTagsUsed;
		subscreenControl.ShowSubscreen(detailsSubscreen);
		base.WatchUI.PushFlow(this);
	}

	private void OnGameManagerStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
	{
		UpdateAllTabs();
	}

	private void OnLocalPlayerIsHostChanged(bool arg2)
	{
		UpdateAllTabs();
	}

	private void OnRoomDetailsUpdated(long id)
	{
		UpdateAllTabs();
	}

	private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RecRoom.Systems.PlayerRoles.RoomRole newRoomRoleDef)
	{
		if (player.IsLocal)
		{
			UpdateAllTabs();
		}
	}

	public void ShowRoomSpecificSubscreen()
	{
		targetRoomId = GameSessions.LocalGameSession.RoomId;
		searchTagsUsed = null;
		subscreenControl.ShowSubscreen(roomSpecificSubscreen);
	}

	public void UpdateTargetRoomId(long id)
	{
		targetRoomId = id;
		searchTagsUsed = null;
		UpdateAllTabs();
	}

	private void UpdateAllTabs()
	{
		RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(targetRoomId);
		if (cachedRoomDetails == null)
		{
			RecNet.Rooms.GetRoomDetails(targetRoomId).Then(delegate(RoomDetails newRoomDetails)
			{
				screenHeader.Title = string.Format("^{0}{1}", newRoomDetails.Room.Name, (!newRoomDetails.Room.IsPublished) ? " [PRIVATE]" : string.Empty);
				UpdateSetupTab(newRoomDetails);
			});
		}
		else
		{
			screenHeader.Title = string.Format("^{0}{1}", cachedRoomDetails.Room.Name, (!cachedRoomDetails.Room.IsPublished) ? " [PRIVATE]" : string.Empty);
			UpdateSetupTab(cachedRoomDetails);
		}
		UpdateScoreboardTab();
		UpdateDetailsTab();
	}

	private void UpdateScoreboardTab()
	{
		bool flag = NetworkedSingletonMonoBehaviour<GameManager>.Instance != null && NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentState != GameStates.DISABLED;
		gameScoreboardRoot.SetActive(flag);
		emptyScoreboardDisplayRoot.gameObject.SetActive(!flag);
	}

	private void UpdateSetupTab(RoomDetails roomDetails)
	{
		bool flag = roomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner;
		bool flag2 = roomDetails.Room.RoomId == RecNet.Rooms.LocalRoomDetails.Room.RoomId;
		publishRoomButton.Interactable = flag;
		publishRoomButton.Label.text = ((!roomDetails.Room.IsPublished) ? "Publish Room" : "Unpublish Room");
		generalSetupButton.Interactable = flag;
		subroomsButton.Interactable = flag && roomDetails.Scenes.Count > 1;
		gameSetupButton.Interactable = flag2 && NetworkedSingletonMonoBehaviour<GameManager>.Instance != null;
	}

	private void UnpublishRoom()
	{
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Unpublishing...", 10f);
		publishRoomButton.Interactable = false;
		RecNet.Rooms.ModifyRoomPublishState(targetRoomId, newIsPublished: false, delegate(string error, RecNet.Rooms.CreateModifyRoomResponse serverResponse)
		{
			publishRoomButton.Interactable = true;
			if (string.IsNullOrEmpty(error) && serverResponse.Result == RecNet.Rooms.CreateModifyRoomStatus.Success)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Room unpublished", 3f);
				publishRoomButton.Label.text = "Publish Room";
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Error unpublishing room", 3f);
				UnityEngine.Debug.LogErrorFormat("Error: {0}, Result: {1}", error, serverResponse.Result);
			}
		});
	}

	private void UpdateDetailsTab()
	{
		RoomDetails.TargetRoomId = targetRoomId;
		RoomDetails.SearchTagsUsed = searchTagsUsed;
	}

	[SkipRename]
	public void Button_GameSetup()
	{
		base.WatchUI.PushFlow<GameSetupScreen>();
	}

	[SkipRename]
	public void Button_RoomSetup()
	{
		RoomSettingsScreen flowByType = base.WatchUI.GetFlowByType<RoomSettingsScreen>();
		RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(targetRoomId);
		if (flowByType != null && cachedRoomDetails != null)
		{
			flowByType.ShowScreen(cachedRoomDetails);
		}
	}

	[SkipRename]
	public void Button_Publish()
	{
		RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(targetRoomId);
		if (cachedRoomDetails.Room.IsPublished)
		{
			base.WatchUI.ShowConfirmationDialog("Confirm unpublish?", "Are you sure you want to unpublish this room? It will no longer be viewable in the Play Screen, or searchable by other players.").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					UnpublishRoom();
				}
			});
			return;
		}
		base.WatchUI.ShowTemporaryDialog(publishRoomDialog, cachedRoomDetails, (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses response)
		{
			if (response == ConfirmDialogResponses.Affirmative)
			{
				publishRoomButton.Label.text = "Unpublish Room";
			}
		});
	}

	[SkipRename]
	public void Button_Subrooms()
	{
		RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(targetRoomId);
		base.WatchUI.ShowChooseSubroomDialog(cachedRoomDetails, GameSessions.LocalGameSession.Private, searchTagsUsed);
	}
}
