		[SerializeField]
		private Button3D saveButton;

		[SerializeField]
		private Button3D cloneButton;

		[SerializeField]
		private Button3D restoreButton;

		[SerializeField]
		private float minSaveRestoreInterval = 5f;

		[Header("General")]
		[SerializeField]
		private Button3D roomImageButton;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private RoomSpecificUIBehaviour roomWatcher;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RoomSpecificUIBehaviour roomImageRoomWatcher;

		private GoToRoomConditionalButton[] goToRoomButtons;

		private WatchUI watchMenu;

		private PlayerDetailsWatchUIFlow playerDetailsFlow;

		private Profile creatorProfile;

		private RoomOwnersScreen roomOwnersScreen;

		private RoomDetails targetRoomDetails;

		private PersonalRoomDetails targetRoomPersonalDetails;

		private bool targetIsLocal;

		private RoomPersistenceManager persistenceManager;

		private bool showNotification;

		private Coroutine queuedUpdateDetailsRoutine;

		private long? _targetRoomId;

		private float nextSavePressTime = float.MinValue;

		private float nextRestorePressTime = float.MinValue;

		public long? TargetRoomId
		{
			get
			{
				return _targetRoomId;
			}
			set
			{
				long valueOrDefault = value.GetValueOrDefault();
				long? targetRoomId = _targetRoomId;
				if (valueOrDefault == targetRoomId.GetValueOrDefault() && !(value.HasValue ^ targetRoomId.HasValue))
				{
					return;
				}
				_targetRoomId = value;
				targetRoomPersonalDetails = null;
				if (!_targetRoomId.HasValue)
				{
					return;
				}
				long idValue = _targetRoomId.Value;
				if (RecNet.Rooms.GetCachedRoomDetails(idValue) == null)
				{
					RecNet.Rooms.GetRoomDetails(idValue).Then((Action<RoomDetails>)delegate
					{
						if (this != null)
						{
							long? targetRoomId2 = _targetRoomId;
							if (targetRoomId2.GetValueOrDefault() == idValue && targetRoomId2.HasValue)
							{
								QueueUpdateDetails();
							}
						}
					});
					UpdateUIState("Loading room details...", enableButtons: false);
				}
				else
				{
					UpdateDetails();
				}
				RecNet.Rooms.GetPersonalRoomDetails(idValue).Then(delegate(PersonalRoomDetails details)
				{
					if (this != null)
					{
						long? targetRoomId2 = _targetRoomId;
						if (targetRoomId2.GetValueOrDefault() == idValue && targetRoomId2.HasValue)
						{
							targetRoomPersonalDetails = details;
							QueueUpdateDetails();
						}
					}
				});
			}
		}

		public Button3D SaveButton => saveButton;

		public List<string> SearchTagsUsed { get; set; }

		private void Awake()
		{
			persistenceManager = NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance;
			persistenceManager.RoomSaveSuccessEvent += OnRoomSaveSuccess;
			persistenceManager.RoomSaveFailureEvent += OnRoomSaveFailure;
			persistenceManager.RoomReloadSuccessEvent += OnRoomLoadSuccess;
			persistenceManager.RoomReloadFailureEvent += OnRoomLoadFailure;
			WatchUI.LocalPlayerAndWatchMenuSpawned += OnLocalPlayerAndWatchMenuSpawned;
			OnLocalPlayerAndWatchMenuSpawned();
			goToRoomButtons = GetComponentsInChildren<GoToRoomConditionalButton>(includeInactive: true);
		}

		private void OnEnable()
		{
			RecNet.Rooms.OnRoomDetailsUpdated += OnRoomDetailsUpdated;
			QueueUpdateDetails();
		}

		private void OnDisable()
		{
			RecNet.Rooms.OnRoomDetailsUpdated -= OnRoomDetailsUpdated;
		}

		private void OnDestroy()
		{
			if (persistenceManager != null)
			{
				persistenceManager.RoomSaveSuccessEvent -= OnRoomSaveSuccess;
				persistenceManager.RoomSaveFailureEvent -= OnRoomSaveFailure;
				persistenceManager.RoomReloadSuccessEvent -= OnRoomLoadSuccess;
				persistenceManager.RoomReloadFailureEvent -= OnRoomLoadFailure;
			}
			WatchUI.LocalPlayerAndWatchMenuSpawned -= OnLocalPlayerAndWatchMenuSpawned;
			Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
		}

		private void UpdateUIState(string statusText, bool enableButtons)
		{
			if (targetRoomDetails == null)
			{
				enableButtons = false;
			}
			infoText.text = statusText;
			bool flag = targetRoomDetails != null && targetRoomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner;
			favoriteToggle.Interactable = enableButtons && targetRoomPersonalDetails != null;
			cheerToggle.Interactable = enableButtons && !flag && targetIsLocal && targetRoomPersonalDetails != null;
			reportButton.Interactable = enableButtons && !flag && targetRoomDetails != null && ((targetRoomDetails == null) ? ((bool?)null) : targetRoomDetails.Room?.IsAGRoom) == false;
			creatorInfoButton.Interactable = enableButtons && targetRoomDetails != null && targetRoomDetails.LocalPlayerRole != RecNet.RoomRole.Creator;
			restoreButton.Interactable = enableButtons && flag && targetIsLocal && targetRoomDetails != null;
			saveButton.Interactable = enableButtons && targetIsLocal && flag;
			cloneButton.Interactable = enableButtons && targetRoomDetails != null && (targetRoomDetails.Room.CloningAllowed || flag);
			editRoomNameButton.Interactable = enableButtons && flag && targetRoomDetails != null;
			editRoomDescriptionButton.Interactable = enableButtons && flag && targetRoomDetails != null;
			editRoomTagsButton.Interactable = enableButtons && flag && targetRoomDetails != null;
			seeAllOwnersButton.Interactable = enableButtons && targetRoomDetails != null && targetRoomDetails.CoOwnerIds.Count > 0;
			if (goToRoomButtons != null)
			{
				GoToRoomConditionalButton[] array = goToRoomButtons;
				foreach (GoToRoomConditionalButton goToRoomConditionalButton in array)
				{
					goToRoomConditionalButton.ForcedButtonState = ((!enableButtons) ? new GoToRoomConditionalButton.GoToRoomButtonState?(GoToRoomConditionalButton.GoToRoomButtonState.Disabled) : ((GoToRoomConditionalButton.GoToRoomButtonState?)null));
				}
			}
			roomImageButton.Interactable = enableButtons && targetIsLocal && targetRoomDetails != null && targetRoomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner;
		}

		private void QueueUpdateDetails()
		{
			if (base.gameObject.activeInHierarchy)
			{
				this.SafeStopCoroutine(queuedUpdateDetailsRoutine);
				queuedUpdateDetailsRoutine = this.EndOfFrameRoutine(delegate
				{
					UpdateDetails();
					queuedUpdateDetailsRoutine = null;
				});
			}
		}

		private void UpdateDetails()
		{
			if (TargetRoomId.HasValue)
			{
				if (RecNet.Rooms.LocalRoomDetails != null && RecNet.Rooms.LocalRoomDetails.Room.RoomId == TargetRoomId.Value)
				{
					targetRoomDetails = RecNet.Rooms.LocalRoomDetails;
					targetIsLocal = true;
				}
				else
				{
					targetRoomDetails = RecNet.Rooms.GetCachedRoomDetails(TargetRoomId.Value);
					targetIsLocal = false;
				}
				if (goToRoomButtons != null)
				{
					GoToRoomConditionalButton[] array = goToRoomButtons;
					foreach (GoToRoomConditionalButton goToRoomConditionalButton in array)
					{
						goToRoomConditionalButton.SetTarget((targetRoomDetails == null) ? null : targetRoomDetails.Room, SearchTagsUsed);
					}
				}
			}
			else
			{
				targetRoomDetails = null;
			}
			if (targetRoomDetails != null)
			{
				UpdateDetailsRoom();
			}
			else
			{
				ClearDetails("Error: Room does not exist!");
			}
		}

		private void ClearDetails(string infoText)
		{
			roomWatcher.SetRoomId(null);
			roomImageRoomWatcher.SetRoomId(null);
			creatorProfile = null;
			roomName.text = "Loading...";
			roomDescription.text = "Loading...";
			roomTags.text = "Loading...";
			tagsTooltip.Message = string.Empty;
			creatorInfo.SetProfile(null);
			UpdatePlayerSpecificUI(null);
			cheerToggle.IsOn = false;
			cheerToggle.Label.text = "Cheer";
			cheersCountText.text = "Cheers:\nLoading...";
			favoriteToggle.IsOn = false;
			favoriteToggle.Label.text = "Favorite";
			favoriteCountText.text = "Favorites:\nLoading...";
			visitsCountText.text = "Visits: Loading...";
			otherOwnersContainer.SetActive(value: false);
			if (infoText != null)
			{
				UpdateUIState(infoText, enableButtons: false);
			}
		}

		private void UpdateDetailsRoom()
		{
			roomWatcher.SetRoomId(targetRoomDetails.Room.RoomId);
			roomImageRoomWatcher.SetRoomId(targetRoomDetails.Room.RoomId);
			roomName.text = "^" + targetRoomDetails.Room.Name;
			if (!string.IsNullOrEmpty(targetRoomDetails.Room.Description))
			{
				roomDescription.text = targetRoomDetails.Room.Description;
			}
			else
			{
				roomDescription.text = "No description yet";
			}
			if (targetRoomDetails.AllTags.Count > 0)
			{
				roomTags.text = string.Format("#{0}", string.Join(", #", targetRoomDetails.AllTags.ToArray()));
				tagsTooltip.Message = string.Format("#{0}", string.Join(", #", targetRoomDetails.AllTags.ToArray()));
			}
			else
			{
				roomTags.text = "No #tags yet";
				tagsTooltip.Message = "No #tags yet";
			}
			otherOwnersContainer.SetActive(targetRoomDetails != null && targetRoomDetails.CoOwnerIds.Count > 0);
			creatorProfile = Profiles.Get(targetRoomDetails.Room.CreatorPlayerId);
			if (creatorProfile == null)
			{
				Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
				creatorInfoButton.Interactable = false;
				UpdatePlayerSpecificUI(null);
			}
			else
			{
				UpdatePlayerSpecificUI(creatorProfile.Id);
			}
			creatorInfo.SetProfile(creatorProfile);
			cheerToggle.IsOn = targetRoomPersonalDetails != null && targetRoomPersonalDetails.IsCheering;
			cheerToggle.Label.text = ((!cheerToggle.IsOn) ? "Cheer" : "Uncheer");
			cheersCountText.text = "Cheers:\n" + targetRoomDetails.CheerCount;
			favoriteToggle.IsOn = targetRoomPersonalDetails != null && targetRoomPersonalDetails.IsBookmarked;
			favoriteToggle.Label.text = ((!favoriteToggle.IsOn) ? "Favorite" : "Unfavorite");
			favoriteCountText.text = "Favorites:\n" + targetRoomDetails.FavoriteCount;
			visitsCountText.text = "Visits: " + targetRoomDetails.VisitCount;
			if (!targetRoomDetails.Room.IsActive)
			{
				if (targetRoomDetails.Room.State == RoomState.Moderation_PendingReview)
				{
					UpdateUIState("Room is under review. Contact us at conduct@againstgrav.com", enableButtons: true);
				}
				else
				{
					UpdateUIState("Room is not active. Contact us at support@againstgrav.com", enableButtons: true);
				}
			}
			else
			{
				UpdateUIState(string.Empty, enableButtons: true);
			}
		}

