		private void HandleModifyResponse(string action, string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogError("Error updating room: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					UpdateUIState("Successfully " + action + "!", enableButtons: true);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Successfully updated!", 3f);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					UpdateUIState("You can't modify rooms!", enableButtons: false);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					UpdateUIState("Failed to " + action + ". Please try again.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomNotActive:
					UpdateUIState("Failed to " + action + ". This room is no longer active.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DuplicateName:
					UpdateUIState(string.Concat("Failed to ", action, ". \"", roomName, "\" is already in use."), enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.ReservedName:
					UpdateUIState(string.Concat("Failed to ", action, ". \"", roomName, "\" is a reserved ^name."), enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateName:
					UpdateUIState(string.Concat("Failed to ", action, ". \"", roomName, "\" contains inappropriate words."), enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateDescription:
					UpdateUIState(string.Concat("Failed to ", action, ". \"", roomDescription, "\" contains inappropriate words."), enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.TooManyRooms:
					UpdateUIState("Failed to " + action + ". You have hit the maximum number of allowed rooms :(", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomUnderModerationReview:
					UpdateUIState("Failed to " + action + ". Please contact us at conduct@againstgrav.com", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.AccessibilityUnderModerationLock:
					UpdateUIState("Failed to " + action + ". Privacy settings are locked.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomDoesNotExist:
					UpdateUIState("Failed to " + action + ". This room does not exist.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DataHistoryDoesNotExist:
					UpdateUIState("Failed to " + action + ". Save history does not exist!", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DataHistoryAlreadyActive:
					UpdateUIState("Failed to " + action + ". Save history already restored. Try reloading!", enableButtons: true);
					break;
				default:
					UpdateUIState("Failed to " + action + ". If this persists, please contact the developers at support@againstgrav.com.", enableButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to " + action + ": " + error);
				UpdateUIState("Failed to " + action + ": " + error, enableButtons: true);
			}
			QueueUpdateDetails();
		}

		private void OnRoomSaveSuccess()
		{
			if (RecNet.Rooms.LocalRoomDetails != null && !TargetRoomId.HasValue)
			{
				TargetRoomId = RecNet.Rooms.LocalRoomDetails.Room.RoomId;
			}
			if (showNotification)
			{
				showNotification = false;
				UpdateUIState("Room saved!", enableButtons: true);
