namespace AGUI.StackedUI.Dialog
{
	public class UITakeRoomPictureDialog : TakePictureDialog<RecNet.Room>
	{
		private RecNet.Room targetRoom;

		public override IPromise<TakePictureDialogResponse> ShowDialog(RecNet.Room room)
		{
			targetRoom = room;
			return ShowDialog();
		}

		protected override void ProcessPicture()
		{
			Images.UploadSavedImage(photoSet, Images.SavedImageType.RoomThumbnail).Error(delegate(string uploadError)
			{
				UnityEngine.Debug.LogError("Failed to upload room image: " + uploadError);
				UpdateUI(uploadError, enableButtons: true);
			}).Then(delegate(string imageName)
			{
				UpdateUI("Setting as room image...", enableButtons: false);
				RecNet.Rooms.ModifyRoomImageName(targetRoom.RoomId, imageName, HandleModifyResponse);
			});
		}

		private void HandleModifyResponse(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to create room: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					Respond(new TakePictureDialogResponse(ConfirmDialogResponses.Affirmative, photoSet), shouldCloseDialog: true);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Room picture updated!", 3f);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					UpdateUI("Juniors can't modify rooms!", enableButtons: false);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					UpdateUI("Error creating room. Permission was denied.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PlayerHasRoomUnderModerationReview:
					UpdateUI("Failed to update image. You have a room under moderation review. Email conduct@againstgrav.com", enableButtons: true);
					break;
				default:
					UpdateUI("Error updating room image. If this persists, please contact us at support@againstgrav.com", enableButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to update room image: " + error);
				UpdateUI("Failed to update room image: " + error, enableButtons: true);
			}
		}
	}
}
public abstract class PrefabSpawner<T> : Spawner where T : UnityEngine.Component
{
	[SerializeField]
	private T prefab;

	protected T instance;

	protected override bool TrySpawnChildren()
	{
		if (prefab == null)
		{
			UnityEngine.Debug.LogWarning("PrefabSpawner.TrySpawn(): Prefab is null.");
			return false;
		}
		instance = UnityEngine.Object.Instantiate(prefab, base.transform, worldPositionStays: false);
		instance.transform.localPosition = Vector3.zero;
		instance.transform.localRotation = Quaternion.identity;
		instance.transform.localScale = Vector3.one;
		instance.gameObject.hideFlags = HideFlags.NotEditable;
		return true;
	}

	protected override void InitializeChildren()
	{
		if (UnityEngine.Application.isPlaying)
		{
			VisibilityRestriction[] componentsInChildren = instance.GetComponentsInChildren<VisibilityRestriction>(includeInactive: true);
			VisibilityRestriction[] array = componentsInChildren;
			foreach (VisibilityRestriction visibilityRestriction in array)
			{
				visibilityRestriction.Initialize();
			}
		}
	}
}
