	public UnityEvent PreBackButtonPressedEvent { get; internal set; }

	public UnityEvent PreHomeButtonPressedEvent { get; internal set; }

	public UnityEvent PreExpandButtonPressedEvent { get; internal set; }

	private StackedUIBase UIBase => (!(uiFlow != null)) ? null : uiFlow.UIBase;

	private WatchUI WatchUI => UIBase as WatchUI;

	private bool CanShowExpandButton => ShowExpandButton && !uiFlow.ForceSpecificSize && UIBase != null && UIBase.SupportsResizing;

	private void Start()
	{
		GatherReferences();
		if (UIBase != null)
		{
			UIBase.ResizeCompleteEvent += OnUIBaseResizeComplete;
		}
		LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
		instance.DisplayModeChange = (Action)Delegate.Combine(instance.DisplayModeChange, new Action(OnLocalPlayerControllerDisplayModeChange));
		postStart = true;
		Refresh();
	}

	private void OnDestroy()
	{
		if (UIBase != null)
		{
			UIBase.ResizeCompleteEvent -= OnUIBaseResizeComplete;
		}
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance != null)
		{
			LocalPlayerController instance = SingletonMonoBehaviour<LocalPlayerController>.Instance;
			instance.DisplayModeChange = (Action)Delegate.Remove(instance.DisplayModeChange, new Action(OnLocalPlayerControllerDisplayModeChange));
		}
	}

	private void OnUIBaseResizeComplete(SizeOption size)
	{
		Refresh();
	}

	private void OnLocalPlayerControllerDisplayModeChange()
	{
		Refresh();
	}

	public void Refresh()
	{
		if (PauseRefresh || (UnityEngine.Application.isPlaying && !postStart))
		{
			return;
		}
		GatherReferences();
		if ((bool)titleText)
		{
			titleText.text = Title;
		}
		else
		{
			UnityEngine.Debug.LogWarning("Missing TitleText reference on ScreenHeader", this);
		}
		backButton.gameObject.SetActive(ShowBackButton);
		homeButton.gameObject.SetActive(ShowHomeButton);
		reportBugButton.gameObject.SetActive(ShowReportBugButton);
		missingSomethingButton.gameObject.SetActive(value: false);
		if (UnityEngine.Application.isPlaying)
		{
			if (CanShowExpandButton)
			{
				expandButton.gameObject.SetActive(value: true);
				RefreshExpandImage();
			}
			else
			{
				expandButton.gameObject.SetActive(value: false);
			}
		}
		else
		{
			expandButton.gameObject.SetActive(ShowExpandButton);
		}
	}

	private void RefreshExpandImage()
	{
		if (UIBase.Size == SizeOption.NORMAL)
		{
			expandImage.sprite = expandMaximizeSprite;
		}
		else
		{
			expandImage.sprite = expandMinimizeSprite;
		}
	}

	private void GatherReferences()
	{
		if (uiFlow == null)
		{
			uiFlow = GetComponentInParent<StackedUIFlowBase>();
		}
	}

	[SkipRename]
	public void Button_Back()
	{
		if (PreBackButtonPressedEvent != null)
		{
			PreBackButtonPressedEvent.Invoke();
		}
		StackedUIFlowBase componentInParent = GetComponentInParent<StackedUIFlowBase>();
		if (componentInParent != null)
		{
			componentInParent.Button_ExitFlow();
		}
	}

	[SkipRename]
	public void Button_Home()
	{
		if (PreHomeButtonPressedEvent != null)
		{
			PreHomeButtonPressedEvent.Invoke();
		}
		if (UIBase != null)
		{
			UIBase.PopAllFlows();
		}
	}

	[SkipRename]
	public void Button_Expand()
	{
		if (PreExpandButtonPressedEvent != null)
		{
			PreExpandButtonPressedEvent.Invoke();
		}
		if (WatchUI != null)
		{
			WatchUI.ToggleSize();
			RefreshExpandImage();
		}
	}

	[SkipRename]
	public void Button_ReportBug()
	{
		BugReportingUIFlow flowByType = UIBase.GetFlowByType<BugReportingUIFlow>();
		UIBase.PushFlow(flowByType);
	}

	[SkipRename]
