[ExecuteInEditMode]
public abstract class Spawner : UnityEngine.MonoBehaviour
{
	private bool childrenSpawned;

	protected abstract bool TrySpawnChildren();

	protected abstract void InitializeChildren();

	protected virtual void Awake()
	{
		Spawn();
	}

	public void Spawn()
	{
		if (!childrenSpawned && TrySpawnChildren())
		{
			InitializeChildren();
			childrenSpawned = true;
		}
	}

	public void Clear()
	{
		if (base.transform.childCount > 0)
		{
			Transform[] array = new Transform[base.transform.childCount];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = base.transform.GetChild(i);
			}
			Transform[] array2 = array;
			foreach (Transform transform in array2)
			{
				if (UnityEngine.Application.isEditor)
				{
					UnityEngine.Object.DestroyImmediate(transform.gameObject, allowDestroyingAssets: true);
				}
				else
				{
					UnityEngine.Object.Destroy(transform.gameObject);
				}
			}
		}
		childrenSpawned = false;
	}
}
