		}
		UnityEngine.Object.Destroy(diagnosticsButton.gameObject);
		defaultMicSettingsTooltipText = voiceChatTooltip.Message;
		Profiles.OnProfileUpdated += OnProfileUpdated;
		RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomUpdated);
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
		{
			NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += OnGameManagerStateChangeEvent;
		}
