		walkingHandSlider.value = (float)SingletonMonoBehaviour<SettingsManager>.Instance.WalkingHandMode;
		UpdateWalkModeSlider();
		rotationIncrementSlider.value = (float)SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateMode;
		touchpadTeleportToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.TouchpadTeleportEnabled;
		showRoomCenterToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.ShowRoomCenter;
		thumbstickWalkingModeSlider.value = (float)SingletonMonoBehaviour<SettingsManager>.Instance.ThumbstickWalk;
		rotationIncrementSlider.Interactable = SingletonMonoBehaviour<SettingsManager>.Instance.SwipeRotateEnabled;
		comfortFlyToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.ComfortFly;
		comfortSmoothRotateToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.ComfortSmoothRotate;
		comfortSwipeRotateToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.ComfortSwipeRotate;
