		psOnlyMatchingToggle.IsOn = SingletonMonoBehaviour<SettingsManager>.Instance.PSOnlyMatching;
		bool flag = Login.IsLoginCached() && Profiles.LocalProfile.Verified;
		rememberMeToggleContainer.SetActive(flag);
		rememberMeToggle.IsOn = flag;
		PlatformActivateObject[] componentsInChildren = advancedPagedGrid.GetComponentsInChildren<PlatformActivateObject>(includeInactive: true);
		PlatformActivateObject[] array = componentsInChildren;
		foreach (PlatformActivateObject platformActivateObject in array)
		{
			if (!platformActivateObject.ShouldBeActive)
			{
				advancedPagedGrid.AddIgnoredChild(platformActivateObject.transform);
			}
		}
		advancedPagedGrid.UpdateGrid();
		devDisplaySlider.value = (int)SingletonMonoBehaviour<SettingsManager>.Instance.DeveloperDisplayMode;
		devDisplayGroup.gameObject.SetActive(Profiles.LocalProfile != null && (bool)Profiles.LocalProfile.Developer);
