		personalSpaceSlider.value = (float)SingletonMonoBehaviour<SettingsManager>.Instance.PersonalSpace;
		preferNonJuniorsToggle.IsOn = Profiles.LocalProfile != null && (bool)Profiles.LocalProfile.AvoidJuniors;
		muteToggleContainer.gameObject.SetActive(SingletonMonoBehaviour<SettingsManager>.Instance.VoiceChat == VoiceChat.AlwaysOn);
		touchpadTeleportEnabledSetting.SetActive(SingletonMonoBehaviour<PlatformManager>.Instance.CurrentHardwareType == PlatformManager.HardwareType.VIVE);
