	private void OnPlayerRoleDefinitionUpdated(PhotonPlayer player, RecRoom.Systems.PlayerRoles.RoomRole roleDef)
	{
		bool value = roleDef.CanTalk.Value;
		voiceChatSlider.Interactable = value;
		voiceChatTooltip.Message = ((!value) ? "The event host has silenced all players" : defaultMicSettingsTooltipText);
		if (value)
		{
			voiceChatSlider.value = (float)Player.LocalPlayer.SavedVoiceChatSettings;
		}
		else
		{
			voiceChatSlider.value = 0f;
		}
	}

