	private IEnumerator RunRemoveCachedLogin()
	{
		yield return Login.RemoveCachedLogin(delegate(string e)
		{
			if (string.IsNullOrEmpty(e))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "You'll be logged out after this session", 5f);
				rememberMeToggleContainer.SetActive(value: false);
			}
			else
			{
				UnityEngine.Debug.LogError(e);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Vital, "Uh oh! Something went wrong", 5f);
				rememberMeToggle.ForcePressed();
			}
		});
	}

