	private int GetSliderValueByAutosaveInterval(float value)
	{
		for (int i = 0; i < sliderToAutosaveIntervalMappings.Length; i++)
		{
			if (value <= sliderToAutosaveIntervalMappings[i])
			{
				return i;
			}
		}
		return sliderToAutosaveIntervalMappings.Length - 1;
	}

	[SkipRename]
	public void Slider_AutosaveFrequencyValueChange(float value)
	{
		int num = (int)value;
		if (num >= 0 && num < sliderToAutosaveIntervalMappings.Length)
		{
			SingletonMonoBehaviour<SettingsManager>.Instance.AutosaveInterval = sliderToAutosaveIntervalMappings[num];
		}
		else
		{
