public class VolumeDisplay : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private GameObject[] indicators;

	private float[] thresholds;

	private float[] indicatorEndOfLife;

	private float minVolume;

	[SerializeField]
	private float maxVolume = 3.1622f;

	private void Awake()
	{
		indicatorEndOfLife = new float[indicators.Length];
		thresholds = new float[indicators.Length];
		for (int i = 0; i < indicatorEndOfLife.Length; i++)
		{
			indicatorEndOfLife[i] = 0f;
			thresholds[i] = Mathf.Lerp(minVolume, maxVolume, ((float)i + 1f) / (float)indicators.Length);
		}
	}

	private void Update()
	{
		if (Player.LocalPlayer == null)
		{
			return;
		}
		float num = ((!Player.LocalPlayer.Mute) ? Player.LocalPlayer.AudioMaxForFrame : 0f);
		for (int num2 = indicators.Length - 1; num2 >= 0; num2--)
		{
			bool flag = num >= thresholds[num2];
			if (flag)
			{
				if (indicators[num2].activeSelf != flag)
				{
					indicators[num2].SetActive(value: true);
				}
				indicatorEndOfLife[num2] = UnityEngine.Time.realtimeSinceStartup + 0.1f;
			}
			else if (indicators[num2].activeSelf && UnityEngine.Time.realtimeSinceStartup > indicatorEndOfLife[num2])
			{
				indicators[num2].SetActive(value: false);
			}
		}
	}
}
