public class SubscreenControl : UnityEngine.MonoBehaviour
{
	public delegate void ActiveSubscreenChangedHandler();

	[CompilerGenerated]
	[DebuggerBrowsable(DebuggerBrowsableState.Never)]
	private ActiveSubscreenChangedHandler m_ActiveSubscreenChanged;

	private StackedUIFlowBase uiFlowBase;

	private Subscreen defaultSubscreen;

	private Subscreen[] allSubscreens = new Subscreen[0];

	public Subscreen ActiveSubscreen { get; private set; }

	public event ActiveSubscreenChangedHandler ActiveSubscreenChanged
	{
		add
		{
			ActiveSubscreenChangedHandler activeSubscreenChangedHandler = this.m_ActiveSubscreenChanged;
			ActiveSubscreenChangedHandler activeSubscreenChangedHandler2;
			do
			{
				activeSubscreenChangedHandler2 = activeSubscreenChangedHandler;
				activeSubscreenChangedHandler = Interlocked.CompareExchange(ref this.m_ActiveSubscreenChanged, (ActiveSubscreenChangedHandler)Delegate.Combine(activeSubscreenChangedHandler2, value), activeSubscreenChangedHandler);
			}
			while (activeSubscreenChangedHandler != activeSubscreenChangedHandler2);
		}
		remove
		{
			ActiveSubscreenChangedHandler activeSubscreenChangedHandler = this.m_ActiveSubscreenChanged;
			ActiveSubscreenChangedHandler activeSubscreenChangedHandler2;
			do
			{
				activeSubscreenChangedHandler2 = activeSubscreenChangedHandler;
				activeSubscreenChangedHandler = Interlocked.CompareExchange(ref this.m_ActiveSubscreenChanged, (ActiveSubscreenChangedHandler)Delegate.Remove(activeSubscreenChangedHandler2, value), activeSubscreenChangedHandler);
			}
			while (activeSubscreenChangedHandler != activeSubscreenChangedHandler2);
		}
	}

	private void Awake()
	{
		uiFlowBase = GetComponentInParent<StackedUIFlowBase>();
		allSubscreens = GetComponentsInChildren<Subscreen>(includeInactive: true);
		defaultSubscreen = allSubscreens[0];
		Subscreen[] array = allSubscreens;
		foreach (Subscreen subscreen in array)
		{
			if (subscreen.Default)
			{
				defaultSubscreen = subscreen;
			}
			subscreen.gameObject.SetActive(value: false);
		}
		uiFlowBase.FlowEntered += OnParentFlowEntered;
	}

	private void OnDestroy()
	{
		uiFlowBase.FlowEntered -= OnParentFlowEntered;
	}

	private void OnEnable()
	{
		if (ActiveSubscreen != null && ActiveSubscreen.UpdateButtonOnEnable)
		{
			ActiveSubscreen.Button.ForcePressed();
		}
	}

	private void OnParentFlowEntered()
	{
		if (ActiveSubscreen == null && defaultSubscreen != null && defaultSubscreen.Button != null)
		{
			Subscreen[] array = allSubscreens;
			foreach (Subscreen subscreen in array)
			{
				subscreen.gameObject.SetActive(value: false);
			}
			defaultSubscreen.Button.ForcePressed();
		}
	}

	public void ShowDefaultSubscreen()
	{
		if (defaultSubscreen != null)
		{
			ShowSubscreen(defaultSubscreen);
		}
	}

	public void ShowSubscreen(Subscreen subscreen)
	{
		if (subscreen != ActiveSubscreen)
		{
			if (ActiveSubscreen != null)
			{
				ActiveSubscreen.gameObject.SetActive(value: false);
			}
			ActiveSubscreen = subscreen;
			ActiveSubscreen.gameObject.SetActive(value: true);
			if (ActiveSubscreen.UpdateButtonOnEnable)
			{
				ActiveSubscreen.Button.ForcePressed();
			}
			if (this.ActiveSubscreenChanged != null)
			{
				this.ActiveSubscreenChanged();
			}
		}
	}

	public void SetDefaultSubscreen(Subscreen subscreen)
	{
		defaultSubscreen = subscreen;
	}
}
