	private Button3D failButton;

	[SerializeField]
	private Button3D passButton;

	[SerializeField]
	private Button3D retestButton;

	[SerializeField]
	private Button3D submitBugToJiraButton;

	[SerializeField]
	private Button3D viewJiraBugButton;

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		ReloadDataAndUpdateUi();
	}

	public void ReloadDataAndUpdateUi()
	{
		isLoading = true;
		TestCaseManagement.GetTestCase(TestCaseId).Then(delegate(TestCase tc)
		{
			testCase = tc;
		}).Error(delegate
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Failed loading the test case.", 3f);
		})
			.Finally(delegate
			{
				isLoading = false;
				UpdateUi();
			});
		UpdateUi();
	}

	public void UpdateUi()
	{
		if (textBackgrounds != null)
		{
			UnityEngine.UI.Image[] array = textBackgrounds;
			foreach (UnityEngine.UI.Image image in array)
			{
				image.color = ((testCase == null) ? TestCaseItem.ConvertToColor(TestCaseStatus.NotYetTested) : TestCaseItem.ConvertToColor(testCase.Status));
			}
		}
		if (!isLoading)
		{
			contentPanel.SetActive(value: true);
			loadingPanel.SetActive(value: false);
			titleText.text = $"{testCase.Title} ({StringExt.SplitPascalCaseIntoWords(testCase.Status.ToString())})";
			descriptionText.text = (string.IsNullOrEmpty(testCase.Description) ? "No description." : testCase.Description);
			assigneesText.text = TestCaseItem.GetAssigneesString(testCase);
			tagsText.text = $"Tags: {TestCaseManagement.TagsToString(testCase.Tags)}";
			EnableTestCaseButtons();
		}
		else
		{
			contentPanel.SetActive(value: false);
			loadingPanel.SetActive(value: true);
		}
	}

	private void EnableTestCaseButtons()
	{
		DateTime now = DateTime.Now;
		bool? flag = ((TestPass != null) ? new bool?(TestPass.IsClosed) : ((bool?)null));
		bool? flag2 = ((!flag.HasValue) ? ((bool?)null) : new bool?(!flag.Value));
		bool flag3 = flag2.HasValue && flag2.Value;
		bool flag4 = !string.IsNullOrWhiteSpace(testCase.JiraBugUrl);
		if (!flag3)
		{
			unclaimButton.gameObject.SetActive(value: false);
			claimButton.gameObject.SetActive(value: false);
			failButton.gameObject.SetActive(value: false);
			passButton.gameObject.SetActive(value: false);
			retestButton.gameObject.SetActive(value: false);
			submitBugToJiraButton.gameObject.SetActive(value: false);
			viewJiraBugButton.gameObject.SetActive(flag4);
			return;
		}
		bool flag5 = testCase.AssignedPlayerIds.Contains((int)Player.LocalPlayer.PlayerId);
		switch (testCase.Status)
		{
		case TestCaseStatus.NotYetTested:
			unclaimButton.gameObject.SetActive(flag5);
			claimButton.gameObject.SetActive(!flag5);
			failButton.gameObject.SetActive(value: false);
			passButton.gameObject.SetActive(value: false);
			retestButton.gameObject.SetActive(value: false);
			break;
		case TestCaseStatus.Claimed:
			unclaimButton.gameObject.SetActive(flag5);
			claimButton.gameObject.SetActive(!flag5);
			failButton.gameObject.SetActive(flag5);
			passButton.gameObject.SetActive(flag5);
			retestButton.gameObject.SetActive(value: false);
			break;
		case TestCaseStatus.Failed:
		case TestCaseStatus.Passed:
			unclaimButton.gameObject.SetActive(value: false);
			claimButton.gameObject.SetActive(value: false);
			failButton.gameObject.SetActive(value: false);
			passButton.gameObject.SetActive(value: false);
			retestButton.gameObject.SetActive(flag5);
			break;
		default:
			throw new NotImplementedException($"Unknown TestCaseStatus: {testCase.Status}");
		}
		submitBugToJiraButton.gameObject.SetActive(!flag4);
		viewJiraBugButton.gameObject.SetActive(flag4);
	}

	[SkipRename]
	public void Button_UnclaimTestCase()
	{
		isLoading = true;
		UpdateUi();
		TestCaseManagement.UnclaimTestCase(testCase.Id).Error(delegate
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Failed unclaiming the test case.", 3f);
		}).Finally(delegate
		{
			isLoading = false;
