public class TestCaseItem : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private UnityEngine.UI.Image background;

	[SerializeField]
	private Text nameText;

	[SerializeField]
	private Text assigneesText;

	private TestCase model;

	public TestCase Model
	{
		get
		{
			return model;
		}
		set
		{
			model = value;
			Refresh();
		}
	}

	public static Color ConvertToColor(TestCaseStatus testCaseStatus)
	{
		return testCaseStatus switch
		{
			TestCaseStatus.NotYetTested => new Color32(150, 150, 150, byte.MaxValue), 
			TestCaseStatus.Claimed => new Color32(0, 150, byte.MaxValue, byte.MaxValue), 
			TestCaseStatus.Failed => new Color32(193, 0, 13, byte.MaxValue), 
			TestCaseStatus.Passed => new Color32(0, 193, 22, byte.MaxValue), 
			_ => throw new NotImplementedException($"Unknown TestCaseStatus: {testCaseStatus}"), 
		};
	}

	public static string GetAssigneesString(TestCase testCase)
	{
		string arg = ((testCase.AssignedPlayerNames.Count <= 0) ? "none" : string.Join(", ", testCase.AssignedPlayerNames));
		string arg2 = ((testCase.NumAssignedPlayersNeeded <= 0) ? string.Empty : $" ({testCase.NumAssignedPlayersNeeded} needed)");
		return $"Assignees{arg2}: {arg}";
	}

	public void Refresh()
	{
		nameText.text = $"<size=40>{model.Title}</size>";
		assigneesText.text = GetAssigneesString(model);
		background.color = ConvertToColor(model.Status);
	}

	[SkipRename]
	public void Button_View()
	{
		TestPassWatchUIFlow componentInParent = GetComponentInParent<TestPassWatchUIFlow>();
		if (componentInParent != null)
		{
			componentInParent.ViewTestCaseDetails(model.Id);
		}
	}
