public class TestPassItem : UnityEngine.MonoBehaviour
{
	public static Color32 OpenTestPassColor = new Color32(0, 150, byte.MaxValue, byte.MaxValue);

	public static Color32 ClosedTestPassColor = new Color32(150, 150, 150, byte.MaxValue);

	[SerializeField]
	private Text nameText;

	[SerializeField]
	private UnityEngine.UI.Image background;

	private TestPass model;

	public TestPass Model
	{
		get
		{
			return model;
		}
		set
		{
			model = value;
			Refresh();
		}
	}

	public static string GetTestPassCompletionStatusRichText(TestPass testPass)
	{
		float num = ((testPass.TestCases.Count <= 0) ? 0f : (100f * ((float)testPass.TestCases.Count((TestCase tc) => tc.Status == TestCaseStatus.Passed) / (float)testPass.TestCases.Count)));
		float num2 = ((testPass.TestCases.Count <= 0) ? 0f : (100f * ((float)testPass.TestCases.Count((TestCase tc) => tc.Status == TestCaseStatus.Failed) / (float)testPass.TestCases.Count)));
		float num3 = ((testPass.TestCases.Count <= 0) ? 0f : (100f * ((float)testPass.TestCases.Count((TestCase tc) => tc.Status != TestCaseStatus.Passed && tc.Status != TestCaseStatus.Failed) / (float)testPass.TestCases.Count)));
		return $"<color=#00c116>{Math.Round(num, 2)}%</color>, <color=#c1000d>{Math.Round(num2, 2)}%</color>, <color=#666666>{Math.Round(num3, 2)}%</color>";
	}

	public void Refresh()
	{
		string text = TestCaseManagement.TagsToString(model.Tags);
		if (text.Length > 0)
		{
			text += ' ';
		}
		string testPassCompletionStatusRichText = GetTestPassCompletionStatusRichText(model);
		nameText.text = string.Format("<size=48>{0}{1}</size>\n{2} - {3}\n{4}", text, model.Name, model.StartDate.ToString("M/d/yy"), model.EndDate.ToString("M/d/yy"), testPassCompletionStatusRichText);
		DateTime now = DateTime.Now;
		bool? flag = ((model != null) ? new bool?(model.IsClosed) : ((bool?)null));
		bool? flag2 = ((!flag.HasValue) ? ((bool?)null) : new bool?(!flag.Value));
		bool flag3 = flag2.HasValue && flag2.Value;
		background.color = ((!flag3) ? ClosedTestPassColor : OpenTestPassColor);
	}

	[SkipRename]
	public void Button_ViewTestPass()
	{
		TestCaseManagementWatchUIFlow componentInParent = GetComponentInParent<TestCaseManagementWatchUIFlow>();
		if (componentInParent != null)
		{
			componentInParent.Button_ViewTestPass(model.Id);
		}
	}
