public class TestPassWatchUIFlow : WatchUIFlow
{
	public enum DisplayMode
	{
		MyUnfinished,
		NotYetTested,
		Claimed,
		Failed,
		Passed
	}

	public int TestPassId;

	private TestPass testPass;

	private DisplayMode currentDisplayMode;

	private List<string> tagFilters = new List<string>();

	[SerializeField]
	private TestCasePagedGrid testCasePagedGrid;

	[SerializeField]
	private Text noTestCasesPanel;

	[SerializeField]
	private RadioButton3D myUnfinishedButton;

	[SerializeField]
	private RadioButton3D notYetTestedButton;

	[SerializeField]
	private RadioButton3D claimedButton;

	[SerializeField]
	private RadioButton3D failedButton;

	[SerializeField]
	private RadioButton3D passedButton;

	[SerializeField]
	private ToggleButton3D[] filterToggles;

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (base.WatchUI.Size == SizeOption.NORMAL)
		{
			base.WatchUI.ToggleSize();
		}
		InitializeRadioButtons();
		ClearAllFilters();
		ReloadTestCasesAndUpdateUi();
	}

	private void InitializeRadioButtons()
	{
		switch (currentDisplayMode)
		{
		case DisplayMode.MyUnfinished:
			myUnfinishedButton.ForcePressed();
			break;
		case DisplayMode.NotYetTested:
			notYetTestedButton.ForcePressed();
			break;
		case DisplayMode.Claimed:
			claimedButton.ForcePressed();
			break;
		case DisplayMode.Failed:
			failedButton.ForcePressed();
			break;
		case DisplayMode.Passed:
			passedButton.ForcePressed();
			break;
		default:
			throw new NotImplementedException($"Unimplemented display mode: {currentDisplayMode}");
		}
	}

	private void UpdateUi()
	{
		if (base.IsCurrentFlow)
		{
			List<TestCase> testCases = ((testPass != null) ? testPass.TestCases : null) ?? new List<TestCase>();
			testCases = FilterTestCasesByDisplayMode(testCases, currentDisplayMode);
			testCases = FilterTestCases(testCases, tagFilters);
			testCasePagedGrid.SetTestCases(testCases);
		}
	}

	public void ReloadTestCasesAndUpdateUi()
	{
		testPass = null;
		noTestCasesPanel.text = "Loading...";
		UpdateUi();
		TestCaseManagement.GetTestPass(TestPassId).Then(delegate(TestPass tp)
		{
			testPass = tp;
			if (testPass != null)
			{
				ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
				if (componentInChildren != null)
				{
					componentInChildren.Title = GetFlowTitle(testPass);
				}
				testPass.TestCases = SortTestCases(testPass.TestCases);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Failed loading test cases.", 3f);
			}
		}).Error(delegate
		{
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Failed loading the test pass.", 3f);
		})
			.Finally(delegate
			{
				noTestCasesPanel.text = "No test cases";
				UpdateUi();
			});
	}

	public void ViewTestCaseDetails(string testCaseId)
	{
		TestCaseDetailsWatchUIFlow flowByType = base.WatchUI.GetFlowByType<TestCaseDetailsWatchUIFlow>();
		flowByType.TestPass = testPass;
		flowByType.TestCaseId = testCaseId;
		Player.LocalPlayer.PlayerUI.WatchMenu.PushFlow(flowByType);
	}

	[SkipRename]
	public void Button_MyUnfinishedDisplayMode()
	{
		currentDisplayMode = DisplayMode.MyUnfinished;
		UpdateUi();
	}

	[SkipRename]
	public void Button_NotYetTestedDisplayMode()
	{
		currentDisplayMode = DisplayMode.NotYetTested;
		UpdateUi();
	}

	[SkipRename]
	public void Button_ClaimedDisplayMode()
	{
		currentDisplayMode = DisplayMode.Claimed;
		UpdateUi();
	}

	[SkipRename]
	public void Button_FailedDisplayMode()
	{
		currentDisplayMode = DisplayMode.Failed;
		UpdateUi();
	}

	[SkipRename]
	public void Button_PassedDisplayMode()
	{
		currentDisplayMode = DisplayMode.Passed;
		UpdateUi();
	}

	[SkipRename]
	public void Button_ClearFilters()
	{
		ClearAllFilters();
		UpdateUi();
	}

	[SkipRename]
	public void Button_ToggleFilter(string filter)
	{
		ToggleTagFilter(filter);
		UpdateUi();
	}

	private void ClearAllFilters()
	{
		tagFilters = new List<string>();
		ToggleButton3D[] array = filterToggles;
		foreach (ToggleButton3D toggleButton3D in array)
		{
			toggleButton3D.ForceRelease();
		}
	}

	private void ToggleTagFilter(string tag)
	{
		if (!tagFilters.Contains(tag))
		{
			tagFilters.Add(tag);
		}
		else
		{
			tagFilters.Remove(tag);
		}
	}

	private string GetFlowTitle(TestPass testPass)
	{
		string testPassCompletionStatusRichText = TestPassItem.GetTestPassCompletionStatusRichText(testPass);
		return string.Format("{0}\n{1} - {2} ({3})", testPass.Name, testPass.StartDate.ToString("M/d/yy"), testPass.EndDate.ToString("M/d/yy"), testPassCompletionStatusRichText);
	}

	private List<TestCase> SortTestCases(List<TestCase> testCases)
	{
		List<TestCase> list = testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.Claimed && tc.AssignedPlayerIds.Contains((int)Player.LocalPlayer.PlayerId)).ToList();
		List<TestCase> second = (from tc in testCases.Except(list)
			orderby tc.Status
			select tc).ToList();
		return list.Concat(second).ToList();
	}

	private List<TestCase> FilterTestCasesByDisplayMode(List<TestCase> testCases, DisplayMode displayMode)
	{
		return displayMode switch
		{
			DisplayMode.MyUnfinished => testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.Claimed && tc.AssignedPlayerIds.Contains((int)Player.LocalPlayer.PlayerId)).ToList(), 
			DisplayMode.NotYetTested => testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.NotYetTested).ToList(), 
			DisplayMode.Claimed => testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.Claimed && !tc.AssignedPlayerIds.Contains((int)Player.LocalPlayer.PlayerId)).ToList(), 
			DisplayMode.Failed => testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.Failed).ToList(), 
			DisplayMode.Passed => testCases.Where((TestCase tc) => tc.Status == TestCaseStatus.Passed).ToList(), 
			_ => throw new NotImplementedException($"Unimplemented display mode: {displayMode}"), 
		};
	}

	private List<TestCase> FilterTestCases(List<TestCase> testCases, List<string> tagFilters)
	{
		if (!tagFilters.Any())
		{
			return testCases;
		}
		return testCases.Where((TestCase tc) => tc.Tags.Any((string tag) => tagFilters.Any((string tagFilter) => tag.Equals(tagFilter, StringComparison.OrdinalIgnoreCase)))).ToList();
	}
}
