public class TapToOpenWatch : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private Collider oculusCollider;

	[SerializeField]
	private Collider viveCollider;

	private float tapDecayTime = 0.5f;

	private float minTimeBetweenTaps = 1f;

	private float lastTapTime;

	private bool _isTapped;

	public bool IsTapped
	{
		get
		{
			return _isTapped;
		}
		set
		{
			if (value)
			{
				if (UnityEngine.Time.time - lastTapTime > minTimeBetweenTaps)
				{
					lastTapTime = UnityEngine.Time.time;
					_isTapped = value;
					StartCoroutine(RunTapDecay());
				}
			}
			else
			{
				_isTapped = value;
			}
		}
	}

	private void Awake()
	{
		InputManager.VRInputMode vRMode = SingletonMonoBehaviour<InputManager>.Instance.VRMode;
		oculusCollider.enabled = vRMode == InputManager.VRInputMode.Oculus || vRMode == InputManager.VRInputMode.SteamVR_Oculus || vRMode == InputManager.VRInputMode.SteamVR_WindowsMR;
		viveCollider.enabled = !oculusCollider.enabled;
	}

	private IEnumerator RunTapDecay()
	{
		yield return new WaitForSeconds(tapDecayTime);
		IsTapped = false;
	}

	private void OnTriggerEnter(Collider other)
	{
		if (Player.LocalPlayerExists)
		{
			PlayerHand componentInParent = other.GetComponentInParent<PlayerHand>();
			PlayerHand attachedHand = Player.LocalPlayer.PlayerUI.WatchMenuProjector.AttachedHand;
			if (attachedHand != null && componentInParent == Player.LocalPlayer.GetOtherHand(attachedHand.Type) && componentInParent.MenuFinger.gameObject == other.gameObject)
			{
				IsTapped = true;
			}
		}
	}
}
public class WatchAttractor : UnityEngine.MonoBehaviour
{
	[Flags]
	public enum EffectFlags
	{
		Sound = 1,
		Particle = 2,
		Haptic = 4,
		Text = 8
	}

	public const EffectFlags EffectFlags_None = (EffectFlags)0;

	public const EffectFlags EffectFlags_All = (EffectFlags)(-1);

	public const EffectFlags EffectFlags_AllButText = ~EffectFlags.Text;

	[SerializeField]
	private NotificationLineControl notificationEffect;

	[SerializeField]
	private float notificationEffectAutoDismissDuration = 10f;

	[SerializeField]
	private NotificationLineControl.NotificationLineControlConfig notificationLineConfig;

	[SerializeField]
	private NotificationProjectorBeam notificationProjectorBeam;

	[SerializeField]
	private RecRoomAudioClip notificationAudio;

	private bool hasNonMessageNotification;

	private Player cachedPlayer;

	private Player player
	{
		get
		{
			if (cachedPlayer == null)
			{
				cachedPlayer = base.gameObject.GetComponentInParent<Player>();
			}
			return cachedPlayer;
		}
	}

	private void Start()
	{
		if (player != null)
		{
			if (!player.isLocal)
			{
				UnityEngine.Object.Destroy(this);
			}
			player.PlayerEvents.MenuVisibleEvent += PlayerEvents_MenuVisibleEvent;
		}
		notificationEffect.Config = notificationLineConfig;
	}

	private void OnDestroy()
	{
		if (player != null && player.PlayerEvents != null)
		{
			player.PlayerEvents.MenuVisibleEvent -= PlayerEvents_MenuVisibleEvent;
		}
	}

	private void PlayerEvents_MenuVisibleEvent(bool visible)
	{
		if (visible)
		{
			StopNotificationEffect();
		}
	}

	public void PlayNotificationEffect(bool isMessageNotification, EffectFlags effectsToPlay = (EffectFlags)(-1), string textOverride = null, string textOverrideSubtitle = null)
	{
		if (player == null)
		{
			return;
		}
		PlayerHand attachedHand = player.PlayerUI.WatchMenuProjector.AttachedHand;
		if (!isMessageNotification)
		{
			hasNonMessageNotification = true;
		}
		if (attachedHand == null)
		{
			UnityEngine.Debug.LogError("PlayerMenu notification feedback tried to play with a null AnchorHand.");
		}
		else if (SingletonMonoBehaviour<SettingsManager>.Instance.ShowWatchNotifications || !isMessageNotification)
		{
			if ((effectsToPlay & EffectFlags.Sound) == EffectFlags.Sound)
			{
				AudioManager.Play3DSFX(notificationAudio, attachedHand.transform.position);
			}
			if ((effectsToPlay & EffectFlags.Particle) == EffectFlags.Particle && notificationEffect != null)
			{
				ShowNotificationEffect(show: true);
			}
			if ((effectsToPlay & EffectFlags.Text) == EffectFlags.Text)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.IsNullOrEmpty(textOverride) ? "New notification!" : textOverride, string.IsNullOrEmpty(textOverrideSubtitle) ? "Check your watch..." : textOverrideSubtitle, 3f);
			}
			if ((effectsToPlay & EffectFlags.Haptic) == EffectFlags.Haptic)
			{
				player.StartCoroutine(NotificationVibrationCoroutine(attachedHand));
			}
		}
	}

	public void StopNotificationEffect()
	{
		ShowNotificationEffect(show: false);
	}

	public void ClearMessageNotification()
	{
		if (notificationEffect.gameObject.activeSelf && !hasNonMessageNotification)
		{
			ShowNotificationEffect(show: false);
		}
	}

	private void ShowNotificationEffect(bool show)
	{
		CancelInvoke("DelayedDisableNotificationEffect");
		notificationEffect.gameObject.SetActive(show);
		if (show)
		{
			Invoke("DelayedDisableNotificationEffect", notificationEffectAutoDismissDuration);
		}
		notificationProjectorBeam.gameObject.SetActive(show);
		if (!show)
		{
			hasNonMessageNotification = false;
		}
	}

	private void DelayedDisableNotificationEffect()
	{
		if (notificationEffect.gameObject.activeSelf)
		{
			ShowNotificationEffect(show: false);
		}
	}

	private IEnumerator NotificationVibrationCoroutine(PlayerHand handToVibrate)
	{
		yield return new WaitForSeconds(0.1f);
		handToVibrate.Vibrate(450);
		yield return new WaitForSeconds(0.1f);
		handToVibrate.Vibrate(450);
	}
}
namespace RecRoom
{
	public class WatchGazeTracker : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public struct GazeParameters
		{
			[SerializeField]
			private float maxFovAngle;

			[SerializeField]
			private float maxPitchAngle;

			[SerializeField]
			private float maxRollAngle;

			public float MaxFovDot { get; private set; }

			public float MaxPitchDot { get; private set; }

			public float MaxRollDot { get; private set; }

			public void CalculateDotProductThresholds()
			{
				MaxFovDot = Mathf.Cos(maxFovAngle * ((float)Math.PI / 180f));
				MaxPitchDot = Mathf.Cos(maxPitchAngle * ((float)Math.PI / 180f));
				MaxRollDot = Mathf.Cos(maxRollAngle * ((float)Math.PI / 180f));
			}
		}

		[SerializeField]
		private GazeParameters watchOpenParameters;

		[SerializeField]
		private GazeParameters watchCloseParameters;

		[SerializeField]
		private float watchOpenDwellDuration = 1f;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private WatchMenuProjector watchMenuProjector;

		private PlayerHand dwellHand;

		private float dwellStartTime;

		private bool dwellAllowed = true;

		private void Awake()
		{
			watchOpenParameters.CalculateDotProductThresholds();
			watchCloseParameters.CalculateDotProductThresholds();
		}

		public void UpdateWatchDwelling()
		{
			if (dwellHand == null)
			{
				watchMenuProjector.WatchVisual.ResetDwellVisual();
				PlayerHand gazedHand = GetGazedHand(watchOpenParameters);
				if (gazedHand == null)
				{
					dwellAllowed = true;
				}
				else if (gazedHand.HandVisualsActive && dwellAllowed)
				{
					dwellHand = gazedHand;
					dwellStartTime = UnityEngine.Time.time;
					if (dwellHand != watchMenuProjector.AttachedHand)
					{
						watchMenuProjector.AttachedHand = dwellHand;
					}
				}
				return;
			}
			float num = Mathf.InverseLerp(dwellStartTime, dwellStartTime + watchOpenDwellDuration, UnityEngine.Time.time);
			watchMenuProjector.WatchVisual.SetDwellVisualProgress(num);
			if (!dwellHand.HandVisualsActive || !IsGazingAtWatch(dwellHand, watchCloseParameters, out var _))
			{
				dwellHand = null;
			}
			else if (num >= 1f)
			{
				WatchVisual watchVisual = watchMenuProjector.WatchVisual;
				if (!SingletonMonoBehaviour<SettingsManager>.Instance.TapToOpenWatch || watchVisual.TapToOpenWatch.IsTapped)
				{
					watchMenuProjector.AuthorityOpenMenuAttached(dwellHand);
					dwellHand = null;
					dwellAllowed = false;
					watchVisual.ResetDwellVisual();
					watchVisual.TapToOpenWatch.IsTapped = false;
				}
			}
		}

		public bool IsGazingAtWatch()
		{
			bool handInFov;
			return IsGazingAtWatch(out handInFov);
		}

		public bool IsGazingAtWatch(out bool handInFov)
		{
			GazeParameters parameters = ((!watchMenuProjector.IsMenuOpen) ? watchOpenParameters : watchCloseParameters);
			return IsGazingAtWatch(watchMenuProjector.AttachedHand, parameters, out handInFov);
		}

		private bool IsGazingAtWatch(PlayerHand hand, GazeParameters parameters, out bool handInFov)
		{
			if (hand == null)
			{
				handInFov = false;
				return false;
			}
			Player player = watchMenuProjector.Player;
			Vector3 normalized = (hand.WatchFaceTransform.position - player.Head.transform.position).normalized;
			Vector3 forward = player.Head.transform.forward;
			Vector3 forward2 = hand.WatchFaceTransform.forward;
			Vector3 up = hand.WatchFaceTransform.up;
			Vector3 up2 = player.Head.transform.up;
			float num = Vector3.Dot(normalized, forward);
			float num2 = Vector3.Dot(normalized, forward2);
			float num3 = Vector3.Dot(up, up2);
			handInFov = num >= parameters.MaxFovDot;
			return handInFov && num2 >= parameters.MaxPitchDot && num3 >= parameters.MaxRollDot;
		}

		private PlayerHand GetGazedHand(GazeParameters gazeParameters)
		{
			Player player = watchMenuProjector.Player;
			if (IsGazingAtWatch(player.LeftHand, gazeParameters, out var handInFov))
			{
				return player.LeftHand;
			}
			if (IsGazingAtWatch(player.RightHand, gazeParameters, out handInFov))
			{
				return player.RightHand;
			}
			return null;
		}
	}
}
namespace RecRoom.AGUI
{
	public class WatchMenuProjector : MenuProjector
	{
		public enum WatchMenuAnimationState
		{
			Hidden,
			Hydrate,
			Visible,
			Dehydrate,
			PlayerMenu_Transition,
			PlayerMenu_Refresh,
			PlayerMenu_KeyboardActive,
			PlayerMenu_KeyboardInactive
		}

		[SerializeField]
		private GameObject projectionRoot;

		[SerializeField]
		private GameObject keyboardRoot;

		[SerializeField]
		private GameObject XLKeyboardRoot;

		[SerializeField]
		private Renderer projectionRenderer;

		[SerializeField]
		private WatchVisual watchVisualPrefab;

		[SerializeField]
		private Transform watchVisualRoot;

		[SerializeField]
		private Transform remoteVisualRoot;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Animator animator;

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private WatchGazeTracker watchGazeTracker;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action<bool> m_MenuDetachedChangedAction;

		[NonSerialized]
		public bool WatchGazeOpeningEnabled = true;

		private float watchInteractionPausedEndTime;

		private Coroutine watchInteractionPauseRoutine;

		private Dictionary<int, WatchMenuAnimationState> hashStateDictionary = new Dictionary<int, WatchMenuAnimationState>();

		private Vector3 projectionRootDefaultLocalPosition = Vector3.zero;

		private bool keepMenuOpenUntilNextGaze;

		private TokenFlag hideProjectionRendererFlag = new TokenFlag();

		private SynchronizedField<bool> _isMenuOpen;

		private SynchronizedField<bool> _isWatchAttachedToLeftHand;

		private SynchronizedField<bool, Vector3, Quaternion> menuDetachedFromWrist;

		private WatchMenuAnimationState? menuStateLastUpdate;

		public Player Player { get; private set; }

		public Renderer ProjectionRenderer => projectionRenderer;

		public Transform WatchVisualRoot => watchVisualRoot;

		public bool IsMenuOpen
		{
			get
			{
				return _isMenuOpen.Get();
			}
			private set
			{
				_isMenuOpen.Set(value);
			}
		}

		private bool isWatchAttachedToLeftHand
		{
			get
			{
				return _isWatchAttachedToLeftHand.Get();
			}
			set
			{
				_isWatchAttachedToLeftHand.Set(value);
			}
		}

		public WatchVisual WatchVisual { get; private set; }

		public WatchGazeTracker WatchGazeTracker => watchGazeTracker;

		public PlayerHand AttachedHand
		{
			get
			{
				return (!isWatchAttachedToLeftHand) ? Player.RightHand : Player.LeftHand;
			}
			set
			{
				isWatchAttachedToLeftHand = value != null && value.Type == PlayerHand.HandType.Left;
			}
		}

		public bool AttachedToWrist => !menuDetachedFromWrist.Get1();

		private Vector3 OptimalDetachedMenuWithKeyboardPositionWorldSpace
		{
			get
			{
				Transform targetTransform = Player.Head.RigidbodyEx.TargetTransform;
				Vector3 result = targetTransform.TransformPoint(0f, 0f, base.OptimalDetachedMenuDistance + 0.1f);
				result.y = targetTransform.position.y - 0.25f;
				return result;
			}
		}

		public bool IsMenuAnimationVisible => MenuAnimationState != WatchMenuAnimationState.Hidden;

		public WatchMenuAnimationState MenuAnimationState
		{
			get
			{
				if (animator != null && animator.gameObject.activeInHierarchy)
				{
					int shortNameHash = animator.GetCurrentAnimatorStateInfo(0).shortNameHash;
					return hashStateDictionary[shortNameHash];
				}
				return WatchMenuAnimationState.Hidden;
			}
		}

		public event Action<bool> MenuDetachedChangedAction
		{
			add
			{
				Action<bool> action = this.m_MenuDetachedChangedAction;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_MenuDetachedChangedAction, (Action<bool>)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action<bool> action = this.m_MenuDetachedChangedAction;
				Action<bool> action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_MenuDetachedChangedAction, (Action<bool>)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		protected void Awake()
		{
			Player = base.gameObject.GetComponentInParent<Player>();
			_isWatchAttachedToLeftHand = new SynchronizedField<bool>(Player, "WH", defaultValue: false, SetterPermissionMode.ANYONE, OnWatchHandChanged);
			_isMenuOpen = new SynchronizedField<bool>(Player, "MO", defaultValue: false, SetterPermissionMode.ANYONE, OnMenuVisibleChanged);
			menuDetachedFromWrist = new SynchronizedField<bool, Vector3, Quaternion>(Player, "MD", defaultVal1: true, Vector3.zero, Quaternion.identity, SetterPermissionMode.ANYONE, OnMenuDetachedFromWristChanged);
			remoteVisualRoot.gameObject.SetActive(!Player.isLocal);
			WatchMenuAnimationState[] array = (WatchMenuAnimationState[])System.Enum.GetValues(typeof(WatchMenuAnimationState));
			for (int i = 0; i < array.Length; i++)
			{
				WatchMenuAnimationState value = array[i];
				string text = value.ToString();
				int key = Animator.StringToHash(text);
				hashStateDictionary[key] = value;
			}
			if (Player.isLocal)
			{
				Player.PlayerLocomotion.TeleportEvent += OnThisLocalPlayerTeleport;
				animator.cullingMode = AnimatorCullingMode.AlwaysAnimate;
			}
			else
			{
				animator.cullingMode = AnimatorCullingMode.CullCompletely;
			}
			base.transform.SetParent(Player.TrackingSpace.transform);
			this.EndOfFrameRoutine(delegate
			{
				animator.enabled = true;
			});
			projectionRootDefaultLocalPosition = projectionRoot.transform.localPosition;
		}

		private void Start()
		{
			if (Player.isLocal)
			{
				AttachedHand = Player.GetOtherHand(Player.DominantHand.Type);
			}
			SpawnWatchVisuals();
			if (!Player.isLocal)
			{
				WatchVisual.DisableDwellVisual();
			}
			else
			{
				Player.BlobShadowProjector.AddShadowCaster(WatchVisual.Renderer);
			}
			OnWatchHandChanged();
			OnMenuVisibleChanged();
			OnMenuDetachedFromWristChanged();
		}

		protected void OnDestroy()
		{
			if (Player != null && Player.isLocal && Player.PlayerLocomotion != null)
			{
				Player.PlayerLocomotion.TeleportEvent -= OnThisLocalPlayerTeleport;
			}
		}

		private void Update()
		{
			WatchMenuAnimationState? watchMenuAnimationState = menuStateLastUpdate;
			menuStateLastUpdate = MenuAnimationState;
			if (!watchMenuAnimationState.HasValue || MenuAnimationState != watchMenuAnimationState.Value)
			{
				if (MenuAnimationState == WatchMenuAnimationState.Hidden)
				{
					SetChildrenActive(active: false);
					return;
				}
				if (Player.isLocal)
				{
					Player.PlayerUI.WatchMenu.FullyVisible = MenuAnimationState == WatchMenuAnimationState.Visible;
				}
			}
			if (Player.isLocal)
			{
				LocalUpdateAttachedHand();
				LocalUpdateKeyboardState();
				if (Player.PlayerUI.MenusCanBeOpened && !IsMenuOpen)
				{
					LocalUpdateTapWatchVisuals();
					LocalUpdateWatchDwelling();
				}
			}
			if (AttachedToWrist && IsMenuAnimationVisible)
			{
				UpdateAttachedMenuPosition();
			}
			WatchVisual.OutfitItem.SetVisible(AttachedHand != null && AttachedHand.HandVisualsActive, this);
		}

		private void UpdateAttachedMenuPosition()
		{
			if (AttachedHand != null)
			{
				Transform transform = AttachedHand.transform;
				Transform transform2 = Player.TrackingSpace.transform;
				Transform watchMenuOrigin = AttachedHand.WatchMenuOrigin;
				Transform watchFaceTransform = AttachedHand.WatchFaceTransform;
				Vector3 position = transform.TransformPoint(watchMenuOrigin.localPosition);
				Quaternion rotation = transform.TransformRotation(watchMenuOrigin.localRotation);
				Vector3 localPosition = transform2.InverseTransformPoint(position);
				Quaternion localRotation = transform2.InverseTransformRotation(rotation);
				projectionRoot.transform.position = watchFaceTransform.position;
				SetMenuLocalPosition(localPosition, localRotation);
			}
		}

		private void LocalUpdateAttachedHand()
		{
			if (AttachedHand != null && AttachedHand.HandConnectedState == PlayerHand.ConnectedState.NOT_CONNECTED)
			{
				PlayerHand otherHand = Player.GetOtherHand(AttachedHand.Type);
				if (otherHand != null && otherHand.HandConnectedState != PlayerHand.ConnectedState.NOT_CONNECTED)
				{
					AttachedHand = otherHand;
				}
			}
		}

		private void LocalUpdateKeyboardState()
		{
			if (Player.PlayerUI.LocalVirtualKeyboard == null)
			{
				return;
			}
			bool flag = false;
			if (IsMenuOpen)
			{
				TMP_InputField focusedInputField = KeyboardInputField.FocusedInputField;
				flag = focusedInputField != null && focusedInputField.transform.HasParent(base.transform) && SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode;
			}
			if (flag != Player.PlayerUI.LocalVirtualKeyboard.IsOpen)
			{
				if (flag)
				{
					AuthorityOpenMenuWithKeyboard();
				}
				else
				{
					Player.PlayerUI.LocalVirtualKeyboard.HideKeyboard(this);
				}
			}
		}

		private void LocalUpdateWatchDwelling()
		{
			if (WatchGazeOpeningEnabled)
			{
				WatchGazeTracker.UpdateWatchDwelling();
			}
		}

		private void LocalUpdateTapWatchVisuals()
		{
			if (SingletonMonoBehaviour<SettingsManager>.Instance.TapToOpenWatch && !IsMenuOpen && WatchGazeTracker.IsGazingAtWatch() && !WatchVisual.TapToOpenWatch.IsTapped)
			{
				OutlineEffectRenderer.RenderHoverOutline(WatchVisual.Renderer);
			}
		}

		private void OnThisLocalPlayerTeleport(Player player, Vector3 sourceGroundPosition, Vector3 destinationGroundPosition)
		{
			if (Player.isLocal && !AttachedToWrist)
			{
				IsMenuOpen = false;
			}
		}

		private void OnMenuDetachedFromWristChanged()
		{
			if (!AttachedToWrist)
			{
				SetMenuLocalPosition(menuDetachedFromWrist.Get2(), menuDetachedFromWrist.Get3());
			}
			SetProjectionVisualsVisible(AttachedToWrist, this);
			if (this.MenuDetachedChangedAction != null)
			{
				this.MenuDetachedChangedAction(AttachedToWrist);
			}
		}

		private void OnWatchHandChanged()
		{
			if (AttachedHand != null && WatchVisual != null)
			{
				WatchVisual.transform.SetParent(AttachedHand.WatchAnchor, worldPositionStays: false);
				if (AttachedHand.Type == PlayerHand.HandType.Right)
				{
					WatchVisual.OutfitItem.CurrentBodyPart = Player.BodyPart.RightHand;
				}
				else
				{
					WatchVisual.OutfitItem.CurrentBodyPart = Player.BodyPart.LeftHand;
				}
				Player.PlayerOutfit.SetOutfitTarget(WatchVisual.OutfitItem);
				WatchVisual.OutfitItem.ActiveRenderer.gameObject.SetActive(value: true);
			}
		}

		private void OnMenuVisibleChanged()
		{
			if (IsMenuOpen)
			{
				OnMenuOpened();
				OnMenuDetachedFromWristChanged();
			}
			else
			{
				OnMenuClosed();
			}
			keepMenuOpenUntilNextGaze = false;
			if (Player.isLocal)
			{
				Player.PlayerEvents.MenuVisible(IsMenuOpen);
			}
		}

		public void UpdateControls(bool leftMenuButtonUp, bool rightMenuButtonUp, bool leftHandExpressoButtonDown, bool rightHandExpressoButtonDown)
		{
			if (!IsMenuOpen)
			{
				return;
			}
			if (AttachedToWrist)
			{
				if (ShouldDismissAttachedMenu())
				{
					AuthorityCloseMenu();
				}
				else if (AttachedHand != null && ((AttachedHand.Type != PlayerHand.HandType.Left) ? rightMenuButtonUp : leftMenuButtonUp))
				{
					AuthorityDetachMenu();
				}
			}
			else if (leftHandExpressoButtonDown || rightHandExpressoButtonDown)
			{
				AuthorityCloseMenu();
			}
		}

		public void AuthorityOpenMenuWithKeyboard()
		{
			if (AttachedToWrist)
			{
				LocalShowDetachedMenu(OptimalDetachedMenuWithKeyboardPositionWorldSpace, base.OptimalDetachedMenuRotationWorldSpace);
				TemporarilyPauseWatchInteraction(0.5f);
			}
			if (Player.PlayerUI.LocalVirtualKeyboard != null)
			{
				Player.PlayerUI.LocalVirtualKeyboard.ShowKeyboard(this, GetLocalKeyboardParent());
			}
		}

		public void AuthorityOpenMenuAttached(PlayerHand hand, bool force = false)
		{
			if (!IsMenuOpen || force)
			{
				menuDetachedFromWrist.Set1(newValue: false);
				AttachedHand = hand;
				IsMenuOpen = true;
			}
		}

		public void AuthorityOpenMenuDetached(bool force = false)
		{
			if (!IsMenuOpen || force)
			{
				LocalShowDetachedMenu(base.OptimalDetachedMenuPositionWorldSpace, base.OptimalDetachedMenuRotationWorldSpace);
				TemporarilyPauseWatchInteraction(0.5f);
			}
		}

		public void AuthorityOpenMenuDetached(Vector3 position, bool force = true)
		{
			if (!IsMenuOpen || force)
			{
				LocalShowDetachedMenu(position, base.OptimalDetachedMenuRotationWorldSpace);
				TemporarilyPauseWatchInteraction(0.5f);
			}
		}

		public void AuthorityDetachMenu()
		{
			if (IsMenuOpen && AttachedToWrist)
			{
				LocalShowDetachedMenu(base.transform.position, base.transform.rotation);
			}
		}

		public void AuthorityReattachMenu()
		{
			if (IsMenuOpen && !AttachedToWrist)
			{
				menuDetachedFromWrist.Set1(newValue: false);
				TemporarilyPauseWatchInteraction(0.5f);
			}
		}

		public void AuthorityCloseMenu()
		{
			IsMenuOpen = false;
		}

		private void LocalShowDetachedMenu(Vector3 detachPositionWorldSpace, Quaternion detachRotationWorldSpace)
		{
			Vector3 newValue = Player.TrackingSpace.transform.InverseTransformPoint(detachPositionWorldSpace);
			Quaternion newValue2 = Player.TrackingSpace.transform.InverseTransformRotation(detachRotationWorldSpace);
			menuDetachedFromWrist.Set(newValue1: true, newValue, newValue2);
			IsMenuOpen = true;
		}

		private void OnMenuOpened()
		{
			SetChildrenActive(active: true);
			this.EndOfFrameRoutine(delegate
			{
				if (IsMenuOpen)
				{
					animator.SetBool("Visible", value: true);
				}
			});
			SingletonMonoBehaviour<TutorialManager>.Instance.TryTeachableMoment<WatchChallengesTeachableMoment>();
			if (SingletonMonoBehaviour<SettingsManager>.Instance.TapToOpenWatch && Player.isLocal)
			{
				TemporarilyPauseWatchInteraction(1f);
			}
			projectionRoot.transform.localPosition = projectionRootDefaultLocalPosition;
		}

		private void OnMenuClosed()
		{
			if (Player.isLocal)
			{
				Player.PlayerUI.LocalVirtualKeyboard.HideKeyboard(this);
			}
			animator.SetBool("Visible", value: false);
		}

		private Transform GetLocalKeyboardParent()
		{
			if (Player.LocalPlayer.PlayerUI.WatchMenu.Size == SizeOption.LARGE)
			{
				return XLKeyboardRoot.transform;
			}
			return keyboardRoot.transform;
		}

		public void TriggerTransition()
		{
			animator.SetTrigger("Transition");
		}

		public void TriggerRefresh()
		{
			animator.SetTrigger("Refresh");
		}

		public void ShowProjectionVisuals(object token)
		{
			SetProjectionVisualsVisible(visible: true, token);
		}

		public void HideProjectionVisuals(object token)
		{
			SetProjectionVisualsVisible(visible: false, token);
		}

		private void SetProjectionVisualsVisible(bool visible, object token)
		{
			if (!visible)
			{
				hideProjectionRendererFlag.Add(token);
			}
			else
			{
				hideProjectionRendererFlag.Remove(token);
			}
			if (projectionRenderer != null)
			{
				projectionRenderer.enabled = !hideProjectionRendererFlag.HasTokens;
			}
		}

		private void TemporarilyPauseWatchInteraction(float duration)
		{
			watchInteractionPausedEndTime = Mathf.Max(UnityEngine.Time.time + duration, watchInteractionPausedEndTime);
			if (watchInteractionPauseRoutine != null)
			{
				Player.PlayerUI.WatchMenu.BasicInteractionRestriction.AllElementsRestricted = false;
				this.SafeStopCoroutine(watchInteractionPauseRoutine);
			}
			watchInteractionPauseRoutine = StartCoroutine(RunTemporaryDisableWatchInteraction(watchInteractionPausedEndTime - UnityEngine.Time.time));
		}

		private IEnumerator RunTemporaryDisableWatchInteraction(float duration)
		{
			if (!Player.PlayerUI.WatchMenu.BasicInteractionRestriction.HasAnyActiveRestrictions)
			{
				Player.PlayerUI.WatchMenu.BasicInteractionRestriction.AllElementsRestricted = true;
				yield return new WaitForSeconds(duration);
				Player.PlayerUI.WatchMenu.BasicInteractionRestriction.AllElementsRestricted = false;
			}
			watchInteractionPauseRoutine = null;
		}

		private void SetMenuLocalPosition(Vector3 localPosition, Quaternion localRotation)
		{
			base.transform.localPosition = localPosition;
			base.transform.localRotation = localRotation;
		}

		private void SetChildrenActive(bool active)
		{
			for (int i = 0; i < base.transform.childCount; i++)
			{
				base.transform.GetChild(i).gameObject.SetActive(active);
			}
		}

		private bool ShouldDismissAttachedMenu()
		{
			if (!AttachedToWrist)
			{
				return false;
			}
			if (!AttachedHand.HandVisualsActive)
			{
				return true;
			}
			bool handInFov;
			bool flag = WatchGazeTracker.IsGazingAtWatch(out handInFov);
			if (flag && keepMenuOpenUntilNextGaze)
			{
				keepMenuOpenUntilNextGaze = false;
			}
			return !handInFov || (!flag && !keepMenuOpenUntilNextGaze);
		}

		private void SpawnWatchVisuals()
		{
			OutfitItem outfitItem = PlayerOutfit.InstantiateNewOutfitPrefab(watchVisualPrefab.OutfitItem, Player.BodyPart.LeftHand, Player);
			WatchVisual = outfitItem.GetComponent<WatchVisual>();
			WatchVisual.transform.position = Vector3.zero;
			WatchVisual.transform.rotation = Quaternion.identity;
			Player.PlayerUI.WatchAttractor = WatchVisual.GetComponent<WatchAttractor>();
			if (Player.isLocal)
			{
				return;
			}
			Collider[] componentsInChildren = outfitItem.gameObject.GetComponentsInChildren<Collider>();
			if (componentsInChildren != null && componentsInChildren.Length > 0)
			{
				for (int i = 0; i < componentsInChildren.Length; i++)
				{
					componentsInChildren[i].enabled = false;
				}
			}
		}
	}
}
public class WatchVisual : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private OutfitItem _outfitItem;

	[SerializeField]
	private Renderer dwellVisual;

	[SerializeField]
	private int dwellVisualMaterialIndex;

	[SerializeField]
	private float maxSwipeValue = 1.35f;

	[Autofill(AutofillType.SelfAndChildren, false)]
	[SerializeField]
	private TapToOpenWatch _tapToOpenWatch;

	private int progressParameterId = -1;

	public TapToOpenWatch TapToOpenWatch => _tapToOpenWatch;

	public Renderer Renderer => _outfitItem.ActiveRenderer;

	public OutfitItem OutfitItem => _outfitItem;

	private void Awake()
	{
		progressParameterId = Shader.PropertyToID("_Swipe");
	}

	public void SetDwellVisualProgress(float t)
	{
		if (dwellVisual != null)
		{
			dwellVisual.enabled = true;
			dwellVisual.materials[dwellVisualMaterialIndex].SetFloat(progressParameterId, Mathf.Lerp(0f, maxSwipeValue, t));
		}
	}

	public void ResetDwellVisual()
	{
		if (dwellVisual != null)
		{
			dwellVisual.materials[dwellVisualMaterialIndex].SetFloat(progressParameterId, 0f);
		}
	}

	public void DisableDwellVisual()
	{
		if (dwellVisual != null)
		{
			dwellVisual.enabled = false;
		}
	}
}
