		remove
		{
			Action action = WatchUI.m_LocalPlayerAndWatchMenuSpawned;
			Action action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref WatchUI.m_LocalPlayerAndWatchMenuSpawned, (Action)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public static event Action<ToastIds, string> OnToastUpdatedEvent
	{
		add
		{
			Action<ToastIds, string> action = WatchUI.m_OnToastUpdatedEvent;
			Action<ToastIds, string> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref WatchUI.m_OnToastUpdatedEvent, (Action<ToastIds, string>)Delegate.Combine(action2, value), action);
			}
			while (action != action2);
		}
		remove
		{
			Action<ToastIds, string> action = WatchUI.m_OnToastUpdatedEvent;
			Action<ToastIds, string> action2;
			do
			{
				action2 = action;
				action = Interlocked.CompareExchange(ref WatchUI.m_OnToastUpdatedEvent, (Action<ToastIds, string>)Delegate.Remove(action2, value), action);
			}
			while (action != action2);
		}
	}

	public void PauseMessages(object token)
	{
		pauseMessagesFlag.Add(token);
	}

	public void UnpauseMessages(object token)
	{
		pauseMessagesFlag.Remove(token);
	}

	private void UpdatePausedMessagesInWatch(bool areOnlyCertainButtonsAllowed)
	{
		if (areOnlyCertainButtonsAllowed)
		{
			PauseMessages(this);
		}
		else
		{
			UnpauseMessages(this);
		}
	}

	private void Start()
	{
		BasicInteractionRestriction.OnRestrictionUpdated += UpdatePausedMessagesInWatch;
		foreach (StackedUIFlowBase allFlow in base.AllFlows)
		{
			Button3DBase[] componentsInChildren = allFlow.GetComponentsInChildren<Button3DBase>(includeInactive: true);
			Button3DBase[] array = componentsInChildren;
			foreach (Button3DBase button3DBase in array)
			{
				button3DBase.ButtonDownAudio = buttonDownAudio;
				button3DBase.ButtonUpAudio = buttonUpAudio;
			}
		}
		if (WatchMenuProjector != null && WatchMenuProjector.ProjectionRenderer != null)
		{
			projectionRendererMaterial = WatchMenuProjector.ProjectionRenderer.material;
		}
		if (backgroundImage != null)
		{
			backgroundImageMaterial = new Material(backgroundImage.material);
			backgroundImage.material = backgroundImageMaterial;
		}
		StartCoroutine(WaitForPlayerSpawnAndShowDialog());
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if (Player.LocalPlayerExists && Player.LocalPlayer.PlayerUI != null)
		{
			Player.LocalPlayer.PlayerUI.WatchMenuProjector.MenuDetachedChangedAction -= OnMenuDetachedChanged;
		}
		BasicInteractionRestriction.OnRestrictionUpdated -= UpdatePausedMessagesInWatch;
		if (projectionRendererMaterial != null)
		{
			UnityEngine.Object.Destroy(projectionRendererMaterial);
			projectionRendererMaterial = null;
		}
		if (backgroundImageMaterial != null)
		{
			UnityEngine.Object.Destroy(backgroundImageMaterial);
			backgroundImageMaterial = null;
		}
	}

	protected override void PushFlowInternal(StackedUIFlowBase flow)
	{
		if (!Locked)
		{
			base.PushFlowInternal(flow);
		}
	}

	protected override bool PopFlowInternal()
	{
		if (!Locked)
		{
			return base.PopFlowInternal();
		}
		return false;
	}

	protected override bool RefreshTopFlowInternal()
	{
		if (WatchMenuProjector != null && WatchMenuProjector.IsMenuAnimationVisible)
		{
			WatchMenuProjector.TriggerTransition();
		}
		return base.RefreshTopFlowInternal();
	}

	protected override void FlowTransition(StackedUIFlowBase newFlow, StackedUIFlowBase oldFlow)
	{
		base.FlowTransition(newFlow, oldFlow);
		if (WatchMenuProjector != null && WatchMenuProjector.IsMenuAnimationVisible)
		{
			WatchMenuProjector.TriggerTransition();
		}
		WatchUIFlow watchUIFlow = newFlow as WatchUIFlow;
		if (watchUIFlow != null && watchUIFlow.AlwaysDetachMenu && Player.LocalPlayerExists)
		{
			WatchMenuProjector.AuthorityDetachMenu();
		}
	}

	protected override void OnUIOpened()
	{
		base.OnUIOpened();
		if (SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode && !base.CurrentFlow.ForceSpecificSize)
		{
			base.Size = SizeOption.NORMAL;
		}
		WatchUIFlow watchUIFlow = base.CurrentFlow as WatchUIFlow;
		if (watchUIFlow != null && watchUIFlow.AlwaysDetachMenu && Player.LocalPlayerExists)
		{
			WatchMenuProjector.AuthorityDetachMenu();
		}
		if (watchOpenAudioSource != null)
		{
			watchOpenAudioSource.Stop();
		}
		if (watchOpenedAudio != null && watchOpenedAudio.audioClip != null)
		{
			watchOpenAudioSource = AudioManager.Play3DSFX(watchOpenedAudio, base.transform);
		}
		Messages.OnMessageListUpdated += MessagesUpdated;
		SetToast(ToastIds.Messages, Messages.MessageList.Count + Chats.GetUnreadChatThreadsCount());
	}

	protected override void OnUIClosed()
	{
		base.OnUIClosed();
		Messages.OnMessageListUpdated -= MessagesUpdated;
	}

	protected override void OnFlowsInitialized()
	{
		base.OnFlowsInitialized();
		confirmationDialog = GetFlowByType<UIConfirmationDialog>();
		if (confirmationDialog == null)
		{
			UnityEngine.Debug.LogError("No confirmation dialog found");
		}
		chatThreadScreen = GetFlowByType<ChatThreadScreen>();
		if (chatThreadScreen == null)
		{
			UnityEngine.Debug.LogError("No ChatThreadScreen found");
		}
		messageDialog = GetFlowByType<UIMessageDialog>();
		if (messageDialog == null)
		{
			UnityEngine.Debug.LogError("No message dialog found");
		}
		voteDialog = GetFlowByType<UIVoteDialog>();
		if (voteDialog == null)
		{
			UnityEngine.Debug.LogError("No vote dialog found");
		}
		importFriendsDialog = GetFlowByType<UIImportFriendsDialog>();
		if (importFriendsDialog == null)
		{
			UnityEngine.Debug.LogError("No import friends dialog found");
		}
		registrationDialog = GetFlowByType<UIRegistrationDialog>();
		if (registrationDialog == null)
		{
			UnityEngine.Debug.LogError("No registration dialog found");
		}
	}

	protected override void OnSizeChanged()
	{
		if (WatchMenuProjector != null)
		{
			if (base.gameObject.activeInHierarchy && WatchMenuProjector.IsMenuAnimationVisible)
			{
				WatchMenuProjector.TriggerRefresh();
				StartCoroutine(RunResizeCompleteEvent());
			}
			else
			{
				OnResizeComplete();
			}
			if (base.Size == SizeOption.LARGE)
			{
				WatchMenuProjector.AuthorityDetachMenu();
			}
		}
		else
		{
			OnResizeComplete();
		}
	}

	private IEnumerator RunResizeCompleteEvent()
	{
		yield return null;
		while (!base.FullyVisible)
		{
			yield return null;
		}
		OnResizeComplete();
	}

