	public IPromise<ResponseType> ShowTemporaryDialog<DialogType, ResponseType>(DialogType dialogPrefab, Func<DialogType, IPromise<ResponseType>> createPromiseFunc, WatchAttractor.EffectFlags notificationEffects = ~WatchAttractor.EffectFlags.Text) where DialogType : UIDialog<ResponseType>
	{
		DialogType newDialog = UnityEngine.Object.Instantiate(dialogPrefab, base.transform, worldPositionStays: false);
		newDialog.IsInstanced = true;
		if ((bool)newDialog)
		{
			PlayAttract(notificationEffects);
			InitializeFlow(newDialog);
			PushFlow(newDialog);
			IPromise<ResponseType> promise = createPromiseFunc(newDialog);
			promise.Then((Action)delegate
			{
				UnityEngine.Object.Destroy(newDialog.gameObject);
			});
			return promise;
		}
		return null;
	}

