	public void ShowSwitchPlayerTypeAndJoinDialog(RecNet.Rooms.CanJoinStatus canJoinStatus, Action tryJoin)
	{
		Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Oops!", $"Sorry, this room is only accessible to {canJoinStatus.FailureString} players.\n\nWould you like to switch to {LocalPlayerController.GetPlayerModeDescription(canJoinStatus.SuggestedPlayerType)}?", "Switch").Then(delegate(ConfirmDialogResponses response)
		{
			if (response == ConfirmDialogResponses.Affirmative && canJoinStatus.SuggestedPlayerType != LocalPlayerController.PlayerType.SCREEN)
			{
				if (canJoinStatus.SuggestedPlayerType == LocalPlayerController.PlayerType.VR_TELEPORT)
				{
					SingletonMonoBehaviour<LocalPlayerController>.Instance.SwitchVRMovementModeToJoinRoom(VRMovementMode.TELEPORT);
				}
				else
				{
					SingletonMonoBehaviour<LocalPlayerController>.Instance.SwitchVRMovementModeToJoinRoom(VRMovementMode.WALK);
				}
				if (tryJoin != null)
				{
					tryJoin();
				}
			}
		});
	}

