	public void ShowReportScreen(Action<ReportWatchUIFlow> setup, Func<ReportWatchUIFlow, bool> canReport, Action<ReportWatchUIFlow> createReport)
	{
		ReportWatchUIFlow flowByType = GetFlowByType<ReportWatchUIFlow>();
		PushFlow(flowByType);
