		flowByType.CanIssueReportAction = canReport;
		flowByType.CreateReportAction = createReport;
	}

	private void CreatePlayerReport(ReportWatchUIFlow reportFlow)
	{
		Player player = Player.FindLocalPlayer(reportFlow.CurrentProfile.Id);
		bool playerPresent = player != null;
		float? heightReported = null;
		if (playerPresent)
		{
			heightReported = player.CurrentFloorHeightFromHead;
		}
		PlayerReporting.CreateReport(reportFlow.CurrentProfile.Id, reportFlow.Category, reportFlow.Description, heightReported, delegate(string wwwError, OkResponse okResponse)
		{
			if (!string.IsNullOrEmpty(wwwError))
			{
				UnityEngine.Debug.LogError("Failed to report player" + wwwError);
			}
			if (okResponse.Success)
			{
				AnalyticsHelper.ReportPlayer(reportFlow.CurrentProfile.Id, reportFlow.Category, playerPresent);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Thanks for your report.", "We will investigate.", 4f);
			}
			else
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, okResponse.Message, 4f);
			}
		});
	}

	public static void SetToast(ToastIds toastId, int count)
	{
		string text = string.Empty;
		if (count > 0)
		{
			text = ((count >= 100) ? "99+" : count.ToString());
		}
		SetToast(toastId, text);
	}

	public static void SetToast(ToastIds toastId, string text)
	{
		ToastTexts[toastId] = text;
		WatchUI.OnToastUpdatedEvent.DoIfNotNull(delegate(Action<ToastIds, string> _)
		{
			_(toastId, text);
		});
	}

	public static string GetToast(ToastIds toastId)
	{
		string value = string.Empty;
		ToastTexts.TryGetValue(toastId, out value);
		return value;
	}

