	private IEnumerator WaitForPlayerSpawnAndShowDialog()
	{
		while (Player.LocalPlayer == null || Player.LocalPlayer.IsSpawning)
		{
			yield return null;
		}
		if (WatchUI.LocalPlayerAndWatchMenuSpawned != null)
		{
			WatchUI.LocalPlayerAndWatchMenuSpawned();
		}
		WatchMenuProjector.MenuDetachedChangedAction += OnMenuDetachedChanged;
		if (SingletonMonoBehaviour<SessionManager>.Instance != null && !string.IsNullOrEmpty(SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage))
		{
			ShowConfirmationDialog(UIConfirmationDialog.DialogType.OK_CANCEL, SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle, SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage);
			SingletonMonoBehaviour<SessionManager>.Instance.AlertTitle = null;
			SingletonMonoBehaviour<SessionManager>.Instance.AlertMessage = null;
		}
	}

	public void SetBackgroundColors(Color backgroundColor, Color largeScanlineColor)
	{
		if (backgroundImageMaterial != null)
		{
			backgroundImageMaterial.SetColor(mainColorId, backgroundColor);
			backgroundImageMaterial.SetColor(scanlineColorId, largeScanlineColor);
		}
		if (projectionRendererMaterial != null)
		{
			projectionRendererMaterial.SetColor(mainColorId, backgroundColor);
			projectionRendererMaterial.SetColor(scanlineColorId, largeScanlineColor);
		}
	}

	public void PlayAttract(WatchAttractor.EffectFlags notificationEffects = ~WatchAttractor.EffectFlags.Text)
	{
		if (!base.FullyVisible)
		{
			WatchAttractor.PlayNotificationEffect(isMessageNotification: false, notificationEffects);
			return;
		}
		notificationEffects &= WatchAttractor.EffectFlags.Sound | WatchAttractor.EffectFlags.Haptic;
		WatchAttractor.PlayNotificationEffect(isMessageNotification: false, notificationEffects);
	}

	public void StopAttract()
	{
		WatchAttractor.StopNotificationEffect();
	}

	public void HandleIncomingChatMessage(ChatThread chatThread)
	{
		ChatMessage chatMessage = chatThread.Messages.First();
		if (AreMessagesPaused || chatMessage.SenderPlayerId <= 0 || chatMessage.SenderPlayerId == (long)Profiles.LocalProfile.Id || chatThread.IsSnoozed)
		{
			return;
		}
		float value = 0f;
		if (nextChatNotificationTimes.TryGetValue(chatThread.ChatThreadId, out value) && UnityEngine.Time.time < value)
		{
			return;
		}
		nextChatNotificationTimes[chatThread.ChatThreadId] = UnityEngine.Time.time + minTimeBetweenChatNotifications;
		if (!base.FullyVisible)
		{
			chatThreadScreen.ShowScreen(chatThread);
			WatchAttractor.PlayNotificationEffect(isMessageNotification: true);
		}
		else
		{
			WatchAttractor.PlayNotificationEffect(isMessageNotification: true, WatchAttractor.EffectFlags.Sound | WatchAttractor.EffectFlags.Haptic);
		}
		if (SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance != null && SingletonMonoBehaviour<SettingsManager>.Instance.ShowWatchNotifications)
		{
			Profile profile = Profiles.Get(chatMessage.SenderPlayerId);
			if (profile != null)
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, string.Empty, $"New message from {profile.DisplayName}!", 3f);
			}
		}
	}

	public void HandleIncomingRecNetMessage(RecNet.Message message)
	{
		if (!AreMessagesPaused)
		{
			if (!base.FullyVisible)
			{
				ShowMessageDialog(message);
				WatchAttractor.PlayNotificationEffect(isMessageNotification: true);
			}
			else
			{
				WatchAttractor.PlayNotificationEffect(isMessageNotification: true, WatchAttractor.EffectFlags.Sound | WatchAttractor.EffectFlags.Haptic);
			}
		}
	}

	private void MessagesUpdated(Messages.UpdateType updateType)
	{
		SetToast(ToastIds.Messages, Messages.MessageList.Count + Chats.GetUnreadChatThreadsCount());
	}

	public void ToggleSize()
	{
		if (base.CurrentFlow.ForceSpecificSize)
		{
			return;
		}
		if (base.Size == SizeOption.NORMAL)
		{
			base.Size = SizeOption.LARGE;
			return;
		}
		base.Size = SizeOption.NORMAL;
		if (Player.LocalPlayerExists && SingletonMonoBehaviour<LocalPlayerController>.Instance.InVRDisplayMode)
		{
			WatchMenuProjector.AuthorityReattachMenu();
		}
	}

	static WatchUI()
	{
		WatchUI.OnToastUpdatedEvent = null;
	}
}
