public class BackpackToolButton : UnityEngine.MonoBehaviour
{
	[SerializeField]
	private float toolVisualSize = 0.1f;

	[SerializeField]
	private Transform toolRoot;

	[SerializeField]
	private TextMeshProUGUI toolName;

	[SerializeField]
	private GameObject favoriteIcon;

	[SerializeField]
	private ToggleButton3D favoriteToggle;

	[SerializeField]
	private ToggleButton3D useToggle;

	private bool currentlyFavorited;

	private bool currentlyInUse;

	public PlayerBackpackToolType CurrentToolType { get; private set; } = PlayerBackpackToolType.INVALID;

	public ToggleButton3D.OnToggleButton3DClick FavoriteAction => favoriteToggle.OnClick;

	public ToggleButton3D.OnToggleButton3DClick UseAction => useToggle.OnClick;

	public void UpdateCurrentlyFavorited(bool isFavorited)
	{
		currentlyFavorited = isFavorited;
		favoriteIcon.SetActive(currentlyFavorited);
		favoriteToggle.IsOn = currentlyFavorited;
		UIHelper.SafeSetText(favoriteToggle.Label, (!currentlyFavorited) ? "Favorite" : "Unfavorite");
	}

	public void UpdateCurrentlyInUse(bool inUse)
	{
		currentlyInUse = inUse;
		useToggle.IsOn = currentlyInUse;
		UIHelper.SafeSetText(useToggle.Label, (!currentlyInUse) ? "Use" : "Recall");
	}

	public void SetToolType(PlayerBackpackToolType toolType, bool isFavorited, bool inUse, StackedUIBase stackedUIBase)
	{
		if (toolType == CurrentToolType && isFavorited == currentlyFavorited && inUse == currentlyInUse)
		{
			return;
		}
		if (toolType == CurrentToolType)
		{
			if (isFavorited != currentlyFavorited)
			{
				UpdateCurrentlyFavorited(isFavorited);
			}
			else if (inUse != currentlyInUse)
			{
				UpdateCurrentlyInUse(inUse);
			}
			return;
		}
		CurrentToolType = toolType;
		UIHelper.SafeSetText(toolName, PlayerBackpackToolSettings.GetToolFriendlyName(CurrentToolType));
		UpdateCurrentlyFavorited(isFavorited);
		UpdateCurrentlyInUse(inUse);
		Delayed3DUIObjectSpawner orAddComponent = toolRoot.gameObject.GetOrAddComponent<Delayed3DUIObjectSpawner>();
		orAddComponent.Initialize(stackedUIBase, delegate
		{
			GameObject gameObject = PlayerBackpackToolSettings.GetToolPrefab(CurrentToolType).gameObject;
			GameObject gameObject2 = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentImposter(gameObject, NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.GetFavoriteEquipmentSkin(gameObject.name));
			gameObject2.transform.parent = toolRoot;
			gameObject2.transform.AssignCorrectScale(toolVisualSize);
			gameObject2.transform.localPosition = Vector3.zero;
			gameObject2.transform.localEulerAngles = PlayerBackpackToolSettings.GetToolSpawnRotationEuler(CurrentToolType);
		});
	}
}
