		{
			return;
		}
		foreach (BaseRoomButton childUIElement in childUIElements)
		{
			BaseRoomButton innerChild = childUIElement;
			innerChild.ButtonAction.AddListener(delegate
			{
				OnBaseRoomButtonClicked.Invoke(innerChild.CurrentRoom);
			});
		}
	}

