	{
		if (rooms != null)
		{
			SetAllActiveChildren(rooms);
		}
	}

	protected override void SetChild(RecNet.Room room, BaseRoomButton button, int activeIndex)
	{
		button.SetRoom(room);
	}

	public int FindPageIndexOfRoom(string roomName)
	{
		int result = -1;
		int num = -1;
		for (int i = 0; i < base.AllActiveChildren.Count; i++)
		{
			if (base.AllActiveChildren[i] != null && base.AllActiveChildren[i].Name == roomName)
			{
				num = i;
				break;
			}
		}
		if (num >= 0)
		{
			result = num / base.PageSize;
		}
		return result;
	}
