namespace RecRoom.AGUI
{
	public class ChatMessageButton : UnityEngine.MonoBehaviour
	{
		public enum ChatMessageDisplay
		{
			MessageAndDisplayCards,
			DisplayCardsOnly,
			MessageOnly
		}

		[SerializeField]
		private Button3D playerButton;

		[SerializeField]
		private TextMeshProUGUI message;

		[SerializeField]
		private TextMeshProUGUI timeSent;

		[Header("Formatting")]
		[SerializeField]
		private GameObject leftSpacer;

		[SerializeField]
		private GameObject rightSpacer;

		[SerializeField]
		private GameObject buttonContainer;

		[SerializeField]
		private GameObject playerMessageContainer;

		[SerializeField]
		private TextMeshProUGUI systemMessageText;

		[SerializeField]
		private UnityEngine.UI.Image playerMessageBg;

		[SerializeField]
		private Sprite messageAndDisplayCardsSprite;

		[SerializeField]
		private Sprite displayCardsOnlySprite;

		[SerializeField]
		private Sprite messageOnlySprite;

		[Header("Display Cards")]
		[SerializeField]
		private GameObject topRow;

		[SerializeField]
		private GameObject displayCardsContainer;

		[SerializeField]
		private ChatMessageDisplayCard[] displayCards;

		private PlayerSpecificUIBehaviour[] playerSpecificUIs = new PlayerSpecificUIBehaviour[0];

		private ChatThread currentChatThread;

		private ChatMessage currentChatMessage;

		private ChatMessageDisplay displayMode;

		public Profile CurrentProfile { get; private set; }

		public Button3D.OnButton3DClick ButtonAction => playerButton.OnClick;

		private void Awake()
		{
			playerSpecificUIs = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
		}

		private void OnEnable()
		{
			if (currentChatMessage != null)
			{
				RefreshVisuals();
			}
		}

		public void SetChatMessage(ChatThread chatThread, ChatMessage chatMessage, ChatMessageDisplay newDisplayMode)
		{
			if (currentChatMessage == chatMessage && displayMode == newDisplayMode)
			{
				return;
			}
			currentChatThread = chatThread;
			currentChatMessage = chatMessage;
			if (currentChatMessage == null || currentChatThread == null)
			{
				return;
			}
			displayMode = newDisplayMode;
			if (currentChatMessage.IsSystemMessage)
			{
				leftSpacer.SetActive(value: false);
				rightSpacer.SetActive(value: false);
				playerMessageContainer.SetActive(value: false);
				systemMessageText.gameObject.SetActive(value: true);
				RefreshTextMessage();
				return;
			}
			Profile profile = Profiles.Get(currentChatMessage.SenderPlayerId);
			if (profile != null && (CurrentProfile == null || (long)CurrentProfile.Id != (long)profile.Id))
			{
				CurrentProfile = profile;
				PlayerSpecificUIBehaviour[] array = playerSpecificUIs;
				foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in array)
				{
					playerSpecificUIBehaviour.SetPlayer(CurrentProfile.Id);
				}
				if ((long)CurrentProfile.Id == (long)Profiles.LocalProfile.Id)
				{
					leftSpacer.SetActive(value: true);
					rightSpacer.SetActive(value: false);
					buttonContainer.SetActive(value: false);
					playerMessageContainer.SetActive(value: true);
					systemMessageText.gameObject.SetActive(value: false);
				}
				else
				{
					leftSpacer.SetActive(value: false);
					rightSpacer.SetActive(value: true);
					buttonContainer.SetActive(value: true);
					playerMessageContainer.SetActive(value: true);
					systemMessageText.gameObject.SetActive(value: false);
				}
			}
			RefreshVisuals();
		}

		private void RefreshVisuals()
		{
			switch (displayMode)
			{
			case ChatMessageDisplay.MessageAndDisplayCards:
				playerMessageBg.sprite = messageAndDisplayCardsSprite;
				topRow.SetActive(value: true);
				message.gameObject.SetActive(value: true);
				RefreshDisplayCards();
				RefreshMessage();
				break;
			case ChatMessageDisplay.DisplayCardsOnly:
				playerMessageBg.sprite = displayCardsOnlySprite;
				topRow.SetActive(value: false);
				message.gameObject.SetActive(value: false);
				RefreshDisplayCards();
				break;
			case ChatMessageDisplay.MessageOnly:
				playerMessageBg.sprite = messageOnlySprite;
				topRow.SetActive(value: true);
				message.gameObject.SetActive(value: true);
				displayCardsContainer.SetActive(value: false);
				RefreshMessage();
				break;
			}
		}

		private void RefreshDisplayCards()
		{
			Relationship relationship = Relationships.Get(currentChatMessage.SenderPlayerId);
			if (currentChatMessage.TextMessageJson.HasDisplayCards && (relationship == null || !relationship.IsBlocked))
			{
				List<Chats.DisplayCardData> displayCardData = currentChatMessage.TextMessageJson.DisplayCardData;
				displayCardsContainer.SetActive(value: true);
				for (int i = 0; i < displayCards.Length; i++)
				{
					bool flag = i < displayCardData.Count;
					displayCards[i].gameObject.SetActive(flag);
					if (flag)
					{
						displayCards[i].SetDisplayCard(displayCardData[i]);
					}
				}
			}
			else
			{
				displayCardsContainer.SetActive(value: false);
			}
		}

		private void RefreshMessage()
		{
			if (base.isActiveAndEnabled)
			{
				if (currentChatMessage.MessageJson.Type == Chats.MessageContentType.Text)
				{
					RefreshTextMessage();
				}
				else
				{
					UnityEngine.Debug.LogError("Unknown message content type!");
				}
			}
		}

		private void RefreshTextMessage()
		{
			if (currentChatMessage.IsSystemMessage)
			{
				systemMessageText.text = currentChatMessage.TextMessageJson.FormattedText;
				return;
			}
			Relationship relationship = Relationships.Get(currentChatMessage.SenderPlayerId);
			if (relationship != null && relationship.IsBlocked)
			{
				message.text = "<Message from blocked player>";
			}
			else
			{
				message.text = currentChatMessage.TextMessageJson.FormattedText;
			}
			DateTime dateTime = currentChatMessage.TimeSent.ToLocalTime();
			if (dateTime.Day == DateTime.Now.Day)
			{
				timeSent.text = dateTime.ToShortTimeString();
			}
			else
			{
				timeSent.text = string.Format("{0} {1}", dateTime.ToString("MMM"), dateTime.Day);
			}
		}
	}
}
public class ChatMessageDisplayCard : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private UnityEngine.UI.Image bgImage;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private Button3D button;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private RawImage buttonImage;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private TextMeshProUGUI nameText;

	[SerializeField]
	private Color playerColor;

	[SerializeField]
	private Color roomColor;

	private Chats.DisplayCardData displayCard;

	private PlayerDetailsWatchUIFlow playerDetailsFlow;

	private WatchUI watchUi;

	private void Start()
	{
		if (Player.LocalPlayerExists)
		{
			watchUi = Player.LocalPlayer.PlayerUI.WatchMenu;
			playerDetailsFlow = watchUi.GetFlowByType<PlayerDetailsWatchUIFlow>();
		}
	}

	public void SetDisplayCard(Chats.DisplayCardData newCard)
	{
		displayCard = newCard;
		button.Interactable = false;
		switch (displayCard.ReplacementType)
		{
		case Chats.MarkupReplacementType.Username:
		{
			bgImage.color = playerColor;
			Profile profile = Profiles.Get(displayCard.Id);
			if (profile != null)
			{
				UpdateProfile(profile);
			}
			else
			{
				Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			}
			break;
		}
		case Chats.MarkupReplacementType.Roomname:
		{
			bgImage.color = roomColor;
			IPromise<RecNet.Room> roomById = RecNet.Rooms.GetRoomById(displayCard.Id);
			roomById.Then(delegate(RecNet.Room room)
			{
				if (this != null)
				{
					UpdateRoom(room);
				}
			});
			break;
		}
		default:
			UnityEngine.Debug.LogError("Unknown MarkupReplacementType!");
			break;
		}
	}

	private void OnDestroy()
	{
		Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		if (id == displayCard.Id && displayCard.ReplacementType == Chats.MarkupReplacementType.Username)
		{
			Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
			UpdateProfile(Profiles.Get(id));
		}
	}

	private void UpdateProfile(Profile profile)
	{
		button.Interactable = true;
		Images.GetProfileImage(profile).Then(delegate(Texture2D image)
		{
			if (this != null && displayCard.Id == (long)profile.Id && displayCard.ReplacementType == Chats.MarkupReplacementType.Username)
			{
				buttonImage.texture = image;
			}
		});
		nameText.text = $"@{profile.Username}";
	}

	private void UpdateRoom(RecNet.Room room)
	{
		button.Interactable = true;
		Images.GetRoomImage(room).Then(delegate(Texture2D image)
		{
			if (this != null && displayCard.Id == room.RoomId && displayCard.ReplacementType == Chats.MarkupReplacementType.Roomname)
			{
				buttonImage.texture = image;
			}
		});
		nameText.text = $"^{room.Name}";
	}

	[SkipRename]
	public void Button_Pressed()
	{
		switch (displayCard.ReplacementType)
		{
		case Chats.MarkupReplacementType.Username:
			if (playerDetailsFlow != null)
			{
				Profile profile = Profiles.Get(displayCard.Id);
				if (profile != null)
				{
					playerDetailsFlow.SetProfile(profile);
					watchUi.PushFlow(playerDetailsFlow);
				}
				else
				{
					button.Interactable = false;
				}
			}
			break;
		case Chats.MarkupReplacementType.Roomname:
			watchUi.ShowRoomDetails(displayCard.Id);
			break;
		default:
			UnityEngine.Debug.LogError("Unknown MarkupReplacementType!");
			break;
		}
	}
}
namespace RecRoom.AGUI
{
	public class ChatMessagePagedGrid : RecyclerPagedGrid<ChatMessage, ChatMessageButton>
	{
		[Serializable]
		public class ChatMessageSenderButtonClicked : UnityEvent<Profile>
		{
		}

		private struct DisplayChatMessage
		{
			public ChatMessage ChatMessage;

			public ChatMessageButton.ChatMessageDisplay ChatMessageDisplay;
		}

		public ChatMessageSenderButtonClicked OnChatMessageSenderButtonClicked;

		private ChatThread currentChatThread;

		private List<int> childToMessageMapping = new List<int>();

		private void Start()
		{
			if (OnChatMessageSenderButtonClicked == null)
			{
				return;
			}
			foreach (ChatMessageButton childUIElement in childUIElements)
			{
				ChatMessageButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate
				{
					OnChatMessageSenderButtonClicked.Invoke(innerChild.CurrentProfile);
				});
			}
		}

		public void SetChatMessages(ChatThread chatThread, IEnumerable<ChatMessage> chatMessages)
		{
			currentChatThread = chatThread;
			List<ChatMessage> list = chatMessages.OrderByDescending((ChatMessage cm) => cm.ChatMessageId).ToList();
			List<ChatMessage> list2 = new List<ChatMessage>();
			for (int num = 0; num < list.Count; num++)
			{
				if (!list[num].IsSystemMessage && (num - 1 < 0 || !list[num - 1].IsSystemMessage))
				{
					list2.Add(EmptySystemMessage());
				}
				list2.Add(list[num]);
			}
			SetAllActiveChildren(list2);
		}

		protected override void CalculateTotalPages()
		{
			childToMessageMapping.Clear();
			for (int i = 0; i < base.AllActiveChildren.Count; i++)
			{
				Relationship relationship = Relationships.Get(base.AllActiveChildren[i].SenderPlayerId);
				if (base.AllActiveChildren[i].TextMessageJson.HasDisplayCards && (relationship == null || !relationship.IsBlocked))
				{
					childToMessageMapping.Add(i);
					childToMessageMapping.Add(i);
					childToMessageMapping.Add(i);
				}
				else
				{
					childToMessageMapping.Add(i);
				}
			}
			base.TotalPages = ((childToMessageMapping.Count == 0) ? 1 : ((childToMessageMapping.Count + base.PageSize - 1) / base.PageSize));
		}

		protected override void CalculateAndActivateChildren()
		{
			int num = base.CurrentPage * base.PageSize;
			List<int> list = childToMessageMapping.SkipTake(num, base.PageSize).ToList();
			List<DisplayChatMessage> list2 = new List<DisplayChatMessage>();
			for (int i = 0; i < list.Count; i++)
			{
				if (i == 0 && num > 0 && childToMessageMapping[num - 1] == childToMessageMapping[num])
				{
					list2.Add(new DisplayChatMessage
					{
						ChatMessage = base.AllActiveChildren[list[i]],
						ChatMessageDisplay = ChatMessageButton.ChatMessageDisplay.MessageOnly
					});
				}
				else if (i == list.Count - 1 && childToMessageMapping.Count > num + base.PageSize && list[i] == childToMessageMapping[num + base.PageSize])
				{
					list2.Add(new DisplayChatMessage
					{
						ChatMessage = base.AllActiveChildren[list[i]],
						ChatMessageDisplay = ChatMessageButton.ChatMessageDisplay.DisplayCardsOnly
					});
				}
				else if (i == 0 || list[i] != list[i - 1])
				{
					list2.Add(new DisplayChatMessage
					{
						ChatMessage = base.AllActiveChildren[list[i]],
						ChatMessageDisplay = ChatMessageButton.ChatMessageDisplay.MessageAndDisplayCards
					});
				}
			}
			for (int j = 0; j < childUIElements.Count; j++)
			{
				bool flag = j < list2.Count;
				childUIElements[j].gameObject.SetActive(flag);
				if (flag)
				{
					SetChild(list2[j].ChatMessage, childUIElements[list2.Count - 1 - j], list2[j].ChatMessageDisplay);
				}
			}
		}

		private void SetChild(ChatMessage chatMessage, ChatMessageButton button, ChatMessageButton.ChatMessageDisplay displayMode)
		{
			button.SetChatMessage(currentChatThread, chatMessage, displayMode);
		}

		protected override void SetChild(ChatMessage chatMessage, ChatMessageButton button, int activeIndex)
		{
			UnityEngine.Debug.LogError("Called wrong SetChild method");
		}

		private ChatMessage EmptySystemMessage()
		{
			ChatMessage chatMessage = new ChatMessage();
			chatMessage.ThreadId = currentChatThread.ChatThreadId;
			chatMessage.SenderPlayerId = -5;
			chatMessage.IsSystemMessage = true;
			chatMessage.MessageJson = new Chats.MessageJson
			{
				Type = Chats.MessageContentType.Text
			};
			chatMessage.TextMessageJson = new Chats.TextMessageJson
			{
				FormattedText = string.Empty
			};
			return chatMessage;
		}
	}
	[RequireComponent(typeof(Button3D))]
	public class ChatThreadButton : UnityEngine.MonoBehaviour
	{
		[Serializable]
		public struct ChatThreadFormatting
		{
			public Font Font;

			public int ChatNameSize;

			public int MessagePreviewSize;

			public int TimeStampSize;

			public Color BackgroundColor;

			public int LineSpacing;
		}

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private Button3D openButton;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private Button3D playerProfileButton;

		[SerializeField]
		private Text chatName;

		[SerializeField]
		private Text messagePreview;

		[SerializeField]
		private Text timeStamp;

		[SerializeField]
		private UnityEngine.UI.Image bgImage;

		[SerializeField]
		private ChatThreadFormatting readFormatting;

		[SerializeField]
		private ChatThreadFormatting unreadFormatting;

		private long currentPreviewMsgId;

		private bool currentIsRead;

		private PlayerSpecificUIBehaviour[] playerWatchers = new PlayerSpecificUIBehaviour[0];

		public ChatThread CurrentChatThread { get; private set; }

		public int CurrentSenderId { get; private set; }

		public Button3D.OnButton3DClick OpenButtonAction => openButton.OnClick;

		public Button3D.OnButton3DClick ProfileButtonAction => playerProfileButton.OnClick;

		private void Awake()
		{
			playerWatchers = GetComponentsInChildren<PlayerSpecificUIBehaviour>();
		}

		private void OnEnable()
		{
			if (CurrentChatThread != null)
			{
				RefreshVisuals();
			}
		}

		public void SetChatThread(ChatThread chatThread)
		{
			if (CurrentChatThread == chatThread)
			{
				if (CurrentChatThread != null)
				{
					ChatMessage chatMessage = CurrentChatThread.Messages.First();
					bool flag = chatMessage.ChatMessageId == CurrentChatThread.LastReadMessageId;
					if (chatMessage.ChatMessageId != currentPreviewMsgId || currentIsRead != flag)
					{
						RefreshVisuals();
					}
				}
			}
			else
			{
				CurrentChatThread = chatThread;
				if (!(CurrentChatThread == null))
				{
					RefreshVisuals();
				}
			}
		}

		private void RefreshVisuals()
		{
			if (!base.gameObject.activeInHierarchy)
			{
				return;
			}
			ChatMessage chatMessage = CurrentChatThread.Messages.First();
			currentPreviewMsgId = chatMessage.ChatMessageId;
			string arg = ((chatMessage.SenderPlayerId == (long)Profiles.LocalProfile.Id) ? "You" : ((!chatMessage.IsSystemMessage) ? CurrentChatThread.GetPlayerName(chatMessage.SenderPlayerId) : string.Empty));
			currentIsRead = chatMessage.ChatMessageId == CurrentChatThread.LastReadMessageId;
			FormatVisuals((!currentIsRead) ? unreadFormatting : readFormatting);
			chatName.text = CurrentChatThread.GetChatName(forceRefresh: true);
			DateTime dateTime = chatMessage.TimeSent.ToLocalTime();
			if (dateTime.Day == DateTime.Now.Day)
			{
				timeStamp.text = dateTime.ToShortTimeString();
			}
			else
			{
				timeStamp.text = string.Format("{0} {1}", dateTime.ToString("MMM"), dateTime.Day);
			}
			PlayerSpecificUIBehaviour[] array = playerWatchers;
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in array)
			{
				playerSpecificUIBehaviour.SetPlayer(chatMessage.SenderPlayerId);
			}
			playerProfileButton.Interactable = !chatMessage.IsSystemMessage;
			CurrentSenderId = chatMessage.SenderPlayerId;
			if (chatMessage.MessageJson.Type == Chats.MessageContentType.Text)
			{
				if (chatMessage.IsSystemMessage)
				{
					messagePreview.text = chatMessage.TextMessageJson.FormattedText;
				}
				else
				{
					messagePreview.text = $"{arg}: {chatMessage.TextMessageJson.FormattedText}";
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Unknown message content type!");
			}
		}

		private void FormatVisuals(ChatThreadFormatting formatting)
		{
			chatName.font = formatting.Font;
			chatName.fontSize = formatting.ChatNameSize;
			chatName.lineSpacing = formatting.LineSpacing;
			messagePreview.font = formatting.Font;
			messagePreview.fontSize = formatting.MessagePreviewSize;
			messagePreview.lineSpacing = formatting.LineSpacing;
			timeStamp.font = formatting.Font;
			timeStamp.fontSize = formatting.TimeStampSize;
			timeStamp.lineSpacing = formatting.LineSpacing;
			bgImage.color = formatting.BackgroundColor;
		}
	}
