	public class ChooseFriendPagedGrid : RecyclerPagedGrid<Profile, ChooseFriendButton>
	{
		[Serializable]
		public class SelectedFriendsUpdated : UnityEvent<List<Profile>>
		{
		}

		public SelectedFriendsUpdated OnSelectedFriendsUpdatedEvent;

		private List<Profile> selectedProfiles = new List<Profile>();

		private bool trackSelectedProfiles = true;

		private void Start()
		{
			if (OnSelectedFriendsUpdatedEvent == null)
			{
				return;
			}
			foreach (ChooseFriendButton childUIElement in childUIElements)
			{
				ChooseFriendButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate(bool isOn)
				{
					if (trackSelectedProfiles)
					{
						Profile currentProfile = innerChild.CurrentProfile;
						if (isOn && !selectedProfiles.Contains(currentProfile))
						{
							selectedProfiles.Add(currentProfile);
							OnSelectedFriendsUpdatedEvent.Invoke(selectedProfiles);
						}
						else if (!isOn && selectedProfiles.Contains(currentProfile))
						{
							selectedProfiles.Remove(currentProfile);
							OnSelectedFriendsUpdatedEvent.Invoke(selectedProfiles);
						}
					}
					else
					{
						OnSelectedFriendsUpdatedEvent.Invoke(new List<Profile> { innerChild.CurrentProfile });
						innerChild.ForceOff();
					}
				});
			}
		}

		public void SetProfiles(IEnumerable<Profile> profiles, bool trackProfiles)
		{
			trackSelectedProfiles = trackProfiles;
			List<Profile> allActiveChildren = profiles.OrderBy(delegate(Profile profile)
			{
				PlayerPresence playerPresence = Presence.Get(profile.Id);
				return playerPresence == null || !playerPresence.AppearsOnlineToMe;
			}).ThenBy(delegate(Profile profile)
			{
				Relationship relationship = Relationships.Get(profile.Id);
				return relationship == null || !relationship.IsFavorited;
			}).ThenBy((Profile profile) => profile.DisplayName.GetDecrypted())
				.ThenBy((Profile profile) => profile.Username.GetDecrypted())
				.ToList();
			SetAllActiveChildren(allActiveChildren);
		}

		protected override void SetChild(Profile profile, ChooseFriendButton button, int activeIndex)
		{
			button.SetProfile(profile, selectedProfiles.Contains(profile));
		}
	}
}
public class FavoriteConditionalButton : PlayerBasedConditionalButton<ToggleButton3D>
{
	public enum FavoriteButtonState
	{
		Disabled,
		Favorite,
		Unfavorite
	}

	[SerializeField]
	private Tooltip tooltip;

	protected override void UpdatePlayerBasedButtonState()
	{
		base.ButtonState = 0;
		Relationship relationship = Relationships.Get(playerWatcher.PlayerId.Value);
		if (relationship != null && relationship.IsFriend)
		{
			base.ButtonState = ((!relationship.IsFavorited) ? 1 : 2);
		}
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		switch ((FavoriteButtonState)base.ButtonState)
		{
		case FavoriteButtonState.Unfavorite:
			UIHelper.SafeSetText(base.LabelText, "Unfavorite");
			base.Button.IsOn = true;
			tooltip.Message = "Unfavorite this player";
			break;
		case FavoriteButtonState.Favorite:
			UIHelper.SafeSetText(base.LabelText, "Favorite");
			base.Button.IsOn = false;
			tooltip.Message = "Favorite this player";
			break;
		case FavoriteButtonState.Disabled:
			UIHelper.SafeSetText(base.LabelText, "Favorite");
			base.Button.IsOn = false;
			tooltip.Message = "You can only favorite friends";
			break;
		}
	}

	protected override void RunButtonAction()
	{
		switch ((FavoriteButtonState)base.ButtonState)
		{
		case FavoriteButtonState.Favorite:
			Relationships.FavoritePlayer(playerWatcher.PlayerId.Value, delegate(string error)
			{
				if (string.IsNullOrEmpty(error))
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Favorited!", 3f);
					base.ButtonState = 2;
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Error favoriting", 3f);
					base.Button.IsOn = false;
					UnityEngine.Debug.LogError("Error favoriting player: " + error);
				}
			});
			break;
		case FavoriteButtonState.Unfavorite:
			Relationships.UnfavoritePlayer(playerWatcher.PlayerId.Value, delegate(string error)
			{
				if (string.IsNullOrEmpty(error))
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Unfavorited", 3f);
					base.ButtonState = 1;
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Minor, "Error unfavoriting", 3f);
					base.Button.IsOn = true;
					UnityEngine.Debug.LogError("Error unfavoriting player: " + error);
				}
			});
			break;
		}
		UpdateButtonState();
	}
}
public class GoToPlayerEventConditionalButton : ConditionalButton<Button3D>
{
	public enum GoToPlayerEventButtonState
	{
		Disabled,
		Join,
		DoesNotExist,
		AlreadyInEvent,
		NotStarted,
		AlreadyFinished
	}

	[SerializeField]
	private bool showCountdown;

	[FormerlySerializedAs("showEventDetailsIfDisabled")]
	[SerializeField]
	private bool goToEventDetailsIfDisabled;

	private PlayerEvent targetEvent;

	private IDisposable updateTimeToEventToken;

	private GoToPlayerEventButtonState? _forcedButtonState;

	public GoToPlayerEventButtonState? ForcedButtonState
	{
		get
		{
			return _forcedButtonState;
		}
		set
		{
			GoToPlayerEventButtonState? forcedButtonState = _forcedButtonState;
			if (forcedButtonState.GetValueOrDefault() != value.GetValueOrDefault() || (forcedButtonState.HasValue ^ value.HasValue))
			{
				_forcedButtonState = value;
				UpdateButtonState();
			}
		}
	}

	public void SetTarget(PlayerEvent playerEvent)
	{
		targetEvent = playerEvent;
		UpdateButtonState();
		UpdateUIForNewButtonState();
	}

	protected override void UpdateButtonState()
	{
		if (ForcedButtonState.HasValue)
		{
			base.ButtonState = (int)ForcedButtonState.Value;
		}
		else if (SingletonMonoBehaviour<SessionManager>.Instance.LeaveSceneStarted)
		{
			base.ButtonState = 0;
		}
		else if (targetEvent == null)
		{
			base.ButtonState = 2;
		}
		else if (!targetEvent.IsHappeningNow && (!targetEvent.IsOrganizedByLocalPlayer || (targetEvent.StartTime - DateTime.UtcNow).Hours >= 1))
		{
			base.ButtonState = 4;
		}
		else if (GameSessions.LocalGameSession.PlayerEventId.HasValue && GameSessions.LocalGameSession.PlayerEventId.Value == targetEvent.PlayerEventId)
		{
			base.ButtonState = 3;
		}
		else
		{
			base.ButtonState = 1;
		}
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		switch ((GoToPlayerEventButtonState)base.ButtonState)
		{
		case GoToPlayerEventButtonState.DoesNotExist:
			UIHelper.SafeSetText(base.LabelText, "No Event");
			break;
		case GoToPlayerEventButtonState.NotStarted:
			if (showCountdown)
			{
				if (updateTimeToEventToken != null)
				{
					updateTimeToEventToken.Dispose();
				}
				TimeSpan timeSpan = targetEvent.StartTime - DateTime.UtcNow;
				if (timeSpan.Days > 0)
				{
					UIHelper.SafeSetText(base.LabelText, $"Event Starts In\n{timeSpan.Days} days {timeSpan.Hours} hours");
				}
				else
				{
					updateTimeToEventToken = this.Update1hz(UpdateTimeToEventRoutine);
				}
			}
			break;
		case GoToPlayerEventButtonState.AlreadyFinished:
			UIHelper.SafeSetText(base.LabelText, "Event Finished");
			break;
		case GoToPlayerEventButtonState.AlreadyInEvent:
			UIHelper.SafeSetText(base.LabelText, "In Event");
			break;
		default:
			UIHelper.SafeSetText(base.LabelText, "Go To Event");
			break;
		}
	}

	private void UpdateTimeToEventRoutine(float deltaTime)
	{
		if (targetEvent.IsHappeningNow)
		{
			UpdateButtonState();
			updateTimeToEventToken.Dispose();
		}
		else
		{
			UIHelper.SafeSetText(base.LabelText, string.Format("Event Starts In\n{0}", (targetEvent.StartTime - DateTime.UtcNow).ToString("hh\\:mm\\:ss")));
		}
	}

	protected override void RunButtonAction()
	{
		if (base.ButtonState == 1)
		{
			SingletonMonoBehaviour<SessionManager>.Instance.RunGoToPlayerEvent(targetEvent, SessionManager.LoadSceneSources.EVENT_DIRECT_GOTO);
		}
		else if (goToEventDetailsIfDisabled)
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowEventDetails(targetEvent);
		}
	}

	protected override bool IsInteractable()
	{
		GoToPlayerEventButtonState goToPlayerEventButtonState = (GoToPlayerEventButtonState)base.ButtonState;
		return base.IsInteractable() && (goToEventDetailsIfDisabled || (goToPlayerEventButtonState != GoToPlayerEventButtonState.DoesNotExist && goToPlayerEventButtonState != GoToPlayerEventButtonState.AlreadyInEvent && goToPlayerEventButtonState != GoToPlayerEventButtonState.NotStarted && goToPlayerEventButtonState != GoToPlayerEventButtonState.AlreadyFinished));
	}
}
