[RequireComponent(typeof(PlayerSpecificUIBehaviour))]
public class PlayerButtonPanelColor : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private UnityEngine.UI.Image panel;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private PlayerSpecificUIBehaviour playerWatcher;

	[Header("Colors")]
	[SerializeField]
	private Color onlineDefaultColor;

	[SerializeField]
	private Color offlineDefaultColor;

	[SerializeField]
	private Color onlineFavoriteColor;

	[SerializeField]
	private Color offlineFavoriteColor;

	private void Awake()
	{
		playerWatcher = GetComponent<PlayerSpecificUIBehaviour>();
		playerWatcher.PlayerIdUpdated += PlayerIdUpdated;
	}

	private void OnDestroy()
	{
		if (playerWatcher != null)
		{
			playerWatcher.PlayerIdUpdated -= PlayerIdUpdated;
		}
	}

	private void OnEnable()
	{
		PlayerIdUpdated();
	}

	private void PlayerIdUpdated()
	{
		Relationship relationship = ((!playerWatcher.PlayerId.HasValue) ? null : Relationships.Get(playerWatcher.PlayerId.Value));
		PlayerPresence playerPresence = ((!playerWatcher.PlayerId.HasValue) ? null : Presence.Get(playerWatcher.PlayerId.Value));
		if (playerPresence != null && playerPresence.AppearsOnlineToMe)
		{
			if (relationship != null && relationship.IsFavorited)
			{
				panel.color = onlineFavoriteColor;
			}
			else
			{
				panel.color = onlineDefaultColor;
			}
		}
		else if (relationship != null && relationship.IsFavorited)
		{
			panel.color = offlineFavoriteColor;
		}
		else
		{
			panel.color = offlineDefaultColor;
		}
	}
}
public class PlayerClubText : PlayerSpecificText
{
	private IPromise<RecNet.Group> currPromise;

	protected override void OnDestroy()
	{
		base.OnDestroy();
		currPromise = null;
	}

	protected override void SetText(Profile currentProfile)
	{
		if (!(base.Text != null))
		{
			return;
		}
		base.Text.text = null;
		base.Text.enabled = false;
		currPromise = null;
		if (currentProfile == null)
		{
			return;
		}
		IPromise<RecNet.Group> promise = Groups.GetPrimaryGroupMembership(currentProfile.Id);
		currPromise = promise;
		currPromise.Then(delegate(RecNet.Group group)
		{
			if (currPromise == promise && group != null && group.BanStatus == GroupBanStatus.GoodStanding)
			{
				base.Text.enabled = true;
				base.Text.text = $"Club: {group.Name}";
			}
		});
	}
}
namespace AGUI.StackedUI
{
	public class PlayerEventButton : UnityEngine.MonoBehaviour
	{
		private const int EVENT_IMAGE_WIDTH = 512;

		public PlayerEvent PlayerEvent;

		[Header("UI Elements")]
		[SerializeField]
		private UnityEngine.UI.Image rsvpImage;

		[SerializeField]
		private Text attendeeCountText;

		[SerializeField]
		private Text startTimeText;

		[SerializeField]
		private Text eventNameText;

		[SerializeField]
		private PlayerEventImage eventImage;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private GoToPlayerEventConditionalButton goToPlayerEventButton;

		[Header("Active vs Inactive Event UI")]
		[SerializeField]
		private GameObject[] showForActiveEvents;

		[SerializeField]
		private GameObject[] showForInactiveEvents;

		[Header("Response Sprites")]
		[SerializeField]
		private Sprite attendingSprite;

		[SerializeField]
		private Sprite maybeSprite;

		[SerializeField]
		private Sprite myEventSprite;

		public void SetPlayerEvent(PlayerEvent playerEvent)
		{
			if (playerEvent == null)
			{
				UnityEngine.Debug.LogError("Player event cannot be null");
				return;
			}
			PlayerEvent = playerEvent;
			if (PlayerEvent == null)
			{
				return;
			}
			attendeeCountText.text = PlayerEvent.AttendeeCount.ToString();
			startTimeText.text = PlayerEvent.StartTime.ToLocalTime().ToString("h:mm tt");
			eventNameText.text = PlayerEvent.Name;
			rsvpImage.sprite = null;
			if (PlayerEvent.IsOrganizedByLocalPlayer)
			{
				rsvpImage.sprite = myEventSprite;
			}
			else
			{
				switch (RecNet.PlayerEvents.GetLocalPlayerAttendingStatus(PlayerEvent.PlayerEventId))
				{
				case PlayerEventResponseType.Yes:
					rsvpImage.sprite = attendingSprite;
					break;
				case PlayerEventResponseType.Interested:
					rsvpImage.sprite = maybeSprite;
					break;
				}
			}
			rsvpImage.enabled = rsvpImage.sprite != null;
			goToPlayerEventButton.SetTarget(PlayerEvent);
			eventImage.SetPlayerEvent(PlayerEvent);
			bool flag = false;
			if (showForActiveEvents != null)
			{
				for (int i = 0; i < showForActiveEvents.Length; i++)
				{
					showForActiveEvents[i].SetActive(flag);
				}
			}
			if (showForInactiveEvents != null)
			{
				for (int j = 0; j < showForInactiveEvents.Length; j++)
				{
					showForInactiveEvents[j].SetActive(!flag);
				}
			}
		}

		[SkipRename]
		public void Button_Info()
		{
			if (PlayerEvent != null)
			{
				Player.LocalPlayer.PlayerUI.WatchMenu.ShowEventDetails(PlayerEvent);
			}
		}
	}
