public class PlayerEventGuestsPagedGrid : ProfileIdPagedGrid
{
	private long currentPlayerEventId;

	private List<PlayerEventResponse> cachedResponses = new List<PlayerEventResponse>();

	protected override void Awake()
	{
		base.Awake();
		RecNet.PlayerEvents.PlayerEventResponseChanged += PlayerEvents_PlayerEventResponseChanged;
		RecNet.PlayerEvents.PlayerEventResponseDeleted += PlayerEvents_PlayerEventResponseDeleted;
	}

	private void OnDestroy()
	{
		RecNet.PlayerEvents.PlayerEventResponseChanged -= PlayerEvents_PlayerEventResponseChanged;
		RecNet.PlayerEvents.PlayerEventResponseDeleted -= PlayerEvents_PlayerEventResponseDeleted;
	}

	private void PlayerEvents_PlayerEventResponseDeleted(PlayerEvent playerEvent, PlayerEventResponse response)
	{
		if (playerEvent.PlayerEventId != currentPlayerEventId)
		{
			return;
		}
		PlayerEventResponse playerEventResponse = cachedResponses.FirstOrDefault((PlayerEventResponse r) => r.PlayerEventResponseId == response.PlayerEventResponseId);
		if (playerEventResponse != null)
		{
			cachedResponses.Remove(playerEventResponse);
			SetProfileIds(cachedResponses.Select((PlayerEventResponse r) => r.PlayerId), resetPage: false);
		}
	}

	private void PlayerEvents_PlayerEventResponseChanged(PlayerEvent playerEvent, PlayerEventResponse response)
	{
		if (playerEvent.PlayerEventId == currentPlayerEventId && cachedResponses.FirstOrDefault((PlayerEventResponse r) => r.PlayerEventResponseId == response.PlayerEventResponseId) == null)
		{
			cachedResponses.Add(response);
			SetProfileIds(cachedResponses.Select((PlayerEventResponse r) => r.PlayerId), resetPage: false);
		}
	}

	public void SetResponses(List<PlayerEventResponse> responses, bool resetPage)
	{
		cachedResponses = responses;
		currentPlayerEventId = ((responses.Count <= 0) ? 0 : responses[0].PlayerEventId);
		SetProfileIds(responses.Select((PlayerEventResponse r) => r.PlayerId), resetPage);
	}

	protected override void SetChild(int profileId, PlayerButton button, int activeIndex)
	{
		button.SetProfile(Profiles.Get(profileId));
		PlayerEventGuestButton playerEventGuestButton = button as PlayerEventGuestButton;
		if (playerEventGuestButton != null)
		{
			playerEventGuestButton.SetResponse(cachedResponses.FirstOrDefault((PlayerEventResponse r) => r.PlayerId == profileId));
		}
	}
}
