namespace AGUI.StackedUI
{
	public class PlayerRoomRoleButton : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private Button3D profileButton;

		public Slider3D PartialRoleSlider;

		public Slider3D FullRoleSlider;

		[SerializeField]
		private Text roleText;

		private int targetProfileId;

		private RoomDetails targetRoom;

		private RecNet.RoomRole targetRole;

		private RecNet.RoomRole localRole;

		public Profile TargetProfile { get; private set; }

		public Button3D.OnButton3DClick ButtonAction => profileButton.OnClick;

		public void SetRoomAndPlayerId(RoomDetails room, long playerId)
		{
			targetRoom = room;
			targetRole = targetRoom.GetPlayerRole((int)playerId);
			localRole = targetRoom.GetPlayerRole((int)(long)Profiles.LocalProfile.Id);
			targetProfileId = (int)playerId;
			TargetProfile = Profiles.Get(playerId);
			PlayerSpecificUIBehaviour[] componentsInChildren = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in componentsInChildren)
			{
				playerSpecificUIBehaviour.SetPlayer(playerId);
			}
			UpdateButtonUI();
		}

		private void UpdateButtonUI()
		{
			if (targetRoom == null)
			{
				return;
			}
			DisableAllRoleVisuals();
			bool flag = targetProfileId == (long)Profiles.LocalProfile.Id;
			Slider3D slider3D = null;
			if (targetRole != RecNet.RoomRole.Creator && (flag || targetRole < localRole))
			{
				switch (localRole)
				{
				case RecNet.RoomRole.Creator:
					slider3D = FullRoleSlider;
					break;
				case RecNet.RoomRole.CoOwner:
					slider3D = ((!flag) ? PartialRoleSlider : FullRoleSlider);
					break;
				case RecNet.RoomRole.Host:
					slider3D = ((!flag) ? null : PartialRoleSlider);
					break;
				}
			}
			if (slider3D != null)
			{
				slider3D.transform.parent.gameObject.SetActive(value: true);
				slider3D.value = (float)targetRole;
			}
			else
			{
				roleText.gameObject.SetActive(value: true);
				roleText.text = targetRole.ToString();
			}
		}

		private void DisableAllRoleVisuals()
		{
			PartialRoleSlider.transform.parent.gameObject.SetActive(value: false);
			FullRoleSlider.transform.parent.gameObject.SetActive(value: false);
			roleText.gameObject.SetActive(value: false);
		}
	}
