			{
				PlayerRoomRoleButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate
				{
					ShowDetailsEvent.Invoke(innerChild.TargetProfile);
				});
				innerChild.FullRoleSlider.OnSlider3DReleased.AddListener(delegate(float value)
				{
					if (innerChild.FullRoleSlider.Interactable)
					{
						UpdateRoleAction.Invoke(targetRoomDetails, innerChild.TargetProfile, (RecNet.RoomRole)Mathf.Round(value), innerChild.FullRoleSlider);
					}
				});
				innerChild.PartialRoleSlider.OnSlider3DReleased.AddListener(delegate(float value)
				{
					if (innerChild.PartialRoleSlider.Interactable)
