public class ProfileIdPagedGrid : RecyclerPagedGrid<int, PlayerButton>
{
	[SerializeField]
	private string noResultsString = "No Results :(";

	[SerializeField]
	private FoundPlayerResult.ShowDetailsEvent ShowDetailsEvent;

	private bool hasRegisteredEvents;

	private List<int> idsOfProfilesToDownload = new List<int>();

	private List<int> cachedProfiles = new List<int>();

	private bool isLoading;

	private int cachedCurrentPage;

	private void Start()
	{
		if (ShowDetailsEvent != null)
		{
			foreach (PlayerButton childUIElement in childUIElements)
			{
				PlayerButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate
				{
					ShowDetailsEvent.Invoke(innerChild.CurrentProfile);
				});
			}
		}
		if (!hasRegisteredEvents)
		{
			Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			base.PageChangeEvent += ProfileIdPagedGrid_PageChangeEvent;
			hasRegisteredEvents = true;
		}
	}

	private void OnDestroy()
	{
		Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
		base.PageChangeEvent -= ProfileIdPagedGrid_PageChangeEvent;
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		if (idsOfProfilesToDownload.Contains((int)id))
		{
			idsOfProfilesToDownload.Remove((int)id);
			if (idsOfProfilesToDownload.Count == 0)
			{
				isLoading = false;
				SetProfileIds(cachedProfiles, resetPage: false);
				SetCurrentPage(cachedCurrentPage);
				cachedProfiles.Clear();
			}
		}
	}

	private void ProfileIdPagedGrid_PageChangeEvent()
	{
		if (!isLoading)
		{
			idsOfProfilesToDownload.Clear();
		}
	}

	public override void SetLoading()
	{
		isLoading = true;
		cachedCurrentPage = base.CurrentPage;
		cachedProfiles = base.AllActiveChildren;
		base.SetLoading();
	}

	public void SetProfileIds(IEnumerable<int> profileIds, bool resetPage)
	{
		SetAllActiveChildren(profileIds, resetPage);
	}

	protected override void ActivateCurrentPageActiveChildren(IList<int> activeChildren)
	{
		if (activeChildren.Count == 0)
		{
			UIHelper.SafeSetText(emptyDisplayText, noResultsString);
		}
		for (int i = 0; i < childUIElements.Count; i++)
		{
			if (i < activeChildren.Count && Profiles.Get(activeChildren[i]) == null)
			{
				idsOfProfilesToDownload.Add(activeChildren[i]);
			}
		}
		if (idsOfProfilesToDownload.Count == 0 || activeChildren.Count == 0)
		{
			base.ActivateCurrentPageActiveChildren(activeChildren);
			return;
		}
		if (!hasRegisteredEvents)
		{
			Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
			base.PageChangeEvent += ProfileIdPagedGrid_PageChangeEvent;
			hasRegisteredEvents = true;
		}
		SetLoading();
	}

	protected override void SetChild(int profileId, PlayerButton button, int activeIndex)
	{
		button.SetProfile(Profiles.Get(profileId));
	}
}
