	public class RoomButtonPagedGrid : RecyclerPagedGrid<RecNet.Room, RoomButton>
	{
		private Dictionary<long, int> friendCountInRooms = new Dictionary<long, int>();

		private List<string> searchTagsUsed;

		private string noResults;

		protected override void Awake()
		{
			base.Awake();
			noResults = ((!(emptyDisplayText != null)) ? string.Empty : emptyDisplayText.text);
		}

		private void OnEnable()
		{
			friendCountInRooms = RecNet.Rooms.GetFriendCountInRooms();
		}

		protected override void SetChild(RecNet.Room room, RoomButton uiElement, int index)
		{
			friendCountInRooms.TryGetValue(room.RoomId, out var value);
			uiElement.SetRoom(room, value, searchTagsUsed);
		}

		public void SetRooms(IEnumerable<RecNet.Room> rooms, List<string> searchTagsUsed)
		{
			if (rooms != null)
			{
				this.searchTagsUsed = searchTagsUsed;
				UIHelper.SafeSetText(emptyDisplayText, noResults);
				SetAllActiveChildren(rooms);
			}
		}

		public void AddRoomToCurrentListIfNotPresent(RecNet.Room roomToAdd)
		{
			if (roomToAdd != null && !base.AllActiveChildren.Any((RecNet.Room r) => r.RoomId == roomToAdd.RoomId))
			{
				List<RecNet.Room> allActiveChildren = base.AllActiveChildren;
				if (allActiveChildren.Count > 0)
				{
					allActiveChildren.Insert(0, roomToAdd);
				}
				else
				{
					allActiveChildren.Add(roomToAdd);
				}
				SetRooms(allActiveChildren, searchTagsUsed);
			}
		}

		public RoomButton GetFirstEnabledButton()
		{
			if (childUIElements.Count <= 0 || !childUIElements[0].isActiveAndEnabled)
			{
				return null;
			}
			return childUIElements[0];
		}

		public int FindPageIndexOfRoom(string roomName)
		{
			int result = -1;
			int num = -1;
			for (int i = 0; i < base.AllActiveChildren.Count; i++)
			{
				if (base.AllActiveChildren[i] != null && base.AllActiveChildren[i].Name == roomName)
				{
					num = i;
					break;
				}
			}
			if (num >= 0)
			{
				result = num / base.PageSize;
			}
			return result;
		}
	}
}
