public class AddRemovePlayerRoomRoleConditionalButton : ConditionalButton<ToggleButton3D>
{
	public delegate void OnReceivedReponse(RecNet.Rooms.CreateModifyRoomResponse response);

	private enum ButtonStates
	{
		Invalid,
		SetRole,
		InviteRole,
		InvitePendingRole,
		RemoveRole,
		ViewRole,
		RoleChangePending
	}

	public static OnReceivedReponse OnReceivedReponseEvent;

	private bool requestPending;

	private long _currentPlayerId = -1L;

	private RecNet.RoomRole _modifyingRoomRole = RecNet.RoomRole.CoOwner;

	protected override void OnEnable()
	{
		base.OnEnable();
		RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomUpdated);
	}

	private void OnDisable()
	{
		RecNet.Rooms.OnLocalRoomUpdated -= new Action(OnLocalRoomUpdated);
	}

	private void OnDestroy()
	{
		RecNet.Rooms.OnLocalRoomUpdated -= new Action(OnLocalRoomUpdated);
	}

	private void OnLocalRoomUpdated()
	{
		UpdateButton();
	}

	public void SetProfileIdAndRole(long profileId, RecNet.RoomRole roomRole)
	{
		_currentPlayerId = profileId;
		_modifyingRoomRole = roomRole;
		UpdateButton();
	}

	protected override void UpdateButtonState()
	{
		if (requestPending)
		{
			base.ButtonState = 6;
			return;
		}
		if (_currentPlayerId < 0)
		{
			base.ButtonState = 0;
			return;
		}
		if (Player.LocalPlayer.PlayerId != _currentPlayerId)
		{
			RecNet.RoomRole localPlayerRole = RecNet.Rooms.LocalRoomDetails.LocalPlayerRole;
			RecNet.RoomRole playerRole = RecNet.Rooms.LocalRoomDetails.GetPlayerRole((int)_currentPlayerId);
			if (localPlayerRole <= playerRole)
			{
				base.ButtonState = 5;
				return;
			}
			if (localPlayerRole <= _modifyingRoomRole)
			{
				base.ButtonState = 5;
				return;
			}
		}
		RecNet.RoomRole playerRole2 = RecNet.Rooms.LocalRoomDetails.GetPlayerRole((int)_currentPlayerId);
		if (_modifyingRoomRole == RecNet.RoomRole.CoOwner)
		{
			switch (RecNet.Rooms.LocalRoomDetails.GetPlayerCoOwnerPermission((int)_currentPlayerId))
			{
			case RoomPermissionValue.True:
				base.ButtonState = 4;
				break;
			case RoomPermissionValue.False:
				base.ButtonState = 2;
				break;
			case RoomPermissionValue.Invited:
				base.ButtonState = 3;
				break;
			default:
				base.ButtonState = 6;
				break;
			}
		}
		else
		{
			base.ButtonState = ((playerRole2 != _modifyingRoomRole) ? 1 : 4);
		}
	}

	protected override bool IsInteractable()
	{
		ButtonStates buttonStates = (ButtonStates)base.ButtonState;
		return base.IsInteractable() && (buttonStates == ButtonStates.SetRole || buttonStates == ButtonStates.RemoveRole || buttonStates == ButtonStates.InviteRole);
	}

	protected override void UpdateUIForNewButtonState()
	{
		base.UpdateUIForNewButtonState();
		ButtonStates buttonStates = (ButtonStates)base.ButtonState;
		switch (buttonStates)
		{
		case ButtonStates.SetRole:
		{
			RecNet.RoomRole playerRole2 = RecNet.Rooms.LocalRoomDetails.GetPlayerRole((int)_currentPlayerId);
			base.LabelText.text = ((playerRole2 == RecNet.RoomRole.Guest) ? "Add" : ((_modifyingRoomRole <= playerRole2) ? "Demote" : "Promote"));
			break;
		}
		case ButtonStates.RemoveRole:
			base.LabelText.text = "Remove";
			break;
		case ButtonStates.InviteRole:
			base.LabelText.text = "Invite";
			break;
		case ButtonStates.InvitePendingRole:
			base.LabelText.text = "Invited";
			break;
		case ButtonStates.RoleChangePending:
			base.LabelText.text = "Pending";
			break;
		case ButtonStates.ViewRole:
		{
			RecNet.RoomRole playerRole = RecNet.Rooms.LocalRoomDetails.GetPlayerRole((int)_currentPlayerId);
			base.LabelText.text = playerRole.ToString();
			break;
		}
		}
		base.Button.IsOn = buttonStates == ButtonStates.RemoveRole;
	}

	protected override void RunButtonAction()
	{
		ButtonStates buttonStates = (ButtonStates)base.ButtonState;
		if (buttonStates == ButtonStates.Invalid || buttonStates == ButtonStates.RoleChangePending)
		{
			return;
		}
		RoomPermissionValue? isCoOwner = null;
		RoomPermissionValue? isHost = null;
		if (_modifyingRoomRole == RecNet.RoomRole.CoOwner)
		{
			isCoOwner = ButtonStateToRoomPermissionValue(buttonStates);
		}
		else if (_modifyingRoomRole == RecNet.RoomRole.Host)
		{
			isHost = ButtonStateToRoomPermissionValue(buttonStates);
		}
		requestPending = true;
		UpdateButton();
		RecNet.Rooms.ModifyPermission(RecNet.Rooms.LocalRoomDetails.Room.RoomId, (int)_currentPlayerId, isCoOwner, isHost, delegate(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			requestPending = false;
			UpdateButton();
			if (response != null && OnReceivedReponseEvent != null)
			{
				OnReceivedReponseEvent(response);
			}
		});
	}

	private RoomPermissionValue ButtonStateToRoomPermissionValue(ButtonStates buttonState)
	{
		return buttonState switch
		{
			ButtonStates.SetRole => RoomPermissionValue.True, 
			ButtonStates.InviteRole => RoomPermissionValue.Invited, 
			ButtonStates.RemoveRole => RoomPermissionValue.False, 
			_ => throw new NotImplementedException($"Cannot convert {buttonState} to a RoomPermissionValue."), 
		};
	}
}
public class AddRemovePlayersRoomRolesDialog : ConfirmUIDialog<RecRoom.Systems.PlayerRoles.RoomRole>
{
	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private AddRemovePlayerRoomRolePagedGrid pagedGrid;

	[SerializeField]
	private TextMeshProUGUI infotext;

	private RecNet.RoomRole currentRoomRole;

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponseEvent = (AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponse)Delegate.Combine(AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponseEvent, new AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponse(AddRemoveButtonReceievedResponse));
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponseEvent = (AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponse)Delegate.Remove(AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponseEvent, new AddRemovePlayerRoomRoleConditionalButton.OnReceivedReponse(AddRemoveButtonReceievedResponse));
	}

	private void AddRemoveButtonReceievedResponse(RecNet.Rooms.CreateModifyRoomResponse response)
	{
		SetInfoText(response.Result.ToString());
	}

	public override IPromise<ConfirmDialogResponses> ShowDialog(RecRoom.Systems.PlayerRoles.RoomRole roomRole)
	{
		if (roomRole.RoleId == RoomRoleId.AG_CREATOR)
		{
			UnityEngine.Debug.LogError("Error: Cannot change creator role");
			return new CompletedPromise<ConfirmDialogResponses>(ConfirmDialogResponses.Negative);
		}
		if (roomRole.RoleId == RoomRoleId.AG_COOWNER)
		{
			currentRoomRole = RecNet.RoomRole.CoOwner;
		}
		else if (roomRole.RoleId == RoomRoleId.AG_HOST)
		{
			currentRoomRole = RecNet.RoomRole.Host;
		}
		else
		{
			currentRoomRole = RecNet.RoomRole.Guest;
		}
		ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
		if (componentInChildren != null)
		{
			componentInChildren.Title = $"Editing Role: {roomRole.RoleName}";
		}
		IEnumerable<long> profileIds = (from id in Player.All.Select((Player p) => p.PlayerId).Concat(from r in Relationships.GetAll()
				where r.IsFriend && !r.IsBlocked
				select Profiles.Get(r.PlayerID) into p
				where p != null && !p.IsJunior()
				select p.Id.GetDecrypted()).Concat(((IEnumerable<int>)RecNet.Rooms.LocalRoomDetails.HostIds).Select((Func<int, long>)((int id) => id)))
				.Concat(((IEnumerable<int>)RecNet.Rooms.LocalRoomDetails.CoOwnerIds).Select((Func<int, long>)((int id) => id)))
			where id != (long)Profiles.LocalProfile.Id
			select id).Distinct();
		pagedGrid.SetProfileIdsAndRole(profileIds, currentRoomRole);
		SetInfoText(string.Empty);
		return base.ShowDialog();
	}

	private void SetInfoText(string info)
	{
		infotext.text = info;
	}
}
[Serializable]
public struct AllowedPlayerTypesSettings
{
	[SerializeField]
	private ToggleButton3D vrWalkAllowedToggle;

	[SerializeField]
	private ToggleButton3D vrTeleportAllowedToggle;

	[SerializeField]
	private ToggleButton3D screensAllowedToggle;

	public bool ScreensSupported => screensAllowedToggle.IsOn;

	public bool Interactable
	{
		set
		{
			vrWalkAllowedToggle.Interactable = value;
			vrTeleportAllowedToggle.Interactable = value;
			screensAllowedToggle.Interactable = value;
		}
	}

	public bool AllowScreens => screensAllowedToggle.IsOn;

	public bool AllowVRWalk => vrWalkAllowedToggle.IsOn;

	public bool AllowVRTeleport => vrTeleportAllowedToggle.IsOn;

	public bool AllAllowed => AllowScreens && AllowVRWalk && AllowVRTeleport;

	public void UpdateToggles(RecNet.Room roomToMatch)
	{
		vrWalkAllowedToggle.IsOn = roomToMatch.SupportsWalkVR;
		vrTeleportAllowedToggle.IsOn = roomToMatch.SupportsTeleportVR;
		screensAllowedToggle.IsOn = roomToMatch.SupportsScreens;
	}

	public void UpdateVRWalkToggle(bool isOn)
	{
		vrWalkAllowedToggle.IsOn = isOn;
	}

	public void UpdateVRTeleportToggle(bool isOn)
	{
		vrTeleportAllowedToggle.IsOn = isOn;
	}

	public void UpdateScreenToggle(bool isOn)
	{
		screensAllowedToggle.IsOn = isOn;
	}

	public List<LocalPlayerController.PlayerType> GetAllowedTypesFromToggles()
	{
		List<LocalPlayerController.PlayerType> list = new List<LocalPlayerController.PlayerType>(3);
		if (vrWalkAllowedToggle.IsOn)
		{
			list.Add(LocalPlayerController.PlayerType.VR_WALK);
		}
		if (vrTeleportAllowedToggle.IsOn)
		{
			list.Add(LocalPlayerController.PlayerType.VR_TELEPORT);
		}
		if (screensAllowedToggle.IsOn)
		{
			list.Add(LocalPlayerController.PlayerType.SCREEN);
		}
		return list;
	}
}
namespace AGUI.StackedUI
{
	public class BrowseRoomsScreen : WatchUIFlow
	{
		private enum DisplayMode
		{
			None,
			Hot,
			Live,
			Search,
			Favorites,
			DoorSelect,
			Featured
		}

		[Header("Radio Buttons")]
		[SerializeField]
		private GameObject contextRow;

		[SerializeField]
		private RadioButton3D featuredRadioButton;

		[SerializeField]
		private RadioButton3D hotRadioButton;

		[SerializeField]
		[FormerlySerializedAs("forYouRadioButton")]
		private RadioButton3D liveRadioButton;

		[SerializeField]
		private RadioButton3D favoritesRadioButton;

		[SerializeField]
		private RadioButton3D searchRadioButton;

		[Header("Subscreens")]
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private SubscreenControl subscreenControl;

		[SerializeField]
		private Subscreen featuredSubscreen;

		[SerializeField]
		private Subscreen roomsSubscreen;

		[Header("Search Settings")]
		[SerializeField]
		private GameObject searchRow;

		[SerializeField]
		private InputField3D searchField;

		[SerializeField]
		private Button3D searchButton;

		[Header("Tags")]
		[SerializeField]
		private GameObject tagFilterContainer;

		[SerializeField]
		private GameObject tagButtonsParent;

		[SerializeField]
		private Sprite agTagSprite;

		[Header("Featured")]
		[SerializeField]
		private RoomButtonPagedGrid rroRoomsGrid;

		[SerializeField]
		private RoomButtonPagedGrid communityRoomsGrid;

		[Header("Rooms Grid")]
		[SerializeField]
		private RoomButtonPagedGrid roomsGrid;

		[SerializeField]
		private int defaultGridSize = 8;

		[SerializeField]
		private int searchGridSize = 4;

		[SerializeField]
		private int hotGridSize = 6;

		[SerializeField]
		private int largeGridSize = 15;

		[SerializeField]
		private int largeSearchGridSize = 10;

		[SerializeField]
		private int largeHotGridSize = 12;

		private ToggleButton3D[] tagToggles = new ToggleButton3D[0];

		private List<string> pinnedTags = new List<string>();

		private bool isJunior = true;

		private string lastSearchQuery;

		private string lastDoorQuery;

		public const string RRO_TAG = "#recroomoriginal";

		public const string COMMUNITY_TAG = "#community";

		private const char TAG_CHARACTER = '#';

		private static DisplayMode savedDisplayMode;

		private static int activeTags;

		private DisplayMode roomsDisplayMode;

		private int maxTagsToDisplay => Mathf.Min(pinnedTags.Count, (base.WatchUI.Size != SizeOption.LARGE) ? 8 : 15);

		private DisplayMode RoomsDisplayMode
		{
			get
			{
				return (isJunior && roomsDisplayMode == DisplayMode.Featured) ? DisplayMode.Hot : roomsDisplayMode;
			}
			set
			{
				if (roomsDisplayMode != value)
				{
					roomsDisplayMode = value;
					if (value != DisplayMode.DoorSelect)
					{
						savedDisplayMode = value;
					}
					if (base.IsCurrentFlow)
					{
						UpdateGridForDisplayMode(refreshRoomList: true);
					}
				}
			}
		}

		public bool RoomListLoading { get; private set; }

		public ToggleButton3D AGRoomsTagButton { get; private set; }

		public RadioButton3D LiveButton => liveRadioButton;

		public RadioButton3D FavoritesButton => favoritesRadioButton;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			isJunior = Profiles.LocalProfile.IsJunior();
			subscreenControl.SetDefaultSubscreen((!isJunior) ? featuredSubscreen : roomsSubscreen);
			RoomsDisplayMode = ((savedDisplayMode != DisplayMode.None) ? savedDisplayMode : DisplayMode.Featured);
			subscreenControl.ShowSubscreen((RoomsDisplayMode != DisplayMode.Featured) ? roomsSubscreen : featuredSubscreen);
			tagToggles = tagButtonsParent.GetComponentsInChildren<ToggleButton3D>(includeInactive: true);
			for (int i = 0; i < tagToggles.Length; i++)
			{
				int temp = i;
				tagToggles[temp].OnClick.AddListener(delegate(bool isOn)
				{
					Toggle_Tag(temp, isOn);
				});
				tagToggles[temp].gameObject.SetActive(value: false);
			}
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			if (pinnedTags.Count == 0 || (pinnedTags.Count == 1 && pinnedTags[0] == "#recroomoriginal"))
			{
				RecNet.Rooms.GetPinnedTags().Then(delegate(List<string> tags)
				{
					if (this != null)
					{
						pinnedTags = tags;
						RefreshTagVisuals();
					}
				});
			}
			else
			{
				for (int num = 0; num < tagToggles.Length; num++)
				{
					tagToggles[num].gameObject.SetActive(num < maxTagsToDisplay);
				}
			}
			bool refreshRoomList = oldFlow.GetType() == typeof(HomeScreenFlow);
			UpdateGridForDisplayMode(refreshRoomList);
			UpdateButtonPresses();
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			ResetDoorSelect(newFlow);
		}

		private void OnDisable()
		{
			if (base.IsCurrentFlow)
			{
				ResetDoorSelect(null);
			}
		}

		protected override void Resize(SizeOption size, bool enteringFlow)
		{
			base.Resize(size, enteringFlow);
			if (!enteringFlow)
			{
				UpdatePageGridSize(size, updateGrid: true);
			}
		}

		private void ResetDoorSelect(StackedUIFlowBase newFlow)
		{
			if (RoomsDisplayMode == DisplayMode.DoorSelect && (newFlow == null || newFlow.GetType() != typeof(ThisRoomWatchUIFlow)))
			{
				RoomsDisplayMode = ((savedDisplayMode != DisplayMode.None) ? savedDisplayMode : DisplayMode.Featured);
			}
		}

		private void RefreshTagVisuals()
		{
			for (int i = 0; i < tagToggles.Length; i++)
			{
				tagToggles[i].gameObject.SetActive(i < maxTagsToDisplay);
				if (i < pinnedTags.Count)
				{
					tagToggles[i].Label.gameObject.SetActive(pinnedTags[i] != "#recroomoriginal");
					tagToggles[i].SetConstantSprite((!(pinnedTags[i] == "#recroomoriginal")) ? null : agTagSprite);
					UIHelper.SafeSetText(tagToggles[i].Label, pinnedTags[i]);
					if (pinnedTags[i] == "#recroomoriginal")
					{
						AGRoomsTagButton = tagToggles[i];
					}
				}
			}
		}

		private void ClearAllTags()
		{
			activeTags = 0;
			ToggleButton3D[] array = tagToggles;
			foreach (ToggleButton3D toggleButton3D in array)
			{
				toggleButton3D.ForceRelease();
			}
			UpdateGridForDisplayMode(refreshRoomList: true);
		}

		private void UpdateButtonPresses()
		{
			RadioButton3D radioButton3D = null;
			switch (RoomsDisplayMode)
			{
			case DisplayMode.Hot:
				radioButton3D = hotRadioButton;
				break;
			case DisplayMode.Live:
				radioButton3D = liveRadioButton;
				break;
			case DisplayMode.Favorites:
				radioButton3D = favoritesRadioButton;
				break;
			case DisplayMode.Search:
				radioButton3D = searchRadioButton;
				break;
			case DisplayMode.Featured:
				radioButton3D = featuredRadioButton;
				break;
			}
			if (radioButton3D != null)
			{
				radioButton3D.ForcePressed();
			}
		}

		private void UpdateGridForDisplayMode(bool refreshRoomList)
		{
			UpdatePageGridSize(base.WatchUI.Size, updateGrid: false);
			if (refreshRoomList)
			{
				if (RoomsDisplayMode == DisplayMode.Featured)
				{
					subscreenControl.ShowSubscreen(featuredSubscreen);
					ShowFeaturedRooms();
				}
				else
				{
					subscreenControl.ShowSubscreen(roomsSubscreen);
					roomsGrid.SetLoading();
					RoomListLoading = true;
					switch (RoomsDisplayMode)
					{
					case DisplayMode.Hot:
						ShowHotRooms();
						break;
					case DisplayMode.Live:
						ShowLiveRooms();
						break;
					case DisplayMode.Favorites:
						RecNet.Rooms.GetMyBookmarkedRooms().Then(delegate(List<RecNet.Room> rooms)
						{
							OnRoomListReceived(rooms, DisplayMode.Favorites);
						});
						break;
					case DisplayMode.Search:
						OnRoomListReceived(Enumerable.Empty<RecNet.Room>(), DisplayMode.Search);
						searchField.Text = string.Empty;
						break;
					case DisplayMode.DoorSelect:
						OnRoomListReceived(Enumerable.Empty<RecNet.Room>(), DisplayMode.DoorSelect);
						break;
					default:
						throw new NotImplementedException("Unknown error fetching rooms");
					}
				}
			}
			UpdateButtonPresses();
			contextRow.SetActive(RoomsDisplayMode != DisplayMode.DoorSelect);
			searchRow.SetActive(RoomsDisplayMode == DisplayMode.Search);
			tagFilterContainer.SetActive((RoomsDisplayMode == DisplayMode.Hot || RoomsDisplayMode == DisplayMode.Live) && !isJunior);
		}

		private void ShowFeaturedRooms()
		{
			RecNet.Rooms.GetHotRooms("#recroomoriginal").Then(delegate(List<RecNet.Room> rooms)
			{
				if (this != null && rooms != null && base.IsCurrentFlow && RoomsDisplayMode == DisplayMode.Featured)
				{
					rroRoomsGrid.SetRooms(rooms, new List<string> { "#recroomoriginal".Substring(1) });
				}
			});
			RecNet.Rooms.GetHotRooms("#community").Then(delegate(List<RecNet.Room> rooms)
			{
				if (this != null && rooms != null && base.IsCurrentFlow && RoomsDisplayMode == DisplayMode.Featured)
				{
					communityRoomsGrid.SetRooms(rooms, new List<string> { "#community".Substring(1) });
				}
			});
		}

		private void ShowHotRooms()
		{
			RoomListLoading = true;
			string query = ConvertActiveTagsToQueryString();
			RecNet.Rooms.GetHotRooms(query).Then(delegate(List<RecNet.Room> rooms)
			{
				if (this != null && rooms != null && query == ConvertActiveTagsToQueryString())
				{
					OnRoomListReceived(rooms, DisplayMode.Hot);
				}
			});
		}

		private void ShowLiveRooms()
		{
			RoomListLoading = true;
			string query = ConvertActiveTagsToQueryString();
			RecNet.Rooms.GetLiveRooms(query).Then(delegate(List<RecNet.Room> rooms)
			{
				if (this != null && rooms != null && query == ConvertActiveTagsToQueryString())
				{
					OnRoomListReceived(rooms, DisplayMode.Live);
				}
			});
		}

		private string ConvertActiveTagsToQueryString()
		{
			List<string> activeFilters = GetActiveFilters();
			if (activeFilters == null || activeFilters.Count == 0)
			{
				return string.Empty;
			}
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < activeFilters.Count; i++)
			{
				stringBuilder.AppendFormat("{0}{1} ", '#', activeFilters[i]);
			}
			return stringBuilder.ToString();
		}

		private List<string> GetActiveFilters()
		{
			List<string> list = new List<string>();
			for (int i = 0; i < pinnedTags.Count; i++)
			{
				if ((activeTags & (1 << i)) != 0)
				{
					if (i < tagToggles.Count())
					{
						tagToggles[i].IsOn = true;
					}
					list.Add(pinnedTags[i].Substring(1));
				}
				else if (i < tagToggles.Count())
				{
					tagToggles[i].IsOn = false;
				}
			}
			return list;
		}

		private List<string> GetActiveTagSet(DisplayMode mode)
		{
			switch (mode)
			{
			case DisplayMode.Search:
				return ExtractTagsFromSearch(lastSearchQuery);
			case DisplayMode.DoorSelect:
				return ExtractTagsFromSearch(lastDoorQuery);
			case DisplayMode.Hot:
			case DisplayMode.Live:
				return GetActiveFilters();
			default:
				return null;
			}
		}

		private List<string> ExtractTagsFromSearch(string searchQuery)
		{
			if (searchQuery == null)
			{
				return null;
			}
			char[] separator = new char[1] { ' ' };
			string[] array = searchQuery.Split(separator, StringSplitOptions.RemoveEmptyEntries);
			if (array == null || array.Length == 0)
			{
				return null;
			}
			List<string> list = new List<string>();
			foreach (string text in array)
			{
				if (text[0] == '#')
				{
					list.Add(text.Substring(1));
				}
			}
			return list;
		}

		private void UpdatePageGridSize(SizeOption size, bool updateGrid)
		{
			bool flag = size == SizeOption.LARGE;
			switch (RoomsDisplayMode)
			{
			case DisplayMode.Hot:
			case DisplayMode.Live:
				if (isJunior)
				{
					roomsGrid.SetPageSize((!flag) ? defaultGridSize : largeGridSize, updateGrid);
				}
				else
				{
					roomsGrid.SetPageSize((!flag) ? hotGridSize : largeHotGridSize, updateGrid);
				}
				break;
			case DisplayMode.Search:
				roomsGrid.SetPageSize((!flag) ? searchGridSize : largeSearchGridSize, updateGrid);
				break;
			default:
				roomsGrid.SetPageSize((!flag) ? defaultGridSize : largeGridSize, updateGrid);
				break;
			}
		}

		private void SearchByRoomName(string searchQuery)
		{
			lastSearchQuery = searchQuery;
			searchButton.Interactable = false;
			roomsGrid.SetLoading();
			RoomListLoading = true;
			RecNet.Rooms.SearchRooms(searchQuery).Then(delegate(List<RecNet.Room> rooms)
			{
				OnRoomListReceived(rooms, DisplayMode.Search);
			}).Error(delegate
			{
				OnRoomListReceived(Enumerable.Empty<RecNet.Room>(), DisplayMode.Search);
			})
				.Finally(delegate
				{
					if (this != null)
					{
						searchButton.Interactable = true;
					}
				});
		}

		private void OnRoomListReceived(IEnumerable<RecNet.Room> rooms, DisplayMode mode)
		{
			if (this != null && base.IsCurrentFlow && RoomsDisplayMode == mode)
			{
				List<string> activeTagSet = GetActiveTagSet(mode);
				roomsGrid.SetRooms(rooms, activeTagSet);
				if (mode == DisplayMode.Favorites)
				{
					roomsGrid.SetEmptyDisplayText("No results [|=(] To favorite a room, open the room details, then tap Favorite.");
				}
				else
				{
					roomsGrid.SetEmptyDisplayText("No results [|=(]");
				}
			}
			RoomListLoading = false;
		}

		public void AddRoomToCurrentListIfNotPresent(RecNet.Room roomToAdd)
		{
			roomsGrid.AddRoomToCurrentListIfNotPresent(roomToAdd);
		}

		public void SearchByDoorSelection(string query, Vector3? position = null)
		{
			if (!base.IsCurrentFlow)
			{
				base.WatchUI.PushFlow(this);
			}
			if (position.HasValue)
			{
				base.WatchUI.WatchMenuProjector.AuthorityOpenMenuDetached(position.Value);
			}
			else
			{
				base.WatchUI.WatchMenuProjector.AuthorityOpenMenuDetached(force: true);
			}
			RoomsDisplayMode = DisplayMode.DoorSelect;
			lastDoorQuery = query;
			roomsGrid.SetLoading();
			RoomListLoading = true;
			RecNet.Rooms.SearchRooms(query).Then(delegate(List<RecNet.Room> rooms)
			{
				OnRoomListReceived(rooms, DisplayMode.DoorSelect);
			});
		}

		public int FindPageIndexOfRoom(string roomName)
		{
			return roomsGrid.FindPageIndexOfRoom(roomName);
		}

		public void SetCurrentPage(int pageIndex)
		{
			roomsGrid.SetCurrentPage(pageIndex);
		}

		public void Button_FeaturedDisplayMode()
		{
			RoomsDisplayMode = DisplayMode.Featured;
		}

		public void Button_HotDisplayMode()
		{
			RoomsDisplayMode = DisplayMode.Hot;
		}

		public void Button_LiveDisplayMode()
		{
			RoomsDisplayMode = DisplayMode.Live;
		}

		public void Button_FavoritesDisplayMode()
		{
			RoomsDisplayMode = DisplayMode.Favorites;
		}

		public void Button_SearchDisplayMode()
		{
			RoomsDisplayMode = DisplayMode.Search;
		}

		public void Button_Search()
		{
			SearchByRoomName(searchField.Text.Trim());
		}

		public void Toggle_Tag(int index, bool isOn)
		{
			if (isOn)
			{
				activeTags |= 1 << index;
				int num = pinnedTags.IndexOf("#recroomoriginal");
				int num2 = pinnedTags.IndexOf("#community");
				if (num >= 0 && num2 >= 0)
				{
					if (index == num && (activeTags & (1 << num2)) != 0)
					{
						activeTags &= ~(1 << num2);
					}
					else if (index == num2 && (activeTags & (1 << num)) != 0)
					{
						activeTags &= ~(1 << num);
					}
				}
			}
			else
			{
				activeTags &= ~(1 << index);
			}
			UpdateGridForDisplayMode(refreshRoomList: true);
		}

		public void Button_HotRRORooms()
		{
			if (!base.IsCurrentFlow)
			{
				base.WatchUI.PushFlow(this);
			}
			RoomsDisplayMode = DisplayMode.Hot;
			ForcePinTag("#recroomoriginal", 0);
			ClearAllTags();
			tagToggles[pinnedTags.IndexOf("#recroomoriginal")].ForcePressed();
		}

		public void Button_HotCommunityRooms()
		{
			if (!base.IsCurrentFlow)
			{
				base.WatchUI.PushFlow(this);
			}
			RoomsDisplayMode = DisplayMode.Hot;
			ForcePinTag("#community", 1);
			ClearAllTags();
			tagToggles[pinnedTags.IndexOf("#community")].ForcePressed();
		}

		public void ForcePinTag(string tag, int index)
		{
			if (!pinnedTags.Contains(tag))
			{
				pinnedTags.Insert(Mathf.Clamp(index, 0, pinnedTags.Count), tag);
				RefreshTagVisuals();
			}
		}
	}
}
public class ChatThreadScreen : WatchUIFlow
{
	public enum CreateChatSource
	{
		CreateChatScreen,
		PlayerDetailsScreen
	}

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private ChatMessagePagedGrid pagedGrid;

	[SerializeField]
	private ChooseFriendsDialog chooseFriendsDialogPrefab;

	[SerializeField]
	private RenameChatDialog renameChatDialogPrefab;

	[SerializeField]
	private TextMeshProUGUI chatName;

	[SerializeField]
	private InputField3D messageField;

	[SerializeField]
	private Button3D sendButton;

	[SerializeField]
	private Button3D addPlayerButton;

	[SerializeField]
	private ToggleButton3D snoozeToggle;

	private ChatThread currentChatThread;

	private List<int> otherProfileIds;

	private PlayerDetailsWatchUIFlow playerDetailsScreen;

	private int replacementStartIndex = -1;

	private Chats.MarkupReplacementType replacementType;

	private List<IPromise> referenceGroupPromises = new List<IPromise>();

	private string messageToSend;

	private CreateChatSource createChatSource;

	private bool cachedCanMessage = true;

	private bool targetCanSendMessage = true;

	private bool hasSeenCurrentChat;

	private const int rateLimit_maxMessages = 5;

	private const float rateLimit_numSeconds = 5f;

	private const float rateLimite_cooldownSeconds = 60f;

	private static float rateLimit_cooldownEndTime = 0f;

	private static Queue<float> rateLimit_previousSendTimes = new Queue<float>();

	private bool OnlyLocalPlayerInThread
	{
		get
		{
			if (currentChatThread != null && currentChatThread.PlayerIds.Count == 1 && currentChatThread.PlayerIds[0] == (long)Profiles.LocalProfile.Id)
			{
				return true;
			}
			return false;
		}
	}

	public override void Initialize(StackedUIBase uiBase)
	{
		base.Initialize(uiBase);
		playerDetailsScreen = base.WatchUI.GetFlowByType<PlayerDetailsWatchUIFlow>();
		Chats.OnChatUpdated += Chats_OnChatUpdated;
		Profiles.OnProfileUpdated += Profiles_OnProfileUpdated;
		Relationships.RelationshipUpdated += Relationships_RelationshipUpdated;
		messageField.InputField.onEndEdit.AddListener(delegate
		{
			if (Input.GetKeyDown(KeyCode.Return) || Input.GetKeyDown(KeyCode.KeypadEnter))
			{
				Button_SendMessage();
			}
		});
	}

	private void Relationships_RelationshipUpdated(long? playerId)
	{
		if (playerId.HasValue)
		{
			if (currentChatThread != null && currentChatThread.PlayerIds.Contains((int)playerId.Value))
			{
				UpdateCachedCanMessage();
				chatName.text = currentChatThread.GetChatName(forceRefresh: true);
			}
			else if (otherProfileIds != null && otherProfileIds.Contains((int)playerId.Value))
			{
				UpdateCachedCanMessage();
				chatName.text = GetNameForNewChat();
			}
			messageField.Interactable = cachedCanMessage;
			targetCanSendMessage = cachedCanMessage && string.IsNullOrEmpty(messageField.Text);
		}
	}

	private void UpdateCachedCanMessage()
	{
		if (otherProfileIds != null)
		{
			foreach (int otherProfileId in otherProfileIds)
			{
				Relationship relationship = Relationships.Get(otherProfileId);
				cachedCanMessage = relationship != null && !relationship.IsBlocked && relationship.IsFriend;
				if (!cachedCanMessage)
				{
					break;
				}
			}
			return;
		}
		if (!(currentChatThread != null))
		{
			return;
		}
		if (currentChatThread.PlayerIds.Count > 2)
		{
			cachedCanMessage = true;
		}
		else if (currentChatThread.PlayerIds.Count == 2)
		{
			int num = currentChatThread.PlayerIds.FirstOrDefault((int id) => id != (int)(long)Profiles.LocalProfile.Id);
			Relationship relationship2 = Relationships.Get(num);
			cachedCanMessage = relationship2 != null && !relationship2.IsBlocked && relationship2.IsFriend;
		}
		else
		{
			cachedCanMessage = false;
		}
	}

	private void Profiles_OnProfileUpdated(long id)
	{
		if (currentChatThread != null && currentChatThread.PlayerIds.Contains((int)id))
		{
			chatName.text = currentChatThread.GetChatName(forceRefresh: true);
		}
		else if (otherProfileIds != null && otherProfileIds.Contains((int)id))
		{
			chatName.text = GetNameForNewChat();
		}
	}

	private string GetNameForNewChat()
	{
		if (currentChatThread == null && otherProfileIds != null)
		{
			string text = string.Empty;
			{
				foreach (int otherProfileId in otherProfileIds)
				{
					Relationship relationship = Relationships.Get(otherProfileId);
					Profile profile = Profiles.Get(otherProfileId);
					text = string.Format("{0}{1}{2}{3}", text, (!string.IsNullOrEmpty(text)) ? ", " : string.Empty, (profile == null) ? "[Unknown]" : profile.DisplayName.GetDecrypted(), (relationship == null || !relationship.IsBlocked) ? string.Empty : " [Blocked]");
				}
				return text;
			}
		}
		return string.Empty;
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Profiles.OnProfileUpdated -= Profiles_OnProfileUpdated;
		Chats.OnChatUpdated -= Chats_OnChatUpdated;
		Relationships.RelationshipUpdated -= Relationships_RelationshipUpdated;
	}

	private void Chats_OnChatUpdated(ChatThread chatThread)
	{
		this.InvokeNextEndOfFrame(delegate
		{
			if (currentChatThread != null && currentChatThread == chatThread)
			{
				Chats.GetRecentMessages(currentChatThread.ChatThreadId).Then((Action<List<ChatMessage>>)delegate
				{
					pagedGrid.SetChatMessages(currentChatThread, currentChatThread.Messages);
				});
				UpdateVisuals(OnlyLocalPlayerInThread);
			}
		});
	}

	private void UpdateVisuals(bool onlyLocalPlayerLeft)
	{
		addPlayerButton.Interactable = !onlyLocalPlayerLeft;
		targetCanSendMessage = !onlyLocalPlayerLeft;
		messageField.Interactable = !onlyLocalPlayerLeft;
		if (currentChatThread != null)
		{
			chatName.text = currentChatThread.GetChatName(forceRefresh: true);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		if (Profiles.LocalProfile.IsJunior())
		{
			base.WatchUI.PopFlow();
			return;
		}
		hasSeenCurrentChat = false;
		UpdateVisuals(OnlyLocalPlayerInThread);
		if (!OnlyLocalPlayerInThread)
		{
			targetCanSendMessage = !string.IsNullOrEmpty(messageField.Text) && cachedCanMessage;
			messageField.Interactable = cachedCanMessage;
		}
		pagedGrid.SetChatMessages(null, Enumerable.Empty<ChatMessage>());
		pagedGrid.SetEmptyDisplayText("Loading...");
		if (!(currentChatThread != null))
		{
			return;
		}
		Chats.GetRecentMessages(currentChatThread.ChatThreadId).Then((Action<List<ChatMessage>>)delegate
		{
			pagedGrid.SetChatMessages(currentChatThread, currentChatThread.Messages);
			if (base.isActiveAndEnabled)
			{
				hasSeenCurrentChat = true;
			}
		});
	}

	public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
	{
		base.OnFlowExited(newFlow, stillOnStack);
		if (hasSeenCurrentChat && currentChatThread != null)
		{
			Chats.ReadMessage(currentChatThread.ChatThreadId, currentChatThread.Messages.First().ChatMessageId);
		}
	}

	public void ShowScreen(ChatThread chatThread)
	{
		if (chatThread != null)
		{
			currentChatThread = chatThread;
			snoozeToggle.IsOn = currentChatThread.IsSnoozed;
			UpdateCachedCanMessage();
			otherProfileIds = null;
			chatName.text = currentChatThread.GetChatName();
			base.WatchUI.PushFlow(this);
		}
		else
		{
			UnityEngine.Debug.LogError("Cannot pass null ChatThread to ChatThreadScreen!");
		}
	}

	public void ShowScreen(List<Profile> otherPlayerProfiles, CreateChatSource source)
	{
		if (otherPlayerProfiles != null)
		{
			createChatSource = source;
			currentChatThread = null;
			snoozeToggle.IsOn = false;
			otherProfileIds = otherPlayerProfiles.Select((Profile p) => (int)(long)p.Id).ToList();
			UpdateCachedCanMessage();
			chatName.text = GetNameForNewChat();
			List<int> list = new List<int>(otherProfileIds);
			list.Add((int)(long)Profiles.LocalProfile.Id);
			Chats.GetChatByPlayers(list).Then(delegate(ChatThread chatThread)
			{
				if (chatThread != null)
				{
					currentChatThread = chatThread;
					snoozeToggle.IsOn = currentChatThread.IsSnoozed;
					otherProfileIds = null;
					chatName.text = currentChatThread.GetChatName();
					pagedGrid.SetChatMessages(currentChatThread, currentChatThread.Messages);
				}
				else
				{
					pagedGrid.SetEmptyDisplayText("No messages");
				}
			});
			base.WatchUI.PushFlow(this);
		}
		else
		{
			UnityEngine.Debug.LogError("Cannot pass null Profile to ChatThreadScreen!");
		}
	}

	private void SendChatMessage(string msg)
	{
		if (OnlyLocalPlayerInThread || IsRateLimited() || string.IsNullOrEmpty(msg))
		{
			return;
		}
		if (referenceGroupPromises.Count != 0)
		{
			messageToSend = msg;
			return;
		}
		if (replacementStartIndex != -1)
		{
			messageToSend = msg;
			CheckForSpecialReferenceGroups(msg);
			return;
		}
		if (currentChatThread != null)
		{
			Chats.SendMessage(currentChatThread.ChatThreadId, Chats.ConstructTextMessageFromRaw(msg)).Then(delegate(SendMessageResponse response)
			{
				if (response.ChatResult == ChatResults.Success)
				{
					int taggedPlayers = 0;
					int taggedRooms = 0;
					if (response.ChatMessage.MessageJson.Type == Chats.MessageContentType.Text && response.ChatMessage.TextMessageJson.HasDisplayCards)
					{
						taggedPlayers = response.ChatMessage.TextMessageJson.DisplayCardData.Where((Chats.DisplayCardData d) => d.ReplacementType == Chats.MarkupReplacementType.Username).Count();
						taggedRooms = response.ChatMessage.TextMessageJson.DisplayCardData.Where((Chats.DisplayCardData d) => d.ReplacementType == Chats.MarkupReplacementType.Roomname).Count();
					}
					AnalyticsHelper.SendMessage(currentChatThread.ChatThreadId, Profiles.LocalProfile.Id, response.ChatMessage.MessageJson.Type, taggedPlayers, taggedRooms);
					RefreshMessages();
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Failed to send message", 3f);
					messageField.Interactable = true;
					targetCanSendMessage = true;
				}
			});
		}
		else
		{
			List<int> list = new List<int>(otherProfileIds);
			list.Add((int)(long)Profiles.LocalProfile.Id);
			Chats.CreateChat(list, Chats.ConstructTextMessageFromRaw(msg)).Then(delegate(CreateChatResponse response)
			{
				if (response.ChatResult == ChatResults.Success)
				{
					AnalyticsHelper.CreateChat(response.ChatThread.ChatThreadId, Profiles.LocalProfile.Id, createChatSource);
					currentChatThread = response.ChatThread;
					otherProfileIds = null;
					RefreshMessages();
				}
				else
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Failed to send message", 3f);
					messageField.Interactable = true;
					targetCanSendMessage = true;
				}
			});
		}
		messageToSend = null;
		UpdateRateLimitTracking();
	}

	private void UpdateRateLimitTracking()
	{
		float realtimeSinceStartup = UnityEngine.Time.realtimeSinceStartup;
		if (rateLimit_previousSendTimes.Count + 1 >= 5)
		{
			float num = rateLimit_previousSendTimes.Dequeue();
			while (rateLimit_previousSendTimes.Count + 1 >= 5)
			{
				num = rateLimit_previousSendTimes.Dequeue();
			}
			if (realtimeSinceStartup - num < 5f)
			{
				UnityEngine.Debug.Log("Hit chat rate limit");
				rateLimit_cooldownEndTime = realtimeSinceStartup + 60f;
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Don't spam!", "Wait a minute before sending another message", 5f);
			}
		}
		rateLimit_previousSendTimes.Enqueue(realtimeSinceStartup);
	}

	private bool IsRateLimited()
	{
		return UnityEngine.Time.realtimeSinceStartup < rateLimit_cooldownEndTime;
	}

	private void Update()
	{
		sendButton.Interactable = targetCanSendMessage && !IsRateLimited();
		messageField.Interactable = !OnlyLocalPlayerInThread && !IsRateLimited();
	}

	private void LeaveChat()
	{
		if (currentChatThread != null)
		{
			base.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Confirm leave chat?", "You will not be able to be invited back to this chat for 24h.").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					Chats.LeaveChat(currentChatThread.ChatThreadId).Then(delegate(ModifyChatResponse result)
					{
						if (result.ChatResult == ChatResults.Success)
						{
							AnalyticsHelper.LeaveChat(currentChatThread.ChatThreadId, Profiles.LocalProfile.Id);
							base.WatchUI.PopFlow();
						}
						else
						{
							SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Error:", response.ToString(), 3f);
						}
					});
				}
			});
		}
		else
		{
			base.WatchUI.PopFlow();
		}
	}

	private void RefreshMessages()
	{
		if (currentChatThread != null)
		{
			messageField.InputField.text = string.Empty;
			messageField.Interactable = cachedCanMessage;
			if (cachedCanMessage)
			{
				messageField.InputField.ActivateInputField();
			}
			pagedGrid.SetChatMessages(currentChatThread, currentChatThread.Messages);
		}
	}

	private void CheckForSpecialReferenceGroups(string text)
	{
		if (messageToSend != null)
		{
			if (IsValidReference(messageToSend))
			{
				string referenceName = text.Substring(replacementStartIndex, text.Length - replacementStartIndex);
				GetReference(referenceName);
			}
			if (referenceGroupPromises.Count == 0)
			{
				replacementStartIndex = -1;
				SendChatMessage(messageToSend);
			}
		}
		else if (text.Last() == '@' || text.Last() == '^')
		{
			replacementStartIndex = text.Length;
			replacementType = ((text.Last() == '@') ? Chats.MarkupReplacementType.Username : Chats.MarkupReplacementType.Roomname);
		}
		else
		{
			if (!IsValidReference(text) || !Chats.IsTerminatorCharacter(text.Last()))
			{
				return;
			}
			string referenceName2;
			if (text[text.Length - 2] == '.')
			{
				if (text.Length - replacementStartIndex - 2 <= 0)
				{
					return;
				}
				referenceName2 = text.Substring(replacementStartIndex, text.Length - replacementStartIndex - 2);
			}
			else
			{
				referenceName2 = text.Substring(replacementStartIndex, text.Length - replacementStartIndex - 1);
			}
			GetReference(referenceName2);
		}
	}

	private bool IsValidReference(string text)
	{
		return replacementStartIndex != -1 && text.Length > replacementStartIndex;
	}

	private void GetReference(string referenceName)
	{
		Chats.MarkupReplacementType markupReplacementType = replacementType;
		switch (markupReplacementType)
		{
		case Chats.MarkupReplacementType.Username:
		{
			IPromise<Profile> profilePromise = Profiles.GetPlayerByUsername(referenceName);
			if (!profilePromise.HasSucceeded)
			{
				referenceGroupPromises.Add(profilePromise);
				profilePromise.Finally(delegate
				{
					RemoveDisplayCardPromise(profilePromise);
				});
			}
			break;
		}
		case Chats.MarkupReplacementType.Roomname:
		{
			IPromise<RecNet.Room> roomPromise = RecNet.Rooms.GetRoomByName(referenceName);
			if (!roomPromise.HasSucceeded)
			{
				referenceGroupPromises.Add(roomPromise);
				roomPromise.Finally(delegate
				{
					RemoveDisplayCardPromise(roomPromise);
				});
			}
			break;
		}
		default:
			UnityEngine.Debug.LogError("Not implemented yet!");
			break;
		}
		replacementStartIndex = -1;
		replacementType = Chats.MarkupReplacementType.Invalid;
	}

	private void RemoveDisplayCardPromise(IPromise promise)
	{
		referenceGroupPromises.Remove(promise);
		if (referenceGroupPromises.Count == 0 && messageToSend != null)
		{
			SendChatMessage(messageToSend);
		}
	}

	private void OnEnable()
	{
		hasSeenCurrentChat = true;
	}

	[SkipRename]
	public void Button_ListMembers()
	{
		base.WatchUI.ShowTemporaryDialog(chooseFriendsDialogPrefab, ChooseFriendsDialog.DisplayMode.ListMemebers, currentChatThread, (WatchAttractor.EffectFlags)0);
	}

	[SkipRename]
	public void Button_LeaveChat()
	{
		LeaveChat();
	}

	[SkipRename]
	public void OnTextValueChanged(string newText)
	{
		targetCanSendMessage = !string.IsNullOrEmpty(newText) && cachedCanMessage;
		if (newText.Length > 0)
		{
			CheckForSpecialReferenceGroups(newText);
		}
		else
		{
			replacementStartIndex = -1;
		}
	}

	[SkipRename]
	public void Button_SendMessage()
	{
		if (!string.IsNullOrEmpty(messageField.InputField.text))
		{
			messageField.Interactable = false;
			targetCanSendMessage = false;
			SendChatMessage(messageField.InputField.text);
			messageField.InputField.text = string.Empty;
		}
	}

	[SkipRename]
	public void Button_OpenSendersProfile(Profile senderPlayerProfile)
	{
		if (playerDetailsScreen != null)
		{
			playerDetailsScreen.SetProfile(senderPlayerProfile);
			base.UIBase.PushFlow(playerDetailsScreen);
		}
	}

	[SkipRename]
	public void Button_RenameChat()
	{
		base.WatchUI.ShowTemporaryConfirmationDialog(renameChatDialogPrefab, currentChatThread.ChatThreadId, (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses response)
		{
			if (response == ConfirmDialogResponses.Affirmative)
			{
				chatName.text = currentChatThread.GetChatName();
			}
		});
	}

	[SkipRename]
	public void Button_SnoozeChat(bool snooze)
	{
		if (!(currentChatThread != null))
		{
			return;
		}
		Chats.SnoozeChat(currentChatThread.ChatThreadId, !currentChatThread.IsSnoozed).Then(delegate(ChatResults result)
		{
			if (result != ChatResults.Success)
			{
				snoozeToggle.IsOn = currentChatThread.IsSnoozed;
			}
		});
	}
}
public class ChooseEventLocationDialog : UIDialog<RecNet.Room>
{
	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private BaseRoomButtonPagedGrid pagedGrid;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private InputField3D searchField;

	[SerializeField]
	private Button3D searchButton;

	[SerializeField]
	[TextArea]
	private string NoResultsMessage = "No rooms found...\n\nSearch by room name or @creatorName to find a room";

	public override void ForceCancel(bool shouldCloseDialog)
	{
		Respond(null, shouldCloseDialog: true);
	}

	public override IPromise<RecNet.Room> ShowDialog()
	{
		pagedGrid.SetLoading();
		RecNet.Rooms.GetMyCreatedRooms().Then(delegate(List<RecNet.Room> myRooms)
		{
			if (myRooms.Count > 0)
			{
				searchField.Text = $"@{Profiles.LocalProfile.Username}";
				pagedGrid.SetRooms(myRooms);
			}
			else
			{
				RecNet.Rooms.GetHotRooms(string.Empty).Then(delegate(List<RecNet.Room> hotRooms)
				{
					searchField.Text = string.Empty;
					if (hotRooms.Count > 0)
					{
						pagedGrid.SetRooms(hotRooms);
					}
					else
					{
						pagedGrid.SetEmptyDisplayText(NoResultsMessage);
					}
				});
			}
		});
		return base.ShowDialog();
	}

	private void SearchRooms(string searchQuery)
	{
		searchButton.Interactable = false;
		pagedGrid.SetLoading();
		RecNet.Rooms.SearchRooms(searchQuery).Then(delegate(List<RecNet.Room> rooms)
		{
			pagedGrid.SetRooms(rooms);
			if (rooms.Count == 0)
			{
				pagedGrid.SetEmptyDisplayText(NoResultsMessage);
			}
		}).Error(delegate
		{
			pagedGrid.SetRooms(Enumerable.Empty<RecNet.Room>());
		})
			.Finally(delegate
			{
				if (this != null)
				{
					searchButton.Interactable = true;
				}
			});
	}

	[SkipRename]
	public void Button_Search()
	{
		SearchRooms(searchField.Text.Trim());
	}

	[SkipRename]
	public void Button_ChooseRoom(RecNet.Room room)
	{
		Respond(room, shouldCloseDialog: true);
	}
}
public class ChooseFriendsDialog : UIDialog<ChooseFriendsDialog.DisplayMode, ChatThread, List<Profile>>
{
	public enum DisplayMode
	{
		Invalid,
		StartChat,
		AddPlayer,
		ListMemebers
	}

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private ChooseFriendPagedGrid pagedGrid;

	[SerializeField]
	private GameObject contextRow;

	[SerializeField]
	private GameObject toTextContainer;

	[SerializeField]
	private TextMeshProUGUI playerNames;

	[SerializeField]
	private Button3D startChatButton;

	[SerializeField]
	private Button3D addPlayerButton;

	[SerializeField]
	private TextMeshProUGUI infoText;

	private List<Profile> selectedProfiles = new List<Profile>();

	private ScreenHeader screenHeader;

	private PlayerDetailsWatchUIFlow playerDetailsFlow;

	private ChatThread currentChatThread;

	private DisplayMode _displayMode;

	private DisplayMode CurrentDisplayMode
	{
		get
		{
			return _displayMode;
		}
		set
		{
			if (value != _displayMode)
			{
				_displayMode = value;
				UpdateUIForDisplayMode();
			}
		}
	}

	public override IPromise<List<Profile>> ShowDialog(DisplayMode mode, ChatThread chatThread)
	{
		screenHeader = GetComponentInChildren<ScreenHeader>();
		playerDetailsFlow = Player.LocalPlayer.PlayerUI.WatchMenu.GetFlowByType<PlayerDetailsWatchUIFlow>();
		currentChatThread = chatThread;
		CurrentDisplayMode = mode;
		return base.ShowDialog();
	}

	public override void ForceCancel(bool closeDialog)
	{
		Respond(null, closeDialog);
	}

	private void UpdateUIForDisplayMode()
	{
		IEnumerable<Profile> enumerable = from r in Relationships.GetAll()
			where r.IsFriend && !r.IsBlocked
			select Profiles.Get(r.PlayerID) into p
			where p != null && !p.IsJunior()
			select p;
		switch (CurrentDisplayMode)
		{
		case DisplayMode.StartChat:
			screenHeader.Title = "Choose Friends";
			playerNames.text = string.Empty;
			break;
		case DisplayMode.AddPlayer:
			screenHeader.Title = "Add Player";
			enumerable = enumerable.Where((Profile p) => !currentChatThread.PlayerIds.Contains((int)(long)p.Id));
			playerNames.text = string.Empty;
			break;
		case DisplayMode.ListMemebers:
			screenHeader.Title = "Members";
			enumerable = enumerable.Where((Profile p) => currentChatThread.PlayerIds.Contains((int)(long)p.Id));
			playerNames.text = string.Join(", ", enumerable.Select((Profile p) => p.DisplayName.ToString()).ToArray());
			break;
		}
		pagedGrid.SetProfiles(enumerable, CurrentDisplayMode != DisplayMode.ListMemebers);
		toTextContainer.SetActive(CurrentDisplayMode == DisplayMode.StartChat);
		startChatButton.gameObject.SetActive(CurrentDisplayMode == DisplayMode.StartChat);
		startChatButton.Interactable = selectedProfiles.Count() > 0;
		addPlayerButton.gameObject.SetActive(CurrentDisplayMode == DisplayMode.ListMemebers);
		contextRow.SetActive(CurrentDisplayMode != DisplayMode.AddPlayer);
		infoText.text = string.Empty;
	}

	private void AddPlayerToChat(Profile profile)
	{
		infoText.text = "Adding player to chat...";
		Chats.AddPlayerToChat(currentChatThread.ChatThreadId, (int)(long)profile.Id).Then(delegate(ChatResults result)
		{
			switch (result)
			{
			case ChatResults.Success:
				Respond(null, shouldCloseDialog: true);
				break;
			case ChatResults.CannotMessagePlayer:
				infoText.text = "Error: You are not allowed to message this player.";
				break;
			case ChatResults.InvalidArguments:
				infoText.text = "Error: Invalid player selected.";
				break;
			case ChatResults.MembershipNotFound:
				infoText.text = "Error: You are not part of this chat!";
				break;
			case ChatResults.PlayerAlreadyOnThread:
				infoText.text = "Error: This player is already part of the chat.";
				break;
			case ChatResults.ThreadNotFound:
				infoText.text = "Error: This chat no longer exists.";
				break;
			case ChatResults.RecentlyLeftThread:
				infoText.text = "Error: This player recently left this chat. Please try again in a few hours.";
				break;
			case ChatResults.InvalidCharacters:
				break;
			}
		});
	}

	[SkipRename]
	public void SelectedProfilesUpdated(List<Profile> newProfiles)
	{
		switch (CurrentDisplayMode)
		{
		case DisplayMode.StartChat:
			selectedProfiles = newProfiles;
			playerNames.text = string.Join(", ", selectedProfiles.Select((Profile p) => p.DisplayName.ToString()).ToArray());
			startChatButton.Interactable = selectedProfiles.Count > 0;
			break;
		case DisplayMode.AddPlayer:
			if (newProfiles.Count == 1)
			{
				AddPlayerToChat(newProfiles[0]);
			}
			break;
		case DisplayMode.ListMemebers:
			if (newProfiles.Count == 1 && playerDetailsFlow != null)
			{
				playerDetailsFlow.SetProfile(newProfiles[0]);
				base.UIBase.PushFlow(playerDetailsFlow);
			}
			break;
		default:
			UnityEngine.Debug.LogErrorFormat("DisplayMode {0} not supported", CurrentDisplayMode);
			break;
		}
	}

	[SkipRename]
	public void Button_StartChat()
	{
		Respond(selectedProfiles, shouldCloseDialog: true);
	}

	[SkipRename]
	public void Button_AddPlayer()
	{
		base.UIBase.RefreshTopFlow();
		CurrentDisplayMode = DisplayMode.AddPlayer;
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class ChooseParentRoomDialog : ConfirmUIDialog<RoomDetails, RoomScene>
	{
		[SerializeField]
		private BaseRoomButtonPagedGrid pagedGrid;

		[SerializeField]
		private TextMeshProUGUI infoText;

		private RoomScene targetRoomScene;

		private string newParentRoomName;

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(RoomDetails roomDetails, RoomScene roomScene)
		{
			pagedGrid.SetRooms(Enumerable.Empty<RecNet.Room>());
			targetRoomScene = roomScene;
			SetInfoText(string.Empty, activeButtons: true);
			if (targetRoomScene != null)
			{
				List<RecNet.Room> roomsToShow = new List<RecNet.Room>();
				if (roomDetails.Scenes.Count > 1)
				{
					roomsToShow.Add(null);
				}
				RecNet.Rooms.GetMyCreatedRooms().Then(delegate(List<RecNet.Room> myRooms)
				{
					roomsToShow.AddRange(myRooms.Where((RecNet.Room r) => r.RoomId != targetRoomScene.RoomId));
					pagedGrid.SetRooms(roomsToShow);
				});
			}
			else
			{
				UnityEngine.Debug.LogError("targetRoom is null");
			}
			return base.ShowDialog();
		}

		private void SetInfoText(string info, bool activeButtons)
		{
			infoText.text = info;
			foreach (BaseRoomButton baseRoomButton in pagedGrid.BaseRoomButtons)
			{
				Button3D componentInChildren = baseRoomButton.GetComponentInChildren<Button3D>();
				if (componentInChildren != null)
				{
					componentInChildren.Interactable = activeButtons;
				}
			}
		}

		private void HandleModifyResponse(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to create room: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Success!", 3f);
					Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					SetInfoText("You can't modify rooms!", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					SetInfoText("Error modifying room. Please try again.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PlayerHasRoomUnderModerationReview:
					SetInfoText("Failed to modify room. You have a room under moderation review. Contact conduct@againstgrav.com", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DuplicateName:
					SetInfoText($"There is already a subroom called \"{targetRoomScene.Name}\" in ^{newParentRoomName}!", activeButtons: true);
					break;
				default:
					SetInfoText("Error creating room. If this persists, please contact the developers at support@againstgrav.com.", activeButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to modify room: " + error);
				SetInfoText("Failed to modify room: " + error, activeButtons: true);
			}
		}

		[SkipRename]
		public void Button_ChooseRoom(RecNet.Room room)
		{
			SetInfoText("Updating...", activeButtons: false);
			RecNet.Rooms.ModifySceneParent(targetRoomScene, room?.RoomId ?? (-1), HandleModifyResponse);
		}
	}
	public class ChooseSubroomDialog : ConfirmUIDialog<RoomDetails, bool, List<string>>
	{
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private SubroomButtonPagedGrid pagedGrid;

		[SerializeField]
		private Text infoText;

		private RoomDetails targetRoomDetails;

		private bool goToPrivate;

		private List<string> searchTagsUsed;

		public override IPromise<ConfirmDialogResponses> ShowDialog(RoomDetails roomDetails, bool isPrivate, List<string> searchTagsUsed)
		{
			if (roomDetails == null)
			{
				return new CompletedPromise<ConfirmDialogResponses>(ConfirmDialogResponses.Cancel);
			}
			targetRoomDetails = roomDetails;
			goToPrivate = isPrivate;
			this.searchTagsUsed = searchTagsUsed;
			if (targetRoomDetails.LocalPlayerRole >= RecNet.RoomRole.CoOwner)
			{
				List<string> list = new List<string>();
				list.Add($"Continue to ^{targetRoomDetails.Room.Name}");
				List<string> list2 = list;
				list2.AddRange(targetRoomDetails.Scenes.Select((RoomScene s) => s.Name));
				pagedGrid.SetSceneNames(list2);
			}
			else
			{
				pagedGrid.SetSceneNames(from s in targetRoomDetails.Scenes
					where s.CanMatchmakeInto
					select s.Name);
			}
			SetInfoText(string.Empty, activeButtons: true);
			return base.ShowDialog();
		}

		private void SetInfoText(string info, bool activeButtons)
		{
			infoText.text = info;
		}

		[SkipRename]
		public void Button_ChooseSubroom(string roomSceneName)
		{
			if (!string.IsNullOrEmpty(roomSceneName))
			{
				if (targetRoomDetails.Scenes.Select((RoomScene s) => s.Name).Contains(roomSceneName))
				{
					SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(targetRoomDetails.Room.Name, roomSceneName, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, goToPrivate, searchTagsUsed);
				}
				else
				{
					SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(targetRoomDetails.Room.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, goToPrivate, searchTagsUsed);
				}
				Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
			}
		}
	}
}
namespace RecRoom
{
	public class CreatePlayerEventUI : UnityEngine.MonoBehaviour
	{
		private const int NUM_BUFFER_MINUTES = 20;

		[SerializeField]
		private RawImage eventImage;

		[SerializeField]
		private InputField3D nameField;

		[SerializeField]
		private InputField3D descriptionField;

		[SerializeField]
		private InputField3D tagsField;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private TextMeshProUGUI startDateButtonText;

		[SerializeField]
		private TextMeshProUGUI timeRangeButtonText;

		[SerializeField]
		private TextMeshProUGUI locationButtonText;

		[SerializeField]
		private Slider3D eventAccessibilitySlider;

		[SerializeField]
		private Button3D createButton;

		[SerializeField]
		[Autofill(AutofillType.Parent, false)]
		private EventsScreen parentEventsScreen;

		[SerializeField]
		private UIDateSelectionDialog datePickerPrefab;

		[SerializeField]
		private TimeRangeSelectionDialog timeRangePickerPrefab;

		[SerializeField]
		private ChooseEventLocationDialog locationPickerPrefab;

		private DateTime? startDate;

		private TimeRangeSelectionDialog.StartEndTimes timeRange;

		private RecNet.Room location;

		private void Awake()
		{
			ClearDetails();
		}

		public void ClearDetails()
		{
			SetInfoText(string.Empty);
			eventImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
			nameField.Text = string.Empty;
			descriptionField.Text = string.Empty;
			locationButtonText.text = "Select ^location";
			startDateButtonText.text = "Set Date";
			timeRangeButtonText.text = "Set Time";
			eventAccessibilitySlider.value = EventDetailsScreen.GetSliderValueFromAccessibility(PlayerEventAccessibility.Public);
		}

		private void HandleCreateResponse(CreateModifyPlayerEventResponse response)
		{
			switch (response.Result)
			{
			case CreateModifyPlayerEventStatus.Success:
				ClearDetails();
				AnalyticsHelper.CreatedPlayerEvent(response.PlayerEvent);
				Player.LocalPlayer.PlayerUI.WatchMenu.ShowEventDetails(response.PlayerEvent);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Event Created!", 3f);
				break;
			case CreateModifyPlayerEventStatus.PlayerDoesNotExist:
				infoText.text = "Player doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.RoomDoesNotExist:
				infoText.text = "Room doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.DoesNotOwnRoom:
				infoText.text = "You don't own this room.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateName:
				infoText.text = "Inappropriate name.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateDescription:
				infoText.text = "Inappropriate description.";
				break;
			case CreateModifyPlayerEventStatus.HasModeratorClosedEvent:
				infoText.text = "One of you events is under moderation review. Contact conduct@againstgrav.com";
				break;
			case CreateModifyPlayerEventStatus.EventDatesInvalid:
				infoText.text = "Event date / time is invalid";
				break;
			case CreateModifyPlayerEventStatus.EventTooLong:
				infoText.text = "Event duration is too long";
				break;
			case CreateModifyPlayerEventStatus.EventTooShort:
				infoText.text = "Event duration is too short";
				break;
			case CreateModifyPlayerEventStatus.EventCountLimitReached:
				infoText.text = "You already have the maximum number of open events.";
				break;
			default:
				infoText.text = response.Result.ToString();
				UnityEngine.Debug.LogError(response.Result);
				break;
			}
			createButton.Interactable = true;
		}

		private void SetInfoText(string message)
		{
			infoText.text = message;
		}

		[SkipRename]
		public void Button_CreateEvent()
		{
			string text = CheckFieldsForErrors();
			if (text != null)
			{
				SetInfoText(text);
				return;
			}
			DateTime dateTime = new DateTime(startDate.Value.Year, startDate.Value.Month, startDate.Value.Day, timeRange.startHours24, timeRange.startMinutes, 0, DateTimeKind.Local);
			DateTime dateTime2 = new DateTime(startDate.Value.Year, startDate.Value.Month, startDate.Value.Day, timeRange.endHours24, timeRange.endMinutes, 0, DateTimeKind.Local);
			if (dateTime2 < dateTime)
			{
				dateTime2 = dateTime2.AddDays(1.0);
			}
			if (dateTime < DateTime.Now)
			{
				SetInfoText("Event must start in the future!");
				return;
			}
			createButton.Interactable = false;
			DateTime utcNow = DateTime.UtcNow;
			IPromise<CreateModifyPlayerEventResponse> promise = RecNet.PlayerEvents.CreateEvent(location.RoomId, nameField.Text.Trim(), descriptionField.Text.Trim(), dateTime.ToUniversalTime(), dateTime2.ToUniversalTime(), EventDetailsScreen.GetAccessibilityFromSlider(eventAccessibilitySlider.value));
			promise.Then(HandleCreateResponse).Error(delegate(string errorMsg)
			{
				infoText.text = "Create event error: " + errorMsg;
				createButton.Interactable = true;
			});
		}

		[SkipRename]
		public void Button_ChooseStartDate()
		{
			UIDialog<DateTime?> dialogInstance = null;
			parentEventsScreen.WatchUI.ShowTemporaryDialog(datePickerPrefab, out dialogInstance, (WatchAttractor.EffectFlags)0).Then(delegate(DateTime? dateTimeNullable)
			{
				if (dateTimeNullable.HasValue)
				{
					startDate = dateTimeNullable;
					startDateButtonText.text = GetDateFormatted(startDate.Value);
				}
			});
			UIDateSelectionDialog uIDateSelectionDialog = dialogInstance as UIDateSelectionDialog;
			if (!(uIDateSelectionDialog != null))
			{
				return;
			}
			if (startDate.HasValue)
			{
				uIDateSelectionDialog.SetCurrentDate(startDate.Value);
			}
			else
			{
				uIDateSelectionDialog.SetCurrentDate(DateTime.Today.AddMinutes(20.0));
			}
			uIDateSelectionDialog.DisplayYear = false;
			uIDateSelectionDialog.customDateConversion = delegate(ref int month, ref int day, ref int year)
			{
				DateTime today = DateTime.Today;
				year = today.Year;
				DateTime dateTime = new DateTime(year, month, day, 0, 0, 0, DateTimeKind.Local);
				if (dateTime < today)
				{
					year = today.Year + 1;
				}
			};
		}

		[SkipRename]
		public void Button_ChooseTimeRange()
		{
			UIDialog<TimeRangeSelectionDialog.StartEndTimes> dialogInstance = null;
			parentEventsScreen.WatchUI.ShowTemporaryDialog(timeRangePickerPrefab, out dialogInstance, (WatchAttractor.EffectFlags)0).Then(delegate(TimeRangeSelectionDialog.StartEndTimes enteredTimeRange)
			{
				if (enteredTimeRange != null)
				{
					timeRange = enteredTimeRange;
					timeRangeButtonText.text = GetTimeRangeFormatted(timeRange);
				}
			});
			TimeRangeSelectionDialog timeRangeSelectionDialog = dialogInstance as TimeRangeSelectionDialog;
			if (timeRangeSelectionDialog != null)
			{
				if (timeRange != null)
				{
					timeRangeSelectionDialog.SetTimeRange(timeRange);
					return;
				}
				DateTime dateTime = DateTime.Now.AddMinutes(20.0);
				int num = dateTime.Minute / 15 * 15;
				DateTime dateTime2 = dateTime.AddHours(1.0);
				timeRangeSelectionDialog.SetTimeRange(new TimeRangeSelectionDialog.StartEndTimes
				{
					startHours24 = dateTime.Hour,
					startMinutes = num,
					endHours24 = dateTime2.Hour,
					endMinutes = num
				});
			}
		}

		[SkipRename]
		public void Button_ChooseLocation()
		{
			parentEventsScreen.WatchUI.ShowTemporaryDialog(locationPickerPrefab, (WatchAttractor.EffectFlags)0).Then(delegate(RecNet.Room room)
			{
				if (room != null)
				{
					location = room;
				}
				if (location == null)
				{
					locationButtonText.text = "Choose Location";
					eventImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
				}
				else
				{
					locationButtonText.text = $"^{location.Name}";
					Images.GetRoomImage(room).Then(delegate(Texture2D texture)
					{
						if (this != null && texture != null && location != null && location.ImageName == texture.name)
						{
							eventImage.texture = texture;
						}
					});
				}
			});
		}

		private string CheckFieldsForErrors()
		{
			string text = nameField.Text.Trim();
			string text2 = descriptionField.Text.Trim();
			if (text.Length < 3)
			{
				return "Name too short!";
			}
			if (text.Length > RecNet.PlayerEvents.MAX_NAME_LENGTH)
			{
				return "Name too long!";
			}
			if (text2.Length > RecNet.PlayerEvents.MAX_DESCRIPTION_LENGTH)
			{
				return "Description too long!";
			}
			if (location == null)
			{
				return "Please choose a location!";
			}
			if (!startDate.HasValue)
			{
				return "Please choose a start date!";
			}
			if (timeRange == null)
			{
				return "Please choose a time range!";
			}
			return null;
		}

		private string GetDateFormatted(DateTime localDateTime)
		{
			DateTime dateTime = DateTime.Today.ToLocalTime();
			DateTime dateTime2 = dateTime.AddDays(1.0);
			if (dateTime.Day == localDateTime.Day && dateTime.Month == localDateTime.Month && dateTime.Year == localDateTime.Year)
			{
				return "Today";
			}
			if (dateTime2.Day == localDateTime.Day && dateTime2.Month == localDateTime.Month && dateTime2.Year == localDateTime.Year)
			{
				return "Tomorrow";
			}
			return localDateTime.ToString("dddd, MMMM d");
		}

		private string GetTimeRangeFormatted(TimeRangeSelectionDialog.StartEndTimes range)
		{
			if (range == null)
			{
				return "Time Range";
			}
			return string.Format("{0}:{1:D2}{2} - {3}:{4:D2}{5}", Convert24HrsTo12Hrs(range.startHours24), range.startMinutes, (range.startHours24 < 12) ? "am" : "pm", Convert24HrsTo12Hrs(range.endHours24), range.endMinutes, (range.endHours24 < 12) ? "am" : "pm");
		}

		private int Convert24HrsTo12Hrs(int hour)
		{
			hour %= 12;
			if (hour == 0)
			{
				return 12;
			}
			return hour;
		}
	}
}
namespace AGUI.StackedUI
{
	public class CreateRoomScreen : WatchUIFlow
	{
		[SerializeField]
		private CloneRoomUIDialog cloneDialog;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private SubscreenControl subscreenControl;

		[SerializeField]
		private Subscreen baseRoomsSubscreen;

		[SerializeField]
		private Subscreen myRoomsSubscreen;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private BaseRoomButtonPagedGrid baseRoomsGrid;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RoomButtonPagedGrid myRooomsGrid;

		private bool baseRoomsGridPopulated;

		public Action CloneDialogOpened;

		public Action<bool> CloneDialogClosed;

		public bool BaseRoomsButtonsPopulated => baseRoomsGridPopulated;

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			if (Profiles.LocalProfile.IsJunior())
			{
				return;
			}
			baseRoomsGrid.SetRooms(Enumerable.Empty<RecNet.Room>());
			RecNet.Rooms.GetBaseRooms().Then(delegate(List<RecNet.Room> rooms)
			{
				if (this != null)
				{
					baseRoomsGrid.SetRooms(rooms.OrderBy((RecNet.Room r) => r.Name != "MakerRoom"));
					baseRoomsGridPopulated = true;
				}
			});
			myRooomsGrid.SetLoading();
			RecNet.Rooms.GetMyCreatedRooms().Then(delegate(List<RecNet.Room> myRooms)
			{
				if (this != null)
				{
					myRooomsGrid.SetRooms(myRooms, null);
				}
			});
		}

		public int FindPageIndexOfBaseRoom(string roomName)
		{
			return baseRoomsGrid.FindPageIndexOfRoom(roomName);
		}

		public void SetBaseRoomsCurrentPage(int pageIndex)
		{
			baseRoomsGrid.SetCurrentPage(pageIndex);
		}

		public void ShowBaseRoomsSubscreen()
		{
			subscreenControl.ShowSubscreen(baseRoomsSubscreen);
		}

		[SkipRename]
		public void Button_CopyBaseRoom(RecNet.Room targetRoom)
		{
			base.WatchUI.ShowTemporaryDialog(cloneDialog, targetRoom, (WatchAttractor.EffectFlags)0).Then(delegate(RecNet.Room newRoom)
			{
				if (CloneDialogClosed != null)
				{
					CloneDialogClosed(newRoom != null);
				}
				if (newRoom != null)
				{
					SingletonMonoBehaviour<SessionManager>.Instance.RunJoinRoom(newRoom.Name, SessionManager.LoadSceneSources.CUSTOM_ROOMS_WATCH, isPrivate: true, null);
				}
			});
			if (CloneDialogOpened != null)
			{
				CloneDialogOpened();
			}
		}
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class EditTagsDialog : ConfirmUIDialog<RoomDetails>
	{
		[SerializeField]
		private TextMeshProUGUI autoTagsText;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private InputField3D roomTagsField;

		[SerializeField]
		private GameObject tagTogglesParent;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private Button3D cancelButton;

		[SerializeField]
		private Button3D saveButton;

		private ToggleButton3D[] tagToggles = new ToggleButton3D[0];

		private List<string> playerAddedTags = new List<string>();

		private List<string> hotTags = new List<string>();

		private RoomDetails targetRoom;

		private void Awake()
		{
			tagToggles = tagTogglesParent.GetComponentsInChildren<ToggleButton3D>(includeInactive: true);
			RecNet.Rooms.GetPopularTags().Then(delegate(List<string> popularTags)
			{
				if (this != null)
				{
					hotTags = popularTags;
					for (int i = 0; i < tagToggles.Length; i++)
					{
						tagToggles[i].gameObject.SetActive(i < hotTags.Count);
						if (i < hotTags.Count)
						{
							UIHelper.SafeSetText(tagToggles[i].Label, hotTags[i]);
							int temp = i;
							tagToggles[temp].OnClick.AddListener(delegate(bool isOn)
							{
								Toggle_Tag(temp, isOn);
							});
						}
					}
				}
			});
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(RoomDetails room)
		{
			targetRoom = room;
			if (targetRoom.PlayerAddedTags.Count > 0)
			{
				roomTagsField.InputField.text = string.Format("#{0}", string.Join(", #", targetRoom.PlayerAddedTags.ToArray()));
			}
			if (targetRoom.AutoTags.Count > 0 || targetRoom.AgTags.Count > 0)
			{
				autoTagsText.text = string.Format("#{0}", string.Join(", #", targetRoom.AutoTags.Concat(targetRoom.AgTags).ToArray()));
			}
			SetInfoText(string.Empty, enableButtons: true);
			return base.ShowDialog();
		}

		private void SetInfoText(string info, bool enableButtons)
		{
			infoText.text = info;
			roomTagsField.Interactable = enableButtons;
			ToggleButton3D[] array = tagToggles;
			foreach (ToggleButton3D toggleButton3D in array)
			{
				toggleButton3D.Interactable = enableButtons;
			}
			cancelButton.Interactable = enableButtons;
			saveButton.Interactable = enableButtons;
		}

		private void HandleModifyTagsResponse(string error, RecNet.Rooms.ModifyTagsResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.RoomTagStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to modify tags: " + response);
				}
				string arg = ((response.Tags == null || response.Tags.Count <= 0) ? string.Empty : $"#{response.Tags[0]}");
				switch (response.Result)
				{
				case RecNet.Rooms.RoomTagStatus.Success:
					Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
					break;
				case RecNet.Rooms.RoomTagStatus.TooManyTags:
					SetInfoText("You can only add up to 3 tags", enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.TagUseRestricted:
					SetInfoText($"Restricted tag: {arg}", enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.InvalidTag:
					SetInfoText(string.Format("Invalid tag:", arg), enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.InappropriateTag:
					SetInfoText($"Inappropriate tag: {arg}", enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.TagTooLong:
					SetInfoText($"Maximum 15 characters per tag: {arg}", enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.LacksPermission:
					SetInfoText("You do not have permission to modify this room's tags", enableButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.RoomDoesNotExist:
					SetInfoText("Error: This room does not exist!", enableButtons: true);
					break;
				default:
					SetInfoText("Error modifying tags. If this persists, please contact the developers at support@againstgrav.com.", enableButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to modify tags: " + error);
				SetInfoText("Failed to modify tags: " + error, enableButtons: true);
			}
		}

		private bool ValidateTags()
		{
			if (!string.IsNullOrEmpty(roomTagsField.Text))
			{
				playerAddedTags.Clear();
				string[] array = roomTagsField.Text.Split(new char[4] { '#', ',', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
				if (array.Length > 3)
				{
					infoText.text = "Cannot add more than 3 tags";
					return false;
				}
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (!text.IsAlphaNumeric())
					{
						infoText.text = "Tags can only contain alphabets and numbers";
						return false;
					}
					if (text.Length < 2)
					{
						infoText.text = "Tags must be at least 2 characters long";
						return false;
					}
					if (text.Length > 15)
					{
						infoText.text = "Tags cannot be longer than 15 characters";
						return false;
					}
				}
				playerAddedTags.AddRange(array);
				return true;
			}
			return true;
		}

		[SkipRename]
		public void Toggle_Tag(int index, bool isOn)
		{
			if (index >= hotTags.Count)
			{
				return;
			}
			if (isOn)
			{
				string text = roomTagsField.Text;
				if (!string.IsNullOrEmpty(text))
				{
					text = string.Format("{0}{1}", text, ", ");
				}
				roomTagsField.Text = $"{text}{hotTags[index]}";
				return;
			}
			string[] source = roomTagsField.Text.Split(new char[3] { ',', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
			IEnumerable<string> source2 = source.Where((string sp) => sp != hotTags[index] && sp != $"{'#'}{hotTags[index]}");
			roomTagsField.Text = string.Join(", ", source2.ToArray());
		}

		[SkipRename]
		public void Button_Save()
		{
			if (ValidateTags())
			{
				SetInfoText("Saving...", enableButtons: false);
				RecNet.Rooms.ModifyRoomTags(targetRoom.Room.RoomId, RecNet.Rooms.GenerateAutoTagsForLocalRoom(), playerAddedTags, HandleModifyTagsResponse);
			}
		}
	}
	public class EnterInventionDescriptionDialog : EnterTextDialog<Invention>
	{
		private Invention targetInvention;

		private bool resetInfoText;

		public override IPromise<EnterTextDialogResponse> ShowDialog(Invention invention)
		{
			targetInvention = invention;
			inputField.Text = ((targetInvention != null) ? targetInvention.Description : string.Empty);
			return ShowDialog();
		}

		protected override bool ValidateInput(string str)
		{
			inputString = str.Trim();
			infoText.text = string.Empty;
			return true;
		}

		protected override void ProcessText()
		{
			if (!ValidateInput(inputString))
			{
				return;
			}
			if (targetInvention != null)
			{
				if (targetInvention.Description == inputString)
				{
					Respond(new EnterTextDialogResponse(ConfirmDialogResponses.Affirmative, inputString), shouldCloseDialog: true);
					return;
				}
				UpdateUI("Updating...", enableButtons: false);
				Inventions.UpdateInventionDescription(targetInvention.InventionId, inputString).Then(HandleModifyResponse).Error(delegate(string errMsg)
				{
					UnityEngine.Debug.LogError("Failed to update invention description: " + errMsg);
					UpdateUI("Failed to update invention description: " + errMsg, enableButtons: true);
				});
			}
			else
			{
				Respond(new EnterTextDialogResponse(ConfirmDialogResponses.Affirmative, inputString), shouldCloseDialog: true);
			}
		}

		private void HandleModifyResponse(InventionResponse response)
		{
			if (response.Status == InventionResult.Success)
			{
				Respond(new EnterTextDialogResponse(ConfirmDialogResponses.Affirmative, inputString), shouldCloseDialog: true);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Major, "Invention description updated!", 3f);
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Failed to update invention description: " + response.Status);
				string responseCodeFriendlyMessage = Inventions.GetResponseCodeFriendlyMessage(response.Status);
				UpdateUI(responseCodeFriendlyMessage, enableButtons: true);
			}
		}
	}
