	public struct EnterTextDialogResponse
	{
		public ConfirmDialogResponses responseType;

		public string text;

		public static EnterTextDialogResponse Cancel = new EnterTextDialogResponse(ConfirmDialogResponses.Cancel, null);

		public EnterTextDialogResponse(ConfirmDialogResponses responseType, string text)
		{
			this.responseType = responseType;
			this.text = text;
		}
	}
	public abstract class EnterTextDialog<T> : UIDialog<T, EnterTextDialogResponse>
	{
		[SerializeField]
		private Button3D cancelButton;

		[SerializeField]
		private Button3D saveButton;

		[SerializeField]
		private TextMeshProUGUI cancelButtonText;

		[SerializeField]
		private TextMeshProUGUI saveButtonText;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		protected ValidatedButtonInputField inputField;

		[SerializeField]
		protected TextMeshProUGUI infoText;

		protected string inputString;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			inputField.IsValidFunction = ValidateInput;
		}

		protected virtual bool ValidateInput(string str)
		{
			inputString = str.Trim();
			if (inputString.Length < 2)
			{
				infoText.text = "Must be at least 2 characters long";
				return false;
			}
			infoText.text = string.Empty;
			return true;
		}

		public override IPromise<EnterTextDialogResponse> ShowDialog()
		{
			inputString = string.Empty;
			UpdateUI(string.Empty, enableButtons: true);
			return base.ShowDialog();
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(EnterTextDialogResponse.Cancel, shouldCloseDialog);
		}

		protected void UpdateUI(string info, bool enableButtons)
		{
			inputField.Interactable = enableButtons;
			cancelButton.Interactable = enableButtons;
			saveButton.Interactable = enableButtons;
			infoText.text = info;
		}

		protected abstract void ProcessText();

		public void SetButtonText(string affirmativeText, string negativeText)
		{
			if (saveButtonText != null)
			{
				saveButtonText.text = affirmativeText;
			}
			if (cancelButtonText != null)
			{
				cancelButtonText.text = negativeText;
			}
		}

		[SkipRename]
		public void Button_Cancel()
		{
			ForceCancel(shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_Save()
		{
			ProcessText();
		}
	}
}
