				locationText.text = "^" + room.Name;
			});
			timeText.text = $"{targetEvent.StartTime.ToLocalTime().ToShortTimeString()} - {targetEvent.EndTime.ToLocalTime().ToShortTimeString()}";
			dateText.text = $"{targetEvent.StartTime.ToLocalTime():MM/dd/yy}";
			yesCountText.text = "Yes:\n" + targetEvent.AttendeeCount;
			interestedCountText.text = string.Empty;
			UpdateRsvpStatus();
			organizerProfile = Profiles.Get(targetEvent.CreatorPlayerId);
			organizerInfo.SetProfile(organizerProfile);
			UpdatePlayerSpecificUI(targetEvent.CreatorPlayerId);
			invitedCountText.text = string.Empty;
			UpdateDetailsTabUIState(string.Empty, enableButtons: true);
