		private void UpdateRsvpStatus(PlayerEventResponseType response)
		{
			switch (response)
			{
			case PlayerEventResponseType.Yes:
				yesToggle.IsOn = true;
				return;
			case PlayerEventResponseType.Interested:
				interestedToggle.IsOn = true;
				return;
			case PlayerEventResponseType.No:
				noToggle.IsOn = true;
				return;
			}
			yesToggle.IsOn = false;
			interestedToggle.IsOn = false;
			noToggle.IsOn = false;
		}

		private void UpdateDetailsTabUIState(string statusText, bool enableButtons)
		{
