			infoText.text = statusText;
			eventImageButton.Interactable = false;
			editEventNameButton.Interactable = enableButtons && targetEvent.IsOrganizedByLocalPlayer;
			editEventDescriptionButton.Interactable = enableButtons && targetEvent.IsOrganizedByLocalPlayer;
			editEventTagsButton.Interactable = enableButtons && targetEvent.IsOrganizedByLocalPlayer;
			yesToggle.Interactable = enableButtons;
			interestedToggle.Interactable = enableButtons;
			noToggle.Interactable = enableButtons;
			organizerInfoButton.Interactable = enableButtons && !targetEvent.IsOrganizedByLocalPlayer;
			reportButton.Interactable = enableButtons && !targetEvent.IsOrganizedByLocalPlayer;
			inviteFriendsButton.Interactable = enableButtons;
			goToEventButton.ForcedButtonState = ((!enableButtons) ? new GoToPlayerEventConditionalButton.GoToPlayerEventButtonState?(GoToPlayerEventConditionalButton.GoToPlayerEventButtonState.Disabled) : ((GoToPlayerEventConditionalButton.GoToPlayerEventButtonState?)null));
