		private void UpdateSetupTab()
		{
			saveChangesButton.Interactable = false;
			newRoomLocation = null;
			newTimeRange = null;
			newDate = null;
			newEventAccessibility = null;
			if (targetEvent != null)
			{
				eventAccessibilitySlider.value = GetSliderValueFromAccessibility(targetEvent.Accessibility);
			}
		}

		private bool HasChanges()
		{
			if (targetEvent == null)
			{
				return false;
			}
			if (newRoomLocation != null && newRoomLocation.RoomId != targetEvent.RoomId)
			{
				return true;
			}
			PlayerEventAccessibility? playerEventAccessibility = newEventAccessibility;
			if (playerEventAccessibility.HasValue)
			{
				PlayerEventAccessibility? playerEventAccessibility2 = newEventAccessibility;
				if (playerEventAccessibility2.GetValueOrDefault() != targetEvent.Accessibility || !playerEventAccessibility2.HasValue)
				{
					return true;
				}
			}
			DateTime dateTime = targetEvent.StartTime.ToLocalTime();
			DateTime dateTime2 = targetEvent.EndTime.ToLocalTime();
			DateTime? dateTime3 = newDate;
			if (dateTime3.HasValue && (newDate.Value.Month != dateTime.Month || newDate.Value.Day != dateTime.Day || newDate.Value.Year != dateTime.Year))
			{
				return true;
			}
			if (newTimeRange != null && (newTimeRange.startHours24 != dateTime.Hour || newTimeRange.startMinutes != dateTime.Minute || newTimeRange.endHours24 != dateTime2.Hour || newTimeRange.endMinutes != dateTime2.Minute))
			{
				return true;
			}
			return false;
		}

		private void UpdatePlayerSpecificUI(long? profileId)
		{
			PlayerSpecificUIBehaviour[] array = playerSpecificBehaviors;
			foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in array)
			{
				playerSpecificUIBehaviour.SetPlayer(profileId);
			}
		}

		private void RsvpToEvent(PlayerEventResponseType response, bool isOn)
		{
			if (isOn)
			{
				AnalyticsHelper.RSVPToEvent(targetEvent, targetEvent.PlayerEventId, response);
				RecNet.PlayerEvents.RespondToEvent(targetEvent.PlayerEventId, response).Then(delegate(CreateModifyPlayerEventStatus result)
				{
					if (result != CreateModifyPlayerEventStatus.Success)
					{
						UpdateRsvpStatus();
						HandleModifyResponse(result);
					}
				}).Error(delegate
				{
					UpdateRsvpStatus();
				});
				return;
			}
			AnalyticsHelper.RSVPToEvent(targetEvent, targetEvent.PlayerEventId, PlayerEventResponseType.None);
			RecNet.PlayerEvents.DeleteResponse(targetEvent.PlayerEventId, response).Then(delegate(CreateModifyPlayerEventStatus result)
			{
				if (result != CreateModifyPlayerEventStatus.Success)
				{
					UpdateRsvpStatus();
					HandleModifyResponse(result);
				}
			}).Error(delegate
			{
				UpdateRsvpStatus();
			});
		}

		private void PlayerEvents_PlayerEventResponseChanged(PlayerEvent playerEvent, PlayerEventResponse response)
		{
			if (playerEvent == targetEvent)
			{
				UpdateRsvpStatus(response.Type);
			}
		}

		private void PlayerEvents_PlayerEventResponseDeleted(PlayerEvent playerEvent, PlayerEventResponse response)
		{
			if (playerEvent == targetEvent)
			{
				UpdateRsvpStatus(PlayerEventResponseType.None);
			}
		}

		private void PlayerEvents_PlayerEventUpdated(PlayerEvent playerEvent)
		{
			if (targetEvent != null && targetEvent.PlayerEventId == playerEvent.PlayerEventId)
			{
				targetEvent = playerEvent;
				UpdateDetailsTab();
				UpdateSetupTab();
			}
		}

		private void Profiles_OnProfileUpdated(long id)
		{
			if (targetEvent != null && targetEvent.CreatorPlayerId == id && (long)Profiles.LocalProfile.Id != id)
			{
				organizerProfile = Profiles.Get(id);
				organizerInfoButton.Interactable = true;
				organizerInfo.SetProfile(organizerProfile);
				UpdatePlayerSpecificUI(id);
			}
		}

		private void HandleModifyResponse(CreateModifyPlayerEventStatus result)
		{
			switch (result)
			{
			case CreateModifyPlayerEventStatus.Success:
				UpdateSetupTab();
				UpdateDetailsTab();
				detailsButton.ForcePressed();
				infoText.text = "Success!";
				break;
			case CreateModifyPlayerEventStatus.PlayerDoesNotExist:
				infoText.text = "Player doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.RoomDoesNotExist:
				infoText.text = "Room doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.DoesNotOwnRoom:
				infoText.text = "You don't own this room.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateName:
				infoText.text = "Inappropriate name.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateDescription:
				infoText.text = "Inappropriate description.";
				break;
			case CreateModifyPlayerEventStatus.HasModeratorClosedEvent:
				infoText.text = "One of you events is under moderation review. Contact conduct@againstgrav.com";
				break;
			case CreateModifyPlayerEventStatus.EventDatesInvalid:
				infoText.text = "Event date / time is invalid";
				break;
			case CreateModifyPlayerEventStatus.EventTooLong:
				infoText.text = "Event duration is too long";
				break;
			case CreateModifyPlayerEventStatus.EventTooShort:
				infoText.text = "Event duration is too short";
				break;
			case CreateModifyPlayerEventStatus.DoesNotExist:
				infoText.text = "Event does not exist.";
				break;
			case CreateModifyPlayerEventStatus.PrivateEvent:
				infoText.text = "Event is private.";
				break;
			case CreateModifyPlayerEventStatus.EventCountLimitReached:
				infoText.text = "You already have the maximum number of open events.";
				break;
			default:
				UnityEngine.Debug.LogError(result);
				break;
			}
		}

