			{
				DateTime dateTime = targetEvent.StartTime.ToLocalTime();
				DateTime dateTime2 = targetEvent.EndTime.ToLocalTime();
				DateTime? dateTime3 = newDate;
				if (dateTime3.HasValue)
				{
					dateTime = new DateTime(newDate.Value.Year, newDate.Value.Month, newDate.Value.Day, dateTime.Hour, dateTime.Minute, 0, DateTimeKind.Local);
					dateTime2 = new DateTime(newDate.Value.Year, newDate.Value.Month, newDate.Value.Day, dateTime2.Hour, dateTime2.Minute, 0, DateTimeKind.Local);
				}
				if (newTimeRange != null)
				{
					dateTime = new DateTime(dateTime.Year, dateTime.Month, dateTime.Day, newTimeRange.startHours24, newTimeRange.startMinutes, 0, DateTimeKind.Local);
					dateTime2 = new DateTime(dateTime2.Year, dateTime2.Month, dateTime2.Day, newTimeRange.endHours24, newTimeRange.startMinutes, 0, DateTimeKind.Local);
				}
				if (dateTime2 < dateTime)
				{
					dateTime2 = dateTime2.AddDays(1.0);
				}
				saveChangesButton.interactable = false;
				PlayerEvent playerEvent = targetEvent;
				long roomId = ((newRoomLocation == null) ? targetEvent.RoomId : newRoomLocation.RoomId);
				string text = targetEvent.Name;
				string description = targetEvent.Description;
				DateTime startTime = dateTime.ToUniversalTime();
				DateTime endTime = dateTime2.ToUniversalTime();
				PlayerEventAccessibility? playerEventAccessibility = newEventAccessibility;
				IPromise<CreateModifyPlayerEventResponse> promise = RecNet.PlayerEvents.ModifyEvent(playerEvent, roomId, text, description, startTime, endTime, (!playerEventAccessibility.HasValue) ? targetEvent.Accessibility : newEventAccessibility.Value);
