		public static PlayerEventAccessibility GetAccessibilityFromSlider(float sliderValue)
		{
			if (sliderValue < 0.5f)
			{
				return PlayerEventAccessibility.Public;
			}
			if (sliderValue < 1.5f)
			{
				return PlayerEventAccessibility.Unlisted;
			}
			return PlayerEventAccessibility.Private;
		}

		public static float GetSliderValueFromAccessibility(PlayerEventAccessibility playerEventAccessibility)
		{
			return playerEventAccessibility switch
			{
				PlayerEventAccessibility.Public => 0f, 
				PlayerEventAccessibility.Unlisted => 1f, 
				PlayerEventAccessibility.Private => 2f, 
				_ => 0f, 
			};
		}

		private string GetDateFormatted(DateTime localDateTime)
		{
			DateTime dateTime = DateTime.Today.ToLocalTime();
			DateTime dateTime2 = dateTime.AddDays(1.0);
			if (dateTime.Day == localDateTime.Day && dateTime.Month == localDateTime.Month && dateTime.Year == localDateTime.Year)
			{
				return "Today";
			}
			if (dateTime2.Day == localDateTime.Day && dateTime2.Month == localDateTime.Month && dateTime2.Year == localDateTime.Year)
			{
				return "Tomorrow";
			}
			return localDateTime.ToString("dddd, MMMM d");
		}

		private string GetTimeRangeFormatted(TimeRangeSelectionDialog.StartEndTimes range)
		{
			if (range == null)
			{
				return "Time Range";
			}
			return string.Format("{0}:{1:D2}{2} - {3}:{4:D2}{5}", Convert24HrsTo12Hrs(range.startHours24), range.startMinutes, (range.startHours24 < 12) ? "am" : "pm", Convert24HrsTo12Hrs(range.endHours24), range.endMinutes, (range.endHours24 < 12) ? "am" : "pm");
		}

		private int Convert24HrsTo12Hrs(int hour)
		{
			hour %= 12;
			if (hour == 0)
			{
				return 12;
			}
			return hour;
		}
	}
	public class EventsScreen : WatchUIFlow
	{
		private enum DisplayMode
		{
			None,
			AllEvents,
			MyEvents,
			CreateEvent,
			Search
		}

		private class PageData
		{
			public string FirstGroupDateLabel;

			public IEnumerable<PlayerEvent> FirstGroupEvents;

			public string SecondGroupDateLabel;

			public IEnumerable<PlayerEvent> SecondGroupEvents;

			public int FirstEventIdx;

			public int LastEventIdx;
		}

		[Header("Radio Buttons")]
		[SerializeField]
		private GameObject contextRow;

		[SerializeField]
		private RadioButton3D allRadioButton;

		[SerializeField]
		private RadioButton3D myEventsRadioButton;

		[SerializeField]
		private RadioButton3D createRadioButton;

		[SerializeField]
		private RadioButton3D searchRadioButton;

		[Header("Event grids")]
		[SerializeField]
		private TextMeshProUGUI firstGridDateLabel;

		[SerializeField]
		private GameObject firstGridDivider;

		[SerializeField]
		private PlayerEventButtonPagedGrid firstGrid;

		[SerializeField]
		private TextMeshProUGUI secondGridDateLabel;

		[SerializeField]
		private GameObject secondGridDivider;

		[SerializeField]
		private PlayerEventButtonPagedGrid secondGrid;

		[SerializeField]
		private GameObject noCreatedEventsObject;

		[Header("Paging")]
		[SerializeField]
		protected RectTransform pageControls;

		[SerializeField]
		private Selectable previousPageButton;

		[SerializeField]
		private Selectable nextPageButton;

		[SerializeField]
		protected PageDisplay pageDisplay;

		private List<PlayerEvent> currentEvents;

		private List<PageData> eventsPages = new List<PageData>();

		private bool needsRefreshOnEnable;

		private int currentPageIdx;

		private DisplayMode eventsDisplayMode;

		private int TotalPages => eventsPages.Count;

		private DisplayMode EventsDisplayMode
		{
			get
			{
				return eventsDisplayMode;
			}
			set
			{
				if (eventsDisplayMode != value)
				{
					eventsDisplayMode = value;
					if (base.IsCurrentFlow)
					{
						UpdateGridForDisplayMode(refreshEventList: true);
					}
				}
			}
		}

		private void Awake()
		{
			firstGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
			secondGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
			RecNet.PlayerEvents.PlayerEventCreated += OnEventCacheChanged;
			RecNet.PlayerEvents.PlayerEventUpdated += OnEventCacheChanged;
			RecNet.PlayerEvents.PlayerEventDeleted += OnEventCacheChanged;
		}

		private void OnEnable()
		{
			if (needsRefreshOnEnable)
			{
				UpdateGridForDisplayMode(refreshEventList: true);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			RecNet.PlayerEvents.PlayerEventCreated -= OnEventCacheChanged;
			RecNet.PlayerEvents.PlayerEventUpdated -= OnEventCacheChanged;
			RecNet.PlayerEvents.PlayerEventDeleted -= OnEventCacheChanged;
		}

		private void OnEventCacheChanged(PlayerEvent ignore)
		{
			if (base.isActiveAndEnabled)
			{
				UpdateGridForDisplayMode(refreshEventList: true);
			}
			else
			{
				needsRefreshOnEnable = true;
			}
		}

		private void UpdateGridForDisplayMode(bool refreshEventList)
		{
			if (refreshEventList)
			{
				switch (EventsDisplayMode)
				{
				case DisplayMode.AllEvents:
					RecNet.PlayerEvents.GetUpcomingEvents().Then(delegate(List<PlayerEvent> events)
					{
						OnEventListReceived(events, DisplayMode.AllEvents);
					});
					break;
				case DisplayMode.MyEvents:
					OnEventListReceived(RecNet.PlayerEvents.GetAllEventsForThisPlayerFromCache(), DisplayMode.MyEvents);
					break;
				}
			}
			UpdateTabButtons();
		}

		private void UpdateTabButtons()
		{
			RadioButton3D radioButton3D = null;
			switch (EventsDisplayMode)
			{
			case DisplayMode.AllEvents:
				radioButton3D = allRadioButton;
				break;
			case DisplayMode.MyEvents:
				radioButton3D = myEventsRadioButton;
				break;
			case DisplayMode.CreateEvent:
				radioButton3D = createRadioButton;
				break;
			case DisplayMode.Search:
				radioButton3D = searchRadioButton;
				break;
			}
			if (radioButton3D != null)
			{
				radioButton3D.ForcePressed();
			}
		}

		private void OnEventListReceived(IEnumerable<PlayerEvent> events, DisplayMode mode)
		{
			if (this != null && base.IsCurrentFlow && EventsDisplayMode == mode)
			{
				currentEvents = events.ToList();
				currentPageIdx = 0;
				eventsPages = CalculatePageGroupings(currentEvents, 4);
				AssignEventsToGrids();
				UpdatePagingControls();
			}
		}

		private void AssignEventsToGrids()
		{
			if (eventsPages.Count == 0 || currentPageIdx < 0 || currentPageIdx >= eventsPages.Count)
			{
				noCreatedEventsObject.SetActive(value: true);
				firstGridDateLabel.text = string.Empty;
				firstGridDivider.SetActive(value: false);
				firstGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
				secondGridDateLabel.text = string.Empty;
				secondGridDivider.SetActive(value: false);
				secondGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
				return;
			}
			noCreatedEventsObject.SetActive(value: false);
			PageData pageData = eventsPages[currentPageIdx];
			if (pageData.FirstGroupDateLabel == null)
			{
				firstGridDateLabel.text = string.Empty;
				firstGridDivider.SetActive(value: false);
				firstGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
			}
			else
			{
				firstGridDateLabel.text = pageData.FirstGroupDateLabel;
				firstGridDivider.SetActive(value: true);
				firstGrid.SetPlayerEvents(pageData.FirstGroupEvents);
			}
			if (pageData.SecondGroupDateLabel == null)
			{
				secondGridDateLabel.text = string.Empty;
				secondGridDivider.SetActive(value: false);
				secondGrid.SetPlayerEvents(Enumerable.Empty<PlayerEvent>());
			}
			else
			{
				secondGridDateLabel.text = pageData.SecondGroupDateLabel;
				secondGridDivider.SetActive(value: true);
				secondGrid.SetPlayerEvents(pageData.SecondGroupEvents);
			}
		}

		private void UpdatePagingControls()
		{
			pageControls.gameObject.SetActive(TotalPages > 1);
			previousPageButton.interactable = currentPageIdx > 0;
			nextPageButton.interactable = currentPageIdx + 1 < TotalPages;
			pageDisplay.UpdatePageDisplay(currentPageIdx, TotalPages);
		}

		[SkipRename]
		public void Button_AllEventsDisplayMode()
		{
			EventsDisplayMode = DisplayMode.AllEvents;
		}

		[SkipRename]
		public void Button_MyEventsDisplayMode()
		{
			EventsDisplayMode = DisplayMode.MyEvents;
		}

		[SkipRename]
		public void Button_CreateEventDisplayMode()
		{
			EventsDisplayMode = DisplayMode.CreateEvent;
		}

		[SkipRename]
		public void Button_SearchDisplayMode()
		{
			EventsDisplayMode = DisplayMode.Search;
		}

		[SkipRename]
		public void Button_NextPage()
		{
			if (currentPageIdx + 1 < TotalPages)
			{
				currentPageIdx++;
				AssignEventsToGrids();
				UpdatePagingControls();
			}
			UpdatePagingControls();
		}

		[SkipRename]
		public void Button_PreviousPage()
		{
			if (currentPageIdx > 0)
			{
				currentPageIdx--;
				AssignEventsToGrids();
				UpdatePagingControls();
			}
		}

		private bool IsSameDay(DateTime day1, DateTime day2)
		{
			return day1.DayOfYear == day2.DayOfYear && day1.Month == day2.Month && day1.Year == day2.Year;
		}

		private int GetEndIndexForGroup(List<PlayerEvent> eventsList, int searchStartIdx)
		{
			int i = searchStartIdx + 1;
			if (eventsList[searchStartIdx].IsHappeningNow)
			{
				for (; i < eventsList.Count && eventsList[i].IsHappeningNow; i++)
				{
				}
			}
			else
			{
				for (DateTime day = eventsList[searchStartIdx].StartTime.ToLocalTime(); i < eventsList.Count && IsSameDay(day, eventsList[i].StartTime.ToLocalTime()); i++)
				{
				}
			}
			return i - 1;
		}

		private List<PageData> CalculatePageGroupings(List<PlayerEvent> eventsList, int maxEventsPerRow, int numRows = 2)
		{
			int val = maxEventsPerRow * numRows;
			List<PageData> list = new List<PageData>();
			int num = 0;
			while (num < eventsList.Count)
			{
				PageData pageData = new PageData();
				int endIndexForGroup = GetEndIndexForGroup(currentEvents, num);
				int val2 = endIndexForGroup - num + 1;
				int num2 = Math.Min(val2, val);
				endIndexForGroup = num + num2 - 1;
				pageData.FirstEventIdx = num;
				pageData.FirstGroupDateLabel = GetDateLabel(currentEvents[num]);
				pageData.FirstGroupEvents = currentEvents.SkipTake(num, num2);
				bool flag = num2 <= maxEventsPerRow;
				bool flag2 = endIndexForGroup + 1 < currentEvents.Count;
				if (flag && flag2)
				{
					int num3 = endIndexForGroup + 1;
					endIndexForGroup = GetEndIndexForGroup(currentEvents, num3);
					val2 = endIndexForGroup - num3 + 1;
					num2 = Math.Min(val2, maxEventsPerRow);
					endIndexForGroup = num3 + num2 - 1;
					pageData.SecondGroupDateLabel = GetDateLabel(currentEvents[num3]);
					pageData.SecondGroupEvents = currentEvents.SkipTake(num3, num2);
				}
				pageData.LastEventIdx = endIndexForGroup;
				list.Add(pageData);
				num = endIndexForGroup + 1;
			}
			return list;
		}

		private string GetDateLabel(PlayerEvent playerEvent)
		{
			if (playerEvent.IsHappeningNow)
			{
				return "Now";
			}
			DateTime dateTime = playerEvent.StartTime.ToLocalTime();
			DateTime dateTime2 = DateTime.Today.ToLocalTime();
			DateTime dateTime3 = dateTime2.AddDays(1.0);
			if (dateTime2.Day == dateTime.Day && dateTime2.Month == dateTime.Month && dateTime2.Year == dateTime.Year)
			{
				return "Today";
			}
			if (dateTime3.Day == dateTime.Day && dateTime3.Month == dateTime.Month && dateTime3.Year == dateTime.Year)
			{
				return "Tomorrow";
			}
			return dateTime.ToString("dddd, MMMM d");
		}
	}
