	private void UpdateCustomGameOptions()
	{
		if (customGameControls == null)
		{
			customGameControls = customGameOptionsRoot.GetComponentsInChildren<Selectable>();
		}
		if (gameManager == null || GameSessions.LocalGameSession.IsSandbox)
		{
			customGameOptionsRoot.gameObject.SetActive(value: false);
			return;
		}
		customGameOptionsRoot.gameObject.SetActive(value: true);
		bool canEditCustomGameSettings = gameManager.CustomGameSettings.CanEditCustomGameSettings;
		Selectable[] array = customGameControls;
		foreach (Selectable selectable in array)
		{
			selectable.interactable = canEditCustomGameSettings;
		}
		customGameMaxScoreRoot.gameObject.SetActive(gameManager.CustomGameSettings.CurrentModeSupportsCustomScoreToWin);
		customGameMaxScoreButton.Label.text = gameManager.ScoreManager.ScoreToWinAndUnitsString.ToUpper();
		customGameDurationRoot.gameObject.SetActive(gameManager.CustomGameSettings.CurrentModeSupportsCustomDuration);
		customGameDurationButton.Label.text = gameManager.GameTimerManager.Duration.ToTimeString();
		customGameFieldItemsEnabledRoot.gameObject.SetActive(gameManager.CustomGameSettings.SupportsCustomFieldItemsOverride);
		customGameFieldItemsEnabledButton.Label.text = ((!gameManager.SpawnManager.FieldEquipmentEnabled) ? "OFF" : "ON");
		customGameStartItem1Root.gameObject.SetActive(gameManager.CustomGameSettings.SupportsCustomSpawnEquipment);
		customGameStartItem1Button.Label.text = SpawnableToolSettings.GetSpawnableToolFriendlyName(gameManager.SpawnManager.DominantHandSpawnEquipment).ToUpper();
		customGameStartItem2Root.gameObject.SetActive(gameManager.CustomGameSettings.SupportsCustomSpawnEquipment);
		customGameStartItem2Button.Label.text = SpawnableToolSettings.GetSpawnableToolFriendlyName(gameManager.SpawnManager.OffHandSpawnEquipment).ToUpper();
		gameControlsGrid.RefreshChildren();
	}

	private void UpdateSandboxGameOptions()
	{
		if (sandboxGameControls == null)
		{
			sandboxGameControls = sandboxGameOptionsRoot.GetComponentsInChildren<Selectable>();
		}
		if (!GameSessions.LocalGameSession.IsSandbox)
		{
			sandboxGameOptionsRoot.gameObject.SetActive(value: false);
			endSandboxGameButton.gameObject.SetActive(value: false);
			return;
		}
		sandboxGameOptionsRoot.gameObject.SetActive(value: true);
		endSandboxGameButton.gameObject.SetActive(value: true);
		bool canEditCustomGameSettings = gameManager.CustomGameSettings.CanEditCustomGameSettings;
		Selectable[] array = sandboxGameControls;
		foreach (Selectable selectable in array)
		{
			selectable.interactable = canEditCustomGameSettings;
		}
		UpdateSandboxTimeLimitSlider(updateSliderValue: true);
		if (NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning)
		{
			endGameButtonLabel.text = "END GAME";
		}
		else
		{
			endGameButtonLabel.text = "START GAME";
		}
		endSandboxGameButton.Interactable = PlayerRoomRoleManager.Instance.GetLocalPlayerRoleDefinition().CanStartGames.Value && (NetworkedSingletonMonoBehaviour<GameManager>.Instance.CurrentPreGameState == PreGameSubStates.WAITING_FOR_START_GAME || NetworkedSingletonMonoBehaviour<GameManager>.Instance.IsGameRunning);
	}

	private void UpdateSandboxTimeLimitSlider(bool updateSliderValue)
	{
		if (gameManager != null)
		{
			if (updateSliderValue)
			{
				float duration = NetworkedSingletonMonoBehaviour<GameManager>.Instance.GameTimerManager.Duration;
				sandboxTimeLimitSlider.value = TimeLimitMinutesToSliderValue((int)(duration / 60f));
			}
			int num = SliderValueToTimeLimitMinutes();
			string arg = "∞";
			if (num > 0)
			{
				arg = $"{num.ToString()}m";
			}
			sandboxTimeLimitSliderText.text = $"{sandboxTimeLimitLabel} ({arg})";
		}
	}

	private int SliderValueToTimeLimitMinutes()
	{
		int num = (int)sandboxTimeLimitSlider.FloatOrRoundedValue;
		if ((float)num == sandboxTimeLimitSlider.maxValue)
		{
			return -1;
		}
		int num2 = Mathf.Min(num, highAccuracyTimeLimitMaxValue);
		int num3 = Mathf.Max(0, num - num2);
		return num2 + num3 * lowAccuracyTimeLimitIncrement;
	}

	private int TimeLimitMinutesToSliderValue(int minutes)
	{
		if (minutes <= 0)
		{
			return (int)sandboxTimeLimitSlider.maxValue;
		}
		int num = Mathf.Min(highAccuracyTimeLimitMaxValue, minutes);
		int num2 = Mathf.Max(0, minutes - num);
		return num + num2 / lowAccuracyTimeLimitIncrement;
	}

