namespace RecRoom.AGUI
{
	public class InviteFriendButton : UnityEngine.MonoBehaviour
	{
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private ToggleButton3D toggle;

		[SerializeField]
		private UnityEngine.UI.Image background;

		[SerializeField]
		private Color defaultColor;

		[SerializeField]
		private Color cantInviteColor;

		[SerializeField]
		private GameObject selectedVisual;

		[SerializeField]
		private Text rsvpText;

		private PlayerSpecificUIBehaviour[] playerSpecificUIs = new PlayerSpecificUIBehaviour[0];

		public Profile CurrentProfile { get; private set; }

		public ToggleButton3D.OnToggleButton3DClick ButtonAction => toggle.OnClick;

		private void Awake()
		{
			playerSpecificUIs = GetComponentsInChildren<PlayerSpecificUIBehaviour>(includeInactive: true);
			ButtonAction.AddListener(delegate(bool isOn)
			{
				selectedVisual.SetActive(isOn);
			});
		}

		public void SetProfile(Profile profile, PlayerEventResponseType responseType, bool isSelected)
		{
			if (CurrentProfile == profile)
			{
				return;
			}
			CurrentProfile = profile;
			if (CurrentProfile != null)
			{
				selectedVisual.SetActive(isSelected);
				bool flag = responseType == PlayerEventResponseType.None;
				rsvpText.text = ((!flag) ? responseType.ToString() : string.Empty);
				toggle.Interactable = flag;
				background.color = ((!flag) ? cantInviteColor : defaultColor);
				PlayerSpecificUIBehaviour[] array = playerSpecificUIs;
				foreach (PlayerSpecificUIBehaviour playerSpecificUIBehaviour in array)
				{
					playerSpecificUIBehaviour.SetPlayer(CurrentProfile.Id);
				}
			}
		}
	}
	public class InviteFriendButtonsPagedGrid : RecyclerPagedGrid<Profile, InviteFriendButton>
	{
		[Serializable]
		public class SelectedFriendsUpdated : UnityEvent<List<Profile>>
		{
		}

		public SelectedFriendsUpdated OnSelectedFriendsUpdatedEvent;

		private List<Profile> selectedProfiles = new List<Profile>();

		private List<PlayerEventResponse> responses = new List<PlayerEventResponse>();

		private void Start()
		{
			if (OnSelectedFriendsUpdatedEvent == null)
			{
				return;
			}
			foreach (InviteFriendButton childUIElement in childUIElements)
			{
				InviteFriendButton innerChild = childUIElement;
				innerChild.ButtonAction.AddListener(delegate(bool isOn)
				{
					Profile currentProfile = innerChild.CurrentProfile;
					if (isOn && !selectedProfiles.Contains(currentProfile))
					{
						selectedProfiles.Add(currentProfile);
						OnSelectedFriendsUpdatedEvent.Invoke(selectedProfiles);
					}
					else if (!isOn && selectedProfiles.Contains(currentProfile))
					{
						selectedProfiles.Remove(currentProfile);
						OnSelectedFriendsUpdatedEvent.Invoke(selectedProfiles);
					}
				});
			}
		}

		public new void SetLoading()
		{
			SetAllActiveChildren(Enumerable.Empty<Profile>());
			UIHelper.SafeSetText(emptyDisplayText, "Loading...");
		}

		public void SetProfiles(IEnumerable<Profile> profiles, List<PlayerEventResponse> playerResponses)
		{
			responses = playerResponses;
			List<Profile> allActiveChildren = profiles.OrderBy(delegate(Profile profile)
			{
				Relationship relationship = Relationships.Get(profile.Id);
				return relationship == null || !relationship.IsFavorited;
			}).ThenBy((Profile profile) => profile.DisplayName.GetDecrypted()).ThenBy((Profile profile) => profile.Username.GetDecrypted())
				.ToList();
			SetAllActiveChildren(allActiveChildren);
		}

		protected override void SetChild(Profile profile, InviteFriendButton button, int activeIndex)
		{
			PlayerEventResponse playerEventResponse = responses.Find((PlayerEventResponse r) => r.PlayerId == (long)profile.Id);
			button.SetProfile(profile, playerEventResponse?.Type ?? PlayerEventResponseType.None, selectedProfiles.Contains(profile));
		}
	}
}
public class InviteFriendsDialog : ConfirmUIDialog<PlayerEvent>
{
	[SerializeField]
	private Text invitedNamesText;

	[SerializeField]
	private Button3D sendInvitesButton;

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private InviteFriendButtonsPagedGrid pagedGrid;

	[SerializeField]
	private Text infoText;

	private PlayerEvent targetEvent;

	private List<Profile> selectedProfiles = new List<Profile>();

	public override IPromise<ConfirmDialogResponses> ShowDialog(PlayerEvent playerEvent)
	{
		targetEvent = playerEvent;
		sendInvitesButton.Interactable = false;
		invitedNamesText.text = string.Empty;
		infoText.text = string.Empty;
		RecNet.PlayerEvents.GetAllPlayerEventResponses(targetEvent.PlayerEventId).Then(delegate(List<PlayerEventResponse> responses)
		{
			IEnumerable<Profile> profiles = from r in Relationships.GetAll()
				where r.IsFriend
				select Profiles.Get(r.PlayerID) into p
				where p != null && !p.IsJunior()
				select p;
			pagedGrid.SetProfiles(profiles, responses);
		});
		return base.ShowDialog();
	}

	private void HandleInviteResponse(BulkInviteResponse response)
	{
		switch (response.Result)
		{
		case CreateModifyPlayerEventStatus.Success:
			SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Successfully invited friends!", 3f);
			Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
			break;
		case CreateModifyPlayerEventStatus.DoesNotExist:
			infoText.text = "Error: Event does not exist.";
			break;
		case CreateModifyPlayerEventStatus.DoesNotOwnRoom:
			infoText.text = "Error: Only the event organizer can send invites for a private event.";
			break;
		case CreateModifyPlayerEventStatus.HasModeratorClosedEvent:
			infoText.text = "Error: This event is under moderation review. Contact conduct@againstgrav.com";
			break;
		case CreateModifyPlayerEventStatus.SomeInvitesFailed:
			ShowPlayerInvitesFailedReason(response.FailedInvites);
			break;
		}
	}

	private void ShowPlayerInvitesFailedReason(List<InviteResponse> responses)
	{
		string text = string.Empty;
		foreach (InviteResponse response in responses)
		{
			Profile profile = Profiles.Get(response.InvitedPlayerId);
			switch (response.Result)
			{
			case CreateModifyPlayerEventStatus.CannotInviteJunior:
				text = $"{text}{profile.DisplayName} is a junior.\n\n";
				break;
			case CreateModifyPlayerEventStatus.PlayerDoesNotExist:
				text = $"{text}{profile.DisplayName} does not exist.\n\n";
				break;
			default:
				text = $"{text}Error inviting {profile.DisplayName}: {response.Result.ToString()}\n\n";
				break;
			case CreateModifyPlayerEventStatus.Success:
			case CreateModifyPlayerEventStatus.PlayerAlreadyInvited:
				break;
			}
		}
		if (!string.IsNullOrEmpty(text))
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_ONLY, "Some invites failed", text);
			return;
		}
		SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Successfully invited friends!", 3f);
		Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
	}

	[SkipRename]
	public void SelectedProfilesUpdated(List<Profile> newProfiles)
	{
		selectedProfiles = newProfiles;
		invitedNamesText.text = string.Join(", ", selectedProfiles.Select((Profile p) => p.DisplayName.ToString()).ToArray());
		sendInvitesButton.Interactable = selectedProfiles.Count > 0;
	}

	[SkipRename]
	public void Button_SendInvites()
	{
		if (selectedProfiles.Count > 0)
		{
			AnalyticsHelper.InvitedPlayersToEvent(targetEvent, selectedProfiles.Count);
			RecNet.PlayerEvents.InvitePlayers(targetEvent.PlayerEventId, selectedProfiles.Select((Profile p) => (int)(long)p.Id).ToList()).Then(HandleInviteResponse);
		}
	}
