namespace AGUI.StackedUI.Dialog
{
	public class PublishRoomDialog : UIDialog<RoomDetails, ConfirmDialogResponses>
	{
		[SerializeField]
		private ValidatedButtonInputField roomNameField;

		[SerializeField]
		private ValidatedButtonInputField roomDescriptionField;

		[SerializeField]
		private ValidatedButtonInputField roomTagsField;

		[SerializeField]
		private GameObject tagsParentObject;

		[SerializeField]
		private Slider3D ageRequirementSlider;

		[SerializeField]
		private ToggleButton3D copyableToggle;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private Button3D cancelButton;

		[SerializeField]
		private Button3D publishButton;

		[SerializeField]
		private Button3D takeRoomPictureButton;

		[SerializeField]
		private RawImage roomImage;

		[SerializeField]
		private AllowedPlayerTypesSettings supportedPlayerTypesSettings;

		[SerializeField]
		private UITakeRoomPictureDialog takeRoomPictureDialog;

		private string roomName = string.Empty;

		private string roomDescription = string.Empty;

		private ToggleButton3D[] tagToggles = new ToggleButton3D[0];

		private List<string> playerAddedTags = new List<string>();

		private List<string> hotTags = new List<string>();

		private bool hasTakenPicture;

		private RoomDetails targetRoomDetails;

		private bool resetInfoText;

		private void Awake()
		{
			tagToggles = tagsParentObject.GetComponentsInChildren<ToggleButton3D>(includeInactive: true);
			RecNet.Rooms.GetPopularTags().Then(delegate(List<string> popularTags)
			{
				if (this != null)
				{
					hotTags = popularTags;
					for (int i = 0; i < tagToggles.Length; i++)
					{
						tagToggles[i].gameObject.SetActive(i < hotTags.Count);
						if (i < hotTags.Count)
						{
							UIHelper.SafeSetText(tagToggles[i].Label, hotTags[i]);
							int temp = i;
							tagToggles[temp].OnClick.AddListener(delegate(bool isOn)
							{
								Toggle_Tag(temp, isOn);
							});
						}
					}
				}
			});
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			roomNameField.IsValidFunction = NameAndDescriptionAreValid;
			roomDescriptionField.IsValidFunction = NameAndDescriptionAreValid;
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(RoomDetails roomDetails)
		{
			if (roomDetails == null)
			{
				throw new Exception("Empty Room Details in publish dialog!");
			}
			targetRoomDetails = roomDetails;
			if (targetRoomDetails != null)
			{
				SetInfoText(string.Empty, activeButtons: true);
				roomNameField.Text = targetRoomDetails.Room.Name;
				roomDescriptionField.Text = targetRoomDetails.Room.Description;
				roomImage.texture = SingletonMonoBehaviour<SessionManager>.Instance.DefaultProfileImage;
				Images.GetRoomImage(targetRoomDetails.Room).Then(delegate(Texture2D image)
				{
					roomImage.texture = image;
				});
				if (targetRoomDetails.PlayerAddedTags.Count > 0)
				{
					roomTagsField.InputField.text = string.Format("#{0}", string.Join(", #", targetRoomDetails.PlayerAddedTags.ToArray()));
				}
				copyableToggle.IsOn = roomDetails.Room.CloningAllowed;
				supportedPlayerTypesSettings.UpdateVRTeleportToggle(roomDetails.Room.SupportsTeleportVR);
				supportedPlayerTypesSettings.UpdateVRWalkToggle(roomDetails.Room.SupportsWalkVR);
				supportedPlayerTypesSettings.UpdateScreenToggle(roomDetails.Room.SupportsScreens);
			}
			else
			{
				UnityEngine.Debug.LogError("targetRoom is null");
			}
			return base.ShowDialog();
		}

		private void SetInfoText(string info, bool activeButtons)
		{
			infoText.text = info;
			if (!string.IsNullOrEmpty(info))
			{
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, info, 3f);
			}
			roomNameField.Interactable = activeButtons;
			roomDescriptionField.Interactable = activeButtons;
			takeRoomPictureButton.Interactable = activeButtons;
			roomTagsField.Interactable = activeButtons;
			ToggleButton3D[] array = tagToggles;
			foreach (ToggleButton3D toggleButton3D in array)
			{
				toggleButton3D.Interactable = activeButtons;
			}
			copyableToggle.Interactable = activeButtons;
			ageRequirementSlider.Interactable = activeButtons;
			supportedPlayerTypesSettings.Interactable = activeButtons;
			cancelButton.Interactable = activeButtons;
			publishButton.Interactable = activeButtons;
		}

		private void HandlePublishResponse(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to create room: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					if (Player.LocalPlayerExists)
					{
						Player.LocalPlayer.PlayerEvents.CreatedNewRoom();
					}
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Successfully published!", 3f);
					Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					SetInfoText("Juniors can't create rooms!", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					SetInfoText("Error creating room. Please try again.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DuplicateName:
					SetInfoText("Error: There is already a room called ^" + roomName, activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.ReservedName:
					SetInfoText("Error: \"" + roomName + "\" is a reserved ^name.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateName:
					SetInfoText("Error: \"" + roomName + "\" contains inappropriate words.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateDescription:
					SetInfoText("Error: \"" + roomDescription + "\" contains inappropriate words.", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.TooManyRooms:
					SetInfoText("Error: You have hit the maximum number of allowed rooms :(", activeButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PlayerHasRoomUnderModerationReview:
					SetInfoText("Error: You have a room under moderation review. Contact conduct@againstgrav.com", activeButtons: true);
					break;
				default:
					SetInfoText("Unknown error. If this persists, please contact the developers at support@againstgrav.com.", activeButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to create room: " + error);
				SetInfoText("Failed to create room: " + error, activeButtons: true);
			}
		}

		private void HandleNonSuccessModifyTagsResponse(string error, RecNet.Rooms.ModifyTagsResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				UnityEngine.Debug.LogErrorFormat("Failed to modify tags: " + response);
				string arg = ((response.Tags == null || response.Tags.Count <= 0) ? string.Empty : $"#{response.Tags[0]}");
				switch (response.Result)
				{
				case RecNet.Rooms.RoomTagStatus.TooManyTags:
					SetInfoText("You can only add up to 3 tags", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.TagUseRestricted:
					SetInfoText($"Restricted tag: {arg}", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.InvalidTag:
					SetInfoText($"Invalid tag: {arg}", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.InappropriateTag:
					SetInfoText($"Inappropriate tag: {arg}", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.TagTooLong:
					SetInfoText($"Maximum 15 characters per tag: {arg}", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.LacksPermission:
					SetInfoText("You do not have permission to modify this room's tags", activeButtons: true);
					break;
				case RecNet.Rooms.RoomTagStatus.RoomDoesNotExist:
					SetInfoText("Error: This room does not exist!", activeButtons: true);
					break;
				default:
					SetInfoText("Error modifying tags. If this persists, please contact the developers at support@againstgrav.com.", activeButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to modify tags: " + error);
				SetInfoText("Failed to modify tags: " + error, activeButtons: true);
			}
		}

		private bool NameAndDescriptionAreValid(string str)
		{
			roomName = roomNameField.Text.Trim();
			roomDescription = roomDescriptionField.Text.Trim();
			if (roomName.Length <= 2)
			{
				infoText.text = "^name too short!";
			}
			else if (!roomName.IsAlphaNumeric())
			{
				infoText.text = "^name can only contain letters and numbers!";
			}
			else
			{
				if (roomDescription.Length >= 2)
				{
					if (resetInfoText)
					{
						resetInfoText = false;
						infoText.text = string.Empty;
					}
					return true;
				}
				infoText.text = "Description too short!";
			}
			resetInfoText = true;
			return false;
		}

		private bool TagsAreValid()
		{
			if (!string.IsNullOrEmpty(roomTagsField.Text))
			{
				playerAddedTags.Clear();
				string[] array = roomTagsField.Text.Split(new char[4] { '#', ',', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
				if (array.Length > 3)
				{
					SetInfoText("Cannot add more than 3 tags", activeButtons: true);
					return false;
				}
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (!text.IsAlphaNumeric())
					{
						SetInfoText("Tags can only contain alphabets and numbers", activeButtons: true);
						return false;
					}
					if (text.Length < 2)
					{
						SetInfoText("Tags must be at least 2 characters long", activeButtons: true);
						return false;
					}
					if (text.Length > 15)
					{
						SetInfoText("Tags cannot be longer than 15 characters", activeButtons: true);
						return false;
					}
				}
				playerAddedTags.AddRange(array);
				return true;
			}
			return true;
		}

		private bool RoomPhotoIsValid()
		{
			if (!targetRoomDetails.Room.HasDefaultImage || hasTakenPicture)
			{
				return true;
			}
			SetInfoText("Missing room photo!", activeButtons: true);
			return false;
		}

		[SkipRename]
		public void Button_TakeRoomPicture()
		{
			Player.LocalPlayer.PlayerUI.WatchMenu.ShowTemporaryDialog(takeRoomPictureDialog, targetRoomDetails.Room, (WatchAttractor.EffectFlags)0).Then(delegate(TakePictureDialogResponse takePictureResponse)
			{
				if (takePictureResponse.responseType == ConfirmDialogResponses.Affirmative && takePictureResponse.photoSet != null)
				{
					hasTakenPicture = true;
					roomImage.texture = takePictureResponse.photoSet.MainTexture;
				}
			});
		}

		[SkipRename]
		public void Button_Cancel()
		{
			Respond(ConfirmDialogResponses.Cancel, shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_Publish()
		{
			if (targetRoomDetails == null || !NameAndDescriptionAreValid(null) || !TagsAreValid() || !RoomPhotoIsValid())
			{
				return;
			}
			SetInfoText("Publishing...", activeButtons: false);
			List<string> list = null;
			RecNet.Rooms.ModifyRoomTags(autoTags: (targetRoomDetails.Room.RoomId != RecNet.Rooms.LocalRoomDetails.Room.RoomId) ? targetRoomDetails.AutoTags : RecNet.Rooms.GenerateAutoTagsForLocalRoom(), roomId: targetRoomDetails.Room.RoomId, playerAddedTags: playerAddedTags, callback: delegate(string error, RecNet.Rooms.ModifyTagsResponse response)
			{
				if (string.IsNullOrEmpty(error) && response.Result == RecNet.Rooms.RoomTagStatus.Success)
				{
					RecNet.Rooms.ModifyRoomPublishState(targetRoomDetails.Room.RoomId, newIsPublished: true, HandlePublishResponse);
				}
				else
				{
					HandleNonSuccessModifyTagsResponse(error, response);
				}
			});
		}

		[SkipRename]
		public void Toggle_Tag(int index, bool isOn)
		{
			if (index >= hotTags.Count)
			{
				return;
			}
			if (isOn)
			{
				string text = roomTagsField.Text;
				if (!string.IsNullOrEmpty(text))
				{
					text = string.Format("{0}{1}", text, ", ");
				}
				roomTagsField.Text = $"{text}{hotTags[index]}";
				return;
			}
			string[] source = roomTagsField.Text.Split(new char[3] { ',', ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
			IEnumerable<string> source2 = source.Where((string sp) => sp != hotTags[index] && sp != $"{'#'}{hotTags[index]}");
			roomTagsField.Text = string.Join(", ", source2.ToArray());
		}
	}
}
