	[SerializeField]
	private Button3D upgradeButton;

	[SerializeField]
	private GameObject eliteText;

	[SerializeField]
	private TierRewardPagedGrid tierRewardPagedGrid;

	[Header("Animation")]
	[SerializeField]
	private Transform acornsParent;

	[SerializeField]
	private Animator acornBonusAnimator;

	[SerializeField]
	private Color gold;

	[Header("Audio")]
	[SerializeField]
	private RecRoomAudioClip acornPopAudio;

	[SerializeField]
	private RecRoomAudioClip tierUpAudio;

	[SerializeField]
	private RecRoomAudioClip incrementXPClip;

	[SerializeField]
	private RecRoomAudioClip levelUpClip;

	[SerializeField]
	private RecRoomAudioClip statPostedClip;

	[SerializeField]
	private RecRoomAudioClip summaryOpenClip;

	[SerializeField]
	private RecRoomAudioClip roundCompleteClip;

	[SerializeField]
	private RecRoomAudioClip totalXPEarnedClip;

	[SerializeField]
	private RecRoomAudioClip goldAcornAudio;

	[SerializeField]
	private RecRoomAudioClip acornToTierAudio;

	private static readonly int ACORN_FILLED_ANIMATION_ID = Animator.StringToHash("IsFilled");

	private static readonly int ACORN_FILLING_ANIMATION_ID = Animator.StringToHash("Filling");

	private static readonly int ACORN_GOLD_ANIMATION_ID = Animator.StringToHash("IsGold");

	private static readonly int ACORNBONUS_ISLARGE_ANIMATION_ID = Animator.StringToHash("IsLarge");

	private Animator[] acornAnimators = new Animator[0];

	private StorefrontSeasonDTO currentSeason;

	private RecNetRecRoyaleStats.RecRoyalePlayerProgress currentLevelStats;

	private long cachedAcornCount;

	private bool incrementTierNumberOnDisable;

	private SFXAudioSource xpLoopingSource;

	private PurchasableSeasonTier tierToBuy;

	private List<Avatars.GiftPackage> giftPackagesToSpawn = new List<Avatars.GiftPackage>();

	private Coroutine statAnimationCoroutine;

	private Coroutine tierUpRoutine;

	private Coroutine animateAcornsRoutine;

	private bool IsAtMaxTier
	{
		get
		{
			if (currentSeason != null)
			{
				int num = currentSeason.PersonalDetails.CurrentSeasonTierNumber + 1;
				if (num > currentSeason.Tiers.Count)
				{
					return true;
				}
			}
			return false;
		}
	}

	private bool IsAtMaxLevel => currentLevelStats != null && currentLevelStats.NextLevelXPThreshold == 0;

	private void Awake()
	{
		UpdateCachedBalanceAsync();
	}

	public override void Initialize(WatchUIFlow flow)
	{
		thisFlow = flow;
		acornAnimators = acornsParent.GetComponentsInChildren<Animator>();
		RecNetRecRoyaleStats.GetLocalPlayerProgress().Then(delegate(RecNetRecRoyaleStats.RecRoyalePlayerProgress p)
		{
			if (this != null)
			{
				currentLevelStats = p;
				UpdatePersonalDetails();
			}
		});
		RecNetRecRoyaleStats.OnPlayerStatsReceived += StatUpdatesReceived;
		Storefronts.DownloadStorefrontSeason(StorefrontTypes.RecRoyale, delegate(string error, StorefrontSeasonDTO season)
		{
			if (string.IsNullOrEmpty(error))
			{
				currentSeason = season;
				if (currentSeason == null)
				{
					UnityEngine.Debug.LogError("ERROR! CURRENT SEASON CANNOT BE NULL! :(");
				}
				if (currentSeason.PersonalDetails == null)
				{
					UnityEngine.Debug.LogError("Personal details cannot be null!");
				}
				TimeSpan timeSpan = currentSeason.EndAt - DateTime.UtcNow;
				seasonEndsText.text = ((timeSpan.Days <= daysLeftToShowSeasonEndsText) ? $"Season ends:\n{GetFormatedTimeString(timeSpan)}" : string.Empty);
				UpdatePersonalDetails();
				CheckIfPlayerShouldRedeemAcorns();
			}
			else
			{
				UnityEngine.Debug.LogError($"Error downloading StorefrontTypes.RecRoyale_Season1: {error}");
			}
		});
	}

	private void OnDestroy()
	{
		RecNetRecRoyaleStats.OnPlayerStatsReceived -= StatUpdatesReceived;
	}

	private void Update()
	{
		if (base.gameObject.activeSelf)
		{
			AnalyticsHelper.AccumulateTime("Watch_RecRoyaleUI", UnityEngine.Time.unscaledDeltaTime);
		}
	}

	public override void OnFlowEntered(StackedUIFlowBase oldFlow)
	{
		base.OnFlowEntered(oldFlow);
		UpdatePersonalDetails();
		if (currentSeason != null)
		{
			tierRewardPagedGrid.SetTiers(currentSeason.Tiers, currentSeason.PersonalDetails, thisFlow);
		}
	}

	private void OnEnable()
	{
		UpdatePersonalDetails();
		tierRewardPagedGrid.UpdateGrid();
		seasonTierGroup.SetActive(value: true);
		XPGroup.SetActive(value: false);
		animatedAcorn.gameObject.SetActive(value: false);
		animatedXPText.gameObject.SetActive(value: false);
		acornBonusAnimator.gameObject.SetActive(!IsAtMaxTier);
		if (!IsAtMaxTier)
		{
			acornBonusAnimator.SetBool(ACORNBONUS_ISLARGE_ANIMATION_ID, value: false);
		}
		if (currentLevelStats != null)
		{
			acornBonusText.text = $"x{currentLevelStats.NextLevelAcornReward.ToString()}";
		}
	}

	private void OnDisable()
	{
		AudioManager.StopLoopingSFX(xpLoopingSource);
		if (animateAcornsRoutine != null && tierToBuy != null)
		{
			UnlockNextTier(CurrencyType.RecRoyale_Season1, tierToBuy.PurchasableItemId, tierToBuy.TierNumber, animateResult: false);
		}
		if (tierUpRoutine != null && incrementTierNumberOnDisable)
		{
			currentSeason.PersonalDetails.CurrentSeasonTierNumber++;
		}
		TrySpawnGiftPackages();
	}

	private void DebugUpdatePersonalDetails()
	{
		tierRewardPagedGrid.SetTiers(currentSeason.Tiers, currentSeason.PersonalDetails, thisFlow);
	}

	private void UpdatePersonalDetails()
	{
		if (currentSeason != null)
		{
			yourTierText.text = $"Reward Tier -- {currentSeason.PersonalDetails.CurrentSeasonTierNumber}";
			bool flag = !currentSeason.PersonalDetails.HasEliteUpgrade;
			upgradeButton.gameObject.SetActive(flag);
			eliteText.SetActive(!flag);
			maxLevelReachedText.SetActive(IsAtMaxLevel);
			maxTierReachedText.SetActive(IsAtMaxTier);
			acornsParent.gameObject.SetActive(!IsAtMaxTier);
			acornBonusAnimator.gameObject.SetActive(!IsAtMaxTier && !IsAtMaxLevel);
		}
		else
		{
			yourTierText.text = string.Empty;
			upgradeButton.gameObject.SetActive(value: false);
			eliteText.SetActive(value: false);
			maxLevelReachedText.SetActive(value: false);
			maxTierReachedText.SetActive(value: false);
			acornsParent.gameObject.SetActive(value: true);
			acornBonusAnimator.gameObject.SetActive(value: true);
		}
		int num = (int)cachedAcornCount;
		if (!IsAtMaxTier && base.isActiveAndEnabled)
		{
			for (int i = 0; i < acornAnimators.Length; i++)
			{
				bool value = i < num;
				acornAnimators[i].SetBool(ACORN_FILLED_ANIMATION_ID, value);
				acornAnimators[i].SetBool(ACORN_GOLD_ANIMATION_ID, value: false);
			}
		}
		if (currentLevelStats != null)
		{
			rankText.text = $"Lv {currentLevelStats.Level} ({currentLevelStats.RankName})";
			if (BattleRoyaleImageManager.Instance != null)
			{
				rankBadge.sprite = BattleRoyaleImageManager.Instance.GetColorSpriteForRankIdx(currentLevelStats.RankIdx);
			}
			if (IsAtMaxLevel)
			{
				xpBar.normalizedValue = 1f;
			}
			else
			{
				float num2 = Mathf.Clamp01((float)(currentLevelStats.TotalXP - currentLevelStats.CurrentLevelXPThreshold) / (float)(currentLevelStats.NextLevelXPThreshold - currentLevelStats.CurrentLevelXPThreshold));
				if (num2 < 1f && num2 > 0.95f)
				{
					num2 -= 0.05f;
				}
				xpBar.normalizedValue = num2;
			}
			acornBonusText.text = $"x{currentLevelStats.NextLevelAcornReward.ToString()}";
		}
		else
		{
			rankText.text = string.Empty;
			xpBar.normalizedValue = 0f;
			acornBonusText.text = string.Empty;
		}
	}

	private void StatUpdatesReceived(RecNetRecRoyaleStats.StatUpdates newPlayerStats)
	{
		RunStatAnimation(newPlayerStats);
	}

	private IEnumerator AnimatePosition(Transform tranformToAnimate, Vector3 start, Vector3 end, float duration)
	{
		float t = 0f;
		while (t < 1f)
		{
			t += UnityEngine.Time.deltaTime / duration;
			tranformToAnimate.position = Vector3.Lerp(start, end, t);
			yield return null;
		}
	}

	private void RunStatAnimation(RecNetRecRoyaleStats.StatUpdates newPlayerStats)
	{
		if (Player.LocalPlayerExists)
		{
			if (statAnimationCoroutine != null)
			{
				Player.LocalPlayer.StopCoroutine(statAnimationCoroutine);
				statAnimationCoroutine = null;
			}
			statAnimationCoroutine = Player.LocalPlayer.StartCoroutine(AnimateStats(newPlayerStats));
		}
	}

	private IEnumerator AnimateStats(RecNetRecRoyaleStats.StatUpdates newPlayerStats)
	{
		if (currentLevelStats == null && newPlayerStats != null && newPlayerStats.NewProgress.Count > 0)
		{
			currentLevelStats = newPlayerStats.NewProgress.LastItem();
			UpdatePersonalDetails();
		}
		else
		{
			if (newPlayerStats == null || newPlayerStats.NewProgress == null || newPlayerStats.NewProgress.Count == 0 || newPlayerStats.TotalXPAwarded == 0)
			{
				yield break;
			}
			int lastAcornBalance = (int)cachedAcornCount;
			UpdateCachedBalanceAsync();
			OpenWatchAndShowScreen();
			seasonTierGroup.SetActive(value: false);
			XPGroup.SetActive(value: true);
			roundCompleteText.gameObject.SetActive(value: false);
			xpText.text = string.Empty;
			AudioManager.Play2DSFX(summaryOpenClip);
			yield return new WaitForSeconds(0.75f);
			roundCompleteText.gameObject.SetActive(value: true);
			AudioManager.Play2DSFX(roundCompleteClip);
			yield return new WaitForSeconds(1.5f);
			for (int i = 0; i < newPlayerStats.XPAwardStrings.Count; i++)
			{
				xpText.text = $"{xpText.text}\n{newPlayerStats.XPAwardStrings[i]}";
				AudioManager.Play2DSFX(statPostedClip);
				yield return new WaitForSeconds(1f);
			}
			yield return new WaitForSeconds(0.5f);
			animatedXPText.gameObject.SetActive(value: true);
			animatedXPText.text = newPlayerStats.TotalXPAwarded.ToString();
			AudioManager.Play2DSFX(totalXPEarnedClip);
			yield return AnimatePosition(animatedXPText.transform, animatedXPStart.position, animatedXPEnd.position, 0.8f);
			yield return new WaitForSeconds(0.3f);
			animatedXPText.gameObject.SetActive(value: false);
			yield return new WaitForSeconds(0.5f);
			seasonTierGroup.SetActive(value: true);
			XPGroup.SetActive(value: false);
			if (!IsAtMaxTier && base.isActiveAndEnabled)
			{
				for (int j = 0; j < acornAnimators.Length; j++)
				{
					bool value = j < lastAcornBalance;
					acornAnimators[j].SetBool(ACORN_FILLED_ANIMATION_ID, value);
					acornAnimators[j].SetBool(ACORN_GOLD_ANIMATION_ID, value: false);
				}
			}
			if (IsAtMaxLevel)
			{
				CheckIfPlayerShouldRedeemAcorns();
				yield break;
			}
			long startXPValue = currentLevelStats.TotalXP;
			int acornsEarned = 0;
			for (int k = 0; k < newPlayerStats.NewProgress.Count; k++)
			{
				if (k > 0)
				{
					acornsEarned += newPlayerStats.NewProgress[k - 1].NextLevelAcornReward;
					yield return new WaitForSeconds(0.5f);
					rankText.text = $"Lv {newPlayerStats.NewProgress[k].Level} ({newPlayerStats.NewProgress[k].RankName})";
					if (BattleRoyaleImageManager.Instance != null)
					{
						rankBadge.sprite = BattleRoyaleImageManager.Instance.GetColorSpriteForRankIdx(newPlayerStats.NewProgress[k].RankIdx);
					}
					acornBonusText.text = $"x{acornsEarned.ToString()}";
					AudioManager.Play2DSFX(levelUpClip);
					if (k == 1 && !IsAtMaxTier && base.isActiveAndEnabled)
					{
						acornBonusAnimator.SetBool(ACORNBONUS_ISLARGE_ANIMATION_ID, value: true);
					}
					yield return new WaitForSeconds(0.5f);
				}
				if (newPlayerStats.NewProgress[k].NextLevelXPThreshold == 0)
				{
					maxLevelReachedText.SetActive(value: true);
					continue;
				}
				long targetXPValue = newPlayerStats.NewProgress[k].TotalXP;
				long barStartValue = newPlayerStats.NewProgress[k].CurrentLevelXPThreshold;
				long barEndValue = newPlayerStats.NewProgress[k].NextLevelXPThreshold;
				float startPct = Mathf.Clamp01((float)(startXPValue - barStartValue) / (float)(barEndValue - barStartValue));
				float endPct = Mathf.Clamp01((float)(targetXPValue - barStartValue) / (float)(barEndValue - barStartValue));
				float currPct = startPct;
				if (currPct <= endPct)
				{
					if (endPct < 1f && endPct > 0.95f)
					{
						endPct -= 0.05f;
					}
					float animationTime = 1f;
					float animSpeed = (endPct - startPct) / animationTime;
					xpLoopingSource = AudioManager.StartLooping2DSFX(incrementXPClip);
					while (currPct <= endPct)
					{
						currPct += animSpeed * UnityEngine.Time.deltaTime;
						xpBar.normalizedValue = currPct;
						yield return null;
					}
					AudioManager.StopLoopingSFX(xpLoopingSource);
				}
				else
				{
					UnityEngine.Debug.LogError("Error animating xp, endPct > currPct");
				}
			}
			bool didAnimate = false;
			if (!IsAtMaxTier)
			{
				didAnimate = TryAnimateAcornChange(lastAcornBalance, lastAcornBalance + acornsEarned);
			}
			currentLevelStats = newPlayerStats.NewProgress.LastItem();
			if (!didAnimate)
			{
				UpdatePersonalDetails();
			}
		}
	}

	private void TryAnimateTierUp(bool usedAcorns, int newAcornBalance, bool noAvailableItems)
	{
		OpenWatchAndShowScreen();
		if (tierUpRoutine != null)
		{
			StopCoroutine(tierUpRoutine);
			tierUpRoutine = null;
		}
		tierUpRoutine = StartCoroutine(RunAnimateTierUp(usedAcorns, newAcornBalance, noAvailableItems));
	}

	private IEnumerator RunAnimateTierUp(bool usedAcorns, int newAcornBalance, bool noAvailableItems)
	{
		tierRewardPagedGrid.SetCurrentPage(Mathf.Clamp(currentSeason.PersonalDetails.CurrentSeasonTierNumber / tierRewardPagedGrid.PageSize, 0, tierRewardPagedGrid.TotalPages - 1));
		currentSeason.PersonalDetails.CurrentSeasonTierNumber++;
		incrementTierNumberOnDisable = false;
		yield return new WaitForSeconds(0.3f);
		tierRewardPagedGrid.UpdateBuyButton(currentSeason.PersonalDetails.CurrentSeasonTierNumber, interactable: false, (!usedAcorns) ? "Purchasing" : "Unlocking");
		if (usedAcorns)
		{
			animatedAcorn.color = gold;
			animatedAcorn.gameObject.SetActive(value: true);
			for (int i = 0; i < acornAnimators.Length; i++)
			{
				acornAnimators[i].SetBool(ACORN_GOLD_ANIMATION_ID, value: false);
				acornAnimators[i].SetBool(ACORN_FILLED_ANIMATION_ID, value: false);
				yield return AnimatePosition(end: tierRewardPagedGrid.GetUnlockedTierTransform(currentSeason.PersonalDetails.CurrentSeasonTierNumber).position, tranformToAnimate: animatedAcorn.transform, start: acornAnimators[i].transform.position, duration: 0.1f);
				AudioManager.Play2DSFX(acornToTierAudio);
			}
			animatedAcorn.gameObject.SetActive(value: false);
			yield return new WaitForSeconds(0.5f);
		}
		AudioManager.Play2DSFX(tierUpAudio);
		tierRewardPagedGrid.PlayUnlockAnimation(currentSeason.PersonalDetails.CurrentSeasonTierNumber, tierUpAudio.audioClip.length);
		yield return new WaitForSeconds(0.5f);
		tierRewardPagedGrid.UpdateGrid();
		TrySpawnGiftPackages();
		yield return new WaitForSeconds(2f);
		if (noAvailableItems)
		{
			GiftManager.GiftRarity rarity = GiftManager.GiftRarity.None;
			PurchasableSeasonTier currentTier = currentSeason.Tiers[currentSeason.PersonalDetails.CurrentSeasonTierNumber - 1];
			if (currentTier.FreeRewards.Count > 0)
			{
				PurchasableSeasonTierReward purchasableSeasonTierReward = currentTier.FreeRewards.FirstOrDefault((PurchasableSeasonTierReward pstr) => pstr.GiftDrop.IsQuery);
				if (purchasableSeasonTierReward != null)
				{
					rarity = purchasableSeasonTierReward.GiftDrop.Rarity;
				}
			}
			else if (currentTier.PaidRewards.Count > 0)
			{
				PurchasableSeasonTierReward purchasableSeasonTierReward2 = currentTier.PaidRewards.FirstOrDefault((PurchasableSeasonTierReward pstr) => pstr.GiftDrop.IsQuery);
				if (purchasableSeasonTierReward2 != null)
				{
					rarity = purchasableSeasonTierReward2.GiftDrop.Rarity;
				}
			}
			bool done = false;
			thisFlow.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_ONLY, "Successfully Unlocked Tier!", $"You already have all {rarity} items!").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					done = true;
				}
			});
			yield return new WaitUntil(() => done);
		}
		if (IsAtMaxTier)
		{
			UpdatePersonalDetails();
		}
		else if (usedAcorns)
		{
			TryAnimateAcornChange(0, newAcornBalance);
		}
	}

	private bool TryAnimateAcornChange(int oldBalance, int newBalance)
	{
		if (!IsAtMaxTier)
		{
			PurchasableSeasonTier purchasableSeasonTier = currentSeason.Tiers[currentSeason.PersonalDetails.CurrentSeasonTierNumber];
			int cost = purchasableSeasonTier.GetCost(CurrencyType.RecRoyale_Season1);
			if (oldBalance >= cost)
			{
				UnlockNextTier(CurrencyType.RecRoyale_Season1, purchasableSeasonTier.PurchasableItemId, purchasableSeasonTier.TierNumber);
				return true;
			}
			if (oldBalance < newBalance && oldBalance < acornAnimators.Length)
			{
				tierToBuy = ((newBalance < cost) ? null : purchasableSeasonTier);
				OpenWatchAndShowScreen();
				if (animateAcornsRoutine != null)
				{
					StopCoroutine(animateAcornsRoutine);
					animateAcornsRoutine = null;
				}
				animateAcornsRoutine = StartCoroutine(RunAnimateAcorns(oldBalance, newBalance));
				return true;
			}
		}
		return false;
	}

	private void CheckIfPlayerShouldRedeemAcorns()
	{
		if (currentSeason != null && currentSeason.PersonalDetails != null && !IsAtMaxTier)
		{
			PurchasableSeasonTier purchasableSeasonTier = currentSeason.Tiers[currentSeason.PersonalDetails.CurrentSeasonTierNumber];
			int cost = purchasableSeasonTier.GetCost(CurrencyType.RecRoyale_Season1);
			if (cachedAcornCount >= cost)
			{
				UnlockNextTier(CurrencyType.RecRoyale_Season1, purchasableSeasonTier.PurchasableItemId, purchasableSeasonTier.TierNumber);
			}
		}
	}

	private IEnumerator RunAnimateAcorns(int oldBalance, int newBalance)
	{
		int acornsEarned = newBalance - oldBalance;
		yield return new WaitForSeconds(0.8f);
		animatedAcorn.color = Color.white;
		animatedAcorn.gameObject.SetActive(value: true);
		for (int i = oldBalance; i < Mathf.Min(newBalance, acornAnimators.Length); i++)
		{
			yield return AnimatePosition(animatedAcorn.transform, animatedAcornStart.position, acornAnimators[i].transform.position, 0.25f);
			acornAnimators[i].SetTrigger(ACORN_FILLING_ANIMATION_ID);
			acornAnimators[i].SetBool(ACORN_FILLED_ANIMATION_ID, value: true);
			Text text = acornBonusText;
			int num;
			acornsEarned = (num = acornsEarned - 1);
			num = num;
			text.text = $"x{num.ToString()}";
			AudioManager.Play2DSFX(acornPopAudio);
		}
		animatedAcorn.gameObject.SetActive(value: false);
		if (tierToBuy != null)
		{
			yield return new WaitForSeconds(0.7f);
			Animator[] array = acornAnimators;
			foreach (Animator animator in array)
			{
				animator.SetBool(ACORN_GOLD_ANIMATION_ID, value: true);
			}
			AudioManager.Play2DSFX(goldAcornAudio);
			tierRewardPagedGrid.UpdateBuyButton(tierToBuy.TierNumber, interactable: false, "Unlocking");
			UnlockNextTier(CurrencyType.RecRoyale_Season1, tierToBuy.PurchasableItemId, tierToBuy.TierNumber);
		}
		else
		{
			acornBonusAnimator.SetBool(ACORNBONUS_ISLARGE_ANIMATION_ID, value: false);
			yield return new WaitForSeconds(0.5f);
			if (currentLevelStats != null)
			{
				if (IsAtMaxLevel)
				{
					acornBonusAnimator.gameObject.SetActive(value: false);
				}
				else
				{
					acornBonusText.text = $"x{currentLevelStats.NextLevelAcornReward.ToString()}";
				}
			}
		}
		animateAcornsRoutine = null;
	}

	private void OpenWatchAndShowScreen()
	{
		if (thisFlow == null)
		{
			UnityEngine.Debug.LogError("thisflow is null");
			return;
		}
		((ThisRoomWatchUIFlow)thisFlow).ShowRoomSpecificSubscreen();
		if (!thisFlow.IsCurrentFlow)
		{
			thisFlow.WatchUI.PushFlow(thisFlow);
		}
		if (!thisFlow.WatchUI.WatchMenuProjector.IsMenuOpen)
		{
			thisFlow.WatchUI.WatchMenuProjector.AuthorityOpenMenuDetached();
		}
	}

	private void UpgradeToEliteTrack()
	{
		if (currentSeason.PersonalDetails == null)
		{
			return;
		}
		int cost = currentSeason.EliteUpgrade.GetCost(CurrencyType.RecCenterTokens);
		long? balance = Storefronts.GetBalance(CurrencyType.RecCenterTokens);
		if (balance.HasValue && balance.GetValueOrDefault() >= cost)
		{
			thisFlow.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, $"Spend {cost} tokens to update to Elite tiers?", $"You'll immediately receive all Elite items up to your current tier {currentSeason.PersonalDetails.CurrentSeasonTierNumber}. You currently have {Storefronts.GetBalance(CurrencyType.RecCenterTokens)} tokens.").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					Storefronts.PurchaseSeasonEliteTrack(StorefrontTypes.RecRoyale, CurrencyType.RecCenterTokens, currentSeason.EliteUpgrade.PurchasableItemId, delegate(string error, Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage> updateResponse)
					{
						if (string.IsNullOrEmpty(error) && updateResponse.BalanceUpdates.Count == 1 && updateResponse.BalanceUpdates[0].UpdateResponse == Storefronts.UpdateResponseTypes.OK)
						{
							currentSeason.PersonalDetails.HasEliteUpgrade = true;
							tierRewardPagedGrid.SetTiers(currentSeason.Tiers, currentSeason.PersonalDetails, thisFlow);
							List<Avatars.GiftPackage> data = updateResponse.BalanceUpdates[0].Data;
							Avatars.GiftPackages.AddRange(data);
							SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(data, useSpawnLocation: false, dismissExistingGift: true);
							SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Upgrade successful!", 3f);
							AnalyticsHelper.UpgradeToElite(currentSeason.PersonalDetails);
						}
					});
				}
			});
		}
		else
		{
			thisFlow.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_ONLY, "Not enough Tokens!", $"You need at least {cost} Tokens to upgrade to the Elite track. You currently have {Storefronts.GetBalance(CurrencyType.RecCenterTokens)} tokens.\nYou can get more tokens by completing the orientation challenges.", "OK");
		}
	}

	private void PurchaseNextTier()
	{
		if (currentSeason.PersonalDetails == null)
		{
			return;
		}
		int num = currentSeason.PersonalDetails.CurrentSeasonTierNumber + 1;
		if (num > currentSeason.Tiers.Count)
		{
			upgradeButton.Interactable = false;
			return;
		}
		PurchasableSeasonTier nextTier = currentSeason.Tiers[currentSeason.PersonalDetails.CurrentSeasonTierNumber];
		int cost = nextTier.GetCost(CurrencyType.RecCenterTokens);
		long? balance = Storefronts.GetBalance(CurrencyType.RecCenterTokens);
		if (balance.HasValue && balance.GetValueOrDefault() >= cost)
		{
			thisFlow.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, $"Spend {cost} tokens to buy the next tier (Tier {num})?", $"You'll immediately receive all items associated with that tier. You currently have {Storefronts.GetBalance(CurrencyType.RecCenterTokens)} tokens.").Then(delegate(ConfirmDialogResponses response)
			{
				if (response == ConfirmDialogResponses.Affirmative)
				{
					tierRewardPagedGrid.UpdateBuyButton(nextTier.TierNumber, interactable: false, "Purchasing");
					UnlockNextTier(CurrencyType.RecCenterTokens, nextTier.PurchasableItemId, nextTier.TierNumber);
				}
			});
		}
		else
		{
			thisFlow.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_ONLY, "Not enough Tokens!", $"You need at least {cost} Tokens to purchase the next tier (Tier {num}).You currently have {Storefronts.GetBalance(CurrencyType.RecCenterTokens)} tokens.\nYou can get more tokens by completing the orientation challenges.", "OK");
		}
	}

	private void UnlockNextTier(CurrencyType currencyType, int purchasableItemId, int tierNumber, bool animateResult = true)
	{
		tierToBuy = null;
		Storefronts.PurchaseSeasonTier(StorefrontTypes.RecRoyale, currencyType, purchasableItemId, delegate(string error, Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage> updateResponse)
		{
			if (string.IsNullOrEmpty(error) && updateResponse.BalanceUpdates.Count == 1 && updateResponse.BalanceUpdates[0].UpdateResponse == Storefronts.UpdateResponseTypes.OK)
			{
				bool noAvailableItems = false;
				List<Avatars.GiftPackage> data = updateResponse.BalanceUpdates[0].Data;
				if (data.Any((Avatars.GiftPackage gp) => !gp.IsValid))
				{
					noAvailableItems = true;
				}
				giftPackagesToSpawn = data.Where((Avatars.GiftPackage gp) => gp.IsValid && gp.SupportsCurrentPlatform).ToList();
				if (animateResult)
				{
					incrementTierNumberOnDisable = true;
					TryAnimateTierUp(currencyType == CurrencyType.RecRoyale_Season1, (int)updateResponse.Balance, noAvailableItems);
				}
				else
				{
					currentSeason.PersonalDetails.CurrentSeasonTierNumber++;
					TrySpawnGiftPackages();
					tierRewardPagedGrid.UpdateGrid();
				}
				if (currencyType == CurrencyType.RecCenterTokens)
				{
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Purchase successful!", 3f);
				}
				else if (currencyType == CurrencyType.RecRoyale_Season1)
				{
					UpdateCachedBalanceAsync();
				}
				AnalyticsHelper.PurchasedTier(currentSeason.PersonalDetails.CurrentSeasonTierNumber, currencyType);
			}
			else
			{
				if (base.isActiveAndEnabled)
				{
					Animator[] array = acornAnimators;
					foreach (Animator animator in array)
					{
						animator.SetBool(ACORN_GOLD_ANIMATION_ID, value: false);
					}
					acornBonusAnimator.SetBool(ACORNBONUS_ISLARGE_ANIMATION_ID, value: false);
				}
				tierRewardPagedGrid.UpdateBuyButton(tierNumber, interactable: true, "Error");
				if (string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError($"Error unlocking tier {tierNumber}: {updateResponse.BalanceUpdates[0].UpdateResponse.ToString()}");
				}
				else
				{
					UnityEngine.Debug.LogError($"Error unlocking tier: {error}");
				}
			}
		});
	}

	private void TrySpawnGiftPackages()
	{
		if (giftPackagesToSpawn.Count > 0)
		{
			List<Avatars.GiftPackage> list = new List<Avatars.GiftPackage>(giftPackagesToSpawn);
			giftPackagesToSpawn.Clear();
			Avatars.GiftPackages.AddRange(list);
			SingletonMonoBehaviour<GiftManager>.Instance.ReceiveGifts(list, useSpawnLocation: false, dismissExistingGift: true);
		}
	}

	private string GetFormatedTimeString(TimeSpan timeSpan)
	{
		if (timeSpan.Days >= 1)
		{
			return string.Format("{0} {1}", timeSpan.Days, GetPluralForm("day", timeSpan.Days));
		}
		if (timeSpan.Hours >= 1)
		{
			return string.Format("{0} {1}", timeSpan.Hours, GetPluralForm("hour", timeSpan.Hours));
		}
		if (timeSpan.Minutes >= 1)
		{
			return string.Format("{0} {1}", timeSpan.Minutes, GetPluralForm("minute", timeSpan.Minutes));
		}
		return "1 minute";
	}

	private string GetPluralForm(string text, int num)
	{
		return (num <= 1) ? text : $"{text}s";
	}

	private void UpdateCachedBalanceAsync()
	{
		Storefronts.FetchBalance(CurrencyType.RecRoyale_Season1, delegate(string errMsg, long currentBalance)
		{
			if (string.IsNullOrEmpty(errMsg))
			{
				cachedAcornCount = currentBalance;
			}
		});
	}

	[SkipRename]
	public void Button_Info()
	{
		if (thisFlow != null)
		{
			thisFlow.WatchUI.PushFlow(thisFlow.WatchUI.GetFlowByType<RecRoyaleInfoScreen>());
		}
	}

	[SkipRename]
	public void Button_UpgradeToElite()
	{
		if (thisFlow != null && currentSeason.PersonalDetails != null && !currentSeason.PersonalDetails.HasEliteUpgrade)
		{
			UpgradeToEliteTrack();
		}
	}

	[SkipRename]
	public void Button_BuyTier(int tierNumber)
	{
		if (thisFlow != null && currentSeason.PersonalDetails != null && currentSeason.PersonalDetails.HasEliteUpgrade)
		{
			PurchaseNextTier();
		}
	}
}
namespace AGUI.StackedUI.Dialog
{
	public class RenameChatDialog : ConfirmUIDialog<long>
	{
		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private ValidatedButtonInputField inputField;

		[SerializeField]
		private TextMeshProUGUI infoText;

		private long chatThreadId;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			inputField.IsValidFunction = delegate(string newName)
			{
				if (string.IsNullOrEmpty(newName) || newName.Length < 3)
				{
					infoText.text = "Chat name too short";
					return false;
				}
				if (newName.Length > 25)
				{
					infoText.text = "Chat name too long";
					return false;
				}
				if (!newName.ContainsKeyboardCharsOnly())
				{
					infoText.text = $"{newName[newName.Length - 1]} is an invalid character";
					return false;
				}
				infoText.text = string.Empty;
				return true;
			};
		}

		public override IPromise<ConfirmDialogResponses> ShowDialog(long id)
		{
			chatThreadId = id;
			return base.ShowDialog();
		}

		private void HandleChatResponse(ChatResults result)
		{
			switch (result)
			{
			case ChatResults.Success:
				Respond(ConfirmDialogResponses.Affirmative, shouldCloseDialog: true);
				break;
			case ChatResults.MembershipNotFound:
				infoText.text = "You're not part of this chat!";
				break;
			case ChatResults.InvalidCharacters:
				infoText.text = "Chat name contains invalid characters.";
				break;
			default:
				infoText.text = $"Rename failed: {result.ToString()}. If this persists, please contact support@againstgrav.com";
				break;
			}
		}

		[SkipRename]
		public void Button_Submit()
		{
			Chats.RenameChat(chatThreadId, inputField.Text).Then(HandleChatResponse);
		}
	}
}
