				{
					targetRoomDetails = value;
					if (TargetRoomScene != null && TargetRoomScene.RoomSceneId == GameSessions.LocalGameSession.RoomSceneId)
					{
						GameSessions.OnLocalGameSessionUpdated += GameSessions_OnLocalGameSessionUpdated;
					}
					else
