		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			persistenceManager = NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance;
			persistenceManager.RoomSaveSuccessEvent += OnRoomSaveSuccess;
			persistenceManager.RoomSaveFailureEvent += OnRoomSaveFailure;
			if (NetworkedSingletonMonoBehaviour<HostManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<HostManager>.Instance.AllowScoreboardsEvent += OnAllowScoreboards;
				NetworkedSingletonMonoBehaviour<HostManager>.Instance.EnforceHostsOnlyAreasEvent += OnEnforceHostAreasChanged;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent += OnGameManagerStateChanged;
			}
			RecNet.Rooms.OnRoomDetailsUpdated += OnRoomDetailsUpdated;
			screenHeader = GetComponentInChildren<ScreenHeader>();
			subscreenControl.ActiveSubscreenChanged += SubscreenControl_ActiveSubscreenChanged;
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (persistenceManager != null)
			{
				persistenceManager.RoomSaveSuccessEvent -= OnRoomSaveSuccess;
				persistenceManager.RoomSaveFailureEvent -= OnRoomSaveFailure;
			}
			if (NetworkedSingletonMonoBehaviour<HostManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<HostManager>.Instance.AllowScoreboardsEvent -= OnAllowScoreboards;
				NetworkedSingletonMonoBehaviour<HostManager>.Instance.EnforceHostsOnlyAreasEvent -= OnEnforceHostAreasChanged;
			}
			if (NetworkedSingletonMonoBehaviour<GameManager>.Instance != null)
			{
				NetworkedSingletonMonoBehaviour<GameManager>.Instance.StateChangeEvent -= OnGameManagerStateChanged;
			}
			RecNet.Rooms.OnRoomDetailsUpdated -= OnRoomDetailsUpdated;
			GameSessions.OnLocalGameSessionUpdated -= GameSessions_OnLocalGameSessionUpdated;
			subscreenControl.ActiveSubscreenChanged -= SubscreenControl_ActiveSubscreenChanged;
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			UpdateVisuals();
			UpdateUIState(string.Empty, enableButtons: true);
		}

		private void OnRoomSaveSuccess()
		{
			UpdateUIState("Room saved!", enableButtons: true);
			if (TargetRoomDetails == null)
			{
				TargetRoomDetails = RecNet.Rooms.LocalRoomDetails;
			}
			UpdateVisuals();
		}

		private void OnRoomSaveFailure(string errorMessage)
		{
			UpdateUIState("Failed to save room. Please try again.", enableButtons: true);
			UnityEngine.Debug.LogError("Error saving room: " + errorMessage);
		}

		private void OnGameManagerStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			UpdateSubroomSubscreen();
		}

		private void OnSandboxStateChanged(ushort currentStateId, ushort previousStateId, ushort currentSubStateId, ushort previousSubStateId)
		{
			UpdateSubroomSubscreen();
		}

		private void OnAllowScoreboards(bool obj)
		{
			UpdateAllowScoreboardsToggle();
		}

		private void OnEnforceHostAreasChanged(bool obj)
		{
