		private void OnLocalRoomDetailsUpdated()
		{
			RecNet.Rooms.OnLocalRoomUpdated -= new Action(OnLocalRoomDetailsUpdated);
			TargetRoomDetails = RecNet.Rooms.LocalRoomDetails;
			ThisRoomWatchUIFlow flowByType = base.WatchUI.GetFlowByType<ThisRoomWatchUIFlow>();
			flowByType.UpdateTargetRoomId(TargetRoomDetails.Room.RoomId);
		}

		private void GameSessions_OnLocalGameSessionUpdated()
		{
			SingletonMonoBehaviour<SessionManager>.Instance.EndOfFrameRoutine(delegate
			{
				if (this != null)
				{
					RoomDetails cachedRoomDetails = RecNet.Rooms.GetCachedRoomDetails(GameSessions.LocalGameSession.RoomId);
					if (cachedRoomDetails != null)
					{
						TargetRoomDetails = cachedRoomDetails;
						ThisRoomWatchUIFlow flowByType = base.WatchUI.GetFlowByType<ThisRoomWatchUIFlow>();
						flowByType.UpdateTargetRoomId(TargetRoomDetails.Room.RoomId);
					}
					else
					{
						RecNet.Rooms.OnLocalRoomUpdated += new Action(OnLocalRoomDetailsUpdated);
					}
				}
			});
		}

		private void SubscreenControl_ActiveSubscreenChanged()
		{
			UpdateScreenHeader();
		}

		private void UpdateScreenHeader()
		{
			if (!(screenHeader == null) && screenHeader.Title != null)
			{
				if (TargetRoomDetails == null)
				{
					screenHeader.Title = "Room Loading...";
				}
				else if (subscreenControl.ActiveSubscreen == roomSubscreen)
				{
					screenHeader.Title = $"^{TargetRoomDetails.Room.Name}";
				}
				else
				{
					screenHeader.Title = string.Format("^{0}{1}", TargetRoomDetails.Room.Name, (TargetRoomScene == null) ? string.Empty : ("." + TargetRoomScene.Name));
				}
			}
		}

