		private void UpdateMaxPlayersSlider()
		{
			int num = 1;
			int num2 = 20;
			num2 = AGRoomSettings.GetMaxPlayers(TargetRoomScene.Location);
			maxPlayersSlider.minValue = num;
			maxPlayersSlider.maxValue = num2;
			maxPlayersSlider.value = TargetRoomScene.MaxPlayers;
			int num3 = (int)maxPlayersSlider.FloatOrRoundedValue;
			maxPlayersSliderText.text = $"{maxPlayersLabel} ({num3})";
			maxPlayersLabelText.text = num2.ToString();
		}

