		{
		}

		private void UpdateCurrentMoodList()
		{
			if (RecRoomSceneManager.Instance.SceneMoodSettings.RoomMoodsEnabled)
			{
				currentRoomMoodText.text = RecRoomSceneManager.Instance.SceneMoodSettings.CurrentMood.FriendlyName;
				subroomSettingsPagedGrid.RemoveIgnoredChild(currentRoomMoodObject.transform);
			}
			else
			{
				subroomSettingsPagedGrid.AddIgnoredChild(currentRoomMoodObject.transform);
