		private void UpdateSubroomName()
		{
			subroomNameInputField.Text = TargetRoomScene.Name;
		}

		private void UpdateIsStartingRoomToggle()
		{
			isStartingRoomToggle.IsOn = TargetRoomScene.CanMatchmakeInto;
			bool flag = false;
			foreach (RoomScene scene in TargetRoomDetails.Scenes)
			{
				if (scene.RoomSceneId != TargetRoomScene.RoomSceneId && scene.CanMatchmakeInto)
				{
					flag = true;
					break;
				}
			}
			isStartingRoomToggle.Interactable = TargetRoomDetails.Scenes.Count > 1 && flag;
		}

		private void UpdateChangeParentRoomButton()
		{
			chooseParentRoomButton.Label.text = $"^{TargetRoomDetails.Room.Name}";
		}

		private void UpdateUIState(string info, bool enableButtons)
		{
			infoText.text = info;
		}

		private void SaveSettings()
		{
			if (subscreenControl.ActiveSubscreen == roomSubscreen)
			{
				UpdateUIState("Updating room...", enableButtons: false);
				RecNet.Room room = TargetRoomDetails.Room;
				RecNet.Rooms.ModifyRoom(room.RoomId, room.Name, room.Description, room.Accessibility, copyableToggle.IsOn, allowedPlayerTypesSettings.GetAllowedTypesFromToggles(), delegate(string error, RecNet.Rooms.CreateModifyRoomResponse response)
				{
					HandleModifyResponse(error, response.Result, savedSubroom: false);
				});
			}
			else if (subscreenControl.ActiveSubscreen == subroomSubscreen)
			{
				UpdateUIState("Updating subroom...", enableButtons: false);
				RecNet.Rooms.ModifyRoomScene(TargetRoomScene.RoomSceneId, subroomNameInputField.Text.Trim(), (int)maxPlayersSlider.FloatOrRoundedValue, isStartingRoomToggle.IsOn, delegate(string error, RecNet.Rooms.CreateModifyRoomSceneResponse response)
				{
					HandleModifyResponse(error, response.Result, savedSubroom: true);
				});
			}
		}

		private void ModifyCurrentMood(bool forward)
		{
			if (forward)
			{
				RecRoomSceneManager.Instance.SceneMoodSettings.MoveForward();
			}
			else
			{
				RecRoomSceneManager.Instance.SceneMoodSettings.MoveBackward();
			}
			UpdateCurrentMoodList();
		}

		private void HandleModifyResponse(string error, RecNet.Rooms.CreateModifyRoomStatus result, bool savedSubroom)
		{
			string text = null;
			if (string.IsNullOrEmpty(error))
			{
				if (result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Error updating room setup: {0}", result);
				}
				switch (result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					if (savedSubroom)
					{
						NetworkedSingletonMonoBehaviour<RoomPersistenceManager>.Instance.RequestSaveRoomData();
						break;
					}
					UpdateUIState(string.Empty, enableButtons: true);
					SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Success!", 3f);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					text = "You can't modify rooms!";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					text = "Failed to update. You do not have permission to edit this setting.";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomNotActive:
					text = "Failed to update. This room is no longer active.";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomUnderModerationReview:
					text = "Failed to update. Please contact us at conduct@againstgrav.com";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.RoomDoesNotExist:
					text = "Failed to update. This room does not exist.";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.DuplicateName:
					text = $"There is already a subroom  in ^{TargetRoomDetails.Room.Name} with the name \"{TargetRoomScene.Name}\"";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.ReservedName:
					text = "That subroom name is reserved, please choose another one.";
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateName:
					text = "Inappropriate subroom name.";
					break;
				default:
					text = $"Failed to update. Error code: {(int)result}\nIf this persists, please email support@againstgrav.com.";
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogErrorFormat("Failed to update room settings: {0}", error);
				text = $"Failed to update settings: {error}";
			}
			if (text != null)
			{
				UpdateUIState(text, enableButtons: true);
			}
		}

		[SkipRename]
		public void Button_Save()
		{
			SaveSettings();
		}

		[SkipRename]
		public void Button_ChooseParentRoom()
		{
			if (TargetRoomScene == null)
			{
				return;
			}
			if (TargetRoomDetails.Scenes.Count == 1 && (TargetRoomDetails.FavoriteCount > 0 || TargetRoomDetails.CheerCount > 0))
			{
				base.WatchUI.ShowConfirmationDialog(UIConfirmationDialog.DialogType.YES_NO, "Warning!", $"Once this subroom is moved, ^{TargetRoomDetails.Room.Name} and all its stats will be deleted. This action is NOT reversable.", "Continue", "Cancel", (WatchAttractor.EffectFlags)0).Then(delegate(ConfirmDialogResponses response)
				{
					if (response == ConfirmDialogResponses.Affirmative)
					{
						base.WatchUI.ShowTemporaryConfirmationDialog(chooseParentRoomDialog, TargetRoomDetails, TargetRoomScene, (WatchAttractor.EffectFlags)0);
					}
				});
			}
			else
			{
				base.WatchUI.ShowTemporaryConfirmationDialog(chooseParentRoomDialog, TargetRoomDetails, TargetRoomScene, (WatchAttractor.EffectFlags)0);
			}
		}

		[SkipRename]
		public void Toggle_AllowScoreboards(bool value)
		{
			NetworkedSingletonMonoBehaviour<HostManager>.Instance.ToggleAllowScoreboards(value);
		}

		[SkipRename]
		public void Toggle_EnforceHostAreas(bool value)
		{
			NetworkedSingletonMonoBehaviour<HostManager>.Instance.ToggleEnforceHostsOnlyAreas(value);
		}

		[SkipRename]
		public void Toggle_EnableMovementBlockers(bool value)
		{
			RecRoomSceneManager.Instance.GeometrySettings.MovementBlockersEnabled = value;
		}

		[SkipRename]
		public void SliderValueChanged_MaxPlayers(float value)
		{
			int num = (int)maxPlayersSlider.FloatOrRoundedValue;
			maxPlayersSliderText.text = $"{maxPlayersLabel} ({num})";
		}

		[SkipRename]
		public void NextPressed_CurrentMood()
		{
			ModifyCurrentMood(forward: true);
		}

		[SkipRename]
