namespace AGUI.StackedUI
{
	public class StorePurchaseItemScreen : WatchUIFlow
	{
		[Header("Buttons")]
		[SerializeField]
		private Button3D confirmButton;

		[SerializeField]
		private Button3D backButton;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		private PurchasableGiftDrop purchasableGiftDropToBuy;

		private long? initialBalance;

		private Avatars.GiftPackage packageToSpawn;

		private bool hasEnoughTokens;

		private StoreScreen storeScreen;

		private HowToGetTokensScreen howToGetTokensScreen;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_OpenedPurchaseItemScreenEvent;

		[CompilerGenerated]
		[DebuggerBrowsable(DebuggerBrowsableState.Never)]
		private Action m_ClosedPurchaseItemScreenEvent;

		public Button3D ConfirmButton => confirmButton;

		public Button3D BackButton => backButton;

		public event Action OpenedPurchaseItemScreenEvent
		{
			add
			{
				Action action = this.m_OpenedPurchaseItemScreenEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OpenedPurchaseItemScreenEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_OpenedPurchaseItemScreenEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_OpenedPurchaseItemScreenEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public event Action ClosedPurchaseItemScreenEvent
		{
			add
			{
				Action action = this.m_ClosedPurchaseItemScreenEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_ClosedPurchaseItemScreenEvent, (Action)Delegate.Combine(action2, value), action);
				}
				while (action != action2);
			}
			remove
			{
				Action action = this.m_ClosedPurchaseItemScreenEvent;
				Action action2;
				do
				{
					action2 = action;
					action = Interlocked.CompareExchange(ref this.m_ClosedPurchaseItemScreenEvent, (Action)Delegate.Remove(action2, value), action);
				}
				while (action != action2);
			}
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			storeScreen = base.WatchUI.GetFlowByType<StoreScreen>();
			howToGetTokensScreen = base.WatchUI.GetFlowByType<HowToGetTokensScreen>();
		}

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			purchasableGiftDropToBuy = null;
			initialBalance = null;
		}

		public void GetConfirmation(PurchasableGiftDrop purchasableGiftDrop)
		{
			StorefrontGiftDrop storefrontGiftDrop = purchasableGiftDrop.GiftDrops[0];
			if (storefrontGiftDrop == null)
			{
				UnityEngine.Debug.LogError("Item cannot be null!");
				return;
			}
			purchasableGiftDropToBuy = purchasableGiftDrop;
			OpenScreen();
			initialBalance = Storefronts.GetBalance(CurrencyType.RecCenterTokens);
			int cost = purchasableGiftDrop.GetCost(CurrencyType.RecCenterTokens);
			hasEnoughTokens = initialBalance.HasValue && cost <= initialBalance.Value;
			if (hasEnoughTokens)
			{
				string empty = string.Empty;
				UpdateUI($"Confirm purchase of {storefrontGiftDrop.FriendlyName} for {$"{cost:n0}"} tokens?{empty}", "Confirm");
			}
			else
			{
				long num = cost - initialBalance.Value;
				UpdateUI($"It looks like you need {num} more tokens to get the {storefrontGiftDrop.FriendlyName}.\n\nWould you like to learn how to get more tokens?", "Yes");
			}
		}

		private void TryPurchaseItem()
		{
			StorefrontGiftDrop item = purchasableGiftDropToBuy.GiftDrops[0];
			if (item == null)
			{
				UnityEngine.Debug.LogError("Can't purchase null item");
				return;
			}
			UpdateUI($"Purchasing {item.FriendlyName}...", null, showBack: false);
			Storefronts.PurchaseItem(StorefrontTypes.Watch, CurrencyType.RecCenterTokens, purchasableGiftDropToBuy.PurchasableItemId, delegate(string error, Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage> response)
			{
				if (string.IsNullOrEmpty(error) && response.BalanceUpdates.Count == 1 && response.BalanceUpdates[0].UpdateResponse == Storefronts.UpdateResponseTypes.OK)
				{
					packageToSpawn = response.BalanceUpdates[0].Data[0];
					if (!packageToSpawn.IsValid)
					{
						UnityEngine.Debug.LogError(packageToSpawn.ErrorMessage);
						UpdateUI($"Error purchasing item: {packageToSpawn.ErrorMessage}");
					}
					else if (!packageToSpawn.SupportsCurrentPlatform)
					{
						UnityEngine.Debug.LogError("Purchased item received is not supported on current platform!");
						UpdateUI("Error purchasing item :(");
					}
					else if (Avatars.GiftPackages.Contains(packageToSpawn))
					{
						UnityEngine.Debug.LogWarning("Bought duplicate gift!");
						UpdateUI("Bought duplicate gift!");
					}
					else if (packageToSpawn == null)
					{
						UnityEngine.Debug.LogError("Null gift package!");
						UpdateUI("Error purchasing item: Gift package is null");
					}
					else
					{
						int cost = purchasableGiftDropToBuy.GetCost(CurrencyType.RecCenterTokens);
						AnalyticsHelper.PurchasedItem(StorefrontTypes.RecCenter, AnalyticsHelper.PurchaseLocation.Watch, initialBalance, response.Balance, purchasableGiftDropToBuy.GiftDrops[0], cost);
						Avatars.GiftPackages.Add(packageToSpawn);
						if (Player.LocalPlayerExists)
						{
							SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Successfully purchased:", item.FriendlyName, 3f);
							if (string.IsNullOrEmpty(item.AvatarItemDesc))
							{
								Player.LocalPlayer.PlayerEvents.PurchasedNonClothingItem();
							}
							else
							{
								Player.LocalPlayer.PlayerEvents.PurchasedClothingItem();
							}
							SpawnGiftPackage();
						}
					}
				}
				else if (!string.IsNullOrEmpty(error))
				{
					UnityEngine.Debug.LogError(error);
					UpdateUI("Error purchasing items. Please try again later.");
				}
				else if (response != null)
				{
					string text = ((response.BalanceUpdates.Count <= 0) ? string.Empty : response.BalanceUpdates.Select((Storefronts.PurchaseBalanceUpdateResponseDTO<Avatars.GiftPackage>.BalanceUpdateDTO r) => ((int)r.UpdateResponse/*cast due to .constrained prefix*/).ToString()).Aggregate((string s, string s1) => s + "," + s1));
					UnityEngine.Debug.LogError("Responses:" + text + "\nError: " + error);
					if (response.BalanceUpdates != null && response.BalanceUpdates[0] != null && response.BalanceUpdates[0].UpdateResponse == Storefronts.UpdateResponseTypes.NoItemAvailable)
					{
						UpdateUI("No new items available. Please try again later.");
					}
					else
					{
						UpdateUI("Error purchasing items. Please try again later.");
					}
				}
				else
				{
					UnityEngine.Debug.LogError("Received null response from Storefront! " + error);
				}
			});
		}

		private void SpawnGiftPackage()
		{
			if (packageToSpawn == null)
			{
				UnityEngine.Debug.LogError("Cannot spawn null package");
				return;
			}
			if (SingletonMonoBehaviour<GiftManager>.Instance.ActiveGiftBox != null)
			{
				SingletonMonoBehaviour<GiftManager>.Instance.StopReceiveGiftsCoroutine();
			}
			Vector3 forward = Vector3.ProjectOnPlane(Player.LocalPlayer.Head.transform.forward, Vector3.up);
			Quaternion quaternion = Quaternion.LookRotation(forward);
			Vector3 boxPosition = Player.LocalPlayer.CurrentFloorPosition + quaternion * Vector3.forward * 0.6f;
			SingletonMonoBehaviour<GiftManager>.Instance.StartCoroutine(SingletonMonoBehaviour<GiftManager>.Instance.DequeueGift(packageToSpawn, boxPosition, quaternion, (Avatars.GiftPackage variant) => true, 4.4f));
			base.WatchUI.WatchMenuProjector.AuthorityCloseMenu();
			CloseScreen();
			packageToSpawn = null;
		}

		private void UpdateUI(string text, string confirmText = null, bool showBack = true)
		{
			if (this != null)
			{
				bodyText.text = text;
				confirmButton.gameObject.SetActive(!string.IsNullOrEmpty(confirmText));
				UIHelper.SafeSetText(confirmButton.Label, confirmText);
				backButton.gameObject.SetActive(showBack);
			}
		}

		private void OpenScreen()
		{
			base.WatchUI.PushFlow(this);
			if (this.OpenedPurchaseItemScreenEvent != null)
			{
				this.OpenedPurchaseItemScreenEvent();
			}
		}

		private void CloseScreen()
		{
			base.WatchUI.PopFlow();
			if (this.ClosedPurchaseItemScreenEvent != null)
			{
				this.ClosedPurchaseItemScreenEvent();
			}
		}

		[SkipRename]
		public void Button_Confirm()
		{
			if (hasEnoughTokens)
			{
				TryPurchaseItem();
			}
			else if (howToGetTokensScreen != null)
			{
				CloseScreen();
				base.WatchUI.PushFlow(howToGetTokensScreen);
			}
		}

		[SkipRename]
		public void Button_Back()
		{
			CloseScreen();
		}
	}
	public class StorePurchaseTokensScreen : WatchUIFlow
	{
		[Header("Buttons")]
		[SerializeField]
		private Button3D confirmButton;

		[SerializeField]
		private Button3D backButton;

		[SerializeField]
		private TextMeshProUGUI bodyText;

		[SerializeField]
		private PagedTextMeshPro3D pagedText;

		private bool showLongDescription;

		private Commerce.SKU skuToPurchase;

		public override void OnFlowExited(StackedUIFlowBase newFlow, bool stillOnStack)
		{
			base.OnFlowExited(newFlow, stillOnStack);
			skuToPurchase = null;
		}

		public void ShowScreen(Commerce.SKU sku)
		{
			skuToPurchase = sku;
			showLongDescription = !string.IsNullOrEmpty(sku.LongDescription);
			UpdateUI($"Tap Confirm to pay {skuToPurchase.DisplayPrice} for {skuToPurchase.Name}." + string.Format("{0}", (!Login.HasCompetingPlatformCachedLogin) ? string.Empty : "\n\nNote: Tokens move freely between all platforms except PlayStation® due to PlayStation® policies."), "Confirm");
			pagedText.gameObject.SetActive(showLongDescription);
			if (showLongDescription)
			{
				pagedText.SetText($"Item Description:\n\n{sku.LongDescription}");
			}
			if (!base.IsCurrentFlow)
			{
				base.WatchUI.PushFlow(this);
			}
		}

		private void HandleError(string action, string debugError)
		{
			UpdateUI($"An error occurred while trying to {action}. If this persists, please contact us at support@againstgrav.com.");
			UnityEngine.Debug.LogError(debugError);
		}

		private void UpdateUI(string text, string confirmText = null, bool showBack = true)
		{
			if (this != null)
			{
				bodyText.text = text;
				confirmButton.gameObject.SetActive(!string.IsNullOrEmpty(confirmText));
				UIHelper.SafeSetText(confirmButton.Label, confirmText);
				backButton.gameObject.SetActive(showBack);
			}
		}

		[SkipRename]
		public void Button_Confirm()
		{
		}

		[SkipRename]
		public void Button_Back()
		{
			if (base.IsCurrentFlow)
			{
				base.WatchUI.PopFlow();
			}
		}
	}
	public class StoreScreen : WatchUIFlow
	{
		public enum DisplayMode
		{
			Featured,
			Clothing,
			Other,
			NUX,
			Inventions,
			Tokens
		}

		[Flags]
		private enum Filters
		{
			None = 0,
			Purchasable = 1,
			Owned = 2,
			Locked = 4,
			Film = 8,
			Potion = 0x10,
			Food = 0x20,
			GiftBox = 0x40,
			Hat = 0x80,
			Hair = 0x100,
			Accessory = 0x200,
			Torso = 0x400,
			Glove = 0x800,
			OneStar = 0x1000,
			TwoStar = 0x2000,
			ThreeStar = 0x4000,
			FourStar = 0x8000,
			FiveStar = 0x10000,
			More = 0x20000
		}

		[Flags]
		private enum FilterGroups
		{
			OwnershipFilters = 7,
			RarityFilters = 0x1F000,
			ClothingFilters = 0xF80,
			ConsumableFilters = 0x20078
		}

		private enum SmallScreenButton
		{
			ExpandOnly = 1,
			FiveStarQuickFilter,
			FoodQuickFilter,
			KOSkinQuickFilter,
			PotionQuickFilter
		}

		[SerializeField]
		private TextMeshProUGUI tokenCount;

		[SerializeField]
		private GameObject itemsSubscreen;

		[SerializeField]
		private GameObject tokensSubscreen;

		[SerializeField]
		private GameObject searchRow;

		[SerializeField]
		private int featuredItemsGridSize = 10;

		[SerializeField]
		private int defaultItemsGridSize = 8;

		[Header("Featured filters toggles")]
		[SerializeField]
		private GameObject featuredFiltersGroup;

		[SerializeField]
		private ToggleButton3D fiveStarClothingToggle;

		[SerializeField]
		private ToggleButton3D purchasableToggle;

		[SerializeField]
		private ToggleButton3D foodToggle;

		[SerializeField]
		private ToggleButton3D moreToggle;

		[SerializeField]
		private ToggleButton3D potionToggle;

		[SerializeField]
		private GameObject koSkinsQuickFilterParent;

		[SerializeField]
		private GameObject hairDyeQuickFilterParent;

		[SerializeField]
		private GameObject starterPackQuickFilterParent;

		[Header("Buttons")]
		[SerializeField]
		private RadioButton3D featuredButton;

		[SerializeField]
		private RadioButton3D clothingButton;

		[SerializeField]
		private RadioButton3D otherButton;

		[SerializeField]
		private GameObject filterTogglesParent;

		[SerializeField]
		private GameObject radioButtonsParent;

		[SerializeField]
		private GameObject getTokensParent;

		[Header("Filters")]
		[SerializeField]
		private GameObject clothingOthersFilterGroup;

		[SerializeField]
		private GameObject clothingSpecificFilters;

		[SerializeField]
		private GameObject otherSpecificFilters;

		[SerializeField]
		private GameObject inventionsFilterGroup;

		[Header("Start Pack")]
		[SerializeField]
		private TextMeshProUGUI starterPackName;

		[SerializeField]
		private TextMeshProUGUI starterPackDescription;

		[SerializeField]
		private TextMeshProUGUI starterPackPrice;

		[SerializeField]
		private RawImage starterPackImage;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private InputField3D searchInputField;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private WatchStoreItemsPagedGrid itemsPagedGrid;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private WatchStoreTokensPagedGrid tokensPagedGrid;

		private GiftDropStorefront giftDropStorefront;

		private HowToGetTokensScreen howToGetTokensScreen;

		private StorePurchaseTokensScreen purchaseTokensScreen;

		private List<PurchasableGiftDrop> allDisplayModePurchasableGiftDrops = new List<PurchasableGiftDrop>();

		private List<PurchasableGiftDrop> searchFilteredPurchasableGiftDrops = new List<PurchasableGiftDrop>();

		private ToggleButton3D[] filterToggles = new ToggleButton3D[0];

		private int activeFilters;

		private int localPlayerLevel;

		private int defaultPagedGridColumnCount;

		private string currentQuery = string.Empty;

		private DisplayMode _storeDisplayMode;

		private SmallScreenButton _activeSmallScreenButton;

		public StorePurchaseItemScreen PurchaseItemScreen { get; private set; }

		private DisplayMode StoreDisplayMode
		{
			get
			{
				return _storeDisplayMode;
			}
			set
			{
				if (_storeDisplayMode != value)
				{
					_storeDisplayMode = value;
					searchInputField.Text = string.Empty;
					UpdateFiltersVisibility();
					ClearAllFilters();
					UpdateGridForDisplayMode();
					UpdateVisualsForDisplayMode();
				}
			}
		}

		private SmallScreenButton ActiveSmallScreenButton
		{
			get
			{
				return _activeSmallScreenButton;
			}
			set
			{
				if (_activeSmallScreenButton != value)
				{
					_activeSmallScreenButton = value;
					if (base.WatchUI.Size == SizeOption.LARGE)
					{
						WatchUI_ResizeCompleteEvent(SizeOption.LARGE);
					}
				}
			}
		}

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			PurchaseItemScreen = base.WatchUI.GetFlowByType<StorePurchaseItemScreen>();
			howToGetTokensScreen = base.WatchUI.GetFlowByType<HowToGetTokensScreen>();
			filterToggles = filterTogglesParent.GetComponentsInChildren<ToggleButton3D>();
			defaultPagedGridColumnCount = itemsPagedGrid.GridColumnCount;
			base.WatchUI.ResizeCompleteEvent += WatchUI_ResizeCompleteEvent;
			Storefronts.OnLocalPlayerBalanceUpdated += LocalPlayerBalanceUpdated;
			long? balance = Storefronts.GetBalance(CurrencyType.RecCenterTokens);
			tokenCount.text = $"{((!balance.HasValue) ? 0 : balance.Value):n0}";
			koSkinsQuickFilterParent.SetActive(value: true);
			hairDyeQuickFilterParent.SetActive(value: true);
			starterPackQuickFilterParent.SetActive(value: false);
		}

		public override void OnFlowEntered(StackedUIFlowBase oldFlow)
		{
			base.OnFlowEntered(oldFlow);
			localPlayerLevel = Profiles.LocalProfile.Level;
			if (base.WatchUI.Size == SizeOption.LARGE)
			{
				searchInputField.Text = string.Empty;
				UpdateSubscreenButtonPresses();
				UpdateFiltersVisibility();
				UpdateGridForDisplayMode();
				UpdateVisualsForDisplayMode();
				FilterItems();
			}
			Storefronts.GetStorefront(StorefrontTypes.Watch).Then(delegate(GiftDropStorefront sf)
			{
				giftDropStorefront = sf;
				UpdateGridForDisplayMode();
			});
		}

		protected override void OnDestroy()
		{
			base.WatchUI.ResizeCompleteEvent -= WatchUI_ResizeCompleteEvent;
			Storefronts.OnLocalPlayerBalanceUpdated -= LocalPlayerBalanceUpdated;
		}

		private void Update()
		{
			if (base.gameObject.activeSelf)
			{
				AnalyticsHelper.AccumulateTime("Watch_Store", UnityEngine.Time.unscaledDeltaTime);
			}
		}

		private void LocalPlayerBalanceUpdated(CurrencyType type, long balance)
		{
			if (type == CurrencyType.RecCenterTokens)
			{
				tokenCount.text = $"{balance:n0}";
			}
		}

		private void WatchUI_ResizeCompleteEvent(SizeOption size)
		{
			if (size != SizeOption.LARGE)
			{
				return;
			}
			switch (ActiveSmallScreenButton)
			{
			case SmallScreenButton.FiveStarQuickFilter:
				clothingButton.ForcePressed();
				ClearAllFilters();
				fiveStarClothingToggle.ForcePressed();
				purchasableToggle.ForcePressed();
				break;
			case SmallScreenButton.FoodQuickFilter:
				otherButton.ForcePressed();
				ClearAllFilters();
				foodToggle.ForcePressed();
				break;
			case SmallScreenButton.KOSkinQuickFilter:
				otherButton.ForcePressed();
				ClearAllFilters();
				moreToggle.ForcePressed();
				break;
			case SmallScreenButton.PotionQuickFilter:
				otherButton.ForcePressed();
				ClearAllFilters();
				potionToggle.ForcePressed();
				break;
			default:
				if (StoreDisplayMode == DisplayMode.Featured)
				{
					featuredButton.ForcePressed();
					UpdateFiltersVisibility();
					UpdateGridForDisplayMode();
					UpdateVisualsForDisplayMode();
				}
				break;
			}
			ActiveSmallScreenButton = SmallScreenButton.ExpandOnly;
		}

		private void UpdateSubscreenButtonPresses()
		{
			RadioButton3D radioButton3D = null;
			switch (StoreDisplayMode)
			{
			case DisplayMode.Featured:
				radioButton3D = featuredButton;
				break;
			case DisplayMode.Clothing:
				radioButton3D = clothingButton;
				break;
			case DisplayMode.Other:
				radioButton3D = otherButton;
				break;
			}
			if (radioButton3D != null)
			{
				radioButton3D.ForcePressed();
			}
		}

		private void ClearAllFilters()
		{
			activeFilters = 0;
			ToggleButton3D[] array = filterToggles;
			foreach (ToggleButton3D toggleButton3D in array)
			{
				toggleButton3D.ForceRelease();
			}
			itemsPagedGrid.SetItems(allDisplayModePurchasableGiftDrops, resetPage: false);
		}

		private void UpdateFiltersVisibility()
		{
			clothingOthersFilterGroup.SetActive(StoreDisplayMode == DisplayMode.Clothing || StoreDisplayMode == DisplayMode.Other);
			clothingSpecificFilters.SetActive(StoreDisplayMode == DisplayMode.Clothing);
			otherSpecificFilters.SetActive(StoreDisplayMode == DisplayMode.Other);
			inventionsFilterGroup.SetActive(StoreDisplayMode == DisplayMode.Inventions);
			featuredFiltersGroup.SetActive(StoreDisplayMode == DisplayMode.Featured);
		}

		private void UpdateVisualsForDisplayMode()
		{
			searchRow.SetActive(StoreDisplayMode == DisplayMode.Inventions || StoreDisplayMode == DisplayMode.Clothing || StoreDisplayMode == DisplayMode.Other);
			radioButtonsParent.SetActive(StoreDisplayMode != DisplayMode.NUX);
			getTokensParent.SetActive(StoreDisplayMode != DisplayMode.NUX);
			if (StoreDisplayMode == DisplayMode.NUX)
			{
				itemsPagedGrid.SetGridColumnnCount(3);
				itemsPagedGrid.SetPageSize(15);
			}
			else
			{
				itemsPagedGrid.SetGridColumnnCount(defaultPagedGridColumnCount);
				itemsPagedGrid.SetPageSize((StoreDisplayMode != DisplayMode.Featured) ? defaultItemsGridSize : featuredItemsGridSize);
			}
		}

		private void UpdateGridForDisplayMode()
		{
			tokensSubscreen.SetActive(StoreDisplayMode == DisplayMode.Tokens);
			itemsSubscreen.SetActive(StoreDisplayMode != DisplayMode.Tokens);
			List<PurchasableGiftDrop> source = ((giftDropStorefront == null) ? new List<PurchasableGiftDrop>() : giftDropStorefront.StoreItems);
			switch (StoreDisplayMode)
			{
			case DisplayMode.Featured:
				allDisplayModePurchasableGiftDrops = source.Where((PurchasableGiftDrop item) => item.IsFeatured).Take(10).ToList();
				break;
			case DisplayMode.Clothing:
			case DisplayMode.NUX:
				allDisplayModePurchasableGiftDrops = source.Where((PurchasableGiftDrop item) => item.GiftDrops[0].Content == GiftManager.GiftBoxContents.Avatar).ToList();
				break;
			case DisplayMode.Other:
				allDisplayModePurchasableGiftDrops = source.Where((PurchasableGiftDrop item) => item.GiftDrops[0].Content != GiftManager.GiftBoxContents.Avatar).ToList();
				break;
			case DisplayMode.Inventions:
				allDisplayModePurchasableGiftDrops = new List<PurchasableGiftDrop>();
				break;
			default:
				throw new NotImplementedException("Unknown store category");
			}
			itemsPagedGrid.SetItems(allDisplayModePurchasableGiftDrops, resetPage: true);
		}

		private void DisplayModeButtonPressed(DisplayMode displayMode)
		{
			StoreDisplayMode = displayMode;
		}

		private void UpdateActiveFilters(Filters filter, bool active)
		{
			if (StoreDisplayMode != DisplayMode.Featured)
			{
				if (active)
				{
					activeFilters |= (int)filter;
				}
				else
				{
					activeFilters &= (int)(~filter);
				}
				FilterItems();
			}
		}

		private void FilterItems()
		{
			if (string.IsNullOrEmpty(currentQuery))
			{
				searchFilteredPurchasableGiftDrops = allDisplayModePurchasableGiftDrops;
			}
			if (activeFilters == 0)
			{
				itemsPagedGrid.SetItems(searchFilteredPurchasableGiftDrops, resetPage: true);
				return;
			}
			List<PurchasableGiftDrop> list = new List<PurchasableGiftDrop>();
			foreach (PurchasableGiftDrop searchFilteredPurchasableGiftDrop in searchFilteredPurchasableGiftDrops)
			{
				StorefrontGiftDrop item = searchFilteredPurchasableGiftDrop.GiftDrops[0];
				if (((activeFilters & 7) != 0 && !MatchesPurchasableFilter(item) && !MatchesOwnedFilter(item) && !MatchesLockedFilter(item)) || ((activeFilters & 0x1F000) != 0 && !Matches1StarFilter(item) && !Matches2StarFilter(item) && !Matches3StarFilter(item) && !Matches4StarFilter(item) && !Matches5StarFilter(item)))
				{
					continue;
				}
				if (StoreDisplayMode == DisplayMode.Clothing)
				{
					if ((activeFilters & 0xF80) != 0 && !MatchesHatFilter(item) && !MatchesHairFilter(item) && !MatchesAccessoryFilter(item) && !MatchesTorsoFilter(item) && !MatchesGloveFilter(item))
					{
						continue;
					}
				}
				else if (StoreDisplayMode == DisplayMode.Other && (activeFilters & 0x20078) != 0 && !MatchesFilmFilter(item) && !MatchesPotionFilter(item) && !MatchesFoodFilter(item) && !MatchesGiftboxFilter(item) && !MatchesMoreFilter(item))
				{
					continue;
				}
				list.Add(searchFilteredPurchasableGiftDrop);
			}
			itemsPagedGrid.SetItems(list, resetPage: true);
		}

		private void SearchItems()
		{
			if (!string.IsNullOrEmpty(currentQuery))
			{
				searchFilteredPurchasableGiftDrops = allDisplayModePurchasableGiftDrops.Where((PurchasableGiftDrop gd) => gd.GiftDrops[0].FriendlyName.CaseInsensitiveContains(currentQuery)).ToList();
			}
			FilterItems();
		}

		private bool MatchesPurchasableFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 1) != 0 && item.Level <= localPlayerLevel && (item.Content == GiftManager.GiftBoxContents.Consumable || (item.Content == GiftManager.GiftBoxContents.Avatar && !NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.IsOutfitUnlockedOnCurrentPlatform(item.AvatarItemDesc)) || (item.Content == GiftManager.GiftBoxContents.Equipment && !NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.IsEquipmentUnlockedOnCurrentPlatform(item.EquipmentModificationGuid)));
		}

		private bool MatchesOwnedFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 2) != 0 && ((item.Content == GiftManager.GiftBoxContents.Avatar && NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.IsOutfitUnlockedOnCurrentPlatform(item.AvatarItemDesc)) || (item.Content == GiftManager.GiftBoxContents.Equipment && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.IsEquipmentUnlockedOnCurrentPlatform(item.EquipmentModificationGuid)) || (item.Content == GiftManager.GiftBoxContents.Consumable && NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.IsConsumablePurchased(item.ConsumableItemDesc)));
		}

		private bool MatchesLockedFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 4) != 0 && item.Level > localPlayerLevel;
		}

		private bool Matches1StarFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x1000) != 0 && item.Rarity == GiftManager.GiftRarity.Common;
		}

		private bool Matches2StarFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x2000) != 0 && item.Rarity == GiftManager.GiftRarity.Uncommon;
		}

		private bool Matches3StarFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x4000) != 0 && item.Rarity == GiftManager.GiftRarity.Rare;
		}

		private bool Matches4StarFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x8000) != 0 && item.Rarity == GiftManager.GiftRarity.Epic;
		}

		private bool Matches5StarFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x10000) != 0 && item.Rarity == GiftManager.GiftRarity.Legendary;
		}

		private bool MatchesHatFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x80) != 0 && GetOutfitType(item) == OutfitManager.OutfitType.Hat;
		}

		private bool MatchesHairFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x100) != 0 && (GetOutfitType(item) == OutfitManager.OutfitType.Hair || GetOutfitType(item) == OutfitManager.OutfitType.Mouth);
		}

		private bool MatchesAccessoryFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x200) != 0 && (GetOutfitType(item) == OutfitManager.OutfitType.Eye || GetOutfitType(item) == OutfitManager.OutfitType.Neck || GetOutfitType(item) == OutfitManager.OutfitType.Belt);
		}

		private bool MatchesTorsoFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x400) != 0 && GetOutfitType(item) == OutfitManager.OutfitType.Shirt;
		}

		private bool MatchesGloveFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x800) != 0 && (GetOutfitType(item) == OutfitManager.OutfitType.Glove || GetOutfitType(item) == OutfitManager.OutfitType.Wrist);
		}

		private bool MatchesFilmFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 8) != 0 && GetConsumableCategory(item) == ConsumableManager.Category.CameraFilter;
		}

		private bool MatchesPotionFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x10) != 0 && (GetConsumableCategory(item) == ConsumableManager.Category.Potion_Hand || GetConsumableCategory(item) == ConsumableManager.Category.Potion_Head || GetConsumableCategory(item) == ConsumableManager.Category.Potion_HairDye);
		}

		private bool MatchesFoodFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x20) != 0 && GetConsumableCategory(item) == ConsumableManager.Category.Food;
		}

		private bool MatchesGiftboxFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x40) != 0 && item.IsQuery;
		}

		private bool MatchesMoreFilter(StorefrontGiftDrop item)
		{
			return (activeFilters & 0x20000) != 0 && (GetConsumableCategory(item) == ConsumableManager.Category.KO_Customization || item.Content == GiftManager.GiftBoxContents.Equipment);
		}

		private OutfitManager.OutfitType GetOutfitType(StorefrontGiftDrop item)
		{
			OutfitSelection outfitSelection = OutfitSelection.Parse(item.AvatarItemDesc);
			return (!(outfitSelection == null)) ? outfitSelection.outfitItem.Type : OutfitManager.OutfitType.None;
		}

		private ConsumableManager.Category GetConsumableCategory(StorefrontGiftDrop item)
		{
			ConsumableItem consumablePrefab = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.GetConsumablePrefab(item.ConsumableItemDesc);
			return (!(consumablePrefab == null)) ? consumablePrefab.Category : ConsumableManager.Category.Invalid;
		}

		private void EndOfFrameRoutine(Action action)
		{
			MonoBehaviourExt.EndOfFrameRoutine(this, action);
		}

