namespace AGUI.StackedUI.Dialog
{
	public struct TakePictureDialogResponse
	{
		public ConfirmDialogResponses responseType;

		public AltTextureSet photoSet;

		public static TakePictureDialogResponse Cancel = new TakePictureDialogResponse(ConfirmDialogResponses.Cancel, null);

		public TakePictureDialogResponse(ConfirmDialogResponses responseType, AltTextureSet photoSet)
		{
			this.responseType = responseType;
			this.photoSet = photoSet;
		}
	}
	public abstract class TakePictureDialog<T> : UIDialog<T, TakePictureDialogResponse>
	{
		[SerializeField]
		private Button3D flipCameraButton;

		[SerializeField]
		private Button3D takePictureButton;

		[SerializeField]
		private Button3D saveButton;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private Camera dialogCamera;

		[SerializeField]
		[Autofill(AutofillType.Children, false)]
		private RawImage image;

		[SerializeField]
		private TextMeshProUGUI countdownText;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[Header("Audio")]
		[SerializeField]
		private RecRoomAudioClip countDownTickAudio;

		[SerializeField]
		private RecRoomAudioClip shutterAudio;

		private RenderTexture renderTexture;

		protected AltTextureSet photoSet;

		public override void Initialize(StackedUIBase uiBase)
		{
			base.Initialize(uiBase);
			renderTexture = new RenderTexture(2560, 1440, 24);
			renderTexture.antiAliasing = ((QualitySettings.antiAliasing <= 0) ? 1 : QualitySettings.antiAliasing);
			dialogCamera.targetTexture = renderTexture;
			dialogCamera.aspect = ShareCamera.SixteenNineAspectRatio;
			dialogCamera.depthTextureMode = DepthTextureMode.Depth;
			if (RecRoomSceneManager.IsInitialized && RecRoomSceneManager.Instance.SceneRenderingSettings != null)
			{
				RecRoomSceneManager.Instance.SceneRenderingSettings.ApplySceneCameraOverrides(dialogCamera);
			}
		}

		protected override void OnDestroy()
		{
			base.OnDestroy();
			if (renderTexture != null)
			{
				renderTexture.Release();
			}
			if (photoSet != null)
			{
				photoSet.DestroyTextures();
			}
		}

		private void OnEnable()
		{
			countdownText.gameObject.SetActive(value: false);
			takePictureButton.Interactable = true;
		}

		public override IPromise<TakePictureDialogResponse> ShowDialog()
		{
			countdownText.gameObject.SetActive(value: false);
			UpdateUI(string.Empty, enableButtons: true);
			saveButton.Interactable = false;
			photoSet = null;
			SetCameraRenderTexture();
			return base.ShowDialog();
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(TakePictureDialogResponse.Cancel, shouldCloseDialog);
		}

		protected void UpdateUI(string info, bool enableButtons)
		{
			infoText.text = info;
			flipCameraButton.Interactable = enableButtons;
			takePictureButton.Interactable = enableButtons;
		}

		private void SetCameraRenderTexture()
		{
			image.texture = renderTexture;
		}

		private IEnumerator RunTakePicture()
		{
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: true);
			countdownText.text = "3";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "2";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(countDownTickAudio, base.transform.position);
			countdownText.text = "1";
			yield return new WaitForSeconds(1f);
			AudioManager.Play3DSFX(shutterAudio, base.transform.position);
			countdownText.gameObject.SetActive(value: false);
			photoSet = new AltTextureSet();
			photoSet.Render(dialogCamera, renderTexture);
			image.texture = photoSet.MainTexture;
			takePictureButton.Interactable = true;
			saveButton.Interactable = true;
			UpdateUI(string.Empty, enableButtons: true);
		}

		private IEnumerator RunTakePictureAndSave()
		{
			yield return RunTakePicture();
			Button_Save();
		}

		protected abstract void ProcessPicture();

		[SkipRename]
		public void Button_FlipCamera()
		{
			SetCameraRenderTexture();
			saveButton.Interactable = false;
			dialogCamera.transform.rotation = Quaternion.LookRotation(-dialogCamera.transform.forward, dialogCamera.transform.up);
		}

		[SkipRename]
		public void Button_TakePicture()
		{
			UpdateUI(string.Empty, enableButtons: false);
			SetCameraRenderTexture();
			StartCoroutine(RunTakePicture());
		}

		[SkipRename]
		public void Button_Save()
		{
			UpdateUI("Uploading...", enableButtons: false);
			ProcessPicture();
		}

		[SkipRename]
		public void Button_TakePictureAndSave()
		{
			UpdateUI(string.Empty, enableButtons: false);
			SetCameraRenderTexture();
			StartCoroutine(RunTakePictureAndSave());
		}
	}
	public class TimeRangeSelectionDialog : UIDialog<TimeRangeSelectionDialog.StartEndTimes>
	{
		public class StartEndTimes
		{
			public int startHours24;

			public int startMinutes;

			public int endHours24;

			public int endMinutes;
		}

		[SerializeField]
		private TextMeshProUGUI currentTimeText;

		[SerializeField]
		private ValidatedButtonInputField startTimeHoursField;

		[SerializeField]
		private ValidatedButtonInputField startTimeMinutesField;

		[SerializeField]
		private ValidatedButtonInputField endTimeHoursField;

		[SerializeField]
		private ValidatedButtonInputField endTimeMinutesField;

		[SerializeField]
		private Slider3D startTimeAMPM;

		[SerializeField]
		private Slider3D endTimeAMPM;

		[SerializeField]
		private TextMeshProUGUI infoText;

		private string startTimeHoursString = string.Empty;

		private string startTimeMinutesString = string.Empty;

		private string endTimeHoursString = string.Empty;

		private string endTimeMinutesString = string.Empty;

		private StartEndTimes enteredTimeRange;

		private void Start()
		{
			startTimeHoursField.InputField3D.SelectInputField();
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(null, shouldCloseDialog: true);
		}

		public override IPromise<StartEndTimes> ShowDialog()
		{
			SetInfoText(string.Empty);
			currentTimeText.text = $"Current time: {DateTime.UtcNow.ToLocalTime().ToShortTimeString()}";
			startTimeHoursField.IsValidFunction = delegate(string hours)
			{
				startTimeHoursString = hours;
				if (hours.Trim().Length == 2)
				{
					startTimeMinutesField.InputField3D.SelectInputField();
				}
				return TryParseInput();
			};
			startTimeMinutesField.IsValidFunction = delegate(string minutes)
			{
				startTimeMinutesString = minutes;
				if (minutes.Trim().Length == 2)
				{
					endTimeHoursField.InputField3D.SelectInputField();
				}
				return TryParseInput();
			};
			endTimeHoursField.IsValidFunction = delegate(string hours)
			{
				endTimeHoursString = hours;
				if (hours.Trim().Length == 2)
				{
					endTimeMinutesField.InputField3D.SelectInputField();
				}
				return TryParseInput();
			};
			endTimeMinutesField.IsValidFunction = delegate(string minutes)
			{
				endTimeMinutesString = minutes;
				if (minutes.Trim().Length == 2)
				{
					endTimeHoursField.InputField3D.SelectInputField();
				}
				return TryParseInput();
			};
			return base.ShowDialog();
		}

		public void SetInfoText(string message)
		{
			infoText.text = message;
		}

		public void SetTimeRange(StartEndTimes timeRange)
		{
			if (timeRange != null)
			{
				startTimeHoursField.Text = Convert24HrsTo12Hrs(timeRange.startHours24).ToString();
				startTimeMinutesField.Text = timeRange.startMinutes.ToString("D2");
				bool flag = timeRange.startHours24 > 11;
				startTimeAMPM.value = (flag ? 1 : 0);
				endTimeHoursField.Text = Convert24HrsTo12Hrs(timeRange.endHours24).ToString();
				endTimeMinutesField.Text = timeRange.endMinutes.ToString("D2");
				flag = timeRange.endHours24 > 11;
				endTimeAMPM.value = (flag ? 1 : 0);
			}
		}

		private bool TryParseInput()
		{
			enteredTimeRange = null;
			SetInfoText(string.Empty);
			bool flag = !string.IsNullOrEmpty(startTimeHoursString);
			bool flag2 = !string.IsNullOrEmpty(startTimeMinutesString);
			bool flag3 = !string.IsNullOrEmpty(endTimeHoursString);
			bool flag4 = !string.IsNullOrEmpty(startTimeMinutesString);
			if (!flag && !flag2 && !flag3 && !flag4)
			{
				return false;
			}
			int result = -1;
			int result2 = -1;
			int result3 = -1;
			int result4 = -1;
			if (flag && !int.TryParse(startTimeHoursString.Trim(), out result))
			{
				SetInfoText("Invalid start hour");
				return false;
			}
			if (flag2 && !int.TryParse(startTimeMinutesString.Trim(), out result2))
			{
				SetInfoText("Invalid start minute");
				return false;
			}
			if (flag3 && !int.TryParse(endTimeHoursString.Trim(), out result3))
			{
				SetInfoText("Invalid end hour");
				return false;
			}
			if (flag4 && !int.TryParse(endTimeMinutesString.Trim(), out result4))
			{
				SetInfoText("Invalid end minute");
				return false;
			}
			if (!flag || !flag2 || !flag3 || !flag4)
			{
				return false;
			}
			if (result < 1 || result > 12)
			{
				SetInfoText("Start hour must be between 1 and 12");
				return false;
			}
			if (result2 < 0 || result2 > 59)
			{
				SetInfoText("Start minute must be between 0 and 59");
				return false;
			}
			if (result3 < 1 || result3 > 12)
			{
				SetInfoText("End hour must be between 1 and 12");
				return false;
			}
			if (result4 < 0 || result4 > 59)
			{
				SetInfoText("End minute must be between 0 and 59");
				return false;
			}
			enteredTimeRange = new StartEndTimes
			{
				startHours24 = Convert12HrsTo24Hrs(result, startTimeAMPM.value > 0.5f),
				startMinutes = result2,
				endHours24 = Convert12HrsTo24Hrs(result3, endTimeAMPM.value > 0.5f),
				endMinutes = result4
			};
			return true;
		}

		[SkipRename]
		public void Button_Submit()
		{
			if (TryParseInput())
			{
				Respond(enteredTimeRange, shouldCloseDialog: true);
			}
		}

		[SkipRename]
		public void Button_Cancel()
		{
			ForceCancel(shouldCloseDialog: true);
		}

		private int Convert24HrsTo12Hrs(int hour)
		{
			hour %= 12;
			if (hour == 0)
			{
				return 12;
			}
			return hour;
		}

		private int Convert12HrsTo24Hrs(int hour, bool isPM)
		{
			if (hour == 12)
			{
				return isPM ? 12 : 0;
			}
			return (!isPM) ? hour : (hour + 12);
		}
	}
	public class UIDateSelectionDialog : UIDialog<DateTime?>
	{
		public delegate void DateConversion(ref int month, ref int day, ref int year);

		public delegate string AdditionalDateValidation(int month, int day, int year);

		public DateConversion customDateConversion;

		public AdditionalDateValidation customDateValidation;

		[SerializeField]
		private TextMeshProUGUI infoText;

		[SerializeField]
		private ValidatedButtonInputField monthField;

		[SerializeField]
		private ValidatedButtonInputField dayField;

		[SerializeField]
		private ValidatedButtonInputField yearField;

		[SerializeField]
		private Button3D submitButton;

		[SerializeField]
		private bool displayYear = true;

		[SerializeField]
		private GameObject yearContainer;

		private string monthString = string.Empty;

		private string dayString = string.Empty;

		private string yearString = string.Empty;

		private DateTime? enteredDate;

		public bool DisplayYear
		{
			get
			{
				return yearContainer != null && yearContainer.activeSelf;
			}
			set
			{
				yearContainer.SetActive(value);
			}
		}

		private void Awake()
		{
			DisplayYear = displayYear;
		}

		private void Start()
		{
			monthField.InputField3D.SelectInputField();
		}

		public void SetTitleText(string titleText)
		{
			ScreenHeader componentInChildren = GetComponentInChildren<ScreenHeader>();
			if (componentInChildren != null)
			{
				componentInChildren.Title = titleText;
			}
		}

		public void SetInfoText(string info)
		{
			infoText.text = info;
		}

		public void EnableButtons(bool enableButtons)
		{
			monthField.Interactable = enableButtons;
			dayField.Interactable = enableButtons;
			yearField.Interactable = enableButtons;
			submitButton.Interactable = enableButtons;
		}

		public void SetCurrentDate(DateTime date)
		{
			dayField.Text = date.Day.ToString();
			monthField.Text = date.Month.ToString();
			yearField.Text = date.Year.ToString();
			TryParseDate();
		}

		public override IPromise<DateTime?> ShowDialog()
		{
			SetInfoText(string.Empty);
			EnableButtons(enableButtons: true);
			monthField.IsValidFunction = delegate(string month)
			{
				monthString = month;
				if (month.Trim().Length == 2)
				{
					dayField.InputField3D.SelectInputField();
				}
				return TryParseDate();
			};
			dayField.IsValidFunction = delegate(string day)
			{
				dayString = day;
				if (day.Trim().Length == 2)
				{
					yearField.InputField3D.SelectInputField();
				}
				return TryParseDate();
			};
			yearField.IsValidFunction = delegate(string year)
			{
				yearString = year;
				return TryParseDate();
			};
			return base.ShowDialog();
		}

		private bool TryParseDate()
		{
			enteredDate = null;
			infoText.text = string.Empty;
			int result = -1;
			int result2 = -1;
			int result3 = -1;
			bool flag = !string.IsNullOrEmpty(monthString);
			bool flag2 = !string.IsNullOrEmpty(dayString);
			bool flag3 = !string.IsNullOrEmpty(yearString) && yearString.Trim().Length == 4;
			if (!flag && !flag2 && !flag3)
			{
				return false;
			}
			if (flag && !int.TryParse(monthString.Trim(), out result))
			{
				infoText.text = "Invalid month entered";
				return false;
			}
			if (flag2 && !int.TryParse(dayString.Trim(), out result2))
			{
				infoText.text = "Invalid day entered";
				return false;
			}
			if (flag3 && !int.TryParse(yearString.Trim(), out result3))
			{
				infoText.text = "Invalid year entered";
				return false;
			}
			if (!flag || !flag2 || !flag3)
			{
				return false;
			}
			if (customDateConversion != null)
			{
				customDateConversion(ref result, ref result2, ref result3);
			}
			if (flag2)
			{
				int num = 31;
				if (flag3 && flag)
				{
					num = DateTime.DaysInMonth(result3, result);
				}
				if (result2 < 1 || result2 > num)
				{
					infoText.text = "That day doesn't make sense!";
					return false;
				}
			}
			if (customDateValidation != null)
			{
				string value = customDateValidation(result, result2, result3);
				if (!string.IsNullOrEmpty(value))
				{
					SetInfoText(value);
					return false;
				}
			}
			try
			{
				enteredDate = new DateTime(result3, result, result2);
				infoText.text = GetDateFormatted(enteredDate.Value);
				return true;
			}
			catch
			{
				infoText.text = "Invalid date. Please resubmit a valid date.";
				return false;
			}
		}

		private string GetDateFormatted(DateTime localDateTime)
		{
			DateTime dateTime = DateTime.Today.ToLocalTime();
			DateTime dateTime2 = dateTime.AddDays(1.0);
			if (dateTime.Day == localDateTime.Day && dateTime.Month == localDateTime.Month && dateTime.Year == localDateTime.Year)
			{
				return "Today";
			}
			if (dateTime2.Day == localDateTime.Day && dateTime2.Month == localDateTime.Month && dateTime2.Year == localDateTime.Year)
			{
				return "Tomorrow";
			}
			string text = null;
			if (DisplayYear)
			{
				try
				{
					return localDateTime.ToString("MMMM d, yyyy");
				}
				catch (Exception)
				{
					try
					{
						return localDateTime.ToString("d");
					}
					catch (Exception)
					{
						return $"Month: {localDateTime.Month}  Day: {localDateTime.Day}  Year: {localDateTime.Year}";
					}
				}
			}
			try
			{
				return localDateTime.ToString("dddd, MMMM d");
			}
			catch (Exception)
			{
				return $"Month: {localDateTime.Month}  Day: {localDateTime.Day}";
			}
		}

		public override void ForceCancel(bool shouldCloseDialog)
		{
			Respond(null, shouldCloseDialog: true);
		}

		[SkipRename]
		public void Button_Submit()
		{
			if (TryParseDate())
			{
				Respond(enteredDate, shouldCloseDialog: true);
			}
		}

		[SkipRename]
		public void Button_Cancel()
		{
			ForceCancel(shouldCloseDialog: true);
		}
	}
	public class UpdatePlayerEventDescriptionDialog : EnterTextDialog<PlayerEvent>
	{
		private PlayerEvent targetEvent;

		public override IPromise<EnterTextDialogResponse> ShowDialog(PlayerEvent playerEvent)
		{
			targetEvent = playerEvent;
			if (targetEvent != null)
			{
				inputField.Text = targetEvent.Description;
			}
			else
			{
				UnityEngine.Debug.LogError("targerEvent is null");
			}
			return ShowDialog();
		}

		protected override bool ValidateInput(string str)
		{
			inputString = str.Trim();
			if (inputString.Length > RecNet.PlayerEvents.MAX_DESCRIPTION_LENGTH)
			{
				infoText.text = "Event description too long!";
				return false;
			}
			return base.ValidateInput(str);
		}

		protected override void ProcessText()
		{
			if (targetEvent != null && ValidateInput(inputString))
			{
				UpdateUI("Updating...", enableButtons: false);
				RecNet.PlayerEvents.ModifyEvent(targetEvent, targetEvent.RoomId, targetEvent.Name, inputString, targetEvent.StartTime, targetEvent.EndTime, targetEvent.Accessibility).Then(HandleModifyResponse);
			}
		}

		private void HandleModifyResponse(CreateModifyPlayerEventResponse response)
		{
			switch (response.Result)
			{
			case CreateModifyPlayerEventStatus.Success:
				Respond(new EnterTextDialogResponse(ConfirmDialogResponses.Affirmative, response.PlayerEvent.Description), shouldCloseDialog: true);
				SingletonMonoBehaviour<ScreenSpaceNotificationManager>.Instance.Play(ScreenSpaceNotificationManager.NotificationType.Medium, "Updated!", 3f);
				break;
			case CreateModifyPlayerEventStatus.PlayerDoesNotExist:
				infoText.text = "Player doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.RoomDoesNotExist:
				infoText.text = "Room doesn't exist.";
				break;
			case CreateModifyPlayerEventStatus.DoesNotOwnRoom:
				infoText.text = "You don't own this room.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateName:
				infoText.text = "Inappropriate name.";
				break;
			case CreateModifyPlayerEventStatus.InappropriateDescription:
				infoText.text = "Inappropriate description.";
				break;
			case CreateModifyPlayerEventStatus.HasModeratorClosedEvent:
				infoText.text = "One of you events is under moderation review. Contact conduct@againstgrav.com";
				break;
			case CreateModifyPlayerEventStatus.EventDatesInvalid:
				infoText.text = "Event date / time is invalid";
				break;
			case CreateModifyPlayerEventStatus.EventTooLong:
				infoText.text = "Event duration is too long";
				break;
			case CreateModifyPlayerEventStatus.EventTooShort:
				infoText.text = "Event duration is too short";
				break;
			case CreateModifyPlayerEventStatus.EventCountLimitReached:
				infoText.text = "You already have the maximum number of open events.";
				break;
			default:
				infoText.text = response.Result.ToString();
				UnityEngine.Debug.LogError(response.Result);
				break;
			}
		}
	}
