	public class UpdateRoomDescriptionDialog : EnterTextDialog<RoomDetails>
	{
		private RoomDetails targerRoomDetails;

		public override IPromise<EnterTextDialogResponse> ShowDialog(RoomDetails roomDetails)
		{
			targerRoomDetails = roomDetails;
			if (targerRoomDetails != null)
			{
				inputField.Text = targerRoomDetails.Room.Description;
			}
			else
			{
				UnityEngine.Debug.LogError("targetRoom is null");
			}
			return ShowDialog();
		}

		protected override void ProcessText()
		{
			if (targerRoomDetails != null && ValidateInput(inputString))
			{
				UpdateUI("Saving...", enableButtons: false);
				RecNet.Rooms.ModifyRoomDescription(targerRoomDetails.Room.RoomId, inputString, HandleCreateResponse);
			}
		}

		private void HandleCreateResponse(string error, RecNet.Rooms.CreateModifyRoomResponse response)
		{
			if (string.IsNullOrEmpty(error))
			{
				if (response.Result != RecNet.Rooms.CreateModifyRoomStatus.Success)
				{
					UnityEngine.Debug.LogErrorFormat("Failed to update: " + response.Result);
				}
				switch (response.Result)
				{
				case RecNet.Rooms.CreateModifyRoomStatus.Success:
					Respond(new EnterTextDialogResponse(ConfirmDialogResponses.Affirmative, response.RoomDetails.Room.Description), shouldCloseDialog: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.JuniorStatusFail:
					UpdateUI("You can't update rooms!", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PermissionDenied:
					UpdateUI("Error updating. Please try again.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.InappropriateDescription:
					UpdateUI("Failed to update. \"" + inputString + "\" contains inappropriate words.", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.TooManyRooms:
					UpdateUI("Failed to update. You have hit the maximum number of allowed rooms :(", enableButtons: true);
					break;
				case RecNet.Rooms.CreateModifyRoomStatus.PlayerHasRoomUnderModerationReview:
					UpdateUI("Failed to update. You have a room under moderation review. Contact conduct@againstgrav.com", enableButtons: true);
					break;
				default:
					UpdateUI("Error updating. If this persists, please contact the developers at support@againstgrav.com.", enableButtons: true);
					break;
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Failed to update: " + error);
				UpdateUI("Failed to update: " + error, enableButtons: true);
			}
		}
	}
