namespace RecRoom.AGUI
{
	public class SubroomButtonPagedGrid : RecyclerPagedGrid<string, SubroomButton>
	{
		[Serializable]
		public class SubroomChosen : UnityEvent<string>
		{
		}

		[SerializeField]
		[Autofill(AutofillType.Self, false)]
		private RadioGroup3D radioGroup;

		public SubroomChosen OnSubroomChosenEvent;

		private void Start()
		{
			if (OnSubroomChosenEvent == null)
			{
				return;
			}
			foreach (SubroomButton childUIElement in childUIElements)
			{
				SubroomButton innerChild = childUIElement;
				innerChild.RadioButton.OnClick.AddListener(delegate
				{
					OnSubroomChosenEvent.Invoke(innerChild.SceneName);
				});
				radioGroup.AddButton(innerChild.RadioButton);
