public class TierRewardPagedGrid : RecyclerPagedGrid<PurchasableSeasonTier, TierRewardSpawner>
{
	[Serializable]
	public class BuyTierEvent : UnityEvent<int>
	{
	}

	[SerializeField]
	private UnityEngine.UI.Image freeBackground;

	[SerializeField]
	private UnityEngine.UI.Image paidBackground;

	[Header("Colors")]
	[SerializeField]
	private Color freeRewardsColor;

	[SerializeField]
	private Color paidRewardsBasicPlayerColor;

	[SerializeField]
	private Color paidRewardsElitePlayerColor;

	private PlayerStorefrontSeasonDTO personalDetails;

	private WatchUIFlow thisFlow;

	public BuyTierEvent OnBuyTierEvent;

	private void Start()
	{
		if (OnBuyTierEvent == null)
		{
			return;
		}
		foreach (TierRewardSpawner childUIElement in childUIElements)
		{
			TierRewardSpawner innerChild = childUIElement;
			innerChild.ButtonAction.AddListener(delegate
			{
				OnBuyTierEvent.Invoke(innerChild.TierNumber);
			});
		}
	}

	public void SetTiers(IEnumerable<PurchasableSeasonTier> tiers, PlayerStorefrontSeasonDTO details, WatchUIFlow watchUIFlow)
	{
		thisFlow = watchUIFlow;
		freeBackground.color = freeRewardsColor;
		paidBackground.color = ((!details.HasEliteUpgrade) ? paidRewardsBasicPlayerColor : paidRewardsElitePlayerColor);
		personalDetails = details;
		SetAllActiveChildren(tiers, resetPage: false);
	}

	public void UpdateBuyButton(int tierNumber, bool interactable, string text)
	{
		int num = (tierNumber - 1) % base.PageSize;
		if (num >= 0 && num < childUIElements.Count)
		{
			childUIElements[num].UpdateBuyButton(interactable, text);
		}
	}

	public Transform GetUnlockedTierTransform(int tierNumber)
	{
		int num = (tierNumber - 1) % base.PageSize;
		if (num >= 0 && num < childUIElements.Count)
		{
			return childUIElements[num].transform;
		}
		return null;
	}

	public void PlayUnlockAnimation(int tierNumber, float duration)
	{
		int num = (tierNumber - 1) % base.PageSize;
		if (num >= 0 && num < childUIElements.Count)
		{
			childUIElements[num].PlayUnlockAnimation(duration);
		}
	}

	protected override void SetChild(PurchasableSeasonTier tier, TierRewardSpawner spawner, int activeIndex)
	{
		spawner.ThisFlow = thisFlow;
		spawner.SetTier(tier, personalDetails.HasEliteUpgrade, personalDetails.CurrentSeasonTierNumber >= tier.TierNumber, tier.TierNumber == personalDetails.CurrentSeasonTierNumber + 1);
	}
}
public class TierRewardSpawner : UnityEngine.MonoBehaviour
{
	private struct RewardVisual
	{
		public Transform transform;

		public Vector3 normalScale;

		public Vector3 largeScale;
	}

	private const float NORMAL_REWARD_SIZE = 0.025f;

	private const float LARGE_REWARD_SIZE = 0.0375f;

	private static readonly int TIER_UNLOCKING_ANIMATION_ID = Animator.StringToHash("Unlocking");

	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private Animator animator;

	[SerializeField]
	private GiftBoxMerchVisual giftBoxMerchVisualPrefab;

	[SerializeField]
	private GameObject xpBoostVisualPrefab;

	[SerializeField]
	private TextMeshProUGUI tierNumberText;

	[SerializeField]
	private Transform backgroundParent;

	[SerializeField]
	private Button3D buyTierButton;

	[Header("Free")]
	[SerializeField]
	private Transform[] freeRewardRoots = new Transform[0];

	[SerializeField]
	private GameObject freeRewardBottomRow;

	[SerializeField]
	private UnityEngine.UI.Image freeBackground;

	[SerializeField]
	private GameObject freeLockObject;

	[Header("Paid")]
	[SerializeField]
	private Transform[] paidRewardRoots = new Transform[0];

	[SerializeField]
	private GameObject paidRewardBottomRow;

	[SerializeField]
	private UnityEngine.UI.Image paidBackground;

	[SerializeField]
	private GameObject paidLockObject;

	[Header("Colors")]
	[SerializeField]
	private Color freeUnlockedColor;

	[SerializeField]
	private Color freeLockedColor;

	[SerializeField]
	private Color paidBasicPlayerUnlockedColor;

	[SerializeField]
	private Color paidElitePlayerUnlockedColor;

	[SerializeField]
	private Color paidLockedColor;

	private PurchasableSeasonTier currentSeasonTier;

	private float normalSingleRewardRadius;

	private float normalMultipleRewardsRadius;

	private float largeSingleRewardRadius;

	private float largeMultipleRewardsRadius;

	private SizeOption previousSize;

	private List<RewardVisual> rewardVisuals = new List<RewardVisual>();

	[HideInInspector]
	public WatchUIFlow ThisFlow;

	public Button3D.OnButton3DClick ButtonAction => buyTierButton.OnClick;

	public int TierNumber => (currentSeasonTier == null) ? (-1) : currentSeasonTier.TierNumber;

	private void Awake()
	{
		normalSingleRewardRadius = 0.025f;
		normalMultipleRewardsRadius = normalSingleRewardRadius / 1.5f;
		largeSingleRewardRadius = 0.0375f;
		largeMultipleRewardsRadius = largeSingleRewardRadius / 1.5f;
	}

	private void OnDestroy()
	{
		if (ThisFlow != null)
		{
			ThisFlow.WatchUI.ResizeCompleteEvent -= ThisFlow_ResizeEvent;
			ThisFlow.WatchUI.FullyVisibleChanged -= WatchUI_FullyVisibleChanged;
		}
	}

	private void OnEnable()
	{
		if (rewardVisuals.Count > 0 && ThisFlow.WatchUI.Size != previousSize)
		{
			ThisFlow_ResizeEvent(ThisFlow.WatchUI.Size);
		}
	}

	private void OnDisable()
	{
		if (rewardVisuals.Count > 0)
		{
			previousSize = ThisFlow.WatchUI.Size;
		}
	}

	private void ThisFlow_ResizeEvent(SizeOption size)
	{
		if (ThisFlow.enabled)
		{
			for (int i = 0; i < rewardVisuals.Count; i++)
			{
				UpdateRewardSize(i, size);
			}
		}
	}

	private void UpdateRewardSize(int rewardNumber, SizeOption size)
	{
		Vector3 localScale = ((ThisFlow.WatchUI.Size != SizeOption.NORMAL) ? rewardVisuals[rewardNumber].largeScale : rewardVisuals[rewardNumber].normalScale);
		rewardVisuals[rewardNumber].transform.localScale = localScale;
	}

	public void UpdateBuyButton(bool interactable, string text)
	{
		buyTierButton.Interactable = interactable;
		buyTierButton.Label.text = text;
	}

	public void PlayUnlockAnimation(float duration)
	{
		animator.SetTrigger(TIER_UNLOCKING_ANIMATION_ID);
	}

	private void UpdateColorsAndLock(bool elitePlayer, bool isUnlocked, bool canBuy)
	{
		freeBackground.color = ((!isUnlocked) ? freeLockedColor : freeUnlockedColor);
		freeLockObject.SetActive(!isUnlocked);
		if (isUnlocked)
		{
			paidBackground.color = ((!elitePlayer) ? paidBasicPlayerUnlockedColor : paidElitePlayerUnlockedColor);
			paidLockObject.SetActive(!elitePlayer);
		}
		else
		{
			paidBackground.color = paidLockedColor;
			paidLockObject.SetActive(value: true);
		}
		buyTierButton.Label.text = "Buy Tier";
		buyTierButton.gameObject.SetActive(elitePlayer && canBuy);
		UpdateBuyButton(interactable: true, "Buy Tier");
	}

	public void SetTier(PurchasableSeasonTier tier, bool elitePlayer, bool isUnlocked, bool canBuy)
	{
		UpdateColorsAndLock(elitePlayer, isUnlocked, canBuy);
		if (tier == currentSeasonTier)
		{
			return;
		}
		foreach (RewardVisual rewardVisual in rewardVisuals)
		{
			UnityEngine.Object.Destroy(rewardVisual.transform.gameObject);
		}
		currentSeasonTier = tier;
		rewardVisuals.Clear();
		if (currentSeasonTier != null)
		{
			tierNumberText.text = currentSeasonTier.TierNumber.ToString();
			SetRewards(currentSeasonTier.FreeRewards, freeRewardRoots, freeRewardBottomRow);
			SetRewards(currentSeasonTier.PaidRewards, paidRewardRoots, paidRewardBottomRow);
		}
	}

	private void SetRewards(List<PurchasableSeasonTierReward> rewards, Transform[] rewardRoots, GameObject bottomRow)
	{
		if (rewards == null)
		{
			UnityEngine.Debug.LogErrorFormat("Null list of rewards in tier {1}", currentSeasonTier.TierNumber);
			return;
		}
		if (rewards.Count > 4)
		{
			UnityEngine.Debug.LogWarningFormat("More than 4 rewards per track in tier {1}", currentSeasonTier.TierNumber);
		}
		for (int i = 0; i < rewardRoots.Length; i++)
		{
			rewardRoots[i].gameObject.SetActive(rewards.Count > i);
		}
		bottomRow.SetActive(rewards.Count >= 3);
		if (ThisFlow.WatchUI.FullyVisible)
		{
			SpawnVisuals(rewards, rewardRoots);
		}
		else
		{
			ThisFlow.WatchUI.FullyVisibleChanged += WatchUI_FullyVisibleChanged;
		}
	}

	private void WatchUI_FullyVisibleChanged(bool fullyVisible)
	{
		if (fullyVisible)
		{
			ThisFlow.WatchUI.FullyVisibleChanged -= WatchUI_FullyVisibleChanged;
			SpawnVisuals(currentSeasonTier.FreeRewards, freeRewardRoots);
			SpawnVisuals(currentSeasonTier.PaidRewards, paidRewardRoots);
		}
	}

	private void SpawnVisuals(List<PurchasableSeasonTierReward> rewards, Transform[] rewardRoots)
	{
		for (int i = 0; i < rewards.Count && i <= 4; i++)
		{
			GameObject gameObject = null;
			StorefrontGiftDrop giftDrop = rewards[i].GiftDrop;
			if (giftDrop == null && rewards[i].SeasonXpBoost == 0f)
			{
				UnityEngine.Debug.LogError("Cannot spawn reward if no gift drop and no XP boost!");
				continue;
			}
			if (giftDrop != null)
			{
				switch (giftDrop.Content)
				{
				case GiftManager.GiftBoxContents.Avatar:
				{
					OutfitSelection selection = OutfitSelection.Parse(giftDrop.AvatarItemDesc);
					gameObject = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitImposter(selection);
					break;
				}
				case GiftManager.GiftBoxContents.Consumable:
					gameObject = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.SpawnConsumableImposter(giftDrop.ConsumableItemDesc);
					break;
				case GiftManager.GiftBoxContents.Equipment:
					gameObject = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentImposter(giftDrop.EquipmentPrefabName, giftDrop.EquipmentModificationGuid);
					break;
				case GiftManager.GiftBoxContents.Query:
				{
					GiftBoxMerchVisual giftBoxMerchVisual = UnityEngine.Object.Instantiate(giftBoxMerchVisualPrefab);
					giftBoxMerchVisual.SetGiftDrop(giftDrop);
					gameObject = giftBoxMerchVisual.gameObject;
					break;
				}
				default:
					UnityEngine.Debug.LogErrorFormat("Error: case {0} not set up in TierRewardSpawner", giftDrop.Content.ToString());
					return;
				}
			}
			else
			{
				gameObject = UnityEngine.Object.Instantiate(xpBoostVisualPrefab);
			}
			if (gameObject == null)
			{
				UnityEngine.Debug.LogErrorFormat("Error spawning {0}", giftDrop.FriendlyName, base.gameObject);
				break;
			}
			gameObject.SetLayerRecursively(Layers.IgnoreRaycast);
			gameObject.transform.SetParent(rewardRoots[i]);
			Vector3 one = Vector3.one;
			Vector3 one2 = Vector3.one;
			if (ThisFlow.WatchUI.Size == SizeOption.NORMAL)
			{
				one = gameObject.transform.CalculateCorrectScale((rewards.Count <= 1) ? normalSingleRewardRadius : normalMultipleRewardsRadius);
				one2 = one * 1.5f;
			}
			else
			{
				one2 = gameObject.transform.CalculateCorrectScale((rewards.Count <= 1) ? largeSingleRewardRadius : largeMultipleRewardsRadius);
				one = one2 / 1.5f;
			}
			rewardVisuals.Add(new RewardVisual
			{
				transform = gameObject.transform,
				normalScale = one,
				largeScale = one2
			});
			UpdateRewardSize(rewardVisuals.Count - 1, ThisFlow.WatchUI.Size);
			gameObject.transform.localPosition = Vector3.zero;
			gameObject.transform.localRotation = Quaternion.identity;
		}
	}
}
