public class WatchStoreItemButton : UnityEngine.MonoBehaviour
{
	[SerializeField]
	[Autofill(AutofillType.Children, false)]
	private Button3D buyButton;

	[SerializeField]
	[Autofill(AutofillType.Self, false)]
	private Tooltip tooltip;

	[SerializeField]
	private Text itemName;

	[SerializeField]
	private Text buyButtonText;

	[SerializeField]
	private Text levelText;

	[SerializeField]
	private GameObject lockedIcon;

	[SerializeField]
	private float prefabSize = 0.025f;

	[SerializeField]
	private Transform prefabRoot;

	[SerializeField]
	private GiftBoxMerchVisual giftBoxMerchVisualPrefab;

	[Header("Colors")]
	[SerializeField]
	private UnityEngine.UI.Image outline;

	[SerializeField]
	private Color oneStarColor;

	[SerializeField]
	private Color twoStarColor;

	[SerializeField]
	private Color threeStarColor;

	[SerializeField]
	private Color fourStarColor;

	[SerializeField]
	private Color fiveStarColor;

	[SerializeField]
	private Color defaultColor;

	private int localPlayerLevel;

	private StorefrontGiftDrop _currentItem;

	private OutfitSelection outfitSelection;

	public PurchasableGiftDrop PurchasableGiftDrop { get; set; }

	public int Cost { get; private set; }

	public StorefrontGiftDrop CurrentItem
	{
		get
		{
			return _currentItem;
		}
		private set
		{
			if (_currentItem != value)
			{
				outfitSelection = null;
				_currentItem = value;
			}
		}
	}

	public Button3D.OnButton3DClick ButtonAction => buyButton.OnClick;

	private void OnEnable()
	{
		localPlayerLevel = Profiles.LocalProfile.Level;
		if (CurrentItem != null)
		{
			UpdateButtonInteractability();
		}
	}

	private void OnAvatarItemOwnershipChanged(OutfitSelection selection)
	{
		if (CurrentItem != null && OutfitSelection.Parse(CurrentItem.AvatarItemDesc) == selection)
		{
			UpdateButtonInteractability();
		}
	}

	public void SetItem(PurchasableGiftDrop purchasableGiftDrop, StackedUIBase stackedUIBase)
	{
		if (PurchasableGiftDrop == purchasableGiftDrop)
		{
			return;
		}
		foreach (Transform item in prefabRoot)
		{
			UnityEngine.Object.Destroy(item.gameObject);
		}
		PurchasableGiftDrop = purchasableGiftDrop;
		CurrentItem = purchasableGiftDrop.GiftDrops[0];
		Cost = purchasableGiftDrop.GetCost(CurrencyType.RecCenterTokens);
		if (CurrentItem == null)
		{
			return;
		}
		Delayed3DUIObjectSpawner orAddComponent = prefabRoot.gameObject.GetOrAddComponent<Delayed3DUIObjectSpawner>();
		orAddComponent.Initialize(stackedUIBase, delegate(Transform parent)
		{
			GameObject gameObject = null;
			switch (CurrentItem.Content)
			{
			case GiftManager.GiftBoxContents.Avatar:
				outfitSelection = OutfitSelection.Parse(CurrentItem.AvatarItemDesc);
				gameObject = NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.SpawnOutfitImposter(outfitSelection);
				break;
			case GiftManager.GiftBoxContents.Equipment:
				gameObject = NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.SpawnEquipmentImposter(CurrentItem.EquipmentPrefabName, CurrentItem.EquipmentModificationGuid);
				break;
			case GiftManager.GiftBoxContents.Consumable:
				gameObject = NetworkedSingletonMonoBehaviour<ConsumableManager>.Instance.SpawnConsumableImposter(CurrentItem.ConsumableItemDesc);
				break;
			case GiftManager.GiftBoxContents.Query:
			{
				GiftBoxMerchVisual giftBoxMerchVisual = UnityEngine.Object.Instantiate(giftBoxMerchVisualPrefab);
				giftBoxMerchVisual.SetGiftDrop(CurrentItem);
				gameObject = giftBoxMerchVisual.gameObject;
				break;
			}
			default:
				UnityEngine.Debug.LogErrorFormat("Error: case {0} not set up in WatchStoreItemButton", CurrentItem.Content.ToString());
				return;
			}
			if (gameObject == null)
			{
				UnityEngine.Debug.LogErrorFormat("Error spawning {0}", CurrentItem.FriendlyName, base.gameObject);
			}
			else
			{
				gameObject.transform.SetParent(parent, worldPositionStays: true);
				gameObject.transform.AssignCorrectScale(prefabSize);
				gameObject.transform.localPosition = Vector3.zero;
				gameObject.transform.localRotation = Quaternion.identity;
				gameObject.SetLayerRecursively(Layers.IgnoreRaycast);
			}
		});
		itemName.text = CurrentItem.FriendlyName;
		switch (CurrentItem.Rarity)
		{
		case GiftManager.GiftRarity.Common:
			outline.color = oneStarColor;
			break;
		case GiftManager.GiftRarity.Uncommon:
			outline.color = twoStarColor;
			break;
		case GiftManager.GiftRarity.Rare:
			outline.color = threeStarColor;
			break;
		case GiftManager.GiftRarity.Epic:
			outline.color = fourStarColor;
			break;
		case GiftManager.GiftRarity.Legendary:
			outline.color = fiveStarColor;
			break;
		default:
			outline.color = defaultColor;
			break;
		}
		UpdateButtonInteractability();
	}

	private void UpdateButtonInteractability()
	{
		if (base.gameObject.activeInHierarchy)
		{
			bool flag = CurrentItem.Level > localPlayerLevel;
			buyButton.gameObject.SetActive(!flag);
			lockedIcon.SetActive(flag);
			if (tooltip != null)
			{
				tooltip.Message = ((!flag) ? CurrentItem.Tooltip : $"Unlocks when you reach level {CurrentItem.Level}");
				tooltip.enabled = !string.IsNullOrEmpty(tooltip.Message);
			}
			if ((CurrentItem.Content == GiftManager.GiftBoxContents.Avatar && NetworkedSingletonMonoBehaviour<OutfitManager>.Instance.IsOutfitUnlockedOnCurrentPlatform(outfitSelection)) || (CurrentItem.Content == GiftManager.GiftBoxContents.Equipment && NetworkedSingletonMonoBehaviour<EquipmentManager>.Instance.IsEquipmentUnlockedOnCurrentPlatform(CurrentItem.EquipmentModificationGuid)))
			{
				buyButton.Interactable = false;
				buyButtonText.text = "Already Owned";
			}
			else if (flag)
			{
				levelText.text = CurrentItem.Level.ToString();
			}
			else
			{
				buyButton.Interactable = true;
				buyButtonText.text = $"{Cost:n0}";
			}
		}
	}
}
