namespace Gaia
{
	public class GaiaCompatiblePackage
	{
		public string m_packageName;

		public string m_packageDescription;

		public string m_packageImageName;

		public string m_packageURL;

		public bool m_isCompatible;

		public bool m_isInstalled;

		public bool m_installedFoldedOut;

		public bool m_compatibleFoldedOut;

		public List<MethodInfo> m_methods = new List<MethodInfo>();

		public Dictionary<string, bool> m_methodGroupFoldouts = new Dictionary<string, bool>();
	}
	public class GaiaCompatiblePublisher
	{
		public string m_publisherName;

		public bool m_installedFoldedOut;

		public bool m_compatibleFoldedOut;

		private Dictionary<string, GaiaCompatiblePackage> m_packages = new Dictionary<string, GaiaCompatiblePackage>();

		public GaiaCompatiblePackage GetPackage(string packageName)
		{
			if (m_packages.TryGetValue(packageName, out var value))
			{
				return value;
			}
			return null;
		}

		public List<GaiaCompatiblePackage> GetPackages()
		{
			List<GaiaCompatiblePackage> list = new List<GaiaCompatiblePackage>(m_packages.Values);
			list.Sort((GaiaCompatiblePackage a, GaiaCompatiblePackage b) => a.m_packageName.CompareTo(b.m_packageName));
			return list;
		}

		public int InstalledPackages()
		{
			int num = 0;
			foreach (KeyValuePair<string, GaiaCompatiblePackage> package in m_packages)
			{
				if (package.Value.m_isInstalled)
				{
					num++;
				}
			}
			return num;
		}

		public int CompatiblePackages()
		{
			int num = 0;
			foreach (KeyValuePair<string, GaiaCompatiblePackage> package in m_packages)
			{
				if (package.Value.m_isCompatible)
				{
					num++;
				}
			}
			return num;
		}

		public void AddPackage(GaiaCompatiblePackage package)
		{
			m_packages.Add(package.m_packageName, package);
		}
	}
	public class GaiaExtensionManager
	{
		private Dictionary<string, GaiaCompatiblePublisher> m_extensions = new Dictionary<string, GaiaCompatiblePublisher>();

		public void ScanForExtensions()
		{
			m_extensions.Clear();
			string empty = string.Empty;
			string empty2 = string.Empty;
			string packageImageName = string.Empty;
			string packageDescription = string.Empty;
			string packageURL = string.Empty;
			List<System.Type> typesInNamespace = GetTypesInNamespace("Gaia.GX.");
			for (int i = 0; i < typesInNamespace.Count; i++)
			{
				string[] array = typesInNamespace[i].FullName.Split('.');
				empty = Regex.Replace(array[2], "(\\B[A-Z])", " $1");
				empty2 = Regex.Replace(array[3], "(\\B[A-Z])", " $1");
				MethodInfo[] methods = typesInNamespace[i].GetMethods(BindingFlags.Static | BindingFlags.Public);
				List<MethodInfo> list = new List<MethodInfo>();
				foreach (MethodInfo methodInfo in methods)
				{
					if (methodInfo.Name.StartsWith("GX_"))
					{
						list.Add(methodInfo);
					}
					else if (methodInfo.Name == "GetPublisherName")
					{
						empty = (string)methodInfo.Invoke(null, null);
					}
					else if (methodInfo.Name == "GetPackageName")
					{
						empty2 = (string)methodInfo.Invoke(null, null);
					}
				}
				GaiaCompatiblePublisher value = null;
				if (!m_extensions.TryGetValue(empty, out value))
				{
					value = new GaiaCompatiblePublisher();
					value.m_publisherName = empty;
					value.m_compatibleFoldedOut = false;
					value.m_installedFoldedOut = false;
					m_extensions.Add(empty, value);
				}
				GaiaCompatiblePackage gaiaCompatiblePackage = value.GetPackage(empty2);
				if (gaiaCompatiblePackage == null)
				{
					gaiaCompatiblePackage = new GaiaCompatiblePackage();
					gaiaCompatiblePackage.m_compatibleFoldedOut = false;
					gaiaCompatiblePackage.m_installedFoldedOut = false;
					gaiaCompatiblePackage.m_packageName = empty2;
					value.AddPackage(gaiaCompatiblePackage);
				}
				if (list.Count > 0)
				{
					gaiaCompatiblePackage.m_isInstalled = true;
				}
				else
				{
					gaiaCompatiblePackage.m_isInstalled = false;
				}
				gaiaCompatiblePackage.m_methods = new List<MethodInfo>(list);
			}
			typesInNamespace = GetTypesInNamespace("Gaia.GXC.");
			for (int k = 0; k < typesInNamespace.Count; k++)
			{
				string[] array = typesInNamespace[k].FullName.Split('.');
				empty = Regex.Replace(array[2], "(\\B[A-Z])", " $1");
				empty2 = Regex.Replace(array[3], "(\\B[A-Z])", " $1");
				MethodInfo[] methods = typesInNamespace[k].GetMethods(BindingFlags.Static | BindingFlags.Public);
				foreach (MethodInfo methodInfo in methods)
				{
					if (methodInfo.Name == "GetPublisherName")
					{
						empty = (string)methodInfo.Invoke(null, null);
					}
					else if (methodInfo.Name == "GetPackageName")
					{
						empty2 = (string)methodInfo.Invoke(null, null);
					}
					else if (methodInfo.Name == "GetPackageImage")
					{
						packageImageName = (string)methodInfo.Invoke(null, null);
					}
					else if (methodInfo.Name == "GetPackageDescription")
					{
						packageDescription = (string)methodInfo.Invoke(null, null);
					}
					else if (methodInfo.Name == "GetPackageURL")
					{
						packageURL = (string)methodInfo.Invoke(null, null);
					}
				}
				GaiaCompatiblePublisher value2 = null;
				if (!m_extensions.TryGetValue(empty, out value2))
				{
					value2 = new GaiaCompatiblePublisher();
					value2.m_publisherName = empty;
					value2.m_compatibleFoldedOut = false;
					value2.m_installedFoldedOut = false;
					m_extensions.Add(empty, value2);
				}
				GaiaCompatiblePackage gaiaCompatiblePackage2 = value2.GetPackage(empty2);
				if (gaiaCompatiblePackage2 == null)
				{
					gaiaCompatiblePackage2 = new GaiaCompatiblePackage();
					gaiaCompatiblePackage2.m_compatibleFoldedOut = false;
					gaiaCompatiblePackage2.m_installedFoldedOut = false;
					gaiaCompatiblePackage2.m_packageName = empty2;
					value2.AddPackage(gaiaCompatiblePackage2);
				}
				gaiaCompatiblePackage2.m_isCompatible = true;
				gaiaCompatiblePackage2.m_packageDescription = packageDescription;
				gaiaCompatiblePackage2.m_packageImageName = packageImageName;
				gaiaCompatiblePackage2.m_packageURL = packageURL;
			}
		}

		public int GetInstalledExtensionCount()
		{
			int num = 0;
			foreach (GaiaCompatiblePublisher value in m_extensions.Values)
			{
				num += value.InstalledPackages();
			}
			return num;
		}

		public List<GaiaCompatiblePublisher> GetPublishers()
		{
			List<GaiaCompatiblePublisher> list = new List<GaiaCompatiblePublisher>(m_extensions.Values);
			list.Sort((GaiaCompatiblePublisher a, GaiaCompatiblePublisher b) => a.m_publisherName.CompareTo(b.m_publisherName));
			return list;
		}

		public List<System.Type> GetTypesInNamespace(string nameSpace)
		{
			List<System.Type> list = new List<System.Type>();
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			for (int i = 0; i < assemblies.Length; i++)
			{
				if (!assemblies[i].FullName.StartsWith("Assembly"))
				{
					continue;
				}
				System.Type[] types = assemblies[i].GetTypes();
				for (int j = 0; j < types.Length; j++)
				{
					if (!string.IsNullOrEmpty(types[j].Namespace) && types[j].Namespace.StartsWith(nameSpace))
					{
						list.Add(types[j]);
					}
				}
			}
			return list;
		}
	}
	public class Template
	{
		public string FilePath;

		public TemplateFrame Frame;

		private Dictionary<string, TemplateValue> Variables;

		public Template(string filePath, bool debug)
		{
			FilePath = filePath;
			if (Frame == null && !findPreviouslyBuiltFrame())
			{
				Frame = new TemplateFrame(filePath, debug);
			}
			Variables = new Dictionary<string, TemplateValue>();
		}

		private bool findPreviouslyBuiltFrame()
		{
			foreach (TemplateFrame item in TemplateFrames.List)
			{
				if (item.FilePath == FilePath)
				{
					Frame = item;
					return true;
				}
			}
			return false;
		}

		public void Set(string name, string value)
		{
			if (value == null)
			{
				value = string.Empty;
			}
			if (Variables.ContainsKey(name))
			{
				Variables[name].Value = value;
			}
			else
			{
				Variables.Add(name, new TemplateValue(value, Frame.Variables[name]));
			}
		}

		private int[] CopyIndicies(TemplateFrameVariable tfv)
		{
			int[] array = new int[tfv.Indicies.Count];
			tfv.Indicies.CopyTo(array);
			return array;
		}

		public override string ToString()
		{
			StringBuilder stringBuilder = new StringBuilder(Frame.Text);
			foreach (TemplateValue value in Variables.Values)
			{
				value.Indicies = CopyIndicies(value.FrameVar);
			}
			foreach (TemplateValue value2 in Variables.Values)
			{
				for (int i = 0; i < value2.Indicies.Length; i++)
				{
					stringBuilder.Insert(value2.Indicies[i], value2.Value);
					UpdateIndicies(value2.FrameVar.Positions[i], value2.Value.Length);
				}
			}
			return stringBuilder.ToString();
		}

		private void UpdateIndicies(int position, int length)
		{
			foreach (TemplateValue value in Variables.Values)
			{
				for (int i = 0; i < value.FrameVar.Positions.Count; i++)
				{
					if (value.FrameVar.Positions[i] > position)
					{
						value.Indicies[i] = value.Indicies[i] + length;
					}
				}
			}
		}
	}
	public class TemplateValue
	{
		public string Value;

		public int[] Indicies;

		public readonly TemplateFrameVariable FrameVar;

		public TemplateValue(string value, TemplateFrameVariable fv)
		{
			Value = value;
			FrameVar = fv;
		}
	}
	public static class TemplateFrames
	{
		public static List<TemplateFrame> List = new List<TemplateFrame>();
	}
	public class TemplateFrameVariable
	{
		public List<int> Indicies;

		public List<int> Positions;

		public TemplateFrameVariable(List<int> indicies, List<int> positions)
		{
			Indicies = indicies;
			Positions = positions;
		}
	}
	public class TemplateFrame
	{
		public Dictionary<string, TemplateFrameVariable> Variables = new Dictionary<string, TemplateFrameVariable>();

		public string FilePath;

		public string Text;

		private const char BeginChar = '{';

		private const char EndChar = '}';

		private int VariableCount;

		public TemplateFrame(string filePath, bool debug)
		{
			FilePath = filePath;
			Text = Build(filePath);
			if (!debug)
			{
				TemplateFrames.List.Add(this);
			}
		}

		public string Build(string filePath)
		{
			char[] array = Utils.ReadAllText(filePath).ToCharArray();
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i] != '{' || array[i + 1] != '{')
				{
					continue;
				}
				int num = i;
				i += 2;
				string varName = getVarName(array, ref i);
				if (varName != null)
				{
					if (!Variables.ContainsKey(varName))
					{
						Variables.Add(varName, new TemplateFrameVariable(new List<int>(), new List<int>()));
					}
					Variables[varName].Indicies.Add(num);
					Variables[varName].Positions.Add(VariableCount++);
				}
				array = shiftCharArryLeft(array, num, i);
				i = num - 1;
			}
			return new string(array);
		}

		private char[] shiftCharArryLeft(char[] arry, int startIndex, int endIndex)
		{
			char[] array = new char[arry.Length - (endIndex - startIndex + 1)];
			for (int i = 0; i < startIndex; i++)
			{
				array[i] = arry[i];
			}
			int num = 0;
			for (int j = endIndex + 1; j < arry.Length; j++)
			{
				array[startIndex + num] = arry[j];
				num++;
			}
			return array;
		}

		private string getVarName(char[] text, ref int pos)
		{
			pos = skipSpaces(text, pos);
			int num = pos;
			while (text[pos] != ' ')
			{
				pos++;
			}
			int num2 = pos;
			char[] array = new char[num2 - num];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = text[num + i];
			}
			pos = skipSpaces(text, pos);
			if (text[pos] != '}' && text[++pos] != '}')
			{
				return null;
			}
			pos++;
			return new string(array);
		}

		private static int skipSpaces(char[] text, int pos)
		{
			while (text[pos] == ' ')
			{
				pos++;
			}
			return pos;
		}
	}
