	public class fsPrimitiveConverter : fsConverter
	{
		public override bool CanProcess(System.Type type)
		{
			return type.Resolve().IsPrimitive || type == typeof(string) || type == typeof(decimal);
		}

		public override bool RequestCycleSupport(System.Type storageType)
		{
			return false;
		}

		public override bool RequestInheritanceSupport(System.Type storageType)
		{
			return false;
		}

		private static bool UseBool(System.Type type)
		{
			return type == typeof(bool);
		}

		private static bool UseInt64(System.Type type)
		{
			return type == typeof(sbyte) || type == typeof(byte) || type == typeof(short) || type == typeof(ushort) || type == typeof(int) || type == typeof(uint) || type == typeof(long);
		}

		private static bool UseUInt64(System.Type type)
		{
			return type == typeof(ulong);
		}

		private static bool UseDouble(System.Type type)
		{
			return type == typeof(float) || type == typeof(double) || type == typeof(decimal);
		}

		private static bool UseString(System.Type type)
		{
			return type == typeof(string) || type == typeof(char);
		}

		public override fsResult TrySerialize(object instance, out fsData serialized, System.Type storageType)
		{
			System.Type type = instance.GetType();
			if (fsConfig.Serialize64BitIntegerAsString && (type == typeof(long) || type == typeof(ulong)))
			{
				serialized = new fsData((string)Convert.ChangeType(instance, typeof(string)));
				return fsResult.Success;
			}
			if (UseBool(type))
			{
				serialized = new fsData((bool)instance);
				return fsResult.Success;
			}
			if (UseInt64(type))
			{
				serialized = new fsData((long)Convert.ChangeType(instance, typeof(long)));
				return fsResult.Success;
			}
			if (UseUInt64(type))
			{
				serialized = new fsData((ulong)Convert.ChangeType(instance, typeof(ulong)));
				return fsResult.Success;
			}
			if (UseDouble(type))
			{
				serialized = new fsData((double)Convert.ChangeType(instance, typeof(double)));
				return fsResult.Success;
			}
			if (UseString(type))
			{
				serialized = new fsData((string)Convert.ChangeType(instance, typeof(string)));
				return fsResult.Success;
			}
			serialized = null;
			return fsResult.Fail("Unhandled primitive type " + instance.GetType());
		}

		public override fsResult TryDeserialize(fsData storage, ref object instance, System.Type storageType)
		{
			fsResult success = fsResult.Success;
			if (UseBool(storageType))
			{
				fsResult fsResult = (success += CheckType(storage, fsDataType.Boolean));
				if (fsResult.Succeeded)
				{
					instance = storage.AsBool;
				}
				return success;
			}
			if (UseDouble(storageType) || UseInt64(storageType) || UseUInt64(storageType))
			{
				if (storage.IsDouble)
				{
					instance = Convert.ChangeType(storage.AsDouble, storageType);
				}
				else if (storage.IsInt64)
				{
					instance = Convert.ChangeType(storage.AsInt64, storageType);
				}
				else if (storage.IsUInt64)
				{
					instance = Convert.ChangeType(storage.AsUInt64, storageType);
				}
				else
				{
					if (!fsConfig.Serialize64BitIntegerAsString || !storage.IsString || (!(storageType == typeof(long)) && !(storageType == typeof(ulong))))
					{
						return fsResult.Fail(string.Concat(GetType().Name, " expected number but got ", storage.Type, " in ", storage));
					}
					instance = Convert.ChangeType(storage.AsString, storageType);
				}
				return fsResult.Success;
			}
			if (UseString(storageType))
			{
				fsResult fsResult2 = (success += CheckType(storage, fsDataType.String));
				if (fsResult2.Succeeded)
				{
					instance = storage.AsString;
				}
				return success;
			}
			return fsResult.Fail(GetType().Name + ": Bad data; expected bool, number, string, but got " + storage);
		}
	}
	public class fsReflectedConverter : fsConverter
	{
		public override bool CanProcess(System.Type type)
		{
			if (type.Resolve().IsArray || typeof(ICollection).IsAssignableFrom(type))
			{
				return false;
			}
			return true;
		}

		public override fsResult TrySerialize(object instance, out fsData serialized, System.Type storageType)
		{
			serialized = fsData.CreateDictionary();
			fsResult success = fsResult.Success;
			fsMetaType fsMetaType = fsMetaType.Get(instance.GetType());
			fsMetaType.EmitAotData();
			for (int i = 0; i < fsMetaType.Properties.Length; i++)
			{
				fsMetaProperty fsMetaProperty2 = fsMetaType.Properties[i];
				if (fsMetaProperty2.CanRead)
				{
					fsData data;
					fsResult result = Serializer.TrySerialize(fsMetaProperty2.StorageType, fsMetaProperty2.Read(instance), out data);
					success.AddMessages(result);
					if (!result.Failed)
					{
						serialized.AsDictionary[fsMetaProperty2.JsonName] = data;
					}
				}
			}
			return success;
		}

		public override fsResult TryDeserialize(fsData data, ref object instance, System.Type storageType)
		{
			fsResult success = fsResult.Success;
			fsResult fsResult = (success += CheckType(data, fsDataType.Object));
			if (fsResult.Failed)
			{
				return success;
			}
			fsMetaType fsMetaType = fsMetaType.Get(storageType);
			fsMetaType.EmitAotData();
			for (int i = 0; i < fsMetaType.Properties.Length; i++)
			{
				fsMetaProperty fsMetaProperty2 = fsMetaType.Properties[i];
				if (fsMetaProperty2.CanWrite && data.AsDictionary.TryGetValue(fsMetaProperty2.JsonName, out var value))
				{
					object result = null;
					if (fsMetaProperty2.CanRead)
					{
