{
	public class fsJsonParser
	{
		private int _start;

		private string _input;

		private readonly StringBuilder _cachedStringBuilder = new StringBuilder(256);

		private fsJsonParser(string input)
		{
			_input = input;
			_start = 0;
		}

		private fsResult MakeFailure(string message)
		{
			int num = Math.Max(0, _start - 20);
			int length = Math.Min(50, _input.Length - num);
			string warning = "Error while parsing: " + message + "; context = <" + _input.Substring(num, length) + ">";
			return fsResult.Fail(warning);
		}

		private bool TryMoveNext()
		{
			if (_start < _input.Length)
			{
				_start++;
				return true;
			}
			return false;
		}

		private bool HasValue()
		{
			return HasValue(0);
		}

		private bool HasValue(int offset)
		{
			return _start + offset >= 0 && _start + offset < _input.Length;
		}

		private char Character()
		{
			return Character(0);
		}

		private char Character(int offset)
		{
			return _input[_start + offset];
		}

		private void SkipSpace()
		{
			while (HasValue())
			{
				char c = Character();
				if (char.IsWhiteSpace(c))
				{
					TryMoveNext();
					continue;
				}
				if (!HasValue(1) || Character(0) != '/')
				{
					break;
				}
				if (Character(1) == '/')
				{
					while (HasValue() && !Environment.NewLine.Contains(string.Empty + Character()))
					{
						TryMoveNext();
					}
				}
				else
				{
					if (Character(1) != '*')
					{
						continue;
					}
					TryMoveNext();
					TryMoveNext();
					while (HasValue(1))
					{
						if (Character(0) == '*' && Character(1) == '/')
						{
							TryMoveNext();
							TryMoveNext();
							TryMoveNext();
							break;
						}
						TryMoveNext();
					}
				}
			}
		}

		private bool IsHex(char c)
		{
			return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
		}

		private uint ParseSingleChar(char c1, uint multipliyer)
		{
			uint result = 0u;
			if (c1 >= '0' && c1 <= '9')
			{
				result = (uint)(c1 - 48) * multipliyer;
			}
			else if (c1 >= 'A' && c1 <= 'F')
			{
				result = (uint)(c1 - 65 + 10) * multipliyer;
			}
			else if (c1 >= 'a' && c1 <= 'f')
			{
				result = (uint)(c1 - 97 + 10) * multipliyer;
			}
			return result;
		}

		private uint ParseUnicode(char c1, char c2, char c3, char c4)
		{
			uint num = ParseSingleChar(c1, 4096u);
			uint num2 = ParseSingleChar(c2, 256u);
			uint num3 = ParseSingleChar(c3, 16u);
			uint num4 = ParseSingleChar(c4, 1u);
			return num + num2 + num3 + num4;
		}

		private fsResult TryUnescapeChar(out char escaped)
		{
			TryMoveNext();
			if (!HasValue())
			{
				escaped = ' ';
				return MakeFailure("Unexpected end of input after \\");
			}
			switch (Character())
			{
			case '\\':
				TryMoveNext();
				escaped = '\\';
				return fsResult.Success;
			case '/':
				TryMoveNext();
				escaped = '/';
				return fsResult.Success;
			case '"':
				TryMoveNext();
				escaped = '"';
				return fsResult.Success;
			case 'a':
				TryMoveNext();
				escaped = '\a';
				return fsResult.Success;
			case 'b':
				TryMoveNext();
				escaped = '\b';
				return fsResult.Success;
			case 'f':
				TryMoveNext();
				escaped = '\f';
				return fsResult.Success;
			case 'n':
				TryMoveNext();
				escaped = '\n';
				return fsResult.Success;
			case 'r':
				TryMoveNext();
				escaped = '\r';
				return fsResult.Success;
			case 't':
				TryMoveNext();
				escaped = '\t';
				return fsResult.Success;
			case '0':
				TryMoveNext();
				escaped = '\0';
				return fsResult.Success;
			case 'u':
				TryMoveNext();
				if (IsHex(Character(0)) && IsHex(Character(1)) && IsHex(Character(2)) && IsHex(Character(3)))
				{
					uint num = ParseUnicode(Character(0), Character(1), Character(2), Character(3));
					TryMoveNext();
					TryMoveNext();
					TryMoveNext();
					TryMoveNext();
					escaped = (char)num;
					return fsResult.Success;
				}
				escaped = '\0';
				return MakeFailure($"invalid escape sequence '\\u{Character(0)}{Character(1)}{Character(2)}{Character(3)}'\n");
			default:
				escaped = '\0';
				return MakeFailure($"Invalid escape sequence \\{Character()}");
			}
		}

		private fsResult TryParseExact(string content)
		{
			for (int i = 0; i < content.Length; i++)
			{
				if (Character() != content[i])
				{
					return MakeFailure("Expected " + content[i]);
				}
				if (!TryMoveNext())
				{
					return MakeFailure("Unexpected end of content when parsing " + content);
				}
			}
			return fsResult.Success;
		}

		private fsResult TryParseTrue(out fsData data)
		{
			fsResult result = TryParseExact("true");
			if (result.Succeeded)
			{
				data = new fsData(boolean: true);
				return fsResult.Success;
			}
			data = null;
			return result;
		}

		private fsResult TryParseFalse(out fsData data)
		{
			fsResult result = TryParseExact("false");
			if (result.Succeeded)
			{
				data = new fsData(boolean: false);
				return fsResult.Success;
			}
			data = null;
			return result;
		}

		private fsResult TryParseNull(out fsData data)
		{
			fsResult result = TryParseExact("null");
			if (result.Succeeded)
			{
				data = new fsData();
				return fsResult.Success;
			}
			data = null;
			return result;
		}

		private bool IsSeparator(char c)
		{
			return char.IsWhiteSpace(c) || c == ',' || c == '}' || c == ']';
		}

		private fsResult TryParseNumber(out fsData data)
		{
			int start = _start;
			while (TryMoveNext() && HasValue() && !IsSeparator(Character()))
			{
			}
			string text = _input.Substring(start, _start - start);
			if (!text.Contains("."))
			{
				switch (text)
				{
				case "Infinity":
				case "-Infinity":
				case "NaN":
					break;
				default:
				{
					if (!ulong.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var result))
					{
						data = null;
						return MakeFailure("Bad UInt64 format with " + text);
					}
					data = new fsData(result);
					return fsResult.Success;
				}
				}
			}
			if (!double.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var result2))
			{
				data = null;
				return MakeFailure("Bad double format with " + text);
			}
			data = new fsData(result2);
			return fsResult.Success;
		}

		private fsResult TryParseString(out string str)
		{
			_cachedStringBuilder.Length = 0;
			if (Character() != '"' || !TryMoveNext())
			{
				str = string.Empty;
				return MakeFailure("Expected initial \" when parsing a string");
			}
			while (HasValue() && Character() != '"')
			{
				char c = Character();
				if (c == '\\')
				{
					char escaped;
					fsResult result = TryUnescapeChar(out escaped);
					if (result.Failed)
					{
						str = string.Empty;
						return result;
					}
					_cachedStringBuilder.Append(escaped);
				}
				else
				{
					_cachedStringBuilder.Append(c);
					if (!TryMoveNext())
					{
						str = string.Empty;
						return MakeFailure("Unexpected end of input when reading a string");
					}
				}
			}
			if (!HasValue() || Character() != '"' || !TryMoveNext())
			{
				str = string.Empty;
				return MakeFailure("No closing \" when parsing a string");
			}
			str = _cachedStringBuilder.ToString();
			return fsResult.Success;
		}

		private fsResult TryParseArray(out fsData arr)
		{
			if (Character() != '[')
			{
				arr = null;
				return MakeFailure("Expected initial [ when parsing an array");
			}
			if (!TryMoveNext())
			{
				arr = null;
				return MakeFailure("Unexpected end of input when parsing an array");
			}
			SkipSpace();
			List<fsData> list = new List<fsData>();
			while (HasValue() && Character() != ']')
			{
				fsData data;
				fsResult result = RunParse(out data);
				if (result.Failed)
				{
					arr = null;
					return result;
				}
				list.Add(data);
				SkipSpace();
				if (HasValue() && Character() == ',')
				{
					if (!TryMoveNext())
					{
						break;
					}
					SkipSpace();
				}
			}
			if (!HasValue() || Character() != ']' || !TryMoveNext())
			{
				arr = null;
				return MakeFailure("No closing ] for array");
			}
			arr = new fsData(list);
			return fsResult.Success;
		}

		private fsResult TryParseObject(out fsData obj)
		{
			if (Character() != '{')
			{
				obj = null;
				return MakeFailure("Expected initial { when parsing an object");
			}
			if (!TryMoveNext())
			{
				obj = null;
				return MakeFailure("Unexpected end of input when parsing an object");
			}
			SkipSpace();
			Dictionary<string, fsData> dictionary = new Dictionary<string, fsData>((!fsConfig.IsCaseSensitive) ? StringComparer.CurrentCultureIgnoreCase : StringComparer.CurrentCulture);
			while (HasValue() && Character() != '}')
			{
				SkipSpace();
				fsResult result = TryParseString(out var str);
				if (result.Failed)
				{
					obj = null;
					return result;
				}
				SkipSpace();
				if (!HasValue() || Character() != ':' || !TryMoveNext())
				{
					obj = null;
					return MakeFailure("Expected : after key \"" + str + "\"");
				}
				SkipSpace();
				result = RunParse(out var data);
				if (result.Failed)
				{
					obj = null;
					return result;
				}
				dictionary.Add(str, data);
				SkipSpace();
				if (HasValue() && Character() == ',')
				{
					if (!TryMoveNext())
					{
						break;
					}
					SkipSpace();
				}
			}
			if (!HasValue() || Character() != '}' || !TryMoveNext())
			{
				obj = null;
				return MakeFailure("No closing } for object");
			}
			obj = new fsData(dictionary);
			return fsResult.Success;
		}

		private fsResult RunParse(out fsData data)
		{
			SkipSpace();
			if (!HasValue())
			{
				data = null;
				return MakeFailure("Unexpected end of input");
			}
			switch (Character())
			{
			case '+':
			case '-':
			case '.':
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
			case 'I':
			case 'N':
				return TryParseNumber(out data);
			case '"':
			{
				string str;
				fsResult result = TryParseString(out str);
				if (result.Failed)
				{
					data = null;
					return result;
				}
				data = new fsData(str);
				return fsResult.Success;
			}
			case '[':
				return TryParseArray(out data);
			case '{':
				return TryParseObject(out data);
			case 't':
				return TryParseTrue(out data);
			case 'f':
				return TryParseFalse(out data);
			case 'n':
				return TryParseNull(out data);
			default:
				data = null;
				return MakeFailure("unable to parse; invalid token \"" + Character() + "\"");
			}
		}

		public static fsResult Parse(string input, out fsData data)
		{
			if (string.IsNullOrEmpty(input))
			{
				data = null;
				return fsResult.Fail("No input");
			}
			fsJsonParser fsJsonParser2 = new fsJsonParser(input);
			return fsJsonParser2.RunParse(out data);
		}

		public static fsData Parse(string input)
		{
			Parse(input, out var data).AssertSuccess();
			return data;
		}
	}
	public static class fsJsonPrinter
	{
		private static void InsertSpacing(TextWriter stream, int count)
		{
			for (int i = 0; i < count; i++)
			{
				stream.Write("    ");
			}
		}

		private static string EscapeString(string str)
		{
			bool flag = false;
			foreach (char c in str)
			{
				int num = Convert.ToInt32(c);
				if (num < 0 || num > 127)
				{
					flag = true;
					break;
				}
				switch (c)
				{
				case '\0':
				case '\a':
				case '\b':
				case '\t':
				case '\n':
				case '\f':
				case '\r':
				case '"':
				case '\\':
					flag = true;
					break;
				}
				if (flag)
				{
					break;
				}
			}
			if (!flag)
			{
				return str;
			}
			StringBuilder stringBuilder = new StringBuilder();
			foreach (char c2 in str)
			{
				int num2 = Convert.ToInt32(c2);
				if (num2 < 0 || num2 > 127)
				{
					stringBuilder.Append($"\\u{num2:x4} ".Trim());
					continue;
				}
				switch (c2)
				{
				case '"':
					stringBuilder.Append("\\\"");
					break;
				case '\\':
					stringBuilder.Append("\\\\");
					break;
				case '\a':
					stringBuilder.Append("\\a");
					break;
				case '\b':
					stringBuilder.Append("\\b");
					break;
				case '\f':
					stringBuilder.Append("\\f");
					break;
				case '\n':
					stringBuilder.Append("\\n");
					break;
				case '\r':
					stringBuilder.Append("\\r");
					break;
				case '\t':
					stringBuilder.Append("\\t");
					break;
				case '\0':
					stringBuilder.Append("\\0");
					break;
				default:
					stringBuilder.Append(c2);
					break;
				}
			}
			return stringBuilder.ToString();
		}

		private static void BuildCompressedString(fsData data, TextWriter stream)
		{
			switch (data.Type)
			{
			case fsDataType.Null:
				stream.Write("null");
				break;
			case fsDataType.Boolean:
				if (data.AsBool)
				{
					stream.Write("true");
				}
				else
				{
					stream.Write("false");
				}
				break;
			case fsDataType.Double:
				stream.Write(ConvertDoubleToString(data.AsDouble));
				break;
			case fsDataType.Int64:
				stream.Write(data.AsInt64);
				break;
			case fsDataType.UInt64:
				stream.Write(data.AsUInt64);
				break;
			case fsDataType.String:
				stream.Write('"');
				stream.Write(EscapeString(data.AsString));
				stream.Write('"');
				break;
			case fsDataType.Object:
			{
				stream.Write('{');
				bool flag2 = false;
				foreach (KeyValuePair<string, fsData> item in data.AsDictionary)
				{
					if (flag2)
					{
						stream.Write(',');
					}
					flag2 = true;
					stream.Write('"');
					stream.Write(item.Key);
					stream.Write('"');
					stream.Write(":");
					BuildCompressedString(item.Value, stream);
				}
				stream.Write('}');
				break;
			}
			case fsDataType.Array:
			{
				stream.Write('[');
				bool flag = false;
				foreach (fsData @as in data.AsList)
				{
					if (flag)
					{
						stream.Write(',');
					}
					flag = true;
					BuildCompressedString(@as, stream);
				}
				stream.Write(']');
				break;
			}
			}
		}

		private static void BuildPrettyString(fsData data, TextWriter stream, int depth)
		{
			switch (data.Type)
			{
			case fsDataType.Null:
				stream.Write("null");
				break;
			case fsDataType.Boolean:
				if (data.AsBool)
				{
					stream.Write("true");
				}
				else
				{
					stream.Write("false");
				}
				break;
			case fsDataType.Double:
				stream.Write(ConvertDoubleToString(data.AsDouble));
				break;
			case fsDataType.Int64:
				stream.Write(data.AsInt64);
				break;
			case fsDataType.UInt64:
				stream.Write(data.AsUInt64);
				break;
			case fsDataType.String:
				stream.Write('"');
				stream.Write(EscapeString(data.AsString));
				stream.Write('"');
				break;
			case fsDataType.Object:
			{
				stream.Write('{');
				stream.WriteLine();
				bool flag2 = false;
				foreach (KeyValuePair<string, fsData> item in data.AsDictionary)
				{
					if (flag2)
					{
						stream.Write(',');
						stream.WriteLine();
					}
					flag2 = true;
					InsertSpacing(stream, depth + 1);
					stream.Write('"');
					stream.Write(item.Key);
					stream.Write('"');
					stream.Write(": ");
					BuildPrettyString(item.Value, stream, depth + 1);
				}
				stream.WriteLine();
				InsertSpacing(stream, depth);
				stream.Write('}');
				break;
			}
			case fsDataType.Array:
			{
				if (data.AsList.Count == 0)
				{
					stream.Write("[]");
					break;
				}
				bool flag = false;
				stream.Write('[');
				stream.WriteLine();
				foreach (fsData @as in data.AsList)
				{
					if (flag)
					{
						stream.Write(',');
						stream.WriteLine();
					}
					flag = true;
					InsertSpacing(stream, depth + 1);
					BuildPrettyString(@as, stream, depth + 1);
				}
				stream.WriteLine();
				InsertSpacing(stream, depth);
				stream.Write(']');
				break;
			}
			}
		}

		public static void PrettyJson(fsData data, TextWriter outputStream)
		{
			BuildPrettyString(data, outputStream, 0);
		}

		public static string PrettyJson(fsData data)
		{
			StringBuilder stringBuilder = new StringBuilder();
			using StringWriter stream = new StringWriter(stringBuilder);
			BuildPrettyString(data, stream, 0);
			return stringBuilder.ToString();
		}

		public static void CompressedJson(fsData data, StreamWriter outputStream)
		{
			BuildCompressedString(data, outputStream);
		}

		public static string CompressedJson(fsData data)
		{
			StringBuilder stringBuilder = new StringBuilder();
			using StringWriter stream = new StringWriter(stringBuilder);
			BuildCompressedString(data, stream);
			return stringBuilder.ToString();
		}

		private static string ConvertDoubleToString(double d)
		{
			if (double.IsInfinity(d) || double.IsNaN(d))
			{
				return d.ToString(CultureInfo.InvariantCulture);
			}
			string text = d.ToString(CultureInfo.InvariantCulture);
			if (!text.Contains("."))
			{
				text += ".0";
			}
			return text;
		}
	}
