	public struct fsResult
	{
		private static readonly string[] EmptyStringArray = Array.Empty<string>();

		private bool _success;

		private List<string> _messages;

		public static fsResult Success = new fsResult
		{
			_success = true
		};

		public bool Failed => !_success;

		public bool Succeeded => _success;

		public bool HasWarnings => _messages != null && _messages.Any();

		public Exception AsException
		{
			get
			{
				if (!Failed && !RawMessages.Any())
				{
					throw new Exception("Only a failed result can be converted to an exception");
				}
				return new Exception(FormattedMessages);
			}
		}

		public IEnumerable<string> RawMessages
		{
			get
			{
				if (_messages != null)
				{
					return _messages;
				}
				return EmptyStringArray;
			}
		}

		public string FormattedMessages => string.Join(",\n", RawMessages.ToArray());

		public void AddMessage(string message)
		{
			if (_messages == null)
			{
				_messages = new List<string>();
			}
			_messages.Add(message);
		}

		public void AddMessages(fsResult result)
		{
			if (result._messages != null)
			{
				if (_messages == null)
				{
					_messages = new List<string>();
				}
				_messages.AddRange(result._messages);
			}
		}

		public fsResult Merge(fsResult other)
		{
			_success = _success && other._success;
			if (other._messages != null)
			{
				if (_messages == null)
				{
					_messages = new List<string>(other._messages);
				}
				else
				{
					_messages.AddRange(other._messages);
				}
			}
			return this;
		}

		public static fsResult Warn(string warning)
		{
			return new fsResult
			{
				_success = true,
				_messages = new List<string> { warning }
			};
		}

		public static fsResult Fail(string warning)
		{
			return new fsResult
			{
				_success = false,
				_messages = new List<string> { warning }
			};
		}

		public static fsResult operator +(fsResult a, fsResult b)
		{
			return a.Merge(b);
		}

		public fsResult AssertSuccess()
		{
			if (Failed)
			{
				throw AsException;
			}
			return this;
		}

		public fsResult AssertSuccessWithoutWarnings()
		{
			if (Failed || RawMessages.Any())
			{
				throw AsException;
			}
			return this;
		}
	}
	public class fsSerializer
	{
		internal class fsLazyCycleDefinitionWriter
		{
			private Dictionary<int, fsData> _pendingDefinitions = new Dictionary<int, fsData>();

			private HashSet<int> _references = new HashSet<int>();

			public void WriteDefinition(int id, fsData data)
			{
				if (_references.Contains(id))
				{
					EnsureDictionary(data);
					data.AsDictionary["$id"] = new fsData(id.ToString());
				}
				else
				{
					_pendingDefinitions[id] = data;
				}
			}

			public void WriteReference(int id, Dictionary<string, fsData> dict)
			{
				if (_pendingDefinitions.ContainsKey(id))
				{
					fsData fsData2 = _pendingDefinitions[id];
					EnsureDictionary(fsData2);
					fsData2.AsDictionary["$id"] = new fsData(id.ToString());
					_pendingDefinitions.Remove(id);
				}
				else
				{
					_references.Add(id);
				}
				dict["$ref"] = new fsData(id.ToString());
			}

			public void Clear()
			{
				_pendingDefinitions.Clear();
			}
		}

		private static HashSet<string> _reservedKeywords;

