			if (sessionManager != null && !sessionManager.IsLocked())
			{
				sessionManager.m_session.m_terrainWidth = m_tilesX * m_terrainSize;
				sessionManager.m_session.m_terrainDepth = m_tilesZ * m_terrainSize;
				sessionManager.m_session.m_terrainHeight = m_terrainHeight;
				sessionManager.AddDefaults(this);
				sessionManager.SetSeaLevel(m_seaLevel);
				GaiaOperation gaiaOperation = new GaiaOperation();
				gaiaOperation.m_description = "Creating terrain";
				gaiaOperation.m_generatedByID = m_defaultsID;
				gaiaOperation.m_generatedByName = base.name;
				gaiaOperation.m_generatedByType = GetType().ToString();
				gaiaOperation.m_isActive = true;
				gaiaOperation.m_operationDateTime = DateTime.Now.ToString();
				gaiaOperation.m_operationType = GaiaOperation.OperationType.CreateTerrain;
				sessionManager.AddOperation(gaiaOperation);
			}
			Terrain[,] world = new Terrain[m_tilesX, m_tilesZ];
			for (int i = 0; i < m_tilesX; i++)
			{
				for (int j = 0; j < m_tilesZ; j++)
				{
					CreateTile(i, j, ref world, null);
				}
			}
			RemoveWorldSeams(ref world);
		}

		public void UpdateFromTerrain()
		{
			Terrain activeTerrain = Terrain.activeTerrain;
			if (activeTerrain == null)
			{
				UnityEngine.Debug.Log("Could not update from active terrain - no current active terrain");
				return;
			}
			m_baseMapDist = (int)activeTerrain.basemapDistance;
			m_castShadows = activeTerrain.castShadows;
			m_detailDensity = activeTerrain.detailObjectDensity;
			m_detailDistance = (int)activeTerrain.detailObjectDistance;
			m_pixelError = (int)activeTerrain.heightmapPixelError;
			m_billboardStart = (int)activeTerrain.treeBillboardDistance;
			m_fadeLength = (int)activeTerrain.treeCrossFadeLength;
			m_treeDistance = (int)activeTerrain.treeDistance;
			m_maxMeshTrees = activeTerrain.treeMaximumFullLODCount;
			if (activeTerrain.materialType == Terrain.MaterialType.Custom)
			{
				m_material = activeTerrain.materialTemplate;
			}
			TerrainCollider component = activeTerrain.GetComponent<TerrainCollider>();
			if (component != null)
			{
				m_physicsMaterial = component.material;
			}
			TerrainData terrainData = activeTerrain.terrainData;
			m_controlTextureResolution = terrainData.alphamapResolution;
			m_baseMapSize = terrainData.baseMapResolution;
			m_detailResolution = terrainData.detailResolution;
			m_heightmapResolution = terrainData.heightmapResolution;
			m_bending = terrainData.wavingGrassAmount;
			m_size = terrainData.wavingGrassSpeed;
			m_speed = terrainData.wavingGrassStrength;
			m_grassTint = terrainData.wavingGrassTint;
			m_terrainSize = (int)terrainData.size.x;
			m_terrainHeight = (int)terrainData.size.y;
		}

		public void CreateTerrain(GaiaResource resources)
		{
			resources.AssociateAssets();
			GaiaSessionManager sessionManager = GaiaSessionManager.GetSessionManager();
			if (sessionManager != null && !sessionManager.IsLocked())
			{
				sessionManager.m_session.m_terrainWidth = m_tilesX * m_terrainSize;
				sessionManager.m_session.m_terrainDepth = m_tilesZ * m_terrainSize;
				sessionManager.m_session.m_terrainHeight = m_terrainHeight;
				sessionManager.AddDefaults(this);
				sessionManager.SetSeaLevel(m_seaLevel);
				sessionManager.AddResource(resources);
				resources.ChangeSeaLevel(m_seaLevel);
				sessionManager.AddOperation(GetTerrainCreationOperation(resources));
			}
			Terrain[,] world = new Terrain[m_tilesX, m_tilesZ];
			for (int i = 0; i < m_tilesX; i++)
			{
				for (int j = 0; j < m_tilesZ; j++)
				{
					CreateTile(i, j, ref world, resources);
				}
			}
			RemoveWorldSeams(ref world);
		}

		public GaiaOperation GetTerrainCreationOperation(GaiaResource resources)
		{
			GaiaOperation gaiaOperation = new GaiaOperation();
			gaiaOperation.m_description = "Creating terrain";
			gaiaOperation.m_generatedByID = m_defaultsID;
			gaiaOperation.m_generatedByName = base.name;
			gaiaOperation.m_generatedByType = GetType().ToString();
			gaiaOperation.m_isActive = true;
			gaiaOperation.m_operationDateTime = DateTime.Now.ToString();
			gaiaOperation.m_operationType = GaiaOperation.OperationType.CreateTerrain;
			return gaiaOperation;
		}

		private void CreateTile(int tx, int tz, ref Terrain[,] world, GaiaResource resources)
		{
			if (tx < 0 || tx >= m_tilesX)
			{
				UnityEngine.Debug.LogError("X value out of bounds");
				return;
			}
			if (tz < 0 || tz >= m_tilesZ)
			{
				UnityEngine.Debug.LogError("Z value out of bounds");
				return;
			}
			GetAndFixDefaults();
			Vector2 vector = new Vector2((float)(-m_terrainSize * m_tilesX) * 0.5f, (float)(-m_terrainSize * m_tilesZ) * 0.5f);
			if (world.Length < m_tilesX)
			{
				world = new Terrain[m_tilesX, m_tilesZ];
			}
			TerrainData terrainData = new TerrainData();
			terrainData.name = $"Terrain_{tx}_{tz}-{DateTime.Now:yyyyMMdd-HHmmss}";
			terrainData.alphamapResolution = m_controlTextureResolution;
			terrainData.baseMapResolution = m_baseMapSize;
			terrainData.SetDetailResolution(m_detailResolution, m_detailResolutionPerPatch);
			terrainData.heightmapResolution = m_heightmapResolution;
			terrainData.wavingGrassAmount = m_bending;
			terrainData.wavingGrassSpeed = m_size;
			terrainData.wavingGrassStrength = m_speed;
			terrainData.wavingGrassTint = m_grassTint;
			terrainData.size = new Vector3(m_terrainSize, m_terrainHeight, m_terrainSize);
			Terrain component = Terrain.CreateTerrainGameObject(terrainData).GetComponent<Terrain>();
			component.name = terrainData.name;
			component.transform.position = new Vector3((float)(m_terrainSize * tx) + vector.x, 0f, (float)(m_terrainSize * tz) + vector.y);
			component.basemapDistance = m_baseMapDist;
			component.castShadows = m_castShadows;
			component.detailObjectDensity = m_detailDensity;
			component.detailObjectDistance = m_detailDistance;
			component.heightmapPixelError = m_pixelError;
			component.treeBillboardDistance = m_billboardStart;
			component.treeCrossFadeLength = m_fadeLength;
			component.treeDistance = m_treeDistance;
			component.treeMaximumFullLODCount = m_maxMeshTrees;
			GaiaConstants.EnvironmentRenderer environmentRenderer = GaiaConstants.EnvironmentRenderer.BuiltIn;
			GaiaSettings gaiaSettings = Utils.GetGaiaSettings();
			if (gaiaSettings != null)
			{
				environmentRenderer = gaiaSettings.m_currentRenderer;
			}
			if (environmentRenderer == GaiaConstants.EnvironmentRenderer.BuiltIn)
			{
				if (m_material != null)
				{
					component.materialType = Terrain.MaterialType.Custom;
					component.materialTemplate = m_material;
				}
			}
			else
			{
				component.materialType = Terrain.MaterialType.Custom;
				if (environmentRenderer == GaiaConstants.EnvironmentRenderer.LightWeight2018x)
				{
					Shader shader = Shader.Find("LightweightPipeline/Terrain/Standard Terrain");
					Material material = new Material(shader);
					material.name = "Lightweight-DefaultTerrain";
					component.materialTemplate = material;
				}
				else
				{
					Shader shader2 = Shader.Find("HDRenderPipeline/Terrain/Standard Terrain");
					Material material2 = new Material(shader2);
					material2.name = "HDRender-DefaultTerrain";
					component.materialTemplate = material2;
				}
			}
			if (m_physicsMaterial != null)
			{
				TerrainCollider component2 = component.GetComponent<TerrainCollider>();
				if (component2 != null)
				{
					component2.material = m_physicsMaterial;
				}
				else
				{
					UnityEngine.Debug.LogWarning("Unable to assign physics material to terrain!");
				}
			}
			if (resources != null)
			{
				resources.ApplyPrototypesToTerrain(component);
			}
			else
			{
				component.Flush();
			}
			world[tx, tz] = component;
			GameObject gameObject = GameObject.Find("Gaia Environment");
			if (gameObject == null)
			{
				gameObject = new GameObject("Gaia Environment");
			}
			component.transform.parent = gameObject.transform;
		}

		private void RemoveWorldSeams(ref Terrain[,] world)
		{
			for (int i = 0; i < m_tilesX; i++)
			{
				for (int j = 0; j < m_tilesZ; j++)
				{
					Terrain right = null;
					Terrain left = null;
					Terrain bottom = null;
					Terrain top = null;
					if (i > 0)
					{
						left = world[i - 1, j];
					}
					if (i < m_tilesX - 1)
					{
						right = world[i + 1, j];
					}
					if (j > 0)
					{
						bottom = world[i, j - 1];
					}
					if (j < m_tilesZ - 1)
					{
						top = world[i, j + 1];
					}
					world[i, j].SetNeighbors(left, top, right, bottom);
				}
			}
		}

		public string GetAndFixDefaults()
		{
			StringBuilder stringBuilder = new StringBuilder();
			if (!Mathf.IsPowerOfTwo(m_terrainSize))
			{
				stringBuilder.AppendFormat("Terrain size must be power of 2! {0} was changed to {1}.\n", m_terrainSize, Mathf.ClosestPowerOfTwo(m_terrainSize));
				m_terrainSize = Mathf.ClosestPowerOfTwo(m_terrainSize);
			}
			if (!Mathf.IsPowerOfTwo(m_heightmapResolution - 1))
			{
				stringBuilder.AppendFormat("Height map size must be power of 2 + 1 number! {0} was changed to {1}.\n", m_heightmapResolution, Mathf.ClosestPowerOfTwo(m_heightmapResolution) + 1);
				m_heightmapResolution = Mathf.ClosestPowerOfTwo(m_heightmapResolution) + 1;
			}
			if (!Mathf.IsPowerOfTwo(m_controlTextureResolution))
			{
				stringBuilder.AppendFormat("Control texture resolution must be power of 2! {0} was changed to {1}.\n", m_controlTextureResolution, Mathf.ClosestPowerOfTwo(m_controlTextureResolution));
				m_controlTextureResolution = Mathf.ClosestPowerOfTwo(m_controlTextureResolution);
			}
			if (m_controlTextureResolution > 2048)
			{
				stringBuilder.AppendFormat("Control texture resolution must be <= 2048! {0} was changed to {1}.\n", m_controlTextureResolution, 2048);
				m_controlTextureResolution = 2048;
			}
			if (!Mathf.IsPowerOfTwo(m_baseMapSize))
			{
				stringBuilder.AppendFormat("Basemap size must be power of 2! {0} was changed to {1}.\n", m_baseMapSize, Mathf.ClosestPowerOfTwo(m_baseMapSize));
				m_baseMapSize = Mathf.ClosestPowerOfTwo(m_baseMapSize);
			}
			if (m_baseMapSize > 2048)
			{
				stringBuilder.AppendFormat("Basemap size must be <= 2048! {0} was changed to {1}.\n", m_baseMapSize, 2048);
				m_baseMapSize = 2048;
			}
			if (!Mathf.IsPowerOfTwo(m_detailResolution))
			{
				stringBuilder.AppendFormat("Detail map size must be power of 2! {0} was changed to {1}.\n", m_detailResolution, Mathf.ClosestPowerOfTwo(m_detailResolution));
				m_detailResolution = Mathf.ClosestPowerOfTwo(m_detailResolution);
			}
			if (m_detailResolutionPerPatch < 8)
			{
				stringBuilder.AppendFormat("Detail resolution per patch must be >= 8! {0} was changed to {1}.\n", m_detailResolutionPerPatch, 8);
				m_detailResolutionPerPatch = 8;
			}
			return stringBuilder.ToString();
		}

		public string SerialiseJson()
		{
			fsSerializer fsSerializer = new fsSerializer();
			fsSerializer.TrySerialize(this, out var data);
			return fsJsonPrinter.CompressedJson(data);
		}

		public void DeSerialiseJson(string json)
		{
			fsData data = fsJsonParser.Parse(json);
			fsSerializer fsSerializer = new fsSerializer();
			GaiaDefaults instance = this;
			fsSerializer.TryDeserialize(data, ref instance);
		}
	}
	[Serializable]
	public class GaiaResource : ScriptableObject
	{
		[Tooltip("Unique identifier for these resources.")]
		[HideInInspector]
		public string m_resourcesID = Guid.NewGuid().ToString();

		[Tooltip("Resource name")]
		public string m_name = "Gaia Resource";

		[Tooltip("The absolute height of the sea or water table in meters. All spawn criteria heights are calculated relative to this. This can also be thought of as the water level. This value is sourced from the defaults file, and managed on a session by session basis.")]
		public float m_seaLevel = 100f;

		[Tooltip("The beach height in meters. Beaches are spawned at sea level and are extended for this height above sea level. This is used when creating default spawn rules in order to create a beach in the zone between water and land.")]
		public float m_beachHeight = 5f;

		[Tooltip("Terrain height.")]
		public float m_terrainHeight = 1000f;

		[Tooltip("Texture prototypes and fitness criteria.")]
		public ResourceProtoTexture[] m_texturePrototypes = new ResourceProtoTexture[0];

		[Tooltip("Detail prototypes, dna and fitness criteria.")]
		public ResourceProtoDetail[] m_detailPrototypes = new ResourceProtoDetail[0];

		[Tooltip("Tree prototypes, dna and fitness criteria.")]
		public ResourceProtoTree[] m_treePrototypes = new ResourceProtoTree[0];

		[Tooltip("Game object prototypes, dna and fitness criteria.")]
		public ResourceProtoGameObject[] m_gameObjectPrototypes = new ResourceProtoGameObject[0];

		public bool SetAssetAssociations()
		{
			int num = 0;
			bool result = false;
			for (num = 0; num < m_texturePrototypes.GetLength(0); num++)
			{
				ResourceProtoTexture resourceProtoTexture = m_texturePrototypes[num];
				if (resourceProtoTexture.SetAssetAssociations())
				{
					result = true;
				}
			}
			for (num = 0; num < m_detailPrototypes.GetLength(0); num++)
			{
				ResourceProtoDetail resourceProtoDetail = m_detailPrototypes[num];
				if (resourceProtoDetail.SetAssetAssociations())
				{
					result = true;
				}
			}
			for (num = 0; num < m_treePrototypes.GetLength(0); num++)
			{
				ResourceProtoTree resourceProtoTree = m_treePrototypes[num];
				if (resourceProtoTree.SetAssetAssociations())
				{
					result = true;
				}
			}
			for (num = 0; num < m_gameObjectPrototypes.GetLength(0); num++)
			{
				ResourceProtoGameObject resourceProtoGameObject = m_gameObjectPrototypes[num];
				if (resourceProtoGameObject.SetAssetAssociations())
				{
					result = true;
				}
			}
			return result;
		}

		public bool AssociateAssets()
		{
			int num = 0;
			bool result = false;
			for (num = 0; num < m_texturePrototypes.GetLength(0); num++)
			{
				ResourceProtoTexture resourceProtoTexture = m_texturePrototypes[num];
				if (resourceProtoTexture.AssociateAssets())
				{
					result = true;
				}
			}
			for (num = 0; num < m_detailPrototypes.GetLength(0); num++)
			{
				ResourceProtoDetail resourceProtoDetail = m_detailPrototypes[num];
				if (resourceProtoDetail.AssociateAssets())
				{
					result = true;
				}
			}
			for (num = 0; num < m_treePrototypes.GetLength(0); num++)
			{
				ResourceProtoTree resourceProtoTree = m_treePrototypes[num];
				if (resourceProtoTree.AssociateAssets())
				{
					result = true;
				}
			}
			for (num = 0; num < m_gameObjectPrototypes.GetLength(0); num++)
			{
				ResourceProtoGameObject resourceProtoGameObject = m_gameObjectPrototypes[num];
				if (resourceProtoGameObject.AssociateAssets())
				{
					result = true;
				}
			}
			return result;
		}

		public void DeletePrototypes()
		{
			m_texturePrototypes = new ResourceProtoTexture[0];
			m_detailPrototypes = new ResourceProtoDetail[0];
			m_treePrototypes = new ResourceProtoTree[0];
			m_gameObjectPrototypes = new ResourceProtoGameObject[0];
		}

		public bool PrototypesMissingFromTerrain()
		{
			Terrain activeTerrain = TerrainHelper.GetActiveTerrain();
			if (activeTerrain == null)
			{
				UnityEngine.Debug.LogWarning("Could not check assets in terrain as no terrain has been supplied.");
				return false;
			}
			int num = 0;
			for (num = 0; num < m_texturePrototypes.GetLength(0); num++)
			{
				if (PrototypeMissingFromTerrain(GaiaConstants.SpawnerResourceType.TerrainTexture, num))
				{
					return true;
				}
			}
			for (num = 0; num < m_detailPrototypes.GetLength(0); num++)
			{
				if (PrototypeMissingFromTerrain(GaiaConstants.SpawnerResourceType.TerrainDetail, num))
				{
					return true;
				}
			}
			for (num = 0; num < m_treePrototypes.GetLength(0); num++)
			{
				if (PrototypeMissingFromTerrain(GaiaConstants.SpawnerResourceType.TerrainTree, num))
				{
					return true;
				}
			}
			for (num = 0; num < m_gameObjectPrototypes.GetLength(0); num++)
			{
				if (PrototypeMissingFromTerrain(GaiaConstants.SpawnerResourceType.GameObject, num))
				{
					return true;
				}
			}
			return false;
		}

		public bool PrototypeMissingFromTerrain(GaiaConstants.SpawnerResourceType resourceType, int resourceIdx)
		{
			if (PrototypeIdxInTerrain(resourceType, resourceIdx) == -1)
			{
				return true;
			}
			return false;
		}

		public int PrototypeIdxInTerrain(GaiaConstants.SpawnerResourceType resourceType, int resourceIdx)
		{
			int result = -1;
			int num = 0;
			Terrain activeTerrain = TerrainHelper.GetActiveTerrain();
			if (activeTerrain == null)
			{
				return result;
			}
			if (ResourceIdxOutOfBounds(resourceType, resourceIdx))
			{
				return result;
			}
			if (!ResourceIsInUnity(resourceType, resourceIdx))
			{
				return result;
			}
			switch (resourceType)
			{
			case GaiaConstants.SpawnerResourceType.TerrainTexture:
			{
				ResourceProtoTexture resourceProtoTexture = m_texturePrototypes[resourceIdx];
				SplatPrototype[] splatPrototypes = activeTerrain.terrainData.splatPrototypes;
				foreach (SplatPrototype splatPrototype in splatPrototypes)
				{
					if (Utils.IsSameTexture(resourceProtoTexture.m_texture, splatPrototype.texture))
					{
						return num;
					}
					num++;
				}
				return result;
			}
			case GaiaConstants.SpawnerResourceType.TerrainDetail:
			{
				ResourceProtoDetail resourceProtoDetail = m_detailPrototypes[resourceIdx];
				DetailPrototype[] detailPrototypes = activeTerrain.terrainData.detailPrototypes;
				foreach (DetailPrototype detailPrototype in detailPrototypes)
				{
					if (resourceProtoDetail.m_renderMode == detailPrototype.renderMode)
					{
						if (Utils.IsSameTexture(resourceProtoDetail.m_detailTexture, detailPrototype.prototypeTexture))
						{
							return num;
						}
						if (Utils.IsSameGameObject(resourceProtoDetail.m_detailProtoype, detailPrototype.prototype))
						{
							return num;
						}
					}
					num++;
				}
				return result;
			}
			case GaiaConstants.SpawnerResourceType.TerrainTree:
			{
				ResourceProtoTree resourceProtoTree = m_treePrototypes[resourceIdx];
				TreePrototype[] treePrototypes = activeTerrain.terrainData.treePrototypes;
				foreach (TreePrototype treePrototype in treePrototypes)
				{
					if (Utils.IsSameGameObject(resourceProtoTree.m_desktopPrefab, treePrototype.prefab))
					{
						return num;
					}
					num++;
				}
				return result;
			}
			case GaiaConstants.SpawnerResourceType.GameObject:
				return resourceIdx;
			default:
				return result;
			}
		}

		public bool ResourceIdxOutOfBounds(GaiaConstants.SpawnerResourceType resourceType, int resourceIdx)
		{
			switch (resourceType)
			{
			case GaiaConstants.SpawnerResourceType.TerrainTexture:
				if (resourceIdx < 0 || resourceIdx >= m_texturePrototypes.GetLength(0))
				{
					return true;
				}
				return false;
			case GaiaConstants.SpawnerResourceType.TerrainDetail:
				if (resourceIdx < 0 || resourceIdx >= m_detailPrototypes.GetLength(0))
				{
					return true;
				}
				return false;
			case GaiaConstants.SpawnerResourceType.TerrainTree:
				if (resourceIdx < 0 || resourceIdx >= m_treePrototypes.GetLength(0))
				{
					return true;
				}
				return false;
			case GaiaConstants.SpawnerResourceType.GameObject:
				if (resourceIdx < 0 || resourceIdx >= m_gameObjectPrototypes.GetLength(0))
				{
					return true;
				}
				return false;
			default:
				return true;
			}
		}

		public bool ResourceIsInUnity(GaiaConstants.SpawnerResourceType resourceType, int resourceIdx)
		{
			if (ResourceIdxOutOfBounds(resourceType, resourceIdx))
			{
				return false;
			}
			switch (resourceType)
			{
			case GaiaConstants.SpawnerResourceType.TerrainTexture:
			{
				ResourceProtoTexture resourceProtoTexture = m_texturePrototypes[resourceIdx];
				if (resourceProtoTexture.m_texture == null)
				{
					return false;
				}
				return true;
			}
			case GaiaConstants.SpawnerResourceType.TerrainDetail:
			{
				ResourceProtoDetail resourceProtoDetail = m_detailPrototypes[resourceIdx];
				if (resourceProtoDetail.m_detailTexture == null && resourceProtoDetail.m_detailProtoype == null)
				{
					return false;
				}
				return true;
			}
			case GaiaConstants.SpawnerResourceType.TerrainTree:
			{
				ResourceProtoTree resourceProtoTree = m_treePrototypes[resourceIdx];
				if (resourceProtoTree.m_desktopPrefab == null)
				{
					return false;
				}
				return true;
			}
			case GaiaConstants.SpawnerResourceType.GameObject:
			{
				ResourceProtoGameObject resourceProtoGameObject = m_gameObjectPrototypes[resourceIdx];
				if (resourceProtoGameObject.m_instances[0] == null)
				{
					return false;
				}
				return true;
			}
			default:
				return false;
			}
		}

		public void UpdatePrototypesFromTerrain()
		{
			Terrain activeTerrain = TerrainHelper.GetActiveTerrain();
			if (activeTerrain == null)
			{
				UnityEngine.Debug.LogWarning("Can not update prototypes from the terrain as there is no terrain currently active in this scene.");
				return;
			}
			Dictionary<string, string> names = new Dictionary<string, string>();
			m_terrainHeight = activeTerrain.terrainData.size.y;
			List<ResourceProtoTexture> list = new List<ResourceProtoTexture>(m_texturePrototypes);
			while (list.Count > activeTerrain.terrainData.splatPrototypes.Length)
			{
				list.RemoveAt(list.Count - 1);
			}
			int i;
			for (i = 0; i < activeTerrain.terrainData.splatPrototypes.Length; i++)
			{
				SplatPrototype splatPrototype = activeTerrain.terrainData.splatPrototypes[i];
				ResourceProtoTexture resourceProtoTexture;
				if (i < list.Count)
				{
					resourceProtoTexture = list[i];
				}
				else
				{
					resourceProtoTexture = new ResourceProtoTexture();
					list.Add(resourceProtoTexture);
				}
				resourceProtoTexture.m_name = GetUniqueName(splatPrototype.texture.name, ref names);
				resourceProtoTexture.m_texture = splatPrototype.texture;
				resourceProtoTexture.m_normal = splatPrototype.normalMap;
				resourceProtoTexture.m_offsetX = splatPrototype.tileOffset.x;
				resourceProtoTexture.m_offsetY = splatPrototype.tileOffset.y;
				resourceProtoTexture.m_sizeX = splatPrototype.tileSize.x;
