		{
			for (int i = 0; i < m_spawnCriteria.Length; i++)
			{
				if (m_spawnCriteria[i].m_isActive && m_spawnCriteria[i].m_checkProximity && !tagList.Contains(m_spawnCriteria[i].m_proximityTag))
				{
					tagList.Add(m_spawnCriteria[i].m_proximityTag);
				}
			}
		}
