		public SpawnInfo GetSpawnInfo(Vector3 location)
		{
			SpawnInfo spawnInfo = new SpawnInfo();
			spawnInfo.m_textureStrengths = new float[Terrain.activeTerrain.terrainData.alphamapLayers];
			if (m_spawner.CheckLocation(location, ref spawnInfo))
			{
				spawnInfo.m_fitness = GetFitness(ref spawnInfo);
			}
			else
			{
				spawnInfo.m_fitness = 0f;
			}
			return spawnInfo;
		}

		public float GetFitness(ref SpawnInfo spawnInfo)
		{
			SpawnCritera[] array = m_selectedResourceType switch
			{
				GaiaConstants.SpawnerResourceType.TerrainDetail => spawnInfo.m_spawner.m_resources.m_detailPrototypes[m_selectedResourceIdx].m_spawnCriteria, 
				GaiaConstants.SpawnerResourceType.TerrainTexture => spawnInfo.m_spawner.m_resources.m_texturePrototypes[m_selectedResourceIdx].m_spawnCriteria, 
				GaiaConstants.SpawnerResourceType.TerrainTree => spawnInfo.m_spawner.m_resources.m_treePrototypes[m_selectedResourceIdx].m_spawnCriteria, 
				_ => spawnInfo.m_spawner.m_resources.m_gameObjectPrototypes[m_selectedResourceIdx].m_spawnCriteria, 
			};
			if (array == null || array.Length == 0)
			{
				return 0f;
			}
			float num = float.MinValue;
			float num2 = 0f;
			foreach (SpawnCritera spawnCritera in array)
			{
				if (spawnCritera.m_checkType == GaiaConstants.SpawnerLocationCheckType.BoundedAreaCheck && !spawnInfo.m_spawner.CheckLocationBounds(ref spawnInfo, GetMaxScaledRadius(ref spawnInfo)))
				{
					return 0f;
				}
				num2 = spawnCritera.GetFitness(ref spawnInfo);
				if (num2 > num)
				{
					num = num2;
					if (num >= 1f)
					{
						return num;
					}
				}
			}
			if (num == float.MinValue)
			{
				return 0f;
			}
			return num;
		}

		public float GetMinFitness(ref SpawnInfo spawnInfo)
		{
			SpawnCritera[] spawnCriteria;
			switch (m_selectedResourceType)
			{
			case GaiaConstants.SpawnerResourceType.TerrainDetail:
				if (m_selectedResourceIdx >= spawnInfo.m_spawner.m_resources.m_detailPrototypes.Length)
				{
					return 0f;
				}
				spawnCriteria = spawnInfo.m_spawner.m_resources.m_detailPrototypes[m_selectedResourceIdx].m_spawnCriteria;
				break;
			case GaiaConstants.SpawnerResourceType.TerrainTexture:
				if (m_selectedResourceIdx >= spawnInfo.m_spawner.m_resources.m_texturePrototypes.Length)
				{
					return 0f;
				}
				spawnCriteria = spawnInfo.m_spawner.m_resources.m_texturePrototypes[m_selectedResourceIdx].m_spawnCriteria;
				break;
			case GaiaConstants.SpawnerResourceType.TerrainTree:
				if (m_selectedResourceIdx >= spawnInfo.m_spawner.m_resources.m_treePrototypes.Length)
				{
					return 0f;
				}
				spawnCriteria = spawnInfo.m_spawner.m_resources.m_treePrototypes[m_selectedResourceIdx].m_spawnCriteria;
				break;
			default:
				if (m_selectedResourceIdx >= spawnInfo.m_spawner.m_resources.m_gameObjectPrototypes.Length)
				{
					return 0f;
				}
				spawnCriteria = spawnInfo.m_spawner.m_resources.m_gameObjectPrototypes[m_selectedResourceIdx].m_spawnCriteria;
				break;
			}
			if (spawnCriteria == null || spawnCriteria.Length == 0)
			{
				return 0f;
			}
			float num = float.MaxValue;
			float num2 = 0f;
			foreach (SpawnCritera spawnCritera in spawnCriteria)
			{
				if (spawnCritera.m_checkType == GaiaConstants.SpawnerLocationCheckType.BoundedAreaCheck && !spawnInfo.m_spawner.CheckLocationBounds(ref spawnInfo, GetMaxScaledRadius(ref spawnInfo)))
				{
					return 0f;
				}
				num2 = spawnCritera.GetFitness(ref spawnInfo);
				if (num2 < num)
				{
					num = num2;
					if (num <= 0f)
					{
						return num;
					}
				}
			}
			if (num == float.MaxValue)
			{
				return 0f;
			}
			return num;
		}

		public float GetMaxScaledRadius(ref SpawnInfo spawnInfo)
		{
			return m_selectedResourceType switch
			{
				GaiaConstants.SpawnerResourceType.TerrainTexture => 1f, 
				GaiaConstants.SpawnerResourceType.TerrainDetail => spawnInfo.m_spawner.m_resources.m_detailPrototypes[m_selectedResourceIdx].m_dna.m_boundsRadius * spawnInfo.m_spawner.m_resources.m_detailPrototypes[m_selectedResourceIdx].m_dna.m_maxScale, 
				GaiaConstants.SpawnerResourceType.TerrainTree => spawnInfo.m_spawner.m_resources.m_treePrototypes[m_selectedResourceIdx].m_dna.m_boundsRadius * spawnInfo.m_spawner.m_resources.m_treePrototypes[m_selectedResourceIdx].m_dna.m_maxScale, 
				_ => spawnInfo.m_spawner.m_resources.m_gameObjectPrototypes[m_selectedResourceIdx].m_dna.m_boundsRadius * spawnInfo.m_spawner.m_resources.m_gameObjectPrototypes[m_selectedResourceIdx].m_dna.m_maxScale, 
			};
		}

		private void OnDrawGizmos()
		{
			if (m_resources == null || m_spawner == null || m_terrainHeightMap == null)
			{
				return;
			}
			float y = base.transform.position.y;
			float num = base.transform.position.x - m_range;
			float num2 = base.transform.position.x + m_range;
			float num3 = base.transform.position.z - m_range;
			float num4 = base.transform.position.z + m_range;
			float radius = Mathf.Clamp(m_resolution * 0.25f, 0.5f, 5f);
			m_spawner.m_spawnRange = m_range;
			m_spawner.m_spawnerBounds = new Bounds(base.transform.position, new Vector3(m_range * 2f, m_range * 20f, m_range * 2f));
			SpawnInfo spawnInfo = new SpawnInfo();
			Vector3 locationWU = default(Vector3);
			float num5 = 0f;
			if ((DateTime.Now - m_lastCacheUpdateDate).TotalSeconds > 5.0)
			{
				m_lastCacheUpdateDate = DateTime.Now;
				m_spawner.DeleteSpawnCaches();
				m_spawner.CreateSpawnCaches(m_selectedResourceType, m_selectedResourceIdx);
				Terrain terrain = TerrainHelper.GetTerrain(base.transform.position);
				if (terrain != null)
				{
					base.transform.position = new Vector3(base.transform.position.x, terrain.SampleHeight(base.transform.position) + 5f, base.transform.position.z);
				}
			}
			spawnInfo.m_textureStrengths = new float[Terrain.activeTerrain.terrainData.alphamapLayers];
			for (float num6 = num; num6 < num2; num6 += m_resolution)
			{
				for (float num7 = num3; num7 < num4; num7 += m_resolution)
				{
					locationWU.Set(num6, y, num7);
					if (m_spawner.CheckLocation(locationWU, ref spawnInfo))
					{
						num5 = GetFitness(ref spawnInfo);
						if (!(num5 < m_minimumFitness))
						{
							Gizmos.color = Color.Lerp(m_unfitColour, m_fitColour, num5);
							Gizmos.DrawSphere(spawnInfo.m_hitLocationWU, radius);
						}
					}
				}
			}
			if (m_resources != null)
			{
				Bounds bounds = default(Bounds);
				if (TerrainHelper.GetTerrainBounds(base.transform.position, ref bounds))
				{
					bounds.center = new Vector3(bounds.center.x, m_resources.m_seaLevel, bounds.center.z);
					bounds.size = new Vector3(bounds.size.x, 0.05f, bounds.size.z);
					Gizmos.color = new Color(Color.blue.r, Color.blue.g, Color.blue.b, Color.blue.a / 4f);
					Gizmos.DrawCube(bounds.center, bounds.size);
				}
			}
		}
	}
	public class Scanner : UnityEngine.MonoBehaviour
	{
		[Tooltip("The name of the stamp as it will be stored in the project. Initally based on the file name.")]
		public string m_featureName = $"{DateTime.Now}";

		[Tooltip("The type of stamp, also controls which directory the stamp will be loaded into.")]
		public GaiaConstants.FeatureType m_featureType = GaiaConstants.FeatureType.Mountains;

		[Range(0f, 1f)]
		[Tooltip("Base level for this stamp, used by stamper to cut off all heights below the base. It is the highest point of the stamp around its edges.")]
		public float m_baseLevel;

		[HideInInspector]
		[Range(0.1f, 1f)]
		[Tooltip("Scan resolution in meters. Leave this at smaller values for higher quality scans.")]
		public float m_scanResolution = 0.1f;

		[Tooltip("The material that will be used to display the scan preview. This is just for visualisation and will not affect the scan.")]
		public Material m_previewMaterial;

		private HeightMap m_scanMap;

		private Bounds m_scanBounds;

		private int m_scanWidth = 1;

		private int m_scanDepth = 1;

		private int m_scanHeight = 500;

		private Vector3 m_groundOffset = Vector3.zero;

		private Vector3 m_groundSize = Vector3.zero;

		private void OnEnable()
		{
			MeshFilter meshFilter = GetComponent<MeshFilter>();
			if (meshFilter == null)
			{
				meshFilter = base.gameObject.AddComponent<MeshFilter>();
			}
			meshFilter.hideFlags = HideFlags.HideInInspector;
			MeshRenderer meshRenderer = GetComponent<MeshRenderer>();
			if (meshRenderer == null)
			{
				meshRenderer = base.gameObject.AddComponent<MeshRenderer>();
			}
			meshRenderer.hideFlags = HideFlags.HideInInspector;
		}

		private void Awake()
		{
			base.gameObject.SetActive(value: false);
		}

		public void Reset()
		{
			m_featureName = string.Empty;
			m_scanMap = null;
			m_scanBounds = new Bounds(base.transform.position, Vector3.one * 10f);
			m_scanWidth = (m_scanDepth = (m_scanHeight = 0));
			m_scanResolution = 0.1f;
			m_baseLevel = 0f;
			base.transform.localRotation = Quaternion.identity;
			base.transform.localScale = Vector3.one;
		}

		public void LoadRawFile(string path)
		{
			if (string.IsNullOrEmpty(path))
			{
				UnityEngine.Debug.LogError("Must supply a valid path. Raw load Aborted!");
			}
			Reset();
			m_featureName = Path.GetFileNameWithoutExtension(path);
			m_scanMap = new HeightMap();
			m_scanMap.LoadFromRawFile(path);
			if (!m_scanMap.HasData())
			{
				UnityEngine.Debug.LogError("Unable to load raw file. Raw load aborted.");
				return;
			}
			m_scanWidth = m_scanMap.Width();
			m_scanDepth = m_scanMap.Depth();
			m_scanHeight = m_scanWidth / 2;
			m_scanResolution = 0.1f;
			m_scanBounds = new Bounds(base.transform.position, new Vector3((float)m_scanWidth * m_scanResolution, (float)m_scanWidth * m_scanResolution * 0.4f, (float)m_scanDepth * m_scanResolution));
			m_baseLevel = m_scanMap.GetBaseLevel();
			MeshFilter meshFilter = GetComponent<MeshFilter>();
			if (meshFilter == null)
			{
				meshFilter = base.gameObject.AddComponent<MeshFilter>();
				meshFilter.hideFlags = HideFlags.HideInInspector;
			}
			MeshRenderer meshRenderer = GetComponent<MeshRenderer>();
			if (meshRenderer == null)
			{
				meshRenderer = base.gameObject.AddComponent<MeshRenderer>();
				meshRenderer.hideFlags = HideFlags.HideInInspector;
			}
			meshFilter.mesh = Utils.CreateMesh(m_scanMap.Heights(), m_scanBounds.size);
			if (m_previewMaterial != null)
			{
				m_previewMaterial.hideFlags = HideFlags.HideInInspector;
				meshRenderer.sharedMaterial = m_previewMaterial;
			}
		}

