		public string GetRandomMountainFieldPath()
		{
			if (m_genMountainStamps.Count == 0)
			{
				m_genMountainStamps = Utils.GetGaiaStampsList(GaiaConstants.FeatureType.Mountains);
			}
			if (m_genMountainStamps.Count == 0)
			{
				return string.Empty;
			}
			int num = 0;
			int num2 = 0;
			for (num = 0; num < m_genMountainStamps.Count; num++)
			{
				string text = m_genMountainStamps[num];
				if (text.Contains("Field"))
				{
					num2++;
				}
			}
			int num3 = 0;
			int num4 = UnityEngine.Random.Range(0, num2 - 1);
			for (num = 0; num < m_genMountainStamps.Count; num++)
			{
				string text = m_genMountainStamps[num];
				if (text.Contains("Field"))
				{
					if (num3 == num4)
					{
						return text;
					}
					num3++;
				}
			}
			return string.Empty;
		}

		public GameObject Apply(int operationIdx)
		{
			if (operationIdx < 0 || operationIdx >= m_session.m_operations.Count)
			{
				UnityEngine.Debug.LogWarning($"Can not Apply operation because the index {operationIdx} is out of bounds.");
				return null;
			}
			GaiaOperation gaiaOperation = m_session.m_operations[operationIdx];
			GameObject gameObject = FindOrCreateObject(gaiaOperation);
			if (gameObject == null)
			{
				return gameObject;
			}
			Stamper component = gameObject.GetComponent<Stamper>();
			if (component != null && gaiaOperation.m_operationType == GaiaOperation.OperationType.Stamp)
			{
				component.DeSerialiseJson(gaiaOperation.m_operationDataJson[0]);
				component.m_resources = Utils.GetAsset(ScriptableObjectWrapper.GetSessionedFileName(m_session.GetSessionFileName(), component.m_resourcesPath), typeof(GaiaResource)) as GaiaResource;
				if (component.m_resources == null)
				{
					ExportSessionResource(component.m_resourcesPath);
					component.m_resources = Utils.GetAsset(ScriptableObjectWrapper.GetSessionedFileName(m_session.GetSessionFileName(), component.m_resourcesPath), typeof(GaiaResource)) as GaiaResource;
				}
				component.m_seaLevel = m_session.m_seaLevel;
			}
			Spawner component2 = gameObject.GetComponent<Spawner>();
			if (component2 != null && gaiaOperation.m_operationType == GaiaOperation.OperationType.Spawn)
			{
				component2.DeSerialiseJson(gaiaOperation.m_operationDataJson[0]);
				component2.m_resources = Utils.GetAsset(ScriptableObjectWrapper.GetSessionedFileName(m_session.GetSessionFileName(), component2.m_resourcesPath), typeof(GaiaResource)) as GaiaResource;
				if (component2.m_resources == null)
				{
					ExportSessionResource(component2.m_resourcesPath);
					component2.m_resources = Utils.GetAsset(ScriptableObjectWrapper.GetSessionedFileName(m_session.GetSessionFileName(), component2.m_resourcesPath), typeof(GaiaResource)) as GaiaResource;
				}
				if (component2.m_resources == null)
				{
					UnityEngine.Debug.LogError("Unable to get resources file for " + component2.name);
				}
				else
				{
					component2.AssociateAssets();
					int[] missingResources = component2.GetMissingResources();
					if (missingResources.GetLength(0) > 0)
					{
						component2.AddResourcesToTerrain(missingResources);
					}
					component2.m_resources.ChangeSeaLevel(m_session.m_seaLevel);
				}
			}
			return gameObject;
		}

		public void PlaySession()
		{
			m_cancelPlayback = false;
			ExportSessionResources();
			StartCoroutine(PlaySessionCoRoutine());
		}

		public IEnumerator PlaySessionCoRoutine()
		{
			m_progress = 0uL;
			if (UnityEngine.Application.isPlaying)
			{
				for (int idx = 0; idx < m_session.m_operations.Count; idx++)
				{
					if (!m_cancelPlayback && m_session.m_operations[idx].m_isActive)
					{
						yield return StartCoroutine(PlayOperationCoRoutine(idx));
					}
				}
			}
			else
			{
				for (int i = 0; i < m_session.m_operations.Count; i++)
				{
					if (!m_cancelPlayback && m_session.m_operations[i].m_isActive)
					{
						m_updateOperationCoroutine = PlayOperationCoRoutine(i);
						yield return new WaitForSeconds(0.2f);
					}
				}
			}
			UnityEngine.Debug.Log("Finished playing session " + m_session.m_name);
			m_updateSessionCoroutine = null;
		}

		public void PlayOperation(int opIdx)
		{
			m_cancelPlayback = false;
			StartCoroutine(PlayOperationCoRoutine(opIdx));
		}

		public IEnumerator PlayOperationCoRoutine(int operationIdx)
		{
			if (operationIdx < 0 || operationIdx >= m_session.m_operations.Count)
			{
				UnityEngine.Debug.LogWarning($"Operation index {operationIdx} is out of bounds.");
				m_updateOperationCoroutine = null;
				yield break;
			}
			if (!m_session.m_operations[operationIdx].m_isActive)
			{
				UnityEngine.Debug.LogWarning($"Operation '{m_session.m_operations[operationIdx].m_description}' is not active. Ignoring.");
				m_updateOperationCoroutine = null;
				yield break;
			}
			bool lockState = m_session.m_isLocked;
			m_session.m_isLocked = true;
			GaiaOperation operation = m_session.m_operations[operationIdx];
			GameObject go = Apply(operationIdx);
			Stamper stamper = null;
			Spawner spawner = null;
			if (go != null)
			{
				stamper = go.GetComponent<Stamper>();
				spawner = go.GetComponent<Spawner>();
			}
			switch (operation.m_operationType)
			{
			case GaiaOperation.OperationType.CreateTerrain:
				if (TerrainHelper.GetActiveTerrainCount() == 0 && m_session.m_defaults != null && m_session.m_defaults.m_content.GetLength(0) <= 0)
				{
				}
				break;
			case GaiaOperation.OperationType.FlattenTerrain:
				if (stamper != null)
				{
					stamper.FlattenTerrain();
				}
				break;
			case GaiaOperation.OperationType.SmoothTerrain:
				if (stamper != null)
				{
					stamper.SmoothTerrain();
				}
				break;
			case GaiaOperation.OperationType.ClearDetails:
				if (stamper != null)
				{
					stamper.ClearDetails();
				}
				break;
			case GaiaOperation.OperationType.ClearTrees:
				if (stamper != null)
				{
					stamper.ClearTrees();
				}
				break;
			case GaiaOperation.OperationType.Stamp:
				if (!(stamper != null))
				{
					break;
				}
				m_currentStamper = stamper;
				m_currentSpawner = null;
				if (!UnityEngine.Application.isPlaying)
				{
					stamper.HidePreview();
					stamper.Stamp();
					while (stamper.IsStamping())
					{
						if ((DateTime.Now - m_lastUpdateDateTime).Milliseconds > 250)
						{
							m_lastUpdateDateTime = DateTime.Now;
							m_progress++;
						}
						yield return new WaitForSeconds(0.2f);
					}
				}
				else
				{
					yield return StartCoroutine(stamper.ApplyStamp());
				}
				break;
			case GaiaOperation.OperationType.StampUndo:
				if (stamper != null)
				{
					stamper.Undo();
				}
				break;
			case GaiaOperation.OperationType.StampRedo:
				if (stamper != null)
				{
					stamper.Redo();
				}
				break;
			case GaiaOperation.OperationType.Spawn:
				if (!(spawner != null))
				{
					break;
				}
				m_currentStamper = null;
				m_currentSpawner = spawner;
				if (UnityEngine.Application.isPlaying)
				{
					break;
				}
				spawner.RunSpawnerIteration();
				while (spawner.IsSpawning())
				{
					if ((DateTime.Now - m_lastUpdateDateTime).Milliseconds > 250)
					{
						m_lastUpdateDateTime = DateTime.Now;
						m_progress++;
					}
					yield return new WaitForSeconds(0.2f);
				}
				break;
			}
			m_session.m_isLocked = lockState;
			m_updateOperationCoroutine = null;
		}

		public void CancelPlayback()
		{
			m_cancelPlayback = true;
			if (m_currentStamper != null)
			{
				m_currentStamper.CancelStamp();
			}
			if (m_currentSpawner != null)
			{
				m_currentSpawner.CancelSpawn();
			}
		}

		public void ExportSessionResources()
		{
			string text = "Assets/GaiaSessions/";
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			text = Path.Combine(text, Utils.FixFileName(m_session.m_name));
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			if (m_session.m_defaults != null && m_session.m_defaults.m_content.GetLength(0) > 0)
			{
				string path = Path.Combine(text, ScriptableObjectWrapper.GetSessionedFileName(m_session.m_name, m_session.m_defaults.m_fileName));
				Utils.WriteAllBytes(path, m_session.m_defaults.m_content);
			}
			foreach (KeyValuePair<string, ScriptableObjectWrapper> resource in m_session.m_resources)
			{
				string path2 = Path.Combine(text, ScriptableObjectWrapper.GetSessionedFileName(m_session.m_name, resource.Value.m_fileName));
				Utils.WriteAllBytes(path2, resource.Value.m_content);
			}
		}

		public void ExportSessionDefaults()
		{
			string text = "Assets/GaiaSessions/";
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			text = Path.Combine(text, Utils.FixFileName(m_session.m_name));
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			if (m_session.m_defaults != null && m_session.m_defaults.m_content.GetLength(0) > 0)
			{
				string path = Path.Combine(text, ScriptableObjectWrapper.GetSessionedFileName(m_session.m_name, m_session.m_defaults.m_fileName));
				Utils.WriteAllBytes(path, m_session.m_defaults.m_content);
			}
		}

		public void ExportSessionResource(string resourcePath)
		{
			string text = "Assets/GaiaSessions/";
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			text = Path.Combine(text, Utils.FixFileName(m_session.m_name));
			if (!Directory.Exists(text))
			{
				Directory.CreateDirectory(text);
			}
			foreach (KeyValuePair<string, ScriptableObjectWrapper> resource in m_session.m_resources)
			{
				if (Path.GetFileName(resourcePath).ToLower() == Path.GetFileName(resource.Value.m_fileName).ToLower())
				{
					string path = Path.Combine(text, ScriptableObjectWrapper.GetSessionedFileName(m_session.m_name, resource.Value.m_fileName));
					Utils.WriteAllBytes(path, resource.Value.m_content);
				}
			}
		}

		private void OnDrawGizmosSelected()
		{
			if (m_session != null)
			{
				Bounds bounds = default(Bounds);
				if (TerrainHelper.GetTerrainBounds(base.transform.position, ref bounds))
				{
					Gizmos.color = Color.white;
					Gizmos.DrawWireCube(bounds.center, bounds.size);
					bounds.center = new Vector3(bounds.center.x, m_session.m_seaLevel, bounds.center.z);
					bounds.size = new Vector3(bounds.size.x, 0.05f, bounds.size.z);
					Gizmos.color = new Color(Color.blue.r, Color.blue.g, Color.blue.b, Color.blue.a / 4f);
					Gizmos.DrawCube(bounds.center, bounds.size);
				}
			}
		}

		private GameObject FindOrCreateObject(GaiaOperation operation)
		{
			if (operation.m_generatedByType == "Gaia.Stamper")
			{
				Stamper[] array = UnityEngine.Object.FindObjectsOfType<Stamper>();
				for (int i = 0; i < array.GetLength(0); i++)
				{
					if (array[i].m_stampID == operation.m_generatedByID && array[i].name == operation.m_generatedByName)
					{
						return array[i].gameObject;
					}
				}
				return ShowStamper(operation.m_generatedByName, operation.m_generatedByID);
			}
			if (operation.m_generatedByType == "Gaia.Spawner")
			{
				Spawner[] array2 = UnityEngine.Object.FindObjectsOfType<Spawner>();
				for (int j = 0; j < array2.GetLength(0); j++)
				{
					if (array2[j].m_spawnerID == operation.m_generatedByID && array2[j].name == operation.m_generatedByName)
					{
						return array2[j].gameObject;
					}
				}
				return CreateSpawner(operation.m_generatedByName, operation.m_generatedByID);
			}
			return null;
		}

		private GameObject ShowStamper(string name, string id)
		{
			GameObject gameObject = GameObject.Find("Gaia");
			if (gameObject == null)
			{
				gameObject = new GameObject("Gaia");
			}
			GameObject gameObject2 = GameObject.Find(name);
			if (gameObject2 == null)
			{
				gameObject2 = new GameObject(name);
				gameObject2.transform.parent = gameObject.transform;
				Stamper stamper = gameObject2.AddComponent<Stamper>();
				stamper.m_stampID = id;
				stamper.HidePreview();
				stamper.m_seaLevel = m_session.m_seaLevel;
			}
			return gameObject2;
		}

		private GameObject CreateSpawner(string name, string id)
		{
			GameObject gameObject = GameObject.Find("Gaia");
			if (gameObject == null)
			{
				gameObject = new GameObject("Gaia");
			}
			GameObject gameObject2 = new GameObject(name);
			gameObject2.transform.parent = gameObject.transform;
			Spawner spawner = gameObject2.AddComponent<Spawner>();
			spawner.m_spawnerID = id;
			return gameObject2;
		}
	}
	[Serializable]
	public class SpawnCritera
	{
		[Tooltip("Criteria name")]
		public string m_name;

		[Tooltip("CHECK TYPE - a single point on the terrain or area based. The size of the area checks is based on the Bounds Radius in the DNA. Area based checks are good for larger structures but substantially slower so use with care.")]
		public GaiaConstants.SpawnerLocationCheckType m_checkType;

		[Tooltip("When selected, the criteria will only be valid if the terrain was clear of any other objects at this location. A location is determined to be ‘virgin’ when raycast collision test hits clear terrain. To detect other objects at this location they must have colliders. You can use an invisible collider and this test to stop any resources that require virgin terrain from spawning at that location.")]
		public bool m_virginTerrain = true;

		[Tooltip("Whether or not this location will be checked for height.")]
		public bool m_checkHeight = true;

		[Tooltip("The minimum valid height relative to sea level. Only tested when Check Height is checked.")]
		public float m_minHeight;

		[Tooltip("The maximum valid height relative to sea level. Only tested when Check Height is checked.")]
		public float m_maxHeight = 1000f;

		[Tooltip("The fitness curve - evaluated between the minimum and the maximum height when Check Height is checked. 0 is low fitness and unlikely to spawn, 1 is high fitness and likely to spawn.")]
		public AnimationCurve m_heightFitness = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 0f));

		[Tooltip("Whether or not this location will be checked for slope.")]
		public bool m_checkSlope = true;

		[Tooltip("The minimum valid slope. Only tested when Check Slope is checked.")]
		public float m_minSlope;

		[Tooltip("The maximum valid slope. Only tested when Check Slope is checked.")]
		public float m_maxSlope = 90f;

		[Tooltip("The fitness curve - evaluated between the minimum and the maximum slope when Check Slope is checked. 0 is low fitness and unlikely to spawn, 1 is high fitness and likely to spawn.")]
		public AnimationCurve m_slopeFitness = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(1f, 0f));

		[Tooltip("Whether or not to check proximity to other tags near this location.")]
		public bool m_checkProximity;

		[Tooltip("The tag that will be checked in proximity to this location e.g. House")]
		public string m_proximityTag = string.Empty;

		[Tooltip("The minimum valid proximity. Only tested when Check Proximity is checked.")]
		public float m_minProximity;

		[Tooltip("The maximum valid proximity. Only tested when Check Proximity is checked.")]
		public float m_maxProximity = 100f;

		[Tooltip("The fitness curve - evaluated between the minimum and the maximum proximity when Check Proximity is checked. 0 is low fitness and unlikely to spawn, 1 is high fitness and likely to spawn.")]
		public AnimationCurve m_proximityFitness = new AnimationCurve(new Keyframe(0f, 1f), new Keyframe(0.3f, 0.2f), new Keyframe(1f, 0f));

		[Tooltip("Check textures at this location.")]
		public bool m_checkTexture;

		[Tooltip("Texture slots from your terrain (first valid slot is 0). Will select for presence that texture. Use exclamation mark in front of slot to select for absence of that texture. For example 3 selects for presence of texture 3, !3 checks for absence of texture 3. Fitness is based on the strength of the texture at that location in range 0..1. Only tested when Check Texture is checked.")]
		public string m_matchingTextures = "!3";

		[Tooltip("Whether or not this spawn criteria is active. It will be ignored if not active.")]
		public bool m_isActive = true;

		private bool m_isInitialised;

		public void Initialise(Spawner spawner)
		{
			string text = string.Empty;
			char c = 4.ToString()[0];
			if (Terrain.activeTerrain != null)
			{
				c = Terrain.activeTerrain.terrainData.alphamapLayers.ToString()[0];
			}
			for (int i = 0; i < m_matchingTextures.Length; i++)
			{
				if ((m_matchingTextures[i] >= '0' && m_matchingTextures[i] <= c) || m_matchingTextures[i] == '!')
				{
					text += m_matchingTextures[i];
				}
			}
			m_matchingTextures = text;
			m_isInitialised = true;
		}

		public float GetSlopeFitness(float slope)
		{
			float result = 1f;
			if (m_checkSlope)
			{
				if (slope < m_minSlope || slope > m_maxSlope)
				{
					return 0f;
				}
				result = m_maxSlope - m_minSlope;
				if (result > 0f)
				{
					result = (slope - m_minSlope) / result;
					result = m_slopeFitness.Evaluate(result);
				}
				else
				{
					result = 0f;
				}
			}
			return result;
		}

		public float GetHeightFitness(float height, float sealLevel)
		{
			float result = 1f;
			if (m_checkHeight)
			{
				height -= sealLevel;
				if (height < m_minHeight || height > m_maxHeight)
				{
					return 0f;
				}
				result = m_maxHeight - m_minHeight;
				if (result > 0f)
				{
					result = (height - m_minHeight) / result;
					result = m_heightFitness.Evaluate(result);
				}
				else
				{
					result = 0f;
				}
			}
			return result;
		}

		public float GetProximityFitness(float proximity)
		{
			float result = 1f;
			if (m_checkProximity)
			{
				if (proximity < m_minProximity || proximity > m_maxProximity)
				{
					return 0f;
				}
				result = m_maxProximity - m_minProximity;
				if (result > 0f)
				{
					result = (proximity - m_minProximity) / result;
					result = m_proximityFitness.Evaluate(result);
				}
				else
				{
					result = 0f;
				}
			}
			return result;
		}

		public float GetTextureFitness(float[] textures)
		{
			bool flag = false;
			float num = 1f;
			if (m_checkTexture)
			{
				num = float.MaxValue;
				for (int i = 0; i < m_matchingTextures.Length; i++)
				{
					if (m_matchingTextures[i] == '!')
					{
						flag = true;
					}
					else if (flag)
					{
						float num2 = 1f - textures[(int)char.GetNumericValue(m_matchingTextures[i])];
						flag = false;
						if (num == float.MaxValue || num2 < num)
						{
							num = num2;
						}
					}
					else
					{
						float num2 = textures[(int)char.GetNumericValue(m_matchingTextures[i])];
						if (num == float.MaxValue || num2 > num)
						{
							num = num2;
						}
					}
				}
			}
			return num;
		}

		public float GetFitness(ref SpawnInfo spawnInfo)
		{
			if (!m_isInitialised)
			{
				Initialise(spawnInfo.m_spawner);
			}
			if (!m_isActive)
			{
				return 0f;
			}
			if (m_virginTerrain && !spawnInfo.m_wasVirginTerrain)
			{
				return 0f;
			}
			float num = 1f;
			if (m_checkHeight)
			{
				num = Mathf.Min(num, GetHeightFitness(spawnInfo.m_terrainHeightWU, spawnInfo.m_spawner.m_resources.m_seaLevel));
			}
			if (m_checkSlope && num > 0f)
			{
				num = ((m_checkType != GaiaConstants.SpawnerLocationCheckType.PointCheck) ? Mathf.Min(num, GetSlopeFitness(spawnInfo.m_areaAvgSlopeWU)) : Mathf.Min(num, GetSlopeFitness(spawnInfo.m_terrainSlopeWU)));
			}
			if (m_checkTexture && num > 0f)
			{
				num = Mathf.Min(num, GetTextureFitness(spawnInfo.m_textureStrengths));
			}
			if (m_checkProximity && num > 0f)
			{
				Rect area = new Rect(spawnInfo.m_hitLocationWU.x - m_maxProximity, spawnInfo.m_hitLocationWU.z - m_maxProximity, m_maxProximity * 2f, m_maxProximity * 2f);
				GameObject closestObject = spawnInfo.m_spawner.GetClosestObject(m_proximityTag, area);
				num = ((!(closestObject != null)) ? 0f : Mathf.Min(num, GetProximityFitness(Vector3.Distance(closestObject.transform.position, spawnInfo.m_hitLocationWU))));
			}
			return num;
		}
	}
	[ExecuteInEditMode]
	public class Spawner : UnityEngine.MonoBehaviour
	{
