	public class TreeManager
	{
		private List<TreePrototype> m_terrainTrees = new List<TreePrototype>();

		private Quadtree<int> m_terrainTreeLocations = new Quadtree<int>(new Rect(0f, 0f, 10f, 10f));

		public void LoadTreesFromTerrain()
		{
			m_terrainTrees = null;
			m_terrainTreeLocations = null;
			float f = float.NaN;
			float num = float.NaN;
			float num2 = float.NaN;
			float num3 = float.NaN;
			float num4 = float.NaN;
			Terrain terrain = null;
			Terrain[] activeTerrains = Terrain.activeTerrains;
			foreach (Terrain terrain2 in activeTerrains)
			{
				if (float.IsNaN(f))
				{
					terrain = terrain2;
					f = terrain2.transform.position.y;
					num = terrain2.transform.position.x;
					num3 = terrain2.transform.position.z;
					num2 = num + terrain2.terrainData.size.x;
					num4 = num3 + terrain2.terrainData.size.z;
					continue;
				}
				if (terrain2.transform.position.x < num)
				{
					num = terrain2.transform.position.x;
				}
				if (terrain2.transform.position.z < num3)
				{
					num3 = terrain2.transform.position.z;
				}
				if (terrain2.transform.position.x + terrain2.terrainData.size.x > num2)
				{
					num2 = terrain2.transform.position.x + terrain2.terrainData.size.x;
				}
				if (terrain2.transform.position.z + terrain2.terrainData.size.z > num4)
				{
					num4 = terrain2.transform.position.z + terrain2.terrainData.size.z;
				}
			}
			if (!(terrain != null))
			{
				return;
			}
			Rect boundaries = new Rect(num, num3, num2 - num, num4 - num3);
			m_terrainTreeLocations = new Quadtree<int>(boundaries);
			m_terrainTrees = new List<TreePrototype>(terrain.terrainData.treePrototypes);
			Terrain[] activeTerrains2 = Terrain.activeTerrains;
			foreach (Terrain terrain3 in activeTerrains2)
			{
				float x = terrain3.transform.position.x;
				float z = terrain3.transform.position.z;
				float x2 = terrain3.terrainData.size.x;
				float z2 = terrain3.terrainData.size.z;
				TreeInstance[] treeInstances = terrain3.terrainData.treeInstances;
				for (int k = 0; k < treeInstances.Length; k++)
				{
					TreeInstance treeInstance = treeInstances[k];
					m_terrainTreeLocations.Insert(x + treeInstance.position.x * x2, z + treeInstance.position.z * z2, treeInstances[k].prototypeIndex);
				}
			}
		}

		public void AddTree(Vector3 position, int prototypeIdx)
		{
			if (m_terrainTreeLocations != null)
			{
				m_terrainTreeLocations.Insert(position.x, position.z, prototypeIdx);
			}
		}

		public int Count(Vector3 position, float range)
		{
			if (m_terrainTreeLocations == null)
			{
				return 0;
			}
			Rect range2 = new Rect(position.x - range, position.z - range, range * 2f, range * 2f);
			return m_terrainTreeLocations.Find(range2).Count();
		}

		public int Count()
		{
			if (m_terrainTreeLocations == null)
			{
				return 0;
			}
			return m_terrainTreeLocations.Count;
		}
	}
	public class RuntimeStamper : UnityEngine.MonoBehaviour
	{
		public bool m_showGUI = true;

		public bool m_showDebug = true;

		public string m_stampAddress = "Gaia/Stamps/RuggedHills 1810 4";

		public string m_currentProgress = string.Empty;

		private Rect m_currentPosition;

		private Stamper m_stamper;

		private void Awake()
		{
			m_currentPosition.height = 20f;
			m_currentPosition.width = 300f;
		}

		private void Start()
		{
			CreateStamper();
		}

		private void LateUpdate()
		{
			m_currentPosition.center = new Vector2((float)Screen.width / 2f, (float)Screen.height - 20f);
			if (m_stamper != null)
			{
				m_currentProgress = string.Format("Stamp progress: " + m_stamper.m_stampProgress);
			}
		}

		private void OnGUI()
		{
			if (m_showGUI && m_showGUI)
			{
				GUI.Label(m_currentPosition, m_currentProgress);
			}
		}

		private void CreateStamper()
		{
			string stampAddress = m_stampAddress;
			stampAddress = stampAddress.Replace("\\", "/");
			TextAsset textAsset = Resources.Load<TextAsset>(stampAddress);
			if (textAsset == null)
			{
				m_currentProgress = "Failed to load stamp at " + stampAddress;
				if (m_showDebug)
				{
					UnityEngine.Debug.Log(m_currentProgress);
				}
				return;
			}
			m_currentProgress = "Loaded stamp at " + textAsset.name;
			if (m_showDebug)
			{
				if (m_showDebug)
				{
					UnityEngine.Debug.Log(m_currentProgress);
				}
				GameObject gameObject = new GameObject("Runtime Stamper");
				m_stamper = gameObject.AddComponent<Stamper>();
				if (m_stamper.LoadRuntimeStamp(textAsset))
				{
					m_currentProgress = "Loaded Stamp";
					m_stamper.FlattenTerrain();
					m_stamper.FitToTerrain();
					m_stamper.m_height = 6f;
					m_stamper.m_distanceMask = AnimationCurve.Linear(0f, 1f, 1f, 0f);
					m_stamper.m_rotation = 0f;
					m_stamper.m_stickBaseToGround = true;
					m_stamper.m_updateTimeAllowed = 1f / 15f;
					m_stamper.UpdateStamp();
					m_stamper.Stamp();
				}
				else
				{
					m_currentProgress = "Failed to load stamp";
				}
				if (m_showDebug)
				{
					UnityEngine.Debug.Log(m_currentProgress);
				}
			}
		}
	}
