		public void Reset()
		{
			m_widthX = (m_depthZ = 0);
			m_widthInvX = (m_depthInvZ = 0f);
			m_heights = null;
			m_statMinVal = (m_statMaxVal = 0f);
			m_statSumVals = 0.0;
			m_metaData = new byte[0];
			m_heights = new float[0, 0];
			m_isDirty = false;
