	public class Quadtree<T>
	{
		private class QuadtreeNode
		{
			public Vector2 Position { get; private set; }

			public T Value { get; private set; }

			public QuadtreeNode(Vector2 position, T value)
			{
				Position = position;
				Value = value;
			}
		}

		private readonly int nodeCapacity = 32;

		private readonly List<QuadtreeNode> nodes;

		private Quadtree<T>[] children;

		private Rect boundaries;

		public int Count { get; private set; }

		public Quadtree(Rect boundaries, int nodeCapacity = 32)
		{
			this.boundaries = boundaries;
			this.nodeCapacity = nodeCapacity;
			nodes = new List<QuadtreeNode>(nodeCapacity);
		}

		public bool Insert(float x, float y, T value)
		{
			Vector2 position = new Vector2(x, y);
			QuadtreeNode node = new QuadtreeNode(position, value);
			return Insert(node);
		}

		public bool Insert(Vector2 position, T value)
		{
			QuadtreeNode node = new QuadtreeNode(position, value);
			return Insert(node);
		}

		private bool Insert(QuadtreeNode node)
		{
			if (!boundaries.Contains(node.Position))
			{
				return false;
			}
			if (children != null)
			{
				Quadtree<T> quadtree = ((node.Position.y < children[2].boundaries.yMin) ? ((!(node.Position.x < children[1].boundaries.xMin)) ? children[1] : children[0]) : ((!(node.Position.x < children[1].boundaries.xMin)) ? children[3] : children[2]));
				if (quadtree.Insert(node))
				{
					Count++;
					return true;
				}
			}
			if (nodes.Count < nodeCapacity)
			{
				nodes.Add(node);
				Count++;
				return true;
			}
			Subdivide();
			return Insert(node);
		}

		public IEnumerable<T> Find(Rect range)
		{
			if (Count == 0)
			{
				yield break;
			}
			bool allowInverse = false;
			if (!boundaries.Overlaps(range, allowInverse))
			{
				yield break;
			}
			if (children == null)
			{
				for (int index = 0; index < nodes.Count; index++)
				{
					QuadtreeNode node = nodes[index];
					if (range.Contains(node.Position))
					{
						yield return node.Value;
					}
				}
				yield break;
			}
			for (int i = 0; i < children.Length; i++)
			{
				Quadtree<T> child = children[i];
				foreach (T item in child.Find(range))
				{
					yield return item;
				}
			}
		}

		public bool Remove(float x, float z, T value)
		{
			return Remove(new Vector2(x, z), value);
		}

		public bool Remove(Vector2 position, T value)
		{
			if (Count == 0)
			{
				return false;
			}
			if (!boundaries.Contains(position))
			{
				return false;
			}
			if (children != null)
			{
				bool result = false;
				Quadtree<T> quadtree = ((position.y < children[2].boundaries.yMin) ? ((!(position.x < children[1].boundaries.xMin)) ? children[1] : children[0]) : ((!(position.x < children[1].boundaries.xMin)) ? children[3] : children[2]));
				if (quadtree.Remove(position, value))
				{
					result = true;
					Count--;
				}
				if (Count <= nodeCapacity)
				{
					Combine();
				}
				return result;
			}
			for (int i = 0; i < nodes.Count; i++)
			{
				QuadtreeNode quadtreeNode = nodes[i];
				if (quadtreeNode.Position.Equals(position))
				{
					nodes.RemoveAt(i);
					Count--;
					return true;
				}
			}
			return false;
		}

		private void Subdivide()
		{
			children = new Quadtree<T>[4];
			float num = boundaries.width * 0.5f;
			float num2 = boundaries.height * 0.5f;
			for (int i = 0; i < children.Length; i++)
			{
				Rect rect = new Rect(boundaries.xMin + num * (float)(i % 2), boundaries.yMin + num2 * (float)(i / 2), num, num2);
				children[i] = new Quadtree<T>(rect);
			}
			Count = 0;
			for (int j = 0; j < nodes.Count; j++)
			{
				QuadtreeNode node = nodes[j];
				Insert(node);
			}
			nodes.Clear();
		}

		private void Combine()
		{
			for (int i = 0; i < children.Length; i++)
			{
				Quadtree<T> quadtree = children[i];
				nodes.AddRange(quadtree.nodes);
			}
			children = null;
		}
	}
	public class ScaleTexture
	{
		public class ThreadData
		{
			public int start;

			public int end;

			public ThreadData(int s, int e)
			{
				start = s;
				end = e;
			}
		}

		private static Color[] texColors;

		private static Color[] newColors;

		private static int w;

		private static float ratioX;

		private static float ratioY;

		private static int w2;

		private static int finishCount;

		private static Mutex mutex;

		public static void Point(Texture2D tex, int newWidth, int newHeight)
		{
			ThreadedScale(tex, newWidth, newHeight, useBilinear: false);
		}

		public static void Bilinear(Texture2D tex, int newWidth, int newHeight)
		{
			ThreadedScale(tex, newWidth, newHeight, useBilinear: true);
		}

		private static void ThreadedScale(Texture2D tex, int newWidth, int newHeight, bool useBilinear)
		{
			texColors = tex.GetPixels();
			newColors = new Color[newWidth * newHeight];
			if (useBilinear)
			{
				ratioX = 1f / ((float)newWidth / (float)(tex.width - 1));
				ratioY = 1f / ((float)newHeight / (float)(tex.height - 1));
			}
			else
			{
				ratioX = (float)tex.width / (float)newWidth;
				ratioY = (float)tex.height / (float)newHeight;
			}
			w = tex.width;
			w2 = newWidth;
			int num = Mathf.Min(SystemInfo.processorCount, newHeight);
			int num2 = newHeight / num;
			finishCount = 0;
			if (mutex == null)
			{
				mutex = new Mutex(initiallyOwned: false);
			}
			if (num > 1)
			{
				int num3 = 0;
				ThreadData parameter;
				for (num3 = 0; num3 < num - 1; num3++)
				{
					parameter = new ThreadData(num2 * num3, num2 * (num3 + 1));
					ParameterizedThreadStart start = ((!useBilinear) ? new ParameterizedThreadStart(PointScale) : new ParameterizedThreadStart(BilinearScale));
					Thread thread = new Thread(start);
					thread.Start(parameter);
				}
				parameter = new ThreadData(num2 * num3, newHeight);
				if (useBilinear)
				{
					BilinearScale(parameter);
				}
				else
				{
					PointScale(parameter);
				}
				while (finishCount < num)
				{
					Thread.Sleep(1);
				}
			}
			else
			{
				ThreadData obj = new ThreadData(0, newHeight);
				if (useBilinear)
				{
					BilinearScale(obj);
				}
				else
				{
					PointScale(obj);
				}
			}
			tex.Resize(newWidth, newHeight);
			tex.SetPixels(newColors);
			tex.Apply();
		}

		public static void BilinearScale(object obj)
		{
			ThreadData threadData = (ThreadData)obj;
			for (int i = threadData.start; i < threadData.end; i++)
			{
				int num = (int)Mathf.Floor((float)i * ratioY);
				int num2 = num * w;
				int num3 = (num + 1) * w;
				int num4 = i * w2;
				for (int j = 0; j < w2; j++)
				{
					int num5 = (int)Mathf.Floor((float)j * ratioX);
					float value = (float)j * ratioX - (float)num5;
					ref Color reference = ref newColors[num4 + j];
					reference = ColorLerpUnclamped(ColorLerpUnclamped(texColors[num2 + num5], texColors[num2 + num5 + 1], value), ColorLerpUnclamped(texColors[num3 + num5], texColors[num3 + num5 + 1], value), (float)i * ratioY - (float)num);
				}
			}
			mutex.WaitOne();
			finishCount++;
			mutex.ReleaseMutex();
		}

		public static void PointScale(object obj)
		{
			ThreadData threadData = (ThreadData)obj;
			for (int i = threadData.start; i < threadData.end; i++)
			{
				int num = (int)(ratioY * (float)i) * w;
				int num2 = i * w2;
				for (int j = 0; j < w2; j++)
				{
					ref Color reference = ref newColors[num2 + j];
					reference = texColors[(int)((float)num + ratioX * (float)j)];
				}
			}
			mutex.WaitOne();
			finishCount++;
			mutex.ReleaseMutex();
		}

		private static Color ColorLerpUnclamped(Color c1, Color c2, float value)
		{
			return new Color(c1.r + (c2.r - c1.r) * value, c1.g + (c2.g - c1.g) * value, c1.b + (c2.b - c1.b) * value, c1.a + (c2.a - c1.a) * value);
		}
	}
