		public static System.Type GetType(string TypeName)
		{
			System.Type type = System.Type.GetType(TypeName);
			if (type != null)
			{
				return type;
			}
			if (TypeName.Contains("."))
			{
				string assemblyString = TypeName.Substring(0, TypeName.IndexOf('.'));
				try
				{
					Assembly assembly = Assembly.Load(assemblyString);
					if (assembly == null)
					{
						return null;
					}
					type = assembly.GetType(TypeName);
					if (type != null)
					{
						return type;
					}
				}
				catch (Exception)
				{
				}
			}
			Assembly callingAssembly = Assembly.GetCallingAssembly();
			if (callingAssembly != null)
			{
				type = callingAssembly.GetType(TypeName);
				if (type != null)
				{
					return type;
				}
			}
			Assembly[] assemblies = AppDomain.CurrentDomain.GetAssemblies();
			for (int i = 0; i < assemblies.GetLength(0); i++)
			{
				type = assemblies[i].GetType(TypeName);
				if (type != null)
				{
					return type;
				}
			}
			AssemblyName[] referencedAssemblies = callingAssembly.GetReferencedAssemblies();
			AssemblyName[] array = referencedAssemblies;
			foreach (AssemblyName assemblyRef in array)
			{
				Assembly assembly2 = Assembly.Load(assemblyRef);
				if (assembly2 != null)
				{
					type = assembly2.GetType(TypeName);
					if (type != null)
					{
						return type;
					}
				}
			}
			return null;
		}
	}
	public class WaterFlowMap
	{
		public float m_dropletVolume = 0.3f;

		public float m_dropletAbsorbtionRate = 0.05f;

		public int m_waterflowSmoothIterations = 1;

		private UnityHeightMap m_heightMap;

		private HeightMap m_waterFlowMap;

		public void CreateWaterFlowMap(Terrain terrain)
		{
			m_heightMap = new UnityHeightMap(terrain);
			int num = m_heightMap.Width();
			int num2 = m_heightMap.Depth();
			m_waterFlowMap = new HeightMap(num, num2);
			for (int i = 1; i < num - 1; i++)
			{
				for (int j = 1; j < num2 - 1; j++)
				{
					TraceWaterFlow(i, j, num, num2);
				}
			}
			m_waterFlowMap.Flip();
			m_waterFlowMap.Smooth(m_waterflowSmoothIterations);
		}

		private void TraceWaterFlow(int startX, int startZ, int width, int height)
		{
			float num = m_dropletVolume;
			int num2 = startX;
			int num3 = startZ;
			while (num > 0f)
			{
				m_waterFlowMap[num2, num3] += m_dropletAbsorbtionRate;
				num -= m_dropletAbsorbtionRate;
				float num5;
				float num4 = (num5 = m_heightMap[num2, num3]);
				int num6 = num2;
				int num7 = num3;
				for (int i = -1; i < 2; i++)
				{
					for (int j = -1; j < 2; j++)
					{
						int num8 = num2 + i;
						int num9 = num3 + j;
						if (num8 >= 0 && num8 < width && num9 >= 0 && num9 < height && m_heightMap[num8, num9] < num4)
						{
							num6 = num8;
							num7 = num9;
							num4 = m_heightMap[num8, num9];
						}
					}
				}
				if (num5 == num4)
				{
					m_heightMap[num2, num3] += m_dropletAbsorbtionRate;
					continue;
				}
				num2 = num6;
				num3 = num7;
			}
		}

		public void ExportWaterMapToPath(string path)
		{
			Utils.CompressToSingleChannelFileImage(m_waterFlowMap.Heights(), path, TextureFormat.RGBA32, exportPNG: true, exportJPG: false);
		}
	}
	public class XorshiftPlus
	{
		private const ulong m_A_Init = 181353uL;

		private const ulong m_B_Init = 7uL;

		public int m_seed;

		public ulong m_stateA;

		public ulong m_stateB;

		public XorshiftPlus(int seed = 1)
		{
			m_seed = seed;
			if (m_seed == 0)
			{
				m_seed = 1;
			}
			Reset();
		}

		public void Reset()
		{
			m_stateA = 181353uL * (ulong)(uint)m_seed;
			m_stateB = 7uL * (ulong)(uint)m_seed;
		}

		public void Reset(int seed)
		{
			m_seed = seed;
			if (m_seed == 0)
			{
				m_seed = 1;
			}
			Reset();
		}

		public void Reset(ulong stateA, ulong stateB)
		{
			UnityEngine.Debug.Log("Resetting RNG State " + stateA + " " + stateB);
			m_stateA = stateA;
			m_stateB = stateB;
		}

		public void GetState(out int seed, out ulong stateA, out ulong stateB)
		{
			seed = m_seed;
			stateA = m_stateA;
			stateB = m_stateB;
		}

		public float Next()
		{
			ulong stateA = m_stateA;
			ulong num = (m_stateA = m_stateB);
			stateA ^= stateA << 23;
			stateA ^= stateA >> 17;
			return (float)((m_stateB = stateA ^ (num ^ (num >> 26))) + num) / 1.8446744E+19f;
		}

		public int NextInt()
		{
			return (int)(Next() * 2.1474836E+09f);
		}

		public float Next(float min, float max)
		{
			return min + Next() * (max - min);
		}

		public int Next(int min, int max)
		{
			if (min == max)
			{
				return min;
			}
			return (int)Next(min, (float)max + 0.999f);
		}

		public Vector3 NextVector()
		{
			return new Vector3(Next(), Next(), Next());
		}

		public Vector3 NextVector(float min, float max)
		{
			return new Vector3(Next(min, max), Next(min, max), Next(min, max));
		}
	}
	public class CameraController : UnityEngine.MonoBehaviour
	{
		public GameObject target;

		public float targetHeight = 5f;

		public float distance = 12f;

		public float offsetFromWall = 0.1f;

		public float maxDistance = 20f;

		public float minDistance = 0.6f;

		public float xSpeed = 200f;

		public float ySpeed = 200f;

		public float yMinLimit = -80f;

		public float yMaxLimit = 80f;

		public float zoomRate = 40f;

		public float rotationDampening = 0.5f;

		public float zoomDampening = 5f;

		public LayerMask collisionLayers = -1;

		public bool lockToRearOfTarget;

		public bool allowMouseInputX = true;

		public bool allowMouseInputY = true;

		private float xDeg;

		private float yDeg;

		private float currentDistance;

		private float desiredDistance;

		private float correctedDistance;

		private bool rotateBehind;

		private bool mouseSideButton;

		private float pbuffer;

		private void Start()
		{
			Vector3 eulerAngles = base.transform.eulerAngles;
			xDeg = eulerAngles.x;
			yDeg = eulerAngles.y;
			currentDistance = distance;
			desiredDistance = distance;
			correctedDistance = distance;
			if (lockToRearOfTarget)
			{
				rotateBehind = true;
			}
			if (target == null)
			{
				target = GameObject.FindGameObjectWithTag("Player");
			}
		}

		private void LateUpdate()
		{
			if (target == null)
			{
				return;
			}
			if (pbuffer > 0f)
			{
				pbuffer -= UnityEngine.Time.deltaTime;
			}
			if (pbuffer < 0f)
			{
				pbuffer = 0f;
			}
			if (mouseSideButton && Input.GetAxis("Vertical") != 0f)
			{
				mouseSideButton = false;
			}
			if (GUIUtility.hotControl == 0)
			{
				if (Input.GetMouseButton(0) || Input.GetMouseButton(1))
				{
					if (allowMouseInputX)
					{
						xDeg += Input.GetAxis("Mouse X") * xSpeed * 0.02f;
					}
					else
					{
						RotateBehindTarget();
					}
					if (allowMouseInputY)
					{
						yDeg -= Input.GetAxis("Mouse Y") * ySpeed * 0.02f;
					}
					if (!lockToRearOfTarget)
					{
						rotateBehind = false;
					}
				}
				else if (Input.GetAxis("Vertical") != 0f || Input.GetAxis("Horizontal") != 0f || rotateBehind || mouseSideButton)
				{
					RotateBehindTarget();
				}
			}
			yDeg = ClampAngle(yDeg, yMinLimit, yMaxLimit);
			Quaternion quaternion = Quaternion.Euler(yDeg, xDeg, 0f);
			desiredDistance -= Input.GetAxis("Mouse ScrollWheel") * UnityEngine.Time.deltaTime * zoomRate * Mathf.Abs(desiredDistance);
			desiredDistance = Mathf.Clamp(desiredDistance, minDistance, maxDistance);
			correctedDistance = desiredDistance;
			Vector3 vector = new Vector3(0f, 0f - targetHeight, 0f);
			Vector3 end = target.transform.position - (quaternion * Vector3.forward * desiredDistance + vector);
			Vector3 vector2 = new Vector3(target.transform.position.x, target.transform.position.y + targetHeight, target.transform.position.z);
			bool flag = false;
			if (Physics.Linecast(vector2, end, out var hitInfo, collisionLayers))
			{
				correctedDistance = Vector3.Distance(vector2, hitInfo.point) - offsetFromWall;
				flag = true;
			}
			currentDistance = ((flag && !(correctedDistance > currentDistance)) ? correctedDistance : Mathf.Lerp(currentDistance, correctedDistance, UnityEngine.Time.deltaTime * zoomDampening));
			currentDistance = Mathf.Clamp(currentDistance, minDistance, maxDistance);
			end = target.transform.position - (quaternion * Vector3.forward * currentDistance + vector);
			base.transform.rotation = quaternion;
			base.transform.position = end;
		}

		private void RotateBehindTarget()
		{
			float y = target.transform.eulerAngles.y;
			float y2 = base.transform.eulerAngles.y;
			xDeg = Mathf.LerpAngle(y2, y, rotationDampening * UnityEngine.Time.deltaTime);
			if (y == y2)
			{
				if (!lockToRearOfTarget)
				{
					rotateBehind = false;
				}
			}
			else
			{
				rotateBehind = true;
			}
		}

		private float ClampAngle(float angle, float min, float max)
		{
			if (angle < -360f)
			{
				angle += 360f;
			}
			if (angle > 360f)
			{
				angle -= 360f;
			}
			return Mathf.Clamp(angle, min, max);
		}
	}
	public class FrameRateManager : UnityEngine.MonoBehaviour
	{
		public bool m_showFPS = true;

		public bool m_showGUI = true;

		public bool m_autoQualityManagement = true;

		public float m_autoCheckInterval = 10f;

		public int m_targetFrameRate = 60;

		public int m_fontSize = 25;

		private float m_autoCheckTimeLeft;

		private int m_currentQuality;

		private int m_maxQuality = 1;

		private string[] m_qualityNames;

		private float m_fpsUpdateInterval = 0.5f;

		private float m_fpsAccum;

		private int m_fpsFrames;

		private float m_fpsTimeLeft;

		private float m_fpsValue;

		private string m_fpsValueStr = string.Empty;

		private GUIStyle m_fpsStyle = new GUIStyle();

		private GUIStyle m_fpsShadowStyle = new GUIStyle();

		private Rect m_fpsLocation = new Rect(5f, 5f, 100f, 25f);

		private Rect m_fpsShadowLocation = new Rect(6f, 6f, 100f, 25f);

		private void Start()
		{
			UnityEngine.Application.targetFrameRate = m_targetFrameRate;
			m_maxQuality = QualitySettings.names.Length - 1;
			m_qualityNames = QualitySettings.names;
			m_currentQuality = QualitySettings.GetQualityLevel();
			m_autoCheckTimeLeft = m_autoCheckInterval;
			UnityEngine.Debug.Log("Current quality is " + m_qualityNames[m_currentQuality]);
			m_fpsStyle.fontSize = m_fontSize;
			m_fpsShadowStyle.fontSize = m_fontSize;
			m_fpsTimeLeft = m_fpsUpdateInterval;
			m_fpsLocation = new Rect(Screen.width - 250, 5f, 100f, 25f);
			m_fpsShadowLocation = new Rect(Screen.width - 250 + 1, 6f, 100f, 25f);
		}

		private void OnGUI()
		{
			if (!m_showFPS && !m_showGUI)
			{
				return;
			}
			if (m_showFPS)
			{
				GUI.Label(m_fpsShadowLocation, m_fpsValueStr, m_fpsShadowStyle);
				GUI.Label(m_fpsLocation, m_fpsValueStr, m_fpsStyle);
			}
			if (!m_showGUI)
			{
				return;
			}
			GUILayout.BeginVertical();
			for (int i = 0; i <= m_maxQuality; i++)
			{
				if (GUILayout.Button(m_qualityNames[i]))
				{
					QualitySettings.SetQualityLevel(i, applyExpensiveChanges: true);
					m_currentQuality = i;
					UpdateQuality();
					m_autoQualityManagement = false;
				}
			}
			GUILayout.EndVertical();
		}

		private void Update()
		{
			m_fpsTimeLeft -= UnityEngine.Time.deltaTime;
			m_fpsAccum += UnityEngine.Time.timeScale / UnityEngine.Time.deltaTime;
			m_fpsFrames++;
			if (m_fpsTimeLeft <= 0f)
			{
				m_fpsValue = m_fpsAccum / (float)m_fpsFrames;
				if (m_fpsValue < 30f)
				{
					m_fpsStyle.normal.textColor = Color.yellow;
				}
				else if (m_fpsValue < 10f)
				{
					m_fpsStyle.normal.textColor = Color.red;
				}
				else
				{
					m_fpsStyle.normal.textColor = Color.green;
				}
				m_fpsValueStr = $"{m_fpsValue:f0} {m_qualityNames[m_currentQuality].Substring(0, 3)}";
				m_fpsTimeLeft = m_fpsUpdateInterval;
				m_fpsAccum = 0f;
				m_fpsFrames = 0;
			}
			if (!m_autoQualityManagement)
			{
				return;
			}
			m_autoCheckTimeLeft -= UnityEngine.Time.deltaTime;
			if (m_autoCheckTimeLeft < 0f)
			{
				if (m_fpsValue + 10f >= (float)m_targetFrameRate)
				{
					IncreaseQuality();
				}
				else if (m_fpsValue - 10f <= (float)m_targetFrameRate)
				{
					DecreaseQuality();
				}
				m_autoCheckTimeLeft = m_autoCheckInterval;
			}
		}

		private void UpdateQuality()
		{
			if (QualitySettings.GetQualityLevel() != m_currentQuality)
			{
				UnityEngine.Debug.Log("Changing quality to " + m_qualityNames[m_currentQuality]);
				switch (m_currentQuality)
				{
				case 0:
					Terrain.activeTerrain.treeDistance = 250f;
					Terrain.activeTerrain.treeBillboardDistance = 30f;
					Terrain.activeTerrain.treeCrossFadeLength = 5f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 5;
					Terrain.activeTerrain.detailObjectDistance = 40f;
					Terrain.activeTerrain.detailObjectDensity = 0.1f;
					Terrain.activeTerrain.heightmapPixelError = 20f;
					Terrain.activeTerrain.heightmapMaximumLOD = 1;
					Terrain.activeTerrain.basemapDistance = 100f;
					break;
				case 1:
					Terrain.activeTerrain.treeDistance = 500f;
					Terrain.activeTerrain.treeBillboardDistance = 50f;
					Terrain.activeTerrain.treeCrossFadeLength = 10f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 10;
					Terrain.activeTerrain.detailObjectDistance = 50f;
					Terrain.activeTerrain.detailObjectDensity = 0.25f;
					Terrain.activeTerrain.heightmapPixelError = 10f;
					Terrain.activeTerrain.heightmapMaximumLOD = 1;
					Terrain.activeTerrain.basemapDistance = 250f;
					break;
				case 2:
					Terrain.activeTerrain.treeDistance = 650f;
					Terrain.activeTerrain.treeBillboardDistance = 75f;
					Terrain.activeTerrain.treeCrossFadeLength = 25f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 20;
					Terrain.activeTerrain.detailObjectDistance = 60f;
					Terrain.activeTerrain.detailObjectDensity = 0.4f;
					Terrain.activeTerrain.heightmapPixelError = 8f;
					Terrain.activeTerrain.heightmapMaximumLOD = 0;
					Terrain.activeTerrain.basemapDistance = 500f;
					break;
				case 3:
					Terrain.activeTerrain.treeDistance = 800f;
					Terrain.activeTerrain.treeBillboardDistance = 100f;
					Terrain.activeTerrain.treeCrossFadeLength = 40f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 30;
					Terrain.activeTerrain.detailObjectDistance = 80f;
					Terrain.activeTerrain.detailObjectDensity = 0.7f;
					Terrain.activeTerrain.heightmapPixelError = 5f;
					Terrain.activeTerrain.heightmapMaximumLOD = 0;
					Terrain.activeTerrain.basemapDistance = 800f;
					break;
				case 4:
					Terrain.activeTerrain.treeDistance = 1000f;
					Terrain.activeTerrain.treeBillboardDistance = 150f;
					Terrain.activeTerrain.treeCrossFadeLength = 50f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 50;
					Terrain.activeTerrain.detailObjectDistance = 120f;
					Terrain.activeTerrain.detailObjectDensity = 1f;
					Terrain.activeTerrain.heightmapPixelError = 5f;
					Terrain.activeTerrain.heightmapMaximumLOD = 0;
					Terrain.activeTerrain.basemapDistance = 1000f;
					break;
				case 5:
					Terrain.activeTerrain.treeDistance = 2000f;
					Terrain.activeTerrain.treeBillboardDistance = 200f;
					Terrain.activeTerrain.treeCrossFadeLength = 50f;
					Terrain.activeTerrain.treeMaximumFullLODCount = 100;
					Terrain.activeTerrain.detailObjectDistance = 150f;
					Terrain.activeTerrain.detailObjectDensity = 1f;
					Terrain.activeTerrain.heightmapPixelError = 5f;
					Terrain.activeTerrain.heightmapMaximumLOD = 0;
					Terrain.activeTerrain.basemapDistance = 1000f;
					break;
				}
			}
		}

		private bool IncreaseQuality()
		{
			if (m_currentQuality < m_maxQuality)
			{
				m_currentQuality++;
				UpdateQuality();
			}
			return true;
		}

		private bool DecreaseQuality()
		{
			if (m_currentQuality > 0)
			{
				m_currentQuality--;
				UpdateQuality();
			}
			return true;
		}
	}
	public class FreeCamera : UnityEngine.MonoBehaviour
	{
		public bool enableInputCapture = true;

		public bool lockAndHideCursor;

		public bool holdRightMouseCapture = true;

		public float lookSpeed = 5f;

		public float moveSpeed = 5f;

		public float sprintSpeed = 50f;

		private bool m_inputCaptured;

		private float m_yaw;

		private float m_pitch;

		private void Awake()
		{
			base.enabled = enableInputCapture;
		}

		private void OnEnable()
		{
			if (enableInputCapture && !holdRightMouseCapture)
			{
				CaptureInput();
			}
		}

		private void OnDisable()
		{
			ReleaseInput();
		}

		private void OnValidate()
		{
			if (UnityEngine.Application.isPlaying)
			{
				base.enabled = enableInputCapture;
			}
		}

		private void CaptureInput()
		{
			if (lockAndHideCursor)
			{
				Cursor.lockState = CursorLockMode.Locked;
				Cursor.visible = false;
			}
			m_inputCaptured = true;
			m_yaw = base.transform.eulerAngles.y;
			m_pitch = base.transform.eulerAngles.x;
		}

		private void ReleaseInput()
		{
			if (lockAndHideCursor)
			{
				Cursor.lockState = CursorLockMode.None;
				Cursor.visible = true;
			}
			m_inputCaptured = false;
		}

		private void OnApplicationFocus(bool focus)
		{
			if (m_inputCaptured && !focus)
			{
				ReleaseInput();
			}
		}

		private void Update()
		{
			if (!m_inputCaptured)
			{
				if (!holdRightMouseCapture && Input.GetMouseButtonDown(0))
				{
					CaptureInput();
				}
				else if (holdRightMouseCapture && Input.GetMouseButtonDown(1))
				{
					CaptureInput();
				}
			}
			if (!m_inputCaptured)
			{
				return;
			}
			if (m_inputCaptured)
			{
				if (!holdRightMouseCapture && Input.GetKeyDown(KeyCode.Escape))
				{
					ReleaseInput();
				}
				else if (holdRightMouseCapture && Input.GetMouseButtonUp(1))
				{
					ReleaseInput();
				}
			}
			float axis = Input.GetAxis("Mouse X");
			float axis2 = Input.GetAxis("Mouse Y");
			m_yaw = (m_yaw + lookSpeed * axis) % 360f;
			m_pitch = (m_pitch - lookSpeed * axis2) % 360f;
			base.transform.rotation = Quaternion.AngleAxis(m_yaw, Vector3.up) * Quaternion.AngleAxis(m_pitch, Vector3.right);
			float num = UnityEngine.Time.deltaTime * ((!Input.GetKey(KeyCode.LeftShift)) ? moveSpeed : sprintSpeed);
			float num2 = num * Input.GetAxis("Vertical");
			float num3 = num * Input.GetAxis("Horizontal");
			float num4 = num * (((!Input.GetKey(KeyCode.E)) ? 0f : 1f) - ((!Input.GetKey(KeyCode.Q)) ? 0f : 1f));
			base.transform.position += base.transform.forward * num2 + base.transform.right * num3 + Vector3.up * num4;
		}
	}
	public class Growth : UnityEngine.MonoBehaviour
	{
		[Range(0.1f, 2f)]
		[Tooltip("The start size in the game.")]
		public float m_startScale = 0.15f;

		[Range(0.1f, 2f)]
		[Tooltip("The end size in the game.")]
		public float m_endScale = 1f;

		[Range(0f, 2f)]
		[Tooltip("Scale variance. Final scale is equal to end scale plus a a random value between 0 and this.")]
		public float m_scaleVariance = 0.25f;

		[Range(0.5f, 60f)]
		[Tooltip("The time it takes to grow in seconds.")]
		public float m_growthTime = 5f;

		private float m_actualEndScale;

		private void Start()
		{
			Initialise();
		}

		public virtual void Initialise()
		{
			m_actualEndScale = m_endScale + UnityEngine.Random.Range(0f, m_scaleVariance);
			StartCoroutine(Grow());
		}

		private IEnumerator Grow()
		{
			float startTime = UnityEngine.Time.realtimeSinceStartup;
			float currentTime = startTime;
			float deltaScale = m_actualEndScale - m_startScale;
			float finishTime = startTime + m_growthTime;
			while (currentTime < finishTime)
			{
				float scale = 1f - (finishTime - currentTime) / m_growthTime;
				scale = m_startScale + scale * deltaScale;
				base.gameObject.transform.localScale = Vector3.one * scale;
				yield return null;
				currentTime = UnityEngine.Time.realtimeSinceStartup;
			}
		}

		public virtual void Die()
		{
			UnityEngine.Object.Destroy(base.gameObject, 5f);
		}
	}
	[GaiaScriptOrder(500)]
	public class ScreenShotter : UnityEngine.MonoBehaviour
	{
		public KeyCode m_screenShotKey = KeyCode.F12;

		public GaiaConstants.StorageFormat m_imageFormat = GaiaConstants.StorageFormat.JPG;

		public string m_targetDirectory = "Screenshots";

		public int m_targetWidth = 1900;

		public int m_targetHeight = 1200;

		public bool m_useScreenSize = true;

		public Camera m_mainCamera;

		private bool m_takeShot;

		private bool m_refreshAssetDB;

		public Texture2D m_watermark;

		private void OnEnable()
		{
			if (m_mainCamera == null)
			{
				m_mainCamera = Camera.main;
			}
			string path = Path.Combine(UnityEngine.Application.dataPath, m_targetDirectory);
			if (!Directory.Exists(path))
			{
				Directory.CreateDirectory(path);
			}
		}

		private void OnDisable()
		{
			if (m_refreshAssetDB)
			{
				m_refreshAssetDB = false;
			}
		}

		private string ScreenShotName(int width, int height)
		{
			string text = Path.Combine(UnityEngine.Application.dataPath, m_targetDirectory);
			text = text.Replace('\\', '/');
			if (text[text.Length - 1] == '/')
			{
				text = text.Substring(0, text.Length - 1);
			}
			if (m_imageFormat == GaiaConstants.StorageFormat.JPG)
			{
				return string.Format("{0}/Grab {1} w{2}h{3} x{4}y{5}z{6}r{7}.jpg", text, DateTime.Now.ToString("yyyyMMddHHmmss"), width, height, (int)m_mainCamera.transform.position.x, (int)m_mainCamera.transform.position.y, (int)m_mainCamera.transform.position.z, (int)m_mainCamera.transform.rotation.eulerAngles.y);
			}
			return string.Format("{0}/Grab {1} w{2}h{3} x{4}y{5}z{6}r{7}.png", text, DateTime.Now.ToString("yyyyMMdd HHmmss"), width, height, (int)m_mainCamera.transform.position.x, (int)m_mainCamera.transform.position.y, (int)m_mainCamera.transform.position.z, (int)m_mainCamera.transform.rotation.eulerAngles.y);
		}

		public void TakeHiResShot()
		{
			m_takeShot = true;
		}

		private void LateUpdate()
		{
			if (Input.GetKeyDown(m_screenShotKey) || m_takeShot)
			{
				if (m_useScreenSize)
				{
					m_targetWidth = Screen.width;
					m_targetHeight = Screen.height;
				}
				m_refreshAssetDB = true;
				RenderTexture renderTexture = new RenderTexture(m_targetWidth, m_targetHeight, 24);
				m_mainCamera.targetTexture = renderTexture;
				Texture2D texture2D = new Texture2D(m_targetWidth, m_targetHeight, TextureFormat.RGB24, mipmap: false);
				m_mainCamera.Render();
				RenderTexture.active = renderTexture;
				texture2D.ReadPixels(new Rect(0f, 0f, m_targetWidth, m_targetHeight), 0, 0);
				m_mainCamera.targetTexture = null;
				RenderTexture.active = null;
				UnityEngine.Object.Destroy(renderTexture);
				if (m_watermark != null)
				{
					Utils.MakeTextureReadable(m_watermark);
					texture2D = AddWatermark(texture2D, m_watermark);
				}
				byte[] bytes = texture2D.EncodeToJPG();
				string text = ScreenShotName(m_targetWidth, m_targetHeight);
				Utils.WriteAllBytes(text, bytes);
				m_takeShot = false;
				UnityEngine.Debug.Log($"Took screenshot to: {text}");
			}
		}

		public Texture2D AddWatermark(Texture2D background, Texture2D watermark)
		{
			int num = background.width - watermark.width - 10;
			int num2 = num + watermark.width;
			int num3 = 8;
			int num4 = num3 + watermark.height;
			for (int i = num; i < num2; i++)
			{
				for (int j = num3; j < num4; j++)
				{
					Color pixel = background.GetPixel(i, j);
					Color pixel2 = watermark.GetPixel(i - num, j - num3);
					Color color = Color.Lerp(pixel, pixel2, pixel2.a / 1f);
					background.SetPixel(i, j, color);
				}
			}
			background.Apply();
			return background;
		}
	}
